INSERT INTO books VALUES (1, 'GEN', 'Gênesis', 'AT', 50);
INSERT INTO chapters VALUES (1, 1, 1, 31);
INSERT INTO verses VALUES (1, 1, 1, 1, 'No-princípio criou Elohim a os-céus e-a a-terra');
INSERT INTO verses VALUES (2, 1, 1, 2, 'E-a-terra era sem-forma e-vazia e-escuridão sobre abismo e-Espírito-de e-espirito pairava pairava as-águas face-de as-águas');
INSERT INTO verses VALUES (3, 1, 1, 3, 'E-disse Elohim haja luz e-foi luz');
INSERT INTO verses VALUES (4, 1, 1, 4, 'E-viu Elohim a a-luz E-separou bom entre a-luz e-entre a-luz e-entre a-escuridão');
INSERT INTO verses VALUES (5, 1, 1, 5, 'E-chamou Elohim para-a-luz à-luz dia chamou chamou noite tarde e-foi dia um um');
INSERT INTO verses VALUES (6, 1, 1, 6, 'E-disse Elohim haja expansão no-meio-de as-águas e-seja separando entre águas das-águas');
INSERT INTO verses VALUES (7, 1, 1, 7, 'E-fez Elohim a E-separou entre entre as-águas debaixo-de à-expansão e-entre e-entre as-águas de-cima-de à-expansão para-a-expansão e-foi assim');
INSERT INTO verses VALUES (8, 1, 1, 8, 'E-chamou Elohim à-expansão céus e-foi tarde dia manhã dia segundo');
INSERT INTO verses VALUES (9, 1, 1, 9, 'E-disse Elohim ajuntem-se as-águas debaixo-de os-céus a um e-apareça e-apareça a-seca e-foi assim');
INSERT INTO verses VALUES (10, 1, 1, 10, 'E-chamou Elohim para-a-seca terra terra e-ao-ajuntamento-de chamou chamou mares E-viu porque- bom');
INSERT INTO verses VALUES (11, 1, 1, 11, 'E-disse Elohim brote a-terra verdura erva semeando semente árvore fruto fez fruto conforme-sua-espécie que semente-sua em-ele sobre a-terra e-foi assim');
INSERT INTO verses VALUES (12, 1, 1, 12, 'E-produziu a-terra verdura erva semeando semente conforme-sua-espécie e-árvore fazendo fruto que conforme-sua-espécie E-viu segundo-especie-dele E-viu Elohim porque bom');
INSERT INTO verses VALUES (13, 1, 1, 13, 'e-foi tarde dia manhã dia terceiro');
INSERT INTO verses VALUES (14, 1, 1, 14, 'E-disse Elohim haja luzeiros na-expansão-de os-céus para-separar entre o-dia e-entre a-noite e-sejam para-sinais e-para-estações e-para-dias e-anos');
INSERT INTO verses VALUES (15, 1, 1, 15, 'e-sejam como-luzeiros na-expansão-de os-céus para-iluminar sobre a-terra e-foi assim');
INSERT INTO verses VALUES (16, 1, 1, 16, 'E-fez Elohim a os-luzeiros os-grandes os-grandes o-grande o-luminoso o-dia para-domínio o-pequeno e-a o-luminoso o-pequeno as-estrelas a-noite e-a as-estrelas');
INSERT INTO verses VALUES (17, 1, 1, 17, 'E-colocou eles Elohim na-expansão-de os-céus para-iluminar sobre a-terra');
INSERT INTO verses VALUES (18, 1, 1, 18, 'e-para-dominar no-dia e-na-noite e-para-separar entre a-luz e-entre a-escuridão E-viu Elohim porque bom');
INSERT INTO verses VALUES (19, 1, 1, 19, 'e-foi tarde dia quarto dia quarto');
INSERT INTO verses VALUES (20, 1, 1, 20, 'E-disse Elohim enxameiem as-águas enxame alma vivente e-ave voe sobre a-terra expansão face-de expansão os-céus');
INSERT INTO verses VALUES (21, 1, 1, 21, 'E-criou Elohim a os-grandes os-grandes e-a todo alma a-vida a-rastejante que enxamearam conforme-sua-espécie segundo-espécies-suas e-a asa conforme-sua-espécie E-viu segundo-especie-dele E-viu Elohim porque bom');
INSERT INTO verses VALUES (22, 1, 1, 22, 'E-abençoou eles Elohim dizendo frutificai e-multiplicai-vos e-enchei a as-águas nos-mares multiplique-se multiplique na-terra');
INSERT INTO verses VALUES (23, 1, 1, 23, 'e-foi tarde dia manhã dia quinto');
INSERT INTO verses VALUES (24, 1, 1, 24, 'E-disse Elohim produza a-terra alma vivente conforme-sua-espécie animal-doméstico e-réptil e-vida-sua conforme-sua-espécie segundo-espécie-sua e-foi assim');
INSERT INTO verses VALUES (25, 1, 1, 25, 'E-fez Elohim a a-terra conforme-sua-espécie segundo-espécie-sua conforme-sua-espécie o-gado segundo-espécie-sua a-terra conforme-sua-espécie E-viu o-solo segundo-espécie-sua E-viu Elohim porque bom');
INSERT INTO verses VALUES (26, 1, 1, 26, 'E-disse Elohim façamos homem à-nossa-imagem conforme-nossa-semelhança e-dominem em-peixe o-mar e-sobre-as-aves-de os-céus e-sobre-os-animais e-em-todo a-terra e-em-todo o-réptil o-rastejante sobre a-terra');
INSERT INTO verses VALUES (27, 1, 1, 27, 'E-criou Elohim a o-homem à-sua-imagem à-imagem-de Elohim criou ele macho e-fêmea criou eles');
INSERT INTO verses VALUES (28, 1, 1, 28, 'E-abençoou eles Elohim E-disse a-eles Elohim frutificai e-multiplicai-vos e-enchei a a-terra e-dominai sobre-os-peixes-de o-mar e-sobre-as-aves-de e-em-ave os-céus e-em-todo vida que-se-move sobre a-terra');
INSERT INTO verses VALUES (29, 1, 1, 29, 'E-disse Elohim eis dei a-vós a todo semeando semente semente que sobre face-de todo a-terra semeando todo a-vós será para-alimento fruto-de árvore semeando semente para-vós será para-comida');
INSERT INTO verses VALUES (30, 1, 1, 30, 'e-para-todo a-terra a-terra e-para-todo- ave os-céus e-para-todo rastejante sobre a-terra vivente em-ele alma para-alimento את- todo verdura-de erva para-alimento e-foi- assim');
INSERT INTO verses VALUES (31, 1, 1, 31, 'E-viu Elohim את- todo que muito e-eis- bom dia e-foi- tarde e-foi- manhã dia o-sexto');
INSERT INTO chapters VALUES (2, 1, 2, 25);
INSERT INTO verses VALUES (32, 1, 2, 1, 'E-foram-terminados os-céus E-a-terra e-todo exércitos-deles');
INSERT INTO verses VALUES (33, 1, 2, 2, 'E-terminou Elohim no-dia o-sétimo sua-obra que fez e-cessou no-dia o-sétimo de-todo obra-dele que fez');
INSERT INTO verses VALUES (34, 1, 2, 3, 'E-abençoou Elohim את- dia o-sétimo ele que nele em-ele cessou de-todo obra-dele que criou Elohim para-fazer');
INSERT INTO verses VALUES (35, 1, 2, 4, 'Estas gerações-de os-céus E-a-terra quando-foram-criados em-dia-de fazer yhwh Elohim terra e-céus');
INSERT INTO verses VALUES (36, 1, 2, 5, 'e-tudo arbusto-de o-campo antes ainda-não será na-terra erva-de o-campo ainda-não brotou que não fez-chover yhwh Elohim sobre a-terra não-havia para-lavrar para-trabalhar את- a-terra');
INSERT INTO verses VALUES (37, 1, 2, 6, 'e-vapor subia de a-terra e-regou את- todo face-de- a-terra');
INSERT INTO verses VALUES (38, 1, 2, 7, 'E-formou yhwh Elohim את- pó pó e-soprou em-suas-narinas e-soprou vida e-houve o-homem E-foi vivente para-alma vivente');
INSERT INTO verses VALUES (39, 1, 2, 8, 'E-plantou yhwh Elohim jardim- ao-oriente e-colocou nome את- o-homem formou formou');
INSERT INTO verses VALUES (40, 1, 2, 9, 'E-fez-brotar yhwh Elohim de a-terra agradável à-vista desejável para-alimento e-bom a-vida no-meio-de o-jardim em-meio-de o-conhecimento bom o-conhecimento bom e-mal');
INSERT INTO verses VALUES (41, 1, 2, 10, 'saindo sai de-Éden את- o-jardim e-de-ali divide-se e-foi para-quatro cabeças');
INSERT INTO verses VALUES (42, 1, 2, 11, 'nome o-primeiro Pishon ele o-que-rodeia את todo Havilá a-Havilá o-ouro nome o-ouro');
INSERT INTO verses VALUES (43, 1, 2, 12, 'e-ouro-de a-terra aquela bom nome o-bdélio e-pedra-de o-ônix');
INSERT INTO verses VALUES (44, 1, 2, 13, 'e-nome-de- o-rio Giom ele o-que-rodeia o-que-circunda את todo terra Cush');
INSERT INTO verses VALUES (45, 1, 2, 14, 'e-nome-de o-rio o-terceiro Tigre ele o-que-vai ao-oriente-de Assur e-o-rio o-quarto ele Eufrates');
INSERT INTO verses VALUES (46, 1, 2, 15, 'E-tomou yhwh Elohim את- e-o-colocou e-colocou-o para-cultivá-la Éden para-trabalhar-a e-para-guardar-a');
INSERT INTO verses VALUES (47, 1, 2, 16, 'E-ordenou yhwh Elohim sobre dizendo de-toda de-todo comer comerás comer comerás');
INSERT INTO verses VALUES (48, 1, 2, 17, 'e-da-árvore-de o-conhecimento bom e-mal não comerás nós que em-dia-de comeres-tu nós morrendo morrerás');
INSERT INTO verses VALUES (49, 1, 2, 18, 'E-disse yhwh Elohim não estar o-homem sozinho sozinho-dele auxiliar correspondente-a-ele auxiliar correspondente-a-ele');
INSERT INTO verses VALUES (50, 1, 2, 19, 'E-formou yhwh Elohim de a-terra todo animal-de o-campo e-את e-trouxe ave para-ver E-veio e-tudo o-homem para-ver que- chamará- vivente ele que chamará para-ele o-homem alma vida ele nome-dele');
INSERT INTO verses VALUES (51, 1, 2, 20, 'E-chamou o-homem nomes-de para-todo o-gado e-para-ave-de os-céus animal-de vivente-de E-ao-homem e-para-o-homem auxiliar correspondente-a-ele ajudadora correspondente-a-ele');
INSERT INTO verses VALUES (52, 1, 2, 21, 'E-fez-cair yhwh Elohim sono-profundo sono-profundo o-homem e-dormiu E-tomou uma de-suas-costelas e-fechou carne em-seu-lugar');
INSERT INTO verses VALUES (53, 1, 2, 22, 'E-edificou yhwh Elohim objeto-direto a-costela que tomou de e-trouxe-a para-mulher e-trouxe-ela a o-homem');
INSERT INTO verses VALUES (54, 1, 2, 23, 'E-disse o-homem esta desta-vez osso de-meus-ossos e-carne de-carne-minha a-esta será-chamada mulher que de-homem foi-tomada esta');
INSERT INTO verses VALUES (55, 1, 2, 24, 'sobre assim deixará homem e-unir-se-á pai-dele e-sejam mãe-dele um em-mulher-dele e-serão para-carne um');
INSERT INTO verses VALUES (56, 1, 2, 25, 'e-eram dois-deles nus o-homem e-mulher-dele e-não envergonhavam-se');
INSERT INTO chapters VALUES (3, 1, 3, 24);
INSERT INTO verses VALUES (57, 1, 3, 1, 'e-a-serpente ser astuto de-toda animal-de o-campo que fez yhwh Elohim E-disse a certamente mesmo porque- não comereis de-toda árvore o-jardim árvore o-jardim');
INSERT INTO verses VALUES (58, 1, 3, 2, 'E-disse a-mulher a do-fruto-de de-fruto-de comeremos o-jardim comemos');
INSERT INTO verses VALUES (59, 1, 3, 3, 'e-do-fruto-de a-árvore que em-meio-de disse disse não comereis nós dele tocareis tocareis nele para-que-não morrereis');
INSERT INTO verses VALUES (60, 1, 3, 4, 'E-disse a-serpente a a-mulher morrais morrer morrereis');
INSERT INTO verses VALUES (61, 1, 3, 5, 'que sabe Elohim que em-dia-de comerdes nós e-se-abrirão vossos-olhos e-sereis como-Elohim conhecendo bom e-mal');
INSERT INTO verses VALUES (62, 1, 3, 6, 'E-viu a-mulher que bom a-árvore para-alimento e-que desejo aos-olhos e-desejável a-árvore a-árvore e-tomou de-seu-fruto e-comeste e-deu e-deu com-ela e-comeu com-ela e-comeu');
INSERT INTO verses VALUES (63, 1, 3, 7, 'E-abriram-se os-olhos-de dois-deles e-souberam que nus eles e-coseram folhas-de figueira e-fizeram a-eles cintas');
INSERT INTO verses VALUES (64, 1, 3, 8, 'e-ouviram objeto-direto yhwh yhwh passeando andando na-brisa-de o-dia e-escondeu-se o-homem o-homem de-diante-de yhwh yhwh no-meio-de árvore o-jardim o-jardim');
INSERT INTO verses VALUES (65, 1, 3, 9, 'E-chamou yhwh Elohim a E-disse a-ele onde-estás onde');
INSERT INTO verses VALUES (66, 1, 3, 10, 'E-disse objeto-direto voz-tua ouvi e-temi e-temi eu e-me-escondi eu e-escondi-me');
INSERT INTO verses VALUES (67, 1, 3, 11, 'E-disse quem declarou a-ti que nu tu acaso-de a-árvore ordenei-te para-não para-não comeste dele comeste');
INSERT INTO verses VALUES (68, 1, 3, 12, 'E-disse o-homem a-mulher que deste comigo ela deu para-mim e-comi a-árvore e-comi');
INSERT INTO verses VALUES (69, 1, 3, 13, 'E-disse yhwh Elohim para-a-mulher que isto E-disse e-disse a-mulher a-serpente e-comi e-comi');
INSERT INTO verses VALUES (70, 1, 3, 14, 'E-disse yhwh Elohim a a-serpente que fizeste isto maldito tu de-todo a-animal animal-de vivente-de o-campo andarás ventre-teu comerás e-pó tua-vida todo dias-de vidas-tuas');
INSERT INTO verses VALUES (71, 1, 3, 15, 'E-inimizade colocarei entre-ti entre-ti e-entre e-entre e-entre tua-semente e-entre sua-semente ele cabeça e-tu ferirás-o calcanhar');
INSERT INTO verses VALUES (72, 1, 3, 16, 'a disse multiplicando multiplicarei tua-dor e-tua-gravidez com-dor darás-à-luz filhos filhos e-a homem-teu desejo-teu e-ele dominará- em-ti');
INSERT INTO verses VALUES (73, 1, 3, 17, 'E-ao-homem disse porque à-voz-de para-voz e-comeste e-comeste de ordenei-te dizendo não comerás nós maldita a-terra por-tua-causa com-fadiga a-comerás em-fadiga dias-de tua-vida dias-de vidas-tuas');
INSERT INTO verses VALUES (74, 1, 3, 18, 'E-espinhos e-cardos fará-brotar para-ti e-comerás אֶת־ erva-de o-campo');
INSERT INTO verses VALUES (75, 1, 3, 19, 'no-suor-de teu-rosto comerás pão até retorno-teu a que porque foste-tomado tomado-foste tu pó tu e-a pó retornarás');
INSERT INTO verses VALUES (76, 1, 3, 20, 'E-chamou o-homem nome mulher-sua Eva que ela era mãe todo viveu');
INSERT INTO verses VALUES (77, 1, 3, 21, 'E-fez yhwh Elohim para-homem e-para-mulher-sua túnicas-de pele e-vestiu-os');
INSERT INTO verses VALUES (78, 1, 3, 22, 'E-disse yhwh yhwh eis eis o-homem ser como-um-de nós para-conhecer bom e-agora e-agora enviará mão-sua sua-mão e-tome também a-vidas a-vida e-coma e-viva');
INSERT INTO verses VALUES (79, 1, 3, 23, 'e-enviou-o yhwh Elohim de-jardim- para-lavrar para-cultivar אֶת־ foi-tomado que tomou de-lá');
INSERT INTO verses VALUES (80, 1, 3, 24, 'e-expulsou אֶת־ o-homem ao-oriente de-oriente para-jardim- éden chama-de a-espada que-se-revolvia chama-de a-espada árvore a-vida אֶת־ caminho árvore-de a-vidas');
INSERT INTO chapters VALUES (4, 1, 4, 26);
INSERT INTO verses VALUES (81, 1, 4, 1, 'e-o-homem saber אֶת־ חַוָּ֣ה mulher-sua e-concebeu e-deu-à-luz E-disse קַ֔יִן e-disse adquiri homem אֶת־ yhwh');
INSERT INTO verses VALUES (82, 1, 4, 2, 'e-acrescentou para-dar-à-luz אֶת־ irmão-seu אֶת־ הָ֑בֶל e-foi- הֶ֙בֶל֙ ser rebanho terra foi servo solo');
INSERT INTO verses VALUES (83, 1, 4, 3, 'e-foi desde-fim-de dias e-trouxe קַ֜יִן do-fruto-de o-solo oferta para-יהוה');
INSERT INTO verses VALUES (84, 1, 4, 4, 'e-הֶ֨בֶל trouxe também ele de-primogênitos-de rebanho-seu e-de-gorduras-delas yhwh yhwh a הֶ֖בֶל e-a oferta-sua');
INSERT INTO verses VALUES (85, 1, 4, 5, 'e-a קַ֥יִן não oferta-sua não olhou muito para-קַ֙יִן֙ muito e-caíram faces-suas');
INSERT INTO verses VALUES (86, 1, 4, 6, 'E-disse yhwh a קָ֑יִן por-que para-ti para-ti e-para-que caíram faces-tuas');
INSERT INTO verses VALUES (87, 1, 4, 7, 'não se farás-bem elevação não não farás-bem para-a-porta pecado agachado e-para-ti desejo-dele e-tu dominarás em-ele');
INSERT INTO verses VALUES (88, 1, 4, 8, 'E-disse קַיִן a הֶבֶל irmão-dele e-aconteceu em-estar-eles no-campo E-levantou קַיִן a הֶבֶל irmão-dele e-matou-ele');
INSERT INTO verses VALUES (89, 1, 4, 9, 'E-disse yhwh a קַיִן onde הֶבֶל E-disse não não soube guardião eu eu');
INSERT INTO verses VALUES (90, 1, 4, 10, 'E-disse que fizeste voz sangues-de irmão-teu clamam para-mim de a-terra');
INSERT INTO verses VALUES (91, 1, 4, 11, 'e-agora maldito tu de a-terra que abriu את boca-dela para-tomar את sangues-de irmão-teu de-mão-tua');
INSERT INTO verses VALUES (92, 1, 4, 12, 'que trabalharás את a-terra não para-ti dar força-dela para-ti na-terra e-vagante serás na-terra');
INSERT INTO verses VALUES (93, 1, 4, 13, 'E-disse קַיִן a yhwh grande iniquidade-minha de-carregar');
INSERT INTO verses VALUES (94, 1, 4, 14, 'eis expulsaste a-mim o-dia de-cima-de face-de a-terra e-de-faces-tuas esconderei-me e-serei errante e-vagante na-terra e-acontecerá todo achador-meu matará-me');
INSERT INTO verses VALUES (95, 1, 4, 15, 'E-disse a-ele yhwh portanto todo matador-de קַיִן sete-vezes será-vingado yhwh yhwh para-קַיִן para-não para-não bater a-ele todo achador-dele');
INSERT INTO verses VALUES (96, 1, 4, 16, 'e-saiu קַיִן de-diante-de yhwh e-habitou em-terra-de נוֹד oriente-de עֵדֶן');
INSERT INTO verses VALUES (97, 1, 4, 17, 'e-conheceu קַיִן את mulher-dele e-concebeu e-deu-à-luz e-houve חֲנוֹךְ E-foi E-chamou cidade E-chamou nome a-cidade como-nome-de filho-de-ele Hanoque');
INSERT INTO verses VALUES (98, 1, 4, 18, 'e-nasceu para-Hanoque a Irade dar-à-luz gerou a dar-à-luz e-Mehuiael gerou dar-à-luz Metusael e-Metusael gerou a Lameque');
INSERT INTO verses VALUES (99, 1, 4, 19, 'e-tomou para-ele Lameque duas mulheres nome a-uma Ada e-nome-de a-segunda Zilá');
INSERT INTO verses VALUES (100, 1, 4, 20, 'e-deu-à-luz Ada a ele ser foi pai-de habitou tenda e-gado');
INSERT INTO verses VALUES (101, 1, 4, 21, 'e-nome-de irmão-de-ele Jubal ele ser pai-de todo tocador-de lira e-flauta');
INSERT INTO verses VALUES (102, 1, 4, 22, 'e-Zilá também ela deu-à-luz a Tubal Caim afiador-de todo forjador-de bronze e-ferro e-irmã-de Tubal Caim Naamá');
INSERT INTO verses VALUES (103, 1, 4, 23, 'E-disse Lameque para-mulheres-de-ele Ada e-Zilá ouçam voz-de-mim mulheres-de Lameque escutem palavra-de-mim que homem matei por-ferida-de-mim e-jovem por-machucadura-de-mim');
INSERT INTO verses VALUES (104, 1, 4, 24, 'que sete-vezes será-vingado Caim e-Lameque setenta e-sete');
INSERT INTO verses VALUES (105, 1, 4, 25, 'e-conheceu homem ainda a mulher-dele filho filho e-chamou a que Sete porque semente para-mim debaixo descendência que em-lugar-de Abel porque matou-o Caim');
INSERT INTO verses VALUES (106, 1, 4, 26, 'e-para-Sete também ele E-chamou filho E-chamou a nome-de-ele Enos então yhwh para-chamar em-nome-de yhwh');
INSERT INTO chapters VALUES (5, 1, 5, 32);
INSERT INTO verses VALUES (107, 1, 5, 1, 'este livro-de gerações-de homem em-dia-de criou Elohim homem em-semelhança-de Elohim fez ele');
INSERT INTO verses VALUES (108, 1, 5, 2, 'macho e-fêmea criou-eles E-abençoou eles E-chamou a homem homem em-dia ser-criados-eles');
INSERT INTO verses VALUES (109, 1, 5, 3, 'e-viveu homem trinta e-cem ano e-gerou em-semelhança-sua conforme-imagem-sua E-chamou a nome-de-ele Sete');
INSERT INTO verses VALUES (110, 1, 5, 4, 'e-foram dias-de homem depois-de gerar-ele a Sete oito oitocentos ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (111, 1, 5, 5, 'e-foram todo homem homem que viveu nove novecentos ano e-trinta ano E-morreu');
INSERT INTO verses VALUES (112, 1, 5, 6, 'e-viveu Sete cinco dois e-cem ano e-gerou a Enos');
INSERT INTO verses VALUES (113, 1, 5, 7, 'e-viveu Sete depois-de gerar-ele a Enos sete dois e-oito centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (114, 1, 5, 8, 'e-foram todo dias-de Sete dois dez ano e-nove centenas ano E-morreu');
INSERT INTO verses VALUES (115, 1, 5, 9, 'e-viveu Enos noventa ano e-gerou a Cainã');
INSERT INTO verses VALUES (116, 1, 5, 10, 'e-viveu Enos depois-de gerar-ele a Cainã cinco dez ano e-oito centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (117, 1, 5, 11, 'e-foram todo dias-de Enos cinco dois e-nove centenas ano E-morreu');
INSERT INTO verses VALUES (118, 1, 5, 12, 'e-viveu Cainã setenta ano e-gerou a Maalalel');
INSERT INTO verses VALUES (119, 1, 5, 13, 'e-viveu Cainã depois-de gerar-ele a Maalalel quarenta ano e-oito centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (120, 1, 5, 14, 'e-foram todo dias-de Cainã dez dois e-nove centenas ano E-morreu');
INSERT INTO verses VALUES (121, 1, 5, 15, 'e-viveu Maalalel cinco dois e-sessenta ano e-gerou a Jarede');
INSERT INTO verses VALUES (122, 1, 5, 16, 'e-viveu Maalalel depois gerar-ele a Jarede trinta ano e-oito centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (123, 1, 5, 17, 'e-foram todo dias-de Maalalel cinco e-noventa ano e-oito centenas ano E-morreu');
INSERT INTO verses VALUES (124, 1, 5, 18, 'e-viveu Jarede duas e-sessenta ano e-cem ano e-gerou a Enoque');
INSERT INTO verses VALUES (125, 1, 5, 19, 'e-viveu Jarede depois gerar-ele a Enoque oito centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (126, 1, 5, 20, 'e-foram todo dias-de Jarede duas e-sessenta ano e-nove centenas ano E-morreu');
INSERT INTO verses VALUES (127, 1, 5, 21, 'e-viveu Enoque cinco e-sessenta ano e-gerou a Matusalém');
INSERT INTO verses VALUES (128, 1, 5, 22, 'e-andou Enoque a o-Elohim depois gerar-ele a Matusalém três centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (129, 1, 5, 23, 'e-houve todo dias-de Enoque cinco e-sessenta ano e-três centenas anos');
INSERT INTO verses VALUES (130, 1, 5, 24, 'e-andou Enoque a o-Elohim e-não-ele ele tomou a-ele Elohim');
INSERT INTO verses VALUES (131, 1, 5, 25, 'e-viveu Matusalém sete e-oitenta ano e-cem-de ano e-gerou a Lameque');
INSERT INTO verses VALUES (132, 1, 5, 26, 'e-viveu Metusalém depois-de gerar-ele a Lameque duas e-oitenta ano e-sete centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (133, 1, 5, 27, 'e-foram todo dias-de Matusalém nove e-sessenta ano e-nove centenas ano E-morreu');
INSERT INTO verses VALUES (134, 1, 5, 28, 'e-viveu Lameque duas e-oitenta ano e-cem-de ano filho filho');
INSERT INTO verses VALUES (135, 1, 5, 29, 'E-chamou a nome-dele dizendo para-dizer consolará-nos de-obra-nossa e-de-dor-de mãos-nossas de a-terra que yhwh yhwh');
INSERT INTO verses VALUES (136, 1, 5, 30, 'e-viveu Lameque depois-de gerar-ele a Noé cinco e-noventa ano e-cinco centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (137, 1, 5, 31, 'e-foi todo dias-de Lameque sete e-setenta ano e-sete centenas ano E-morreu');
INSERT INTO verses VALUES (138, 1, 5, 32, 'e-foi Noé filho-de cinco centenas ano e-gerou Noé a nome a Cam e-a Jafé');
INSERT INTO chapters VALUES (6, 1, 6, 22);
INSERT INTO verses VALUES (139, 1, 6, 1, 'e-houve porque começou o-homem para-multiplicar sobre face-de a-terra a-eles nasceram para-eles');
INSERT INTO verses VALUES (140, 1, 6, 2, 'e-viram filhos-de הָֽאֱלֹהִים o-homem que o-homem porque boas a-eles e-tomaram de-toda mulheres de-todo que escolheram');
INSERT INTO verses VALUES (141, 1, 6, 3, 'E-disse yhwh não contenderá espírito-meu para-sempre para-sempre ele ele e-sejam e-serão dias-dele cem e-vinte anos');
INSERT INTO verses VALUES (142, 1, 6, 4, 'os-nefilim foram na-terra em-os-dias os-aqueles e-também depois-de assim que entraram filhos-de הָֽאֱלֹהִים a filhas-de a-eles e-geraram para-eles eles os-valentes que desde-eternidade homens-de o-nome');
INSERT INTO verses VALUES (143, 1, 6, 5, 'E-viu yhwh que multiplicai maldade-de o-homem em-a-terra e-todo formação-de pensamentos-de coração-dele somente mau todo o-dia');
INSERT INTO verses VALUES (144, 1, 6, 6, 'e-lamentou yhwh porque fez a o-homem em-a-terra e-entristeceu-se a coração-dele');
INSERT INTO verses VALUES (145, 1, 6, 7, 'E-disse yhwh apagarei a o-homem de-cima-de face-de de-sobre face-de a-terra desde-homem até animal que réptil que ave os-céus porque lamentei porque fiz-eles');
INSERT INTO verses VALUES (146, 1, 6, 8, 'e-Noé encontrou graça em-olhos-de yhwh');
INSERT INTO verses VALUES (147, 1, 6, 9, 'Estas gerações-de Noé Noé homem justo íntegro ser em-gerações-dele a הָאֱלֹהִים andou-com Noé');
INSERT INTO verses VALUES (148, 1, 6, 10, 'e-gerou Noé três filhos a nome a Cam e-a Jafé');
INSERT INTO verses VALUES (149, 1, 6, 11, 'e-corrompeu-se a-terra diante-de הָאֱלֹהִים e-encheu-se a-terra violência');
INSERT INTO verses VALUES (150, 1, 6, 12, 'E-viu Elohim a a-terra e-eis corrompida porque corrompeu todo carne a caminho-dele sobre a-terra');
INSERT INTO verses VALUES (151, 1, 6, 13, 'E-disse Elohim para-Noé fim-de todo carne veio diante-de-mim a-terra cheia a-terra violência de-face-deles e-eis-eu destruindo-eles a a-terra');
INSERT INTO verses VALUES (152, 1, 6, 14, 'fez a-ti arca-de madeiras-de gofer compartimentos faz-o a a-arca e-betumarás ela de-dentro e-de-fora com-o-betume');
INSERT INTO verses VALUES (153, 1, 6, 15, 'e-este que farás ela três centenas-de côvado comprimento-de a-arca cinquenta côvado largura-dela e-trinta côvado altura-dela');
INSERT INTO verses VALUES (154, 1, 6, 16, 'janela faz-o para-a-arca e-a côvado acabarás-a de-em-cima e-entrada-de a-arca em-lado-dela porás inferiores dois e-terceiros faz-a');
INSERT INTO verses VALUES (155, 1, 6, 17, 'e-eu eis-me trazendo a águas águas sobre a-terra para-destruir espírito vida debaixo-de em-ele espírito viventes de-debaixo-de os-céus todo que na-terra expirará');
INSERT INTO verses VALUES (156, 1, 6, 18, 'e-estabelecerei a aliança-minha contigo e-entrarás tu a-arca tu e-filhos-teus e-esposa-tua e-esposas-de filhos-teus contigo');
INSERT INTO verses VALUES (157, 1, 6, 19, 'e-de-todo o-vivente de-todo de-toda dois de-todo trarás a macho e-fêmea contigo macho e-fêmea serão');
INSERT INTO verses VALUES (158, 1, 6, 20, 'de-a-ave conforme-sua-espécie e-de conforme-sua-espécie de-toda de-todo réptil conforme-sua-espécie segundo-espécie-sua de-toda de-todo virão a-ti para-manter-vivos');
INSERT INTO verses VALUES (159, 1, 6, 21, 'e-tu toma para-ti de-todo alimento que será-comido e-ajuntarás a-ti e-acontecerá para-alimento e-para-eles para-comida');
INSERT INTO verses VALUES (160, 1, 6, 22, 'E-fez Noach conforme-tudo que ordenou ele Elohim assim fez');
INSERT INTO chapters VALUES (7, 1, 7, 24);
INSERT INTO verses VALUES (161, 1, 7, 1, 'E-disse yhwh a-Noach vem tu e-todo casa-tua a a-arca porque a-ti vi justo diante-de-mim na-geração a-esta');
INSERT INTO verses VALUES (162, 1, 7, 2, 'de-toda a-animal os-animais tomarás para-ti sete sete homem e-mulher-dele e-de a-animal não não ela ele dois homem e-esposa-dele');
INSERT INTO verses VALUES (163, 1, 7, 3, 'também de-ave-de os-céus sete sete macho e-fêmea para-manter-viva semente sobre face-de todo a-terra');
INSERT INTO verses VALUES (164, 1, 7, 4, 'que para-dias ainda sete eu faço-chover sobre a-terra dia dia noite noite e-apagarei את- todo de-cima-de face-de fiz de-sobre face-de a-terra');
INSERT INTO verses VALUES (165, 1, 7, 5, 'E-fez Noach conforme-tudo que yhwh yhwh');
INSERT INTO verses VALUES (166, 1, 7, 6, 'e-Noé filho-de seis centenas ano ser águas águas sobre a-terra');
INSERT INTO verses VALUES (167, 1, 7, 7, 'E-veio Noé e-filhos-dele e-esposa-dele e-esposas-de filhos-seus com-ele de-diante-de a-arca de-face-de águas-de o-dilúvio');
INSERT INTO verses VALUES (168, 1, 7, 8, 'de o-gado a-pura e-de o-gado que não-ela e-tudo e-de a-ave e-todo que réptil sobre a-terra');
INSERT INTO verses VALUES (169, 1, 7, 9, 'dois dois vieram a Noach macho e-fêmea macho e-fêmea como-que ordenou Elohim a Noé');
INSERT INTO verses VALUES (170, 1, 7, 10, 'e-foi para-sete-de os-dias e-águas-de o-dilúvio foram sobre a-terra');
INSERT INTO verses VALUES (171, 1, 7, 11, 'em-ano-de seis-de centenas ano para-vida-de Noé em-o-mês dia em-sete-de no-dia dia para-o-mês em-o-dia o-este foram-fendidas todo fontes-de abismo multiplicai e-comportas-de os-céus foram-abertas');
INSERT INTO verses VALUES (172, 1, 7, 12, 'e-foi a-chuva sobre a-terra dia dia noite noite');
INSERT INTO verses VALUES (173, 1, 7, 13, 'em-essência-de o-dia o-este veio Noé e-Shem e-Cham e-Yafet filhos-de Noach e-mulher-de Noé e-três-de mulheres-de filhos-seus com-eles a a-arca');
INSERT INTO verses VALUES (174, 1, 7, 14, 'eles e-todo conforme-sua-espécie segundo-espécie-sua conforme-sua-espécie o-gado segundo-espécie-sua e-todo conforme-sua-espécie o-que-rasteja conforme-sua-espécie a-terra segundo-espécie-sua e-todo a-ave conforme-espécie-sua todo pássaro-de todo asa');
INSERT INTO verses VALUES (175, 1, 7, 15, 'e-vieram a Noé a a-arca dois dois espírito vida que nele espírito vivos');
INSERT INTO verses VALUES (176, 1, 7, 16, 'e-os-que-vêm macho e-fêmea de-todo carne vieram como-que ele a-ele e-fechou yhwh yhwh atrás-dele');
INSERT INTO verses VALUES (177, 1, 7, 17, 'e-foi o-dilúvio quarenta dia sobre a-terra e-multiplicaram as-águas e-levantaram a de-cima-de a-terra de-sobre a-terra');
INSERT INTO verses VALUES (178, 1, 7, 18, 'e-prevaleceram as-águas e-multiplicaram muito sobre a-terra e-foi a-arca as-águas face-de as-águas');
INSERT INTO verses VALUES (179, 1, 7, 19, 'e-as-águas muito muito muito a-terra e-cobriram todo as-montanhas as-altas que sob todo os-céus');
INSERT INTO verses VALUES (180, 1, 7, 20, 'cinco quinze côvado de-acima prevaleceram as-águas e-cobriram as-montanhas');
INSERT INTO verses VALUES (181, 1, 7, 21, 'e-expirou todo carne o-que-rasteja sobre a-terra e-sobre-os-animais e-em-o-gado e-em-a-vida-selvagem e-em-todo o-enxame e-tudo o-homem a-terra e-todo o-homem');
INSERT INTO verses VALUES (182, 1, 7, 22, 'todo que fôlego-de vida em-suas-narinas de-toda de-todo que em-a-terra-seca morreram');
INSERT INTO verses VALUES (183, 1, 7, 23, 'e-apagou את- todo a-substância que sobre face-de a-terra de-homem até animal até réptil e-até ave os-céus e-foram-apagados de a-terra e-restou somente- Noé e-que com-ele em-a-arca');
INSERT INTO verses VALUES (184, 1, 7, 24, 'e-prevaleceram as-águas sobre a-terra cinquenta dia dia');
INSERT INTO chapters VALUES (8, 1, 8, 22);
INSERT INTO verses VALUES (185, 1, 8, 1, 'e-lembrou-se Elohim a Noé e-a todo a-vida e-a todo a-animal que espírito em-a-arca e-fez-passar as-águas espírito sobre a-terra e-diminuíram as-águas');
INSERT INTO verses VALUES (186, 1, 8, 2, 'e-foram-fechadas fontes-de abismo e-trapos os-céus e-foi-retida a-chuva de os-céus');
INSERT INTO verses VALUES (187, 1, 8, 3, 'e-retornaram as-águas de-cima-de a-terra indo e-retornando e-diminuíram as-águas ao-fim-de cinquenta e-cem dia');
INSERT INTO verses VALUES (188, 1, 8, 4, 'e-repousou a-arca no-mês o-sétimo no-sétimo- dia dia sobre sobre montes-de Ararate');
INSERT INTO verses VALUES (189, 1, 8, 5, 'e-as-águas foram indo e-diminuindo até o-mês o-dez em-o-décimo no-primeiro do-mês apareceram topos-de os-montes');
INSERT INTO verses VALUES (190, 1, 8, 6, 'e-foi ao-fim-de quarenta dia e-abriu Noé a janela-de a-arca que fez');
INSERT INTO verses VALUES (191, 1, 8, 7, 'e-enviou a o-corvo e-saiu saindo e-retornando até de-cima-de a-terra de-sobre a-terra');
INSERT INTO verses VALUES (192, 1, 8, 8, 'e-enviou a a-pomba para-ver para-ver diminuíram de-cima-de face-de face-de a-terra');
INSERT INTO verses VALUES (193, 1, 8, 9, 'e-não encontrou a-pomba descanso para-planta-de a-ele e-retornou a-ele a a-arca porque sua-mão sobre e-trouxe todo a-ele e-estendeu mão-dele e-tomou-a E-veio ela a-ele a a-arca');
INSERT INTO verses VALUES (194, 1, 8, 10, 'e-esperou ainda sete dias outros e-continuou enviou a a-pomba de a-arca');
INSERT INTO verses VALUES (195, 1, 8, 11, 'e-veio a-ele a-pomba ao-tempo-de tarde e-eis folha-de oliveira arrancada em-boca-dela e-soube Noé porque de-cima-de a-terra de-sobre a-terra');
INSERT INTO verses VALUES (196, 1, 8, 12, 'e-esperou ainda sete dias outros e-enviou a a-pomba e-não continuou retornar- a-ele ainda');
INSERT INTO verses VALUES (197, 1, 8, 13, 'e-foi em-uma e-seis- centenas ano em-o-primeiro no-primeiro para-o-mês secaram de-cima-de a-terra a-terra e-removeu Noach a E-viu a-arca E-viu face-de secaram face-de a-terra');
INSERT INTO verses VALUES (198, 1, 8, 14, 'e-em-o-mês o-segundo em-sete e-vinte dia para-o-mês secou a-terra');
INSERT INTO verses VALUES (199, 1, 8, 15, 'e-falou Elohim a dizendo para-dizer');
INSERT INTO verses VALUES (200, 1, 8, 16, 'sai de tu tu e-esposa-tua e-filhos-teus e-esposas-de filhos-teus contigo');
INSERT INTO verses VALUES (201, 1, 8, 17, 'todo a-vida que contigo e-sobre-os-animais carne em-o-ave e-em-a-animal e-em-todo o-réptil o-que-rasteja sobre na-terra contigo e-os-cruzem-se em-a-terra e-frutifiquem e-multipliquem sobre a-terra');
INSERT INTO verses VALUES (202, 1, 8, 18, 'e-saiu- Noach e-filhos-dele e-esposa-dele e-esposas-de filhos-dele com-ele');
INSERT INTO verses VALUES (203, 1, 8, 19, 'todo a-vida todo o-réptil e-todo a-ave todo rastejante sobre a-terra para-famílias-deles saíram de a-arca');
INSERT INTO verses VALUES (204, 1, 8, 20, 'E-edificou Noach altar para-יהוה E-tomou de-toda a-animal os-animais e-de-todo a-ave o-puro e-ofereceu holocaustos em-o-altar');
INSERT INTO verses VALUES (205, 1, 8, 21, 'e-cheirou yhwh a aroma E-disse yhwh yhwh a coração-dele não ajuntarei para-amaldiçoar ainda que a-terra por-causa-de o-homem porque inclinação coração o-homem mau desde-juventude-dele e-não ajuntarei ainda para-ferir a todo viveu como-aquela fiz');
INSERT INTO verses VALUES (206, 1, 8, 22, 'até todo a-terra semente semente e-colheita e-frio e-calor e-verão e-inverno e-dia não não cessarão');
INSERT INTO chapters VALUES (9, 1, 9, 29);
INSERT INTO verses VALUES (207, 1, 9, 1, 'E-abençoou Elohim a Noé E-disse a-eles frutificai e-multiplicai-vos e-enchei e-multipliquem e-encham a a-terra');
INSERT INTO verses VALUES (208, 1, 9, 2, 'e-temor-de-vocês e-terror-de-vocês será sobre todo a-terra a-terra e-sobre todo ave os-céus em-todo que rasteja o-mar e-em-todo- peixes-de o-mar em-mão-de-vocês foram-dados');
INSERT INTO verses VALUES (209, 1, 9, 3, 'todo réptil que a-vós será para-alimento será para-alimento dei a-vós dei para-vocês a todo');
INSERT INTO verses VALUES (210, 1, 9, 4, 'somente carne em-alma-sua não não comereis');
INSERT INTO verses VALUES (211, 1, 9, 5, 'e-somente a sangue-vosso para-almas-vossas requerei de-mão-de todo vida requererei-o e-de-mão-de o-homem de-mão-de homem irmão-seu requerei a alma o-homem');
INSERT INTO verses VALUES (212, 1, 9, 6, 'derramador-de sangue o-homem em-o-homem sangue-seu será-derramado que à-imagem-de Elohim fez a o-homem');
INSERT INTO verses VALUES (213, 1, 9, 7, 'e-vós frutificai e-multiplicai-vos frutificai na-terra e-multiplicai em-ela');
INSERT INTO verses VALUES (214, 1, 9, 8, 'E-disse Elohim a Noé e-a dizendo com-ele para-dizer');
INSERT INTO verses VALUES (215, 1, 9, 9, 'e-eu eis-me estabelecendo a aliança-minha convosco e-com descendência-vossa depois-vós');
INSERT INTO verses VALUES (216, 1, 9, 10, 'e-a todo alma a-vida que convosco em-o-ave em-a-animal a-terra vivente-de de-toda convosco de-todo a-todo animal-de a-terra vivente-de a-terra');
INSERT INTO verses VALUES (217, 1, 9, 11, 'e-estabelecerei a aliança-minha convosco e-não será-cortada todo carne mais de-águas-de o-dilúvio e-não a-terra mais dilúvio para-destruir a-terra');
INSERT INTO verses VALUES (218, 1, 9, 12, 'E-disse Elohim esta sinal-de a-aliança que eu deu e-entre e-entre-vós vivente todo alma vida eternidade convosco para-gerações-de eternidade');
INSERT INTO verses VALUES (219, 1, 9, 13, 'a dei dei em-a-nuvem e-será para-sinal aliança e-entre a-terra a-terra');
INSERT INTO verses VALUES (220, 1, 9, 14, 'e-será em-a-névoa nuvem sobre a-terra e-aparecerá o-arco em-a-nuvem');
INSERT INTO verses VALUES (221, 1, 9, 15, 'e-lembrarei a aliança-minha que entre-mim e-entre e-entre vivente alma vida em-todo carne e-não será mais as-águas para-dilúvio para-destruir todo carne');
INSERT INTO verses VALUES (222, 1, 9, 16, 'e-será o-arco em-a-nuvem e-verei-a para-lembrar aliança eternidade entre Elohim e-entre todo vivente vivente em-todo carne que sobre a-terra');
INSERT INTO verses VALUES (223, 1, 9, 17, 'E-disse Elohim a esta esta sinal-de a-aliança que e-entre entre-mim e-entre todo carne que sobre a-terra');
INSERT INTO verses VALUES (224, 1, 9, 18, 'e-foram filhos-de Noé os-saintes de a-arca nome e-Cham ele e-Cham ele pai-de Canaan');
INSERT INTO verses VALUES (225, 1, 9, 19, 'três Estas filhos-de Noach e-de-os-esse espalhou-se todo a-terra');
INSERT INTO verses VALUES (226, 1, 9, 20, 'e-ele-começou-a-ser Noé homem a-terra E-plantou vinhedo');
INSERT INTO verses VALUES (227, 1, 9, 21, 'e-bebeu de o-vinho e-intoxicou-se no-meio-de em-meio-de a-tenda-dele');
INSERT INTO verses VALUES (228, 1, 9, 22, 'E-viu Cham pai-de Canaan את nudez-de seu-pai e-revelou a-dois-de seus-irmãos no-exterior');
INSERT INTO verses VALUES (229, 1, 9, 23, 'E-tomou nome e-Jefet a a-roupa e-eles-postaram sobre o-lombo dois-deles e-andaram atrás-ela e-eles-cobriram את a-nudez-de de-seu-pai e-os-lhes-faces atrás-ela não seu-pai não viram-;');
INSERT INTO verses VALUES (230, 1, 9, 24, 'e-ele-se-levantou Noé de-o-sua-vinho e-ele-conheceu objeto-direto que fez- para-ele filho-de-ele o-pequeno;');
INSERT INTO verses VALUES (231, 1, 9, 25, 'E-disse maldito assim servo servos será para-seus-irmãos;');
INSERT INTO verses VALUES (232, 1, 9, 26, 'E-disse bendito yhwh elohim-de nome e-seja Canaan servo a-eles');
INSERT INTO verses VALUES (233, 1, 9, 27, 'japte Elohim le-yefet veyishkon be-ohalei- e-seja E-foi kena''an servo lahem:');
INSERT INTO verses VALUES (234, 1, 9, 28, 'e-viveu Noé atrás-de o-dilúvio três novecentos ano ve-chamishim anos');
INSERT INTO verses VALUES (235, 1, 9, 29, 'e-foram todo dias-de Noé nove novecentos ano e-cinquenta ano E-morreu');
INSERT INTO chapters VALUES (10, 1, 10, 32);
INSERT INTO verses VALUES (236, 1, 10, 1, 'e-estes gerações-de filhos-de Noé nome chom va-yafet a-eles a-eles filhos achar o-dilúvio');
INSERT INTO verses VALUES (237, 1, 10, 2, 'filhos-de Jafé Gômer e-Magogue e-Madai e-Javã e-Tubal e-Meseque e-Tirás');
INSERT INTO verses VALUES (238, 1, 10, 3, 'e-filhos-de Gômer Asquenaz e-rifat e-togarmah');
INSERT INTO verses VALUES (239, 1, 10, 4, 'e-filhos-de Javã Elisá e-tarshish Quitim e-dodanim');
INSERT INTO verses VALUES (240, 1, 10, 5, 'de-elleh nifredhu ilhas-de-a as-nações be-arctotam homem le-lshono para-famílias-deles be-goyehem');
INSERT INTO verses VALUES (241, 1, 10, 6, 'e-filhos-de Cam Cuxe e-Misraim e-Put e-Canaã');
INSERT INTO verses VALUES (242, 1, 10, 7, 'e-filhos-de Cuxe Sebá e-Chavila e-Sabtata e-Raama e-Sabtecá e-filhos-de Raama Sabá e-Dedã');
INSERT INTO verses VALUES (243, 1, 10, 8, 'e-Cuxe dar-à-luz a ele ele começou para-ser gibor na-terra');
INSERT INTO verses VALUES (244, 1, 10, 9, 'ele foi gibor- yhwh diante-de yhwh sobre assim que-se-diz Kemered yhwh caça diante-de yhwh');
INSERT INTO verses VALUES (245, 1, 10, 10, 'e-foi primeira seu-reino Babilônia e-erech e-acad e-kalneh em-terra-de shinar');
INSERT INTO verses VALUES (246, 1, 10, 11, 'de aquela sair saiu E-edificou e-construiu a nínvea e-a ruas cidade e-a calah');
INSERT INTO verses VALUES (247, 1, 10, 12, 'e-a entre entre e-entre e-entre ela ela a-cidade a-grande');
INSERT INTO verses VALUES (248, 1, 10, 13, 'e-Misraim dar-à-luz a ludim e-a Ludim e-a Leabim e-a Naftuim');
INSERT INTO verses VALUES (249, 1, 10, 14, 'e-a Patrusim e-a Casluim que saíram de-lá Filisteus e-a Caftorim');
INSERT INTO verses VALUES (250, 1, 10, 15, 'e-Canaã dar-à-luz a tsidon primogênito-seu e-a Hete');
INSERT INTO verses VALUES (251, 1, 10, 16, 'e-a o-jebuseu e-a o-amorreu e-a o-girgaseu');
INSERT INTO verses VALUES (252, 1, 10, 17, 'e-a o-hivvi e-a o-arqueu e-a o-sineu');
INSERT INTO verses VALUES (253, 1, 10, 18, 'e-a o-arvedi e-a o-zemareu e-a o-chamati e-apos espalharam-se-os famílias-de-as o-canaanita-verso-final');
INSERT INTO verses VALUES (254, 1, 10, 19, 'e-foi fronteira-de-a o-canaanita de-sidom Bo-achah grara até Gaza vem-a S''domah va-amorah ve-admah u-tzvoyim até la-sha''');
INSERT INTO verses VALUES (255, 1, 10, 20, 'Estas filhos-de cham para-famílias-deles li-lshonotam be-arzotam be-goyehem''');
INSERT INTO verses VALUES (256, 1, 10, 21, 'u-lshem nasceu também ele ab-i todo filhos-de e-veber a-chi ye-fet o-grande');
INSERT INTO verses VALUES (257, 1, 10, 22, 'filhos-de nome Elão ve-a-shur e-Arfaxade ve-lud ve-ar-am');
INSERT INTO verses VALUES (258, 1, 10, 23, 'e-filhos-de Arã Uz e-Hul e-Geter va-mash');
INSERT INTO verses VALUES (259, 1, 10, 24, 'e-Arfaxade dar-à-luz a enviou dar-à-luz gerou a Éber');
INSERT INTO verses VALUES (260, 1, 10, 25, 'e-a-Éber nasceu segundo filhos nome ha-e-chad Pelegue que em-dias-seus foi-dividida a-terra e-nome-de irmão-seu Joctã');
INSERT INTO verses VALUES (261, 1, 10, 26, 'e-Joctã dar-à-luz a Almodá e-a Salefe e-a Hazarmavé e-a Jerá');
INSERT INTO verses VALUES (262, 1, 10, 27, 'e-a Hadorão e-a Uzal e-a Diclá');
INSERT INTO verses VALUES (263, 1, 10, 28, 'e-a o-val e-a Avi-mael e-a Sabá');
INSERT INTO verses VALUES (264, 1, 10, 29, 'e-a Ofir e-a Havilá e-a Jobabe todo estes filhos-de Joctã');
INSERT INTO verses VALUES (265, 1, 10, 30, 'e-foi moshav-am mi-Meisha Bo-achah Sepharah monte-de ha-qedem');
INSERT INTO verses VALUES (266, 1, 10, 31, 'Estas filhos-de nome para-famílias-deles li-lshonot-am be-arzot-am le-goyeh-em');
INSERT INTO verses VALUES (267, 1, 10, 32, 'Estas de-famílias filhos-de Noach para-a-sua-genealogia em-seus-povos e-de-estes se-separaram as-nações na-terra depois o-dilúvio');
INSERT INTO chapters VALUES (11, 1, 11, 32);
INSERT INTO verses VALUES (268, 1, 11, 1, 'e-foi todo a-terra de-língua um e-de-palavras umidos');
INSERT INTO verses VALUES (269, 1, 11, 2, 'e-foi em-seu-marchar ao-oriente e-eles-acharam em-a-valley em-terra-de Shinar e-habitaram nome');
INSERT INTO verses VALUES (270, 1, 11, 3, 'e-eles-disseram homem a companheiro-seu venha nós-faremos-tijolos de-tijolos e-nós-queimaremos para-a-queimação a-eles para-eles os-tijolos para-a-pedra ser a-eles a-eles de-o-barro');
INSERT INTO verses VALUES (271, 1, 11, 4, 'e-ele-disseram dê-a constramos- para-nós cidade e-torre e-sua-cabeça na-terra-do-ceu e-nos-tornemos- para-nós nome para-que-não nafutz sobre face-de todo a-terra');
INSERT INTO verses VALUES (272, 1, 11, 5, 'e-desceu yhwh lireot a a-cidade e-a ha-migdal que o-homem filhos-de o-homem');
INSERT INTO verses VALUES (273, 1, 11, 6, 'E-disse yhwh eis povo um ve-safa uma lekholam vezeh hachilam laasot e-agora não yibatsar de-eles todo que eles-zelaram para-fazerem');
INSERT INTO verses VALUES (274, 1, 11, 7, 'venha nós-desçamos e-nos-confundamos nome sua-língua que não eles-ouvirão homem beira-de seu-amigo');
INSERT INTO verses VALUES (275, 1, 11, 8, 'e-ele-espalhou yhwh eles de-lá sobre face-de todo a-terra e-eles-pararam para-construir a-cidade');
INSERT INTO verses VALUES (276, 1, 11, 9, 'sobre chamou chamou nome-dela Babilônia porque yhwh molhou yhwh língua todo yhwh e-de-ali espalhá-los yhwh sobre face-de todo a-terra');
INSERT INTO verses VALUES (277, 1, 11, 10, 'Estas gerações-de nome nome filho-de cem ano e-gerou a Arfaxeado dois-anos depois o-dilúvio');
INSERT INTO verses VALUES (278, 1, 11, 11, 'e-viveu nome depois-de gerar-ele a Arfaxeado cinco centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (279, 1, 11, 12, 'e-Arfaxeado vida cinco e-trinta ano e-gerou a enviou');
INSERT INTO verses VALUES (280, 1, 11, 13, 'e-viveu Arfaxeado depois-de gerar-ele a enviou três dois e-quatro centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (281, 1, 11, 14, 'e-envie vida trinta ano e-gerou a Éber');
INSERT INTO verses VALUES (282, 1, 11, 15, 'e-viveu enviou depois-de gerar-ele a além- três dois e-quatro centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (283, 1, 11, 16, 'e-viveu- além quatro e-trinta ano e-gerou a paleg');
INSERT INTO verses VALUES (284, 1, 11, 17, 'e-viveu- além- depois-de gerar-ele a paleg trinta ano e-quatro centenas ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (285, 1, 11, 18, 'e-viveu paleg trinta ano e-gerou a Reu');
INSERT INTO verses VALUES (286, 1, 11, 19, 'e-viveu fluir depois-de gerar-ele a pastorearam nove dois e-doiscentos ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (287, 1, 11, 20, 'e-viveu re-u sh-teiym e-trinta ano e-gerou a so-ruug');
INSERT INTO verses VALUES (288, 1, 11, 21, 'e-viveu re-u depois-de gerar-ele a so-ruug sete dois e-doiscentos ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (289, 1, 11, 22, 'va-y-chi so-ruug trinta ano e-gerou a naa-hor');
INSERT INTO verses VALUES (290, 1, 11, 23, 'e-viveu srug depois-de holidó a Naor maatayim ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (291, 1, 11, 24, 'e-viveu nachor nove e-vinte ano e-gerou a Terá');
INSERT INTO verses VALUES (292, 1, 11, 25, 'e-viveu nachor depois-de gerar-ele a terach teshá- doze ano e-cem ano e-gerou filhos e-filhas');
INSERT INTO verses VALUES (293, 1, 11, 26, 'e-viveu terach setenta ano vayyoled a abram a Naor e-a o-Ran-:');
INSERT INTO verses VALUES (294, 1, 11, 27, 'e-estes gerações-de e-Tarah e-Tarah gerou a a-Abram a Naor e-a o-Ran- ve-o-Ran- gerou a Loth-:');
INSERT INTO verses VALUES (295, 1, 11, 28, 'E-morreu o-Ran- sobre face-de seu-pai pai-seu em-terra-de moledato- Be-Ur coshdeem');
INSERT INTO verses VALUES (296, 1, 11, 29, 'E-tomou abram ve-nachor a-eles mulheres nome esposa-de abram sarah ve-shem esposa-de nachor milcha filha-de haran avi- de-Malka e-Avi Yescah');
INSERT INTO verses VALUES (297, 1, 11, 30, 'e-foi Sara aquara não para-ela e-valad');
INSERT INTO verses VALUES (298, 1, 11, 31, 'E-tomou Terach a Abram filho-seu e-a Lot ben- Harã filho-de seu-filho e-את Sarái nora-dele mulher-de Abram filho-seu e-saíram com-eles luzeiro dos-cassidim para-andar terra-para Canaã e-vieram até Harã e-habitaram nome');
INSERT INTO verses VALUES (299, 1, 11, 32, 'e-foram dias-de Tera cinco dois e-doiscentos ano E-morreu Tera Bharã:');
INSERT INTO chapters VALUES (12, 1, 12, 20);
INSERT INTO verses VALUES (300, 1, 12, 1, 'E-disse yhwh a Abram vai-para para-ti de-a-tua-terra e-de-teu-nascimento e-de-casa pai-teu a a-terra que teu-pai:');
INSERT INTO verses VALUES (301, 1, 12, 2, 'e-e-farei-te para-povo grande e-e-abençoarei-te e-eu-exaltarei o-teu-nome e-sejas em-benção');
INSERT INTO verses VALUES (302, 1, 12, 3, 'e-eu-abençoarei o-que-te-abençoe e-o-que-te-amaldiçoe não-ser-eu e-se-abençoarão em-ti todo famílias-de a-terra');
INSERT INTO verses VALUES (303, 1, 12, 4, 'E-andou אַבְרָ֗ם como-que palavra a-ele yhwh E-andou com-ele Lot-verso e-Abram filho-de cinco dois e-setenta ano em-saída-dele de-Charran');
INSERT INTO verses VALUES (304, 1, 12, 5, 'E-tomou Abram a sara-y sua-mulher e-a Lot filho-de o-seu-irmão e-a todo o-seu-bens que eles-adquiriram e-a a-alma que fizeram em-Charan e-eles-saíram para-andar terra-para Canaã e-vieram na-terra כְּנָֽעַן');
INSERT INTO verses VALUES (305, 1, 12, 6, 'e-ele-passou Abram na-terra até lugar Siquem até Elom Moreh ve-ha-cnanai az na-terra');
INSERT INTO verses VALUES (306, 1, 12, 7, 'E-viu yhwh a E-disse E-disse le-zarkha etenn a E-edificou esta va-yiben nome altar a-ele han-nireh a-ele');
INSERT INTO verses VALUES (307, 1, 12, 8, 'va-ya-teq de-lá a-montanha ao-oriente para-a-casa-de El e-ele-esticou sua-tenda casa-de El ao-oriente e-a-aldeia do-leste e-ele-construiu E-chamou um-altar yhwh E-chamou em-nome-de yhwh');
INSERT INTO verses VALUES (308, 1, 12, 9, 'e-ele-partiu Abram indo e-partir a-sud');
INSERT INTO verses VALUES (309, 1, 12, 10, 'e-houve fome em-a-terra e-descer Abram de-Mitsraymah para-viver nome porque grande a-fome na-terra');
INSERT INTO verses VALUES (310, 1, 12, 11, 'e-houve como-que se-aproximou para-vir Egito-para E-disse a serei mulher-dele eis-que- que soube porque mulher fará-te aparência tu');
INSERT INTO verses VALUES (311, 1, 12, 12, 'e-será porque verão te-a os-megem e-direão esta esta e-te-ferão me-a te-a viverão-te');
INSERT INTO verses VALUES (312, 1, 12, 13, 'dize- por-favor irmã-de-mim você-é a-fim-de será-bom a-mim por-você e-viverá alma-minha em-razão-de-você');
INSERT INTO verses VALUES (313, 1, 12, 14, 'e-houve com-vir Abrão Egito-para e-viram os-megdes a a-mulher ela muito ela-é muito');
INSERT INTO verses VALUES (314, 1, 12, 15, 'e-viram a-ela príncipes-de פַּרְעֹה e-ele-louvarão a-ela a Faraó e-foi-tirada a-mulher casa פַּרְעֹה');
INSERT INTO verses VALUES (315, 1, 12, 16, 'e-a-abram o-fez-bem por-ela e-foi para-ele ovelhas-e e-gado e-jumentos e-servos e-escravas e-juntas e-camelas');
INSERT INTO verses VALUES (316, 1, 12, 17, 'e-nagge yhwh a Pharaoh negaim gadolim e-a casa-dele sobre palavra sara-i mulher-de Abram');
INSERT INTO verses VALUES (317, 1, 12, 18, 'E-chamou Pharaoh le-Abram E-disse que- zot a-mim li por-que a-mim que para-mim ela es-tu-a e-la');
INSERT INTO verses VALUES (318, 1, 12, 19, 'por-que dis-e-stu irm-a-da-mi ela e-que-ei ela para-mim para-mulher e-agora eis es-tu-a pe-go e-vai');
INSERT INTO verses VALUES (319, 1, 12, 20, 'E-ordenou sobre-ele פַּרְעֹה homens ve-y-sha-l-chu ele e-a mulher-sua e-a todo que a-ele');
INSERT INTO chapters VALUES (13, 1, 13, 18);
INSERT INTO verses VALUES (320, 1, 13, 1, 'e-subiu Abram de-Mitsrayim ele e-esposa-dele e-todo que para-ele e-Lot com-ele o-Negueva');
INSERT INTO verses VALUES (321, 1, 13, 2, 'e-Abram pesado muito na-o-pecuária com-a-prata e-no-ouro');
INSERT INTO verses VALUES (322, 1, 13, 3, 'E-andou para-os-seus-movimentos do-negueb e-até casa-de El até o-lugar que foi entre no-primeiro e-entre casa-de El e-entre a-ay');
INSERT INTO verses VALUES (323, 1, 13, 4, 'a lugar o altar que fez E-chamou na-primeira E-chamou nome yhwh em-nome-de yhwh');
INSERT INTO verses VALUES (324, 1, 13, 5, 'e-também o-que-vai o-andando ser Abram foi ovelhas- e-vacas e-tendas-verso');
INSERT INTO verses VALUES (325, 1, 13, 6, 'e-não eles a-terra a-terra para-habitar juntos porque foi re-sus-to-eles muito e-não poderiam para-habitar juntos-verso');
INSERT INTO verses VALUES (326, 1, 13, 7, 'e-foi entre entre pastores-de e-entre Abram e-entre pastores-de rebanho-de Lot-verso e-o-canaanita e-o-perizeu então habitou na-terra');
INSERT INTO verses VALUES (327, 1, 13, 8, 'E-disse Abram a Lot a por-favor seja Meriba e-entre e-entre-você e-entre meus-ovelheiros e-entre teus-ovelheiros porque homens irmãos nós-verso');
INSERT INTO verses VALUES (328, 1, 13, 9, 'não- todo a-terra diante-de-ti hi-par-ed por-favor de-mim-sobre se a-esquerda e-direita-eu-fiquei e-se a-direita e-esmialha-verso');
INSERT INTO verses VALUES (329, 1, 13, 10, 'e-ele-levantou- Lot E-viu os-seus-olhos E-viu que todo circularidade o-Jordão porque toda-a-sua yhwh em-frente-de corrupção yhwh a Sodoma e-a Amorá como-jardim- yhwh como-terra- Egito em-sua-comer tristeza-verso-final');
INSERT INTO verses VALUES (330, 1, 13, 11, 'e-ele-escolheu-para-o para-ele ל֗וֹט את todo кїкїр o-Jordão ao-oriente Ló мїкїдем de-cima-de homem de-sobre irmão-dele');
INSERT INTO verses VALUES (331, 1, 13, 12, 'Abrão habitou em-terra-de assim e-вот habitou em-cidades-de ה-кїкїр e-ele-acampou até сїдом-verso-final');
INSERT INTO verses VALUES (332, 1, 13, 13, 'e-homens-de сїдом más e-perversidades para-יהוה muito');
INSERT INTO verses VALUES (333, 1, 13, 14, 'וֽ͏ַיהוָ֞ה disse a אַבְרָ֗ם depois-de se-separou- ל֣וֹט de-a-com-o eleva por-favor os-teus-olhos e-vê de o-lugar que tu nome ao-norte e-o-sul e-o-leste e-o-oeste');
INSERT INTO verses VALUES (334, 1, 13, 15, 'que a todo a-terra a-ti tu viu para-ti a-ele-aqui e-para-a-semente-teu até eternidade');
INSERT INTO verses VALUES (335, 1, 13, 16, 'e-eu-postarei את- a-semente-teu a-terra a-terra que se pode homem para-contar a-terra o-pó a-terra também semente-teu será-maneira');
INSERT INTO verses VALUES (336, 1, 13, 17, 'levantou andarás na-terra para-comprimento-seu e-para-largura-seu que a-ti darei-eu');
INSERT INTO verses VALUES (337, 1, 13, 18, 'e-ele-acampou Abram E-veio e-permaneceu em-carvalhos Mamar-e que em-Hebron e-eben- nome altar la-yhwh:');
INSERT INTO chapters VALUES (14, 1, 14, 24);
INSERT INTO verses VALUES (338, 1, 14, 1, 'e-houve em-os-dias-de Amrafel rei-de Shinar Ariokh rei Elasar Kedorlaomer rei Elão ve-Tidal rei goyim:');
INSERT INTO verses VALUES (339, 1, 14, 2, 'fizeram guerra a bera'' rei sedom e-a birsha rei amora shina''av rei adma veshemaever rei e-rei-de bela'' hi- tsoar');
INSERT INTO verses VALUES (340, 1, 14, 3, 'todo estes juntaram-se a ele mar ele mar do-sal');
INSERT INTO verses VALUES (341, 1, 14, 4, 'dois dez ano serviram a kedarlamémer e-três- doze ano mardou');
INSERT INTO verses VALUES (342, 1, 14, 5, 'e-em-quatro dez ano veio kedarlamémer e-os-reis que com-ele e-feriram a refaim em-o-ashtarot as-cornos e-a os-zuzim em-eles e-את as-terror em-shaveh as-cidades');
INSERT INTO verses VALUES (343, 1, 14, 6, 'e-a o-hori em-o-montes-ram até até o-touro pa-ar-an que sobre o-meadero');
INSERT INTO verses VALUES (344, 1, 14, 7, 'e-voltaram e-vieram a olho ela ela Quades e-feriram a todo os-campos dos-Amalequitas e-também a o-amorreu o-que-habitava em-Hatsotsera de-Tamar');
INSERT INTO verses VALUES (345, 1, 14, 8, 'e-saiu rei-de S''dom e-rei-de Amorá e-melque Admá e-rei-de e-rei-de Belá hia- Tsoar e-vi-yarchu itam guerra be-emek os-sedeis');
INSERT INTO verses VALUES (346, 1, 14, 9, 'a de-dar-la-omer rei e-ilam e-tide-al rei nações e-amrafel rei sin-ar e-arioch rei elasar quatro me-lachim a ha-chamesh');
INSERT INTO verses VALUES (347, 1, 14, 10, 'e-o-vale o-de-sodoma em-as-tendas nas-tendas o-azul e-eles-se-esconderam rei-de sodoma e-amora e-eles-caíram- para-lá e-os-restantes em-ha-herah nassu');
INSERT INTO verses VALUES (348, 1, 14, 11, 've-yikchu a todo rekush sedom ve-amorah e-a todo achlam veyelechu');
INSERT INTO verses VALUES (349, 1, 14, 12, 'e-tomaram a lot e-a rekusho filho-de irmão-de Abrão e-foram e-ele habitou em-Sedom');
INSERT INTO verses VALUES (350, 1, 14, 13, 'E-veio o-fugitivo e-anunciou a-Abram o-hebreu e-ele morando nas-arcas de-Mamera o-amorreu a-chi eshkol e-irm-a-o aner e-eles baalei berit- abram');
INSERT INTO verses VALUES (351, 1, 14, 14, 'E-ouviu abram que nishba irmão-dele ve-yarek a alunos-dele filhos-de casa-seu oito dez e-três centenas e-ele-perseguiu até dan');
INSERT INTO verses VALUES (352, 1, 14, 15, 'e-ele-dividiu em-ela-eles noite ele ele ve-yach-chem e-ele-perseguiu-os até obrigação que de-a-esquerda para-o-damasco');
INSERT INTO verses VALUES (353, 1, 14, 16, 'e-ele-estabeleceu את todo o-bens e-também a lot seu-irmão e-seus-bens ele-devolveu e-também a as-mulheres e-a o-povo');
INSERT INTO verses VALUES (354, 1, 14, 17, 'e-saiu rei-de S''dom li-kra-to a-harei shuvo me-hakhot a kedar- la-oemer e-a os-reis ele com-ele a emeq shaveh ele emeq o rei');
INSERT INTO verses VALUES (355, 1, 14, 18, 'e-rei- justiça rei paz pão pão e-vinho e-ele sacerdote para-o-elohim altíssimo');
INSERT INTO verses VALUES (356, 1, 14, 19, 'e-abraão-benço-ele-o E-disse bendito abram para-o-elohim altíssimo conhe céus e-a-terra');
INSERT INTO verses VALUES (357, 1, 14, 20, 'e-bendito El elyon que de-guarda teu-necessidade em-mão-tua e-ele-deu de-toda decimo de-todo');
INSERT INTO verses VALUES (358, 1, 14, 21, 'E-disse rei-de sodom a Abram dá para-mim a-alma e-o-tesouro toma- para-ti');
INSERT INTO verses VALUES (359, 1, 14, 22, 'E-disse Abrão a rei Sodoma eleva-eu ya-di a yhwh El altíssimo conhe céus e-a-terra');
INSERT INTO verses VALUES (360, 1, 14, 23, 'se de-fio- e-até- costura-de- sapato e-se eu-tomarei de-todo que para-ti e-não dizerás eu enriqueci- a Abram');
INSERT INTO verses VALUES (361, 1, 14, 24, 'por-mim somente que comerão os-jovens e-partilha os-homens que foram comigo Aner Escol e-Mamera eles tomem seu-parto');
INSERT INTO chapters VALUES (15, 1, 15, 21);
INSERT INTO verses VALUES (362, 1, 15, 1, 'depois- as-palavras estes foi ser yhwh a abram dizendo para-dizer a eu אַבְרָ֗ם para-ti escudo-de para-ti muito muito muito');
INSERT INTO verses VALUES (363, 1, 15, 2, 'E-disse אַבְרָ֗ם Adonai yhwh que- tu-darás para-mim e-eu andando Ariri ele Mesheq em-o-casa ele damasco eliezer');
INSERT INTO verses VALUES (364, 1, 15, 3, 'E-disse abram eis para-mim não deste semente e-eis filho-de em-o-casa herdará de-mim');
INSERT INTO verses VALUES (365, 1, 15, 4, 'e-eis palavra-de a-ele dizendo não não você-herdará esta porque mãe que ele de-seus-intestinos ele ele-te-herdará');
INSERT INTO verses VALUES (366, 1, 15, 5, 'e-saiu ele o-em-a-corte E-disse olha-para-o por-favor os-ceus as-estrelas as-estrelas se eles E-disse a-ele E-disse será assim será semente-tua');
INSERT INTO verses VALUES (367, 1, 15, 6, 'e-creu em-yhwh e-pensou-a para-ele justiça');
INSERT INTO verses VALUES (368, 1, 15, 7, 'E-disse a-ele eu yhwh que saí-te luzeiro dos-caldeus para-dar a-ti a a-terra a-esta para-possuí-la');
INSERT INTO verses VALUES (369, 1, 15, 8, 'E-disse Adonai yhwh em-ela eu-saberei que e-ele-me-esposará');
INSERT INTO verses VALUES (370, 1, 15, 9, 'E-disse a-ele toma-a a-mim novilha tripla e-ovelha tripla e-bode tripla e-ave-de-pescoço-branco e-a-cria-verso-final');
INSERT INTO verses VALUES (371, 1, 15, 10, 'e-tomou para-ele a eles estes E-colocou a-elas no-meio E-deu homem não ao-encontro-de companheiro-seu e-a a-ave não depois-');
INSERT INTO verses VALUES (372, 1, 15, 11, 'e-desceu o-pássaro sobre os-cadáveres eles eles Abram');
INSERT INTO verses VALUES (373, 1, 15, 12, 'e-houve o-sol para-vir e-sono caindo sobre Abram e-eis terror escuridão grande caindo sobre-ele');
INSERT INTO verses VALUES (374, 1, 15, 13, 'E-disse a-Abraão conheceu sabendo porque estrangeiro será tua-semente na-terra não a-eles e-os-escravizaram e-oprimam eles quatro centenas anos');
INSERT INTO verses VALUES (375, 1, 15, 14, 'e-também a o-povo que servirão eu eu e-depois-de assim saiam com-a-moeda grande');
INSERT INTO verses VALUES (376, 1, 15, 15, 'e-tu virá a os-teus-avós em-a-paz sepultar-se em-erva boa');
INSERT INTO verses VALUES (377, 1, 15, 16, 'e-geração quarto voltarão aqui-estes que não inteiro iniquidade-de o-amorreu até até-aqui');
INSERT INTO verses VALUES (378, 1, 15, 17, 'e-houve o-sol veio e-erva ser e-eis forno fumo e-luminária fogo que passou entre os-decisões as estas');
INSERT INTO verses VALUES (379, 1, 15, 18, 'no-dia aquele cortou yhwh a Abrão dizendo para-dizer dei dei a a-terra a-esta do-rivoli o-grande até o-rio a-grande rio-de Eufrates');
INSERT INTO verses VALUES (380, 1, 15, 19, 'a o-keini e-a o-qenizi e-a o-primeiro');
INSERT INTO verses VALUES (381, 1, 15, 20, 'e-a o-hitita e-a o-perizzita e-a os-rfaim');
INSERT INTO verses VALUES (382, 1, 15, 21, 'e-a o-amorreu e-a o-canaanita e-a o-gergeseu e-a o-jebuseu');
INSERT INTO chapters VALUES (16, 1, 16, 16);
INSERT INTO verses VALUES (383, 1, 16, 1, 'e-saraia mulher-de abram não deu-à-luz a-ele e-para-ela escrava egyptiana e-nome-de-ela o-estrangeiro');
INSERT INTO verses VALUES (384, 1, 16, 2, 'E-disse sara- a אַבְרָ֗ם eis-que- yhwh retenha-me yhwh de-parir vem- por-favor a serva-meu talvez à-voz-de de-ela E-ouviu Abrão para-a-voz sara-');
INSERT INTO verses VALUES (385, 1, 16, 3, 'e-tomou Sarái esposa-de אַבְרָ֗ם a estrangeira a-egyptia escrava-de-a de-fim dez dois para-estar Abrão e-deu assim e-deu ela a-ele espos-a para-ele para-mulher');
INSERT INTO verses VALUES (386, 1, 16, 4, 'E-veio a a-Gar E-viu que porque ela-concebeu e-ela-se-elevou senhora-a-sua em-seus-olhos-verso-final');
INSERT INTO verses VALUES (387, 1, 16, 5, 'E-disse Sarái a abrãm minha-fúria eu dei eu-deti minha-escrava E-viu que porque ela-concebeu e-eu-levei em-seus-olhos yhwh yhwh entre-mim');
INSERT INTO verses VALUES (388, 1, 16, 6, 'E-disse Abram a eis eis tuas-escrava na-tua-mão faze- para-ela o-bom em-o-suyos e-ele-a-maçou-a sara e-ela-fugiu de-a-frente-de-a');
INSERT INTO verses VALUES (389, 1, 16, 7, 'e-ele-achou-a anjo yhwh sobre olho as-águas no-deserto sobre o-de-o-olho em-a-caminho shur');
INSERT INTO verses VALUES (390, 1, 16, 8, 'E-disse hagar shifchat sara-i ei- mizze baat e-onde E-disse de-diante-de mipnay Sarái eu eu borachat');
INSERT INTO verses VALUES (391, 1, 16, 9, 'E-disse a-ela anjo yhwh volta a gibretekh debaixo debaixo-de mãos-de-a');
INSERT INTO verses VALUES (392, 1, 16, 10, 'E-disse a-ela anjo yhwh multiplicando multiplicarei a semente-te e-não será-contado de-multidão');
INSERT INTO verses VALUES (393, 1, 16, 11, 'E-disse a-ela anjo yhwh eis-a grávida e-parirás filho e-chamarás nome-dele Ismael porque yhwh yhwh a tribulação-te');
INSERT INTO verses VALUES (394, 1, 16, 12, 'e-ele será bode homem sua-mão em-todo e-a-mão todo nele e-sobre face-de todo seus-irmãos morará');
INSERT INTO verses VALUES (395, 1, 16, 13, 'e-chamou nome-de yhwh o-falando tu tu El que porque disse-a também aqui vi depois-de vendo-eu');
INSERT INTO verses VALUES (396, 1, 16, 14, 'sobre chamou chamou para-a-fonte em-Beer para-o-vivo eis eis e-entre santo e-entre em-o-Bared');
INSERT INTO verses VALUES (397, 1, 16, 15, 'e-deleveu a-Gar para-Abram filho E-chamou abram nome- filho-dele que ela-deu-à-luz a-Gar Ismael');
INSERT INTO verses VALUES (398, 1, 16, 16, 'e-abram filho-de oitenta ano e-seis dois em-a-geração-de a-gerar a Ismael para-Abram');
INSERT INTO chapters VALUES (17, 1, 17, 27);
INSERT INTO verses VALUES (399, 1, 17, 1, 'e-houve abram filho-de noventa ano e-ela-será dois yhwh yhwh E-disse a-ele E-disse a-ele eu- El Shaddai andarei diante-de-mim e-serei perfeito');
INSERT INTO verses VALUES (400, 1, 17, 2, 'e-eu-darei a-meu-convenção entre-mim e-entre-tu e-aumentarei te com-muito muito');
INSERT INTO verses VALUES (401, 1, 17, 3, 'e-caiu Abrão sobre perante-ele e-falou com-ele dizendo para-dizer');
INSERT INTO verses VALUES (402, 1, 17, 4, 'eu eis minha-aliança contigo e-serás para-pai multidão goyim:');
INSERT INTO verses VALUES (403, 1, 17, 5, 'e-não será-chamado ainda a o-teu-nome Abram e-era que Abraão porque pai- multidão nações e-te-darei');
INSERT INTO verses VALUES (404, 1, 17, 6, 'e-eu-criarei-te o-te em-muito muito e-eu-te-darei para-nações e-reis de-tu sairão');
INSERT INTO verses VALUES (405, 1, 17, 7, 'e-elevar-ei a a-minha-aliança entre-me e-entre tua-semente o-semente-teu depois-de-tu para-gerações-eles eternidade eternidade a-ti para-ti para-Elohim e-para-a-semente-teu depois-de-tu');
INSERT INTO verses VALUES (406, 1, 17, 8, 'e-darei a-ti e-a-semente-teu depois-de-você com terra terra את todo terra Canaã para-posse eternidade e-eu-serei a-eles para-elohim');
INSERT INTO verses VALUES (407, 1, 17, 9, 'E-disse Elohim a Abraão e-tu a tu você-guardará tu e-a-semente-teu depois-de-você para-gerações-eles');
INSERT INTO verses VALUES (408, 1, 17, 10, 'esta de-meu-conven-to que vocês-guard-arão entre-mim e-entre-vós e-entre tua-semente depois-de-ti circuncidar-ei a-vós todo macho');
INSERT INTO verses VALUES (409, 1, 17, 11, 'e-vocês-ser-virão-circuncidados את de-carne vossa-prepúcio e-será para-sinal aliança entre-mim-e-vocês e-entre-voces');
INSERT INTO verses VALUES (410, 1, 17, 12, 'e-filho-de oito dias a-vós a-vós todo macho para-gerações-de-vocês nascido de-toda e-compra-de- prata não filho-de ele que não de-semente-teu ela');
INSERT INTO verses VALUES (411, 1, 17, 13, 'circuncidado-ele circuncidará nascido casa-teu e-compra-de de-prata-teu e-será em-o-meu-convenção em-a-carne-de-vós para-o-convenção eternidade');
INSERT INTO verses VALUES (412, 1, 17, 14, 'e-atornado macho macho não ser-circuncidado a em-a-carne atornamento-dele e-ser-cortado aquela a-essa de-o-povo-dele a aliança-minha hipar-');
INSERT INTO verses VALUES (413, 1, 17, 15, 'E-disse Elohim a Abraão Sarái eshta-kha- não tiqra- que shema-ha- sara-i- porque sarah- shema-ha-');
INSERT INTO verses VALUES (414, 1, 17, 16, 'veberakhti- a-ela e-tambem dei mimenah- a-ti filho veberakhtihah- e-ser-ia para-povos reis-de povo-es de-a-ela ser-ão');
INSERT INTO verses VALUES (415, 1, 17, 17, 'e-caiu Abraão sobre sua-face E-disse E-disse no-cor-do o-grande de-cem- ano ser-nascido e-se-que- Sara filha-de- noventa ano dará-a-luz.');
INSERT INTO verses VALUES (416, 1, 17, 18, 'E-disse Abraão a o-Elohim se Ismael viverá diante-de-você.');
INSERT INTO verses VALUES (417, 1, 17, 19, 'E-disse Elohim mas Sara mulher-tua gerando a-ti filho e-lerás a nome-de-ele Isaque e-elevar-ei a em-meu-convenção eternidade para-o-convenção eternidade para-semente-dele atrás-dele');
INSERT INTO verses VALUES (418, 1, 17, 20, 'e-a-izmael ouvi-teu eis abençoei-te a-ele ele a-ele ele a-ele ele muito muito dez príncipes gerará e-dar-lhe-e-o para-povo grande');
INSERT INTO verses VALUES (419, 1, 17, 21, 'e-a aliança-minha levantarei a Isaque a-ti dará-a-geração para-ti sara ao-festival esta na-ano a-seguinte');
INSERT INTO verses VALUES (420, 1, 17, 22, 'E-terminou para-falar com-ele e-subiu Elohim de-cima-de Abraão');
INSERT INTO verses VALUES (421, 1, 17, 23, 'E-tomou Abraão a ismael filho-seu e-a todo filhos-de em-a-casa-seu e-את todo de-adquirir com-prata-seu todo macho em-homens-de casa Abraão o-dia a de-carne da-uncircuncisão-seu [אִתּ֖וֹ] o-dia esta como palavra com-ele Elohim');
INSERT INTO verses VALUES (422, 1, 17, 24, 'e-abraãm filho-de noventa e-que-nove ano em-o-mol-o de-a-carne a-uncircuncisão-dele');
INSERT INTO verses VALUES (423, 1, 17, 25, 'e-Ismael seu-filho filho-de três dez ano em-o-mol-o את de-a-carne a-uncircuncisão-dele');
INSERT INTO verses VALUES (424, 1, 17, 26, '[בְּעֶ֙צֶם֙] o-dia esta foi-mol-to Abraão e-Ismael filho-seu');
INSERT INTO verses VALUES (425, 1, 17, 27, 'e-todo homens-de be-to- ye-lid casa u-miqnat- prata de-junto-de filho-de ne-char nim-molu com-ele');
INSERT INTO chapters VALUES (18, 1, 18, 33);
INSERT INTO verses VALUES (426, 1, 18, 1, 'E-viu a-ele yhwh be-e-lo-nei- ma-mar-e-a e-ele habitou pe-tach- ha-o-hel o-dia o-dia');
INSERT INTO verses VALUES (427, 1, 18, 2, 'va-yiss-a os-seus-olhos E-viu e-eis três homens estando-plantados sobre-ele E-viu e-correu para-eles da-porta a-tenda e-prostrou-se para-terra');
INSERT INTO verses VALUES (428, 1, 18, 3, 'E-disse Adonai se por-favor encontrei graça em-tua-olho a de-cima-de passes de-sobre servo-teu');
INSERT INTO verses VALUES (429, 1, 18, 4, 'será-tirado- por-favor pouco- águas e-lavem-se debaixo a-árvore em-baixo-de o-árvore:');
INSERT INTO verses VALUES (430, 1, 18, 5, 'e-ele-tomarei de-o pão e-vos-alimentarão para-vós atrás-de vós-passareis porque sobre assim vós-passastes sobre servo-de-vós e-disseram assim vós-fará como-que dibartā׃');
INSERT INTO verses VALUES (431, 1, 18, 6, 'va-yemahēr Abraão ha-ohelah a E-disse E-disse mahari três seim qemakh sōlet lūshi va-ʿāṣī ʿugōt׃');
INSERT INTO verses VALUES (432, 1, 18, 7, 'e-a o-bovino correu E-tomou E-tomou filho-de manhã E-colocou e-bom E-deu a ele e-ele-pressuroso para-fazer a-ele');
INSERT INTO verses VALUES (433, 1, 18, 8, 'E-tomou gordura e-leite e-filho-de o-bovino que E-colocou E-deu em-frente-de-eles e-ele debaixo a-árvore debaixo-de a-árvore e-eles-comeram');
INSERT INTO verses VALUES (434, 1, 18, 9, 'e-disseram onde שָׂרָ֣ה mulher-tua E-disse E-disse eis');
INSERT INTO verses VALUES (435, 1, 18, 10, 'E-disse voltaram voltarei a-ti como tempo-de vivente e-eis- filho a-Sara mulher-tua e-Sara ouvindo-a porta da-tenda e-ele atrás-dele');
INSERT INTO verses VALUES (436, 1, 18, 11, 'e-Abraão e-Sara idosos vêm em-os dias cessou- para-ser- para-a-Sara- caminho- como-nasceram-');
INSERT INTO verses VALUES (437, 1, 18, 12, 'e-risou- Sara- no-centro-de-a-sua- dizendo depois-de quando-fui-menina- foi- para-mim tempo-o e-o-meu-adonai velho');
INSERT INTO verses VALUES (438, 1, 18, 13, 'E-disse yhwh a Abraão por-que este-o risou-a dizendo para-dizer o-nariz realmente a-criança e-eu envelheci-eu');
INSERT INTO verses VALUES (439, 1, 18, 14, 'seria-maravilhoso de-יהוה palavra para-a-festa retornarei a-você agora vivente e-a-Sarah filho');
INSERT INTO verses VALUES (440, 1, 18, 15, 'e-ela-negou-se Sarah para-dizer dizendo não que que e-ele-disse não porque riu-se');
INSERT INTO verses VALUES (441, 1, 18, 16, 'e-eles-se-levantaram de-lá os-homens e-eles-viram sobre face-de Sodoma e-Abraão andou com-eles para-enviá-los');
INSERT INTO verses VALUES (442, 1, 18, 17, 'e-yhwh disse o-tapando eu de-Abraão que eu fez');
INSERT INTO verses VALUES (443, 1, 18, 18, 'e-Abraão era será para-povo grande e-grande e-os-bendecem nele todo nações-de a-terra');
INSERT INTO verses VALUES (444, 1, 18, 19, 'que o-conheceu-o a-fim-de que ele-comanda a seus-filhos e-a sua-casa o-caminho-de yhwh caminho yhwh para-fazer justiça e-juízo yhwh traga-o yhwh sobre Abraão a que palavra sobre-ele');
INSERT INTO verses VALUES (445, 1, 18, 20, 'E-disse yhwh grita- sodoma e-amora porque multiplicai que porque muito muito');
INSERT INTO verses VALUES (446, 1, 18, 21, '-irei agora e-eu-verei da-grita- a-vindo-a para-mim fizeram -toda e-se não -saberei');
INSERT INTO verses VALUES (447, 1, 18, 22, 'e-viraram de-lá os-homens e-foram -sodoma e-abraãm ainda-ele ficou-em-pé diante-de yhwh');
INSERT INTO verses VALUES (448, 1, 18, 23, 'e-veio-aproximar-se Abraão E-disse o-nascer-do-sol destruirás justo com perverso');
INSERT INTO verses VALUES (449, 1, 18, 24, 'talvez haja cinquenta justos no-meio-de a-cidade o-nariz você-removerá e-não você-levará para-o-lugar para-fim-de cinquenta os-retos que na-sua-entre');
INSERT INTO verses VALUES (450, 1, 18, 25, 'que-não para-você de-fazer como-dizer este para-matar just-o com perverso-o e-acontecerá como-just-o como-perverso-o abominável para-ti que-julga todo não não faz-o juízo');
INSERT INTO verses VALUES (451, 1, 18, 26, 'E-disse yhwh se encontro em-Sodoma cinquenta no-meio-de em-meio-de a-cidade e-elevar-ei para-todo o-lugar por-elas');
INSERT INTO verses VALUES (452, 1, 18, 27, 'e-respondeu Abraão E-disse eis-que- por-favor eu-jurei para-falar a pó e-eu poeira e-fuligem');
INSERT INTO verses VALUES (453, 1, 18, 28, 'talvez eles-faltam cinquenta os-justos cinco destruirás em-cinco a E-disse não E-disse não destruirei-eu se encontrarei nome quarenta e-cinco');
INSERT INTO verses VALUES (454, 1, 18, 29, 'e-continuou ainda para-falar a-ele E-disse talvez eles-encontrarão nome quarenta E-disse não eu-farei por-causa-de as-quarenta');
INSERT INTO verses VALUES (455, 1, 18, 30, 'E-disse a por-favor se-irar a-o-Adonai e-e-falarei ou-mas eles-se-encontrarão nome E-disse não não eu-farei se eu-acharei nome trinta');
INSERT INTO verses VALUES (456, 1, 18, 31, 'E-disse eis-a por-favor eu-jurei para-falar a Adonai tal-mas encontrem-eles E-disse não E-disse não destruirei-eu por-causa-de os-vinte');
INSERT INTO verses VALUES (457, 1, 18, 32, 'E-disse a por-favor arderá ao-יהוה e-falarei-eu somente- esta-vez tal-mas encontrem-eles E-disse não E-disse não destruirei por-causa-de a-dez');
INSERT INTO verses VALUES (458, 1, 18, 33, 'E-andou yhwh como-que terminou para-falar a Abraão e-Abraão retornou para-lugar-dele');
INSERT INTO chapters VALUES (19, 1, 19, 38);
INSERT INTO verses VALUES (459, 1, 19, 1, 'e-vieram segundo os-anjos Sodoma na-atardecer e-Lote habitou na-porta-de Sodoma e-viu- a-Lot E-levantou para-eles e-prostrou-se Apaim para-terra');
INSERT INTO verses VALUES (460, 1, 19, 2, 'E-disse eis por-favor- Adonai afastem-se por-favor a casa vossos-servos e-pernoitem e-lavem vossos-pés e-vos-levantareis e-vós-andareis para-a-vossa-caminho que não porque na-parteira e-pernoitareis');
INSERT INTO verses VALUES (461, 1, 19, 3, 'e-ele-precipitar-se muito muito a-ele para-ele e-vieram a a-eles E-fez para-eles banquete e-pães-açucarados fazer-cozido e-eles-comeram');
INSERT INTO verses VALUES (462, 1, 19, 4, 'ainda-não vos-deitareis e-os-homens a-cidade homens-de Sodoma viraram-se sobre a-casa do-jovem e-até até-o-vieiro todo o-povo de-extremidade');
INSERT INTO verses VALUES (463, 1, 19, 5, 'e-eles-chamaram a a-Lot a-ele a-ele onde os-homens que a-noite a-ti a-noite tire-os eles e-sabemos a-eles');
INSERT INTO verses VALUES (464, 1, 19, 6, 'e-ele-saiu a-para-eles Ló o-porta e-a-parteira fechar atrás-dele');
INSERT INTO verses VALUES (465, 1, 19, 7, 'E-disse a por-favor meus-irmãos voces-griteis');
INSERT INTO verses VALUES (466, 1, 19, 8, 'eis por-favor para-mim duas filhas que não souberam homem tirei- agora as-elas a-vós e-façam a-elas como-bom em-os-vossos-olhos somente para-os-homens o-elohim a fazeis palavra porque sobre assim entraram em-a-sombra de-mim');
INSERT INTO verses VALUES (467, 1, 19, 9, 'e-disseram vem- aqui-e e-disseram o-primeiro veio para-habitar e-julgou julgamento agora a-ti para-ti deles e-imploraram o-homem muito muito e-se-aproximaram para-partir a-porta');
INSERT INTO verses VALUES (468, 1, 19, 10, 'e-eles-deram os-homens a a-mão-dele e-eles-trouxeram a lot a-eles a-casa e-a a-porta fecharam');
INSERT INTO verses VALUES (469, 1, 19, 11, 'e-a os-homens que entrada-de a-casa feriram em-os-sabores de-pequeno e-até grande e-ele-quiseram para-a-capturar o-porta');
INSERT INTO verses VALUES (470, 1, 19, 12, 'e-disseram os-homens a Lot até quem- para-ti aqui noivo e-tudo e-filhas-tuas e-todo que para-ti na-cidade tire- de o-lugar');
INSERT INTO verses VALUES (471, 1, 19, 13, 'porque destruidores nós a o-lugar esta porque yhwh clamação-deles yhwh face-de yhwh e-ele-nos-enviou yhwh para-destruí-la');
INSERT INTO verses VALUES (472, 1, 19, 14, 'e-saiu Lot e-ele-falou- a genro-seus- tomadores filhas-dele E-disse E-disse saiam de o-lugar esta porque yhwh yhwh e-houve a-cidade E-foi como-escarnecendo em-olhos-de noivos-dele');
INSERT INTO verses VALUES (473, 1, 19, 15, 'e-como a-alvorada subir e-eles-exortaram os-mensageiros em-lote dizendo levantou toma את- mulher-teu e-a duas filhas-teu que-achadas para-que-não aumentarás em-perversidade a-cidade');
INSERT INTO verses VALUES (474, 1, 19, 16, 'e-adiou-se e-fortaleceram os-homens em-mão-seu e-em-mão- esposa-dele e-em-a-mão duas em-as-filhas-dele em-a-mercy yhwh sobre-ele e-eles-saíram-no-le e-eles-deitaram-no-le de-fora para-a-cidade');
INSERT INTO verses VALUES (475, 1, 19, 17, 'e-houve como-saíram-no-los eles o-outside E-disse foi-fugido sobre a-tua-vida a olhar-vi de-te e-a estares-estarás em-todo o-campo a-montanha-aquela escapares-escapas-te para-que-não serás-acrescentado-você-será');
INSERT INTO verses VALUES (476, 1, 19, 18, 'E-disse Ló a-eles a por-favor Adonai');
INSERT INTO verses VALUES (477, 1, 19, 19, 'eis encontrou encontrou-encontra seu-escravo-teu-servo favor-graça em-tuas-olhos e-magnificaste gratidão-teu que comigo comigo para-viver a não e-eu não posso para-fugir a-montanha para-que-não você-se-apaixona-me o-mal e-eu-morrerei');
INSERT INTO verses VALUES (478, 1, 19, 20, 'eis por-favor a-cidade esta-coisa perto para-Nus para lá e-ela pequena escapar-se por-favor ali não ela ela e-viva alma-de-mim');
INSERT INTO verses VALUES (479, 1, 19, 21, 'E-disse a-ele eis elevado-eu faces-tua também para-a-palavra esta para-não vira-teu a a-cidade que dibartā׃');
INSERT INTO verses VALUES (480, 1, 19, 22, 'apressado escapou-seu ali que não posso para fazer palavra até vindo-teu para-lá chamou assim chamou nome-de a-cidade zombaria');
INSERT INTO verses VALUES (481, 1, 19, 23, 'o-sol sair sobre a-terra e-Lot veio Tsorah-ela');
INSERT INTO verses VALUES (482, 1, 19, 24, 'e-yhwh fez-chover sobre Sedom e-sobre Amora gafrit yhwh de-a yhwh de os-céus');
INSERT INTO verses VALUES (483, 1, 19, 25, 'e-vahaphokh a ha-arim o-Elohim e-a tudo-de o-campo e-את todo a-terra as-cidades e-florescente a-terra');
INSERT INTO verses VALUES (484, 1, 19, 26, 'e-viu mulher-sua de-a-trás-dele e-foi estabelecido sal');
INSERT INTO verses VALUES (485, 1, 19, 27, 'e-se-levantou Abraão no-manhã a o-lugar que ficou-em-pé yhwh a face-de yhwh');
INSERT INTO verses VALUES (486, 1, 19, 28, 'e-ele-viu sobre face-de Sodoma e-amarra terra todo E-viu terra subir E-viu a-terra subiu fumo a-terra como-fumo o-ferreiro');
INSERT INTO verses VALUES (487, 1, 19, 29, 'e-houve em-destruição Elohim a cidades-de ה-кїкїр e-lembrou Elohim a Abraão e-ele-mandou a Lote de-meio-de a-conversão em-conversão a as-cidades que habitou nelas Loth-:');
INSERT INTO verses VALUES (488, 1, 19, 30, 'e-subiu lot de-Mitzpah e-sentou na-montanha e-duas filhas-dele com-ele que temer para-habitar em-Mitzpah e-habitou na-caverna ele e-dois filhas-dele');
INSERT INTO verses VALUES (489, 1, 19, 31, 'E-disse a-primogênita a a-pequena nosso-pai velho e-homem não-há na-terra para-vir sobre-nós ao-modo-de todo a-terra');
INSERT INTO verses VALUES (490, 1, 19, 32, 'vem que-nos-bebamos a nosso-pai vinho e-nos-deitaremos com-ele e-viveremos de-no-pai semente');
INSERT INTO verses VALUES (491, 1, 19, 33, 'e-vos-deram-a-beber a de-seus-pais vinho ele ele e-ela-veio a-primeira e-ela-deitou a seu-pai e-não conheceu em-o-seu-dormir');
INSERT INTO verses VALUES (492, 1, 19, 34, 'e-aconteceu de-amanhã E-disse a-primeira a a-menor eis eu-deitei ontem a pai-meu beberemos vinho também a-noite e-vem-i deita-te com-ele e-nos-viva d-ele-o-no-s zera-.');
INSERT INTO verses VALUES (493, 1, 19, 35, 'e-vos-bebeu-a também na-noite a-esse a o-pai-deles vinho e-levantou-se a-menor e-ela-deitou com-ele e-não conheceu em-o-seu-dormir e-em-a-sua-levantar');
INSERT INTO verses VALUES (494, 1, 19, 36, 'e-ela-concebeu-as duas-de filhas-de Ló de-seus-pais');
INSERT INTO verses VALUES (495, 1, 19, 37, 'ela-deu-a-luz- a-primeira-nascida filho e-chamou nome-de-ele Moabe ele avi- Moabe até o-dia');
INSERT INTO verses VALUES (496, 1, 19, 38, 'e-ela-menor também ela-foi filho filho e-chamou nome-de-ele ele meu-povo ele pai-de filhos-de Amom até o-dia');
INSERT INTO chapters VALUES (20, 1, 20, 18);
INSERT INTO verses VALUES (497, 1, 20, 1, 'e-ele-partiu de-aqui Abraão terra-para o-sul e-habitou entre e-entre e-entre Shur e-ele-estabeleceu-se em-Berseba');
INSERT INTO verses VALUES (498, 1, 20, 2, 'E-disse Abraão a Sarah mulher-sua ela ela e-enviou Avimelech rei E-tomou E-tomou a Sarah');
INSERT INTO verses VALUES (499, 1, 20, 3, 'E-veio Elohim a Avimelech a-noite E-disse a-ele para-ele veja-você morreu sobre a-mulher que tomaste e-ela em-sementeira marido');
INSERT INTO verses VALUES (500, 1, 20, 4, 'e-Avimeléc não qarav para-ela E-disse Adonai ha-goy também justo taharog');
INSERT INTO verses VALUES (501, 1, 20, 5, 'não-é-que ele palavras-de a-mim ela ele ve-hi- também ele amara achi ele b''tam- esta ubeniqyon kapay fiz esta-ali');
INSERT INTO verses VALUES (502, 1, 20, 6, 'E-disse a-ele o-Alohim em-o-sonho também eu conheci que com-a-sinceridade para-teu-coracao fizeste esta e-eu-ocultei também eu de-te de-pecado para-mim sobre assim não eu-deti-te para-sair a-ela');
INSERT INTO verses VALUES (503, 1, 20, 7, 'e-agora retorna esposa-de o-homem ele profeta ele e-ele-orará em-teu-lado e-vive e-se não-és morrerás tu porque morte-de morres tu e-todo que para-ti');
INSERT INTO verses VALUES (504, 1, 20, 8, 'e-ele-se-levantou Avimélek na-manhã E-chamou para-todo seus-servos e-ele-falou a todo as-palavras estes muito e-eles-tremeliram os-homens muito');
INSERT INTO verses VALUES (505, 1, 20, 9, 'E-chamou Avimeléc a-Abraão E-disse a-ele de-o- o-fez-tu a-nós para-ti pecado-eu para-ti porque trouxe-tu sobre-mim e-sobre reinado-meu pecado-a grande comigo que não se-fazam fiz-te- comigo-');
INSERT INTO verses VALUES (506, 1, 20, 10, 'E-disse Avimelech a Abraão que que porque fiz-te- a a-palavra a-esta');
INSERT INTO verses VALUES (507, 1, 20, 11, 'E-disse Abraão que disse-ei- somente não-há temor-de Elohim no-lugar- esta e-matar-me- sobre palavra minha-esposa-');
INSERT INTO verses VALUES (508, 1, 20, 12, 'e-também verdadeiramente- irmã- ela pai-meu não mas- não filha-de mim-i e-ela-tornou-se para-mim para-mulher');
INSERT INTO verses VALUES (509, 1, 20, 13, 'e-houve como-que hit-etu a-mim Elohim de-casa-de avi e-disse para-ela este chas-de-khakh que ta-as-i comigo a todo o-lugar que nav-oa ali dize- ele achi ela');
INSERT INTO verses VALUES (510, 1, 20, 14, 'E-tomou avi-melakh ovelhas u-vakar e-servos e-escravas E-colocou le-abr-a-ham e-ele-estabeleceu a-ele a Sarah esposa-dele');
INSERT INTO verses VALUES (511, 1, 20, 15, 'E-disse Abimélek eis minha-terra diante-de-ti em-bom nos-teus-olhos retornou');
INSERT INTO verses VALUES (512, 1, 20, 16, 'e-a-Sara disse eis dei mil prata a-seu-irmão eis ele para-ti cobertura a-todo para-todo que contigo e-a todo e-em-face-dele-verso');
INSERT INTO verses VALUES (513, 1, 20, 17, 'e-ele-orou Abraão a o-Elohim e-curou Elohim a Avimélek e-a es-toa e-ama-hot-aio ve-yel-edu');
INSERT INTO verses VALUES (514, 1, 20, 18, 'porque atzor yhwh yhwh por-causa-de todo ventre para-casa-de Avimélek sobre palavra sarah- mulher-de Abraão');
INSERT INTO chapters VALUES (21, 1, 21, 34);
INSERT INTO verses VALUES (515, 1, 21, 1, 've-YHVH pakad a sarah- como-que disse yhwh yhwh les-Sarah como-que palavra');
INSERT INTO verses VALUES (516, 1, 21, 2, 've-tahar e-deu-a שָׂרָ֧ה para-Abraão filho para-seus-idades ao-tempo que ele a-ele Elohim');
INSERT INTO verses VALUES (517, 1, 21, 3, 'E-chamou Abraão את- nome- seu-filho que-nasceu- para-ele que deu-a- para-ele sarah- Isaque');
INSERT INTO verses VALUES (518, 1, 21, 4, 'e-circuncidou Abraão a Isaque seu-filho filho-de oitavo dias ele ordenou a-ele Elohim');
INSERT INTO verses VALUES (519, 1, 21, 5, 'e-Abraão filho-de cem ano a-ele a-ele את Isaque filho-seu');
INSERT INTO verses VALUES (520, 1, 21, 6, 'E-disse Sara risada fez para-mim Elohim todo o-que-ouve para-mim');
INSERT INTO verses VALUES (521, 1, 21, 7, 'E-disse quem falou a-Abram amamentou-a filhos Sarah porque nasci- filho em-seus-idades');
INSERT INTO verses VALUES (522, 1, 21, 8, 'e-cresceu o-menino e-ele-criou E-fez Abraão de-bebida grande em-dia ele-criou a Isaque');
INSERT INTO verses VALUES (523, 1, 21, 9, 'E-viu Sara את- filho-de o-habitante a-egípcia que ela-deu-à-luz para-Abrão que-zombava-se');
INSERT INTO verses VALUES (524, 1, 21, 10, 'E-disse a-Abrão expeliu a-ama a-esta e-a que não não herdará filho-de a-ama a-esta com filhos-de com Isaque');
INSERT INTO verses VALUES (525, 1, 21, 11, 'e-mau a-palavra muito em-olhos-de Abraão sobre adorações filho-seu');
INSERT INTO verses VALUES (526, 1, 21, 12, 'E-disse Elohim a Abraão a será-mau em-olhos-teus sobre o-jovem e-sobre serva-tua todo que dizerás que sarah- será-chamada a-ti porque em-Isaque será-chamado para-ti semente');
INSERT INTO verses VALUES (527, 1, 21, 13, 'e-também a filho-de a-ama que tua-semente ele a-semente-teu ela');
INSERT INTO verses VALUES (528, 1, 21, 14, 'e-ele-levantou-se Avraam-separado em-a-manhã e-tomou pão e-sopa águas E-colocou a da-criança nome sobre seio-a-seu e-a o-menino e-ele-mandou-a-a e-ela-partiu-se e-ela-permaneceu em-o-deserto em-Beer sete');
INSERT INTO verses VALUES (529, 1, 21, 15, 'e-eles-terminaram as-águas de a-iração e-ela-jogou debaixo o-menino sob um o-silvestres-verso');
INSERT INTO verses VALUES (530, 1, 21, 16, 'e-ela-andou e-ela-sentou-se para-ela de-a-frente-de o-longe como-estacas arco que disse-a a vejo-eu em-morte-de o menino e-ela-sentou-se em-frente e-ela-alçou-a a de-a-sua e-ela-chorou-eu');
INSERT INTO verses VALUES (531, 1, 21, 17, 'E-ouviu Elohim a voz-de E-chamou E-chamou anjo-de Elohim a Hagar E-disse os-céus E-disse para-ela que para-a Hagar a temas porque ouviu Elohim a voz-que o-menino em-o-que ele-é nome');
INSERT INTO verses VALUES (532, 1, 21, 18, 'levanta-te e-leva a o jovem e-forte-te a mão-tua nele porque para-povo grande eu-o-colocarei');
INSERT INTO verses VALUES (533, 1, 21, 19, 'e-ele-abriu Elohim a E-viu e-ela-viu poço águas e-ela-andou e-cheiou águas o-caldeirao águas e-ela-deu-a-beber a o-jovem');
INSERT INTO verses VALUES (534, 1, 21, 20, 'e-houve Elohim a o-menino e-ele-cresceu e-habitou e-houve E-foi multiplicai flecha-verso');
INSERT INTO verses VALUES (535, 1, 21, 21, 'e-habitou em-deserto-de paraan e-tomou sua-mãe sua-mae mulher de-terra-de Egito');
INSERT INTO verses VALUES (536, 1, 21, 22, 'e-aconteceu em-o-tempo aquela E-disse avimalek e-Pifoc príncipe-de tzava-o dizendo Avraham para-dizer Elohim im-mekha em-todo que tu fez');
INSERT INTO verses VALUES (537, 1, 21, 23, 'e-agora hisheva-a a-mim be-Elohim elas se tishqor para-mim ul-nini ul-nechdi khased que asiti comigo farás comigo e-com- a-terra que moraste nela');
INSERT INTO verses VALUES (538, 1, 21, 24, 'E-disse Abraão eu jures-me');
INSERT INTO verses VALUES (539, 1, 21, 25, 'e-confrontará Abraão a Avimélek sobre blasfêmias poço as-águas que despojaram servos-de Avimélek');
INSERT INTO verses VALUES (540, 1, 21, 26, 'E-disse Avimélek não soube quem fez a a-coisa esta e-também a-mim não eu não e-também eu o-dia ouvi para-não o-dia');
INSERT INTO verses VALUES (541, 1, 21, 27, 'E-tomou Abraão ovelhas e-gado E-colocou a-Avimélek e-eles-cortaram dois-deles em-brisa');
INSERT INTO verses VALUES (542, 1, 21, 28, 'e-ele-estabeleceu Abraão a sete de-cordeiros a-o-rebanho para-separadamente-deles');
INSERT INTO verses VALUES (543, 1, 21, 29, 'E-disse Avimelech a Abraão que eis-aqui sete de-cordeiros os-estes que você-estabeleceu para-separadamente-aqui');
INSERT INTO verses VALUES (544, 1, 21, 30, 'E-disse que a sete ovelhas-meninas tome-a de-mim por-causa-de será- que para-assembléia porque cavou-eu a a-fonte a esta');
INSERT INTO verses VALUES (545, 1, 21, 31, 'sobre chamou chamou para-o-lugar o-aquele poço que porque nome juraram-eles dois-deles');
INSERT INTO verses VALUES (546, 1, 21, 32, 'e-cortaram berith bebaer sete E-levantou abimelakh upikhol príncipe-de tseva''o e-eles-retornaram a terra filisteus');
INSERT INTO verses VALUES (547, 1, 21, 33, 'E-plantou eshel bebaer sete vayikra- nome yhwh yhwh eternidade eternidade');
INSERT INTO verses VALUES (548, 1, 21, 34, 'vayagar Abraão em-terra-de Filisteus dias muitos');
INSERT INTO chapters VALUES (22, 1, 22, 24);
INSERT INTO verses VALUES (549, 1, 22, 1, 'e-houve outro as-palavras os-estes vehaelohim tentou a E-disse a-ele para-ele E-disse E-disse eis-me');
INSERT INTO verses VALUES (550, 1, 22, 2, 'E-disse toma por-favor a em-o-teu-filho a o-teu-único que amaste a Isaque e-vai-a sobre a terra o-montanha-da-Providência e-ele-o-sube nome para-oferta sobre um os-montes que disse para-ti');
INSERT INTO verses VALUES (551, 1, 22, 3, 'e-ele-se-levantou Abraão no-bom-dia e-ele-faz-força a E-tomou E-tomou a segundo os-jovens-seus com-ele e-a Isaque filho-seu e-ele-abre árvores-de a-subida E-levantou E-andou a o-lugar que palavras-de para-ele Elohim');
INSERT INTO verses VALUES (552, 1, 22, 4, 'no-dia o-terceiro e-ele-leva Abraão a E-viu E-viu a o-lugar de-longe:');
INSERT INTO verses VALUES (553, 1, 22, 5, 'E-disse Abraão a os-jovens-seus sentai para-vós aqui com o-jumento e-eu e-o-noviciado venhamos até כֹּ֑ה e-voltaríamos a-vós');
INSERT INTO verses VALUES (554, 1, 22, 6, 'E-tomou Abraão a árvores-de a-oferta e-pôs sobre E-tomou seu-filho E-tomou em-mão-de-ele a o-fogo e-a a-que-devora e-caminharam dois-deles juntos-verso');
INSERT INTO verses VALUES (555, 1, 22, 7, 'E-disse Isaque a seu-pai E-disse E-disse E-disse E-disse hineni- E-disse eis eis a-foi e-a-senhos e-onde o-cordeiro para-holocausto');
INSERT INTO verses VALUES (556, 1, 22, 8, 'E-disse Abraão Elohim ver- para-ele o-cordeiro para-oferta filhos-de e-caminharam dois-deles juntos-verso');
INSERT INTO verses VALUES (557, 1, 22, 9, 'e-vieram a o-lugar que palavras-de E-edificou a-Elohim e-construiu nome Abraão a o altar e-arranjou a os-madeiras ele a Isaque seu-filho e-ele-colocou ele-o sobre o altar de-acima para-os-árvores:');
INSERT INTO verses VALUES (558, 1, 22, 10, 'e-estendeu Abraão a E-tomou E-tomou a a-que-devora para-sacrificar a filho-seu');
INSERT INTO verses VALUES (559, 1, 22, 11, 'E-chamou a-ele mensageiro-de yhwh de E-disse E-disse Avraam-separado Abraão E-disse eis-me');
INSERT INTO verses VALUES (560, 1, 22, 12, 'E-disse a você-mandará mão-tua a a-ele e-a que para-ele alguma que agora soube tu temor Elohim tu e-não guardaste a em-o-seu-filho a o-único-teu de-mim');
INSERT INTO verses VALUES (561, 1, 22, 13, 'e-ele-leva Abraão a E-viu E-viu e-eis- a-javali atrás-de foi-agarrado em-o-teu-caminho com-as-sua-velhas E-tomou Abraão E-tomou a debaixo e-ele-alçou-o para-oferta em-baixo-de filho-seu');
INSERT INTO verses VALUES (562, 1, 22, 14, 'E-chamou Abraão nome-de o-lugar yhwh יהוה ele-verá que ser-dito o-dia em-monte-de yhwh ser-visto');
INSERT INTO verses VALUES (563, 1, 22, 15, 'E-chamou anjo yhwh a Abraão segundo de os-céus');
INSERT INTO verses VALUES (564, 1, 22, 16, 'E-disse em-mi eu-jurei oráculo-de que porque porque que tu-fizeste a a-coisa esta e-não cortaste a em-teu-filho a único-teu');
INSERT INTO verses VALUES (565, 1, 22, 17, 'porque abençoou ab-rei-te-o multiplicarei a-rbe את- zera-ka ke-kokhevei os-céus ve-kah-hol o-mar sobre tua-semente ha-yam e-inheritará zera-ka את portão-de oyevav');
INSERT INTO verses VALUES (566, 1, 22, 18, 'e-serão-benditos em-o-sêmen-teu todo de-povos a-terra por-causa-de que ouviste em-a-voz-minha');
INSERT INTO verses VALUES (567, 1, 22, 19, 'e-ele-retornou Abraão a os-jovens-seus e-ele-levantaram-se e-caminharam juntos a poço sete e-habitou Abraão em-a-fonte sete');
INSERT INTO verses VALUES (568, 1, 22, 20, 'e-houve depois-de as-palavras os-estes e-ele-foi-dito a-Abraão dizendo eis filha-que-dá-a-luz malkah também ele filhos para-nachor irmão-teu');
INSERT INTO verses VALUES (569, 1, 22, 21, 'a Uz primogênito-seu e-a booz irmão-dele e-a qemu-el pai-de aram');
INSERT INTO verses VALUES (570, 1, 22, 22, 'e-a kesed e-a hazo e-a pildash e-a yidlaf e-a Betuel-');
INSERT INTO verses VALUES (571, 1, 22, 23, 'e-Betuel dar-à-luz a Rebeca Estas estes deu-à-luz milcha para-Nahor irmão-de Abraão');
INSERT INTO verses VALUES (572, 1, 22, 24, 'e-sua-concubina e-nome-dela Reuma ela-deu-a-luz- também ela-foi a Geraque e-a Gacham e-a Tachash e-com ma''akah');
INSERT INTO chapters VALUES (23, 1, 23, 20);
INSERT INTO verses VALUES (573, 1, 23, 1, 'e-foram chayyei Sara cem ano e-vinte ano vesheva'' dois segundo vidas- Sarah');
INSERT INTO verses VALUES (574, 1, 23, 2, 'vatamat Sarah bekiryat quatro ela Hebrom na-terra assim E-veio Abraão lesapod lesharah velibkothah');
INSERT INTO verses VALUES (575, 1, 23, 3, 'E-levantou Abraão de-cima-de face-de morto-o e-falou a dizendo pecado-a para-dizer');
INSERT INTO verses VALUES (576, 1, 23, 4, 'estrangeiro- eu eu com-vós dai-vos para-mim posse-de sepultura-a com-vocês e-eu-enterrarei-a morto-eu de-perante-mim-versículo-final');
INSERT INTO verses VALUES (577, 1, 23, 5, 'e-eles-responderam filhos-de hate dizendo a-ele dizendo a-ele');
INSERT INTO verses VALUES (578, 1, 23, 6, 'ouvir-nos Adonai príncipe Elohim tu tu em-seleção sepulcros-nossos sepultar a teu-morto homem nós a seu-sepulcro não terminará de-vós do-túmulo da-morte-de-vós');
INSERT INTO verses VALUES (579, 1, 23, 7, 'E-levantou Abraão e-prostrou-se para-o-povo- a-terra para-filhos-de Hete');
INSERT INTO verses VALUES (580, 1, 23, 8, 'e-falou com-eles dizendo se há a de-vossas-almas para-enterrar a da-morte-dele de-diante-de-mim ouvi-me e-atingi-vos para-mim Be-efron filho-de Tsochar');
INSERT INTO verses VALUES (581, 1, 23, 9, 'e-ele-dará- para-mim a Me-arat Ha-machpeleha que a-ele que em-extremidade Sadehu Be-khesef enchei Yittenenah para-mim Be-tochchem La-achuzat- Qever');
INSERT INTO verses VALUES (582, 1, 23, 10, 'e-efron habitou no-meio-de filhos-de het e-ele-respondeu efron o-חִתִּ֤י a Abraão a-todo filhos-de het dizendo ba-ei shaar- cidade-dele para-dizer');
INSERT INTO verses VALUES (583, 1, 23, 11, 'não Adonai shmaeni dei para-ti para-ti ve-hamearah a-ti nele para-ti netatiahah le-einei filhos-de povo-meu a-dei para-ti sepultar morto-tu');
INSERT INTO verses VALUES (584, 1, 23, 12, 'e-abaixou-se Abraão diante-de povo a-terra');
INSERT INTO verses VALUES (585, 1, 23, 13, 'e-falou a Efron em-orelhas-de dizendo a-terra dizendo somente se dei se ouve-me darei prata o-campo toma mais-que-a-mim e-eu-enterrarei a morto-dele ali');
INSERT INTO verses VALUES (586, 1, 23, 14, 'e-respondeu Efron a dizendo a-ele a-ele');
INSERT INTO verses VALUES (587, 1, 23, 15, 'Adonai ouça-me terra quatro de-uma sheqel- prata entre-mim e-em-você que ela e-a morto-seu sepultar');
INSERT INTO verses VALUES (588, 1, 23, 16, 'E-ouviu Abraão a Efron- e-evalou Abraão para-Efron a o-prata que palavra em-orelhas-de filhos-de het- quatro novecentos sheqel- prata transitorio- para-o-comerciante-');
INSERT INTO verses VALUES (589, 1, 23, 17, 'e-elevantou-se- campo- Efron que em-a-machpe-la que diante-de ma-mar-e-a o-campo e-a-me-arah que nele e-todo a-árvore que no-campo que em-todo gevul-o ao-redor');
INSERT INTO verses VALUES (590, 1, 23, 18, 'le-abraham le-mikna aos-olhos-de filhos-de het em-todo ba-ei shaar- ir-o');
INSERT INTO verses VALUES (591, 1, 23, 19, 'e-depois-de assim-que sepultou Abraão a Sara esposa-dele a de-tumba dos-campos ela sobre face-de Mamar-e ela Hebrom em-terra-de כְּנָֽעַן');
INSERT INTO verses VALUES (592, 1, 23, 20, 'E-levantou o-de-a-terra e-o-túmulo que nele para-Abraão para-posse-de sepultura de-com filhos-de Hete');
INSERT INTO chapters VALUES (24, 1, 24, 67);
INSERT INTO verses VALUES (593, 1, 24, 1, 'e-Abram velho veio em-os dias e-Theos abençoou a Abraão em-todo');
INSERT INTO verses VALUES (594, 1, 24, 2, 'E-disse Abraão a seu-aervo velho casa-dele o-mandante em-todo que debaixo põe- agora mão-tua em-baixo-de joelho-meu');
INSERT INTO verses VALUES (595, 1, 24, 3, 'e-juro-te em-Theos Elohim-de os-céus Elohim a-terra que não leva mulher para-meu-filho de-filhas o-kenaani eu eu habitante em-o-centro-dele');
INSERT INTO verses VALUES (596, 1, 24, 4, 'que a terra-meu e-a nascimento-meu vai e-toma mulher para-meu-filho para-Yitzkhak');
INSERT INTO verses VALUES (597, 1, 24, 5, 'E-disse a-ele o-escravo talvez não que-te-apeteceria a-mulher para-andar depois-de-mim a a-terra esta o-que-devolveu eu-devolverei a seu-filho a a-terra que saíste de-lá');
INSERT INTO verses VALUES (598, 1, 24, 6, 'E-disse a-ele Abraão hisshamer a-ti para-que-não tu-devolverás a filhos-de ali');
INSERT INTO verses VALUES (599, 1, 24, 7, 'yhwh Elohim-de os-céus que para-levar-me de-casa-de meu-pai e-de-terra de-nascimento-meus e-que falou para-mim e-que juro- dizendo dizendo le-zarkha etenn a ele esta ele ele-enviará seu-mandado diante-de-ti e-levarás mulher Libni de-lá');
INSERT INTO verses VALUES (600, 1, 24, 8, 'e-se não desejar-á a-mulher para-andar de-te e-serás-limpado esta esta somente não filhos-de não retornarás ali');
INSERT INTO verses VALUES (601, 1, 24, 9, 'e-ele-colocou o-escravo a debaixo em-substituição-a lado-de Abraão seu-mestre a-ele a-ele sobre a palavra a-esta');
INSERT INTO verses VALUES (602, 1, 24, 10, 'E-tomou o-escravo dez camelos de-camelos adonai-o E-andou e-todo bom adonai-aus na-sua-mão E-levantou E-andou a aram naha-rayim a cidade naa-hor');
INSERT INTO verses VALUES (603, 1, 24, 11, 'E-abençoou ha-gmalim de-fora la-ir a as-águas as-águas tarde tarde le-et tset ha-shaavot');
INSERT INTO verses VALUES (604, 1, 24, 12, 'va-yomer yhwh yhwh Adonai Abraão o-chame- agora diante-de-mim o-dia e-faze- graça povo Adonai Abraão');
INSERT INTO verses VALUES (605, 1, 24, 13, 'eis eu está-postado sobre as-águas as-águas e-filhas homens-de a-cidade saindo para-buscar águas');
INSERT INTO verses VALUES (606, 1, 24, 14, 'e-foi a-jovem- que disse para-ela o-vire- por-favor tua-tigela e-eu-bebere e-ela-dira beba e-também os-teus-camelo eu-apa-recarei-o ela-a tu-provaste-a para-o-teu-escravo para-isaque e-na-aquela eu-saberei porque fiz-te Hesed com Adonai');
INSERT INTO verses VALUES (607, 1, 24, 15, 'e-foi ainda-não antes-de completou para-falar e-eis Ривקה saindo que nascida para-Betuél filho-de milcha mulher-de Naor Ai Abraão e-seu-copo sobre sua-espádua');
INSERT INTO verses VALUES (608, 1, 24, 16, 'e-a-moça boa-de vista muito virgem e-homem não sabia-a e-ela-desceu a-fonte e-ela-encheu o-seu-tanque e-ele-subiu');
INSERT INTO verses VALUES (609, 1, 24, 17, 'e-ele-correu o-escravo para-a-sua-frente E-disse a-enche-me por-favor pouco- águas de-tua-jarra');
INSERT INTO verses VALUES (610, 1, 24, 18, 'E-disse bebe Adonai e-ela-se-apressou e-ela-desceu sua-jarra sobre mão-a-sua e-ela-o-bebeu');
INSERT INTO verses VALUES (611, 1, 24, 19, 'e-ela-começou-a-fim para-o-hidratá-lo E-disse também para-os-camelo-s-teus eu-beberei até se e-eles-terminaram para-o-beber');
INSERT INTO verses VALUES (612, 1, 24, 20, 'e-ela-se-apressou e-ele-acordou o-talho-a-sua a a-hidrat e-correu ainda a a-o-berço para-sugar e-sugou para-todo seus-camelo(s)');
INSERT INTO verses VALUES (613, 1, 24, 21, 'e-o-homem de-estranho para ela quieto para-conhecer e-teve-sucedido yhwh caminho-dele se não');
INSERT INTO verses VALUES (614, 1, 24, 22, 'e-houve como-que completaram os-camelos para-beber E-tomou o-homem anel ouro bekah seu-peso e-dois-de bracelos sobre suas-mãos ouro ouro seu-peso');
INSERT INTO verses VALUES (615, 1, 24, 23, 'E-disse filha-de quem você-é o-gedi por-favor a-mim haja-esse lugar a-teu-pai lugar para-nós para-aquilo');
INSERT INTO verses VALUES (616, 1, 24, 24, 'E-disse a-ele filha-de eu eu filho-de de-Milcah que deu-à-luz a-Nahor');
INSERT INTO verses VALUES (617, 1, 24, 25, 'E-disse a-ele também pedra também de-conto muito com-nosso também lugar para-aquilo');
INSERT INTO verses VALUES (618, 1, 24, 26, 'e-ele-roncou o-homem e-prostrou-se la-yhwh:');
INSERT INTO verses VALUES (619, 1, 24, 27, 'E-disse bendito yhwh Elohim-de Adonai Abraão que não deixou sua-graça e-sua-verdade de-com eu eu no-caminho yhwh yhwh casa irmãos-de Adonai');
INSERT INTO verses VALUES (620, 1, 24, 28, 'e-ela-correu a-jovem-a e-ele-contou para-casa-de mãe-dela segundo-as-palavras as estas');
INSERT INTO verses VALUES (621, 1, 24, 29, 'e-a-Rivca irmão e-nome-de-ele Laban e-ele-correu Laban- a o-homem o-lá-fora a a-fonte');
INSERT INTO verses VALUES (622, 1, 24, 30, 'e-houve para-ver a o-anel e-a as-brincos sobre mãos-de a-sua-irmã e-quando-ele-ouviu a dizendo Rebeca sua-irmã dizendo assim palavra para-mim o-homem E-veio a o-homem e-eis ficou-em-pé sobre os-camelo sobre a-fonte');
INSERT INTO verses VALUES (623, 1, 24, 31, 'E-disse trazer bendito yhwh por-que você-estará no-exterior e-eu eu-preparado a-casa e-lugar para-os-camelenos:');
INSERT INTO verses VALUES (624, 1, 24, 32, 'E-veio o-homem a-casa e-ele-abriu os-camelenos E-colocou pedra e-farinha para-os-camelenos e-agua para-lavar-se seus-pes e-pes os-homens que com-ele');
INSERT INTO verses VALUES (625, 1, 24, 33, 'diante-dele para-comer E-disse não E-disse não se até as-minhas-palavras E-disse E-disse');
INSERT INTO verses VALUES (626, 1, 24, 34, 'E-disse servo Abraão eu');
INSERT INTO verses VALUES (627, 1, 24, 35, 'e-יהוה abençoou a muito muito e-ele-cresceu e-ele-deu a-lhe ovelhas e-gado e-prata e-ouro e-servos e-escravas e-camelenhos e-jumentos');
INSERT INTO verses VALUES (628, 1, 24, 36, 'e-ela-deu-a-luz שָׂרָה֩ esposa-de Adonai filho para-o-meu-adonai atrás-de em-seus-dias-avançados e-ele-deu a-ele a todo que a-ele');
INSERT INTO verses VALUES (629, 1, 24, 37, 'e-ele-jurou-a-mim Adonai dizendo não leva mulher para-meu-filho das-mulheres o-kenaani eu eu habitou na-sua-terra');
INSERT INTO verses VALUES (630, 1, 24, 38, 'se não a casa-de meu-pai vá e-a de-minha-família e-tomará mulher para-meu-filho');
INSERT INTO verses VALUES (631, 1, 24, 39, 'e-disse a Adonai talvez não vá a-mulher depois-de-mim');
INSERT INTO verses VALUES (632, 1, 24, 40, 'E-disse a-mim yhwh que andei diante-dele enviar-á seu-mensagem contigo e-sucederá teu-caminho e tomaste mulher meu-filho de-minha-família e-de-casa pai-meu');
INSERT INTO verses VALUES (633, 1, 24, 41, 'então te-lavará de-minha-maldição que vires a de-a-mi-família e-se para-ti dêem para-ti e-você-seja puro de-a-maldição-meua');
INSERT INTO verses VALUES (634, 1, 24, 42, 'e-eu-vi o-dia a a-fonte yhwh yhwh Elohim-de Adonai Abraão se há-tu agora eu caminho-meua que eu andou sobre-ela');
INSERT INTO verses VALUES (635, 1, 24, 43, 'eis eu estando-ereto sobre as-águas as-águas e-será a-jovem-mulher saindo-a para-beber e-disser a ela dá-me-água agora pouco- águas do-tu-teu-recipiente');
INSERT INTO verses VALUES (636, 1, 24, 44, 'e-disse-a-mulher a-mim também tu beba e-também para-os-teus-camelo-s ela ela a-mulher yhwh repreendo yhwh para-filho-de Adonai');
INSERT INTO verses VALUES (637, 1, 24, 45, 'eu-sou ainda-não eu-devorarei para-falar a meu-coracao e-eis Rebeca saindo-a e-seu-taz sobre em-sua-espaldas e-ele-descerreu a-fonte e-ela-bebeu e-eu-falei para-ela o-abasteça-me por-favor');
INSERT INTO verses VALUES (638, 1, 24, 46, 'e-ela-se-apressou e-ele-desceu o-tanque-de-a de-em-o-superior-de-a E-disse beba e-também os-camelo-seus eu-apa-recarei-o e-eu-estive e-também os-camelo bebeu-a');
INSERT INTO verses VALUES (639, 1, 24, 47, 'e-eu-pedi אֹתָהּ e-eu-disse filha-de quem E-disse e-disse filha-de em-Betu-El filho-de nachor que deu-a-parida a-ele Milcah e-eu-ponhei o-nariz sobre seu-apo e-os-acessórios sobre mãos-de-a');
INSERT INTO verses VALUES (640, 1, 24, 48, 'e-eu-consagrei e-eu-me-prostrei para-יהוה e-eu-bençoei a yhwh Elohim-de Adonai Abraão que dá-me-graça no-caminho אמת para-tomar a filha-de irmão-de Adonai para-seu-filho');
INSERT INTO verses VALUES (641, 1, 24, 49, 'e-agora se haja-vos fazendo misericórdia e-verdade a Adonai הַגּ֣idoּ para-mim e-se não הַגּ֣idoּ para-mim e-eu-virei sobre direita ou sobre esquerdo-:');
INSERT INTO verses VALUES (642, 1, 24, 50, 'e-ele-respondeu Laban e-Betu-el e-disseram de-יהוה sair a-palavra não podemos palavra a-ti mau ou bom');
INSERT INTO verses VALUES (643, 1, 24, 51, 'eis-a Rebeca diante-de-ti toma e-vá e-seja mulher para-filho-de seu-adonai yhwh palavra yhwh');
INSERT INTO verses VALUES (644, 1, 24, 52, 'e-houve como-que ouviu servo Abraão a palavras-deles e-prostrou-se terra-para la-yhwh:');
INSERT INTO verses VALUES (645, 1, 24, 53, 'e-saiu o-escravo objetos-de prata ouro zahav e-roupas E-deu para-Rebeca dar deu para-o-irmão-de-a e-para-a-mãe-de-a');
INSERT INTO verses VALUES (646, 1, 24, 54, 'e-eles-comeram e-eles-beberam ele e-os-homens que com-ele e-eles-pernoitaram e-ele-levantaram-se E-disse E-disse envia-me para-o-meu-adonai');
INSERT INTO verses VALUES (647, 1, 24, 55, 'E-disse seu irmão e sua mãe viverá a moça conosco dias ou dez apos andares');
INSERT INTO verses VALUES (648, 1, 24, 56, 'E-disse para-eles a taacharu oti ve-yhwh hitzliakh darkhi shalchuni e elka o-meu-adonai-versículo');
INSERT INTO verses VALUES (649, 1, 24, 57, 'e-disseram encontrou-se a-juventude-a e-será-perguntada a boca-dela');
INSERT INTO verses VALUES (650, 1, 24, 58, 'e-eles-chamaram para-Rebeca e-disseram a ela se-i-darás com o-homem E-disse e-disse irei.');
INSERT INTO verses VALUES (651, 1, 24, 59, 'e-enviaram a Rebeca irmã-deles-a e-a de-sua-ameixa-a e-a servo Abraão e-a אנשי׃');
INSERT INTO verses VALUES (652, 1, 24, 60, 'e-abençoaram a Rebeca e-disseram para-ela irmã-nossa אַ֥תְּ ser-que para-milhares-de multidões e-herdará semente-teu a portão-de inimigos-seus');
INSERT INTO verses VALUES (653, 1, 24, 61, 'e levantou-se Rebeca e suas servas e se embarcou sobre os camelos e caminhou depois-de E-tomou E-tomou o servo a sua-mãe E-andou');
INSERT INTO verses VALUES (654, 1, 24, 62, 'e-Isaque veio de entrada em-Beer para-o-vivo minha-sogra e-ele habitante em-terra-de ao-sul');
INSERT INTO verses VALUES (655, 1, 24, 63, 'e-ele-saiu Isaque a procurar no-campo para buscar tarde va-yiss-a os-seus-olhos E-viu e-eis camelos que vinham:');
INSERT INTO verses VALUES (656, 1, 24, 64, 'e levantou-se rebequá a E-viu e-ela-viu a de-cima-de e caiu de-sobre o camelô');
INSERT INTO verses VALUES (657, 1, 24, 65, 'E-disse a o servo quem- o-que-vai o/a/disto que vai E-disse para nos ver ele o-escravo e-tomou Adonai e tomou o manto e cobriu-se');
INSERT INTO verses VALUES (658, 1, 24, 66, 'e contou o-escravo [לְיִצְחָ֑ק] a todo as-palavras que fez');
INSERT INTO verses VALUES (659, 1, 24, 67, 'e-trouxe-a Isaque a-tenda-a Sara sua-mãe E-tomou a Rebekah e-ela-tornou-se para-ele para a mulher e-ele-amou-a-a e-ele-consolou-se sua-mãe atrás-de mãe-de ele');
INSERT INTO chapters VALUES (25, 1, 25, 34);
INSERT INTO verses VALUES (660, 1, 25, 1, 'e-acrescentou Abraão E-tomou mulher e-nome-de-ela Quetura');
INSERT INTO verses VALUES (661, 1, 25, 2, 'e-deu-à-luz a-ele a Zimran e-a Yaqsan e-a Medan e-a Midiã e-a Yishbak e-a שׁוּחַ׃');
INSERT INTO verses VALUES (662, 1, 25, 3, 'e Yaqsan dar-à-luz a שָׁבַע e-a Dedan e-filhos-de דְדָ֔ן foram Assúrim e Lutushim e nações:');
INSERT INTO verses VALUES (663, 1, 25, 4, 'e-filhos-de Midiã Efá e Efer e-enoch e Abida e Eldaá todo estes filhos-de Quetura');
INSERT INTO verses VALUES (664, 1, 25, 5, 'E-colocou Abraão a todo que para-ele para-Yitzkhak');
INSERT INTO verses VALUES (665, 1, 25, 6, 'e-por-filhos os-femininos que a-Abram dar Abraão presentes e-os-enviou de-cima-de Isaque seu-filho enquanto-ele vida ao-oriente a oriente adiante');
INSERT INTO verses VALUES (666, 1, 25, 7, 'e-estes dias-de dois chayyé Abraão que viveu cem ano ve-shiv''ím ano e-cinco dois');
INSERT INTO verses VALUES (667, 1, 25, 8, 'e foi adormecido E-morreu Abraão em-erva bem velho e-satisfeito e-ele-foi-recolhido a seus-povos');
INSERT INTO verses VALUES (668, 1, 25, 9, 'e sepultaram ele Isaque ve-yishma''èal filhos-dele a me''árat hammákhpéla'' a שֵׂדֶה עֶפְרוֹן filho-de צֹהַר a hitita que sobre face-de מַמְרֵא׃');
INSERT INTO verses VALUES (669, 1, 25, 10, 'הַשֵּׂדֶה que adquiriu Abraão de-junto-de filhos-de het para-aí קֻבָּר Abraão e-Sara esposa-dele');
INSERT INTO verses VALUES (670, 1, 25, 11, 'e-houve depois-de morrendo Abraão E-abençoou Elohim a Isaque filho-seu e-sentou Isaque com em-Beer para-o-vivo vendo-eu');
INSERT INTO verses VALUES (671, 1, 25, 12, 'e-estes תּוֹלְדֹת Ismael filho-de Abraão que deu-a-parida o-habitante a-egípcia shifchat sarah- לְאַבְרָהָם׃');
INSERT INTO verses VALUES (672, 1, 25, 13, 'e-estes nomes-de filhos-de Ismael em-seus-nomes [לְתוֹלְדֹתָ֑ם] primogênito Ismael Nevayot e Quedar e Adbeel e Mibsão');
INSERT INTO verses VALUES (673, 1, 25, 14, 'e-do-nome e-Duma e-mas-sua');
INSERT INTO verses VALUES (674, 1, 25, 15, 'chad-ad ve-teima Jetur Nafis va-qed-ma');
INSERT INTO verses VALUES (675, 1, 25, 16, 'Estas eles filhos-de Ismael e-estes שְׁמֹתָ֔ם em-suas-cortiços e-em-seus-alcovos doze dez [לְאֻמֹּתָֽם] para-suas-nações:');
INSERT INTO verses VALUES (676, 1, 25, 17, 'e-estes segundo chayyei Ismael cem ano e-trinta ano vesheva'' dois va-yigvaa E-morreu e-ele-foi-recolhido a seus-povos');
INSERT INTO verses VALUES (677, 1, 25, 18, 'e-eles-moraram em-um-lugar até Shor que sobre face-de Egito em-sua-comer Assúria sobre face-de todo seus-irmãos caíu:');
INSERT INTO verses VALUES (678, 1, 25, 19, 'e-estes gerações-de Isaque filho-de Abraão Abraão gerou a Isaque');
INSERT INTO verses VALUES (679, 1, 25, 20, 'e-houve Isaque filho-de quarenta ano quando-ele-a-prendeu a Rebeca filha-de Betuel o-aramita de-Padan Arã a-ele a-Lavan o-Arami para-ele para-mulher');
INSERT INTO verses VALUES (680, 1, 25, 21, 'e-eu-roguei Isaque para-o-yhwh para-contra mulher-dele que estéril-a ela e-ele-foi-rogado a-ele yhwh e-concebeu Rebeca esposa-dele');
INSERT INTO verses VALUES (681, 1, 25, 22, 'e se agitaram os filhos em seu seio E-disse se assim por-que eu eu e saiu para buscar a yhwh');
INSERT INTO verses VALUES (682, 1, 25, 23, 'E-disse yhwh para-ela segundo em-a-barriga-de-você e-dois לְאֻמִּ֔ים de-os-intestinos-de-você separar-se-ão e-a-nação de-sua-nação se-fortalecerá e-muito servirá pequeno');
INSERT INTO verses VALUES (683, 1, 25, 24, 'e-cheio-foram seus-dias para-o-nascimento e-eis ТОМИМ em-se');
INSERT INTO verses VALUES (684, 1, 25, 25, 'e-saiu o-primeiro admoni todos como-um-veloz tigela e-chamaram seu-nome euveus:');
INSERT INTO verses VALUES (685, 1, 25, 26, 'ואחרי־ sair saiu o-seu-irmão e-a-sua-mão segurando pelo-calcanhar E-chamou E-chamou seu-nome Jacó e-Isaac filho-de sessenta eles para-o-nascimento a-eles');
INSERT INTO verses VALUES (686, 1, 25, 27, 'e-ele-criaram os-jovens e-houve Esaú homem sabe caça homem campo e-jaʿaqob homem têm habitou tendas');
INSERT INTO verses VALUES (687, 1, 25, 28, 'e-ele-amou Isaque a Esaú porque caça em-boca-sua e-Rebeca amando a Jacó');
INSERT INTO verses VALUES (688, 1, 25, 29, 'e-ele-cozinha Jacó guisado E-veio ê-sav de o-campo e-ele cansado-');
INSERT INTO verses VALUES (689, 1, 25, 30, 'E-disse Esaú a Jacó ameixa-me- por-favor de o-homem que esta eu cansado eu sobre assim קָרָֽא־ nome-de-ele Edom');
INSERT INTO verses VALUES (690, 1, 25, 31, 'E-disse Jacó vendeu- como-o-dia a de-a-primeira-da-tua para-mim');
INSERT INTO verses VALUES (691, 1, 25, 32, 'E-disse Esaú eis eu  הולך  la-mut וְלָמָּה־ isto para-mim primeira-');
INSERT INTO verses VALUES (692, 1, 25, 33, 'E-disse Jacó hisheba a-mim como-o-dia e-ele-jurou a-ele e-vendeu a de-a-primeira-dele a-Jacob');
INSERT INTO verses VALUES (693, 1, 25, 34, 've-yaʿaqōb dar le-ʿēśaw pão e-nosso ʿădāšîm e-comeu vayyēṣṭâ E-levantou E-andou vayyibez Esaú a habbekhorâ');
INSERT INTO chapters VALUES (26, 1, 26, 35);
INSERT INTO verses VALUES (694, 1, 26, 1, 'e-houve רָעָב֙ na-terra milbad הרעב harishon que ser em-dias-de Abraão E-andou Isaque a rei-de Filisteus gerarah');
INSERT INTO verses VALUES (695, 1, 26, 2, 'E-viu a-ele yhwh E-disse a tered Egito-para shechon na-terra que disse para-ti');
INSERT INTO verses VALUES (696, 1, 26, 3, 'gur na-terra a-esta e-ehye contigo e-abenço-e-a porque para-ti e-para-o-semente-de-tu אֶתּוֹ a todo as-terra o-Elohim e-elevar-ei a a-juramento que eu-jurei le-abraham pai-teu');
INSERT INTO verses VALUES (697, 1, 26, 4, 'e-multiplicarei a zera-ka ke-kokhevei os-céus e-darei para-o-semente-de-tu a todo as-terra o-elohim e-ser-vos-benditos em-o-sêmen-teu a-terra nações-de a-terra');
INSERT INTO verses VALUES (698, 1, 26, 5, 'por-causa-de que ouviu Abraão por minha voz e guardou a minha guarda as-minhas-mandamentos chukkotai e minhas leis');
INSERT INTO verses VALUES (699, 1, 26, 6, 'e-habitou Isaque em-Berseba');
INSERT INTO verses VALUES (700, 1, 26, 7, 'e-eles-perguntaram homens-de o-lugar para-a-sua-mulher E-disse irmã-de-mim ela que temer dizendo a-minha-mulher para-que-não e-eles-me-exterminarão homens-de o-lugar sobre vista porque boa-de aparência ela');
INSERT INTO verses VALUES (701, 1, 26, 8, 'e-houve que אֲרַכְתֶּם- para-ele nome os-dias e-ele-viu Avimelech rei filisteus בְּעַד- E-viu E-viu e-eis Isaque מְצַחֵ֔ק a רִבְקָ֥ה esposa-dele');
INSERT INTO verses VALUES (702, 1, 26, 9, 'E-chamou Avimélek a-Isaque E-disse porém eis esposa-teu ela ו-אֵ֥יךְ disseste irmã-de-mim ela E-disse a-ele Isaque que eu-disse para-que-não morrirei sobre-ela');
INSERT INTO verses VALUES (703, 1, 26, 10, 'E-disse Abimélek que zot fizeste nós pouco deitou-se um o-povo a esposa-teu וְהֵבֵאתָ֥ sobre nós culpa');
INSERT INTO verses VALUES (704, 1, 26, 11, 'E-ordenou Abimélek a dizendo o-povo dizendo o-toque-o no-homem morrendo e-na-mulher-seu morrer será-morto');
INSERT INTO verses VALUES (705, 1, 26, 12, 'e plantou Isaque na-terra aquela e achou em ano aquela cem portas-as e abençoou-o yhwh');
INSERT INTO verses VALUES (706, 1, 26, 13, 'e-cresceu o-homem E-andou caminhar e-cresceu até porque muito muito');
INSERT INTO verses VALUES (707, 1, 26, 14, 'e-foi para-ele rebanho-de o rebanho -e a mercadoria manhã e serviu-se dela ele e se enoijaram a-ele filisteus');
INSERT INTO verses VALUES (708, 1, 26, 15, 'e-todo as cisternas que escavaram seu-pai pai-dele nos-dias seu-pai pai-seu entupidos filisteus pó terra:');
INSERT INTO verses VALUES (709, 1, 26, 16, 'E-disse Avimelekh a Isaque vai de nós muito e fez-se grande dele muito');
INSERT INTO verses VALUES (710, 1, 26, 17, 'E-andou de-lá Isaque e acampou em um vale גראר e-habitou nome');
INSERT INTO verses VALUES (711, 1, 26, 18, 'e voltou Isaque vey-yachpor a poços-de-a as-águas que cavaram em-os-dias-de Abraão seu-pai e-selaram-no filisteus atrás-de morrendo Abraão E-chamou para-eles nomes em-o-valle que chamou seu-pai pai-seu');
INSERT INTO verses VALUES (712, 1, 26, 19, 'e-cavaram servos-de- Isaque no-riff e-acharam- águas vida águas vivos');
INSERT INTO verses VALUES (713, 1, 26, 20, 'e-disputaram pastores-de Gerar com pastores dizendo para-dizer as-águas E-chamou E-chamou nome-de que trabalho porque se-encheram-de-trabalho com-ele-verso');
INSERT INTO verses VALUES (714, 1, 26, 21, 'e-cavaram poço אַחֶ֔רֶת e-disputaram também E-chamou E-chamou shema-ha- ódio');
INSERT INTO verses VALUES (715, 1, 26, 22, '并夺取了 de-lá e cavou poço outro e-não ravu sobre-ela E-chamou nome-dela largos E-disse porque Agora yhwh yhwh para-nós na-terra na-terra');
INSERT INTO verses VALUES (716, 1, 26, 23, 'e-ofereceu de-lá em-Beer sete');
INSERT INTO verses VALUES (717, 1, 26, 24, 'E-viu a-ele yhwh na-noite a-aquela E-disse eu Elohim-de Abraão pai-teu a temera eu com-você eu e-bendiz-te e-aumentarei a zera-ka por-causa-de Abraão AVDI');
INSERT INTO verses VALUES (718, 1, 26, 25, 'E-edificou nome altar E-chamou em-nome-de yhwh e estendeu nome sua tenda e cavaram nome servos- Isaque de-a-er:');
INSERT INTO verses VALUES (719, 1, 26, 26, 'e-Avimeléc andar a-ele de-Megiddo e-posseu-a do-seu-amigo e-Ficol príncipe-de seu-exército;');
INSERT INTO verses VALUES (720, 1, 26, 27, 'E-disse para-eles Isaque por-que vinde-vos a-mim e-vós odeiais-vos me-a e-me-enviastes-vos de-com-vos');
INSERT INTO verses VALUES (721, 1, 26, 28, 'e-disseram o-ve-o nós-vimos porque yhwh יהוה com-você e-nos-dissemos Tihi agora curse [בֵּינוֹתֵ֖ינוּ] בֵּינֵ֣ינוּ e-entre-tu e-se-cortará berith contigo');
INSERT INTO verses VALUES (722, 1, 26, 29, 'se faze-o com-nos ra-á não não nossa-te-toch וְכַאֲשֶׁ֨ר fizemos contigo somente bom tu em-a-paz tu yhwh abençoado yhwh');
INSERT INTO verses VALUES (723, 1, 26, 30, 'E-fez a-eles banquete e comeram e beberam:');
INSERT INTO verses VALUES (724, 1, 26, 31, 'e-eles-se-levantaram-cedo em-a-manhã e-eles-juraram homem contra seu irmão e-eles-os-enviaram Isaque e-caminharam de-com-ele em-paz');
INSERT INTO verses VALUES (725, 1, 26, 32, 'e-houve no-dia no-dia e-vieram servos-de Isaque disseram a-ele a-ele de-louvores a-o-berço que cavaram e-eles-disseram a-ele achamos águas');
INSERT INTO verses VALUES (726, 1, 26, 33, 'E-chamou a-ela sete sobre assim nome-de a-cidade até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (727, 1, 26, 34, 'e-houve ěšav filho-de quarenta E-tomou E-tomou mulher a judeita filha-de minha-fonte o-hití e-a em-a-sma-t filha-de e-il-on o-hití:');
INSERT INTO verses VALUES (728, 1, 26, 35, 'e-as-se-tornaram de-a-mora-t espírito para-Isaque e-para-Rebeca:');
INSERT INTO chapters VALUES (27, 1, 27, 46);
INSERT INTO verses VALUES (729, 1, 27, 1, 'e-houve porque velho Isaque e-as-fizeram seus-olhos E-chamou E-chamou a Esaú o-grande E-disse a-ele a-ele E-disse a-ele a-ele eis-me');
INSERT INTO verses VALUES (730, 1, 27, 2, 'E-disse eis-que- por-favor não não dia dia meu-morte:');
INSERT INTO verses VALUES (731, 1, 27, 3, 'e-agora sair- por-favor os-teus-vess-eis a-tua-mira e-a-tua-flecha e-sai o-campo a-mim para-mim');
INSERT INTO verses VALUES (732, 1, 27, 4, 'e-faze- para-mim de-gostos como-que eu-am-ei a-mim para-mim e-com-erei por-causa-de que-bençoes-te alma-minha בטרעם morrer-ei:');
INSERT INTO verses VALUES (733, 1, 27, 5, 'e-Rebeca ouviu-a em-falar Isaque a Esaú filho-seu E-andou ěšav o-campo para-o-capturar caça para-trazer');
INSERT INTO verses VALUES (734, 1, 27, 6, 'e-Rebeca disse a Jacó dizendo eis eis ouvi a pai-teu falando dizendo עֵשָׂ֥ו irmão-teu para-dizer');
INSERT INTO verses VALUES (735, 1, 27, 7, 'trouxe-a a-mim caça e-faze- para-mim de-gostosuras e-comer-a e-abenço-e-a yhwh yhwh diante-de morte-de-mim');
INSERT INTO verses VALUES (736, 1, 27, 8, 'e-agora filhos-de ouviu em-o-voz-de-mim para aquele eu mandamento te:');
INSERT INTO verses VALUES (737, 1, 27, 9, 'vai-para por-favor a o-rebanho וקח־ a-mim de-lá segundo de-gado eles bons e-farei a-eles sabores para-o-pai-tua como-que amou');
INSERT INTO verses VALUES (738, 1, 27, 10, 'וְהֵבֵאתָ֥ para-o-teu-pai e-comerá em-razão-de que יברךך diante-de sua morte:');
INSERT INTO verses VALUES (739, 1, 27, 11, 'E-disse Jacó a sua-mãe eis aquelas Esaú irmão-meu homem pelos e-eu homem escorregadio');
INSERT INTO verses VALUES (740, 1, 27, 12, 'אוּלַ֤י me-procurará pai-meu e-eu-serei em-seus-olhos como-pendurado e levar-te-ei sobre-mim maldição e-não bênção-');
INSERT INTO verses VALUES (741, 1, 27, 13, 'E-disse a-ele sua-mãe alai maldição-teu filhos-de somente ouviu em-voz-minha e-ir toma- para-mim');
INSERT INTO verses VALUES (742, 1, 27, 14, 'E-andou E-tomou e-trouxe para a mãe e-fazeste sua-mãe gostosos como amou seu-pai');
INSERT INTO verses VALUES (743, 1, 27, 15, 'e-tomou rebeca a roupas esau o-grande o grande as mais agradáveis que com ela ba-bayit e vestiu a Jacó o-filho-a o-pequeno;');
INSERT INTO verses VALUES (744, 1, 27, 16, 'e-a peles de-gado as-ovelhas vestiu-a sobre mãos-dele e-sobre campo-de o-seio-dele');
INSERT INTO verses VALUES (745, 1, 27, 17, 'e-deu a os-gostosos e-a o pão que fez-a na-mão-de Jacó o-filho-seu.');
INSERT INTO verses VALUES (746, 1, 27, 18, 'E-veio a E-disse E-disse E-disse E-disse quem tu tu filhos-de');
INSERT INTO verses VALUES (747, 1, 27, 19, 'E-disse Jacó a eu eu Esaú seu primogênito eu fiz como falaste a-mim arise, por-favor return e comerá da caça minha por-causa-de me bendigas alma-tua');
INSERT INTO verses VALUES (748, 1, 27, 20, 'E-disse Isaque a seu-filho que isto prestei E-disse que E-disse yhwh chama yhwh teu-Elohim perante mim:');
INSERT INTO verses VALUES (749, 1, 27, 21, 'E-disse Isaque a Jacó vem por favor e te amasse filhos-de o você este filhos-de Esaú se não');
INSERT INTO verses VALUES (750, 1, 27, 22, 'e ele se aproximou Jacó a seu-pai pai-dele E-disse E-disse voz voz-de Jacó e as mãos mãos-de Esau');
INSERT INTO verses VALUES (751, 1, 27, 23, 'e-não conheceu-o porque foram as-sua-mãos para que Esau irmão-seu cabelos e bendisse-o');
INSERT INTO verses VALUES (752, 1, 27, 24, 'E-disse tu este filhos-de Esaú E-disse eu');
INSERT INTO verses VALUES (753, 1, 27, 25, 'E-disse traga a-mim e-a- comerá -do-cer filhos-de para te-barake-te minha-alma e-va-ga-shé- e-comeu e-trouxe a-ele -lo vinho e-va-ve-she-té-:');
INSERT INTO verses VALUES (754, 1, 27, 26, 'E-disse a-ele Isaque seu-pai gash- na'' ushqah- li filhos-de');
INSERT INTO verses VALUES (755, 1, 27, 27, 'e se aproximou e-beijou- a-ele vayyarah a aroma-de E-disse wayyabarakhehu E-disse viu aroma filhos-de kreich- campo yhwh berakho- yhwh');
INSERT INTO verses VALUES (756, 1, 27, 28, 'e lhe dará para-ti os-Elohim chuva os-céus a-terra a-terra e abundância grãos e vinha');
INSERT INTO verses VALUES (757, 1, 27, 29, 'servir-te povos para-ti לְאֻמִּ֔ים a-ti senhor a-teu-irmão e-se-inclinarão para-ti filhos-de a-ti que-maldiz-te maldito e-bendizer-te maldito');
INSERT INTO verses VALUES (758, 1, 27, 30, 'e-houve como-que completou Isaque para-abençoar a e-houve E-foi porém sair saiu Jacó face-de face-de seu-pai pai-seu e-Ésaú irmão-seu veio de-seu-caça');
INSERT INTO verses VALUES (759, 1, 27, 31, 'E-fez também ele e-trouxe E-veio E-disse E-disse para-o-seu-pai levante-se pai-meu e-ele-coma de-caça seu-filho por-causa-de abençoe-me alma-tua');
INSERT INTO verses VALUES (760, 1, 27, 32, 'E-disse a-ele Isaque seu-pai quem E-disse E-disse eu em-o-seu-filho com-a-primeira-fruta-de-você עֵשָֽׂו׃');
INSERT INTO verses VALUES (761, 1, 27, 33, 'e achou-se apavorado Isaque ansiedade grande até E-disse E-disse ele então e-trouxe a-caça- caça de-toda para-mim e-eu-comi de-todo בטרעם será e-eu-bençoe-o também abençoado será');
INSERT INTO verses VALUES (762, 1, 27, 34, 'quando-ouvi ěšav a seu-pai pai-dele e-ele-gritou grito grande e-amarga E-disse muito E-disse para-seu-pai abençoe-me também ani pai-meu');
INSERT INTO verses VALUES (763, 1, 27, 35, 'E-disse veio irmão-teu com-enganosa E-tomou bênção-teu');
INSERT INTO verses VALUES (764, 1, 27, 36, 'E-disse haki chamou shemo Jacó veyaakveni este paamayim a bekhorati tomou e-eis tomou tomou berkhati E-disse a-mim atzaltah li em-benção');
INSERT INTO verses VALUES (765, 1, 27, 37, 'e-ele-respondeu Isaque E-disse leesav eis gevir samtivi para-ti e-a dei a-ele eu-deti a-ele la-abadim ve-dagan ve-tirosch smachtivi ule-kha אֵפוֹא que eu-farei filhos-de');
INSERT INTO verses VALUES (766, 1, 27, 38, 'E-disse esau a pai-de-ele uma achat hi- para-ti pai-meu barcheni também ani pai-meu e-levantou ê-sav seu-grito וַיֵּֽבְךְּ׃');
INSERT INTO verses VALUES (767, 1, 27, 39, 'e-respondeu Isaque seu-pai E-disse a-ele eis de-a-oleo a-terra será מֽוֹשָׁבֶ֔ךָ e-de-a-chuva os-céus de-acima');
INSERT INTO verses VALUES (768, 1, 27, 40, 'e-sobre חַרְבְּךָ֣ viveras e-a irmão-teu serviras e-será como-que removeras de-cima-de seu-grafo de-sobre garganta-vossa');
INSERT INTO verses VALUES (769, 1, 27, 41, 'e-abominou-se ěšav a Jacó sobre abencao seu-pai E-disse pai-seu E-disse Esaú dias-de se-ajuntarão os-dias luto pai-meu e-eu-te-matarei a Jacó meu-irmão');
INSERT INTO verses VALUES (770, 1, 27, 42, 'vayuggad para-Rebeca a palavras-de Esaú o-grande o-grande e-ela-mandou e-chamou le-ya''akov seu-filho E-disse a-ele eis behold Esaú irmão-teu a-ti a-ti para-te-matar');
INSERT INTO verses VALUES (771, 1, 27, 43, 'e-agora filhos-de ouviu em-minha-voz e-levantar-se ברח- para-ti a a-Lavan irmão-meu em-Haran');
INSERT INTO verses VALUES (772, 1, 27, 44, 'e habitarás com-ele dias um-dia até que tashuv de-ira irmão-teu');
INSERT INTO verses VALUES (773, 1, 27, 45, 'até e-voltar também seu-irmão de-ti e-esquecer para-ele que fizeste a-ele e-enviarei e-tomarei-te de-lá dia um também de-vocês-dois dia um');
INSERT INTO verses VALUES (774, 1, 27, 46, 'E-disse רִבְקָה֙ a Isaque קַ֣צְתִּי de-diante-de de-face-de filhas-de het se tomou Jacó mulher מִבְּנֽוֹת־ a-terra כָּאֵ֙לֶּה֙ a-mim vida por-que para-mim vivos');
INSERT INTO chapters VALUES (28, 1, 28, 22);
INSERT INTO verses VALUES (775, 1, 28, 1, 'E-chamou Isaque a E-abençoou ele a-ela E-disse a-ele a-ele não tome-você mulher de-construções כְּנָֽעַן');
INSERT INTO verses VALUES (776, 1, 28, 2, 'levantou vá-você Paddan Arã casa-seu Betuel pai-de mãe-tua e-toma para-ti de-lá mulher de-Binot Laban irmão-de אִמֶּֽךָ׃');
INSERT INTO verses VALUES (777, 1, 28, 3, 'e-a Shaddai abençoará ot-cha e-afirmará-te e-aumentará-te serás para-congregar עַמִּֽים׃');
INSERT INTO verses VALUES (778, 1, 28, 4, 'e dará: para-ti a a-ti Abraão a-ti e para o teu semente: contigo para a herança tua: a terra dos que estão em teu meio: que deu Elohim para Abraão:');
INSERT INTO verses VALUES (779, 1, 28, 5, 'e-estendeu Isaque a Jacó E-andou padeça Arã a Laban filho-de Beituel mãe Ai Rebeca mãe Jacó E Esaú:');
INSERT INTO verses VALUES (780, 1, 28, 6, 'E-viu Esaú porque abençoou Isaque a ele e enviaria ele para buscar Arã que tomasse a-ele ele E-ordenou em seu nome dizendo e ordenou sobre-ele dizendo não a-ti mulher מִבְּנוֹת כְּנָֽעַן');
INSERT INTO verses VALUES (781, 1, 28, 7, 'E-ouviu Jacó a pai-dele e-a mãe-dele E-andou aram');
INSERT INTO verses VALUES (782, 1, 28, 8, 'E-viu Esaú que raot filhas-de assim em-olhos-de Isaque seu-pai');
INSERT INTO verses VALUES (783, 1, 28, 9, 'E-andou Esaú a E-tomou E-tomou a machalat filha-de Ismáel filho-de Abraão a-ele Nevayot sobre suas mulheres: para-ele para-mulher');
INSERT INTO verses VALUES (784, 1, 28, 10, 'e-ele-saiu Jacó de-a-fonte sete E-andou Harana');
INSERT INTO verses VALUES (785, 1, 28, 11, 'e-encontrou no-lugar e-estendeu nome porque veio E-tomou E-tomou de-pedras o-lugar e-colocou em-cabeça e-deitou-se no-lugar a-aquela');
INSERT INTO verses VALUES (786, 1, 28, 12, 'e-chalom e-eis sulam mutsav terra-para ve-rosho magia hashamayim e-eis mensageiros-de Elohim subindo ve-yordim em-ele');
INSERT INTO verses VALUES (787, 1, 28, 13, 'e-eis yhwh nitzav em-ele-o E-disse eu yhwh Elohim-de Abraão pai-teu ve-elohê Isaque a-terra que tu deitado sobre-ela a-ti ettenana e para o teu semental:');
INSERT INTO verses VALUES (788, 1, 28, 14, 'e-era tua-semente como pó a-terra e te expandirás para o mar e para a manhã e para o norte e para a terra do sul e te abençoarão em ti todo a-terra a terra e na tua semente:');
INSERT INTO verses VALUES (789, 1, 28, 15, 'e-eis eu com-te e guardarei-te em-todo que t-te-lek e reverterei-te a que não porque até não deixarei-te até que se para-ti a que até para-ti');
INSERT INTO verses VALUES (790, 1, 28, 16, 'e-ele-se-adiantou Jacó de-sua-dormição E-disse certamente há yhwh no-lugar- esta e-eu não eu-conheci');
INSERT INTO verses VALUES (791, 1, 28, 17, 'e-ele-teve-medo E-disse que terrível o-lugar esta não-há que porque se- casa Elohim vezeh portão-de os-céus');
INSERT INTO verses VALUES (792, 1, 28, 18, 'e-ele-se-levantou Jacó na-manhã E-tomou a a pedra que nome em-seus-cabelos e-colocou a-ela mártir e-ele-esguichou óleo sobre cabeça-sua:');
INSERT INTO verses VALUES (793, 1, 28, 19, 'E-chamou a nome-de o-lugar o-aquele casa-de El e-então Luz nome-de a-cidade para-o-primeiro-a');
INSERT INTO verses VALUES (794, 1, 28, 20, 'e-ele-estabeleceu Jacó neder dizendo se sera comigo com-mim e-guarda-me no-caminho o-este eu eu indo pão para-mim pão para comer e vestes para-vestir');
INSERT INTO verses VALUES (795, 1, 28, 21, 'e eu voltarei em-peace a casa pai-meu yhwh yhwh a-mim para-elohim');
INSERT INTO verses VALUES (796, 1, 28, 22, 'e-a-stone desta que seti será será casa e-tudo e-todo que tu-darás a-mim para-ti a-make-ten-him para-ti');
INSERT INTO chapters VALUES (29, 1, 29, 35);
INSERT INTO verses VALUES (797, 1, 29, 1, 'e-levantou Jacó seus pés E-andou na-terra filhos-de adiante');
INSERT INTO verses VALUES (798, 1, 29, 2, 'E-viu e-eis a-béria basadeh e-eis- nome três de-ovinos o-vacado que sobre-ela aquela de a-béria aquele be-ajamem-no os-ovinos e-a-pedra grande sobre yhwh o-poço');
INSERT INTO verses VALUES (799, 1, 29, 3, 'e se juntarem- ali todo as ovelhas de-cima-de a a pedra de-sobre boca-de o poço e bebessem- a do-rebanho e devolvessem- a a pedra sobre yhwh a-o-berço no seu lugar:');
INSERT INTO verses VALUES (800, 1, 29, 4, 'E-disse a-eles Jacó meus-irmãos de-onde vós e-disseram de-charan nós-verso');
INSERT INTO verses VALUES (801, 1, 29, 5, 'E-disse a-eles o-conhecer-vós a לבן filho-de Nacor e-disseram conhecemos');
INSERT INTO verses VALUES (802, 1, 29, 6, 'E-disse a-eles pergunta-paz a-ele e-disseram paz e-eis Raquel a-filha-seu -a com o-rebanho');
INSERT INTO verses VALUES (803, 1, 29, 7, 'E-disse eis ainda o-dia grande não tempo foi-recolhido o-pecuarismo o-abasteçam a-o-rebanho e-vão Reu');
INSERT INTO verses VALUES (804, 1, 29, 8, 'e-disseram não nós-podemos até que ye''aspu todo os-toros e-rolariam de-cima-de a-pedra de-sobre boca-de o-cisterna e-abriam-noles o-rebanho');
INSERT INTO verses VALUES (805, 1, 29, 9, 'ainda-aquele falando-é עִמָּם e-Rachel veio com o-rebanho que a-seu-pai que pastoreando ela');
INSERT INTO verses VALUES (806, 1, 29, 10, 'e-houve como-que ver Jacó a Rachel filha-de sua-mãe Ai mãe-dele e-a sua-mãe Laban Ai mãe-dele e-veio-aproximar-se de-cima-de e-ele-arrastou a a-pedra de-sobre boca-de a-o-poço sua-mãe a rebanho Laban irmão-de mãe-de ele');
INSERT INTO verses VALUES (807, 1, 29, 11, 'e-ele-beijou Jacó para-Rachel e-levantou a seu-grito וַיֵּֽבְךְּ׃');
INSERT INTO verses VALUES (808, 1, 29, 12, 'e-anunciou Jacó para-Rachel que a-chi pai-dela ele e-que filho-de ele ele e-ela-correu e-ela-contou para-seu-pai');
INSERT INTO verses VALUES (809, 1, 29, 13, 'e-houve quando-ouviram Labao a ouviu Jacó filho-de sua irmã e-correu para encontrá-lo e beijou-o a-ele e beijou-o a-ele e ele o trouxe a casa-dele e contou a Laban a todo as-palavras as estas');
INSERT INTO verses VALUES (810, 1, 29, 14, 'E-disse a-ele la-van somente meu-carne e-minha-carne tu e-habitou com-ele novo dias');
INSERT INTO verses VALUES (811, 1, 29, 15, 'E-disse a Laban a-Jacó por que tu tu e servir-me-ia sem-recompensa a-mim para-mim que- de tua remuneração');
INSERT INTO verses VALUES (812, 1, 29, 16, 'e a Laban duas filhas nome a grande Lia e-nome-de a pequena Rachel:');
INSERT INTO verses VALUES (813, 1, 29, 17, 'e vossos olhos Lea frágeis e Rachel era fará-te será chamada vista aparência');
INSERT INTO verses VALUES (814, 1, 29, 18, 'e-ele-amou Jacó a E-disse E-disse e-abadcha- sete dois be-Rachel- bitcha- ha-katanna-');
INSERT INTO verses VALUES (815, 1, 29, 19, 'E-disse para-branco bom titi- aquela para-ti de-me a-ela a homem-de acher cativeiro comigo');
INSERT INTO verses VALUES (816, 1, 29, 20, 'e-serveu Jacó em-Rachel sete dois e-foram na-sua-vista como-dias umidos na-sua-amor a-ela');
INSERT INTO verses VALUES (817, 1, 29, 21, 'E-disse Jacó a para-Lavan venha que a-minha-mulher porque preencheram meus-dias e-eu-virei a-ela');
INSERT INTO verses VALUES (818, 1, 29, 22, 'e-reuniu-se Lavan a todo homens-de o-lugar E-fez banquete');
INSERT INTO verses VALUES (819, 1, 29, 23, 'e-houve na-noite E-tomou a para-Lea e-trouxe E-veio a-ele a-ela E-veio a-ela');
INSERT INTO verses VALUES (820, 1, 29, 24, 'E-colocou Lavan para-ela a זִלְפָּ֖ה sua-escrava para-Lea filha-dele escrava');
INSERT INTO verses VALUES (821, 1, 29, 25, 'e-houve em-a-manhã e-eis- ela E-disse E-disse a para-branco a-mim esta-coisa fizeste para-mim não- em-Rachel trabalhei-eu contigo e-para-que enganaste-me');
INSERT INTO verses VALUES (822, 1, 29, 26, 'E-disse la-van não será-feito assim em-nos a-dar a-pequena diante-de a-primeira');
INSERT INTO verses VALUES (823, 1, 29, 27, 'enchei sete esta e-daremos a-ti também a esta em-trabalho comigo trabalharás comigo ainda sete- dois outras');
INSERT INTO verses VALUES (824, 1, 29, 28, 'E-fez Jacó assim e-cheio-o sete esta e-ele-deu para-ele a a-ele a-filha-seu para-ele para-mulher');
INSERT INTO verses VALUES (825, 1, 29, 29, 'E-colocou para-Laban para-Rachel filha-o a bilhah escrava-o para-ela para-escrava');
INSERT INTO verses VALUES (826, 1, 29, 30, 'E-veio também a Rachel e-ele-amou também a Rachel de-maça e-ele-serviu com-ele mais sete- dois outras');
INSERT INTO verses VALUES (827, 1, 29, 31, 'E-viu yhwh porque odiada a-Leah e-abriu a misericórdia-a וְרָחֵ֖ל estér-verso');
INSERT INTO verses VALUES (828, 1, 29, 32, 'e-ela-concebeu Lea e-deu-à-luz filho e-chamou nome-de-ele Rúben que disse-a porque yhwh yhwh que porque agora que-me-amaria meu-homem-verso');
INSERT INTO verses VALUES (829, 1, 29, 33, 'e-ela-concebeu mais e-deu-à-luz filho E-disse porque yhwh yhwh eu des-amada-a eu e-ele-deu a-mim também a esta e-chamou nome-de-ele Simeão');
INSERT INTO verses VALUES (830, 1, 29, 34, 'e concebeu mais e-deu-à-luz filho E-disse agora desta-vez ela dará à luz marido-meu a-mim porque a-ele a-ele filhos filhos sobre assim קָרָֽא־ tomou Levi');
INSERT INTO verses VALUES (831, 1, 29, 35, 'e-ela-concebeu ainda e-deu-à-luz filho E-disse desta-vez odeh a yhwh sobre assim chamou-a nome-de-ele Judá e-ela-ficou-em-pé deu-à-luz');
INSERT INTO chapters VALUES (30, 1, 30, 43);
INSERT INTO verses VALUES (832, 1, 30, 1, 'E-viu Raquel que não deu-à-luz a-Jacob e-ela-invegou-a Rachel em-a-irmã-a E-disse a Jacó filhos para-mim filhos eu não morreu-a eu');
INSERT INTO verses VALUES (833, 1, 30, 2, 'e-acendeu-se- nariz Jacó E-disse E-disse acaso-debaixo eu eu que impediu-o de-teu fruto-de בָֽטֶן׃');
INSERT INTO verses VALUES (834, 1, 30, 3, 'E-disse eis minha-escrava Bilha veio para-ela [וְתֵלֵד֙] sobre as-joelhos e-elevarei também eu de-elas');
INSERT INTO verses VALUES (835, 1, 30, 4, 'e-deu para-ele a Bilha sua-escrava para-mulher E-veio para-ela Jacó');
INSERT INTO verses VALUES (836, 1, 30, 5, 'e-concebeu Bilha e-deu-à-luz para-JaŃob filho');
INSERT INTO verses VALUES (837, 1, 30, 6, 'E-disse Raquel Dan-ni Elohim e-também ouviu com-a-minha-voz e-ele-deu filho filho sobre assim chamou-a nome-de-ele dan');
INSERT INTO verses VALUES (838, 1, 30, 7, 'e-ela-concebeu ainda e-ela-pariu Bilha שִׁפְחַ֣ת Raquel filho segundo a-Jacob');
INSERT INTO verses VALUES (839, 1, 30, 8, 'E-disse Raquel Nefetolei Elohim eu-fui-concebido com irmã-de-mim também pude e-chamou seu-nome nafthal-i');
INSERT INTO verses VALUES (840, 1, 30, 9, 'E-viu Lea que está-estando de-parir e-tomou a zilfa e-deu e-deu ela a-aquele-de-Jacob para-mulher');
INSERT INTO verses VALUES (841, 1, 30, 10, 'e-deu-à-luz זִלְפָּ֛ה shifchat Lea a-aquele-de-Jacob filho');
INSERT INTO verses VALUES (842, 1, 30, 11, 'E-disse Lea e-chamou a nome-de-ele Gad');
INSERT INTO verses VALUES (843, 1, 30, 12, 'e-deu-à-luz zilfa שִׁפְחַ֣ת a-Lea filho segundo a-Jacob');
INSERT INTO verses VALUES (844, 1, 30, 13, 'E-disse a-Lea em-Aser que abençoa-me filhas e-chamou a nome-de-ele que');
INSERT INTO verses VALUES (845, 1, 30, 14, 'E-andou Reuven- em-dias-de ceifa-de trigo e-achou dudais e-trouxe eles a-eles sua-mãe E-disse mãe-dele e ela disse Raquel a Lea dá-me- por-favor para-mim de-dudais seu filho:');
INSERT INTO verses VALUES (846, 1, 30, 15, 'E-disse para-ela Ha''me''at Kach''tek a meu-homem também também a E-disse filhos-de e-ela-disse raquel portanto dormirá debaixo a-noite sob dois em-o-filho-teu');
INSERT INTO verses VALUES (847, 1, 30, 16, 'E-veio Jacó de o-campo [וַתֵּצֵ֨א] vatese Леах E-disse e-disse a-mim-adai que porque alugar te-aluguei em-dudaei filhos-de com-ela com-ela ele ela');
INSERT INTO verses VALUES (848, 1, 30, 17, 'E-ouviu Elohim a לאה e-ela-concebeu e-deu-à-luz filho filho quinto');
INSERT INTO verses VALUES (849, 1, 30, 18, 'E-disse Lea dar Elohim sacrário que dei shefachatí le-ishi e-chamou nome-de-ele Yissachar');
INSERT INTO verses VALUES (850, 1, 30, 19, 'vat-hahr ainda le-Ahá e-deu-à-luz filho-de sexto l-Ya''akov');
INSERT INTO verses VALUES (851, 1, 30, 20, 'E-disse Lea zvadani Elohim oti zeved bom bom desta-vez meu-homem porque nasci- a-ele seis filhos e-chamou a nome-de-ele Zevulun-');
INSERT INTO verses VALUES (852, 1, 30, 21, 'e-depois yalda bat e-chamou a shema-ha- dinah');
INSERT INTO verses VALUES (853, 1, 30, 22, 'e-le-lembrou Elohim a Raquel E-ouviu El Elohim e-abriu a útero-dela');
INSERT INTO verses VALUES (854, 1, 30, 23, 'e-concebeu e-deu-à-luz filho E-disse ele-reuniu Elohim a minha-ignomínia-:');
INSERT INTO verses VALUES (855, 1, 30, 24, 'e-ele-chamou-a a nome-dele dizendo dizendo yhwh yhwh filho filho outro');
INSERT INTO verses VALUES (856, 1, 30, 25, 'e-houve como ela-deu-à-luz Rachel a E-disse E-disse Jacó a la-van envia-me-o e-eu-i-darei a meu-lugar e-para-a-minha-terra');
INSERT INTO verses VALUES (857, 1, 30, 26, 'tinha a meus-homens e-a meus-filhos que servi a-você que tu porque tu soubeste a minha-servidão que servi-a-você');
INSERT INTO verses VALUES (858, 1, 30, 27, 'E-disse a-ele la-van se por-favor encontrei graça em-olhos-teus temi yhwh yhwh por-causa-de-você');
INSERT INTO verses VALUES (859, 1, 30, 28, 'E-disse fêmea sacrá-te sobre-mim e-eu-darei');
INSERT INTO verses VALUES (860, 1, 30, 29, 'E-disse a-ele tu soubeste a que servir-te-ei e-a que foi de-tua-herdade comigo:');
INSERT INTO verses VALUES (861, 1, 30, 30, 'que pouco que a-ti para-ti diante-de-mim e-ele-rompeu E-abençoou yhwh yhwh a-ti e-agora e-agora quando eu-farei também eu para-casa-meu');
INSERT INTO verses VALUES (862, 1, 30, 31, 'E-disse que darei E-disse E-disse Jacó não dará- para-mim dizia-se se fazer- para-mim a-palavra esta retornarei rebanho-vosso');
INSERT INTO verses VALUES (863, 1, 30, 32, '[אֽ͏ֶעֱבֹ֨ר] em-todo o-dia o-dia [מִשָּׁ֜ם] de-lá todo [נָקֹ֣ד] [וְטָל֗וּא] [וְכָל־שֶׂה־חוּם֙] e-todo [וְטָל֥וּא] [וְנָקֹ֖ד] em-os-burros e-errado e-pagará em-as-caças e-foi meu-salário');
INSERT INTO verses VALUES (864, 1, 30, 33, 'e-responderá-a em-mim minha-justiça em-dia-de amanhã porque viras sobre meu-salário diante-de-ti todo que não-há punido e pendurado ele e a chama nos calores roubado ele comigo:');
INSERT INTO verses VALUES (865, 1, 30, 34, 'E-disse Labao eis se haja segundo a tua palavra:');
INSERT INTO verses VALUES (866, 1, 30, 35, 'e tirou no-dia aquele a as feras os acorrentados e os pendurados e-a todo as-azim as-nukdot e-hateluot todo que laban E-colocou e-todo chum bakashvim E-deu por-mão-de banayo');
INSERT INTO verses VALUES (867, 1, 30, 36, 'e-ele-postou o-caminho-de três-de dias entre-o e-entre Jacó e-Jacob apascentando a rebanho Laban os-restantes-verso');
INSERT INTO verses VALUES (868, 1, 30, 37, 'e-tomou a-ele Jacó bastão para-Bet-Lehem ao-leite e-Luz e-Ermon e-esculpiu nelas ПЦАЛОТ para-feminino-de-leite de-esfola [אֲשֶׁ֖ר] que sobre');
INSERT INTO verses VALUES (869, 1, 30, 38, 'וַיַּצֵּ֗ג a הַמַּקְלוֹת֙ que פִּצֵּ֔ל בָּרֳהָטִ֖ים as-águas as-águas que תָּבֹ֨אןָ הַצֹּ֤אן לִשְׁתּוֹת֙ para-a vista o-rebanho e se aqueceram no Bóan lishtho');
INSERT INTO verses VALUES (870, 1, 30, 39, 'e se aqueceram a-o-rebanho a as madeiras e deu à luz o-rebanho acoados ponteados e os tuleus:');
INSERT INTO verses VALUES (871, 1, 30, 40, 'e-os-que-pastoreiam separou Jacó E-colocou face-de o-rebanho a acorrentado e-todo quentou em-o-rebanho Laban sozinho para-ele adárim para-somente-dele e-não shatam sobre rebanho lavan');
INSERT INTO verses VALUES (872, 1, 30, 41, 'e-foi em-todo yahem ha-tson ham-mequshshuroth e puser Jacó a ham-makloth para-olhos-de a-o-rebanho barohtim leyahmenah bam-makloth');
INSERT INTO verses VALUES (873, 1, 30, 42, 'ú-bê-ha-ât-if a-o-rebanho não yash-im e-era hâ-âtûp-im lê-lavân vâ-ha-kshûr-im lê-yâ-akô:');
INSERT INTO verses VALUES (874, 1, 30, 43, 'e se espalhou o homem muito muito e-foi a-ele ovelhas muitas e escravas e servos e-camelenhos e-jumentos');
INSERT INTO chapters VALUES (31, 1, 31, 54);
INSERT INTO verses VALUES (875, 1, 31, 1, 'E-ouviu a palavras de dizendo tomou dizendo tomou Jacó a todo que nossos pais e do que nossos pais fez a todo a glória a-esta');
INSERT INTO verses VALUES (876, 1, 31, 2, 'E-viu Jacó a face-de Laban e-eis não-ele com-ele como-ontem terceiro-dia');
INSERT INTO verses VALUES (877, 1, 31, 3, 'E-disse yhwh a Jacó shuv a terra os-teus-pais e-para-a-tua-nascimento contigo');
INSERT INTO verses VALUES (878, 1, 31, 4, 'e-enviou Jacó E-chamou para-Rachel e-para-Lea o-campo a seu rebanho');
INSERT INTO verses VALUES (879, 1, 31, 5, 'E-disse para-as-mesmas viu eu a face-de abichen porque não-ela a-mim kitemol e-hoje ser comigo foi comigo-');
INSERT INTO verses VALUES (880, 1, 31, 6, 've-atenah yedanten que em-todo kochi avadhti a abichen');
INSERT INTO verses VALUES (881, 1, 31, 7, 'va-abichen hetel em-mim ve-hechelif a minha recompensa dez moedos e-nao- nethavô comigo leharaá comigo-');
INSERT INTO verses VALUES (882, 1, 31, 8, 'se assim dará-dize será será shecarécha veyaldû todo a-o-rebanho nequdîm e-se será dará-dize aquddîm será shecarécha veyaldû todo a-o-rebanho aquddîm');
INSERT INTO verses VALUES (883, 1, 31, 9, 'e-economizou Elohim a de-o-rebanho seu-pai e-ele-deu para-mim');
INSERT INTO verses VALUES (884, 1, 31, 10, 'e-houve na-época quando-fervia o-rebanho e-elevei meus-olhos e-eu-vi em-o-sonho e-eis os-pescoins que-subiam sobre o-rebanho acorrentados pontilhados e-vestidos-de-vermelho');
INSERT INTO verses VALUES (885, 1, 31, 11, 'E-disse a-mim anjo o-Elohim em-o-sono יַעֲקֹב e-disse eis-me');
INSERT INTO verses VALUES (886, 1, 31, 12, 'E-disse sair- por-favor os-teus-olhos וּרְאֵה֙ todo os-pescoins os-elevados sobre o-rebanho que pontilhados e-vestidos-de-vermelho porque רָאִ֔יתִי a todo que Laban fez para-ti');
INSERT INTO verses VALUES (887, 1, 31, 13, 'eu o-elohim casa-de El que ungiu-te nome מַצֵּבָ֔ה que a-mim para-mim nome voto agora levantou sai de a-terra a-esta e-volta a terra de-tua-nascimento');
INSERT INTO verses VALUES (888, 1, 31, 14, 'e-ela-respondeu Raquel e-Lea e-disseram a-ele ainda para-nós uma-parte e herança em-casa-de אָבִֽינוּ׃');
INSERT INTO verses VALUES (889, 1, 31, 15, 'não estrangeiras somos-contadas a-ele que vendido-nos e-comeu também comer a em-o-nos-ouro');
INSERT INTO verses VALUES (890, 1, 31, 16, 'que todo o-abundância que livrou Elohim de-a-no-s ele ele e-agora e-agora todo disse disse Elohim a-ti fez');
INSERT INTO verses VALUES (891, 1, 31, 17, 'E-levantou Jacó e-ele-levantou a seus-filhos e-a suas mulheres: sobre os-camelo');
INSERT INTO verses VALUES (892, 1, 31, 18, 'e-ele-dirigiu a todo seu-patrimônio e-a todo suas-propriedades que riquezas patrimônio propriedades que racah seu-pai Arã lavo a Isaque pai-dele na-terra כְּנָֽעַן');
INSERT INTO verses VALUES (893, 1, 31, 19, 've-la-van andar ligezoz a tsono-o vategnove Rachel a haterefim que le-aviha');
INSERT INTO verses VALUES (894, 1, 31, 20, 'vayignove Jacó a coração Laban haarami declarou a-ele que a-ele ele fugindo ela');
INSERT INTO verses VALUES (895, 1, 31, 21, 'e fugiu ele e-todo que a-ele E-levantou vayaavor a o-rio e-colocou a sua-face monte-de o-Gileade');
INSERT INTO verses VALUES (896, 1, 31, 22, 'e-ele-foi-dito para-Lavan no-dia o terceiro que correu Jacó');
INSERT INTO verses VALUES (897, 1, 31, 23, 'E-tomou a irmãos-de-ele com-ele e-ele-perseguiu o-caminho-de caminho sete dias ele ele em-monte-de o-Gileade');
INSERT INTO verses VALUES (898, 1, 31, 24, 'E-veio Elohim a Labão o arameu a-noite E-disse a-ele para-ele a-ti para-ti para-que-não fale com Jacó de bom até mau');
INSERT INTO verses VALUES (899, 1, 31, 25, 'e-ele-alcançou Laban a Jacó e-Jacob colocou a a-aholuo no monte e-Lavan colocou a seus-irmãos em-monte-de o-Gileade');
INSERT INTO verses VALUES (900, 1, 31, 26, 'E-disse Labão a-Jacó que oashtata roubou a meu coração administrou a minhas filhas como prisioneiras espada');
INSERT INTO verses VALUES (901, 1, 31, 27, 'por-que escondida-estás para-fugir e-você-roubou a-mim e-não a-mim para-mim e-eu-te-enviei ВШМАХА УВШРИМ ВТОФ УБКИНОР');
INSERT INTO verses VALUES (902, 1, 31, 28, 'e-não НЕТАШТНИ ЛЕНАШК ЛЕВАНИ ВЛИБНОТАИ agora היסכלת עשׂו׃');
INSERT INTO verses VALUES (903, 1, 31, 29, 'há para-o-elohim minha-mão para-fazer mal mau וֽאֱלֹהֵ֨י אֲבִיכֶ֜ם אֶ֣מֶשׁ ׀ disse a-mim-adai dizendo הישמר a-ti מדדבר com Jacó מצוב até mau');
INSERT INTO verses VALUES (904, 1, 31, 30, 'e-agora andou e-você-andou porque ניכסוף ניכספה para-casa-de pai-teu por-que גנבת a yhwh');
INSERT INTO verses VALUES (905, 1, 31, 31, 'e-respondeu Jacó E-disse ללבן que ירcai que eu-disse para-que-não תגזור a בנותיך מעמי׃');
INSERT INTO verses VALUES (906, 1, 31, 32, 'povo que será-encontrada a não não diante em-frente-de אחינו הכר־ comigo que עםדי וקח־ que e-não conheceu Jacó porque Rachel gananbatam:');
INSERT INTO verses VALUES (907, 1, 31, 33, 'E-veio lavan em-tenda Jacov ⚩ e no telhado Lea e no telhado duas-de as servas e-não acharam encontrou do telhado a-Leá E-veio em-tenda Rachel:');
INSERT INTO verses VALUES (908, 1, 31, 34, 'וְרָחֵ֞ל לָקְחָ֣ה a הַתְּרָפִ֗ים וַתְּשִׂמֵ֛ם בְּכַ֥ר הַגָּמָל e-ela-sentou-se sobre-eles וַיְמַשֵׁ֥שׁ לָבָ֛ן a encontrou ha-o-hel e-não מָצָֽא׃');
INSERT INTO verses VALUES (909, 1, 31, 35, 'E-disse a אָבִ֗יהָ a se encolerizou que Adonai porque não posso arising diante de ti porque caminho mulheres encontrou e procurou e-não achar a as terafins');
INSERT INTO verses VALUES (910, 1, 31, 36, 'se encolerizou para-Iaquóv e discutiu בלאבן e-respondeu Jacó E-disse llelaban que o-que מה que porque דלקת depois-de-mim');
INSERT INTO verses VALUES (911, 1, 31, 37, 'porque misiónsshat a de-toda כלאי que מצאת diante objetos-de ביתך foi-posto entre diante-de meus-irmãos ואחייך ויחכו entre שְׁנֵֽינוּ׃');
INSERT INTO verses VALUES (912, 1, 31, 38, 'זֶה֩ vinte שָׁנָ֤ה eu contigo רְחֵלֶ֥יךָ וְעִזֶּ֖יךָ não שִׁכֵּ֑לוּ וְאֵילֵ֥י צֹאנְךָ֖ não אָכָֽלְתִּי׃');
INSERT INTO verses VALUES (913, 1, 31, 39, 'טְרֵפָה֙ não היביתי eu eu אחתנה מיידי תבקשנה dia dia noite noite');
INSERT INTO verses VALUES (914, 1, 31, 40, 'היהתי ביום אכלני חרוב KERACH בלילה ela se entristeceu minha vida dos meus olhos:');
INSERT INTO verses VALUES (915, 1, 31, 41, 'este para mim vinte ano em tua casa servi-te quatro quinze ano nas duas filhas tuas e-seis dois no teu rebanho e trocou a minha recompensa dez em moedas:');
INSERT INTO verses VALUES (916, 1, 31, 42, 'se não fosse Elohim-de meu pai Elohim-de Abraão e medo Isaque ser a-mim que agora vazio enviasse-me a minha miséria e-a ver palma-de-mao-minha viu Elohim e repreendeu amem:');
INSERT INTO verses VALUES (917, 1, 31, 43, 'e-ele-respondeu lavan E-disse a Jacó as filhas minhas filhas e os filhos filhos-de e o gado e-tudo e-todo que tu viu para-mim- ele o-dia que faça para estes o-dia ou para seus filhos que geraram:');
INSERT INTO verses VALUES (918, 1, 31, 44, 'e-agora לְכוּ נִכְרְתָה berith eu וָאָ֑תָה e-acontecerá לְעֵ֖ד entre-mim וּבֵינֶֽךָ׃');
INSERT INTO verses VALUES (919, 1, 31, 45, 'E-tomou Jacó pedra וַיְרִימֶ֖הָ מַצֵּבָֽה׃');
INSERT INTO verses VALUES (920, 1, 31, 46, 'E-disse Jacó לְאֶחָיו֙ לִקְט֣וּ de-pedras וַיִּקְח֥וּ אבנים e-ele-fizeram- גל ואכלו nome sobre הגל׃');
INSERT INTO verses VALUES (921, 1, 31, 47, 'e ele chamou a-ele la-van יגאר שודאות chamou a-ele a-ele גלעד׃');
INSERT INTO verses VALUES (922, 1, 31, 48, 'E-disse la-van הגל זה até entre-mim ובינך o-dia sobre assim קָרָֽא־ nome-de-ele גלעד׃');
INSERT INTO verses VALUES (923, 1, 31, 49, 'וְהַמִּצְפָּה֙ que disse יִ֥צֶף yhwh entre-mim e-entre-tu que נִסָּתֵ֖ר homem מֵרֵעֵֽהוּ׃');
INSERT INTO verses VALUES (924, 1, 31, 50, 'se תְּעַנֶּ֣ה a filhas-minhas e-se תִּקַּ֤ח mulheres sobre בְּנֹתַ֔י nao-ha homem com-nosso viu Elohim até entre-mim וּבֵינֶֽךָ׃');
INSERT INTO verses VALUES (925, 1, 31, 51, 'E-disse Laban לְיַעֲקֹ֑ב eis הַגַּ֣ל este e-eis הַמַצֵּבָ֔ה que יָרִ֖יתִי entre-mim וּבֵינֶֽךָ׃');
INSERT INTO verses VALUES (926, 1, 31, 52, 'até הַגַּ֣ל este וְעֵדָ֖ה הַמַּצֵּבָ֑ה se eu não אֽ͏ֶעֱבֹ֤ר a-ti a הַגַּ֣ל este e-se אַתָּה não תַעֲבֹ֨ר a-mim a הַגַּ֥ל e-a הַמַּצֵּבָ֥ה a-esta לְרָעָֽה׃');
INSERT INTO verses VALUES (927, 1, 31, 53, 'Elohim-de Abraão וֵֽאלֹהֵ֤י nachor יִשְׁפְּט֣וּ בֵינֵ֔ינוּ Elohim-de pai-deles וַיִּשָּׁבַ֣ע Jacó בְּפַ֖חַד seu-pai Isaque');
INSERT INTO verses VALUES (928, 1, 31, 54, 'e ofereceu Jacó oferta no monte E-chamou a seus irmãos para comer pão pão Belém e-acamparam-se na-montanha');
INSERT INTO chapters VALUES (32, 1, 32, 33);
INSERT INTO verses VALUES (929, 1, 32, 1, 'e-ele-se-levantou lavan na-manhã e beijou ל-בָ-נוֹי e suas filhas E-abençoou a eles E-andou e-voltou Laban para-lugar-dele');
INSERT INTO verses VALUES (930, 1, 32, 2, 'e Jacó andar em sua jornada e encontraram-se em-ele mensageiros-de Elohim');
INSERT INTO verses VALUES (931, 1, 32, 3, 'E-disse Jacó como-que ראמים acampamento-de Elohim esta E-chamou nome-de o-lugar o-aquele מֽ͏ַחֲנָֽיִם׃');
INSERT INTO verses VALUES (932, 1, 32, 4, 'e-enviou Jacó mensageiros diante-dele a Esaú irmão-dele na-terra Seir campo-de Edom');
INSERT INTO verses VALUES (933, 1, 32, 5, 'E-ordenou eles dizendo assim תאמרון לאדוני לעשו assim disse seu-escravo-teu-servo Jacó com לבן גרתי ואחר até agora');
INSERT INTO verses VALUES (934, 1, 32, 6, 'e-foi a-mim bovino וחמר CKER E servo E serva E enviarei para-dizer para-o-meu-adonai para buscar- graça em-olhos-teus');
INSERT INTO verses VALUES (935, 1, 32, 7, 'e-voltaram-se os-anjos a dizendo dizendo vimos-nos a irmão-teu a Esaú e-também andou para te ver e-quatro-de centenas homem com-ele-verso');
INSERT INTO verses VALUES (936, 1, 32, 8, 'e temeu Jacó muito e se encolheu a-ele e partiu-se a o-povo que com-ele e-a o-rebanho e-a o-bóqar e-hagamallim para-dois cânoth:');
INSERT INTO verses VALUES (937, 1, 32, 9, 'E-disse se virá ê-sav a a-machnê a-achath e-hikkahu e será a-machnê hênissê''ar liflitâ:');
INSERT INTO verses VALUES (938, 1, 32, 10, 'E-disse Jacó Elohim-de pai-meu Abraão וֵאלֹהֵ֖י pai-meu Isaque yhwh הָאֹמֵ֣ר a-mim שׁ֧וּב לְאַרְצְךָ֛ וּלְמוֹלַדְתְּךָ֖ וְאֵיטִ֥ibal contigo');
INSERT INTO verses VALUES (939, 1, 32, 11, 'קָטֹ֜nְתִּי de-toda הַחֲסָדִים֙ e-de-todo הָ֣אֱמֶ֔ת que fiz-te- que servo-teu porque בְמַקְלִ֗i עָבַ֙רְתִּי֙ e-agora o-Jordão este e-agora estava para-dois cânoth:');
INSERT INTO verses VALUES (940, 1, 32, 12, 'הַצִּילֵ֥נִי por-favor de-mão-de irmão-meu da-mão-de Esaú porque eu ele a-ele para-que-não mãe וְהִכַּ֔נִי mãe sobre filhos');
INSERT INTO verses VALUES (941, 1, 32, 13, 'e-tu tu-disseste הֵיטֵ֥ב אֵיטִ֖יב contigo וְשַׂמְתִּ֤י a zera-ka o-mar o-mar que não será-contado de-multidão');
INSERT INTO verses VALUES (942, 1, 32, 14, 'וַיָּ֥לֶן nome na-noite aquele E-tomou de הַבָּ֧א בְיָד֛וֹ oferta לְעֵשֹׁו irmão-dele');
INSERT INTO verses VALUES (943, 1, 32, 15, 'עִזִּים מָאתַיִם וּתְיָשִׁים vinte רְחֵלִים duzentos וְאֵילִים vinte');
INSERT INTO verses VALUES (944, 1, 32, 16, 'גְּמַלִּים מֵינִיקֹות e-seus-filhos שְׁלֹשִׁים פָּרֹות quarenta e jumentos dez as donzelas vinte e camelos dez');
INSERT INTO verses VALUES (945, 1, 32, 17, 'E-colocou por-mão-de seus-servos troupe sozinho E-disse E-disse a seus-servos passai diante-de-mim entre e levai e-entre troupe e-entre Eder');
INSERT INTO verses VALUES (946, 1, 32, 18, 'E-ordenou a dizendo que porque  se encontrar: Esaú  meu irmão: dizendo dizendo para-quem- andarás e-onde Estas  e para quem: estes diante-de-você.');
INSERT INTO verses VALUES (947, 1, 32, 19, 'e-dirás para-o-teu-escravo a-Jacó oferta-cereais ela mensageiro: a meu senhor: a Edom: e-eis também ele depois de nós:');
INSERT INTO verses VALUES (948, 1, 32, 20, 'E-ordenou também a também também também o-terceiro também a dizendo  os que vão: atrás-de  os camelos: dizendo como-palavra ele תְּדַבְּר֣וּן a Esaú בְּמֹצַאֲכֶ֖ם a-ele');
INSERT INTO verses VALUES (949, 1, 32, 21, 'e-vós-direis também eis avadcha Jacó אַחֲרֵ֑ינוּ porque disse אֲכַפְּרָ֣ה פָנָ֗יו בַּמִּנְחָה֙ הַהֹלֶ֣כֶת לְפָנָ֔י e-depois-de assim eu-verei פָנָ֔יו אוּלַ֖י e-le-va face-de');
INSERT INTO verses VALUES (950, 1, 32, 22, 'e passou a oferenda sobre perante-ele e-ele nós na noite— o-aquele no-lager');
INSERT INTO verses VALUES (951, 1, 32, 23, 'e-elevantou-se- na-noite ele ele E-tomou duas suas mulheres e-a duas sas servas e-a um dez seus filhos e passou a passageiro Jacó.');
INSERT INTO verses VALUES (952, 1, 32, 24, 'e tomou-os e passou-os a o rio e passou a que lhe:');
INSERT INTO verses VALUES (953, 1, 32, 25, 'e ficou Jacó sozinho e lutou homem com-ele até subida o amanhecer:');
INSERT INTO verses VALUES (954, 1, 32, 26, 'E-viu que não pode-r a-ele e tocou com-a-palma- em-seu-reto e-foçou planta-de coxa Jacó em-seu-rosto com-ele-verso');
INSERT INTO verses VALUES (955, 1, 32, 27, 'E-disse envia-me que subir na-madrugada E-disse não que-envie-te que se abençoe-me');
INSERT INTO verses VALUES (956, 1, 32, 28, 'E-disse a-ele que E-disse E-disse Jacó');
INSERT INTO verses VALUES (957, 1, 32, 29, 'E-disse não Jacó será-dito ainda seu-nome que se Israel porque reisaste com Elohim e-com- homens e foi capaz');
INSERT INTO verses VALUES (958, 1, 32, 30, 'ele perguntou Jacó E-disse diga-a agora E-disse E-disse por-que isto perguntaste E-abençoou ele ele nome');
INSERT INTO verses VALUES (959, 1, 32, 31, 'E-chamou Jacó nome o-lugar Penael porque vi Elohim face a face e foi derrotada alma-de-mim');
INSERT INTO verses VALUES (960, 1, 32, 32, 'ele lançou a-ele o-sol como passou a Penael e-ele quebrando sobre fétero');
INSERT INTO verses VALUES (961, 1, 32, 33, 'sobre assim não comerão filhos-de Israel a gide até o-dia sobre que tocar até o-dia este porque tangendo com-a-palma- coxa Jacó no gide a vaca');
INSERT INTO chapters VALUES (33, 1, 33, 20);
INSERT INTO verses VALUES (962, 1, 33, 1, 'e-ele-leva Jacó os-seus-olhos E-viu e-eis Esaú veio e com ele quatro centenas homem e partiu a os filhotes sobre Lea e-sobre Rachel e-sobre duas-de as-safachot:');
INSERT INTO verses VALUES (963, 1, 33, 2, 'e-ele-posto a as-safachot: e-a seus-nascidos primeira e-a Lea e-seus-nascidos últimos e-a e-a José últimos:');
INSERT INTO verses VALUES (964, 1, 33, 3, 'e-ele passou em-frente-de-eles e-adoraram terra sete vezes até ele entrou até irmão-dele');
INSERT INTO verses VALUES (965, 1, 33, 4, 'e-ele-correu Esaú para ele e abraçou-o e-caiu sobre seu pescoço e-choraram');
INSERT INTO verses VALUES (966, 1, 33, 5, 'e levantou a E-viu E-viu a E-disse e-a as crianças E-disse quem estes para-ti E-disse as crianças que e foi grato Elohim a servo-teu');
INSERT INTO verses VALUES (967, 1, 33, 6, 'e se aproximaram as-safachot: aqui e suas filhas e se prostraram');
INSERT INTO verses VALUES (968, 1, 33, 7, 'e se aproximou também a Lea e suas filhas e se prostraram e-depois se aproximou José וְרָחֵ֖ל וַיִּֽשְׁתַּחֲוֽוּ׃');
INSERT INTO verses VALUES (969, 1, 33, 8, 'E-disse quem a-ti todo a-machnê este que E-disse E-disse para buscar- graça em-olhos-de Adonai');
INSERT INTO verses VALUES (970, 1, 33, 9, 'E-disse Esaú há a-mim muito haja a-ti a-ti que para-ti');
INSERT INTO verses VALUES (971, 1, 33, 10, 'E-disse Jacó a por-favor se por-favor encontrei graça em-tua-olho e-toma que de-mim porque sobre כֵּ֞ן face-de tua-face כִּרְאֹ֛ת face-de Elohim וַתִּרְצֵֽנִי׃');
INSERT INTO verses VALUES (972, 1, 33, 11, 'toma por-favor a בִּרְכָתִי֙ para-ti הֻבָ֣את para-ti porque חַנַּ֥נִי Elohim e-porque há para-mim- todo e-ele-precipitar-se nele E-tomou');
INSERT INTO verses VALUES (973, 1, 33, 12, 'E-disse NSSʻa e neleḵā e elka para negdekā');
INSERT INTO verses VALUES (974, 1, 33, 13, 'E-disse a-ele Adonai sabe porque hayladim rakkim e haṣzon e habbakar alot sobre mim dia um um vametu todo o-rebanho');
INSERT INTO verses VALUES (975, 1, 33, 14, 'יַעֲבָר־ agora Adonai diante-de seu-escravo e-eu אֶֽתְנָהֲלָ֣ה לְאִטִּ֗י לְרֶ֨גֶל הַמְּלָאכָ֤ה que diante-de-mim até as crianças até que אָבֹ֥א a Adonai שֵׂעִֽירָה׃');
INSERT INTO verses VALUES (976, 1, 33, 15, 'E-disse Esaú אַצִּֽיגָה־ agora im-mekha de o-povo E-disse comigo E-disse por-que זֶּ֔ה encontre graça em-olhos-de Adonai');
INSERT INTO verses VALUES (977, 1, 33, 16, 'va-yashav no-dia o mesmo eu-šeav para-s-seu-caminho se-ʿirah');
INSERT INTO verses VALUES (978, 1, 33, 17, 'e-jaʿaqob viu-se-mover sukatá E-edificou a-ele casa e-para-comprar-lhe fez sukot sobre chamou chamou nome-de o-lugar sukot');
INSERT INTO verses VALUES (979, 1, 33, 18, 'E-veio Jacó שָׁלוֹם cidade שַׂכְמֵ֗ן que em-terra-de Canaã בְּבוֹא֖וֹ מִפַּדַּ֣ן Arã וַיִּחָנֶ֖ה a face-de a-cidade');
INSERT INTO verses VALUES (980, 1, 33, 19, 'וַיִּקְנֶ֣ה a חֵלְקַ֣ת o-campo que estendeu nome אֲהֽוֹלוֹ de-mão-de filhos-de חֲמ֥וֹר pai-de שַׂכְמֵ֑ן em-cem קְשִׂיטָֽה׃');
INSERT INTO verses VALUES (981, 1, 33, 20, 'וַיַּצֶּב־ nome מִזְבֵּ֑חַ vayikra- a-ele El Elohim-de Israel');
INSERT INTO chapters VALUES (34, 1, 34, 31);
INSERT INTO verses VALUES (982, 1, 34, 1, 'e-saiu דִינָה֙ filha-de Lea- que deu-à-luz para-ver para-ver a-terra a-terra');
INSERT INTO verses VALUES (983, 1, 34, 2, 'E-viu ela שְׁכֶ֧ם filho-de חֲמ֛וֹר הֽ͏ַחִוּ֖י a-terra E-tomou E-tomou ela e-ele-deitou a-ela וַיְעַנֶּֽהָ׃');
INSERT INTO verses VALUES (984, 1, 34, 3, 'וַתִּדְבַּ֣ק naphshô בְּדִינָ֖ה בַּֽת־ Jacó וַיֶּֽאֱהַב֙ a a-jovem-a וַיְדַבֵּ֖ר sobre coração הַֽנַּעֲרָֽ׃');
INSERT INTO verses VALUES (985, 1, 34, 4, 'E-disse Siquem a seu-pai dizendo dizendo toma- para-mim a הַיַּלְדָּ֥ה a-esta para-mulher');
INSERT INTO verses VALUES (986, 1, 34, 5, 'וְיַעֲקֹ֣ב ouviu que טִמֵּא֙ a דִּינָ֣ה בִתּ֔וֹ e-filhos-dele foram a de-seu-banhado no-campo e-ha-herish Jacó até ba-am');
INSERT INTO verses VALUES (987, 1, 34, 6, 'va-yetsa Hamor pai-de sh-keim a Jacó para-falar com-ele');
INSERT INTO verses VALUES (988, 1, 34, 7, 'e filhos-de Jacó vieram de o-campo kasham-eim va-tichazu os-homens a-eles muito muito porque nabal fez be-yisra-el li-she-kav não בַּֽת־ Jacó e-assim não יהיה׃');
INSERT INTO verses VALUES (989, 1, 34, 8, 'e-falou חֲמ֥וֹר עם-הם dizendo o-lombo filhos-de 😉 נפשוֹ בתיכם dai-vos agora ela a-ele para-mulher');
INSERT INTO verses VALUES (990, 1, 34, 9, 'והתחטנוּ nós בנותיכם תיתנוּ- para-nós e-a a-vós tomai-vos para-vocês');
INSERT INTO verses VALUES (991, 1, 34, 10, 'e-com-nós vivareis E-a-terra será diante-de-vós voltem-vos e-comerciais-a e-possuam nela');
INSERT INTO verses VALUES (992, 1, 34, 11, 'E-disse shikem a seu-pai e-a sua-irmão encontre graça em-os-vossos-olhos e-que dizeis-vos para-mim אֶתְנָה');
INSERT INTO verses VALUES (993, 1, 34, 12, 'הַרְבּוּ sobre-mim muito מֹ֣הַר וּמַתָּ֔ן וְאֶ֨תְּנָ֔ה como-que תֹּאמְר֖וּ a-mim וּתְנוּ־ para-mim a הַֽנַּעֲרָ֖ para-mulher');
INSERT INTO verses VALUES (994, 1, 34, 13, 'e-responderam filhos-de Jacó a seu-pai e-a χamor Abiú בְּמִרְמָ֖ה וַיְדַבֵּ֑רוּ que טִמֵּ֔א a דִּינָ֥ה אֲחֹתָֽם׃');
INSERT INTO verses VALUES (995, 1, 34, 14, 'e-disseram a-eles não נוּכַל֙ para-fazer a-coisa esta לָתֵת֙ a אֲחֹתֵ֔נוּ לְאִ֖ישׁ que a-ele ela porque חֶרְפָּ֥ה ela para-nós');
INSERT INTO verses VALUES (996, 1, 34, 15, 'somente bázot a-vós a-vós mãe tִּהְי֣וּ kָמֹ֔נוּ a-vós para-vocês todo macho');
INSERT INTO verses VALUES (997, 1, 34, 16, 'vְnָתַ֤נּוּ a a-vós a-vós e-a bְּnֹתֵיכֶ֖ם nִֽקַּֽח־ para-nós vְyָשַׁ֣בְנוּ um vְhָיִ֖ינוּ para-o-povo um');
INSERT INTO verses VALUES (998, 1, 34, 17, 'e-se não tִshְׁmְע֛וּ a-nós para-ser-circuncidado vְlָqַ֥חְנוּ a bִּתֵּ֖נוּ וְהָלָֽכְנוּ׃');
INSERT INTO verses VALUES (999, 1, 34, 18, 'וַיִּֽיטְב֥וּ דִבְרֵיהֶ֖ם aos-olhos-de חֲמ֑וֹר e-em-olhos-de Shekem filho-de חֲמֽוֹר׃');
INSERT INTO verses VALUES (1000, 1, 34, 19, 'e-não אֵחַ֤ר o-menino para fazer que porque חָפֵ֖ץ בְּבַֽת־ Jacó de-toda nobre seu-pai casa pai-seu');
INSERT INTO verses VALUES (1001, 1, 34, 20, 'E-veio חֲמ֛וֹר וּשְׁכֶ֥ם filho-seu a portão Irã e falaram a dizendo Urãm para-dizer');
INSERT INTO verses VALUES (1002, 1, 34, 21, 'os-homens ha-eleh perfeitos eles conosco e se assentarão na-terra e trabalharão a-ela E-a-terra eis Rachabath- duas mãos em-frente-de-eles a suas filhas levaremos lanu a-eles e-a deu para-eles');
INSERT INTO verses VALUES (1003, 1, 34, 22, 'somente בְּ֠זֹאת יֵאֹ֨תוּ לָ֤נוּ os-homens para-habitar אִתָּנוּ para-ser um um בְּהִמּ֥וֹל a-nós todo eles conforme e-ele-s נִמֹּלִֽים׃');
INSERT INTO verses VALUES (1004, 1, 34, 23, 'מִקְנֵהֶ֤ם וְקִנְיָנָם֙ e-todo בְּהֶמְתָּ֔ם não eles eles somente a-eles a-eles וְיֵשְׁב֖וּ com-nos');
INSERT INTO verses VALUES (1005, 1, 34, 24, 'e-ouviram a jumento e-a o-lombo seu-filho todo יֹצְאֵ֖י portão sua cidade e circuncidaram-no todo macho todo que saíam portão-de ir-o');
INSERT INTO verses VALUES (1006, 1, 34, 25, 'e-houve no-dia o-terceiro em sua existência como abraços e-eles-tomaram dois filhos-de Jacó Simão e Levi irmãos Diná homem sua espada e-vieram sobre a-cidade בטַח וַיַּֽהַרְג֖וּ todo macho');
INSERT INTO verses VALUES (1007, 1, 34, 26, 'e-a jumento e-a o-lombo seu-filho eles-mataram à-boca-de espada  וַיִּקְח֧וּ  a  דִּינָ֛ה  de-casa-de sh-keim  וַיֵּצֵֽאוּ׃');
INSERT INTO verses VALUES (1008, 1, 34, 27, 'filhos-de Jacó vieram sobre  הַ֣חֲלָלִ֔ים   וַיָּבֹ֖זּוּ  a-cidade que  טִמְּא֖וּ  irmã-deles');
INSERT INTO verses VALUES (1009, 1, 34, 28, 'a  צֹאנָ֥ם  e-a בְּקָרָ֖ם e-a ve-et que בָּעִ֛יר e-a que no-campo lakahu');
INSERT INTO verses VALUES (1010, 1, 34, 29, 'e-a todo חֵילָ֤ם e-a todo טַפָּם֙ e-a נְשֵׁיהֶ֔ם שָׁב֖וּ וַיָּבֹ֑זּוּ e-a todo que na-casa');
INSERT INTO verses VALUES (1011, 1, 34, 30, 'E-disse Jacó a Simeão e-a לֵוִי֮ עֲכַרְתֶּ֣ם אֹתִי֒ a-terra בְּיֹשֵׁ֣ב a-terra בַּֽכְּנַעֲנִ֖י וּבַפְּרִזִּ֑י e-eu mortos de-número וְנֶאֶסְפ֤וּ sobre-mim וְהִכּ֔וּנִי וְנִשְׁמַדְתִּ֖י eu וּבֵיתִֽי׃');
INSERT INTO verses VALUES (1012, 1, 34, 31, 'וַיֹּאמְר֑וּ הַכְזוֹנָ֕ה faz-o a אֲחוֹתֵֽנוּ׃');
INSERT INTO chapters VALUES (35, 1, 35, 29);
INSERT INTO verses VALUES (1013, 1, 35, 1, 'E-disse Elohim a Jacó folhas-de sobe casa-de El וְשֶׁב־ nome e-faze- nome altar de-diante-de הַנִּרְאֶ֣ה para-ti בְּבָרְחֲךָ֔ de-face-de עֵשָׂ֥ו irmão-teu');
INSERT INTO verses VALUES (1014, 1, 35, 2, 'E-disse Jacó a e-para e-a todo que com-ele הָסִ֜רוּ a Elohim-de הַנֵּכָר֙ que בְּתֹךְכֶ֔ם וְהִֽטַּהֲר֔וּ וְהַחֲלִ֖יפוּ שִׂמְלֹתֵיכֶֽם׃');
INSERT INTO verses VALUES (1015, 1, 35, 3, 'e-naquemos e-naaleh casa-de El e-e''asah- nome mizbeach la''eil ha''oneh oti'' e-houve comigo E-foi comigo no-caminho que halakh''ti:');
INSERT INTO verses VALUES (1016, 1, 35, 4, 'e-eles-distribuíram a Jacó a todo Elohim-de hannechare que be''yadam e-a os nazamim eles em-suas-ouvidos debaixo eles Jacó debaixo-de o-ela que com shchem');
INSERT INTO verses VALUES (1017, 1, 35, 5, 'e-saíram e-houve chittath Elohim sobre- as-cidades que suas-redondezas e-não perseguiram depois-de filhos-de Jacó');
INSERT INTO verses VALUES (1018, 1, 35, 6, 'E-veio Jacó lozah que na-terra Canaã ela casa-de ele ele e-todo o-povo que com-ele-verso');
INSERT INTO verses VALUES (1019, 1, 35, 7, 'E-edificou nome altar E-chamou para-o-lugar El casa-de que porque nome a-ele a-ele הָֽאֱלֹהִ֔ים de-diante-de de-faces-de irmão-dele');
INSERT INTO verses VALUES (1020, 1, 35, 8, 'e-morreu דּוֹבָרָה מֵינֶקֶת רִבְקָה וַתִּּקְבֵּר debaixo-de para-a-casa-de debaixo em-lugar-de E-chamou E-chamou nome-de-ele אַלּוֹן בָּכ֣וּת׃');
INSERT INTO verses VALUES (1021, 1, 35, 9, 'E-viu Elohim a Jacó ainda בְּבוֹא֖וֹ מִפַּדַּ֣ן E-abençoou ele a-ele');
INSERT INTO verses VALUES (1022, 1, 35, 10, 'e-ele-disse para-ele Elohim teu-nome Jacó não יִקְרֵא֩ שִׁמְךָ֨ que Jacó será se E-chamou será nome-teu E-chamou a nome-de-ele Israel');
INSERT INTO verses VALUES (1023, 1, 35, 11, 'E-disse a-ele Elohim eu El Shaddai frutificai e muitos nação e congregação nações será de ti e-reis dos teus calcanhares sairão');
INSERT INTO verses VALUES (1024, 1, 35, 12, 'e-a a-terra dei eu dei le-abraham a-ti para-ti a-ele-aqui e a tua semente depois de ti darei a a-terra');
INSERT INTO verses VALUES (1025, 1, 35, 13, 'e-ofereceu dos seus pés Elohim no-lugar- que palavra com-ele');
INSERT INTO verses VALUES (1026, 1, 35, 14, 'e estabeleceu Jacó um monumento no-lugar que palavra com-ele má-ter pedra e-suscitou sobre-ela neces e-ele-esguichou sobre-ela azeite');
INSERT INTO verses VALUES (1027, 1, 35, 15, 'E-chamou Jacó a nome o-lugar que palavra com-ele ali Elohim casa-de El');
INSERT INTO verses VALUES (1028, 1, 35, 16, 'e-eles-partiram de-casa-de El e-foi ainda como-um a-terra para-vir Efrata e-deu-à-luz Rachel ela-suscitou na-geração');
INSERT INTO verses VALUES (1029, 1, 35, 17, 'e-houve no-suscita-la quando deu à luz E-disse para-ela a que pariu a temas para-ti filho este para-ti filho');
INSERT INTO verses VALUES (1030, 1, 35, 18, 'e-houve na saída sua alma que morreu e-chamou nome-de-ele filho-de luto e seu pai ele chamou-se para-ele Benjamin:');
INSERT INTO verses VALUES (1031, 1, 35, 19, 'e-ela-morreu Raquel e foi sepultada no-caminho efratah ela casa pão');
INSERT INTO verses VALUES (1032, 1, 35, 20, 'e estabeleceu Jacó mara sobre ela ele mara sepultura de Rachel até o-dia');
INSERT INTO verses VALUES (1033, 1, 35, 21, 'e partiu-se Israel e-ele-esticou tenda da Heleia para o Migdal Eder');
INSERT INTO verses VALUES (1034, 1, 35, 22, 'e-houve  Bishkôn  Israel na-terra aquela E-andou  Reuven   E se deitou  a  Bilha  seu-pai  seu pai  E-ouviu  Israel   E foram  filhos-de Jacó dois dez');
INSERT INTO verses VALUES (1035, 1, 35, 23, 'filhos-de Lia em-primogênito Jacó Rúben e Simão e Levi e-Yehuda וְיִשָׂשכָ֖ר וּזְבוּלֻֽן׃');
INSERT INTO verses VALUES (1036, 1, 35, 24, 'filhos-de Rachel José e-Benjamin:');
INSERT INTO verses VALUES (1037, 1, 35, 25, 'e-filhos-de בִלְהָה֙ שִׁפְחַ֣ת Rachel דָּ֖ן וְנַפְתָּלִֽי׃');
INSERT INTO verses VALUES (1038, 1, 35, 26, 'e-filhos-de זִלְפָּ֛ה shifchat Lea Gad e Asher Estas filhos-de Jacó que nasceu a-ele em Padan aram');
INSERT INTO verses VALUES (1039, 1, 35, 27, 'E-veio Jacó a seu-pai pai-dele Mamar-e cidade-de ela ela Hebrom que gar- nome Abraão e Isaac:');
INSERT INTO verses VALUES (1040, 1, 35, 28, 'e-foram dias-de Isaque cem ano e-oitenta anos');
INSERT INTO verses VALUES (1041, 1, 35, 29, 'e foi adormecido Isaque E-morreu e reuniu-se a seus povos velho e Sebá dias ele a-ele Êsaú e Jacó seus filhos:');
INSERT INTO chapters VALUES (36, 1, 36, 43);
INSERT INTO verses VALUES (1042, 1, 36, 1, 'e-estes filhas-gerais: Esaú ele Edom');
INSERT INTO verses VALUES (1043, 1, 36, 2, 'ê-sav tomou a suas mulheres: filhas de assim a Adá filha-de Eilon a hitita e-a אָהֳלִֽיבָמָה filha-de עֲנָ֔ה filha-de Zibeão הֽ͏ַחִוִּֽי׃');
INSERT INTO verses VALUES (1044, 1, 36, 3, 'e-a balsama filha-de Ismael נְבָיֽוֹת׃');
INSERT INTO verses VALUES (1045, 1, 36, 4, 'e-deleveu עָדָ֛ה לְעֵשָׂ֖ו a Elifaz וּבָ֣שַׂ֔מֶת deu-à-luz a Reuel');
INSERT INTO verses VALUES (1046, 1, 36, 5, 'וְאָהֳלִֽיבָמָה֙ יָֽלְדָ֔ה a e-a יַעְלָ֖ם e-a Estas estas-estes filhos-de Esaú que יולדוּ- a-ele em-terra-de כְּנָֽעַן');
INSERT INTO verses VALUES (1047, 1, 36, 6, 'E-tomou עשו a נשיו e-a filhos-seus e-a בנותיו֮ e-a tudo-de נפשות ביתוֹ֒ e-a מקנהוּ e-a todo בהמתוֹ de-diante-de todo קנייניוֹ que racãš em-terra-de E-andou a terra de-face-de Jacó irmão-dele');
INSERT INTO verses VALUES (1048, 1, 36, 7, 'porque foi rekušám muito mishbet juntos e-não terra terra meguřeihem eles de-diante-de de-face-de miqnehem');
INSERT INTO verses VALUES (1049, 1, 36, 8, 'e-habitou ěšav em-monte-de Seir Esaú ele Edom');
INSERT INTO verses VALUES (1050, 1, 36, 9, 'e-estes filhas-gerais: Esaú pai-de Edom na-montanha Seir');
INSERT INTO verses VALUES (1051, 1, 36, 10, 'Estas nomes-de filhos-de Esaú ělifaz filho-de adah mulher-de Esaú reu''el filho-de בָּשְׂמַ֖ת mulher-de עֵשָֽׂו׃');
INSERT INTO verses VALUES (1052, 1, 36, 11, 'e-foram filhos-de Elifaz תֵּימָ֣ן אוֹמָ֔ר צְפ֥וֹ וְגַעְתָּ֖ם uknaz');
INSERT INTO verses VALUES (1053, 1, 36, 12, 'וְתִמְנַ֣ע ׀ ela-foi era לֶֽאֱלִיפַז֙ filho-de Esaú e-deu-à-luz לֶאֱלִיפַ֖ז a Estas estes filhos-de Ada mulher-de עֵשָֽׂו׃');
INSERT INTO verses VALUES (1054, 1, 36, 13, 'e-estes filhos-de רְעוּאֵ֔ל Naate וָזֶ֖רַח שַׁמָּ֣ה וּמִזָּ֑ה Estas foram filhos-de בָשְׂמַ֖ת mulher-de עֵשָֽׂו׃');
INSERT INTO verses VALUES (1055, 1, 36, 14, 'e-estes הָי֗וּ filhos-de אָהֳלִיבָמָ֧ה filha-de עֲנָ֛ה filha-de Zibeão mulher-de Esaú e-deu-à-luz para-Esaú a e-a יַעְלָ֖ם e-a qó-rakh');
INSERT INTO verses VALUES (1056, 1, 36, 15, 'Estas chefes-de filhos-de Esaú filhos-de אליפז primogênito-de Esaú אלוף תימן chefe אוֹמָ֔ר chefe  צphoon chefe Quenaz');
INSERT INTO verses VALUES (1057, 1, 36, 16, 'אלוף- קרוח chefe GeVatham chefe Estas estes אלופיים אליפז na-terra Estas estes filhos-de עָדָֽה׃');
INSERT INTO verses VALUES (1058, 1, 36, 17, 'e-estes filhos-de רְעוּאֵל֙ filho-de Esaú chefe נַ֙חַת֙ chefe זֶ֔רַח chefe como chefe Estas estes אלופיים רְעוּאֵל֙ na-terra Estas estes filhos-de בָשְׂמַ֖ת mulher-de עֵשָֽׂו׃');
INSERT INTO verses VALUES (1059, 1, 36, 18, 'e-estes filhos-de אָהֳלִֽיבָמָה mulher-de Esaú chefe יְע֛וּשׁ chefe יַעְלָ֖ם chefe  קֹ֑רַח Estas אַלּוּפֵ֞י אָֽהֳלִיבָמָ֛ה filha-de Aná mulher-de עֵשָֽׂו׃');
INSERT INTO verses VALUES (1060, 1, 36, 19, 'Estas filhos-de ê-sav e-aqueles ele ele Edom');
INSERT INTO verses VALUES (1061, 1, 36, 20, 'Estas filhos-de שֵׂעִיר֙ הַחֹרִ֔י a-terra a-terra Lotã e Sobal וְצִבְע֥וֹן e Aná');
INSERT INTO verses VALUES (1062, 1, 36, 21, 'וְדִשׁ֥וֹן e Ezer וְדִישָׁ֑ן Estas אלופיים הכר filhos-de Seir em-terra-de Edom');
INSERT INTO verses VALUES (1063, 1, 36, 22, 'e-foram filhos-de Lotã Hori והימים e irmã-de Lotã Timna');
INSERT INTO verses VALUES (1064, 1, 36, 23, 'e-estes filhos-de Sobal עלון ומנחת ועibal שׁפה ואון׃');
INSERT INTO verses VALUES (1065, 1, 36, 24, 'e-aqueles filhos-de Zibeão והayah ele ele ענה encontrou achou a os-brancos no-deserto -no seu pastoreio seu-pai as jumentas -para o cobertor pai-seu');
INSERT INTO verses VALUES (1066, 1, 36, 25, 'e-aqueles filhos-de Aná Dishon e Aholibama filha-de Anah:');
INSERT INTO verses VALUES (1067, 1, 36, 26, 'e-estes filhos-de Dishan Chamdan e Esbã e Itrã e Querã');
INSERT INTO verses VALUES (1068, 1, 36, 27, 'Estas filhos-de Etsur Bilã e Zaavã וַעֲקָֽן׃');
INSERT INTO verses VALUES (1069, 1, 36, 28, 'Estas filhos-de דִישֹׁן Uz e-Arã');
INSERT INTO verses VALUES (1070, 1, 36, 29, 'Estas chefes-de הַחֹרִ֑י אלוף לוֹטָן֙ chefe Sobal chefe Zibeão chefe Anah:');
INSERT INTO verses VALUES (1071, 1, 36, 30, 'chefe דִּשֹׁ֛ן chefe אֵ֖צֶר chefe דִּישָׁ֑ן Estas אַלּוּפֵ֧י o cori para seus alafiem em-terra-de Seir');
INSERT INTO verses VALUES (1072, 1, 36, 31, 'e-estes os-reis que rei em-terra-de Edom diante-de rei-de rei para-filhos-de Israel');
INSERT INTO verses VALUES (1073, 1, 36, 32, 'e-reinou no edom bela'' filho-de em ur e-nome-de cidade-dele Dinhaba');
INSERT INTO verses VALUES (1074, 1, 36, 33, 'E-morreu Bela e-reinou em-lugar-dele Jobabe filho-de Zerá de-Bozra');
INSERT INTO verses VALUES (1075, 1, 36, 34, 'E-morreu Jobabe e-reinou em-lugar-dele Huscham da-terra-de o-temanita');
INSERT INTO verses VALUES (1076, 1, 36, 35, 'E-morreu Huscham e-reinou em-lugar-dele Hadade filho-de filho-de-Bedade o-que-feriu a Midiã em-campo-de Moabe e-nome-de cidade-dele aventura:');
INSERT INTO verses VALUES (1077, 1, 36, 36, 'E-morreu Hadade e-reinou em-lugar-dele Samla de-Masreca');
INSERT INTO verses VALUES (1078, 1, 36, 37, 'E-morreu Samla e-reinou em-lugar-dele Saul de-Reobote o-rio');
INSERT INTO verses VALUES (1079, 1, 36, 38, 'E-morreu שָׁאוּל e-reinou em-lugar-dele Baal Hanã filho-de Acbor');
INSERT INTO verses VALUES (1080, 1, 36, 39, 'E-morreu בַּ֣עַל Chanan filho-de Acabor e-reinou em-lugar-dele הֲדַ֔ר e-nome-de cidade-dele פָּ֑עוּ e-nome-de esposa-dele מְהֵֽיטַבְאֵל֙ filha-de Matrede ouro ouro ouro');
INSERT INTO verses VALUES (1081, 1, 36, 40, 'וְ֠אֵלֶּה שְׁמ֞וֹת אלופיים ěšav לְמִשְׁפְּחֹתָ֔ם לִמְקֹמֹתָ֖ם em-nomes-deles chefe Timna chefe עַֽלְוָ֖ה chefe Jetete');
INSERT INTO verses VALUES (1082, 1, 36, 41, 'chefe Aolibama chefe Elá chefe Pinon');
INSERT INTO verses VALUES (1083, 1, 36, 42, 'chefe Quenaz chefe Temã chefe Mibzar');
INSERT INTO verses VALUES (1084, 1, 36, 43, 'chefe Magdiel chefe Irã Estas chefes-de Edom לְמֹֽשְׁבֹתָם֙ em-terra-de אֲחֻזָּתָ֔ם ele ele pai-de Edom');
INSERT INTO chapters VALUES (37, 1, 37, 36);
INSERT INTO verses VALUES (1085, 1, 37, 1, 'e-sentou Jacó em-terra-de [מְגוּרֵ֣י] seu-pai em-terra-de כְּנָֽעַן');
INSERT INTO verses VALUES (1086, 1, 37, 2, 'Estas [׀] Jacó [יַעֲקֹ֗ב] filho-de [בֶּן־שְׁבַֽע־עֶשְׂרֵ֤ה] quinze ser foi [אֶת־אֶחָיו֙] a irmãos-de-ele [נַ֗עַר] e-ele [בִלְהָ֛ה] a filhos-de [נְשֵׁ֣י] seu-pai e-trouxe [יוֹסֵ֛ף] mulheres-de pai-seu E-veio a a');
INSERT INTO verses VALUES (1087, 1, 37, 3, 'וְיִשָׂרָאֵ֗ל amou a José de-todo ele a-ele filho-de a-ele ele a-ele e fizer para-ele כְּתֹ֥נֶת פַּסִּֽים׃');
INSERT INTO verses VALUES (1088, 1, 37, 4, '[וַיִּרְא֣וּ] irmãos-seus porque [אָהַ֤ב] amou [מִכָּל־אֶחָ֔יו] de-todo ele [וְלֹ֥א] a-ela e-não [לְשָׁלֹֽם]');
INSERT INTO verses VALUES (1089, 1, 37, 5, 'וַיַּחֲלֹ֤ם José sonho e-anunciou para os seus irmãos e acrescentaram ainda odiou ele');
INSERT INTO verses VALUES (1090, 1, 37, 6, 'E-disse a-eles ouvi por favor este sonho este que eu sonhei:');
INSERT INTO verses VALUES (1091, 1, 37, 7, 'e-eis nós sonhadores sonhadoras no-meio-de o-campo e-eis arqueou-se minha sonhadora e-também נצבה e-eis תסובינה אלולותיכם VESHESTAKHAVENA לאלולתי׃');
INSERT INTO verses VALUES (1092, 1, 37, 8, 'e-disseram a-ele seus-irmãos HAMALOK TIMLOK sobre-nós se MASOL TIMSHOL BANU e acrescentaram ainda ele a-ele sobre seus sonhos e-sobre suas palavras:');
INSERT INTO verses VALUES (1093, 1, 37, 9, 'e sonhou ainda sonho outro e contou ele aos seus irmãos E-disse eis eu sonhei sonho ainda e-eis o sol e a lua וְאַחַ֤ד dez estrelas מִֽשְׁתַּחֲוִ֖ים a-mim');
INSERT INTO verses VALUES (1094, 1, 37, 10, 'וַיְסַפֵּ֣ר a אָבִיו֮ e-a seu-pai E-disse a-ele pai-dele E-disse a-ele que הַחֲל֥וֹם este que חָלָ֑מְתָּ הֲב֣וֹא נָב֗וֹא eu a-ti וְאַחֶ֔יךָ disse a-ti para-terra');
INSERT INTO verses VALUES (1095, 1, 37, 11, 'וַיְקַנְאוּ־ em-ele seus-irmaos e seu pai שָׁמַר a a-palavra');
INSERT INTO verses VALUES (1096, 1, 37, 12, 'e-foram seus-irmaos לִרְעֹות אֶת־ pai-deles בִּשְׁכֶם׃');
INSERT INTO verses VALUES (1097, 1, 37, 13, 'E-disse Israel a José não teus-irmaos רֹעִים בִּשְׁכֶם לְכָה וְאֶשְׁלַחֲךָ֣ E-disse a-ele a-ele eis-me');
INSERT INTO verses VALUES (1098, 1, 37, 14, 'E-disse a-ele vai- por-favor viu a paz teus-irmaos e-a a paz o-rebanho וַהֲשִׁיבֵנִי palavra וַיִּשְׁלַחֵ֙הוּ֙ de-emeque Hebrom E-veio shchem:');
INSERT INTO verses VALUES (1099, 1, 37, 15, 'e-o-encontrou-o homem e-eis perdido no-campo e-lhe-perguntou o-homem dizendo que procurares:');
INSERT INTO verses VALUES (1100, 1, 37, 16, 'E-disse a eu eu pedindo diga-a agora eles onde eles pastores:');
INSERT INTO verses VALUES (1101, 1, 37, 17, 'E-disse o-homem saíram deste-lado que ouvi dizendo-os venhamos de-les E-andou José atrás-de seus-irmãos e-os-encontraram em-Bet-Datan');
INSERT INTO verses VALUES (1102, 1, 37, 18, 'e-eles-deram-conta ele de-longe e-antes-de se-aproximará a-eles e-os-enganaram ele para-o-matar');
INSERT INTO verses VALUES (1103, 1, 37, 19, 'e-disseram homem a eis eis em-Príncipe os-sonhos este veio');
INSERT INTO verses VALUES (1104, 1, 37, 20, 'e-agora ide e-o-matemos e-o-lancemos em um as-ortoֿ e-amar-nuֿ חַיָּה vivente a-khalata-huֿ e-nera-ehֿ que yihiyuֿ chalomotayֿ');
INSERT INTO verses VALUES (1105, 1, 37, 21, 'E-ouviu Rúben [וַיַּצִּלֵ֖הוּ] [מִיָּדָ֑ם] E-disse não [נַכֶּ֖נּוּ] alma');
INSERT INTO verses VALUES (1106, 1, 37, 22, 'E-disse alihemֿ Reúben a derramareis sangue ele a-ele a o poço o-este que no-deserto e mão a ele nele para-que resgate ele dos seus olhos para devolvê-lo a seu-pai');
INSERT INTO verses VALUES (1107, 1, 37, 23, 'e-foi como- veio José a seus-irmaos e esticaram a José a a canga dele a capa as faixas que sobre-ele');
INSERT INTO verses VALUES (1108, 1, 37, 24, 'e tomaram-no e lançaram-no ele na cova e a cova vazio não-há nele águas');
INSERT INTO verses VALUES (1109, 1, 37, 25, 'e sentaram-se para comer lechem וַיִּשְׂא֤וּ seus olhos- e viram e-eis caminho de-Ishmael -a de-Migdal-gad e-cavalos-les levando-os -a-lhe e-castiço e-Lot andando para baixar de Egito:');
INSERT INTO verses VALUES (1110, 1, 37, 26, 'E-disse Judá a seus-irmaos que por meio de golpe porque matemos a nosso irmão e o cubramos a com sangue');
INSERT INTO verses VALUES (1111, 1, 37, 27, 'vamos e vendamo-lo a arameus וְיָדֵ֙נוּ֙ a תְּהִי־ nele ele אָחִ֥ינוּ בְשָׂרֵ֖נוּ ele וַֽיִּשְׁמְע֖וּ אֶחָֽיו׃');
INSERT INTO verses VALUES (1112, 1, 37, 28, 'וַיַּֽעַבְרוּ֩ homens מִדְיָנִ֜ים סֹֽחֲרִ֗ים וַֽיִּמְשְׁכוּ֙ e subiram a José de o poço e venderam a José aos ismaelitas vinte prata e-trouxeram a José de egito:');
INSERT INTO verses VALUES (1113, 1, 37, 29, 'e-ele-retornou Rúben a o poço e-eis não-há José no poço e rasgou a suas roupas:');
INSERT INTO verses VALUES (1114, 1, 37, 30, 'e-voltou a seus-irmãos E-disse o menino não há e-eu para-onde eu- veio');
INSERT INTO verses VALUES (1115, 1, 37, 31, 'e tomaram a cota José e sacrificaram um-sair ez''im e despejaram a a cota no sangue:');
INSERT INTO verses VALUES (1116, 1, 37, 32, 'e enviaram a cota as fases e trouxeram a esta e-disseram isto achamos conhece ela a túnica do teu filho a-vós se não');
INSERT INTO verses VALUES (1117, 1, 37, 33, 'e reconheceu-a E-disse túnica filhos-de vivente maldade comeram-na golpeador טֹרַ֖ף José');
INSERT INTO verses VALUES (1118, 1, 37, 34, '[וַיִּקְרַ֤ע] Jacó [שִׂמְלֹתָ֔יו] e-colocou [שַׂ֖ק] em-lombos-seus [וַיִּתְאַבֵּ֥ל] sobre filho-seu dias');
INSERT INTO verses VALUES (1119, 1, 37, 35, '[וַיָּקֻמוּ֩] todo [וְכָל־בְּנֹתָ֜יו] e-todo [וַיְמָאֵן֙] [לְהִתְנַחֵ֔ם] E-disse [כִּֽי־אֵרֵ֧ד] E-disse porque [שְׁאֹ֑לָה] a ele seu-pai');
INSERT INTO verses VALUES (1120, 1, 37, 36, '[וְהַ֨מְּדָנִ֔ים] [מָכְר֥וּ] ele a Egito [סְרִ֣יס] [פַּרְעֹ֔ה] Faraó príncipe');
INSERT INTO chapters VALUES (38, 1, 38, 30);
INSERT INTO verses VALUES (1121, 1, 38, 1, 'e-houve em-o-tempo aquela e-desceu Judá de-junto-de [אֶחָ֑יו] [וַיֵּ֛ט] até homem [וּשְׁמ֥וֹ] e-nome-dele');
INSERT INTO verses VALUES (1122, 1, 38, 2, 'e-viu- nome יְהוּדָה filha-de homem כנעני e-nome-de-ele שׁועה e-tomou-a E-veio a-ela');
INSERT INTO verses VALUES (1123, 1, 38, 3, 'e-concebeu e-deu-à-luz filho E-chamou a nome-de-ele');
INSERT INTO verses VALUES (1124, 1, 38, 4, 'e-concebeu ainda e-deu-à-luz filho e-chamou a nome-de-ele');
INSERT INTO verses VALUES (1125, 1, 38, 5, '[וַתֹּ֤סֶף] ainda e-deu-à-luz filho e-chamou a nome-de-ele [וְהָיָ֥ה] e-acontecerá [בְּלִדְתָּ֥הּ] ele');
INSERT INTO verses VALUES (1126, 1, 38, 6, 'E-tomou יְהוּדָה mulher לער בבכוריו e-nome-dela de-Tamar');
INSERT INTO verses VALUES (1127, 1, 38, 7, 'e-houve arre primogênito-de Judá mau em-olhos-de yhwh WAYYIMTUHU yhwh');
INSERT INTO verses VALUES (1128, 1, 38, 8, 'E-disse Judá [לְאוֹנָ֔ן] veio a mulher-de irmão-teu [אֹתָ֑הּ] ela semente [לְאָחִֽיךָ]');
INSERT INTO verses VALUES (1129, 1, 38, 9, 'e-soube [אוֹנָ֔ן] que não a-ele será [הַזָּ֑רַע] e-será se veio a [וְשִׁחֵ֣ת] [אַ֔רְצָה] para-não terra-para para-não');
INSERT INTO verses VALUES (1130, 1, 38, 10, 'וַיֵּ֛רַע em-olhos-de yhwh que fez E-morreu também ele');
INSERT INTO verses VALUES (1131, 1, 38, 11, 'E-disse יְהוּדָה לְתָמָ֨ר כַּלָּת֜וֹ שְׁבִ֧י אַלְמָנָ֣ה casa-de אָבִ֗יךְ até יִגְדַּל֙ que disse porque disse para-que-não morrerá também ele כְּאֶחָ֑יו e-ela-partiu-se Tamar e-habitou casa אָבִֽיהָ׃');
INSERT INTO verses VALUES (1132, 1, 38, 12, 'e-ele-multiplicaram-se-os os-dias e-ela-morreu filha-de שׁ֣וּעַ esposa-de Judá e-lamentou Judá e-ele-subiu ele גֹּֽזֲזֵ֤י צֹאנוֹ֙ ele e chirá רֵעֵ֥הוּ a adullami timnata');
INSERT INTO verses VALUES (1133, 1, 38, 13, 'e-ele-foi-dito para tamar dizendo eis carmim olé timnata lagoz seu rebanho');
INSERT INTO verses VALUES (1134, 1, 38, 14, 'e ela tirou בגדים אלמנותה מעליה e cobriu בתצעיף ותיתעלפה e-sentou na porta עינים que sobre caminho que porque ראתה porque גדל שלאה a-ele não foram-dadas para-ele para-mulher');
INSERT INTO verses VALUES (1135, 1, 38, 15, 'וייראהה Judá e-pensou-a para-zona que cobriu-se suas-faces:');
INSERT INTO verses VALUES (1136, 1, 38, 16, 'e-ele-esticou a-ela a E-disse E-disse dá agora que não saber que conheceu ela E-disse ela que que tu-darás para-mim porque vires para-mim');
INSERT INTO verses VALUES (1137, 1, 38, 17, 'E-disse eu eu-enviarei gadi- cabras E-disse do-rebanho e-disse até dareis em-obras até enviaste-te');
INSERT INTO verses VALUES (1138, 1, 38, 18, 'E-disse que o-em-obras que darei E-disse e-disse selo-te e-fogo-te e-rodado-te que em-mão-tua e-ele-deu para-ele-a-lhe E-veio a-ele e-concebeu a-ele');
INSERT INTO verses VALUES (1139, 1, 38, 19, 'e-levantou-se e saiu e tirou sua cobertura de cima dela e vestiu-se de-roupas a virgindade');
INSERT INTO verses VALUES (1140, 1, 38, 20, 'e-enviou Judá a cordeiro as cabras em-mão-de seu rebanho o seu vizinho Adulam tomar o-urebo''n de-mão-de a mulher e-não metsa''ah::-');
INSERT INTO verses VALUES (1141, 1, 38, 21, 'vayisa''al a homens-de dizendo dizendo onde ela הִ֥וא ba-ey''nayim sobre ha-dar''ke'' e-disseram não haytah בוזה kedesh::-');
INSERT INTO verses VALUES (1142, 1, 38, 22, 'e-ele-voltou a E-disse não não metsa''tiyah'' e-tambem homens-de o-lugar disseram não haytah בוזה kedesh::-');
INSERT INTO verses VALUES (1143, 1, 38, 23, 'E-disse Judá tiqqa''·- para-que-não pen נִהְיֶ֣ה eis eis שָׁלַ֙חְתִּי֙ הַגְּדִ֣י esta não não מְצָאתָֽהּ׃');
INSERT INTO verses VALUES (1144, 1, 38, 24, 'e-houve [׀] [כְּמִשְׁלֹ֣שׁ] [חֳדָשִׁ֗ים] [וַיֻּגַּ֨ד] [לִֽיהוּדָ֤ה] [לֽ͏ֵאמֹר֙] [זָֽנְתָה֙] [תָּמָ֣ר] e-também eis eis [הָרָ֖ה] E-disse E-disse [יְהוּדָ֔ה] [הוֹצִיא֖וּהָ]');
INSERT INTO verses VALUES (1145, 1, 38, 25, 'ela [מוּצֵ֗את] [וְהִ֨יא] [שָׁלְחָ֤ה] a dizendo dizendo para-homem para-ele eu a-ele E-disse [הַכֶּר־נָ֔א] e-disse [הַחֹתֶ֧מֶת] [וְהַפְּתִילִ֛ים] [וְהַמַּטֶּ֖ה] [הָאֵֽלֶּה]');
INSERT INTO verses VALUES (1146, 1, 38, 26, '[וַיַּכֵּ֣ר] Judá E-disse [צָֽדְקָ֣ה] mais-que-a-mim porque sobre assim não [וְלֹֽא־יָסַ֥ף] [ע֖וֹד] filhos-de e-não');
INSERT INTO verses VALUES (1147, 1, 38, 27, 'e-houve na época para dar-a e-eis gemeos em-se');
INSERT INTO verses VALUES (1148, 1, 38, 28, 'e-houve quando de-a e-ele-deu e-tomou e tomou-a a grávida e amarrou-a sobre dizendo segundo sair este יָצָ֥א primeira');
INSERT INTO verses VALUES (1149, 1, 38, 29, 'e-houve como um que mão-sua sua-mão saiu sair e-disse E-disse rompeu-a עָלֶ֣יךָ פרץ E-chamou seu-nome פרץ׃');
INSERT INTO verses VALUES (1150, 1, 38, 30, 'e-depois sair irmão-seu que sobre mão-sua E-chamou E-chamou seu-nome זרחה׃');
INSERT INTO chapters VALUES (39, 1, 39, 23);
INSERT INTO verses VALUES (1151, 1, 39, 1, 'e-José HDR Egito-para ויקנהוּ פוטיפאר סריס פרעה príncipe הטבחים homem egípcio de-mão-de הַיִּשְׁמְעֵאלִ֔ים que הורידוהו ali');
INSERT INTO verses VALUES (1152, 1, 39, 2, 'e-houve yhwh a e-houve E-foi homem e-houve E-foi [אֲדֹנָ֥יו] [הַמִּצְרִֽי]');
INSERT INTO verses VALUES (1153, 1, 39, 3, 'E-viu [אֲדֹנָ֔יו] que yhwh com-ele e-tudo que ele yhwh yhwh [בְּיָדֽוֹ]');
INSERT INTO verses VALUES (1154, 1, 39, 4, 'WAYYITMACA יוסף חן em-suas-olhos WAYYISHERET ele e o colocou sobre casa-dele dar há para-ele deu em-mão-sua');
INSERT INTO verses VALUES (1155, 1, 39, 5, 'e-houve desde então colocou ele em sua casa e-sobre todo que E-abençoou yhwh E-abençoou yhwh a casa e-houve por causa de yhwh E-foi a bênção yhwh em-todo que há a-ele na-casa e na terra');
INSERT INTO verses VALUES (1156, 1, 39, 6, 'e abandonou todo que a-ele por-mão-de José que conheceu com-ele dizia-se e-houve se o pão que vista que comia E-foi José נורא- תואר ויפeh aparência');
INSERT INTO verses VALUES (1157, 1, 39, 7, 'e-houve outro as-palavras os-estes [וַתִּשָּׂ֧א] esposa-de [אֶת־עֵינֶ֖יהָ] a E-disse a José');
INSERT INTO verses VALUES (1158, 1, 39, 8, 'WAYMAEN E-disse E-disse mulher-de אדוןיו eis Adonai não conheceu ITHI e-tudo ba-bayit dar que há para-ele deu BYADHI:');
INSERT INTO verses VALUES (1159, 1, 39, 9, 'אֵינֶנּוּ grande em-casa hazeh מִמֶּנִּי֒ e-não escuridão de-mim que porque se te ba-asher אַתְּ־ mulher-sua וְאֵ֨יךְ אֶֽעֱשֶׂ֜ה a má הַגְּדֹלָה֙ a-esta וְחָטָ֖אתִי para-Elohim');
INSERT INTO verses VALUES (1160, 1, 39, 10, 'e-houve [כְּדַבְּרָ֥הּ] a dia [׀] dia e-não ouviu [לִשְׁכַּ֥ב] [אֶצְלָ֖הּ] [לִהְי֥וֹת] com-ela');
INSERT INTO verses VALUES (1161, 1, 39, 11, 'e-houve כְּהַיּ֣וֹם esta E-veio הביתה para fazer sua-obra וְאֵ֨ין homem מֵאַנְשֵׁ֥י a-casa nome na-casa');
INSERT INTO verses VALUES (1162, 1, 39, 12, 'וַתִּתְפְּשֵׂ֧הוּ בְּבִגְד֛וֹ dizendo שִׁכְבָ֣ה comigo וַיַּעֲזֹ֤ב בִּגְדוֹ֙ em-mã e-estendeu-se e-ele-saiu para-a-fora');
INSERT INTO verses VALUES (1163, 1, 39, 13, 'e-houve para-ver-a porque deixou em-suas-roupas em-mã e-estendeu-se para-a-fora');
INSERT INTO verses VALUES (1164, 1, 39, 14, 'e-chamou para-os-homens de-sua-casa E-disse a-eles dizendo vejam היביא para-nós homem hebreu לצחק בnanoו veio a-mim לישכב comigo ואקרא בקול grande');
INSERT INTO verses VALUES (1165, 1, 39, 15, 'e-houve כשםעו porque הרמתי קולי ואקרא e deixou-o sua vestidura ao meu lado e se deitou e-ele-saiu para-a-fora');
INSERT INTO verses VALUES (1166, 1, 39, 16, 'e pôs-se sua vestidura ao seu lado até vir adonai-aus a casa-dele');
INSERT INTO verses VALUES (1167, 1, 39, 17, 'e falou a-ele como palavras estes dizendo veio para mim o servo o hebreu que levaste para-nós para brincar em-mim');
INSERT INTO verses VALUES (1168, 1, 39, 18, 'e-houve como se erguesse minha voz e chamei e deixou em suas vestes ao meu lado e-fugiu para-a-fora');
INSERT INTO verses VALUES (1169, 1, 39, 19, 'e-houve quando-ouviram seu senhor a palavras-de esposa-dele que a-ele dizendo dizendo como-as-coisas os-estes a-mim servo-teu e tornou-se agradável אַף׃');
INSERT INTO verses VALUES (1170, 1, 39, 20, 'E-tomou Adonai José ele e o colocou a casa no sarayu em lugar que o-rei de presos e-foi nome em-casa-de no sarayu:');
INSERT INTO verses VALUES (1171, 1, 39, 21, 'e-houve yhwh a José a-ele a-ele E-colocou E-deu sua face em-olhos-de príncipe casa-de no sarayu:');
INSERT INTO verses VALUES (1172, 1, 39, 22, 'E-colocou príncipe casa-de o sar por-mão-de José a todo [הַסֹּ֑הַר] que em-casa-de o sar e-a ele ser fazem nome ele foi fez');
INSERT INTO verses VALUES (1173, 1, 39, 23, 'ain comandante-de casa-de o sar viu a todo murmurada yhwh em-o-que yhwh com-ele yhwh ele fez yhwh conseguem:');
INSERT INTO chapters VALUES (40, 1, 40, 23);
INSERT INTO verses VALUES (1174, 1, 40, 1, 'e-houve outro as-palavras os-estes fornece rei-de Egito e-a-опе p-e-אֲדֹנֵיהֶם para-rei-de Egito');
INSERT INTO verses VALUES (1175, 1, 40, 2, 'e-v-i-q-tsof Faraó sobre segundo sarisay sobre comandante-de a-mashqim e-sobre príncipe ha-опеim');
INSERT INTO verses VALUES (1176, 1, 40, 3, 'E-colocou eles b-mishmar casa príncipe a-tavbachim a casa o sar m-kom que José ásur nome');
INSERT INTO verses VALUES (1177, 1, 40, 4, 'e foi contado comandante-de os que cortavam a José com-eles eles a-eles e-foram dias no serviço');
INSERT INTO verses VALUES (1178, 1, 40, 5, 'e eles sonharam sonho os dois deles homem seu sonho na noite um homem quando ele estava desperto seu sonho o que bebe e o que come que como-rei Egito que presos em-casa-de o cárcere:');
INSERT INTO verses VALUES (1179, 1, 40, 6, 'E-veio neles José no-manhã E-viu eles e eis-los despidos:');
INSERT INTO verses VALUES (1180, 1, 40, 7, 'e perguntou a aos criados Faraó que com ele em-merar casa dizendo dizendo por-que vosso(s) rosto(s) o-dia o-dia');
INSERT INTO verses VALUES (1181, 1, 40, 8, 'e-disseram a-ele sonho sonhamos e-interpretar não-há ele E-disse a-eles José não para-elohim interpretações contai-vos por-favor a-mim');
INSERT INTO verses VALUES (1182, 1, 40, 9, 'e-contou chefe aqueles que dão de beber a E-disse a-ele E-disse a-ele no meu sonho e-eis vinho לְפָנַֽי׃');
INSERT INTO verses VALUES (1183, 1, 40, 10, 'e no vinho três saraíques e ela cifrão subiu se esticou eles fizeram as suas asas u''nav''im:');
INSERT INTO verses VALUES (1184, 1, 40, 11, 've-kos פַּרְעֹה b''yadi va-ekach a ha''unav''im eles eles a כוס Faraó váeten a ha-kos sobre palma פַּרְעֹה');
INSERT INTO verses VALUES (1185, 1, 40, 12, 'E-disse a-ele José este pitrono sheloshet hasharigim três dias eles');
INSERT INTO verses VALUES (1186, 1, 40, 13, 'em-ainda três-de dias yisa Pharaoh a rosh-ekha va-hashiv''kha sobre kannekha e-tu-porás kos- Faraó em-mão-de-ele kamishpat הָֽרִאשׁ֔וֹן que הָיִ֖יתָ mashehu:');
INSERT INTO verses VALUES (1187, 1, 40, 14, 'que se zakartani ''itkha ka''asher para-ti para-ti comigo na'' עםדי bondade e me lembraste a Faraó e me tiraste de a casa a-esta');
INSERT INTO verses VALUES (1188, 1, 40, 15, 'porque ladrão eu fui ladrão מֵאֶ֖רֶץ os hebreus e-também aqui não faça maldita porque e colocaram me-a no poço');
INSERT INTO verses VALUES (1189, 1, 40, 16, 'E-viu príncipe-de que bom bom E-disse E-disse a José também eu no meu sonho e-eis שְׁלֹשָׁ֛ה os meus meu sobre minha-cabeça:');
INSERT INTO verses VALUES (1190, 1, 40, 17, 'e no sál a-superior de-toda alimento פַּרְעֹה obra-de que eu assava e o pássaro comia eles de de-cima-de de-sobre minha-cabeça:');
INSERT INTO verses VALUES (1191, 1, 40, 18, 'e-respondeu José E-disse este sua pele três as-salim três dias eles');
INSERT INTO verses VALUES (1192, 1, 40, 19, 'em-ainda três-de dias yisa Faraó a rosh-ka me''al-eka ve''tala te sobre e-coma ve''akal a ave a basar-ka me''al-eka');
INSERT INTO verses VALUES (1193, 1, 40, 20, 'e-houve em-o-dia no-dia dia dia a Faraó E-fez banquete para-todo servos-dele vayisa a rosh comandante-de ha-mashkîm e-a cabeça no-meio-de ha-ʾāpîm no-meio-de seus-servos');
INSERT INTO verses VALUES (1194, 1, 40, 21, 'va-yashbê a príncipe ha-mashkîm E-colocou maškêhu E-deu ha-kôs sobre palma פַּרְעֹה');
INSERT INTO verses VALUES (1195, 1, 40, 22, 'e-a príncipe ha-ʾāpîm ta-lâh como-que pa-tar a-eles José');
INSERT INTO verses VALUES (1196, 1, 40, 23, 'e-não macho chefe o que enxova a José e o esqueceu;');
INSERT INTO chapters VALUES (41, 1, 41, 57);
INSERT INTO verses VALUES (1197, 1, 41, 1, 'e-houve ao-fim-de dois anos dias e Faraó sonhava e-eis ficou-em-pé sobre o-rio');
INSERT INTO verses VALUES (1198, 1, 41, 2, 'e-eis de o Nilo subidas sete ovos vista aparência e carne carne e pastoreavam בָּאָֽחוּ׃');
INSERT INTO verses VALUES (1199, 1, 41, 3, 'וְהִנֵּ֞ה sete פָּר֣וֹת אֲחֵר֗וֹת אולות אַחֲרֵיהֶן֙ de o-rio vista aparência וְדַקּ֣וֹת carne וַֽתַּעֲמֹ֛דְנָה ao-lado-de הַפָּר֖וֹת sobre beira-de o-rio');
INSERT INTO verses VALUES (1200, 1, 41, 4, 'וַתֹּאכַ֣לְנָה הַפָּר֗וֹת רָעֽוֹת הַמַּרְאֶה֙ וְדַקֹּ֣ת a-carne a sete הַפָּר֔וֹת יְפֹ֥ת a-mar''eh וְהַבְּרִיאֹ֑ת וַיִּיקַ֖ץ פַּרְעֹה');
INSERT INTO verses VALUES (1201, 1, 41, 5, 'וַיִּישָׁ֕ן וַֽיַּחֲלֹ֖ם segunda והנה sete שִׁבֳּלִ֗ים )(((올ות)) בּ-קָנֶה um um וְטוֹבֹת׃');
INSERT INTO verses VALUES (1202, 1, 41, 6, 'e-eis sete [שִׁבֳּלִ֔ים] [דַּקּ֖וֹת] [וּשְׁדוּפֹ֣ת] [קָדִ֑ים] [צֹמְח֖וֹת] [אַחֲרֵיהֶֽן]');
INSERT INTO verses VALUES (1203, 1, 41, 7, 'וַתִּ-בְלַעְנָה֙ os-shibbêlim as-dakkôth a sete os-shibbêlim as-brêiôt e-as-melêôth vayiqats פַּרְעֹה e-eis chalom');
INSERT INTO verses VALUES (1204, 1, 41, 8, 'e-houve pela-manhã vatippe''em espírito-dele e-enviou E-chamou a todo os-sábios Egito e-a a-eles chakhame''êhâ vayesaper פרעה para-eles a חלום e-não-há פותר eles a-Faraó');
INSERT INTO verses VALUES (1205, 1, 41, 9, '[וַיְדַבֵּר֙] comandante-de [הַמַּשְׁקִ֔ים] a dizendo dizendo a [מַזְכִּ֥יר] o-dia');
INSERT INTO verses VALUES (1206, 1, 41, 10, 'פַּרְעֹה [קָצַ֣ף] sobre E-colocou E-deu a-mim [בֵּ֚ית] casa comandante-de [אֹתִ֕י] e-[OBJ] e-[OBJ] príncipe');
INSERT INTO verses VALUES (1207, 1, 41, 11, 'e nós sonhamos sonho na noite um eu e ele homem de sua cama seu sonho nós sonhamos:');
INSERT INTO verses VALUES (1208, 1, 41, 12, 'e lá com nós jovem hebreu servo sir da-carnes e-nos-relatamos- a-ele e-desvendou- para-nós a nossos-sonhos homem como-seu desvendou:');
INSERT INTO verses VALUES (1209, 1, 41, 13, 'e-houve como-que desvende- para-nós ser foi de-mim-me retornou sobre כּנָּי e-a-ele תָּלָה׃');
INSERT INTO verses VALUES (1210, 1, 41, 14, 'e-estendeu Faraó E-chamou a José [מִן־הַבּ֑וֹר] de [וַיְחַלֵּ֣ף] [שִׂמְלֹתָ֔יו] [וַיָּבֹ֖א] [אֶל־פַּרְעֹֽה] E-veio a');
INSERT INTO verses VALUES (1211, 1, 41, 15, 'E-disse Faraó a José sonho חָלַםְתִּי וּפֹתֵר ele a-ela e-eu שָׁמַעְתִּי dizendo dizendo תִּשְׁמַע חֲלוֹם ele ele');
INSERT INTO verses VALUES (1212, 1, 41, 16, 'e-ele-respondeu [יוֹסֵ֧ף] a dizendo para-dizer sem-mim Elohim [אֶת־שְׁל֥וֹם] a');
INSERT INTO verses VALUES (1213, 1, 41, 17, 'e-falou פַּרְעֹה a José [הִנְנִ֥י] eis-me ficou-em-pé sobre');
INSERT INTO verses VALUES (1214, 1, 41, 18, 'e-eis de הַיְאֹר עֹלֹת sete פָּרוֹת בְּרִיאוֹת carne וִיפֹ֣ת escreveste e pastorearam em Achú:');
INSERT INTO verses VALUES (1215, 1, 41, 19, 'e eis que sete- פָּרֹות outras עֹלוֹת atrás-delas deles e delas muito muito e deles carne não eu vi como uma em-todo terra Egito para pastorear:');
INSERT INTO verses VALUES (1216, 1, 41, 20, 'e comeu as fêmeas as raposas e as corças a sete as fêmeas as primeiras הַבְּרִיאֹֽת׃');
INSERT INTO verses VALUES (1217, 1, 41, 21, 'e-vieram a entre si e-não foi conhecido porque viram a קִרְבֶּנָה וּמַרְאֵיהֶן mau conforme בַּתְּחִלָּה וָאִיקָץ׃');
INSERT INTO verses VALUES (1218, 1, 41, 22, 'e-eu-vi בַּחֲלֹםִי והנה sete שִׁבֳּלִים עֹלֹות בְּקָנֶה um um וְטֹבֽוֹת׃');
INSERT INTO verses VALUES (1219, 1, 41, 23, 'e-eis sete שִׁבֳּלִים cunhadas dakot shadupot kadim zomchot depois-deles');
INSERT INTO verses VALUES (1220, 1, 41, 24, 'vati''bal''una hashebelim [הַדַּקֹּ֔ת] a sete hashebelim hatovot וָאֹמַר֙ a הַחַרְטֻמִּ֔ים e-não-há מַגִּ֖יד a-mim');
INSERT INTO verses VALUES (1221, 1, 41, 25, 'E-disse José a Faraó [פַּרְעֹ֖ה] um ele ele a que o-Elohim declarou [לְפַרְעֹֽה]');
INSERT INTO verses VALUES (1222, 1, 41, 26, 'sete פָּרֹ֣ת הַטֹּבֹ֔ות sete dois elas וְשֶׁ֤בַע הַֽשִּׁבֳּלִים֙ הַטֹּבֹ֔ות sete dois aqui-estes חֲלוֹם um ele');
INSERT INTO verses VALUES (1223, 1, 41, 27, 'vesheva'' הַפָּרֹות הָרַקּוֹת וְהָרָעֹת הָעֹלֹת אַחֲרֵיהֶן sete dois elas וְשֶׁבַע הַשִׁבֳּלִים֙ הָרֵק֔וֹת שְׁדֻפ֖וֹת הַקָּדִ֑ים יִהְי֕וּ sete segundo רָעָֽב׃');
INSERT INTO verses VALUES (1224, 1, 41, 28, 'ele a-palavra que falei a Faraó que o-Elohim fez [אֶת־פַּרְעֹֽה] a');
INSERT INTO verses VALUES (1225, 1, 41, 29, 'eis sete dois [בָּא֑וֹת] sete grande em-todo terra');
INSERT INTO verses VALUES (1226, 1, 41, 30, 'וְ֠קָמוּ sete segundo רָעָב֙ atrás-delas וְנִשְׁכַּ֥ח todo הַשָּׂבָ֖ע em-terra-de Egito e consumirá a-fome a a-terra');
INSERT INTO verses VALUES (1227, 1, 41, 31, 'e-não [הַשָּׂבָע֙] [בָּאָ֔רֶץ] de-diante-de [הָרָעָ֥ב] [הַה֖וּא] o-aquele depois-de ele muito');
INSERT INTO verses VALUES (1228, 1, 41, 32, 'e-sobre [הִשָּׁנ֧וֹת] [הַחֲל֛וֹם] a פַּרְעֹה [כִּֽי־נָכ֤וֹן] porque [מֵעִ֣ם] a-palavra de-com os-Elohim [לַעֲשֹׂתֽוֹ]');
INSERT INTO verses VALUES (1229, 1, 41, 33, 'e-agora [יֵרֶ֣א] פַּרְעֹה homem [נָב֣וֹן] [וְחָכָ֑ם] [וִישִׁיתֵ֖הוּ] sobre terra');
INSERT INTO verses VALUES (1230, 1, 41, 34, 'fará פַּרְעֹה [וְיַפְקֵ֥ד] [פְּקִדִ֖ים] sobre a-terra [אֶת־אֶ֣רֶץ] a terra Egito [הַשָּׂבָֽע] segundo');
INSERT INTO verses VALUES (1231, 1, 41, 35, '[וְיִקְבְּצ֗וּ] a todo [הַטֹּבֹ֔ת] [הַבָּאֹ֖ת] [הָאֵ֑לֶּה] [וְיִצְבְּרוּ־בָ֞ר] debaixo [יַד־פַּרְעֹ֛ה] [אֹ֥כֶל] em-lugar-de mão-de');
INSERT INTO verses VALUES (1232, 1, 41, 36, 'e-será הָאֹ֤כֶל לְפִקָּדוֹן֙ לָאָ֔רֶץ לְשֶׁ֙בַע֙ segundo הָרָעָ֔ב que serão em-terra-de Egito e-não a-terra a-terra bar''ava:');
INSERT INTO verses VALUES (1233, 1, 41, 37, 'e-foi-bom a palavra aos-olhos-de Faraó e-em-olhos-de todo seus-servos');
INSERT INTO verses VALUES (1234, 1, 41, 38, 'E-disse פַּרְעֹה a servos-dele הֲנִמְצָ֣א כָזֶ֔ה homem espírito espírito Elohim em-ele');
INSERT INTO verses VALUES (1235, 1, 41, 39, 'E-disse Faraó a José apos fez-saber Elohim te a todo esta não-há נָב֥וֹן וְחָכָ֑ם como-você');
INSERT INTO verses VALUES (1236, 1, 41, 40, 'tu será sobre em-o-casa e-sobre seu-boca beije todo meu-povo somente o-trono exaltou מִמֶּֽךָּ׃');
INSERT INTO verses VALUES (1237, 1, 41, 41, 'E-disse פַּרְעֹה a José dei dei sobre sobre todo terra Egito');
INSERT INTO verses VALUES (1238, 1, 41, 42, 'e-retirou פרעה a de-cima-de sua-mão E-colocou E-deu a-ela sobre mão ele e vestiu ele vestes- o-ouro e-colocou rebêd dia sobre seu-colo:');
INSERT INTO verses VALUES (1239, 1, 41, 43, 'e-cavalgou ele בְּמִרְכֶּ֤בֶת הַמִּשְׁנֶה֙ que a-ele e-cham-los diante-dele אַבְרֵ֑ךְ ele sobre sobre todo terra Egito');
INSERT INTO verses VALUES (1240, 1, 41, 44, 'E-disse Pharaoh a José eu Faraó וּבִלְעָדֶ֗יךָ não יָרִ֨ים homem a יָד֛וֹ e-a ragleo em-todo terra Egito');
INSERT INTO verses VALUES (1241, 1, 41, 45, 'E-chamou [פַרְעֹ֣ה] nome-de [צָֽפְנַ֣ת] [פַּעְנֵחַ֒] [וַיִּתֶּן־ל֣וֹ] e-ele-deu a-ele a [כֹּהֵ֥ן] filha-de [לְאִשָּׁ֑ה] sacerdote [יוֹסֵ֖ף] para-mulher e-ele-saiu sobre terra');
INSERT INTO verses VALUES (1242, 1, 41, 46, 'ויהוסף filho-de trinta ano בעמדוהו diante-de faráoh rei-de Egito e-saiu José de-diante-de פַּרְעֹה WAYYAVVOR em-todo terra Egito');
INSERT INTO verses VALUES (1243, 1, 41, 47, 'e-sa- a-terra בְּשֶׁ֖בַע segundo HASVA''AH LIKMATZIM');
INSERT INTO verses VALUES (1244, 1, 41, 48, '[וַיִּקְבֹּ֞ץ] a todo [שֶׁ֣בַע] sete dois que foram em-terra-de Egito e-ele-deu [אֹ֧כֶל] em-cidades [אֲשֶׁ֥ר] [סְבִיבֹתֶ֖יהָ] dar que deu');
INSERT INTO verses VALUES (1245, 1, 41, 49, '[וַיִּצְבֹּ֨ר] [יוֹסֵ֥ף] [בָּ֛ר] [כְּח֥וֹל] o-mar [הַרְבֵּ֣ה] muito até porque [לִסְפֹּ֖ר] [כִּי־אֵ֥ין] porque');
INSERT INTO verses VALUES (1246, 1, 41, 50, 'וּלְיוֹסֵ֤ף יֻלּוּד segundo filhos בטרעם תָּבוֹא ano-de הָרַעֲבָ que deu-a-luz a-ele אָסְנַת filha-de פֶּרַע sacerdote אֹן׃');
INSERT INTO verses VALUES (1247, 1, 41, 51, 'E-chamou José a nome [מְנַשֶּׁ֑ה] Manassés porque- [אֶת־כָּל־עֲמָלִ֔י] e-[OBJ] a todo e-[OBJ] todo casa');
INSERT INTO verses VALUES (1248, 1, 41, 52, 'e-[OBJ] nome o-segundo chamou Efraim porque frutificou-me Elohim em-terra-de');
INSERT INTO verses VALUES (1249, 1, 41, 53, 'e se esvaziaram sete segundo o fome que ser em-terra-de Egito');
INSERT INTO verses VALUES (1250, 1, 41, 54, 'e começaram a ser sete segundo a fome para-vir conforme disse José e-houve רָעָב֙ em-todo as-áreas e-em-todo ser Egito foi pão');
INSERT INTO verses VALUES (1251, 1, 41, 55, 'e se fizeram a fome todo terra Egito e clamou o-povo a E-disse por pão E-disse פרעה para-todo Mitzrayim a-vós a José que diga a-vós façam');
INSERT INTO verses VALUES (1252, 1, 41, 56, 'e-a-fome ser sobre todo a-terra a-terra e abriu José a todo que neles e partiu para os egípcios e fortaleceu o fome em-terra-de Egito');
INSERT INTO verses VALUES (1253, 1, 41, 57, 'e-todo a-terra vieram Egito-para para quebrar a José porque a-terra a-fome em-todo a-terra');
INSERT INTO chapters VALUES (42, 1, 42, 38);
INSERT INTO verses VALUES (1254, 1, 42, 1, 'E-viu Jacó que há Sheber E-disse E-disse Jacó para seus filhos לָ֖מָּה serão alimentados');
INSERT INTO verses VALUES (1255, 1, 42, 2, 'E-disse eis eu ouvi que há Sheber em-Egito desceis lá-baixo e quebrai a-nos de-lá e viveremos e-não que');
INSERT INTO verses VALUES (1256, 1, 42, 3, 'וירדוּ irmãos José dez para-partir bar de-Egito');
INSERT INTO verses VALUES (1257, 1, 42, 4, 'e-a בִּנְיָמִין֙ Ai José não enviou que disse seus-irmaos porque disse para-que-não יִקְרָאֶ֖נּוּ אָסֽוֹן׃');
INSERT INTO verses VALUES (1258, 1, 42, 5, 'e-vieram filhos-de Israel [לִשְׁבֹּ֖ר] no-meio-de [הַבָּאִ֑ים] porque foi [בְּאֶ֥רֶץ] em-terra-de');
INSERT INTO verses VALUES (1259, 1, 42, 6, 'וְיוֹסֵ֗ף ele הַשַּׁלִּ֣יט sobre ele ele הַמַּשְׁבִּ֖יר a-terra povo a-terra e-vieram irmãos José וַיִּשְׁתַּֽחֲווּ־ a-ele Apaim para-terra');
INSERT INTO verses VALUES (1260, 1, 42, 7, 'E-viu José a seus-irmãos וַיַּכִּרֵ֑ם e-o reconheceram a-eles e-ele-falou עם-הם E-disse E-disse para-eles de-onde v-e-eis-vos e-disseram de-terra-de kena''an para-quebrar- comer:');
INSERT INTO verses VALUES (1261, 1, 42, 8, 'e-o reconheceram José a seus-irmaos não não e-eles o reconheceram:');
INSERT INTO verses VALUES (1262, 1, 42, 9, 'e-o recordou José a as-sueños que sonharam a-eles E-disse para-eles espionadores אַתֶּ֔ם para-ver a a-terra a-terra בָּאתֶֽם׃');
INSERT INTO verses VALUES (1263, 1, 42, 10, 'e-disseram a-ele não Adonai [וַעֲבָדֶ֥יךָ] [בָּ֖אוּ] [לִשְׁבָּר־אֹֽכֶל]');
INSERT INTO verses VALUES (1264, 1, 42, 11, '[כֻּלָּ֕נוּ] filhos-de homem-de um [כֵּנִ֣ים] [אֲנַ֔חְנוּ] nós não foram');
INSERT INTO verses VALUES (1265, 1, 42, 12, 'E-disse a-eles não porque a-terra a-terra para-ver');
INSERT INTO verses VALUES (1266, 1, 42, 13, 'e-disseram dois dez עֲבָדֶ֨יךָ irmãos nós filhos-de homem-de um em-terra-de assim e-eis o-pequeno a o-dia o-dia e o único não há');
INSERT INTO verses VALUES (1267, 1, 42, 14, 'E-disse a-eles José ele que falei vocês dizendo espionagem atemu:');
INSERT INTO verses VALUES (1268, 1, 42, 15, 'bázot nós os espionamos viveu Pharaoh se vocês saiam que porque se o-pequeno seus irmãos não até-aqui');
INSERT INTO verses VALUES (1269, 1, 42, 16, '[שִׁלְח֨וּ] [מִכֶּ֣ם] um E-tomou a [וְאַתֶּם֙] e-vós [וְיִבָּֽחֲנוּ֙] [דִּבְרֵיכֶ֔ם] palavras-vosso [אִתְּכֶ֑ם] convosco e-se não que פַּרְעֹה porque [sem-traducao] atemu:');
INSERT INTO verses VALUES (1270, 1, 42, 17, '[וַיֶּאֱסֹ֥ף] eles a [שְׁלֹ֥שֶׁת] três');
INSERT INTO verses VALUES (1271, 1, 42, 18, 'E-disse [אֲלֵהֶ֤ם] José no-dia o-terceiro esta [עֲשׂ֖וּ] e-vivam a Elohim temer temer');
INSERT INTO verses VALUES (1272, 1, 42, 19, 'se [אַתֶּ֔ם] [אֲחִיכֶ֣ם] um um [בְּבֵ֣ית] em-casa-de [וְאַתֶּם֙] e-vós ide [שֶׁ֖בֶר] Sheber [בָּתֵּיכֶֽם]');
INSERT INTO verses VALUES (1273, 1, 42, 20, 'e-a o-pequeno o-pequeno [אֵלַ֔י] a-mim [דִבְרֵיכֶ֖ם] [וְלֹ֣א] e-não morrai e-fizeram assim');
INSERT INTO verses VALUES (1274, 1, 42, 21, 'e-eles-disseram homem a o-seu-irmão [אֲשֵׁמִ֣ים] [׀] [אֲנַחְנוּ֮] sobre [אֲשֶׁ֨ר] que [צָרַ֥ת] [נַפְשׁ֛וֹ] nafsho [אֵלֵ֖ינוּ] a-nós e-não ouvimos sobre assim veio [הַזֹּֽאת] [sem-traducao] a esta');
INSERT INTO verses VALUES (1275, 1, 42, 22, 'e-ele-respondeu Reuben eles dizendo הֲלֹא֩ [אָמַ֨רְתִּי] [אֲלֵיכֶ֧ם] para-dizer dizendo [אַל־תֶּחֶטְא֥וּ] [בַיֶּ֖לֶד] e-não ouvistes e-também eis eis [sem-traducao]');
INSERT INTO verses VALUES (1276, 1, 42, 23, 'e-eles não [יֽ͏ָדְע֔וּ] que ouviu José que [הַמֵּלִ֖יץ] entre-eles-verso-final');
INSERT INTO verses VALUES (1277, 1, 42, 24, '[וַיִּסֹּ֥ב] [מֵֽעֲלֵיהֶ֖ם] [וַיֵּ֑בְךְּ] e-ele-retornou para-eles e-falou a-eles E-tomou [מֵֽאִתָּם֙] a Simeão ele ele');
INSERT INTO verses VALUES (1278, 1, 42, 25, 'E-ordenou José [וַיְמַלְא֣וּ] a [בָּר֒] [וּלְהָשִׁ֤יב] [כַּסְפֵּיהֶם֙] [אִ֣ישׁ] homem a a-eles [צֵדָ֖ה] a-eles justiça a-eles E-fez a-eles assim');
INSERT INTO verses VALUES (1279, 1, 42, 26, 'e-levantaram a [עַל־חֲמֹרֵיהֶ֑ם] sobre [מִשָּֽׁם]');
INSERT INTO verses VALUES (1280, 1, 42, 27, 'e abriu o-primeiro a [לָתֵ֥ת] a-dar [לַחֲמֹר֖וֹ] [בַּמָּל֑וֹן] E-viu E-viu a com-prata-seu e-eis- ele [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1281, 1, 42, 28, 'E-disse a irmãos-de-ele [כַּסְפִּ֔י] [וְגַ֖ם] eis eis [וַיֵּצֵ֣א] e-saiu [וַיֶּֽחֶרְד֞וּ] [אִ֤ישׁ] homem dizendo seu-irmao dizendo que [לָֽנוּ] fez Elohim para-nós');
INSERT INTO verses VALUES (1282, 1, 42, 29, 'and-they-entered a Jacó pai-deles terra-para assim a-ele a-ele a eles dizendo eles para-dizer');
INSERT INTO verses VALUES (1283, 1, 42, 30, 'palavra o-homem Adonai a-terra [אִתָּ֖נוּ] [קָשׁ֑וֹת] E-colocou a-nós [כִּֽמְרַגְּלִ֖ים] a a-terra');
INSERT INTO verses VALUES (1284, 1, 42, 31, '[וַנֹּ֥אמֶר] a-ele כֵּנִ֣ים anachnu não [הָיִ֖ינוּ] מְרַגְּלִֽים׃');
INSERT INTO verses VALUES (1285, 1, 42, 32, 'doze dez nós irmãos filhos-de o-primeiro [אֵינֶ֔נּוּ] não há o-dia o-dia a [כְּנָֽעַן] em-terra-de כְּנָֽעַן');
INSERT INTO verses VALUES (1286, 1, 42, 33, 'E-disse a-nos o-homem Adonai a-terra com-isto eu-saberei que [כֵנִ֖ים] vós [אֲחִיכֶ֤ם] o-primeiro e-nichu comigo e-a [בָּתֵּיכֶ֖ם] [קְח֥וּ] [וָלֵֽכוּ] [sem-traducao]');
INSERT INTO verses VALUES (1287, 1, 42, 34, '[וְ֠הָבִיאוּ] a o-pequeno [אֵלַי֒] [וְאֵֽדְעָ֗ה] que não não espiões que porque [אַתֶּ֑ם] vós a a-vós darei a-vós e-[OBJ] a-terra');
INSERT INTO verses VALUES (1288, 1, 42, 35, 'e-houve eles [מְרִיקִ֣ים] [שַׂקֵּיהֶ֔ם] e-eis- homem [בְּשַׂקּ֑וֹ] [וַיִּרְא֞וּ] [אֶת־צְרֹר֧וֹת] e-eles-veem a [וַאֲבִיהֶ֖ם] [וַיִּירָֽאוּ] eles [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1289, 1, 42, 36, 'E-disse para-eles Jacó pai-deles a-mim [שִׁכַּלְתֶּ֑ם] [יוֹסֵ֤ף] [אֵינֶ֙[t]נּוּ֙] não há e-a [וְאֶת־בִּנְיָמִ֣ן] [תִּקָּ֔חוּ] sobre-mim foram [כֻלָּֽנָה]');
INSERT INTO verses VALUES (1290, 1, 42, 37, 'E-disse Rúben a dizendo dizendo a segundo filhos-de [אֲבִיאֶ֖נּוּ] se não ele a-ti dá ele sobre minha-mão e-eu [sem-traducao] para-ti');
INSERT INTO verses VALUES (1291, 1, 42, 38, 'E-disse não [בְּנִ֖י] filhos-de com-vós porque seu-irmão sozinho ele [וּקְרָאָ֤הוּ] [אָסוֹן֙] [בַּדֶּ֙רֶךְ֙] [אֲשֶׁ֣ר] no-caminho que andais nela [שְׁאֽוֹלָה] a [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO chapters VALUES (43, 1, 43, 34);
INSERT INTO verses VALUES (1292, 1, 43, 1, 'e a fome כָּבוֹד na-terra');
INSERT INTO verses VALUES (1293, 1, 43, 2, 'e-houve como [כִּלּוּ֙] para-comer a [אֲשֶׁ֥ר] que [מִמִּצְרָ֑יִם] E-disse E-disse a-eles pai-deles [שִׁבְרוּ־לָ֥נוּ] [מְעַט־אֹֽכֶל] para-nós pouco- comer:');
INSERT INTO verses VALUES (1294, 1, 43, 3, 'E-disse a-ele Judá dizendo [הָעֵ֣ד] [הֵעִד֩] [בָּ֨נוּ] o-homem dizendo não vereis face-de [אֲחִיכֶ֥ם] [אִתְּכֶֽם]');
INSERT INTO verses VALUES (1295, 1, 43, 4, 'se [מְשַׁלֵּ֥חַ] [אֶת־אָחִ֖ינוּ] a [נֵרְדָ֕ה] [וְנִשְׁבְּרָ֥ה] a-ti [אֹֽכֶל]');
INSERT INTO verses VALUES (1296, 1, 43, 5, 'e-se [מְשַׁלֵּ֖חַ] não não [כִּֽי־הָאִ֞ישׁ] disse [אֵלֵ֙ינוּ֙] disse [פָנַ֔י] não vereis face-de');
INSERT INTO verses VALUES (1297, 1, 43, 6, 'E-disse Israel [לָמָ֥ה] [הֲרֵעֹתֶ֖ם] a-mim para-dizer para-o homem [הַע֥וֹד] a-vós [אָֽח]');
INSERT INTO verses VALUES (1298, 1, 43, 7, 'disseram- [שָׁא֣וֹל] [שָֽׁאַל־הָ֠אִישׁ] האישׁ a-nos dizendo dizendo [אֲבִיכֶ֥ם] vida viveu a-vós para-vós irmão [עַל־פִּ֖י] a-ele sobre o meu as-palavras que [יֹאמַ֔ר] נֵדַע porque [sem-traducao] [sem-traducao] a [sem-traducao]');
INSERT INTO verses VALUES (1299, 1, 43, 8, 'E-disse Judá a seu-pai pai-de-ele [הַנַּ֛עַר] o-jovem ITHI [וְנֵלֵ֑כָה] e neleḵā [וְלֹ֣א] e-não [גַּם־אֲנַ֥חְנוּ] também nós também tu também [sem-traducao]');
INSERT INTO verses VALUES (1300, 1, 43, 9, 'eu [אֽ͏ֶעֶרְבֶ֔נּוּ] [מִיָּדִ֖י] [תְּבַקְשֶׁ֑נּוּ] se não [אֵלֶ֙יךָ֙] a-ti [לְפָנֶ֔יךָ] diante-de-ti a-ti a-ti todo');
INSERT INTO verses VALUES (1301, 1, 43, 10, 'que [לוּלֵ֣א] [הִתְמַהְמָ֑הְנוּ] porque [שַׁ֖בְנוּ] [זֶ֥ה] este');
INSERT INTO verses VALUES (1302, 1, 43, 11, 'E-disse a-eles Israel [אֲבִיהֶ֗ם] se [׀] [אֵפוֹא֮] esta [עֲשׂוּ֒] [קְח֞וּ] [מִזִּמְרַ֤ת] a-terra [בִּכְלֵיכֶ֔ם] [וְהוֹרִ֥ידוּ] לָאִ֖ישׁ [מִנְחָ֑ה] [מְעַ֤ט] [צֳרִי֙] [וּמְעַ֣ט] mel [נְכֹ֣את] e-Lot [בָּטְנִ֖ים] [וּשְׁקֵדִֽים]');
INSERT INTO verses VALUES (1303, 1, 43, 12, '[וְכֶ֥סֶף] [מִשְׁנֶ֖ה] tomem em-vossas-mãos e-a [הַמּוּשָׁ֨ב] [בְּפִ֤י] [אַמְתְּחֹֽתֵיכֶם֙] [תָּשִׁ֣יבוּ] [בְיֶדְכֶ֔ם] [אוּלַ֥י] talvez ele ela');
INSERT INTO verses VALUES (1304, 1, 43, 13, 'e-a [קָ֑חוּ] [וְק֖וּמוּ] [שׁ֥וּבוּ] retornem a o-homem');
INSERT INTO verses VALUES (1305, 1, 43, 14, 'e-a Shaddai יִתֵּן a-vós [רַחֲמִים֙] diante-de o-homem e-ele-mandará a-vós a seus irmãos outro e-a [כַּאֲשֶׁ֥ר] e-eu como [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1306, 1, 43, 15, 'e-tomaram os-homens a [הַזֹּ֔את] esta [לָקְח֥וּ] prata [וְאֶת־בִּנְיָמִ֑ן] em suas mãos e-a Binyamin e levantaram-se e-desceram Egito yhwh diante-de José');
INSERT INTO verses VALUES (1307, 1, 43, 16, 'E-viu José [אִתָּם֮] a E-disse E-disse [עַל־בֵּית֔וֹ] sobre casa-dele [הַבָּ֑יְתָה] a os-homens a-casa que טֶ֙בַח֙ [יֹאכְל֥וּ] porque comigo comerão muito [sem-traducao]');
INSERT INTO verses VALUES (1308, 1, 43, 17, 'E-fez o-homem [כַּֽאֲשֶׁ֖ר] disse José e-trouxe o-homem a os-homens casa-seu José');
INSERT INTO verses VALUES (1309, 1, 43, 18, '[וַיִּֽירְא֣וּ] [הָֽאֲנָשִׁ֗ים] que [הֽוּבְאוּ֮] casa José e-disseram sobre palavra a-prata [בְּאַמְתְּחֹתֵ֙ינוּ֙] [בַּתְּחִלָּ֔ה] no-primeiro nos [לְהִתְגֹּלֵ֤ל] [עָלֵ֙ינוּ֙] sobre-nos [עָלֵ֔ינוּ] sobre-nós [אֹתָ֛נוּ] a-nós aos-escravos e-a [sem-traducao]');
INSERT INTO verses VALUES (1310, 1, 43, 19, '[וַֽיִּגְּשׁוּ֙] a o-homem que sobre casa a-ele [פֶּ֥תַח] a-ele');
INSERT INTO verses VALUES (1311, 1, 43, 20, 'e-disseram por-mim Adonai [יָרֹ֥ד] [יָרַ֛דְנוּ] em-o-início para-quebrar- comer:');
INSERT INTO verses VALUES (1312, 1, 43, 21, 'e-houve porque [אֶל־הַמָּל֗וֹן] a [אֶת־אַמְתְּחֹתֵ֔ינוּ] [וְהִנֵּ֤ה] a [בְּפִ֣י] e-eis [כַּסְפֵּ֖נוּ] homem [וַנָּ֥שֶׁב] ele [בְּיָדֵֽנוּ]');
INSERT INTO verses VALUES (1313, 1, 43, 22, '[וְכֶ֧סֶף] [אַחֵ֛ר] [הוֹרַ֥דְנוּ] [בְיָדֵ֖נוּ] para-quebrar- não não [מִי־שָׂ֥ם] quem nome [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1314, 1, 43, 23, 'E-disse [שָׁל֨וֹם] a-vós a [Elohim] [וֽ͏ֵאלֹהֵ֤י] [אֲבִיכֶם֙] dar a-vós a-vos [בְּאַמְתְּחֹ֣תֵיכֶ֔ם] [כַּסְפְּכֶ֖ם] [בָּ֣א] veio a-mim e-ele-saiu a-eles a Simeão');
INSERT INTO verses VALUES (1315, 1, 43, 24, 'e-trouxe o-homem a os-homens [יוֹסֵ֑ף] José e-ele-deu águas E-colocou [מִסְפּ֖וֹא] E-deu');
INSERT INTO verses VALUES (1316, 1, 43, 25, '[וַיָּכִ֙ינוּ֙] a a oferta-cereais até vir que בָּצְהָרָיִם porque ouviram porque nome [sem-traducao] pão');
INSERT INTO verses VALUES (1317, 1, 43, 26, 'E-veio José a-casa [וַיָּבִ֥יאּוּ] a-ele a [אֲשֶׁר־בְּיָדָ֖ם] que byeidam a-casa e-se-prostraram para-ele para-terra');
INSERT INTO verses VALUES (1318, 1, 43, 27, 'e-ele-perguntou a-eles [לְשָׁל֔וֹם] E-disse [הֲשָׁל֛וֹם] [אֲבִיכֶ֥ם] [הַזָּקֵ֖ן] que אֲמַרְתֶּ֑ם [הַעוֹדֶ֖נּוּ] viveu');
INSERT INTO verses VALUES (1319, 1, 43, 28, 'e-disseram paz [לְעַבְדְּךָ֥] [לְאָבִ֖ינוּ] ainda-ele viveu e-inclinaram-se');
INSERT INTO verses VALUES (1320, 1, 43, 29, 'e levantou os-seus-olhos E-viu a [אָחִיו֮] [בֶּן־אִמּוֹ֒] E-disse [הֲזֶה֙] E-disse o-pequeno [אֲשֶׁ֥ר] [אֲמַרְתֶּ֖ם] que אֲמַרְתֶּ֖ם a-mim E-disse Elohim [sem-traducao] filhos-de');
INSERT INTO verses VALUES (1321, 1, 43, 30, 'vayemaher José porque [רַחֲמָיו֙] רַחֲמָיו֙ a irmão-seu e-buscou [הַחַ֖דְרָה] E-veio [שָֽׁמָּה] וַיֵּ֥בְךְּ ali');
INSERT INTO verses VALUES (1322, 1, 43, 31, 'e-ele-se-lavou sua-face [וַיֵּצֵ֑א] [וַיִּ֨תְאַפַּ֔ק] E-disse שִׂ֥ימוּ pão');
INSERT INTO verses VALUES (1323, 1, 43, 32, 'e-os-colocaram a-ele sozinho e-para-eles [לְבַדָּ֑ם] [וְלַמִּצְרִ֞ים] [הָאֹכְלִ֤ים] com-ele [לְבַדָּ֔ם] que não [יוּכְל֜וּן] os egípcios [לֶאֱכֹ֤ל] a pão Belém ela [לְמִצְרָֽיִם] a-vós [sem-traducao]');
INSERT INTO verses VALUES (1324, 1, 43, 33, 'e-habitaram diante-dele [הַבְּכֹר֙] [כִּבְכֹ֣רָת֔וֹ] [וְהַצָּעִ֖יר] [כִּצְעִרָת֑וֹ] [וַיִּתְמְה֥וּ] os-homens homem a');
INSERT INTO verses VALUES (1325, 1, 43, 34, 'e-ele-leva [מַשְׂאֹ֜ת] de-junto-de em-seus-faces אֲלֵהֶם֒ [וַתֵּ֜רֶב] [מַשְׂאַ֧ת] Benjamim [מִמַּשְׂאֹ֥ת] kulam cinco [יָד֑וֹת] [וַיִּשְׁתּ֥וּ] [וַֽיִּשְׁכְּר֖וּ] com-ele');
INSERT INTO chapters VALUES (44, 1, 44, 34);
INSERT INTO verses VALUES (1326, 1, 44, 1, 'E-ordenou a que dizendo [מַלֵּ֞א] dizendo enchei a [כַּאֲשֶׁ֥ר] os-homens [שְׂאֵ֑ת] como-que [כֶּֽסֶף־אִ֖ישׁ] [בְּפִ֥י] [אַמְתַּחְתּֽוֹ] homem');
INSERT INTO verses VALUES (1327, 1, 44, 2, 'e-[OBJ] [גְּבִ֣יעַ] [הַכֶּ֗סֶף] [תָּשִׂים֙] [בְּפִי֙] [אַמְתַּ֣חַת] o-pequeno e-[OBJ] e-[OBJ] prata [וַיַּ֕עַשׂ] E-fez conforme-palavra-de José que palavra');
INSERT INTO verses VALUES (1328, 1, 44, 3, '[הַבֹּ֖קֶר] luz e-os-homens [שֻׁלְּח֔וּ] eles [וַחֲמֹרֵיהֶֽם]');
INSERT INTO verses VALUES (1329, 1, 44, 4, 'eles [יָֽצְא֣וּ] a não não [וְיוֹסֵ֤ף] disse disse [עַל־בֵּית֔וֹ] sobre casa-dele levantou [הָֽאֲנָשִׁ֑ים] depois-de [וְאָמַרְתָּ֣] [אֲלֵהֶ֔ם] e-dirás a-eles por-que debaixo maldade debaixo-de boa');
INSERT INTO verses VALUES (1330, 1, 44, 5, 'não este que [יִשְׁתֶּ֤ה] Adonai nele e ele [נַחֵ֥שׁ] [יְנַחֵ֖שׁ] nele [הֲרֵעֹתֶ֖ם] que vocês-fizeram');
INSERT INTO verses VALUES (1331, 1, 44, 6, '[וַֽיַּשִּׂגֵ֑ם] e-falou a-eles a as-palavras');
INSERT INTO verses VALUES (1332, 1, 44, 7, 'e-disseram a-ele por-que יְדַבֵּ֣ר Adonai segundo-as-palavras estas [חָלִ֙ילָה֙] para-o-servos-teus [מֵעֲשׂ֖וֹת] como a palavra a-esta');
INSERT INTO verses VALUES (1333, 1, 44, 8, 'eis prata que [מָצָ֙אנוּ֙] בְּפִ֣י [אַמְתְּחֹתֵ֔ינוּ] [הֱשִׁיבֹ֥נוּ] a-ti da-terra assim [וְאֵ֗יךְ] [נִגְנֹב֙] de-casa-de [אֲדֹנֶ֔יךָ] prata ou ouro');
INSERT INTO verses VALUES (1334, 1, 44, 9, 'que será-encontrado [אִתּ֛וֹ] [מֵעֲבָדֶ֖יךָ] ומות e-também [נִֽהְיֶ֥ה] [לַֽאדֹנִ֖י] לאדוני para-servos');
INSERT INTO verses VALUES (1335, 1, 44, 10, 'E-disse também עַתָּה [כֶּן־ה֑וּא] assim ele que será achado com-ele ser- para-mim servo e-vós תִּהְי֥וּ justo');
INSERT INTO verses VALUES (1336, 1, 44, 11, '[וֽ͏ַיְמַהֲר֗וּ] [וַיּוֹרִ֛דוּ] homem a [אָ֑רְצָה] terra [אִ֥ישׁ] homem [sem-traducao]');
INSERT INTO verses VALUES (1337, 1, 44, 12, 'e procurou [בַּגָּד֣וֹל] começou [וּבַקָּטֹ֖ן] [כִּלָּ֑ה] [וַיִּמָּצֵא֙] [הַגָּבִ֔יעַ] [בְּאַמְתַּ֖חַת] Benjamin');
INSERT INTO verses VALUES (1338, 1, 44, 13, '[וֽ͏ַיִּקְרְע֖וּ] [שִׂמְלֹתָ֑ם] [וַֽיַּעֲמֹס֙] homem sobre [וַיָּשֻׁ֖בוּ] e-eles-retornaram');
INSERT INTO verses VALUES (1339, 1, 44, 14, 'E-veio Judá ve-echav [בֵּ֣יתָה] José e-ele ainda-ele nome וייפלוּ diante-dele para-terra');
INSERT INTO verses VALUES (1340, 1, 44, 15, 'E-disse a-eles José que [הַזֶּ֖ה] este que עֲשִׂיתֶ֑ם não Yedautem porque [אִ֖ישׁ] [אֲשֶׁ֥ר] homem que [sem-traducao]');
INSERT INTO verses VALUES (1341, 1, 44, 16, 'E-disse Judá que [לַֽאדֹנִ֔י] para-o-senhore∶ que [הָאֱלֹהִ֗ים] encontrou [אֶת־עֲוֺ֣ן] os-Elohim [הִנֶּ֤נּוּ] a iniquidade teus-servos também [אֲשֶׁר־נִמְצָ֥א] para-o-senhore∶ também [sem-traducao] também que nimtsá [sem-traducao] em-mão-sua');
INSERT INTO verses VALUES (1342, 1, 44, 17, 'E-disse longe-seja a-mim [מֵעֲשׂ֖וֹת] esta o homem que [נִמְצָ֨א] [הַגָּבִ֜יעַ] [בְּיָד֗וֹ] ele ser- para-mim servo [עֲל֥וּ] ALU לְשָׁל֖וֹם a [sem-traducao]');
INSERT INTO verses VALUES (1343, 1, 44, 18, 'e-ele-aproximou-se a-ele Judá E-disse por-mim Adonai YEDABER- por-favor servo-teu palavra em-orelhas-de Adonai e-a [בְּעַבְדֶּ֑ךָ] que [כָמ֖וֹךָ] porque [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1344, 1, 44, 19, 'Adonai [שָׁאַ֔ל] a dizendo dizendo pai para-vós pai');
INSERT INTO verses VALUES (1345, 1, 44, 20, '[וַנֹּ֙אמֶר֙] a Adonai pai a-nós pai velho [קָטָ֑ן] [וְאָחִ֨יו] pequeno [וַיִּוָּתֵ֨ר] ele sozinho ele [וְאָבִ֥יו] [אֲהֵבֽוֹ]');
INSERT INTO verses VALUES (1346, 1, 44, 21, 'E-disse a teus-servos הורידוהו a-mim [עֵינִ֖י] [עָלָֽיו] sobre-ele');
INSERT INTO verses VALUES (1347, 1, 44, 22, '[וַנֹּ֙אמֶר֙] a Adonai não poderia o-menino [וְעָזַ֥ב] a pai-seu [sem-traducao] a pai-dele e-morreu');
INSERT INTO verses VALUES (1348, 1, 44, 23, 'E-disse a teus-servos se não o-pequeno seus irmãos não convosco para-ver voces-aumentariam para-ver face-de');
INSERT INTO verses VALUES (1349, 1, 44, 24, 'e-houve que [עָלִ֔ינוּ] a servo-teu pai-meu [OBJ] a-ele a Adonai');
INSERT INTO verses VALUES (1350, 1, 44, 25, 'E-disse [אָבִ֑ינוּ] [שֻׁ֖בוּ] [שִׁבְרוּ־לָ֥נוּ] para-nós');
INSERT INTO verses VALUES (1351, 1, 44, 26, 'וַנֹּ֕אמֶר não [נוּכַ֖ל] para-descer se [אָחִ֨ינוּ] o-pequeno [אִתָּ֙נוּ֙] com-nos [כִּי־לֹ֣א] porque para-ver face-de para-ver face-de o-pequeno [אֵינֶ֥נּוּ] [אִתָּֽנוּ] não-ela com-nos');
INSERT INTO verses VALUES (1352, 1, 44, 27, 'E-disse avadcha meu-pai a-nós vós Yedautem que dois deu-a-luz para-mim minha-esposa-');
INSERT INTO verses VALUES (1353, 1, 44, 28, 'e-saiu o-primeiro de-mi- e-eu-disse mas- [טָרֹ֣ף] [טֹרָ֑ף] e-não [רְאִיתִ֖יו] até até-aqui');
INSERT INTO verses VALUES (1354, 1, 44, 29, '[וּלְקַחְתֶּ֧ם] também a este de-com face-de [וְהֽוֹרַדְתֶּ֧ם] אָסֹון [בְּרָעָ֖ה] a [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1355, 1, 44, 30, 'e-agora [כְּבֹאִי֙] a seu-escravo-teu-servo meu-pai e-o-menino não há אִתָּ֑נוּ e-seu-espírito [בְנַפְשֽׁוֹ] [sem-traducao]');
INSERT INTO verses VALUES (1356, 1, 44, 31, 'e-foi [כִּרְאוֹת֛וֹ] porque não-há o-menino ומות [עֲבָדֶ֜יךָ] [אֶת־שֵׂיבַ֨ת] a [אָבִ֛ינוּ] avadcha nosso-pai [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1357, 1, 44, 32, 'que teu-servo tarde a o jovem de-com dizendo dizendo se não [וְחָטָ֥אתִי] para-ti [כָּל־הַיָּמִֽים] todo');
INSERT INTO verses VALUES (1358, 1, 44, 33, 'e-agora [יֵֽשֶׁב־נָ֤א] por-favor debaixo em-lugar-de o jovem servo [וְהַנַּ֖עַר] e-o-menino [עִם־אֶחָֽיו] com');
INSERT INTO verses VALUES (1359, 1, 44, 34, 'porque [אֶֽעֱלֶ֣ה] [אֶל־אָבִ֔י] a pai-meu e-o-menino para-que-não comigo [בָרָ֔ע] verei [יִמְצָ֖א] que [sem-traducao] a pai-meu');
INSERT INTO chapters VALUES (45, 1, 45, 28);
INSERT INTO verses VALUES (1360, 1, 45, 1, 'e-não [יוֹסֵ֜ף] José a-todo para-todo [עָלָ֔יו] E-chamou E-chamou [כָל־אִ֖ישׁ] todo homem de-mim-sobre e-não ficou-em-pé homem com-ele [sem-traducao] José a אֶחָֽיו׃');
INSERT INTO verses VALUES (1361, 1, 45, 2, 'E-colocou a seu-grito [וַיִּשְׁמְע֣וּ] e-ouviram Egito E-ouviu casa פַּרְעֹה');
INSERT INTO verses VALUES (1362, 1, 45, 3, 'E-disse [יוֹסֵ֤ף] a irmãos-de-ele eu José [אָבִ֖י] pai-meu viveu e-não [לַעֲנ֣וֹת] ele que a-ele porque');
INSERT INTO verses VALUES (1363, 1, 45, 4, 'E-disse [יוֹסֵ֧ף] a [גְּשׁוּ־נָ֥א] [אֵלַ֖י] agora E-disse [אֲנִי֙] E-disse eu José [אֹתִ֖י] que');
INSERT INTO verses VALUES (1364, 1, 45, 5, 'e-agora a [אַל־תֵּעָ֣צְב֗וּ] e-a se encolerizou [כִּֽי־מְכַרְתֶּ֥ם] porque [הֵ֑נָּה] que aqui-estes porque para-preservação enviou-me Elohim diante-vos');
INSERT INTO verses VALUES (1365, 1, 45, 6, 'porque este [הָרָעָ֖ב] a-fome a-terra a-terra [חָמֵ֣שׁ] cinco dois que não-há [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1366, 1, 45, 7, '[וַיִּשְׁלָחֵ֤נִי] Elohim diante-de-vós להשם a-vós sheerit em-a-terra [וּלְהַחֲי֣וֹת] a-vós [לִפְלֵיטָ֖ה] [גְּדֹלָֽה]');
INSERT INTO verses VALUES (1367, 1, 45, 8, 'e-agora não atem [אֹתִי֙] oti'' que porque o-Elohim [לְאָ֜ב] [לְפַרְעֹ֗ה] [וּלְאָדוֹן֙] [לְכָל־בֵּית֔וֹ] para-todo casa-dele [מִצְרָֽיִם] em-todo terra Egito');
INSERT INTO verses VALUES (1368, 1, 45, 9, '[מַהֲרוּ֮] [וַעֲל֣וּ] a avi a-ele a-ele disse disse [יוֹסֵ֔ף] José pôs-me Elohim [לְכָל־מִצְרָ֑יִם] para-todo Egito dominai para-mim a terá-se-estabelecido');
INSERT INTO verses VALUES (1369, 1, 45, 10, '[וְיָשַׁבְתָּ֣] em-terra-de [וְהָיִ֤יתָ] [קָרוֹב֙] proximo tu tu [וּבְנֵ֣י] e-filhos-de בניך [וּבְקָרְךָ֖] [וְכָל־אֲשֶׁר־לָֽךְ] e-todo que para-ti');
INSERT INTO verses VALUES (1370, 1, 45, 11, '[וְכִלְכַּלְתִּ֤י] o-te nome porque ainda cinco dois רָעָ֑ב tu [וּבֵֽיתְךָ֖] tu [sem-traducao] e-todo que para-ti');
INSERT INTO verses VALUES (1371, 1, 45, 12, 'e-eis vossos-olhos [רֹא֔וֹת] וְעֵינֵ֖י achi Benjamin porque [הַֽמְדַבֵּ֥ר] [אֲלֵיכֶֽם] a-vós');
INSERT INTO verses VALUES (1372, 1, 45, 13, '[וְהִגַּדְתֶּ֣ם] [לְאָבִ֗י] a todo e-[OBJ] em-Egito e-a todo que [אֶת־אָבִ֖י] [הֵֽנָּה] e-vós-fareis-descer a pai-meu até-aqui');
INSERT INTO verses VALUES (1373, 1, 45, 14, 'e-ele-caiu sobre [בִנְיָמִֽן־אָחִ֖יו] [וַיֵּ֑בְךְּ] irmão-seu [בָּכָ֖ה] e-Benjamim chorou sobre [sem-traducao]');
INSERT INTO verses VALUES (1374, 1, 45, 15, '[וַיְנַשֵּׁ֥ק] para-todo seus-irmãos [עֲלֵיהֶ֑ם] sobre-eles [כֵ֔ן] assim [אֶחָ֖יו] seus-irmãos');
INSERT INTO verses VALUES (1375, 1, 45, 16, '[וְהַקֹּ֣ל] [נִשְׁמַ֗ע] casa Faraó dizendo entraram irmãos José e-foi-bom em-olhos-de פַּרְעֹה e-em-olhos-de seus-servos');
INSERT INTO verses VALUES (1376, 1, 45, 17, 'E-disse Faraó a José disse esta [עֲשׂ֑וּ] [טַֽעֲנוּ֙] fazei [וּלְכוּ־בֹ֖אוּ] a [כְּנָֽעַן]');
INSERT INTO verses VALUES (1377, 1, 45, 18, '[וּקְח֧וּ] a [וְאֶת־בָּתֵּיכֶ֖ם] e-[OBJ] [אֵלָ֑י] [וְאֶתְּנָ֣ה] a-vós [אֶת־טוּב֙] terra a bom terra a-terra a a-terra');
INSERT INTO verses VALUES (1378, 1, 45, 19, 've-a-ta-ha [צֻוֵּ֖יתָה] esta fazei tomai [מֵאֶ֨רֶץ] de-terra-de Egito [לְטַפְּכֶם֙] [וְלִנְשֵׁיכֶ֔ם] [וּנְשָׂאתֶ֥ם] [אֶת־אֲבִיכֶ֖ם] a [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1379, 1, 45, 20, '[וְעֵ֣ינְכֶ֔ם] a [עַל־כְּלֵיכֶ֑ם] sobre [כָּל־אֶ֥רֶץ] porque a-vós ele terra');
INSERT INTO verses VALUES (1380, 1, 45, 21, 'e-ele-fizeram- assim filhos-de E-colocou a-eles a-eles José [עַל־פִּ֣י] sobre E-colocou a-eles E-deu a-eles justiça [sem-traducao]');
INSERT INTO verses VALUES (1381, 1, 45, 22, '[לְכֻלָּ֥ם] dar לָאִ֖ישׁ chal-pot [שְׂמָלֹ֑ת] [וּלְבִנְיָמִ֤ן] dar três centenas-de prata e-cinco [חֲלִפֹ֥ת] [שְׂמָלֹֽת]');
INSERT INTO verses VALUES (1382, 1, 45, 23, '[וּלְאָבִ֞יו] enviou [כְּזֹאת֙] asarah [חֲמֹרִ֔ים] carregando [מִטּ֣וּב] Egito [וְעֶ֣שֶׂר] [אֲתֹנֹ֡ת] [נֹֽ֠שְׂאֹת] [בָּ֣ר] [וָלֶ֧חֶם] [וּמָז֛וֹן] [לְאָבִ֖יו] [לַדָּֽרֶךְ]');
INSERT INTO verses VALUES (1383, 1, 45, 24, 'e-enviou a seus-irmãos E-disse E-disse a-eles a');
INSERT INTO verses VALUES (1384, 1, 45, 25, 'e-ele-levantaram-se de-Egito e-vieram terra Canaã a Jacó pai-deles');
INSERT INTO verses VALUES (1385, 1, 45, 26, '[וַיַּגִּ֨דוּ] a-ele dizendo ainda José vida e-quando ele [בְּכָל־אֶ֣רֶץ] em-todo terra Egito que coração-dele a-eles não [sem-traducao] para-eles');
INSERT INTO verses VALUES (1386, 1, 45, 27, 'e-falaram a-ele a todo דְּבָרַי José que palavra E-viu E-viu a [יוֹסֵ֖ף] que ele José espírito a-ela [אֲבִיהֶֽם] espírito Jacó pai-deles');
INSERT INTO verses VALUES (1387, 1, 45, 28, 'E-disse Israel muito [עוֹד־יוֹסֵ֥ף] [בְּנִ֖י] filhos-de viveu [וְאֶרְאֶ֖נּוּ] [בְּטֶ֥רֶם] [אָמֽוּת]');
INSERT INTO chapters VALUES (46, 1, 46, 34);
INSERT INTO verses VALUES (1388, 1, 46, 1, '[וַיִּסַּ֤ע] Israel e-todo que a-ele E-veio [וַיִּזְבַּ֣ח] sete e-sacrificou seu-pai לֵאלֹהֵ֖י seu-pai Isaque');
INSERT INTO verses VALUES (1389, 1, 46, 2, 'E-disse Elohim para-o-Israel [לְיִשְׂרָאֵל֙] a-noite E-disse E-disse Jacó E-disse eis-me');
INSERT INTO verses VALUES (1390, 1, 46, 3, 'E-disse eu o-elohim Elohim-de teu-pai a [מֵרְדָ֣ה] [מִצְרַ֔יְמָה] Egito-para porque para-povo grande [sem-traducao] nome');
INSERT INTO verses VALUES (1391, 1, 46, 4, 'eu [אֵרֵ֤ד] contigo Egito-para e-eu [אַֽעַלְךָ֣] também [וְיוֹסֵ֕ף] [יָשִׁ֥ית] sua-mão mão-sua sobre de-tus-teus-olhos');
INSERT INTO verses VALUES (1392, 1, 46, 5, 'E-levantou Jacó [מִבְּאֵ֣ר] sete [וַיִּשְׂא֨וּ] filhos-de Israel a Jacó [וְאֶת־נְשֵׁיהֶ֔ם] e-[OBJ] [אֲשֶׁר־שָׁלַ֥ח] e-[OBJ] [לָשֵׂ֥את] ele que enviou');
INSERT INTO verses VALUES (1393, 1, 46, 6, 'e-eles-tomaram a de-seus-bens e-a o-seu-bens que [כְּנַ֔עַן] em-terra-de Canaã e-vieram Egito-para Jacó e-todo [sem-traducao] com-ele');
INSERT INTO verses VALUES (1394, 1, 46, 7, '[בָּנָ֞יו] e-filhos-de seus-filhos com-ele [בְּנֹתָ֛יו] [וּבְנ֥וֹת] seus-filhos e-todo [הֵבִ֥יא] trouxe com-ele de Egito:');
INSERT INTO verses VALUES (1395, 1, 46, 8, 've-Eleh [שְׁמ֧וֹת] filhos-de Israel os-que-vêm [יַעֲקֹ֣ב] Jacó e-seus-filhos [יַעֲקֹ֖ב] Jacó Reuven-verso');
INSERT INTO verses VALUES (1396, 1, 46, 9, 'e-filhos-de Rúben Hanoque e-palu [וְחֶצְר֥וֹן] e-karmiː');
INSERT INTO verses VALUES (1397, 1, 46, 10, 'e-filhos-de Shimon- [יְמוּאֵ֧ל] [וְיָמִ֛ין] [וְאֹ֖הַד] ve-Yakin [וְצֹ֑חַר] ve-Shaul filho-de [sem-traducao]');
INSERT INTO verses VALUES (1398, 1, 46, 11, 'e-filhos-de Levi Gérson Coate e-Merari');
INSERT INTO verses VALUES (1399, 1, 46, 12, 'e-filhos-de Judá [עֵ֧ר] [וְאוֹנָ֛ן] [וְשֵׁלָ֖ה] [וָפֶ֣רֶץ] [וָזָ֑רַח] E-morreu Er e-Onã em-terra-de Canaã e-foram filhos-de Perez Hezrom');
INSERT INTO verses VALUES (1400, 1, 46, 13, 'e-filhos-de [יִשָׂשכָ֑ר] [תּוֹלָ֥ע] [וּפֻוָּ֖ה[t]] [וְי֥וֹב]');
INSERT INTO verses VALUES (1401, 1, 46, 14, 'e-filhos-de Zebulom [סֶ֥רֶד] [וְאֵל֖וֹן] [וְיַחְלְאֵֽל]');
INSERT INTO verses VALUES (1402, 1, 46, 15, 'Estas filhos-de Lea que [אֲשֶׁ֨ר] le-ya''akov [לְיַעֲקֹב֙] Arã e-a דִּינָ֣ה [דִּינָ֣ה] todo alma os-filhos-dele [וּבְנוֹתָ֖יו] trinta [וְשָׁלֹֽשׁ]');
INSERT INTO verses VALUES (1403, 1, 46, 16, 'e-filhos-de Gade [צִפְי֥וֹן] [וְחַגִּ֖י] [שׁוּנִ֣י] [וְאֶצְבֹּ֑ן] [עֵרִ֥י] [וַֽאֲרוֹדִ֖י] [וְאַרְאֵלִֽי]');
INSERT INTO verses VALUES (1404, 1, 46, 17, 'e-filhos-de que [יִמְנָ֧ה] [וְיִשְׁוָ֛ה] [וְיִשְׁוִ֥י] [וּבְרִיעָ֖ה] [וְשֶׂ֣רַח] [אֲחֹתָ֑ם] e-filhos-de [בְרִיעָ֔ה] [חֶ֖בֶר] [וּמַלְכִּיאֵֽל]');
INSERT INTO verses VALUES (1405, 1, 46, 18, 'Estas filhos-de [זִלְפָּ֔ה] que deu Labao [בִתּ֑וֹ] [וַתֵּ֤לֶד] ela-deu-a-luz- a estes a-Jacó seis dez alma');
INSERT INTO verses VALUES (1406, 1, 46, 19, 'filhos-de [רָחֵל֙] mulher-de Jacó José e-Benjamin:');
INSERT INTO verses VALUES (1407, 1, 46, 20, '[וַיִּוָּלֵ֣ד] [לְיוֹסֵף֮] na-terra Egito que deu-a-luz a-ele אָסְנַת filha-de פֶּרַע sacerdote [אֶת־מְנַשֶּׁ֖ה] a ménashé e-a Efrayim');
INSERT INTO verses VALUES (1408, 1, 46, 21, 'e-filhos-de [בִנְיָמִ֗ן] [בֶּ֤לַע] [וָבֶ֙כֶר֙] [וְאַשְׁבֵּ֔ל] [גֵּרָ֥א] [וְנַעֲמָ֖ן] [אֵחִ֣י] [וָרֹ֑אשׁ] [מֻפִּ֥ים] [וְחֻפִּ֖ים] [וָאָֽרְדְּ]');
INSERT INTO verses VALUES (1409, 1, 46, 22, 'Estas filhos-de Rachel que nasceu לְיַעֲקֹ֑ב todo quatro quatro dez');
INSERT INTO verses VALUES (1410, 1, 46, 23, 'e-filhos-de Dan [sem-traducao]');
INSERT INTO verses VALUES (1411, 1, 46, 24, 'e-filhos-de Naftali [יַחְצְאֵ֥ל] [וְגוּנִ֖י] [וְיֵ֥צֶר] [וְשִׁלֵּֽם]');
INSERT INTO verses VALUES (1412, 1, 46, 25, 'Estas filhos-de [בִלְהָ֔ה] que deu Labao [בִּתּ֑וֹ] [וַתֵּ֧לֶד] e-deleveu a estes para-Jacobe todo alma sete');
INSERT INTO verses VALUES (1413, 1, 46, 26, 'todo [הַבָּאָ֨ה] [לְיַעֲקֹ֤ב] [מִצְרַ֙יְמָה֙] de-Mitsraymah [יְרֵכ֔וֹ] [מִלְּבַ֖ד] fora-de-a mulheres-de filhos-de Jacó todo alma sessenta [sem-traducao]');
INSERT INTO verses VALUES (1414, 1, 46, 27, 'e-filhos-de José que nasceu a-ele [שְׁנָ֑יִם] alma dois todo a alma para-a-casa-de Jacó a-vindo-a [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1415, 1, 46, 28, 'e-[OBJ] [שָׁלַ֤ח] enviou diante-dele a José [גֹּ֑שְׁנָה] diante-dele [אַ֥רְצָה] e-vieram');
INSERT INTO verses VALUES (1416, 1, 46, 29, '[וַיֶּאְסֹ֤ר] José [מֶרְכַּבְתּ֔וֹ] e-subiu [לִקְרַֽאת־יִשְׂרָאֵ֥ל] seu-pai pai-dele [וַיֵּרָ֣א] a-ele a-ele e-caiu sobre [עַל־צַוָּארָ֖יו] [עֽוֹד] sobre');
INSERT INTO verses VALUES (1417, 1, 46, 30, 'E-disse Israel a José [הַפָּ֑עַם] a-vez depois-de [אֶת־פָּנֶ֔יךָ] que perante-você porque ainda-tu viveu');
INSERT INTO verses VALUES (1418, 1, 46, 31, 'E-disse [יוֹסֵ֤ף] a irmãos-de-ele seu-pai casa pai-dele subirei [וְאֹֽמְרָ֣ה] a-ele [אַחַ֧י] para-ele [אֲשֶׁ֥ר] e-casa-de meu-pai que em-terra-de kena''an a-noite para-mim');
INSERT INTO verses VALUES (1419, 1, 46, 32, 'e-os-homens [רֹ֣עֵי] rebanho porque homens-de [הָי֑וּ] foram [וּבְקָרָ֛ם] [וְכָל־אֲשֶׁ֥ר] a-eles que a-eles [sem-traducao]');
INSERT INTO verses VALUES (1420, 1, 46, 33, 'e-será porque a-vós para-vocês Faraó e-disse que- [sem-traducao]');
INSERT INTO verses VALUES (1421, 1, 46, 34, 'וַאֲמַרְתֶּ֗ם homens-de [מִקְנֶ֜ה] eram servos-teus [מִנְּעוּרֵ֣ינוּ] e-até até-agora também nos também nossos-pais [גֹּ֔שֶׁן] [כִּֽי־תוֹעֲבַ֥ת] em-terra-de goshen porque yhwh Egito todo [sem-traducao] ovelhas-.');
INSERT INTO chapters VALUES (47, 1, 47, 31);
INSERT INTO verses VALUES (1422, 1, 47, 1, 'E-veio יוֹסֵף֮ e-anunciou [לְפַרְעֹה֒] E-disse [אָבִ֨י] [וְאַחַ֜י] [וְצֹאנָ֤ם] [וּבְקָרָם֙] e-todo a-eles a-eles entraram da-terra assim e eis-los em-terra-de [sem-traducao]');
INSERT INTO verses VALUES (1423, 1, 47, 2, '[וּמִקְצֵ֣ה] seus-irmãos tomou cinco homens [וַיַּצִּגֵ֖ם] diante-de Faraó');
INSERT INTO verses VALUES (1424, 1, 47, 3, 'E-disse Pharaoh a seus-irmãos que [אֶל־פַּרְעֹ֗ה] e-disseram a פַּרְעֹה [גַּם־אֲנַ֖חְנוּ] [גַּם־אֲבוֹתֵֽינוּ] teus-servos também nós-mesmos também [sem-traducao]');
INSERT INTO verses VALUES (1425, 1, 47, 4, 'e-disseram a פַּרְעֹה para-viver em-a-terra [כִּי־אֵ֣ין] porque não-há [אֲשֶׁ֣ר] [לַעֲבָדֶ֔יךָ] que para-o-servos-teus porque grande e-agora na-terra assim e-agora [גֹּֽשֶׁן] agora servos-teus em-terra-de [sem-traducao]');
INSERT INTO verses VALUES (1426, 1, 47, 5, 'E-disse Faraó a dizendo dizendo seu pai [בָּ֥אוּ] entraram para-ti');
INSERT INTO verses VALUES (1427, 1, 47, 6, 'terra Egito diante de ti ela [בְּמֵיטַ֣ב] a-terra [הוֹשֵׁ֥ב] a teu-pai e-a [בְּאֶ֣רֶץ] יִשַׁבּוּ na-terra goshen e-se conheceste [שָׂרֵ֥י] [מִקְנֶ֖ה] homens de valente [sem-traducao] príncipes-de [sem-traducao] sobre que a-mim');
INSERT INTO verses VALUES (1428, 1, 47, 7, 'e-trouxe José a seu-pai pai-dele [לִפְנֵ֣י] diante-de E-abençoou E-abençoou Jacó a');
INSERT INTO verses VALUES (1429, 1, 47, 8, 'E-disse פַּרְעֹה a Jacó dias-de dias de tua-vida vidas-tuas');
INSERT INTO verses VALUES (1430, 1, 47, 9, 'E-disse Jacó a dias-de os-dias segundo [שְׁלֹשִׁ֥ים] trinta e-cem ano pouco [הָיוּ֙] dias-de os-dias segundo [וְלֹ֣א] e-não [אֶת־יְמֵי֙] a os-dias segundo chayyei [מְגוּרֵיהֶֽם] nos-dias [sem-traducao]');
INSERT INTO verses VALUES (1431, 1, 47, 10, 'E-abençoou Jacó a Faraó e-ele-saiu de-a-frente-de Faraó');
INSERT INTO verses VALUES (1432, 1, 47, 11, '[וַיּוֹשֵׁ֣ב] [יוֹסֵף֮] a [וְאֶת־אֶחָיו֒] E-colocou a-eles E-deu para-eles [מִצְרַ֔יִם] em-terra-de a-terra [בְּאֶ֣רֶץ] a-terra em-terra-de [צִוָּ֥ה] conforme');
INSERT INTO verses VALUES (1433, 1, 47, 12, '[וַיְכַלְכֵּ֤ל] José a [וְאֶת־אֶחָ֔יו] e-[OBJ] seus-irmãos seu-pai pão casa pai-seu');
INSERT INTO verses VALUES (1434, 1, 47, 13, '[וְלֶ֤חֶם] [אֵין֙] em-todo a-terra porque muito a-fome terra [מִצְרַ֙יִם֙] terra Mitzrayim de-diante-de Canaã de-face-de [sem-traducao]');
INSERT INTO verses VALUES (1435, 1, 47, 14, '[וַיְלַקֵּ֣ט] José a todo a-prata [וּבְאֶ֣רֶץ] em-terra-de Mitzrayim [אֲשֶׁר־הֵ֣ם] Canaã e-trouxe que eles [בֵּ֥יתָה] E-veio José a E-disse casa-seu Faraó');
INSERT INTO verses VALUES (1436, 1, 47, 15, '[וַיִּתֹּ֣ם] הכסף da-terra Egito e-de-terra [כְּנַעַן֒] e-ele-chegou todo em-o-Egito dizendo [הָֽבָה־לָּ֣נוּ] pão dá para-nós Belém que [אָפֵ֖ס] opposite-you- porque [sem-traducao] כַּסֶּפֶת׃');
INSERT INTO verses VALUES (1437, 1, 47, 16, 'E-disse José dai [מִקְנֵיכֶ֔ם] [וְאֶתְּנָ֥ה] a-vós [בְּמִקְנֵיכֶ֑ם] se [כָּֽסֶף]');
INSERT INTO verses VALUES (1438, 1, 47, 17, 'e-trouxeram a [אֶל־יוֹסֵף֒] E-colocou a-eles E-deu pão [בַּסּוּסִ֗ים] pao [הַצֹּ֛אן] [וּבְמִקְנֵ֥ה] o-rebanho [וּבַחֲמֹרִ֑ים] o-bovino [בַּלֶּ֙חֶם֙] [בְּכָל־מִקְנֵהֶ֔ם] por-pão aquela [sem-traducao] aquela aquela');
INSERT INTO verses VALUES (1439, 1, 47, 18, '[וַתִּתֹּם֮] o-ano aquela וַיָּבֹ֨אוּ a-ele em-a-ano a-segunda e-disseram a-ele não [מֵֽאֲדֹנִ֔י] que porque se [וּמִקְנֵ֥ה] os-animais [אֶל־אֲדֹנִ֑י] não a Adonai não [בִּלְתִּ֥י] diante-de Adonai para-não se [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1440, 1, 47, 19, 'por-que [נָמ֣וּת] [לְעֵינֶ֗יךָ] também também também [קְנֵֽה־אֹתָ֥נוּ] quneh- [בַּלָּ֑חֶם] e-a [אֲנַ֤חְנוּ] [וְאַדְמָתֵ֙נוּ֙] [עֲבָדִ֣ים] nós [וְתֶן־זֶ֗רַע] avádim para-Faraó e-tenha semente não e-não [sem-traducao] [sem-traducao] não [sem-traducao]');
INSERT INTO verses VALUES (1441, 1, 47, 20, 'וַיִּ֨קֶן José a todo terra-de Egito para-Faraó porque [שָׂדֵ֔הוּ] Egito homem [הָרָעָ֑ב] porque a-terra [לְפַרְעֹֽה] הָרַעֲבָ e-foi a-terra a-Faraó');
INSERT INTO verses VALUES (1442, 1, 47, 21, 'e- o-povo ele ele [מִקְצֵ֥ה] mi-qtze [וְעַד־קָצֵֽהוּ] Egito e-até [sem-traducao]');
INSERT INTO verses VALUES (1443, 1, 47, 22, 'somente solo-de os-sacerdotes não [קָנָ֑ה] que [חֹ֨ק] [לַכֹּהֲנִ֜ים] de-junto-de פַּרְעֹה [וְאָֽכְל֤וּ] a [אֲשֶׁ֨ר] dar a-eles para-eles Faraó não [מָכְר֖וּ] não [sem-traducao] a אַדְמָתָֽם׃');
INSERT INTO verses VALUES (1444, 1, 47, 23, 'E-disse José a eis [קָנִ֨יתִי] [אֶתְכֶ֥ם] o-dia o-dia e-[OBJ] [הֵֽא־לָכֶ֣ם] semente [וּזְרַעְתֶּ֖ם] para-vós a');
INSERT INTO verses VALUES (1445, 1, 47, 24, 'e-será [בַּתְּבוּאֹ֔ת] e-dareis [חֲמִישִׁ֖ית] para-o-Faraó e-quatro [הַיָּדֹ֡ת] será a-vós [לְזֶ֨רַע] [הַשָּׂדֶ֧ה] [וּֽלְאָכְלְכֶ֛ם] [וְלַאֲשֶׁ֥ר] [בְּבָתֵּיכֶ֖ם] [וְלֶאֱכֹ֥ל] [לְטַפְּכֶֽם]');
INSERT INTO verses VALUES (1446, 1, 47, 25, 'e-disseram [הֶחֱיִתָ֑נוּ] foi-encontrado- graça em-olhos-de Adonai e-nos-seremos servos a-Faraó');
INSERT INTO verses VALUES (1447, 1, 47, 26, 'e-colocou aquela [יוֹסֵ֡ף] [לְחֹק֩] até o dia o-este sobre solo-de Egito [רַ֞ק] [אַדְמַ֤ת] apenas terra-de não era não era a-Faraó');
INSERT INTO verses VALUES (1448, 1, 47, 27, 'e-habitou Israel em-terra-de Egito em-terra-de [גֹּ֑שֶׁן] [וַיֵּאָחֲז֣וּ] nela [וַיִּפְר֥וּ] [וַיִּרְבּ֖וּ] muito');
INSERT INTO verses VALUES (1449, 1, 47, 28, '[וַיְחִ֤י] Jacó em-terra-de Egito sete dez ano e-houve dias-de Jacó segundo vidas-dele sete dois e-quarenta e-cem');
INSERT INTO verses VALUES (1450, 1, 47, 29, '[וַיִּקְרְב֣וּ] dias-de Israel E-chamou [׀] [לִבְנ֣וֹ] [לְיוֹסֵ֗ף] E-disse a-ele se por-favor encontrei graça em-tua-olho põe- debaixo tua-mao em-lugar-de comigo e-farás comigo bondade [תִקְבְּרֵ֖נִי] a agora [sem-traducao] em-Egito');
INSERT INTO verses VALUES (1451, 1, 47, 30, '[וְשָֽׁכַבְתִּי֙] com [וּנְשָׂאתַ֙נִי֙] [מִמִּצְרַ֔יִם] do-Egito [בִּקְבֻרָתָ֑ם] [וַיֹּאמַ֕ר] eu eu fazerei [sem-traducao]');
INSERT INTO verses VALUES (1452, 1, 47, 31, 'E-disse [הִשָּֽׁבְעָה֙] a-mim e-ele-jurou a-ele e-prostrou-se Israel sobre cabeça o-leito');
INSERT INTO chapters VALUES (48, 1, 48, 22);
INSERT INTO verses VALUES (1453, 1, 48, 1, 'e-houve depois-de as-palavras os-estes E-disse [לְיוֹסֵ֔ף] eis teu-pai [חֹלֶ֑ה] E-tomou a segundo seus-filhos com-ele a ménashé e-a Efrayim');
INSERT INTO verses VALUES (1454, 1, 48, 2, 'e-anunciou a-Jacó E-disse eis em-o-seu-filho José veio a-ti [וַיִּתְחַזֵּק֙] Israel e-habitou sobre o-leito');
INSERT INTO verses VALUES (1455, 1, 48, 3, 'E-disse Jacó a José El Shaddai [בְּל֖וּז] a-mim [כְּנָ֑עַן] E-abençoou assim E-abençoou de-mim');
INSERT INTO verses VALUES (1456, 1, 48, 4, 'E-disse a-mim eis-me [מַפְרְךָ֙] [וְהִרְבִּיתִ֔ךָ] e-eu-te-darei [לִקְהַ֣ל] עַמִּ֑ים [וְנָ֨תַתִּ֜י] a a-terra esta [אַחֲרֶ֖יךָ] depois de ti eternidade eternidade');
INSERT INTO verses VALUES (1457, 1, 48, 5, 'e-agora dois [הַנּוֹלָדִ֨ים] a-ti a ti na-terra Egito até venha a-ti [אֶפְרַ֙יִם֙] para-mim- eles Efraim e Manassés- [sem-traducao] [sem-traducao] serao a-mim');
INSERT INTO verses VALUES (1458, 1, 48, 6, '[וּמוֹלַדְתְּךָ֛] que [אַחֲרֵיהֶ֖ם] a-ti a-ti sobre sobre nome [יִקָּרְא֖וּ] seriam chamados [sem-traducao]');
INSERT INTO verses VALUES (1459, 1, 48, 7, 'וַאֲנִ֣י ׀ [׀] [בְּבֹאִ֣י] [מִפַּדָּ֗ן] [מֵ֩תָה֩] [עָלַ֨י] em-a-terra [בְּאֶ֤רֶץ] em-a-caminho [בַּדֶּ֔רֶךְ] como-um terra [לָבֹ֣א] Efrata [וָאֶקְבְּרֶ֤הָ] nome no-caminho [אֶפְרָ֔ת] ela casa pão');
INSERT INTO verses VALUES (1460, 1, 48, 8, 'E-viu Israel a filhos-de E-disse E-disse');
INSERT INTO verses VALUES (1461, 1, 48, 9, 'E-disse José a pai-dele eles eles que deu para-mim Elohim neste E-disse [sem-traducao] agora para-mim [sem-traducao]');
INSERT INTO verses VALUES (1462, 1, 48, 10, '[וְעֵינֵ֤י] Israel [כָּבְד֣וּ] [מִזֹּ֔קֶן] não podia para-ver [וַיַּגֵּ֤שׁ] eles a-ele [וַיִּשַּׁ֥ק] a-eles [וַיְחַבֵּ֥ק] a-eles');
INSERT INTO verses VALUES (1463, 1, 48, 11, 'E-disse Israel a José viu não não [וְהִנֵּ֨ה] e-eis a-rea de-mim-me também também a semente-tua');
INSERT INTO verses VALUES (1464, 1, 48, 12, 'e-ele-saiu José eles de-com [בִּרְכָּ֑יו] e-prostrou-se [לְאַפָּ֖יו] para-terra');
INSERT INTO verses VALUES (1465, 1, 48, 13, 'E-tomou [יוֹסֵף֮] a [אֶת־אֶפְרַ֤יִם] a [מִשְּׂמֹ֣אל] [יִשְׂרָאֵ֔ל] [וְאֶת־מְנַשֶּׁ֥ה] Israel e-[OBJ] Manassés [וַיַּגֵּ֖שׁ] a-ele Israel');
INSERT INTO verses VALUES (1466, 1, 48, 14, 'e-enviou Israel a [וַיָּ֨שֶׁת] [עַל־רֹ֤אשׁ] sobre cabeça אֶפְרַיִם e-ele [עַל־רֹ֣אשׁ] e-[OBJ] [שִׂכֵּל֙] sobre que Manassés [הַבְּכֽוֹר] a porque');
INSERT INTO verses VALUES (1467, 1, 48, 15, 'E-abençoou a José E-disse [אֲשֶׁר֩] que [אֲבֹתַ֤י] [לְפָנָיו֙] diante-dele Abraão [הָֽאֱלֹהִים֙] הָֽאֱלֹהִים [אֹתִ֔י] a-mim [עַד־הַיּ֥וֹם] até o-dia a-esta');
INSERT INTO verses VALUES (1468, 1, 48, 16, '[הַמַּלְאָךְ֩] [הַגֹּאֵ֨ל] a-mim de-todo mau [אֶת־הַנְּעָרִים֒] a [בָהֶם֙] E-chamou [וְשֵׁ֥ם] [אֲבֹתַ֖י] e-nome-de pais-meus Abraão [לָרֹ֖ב] [בְּקֶ֥רֶב] a-terra a-terra');
INSERT INTO verses VALUES (1469, 1, 48, 17, 'E-viu José porque seu-pai [יַד־יְמִינ֛וֹ] mão-de [אֶפְרַ֖יִם] sobre cabeça Efraim [יַד־אָבִ֗יו] em-olhos-dele [אֹתָ֛הּ] de-cima-de pai-de-ele [עַל־רֹ֥אשׁ] ela de-sobre cume-de Efraim sobre cabeça [sem-traducao]');
INSERT INTO verses VALUES (1470, 1, 48, 18, 'E-disse José a pai-dele não assim pai-meu porque este [עַל־רֹאשֽׁוֹ] sobre');
INSERT INTO verses VALUES (1471, 1, 48, 19, 'e-recusou seu-pai E-disse [יָדַ֤עְתִּֽי] filhos-de soube também ele sera [יִגְדָּ֑ל] e-também ele o-pequeno [יִגְדַּ֣ל] nós [וְזַרְע֖וֹ] será [מְלֹֽא־הַגּוֹיִֽם] [sem-traducao] será [sem-traducao] os-gentios');
INSERT INTO verses VALUES (1472, 1, 48, 20, '[וַיְבָ֨רֲכֵ֜ם] no-dia [הַהוּא֮] [לֵאמוֹר֒] [בְּךָ֗] [יְבָרֵ֤ךְ] Israel dizendo [יְשִֽׂמְךָ֣] Elohim [כְּאֶפְרַ֖יִם] [וְכִמְנַשֶּׁ֑ה] [וַיָּ֥שֶׂם] a Efraim diante-de');
INSERT INTO verses VALUES (1473, 1, 48, 21, 'E-disse Israel a eis eu eu morreu e-era Elohim [וְהֵשִׁ֣יב] [אֶתְכֶ֔ם] vos a terra [sem-traducao]');
INSERT INTO verses VALUES (1474, 1, 48, 22, '[וַאֲנִ֞י] dei a-ti [שְׁכֶ֥ם] um sobre [אֲשֶׁ֤ר] que [מִיַּ֣ד] da-mão-de [בְּחַרְבִּ֖י] [וּבְקַשְׁתִּֽי׃]');
INSERT INTO chapters VALUES (49, 1, 49, 33);
INSERT INTO verses VALUES (1475, 1, 49, 1, 'E-chamou Jacó a E-disse E-disse [וְאַגִּ֣ידָה] a-vós a-vós a que [בְּאַחֲרִ֥ית] vos');
INSERT INTO verses VALUES (1476, 1, 49, 2, '[הִקָּבְצ֥וּ] [וְשִׁמְע֖וּ] filhos-de Jacó [וְשִׁמְע֖וּ] a Israel');
INSERT INTO verses VALUES (1477, 1, 49, 3, '[רְאוּבֵן֙] [בְּכֹ֣רִי] tu [כֹּחִ֖י] [וְרֵאשִׁ֣ית] [אוֹנִ֑י] [יֶ֥תֶר] [שְׂאֵ֖ת] [וְיֶ֥תֶר] [עָֽז]');
INSERT INTO verses VALUES (1478, 1, 49, 4, '[פַּ֤חַז] [כַּמַּ֙יִם֙] a que porque [מִשְׁכְּבֵ֣י] [אָבִ֑יךָ] pai-teu entao [יְצוּעִ֥י] subir [sem-traducao]');
INSERT INTO verses VALUES (1479, 1, 49, 5, '[שִׁמְע֥וֹן] [וְלֵוִ֖י] [אַחִ֑ים] instrumentos-de violência [מְכֵרֹתֵיהֶֽם]');
INSERT INTO verses VALUES (1480, 1, 49, 6, '[בְּסֹדָם֙] a [נַפְשִׁ֔י] [בִּקְהָלָ֖ם] [אַל־תֵּחַ֣ד] a que [בְאַפָּם֙] porque [אִ֔ישׁ] [וּבִרְצֹנָ֖ם] homem');
INSERT INTO verses VALUES (1481, 1, 49, 7, 'maldito [אַפָּם֙] que [עָ֔ז] [וְעֶבְרָתָ֖ם] que [קָשָׁ֑תָה] [אֲחַלְּקֵ֣ם] [בְּיַעֲקֹ֔ב] [וַאֲפִיצֵ֖ם] em-Israel');
INSERT INTO verses VALUES (1482, 1, 49, 8, 'Judá tu [יוֹד֣וּךָ] [אַחֶ֔יךָ] tua-mao [בְּעֹ֣רֶף] [אֹיְבֶ֑יךָ] [יִשְׁתַּחֲוּ֥וּ] a-ti filhos-de pai-teu');
INSERT INTO verses VALUES (1483, 1, 49, 9, '[גּ֤וּר] [אַרְיֵה֙] Judá [מִטֶּ֖רֶף] filhos-de [עָלִ֑יתָ] [כָּרַ֨ע] [רָבַ֧ץ] [כְּאַרְיֵ֛ה] [וּכְלָבִ֖יא] quem [יְקִימֶֽנּוּ]');
INSERT INTO verses VALUES (1484, 1, 49, 10, 'não ele se desviará [מִֽיהוּדָ֔ה] [וּמְחֹקֵ֖ק] [מִבֵּ֣ין] [רַגְלָ֑יו] até até porque vira [וְל֖וֹ] [יִקְּהַ֥ת] [עַמִּֽים]');
INSERT INTO verses VALUES (1485, 1, 49, 11, '[אֹסְרִ֤י] [לַגֶּ֙פֶן֙] [*עירה] filhos-de [וְלַשֹּׂרֵקָ֖ה] [בְּנִ֣י] [אֲתֹנ֑וֹ] [כִּבֵּ֤ס] [בַּיַּ֙יִן֙] [לְבֻשׁ֔וֹ]');
INSERT INTO verses VALUES (1486, 1, 49, 12, '[חַכְלִילִ֥י] [עֵינַ֖יִם] [מִיָּ֑יִן] [וּלְבֶן־שִׁנַּ֖יִם] dois');
INSERT INTO verses VALUES (1487, 1, 49, 13, '[זְבוּלֻ֕ן] [לְח֥וֹף] mares [יִשְׁכֹּ֑ן] e-ele [לְח֣וֹף] [אֳנִיּ֔וֹת] [וְיַרְכָת֖וֹ] sobre');
INSERT INTO verses VALUES (1488, 1, 49, 14, '[יִשָּׂשכָ֖ר] [חֲמֹ֣ר] [גָּ֑רֶם] [רֹבֵ֖ץ] entre [הַֽמִּשְׁפְּתָֽיִם]');
INSERT INTO verses VALUES (1489, 1, 49, 15, 'E-viu [מְנֻחָה֙] que bom e-[OBJ] que porque [וַיֵּ֤ט] [שִׁכְמוֹ֙] [לִסְבֹּ֔ל] e-houve E-foi servo');
INSERT INTO verses VALUES (1490, 1, 49, 16, '[דָּ֖ן] ele-julgará povo-seu como-um-de tribos-de Israel');
INSERT INTO verses VALUES (1491, 1, 49, 17, '[יְהִי־דָן֙] [נָחָ֣שׁ] [עֲלֵי־דֶ֔רֶךְ] sobre caminho [הַנֹּשֵׁךְ֙] sobre [וַיִּפֹּ֥ל] [רֹכְב֖וֹ] [אָחֽוֹר]');
INSERT INTO verses VALUES (1492, 1, 49, 18, '[לִֽישׁוּעָתְךָ֖] [קִוִּ֥יתִי] yhwh');
INSERT INTO verses VALUES (1493, 1, 49, 19, '[גָּ֖ד] [גְּד֣וּד] [יְגוּדֶ֑נּוּ] [וְה֖וּא] [יָגֻ֥ד] calcanhar');
INSERT INTO verses VALUES (1494, 1, 49, 20, '[מֵאָשֵׁ֖ר] oito [לַחְמ֑וֹ] e-ele [יִתֵּ֖ן] [מַֽעֲדַנֵּי־מֶֽלֶךְ׃] rei');
INSERT INTO verses VALUES (1495, 1, 49, 21, 'Naftali [אַיָּלָ֣ה] [שְׁלֻחָ֑ה] [הַנֹּתֵ֖ן] palavras-de [sem-traducao]');
INSERT INTO verses VALUES (1496, 1, 49, 22, 'filho [פֹּרָת֙] José filho [פֹּרָ֖ת] sobre olho [צָעֲדָ֖ה] [עֲלֵי־שֽׁוּר]');
INSERT INTO verses VALUES (1497, 1, 49, 23, '[וַֽיְמָרֲרֻ֖הוּ] [וָרֹ֑בּוּ] [וַֽיִּשְׂטְמֻ֖הוּ] [בַּעֲלֵ֥י] [חִצִּֽים]');
INSERT INTO verses VALUES (1498, 1, 49, 24, 'e-habitou [בְּאֵיתָן֙] [קַשְׁתּ֔וֹ] [וַיָּפֹ֖זּוּ] [זְרֹעֵ֣י] suas-maos [מִידֵי֙] [אֲבִ֣יר] Jacó [מִשָּׁ֥ם] [רֹעֶ֖ה] pedra Israel');
INSERT INTO verses VALUES (1499, 1, 49, 25, '[מֵאֵ֨ל] teu-pai [וְיַעְזְרֶ֗ךָּ] e-[OBJ] Shaddai [וִיבָ֣רְכֶ֔ךָּ] [בִּרְכֹ֤ת] céus [מֵעָ֔ל] [בִּרְכֹ֥ת] [תְּה֖וֹם] [רֹבֶ֣צֶת] [תָּ֑חַת] [בִּרְכֹ֥ת] [שָׁדַ֖יִם] [וָרָֽחַם]');
INSERT INTO verses VALUES (1500, 1, 49, 26, '[בִּרְכֹ֣ת] pai-de-ti [גָּֽבְרוּ֙] sobre [הוֹרַ֔י] [עַֽד־תַּאֲוַ֖ת] até eternidade [תִּֽהְיֶ֙ין֙] eternidade [יוֹסֵ֔ף] para-cabeca José [אֶחָֽיו׃] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1501, 1, 49, 27, '[בִּנְיָמִין֙] [זְאֵ֣ב] [יִטְרָ֔ף] [בַּבֹּ֖קֶר] [יֹ֣אכַל] até [וְלָעֶ֖רֶב] [יְחַלֵּ֥ק] [שָׁלָֽל]');
INSERT INTO verses VALUES (1502, 1, 49, 28, 'todo estes tribos-de Israel dois dez [אֲשֶׁר־דִּבֶּ֨ר] a-eles palavra E-abençoou [אוֹתָ֔ם] E-abençoou a-eles homem que eles abençoou');
INSERT INTO verses VALUES (1503, 1, 49, 29, 'E-ordenou [אוֹתָ֗ם] E-disse para-eles eu [נֶאֱסָ֣ף] a povo-meu [אֹתִ֖י] a-mim a [אֲשֶׁ֥ר] a [עֶפְר֥וֹן] que [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (1504, 1, 49, 30, '[בַּמְּעָרָ֞ה] que [בִּשְׂדֵ֧ה] [הַמַּכְפֵּלָ֛ה] que sobre face-de [כְּנָ֑עַן] em-terra-de assim que [אֶת־הַשָּׂדֶ֗ה] Abraão a o-campo de-junto-de [sem-traducao] [sem-traducao] La-achuzat- Qever');
INSERT INTO verses VALUES (1505, 1, 49, 31, '[שָׁ֣מָּה] [קֽ͏ָבְר֞וּ] a e-[OBJ] e-[OBJ] [אִשְׁתּ֔וֹ] mulher-dele [קָבְר֣וּ] [אֶת־יִצְחָ֔ק] e-[OBJ] Isaque e-[OBJ] [וְשָׁ֥מָּה] mulher-sua [אֶת־לֵאָֽה] a');
INSERT INTO verses VALUES (1506, 1, 49, 32, '[מִקְנֵ֧ה] [הַשָּׂדֶ֛ה] [וְהַמְּעָרָ֥ה] que nele de-com filhos-de Hete');
INSERT INTO verses VALUES (1507, 1, 49, 33, 'E-terminou Jacó [לְצַוֺּ֣ת] a [וַיֶּאֱסֹ֥ף] [רַגְלָ֖יו] [אֶל־הַמִּטָּ֑ה] a [וַיֵּאָ֥סֶף] [אֶל־עַמָּֽיו] a');
INSERT INTO chapters VALUES (50, 1, 50, 26);
INSERT INTO verses VALUES (1508, 1, 50, 1, '[וַיִפֹּ֥ל] [יוֹסֵ֖ף] sobre seu-pai seu-pai [עָלָ֖יו] sobre-ele e-beijou- a-ele');
INSERT INTO verses VALUES (1509, 1, 50, 2, 'E-ordenou [יוֹסֵ֤ף] a seus-servos a [אֶת־אָבִ֑יו] [וַיַּחַנְט֥וּ] a seu-pai [sem-traducao] [sem-traducao] a Israel');
INSERT INTO verses VALUES (1510, 1, 50, 3, '[וַיִּמְלְאוּ־לוֹ֙] a-ele dia que porque assim dias-de dias-de [וַיִּבְכּ֥וּ] ele a-ele Egito dia dia');
INSERT INTO verses VALUES (1511, 1, 50, 4, '[וַיַּֽעַבְרוּ֙] dias-de [בְכִית֔וֹ] e-falou José a casa dizendo dizendo se por-favor encontrei graça [בְּאָזְנֵ֥י] [פַרְעֹ֖ה] dizendo yhwh dizendo para-dizer');
INSERT INTO verses VALUES (1512, 1, 50, 5, '[אָבִ֞י] [הִשְׁבִּיעַ֣נִי] dizendo eis eu morreu [בְּקִבְרִ֗י] que [כָּרִ֤יתִי] a-mim em-terra-de Canaã para lá [תִּקְבְּרֵ֑נִי] e-agora [אֶֽעֱלֶה־נָּ֛א] [וְאֶקְבְּרָ֥ה] [אֶת־אָבִ֖י] a');
INSERT INTO verses VALUES (1513, 1, 50, 6, 'E-disse Faraó folhas-de [וּקְבֹ֥ר] a teu-pai como-que [sem-traducao]');
INSERT INTO verses VALUES (1514, 1, 50, 7, 'e-ofereceu José [לִקְבֹּ֣ר] a pai-seu [אִתּ֜וֹ] [כָּל־עַבְדֵ֤י] todo servos-de [בֵית֔וֹ] e-tudo [זִקְנֵ֥י] e-todo anciãos-de terra-de Egito');
INSERT INTO verses VALUES (1515, 1, 50, 8, 'e-tudo casa José e-seus-irmãos e-Beit seu-pai somente [טַפָּם֙] [וְצֹאנָ֣ם] [וּבְקָרָ֔ם] [עָזְב֖וּ] em-terra-de [גֹּֽשֶׁן]');
INSERT INTO verses VALUES (1516, 1, 50, 9, 'e-subiu com-ele também [גַּם־פָּרָשִׁ֑ים] e-houve cavaleiros E-foi muito');
INSERT INTO verses VALUES (1517, 1, 50, 10, 'e-vieram até [הָאָטָ֗ד] [אֲשֶׁר֙] que em-além-de o-Jordão [מִסְפֵּ֛ד] nome [וְכָבֵ֖ד] muito [וַיַּ֧עַשׂ] muito E-fez [שִׁבְעַ֥ת] [יָמִֽים]');
INSERT INTO verses VALUES (1518, 1, 50, 11, 'E-viu [יוֹשֵׁב֩] a-terra [הַֽכְּנַעֲנִ֜י] a [בְּגֹ֙רֶן֙] [הָֽאָטָ֔ד] [וַיֹּ֣אמְר֔וּ] e-disseram [זֶ֖ה] [לְמִצְרָ֑יִם] este chamou sobre [אָבֵ֣ל] chamou nome-dela Abel Egito que em-além-de o-Jordão');
INSERT INTO verses VALUES (1519, 1, 50, 12, 'e-fizeram filhos-dele a-ele assim como-que [צִוָּֽם]');
INSERT INTO verses VALUES (1520, 1, 50, 13, '[וַיִּשְׂא֨וּ] ele [בָנָיו֙] terra-para Canaã [וַיִּקְבְּר֣וּ] ele [בִּמְעָרַ֖ת] [שְׂדֵ֣ה] [הַמַּכְפֵּלָ֑ה] que [קָנָה֩] Abraão a [לַאֲחֻזַּת־קֶ֗בֶר] [מֵאֵ֛ת] [עֶפְרֹ֥ן] de-junto-de [עַל־פְּנֵ֥י] [מַמְרֵֽא] sobre face-de [sem-traducao]');
INSERT INTO verses VALUES (1521, 1, 50, 14, '[וַיָּ֨שָׁב] [יוֹסֵ֤ף] [מִצְרַ֙יְמָה֙] ele e-irmãos-de-o e-todo [אִתּ֖וֹ] com-ele [אֶת־אָבִ֑יו] a seu-pai depois-de [sem-traducao] a seu-pai');
INSERT INTO verses VALUES (1522, 1, 50, 15, '[וַיִּרְא֤וּ] [אֲחֵֽי־יוֹסֵף֙] [כִּי־מֵ֣ת] porque morreu [ל֥וּ] e-disseram [יוֹסֵ֑ף] [וְהָשֵׁ֤ב] José [לָ֔נוּ] [OBJ] [כָּל־הָ֣רָעָ֔ה] a todo ele que');
INSERT INTO verses VALUES (1523, 1, 50, 16, '[וַיְצַוּ֕וּ] a dizendo dizendo [צִוָּ֔ה] [לִפְנֵ֥י] diante-de dizendo');
INSERT INTO verses VALUES (1524, 1, 50, 17, 'assim [לְיוֹסֵ֗ף] [אָ֣נָּ֡א] [שָׂ֣א] [נָ֠א] [פֶּ֣שַׁע] [אַחֶ֤יךָ] [וְחַטָּאתָם֙] [כִּי־רָעָ֣ה] porque e-agora [שָׂ֣א] [נָ֔א] [לְפֶ֥שַׁע] por-favor [Elohim] [אָבִ֑יךָ] Elohim-de teu-pai [בְּדַבְּרָ֥ם] a-ele [sem-traducao] a-ele');
INSERT INTO verses VALUES (1525, 1, 50, 18, 'e-foram também seus-irmãos [לְפָנָ֑יו] diante-dele e-disseram a-ti a-ti');
INSERT INTO verses VALUES (1526, 1, 50, 19, 'E-disse [אֲלֵהֶ֛ם] José a que porque acaso-debaixo Elohim');
INSERT INTO verses VALUES (1527, 1, 50, 20, '[וְאַתֶּ֕ם] [חֲשַׁבְתֶּ֥ם] sobre-mim maldade Elohim [חֲשָׁבָ֣הּ] [לְטֹבָ֔ה] para-que fez como-o-dia este [לְהַחֲיֹ֥ת] com muito');
INSERT INTO verses VALUES (1528, 1, 50, 21, 'e-agora a eu eu [אֶתְכֶ֖ם] vos e-[OBJ] [אוֹתָ֔ם] [וַיְדַבֵּ֖ר] a-eles sobre');
INSERT INTO verses VALUES (1529, 1, 50, 22, 'e-habitou José em-Egito ele e-Beit seu-pai e-viveu José cem e-dez dois');
INSERT INTO verses VALUES (1530, 1, 50, 23, 'E-viu José para-Efraim filhos-de [שִׁלֵּשִׁ֑ים] também filhos-de Maquir filho-de Manassés [עַל־בִּרְכֵּ֥י] sobre [sem-traducao] José');
INSERT INTO verses VALUES (1531, 1, 50, 24, 'E-disse José a eu eu morreu [פָּקֹ֧ד] [יִפְקֹ֣ד] [אֶתְכֶ֗ם] a-vos [אֶתְכֶם֙] vos de a-terra a-esta a a-terra que [וּֽלְיַעֲקֹֽב] le-abraham para-Isaque [sem-traducao]');
INSERT INTO verses VALUES (1532, 1, 50, 25, '[וַיַּשְׁבַּ֣ע] José a filhos-de dizendo dizendo [יִפְקֹ֤ד] visitara Elohim vos [אֶת־עַצְמֹתַ֖י] a');
INSERT INTO verses VALUES (1533, 1, 50, 26, 'E-morreu José filho-de cem e-dez dois ele a-ele [בָּאָר֖וֹן] [בְּמִצְרָֽיִם]');
INSERT INTO books VALUES (2, 'EXO', 'Êxodo', 'AT', 40);
INSERT INTO chapters VALUES (51, 2, 1, 22);
INSERT INTO verses VALUES (1534, 2, 1, 1, 'e-estes nomes-de filhos-de Israel os-vindos Egito-para com Jacó homem e-casa-sua vieram');
INSERT INTO verses VALUES (1535, 2, 1, 2, 'Reuben Simeão Levi e-Judá');
INSERT INTO verses VALUES (1536, 2, 1, 3, 'Issacar Zebulom e-Benjamim');
INSERT INTO verses VALUES (1537, 2, 1, 4, 'Dã e-Naftali Gade e-Aser');
INSERT INTO verses VALUES (1538, 2, 1, 5, 'e-foi todo alma saídos-de coxa-de Jacó setenta ser e-José foi em-Egito');
INSERT INTO verses VALUES (1539, 2, 1, 6, 'E-morreu José e-todo e-tudo e-todo a-geração a-aquela');
INSERT INTO verses VALUES (1540, 2, 1, 7, 'e-filhos-de Israel frutificaram e-pulularam e-multiplicaram e-multiplicaram-se em-muito muito e-encheu-se a-terra eles');
INSERT INTO verses VALUES (1541, 2, 1, 8, 'E-levantou rei-de novo sobre Egito que não conheceu a José');
INSERT INTO verses VALUES (1542, 2, 1, 9, 'E-disse a eis eis povo filhos-de Israel muito nós de-nós');
INSERT INTO verses VALUES (1543, 2, 1, 10, 'vamos sejamos-sábios a-ele para-que-não multiplique e-será porque aconteçam guerra e-juntar-se-á também ele sobre inimigos-nossos e-lutará contra-nós e-subirá de a-terra');
INSERT INTO verses VALUES (1544, 2, 1, 11, 'e-puseram sobre-ele príncipes-de tributos para afligir-o com-cargas-suas E-edificou cidades-de provisões para-Faraó a Pitom e-a Ramessés');
INSERT INTO verses VALUES (1545, 2, 1, 12, 'e-como afligiam ele assim multiplicava e-assim espalhava-se e-aborreceram-se de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (1546, 2, 1, 13, 'e-fizeram-servir Egito a filhos-de Israel com-dureza');
INSERT INTO verses VALUES (1547, 2, 1, 14, 'e-amarguraram a vidas-suas com-serviço duro com-argamassa e-com-tijolos e-em-todo serviço no-campo את todo serviço-deles que serviram neles com-dureza');
INSERT INTO verses VALUES (1548, 2, 1, 15, 'E-disse rei Egito às-parteiras as-hebreias que nome a-uma Sifrá e-nome-de a-segunda Puá');
INSERT INTO verses VALUES (1549, 2, 1, 16, 'E-disse quando-ajudardes-no-parto a as-hebreias e-verdes sobre ele se ele ele e-matareis a-ele e-se filha ela e-viverá');
INSERT INTO verses VALUES (1550, 2, 1, 17, 'e-temeram as-parteiras a Elohim e-não fizeram como palavra a-elas rei Egito e-fizeram-viver a os-meninos');
INSERT INTO verses VALUES (1551, 2, 1, 18, 'E-chamou rei-de Mitzrayim E-disse E-disse a-elas por-que fizestes a-coisa esta e-fizeram-viver a os-meninos');
INSERT INTO verses VALUES (1552, 2, 1, 19, 'e-disseram as-parteiras a que não não como-as-mulheres as-egípcias as-hebreias porque vivazes elas antes-de vir a-elas a-parteira e-dão-à-luz');
INSERT INTO verses VALUES (1553, 2, 1, 20, 'e-fez-bem Elohim às-parteiras e-multiplicou o-povo e-multiplicaram-se muito');
INSERT INTO verses VALUES (1554, 2, 1, 21, 'e-houve porque temeram as-parteiras a a-eles E-fez a-eles casas');
INSERT INTO verses VALUES (1555, 2, 1, 22, 'E-ordenou Faraó para-todo dizendo para-dizer todo o-filho o-nascido ao-rio lançareis-o e-todo a-filha fareis-viver');
INSERT INTO chapters VALUES (52, 2, 2, 25);
INSERT INTO verses VALUES (1556, 2, 2, 1, 'E-andou homem de-casa-de Levi E-tomou a filha-de Levi');
INSERT INTO verses VALUES (1557, 2, 2, 2, 'e-concebeu a-mulher e-deu-à-luz filho E-viu ele porque ele ele e-escondeu-o três meses');
INSERT INTO verses VALUES (1558, 2, 2, 3, 'e-não pôde mais escondê-lo e-tomou para-ele arca-de junco e-betumou-a com-betume e-com-pez e-pôs nela a o-menino e-pôs no-junco sobre beira-de o-rio');
INSERT INTO verses VALUES (1559, 2, 2, 4, 'e-pôs-se irmã-dele de-longe para-saber que- a-ele a-ele');
INSERT INTO verses VALUES (1560, 2, 2, 5, 'e-desceu filha-de Faraó para-lavar-se sobre o-rio e-donzelas-dela caminhando E-viu mão no-meio-de e-viu a a-arca em-meio-de o-junco e-enviou a serva-dela e-tomou-a');
INSERT INTO verses VALUES (1561, 2, 2, 6, 'e-abriu e-viu-o a o-menino e-eis- menino chorando E-disse sobre-ele e-disse de-meninos-de os-hebreus este');
INSERT INTO verses VALUES (1562, 2, 2, 7, 'E-disse irmã-dele a filha-de Faraó para-ti e-chamarei para-ti de ama-de-leite de para-ti e-amamentará para-ti a o-menino');
INSERT INTO verses VALUES (1563, 2, 2, 8, 'e-disse para-ela filha-de פַּרְעֹה vai e-foi a-donzela e-chamou a mãe o-menino');
INSERT INTO verses VALUES (1564, 2, 2, 9, 'E-disse para-ela filha-de פַּרְעֹה leva a o-menino o-este e-amamenta-o para-mim e-eu e-tomou a teu-salário e-tomou a-mulher o-menino e-amamentou-o');
INSERT INTO verses VALUES (1565, 2, 2, 10, 'e-cresceu o-menino e-trouxe-o para-filha-de Faraó e-foi para-ela para-filho e-chamou E-disse que e-disse porque de as-águas משה-o');
INSERT INTO verses VALUES (1566, 2, 2, 11, 'e-houve em-os-dias aqueles e-cresceu Moisés e-saiu a seus-irmãos E-viu com-cargas-suas E-viu homem egípcio golpeando homem hebreu de-seus-irmãos');
INSERT INTO verses VALUES (1567, 2, 2, 12, 'e-voltou-se aqui e-ali E-viu que não-há homem e-golpeou a o-egípcio e-escondeu-o na-areia');
INSERT INTO verses VALUES (1568, 2, 2, 13, 'e-saiu no-dia o-segundo e-eis dois homens hebreus E-disse E-disse ao-malvado por-que golpeias teu-companheiro');
INSERT INTO verses VALUES (1569, 2, 2, 14, 'E-disse quem te-pôs para-homem príncipe e-juiz sobre-nós para-matar-me tu disse como mataste a o-egípcio e-temeu Moisés E-disse certamente conhecido a-palavra');
INSERT INTO verses VALUES (1570, 2, 2, 15, 'E-ouviu Faraó a a-palavra este e-buscou para-matar a Moisés de-diante-de Moisés de-diante-de פַּרְעֹה e-habitou em-terra-de מִדְיָן e-habitou sobre o-poço');
INSERT INTO verses VALUES (1571, 2, 2, 16, 'e-para-sacerdote מִדְיָן sete filhas e-vieram e-tiraram e-encheram a os-bebedouros para-dar-de-beber rebanho seu-pai');
INSERT INTO verses VALUES (1572, 2, 2, 17, 'e-vieram os-pastores e-expulsaram-nas E-levantou Moisés e-salvou-as e-deu-de-beber a seu-rebanho');
INSERT INTO verses VALUES (1573, 2, 2, 18, 'e-vieram a רְעוּאֵל E-disse E-disse por-que apressastes o-dia o-dia');
INSERT INTO verses VALUES (1574, 2, 2, 19, 'e-disseram homem egípcio ele-livrou-nos da-mão-de os-pastores e-também tirando ela-tirou para-nós e-deu-de-beber a o-rebanho');
INSERT INTO verses VALUES (1575, 2, 2, 20, 'E-disse a filhas-dele e-onde-ele por-que isto vós-abandonastes a a-ele chamai para-ele e-ele-comerá pão');
INSERT INTO verses VALUES (1576, 2, 2, 21, 'e-ele-consentiu Moisés para-habitar a E-colocou E-deu a Zípora filha-dele para-Moisés');
INSERT INTO verses VALUES (1577, 2, 2, 22, 'e-deu-à-luz filho E-chamou a nome-de-ele que disse disse forasteiro eu-fui em-terra-de estranha');
INSERT INTO verses VALUES (1578, 2, 2, 23, 'e-houve em-os-dias do-muitos os-aqueles E-morreu rei Egito e-eles-gemeram filhos-de Israel de o-trabalho e-eles-clamaram e-ela-subiu clamor-deles a Elohim de o-trabalho');
INSERT INTO verses VALUES (1579, 2, 2, 24, 'E-ouviu Elohim a gemido-deles e-lembrou Elohim a aliança-dele a Abraão a Isaque e-com Jacó');
INSERT INTO verses VALUES (1580, 2, 2, 25, 'E-viu Elohim a filhos-de Israel e-soube Elohim');
INSERT INTO chapters VALUES (53, 2, 3, 22);
INSERT INTO verses VALUES (1581, 2, 3, 1, 'e-Moisés ser apascentando a rebanho-de Jetro sogro-dele sacerdote Midiã e-ele-conduziu a o-rebanho atrás-de o-deserto E-veio a monte-de Elohim Horebe');
INSERT INTO verses VALUES (1582, 2, 3, 2, 'E-viu anjo-de yhwh a-ele em-chama-de fogo de-meio-de E-viu E-viu e-eis a-sarça queimando no-fogo e-a-sarça não-ela consumida');
INSERT INTO verses VALUES (1583, 2, 3, 3, 'E-disse Moisés desviarei agora e-eu-verei o-grande a-visão a-grande este por-que não queima a-sarça');
INSERT INTO verses VALUES (1584, 2, 3, 4, 'E-viu yhwh que desviou para-ver E-chamou a-ele Elohim de-meio-de a-sarça E-disse Moisés Moisés E-disse eis-me');
INSERT INTO verses VALUES (1585, 2, 3, 5, 'E-disse a te-aproximes aqui de-cima-de sandálias-tuas que pés-teus porque tu que tu estando-em-pé ele terra-de santidade ela');
INSERT INTO verses VALUES (1586, 2, 3, 6, 'E-disse eu Elohim-de pai-teu Elohim-de Abraão Elohim-de Isaque e-Elohim-de Jacó e-ele-escondeu Moisés rosto-dele que temer de-olhar a Elohim');
INSERT INTO verses VALUES (1587, 2, 3, 7, 'E-disse yhwh viu vi a aflição-de povo-meu que em-Egito e-a de-diante-de ouvi que opressores-seus porque conheci a dores-suas');
INSERT INTO verses VALUES (1588, 2, 3, 8, 'e-desci para-livrar-o da-mão-de Egito e-para-fazer-subir-o de a-terra aquela a terra boa e-larga a terra fluindo-de leite e-mel a lugar-de o-cananeu e-o-heteu e-o-amorreu e-o-perizeu e-o-heveu e-o-jebuseu');
INSERT INTO verses VALUES (1589, 2, 3, 9, 'e-agora eis clamor-de filhos-de Israel veio a-mim e-também vi a a-opressão eles Egito oprimindo a-eles');
INSERT INTO verses VALUES (1590, 2, 3, 10, 'e-agora vai e-enviarei-te a Faraó e-faze-sair a povo-meu filhos-de Israel de-Egito');
INSERT INTO verses VALUES (1591, 2, 3, 11, 'E-disse Moisés a quem eu que porque irei a Faraó e-que farei-sair a filhos-de Israel de-Egito');
INSERT INTO verses VALUES (1592, 2, 3, 12, 'E-disse porque estarei contigo e-este que eu porque eu enviei-te em-fazeres-sair-tu a o-povo sobre servireis a Elohim sobre a-montanha a-esta');
INSERT INTO verses VALUES (1593, 2, 3, 13, 'E-disse Moisés a eis eu eu veio a filhos-de a-eles e-disser a-eles Elohim-de pais-vossos enviou-me a-vós e-disserem a-mim que- nome-seu que disse a-eles');
INSERT INTO verses VALUES (1594, 2, 3, 14, 'E-disse Elohim a Moisés EU-SOU que E-disse E-disse assim dirás a-filhos-de Israel EU-SOU enviou-me a-vós');
INSERT INTO verses VALUES (1595, 2, 3, 15, 'E-disse ainda Elohim a Moisés assim dirás yhwh filhos-de Israel yhwh Elohim-de pais-vossos Elohim-de Abraão Elohim-de Isaque e-Elohim-de Jacó para-sempre a-vós este nome-meu para-sempre e-esta memória-minha para-geração geração');
INSERT INTO verses VALUES (1596, 2, 3, 16, 'vai e-reunirás a anciãos-de Israel e-dirás yhwh yhwh Elohim-de pais-vossos apareceu a-mim Elohim-de Abraão Isaque dizendo para-dizer visitar visitei a-vós a-vós o-feito para-vocês em-Egito');
INSERT INTO verses VALUES (1597, 2, 3, 17, 'e-disse farei-subir a-vós de-aflição-de Egito a terra o-cananeu e-o-heteu e-o-amorreu e-o-perizeu e-o-heveu e-o-jebuseu a terra que-flui leite e-mel');
INSERT INTO verses VALUES (1598, 2, 3, 18, 'e-ouvirão a-voz-tua e-virás tu e-anciãos-de Israel a rei Egito a-ele yhwh yhwh Elohim-de os-hebreus encontrou-nos e-agora e-agora o-caminho-de por-favor caminho três-de dias no-deserto e-sacrificaremos a-יהוה Elohim-nosso');
INSERT INTO verses VALUES (1599, 2, 3, 19, 'e-eu soube que não dará a-vós rei Egito para-ir e-não com-mão forte');
INSERT INTO verses VALUES (1600, 2, 3, 20, 'e-enviarei a mão-minha e-ferirei a Egito em-todo maravilhas-minhas que eu-farei em-meio-dele e-depois-de assim enviará a-vós');
INSERT INTO verses VALUES (1601, 2, 3, 21, 'e-darei a favor o-povo- este em-olhos-de que e-será não ides não ireis vazios');
INSERT INTO verses VALUES (1602, 2, 3, 22, 'e-pedirá mulher de-vizinha-dela e-de-habitante-de casa-dela objetos-de prata ouro ouro e-vestimentas e-poreis sobre filhos-vossos e-sobre filhas-vossas e-despojareis a Egito');
INSERT INTO chapters VALUES (54, 2, 4, 31);
INSERT INTO verses VALUES (1603, 2, 4, 1, 'e-respondeu Moisés E-disse e-eis não crerão em-mim e-não ouvirão que porque dirão não yhwh a-ti yhwh');
INSERT INTO verses VALUES (1604, 2, 4, 2, 'E-disse a-ele yhwh em-mão-tua E-disse cajado');
INSERT INTO verses VALUES (1605, 2, 4, 3, 'E-disse lança-o terra-para e-lançou-o terra-para e-houve para-serpente e-fugiu Moisés de-face-dele');
INSERT INTO verses VALUES (1606, 2, 4, 4, 'E-disse yhwh a Moisés enviou mão-tua e-segura em-cauda-dele sua-mão mão-dele e-segurou e-houve E-foi para-cajado em-palma-dele');
INSERT INTO verses VALUES (1607, 2, 4, 5, 'para-que creiam porque apareceu yhwh yhwh Elohim-de pais-deles Elohim-de Abraão Elohim-de Isaque e-Elohim-de Jacó');
INSERT INTO verses VALUES (1608, 2, 4, 6, 'E-disse yhwh a-ele ainda traze- por-favor mão-tua e-trouxe sua-mão mão-sua em-seio-seu e-ele-tirou-a sua-mão mão-sua leprosa como-a-neve');
INSERT INTO verses VALUES (1609, 2, 4, 7, 'E-disse retorna mão-tua a seio-teu sua-mão mão-sua a seio-seu e-ele-tirou-a de-seio-seu e-eis- ela-retornou como-carne-sua');
INSERT INTO verses VALUES (1610, 2, 4, 8, 'e-será se não para-ti para-ti e-não eles-ouvirão para-voz-de o-sinal o-primeiro e-eles-crerão para-voz-de o-sinal o-último');
INSERT INTO verses VALUES (1611, 2, 4, 9, 'e-será se não também também para-dois-de os-sinais estes e-não eles-ouvirão para-voz-tua e-tu-tomarás de-águas-de o-rio e-tu-derramarás e-sejam e-serão as-águas que tu-tomarás e-sejam o-rio e-serão para-sangue na-terra-seca');
INSERT INTO verses VALUES (1612, 2, 4, 10, 'E-disse Moisés a yhwh por-mim não não homem eu também também também também também também desde-então a que porque pesado-de boca eu língua eu');
INSERT INTO verses VALUES (1613, 2, 4, 11, 'E-disse yhwh a-ele quem nome boca para-o-homem ou quem- ele-coloca mudo ou surdo ou que-vê ou cego eu yhwh yhwh');
INSERT INTO verses VALUES (1614, 2, 4, 12, 'e-agora vai e-eu estarei com boca-tua e-eu-ensinarei-te que tu-falarás');
INSERT INTO verses VALUES (1615, 2, 4, 13, 'E-disse por-mim Adonai envia- por-favor por-mão-de tu-enviarás');
INSERT INTO verses VALUES (1616, 2, 4, 14, 'e-acendeu-se- yhwh yhwh E-disse E-disse não-é-que אַהֲרֹן irmão-teu o-levita eu-sei porque ele ele-falará ele sai eis-que- ele saindo para-encontro-teu e-ele-te-verá e-ele-se-alegrará em-coração-seu');
INSERT INTO verses VALUES (1617, 2, 4, 15, 'e-tu-falarás a-ele e-tu-colocarás a as-palavras em-boca-sua e-eu estarei com boca-tua e-com- boca-sua e-eu-ensinarei a-vós את que vós-fareis');
INSERT INTO verses VALUES (1618, 2, 4, 16, 'e-ele-falará- a-ti para-ti a ele e-será ele ele-será- para-ti para-boca e-tu será- para-ele para-Elohim');
INSERT INTO verses VALUES (1619, 2, 4, 17, 'e-a o-bastão este tu-tomarás em-mão-tua que farás- nele a os-sinais');
INSERT INTO verses VALUES (1620, 2, 4, 18, 'E-andou Moisés e-voltou a Jetro sogro-seu E-disse a-ele irei por-favor e-voltarei a irmãos-meus que em-Egito vida E-disse vivos E-disse Jetro para-Moisés vai em-paz');
INSERT INTO verses VALUES (1621, 2, 4, 19, 'E-disse yhwh a Moisés em-Midiã vai retornou Egito porque morreram todo os-homens os-que-buscam a alma-tua');
INSERT INTO verses VALUES (1622, 2, 4, 20, 'E-tomou Moisés a mulher-sua e-a filhos-seus e-fez-montar-os sobre o-jumento E-tomou terra-para Egito E-tomou Moisés a bastão-de o-Elohim em-mão-sua');
INSERT INTO verses VALUES (1623, 2, 4, 21, 'E-disse yhwh a Moisés em-ir-teu para-voltar Egito-para viu todo os-prodígios que coloquei em-mão-tua e-farás-os diante-de Faraó e-eu fortalecerei a coração-dele e-não enviará a o-povo');
INSERT INTO verses VALUES (1624, 2, 4, 22, 'e-dirás a Faraó disse yhwh yhwh filhos-de primogênito-meu Israel');
INSERT INTO verses VALUES (1625, 2, 4, 23, 'e-disse a-ti enviou a filhos-de e-servirá-me e-recusaste eis eu eu matando a filho-teu primogênito-teu');
INSERT INTO verses VALUES (1626, 2, 4, 24, 'e-houve no-caminho na-hospedaria e-encontrou-o yhwh e-buscou matá-lo');
INSERT INTO verses VALUES (1627, 2, 4, 25, 'e-tomou Zípora pedra e-cortou a prepúcio-de filho-seu e-tocou E-disse que porque tu sangues tu para-mim');
INSERT INTO verses VALUES (1628, 2, 4, 26, 'e-desistiu nós então disse noivo-de sangues para-circuncisões');
INSERT INTO verses VALUES (1629, 2, 4, 27, 'E-disse yhwh a Arão vai para-encontro-de Moisés o-deserto-para E-andou e-encontrou-o em-monte-de o-Elohim e-beijou- para-ele');
INSERT INTO verses VALUES (1630, 2, 4, 28, 'e-contou Moisés para-Arão objeto-direto todo yhwh yhwh que enviou-o e-a todo os-sinais que ordenou-o');
INSERT INTO verses VALUES (1631, 2, 4, 29, 'E-andou Moisés e-Arão e-reuniram a todo anciãos-de filhos-de Israel');
INSERT INTO verses VALUES (1632, 2, 4, 30, 'e-falou Aarão את todo as-palavras yhwh palavra yhwh a Moisés E-fez os-sinais para-olhos-de o-povo');
INSERT INTO verses VALUES (1633, 2, 4, 31, 'e-creu o-povo e-ouviram porque yhwh yhwh a filhos-de ver e-que viu a aflição-deles e-inclinaram-se e-prostraram-se');
INSERT INTO chapters VALUES (55, 2, 5, 23);
INSERT INTO verses VALUES (1634, 2, 5, 1, 'e-depois vieram Moisés e-Aarão e-disseram a Faraó yhwh disse yhwh Elohim-de Israel enviou a povo-meu e-celebrem para-mim no-deserto');
INSERT INTO verses VALUES (1635, 2, 5, 2, 'E-disse Faraó quem yhwh que escutarei em-voz-dele para-enviar a não não conheci a yhwh não a Israel não enviarei');
INSERT INTO verses VALUES (1636, 2, 5, 3, 'e-disseram Elohim-de os-hebreus encontrou-se sobre-nós iremos por-favor o-caminho-de três-de dias no-deserto e-sacrificaremos para-יהוה Elohim-nosso para-que-não encontre-nos com-a-pestilência ou com-a-espada');
INSERT INTO verses VALUES (1637, 2, 5, 4, 'E-disse para-eles rei Egito por-que Moisés e-Aarão fazeis-cessar a o-povo de-obras-dele ide para-trabalhos-forçados-vossos');
INSERT INTO verses VALUES (1638, 2, 5, 5, 'E-disse Faraó eis muitos agora a-terra a-terra eles eles de-trabalhos-forçados-deles');
INSERT INTO verses VALUES (1639, 2, 5, 6, 'E-ordenou פַּרְעֹה no-dia o-aquele a os-feitores no-povo dizendo oficiais-dele para-dizer');
INSERT INTO verses VALUES (1640, 2, 5, 7, 'não continuareis para-dar palha para-o-povo para-fazer-tijolos as-tijolos como-ontem e-hoje eles e-eles-irão e-eles-colherão a-eles palha');
INSERT INTO verses VALUES (1641, 2, 5, 8, 'e-a ordem as-tijolos eles eles fazendo ontem antes-de-ontem colocareis não não nós de-ele eles desceiros eles sobre dizendo eles clamando dizendo venhamos sacrifiquemos א-לוהינו');
INSERT INTO verses VALUES (1642, 2, 5, 9, 'se-tornará-pesada a-obra sobre os-homens e-farão--- nela e-a clamarão em-palavras-de--- mentira');
INSERT INTO verses VALUES (1643, 2, 5, 10, 'e-saíram de-mandatários o-povo e-de-seus-oficiais e-disseram a dizendo dizendo disse disse Faraó não-sou a-vós a-vós teven');
INSERT INTO verses VALUES (1644, 2, 5, 11, 'vocês ide tomai a-vós teven de-o-que encontrareis que não-há impuro de-vossa-trabalho palavra');
INSERT INTO verses VALUES (1645, 2, 5, 12, 'e-dispersou o-povo em-todo terra Egito para-colher kash- la-teven-');
INSERT INTO verses VALUES (1646, 2, 5, 13, 've-han-nogshim- atzim- dizendo khalu- ma-ashechem- palavra-de dia be-yomo- como bi-heyet- ha-teven-');
INSERT INTO verses VALUES (1647, 2, 5, 14, 'va-yukhu- oficiais-de filhos-de Israel que colocaram em-eles opressores-de dizendo dizendo não não esgotaram-vos rasgastes-vos para-branco como-ontem anteontem também ontem também o-dia');
INSERT INTO verses VALUES (1648, 2, 5, 15, 'e-vieram oficiais-de filhos-de Israel e-clamaram a dizendo dizendo por-que fazes assim para-os-teus-servos');
INSERT INTO verses VALUES (1649, 2, 5, 16, 'pedra não-há deu para-o-servos-teus e-para-pedras dizendo para-nós fazei e-eis servos-teus machucados e-pecado povo-tua');
INSERT INTO verses VALUES (1650, 2, 5, 17, 'E-disse n-rasos vós n-rasos sobre assim vós dizendo-os vamos-nós n-sacrificaremos para-יהוה');
INSERT INTO verses VALUES (1651, 2, 5, 18, 'e-agora ide serviremos-ele e-tijolo não a-vós a-vós e-o-interno para-os-tijolos dará-vos');
INSERT INTO verses VALUES (1652, 2, 5, 19, 'e-eles-veem de-oficiais filhos-de eles eles dizendo dizendo não tirar-vós dos-tijolos-vossos palavra-de dia em-dia-de-o');
INSERT INTO verses VALUES (1653, 2, 5, 20, 'e-eles-encontraram-se a Moisés e-com Arão estando-plantados para-enfrentá-los em-sair-de-eles de-a פַּרְעֹה');
INSERT INTO verses VALUES (1654, 2, 5, 21, 'e-disseram a-eles veira yhwh sobre-vós veyishpot que hibashatem a reicheinu be-einei Pharaoh uve-einei seus-servos para-dar cherev byeidam para-nos-matar-:');
INSERT INTO verses VALUES (1655, 2, 5, 22, 'e-estabeleceu-se Moisés a yhwh E-disse Adonai por-que o-mau ao-povo esta por-que isto me-destinaste');
INSERT INTO verses VALUES (1656, 2, 5, 23, 'e-desde-o-tempo eu-vi a Faraó para-falar em-tu-nome foi-mau ao-povo esta e-o-salve não salvaste a o-seu-povo');
INSERT INTO chapters VALUES (56, 2, 6, 30);
INSERT INTO verses VALUES (1657, 2, 6, 1, 'E-disse yhwh a Moisés agora verás que farei que porque com-a-mão forte os-enviará e-com-a-mão forte os-expulsará de-a-terra-o');
INSERT INTO verses VALUES (1658, 2, 6, 2, 'e-falou Elohim a E-disse a-ele a-ele yhwh yhwh');
INSERT INTO verses VALUES (1659, 2, 6, 3, 'e-eu-apareci a Abraão a Isaque e-a Jacó yhwh não e-meu-nome a-eles não conheci-me para-eles');
INSERT INTO verses VALUES (1660, 2, 6, 4, 'e-tambem ergui-eu a aliança-minha com-elas-os a-eles a-eles a terra terra a terra moradas-deles-os que moraram em-ela');
INSERT INTO verses VALUES (1661, 2, 6, 5, 'e-tambem eu ouvi a clamor-de filhos-de Israel que Egito servos eles e-elembrei-me a em-pacto-meu');
INSERT INTO verses VALUES (1662, 2, 6, 6, 'portanto disse filhos-de Israel yhwh yhwh e-sairei debaixo-de de-baixo-de sílulas Egito e-salvarei vos de-servidão-de-eles e-redimir-eu vos com-braco estendida e-com-juízos grandes-');
INSERT INTO verses VALUES (1663, 2, 6, 7, 'e-eu-tomarei a-vocês para-mim para-povo e-eu-serei a-vós para-אלהים e-vocês-sabereis que eu yhwh אֱלֹהִים-de-vós o-que-tirou vos debaixo-de sendes Egito');
INSERT INTO verses VALUES (1664, 2, 6, 8, 'e-eu-trarei vos a a-terra que eu-elevei a minha-mão para-dar a-ela le-abraham para-Isaque e-para-JaŃob a-vós essa-a a-vós yhwh eu yhwh');
INSERT INTO verses VALUES (1665, 2, 6, 9, 'e-falou Moisés assim a filhos-de Israel e-não ouviram a espírito de-curto espírito e-de-trabalho dura-:');
INSERT INTO verses VALUES (1666, 2, 6, 10, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (1667, 2, 6, 11, 'veio palavra a פַּרְעֹה rei Egito e-enviará a filhos-de Israel de-a-terra-o');
INSERT INTO verses VALUES (1668, 2, 6, 12, 'e-falou Moisés diante-de yhwh dizendo eis filhos-de Israel não ouviu a-mim e-como me-ouvam פַּרְעֹה e-eu erem lábios-verso');
INSERT INTO verses VALUES (1669, 2, 6, 13, 'e-falou yhwh a Moisés e-a Aharon- e-ele-comandou-os a filhos-de Israel e-a פַּרְעֹה rei Egito para-sair a filhos-de Israel de-terra-de Egito');
INSERT INTO verses VALUES (1670, 2, 6, 14, 'Estas cabeças-de casa-de pais-deles filhos-de Reuven- primogênito-de Israel Chenoch- e-Palu- Chezron- Estas estes famílias-de Reuven-verso');
INSERT INTO verses VALUES (1671, 2, 6, 15, 'e-filhos-de Shimon- Yemu''el ve-Yamin ve-Ohad ve-Yakin ve-Tsohar ve-Shaul filho-de Estas estes famílias-de Simeão');
INSERT INTO verses VALUES (1672, 2, 6, 16, 've-Eleh Shmot filhos-de Levi le-Toldotam Gérson e-Coate e-meu-amargura e-dois chayyei Levi sete e-trinta e-cem anos');
INSERT INTO verses VALUES (1673, 2, 6, 17, 'filhos-de Gerson para-meu-filho e-Shimi para-famílias-deles');
INSERT INTO verses VALUES (1674, 2, 6, 18, 'e-filhos-de Qehat Anrão e-Izar e-Chevron e-Uziel e-dois chayyei Qehat três e-trinta e-cem anos');
INSERT INTO verses VALUES (1675, 2, 6, 19, 'e-filhos-de miseria Mahli e-Mushi Estas famílias-de o-levita para-os-filhos-deles');
INSERT INTO verses VALUES (1676, 2, 6, 20, 'E-tomou Amram a Joquebede a-ele a-ele para-esposa a-ele a-ele a אַהֲרֹן e-a Moisés e-dois chayyei Amram sete e-trinta e-cem anos');
INSERT INTO verses VALUES (1677, 2, 6, 21, 'e-filhos-de Isar Coré e-Nofeg e-Zicri');
INSERT INTO verses VALUES (1678, 2, 6, 22, 'e-filhos-de Uziel Misha-el e-Eltsafan e-Sitri');
INSERT INTO verses VALUES (1679, 2, 6, 23, 'E-tomou Arão a Elisheba filha-de Amminadab a-ele Nasom a-ele a-ele e-deu-à-luz para-ele a Nadav e-a Abihu a Elazar e-a Itamar');
INSERT INTO verses VALUES (1680, 2, 6, 24, 'e-filhos-de Qorach Assir e-ekana e-abiasaf Estas famílias-de o-karchi-:');
INSERT INTO verses VALUES (1681, 2, 6, 25, 'e-elazar filho-de Arão tomou- a-ele a-ele putiael a-ele a-ele e-deu-à-luz Estas a pinchas estes cabeças-de pais os-levitas para-famílias-deles');
INSERT INTO verses VALUES (1682, 2, 6, 26, 'ele אַהֲרֹן e-Mosheh que disse yhwh a-eles extraiu-os a filhos-de Israel da-terra-de Egito sobre exércitos-deles-verso');
INSERT INTO verses VALUES (1683, 2, 6, 27, 'eles os-falando a faráoh rei-de Egito para-sair ele filhos-de Israel de-Egito ele Moisés e-Aarão');
INSERT INTO verses VALUES (1684, 2, 6, 28, 'e-houve no-dia palavra yhwh a Moisés em-terra-de Egito');
INSERT INTO verses VALUES (1685, 2, 6, 29, 'e-ele-falou yhwh a Moisés dizendo yhwh yhwh palavra a Faraó rei Egito a todo que eu palavra para-ti');
INSERT INTO verses VALUES (1686, 2, 6, 30, 'E-disse Moisés diante-de yhwh eis eu cortar lábios-de-duas e-como ele-ouvirá a-mim פַּרְעֹה');
INSERT INTO chapters VALUES (57, 2, 7, 29);
INSERT INTO verses VALUES (1687, 2, 7, 1, 'E-disse yhwh a Moisés viu dei-te Elohim para-o-Faraó e-Aharon será será profeta-tu');
INSERT INTO verses VALUES (1688, 2, 7, 2, 'tu Tedeber a todo que eu-direi-te e-Aharon irmão-teu Yedaber a Faraó e-ele-mandará a filhos-de Israel de-a-terra-o');
INSERT INTO verses VALUES (1689, 2, 7, 3, 'e-eu eu-dificultarei a coração Faraó e-aumentarei a seus-sinais e-a seus-milagres em-terra-de Egito');
INSERT INTO verses VALUES (1690, 2, 7, 4, 'e-não ouvirá a-mim-vocês Faraó e-darei a minha-mão em-Egito e-sairei-eu a exércitos-meus a povo-de-mim filhos-de Israel de-terra-de Egito em-julgamentos grandes');
INSERT INTO verses VALUES (1691, 2, 7, 5, 'e-sabem Mitzrayim porque yhwh yhwh bentoti a yadi sobre Egito vehotsetiti a filhos-de Israel deles');
INSERT INTO verses VALUES (1692, 2, 7, 6, 'E-fez Moisés e-Arão como-que ordenou yhwh eles assim fizeram');
INSERT INTO verses VALUES (1693, 2, 7, 7, 'umoshe filho-de oitenta ano e-Aaron filho-de três ushmonim ano em-seu-falar a פַּרְעֹה');
INSERT INTO verses VALUES (1694, 2, 7, 8, 'E-disse yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (1695, 2, 7, 9, 'que yedaber a-vos Faraó dizendo deite a-vós maravilha e-dirás a Arão toma a cane-teu haja diante-de Pharaoh seja para-o-crocodilo');
INSERT INTO verses VALUES (1696, 2, 7, 10, 'E-veio Moisés e-Aarão a Faraó e-ele-fizeram assim conforme yhwh yhwh e-ele-jogou Arão a cane-seu diante-de Pharaoh e-houve servos-dele E-foi para-o-crocodilo');
INSERT INTO verses VALUES (1697, 2, 7, 11, 'E-chamou também Faraó aos-sábios e-aos-feiticeiros e-ele-fizeram também eles os-sábios Egito em-lhes-fogos assim');
INSERT INTO verses VALUES (1698, 2, 7, 12, 'e-ele-throw-them homem o-sua-bastão e-foram para-os-taninos e-ele-devorou bastao-de- אַהֲרֹן a de-sua-bastoes');
INSERT INTO verses VALUES (1699, 2, 7, 13, 'e-ele-se-firmou coração Faraó e-não ouviu a-eles conforme palavra yhwh');
INSERT INTO verses VALUES (1700, 2, 7, 14, 'E-disse yhwh a Moisés pesado coração Faraó de-recusar para-enviar o-povo');
INSERT INTO verses VALUES (1701, 2, 7, 15, 'vai a o-Pharaoh eis sai saindo a-marear e-voc-se-estabelecer-a para-o-encontro-dele sobre língua o-Yor e-a-maté que se-tornar para-serpente  tomarei  em-mão-teu');
INSERT INTO verses VALUES (1702, 2, 7, 16, 'e-dirás a-ele yhwh Elohim-de os-Hebreus enviaram-me a-ti dizendo enviou a povo-meu e-worship-me no-deserto e-eis não ouviste até assim-:');
INSERT INTO verses VALUES (1703, 2, 7, 17, 'assim disse yhwh com-isto sabereis que eu yhwh eis eu ferindo- com-o-bastão que em-minha-mão sobre as-águas que no-Nilo e-ser-vos-tornar-ão em-sangue-:');
INSERT INTO verses VALUES (1704, 2, 7, 18, 'e-a-peixe que morrerás morra e-o-veneno o-nilo e-se-contaminaram Egito águas águas de o-rio');
INSERT INTO verses VALUES (1705, 2, 7, 19, 'E-disse yhwh a Moisés disse a arão toma teu-bastão e-estende-a tua-mão sobre das-aguas Egito sobre rios-de-eles sobre rio-de-eles e-sobre lagos-de-eles e-sobre todo esperança aguas-de-eles e-serão- sangue e-será sangue em-todo terra Egito e-na-arvores e-na-pedras');
INSERT INTO verses VALUES (1706, 2, 7, 20, 'e-ele-fizeram- assim-que Moisés e-Aharon como-que ordenou yhwh e-ele-alçou com-a-bastona e-ele-feriu a as-águas que no-Nilo aos-olhos-de פַּרְעֹה e-perante-os-olhos-de servos-dele e-ele-virou-se todo as-águas que no-Nilo para-sangue');
INSERT INTO verses VALUES (1707, 2, 7, 21, 'e-a-peixe que no-yor morreu e-estragou-se o-rio e-não puderam águas para-beber e-houve de o-yor E-foi o-sangue em-todo terra Egito');
INSERT INTO verses VALUES (1708, 2, 7, 22, 'e-fizeram- assim os-sábios Egito em-seus-luxos e-ele-firmou coração-de Faraó e-não ouviu yhwh conforme palavra yhwh');
INSERT INTO verses VALUES (1709, 2, 7, 23, 'e-ele-virou Faraó E-veio a casa-dele e-não beber para-seu-coracao também a-esta');
INSERT INTO verses VALUES (1710, 2, 7, 24, 'e-eles-cavaram todo Egito em-torno-de águas águas que não não puderam para-beber de-a-águas o-rio');
INSERT INTO verses VALUES (1711, 2, 7, 25, 'e-ele-fill sete-de dias atrás-de bater yhwh a o-rio');
INSERT INTO verses VALUES (1712, 2, 7, 26, 'E-disse yhwh a Moisés veio a a-ele e-dirás disse yhwh disse yhwh enviou a povo-meu e-servirâ-me');
INSERT INTO verses VALUES (1713, 2, 7, 27, 'e-se tu tu eis eu eu castigo a todo seu limite nos-carpados:');
INSERT INTO verses VALUES (1714, 2, 7, 28, 'e-swarm o-n-ilho sapos e-subiram e-entraram em-a-casa-teu e-no-quarto de-dormir-teu e-sobre de-cama-teu e-no-casa servos-teus e-no-povo-teu e-no-forno-teu e-no-vestimentas-teu');
INSERT INTO verses VALUES (1715, 2, 7, 29, 'e-em-choro uBeAmakha e-em-todo servos-teus eles-subirão os-sapos');
INSERT INTO chapters VALUES (58, 2, 8, 28);
INSERT INTO verses VALUES (1716, 2, 8, 1, 'E-disse yhwh a Moisés disse a Arão desvia a tua-mão- com-a-magia sobre as-nhara sobre os-ilhos e-sobre os-estagnos veha''ala a as-rãs sobre terra Egito');
INSERT INTO verses VALUES (1717, 2, 8, 2, 'e-virou Arão a sobre sobre de-a-água Egito e-ele-subiu a-rã e-ela-cobriu a terra Egito');
INSERT INTO verses VALUES (1718, 2, 8, 3, 'e-eles-fizeram- assim os-sábios em-seus-magias e-eles-subiram a as-rãs sobre terra Egito');
INSERT INTO verses VALUES (1719, 2, 8, 4, 'E-chamou Faraó para-moshe e para Aharon E-disse invocai-vos a yhwh e-disciplinar os-sapos de mim e do meu e lançarei a o-povo e sacrifiquem para-יהוה');
INSERT INTO verses VALUES (1720, 2, 8, 5, 'E-disse Moisés para-o-faraó se-ornar em-mim para-quando eu-apelo para-ti a-ti e-para-o-seu-povo para-cortar as-rãs de-vós e-de-tua-casa somente no-Nilo vocês-permanecerão');
INSERT INTO verses VALUES (1721, 2, 8, 6, 'E-disse para-o-manhã E-disse como-a-palavra-tua para-que saberás porque não como-יהוה Elohim-nosso');
INSERT INTO verses VALUES (1722, 2, 8, 7, 'e-virão-se os-sapos de-tu e-de-a-casa-tua e-de-o-servidor-tu e-do-povo-tu somente no-río permanecer-vos-eis');
INSERT INTO verses VALUES (1723, 2, 8, 8, 'e-ele-saiu Moisés e-Aarão de-com Faraó e-clamou Moisés a yhwh sobre palavra os-sapos que nome a-Faraó');
INSERT INTO verses VALUES (1724, 2, 8, 9, 'E-fez yhwh conforme-a-palavra-de Moisés e-morreram os-sapos de nas-casas de nas-áreas e-de as-terra-s');
INSERT INTO verses VALUES (1725, 2, 8, 10, 'e-ele-reuniram eles chamarim ermines e-ela-estragou-se a-terra');
INSERT INTO verses VALUES (1726, 2, 8, 11, 'E-viu פַּרְעֹה que era a-livreira e-o-grave a coração-dele e-não ouviu a-eles conforme yhwh yhwh');
INSERT INTO verses VALUES (1727, 2, 8, 12, 'E-disse yhwh a Moisés disse a Arão inclina a a-terra e-derribe a o-pó a-terra e-acontecerá para-os-formigas em-todo terra Egito');
INSERT INTO verses VALUES (1728, 2, 8, 13, 'e-ele-fizeram- assim e-ele-inclinou-se Arão a sua-mão com-sua-bastona a-terra a o-pó a-terra e-sobre-os-animais o-vermes a-terra ser todo poeira-de a-terra foi de-vermes em-todo terra Egito');
INSERT INTO verses VALUES (1729, 2, 8, 14, 'e-fizeram assim os-sábios em-seus-caracteristicas para-sair a os-cinzentos e-não poderiam e-foi e-sobre-os-animais em-o-homem e-na-bestas');
INSERT INTO verses VALUES (1730, 2, 8, 15, 'e-disseram os-sábios a Faraó dedo ela ela e-estreitou-se coração-de Faraó e-não ouviu yhwh conforme palavra yhwh');
INSERT INTO verses VALUES (1731, 2, 8, 16, 'E-disse yhwh a Moisés o-amanhecer na-manhã e-tome-posiçâo diante-de eis hein saindo a-a-gôa a-ele a-ele disse yhwh yhwh enviou povo-meu e-servirâ-me');
INSERT INTO verses VALUES (1732, 2, 8, 17, 'que se não-tu enviador a povo-meu eis-me emissor em-tu e-em-teus-servos e-no-seu-povo e-em-tuas-casas a a-peste-de-insetos e-eles-encherão as-casas a-terra a he-aráv e-também a terra que e-ele-s sobre-ela');
INSERT INTO verses VALUES (1733, 2, 8, 18, 'e-hifleteeti no-dia o-aquele a terra go-shen que meu-povo ficou-em-pé para-não para-não ser- nome tarde que saberás yhwh eu a-terra em-meio-de a-terra');
INSERT INTO verses VALUES (1734, 2, 8, 19, 'e-postarei resgate entre povo-meu e-entre povo-teu para-manhã será o-sinal a-esta');
INSERT INTO verses VALUES (1735, 2, 8, 20, 'E-fez yhwh assim E-veio tarde pesado casa-seu Faraó e-Beit servos-dele e-em-todo terra Egito a-terra de-diante-de de-faces-de a-plaga');
INSERT INTO verses VALUES (1736, 2, 8, 21, 'E-chamou פַּרְעֹה a Moisés E-disse E-disse ide zibchu le-elohemekhem na-terra');
INSERT INTO verses VALUES (1737, 2, 8, 22, 'E-disse Moisés não nakhon para fazer assim que abominação-de Egito nizbazh a-yhwh Elohim-nosso eis nizbazh a toavat Egito le-einehem e-não yiskelunuh');
INSERT INTO verses VALUES (1738, 2, 8, 23, 'o-caminho-de três-de dias nelikh no-deserto vezavakhnu para-יהוה Elohim-nosso conforme diga a-nós');
INSERT INTO verses VALUES (1739, 2, 8, 24, 'E-disse פַּרְעֹה eu e-solte vos e-zarbeieis a-יהוה Elohim-vosso no-deserto somente afaste-se não vocês-afastem para-andar clamei em-meu-lugar');
INSERT INTO verses VALUES (1740, 2, 8, 25, 'E-disse Moisés eis eu saindo- -de-você e-eu-orarei a yhwh e-se-apartará o-grilo -de-Faraó -de-seus-servos -e-de-seu-povo amanhã- somente a José para-não o-tel para-não enviou a o-povo para-sacrificar para-יהוה');
INSERT INTO verses VALUES (1741, 2, 8, 26, 'e-ele-saiu Moisés de-com Faraó e-ele-suplicou a yhwh');
INSERT INTO verses VALUES (1742, 2, 8, 27, 'E-fez yhwh conforme-a-palavra-de Moisés e-removeu o-terrível de-faraó de-seus-servos e-de-seu-povo não permaneceu um');
INSERT INTO verses VALUES (1743, 2, 8, 28, 'e-ele-afirmou Faraó a também também na-vez esta e-não enviou a o-povo');
INSERT INTO chapters VALUES (59, 2, 9, 35);
INSERT INTO verses VALUES (1744, 2, 9, 1, 'E-disse yhwh a Moisés veio a a-ele e-tu-falarás yhwh assim disse yhwh Elohim-de os-hebreus enviou a povo-meu e-servirâ-me');
INSERT INTO verses VALUES (1745, 2, 9, 2, 'que se tu tu para-libertar e-vos mantém-se em-eles');
INSERT INTO verses VALUES (1746, 2, 9, 3, 'eis mão-de yhwh ho-yah be-miknecha que no-campo ba-susim ba-chamorim em-gamalim em-o-amanhecer e-no-rebanho palavra muito muito');
INSERT INTO verses VALUES (1747, 2, 9, 4, 'e-separou yhwh entre de-o-pecuário Israel e-entre de-o-pecuário Egito e-não morra de-todo para-filhos-de Israel palavra');
INSERT INTO verses VALUES (1748, 2, 9, 5, 'e-colocou yhwh na-festa dizendo amanhã fará yhwh a-palavra este na-terra');
INSERT INTO verses VALUES (1749, 2, 9, 6, 'E-fez yhwh a a-coisa o-este de-amanhã E-morreu todo de-o-pecuário Egito e-de-o-pecuário filhos-de um não morreu um');
INSERT INTO verses VALUES (1750, 2, 9, 7, 'e-enviou Faraó e-eis não morreu de-o-rebanho Israel até um e-se-tornou-grande coração Faraó e-não enviou a o-povo');
INSERT INTO verses VALUES (1751, 2, 9, 8, 'E-disse yhwh a Moisés e-a a-vós tomai para-vocês enchei vossas-farcas cinza o-ovelha e-espargeu-o Moisés aos-céus para-olhos-de Faraó');
INSERT INTO verses VALUES (1752, 2, 9, 9, 'e-foi até-a-poeira sobre todo terra Egito e-será sobre o-homem e-sobre o-gado para-schichin florescendo abawbuot em-todo terra Egito');
INSERT INTO verses VALUES (1753, 2, 9, 10, 've-yikhu a piach ha-kibshan e-pararam diante-de פַּרְעֹה ele a-ele Moisés e-houve E-foi schichin abawbuot florescendo e-sobre-os-animais u-vabahemah');
INSERT INTO verses VALUES (1754, 2, 9, 11, 'e-não puderam os-escritores para-estar diante-de de-diante-de de-diante-de o-sufocado porque foi o-sufocado em-os-escritores e-em-todo Egito');
INSERT INTO verses VALUES (1755, 2, 9, 12, 'e-ele-fortaleceu yhwh a coração Faraó e-não ouviu a-eles como yhwh yhwh a Moisés');
INSERT INTO verses VALUES (1756, 2, 9, 13, 'E-disse yhwh a Moisés o-manhã de-manhã e-ele-se-estabeleceu diante-de Faraó a-ele a-ele yhwh disse yhwh Elohim-de os-hebreus enviou a povo-meu e-eles-me-servirão');
INSERT INTO verses VALUES (1757, 2, 9, 14, 'que em-o-tempo desta eu enviou a todo das-minha-preguic a para-o-teu-coracao e-em-seus-servos-teus e-no-povo-teu que conheceras porque não-há como-mim em-todo a-terra');
INSERT INTO verses VALUES (1758, 2, 9, 15, 'que agora enviei-eu a minha-mao e-eu-ameacei a-ti e-com o-povo-teu no-dizer e-tu-escondeste-te de a-terra');
INSERT INTO verses VALUES (1759, 2, 9, 16, 'e-entretanto por-causa-de esta te-elevei-te por-causa-de para-exibir-te a minha-força e-para-o conta nome-meu em-todo a-terra');
INSERT INTO verses VALUES (1760, 2, 9, 17, 'ainda-tu elevado em-o-povo-meu para-não lança-os');
INSERT INTO verses VALUES (1761, 2, 9, 18, 'eis-me manda-chover como tempo-de amanhã gelo pesado muito que não foi como-este em-Egito de-o o-dia foi-fundada-a e-até agora');
INSERT INTO verses VALUES (1762, 2, 9, 19, 'e-agora enviou a-ovelha a de-teu-rebanho e-a a-ti que a-ti no-campo todo o-homem e-o-animal que será-achado-a no-campo e-não será-coletado-o a-casa e-descerá sobre-eles o-gelo e-morreram');
INSERT INTO verses VALUES (1763, 2, 9, 20, 'o-teme a yhwh yhwh de-escravos Faraó ele-livrou a seus-escravos e-a de-seu-banhado a as-casas');
INSERT INTO verses VALUES (1764, 2, 9, 21, 'e-que não nome seu-coracao yhwh palavra yhwh e-olvidou a seus-escravos e-a suas-propriedades no-campo');
INSERT INTO verses VALUES (1765, 2, 9, 22, 'E-disse yhwh a desvia a mão-tua e-seja os-céus E-foi gelo em-todo terra Egito sobre o-homem e-sobre o-gado e-sobre todo erva-de o-campo em-terra-de Egito');
INSERT INTO verses VALUES (1766, 2, 9, 23, 'e-ele-esticou Moisés a seu-bastão sobre dar e-yhwh deu sons e-gelo e-ela-andou fogo yhwh e-ele-choveu yhwh barrad sobre terra Egito');
INSERT INTO verses VALUES (1767, 2, 9, 24, 'e-houve barad ve-esh mitlakhat no-meio-de habbarad pesado muito que não foi kamohu em-todo terra era meaz haytah legoy');
INSERT INTO verses VALUES (1768, 2, 9, 25, 'vayyakh o-barad em-todo terra Egito a todo que no-campo de-homem e-até animal e-a todo erva o-campo bateu o-barad e-a todo árvore o-campo quebra');
INSERT INTO verses VALUES (1769, 2, 9, 26, 'somente em-terra-de goshen que nome filhos-de não ser foi barad');
INSERT INTO verses VALUES (1770, 2, 9, 27, 'e-enviou פַּרְעֹה E-chamou para-moshe e-para-aaron E-disse a-eles pecado-eu a-vez yhwh o-justo e-eu e-o-seu-povo os-malvados');
INSERT INTO verses VALUES (1771, 2, 9, 28, 'clamem a yhwh e-muita de-ser vozes Elohim e-com-gelo e-eu-enviaria vos e-não voces-aumentariam para-estar-parado-verso-final');
INSERT INTO verses VALUES (1772, 2, 9, 29, 'E-disse a-ele Moisés quando-sair-eu a a-cidade eu-separarei a kapay a yhwh não e-cessarão e-o-gelo não que ainda a-terra saberás porque para-יהוה a-terra');
INSERT INTO verses VALUES (1773, 2, 9, 30, 'e-tu e-seus-servos-teus eu-sei que ainda-não temerão-eles de-diante-de yhwh Elohim');
INSERT INTO verses VALUES (1774, 2, 9, 31, 'e-a-lã e-o-trigo nucata que ha-seora aviv e-a-palha gibol');
INSERT INTO verses VALUES (1775, 2, 9, 32, 've-hachita ve-hakusemet não nuku que afilot até-aqui');
INSERT INTO verses VALUES (1776, 2, 9, 33, 'e-saiu Moisés de-com Faraó a a-cidade vayifros as-suas-mãos a yhwh e-eles-pararam as-vozes e-o-gelo e-chuva não foi-espalhado para-terra');
INSERT INTO verses VALUES (1777, 2, 9, 34, 'E-viu פַּרְעֹה porque parou a-chuva e-o-gelo e-as-vozes e-continuou para-o-pecar e-ele-dificultou ele ele e-seus-servos');
INSERT INTO verses VALUES (1778, 2, 9, 35, 'e-ele-fortaleceu coração Faraó e-não enviou a filhos-de Israel como yhwh yhwh por-mão-de Moisés');
INSERT INTO chapters VALUES (60, 2, 10, 29);
INSERT INTO verses VALUES (1779, 2, 10, 1, 'E-disse yhwh a Moisés veio a Faraó porque eu dificultei a coração-seu e-a Estas seus-servos para-que minha seus-sinais estes em-o-centro-dele');
INSERT INTO verses VALUES (1780, 2, 10, 2, 'e-para-o-fim-de você-contará em-o-ouvido seu-filho e-filho-de seu-filho a que brinquei-eu-com em-Egito e-a sinais-meus que coloquei yhwh e-voces-sabereis porque eu yhwh');
INSERT INTO verses VALUES (1781, 2, 10, 3, 'E-veio Moisés e-Aharon a Faraó a-ele a-ele yhwh disse yhwh Elohim-de os-Ebraelitas até quando de-que-voces-se-recusaram para-anotar de-perante-mim enviou povo-meu e-va-abdu-ni');
INSERT INTO verses VALUES (1782, 2, 10, 4, 'que se tu tu para-shalach a meu-povo eis-me multiplicarei ma-char ar-beh bi-gvul-cha');
INSERT INTO verses VALUES (1783, 2, 10, 5, 've-kisah a a-terra a-terra e-não podia li-roth e-coma a-terra ve-achal a Jetro a-vós a-restante e-coma de o-barad a-vós a todo o-arvore o-crescente para-vocês de o-campo');
INSERT INTO verses VALUES (1784, 2, 10, 6, 'e-cheios-de teus-batim וּבָתֵּ֣י todo seus-servos וּבָתֵּ֣י todo Egito que não viram avós-teus e-avós avós-teus até o-dia sobre a-terra até o-dia esta e-virou-se e-ele-saiu de-com פַּרְעֹה');
INSERT INTO verses VALUES (1785, 2, 10, 7, 'e-disseram servos-de Faraó a-ele até será for este a-nós para-apanhar enviou a os-homens e-servirão a yhwh que antes que-sabes porque perdida Egito');
INSERT INTO verses VALUES (1786, 2, 10, 8, 'e-os-estabeleceram a Moisés e-com E-disse a Faraó E-disse a-eles para-voces-andem quem a yhwh os-elohim-seus quem e-quem os-andantes');
INSERT INTO verses VALUES (1787, 2, 10, 9, 'E-disse Moisés com-os-jovens-nossos e-com-os-idosos-nossos nós-andaremos em-nossos-vanos e-nos-construindo em-nois-ovelhas e-nos-gado iremos que festa- yhwh para-nós');
INSERT INTO verses VALUES (1788, 2, 10, 10, 'E-disse a-eles haja assim yhwh com-vocês como eu-enviarei vos e-com crianças-vos que porque diante diante-de faces-vos');
INSERT INTO verses VALUES (1789, 2, 10, 11, 'não assim vai-em por-favor os-homens e-serve que yhwh porque a-ela vós eles e-ele-expeliu face-de de-com face-de Faraó');
INSERT INTO verses VALUES (1790, 2, 10, 12, 'E-disse yhwh a Moisés estenda a-tua-mão sobre terra Mitzrayim em-o-grilo e-ele-suba sobre terra a-terra e-ele-coma a todo erva a-terra a todo que deixou o-gelo');
INSERT INTO verses VALUES (1791, 2, 10, 13, 'e-virou Moisés a em-o-sicoma sobre terra Egito e-yhwh dirigiu-se espírito-de para-o-leste na-terra todo ser e-Espírito-de e-todo a-noite a-manhã foi e-o-vento do-leste levantou a o-arvèh:');
INSERT INTO verses VALUES (1792, 2, 10, 14, 'e-subiu o-arvèh sobre todo terra Egito e-ele-estabeleceu-se em-todo território Egito muito muito em-o-sua-frente não multiplicarei assim arvèh não e-depois-dele não ele-será- assim');
INSERT INTO verses VALUES (1793, 2, 10, 15, 'e-ele-cobriu a olho todo a-terra e-comeu a-terra a-terra a todo a-árvore a-terra e-את todo fruto o-arvore que hoteir habbarad e-não notar todo yerek em-a-arvore uveaseve o-campo em-todo terra Egito');
INSERT INTO verses VALUES (1794, 2, 10, 16, 'vayemaher Faraó para-chamar para-moshe uleahaaron E-disse chatati para-יהוה אֱלֹהִים-de-vocês e-para-vos');
INSERT INTO verses VALUES (1795, 2, 10, 17, 'e-agora eleva por-favor pecado-eu porém desta-vez e-o-implorar-vos a-yhwh vosso-Elohim e-disciplinar de-sobre-mim somente a a-mortes a-esta');
INSERT INTO verses VALUES (1796, 2, 10, 18, 'e-ele-saiu de-com Faraó e-ele-implorou a yhwh');
INSERT INTO verses VALUES (1797, 2, 10, 19, 'e-ele-virou yhwh espírito-de mar muito muito e-ele-levantou a a ervilha e-tocou-ele-o não sof multiplicarei um arvève um em-todo fronteira-de Egito');
INSERT INTO verses VALUES (1798, 2, 10, 20, 'e-estreitou yhwh a coração Faraó e-não enviou a filhos-de Israel');
INSERT INTO verses VALUES (1799, 2, 10, 21, 'E-disse yhwh a Moisés desvia mão-tua e-seja os-céus E-foi escuridão sobre terra Egito e-andará escuridão');
INSERT INTO verses VALUES (1800, 2, 10, 22, 'e-virou Moisés a mão-sua e-houve os-céus E-foi treva- escuridão em-todo terra Egito três dias');
INSERT INTO verses VALUES (1801, 2, 10, 23, 'não viram homem a o-seu-irmão e-não levantaram-se homem de-em-sob-dele três-de ser luz filhos-de Israel foi luz em-mesmo-lugares-deles');
INSERT INTO verses VALUES (1802, 2, 10, 24, 'E-chamou Faraó a E-disse E-disse vão-vocês servem a yhwh somente rebanho-de-vocês e-no-seu-campo se-reúna também tuf-vosso irei com-vos');
INSERT INTO verses VALUES (1803, 2, 10, 25, 'E-disse Moisés também tu dareis em-mão-nossa sacrifícios e-oferendas e-faremos para-יהוה Elohim-nosso');
INSERT INTO verses VALUES (1804, 2, 10, 26, 'e-também de-nosso-pecúlio irei não não permanecerá que nós de-mim para-lavrar para-servir a yhwh Elohim-nosso e-nós não nossa-conhecimento que nos-adoraremos a yhwh até vindo-nos ali');
INSERT INTO verses VALUES (1805, 2, 10, 27, 'e-ele-fortaleceu yhwh a coração Faraó e-não pai para-enviá-los');
INSERT INTO verses VALUES (1806, 2, 10, 28, 'e-ele-disse a-ele Faraó vai de-mim-sobre a-ti para-ti a você-aumentará que face-de porque em-dia-de morrerás face-de morrerás');
INSERT INTO verses VALUES (1807, 2, 10, 29, 'E-disse Moisés assim falaste não ajuntarei ainda ver teu-rosto');
INSERT INTO chapters VALUES (61, 2, 11, 10);
INSERT INTO verses VALUES (1808, 2, 11, 1, 'E-disse yhwh a Moisés ainda um um traria sobre Faraó e-sobre Egito depois-de assim enviará vos deste quando-ele-o-enviar toda expeliu expulsará vós deste-lado');
INSERT INTO verses VALUES (1809, 2, 11, 2, 'diga- por-favor em-orelhas-de o-povo e-eles-perguntarão homem de-junto-de companheiro-seu e-mulher de-junto-de sua-companheira objetos-de prata ouro ouro');
INSERT INTO verses VALUES (1810, 2, 11, 3, 'E-colocou yhwh a favor o-povo em-olhos-de também também o-homem Moisés grande muito em-terra-de Egito em-olhos-de servos-de- Faraó e-no-livro o-povo');
INSERT INTO verses VALUES (1811, 2, 11, 4, 'E-disse Moisés assim disse yhwh meio-da-noite a-noite eu saindo no-meio-de Egito');
INSERT INTO verses VALUES (1812, 2, 11, 5, 'e-morre todo primeiro-nato em-terra-de Egito de-primeiro-nato Faraó o-que-está-sentado até trono-dele até primogênito-de a-escrava que e-tudo os-cheiros animal-doméstico em-primogênito animal');
INSERT INTO verses VALUES (1813, 2, 11, 6, 'e-seja gritaria grande em-todo terra Egito que não não tornou-se não não acrescenta');
INSERT INTO verses VALUES (1814, 2, 11, 7, 'e-para-todo filhos-de Israel não não cão de-sua-língua para-homem e-até animal a-fim-de sabereis que yhwh entre entre e-entre e-entre Israel');
INSERT INTO verses VALUES (1815, 2, 11, 8, 'e-desceram todo Estas estes a-mim dizendo a-mim tu saia tu e-todo o-povo que em-tu-pés e-depois-de assim eu-sairei e-ele-saiu de-com פַּרְעֹה com-seu-escolhido também');
INSERT INTO verses VALUES (1816, 2, 11, 9, 'E-disse yhwh a Moisés não ele-ouvirá a-vós Faraó para-fim-de multidões meus-sinais em-terra-de Egito');
INSERT INTO verses VALUES (1817, 2, 11, 10, 'e-Moshe e-Aharon o-fez-e a todo os-moftim estes diante-de yhwh yhwh a coração Faraó e-não enviou a filhos-de Israel de-a-terra-o');
INSERT INTO chapters VALUES (62, 2, 12, 51);
INSERT INTO verses VALUES (1818, 2, 12, 1, 'E-disse yhwh a Moisés e-a Arão dizendo Egito para-dizer');
INSERT INTO verses VALUES (1819, 2, 12, 2, 'o-hodesh este a-vós cabeça meses resheon ele a-vós le-chadshi ha-shana');
INSERT INTO verses VALUES (1820, 2, 12, 3, 'dabru a todo dizendo Israel dizendo be-asor no-mês a-eles e-eles-tomem para-ela-os homem o-cor-de-cabra para-casa-de os-pais o-cor-de-cabra para-a-casa');
INSERT INTO verses VALUES (1821, 2, 12, 4, 'e-se ele-se-faça-pequeno o-da-casa de-ser e-tome ele ele e-o-seu-vizinho o-próximo a casa-dele em-taxa-de almas homem de-conformidade-com que-o-comessem vocês-tornarão sobre o-cordeiro');
INSERT INTO verses VALUES (1822, 2, 12, 5, 'cordeiro perfeito macho filho-de será a-vós a-vós de os-camurças e-de os-cabritos vocês-tomarão');
INSERT INTO verses VALUES (1823, 2, 12, 6, 'e-será a-vós para-misericórdia até quatro dez dia no-mês este e-sacrificarão ele todo assembleia congregação-de- entre entre os-pardais');
INSERT INTO verses VALUES (1824, 2, 12, 7, 'e-tomarão de o-sangue sobre duas-de as-molduras sobre o-entrante sobre ele que comerão a-ele neles');
INSERT INTO verses VALUES (1825, 2, 12, 8, 'e-comerão a a-carne na-noite esta em-fogão- fogo e-massas sobre amargos o-comerão');
INSERT INTO verses VALUES (1826, 2, 12, 9, 'a nós do-que-ele por-favor e-cozido cozido que porque se em-fogão- fogo cabeça-dele sobre pés-dele e-sobre kirbo');
INSERT INTO verses VALUES (1827, 2, 12, 10, 'e-não nós dele até nós e o que restou de-ele até manhã no fogo serão consumidos');
INSERT INTO verses VALUES (1828, 2, 12, 11, 'e-assim-aqui comereis ele vossas-entranhas cinturados vossos-calçados em-vossos-pés e-vossos-bastões em-mão-vossa e-voces-comeram ele com-pressa Páscoa ele para-יהוה');
INSERT INTO verses VALUES (1829, 2, 12, 12, 'e-passarei em-terra- Egito na-noite deste e-ferrei todo primogênito em-terra-de Egito de-homem e-até animal e-em-todo Elohim-de yhwh fazerei os-julgamentos eu yhwh');
INSERT INTO verses VALUES (1830, 2, 12, 13, 'e-será o-sangue a-vós para-um-sinal sobre as-casas que vós nome e-vi a o-sangue e-passei-para em-voces e-não será em-vos nega-f le-mash-chit be-hak-koti em-terra-de Egito');
INSERT INTO verses VALUES (1831, 2, 12, 14, 'e-será o-dia ha-zeh a-vós le-zich-aron ve-chag-getem ele chag para-יהוה para-gerações-vossas chuq-at eternidade te-chagu-hu');
INSERT INTO verses VALUES (1832, 2, 12, 15, 'shib-aat dias massots tocheleu somente no-dia harishon tashbithu fermento de-vossas-casas que todo comedor azedo e serão cortados a-alma aquela de-Israel desde-dia o-primeiro até dia o-sétimo');
INSERT INTO verses VALUES (1833, 2, 12, 16, 'e-no-dia o-primeiro מִקְרָא־ santidade e-no-dia o-sétimo será a-vós será a-vós todo trabalho não será feito em-elas ele sozinho será comido a-vós alma ele sozinho será feito a-vós');
INSERT INTO verses VALUES (1834, 2, 12, 17, 'e-vós-guardareis a que porque o-dia o-dia esta הוציתי a exércitos-vos da-terra Egito e-vós-guardareis a o-dia eternidade para-gerações-vos chuq-at eternidade');
INSERT INTO verses VALUES (1835, 2, 12, 18, 'no princípio em-quatro dez dia no mês na-atardecer comereis panes pães sem fermento até dia o-primeiro e-vinte no-mês no-o-crepúsculo');
INSERT INTO verses VALUES (1836, 2, 12, 19, 'sete dias סאור não será-encontrada em-vosso que todo comedor fermento e-será-eliminada a-alma aquela da-congregação Israel no-estrangeiro e-no-circunciso a-terra');
INSERT INTO verses VALUES (1837, 2, 12, 20, 'todo não não comereis em-todo móshəvōteḵem comereis matzot:');
INSERT INTO verses VALUES (1838, 2, 12, 21, 'E-chamou Moisés para-todo anciãos-de E-disse E-disse a-eles mis-ku a-vós para-vós rebanho-de le-mish-pach-to-chem ve-sha-chat-u o-passo');
INSERT INTO verses VALUES (1839, 2, 12, 22, 'e-tomareis agud-dat ezob e-tubaltem be-dam que be-saf ve-higashetem a ha-mashqof e-a duas ha-mezuzot de não que be-saf e-vós não tetzau homem mi-petach- casa-dele até manhã');
INSERT INTO verses VALUES (1840, 2, 12, 23, 'e-passou yhwh para-negof a Egito e-verá a ha-dam sobre o-mashqof e-sobre yhwh os-mezuzot e-passeou yhwh sobre o-fetach e-não dará o-mashchit para entrar a em-vossoas-casas para-negof');
INSERT INTO verses VALUES (1841, 2, 12, 24, 'e-vos-guardastes a a-coisa esta por-tempo para-ti e-aos-seus-filhos até eternidade');
INSERT INTO verses VALUES (1842, 2, 12, 25, 'e-será porque vai-vos a a-terra yhwh a-vós yhwh para-vocês como-que palavra e-vós-guardareis a o-trabalho a esta');
INSERT INTO verses VALUES (1843, 2, 12, 26, 'e-será porque eles-dire-ão a-vós filhos-vos que o-trabalho a-vós para-vocês');
INSERT INTO verses VALUES (1844, 2, 12, 27, 'e-disse-reis ofertar- ele ele a-יהוה que Pásca sobre casas-de filhos-de Israel em-Egito negro-seu a Egito e-a nossas-casas e-salvou e ardeu o-povo e-prostraram-se');
INSERT INTO verses VALUES (1845, 2, 12, 28, 'e-caminharam filhos-de Israel como-que ordenou yhwh yhwh Moisés e-Aarão assim fizeram');
INSERT INTO verses VALUES (1846, 2, 12, 29, 'e-houve em-meio a-noite e-yhwh bateu todo primeiro-nato em-terra-de Egito de-a-primeira Faraó o-que-está-sentado sobre até até primogênito-de o-exilado que em-casa-de e-tudo e-todo animal-doméstico animal');
INSERT INTO verses VALUES (1847, 2, 12, 30, 'E-levantou פרעה noite ele e-todo seus-servos e-todo Egito e-foi gritaria grande em-Egito porque não-há casa que não há nome morreu');
INSERT INTO verses VALUES (1848, 2, 12, 31, 'E-chamou para-Moshe e-para-Aaron noite E-disse levantem-se saiam de-meio-de povo-meu também vós também filhos-de Israel e-vão servi a yhwh para-falar-vos');
INSERT INTO verses VALUES (1849, 2, 12, 32, 'também rebanho-vos também em-vosso-boi tomem como-que falastes e-andei e-bendistes também de-mim');
INSERT INTO verses VALUES (1850, 2, 12, 33, 'ela fortaleceu-se Mitzrayim sobre o-povo para-pressa para-guerra que a-terra porque disseram-eles todos-nós mortos');
INSERT INTO verses VALUES (1851, 2, 12, 34, 'e-levantou o-povo a ainda-não antes-de que-se-farte de-seus-restos enroladas em-suas-vestes sobre de-seus-lombos');
INSERT INTO verses VALUES (1852, 2, 12, 35, 'e-filhos-de Israel fizeram conforme-a-palavra-de Moisés e-perguntaram do-Egito objetos-de ouro e-vessãis ouro e-vestes');
INSERT INTO verses VALUES (1853, 2, 12, 36, 'E yhwh dar a favor o-povo em-olhos-de Egito e perguntaram-lhes e tiraram a Egito');
INSERT INTO verses VALUES (1854, 2, 12, 37, 'E-OS-ELES-SAIRAM filhos-de Israel de-ruamess sukkotá c''shesh- centenas mil pé os-hagbarim apenas mancha:');
INSERT INTO verses VALUES (1855, 2, 12, 38, 'e-também tarde subir subiu com-eles e-rebanhos e-gado do-rebanho muito muito');
INSERT INTO verses VALUES (1856, 2, 12, 39, 'e-fizeram-assar a o-pão que extrairam de-o-Egito pães-de-forma que não não fermentado porque forçaram desde-Mitsrayim e-não puderam para-se-demorar a-eles justiça não fizeram para-eles');
INSERT INTO verses VALUES (1857, 2, 12, 40, 'e-moshab filhos-de Israel que habitaram em-Egito trinta ano e-quatro centenas anos');
INSERT INTO verses VALUES (1858, 2, 12, 41, 'e-houve de-fim trinta ano e-quatro centenas ano e-houve [בְּעֶ֙צֶם֙] o-dia esta todo tzivot yhwh de-terra-de Egito');
INSERT INTO verses VALUES (1859, 2, 12, 42, 'noite de-shimurim ele a-yhwh לְהוֹצִיאָ֖ם da-terra Egito ele noite o-este a-yhwh de-shimurim para-todo filhos-de Israel para-gerações-eles');
INSERT INTO verses VALUES (1860, 2, 12, 43, 'E-disse yhwh a Moisés esta esta lei o-pascha todo filho-de נֵכָ֖ר נֶכְרָה não comerá em-ele');
INSERT INTO verses VALUES (1861, 2, 12, 44, 'e-todo servo homem de-aquisição- ele e-teceu a-ele então ele-comerá em-ele');
INSERT INTO verses VALUES (1862, 2, 12, 45, 'estrangeiro vesakir não ele-comerá- em-ele');
INSERT INTO verses VALUES (1863, 2, 12, 46, 'em-casa um e-o-eche-le não tirar de a-casa de não fora e-ossos não vocês-partirão- nele-verso');
INSERT INTO verses VALUES (1864, 2, 12, 47, 'todo עֲדַ֥ת Israel ele a-ele');
INSERT INTO verses VALUES (1865, 2, 12, 48, 'e-quando Yagur contigo ger ואsha Pesach para-יהוה a-ele a-ele todo macho ve-az se-aproximará la-asoto a-terra ke-ezrach a-terra e-todo arel não yochal em-ele');
INSERT INTO verses VALUES (1866, 2, 12, 49, 'lei uma será la-ezrach e para o estrangeiro הַגָּ֥ר בְּתוֹכְכֶֽם׃');
INSERT INTO verses VALUES (1867, 2, 12, 50, 'va-yasu todo filhos-de Israel como-que yhwh yhwh a Moisés e-com אַהֲרֹן assim fizeram');
INSERT INTO verses VALUES (1868, 2, 12, 51, 'e-houve בְּעֶ֖צֶם o-dia esta tire-ou yhwh a filhos-de Israel de-terra-de Egito sobre exércitos-deles-verso');
INSERT INTO chapters VALUES (63, 2, 13, 22);
INSERT INTO verses VALUES (1869, 2, 13, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (1870, 2, 13, 2, 'santo-de para-mim todo primogênito pedra-da todo ventre-o e-sobre-os-animais Israel ele e-no-animal para-mim ela');
INSERT INTO verses VALUES (1871, 2, 13, 3, 'E-disse Moisés a o povo lembra-te a o-dia o-este que sai-vos de-Egito que escravos mão be-chozek mão tire-ou yhwh vos deste e-não será comido azedo-o');
INSERT INTO verses VALUES (1872, 2, 13, 4, 'o-dia vós sain-do em-o-mês o-primavera');
INSERT INTO verses VALUES (1873, 2, 13, 5, 'e-foi porque yhwh yhwh a terra o-canaanita e-o-het e-o-amorreu e-o-hivite e-o-jebuseu que jura-vou para-ti terra para-ti terra fluindo-de leite e-mel e-servirás a o-trabalho a-esta no mês- a-esta');
INSERT INTO verses VALUES (1874, 2, 13, 6, 'sete dias comerás de-mazze e-no-dia o-sétimo festa a-yhwh');
INSERT INTO verses VALUES (1875, 2, 13, 7, 'massas-de-farinha yeakhel a sete os-dias e-não a-ti a ti fermentado a-ti será-visto para-ti fermento em-todo גְּבֻלֶֽךָ׃');
INSERT INTO verses VALUES (1876, 2, 13, 8, 'e-contarás para-o-seu-filho no-dia aquele dizendo por-causa-de este fez yhwh a-mim na-saída-meu de-Egito');
INSERT INTO verses VALUES (1877, 2, 13, 9, 'e-será a-ti por-sinal sobre da-tua-mão entre entre os olhos para-que ser-ás yhwh yhwh que porque com a mão forte extrair-te yhwh de-Egito');
INSERT INTO verses VALUES (1878, 2, 13, 10, 'e-guardarás a a-regulação esta para-a-sua-festa de-dias dia-e-noite');
INSERT INTO verses VALUES (1879, 2, 13, 11, 'e-será porque yhwh yhwh a terra o-kenaani a-ti jurou a-ti para-ti e-dar-a para-ti');
INSERT INTO verses VALUES (1880, 2, 13, 12, 'e-passarás todo primeiro-de ventre a-יהוה e-todo animal-doméstico seger será a-ti será para-ti ha-zkharyim para-יהוה');
INSERT INTO verses VALUES (1881, 2, 13, 13, 'e-todo peter chomer resgatar-ás bobo-she e-se não e-tudo e-arpo-to homem em-primogênito homem be-banecha tífdeh');
INSERT INTO verses VALUES (1882, 2, 13, 14, 'e-será porque yishalheka bincha dizendo Leomar que a-ele e-dirás mão be-chozek yhwh hotzi-anu yhwh de-misraim de-casa-de servos');
INSERT INTO verses VALUES (1883, 2, 13, 15, 'e-houve porque hiqsha Paro- para-enviar-nos- e-matou yhwh todo primogênito em-terra-de homem de-primeira animal-doméstico e-até primogênito-de animal sobre assim eu que-sacrifica a-יהוה todo a-pomba o-útero os-masculinos e-todo em-primogênito filhos-de eu-redimir-eu');
INSERT INTO verses VALUES (1884, 2, 13, 16, 'e-era para-sinal sobre sua-mão entre entre que porque mão mão yhwh yhwh de-Egito');
INSERT INTO verses VALUES (1885, 2, 13, 17, 'e-houve em-enviarmos פרעה a o-povo e-não o-caminho-de terra caminho que filisteus ele que ele disse disse Elohim para-que-não ינחם o-povo בראותם guerra ושבו Míseremah');
INSERT INTO verses VALUES (1886, 2, 13, 18, 'ויסוב Elohim a o-povo o-caminho-de o deserto mar-de סוף וחמושים subiram filhos-de Israel dizendo Egito');
INSERT INTO verses VALUES (1887, 2, 13, 19, 'E-tomou Moisés a עצמות José que porque השבע השביע a dizendo Israel dizendo פָּקֹ֨ד יִפְקֹ֤ד Elohim vos וְהַעֲלִיתֶ֧ם a עַצְמֹתַ֛י de-este אִתְּכֶֽם׃');
INSERT INTO verses VALUES (1888, 2, 13, 20, 'e-partiram de-tendas e-acamparam com-eles em-extremidade-de o-meadero');
INSERT INTO verses VALUES (1889, 2, 13, 21, 'e-יהוה andou em-frente-de-eles dia em-amostra nuvem para-acampar-eles o-caminho e-o-noite em-a-coluna fogo para-iluminar a-eles para-andar de-dia e-noite');
INSERT INTO verses VALUES (1890, 2, 13, 22, 'não ele-se-move coluna o-nuvem diariamente e-coluna noite noite diante-de o-povo');
INSERT INTO chapters VALUES (64, 2, 14, 31);
INSERT INTO verses VALUES (1891, 2, 14, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (1892, 2, 14, 2, 'palavra a filhos-de Israel e-eles-voltam-se e-acamparão diante-de boca-de entre entre e-entre o-mar ha-yam diante-de בַּ֣עַל norte em-seu acamparam sobre o-mar:');
INSERT INTO verses VALUES (1893, 2, 14, 3, 'e-disse Faraó aos-filhos-de Israel estavam-confusos eles em-a-terra fechar sobre-eles o-meadero');
INSERT INTO verses VALUES (1894, 2, 14, 4, 'e-forte-eu-tornarei a coração-de Pharaoh e-perseguiu depois-deles e-exaltarei em-Pharaoh e-em-todo חֵיל֔וֹ yhwh Egito porque eu yhwh e-fizeram assim');
INSERT INTO verses VALUES (1895, 2, 14, 5, 'e-foi-dito como-rei Egito que correu o-povo e-virou-se para-o-coracao  פרעה e-de-sus-servos a o-povo e-disseram que isto fizemos porque enviamos-nos a Israel de-sus-servos');
INSERT INTO verses VALUES (1896, 2, 14, 6, 'e-ajuntou-se a seu-carro tomou amav tomou com-ele-verso');
INSERT INTO verses VALUES (1897, 2, 14, 7, 'E-tomou seis-de centenas רֶ֙כֶב֙ e-tudo e-todo carros Egito e-os-príncipes sobre tudo-o');
INSERT INTO verses VALUES (1898, 2, 14, 8, 'e-ele-fortaleceu yhwh a coração Faraó rei Egito e-ele-perseguiu depois-de filhos-de Israel e-filhos-de Israel יֹצְאִים com-mão subiu');
INSERT INTO verses VALUES (1899, 2, 14, 9, 'e perseguiram Egito depois-deles e-os-atingiram elas os-acampamentos sobre o-mar todo סוּס֙ carros Faraó -e-sua-parasha e-o-exército-seu sobre boca-minha as-chiros diante-de Baal norte');
INSERT INTO verses VALUES (1900, 2, 14, 10, 'e-Pharaoh ofereceu e-ele-levantaram filhos-de Israel a os-seus-olhos e-eis do-Egito viajando depois-deles muito muito e-clamaram filhos-de Israel a yhwh');
INSERT INTO verses VALUES (1901, 2, 14, 11, 'e-disseram a Moisés a-por-não não-há túmulos em-Egito para tomarmos para morrermos no-deserto que isto fizeste tu para nos levarmos de-Egito');
INSERT INTO verses VALUES (1902, 2, 14, 12, 'não-é este a-palavra que falamos a-você dizendo dizendo nós dele e-nos-adoraremos que bom porque bom a-nós servo a Egito de-morte-nossa no-deserto');
INSERT INTO verses VALUES (1903, 2, 14, 13, 'E-disse Moisés a o-povo a v-trepareis h-vos-posicionareis yhwh a a-vós o-dia que ele-fará para-vocês o-dia o-dia não v-vistes a Mitzrayim o-dia não a-som-brevariais para-ver-los mais até eternidade');
INSERT INTO verses VALUES (1904, 2, 14, 14, 'yhwh lutará a-vós e-vós v-calareis-vos');
INSERT INTO verses VALUES (1905, 2, 14, 15, 'E-disse yhwh a Moisés que v-gritarais a-mim palavra a filhos-de Israel e-eles-partirão-verso');
INSERT INTO verses VALUES (1906, 2, 14, 16, 'e-tu elevem a a-tua-mata e-estenda a yadcha sobre o-mar no-meio-de o-mar filhos-de Israel em-meio-de o-mar na-terra-firmada-verso');
INSERT INTO verses VALUES (1907, 2, 14, 17, 'e-eu eis-me e fortaleça a coração Egito e venham apos-eles e seja respeitada perante Faraó e-em-todo seu exército em-suas-carretas e-em-seus-cavalos');
INSERT INTO verses VALUES (1908, 2, 14, 18, 'e conhecerão Egito porque yhwh yhwh em-a-honra-dele em-faraó em-seu-cavalo e-em-sus-cavalos');
INSERT INTO verses VALUES (1909, 2, 14, 19, 'e-partiu anjo os-Elohim o-que-vai diante-de acampamento-de Israel E-andou de-após-eles e-partiu coluna da-névoa de-diante-deles e-parou de-eles');
INSERT INTO verses VALUES (1910, 2, 14, 20, 'E-veio entre acampamento-de Egito e-entre e-entre Israel E-foi e-houve e-o-trevas e-ele-iluminou a a-noite e-não se-achegou este a este todo a-noite');
INSERT INTO verses VALUES (1911, 2, 14, 21, 'e-ele-esticou Moisés a mão-sua sobre yhwh e-ele-conduziu יהוה a o-mar com-vento do-norte Azza- todo a-noite e-colocou as-águas o-mar para-o-deserto e-eles-partiram as-águas');
INSERT INTO verses VALUES (1912, 2, 14, 22, 'e chegaram a filhos-de no-meio-de o-mar o-mar em-a-terra-firmo a-eles a-eles a-muralha de-seu-lado-direito e-de-seu-lado-esquerdo');
INSERT INTO verses VALUES (1913, 2, 14, 23, 'e-eles-perseguiram Egito e-vieram de-elles todo sus Faraó rikbo- e-seus-cavaleiros a o-mar o-mar:');
INSERT INTO verses VALUES (1914, 2, 14, 24, 'e-houve em-Ashmorah a-manhã e-ele-olhou yhwh a acampamento-de Egito em-a-coluna fogo e-nuvem e-ele-se-alçou a acampamento-de Egito');
INSERT INTO verses VALUES (1915, 2, 14, 25, 'e-ele-se-retirou a roda de-sua-marcos e-ele-o-conduziu com-dificuldade E-disse Egito forçadamente de-diante-de Israel que yhwh lutou a-eles com-Egito');
INSERT INTO verses VALUES (1916, 2, 14, 26, 'E-disse yhwh a Moisés estende a mão-tua sobre ha-yam e-voltarão as-águas sobre Egito sobre rikbo- e-sobre os-parashim');
INSERT INTO verses VALUES (1917, 2, 14, 27, 'e-ele-inclinou-se Moisés a mão-sua sobre o-mar e voltou manhã em-frente manhã para-o-eitan e-Misraim nós-sairemos yhwh e-estremeu no-meio-de o-mar Egito em-meio-de o-mar:');
INSERT INTO verses VALUES (1918, 2, 14, 28, 'e-voltaram as-águas e-cobriram a o-carro a-todo os-parashim para-todo força Faraó os-que-vêm atrás-de-eles no-mar não permaneceu neles até um');
INSERT INTO verses VALUES (1919, 2, 14, 29, 'e-filhos-de Israel andaram na-terra no-meio-de o-mar e-os-água a-eles muralha de-seu-direito e-de-seu-esquerdo');
INSERT INTO verses VALUES (1920, 2, 14, 30, 'e-Yoshua yhwh no-dia a-esse a Israel de-mão-de E-viu E-viu Israel a Egito o-mar sobre beira-de o-mar:');
INSERT INTO verses VALUES (1921, 2, 14, 31, 'E-viu Israel a a-mão a-grande que yhwh yhwh em-Egito e-eles-tremeliram o-povo a yhwh e-eles-crederam em-יהוה e-em-Moshe seu-servo');
INSERT INTO chapters VALUES (65, 2, 15, 27);
INSERT INTO verses VALUES (1922, 2, 15, 1, 'então cantei Moisés e filhos-de Israel a a canção esta dizendo e-disseram dizendo eu canto para yhwh porque orgulho arrogância cavalo e seu cavaleiro Rama no mar:');
INSERT INTO verses VALUES (1923, 2, 15, 2, 'minha-forteza e-cantares-meu Yah e-foi a-mim li-yeshuah este meu-elohim e-anvehu Elohim-de pai-meu va-arommenhuhu');
INSERT INTO verses VALUES (1924, 2, 15, 3, 'yhwh homem guerra yhwh nome-dele');
INSERT INTO verses VALUES (1925, 2, 15, 4, 'marckhot Pharaoh ve-chilo yarah bayam umibhar shalishav tubbu beyam- juncos');
INSERT INTO verses VALUES (1926, 2, 15, 5, 'fundos os-cobri-los desceram em-garras como pedra:');
INSERT INTO verses VALUES (1927, 2, 15, 6, 'yeminecha yhwh santo com-poder teu-direito yhwh terrifica inimigo:');
INSERT INTO verses VALUES (1928, 2, 15, 7, 'E-POR-MUITOS a-tua-altitude destruirás teus-inimigos lançará teu-ira o-comerá como-cinzas');
INSERT INTO verses VALUES (1929, 2, 15, 8, 'e-no-espírito teu-rosto foram-envolvidos águas estabeleceram-se כְמוֹ־ derretidos correndo congela-o abismos בְּלֶב־ mar-');
INSERT INTO verses VALUES (1930, 2, 15, 9, 'disse inimigo eu-perseguirei seguirei-o dividirei despojos os-encherá nafshi espalharei espada-meu torresmo-seu minha-mão:');
INSERT INTO verses VALUES (1931, 2, 15, 10, 'raspou-você em-vento-teu e-o-ocultaste mar mergulharam-eles como-ferro em-agua majestosos-eles');
INSERT INTO verses VALUES (1932, 2, 15, 11, 'quem kamoka yhwh quem quem como dedicado no santuário assustador hinos fez milagres:');
INSERT INTO verses VALUES (1933, 2, 15, 12, 'tu estendeste a tua mão direita os engoliu terra');
INSERT INTO verses VALUES (1934, 2, 15, 13, 'tu lançaste por tua misericórdia com ז֣וּ resgataste levaste pela tua força a morada Sua santidade:');
INSERT INTO verses VALUES (1935, 2, 15, 14, 'ouçam povo-es tremem terror agarrado habitantes-de fesliteiros');
INSERT INTO verses VALUES (1936, 2, 15, 15, 'então se-espantaram chefes-de Edom de-cervos Moabe tomá-los terremoto derretem-se todo habitantes-de Canaan');
INSERT INTO verses VALUES (1937, 2, 15, 16, 'caia em-eles terror e-pavor grande braço-tua se-fazerão como-a-pedra até passará yhwh yhwh até passará com ז֥וּ compraste-tu');
INSERT INTO verses VALUES (1938, 2, 15, 17, 'introduzirás-os e-plantarás-os em-monte-de herança-tua lugar para-a-sua-estadia tu-fizeste yhwh do-sanctuário Adonai estabeleceram יָדֶֽיךָ׃');
INSERT INTO verses VALUES (1939, 2, 15, 18, 'yhwh ele-reinará para-sempre para-sempre');
INSERT INTO verses VALUES (1940, 2, 15, 19, 'que veio cavalo פרעה em-o-sua-carroagem e-em-seus-cavalos no-mar e-estabeleceu-se yhwh sobre-eles a o-mar ha-yam e-filhos-de Israel andaram no-meio-de o-mar o-mar:');
INSERT INTO verses VALUES (1941, 2, 15, 20, 'e-tomou Miriam a nebiya a-irmã de-Aaron a o-tamborim em-mã e-saiu-a todo as-mulheres depois-dela em-tumpos e-no-maioles');
INSERT INTO verses VALUES (1942, 2, 15, 21, 'e-respondeu-a a-eles Miriam cantem para-יהוה porque elevado-o exultou-a ס֥וּס e-seu-cavaleiro elevada-a no-mar-verso-final');
INSERT INTO verses VALUES (1943, 2, 15, 22, 'e-partiu-ele-se Moisés a Israel מִיַּם- Suf e-saíram a no deserto- Shur e-foram três- יָמִ֛ים em-o-midbar e-não encontraram-os águas');
INSERT INTO verses VALUES (1944, 2, 15, 23, 'e-vieram amarada-a e-não puderam para-beber-ele águas de-amarado-o que amaros eles sobre assim קָרָֽא־ shema-ha- amara');
INSERT INTO verses VALUES (1945, 2, 15, 24, 'e-ele-queixou-se o-povo sobre Moisés dizendo que- nós-beberemos');
INSERT INTO verses VALUES (1946, 2, 15, 25, 'e-ele-gritou a yhwh yhwh árvore madeira e lançou a as-águas e-eles-deram-doçura as-águas a-ele nome para-ele חֹ֥ק וּמִשְׁפָּ֖ט e ali ele-o-provou');
INSERT INTO verses VALUES (1947, 2, 15, 26, 'E-disse se audição à-voz-de לְקוֹל yhwh Elohim-teus e-o-retirado em-o-sus farás e-a-ouves para-as-mandamentos-seus e-guardas todo os-preceitos-seus todo a-doença que eu-postei que não yhwh sobre-ti porque eu yhwh te-curador');
INSERT INTO verses VALUES (1948, 2, 15, 27, 'e-vieram o-que-dizem e ali dois dez olhos águas e-setenta tamareiros e-acamparam- nome sobre as-águas');
INSERT INTO chapters VALUES (66, 2, 16, 36);
INSERT INTO verses VALUES (1949, 2, 16, 1, 'e-eles-partiram de-eilim e-vieram todo congregação-de filhos-de Israel a e-entre sin que entre dia e-entre Si-na-y בַּחֲמִשֹּׁ֨ה dez dia para-o-mês o-segundo para-saírem de-terra-de Egito');
INSERT INTO verses VALUES (1950, 2, 16, 2, 'todo congregação-de filhos-de Israel sobre Moisés e-sobre אַהֲרֹן no-deserto');
INSERT INTO verses VALUES (1951, 2, 16, 3, 'e-disseram a-para-eles filhos-de Israel quem יִתֵּן morrer-nos por-mão-de- yhwh em-terra-de Egito em-nossa-sentença sobre pão a-carne em-comer-nos pão para serdes saciados porque saiestes nós a o-deserto esta para-matar a todo הַקָּהָ֥ל este bar''ava:');
INSERT INTO verses VALUES (1952, 2, 16, 4, 'E-disse yhwh a Moisés eis-me a-vós pão pão de os-céus e-sairá o-povo e-las-recolham palavra-de dia be-yomo- para-propósito-de forçadamente-o se-andará em-a-lei-meu se não');
INSERT INTO verses VALUES (1953, 2, 16, 5, 'e-foi no-dia o-sexto e-eles-prepararão a que trará-os e-foi sobre sobre dia recolherão dia dia');
INSERT INTO verses VALUES (1954, 2, 16, 6, 'E-disse Moisés e-Aarão a todo tarde Israel que yhwh porque yhwh saírei vos de-terra-de Egito');
INSERT INTO verses VALUES (1955, 2, 16, 7, 'e-manhã e-vós-ver-eis a yhwh yhwh em-a-ouvido-seu a queixas-vos sobre que e-nós o-que porque sobre-nós');
INSERT INTO verses VALUES (1956, 2, 16, 8, 'E-disse Moisés deitando-se yhwh a-vós na-noite em-a-carne para-comer e-pão na-manhã para-satisfazer em-ouvir yhwh a queixas-vos que vós מַלִּינִ֖ם sobre-ele e-nós o-que que sobre nós vossas-reclamações porque sobre yhwh');
INSERT INTO verses VALUES (1957, 2, 16, 9, 'E-disse Moisés a Arão disse a todo a congregação filhos-de yhwh que diante-de yhwh porque ouviu a vossas-reclamações-verso-final');
INSERT INTO verses VALUES (1958, 2, 16, 10, 'e-houve כְּדַבֵּ֤ר Arão a todo congregação-de filhos-de Israel e-voltaram-se yhwh a-deserto e-eis glória-de yhwh apareceu em-a-nuvem');
INSERT INTO verses VALUES (1959, 2, 16, 11, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (1960, 2, 16, 12, 'ouvi a reclamações filhos-de Israel palavra dizendo entre entre os-araviãs comereis carne e-no-manhã vocês-se-satisfarão- que e saberéis yhwh eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (1961, 2, 16, 13, 'e-houve na-noite e-ele-subiu a-súplica e-ela-cobriu a o-acampamento era foi de-a-decepção do-ora ao-redor o-lager');
INSERT INTO verses VALUES (1962, 2, 16, 14, 'e subiu a escabecim o tal e-eis sobre face-de o deserto fino espalhado fino como uma tampa sobre a-terra');
INSERT INTO verses VALUES (1963, 2, 16, 15, 'e viram filhos-de Israel e-disseram homem a ele que não porque não E-disse que ele ele Moisés a-eles dar yhwh a-vós para-alimento yhwh a-vós para-alimento');
INSERT INTO verses VALUES (1964, 2, 16, 16, 'este a-palavra que ordenou yhwh líquto nós homem de-conformidade-com áklo ómer lagulgoléth de-número nafshetékhem homem láasher em-o-seu-tenda vocês-tomarão');
INSERT INTO verses VALUES (1965, 2, 16, 17, 'e-fizeram assim filhos-de Israel e-eles-colheram o-muito e-o-pouco');
INSERT INTO verses VALUES (1966, 2, 16, 18, 'e-eles-mediram em-o-omeron e-não o-preferiu o-muito e-o-pouco não o-faltou homem de-a a-co-lo l-a-q-t-u');
INSERT INTO verses VALUES (1967, 2, 16, 19, 'E-disse Moisés a-eles homem a nós dele até manhã');
INSERT INTO verses VALUES (1968, 2, 16, 20, 'e-não ouviu a Moisés nós homens do-que-ele até manhã v-y-r-u-m t-o-l-a-ay-im v-y-b-a-sh e-ira-se sobre-eles Moisés');
INSERT INTO verses VALUES (1969, 2, 16, 21, 'e recolheram ele ba-voker de-manhã homem cada que eles começassem a comer e quente o-sol e tocou');
INSERT INTO verses VALUES (1970, 2, 16, 22, 'e-houve em-o-dia no-dia l-a-q-t-u pão pão segundo o-omem para-o-um e-vieram todo príncipes-de a-congregação e-eles-disseram para-Moisés');
INSERT INTO verses VALUES (1971, 2, 16, 23, 'E-disse a-eles ele que palavra yhwh Sabbaton Sabbat- Kodesh a-yhwh amanhã- a que t''afu eifu e-a que- t''bashelu b''shulu a-vós todo ha''odef הַנִּ֧יחוּ yhwh para-de-guarda até a-manhã');
INSERT INTO verses VALUES (1972, 2, 16, 24, 'e-os-colocaram ele até a-manhã conforme ordenou Moisés e-não o-ameaçado e-ulceração não ela-foi em-ele');
INSERT INTO verses VALUES (1973, 2, 16, 25, 'E-disse Moisés comê-lo o-dia porque o-dia o-dia o-dia não não encontrar-no no-campo');
INSERT INTO verses VALUES (1974, 2, 16, 26, 'seis-de dias recolham-no e-no-dia o-setimo sabáth não ele-será- em-ele');
INSERT INTO verses VALUES (1975, 2, 16, 27, 'e-aconteceu no-dia o-sétimo saíram de o-povo para-coletar e-não acharam');
INSERT INTO verses VALUES (1976, 2, 16, 28, 'E-disse yhwh a Moisés até a-onde de-voces לשמור as-minhas-mandamentos e-de-mim-leis');
INSERT INTO verses VALUES (1977, 2, 16, 29, 'olhem porque dar a-vós para-vós o sétimo ele assim a-vós no-dia a-vós pão o-sexto pão dias descanse homem em-lugar-dele a sairá no-dia de seu lugar no-dia o sétimo');
INSERT INTO verses VALUES (1978, 2, 16, 30, 'e-eles-assentaram-se o-povo no-dia o-sétimo');
INSERT INTO verses VALUES (1979, 2, 16, 31, 'e-eles-chamaram casa-de Israel a nome-de-ele de e-ele como-semente gad la-van e-o-sabor como-de-espuma com-mel');
INSERT INTO verses VALUES (1980, 2, 16, 32, 'E-disse Moisés este a-palavra que ordenou yhwh enchei o-omer nós para-de-guarda para-gerações-de-vocês para-a-cau-sa-de e-verão a o pão que eu-eu-comi vos no-deserto בּוֹחֲצִיעַי vos de-terra-de Egito');
INSERT INTO verses VALUES (1981, 2, 16, 33, 'E-disse Moisés a Arão qach uma uma e-tenha lá cheio-de ele de yhwh ele diante-de yhwh para-de-guarda para-gerações-de-vocês');
INSERT INTO verses VALUES (1982, 2, 16, 34, 'como ordenou yhwh a Moisés e-ele-o-colocou de-Aaron diante-de da-testemunho para-guarda');
INSERT INTO verses VALUES (1983, 2, 16, 35, 'e-filhos-de Israel comam a o-ma-nãh quarenta ano até deles-os a terra morando-a a terra comeram-e até deles-os a fim-o terra כְּנָֽעַן');
INSERT INTO verses VALUES (1984, 2, 16, 36, 'e-a-omer décima-a a-árvore ele');
INSERT INTO chapters VALUES (67, 2, 17, 16);
INSERT INTO verses VALUES (1985, 2, 17, 1, 'e-partiram-e todo assembleia-a filhos-de Israel do-midbar- yhwh lemaseihem sobre boca-de águas e-acamparam em-Rפידים e-não-há águas para-beber-ele o-povo');
INSERT INTO verses VALUES (1986, 2, 17, 2, 'e-estava-cheio o-povo com Moisés e-disseram águas para-nós E-disse a-eles E-disse para-eles comigo que a-multidão comigo que- vocês-experimentarão a yhwh');
INSERT INTO verses VALUES (1987, 2, 17, 3, 'e se-desejava nome o-povo água e desfaleceu o-povo sobre E-disse E-disse por-que isto vocês nos levantaste do-Egito para matar de-mim-me e-a filhos-de e-a minha posse no deserto');
INSERT INTO verses VALUES (1988, 2, 17, 4, 'e-clamou Moisés a dizendo dizendo que eu-farei ao-povo esta ainda pouco e-apedreje-me');
INSERT INTO verses VALUES (1989, 2, 17, 5, 'E-disse yhwh a Moisés passagem diante-de o-povo e-toma contigo מִזִּקְנֵי Israel e-mat-teu que golpeaste em-ele a o-rio pe-go em-a-mão-tua e-andaste');
INSERT INTO verses VALUES (1990, 2, 17, 6, 'eis-me ficou-em-pé para-diante-tu ali sobre o-saliente em-Horebe e atingirás na-rocha e saíram nós águas e-bebeste o-povo E-fez assim Moisés aos-olhos-de anciãos-de Israel');
INSERT INTO verses VALUES (1991, 2, 17, 7, 'E-chamou nome o-lugar massá e-mrívah sobre riv filhos-de Israel e-sobre nasstam a dizendo dizendo yhwh yhwh b-qirbbenuv se não.');
INSERT INTO verses VALUES (1992, 2, 17, 8, 'E-veio עֲמָלֵק e lutou com Israel birfidim');
INSERT INTO verses VALUES (1993, 2, 17, 9, 'E-disse Moisés a יְהוֹשֻׁעַ בְּחַר- lanu homens ve-tsé [מָחָ֗ר] eu amanhã eu-sou estava de pé sobre cabeça das colinas ומטה Elohim BYADHI:');
INSERT INTO verses VALUES (1994, 2, 17, 10, 'E-fez Josué como-que palavras-de a-ele Moisés para-lutar ba-amalek umoshe Aarão e-Hur subiram cabeça a montanha;');
INSERT INTO verses VALUES (1995, 2, 17, 11, 'e-foi como-que ele-elevará Moisés sua-mão e-sejusgado Israel vekaʾasher ele-descansará sua-mão e-sejusgado Amaleque');
INSERT INTO verses VALUES (1996, 2, 17, 12, 'e-mãos-de Moisés pesados e-eles-tomaram- pedra e-os-colocaram abaixo-dele e-sentou sobre-ela e-Aharon e-Hur tamechu be-yadaiv um um um e-houve E-foi suas mãos Emuna até veio o-sol');
INSERT INTO verses VALUES (1997, 2, 17, 13, 've-ya-chalosh יְהוֹשֻׁעַ a Amalek e-a amav à-boca-de com-espada');
INSERT INTO verses VALUES (1998, 2, 17, 14, 'E-disse yhwh a Moisés esta esta zikaron no-livro veshim em-orelhas-de Yehoshua porque maho eu-apagarei debaixo-de macho Amaleque de-debaixo-de os-céus');
INSERT INTO verses VALUES (1999, 2, 17, 15, 'E-edificou Moisés מִזְבֵּ֑חַ E-chamou seu-nome yhwh dele-é');
INSERT INTO verses VALUES (2000, 2, 17, 16, 'E-disse porque mão sobre trono Yah guerra a-yhwh contra-Amaleque geração geração');
INSERT INTO chapters VALUES (68, 2, 18, 27);
INSERT INTO verses VALUES (2001, 2, 18, 1, 'E-ouviu de-Jetro sacerdote Midiã cons- sogro Moisés a todo que fez Elohim לְמֹשֶׁ֔ה e-a-israel povo-seu yhwh tire-ou yhwh a Israel de-Egito');
INSERT INTO verses VALUES (2002, 2, 18, 2, 'E-tomou Jetro cons- sogro Moisés a Tsipora mulher-de Moisés depois seus-enviados');
INSERT INTO verses VALUES (2003, 2, 18, 3, 'e-a segundo be-ne-ha que nome o-primeiro ger-shom que disse forasteiro eu-fui em-terra-de estranha');
INSERT INTO verses VALUES (2004, 2, 18, 4, 'e-nome-de o-primeiro Eleazar porque Elohim-de pai-meu no auxílio e me resgatou de espada פַּרְעֹה');
INSERT INTO verses VALUES (2005, 2, 18, 5, 'E-veio yit-ro cho-ten Moisés u-ba-na-vau e-esposa-dele a Moisés a o-deserto que ele cho-ne nome monte-de Elohim');
INSERT INTO verses VALUES (2006, 2, 18, 6, 'E-disse a Moisés eu seu cunhado Jetro veio a-ti e sua mulher e-dois-de com-ela com ela:');
INSERT INTO verses VALUES (2007, 2, 18, 7, 'e-saiu Moisés ao-encontro-de sogro-seu e-abaixou-se e-beijou- a-ele e perguntaram homem-de para-o-amigo-seu para-paz e-vieram a-tenda');
INSERT INTO verses VALUES (2008, 2, 18, 8, 'e-disse Moisés para-o-cunhado-seu את todo que yhwh yhwh para-Pharaoh sobre sobre odeiras Israel a todo a-maldição que encontraram-seu yhwh e-ele-salvou-os yhwh');
INSERT INTO verses VALUES (2009, 2, 18, 9, 'e uniu-os Jetro sobre todo a-boa yhwh fez yhwh a Israel que resgatou-o de-mão-de Egito');
INSERT INTO verses VALUES (2010, 2, 18, 10, 'E-disse Jetro bendito yhwh que salvou a-vós de-mão-de Egito e-de-mão-de Faraó que resgatou a debaixo-de de-debaixo-de mão-de Egito');
INSERT INTO verses VALUES (2011, 2, 18, 11, 'agora soube porque yhwh yhwh que o-Elohim porque badavar que zadu sobre-eles');
INSERT INTO verses VALUES (2012, 2, 18, 12, 'E-tomou Yitro choten Moisés holocausto uzvachim para-אלהים E-veio Arão e-tudo anciãos-de Israel para comer pão com choten Moisés diante-de Elohim');
INSERT INTO verses VALUES (2013, 2, 18, 13, 'e-houve de-amanhã e-habitou Moisés para-julgar a o-povo e-ele-estabeleceu o-povo sobre Moisés de o-amanhecer até no entardecer');
INSERT INTO verses VALUES (2014, 2, 18, 14, 'E-viu cons- sogro Moisés a todo que ele E-disse para-o-povo E-disse que tu o-este que tu tu para-o-povo madua'' tu habitante- apenas contigo e-todo o-povo stood sobre-ti de manhã até tarde');
INSERT INTO verses VALUES (2015, 2, 18, 15, 'E-disse Moisés para-o-sogro porque virá a-mim o-povo para-buscar Elohim');
INSERT INTO verses VALUES (2016, 2, 18, 16, 'porque a-eles para-eles palavra veio a-mim entre entre e-entre e-entre companheiro-seu e-anunciarei a de-leis Elohim e-a das-sua-ordens');
INSERT INTO verses VALUES (2017, 2, 18, 17, 'E-disse o-sogro Moisés a-ele não bom a-palavra tu tu fez');
INSERT INTO verses VALUES (2018, 2, 18, 18, 'a-decayimento você-decaina também tu também o-povo este que contigo porque seja-grave de-tu a-palavra não poderás faz-o apenas de ti:');
INSERT INTO verses VALUES (2019, 2, 18, 19, 'Agora ouviu no teu voz aconselha-te e-seja Elohim contigo foi tu ao povo em-frente-a הָֽאֱלֹהִ֔ים e trazeste tu a as-palavras a Elohim');
INSERT INTO verses VALUES (2020, 2, 18, 20, 'e-adverti-los a-eles a os-regulamentos e-a a-eles e-anunciaste para-ela-os a o-caminho irão nela e-a o-trabalho que fazem');
INSERT INTO verses VALUES (2021, 2, 18, 21, 'e-tu TECHAZEH de-todo o-povo ANASH''E- CHAYIL YIREI'' Elohim homens-de EMET SON''EI'' BATZA'' VESAM''THA'' ALHEM príncipes-de milhares príncipes-de centenas príncipes-de cinquenta e-príncipes-de dez');
INSERT INTO verses VALUES (2022, 2, 18, 22, 'e-julgaram a o-povo em-todo tempo o-grande todo a-coisa o-grande o-pequeno a-ti e-todo a-palavra o-pequeno julgarão-os eles e-aliviar me''al-eka וְנָשְׂא֖וּ contigo');
INSERT INTO verses VALUES (2023, 2, 18, 23, 'mãe a a-coisa o-este farás e-ordenou-te Elohim e-poderás ficou-em-pé e-também todo o-povo esta sobre de-seu-lugar virá em paz');
INSERT INTO verses VALUES (2024, 2, 18, 24, 'E-ouviu Moisés à-voz-de o-marido-dele E-fez todo que disse');
INSERT INTO verses VALUES (2025, 2, 18, 25, 'e escolheu Moisés homens de força de-todo eles E-deu a-eles cabeças sobre o-povo príncipes-de milhares príncipes-de centenas príncipes-de cinquenta e-príncipes-de dez');
INSERT INTO verses VALUES (2026, 2, 18, 26, 'e-julguem a o-povo em-todo o-tempo a a-coisa o-difícil o-pequeno a eles e-todo a-palavra o-pequeno e-julgarão eles');
INSERT INTO verses VALUES (2027, 2, 18, 27, 'e-enviou Moisés a o-marido-dele a-ele a-ele a terra-dele');
INSERT INTO chapters VALUES (69, 2, 19, 25);
INSERT INTO verses VALUES (2028, 2, 19, 1, 'em-o-mês o-terceiro para-sair filhos-de Israel da-terra no-dia em-o-dia esta entraram deserto-de Sinai');
INSERT INTO verses VALUES (2029, 2, 19, 2, 'e-partiram de-Rפידים e-vieram deserto-de Sinai e-acamparam no-deserto e-acampou-se- nome diante diante-de o-monte');
INSERT INTO verses VALUES (2030, 2, 19, 3, 'e-moshe subir a E-chamou a-ele yhwh yhwh dizendo o-monte dizendo assim dirás para-casa-de Jacó e-anunciaste para-filhos-de Israel');
INSERT INTO verses VALUES (2031, 2, 19, 4, 'vós vistes que fiz Lemitsrayim e-levantei vos sobre as-asas penas e-traggo vos para-mim');
INSERT INTO verses VALUES (2032, 2, 19, 5, 'e-agora se ouvinte ouvi-reis com-a-minha-voz e-vos-guardastes e-sereis da-minha-aliança e-fosteis para-mim segregada de-todo os-povos porque para-mim todo a-terra');
INSERT INTO verses VALUES (2033, 2, 19, 6, 'e vós ser-vós-vos-vereis- para-mim reino-de sacerdotes e-povo Estas estas-estes as-palavras que falarias a filhos-de Israel');
INSERT INTO verses VALUES (2034, 2, 19, 7, 'E-veio Moisés E-chamou para-os-anciãos o-povo e-colocou em-frente-a-eles a todo as-palavras os-estes que yhwh yhwh');
INSERT INTO verses VALUES (2035, 2, 19, 8, 'e-responderam todo o-povo yachdav e-disseram todo yhwh palavra yhwh façamos-nós e-estabeleceu-se Moisés a palavras-de o-povo a yhwh');
INSERT INTO verses VALUES (2036, 2, 19, 9, 'E-disse yhwh a eis eu eu veio para ti em-entre o-nuvem por-causa-de ouvirá o-povo em-minhas-palavras contigo e-também em-te crerão para-sempre e-revelou Moisés a palavras-de o-povo a yhwh');
INSERT INTO verses VALUES (2037, 2, 19, 10, 'E-disse yhwh a Moisés vai a o-dia e-os-santificarei o-dia e-amanhã e-lavarem-se-as-roupas suas-vestes-verso-final');
INSERT INTO verses VALUES (2038, 2, 19, 11, 'e-sejam prontos para-o-dia o terceiro que no-dia no-dia descer-á yhwh yhwh todo o-povo sobre monte-de Sinai');
INSERT INTO verses VALUES (2039, 2, 19, 12, 'e-limitarás a o-povo dizendo dizendo a-vós a-vós subida na-montanha e-tocarás em-a-sua-extremidade todo morrendo na-montanha morrer será-morto');
INSERT INTO verses VALUES (2040, 2, 19, 13, 'não tocarás mão mão porque sacudirás será-sacudido ou jorrará não se animal se homem não viva em-a-duração-do-trombeta o-trombeta eles subam em-o-monte');
INSERT INTO verses VALUES (2041, 2, 19, 14, 'e desceu Moisés de o-monte a o-povo e-os-consagrou a o-povo e-eles-lavaram as-vestes-deles');
INSERT INTO verses VALUES (2042, 2, 19, 15, 'E-disse a o-povo sejam prontos para-três dias a vocês-virão a mulher');
INSERT INTO verses VALUES (2043, 2, 19, 16, 'e-houve no-dia o-terceiro para-serem a-manhã e-houve vozes e-raios e-nuvem pesado sobre o-monte e-som de-trumpete muito muito e-tremeu todo o-povo que no-lager');
INSERT INTO verses VALUES (2044, 2, 19, 17, 'e-saiu Moisés a o-povo para-encontro-de os-elohim de o-acampamento va-yit-ya-tsăbū em-baixo o-monte');
INSERT INTO verses VALUES (2045, 2, 19, 18, '-e montanha Sinai ashan kullo de-diante-de que yarad sobre-ele yhwh no-fogo e-subiu asano ke''ashen hakchibshan e-tremeu todo muito muito');
INSERT INTO verses VALUES (2046, 2, 19, 19, 'e-houve voz o-shofar  הולך  e-forte muito Moisés יְדַבֵּ֔ר וְהָאֱלֹהִ֖ים responderá-o em-a-voz');
INSERT INTO verses VALUES (2047, 2, 19, 20, 'e desceu yhwh sobre monte-de Sinai a E-chamou yhwh E-chamou yhwh para-Moshe a cabeça o-monte e-ofereceu Moisés');
INSERT INTO verses VALUES (2048, 2, 19, 21, 'E-disse yhwh a Moisés רֵ֖ד o-testemunha no-povo-o para-que-não para-ver a nós para-ver e-caiu dele muito');
INSERT INTO verses VALUES (2049, 2, 19, 22, 'e-também hakohanim os-que-se-aproximam a yhwh se-santificarão para-que-não yhwh neles yhwh');
INSERT INTO verses VALUES (2050, 2, 19, 23, 'E-disse Moisés a yhwh não podera o-povo para subir a monte-de Sinai dizendo você a testemunha neles para-dizer o cercado a muito e santificá-lo:');
INSERT INTO verses VALUES (2051, 2, 19, 24, 'E-disse a-ele yhwh vai- desce tu tu e-Aharôn contigo e os sacerdotes e-o povo a destruam para-subir a yhwh para-que-não que se espalhe- em-eles');
INSERT INTO verses VALUES (2052, 2, 19, 25, 'e-desceu Moisés a E-disse E-disse a-eles');
INSERT INTO chapters VALUES (70, 2, 20, 26);
INSERT INTO verses VALUES (2053, 2, 20, 1, 'e-falou Elohim a todo as-palavras dizendo para-dizer');
INSERT INTO verses VALUES (2054, 2, 20, 2, 'eu yhwh Elohim-teu que saí-te de-terra-de Egito de-casa escravos');
INSERT INTO verses VALUES (2055, 2, 20, 3, 'não sera- para-ti Elohim outros sobre minhas-faces');
INSERT INTO verses VALUES (2056, 2, 20, 4, 'não farás- para-ti ídolo- e-todo imagem que nos-céus- de-a-cima e-que em-a-terra de-a-baixo e-que na-agua de-abaxo debaixo-de');
INSERT INTO verses VALUES (2057, 2, 20, 5, 'não a-eles para-eles e-não que porque yhwh yhwh Elohim-teu El zeloso que-visita pecado avós sobre filhos sobre tri-nos e-sobre quad-ro-s a-o-inim-ho');
INSERT INTO verses VALUES (2058, 2, 20, 6, 'e-faz chan-dor para-milhares a-am-o-s e-para-guardadores-de mandamentos-meus');
INSERT INTO verses VALUES (2059, 2, 20, 7, 'não e-le-va a nome-de yhwh que não porque yhwh pur-gar-a yhwh a que e-le-va a nome-de-ele para-a-vaidade-verso-final');
INSERT INTO verses VALUES (2060, 2, 20, 8, 'lembra-te a dia o-sábado para-santificá-lo');
INSERT INTO verses VALUES (2061, 2, 20, 9, 'seis dias servirás e-fazes todo trabalho-teu');
INSERT INTO verses VALUES (2062, 2, 20, 10, 'e-dia o-sétimo sábado- a-yhwh Elohim-teu não farás todo tu você- e-filhoteu- e-filha-teu servo-teu e-escravateu e-em-vossoanimal e-estrangeiro-teu que em-a-porta-de-tuas');
INSERT INTO verses VALUES (2063, 2, 20, 11, 'que seis- dias yhwh yhwh a os-céus e-a a-terra no-dia o mar e-a todo yhwh contra-eles e-ele-descansou no-dia o sétimo sobre sim abençoou yhwh a dia a-sabáte e-ele-o-consagrou');
INSERT INTO verses VALUES (2064, 2, 20, 12, 'honra a Avicha e-a mãe-tua para-que sobre a-terra sobre האדמה que para-ti seus-elohim deu para-ti');
INSERT INTO verses VALUES (2065, 2, 20, 13, 'não não-matarás');
INSERT INTO verses VALUES (2066, 2, 20, 14, 'não não-terás-covarde');
INSERT INTO verses VALUES (2067, 2, 20, 15, 'não não-rou-bas');
INSERT INTO verses VALUES (2068, 2, 20, 16, 'não res-pon-da em-o-seu-amigo até mentira');
INSERT INTO verses VALUES (2069, 2, 20, 17, 'não tachmod casa re''ekha não desejarás mulher-de re''eka ve-avdo va-amato e-seu-boi e-tudo e-todo que lere''eka');
INSERT INTO verses VALUES (2070, 2, 20, 18, 'e-todo o-povo vendo-os a as-vozes voz os que brilham e-את voz-de E-viu e-a o-monte fumo-será E-viu o-povo e-eles-tremeluziram e-eles-pararam-se de-a-longe');
INSERT INTO verses VALUES (2071, 2, 20, 19, 'e-disseram a Moisés daber- tu com-nos e-será-ouvida El יְדַבֵּר immanu Elohim para-que-não morram-vos');
INSERT INTO verses VALUES (2072, 2, 20, 20, 'E-disse Moisés a o-povo que v-trepareis porque para-a-razão-de tentações vos veio o-Elohim e-por-causa-de seráis-vós para-não sobre vossas-caras para-não pecareis-vos');
INSERT INTO verses VALUES (2073, 2, 20, 21, 'e-estabeleceu o-povo de-longe umoshe se-aproximou a a-escuridão que nome Elohim');
INSERT INTO verses VALUES (2074, 2, 20, 22, 'E-disse yhwh a Moisés assim tu teirim a filhos-de Israel que vistes-vós porque de os-céus falei com-vos');
INSERT INTO verses VALUES (2075, 2, 20, 23, 'não fazeis comigo deos prata e-Elohim-de ouro não fazeis a-vós');
INSERT INTO verses VALUES (2076, 2, 20, 24, 'altar-de terra farás- para-mim e-imoltes sobre-ele a vossas-ofertas e-a vossos-sacrifícios-de-paz a rebanho-vosso e-a vossas-ovelhas em-todo o-lugar que lembrarei a meu nome- irei a-ti e-bençã-o-te');
INSERT INTO verses VALUES (2077, 2, 20, 25, 'e-se altar-de pedras tu-farás para-mim não que a-elas cortou porque espada-tua levantou-te sobre-ela e-vilefez-a');
INSERT INTO verses VALUES (2078, 2, 20, 26, 'e-não subirás em-alturas sobre de-meu-altar que não serás-revelado erva-teu sobre-ele');
INSERT INTO chapters VALUES (71, 2, 21, 37);
INSERT INTO verses VALUES (2079, 2, 21, 1, 'e-estes os-juízos que ta-shim diante-deles');
INSERT INTO verses VALUES (2080, 2, 21, 2, 'que tique-he servo hebree seis dois ele-serve e-bash-seveeth saia la-chafshee gratuitamente');
INSERT INTO verses VALUES (2081, 2, 21, 3, 'se be-gapho yavo be-gapho sairá se ele mulher ele וְיָצְאָה mulher-sua com-ele-verso');
INSERT INTO verses VALUES (2082, 2, 21, 4, 'se adonai-o dê a-ele filhos ve-yalda- a-ele filhos ou filhas a-mulher ve-ilade-ha תִּהְיֶה֙ para-a-sua-madama e-ele saia em-o-seu');
INSERT INTO verses VALUES (2083, 2, 21, 5, 'e-se disse diga יֹאמַר֙ o-escravo amou-ei a Adonai não mulher-sua e-a filhos-de não אֵצֵא livre-seu');
INSERT INTO verses VALUES (2084, 2, 21, 6, 'e-aproximou-ele adonai-o a Elohim e-aproximou-ele a a porta ou a a-moldura e-ferrou seu-adonai para-sempre a-sua-orelha em-a-marca e-serviu-o para-sempre');
INSERT INTO verses VALUES (2085, 2, 21, 7, 'e-quando venderá homem a não para-escrava não sairás como-a-saída os-escravos');
INSERT INTO verses VALUES (2086, 2, 21, 8, 'se ruim em-os-olhos de-seu-adonai que ele-desejou-a e-redimiu-a para-o-povo estrangeiro não reinará para-vender-a em-o-seu-vestido em-ela');
INSERT INTO verses VALUES (2087, 2, 21, 9, 'e-se para-o-seu-filho será-dada-a conforme-o-julgamento das-filhas fará- a-ela');
INSERT INTO verses VALUES (2088, 2, 21, 10, 'se outra יִקָּח־ a-ele שֹׁאֵרָהּ não וְעֹנַתָ֖הּ não יִגְרַע׃');
INSERT INTO verses VALUES (2089, 2, 21, 11, 'e-se não אֵלֶּה não faz-o para ela וְיָצְאָה חִנָּם não כַּסֶּפֶת׃');
INSERT INTO verses VALUES (2090, 2, 21, 12, 'מַכֶּה homem וָמֵת morrendo será-morto');
INSERT INTO verses VALUES (2091, 2, 21, 13, 'וַאֲשֶׁר֙ não צָדָה וְהָאֱלֹהִ֖ים אִנָּ֣ה לְיָד֑וֹ וְשַׂמְתִּ֤י a-ti lugar que יָנ֖וּס ali');
INSERT INTO verses VALUES (2092, 2, 21, 14, 'e-quando יָזִ֥ד homem sobre re-a-hu לְהָרְג֣וֹ בְעָרְמָ֑ה de-com altar-meu תִּקָּחֶ֖נּוּ para a morte');
INSERT INTO verses VALUES (2093, 2, 21, 15, 'e que atinge seu-pai e sua mãe morrendo será-morto');
INSERT INTO verses VALUES (2094, 2, 21, 16, 'e que rouba homem e o vende e é achado em sua mão morrendo será-morto');
INSERT INTO verses VALUES (2095, 2, 21, 17, 'e maldiz seu-pai e sua mãe morrendo será-morto');
INSERT INTO verses VALUES (2096, 2, 21, 18, 'e-quando se disputarão homens e atingirá homem a companheiro-seu em-pé ou em-águpe e-não mor-te e-caiu para-cam-a:');
INSERT INTO verses VALUES (2097, 2, 21, 19, 'se ar-rise e-andará fora sobre de-sua-cara e-pur-a o-ma-chado somente sua-sentada irá dar e curará curará');
INSERT INTO verses VALUES (2098, 2, 21, 20, 'e-quando atingirá homem a seu servo ou a debaixo sua-mão e morrerá em-lugar-de sua-mão vengará-se vengará-se');
INSERT INTO verses VALUES (2099, 2, 21, 21, 'entretanto se dia ou dois dias não não que porque ele ela');
INSERT INTO verses VALUES (2100, 2, 21, 22, 'e-quando vencerão אֲנָשִׂים וְנָגְפוּ mulher הָרָה e-eles-sairão יְלָדֶיהָ será será אָסֹון עָנֹשׁ יֵעָנֵשׁ como יָשִׁית sobre-ele בַּ֣עַל a-mulher וְנָתַן בִּפְלִלִים׃');
INSERT INTO verses VALUES (2101, 2, 21, 23, 'e-se será yihye e-tu-darás debaixo debaixo-de alma');
INSERT INTO verses VALUES (2102, 2, 21, 24, 'olho debaixo olho שֶׁן debaixo שֶׁן mão debaixo mão רֶגֶל debaixo רָגֶל׃');
INSERT INTO verses VALUES (2103, 2, 21, 25, 'כּוֹויָה debaixo כּוֹויָה פֶּץַע debaixo פָּץַע חַבורָה debaixo חַבורָה׃');
INSERT INTO verses VALUES (2104, 2, 21, 26, 'e-quando irá atingir homem a olho seu servo ou a olho debaixo e corromperá livremente enviará em-baixo-de sua face');
INSERT INTO verses VALUES (2105, 2, 21, 27, 'e-se dente seu servo ou dente seu servo dejará cair debaixo enviará em-baixo-de שנה׃');
INSERT INTO verses VALUES (2106, 2, 21, 28, 'e-quando יחג boi a homem ou a mulher ומות סקל יסקל השור e-não יאכל a em-carne-sua e-baal השור נקי׃');
INSERT INTO verses VALUES (2107, 2, 21, 29, 'e-se ovelha -nagach- ele desde-mol -shilshom- e-hu''ad em-seus e-não guardará-o e-matará homem ou mulher o-touro irá-queimar e-também em-ló será-morto');
INSERT INTO verses VALUES (2108, 2, 21, 30, 'se kôper yûšath sobre-ele vênatan pîdêyon naphshô conforme-tudo que yûšath sobre-ele');
INSERT INTO verses VALUES (2109, 2, 21, 31, 'ou filho yiggach ou bat yiggach como-o-julgamento para-ele será-feito para-ele');
INSERT INTO verses VALUES (2110, 2, 21, 32, 'se servo יִגַּח השור ou אָמַה כּסֶף trinta שְׁקָלִים dará לַאֲדֹנָיו וְהַשׁוֹר יִסַּקֵל׃');
INSERT INTO verses VALUES (2111, 2, 21, 33, 'e-quando יִפְתַּח homem בָּור ou- porque irá homem bur e-não cobrirá e cairá- lá burro ou cavalo:');
INSERT INTO verses VALUES (2112, 2, 21, 34, 'senhor do bur pagará prata יָשִׁיב לִבְעַלֵּיהוּ וְהַמֵּת ele-será- para-ele');
INSERT INTO verses VALUES (2113, 2, 21, 35, 'e-quando יִגַּפ שׁוֹר־ homem a boi re-a-hu ומות וּמָכְרוּ a הַשׁוֹר o-vivo וְחָצֻ a com-prata-seu e-também a o morto יֵחֱצוּן׃');
INSERT INTO verses VALUES (2114, 2, 21, 36, 'ou 노다'' que boi נגג'' ele de-ontem anteontem e-não ישמרנו'' בעלאו שלא'' pague שור debaixo השור והמת ele-será- para-ele');
INSERT INTO verses VALUES (2115, 2, 21, 37, 'que יגנב- homem boi ou שוה e-o-carne ou e-o-vendido cinco debaixo pagará em-lugar-de debaixo e-quatro-de ovelhas debaixo-de o-cordeiro');
INSERT INTO chapters VALUES (72, 2, 22, 30);
INSERT INTO verses VALUES (2116, 2, 22, 1, 'se no-ferrete será-encontrado o-ladrão e-atingirá e-morrerá a-ele a-ele דּוֹמִים׃');
INSERT INTO verses VALUES (2117, 2, 22, 2, 'se זַרְחָה o-sol sobre-ele a-ele a-ele שַׁלֵּם pagará a-ele não-há a-ele וְנֻמַּכּר בְּגִנְבָּתוֹ׃');
INSERT INTO verses VALUES (2118, 2, 22, 3, 'se הִמְצֵא֩ תִּמְצֵא בְּיָדוֹ הַגִּנְבָּה משׁור até vida até שׂה vivos dois ישׁלם׃');
INSERT INTO verses VALUES (2119, 2, 22, 4, 'que  yab''er- homem שׂדה ou כרם וְשׁילַח֙ a וּבִעֵר em-campo-de acher mitev שׂדהוּ e bom o jardim');
INSERT INTO verses VALUES (2120, 2, 22, 5, 'porque sairá אֵ֜שׁ e encontrará espinhos e seremos comidos trigo ou a germinação ou o-campo paz pagará o que faz passar a a que arde:');
INSERT INTO verses VALUES (2121, 2, 22, 6, 'porque dê homem a seu companheiro prata ou instrumentos para guardar e furtado de-casa-de o-homem se será-encontrado o-ladrão pague dois');
INSERT INTO verses VALUES (2122, 2, 22, 7, 'se não será achado o גַּנָּ֔ב e וְנִקְרַ֥ב de בַּֽעַל־ a-casa a sua-mão se não enviou mão-sua na בִּמְלֶ֥אכֶת seu-amigo');
INSERT INTO verses VALUES (2123, 2, 22, 8, 'sobre todo palavra-de a פֶּ֡שַׁע sobre shór sobre o חֲ֠מוֹר sobre a שֶׂ֨ה até a שַׂלְמָ֜ה sobre todo o אֲבֵדָ֗ה que dira porque ele este até הָֽאֱלֹהִ֔ים yavo palavra-de dois-deles que יַרְשִׁיעֻן֙ Elohim pague dois לְרֵעֵֽהוּ׃');
INSERT INTO verses VALUES (2124, 2, 22, 9, 'porque dê homem a seu companheiro חֲמ֨וֹר ou boi ou שֶׂ֛ה e-todo animal לִשְׁמֹ֑ר וּמֵ֛ת ou- נִשְׁבַּ֥ר ou- nishba não viu');
INSERT INTO verses VALUES (2125, 2, 22, 10, 'de-o-selo yhwh תִּהְיֶה֙ entre dois-deles se não sua-mão mão-sua בִּמְלֶ֣אכֶת e-tome e tomará dele e-não pagará;');
INSERT INTO verses VALUES (2126, 2, 22, 11, 'e-se ladrão roubará dele pagará a ele;');
INSERT INTO verses VALUES (2127, 2, 22, 12, 'se golpeador golpeará יְבִיאֶהוּ até não não ישׁלם׃');
INSERT INTO verses VALUES (2128, 2, 22, 13, 'e-quando יִשַׁאֵל homem de-com re-a-hu וְנִשַׁבֵּר ou morreu בְּעָלָיו não-há com-ele שַׁלֵּם ישׁלם׃');
INSERT INTO verses VALUES (2129, 2, 22, 14, 'se בְּעָלָיו não não יְשַׁלֵּם ele שָׂכִיר ele veio בִּשְׂכָרֽוֹ׃');
INSERT INTO verses VALUES (2130, 2, 22, 15, 'e-quando יְפַתֶּ֣ה homem בְּתוּלָ֛ה que não com-ela וְשָׁכַ֣ב com-ela para-ele יִמְהָרֶ֥נָּה a-ele para-mulher');
INSERT INTO verses VALUES (2131, 2, 22, 16, 'se מָאֵ֧ן יְמָאֵ֛ן אָבִ֖יהָ a-ele a-ele prata יִשְׁקֹ֔ל כְּמֹ֖הַר as vírgidas:');
INSERT INTO verses VALUES (2132, 2, 22, 17, 'a feiticeira não viverá:');
INSERT INTO verses VALUES (2133, 2, 22, 18, 'todo dormir morrendo animal morrer será-morto');
INSERT INTO verses VALUES (2134, 2, 22, 19, 'sacrificador aos elohim(es) ele o abominará: para-não a-yhwh sozinho');
INSERT INTO verses VALUES (2135, 2, 22, 20, 'e estrangeiro não arrependimento e-não será apertado porque גרים fosteis em-terra-de Egito');
INSERT INTO verses VALUES (2136, 2, 22, 21, 'todo אלמנה não não תענוון׃');
INSERT INTO verses VALUES (2137, 2, 22, 22, 'se אנוה ele que porque se צעוק יצעק a-mim ouviu אֵשְׁמַע צעקתו׃');
INSERT INTO verses VALUES (2138, 2, 22, 23, 'והרה אפיתי והרגתי vos com a espada e-sejam נְשֵׁיכֶם אֲלָמֹות וּבְנֵיכֶם יְתוֹמִים׃');
INSERT INTO verses VALUES (2139, 2, 22, 24, 'se כּסֶף תַּלְוֶה a עַמּי a הֶעָנִי֙ a-ele não תִהְיֶה a-ele כְּנוֹשֶׁה não תְּשַׂימ֥וּן sobre-ele נֶֽשֶׁךְ׃');
INSERT INTO verses VALUES (2140, 2, 22, 25, 'se חָבֹ֥ל תַּחְבֹּ֖ל שַׂלְמַ֣ת re''ekha até veio a-ele תְּשִׁיבֶ֥נּוּ a-ele');
INSERT INTO verses VALUES (2141, 2, 22, 26, 'que ela para-a-sua-conta הִ֥וא שִׂמְלָת֖וֹ ela בַּמֶּ֣ה יִשְׁכָּ֔ב e-foi porque יִצְעַ֣ק a-mim וְשָׁמַעְתִּ֖י porque חַנּ֥וּן eu');
INSERT INTO verses VALUES (2142, 2, 22, 27, 'Elohim não תְקַלֵּ֑ל וְנָשִׂ֥יא בְעַמְּךָ֖ não תָאֹֽר׃');
INSERT INTO verses VALUES (2143, 2, 22, 28, 'מְלֵאָתְךָ֥ וְדִמְעֲךָ֖ não תְאַחֵ֑ר em-primogênito בָּנֶ֖יךָ tu-darás para-mim');
INSERT INTO verses VALUES (2144, 2, 22, 29, 'assim farás para-te para-o-ovelho-te shib-aat será será no-dia mãe-dele no-dia o-sétimo dar-vos-vou para-mim');
INSERT INTO verses VALUES (2145, 2, 22, 30, 'e-para-os santidade ser-vós-vais a-mim e-carne no-campo não não vós-comereis para-o-cão ele a-ele');
INSERT INTO chapters VALUES (73, 2, 23, 33);
INSERT INTO verses VALUES (2146, 2, 23, 1, 'não levardes-vos ouviu שָׁוְא a תַּשְׁבִּית mão-tua com perverso-o להיות até violência');
INSERT INTO verses VALUES (2147, 2, 23, 2, 'não תִהְיֶה אחרי- muitos לרעות e-não תענה sobre muito לנטות atrás-de muitos להטות׃');
INSERT INTO verses VALUES (2148, 2, 23, 3, 'והDAL não תֶהְדַּ֖ר בְּרִיבֽוֹ׃');
INSERT INTO verses VALUES (2149, 2, 23, 4, 'que תִפְגַּ֞ע שׁ֧וֹר אֹֽיִבְךָ֛ ou חֲמֹר֖וֹ תֹּעֶ֑ה retornar תְּשִׁיבֶ֖נּוּ a-ele');
INSERT INTO verses VALUES (2150, 2, 23, 5, 'porque תִרְאֶ֞ה חֲמ֣וֹר שׂונאתך debaixo em-lugar-de משהאו והchalkalta a-ele a-ele עזוב תעזוב com-ele-verso');
INSERT INTO verses VALUES (2151, 2, 23, 6, 'não תטה משפט איבונך בְּרִיבֽוֹ׃');
INSERT INTO verses VALUES (2152, 2, 23, 7, 'מדבר־ שֶׁׁקֶר תִּרְחָ֑ק ונקי e-צדיק que תּהֲרֹג porque não אַצְדּיָק perverso');
INSERT INTO verses VALUES (2153, 2, 23, 8, 'וְשׁוֹחַד não תִּקָּח que הַשׁוֹחַד יְעַוֵּר פִּיקְחִים וִֽיסַלֵּף palavras-de צַדּיָקִים׃');
INSERT INTO verses VALUES (2154, 2, 23, 9, 'e o estrangeiro não será apertado e-vós vós conheceréis a alma o estrangeiro porque estrangeiros fostes em-terra-de Egito');
INSERT INTO verses VALUES (2155, 2, 23, 10, 'e-seis dois sowaste a a tua terra e-ajuntarás a suas produções');
INSERT INTO verses VALUES (2156, 2, 23, 11, 'e a sétima será deixada e a despojará e comerão avíons seu povo e restarão comerás animal-de o-campo assim farás para seu jardim para suas oliveiras:');
INSERT INTO verses VALUES (2157, 2, 23, 12, 'seis dias farás suas obras e no dia ha-shevi-i תִּשְׁבֹּ֑ת para-que יָנ֗וּחַ שֽׁוֹרְךָ֙ וַחֲמֹרֶ֔ךָ וְיִנָּפֵ֥שׁ filho-de אֲמָתְךָ֖ וְהַגֵּֽר׃');
INSERT INTO verses VALUES (2158, 2, 23, 13, 'וּבְכֹ֛ל que disse a-vós תִּשָּׁמֵ֑רוּ e-ali Elohim não não não não יִשָּׁמַ֖ע sobre teu-boca:');
INSERT INTO verses VALUES (2159, 2, 23, 14, 'três pés- comemorar- a-mim ano-');
INSERT INTO verses VALUES (2160, 2, 23, 15, 'a chag os-maizot- guardar- sete-de comerás comer- maizot como- eu-te-ordenei- לְמֹועֶד֙ novo הָאֲבִיב֑ porque em-ele יָצְאָתָ֣ de-Egito e-não יֵרָאוּ֥ face-de vazios');
INSERT INTO verses VALUES (2161, 2, 23, 16, 'וְחַ֥ג הַקֹּצִ֗יר בְּכוּרֵ֣י suas obras que תִּזְרַ֗ע no-campo וְחַ֥ג האסיפ בצאת השנה באספך a מעשיך de o-campo');
INSERT INTO verses VALUES (2162, 2, 23, 17, 'três פעמים בשנה יראה todo זכורך a face-de yhwh yhwh');
INSERT INTO verses VALUES (2163, 2, 23, 18, 'não תזבח sobre  חָמֵ֖ץ   דַּם־   זִבְחִ֑י  e-não yalin gordura-de  חַגִּ֖י  até manhã');
INSERT INTO verses VALUES (2164, 2, 23, 19, 'רֵאשִׁ֗ית   בִּכּוּרֵי֙   אַדְמָ֣תְךָ   תָּבִ֕יא  casa yhwh teu-Elohim não  תְבַשֵּׁ֥ל   גְּדִ֖י  sua-mãe mãe-de ele');
INSERT INTO verses VALUES (2165, 2, 23, 20, 'eis eu enviou מַלְאָךְ diante-de-ti לִשְׁמָרְךָ בַּדָּ֑רֶךְ וְלַהֲבִ֣יאֲךָ a o-lugar que הֲכִנֹֽתִי׃');
INSERT INTO verses VALUES (2166, 2, 23, 21, 'הישמר מִפָּנָ֛יו וּשְׁמַ֥ע בְּקֹל֖וֹ a תַּמֵּ֣ר que não não yasua que porque nome-meu em-o-centro-dele');
INSERT INTO verses VALUES (2167, 2, 23, 22, 'que se ouviu תִּשְׁמַע֙ em-voz-dele e farás todo que eu falar e aborrecer a teu inimigo e comprimir-te-ei a teus apertadores');
INSERT INTO verses VALUES (2168, 2, 23, 23, 'porque irei minha angelos ante ti e trarei-te a o-emori e-o-heteu e separarei וְהַֽכְּנַעֲנִ֔י o-hivi e-o-jebuseu e o farás arder');
INSERT INTO verses VALUES (2169, 2, 23, 24, 'não terás por adoração aos seus elohim e-não os farás servir e-não você-fará que porque destruirás destruirás e quebrarás quebrarás as suas estâtuas');
INSERT INTO verses VALUES (2170, 2, 23, 25, 'e servireis a yhwh Elohim-vosso e abençoe a o teu pão e-a as tuas águas e eu tirarei doença do-teu-interno');
INSERT INTO verses VALUES (2171, 2, 23, 26, 'não ser-ás cicatriz e eu arrebentar na tua terra a número os teus dias e eu preencher');
INSERT INTO verses VALUES (2172, 2, 23, 27, 'a minha dor Eu lançarei diante-de-ti e a morte a todo o-povo que virá com-eles e eu darei a todo seus inimigos a-ti na face:');
INSERT INTO verses VALUES (2173, 2, 23, 28, 'e lançarei a a fome diante-de-ti e a desolação a do Hivite a o-cananeu e-a do Hítie de-a-frente-de-você-versículo-final');
INSERT INTO verses VALUES (2174, 2, 23, 29, 'não o arrependerei dele de ti diante no ano um para-que-não a-terra a-terra sem semear e multiplicarei animal-de vivente-de o-campo');
INSERT INTO verses VALUES (2175, 2, 23, 30, 'pouco מְעַ֛ט o arrependerei dele de-diante-de-você até que e te ferirei e herdarei a a-terra');
INSERT INTO verses VALUES (2176, 2, 23, 31, 'e beberei a גּוֹבְלֵךְ מִיַּם- Suf e-até mar que וּמִמִּדְבָּר até o-rio que darei a-terra a habitantes-de a-terra וְגֵרַשׁתָּם de-diante-tua');
INSERT INTO verses VALUES (2177, 2, 23, 32, 'não a-eles a-eles וְלֵאֱלֹהֵיהֶם em-brisa');
INSERT INTO verses VALUES (2178, 2, 23, 33, 'não יִשַׁבּוּ בְּאַרְצֶךָ para-que-não יַחֲטִיאוּ a-ti que porque תַּעֲבֹד a a-ti porque será para-ti para-laço');
INSERT INTO chapters VALUES (74, 2, 24, 18);
INSERT INTO verses VALUES (2179, 2, 24, 1, 'e-a disse folhas-de sobe tu yhwh tu e-Aarão Nadabe e-Avi-hu-a e-setenta מִזִּקְנֵי Israel e-vos-inclinar-eis de-longe:');
INSERT INTO verses VALUES (2180, 2, 24, 2, 'e-avancar Moisés sozinho a yhwh não não e-avançarão não não eles-subirão com-ele-verso');
INSERT INTO verses VALUES (2181, 2, 24, 3, 'E-veio Moisés e-disse para-o-povo a todo yhwh יהוה e-a todo as-julgamentos voz um o-povo voz um yhwh todo as-palavras que palavra yhwh serão-feitas:');
INSERT INTO verses VALUES (2182, 2, 24, 4, 'e-escreveu Moisés a todo yhwh yhwh e-ele-levantou-se E-edificou e-ele-construiu debaixo em-lugar-de o-monte e-ambas dez מַצֵּבָ֔ה לִשְׁנֵ֥ים dez tribos-de Israel');
INSERT INTO verses VALUES (2183, 2, 24, 5, 'e-enviou a נַעֲרֵי֙ filhos-de Israel וַיּֽ͏ַעֲל֖וּ עֹלֹ֑ת וַֽיִּזְבְּח֞וּ זְבָחִ֧ים שְׁלָמִ֛ים a-yhwh פָּרִֽים׃');
INSERT INTO verses VALUES (2184, 2, 24, 6, 'E-tomou Moisés metade o-sangue וַיָּ֖שֶׂם בָּאַגָּנֹ֑ת וַחֲצִ֣י o-sangue זָרַ֖ק sobre o-altar');
INSERT INTO verses VALUES (2185, 2, 24, 7, 'E-tomou livro a-aliança E-chamou em-orelhas-de o-povo e-disseram todo que yhwh yhwh נַעֲשֶׂ֥ה וְנִשְׁמָֽע׃');
INSERT INTO verses VALUES (2186, 2, 24, 8, 'E-tomou Moisés a o-sangue וַיִּזְרֹ֖ק E-disse eis E-disse eis דַֽם־ yhwh que sobre yhwh com-vocês sobre todo as-palavras as estas');
INSERT INTO verses VALUES (2187, 2, 24, 9, 'e-ofereceu Moisés e-Arão Nadav e-Avi-hu-a e-setenta de-anciãos-de Israel');
INSERT INTO verses VALUES (2188, 2, 24, 10, 'e-eles-viram a Elohim-de Israel e-embaixo-de רַגְלָ֗יו כְּמַעֲשֵׂה֙ לִבְנַ֣ת o safir -cezem os-céus -para-se purificar:');
INSERT INTO verses VALUES (2189, 2, 24, 11, 'e-a os que saem filhos-de não não sua-mão sua-mão e viram a Elohim e comeram e beberam:');
INSERT INTO verses VALUES (2190, 2, 24, 12, 'E-disse yhwh a folhas-de sobe a-mim a montanha -seja- a-ti E darei-lhe a ti a tabelas a pedra e a lei e o mandamento que escrevi-os para ensiná-los:');
INSERT INTO verses VALUES (2191, 2, 24, 13, 'E-levantou Moisés e Josué seu servo e-ofereceu Moisés a monte-de Elohim');
INSERT INTO verses VALUES (2192, 2, 24, 14, 'e-a disse disse sentai até nisto até que retornaremos a-vós e-eis אַהֲרֹן e-Hur com-vocês quem Ba''al de-ber yigash a-eles');
INSERT INTO verses VALUES (2193, 2, 24, 15, 'e-ofereceu Moisés a o-monte vayekas ha-eanan a o-monte');
INSERT INTO verses VALUES (2194, 2, 24, 16, 'vayishkon kavod- yhwh sobre monte-de Sinai vayekashehu ha-eanan E-chamou dias no-dia a Moisés no-dia ha-shevi-i de-meio ha-eanan:');
INSERT INTO verses VALUES (2195, 2, 24, 17, 'וּמַרְאֵה֙ glória-de yhwh כְּאֵ֥שׁ אֹכֶ֖לֶת na-cabeça o-monte aos-olhos-de filhos-de Israel');
INSERT INTO verses VALUES (2196, 2, 24, 18, 'E-veio Moisés no-meio-de ha-eanan e-subiu a e-houve E-foi Moisés no monte dia dia noite noite');
INSERT INTO chapters VALUES (75, 2, 25, 40);
INSERT INTO verses VALUES (2197, 2, 25, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2198, 2, 25, 2, 'palavra a filhos-de Israel e-eles-tomarão- a-mim Terumá me''et todo homem que יִדְּבֶ֣נּוּ coração-dele תִּקְח֖וּ a תְּרוּמָתִֽי׃');
INSERT INTO verses VALUES (2199, 2, 25, 3, 've-zot הַתְּרוּמָ֔ה que תִּקְח֖וּ de-lhes ouro e-prata e-niqureth:');
INSERT INTO verses VALUES (2200, 2, 25, 4, 'e-tekeli e-púrpura e-carmesim segundo e-seis e-azim:');
INSERT INTO verses VALUES (2201, 2, 25, 5, 'e-peles oveis vermelhas-muito e-peles tachashim וַעֲצֵ֥י שִׁטִּֽים׃');
INSERT INTO verses VALUES (2202, 2, 25, 6, 'שֶׁ֖מֶן לַמָּאֹ֑ר בְּשָׂמִים֙ לְשֶׁ֣מֶן o-mishcha וְלִקְטֹ֖רֶת הַסַּמִּֽים׃');
INSERT INTO verses VALUES (2203, 2, 25, 7, 'pedras-de- שֹׁ֕הַם וְאַבְנֵ֖י מִלּוֹאִים לָאֵפוֹד וְלַחֹשֶׁן׃');
INSERT INTO verses VALUES (2204, 2, 25, 8, 'וְעָשׂוּ a-mim מִקְדַּשׁ וְשָׁכַנְתִּי em-meio-de-eles');
INSERT INTO verses VALUES (2205, 2, 25, 9, 'כְּכֹל que eu vista אוֹתֶיךָ֔ a תַּבְנִיט o-tabernáculo e-a תַּבְנִיט todo seu recipiente e-assim façam');
INSERT INTO verses VALUES (2206, 2, 25, 10, 'e façam arca madeiras-de acácia dois palmos e meio seu-comprimento e um palmo e meio em-ele-o-largura-seu e um palmo e meio sua altura');
INSERT INTO verses VALUES (2207, 2, 25, 11, 'וְצִפִּיתָ֤ ele ouro puro de-dentro e-de-fora תְּצַפֶּ֑נּוּ וְעָשִׂ֧יתָ sobre-ele זֵ֥ר ouro ao-redor');
INSERT INTO verses VALUES (2208, 2, 25, 12, 'וְיָצַ֣קְתָּ para-ele quatro טַבְּעֹ֣ת ouro וְנָ֣תַתָּ֔ה sobre quatro פַּעֲמֹתָ֑יו e-duas-de טַבָּעֹ֗ת sobre צַלְעוֹ֙ a-uma u-shtey טַבָּעֹ֔ת sobre צַלְע֖וֹ הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (2209, 2, 25, 13, 'e-farás בַדֵּ֖י madeiras-de acácia וְצִפִּיתָ֥ eles ouro');
INSERT INTO verses VALUES (2210, 2, 25, 14, 'וְהֵֽבֵאתָ֤ a הַבַּדִּים֙ sobre sobre צַלְעֹ֣ת הָאָרֹ֑ן para-levar a הָאָרֹ֖ן neles');
INSERT INTO verses VALUES (2211, 2, 25, 15, 'בְּטַבְּעֹת֙ הָאָרֹ֔ן serão הַבַּדִּ֑ים não יָסֻ֖רוּ nós');
INSERT INTO verses VALUES (2212, 2, 25, 16, 'וְנָתַתָּ֖ a הָאָרֹ֑ן a o-testemunho que etenn para-ti');
INSERT INTO verses VALUES (2213, 2, 25, 17, 'e-farás כַפֹּ֖רֶת ouro puro אַמָּתַ֤יִם e meio אָרְכָּ֔הּ e um palmo e meio rāḥabbah');
INSERT INTO verses VALUES (2214, 2, 25, 18, 've''asitā dois kərubīm ouro miqšāh farás eles misnē pontas ha-kappōret');
INSERT INTO verses VALUES (2215, 2, 25, 19, 'va''asē querubim um miqqetsāh deste-lado e-caravel- um de-acéu- deste de a-caporéth- fazei a os-querubins sobre segundo os-seus-filhos-');
INSERT INTO verses VALUES (2216, 2, 25, 20, 'e-sejam os-querubins que-spreadem- as-asas- acima-de- cobrindo-os- com-as-sus-asas- sobre a-caporéth- e as faces homem a irmão-dele face-de os-querubins serão face-de os-querubins');
INSERT INTO verses VALUES (2217, 2, 25, 21, 'e eu dar-te-ei a a propiciação sobre o arca de-acima e-a o arca dês a a testemunho que etenn para-ti');
INSERT INTO verses VALUES (2218, 2, 25, 22, 'e eu me assemblerei a-ti nome e eu falar-te-ei contigo de-cima-de a propiciação do meio segundo os-querubins que sobre arão a testemunha a todo que ordenemos te a filhos-de Israel');
INSERT INTO verses VALUES (2219, 2, 25, 23, 'e-farás mesa árvores-de acácia dois pés seu-comprimento e um pé em-ele-o-largura-seu e um pé e meio de sua altura:');
INSERT INTO verses VALUES (2220, 2, 25, 24, 'e cobrirás ele ouro puro e-farás para-ele zer ouro ao-redor');
INSERT INTO verses VALUES (2221, 2, 25, 25, 've-asita para-ele misgeret topach ao-redor ve''asita zer- zahav misgeret ao-redor');
INSERT INTO verses VALUES (2222, 2, 25, 26, 'e-farás para-ele quatro taba''ot ouro ve''nata''ta a sobre sobre quatro hafe''ot que para quatro de-seus-pés');
INSERT INTO verses VALUES (2223, 2, 25, 27, 'conforme a misteriosa serão as plantas para quartos separadamente levando a a mesa');
INSERT INTO verses VALUES (2224, 2, 25, 28, 'e-farás a הַבַּדִּים֙ madeiras-de שִׁיטִים eles ouro ouro וְנִשְׂאָה־ neles a a mesa');
INSERT INTO verses VALUES (2225, 2, 25, 29, 've-asita קְעָרֹתָיו וְכַפֹּתָיו וּקְשׂוֹתָיו֙ וּמְנַקִּיֹּתָ֔יו que יֻסַּךְ בָּהֵן ouro puro farás eles');
INSERT INTO verses VALUES (2226, 2, 25, 30, 'e eu dar-te-ei sobre pão pão-de face ante-mi sempre');
INSERT INTO verses VALUES (2227, 2, 25, 31, 'e-farás lampada- ouro puro candelabrum- -fiet a-lampada -suas-mamas -et-e-sua-cana -suas-copas -suas-bacias -e-suas-floradas de-a-ela ser-ão');
INSERT INTO verses VALUES (2228, 2, 25, 32, 'e-seis קָנִים יֹצְאִים מִצִּדֶּהָ שְׁלֹשָׁה קְנֵי מְנֹרָה מִצִּדָּהּ הָאֶחָד o-primeiro קְנֵי מְנֹרָה de-lá-dela o-segundo');
INSERT INTO verses VALUES (2229, 2, 25, 33, 'três gevú-''im mash-qú-kadím baq-qué-né o-primeiro kap-tór va-perákh e-três gevú-im mash-qú-kadím baq-qué-né o-primeiro kap-tór e-fo-rach assim seis as quinas que saem de a manora:');
INSERT INTO verses VALUES (2230, 2, 25, 34, 'e na manora quatro copos enfileirados suas bordas e suas flores:');
INSERT INTO verses VALUES (2231, 2, 25, 35, 'e a cipreste debaixo segundo das vimeiras deles e a cipreste debaixo segundo das vimeiras de-a e a cipreste debajo de segundo das vimeiras מִמֶּנָּה seis as quinas que saem de a manora:');
INSERT INTO verses VALUES (2232, 2, 25, 36, 'suas têmporas e seus canos de ela sejam toda de jardim uma ouro puro');
INSERT INTO verses VALUES (2233, 2, 25, 37, 'e-farás a suas velas sete e levou a luzes-deiha e iluminasse sobre Éber suas-faces:');
INSERT INTO verses VALUES (2234, 2, 25, 38, 'e-suas-mãos e-seus-pés ouro puro');
INSERT INTO verses VALUES (2235, 2, 25, 39, 'como-circunferência ouro puro fará ela a todo os-vasos as estas');
INSERT INTO verses VALUES (2236, 2, 25, 40, 'e-veja e-faça segundo-suas-estranhamentos que tu aspecto na-montanha');
INSERT INTO chapters VALUES (76, 2, 26, 37);
INSERT INTO verses VALUES (2237, 2, 26, 1, 'e-a a-arca vós-fará dez tapumes seis משזער וּתְכֵ֤לֶת וארגמן וְתֹלַ֣עַת segundo כְּרֻבִ֛ים obra-de חֹשֵׁ֖ב eles a-eles');
INSERT INTO verses VALUES (2238, 2, 26, 2, 'אֹ֣רֶךְ הַיְרִיעָ֣ה הָֽאַחַ֗ת oito e-vinte na-côvado וְרֹ֙חַב֙ quatro בָּאַמָּ֔ה a cortina a-uma medida uma uma as cortinas；');
INSERT INTO verses VALUES (2239, 2, 26, 3, 'cinco as cortinas traves mulher a sua irmã； e-cinco cortinas traves mulher a sua irmã；');
INSERT INTO verses VALUES (2240, 2, 26, 4, 'e farás； tules azul sobre שַׂפַּת הַיְרִיעָה a-uma de-acéu- בְּחֹבָרֶת וְכֵן תַּעֲשֶׂה בְּשַׂפַּת הַיְרִיעָה הַקִּיצוֹנָה בְּמַחְבֶּרֶת הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (2241, 2, 26, 5, 'cinquenta luláoth farás na veste a primeira e cinquenta luláoth farás em-extremidade a veste que na fita a-segunda מַקְבִּילֹת֙ הַלֻּ֣לָאֹ֔ת mulher a אֲחֹתָֽהּ׃');
INSERT INTO verses VALUES (2242, 2, 26, 6, 'e farás cinquenta קַרְסֵ֣י ouro וְחִבַּרְתָּ֨ a as-telas mulher a אֲחֹתָהּ֙ בַּקְּרָסִ֔ים um o-tabernáculo um');
INSERT INTO verses VALUES (2243, 2, 26, 7, 'וְעָשִׂ֙יתָ֙ yeru''ot ez''im le-ohel sobre ham-mishkan ashtei- doze eles farás a-eles');
INSERT INTO verses VALUES (2244, 2, 26, 8, 'orek — hayeru''ah ha-achat sheloshim — na-côvado ve-rochav quatro בָּאַמָּ֔ה הַיְרִיעָ֖ה a-uma medida uma uma dez יְרִיעֹֽת׃');
INSERT INTO verses VALUES (2245, 2, 26, 9, 'וְחִבַּרְתָּ֞ a cinco הַיְרִיעֹת֙ sozinho e-a seis הַיְרִיעֹ֖ת sozinho וְכָפַלְתָּ֙ a face-de הַשִּׁשִּׁ֔ית a de-frente face-de o-tenda');
INSERT INTO verses VALUES (2246, 2, 26, 10, 'e farás； cinquenta luláoth sobre שַׂפַּת הַיְרִיעָה a-uma הַקִּיצֹנָה בְּחֹבָרֶת e cinquenta luláoth sobre língua הַיְרִיעָה הַחֹבֶ֖רֶת הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (2247, 2, 26, 11, 've''asitā קַרְסֵי bronze cinquenta וְהֵבֵאתָ֤ a הַקְּרָסִים֙ בַּלֻּ֣לָאֹ֔ת וְחִבַּרְתָּ֥ a um e-acontecerá um');
INSERT INTO verses VALUES (2248, 2, 26, 12, 'וְסֶ֙רַח֙ הָעֹדֵ֔ף בִּירִיעֹ֖ת haohel חֲצִ֤י הַיְרִיעָה a-odéfet tisrákh sobre achóre o-tabernáculo');
INSERT INTO verses VALUES (2249, 2, 26, 13, 've-ha-amá deste ve-ha-amá de-este ba-odéf be-órekh yeru''ot haohel será sarúakh sobre tsidvé o-tabernáculo mizze e deste para cobri-lo;');
INSERT INTO verses VALUES (2250, 2, 26, 14, 'e-farás cobertura ao tenda peles oliveiras vermelhos e-tampa peles tachashim de-acima');
INSERT INTO verses VALUES (2251, 2, 26, 15, 'e-farás a as divisões para o santuário de troncos de carmelitas que se levantam');
INSERT INTO verses VALUES (2252, 2, 26, 16, 'dez côvados comprimento o kares e amah וַחֲצִ֣י a amah largura o kares o-primeiro');
INSERT INTO verses VALUES (2253, 2, 26, 17, 'duas jotas para o kares o-primeiro mesolabot mulher a sua irmã； assim a-todo para-todo karies o-tabernáculo');
INSERT INTO verses VALUES (2254, 2, 26, 18, 'e-farás a as divisões para o santuário vinte carruagem para-a-lado norte sudeste;');
INSERT INTO verses VALUES (2255, 2, 26, 19, 'e-quarenta as-carruagens prata debaixo sob vinte o kares segundo carruagens o-primeiro a-carruagem o-primeiro para-duas-de as suas mãos e-dois o-primeiro debaixo-de o kares o-único para as duas as suas mãos');
INSERT INTO verses VALUES (2256, 2, 26, 20, 'e para o lado o-tabernáculo a-segunda para a borda do-norte vinte carvalho');
INSERT INTO verses VALUES (2257, 2, 26, 21, 'e-quarenta seus senhores prata segundo senhores debaixo o keresh o-primeiro e-dois adanim debaixo o keresh o-primeiro');
INSERT INTO verses VALUES (2258, 2, 26, 22, 'e as yarkei o-tabernáculo para-o-mar vós-fará seis kareishim');
INSERT INTO verses VALUES (2259, 2, 26, 23, 'e-dois-de kareishim farás para espinhos ham-mishkan nas yarkei');
INSERT INTO verses VALUES (2260, 2, 26, 24, 'e serão תֹֽאֲמִים֮ מִלְּמַטָּה֒ וְיַחְדָּ֗ו serao תַמִּים֙ sobre cabeça-sua a הַטַּבַּ֖עַת será assim será לִשְׁנֵיהֶ֔ם para-dois הַמִּקְצֹעֹ֖ת ser-ão');
INSERT INTO verses VALUES (2261, 2, 26, 25, 'e-sejam oito קְרָשִׁ֔ים וְאַדְנֵיהֶ֣ם prata seis dez אֲדָנִ֑ים segundo אדנים debaixo הַקֶּ֣רֶשׁ o-primeiro e-dois אדנים debaixo הַקֶּ֥רֶשׁ o-primeiro');
INSERT INTO verses VALUES (2262, 2, 26, 26, 'e-farás [בְרִיחִ֖ם] madeiras-de acácia [חֲמִשָּׁ֕ה] [לְקַרְשֵׁ֥י] [צֶֽלַע־הַמִּשְׁכָּ֖ן] o-primeiro');
INSERT INTO verses VALUES (2263, 2, 26, 27, 'e-cinco בְרִיחִ֔ם לְקַרְשֵׁ֥י canela- o-tabernáculo a-segunda e-cinco nos-ferraduras para-creshe- canela o-tabernáculo para-as-jarcas- para-o-mar');
INSERT INTO verses VALUES (2264, 2, 26, 28, 'e-briqah- o-tikhon- no-meio-de os-karashim- em-briqah- de o-ketzeh- a o extremo:');
INSERT INTO verses VALUES (2265, 2, 26, 29, 'e-a as divisões ouro ouro e-a ouro farás ouro casarim para os bordados ouro a os bordados ouro');
INSERT INTO verses VALUES (2266, 2, 26, 30, 'e estabelecerás a ham-mishkan como juízo dele que vê na-montanha');
INSERT INTO verses VALUES (2267, 2, 26, 31, 'e-farás faraóque tchelãz e-púrpura e-carmesim segundo e-seis מָשָׁזַר obra-de חֹשֵׂב ele-fará a-ela כּוּרְבִים׃');
INSERT INTO verses VALUES (2268, 2, 26, 32, 'e-darás אֹתָהּ sobre אַרְבַּעָה֙ colunas-de שִׁיטִים ouro ouro ouro ouro sobre quatro אַדְנֵי־ prata:');
INSERT INTO verses VALUES (2269, 2, 26, 33, 'e-darás a debaixo em-lugar-de הַקּרָסִים֒ וְהֵבֵאתָ֥ lá-baixo de-casa-de לַפָֹּרֹכֶת a arca o-testemunho וְהִבְדִּילָ֤ה a-vós entre entre e-entre e-entre santidade-de os-santos');
INSERT INTO verses VALUES (2270, 2, 26, 34, 've''nata''ta a sobre sobre arca a testemunha no-sagrado os-santos');
INSERT INTO verses VALUES (2271, 2, 26, 35, 'e colocaste a o shulḥan de-fora perante o parokhet e-a a menorá sobre o shulḥan sobre canto o-tabernáculo para o timna'' e o shulḥan põe sobre canto צָפֽוֹן׃');
INSERT INTO verses VALUES (2272, 2, 26, 36, 'e-farás כַּפֶּר para-a-entrada-de a-tenda תכלת e-púrpura e-carmesim segundo e-seis משזר obra-de ROOM:');
INSERT INTO verses VALUES (2273, 2, 26, 37, 'e-farás לכפר cinco colunas-de שִׁיטִים וְצִפִּיתָ֤ eles ouro ויהם ouro ויצקת a-eles חמישה Adonai bronze');
INSERT INTO chapters VALUES (77, 2, 27, 21);
INSERT INTO verses VALUES (2274, 2, 27, 1, 'e-farás a o-altar árvores-de acácia cinco אמות comprimento-o והמשה côvados largura-o será yihye o altar e três côvados sua altura');
INSERT INTO verses VALUES (2275, 2, 27, 2, 'e-farás suas cornetas sobre quatro suas pontas nós serão suas cornetas וְצִפִּיתָ֥ ele bronze');
INSERT INTO verses VALUES (2276, 2, 27, 3, 'e-farás suas chamas para alimentá-lo e seus óleos e suas vasilhas e seus vasos e as suas cavas para-todo כְּלֵיָיו farás bronze');
INSERT INTO verses VALUES (2277, 2, 27, 4, 'e-farás para-ele de-machbar obra-de rede bronze e-farás sobre da-rede quatro טַבְּעֹ֣ת sobre sobre quatro os-seus-filhos-');
INSERT INTO verses VALUES (2278, 2, 27, 5, 'e-darás aquela debaixo o-altar de-malate e-foi da-rede até até o-altar');
INSERT INTO verses VALUES (2279, 2, 27, 6, 'e-farás de-cápsulas למזבח em-cápsulas árvores-de acácia וְצִפִּיתָ֥ eles bronze');
INSERT INTO verses VALUES (2280, 2, 27, 7, 'e vindo a varas-de-ela e-sejam e-serão os abdins sobre duas costelas ele em-se ele');
INSERT INTO verses VALUES (2281, 2, 27, 8, 'nabub luchot farás ele como a-rea a-teca na-montanha assim façam');
INSERT INTO verses VALUES (2282, 2, 27, 9, 'e farás a átrio-de ham-mishkan para-a NEGUE- TIYMANAH KLAEIM LECHATSER seis משזער cem BAAMAH comprimento LAFEH HA''ECHAT:');
INSERT INTO verses VALUES (2283, 2, 27, 10, 'e-seus-pilares vinte VE''ADNEIM ESREIM bronze e-ganchos-de HA''AMMUDIM e-seus-órgãos-reprodutivos כַּסֶּפֶת׃');
INSERT INTO verses VALUES (2284, 2, 27, 11, 'e-assim -lado-esquerdo -norte -no-lado-direito -costelas cem comprimento -vinte -e-seus-órgãos-genitais -vinte bronze e-ganchos-de os-pilares e-seus-órgãos-reprodutivos כַּסֶּפֶת׃');
INSERT INTO verses VALUES (2285, 2, 27, 12, 'e largura o-pateo às laterais de mar cortinas cinquenta jardim e suas colunas dez e seus enredados dez');
INSERT INTO verses VALUES (2286, 2, 27, 13, 'e-largura o-pátio às laterais de leste oeste cinquenta jardim; jardim:');
INSERT INTO verses VALUES (2287, 2, 27, 14, 'וַחֲמֵ֨שׁ doze אַמָּ֛ה קְלָעִ֖ים לַכָּתֵ֑ף עַמֻּדֵיהֶ֣ם שְׁלֹשָׁ֔ה וְאַדְנֵיהֶ֖ם três');
INSERT INTO verses VALUES (2288, 2, 27, 15, 'וְלַכָּתֵף֙ הַשֵּׁנִ֔ית cinco dez קְלָעִ֑ים os seus pilares três e suas cortinas três');
INSERT INTO verses VALUES (2289, 2, 27, 16, 'e ao portão o-haçatsér cobertura vinte côvado túrgida argila vermelho segundo e-seis verde obra-de azul os seus pilares quatro quatro quatro');
INSERT INTO verses VALUES (2290, 2, 27, 17, 'todo pilares o pátio ao-redor forrados prata e neles prata e as suas bases bronze');
INSERT INTO verses VALUES (2291, 2, 27, 18, 'comprimento o pátio cem de um côvado e a largura de cinquenta cinquenta e levante-se cinco côvados seis mancebo e seus anciãos bronze');
INSERT INTO verses VALUES (2292, 2, 27, 19, 'a-todo utensílios-de o-tabernáculo em-todo sua servidão e-todo suas testemunhas e-todo testemunhem o recinto bronze');
INSERT INTO verses VALUES (2293, 2, 27, 20, 'e-tu ordene a filhos-de Israel e tomem eleicha óleo oliveira zāḵ kāṯı̂ṯ lammāʾōr lehaʿalōṯ neṛ sempre');
INSERT INTO verses VALUES (2294, 2, 27, 21, 'em-tenda-de moʾēḏ de-fora lappārōḵeṯ que sobre hāʿedūṯ ele ʾothō Aarao e-filhos-dele meʿereḇ até yhwh diante-de eternidade estatuto-de eterno para-generaçőes-elas de-com filhos-de Israel');
INSERT INTO chapters VALUES (78, 2, 28, 43);
INSERT INTO verses VALUES (2295, 2, 28, 1, 'e-tu que-approxime-se a-te a Aarao seu-irmão e-a filhos-seus de-mais filhos-de Israel para-sacerdote-o a-mim arão nadav e-abiahu Eleazar e-itamar filhos-de Aharon');
INSERT INTO verses VALUES (2296, 2, 28, 2, 'e-farás roupas-o santidade para-arão seu-irmão para-honra e-beleza:');
INSERT INTO verses VALUES (2297, 2, 28, 3, 'e-tu fale a todo sabedoria- espírito que plenitude-dele espírito sabedoria e-façam a vestes- Aarao para-santificação para-sacerdócio- a-mim');
INSERT INTO verses VALUES (2298, 2, 28, 4, 've-Eleh os vestuários que façam choshen e ephod e m''ail e k''tonet tashbets m''znefet e ''abnet וְעָשׂ֨וּ vestuários- קדוש para-Aaron אחיך e-para-seus-filhos לכהנו- a-mim');
INSERT INTO verses VALUES (2299, 2, 28, 5, '[וְהֵם֙] [יִקְח֣וּ] a [וְאֶת־הַתְּכֵ֖לֶת] e-[OBJ] [וְאֶת־תּוֹלַ֥עַת] e-[OBJ] [וְאֶת־הַשֵּֽׁשׁ׃] e-[OBJ] e-[OBJ]');
INSERT INTO verses VALUES (2300, 2, 28, 6, 'ועשוּ a ouro זהב תכלת וargaman תולעת segundo e-seis משzar obra-de choshev');
INSERT INTO verses VALUES (2301, 2, 28, 7, 'שתים as-ombreiras חבורות sera לו a segundo קצואיו e-chur:');
INSERT INTO verses VALUES (2302, 2, 28, 8, 'e-heshév apuddáto que sobre-ele kém-áshehu nós será ouro tékhelet e-púrpura e-carmesim segundo e-seis máshazar:');
INSERT INTO verses VALUES (2303, 2, 28, 9, 'e-lakachtá a shtéi pedras-de shoham e-pitachtá sobre-eles שֵׁמֹות filhos-de Israel');
INSERT INTO verses VALUES (2304, 2, 28, 10, 'seis מִשְׁמֹתָם sobre a-pedra a-uma e-a שֵׁמֹות הַשִּשָּה הַנּוֹתָרִים sobre הָאֵבֶן a-segunda כּוֹתְלֹדְתֵיהֶם׃');
INSERT INTO verses VALUES (2305, 2, 28, 11, 'obra-de [חָרַשׁ֮] pedra [פִּתּוּחֵ֣י] [חֹתָ֗ם] [תְּפַתַּח֙] a duas [עַל־שְׁמֹ֖ת] sobre [יִשְׂרָאֵ֑ל] filhos-de Israel ouro [תַּעֲשֶׂ֥ה] eles');
INSERT INTO verses VALUES (2306, 2, 28, 12, 'וְשַׂמְתָּ a duas sobre sobre כִּתְפֹת הָאֵפֹד pedras-de זִכָּרוֹן aos-filhos-de Israel וְנָשָׂא Aarao a yhwh diante-de yhwh sobre duas-de כְּתֵפָיו para lembrança:');
INSERT INTO verses VALUES (2307, 2, 28, 13, 'e-farás [מִשְׁבְּצֹ֖ת] ouro');
INSERT INTO verses VALUES (2308, 2, 28, 14, 'e-duas de-shársharót ouro puro [מִגְבָּלֹ֛ת] farás eles obra-de ábôt e-teráhatá a de-shársharót as-abót sobre [sem-traducao]');
INSERT INTO verses VALUES (2309, 2, 28, 15, 'e farás chóshén מִשְׁפָּט֙ obra-de חֹשֵׁ֔ב כְּמַעֲשֵׂ֥ה אֵפֹ֖ד תַּעֲשֶׂ֑נּוּ ouro תְּכֵ֨לֶת וְאַרְגָּמָ֜ן וְתוֹלַ֧עַת segundo e-seis מָשְׁזָ֖ר farás ele');
INSERT INTO verses VALUES (2310, 2, 28, 16, 'רָב֥וּעַ será כָּפ֑וּל זֶ֥רֶת seu-comprimento וְזֶ֥רֶת רָחְבּֽוֹ׃');
INSERT INTO verses VALUES (2311, 2, 28, 17, 'וּמִלֵּאתָ֥ nele מִלֻּ֣אַת pedra quatro טוּרִ֣ים pedra ט֗וּר homem פִּטְדָה֙ וּבָרֶ֔קֶת הַטּוּר o-primeiro');
INSERT INTO verses VALUES (2312, 2, 28, 18, 'וְהַטּ֖וּר o-segundo נֹ֥פֶךְ סַפִּ֖יר וְיָהֲלֹֽם׃');
INSERT INTO verses VALUES (2313, 2, 28, 19, 'וְהַטּ֖וּר o terceiro לֶ֥שֶׁם שְׁב֖וֹ וְאַחְלָֽמָה׃');
INSERT INTO verses VALUES (2314, 2, 28, 20, 'וְהַטּוּר֙ o-quarto תַּרְשִׁ֥ישׁ וְשֹׁ֖הַם וְיָשְׁפֵ֑ה מְשֻׁבָּצִ֥ים ouro serão בְּמִלּוּאֹתָֽם׃');
INSERT INTO verses VALUES (2315, 2, 28, 21, 'וְ֠הָאֲבָנִים תִּֽהְיֶ֜ינתּ sobre שְׁמֹ֧ות filhos-de Israel dois dez sobre שְׁמֹתָ֑ם פִּתּוּחֵ֤י חֹתָם homem sobre seu-nome seja-ela para-dois dez שָֽׁבֶט׃');
INSERT INTO verses VALUES (2316, 2, 28, 22, 'וְעָשִׂ֧יתָ sobre o-bolsa-de-terrazinhos [גַּבְלֻ֖ת] gabelut obra-de ouro ouro puro');
INSERT INTO verses VALUES (2317, 2, 28, 23, 'וְעָשִׂ֙יתָ֙ sobre o choshen shtéi ouro ouro ve-natattaa- a dois-de ha-tabbawot sobre segundo pontas o choshen');
INSERT INTO verses VALUES (2318, 2, 28, 24, 'e dará a dois-de o-ouro o-ouro sobre duas as plantas a cortos o choshen');
INSERT INTO verses VALUES (2319, 2, 28, 25, 'e-a duas cortos duas as ondas darás sobre duas os mizbóts e dará sobre כּ-תְּפֹת ה-אֵפֹד a מ-וּל faces-suas');
INSERT INTO verses VALUES (2320, 2, 28, 26, '[וְעָשִׂ֗יתָ] [שְׁתֵּי֙] [טַבְּע֣וֹת] ouro [וְשַׂמְתָּ֣] eles sobre segundo [הַחֹ֑שֶׁן] [עַל־שְׂפָת֕וֹ] sobre [אֶל־עֵ֥בֶר] que a');
INSERT INTO verses VALUES (2321, 2, 28, 27, 'וְעָשִַׂיתָ֮ duas טַבְּע֣וֹת ouro e-darás eles sobre שְׁתֵּי֩ כִתְפ֨וֹת הָאֵפ֤וֹד מִלְּמַ֙טָּה֙ מִמּ֣וּל rosto-dele como מֶחְבַּרְתּ֑וֹ מִמַּ֕עַל לְחֵ֖שֶׁב הָאֵפֽוֹד׃');
INSERT INTO verses VALUES (2322, 2, 28, 28, 'e se firmarão a o choshen a tavuot a efdod em fital tecelagem-azul ser sobre chesheb a efdod e-não de-cima-de o choshen de-sobre a efdod:');
INSERT INTO verses VALUES (2323, 2, 28, 29, 'e levantou Aharon a nomes filhos-de Israel no-bexen a-mispat sobre para-seu-coração em-vir-seu a a-santidade para-lembrança diante-de yhwh sempre');
INSERT INTO verses VALUES (2324, 2, 28, 30, 'e deu-a a bexen a-mispat a e-sejam e-a os-tumim וְהָיוּ֙ sobre yhwh Arão בְּבוֹא֖וֹ diante-de yhwh e levantou Aharon yhwh juízo filhos-de Israel sobre seu-lábbo diante-de yhwh sempre');
INSERT INTO verses VALUES (2325, 2, 28, 31, 've''asitā a mí-ail há-efód klíl תְּכֵלֶת׃');
INSERT INTO verses VALUES (2326, 2, 28, 32, 'e-será pí- cabeça-sua bétokhów será yihye líféwy sáviv obra-de órég כפי תחרא não a-ele não יתקרע׃');
INSERT INTO verses VALUES (2327, 2, 28, 33, 'e-farás sobre שולהיו רימוני תכלת וארגמן ותולעת segundo sobre שולהיו ouro ופעמןiei zahav no-entre-vocês ao-redor');
INSERT INTO verses VALUES (2328, 2, 28, 34, '[פַּעֲמֹ֤ן] ouro [וְרִמּ֔וֹן] [פּֽ͏ַעֲמֹ֥ן] ouro [וְרִמּ֑וֹן] sobre [הַמְּעִ֖יל] [סָבִֽיב]');
INSERT INTO verses VALUES (2329, 2, 28, 35, 'e-será sobre Aarao לְשָׁרֵ֑ת וְנִשְׁמַ֣ע ק֠וֹלוֹ בְּבֹא֨וֹ a yhwh diante-de yhwh וּבְצֵאת֖וֹ e-não não');
INSERT INTO verses VALUES (2330, 2, 28, 36, 'e-farás צִּ֖יץ ouro puro e abraque sobre-ele פִּתּוּחֵ֣י חתם santidade a-yhwh');
INSERT INTO verses VALUES (2331, 2, 28, 37, '[וְשַׂמְתָּ֤] ele sobre [תְּכֵ֔לֶת] [וְהָיָ֖ה] [עַל־הַמִּצְנָ֑פֶת] sobre [פְּנֵֽי־הַמִּצְנֶ֖פֶת] será');
INSERT INTO verses VALUES (2332, 2, 28, 38, 'e-será-que sobre מֵצַח Aharon- וְנָשָׂא Arão a iniquidade os-santos que יַקְדִּישׁוּ filhos-de Israel para-todo מתנות seu-sagrados e-será a-eles fronte-sua yhwh para-alegria a-eles diante-de yhwh');
INSERT INTO verses VALUES (2333, 2, 28, 39, 'e-tocaste a-camisa seis e-tu-farás cabeça-cobrindo seis e-tingido vós-fará obra-de tiraste:');
INSERT INTO verses VALUES (2334, 2, 28, 40, 'e-por-filhos Arão farás manto-sua e-farás a-eles אבנטים ומגבעות farás a-eles לכבוד לתיפארת');
INSERT INTO verses VALUES (2335, 2, 28, 41, 'והילבשת eles a Aarão irmão-teu e-a seus-filhos eles ומשחת -os -Identifier eles ידם WKידשת eles WKחnano a-mim');
INSERT INTO verses VALUES (2336, 2, 28, 42, 'e faça a-eles de entradas- bada para cobrir de-carne nudez de coxas- e-até coxas ser-ão');
INSERT INTO verses VALUES (2337, 2, 28, 43, 'e-sejam sobre Aarao e-sobre -seus-filhos em entrá-los a tenda מוֹעֵ֗ד ou na coito-los a o-altar para servir no santuário e-não eternidade a-ele va-metu chuq-at a-ele para-ele e para semente dele atrás-dele');
INSERT INTO chapters VALUES (79, 2, 29, 46);
INSERT INTO verses VALUES (2338, 2, 29, 1, 'e isto a palavra que a-eles a-eles eles eles para sacerdote a-mim tomou um um filho-de manhã e olivos dois temimim-');
INSERT INTO verses VALUES (2339, 2, 29, 2, 'e pão de-maçãs e biscoitos não-fermentados misturados com-o óleo e biscoitos-de não-fermentados ungidas -com-óleo farinha-fina trigo farás eles');
INSERT INTO verses VALUES (2340, 2, 29, 3, 'e-tu-porás a-eles sobre um um eles eles no cesto e- הפר e-a segundo ha-eilim-');
INSERT INTO verses VALUES (2341, 2, 29, 4, 'e-a אַהֲרֹן e-a filhos-dele תַּקְרִ֔יב a entrada eles reunião וְרָחַצְתָּ֥ eles com-a-água');
INSERT INTO verses VALUES (2342, 2, 29, 5, '[וְלָקַחְתָּ֣] a [וְהִלְבַּשְׁתָּ֤] [אֶֽת־אַהֲרֹן֙] a e-[OBJ] a [הָאֵפֹ֔ד] e-[OBJ] [וְאֶת־הַחֹ֑שֶׁן] [וְאָפַדְתָּ֣] a-ele [בְּחֵ֖שֶׁב] e-[OBJ]');
INSERT INTO verses VALUES (2343, 2, 29, 6, 'e-tu-colocarás הַמִּצְנֶ֖פֶת sobre sua-cabeça וְנָתַתָּ֛ a diadema eles sobre הַמִּצְנָֽפֶת׃');
INSERT INTO verses VALUES (2344, 2, 29, 7, 'e-tomarás a óleo o-mishcha וְיָצַקְתָּ֖ sobre ele וּמָשַׁחְתָּ֖ ele');
INSERT INTO verses VALUES (2345, 2, 29, 8, 'e-a seus-filhos תַּקְרִ֑יב vehilbashtam כֻּתֳּנֹֽת׃');
INSERT INTO verses VALUES (2346, 2, 29, 9, 'וְחָגַרְתָּ֩ eles אַבְנֵ֜ט Aarão e-seus-filhos וְחָבַשְׁתָּ֤ a-eles migbaot e-será a-eles כְּהֻנָּ֖ה para a lei eternidade וּמִלֵּאתָ֥ יֽ͏ַד־ Aarao não seus filhos:');
INSERT INTO verses VALUES (2347, 2, 29, 10, 'וְהִקְרַבְתָּ֙ a הפר diante-de tenda reunião וְסָמַ֨ךְ Aarao e-filhos-dele a maos-deles sobre cabeça הַפָּֽר׃');
INSERT INTO verses VALUES (2348, 2, 29, 11, 'וְשָׁחַטְתָּ֥ a o-touro yhwh yhwh entrada tenda encontro');
INSERT INTO verses VALUES (2349, 2, 29, 12, 'e-tomarás de-sangue-de הפר e dará sobre cornos o-altar em-teus-azymes e-a todo do-sangue tu-serrarás a base o-altar');
INSERT INTO verses VALUES (2350, 2, 29, 13, 'e tomarás a todo o-chalev a-que-cobre a o-qerev e-a o-lóbulo sobre o-fígado e-את duas os-rins e-a o-gordura que neles e oferecerás o-altar-para');
INSERT INTO verses VALUES (2351, 2, 29, 14, 'e-a carne o-touro e-a seu-oro e-a ele-estendeu tu-queimarás no-fogo ele para-o-lager pecado ela');
INSERT INTO verses VALUES (2352, 2, 29, 15, 'e-a o-primeiro o-único to-peça e-sustentem Aarao e-filhos-dele a maos-deles sobre cabeça o-abelhaue');
INSERT INTO verses VALUES (2353, 2, 29, 16, 'e-masacrarem a o-velho e-tomarás a seu-sangue e-jetastes sobre ele ao-redor');
INSERT INTO verses VALUES (2354, 2, 29, 17, 'e- o-abelhaue despedaçaste para-seus-nicotamentos e-lavaste sua-fenda e-sus-pés e-dar-tei-a sobre as-águas e-sobre cabeça-dele');
INSERT INTO verses VALUES (2355, 2, 29, 18, 'e-oferecereis-o a todo o-velo ele holocausto ele para-יהוה aroma um-cheiro ele a-yhwh ela');
INSERT INTO verses VALUES (2356, 2, 29, 19, 'e-tomareis-o a o-touro o-segundo e-sustentareis-o Aarao e-filhos-dele a maos-deles sobre cabeça o-abelhaue');
INSERT INTO verses VALUES (2357, 2, 29, 20, 'e-imirareis-o a o-velo e tomaste de-sua-mão e deste sobre formado orelha Arão e-sobre formado orelha filhos-dele a-direita e-sobre neles yadam a-direita e-sobre bohen de-seus-pés a-direita e lançaste a o-sangue sobre ele ao-redor');
INSERT INTO verses VALUES (2358, 2, 29, 21, 'e tomaste de o-sangue que sobre o Mizbach e o shemen o mashachah e zita sobre Arão e-sobre as-roupas-seu e-sobre ele e-sobre de-roupas filhos-dele com-ele e kodesh que e os begadav e-filhos-dele e os bigdei filhos-dele com-ele');
INSERT INTO verses VALUES (2359, 2, 29, 22, 'וְלָקַחְתָּ de o ayil a-gordura e ha-aliyah e-a o chalbe a-que-cobre a o keruv e-a yoteret do-fígado e-את duas ha-klayot e-a que sobre-eles e-a coxa que porque eil ele ela');
INSERT INTO verses VALUES (2360, 2, 29, 23, 've-ikkar pão uma va-hallat pão shemen uma ve-rakik um mis-sal ha-matzot que diante-de yhwh');
INSERT INTO verses VALUES (2361, 2, 29, 24, 'vesamta o todo sobre mãos-de Arão e-sobre mãos-de seus-filhos e enfarinharás eles oferta-elevação diante-de yhwh');
INSERT INTO verses VALUES (2362, 2, 29, 25, 'e tomarás eles imediatamente deles e oferecerás em fumaça o-altar sobre o-holocausto por odor cheiro agradável yhwh yhwh ele ele para-יהוה');
INSERT INTO verses VALUES (2363, 2, 29, 26, 'וְלָקַחְתָּ a este vislumbre do carneiro o cheio que para Arão ele ele oferta-elevação yhwh yhwh a-ti a-ti para-ele');
INSERT INTO verses VALUES (2364, 2, 29, 27, 'e santificaste com vista da-oferta e-את coxa הַתְּרוּמָ֔ה que e levantaste e-que e ergueste do elefante que estava cheio do-que para-Aarão e de suas filhas');
INSERT INTO verses VALUES (2365, 2, 29, 28, 'e-será para-Aarão e suas filhas por-tempo para sempre de-com filhos-de que porque ele ele será for me''et filhos-de Israel Mizbe''achay Shalmeim Tummatam para-יהוה');
INSERT INTO verses VALUES (2366, 2, 29, 29, 'uvgadi a-santidade que leAharon serao levanay atrás-dele lemashchah em-elas ulamel neles a yadam');
INSERT INTO verses VALUES (2367, 2, 29, 30, 'sete dias yilbasham o-sacerdote em-lugar-dele dos seus que virá a tenda encontro para servir no santuário:');
INSERT INTO verses VALUES (2368, 2, 29, 31, 'e-a o carneiro que está cheio pegará e cozinhará a a-carne-dele em algum lugar santo');
INSERT INTO verses VALUES (2369, 2, 29, 32, 'e-coma אַהֲרֹן e-filhos-dele a de-carne o-abelhaue e-a o pão que בַּסָּ֑ל entrada tenda encontro');
INSERT INTO verses VALUES (2370, 2, 29, 33, 'וְאָכְל֤וּ eles que כֻּפַּ֣ר neles לְמַלֵּ֥א a mão-deles eles a-eles וְזָ֥ר não eles porque santidade-de eles');
INSERT INTO verses VALUES (2371, 2, 29, 34, 'וְֽאִם־ יִוָּתֵ֞ר מִבְּשַׂ֧ר הַמִּלֻּאִ֛ים e-de הַלֶּ֖חֶם até הַבָּקֵ֑ר não a o-restante ele não será comido porque santidade-de ela');
INSERT INTO verses VALUES (2372, 2, 29, 35, 'e farás para Arão e-para-seus-filhos assim conforme-tudo que ordenei isto sete dias preencherá suas mãos:');
INSERT INTO verses VALUES (2373, 2, 29, 36, 'e um carneiro de oferta de reconciliação farás para o dia sobre as-cuprires e-acharites-a sobre o altar em-te-cuprires ele e-ungires a-ele para-santificá-lo-verso-final');
INSERT INTO verses VALUES (2374, 2, 29, 37, 'sete dias cuprires-te sobre o altar ele a-ele e-será o-altar santo-de santos todo da-pessoa-que-tocou no-mizbeach ele-será-santificado');
INSERT INTO verses VALUES (2375, 2, 29, 38, 'e-este que vós-fará sobre o-altar cordeiros filhos-de ano dois para-o-dia sempre');
INSERT INTO verses VALUES (2376, 2, 29, 39, 'a o-primeiro o-um farás no-manha e-את o carneiro o-segundo entre entre os-pardais');
INSERT INTO verses VALUES (2377, 2, 29, 40, 'e a décima farinha-de-trigo moído em óleo de cevada quarto deste vinho ve-nesech reviit הַהִ֖ין vinho לכּבשׂ o-primeiro');
INSERT INTO verses VALUES (2378, 2, 29, 41, 'e-את o carneiro o-segundo vós-fará entre הָעַרְבָּ֑יִם כמנחת הבקר ukhniskah fazer- para-a para-aroma agradavel mulher para-יהוה');
INSERT INTO verses VALUES (2379, 2, 29, 42, 'holocausto-de contínuo para-gerações-vossas porta tenda-de encontro yhwh yhwh que a-vós a-vós ali de-falar a-ti nome');
INSERT INTO verses VALUES (2380, 2, 29, 43, 'e-congregar-ei-me para lá aos-filhos-de Israel e-santificar-se-há-de com-a-minha-glória-versículo-final');
INSERT INTO verses VALUES (2381, 2, 29, 44, 'e-santificar-ei-me a tenda encontro e-a o-altar e-a Aarao e-a ele eu-santificarei para-servir a-mim');
INSERT INTO verses VALUES (2382, 2, 29, 45, 'e-habitar-ei-me no-meio-de filhos-de Israel e-eu-serei a-eles para-Elohim');
INSERT INTO verses VALUES (2383, 2, 29, 46, 'e-conhecerão que eu yhwh אֱלֹ֣הֵיהֶ֔ם que saí-ei eles da-terra-de Egito para-a-sua-habitação בְתוֹכָ֑ם eu yhwh אֱלֹהֵיהֶם-de-eles');
INSERT INTO chapters VALUES (80, 2, 30, 38);
INSERT INTO verses VALUES (2384, 2, 30, 1, 'e-farás altar de-o-fumaceiro fumo-de-oferenda de troncos de carmelitas farás ele');
INSERT INTO verses VALUES (2385, 2, 30, 2, 'cubit-o o-seu-comprimento e um palmo a-sua-largura quadrado será e-duas-coudernas a-sua-altura nós os-seus-chifres');
INSERT INTO verses VALUES (2386, 2, 30, 3, 'e-cobri-e ele ouro טהור a [וְאֶת־קִירֹתָ֛יו] e-a [וְאֶת־קַרְנֹתָ֑יו] ao-redor para-ele suas cornetas ouro לו זֵ֥ר ouro ao-redor');
INSERT INTO verses VALUES (2387, 2, 30, 4, '[וּשְׁתֵּי֩] [טַבְּעֹ֨ת] ouro tu-farás [׀] debaixo-de para-seu-fio sobre duas [צַלְעֹתָ֔יו] vós-fará sobre segundo [וְהָיָה֙] e-foi para quartos separadamente ele ele animal');
INSERT INTO verses VALUES (2388, 2, 30, 5, 'e-farás a [עֲצֵ֣י] árvores-de acácia eles ouro');
INSERT INTO verses VALUES (2389, 2, 30, 6, 'וְנָתַתָּ֤ ele diante-de o-véu que sobre arão a testemunha diante-de a propiciação que sobre a testemunho a-ti אִוָּעֵ֥ד a-ti ali');
INSERT INTO verses VALUES (2390, 2, 30, 7, 'e-ele-queimou sobre-ele Aarao fumo [סַמִּ֑ים] ba-voker na-manhã em-ben-a-o a as-luzes queimará-as');
INSERT INTO verses VALUES (2391, 2, 30, 8, 'e-em-oferendas-de-ascensão Aarao a entre entre as-vésperas queimará-as fumegante permanente yhwh yhwh para-gerações-de-vocês');
INSERT INTO verses VALUES (2392, 2, 30, 9, 'não subireis sobre-ele fumegante זרעה e-oferta e-minchah não não tiss-khu sobre-ele');
INSERT INTO verses VALUES (2393, 2, 30, 10, 've-chipp-er Arão sobre uma uma בשנה mid-dam chéttā''ath uma uma b-shana ye-chapp-per sobre-ele para-gerações-vossas ele qo-da-shim ele para-יהוה');
INSERT INTO verses VALUES (2394, 2, 30, 11, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (2395, 2, 30, 12, 'que tis-sa a cabeça ben-ei- Israel li-pqu-dey-hem ve-nath-no homem koper nafsho eles bifqod a-eles e-não será eles negef bifqod eles');
INSERT INTO verses VALUES (2396, 2, 30, 13, 'este yittenu todo haover sobre os-contados machatzit hashqelet em-siclo a-santidade vinte gerah hashqelet מחצית o-sheqel dádiva-feminina-singular la-yhwh:');
INSERT INTO verses VALUES (2397, 2, 30, 14, 'todo o-que-passa sobre os-contados מִבֶּ֛ן vinte ano e-para-cima irá dar yhwh yhwh');
INSERT INTO verses VALUES (2398, 2, 30, 15, 'o-rico não aumentará não não diminuirá de-meio o-sheqel לָתֵת֙ yhwh oferta-de yhwh para-ter-expiação sobre almas-vosso');
INSERT INTO verses VALUES (2399, 2, 30, 16, 'e tomaste a prata [מֵאֵת֙] de-com filhos-de Israel ele a-ele sobre avodat tenda reunião e-será para-os-filhos-de Israel yhwh diante-de yhwh para-ter-expiação sobre almas-vosso');
INSERT INTO verses VALUES (2400, 2, 30, 17, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (2401, 2, 30, 18, 'e farás [כִּיּ֥וֹר] de-cobre e-seu-copo bronze para-lavar-a-si-mesmo e-colocarás ele entre tenda-de e-entre e-entre o altar e-dar-tei-a para lá águas');
INSERT INTO verses VALUES (2402, 2, 30, 19, 'e-lavaram Aarão e-seus-filhos nós a maos-deles e-a seus-pés');
INSERT INTO verses VALUES (2403, 2, 30, 20, 'em-a-sua-entrada a tenda encontro lavarão-se águas e-não morrerão ou na coito-los a o-altar para-servir para-queimar mulher para-יהוה');
INSERT INTO verses VALUES (2404, 2, 30, 21, 'e-lavaram mãos-deles e-pés-deles e-não morrem e-será a-eles lei- a-ele a-ele e-para-seu-descendente para-gerações-eles');
INSERT INTO verses VALUES (2405, 2, 30, 22, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (2406, 2, 30, 23, 'e-tu toma para-vós com-perfumes cabeça amar-doce- liberdade cinco centenas e-cinzento- báscem machtítuho cinquenta e duzentos ve-qnéhe- bośém cinquenta e-duzentos');
INSERT INTO verses VALUES (2407, 2, 30, 24, 've-kiddáh cinco centenas em-siclo a-santidade ve-shémen oliveira hin:');
INSERT INTO verses VALUES (2408, 2, 30, 25, 'e-farás ele shémén mishchat- santidade roqách de-a-mistura obra-de misturador שֶֽׁמֶן será santidade será');
INSERT INTO verses VALUES (2409, 2, 30, 26, 'e-un-ganhou nele a tenda de-encontro e-a arca ha-edut:');
INSERT INTO verses VALUES (2410, 2, 30, 27, 'e-a o shulḥan e-a todo utensílios-dele e-a a-de-a-luz e-a os-seus-vesséis e-a yhwh haqtōret');
INSERT INTO verses VALUES (2411, 2, 30, 28, 'e-a altar-de a-holocausto e-a todo seu recipiente e-a o-de-o-recipientedeágua e-a como-ele');
INSERT INTO verses VALUES (2412, 2, 30, 29, 'e-santificaste eles e-sejam santo-de os-santos todo da-pessoa-que-tocou neles ele-será-santificado');
INSERT INTO verses VALUES (2413, 2, 30, 30, 'e-a Aarão e-a seus-filhos eles WKידשת eles para-o-servir a-mim');
INSERT INTO verses VALUES (2414, 2, 30, 31, 'e-a filhos-de Israel dizendo dizendo óleo será santo será este yhwh para-gerações-de-vocês');
INSERT INTO verses VALUES (2415, 2, 30, 32, 'sobre homem não não ser ungido não não fareis como ele ele ele será a-vós a-vós');
INSERT INTO verses VALUES (2416, 2, 30, 33, 'homem que fará perfume como ele e-que ele-dará nós sobre זָ֑ר e será cortado do seu povo');
INSERT INTO verses VALUES (2417, 2, 30, 34, 'E-disse yhwh a Moisés toma a-ti perfume derramará e escarlate e-oleo-de-gomasilvestre aromaticos e-olibanum sozinho de-algodao será será');
INSERT INTO verses VALUES (2418, 2, 30, 35, 'e-farás a-ela Ketoret galanga obra-de que-faz-galanga salgado puro קֹדֶשׁ׃');
INSERT INTO verses VALUES (2419, 2, 30, 36, 'e-esmagueste de-ela hadeq- e-natahtah diante-de ha-edut- em-tenda-de encontro que אִוָּעֵ֥ד a-ti a-ti santidade-de santíssimos será a-vós');
INSERT INTO verses VALUES (2420, 2, 30, 37, 've-ha-qtor-et- que farás be-matkhun-tahh- não fareis a-vós קֹ֛דֶשׁ será a-ti a-yhwh');
INSERT INTO verses VALUES (2421, 2, 30, 38, 'homem que ele-fará kamo-ha- le-harikh- nela ve-nikhrat- me-am-maw-yo-');
INSERT INTO chapters VALUES (81, 2, 31, 18);
INSERT INTO verses VALUES (2422, 2, 31, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (2423, 2, 31, 2, 'viu qara-ti em-o-nome de-Betsalel filho-de Uri filho-de Hur para-matate Judá');
INSERT INTO verses VALUES (2424, 2, 31, 3, 'e-e-preeenchi ele espírito Elohim com-a-sabedoria e-com-a-entendimento e-com-o-conhecimento e-em-todo obra');
INSERT INTO verses VALUES (2425, 2, 31, 4, 'para-pensar pensamentos para-fazer em-o-ouro e-no-prata e-no-cobre');
INSERT INTO verses VALUES (2426, 2, 31, 5, 'e-no-estanho pedra para-encher [וּבַחֲרֹ֣שֶׁת] árvore para-fazer em-todo obra');
INSERT INTO verses VALUES (2427, 2, 31, 6, 'e-eu eis dei com-ele a Ahiliv filho-de Achisamac Para-a-margem- Dã dei todo sabio coração dei sabedoria e-fazerão a todo que mandei-vos');
INSERT INTO verses VALUES (2428, 2, 31, 7, 'com tenda מוֹעֵ֗ד e-a o-arca para-a-testemunha e-a a-da-cobertura que sobre-ele e-a todo instrumentos-de o-tenda');
INSERT INTO verses VALUES (2429, 2, 31, 8, 'e-a o shulḥan e-a utensílios-dele e-a a-do-luz [מִזְבַּ֥ח] e-a todo seus-vessis e-a yhwh haqtōret');
INSERT INTO verses VALUES (2430, 2, 31, 9, 'e-a altar-de a-holocausto e-a todo seu recipiente e-a o-do-lavabo e-a e-o');
INSERT INTO verses VALUES (2431, 2, 31, 10, 'e-a das-roupas a-da-guarda e-a roupas-de a-santidade para-arão o-sacerdote e-a de-roupas filhos-dele para-servir-como-sacerdote');
INSERT INTO verses VALUES (2432, 2, 31, 11, 'e-a óleo [הַמִּשְׁחָ֛ה] e-a fumo-de das-essências para-o-santo conforme-tudo que mandei-te-eu façam');
INSERT INTO verses VALUES (2433, 2, 31, 12, 'E-disse yhwh a Moisés');
INSERT INTO verses VALUES (2434, 2, 31, 13, 'e-tu palavra a filhos-de dizendo dizendo somente a que תִּשְׁמֹ֑רוּ ela sinal ela-é entre-mim para-conhecer que para-conhecer yhwh eu yhwh מְקַדֵּשְׁכֶֽם׃');
INSERT INTO verses VALUES (2435, 2, 31, 14, 'e-guardardes a que porque ela a-vós a-vós morrendo morte-de que porque todo obra nela obra aquela a-alma a-essa de-meio-de seus-povos');
INSERT INTO verses VALUES (2436, 2, 31, 15, 'seis-de dias será feito obra e-no-dia o-sétimo sábado dia-de-sábado santidade a-yhwh todo obra obra em-dia morrendo morrer será-morto');
INSERT INTO verses VALUES (2437, 2, 31, 16, 'e-guardarão filhos-de Israel a do sabbat para-fazer a eternidade para-gerações-eles yhwh eternidade');
INSERT INTO verses VALUES (2438, 2, 31, 17, 'entre-mim e-entre filhos-de Israel sinal-de ela para-sempre porque seis-de dias yhwh yhwh a os-céus e-a a-terra e-no-dia o-sétimo שַׁבָּת e-nafash');
INSERT INTO verses VALUES (2439, 2, 31, 18, 'E-colocou a Moisés כְּכַלֹּתוֹ֙ para-falar com-ele em-monte-de Sinai segundo tabelas a testemunha pedra pedra kethubhim com-dedo-de Elohim');
INSERT INTO chapters VALUES (82, 2, 32, 35);
INSERT INTO verses VALUES (2440, 2, 32, 1, 'E-viu o-povo porque bosehesh Moisés לארדת de o-monte ve-yikkehel o-povo a-ele Arão e-disseram a-ele levanta-te aseh- a-nos Elohim que andem diante-de-nós porque este Moisés o-homem que não da-terra Egito a-ele yadonu a-ele foi a-ele');
INSERT INTO verses VALUES (2441, 2, 32, 2, 'E-disse para-eles Arão parqu nizmei o-ouro que em-orelhas-de neshechem benechem e-filhas-vossas e-trarão a-mim');
INSERT INTO verses VALUES (2442, 2, 32, 3, 'e-se-despiram todo o-povo o-ouro de-anéis o-de-ouro que em-suas-ouvidos e trouxeram- a Aharon');
INSERT INTO verses VALUES (2443, 2, 32, 4, 'E-tomou de-mãos-eles [וַיָּ֤צַר] ele com-a-gravura e-o-fez bezerro para-ídolo e-disseram Estas teu-Elohim Israel que elevaram-vos da-terra-de Egito');
INSERT INTO verses VALUES (2444, 2, 32, 5, 'E-viu Arão E-edificou altar diante-dele E-chamou Aharon E-disse festa-de a-yhwh amanhã');
INSERT INTO verses VALUES (2445, 2, 32, 6, 'e-levantaram-se de-amanhã e-subiram holocaustos e-aproximaram-se paz e-habitou o-povo para-comer וְשָׁת֔וֹ e-levantaram-se para-zombar');
INSERT INTO verses VALUES (2446, 2, 32, 7, 'e-falou yhwh a Moisés que Rede porque corrompeu o-povo-tuo que elevantes dizendo Egito');
INSERT INTO verses VALUES (2447, 2, 32, 8, 'desviaram-se rapidamente de o-caminho que tzivitim a-eles a-eles egel massakah וַיִּשְׁתַּֽחֲווּ־ a-ele Estas a-ele e-disseram estes teu-Elohim Israel que heolukha dizendo Egito');
INSERT INTO verses VALUES (2448, 2, 32, 9, 'E-disse yhwh a Moisés vi a o-povo este ele com qshe- costas ela');
INSERT INTO verses VALUES (2449, 2, 32, 10, 'e-agora hanikah a-mim veyichar- afpi neles vaakalem e-e-farei te para-povo grande');
INSERT INTO verses VALUES (2450, 2, 32, 11, 'e-e-curou-se Moisés a yhwh yhwh E-disse E-disse yhwh yhwh ele-será-ira teu-apo em-o-povo-tua que tu-e-saiu-te da-terra Egito com-a-força grande e-na-mão forte');
INSERT INTO verses VALUES (2451, 2, 32, 12, 'por-que dizem Egito dizendo em-o-mal e-saiu-os-eles para-a-exterminar eles nas-montanhas e-para-completá-los de-cima-de face-de a-terra volta de-a-ira nervo-teu e-perdoa sobre o-mal para-povo-teu');
INSERT INTO verses VALUES (2452, 2, 32, 13, 'macho para-Abram para-Isaque e-para-Israel servos-teus que juras-te a-eles sobre-ti e falou a-eles multiplicarei a semente-vosso como-os-estrelas os-céus e-todo a-terra a-esta que disse-ei- אֶתּוֹ para-sempre e-receberam para-sempre');
INSERT INTO verses VALUES (2453, 2, 32, 14, 'e-se-arrependeu yhwh sobre a-maldade que palavra para-fazer para-o-povo-suo');
INSERT INTO verses VALUES (2454, 2, 32, 15, 'e-virou e-ele-descerrou Moisés de o-monte e-dois as-tavas da-testemunho na-sua-mão as-tavas escritos de-os da-escrita-de-eles mizze eles eles escrevidos');
INSERT INTO verses VALUES (2455, 2, 32, 16, 'e-as-tábuas obra-de Elohim elas-eram e-o-machado escrita Elohim ele gravada sobre das-tábuas');
INSERT INTO verses VALUES (2456, 2, 32, 17, 'E-ouviu [יְהוֹשֻׁ֛עַ] a voz o-povo E-disse E-disse voz Moisés voz');
INSERT INTO verses VALUES (2457, 2, 32, 18, 'E-disse não-há voz anota gibura e-não-há voz anota halusha voz anana eu ouviu');
INSERT INTO verses VALUES (2458, 2, 32, 19, 'e-foi como karav a E-viu E-viu a ha-egele um-holot e-acendeu-se- tambem Moisés ve-yashleh a eles debaixo eles debaixo-de a-montanha');
INSERT INTO verses VALUES (2459, 2, 32, 20, 'E-tomou a ha-egele que fizeram e-queimou no-fogo até até que finos e-espargeu sobre face-de as-águas e-deu-de-beber a filhos-de Israel');
INSERT INTO verses VALUES (2460, 2, 32, 21, 'E-disse Moisés a Arão a-ti fez a-ti o-povo este porque levaste sobre-ele pecado grande');
INSERT INTO verses VALUES (2461, 2, 32, 22, 'E-disse Arão a certamente ira tu tu eu soube que o-povo ele com-mal ela');
INSERT INTO verses VALUES (2462, 2, 32, 23, 'e-disseram a-mim fazei- a-nos Elohim que irao diante-de-nós porque este Moisés o-homem que elevamos-nos da-terra não não sabemos a-ele foi a-ele');
INSERT INTO verses VALUES (2463, 2, 32, 24, 'וָאֹמַ֤ר a-eles para-quem ouro se-separaram e deram- a-mim e-eu-o-throwei em-a-chama e-ele-saiu o-bezerro a-esta');
INSERT INTO verses VALUES (2464, 2, 32, 25, 'E-viu Moisés a que porque ele ele porque Faraó Arão para-encontrar em-seus-lugares');
INSERT INTO verses VALUES (2465, 2, 32, 26, 'e-ele-estabeleceu Moisés no-porta o-acampamento E-disse quem a-yhwh a-mim e-eles-se-reuniram a-ele todo filhos-de Levi');
INSERT INTO verses VALUES (2466, 2, 32, 27, 'E-disse a-eles assim yhwh yhwh Elohim-de Israel שִׂ֥ימוּ homem-de sua-espada sobre em-seu-reto passai e-voltaram miša''ar a-o-portão no-acampamento e-matar-am homem-de a áhiy e-homem a E-a-terra e-homem a seu-próximo');
INSERT INTO verses VALUES (2467, 2, 32, 28, 'e-fizeram filhos-de Levi conforme-a-palavra-de Moisés [מִן־הָעָם֙] no-dia o-povo no-dia aquele em-três alfei homem');
INSERT INTO verses VALUES (2468, 2, 32, 29, 'E-disse Moisés מלאו mãos-vossas o-dia a-yhwh que homem com-seu-filho e-com-seu-irmão e-para-dar sobre-vós o-dia em-benção');
INSERT INTO verses VALUES (2469, 2, 32, 30, 'e-houve de-amanhã E-disse Moisés a o-povo vós pecado-vos pecado-a e-agora e-agora eu-elevar-ei a yhwh talvez eu-perdoarei por-causa-de pecado-vosso');
INSERT INTO verses VALUES (2470, 2, 32, 31, 'e-estabeleceu-se Moisés a yhwh E-disse por-favor pecou o-povo este pecado-a grande a-eles a-eles ouro ouro');
INSERT INTO verses VALUES (2471, 2, 32, 32, 'e-agora se levantaste pecado-vosso e-se não-há apaga-me por-favor de-teu-conto que escreveste');
INSERT INTO verses VALUES (2472, 2, 32, 33, 'E-disse yhwh a quem quem que pecou- a-mim eu-apagarei-o de-meu-conto');
INSERT INTO verses VALUES (2473, 2, 32, 34, 'e-agora vai esperaremos a o-povo a que para-ti eis eis meu-anjo irei diante-de-ti e-no-dia-de meu-exame e-eu-examinarei sobre-eles pecado-deles');
INSERT INTO verses VALUES (2474, 2, 32, 35, '[וַיִּגֹּ֥ף] yhwh a sobre sobre que fizeram a o-bezerro que fez Aharon');
INSERT INTO chapters VALUES (83, 2, 33, 23);
INSERT INTO verses VALUES (2475, 2, 33, 1, 'e-falou yhwh a Moisés folhas-de sobe tu tu e-o-povo que e-elevar-teste da-terra Egito a a-terra que juro-eu para-Abraão dizendo e-a-Jaōob dizendo para-o-semente-teu darei-eu');
INSERT INTO verses VALUES (2476, 2, 33, 2, 'e lançarei diante-de-ti anjo e-ele-expulsarei a o-cananeu o amorreu e-o-heteu e-o-perizeu o-hivi e-o-jebuseu');
INSERT INTO verses VALUES (2477, 2, 33, 3, 'a terra fluindo-de leite que não não subirei-eu que porque tu qsh- o-ref- tu para-que-não a-chel-kha- no-caminho');
INSERT INTO verses VALUES (2478, 2, 33, 4, 'E-ouviu o-povo a a-palavra o mal este va-yit-ab-balu- e-não shatu- homem e-dyo- sobre-ele');
INSERT INTO verses VALUES (2479, 2, 33, 5, 'E-disse yhwh a Moisés disse a filhos-de Israel um com qsh- o-ref- e-agora um e-eleh- be-qirv-kha- e-eu-te-cortarei e-agora fazer-descer em-tua-preciosidade me''al-eka וְאֵדְעָ֖ה que farei para-ti');
INSERT INTO verses VALUES (2480, 2, 33, 6, 'e-eles-se-espirraram filhos-de Israel a em-sua-preciosidade me-ha-mar Horov:');
INSERT INTO verses VALUES (2481, 2, 33, 7, 'e-Moshe tomará a a-tenda e-estenderá-se-a para-ele de-fora ao-acampamento o-longe de a-ele וְקָ֥רָא a-ele tenda reunião yhwh todo mevakesh yhwh ele sairá a tenda encontro que de-fora o-lager');
INSERT INTO verses VALUES (2482, 2, 33, 8, 'e-foi quando-sair Moisés a a-tenda e-levantar-se-ão todo o-povo e-parar-se-ão homem entrada-de אָהֳל֑וֹ e-ver-se-ão depois-de Moisés até quando-vir-ele a-tenda');
INSERT INTO verses VALUES (2483, 2, 33, 9, 'e-foi quando-entrar Moisés ha-ohelah descerá piléster o-nubloso e-permanecerá entrada-de haohel e falará com Moisés');
INSERT INTO verses VALUES (2484, 2, 33, 10, 'e-verá todo o-povo a piléster o-nuvem ficou-em-pé entrada-de haohel e-levantou-se todo o-povo e-adoraram homem porta a-tenda-dele');
INSERT INTO verses VALUES (2485, 2, 33, 11, 'e-falou yhwh a Moisés face a face como יְדַבֵּר homem a companheiro-seu וְשָׁב֙ a o-acampamento não Josué filho-de Nun o-jovem não יָמִ֖ישׁ de-meio o-tenda');
INSERT INTO verses VALUES (2486, 2, 33, 12, 'E-disse Moisés a yhwh tu você disse a-mim o-alto a o-povo não e-tu não me-ensinaste a que tens-lhe comigo e-tu dis-e-stu te-conheci no-nome e-também encontraste graça be-einai');
INSERT INTO verses VALUES (2487, 2, 33, 13, 'e-agora se por-favor achei graça nos-teus-olhos ensina-me por-favor a caminhos-teus e-conhecer-te-ei para encontre que em-olhos-teus e-ver porque o-povo-teu o-povo a-esta');
INSERT INTO verses VALUES (2488, 2, 33, 14, 'E-disse face-de andarão e-descansarei para-ti');
INSERT INTO verses VALUES (2489, 2, 33, 15, 'E-disse a-ele se não-há suas faces caminhando a subir-nos-eis deste-lado');
INSERT INTO verses VALUES (2490, 2, 33, 16, 'e-no-modo ser-conhecido então porque achei graça em-olhos-teus eu veamekha acaso-nao em-a-tua-andar com-nosso e-nós-te-fizemos eu וְעַמְּךָ de-todo o-povo que a-terra face-de a-terra');
INSERT INTO verses VALUES (2491, 2, 33, 17, 'E-disse yhwh a também também a a-palavra este que falaste אֶעֱשֶׂה porque encontraste graça diante de mim e-eu-conheci-te em-o-nome');
INSERT INTO verses VALUES (2492, 2, 33, 18, 'E-disse mostra-me por-favor a a-tua-glória');
INSERT INTO verses VALUES (2493, 2, 33, 19, 'E-disse eu eu-passarei todo de-seu-bem sobre perante-você yhwh em-o-nome yhwh diante-de-ti e-terei-misericórdia a que eu-virei-a-alma e-terei-compaixão a que eu-terei-compaixão');
INSERT INTO verses VALUES (2494, 2, 33, 20, 'E-disse não poderas li-roth a que porque o-homem me-virem o-homem e-viveu');
INSERT INTO verses VALUES (2495, 2, 33, 21, 'E-disse yhwh eis lugar comigo e-permanecerás sobre a-rocha');
INSERT INTO verses VALUES (2496, 2, 33, 22, 'e-foi em-o-passe a-minha-glória e-eu-te-colocarei em-a-encruzilhada o-rochedo e-eu-te-cobrirei a-minha-mão sobre-ti até [sem-traducao]');
INSERT INTO verses VALUES (2497, 2, 33, 23, 'e-eu-retirarei a כף e-você-verá a não e-minhas-faces não sejam-vistos');
INSERT INTO chapters VALUES (84, 2, 34, 35);
INSERT INTO verses VALUES (2498, 2, 34, 1, 'E-disse yhwh a Moisés esculpe- para-ti dois as-tábuas אבנים como-as-primeiras e-eu-escreverei sobre הַלֻּחֹ֔ת a as-palavras que foram sobre as-tábuas e-agora que que-você-partiu');
INSERT INTO verses VALUES (2499, 2, 34, 2, 'e-serei certo no-manhã e-subas pela-manhã a monte-de Sinai e-voc-se-estabelecer-a a-mim nome sobre cabeça a-montanha');
INSERT INTO verses VALUES (2500, 2, 34, 3, 'e-homem não subir contigo e-também homem a será-teme em-todo o-monte também o rebanho e-o-vacalho a pastorearão a de-frente a-montanha a-aquela');
INSERT INTO verses VALUES (2501, 2, 34, 4, 'e-ele-se-apartou dois tavas pedras como-as-primeiras e-ele-se-levantou Moisés pela-manhã e-subiu a monte-de Sinai yhwh ele E-tomou a-ele E-tomou em-mão-de-ele segundo as-tavas a-banim-kaf-segol');
INSERT INTO verses VALUES (2502, 2, 34, 5, 'e-ele-descerrou yhwh em-a-névoa [וַיִּתְיַצֵּ֥ב] com-ele nome E-chamou em nome de yhwh');
INSERT INTO verses VALUES (2503, 2, 34, 6, 'e-ele-passou yhwh sobre em-seus-faces E-chamou yhwh yhwh yhwh misericordioso e-gracioso longo Apaim e-grande bondade e-verdade');
INSERT INTO verses VALUES (2504, 2, 34, 7, 'guardião hesed para-mil-gerações leva [עָוֺ֛ן] e-transgressão e-pecado e-nos-purificar-á não purificar-á visitante iniquidade אָב֗וֹת sobre filhos e-sobre filhos filhos sobre terços e-sobre quartos');
INSERT INTO verses VALUES (2505, 2, 34, 8, 'e-ele-pressuroso Moisés e ardeu terra-para e-prostrou-se');
INSERT INTO verses VALUES (2506, 2, 34, 9, 'E-disse se por-favor achei graça em-olhos-teus Adonai andará- por-favor que entre-nós ele com duração-de costas ele e-perdoarás para-nosso-pecado e-para-nossa-transgressao e-nosso-posse');
INSERT INTO verses VALUES (2507, 2, 34, 10, 'E-disse eis eu cortando braço-de-paz diante todo seu-people eu-farei maravilhas que não foram-criados em-todo a-terra e-em-todo as-nações e-viu yhwh o-povo ele אתה em-seu-interior a trabalho yhwh porque nora ele que eu fez contigo');
INSERT INTO verses VALUES (2508, 2, 34, 11, 'shamar- a-ti a eu eu o-dia o-dia eis-me gorêsh mippenêcha a o amorite וְהַֽכְּנַעֲנִ֔י ve-hachitti e-o-perizeu e-o-heveu e-o-jebuseu');
INSERT INTO verses VALUES (2509, 2, 34, 12, 'hisshamer a-ti para-que-não tikhrot ברית a-terra a-terra tu tu veio sobre-ela para-que-não será lemokeš em-te');
INSERT INTO verses VALUES (2510, 2, 34, 13, 'que a mizbêchotam tittozun e-a matsevôtam quebre-vos e-a seus-bem-aventurados cortai-os');
INSERT INTO verses VALUES (2511, 2, 34, 14, 'que não inclinai-vos a-El outro que yhwh ciumento seu-nome El ciumento ele');
INSERT INTO verses VALUES (2512, 2, 34, 15, 'para-que-não cortai berith a-terra a-terra e-prostituam-se-eles depois-de elohim-deles e-imolem לֵאלֹ֣הֵיהֶ֔ם e-anunciará a-ti e-comerás de-seu-sacrifício׃');
INSERT INTO verses VALUES (2513, 2, 34, 16, 'e-toma de-filhas-dele para-filhos-teus e-adulterarão filhas-dele depois-de Elohim-deles e-adulterarão-os a filhos-teus depois-de Elohim-deles׃');
INSERT INTO verses VALUES (2514, 2, 34, 17, 'Elohim-de MASCA não farás- para-ti');
INSERT INTO verses VALUES (2515, 2, 34, 18, 'a chag os-maizot- guardar- sete comerás comer-ás massas-de-farinha que mandei-te para-o-festival novo que porque em-mês-de הָאֲבִיב֑ saíste de-Egito');
INSERT INTO verses VALUES (2516, 2, 34, 19, 'todo que-abre ventre a-mim e-todo de-seu-pecúlio lembrar-te-ás primeiro-fruto boi e-sacrifício');
INSERT INTO verses VALUES (2517, 2, 34, 20, 'e-primeiro-fruto jumento resgatar-ás bobo-she e-se não você livrará e-arpo-to todo em primogênito-de filhos-teus tífdeh e-não יֵרָאוּ֥ face-de vazios');
INSERT INTO verses VALUES (2518, 2, 34, 21, 'seis dias ta-abod e no dia ha-shevi-i תִּשְׁבֹּ֑ת be-charish u-ba-qatzir ti-shbot');
INSERT INTO verses VALUES (2519, 2, 34, 22, 'וְחַ֥ג shavuot farás a-ti be-ku-rei colheita chi-tim ve-chag o-ajuntador a-temporada ha-shana');
INSERT INTO verses VALUES (2520, 2, 34, 23, 'três [פְּעָמִ֖ים] [בַּשָּׁנָ֑ה] [יֵרָאֶה֙] todo [אֶת־פְּנֵ֛י] a face-de yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (2521, 2, 34, 24, 'porque luz-seu nações diante de ti e-estenderei a teu-limite e-não desejará homem a yhwh tuas-mulheres para-ver a face-de yhwh teu-Elohim três yhwh ano-');
INSERT INTO verses VALUES (2522, 2, 34, 25, 'não imoltes sobre חָמֵ֖ץ דַּם־ זִבְחִ֑י e-não יָלִ֣ין pela-manhã sacrifício-masculino-singular festa-de o-passo');
INSERT INTO verses VALUES (2523, 2, 34, 26, '[רֵאשִׁ֗ית] [בִּכּוּרֵי֙] [אַדְמָ֣תְךָ֔] [תָּבִ֕יא] casa yhwh teu-Elohim não [גְּדִ֖י] [בַּחֲלֵ֥ב] sua-mãe');
INSERT INTO verses VALUES (2524, 2, 34, 27, 'E-disse yhwh a Moisés escreveu- a-ti que as-palavras estes porque sobre o meu as-palavras estes cortei [sem-traducao] berith e-a Israel');
INSERT INTO verses VALUES (2525, 2, 34, 28, 'e-foi nome com dia quarenta dia pão não comer não não [שָׁתָ֑ה] não [עַל־הַלֻּחֹ֗ת] e-escreveu sobre [הַבְּרִ֔ית] a palavras-de a-aliança a-sre-t [sem-traducao]');
INSERT INTO verses VALUES (2526, 2, 34, 29, 'e-houve [בְּרֶ֤דֶת] Moisés de-montanha-de Sinai [וּשְׁנֵ֨י] [לֻחֹ֤ת] [הָֽעֵדֻת֙] pela-mão-de Moisés [מִן־הָהָ֑ר] de o-monte que não pele porque [בְּדַבְּר֥וֹ] pele sua-face [sem-traducao] com-ele');
INSERT INTO verses VALUES (2527, 2, 34, 30, 'E-viu Arão e-todo filhos-de Israel a Moisés pele [פָּנָ֑יו] pele perante-ele a-ele [sem-traducao] a-ele');
INSERT INTO verses VALUES (2528, 2, 34, 31, 'E-chamou para-eles Moisés e-retornaram a-ele Aarão e-todo [בָּעֵדָ֑ה] [וַיְדַבֵּ֥ר] e-falou Moisés a-eles');
INSERT INTO verses VALUES (2529, 2, 34, 32, 'e-depois-de assim [כָּל־בְּנֵ֣י] todo filhos-de Israel [כָּל־אֲשֶׁ֨ר] a yhwh que palavra yhwh com-ele em-monte-de Sinai');
INSERT INTO verses VALUES (2530, 2, 34, 33, 'E-terminou Moisés falando com-eles E-colocou sobre sua-face [sem-traducao]');
INSERT INTO verses VALUES (2531, 2, 34, 34, '[וּבְבֹ֨א] Moisés diante-de yhwh para-falar com-ele [יָסִ֥יר] a [עַד־צֵאת֑וֹ] até [וְדִבֶּר֙] [אֶל־בְּנֵ֣י] [יִשְׂרָאֵ֔ל] a filhos-de Israel a que [sem-traducao]');
INSERT INTO verses VALUES (2532, 2, 34, 35, 'e-viram filhos-de Israel a que Moisés pele face-de [מֹשֶׁ֑ה] face-de Moisés e-devolver-á Moisés a [לְדַבֵּ֥ר] sobre E-abençoou até quando-vir-ele de-falar com-ele');
INSERT INTO chapters VALUES (85, 2, 35, 35);
INSERT INTO verses VALUES (2533, 2, 35, 1, 'ויחל Moisés a todo assembleia E-disse Israel Estas a-eles estas-estes yhwh que eles yhwh [sem-traducao] eles');
INSERT INTO verses VALUES (2534, 2, 35, 2, 'seis-de dias [תֵּעָשֶׂ֣ה] obra e-no-dia o-sétimo será a-vós קֹ֛דֶשׁ [שַׁבַּ֥ת] [שַׁבָּת֖וֹן] a-yhwh todo nele obra obra será-morto');
INSERT INTO verses VALUES (2535, 2, 35, 3, 'não [אֵ֔שׁ] fogo em-todo [בְּי֖וֹם] em-dia a-sabáte');
INSERT INTO verses VALUES (2536, 2, 35, 4, 'E-disse Moisés a todo dizendo filhos-de Israel dizendo yhwh dizendo que ordenou yhwh para-dizer');
INSERT INTO verses VALUES (2537, 2, 35, 5, 'tomem [מֵֽאִתְּכֶ֤ם] [תְּרוּמָה֙] a-yhwh todo [נְדִ֣יב] coração-dele [יְבִיאֶ֕הָ] a oferta-de yhwh ouro e-prata e-niqureth:');
INSERT INTO verses VALUES (2538, 2, 35, 6, 'e-tekeli e-púrpura e-carmesim segundo e-seis e-azim:');
INSERT INTO verses VALUES (2539, 2, 35, 7, 'e-peles oveis vermelhas-muito e-peles tachashim וַעֲצֵ֥י [שִׂטִּֽים]');
INSERT INTO verses VALUES (2540, 2, 35, 8, 'e-óleo lammāʾōr [וּבְשָׂמִים֙] לְשֶׁ֣מֶן o-mishcha וְלִקְטֹ֖רֶת הַסַּמִּֽים׃');
INSERT INTO verses VALUES (2541, 2, 35, 9, '[וְאַ֨בְנֵי־שֹׁ֔הַם] [וְאַבְנֵ֖י] [מִלֻּאִ֑ים] [לָאֵפ֖וֹד] [וְלַחֹֽשֶׁן]');
INSERT INTO verses VALUES (2542, 2, 35, 10, 'e-todo sabio coração [וְיַעֲשׂ֔וּ] virao [כָּל־אֲשֶׁ֥ר] a yhwh que ordenou yhwh');
INSERT INTO verses VALUES (2543, 2, 35, 11, 'a [אֶֽת־אָהֳל֖וֹ] a [אֶת־קְרָסָיו֙] e-[OBJ] [אֶת־בְּרִיחָ֕ו] a [וְאֶת־אֲדָנָֽיו] e-[OBJ] a a e-[OBJ]');
INSERT INTO verses VALUES (2544, 2, 35, 12, 'a [וְאֶת־בַּדָּ֖יו] e-[OBJ] e-[OBJ] a [הַמָּסָֽךְ] e-[OBJ]');
INSERT INTO verses VALUES (2545, 2, 35, 13, 'a o mesa e-a varas-de-ela pão todo seu recipiente e-a pão-de as-faces');
INSERT INTO verses VALUES (2546, 2, 35, 14, 'e-[OBJ] o-luzeiro [וְאֶת־כֵּלֶ֖יהָ] e-[OBJ] e-[OBJ] e-[OBJ] o-luzeiro e-[OBJ]');
INSERT INTO verses VALUES (2547, 2, 35, 15, 'e-a altar-de [וְאֶת־בַּדָּ֔יו] e-a [שֶׁ֣מֶן] e-את azeite o-mishcha e-a fumo [הַפֶּ֖תַח] e-a cobriu [sem-traducao] para-a-porta o-tabernáculo');
INSERT INTO verses VALUES (2548, 2, 35, 16, 'com altar-de a-oferta e-a [וְאֶת־מִכְבַּ֤ר] o-bronze que a-ele a varas-de-ela e-a todo seu recipiente a o-de-o-recipientedeágua e-a como-ele');
INSERT INTO verses VALUES (2549, 2, 35, 17, 'a [קַלְעֵ֣י] [הֶחָצֵ֔ר] a [וְאֶת־אֲדָנֶ֑יהָ] e-[OBJ] [מָסַ֖ךְ] e-[OBJ] [הֶחָצֵֽר]');
INSERT INTO verses VALUES (2550, 2, 35, 18, 'a [הַמִּשְׁכָּ֛ן] o-tabernáculo e-a testemunhem o recinto e-a [sem-traducao]');
INSERT INTO verses VALUES (2551, 2, 35, 19, 'a de-roupas [לְשָׁרֵ֣ת] para servir [אֶת־בִּגְדֵ֤י] a roupas-de a-santidade para-arão o-sacerdote e-a de-roupas filhos-dele para-servir-como-sacerdote');
INSERT INTO verses VALUES (2552, 2, 35, 20, 'todo עֲדַ֥ת ben-ei- Israel de-a-frente-de Moisés');
INSERT INTO verses VALUES (2553, 2, 35, 21, 'e-vieram todo homem que e-tudo no seu coração e-todo que ele [הֵ֠בִיאוּ] a-ele yhwh a [אֹ֤הֶל] yhwh [וּלְכָל־עֲבֹ֣דָת֔וֹ] tenda-de encontro e-para-todo- עֲבֹ֣דָת֔וֹ [sem-traducao] o-santuário');
INSERT INTO verses VALUES (2554, 2, 35, 22, 'e-vieram os-homens sobre as-mulheres todas [נְדִ֣יב] coração heviu [חָ֣ח] [וָנֶ֜זֶם] [וְטַבַּ֤עַת] [וְכוּמָז֙] todo ouro ouro e-todo homem que ouro [לַיהוָֽה] ouro para-יהוה');
INSERT INTO verses VALUES (2555, 2, 35, 23, 'e-todo homem que foi-achado com-ele tchelãz e-púrpura e-carmesim segundo e-seis [אֵילִ֧ם] e-peles oveis vermelhas-muito e-peles tachashim [sem-traducao]');
INSERT INTO verses VALUES (2556, 2, 35, 24, 'todo [תְּר֤וּמַת] [כֶּ֙סֶף֙] prata e bronze [OBJ] a yhwh e-tudo e-todo que [אִתּ֜וֹ] com-ele de troncos de [לְכָל־מְלֶ֥אכֶת] para-todo obra-de o-trabalho [sem-traducao]');
INSERT INTO verses VALUES (2557, 2, 35, 25, 'e-todo mulher [בְּיָדֶ֣יהָ] coração [וַיָּבִ֣יאוּ] [מַטְוֶ֗ה] [אֶֽת־הַתְּכֵ֙לֶת֙] [וְאֶת־הָֽאַרְגָּמָ֔ן] a [הַשָּׁנִ֖י] e-[OBJ] a e-[OBJ]');
INSERT INTO verses VALUES (2558, 2, 35, 26, 'e-todo [אֲשֶׁ֨ר] que [לִבָּ֛ן] [אֹתָ֖נָה] [בְּחָכְמָ֑ה] [טָוּ֖וּ] [אֶת־הָעִזִּֽים] a');
INSERT INTO verses VALUES (2559, 2, 35, 27, '[וְהַנְּשִׂאִ֣ם] [הֵבִ֔יאוּ] a pedras-de [הַשֹּׁ֔הַם] e-a pedras-de os-enchimentos [לָאֵפ֖וֹד] וְלַחֹשֶׁן׃');
INSERT INTO verses VALUES (2560, 2, 35, 28, 'e-[OBJ] [וְאֶת־הַשָּׁ֑מֶן] e-[OBJ] [וּלְשֶׁ֙מֶן֙] [הַמִּשְׁחָ֔ה] [וְלִקְטֹ֖רֶת] [הַסַּמִּֽים]');
INSERT INTO verses VALUES (2561, 2, 35, 29, 'todo homem e-mulher que [לִבָּם֮] eles [לְהָבִיא֙] [לְכָל־הַמְּלָאכָ֔ה] para-todo a-obra yhwh ordenou yhwh para-fazer pela-mão-de Moisés [לַיהוָֽה׃] filhos-de Israel oferta-voluntária para-יהוה');
INSERT INTO verses VALUES (2562, 2, 35, 30, 'E-disse Moisés a filhos-de Israel chamou yhwh yhwh [בְּצַלְאֵ֛ל] de-Betsalel filho-de Uri filho-de Hur para-matate Judá');
INSERT INTO verses VALUES (2563, 2, 35, 31, 'וַיְמַלֵא ele espírito Elohim com-a-sabedoria [בִּתְבוּנָ֥ה] e-com-o-conhecimento e-em-todo obra');
INSERT INTO verses VALUES (2564, 2, 35, 32, 'e-para-inventar [מַֽחַשָׁבֹ֑ת] [לַעֲשֹׂ֛ת] em-o-ouro e-no-prata e-no-cobre');
INSERT INTO verses VALUES (2565, 2, 35, 33, 'e-no-estanho pedra para-encher [וּבַחֲרֹ֣שֶׁת] árvore para-fazer em-todo obra-de [sem-traducao]');
INSERT INTO verses VALUES (2566, 2, 35, 34, 'e-para-dar-mandamentos dar בַּלִּבּוֹ ele [וְאָֽהֳלִיאָ֥ב] filho-de [לְמַטֵּה־דָֽן] Para-a-margem- Dan:');
INSERT INTO verses VALUES (2567, 2, 35, 35, 'enchei eles [חָכְמַת־לֵ֗ב] coração [כָּל־מְלֶ֣אכֶת] todo obra-de [וְחֹשֵׁב֒] [וְרֹקֵ֞ם] [בַּתְּכֵ֣לֶת] [וּבָֽאַרְגָּמָ֗ן] [בְּתוֹלַ֧עַת] [הַשָּׁנִ֛י] [וּבַשֵּׁ֖שׁ] [וְאֹרֵ֑ג] [עֹשֵׂי֙] עֹשְׂיֵי֙ todo obra [sem-traducao] [sem-traducao]');
INSERT INTO chapters VALUES (86, 2, 36, 38);
INSERT INTO verses VALUES (2568, 2, 36, 1, 'וְעָשָׂה֩ [בְצַלְאֵ֨ל] [וְאָהֳלִיאָ֜ב] e-tudo homem sabio coração que dar yhwh sabedoria [וּתְבוּנָה֙] animal para-conhecer [לַעֲשֹׂ֔ת] a todo trabalho a-todo a-santidade yhwh que ordenou yhwh');
INSERT INTO verses VALUES (2569, 2, 36, 2, 'E-chamou Moisés a [וְאֶל־אָֽהֳלִיאָב֒] e-para [כָּל־אִ֣ישׁ] e-a todo dar yhwh coração que deu yhwh sabedoria בַּלִּבּוֹ todo que [לַעֲשֹׂ֥ת] coração-dele [sem-traducao] a a-obra [sem-traducao] a-ela');
INSERT INTO verses VALUES (2570, 2, 36, 3, 've-yikhu de-diante-de Moisés a todo [אֲשֶׁ֨ר] que [בְּנֵ֣י] filhos-de Israel [עֲבֹדַ֥ת] serviço-de o-santo [אֹתָ֑הּ] a-ela [הֵבִ֨יאוּ] a-ele para-ele ainda oferta-voluntária [בַּבֹּֽקֶר] [sem-traducao]');
INSERT INTO verses VALUES (2571, 2, 36, 4, 'e-vieram todo [הָעֹשִׂ֕ים] [OBJ] a todo obra-de a-santidade homem-de homem [sem-traducao] que eles עֹשִׂ֣ים׃');
INSERT INTO verses VALUES (2572, 2, 36, 5, 'e-disseram a Moisés [מַרְבִּ֥ים] [הָעָ֖ם] o-povo [מִדֵּ֤י] desde [לַמְּלָאכָ֔ה] [אֲשֶׁר־צִוָּ֥ה] yhwh ordenou yhwh [sem-traducao] a-ela');
INSERT INTO verses VALUES (2573, 2, 36, 6, 'E-ordenou Moisés [וַיַּעֲבִ֨ירוּ] voz [בַּֽמַּחֲנֶה֮] dizendo homem e-mulher a obra ainda obra [וַיִּכָּלֵ֥א] a-santidade e-foi-retida o-povo [sem-traducao]');
INSERT INTO verses VALUES (2574, 2, 36, 7, '[וְהַמְּלָאכָ֗ה] era [דַיָּ֛ם] para-todo a-obra para fazer a-ela e-tenha-sobra.');
INSERT INTO verses VALUES (2575, 2, 36, 8, 'e-fizeram todo sabio coração [אֶת־הַמִּשְׁכָּ֖ן] [עֶ֣שֶׂר] a o-tabernáculo dez tapumes seis משזער וּתְכֵ֤לֶת וארגמן ותולעת segundo כְּרֻבִ֛ים eles חֹשֵׁ֖ב fez eles');
INSERT INTO verses VALUES (2576, 2, 36, 9, 'comprimento-o הַיְרִיעָ֣ה הָֽאַחַ֗ת oito e-vinte na-côvado וְרֹ֙חַב֙ quatro na-côvado a cortina a-uma medida uma para-todo as cortinas');
INSERT INTO verses VALUES (2577, 2, 36, 10, '[וַיְחַבֵּר֙] a cinco uma uma a um e-cinco uma [אֶל־אֶחָֽת] uma a uma');
INSERT INTO verses VALUES (2578, 2, 36, 11, 'E-fez tules azul sobre שַׂפַּת הַיְרִיעָה a-uma de-acéu- [בַּמַּחְבָּ֑רֶת] assim fez בְּשַׂפַּת הַיְרִיעָה הַקִּיצוֹנָה בְּמַחְבֶּרֶת הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (2579, 2, 36, 12, 'cinquenta [לֻלָאֹ֗ת] fez na veste a primeira e cinquenta [לֻלָאֹ֗ת] fez em-extremidade הַיְרִיעָה que na fita a-segunda מַקְבִּילֹת֙ הַלֻּ֣לָאֹ֔ת uma a uma');
INSERT INTO verses VALUES (2580, 2, 36, 13, 'E-fez cinquenta קַרְסֵ֣י ouro [וַיְחַבֵּ֨ר] a uma uma a e-houve בַּקְּרָסִ֔ים um o-tabernáculo um');
INSERT INTO verses VALUES (2581, 2, 36, 14, 'E-fez yeru''ot ez''im le-ohel sobre ham-mishkan עשתiei- doze eles fez eles');
INSERT INTO verses VALUES (2582, 2, 36, 15, 'comprimento-o הַיְרִיעָ֣ה [הָאַחַ֗ת] sheloshim — na-côvado e-quatro covados largura הַיְרִיעָ֣ה a-uma medida uma [לְעַשְׁתֵּ֥י] dez יְרִיעֹֽת׃');
INSERT INTO verses VALUES (2583, 2, 36, 16, '[וַיְחַבֵּ֛ר] a cinco [לְבָ֑ד] [וְאֶת־שֵׁ֥שׁ] e-[OBJ] seis');
INSERT INTO verses VALUES (2584, 2, 36, 17, 'E-fez [לֻֽלָאֹ֣ת] [חֲמִשִּׁ֗ים] sobre língua הַיְרִיעָה הַקִּיצֹנָה [בַּמַּחְבָּ֑רֶת] e cinquenta [לֻלָאֹ֗ת] fez sobre língua הַיְרִיעָה הַחֹבֶ֖רֶת הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (2585, 2, 36, 18, 'E-fez קַרְסֵי bronze cinquenta [לְחַבֵּ֥ר] a ha-o-hel um um');
INSERT INTO verses VALUES (2586, 2, 36, 19, 'E-fez cobertura ao tenda peles [אֵלִ֖ים] vermelhos e-tampa peles tachashim de-acima');
INSERT INTO verses VALUES (2587, 2, 36, 20, 'E-fez a as divisões para o santuário de troncos de carmelitas que se levantam');
INSERT INTO verses VALUES (2588, 2, 36, 21, 'dez [אַמֹּ֖ת] comprimento o kares e amah וַחֲצִ֣י a amah largura o kares o-primeiro');
INSERT INTO verses VALUES (2589, 2, 36, 22, 'duas [יָדֹ֗ת] para o kares o-primeiro mesolabot uma a um assim a-todo para-todo karies o-tabernáculo');
INSERT INTO verses VALUES (2590, 2, 36, 23, 'E-fez a as divisões para o santuário vinte קְרָשִׁ֔ים para-a-lado Nebeg sul');
INSERT INTO verses VALUES (2591, 2, 36, 24, 'e-quarenta as-carruagens prata debaixo sob vinte os-karashim- segundo carruagens o-primeiro a-carruagem o-primeiro para-duas-de as suas mãos e-dois o-primeiro debaixo-de o kares o-primeiro para as duas as suas mãos');
INSERT INTO verses VALUES (2592, 2, 36, 25, 'e para o lado o-tabernáculo a-segunda para a borda norte fez vinte kareishim');
INSERT INTO verses VALUES (2593, 2, 36, 26, 'e-quarenta seus senhores prata segundo senhores debaixo o keresh o-primeiro e-dois adanim debaixo o kares o-primeiro');
INSERT INTO verses VALUES (2594, 2, 36, 27, 'e as yarkei o-tabernáculo para-o-mar fez seis kareishim');
INSERT INTO verses VALUES (2595, 2, 36, 28, 'e-dois-de kareishim fez para espinhos ham-mishkan nas yarkei');
INSERT INTO verses VALUES (2596, 2, 36, 29, 'e-sejam [תוֹאֲמִם֮] מִלְּמַטָּה֒ וְיַחְדָּ֗ו serao תַמִּים֙ a cabeça-sua a הַטַּבַּ֖עַת a-uma assim fez לִשְׁנֵיהֶ֔ם [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (2597, 2, 36, 30, 'e-sejam oito קְרָשִׁ֔ים וְאַדְנֵיהֶ֣ם prata seis dez אֲדָנִ֑ים segundo [אֲדָנִים֙] segundo adanim debaixo o kares o-primeiro');
INSERT INTO verses VALUES (2598, 2, 36, 31, 'E-fez [בְּרִיחֵ֖י] árvores-de acácia [חֲמִשָּׁ֕ה] [לְקַרְשֵׁ֥י] [צֶֽלַע־הַמִּשְׁכָּ֖ן] o-tabernáculo');
INSERT INTO verses VALUES (2599, 2, 36, 32, 'e-cinco בְרִיחִ֔ם לְקַרְשֵׁ֥י צֶֽלַע־ o-tabernáculo a-segunda e-cinco [לְקַרְשֵׁ֣י] [הַמִּשְׁכָּ֔ן] o-tabernáculo para-as-jarcas- para-o-mar');
INSERT INTO verses VALUES (2600, 2, 36, 33, 'E-fez a [הַתִּיכֹ֑ן] [לִבְרֹ֙חַ֙] no-meio-de em-meio-de [מִן־הַקָּצֶ֖ה] de o-ketzeh- a o extremo:');
INSERT INTO verses VALUES (2601, 2, 36, 34, 'e-a as divisões ouro ouro e-a ouro fez ouro casarim para os bordados ouro a os bordados ouro');
INSERT INTO verses VALUES (2602, 2, 36, 35, 'E-fez a o-véu tchelãz e-púrpura e-carmesim segundo e-seis מָשָׁזַר obra-de חֹשֵׂב fez a-ela כּוּרְבִים׃');
INSERT INTO verses VALUES (2603, 2, 36, 36, 'E-fez para-ela quatro colunas-de שִׁיטִים [וַיְצַפֵּ֣ם] ouro ויהם ouro [וַיִּצֹ֣ק] a-eles quatro as-carruagens prata:');
INSERT INTO verses VALUES (2604, 2, 36, 37, 'E-fez כַּפֶּר para-a-entrada-de a-tenda tchelãz e-púrpura e-carmesim segundo e-seis מָשָׁזַר obra-de ROOM:');
INSERT INTO verses VALUES (2605, 2, 36, 38, 'e-a [חֲמִשָּׁה֙] cinco e-a [רָאשֵׁיהֶ֛ם] [וַחֲשֻׁקֵיהֶ֖ם] ouro e-seus-órgãos-reprodutivos ouro VE''ADNEIM חמישה bronze');
INSERT INTO chapters VALUES (87, 2, 37, 29);
INSERT INTO verses VALUES (2606, 2, 37, 1, 'E-fez de-Betsalel a הָאָרֹ֖ן árvores-de acácia dois palmos e meio seu-comprimento e um palmo e meio em-ele-o-largura-seu e um palmo e meio sua altura');
INSERT INTO verses VALUES (2607, 2, 37, 2, '[וַיְצַפֵּ֛הוּ] ouro puro de-casa [וּמִח֑וּץ] E-fez a-ele זֵ֥ר ouro ao-redor');
INSERT INTO verses VALUES (2608, 2, 37, 3, '[וַיִּצֹ֣ק] a-ele quatro טַבְּעֹ֣ת ouro sobre quatro פַּעֲמֹתָ֑יו e-duas-de טַבָּעֹ֗ת sobre צַלְעוֹ֙ a-uma u-shtey [עַל־צַלְע֖וֹ] sobre צַלְע֖וֹ הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (2609, 2, 37, 4, 'E-fez em-cápsulas árvores-de acácia e-cobriu eles ouro');
INSERT INTO verses VALUES (2610, 2, 37, 5, 'e-trouxe a הַבַּדִּים֙ sobre sobre צַלְעֹ֣ת הָאָרֹ֑ן levando a [sem-traducao]');
INSERT INTO verses VALUES (2611, 2, 37, 6, 'E-fez [כַּפֹּ֖רֶת] ouro puro אַמָּתַ֤יִם e meio אָרְכָּ֔הּ e um palmo e meio rāḥabbah');
INSERT INTO verses VALUES (2612, 2, 37, 7, 'E-fez segundo [כְרֻבִ֖ים] ouro miqšāh fez eles misnē pontas ha-kappōret');
INSERT INTO verses VALUES (2613, 2, 37, 8, '[כְּרוּב־אֶחָ֤ד] um miqqetsāh deste-lado e-caravel- um de-acéu- deste de a-caporéth- fez a os-querubins de-dois-de');
INSERT INTO verses VALUES (2614, 2, 37, 9, 'e-foram os-querubins que-spreadem- as-asas- acima-de- [סֹֽכְכִ֤ים] com-as-sus-asas- sobre a-caporéth- e as faces homem a irmão-dele face-de os-querubins foram face-de os-querubins');
INSERT INTO verses VALUES (2615, 2, 37, 10, 'E-fez a [עֲצֵ֣י] árvores-de acácia אַמָּתַ֤יִם seu-comprimento e um pé em-ele-o-largura-seu e um palmo e meio sua altura');
INSERT INTO verses VALUES (2616, 2, 37, 11, 'e-cobriu ele ouro puro E-fez a-ele זֵ֥ר ouro ao-redor');
INSERT INTO verses VALUES (2617, 2, 37, 12, 'E-fez a-ele misgeret topach ao-redor E-fez zer- zahav misgeret ao-redor');
INSERT INTO verses VALUES (2618, 2, 37, 13, '[וַיִּצֹ֣ק] a-ele quatro טַבְּעֹ֣ת ouro E-colocou a sobre sobre quatro hafe''ot que para quatro de-seus-pés');
INSERT INTO verses VALUES (2619, 2, 37, 14, 'conforme a misteriosa foram as plantas [בָּתִּים֙] [לַבַּדִּ֔ים] levando a a mesa');
INSERT INTO verses VALUES (2620, 2, 37, 15, 'E-fez a הַבַּדִּים֙ árvores-de שִׁיטִים eles ouro ouro levando a a mesa');
INSERT INTO verses VALUES (2621, 2, 37, 16, 'E-fez a [׀] que sobre [אֶת־קְעָרֹתָ֤יו] a e-[OBJ] e-[OBJ] [וְאֶת־הַקְּשָׂוֺ֔ת] e-[OBJ] [יֻסַּ֖ךְ] e-[OBJ] ouro que');
INSERT INTO verses VALUES (2622, 2, 37, 17, 'E-fez a ouro ouro puro candelabrum- fez a a menorá -suas-mamas -et-e-sua-cana -suas-copas -suas-bacias -e-suas-floradas de-a-ela eram');
INSERT INTO verses VALUES (2623, 2, 37, 18, 'e-seis קָנִים יֹצְאִים מִצִּדֶּהָ שְׁלֹשָׁה קְנֵי מְנֹרָה מִצִּדָּהּ do único o-primeiro קְנֵי מְנֹרָה de-lá-dela o-segundo');
INSERT INTO verses VALUES (2624, 2, 37, 19, 'três gevú-''im mash-qú-kadím baq-qué-né o-primeiro kap-tór va-perákh e-três gevú-im mash-qú-kadím בּ-קָנֶה um kap-tór e-fo-rach assim seis as quinas que saem de a manora:');
INSERT INTO verses VALUES (2625, 2, 37, 20, 'e na manora quatro copos [מְשֻׁ֨קָּדִ֔ים] suas bordas e suas flores:');
INSERT INTO verses VALUES (2626, 2, 37, 21, 'e a cipreste debaixo segundo das vimeiras deles e a cipreste debaixo segundo das vimeiras de-a e a cipreste debaixo-de segundo das vimeiras מִמֶּנָּה seis as quinas que saem de-elas');
INSERT INTO verses VALUES (2627, 2, 37, 22, 'suas têmporas e seus canos de ela foram toda de jardim uma ouro puro');
INSERT INTO verses VALUES (2628, 2, 37, 23, 'E-fez a suas velas sete e-suas-mãos ouro ouro puro');
INSERT INTO verses VALUES (2629, 2, 37, 24, 'como-circunferência ouro puro fez a-ela e-a todo [sem-traducao]');
INSERT INTO verses VALUES (2630, 2, 37, 25, 'E-fez a altar-de [עֲצֵ֣י] árvores-de acácia cubit-a [וְאַמָּ֨ה] [רָחְבּ֜וֹ] [רָב֗וּעַ] [וְאַמָּתַ֙יִם֙] [קֹֽמָת֔וֹ] nós dele foram os-seus-chifres');
INSERT INTO verses VALUES (2631, 2, 37, 26, 'e-cobriu ele ouro טהור a [וְאֶת־קִירֹתָ֛יו] e-a [וְאֶת־קַרְנֹתָ֑יו] ao-redor a-ele suas cornetas ouro para-ele זֵ֥ר ouro ao-redor');
INSERT INTO verses VALUES (2632, 2, 37, 27, '[וּשְׁתֵּי֩] [טַבְּעֹ֨ת] ouro fez para-ele debaixo-de para-seu-fio sobre duas [צַלְעֹתָ֔יו] sobre segundo [צִדָּ֑יו] para quartos separadamente para-levar ele neles');
INSERT INTO verses VALUES (2633, 2, 37, 28, 'E-fez a [עֲצֵ֣י] árvores-de acácia eles ouro');
INSERT INTO verses VALUES (2634, 2, 37, 29, 'E-fez a shemen a unção santidade e-a fumegante das-essências puro obra-de [sem-traducao]');
INSERT INTO chapters VALUES (88, 2, 38, 31);
INSERT INTO verses VALUES (2635, 2, 38, 1, 'E-fez a altar-de a-holocausto árvores-de acácia cinco אמות o-seu-comprimento [רָחְבּוֹ֙] [רָב֔וּעַ] a-sua-largura [אַמּ֖וֹת] e três côvados sua altura');
INSERT INTO verses VALUES (2636, 2, 38, 2, 'E-fez suas cornetas sobre quatro suas pontas nós eram suas cornetas e-cobriu ele bronze');
INSERT INTO verses VALUES (2637, 2, 38, 3, 'E-fez a todo utensílios-de o-altar a [אֶת־הַמִּזְלָגֹ֖ת] e-a [כָּל־כֵּלָ֖יו] e-a as-alâbadas a [sem-traducao] e-a [sem-traducao] todo כְּלֵיָיו fez bronze');
INSERT INTO verses VALUES (2638, 2, 38, 4, 'E-fez [לַמִּזְבֵּ֙חַ֙] de-machbar obra-de rede bronze debaixo [כַּרְכֻּבּ֛וֹ] [מִלְּמַ֖טָּה] até [sem-traducao]');
INSERT INTO verses VALUES (2639, 2, 38, 5, '[וַיִּצֹ֞ק] quatro [טַבָּעֹ֛ת] [בְּאַרְבַּ֥ע] [הַקְּצָוֺ֖ת] [לְמִכְבַּ֣ר] [הַנְּחֹ֑שֶׁת] casarim [לַבַּדִּֽים]');
INSERT INTO verses VALUES (2640, 2, 38, 6, 'E-fez a [עֲצֵ֣י] árvores-de acácia eles eles');
INSERT INTO verses VALUES (2641, 2, 38, 7, 'e-trouxe a [בַּטַּבָּעֹ֗ת] sobre sobre צַלְעֹ֣ת o altar ele ele com-eles nabub luchot ele ele');
INSERT INTO verses VALUES (2642, 2, 38, 8, 'E-fez a [הַכִּיּ֣וֹר] bronze e-a [כַּנּ֣וֹ] bronze [בְּמַרְאֹת֙] [הַצֹּ֣בְאֹ֔ת] que [צָֽבְא֔וּ] entrada tenda reunião');
INSERT INTO verses VALUES (2643, 2, 38, 9, 'E-fez a [לִפְאַ֣ת] [׀] Neguebe [תֵּימָ֗נָה] [קַלְעֵ֤י] o-pateo seis [מָשְׁזָ֔ר] cem [בָּאַמָּֽה]');
INSERT INTO verses VALUES (2644, 2, 38, 10, '[עַמּוּדֵיהֶ֣ם] vinte VE''ADNEIM vinte bronze e-ganchos-de HA''AMMUDIM e-seus-órgãos-reprodutivos כַּסֶּפֶת׃');
INSERT INTO verses VALUES (2645, 2, 38, 11, '[וְלִפְאַ֤ת] -norte cem [בָֽאַמָּ֔ה] [עַמּוּדֵיהֶ֣ם] vinte VE''ADNEIM vinte bronze e-ganchos-de [הָֽעַמּוּדִ֛ים] e-seus-órgãos-reprodutivos כַּסֶּפֶת׃');
INSERT INTO verses VALUES (2646, 2, 38, 12, '[וְלִפְאַת־יָ֗ם] [קְלָעִים֙] [חֲמִשִּׁ֣ים] cinquenta na-côvado [עֲשָׂרָ֔ה] dez e seus enredados dez e-ganchos-de HA''AMMUDIM [כָּֽסֶף] כַּסֶּפֶת׃');
INSERT INTO verses VALUES (2647, 2, 38, 13, '[וְלִפְאַ֛ת] leste oeste cinquenta jardim; jardim:');
INSERT INTO verses VALUES (2648, 2, 38, 14, 'cordões חֲמֵשׁ- doze côvado a [שְׁלֹשָׁ֔ה] [וְאַדְנֵיהֶ֖ם] שְׁלֹשָׁ֔ה quatro três');
INSERT INTO verses VALUES (2649, 2, 38, 15, '[וְלַכָּתֵ֣ף] a-segunda [מִזֶּ֤ה] [וּמִזֶּה֙] para-portão-de o-pátio [קְלָעִ֕ים] cinco dez jardim e suas colunas שְׁלֹשָׁ֔ה e seus enredados três');
INSERT INTO verses VALUES (2650, 2, 38, 16, 'todo [הֶחָצֵ֛ר] o-courim ao-redor seis máshazar:');
INSERT INTO verses VALUES (2651, 2, 38, 17, '[וְהָאֲדָנִ֣ים] [לָֽעַמֻּדִים֮] [נְחֹשֶׁת֒] [וָוֵ֨י] [הָֽעַמּוּדִ֜ים] [וַחֲשׁוּקֵיהֶם֙] prata [וְצִפּ֥וּי] [רָאשֵׁיהֶ֖ם] prata e-eles forrados prata todo [עַמֻּדֵ֥י] [הֶחָצֵֽר]');
INSERT INTO verses VALUES (2652, 2, 38, 18, '[וּמָסַ֞ךְ] porta-de [הֶחָצֵר֙] obra-de [רֹקֵ֔ם] tchelãz e-púrpura e-carmesim segundo e-seis מָשָׁזַר e-vinte côvado comprimento [וְקוֹמָ֤ה] [בְרֹ֙חַב֙] cinco covados como [קַלְעֵ֥י] [הֶחָצֵֽר]');
INSERT INTO verses VALUES (2653, 2, 38, 19, '[וְעַמֻּֽדֵיהֶם֙] quatro VE''ADNEIM quatro bronze [וָוֵיהֶ֣ם] prata [וְצִפּ֧וּי] [רָאשֵׁיהֶ֛ם] e-seus-órgãos-reprodutivos כַּסֶּפֶת׃');
INSERT INTO verses VALUES (2654, 2, 38, 20, '[וְֽכָל[c]] [הַיְתֵדֹ֞ת] [לַמִּשְׁכָּ֧ן] ao-redor bronze');
INSERT INTO verses VALUES (2655, 2, 38, 21, 'Estas [פְקוּדֵ֤י] o-tabernáculo tabernáculo-de o-testemunho que [פֻּקַּ֖ד] sobre boca-de Moisés serviço-dele [בְּיַד֙] em-mão-de aitamar filho-de אַהֲרֹן o-sacerdote');
INSERT INTO verses VALUES (2656, 2, 38, 22, '[וּבְצַלְאֵ֛ל] filho-de Uri filho-de Hur para-a-tribo-de Judá fez yhwh todo que ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2657, 2, 38, 23, '[וְאִתּ֗וֹ] Ahiliv filho-de [לְמַטֵּה־דָ֖ן] Para-a-margem- Dan [וְרֹקֵ֗ם] [בַּתְּכֵ֙לֶת֙] [וּבָֽאַרְגָּמָ֔ן] em-o-azul [הַשָּׁנִ֖י] [וּבַשֵּֽׁשׁ׃] o-escarlate [sem-traducao]');
INSERT INTO verses VALUES (2658, 2, 38, 24, 'todo o-ouro [לַמְּלָאכָ֔ה] [בְּכֹ֖ל] em-todo obra-de e-houve e-foi [זְהַ֣ב] [הַתְּנוּפָ֗ה] nove e-vinte [כִּכָּ֔ר] [וּשְׁבַ֨ע] [מֵא֧וֹת] [וּשְׁלֹשִׁ֛ים] siclo [בְּשֶׁ֥קֶל] [הַקֹּֽדֶשׁ]');
INSERT INTO verses VALUES (2659, 2, 38, 25, '[וְכֶ֛סֶף] [פְּקוּדֵ֥י] [הָעֵדָ֖ה] [מְאַ֣ת] [כִּכָּ֑ר] [וְאֶלֶף֩] [וּשְׁבַ֨ע] [מֵא֜וֹת] [וַחֲמִשָּׁ֧ה] [וְשִׁבְעִ֛ים] siclo [בְּשֶׁ֥קֶל] [הַקֹּֽדֶשׁ]');
INSERT INTO verses VALUES (2660, 2, 38, 26, '[בֶּ֚קַע] [לַגֻּלְגֹּ֔לֶת] [מַחֲצִ֥ית] [הַשֶּׁ֖קֶל] em-siclo a-santidade a-todo [הָעֹבֵ֜ר] sobre [מִבֶּ֨ן] de-filho-de vinte ano [לְשֵׁשׁ־מֵא֥וֹת] [אֶ֙לֶף֙] centenas mil [וַחֲמֵ֥שׁ] [מֵא֖וֹת] [וַחֲמִשִּֽׁים] centenas e-cinquenta');
INSERT INTO verses VALUES (2661, 2, 38, 27, 'e-houve [מְאַת֙] [כִּכַּ֣ר] [הַכֶּ֔סֶף] [לָצֶ֗קֶת] a Adonai [הַקֹּ֔דֶשׁ] e-[OBJ] Adonai [הַפָּרֹ֑כֶת] [מְאַ֧ת] [אֲדָנִ֛ים] [לִמְאַ֥ת] [הַכִּכָּ֖ר] [כִּכָּ֥ר] [לָאָֽדֶן]');
INSERT INTO verses VALUES (2662, 2, 38, 28, 'e-[OBJ] [וּשְׁבַ֤ע] [הַמֵּאוֹת֙] [וַחֲמִשָּׁ֣ה] [וְשִׁבְעִ֔ים] [עָשָׂ֥ה] fez [לָעַמּוּדִ֑ים] [וְצִפָּ֥ה] [רָאשֵׁיהֶ֖ם] [וְחִשַּׁ֥ק] eles');
INSERT INTO verses VALUES (2663, 2, 38, 29, '[וּנְחֹ֥שֶׁת] [הַתְּנוּפָ֖ה] [שִׁבְעִ֣ים] [כִּכָּ֑ר] [וְאַלְפַּ֥יִם] [וְאַרְבַּע־מֵא֖וֹת] centenas');
INSERT INTO verses VALUES (2664, 2, 38, 30, 'E-fez [בָּ֗הּ] a Adonai [אֹ֣הֶל] tenda e-[OBJ] e-[OBJ] [הַנְּחֹ֔שֶׁת] [וְאֶת־מִכְבַּ֥ר] e-[OBJ] [אֲשֶׁר־ל֑וֹ] e-[OBJ] que a-ele e-[OBJ] todo');
INSERT INTO verses VALUES (2665, 2, 38, 31, 'e-[OBJ] Adonai o-pateo [וְאֶת־אַדְנֵ֖י] e-[OBJ] Adonai e-[OBJ] [כָּל־יִתְדֹ֧ת] e-[OBJ] todo [הֶחָצֵ֖ר] [סָבִֽיב] e-[OBJ] todo [sem-traducao] [sem-traducao] ao-redor');
INSERT INTO chapters VALUES (89, 2, 39, 43);
INSERT INTO verses VALUES (2666, 2, 39, 1, 'e-de [וְהָֽאַרְגָּמָן֙] [וְתוֹלַ֣עַת] [הַשָּׁנִ֔י] [עָשׂ֥וּ] [בִגְדֵי־שְׂרָ֖ד] [לְשָׁרֵ֣ת] [בַּקֹּ֑דֶשׁ] [וַֽיַּעֲשׂ֞וּ] [אֶת־בִּגְדֵ֤י] [הַקֹּ֙דֶשׁ֙] a [לְאַהֲרֹ֔ן] a-santidade que yhwh como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2667, 2, 39, 2, 'E-fez a ouro ouro [וְאַרְגָּמָ֛ן] e-púrpura e-carmesim segundo [מָשְׁזָֽר] [sem-traducao]');
INSERT INTO verses VALUES (2668, 2, 39, 3, '[וַֽיְרַקְּע֞וּ] a o-ouro [וְקִצֵּ֣ץ] [פְּתִילִם֒] [לַעֲשׂ֗וֹת] no-meio-de [הַתְּכֵ֙לֶת֙] [וּבְת֣וֹךְ] [הָֽאַרְגָּמָ֔ן] [וּבְת֛וֹךְ] [תּוֹלַ֥עַת] [הַשָּׁנִ֖י] [וּבְת֣וֹךְ] [הַשֵּׁ֑שׁ] [מַעֲשֵׂ֖ה] [חֹשֵֽׁב]');
INSERT INTO verses VALUES (2669, 2, 39, 4, '[כְּתֵפֹ֥ת] [עָֽשׂוּ־ל֖וֹ] a-ele [עַל־שְׁנֵ֥י] sobre segundo [חֻבָּֽר]');
INSERT INTO verses VALUES (2670, 2, 39, 5, '[וְחֵ֨שֶׁב] [אֲפֻדָּת֜וֹ] que sobre-ele nós ele [כְּמַעֲשֵׂהוּ֒] ouro [תְּכֵ֧לֶת] e-púrpura e-carmesim segundo [וְשֵׁ֣שׁ] [מָשְׁזָ֑ר] como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2671, 2, 39, 6, '[וַֽיַּעֲשׂוּ֙] a pedras-de [מֻֽסַבֹּ֖ת] [מִשְׁבְּצֹ֣ת] ouro [מְפֻתָּחֹת֙] [פִּתּוּחֵ֣י] [חוֹתָ֔ם] [עַל־שְׁמ֖וֹת] sobre [יִשְׂרָאֵֽל] filhos-de Israel');
INSERT INTO verses VALUES (2672, 2, 39, 7, '[וַיָּ֣שֶׂם] eles sobre [כִּתְפֹ֣ת] [הָאֵפֹ֔ד] [אַבְנֵ֥י] [זִכָּר֖וֹן] aos-filhos-de Israel como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2673, 2, 39, 8, 'E-fez a [מַעֲשֵׂ֥ה] [חֹשֵׁ֖ב] [כְּמַעֲשֵׂ֣ה] [אֵפֹ֑ד] ouro ouro [וְאַרְגָּמָ֛ן] e-púrpura e-carmesim segundo [מָשְׁזָֽר] [sem-traducao]');
INSERT INTO verses VALUES (2674, 2, 39, 9, '[רָב֧וּעַ] ser [כָּפ֖וּל] fizeram a [זֶ֧רֶת] [אָרְכּ֛וֹ] [וְזֶ֥רֶת] [רָחְבּ֖וֹ] [כָּפֽוּל]');
INSERT INTO verses VALUES (2675, 2, 39, 10, '[וַיְמַלְאוּ־ב֔וֹ] quatro quatro [אָ֑בֶן] pedra [אֹ֤דֶם] homem [וּבָרֶ֔קֶת] [הַטּ֖וּר] o-primeiro o-primeiro');
INSERT INTO verses VALUES (2676, 2, 39, 11, '[וְהַטּ֖וּר] [הַשֵּׁנִ֑י] [נֹ֥פֶךְ] [סַפִּ֖יר] [וְיָהֲלֹֽם]');
INSERT INTO verses VALUES (2677, 2, 39, 12, '[וְהַטּ֖וּר] [הַשְּׁלִישִׁ֑י] [לֶ֥שֶׁם] [שְׁב֖וֹ] [וְאַחְלָֽמָה]');
INSERT INTO verses VALUES (2678, 2, 39, 13, '[וְהַטּוּר֙] o-quarto [תַּרְשִׁ֥ישׁ] [שֹׁ֖הַם] [וְיָשְׁפֵ֑ה] [מֽוּסַבֹּ֛ת] [מִשְׁבְּצ֥וֹת] ouro [בְּמִלֻּאֹתָֽם]');
INSERT INTO verses VALUES (2679, 2, 39, 14, '[וְ֠הָאֲבָנִים] sobre [בְּנֵי־יִשְׂרָאֵ֥ל] filhos-de Israel [עֶשְׂרֵ֖ה] [עַל־שְׁמֹתָ֑ם] [פִּתּוּחֵ֤י] sobre [אִ֣ישׁ] [עַל־שְׁמ֔וֹ] [לִשְׁנֵ֥ים] homem sobre dez');
INSERT INTO verses VALUES (2680, 2, 39, 15, '[וַיַּעֲשׂ֧וּ] sobre [שַׁרְשְׁרֹ֥ת] [גַּבְלֻ֖ת] [מַעֲשֵׂ֣ה] obra-de ouro [טָהֽוֹר]');
INSERT INTO verses VALUES (2681, 2, 39, 16, '[וַֽיַּעֲשׂ֗וּ] [שְׁתֵּי֙] [מִשְׁבְּצֹ֣ת] ouro [וּשְׁתֵּ֖י] [טַבְּעֹ֣ת] ouro [וֽ͏ַיִּתְּנ֗וּ] a [הַטַּבָּעֹ֔ת] [עַל־שְׁנֵ֖י] sobre segundo');
INSERT INTO verses VALUES (2682, 2, 39, 17, '[וַֽיִּתְּנ֗וּ] [שְׁתֵּי֙] [הָעֲבֹתֹ֣ת] o-ouro sobre [הַטַּבָּעֹ֑ת] [עַל־קְצ֖וֹת] sobre');
INSERT INTO verses VALUES (2683, 2, 39, 18, 'e-[OBJ] [שְׁתֵּ֤י] [קְצוֹת֙] duas [הָֽעֲבֹתֹ֔ת] deram sobre duas [וַֽיִּתְּנֻ֛ם] [עַל־כִּתְפֹ֥ת] sobre [אֶל־מ֥וּל] [פָּנָֽיו] a');
INSERT INTO verses VALUES (2684, 2, 39, 19, '[וַֽיַּעֲשׂ֗וּ] [שְׁתֵּי֙] [טַבְּעֹ֣ת] ouro [וַיָּשִׂ֕ימוּ] sobre segundo [הַחֹ֑שֶׁן] [עַל־שְׂפָת֕וֹ] sobre [אֶל־עֵ֥בֶר] que a');
INSERT INTO verses VALUES (2685, 2, 39, 20, '[וַֽיַּעֲשׂוּ֮] duas [טַבְּעֹ֣ת] ouro [וַֽיִּתְּנֻ֡ם] sobre [כִתְפֹ֨ת] [הָאֵפֹ֤ד] [מִלְמַ֙טָּה֙] [מִמּ֣וּל] [פָּנָ֔יו] [לְעֻמַּ֖ת] [מֶחְבַּרְתּ֑וֹ] [מִמַּ֕עַל] [לְחֵ֖שֶׁב] [הָאֵפֹֽד]');
INSERT INTO verses VALUES (2686, 2, 39, 21, '[וַיִּרְכְּס֣וּ] a [מִטַּבְּעֹתָיו֩] [אֶל־טַבְּעֹ֨ת] a [בִּפְתִ֣יל] [תְּכֵ֗לֶת] [לִֽהְיֹת֙] [עַל־חֵ֣שֶׁב] [הָאֵפֹ֔ד] sobre [הַחֹ֔שֶׁן] de-cima-de e-não [כַּאֲשֶׁ֛ר] [צִוָּ֥ה] yhwh [אֶת־מֹשֶֽׁה] como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2687, 2, 39, 22, 'E-fez a [הָאֵפֹ֖ד] [מַעֲשֵׂ֣ה] obra-de [כְּלִ֖יל] [תְּכֵֽלֶת]');
INSERT INTO verses VALUES (2688, 2, 39, 23, '[וּפִֽי־הַמְּעִ֥יל] [בְּתוֹכ֖וֹ] [כְּפִ֣י] [תַחְרָ֑א] [שָׂפָ֥ה] [לְפִ֛יו] [סָבִ֖יב] não não');
INSERT INTO verses VALUES (2689, 2, 39, 24, '[וַֽיַּעֲשׂוּ֙] sobre [הַמְּעִ֔יל] [רִמּוֹנֵ֕י] [תְּכֵ֥לֶת] [וְאַרְגָּמָ֖ן] [וְתוֹלַ֣עַת] [שָׁנִ֑י] segundo');
INSERT INTO verses VALUES (2690, 2, 39, 25, '[וַיַּעֲשׂ֥וּ] [פַעֲמֹנֵ֖י] ouro puro [וַיִּתְּנ֨וּ] a no-meio-de [הָרִמֹּנִ֗ים] [עַל־שׁוּלֵ֤י] sobre [סָבִ֔יב] no-meio-de [הָרִמֹּנִֽים]');
INSERT INTO verses VALUES (2691, 2, 39, 26, '[פַּעֲמֹ֤ן] [וְרִמֹּן֙] [פַּעֲמֹ֣ן] [וְרִמֹּ֔ן] sobre [הַמְּעִ֖יל] [סָבִ֑יב] [לְשָׁרֵ֕ת] [כַּאֲשֶׁ֛ר] como yhwh yhwh a Moisés');
INSERT INTO verses VALUES (2692, 2, 39, 27, '[וֽ͏ַיַּעֲשׂ֛וּ] a [שֵׁ֖שׁ] seis obra-de [לְאַהֲרֹ֖ן] [וּלְבָנָֽיו]');
INSERT INTO verses VALUES (2693, 2, 39, 28, 'e-[OBJ] [הַמִּצְנֶ֣פֶת] seis e-[OBJ] [הַמִּגְבָּעֹ֖ת] [שֵׁ֑שׁ] seis e-[OBJ] [שֵׁ֥שׁ] [מָשְׁזָֽר] seis');
INSERT INTO verses VALUES (2694, 2, 39, 29, 'e-[OBJ] [שֵׁ֣שׁ] seis [וּתְכֵ֧לֶת] [וְאַרְגָּמָ֛ן] e-púrpura e-carmesim segundo obra-de [כַּאֲשֶׁ֛ר] como yhwh yhwh a Moisés');
INSERT INTO verses VALUES (2695, 2, 39, 30, '[וֽ͏ַיַּעֲשׂ֛וּ] a [נֵֽזֶר־הַקֹּ֖דֶשׁ] ouro [טָה֑וֹר] [וַיִּכְתְּב֣וּ] puro [מִכְתַּב֙] sobre-ele [חוֹתָ֔ם] [קֹ֖דֶשׁ] [לַיהוָֽה]');
INSERT INTO verses VALUES (2696, 2, 39, 31, '[וַיִּתְּנ֤וּ] sobre-ele [פְּתִ֣יל] [תְּכֵ֔לֶת] [לָתֵ֥ת] sobre [מִלְמָ֑עְלָה] [כַּאֲשֶׁ֛ר] como yhwh yhwh a Moisés');
INSERT INTO verses VALUES (2697, 2, 39, 32, '[וַתֵּ֕כֶל] todo [מִשְׁכַּ֖ן] [אֹ֣הֶל] tenda reunião [בְּנֵ֣י] filhos-de Israel [אֲשֶׁ֨ר] que yhwh yhwh a Moisés');
INSERT INTO verses VALUES (2698, 2, 39, 33, '[וַיָּבִ֤יאוּ] a [אֶל־מֹשֶׁ֔ה] a Moisés a [קְרָשָׁ֔יו] e-[OBJ] todo [וְעַמֻּדָ֥יו] [וַאֲדָנָֽיו]');
INSERT INTO verses VALUES (2699, 2, 39, 34, 'e-[OBJ] [עוֹרֹ֤ת] [הָֽאֵילִם֙] [הַמְאָדָּמִ֔ים] [וְאֶת־מִכְסֵ֖ה] e-[OBJ] [הַתְּחָשִׁ֑ים] e-[OBJ] [פָּרֹ֥כֶת] e-[OBJ]');
INSERT INTO verses VALUES (2700, 2, 39, 35, 'a [הָעֵדֻ֖ת] [וְאֶת־בַּדָּ֑יו] e-[OBJ] [הַכַּפֹּֽרֶת] e-[OBJ]');
INSERT INTO verses VALUES (2701, 2, 39, 36, 'a [אֶת־כָּל־כֵּלָ֔יו] e-[OBJ] pão [הַפָּנִֽים] e-[OBJ]');
INSERT INTO verses VALUES (2702, 2, 39, 37, 'a [הַטְּהֹרָ֜ה] [אֶת־נֵרֹתֶ֗יהָ] a [הַמַּֽעֲרָכָ֖ה] [וְאֶת־כָּל־כֵּלֶ֑יהָ] e-[OBJ] e-[OBJ] o-luzeiro e-[OBJ]');
INSERT INTO verses VALUES (2703, 2, 39, 38, 'e-[OBJ] [מִזְבַּ֣ח] o-ouro e-[OBJ] óleo [הַמִּשְׁחָ֔ה] e-[OBJ] [קְטֹ֣רֶת] [הַסַּמִּ֑ים] e-[OBJ] [מָסַ֖ךְ] [פֶּ֥תַח] [הָאֹֽהֶל]');
INSERT INTO verses VALUES (2704, 2, 39, 39, '[OBJ] [׀] [מִזְבַּ֣ח] e-[OBJ] [וְאֶת־מִכְבַּ֤ר] [הַנְּחֹ֙שֶׁת֙] que a-ele a [אֶת־הַכִּיֹּ֖ר] e-[OBJ] todo a e-[OBJ]');
INSERT INTO verses VALUES (2705, 2, 39, 40, 'a [קַלְעֵ֨י] [הֶחָצֵ֜ר] a [וְאֶת־אֲדָנֶ֗יהָ] e-[OBJ] [לְשַׁ֣עַר] e-[OBJ] [אֶת־מֵיתָרָ֖יו] [וִיתֵדֹתֶ֑יהָ] e-[OBJ] a [עֲבֹדַ֥ת] [הַמִּשְׁכָּ֖ן] e-[OBJ] todo');
INSERT INTO verses VALUES (2706, 2, 39, 41, 'a [הַשְּׂרָ֖ד] [לְשָׁרֵ֣ת] [בַּקֹּ֑דֶשׁ] [אֶת־בִּגְדֵ֤י] a [לְאַהֲרֹ֣ן] a-santidade [וְאֶת־בִּגְדֵ֥י] o-sacerdote e-[OBJ]');
INSERT INTO verses VALUES (2707, 2, 39, 42, '[כְּכֹ֛ל] que yhwh yhwh a Moisés assim fizeram filhos-de Israel a todo');
INSERT INTO verses VALUES (2708, 2, 39, 43, 'E-viu Moisés a todo [עָשׂ֣וּ] e-eis fizeram a-ela yhwh ordenou yhwh E-abençoou eles E-abençoou Moisés');
INSERT INTO chapters VALUES (90, 2, 40, 38);
INSERT INTO verses VALUES (2709, 2, 40, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (2710, 2, 40, 2, '[בְּיוֹם־הַחֹ֥דֶשׁ] [הָרִאשׁ֖וֹן] [בְּאֶחָ֣ד] [לַחֹ֑דֶשׁ] [תָּקִ֕ים] [אֶת־מִשְׁכַּ֖ן] a [מוֹעֵֽד]');
INSERT INTO verses VALUES (2711, 2, 40, 3, '[וְשַׂמְתָּ֣] nome a arca [הָעֵד֑וּת] [וְסַכֹּתָ֥] sobre [אֶת־הַפָּרֹֽכֶת] a');
INSERT INTO verses VALUES (2712, 2, 40, 4, '[וְהֵבֵאתָ֙] a [וְעָרַכְתָּ֖] [אֶת־עֶרְכּ֑וֹ] a [אֶת־הַמְּנֹרָ֔ה] [וְהַעֲלֵיתָ֖] a a');
INSERT INTO verses VALUES (2713, 2, 40, 5, '[וְנָתַתָּ֞ה] a o-ouro [לִקְטֹ֔רֶת] [לִפְנֵ֖י] diante-de arca [וְשַׂמְתָּ֛] [אֶת־מָסַ֥ךְ] a [לַמִּשְׁכָּֽן]');
INSERT INTO verses VALUES (2714, 2, 40, 6, '[וְנָ֣תַתָּ֔ה] a [מִזְבַּ֣ח] [הָעֹלָ֑ה] [לִפְנֵ֕י] entrada [מִשְׁכַּ֥ן] [אֹֽהֶל־מוֹעֵֽד]');
INSERT INTO verses VALUES (2715, 2, 40, 7, '[וְנָֽתַתָּ֙] a [בֵּֽין־אֹ֥הֶל] [מוֹעֵ֖ד] e-entre encontro [וְנָתַתָּ֥] [שָׁ֖ם] [מָֽיִם] nome águas');
INSERT INTO verses VALUES (2716, 2, 40, 8, '[וְשַׂמְתָּ֥] a [סָבִ֑יב] [וְנָ֣תַתָּ֔] [אֶת־מָסַ֖ךְ] a [הֶחָצֵֽר]');
INSERT INTO verses VALUES (2717, 2, 40, 9, '[וְלָקַחְתָּ֙] a óleo [וּמָשַׁחְתָּ֥] [אֶת־הַמִּשְׁכָּ֖ן] a o-tabernáculo ele todo que nele e-[OBJ] todo');
INSERT INTO verses VALUES (2718, 2, 40, 10, '[וּמָשַׁחְתָּ֛] a [הָעֹלָ֖ה] [וְאֶת־כָּל־כֵּלָ֑יו] e-[OBJ] todo [וְהָיָ֥ה] [הַמִּזְבֵּ֖חַ] a [קֽ͏ָדָשִֽׁים]');
INSERT INTO verses VALUES (2719, 2, 40, 11, '[וּמָשַׁחְתָּ֥] a [וְאֶת־כַּנּ֑וֹ] e-[OBJ] ele');
INSERT INTO verses VALUES (2720, 2, 40, 12, '[וְהִקְרַבְתָּ֤] a Arão e-[OBJ] [אֹ֣הֶל] a entrada eles reunião');
INSERT INTO verses VALUES (2721, 2, 40, 13, '[וְהִלְבַּשְׁתָּ֙] a Arão a [הַקֹּ֑דֶשׁ] a-santidade ele ele ele ele [לִֽי] a-mim');
INSERT INTO verses VALUES (2722, 2, 40, 14, 'e-[OBJ] [תַּקְרִ֑יב] [וְהִלְבַּשְׁתָּ֥] eles eles');
INSERT INTO verses VALUES (2723, 2, 40, 15, '[וּמָשַׁחְתָּ֣] eles como [מָשַׁ֙חְתָּ֙] a [וְכִהֲנ֖וּ] [לִ֑י] a-mim [לִהְיֹ֨ת] a-eles [מָשְׁחָתָ֛ם] [לִכְהֻנַּ֥ת] eternidade [לְדֹרֹתָֽם]');
INSERT INTO verses VALUES (2724, 2, 40, 16, 'E-fez Moisés [כְּ֠כֹל] que [צִוָּ֧ה] yhwh ele assim fez');
INSERT INTO verses VALUES (2725, 2, 40, 17, 'e-houve [בַּחֹ֧דֶשׁ] [הָרִאשׁ֛וֹן] [בַּשָּׁנָ֥ה] [הַשֵּׁנִ֖ית] [בְּאֶחָ֣ד] [לַחֹ֑דֶשׁ] [הוּקַ֖ם] [הַמִּשְׁכָּֽן]');
INSERT INTO verses VALUES (2726, 2, 40, 18, 'E-levantou Moisés a E-colocou E-deu a [אֶת־קְרָשָׁ֔יו] E-colocou a [וַיָּ֖קֶם] E-deu a E-levantou a');
INSERT INTO verses VALUES (2727, 2, 40, 19, '[וַיִּפְרֹ֤שׂ] a [עַל־הַמִּשְׁכָּ֔ן] sobre [אֶת־מִכְסֵ֥ה] [הָאֹ֛הֶל] a [מִלְמָ֑עְלָה] [כַּאֲשֶׁ֛ר] sobre-ele yhwh como yhwh a Moisés');
INSERT INTO verses VALUES (2728, 2, 40, 20, 'E-tomou E-colocou a [אֶל־הָ֣אָרֹ֔ן] a [אֶת־הַבַּדִּ֖ים] [עַל־הָאָרֹ֑ן] E-colocou [אֶת־הַכַּפֹּ֛רֶת] sobre [מִלְמָֽעְלָה] E-deu a sobre');
INSERT INTO verses VALUES (2729, 2, 40, 21, 'e-trouxe a [אֶל־הַמִּשְׁכָּן֒] a [OBJ] [פָּרֹ֣כֶת] a [וַיָּ֕סֶךְ] sobre [אֲר֣וֹן] sobre arca [צִוָּ֥ה] yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2730, 2, 40, 22, 'E-colocou a [בְּאֹ֣הֶל] [מוֹעֵ֔ד] sobre sobre [הַמִּשְׁכָּ֖ן] o-tabernáculo [מִח֖וּץ] [לַפָּרֹֽכֶת]');
INSERT INTO verses VALUES (2731, 2, 40, 23, '[וַיַּעֲרֹ֥ךְ] [עָלָ֛יו] [עֵ֥רֶךְ] pão diante-de yhwh como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2732, 2, 40, 24, '[וַיָּ֤שֶׂם] a [בְּאֹ֣הֶל] [מוֹעֵ֔ד] encontro [הַשֻּׁלְחָ֑ן] sobre sobre [הַמִּשְׁכָּ֖ן] o-tabernáculo ao-sul');
INSERT INTO verses VALUES (2733, 2, 40, 25, '[וַיַּ֥עַל] [הַנֵּרֹ֖ת] diante-de yhwh como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2734, 2, 40, 26, '[וַיָּ֛שֶׂם] a o-ouro [בְּאֹ֣הֶל] [מוֹעֵ֑ד] reunião diante-de');
INSERT INTO verses VALUES (2735, 2, 40, 27, '[וַיַּקְטֵ֥ר] sobre-ele [קְטֹ֣רֶת] [סַמִּ֑ים] como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2736, 2, 40, 28, '[וַיָּ֛שֶׂם] a [הַפֶּ֖תַח] [לַמִּשְׁכָּֽן]');
INSERT INTO verses VALUES (2737, 2, 40, 29, 'e-[OBJ] [מִזְבַּ֣ח] [הָעֹלָ֔ה] nome entrada [מִשְׁכַּ֣ן] [אֹֽהֶל־מוֹעֵ֑ד] reunião [עָלָ֗יו] sobre-ele a [כַּאֲשֶׁ֛ר] e-[OBJ] yhwh como yhwh a Moisés');
INSERT INTO verses VALUES (2738, 2, 40, 30, '[וַיָּ֙שֶׂם֙] a [בֵּֽין־אֹ֥הֶל] [מוֹעֵ֖ד] e-entre encontro E-colocou [שָׁ֛מָּה] águas [לְרָחְצָֽה] águas [sem-traducao]');
INSERT INTO verses VALUES (2739, 2, 40, 31, '[וְרָחֲצ֣וּ] nós Moisés [וְאַהֲרֹ֣ן] e-seus-filhos a maos-deles e-[OBJ] [sem-traducao]');
INSERT INTO verses VALUES (2740, 2, 40, 32, '[בְּבֹאָ֞ם] a tenda [וּבְקָרְבָתָ֛ם] [אֶל־הַמִּזְבֵּ֖חַ] a [כַּאֲשֶׁ֛ר] [צִוָּ֥ה] yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2741, 2, 40, 33, 'E-levantou a [סָבִיב֙] ao-redor [וְלַמִּזְבֵּ֔חַ] E-colocou E-deu a [הֶחָצֵ֑ר] E-terminou [מֹשֶׁ֖ה] [אֶת־הַמְּלָאכָֽה׃] Moisés a [sem-traducao]');
INSERT INTO verses VALUES (2742, 2, 40, 34, '[וַיְכַ֥ס] [הֶעָנָ֖ן] a tenda reunião yhwh yhwh enchei a');
INSERT INTO verses VALUES (2743, 2, 40, 35, 'e-não [מֹשֶׁ֗ה] Moisés [אֶל־אֹ֣הֶל] a tenda encontro porque [וּכְב֣וֹד] yhwh [מָלֵ֖א] [אֶת־הַמִּשְׁכָּֽן] yhwh enchei a o-tabernáculo');
INSERT INTO verses VALUES (2744, 2, 40, 36, '[וּבְהֵעָל֤וֹת] a-nuvem de-cima-de [הַמִּשְׁכָּ֔ן] [יִסְע֖וּ] filhos-de Israel em-todo [מַסְעֵיהֶֽם]');
INSERT INTO verses VALUES (2745, 2, 40, 37, 'e-se não [הֶעָנָ֑ן] [וְלֹ֣א] e-não [עַד־י֖וֹם] até dia');
INSERT INTO verses VALUES (2746, 2, 40, 38, 'que [עֲנַ֨ן] yhwh sobre [יוֹמָ֔ם] [וְאֵ֕שׁ] [תִּהְיֶ֥ה] será noite nele [כָל־בֵּֽית־יִשְׂרָאֵ֖ל] todo casa-de Israel em-todo');
INSERT INTO books VALUES (3, 'LEV', 'Levítico', 'AT', 27);
INSERT INTO chapters VALUES (91, 3, 1, 17);
INSERT INTO verses VALUES (2747, 3, 1, 1, 'E-chamou a Moisés yhwh a-ele para-ele de-tenda-de dizendo para-dizer');
INSERT INTO verses VALUES (2748, 3, 1, 2, 'palavra a filhos-de Israel e-dirás homem homem porque aproximará de-vós oferta para-יהוה de o-gado de o-bovino e-de o-rebanho aproximareis a oferta-vossa');
INSERT INTO verses VALUES (2749, 3, 1, 3, 'se holocausto oferta-sua macho o-bovino macho perfeito aproximá-lo-á a entrada-de ele encontro aproximará yhwh para-favor-seu diante-de yhwh');
INSERT INTO verses VALUES (2750, 3, 1, 4, 'e-apoiará sua-mão sobre cabeça o-holocausto e-será-aceito a-ele para-expiar sobre-ele');
INSERT INTO verses VALUES (2751, 3, 1, 5, 'e-degolará a filho o-bovino yhwh yhwh e-aproximarão filhos-de אַהֲרֹן os-sacerdotes a o-sangue e-aspergirão a o-sangue sobre o-altar ao-redor que entrada-de tenda-de encontro');
INSERT INTO verses VALUES (2752, 3, 1, 6, 'e-esfolará a o-holocausto e-cortará a-ela em-pedaços-seus');
INSERT INTO verses VALUES (2753, 3, 1, 7, 'e-porão filhos-de Arão o-sacerdote fogo sobre o-altar e-arranjarão madeiras sobre o-fogo');
INSERT INTO verses VALUES (2754, 3, 1, 8, 'e-arranjarão filhos-de Arão os-sacerdotes את os-pedaços a a-cabeça e-a a-gordura sobre as-madeiras que sobre o-fogo que sobre o-altar');
INSERT INTO verses VALUES (2755, 3, 1, 9, 'e-interior-seu e-pernas-suas lavará nas-águas e-fará-fumaça o-sacerdote a o-tudo ao-altar holocausto mulher aroma-de suavidade para-יהוה');
INSERT INTO verses VALUES (2756, 3, 1, 10, 'e-se de o-rebanho oferta-sua de os-cordeiros macho de os-cabritos para-holocausto macho perfeito aproximá-lo-á');
INSERT INTO verses VALUES (2757, 3, 1, 11, 'e-degolará ele sobre lado-de o-altar ao-norte diante-de yhwh e-aspergirão filhos-de Arão os-sacerdotes a sangue-seu sobre o-altar ao-redor');
INSERT INTO verses VALUES (2758, 3, 1, 12, 'e-cortará ele em-pedaços-seus e-a cabeça-sua e-a gordura-sua eles o-sacerdote a-eles sobre as-madeiras que sobre o-fogo que sobre o-altar');
INSERT INTO verses VALUES (2759, 3, 1, 13, 'e-o-interior e-as-pernas lavará nas-águas e trouxe-próximo o-sacerdote a o-tudo e fez-fumaça ao-altar ele ele mulher aroma-de tranquilidade para-יהוה');
INSERT INTO verses VALUES (2760, 3, 1, 14, 'e se de a ave holocausto oferenda-sua para-יהוה e trouxe-próximo de as rolas ou de filhos-de a-pomba a oferenda-sua');
INSERT INTO verses VALUES (2761, 3, 1, 15, 'e trouxe-próximo-o o-sacerdote a o altar e torceu a cabeça-sua e fez-fumaça o altar-para sobre sangue-seu sobre parede-de o-altar');
INSERT INTO verses VALUES (2762, 3, 1, 16, 'e removeu a papo-seu com penas-suas e lançou ela junto-a o-altar oriente-para a lugar-de a cinza');
INSERT INTO verses VALUES (2763, 3, 1, 17, 'e fendeu ele em asas-suas não separará e fez-fumaça ele o-sacerdote ao-altar sobre as madeiras que sobre ele holocausto ele mulher aroma-de tranquilidade para-יהוה');
INSERT INTO chapters VALUES (92, 3, 2, 16);
INSERT INTO verses VALUES (2764, 3, 2, 1, 'e alma porque trouxer-próximo oferenda-de oferta-cereais para-יהוה será será oferenda-sua e derramou sobre-ela óleo e colocou sobre-ela incenso');
INSERT INTO verses VALUES (2765, 3, 2, 2, 'e trouxe-ela a filhos-de Aarão os sacerdotes e pegou-punhado de-lá enchei punhado-seu de flor-farinha-sua sobre sobre todo incenso-sua e fez-fumaça o sacerdote a memorial-sua ao-altar mulher aroma-de tranquilidade para-יהוה');
INSERT INTO verses VALUES (2766, 3, 2, 3, 'e a restante de a oferta-cereais para-Aarão e para filhos-seus santidade-de santidades yhwh yhwh');
INSERT INTO verses VALUES (2767, 3, 2, 4, 'e-que trouxeres-próximo oferenda-de oferta cozido-de forno flor-farinha bolos não-fermentados misturados com-o óleo e biscoitos-de não-fermentados untados com-o óleo');
INSERT INTO verses VALUES (2768, 3, 2, 5, 'e-se oferta-cereais sobre a frigideira oferenda-de-ti farinha-fina misturada em-o-óleo sem-fermento ela-será');
INSERT INTO verses VALUES (2769, 3, 2, 6, 'pedaços a-ela pedaços e-tu-derramarás sobre-ela óleo oferta ela');
INSERT INTO verses VALUES (2770, 3, 2, 7, 'e-se oferenda-de panela oferenda-de-ti farinha-fina em-o-óleo ela-será-feita');
INSERT INTO verses VALUES (2771, 3, 2, 8, 'e-tu-trarás a a-oferenda que ele-será-feito de-estes para-יהוה e-ele-a-oferecerá a o-sacerdote e-ele-a-aproximará a o-altar');
INSERT INTO verses VALUES (2772, 3, 2, 9, 'e-ele-levantará o-sacerdote de a-oferenda a memorial-dela e-ele-queimará o altar-para mulher aroma agradável para-יהוה');
INSERT INTO verses VALUES (2773, 3, 2, 10, 'e-a-restante de a oferta-cereais para-Aarão e-para-filhos-dele santo santíssimos yhwh yhwh');
INSERT INTO verses VALUES (2774, 3, 2, 11, 'todo a-oferenda que vós-oferecereis não não ela-será-feita que porque todo fermento nós mel não vós-queimareis de-ele mulher para-יהוה');
INSERT INTO verses VALUES (2775, 3, 2, 12, 'oferenda-de primícias vós-oferecereis eles para-יהוה e-a o-altar não eles-subirão para-aroma agradável');
INSERT INTO verses VALUES (2776, 3, 2, 13, 'e-todo oferenda oferenda-de-ti em-o-sal tu-salgará e-não tu-cessarás sal aliança de-cima-de de-sobre sobre sobre todo oferenda-de-ti tu-oferecerás sal');
INSERT INTO verses VALUES (2777, 3, 2, 14, 'e-se tu-oferecerás oferenda-de primícias para-יהוה espigas-verdes tostadas em-o-fogo grãos-pisados espigas-frescas tu-oferecerás את oferenda-de primícias-de-ti');
INSERT INTO verses VALUES (2778, 3, 2, 15, 'e-tu-porás sobre-ela óleo e-tu-colocarás sobre-ela incenso oferta ela');
INSERT INTO verses VALUES (2779, 3, 2, 16, 'e-ele-queimará o-sacerdote a memorial-dela de-grãos-pisados-dela sobre sobre todo incenso-dela mulher para-יהוה');
INSERT INTO chapters VALUES (93, 3, 3, 17);
INSERT INTO verses VALUES (2780, 3, 3, 1, 'e-se sacrifício paz oferenda-sua mãe ele o-bovino ele oferecendo se macho se yhwh íntegro ele-o-oferecerá diante-de yhwh');
INSERT INTO verses VALUES (2781, 3, 3, 2, 'e-ele-apoiará sua-mão sobre cabeça oferenda-dele e-ele-o-abaterá entrada tenda de-encontro e-aspergirão filhos-de Aarão os-sacerdotes a o-sangue sobre o-altar ao-redor');
INSERT INTO verses VALUES (2782, 3, 3, 3, 'e-oferecerá de-sacrifício-de as-ofertas-de-paz mulher para-יהוה a a-gordura a-que-cobre a as-entranhas e-את todo a-gordura que sobre as-entranhas');
INSERT INTO verses VALUES (2783, 3, 3, 4, 'e-את duas os-rins e-a a-gordura que sobre-eles que sobre os-lombos e-a o-lóbulo sobre o-fígado sobre os-rins removerá-a');
INSERT INTO verses VALUES (2784, 3, 3, 5, 'e-queimarão ele filhos-de Aarão ao-altar sobre o-holocausto que sobre as-lenhas que sobre o-fogo mulher aroma suave para-יהוה');
INSERT INTO verses VALUES (2785, 3, 3, 6, 'e-se de o-rebanho oferenda-sua para-sacrifício-de macho para-יהוה fêmea ou fêmea perfeito oferecerá-o');
INSERT INTO verses VALUES (2786, 3, 3, 7, 'se cordeiro ele oferecendo ele oferenda-sua yhwh a-ele diante-de yhwh');
INSERT INTO verses VALUES (2787, 3, 3, 8, 'e-porá a mão-dele sobre cabeça ele e-imolará a-ele diante-de tenda de-encontro e-aspergirão filhos-de Aarão a sangue-seu sobre o-altar ao-redor');
INSERT INTO verses VALUES (2788, 3, 3, 9, 'e-oferecerá de-sacrifício-de as-ofertas-de-paz mulher para-יהוה gordura-sua a-cauda-gorda inteira próximo-a a-espinha removerá-a e-a a-gordura a-que-cobre a as-entranhas e-את todo a-gordura que sobre as-entranhas');
INSERT INTO verses VALUES (2789, 3, 3, 10, 'e-את duas os-rins e-a a-gordura que sobre-eles que sobre os-lombos e-a o-lóbulo sobre o-fígado sobre os-rins removerá-a');
INSERT INTO verses VALUES (2790, 3, 3, 11, 'e-queimará-o o-sacerdote o altar-para pão mulher para-יהוה');
INSERT INTO verses VALUES (2791, 3, 3, 12, 'e-se cabra oferenda-sua e-oferecerá-a diante-de yhwh');
INSERT INTO verses VALUES (2792, 3, 3, 13, 'e-porá a mão-dele sobre ele e-imolará a-ele diante-de tenda de-encontro e-aspergirão filhos-de Aarão a sangue-seu sobre o-altar ao-redor');
INSERT INTO verses VALUES (2793, 3, 3, 14, 'e-oferecerá nós oferenda-dele mulher para-יהוה a a-gordura a-que-cobre a as-entranhas e-את todo a-gordura que sobre as-entranhas');
INSERT INTO verses VALUES (2794, 3, 3, 15, 'e-את duas os-rins e-a a-gordura que sobre-eles que sobre os-lombos e-a o-lóbulo sobre o-fígado sobre os-rins removerá-a');
INSERT INTO verses VALUES (2795, 3, 3, 16, 'e-ele-fará-fumaça-eles o-sacerdote o altar-para pão mulher para-aroma suave todo gordura para-יהוה');
INSERT INTO verses VALUES (2796, 3, 3, 17, 'estatuto-de eternidade para-gerações-vossas em-todo habitações-vossas todo gordura não sangue não comereis');
INSERT INTO chapters VALUES (94, 3, 4, 35);
INSERT INTO verses VALUES (2797, 3, 4, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2798, 3, 4, 2, 'palavra a filhos-de dizendo dizendo alma porque de-toda em-erro yhwh mandamentos-de não que não serão-feitas e-ele-fez de-uma de-elas');
INSERT INTO verses VALUES (2799, 3, 4, 3, 'mãe o-sacerdote o-ungido ele-pecar para-culpa-de o-povo e-ele-oferecerá sobre pecado-dele que ele-pecou touro filho-de manhã perfeito para-יהוה para-oferta-pelo-pecado');
INSERT INTO verses VALUES (2800, 3, 4, 4, 'e-ele-trouxe a o-touro a entrada-de tenda-de yhwh diante-de yhwh e-ele-apoiará a mão-dele sobre cabeça yhwh e-ele-degolará a o-touro diante-de yhwh');
INSERT INTO verses VALUES (2801, 3, 4, 5, 'e-tome o-sacerdote o-ungido de-sangue-de o-touro e-ele-trouxe ele a tenda-de encontro');
INSERT INTO verses VALUES (2802, 3, 4, 6, 'e-ele-mergulhará o-sacerdote a dedo-dele no-sangue e-ele-aspergirá de o-sangue sete yhwh diante-de yhwh a face-de véu-de o-santuário');
INSERT INTO verses VALUES (2803, 3, 4, 7, 'e-ele-dará o-sacerdote de o-sangue sobre chifres-de altar-de incenso yhwh diante-de yhwh que em-tenda-de encontro e-את todo sangue o-touro ele-derramará a base-de altar-de a-holocausto que entrada-de tenda-de encontro');
INSERT INTO verses VALUES (2804, 3, 4, 8, 'e-a todo gordura-de touro-de nós ele-levantará de-ele a a-gordura a-que-cobre sobre as-entranhas e-את todo a-gordura que sobre as-entranhas');
INSERT INTO verses VALUES (2805, 3, 4, 9, 'e-את duas os-rins e-a a-gordura que sobre-eles que sobre os-lombos e-a o-lóbulo sobre o-fígado sobre os-rins removerá-a');
INSERT INTO verses VALUES (2806, 3, 4, 10, 'como será-levantado de-touro sacrifício-de os-pacíficos e-fará-fumaça-eles o-sacerdote sobre altar-de a-elevação');
INSERT INTO verses VALUES (2807, 3, 4, 11, 'e-a pele-de o-touro e-a todo em-carne-sua sobre cabeça-sua e-sobre como-pernas-suas e-interior-seu e-esterco-seu');
INSERT INTO verses VALUES (2808, 3, 4, 12, 'e-fará-sair a todo o-touro a de-fora para-o-acampamento a lugar-de ele a derramamento-de a-cinza e-queimará a-ele sobre madeiras no-fogo sobre derramamento-de a-cinza será-queimado');
INSERT INTO verses VALUES (2809, 3, 4, 13, 'e-se todo congregação-de Israel errarem e-for-oculta palavra de-olhos-de a-assembleia uma uma yhwh de-mandamentos-de yhwh que não não-sejam-feitas e-forem-culpados');
INSERT INTO verses VALUES (2810, 3, 4, 14, 'e-for-conhecida a-transgressão que transgrediram sobre-ela e-farão-aproximar a-assembleia touro filho-de manhã para-transgressão ele a-ele diante-de tenda-de encontro');
INSERT INTO verses VALUES (2811, 3, 4, 15, 'e-apoiarão anciãos-de a-congregação a mãos-suas sobre cabeça yhwh diante-de yhwh e-ele-degolará yhwh o-touro diante-de yhwh');
INSERT INTO verses VALUES (2812, 3, 4, 16, 'e-trará o-sacerdote o-ungido de-sangue-de o-touro a tenda encontro');
INSERT INTO verses VALUES (2813, 3, 4, 17, 'e-mergulhará o-sacerdote dedo-dele de o-sangue e-aspergirá sete vezes yhwh yhwh face-de face-de a-cortina');
INSERT INTO verses VALUES (2814, 3, 4, 18, 'e-de o-sangue dará sobre pontas-de o-altar que yhwh yhwh que em-tenda-de encontro e-a todo o-sangue ele-derramará a base-de altar-de a-elevação que entrada-de tenda-de encontro');
INSERT INTO verses VALUES (2815, 3, 4, 19, 'e-a todo gordura-sua nós de-ele e-fará-fumaça o-altar-para');
INSERT INTO verses VALUES (2816, 3, 4, 20, 'e-fará para-o-touro como-que fez para-touro-de a-transgressão assim fará- para-ele e-cobrirá sobre-eles o-sacerdote a-eles para-eles');
INSERT INTO verses VALUES (2817, 3, 4, 21, 'e-fará-sair a o-touro a de-fora ele e-queimará a-ele como-que queimou את o-touro o-primeiro ele a-congregação ela');
INSERT INTO verses VALUES (2818, 3, 4, 22, 'que príncipe pecará e-fez uma de-todo yhwh yhwh Elohim que não serão-feitas em-erro e-será-culpado');
INSERT INTO verses VALUES (2819, 3, 4, 23, 'ou a-ele a-ele pecado-dele que pecou nela e-trará a oferenda-sua macho cabras macho perfeito');
INSERT INTO verses VALUES (2820, 3, 4, 24, 'e-apoiará sua-mão sobre cabeça o-bode ele a-ele em-lugar que matará yhwh a-holocausto ele yhwh pecado ela');
INSERT INTO verses VALUES (2821, 3, 4, 25, 'e-tome o sacerdote de-sangue a-oferta-pelo-pecado com-dedo-dele e-dará sobre chifres altar-de a-holocausto e-a sangue-seu derramará a base altar-de a-holocausto');
INSERT INTO verses VALUES (2822, 3, 4, 26, 'e-a todo gordura-dele queimará ao-altar como-gordura sacrifício os-pacíficos e-fará-expiação sobre-ele o-sacerdote a-ele e-será-perdoado a-ele');
INSERT INTO verses VALUES (2823, 3, 4, 27, 'e-se uma uma pecará em-erro a-terra a-terra uma uma yhwh yhwh que não não-sejam-feitas e-será-culpado');
INSERT INTO verses VALUES (2824, 3, 4, 28, 'ou foi-conhecido a-ele pecado-dele que pecou e-trará oferta-dele cabra-fêmea cabras perfeita fêmea sobre pecado-dele que pecou');
INSERT INTO verses VALUES (2825, 3, 4, 29, 'e-apoiará a sobre sobre cabeça a-oferta-pelo-pecado e-matará a a-oferta-pelo-pecado em-lugar a-holocausto');
INSERT INTO verses VALUES (2826, 3, 4, 30, 'e-tome o-sacerdote de-sangue-dela com-dedo-dele e-dará sobre chifres altar-de a-holocausto e-a todo sangue-dela derramará a base o-altar');
INSERT INTO verses VALUES (2827, 3, 4, 31, 'e-a todo gordura-dela removerá como-que de-cima-de gordura de-sobre sacrifício a-paz e-queimará o-sacerdote ao-altar para-cheiro agradável para-יהוה e-fará-expiação sobre-ele a-ele e-será-perdoado a-ele');
INSERT INTO verses VALUES (2828, 3, 4, 32, 'e-se sujeitai ele-trará oferenda-sua fêmea fêmea perfeita ele-a-trará');
INSERT INTO verses VALUES (2829, 3, 4, 33, 'e-apoiará a sobre sobre cabeça a-oferta-pelo-pecado e-abaterá a-ela para-transgressão em-lugar que ele-abaterá a o-holocausto');
INSERT INTO verses VALUES (2830, 3, 4, 34, 'e-tome o sacerdote de-sangue a-oferta-pelo-pecado com-dedo-dele e-porá sobre chifres-de altar-de o-holocausto e-a todo sangue-dela derramará a base-de o-altar');
INSERT INTO verses VALUES (2831, 3, 4, 35, 'e-a todo gordura-dela ele-removerá como é-removida gordura-de o-cordeiro de-sacrifício-de eles e-fará-fumaça sobre a-elas yhwh sobre ofertas-de-fogo-de yhwh e-fará-expiação sobre-ele o-sacerdote a-ele pecado-seu que ele-pecou e-será-perdoado a-ele');
INSERT INTO chapters VALUES (95, 3, 5, 26);
INSERT INTO verses VALUES (2832, 3, 5, 1, 'e-alma porque ela-pecará voz voz-de juramento e-ele até ver viu ou conheceu se não ele-declarará e-levará iniquidade-sua');
INSERT INTO verses VALUES (2833, 3, 5, 2, 'ou alma que ela-tocará em-todo palavra impuro ou vivente animal impura ou animal-doméstico animal impura ou em-carcaça-de coisa-que-se-arrasta impura nós dele e-ele impuro e-será-culpado');
INSERT INTO verses VALUES (2834, 3, 5, 3, 'ou porque ele-tocará em-impureza-de homem a-todo impureza-sua que ele-se-tornará-impuro nela e-será-escondido nós e-ele saber e-será-culpado');
INSERT INTO verses VALUES (2835, 3, 5, 4, 'ou alma que ela-jurará para-falar-precipitadamente com-lábios para-fazer-mal ou para-fazer-bem para-todo a-todo ele-falará-precipitadamente o-homem o-homem e-será-escondido de-ele nós conheceu e-culpado para-uma destas');
INSERT INTO verses VALUES (2836, 3, 5, 5, 'e-acontecerá porque ele-será-culpado para-uma destas e-confessará que ele-pecou sobre-ela');
INSERT INTO verses VALUES (2837, 3, 5, 6, 'e-trará a culpa-sua sobre sobre pecado-dele que fêmea fêmea de o-rebanho cordeira ou cabra-de cabras para-oferta-de-pecado e-fará-expiação sobre-ele o-sacerdote de-pecado-seu');
INSERT INTO verses VALUES (2838, 3, 5, 7, 'e-se não sua-mão mão-sua suficiente-de cordeiro e-ele-trouxe a culpa-sua que ele-pecou duas-de rolas ou um filhos-de pomba para-יהוה um para-pecado e-um para-holocausto');
INSERT INTO verses VALUES (2839, 3, 5, 8, 'e-ele-trouxe eles a o-sacerdote e-ele-ofereceu a que para-o-pecado primeira e-ele-torceu a cabeça-sua de-em-frente-de pescoço-seu e-não ele-separará');
INSERT INTO verses VALUES (2840, 3, 5, 9, 'e-aspergirá de-sangue o-pecado sobre parede-de o altar e-o-restante em-o-sangue ele-será-espremido a base-de ele pecado ela');
INSERT INTO verses VALUES (2841, 3, 5, 10, 'e-a o-segundo ele-fará holocausto como-o-juízo e-fará-expiação sobre-ele o-sacerdote de-pecado-seu que a-ele e-será-perdoado a-ele');
INSERT INTO verses VALUES (2842, 3, 5, 11, 'e-se não sua-mão mão-sua para-duas-de rolas ou para-dois filhos-de Jonah e-trará a oferta-dele que ele-pecou dezavos a-efe farinha-de-trigo para-oferta-de-pecado não colocará em-aquela que e-não dará sobre-ela de-bálsamo porque pecado ela');
INSERT INTO verses VALUES (2843, 3, 5, 12, 'e-a-traria-a a o-sacerdote e-pegou o-sacerdote de-a cheio-de da-parte-que-ele-pegou a a-oferta-memorial e fez-fumaça sobre sobre yhwh yhwh ela e-la');
INSERT INTO verses VALUES (2844, 3, 5, 13, 'e-perdoaria sobre-ele o-sacerdote sobre pecado-suo que pecou de-uma a-ele e-perdoado-ficará a-ele e-será para-o-sacerdote como-de-pan-do-offerta');
INSERT INTO verses VALUES (2845, 3, 5, 14, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2846, 3, 5, 15, 'alma porque você-oferecerá em-alto e-pecou-a-mulher por-erro yhwh yhwh e-ele-trará a a-sua-oferta-pelo-pecado para-yhwh um-touro  תָּמִ֣ים  de o-rebanho em-o-valor-dele de-prata- שְׁקָלִ֥ים no-sheqel-de- o-santo para-o-expiatório');
INSERT INTO verses VALUES (2847, 3, 5, 16, 'e-a que pecou de o-santo pagará e-a a-seu-cinquenta José ele e colocou ele para-o-sacerdote e-o-sacerdote perdoará sobre-ele com-a-ovelha a-ele e-será-perdoado a-ele');
INSERT INTO verses VALUES (2848, 3, 5, 17, 'e-se que porque tu-pecarás uma uma yhwh mandamentos-de não que não serão-feitas e-não conheceu e-culpado e-levará iniquidade-sua');
INSERT INTO verses VALUES (2849, 3, 5, 18, 'e-o-trará a-ovelha-machão perfeito de o-rebanho em-o-valor-seu para-a-oferta-pelo-pequeno-erro a o-sacerdote e-perdoará sobre o sacerdote sobre da-seu-erro que inadvertido a-ele não conheceu e-será-perdoado a-ele');
INSERT INTO verses VALUES (2850, 3, 5, 19, 'a-oferta-pelo-pequeno-erro ele culpado pecar para-יהוה');
INSERT INTO verses VALUES (2851, 3, 5, 20, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2852, 3, 5, 21, 'alma que pecará e-ofenderá ofensa em-Javé e-negará em-seu-amigo em-arrasto ou mão mão ou no-furto ou oprimiu a seu-amigo');
INSERT INTO verses VALUES (2853, 3, 5, 22, 'ou encontrou perdido e-negou-se nela e-jurou sobre de-toda sobre o-homem de-todo que ele-fará o-homem para-pecar nele-a');
INSERT INTO verses VALUES (2854, 3, 5, 23, 'e-será-que porque ele-pecará e-será-culpado e-devolver-á a a-rapina que roubou ou a o-que-faz-a-opressão que oprimiu ou a a-responsabilidade-de-devolução que o-pagamento-do-fiscal encontrou ou a o-perdido que מָצָֽא׃');
INSERT INTO verses VALUES (2855, 3, 5, 24, 'ou- de-toda que jura-se em-ele-o para-a-falsez ele ele com-no-cabeça-seu e-ele-quinto-seu adicionará sobre-ele ele a-ele para-ele dará-o-a em-dia culpa-seu');
INSERT INTO verses VALUES (2856, 3, 5, 25, 'e-a culpa-seu traga-o a-yhwh veado perfeito de o-rebanho em-o-teu-valor para-a-expiatória a o-sacerdote');
INSERT INTO verses VALUES (2857, 3, 5, 26, 'e-fará-expiação sobre-ele o-sacerdote diante-de yhwh e-se-lhe-perdoará a-ele sobre de-toda de-todo que faz-o para-a-culpa em-ela');
INSERT INTO chapters VALUES (96, 3, 6, 23);
INSERT INTO verses VALUES (2858, 3, 6, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2859, 3, 6, 2, 'ordene a Arão dizendo esta dizendo esta ela o-holocausto sobre a-sacrifício sobre acendedor sobre o-altar todo a-noite até a-manhã e-fogo o-altar será-acendida em-ele');
INSERT INTO verses VALUES (2860, 3, 6, 3, 'e-vestirá o sacerdote de-seu [בַ֗ד] e-calções-de linhas ele-vestirá sobre carne-seu e-ele-alçará comerás que você-comerá a-chama a a-holocausto sobre o-altar e-ele-colocará junto o-altar');
INSERT INTO verses VALUES (2861, 3, 6, 4, 'e-despirá a as-roupas-seu e-vestirá roupas outros e-sairá a o-deshen a de-fora para-o-machane a lugar puro');
INSERT INTO verses VALUES (2862, 3, 6, 5, 'e-a-esh sobre o-mizbeah não em-ele não te-kbeh ve-bear al-eha o-sacerdote madeiras ba-voker no-manhã ve-arakh sobre-ela ha-olah e-ele-queimou sobre-ela de-a-gordura os-sacrifícios-de-paz');
INSERT INTO verses VALUES (2863, 3, 6, 6, 'fogo permanente será-queimada sobre não não se-apagará');
INSERT INTO verses VALUES (2864, 3, 6, 7, 'e-esta lei-de a-oferenda o-trazer-near ela-a filhos-de Arão yhwh yhwh a face-de o-altar');
INSERT INTO verses VALUES (2865, 3, 6, 8, 'e-ele-levantará nós em-o-centro de-a-massa a-oferenda e-de-o-óleo e-את todo a-lábdana que sobre a-oferenda e fez-fumaça o-altar cheiro oferta memória-de-a para-יהוה');
INSERT INTO verses VALUES (2866, 3, 6, 9, 'e-o-restante de-a eles-comerão Aarão e-seus-filhos pães-ásperos ser-aco-lida em-o-loco santo na-corte tenda-de encontro eles-a-comerão');
INSERT INTO verses VALUES (2867, 3, 6, 10, 'não ser-aco-lida fermentado parte-dele dei a-ela de-a-chama-meu santo-de santos ela como-a-iniquidade e-como-o-sacrifício');
INSERT INTO verses VALUES (2868, 3, 6, 11, 'todo macho em-os-filhos Arão ele-as-irá-comer lei- eterno yhwh de-os-fogos yhwh todo que ele-tocará neles ele-será-santificado');
INSERT INTO verses VALUES (2869, 3, 6, 12, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2870, 3, 6, 13, 'este oferta Arão e-seus-filhos que trarão a-יהוה em-dia-de ele a-ele décima-parte o-efe farinha-fina oferta permanente meio-dele de-manhã e-meio-dele no-o-crepúsculo');
INSERT INTO verses VALUES (2871, 3, 6, 14, 'sobre de-a-mancha em-o-a-oleo será-fazida de-murbecha trará-a-a de-tubina de-mincha pedaços tu-oferecerás aroma-de tranquilidade para-יהוה');
INSERT INTO verses VALUES (2872, 3, 6, 15, 'e-o-sacerdote o-mashuach em-a-sua-baixo de-seus-construções fará ela lei- perpétuo a-yhwh inteiro queimará');
INSERT INTO verses VALUES (2873, 3, 6, 16, 'e-todo oferenda-de sacerdote inteiro não não será-comido');
INSERT INTO verses VALUES (2874, 3, 6, 17, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2875, 3, 6, 18, 'palavra a Arão dizendo esta dizendo esta lei-de-a a-oferta-pelo-pecado em-o-lugar que se-a-prostrar a-sacrifício se-a-prostrar yhwh diante-de yhwh ela santos e-la');
INSERT INTO verses VALUES (2876, 3, 6, 19, 'o-sacerdote o-purificador a-ela a-comes-a em-lugar santo ser-comes-a na-corte tenda reunião');
INSERT INTO verses VALUES (2877, 3, 6, 20, 'todo que se-fatigue em-a-carne-de-ela ser-santificado e-que se-lavará de-sangue-dela sobre o-vestuário que se-lavará sobre-ela lavará-se em-o-lugar santo');
INSERT INTO verses VALUES (2878, 3, 6, 21, 'e-vesselário- buraco que ser-cozido- nele que-se-partirá e-se em-vaso de-bronze foi-cozida e-unte e-lave-se com-a-água');
INSERT INTO verses VALUES (2879, 3, 6, 22, 'todo macho em-os-sacerdotes comer-á ela santidade-de ela e-la');
INSERT INTO verses VALUES (2880, 3, 6, 23, 'e-todo pecado que ser-á-trazido de-seu-sangue a tenda encontro não ao-sanctuário não ser-á-comida com-fogo ser-á-consumido');
INSERT INTO chapters VALUES (97, 3, 7, 38);
INSERT INTO verses VALUES (2881, 3, 7, 1, 'e-esta torah-de o-pecado santidade-de os-santos ele');
INSERT INTO verses VALUES (2882, 3, 7, 2, 'em-o-lugar que eles-imolam a o-holocausto eles-imolam a o-pecado e-a sangue-seu ele-jogará sobre o-altar ao-redor');
INSERT INTO verses VALUES (2883, 3, 7, 3, 'e-a todo gordura-sua nós de-ele a a-subida e-a o-gordura o-que-cobre a as-entranhas');
INSERT INTO verses VALUES (2884, 3, 7, 4, 'e-את duas os-rins e-a a-gordura que sobre-eles que sobre os-lombos e-a o-lóbulo sobre o-fígado sobre os-rins removerá-a');
INSERT INTO verses VALUES (2885, 3, 7, 5, 'e-fará-fumaça eles o-sacerdote ao-altar mulher a-yhwh asom ele');
INSERT INTO verses VALUES (2886, 3, 7, 6, 'todo macho em-o-kohanim o-e-ocle-no no-makom santo e-o-eche-le santidade-de ele ela');
INSERT INTO verses VALUES (2887, 3, 7, 7, 'ka-hachatata ka-asom torah uma a-eles o-sacerdote que yechaper- a-ele será será');
INSERT INTO verses VALUES (2888, 3, 7, 8, 'e-o-sacerdote o-maqurib a olat- pele pele-de ha-olah que hiqrib a-ele será será');
INSERT INTO verses VALUES (2889, 3, 7, 9, 'e-todo minchah que teafah- bat-tanur e-todo naasah bamarcheshet e-sobre machavat a-ele o-maquive a-ela para-ele serás');
INSERT INTO verses VALUES (2890, 3, 7, 10, 'e-todo oferta-cereais em-estado-de em-o-óleo e-espad-a para-todo filhos-de de-Aaron será homem como-seu-irmão');
INSERT INTO verses VALUES (2891, 3, 7, 11, 'e-esta tor-a-de sacrifício-de os-pacíficos que aproximará para-יהוה');
INSERT INTO verses VALUES (2892, 3, 7, 12, 'mãe sobre tod-a oferecerá-o e-oferecerá sobre sacrifício-de a-atitude-de-gratidão bolos massas-de-farinha misturados com-o óleo e biscoitos-de não-fermentados ungidas -com-óleo e-farinha-de-grão-mole misturada bolos -misturados em-o-óleo-verso');
INSERT INTO verses VALUES (2893, 3, 7, 13, 'sobre pão pão fermentado-masculino-singular ele-aproximará oferenda-sua sobre sacrifício-masculino-singular ação-de-graças-feminina-singular seus-paz-seus-verso');
INSERT INTO verses VALUES (2894, 3, 7, 14, 'e trouxe-próximo nós um de-todo oferta-masculino-singular dádiva-feminina-singular a-yhwh para-o-sacerdote o-que-joga a a-ele será para-ele será');
INSERT INTO verses VALUES (2895, 3, 7, 15, 'e-na-carne o-sacrifício a-acção-de-graças seus-da-paz em-dia oferenda-sua ser-comes não nós dele até manhã');
INSERT INTO verses VALUES (2896, 3, 7, 16, 'e-se o-voto ou a-oferta-voluntária o-sacrifício oferenda-dele em-dia-de seu-que-ele-apresentou a o-seu-sacrifício ser-aco-lido e-de-a-ma-hor-ta nós dele ser-aco-lido');
INSERT INTO verses VALUES (2897, 3, 7, 17, 'e-o-no-te-ro de-ba-sar o-zav-a-ch no-dia o-terceiro b-a-esh será-queimado');
INSERT INTO verses VALUES (2898, 3, 7, 18, 'e-se e-ac-o-l ser-aco-lido de-ba-sar zevach no-dia no-dia não não yeratzeh ele não não a-ele a-ele será yihye e-a-alma nós dele avonah tissah');
INSERT INTO verses VALUES (2899, 3, 7, 19, 've-habasar que yigga não tamai não yeakhel em-a-foi será-consagrado e-o-carne todo puro comerá carne');
INSERT INTO verses VALUES (2900, 3, 7, 20, 'e-a-alma que comerá carne do-altar o-salmos que para-יהוה e-sua-imundície sobre-ele e-ser-cortado aquela a-essa de-a-tribos');
INSERT INTO verses VALUES (2901, 3, 7, 21, 'e-alma porque tocar-á em-todo homem em-a-imundície homem ou de-animais impura ou em-todo e-coma impuro e-comerá da-carne-de sacrifício do-sacrifícios que aquela e-ser-cortado a-alma a-essa de-seus-povos');
INSERT INTO verses VALUES (2902, 3, 7, 22, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2903, 3, 7, 23, 'palavra a filhos-de dizendo dizendo todo gordura boi não e-avesso não comereis');
INSERT INTO verses VALUES (2904, 3, 7, 24, 'e-gordura carcaça e-gordura animal-morto será-fazido para-todo trabalho não não comê-lo-vos');
INSERT INTO verses VALUES (2905, 3, 7, 25, 'que todo comedor sabugo de o-gado que aproximará mimenah- mulher a-yhwh e-ser-cortado a-alma que-comendo de-seus-povos');
INSERT INTO verses VALUES (2906, 3, 7, 26, 'e-todo não comereis comêis em-todo moradas-vossas ao-pássaro e-ao-animal');
INSERT INTO verses VALUES (2907, 3, 7, 27, 'todo alma que comer-ás todo aquela e-ser-cortado a-alma a-essa de-seus-povos');
INSERT INTO verses VALUES (2908, 3, 7, 28, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2909, 3, 7, 29, 'palavra a filhos-de dizendo dizendo o-trazendo-nearragemento a sacrifício seus-de-paz para-יהוה trará a oferenda-sua para-יהוה do-sacrifício seus-de-paz');
INSERT INTO verses VALUES (2910, 3, 7, 30, 'suas-mãos traga-as a ofertas-de-fogo-de yhwh a o-gordura sobre o-peito ele-o-traga a ele para-sprinkle a-ele yhwh diante-de yhwh');
INSERT INTO verses VALUES (2911, 3, 7, 31, 'e-ele-queime o-sacerdote a o-gordura o altar-para e-foi o-peito para-Aarão e-ele-seus-filhos');
INSERT INTO verses VALUES (2912, 3, 7, 32, 'e-את coxa o-direito vocês-serão oferta para-o-sacerdote dos-araus de-seus-sacrifícios-de-paz');
INSERT INTO verses VALUES (2913, 3, 7, 33, 'o-oferecendo a sangue os-de-paz e-a o-gordura a-ele Aarão para-ele ser-ás lado a-direita para-ele');
INSERT INTO verses VALUES (2914, 3, 7, 34, 'que a vê a-sacrifício e-את lado a-oferta tom-eu de-junto-de filhos-de Israel de-altar-s da-sacrifício-seus eles aqueles-eles para-Aarão o-sacerdote e-para-seus-filhos por-tempo eterno de-com filhos-de Israel');
INSERT INTO verses VALUES (2915, 3, 7, 35, 'esta oferta-de-unção Arão e-oferta-de-unção filhos-dele de-os-fogos yhwh em-dia-de ofereceu eles para-servir para-יהוה');
INSERT INTO verses VALUES (2916, 3, 7, 36, 'que ordenou yhwh para-dar a-eles em-dia-de mash-ho eles de-com filhos-de Israel chuq-at eternidade para-gerações-eles');
INSERT INTO verses VALUES (2917, 3, 7, 37, 'esta a-Torah la-olah la-minchah ve-la-chat-ta-at ve-la-a-sham ve-la-mil-lu-im ul-zevach ha-shelamim');
INSERT INTO verses VALUES (2918, 3, 7, 38, 'que ordenou yhwh a Moisés em-monte-de Si-na-y no-dia tzav-to a filhos-de Israel para-o-levantar a suas-ofertas para-יהוה em-deserto-de Sinai');
INSERT INTO chapters VALUES (98, 3, 8, 36);
INSERT INTO verses VALUES (2919, 3, 8, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (2920, 3, 8, 2, 'toma a Arão e-a filhos-seus com-ele e-את os-vestidos e-a azeite a-unção e-את touro o-sacrifício-do-pecado e-את segundo os-ovelhas e-a cesto das-pães-ásperos');
INSERT INTO verses VALUES (2921, 3, 8, 3, 'e-a todo a-congregação o-reunir a entrada tenda-de encontro');
INSERT INTO verses VALUES (2922, 3, 8, 4, 'E-fez Moisés como-que ordenou yhwh ele e-ela-se-reuniu a-congregação a entrada-de tenda-de encontro');
INSERT INTO verses VALUES (2923, 3, 8, 5, 'E-disse Moisés a a-congregação este a-palavra yhwh ordenou yhwh para-fazer');
INSERT INTO verses VALUES (2924, 3, 8, 6, 'e-ele-se-aproximou Moisés a אַהֲרֹן e-a eles e-ele-se-lavou eles no-a-guas');
INSERT INTO verses VALUES (2925, 3, 8, 7, 'E-colocou sobre-ele a a-roupa-interna ele ele com-o-fato ele ele E-colocou o ma''il E-deu sobre-ele ele a ephod e ele amarrou a-ele a-ele o ephod e ele vestiu o ephod para-ele em-ele');
INSERT INTO verses VALUES (2926, 3, 8, 8, 'e-colocou sobre-ele a E-colocou E-deu a o choshen a dos brilhantes e-a os-tumis');
INSERT INTO verses VALUES (2927, 3, 8, 9, 'e-colocou a הַמִּצְנֶפֶת sobre sua-cabeça e-ele-postou sobre o-mitzenefet a o-ouro as-pnai a tzitz o-ouro yhwh o-santuário como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2928, 3, 8, 10, 'E-tomou Moisés a óleo o-mishcha e-eimshach a o-tabernáculo eles todo que nele ve-yekadesh a-eles');
INSERT INTO verses VALUES (2929, 3, 8, 11, 've-eyaz nós o-altar sete vezes e-eimshach a o-mizbeach e-a todo keilai e-a o-lavabo e-a seu-copo para-santificá-los-verso-final');
INSERT INTO verses VALUES (2930, 3, 8, 12, 'e-ele-derramou de-a-oleo do-consagracao sobre cabeça Aarão e-ele-ungiu ele para-santificá-lo-verso-final');
INSERT INTO verses VALUES (2931, 3, 8, 13, 'e-ele-ofereceu Moisés a filhos-de Arão e-vestiu-eles roupas-de-algodão eles a-elas cinto a-eles a-eles de-capuz como yhwh yhwh a Moisés');
INSERT INTO verses VALUES (2932, 3, 8, 14, 'e-avançou a touro a-oferta-pelo-pecado e-apoiou-se אַהֲרֹן e-filhos-dele a mãos-deles sobre cabeça touro-de do-pecado');
INSERT INTO verses VALUES (2933, 3, 8, 15, 'e-imolou E-tomou Moisés a E-colocou E-deu sobre cornes o-matzbeach ao-redor com-dedo-dele e-vichate a o-altar e-a o-sangue yatzaq a base-de o altar ve-yiqaddeshu para-expiar sobre-ele');
INSERT INTO verses VALUES (2934, 3, 8, 16, 'E-tomou a todo o-chalev asher sobre o-qerev e-את yoteret o-fígado e-a duas-de os-rins ve-et a-sua-gordura e-ele-queimou Moisés o-altar-para');
INSERT INTO verses VALUES (2935, 3, 8, 17, 'e-a o-bezerro e-a sua-pele e-a carne-seu e-a ele-estendeu queimou no-fogo yhwh para-o-lager como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2936, 3, 8, 18, 'e-ele-aproximou a o-touro o-holocausto e-eles-aproximaram-se Arão e-filhos-dele a mãos-deles sobre cabeça o-abelhaue');
INSERT INTO verses VALUES (2937, 3, 8, 19, 'e-ele-spicou e-ele-jogou Moisés a o-sangue sobre o-altar ao-redor');
INSERT INTO verses VALUES (2938, 3, 8, 20, 'e-a o-abelhaue foi-nicotado para-seus-nicotamentos e-ele-queimou-com-incenso Moisés a o-cabeça e-a os-nicotados e-a o-pader');
INSERT INTO verses VALUES (2939, 3, 8, 21, 'e-a o-proximidade e-a os-juntas lavou-se nas-águas e-queimou-incenso Moisés a ele o-touro do-altar ele ele para-o-cheiro- agradável yhwh ele para-יהוה como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2940, 3, 8, 22, 'e-aproximou a o-touro o-segundo touro os-enchimentos e-ele-apoiaram-se Arão e-filhos-dele a mãos-deles sobre cabeça o-touro');
INSERT INTO verses VALUES (2941, 3, 8, 23, 'e-ele-imolou E-tomou E-tomou do-seu-sangue E-deu E-colocou tubo o-relho- אַהֲרֹן a-direita sua-mão neles mão-dele a-direita e-sobre bohen ragleo ha-yemanit');
INSERT INTO verses VALUES (2942, 3, 8, 24, 'va-yakrev a filhos-de Arão Moisés de ha-dam sobre tenukh oznam ha-yemanit e-sobre neles yadam a-direita e-sobre os-bones de-seus-pés a-direita e-ele-espalhou Moisés a o-sangue sobre o-do-macrônio-altar ao-redor');
INSERT INTO verses VALUES (2943, 3, 8, 25, 'E-tomou a a-de-graxa e-a a-subida e-com tudo-de de-graxa que sobre o-interno e-את mais-alta o-fígado e-a duas-de os-rins e-com a-sua-gordura e-a coxa a-direita');
INSERT INTO verses VALUES (2944, 3, 8, 26, 'e-de-a-salva os-maçōs que diante-de yhwh yhwh tomou pão-azeviche uma uma pão-de pão uma uma um um sobre o-de-leite e-sobre coxa o-direito');
INSERT INTO verses VALUES (2945, 3, 8, 27, 'E-colocou a sobre sobre mãos-de Arão e-sobre mãos-de seus-filhos eles a-eles oferta-elevação yhwh yhwh');
INSERT INTO verses VALUES (2946, 3, 8, 28, 'Moisés a-elas eles de-cima-de e-queimou o-altar sobre o-holocausto enchimentos eles para-aroma suave mulher ele para-יהוה');
INSERT INTO verses VALUES (2947, 3, 8, 29, 'E-tomou Moisés a o-di-fígado e-o-elevou oferta-elevação yhwh yhwh de-a-erva os-de-preenchimento ser foi para-o-tempo como yhwh yhwh a Moisés');
INSERT INTO verses VALUES (2948, 3, 8, 30, 'E-tomou Moisés de-a-oleo a-da-unção e-de o-sangue que sobre do-ara [עַל־בְּגָדָ֔יו] sobre Arão sobre as-roupas-seu e-sobre os-filhos-dele e-sobre de-roupas filhos-dele com-ele e-santificou a Arão a os-de-seus-vestidos e-a os-filhos-dele e-a de-roupas filhos-dele com-ele');
INSERT INTO verses VALUES (2949, 3, 8, 31, 'E-disse Moisés a Aarão e-a filhos-seus cozinharam a a-carne-o entrada-de tenda ele e ali comereis a-ele e- o-pão que dizendo os-de-preenchimento-os como-que mandei-eu para-dizer Aarão e-seus-filhos o-comerão');
INSERT INTO verses VALUES (2950, 3, 8, 32, 'e-o-restante em-a-carne e-no-pão com-fogo queimareis');
INSERT INTO verses VALUES (2951, 3, 8, 33, 'e-de-a-entrada tenda encontro não sair-vós sete-de dias até dia de-encher dias-de de-vos-encher que sete-de dias ele-encherá a vossas-mãos');
INSERT INTO verses VALUES (2952, 3, 8, 34, 'como-que fez no-dia esta ordenou yhwh para-fazer para-expiar sobre-vós');
INSERT INTO verses VALUES (2953, 3, 8, 35, 'e-porta tenda encontro vós-vos-estabelecereis dia e-noite sete-de dias e-vigiai a yhwh yhwh e-não morrai porque assim mandei');
INSERT INTO verses VALUES (2954, 3, 8, 36, 'E-fez אַהֲרֹן e-seus-filhos a todo as-palavras yhwh ordenou yhwh por-mão-de Moisés');
INSERT INTO chapters VALUES (99, 3, 9, 24);
INSERT INTO verses VALUES (2955, 3, 9, 1, 'e-houve no-dia o-oitavo chamou Moisés para-Aarão e para filhos-seus e-para-os-idosos Israel');
INSERT INTO verses VALUES (2956, 3, 9, 2, 'E-disse a Arão toma a-vos bezerro filho-de manhã para-peca e-touro para-oferta yhwh e-o-aproximar diante-de yhwh');
INSERT INTO verses VALUES (2957, 3, 9, 3, 'e-a filhos-de Israel dizendo dizendo tomai Seir cabras para-transgressão e-bezerro e-cordeiro filhos-de ano perfeitos para-holocausto');
INSERT INTO verses VALUES (2958, 3, 9, 4, 'e-boi e-touro para-paz para-sacrificar diante-de yhwh e oferta em-estado-de-mistura com-o-açúcar que o-dia yhwh apareceu a-vós');
INSERT INTO verses VALUES (2959, 3, 9, 5, 'e-eles-tomaram a que ordenou Moisés a face-de tenda de-encontro e-eles-se-aproximaram todo a-congregação yhwh diante-de yhwh');
INSERT INTO verses VALUES (2960, 3, 9, 6, 'E-disse Moisés este-isto a-palavra que yhwh yhwh fazeis-vós E-viu a-vós yhwh yhwh');
INSERT INTO verses VALUES (2961, 3, 9, 7, 'E-disse Moisés a Arão oferta a o-altar e-fazes a pecado-teu e-a oferta-teu e-perdoa em-teu-lugar e atrás-de o-povo e-faz a oferenda-de yhwh e-perdoa em-o-lugar-de-homem conforme ordenou yhwh');
INSERT INTO verses VALUES (2962, 3, 9, 8, 'e-ele-se-aproximou אַהֲרֹן a o-altar e-ele-imolou a bezerro do-pecado que a-ele');
INSERT INTO verses VALUES (2963, 3, 9, 9, 'e-eles-se-aproximaram filhos-de Aarão a a-ele a-ele-o e-banhou-se o-dedo-dele E-colocou E-deu sobre as-chifres o-altar e-a do-sangue derramou a base o-altar');
INSERT INTO verses VALUES (2964, 3, 9, 10, 'e-a a-gordura e-a das-vidros e-a a-mais de do-fígado de yhwh queimou-um-sacrifício o altar-para como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (2965, 3, 9, 11, 'e-a a-carne e-a a-pele queimou no-fogo fora-de o-lager');
INSERT INTO verses VALUES (2966, 3, 9, 12, 'e-queimou-o-sacrifício a o-holocausto e-encontraram filhos-de a-ele a-ele a o-sangue e-esperneou-o sobre o-altar ao-redor');
INSERT INTO verses VALUES (2967, 3, 9, 13, 'e-a a-oferta a-ele para-ele para-os-seus-membros e-a a-cabeça e-ele-queimou sobre o-altar');
INSERT INTO verses VALUES (2968, 3, 9, 14, 'e-ele-lavou a o-intestino e-a os-juntas e-ele-queimou sobre a-holocausto o-altar-para');
INSERT INTO verses VALUES (2969, 3, 9, 15, 'e-ele-aproximou a oferenda o-povo E-tomou a a-besta-caprina a-oferta-pelo-pecado que para-o-povo e-ele-sacrificou-o e-o-pecou como-a-primeira-vez');
INSERT INTO verses VALUES (2970, 3, 9, 16, 'e-ele-se-aproximou a o-holocausto e-ele-fêz-a como-o-julgamento');
INSERT INTO verses VALUES (2971, 3, 9, 17, 'e-ele-se-aproximou a a-oferta-de-pão e-ele-cheiou sua-mão de-a e-coletou sobre o-altar fora-de-a oferta-que-subiu a-manhã');
INSERT INTO verses VALUES (2972, 3, 9, 18, 'e-ele-imolou a o-touro e-a a-avela sacrifício a-paz que para-o-povo e-eles-acharam filhos-de a-ele a o-sangue para-ele e-os-espargiu sobre o-altar ao-redor');
INSERT INTO verses VALUES (2973, 3, 9, 19, 'e-a os-mamíeiros de o-touro e-de o-veado a-alma e-o-cobridor e-as-âmadas e-a-sobra do-fígado');
INSERT INTO verses VALUES (2974, 3, 9, 20, 'e-os-colocaram a os-leiteiros sobre as-visionárias e-queimou os-leiteiros o-altar-para');
INSERT INTO verses VALUES (2975, 3, 9, 21, 'e-a a-vision e-את coxa o-direito levantou de-Aaron oferta diante-de yhwh como ordenou Moisés');
INSERT INTO verses VALUES (2976, 3, 9, 22, 'e-ele-leva Arão a a o-povo e-eles-bendizem e-ele-desce de-fazer o-pecado e-a-oferta e-o-sacrifício-de-paz');
INSERT INTO verses VALUES (2977, 3, 9, 23, 'E-veio Moisés e-Aarão a tenda encontro e-eles-saem e-ele-bendizem a o-povo E-viu glória-de- yhwh a todo o-povo');
INSERT INTO verses VALUES (2978, 3, 9, 24, 'e-ela-sai fogo de-diante-de yhwh e-comeste sobre o altar a E-viu e-a os-leiteiros E-viu todo o-povo e-ele-ronou e-caíram sobre em-seus-faces');
INSERT INTO chapters VALUES (100, 3, 10, 20);
INSERT INTO verses VALUES (2979, 3, 10, 1, 'e-eles-tomaram filhos-de Aharon Nadab e-Abihu homem seu-tronco-de-fogo e-eles-soltaram nelas fogo e-ele-empurraram sobre-ela fumo-de-oferenda e-eles-se-aproximaram yhwh yhwh fogo estranha não não eles a-eles');
INSERT INTO verses VALUES (2980, 3, 10, 2, 'e-ela-saiu fogo de-a-frente-de yhwh e-comeste eles e-eles-morreram diante-de yhwh');
INSERT INTO verses VALUES (2981, 3, 10, 3, 'E-disse Moisés a ele ele-que yhwh palavra dizendo para-dizer em-meus-próximos eu-santificarei e-sobre face-de todo o-povo eu-exaltarei e-ele-caiu-em-silêncio Aharon');
INSERT INTO verses VALUES (2982, 3, 10, 4, 'E-chamou Moisés a e-para e-a Eltsafan filhos-de Uziael amante E-disse E-disse a-eles aproximem-se levantem a irmãos-vossos de-junto-de face-de o-santuário a fora- -do-machaneh');
INSERT INTO verses VALUES (2983, 3, 10, 5, 'e-eles-se-aproximaram e-ele-os-levantou -em-mantos-deles a fora- -para-o-machaneh conforme palavra Moisés');
INSERT INTO verses VALUES (2984, 3, 10, 6, 'E-disse Moisés a arão e-a-elazar e-a-itamar -seus-filhos cabeças-vos a descontareis e-vestidos-vos não descontareis e-não morrireis e-sobre todo a-congregação irar-se-á e-irmãos-vos todo casa Israel chorareis yhwh a-destruição que queimar yhwh');
INSERT INTO verses VALUES (2985, 3, 10, 7, 'e-de-a-entrada tenda encontro não sair-vós para-que-não morrer-vós porque yhwh de-o-sacrifício yhwh sobre-vós e-fizeram conforme-palavra-de Moisés');
INSERT INTO verses VALUES (2986, 3, 10, 8, 'e-falou yhwh a dizendo para-dizer');
INSERT INTO verses VALUES (2987, 3, 10, 9, 'vinho e-de-álcool a beber-vós tu e-filhos-teu com-você em-a-chegada-de-voces a tenda-de encontro e-não morrem chuq-at eternidade para-gerações-de-vocês');
INSERT INTO verses VALUES (2988, 3, 10, 10, 'e-para-separar entre o-santo e-entre o-secular e-entre o-imundo e-entre o-puro');
INSERT INTO verses VALUES (2989, 3, 10, 11, 'e-para-dar-mandamentos a filhos-de Israel a todo as-leis yhwh palavra yhwh a-eles por-mão-de Moisés');
INSERT INTO verses VALUES (2990, 3, 10, 12, 'e-falou Moisés a e-para e-a Elazar e-a Itamar os-seus-filhos os-novamente-restantes tomem a a-oferenda yhwh de-a-chamas yhwh e-comam-na não-fermentados que o-altar porque ela santidades e-la');
INSERT INTO verses VALUES (2991, 3, 10, 13, 'e-voces-comeram a-ela em-o-lugar santo que lei-teu e-lei- ela ele yhwh yhwh porque assim comande-eu');
INSERT INTO verses VALUES (2992, 3, 10, 14, 'e-את veja a-sacrifício e-את coxa a-entrega comam-vós em-lugar puro tu tu e-filhas-teu contigo porque lei-tua e-lei- filhos-teus deram de-altar-de da-paz-de filhos-de Israel');
INSERT INTO verses VALUES (2993, 3, 10, 15, 'costado a-entrega e-vista da-oferta sobre fumaças das-cremesses trarão para-sacudir uma-tenufa diante-de yhwh e-será a-ti e-seus-batons contigo para-pegar-em eternamente conforme yhwh yhwh');
INSERT INTO verses VALUES (2994, 3, 10, 16, 'e-את um-sair do-pecado darásh darash Moisés e-eis soráf va-yikhtsof sobre Elazar e-sobre Itamar filhos-de Arão dizendo para-dizer');
INSERT INTO verses VALUES (2995, 3, 10, 17, 'madua'' não akhaltém a a-oferta-pelo-pecado que o-santuário porque ela santidades ela dar a-vós para-vós lashet a iniquidade a-congregação para-expiar yhwh diante-de yhwh');
INSERT INTO verses VALUES (2996, 3, 10, 18, 'eis não huvá a dama-hu a ha-kodesh penimah ako-l to-achlu ela ba-kodesh como-que tziviti');
INSERT INTO verses VALUES (2997, 3, 10, 19, 'e-falou Arão a eis o-dia ha-yom hi-qrivu a chatat-am yhwh oferta-eles diante-de yhwh e-chamaram-na me-a o-dia e-comerei pecado yhwh o-bom em-olhos-de yhwh');
INSERT INTO verses VALUES (2998, 3, 10, 20, 'E-ouviu Moisés e-foi-bom em-seus-olhos');
INSERT INTO chapters VALUES (101, 3, 11, 47);
INSERT INTO verses VALUES (2999, 3, 11, 1, 'e-ele-falou yhwh a Moisés dizendo אַהֲרֹן dizendo a-eles');
INSERT INTO verses VALUES (3000, 3, 11, 2, 'falem a filhos-de dizendo esta esta a-vida que comereis de-todo o-animal que sobre a-terra');
INSERT INTO verses VALUES (3001, 3, 11, 3, 'todas esmaga-ora esmagou-a e-esmagando-a esmagou esmaga-as eleva-a gume-da em-animais a-ela comereis-vos');
INSERT INTO verses VALUES (3002, 3, 11, 4, 'entretanto a não comereis com-erdes de-a-superfície-de a-geração e-de-as-frações-de da-partilha a o-camelo ele de-a-superfície-de a-geração ele e-parte-do-peito ele a-vós impuro ele para-vocês');
INSERT INTO verses VALUES (3003, 3, 11, 5, 'e-a a-pantera porque ele gêra não e-parte-do-peito não ele a-vós ele para-vocês');
INSERT INTO verses VALUES (3004, 3, 11, 6, 'e-a a-lebre porque ela gerah não e-parsa não ela a-vós ela para-vocês');
INSERT INTO verses VALUES (3005, 3, 11, 7, 'e-a o-chazir porque ele parsa ele e-sosae esmagou parsa e-ele gerah ele a-vós impuro ele para-vocês');
INSERT INTO verses VALUES (3006, 3, 11, 8, 'de-misar-am não vós-comereis e-bnivlatam não tegauu tmeim eles a-vós');
INSERT INTO verses VALUES (3007, 3, 11, 9, 'a este de-toda de-todo que nas-águas todo que a-ele snpfr vkshqst bmyym eles vbnhlm  a eles comereis-vos');
INSERT INTO verses VALUES (3008, 3, 11, 10, 'e-tudo que não-há a-ele snpfr vkshqst byymm de-toda de-todo coisa-que-se-arrasta as-águas vmkl alma a-viva que nas-águas eles a-vós para-vocês');
INSERT INTO verses VALUES (3009, 3, 11, 11, 'vskts serão a-vós mbshr não vós-comereis e-a carne-de-seus abominar-vos-eis');
INSERT INTO verses VALUES (3010, 3, 11, 12, 'todo que não-há para-ele unha-grande e-unha-pequena nas-águas ele a-vós para-vocês');
INSERT INTO verses VALUES (3011, 3, 11, 13, 'e-a estes abominar-vos-eis não a-ave não eles abominação eles a a-águia-grande e-a a-águia-de-pescoço-vermelho e-a a-avestruz');
INSERT INTO verses VALUES (3012, 3, 11, 14, 'e-a a da''ah conforme-sua-espécie a ayah para a minah');
INSERT INTO verses VALUES (3013, 3, 11, 15, 'a todo conforme-sua-espécie');
INSERT INTO verses VALUES (3014, 3, 11, 16, 'e-את בת a ya''anah e-a a ta''chamas e-a conforme-sua-espécie e-a o netz para a minoohu');
INSERT INTO verses VALUES (3015, 3, 11, 17, 'e-a o copo e-a a lançada e-a o arrebatado');
INSERT INTO verses VALUES (3016, 3, 11, 18, 'e-a a suspirada e-a a que geme e-a o misericordioso');
INSERT INTO verses VALUES (3017, 3, 11, 19, 'e-את a-chasida o-anafa conforme-sua-espécie e-a a-duchifat e-a o-atalef');
INSERT INTO verses VALUES (3018, 3, 11, 20, 'todo coisa-que-se-arrasta a-ave o-que-vai sobre quatro ele a-vós para-vocês');
INSERT INTO verses VALUES (3019, 3, 11, 21, 'entretanto a este de-toda de-todo coisa-que-se-arrasta o-que-vai o-andando sobre quatro que de-genuas do-em-o-alto para-a-sua-perna para-ser-espantado nelas sobre a-terra');
INSERT INTO verses VALUES (3020, 3, 11, 22, 'a estes deles tocheleu conforme-sua-espécie [וְאֶת־הַסָּלְעָ֖ם] conforme-sua-espécie e-a conforme-sua-espécie segundo-espécie-sua conforme-sua-espécie o-chargol conforme-espécie-sua e-a o-hagab para-o-seu-mine');
INSERT INTO verses VALUES (3021, 3, 11, 23, 'e-tudo coisa-que-se-arrasta a-ave que a-ele quatro pés ele a-vós para-vocês');
INSERT INTO verses VALUES (3022, 3, 11, 24, 'e-para-os-outros vós sereis contaminados todo da-pessoa-que-tocou em-a-sua-imundície será-contaminado até no entardecer');
INSERT INTO verses VALUES (3023, 3, 11, 25, 'e-todo o-que-leva de-a-sua-imundície lavará seus-vestidos e-o-contaminará até no entardecer');
INSERT INTO verses VALUES (3024, 3, 11, 26, 'para-todo a-animal ela ela-é partindo partida e-o-tritura não-ela triturando e-gomo não-ela em-alta impuros eles a-vós todo da-pessoa-que-tocou neles se-tornará-impuro');
INSERT INTO verses VALUES (3025, 3, 11, 27, 'e-tudo andando sobre as-mãos em-todo a-vida a andando sobre eles a-vós eles a-vós todo o tocando na sua imundícia será contaminado até הערב׃');
INSERT INTO verses VALUES (3026, 3, 11, 28, 'e-o-carregador a néscias-eles lavará-seu roupas-seu e-tameie até a-tarde a-vós eles para-vocês');
INSERT INTO verses VALUES (3027, 3, 11, 29, 'e-este a-vós o-tamei no-serrez o-sorrec sobre a-terra o-choled e-o-achbar conforme-sua-espécie para-minehu');
INSERT INTO verses VALUES (3028, 3, 11, 30, 'e-a-anaka e-o-kocha e-a-ltaah e-o-homet e-a-tinshemet');
INSERT INTO verses VALUES (3029, 3, 11, 31, 'Estas a-tmeim a-vós em-todo a-sharets todo a-nogeah בָּהֶ֛ם be-motam yitmaa até no entardecer');
INSERT INTO verses VALUES (3030, 3, 11, 32, 'e-tudo que yifoll- alav de-eles em-morte será-contaminado de-todo utensílio- madeira ou roupa ou pele obra saco todo utensílio que será-feito trabalho com-eles na-água será-trazido e-tame até o-crepúsculo e-taher');
INSERT INTO verses VALUES (3031, 3, 11, 33, 'e-todo utensílio-de silencio que cairá de-eles a dentro-dele todo que dentro-dele ele-se-tornará-impuro e-a-ele vocês-quebrarão');
INSERT INTO verses VALUES (3032, 3, 11, 34, 'de-todo o comido que será comido que virá águas águas ficará impuro e-todo de beber que irá beber em-todo vesselo será contaminado:');
INSERT INTO verses VALUES (3033, 3, 11, 35, 'e-tudo que cairá de-seus-lixos em-ele-o ficará-imundo forno e-vasos será-partido impuros eles e-impuros serão a-vós');
INSERT INTO verses VALUES (3034, 3, 11, 36, 'porém fonte e-borralho expectativa-de será será puro e-tocando em-a-impureza-deles será-contaminado');
INSERT INTO verses VALUES (3035, 3, 11, 37, 'e-que cairá de-a-nível-deles sobre todo semente semente que ele puro ela');
INSERT INTO verses VALUES (3036, 3, 11, 38, 'e-que será-dado- águas sobre זרע e-caiu de-a-nível-deles ele a-vós ele para-vocês');
INSERT INTO verses VALUES (3037, 3, 11, 39, 'e-que yāmūth de a-animal a-vós para-alimento para-vocês para-alimento da-pessoa-que-tocou em-o-nível-dela se-tornará-impuro até no entardecer');
INSERT INTO verses VALUES (3038, 3, 11, 40, 'e-a-pessoa-quem-comerá de-a-nível-dela lavará as-roupas-dele e-tornar-se-impuro até a-tarde e-o-que-leva a a-carne-de-sua-morte ele-lavará as-suas-roupas e-será-imundo até no entardecer');
INSERT INTO verses VALUES (3039, 3, 11, 41, 'e-todo o-enxame o-que-cruza sobre ele não ele não ser-aco-lido');
INSERT INTO verses VALUES (3040, 3, 11, 42, 'todo andando sobre e-tudo andando sobre quatro até todo muitos pés para-todo o-enxame não sobre a-terra eles vocês-comerão porque abominação eles');
INSERT INTO verses VALUES (3041, 3, 11, 43, 'a vocês-abominarão a almas-vossas em-todo o-enxame o-que-cruza e-não vocês-se-tornarão-imundos neles e-vós-ser-eis-imundos em-eles');
INSERT INTO verses VALUES (3042, 3, 11, 44, 'que eu yhwh Elohim-vossos e-vós-santificar-eis-vos e-sereis santos que santo eu e-não vocês-se-tornarão-imundos a almas-vosso em-todo o-enxame o-que-rasteja sobre a-terra');
INSERT INTO verses VALUES (3043, 3, 11, 45, 'que eu yhwh yhwh vos da-terra Egito para-ser para-vocês a-vós e-estardes e-sereis porque que eu');
INSERT INTO verses VALUES (3044, 3, 11, 46, 'esta torah-de os-animais e-o-pássaro e-tudo alma a-vida o-rastejante nas-águas e-para-todo- alma o-repugnante sobre a-terra');
INSERT INTO verses VALUES (3045, 3, 11, 47, 'para-separar entre o-imundo e-entre a-puro e-entre a-vida a-comestivel e-entre a-vida que não será-comido');
INSERT INTO chapters VALUES (102, 3, 12, 8);
INSERT INTO verses VALUES (3046, 3, 12, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3047, 3, 12, 2, 'palavra a filhos-de dizendo dizendo que porque concebe macho macho e-torna-se-imunda sete-de dias como-dias da-menstruação das-suas-impurezas torna-se-imunda');
INSERT INTO verses VALUES (3048, 3, 12, 3, 'e-no-dia הַשְׁמִינִ֑י é-uncido de-a-carne a-uncircuncisão-dele');
INSERT INTO verses VALUES (3049, 3, 12, 4, 'e-trinta dia e-três-de dias habitará em-sangue pureza em-todo santo-de não não e-a o santuário dias-de virá até de-cheio dias-de sua-pureza');
INSERT INTO verses VALUES (3050, 3, 12, 5, 'e-se fêmea dará-a-luz e-se-tornará-impura dois-sete como-a-menstruação-sua dia dia e-seis dias tensebe sobre sangues-de ta-hora');
INSERT INTO verses VALUES (3051, 3, 12, 6, 'u-vimloat dias-de dias-de leven ou levat tavi-a sujeitai filho-de shnato para-oferta e-filho-de yona ou tor para-oferta-de-pecado a porta tenda-de encontro a o-sacerdote');
INSERT INTO verses VALUES (3052, 3, 12, 7, 've-hikriv-o diante-de yhwh e-perdoar sobre-ela e-taharah mi-meqor דָּמֶ֑יהָ esta lei-de-a ha-yoledet la-zachar ou la-neqevah');
INSERT INTO verses VALUES (3053, 3, 12, 8, 'e-se não temtza yada-ah suficiente-de cordeiro ve-laqekhah duas-de rolas ou segundo um yonah um para-oferta ve-echad para-oferta-de-pecado e-fará-expiação em-a o-sacerdote ve-taherah');
INSERT INTO chapters VALUES (103, 3, 13, 59);
INSERT INTO verses VALUES (3054, 3, 13, 1, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (3055, 3, 13, 2, 'homem porque sera בְּעֹר־ seu-braço levou-a ou sua-ferida ou em-mistério e-acontecerá em-cara a-carne-dele para-aflição lepra e-o-levaram a Aarão não ou a um de-seus-construções aos-sacerdotes');
INSERT INTO verses VALUES (3056, 3, 13, 3, 'e-viu o-sacerdote a o-nega em-pele- o-carne revolver em-o-negue a-virou para-branco e-aparencia o-negue profundo de-pele em-carne-sua negue ele ele e-o-veio o-sacerdote ele a-ele');
INSERT INTO verses VALUES (3057, 3, 13, 4, 'e-se em-a-claridade ela ela-é em-ouro be-saro e-o-profundamente não-há a-sua-aparência de o-pele e-o-cabelo não virou-se Laban e-o-encerrou o-sacerdote a a-praga sete dias');
INSERT INTO verses VALUES (3058, 3, 13, 5, 'e-o-viu o-sacerdote no-dia o-sétimo e-eis a-praga ficou-em-pé em-seus-olhos não espalhou-se a-praga na-pele e-o-encerrou o-sacerdote sete dias segunda');
INSERT INTO verses VALUES (3059, 3, 13, 6, 'e-ele-viu o-sacerdote ele no-dia o-sétimo segunda-vez e-eis clara- a-praga e-não espalhou-se a-praga na-pele e-o-puregue o-sacerdote de-sangue ela e-lave-se as-suas-roupas e-ele-fique-puro');
INSERT INTO verses VALUES (3060, 3, 13, 7, 'e-se a fadiga será quebrantada a borda no fogo atrás-de e mostrá-lo a o-sacerdote para sua purificação e será visível segundo a o-sacerdote');
INSERT INTO verses VALUES (3061, 3, 13, 8, 'e verá o-sacerdote e-eis se espalhou a mancha no couro e tornou-se impuro o-sacerdote erupção ela');
INSERT INTO verses VALUES (3062, 3, 13, 9, 'praga zaraat que será em-a-carnagem e-o-foi-trazido a o-sacerdote');
INSERT INTO verses VALUES (3063, 3, 13, 10, 'e verá o-sacerdote e-eis saet- levana- ba''or e ela se virte sa''ar- Laban e mi''chayta- vida viveu ba''saet:');
INSERT INTO verses VALUES (3064, 3, 13, 11, 'lepra velha ela em-ouro em-carne-sua e-o-contaminar o-sacerdote não ele-o-encarcerará que impuro ele');
INSERT INTO verses VALUES (3065, 3, 13, 12, 'e-se borboleta florescerá a-lepra em-a-pele e-cobriu-a a-lepra a todo pele o-mal de-seu-cabeça os-olhos-de seus pés para-todo visão olhos de o-sacerdote');
INSERT INTO verses VALUES (3066, 3, 13, 13, 'e-viu o-sacerdote e-eis cobriu-a a-lepra a todo em-carne-sua e-purificou-o revolver o-mal tudo-seu ele Laban puro ela');
INSERT INTO verses VALUES (3067, 3, 13, 14, 'e no dia ser-visto nele carne vida se-tornar-imundo');
INSERT INTO verses VALUES (3068, 3, 13, 15, 'e-verá o-sacerdote a a-carne o-vivo e-o-tornará-imundo a-carne o-vivo ele ele ele ela');
INSERT INTO verses VALUES (3069, 3, 13, 16, 'ou porque virá o homem o-vivo e se converterá em branco e virá a o-sacerdote');
INSERT INTO verses VALUES (3070, 3, 13, 17, 'e-o-ve-rá-a-lo o-sacerdote e-eis se-tornar o-nega ללבן e-e-ti-har o-sacerdote a o-nega ele ela');
INSERT INTO verses VALUES (3071, 3, 13, 18, 'e-ba-sar porque será nele- na-seu-pele she-chin e-e-ni-rfa');
INSERT INTO verses VALUES (3072, 3, 13, 19, 'e-será em-o-lugar o-escurecido שאת para-a-branca ou na-montanha para-a-branca tornar-vermelho e-se-viu a o-sacerdote');
INSERT INTO verses VALUES (3073, 3, 13, 20, 'e-viu o-sacerdote e-eis a-aparição-dele abaixado de o-pele revolver virou Laban e-tim-o o-sacerdote ela tsara-at ela ba-schin para-ha');
INSERT INTO verses VALUES (3074, 3, 13, 21, 'e-se yire-nah o-sacerdote e-eis não-há nela se-ar la-van u-shfa-la e-in-nah de ha-oor e-ela clara-ou-brilhante e-o-cercou o-sacerdote sete dias');
INSERT INTO verses VALUES (3075, 3, 13, 22, 'e-se estendeu-se você-estenderá em-a-pele e-o-tornará-imundo ele ele ela e-la');
INSERT INTO verses VALUES (3076, 3, 13, 23, 'e-se abaixo-dela você-permanecerá não não estendeu-se-a queimou ela ela e-o-puregue o-sacerdote');
INSERT INTO verses VALUES (3077, 3, 13, 24, 'ou carne porque será em seu interior de uma lança fogo e seria de vida da lança em seu fígado Lebanah vermelha ou branca');
INSERT INTO verses VALUES (3078, 3, 13, 25, 'e-viu aquela הַכֹּהֵן e-eis seja-virado de-pelo lavan em-o-lar e-a-aparição-de-a profundo de o-pele ela ele em-o-banhado florescendo ele ele o-sacerdote toque ela e-la');
INSERT INTO verses VALUES (3079, 3, 13, 26, 'e-se verão o-sacerdote e-eis não-há em-o-lar cabelo-escuro branco-o e-baixa não-há de a-pele e-ela escura-a e-o-cercou o-sacerdote sete dias');
INSERT INTO verses VALUES (3080, 3, 13, 27, 'e-o-viu o-sacerdote no-dia o sétimo se estendeu-se-ele você-estenderá em-a-pele e-torne-se-impuro ele a-ele a-praga ela e-la');
INSERT INTO verses VALUES (3081, 3, 13, 28, 'e-se em-a-sua-baixo você-estará-parado o-branco não ela-se-espalhou na-pele e-ela a-mancha-clara ela o-soluço ela e-o-puregue o-sacerdote ela estrague-se-a a-mancha e-la');
INSERT INTO verses VALUES (3082, 3, 13, 29, 'e-homem ou mulher porque nele tocar toque-o na-cabeça ou no-bigode');
INSERT INTO verses VALUES (3083, 3, 13, 30, 'והיא ראתה o sacerdote a a-mancha e-eis de-seu-aparecer profundo de a-pele e-nele ca-pelo y-ruivo ele e-tornar-imundo a-ele-o ele o-sangue ele a-lepra ha-rosh ele o-vieiro ela');
INSERT INTO verses VALUES (3084, 3, 13, 31, 'e-quando ele-vera o sacerdote a praga o-sangue e-eis não-há a-aparência-dele profundo de a-pele e-pelo preto não-há nele e-encerrou o-sacerdote a flagelo o-decorrente sete dias');
INSERT INTO verses VALUES (3085, 3, 13, 32, 'והיא ראתה o-sacerdote a no-dia em-o-dia o-setimo e-eis não espalhou-se nele e-não foi em-ele pelo dourado e-a-aparência o-necrose não profundo de a-pele');
INSERT INTO verses VALUES (3086, 3, 13, 33, 'e-se-barbeará e-a não não barbeie e-entregue o-sacerdote a o-necrose sete dias segunda');
INSERT INTO verses VALUES (3087, 3, 13, 34, 'e-viu o-sacerdote a no-dia em-o-dia o-sétimo e-eis não espalhou-se a-pústula na-pele e-a-sua-aparência não-ela profunda ele a-pele e-pure-se ele o-sacerdote e-lavou-se as-suas-roupas e-pureu-se');
INSERT INTO verses VALUES (3088, 3, 13, 35, 'e-se espalhou se-estenderá o-exudado em-a-pele depois-de sua-purificação-.');
INSERT INTO verses VALUES (3089, 3, 13, 36, 'e-o-verá o-sacerdote e-eis se-estendeu o-exudado em-a-pele não deverá-examinar o-sacerdote para-a-cabeleira o-amarelo ele ela');
INSERT INTO verses VALUES (3090, 3, 13, 37, 'e-se nos seus olhos ficou-em-pé a ferida e a pele preta cresceu nele foi curado ele puro ele e purificado o-sacerdote');
INSERT INTO verses VALUES (3091, 3, 13, 38, 'e-homem ou mulher porque será em-pele- [לְבָנֹֽת]');
INSERT INTO verses VALUES (3092, 3, 13, 39, 'e-viu o-sacerdote e-eis em-pele- [בֶּהָרֹ֖ת] [כֵּה֣וֹת] [לְבָנֹ֑ת] [בֹּ֥הַק] ele ele פרח em-a-pele ele ela');
INSERT INTO verses VALUES (3093, 3, 13, 40, 'וְאִ֕ישׁ que ele-será-marcado sua-cabeça careca ele puro ele');
INSERT INTO verses VALUES (3094, 3, 13, 41, 'e se de-a-parte-de rosto-dele ele-será-marcado sua-cabeça gibe ele puro ele');
INSERT INTO verses VALUES (3095, 3, 13, 42, 'e-quando ser-á em-a-calvicia ou em-o-gibe praga לבן ele-será-escarlateado tzaraat ela ele em-o-sujo-dele ou com-a-sujeira-dele');
INSERT INTO verses VALUES (3096, 3, 13, 43, 'והיא ראתה ele o-sacerdote e-eis espírito- a-praga branca faz-se-terra em-o-sujo-dele ou com-a-sujeira-dele como-a-aparência pele pele carne');
INSERT INTO verses VALUES (3097, 3, 13, 44, 'homem-de ele ele ele ele impuro o-impurizar o-sacerdote em-a-sua-cabeça seu-mal');
INSERT INTO verses VALUES (3098, 3, 13, 45, 'e-o-leproso que nele-o o-mal em-seus-vestidos serão puros será será desfeito e-sobre de-sua-boca vira e-se-tornará-impuro chamaria será-dito');
INSERT INTO verses VALUES (3099, 3, 13, 46, 'todo os-dias que da-mancha nele ele-se-tornará-impuro ele ele בֶּדָ֣ד habitou de-fora para-o-acampamento de-sua-residência');
INSERT INTO verses VALUES (3100, 3, 13, 47, '[וְהַבֶּ֕גֶד] porque nele em-ele praga da-mancha em-um-vestuário de-lã ou em-um-vestuário pishˈtim');
INSERT INTO verses VALUES (3101, 3, 13, 48, 'ou bishˈti ou be-ˈerev la-pishˈtim ve-la-tsaˈmer ou be-ˈor ou em-todo pele ˈor');
INSERT INTO verses VALUES (3102, 3, 13, 49, 'e-será ha-neˈgaʿ ye-raq-raq ou a-da-mdam em-a-roupa ou em-a-pele ou na-segunda ou no-crepúsculo ou em-todo utensílio-de ele a-praga lepra ele e-ele-viu a o-sacerdote');
INSERT INTO verses VALUES (3103, 3, 13, 50, 'e-ela-viu o-sacerdote a a-praga e-eisgir a o-nega sete dias');
INSERT INTO verses VALUES (3104, 3, 13, 51, 'והיא ראתה a no-dia no-dia o-sétimo porque pasha o-nega em-o-beged ou em-sheti a-todo no-erev ou na-pelouse para-todo que será-feito o-pelouse ele tsaraat a-praga impuro ela');
INSERT INTO verses VALUES (3105, 3, 13, 52, 'וְשַׂרְף a הַבֶּגֶד ou a Eis ou a o pôr-do-sol em-coroa ou nas-fértices ou a nele instrumento a-cútis que ela em-ele o-tetraço porque lepra testemunho ele com-fogo ser-á-consumido');
INSERT INTO verses VALUES (3106, 3, 13, 53, 'e-se vir-ver o-sacerdote e-eis não pasa o nega'' no baged ou na basheti ou no avaré ou em-todo vida ouro:');
INSERT INTO verses VALUES (3107, 3, 13, 54, 'e tziva''ah o-sacerdote e kibso''u a que nele o nega'' e higsiro''oh sete- dias segunda');
INSERT INTO verses VALUES (3108, 3, 13, 55, 'וְרָאָ֨ה o sacerdote depois-de foi-afastado a a-pústula e-eis não tornou-se a-pústula a seu-olho e-a-pústula ele alargou-se estava-imundo ele ela seriam-queimados pechethet ele bekarachto ou begavachtov');
INSERT INTO verses VALUES (3109, 3, 13, 56, 've''im ver o-sacerdote e-eis kehah hannega atrás-de hukkavbes ele ve''kar''a ele de habged ou de ha''or ou de הַשְׁתִ֖י ou de הָעֵֽרֶב׃');
INSERT INTO verses VALUES (3110, 3, 13, 57, 'e-se [ע֜וֹד] ainda em-o-beged ou na-segunda ou no-crepúsculo ela em-todo utensílio- [OBJ] [אֲשֶׁר־בּ֖וֹ] ela a que nele');
INSERT INTO verses VALUES (3111, 3, 13, 58, '[וְהַבֶּ֡גֶד] ou [אוֹ־הָעֵ֜רֶב] ou [הָעוֹר֙] ou todo instrumento-de [מֵהֶ֖ם] que [וְכֻבַּ֥ס] וְסָ֥ר de-eles o-mal segundo e-taher');
INSERT INTO verses VALUES (3112, 3, 13, 59, 'esta lei: נֶֽגַע- lepra: roupa: o linho ou as peles ou e a seda: ou e o linho que foi feito em lençol: ou todo instrumento de couro: para ser purificado ou para se tornar impuro');
INSERT INTO chapters VALUES (104, 3, 14, 57);
INSERT INTO verses VALUES (3113, 3, 14, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3114, 3, 14, 2, 'esta será lei-de o leproso em-dia sua purificação e levado a o-sacerdote');
INSERT INTO verses VALUES (3115, 3, 14, 3, '[וְיָצָא֙] o-sacerdote a fora-de para-o-lager ve-ra''ah o-sacerdote e-eis foi-curado praga- de');
INSERT INTO verses VALUES (3116, 3, 14, 4, '[וְצִוָּה֙] o-sacerdote e-tome [לַמִּטַּהֵ֛ר] duas-de [חַיּ֖וֹת] [טְהֹר֑וֹת] [וְעֵ֣ץ] וְעֵ֣ץ erez [תוֹלַ֖עַת] [וְאֵזֹֽב]');
INSERT INTO verses VALUES (3117, 3, 14, 5, 'וְצִוָּה֙ o-sacerdote e sacrifique a a ave a-uma a vida cascalho sobre águas vivos');
INSERT INTO verses VALUES (3118, 3, 14, 6, 'a a ave a-vida ele pegue a-ela e-a árvore o cedro e-a segundo a traça e-a o carvalho e imerga a-eles e-את a ave a-vida sobre a-pá a-sacada sobre as-águas os-animais');
INSERT INTO verses VALUES (3119, 3, 14, 7, 'e-sacrificou sobre o-purificado de a-lepra sete vezes e-o-purificou e-enviou a a-pá o-animais sobre face-de o-campo');
INSERT INTO verses VALUES (3120, 3, 14, 8, 'e civeis o que purifica a em suas vestes וְגִלַּ֣ח a todo sua cabeça e lavar em água e purificar e-depois vira a o-acampamento e se assentará de-fora em sua tenda sete dias');
INSERT INTO verses VALUES (3121, 3, 14, 9, 'e-será no-dia o sétimo יְגַלַּ֣ח a todo seu-cabelo a sua-cabeça e-a sua-barba e-את suas-frontes seus-olhos e-a todo seu-cabelo cortará-lhe e-vestirá-o a E-disse e-lavará-o a seu-corpo nas-aguas e purifique;');
INSERT INTO verses VALUES (3122, 3, 14, 10, 'e-no-dia ha-shmini tomará dois cordeiros perfeitos uma uma filha-de sua perfeita e-três dez farinha-a oferta-cereais em-estado-de-mistura um e um azeite');
INSERT INTO verses VALUES (3123, 3, 14, 11, 'e estabelecerá o-sacerdote o que purificou a o-homem o purificado e-os diante-de yhwh entrada-de tenda-de encontro');
INSERT INTO verses VALUES (3124, 3, 14, 12, 'e-tome o sacerdote a o-primeiro o primeiro ele a-ele para-a-oferta-pelo-pequeno-erro e-a lho eles e-sacrou a-eles yhwh diante-de yhwh');
INSERT INTO verses VALUES (3125, 3, 14, 13, 'e-imolará a o cordeiro em lugar de que será sacrificado a o-pecado e-a que em-lugar-de a-santidade ele como expiação o pecador ele ele santidade-de santíssimos ela');
INSERT INTO verses VALUES (3126, 3, 14, 14, 'e-tome o sacerdote de-sangue-de o emasmo e deu o-sacerdote sobre tenuk a oézên o metáhêr a-direita sua-mão bohen mão-dele a-direita e-sobre bohen ragleo ha-yemanit');
INSERT INTO verses VALUES (3127, 3, 14, 15, 'e-tome o-sacerdote milog o shamen e yatsaq sobre palma o-sacerdote a shamáelite');
INSERT INTO verses VALUES (3128, 3, 14, 16, 'e taval o-sacerdote a seu-ó-lho a-direita de o-á-sa que sobre sua-mã-o a-esquer-da e-ele-aspergirá de o-á-sa yhwh sete yhwh diante-de yhwh');
INSERT INTO verses VALUES (3129, 3, 14, 17, 'e-resto o-á-sa que sobre sua-mã-o dará o-sacerdote sobre cheio ou-ço o-ma-tteh-her sua-mão e-sobre bo-hen mão-dele a-direita sobre bohen ragleo a-direita sobre a-ele ha-asham');
INSERT INTO verses VALUES (3130, 3, 14, 18, 've-ha-nothar be-shemen que sobre kef o-sacerdote dará sobre cabeça o-ma-tteh-her e-fará-expiação sobre-ele yhwh diante-de yhwh');
INSERT INTO verses VALUES (3131, 3, 14, 19, 've-asah o-sacerdote a a-oferta-pelo-pecado ve-kippar sobre o-ma-tteh-her מִטֻּמְאָת֑וֹ e-depois matará a a-elevação');
INSERT INTO verses VALUES (3132, 3, 14, 20, '[וְהֶעֱלָ֧ה] o-sacerdote a a queimada e-a a oferenda o altar-para e-fará-expiação sobre-ele o-sacerdote e-taher');
INSERT INTO verses VALUES (3133, 3, 14, 21, 'e-se ele ele sua-mão mão-sua e-tome e tomará um um imposto de balanço para expiação sobre-ele e oferta de farinha um um em-o-a-oleo de oferta e o azeite');
INSERT INTO verses VALUES (3134, 3, 14, 22, 'e-duas-de rolas ou segundo filhos-de Jonas que atingirá sua-mão e-era um chéttā''at e o único oferta holocausto;');
INSERT INTO verses VALUES (3135, 3, 14, 23, 'e-trará eles no-dia הַשְׁמִינִ֛י para a purificação dele a o-sacerdote a porta yhwh encontro diante-de yhwh');
INSERT INTO verses VALUES (3136, 3, 14, 24, 'e-tome o-sacerdote a sujeitai o reto e-a ele eles e levantou אֹתָ֧ם o-sacerdote yhwh diante-de yhwh');
INSERT INTO verses VALUES (3137, 3, 14, 25, 'e matou a sujeitai e-tome e tomou o-sacerdote de-sangue-de o sacrifício e deu sobre tubo o-relho- sua-mão a-direita e-sobre nele mão-dele a-direita e-sobre bohen ragleo ha-yemanit');
INSERT INTO verses VALUES (3138, 3, 14, 26, 'e-de o óleo e ungiu o-sacerdote sobre palma o-sacerdote a mão esquerda:');
INSERT INTO verses VALUES (3139, 3, 14, 27, 'e separou-o o-sacerdote no seu polegar a-direita de o óleo que sobre sua mão a esquerda sete yhwh diante-de yhwh');
INSERT INTO verses VALUES (3140, 3, 14, 28, 'e colocou-o o sacerdote de o óleo que sobre sua mão sobre preparado orelha o-ma-tteh-her sua-mão e-sobre bo-hen mão-dele a-direita e-sobre bohen ragleo a-direita sobre lugar-de a-ele ha-asham');
INSERT INTO verses VALUES (3141, 3, 14, 29, 've-ha-nothar de o-óleo que sobre כּף o-sacerdote yittein sobre cabeça o-ma-tteh-her yhwh sobre-ele diante-de yhwh');
INSERT INTO verses VALUES (3142, 3, 14, 30, 've-asah a o-um de ha-torim ou de filhos-de sua-mão do-que tasag יָדֽוֹ׃');
INSERT INTO verses VALUES (3143, 3, 14, 31, 'a que sua-mão mão-sua a ha-echad chéttā''at e-a hā''ēchād holocausto sobre a-oferenda e-cobrirá yhwh sobre o-mpurificado diante-de yhwh');
INSERT INTO verses VALUES (3144, 3, 14, 32, 'esta [תּוֹרַ֔ת] que nele praga lepra que sua-mão [בְּטָהֳרָתֽוֹ׃] mão-sua');
INSERT INTO verses VALUES (3145, 3, 14, 33, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (3146, 3, 14, 34, 'que tabō''u a terra Canaã que eu a-vós a-vós lā''ăchūzāh věnātātī נגע doença terra terra ăchūzatkēm');
INSERT INTO verses VALUES (3147, 3, 14, 35, 'e-ele-virá que a-ele a-casa e-h-i-g-u-r dizendo dizendo canegá apareceu a-mim na-casa');
INSERT INTO verses VALUES (3148, 3, 14, 36, 'e ordenou o-sacerdote e viram a a-casa antes-de virá para-ver para ver a a canega e-não ele-se-tornará-impuro todo que ba-bayit e depois para-ver virá o-sacerdote para-ver a a-casa');
INSERT INTO verses VALUES (3149, 3, 14, 37, 'e-viu a a-mancha e-eis a-praga [הַבַּ֔יִת] a-casa [יְרַקְרַקֹּ֔ת] [א֖וֹ] ou [וּמַרְאֵיהֶ֥ן] [שָׁפָ֖ל] baixo de');
INSERT INTO verses VALUES (3150, 3, 14, 38, 'וְיָצָ֧א o-sacerdote de a-casa a entrada-de a-casa e-eisgir a a-casa sete dias');
INSERT INTO verses VALUES (3151, 3, 14, 39, 'ושׁוב o-sacerdote no-dia o sétimo [וְרָאָ֕ה] e-eis se-estendeu a-praga em-o-lar a-casa');
INSERT INTO verses VALUES (3152, 3, 14, 40, '[וְצִוָּה֙] o-sacerdote e-saque-a a as pedras que nelas o-mal [אֶתְהֶן֙] as-elas a de-fora para-a-cidade a lugar');
INSERT INTO verses VALUES (3153, 3, 14, 41, 'e-a a-casa que sejam expostas do templo ao-redor e derramem a a poeira que hiktzu a de-fora para-a-cidade a lugar impuro:');
INSERT INTO verses VALUES (3154, 3, 14, 42, 'e tomaram pedras outras e trazem a em-lugar-de as-pedras e-pó outro יִקָּח e espalhou a a-casa');
INSERT INTO verses VALUES (3155, 3, 14, 43, 'e-se volte a mancha e se espalhou na-casa apos chiltz a as-pedras ve''acharei היקצוֹת a a-casa e-após-de hit''toch');
INSERT INTO verses VALUES (3156, 3, 14, 44, 'e-ele-virá o-sacerdote e verá e-eis pasa hannega ba-bayit tsara''at mamerset ela na-casa impuro ele');
INSERT INTO verses VALUES (3157, 3, 14, 45, 've''natz a a-casa a avanyo e-a seus árvores e-a todo o-pó a-casa e tirou a de-fora para-a-cidade a lugar impuro∶');
INSERT INTO verses VALUES (3158, 3, 14, 46, '[וְהַבָּא֙] a a-casa todo ele [יִטְמָ֖א] a-ela ele-se-tornará-impuro até no entardecer');
INSERT INTO verses VALUES (3159, 3, 14, 47, 'e o que estava deitado na-casa cobriria a com suas vestes e o que comeu na-casa cobriria a com suas vestes∶');
INSERT INTO verses VALUES (3160, 3, 14, 48, 'e-se veio [הַכֹּהֵ֗ן] o-sacerdote ve-ra''ah e-eis não espalhou-se a-praga na-casa atrás-de [וְטִהַ֤ר] a a-casa que o-sacerdote a a-casa porque');
INSERT INTO verses VALUES (3161, 3, 14, 49, 'e-tome לְחַטֹּא a a-casa duas צִפְרִים וְעֵץ erez וַשָּנִי toláat e eu azovei:');
INSERT INTO verses VALUES (3162, 3, 14, 50, 'e eu sacrifiquei: a a ave a-uma a vida cheres sobre águas vivos');
INSERT INTO verses VALUES (3163, 3, 14, 51, 'e-tome a árvore-de o cedro e-a a oliveira e-את o verme o verme e o a ave eles e imergi: os-los נֶפֶשׁ-הַחַיִים a ave a-vida וּבַמַּיִם נֶפֶשׁ-הַחַיִים e derramou a a-casa sete vezes');
INSERT INTO verses VALUES (3164, 3, 14, 52, '[וְחִטֵּ֣א] a a-casa [הַצִּפּ֔וֹר] [וּבַמַּ֖יִם] a-vida [וּבַצִּפֹּ֣ר] [הַחַיָּ֗ה] a vida e em madeira o cedro [וּבִשְׁנִ֥י] [הַתּוֹלָֽעַת]');
INSERT INTO verses VALUES (3165, 3, 14, 53, '[וְשִׁלַּ֞ח] a [הַֽחַיָּ֛ה] [אֶל־מִח֥וּץ] a de-fora la-ir a face-de o-campo e-fará-expiação sobre a-casa e-taher');
INSERT INTO verses VALUES (3166, 3, 14, 54, 'esta a-Torah para-todo negue [וְלַנָּֽתֶק]');
INSERT INTO verses VALUES (3167, 3, 14, 55, 'e a lepra o pano e o couro; versículo:');
INSERT INTO verses VALUES (3168, 3, 14, 56, 'e para a lepra e-para-a-safá e o linho; versículo:');
INSERT INTO verses VALUES (3169, 3, 14, 57, 'para ensinar em-dia o-imundo e-no-dia-de o que é purificado esta lei-de a lepra; versículo:');
INSERT INTO chapters VALUES (105, 3, 15, 33);
INSERT INTO verses VALUES (3170, 3, 15, 1, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (3171, 3, 15, 2, 'disseram a filhos-de Israel e-disseis a-eles homem que será yihye o zabe do-seu-braço de-sua-peneta ele ela');
INSERT INTO verses VALUES (3172, 3, 15, 3, 'e-isto será sua-impureza בְּזוֹב֑וֹ neve de-seu-braço a בְּזוֹב֑וֹ ou as-estrias em-seu-braço ela sujeito-sua e-la');
INSERT INTO verses VALUES (3173, 3, 15, 4, 'todo o-misbá que irá-cobrir sobre-ele o-zab irá-timá e-todo o utensílio que habitou sobre-ele irá-timá:');
INSERT INTO verses VALUES (3174, 3, 15, 5, 'e-um-homem que irá se deitar no-misbá-lo irá-cobrir-se em-suas-roupas e-lavará nas-aguas e-impuro até ha-arev:');
INSERT INTO verses VALUES (3175, 3, 15, 6, 'e-o-sentado sobre o utensílio que habitou sobre-ele o-zab suja-se em-suas-roupas e-lavará nas-aguas e-impuro até ha-arev:');
INSERT INTO verses VALUES (3176, 3, 15, 7, 'e-o-toque em-carne o-zab suja-se em-suas-roupas e-lavará nas-aguas e-impuro até a entardecer:');
INSERT INTO verses VALUES (3177, 3, 15, 8, 'e-quando verde o-zab em-puro e-vestiu-se seus-vestuários e-lavará nas-aguas e-impuro até a entardecer:');
INSERT INTO verses VALUES (3178, 3, 15, 9, 'e-todo o-carro que irá-sentar-se sobre-ele o-zab e-será-timpu');
INSERT INTO verses VALUES (3179, 3, 15, 10, 'e-todo o que toca em-todo será será sob ele ele-se-tornará-impuro até a-tarde e o que carrega a-eles sujará seus-vestuários e-lavará nas-aguas e-impuro até ha-arev:');
INSERT INTO verses VALUES (3180, 3, 15, 11, 'e-tudo que irá-se-unir nele o leproso e suas mãos não שָׁטַ֣ף nas-águas e sujará em suas vestes e-lavará nas-aguas e-impuro até ha-arev:');
INSERT INTO verses VALUES (3181, 3, 15, 12, 'e-vesselário- buraco que irá-se-unir nele o-zab que-se-partirá e-todo vida árvore irá-escovar-se com-a-água');
INSERT INTO verses VALUES (3182, 3, 15, 13, 'e-quando irá-se-purificar o-zab מִזְבֹּחֹו a-ele a-ele sete יָמִ֛ים para-sua-purificação e-secará nos-seus-vestuários e-lavará seu-carne vida vivos e-puro:');
INSERT INTO verses VALUES (3183, 3, 15, 14, 'e-no-dia ha-shmini יִקָּח־ a-ele duas torim ou segundo filhos-de yonah e-ele-veio diante-de yhwh a porta-de tenda encontro e-o-dar-lhes-ele a o-sacerdote');
INSERT INTO verses VALUES (3184, 3, 15, 15, 'e-fez eles o-sacerdote um pecado e o um holocausto e-fará-expiação sobre-ele o-sacerdote diante-de yhwh do-ofertório:');
INSERT INTO verses VALUES (3185, 3, 15, 16, 'e-um-homem porque nós dele deito-de- semente e-lavará no-agua a todo a-carne-dele e-impuro até ha-arev:');
INSERT INTO verses VALUES (3186, 3, 15, 17, 'e-todo roupa e-todo ouro que será sobre-ele deito-de- semente e coçará nas-aguas e-impuro até a entardecer:');
INSERT INTO verses VALUES (3187, 3, 15, 18, 'e mulher que irá deitar-se com homem a-ela deito-de- semente e lavarão nos-mã-ys e se tornarão impuros até a entardecer:');
INSERT INTO verses VALUES (3188, 3, 15, 19, 'e-mulher porque sera zabá será será sua zabá em seu corpo shib-aat dias será em-nidáh e-todo o-nogue nela ser-tame até ha-arev:');
INSERT INTO verses VALUES (3189, 3, 15, 20, 'e-tudo que dormir sobre-ele em-nidáh será contaminado e-tudo que habitar sobre-ele será contaminado');
INSERT INTO verses VALUES (3190, 3, 15, 21, 'e-todo o-nogue em-cama היה-כבוס -בגדיו e-lavará nas-aguas e-impuro até ha-arev:');
INSERT INTO verses VALUES (3191, 3, 15, 22, 'e-todo [בְּכָל־כְּלִ֖י] em-todo utensílio que [בְּגָדָ֛יו] sobre-ele [בַּמַּ֖יִם] suas vestes e-lavará nas-aguas e-o-contaminará até no entardecer');
INSERT INTO verses VALUES (3192, 3, 15, 23, 'e-se sobre ele ele ou sobre הכליה que זה -ישבطة sobre-ele em-se-negar- ele ele-se-tornará-impuro até ha-arev:');
INSERT INTO verses VALUES (3193, 3, 15, 24, 'e-se- escôb- irá-dormir- homem aquela וּתְהִ֤י ela-estiver-doente- sobre-ele e sujo sete dias e-todo o-leito- que irá-dormir- sobre-ele será-timido-');
INSERT INTO verses VALUES (3194, 3, 15, 25, 'e-a-mulher- porque יָזוּב ז֨וֹב דָּמָ֜הּ dias muitos בְּלֹא֙ עֶת־ niddatáh ou porque תָז֖וּב sobre niddatáh todo יְמֵ֞י ז֣וֹב ela כִּימֵ֧י niddatáh não a-vós e-la');
INSERT INTO verses VALUES (3195, 3, 15, 26, 'todo [אֲשֶׁר־תִּשְׁכַּ֤ב] que [כָּל־יְמֵ֣י] sobre-ele todo dias-de [יִֽהְיֶה־לָּ֑הּ] [וְכָֽל־הַכְּלִי֙] [אֲשֶׁ֣ר] ele-será- a-ela e-todo será que [נִדָּתָֽהּ] sobre-ele será');
INSERT INTO verses VALUES (3196, 3, 15, 27, 'e-todo o que tocou com-eles será imundo e lavará seus vestidos e-lavará nas-aguas e-impuro até a tarde׃');
INSERT INTO verses VALUES (3197, 3, 15, 28, 'וְאִֽם־ purificação mizbāḥā e a cobrirá a ela sete dias e-depois será purificada');
INSERT INTO verses VALUES (3198, 3, 15, 29, 'e-no-dia ha-shmini tomará a-ela duas torim ou segundo filhos-de yonah e traria-a elas a o-sacerdote a entrada-de tenda encontro');
INSERT INTO verses VALUES (3199, 3, 15, 30, 'e faria o-sacerdote a o primeiro pecado e-a הָאֶחָ֖ד holocausto e-fará-expiação עָלֶ֤יהָ yhwh diante-de yhwh mizbāḥā tumahtô:');
INSERT INTO verses VALUES (3200, 3, 15, 31, 'e santificardes a filhos-de Israel da sua impureza e-não morrerão por causa de sua impureza בְּטַמְּאָ֥ם a מִשְׁכָּנִ֖י que em-meio-de-eles');
INSERT INTO verses VALUES (3201, 3, 15, 32, 'esta lei-de [הַזָּ֑ב] e-que תֵצֵ֥א nós deito-de- זֶרַע le''tame''a- em-ela');
INSERT INTO verses VALUES (3202, 3, 15, 33, 'e a doxa בְּנִדָּתָ֔הּ וְהַזָּב֙ a זוֹב֔וֹ לַזָּכָ֖ר e na-fébe-a e para-êish que ishe-kab com temé-a');
INSERT INTO chapters VALUES (106, 3, 16, 34);
INSERT INTO verses VALUES (3203, 3, 16, 1, 'e-falou yhwh a Moisés morrendo morte segundo filhos-de Aarão [לִפְנֵי־יְהוָ֖ה] diante-de yhwh');
INSERT INTO verses VALUES (3204, 3, 16, 2, 'E-disse yhwh a Moisés palavra a Aarão aikhakhā e-a yabō'' em-todo ʿet a o-santuário מֵבֵית para-a-paróte a que a-cáforé que sobre o-arón e-não יָמוּט porque no-únan erei sobre a tampa');
INSERT INTO verses VALUES (3205, 3, 16, 3, 'nisto virá אַהֲרֹן a a-santidade no-par filho-de manhã para-pecado um para-holocausto');
INSERT INTO verses VALUES (3206, 3, 16, 4, 'cotonete- no-bad Sanctuary vestira e-calções-de linhas serão sozinho carne-seu e-com-cinto sozinho will gird with e-com-turbante eles יתnof garments of santo-de eles e-lavará in water a a-carne-dele e-vestira-os');
INSERT INTO verses VALUES (3207, 3, 16, 5, 'e-de assembleia de filhos-de Israel tomará dois o carneiro cabras para-oferta-de-pecado um um para-holocausto');
INSERT INTO verses VALUES (3208, 3, 16, 6, 'e oferecerá Aarao a touro-de do-pecado que a-ele e-fará-expiação atrás-dele e sobre casa-dele');
INSERT INTO verses VALUES (3209, 3, 16, 7, 'e-tome a segundo os carneiros eles eles yhwh yhwh entrada tenda encontro');
INSERT INTO verses VALUES (3210, 3, 16, 8, 'e deu-lhe Aarao sobre segundo os carneiros sortes um um a-yhwh um um para Azazel');
INSERT INTO verses VALUES (3211, 3, 16, 9, 'e-oferecerá Arão a o-bode subir subiu sobre-ele a sorte a-yhwh e o fará חַטָּֽאת׃');
INSERT INTO verses VALUES (3212, 3, 16, 10, 'e o carneiro que subir sobre-o o sorteio para Azazel estará viveu yhwh yhwh para expiar sobre-ele ele a-ele para Azazel no deserto:');
INSERT INTO verses VALUES (3213, 3, 16, 11, 'e trouxe-próximo Arão a touro a-oferta-pelo-pecado que a-ele e-fará-expiação por ele e atrás-de casa-dele e-degolará a touro-de o pecado que a-ele');
INSERT INTO verses VALUES (3214, 3, 16, 12, 'e-tome מְלֹא- a-machta de-cima-de eish de-sobre yhwh de-diante-de yhwh u-meloa chapnia ketoret סַמִּ֖ים dakha ve-habei de-casa-de la-parokhet');
INSERT INTO verses VALUES (3215, 3, 16, 13, 've-natan a a incenso sobre yhwh diante-de yhwh e a cobertura nuvem a incenso a o cipreste que sobre a testemunha e-não não');
INSERT INTO verses VALUES (3216, 3, 16, 14, 'e-tome de-sangue-de o touro e ele o esmagou em sua testa sobre face-de o cipreste קדמה velifnei הכפרת יחזה sete- רגעים de o-sangue באצבעיו:');
INSERT INTO verses VALUES (3217, 3, 16, 15, 'e sacrifique a a-besta-caprina a-oferta-pelo-pecado que para-o-povo והביא a דםיו a מֵבֵית לפרוכת e-fará a דםו como-que ele para o sangue o carneiro e espargiu a-ele sobre a propiciação yhwh a propiciação');
INSERT INTO verses VALUES (3218, 3, 16, 16, 'e-perdoar sobre o santuário dos impuros filhos-de Israel e dos seus pecados para-todo seus pecados e também fará para-tenda-de encontro no-meio-de com-elas-os no-meio-de טֻמְאֹתָֽם׃');
INSERT INTO verses VALUES (3219, 3, 16, 17, 'e-todo homem não [בְּאֹ֣הֶל] em-tenda-de מוֹעֵ֗ד [לְכַפֵּ֥ר] para-expiar ao-sanctuário até [בַּעֲדוֹ֙] ve-chipp-er [בֵּית֔וֹ] e atrás-de casa-dele וּבְעַ֖ד todo assembleia Israel');
INSERT INTO verses VALUES (3220, 3, 16, 18, 'וְיָצָ֗א a o-altar que diante-de yhwh e-tome sobre-ele וְלָקַ֞ח de-sangue o-touro וּמִדַּ֣ם o-bode e deu sobre carnot ele ao-redor');
INSERT INTO verses VALUES (3221, 3, 16, 19, 'e-ele-aspergirá sobre-ele de o-sangue be''etsba''u sete vezes ve''thiro ve''kidsho mitumot filhos-de Israel');
INSERT INTO verses VALUES (3222, 3, 16, 20, 'e cilláh mikappar a o-santuário e-a tenda encontro e-a o-altar ve''hikriv a hasa''ir o-vivo:');
INSERT INTO verses VALUES (3223, 3, 16, 21, 'vesamak Arão a duas sobre sobre o carneiro a vida e confessar-se-á sobre-ele a todo os pecados filhos-de Israel e-a todo eles para-todo seus pecados ve-natan eles sobre cabeça o-bode וְשִׁלַּ֛ח por-mão-de homem a sua hora o deserto');
INSERT INTO verses VALUES (3224, 3, 16, 22, 'e levantará o carneiro sobre-ele a todo suas-iniquidades a terra a-sentença e-ele-mandará a o-velho no-deserto');
INSERT INTO verses VALUES (3225, 3, 16, 23, 'e vindo Arão a tenda encontro e-despirá a em-suas-vestes a-ceragem que vestiu-o em-vir-seu a a-santidade e-deixou-os-lá nome');
INSERT INTO verses VALUES (3226, 3, 16, 24, 'e-lixou-o a em-suas-carne nos-mãos-d''água em-o-loco santo e-vestirá a em-suas-roupas e-saiu e-fez a sua-oferta e-a holocausto-de o-povo e-fará-expiação atrás-dele e-para o-povo');
INSERT INTO verses VALUES (3227, 3, 16, 25, 'e-a gordura a penitência imolou o-altar-para');
INSERT INTO verses VALUES (3228, 3, 16, 26, 'e-enviou a o-velho para-a-cabeça-do-deserto הכֶּסֶף as-roupas-seu e-lavará a a-carne-dele nas-águas e-depois-de assim virá a o-acampamento');
INSERT INTO verses VALUES (3229, 3, 16, 27, 'e-את פָּר a penitência e-את um-sair do-pecado que הֻבָּא a דָּמַם para expiar בַּקֹּדֶשׁ יָצִיא a de-fora para-o-lager וְשַׂרְפוּ בָּאֵשׁ a os seus ouros e-a seus ossos e-a suas peles');
INSERT INTO verses VALUES (3230, 3, 16, 28, 'e aquele que arde eles queimará as-roupas-seu e-lavará a a-carne-dele nas-águas e-depois-de assim virá a o-acampamento');
INSERT INTO verses VALUES (3231, 3, 16, 29, 'e-será a-vós לְחֻקָּה eternidade no-mês do sétimo no décimo no mês vocês se purifiquem a nafshoteichem não trabalho não fareis ha''ezrach e-o-estrangeiro eternidade no-vosso-médio');
INSERT INTO verses VALUES (3232, 3, 16, 30, 'porque bayom este yikappar sobre-vós letaher de-toda de-todo os-vossos-pecados yhwh yhwh titaharu');
INSERT INTO verses VALUES (3233, 3, 16, 31, 'shabbat shabbon ela a-vós ve''innitem a נַפְשֹׁתֵיכֶ֑ם eternidade eternidade');
INSERT INTO verses VALUES (3234, 3, 16, 32, 'e-fará-expiação o sacerdote que ele a-ele e-que que sejam cheios a debaixo seu-pai em-lugar-de pai-seu e vestam-se a de-roupas a separação de-roupas o-santuário');
INSERT INTO verses VALUES (3235, 3, 16, 33, 'e expiará a santuário o-santuário e-a tenda encontro e-a o-altar expiará e-sobre hakohanim e-sobre todo povo a-congregação expiará;');
INSERT INTO verses VALUES (3236, 3, 16, 34, 'e será a-vós para-vocês eternidade para sempre para expiar sobre filhos-de uma de-todo seu pecado uma no ano yhwh como ordenou yhwh a Moisés');
INSERT INTO chapters VALUES (107, 3, 17, 16);
INSERT INTO verses VALUES (3237, 3, 17, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3238, 3, 17, 2, 'palavra a Arão e-para filhos-seus e-a todo filhos-de Israel e-dirás a-eles yhwh dizendo que ordenou yhwh para-dizer');
INSERT INTO verses VALUES (3239, 3, 17, 3, 'homem homem de-casa-de Israel que será sacrificado boi ou gados ou cabra na-campanha ou que ser sacrificado ele o-lager');
INSERT INTO verses VALUES (3240, 3, 17, 4, 'e-a entrada-de tenda não não e trouxeram-no para oferecer oferta a-yhwh diante-de yhwh yhwh sangue será contado para o homem o-aquele sangue que derramou e foi cortado o-homem aquele de-meio-de seu-povo');
INSERT INTO verses VALUES (3241, 3, 17, 5, 'a-fim-de que trarão filhos-de Israel a seus sacrifícios eles eles זֹבְחִים sobre face-de do campo e trarão-os a-yhwh a entrada-de tenda-de encontro a o-sacerdote e sacrificaram זֹבְחִים שְׁלָמִים a-yhwh a-eles');
INSERT INTO verses VALUES (3242, 3, 17, 6, 'וְזָרַ֨ק o-sacerdote a ha-dam yhwh altar-de yhwh entrada-de tenda de-encontro e fez-fumaça a-gordura para-aroma tranquilidade para-יהוה');
INSERT INTO verses VALUES (3243, 3, 17, 7, 'e-não יִזְבְּח֥וּ ainda a זִבְחֵיהֶ֔ם eles que eles זֹנִ֖ים eternidade chuq-at a-eles será- esta a-eles para-gerações-eles');
INSERT INTO verses VALUES (3244, 3, 17, 8, 'e-lhes תֹּאמַ֔ר homem homem de-casa-de Israel e-de הַגֵּ֖ר que dormir בְּתוֹכָ֑ם que subia holocausto ou זָֽבַח׃');
INSERT INTO verses VALUES (3245, 3, 17, 9, 'e-a entrada-de tenda-de não não ele-o-traga ele ele a-yhwh e será cortado o-homem o-aquele de seu povo:');
INSERT INTO verses VALUES (3246, 3, 17, 10, 'e-homem homem de-casa-de Israel e-de o estrangeiro o estrangeiro entre vós que אכל todo דָּ֑ם e-darei face-de na alma que come a o-sangue e eu o cortarei a-ela de-meio-de a-sua-pena;');
INSERT INTO verses VALUES (3247, 3, 17, 11, 'que alma a-carne-o בַּדָּ֣ם ela e-eu eu o derreterei a-vós sobre o altar para expiar sobre ele porque o-dam ele b-nefesh yikappêr');
INSERT INTO verses VALUES (3248, 3, 17, 12, 'sobre assim dissesse aos-filhos-de Israel todo alma mikkem não ta''achal דָּ֑ם e o ger הַגָּ֥ Be-tochchem não o-dia dam');
INSERT INTO verses VALUES (3249, 3, 17, 13, 'e-homem homem de-filhos-de Israel e-de e o ger e o ger b-tokham que יָצַד vivente חַיָּה ou ave que ser-comes וְשָׁפַךְ a דָּם וְכִסֵּהוּ בֶּעָפָֽר׃');
INSERT INTO verses VALUES (3250, 3, 17, 14, 'porque alma todo carne ele em-seu-próprio-alma הוּא e eu disse aos-filhos-de Israel não todo que não comereis porque ela todo carne sangue-seu ele todo אֹכְלוֹ eternidade');
INSERT INTO verses VALUES (3251, 3, 17, 15, 'e-todo alma comerás תֵּאכֶל carcaça וּטְרֵפָה no azará e no ger e enxaguou suas vestes e-lavará nos maimim e-impuro até a-noite e purificar:');
INSERT INTO verses VALUES (3252, 3, 17, 16, 'וְאִם֙ não יְכַבֵּ֔ס e na sará-o não será lavado e levante-se iniquidade-sua');
INSERT INTO chapters VALUES (108, 3, 18, 30);
INSERT INTO verses VALUES (3253, 3, 18, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3254, 3, 18, 2, 'palavra a filhos-de Israel e-dirás a-eles yhwh yhwh');
INSERT INTO verses VALUES (3255, 3, 18, 3, 'como fez terra-de Egito que não nela não fareis e como fez terra-de como Canaã que eu-sou não a-vocês lá-baixo não fareis e em suas leis não andareis');
INSERT INTO verses VALUES (3256, 3, 18, 4, 'a מִשְׁפָּטַ֧י fazei e-a minhas leis guardareis para-andar yhwh eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (3257, 3, 18, 5, 'e guardareis a חֻקּוֹתַי e-a מִשְׁפָּטַי eles o-homem e-viva o-homem וָחַי yhwh eu yhwh');
INSERT INTO verses VALUES (3258, 3, 18, 6, 'homem homem a todo não em-carne-sua não תִּקְרְב֖וּ לְגַלּוֹת yhwh eu yhwh');
INSERT INTO verses VALUES (3259, 3, 18, 7, 'nudez-de seu-pai וְעֶרְוַת אִמְּךָ não תְגַלּוּ אִמְּךָ ela não revele seu despojo;');
INSERT INTO verses VALUES (3260, 3, 18, 8, 'nudez-de esposa-de não não revele nudez-de ela e-la');
INSERT INTO verses VALUES (3261, 3, 18, 9, 'despojo de sua irmã; filha-de teu-pai ou filha-de a-teua-mãe מולדת casa ou não ח֑וּץ não que seus despojos;');
INSERT INTO verses VALUES (3262, 3, 18, 10, 'despojo de filha-de filho-te ou não sua filha; não que suas-vergonha porque vergonha-teu até-aqui');
INSERT INTO verses VALUES (3263, 3, 18, 11, 'vergonha filha-de mulher-de teu-pai gerada pai-teu ela não não תְגַלֶּ֖ה vergonha-ela:');
INSERT INTO verses VALUES (3264, 3, 18, 12, 'nudez-de irmã- não não תְגַלֶּ֖ה resto ela e-la');
INSERT INTO verses VALUES (3265, 3, 18, 13, 'nudez-de irmã- não não revela porque ela não e-la');
INSERT INTO verses VALUES (3266, 3, 18, 14, 'nudez-de meu-irmão- não não revela não sua-mulher não ela tua-tia- e-la');
INSERT INTO verses VALUES (3267, 3, 18, 15, 'nudez-de kortakhak não revela mulher filho-te ela não revela seu-escândalo:');
INSERT INTO verses VALUES (3268, 3, 18, 16, 'nudez-de esposa-de não não [עֶרְוַ֥ת] nudez-de ela');
INSERT INTO verses VALUES (3269, 3, 18, 17, 'nudez-de mulher [וּבִתָּ֖הּ] não [תְגַלֵּ֑ה] a filha-de não e-[OBJ] filha-de [עֶרְוָתָ֔הּ] não [הֵ֖נָּה] [זִמָּ֥ה] ela');
INSERT INTO verses VALUES (3270, 3, 18, 18, 'וְאִשָׁ֥ה a não não תִקָּ֑ח para aprisionar para revelar seu desonro sobre-ela em sua vida:');
INSERT INTO verses VALUES (3271, 3, 18, 19, 'e-a mulher por seu fluxo não não תִקְרַ֔ב para revelar seu desonro:');
INSERT INTO verses VALUES (3272, 3, 18, 20, 'e-a esht teu companheiro: não תתן deitaste-te com para semear para sujar em-ela');
INSERT INTO verses VALUES (3273, 3, 18, 21, 'e de tua semente não dará para passar para o rei e-não תְחַלֵּל a nome yhwh eu yhwh');
INSERT INTO verses VALUES (3274, 3, 18, 22, 'e- não não dormirás de leitos mulher ela e-la');
INSERT INTO verses VALUES (3275, 3, 18, 23, 'e-em-todo animal não תתן dormiste para sujar nela e-mulher não תַעֲמֹ֞ד ele animal לְרִבְעָ֖הּ תֶּ֥בֶל ela');
INSERT INTO verses VALUES (3276, 3, 18, 24, 'a [בְּכָל־אֵ֑לֶּה] que estes porque em-todo estes [מְשַׁלֵּ֖חַ] as-nações que');
INSERT INTO verses VALUES (3277, 3, 18, 25, '[וַתִּטְמָ֣א] a-terra [וָאֶפְקֹ֥ד] [עֲוֺנָ֖הּ] sobre-ela [וַתָּקִ֥א] a-terra a');
INSERT INTO verses VALUES (3278, 3, 18, 26, 'e-guardareis vocês a חֻקֹּתַי֙ e-a מִשְׁפָּטַ֔י de-toda fareis de-todo הַתּוֹעֵבֹ֖ת estes הָֽאֶזְרָ֔ח e-o-estrangeiro eternidade no-vosso-médio');
INSERT INTO verses VALUES (3279, 3, 18, 27, 'que a todo הַתּוֹעֵבֹ֣ת o-Elohim fizeram os-homens-de- a-terra a-terra yhwh e se sujou a-terra');
INSERT INTO verses VALUES (3280, 3, 18, 28, 'e-não a-terra a-terra vos בְּטַֽמַּאֲכֶ֖ם a-ela como קָאָ֛ה a o-povo que לִפְנֵיכֶֽם׃');
INSERT INTO verses VALUES (3281, 3, 18, 29, 'que todo que de-toda de-todo as toevot estas וְנִכְרְת֛וּ as-nepashot ha-oshot de-meio-de amam');
INSERT INTO verses VALUES (3282, 3, 18, 30, 'e-guardareis a para-não לְבִלְתִּ֨י asahot me-chukot as coisas abomináveis que naasu diante-de-vós e-não ti-tammuo com-eles yhwh yhwh Elohim-vosso');
INSERT INTO chapters VALUES (109, 3, 19, 37);
INSERT INTO verses VALUES (3283, 3, 19, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3284, 3, 19, 2, 'palavra a todo congregação-de filhos-de Israel [תִּהְי֑וּ] que [קָד֔וֹשׁ] [אֲנִ֖י] yhwh santo yhwh');
INSERT INTO verses VALUES (3285, 3, 19, 3, 'homem sua-mãe [וְאָבִיו֙] [תִּירָ֔אוּ] e-[OBJ] [תִּשְׁמֹ֑רוּ] [אֲנִ֖י] yhwh yhwh');
INSERT INTO verses VALUES (3286, 3, 19, 4, 'a [אֶל־הָ֣אֱלִילִ֔ים] a [מַסֵּכָ֔ה] não [תַעֲשׂ֖וּ] a-vós [אֲנִ֖י] yhwh eu yhwh');
INSERT INTO verses VALUES (3287, 3, 19, 5, 'e-que [תִזְבְּח֛וּ] sacrifício paz a-yhwh [לִֽרְצֹנְכֶ֖ם] [תִּזְבָּחֻֽהוּ]');
INSERT INTO verses VALUES (3288, 3, 19, 6, 'no-dia vossos-pecados-sejam-ofertados será-ingerido e-na-mañhã e-o-restante até dia o-terceiro com-fogo será-queimado');
INSERT INTO verses VALUES (3289, 3, 19, 7, 'e-se היאכל será-ingerido no-dia o terceiro impuro ele não o-aceite-se');
INSERT INTO verses VALUES (3290, 3, 19, 8, 'e-os-comedores seu-pecado יִשָׂא porque yhwh santidade-de yhwh חִלֵּל aquela a-alma aquela de-a-tribos');
INSERT INTO verses VALUES (3291, 3, 19, 9, '[וּֽבְקֻצְרְכֶם֙] a [אַרְצְכֶ֔ם] não não [פְּאַ֥ת] [שָׂדְךָ֖] [לִקְצֹ֑ר] [וְלֶ֥קֶט] [קְצִֽירְךָ֖] não não');
INSERT INTO verses VALUES (3292, 3, 19, 10, 'e o teu jardim não serás consumido e a tua videira o teu jardim não serás arrebatado o pobre e ao estrangeiro תַּעֲזֹ֣ב eles eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (3293, 3, 19, 11, 'não serás roubado e-não serás mudo e-não serás enganado homem em seu amito');
INSERT INTO verses VALUES (3294, 3, 19, 12, 'e-não vocês jurareis em meu nome para mentira e profanareis a nome yhwh eu yhwh');
INSERT INTO verses VALUES (3295, 3, 19, 13, 'não תַעֲשׁוּק a seu reac e-não enganareis não falsificar-vos-ai obra סוכיר contigo até manhã');
INSERT INTO verses VALUES (3296, 3, 19, 14, 'não תקלל surdo velifnei não não dará מיכשול ויראת מאלהיך yhwh yhwh');
INSERT INTO verses VALUES (3297, 3, 19, 15, 'não [עָ֙וֶל֙] [בַּמִּשְׁפָּ֔ט] [לֹא־תִשָּׂ֣א] não [וְלֹ֥א] [תֶהְדַּ֖ר] face-de e-não [בְּצֶ֖דֶק] face-de grande');
INSERT INTO verses VALUES (3298, 3, 19, 16, 'não [רָכִיל֙] [בְּעַמֶּ֔יךָ] não não [עַל־דַּ֣ם] sobre sangue yhwh yhwh');
INSERT INTO verses VALUES (3299, 3, 19, 17, 'não תִּשָׂנָא a irmão-teu bilbavekha הוֹכֵ֤חַ תּוֹכִ֙יחַ֙ a עֲמִיתֶךָ e-não Tisa sobre-ele erro;');
INSERT INTO verses VALUES (3300, 3, 19, 18, 'não vindicação e-não voar a filhos-de seu povo e amaste yhwh como tu eu yhwh');
INSERT INTO verses VALUES (3301, 3, 19, 19, 'a מִצְוֹתַי guardareis em tua besta não quadrilhar duas vezes seu campo. não tizra'' כִּלְאָ֑יִם כלאים não subia sha''atnez não subia sobre-te');
INSERT INTO verses VALUES (3302, 3, 19, 20, 've''ish porque יִשַּׂכֵּב a mulher deito-de- semente ve''hu'' shifchah não para-homem ve''hefdeh não não ou chuphshah não não a-ela בִּקֹּ֧רֶת תִּהְיֶ֛ה não יוּמְת֖וּ porque não חֻפָּֽשׁׁה׃');
INSERT INTO verses VALUES (3303, 3, 19, 21, 'e-ele-trouxe a ashamó a-yhwh a entrada tenda reunião touro -Assom-');
INSERT INTO verses VALUES (3304, 3, 19, 22, 'e-perdoaria sobre-ele o-sacerdote בְּאֵ֤יל הָֽאָשָׁם֙ diante-de yhwh sobre pecado-dele que pecou a-ele a-ele de-sua-iniquidade que pecou');
INSERT INTO verses VALUES (3305, 3, 19, 23, '[וְכִי־תָבֹ֣אוּ] [אֶל־הָאָ֗רֶץ] a a-terra alimento todo madeira-de [אֶת־פִּרְי֑וֹ] [שָׁלֹ֣שׁ] [שָׁנִ֗ים] será a-vós três não será não');
INSERT INTO verses VALUES (3306, 3, 19, 24, '[וּבַשָּׁנָה֙] [הָרְבִיעִ֔ת] será todo [קֹ֥דֶשׁ] santidade-de [לַיהוָֽה]');
INSERT INTO verses VALUES (3307, 3, 19, 25, 'e-no-ano a quinta comam-vós a פרייו a-vós para-vocês תבואתו yhwh yhwh Elohim-vosso');
INSERT INTO verses VALUES (3308, 3, 19, 26, 'não comereis sobre não não [וְלֹ֥א] e-não');
INSERT INTO verses VALUES (3309, 3, 19, 27, 'não ataquem fim vossas cabeças e-não destruíais a fim seu-pêlo-branco:');
INSERT INTO verses VALUES (3310, 3, 19, 28, 'e vermes na alma não vós derramastes em vossos corpos e escreveste que aqua não dei-vos בָּכֶ֑ם eu yhwh');
INSERT INTO verses VALUES (3311, 3, 19, 29, 'a desvirtuaste a seu filho a-terra e-não a-terra a-terra e preencheveste a-terra ziná:');
INSERT INTO verses VALUES (3312, 3, 19, 30, 'a minhas sábias guardai-as e o meu santuário תיראוּ yhwh yhwh');
INSERT INTO verses VALUES (3313, 3, 19, 31, 'a voltais-vos a הָאֹבֹת֙ e-a os entendidos a yhwh לְטָמְאָ֣ה bahêm eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (3314, 3, 19, 32, 'de-diante-de שֵׂיבָה֙ תָּק֔וּם וְהָדַרְתָּ֖ face-de até-o-vieiro e temerás מֵּאֱלֹהֶ֖יךָ eu yhwh');
INSERT INTO verses VALUES (3315, 3, 19, 33, 'e-quando [אִתְּךָ֛] [גֵּ֖ר] [בְּאַרְצְכֶ֑ם] não não ele');
INSERT INTO verses VALUES (3316, 3, 19, 34, 'כְּאֶזְרָ֣ח מִכֶּם֩ será a-vós הַגֵּ֣ר ׀ הַגָּ֣ר אִתְּכֶ֗ם e amarás a-ele a-ele porque גרים fostes em-terra-de Egito eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (3317, 3, 19, 35, 'não [עָ֖וֶל] [בַּמִּשְׁפָּ֑ט] [בַּמִּדָּ֕ה] [בַּמִּשְׁקָ֖ל] [וּבַמְּשׂוּרָֽה]');
INSERT INTO verses VALUES (3318, 3, 19, 36, 'mazéni justica pedras-de tsedéq eífat tsedéq וְהִ֥ין será a-vós a-vós yhwh yhwh Elohim-de-vos que הוֹצֵ֥אתִי vos dizendo Egito');
INSERT INTO verses VALUES (3319, 3, 19, 37, 'e guardareis a todo chúqotáyi eles todo yhwh e-fizerdes a-eles eu yhwh');
INSERT INTO chapters VALUES (110, 3, 20, 27);
INSERT INTO verses VALUES (3320, 3, 20, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3321, 3, 20, 2, 'e-a filhos-de Israel dizei homem homem de filhos Israel e-de ha''ger o estrangeiro b-y-i-s-r-a-e-l que dê mi''zera''o morrendo morte-de morrerá a-terra a-terra irágemú ba''avon');
INSERT INTO verses VALUES (3322, 3, 20, 3, 'e-eu darei a face-de האישׁ aquele ele ele de-meio-de que porque dar deu para o-monoque para-que tame-a a מִקְדָּשִׁ֔י e-lhe-chalel a nome minha-santa-lócus');
INSERT INTO verses VALUES (3323, 3, 20, 4, 'e-se o apagarem ensiná-los povo a-terra a seus olhos de o-homem aquele em sua mão para-não ao rei ele המית ele');
INSERT INTO verses VALUES (3324, 3, 20, 5, 'e colocarei eu a face-de -no homem o-aquele em sua família ele a ele e-את todo as adúlteras após-ele para se desvendar atrás-de o-monoque de-meio-de povo-');
INSERT INTO verses VALUES (3325, 3, 20, 6, 'e-a-alma que vir-te-vire a הָאֹבֹת֙ e-a os entendidos para se desvendar apos-eles e-darei aquela face-de ele aquele וְהִכְרַתִּ֥י a-ele de-meio-de seu-povo');
INSERT INTO verses VALUES (3326, 3, 20, 7, 'e-voc-es-vos-santificai-vos e-sereis santos que eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (3327, 3, 20, 8, 'e-guardardes a chukkay eles a-eles yhwh yhwh que santificam-vos:');
INSERT INTO verses VALUES (3328, 3, 20, 9, 'porque homem homem que maldigá-lo a morrendo e-a seu-pai morte-de morrerá seu pai e sua mãe que seja maldito seus-dutos em-ele');
INSERT INTO verses VALUES (3329, 3, 20, 10, 'e-homem que forneça a mulher-de homem que forneça a mulher-de companheiro-seu morte de será morta הַנֹּאֵ֖ף וְהַנֹּאָֽפֶת׃');
INSERT INTO verses VALUES (3330, 3, 20, 11, 'e-homem que [יִשְׁכַּב֙] a seu-pai pai-dele seu-pai pai-dele [מֽוֹת־יוּמְת֥וּ] [שְׁנֵיהֶ֖ם] [דְּמֵיהֶ֥ם] dois-deles');
INSERT INTO verses VALUES (3331, 3, 20, 12, 'e-homem que יִשְׁכַּב֙ a morrendo morrer serão mortos dois-deles תֶּ֥בֶל fizeram דּ-מֵי-הֶ em-eles');
INSERT INTO verses VALUES (3332, 3, 20, 13, 'e-homem que dormirá a macho מִשׁ-כּוֹבֵ- mulher תּוֹעֵבָה fizeram morrendo morrer יֻמָ-תּוּ דּ-מֵי-הֶ em-eles');
INSERT INTO verses VALUES (3333, 3, 20, 14, 'e-homem que ele-tomará a mulher e-[OBJ] ela [בָּאֵ֞שׁ] ela ele [וְאֶתְהֶ֔ן] ele [זִמָּ֖ה] e-não');
INSERT INTO verses VALUES (3334, 3, 20, 15, 'e-homem que dê שְׁכָבְתּ֛וֹ בִּבְהֵמָ֖ה morrendo morrerá e-a o-animal תַּהֲרֹֽגוּ׃');
INSERT INTO verses VALUES (3335, 3, 20, 16, 'e-mulher que תִּקְרַ֤ב a todo animal para a quarta a-ela וְהָרַגְתָּ֥ morrendo a-mulher e-a הַבְּהֵמָ֑ה morrer יוּמָ֖תוּ דְּמֵיהֶ֥ם em-eles');
INSERT INTO verses VALUES (3336, 3, 20, 17, 'e-homem que [אֶת־אֲחֹת֡וֹ] a [א֣וֹ] filha-de [וְרָאָ֨ה] ou [וְהִֽיא־תִרְאֶ֤ה] [אֶת־עֶרְוָתוֹ֙] [חֶ֣סֶד] ele [וְנִ֨כְרְת֔וּ] [לְעֵינֵ֖י] [בְּנֵ֣י] a [עֶרְוַ֧ת] [אֲחֹת֛וֹ] ele [עֲוֺנ֥וֹ] aos-olhos-de filhos-de');
INSERT INTO verses VALUES (3337, 3, 20, 18, '[וְ֠אִישׁ] que [אֶת־אִשָּׁ֜ה] a mulher [אֶת־עֶרְוָתָהּ֙] [אֶת־מְקֹרָ֣הּ] a [וְהִ֕יא] a [אֶת־מְק֣וֹר] [דָּמֶ֑יהָ] [וְנִכְרְת֥וּ] [שְׁנֵיהֶ֖ם] a [עַמָּֽם]');
INSERT INTO verses VALUES (3338, 3, 20, 19, 'וְעֶרְוַ֨ת irmã אִמְּךָ֛ e irmã-de teu-pai não תְגַלֵּ֑ה que a שְׁאֵר֛וֹ הֶעֱרָ֖ה עֲוֺנָ֥ם carregarao');
INSERT INTO verses VALUES (3339, 3, 20, 20, 'e-homem que יִשְׁכַּב֙ a [עֶרְוַ֥ת] nudez-de דּוֹ gilá chetáam yissaú arírim morrerão:');
INSERT INTO verses VALUES (3340, 3, 20, 21, 'e-homem que yikkach a mulher-de irmão-seu ela ela nudez-de áhiy gilá arírim ser-ão');
INSERT INTO verses VALUES (3341, 3, 20, 22, 'e guardareis a todo chukkotay eles todo מִשְׁפָּטַי a-terra a-eles e-não תָקִ֤יא vos a-terra que eu multiplicarei a-vós para lá para-habitar nela');
INSERT INTO verses VALUES (3342, 3, 20, 23, 'e-não [תֵֽלְכוּ֙] [בְּחֻקֹּ֣ת] a-nação que eu [מִפְּנֵיכֶ֑ם] que porque a todo estes');
INSERT INTO verses VALUES (3343, 3, 20, 24, 'e-disse a-vós [אַתֶּם֮] [תִּֽירְשׁ֣וּ] a [וַאֲנִ֞י] e-eu a-vós para-vocês para-possuir terra terra fluindo-de leite e-mel yhwh yhwh Elohim-vosso que [מִן־הָֽעַמִּֽים] de');
INSERT INTO verses VALUES (3344, 3, 20, 25, 'e separareis entre na besta [לַטְּמֵאָ֔ה] [וּבֵין־הָע֥וֹף] e-entre a ave o-imundo [אֶת־נַפְשֹֽׁתֵיכֶ֜ם] e-não raspareis a [אֲשֶׁ֣ר] na besta a-terra e-em-todo a-vós tremereis a-te-rri-tó-ria que hivdalti a-vós letema');
INSERT INTO verses VALUES (3345, 3, 20, 26, 'e-sereis a-mim santos que santo eu yhwh va''abdel a-vós de ha''amim a-ser a-mim');
INSERT INTO verses VALUES (3346, 3, 20, 27, 'e-homem ou mulher porque for neles Ov morrendo yiddeoni morte-de yumato''u eles yirgemu eles demeyhem em-eles');
INSERT INTO chapters VALUES (111, 3, 21, 24);
INSERT INTO verses VALUES (3347, 3, 21, 1, 'E-disse yhwh a Moisés disse a os-sacerdotes filhos-de Aarão e-dirás a-eles para-alma não yetema em-seu-peculiar-povo:');
INSERT INTO verses VALUES (3348, 3, 21, 2, 'que se para-sua-permanência: a-ele a-ela para-suamãe: e-para-seu-pai: e-para-seu-filho: e-para-suafilha: e-para-seus-irmãos:');
INSERT INTO verses VALUES (3349, 3, 21, 3, 'e-para-suas-irmãs: a-virgem: a-proximada: a-ele que não היהתה para-homem para-ela será-timado:');
INSERT INTO verses VALUES (3350, 3, 21, 4, 'não será-timado בַּ֣עַל em-seu-povo para-sua-alegria:');
INSERT INTO verses VALUES (3351, 3, 21, 5, 'não escarlate בְּרֹאשָׁ֔ם e-lateral seu-cabelo não não e-seu-carne não não vermelho');
INSERT INTO verses VALUES (3352, 3, 21, 6, 'santos יִהְיוּ לֵאלֹ֣הֵיהֶ֔ם e-não יְחַלְּל֔וּ nome Elohim-deles que a yhwh pão לֶ֧חֶם eles eles e-sejam e-serão קֹדֶשׁ׃');
INSERT INTO verses VALUES (3353, 3, 21, 7, 'mulher [זֹנָ֤ה] [וַחֲלָלָה֙] não [יִקָּ֔חוּ] [וְאִשָּׁ֛ה] [גְּרוּשָׁ֥ה] [מֵאִישָׁ֖הּ] não [יִקָּ֑חוּ] porque ele ele');
INSERT INTO verses VALUES (3354, 3, 21, 8, '[וְקִדַּשְׁתּ֔וֹ] porque a ele teu-Elohim ele מַקְרִ֑יב que sera para-ti yhwh santo eu yhwh מְקַדֵּשְׁכֶֽם׃');
INSERT INTO verses VALUES (3355, 3, 21, 9, 'וּבַת֙ homem sacerdote que תֵּחֵ֖ל לִזְנוֹת a pai-dela ela מְחַלֵּלֶת com-fogo ser-á-consumido');
INSERT INTO verses VALUES (3356, 3, 21, 10, 'וְהַכֹּהֵן֩ o grande de seus irmãos que יוּצַ֥ק sobre seu rosto shemen a unção e encheu a mão-de-ele para vesti-lo não as roupas a não não se separou e em suas roupas não se separou');
INSERT INTO verses VALUES (3357, 3, 21, 11, 'e-sobre todo [מֵ֖ת] não não [לְאָבִ֥יו] [וּלְאִמּ֖וֹ] não não');
INSERT INTO verses VALUES (3358, 3, 21, 12, 'e-de não não [וְלֹ֣א] e-não [OBJ] a [Elohim] que porque [שֶׁ֣מֶן] óleo [Elohim] [עָלָ֖יו] sobre-ele yhwh yhwh');
INSERT INTO verses VALUES (3359, 3, 21, 13, 'e ele mulher em-suas-virgindades pegará;');
INSERT INTO verses VALUES (3360, 3, 21, 14, 'viúva e-divorciada e-quebrantada adúltera a não não que porque se virgem de-seus-povos ele-tomará mulher');
INSERT INTO verses VALUES (3361, 3, 21, 15, 'e-não sua-semente seu-sêmen que porque yhwh yhwh sua-sanidade;');
INSERT INTO verses VALUES (3362, 3, 21, 16, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3363, 3, 21, 17, 'palavra a dizendo dizendo homem de-seu-semente para-suas-gerações será nele nele não não se-achegará pão pão-de Elohim-dele');
INSERT INTO verses VALUES (3364, 3, 21, 18, 'que todo homem que não impuro não se-achegará homem cego ou pulcro ou excomungado ou rebelde');
INSERT INTO verses VALUES (3365, 3, 21, 19, 'ou homem que nele em-ele [רָ֑גֶל] [א֖וֹ] ou mão mão');
INSERT INTO verses VALUES (3366, 3, 21, 20, 'ou [אוֹ־דַ֔ק] ou [תְּבַלֻּ֣ל] ou [א֤וֹ] [גָרָב֙] ou [יַלֶּ֔פֶת] ou [מְר֥וֹחַ] ou');
INSERT INTO verses VALUES (3367, 3, 21, 21, 'todo homem que nele mum מִזֶּ֙רַע֙ não o-sacerdote não יִגַּ֔שׁ yhwh a ofertas-de-fogo-de yhwh pão nele não pão Elohim-dele não יִגַּ֖שׁ para oferecer:');
INSERT INTO verses VALUES (3368, 3, 21, 22, 'pão Elohim-dele dos santuários ha-kodashim e-de הַקֳּדָשִׁ֖ים comerá');
INSERT INTO verses VALUES (3369, 3, 21, 23, 'porém a não não virá não o-altar não se aproximará porque impuro nele que profanará yhwh meus santuários porque eu yhwh מְקַדָּֽשָֽׁם׃');
INSERT INTO verses VALUES (3370, 3, 21, 24, 'e-falou Moisés a אַהֲרֹן e-a seus filhos e-a todo filhos-de Israel');
INSERT INTO chapters VALUES (112, 3, 22, 33);
INSERT INTO verses VALUES (3371, 3, 22, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3372, 3, 22, 2, 'palavra a Arão e-a filhos-seus e se separarão dos santuários filhos-de Israel e-não que profanem eles nome minha santidade que yhwh os santificadores yhwh eu yhwh');
INSERT INTO verses VALUES (3373, 3, 22, 3, 'disse a-eles para vossas gerações todo homem que se-aproximará de-todo seu sême a os-santos que os santifiquem filhos-de Israel a-yhwh aquela sobre-ele e serão cortados yhwh a mesma ante mim eu yhwh');
INSERT INTO verses VALUES (3374, 3, 22, 4, 'homem homem מִזֶּ֣רַע Arão e-ele feridos ou זָ֔ב בַּקֳּדָשִׁים֙ não יֹאכַ֔ל até que será-limpo e o que tocou em-todo טְמֵא־ alma ou nós que תֵצֵ֥א dele deito-de- semente');
INSERT INTO verses VALUES (3375, 3, 22, 5, 'ou homem que [בְּכָל־שֶׁ֖רֶץ] em-todo [יִטְמָא־ל֑וֹ] que [בְאָדָם֙] a-ele [יִטְמָא־ל֔וֹ] a-todo que para-todo');
INSERT INTO verses VALUES (3376, 3, 22, 6, 'alma que תִּגַּע־ nele וְטָמְאָ֖ה até a-tarde e-não que de os-santos porque se rachats a-carne-dele com-a-água');
INSERT INTO verses VALUES (3377, 3, 22, 7, 'וּבָ֥א o-sol ve''taher e-depois comer-á de que porque ele ela');
INSERT INTO verses VALUES (3378, 3, 22, 8, 'nevela u''trefa não yo''chal le''tame''a- nela yhwh yhwh');
INSERT INTO verses VALUES (3379, 3, 22, 9, 'e-guardarão a [וְלֹֽא־יִשְׂא֤וּ] e-não levarão sobre-ele nele que em-ele porque yhwh eu yhwh');
INSERT INTO verses VALUES (3380, 3, 22, 10, 'e-todo זָ֖ר não yo''chal santidade toshab sacerdote vesakir não o-dia קֹדֶשׁ׃');
INSERT INTO verses VALUES (3381, 3, 22, 11, 'e sacerdote porque comprará alma propriedade ele ele come nele e gerará eles eles comerão com seu pão');
INSERT INTO verses VALUES (3382, 3, 22, 12, 'e-filha-de que porque será a homem-de ela isso em-oferta-de não não você-comerá');
INSERT INTO verses VALUES (3383, 3, 22, 13, 'e-filha-de que porque será אַלְמָנָ֣ה e separação וְזֶרַע֮ não-há לָהּ֒ וְשָׁבָ֞ה a casa pai-dela כִּנְעוּרֶ֔יהָ comerás אָבִ֖יהָ comerás e-todo זָ֖ר não o-dia em-ele');
INSERT INTO verses VALUES (3384, 3, 22, 14, 'וְאִ֕ישׁ porque comera santidade בִּשְׁגָגָ֑ה וְיָסַ֤ף [עָלָ֔יו] sobre-ele e colocou para-o-sacerdote a o-santuário');
INSERT INTO verses VALUES (3385, 3, 22, 15, 'e-não [יְחַלְּל֔וּ] a [בְּנֵ֣י] filhos-de Israel a que');
INSERT INTO verses VALUES (3386, 3, 22, 16, 'vehisši''yu elas iniquidade ašmā ba''aklām a que porque yhwh yhwh מְקַדָּֽשָֽׁם׃');
INSERT INTO verses VALUES (3387, 3, 22, 17, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3388, 3, 22, 18, 'palavra a Arão e-para filhos-seus e-a todo filhos-de Israel e-dirás a-eles homem homem de-a-casa Israel e-de ha''ger b-y-i-s-r-a-e-l que yakriv oferta-sua para-todo nidrehem e-para-todo- nidvotam que yakrivu a-yhwh para-holocausto');
INSERT INTO verses VALUES (3389, 3, 22, 19, 'lirztokem תָּמִ֣ים macho no-bêkar nos-châvîm e-be-êzîm:');
INSERT INTO verses VALUES (3390, 3, 22, 20, 'todo que nele não não que-ofreçam porque será a-vós será a-vós');
INSERT INTO verses VALUES (3391, 3, 22, 21, 'e-homem porque ofereça ofertar- holocaustos- para-יהוה לְפַלֵּא־ נֶ֙דֶר֙ ou de-lançamento em-o-amanhecer será no-gado perfeitos não para a vontade todo não não ser- em-ele');
INSERT INTO verses VALUES (3392, 3, 22, 22, 'cabeça ou quebrado ou esmaga ou queimado ou cavado ou Estas não offerei-vos estes a-yhwh e queimareis não dar-vos-ei deles sobre ele para-יהוה');
INSERT INTO verses VALUES (3393, 3, 22, 23, '[וְשׁ֥וֹר] [וָשֶׂ֖ה] [שָׂר֣וּעַ] [וְקָל֑וּט] [נְדָבָה֙] farás ele [וּלְנֵ֖דֶר] não [יֵרָצֶֽה]');
INSERT INTO verses VALUES (3394, 3, 22, 24, 'e-mָע֤וּךְ e-כָתוּת֙ e-נָת֣וּק e-cortem não ofreçais para-יהוה e-na-vossas-terras não fazeis:');
INSERT INTO verses VALUES (3395, 3, 22, 25, 'e-de-mão-de filho-de não não ofreçais a pão-de que de-todo estes porque sua-ungüento não impuro a-vós não correrão a-vós');
INSERT INTO verses VALUES (3396, 3, 22, 26, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3397, 3, 22, 27, 'boi ou gados que oveja porque ser-nascido e será debaixo sua-mãe debaixo-de mãe-dele e do dia o sétimo e a Halaá irá-se para uma oferta mulher para-יהוה');
INSERT INTO verses VALUES (3398, 3, 22, 28, 'e um boi ou ele a-ele não seu-filho não um em-dia um');
INSERT INTO verses VALUES (3399, 3, 22, 29, 'e-quando vocês sacrifiquem oferta- de ação de graças a-yhwh para vossa satisfação Vocais: תִּזְבָּֽחוּ׃ Tradução literal: Sacrificareis׃');
INSERT INTO verses VALUES (3400, 3, 22, 30, 'no-dia o-aquele e-o-eche-le não nós dele até yhwh eu yhwh');
INSERT INTO verses VALUES (3401, 3, 22, 31, 'e-guardardes mandamentos-meus e-fizerdes eles eu yhwh');
INSERT INTO verses VALUES (3402, 3, 22, 32, 'e-não [תְחַלְּלוּ֙] a nome [וְנִ֨קְדַּשְׁתִּ֔י] no-meio-de em-meio-de filhos-de Israel yhwh yhwh');
INSERT INTO verses VALUES (3403, 3, 22, 33, '[הַמּוֹצִ֤יא] vos da-terra Egito a-ser a-vós para-Elohim eu yhwh');
INSERT INTO chapters VALUES (113, 3, 23, 44);
INSERT INTO verses VALUES (3404, 3, 23, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3405, 3, 23, 2, 'palavra a filhos-de Israel e-dirás a-eles yhwh yhwh eles [מִקְרָאֵ֣י] eles Estas eles estes');
INSERT INTO verses VALUES (3406, 3, 23, 3, 'seis-de dias [תֵּעָשֶׂ֣ה] obra e-no-dia o-sétimo sabáth שַׁבָּתֹן מִקְרָא- santidade não obra não ela שַׁבָּת ela-foi a-yhwh em-todo מֹשְׁבֹתֵיכֶם׃');
INSERT INTO verses VALUES (3407, 3, 23, 4, 'Estas [מוֹעֲדֵ֣י] yhwh [מִקְרָאֵ֖י] santidade que eles eles');
INSERT INTO verses VALUES (3408, 3, 23, 5, 'no-mês o-primeiro בְּאַרְבָּעָ֥ה dez לַחֹ֖דֶשׁ entre הָעַרְבָּ֑יִם Pésach para-יהוה');
INSERT INTO verses VALUES (3409, 3, 23, 6, 'e na quinta dez dia para-o-mês esta festa-de a matzot a-yhwh sete dias matzot comereis-vos');
INSERT INTO verses VALUES (3410, 3, 23, 7, 'no-dia הָֽרִאשׁ֔וֹן Lei- será a-vós a-vós todo não serviço não façam ;');
INSERT INTO verses VALUES (3411, 3, 23, 8, 'e ofereçais mulher a-yhwh sete-de dias no-dia o sétimo Lei- santidade todo não serviço não façam ;');
INSERT INTO verses VALUES (3412, 3, 23, 9, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3413, 3, 23, 10, 'palavra a filhos-de Israel e-dirás a-eles porque vai-vos a a-terra a-vós eu deu a-vós e-cortes-eis a cortada-a e-vi-eis a omar primeira cortada-vos a o-sacerdote');
INSERT INTO verses VALUES (3414, 3, 23, 11, 'e-elevar-se-á a o-omar yhwh yhwh para-vos-sede-a-vontade מִמָּחֳרַת֙ הַשָּׁבָת יְנִיפֶ֖נּוּ o-sacerdote');
INSERT INTO verses VALUES (3415, 3, 23, 12, 'וַעֲשִׂיתֶ֕ם em-dia הֲנִֽיפְכֶ֖ם a הָעֹ֑מֶר sujeitai perfeito filho-de שְׁנָת֛וֹ para-oferta para-יהוה');
INSERT INTO verses VALUES (3416, 3, 23, 13, 'וּמִנְחָתוֹ֩ segundo עֶשְׂרֹנִ֜ים flor-farinha misturada בַשֶּׁ֛מֶן mulher a-yhwh aroma נִיחֹ֑חַ e cálice vinho quarto deste vinho');
INSERT INTO verses VALUES (3417, 3, 23, 14, 'e pão e vinha e Carmelo não comereis até o-dia o-dia até até vocês traga-los a oferta eternidade estatuto-de eterno para-gerações-vossas em-todo vosso acampamento');
INSERT INTO verses VALUES (3418, 3, 23, 15, 'e contareis a-vós a partir do dia seguinte הַשָּׁבָת מִיּוֹם֙ הֲבִ֣יאֲכֶ֔ם a עֹ֖מֶר הַתְּנוּפָ֑ה sete שַׁבָּת֖וֹת [תִּהְיֶֽינָה] תִּהְיֶֽינָה׃');
INSERT INTO verses VALUES (3419, 3, 23, 16, 'até מִֽמָּחֳרַ֤ת הַשַּׁבָּת֙ a sétima תִּסְפְּר֖וּ cinquenta dia e oferecerdes oferta-cereais nova a-yhwh');
INSERT INTO verses VALUES (3420, 3, 23, 17, '[מִמּוֹשְׁבֹ֨תֵיכֶ֜ם] levardes pão pão dois segundo deas onças flor-farinha serão חָמֵ֖ץ fareis-vos primícias la-yhwh:');
INSERT INTO verses VALUES (3421, 3, 23, 18, 'e oferecerdes sobre o pão sete кָבָשִׂ֤ים תְּמִימִם֙ filhos-de ano וּפַ֧ר um manhã um [יִהְי֤וּ] dois serao עֹלָה֙ a-yhwh וּמִנְחָתָם֙ וְנִסְכֵּיהֶ֔ם mulher aroma-de tranquilidade para-יהוה');
INSERT INTO verses VALUES (3422, 3, 23, 19, 'וַעֲשִׂיתֶ֛ם Seir um um para-oferta-de-pecado e-dois כְבָשִׂ֛ים filhos-de ano para-sacrifício-de shlamim');
INSERT INTO verses VALUES (3423, 3, 23, 20, 'וְהֵנִ֣יף o-sacerdote אֹתָ֡ם eles sobre pão תְּנוּפָה֙ diante-de yhwh yhwh segundo כְּבָשִׂ֑ים קֹ֛דֶשׁ serao a-yhwh לַכֹּהֵֽן׃');
INSERT INTO verses VALUES (3424, 3, 23, 21, '[וּקְרָאתֶ֞ם] [בְּעֶ֣צֶם] o-dia o-dia [הַזֶּ֗ה] [מִֽקְרָא־קֹ֙דֶשׁ֙] será a-vós todo obra-de não não [חֻקַּ֥ת] eternidade [בְּכָל־מוֹשְׁבֹ֥תֵיכֶ֖ם] em-todo');
INSERT INTO verses VALUES (3425, 3, 23, 22, 'e na colheita-vos a colheita vossa terra não תכל fim da seu campo na colheita-vos não colheita não recolherás o pobre eles deixarás yhwh eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (3426, 3, 23, 23, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3427, 3, 23, 24, 'palavra a filhos-de dizendo dizendo [הַשְּׁבִיעִ֜י] [בְּאֶחָ֣ד] no-primeiro será a-vós para-vocês [זִכְר֥וֹן] [תְּרוּעָ֖ה] [מִקְרָא־קֹֽדֶשׁ]');
INSERT INTO verses VALUES (3428, 3, 23, 25, 'todo obra-de não não fareis וְהִקְרַבְתֶּ֥ם mulher para-יהוה');
INSERT INTO verses VALUES (3429, 3, 23, 26, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3430, 3, 23, 27, '[אַ֡ךְ] [בֶּעָשׂ֣וֹר] [לַחֹדֶשׁ֩] [הַשְּׁבִיעִ֨י] o-este dia [הַכִּפֻּרִ֣ים] ele [מִֽקְרָא־קֹ֙דֶשׁ֙] será a-vós a-vós [אֶת־נַפְשֹׁתֵיכֶ֑ם] a [אִשֶּׁ֖ה] [לַיהוָֽה] mulher');
INSERT INTO verses VALUES (3431, 3, 23, 28, 'e-todo não não [בְּעֶ֖צֶם] o-dia o-dia que dia dia ele ele [עֲלֵיכֶ֔ם] sobre-vós yhwh yhwh');
INSERT INTO verses VALUES (3432, 3, 23, 29, 'que todo [אֲשֶׁ֣ר] que não o-dia [הַזֶּ֑ה] o-dia esta');
INSERT INTO verses VALUES (3433, 3, 23, 30, 'e-todo הַנֶּ֗פֶשׁ que תַּעֲשֶׂה todo o-dia בְּעֶ֖צֶם o-dia esta aquela a a-alma aquela de-meio-de a-sua-pena;');
INSERT INTO verses VALUES (3434, 3, 23, 31, 'todo não não fareis eternidade eterno para-gerações-vossas em-todo מֹֽשְׁבֹֽתֵיכֶֽם׃');
INSERT INTO verses VALUES (3435, 3, 23, 32, '[שַׁבַּ֨ת] [שַׁבָּת֥וֹן] ele a-vós [וְעִנִּיתֶ֖ם] a [בְּתִשְׁעָ֤ה] [לַחֹ֙דֶשׁ֙] [בָּעֶ֔רֶב] [מֵעֶ֣רֶב] [עַד־עֶ֔רֶב] até tarde');
INSERT INTO verses VALUES (3436, 3, 23, 33, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3437, 3, 23, 34, 'palavra a filhos-de dizendo dizendo [עָשָׂ֜ר] dia dia [הַשְּׁבִיעִי֙] [הַזֶּ֔ה] esta [הַסֻּכּ֛וֹת] [שִׁבְעַ֥ת] sete dias');
INSERT INTO verses VALUES (3438, 3, 23, 35, 'no-dia [הָרִאשׁ֖וֹן] [מִקְרָא־קֹ֑דֶשׁ] santidade todo não [תַעֲשֽׂוּ] não');
INSERT INTO verses VALUES (3439, 3, 23, 36, 'sete dias vós-oferecereis mulher a-yhwh no-dia הַשְׁמִינִ֡י מִקְרָא־ será a-vós para-vocês וְהִקְרַבְתֶּ֨ם mulher a-yhwh ela ele todo não servico não façam');
INSERT INTO verses VALUES (3440, 3, 23, 37, 'Estas moedê yhwh que eles eles miqraê santidade para oferecerem mulher a-yhwh oláh e minhá sacrifício e nesakim palavra-de dia em-dia-de-o');
INSERT INTO verses VALUES (3441, 3, 23, 38, 'fora-de-a shabbôt yhwh e milvad mattanotêkem e só todo vossas promessas e só todo vossas ofertas que dar-vos-ão para-יהוה');
INSERT INTO verses VALUES (3442, 3, 23, 39, 'mas em cinco dez dia para-o-mês o-sétimo no vosso convênio a a-terra a-terra comemorareis a festa- no-dia sete-de dias no-dia a-primeira sabathon não o-sétimo Sabbath');
INSERT INTO verses VALUES (3443, 3, 23, 40, 'e tomareis a-vós no-dia o-primeiro fruto árvore glória - palmeiras e ramos de árvore- oliveiras e ramos de águas correntes yhwh diante-de yhwh Elohim de-vós sete dias');
INSERT INTO verses VALUES (3444, 3, 23, 41, '[וְחַגֹּתֶ֤ם] ele chag a-yhwh sete dias בשנה estatuto-de eternidade para-gerações-vossas no mês- ha-shevi-i תָּחֹ֥גּוּ ele');
INSERT INTO verses VALUES (3445, 3, 23, 42, '[בַּסֻּכֹּ֥ת] [תֵּשְׁב֖וּ] sete-de dias todo [בְּיִשְׂרָאֵ֔ל] em-Israel [בַּסֻּכֹּֽת]');
INSERT INTO verses VALUES (3446, 3, 23, 43, '[לְמַעַן֮] [יֵדְע֣וּ] [דֹרֹֽתֵיכֶם֒] que [בַסֻּכּ֗וֹת] [הוֹשַׁ֙בְתִּי֙] a filhos-de Israel [אוֹתָ֖ם] eles da-terra Egito yhwh yhwh');
INSERT INTO verses VALUES (3447, 3, 23, 44, 'e-falou Moisés a yhwh yhwh a filhos-de Israel');
INSERT INTO chapters VALUES (114, 3, 24, 23);
INSERT INTO verses VALUES (3448, 3, 24, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3449, 3, 24, 2, 'צַו a filhos-de Israel e tomem eleicha óleo oliveira zāḵ kāṯı̂ṯ lammāʾōr lehaʿalōṯ neṛ sempre');
INSERT INTO verses VALUES (3450, 3, 24, 3, '[מִחוּץ֩] [לְפָרֹ֨כֶת] o-testemunho em-tenda-de [מוֹעֵ֗ד] [יַעֲרֹךְ֩] ele Arão [מֵעֶ֧רֶב] até manhã yhwh yhwh [חֻקַּ֥ת] eternidade eternidade');
INSERT INTO verses VALUES (3451, 3, 24, 4, 'sobre הַמּוֹנֹרָה הַטּוֹהֶרָה יַעֲרֹךְ a as velas yhwh yhwh sempre');
INSERT INTO verses VALUES (3452, 3, 24, 5, 'וְלָקַחְתָּ sōlet e assaste a-ela dois dez panelas segundo dez será a pão HA''ECHAT:');
INSERT INTO verses VALUES (3453, 3, 24, 6, 'e-tu-colocarás eles sh-teiym arranjadas seis a arranjada sobre o mesa o puro diante-de yhwh');
INSERT INTO verses VALUES (3454, 3, 24, 7, 'e-dar-tei-a sobre הַמְּעַרֶ֑כֶת a areia zakkāh e-será laléchem le''azkará mulher para-יהוה');
INSERT INTO verses VALUES (3455, 3, 24, 8, 'no-dia hashabbát no-dia הַשַׁבָּ֗ת ya''arke''nú diante-de yhwh permanente de-com filhos-de Israel eternidade eternidade');
INSERT INTO verses VALUES (3456, 3, 24, 9, 'e-será para-arão uvelévaná''yv va''akalú''hú em-o-loco qadosh que kodesh kadashím ele a-ele de-um-homem yhwh lei- eternidade');
INSERT INTO verses VALUES (3457, 3, 24, 10, 'e-saiu filho-de mulher israelita-a e-ele filho-de no-meio-de egípcio em-meio-de filhos-de Israel e-ela-ele-se-opuseram no-acampamento filho a-israelita e-homem o-israelita:');
INSERT INTO verses VALUES (3458, 3, 24, 11, 'e-ele filho-de a-mulher a-israelita a o-nome ele e-trouxeram ele sua-mãe Moisés e-nome-de sua-mae שֶׁלּוֹמִית filha-de Palavra Para-a-margem- Dan:');
INSERT INTO verses VALUES (3459, 3, 24, 12, 'E-os-deixaram-o בַּמִּשְׁמָ֑ר Para-separar a-eles sobre yhwh yhwh');
INSERT INTO verses VALUES (3460, 3, 24, 13, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3461, 3, 24, 14, 'Saia a O-mal- a de-fora para-o-machane E-sustentem todo Os-que-ouvirem ele mãos-deles sobre sua-cabeça e lançarem a-ele todo הָעֵדָֽה׃');
INSERT INTO verses VALUES (3462, 3, 24, 15, 'e-a filhos-de Israel dizendo dizendo homem homem porque Maldigam Elohav e-levará seu pecado');
INSERT INTO verses VALUES (3463, 3, 24, 16, 'e o que perfura nome-de morrendo morte-de יִומְתֶּה o arremesso arremessarão em-ele todo a-congregação como-estrangeiro como-cidadão no seu perfurador nome será-morto');
INSERT INTO verses VALUES (3464, 3, 24, 17, 'e cada homem que atingirá todo homem morrendo morrer será-morto');
INSERT INTO verses VALUES (3465, 3, 24, 18, 'e que atinge alma-de animal pagará debaixo debaixo-de alma');
INSERT INTO verses VALUES (3466, 3, 24, 19, 'e cada homem porque dará estragado em-seu-amigo como-que fez assim para-ele para-ele');
INSERT INTO verses VALUES (3467, 3, 24, 20, 'shibber debaixo shibber olho debaixo olho שֶׁן debaixo שֶׁן como-que dará mum בָּֽאָדָ֔ם assim ser-entregue em-ele');
INSERT INTO verses VALUES (3468, 3, 24, 21, 'e que atinge animal ser-compensado e que atinge homem será-morto');
INSERT INTO verses VALUES (3469, 3, 24, 22, 'juízo um será a-vós como estrangeiro como-azar será que eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (3470, 3, 24, 23, 'e-falou Moisés a filhos-de Israel e saíram a o-maledizente a ele para-o-machane e lançaram ele pedra e-filhos-de yhwh fizeram como-que ordenou yhwh a Moisés');
INSERT INTO chapters VALUES (115, 3, 25, 55);
INSERT INTO verses VALUES (3471, 3, 25, 1, 'e-falou yhwh a Moisés em-monte-de dizendo');
INSERT INTO verses VALUES (3472, 3, 25, 2, 'palavra a filhos-de Israel e-dirás que porque vão-vos a a-terra que a-vós deu a-terra e voltará a-terra sabáth para-יהוה');
INSERT INTO verses VALUES (3473, 3, 25, 3, 'seis dois sowaste seu campo e-seis dois cante seu jardim e-ajuntarás a suas produções');
INSERT INTO verses VALUES (3474, 3, 25, 4, 'e-no-ano a sétima sabáth sabáthon será לָאָ֔רֶץ sabáth a-yhwh seu campo não tizra'' ve-kharmekha'' não tizmor:');
INSERT INTO verses VALUES (3475, 3, 25, 5, 'a safikh ktsirakh não tiktsor e-a enave não não tibtsor ano-de será será para-a-terra');
INSERT INTO verses VALUES (3476, 3, 25, 6, 'והיהת shabbat a-terra a-vós para-alimento a-ti ve-l''abdekha'' e para a serva tua e para o arrendatário teu e para o estrangeiro residente no teu que estão contigo');
INSERT INTO verses VALUES (3477, 3, 25, 7, 'e para a tua besta e para o teu animal vivo que na tua terra será todo seu produto para-comer');
INSERT INTO verses VALUES (3478, 3, 25, 8, 'e contará a-ti sete shabbôt dois sete dois sete vezes e-sejam a-ti dias-de sete shabbôt os anos nove e quarenta anos');
INSERT INTO verses VALUES (3479, 3, 25, 9, 'e passareis sopro alarme no-mês o sétimo em-o décimo para-o-mês em-dia-de as-cuprires passareis corneta em-todo terra-vos');
INSERT INTO verses VALUES (3480, 3, 25, 10, 'e santificareis a ano o cinquenta ano e chamareis דרור na-terra para-todo os-sentados-a ela ela-foi a-vós a-vós e-vós-voltar-se-ás homem a אחזתו e-homem a família-dele תשבו׃');
INSERT INTO verses VALUES (3481, 3, 25, 11, '[יוֹבֵ֣ל] ela [שְׁנַ֛ת] [הַחֲמִשִּׁ֥ים] ano será a-vós não [תִזְרָ֔עוּ] e-não [תִקְצְרוּ֙] a [וְלֹ֥א] e-não [אֶת־נְזִרֶֽיהָ] a');
INSERT INTO verses VALUES (3482, 3, 25, 12, 'que Yovē'' ela santidade será a-vós de ha-Šādē Tō''ekhulu a suas produções');
INSERT INTO verses VALUES (3483, 3, 25, 13, 'em-ano-de hay-Yovē'' esta Tāšubu homem a ʾAkhūzāto:');
INSERT INTO verses VALUES (3484, 3, 25, 14, 'e-quando Timmekru mimmekără la-ʿāmitekā ou קָנֹה de-mão-de עֲמִיתֶךָ a תּוֹנ֖וּ homem a irmão-dele');
INSERT INTO verses VALUES (3485, 3, 25, 15, 'em-número-de dois atrás-de [הַיּוֹבֵ֔ל] [תִּקְנֶ֖ה] de-junto-de [עֲמִיתֶ֑ךָ] [בְּמִסְפַּ֥ר] dois [יִמְכָּר־לָֽךְ]');
INSERT INTO verses VALUES (3486, 3, 25, 16, '[לְפִ֣י] muito [רֹ֣ב] [הַשָּׁנִ֗ים] [תַּרְבֶּה֙] [מִקְנָת֔וֹ] [וּלְפִי֙] [מְעֹ֣ט] [הַשָּׁנִ֔ים] [תַּמְעִ֖יט] porque que [מִסְפַּ֣ר] ele ele para-ti');
INSERT INTO verses VALUES (3487, 3, 25, 17, 'e-não [תוֹנוּ֙] homem a [וְיָרֵ֖אתָ] [מֵֽאֱלֹהֶ֑יךָ] que porque eu yhwh');
INSERT INTO verses VALUES (3488, 3, 25, 18, 'e fazeis a minhas ordenanças e-a מִשְׁפָּטַ֥י eles וַעֲשׂיתֶם a-eles e habitaréis sobre a-terra em segurança');
INSERT INTO verses VALUES (3489, 3, 25, 19, 'e dará a-terra seu fruto e comeréis para serdes saciados e habitaréis לָבֶ֖טַח sobre-ela');
INSERT INTO verses VALUES (3490, 3, 25, 20, 'e-porque [תֹאמְר֔וּ] que em-a-ano [הַשְּׁבִיעִ֑ת] eis não [נִזְרָ֔ע] e-não [נֶאֱסֹ֖ף] a');
INSERT INTO verses VALUES (3491, 3, 25, 21, 'וְצִוּ֤יתִי a a-vós a-vós na-ano הַשִׁשֿׁ֑ית וְעָשׂת֙ a הַתְּבוּאָ֔ה para-três os-três:');
INSERT INTO verses VALUES (3492, 3, 25, 22, 'e-sows-vós a o-ano o-oitavo e-eat-vós de a-colheita até até- o-ano o-nono até בוֹא֙ תְּב֣וּאָתָ֔הּ תֹּאכְל֖וּ velho');
INSERT INTO verses VALUES (3493, 3, 25, 23, 'E-a-terra não [תִמָּכֵר֙] [לִצְמִתֻ֔ת] porque a-terra a-terra porque [אַתֶּ֖ם] comigo');
INSERT INTO verses VALUES (3494, 3, 25, 24, 'e em tudo terra אֲחֻזַּתְכֶ֑ם גְּאֻלָּ֖ה vocês-serão para-a-terra');
INSERT INTO verses VALUES (3495, 3, 25, 25, 'porque יָמ֣וּךְ irmão-teu וּמָכַ֖ר de-sua-possesão וּבָ֤א seu-redentor a-ele para-ele e-redem-lo a do-comprado irmão-dele');
INSERT INTO verses VALUES (3496, 3, 25, 26, 'e-um-homem que não ele-será- a-ele redentor sua-mão mão-de-ele e-encontrou para sua-redenção');
INSERT INTO verses VALUES (3497, 3, 25, 27, '[וְחִשַּׁב֙] a segundo [וְהֵשִׁיב֙] [אֶת־הָ֣עֹדֵ֔ף] a [אֲשֶׁ֣ר] [מָֽכַר־ל֑וֹ] que [לַאֲחֻזָּתֽוֹ]');
INSERT INTO verses VALUES (3498, 3, 25, 28, 'e-se não sua-mão mão-sua [הָשִׁ֣יב] a-ele para-ele e-foi [בְּיַד֙] em-mão-de ele até até ano-de [וְיָצָא֙] [בַּיֹּבֵ֔ל] [וְשָׁ֖ב] [לַאֲחֻזָּתֽוֹ]');
INSERT INTO verses VALUES (3499, 3, 25, 29, 'e-homem porque [בֵּית־מוֹשַׁב֙] casa-de [חוֹמָ֔ה] cidade [גְּאֻלָּת֔וֹ] [עַד־תֹּ֖ם] [שְׁנַ֣ת] até [יָמִ֖ים] ano-de [גְאֻלָּתֽוֹ]');
INSERT INTO verses VALUES (3500, 3, 25, 30, 'e-se não יִגָּאֵ֗ל a-ele מְלֹ֣את a-ele ano תְמִימָה֒ וְ֠קָם o-casa que בָּעִ֜יר que חֹמָ֗ה ele לַקֹּנֶ֥ה não לְדֹרֹתָ֑יו não sairá בַּיֹּבֵֽל׃');
INSERT INTO verses VALUES (3501, 3, 25, 31, 'וּבָתֵּ֣י as-hátsérim que não-há para-eles chómah ao-redor a-terra campo-de a-terra seus pensamentos ge''ulláh tihyéh- a-ele úvayyóvel saira');
INSERT INTO verses VALUES (3502, 3, 25, 32, 'vé''árei os-levitas báttei cidades-de ákhúzótam ge''ullát eternidade será [לַלְוִיִּֽם]');
INSERT INTO verses VALUES (3503, 3, 25, 33, 'e-que [יִגְאַל֙] de os-levitas [מִמְכַּר־בַּ֛יִת] [וְעִ֥יר] casa [בַּיֹּבֵ֑ל] que [בָתֵּ֞י] porque [הַלְוִיִּ֗ם] ela os-levitas no-meio-de [בְּנֵ֥י] em-meio-de filhos-de Israel');
INSERT INTO verses VALUES (3504, 3, 25, 34, '[וּֽשְׂדֵ֛ה] [מִגְרַ֥שׁ] [עָרֵיהֶ֖ם] não [יִמָּכֵ֑ר] porque eternidade ele a-eles');
INSERT INTO verses VALUES (3505, 3, 25, 35, 'e-quando [אָחִ֔יךָ] irmão-teu sua-mão mão-sua contigo [בּ֔וֹ] nele [וְתוֹשָׁ֛ב] e-viva [עִמָּֽךְ]');
INSERT INTO verses VALUES (3506, 3, 25, 36, 'a תִּקַּ֤ח מֵֽאִתּוֹ֙ jugo וְתַרְבִּ֔ית וְיָרֵ֖אתָ מֽ͏ֵאֱלֹהֶ֑יךָ וְחֵ֥י irmão-teu contigo');
INSERT INTO verses VALUES (3507, 3, 25, 37, '[OBJ] [לֹֽא־תִתֵּ֥ן] a-ele [בְּנֶ֑שֶׁךְ] a-ele [לֹא־תִתֵּ֥ן] [אָכְלֶֽךָ] não');
INSERT INTO verses VALUES (3508, 3, 25, 38, 'eu yhwh אֱלֹהִים-de-vós que הוציתי vos da-terra Egito a-vós a-vós a terra a-vós para-ser a-vós para-elohim');
INSERT INTO verses VALUES (3509, 3, 25, 39, 'e-quando [אָחִ֛יךָ] אחיך contigo [לֹא־תַעֲבֹ֥ד] a-ti não [עָֽבֶד] nele [sem-traducao] servo');
INSERT INTO verses VALUES (3510, 3, 25, 40, '[כְּשָׂכִ֥יר] [כְּתוֹשָׁ֖ב] será contigo até ano-de [יַעֲבֹ֥ד] [עִמָּֽךְ] contigo');
INSERT INTO verses VALUES (3511, 3, 25, 41, 'e-saiu de ti ele [וּבָנָ֣יו] com-ele וְשָׁב֙ a [וְאֶל־אֲחֻזַּ֥ת] e-a [יָשֽׁוּב] pais-dele ישוב׃');
INSERT INTO verses VALUES (3512, 3, 25, 42, 'porque eles eles eles הוציתי eles não Egito não [עָֽבֶד] [sem-traducao] servo');
INSERT INTO verses VALUES (3513, 3, 25, 43, 'não nele em-ele [וְיָרֵ֖אתָ] e temereis [sem-traducao]');
INSERT INTO verses VALUES (3514, 3, 25, 44, '[וְעַבְדְּךָ֥] ve-amatcha que [יִהְיוּ־לָ֑ךְ] a-ti de-junto-de [אֲשֶׁר֙] que [מֵהֶ֥ם] [תִּקְנ֖וּ] [עֶ֥בֶד] servo [sem-traducao]');
INSERT INTO verses VALUES (3515, 3, 25, 45, 'e-tambem dos filhos de [הַתּוֹשָׁבִ֜ים] [הַגָּרִ֤ים] com-vós de-eles [תִּקְנ֔וּ] [וּמִמִּשְׁפַּחְתָּם֙] que com-vocês que [הוֹלִ֖ידוּ] [בְּאַרְצְכֶ֑ם] e-sejam a-vós [לֽ͏ַאֲחֻזָּֽה]');
INSERT INTO verses VALUES (3516, 3, 25, 46, '[וְהִתְנַחֲלְתֶּ֨ם] eles [לִבְנֵיכֶ֤ם] [אַחֲרֵיכֶם֙] para-possuir אֲחֻזָּ֔ה para-sempre neles [תַּעֲבֹ֑דוּ] [וּבְאַ֨חֵיכֶ֤ם] filhos-de Israel homem [לֹא־תִרְדֶּ֥ה] nele [בְּפָֽרֶךְ׃] nele com-dureza');
INSERT INTO verses VALUES (3517, 3, 25, 47, 'e-porque [תַשִּׂ֗יג] mão [גֵּ֤ר] [וְתוֹשָׁב֙] contigo [וּמָ֥ךְ] irmão-teu com-ele [וְנִמְכַּ֗ר] [לְגֵ֤ר] [תּוֹשָׁב֙] contigo ou [לְעֵ֖קֶר] [מִשְׁפַּ֥חַת] [גֵּֽר]');
INSERT INTO verses VALUES (3518, 3, 25, 48, 'depois-de [נִמְכַּ֔ר] גְּאֻלָּ֖ה tihyéh- um um [יִגְאָלֶֽנּוּ] [sem-traducao]');
INSERT INTO verses VALUES (3519, 3, 25, 49, 'ou [א֤וֹ] ou filho-de [אֽוֹ־מִשְּׁאֵ֧ר] [בְּשָׂר֛וֹ] ou [יִגְאָלֶ֑נּוּ] [אֽוֹ־הִשִּׂ֥יגָה] sua-mão [וְנִגְאָֽל]');
INSERT INTO verses VALUES (3520, 3, 25, 50, 'e-calculou com [מִשְּׁנַת֙] [הִמָּ֣כְרוֹ] a-ele até até ano-de [וְהָיָ֞ה] e-será prata [בְּמִסְפַּ֣ר] em-número-de dois כִּימֵ֥י será será com-ele');
INSERT INTO verses VALUES (3521, 3, 25, 51, 'se ainda [בַּשָּׁנִ֑ים] [לְפִיהֶן֙] [יָשִׁ֣יב] [גְּאֻלָּת֔וֹ] [מִכֶּ֖סֶף] [מִקְנָתֽוֹ]');
INSERT INTO verses VALUES (3522, 3, 25, 52, 'e-se [נִשְׁאַ֧ר] [בַּשָּׁנִ֛ים] [עַד־שְׁנַ֥ת] até ano-de [כְּפִ֣י] [שָׁנָ֔יו] a-ele segundo [sem-traducao] ele-fará-voltar a [sem-traducao]');
INSERT INTO verses VALUES (3523, 3, 25, 53, '[כִּשְׂכִ֥יר] ano [בְּשָׁנָ֖ה] será com-ele não [בְּפֶ֖רֶךְ] [לְעֵינֶֽיךָ]');
INSERT INTO verses VALUES (3524, 3, 25, 54, 'e-se não [בְּאֵ֑לֶּה] [וְיָצָא֙] e-saiu no-ano-de ele ele [עִמּֽוֹ] com-ele');
INSERT INTO verses VALUES (3525, 3, 25, 55, 'porque a-mim filhos-de Israel eles meus-servos eles que הוציתי eles yhwh Egito eu yhwh Elohim-vosso');
INSERT INTO chapters VALUES (116, 3, 26, 46);
INSERT INTO verses VALUES (3526, 3, 26, 1, 'não a-vós [אֱלִילִ֗ם] [וּפֶ֤סֶל] [וּמַצֵּבָה֙] [לֹֽא־תָקִ֣ימוּ] a-vós [וְאֶ֣בֶן] a-vós não [תִתְּנוּ֙] não [לְהִֽשְׁתַּחֲוֺ֖ת] [עָלֶ֑יהָ] que sobre-ela yhwh eu yhwh');
INSERT INTO verses VALUES (3527, 3, 26, 2, 'a [תִּשְׁמֹ֔רוּ] [וּמִקְדָּשִׁ֖י] [תִּירָ֑אוּ] temei-vos yhwh yhwh');
INSERT INTO verses VALUES (3528, 3, 26, 3, 'se [תֵּלֵ֑כוּ] andareis e-a meus-mandamentos eles e-fizerdes eles');
INSERT INTO verses VALUES (3529, 3, 26, 4, 'e-darei [גִשְׁמֵיכֶ֖ם] [בְּעִתָּ֑ם] e dará a-terra [יְבוּלָ֔הּ] [וְעֵ֥ץ] o-campo dará [פִּרְיֽוֹ]');
INSERT INTO verses VALUES (3530, 3, 26, 5, '[וְהִשִּׂ֨יג] a-vós [דַּ֙יִשׁ֙] a [וּבָצִ֖יר] [יַשִּׂ֣יג] [אֶת־זָ֑רַע] a semente e-voces-comeram [וִֽישַׁבְתֶּ֥ם] [לָבֶ֖טַח] e habitaréis לָבֶ֖טַח [sem-traducao]');
INSERT INTO verses VALUES (3531, 3, 26, 6, 'e-darei paz na-terra [וּשְׁכַבְתֶּ֖ם] e-não-há [מַחֲרִ֑יד] [וְהִשְׁבַּתִּ֞י] vivente mal de a-terra e espada não [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (3532, 3, 26, 7, '[וּרְדַפְתֶּ֖ם] a [וְנָפְל֥וּ] [לִפְנֵיכֶ֖ם] diante-de-vós');
INSERT INTO verses VALUES (3533, 3, 26, 8, '[וְרָדְפ֨וּ] [מִכֶּ֤ם] cinco cem e cem de vós [רְבָבָ֣ה] [יִרְדֹּ֑פוּ] [וְנָפְל֧וּ] inimigos-vossos diante-de-vós [לֶחָֽרֶב]');
INSERT INTO verses VALUES (3534, 3, 26, 9, '[וּפָנִ֣יתִי] a-vós [וְהִפְרֵיתִ֣י] vos [וְהִרְבֵּיתִ֖י] a-vós e-levantarei a aliança-minha');
INSERT INTO verses VALUES (3535, 3, 26, 10, 'e-comereis velho [נוֹשָׁ֑ן] [וְיָשָׁ֕ן] de-diante-de novo [תּוֹצִֽיאוּ]');
INSERT INTO verses VALUES (3536, 3, 26, 11, 'e-darei [מִשְׁכָּנִ֖י] [בְּתוֹכְכֶ֑ם] e-não [נַפְשִׁ֖י] alma-minha');
INSERT INTO verses VALUES (3537, 3, 26, 12, '[וְהִתְהַלַּכְתִּי֙] [בְּת֣וֹכְכֶ֔ם] e-eu-serei a-vós para-אלהים e-vós [תִּהְיוּ־לִ֥י] para-mim le-a-m');
INSERT INTO verses VALUES (3538, 3, 26, 13, 'eu yhwh vosso-Elohim que eu tirei vos da-terra Egito [מִֽהְיֹ֥ת] a-eles עֲבָדִ֑ים [וָאֶשְׁבֹּר֙] [מֹטֹ֣ת] [עֻלְּכֶ֔ם] e-o-olékh vos [קֽוֹמְמִיּֽוּת׃]');
INSERT INTO verses VALUES (3539, 3, 26, 14, 'e-se não [לִ֑י] a-mim e-não [OBJ] a todo');
INSERT INTO verses VALUES (3540, 3, 26, 15, 'e-se בְּחֻקֹּתַ֣י [וְאִ֥ם] e-se a מִשְׁפָּטַ֖י para-não alma-vossa para-não [לְהַפְרְכֶ֖ם] a todo eu [sem-traducao] a em-pacto-meu');
INSERT INTO verses VALUES (3541, 3, 26, 16, 'também eu a-vós isto para-vós [בֶּֽהָלָה֙] [אֶת־הַשַּׁחֶ֣פֶת] [וְאֶת־הַקַּדַּ֔חַת] a [עֵינַ֖יִם] e-a [נָ֑פֶשׁ] [וּזְרַעְתֶּ֤ם] [לָרִיק֙] [זַרְעֲכֶ֔ם] alma [אֹיְבֵיכֶֽם] [sem-traducao] semente-vosso va''akalú''hú inimigos-vossos');
INSERT INTO verses VALUES (3542, 3, 26, 17, 'e-darei face-de em-vós [וְנִגַּפְתֶּ֖ם] diante-de אֹיְבֵיכֶ֑ם [וְרָד֤וּ] [בָכֶם֙] [שֹֽׂנְאֵיכֶ֔ם] [וְנַסְתֶּ֖ם] e-não-há [אֶתְכֶֽם׃] a-vós');
INSERT INTO verses VALUES (3543, 3, 26, 18, 'e-se-que- não אֵלֶּה não [וְיָסַפְתִּי֙] a-mim [אֶתְכֶ֔ם] [שֶׁ֖בַע] vos sete sobre [sem-traducao]');
INSERT INTO verses VALUES (3544, 3, 26, 19, '[וְשָׁבַרְתִּ֖י] a orgulho [וְנָתַתִּ֤י] e-darei a [וְאֶֽת־אַרְצְכֶ֖ם] [כַּנְּחֻשָֽׁה] e-[OBJ]');
INSERT INTO verses VALUES (3545, 3, 26, 20, '[וְתַ֥ם] [לָרִ֖יק] [כֹּחֲכֶ֑ם] e-não [אַרְצְכֶם֙] [אֶת־יְבוּלָ֔הּ] a a-terra não a-terra não');
INSERT INTO verses VALUES (3546, 3, 26, 21, 'e-se [עִמִּי֙] comigo [וְלֹ֥א] e-não [לִשְׁמֹ֣עַֽ] [לִ֑י] a-mim [עֲלֵיכֶם֙] sobre-vós [שֶׁ֖בַע] sete');
INSERT INTO verses VALUES (3547, 3, 26, 22, '[וְהִשְׁלַחְתִּ֨י] [בָכֶ֜ם] a animal-de o-campo [אֶתְכֶ֔ם] vos [אֶת־בְּהֶמְתְּכֶ֔ם] a [אֶתְכֶ֑ם] [וְנָשַׁ֖מּוּ] a-vós');
INSERT INTO verses VALUES (3548, 3, 26, 23, 'e-se-que- não não [לִ֑י] a-mim [עִמִּ֖י] com-mim [sem-traducao]');
INSERT INTO verses VALUES (3549, 3, 26, 24, 'e-irei também eu com-vós [וְהִכֵּיתִ֤י] e-ferrei vos também eu sete sobre [sem-traducao]');
INSERT INTO verses VALUES (3550, 3, 26, 25, '[וְהֵבֵאתִ֨י] sobre-vos espada [נֹקֶ֙מֶת֙] [נְקַם־בְּרִ֔ית] aliança [אֶל־עָרֵיכֶ֑ם] a [דֶ֙בֶר֙] [בְּת֣וֹכְכֶ֔ם] palavra [בְּיַד־אוֹיֵֽב] [sem-traducao] por-mão-de inimigo');
INSERT INTO verses VALUES (3551, 3, 26, 26, '[בְּשִׁבְרִ֣י] a-vós mate- lechem [עֶ֣שֶׂר] dez mulheres [בְּתַנּ֣וּר] um um [לַחְמְכֶ֖ם] [בַּמִּשְׁקָ֑ל] no-pesado e comeréis e-não תִשְׂבָּֽעוּ׃');
INSERT INTO verses VALUES (3552, 3, 26, 27, 'e-se-que- não não [לִ֑י] a-mim [עִמִּ֖י] com-mim [sem-traducao]');
INSERT INTO verses VALUES (3553, 3, 26, 28, '[וְהָלַכְתִּ֥י] com-vós [בַּחֲמַת־קֶ֑רִי] [וְיִסַּרְתִּ֤י] [אֶתְכֶם֙] vos também eu sete sobre');
INSERT INTO verses VALUES (3554, 3, 26, 29, 'e comeréis de-carne [בְּנֵיכֶ֑ם] [וּבְשַׂ֥ר] bְּnֹתֵיכֶ֖ם comereis-vos');
INSERT INTO verses VALUES (3555, 3, 26, 30, '[וְהִשְׁמַדְתִּ֞י] a [וְהִכְרַתִּי֙] [אֶת־חַמָּ֣נֵיכֶ֔ם] a [אֶת־פִּגְרֵיכֶ֔ם] e-n-d-e-rei a [וְגָעֲלָ֥ה] sobre [אֶתְכֶֽם] [sem-traducao] [sem-traducao] alma-minha a-vós');
INSERT INTO verses VALUES (3556, 3, 26, 31, 'e-darei a [חָרְבָּ֔ה] [וַהֲשִׁמּוֹתִ֖י] [אֶת־מִקְדְּשֵׁיכֶ֑ם] a [אָרִ֔יחַ] e-não [נִיחֹֽחֲכֶֽם]');
INSERT INTO verses VALUES (3557, 3, 26, 32, '[וַהֲשִׁמֹּתִ֥י] eu a a-terra [עָלֶ֙יהָ֙] sobre-ela [הַיֹּשְׁבִ֖ים] os-habitantes');
INSERT INTO verses VALUES (3558, 3, 26, 33, 'e-vós cinto [בַגּוֹיִ֔ם] [וַהֲרִיקֹתִ֥י] depois-de-vós espada e-será [אַרְצְכֶם֙] sem semear [וְעָרֵיכֶ֖ם] serao espada:');
INSERT INTO verses VALUES (3559, 3, 26, 34, 'então [תִּרְצֶ֨ה] a-terra a [כֹּ֚ל] dias-de dias-de e-vós em-terra-de אֹיְבֵיכֶ֑ם então [תִּשְׁבַּ֣ת] a-terra [וְהִרְצָ֖ת] a [sem-traducao]');
INSERT INTO verses VALUES (3560, 3, 26, 35, 'todo dias-de [תִּשְׁבֹּ֑ת] a que não [בְּשַׁבְּתֹתֵיכֶ֖ם] [בְּשִׁבְתְּכֶ֥ם] [עָלֶֽיהָ]');
INSERT INTO verses VALUES (3561, 3, 26, 36, '[וְהַנִּשְׁאָרִ֣ים] em-vós [וְהֵבֵ֤אתִי] [מֹ֙רֶךְ֙] no-coração-eles [בְּאַרְצֹ֖ת] [אֹיְבֵיהֶ֑ם] [וְרָדַ֣ף] eles voz folha [נִדָּ֔ף] [וְנָס֧וּ] [מְנֻֽסַת־חֶ֛רֶב] espada e-cairão e-não-há [sem-traducao]');
INSERT INTO verses VALUES (3562, 3, 26, 37, '[וְכָשְׁל֧וּ] homem-de [כְּמִפְּנֵי־חֶ֖רֶב] [וְרֹדֵ֣ף] espada [וְלֹא־תִֽהְיֶ֤ה] a-vós e-não [לִפְנֵ֖י] para-vocês');
INSERT INTO verses VALUES (3563, 3, 26, 38, '[וַאֲבַדְתֶּ֖ם] em-nações e comerá vos terra inimigos-vossos');
INSERT INTO verses VALUES (3564, 3, 26, 39, '[וְהַנִּשְׁאָרִ֣ים] בָּכֶ֗ם [יִמַּ֙קּוּ֙] [בּֽ͏ַעֲוֺנָ֔ם] [בְּאַרְצֹ֖ת] אֹיְבֵיכֶ֑ם e-af [בַּעֲוֺנֹ֥ת] pais-deles [אִתָּ֥ם] [יִמָּֽקּוּ]');
INSERT INTO verses VALUES (3565, 3, 26, 40, '[וְהִתְוַדּ֤וּ] a עֲוֺנָם֙ e-a iniquidade pais-deles [מָֽעֲלוּ־בִ֑י] que maaulu- em-mim וְאַף que [sem-traducao] com-mim [sem-traducao]');
INSERT INTO verses VALUES (3566, 3, 26, 41, 'também eu [עִמָּם֙] com-eles [וְהֵבֵאתִ֣י] eles a-eles em-terra-de [אוֹ־אָ֣ז] ou então [הֶֽעָרֵ֔ל] [וְאָ֖ז] [יִרְצ֥וּ] [אֶת־עֲוֺנָֽם] a');
INSERT INTO verses VALUES (3567, 3, 26, 42, '[וְזָכַרְתִּ֖י] a minha-aliança [וְאַף֩] [אֶת־בְּרִיתִ֨י] a [וְאַ֨ף] Isaque [אַבְרָהָ֛ם] a E-a-terra Abraão [sem-traducao] E-a-terra [sem-traducao]');
INSERT INTO verses VALUES (3568, 3, 26, 43, 'E-a-terra [תֵּעָזֵ֨ב] dentre-eles [וְתִ֣רֶץ] a [בָּהְּשַׁמָּה֙] [מֵהֶ֔ם] de-eles e-eles terão-desejo a עֲוֺנָ֑ם porque [מָאָ֔סוּ] pelos meus juízos rejeitaram e-a [sem-traducao] [sem-traducao] alma-deles');
INSERT INTO verses VALUES (3569, 3, 26, 44, 'e-também também [בְּאֶ֣רֶץ] [אֹֽיְבֵיהֶ֗ם] em-terra-de [וְלֹֽא־גְעַלְתִּים֙] não [לְהָפֵ֥ר] e-não [אִתָּ֑ם] que [אֲנִ֥י] yhwh [אֱלֹהֵיהֶֽם] porque yhwh');
INSERT INTO verses VALUES (3570, 3, 26, 45, '[וְזָכַרְתִּ֥י] a-eles aliança רִאשׁוֹנִ֑ים que [הוֹצֵֽאתִי־אֹתָם֩] [מֵאֶ֨רֶץ] de-terra-de Egito aos-olhos-de [לִהְיֹ֥ת] a-eles a-eles [אֲנִ֥י] yhwh yhwh');
INSERT INTO verses VALUES (3571, 3, 26, 46, 'Estas as leis [וְהַמִּשְׁפָּטִים֮] [וְהַתּוֹרֹת֒] que dar yhwh בֵּינ֕וֹ e-entre filhos-de Israel em-monte-de Sinai pela-mão-de Moisés');
INSERT INTO chapters VALUES (117, 3, 27, 34);
INSERT INTO verses VALUES (3572, 3, 27, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (3573, 3, 27, 2, 'palavra a filhos-de Israel e-dirás a-eles que porque [נֶ֑דֶר] voto em-o-valor-seu [לַֽיהוָֽה] para-יהוה');
INSERT INTO verses VALUES (3574, 3, 27, 3, 'e-era [עֶרְכְּךָ֙] o macho [מִבֶּן֙] vinte ano e-até filho-de sessenta ano e-foi [חֲמִשִּׁ֛ים] [שֶׁ֥קֶל] [כֶּ֖סֶף] prata na-unidade-de-prata o-santuário');
INSERT INTO verses VALUES (3575, 3, 27, 4, 'e-se ela ela e-acontecerá [שְׁלֹשִׁ֥ים] trinta');
INSERT INTO verses VALUES (3576, 3, 27, 5, 'e-se de-filho-de cinco dois e-ate filho-de vinte ano ve-hâyâ: [עֶשְׂרִ֣ים] [שְׁקָלִ֑ים] vinte [עֲשֶׂ֥רֶת] [שְׁקָלִֽים] dez [sem-traducao]');
INSERT INTO verses VALUES (3577, 3, 27, 6, 'e-se de-filho-de novo e-ate filho-de cinco dois e-era [חֲמִשָּׁ֥ה] o macho cinco escalam prata [שְׁלֹ֥שֶׁת] [שְׁקָלִ֖ים] três escalam כַּסֶּפֶת׃');
INSERT INTO verses VALUES (3578, 3, 27, 7, '[וְ֠אִם] de-filho-de [שָׁנָ֤ה] [וָמַ֙עְלָה֙] [אִם־זָכָ֔ר] se macho e-foi [עָשָׂ֖ר] cinco dez [עֲשָׂרָ֥ה] [שְׁקָלִֽים]');
INSERT INTO verses VALUES (3579, 3, 27, 8, 'e-se ele ele [וְהֶֽעֱמִידוֹ֙] [לִפְנֵ֣י] diante-de o-sacerdote ele ele o-sacerdote sobre meu-boca que [הַנֹּדֵ֔ר] mão [הַכֹּהֵֽן׃] [sem-traducao] o-sacerdote');
INSERT INTO verses VALUES (3580, 3, 27, 9, 'e-se animal que [מִמֶּ֛נָּה] mimenah- oferta para-יהוה todo que nós de-ele a-yhwh ele-será- [sem-traducao]');
INSERT INTO verses VALUES (3581, 3, 27, 10, 'não [יַחֲלִיפֶ֗נּוּ] e-não ele bom bom [אוֹ־רַ֣ע] ou mau [יָמִ֤יר] animal-doméstico [בִּבְהֵמָ֔ה] [וְהָֽיָה־ה֥וּא] animal [יִֽהְיֶה־קֹּֽדֶשׁ]');
INSERT INTO verses VALUES (3582, 3, 27, 11, 'e se todo animal impura que não [קָרְבָּ֖ן] mimenah- oferta para-יהוה [לִפְנֵ֥י] a os-animais diante-de o-sacerdote');
INSERT INTO verses VALUES (3583, 3, 27, 12, '[וְהֶעֱרִ֤יךְ] o-sacerdote a-ela entre bom e-entre mal [כְּעֶרְכְּךָ֥] o-sacerdote assim será');
INSERT INTO verses VALUES (3584, 3, 27, 13, 'e-se [יִגְאָלֶ֑נָּה] [וְיָסַ֥ף] [חֲמִישִׁת֖וֹ] [עַל־עֶרְכֶּֽךָ] sobre');
INSERT INTO verses VALUES (3585, 3, 27, 14, 'e-homem porque [אֶת־בֵּית֥וֹ] a [לַֽיהוָ֔ה] [וְהֶעֱרִיכוֹ֙] a-yhwh entre bom e-entre mal e-entre mau ele [הַכֹּהֵ֖ן] a-ele o-sacerdote');
INSERT INTO verses VALUES (3586, 3, 27, 15, 'e-se-que- ה막דיש [אֶת־בֵּית֑וֹ] a casa-dele [כֶּֽסֶף־עֶרְכְּךָ֛] [עָלָ֖יו] [וְהָ֥יָה] a-ele sobre-ele [sem-traducao] a-ele');
INSERT INTO verses VALUES (3587, 3, 27, 16, 'e-se de-sade [מִשְּׂדֵ֣ה] [אֲחֻזָּת֗וֹ] homem a-yhwh e-será [וְהָיָ֥ה] de-conformidade-com [לְפִ֣י] sua-semente semente semente-de-trigo [שְׂעֹרִ֔ים] [בַּחֲמִשִּׁ֖ים] כַּסֶּפֶת׃');
INSERT INTO verses VALUES (3588, 3, 27, 17, 'se [הַיֹּבֵ֖ל] [יַקְדִּ֣ישׁ] [שָׂדֵ֑הוּ] [כְּעֶרְכְּךָ֖] [יָקֽוּם]');
INSERT INTO verses VALUES (3589, 3, 27, 18, 'e-se atrás-de [יַקְדִּ֣ישׁ] [שָׂדֵהוּ֒] [וְחִשַּׁב־ל֨וֹ] [הַכֹּהֵ֜ן] a-ele o-sacerdote a הכסף até פִּ֤י [הַיֹּבֵ֑ל] [וְנִגְרַ֖ע] até ano-de [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (3590, 3, 27, 19, 'e-se [יִגְאַל֙] [אֶת־הַשָּׂדֶ֔ה] a ele [וְ֠יָסַף] [חֲמִשִׁ֧ית] [כֶּֽסֶף־עֶרְכְּךָ֛] [עָלָ֖יו] [וְקָ֥ם] a-ele');
INSERT INTO verses VALUES (3591, 3, 27, 20, 'e-se não [אֶת־הַשָּׂדֶ֔ה] a o-campo e-se [אַחֵ֑ר] não o-campo a homem-de não');
INSERT INTO verses VALUES (3592, 3, 27, 21, 'e-será o-de-a-terra [בְּצֵאת֣וֹ] [בַיֹּבֵ֗ל] קֹ֛דֶשׁ a-yhwh [כִּשְׂדֵ֣ה] o-herem para-o-sacerdote será ʾAkhūzāto:');
INSERT INTO verses VALUES (3593, 3, 27, 22, 'e se a campo- מִקְנָת֔וֹ não não de-sade [יַקְדִּ֖ישׁ] [לַֽיהוָֽה] para-יהוה');
INSERT INTO verses VALUES (3594, 3, 27, 23, '[וְחִשַּׁב־ל֣וֹ] a-ele o-sacerdote a [הָֽעֶרְכְּךָ֔] até até ano-de [וְנָתַ֤ן] [אֶת־הָעֶרְכְּךָ֙] no-dia [הַה֔וּא] em-o-dia aquele');
INSERT INTO verses VALUES (3595, 3, 27, 24, 'em-ano-de [הַיּוֹבֵל֙] voltara o-campo para aquele [קָנָ֖הוּ] [מֵאִתּ֑וֹ] [לַאֲשֶׁר־ל֖וֹ] a-ele a-terra a-terra');
INSERT INTO verses VALUES (3596, 3, 27, 25, 'e-todo será será em-siclo a-santidade vinte será será');
INSERT INTO verses VALUES (3597, 3, 27, 26, 'somente [אֲשֶׁר־יְבֻכַּ֤ר] que [בִּבְהֵמָ֔ה] para-יהוה [אִ֖ישׁ] ele [אִם־שׁ֣וֹר] homem a-ela ele se');
INSERT INTO verses VALUES (3598, 3, 27, 27, 'e-se [בַּבְּהֵמָ֤ה] [הַטְּמֵאָה֙] [וּפָדָ֣ה] [בְעֶרְכֶּ֔ךָ] [וְיָסַ֥ף] [חֲמִשִׁת֖וֹ] sobre-ele e-se não [וְנִמְכַּ֥ר] [בְּעֶרְכֶּֽךָ]');
INSERT INTO verses VALUES (3599, 3, 27, 28, 'somente todo [יַחֲרִם֩] que [לַֽיהוָ֜ה] homem [מֵאָדָ֤ם] de-todo que para-ele não e-animal [וְלֹ֣א] [יִגָּאֵ֑ל] não [קֹֽדֶשׁ־קָֽדָשִׁ֥ים] ele [לַיהוָֽה] todo');
INSERT INTO verses VALUES (3600, 3, 27, 29, 'todo [אֲשֶׁ֧ר] que [מִן־הָאָדָ֖ם] não o-homem morrendo [יוּמָֽת]');
INSERT INTO verses VALUES (3601, 3, 27, 30, 'e-todo a-terra a-terra a-terra do-fruto-de a-árvore o-arvore ele ele santidade para-יהוה');
INSERT INTO verses VALUES (3602, 3, 27, 31, 'e-se [יִגְאַ֛ל] [אִ֖ישׁ] homem [חֲמִשִׁית֖וֹ] [יֹסֵ֥ף] [עָלָֽיו]');
INSERT INTO verses VALUES (3603, 3, 27, 32, 'e-todo [בָּקָר֙] manhã [כֹּ֥ל] todo debaixo [הַשָּׁ֑בֶט] debaixo-de a vara [לַֽיהוָֽה] ele-será- [sem-traducao] para-יהוה');
INSERT INTO verses VALUES (3604, 3, 27, 33, 'não [יְבַקֵּ֛ר] entre bom [וְלֹ֣א] e-não [וְאִם־הָמֵ֣ר] e-se [וְהָֽיָה־ה֧וּא] [וּתְמוּרָת֛וֹ] e-haverá- não [יִגָּאֵֽל] ele-será- santidade não [sem-traducao]');
INSERT INTO verses VALUES (3605, 3, 27, 34, 'Estas os-mandamentos que ordenou yhwh a Moisés a filhos-de Israel');
