INSERT INTO chapters VALUES (118, 4, 1, 54);
INSERT INTO verses VALUES (3606, 4, 1, 1, 'e-falou yhwh a Moisés em-deserto-de Sinai em-tenda-de de-encontro em-um para-o-mês o-segundo em-a-ano a-segunda para-saída-deles de-terra-de dizendo para-dizer');
INSERT INTO verses VALUES (3607, 4, 1, 2, 'levantai a cabeça todo congregação-de filhos-de Israel para-famílias-deles para-casa-de pais-deles em-número-de nomes todo macho para-crânios-deles');
INSERT INTO verses VALUES (3608, 4, 1, 3, 'de-filho-de vinte ano e-para-cima todo exército exército em-Israel eles a-eles tu tu e-Aarão');
INSERT INTO verses VALUES (3609, 4, 1, 4, 'e-convosco serão homem homem para-a-tribo homem cabeça para-casa-de ele ela');
INSERT INTO verses VALUES (3610, 4, 1, 5, 'e-estes nomes-de os-homens que estarão-em-pé convosco para-Rúben Elisur filho-de Sedeur');
INSERT INTO verses VALUES (3611, 4, 1, 6, 'para-Simeão Selumiel filho-de Zurisadai');
INSERT INTO verses VALUES (3612, 4, 1, 7, 'para-Judá Nasom filho-de Aminadabe');
