INSERT INTO verses VALUES (3614, 4, 1, 9, 'para-Zebulom Eliabe filho-de Helom');
INSERT INTO verses VALUES (3615, 4, 1, 10, 'a-filhos-de José para-Efraim Elisama filho-de Amiúde para-Manassés Gamaliel filho-de Pedazur');
INSERT INTO verses VALUES (3616, 4, 1, 11, 'para-Benjamim Abidã filho-de Gideoni');
INSERT INTO verses VALUES (3617, 4, 1, 12, 'para-Dã Aiezer filho-de Amisadai');
INSERT INTO verses VALUES (3618, 4, 1, 13, 'para-Aser Pagiel filho-de Ocrã');
INSERT INTO verses VALUES (3619, 4, 1, 14, 'para-Gade Eliasafe filho-de Deuel');
INSERT INTO verses VALUES (3620, 4, 1, 15, 'para-Naftali Aira filho-de Enã');
INSERT INTO verses VALUES (3621, 4, 1, 16, 'Estas a-congregação príncipes-de tribos-de pais-deles cabeças-de milhares-de Israel eles');
INSERT INTO verses VALUES (3622, 4, 1, 17, 'E-tomou Moisés e-Arão את os-homens os-estes que foram-designados em-nomes');
INSERT INTO verses VALUES (3623, 4, 1, 18, 'e-a todo a-congregação congregaram em-um para-o-mês o-segundo e-registraram-se sobre famílias-deles para-casa-de pais-deles em-número-de nomes-de de-filho-de vinte ano e-para-cima para-crânios-deles');
INSERT INTO verses VALUES (3624, 4, 1, 19, 'como ordenou yhwh a Moisés e-contou-os em-deserto-de Sinai');
INSERT INTO verses VALUES (3625, 4, 1, 20, 'e-foram filhos-de Rúben primogênito-de Israel gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes para-cabeças-deles todo macho de-filho-de vinte ano sai exército saindo exército');
INSERT INTO verses VALUES (3626, 4, 1, 21, 'contados-deles para-tribo-de Rúben seis e-quarenta mil e-cinco centenas');
INSERT INTO verses VALUES (3627, 4, 1, 22, 'a-filhos-de Simeão gerações-deles para-famílias-deles para-casa-de pais-deles contados-dele em-número-de nomes para-cabeças-deles todo macho de-filho-de vinte ano e-para-cima sai exército exército');
INSERT INTO verses VALUES (3628, 4, 1, 23, 'contados-deles para-tribo-de Simeão nove e-cinquenta mil e-três centenas');
INSERT INTO verses VALUES (3629, 4, 1, 24, 'a-filhos-de Gade gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes-de de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3630, 4, 1, 25, 'contados-deles para-tribo-de Gade cinco e-quarenta mil e-seis centenas e-cinquenta');
INSERT INTO verses VALUES (3631, 4, 1, 26, 'a-filhos-de Judá gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3632, 4, 1, 27, 'contados-deles para-tribo-de Judá quatro e-setenta mil e-seis centenas');
INSERT INTO verses VALUES (3633, 4, 1, 28, 'a-filhos-de Issacar gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3634, 4, 1, 29, 'contados-deles para-tribo-de Issacar quatro e-cinquenta mil e-quatro centenas');
INSERT INTO verses VALUES (3635, 4, 1, 30, 'a-filhos-de Zebulom gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3636, 4, 1, 31, 'contados-deles para-a-tribo-de Zebulom sete e-cinquenta mil e-quatro centenas');
INSERT INTO verses VALUES (3637, 4, 1, 32, 'para-filhos-de José a-filhos-de Efraim gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3638, 4, 1, 33, 'contados-deles para-a-tribo-de Efraim quarenta mil e-cinco centenas');
INSERT INTO verses VALUES (3639, 4, 1, 34, 'a-filhos-de Manassés gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes-de de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3640, 4, 1, 35, 'contados-deles para-a-tribo-de Manassés dois e-trinta mil e-duzentos');
INSERT INTO verses VALUES (3641, 4, 1, 36, 'a-filhos-de Benjamim gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3642, 4, 1, 37, 'contados-deles para-a-tribo-de Benjamim cinco e-trinta mil e-quatro centenas');
INSERT INTO verses VALUES (3643, 4, 1, 38, 'a-filhos-de Dã gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3644, 4, 1, 39, 'contados-deles para-a-tribo-de Dã dois e-sessenta mil e-sete centenas');
INSERT INTO verses VALUES (3645, 4, 1, 40, 'a-filhos-de que gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3646, 4, 1, 41, 'contados-deles para-a-tribo-de que um e-quarenta mil e-cinco centenas');
INSERT INTO verses VALUES (3647, 4, 1, 42, 'filhos-de Naftali gerações-deles para-famílias-deles para-casa-de pais-deles em-número-de nomes de-filho-de vinte ano e-para-cima todo sai exército');
INSERT INTO verses VALUES (3648, 4, 1, 43, 'contados-deles para-a-tribo-de Naftali três e-cinquenta mil e-quatro centenas');
INSERT INTO verses VALUES (3649, 4, 1, 44, 'Estas os-contados que contou Moisés e-Aarão e-príncipes-de Israel dois dez homem homem um para-casa-de pais-dele eram');
INSERT INTO verses VALUES (3650, 4, 1, 45, 'e-foram todo contados-de filhos-de Israel para-casa-de pais-deles de-filho-de vinte ano exército todo saindo exército em-Israel');
INSERT INTO verses VALUES (3651, 4, 1, 46, 'e-foram todo os-contados seis-de centenas mil e-três-de milhares e-cinco centenas e-cinquenta');
INSERT INTO verses VALUES (3652, 4, 1, 47, 'e-os-levitas para-a-tribo-de pais-deles não foram-contados em-meio-de-eles');
INSERT INTO verses VALUES (3653, 4, 1, 48, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3654, 4, 1, 49, 'porém a tribo-de não não contarás não cabeças-deles no-meio-de levantarás em-meio-de filhos-de Israel');
INSERT INTO verses VALUES (3655, 4, 1, 50, 'e-tu designa a os-levitas sobre tabernáculo-de o-testemunho e-sobre todo utensílios-dele e-sobre todo que para-ele eles levarão a o-tabernáculo e-a todo utensílios-dele e-eles servirão-o e-ao-redor para-o-tabernáculo acamparão');
INSERT INTO verses VALUES (3656, 4, 1, 51, 'e-quando-partir o-tabernáculo descerão ele os-levitas e-quando-acampar o-tabernáculo levantarão ele os-levitas e-o-estranho o-que-se-aproxima será-morto');
INSERT INTO verses VALUES (3657, 4, 1, 52, 'e-acamparão filhos-de Israel homem sobre acampamento-dele e-homem sobre estandarte-dele para-exércitos-deles');
INSERT INTO verses VALUES (3658, 4, 1, 53, 'e-os-levitas acamparão ao-redor para-tabernáculo-de o-testemunho e-não será ira sobre congregação-de filhos-de Israel e-guardarão os-levitas a guarda-de tabernáculo-de o-testemunho');
INSERT INTO verses VALUES (3659, 4, 1, 54, 'e-fizeram filhos-de Israel conforme-tudo que ordenou yhwh a Moisés assim fizeram');
INSERT INTO chapters VALUES (119, 4, 2, 34);
INSERT INTO verses VALUES (3660, 4, 2, 1, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (3661, 4, 2, 2, 'homem sobre estandarte-dele com-sinais para-casa-de pais-deles acamparão filhos-de Israel defronte ao-redor para-tenda-de encontro acamparão');
INSERT INTO verses VALUES (3662, 4, 2, 3, 'e-os-que-acampam oriente para-o-nascente estandarte-de acampamento-de יְהוּדָה para-exércitos-deles e-príncipe-de a-filhos-de יְהוּדָה נַחְשׁוֹן filho-de Aminadabe');
INSERT INTO verses VALUES (3663, 4, 2, 4, 'e-exército-dele e-contados-deles quatro e-setenta mil e-seis centenas');
INSERT INTO verses VALUES (3664, 4, 2, 5, 'e-os-que-acampam sobre-ele tribo-de Issacar e-príncipe-de a-filhos-de Issacar נְתַנְאֵל filho-de צוּעָר');
INSERT INTO verses VALUES (3665, 4, 2, 6, 'e-exército-dele e-contados-dele quatro e-cinquenta mil e-quatro centenas');
INSERT INTO verses VALUES (3666, 4, 2, 7, 'tribo-de זְבוּלֻן e-príncipe-de a-filhos-de זְבוּלֻן אֱלִיאָב filho-de חֵלֹן');
INSERT INTO verses VALUES (3667, 4, 2, 8, 'e-exército-de-ele e-contados-de-ele sete e-cinquenta mil e-quatro centenas');
INSERT INTO verses VALUES (3668, 4, 2, 9, 'todo os-contados para-acampamento-de Judá centena-de mil e-oitenta mil e-seis-de milhares e-quatro-de centenas para-exércitos-de-eles primeira eles-partirão');
INSERT INTO verses VALUES (3669, 4, 2, 10, 'estandarte-de acampamento-de Rúben para-o-sul para-exércitos-de-eles e-príncipe-de a-filhos-de Rúben Elizur filho-de Sedeur');
INSERT INTO verses VALUES (3670, 4, 2, 11, 'e-exército-de-ele e-contados-de-ele seis e-quarenta mil e-cinco centenas');
INSERT INTO verses VALUES (3671, 4, 2, 12, 'e-os-campistas sobre-ele tribo-de Simeão e-príncipe-de a-filhos-de Simeão Selumiel filho-de Zuri Shaddai');
INSERT INTO verses VALUES (3672, 4, 2, 13, 'e-exército-de-ele e-contados-de-eles nove e-cinquenta mil e-três centenas');
INSERT INTO verses VALUES (3673, 4, 2, 14, 'e-tribo-de Gade e-príncipe-de a-filhos-de Gade Eliasafe filho-de Reuel');
INSERT INTO verses VALUES (3674, 4, 2, 15, 'e-exército-de-ele e-contados-de-eles cinco e-quarenta mil e-seis centenas e-cinquenta');
INSERT INTO verses VALUES (3675, 4, 2, 16, 'todo os-contados para-acampamento-de Rúben centena-de mil e-um e-cinquenta mil e-quatro-de centenas e-cinquenta para-exércitos-de-eles e-do-dois eles-partirão');
INSERT INTO verses VALUES (3676, 4, 2, 17, 'e-partirá tenda-de encontro acampamento-de no-meio-de em-meio-de os-lugares-de-acampamento como-que eles-acamparão assim eles-partirão homem sobre mão-sua para-estandartes-de-eles');
INSERT INTO verses VALUES (3677, 4, 2, 18, 'estandarte-de acampamento-de Efraim para-exércitos-de-eles para-o-mar e-príncipe-de a-filhos-de Efraim Elisama filho-de Amiúde');
INSERT INTO verses VALUES (3678, 4, 2, 19, 'e-exército-de-ele e-contados-de-eles quarenta mil e-cinco centenas');
INSERT INTO verses VALUES (3679, 4, 2, 20, 'e-sobre-ele tribo-de Manassés e-príncipe-de a-filhos-de Manassés Gamaliel filho-de Pedazur');
INSERT INTO verses VALUES (3680, 4, 2, 21, 'e-exército-de-ele e-contados-de-eles dois e-trinta mil e-duzentos');
INSERT INTO verses VALUES (3681, 4, 2, 22, 'e-tribo-de Binyamin e-príncipe-de a-filhos-de Binyamin Abidan filho-de Gideoni');
INSERT INTO verses VALUES (3682, 4, 2, 23, 'e-exército-dele e-contados-deles cinco e-trinta mil e-quatro centenas');
INSERT INTO verses VALUES (3683, 4, 2, 24, 'todo os-contados para-acampamento-de Efrayim cem mil e-oito-de milhares e-cem para-exércitos-deles e-terceiros eles-partirão');
INSERT INTO verses VALUES (3684, 4, 2, 25, 'estandarte-de acampamento-de Dan ao-norte para-exércitos-deles e-príncipe-de a-filhos-de Dan Ahiezer filho-de Amisadai');
INSERT INTO verses VALUES (3685, 4, 2, 26, 'e-exército-dele e-contados-deles dois e-sessenta mil e-sete centenas');
INSERT INTO verses VALUES (3686, 4, 2, 27, 'e-os-acampados sobre-ele tribo-de que e-príncipe-de a-filhos-de que Pagiel filho-de Ocran');
INSERT INTO verses VALUES (3687, 4, 2, 28, 'e-exército-dele e-contados-deles um e-quarenta mil e-cinco centenas');
INSERT INTO verses VALUES (3688, 4, 2, 29, 'e-tribo-de Naftali e-príncipe-de a-filhos-de Naftali Ahira filho-de Einan');
INSERT INTO verses VALUES (3689, 4, 2, 30, 'e-exército-dele e-contados-deles três e-cinquenta mil e-quatro centenas');
INSERT INTO verses VALUES (3690, 4, 2, 31, 'todo os-contados para-acampamento-de Dan cem mil e-sete e-cinquenta mil e-seis centenas por-último partirão segundo-estandartes-deles');
INSERT INTO verses VALUES (3691, 4, 2, 32, 'Estas contados-de filhos-de Israel para-casa-de pais-deles todo contados-de os-acampamentos para-exércitos-deles seis-de centenas mil e-três-de milhares e-cinco centenas e-cinquenta');
INSERT INTO verses VALUES (3692, 4, 2, 33, 'e-os-levitas não foram-contados no-meio-de filhos-de Israel como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (3693, 4, 2, 34, 'e-eles-fizeram filhos-de Israel conforme-tudo que yhwh yhwh a Moisés assim acamparam segundo-estandartes-deles e-assim partiram homem segundo-famílias-dele sobre casa pais-dele');
INSERT INTO chapters VALUES (120, 4, 3, 51);
INSERT INTO verses VALUES (3694, 4, 3, 1, 'e-estes gerações-de Aharon e-Mosheh em-dia-de palavra yhwh a Moisés em-monte-de Sinai');
INSERT INTO verses VALUES (3695, 4, 3, 2, 'e-estes nomes-de filhos-de Aharon o-primogênito Nadab e-Abihu Elazar e-Itamar');
INSERT INTO verses VALUES (3696, 4, 3, 3, 'Estas nomes-de filhos-de Arão os-sacerdotes os-ungidos que enchei mão-deles para-servir-como-sacerdote');
INSERT INTO verses VALUES (3697, 4, 3, 4, 'E-morreu Nadabe e-Abiú diante-de yhwh em-o-aproximar-deles fogo estranho diante-de yhwh em-deserto-de Sinai e-filhos não a-eles para-eles e-serviu-como-sacerdote Eleazar e-Itamar sobre face-de Aarão pai-deles');
INSERT INTO verses VALUES (3698, 4, 3, 5, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3699, 4, 3, 6, 'aproxima a tribo-de Levi ele a-ele diante-de Aarão o-sacerdote ele a-ele');
INSERT INTO verses VALUES (3700, 4, 3, 7, 'e-guardarão a guarda-dele e-a guarda-de todo a-congregação para-lavrar tenda de-encontro para-servir a serviço-de o-tabernáculo');
INSERT INTO verses VALUES (3701, 4, 3, 8, 'e-guardarão את- todo utensílios-de tenda encontro e-a para-lavrar filhos-de Israel para-servir a serviço-de o-tabernáculo');
INSERT INTO verses VALUES (3702, 4, 3, 9, 'e-darás a os-levitas para-Aarão e para filhos-seus dados dados a-ele a-ele de-com filhos-de Israel');
INSERT INTO verses VALUES (3703, 4, 3, 10, 'e-a אַהֲרֹן e-a filhos-dele designarás e-guardarão a sacerdócio-deles e-o-estranho o-que-se-aproxima será-morto');
INSERT INTO verses VALUES (3704, 4, 3, 11, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3705, 4, 3, 12, 'e-eu eis tomei a os-levitas de-meio-de filhos-de debaixo em-lugar-de todo primogênito que-abre ventre e-sejam Israel e-serão para-mim os-levitas');
INSERT INTO verses VALUES (3706, 4, 3, 13, 'que para-mim todo primogênito em-dia ferir-eu todo primogênito na-terra Egito santifiquei para-mim todo primogênito em-Israel de-homem até yhwh para-mim serão eu yhwh');
INSERT INTO verses VALUES (3707, 4, 3, 14, 'e-falou yhwh a Moisés em-deserto-de dizendo para-dizer');
INSERT INTO verses VALUES (3708, 4, 3, 15, 'conta a filhos-de Levi segundo-casa-de pais-deles segundo-famílias-deles todo macho de-filho-de novo e-para-cima contarás-eles');
INSERT INTO verses VALUES (3709, 4, 3, 16, 'e-contou eles Moisés sobre yhwh yhwh como foi-ordenado');
INSERT INTO verses VALUES (3710, 4, 3, 17, 'e-foram estes filhos-de Levi em-nomes-deles Gérson e-Coate e-Merari');
INSERT INTO verses VALUES (3711, 4, 3, 18, 'e-estes nomes-de filhos-de Gérson segundo-famílias-deles Libni e-Simei');
INSERT INTO verses VALUES (3712, 4, 3, 19, 'e-filhos-de Coate segundo-famílias-deles Anrão e-Izar Hebrom e-Uziel');
INSERT INTO verses VALUES (3713, 4, 3, 20, 'e-filhos-de Merari para-famílias-deles Mahli e-Mushi Estas eles famílias-de o-levita para-casa-de pais-seus');
INSERT INTO verses VALUES (3714, 4, 3, 21, 'para-Gershom família-de o-libnita e-família-de o-shimeíta Estas eles famílias-de o-gershonita');
INSERT INTO verses VALUES (3715, 4, 3, 22, 'contados-seus em-número-de todo macho de-filho-de novo e-para-cima contados-seus sete dois-mil e-cinco centenas');
INSERT INTO verses VALUES (3716, 4, 3, 23, 'famílias-de o-gershonita atrás-de o-tabernáculo acamparão para-o-mar');
INSERT INTO verses VALUES (3717, 4, 3, 24, 'e-príncipe-de casa-de pai para-o-gershonita Eliasafe filho-de Lael');
INSERT INTO verses VALUES (3718, 4, 3, 25, 'e-guarda-de filhos-de Gershom em-tenda-de encontro o-tabernáculo e-a-tenda cobertura-sua e-cortina-de entrada-de tenda-de encontro');
INSERT INTO verses VALUES (3719, 4, 3, 26, 'e-cortinas-de o-pátio e-a cortina-de entrada-de o-pátio que sobre o-tabernáculo e-sobre o-altar a-todo e-את cordas-suas para-todo serviço-seu');
INSERT INTO verses VALUES (3720, 4, 3, 27, 'e-para-Coate família-de o-amramita e-família-de o-izharita e-família-de o-hebronita e-família-de o-uzielita Estas eles famílias-de o-coatita');
INSERT INTO verses VALUES (3721, 4, 3, 28, 'em-número-de todo macho de-filho-de novo e-para-cima oito-de milhares e-seis centenas guardadores-de guarda-de o-santuário');
INSERT INTO verses VALUES (3722, 4, 3, 29, 'famílias-de filhos-de Coate sobre sobre lado-de o-tabernáculo sul');
INSERT INTO verses VALUES (3723, 4, 3, 30, 'e-príncipe-de casa-de pai para-famílias-de o-coatita Elizafã filho-de Uziel');
INSERT INTO verses VALUES (3724, 4, 3, 31, 'e-guarda-sua a-arca e-a-mesa e-o-candelabro e-os-altares e-utensílios-de o-santuário que servirão com-eles e-a-cortina e-tudo serviço-seu');
INSERT INTO verses VALUES (3725, 4, 3, 32, 'e-príncipe-de príncipes-de o-levita Eleazar filho-de Aarão o-sacerdote supervisão-de guardadores-de guarda-de o-santuário');
INSERT INTO verses VALUES (3726, 4, 3, 33, 'para-Merari família-de o-Mahli e-família-de o-Mushi Estas eles famílias-de Merari');
INSERT INTO verses VALUES (3727, 4, 3, 34, 'e-contados-deles em-número-de todo macho de-filho-de novo e-para-cima seis-de milhares e-duzentos');
INSERT INTO verses VALUES (3728, 4, 3, 35, 'e-príncipe-de casa-de pai para-famílias-de Merari Zuriel sobre Abiail sobre lado-de o-tabernáculo acamparão norte-para');
INSERT INTO verses VALUES (3729, 4, 3, 36, 'e-contagem-de de-serviço filhos-de amargura pratos-de-ferro o-tabernáculo e-suas-asas e-seus-pilares e-os-seus-mestres e-todo e-tudo e-todo serviço-seu');
INSERT INTO verses VALUES (3730, 4, 3, 37, 'e-as-colunas-de o-courim ao-redor e-os-seus-mestres e-as-suas-estacas e-dos-seus-cordões');
INSERT INTO verses VALUES (3731, 4, 3, 38, 'e-os-acampados diante-de o-tenda oriente em-frente-de-a tenda-de a-reunião do-leste Moshê e-Aharôn e-seus-filhos guardando de-guarda do-santuário para-de-guarda filhos-de Israel e-o-estranho o-que-se-aproxima será-morto');
INSERT INTO verses VALUES (3732, 4, 3, 39, 'todo de-contados dos-Levitas que contou Moisés sobre yhwh yhwh segundo-famílias-deles todo macho de-filho-de novo e-para-cima dois e-vinte mil');
INSERT INTO verses VALUES (3733, 4, 3, 40, 'E-disse yhwh a Moisés ordena macho primogênito macho aos-filhos-de Israel de-filho-de novo e-para-cima e-leve a número nomes-deles');
INSERT INTO verses VALUES (3734, 4, 3, 41, 'e-tomará a os-leviata a-mim yhwh debaixo debaixo-de todo primogênito filhos-de Israel e-את debaixo os-levitas em-lugar-de todo primogênito em-animais filhos-de Israel');
INSERT INTO verses VALUES (3735, 4, 3, 42, 'e-ele-contou Moisés como ordenou yhwh ele a todo em-primeiro de-filhos Israel');
INSERT INTO verses VALUES (3736, 4, 3, 43, 'e-houve todo macho macho em-número nomes de-filho-de novo e-para-cima para-seus-contados dois e-vinte mil três e-setenta e-duzentos');
INSERT INTO verses VALUES (3737, 4, 3, 44, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3738, 4, 3, 45, 'toma a debaixo em-lugar-de todo primogênito de-filhos Israel debaixo besta-m os-levitas em-lugar-de behemt-am yhwh para-mim os-levitas eu yhwh');
INSERT INTO verses VALUES (3739, 4, 3, 46, 'e-את peduy-ei ha-shlosha ve-ha-shbeim ve-hama-tayim ha-odfim sobre os-levitas me-bchor filhos-de Israel');
INSERT INTO verses VALUES (3740, 4, 3, 47, 've-laqacht-a hameshet cinco-vezes escalam para-o-cranio em-sheqel a-santidade tomarás vinte gume-da o-escalam:');
INSERT INTO verses VALUES (3741, 4, 3, 48, 'e-darás a-prata para-Aarão e para filhos-seus ransomados os-excedentes neles');
INSERT INTO verses VALUES (3742, 4, 3, 49, 'E-tomou Moisés a prata o-resgate de-com os-sobras sobre resgatados-de os-levitas');
INSERT INTO verses VALUES (3743, 4, 3, 50, 'de-a primogênito filhos-de Israel tomou a o-prata cinco e sessenta e-três de-cem e-um-mil na-unidade-de-prata o-santuário');
INSERT INTO verses VALUES (3744, 4, 3, 51, 'E-colocou Moisés a prata os-redimidos para-Aaron e-para-seus-filhos yhwh boca-de yhwh yhwh ordenou yhwh a Moisés');
INSERT INTO chapters VALUES (121, 4, 4, 49);
INSERT INTO verses VALUES (3745, 4, 4, 1, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (3746, 4, 4, 2, 'levante a cabeça filhos-de Qehat de-meio-de filhos-de Levi para-famílias-deles segundo-casa-de pais-seus');
INSERT INTO verses VALUES (3747, 4, 4, 3, 'de-filho-de trinta ano e-para-cima e-até filho-de cinquenta ano todo veio obra para-fazer trabalho em-tenda encontro');
INSERT INTO verses VALUES (3748, 4, 4, 4, 'esta serviço-de filhos-de Coate em-tenda-de de-encontro santidade os-santos');
INSERT INTO verses VALUES (3749, 4, 4, 5, 'e-ele-veio אַהֲרֹן e-filhos-dele quando-partir o-acampamento e-desçam a parokhet ha-masakh e-kis-u- nela a aron ha-edut:');
INSERT INTO verses VALUES (3750, 4, 4, 6, 've-natenu sobre-ele kisui- pele takhash u-parshu beged- perfeito azul-violeta de-acima e-colocaram em-os-seus');
INSERT INTO verses VALUES (3751, 4, 4, 7, 'e-sobre mesa o-das-faces desplorem roupa azul-violeta e-darão em-ele a as-tigelas e-a os-pratos e-a das-mangueiras e-a dureza do-sacrifício e-pão será sobre-ele será');
INSERT INTO verses VALUES (3752, 4, 4, 8, 'e-espalharão em-eles roupa carne-carnuda segundo e-vestirão ele em-o-manto pele de-tachash e-colocarão a em-seus-dobradiças');
INSERT INTO verses VALUES (3753, 4, 4, 9, 'e-tomarão manto azul e-cobrirem a de-a-menora o-luzeiro e-a luzes-deiha e-a pratos-deiha e-a vasos-de-fogo-deiha e-את todo instrumentos-de oito que servirão-a para-ela neles');
INSERT INTO verses VALUES (3754, 4, 4, 10, 'e-darão a-ela e-a todo pele a cobertura pele de-tachash e-dêem sobre o-mato');
INSERT INTO verses VALUES (3755, 4, 4, 11, 'e-sobre-o altar-de o-ouro o-ouro roupa tecelagem-azul e-cobrirão a-ele ele pele pele e-colocarão a em-o-seu');
INSERT INTO verses VALUES (3756, 4, 4, 12, 'e-eles-tomaram a todo os-ferramentas-de-serviço da-serviço que servirão-em neles no-santo e-eles-darão a um-vestido pele e-eles-cobrirão a-eles com-a-capinha pele de-tachash e-dêem sobre o-mato');
INSERT INTO verses VALUES (3757, 4, 4, 13, 'e-dele-estavam-limpando a o-altar e-espalharão sobre-ele biged púrpura');
INSERT INTO verses VALUES (3758, 4, 4, 14, 've-natenu em-ele a todo seus-vessōis que servirém sobre-ele em-eles a as-vassouras a os-escrivanões e-a os-penitentes e-a as-alâbadas pele utensílios-de o-altar e-espalharém sobre-ele coberto pele Tachash e-os-colocaram em-o-sobre-ele-verso');
INSERT INTO verses VALUES (3759, 4, 4, 15, 'e-terminou Aharon- e-filhos-dele para-cobrir a o-santo e-a todo utensílios-de o-santo em-a-partida do-lageramento e-depois-de assim venham Estas Qehath- le-saet e-não yiggu a o-santo va-metu estes massa- filhos-de Coate be-ohele encontro');
INSERT INTO verses VALUES (3760, 4, 4, 16, 'u-fqudat Elazar- filho-de Aarão o-sacerdote shemen o-luzeiro u-qatoreth o-sabão e-oferta a-perpétua e-óleo a-unção de-a-conta todo o-tabernáculo e-todo que nele no-sagrado e-no-seus-vesséis');
INSERT INTO verses VALUES (3761, 4, 4, 17, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (3762, 4, 4, 18, 'a você-quebrará a shevet mishpachot o-coatita mitoch os-levitas');
INSERT INTO verses VALUES (3763, 4, 4, 19, 've-zot asu para-ela-os a-eles e-não yamutu begishatam a santo-de ha-kodashim אַהֲרֹן e-filhos-dele yavo-u veshumu aqueles-o homem homem sobre serviço-seu e-a levantamento-seu');
INSERT INTO verses VALUES (3764, 4, 4, 20, 'e-não para-ver para-ver de-abelha a o-santo e-morreram');
INSERT INTO verses VALUES (3765, 4, 4, 21, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3766, 4, 4, 22, 'levantar a cabeça filhos-de Gérson também eles segundo-casa-de pais-deles para-famílias-deles');
INSERT INTO verses VALUES (3767, 4, 4, 23, 'de-filho trinta ano e-para-cima até filho-de cinquenta ano ordene eles todo exército para-lavrar exército para-trabalhar serviço em-tenda encontro');
INSERT INTO verses VALUES (3768, 4, 4, 24, 'esta trabalho-de famílias-de o-gershonita para-lavrar e-para-levar');
INSERT INTO verses VALUES (3769, 4, 4, 25, 'e-eles-levarão a tendas-de o-tabernáculo e-a tenda encontro cobertura-sua e-tampa o-couro-de-animais-marinhos que sobre-ele de-acima e- cobertura entrada-de tenda-de encontro');
INSERT INTO verses VALUES (3770, 4, 4, 26, 'e-את calais o-haçatsér e-a masakh- petakh- portão haçaçér que sobre ham-mishkán e-sobre o-altar ao-redor e-את meitreyhem e-com tudo-de kléi- avodatam a-eles todo que ele-será-feito a-eles ve-avádu');
INSERT INTO verses VALUES (3771, 4, 4, 27, 'sobre de-mim Arão e-seus-filhos ser-ás todo serviço-dele filhos-de o-gershuni para-todo carga-deles e-a-todos serviço-deles e-vigiar-eis de-elas em-serviço a todo levamento-deles');
INSERT INTO verses VALUES (3772, 4, 4, 28, 'esta serviço-da famílias-das filhos-de o-gersonita em-tenda-de de-encontro e-de-sua-guarda em-mão-de aitamar filho-de אַהֲרֹן o-sacerdote');
INSERT INTO verses VALUES (3773, 4, 4, 29, 'filhos-de de-melancolia para-famílias-das-deles para-casa-de pais-deles eles a-eles');
INSERT INTO verses VALUES (3774, 4, 4, 30, 'do-filho trinta ano e-ma''aláh ve-ad filho-de cinquenta ano tipqdem todo para-lavrar la-tzava la-avod a avodat tenda-de encontro');
INSERT INTO verses VALUES (3775, 4, 4, 31, 've-zot mishmeret masa''am para-todo avodatam em-tenda-de reunião pratos-de-ferro o-tabernáculo e-suas-asas e-seus-pilares e-dele-eram-mestres');
INSERT INTO verses VALUES (3776, 4, 4, 32, 'e seus pilares o-hatzéэр em volta e seus anciãos e suas testemunhas e seus herdeiros para-todo utensílios-deles e-a-tudo a-obra-deles e-no-nomes voces-contareis a os-utensilios-de guarda-de de-a-sua-carga');
INSERT INTO verses VALUES (3777, 4, 4, 33, 'esta a-obra-de das-familias filhos-de Merari para-todo a-obra-deles em-tenda-de de-encontro em-mão-de Ithamar filho-de אַהֲרֹן o-sacerdote');
INSERT INTO verses VALUES (3778, 4, 4, 34, 'e-ele-fiscalizou Moisés e-Aharon e-príncipes-de a-congregação a filhos-de o-coatita para-famílias-deles e-para-a-casa-de pais-seus');
INSERT INTO verses VALUES (3779, 4, 4, 35, 'de-filho-de trinta ano e-para-cima e-até filho-de cinquenta ano todo o-vindo para-o-exército para-a-obra em-a-tenda-de encontro');
INSERT INTO verses VALUES (3780, 4, 4, 36, 'e-foram de-sua-fiscalização segundo-famílias-deles dois-mil sete centenas e-cinquenta');
INSERT INTO verses VALUES (3781, 4, 4, 37, 'Estas fiscalizações famílias o-qehathi todo o-que-serva em-tenda-de de-encontro que contou Moisés e-Aarão yhwh de-seu yhwh por-mão-de Moisés');
INSERT INTO verses VALUES (3782, 4, 4, 38, 'e-contados-de filhos-de gerson para-famílias-deles e-para-casa pais-seus');
INSERT INTO verses VALUES (3783, 4, 4, 39, 'de-filho-de trinta ano e-para-cima e-até filho-de cinquenta ano todo o-vindo la-tzava para-a-obra em-tenda encontro');
INSERT INTO verses VALUES (3784, 4, 4, 40, 'e-foram contados-seus para-famílias-deles para-casa-de pais-deles dois-mil e-seis centenas e-trinta');
INSERT INTO verses VALUES (3785, 4, 4, 41, 'Estas os-contados-de das-familias filhos-de Gerson todo o-que-serva em-tenda-de de-encontro que pakad Moisés e-Aarão yhwh de-seu yhwh');
INSERT INTO verses VALUES (3786, 4, 4, 42, 'e que foram contados famílias-de filhos-de Merari para-famílias-deles segundo-casa-de pais-seus');
INSERT INTO verses VALUES (3787, 4, 4, 43, 'de-filho-de trinta ano e-para-cima e-até filho-de cinquenta ano todo o-que-vem para-o-exército para-a-trabalho em-a-tenda encontro');
INSERT INTO verses VALUES (3788, 4, 4, 44, 'e-foram de-seus-contados segundo-famílias-deles três dois-mil e-duzentos');
INSERT INTO verses VALUES (3789, 4, 4, 45, 'Estas contados-de famílias-de filhos-de do-amargura que contou Moisés e-Aarão sobre yhwh yhwh por-mão-de Moisés');
INSERT INTO verses VALUES (3790, 4, 4, 46, 'todo os-contados que contou Moisés e-Aharon e-príncipes Israel a os-levitas para-famílias-deles e-a-casa-de pais-seus');
INSERT INTO verses VALUES (3791, 4, 4, 47, 'de-filho-de trinta ano e-para-cima e-até filho-de cinquenta ano para-lavrar o-que-vem para-o-laborar de-laborar trabalho e-de-laborar profecia em-a-tenda encontro');
INSERT INTO verses VALUES (3792, 4, 4, 48, 'e-foram de-sua-visitação oito milhares e-cinco centenas e-oitenta');
INSERT INTO verses VALUES (3793, 4, 4, 49, 'sobre yhwh yhwh visitou a-eles em-a-mão Moisés homem homem sobre de-sua-obra e-sobre yhwh e-seus-enviados que ordenou yhwh a Moisés');
INSERT INTO chapters VALUES (122, 4, 5, 31);
INSERT INTO verses VALUES (3794, 4, 5, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3795, 4, 5, 2, 'ordene a filhos-de Israel e-eles-enviem de o-acampamento e-tudo leproso e-todo fluxo e-todo impuro para-a-alma');
INSERT INTO verses VALUES (3796, 4, 5, 3, 'do-masculino até fêmea envi-a-los a de-fora para-o-acampamento envia-os e-não tornar-se-ão-imundos a de-seus-acampamentos que eu morando em-meio-de-eles');
INSERT INTO verses VALUES (3797, 4, 5, 4, 'e-ele-fizeram- assim filhos-de Israel e-eles-enviaram a-eles a fora-de para-o-lager yhwh palavra yhwh a Moisés assim fizeram filhos-de Israel');
INSERT INTO verses VALUES (3798, 4, 5, 5, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3799, 4, 5, 6, 'palavra a filhos-de Israel homem que mulher porque o-homem de-todo pecados o-homem para-desonrar ofensa aquela e-ashmá a-alma ha-híu');
INSERT INTO verses VALUES (3800, 4, 5, 7, 've-hitvaddú a chatátaém que asú e-pagava a ashamó com-no-cabeça-seu va-chamishíto adicionará sobre-ele e-dará a-ele ashám a-ele');
INSERT INTO verses VALUES (3801, 4, 5, 8, 'e-se ein la-éish גּוֹיֶל para restituir a-ele para-ele o pecado o-mushab a-yhwh para-o-sacerdote apenas ovelha as-cuprirem que yechaper- nele sobre-ele');
INSERT INTO verses VALUES (3802, 4, 5, 9, 'e-todo terumah para-todo santos filhos-de a-ele será yakrivu para-o-sacerdote para-ele será');
INSERT INTO verses VALUES (3803, 4, 5, 10, 'e-homem a a-ele a-ele sejam homem que a-ele será para-ele será');
INSERT INTO verses VALUES (3804, 4, 5, 11, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3805, 4, 5, 12, 'palavra a filhos-de Israel e-dirás a-eles homem homem porque torne-se-estúpida nele e-ofenderá em-ele acima');
INSERT INTO verses VALUES (3806, 4, 5, 13, 'e-deite homem ela-a deito-de- semente e-se-esconda das-olhos marido-dela e-se-oculta e-ela ficou-imunda e-testemunha não-há em-ela não não foi-apanhada');
INSERT INTO verses VALUES (3807, 4, 5, 14, 'e-passou sobre-ele espírito-de ciúme e-ciumento a mulher-sua e-ela ficou-imunda ou passou sobre-o espírito-de não e-ciumento a mulher-dele e-ela não ficou-imunda-verso-final');
INSERT INTO verses VALUES (3808, 4, 5, 15, 'e-trará o-homem a sua-mulher a o-sacerdote e-ele-trouxe a seu-oferta-sua sobre-ela décima-parte a-árvore qemakh em-semente-de-cevada não ele-derramará sobre-ele óleo e-não ele sobre-ele de-bálsamo porque oferta-estrituária-de de-zelo ele oferenda-de zicaron mazchoret avon');
INSERT INTO verses VALUES (3809, 4, 5, 16, 've-hikrib a-ela o-sacerdote ve-heemidah diante-de yhwh');
INSERT INTO verses VALUES (3810, 4, 5, 17, 'e-tome o-sacerdote águas kedoshim bikli- charesh e-de será que yihye bekarka o-tabernáculo ele-tomará o-sacerdote e colocou a as-águas');
INSERT INTO verses VALUES (3811, 4, 5, 18, 'e-ele-estabeleceu o-sacerdote a a-mulher yhwh yhwh e-desfez a cabeça a-mulher e-dava sobre de-seus-mãos a de-mincha ela oferenda-de ciúmes ela e-com-a-mão-de o-sacerdote serão águas-de de-que-sabem os-amaldiçoados');
INSERT INTO verses VALUES (3812, 4, 5, 19, 'e-jurou ela o-sacerdote e-disse a a-mulher se não deitar-se homem a-te e-se debaixo costura impureza em-lugar-de homem-teu puro-eu de-a-gua os-amargos os-malditos as estas');
INSERT INTO verses VALUES (3813, 4, 5, 20, 'e-você que costura debaixo homem-teu e-porque se-tornou-impuro E-colocou homem sobre-ti a deitamento-seu de-modo-a-partir-de homem-teu:');
INSERT INTO verses VALUES (3814, 4, 5, 21, 'e-jurou-o o-sacerdote a a-mulher-a em-juramento a-cura e-disse o-sacerdote a-mulher yhwh yhwh te-a para-o-sopro no-meio-de em-meio-de povo-teu yhwh yhwh a joelho-teu caindo e-a ventre-teu exército-verso-final');
INSERT INTO verses VALUES (3815, 4, 5, 22, 'e-entraram as-águas os-maldizentes estes em-o-intestino-teu para-gerir ventre e-para-cair joelho-teu e-diga a-mulher amém amém');
INSERT INTO verses VALUES (3816, 4, 5, 23, 'e-escrita-faz a as-maldições os-estes o-sacerdote be-sefer u-machah a águas-de ha-marim');
INSERT INTO verses VALUES (3817, 4, 5, 24, 've-hishkaha a a-mulher a águas-de de-que-sabem os que amarrem u-ba''u bah as-águas os-malditos para-os-malvados-verso-final');
INSERT INTO verses VALUES (3818, 4, 5, 25, 'e-tome o-sacerdote de-mão-de a-mulher a de-mincha as-irritações e-ele-spritzou a a-oferenda yhwh yhwh e-ele-aproximou a-ela a o-altar');
INSERT INTO verses VALUES (3819, 4, 5, 26, 'e pegou-punhado o-sacerdote de a-oferenda a memorial-dela e fez-fumaça o altar-para e-depois ele-fará-beber a a-mulher a as-águas');
INSERT INTO verses VALUES (3820, 4, 5, 27, 've-hishkah-h a as-águas e-será se ficará-imunda e-ela-se-contorceu em-alto em-a-mulher-seu e-entraram na-ela as-águas os-maldizentes para-os-inimigos e-plantou-seu na-barriga-dele e-caiu a-perna-seu e-será a-mulher para-a-maldição em-meio-de a-sua-pena;');
INSERT INTO verses VALUES (3821, 4, 5, 28, 'e-se não e-se-tornou-impura a-mulher ela ela e-será-lavada e-semeará semente');
INSERT INTO verses VALUES (3822, 4, 5, 29, 'esta lei-de as-ciúmes que se-perderá mulher debaixo espos-a e-tornar-se-á-impura;');
INSERT INTO verses VALUES (3823, 4, 5, 30, 'ou homem que passará sobre-ele espírito ciúme e-quenear a mulher-sua e-estabelecer a yhwh diante-de yhwh e-fará a-ela o-sacerdote a todo a-torah a esta');
INSERT INTO verses VALUES (3824, 4, 5, 31, 'e-será-purificado o homem de-pecado e-a-mulher aquela carregará a seu-pecado');
INSERT INTO chapters VALUES (123, 4, 6, 27);
INSERT INTO verses VALUES (3825, 4, 6, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3826, 4, 6, 2, 'palavra a filhos-de Israel e-dirás a-eles homem que mulher porque maravilhará para-o-dar neder nazir para-o-sacrificar-com-erva para-יהוה');
INSERT INTO verses VALUES (3827, 4, 6, 3, 'de-vinho e-escorume faz-sacrifício fermento vinho e-fermento bebida não beberá e-todo serviço não não beberá e-úvas pãoes não não comerá');
INSERT INTO verses VALUES (3828, 4, 6, 4, 'todo dias-de sua-cabeleira de-toda que ser-ará da-videira o-vinho de-a-cisterna-superior e-até não não comer');
INSERT INTO verses VALUES (3829, 4, 6, 5, 'todo os-dias neder nisro tesar não passar sobre sua-cabeça até de-enchimento será que yazir para-יהוה santo será cresça desfaça cabelo cabeça-dele');
INSERT INTO verses VALUES (3830, 4, 6, 6, 'todo dias-de seu-sacrifício a-yhwh sobre não morreu não virá');
INSERT INTO verses VALUES (3831, 4, 6, 7, 'para-seu-pai e-para-sua-mãe para-seu-irmão e-a-sua-irmã não a-eles a-eles que porque diadema Elohim-seu sobre cabeça-dele');
INSERT INTO verses VALUES (3832, 4, 6, 8, 'todo dias-de nizro-o santo ele a-yhwh');
INSERT INTO verses VALUES (3833, 4, 6, 9, 'e-quando morra morreu sobre-ele em-patente pateom e-tome cabeça nizro-o e-gilech rosho no-dia no-dia no-dia ha-shevi-i yegallechennu');
INSERT INTO verses VALUES (3834, 4, 6, 10, 'e-no-dia ha-shmini yavi-a duas torim ou segundo filhos-de yonah a o-sacerdote a entrada-de tenda-de encontro');
INSERT INTO verses VALUES (3835, 4, 6, 11, 'e-fará o-sacerdote um le-chatat ve-echad para-oferta e-perdoar sobre-ele do-que pecou sobre a-alma e-santificar no-dia cabeça-sua no-dia a-aquela');
INSERT INTO verses VALUES (3836, 4, 6, 12, 'e-consagrar para-יהוה a dias-de seu-voto e-trará sujeitai filho-de seu-ano para-a-sacrifício e-os-dias que cairão porque impuro nizro:');
INSERT INTO verses VALUES (3837, 4, 6, 13, 'e-esta lei-de ha-nazir em-dia-de melota dias-de nizro yavi ele a entrada-de tenda-de encontro');
INSERT INTO verses VALUES (3838, 4, 6, 14, 'e trouxe-próximo a qorbano la-yhwh sujeitai filho-de um tamim um uma ve-kabshah achat filha-de ano-a perfeita-a para-oferta-de-pecado e-velho- um perfeito para-paz-');
INSERT INTO verses VALUES (3839, 4, 6, 15, 'e-cesto de-maçãs farinha-a pães misturados com-o óleo e biscoitos-de não-fermentados ungidas -com-óleo e-a-oferta-de-levedura e-seu-sacrifício-das-libações');
INSERT INTO verses VALUES (3840, 4, 6, 16, 've-hikrib o-sacerdote diante-de yhwh e fez a pecado-dele e-a sua-oferta-queimada');
INSERT INTO verses VALUES (3841, 4, 6, 17, 'e-a o-touro fará sacrifício holocaustos- sobre sobre cesto das-pães-de-farinha e-fará o-sacerdote a oferta-sua e-a seu-sacrifício-das-libações');
INSERT INTO verses VALUES (3842, 4, 6, 18, 'e-se-barbeará o-nazir entrada-de tenda-de encontro a cabeça e-tome e-levou a cabelo-de-a cabeça nisro vênatan sobre o-fogo que sob sacrifício os-sacrifícios-de-paz');
INSERT INTO verses VALUES (3843, 4, 6, 19, 'e-tome o sacerdote a do-braço cozido-o de o-veado uma pão-azeviche uma de um e-torta-de-espessura massa-sem-aformar um vênatan sobre mãos-de o-nazir depois se-cortou-o-cabelo a nizro:');
INSERT INTO verses VALUES (3844, 4, 6, 20, 'e-ele-levantou-o aqueles o-sacerdote a-oferta-de-levantamento diante-de yhwh yhwh ele ele sobre sobre a-oferta-de-levantamento e-sobre coxa a-sacrifício-de-elevação e-depois yish-teh o-nazireu יָיַן׃');
INSERT INTO verses VALUES (3845, 4, 6, 21, 'esta lei-de o-nazireu que ele-oferecerá oferta-seu a-yhwh sobre nisro fora-de-a sua-mão atingirás sua-mão razão voto-seu que recolherá sobre fazê-lo-á sobre torat nizro:');
INSERT INTO verses VALUES (3846, 4, 6, 22, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3847, 4, 6, 23, 'palavra a Arão dizendo filhos-seus dizendo assim abençoar-vos a a-eles Israel dizer para-eles');
INSERT INTO verses VALUES (3848, 4, 6, 24, 'abençoe-te yhwh e te preservará');
INSERT INTO verses VALUES (3849, 4, 6, 25, 'enxergue yhwh seus rostos a-ti e o consagre');
INSERT INTO verses VALUES (3850, 4, 6, 26, 'yisa yhwh פניו a-ti e puserá a-ti a-ti');
INSERT INTO verses VALUES (3851, 4, 6, 27, 'e-os-colocaram a nome-meu sobre filhos-de Israel e-eu abençoe-os:');
INSERT INTO chapters VALUES (124, 4, 7, 89);
INSERT INTO verses VALUES (3852, 4, 7, 1, 'e-houve em-dia quando-terminarem Moisés para-elevar a o-tabernáculo ele o-ele ele ele e-a todo utensílios-dele e-a eles e-a todo seu recipiente e-os-ungiu e-o-consagrou a-eles');
INSERT INTO verses VALUES (3853, 4, 7, 2, 'e ofereceram-los príncipes-de Israel cabeças de casa pais-deles eles príncipes-de as tribos eles os-que-estavam-de-pé sobre os que foram contados');
INSERT INTO verses VALUES (3854, 4, 7, 3, 'Va''yaví''u a seu sacrifício yhwh yhwh seis-de ovelhas-que-pastam exército e-dois dez manhã roda sobre segundo os-elevados e-boi para um e-deram eles diante-de o-tabernáculo');
INSERT INTO verses VALUES (3855, 4, 7, 4, 'E-disse yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3856, 4, 7, 5, 'pegue deles e-sejam para-lavrar a avodat tenda de-encontro e dará elas a os-levitas homem yhwh serviço-seu');
INSERT INTO verses VALUES (3857, 4, 7, 6, 'E-tomou Moisés a as-rodas E-colocou o-gado E-deu eles a os-levitas');
INSERT INTO verses VALUES (3858, 4, 7, 7, 'com duas as-rodas e-את אַרְבַּ֣עַת o-bovino deu dar gerson כפי serviço-deles');
INSERT INTO verses VALUES (3859, 4, 7, 8, 'e-את quatro as-rodas e-את oito o-bovino deu dar de-melancolia em-o serviço-deles em-mão-de aitamar filho-de אַהֲרֹן o-sacerdote');
INSERT INTO verses VALUES (3860, 4, 7, 9, 'e-aos-filhos-de Coate não deu porque serviço-de a-santidade em-eles no-ombro elevam');
INSERT INTO verses VALUES (3861, 4, 7, 10, 'וַיַּקְרִ֣יבוּ os-nobres a dedicação-de o altar em-dia consagrado-o ele e-elevaram os-nobres a oferta-eles diante-de o-altar');
INSERT INTO verses VALUES (3862, 4, 7, 11, 'E-disse yhwh a Moisés um um para-o-dia um um para-o-dia eles-oferecerão a sua oferta para-a-consagração o-altar');
INSERT INTO verses VALUES (3863, 4, 7, 12, 'e-houve o que oferece no-dia o primeiro a oferenda-sua Nachshon filho-de Amminadav para-matate Judá');
INSERT INTO verses VALUES (3864, 4, 7, 13, 'וְקָרְבָּנ֞וֹ café-da-manhã- uma uma trinta e-cem peso-seu um um prata setenta siclo em-siclo a-santidade dois-eles cheios farinha-fina misturada em-o-óleo para-minha');
INSERT INTO verses VALUES (3865, 4, 7, 14, 'palma uma dez ouro cheia fumo-sacrifício');
INSERT INTO verses VALUES (3866, 4, 7, 15, 'touro um filho-de manhã um um cordeiro- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3867, 4, 7, 16, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3868, 4, 7, 17, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco atadim cinco cordeiros filhos-de ano cinco este oferenda-de Nasom filho-de Aminadabe');
INSERT INTO verses VALUES (3869, 4, 7, 18, 'no-dia o-segundo se-aproximou Netanuel filho-de Tsua príncipe-de Issachar');
INSERT INTO verses VALUES (3870, 4, 7, 19, 'ofereceu a oferta-dele uma prata uma trinta e-cem um lavatório um prata setenta siclo em-siclo a-santidade dois-eles cheios farinha-fina misturada em-o-óleo para-minha-oferta-verso-final');
INSERT INTO verses VALUES (3871, 4, 7, 20, 'palma uma dez ouro cheia fumegante-verso-final');
INSERT INTO verses VALUES (3872, 4, 7, 21, 'touro um filho-de manhã um um cordeiro-de- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3873, 4, 7, 22, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3874, 4, 7, 23, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco עַתּוּדִ֣ים cinco cordeiros filhos-de ano cinco este oferenda-de Netanel filho-de Zuar');
INSERT INTO verses VALUES (3875, 4, 7, 24, 'no-dia o-terceiro príncipe aos-filhos-de Zebulom Eliabe filho-de Helom');
INSERT INTO verses VALUES (3876, 4, 7, 25, 'sua-oferta tigela-de- uma uma trinta e-cem seu-peso um um prata setenta siclo em-siclo a-santidade os-dois cheios farinha-fina misturada em-o-óleo para-minha-oferta-verso-final');
INSERT INTO verses VALUES (3877, 4, 7, 26, 'palma uma dez ouro cheia fumegante-verso-final');
INSERT INTO verses VALUES (3878, 4, 7, 27, 'touro um filho-de manhã um um cordeiro-de- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3879, 4, 7, 28, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3880, 4, 7, 29, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas-de-tordilho cinco cordeiros filhos-de ano cinco este oferenda-de Eliabe filho-de Helom');
INSERT INTO verses VALUES (3881, 4, 7, 30, 'no-dia o-quarto príncipe aos-filhos-de Rúben Elisur filho-de Sedeur');
INSERT INTO verses VALUES (3882, 4, 7, 31, 'sua-oferta tigela-de- uma uma trinta e-cem seu-peso um um prata setenta siclo em-siclo a-santidade os-dois-eles cheios farinha-fina misturada em-o-óleo para-a-manhã');
INSERT INTO verses VALUES (3883, 4, 7, 32, 'palma uma dez ouro cheia incenso');
INSERT INTO verses VALUES (3884, 4, 7, 33, 'touro um filho-de manhã um um cordeiro-de- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3885, 4, 7, 34, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3886, 4, 7, 35, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas-de-tordilho cinco cordeiros filhos-de ano cinco este oferenda-de Elisur filho-de Sedeur');
INSERT INTO verses VALUES (3887, 4, 7, 36, 'no-dia o-quinqués príncipe aos-filhos-de Simeão Shelumiel filho-de Zurisadai');
INSERT INTO verses VALUES (3888, 4, 7, 37, 'oferta-sua tigela-de- uma uma trinta e-cem peso-seu um um prata setenta siclo em-siclo a-santidade dois-eles cheios farinha-fina misturada em-o-óleo para-minha');
INSERT INTO verses VALUES (3889, 4, 7, 38, 'palma uma dez ouro cheia fumo-sagrado');
INSERT INTO verses VALUES (3890, 4, 7, 39, 'touro um filho-de manhã um um cordeiro-de- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3891, 4, 7, 40, 'Seir um um para-pecado');
INSERT INTO verses VALUES (3892, 4, 7, 41, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas cinco cordeiros filhos-de ano cinco este oferenda-de Selumiel filho-de Zurisadai');
INSERT INTO verses VALUES (3893, 4, 7, 42, 'no-dia o-sexto príncipe aos-filhos-de Gade Eliasafe filho-de Deuel');
INSERT INTO verses VALUES (3894, 4, 7, 43, 'קָרְבָּנ֖וֹ prato-de uma uma trinta e-cem מִשְׁקָלָהּ um um prata setenta siclo em-siclo a-santidade שְׁנֵיהֶם cheios farinha-fina misturada em-o-óleo para-oferta');
INSERT INTO verses VALUES (3895, 4, 7, 44, 'palma uma dez ouro cheia incenso');
INSERT INTO verses VALUES (3896, 4, 7, 45, 'touro um filho-de manhã um um kevesh- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3897, 4, 7, 46, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3898, 4, 7, 47, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco atudim cinco cordeiros filhos-de ano cinco este oferenda-de Eliasafe filho-de Deuel');
INSERT INTO verses VALUES (3899, 4, 7, 48, 'no-dia o-sétimo príncipe aos-filhos-de Efraim Elishama filho-de Amiúde');
INSERT INTO verses VALUES (3900, 4, 7, 49, 'qorbano café-da- uma uma trinta e-cem peso-dela um um prata setenta siclo em-siclo a-santidade dois-eles cheios farinha-fina misturada em-o-óleo para-minha');
INSERT INTO verses VALUES (3901, 4, 7, 50, 'palma uma dez ouro cheia fumaça');
INSERT INTO verses VALUES (3902, 4, 7, 51, 'touro um filho-de manhã um um cordeiro- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3903, 4, 7, 52, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3904, 4, 7, 53, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas cinco cordeiros filhos-de ano cinco este oferenda-de Elisama filho-de Amiúde');
INSERT INTO verses VALUES (3905, 4, 7, 54, 'no-dia o-oitavo príncipe aos-filhos-de Manassés Gamaliel filho-de resgate- Zur');
INSERT INTO verses VALUES (3906, 4, 7, 55, 'oferta-seu tigela-de uma uma trinta e-cem peso-dela um um prata setenta siclo em-siclo a-santidade os-dois cheios farinha-fina misturada em-o-óleo para-minha');
INSERT INTO verses VALUES (3907, 4, 7, 56, 'palma uma dez ouro cheia incenso');
INSERT INTO verses VALUES (3908, 4, 7, 57, 'touro um filho-de manhã um um cordeiro- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3909, 4, 7, 58, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3910, 4, 7, 59, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas cinco cordeiros filhos-de ano cinco este oferenda-de Gamaliel filho-de Zur');
INSERT INTO verses VALUES (3911, 4, 7, 60, 'no-dia o-ninth príncipe aos-filhos-de benjamim Abidã filho-de Gideoni');
INSERT INTO verses VALUES (3912, 4, 7, 61, 'sua-oferta tigela- uma uma trinta e-cem seu-peso um um prata setenta siclo em-siclo a-santidade os-dois cheios farinha-fina misturada em-o-óleo para-minha');
INSERT INTO verses VALUES (3913, 4, 7, 62, 'palma uma dez ouro cheia fumo-sacrificial');
INSERT INTO verses VALUES (3914, 4, 7, 63, 'touro um filho-de manhã um um cordeiro- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3915, 4, 7, 64, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3916, 4, 7, 65, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas cinco cordeiros filhos-de ano cinco este oferenda-de Abidã filho-de Gideoni');
INSERT INTO verses VALUES (3917, 4, 7, 66, 'no-dia o-tenth príncipe aos-filhos-de Dã Aiezer filho-de amisadai');
INSERT INTO verses VALUES (3918, 4, 7, 67, 'sua-oferta tigela-de- uma uma trinta e-cem seu-peso um um prata setenta siclo em-siclo a-santidade os-dois cheios farinha-fina misturada em-o-óleo para-minha');
INSERT INTO verses VALUES (3919, 4, 7, 68, 'palma uma dez ouro cheia fumo-sagrado');
INSERT INTO verses VALUES (3920, 4, 7, 69, 'touro um filho-de manhã um um cordeiro- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3921, 4, 7, 70, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3922, 4, 7, 71, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas cinco cordeiros filhos-de ano cinco este oferenda-de Aiezer filho-de amisadai');
INSERT INTO verses VALUES (3923, 4, 7, 72, 'em-dia-de Ashthai dez dia príncipe aos-filhos-de que Pagiel Ocrã');
INSERT INTO verses VALUES (3924, 4, 7, 73, 'sua-oferta tigela- uma uma trinta e-cem seu-peso um um prata setenta siclo em-siclo a-santidade os-dois-eles cheios farinha-fina misturada em-o-óleo para-a-manhã');
INSERT INTO verses VALUES (3925, 4, 7, 74, 'palma uma dez ouro cheia fumo-sagrado');
INSERT INTO verses VALUES (3926, 4, 7, 75, 'touro um filho-de manhã um um cordeiro- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3927, 4, 7, 76, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3928, 4, 7, 77, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas cinco cordeiros filhos-de ano cinco este oferenda-de Pagiel filho-de Ocrã');
INSERT INTO verses VALUES (3929, 4, 7, 78, 'em-dia-de dois dez dia príncipe aos-filhos-de Naftali Aira filho-de Enã');
INSERT INTO verses VALUES (3930, 4, 7, 79, 'sua-oferta tigela- uma uma trinta e-cem seu-peso um um prata setenta siclo em-siclo a-santidade os-dois cheios farinha-fina misturada em-o-óleo para-a-oferta-de-pão-');
INSERT INTO verses VALUES (3931, 4, 7, 80, 'palma uma dez ouro cheia incenso-');
INSERT INTO verses VALUES (3932, 4, 7, 81, 'touro um filho-de manhã um um cordeiro- um filho-de seu-ano para-holocausto');
INSERT INTO verses VALUES (3933, 4, 7, 82, 'Seir um um para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3934, 4, 7, 83, 'e-para-sacrifício as-ofertas-de-paz manhã dois carneiros cinco ovelhas cinco cordeiros filhos-de ano cinco este oferenda-de Aira filho-de Enã');
INSERT INTO verses VALUES (3935, 4, 7, 84, 'esta consagra-o o-altar em-dia-de ungiu-o a-ele ele príncipes-de Israel tigelas prata duas dez de-mizráquei- prata dois dez taças ouro dois dez');
INSERT INTO verses VALUES (3936, 4, 7, 85, 'trinta e-de-cem a-tigela a-uma prata e-setenta do-mizráquei- o-primeiro todo prata os-vasos duzentos-e-cinquenta e-quatro-de centenas na-unidade-de-prata o-santuário');
INSERT INTO verses VALUES (3937, 4, 7, 86, 'copos ouro duas- dez cheias Ketoret dez dez o-copo em-siclo a-santidade todo ouro-de os-copos vinte e-cento');
INSERT INTO verses VALUES (3938, 4, 7, 87, 'todo o bezerro para a holocausto dois dez as ovelhas carneiros doze dez cordeiros filhos-de ano dois dez e seu cereal-moído e os carneiros as cabras dois dez para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3939, 4, 7, 88, 'e-tudo novilhos sacrifício-de os-da-paz vinte e-quatro novilhos carneiros [אֵילִ֤ם] cabritos sessenta cordeiros filhos-de ano [שִׁשִּׁ֑ים] esta dedicação o altar atrás-de unção ele');
INSERT INTO verses VALUES (3940, 4, 7, 89, 'e-quando-entrar Moisés a tenda a-festa para-falar com-ele E-ouviu a a-ele de-cima-de a-ele de-sobre o-capitel que sobre arão os-querubins de-mezzo-a a-ele os-querubins וַיְדַבֵּ֖ר a-ele');
INSERT INTO chapters VALUES (125, 4, 8, 26);
INSERT INTO verses VALUES (3941, 4, 8, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3942, 4, 8, 2, 'palavra a Arão a-ele a-ela em-o-levantar-você a face-de a móel face-de a-menorah iluminarão sete as-luzes');
INSERT INTO verses VALUES (3943, 4, 8, 3, 'E-fez assim Arão a face-de face-de a-menorah elevação- luzes-sua como-que yhwh yhwh a Moisés');
INSERT INTO verses VALUES (3944, 4, 8, 4, 'e isto trabalho a menorá trava- ouro até coxa-sua até ela trava- ela como-aparência yhwh mostrou- yhwh a Moisés assim fez a a manora:');
INSERT INTO verses VALUES (3945, 4, 8, 5, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3946, 4, 8, 6, 'qach a os-levitas de-meio-de filhos-de Israel eles a-eles');
INSERT INTO verses VALUES (3947, 4, 8, 7, 'e-assim- a-eles a-eles para-purificá-los este-o sobre-eles águas-de חטא e-removerão tesoura sobre todo bêsārâm e-lavarem nos seus vestuários e-se-tornarão-puros');
INSERT INTO verses VALUES (3948, 4, 8, 8, 'e-tomarão touro filho-de manhã e-sua-oferta farinha-de-trigo em-estado-de-mistura com-o-açúcar e-bezerro- segundo filho-de manhã  tomarei  para-oferta-pelo-pecado');
INSERT INTO verses VALUES (3949, 4, 8, 9, 'e oferecerás a os-levitas diante-de tenda reunião e reunirás a todo congregação-de filhos-de Israel');
INSERT INTO verses VALUES (3950, 4, 8, 10, 'e-aproximarás a os-levitas yhwh yhwh E-sustentem filhos-de Israel a mãos-deles sobre os-levitas');
INSERT INTO verses VALUES (3951, 4, 8, 11, 'e levantará Arão a os levitas sinalização yhwh yhwh de-com filhos-de e-sejam para-lavrar para-servir yhwh serviço-de yhwh');
INSERT INTO verses VALUES (3952, 4, 8, 12, 'e os levitas apoiarão a sobre sobre cabeça as ovelhas e farás a o-primeiro chéttā''at e-a hā''ēchād ʿōlāh a-yhwh ləkappēr sobre os-levitas');
INSERT INTO verses VALUES (3953, 4, 8, 13, 'e-vos-estabeleceis a os-levitas diante-de אַהֲרֹן velifnei seus-filhos eles a-eles oferta-elevação para-יהוה');
INSERT INTO verses VALUES (3954, 4, 8, 14, 'e-vos-separais a os-levitas de-meio-de filhos-de e-sejam e-serão a-mim os-levitas');
INSERT INTO verses VALUES (3955, 4, 8, 15, 'ואחרי־ assim entrarão para-lavrar para-servir a tenda eles e-vos-purificais eles e enfarinharás eles oferta-de-levitação');
INSERT INTO verses VALUES (3956, 4, 8, 16, 'que presentes presentes eles a-mim de-meio-de filhos-de Israel debaixo pitarat todo rehem em-primogênito todo de-filhos-de Israel eles eles para-mim');
INSERT INTO verses VALUES (3957, 4, 8, 17, 'que para-mim todo primogênito filhos-de Israel e-sobre-os-animais u-babehemah em-dia-de hakotti todo primogênito em-terra-de eles hiqdashthiti eles para-mim');
INSERT INTO verses VALUES (3958, 4, 8, 18, 'va-ekkakh a debaixo debaixo-de todo bekhor de-filhos Israel');
INSERT INTO verses VALUES (3959, 4, 8, 19, 'va-etthana a dos-Levitas netunim para-arão ulvavano de-meio filhos-de Israel para-lavrar a serviço-de filhos-de Israel em-tenda-de encontro e-perdoar sobre será Israel e-não será em-os-filhos Israel flagelo em-contato filhos-de Israel a o-santuário');
INSERT INTO verses VALUES (3960, 4, 8, 20, 'E-fez Moisés e-Aharon e-todo ádat filhos-de Israel para-os-Levitas yhwh que ordenou yhwh a-eles Moisés lálevím kén- fizeram a-eles filhos-de Israel');
INSERT INTO verses VALUES (3961, 4, 8, 21, 'e-ele-se-purificou os-levitas e-eles-lavaram em-sus-vestes e-ele-levantou Aarão eles oferta-elevação diante-de yhwh e-perdoou sobre-eles אַהֲרֹן para-fazer-santo-a-ela');
INSERT INTO verses VALUES (3962, 4, 8, 22, 'e-depois-de assim vieram para-lavrar para-abrir-trabalho a sua servidão em-tenda-de encontro diante-de אַהֲרֹן velifnei seus-filhos yhwh ordenou yhwh a Moisés a-eles os-levitas assim fizeram para-eles');
INSERT INTO verses VALUES (3963, 4, 8, 23, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3964, 4, 8, 24, 'esta que para-os-Levitas de-filho cinco e-vinte ano e-para-cima virá para-guardar exército em-trabalho-de tenda reunião');
INSERT INTO verses VALUES (3965, 4, 8, 25, 'e-de-filho cinquenta ano ישוב de-guarda o-trabalho e-não ya-abod ainda');
INSERT INTO verses VALUES (3966, 4, 8, 26, 'e-servirá a seu-irmão em-a-tenda encontro para guardar de-serviço não não ele-serve assim farás aos levitas em-os-serviços-deles');
INSERT INTO chapters VALUES (126, 4, 9, 23);
INSERT INTO verses VALUES (3967, 4, 9, 1, 'e-falou yhwh a Moisés no-deserto- sinaí em-a-ano a-segunda para-saí-los da-terra-de Egito dizendo dizendo para-dizer');
INSERT INTO verses VALUES (3968, 4, 9, 2, 'e-eles-fazem filhos-de Israel a o-páscoa no-sua-celebração:');
INSERT INTO verses VALUES (3969, 4, 9, 3, 'na-quarta dez- dia no-primeiro-mês- entre entre os-dezessete-dias- ele ele em-suas-festas- conforme-toda seus-decretos- ele suas-leis- ele ele');
INSERT INTO verses VALUES (3970, 4, 9, 4, 'e-falou Moisés a filhos-de Israel para-fazer o-passo');
INSERT INTO verses VALUES (3971, 4, 9, 5, 'e-fizeram a o-Pesque em-primeiro em-quatro dia dia entre entre os-arávios em-deserto-de Si-na-y conforme-tudo que yhwh yhwh a Moisés assim fizeram filhos-de Israel');
INSERT INTO verses VALUES (3972, 4, 9, 6, 'e-houve homens que eram impuros para a alma homem e-não poderiam no-dia o-páscoa em-o-dia o-aquele e se aproximaram diante-de Moisés no-dia אַהֲרֹן no-dia a-aquela');
INSERT INTO verses VALUES (3973, 4, 9, 7, 'e-disseram os-homens esses-eles a-ele nós impuros para-a-alma homem por-que se-puseram-em-estado-de-desgraça para-não o-aproximado a yhwh yhwh no-meio-de em-meio-de filhos-de Israel');
INSERT INTO verses VALUES (3974, 4, 9, 8, 'E-disse a-eles Moisés em-standam e-eouvirei que yhwh a-vós para-vocês');
INSERT INTO verses VALUES (3975, 4, 9, 9, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3976, 4, 9, 10, 'palavra a filhos-de dizendo dizendo homem homem porque sera- impuro- para-a-alma ou a-vós para-vós ou para-gerações-vossas e fizer pascal para-יהוה');
INSERT INTO verses VALUES (3977, 4, 9, 11, 'בַּחֹ֨דֶשׁ o-segundo em-quatro dez dia entre das-aves eles-faziam ele sobre matzot e-amargos o-comerão');
INSERT INTO verses VALUES (3978, 4, 9, 12, 'não nós do-que-ele até não e-osso não quebrar- nele ele chuq-at o-páscoa farão a-ele');
INSERT INTO verses VALUES (3979, 4, 9, 13, 'e-o-homem que ele puro u-ve-de-rekh não foi e-se-afastará para fazer o-passo aquela a-alma que de-a-sua-povo que yhwh não não oferecerá em-o-tempo-sua pecado-o ele-levará o-homem a-aquela');
INSERT INTO verses VALUES (3980, 4, 9, 14, 'e-quando morará com-vocês estrangeiro e-fará páscoa a-yhwh segundo-a-ordem-de o-páscoa e-segundo-o-juramento-sua assim fará uma será a-vós a-vós e para o estrangeiro a-terra a-terra');
INSERT INTO verses VALUES (3981, 4, 9, 15, 'וביום levantar-á a o-tabernáculo cobriu a-névoa a o-tabernáculo le-ohel será e-no-crepúsculo será sobre o-tabernáculo כאמראה- fogo até manhã');
INSERT INTO verses VALUES (3982, 4, 9, 16, 'assim será permanente ha-eanan cobrirá e-aparencia-de noite noite');
INSERT INTO verses VALUES (3983, 4, 9, 17, 'e-conforme subida a-névoa de-cima-de a-tenda assim partirão filhos-de Israel e-no-lugar que habitará- nome o-nubloso nome acamparão filhos-de Israel');
INSERT INTO verses VALUES (3984, 4, 9, 18, 'sobre yhwh yhwh e-partirão filhos-de Israel yhwh de-seu yhwh e-acamparão todo dias-de que morará o-nublo sobre o-tabernáculo acamparão');
INSERT INTO verses VALUES (3985, 4, 9, 19, 'e-no-alongar-se o-nublo sobre o-tabernáculo dias muitos e-guardarão filhos-de yhwh a guarda-de yhwh e-não eles-partirão');
INSERT INTO verses VALUES (3986, 4, 9, 20, 'haja que será a nuvem dias número sobre o arca yhwh a boca yhwh yhwh e-sobre yhwh yhwh eles-partirão');
INSERT INTO verses VALUES (3987, 4, 9, 21, 'e há que sera a-nuvem do entardecer até manhã e a nuvem a nuvem na-manhã e se levantaram ou dia e-noite e a nuvem a nuvem e se levantaram:');
INSERT INTO verses VALUES (3988, 4, 9, 22, 'ou dias ou novo ou dias em-alongar a-nuéveis sobre o-tabernáculo para-estar-acampado sobre-ele acamparão filhos-de Israel e-não partirão e-em-sua-levantação eles-partirão');
INSERT INTO verses VALUES (3989, 4, 9, 23, 'sobre yhwh yhwh acamparão yhwh de-seu yhwh yhwh a de-guarda yhwh guardaram-se sobre de-seu yhwh por-mão-de Moisés');
INSERT INTO chapters VALUES (127, 4, 10, 36);
INSERT INTO verses VALUES (3990, 4, 10, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (3991, 4, 10, 2, 'fez a-ti dois-de chifres prata miqusha farás eles e-sejam a-ti lemikra a-congregação ulmasa a hammachanot');
INSERT INTO verses VALUES (3992, 4, 10, 3, 'e-sopram בָּהֵן venoedhu a-ti todo a-congregação a entrada-de tenda-de encontro');
INSERT INTO verses VALUES (3993, 4, 10, 4, 'e-se beachat yitqauu venoedhu a-ti hannesiim ראשׁי milhares-de Israel');
INSERT INTO verses VALUES (3994, 4, 10, 5, 'utqatem trova-alarma e-partirão os-lugares-acampamento os-que-acampam para-o-leste');
INSERT INTO verses VALUES (3995, 4, 10, 6, 'e-tocareis alarme segunda-noite e-partirão os-lugares-acampamento os-que-acampam para o timna'' trova-alarma tocarão para-os-marchas-verso');
INSERT INTO verses VALUES (3996, 4, 10, 7, 'e-no-congregar a a-assembleia voces-tocareis e-não voces-clamareis-verso');
INSERT INTO verses VALUES (3997, 4, 10, 8, 'e-filhos-de Arão os-sacerdotes tocarão em-o-chifres-de-aleluia e-sejam a-vós para-a-lei eternidade para-gerações-de-vocês');
INSERT INTO verses VALUES (3998, 4, 10, 9, 'e-quando voces-vireis מִלְחָמָה na-terra-de-vosso sobre a-dura o-opressor vos e-voces-estardes-gritando em-chatzrot yhwh diante-de yhwh Elohim-vosso e-noshaatem me-oyveichechem');
INSERT INTO verses VALUES (3999, 4, 10, 10, 'e no dia sua-alegria u-bemoadeichechem u-beraashi chadshichechem utekaatem em-chatzrot sobre vossas-ofertas e-sobre zibchei shalmeicheim e-sejam a-vós lezicharon diante-de Elohim-vosso eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (4000, 4, 10, 11, 'e-houve basshanah hashnith no mês- o-segundo vinte bacheshe naalah o-nubloso de-cima-de tabernáculo-de ha-edut:');
INSERT INTO verses VALUES (4001, 4, 10, 12, 'e saíram filhos-de Israel para suas viagens de-deserto-de Sinai e acampou o nuãan em-deserto-de Páran:');
INSERT INTO verses VALUES (4002, 4, 10, 13, 'e-partiram na-primeira sobre yhwh yhwh por-mão-de Moisés');
INSERT INTO verses VALUES (4003, 4, 10, 14, 'vaysa estandarte-de acampamento-de filhos-de Judá em-a-primeira para-exércitos-deles e-sobre tzava-o Nasom filho-de Aminadabe');
INSERT INTO verses VALUES (4004, 4, 10, 15, 'e-sobre exército tribo-de filhos-de Iessachar Netanel filho-de Zuar');
INSERT INTO verses VALUES (4005, 4, 10, 16, 'e-sobre exército tribo-de filhos-de Zebulom Eliabe filho-de Chelon');
INSERT INTO verses VALUES (4006, 4, 10, 17, 'e-foi-lançado ham-mishkan e-partiram filhos-de Gershom e-filhos-de Merari carregadores-de o-tabernáculo');
INSERT INTO verses VALUES (4007, 4, 10, 18, 'e-partiu estandarte-de acampamento-de reuven para-exércitos-deles e-sobre tzava-o Elisur filho-de Sedeur');
INSERT INTO verses VALUES (4008, 4, 10, 19, 'e-sobre exército tribo-de filhos-de Simeão Shelumiel filho-de tori Shaddai');
INSERT INTO verses VALUES (4009, 4, 10, 20, 'e-sobre tsva-a tribo-de filhos-de Gade Eliasafe filho-de Deuel');
INSERT INTO verses VALUES (4010, 4, 10, 21, 've-naseu-u ha-khatim carregadores-de o santuário ve-heqimu-u a o-tabernáculo até ba-am');
INSERT INTO verses VALUES (4011, 4, 10, 22, 've-nasa-a estandarte-de acampamento-de filhos-de Efraim para-exércitos-deles e-sobre tzava-o Elisama filho-de Amiúde');
INSERT INTO verses VALUES (4012, 4, 10, 23, 'e-sobre tsva-a tribo-de filhos-de Manassés Gamaliel filho-de peda-h Zur');
INSERT INTO verses VALUES (4013, 4, 10, 24, 'e-sobre tsva-a tribo-de filhos-de Benjamim Abidã filho-de gideon-i');
INSERT INTO verses VALUES (4014, 4, 10, 25, 'e acampou-se bandeira acampamento-de filhos-de Dã que reúne para-todo as acampadas para-exércitos-deles e-sobre tzava-o Aiezer filho-de Amisadai');
INSERT INTO verses VALUES (4015, 4, 10, 26, 'e-sobre exército tribo-de filhos-de que Pagiel filho-de Ocrã');
INSERT INTO verses VALUES (4016, 4, 10, 27, 'e-sobre exército tribo-de filhos-de Naftali Aira filho-de Enã');
INSERT INTO verses VALUES (4017, 4, 10, 28, 'Estas viagens filhos-de Israel para-exércitos-deles e-eles-partiram');
INSERT INTO verses VALUES (4018, 4, 10, 29, 'E-disse Moisés para-Hobab filho-de Reuel o-midianita cons- sogro Moisés partindo-eles-se nós a o-lugar disse yhwh ele ele a-vós a-vós לְכָ֤ה com-nos para-ti para-ti porque yhwh falou bom sobre Israel');
INSERT INTO verses VALUES (4019, 4, 10, 30, 'E-disse a-ele não irei que se a terra-meu e-a nascimento-meu irei.');
INSERT INTO verses VALUES (4020, 4, 10, 31, 'E-disse a por-favor deixarás que que sobre assim conheceste acampamento-nos no-deserto e-você-seja para-nós para-os-olhos');
INSERT INTO verses VALUES (4021, 4, 10, 32, 'e-foi porque andarás com-nosso e-era o-bom aquele que fará-bem yhwh com-nos e-nos-faremos-bem para-ti');
INSERT INTO verses VALUES (4022, 4, 10, 33, 'e-eles-partiram de-montanha-de yhwh o-caminho-de três-de dias e-arca em-aliança-de yhwh n-os-e-a o-caminho-de caminho três-de dias a-eles a-eles m-nu-ha-h');
INSERT INTO verses VALUES (4023, 4, 10, 34, 'v-a-an-na yhwh sobre-eles de-dia b-nas-e-a-m de o-acampamento');
INSERT INTO verses VALUES (4024, 4, 10, 35, 'e-houve b-in-so-a הָאָרֹ֖ן E-disse Moisés q-u-ma-h yhwh yhwh o-yev-e-cha v-yan-nu-su m-shen-a-e-cha de-diante-tua');
INSERT INTO verses VALUES (4025, 4, 10, 36, 'u-b-nu-ho diz-que volta-te yhwh multidões-de milhares-de Israel');
INSERT INTO chapters VALUES (128, 4, 11, 35);
INSERT INTO verses VALUES (4026, 4, 11, 1, 'e-houve o-povo kamithaonnim mau em-orelhas-de yhwh E-ouviu yhwh e-acendeu-se sua-ira vatabe''ar- bam- yhwh e-comeste vatokhal biktshe o-acampamento');
INSERT INTO verses VALUES (4027, 4, 11, 2, 'e clamou o-povo a Moisés e-ele-orou Moisés a yhwh e-ela-senhorou-se o-fogo');
INSERT INTO verses VALUES (4028, 4, 11, 3, 'E-chamou nome-de o-lugar aquele queimadura-de porque queimada yhwh fogo yhwh');
INSERT INTO verses VALUES (4029, 4, 11, 4, 'e-a-multidão que em-meio-seu se-apaixonaram desejo e-voltaram e-eles-choraram também filhos-de Israel e-disseram quem ele-nos-alimentou carne');
INSERT INTO verses VALUES (4030, 4, 11, 5, 'lembramos a o-peixe que nós-comeremos em-Egito חִנָּ֑ם com os-espigões e-את os-abutres e-a o-capim e-a os-cenóveres e-a os-nomes-verso-final');
INSERT INTO verses VALUES (4031, 4, 11, 6, 'e-agora a-nostra-vida seca-a não-há todo sem-o a o-manne nosso olhos:');
INSERT INTO verses VALUES (4032, 4, 11, 7, 'e-o-manne como-semente- ele ele e-a-sua-olho o-bdélio o-bedolach-verso-final');
INSERT INTO verses VALUES (4033, 4, 11, 8, 'navegaram o-povo e-colherão e-moerão em-recheias ou moeram na-moenda e-cozinham em-o-paruru e façam ele de-pães e-foi o-sabor-seu como-o-gosto para-o-seio o óleo');
INSERT INTO verses VALUES (4034, 4, 11, 9, 'e-na-descida o-talho sobre noite noite descerá o-mão sobre-ele');
INSERT INTO verses VALUES (4035, 4, 11, 10, 'E-ouviu Moisés a o povo chorando para-o-sua-famílias homem para-a-porta אָהֳל֑וֹ yhwh muito yhwh muito mal Moisés mau');
INSERT INTO verses VALUES (4036, 4, 11, 11, 'E-disse Moisés a yhwh por-que por-te-imploro para-o-seu-servidor e-porque não encontrei graça em-olhos-teus para-situar a carregamento todo o-povo este sobre-mim');
INSERT INTO verses VALUES (4037, 4, 11, 12, 'e-eu quisi a todo o-povo esta se eu o-gerou-o porque diga a-mim carregue-o no-peito-teu como-que sobre a-terra a o-ninhento sobre a-te-rri-tó-ria que jures-te para-os-seus-pais');
INSERT INTO verses VALUES (4038, 4, 11, 13, 'de-onde a-mim da-carne a-dar para-todo o-povo esta porque dizendo sobre-mim dizendo dá- para-nos carne e-nos-comeremos');
INSERT INTO verses VALUES (4039, 4, 11, 14, 'não eu eu lebadí levando a que o-povo esta porque grande de-mim');
INSERT INTO verses VALUES (4040, 4, 11, 15, 'e-se k-kách-| a-t- a-mim para-mim h-r-g-n-i por-favor h-róg se encontrei graça em-olhos-teus e-a vejo-eu b-r-á-a-t-i:');
INSERT INTO verses VALUES (4041, 4, 11, 16, 'E-disse yhwh a Moisés e-s-p-h-a- para mim setenta homem dos velhos Israel que soubeste porque eles anciãos-de eles e seus juízes e tomarei a-elas a tenda encontro e se juntarão nome contigo');
INSERT INTO verses VALUES (4042, 4, 11, 17, 'e-descerrei-eu e-falarei-eu com-você nome e-arrancarei-eu de o-sopro que sobre-ti e-postarei sobre-eles e-levarão contigo em-massa o-povo tu tissa tu apenas de ti:');
INSERT INTO verses VALUES (4043, 4, 11, 18, 'e-a o-povo toamar consagrem-vos lemahar vaachaltem que porque bekitem yhwh dizendo quem quem yaakhilenu basar porque bom para-nós yhwh a-vós yhwh a-vós carne vaachaltem');
INSERT INTO verses VALUES (4044, 4, 11, 19, 'não dia um tochelun e-não dias-dois e-não- cinco dias e-não asarah dias e-não vinte dia');
INSERT INTO verses VALUES (4045, 4, 11, 20, 'até novo dias até até ele sairá de-a-vossa-face e-será a-vós para-o-estrangeiro porque porque desgostais a yhwh que em-a-vossa-mezquita dizendo dizendo por-que isto saiu-nos de-Egito');
INSERT INTO verses VALUES (4046, 4, 11, 21, 'E-disse Moisés seis-de centenas mil pé-mi o-povo eu eu em-meio-dele e-tu ''amarta carne a-eles a-eles va''aklu novo dias');
INSERT INTO verses VALUES (4047, 4, 11, 22, 'o-rebanho e-bakar será-imolado a-eles e-achou a-eles mãe a o-mar peixes-de a-eles será-coletado a-eles e achou para-eles');
INSERT INTO verses VALUES (4048, 4, 11, 23, 'E-disse yhwh a Moisés yhwh yhwh serás curta agora verás se chamará minha palavra se não');
INSERT INTO verses VALUES (4049, 4, 11, 24, 'e-saiu Moisés e-ele-falou a o-povo a yhwh yhwh e juntou-se setenta homem dos velhos o-povo eles eles em-torno-de o-tenda');
INSERT INTO verses VALUES (4050, 4, 11, 25, 'e-descer yhwh be-anan e-falou a-ele-o a-ele de ha-ruch-ha que sobre-ele E-colocou sobre setenta homem e-houve E-foi ke-no-ch sobre-eles ha-ruch-ha va-yit-nab-av-u e-não e-afirmaram-vos');
INSERT INTO verses VALUES (4051, 4, 11, 26, 'e-permaneceram dois homens-o no-acampamento nome o-primeiro [׀] e-nome-de o-segundo Midad e-foi-posta em-eles הָר֗וּחַ e-eles com-escrições e-não saíram a-tenda-a e-ele-proferiram em-o-lager');
INSERT INTO verses VALUES (4052, 4, 11, 27, 'e-correu o jovem e-revelou para-Moisés E-disse Elad e Midi proferindo no-lager');
INSERT INTO verses VALUES (4053, 4, 11, 28, 'e respondeu Yehoshua filho-de Nuun servindo Moisés de-seus-jovens E-disse Adonai Moisés encarcerando-os');
INSERT INTO verses VALUES (4054, 4, 11, 29, 'E-disse a-ele Moisés o-que-inveja tu a-mim e-quem dará todo yhwh yhwh nébiam yhwh dê yhwh a ruah-o sobre-eles');
INSERT INTO verses VALUES (4055, 4, 11, 30, 'va-yea-sef Moisés a ele ele e-os-anciãos Israel');
INSERT INTO verses VALUES (4056, 4, 11, 31, 'e-Espírito-de nas-a de-junto-de yhwh yhwh shalvim de ha-yam va-yeit-tosh sobre ha-machane dia dia assim dia dia assim em-torno-de o-acampamento ukhe-amatayim a-terra face-de a-terra');
INSERT INTO verses VALUES (4057, 4, 11, 32, 'E-levantou o-povo todo o-hoje o-aquele e-tudo na-noite dia dia o-amanhã e-eles-recolheram a a-súplica o-menor recolheu asarah a-eles e-eles-prostraram-se a-eles prostrar-se em-torno-de o-acampamento');
INSERT INTO verses VALUES (4058, 4, 11, 33, 'o-carne ainda-ele entre suas-dentes ainda-não ser-quebrado e também yhwh acendeu-se no povo e-ele-feriu yhwh no-povo ferida multiplicai muito');
INSERT INTO verses VALUES (4059, 4, 11, 34, 'E-chamou a nome-de o-lugar aquele sepulturas da-avareza porque nome enterraram a o-povo os-que-têm-desejo');
INSERT INTO verses VALUES (4060, 4, 11, 35, 'das-sepulturas da-desejo partiram o-povo courts e-foram em-as-cortes');
INSERT INTO chapters VALUES (129, 4, 12, 16);
INSERT INTO verses VALUES (4061, 4, 12, 1, 'e falou miriam e-Aarão em-mošé sobre oelohim a-mulher a-cushi que tomou porque mulher cushi tomou');
INSERT INTO verses VALUES (4062, 4, 12, 2, 'e-disseram acaso somente em-moshe yhwh yhwh não-é também e colocaram-na yhwh E-ouviu yhwh');
INSERT INTO verses VALUES (4063, 4, 12, 3, 'e-o-homem Moisés muito de-todo muito de-toda o-homem face-de a-terra');
INSERT INTO verses VALUES (4064, 4, 12, 4, 'E-disse yhwh de-repente a Moisés e-a Arão e-a Miryā'' saí-am ter-convosco a tenda de-encontro e-saíram ter-com-eles');
INSERT INTO verses VALUES (4065, 4, 12, 5, 'e-ele-descerrou yhwh em-o-pilar nuvem e-se-posicionou entrada-de haohel E-chamou Aarão e-miriam e-saíram dois-deles');
INSERT INTO verses VALUES (4066, 4, 12, 6, 'E-disse ouvi por-favor palavras-meus se yhwh profeta-vosso a-ele em-a-imagem a-ele me-revelarei em-o-sonho dare-a-falar- em-ele');
INSERT INTO verses VALUES (4067, 4, 12, 7, 'não assim servo-meu Moisés em-todo ele fiel ela');
INSERT INTO verses VALUES (4068, 4, 12, 8, 'a boca a boca dare-a-falar- nele e-aparência e-não yhwh e-imagem yhwh não e-porquê não temor-vos para-falar em-o-servidor-meu em-Moshê');
INSERT INTO verses VALUES (4069, 4, 12, 9, 'e-ele-se-irritou yhwh com-eles E-andou');
INSERT INTO verses VALUES (4070, 4, 12, 10, 'e-o-nubloso afastou-se de-cima-de a-tenda e-eis de-Miráim lepra-a como-neve e-ele-virou-se de-Aaron a de-Miráim e-eis de-lepra-a');
INSERT INTO verses VALUES (4071, 4, 12, 11, 'E-disse אַהֲרֹן a Moisés por-mim Adonai a por-favor será dada sobre-nos oferta de pecado que seja como morta e-que pecamos');
INSERT INTO verses VALUES (4072, 4, 12, 12, 'a agora seja como-morte que em-saída-seu sua-mãe mãe-dele e-ele-foi-comido metade-de de-carne-seu');
INSERT INTO verses VALUES (4073, 4, 12, 13, 'e-ele-gritou Moisés a dizendo dizendo El por-favor cura por-favor a-ela');
INSERT INTO verses VALUES (4074, 4, 12, 14, 'E-disse yhwh a Moisés e-pai-seu ele-vomitará vomitou em-a-frente-dela não eles-serão-ocultos sete-de dias ela-será-fechada shib-aat dias de-fora para-o-machane e-depois ele-será-coletado');
INSERT INTO verses VALUES (4075, 4, 12, 15, 'e-ela-fechou-se Miriam de-fora para-o-acampamento sete-de dias e-o-povo não ele-partiu até ele-foi-coletado Miriam');
INSERT INTO verses VALUES (4076, 4, 12, 16, 'e-depois eles-partiram o-povo de-a-cortes e-acamparam em-deserto-de em Paran-');
INSERT INTO chapters VALUES (130, 4, 13, 33);
INSERT INTO verses VALUES (4077, 4, 13, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4078, 4, 13, 2, 'envia- para-ti אֲנָשִׂים e-eles-procurarão a terra Canaã que eu deu um Israel um um homem um para-o-clã אביו enviarão-os todo príncipe-de בָהֶֽם׃');
INSERT INTO verses VALUES (4079, 4, 13, 3, 'e-enviou eles Moisés do-deserto Parã sobre yhwh yhwh כֻּלּם homens topos-de filhos-de Israel eles');
INSERT INTO verses VALUES (4080, 4, 13, 4, 'e-estes de-seus-nomes para-a-tribo-de Rúben Samuá filho-de Zacur');
INSERT INTO verses VALUES (4081, 4, 13, 5, 'para-a-tribo-de Simeão שָׁפַט filho-de Horí');
INSERT INTO verses VALUES (4082, 4, 13, 6, 'para-tribo-de Judá Calebe filho-de sera-virado-verso-final');
INSERT INTO verses VALUES (4083, 4, 13, 7, 'para-tribo-de Issacar ele-redimirá filho-de José');
INSERT INTO verses VALUES (4084, 4, 13, 8, 'para-matate Efrayim Hoshe''a filho-de Nun:');
INSERT INTO verses VALUES (4085, 4, 13, 9, 'para-tribo-de Benjamim Palti filho-de Rafua''');
INSERT INTO verses VALUES (4086, 4, 13, 10, 'para-tribo-de Zebulom Gaddiel filho-de Sodi''');
INSERT INTO verses VALUES (4087, 4, 13, 11, 'para-matate José para-tribo-de Manassés Gadi filho-de Susy''');
INSERT INTO verses VALUES (4088, 4, 13, 12, 'para-tribo-de Dã Amiel- filho-de Gamaly''');
INSERT INTO verses VALUES (4089, 4, 13, 13, 'para-tribo-de que Setur filho-de Michael');
INSERT INTO verses VALUES (4090, 4, 13, 14, 'para-tribo-de Naftali Nachbi filho-de e-Fesi');
INSERT INTO verses VALUES (4091, 4, 13, 15, 'para-tribo-de Gade Geuel filho-de Maki');
INSERT INTO verses VALUES (4092, 4, 13, 16, 'Estas nomes-de os-homens que enviou Moisés para perseguir E-chamou a-terra E-chamou Moisés para-Hosea filho-de נוּן יְהוֹשֻֽׁעַ');
INSERT INTO verses VALUES (4093, 4, 13, 17, 'e-estendeu eles Moisés para-Tour a terra E-disse E-disse a-eles ALU este no-Negueb e-voces-subiram a o-monte');
INSERT INTO verses VALUES (4094, 4, 13, 18, 'וראות a a-terra que ela e-a o-povo ele sobre-ela o-forte ele se-estafrou o-pouco ele se muito');
INSERT INTO verses VALUES (4095, 4, 13, 19, 'וּמָ֣ה a-terra que ele habitou em-ela ela ela se maldade e que as cidades que ele habitante-de nelas dos acampamentos mãe em fortalezas:');
INSERT INTO verses VALUES (4096, 4, 13, 20, 'e que a-terra o óleo ela se de aroma árvore nela madeira se do-fruto-de a-terra e tomastes dias-de a-terra e os dias dias-de primícias de-uvas;');
INSERT INTO verses VALUES (4097, 4, 13, 21, 'e-ele-levantaram-se e-eles-procuraram a a-terra do-midbar- Tsìn até Rechob para-entrar חֲמָֽת');
INSERT INTO verses VALUES (4098, 4, 13, 22, 'e-subiram no-Néguev E-veio até Hevron וְשָׁ֤ם Ahímán sexto e-Talmay filhos-de o-Anaqueu e-Hebrôn sete dois foi-construída diante-de tsa''an Egito');
INSERT INTO verses VALUES (4099, 4, 13, 23, 'e-vieram até vale-de eshkol va-yikr''tu de-aqui z''mora ve-eshkol um um va-yissa''uhu ba-mot bishnayim e-de harimonim e-de ha-te''enim');
INSERT INTO verses VALUES (4100, 4, 13, 24, 'para aquele lugar aquele chamou vale-de eshkol sobre odot ha-eshkol que kartu de-lá filhos-de Israel');
INSERT INTO verses VALUES (4101, 4, 13, 25, 'e-eles-retornaram mitur a-terra ao-fim-de quarenta dia');
INSERT INTO verses VALUES (4102, 4, 13, 26, 'vayyalku e-ele-chegou a Moisés e-a Arão e-a todo congregação-de filhos-de Israel a deserto-de paran qadeshah a-terra os palavra e-a todo a-congregação vayar''um a pri a-terra');
INSERT INTO verses VALUES (4103, 4, 13, 27, 'וַיְסַפְּרוּ־ a-ele e-disseram בָּ֕אנוּ a a-terra que שְׁלַחְתָּ֑נוּ e-tambem זָבַ֨ת ela e mel a-vós e-este seu fruto');
INSERT INTO verses VALUES (4104, 4, 13, 28, 'no-entanto porque forte o-povo o-que-habitava em-a-terra e-as-cidades em-Bet-Zur muito muito e-também filhos-de o-Anaq vimos nome');
INSERT INTO verses VALUES (4105, 4, 13, 29, 'Amalek habitante na-terra do-sul e-o-Heteu e-o-Jebuseu e-o-amorreu habitante-de no monte e-o-canaanita habitou sobre o-mar e-sobre mão o-Jordão');
INSERT INTO verses VALUES (4106, 4, 13, 30, 'e-hes Kaléve a o-povo E-disse Moisés E-disse alehu subiremos veyarashnu a-ela porque yachol nuchal a-ela');
INSERT INTO verses VALUES (4107, 4, 13, 31, 'vehanashim que alu com-ele não não nuchal para-subir a ele nós força ele de-nós');
INSERT INTO verses VALUES (4108, 4, 13, 32, 'veyotziu dibbat- a-terra que taru- a-ela a filhos-de dizendo a-terra a-terra que avarnu- na-ela para perseguir terra terra okhlet- ela ele e-todo o-povo que vimos בְתוֹכָ֖הּ homens-de middot-');
INSERT INTO verses VALUES (4109, 4, 13, 33, 'e ali vimos a hannefilim- filhos-de anak- de hannefilim- vanehi- be-enenu grilos e-assim fomos em seus olhos:');
INSERT INTO chapters VALUES (131, 4, 14, 45);
INSERT INTO verses VALUES (4110, 4, 14, 1, 'e-carregou todo a-congregação e-eles-se-tornaram a קוֹלָ֑ם e-eles-choraram o-povo na-noite a-aquela');
INSERT INTO verses VALUES (4111, 4, 14, 2, 'e-eles-lamentaram sobre Moisés e-sobre Arão todo filhos-de Israel e-ele-disseram a-para-eles todo a congregação se-não nossas-matrizes na-terra Egito ou em-o-deserto este se-não morremos');
INSERT INTO verses VALUES (4112, 4, 14, 3, 'e-porque yhwh trazendo nós-aos a a-terra esta para-cair em-espada nossas-mulheres e-nossos-filhos serão para-excesso bom bom para-nós volta de Egito:');
INSERT INTO verses VALUES (4113, 4, 14, 4, 'e-disseram homem a irmão-dele foram-dadas cabeça e-voltaríamos de Egito:');
INSERT INTO verses VALUES (4114, 4, 14, 5, 'e-caiu Moisés e-Aarão sobre peneyhem diante-de todo assembleia congregação-de filhos-de Israel');
INSERT INTO verses VALUES (4115, 4, 14, 6, 'vayehôshûa'' filho-de Nun ve''kalêv filho-de yefunneh de hâtârîm a a-terra quebraram em-suas-roupas:');
INSERT INTO verses VALUES (4116, 4, 14, 7, 'e-disseram a todo dizendo a-terra Israel dizendo a-terra que passamos nela a-terra muito muito a-terra muito muito');
INSERT INTO verses VALUES (4117, 4, 14, 8, 'se desejava yhwh yhwh e-ele-trouxe nós a a-terra esta terra para-nós terra que ele fluindo-de leite e-mel');
INSERT INTO verses VALUES (4118, 4, 14, 9, 'porém בַּֽיהוָה֮ a rebelareis-vos e-vós a a-terra que povo eles porque o-nosso-pão eles desviou imagem de-sobre-eles e-יהוה com-nós a temereis-os');
INSERT INTO verses VALUES (4119, 4, 14, 10, 'e-disseram todo a-congregação eles eles em-pedras yhwh yhwh nos-apareceu em-tenda-de encontro a todo filhos-de Israel');
INSERT INTO verses VALUES (4120, 4, 14, 11, 'E-disse yhwh a Moisés até para-onde me-aborrecerão o-povo este e-até a-onde não crerão em-mim em-todo as-sinais que fiz-eu em-o-centro-dele');
INSERT INTO verses VALUES (4121, 4, 14, 12, 'conhecê-lo com-a-praga e-expulsá-los e-eeshah ot-cha le-goy- grande nós de-nós');
INSERT INTO verses VALUES (4122, 4, 14, 13, 'E-disse Moisés a yhwh e-ouvirão Egito porque subestimaste-você com-teu-poder a o-povo este de-seu-meio');
INSERT INTO verses VALUES (4123, 4, 14, 14, 'e-diretriz a a-terra a-terra esta ouviram yhwh tu yhwh בְּקֶ֖רֶב o-povo este que olho tu yhwh tu yhwh e-nuvens-teus ficou-em-pé em-eles tu nuvem אתה andou diante deles diariamente noite fogo noite');
INSERT INTO verses VALUES (4124, 4, 14, 15, 'e morreu a o-povo este um um e disseram as-nações que dizendo a escuta-te para-dizer');
INSERT INTO verses VALUES (4125, 4, 14, 16, 'por-não poderá yhwh para-trazer a o-povo este a a-eles que jurou para-eles vayishchatem no-deserto');
INSERT INTO verses VALUES (4126, 4, 14, 17, 'e-agora ele-se-grandeira- por-favor força Adonai como dizendo para-dizer');
INSERT INTO verses VALUES (4127, 4, 14, 18, 'yhwh longo de-nariz e-muita- bondade leva עון e-pash-te não não purificar-á po-qed [אָבוֹת֙] avós sobre בָּנִים sobre terços e-sobre quartos');
INSERT INTO verses VALUES (4128, 4, 14, 19, 'selach- agora [הָעָ֥ם] o-povo este ke-godel chasdekha ve-ka-asher nas-ta-tha ao-povo este de-misraim e-até até-aqui');
INSERT INTO verses VALUES (4129, 4, 14, 20, 'E-disse yhwh eu perdoei conforme a tua palavra');
INSERT INTO verses VALUES (4130, 4, 14, 21, 'e-o-átrio vive eu e-ele-cheia-se glória-de- yhwh a todo a-terra');
INSERT INTO verses VALUES (4131, 4, 14, 22, 'que todo os-homens os-vendo-os a a-glória-meu e-a as-sinais-meus que fiz em-o-Egito e-no-deserto e-eles-tentaram a-mim este dez vezes e-não ouviram na-voz-meu');
INSERT INTO verses VALUES (4132, 4, 14, 23, 'se e-veem-os a a-terra que eu-jurei não e-todo os-rejeitando-me não vejam-a');
INSERT INTO verses VALUES (4133, 4, 14, 24, 'e-meu-servo כלֵ֗ב ekev era espírito outra com-ele e-cheio depois-de-mim e-traga-o-a a a-terra que veio ali e-seu-herdeiro herdeiro-ele');
INSERT INTO verses VALUES (4134, 4, 14, 25, 'e o Amaleque e o Canaã habitante-de na-vala amanhã olhem e-parti a-vós o deserto o-caminho-de mar-de juncos');
INSERT INTO verses VALUES (4135, 4, 14, 26, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (4136, 4, 14, 27, 'até מָתַ֗י para-a-congregação a-malícia-a esta que eles malinim sobre mim a tulunot filhos-de Israel que eles malinim alai shama''ti');
INSERT INTO verses VALUES (4137, 4, 14, 28, 'disse a-eles vive אנני oráculo-de yhwh se não como falastes a-vós assim fazerei para-vocês');
INSERT INTO verses VALUES (4138, 4, 14, 29, 'em-o-deserto isto é yiflu pigreichechem e-todo pqudeichechem para-todo misparchechem מִבֶּ֛ן vinte ano e-para-cima que halinotem sobre-mim');
INSERT INTO verses VALUES (4139, 4, 14, 30, 'se vós tavu a a-terra que eu-elevei a minha-mão que vos nela porque se Kalev filho-de yefunneh e Josué filho-de Nun:');
INSERT INTO verses VALUES (4140, 4, 14, 31, 'e-vosso-tipo que אֲמַרְתֶּ֖ם para-saque será e-eu-trarei eles וְיָֽדְעוּ֙ וְיָדַעֻהוּ a a-terra que de-aborrecer-vos nela');
INSERT INTO verses VALUES (4141, 4, 14, 32, 'e-corpos-vossos vós יפלוּ em-o-deserto a-esta');
INSERT INTO verses VALUES (4142, 4, 14, 33, 'e-filhos-vossos יִהְי֨וּ רֹעִ֤ים bamidbar quarenta ano וְנָשְׂא֖וּ a זְנוּתֵיכֶ֑ם até perfeição פּגְרֵיכֶ֖ם no-deserto');
INSERT INTO verses VALUES (4143, 4, 14, 34, 'בּמִסְפַּ֨ר הימים que תרטטם a dia dia dia dia לשנה dia לשנה תישאוּ a עוןיכם quarenta ano e-voces-sabereis a תנואתי׃');
INSERT INTO verses VALUES (4144, 4, 14, 35, 'eu yhwh דברתי֒ se לא ׀ esta אעשה para-todo a congregação a-malícia-a esta os jurados sobre mim em-o-deserto este serão despedaçados e ali morrerão:');
INSERT INTO verses VALUES (4145, 4, 14, 36, 'e os homens que enviou Moisés para perseguir a a-terra e voltaram sobre-ele a todo a-congregação para-sair palavra sobre a-terra');
INSERT INTO verses VALUES (4146, 4, 14, 37, 'e-morreram os-homens os que tiram דִבַּת־ a-terra maldade בַּמַּגֵּפָ֖ה yhwh yhwh');
INSERT INTO verses VALUES (4147, 4, 14, 38, 'וִיהוֹשֻׁ֣עַ filho-de Nun וְכָלֵ֖ב filho-de יְפֻנֶּ֑ה חָיוּ֙ de os-homens aqueles הַֽהֹלְכִ֖ים a-explorar a a-terra');
INSERT INTO verses VALUES (4148, 4, 14, 39, 'e-falou Moisés a as-palavras estes a todo filhos-de muito וַיִּֽתְאַבְּל֥וּ o-povo muito');
INSERT INTO verses VALUES (4149, 4, 14, 40, 'e-levantaram-cedo em-a-manhã וַיַּֽעֲל֥וּ a dizendo o-monte dizendo הִנֶּ֗נּוּ e subiremos yhwh que que disse yhwh porque pecamos');
INSERT INTO verses VALUES (4150, 4, 14, 41, 'E-disse Moisés por-que isto vós passamos a yhwh yhwh não não te suceda');
INSERT INTO verses VALUES (4151, 4, 14, 42, 'a que porque yhwh yhwh em-meio-vosso e-não sereis-feridos diante-de inimigos-vossos');
INSERT INTO verses VALUES (4152, 4, 14, 43, 'que o amalequita e o cananeu nome diante-de-vós e cairão com a espada porque sobre assim yhwh de-depois-de yhwh e-não será yhwh com-vos');
INSERT INTO verses VALUES (4153, 4, 14, 44, 'e deram para-subir a cabeça o-monte e arão em-aliança-de yhwh וּמֹשֶׁ֔ה não מָ֖שׁוּ de-meio-de o-acampamento');
INSERT INTO verses VALUES (4154, 4, 14, 45, 'e-ele-descerrou הָעֲמָלֵקִי֙ וְהַֽכְּנַעֲנִ֔י o-que-habitava na-montanha aquele וַיַּכּ֥וּם וַֽיַּכְּת֖וּם até הַֽחָרְמָֽה׃');
INSERT INTO chapters VALUES (132, 4, 15, 41);
INSERT INTO verses VALUES (4155, 4, 15, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4156, 4, 15, 2, 'palavra a filhos-de Israel e-dirás que porque תָבֹ֗אוּ a terra מוֹשְׁבֹ֣תֵיכֶ֔ם que a-vós deu para-vocês');
INSERT INTO verses VALUES (4157, 4, 15, 3, 'e-fareis mulher a-yhwh holocausto ou זֶ֔בַח לְפַלֵּא־ נֶ֙דֶר֙ ou בִנְדָבָ֔ה ou בְּמֹעֲדֵיכֶ֑ם לַעֲשׂ֞וֹת רֵ֤יחַ agradável a-yhwh de o-bovino ou de o-rebanho');
INSERT INTO verses VALUES (4158, 4, 15, 4, 'e-ele-ofereceu o-maquive oferenda-sua para-יהוה oferta-cereais flor-farinha עִשָּׂר֔וֹן בָּל֕וּל בִּרְבִיעִ֥ית הַהִ֖ין azeite');
INSERT INTO verses VALUES (4159, 4, 15, 5, 'e vinho para o vaso quarta parte deste vinho farás sobre a-holocausto ou para o sacrifício o-primeiro o-um');
INSERT INTO verses VALUES (4160, 4, 15, 6, 'ou para a cabra farás oferenda farinha-de-trigo segundo dez misturada em-o-óleo terça parte deste vinho');
INSERT INTO verses VALUES (4161, 4, 15, 7, 'e-vinho para o vaso שְׁלִישִׁית הַהִ֑ין tu-oferecerás aroma-de tranquilidade para-יהוה');
INSERT INTO verses VALUES (4162, 4, 15, 8, 'e-quando תַעֲשֶׂה filho-de manhã holocausto ou זָ֑בַח לְפַלֵּא־ נֶ֥דֶר ou paz para-יהוה');
INSERT INTO verses VALUES (4163, 4, 15, 9, 'e-oferecerá sobre filho-de o-bovino oferenda farinha-de-trigo três dez בָּל֥וּל em-o-óleo metade-de deste vinho');
INSERT INTO verses VALUES (4164, 4, 15, 10, 'וְיַ֛יִן tu-oferecerás para-a-caneca metade a-isto mulher aroma-de agradavel para-יהוה');
INSERT INTO verses VALUES (4165, 4, 15, 11, 'assim será-feito para-o-vaca o-primeiro ou para-a-ove o-primeiro ou para-a-cabra nas-caprinos ou nas-velozes；');
INSERT INTO verses VALUES (4166, 4, 15, 12, 'como-num-contar que fazeis-vós assim fazei para-um como-multiplicidade-deles:');
INSERT INTO verses VALUES (4167, 4, 15, 13, 'todo o-azará fará- assim a estes para-oferecerem mulher aroma-de tranquilidade para-יהוה');
INSERT INTO verses VALUES (4168, 4, 15, 14, 'e-quando estrangeiro entre-vós estrangeiro ou que בְתֽוֹכְכֶם֙ para-gerações-vossas e fará mulher aroma-de tranquilidade a-yhwh como farão assim ele-fará');
INSERT INTO verses VALUES (4169, 4, 15, 15, 'o convênio lei uma a-vós e para o estrangeiro o estrangeiro estatuto-de eternidade para-gerações-vossas como vós como estrangeiro será diante-de yhwh');
INSERT INTO verses VALUES (4170, 4, 15, 16, 'torah uma e juízo um será a-vós e para o estrangeiro הַגָּ֥ר אִתְּכֶֽם׃');
INSERT INTO verses VALUES (4171, 4, 15, 17, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4172, 4, 15, 18, 'palavra a filhos-de Israel e-dirás a-eles בְּבֹֽאֲכֶם֙ a a-terra que eu מֵבִ֥יא vós ali');
INSERT INTO verses VALUES (4173, 4, 15, 19, 'e-será בַּאֲכָלְכֶ֖ם מִלֶּ֣חֶם a-terra תָּרִ֥ימוּ oferta a-yhwh');
INSERT INTO verses VALUES (4174, 4, 15, 20, 'רֵאשִׁית֙ עֲרִסֹ֣תֵכֶ֔ם חַלָּ֖ה Tirimú Terumá Kitrutimá Goren assim Tirimú a-ela');
INSERT INTO verses VALUES (4175, 4, 15, 21, 'Mereishít vossas-arcas vocês-serão a-yhwh Terumá Ledoroteichem:');
INSERT INTO verses VALUES (4176, 4, 15, 22, 'e-porque Tishgú e-não fareis a todo os-comandamentos estes yhwh palavra yhwh a Moisés');
INSERT INTO verses VALUES (4177, 4, 15, 23, 'a todo que yhwh yhwh a-vós pela-mão-de Moisés de yhwh que ordenou yhwh e a salvação para-gerações-de-vocês');
INSERT INTO verses VALUES (4178, 4, 15, 24, 'e-foi mãe das-olhos a congregação foi feita por inadvertência e fizeram todo a congregação touro um manhã um o holocausto por odor agradável a-yhwh e sua oferenda de farinha e sacrifício um e o carneiro- ovelhas um -de oferta de culpa:');
INSERT INTO verses VALUES (4179, 4, 15, 25, 'e-perdoar o-sacerdote sobre todo assembleia filhos-de a-eles e-perdoado-ficará ela porque Shaggáh ele e eles- -trouxeram a seu sacrifício yhwh a-יהוה e sua oferta de culpa diante-de yhwh sobre -deles:');
INSERT INTO verses VALUES (4180, 4, 15, 26, 'e perdoará para-todo a congregação filhos-de Israel e para o estrangeiro o estrangeiro que porque para-todo o-povo por engano;');
INSERT INTO verses VALUES (4181, 4, 15, 27, 'e-se uma uma se pecar por engano e trará vaca filha-de sua idade para-oferta-pelo-pecado');
INSERT INTO verses VALUES (4182, 4, 15, 28, 'e-perdoar o-sacerdote sobre a alma a que pecou por acidente em pecado em-erro yhwh yhwh para-expiar sobre-ele a-ele a-ele');
INSERT INTO verses VALUES (4183, 4, 15, 29, 'o azimut filhos-de Israel e para o estrangeiro o estrangeiro entre vós a lei uma será a-vós que faz por engano;');
INSERT INTO verses VALUES (4184, 4, 15, 30, 'e-a-alma que farás com a mão Rama de o azimut e-de ele a yhwh ele aquela e-ser-cortado a-alma a-essa de-meio-de a-sua-pena;');
INSERT INTO verses VALUES (4185, 4, 15, 31, 'que palavra-de yhwh com o báza e-a sua mandatória destruirás cortarás serás cortada aquela a-essa iniquidade em-ela');
INSERT INTO verses VALUES (4186, 4, 15, 32, 'e-foram filhos-de Israel no-deserto e-encontraram homem מְקֹשֵׁשׁ madeiras em-dia הַשַּׁבָּֽת׃');
INSERT INTO verses VALUES (4187, 4, 15, 33, 'וַיַּקְרִ֣יבוּ ele הַמֹּצְאִ֥ים ele מְקֹשֵׁשׁ עֵצִ֑ים a Moisés e-para Arão e-a todo הָעֵדָֽה׃');
INSERT INTO verses VALUES (4188, 4, 15, 34, 'וַיַּנִּ֥יחוּ ele בַּמִּשְׁמָ֑ר que não פֹרַ֔שׁ que a-ele a-ele');
INSERT INTO verses VALUES (4189, 4, 15, 35, 'E-disse yhwh a morrendo morrer será-morto o-homem ele a-ele-o em pedras todo a-congregação fora-de o-lager');
INSERT INTO verses VALUES (4190, 4, 15, 36, 'e saíram ele todo a congregação a de-fora ele e lançaram a-ele em pedras E-morreu yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (4191, 4, 15, 37, 'E-disse yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4192, 4, 15, 38, 'palavra a filhos-de Israel e-dirás a-eles a-eles para-eles cifteh sobre asas-de nos seus vestuários para as gerações sobre cifteh a borda פֹּתִיל תְּכֵלֶת׃');
INSERT INTO verses VALUES (4193, 4, 15, 39, 'e-foi a-vós לְצִיצִת֒ וּרְאִיתֶ֣ם ele וּזְכַרְתֶּם֙ a yhwh mandamentos-de eles e-fizerdes a-eles e-não תָתֻ֜רוּ vossos-olhos para-coracoes-vos e-depois-de עֵֽינֵיכֶ֔ם que vós זֹנִ֖ים depois-deles');
INSERT INTO verses VALUES (4194, 4, 15, 40, 'para-que תִּזְכְּר֔וּ e-fizerdes a e-sereis מִצְוֺתָ֑י vehitytem kedoshim para os seus elohim:');
INSERT INTO verses VALUES (4195, 4, 15, 41, 'eu yhwh Elohim-vossos que eu tirei vos da-terra Egito a-ser a-vós para os elohim eu yhwh vosso-Elohim');
INSERT INTO chapters VALUES (133, 4, 16, 35);
INSERT INTO verses VALUES (4196, 4, 16, 1, 'E-tomou Qorach filho-de Izhar filho-de Coate filho-de Levi e Datân e Abiram filhos-de Eliaabe e Úm filho-de Peleet filhos-de Reuven-verso');
INSERT INTO verses VALUES (4197, 4, 16, 2, 'e levantaram-se diante-de Moisés e homens filhos de Israel cinquenta e duzentos príncipes assembleia chamados encontro homens de nome');
INSERT INTO verses VALUES (4198, 4, 16, 3, 'e reuniram-se sobre Moisés e-sobre Arão e-disseram que chefe-de para vós porque todo yhwh כֻּלּם santos e-em yhwh e-por-que voc-voltareis sobre assembleia yhwh');
INSERT INTO verses VALUES (4199, 4, 16, 4, 'E-ouviu Moisés e-cairam sobre faces-suas');
INSERT INTO verses VALUES (4200, 4, 16, 5, 'e-falou a qorach dizendo manhã sua-cavalaria yhwh manhã e-saberá yhwh a-ele que para-ele e-a o-santo a-ele a-ela e-a que escolherá- nele aproximará a-ele');
INSERT INTO verses VALUES (4201, 4, 16, 6, 'esta fazei tomai para-vós cântaros  קֹ֖רַח e-todo  עֲדָתֽוֹ׃');
INSERT INTO verses VALUES (4202, 4, 16, 7, 'וּתְנ֣וּ  בָהֵ֣ן ׀  אֵ֡שׁ  וְשִׂימוּ֩  עֲלֵיהֶ֨ן ׀  קְטֹ֜רֶת diante-de yhwh amanhã yhwh o-homem que  יִבְחַ֥ר yhwh yhwh ele chefe-de a-vós filhos-de Levi');
INSERT INTO verses VALUES (4203, 4, 16, 8, 'E-disse Moisés a  קֹ֑רַח ouvi por-favor filhos-de Levi');
INSERT INTO verses VALUES (4204, 4, 16, 9, 'o-ma''at mi-kem porque hi-hibdil Elohim-de Israel vos me-eda''t Israel le-hakriv a-ele para-lavrar la''avod a yhwh tabernáculo-de yhwh ve-la''amod diante-de a-congregação le-shartam');
INSERT INTO verses VALUES (4205, 4, 16, 10, 'e-aproximou ot-cha e-a todo akh-echa filhos-de Levi contigo e buscareis também a-cunha:');
INSERT INTO verses VALUES (4206, 4, 16, 11, 'portanto tu e-todo a-convocação-te@ os-a-sorteados sobre yhwh que que ele porque sobre-ele');
INSERT INTO verses VALUES (4207, 4, 16, 12, 'e-enviou Moisés para-chamar a-datan e-a-abiram filhos-de Eliabe e-disseram não nossos-pedestres:');
INSERT INTO verses VALUES (4208, 4, 16, 13, 'o-que-pequeno que e-elevaste-nos@ de-terra-de derramou leite e mel para nos matar no-deserto porque תִשׂתָרֵ֥ר sobre nós também foi dominado');
INSERT INTO verses VALUES (4209, 4, 16, 14, 'certamente não a terra sangue leite e mel nos levaria e deu-nos para-nós herança שׂדה וָכָ֑רֶם הַעֵינֵ֞י os homens não תּנַקֵּ֖ר não nossos-pedestres:');
INSERT INTO verses VALUES (4210, 4, 16, 15, 'e se fez agradável a Moisés muito E-disse a yhwh a não a um não חֲמ֨וֹר um deles eu levantei-me e-não Harua''ti a um de-eles');
INSERT INTO verses VALUES (4211, 4, 16, 16, 'E-disse Moisés a tu tu e-todo a-convocação-te@ yhwh tu yhwh tu Vahe''m e-Aarão amanhã');
INSERT INTO verses VALUES (4212, 4, 16, 17, 'Ukachu homem seu-tronco-de-fogo Uneta''tem sobre-eles Ketoret Ve''hikravtem diante-de yhwh yhwh Machatho cinquenta Um''ayim Machoth ve-a-ta-ha e-Aarão homem a-mo');
INSERT INTO verses VALUES (4213, 4, 16, 18, 've-yikhu homem seu-tronco-de-fogo e-eles-deram sobre-eles fogo e-os-colocaram sobre-eles fumo-de-oferenda e-va-amadu entrada-de tenda encontro e-moshe e-Aarão');
INSERT INTO verses VALUES (4214, 4, 16, 19, 'e-vay-qahel sobre-alehem qorach a todo a-congregação a entrada tenda reunião E-viu glória-de- yhwh a todo a-edah');
INSERT INTO verses VALUES (4215, 4, 16, 20, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (4216, 4, 16, 21, 'se-hibdalu de-meio-de a-edah esta e-va-achaluhu eles momento:');
INSERT INTO verses VALUES (4217, 4, 16, 22, 'caíram: sobre suas-faces: e-disseram El Elohim-de הרוחות para-todo um o-homem um pecaram: e-sobre todo a-congregação levantar-se:');
INSERT INTO verses VALUES (4218, 4, 16, 23, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4219, 4, 16, 24, 'palavra a dizendo dizendo levantaram-se: de-ao-redor para-o-acampamento: Corá: Datan: E o Abiram:');
INSERT INTO verses VALUES (4220, 4, 16, 25, 'E-levantou Moisés E-andou a Datân e o Abiram e-caminharam atrás-dele anciãos-de Israel');
INSERT INTO verses VALUES (4221, 4, 16, 26, 'e-falou a dizendo dizendo afastem-se de-cima-de de cima as tendas dos os-homens rebelados estes e-a a-eles em-todo que para-eles para-que-não continuaram em-todo a sua culpa:');
INSERT INTO verses VALUES (4222, 4, 16, 27, 'e subiram de-cima-de do tabernáculo- קֹרֶח Datan: וַאֲבִירָּם em-o-redor e Datân e Abiram saíram נִצָּבִ֗ים פֶּ֚תַח אֽ͏ָהֳלֵיהֶ֔ם וּנְשֵׁיהֶ֥ם e-seus-filhos וְטַפָּֽם׃');
INSERT INTO verses VALUES (4223, 4, 16, 28, 'E-disse Moisés nisto sabereis porque yhwh שֶׁלַחַנִי לַעֲשׂוֹת a todo הַמְּעָשֹׂ֖ים estes porque não מִלֵּבִֽי׃');
INSERT INTO verses VALUES (4224, 4, 16, 29, 'se como mortes todo Estas יְמוּתוּן אֵלֶּה וּפְקֻדָּת֙ todo não yhwh sobre-eles não yhwh שֶׁלַחָנִי׃');
INSERT INTO verses VALUES (4225, 4, 16, 30, 'e-se בְּרִיאָה yhwh yhwh a-terra a terra a eles e engolirá a-eles e-a vida que a-eles que חיים o abismo e saberéis porque serão apertados os homens estes a yhwh');
INSERT INTO verses VALUES (4226, 4, 16, 31, 'e-houve quando ele for consumido para falar a todo as-palavras estes a-terra a terra que sob eles');
INSERT INTO verses VALUES (4227, 4, 16, 32, 'e abriu a-terra a boca-dela eles eles e-a nas suas e-a todo o homem que para Corá e-a todo a riqueza');
INSERT INTO verses VALUES (4228, 4, 16, 33, 'e desceram eles e-todo a-eles vida חיים o abismo e cobriu a-terra a-terra e-pereceram de-meio o povo');
INSERT INTO verses VALUES (4229, 4, 16, 34, 'e-todo Israel que seus redutos nassu que porque disseram a-terra tiblā''enu a-terra');
INSERT INTO verses VALUES (4230, 4, 16, 35, 'e-fogo yats''āh de-junto-de yhwh e-comeste a haḥamishšîm u''ma''ăṭayim homem maqribe haqtōret');
INSERT INTO chapters VALUES (134, 4, 17, 28);
INSERT INTO verses VALUES (4231, 4, 17, 1, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4232, 4, 17, 2, 'disse a El''azar filho-de Aarão o-sacerdote ve''yarem a hamachăttoth מִבֵּ֣ין que e-a o-fogo זְרֵה־ הָ֑לְאָה porque קָדֵֽשׁוּ׃');
INSERT INTO verses VALUES (4233, 4, 17, 3, 'אֵ֡ת מַחְתּוֹת֩ הֽ͏ַחַטָּאִ֨ים ha-eleh בְּנַפְשֹׁתָ֗ם וְעָשׂ֨וּ eles רִקֻּעֵ֤י פחמים כיפוי למזבח porque הקריבו diante-de yhwh ויקדו ויהיו para-sinal para-filhos-de Israel');
INSERT INTO verses VALUES (4234, 4, 17, 4, 'E-tomou Eleazar o-sacerdote a מחות הנחושת que הקריבו השרפים e estendessem cobertura para o altar:');
INSERT INTO verses VALUES (4235, 4, 17, 5, 'lembrete aos-filhos-de Israel para-propósito-de que não virá homem estrangeiro não não da semente ele ele para-queimar incenso yhwh yhwh e-não ser-á como coraich e com a congregação dele yhwh palavra a-ele por-mão-de Moisés a-ele');
INSERT INTO verses VALUES (4236, 4, 17, 6, 'e-negaram todo congregação-de filhos-de Israel de-amanhã dizendo Moisés e-sobre Aarao yhwh vós vocês-mataram a povo yhwh');
INSERT INTO verses VALUES (4237, 4, 17, 7, 'e-houve em-reunião a-assembly sobre Moisés e-sobre Arão e-voltaram-se a tenda encontro e-eis cobriram yhwh E-viu glória yhwh');
INSERT INTO verses VALUES (4238, 4, 17, 8, 'E-veio Moisés e-Aarão a face-de tenda encontro');
INSERT INTO verses VALUES (4239, 4, 17, 9, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4240, 4, 17, 10, 'e-elevaram-se de-meio-de a-edah esta e-comeram eles em-breve e-caíram sobre em-seus-faces');
INSERT INTO verses VALUES (4241, 4, 17, 11, 'E-disse Moisés a Arão toma a a-ferida de-cima-de עָלֶ֨יהָ אֵ֜שׁ de-sobre o-altar וְשִׂ֣ים Ketoret וְהוֹלֵ֧ךְ מְהֵרָ֛ה a a-congregação e-perdoa yhwh porque יָצָ֥א הַקֶּ֛צֶף de-a-frente-de yhwh הֵחֵ֥ל הַנָּֽגֶף׃');
INSERT INTO verses VALUES (4242, 4, 17, 12, 'E-tomou Arão como-que palavra Moisés e-o correu a dentro-de o-a congregação e-eis começou-o a a-punhalada no-povo-o E-colocou a o-a fragrância e-o expiou sobre o-povo');
INSERT INTO verses VALUES (4243, 4, 17, 13, 'e-estabeleceu entre e-entre e-entre os-videntes e-a parou-se a-punhalada-verso');
INSERT INTO verses VALUES (4244, 4, 17, 14, 'e houveram os mortos na praga quatro dez mil e sete centenas além-de os-mortos sobre palavra-de qó-rakh');
INSERT INTO verses VALUES (4245, 4, 17, 15, 'e-ele-retornou Arão a Moisés a entrada tenda reunião e a praga foi interrompida');
INSERT INTO verses VALUES (4246, 4, 17, 16, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4247, 4, 17, 17, 'disse a filhos-de Israel e toma deles cetro máta lebeith pai me''et todo nesihehem para-casa-de pais-deles dois dez mattot homem a seu-nome tikhtob sobre mattehu');
INSERT INTO verses VALUES (4248, 4, 17, 18, 'e-את nome Arão tikhtob sobre tribo-de que porque um um lerosh casa avos-eus');
INSERT INTO verses VALUES (4249, 4, 17, 19, 'vehinachtem em-tenda-de reunião diante-de הָעֵד֔וּת que אִוָּעֵ֥ד a-vós ali');
INSERT INTO verses VALUES (4250, 4, 17, 20, 'e-foi o-homem que אֶבְחַר־ nele מַטֵּ֣הוּ יִפְרָ֑ח וַהֲשִׁכֹּתִ֣י מֵֽעָלַ֗י a תְּלֻנּוֹת֙ filhos-de eles que eles מַלִּינִ֖ם sobre-vós');
INSERT INTO verses VALUES (4251, 4, 17, 21, 'e-falou Moisés a filhos-de Israel a-ele אֵלָ֣יו ׀ todo נשיאיהם máta um um מטה um um para-casa-de pais-deles dois dez mattot ומטה no-meio-de em-meio-de mótuwám');
INSERT INTO verses VALUES (4252, 4, 17, 22, 'וישן Moisés a המטות yhwh yhwh na-tenda ha-edut:');
INSERT INTO verses VALUES (4253, 4, 17, 23, 'e-houve da-o E-veio Moisés a tenda העדות e-eis פרח bastao-de- Aarao para-casa-de Levi e-saiu perach e-foceu tsits e-cortou shakedim');
INSERT INTO verses VALUES (4254, 4, 17, 24, 'e-saiu Moisés a todo yhwh de-diante-de yhwh a todo filhos-de Israel e-eles-deram-conta e tomaram homem mattehu');
INSERT INTO verses VALUES (4255, 4, 17, 25, 'E-disse yhwh a Moisés hasheb a tribo-de Arão diante-de hadevedut para a guarda para-sinal para-filhos-de méri e terminem suas lamentações sobre mim e-não morram');
INSERT INTO verses VALUES (4256, 4, 17, 26, 'E-fez Moisés como ordenou yhwh ele assim fez');
INSERT INTO verses VALUES (4257, 4, 17, 27, 'e-disseram filhos-de Israel a dizendo eis eis que nos arrependemos nós morremos todos nós');
INSERT INTO verses VALUES (4258, 4, 17, 28, 'todo o que se aproxima ha-qarav a tabernáculo-de yhwh morra se é que vocês se purifiquem para tocarem');
INSERT INTO chapters VALUES (135, 4, 18, 32);
INSERT INTO verses VALUES (4259, 4, 18, 1, 'E-disse yhwh a tu tu e seus filhos e-casa-de teu-pai com-tu vocês carreguem a iniquidade o santuário e-tu e-filhos-teu com-tu vocês carreguem a iniquidade-de sua função sacerdotal');
INSERT INTO verses VALUES (4260, 4, 18, 2, 'e-também a seu-irmão matteh- Lévi tribo-de teu-pai que-approxime-se com-tu e-ajam sobre-ti e-manter-se-ão-com-teu e-tu e-filhos-teu com-tu diante-de tenda ha-edut:');
INSERT INTO verses VALUES (4261, 4, 18, 3, 'e-guardar-se-ão de-teu-guarnecimento e-guarda todo haohel só-que a os-ferramentas-de-serviço não e-a o-altar não aproximem-se e-não yeremutu também eles também atemu:');
INSERT INTO verses VALUES (4262, 4, 18, 4, 'venilvu sobre-ti veshameuru a guarda-de tenda a-todo para-todo avodat haohel vezar não yikra a-vós');
INSERT INTO verses VALUES (4263, 4, 18, 5, 'ushamartem a de-guarda o-santuário e-a de-guarda o-altar e-não será ainda ketsef sobre filhos-de Israel');
INSERT INTO verses VALUES (4264, 4, 18, 6, 'e-eu eis tom-eu a irmãos-vossos os-levitas de-meio-de filhos-de a-vós lachem  Mitsubishi  doados para-lavrar la-avod a avodat tenda-de encontro');
INSERT INTO verses VALUES (4265, 4, 18, 7, 'e-tu e-filhos-teu com-te guardareis a vossa sacerdócio para-todo palavra o-altar e-no lar à arca e-servireis avodat  Mitsubishi  אֶתּוֹ a כְּהֻנָּתְכֶ֔ם e-o-estranho o-que-se-aproxima será-morto');
INSERT INTO verses VALUES (4266, 4, 18, 8, 'e-falou yhwh a Aharon- eis dei a-ti para-ti a guarda-de תְּרוּמֹתַ֑י a-ti קָדְשׁוֹ filhos-de Israel לְךָ֨ נְתַתֶּם לְמָשְׁחָה e-aos-seus-filhos por-tempo eternidade');
INSERT INTO verses VALUES (4267, 4, 18, 9, 'este- a-ti para-ti מִקֹּדֶשׁ הַקֳּדָשִׁ֖ים de o-fogo todo קָ֠רְבֻּנָם para-todo מִנְחָתָם e-para-todo- חַטָּאתָם e-para-todo- a-ti ele יָשִׁ֣יבוּ para-mim santo-de קָֽדָשִׁ֥ים para-ti ele וּלְבָנֶֽיךָ׃');
INSERT INTO verses VALUES (4268, 4, 18, 10, 'בְּקֹ֥דֶשׁ הַקֳּדָשִׁ֖ים תֹּאכֲלֶ֑נּוּ todo macho ele a-ele santidade ele-será- para-ti');
INSERT INTO verses VALUES (4269, 4, 18, 11, 'e-este לְּךָ֞ oferta-de מַתָּנָ֗ם para-todo תּוֹנֻפֹת a-ti Israel para-ti נְתַתֶּ֣יךָ וְלִבְנֵ֥י וְלִבְנוֹתֵיכֶ֖ם contigo por-tempo eternidade ele puro em-casa-tua comerá a-ele');
INSERT INTO verses VALUES (4270, 4, 18, 12, 'todo חֵּ֣לֶב Yit-shar e-todo gordura תִּירוֹשׁ וְדַגַּֽן רֵאשִׁ֤יתָם que a-ti a-yhwh para-ti נְתַתֶּ֣יךָ׃');
INSERT INTO verses VALUES (4271, 4, 18, 13, 'בְּכֻרֵ֤י todo que em-terra que a-ti será para-ti yihye todo puro em-casa-tua comerão');
INSERT INTO verses VALUES (4272, 4, 18, 14, 'todo herem a-ti será será');
INSERT INTO verses VALUES (4273, 4, 18, 15, 'todo pêter rechem para-todo carne que e-sobre-os-animais para-יהוה em-homem e-com-o-gado ele-será- para-ti somente pede o-homem את primogênito-de o-homem e-a em-o-primeiro-nato a-animais o-imundo tífdeh');
INSERT INTO verses VALUES (4274, 4, 18, 16, 'úpfdúyav de-filho-de novo tífdeh b''urkakkha prata cinco-de escalam em-siclo a-santidade vinte ele ela');
INSERT INTO verses VALUES (4275, 4, 18, 17, 'porém b''bkór- shór ou b''bkór keshév não b''bkór ''ez eles você livrará santo-de eles a o sangue deles tu lançarás sobre o-altar e-a seu óleo tu ungi mulher para-aroma tranquilidade para-יהוה');
INSERT INTO verses VALUES (4276, 4, 18, 18, 'e a carne deles ser- para-ti como a visão a oferta de levita e o desejo a-ti será será');
INSERT INTO verses VALUES (4277, 4, 18, 19, 'todas ofertas os-santos que irámu filhos-de Israel para-יהוה dei a-ti úlebánécha vélibnóteicha contigo por-tempo eternidade beríth eternidade ela ela-foi yhwh a-ti a-ti úlezáraz''acha contigo');
INSERT INTO verses VALUES (4278, 4, 18, 20, 'E-disse yhwh a Arão não não tinhal vécheléq a-ti será a-ti entre vós eu no-meio-de vénaḥlát''echa em-meio-de filhos-de Israel');
INSERT INTO verses VALUES (4279, 4, 18, 21, 'e-para-filhos-de Levi eis dei todo maʿásér em-Israel para herança substituição sua servidão que eles servos a avodat tenda-de encontro');
INSERT INTO verses VALUES (4280, 4, 18, 22, 'e-não se aproximem ainda filhos-de Israel a tenda reunião para-levar pecado para a morte');
INSERT INTO verses VALUES (4281, 4, 18, 23, 'e servir-se-ão o levita ele a serviço-dele tenda encontro e-eles levem עֲוֺנָ֑ם eternidade eterno para-gerações-vossas e-dentro filhos-de não não herdarão herança');
INSERT INTO verses VALUES (4282, 4, 18, 24, 'que a dezimo filhos-de Israel que levantar-se-ão dei oferta dei aos levitas para herança a-eles no-meio-de eu-disse a-eles não filhos-de Israel não herdarão herança');
INSERT INTO verses VALUES (4283, 4, 18, 25, 'e-falou yhwh a Moisés dizendo');
INSERT INTO verses VALUES (4284, 4, 18, 26, 'e-a os levitas diga e-dirás אֲלֵהֶם֒ porque תִ֠קְחוּ de-a filhos-de dei a-vós הַֽמַּעֲשֵׂ֗ר que נָתַ֧תִּי nós מֵאִתָּ֖ם yhwh וַהֲרֵמֹתֶ֤ם do-que-ele yhwh decimo de הַֽמַּעֲשֵֽׂר׃');
INSERT INTO verses VALUES (4285, 4, 18, 27, 'וְנֶחְשַׁ֥ב a-vós תְּרוּמַתְכֶ֑ם כַּדָּגָן֙ de הַגֹּ֔רֶן וְכַֽמְלֵאָ֖ה de a-cavidade:');
INSERT INTO verses VALUES (4286, 4, 18, 28, 'assim תָּרִ֤ימוּ também vós yhwh de-toda de-todo a vossas décimas que תִּקְח֔וּ de-com filhos-de Israel nós do-que-ele yhwh oferta-de yhwh para-Aarão o-sacerdote');
INSERT INTO verses VALUES (4287, 4, 18, 29, 'de-toda a vossos donativos תָּרִ֕ימוּ a todo yhwh yhwh de-todo nós a מִקְדְּשׁ֖וֹ de-nós');
INSERT INTO verses VALUES (4288, 4, 18, 30, 'e-dirás a-eles בַּהֲרִֽימְכֶ֤ם a nós dele וְנֶחְשַׁב֙ aos levitas kituba''at goren e kituba''at jaque:');
INSERT INTO verses VALUES (4289, 4, 18, 31, 'e-voces-comeram ele em-todo lugar vós e vossa casa ele a-vós ele a-vós substituição vossa obra em-tenda encontro');
INSERT INTO verses VALUES (4290, 4, 18, 32, 'e-não levantai-vos sobre-ele erro levantastes-vos nós gordura-sua de-ele não santos filhos-de Israel não desvendastes e-não morrais;');
INSERT INTO chapters VALUES (136, 4, 19, 22);
INSERT INTO verses VALUES (4291, 4, 19, 1, 'e-falou yhwh a Moisés dizendo אַהֲרֹן para-dizer');
INSERT INTO verses VALUES (4292, 4, 19, 2, 'esta lei ha-torah que yhwh dizendo dizendo disse a filhos-de Israel e-eles-tomem a-te frutificai vermelho puro que não-há nela מום que não subiu sobre-ela sobre');
INSERT INTO verses VALUES (4293, 4, 19, 3, 'ונתתם a-ela a Elazar o-sacerdote e-sairá a-ela a de-fora para-o-machane e-ele-degolará a-ela diante-de-ele');
INSERT INTO verses VALUES (4294, 4, 19, 4, 'e-tome אלעזר o-sacerdote מדמהה בקצבעהו e-aspergirá a face-de face-de tenda-de encontro מדמהה sete vezes');
INSERT INTO verses VALUES (4295, 4, 19, 5, 'e-queimará a הפרה לאعينו a עוריה e-a בשרתה e-a dama-hu sobre פרשה ישורף׃');
INSERT INTO verses VALUES (4296, 4, 19, 6, 'e-tome o-sacerdote árvore ארז ואזוב ושני tela e arremessou a em fogueira da vaca');
INSERT INTO verses VALUES (4297, 4, 19, 7, 'e enxaguou suas vestes o-sacerdote e lavou seu corpo em água e-depois virá a o-acampamento e-o-contaminará o-sacerdote até no entardecer');
INSERT INTO verses VALUES (4298, 4, 19, 8, 'e o queimou a-ela היה-מכס בגדיו em água e-lavará a-carne-dele nas-águas ויטמא até הערבה׃');
INSERT INTO verses VALUES (4299, 4, 19, 9, 'ואסף homem טהור a אפר הפרה והניח de-fora para-o-acampamento em-o-loco puro והיהת לאדת filhos-de Israel לְמִשְׁמֶ֛רֶת לְמֵ֥י נִדָּ֖ה חַטָּ֥את ela');
INSERT INTO verses VALUES (4300, 4, 19, 10, 'וְ֠כִבֶּס הָאֹסֵ֨ף a אֵ֤פֶר הַפָּרָה֙ a as-roupas-seu וְטָמֵ֖א até a-tarde וְֽהָיְתָ֞ה aos-filhos-de Israel e-no ger eternidade no-entre-vocês para-a-lei eternidade');
INSERT INTO verses VALUES (4301, 4, 19, 11, 'da-pessoa-que-tocou no-morte para-todo homem homem e-impuro sete dias');
INSERT INTO verses VALUES (4302, 4, 19, 12, 'ele será-limpo- no-dia no-dia o-terceiro e no dia ha-shevi-i será-limpo e-se no-dia será purificado no dia o terceiro não ha-shevi-i não será purificado');
INSERT INTO verses VALUES (4303, 4, 19, 13, 'todo o que tocou em morto o-homem o-homem que morre e-não yhwh a tabernáculo yhwh aquela e-ser-cortado que a-essa de-Israel porque água menstruação será זֹרַ֤ק sobre-ele nele será a-ele טֻמְאָת֥וֹ nele-verso');
INSERT INTO verses VALUES (4304, 4, 19, 14, 'esta ha-torah homem porque יָמ֣וּת בְּאֹ֑הֶל todo הַבּ֤א a הָאֹ֙הֶל֙ e-todo que בָּאֹ֔הֶל ele-se-tornará-impuro sete dias');
INSERT INTO verses VALUES (4305, 4, 19, 15, 'e-tudo instrumento פָת֔וּחַ que não-há צָמִ֥יד פָּתִ֖יל sobre-ele ele ela');
INSERT INTO verses VALUES (4306, 4, 19, 16, 'e-tudo que irá sobre face-de o-campo no santuário- espada homem na morte ou em homem ou no sepulcro ele-se-tornará-impuro sete dias');
INSERT INTO verses VALUES (4307, 4, 19, 17, 'e-tomarão para se tornar impuro do pó de queimadura a-oferta-pelo-pecado e colocou sobre-ele águas vida a כֶּֽלִי׃');
INSERT INTO verses VALUES (4308, 4, 19, 18, 'e-tome arqueiro e imergir בַּמַּיִם֮ homem טָהוֹר֒ וְהִזָּ֤ה sobre הָאֹ֙הֶל֙ e-sobre todo os-vasos e-sobre הַנְּפָשׁ֖וֹת que foram- nome e-sobre הַנֹּגֵ֗עַ בַּעֶ֙צֶם֙ ou בֶֽחָלָ֔ל ou בַמֵּ֖ת ou בַקָּֽבֶר׃');
INSERT INTO verses VALUES (4309, 4, 19, 19, 'e separou o puro sobre no-dia no-dia o terceiro e-no-dia o sétimo no-dia no-dia o-sétimo e lavou suas vestes e-lavará nas-aguas e purificou no-o-crepúsculo');
INSERT INTO verses VALUES (4310, 4, 19, 20, 'e-homem que será contaminado e-não será santificado e-ser-cortado aquela a-essa do-meio-de que porque yhwh santuário yhwh tame águas-de niddah não ele sobre-ele a-vós ela');
INSERT INTO verses VALUES (4311, 4, 19, 21, 'e-será lhem para a lei eternidade e este águas-de niddah purificará as-roupas-seu e o que tocou em-águas-de a niddah ele-se-tornará-impuro até no entanto');
INSERT INTO verses VALUES (4312, 4, 19, 22, 'e-tudo que [הַטָּמֵ֖א] [יִטְמָ֑א] [וְהַנֶּ֥פֶשׁ] [הַנֹּגַ֖עַת] [תִּטְמָ֥א] [עַד־הָעָֽרֶב׃] até');
INSERT INTO chapters VALUES (137, 4, 20, 29);
INSERT INTO verses VALUES (4313, 4, 20, 1, 'e-vieram filhos-de Israel todo הָ֨עֵדָ֤ה no deserto- צִן֙ no-mês הָֽרִאשׁ֔וֹן e-habitou o-povo בְּקָדֵ֑שׁ e-morreu nome Miryā'' Vatikkāber nome');
INSERT INTO verses VALUES (4314, 4, 20, 2, 'e-não águas águas Lāʿēdāh Vayikkāhalū sobre Moisés e-sobre Aharon');
INSERT INTO verses VALUES (4315, 4, 20, 3, 'Vayyarēb o-povo com Moisés dizendo dizendo Ve''lū Gāvānū Biggāʿ Akhēnu yhwh yhwh');
INSERT INTO verses VALUES (4316, 4, 20, 4, '[וְלָמָ֤ה] [הֲבֵאתֶם֙] a yhwh yhwh a [לָמ֣וּת] este [אֲנַ֖חְנוּ] nome');
INSERT INTO verses VALUES (4317, 4, 20, 5, 'וְלָמָ֤ה הֶֽעֱלִיתֻ֙נוּ֙ do-Egito לְהָבִ֣יא a-nós a o-lugar a-má não לא ׀ lugar semente וּתְאֵנָ֤ה וְגֶ֙פֶן֙ וְרִמּ֔וֹן e-aquém não-havia lishtho');
INSERT INTO verses VALUES (4318, 4, 20, 6, 'E-veio Moisés e-Aharon de-diante-de o-a congregação a porta-de tenda encontro e-caíram sobre peneyhem E-viu glória-de- yhwh a-eles');
INSERT INTO verses VALUES (4319, 4, 20, 7, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4320, 4, 20, 8, 'toma a o-a vara e-reúne-te tu a-as assembleias tu e-Aharôn irmão-teu e-convirais a o-a pedra le-einehem a-eles águas וְהוֹצֵאתָ֨ a-eles águas de o-a pedra e-irrigará-vos a a-congregação e-a na-as Urã');
INSERT INTO verses VALUES (4321, 4, 20, 9, 'E-tomou Moisés a o mâtê yhwh yhwh como ordenou-o');
INSERT INTO verses VALUES (4322, 4, 20, 10, 'vayiqhûlû Moisés e-Aharon a a-congregação a E-disse a-eles E-disse a-eles ouvi por-favor os môrîm a-vós o-sela esta nôtsi''â a-vós águas');
INSERT INTO verses VALUES (4323, 4, 20, 11, 'vayyârêm Moisés a mão-sua vayyakkh a o sêlakh com o mâtê-hû águas vayyats''û águas muitos vatash''tô a-congregação e em Ur:');
INSERT INTO verses VALUES (4324, 4, 20, 12, 'E-disse yhwh a Moisés e-a Aharon- porque não vocês crístes em-mim para santificá-me aos-olhos-de não Israel portanto não trouvéis a a-eles esta a a-terra que dei para-eles');
INSERT INTO verses VALUES (4325, 4, 20, 13, 'eles águas-de em Meribá que רבו filhos-de Israel a yhwh e foi santificado em-eles');
INSERT INTO verses VALUES (4326, 4, 20, 14, 'e-enviou Moisés מלאכים santificação a rei Edom disse disse אָחִ֣יךָ tu tu soubeste a todo a tentação que e nos acharam');
INSERT INTO verses VALUES (4327, 4, 20, 15, 'e desceram nos pais Egito-para e-nos-abrigamos em-Egito dias muitos e-levaram-no-nós para-nós Egito e-para-os-pais-nossos:');
INSERT INTO verses VALUES (4328, 4, 20, 16, 'e-chamamos a yhwh E-ouviu nossa-voz e-enviou an anjo e-nos-saiu de-Egito e-eis nós em-sanidade cidade extremidade no-seu-limite:');
INSERT INTO verses VALUES (4329, 4, 20, 17, 'nós-fomos-queimados- agora não não נַעֲבֹר֙ em-campo וּבְכֶ֔רֶם e-não נִשְׁתֶּ֖ה águas-de o-caminho-de caminho o-rei não não נִטֶּה֙ direita até até que נַעֲבֹ֖ר גְּבוּלֶֽךָ׃');
INSERT INTO verses VALUES (4330, 4, 20, 18, 'E-disse a-ele Edom não passes em-mim para-que-não com-a-espada אֵצֵ֥א לִקְרָאתֶֽךָ׃');
INSERT INTO verses VALUES (4331, 4, 20, 19, 'e-disseram a-ele filhos-de Israel בַּֽמְסִלָּ֣ה נַעֲלֶה֒ e-se dos-teus-mãos nós-berremos eu e-das-minhas e-eu-darei das-mãos somente não-há palavra com-meus-pés eu-passarei');
INSERT INTO verses VALUES (4332, 4, 20, 20, 'E-disse não passem e-saiu Edom ao-encontro-dele no-povo pesado e-na-mão forte');
INSERT INTO verses VALUES (4333, 4, 20, 21, 'e recusou-se Edom deu a Israel passar por seu limite e-virou Israel dele');
INSERT INTO verses VALUES (4334, 4, 20, 22, 'e-partiram desde o Santuário e chegaram a filhos-de Israel todo a-congregação Hor a-montanha');
INSERT INTO verses VALUES (4335, 4, 20, 23, 'E-disse yhwh a Moisés e-a Aarao em Hor o-monte dizendo fronteira-de terra-de Edom para-dizer');
INSERT INTO verses VALUES (4336, 4, 20, 24, 'se juntou Arão a que não não virá a dei que dei sobre Israel sobre que meritem a o meu lamei mərivá:');
INSERT INTO verses VALUES (4337, 4, 20, 25, 'qach a Arão e-a Elazar eles veha''ala eles hor a-montanha');
INSERT INTO verses VALUES (4338, 4, 20, 26, 'vehapshet a Arão a as-roupas-seu vehilbashtam a Eleazar filho-seu e-Aharon ye''asaf e-ele-morreu nome');
INSERT INTO verses VALUES (4339, 4, 20, 27, 'E-fez Moisés como ordenou yhwh e-eles-subiram a hor o-monte aos-olhos-de todo הָעֵדָֽה׃');
INSERT INTO verses VALUES (4340, 4, 20, 28, 'e estendeu Moisés a Arão a eles e vestiu eles a Eleazar seu-filho E-morreu Aarao nome na-cabeça o-monte e desceu Moisés Elazar de a-montanha');
INSERT INTO verses VALUES (4341, 4, 20, 29, 'e-eles-viram todo que porque tremeu Aarão e choraram a dia trinta dia todo casa Israel');
INSERT INTO chapters VALUES (138, 4, 21, 35);
INSERT INTO verses VALUES (4342, 4, 21, 1, 'E-ouviu o cananeu rei-de Arad habitou que porque veio o-caminho-de caminho os atarim e lutou em-Israel e-o havia-se nós sevi:');
INSERT INTO verses VALUES (4343, 4, 21, 2, 'e-darrou Israel neder a-yhwh E-disse se deu dar-ias-te a o-povo este por-mi e-acharrei-te a suas-cidades:');
INSERT INTO verses VALUES (4344, 4, 21, 3, 'E-ouviu yhwh com-voz Israel E-colocou a o-kenaani e-acharrou a-eles E-chamou suas-cidades E-chamou nome-de o-lugar Hormá');
INSERT INTO verses VALUES (4345, 4, 21, 4, 'e saíram do monte o-montanha o-caminho-de mar-de Suf [אֶת־אֶ֣רֶץ] a terra Edom e faltou alma-de o-povo no-caminho');
INSERT INTO verses VALUES (4346, 4, 21, 5, 'e-falou o-povo em Elohim, e em Moisés, por-que levai-nos do-Egito para-morrer no-deserto que não-há pão e-não-há águas e nossas almas faltou em pão o queleque:');
INSERT INTO verses VALUES (4347, 4, 21, 6, 'e enviou yhwh no povo a as serpentes as ardentes e picaram a o-povo E-morreu com muito מִיִּשְׂרָאֵֽל׃');
INSERT INTO verses VALUES (4348, 4, 21, 7, 'E-veio o-povo a Moisés e-disseram nos arrependemos porque falamos em-יהוה e a ti intercede a yhwh וְיָסֵ֥ר מֵעָלֵ֖ינוּ a הַנָּחָ֑שׁ e-ele-orou Moisés por-causa-de o-povo');
INSERT INTO verses VALUES (4349, 4, 21, 8, 'E-disse yhwh a Moisés a-ti a-ti שָׂרָ֔ף ele ele sobre נֵ֑ס e-foi ele הַנָּשׁ֔וּךְ bom a-ele e-viveu');
INSERT INTO verses VALUES (4350, 4, 21, 9, 'E-fez Moisés נְחַ֣שׁ bronze וַיְשִׂמֵ֖הוּ sobre הַנֵּ֑ס e-foi se נָשַׁ֤ךְ o nāchāš a homem e olhou a nāchāš a nāchōšet e-viveu');
INSERT INTO verses VALUES (4351, 4, 21, 10, 'e-partiram filhos-de Israel e-acamparam nas ōvot');
INSERT INTO verses VALUES (4352, 4, 21, 11, 'e-partiram de ōvot e acamaram-se nas uiyê os abarim bamidbar que sobre face-de Moabe do mizraḥ o-sol');
INSERT INTO verses VALUES (4353, 4, 21, 12, 'de-lá NASAU e-acamparam BENACHAL Zerede');
INSERT INTO verses VALUES (4354, 4, 21, 13, 'MISHAM NASAU VA''YACHNU ME''EBER ARNON que no-deserto HAYOTZEA MIGVUL HA''EMORI que ארנון fronteira Moabe entre Moabe e-entre o-amorreu');
INSERT INTO verses VALUES (4355, 4, 21, 14, 'sobre [יֵֽאָמַ֔ר] [בְּסֵ֖פֶר] [מִלְחֲמֹ֣ת] yhwh yhwh a [וְאֶת־הַנְּחָלִ֖ים] [אַרְנֽוֹן] e-[OBJ]');
INSERT INTO verses VALUES (4356, 4, 21, 15, 'ואשעד הנהליים que na-tah לשבט ער וְנִשְׁעַ֖ן לִגְב֥וּל Moabe');
INSERT INTO verses VALUES (4357, 4, 21, 16, 'e-de-lá בְּאֵ֑רָה ela הַבְּאֵ֗ר que disse yhwh לְמֹשֶׁ֔ה אֱסֹף֙ a o-povo a-eles a-eles águas');
INSERT INTO verses VALUES (4358, 4, 21, 17, 'então יָשִׁ֣יר Israel a הַשִּׁירָ֖ה esta עֲלִ֥י בְאֵ֖ר anu- a-ela');
INSERT INTO verses VALUES (4359, 4, 21, 18, 'be''er chafaruhah sarim karuhah nedivei o-povo bimakhokek bemish''anaotam וּמִמִּדְבָּר matnah');
INSERT INTO verses VALUES (4360, 4, 21, 19, 'u-mimatnah נַחֲלִיאֵ֑ל וּמִנַּחֲלִיאֵ֖ל בָּמֽוֹת׃');
INSERT INTO verses VALUES (4361, 4, 21, 20, '[וּמִבָּמ֗וֹת] [הַגַּיְא֙] que [בִּשְׂדֵ֣ה] Moabe cabeça [הַפִּסְגָּ֑ה] [וְנִשְׁקָ֖פָה] sobre face-de');
INSERT INTO verses VALUES (4362, 4, 21, 21, 'e-estendeu Israel mensageiros a סִיחֹ֥ן dizendo o-amorreu para-dizer');
INSERT INTO verses VALUES (4363, 4, 21, 22, 'passarei בְאַרְצֶ֗ךָ não נִטֶּה֙ em-campo וּבְכֶ֔רֶם não נִשְׁתֶּ֖ה águas-de בְאֵ֑ר בְּדֶ֤רֶךְ o-rei iremos até que נַעֲבֹ֖ר גְּבֻלֶֽךָ׃');
INSERT INTO verses VALUES (4364, 4, 21, 23, 'e-não deu סִיחֹ֣ן a Israel עֲבֹ֣ר בִּגְבֻלוֹ֒ וַיֶּאֱסֹ֨ף סיחון a todo povo-dele e-saiu para Israel הַמִדְבָּרָה E-veio יָהְצָה וַיִּלָּחֶם em-Israel');
INSERT INTO verses VALUES (4365, 4, 21, 24, 'e-ferrou-o Israel à-boca-de espada וַיִּירַשׁ a sua-terra מֵאַרְנֹן até que até filhos-de Amom porque עַז guvul filhos-de Amon');
INSERT INTO verses VALUES (4366, 4, 21, 25, 'E-tomou Israel a todo as-cidades estes e-habitou Israel em-todo cidades-de o amorreu בְּחֶשְׁבּוֹן e-em-todo בְּנֹתֶיהָ׃');
INSERT INTO verses VALUES (4367, 4, 21, 26, 'que Hesbom cidade סיחון rei o-amorreu ela e-ele נִלְחַ֗ם בְּמֶ֤לֶךְ Moabe הָֽרִאשׁ֔וֹן E-tomou a todo אַרְצ֛וֹ מִיָּד֖וֹ até אַרְנֹֽן׃');
INSERT INTO verses VALUES (4368, 4, 21, 27, 'sobre assim dirao הַמֹּשְׁלִ֖ים בֹּ֣אוּ Hesbom תִּבָּנֶ֥ה וְתִכּוֹנֵ֖ן cidade סיחון׃');
INSERT INTO verses VALUES (4369, 4, 21, 28, 'porque fogo יָצְאָה מֵחֶשְׁבּוֹן לֶהָבָה de-Quiriate סִיחֹן אָכְלָה֙ עָר Moabe בעלים בּamoֹת אַרְנֹן׃');
INSERT INTO verses VALUES (4370, 4, 21, 29, 'אוֹי־ a-ti Moabe אבדת dar como-mosh deu seus-filhos פליטים ובנותיו בשbit para-rei-de אמורי סיחון׃');
INSERT INTO verses VALUES (4371, 4, 21, 30, 'ונيراָם אביד חֶשְׁבּוֹן até דיבון e-nashim até no-pach até me-idba:');
INSERT INTO verses VALUES (4372, 4, 21, 31, 'e-habitou Israel em-terra-de o-amorreu');
INSERT INTO verses VALUES (4373, 4, 21, 32, 'e-estendeu Moisés leraggel a yaazer e-eles-conquistaram benotayha a ha-amori que nome');
INSERT INTO verses VALUES (4374, 4, 21, 33, 'e-voltaram-se va-yala''u o-caminho-de Basã e-saiu Ogue rei-de Basã ele ele e-todo povo-dele que Edrei');
INSERT INTO verses VALUES (4375, 4, 21, 34, 'E-disse yhwh a Moisés ele que a-ele dei ele נָתַ֧תִּי ele e-a para-ele amav e-a terra-dele e-farás a-ele como fizeste a-Siom rei o amorreu que habitante em-Hesbom');
INSERT INTO verses VALUES (4376, 4, 21, 35, 'e-eles-feriram ele e-a filhos-dele e-a todo seu-povo até para-não deixar-restar para-ele sarayid e-possuíram a terra-dele');
INSERT INTO chapters VALUES (139, 4, 22, 41);
INSERT INTO verses VALUES (4377, 4, 22, 1, 'e-partiram filhos-de Israel e-acamparam בְּעַֽרְב֣וֹת Moabe מעבר לְיַרְדֵּ֥ן יְרֵחֽוֹ׃');
INSERT INTO verses VALUES (4378, 4, 22, 2, 'E-viu [בָּלָ֖ק] filho-de [OBJ] a todo que fez Israel');
INSERT INTO verses VALUES (4379, 4, 22, 3, 'וַיָּ֨גָר Moabe de-diante-de o-povo muito que chefe-de ele וַיָּ֣קָץ de-diante-de de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (4380, 4, 22, 4, 'E-disse Moabe a anciaos-de Midiã עַתָּ֞ה יְלַחֲךֵ֤י o convocados a todo nos arredores verde השור a verdejo o-campo e Balac filho-de aquela rei le-moav em-o tempo aquela');
INSERT INTO verses VALUES (4381, 4, 22, 5, 'e-enviou anjos a Balaão filho-de em Avo Potora terra sobre o rio dizendo eis seu povo sair a-ele eis eis que povo a-terra de-Egito eis כיסאה a olho a-terra e-ele habitou [sem-traducao]');
INSERT INTO verses VALUES (4382, 4, 22, 6, 'e-agora [לְכָה־נָּ֨א] [אָֽרָה־לִּ֜י] [אֶת־הָעָ֣ם] [הַזֶּ֗ה] a ele este porque [אוּכַל֙] [נַכֶּה־בּ֔וֹ] [וַאֲגָרְשֶׁ֖נּוּ] [מִן־הָאָ֑רֶץ] que [יָדַ֗עְתִּי] nele [אֲשֶׁר־תְּבָרֵךְ֙] de a-terra porque [יוּאָֽר] [OBJ] que');
INSERT INTO verses VALUES (4383, 4, 22, 7, 'e-foram זִקְנֵ֤י Moabe e-os-idosos Midian וּקְסָמִ֖ים em-mão-deles e-vieram a בִּלְעָ֔ם a-ele a-ele palavras-de בָלָֽק׃');
INSERT INTO verses VALUES (4384, 4, 22, 8, 'E-disse a-eles לִ֤ינוּ aqui a-noite וַהֲשִׁבֹתִ֤י vos palavra como יְדַבֵּר yhwh a-mim e-habitaram senhores-de- Moabe com בִּלְעָם׃');
INSERT INTO verses VALUES (4385, 4, 22, 9, 'E-veio Elohim a E-disse quem מִ֛י os homens contigo');
INSERT INTO verses VALUES (4386, 4, 22, 10, 'E-disse [בִּלְעָ֖ם] a o-Elohim [בֶּן־צִפֹּ֛ר] filho-de [מוֹאָ֖ב] rei Moabe enviou');
INSERT INTO verses VALUES (4387, 4, 22, 11, 'eis o-povo הַיֹּצֵ֣א do-Egito וַיְכַ֖ס a a-terra a-terra agora לְכָ֤ה ele para-mim a-ele talvez אוּכַ֛ל para-lutar nele e-o-gerar-s-tei:');
INSERT INTO verses VALUES (4388, 4, 22, 12, 'E-disse Elohim a não andarás תלך não não ta-or que o-povo ele -bar-kh ela');
INSERT INTO verses VALUES (4389, 4, 22, 13, 'E-levantou -bil-ay-am de-manhã E-disse a príncipes-de -bal-ak ide que -ar-tse-khem yhwh -me-ay-en yhwh -le-ti-ti -la-ha-lo-kh com-vos');
INSERT INTO verses VALUES (4390, 4, 22, 14, 'va-y-qa-ru-mu príncipes-de Moabe e-vieram a בלָק e-disseram מֵאֵ֥ן בִּלְעָ֖ם andou com-nosso:');
INSERT INTO verses VALUES (4391, 4, 22, 15, 'e-continuou ainda בלָק enviou sārim muitos וְנִכְבָּדִ֖ים destas');
INSERT INTO verses VALUES (4392, 4, 22, 16, '[וַיָּבֹ֖אוּ] a [וַיֹּ֣אמְרוּ] a-ele [כֹּ֤ה] disse disse [בֶּן־צִפּ֔וֹר] filho-de [תִמָּנַ֖ע] a por-favor');
INSERT INTO verses VALUES (4393, 4, 22, 17, 'porque כABBד muito e-tudo e-todo que dizerás a-mim אֶעֱשֶׂה וּלְכָה- agora קָבָה- para-mim a o-povo a-esta');
INSERT INTO verses VALUES (4394, 4, 22, 18, 'e-respondeu balac E-disse a servos-de -bal-ak se dê para-mim בָּלָק enchei não prata וְזָהָב não yhwh לַעֲבֹר֙ a boca-minha yhwh meu-Elohim para-fazer קְטַנָה ou גְדוֹלָה׃');
INSERT INTO verses VALUES (4395, 4, 22, 19, 'e-agora שָׁבוּ por-favor בָּזֶה também a-noite a-noite וְאֵ֣דְעָה yhwh יָסַף yhwh palavra comigo');
INSERT INTO verses VALUES (4396, 4, 22, 20, 'E-veio Elohim a בִּלְעָם֮ noite E-disse a-ele se a-ti a-ti vieram os-homens levantou vai com-eles וְאַ֗ךְ a a-palavra ele falarei a-ti ele תַעֲשֶׂה׃');
INSERT INTO verses VALUES (4397, 4, 22, 21, 'E-levantou [בִּלְעָם֙] de-manhã [וַֽיַּחֲבֹ֖שׁ] a [וַיֵּ֖לֶךְ] E-andou com');
INSERT INTO verses VALUES (4398, 4, 22, 22, 'e-acendeu-se- certamente Elohim ele andando E yhwh anjo yhwh a-ele adversário a-ele e-ele monta sobre seu-ásvo e-dois-de seus-jovens com-ele');
INSERT INTO verses VALUES (4399, 4, 22, 23, 'E-viu o-ásvo a yhwh yhwh estava-parado no-caminho e sua espada cortou em-mão-de-ele inclinou-se o-ásvo de ela foi no-campo e-ele-feriu Balaão a a avestruz para atirá-la הַדָּֽרֶךְ׃');
INSERT INTO verses VALUES (4400, 4, 22, 24, 'e-yaa-amod anjo yhwh no abismo dos vinhedos o muro de-este e o muro deste-lado');
INSERT INTO verses VALUES (4401, 4, 22, 25, 'E-viu a avestruz a yhwh yhwh ela foi pressionada a הַקִּ֔יר ela foi pressionada a perna Balaão a haqir e-foz para matá-la:');
INSERT INTO verses VALUES (4402, 4, 22, 26, 'e-foz anjo-de yhwh passar e-yaa-amod em-o-loco estreito que não-há caminho para se inclinar direita e-esquerda');
INSERT INTO verses VALUES (4403, 4, 22, 27, 'E-viu a-avã a yhwh yhwh debaixo debaixo-de bilã-am e-acendeu-se- tambem bilã-am e-feriu a a-avã no-palmo:');
INSERT INTO verses VALUES (4404, 4, 22, 28, 'e-abri yhwh a boca-de E-disse e ela disse para-Balaão a-ti que a-ti porque bateu-me este três pés:');
INSERT INTO verses VALUES (4405, 4, 22, 29, 'E-disse Balaão para-o-avestruz que exaltou-se em-mim se há espada que porque agora mataste-te:');
INSERT INTO verses VALUES (4406, 4, 22, 30, 'E-disse a egípcia a balac eu eu a tua egípcia que cavalguei עָלַ֗י desde o teu até o-dia este a-ti acampei E-disse não כֹּ֑ה E-disse não');
INSERT INTO verses VALUES (4407, 4, 22, 31, 'e revelou-se yhwh a os-olhos-de E-viu E-viu yhwh mensageiro-de yhwh estava de pé em-a-caminho e-sua-espada sela na-sua-mão e ardeu e-prostrou-se para o seu fogo:');
INSERT INTO verses VALUES (4408, 4, 22, 32, 'E-disse a-ele anjo yhwh sobre o-que bateste a em teu jumento este eis eu eis eu eu-saí para o diabo porque e arrastou o-caminho לְנֶגְדִּי׃');
INSERT INTO verses VALUES (4409, 4, 22, 33, 'e vi eu a-jumenta e estendeu diante-de-mim este três as pernas talvez e estendi [מִפָּנַ֔י] que עַתָּ֛ה também [הָרַ֖גְתִּי] [וְאוֹתָ֥הּ] e aquela [sem-traducao]');
INSERT INTO verses VALUES (4410, 4, 22, 34, 'E-disse bil''ám a yhwh yhwh que não não que tu tu stood [בַּדָּ֑רֶךְ] e-agora e-agora se mau a-mim [sem-traducao] a-mim');
INSERT INTO verses VALUES (4411, 4, 22, 35, 'E-disse anjo-de yhwh a balac vai com os-homens [אֲשֶׁר־אֲדַבֵּ֥ר] a ele que falarei a-ti a-ele דַבֵּר E-andou בִּלְעָם com príncipes-de בָלָק׃');
INSERT INTO verses VALUES (4412, 4, 22, 36, 'E-ouviu בָלָק׃ que veio בִּלְעָם e-saiu לִקְרָאתֹ a cidade Moabe que sobre fronteira Arnon que בִּקְצֵה a-fronteira');
INSERT INTO verses VALUES (4413, 4, 22, 37, 'E-disse בָלָק׃ a בִּלְעָם הֲלֹא֩ enviou shalachti a-ti para-chamar- para-ti por-que não não a-mim o-aumenta-se-realmente- não posso como-sua-glória:');
INSERT INTO verses VALUES (4414, 4, 22, 38, 'E-disse bil''ám a balak eis-que- eu-vim- a-ti agora poderia posso palavra coisa-alguma a-palavra que ser-feitos- ele por-me ele אֲדַבֵּֽר׃');
INSERT INTO verses VALUES (4415, 4, 22, 39, 'E-andou בִּלְעָ֖ם com בָּלָ֑ק e-vieram Quiriate חֻצֽוֹת׃');
INSERT INTO verses VALUES (4416, 4, 22, 40, 'e-ele-imolou בָּלָ֖ק manhã וָצֹ֑אן וַיְשַׁלַּ֣ח לְבִלְעָ֔ם וְלַשָּׂרִ֖ים que com-ele');
INSERT INTO verses VALUES (4417, 4, 22, 41, 'e-houve em-a-manhã E-tomou בָּלָק֙ a בלעם ויהלוּ nas cavernas E-viu E-viu de-lá extremidade o-povo');
INSERT INTO chapters VALUES (140, 4, 23, 30);
INSERT INTO verses VALUES (4418, 4, 23, 1, 'E-disse בלעם a בלק בנה- para-mim בוזה sete Mizbóqot והכן para-mim neste sete פָרִ֖ים e-sete איילים׃');
INSERT INTO verses VALUES (4419, 4, 23, 2, 'E-fez בלק como palavra בלעם e-subiu בלק וּבִלְעָם פר ואיל em-o-altar');
INSERT INTO verses VALUES (4420, 4, 23, 3, 'E-disse [בִּלְעָ֜ם] [לְבָלָ֗ק] [הִתְיַצֵּב֮] sobre [וְאֵֽלְכָ֗ה] [אוּלַ֞י] [יִקָּרֵ֤ה] yhwh yhwh [וּדְבַ֥ר] [מַה־יַּרְאֵ֖נִי] que para-ti [וַיֵּ֖לֶךְ] a-ti E-andou');
INSERT INTO verses VALUES (4421, 4, 23, 4, 'וַיִּקָּ֥ר Elohim a E-disse a-ele a-ele a shib-aat הַֽמִּזְבְּחֹת֙ עָרַ֔כְתִּי וָאַ֛עַל פָּ֥ר וָאַ֖יִל em-o-altar');
INSERT INTO verses VALUES (4422, 4, 23, 5, 'e-ele-posto yhwh palavra בְּפִ֣י בִלְעָ֑ם E-disse volta a בָּלָ֖ק e-assim תְדַבֵּֽר׃');
INSERT INTO verses VALUES (4423, 4, 23, 6, 'e-estabeleceu-se a-ele e-eis está-postado sobre ele ele e-todo príncipes-de Moabe');
INSERT INTO verses VALUES (4424, 4, 23, 7, 'e-levantou [מְשָׁל֖וֹ] E-disse de [יַנְחֵ֨נִי] [בָלָ֤ק] [מֶֽלֶךְ־מוֹאָב֙] rei-de [לְכָה֙] [אָֽרָה־לִּ֣י] [יַעֲקֹ֔ב] [וּלְכָ֖ה] [זֹעֲמָ֥ה] [יִשְׂרָאֵֽל] Jacó Israel');
INSERT INTO verses VALUES (4425, 4, 23, 8, 'que אֵקֹב não קְבֹה El וּמָה אֵזֹם não זָעַם yhwh');
INSERT INTO verses VALUES (4426, 4, 23, 9, 'porque [צֻרִים֙] [אֶרְאֶ֔נּוּ] [וּמִגְּבָע֖וֹת] [אֲשׁוּרֶ֑נּוּ] [הֶן־עָם֙] [לְבָדָ֣ד] povo [וּבַגּוֹיִ֖ם] não [יִתְחַשָּֽׁב] não');
INSERT INTO verses VALUES (4427, 4, 23, 10, 'quem מָנָה֙ o-pó Jacó וּמִסְפָּ֖ר a רֹ֣בַע Israel תּוֹמֹ֤ת morrendo morte-de יְשָׁרִ֔ים וְתֵהַ֥י אַחֲרִיתִ֖י como-ele-verso-final');
INSERT INTO verses VALUES (4428, 4, 23, 11, 'E-disse בְּלָק֙ a בִּלְעָ֔ם מֶה fiz-te- a-mim לָקֹ֤ב אֹיְבַ֙י֙ לְקַחְתִּ֔יךָ e-eis ברכת abençoou');
INSERT INTO verses VALUES (4429, 4, 23, 12, '[וַיַּ֖עַן] E-disse [הֲלֹ֗א] a que [יָשִׂ֤ים] yhwh [בְּפִ֔י] ele [אֶשְׁמֹ֖ר] [לְדַבֵּֽר]');
INSERT INTO verses VALUES (4430, 4, 23, 13, 'E-disse a-ele בלק נא ITHI a lugar-de outro que [מִשָּׁ֔ם] de-lá no-entanto [תִרְאֶ֔ה] verás não não תִרְאֶ֑ה e o quebamos- yhwh de-lá');
INSERT INTO verses VALUES (4431, 4, 23, 14, 'e tomou-o- campo- observando a cabeça E-edificou e-construiu sete [וַיַּ֛עַל] e-subiu פר ואיל em-o-altar');
INSERT INTO verses VALUES (4432, 4, 23, 15, 'E-disse a בלק estabeleceu-se assim sobre seu holocausto e-eu eu queirei assim-:');
INSERT INTO verses VALUES (4433, 4, 23, 16, 'e chamou-se yhwh a בִּלְעָ֔ם e-colocou palavra E-disse E-disse volta a בָּלָ֖ק e-assim תְדַבֵּֽר׃');
INSERT INTO verses VALUES (4434, 4, 23, 17, 'E-veio a-ele e eis estava de pé sobre oferta dele e-príncipes-de Moabe E-disse a-ele a-ele בלק yhwh palavra yhwh');
INSERT INTO verses VALUES (4435, 4, 23, 18, 'e-levantou מְשָׁל֖וֹ E-disse levantou בָּלָק֙ e-ouviu ouvireis até eu filho-de-ele Cipora:');
INSERT INTO verses VALUES (4436, 4, 23, 19, 'não homem El e enganará e-filho-de homem e se arrependerá disse disse e-não fazê-lo-á e falará e-não e levantará-se');
INSERT INTO verses VALUES (4437, 4, 23, 20, 'eis abençoou tomarei e abençoe e-não eu trarei');
INSERT INTO verses VALUES (4438, 4, 23, 21, 'não ele olhou אָוֶן em Jacó e-não viu yhwh em-Israel yhwh Elohim-dele com-ele e a trombeta rei em-ele');
INSERT INTO verses VALUES (4439, 4, 23, 22, 'El que me trazem de-Egito como asas רְאֵ֖ם a-ele');
INSERT INTO verses VALUES (4440, 4, 23, 23, 'que não de serpentes em Jacó e-não kesem em-Israel ka''et ye''amor le-ya''akov u-le-yishra''el que- pa''al El');
INSERT INTO verses VALUES (4441, 4, 23, 24, 'eis povo kalabiya'' ya''qum ve-ka''ari não não יִשְׁכַּב֙ até yo''chal te''ref e-sangue- traspassados יִשְׁתֶּֽה׃');
INSERT INTO verses VALUES (4442, 4, 23, 25, 'E-disse בָּלָק֙ a בִּלְעָ֔ם não cabo- não não também abençoou não -eu-bendirei;');
INSERT INTO verses VALUES (4443, 4, 23, 26, 'e-respondeu בִּלְעָ֔ם E-disse a בלָק הלוא eu-falei dizendo dizendo todo yhwh ele yhwh ele -farei;');
INSERT INTO verses VALUES (4444, 4, 23, 27, 'E-disse בָּלָק֙ a בִּלְעָ֔ם venha- agora eu-pegarei-te- a lugar outro אוּלַ֤י -irá- aos-olhos-de o-Elohim -e-receberá-o- yhwh de-lá');
INSERT INTO verses VALUES (4445, 4, 23, 28, 'E-tomou בָּלָ֖ק a בִּלְעָ֑ם cabeça -o-fulgor- -o-reflexo- sobre face-de הַיְשִׁימֹֽן׃');
INSERT INTO verses VALUES (4446, 4, 23, 29, 'E-disse -bil-ay-am a בלק בנה- para-mim בוזה sete Mizbóqot והכן para-mim neste sete פָרִ֖ים e-sete איילים׃');
INSERT INTO verses VALUES (4447, 4, 23, 30, 'E-fez בלק como disse בִּלְעָ֑ם e-subiu פר ואיל em-o-altar');
INSERT INTO chapters VALUES (141, 4, 24, 25);
INSERT INTO verses VALUES (4448, 4, 24, 1, 'E-viu balac que bom be-einei yhwh para-abençoar a Israel e-não andou Kéfa''im- em-vez ao-encontro-de Néchasim herdar-os a הַמִּדְבָּ֖ר faces-suas');
INSERT INTO verses VALUES (4449, 4, 24, 2, 'e-ele-leva Bil''á''am a E-viu E-viu a Israel שֹׁכֵ֖ן para-os-de-sua-fração espírito sobre-ele espírito Elohim');
INSERT INTO verses VALUES (4450, 4, 24, 3, 'e-levantou מְשָׁל֖וֹ E-disse oráculo-de -bil-ay-am -seu-filho Bé''ór Úne''óm Ha''geber שְׁתֻ֥ם a-fonte');
INSERT INTO verses VALUES (4451, 4, 24, 4, 'oráculo-de ouviu palavras-de El que Macháze'' Shaddai Yecháze'' caído וּגְל֥וּי Olhos:');
INSERT INTO verses VALUES (4452, 4, 24, 5, 'que [אֹהָלֶ֖יךָ] [יַעֲקֹ֑ב] Jacó [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (4453, 4, 24, 6, '[כִּנְחָלִ֣ים] [נִטָּ֔יוּ] [כְּגַנֹּ֖ת] sobre rio [כַּאֲהָלִים֙] plantar yhwh [כַּאֲרָזִ֖ים] sobre águas');
INSERT INTO verses VALUES (4454, 4, 24, 7, 'יִֽזַּל־ águas de-sua-moistura e-seu-herdeiro em-aquas muitos e-eleva-lo de-Agag seu-rei e-eleve-se sua-majestade');
INSERT INTO verses VALUES (4455, 4, 24, 8, 'El que-o-saia do-Egito como-um-penacho רְאֵ֖ם a-ele יֹאכַ֞ל nações צָרָ֗יו וְעַצְמֹתֵיהֶ֛ם יְגָרֵ֖ם וְחִצָּ֥יו יִמְחָֽץ׃');
INSERT INTO verses VALUES (4456, 4, 24, 9, '[כָּרַ֨ע] [שָׁכַ֧ב] [כַּאֲרִ֛י] [וּכְלָבִ֖יא] quem [יְקִימֶ֑נּוּ] [מְבָרֲכֶ֣יךָ] [בָר֔וּךְ] [וְאֹרְרֶ֖יךָ] maldito');
INSERT INTO verses VALUES (4457, 4, 24, 10, 'e-acendeu-se- אַ֤ף בָּלָק֙ a בִּלְעָ֔ם E-disse a כַּפָּ֑יו E-disse בָלָק׃ a balac לָקֹ֤ב אֹֽיְבַי֙ קְרָאתִ֔יךָ e-eis בֵּרַ֣ךְ abençoou este três vezes');
INSERT INTO verses VALUES (4458, 4, 24, 11, 'e-agora ברח- a-ti a מקומך- dissesse כב- אכ kabbedkha- yhwh מנעה- yhwh מקבוד-׃');
INSERT INTO verses VALUES (4459, 4, 24, 12, 'E-disse [בִּלְעָ֖ם] a [הֲלֹ֗א] também também a [אֵלַ֖י] que dizendo');
INSERT INTO verses VALUES (4460, 4, 24, 13, 'se dê para-mim בלק enchei ביתו- não וזהב- não אכלנו yhwh a boca-de yhwh para-fazer tobah ou yhwh ele que que yhwh ele אֲדַבֵּֽר׃');
INSERT INTO verses VALUES (4461, 4, 24, 14, 'e-agora eis-me הולך לעמי לְכוּ איעצך que ele-fará o-povo este לעמך באחרית os dias');
INSERT INTO verses VALUES (4462, 4, 24, 15, 'e-levantou מְשָׁל֖וֹ E-disse oráculo-de -bil-ay-am -seu-filho בעור וneaum הגבר שְׁתֻ֥ם a-fonte');
INSERT INTO verses VALUES (4463, 4, 24, 16, 'oráculo-de ouviu palavras-de El conhecimento דַּעַת עֶלְי֑וֹן מַחֲזֵ֤ה Shaddai יָחֱזֶ֔ה caído וּגְל֥וּי Olhos:');
INSERT INTO verses VALUES (4464, 4, 24, 17, 'אֶרְאֶ֙נּוּ֙ e-não עַתָּ֔ה אֲשׁוּרֶ֖נּוּ e-não קָר֑וֹב caminho estrela מִיַּעֲקֹ֗ב וְקָ֥ם שֵׁ֙בֶט֙ de-Israel וּמָחַץ֙ פַּאֲתֵ֣י Moabe וְקַרְקַ֖ר todo filhos-de Sete');
INSERT INTO verses VALUES (4465, 4, 24, 18, 'e-será Edom יְרֵשָׁ֗ה ve-hâyâ: יְרֵשָׁ֛ה Seir אֹיְבָ֑יו וְיִשְׂרָאֵ֖ל fez força');
INSERT INTO verses VALUES (4466, 4, 24, 19, '[וְיֵ֖רְדְּ] [מִֽיַּעֲקֹ֑ב] [וְהֽ͏ֶאֱבִ֥יד] [שָׂרִ֖יד] [מֵעִֽיר]');
INSERT INTO verses VALUES (4467, 4, 24, 20, 'E-viu a Amaleque e-levantou מְשָׁל֖וֹ E-disse primeira nações Amaleque וְאַחֲרִית֖וֹ עֲדֵ֥י perdi-se');
INSERT INTO verses VALUES (4468, 4, 24, 21, 'E-viu a [וַיִּשָּׂ֥א] e-levantou [וַיֹּאמַ֑ר] E-disse [מֽוֹשָׁבֶ֔ךָ] [וְשִׂ֥ים] [בַּסֶּ֖לַע] [קִנֶּֽךָ]');
INSERT INTO verses VALUES (4469, 4, 24, 22, 'que se será para queimar קָ֑יִן até que Aššúrā serás queimado');
INSERT INTO verses VALUES (4470, 4, 24, 23, 'e-levantou מְשָׁל֖וֹ E-disse Ah! quem יִחְיֶה por causa dele El');
INSERT INTO verses VALUES (4471, 4, 24, 24, 'e carneiros da-mão-de cabras e se humilhem Assíria e se humilhem do outro lado do rio e-também ele עַד־ perdi-se');
INSERT INTO verses VALUES (4472, 4, 24, 25, 'E-levantou בִּלְעָ֔ם E-andou e-estabeleceu-se לִמְקוֹם־ e-também andar andou para-caminho-dele');
INSERT INTO chapters VALUES (142, 4, 25, 19);
INSERT INTO verses VALUES (4473, 4, 25, 1, 'e-habitou Israel בָּשָׂטִים e-esperou o-povo para zinar a filhas-de Moabe');
INSERT INTO verses VALUES (4474, 4, 25, 2, 'וַתִּקְרֶאנָ para-o-povo לְזִבְחֵי אֱלֹהֵיהֶן e-comeu o-povo וַיִּשְׁתַּחֲווּ לֵאֱלֹהֵיהֶן׃');
INSERT INTO verses VALUES (4475, 4, 25, 3, 'וַיִּצְמָד Israel לְבַ֣עַל פּוּאֹר e-acendeu-se- yhwh yhwh em-Israel');
INSERT INTO verses VALUES (4476, 4, 25, 4, 'E-disse yhwh a Moisés qach a todo cabeças-de o-povo diante eles a-yhwh em-frente-de o-sol e voltando-se nós também yhwh מִיִּשְׂרָאֵֽל׃');
INSERT INTO verses VALUES (4477, 4, 25, 5, 'E-disse Moisés a os juízes Israel mataram homem seus-homens os que estavam presos a Baal P''or');
INSERT INTO verses VALUES (4478, 4, 25, 6, 'e-eis homem dos filhos de Israel veio e aproximou-se a irmãos-de-ele a a midianita aos-olhos-de Moisés e-perante-os-olhos-de todo congregação-de filhos-de Israel e-eles chorando entrada-de tenda encontro');
INSERT INTO verses VALUES (4479, 4, 25, 7, 'E-viu Pinhas filho-de Eleazar filho-de Aarao o-sacerdote E-levantou E-tomou a-congregação E-tomou romach em-mão-sua');
INSERT INTO verses VALUES (4480, 4, 25, 8, 'E-veio aḥar homem-de Israel a [אֶת־שְׁנֵיהֶ֔ם] vayidkor a dois-deles a homem Israel e-a de-cima-de a qovatāh vatʿazar hammegfā de-sobre filhos-de Israel');
INSERT INTO verses VALUES (4481, 4, 25, 9, 'וַיִּהְיוּ os-mortos bammegfā quatro e-vinte mil');
INSERT INTO verses VALUES (4482, 4, 25, 10, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4483, 4, 25, 11, 'pinḥas filho-de El''azar filho-de Aarão o-sacerdote de-cima-de a minha-furia de-sobre filhos-de Israel bqenaʾo a minha-quina que e-não כִלִּ֥יתִי a filhos-de Israel בְּקִנְאָתִֽי׃');
INSERT INTO verses VALUES (4484, 4, 25, 12, 'portanto disse eis-me deu a-ele a aliança-minha');
INSERT INTO verses VALUES (4485, 4, 25, 13, 'וְהָ֤יְתָה para-ele וּלְזַרְע֣וֹ apos-ele berith כְּהֻנַּ֣ת eternidade debaixo que קִנֵּא֙ לֵֽאלֹהָ֔יו e-o expiou sobre filhos-de Israel');
INSERT INTO verses VALUES (4486, 4, 25, 14, '[וְשֵׁם֩] homem Israel [הַמֻּכֶּ֗ה] que [הֻכָּה֙] a [זִמְרִ֖י] [בֶּן־סָל֑וּא] filho-de [בֵֽית־אָ֖ב] [לַשִּׁמְעֹנִֽי] casa-de pai');
INSERT INTO verses VALUES (4487, 4, 25, 15, 'e-nome-de הָֽאִשָּׁ֧ה הַמֻּכָּ֛ה הַמִּדְיָנִ֖ית כָּזְבִּ֣י filha-de Zur cabeça אֻמּ֥וֹת casa-de ele בְּמִדְיָ֖ן ela');
INSERT INTO verses VALUES (4488, 4, 25, 16, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4489, 4, 25, 17, '[צָר֖וֹר] a [וְהִכִּיתֶ֖ם] [אוֹתָֽם]');
INSERT INTO verses VALUES (4490, 4, 25, 18, 'que [צֹרְרִ֥ים] eles a-vós [בְּנִכְלֵיהֶ֛ם] que a-vós a-vós sobre palavra-de [בַת־נְשִׂ֤יא] e-sobre palavra [הַמֻּכָּ֥ה] [בְיוֹם־הַמַּגֵּפָ֖ה] [עַל־דְּבַר־פְּעֽוֹר] sobre');
INSERT INTO verses VALUES (4491, 4, 25, 19, 'e-houve depois-de a-magga');
INSERT INTO chapters VALUES (143, 4, 26, 65);
INSERT INTO verses VALUES (4492, 4, 26, 1, 'E-disse yhwh a e-para e-a el-azar filho-de dizendo o-sacerdote para-dizer');
INSERT INTO verses VALUES (4493, 4, 26, 2, 'sa-u a rosh todo congregação-de filhos-de Israel de-filho-de vinte ano e-para-cima para-casa-de exército todo exército exército em-Israel');
INSERT INTO verses VALUES (4494, 4, 26, 3, 'e-falou Moisés ve-el-azar o-sacerdote eles be-arbat Moabe sobre yar-den dizendo para-dizer');
INSERT INTO verses VALUES (4495, 4, 26, 4, 'מִבֶּ֛ן vinte ano e-para-cima como-que ordenou yhwh a Moisés e-filhos-de Israel que saem da-terra-de Egito');
INSERT INTO verses VALUES (4496, 4, 26, 5, 'reuven primogênito-de Israel filhos-de Rúben cha-noch de-família ha-chanoki le-palua família-de hap-pallu''i:');
INSERT INTO verses VALUES (4497, 4, 26, 6, '[לְחֶצְרֹ֕ן] família-de [הַֽחֶצְרוֹנִ֑י] [לְכַרְמִ֕י] família-de [הַכַּרְמִֽי]');
INSERT INTO verses VALUES (4498, 4, 26, 7, 'Estas mishpachot הָרֻֽאוּבֵנִ֑י e-foram פְקֻדֵיהֶ֗ם שְׁלֹשָׁ֤ה e-quarenta mil e-sete centenas e-trinta');
INSERT INTO verses VALUES (4499, 4, 26, 8, 'e-filhos-de פַלּ֖וּא אֱלִיאָֽב׃');
INSERT INTO verses VALUES (4500, 4, 26, 9, 'e-filhos-de אֱלִיאָ֔ב נְמוּאֵ֖ל וְדָתָ֣ן e o Abiram ele דָתָ֨ן e Abiram a congregação que הִצּ֜וּ sobre Moisés e-sobre Arão בַּעֲדַת־ Qorach בְּהַצֹּתָ֖ם sobre yhwh');
INSERT INTO verses VALUES (4501, 4, 26, 10, 'וַתִּפְתַּ֨ח a-terra a פִּ֗יהָ eles a-eles e-a קֹ֖רַח em-morte-de a-congregação בַּאֲכֹ֣ל הָאֵ֗שׁ a cinquenta u''ma''ăṭayim homem e-foram para-nês:');
INSERT INTO verses VALUES (4502, 4, 26, 11, 'e-filhos-de קֹ֖רַח não morreram');
INSERT INTO verses VALUES (4503, 4, 26, 12, 'filhos-de Shim`on֮ לְמִשְׁפְּחֹתֵיהֶֽם Li-nemúe''al família-de Ha-nemúe''eli li-yámin família-de hayyáminí li-yákín família-de hayyákín:');
INSERT INTO verses VALUES (4504, 4, 26, 13, 'li-zéraḥ família-de o-zarqi li-shé''ul família-de הַשָּׁאוּלִֽי׃');
INSERT INTO verses VALUES (4505, 4, 26, 14, 'Estas mishpachot הַשִּׁמְעֹנִ֑י dois e-vinte mil e-duzentos');
INSERT INTO verses VALUES (4506, 4, 26, 15, 'filhos-de [גָד֮] [לְמִשְׁפְּחֹתָם֒] [לִצְפ֗וֹן] família-de [הַצְּפוֹנִ֔י] [לְחַגִּ֕י] família-de [הַֽחַגִּ֑י] [לְשׁוּנִ֕י] família-de [הַשּׁוּנִֽי]');
INSERT INTO verses VALUES (4507, 4, 26, 16, 'לְאָזְנִ֕י família-de a orelha para a orelha família-de a orelha:');
INSERT INTO verses VALUES (4508, 4, 26, 17, 'para a arada família-de a arada para Arã família-de a Arã:');
INSERT INTO verses VALUES (4509, 4, 26, 18, 'Estas famílias-de filhos-de Gad conforme-seus-registros quarenta mil e-cinco centenas');
INSERT INTO verses VALUES (4510, 4, 26, 19, 'filhos-de Judá a vergonha e Onan E-morreu a vergonha וְאוֹנָ֖ן em-terra-de כְּנָֽעַן');
INSERT INTO verses VALUES (4511, 4, 26, 20, '[וַיִּהְי֣וּ] filhos-de [לְמִשְׁפְּחֹתָם֒] [לְשֵׁלָ֗ה] [מִשְׁפַּ֙חַת֙] família-de [לְפֶ֕רֶץ] [מִשְׁפַּ֖חַת] família-de [לְזֶ֕רַח] [מִשְׁפַּ֖חַת] família-de');
INSERT INTO verses VALUES (4512, 4, 26, 21, 'e-foram filhos-de פֶ֔רֶץ לְחֶצְרֹ֕ן família-de הַֽחֶצְרֹנִ֑י para moído família-de o moído:');
INSERT INTO verses VALUES (4513, 4, 26, 22, 'Estas famílias-de Judá conforme-seus-registros seis e-setenta mil e-cinco centenas');
INSERT INTO verses VALUES (4514, 4, 26, 23, 'filhos-de Issacar לְמִשְׁפְּחֹתָ֔ם toula família-de o toula: para púah família-de púah:');
INSERT INTO verses VALUES (4515, 4, 26, 24, 'para yashob família-de o yashob: para shemerôn família-de הַשֿׁמְרֹנִֽי׃');
INSERT INTO verses VALUES (4516, 4, 26, 25, 'Estas famílias-de יִשָּׂשכָ֖ר conforme-seus-registros quatro e-sessenta mil e-três centenas');
INSERT INTO verses VALUES (4517, 4, 26, 26, 'filhos-de [זְבוּלֻן֮] [לְמִשְׁפְּחֹתָם֒] [לְסֶ֗רֶד] família-de [הַסַּרְדִּ֔י] [לְאֵל֕וֹן] família-de [הָאֵלֹנִ֑י] [לְיַ֨חְלְאֵ֔ל] família-de [הַיַּחְלְאֵלִֽי]');
INSERT INTO verses VALUES (4518, 4, 26, 27, 'Estas famílias-de הַזְּבוּלֹנִ֖י conforme-seus-registros sessenta mil e-cinco centenas');
INSERT INTO verses VALUES (4519, 4, 26, 28, 'filhos-de José segundo-famílias-deles ménashé E Efraim:');
INSERT INTO verses VALUES (4520, 4, 26, 29, 'filhos-de Menasheh para Machir\ de-família o meu Machir\ e Machir\ gerou a Galaad para Gileade\ família-de o meu Gileade:');
INSERT INTO verses VALUES (4521, 4, 26, 30, 'Estas filhos-de Gileade Iezer\ família-de o meu Iezer\ para a parte\ família-de a minha parte:');
INSERT INTO verses VALUES (4522, 4, 26, 31, '[וְאַ֨שְׂרִיאֵ֔ל] família-de [הָֽאַשְׂרִֽאֵלִ֑י] [וְשֶׁ֕כֶם] família-de [הַשִּׁכְמִֽי]');
INSERT INTO verses VALUES (4523, 4, 26, 32, '[וּשְׁמִידָ֕ע] família-de [הַשְּׁמִידָעִ֑י] [וְחֵ֕פֶר] família-de [הַֽחֶפְרִֽי]');
INSERT INTO verses VALUES (4524, 4, 26, 33, 'וּצְלָפְחָ֣ד filho-de חֵ֗פֶר a-ele havu que filhos porque se filhas ve-shem filhas-de tslafhad machla ve-noa chagla de-Malka vetirzah');
INSERT INTO verses VALUES (4525, 4, 26, 34, 'Estas mishpachot Manassés u-pikdeihem dois e-cinquenta mil e-sete centenas');
INSERT INTO verses VALUES (4526, 4, 26, 35, 'Estas filhos-de efrayim לְמִשְׁפְּחֹתֵיהֶֽם leshutelach família-de o-shotalchi le-beker família-de ha-bakri le-tachan família-de ha-tachani');
INSERT INTO verses VALUES (4527, 4, 26, 36, 'e-estes filhos-de shotalach le-eran família-de ha-erani');
INSERT INTO verses VALUES (4528, 4, 26, 37, 'Estas [מִשְׁפְּחֹ֤ת] filhos-de Efraim lipkudehem dois e-trinta mil e-cinco Estas estes filhos-de José para-famílias-deles');
INSERT INTO verses VALUES (4529, 4, 26, 38, 'filhos-de [בִנְיָמִן֮] [לְמִשְׁפְּחֹתָם֒] [לְבֶ֗לַע] família-de [הַבַּלְעִ֔י] [לְאַשְׁבֵּ֕ל] família-de [הָֽאַשְׁבֵּלִ֑י] [לַאֲחִירָ֕ם] família-de [הָאֲחִירָמִֽי]');
INSERT INTO verses VALUES (4530, 4, 26, 39, 'לִשְׁפוּפָם família-de הַשּׁוּפָמִי לְחוּפָם família-de o choepamí:');
INSERT INTO verses VALUES (4531, 4, 26, 40, 'e-foram filhos-de beláu árdd vé naamán família-de há ardí lén naamán família-de hán naami:');
INSERT INTO verses VALUES (4532, 4, 26, 41, 'Estas filhos-de Benjamim segundo-famílias-deles ú pukédiehem cinco e-quarenta mil e-seis centenas');
INSERT INTO verses VALUES (4533, 4, 26, 42, 'Estas filhos-de dán לְמִשְׁפְּחֹתָ֔ם lésuacham família-de Estas estes famílias-de דָּ֖ן para-famílias-deles');
INSERT INTO verses VALUES (4534, 4, 26, 43, 'todo famílias-de הַשׁוּחָמִ֖י quatro אַרְבָּעָ֧ה e-sessenta mil e-quatro centenas');
INSERT INTO verses VALUES (4535, 4, 26, 44, 'filhos-de que [לְמִשְׁפְּחֹתָם֒] [לְיִמְנָ֗ה] família-de [הַיִּמְנָ֔ה] [לְיִשְׁוִ֕י] família-de [הַיִּשְׁוִ֑י] [לִבְרִיעָ֕ה] família-de [הַבְּרִיעִֽי]');
INSERT INTO verses VALUES (4536, 4, 26, 45, 'aos-filhos-de בְרִיעָ֔ה לְחֶ֕בֶר família-de o hebrui para malakiel família-de o malakielí:');
INSERT INTO verses VALUES (4537, 4, 26, 46, 'e-nome-de filha-de que sarach:');
INSERT INTO verses VALUES (4538, 4, 26, 47, 'Estas famílias-de filhos-de que conforme-seus-registros três e-cinquenta mil e-quatro centenas');
INSERT INTO verses VALUES (4539, 4, 26, 48, 'filhos-de Nafthali לְמִשְׁפְּחֹתָ֔ם para yachzeil família-de o yachzeili para guni família-de o guni:');
INSERT INTO verses VALUES (4540, 4, 26, 49, 'para yetzer família-de o yetziri para completar família-de o que completará:');
INSERT INTO verses VALUES (4541, 4, 26, 50, 'Estas famílias-de Naftali segundo-famílias-deles e suas contas cinco e-quarenta mil e-quatro centenas');
INSERT INTO verses VALUES (4542, 4, 26, 51, 'Estas contas de filhos-de Israel seis-de centenas mil e mil sete centenas e-trinta');
INSERT INTO verses VALUES (4543, 4, 26, 52, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4544, 4, 26, 53, 'para os elohim separte a-terra na-inheritance em-número nomes:');
INSERT INTO verses VALUES (4545, 4, 26, 54, 'para muitos תַּרְבֶּה֙ herança-sua e para poucos תַּמְעִ֖יט sua herança homem de-conformidade-com seus registros seja-dado herança-dele');
INSERT INTO verses VALUES (4546, 4, 26, 55, 'somente por sorteio será dividido a a-terra para nomes carruagens- pais-deles terão herança');
INSERT INTO verses VALUES (4547, 4, 26, 56, 'sobre boca-minha o sorteio será dividido entre entre muito em pequenas porções');
INSERT INTO verses VALUES (4548, 4, 26, 57, 've-Eleh פקודים הַלּוּיִם לְמִשְׁפְּחֹתֵיהֶֽם לְגֵרְשׁוֹן família-de הַגֵּ֣רְשֻׁנּי לִקְהַת família-de o-coatita para-Merari família-de הַמררי׃');
INSERT INTO verses VALUES (4549, 4, 26, 58, 'Estas mishpachot לוּי da família הַלִיבני família-de הַחֵברוני família-de הַמָחללי de-família הַמָUSHי família-de a febre e-Coate gerou a Amram:');
INSERT INTO verses VALUES (4550, 4, 26, 59, 'e o nome de mulher-de Amram Jochébed filha-de Levi que ela-deu-à-luz ela para Levi em-Egito e-deu-à-luz para Amram a Arão e-a Moisés e-a Miriam אֲחֹתָֽם׃');
INSERT INTO verses VALUES (4551, 4, 26, 60, 'foi gerado para Arão a Nadabe e-a אביהו a Elazar e-a aitamar:');
INSERT INTO verses VALUES (4552, 4, 26, 61, 'E-morreu Nadabe וַאֲבִיה֑וּא בהקריבוֹם fogo- זרעה yhwh yhwh');
INSERT INTO verses VALUES (4553, 4, 26, 62, 'e-foram פקודיהם שלושה e-vinte mil todo macho de-filho-de que e-para-cima não não no-meio-de בתוך filhos-de que porque a-eles deu no-meio-de נחלא em-meio-de filhos-de Israel');
INSERT INTO verses VALUES (4554, 4, 26, 63, 'Estas pikuday Moisés Elazar o-sacerdote que פקדוּ a filhos-de Israel בערות sobre sobre Jordão יְרֵחֽוֹ׃');
INSERT INTO verses VALUES (4555, 4, 26, 64, 'e Bealéh não foi homem dos Piquedei Moisés e-Aarão o-sacerdote que Piquedoo a filhos-de Israel em-deserto-de Sinai');
INSERT INTO verses VALUES (4556, 4, 26, 65, 'porque yhwh a-eles morrendo morrer yamatu no-deserto e-não Natar que homem porque se Kalev filho-de yefunneh e Josué filho-de Nun:');
INSERT INTO chapters VALUES (144, 4, 27, 23);
INSERT INTO verses VALUES (4557, 4, 27, 1, 'e Tikkabnáh filhas-de Tsélapachad filho-de Chéfer filho-de Gil''ad filho-de Machir filho-de Manassés [שְׁמ֣וֹת] מְנַשֶּׁ֣ה filho-de José e-estes nomes-de filhas-as Machlah Noah e-Chagla e-Milcah e-Tirzah:');
INSERT INTO verses VALUES (4558, 4, 27, 2, 'e-estavam-se diante-de Moisés e-diante-de Eleazar o-sacerdote e-diante-de os-negros e-todo a-congregação porta dizendo encontro para-dizer');
INSERT INTO verses VALUES (4559, 4, 27, 3, 'nosso-pai morreu no-o-deserto וְה֨וּא não no-meio-de em-meio-de a congregação הַנּוֹעָדִ֛ים sobre yhwh בַּעֲדַת־ קֹ֑רַח porque a-ele morreu e-filhos não a-ele a-ele');
INSERT INTO verses VALUES (4560, 4, 27, 4, 'por-que יִגָּרַ֤ע nome-de אָבִ֙ינוּ֙ do-meio-de que porque a-ele filho filho dá- no-meio-de אֲחֻזָּ֔ה em-meio-de irmãos-de אָבִֽינוּ׃');
INSERT INTO verses VALUES (4561, 4, 27, 5, 'e-ele-se-aproximou Moisés a diante-de yhwh');
INSERT INTO verses VALUES (4562, 4, 27, 6, 'E-disse yhwh a Moisés');
INSERT INTO verses VALUES (4563, 4, 27, 7, 'assim filhas-de צְלָפְחָד֮ דֹּבְרֹת֒ deu תִּתֵּ֤ן a-eles achuzat herança no-meio-de irmãos pai-deles e transferireis a herança o-pai-deles elas');
INSERT INTO verses VALUES (4564, 4, 27, 8, 'e-a filhos-de Israel dizendo dizendo homem porque morre a-ele não-há a-ele e transferireis a seu-pai a filha dele');
INSERT INTO verses VALUES (4565, 4, 27, 9, 'e-se a-ele a-ele filha e-dareis a seu-pai aos irmãos');
INSERT INTO verses VALUES (4566, 4, 27, 10, 'e-se a-ele a-ele [וּנְתַתֶּ֥ם] [אֶת־נַחֲלָת֖וֹ] a seu-pai');
INSERT INTO verses VALUES (4567, 4, 27, 11, 'e-se não-há אַחִים֮ לְאָבִיו֒ ונתתם a נַחֲלָת֗וֹ a-ele o-próximo a-ele מִמִּשְׁפַּחְתּ֖וֹ וְיָרַ֣שׁ a-ela e será para-filhos-de Israel para a lei מִשְׁפָּט yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (4568, 4, 27, 12, 'E-disse yhwh a folhas-de עֲלֵ֛ה a monte-de הָעֲבָרִ֖ים este וּרְאֵה֙ dei a-terra que dei para-filhos-de Israel');
INSERT INTO verses VALUES (4569, 4, 27, 13, 'וְרָאִ֣יתָה a-ela e congregareis-vos a seu povo também tu como congregareis-vos Aarão irmão-teu');
INSERT INTO verses VALUES (4570, 4, 27, 14, 'como-que querestes minha boca בְּמִדְבַּר־ cobre em disputa testemunho para santificarei-vos-me em água eles הֵ֛ם águas-de מריבה santo sobre צין');
INSERT INTO verses VALUES (4571, 4, 27, 15, 'e-falou Moisés a dizendo');
INSERT INTO verses VALUES (4572, 4, 27, 16, 'ele guardará yhwh Elohim-de הרוחות para-todo carne homem sobre הָעֵדָֽה׃');
INSERT INTO verses VALUES (4573, 4, 27, 17, 'que sairá em-frente-a-eles e-que virá em-frente-de-eles e-que יוציאים e-que יביאם e-não תהיה yhwh yhwh -o rebanho que não-há a-eles راعה');
INSERT INTO verses VALUES (4574, 4, 27, 18, 'E-disse yhwh a Moisés toma a-ti a Yehoshua filho-de Nun homem que espírito nele וסמכת a mão-tua sobre-ele');
INSERT INTO verses VALUES (4575, 4, 27, 19, 'והעמדת ele diante-de Eleazar o-sacerdote וְלִפְנֵ֖י todo a-congregação ele ele per-ey-nay-hem');
INSERT INTO verses VALUES (4576, 4, 27, 20, 'e-tu-darás mh hodcha sobre-ele para-que eles-ouvirão todo congregação-de filhos-de Israel');
INSERT INTO verses VALUES (4577, 4, 27, 21, 'e diante de Elazar o-sacerdote ele se levantará e perguntará a-ele em julgamento dos brilhantes diante-de yhwh sobre de-seu-boca saírem e-sobre ele virão ele e-todo filhos-de Israel com-ele e-todo הָעֵדָֽה׃');
INSERT INTO verses VALUES (4578, 4, 27, 22, 'E-fez Moisés como ordenou yhwh ele E-tomou a Josué e o levantou diante-de Eleazar o-sacerdote וְלִפְנֵ֖י todo הָעֵדָֽה׃');
INSERT INTO verses VALUES (4579, 4, 27, 23, 'e apoiou a suas mãos sobre-ele e ordenou-lhe como yhwh yhwh por-mão-de Moisés');
INSERT INTO chapters VALUES (145, 4, 28, 31);
INSERT INTO verses VALUES (4580, 4, 28, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4581, 4, 28, 2, 'ordene a filhos-de Israel e-dirás a-eles a oferecimento-me pão-me mulher-meu cheiro aromático-me guardem le-hakriv yhwh no-sua-celebração:');
INSERT INTO verses VALUES (4582, 4, 28, 3, 'e-dirás a-eles este a-mulher que aproximareis a-yhwh cordeiros filhos-de ano témimim dois para-o-dia holocausto תָמִֽיד׃');
INSERT INTO verses VALUES (4583, 4, 28, 4, 'a um um farás e-[OBJ] e-[OBJ] [הַשֵּׁנִ֔י] o-segundo entre entre');
INSERT INTO verses VALUES (4584, 4, 28, 5, 'vá''ăśerít hā''ăyfá farinha-fina léminnáchah bəlulá bəšémen kāṯı̂ṯ quarto deste vinho');
INSERT INTO verses VALUES (4585, 4, 28, 6, 'ōlát permanente hā''ăśāyah em-monte-de Sinai para-aroma agradavel mulher a-yhwh');
INSERT INTO verses VALUES (4586, 4, 28, 7, 'véniskó רביעית deste vinho לכּבשׂ o-primeiro no-santo ה Sark נסך bebida a-yhwh');
INSERT INTO verses VALUES (4587, 4, 28, 8, 'e-את o carneiro o-segundo vós-fará entre הערביים כמנחת הבקר וכנסכו farás mulher aroma-de agradavel a-yhwh');
INSERT INTO verses VALUES (4588, 4, 28, 9, 'וביום הַשָּׁבָת dois כבשים filhos-de ano [עֶשְׂרֹנִ֗ים] e-dois עֶשְׂרֹנִ֗ים סֹ֧לֶת oferta misturada em-o-óleo וְנִסְכּֽוֹ׃');
INSERT INTO verses VALUES (4589, 4, 28, 10, 'oferta-que-subiu שַׁבַּ֖ת בְּשַׁבַּתּ֑וֹ sobre oferta-que-subiu a-perpétua וְנִסְכָּֽהּ׃');
INSERT INTO verses VALUES (4590, 4, 28, 11, 'וּבְרָאשֵׁי֙ חָדְשֵׁיכֶ֔ם vós-oferecereis holocausto a-yhwh פָּרִ֨ים filhos-de manhã dois um um cordeiros filhos-de ano sete temimim-');
INSERT INTO verses VALUES (4591, 4, 28, 12, 'e-três עֶשְׂרֹנִ֗ים farinha-a oferta-de-cereais em-estado-de-mistura no-óleo -para-o-par o-primeiro e-dois -dez-unhas farinha-a oferta-de-cereais em-estado-de-mistura no-óleo para-o-carneiro o-primeiro');
INSERT INTO verses VALUES (4592, 4, 28, 13, '[וְעִשָּׂרֹ֣ן] [עִשָּׂר֗וֹן] farinha-a oferta-de-cereais em-estado-de-mistura no-óleo לכּבשׂ o-primeiro עֹלָה֙ aroma agradavel mulher a-yhwh');
INSERT INTO verses VALUES (4593, 4, 28, 14, '[וְנִסְכֵּיהֶ֗ם] metade [הַהִין֩] será [לַפָּ֜ר] [וּשְׁלִישִׁ֧ת] [הַהִ֣ין] [לָאַ֗יִל] [וּרְבִיעִ֥ת] [הַהִ֛ין] לכּבשׂ vinho esta oferta-que-subiu novo [בְּחָדְשׁ֔וֹ] le-chadshi ha-shana');
INSERT INTO verses VALUES (4594, 4, 28, 15, '[וּשְׂעִ֨יר] [עִזִּ֥ים] um para-pecado a-yhwh sobre [הַתָּמִ֛יד] [יֵעָשֶׂ֖ה] será-fazido וְנִסְכּֽוֹ׃');
INSERT INTO verses VALUES (4595, 4, 28, 16, '[וּבַחֹ֣דֶשׁ] o-primeiro בְּאַרְבָּעָ֥ה dez dia para-o-mês Pésach a-yhwh');
INSERT INTO verses VALUES (4596, 4, 28, 17, 'e na quinta dez dia para-o-mes este comemore- sete dias não-fermentados ser-aco-lido');
INSERT INTO verses VALUES (4597, 4, 28, 18, 'no-dia הָרִאשׁ֖וֹן מִקְרָא- santidade todo não servico não fazeis:');
INSERT INTO verses VALUES (4598, 4, 28, 19, '[וְהִקְרַבְתֶּ֨ם] mulher [עֹלָה֙] a-yhwh [פָּרִ֧ים] filhos-de manhã dois um um [כְבָשִׂים֙] [בְּנֵ֣י] filhos-de ano [יִהְי֥וּ] a-vós');
INSERT INTO verses VALUES (4599, 4, 28, 20, '[וּמִ֨נְחָתָ֔ם] farinha-fina em-estado-de-mistura com-o-açúcar שְׁלֹשָׁ֨ה עֶשְׂרֹנִ֜ים [לַפָּ֗ר] e-dois [עֶשְׂרֹנִ֛ים] para-o-carneiro façam');
INSERT INTO verses VALUES (4600, 4, 28, 21, '[עִשָּׂר֤וֹן] [עִשָּׂרוֹן֙] farás לכּבשׂ o-primeiro [לְשִׁבְעַ֖ת] [הַכְּבָשִֽׂים]');
INSERT INTO verses VALUES (4601, 4, 28, 22, '[וּשְׂעִ֥יר] pecado um para-ter-expiação sobre-vós');
INSERT INTO verses VALUES (4602, 4, 28, 23, '[מִלְּבַד֙] holocausto-de a-manhã que [לְעֹלַ֣ת] [הַתָּמִ֑יד] farão a Estas');
INSERT INTO verses VALUES (4603, 4, 28, 24, '[כָּאֵ֜לֶּה] [תַּעֲשׂ֤וּ] para o dia sete dias pão mulher aroma-de agradavel a-yhwh sobre [יֵעָשֶׂ֖ה] [וְנִסְכּֽוֹ] será-fazido וְנִסְכּֽוֹ׃');
INSERT INTO verses VALUES (4604, 4, 28, 25, 'e-no-dia o-sétimo מִקְרָא- será a-vós a-vós todo não servico não fazeis:');
INSERT INTO verses VALUES (4605, 4, 28, 26, 'e-no-dia-de [הַבִּכּוּרִ֗ים] [בְּהַקְרִ֨יבְכֶ֜ם] [מִנְחָ֤ה] nova a-yhwh [בְּשָׁבֻעֹ֖תֵיכֶ֑ם] מִֽקְרָא־ será a-vós a-vós todo não servico não fazeis:');
INSERT INTO verses VALUES (4606, 4, 28, 27, 'וְהִקְרַבְתֶּ֨ם oferta por odor agradável a-yhwh [פָּרִ֧ים] filhos-de manhã dois um um sete [בְּנֵ֥י] filhos-de anos');
INSERT INTO verses VALUES (4607, 4, 28, 28, '[וּמִנְחָתָ֔ם] farinha-fina em-estado-de-mistura com-o-açúcar שְׁלֹשָׁ֤ה [עֶשְׂרֹנִים֙] [לַפָּ֣ר] o-primeiro segundo deas onças para-o-carneiro o-primeiro');
INSERT INTO verses VALUES (4608, 4, 28, 29, '[עִשָּׂרוֹן֙] [עִשָּׂר֔וֹן] [לַכֶּ֖בֶשׂ] o-primeiro [לְשִׁבְעַ֖ת] [הַכְּבָשִֽׂים]');
INSERT INTO verses VALUES (4609, 4, 28, 30, '[שְׂעִ֥יר] cabras um para-ter-expiação sobre-vós');
INSERT INTO verses VALUES (4610, 4, 28, 31, '[מִלְּבַ֞ד] [עֹלַ֧ת] [הַתָּמִ֛יד] [וּמִנְחָת֖וֹ] fazeis-vós [תְּמִימִ֥ם] [יִהְיוּ־לָכֶ֖ם] a-vós [sem-traducao]');
INSERT INTO chapters VALUES (146, 4, 29, 39);
INSERT INTO verses VALUES (4611, 4, 29, 1, '[וּבַחֹ֨דֶשׁ] הַשְׁבִיעִ֜י no-primeiro no mês מִֽקְרָא־ será a-vós a-vós todo não servico dia fareis será a-vós será a-vós');
INSERT INTO verses VALUES (4612, 4, 29, 2, 'e-fareis [עֹלָ֜ה] por odor agradável a-yhwh [פַּ֧ר] filho-de um um um um cordeiros filhos-de ano sete temimim-');
INSERT INTO verses VALUES (4613, 4, 29, 3, '[וּמִנְחָתָ֔ם] farinha-fina em-estado-de-mistura com-o-açúcar שְׁלֹשָׁ֤ה [עֶשְׂרֹנִים֙] para-o-touro segundo [עֶשְׂרֹנִ֖ים] [לָאָֽיִל]');
INSERT INTO verses VALUES (4614, 4, 29, 4, '[וְעִשָּׂר֣וֹן] um [לַכֶּ֖בֶשׂ] o-primeiro [לְשִׁבְעַ֖ת] [הַכְּבָשִֽׂים]');
INSERT INTO verses VALUES (4615, 4, 29, 5, 'e o carneiro- um um חטא para-ter-expiação sobre-vós');
INSERT INTO verses VALUES (4616, 4, 29, 6, '[מִלְּבַד֩] [עֹלַ֨ת] [הַחֹ֜דֶשׁ] [וּמִנְחָתָ֗הּ] [וְעֹלַ֤ת] הַתָּמִיד֙ [וּמִנְחָתָ֔הּ] [וְנִסְכֵּיהֶ֖ם] [כְּמִשְׁפָּטָ֑ם] para-aroma agradavel mulher a-yhwh');
INSERT INTO verses VALUES (4617, 4, 29, 7, '[וּבֶעָשׂוֹר֩] para-o-mês הַשְׁבִיעִ֜י este מִֽקְרָא־ será a-vós a-vós וְעִנִּיתֶ֖ם a não todo não não fazeis:');
INSERT INTO verses VALUES (4618, 4, 29, 8, 'וְהִקְרַבְתֶּ֨ם holocausto a-yhwh aroma agradavel [פַּ֧ר] filho-de um um um um кָבָשִׂ֤ים filhos-de ano sete a-vós a-ti a-vós');
INSERT INTO verses VALUES (4619, 4, 29, 9, '[וּמִנְחָתָ֔ם] farinha-fina em-estado-de-mistura com-o-açúcar שְׁלֹשָׁ֤ה [עֶשְׂרֹנִים֙] para-o-touro segundo deas onças para-o-carneiro o-primeiro');
INSERT INTO verses VALUES (4620, 4, 29, 10, '[עִשָּׂרוֹן֙] [עִשָּׂר֔וֹן] [לַכֶּ֖בֶשׂ] o-primeiro [לְשִׁבְעַ֖ת] [הַכְּבָשִֽׂים]');
INSERT INTO verses VALUES (4621, 4, 29, 11, 'Seir um um חטא [חַטַּ֤את] [הַכִּפֻּרִים֙] [וְעֹלַ֣ת] [הַתָּמִ֔יד] o-contínuo e-sua-oferta-de-cereais [sem-traducao]');
INSERT INTO verses VALUES (4622, 4, 29, 12, '[וּבַחֲמִשָּׁה֩] dez dia no-mês o-sétimo מִֽקְרָא־ será a-vós a-vós todo não servico não fareis ve-chag-getem [שִׁבְעַ֥ת] a-yhwh sete dias');
INSERT INTO verses VALUES (4623, 4, 29, 13, 'וְהִקְרַבְתֶּ֨ם [עֹלָ֜ה] mulher רֵ֤יחַ agradável a-yhwh [פָּרִ֧ים] filhos-de manhã três dez carneiros dois cordeiros quatro ano quatro dez [sem-traducao] ser-ão');
INSERT INTO verses VALUES (4624, 4, 29, 14, '[וּמִנְחָתָ֔ם] farinha-fina em-estado-de-mistura com-o-açúcar שְׁלֹשָׁ֨ה עֶשְׂרֹנִ֜ים [לַפָּ֣ר] o-primeiro לשלושה dez [פָּרִ֔ים] segundo [עֶשְׂרֹנִים֙] para-a-ove o-primeiro [לִשְׁנֵ֖י] ha-eilim-');
INSERT INTO verses VALUES (4625, 4, 29, 15, '[וְעִשָּׂרוֹׄן֙[4]] [עִשָּׂר֔וֹן] [לַכֶּ֖בֶשׂ] o-primeiro dez [עָשָׂ֖ר]');
INSERT INTO verses VALUES (4626, 4, 29, 16, 'e o carneiro- um um חטא [עֹלַ֣ת] holocausto-de o-contínuo [וְנִסְכָּֽהּ׃] וְנִסְכָּֽהּ׃');
INSERT INTO verses VALUES (4627, 4, 29, 17, 'e-no-dia haseni [פָּרִ֧ים] filhos-de manhã dois dez carneiros dois cordeiros quatro ano quatro dez temimim-');
INSERT INTO verses VALUES (4628, 4, 29, 18, '[וּמִנְחָתָ֣ם] [וְנִסְכֵּיהֶ֡ם] [לַ֠פָּרִים] [לָאֵילִ֧ם] [וְלַכְּבָשִׂ֛ים] [בְּמִסְפָּרָ֖ם] como-o-julgamento');
INSERT INTO verses VALUES (4629, 4, 29, 19, 'e o carneiro- um um חטא [עֹלַ֣ת] holocausto-de o-contínuo e-sua-oferta-de-cereais [sem-traducao]');
INSERT INTO verses VALUES (4630, 4, 29, 20, '[וּבַיּ֧וֹם] o-terceiro [פָּרִ֥ים] ashtei- dez carneiros dois cordeiros quatro ano quatro dez temimim-');
INSERT INTO verses VALUES (4631, 4, 29, 21, '[וּמִנְחָתָ֣ם] [וְנִסְכֵּיהֶ֡ם] [לַ֠פָּרִים] [לָאֵילִ֧ם] [וְלַכְּבָשִׂ֛ים] [בְּמִסְפָּרָ֖ם] como-o-julgamento');
INSERT INTO verses VALUES (4632, 4, 29, 22, '[וּשְׂעִ֥יר] pecado um [מִלְּבַד֙] holocausto-de o-contínuo e-sua-oferta-de-cereais וְנִסְכָּֽהּ׃');
INSERT INTO verses VALUES (4633, 4, 29, 23, '[וּבַיּ֧וֹם] o-quarto [פָּרִ֥ים] [עֲשָׂרָ֖ה] carneiros dois cordeiros filhos-de quatro quatro dez temimim-');
INSERT INTO verses VALUES (4634, 4, 29, 24, '[מִנְחָתָ֣ם] [וְנִסְכֵּיהֶ֡ם] [לַ֠פָּרִים] [לָאֵילִ֧ם] [וְלַכְּבָשִׂ֛ים] [בְּמִסְפָּרָ֖ם] como-o-julgamento');
INSERT INTO verses VALUES (4635, 4, 29, 25, 'e o carneiro- um um חטא [עֹלַ֣ת] holocausto-de o-contínuo [וְנִסְכָּֽהּ׃] וְנִסְכָּֽהּ׃');
INSERT INTO verses VALUES (4636, 4, 29, 26, '[וּבַיּ֧וֹם] [הַחֲמִישִׁ֛י] [פָּרִ֥ים] [תִּשְׁעָ֖ה] carneiros dois cordeiros filhos-de quatro quatro dez temimim-');
INSERT INTO verses VALUES (4637, 4, 29, 27, '[וּמִנְחָתָ֣ם] [וְנִסְכֵּיהֶ֡ם] [לַ֠פָּרִים] [לָאֵילִ֧ם] [וְלַכְּבָשִׂ֛ים] [בְּמִסְפָּרָ֖ם] como-o-julgamento');
INSERT INTO verses VALUES (4638, 4, 29, 28, '[וּשְׂעִ֥יר] pecado um [מִלְּבַד֙] holocausto-de o-contínuo e-sua-oferta-de-cereais וְנִסְכָּֽהּ׃');
INSERT INTO verses VALUES (4639, 4, 29, 29, '[וּבַיּ֧וֹם] [הַשִּׁשִּׁ֛י] [פָּרִ֥ים] oito carneiros dois cordeiros filhos-de quatro quatro dez temimim-');
INSERT INTO verses VALUES (4640, 4, 29, 30, '[וּמִנְחָתָ֣ם] [וְנִסְכֵּיהֶ֡ם] [לַ֠פָּרִים] [לָאֵילִ֧ם] [וְלַכְּבָשִׂ֛ים] [בְּמִסְפָּרָ֖ם] como-o-julgamento');
INSERT INTO verses VALUES (4641, 4, 29, 31, '[וּשְׂעִ֥יר] pecado um [מִלְּבַד֙] holocausto-de o-contínuo [מִנְחָתָ֖הּ] [וּנְסָכֶֽיהָ׃]');
INSERT INTO verses VALUES (4642, 4, 29, 32, '[וּבַיּ֧וֹם] [הַשְּׁבִיעִ֛י] [פָּרִ֥ים] sete carneiros dois cordeiros filhos-de quatro quatro dez temimim-');
INSERT INTO verses VALUES (4643, 4, 29, 33, '[וּמִנְחָתָ֣ם] [וְנִסְכֵּהֶ֡ם] [לַ֠פָּרִים] [לָאֵילִ֧ם] [וְלַכְּבָשִׂ֛ים] [בְּמִסְפָּרָ֖ם] [כְּמִשְׁפָּטָֽם]');
INSERT INTO verses VALUES (4644, 4, 29, 34, '[וּשְׂעִ֥יר] pecado um [מִלְּבַד֙] holocausto-de o-contínuo [מִנְחָתָ֖הּ] וְנִסְכָּֽהּ׃');
INSERT INTO verses VALUES (4645, 4, 29, 35, 'no-dia o-oitavo עֲצֶ֖רֶת será a-vós todo obra-de não não fazeis:');
INSERT INTO verses VALUES (4646, 4, 29, 36, 'וְהִקְרַבְתֶּ֨ם [עֹלָ֜ה] mulher רֵ֤יחַ agradável a-yhwh touro-de um a-ovelha-machão um cordeiros filhos-de ano sete temimim-');
INSERT INTO verses VALUES (4647, 4, 29, 37, '[מִנְחָתָ֣ם] [וְנִסְכֵּיהֶ֗ם] [לַפָּ֨ר] [לָאַ֧יִל] [וְלַכְּבָשִׂ֛ים] [בְּמִסְפָּרָ֖ם] como-o-julgamento');
INSERT INTO verses VALUES (4648, 4, 29, 38, '[וּשְׂעִ֥יר] pecado um [מִלְּבַד֙] holocausto-de o-contínuo e-sua-oferta-de-cereais וְנִסְכָּֽהּ׃');
INSERT INTO verses VALUES (4649, 4, 29, 39, 'Estas fazei a-yhwh [בְּמוֹעֲדֵיכֶ֑ם] [לְבַ֨ד] [מִנִּדְרֵיכֶ֜ם] [וְנִדְבֹתֵיכֶ֗ם] [לְעֹלֹֽתֵיכֶם֙] [וּלְמִנְחֹ֣תֵיכֶ֔ם] [וּלְנִסְכֵּיכֶ֖ם] [וּלְשַׁלְמֵיכֶֽם]');
INSERT INTO chapters VALUES (147, 4, 30, 17);
INSERT INTO verses VALUES (4650, 4, 30, 1, 'E-disse Moisés a filhos-de Israel conforme-tudo yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (4651, 4, 30, 2, 'e-falou Moisés a cabeças-de [לִבְנֵ֥י] para-os-filhos-de dizendo dizendo este a-palavra que yhwh yhwh');
INSERT INTO verses VALUES (4652, 4, 30, 3, 'homem porque [נֶ֜דֶר] voto a-yhwh ou [לֶאְסֹ֤ר] [אִסָּר֙] [עַל־נַפְשׁ֔וֹ] não sobre naphshô não [מִפִּ֖יו] palavra-dele conforme-toda [sem-traducao] de-seu-brejo ele-fará');
INSERT INTO verses VALUES (4653, 4, 30, 4, '[וְאִשָּׁ֕ה] porque [נֶ֖דֶר] [לַיהוָ֑ה] a-yhwh [אִסָּ֛ר] [בְּבֵ֥ית] em-casa-de אָבִ֖יהָ [sem-traducao]');
INSERT INTO verses VALUES (4654, 4, 30, 5, '[וְשָׁמַ֨ע] [אָבִ֜יהָ] a [וֽ͏ֶאֱסָרָהּ֙] [אֲשֶׁ֣ר] que [עַל־נַפְשָׁ֔הּ] sobre [לָ֖הּ] [אָבִ֑יהָ] a-ela seu pai [וְכָל־אִסָּ֛ר] todo [עַל־נַפְשָׁ֖הּ] e-todo [sem-traducao] que [sem-traducao] sobre não יתקום׃');
INSERT INTO verses VALUES (4655, 4, 30, 6, 'e-se [אָבִ֣יהָ] [אֹתָהּ֮] ela-a no-dia [כָּל־נְדָרֶ֗יהָ] todo [אֲשֶׁר־אָסְרָ֥ה] [עַל־נַפְשָׁ֖הּ] não [יָק֑וּם] sobre [יִֽסְלַח־לָ֔הּ] não [אָבִ֖יהָ] e-יהוה [sem-traducao] para-ela porque [sem-traducao] אָבִ֖יהָ a-ela');
INSERT INTO verses VALUES (4656, 4, 30, 7, 'e-se [תִֽהְיֶה֙] será para-homem [עָלֶ֑יהָ] sobre-ela ou [שְׂפָתֶ֔יהָ] [אֲשֶׁ֥ר] que [עַל־נַפְשָֽׁהּ] sobre [sem-traducao]');
INSERT INTO verses VALUES (4657, 4, 30, 8, 'e-ouviu [אִישָׁ֛הּ] em-dia seu-ouvido [וְהֶחֱרִ֣ישׁ] a-ela [וְקָ֣מוּ] [נְדָרֶ֗יהָ] [וֶֽאֱסָרֶ֛הָ] que [עַל־נַפְשָׁ֖הּ] sobre não levantem-se');
INSERT INTO verses VALUES (4658, 4, 30, 9, '[וְ֠אִם] no-dia ouviu [אִישָׁהּ֮] [יָנִ֣יא] [אוֹתָהּ֒] [וְהֵפֵ֗ר] a [אֲשֶׁ֣ר] que e-[OBJ] e-[OBJ] [שְׂפָתֶ֔יהָ] [אֲשֶׁ֥ר] que [עַל־נַפְשָׁ֑הּ] sobre [יִֽסְלַֽח־לָֽהּ]');
INSERT INTO verses VALUES (4659, 4, 30, 10, '[וְנֵ֥דֶר] viúva [וּגְרוּשָׁ֑ה] todo que [עַל־נַפְשָׁ֖הּ] sobre [עָלֶֽיהָ] levantar-se sobre-ela');
INSERT INTO verses VALUES (4660, 4, 30, 11, 'e-se casa espos-a [אֽוֹ־אָסְרָ֥ה] ou [עַל־נַפְשָׁ֖הּ] [בִּשְׁבֻעָֽה] sobre não [sem-traducao]');
INSERT INTO verses VALUES (4661, 4, 30, 12, 'וְשָׁמַ֤ע [אִישָׁהּ֙] [וְהֶחֱרִ֣שׁ] para-ela não [הֵנִ֖יא] a-ela [וְקָ֙מוּ֙] todo [וְכָל־אִסָּ֛ר] e-todo [עַל־נַפְשָׁ֖הּ] que [sem-traducao] sobre não יתקום׃');
INSERT INTO verses VALUES (4662, 4, 30, 13, 'e-se [יָפֵ֨ר] eles [׀] [אִישָׁהּ֮] no-dia [שָׁמְעוֹ֒] todo [שְׂפָתֶ֧יהָ] [לִנְדָרֶ֛יהָ] [וּלְאִסַּ֥ר] [נַפְשָׁ֖הּ] não não [אִישָׁ֣הּ] [הֲפֵרָ֔ם] [וַיהוָ֖ה] [יִֽסְלַֽח־לָֽהּ]');
INSERT INTO verses VALUES (4663, 4, 30, 14, 'todo [וְכָל־שְׁבֻעַ֥ת] e-todo [לְעַנֹּ֣ת] [נָ֑פֶשׁ] [אִישָׁ֥הּ] alma [וְאִישָׁ֥הּ] [יְפֵרֶֽנּוּ]');
INSERT INTO verses VALUES (4664, 4, 30, 15, 'e-se [יַחֲרִ֨ישׁ] [לָ֥הּ] a-ela [מִיּ֣וֹם] [אֶל־יוֹם֒] a dia [א֥וֹ] a todo [עָלֶ֑יהָ] ou eles todo [לָ֖הּ] que sobre-ela levantou a-eles porque [sem-traducao] para-ela em-dia [sem-traducao]');
INSERT INTO verses VALUES (4665, 4, 30, 16, 'e-se [יָפֵ֛ר] eles eles depois-de [וְנָשָׂ֖א] e levante-se a seu-pecado');
INSERT INTO verses VALUES (4666, 4, 30, 17, 'Estas [הֽ͏ַחֻקִּ֗ים] que tsi-vu-a yhwh a entre entre homem [בֵּֽין־אָ֣ב] entre pai [בֵּ֥ית] [אָבִֽיהָ׃] casa אָבִֽיהָ׃');
INSERT INTO chapters VALUES (148, 4, 31, 54);
INSERT INTO verses VALUES (4667, 4, 31, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4668, 4, 31, 2, '[נְקֹ֗ם] [נִקְמַת֙] filhos-de Israel de-com הַמִּדְיָנִ֑ים apos [תֵּאָסֵ֥ף] a [sem-traducao]');
INSERT INTO verses VALUES (4669, 4, 31, 3, 'e-falou Moisés a dizendo dizendo [מֵאִתְּכֶ֛ם] [אֲנָשִׁ֖ים] homens [וְיִהְיוּ֙] [עַל־מִדְיָ֔ן] sobre Midian a-dar [sem-traducao] yhwh [sem-traducao]');
INSERT INTO verses VALUES (4670, 4, 31, 4, 'mil [לַמַּטֶּ֔ה] mil para-a-tribo a-todo tribos-de Israel [תִּשְׁלְח֖וּ] látsaba');
INSERT INTO verses VALUES (4671, 4, 31, 5, '[וַיִּמּֽ͏ָסְרוּ֙] [מֵאַלְפֵ֣י] Israel mil para-a-tribo doze dez mil exército exército');
INSERT INTO verses VALUES (4672, 4, 31, 6, 'e-enviou eles Moisés mil [לַמַּטֶּ֖ה] [לַצָּבָ֑א] eles e-a [בֶּן־אֶלְעָזָ֤ר] filho-de Elazar o-sacerdote la-tzava e-vessãis [הַתְּרוּעָ֖ה] [בְּיָדֽוֹ] [sem-traducao] em-mão-sua');
INSERT INTO verses VALUES (4673, 4, 31, 7, '[וַֽיִּצְבְּאוּ֙] sobre [כַּאֲשֶׁ֛ר] como yhwh yhwh a Moisés todo macho');
INSERT INTO verses VALUES (4674, 4, 31, 8, 'e-a reis-de [הָרְג֣וּ] hargu sobre [וְאֶת־רֶ֙קֶם֙] a [וְאֶת־חוּר֙] e-a [חֲמֵ֖שֶׁת] e-a [מִדְיָ֑ן] e-a chur e-a [הָרְג֖וּ] [בֶּחָֽרֶב] reis-de Midiã e-את Balaão filho-de filho-de-Beor eles-mataram pela-espada');
INSERT INTO verses VALUES (4675, 4, 31, 9, '[וַיִּשְׁבּ֧וּ] filhos-de Israel a [וְאֶת־טַפָּ֑ם] e-[OBJ] e-[OBJ] [וְאֶת־כָּל־מִקְנֵהֶ֛ם] e-[OBJ] todo e-[OBJ] todo e-[OBJ] todo');
INSERT INTO verses VALUES (4676, 4, 31, 10, 'e-[OBJ] todo [בְּמ֣וֹשְׁבֹתָ֔ם] e-[OBJ] e-[OBJ] todo [בָּאֵֽשׁ]');
INSERT INTO verses VALUES (4677, 4, 31, 11, 'e-eles-levaram a tudo-de [כָּל־הַמַּלְק֑וֹחַ] e-a e-sobre-os-animais [sem-traducao] a-terra e-na-bestas');
INSERT INTO verses VALUES (4678, 4, 31, 12, '[וַיָּבִ֡אוּ] a Moisés e-a Elazar o-sacerdote e-a congregação-de filhos-de Israel a [מוֹאָ֔ב] e-a [עַל־יַרְדֵּ֥ן] e-a o-salvamento a até a [sem-traducao] Moabe que sobre dizendo יְרֵחֽוֹ׃');
INSERT INTO verses VALUES (4679, 4, 31, 13, 'e-saíram Moisés ve-el-azar o-sacerdote e-todo príncipes a-congregação para-enfrentá-los a ele o-lager');
INSERT INTO verses VALUES (4680, 4, 31, 14, 'e-v-i-q-tsof Moisés sobre pikuday הֶחָיִל príncipes-de הָאֲלָפִים֙ e-príncipes-de os-ma''ot os-vindos [מִצְּבָ֥א] [הַמִּלְחָמָֽה]');
INSERT INTO verses VALUES (4681, 4, 31, 15, 'E-disse a-eles Moisés [הַֽחִיִּיתֶ֖ם] todo fêmea');
INSERT INTO verses VALUES (4682, 4, 31, 16, 'eis [הֵ֜נָּה] foram para-filhos-de Israel em-palavra-de בִּלְעָ֔ם [לִמְסָר־מַ֥עַל] [בַּיהוָ֖ה] em-יהוה sobre palavra-de פּוּאֹר yhwh a praga בַּעֲדַ֥ת yhwh');
INSERT INTO verses VALUES (4683, 4, 31, 17, 'e-agora [הִרְג֥וּ] todo macho [וְכָל־אִשָּׁ֗ה] e-todo mulher Yodáat macho [הֲרֹֽגוּ] macho [sem-traducao]');
INSERT INTO verses VALUES (4684, 4, 31, 18, 'e-tudo [הַטַּ֣ף] [בַּנָּשִׁ֔ים] que não conheceram macho macho a-vós a-vós');
INSERT INTO verses VALUES (4685, 4, 31, 19, 'e-vós [חֲנ֛וּ] de-fora para-o-acampamento sete dias todo [הֹרֵ֨ג] alma e-tudo nog''ah [נֹגֵ֣עַ] [בֶּֽחָלָ֗ל] no-dia no-dia e-no-dia o-sétimo vós [אַתֶּ֖ם]');
INSERT INTO verses VALUES (4686, 4, 31, 20, 'e-todo [וְכָל־כְּלִי־ע֛וֹר] e-todo [עִזִּ֖ים] [וְכָל־כְּלִי־עֵ֑ץ] e-todo e-todo');
INSERT INTO verses VALUES (4687, 4, 31, 21, 'E-disse Elazar o-sacerdote a homens-de [הַבָּאִ֖ים] os-vindos esta esta lei ha-torah yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (4688, 4, 31, 22, 'somente a o-de-ouro e-a o-prata a o-bronze a [sem-traducao] a [sem-traducao] e-a [sem-traducao]');
INSERT INTO verses VALUES (4689, 4, 31, 23, 'todo palavra que vira [בָאֵשׁ֙] [וְטָהֵ֔ר] no-fogo [בְּמֵ֥י] [נִדָּ֖ה] [יִתְחַטָּ֑א] e-tudo [אֲשֶׁ֧ר] e-todo que não virá com-fogo passareis [sem-traducao]');
INSERT INTO verses VALUES (4690, 4, 31, 24, '[וְכִבַּסְתֶּ֧ם] [בִּגְדֵיכֶ֛ם] no-dia ha-shevi-i [וּטְהַרְתֶּ֑ם] e-depois [תָּבֹ֥אוּ] a o-acampamento');
INSERT INTO verses VALUES (4691, 4, 31, 25, 'E-disse yhwh a Moisés');
INSERT INTO verses VALUES (4692, 4, 31, 26, '[שָׂ֗א] a cabeça [מַלְק֙וֹחַ֙] [הַשְּׁבִ֔י] em-o-homem e-sobre-os-animais tu [וְאֶלְעָזָ֣ר] o-sacerdote [וְרָאשֵׁ֖י] [אֲב֥וֹת] הָעֵדָֽה׃');
INSERT INTO verses VALUES (4693, 4, 31, 27, '[וְחָצִ֙יתָ֙] a entre entre agarradores a-guerra que saem e-entre e-entre todo הָעֵדָֽה׃');
INSERT INTO verses VALUES (4694, 4, 31, 28, '[וַהֲרֵמֹתָ֨] [מֶ֜כֶס] a-yhwh [מֵאֵ֞ת] homens-de a-guerra os-que-saem la-tzava um alma [מֵחֲמֵ֖שׁ] [הַמֵּא֑וֹת] de o-homem e-de o-bovino e-de as jumentas e-de o-rebanho');
INSERT INTO verses VALUES (4695, 4, 31, 29, '[מִמַּֽחֲצִיתָ֖ם] [תִּקָּ֑חוּ] e-teráhatá [לְאֶלְעָזָ֥ר] o-sacerdote [תְּרוּמַ֥ת] yhwh');
INSERT INTO verses VALUES (4696, 4, 31, 30, '[וּמִמַּחֲצִ֨ת] filhos-de Israel [׀] um [׀] de [מִן־הַחֲמִשִּׁ֗ים] de o-homem de o-bóqar de [וְנָתַתָּ֤ה] eles a-o-rebanho de-todo הַבְּהֵמָ֑ה וְנָתַתָּ֤ yhwh aos levitas [sem-traducao] guarda-de tabernáculo-de yhwh');
INSERT INTO verses VALUES (4697, 4, 31, 31, 'E-fez Moisés Elazar o-sacerdote como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (4698, 4, 31, 32, 'e-houve [הַמַּלְק֔וֹחַ] resto [הַבָּ֔ז] que [בָּזְז֖וּ] povo o-exército [צֹ֗אן] seis-de centenas mil וְשִׁבְעִים mil [sem-traducao] mil:');
INSERT INTO verses VALUES (4699, 4, 31, 33, '[וּבָקָ֕ר] dois e-setenta mil');
INSERT INTO verses VALUES (4700, 4, 31, 34, '[וַחֲמֹרִ֕ים] um e-sessenta mil');
INSERT INTO verses VALUES (4701, 4, 31, 35, 'e-alma homem de [אֲשֶׁ֥ר] que não macho [כָּל־נֶ֕פֶשׁ] macho todo alma dois e-trinta mil');
INSERT INTO verses VALUES (4702, 4, 31, 36, 'e-foi [הַֽמֶּחֱצָ֔ה] [חֵ֕לֶק] que saem [בַּצָּבָ֑א] número o-rebanho três- centenas mil [אֶ֔לֶף] mil [אֲלָפִ֖ים] milhares e-cinco centenas');
INSERT INTO verses VALUES (4703, 4, 31, 37, 'e-houve [הַמֶּ֥כֶס] a-yhwh de do-rebanho seis centenas cinco e-setenta');
INSERT INTO verses VALUES (4704, 4, 31, 38, '[וְהַ֨בָּקָ֔ר] seis e-trinta mil [וּמִכְסָ֥ם] a-yhwh dois e-setenta');
INSERT INTO verses VALUES (4705, 4, 31, 39, '[וַחֲמֹרִ֕ים] trinta mil e-cinco centenas [וּמִכְסָ֥ם] a-yhwh um e-sessenta');
INSERT INTO verses VALUES (4706, 4, 31, 40, 'e-alma homem seis dez mil [וּמִכְסָם֙] a-yhwh dois e-trinta alma');
INSERT INTO verses VALUES (4707, 4, 31, 41, 'E-colocou Moisés a [תְּרוּמַ֣ת] yhwh yhwh [הַכֹּהֵ֑ן] o-sacerdote como yhwh yhwh a Moisés');
INSERT INTO verses VALUES (4708, 4, 31, 42, '[וּמִֽמַּחֲצִ֖ית] filhos-de Israel que [חָצָ֣ה] Moisés de os-homens [sem-traducao]');
INSERT INTO verses VALUES (4709, 4, 31, 43, '[וַתְּהִ֛י] [מֶחֱצַ֥ת] a-congregação de do-rebanho três- centenas mil [שִׁבְעַ֥ת] mil sete milhares e-cinco centenas');
INSERT INTO verses VALUES (4710, 4, 31, 44, '[וּבָקָ֕ר] seis e-trinta mil');
INSERT INTO verses VALUES (4711, 4, 31, 45, '[וַחֲמֹרִ֕ים] trinta mil e-cinco centenas');
INSERT INTO verses VALUES (4712, 4, 31, 46, 'e-alma homem seis dez mil');
INSERT INTO verses VALUES (4713, 4, 31, 47, 'E-tomou Moisés [מִמַּחֲצִ֣ת] filhos-de Israel um [מִן־הַחֲמִשִּׁ֔ים] um de E-colocou eles o-homem e-de הַבְּהֵמָ֑ה E-deu yhwh [כַּאֲשֶׁ֛ר] [צִוָּ֥ה] yhwh tabernáculo-de yhwh como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (4714, 4, 31, 48, 'e-eles-se-aproximaram a Moisés [אֲשֶׁ֖ר] que [הַצָּבָ֑א] o-exército príncipes-de [וְשָׂרֵ֥י] e-príncipes-de [sem-traducao]');
INSERT INTO verses VALUES (4715, 4, 31, 49, 'e-disseram a Moisés teus-servos [אֶת־רֹ֛אשׁ] a cabeça homens-de ha-milchamah que nós e-não ניפקד dele homem');
INSERT INTO verses VALUES (4716, 4, 31, 50, '[וַנַּקְרֵ֞ב] a yhwh yhwh homem encontrou achou [אֶצְעָדָ֣ה] ouro [טַבַּ֖עַת] [עָגִ֣יל] [וְכוּמָ֑ז] [לְכַפֵּ֥ר] [עַל־נַפְשֹׁתֵ֖ינוּ] para-expiar yhwh almas-nossas diante-de yhwh');
INSERT INTO verses VALUES (4717, 4, 31, 51, 'E-tomou Moisés ve-el-azar o-sacerdote a o-de-ouro de-com-eles todo כְּלִ֥י [sem-traducao]');
INSERT INTO verses VALUES (4718, 4, 31, 52, 'e-houve todo [כָּל־זְהַ֣ב] a-oferta que [הֵרִ֙ימוּ֙] a-yhwh [שִׁשָּׁ֨ה] dez mil sete-de centenas e-cinquenta [מֵאֵת֙] de-com príncipes-de [וּמֵאֵ֖ת] [שָׂרֵ֥י] príncipes-de [sem-traducao]');
INSERT INTO verses VALUES (4719, 4, 31, 53, 'homens-de [הַצָּבָ֔א] [בָּזְז֖וּ] homem a-ele');
INSERT INTO verses VALUES (4720, 4, 31, 54, 'E-tomou Moisés [וְאֶלְעָזָ֤ר] o-sacerdote a o-ouro de-junto-de príncipes-de [וְהַמֵּא֑וֹת] [וַיָּבִ֤אוּ] ele ele a tenda encontro [לִפְנֵ֥י] yhwh Israel diante-de yhwh');
INSERT INTO chapters VALUES (149, 4, 32, 42);
INSERT INTO verses VALUES (4721, 4, 32, 1, '[וּמִקְנֶ֣ה] muito foi ser Rúben [רְאוּבֵ֛ן] Gad עָצ֣וּם muito e-eles-veem a terra ya''zer e-a terra Gileade e-eis o-lugar מָקוֹם [sem-traducao]');
INSERT INTO verses VALUES (4722, 4, 32, 2, 'e-vieram filhos-de Gad e-filhos-de Rúben e-disseram a Moisés e-a Eleazar dizendo e-a a-terra a-congregação para-dizer');
INSERT INTO verses VALUES (4723, 4, 32, 3, '[עֲטָר֤וֹת] [וְדִיבֹן֙] [וְיַעְזֵ֣ר] [וְנִמְרָ֔ה] [וְחֶשְׁבּ֖וֹן] [וְאֶלְעָלֵ֑ה] [וּשְׂבָ֥ם] [וּנְב֖וֹ] [וּבְעֹֽן]');
INSERT INTO verses VALUES (4724, 4, 32, 4, 'a-terra que bateu yhwh diante-de congregação-de Israel terra [מִקְנֶ֖ה] ela [וְלַֽעֲבָדֶ֖יךָ] [מִקְנֶֽה׃]');
INSERT INTO verses VALUES (4725, 4, 32, 5, 'e-disseram se [חֵן֙] graça em-tua-olho [אֶת־הָאָ֧רֶץ] a a-terra esta [אַל־תַּעֲבִרֵ֖נוּ] [אֶת־הַיַּרְדֵּֽן] a [sem-traducao] a o-Jordão');
INSERT INTO verses VALUES (4726, 4, 32, 6, 'E-disse Moisés para-filhos-de Gad e-para-filhos-de Rúben [יָבֹ֙אוּ֙] יָבוֹא para-a-guerra e-vós [פֹֽה] [sem-traducao]');
INSERT INTO verses VALUES (4727, 4, 32, 7, '[וְלָ֣מָּה] a coração filhos-de Israel [יִשְׂרָאֵ֑ל] a a-terra que a-eles yhwh yhwh');
INSERT INTO verses VALUES (4728, 4, 32, 8, 'assim fizeram [אֲבֹתֵיכֶ֑ם] [בְּשָׁלְחִ֥י] eles [מִקָּדֵ֥שׁ] [בַּרְנֵ֖עַ] para-ver a a-terra');
INSERT INTO verses VALUES (4729, 4, 32, 9, '[וַֽיַּעֲל֞וּ] até vale-de [וַיִּרְאוּ֙] e-eles-viram a a-terra [בְּנֵ֣י] a coração filhos-de Israel a-eles yhwh a a-terra que deu a-eles yhwh');
INSERT INTO verses VALUES (4730, 4, 32, 10, 'e-acendeu-se- yhwh no-dia no-dia aquele dizendo para-dizer');
INSERT INTO verses VALUES (4731, 4, 32, 11, 'se [הָאֲנָשִׁ֜ים] os-homens [מִמִּצְרַ֗יִם] desde-Mitsrayim de-filho-de vinte ano e-para-cima a-terra האדמה que [לְאַבְרָהָ֥ם] para-Abraao para-Isaque que porque não yhwh depois-de-mim');
INSERT INTO verses VALUES (4732, 4, 32, 12, '[בִּלְתִּ֞י] Calebe filho-de [הַקְּנִזִּ֔י] o-qenizi e Josué que נ֑וּן porque yhwh atrás-de yhwh');
INSERT INTO verses VALUES (4733, 4, 32, 13, 'e-acendeu-se- yhwh yhwh em-Israel [בַּמִּדְבָּ֔ר] no-deserto quarenta ano até [הָעֹשֶׂ֥ה] todo [בְּעֵינֵ֥י] yhwh o-mal em-olhos-de yhwh');
INSERT INTO verses VALUES (4734, 4, 32, 14, 'e-eis [קַמְתֶּ֗ם] debaixo [אֲבֹ֣תֵיכֶ֔ם] [תַּרְבּ֖וּת] homens [חַטָּאִ֑ים] [לִסְפּ֣וֹת] ainda sobre חֲרֹן também yhwh a Israel');
INSERT INTO verses VALUES (4735, 4, 32, 15, 'que [תְשׁוּבֻן֙] [מֵֽאַחֲרָ֔יו] [וְיָסַ֣ף] ainda [לְהַנִּיח֖וֹ] no-deserto [וְשִֽׁחַתֶּ֖ם] para-todo o-povo a-esta');
INSERT INTO verses VALUES (4736, 4, 32, 16, '[וַיִּגְּשׁ֤וּ] a-ele e-disseram [גִּדְרֹ֥ת] rebanho-de [נִבְנֶ֥ה] [לְמִקְנֵ֖נוּ] [פֹּ֑ה] [וְעָרִ֖ים] [לְטַפֵּֽנוּ]');
INSERT INTO verses VALUES (4737, 4, 32, 17, '[וַאֲנַ֜חְנוּ] [נֵחָלֵ֣ץ] [חֻשִׁ֗ים] diante-de filhos-de Israel até que se [אֶל־מְקוֹמָ֑ם] a [טַפֵּ֙נוּ֙] [בְּעָרֵ֣י] [הַמִּבְצָ֔ר] de-diante-de [יֹשְׁבֵ֥י] a-terra habitantes-de a-terra');
INSERT INTO verses VALUES (4738, 4, 32, 18, 'não retornaremos a até até [בְּנֵ֣י] filhos-de Israel homem herança-dele');
INSERT INTO verses VALUES (4739, 4, 32, 19, 'que não [נִנְחַל֙] com-elas-os do-outro-lado [לַיַּרְדֵּ֖ן] והלאה que [בָ֤אָה] [נַחֲלָתֵ֙נוּ֙] [אֵלֵ֔ינוּ] do-outro-lado o Jordão mizrachah');
INSERT INTO verses VALUES (4740, 4, 32, 20, 'E-disse a-eles Moisés se [אֶת־הַדָּבָ֣ר] a a-palavra este yhwh diante-de yhwh');
INSERT INTO verses VALUES (4741, 4, 32, 21, 'e-passou a-vós todo [אֶת־הַיַּרְדֵּ֖ן] a yhwh até yhwh até [מִפָּנָֽיו] a seus inimigos de-face-dele');
INSERT INTO verses VALUES (4742, 4, 32, 22, '[וְנִכְבְּשָׁ֨ה] a-terra diante-de yhwh e-apos [תָּשֻׁ֔בוּ] e-sereis [נְקִיִּ֛ים] de-יהוה [וּמִיִּשְׂרָאֵ֑ל] והיהת a-terra [הַזֹּ֥את] a-vós [לַאֲחֻזָּ֖ה] diante-de yhwh');
INSERT INTO verses VALUES (4743, 4, 32, 23, 'e-se não תַעֲשׂוּן֙ eis eis pecado-vos a-yhwh [חַטַּאתְכֶ֔ם] [אֲשֶׁ֥ר] que [אֶתְכֶֽם] a-vós');
INSERT INTO verses VALUES (4744, 4, 32, 24, '[בְּנֽוּ־לָכֶ֤ם] a-vos Arim [וּגְדֵרֹ֖ת] [לְצֹנַאֲכֶ֑ם] [וְהַיֹּצֵ֥א] [מִפִּיכֶ֖ם] de-vossas façam');
INSERT INTO verses VALUES (4745, 4, 32, 25, 'E-disse filhos-de Gad e-filhos-de Rúben dizendo Moisés dizendo teus-servos [Adonai] como Adonai [sem-traducao]');
INSERT INTO verses VALUES (4746, 4, 32, 26, '[טַפֵּ֣נוּ] nossas-mulheres [מִקְנֵ֖נוּ] e-todo [יִֽהְיוּ־שָׁ֖ם] serao nome em-cidades-de o-Gileade');
INSERT INTO verses VALUES (4747, 4, 32, 27, '[וַעֲבָדֶ֨יךָ] [יַֽעַבְר֜וּ] todo exército [לִפְנֵ֥י] yhwh yhwh para-a-guerra como Adonai palavra');
INSERT INTO verses VALUES (4748, 4, 32, 28, 'E-ordenou a-eles Moisés a Eleazar o-sacerdote e-a Yehoshua filho-de [וְאֶת־רָאשֵׁ֛י] e-[OBJ] [הַמַּטּ֖וֹת] [לִבְנֵ֥י] [יִשְׂרָאֵֽל] para-filhos-de Israel');
INSERT INTO verses VALUES (4749, 4, 32, 29, 'E-disse Moisés [אֲלֵהֶ֗ם] se [בְנֵי־גָ֣ד] filhos-de [׀] [אִ֠תְּכֶם] [אֶֽת־הַיַּרְדֵּ֞ן] [כָּל־חָל֤וּץ] a [לִפְנֵ֣י] yhwh [וְנִכְבְּשָׁ֥ה] a-terra diante-de yhwh a-eles a-terra [הַגִּלְעָ֖ד] [לַאֲחֻזָּֽה] a terra');
INSERT INTO verses VALUES (4750, 4, 32, 30, 'e-se não [חֲלוּצִ֖ים] [אִתְּכֶ֑ם] [וְנֹֽאחֲז֥וּ] [בְתֹכְכֶ֖ם] [בְּאֶ֥רֶץ] [כְּנָֽעַן]');
INSERT INTO verses VALUES (4751, 4, 32, 31, '[וַיַּֽעֲנ֧וּ] filhos-de [וּבְנֵ֥י] [רְאוּבֵ֖ן] dizendo dizendo a que yhwh yhwh a [נַעֲשֶֽׂה]');
INSERT INTO verses VALUES (4752, 4, 32, 32, '[נַ֣חְנוּ] [נַעֲבֹ֧ר] [חֲלוּצִ֛ים] diante-de yhwh terra assim [וְאִתָּ֙נוּ֙] [אֲחֻזַּ֣ת] [נַחֲלָתֵ֔נוּ] [מֵעֵ֖בֶר] [לַיַּרְדֵּֽן]');
INSERT INTO verses VALUES (4753, 4, 32, 33, 'E-colocou a-eles Moisés [מֹשֶׁ֡ה] [לִבְנֵי־גָד֩] [וְלִבְנֵ֨י] [רְאוּבֵ֜ן] [וְלַחֲצִ֣י] [׀] [שֵׁ֣בֶט] filho-de José a [אֶת־מַמְלֶ֙כֶת֙] [סִיחֹן֙] rei [הָֽאֱמֹרִ֔י] e-[OBJ] [ע֖וֹג] [מֶ֣לֶךְ] rei a-terra a-terra [בִּגְבֻלֹ֔ת] [עָרֵ֥י] a-terra a-terra ao-redor');
INSERT INTO verses VALUES (4754, 4, 32, 34, '[וַיִּבְנ֣וּ] filhos-de [אֶת־דִּיבֹ֖ן] a e-[OBJ] e-[OBJ] e-[OBJ]');
INSERT INTO verses VALUES (4755, 4, 32, 35, 'e-[OBJ] [שׁוֹפָ֛ן] [וְאֶת־יַעְזֵ֖ר] e-[OBJ]');
INSERT INTO verses VALUES (4756, 4, 32, 36, 'e-[OBJ] casa [וְאֶת־בֵּ֣ית] e-[OBJ] casa [מִבְצָ֖ר] cidades-de [צֹֽאן]');
INSERT INTO verses VALUES (4757, 4, 32, 37, '[וּבְנֵ֤י] [רְאוּבֵן֙] [בָּנ֔וּ] a [וְאֶת־אֶלְעָלֵ֑א] e-[OBJ] [קִרְיָתָֽיִם] e-[OBJ]');
INSERT INTO verses VALUES (4758, 4, 32, 38, 'e-[OBJ] [וְאֶת־בַּ֧עַל] e-[OBJ] [מֽוּסַבֹּ֥ת] [שֵׁ֖ם] [וְאֶת־שִׂבְמָ֑ה] nome e-[OBJ] [אֶת־שְׁמ֥וֹת] [הֶעָרִ֖ים] [אֲשֶׁ֥ר] a que');
INSERT INTO verses VALUES (4759, 4, 32, 39, '[וַיֵּ֨לְכ֜וּ] filhos-de [מָכִ֧יר] filho-de [גִּלְעָ֖דָה] [וַֽיִּלְכְּדֻ֑הָ] [וַיּ֖וֹרֶשׁ] [אֶת־הָאֱמֹרִ֥י] a que');
INSERT INTO verses VALUES (4760, 4, 32, 40, 'E-colocou Moisés a [לְמָכִ֖יר] [בֶּן־מְנַשֶּׁ֑ה] filho-de [בָּֽהּ]');
INSERT INTO verses VALUES (4761, 4, 32, 41, '[וְיָאִ֤יר] filho-de andar andou [אֶת־חַוֺּתֵיהֶ֑ם] E-chamou [אֶתְהֶ֖ן] E-chamou a-elas [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (4762, 4, 32, 42, '[וְנֹ֣בַח] andar [וַיִּלְכֹּ֥ד] a [וְאֶת־בְּנֹתֶ֑יהָ] E-chamou [לָ֦ה] E-chamou [בִּשְׁמֽוֹ׃]');
INSERT INTO chapters VALUES (150, 4, 33, 56);
INSERT INTO verses VALUES (4763, 4, 33, 1, 'Estas [מַסְעֵ֣י] filhos-de Israel que [מֵאֶ֥רֶץ] da-terra-de Egito [בְּיַד־מֹשֶׁ֖ה] pela-mão-de Moisés');
INSERT INTO verses VALUES (4764, 4, 33, 2, '[וַיִּכְתֹּ֨ב] Moisés a [לְמַסְעֵיהֶ֖ם] [עַל־פִּ֣י] yhwh boca-de yhwh [לְמוֹצָאֵיהֶֽם]');
INSERT INTO verses VALUES (4765, 4, 33, 3, '[וַיִּסְע֤וּ] [מֵֽרַעְמְסֵס֙] [בַּחֹ֣דֶשׁ] [הָֽרִאשׁ֔וֹן] [בַּחֲמִשָּׁ֥ה] dez dia no-mês [הָרִאשׁ֑וֹן] [מִֽמָּחֳרַ֣ת] [הַפֶּ֗סַח] sairam filhos-de Israel [רָמָ֔ה] [לְעֵינֵ֖י] aos-olhos-de todo Egito');
INSERT INTO verses VALUES (4766, 4, 33, 4, '[וּמִצְרַ֣יִם] [מְקַבְּרִ֗ים] a que [הִכָּ֧ה] yhwh [בָּהֶ֖ם] todo [וּבֵאלֹ֣הֵיהֶ֔ם] [עָשָׂ֥ה] yhwh yhwh');
INSERT INTO verses VALUES (4767, 4, 33, 5, '[וַיִּסְע֥וּ] filhos-de Israel [וַֽיַּחֲנ֖וּ] e-acamparam');
INSERT INTO verses VALUES (4768, 4, 33, 6, 'e-partiram [מִסֻּכֹּ֑ת] [וַיַּחֲנ֣וּ] [בְאֵתָ֔ם] que [בִּקְצֵ֥ה] [הַמִּדְבָּֽר]');
INSERT INTO verses VALUES (4769, 4, 33, 7, '[וַיִּסְעוּ֙] [מֵֽאֵתָ֔ם] [וַיָּ֙שָׁב֙] sobre boca-de [אֲשֶׁ֥ר] que sobre face-de [וַֽיַּחֲנ֖וּ] [לִפְנֵ֥י] e-acamparam');
INSERT INTO verses VALUES (4770, 4, 33, 8, '[וַיִּסְעוּ֙] de-diante-de [הַֽחִירֹ֔ת] [וַיַּֽעַבְר֥וּ] no-meio-de [הַמִּדְבָּ֑רָה] [וַיֵּ֨לְכ֜וּ] o-caminho-de caminho [יָמִים֙] [בְּמִדְבַּ֣ר] [אֵתָ֔ם] [וַֽיַּחֲנ֖וּ] e-acamparam [sem-traducao]');
INSERT INTO verses VALUES (4771, 4, 33, 9, '[וַיִּסְעוּ֙] [מִמָּרָ֔ה] [וַיָּבֹ֖אוּ] [אֵילִ֑מָה] [וּ֠בְאֵילִם] [שְׁתֵּ֣ים] [עֶשְׂרֵ֞ה] [עֵינֹ֥ת] águas [וְשִׁבְעִ֥ים] [תְּמָרִ֖ים] [וַיַּחֲנוּ־שָֽׁם] nome');
INSERT INTO verses VALUES (4772, 4, 33, 10, 'e-partiram [מֵאֵילִ֑ם] e-acamparam sobre');
INSERT INTO verses VALUES (4773, 4, 33, 11, 'e-partiram [מִיַּם־ס֑וּף] [וַֽיַּחֲנ֖וּ] e-acamparam');
INSERT INTO verses VALUES (4774, 4, 33, 12, 'e-partiram [מִמִּדְבַּר־סִ֑ין] [וַֽיַּחֲנ֖וּ] e-acamparam');
INSERT INTO verses VALUES (4775, 4, 33, 13, 'e-partiram [מִדָּפְקָ֑ה] e-acamparam [בְּאָלֽוּשׁ]');
INSERT INTO verses VALUES (4776, 4, 33, 14, 'e-partiram [מֵאָל֑וּשׁ] [וַֽיַ[t]חֲנוּ֙] e-não foi nome águas [לָעָ֖ם] [לִשְׁתּֽוֹת]');
INSERT INTO verses VALUES (4777, 4, 33, 15, 'e-partiram [מֵרְפִידִ֑ם] e-acamparam [בְּמִדְבַּ֥ר] [סִינָֽי]');
INSERT INTO verses VALUES (4778, 4, 33, 16, 'e-partiram [מִמִּדְבַּ֣ר] Sinai e-acamparam [בְּקִבְרֹ֥ת] [הַֽתַּאֲוָֽה]');
INSERT INTO verses VALUES (4779, 4, 33, 17, 'e-partiram [מִקִּבְרֹ֣ת] [הַֽתַּאֲוָ֑ה] e-acamparam [בַּחֲצֵרֹֽת]');
INSERT INTO verses VALUES (4780, 4, 33, 18, 'e-partiram [מֵחֲצֵרֹ֑ת] e-acamparam [בְּרִתְמָֽה]');
INSERT INTO verses VALUES (4781, 4, 33, 19, 'e-partiram [מֵרִתְמָ֑ה] e-acamparam [בְּרִמֹּ֥ן] [פָּֽרֶץ]');
INSERT INTO verses VALUES (4782, 4, 33, 20, 'e-partiram [מֵרִמֹּ֣ן] [פָּ֑רֶץ] e-acamparam [בְּלִבְנָֽה]');
INSERT INTO verses VALUES (4783, 4, 33, 21, 'e-partiram [מִלִּבְנָ֑ה] e-acamparam [בְּרִסָּֽה]');
INSERT INTO verses VALUES (4784, 4, 33, 22, 'e-partiram [מֵרִסָּ֑ה] e-acamparam [בִּקְהֵלָֽתָה]');
INSERT INTO verses VALUES (4785, 4, 33, 23, 'e-partiram [מִקְּהֵלָ֑תָה] e-acamparam [בְּהַר־שָֽׁפֶר]');
INSERT INTO verses VALUES (4786, 4, 33, 24, 'e-partiram [מֵֽהַר־שָׁ֑פֶר] [וַֽיַּחֲנ֖וּ] e-acamparam');
INSERT INTO verses VALUES (4787, 4, 33, 25, 'e-partiram [מֵחֲרָדָ֑ה] e-acamparam [בְּמַקְהֵלֹֽת]');
INSERT INTO verses VALUES (4788, 4, 33, 26, 'e-partiram [מִמַּקְהֵלֹ֑ת] e-acamparam [בְּתָֽחַת]');
INSERT INTO verses VALUES (4789, 4, 33, 27, 'e-partiram [מִתָּ֑חַת] e-acamparam [בְּתָֽרַח]');
INSERT INTO verses VALUES (4790, 4, 33, 28, 'e-partiram [מִתָּ֑רַח] e-acamparam [בְּמִתְקָֽה]');
INSERT INTO verses VALUES (4791, 4, 33, 29, 'e-partiram [מִמִּתְקָ֑ה] e-acamparam [בְּחַשְׁמֹנָֽה]');
INSERT INTO verses VALUES (4792, 4, 33, 30, 'e-partiram [מֵֽחַשְׁמֹנָ֑ה] e-acamparam [בְּמֹסֵרֽוֹת]');
INSERT INTO verses VALUES (4793, 4, 33, 31, 'e-partiram [מִמֹּסֵר֑וֹת] e-acamparam [בִּבְנֵ֥י] [יַעֲקָֽן]');
INSERT INTO verses VALUES (4794, 4, 33, 32, 'e-partiram [מִבְּנֵ֣י] [יַעֲקָ֑ן] e-acamparam [בְּחֹ֥ר] [הַגִּדְגָּֽד]');
INSERT INTO verses VALUES (4795, 4, 33, 33, 'e-partiram [מֵחֹ֣ר] [הַגִּדְגָּ֑ד] e-acamparam [בְּיָטְבָֽתָה]');
INSERT INTO verses VALUES (4796, 4, 33, 34, 'e-partiram [מִיָּטְבָ֑תָה] e-acamparam [בְּעַבְרֹנָֽה]');
INSERT INTO verses VALUES (4797, 4, 33, 35, 'e-partiram [מֵֽעַבְרֹנָ֑ה] e-acamparam [בְּעֶצְי֥וֹן] [גָּֽבֶר]');
INSERT INTO verses VALUES (4798, 4, 33, 36, 'e-partiram [מֵעֶצְי֣וֹן] [גָּ֑בֶר] [וַיַּחֲנ֥וּ] [בְמִדְבַּר־צִ֖ן] ela [קָדֵֽשׁ]');
INSERT INTO verses VALUES (4799, 4, 33, 37, 'e-partiram [מִקָּדֵ֑שׁ] [וַֽיַּחֲנוּ֙] [בְּהֹ֣ר] o-monte [בִּקְצֵ֖ה] terra [אֱדֽוֹם]');
INSERT INTO verses VALUES (4800, 4, 33, 38, '[וַיַּעַל֩] Aarao o-sacerdote a [הָהָ֛ר] [עַל־פִּ֥י] yhwh [וַיָּ֣מָת] yhwh E-morreu nome no-ano-de [בְּנֵֽי־יִשְׂרָאֵל֙] [מֵאֶ֣רֶץ] filhos-de Israel da-terra Egito [לַחֹֽדֶשׁ] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (4801, 4, 33, 39, '[וְאַהֲרֹ֔ן] filho-de três [וּמְאַ֖ת] [שָׁנָ֑ה] ano [בְּהֹ֥ר] [הָהָֽר׃]');
INSERT INTO verses VALUES (4802, 4, 33, 40, 'E-ouviu [הַֽכְּנַעֲנִי֙] rei [עֲרָ֔ד] [וְהֽוּא־יֹשֵׁ֥ב] habitou [בְּאֶ֣רֶץ] na-terra assim [בְּנֵ֥י] filhos-de Israel');
INSERT INTO verses VALUES (4803, 4, 33, 41, 'e-partiram [מֵהֹ֣ר] o-monte e-acamparam [בְּצַלְמֹנָֽה]');
INSERT INTO verses VALUES (4804, 4, 33, 42, 'e-partiram [מִצַּלְמֹנָ֑ה] e-acamparam [בְּפוּנֹֽן]');
INSERT INTO verses VALUES (4805, 4, 33, 43, 'e-partiram [מִפּוּנֹ֑ן] e-acamparam [בְּאֹבֹֽת]');
INSERT INTO verses VALUES (4806, 4, 33, 44, 'e-partiram [מֵאֹבֹ֑ת] [וַֽיַּחֲנ֛וּ] [בְּעִיֵּ֥י] [הָעֲבָרִ֖ים] [בִּגְב֥וּל] [מוֹאָֽב]');
INSERT INTO verses VALUES (4807, 4, 33, 45, 'e-partiram [מֵעִיִּ֑ים] e-acamparam [בְּדִיבֹ֥ן] [גָּֽד]');
INSERT INTO verses VALUES (4808, 4, 33, 46, 'e-partiram [מִדִּיבֹ֣ן] [גָּ֑ד] e-acamparam [בְּעַלְמֹ֥ן] [דִּבְלָתָֽיְמָה]');
INSERT INTO verses VALUES (4809, 4, 33, 47, 'e-partiram [מֵעַלְמֹ֣ן] [דִּבְלָתָ֑יְמָה] [וַֽיַּחֲנ֛וּ] [בְּהָרֵ֥י] [הָעֲבָרִ֖ים] diante-de [נְבֽוֹ]');
INSERT INTO verses VALUES (4810, 4, 33, 48, 'e-partiram [מֵהָרֵ֣י] [הָעֲבָרִ֑ים] [וַֽיַּחֲנוּ֙] [בְּעַֽרְבֹ֣ת] Moabe sobre [יַרְדֵּ֥ן] [יְרֵחֽוֹ]');
INSERT INTO verses VALUES (4811, 4, 33, 49, '[וַיַּחֲנ֤וּ] sobre [מִבֵּ֣ית] [הַיְשִׁמֹ֔ת] até até Abel [בְּעַֽרְבֹ֖ת] [מוֹאָֽב׃] Moabe');
INSERT INTO verses VALUES (4812, 4, 33, 50, '[וַיְדַבֵּ֧ר] yhwh a Moisés [מוֹאָ֑ב] [עַל־יַרְדֵּ֥ן] sobre dizendo');
INSERT INTO verses VALUES (4813, 4, 33, 51, 'palavra a filhos-de Israel [אֲלֵהֶ֑ם] que porque vós [אֶת־הַיַּרְדֵּ֖ן] a [כְּנָֽעַן] a terra');
INSERT INTO verses VALUES (4814, 4, 33, 52, '[וְה֨וֹרַשְׁתֶּ֜ם] a a-terra [מִפְּנֵיכֶ֔ם] a-terra [OBJ] [כָּל־מַשְׂכִּיֹּתָ֑ם] e-[OBJ] todo [מַסֵּֽכֹתָם֙] e-[OBJ] e-[OBJ] [כָּל־בָּמֹתָ֖ם] [תַּשְׁמִֽידוּ] e-[OBJ] todo');
INSERT INTO verses VALUES (4815, 4, 33, 53, '[וְהוֹרַשְׁתֶּ֥ם] a a-terra que a-vós dei a-vós [לָרֶ֥שֶׁת] a a-terra');
INSERT INTO verses VALUES (4816, 4, 33, 54, '[וְהִתְנַחַלְתֶּם֩] a a-terra [לְמִשְׁפְּחֹֽתֵיכֶ֗ם] [לָרַ֞ב] [תַּרְבּ֤וּ] [אֶת־נַחֲלָתוֹ֙] a [תַּמְעִ֣יט] [אֶת־נַחֲלָת֔וֹ] a a a-ele El que a-ele será [לְמַטּ֥וֹת] [אֲבֹתֵיכֶ֖ם] a-ele');
INSERT INTO verses VALUES (4817, 4, 33, 55, 'e-se não [אֶת־יֹשְׁבֵ֣י] a-terra habitantes-de a-terra [אֲשֶׁ֣ר] e-foi que [לְשִׂכִּים֙] [בְּעֵ֣ינֵיכֶ֔ם] [וְלִצְנִינִ֖ם] [בְּצִדֵּיכֶ֑ם] [וְצָרֲר֣וּ] [אֶתְכֶ֔ם] [עַל־הָאָ֕רֶץ] vos sobre a-terra que');
INSERT INTO verses VALUES (4818, 4, 33, 56, 'e-foi como [דִּמִּ֛יתִי] para-fazer a-eles [אֽ͏ֶעֱשֶׂ֥ה] a-vós');
INSERT INTO chapters VALUES (151, 4, 34, 29);
INSERT INTO verses VALUES (4819, 4, 34, 1, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4820, 4, 34, 2, '[צַ֞ו] a filhos-de Israel e-dirás a-eles porque vós [כְּנָ֑עַן] esta a-terra assim [תִּפֹּ֤ל] a-vós que terra a-vós [לִגְבֻלֹתֶֽיהָ] terra [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (4821, 4, 34, 3, 'e-será a-vós canto [מִמִּדְבַּר־צִ֖ן] [עַל־יְדֵ֣י] [אֱד֑וֹם] sobre a-vós [גְּב֣וּל] e-será a-vós fronteira [קֵֽדְמָה]');
INSERT INTO verses VALUES (4822, 4, 34, 4, '[וְנָסַ֣ב] a-vós [הַגְּב֨וּל] [מִנֶּ֜גֶב] [לְמַעֲלֵ֤ה] [עַקְרַבִּים֙] [וְעָ֣בַר] [צִ֔נָה] [*והיה] [**וְהָיוּ֙] [תּֽוֹצְאֹתָ֔יו] [מִנֶּ֖גֶב] e-saiu [בַּרְנֵ֑עַ] [וְיָצָ֥א] [חֲצַר־אַדָּ֖ר] [וְעָבַ֥ר]');
INSERT INTO verses VALUES (4823, 4, 34, 5, '[וְנָסַ֧ב] [הַגְּב֛וּל] [מֵעַצְמ֖וֹן] [נַ֣חְלָה] Egito e-sejam [תוֹצְאֹתָ֖יו] [הַיָּֽמָּה]');
INSERT INTO verses VALUES (4824, 4, 34, 6, '[וּגְב֣וּל] mar e-será a-vós o-mar [הַגָּד֖וֹל] [וּגְב֑וּל] este a-vós a-vós mar mar');
INSERT INTO verses VALUES (4825, 4, 34, 7, '[וְזֶֽה־יִהְיֶ֥ה] a-vós a-vós fronteira norte o-grande [תְּתָא֥וּ] a-vós [הֹ֥ר] a-vós [sem-traducao] a-montanha');
INSERT INTO verses VALUES (4826, 4, 34, 8, '[מֵהֹ֣ר] o-monte [תְּתָא֖וּ] [לְבֹ֣א] Hamate e-sejam [תּוֹצְאֹ֥ת] [הַגְּבֻ֖ל] [צְדָֽדָה]');
INSERT INTO verses VALUES (4827, 4, 34, 9, '[וְיָצָ֤א] [הַגְּבֻל֙] [זִפְרֹ֔נָה] e-sejam [תוֹצְאֹתָ֖יו] [חֲצַ֣ר] [עֵינָ֑ן] este a-vós a-vós [צָפֽוֹן] [sem-traducao]');
INSERT INTO verses VALUES (4828, 4, 34, 10, '[וְהִתְאַוִּיתֶ֥ם] a-vós [לִגְב֣וּל] [קֵ֑דְמָה] [מֵחֲצַ֥ר] [עֵינָ֖ן] [שְׁפָֽמָה]');
INSERT INTO verses VALUES (4829, 4, 34, 11, '[וְיָרַ֨ד] [הַגְּבֻ֧ל] [מִשְּׁפָ֛ם] [הָרִבְלָ֖ה] ao-oriente [לָעָ֑יִן] [וְיָרַ֣ד] [הַגְּב֔וּל] [וּמָחָ֛ה] sobre [יָם־כִּנֶּ֖רֶת] [קֵֽדְמָה]');
INSERT INTO verses VALUES (4830, 4, 34, 12, '[וְיָרַ֤ד] [הַגְּבוּל֙] [הַיַּרְדֵּ֔נָה] e-sejam [תוֹצְאֹתָ֖יו] mar [הַמֶּ֑לַח] esta [תִּהְיֶ֨ה] a-vós a-terra [לִגְבֻלֹתֶ֖יהָ] ao-redor');
INSERT INTO verses VALUES (4831, 4, 34, 13, 'E-ordenou Moisés a filhos-de dizendo esta a-terra a-terra que [אֹתָהּ֙] [בְּגוֹרָ֔ל] [אֲשֶׁר֙] que yhwh yhwh [לְתִשְׁעַ֥ת] [הַמַּטּ֖וֹת] [וַחֲצִ֥י] [הַמַּטֶּֽה]');
INSERT INTO verses VALUES (4832, 4, 34, 14, 'que [לָקְח֞וּ] [מַטֵּ֨ה] filhos-de [הָראוּבֵנִי֙] para-casa-de [אֲבֹתָ֔ם] [וּמַטֵּ֥ה] filhos-de [לְבֵ֣ית] para-casa-de [וַחֲצִי֙] [מַטֵּ֣ה] [מְנַשֶּׁ֔ה] [לָקְח֖וּ] [נַחֲלָתָֽם]');
INSERT INTO verses VALUES (4833, 4, 34, 15, 'segundo [הַמַּטּ֖וֹת] [וַחֲצִ֣י] [הַמַּטֶּ֑ה] [לָקְח֣וּ] [נַחֲלָתָ֗ם] [מֵעֵ֛בֶר] [לְיַרְדֵּ֥ן] [יְרֵח֖וֹ] [קֵ֥דְמָה] [מִזְרָֽחָה׃]');
INSERT INTO verses VALUES (4834, 4, 34, 16, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4835, 4, 34, 17, 'Estas [שְׁמ֣וֹת] [הָֽאֲנָשִׁ֔ים] que a-vós a-vós a a-terra [וִיהוֹשֻׁ֖עַ] o-sacerdote filho-de');
INSERT INTO verses VALUES (4836, 4, 34, 18, '[וְנָשִׂ֥יא] um [נָשִׂ֥יא] um [מִמַּטֶּ֑ה] [תִּקְח֖וּ] [לִנְחֹ֥ל] a a-terra');
INSERT INTO verses VALUES (4837, 4, 34, 19, '[וְאֵ֖לֶּה] [שְׁמ֣וֹת] [הָאֲנָשִׁ֑ים] para-a-tribo-de Judá [כָּלֵ֖ב] filho-de');
INSERT INTO verses VALUES (4838, 4, 34, 20, '[וּלְמַטֵּה֙] filhos-de [שִׁמְע֔וֹן] [שְׁמוּאֵ֖ל] filho-de');
INSERT INTO verses VALUES (4839, 4, 34, 21, 'para-a-tribo-de [בִנְיָמִ֔ן] [אֱלִידָ֖ד] filho-de');
INSERT INTO verses VALUES (4840, 4, 34, 22, '[וּלְמַטֵּ֥ה] filhos-de [נָשִׂ֑יא] [בֻּקִּ֖י] [בֶּן־יָגְלִֽי] filho-de');
INSERT INTO verses VALUES (4841, 4, 34, 23, 'aos-filhos-de [יוֹסֵ֔ף] [לְמַטֵּ֥ה] filhos-de [נָשִׂ֑יא] [חַנִּיאֵ֖ל] [בֶּן־אֵפֹֽד] filho-de');
INSERT INTO verses VALUES (4842, 4, 34, 24, '[וּלְמַטֵּ֥ה] filhos-de Efraim [קְמוּאֵ֖ל] [בֶּן־שִׁפְטָֽן] filho-de');
INSERT INTO verses VALUES (4843, 4, 34, 25, '[וּלְמַטֵּ֥ה] filhos-de [נָשִׂ֑יא] [אֱלִיצָפָ֖ן] [בֶּן־פַּרְנָֽךְ] filho-de');
INSERT INTO verses VALUES (4844, 4, 34, 26, '[וּלְמַטֵּ֥ה] filhos-de [נָשִׂ֑יא] [פַּלְטִיאֵ֖ל] [בֶּן־עַזָּֽן] filho-de');
INSERT INTO verses VALUES (4845, 4, 34, 27, '[וּלְמַטֵּ֥ה] filhos-de que [אֲחִיה֖וּד] [בֶּן־שְׁלֹמִֽי] filho-de');
INSERT INTO verses VALUES (4846, 4, 34, 28, '[וּלְמַטֵּ֥ה] filhos-de [נָשִׂ֑יא] [פְּדַהְ[t]אֵ֖ל] filho-de');
INSERT INTO verses VALUES (4847, 4, 34, 29, 'Estas que ordenou yhwh [לְנַחֵ֥ל] a filhos-de Israel');
INSERT INTO chapters VALUES (152, 4, 35, 34);
INSERT INTO verses VALUES (4848, 4, 35, 1, '[וַיְדַבֵּ֧ר] yhwh a Moisés [מוֹאָ֑ב] [עַל־יַרְדֵּ֥ן] sobre dizendo');
INSERT INTO verses VALUES (4849, 4, 35, 2, '[צַו֮] a filhos-de Israel [לַלְוִיִּ֗ם] [מִֽנַּחֲלַ֛ת] [אֲחֻזָּתָ֖ם] [עָרִ֣ים] [לָשָׁ֑בֶת] [וּמִגְרָ֗שׁ] [לֶֽעָרִים֙] [סְבִיבֹ֣תֵיהֶ֔ם] [תִּתְּנ֖וּ] [לַלְוִיִּֽם]');
INSERT INTO verses VALUES (4850, 4, 35, 3, 'e-sejam [הֽ͏ֶעָרִ֛ים] a-eles [לָשָׁ֑בֶת] [וּמִגְרְשֵׁיהֶ֗ם] serao [לִבְהֶמְתָּם֙] [וְלִרְכֻשָׁ֔ם] [וּלְכֹ֖ל] [חַיָּתָֽם]');
INSERT INTO verses VALUES (4851, 4, 35, 4, '[וּמִגְרְשֵׁי֙] [הֶֽעָרִ֔ים] que [תִּתְּנ֖וּ] [לַלְוִיִּ֑ם] [מִקִּ֤יר] [הָעִיר֙] [וָח֔וּצָה] mil [אַמָּ֖ה] ao-redor');
INSERT INTO verses VALUES (4852, 4, 35, 5, '[וּמַדֹּתֶ֞ם] de-fora [לָעִ֗יר] a canto [בָּֽאַמָּ֟ה] [וְאֶת־פְּאַת־נֶגֶב֩] [אַלְפַּ֨יִם] e-[OBJ] canto [׀] [אַלְפַּ֣יִם] [בָּֽאַמָּ֗ה] e-[OBJ] canto [צָפ֛וֹן] [אַלְפַּ֥יִם] [בָּאַמָּ֖ה] e-[OBJ] [בַּתָּ֑וֶךְ] [זֶ֚ה] será a-eles [מִגְרְשֵׁ֖י] [הֶעָרִֽים]');
INSERT INTO verses VALUES (4853, 4, 35, 6, 'e-[OBJ] [הֶֽעָרִ֗ים] que [תִּתְּנוּ֙] [לַלְוִיִּ֔ם] a [שֵׁשׁ־עָרֵ֣י] cidades-de [אֲשֶׁ֣ר] que [לָנֻ֥ס] [שָׁ֖מָּה] [הָרֹצֵ֑חַ] [וַעֲלֵיהֶ֣ם] [תִּתְּנ֔וּ] [אַרְבָּעִ֥ים] [וּשְׁתַּ֖יִם] [עִֽיר] cidade');
INSERT INTO verses VALUES (4854, 4, 35, 7, 'todo [אֲשֶׁ֤ר] que [לַלְוִיִּ֔ם] [אַרְבָּעִ֥ים] [וּשְׁמֹנֶ֖ה] [עִ֑יר] cidade a-elas e-[OBJ] [sem-traducao]');
INSERT INTO verses VALUES (4855, 4, 35, 8, '[וְהֶֽעָרִ֗ים] que [תִּתְּנוּ֙] [מֵאֲחֻזַּ֣ת] filhos-de Israel [הָרַב֙] [תַּרְבּ֔וּ] [וּמֵאֵ֥ת] [הַמְעַ֖ט] [תַּמְעִ֑יטוּ] [אִ֗ישׁ] homem [נַחֲלָתוֹ֙] [אֲשֶׁ֣ר] que [יִתֵּ֥ן] [מֵעָרָ֖יו] [לַלְוִיִּֽם׃]');
INSERT INTO verses VALUES (4856, 4, 35, 9, 'e-falou yhwh a Moisés');
INSERT INTO verses VALUES (4857, 4, 35, 10, 'palavra a filhos-de Israel [אֲלֵהֶ֑ם] que porque vós [אֶת־הַיַּרְדֵּ֖ן] a [כְּנָֽעַן]');
INSERT INTO verses VALUES (4858, 4, 35, 11, '[וְהִקְרִיתֶ֤ם] a-vós [עָרִ֔ים] cidades-de [מִקְלָ֖ט] [תִּהְיֶ֣ינָה] a-vós [וְנָ֥ס] [שָׁ֙מָּה֙] [רֹצֵ֔חַ] [מַכֵּה־נֶ֖פֶשׁ] alma');
INSERT INTO verses VALUES (4859, 4, 35, 12, 'e-sejam a-vós [הֶעָרִ֛ים] [לְמִקְלָ֖ט] [מִגֹּאֵ֑ל] e-não morrera [הָרֹצֵ֔חַ] até [לִפְנֵ֥י] diante-de [לַמִּשְׁפָּֽט] para-o-julgamento');
INSERT INTO verses VALUES (4860, 4, 35, 13, '[וְהֶעָרִ֖ים] que [תִּתֵּ֑נוּ] [שֵׁשׁ־עָרֵ֥י] cidades-de [תִּהְיֶ֥ינָה] a-vós');
INSERT INTO verses VALUES (4861, 4, 35, 14, '[OBJ] três [שְׁלֹ֣שׁ] [הֶעָרִ֗ים] [תִּתְּנוּ֙] [מֵעֵ֣בֶר] e-[OBJ] e-[OBJ] [שְׁלֹ֣שׁ] [הֶֽעָרִ֔ים] na-terra assim cidades-de [עָרֵ֥י] [מִקְלָ֖ט]');
INSERT INTO verses VALUES (4862, 4, 35, 15, 'aos-filhos-de Israel [וְלַגֵּ֤ר] [וְלַתּוֹשָׁב֙] [בְּתוֹכָ֔ם] [תִּהְיֶ֛ינָה] [שֵׁשׁ־הֶעָרִ֥ים] [הָאֵ֖לֶּה] estes [לָנ֣וּס] [שָׁ֔מָּה] [כָּל־מַכֵּה־נֶ֖פֶשׁ] todo alma');
INSERT INTO verses VALUES (4863, 4, 35, 16, 'e-se [בַרְזֶ֧ל] [׀] [הִכָּ֛הוּ] E-morreu [רֹצֵ֣חַֽ] ele morrendo [יוּמַ֖ת] [הָרֹצֵֽחַ]');
INSERT INTO verses VALUES (4864, 4, 35, 17, '[וְאִ֡ם] [בְּאֶ֣בֶן] mão que [בָּ֥הּ] [הִכָּ֛הוּ] [וַיָּמֹ֖ת] E-morreu ele morrendo [יוּמַ֖ת] [הָרֹצֵֽחַ]');
INSERT INTO verses VALUES (4865, 4, 35, 18, '[א֡וֹ] [בִּכְלִ֣י] [עֵֽץ־יָד֩] mão que [הִכָּ֛הוּ] nele [רֹצֵ֣חַֽ] ele morrendo ele [הָרֹצֵֽחַ] será-morto [sem-traducao]');
INSERT INTO verses VALUES (4866, 4, 35, 19, '[גֹּאֵ֣ל] [הַדָּ֔ם] ele [יָמִ֖ית] a [בְּפִגְעוֹ־ב֖וֹ] ele [יְמִיתֶֽנּוּ]');
INSERT INTO verses VALUES (4867, 4, 35, 20, 'e-se [יֶהְדָּפֶ֑נּוּ] [אֽוֹ־הִשְׁלִ֥יךְ] ou [בִּצְדִיָּ֖ה] [וַיָּמֹֽת] [sem-traducao] E-morreu');
INSERT INTO verses VALUES (4868, 4, 35, 21, 'ou [בְאֵיבָ֞ה] [הִכָּ֤הוּ] [בְיָדוֹ֙] E-morreu [מֽוֹת־יוּמַ֥ת] [הַמַּכֶּ֖ה] [רֹצֵ֣חַֽ] ele ele [הַדָּ֗ם] [יָמִ֛ית] [אֶת־הָרֹצֵ֖חַ] a');
INSERT INTO verses VALUES (4869, 4, 35, 22, 'e-se [בְּלֹא־אֵיבָ֖ה] [הֲדָפ֑וֹ] [אוֹ־הִשְׁלִ֥יךְ] [עָלָ֛יו] ou [בְּלֹ֥א] [צְדִיָּֽה] todo');
INSERT INTO verses VALUES (4870, 4, 35, 23, 'ou em-todo [אֲשֶׁר־יָמ֥וּת] que [בְּלֹ֣א] [רְא֔וֹת] E-fez-cair [עָלָ֖יו] [וַיָּמֹ֑ת] sobre-ele E-morreu a-ele não [מְבַקֵּ֖שׁ] a-ele e-não');
INSERT INTO verses VALUES (4871, 4, 35, 24, '[וְשָֽׁפְטוּ֙] [הָֽעֵדָ֔ה] entre [הַמַּכֶּ֔ה] e-entre [גֹּאֵ֣ל] [הַדָּ֑ם] sobre [הַמִּשְׁפָּטִ֖ים] [הָאֵֽלֶּה]');
INSERT INTO verses VALUES (4872, 4, 35, 25, '[וְהִצִּ֨ילוּ] [הָעֵדָ֜ה] a [מִיַּד֮] [גֹּאֵ֣ל] [הַדָּם֒] [וְהֵשִׁ֤יבוּ] ele ele [אֶל־עִ֥יר] a cidade [שָׁ֑מָּה] que [בָּ֗הּ] [עַד־מוֹת֙] [הַכֹּהֵ֣ן] o-grande até ele [בְּשֶׁ֥מֶן] [הַקֹּֽדֶשׁ] que');
INSERT INTO verses VALUES (4873, 4, 35, 26, 'e-se [יֵצֵ֖א] [הָרֹצֵ֑חַ] [אֶת־גְּבוּל֙] a [מִקְלָט֔וֹ] cidade [יָנ֖וּס] que');
INSERT INTO verses VALUES (4874, 4, 35, 27, '[וּמָצָ֤א] ele [גֹּאֵ֣ל] [הַדָּ֔ם] [מִח֕וּץ] [לִגְב֖וּל] cidade [מִקְלָט֑וֹ] [וְרָצַ֞ח] [גֹּאֵ֤ל] [הַדָּם֙] a [אֵ֥ין] a-ele a-ele');
INSERT INTO verses VALUES (4875, 4, 35, 28, 'que [בְעִ֤יר] [מִקְלָטוֹ֙] habitou até [הַכֹּהֵ֣ן] o-grande [וְאַחֲרֵ֥י] morrendo [הַכֹּהֵ֣ן] o-grande [יָשׁוּב֙] retornara [אֶל־אֶ֖רֶץ] a terra [sem-traducao]');
INSERT INTO verses VALUES (4876, 4, 35, 29, 'e-sejam Estas a-vós [לְחֻקַּ֥ת] juízo [לְדֹרֹתֵיכֶ֑ם] em-todo [מוֹשְׁבֹתֵיכֶֽם]');
INSERT INTO verses VALUES (4877, 4, 35, 30, 'todo [לְפִ֣י] alma [יִרְצַ֖ח] [אֶת־הָרֹצֵ֑חַ] [וְעֵ֣ד] um [לֹא־יַעֲנֶ֥ה] [בְנֶ֖פֶשׁ] um não');
INSERT INTO verses VALUES (4878, 4, 35, 31, 'e-não [כֹ֙פֶר֙] [לְנֶ֣פֶשׁ] [רֹצֵ֔חַ] [אֲשֶׁר־ה֥וּא] que ele [כִּי־מ֖וֹת] [יוּמָֽת] porque');
INSERT INTO verses VALUES (4879, 4, 35, 32, 'e-não [כֹ֔פֶר] [לָנ֖וּס] [אֶל־עִ֣יר] a cidade [לָשֶׁ֣בֶת] [בָּאָ֔רֶץ] [עַד־מ֖וֹת] [הַכֹּהֵֽן] até');
INSERT INTO verses VALUES (4880, 4, 35, 33, 'e-não [אֶת־הָאָ֗רֶץ] a a-terra que que [הַדָּ֔ם] ele [יַחֲנִ֖יף] ele [וְלָאָ֣רֶץ] a a-terra [אֲשֶׁ֣ר] não [כִּי־אִ֖ם] [בְּדַ֥ם] que porque mãe');
INSERT INTO verses VALUES (4881, 4, 35, 34, 'e-não [תְטַמֵּ֣א] a a-terra que vós [בָּ֔הּ] [אֲשֶׁ֥ר] que eu [בְּתוֹכָ֑הּ] que porque yhwh yhwh no-meio-de [בְּנֵ֥י] filhos-de Israel');
INSERT INTO chapters VALUES (153, 4, 36, 13);
INSERT INTO verses VALUES (4882, 4, 36, 1, '[וַֽיִ[t]קְרְב֞וּ] [רָאשֵׁ֣י] [הָֽאָב֗וֹת] filhos-de [בְּנֵֽי־גִלְעָד֙] filho-de [בֶּן־מְנַשֶּׁ֔ה] filho-de [בְּנֵ֣י] [יוֹסֵ֑ף] filhos-de José [מֹשֶׁה֙] diante-de Moisés [רָאשֵׁ֥י] [אָב֖וֹת] [לִבְנֵ֥י] [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (4883, 4, 36, 2, '[וַיֹּאמְר֗וּ] a Adonai yhwh yhwh [אֶת־הָאָ֧רֶץ] a a-terra [לִבְנֵ֣י] [יִשְׂרָאֵ֑ל] aos-filhos-de Israel [בַֽיהוָ֔ה] [לָתֵ֗ת] [אֶֽת־נַחֲלַ֛ת] [צְלָפְחָ֥ד] a [לִבְנֹתָֽיו]');
INSERT INTO verses VALUES (4884, 4, 36, 3, 'e-sejam [לְאֶחָ֞ד] [מִבְּנֵ֨י] [שִׁבְטֵ֥י] filhos-de Israel [וְנִגְרְעָ֤ה] [נַחֲלָתָן֙] [מִנַּחֲלַ֣ת] [אֲבֹתֵ֔ינוּ] nossos-pais sobre sobre [הַמַּטֶּ֔ה] [אֲשֶׁ֥ר] que a-eles a-eles [נַחֲלָתֵ֖נוּ] [יִגָּרֵֽעַ] [sem-traducao]');
INSERT INTO verses VALUES (4885, 4, 36, 4, 'e-se [הַיֹּבֵל֮] [לִבְנֵ֣י] aos-filhos-de Israel [נַחֲלָתָ֔ן] sobre sobre [הַמַּטֶּ֔ה] [אֲשֶׁ֥ר] que a-eles a-eles [מַטֵּ֣ה] [אֲבֹתֵ֔ינוּ] nossos-pais [נַחֲלָתָֽן] [sem-traducao]');
INSERT INTO verses VALUES (4886, 4, 36, 5, 'E-ordenou Moisés a filhos-de Israel yhwh dizendo yhwh dizendo assim [דֹּבְרִֽים]');
INSERT INTO verses VALUES (4887, 4, 36, 6, 'este [הַדָּבָ֞ר] que yhwh yhwh [צְלָפְחָד֙] dizendo dizendo [בְּעֵינֵיהֶ֖ם] [תִּהְיֶ֣ינָה] [לְנָשִׁ֑ים] [אַ֗ךְ] somente [מַטֵּ֥ה] [אֲבִיהֶ֖ם] pai-deles [לְנָשִֽׁים] [sem-traducao]');
INSERT INTO verses VALUES (4888, 4, 36, 7, 'e-não [נַחֲלָה֙] [לִבְנֵ֣י] aos-filhos-de Israel [אֶל־מַטֶּ֑ה] que [אִ֗ישׁ] porque homem [אֲבֹתָ֔יו] [יִדְבְּק֖וּ] seus-pais [יִשְׂרָאֵֽל] filhos-de Israel');
INSERT INTO verses VALUES (4889, 4, 36, 8, 'e-todo [יֹרֶ֣שֶׁת] [נַחֲלָ֗ה] [מִמַּטּוֹת֮] [בְּנֵ֣י] filhos-de Israel [מִמִּשְׁפַּ֛חַת] [מַטֵּ֥ה] [אָבִ֖יהָ] [תִּהְיֶ֣ה] será [לְמַ֗עַן] [יִֽירְשׁוּ֙] [בְּנֵ֣י] filhos-de Israel homem [אֲבֹתָֽיו]');
INSERT INTO verses VALUES (4890, 4, 36, 9, 'e-não [נַחֲלָ֛ה] [מִמַּטֶּ֖ה] [לְמַטֶּ֣ה] [אַחֵ֑ר] outro porque homem [מַטּ֖וֹת] [בְּנֵ֥י] [יִשְׂרָאֵֽל] filhos-de Israel');
INSERT INTO verses VALUES (4891, 4, 36, 10, 'como ordenou yhwh a Moisés assim fizeram [צְלָפְחָֽד]');
INSERT INTO verses VALUES (4892, 4, 36, 11, '[וַתִּהְיֶ֜ינָה] [מַחְלָ֣ה] [תִרְצָ֗ה] [וְחָגְלָ֧ה] [וּמִלְכָּ֛ה] [וְנֹעָ֖ה] filhas-de [צְלָפְחָ֑ד] para-os-filhos-de [דֹדֵיהֶ֖ן] [לְנָשִֽׁים]');
INSERT INTO verses VALUES (4893, 4, 36, 12, '[מִֽמִּשְׁפְּחֹ֛ת] filhos-de [בֶן־יוֹסֵ֖ף] filho-de [לְנָשִׁ֑ים] eram [נַחֲלָתָ֔ן] [עַל־מַטֵּ֖ה] [מִשְׁפַּ֥חַת] sobre');
INSERT INTO verses VALUES (4894, 4, 36, 13, 'Estas [הַמִּצְוֺ֞ת] [וְהַמִּשְׁפָּטִ֗ים] que [צִוָּ֧ה] yhwh pela-mão-de Moisés a filhos-de Israel sobre Moabe sobre');
INSERT INTO books VALUES (5, 'DEU', 'Deuteronômio', 'AT', 34);
INSERT INTO chapters VALUES (154, 5, 1, 46);
INSERT INTO verses VALUES (4895, 5, 1, 1, 'Estas as palavras que palavra Moisés a todo Israel em-além-de o Jordão em-o deserto em-a planície diante-de junco entre Parã e-entre ouro e-Labã e-Hazerote e-Di ouro');
INSERT INTO verses VALUES (4896, 5, 1, 2, 'um dez dia de-Horebe o-caminho-de monte-de até até Cades Barneia');
INSERT INTO verses VALUES (4897, 5, 1, 3, 'e-houve em-quarenta ano em-onze-de dez novo no-primeiro para-o-mês palavra Moisés a filhos-de Israel conforme-tudo yhwh ele yhwh a-ele a-eles');
INSERT INTO verses VALUES (4898, 5, 1, 4, 'depois-de o ferir-ele את Siom rei o amorreu que habitante em-Hesbom e-a Ogue rei o basanita que habitante em-Astarote em-Edrei');
INSERT INTO verses VALUES (4899, 5, 1, 5, 'em-além-de o Jordão em-terra-de Moabe quis Moisés explicar a a instrução dizendo para-dizer');
INSERT INTO verses VALUES (4900, 5, 1, 6, 'yhwh Elohim nosso palavra a-nós em-Horebe dizendo muito para-vós habitar em-o monte a-esta');
INSERT INTO verses VALUES (4901, 5, 1, 7, 'virai-vos e-parti para-vós a-vós monte-de o amorreu e-a todo vizinhos-seus em-a planície em-o monte e-em-a baixada e-em-o sul o-mar terra terra o-cananeu e-o Líbano o-grande o-rio a-grande rio-de Eufrates');
INSERT INTO verses VALUES (4902, 5, 1, 8, 'viu dei diante-de-vós a a-terra entrai e-possuí a a-terra yhwh jurou yhwh para-pais-de-vós para-Abraão para-Isaque a-eles para-dar a-eles e-para-descendência-deles depois-deles');
INSERT INTO verses VALUES (4903, 5, 1, 9, 'e-disse a-vós em-o tempo aquela dizendo não posso sozinho carregar a-vós');
INSERT INTO verses VALUES (4904, 5, 1, 10, 'yhwh Elohim de-vós multiplicou a-vós e-eis-vós o-dia como-estrelas-de os-céus para-multidão');
INSERT INTO verses VALUES (4905, 5, 1, 11, 'yhwh Elohim-de pais-de-vós acrescente sobre-vós como-vós mil vezes E-abençoou a-vós conforme palavra a-vós');
INSERT INTO verses VALUES (4906, 5, 1, 12, 'como carregarei sozinho carga-de-vós e-fardo-de-vós e-contenda-de-vós');
INSERT INTO verses VALUES (4907, 5, 1, 13, 'dai a-vós homens sábios e-entendidos e-conhecidos para-tribos-de-vós e-os-colocarei em-cabeças-de-vós');
INSERT INTO verses VALUES (4908, 5, 1, 14, 'e-respondestes a-mim e-dissestes bom a-palavra que falaste para-fazer');
INSERT INTO verses VALUES (4909, 5, 1, 15, 'e-tomei a cabeças-de tribos-vossas homens sábios e-conhecidos eles a-eles cabeças sobre-vós príncipes-de milhares e-príncipes-de centenas e-príncipes-de cinquentas e-príncipes-de dezenas e-oficiais para-tribos-vossas');
INSERT INTO verses VALUES (4910, 5, 1, 16, 'e-ordenei a juízes-vossos aquela dizendo para-dizer ouviu entre irmãos-vossos e-julgareis justiça e-entre homem e-entre irmão-seu e-entre estrangeiro-seu');
INSERT INTO verses VALUES (4911, 5, 1, 17, 'não reconhecereis face em-o-julgamento como-o-pequeno como-o-grande não não temereis que homem porque ele para-Elohim ele e-a-palavra que será-difícil de-vós trareis para-mim e-ouvirei-o');
INSERT INTO verses VALUES (4912, 5, 1, 18, 'e-ordenei vós em-o-tempo aquela a todo as-palavras que vós-fareis');
INSERT INTO verses VALUES (4913, 5, 1, 19, 'e-partimos de-Horebe e-caminhamos com todo o-deserto o-grande e-o-terrível o-aquele que o-caminho-de caminho monte-de o-amorreu como-que yhwh yhwh Elohim-nosso nós até até Cades Barneia');
INSERT INTO verses VALUES (4914, 5, 1, 20, 'e-disse para-vós viestes até monte-de o-amorreu que yhwh Elohim-nosso deu para-nós');
INSERT INTO verses VALUES (4915, 5, 1, 21, 'viu dar yhwh Elohim-teu diante-de-ti a folhas-de sobe possui como-que yhwh yhwh Elohim-de para-ti para-ti a temas e-a desanimes');
INSERT INTO verses VALUES (4916, 5, 1, 22, 'e-aproximastes-vos para-mim todos-vós e-dissestes enviaremos homens diante-de-nós e-esquadrinharão para-nós a a-terra e-retornarão nós palavra a o-caminho que subiremos em-ela e-את as-cidades que entraremos para-elas');
INSERT INTO verses VALUES (4917, 5, 1, 23, 'e-foi-bom em-olhos-meus a-palavra e-tomei de-vós dois dez homens homem um para-a-tribo');
INSERT INTO verses VALUES (4918, 5, 1, 24, 'e-voltaram-se e-subiram a-montanha e-vieram até vale-de Escol e-espiaram a-ela');
INSERT INTO verses VALUES (4919, 5, 1, 25, 'e-tomaram em-mão-de-eles do-fruto-de a-terra e-fizeram-descer a-nós e-retornaram a-nós palavra e-disseram boa a-terra que yhwh Elohim-nosso deu a-nós');
INSERT INTO verses VALUES (4920, 5, 1, 26, 'e-não não-quisestes a-subir e-rebelastes a yhwh yhwh Elohim-vosso');
INSERT INTO verses VALUES (4921, 5, 1, 27, 'e-murmurastes em-tendas-vossas e-dissestes em-ódio-de yhwh a-nós fez-sair-nos de-terra-de Egito a-dar a-nós na-mão-de o-amorreu a-destruir-nos');
INSERT INTO verses VALUES (4922, 5, 1, 28, 'aonde nós subindo irmãos-nossos derreteram a coração-nosso dizendo povo grande e-alto nós cidades grandes e-fortificadas nos-céus e-também filhos-de gigantes vimos nome');
INSERT INTO verses VALUES (4923, 5, 1, 29, 'e-disse a-vós não não-tremais e-não não-temais de-eles');
INSERT INTO verses VALUES (4924, 5, 1, 30, 'yhwh Elohim-vosso o-que-vai diante-de-vós ele lutará a-vós conforme-tudo que fez com-vós em-Egito diante-de-olhos-vossos');
INSERT INTO verses VALUES (4925, 5, 1, 31, 'e-no-deserto que viste que carregou-te yhwh Elohim-teu como-que carrega homem a filho-seu em-todo o-caminho que andastes até ao-virdes-vós até o-lugar a-esta');
INSERT INTO verses VALUES (4926, 5, 1, 32, 'e-na-coisa esta não-vós crendo em-יהוה Elohim-vosso');
INSERT INTO verses VALUES (4927, 5, 1, 33, 'o-que-vai diante-de-vós no-caminho a-explorar a-vós lugar a-acampardes-vós no-fogo noite a-mostrar-vos no-caminho que andais nela e-na-nuvem de-dia');
INSERT INTO verses VALUES (4928, 5, 1, 34, 'E-ouviu yhwh a voz-de palavras-vossas e-irou-se dizendo para-dizer');
INSERT INTO verses VALUES (4929, 5, 1, 35, 'se verá homem nos-homens os-estes a-geração a-má esta a-terra a-terra a-boa que jurei a-dar a-pais-vossos');
INSERT INTO verses VALUES (4930, 5, 1, 36, 'exceto Calebe filho-de ele ele vê-la-á e-a-ele darei a a-terra que pisou nela e para filhos-seus yhwh que enchei atrás-de yhwh');
INSERT INTO verses VALUES (4931, 5, 1, 37, 'também em-mim yhwh yhwh dizendo para-dizer também tu não entrará nome');
INSERT INTO verses VALUES (4932, 5, 1, 38, 'Josué Nun o-que-está-em-pé diante-de-ti ele ele para-lá a-ele ele porque ele ele-fará-herdar-a a Israel');
INSERT INTO verses VALUES (4933, 5, 1, 39, 'e-crianças-vossas que dissestes para-saque será e-filhos-vossos que não o-dia bom bom e-mal eles entrarão para-lá e-para-eles darei-a e-eles herdarão-a');
INSERT INTO verses VALUES (4934, 5, 1, 40, 'e-vós voltai-vos a-vós e-parti o-deserto-para o-caminho-de mar-de juncos');
INSERT INTO verses VALUES (4935, 5, 1, 41, 'e-respondestes e-dissestes a-mim pecamos para-יהוה nós subiremos e-lutaremos conforme-tudo que ordenou-nos yhwh Elohim-nosso e-cingistes homem a utensílios-de guerra-sua e-fostes-ligeiros para-subir o-monte-para');
INSERT INTO verses VALUES (4936, 5, 1, 42, 'E-disse yhwh a-mim disse a-eles não subais e-não que porque não-estou-eu em-meio-vosso e-não sereis-feridos diante-de inimigos-vossos');
INSERT INTO verses VALUES (4937, 5, 1, 43, 'e-falei a-vós e-não ouvistes e-rebelastes a yhwh yhwh e-agistes-presunçosamente e-subistes o-monte-para');
INSERT INTO verses VALUES (4938, 5, 1, 44, 'e-saiu o-amorreu o-habitante em-o-monte o-aquele para-encontro-vosso e-perseguiram a-vós como-que fazem as-abelhas e-eles-atingiram a-vós em-Seir até Hormá');
INSERT INTO verses VALUES (4939, 5, 1, 45, 'e-voltastes e-chorastes diante-de yhwh e-não yhwh yhwh com-voz-vossa e-não deu-ouvidos a-vós');
INSERT INTO verses VALUES (4940, 5, 1, 46, 'e-habitastes em-Cades dias muitos como-os-dias que habitastes');
INSERT INTO chapters VALUES (155, 5, 2, 37);
INSERT INTO verses VALUES (4941, 5, 2, 1, 'e-voltamo-nos e-partimos o-deserto-para o-caminho-de mar-de Suf como yhwh yhwh a-mim e-rodeamos a monte-de Seir dias muitos');
INSERT INTO verses VALUES (4942, 5, 2, 2, 'E-disse yhwh a-mim dizendo');
INSERT INTO verses VALUES (4943, 5, 2, 3, 'muito para-vós rodear a o-monte a-vós voltai-vos para-vocês norte-para');
INSERT INTO verses VALUES (4944, 5, 2, 4, 'e-a o-povo dizendo dizendo vós passando em-território-de irmãos-vossos filhos-de Esaú os-habitantes em-Seir e-temerão muito e-guardar-vos-eis muito');
INSERT INTO verses VALUES (4945, 5, 2, 5, 'a provocareis que porque a-vós darei até de-terra-deles até pisada-de planta-de dei porque herança para-Esaú dei a monte-de Seir');
INSERT INTO verses VALUES (4946, 5, 2, 6, 'alimento comprareis de-com-eles com-a-prata e-comereis e-também águas comprareis de-com-eles com-a-prata e-bebereis');
INSERT INTO verses VALUES (4947, 5, 2, 7, 'que yhwh Elohim-teu abençoou-te em-todo obra-de mão-tua saber andar-teu a o-grande a-grande esta este quarenta ano yhwh Elohim-teu contigo não faltaste palavra');
INSERT INTO verses VALUES (4948, 5, 2, 8, 'e-passamos de-com irmãos-nossos filhos-de Esaú os-habitam em-Seir de-caminho-de a-Arabá de-Elate e-de-Eziom Geber e-voltamos e-passamos o-caminho-de deserto-de Moabe');
INSERT INTO verses VALUES (4949, 5, 2, 9, 'E-disse yhwh a-mim a angusties a Moabe e-a que com-eles a-ti porque não que para-ti dei herança porque para-filhos-de Ló dei a Ar herança');
INSERT INTO verses VALUES (4950, 5, 2, 10, 'os-Emins antes habitaram nela povo grande e-numeroso e-alto como-os-Anaquins');
INSERT INTO verses VALUES (4951, 5, 2, 11, 'Refains são-considerados também eles como-os-Anaquins e-os-moabitas a-eles a-eles Emins');
INSERT INTO verses VALUES (4952, 5, 2, 12, 'e-em-Seir habitaram os-Horeus antes e-filhos-de Esaú herdou-os e-destruiu-os de-diante-deles e-habitaram em-lugar-deles como-que fez Israel para-terra-de herança-dele que yhwh a-eles para-eles');
INSERT INTO verses VALUES (4953, 5, 2, 13, 'agora levantai-vos e-passai a-vós a ribeiro-de Zerede e-passamos a ribeiro-de Zerede');
INSERT INTO verses VALUES (4954, 5, 2, 14, 'e-os-dias que andamos de-Cades Barneia até que passamos a ribeiro-de Zerede trinta e-oito ano até acabou todo a-geração homens-de a-guerra yhwh a-eles como jurou yhwh para-eles');
INSERT INTO verses VALUES (4955, 5, 2, 15, 'e-também mão-de era foi contra-eles para-destruí-los de-meio-de até até foram-acabados');
INSERT INTO verses VALUES (4956, 5, 2, 16, 'e-houve como-que foram-acabados todo homens-de a-guerra para-morrer de-meio-de o-povo');
INSERT INTO verses VALUES (4957, 5, 2, 17, 'e-falou yhwh para-mim dizendo');
INSERT INTO verses VALUES (4958, 5, 2, 18, 'tu passando o-dia a fronteira-de Moabe a Ar');
INSERT INTO verses VALUES (4959, 5, 2, 19, 'e-te-aproximarás em-frente-a filhos-de Amom a os-sities e-a que neles porque não a-ti de-terra-de que Amom para-ti herança porque para-filhos-de Ló a-dei herança');
INSERT INTO verses VALUES (4960, 5, 2, 20, 'terra-de refains é-considerada também ela refains habitaram nela a-eles e-os-amonitas chamam a-eles zamzumins');
INSERT INTO verses VALUES (4961, 5, 2, 21, 'povo grande e-numeroso e-alto como-os-Anaquins e-os-destruiu yhwh de-diante-deles e-os-herdaram e-habitaram em-lugar-deles');
INSERT INTO verses VALUES (4962, 5, 2, 22, 'como-que fez a-filhos-de Esaú os-habitantes em-Seir que destruiu a os-horeus de-diante-deles e-os-herdou e-habitaram até o-dia o-dia a-esta');
INSERT INTO verses VALUES (4963, 5, 2, 23, 'e-os-aveus os-que-habitam em-aldeias até Gaza caftoreus os-que-saem de-Caftor os-destruíram e-habitaram em-lugar-deles');
INSERT INTO verses VALUES (4964, 5, 2, 24, 'levantai-vos partí e-passai a ribeiro-de Arnom dei dei em-mão-tua a Siom rei-de Hesbom o-amorreu e-a terra-dele começa possuir e-provoca nele guerra');
INSERT INTO verses VALUES (4965, 5, 2, 25, 'o-dia o-este começarei dar temor-teu e-medo-teu sobre face-de debaixo sob todo os-céus que eles-ouvirão fama-tua e-tremerão e-se-angustiarão de-diante-tua');
INSERT INTO verses VALUES (4966, 5, 2, 26, 'e-enviei mensageiros de-deserto-de Quedemote a Siom rei Hesbom palavras-de dizendo para-dizer');
INSERT INTO verses VALUES (4967, 5, 2, 27, 'passarei em-terra-tua no-caminho no-caminho irei não me-desviarei direita e-esquerda');
INSERT INTO verses VALUES (4968, 5, 2, 28, 'comida em-o-dinheiro tu-venderás-me e-eu-comerei e-águas em-o-dinheiro tu-darás para-mim e-eu-beberei somente eu-passarei em-os-meus-pés');
INSERT INTO verses VALUES (4969, 5, 2, 29, 'como-que fizeram para-mim filhos-de Esaú os-habitam em-Seir e-os-moabitas os-habitantes até até que eu-atravessarei a o-Jordão a a-terra que yhwh Elohim deu para-nós');
INSERT INTO verses VALUES (4970, 5, 2, 30, 'e-não quis Siom rei Hesbom fazer-nos-passar nele porque yhwh yhwh Elohim a espírito-dele e-endureceu a coração-dele para-fim-de dar-lo em-mão-tua como-o-dia a-esta');
INSERT INTO verses VALUES (4971, 5, 2, 31, 'E-disse yhwh a-mim viu comecei dar diante-de-ti a Siom e-a terra-dele começa possuir para-possuir a terra-dele');
INSERT INTO verses VALUES (4972, 5, 2, 32, 'e-saiu Siom para-encontro-nosso ele e-todo povo-dele para-a-guerra Jaaza');
INSERT INTO verses VALUES (4973, 5, 2, 33, 'e-deu-o yhwh Elohim diante-de-nós e-ferimos ele e-a e-a todo povo-dele');
INSERT INTO verses VALUES (4974, 5, 2, 34, 'e-capturamos a todo aquela em-o-tempo aquele e-destruímos a todo não homens e-as-mulheres e-as-crianças não deixamos sobrevivente');
INSERT INTO verses VALUES (4975, 5, 2, 35, 'somente os-animais saqueamos para-nós e-despojo-de as-cidades que capturamos');
INSERT INTO verses VALUES (4976, 5, 2, 36, 'de-Aroer que sobre borda-de ribeiro-de Arnom e-a-cidade que não era Gileade não foi nós que dar yhwh a o-tudo deu yhwh Elohim diante-de-nós');
INSERT INTO verses VALUES (4977, 5, 2, 37, 'somente a terra não Amom não te-aproximaste todo mão ribeiro-de e-tudo e-cidades-de yhwh e-todo que ordenou yhwh Elohim-nosso');
INSERT INTO chapters VALUES (156, 5, 3, 29);
INSERT INTO verses VALUES (4978, 5, 3, 1, 'e-viramos e-subimos o-caminho-de Basã e-saiu Ogue rei-de Basã ele ele e-todo povo-dele para-a-guerra Edrei');
INSERT INTO verses VALUES (4979, 5, 3, 2, 'E-disse yhwh a-mim a ele que porque dei ele a-ele e-a todo para-ele e-a terra-dele e-farás a-ele como-que fizeste a-Siom rei o-amorreu que habitante em-Hesbom');
INSERT INTO verses VALUES (4980, 5, 3, 3, 'E-colocou yhwh Elohim-nosso em-mão-nossa também a Ogue rei-de o-Basã e-a todo povo-seu e-golpeamos-o até para-não deixar-restar para-ele sobrevivente');
INSERT INTO verses VALUES (4981, 5, 3, 4, 'e-capturamos a todo aquela não era não era cidade que não tomamos de-com-eles sessenta cidade todo região Argobe reino-de Ogue em-o-Basã');
INSERT INTO verses VALUES (4982, 5, 3, 5, 'todo estas cidades fortificadas muralha alta portas e-ferrolho além-de de-cidades-de o-campo muito muito');
INSERT INTO verses VALUES (4983, 5, 3, 6, 'e-devotamos-à-destruição a-eles como-que fizemos a-Siom rei Hesbom devotando-à-destruição todo cidade varões as-mulheres e-as-crianças');
INSERT INTO verses VALUES (4984, 5, 3, 7, 'e-todo o-gado e-despojo-de as-cidades saqueamos para-nós');
INSERT INTO verses VALUES (4985, 5, 3, 8, 'e-tomamos em-o-tempo aquela a a-terra de-mão-de segundo reis-de o-amorreu que em-além-de o Jordão de-ribeiro-de Arnom até monte-de Hermom');
INSERT INTO verses VALUES (4986, 5, 3, 9, 'sidônios chamam a-Hermom Siriom e-o-amorreu chamam- para-ele Senir');
INSERT INTO verses VALUES (4987, 5, 3, 10, 'todas cidades-de a-planície e-todo o-Gileade e-todo o basanita até Salca e-Edrei cidades-de reino-de Ogue em-o-Basã');
INSERT INTO verses VALUES (4988, 5, 3, 11, 'que somente Ogue rei o-Basã restou de-restante-de eis eis leito-seu leito-de ferro ela ele em-Rabá filhos-de Amom nove côvados comprimento-seu e-quatro côvados largura-sua em-côvado-de homem');
INSERT INTO verses VALUES (4989, 5, 3, 12, 'e-a a-terra esta possuímos aquela aquele de-Aroer que sobre ribeiro-de Arnom dei monte-de o-Gileade e-cidades-suas dei para-o-rubenita e-para-o-gadita');
INSERT INTO verses VALUES (4990, 5, 3, 13, 'e-resto-de o-Gileade e-todo o-Basã reino-de dei dei para-metade-de tribo-de o-Manassés todo região-de o-Argobe para-todo será-chamada terra será-chamado terra refains');
INSERT INTO verses VALUES (4991, 5, 3, 14, 'Jair filho-de tomou tomou a todo região-de Argobe E-chamou eles o-gesuritas e-o-maacatitas E-chamou elas até o-dia a o-Basã aldeias-de Jair até o-dia a-esta');
INSERT INTO verses VALUES (4992, 5, 3, 15, 'e-para-Maquir dei a o-Gileade');
INSERT INTO verses VALUES (4993, 5, 3, 16, 'e-para-o-rubenita e-para-o-gadita dei de o-Gileade e-até ribeiro-de Arnon dentro-de o-nachal e-guvul e-ate Yabok o-nachal guvul filhos-de Amom');
INSERT INTO verses VALUES (4994, 5, 3, 17, 'e-a-aravah e-o-yarden e-gbul de-mkineret e-ad mar ha-aravah mar ha-melah debaixo ashdot ha-pisga mizrachah');
INSERT INTO verses VALUES (4995, 5, 3, 18, 'e-eu-mandei vos em-o tempo aquela dizendo yhwh אֱלֹהִים-vo/ós dar a-vós a a-terra esta para-a-posse-de-la pioneiros voc/ós-passareis diante-de irmãos-vos filhos-de Israel todo filhos-de força');
INSERT INTO verses VALUES (4996, 5, 3, 19, 'somente mulheres-de-vocês e-os-filhos-vos e-o-pecuário-vos eu-sei porque pecuário a-vós a-vós se-já-sentarão em-o-vosso-cidade dei a-vós para-vocês');
INSERT INTO verses VALUES (4997, 5, 3, 20, 'até que yhwh יְהוָה para-irmãos-de-vocês como-vocês e-possuirão também eles a yhwh que yhwh a-eles deu a-eles em-além-de o Jordão e-vós-voltar-se-ás homem dei a-vós dei para-vocês');
INSERT INTO verses VALUES (4998, 5, 3, 21, 'e-a יהושע eu-mandado-te aquela dizendo dizendo os-vossos-olhos que-visto את todo yhwh fez yhwh vosso-elohim para-dois os-reis yhwh assim fará tu para-todo as-mamlekhót que tu passando ali');
INSERT INTO verses VALUES (4999, 5, 3, 22, 'não terá-om que yhwh Elohim-vosso ele o-nilhám a-vós');
INSERT INTO verses VALUES (5000, 5, 3, 23, 'e-etchanán a yhwh aquela dizendo para-dizer');
INSERT INTO verses VALUES (5001, 5, 3, 24, 'Adonai yhwh tu a-chilótá l-haraóth a teu-servo et- gadlékha e-a mão-tua o-hazáká que quem El nos-céus e-na-terra que ele-fará como-os-teus-trabalhos e-como-tuas-forcas');
INSERT INTO verses VALUES (5002, 5, 3, 25, 'eu-passarei--- por-favor e-eu-verei a a-terra a-boa que em-além-de o Jordão a-montanha o-bom este e-o-libano');
INSERT INTO verses VALUES (5003, 5, 3, 26, 'e-ele-se-irritou yhwh em-mim por-vosso-causa e-não ouviu a-mim E-disse yhwh a-mim chefe-de para-ti a voces-aumentareis palavra a-mim ainda em-a-palavra a-esta');
INSERT INTO verses VALUES (5004, 5, 3, 27, 'folhas-de cabeça a-encosta e-elevar os-teus-olhos ao-poente e-no-norte e-ao-sul e-no-leste e-vê em-os-teus-olhos porque não passes a o-jordão a-esta');
INSERT INTO verses VALUES (5005, 5, 3, 28, 'e-manda a Yehoshua e-fortaleça-o e-amplie-o porque ele ele-passará diante-de o-povo esta e-ele ele-dar-virá a-eles a a-terra que você-ver-irá');
INSERT INTO verses VALUES (5006, 5, 3, 29, 'e-nós-moramos em-o-valle de-frente casa P''or');
INSERT INTO chapters VALUES (157, 5, 4, 49);
INSERT INTO verses VALUES (5007, 5, 4, 1, 'e-agora Israel ouviu a os-estatutos e-a eu que eu-sou ensinando vos laasot para-que vivereis e-vireis e-possuirão yhwh a-terra que yhwh a-vós pais-vosso deu para-vocês');
INSERT INTO verses VALUES (5008, 5, 4, 2, 'não acrescentareis sobre a-palavra eu eu ordenando vos e-não nós de-ele para-guardar yhwh mandamentos yhwh eu que eu mandando-o a-vós');
INSERT INTO verses VALUES (5009, 5, 4, 3, 'vossos-olhos os-vendo a que yhwh yhwh em-Baal que porque todo andar que andou depois-de yhwh peor destrui-lo yhwh seus-elohim do-teu-interno');
INSERT INTO verses VALUES (5010, 5, 4, 4, 'e-vós os-colados em-יהוה vosso-Elohim vida voces-todos o-dia');
INSERT INTO verses VALUES (5011, 5, 4, 5, 'veja aprendi vocês decrees e-julgamentos como mandei-me yhwh yhwh para fazer assim em-meio-de a-terra a-terra vós vindo para lá para-possuí-la');
INSERT INTO verses VALUES (5012, 5, 4, 6, 'e-vós-guardareis e-fazeis que ela sabedoria-vosso e-entendimento-vosso aos-olhos-de as-nacoes que ouvirão a todo os-custos estes e-diretriz somente com sábio e-inteligente o-povo o-grande a-esta');
INSERT INTO verses VALUES (5013, 5, 4, 7, 'que quem nação grande que- a-ele a-ele próximos a-ela como-yhwh a-ele em-todo nos-chamou a-ele');
INSERT INTO verses VALUES (5014, 5, 4, 8, 'e-quem nação grande que para-ele chuqim umispatim tsadikim como-tudo hatorah a-esta eu eu deu o-dia o-dia');
INSERT INTO verses VALUES (5015, 5, 4, 9, 'rak hisshamer a-ti ushmor nafshecha muito para-que-não tishchach a hadvarim que viram os-teus-olhos dias-de tua-vida do-teu-coracao todo dias-de vida-tua e-anunciaste-os aos-teus-filhos e-aos-filhos-de de-teus-filhos');
INSERT INTO verses VALUES (5016, 5, 4, 10, 'dia que estiveste diante-de yhwh os-teus-elohim em-Horebe em-o-dizer yhwh a-mim a-reunir- a-mim a o-povo e-fará-os-ouvir a as-minhas-palavras que aprenderão para-temer eles vida os-dias que eles vidos sobre a-terra e-a nos-seus-filhos ensinarão-os');
INSERT INTO verses VALUES (5017, 5, 4, 11, 'e-vocês-se-achegaram e-vocês-pararam-se debaixo o-monte e-o-monte queimando em-o-fogo até coração os-céus escuridão nuvem e-trevas');
INSERT INTO verses VALUES (5018, 5, 4, 12, 'e-ele-falou yhwh a-vós de-meio-de o-fogo voz palavras vós ouvindo e-imagem não-vós vendo exceto-eu voz');
INSERT INTO verses VALUES (5019, 5, 4, 13, 'e-anunciou a-vós a bra-rito-o que tsi-vu-a vos para-fazer a-sre-t ha-dvar-im va-yikhtev-em sobre segundo lu-hot a-banim-kaf-segol');
INSERT INTO verses VALUES (5020, 5, 4, 14, 've-oti tsi-vu-a yhwh em-o-tempo aquela para-ensiná-lo vos chuqim umishpatim laasotchem eles na-a-terra que vós ovrim para lá para-possuí-la');
INSERT INTO verses VALUES (5021, 5, 4, 15, 'venishmartem muito lenafshoteychem que não reitem todo tumunah em-dia-de yhwh yhwh aleichem bchorve de-meio o-fogo');
INSERT INTO verses VALUES (5022, 5, 4, 16, 'para-que-não vocês-destruirão a-vós a-vós escultura imagem-de todo macho modelo fêmea ou fêmea');
INSERT INTO verses VALUES (5023, 5, 4, 17, 'modelo todo animal que em-a-terra modelo asa pássaro asa que voo em-os-ceus-verso');
INSERT INTO verses VALUES (5024, 5, 4, 18, 'forma todo réptil na-terra forma todo debaixo-de que nas-aguas de-baixo para-a-terra');
INSERT INTO verses VALUES (5025, 5, 4, 19, 'e-não-que levantes os-seus-olhos os-ceus e-viu a o-sol e-a a-lua e-a as-estrelas todo a-eles os-céus e-serás-expulso e-te-inclinarás yhwh e-servir-lhes-eis eles a-todo yhwh debaixo a-eles para-todo os-povos sob todo os-céus');
INSERT INTO verses VALUES (5026, 5, 4, 20, 'e-vós tomou yhwh e-saiu a-vós de-o-matriz o-ferro de-Egito a-ser a-ele para-o-povo herança como-o-dia a-esta');
INSERT INTO verses VALUES (5027, 5, 4, 21, 'e-יהוה ira-seu- em-mi sobre para-não e-ele-jurou para-não passar a o-Jordão e-para-não- yhwh a a-terra a-ti que yhwh Elohim-teu deu para-ti herança');
INSERT INTO verses VALUES (5028, 5, 4, 22, 'que eu morreu na-terra a-esta ainenini transitorio- a o Jordão e-vós ovrim virishatem a a-terra hatovah a esta');
INSERT INTO verses VALUES (5029, 5, 4, 23, 'hisshamru a-vós para-que-não tishchchu yhwh berit yhwh אֱלֹהִים-de-vós que karat a-vós e-fareis para-vós pesel tumunat todo yhwh cum-pronunciaste yhwh Elohim-tua');
INSERT INTO verses VALUES (5030, 5, 4, 24, 'que yhwh teu-Elohim fogo comedora ele El zelo');
INSERT INTO verses VALUES (5031, 5, 4, 25, 'porque gerarás filhos filhos filhos e-vos-envelheceráis em-a-terra e-vos-destruirá e-voces-fareis escultura imagem-de todo e-voces-fareis o-mal em-olhos-de yhwh- Elohim-seu para-irritar-ele');
INSERT INTO verses VALUES (5032, 5, 4, 26, 'eu-testifiquei-a voces o-dia a os-céus e-a a-terra porque de-cima-de a-terra apressai-vos de-sobre a-terra que vós passantes a o Jordão para lá que não seu-tempo dias sobre-ela porque se-desgastaram vocês-se-desgastarão');
INSERT INTO verses VALUES (5033, 5, 4, 27, 'e-espalhará yhwh vos entre-os-povos e-vocês-permanecerão mortos de-número entre-os-povos que ele-conduzirá yhwh vos ali');
INSERT INTO verses VALUES (5034, 5, 4, 28, 'e-voces-servireis-ao ali Elohim obra-de homem árvore madeira-de e-eu-mostrarei que não eles-verão e-não eles-ouvirão e-não eles-comerão e-não eles-cheirarão');
INSERT INTO verses VALUES (5035, 5, 4, 29, 'e-voces-procurareis de-lá a yhwh teu-Elohim que porque voces-o-pesquisareis em-todo do-teu-cor e-em-todo alma-tua');
INSERT INTO verses VALUES (5036, 5, 4, 30, 'em-dificuldade a-ti e-achou-te todo as-palavras estas na-fim os-dias e-voltarás até yhwh teu-Elohim e-ouvirás na-sua-voz');
INSERT INTO verses VALUES (5037, 5, 4, 31, 'que El misericordioso yhwh teu-Elohim não curará-te e-não destruir-te e-não esquecer-á a aliança avós-teus que a-eles para-eles');
INSERT INTO verses VALUES (5038, 5, 4, 32, 'que pergunta- por-favor para-dias primeiros que foram em-te criou o-dia que homem Elohim homem sobre a-terra e-ao-fim os-céus e-até fim os-céus se-tornou como-palavra a-grande esta ou que-foi-ouvido como-ele-verso-final');
INSERT INTO verses VALUES (5039, 5, 4, 33, 'se-ouviu povo voz Elohim falando de-meio-de- a-chama tu ouviste tu e-viveu-verso-final');
INSERT INTO verses VALUES (5040, 5, 4, 34, 'ou se-quiseram Elohim para-vir tomando a-ele a-ele de-meio-de nação em-sinais em-maravilhas e-em-sinais e-em-guerra e-na-mão forte e-no-braco estendida e-em-terrores grandes conforme-tudo que fez a-vós yhwh Elohim-vosso em-Egito para-os-olhos-teus');
INSERT INTO verses VALUES (5041, 5, 4, 35, 'tu viste para-conhecer que yhwh ele o-Elohim não-há ainda além-dele');
INSERT INTO verses VALUES (5042, 5, 4, 36, 'de os-céus fez-te-ouvir a seu-grito para-te-moldar e-sobre a-terra mostrou-te a seu-fogo o-grande e-seus-palavras ouviste de-dentro-de o-fogo');
INSERT INTO verses VALUES (5043, 5, 4, 37, 'e-sob que amou a avós-teus e-ele-escolheu em-seu-sêmen atrás-dele e-ele-te-arrancou em-suas-frentes o-grande a-grande de-Egito');
INSERT INTO verses VALUES (5044, 5, 4, 38, 'para-expulsar nações grandes e-fortes de-vós de-diante-de-você para-te-trazer para-dar a-você a a-terra-deles herança como-o-dia a-esta');
INSERT INTO verses VALUES (5045, 5, 4, 39, 'e-conhecerás o-dia e-devolverás a que yhwh ele ele הָֽאֱלֹהִ֔ים nos-céus de-acima e-sobre a-terra de-baixo-de não ainda');
INSERT INTO verses VALUES (5046, 5, 4, 40, 'e-guardarás a seus-estatutos e-a eu que o-dia mandamentos-teus o-dia a-ti será-bom para-ti e-aos-seus-filhos depois-de-ti e-para-o-fim-de tardar dias yhwh a-terra que a-ti Elohim-teu deu para-ti todo os dias');
INSERT INTO verses VALUES (5047, 5, 4, 41, 'então separará Moisés três cidades em-além-de o Jordão do-leste do-sol');
INSERT INTO verses VALUES (5048, 5, 4, 42, 'para-fugir para-lá o-mata que matará a seu-amigo em-bilí- conhecimento a-ele não odiou a-ele de-ontem antes-de-ontem e-fugiu a uma de as-cidades o-elohim e-viveu');
INSERT INTO verses VALUES (5049, 5, 4, 43, 'a [בַּמִּדְבָּ֛ר] no-deserto em-terra-de o-plano para-o-Ruveni e-a Ramat em-a-Gilead para-o-Gadi e-a golan em-a-Bashan para-o-Menashi');
INSERT INTO verses VALUES (5050, 5, 4, 44, 'e-esta a-Torah que nome Moisés diante-de filhos-de Israel');
INSERT INTO verses VALUES (5051, 5, 4, 45, 'Estas as-Eidot e-os-estatutos e-os-julgamentos que palavra Moisés a filhos-de Israel em-sair-de-eles de-Egito');
INSERT INTO verses VALUES (5052, 5, 4, 46, 'em-lado-de o Jordão na-vala em-frente-a casa Peor na-terra Siom rei o amorreu que habitante em-Hesbom que bateu Moisés e-filhos-de Israel em-sair-de-eles de-Egito');
INSERT INTO verses VALUES (5053, 5, 4, 47, 'e-ele-os-herdou a sua-terra e-a terra Og rei-de o-Basã segundo reis-de o amorreu que em-além-de o Jordão do-leste do-sol');
INSERT INTO verses VALUES (5054, 5, 4, 48, 'de-Aroer que sobre borda-de o-riacho de-arnon ele monte-de sion ele Hermom');
INSERT INTO verses VALUES (5055, 5, 4, 49, 'e-todo a-aravah alado o-Jordão para-o-nascente mar mar debaixo sob as-dos da-cima');
INSERT INTO chapters VALUES (158, 5, 5, 33);
INSERT INTO verses VALUES (5056, 5, 5, 1, 'E-chamou Moisés a E-disse Israel E-disse a-eles ouviu Israel a eu e-a os-juízos o-dia eu eles em-vossas-orelhas o-dia e-vos-aprendestes a-eles e-vos-guardastes para-fazer-los');
INSERT INTO verses VALUES (5057, 5, 5, 2, 'yhwh nosso-Elohim cortou immanu berith Horob');
INSERT INTO verses VALUES (5058, 5, 5, 3, 'não a avoteinu yhwh yhwh a que esta porque Estas nós o-dia poa vida todos nós vivos');
INSERT INTO verses VALUES (5059, 5, 5, 4, 'faces em-faces palavra yhwh yhwh na-montanha de-meio o-fogo');
INSERT INTO verses VALUES (5060, 5, 5, 5, 'eu ficou-em-pé entre yhwh e-entre-vocês aquela aquele a-vós a-vós yhwh que yhwh de-diante-de temer-vos de-diante-de o-fogo dizendo subistes na-montanha para-dizer');
INSERT INTO verses VALUES (5061, 5, 5, 6, 'eu yhwh teu-Elohim que saí-te da-terra-de Egito de-casa escravos');
INSERT INTO verses VALUES (5062, 5, 5, 7, 'não será- para-ti Elohim outros sobre minhas-faces');
INSERT INTO verses VALUES (5063, 5, 5, 8, 'não para-ti ídolo- todo imagem que nos-céus- de-acima e-o-que em-a-terra de-abaxo e-que na-agua de-abaxo debaixo-de');
INSERT INTO verses VALUES (5064, 5, 5, 9, 'não a-eles para-eles e-não que eu yhwh yhwh Elohim-teu El zeloso que-visita pecado pais sobre filhos e-sobre tri-nos e-sobre quad-ro-s a-o-inim-ho');
INSERT INTO verses VALUES (5065, 5, 5, 10, 'e-faz chan-dor a-mil-ho-s a-am-o-s e-para-guardadores-de');
INSERT INTO verses VALUES (5066, 5, 5, 11, 'não e-le-va a nome-de yhwh que não porque yhwh pur-gar-a yhwh a que e-le-va a nome-de-ele para-a-vaidade-verso-final');
INSERT INTO verses VALUES (5067, 5, 5, 12, 'guarda a dia a-sabáte para-consagrar-o como-que mandou-te yhwh os-seus-elohim');
INSERT INTO verses VALUES (5068, 5, 5, 13, 'servirás e-fazes todo o-teu-trabalho-verso-final');
INSERT INTO verses VALUES (5069, 5, 5, 14, 'e-dia o-sétimo sábado- Elohim-teu não farás não trabalho tu tu uvitca e-servo-teu- e-moça-teu e-vaca-teu e-jumento-teu e-todo be-em-techa ve-gercha que bi-shaarecha para-que yanchah avadcha ve-amatcha kamocha');
INSERT INTO verses VALUES (5070, 5, 5, 15, 'vezacharta porque servo hayita em-terra-de mitzrayim e-te-saiu yhwh os-teus-elohim de-aquele-lá com-mão forte e-com-braco esticada sobre sim yhwh yhwh teu-Elohim para-fazer a dia a-sabáte');
INSERT INTO verses VALUES (5071, 5, 5, 16, 'honra a teu-pai e-a a-teua-mãe yhwh com-mand-o-te yhwh teu-Elohim para-a-cau-sa-de pro-long-a-rem os-se-u-dias e-para-a-cau-sa-de para-ti sobre a-terra a-te-rri-tó-ria que yhwh para-ti deu para-ti');
INSERT INTO verses VALUES (5072, 5, 5, 17, 'não');
INSERT INTO verses VALUES (5073, 5, 5, 18, 'e-não');
INSERT INTO verses VALUES (5074, 5, 5, 19, 'e-não não-rou-bas');
INSERT INTO verses VALUES (5075, 5, 5, 20, 'e-não res-pon-da a-am-i-go-te-u até vai-vu');
INSERT INTO verses VALUES (5076, 5, 5, 21, 'e-não tachmod mulher-de re''ekha e-não titavveh casa re''eka sadehu ve-avdo va-amato shoro vachamoro e-todo e-tudo lere''eka');
INSERT INTO verses VALUES (5077, 5, 5, 22, 'a as-palavras os-estes yhwh yhwh a todo assembleia-vossa na-montanha de-meio voz do-nuvem e-o-trevas voz grande e-não ele-acrescentou e-ele-escreveu-os sobre segundo tabelas de-pedras e-colocou-os para-mim');
INSERT INTO verses VALUES (5078, 5, 5, 23, 'e-houve como-vosso-ouvir a o-ruído de-meio-de a-escuridão e-o-monte queimando no-fogo e-aproximastes-vos a-mim todo topos-de de-vosso-sajam veziknechem');
INSERT INTO verses VALUES (5079, 5, 5, 24, 'e-dissestes eis mostrai-nos yhwh Elohim-nosso a sua-glória e-a seu-grandeza e-a seu-ruído o-dia de-meio-de o-fogo o-dia este ra-inu porque dirá Elohim a o-homem e-viveu');
INSERT INTO verses VALUES (5080, 5, 5, 25, 'e-agora por-que morremos que comereis-nos o-fogo a-grande esta se e-os-yosifim nós para-ouvir a yhwh yhwh Elohim nosso ainda e-mossemortos');
INSERT INTO verses VALUES (5081, 5, 5, 26, 'que quem todo em-carne que voz voz vida vivos falando de-meio- a-chama como-nos e-ele-viveu');
INSERT INTO verses VALUES (5082, 5, 5, 27, 'oferta tu e-ouviu a todo que yhwh yhwh Elohim-nosso e-tu falarias a-nos את todo que yhwh yhwh Elohim nosso a-ti e-ouvimos e-fizemos');
INSERT INTO verses VALUES (5083, 5, 5, 28, 'E-ouviu yhwh a voz-de palavras-vosso em-palavras-vosso E-disse yhwh yhwh a-mim ouvira-eu a voz palavras-de o-povo o-este que falaram para-ti melhoraram todo que diguem-vos');
INSERT INTO verses VALUES (5084, 5, 5, 29, 'quem de-a e-será a-eles-os-seus-coracoes a-eles para-ela-os para-o-timo de-mim-me e-para-guardar a todo as-minhas-mandamentos a-eles os-dias para-sempre seja-bom a-eles e-aos-seus-filhos para-sempre');
INSERT INTO verses VALUES (5085, 5, 5, 30, 'vai disse a-eles retornem a-vós para-os-tendas-vos');
INSERT INTO verses VALUES (5086, 5, 5, 31, 'e-tu aqui ficou-em-pé comigo e-falarei-eu a-ti com todo as-mandamentos e-as-instituições e-os-julgamentos que ensinareis-eles na-terra em-a-terra eu eu a-eles a-eles para-possuí-la');
INSERT INTO verses VALUES (5087, 5, 5, 32, 'e-guardareis para-fazer como-que mandou yhwh Elohim de-vós a-vós não vireis direita e-vos-maio');
INSERT INTO verses VALUES (5088, 5, 5, 33, 'em-todo o-caminho que yhwh yhwh elohim-vosso vos andareis para-que viverais a-vós a-vós e-estendereis dias na-terra que vos-recebereis');
INSERT INTO chapters VALUES (159, 5, 6, 25);
INSERT INTO verses VALUES (5089, 5, 6, 1, 'e-esta a-mandamento os-estatutos e-os-decretos que deu-mandamento yhwh Elohim de-vós para-ensiná-lo a-vós para fazer na-terra que vós os-passantes para lá para-possuí-la');
INSERT INTO verses VALUES (5090, 5, 6, 2, 'para-que terás-temor a yhwh Elohim-teus para-guardar a todo eu e-seus-mandamentos tu eu seus-mandamentos-teus tu dias-de tua-vida seu-filho todo dias-de vida-tua e-para-alma prolongará-eles teus-dias');
INSERT INTO verses VALUES (5091, 5, 6, 3, 'e ouvirás Israel e-guardasteis-vos para-fazer que será-bom a-ti e-que aumentareis muito como-que palavra yhwh Elohim-de avós-teus para-ti terra fluindo-de leite e-mel');
INSERT INTO verses VALUES (5092, 5, 6, 4, 'Israel yhwh yhwh יְהוָה');
INSERT INTO verses VALUES (5093, 5, 6, 5, 'e-amareis a yhwh teu-Elohim em-todo ao-teu-coração e-em-todo alma-tua e-em-todo com-toda-a-sua-força');
INSERT INTO verses VALUES (5094, 5, 6, 6, 'e-sejam as-palavras estes que eu os-seus-mandamentos o-dia sobre ao-teu-coração');
INSERT INTO verses VALUES (5095, 5, 6, 7, 'e-ensinareis-os para-os-teus-filhos e-falarás neles em-a-tua-sentar-te em-a-tua-casa e-em-a-tua-andares no-caminho e-em-a-tua-deitares-te e-em-a-tua-levantares-te');
INSERT INTO verses VALUES (5096, 5, 6, 8, 'e-vincularás-eles para-sinal sobre e-sejam e-serão entre entre de-tus-teus-olhos');
INSERT INTO verses VALUES (5097, 5, 6, 9, 'e-escrit-os sobre em-o-porta-s na-casa-tua e-na-por-do-teu');
INSERT INTO verses VALUES (5098, 5, 6, 10, 'e-será que ele-vir-te yhwh yhwh a a-terra que jura a-os-pais-tuus para-Abraão a-isaac e-a-jacob para-dar para-ti cidades grandes e-boas que não construiste.');
INSERT INTO verses VALUES (5099, 5, 6, 11, 'e-casas cheios-de todo bom que não encheste e-berços cortados que não cavaste-a vinhas e-comerás que não plantaste e-comer-aes e-satisfazer-te-ao');
INSERT INTO verses VALUES (5100, 5, 6, 12, 'hisshamer a-ti para-que-não esquecer-te-ás a yhwh que saiu-te de-terra-de Egito de-casa-de servos');
INSERT INTO verses VALUES (5101, 5, 6, 13, 'a yhwh Elohim-teu temas e-aquele-o servir-lhe-es e-no-seu-nome-o jures-vos-');
INSERT INTO verses VALUES (5102, 5, 6, 14, 'não ide-vós- atrás-de Elohim outros de-elohim- os-povos que em-vossos-redores-');
INSERT INTO verses VALUES (5103, 5, 6, 15, 'que El zeloso- yhwh teu-Elohim בְּקִרְבֶּ֑ךָ para-que-não ira-se- também sobre-ti Elohim-teu de-cima-de face-de a-terra face-de a-terra');
INSERT INTO verses VALUES (5104, 5, 6, 16, 'não provai-vós- a yhwh vosso-Elohim como-que provasseis-vos- na-prova-');
INSERT INTO verses VALUES (5105, 5, 6, 17, 'guarda guardareis a yhwh yhwh vosso-Elohim e-as-sua-testemunhas e-seus-hukkayu que mandou-vos');
INSERT INTO verses VALUES (5106, 5, 6, 18, 've''asitā the-just e-o-bom em-olhos-de yhwh a-fim-de melhor para-ti ובאתה e-possuirás a a-terra o-bom yhwh jurou yhwh para os teus pais:');
INSERT INTO verses VALUES (5107, 5, 6, 19, 'para-a-rejeitar a todo teus-inimigos de-diante-de-você yhwh palavra yhwh');
INSERT INTO verses VALUES (5108, 5, 6, 20, 'porque yishalheka bincha dizendo dizendo que as-testemunhas e-os-preceitos e-os-mishpatim que yhwh yhwh Elohim-nosso a-vós');
INSERT INTO verses VALUES (5109, 5, 6, 21, 'e-dirás para o teu filho servos fomos para Faraó em-Egito e nos tirou yhwh de-misraim com-mão forte');
INSERT INTO verses VALUES (5110, 5, 6, 22, 'E-colocou yhwh אתות e maravilhas גדולים e males no Egito em Faraó e-em-todo casa-dele perante nossos olhos:');
INSERT INTO verses VALUES (5111, 5, 6, 23, 'e-a-nos extraiu de-lá a-fim-de traga a-nós dar a-nós a a-terra que jurou para-os-avós-nossos');
INSERT INTO verses VALUES (5112, 5, 6, 24, 'e-ele-comandou-nos yhwh para-fazer a todo os-custos os-estes para-o-tremor a yhwh Elohim-nosso para-o-bom a-nós todo os-dias para-viver-nos como-no-dia a-esta');
INSERT INTO verses VALUES (5113, 5, 6, 25, 'u-tsedakah será- nós porque nós-guardamos a fazer a yhwh a-mandamento desta diante-de yhwh Elohim-nosso como-que deu-me-o-comando');
INSERT INTO chapters VALUES (160, 5, 7, 26);
INSERT INTO verses VALUES (5114, 5, 7, 1, 'que faz-te-vir yhwh teu-Elohim a a-terra que tu veio-a para lá para-a-sua-herança e-expulsou nações-a muitos-os de-diante-de-você o-hitita e-o-geregeshi e-o-amorreu e-o-canaanita e-o-prizi e-o-hiviti e-o-ibusita sete nações muitos e-grandes מִמֶּֽךָּ׃');
INSERT INTO verses VALUES (5115, 5, 7, 2, 'e-dê-os-a- yhwh Elohim-teu diante-de-ti e-golpeie-os-a o-harem vocês-excluam eles não a-eles a-eles berith e-não te-chan-ê-mês');
INSERT INTO verses VALUES (5116, 5, 7, 3, 'e-não ti-tchat-te-ne neles be-th-chak não ti-the-ne le-bne-o e-sua-filha não tome-você le-bne-chak');
INSERT INTO verses VALUES (5117, 5, 7, 4, 'porque se afastará a teu filho de-me-a-trás e servirão Elohim outros e arderá também yhwh em vós e destruirá-vos logo');
INSERT INTO verses VALUES (5118, 5, 7, 5, 'porque se a-eles fazeis a-eles de-seus-mostruários despedaçais e-de-sus-tábuas esmaga-is e-de-seus-ídolos cortais-no e-de-sus-imagens queimais-os em-a-chama');
INSERT INTO verses VALUES (5119, 5, 7, 6, 'que povo santo tu a-yhwh teu-Elohim em-vós escolheu- yhwh yhwh a-ser a-ele a-ele סְגֻלָּ֔ה de-todo de-toda que sobre face-de a-terra');
INSERT INTO verses VALUES (5120, 5, 7, 7, 'não de-vos-superiores de-todo o-povo yhwh yhwh vocês va-yibchar em-vocês porque vós o pouco de-todo o-povos');
INSERT INTO verses VALUES (5121, 5, 7, 8, 'que de-amor yhwh vocês a a-juramento que jurou para-pais-de-vocês tire-ou yhwh vos com a mão חֲזָקָה e-vos-redimiu de-casa-de escravos de-mão-de Faraó rei-de Egito');
INSERT INTO verses VALUES (5122, 5, 7, 9, 'e-conhecerás porque yhwh ele ele o-Elohim o-elohim o-fiel guarda a aliança e-a-mercê para-seus-amados e-para-guardadores-de para-mil geração');
INSERT INTO verses VALUES (5123, 5, 7, 10, 'e-pagando para-seus-inimigos a sua-face não não adiará para-o-suspeito a de-seus-faces yešallêm- a-ele');
INSERT INTO verses VALUES (5124, 5, 7, 11, 'e-observarás a a-m Mandamentos e-a as-leis eu os-julgamentos o-dia Eu os-seus-mandamentos o-dia para-os-pra cumprir:');
INSERT INTO verses VALUES (5125, 5, 7, 12, 'e-era ekev vocês-ouvirão a os-julgamentos os-estes e-vigiarão e-fizerdes a-eles eles yhwh yhwh para-ti a-ti a-aliança e-a a-mercê que jurou para os teus pais:');
INSERT INTO verses VALUES (5126, 5, 7, 13, 'e-am-te e-bençao-te e-multiplica-te e-benção fruto- de-tu-estômago e-fruto-de terra-teu pão-teu e-vinho-teu וְיִצְהָרֶ֗ךָ oleiro-de sobre e-ashtorot o-teu-rebanho sobre a-terra para-ti jurou para-os-seus-avos para-dar para-ti');
INSERT INTO verses VALUES (5127, 5, 7, 14, 'bendito ser-as de-todo o-povos não será em-você estéril-masculino e-estéril-feminino e-no-teu-gado');
INSERT INTO verses VALUES (5128, 5, 7, 15, 'e-o-removerá yhwh de-vós todo doença e-todo por-causa-de em-o-Egito הָרָעִים não conheceste sobre-ti ele-os-fará-ser em-você e-o-dar-lhes-ele em-todo seus-inimigos:');
INSERT INTO verses VALUES (5129, 5, 7, 16, 'e-comerás a todo yhwh que yhwh para-ti deu para-ti não olha no teu olho sobre-eles e-não ele para-ti a-ti porque enxerto ele para-ti');
INSERT INTO verses VALUES (5130, 5, 7, 17, 'que dirás no-seu-lábio muitos as-nações estes de-mim como posso para-os');
INSERT INTO verses VALUES (5131, 5, 7, 18, 'não temer-te-iras deles macho você-recordará a que yhwh yhwh teu-Elohim para-o-Pharaoh e-para-todo- Egito');
INSERT INTO verses VALUES (5132, 5, 7, 19, 'as-taxes os-grandes que viram os-teus-olhos e-as-sinais e-os-maravilhas e-a-mão a-forte e-o-braço o-esticado que yhwh yhwh teu-Elohim yhwh faz yhwh Elohim-teu temer os-povos que tu temendo de-faces-deles');
INSERT INTO verses VALUES (5133, 5, 7, 20, 'e-também a a serpente yhwh yhwh teu-Elohim neles até servir-ás os-restantes e-os-nascostos de-diante-tua');
INSERT INTO verses VALUES (5134, 5, 7, 21, 'não terás-terror de-face-deles porque yhwh Elohim-teu em-o-teu-interior El grande e-será-nobre');
INSERT INTO verses VALUES (5135, 5, 7, 22, 'e-vomitarão yhwh Elohim-teu a os-povos o-elohim de ti diante pouco não não poderás completaste-os apressa-te para-que-não animal-de sobre-ti vivente-de o-campo');
INSERT INTO verses VALUES (5136, 5, 7, 23, 'e-dê-eles yhwh teu-Elohim diante-de-ti e-destrói-os confusão grande até extermina-eles');
INSERT INTO verses VALUES (5137, 5, 7, 24, 'e-dará reis-deles em tua mão e-destruí-lo a debaixo-de de-debaixo-de os-céus não se-posicionará até em-teu-frente eles extermina-te a-eles');
INSERT INTO verses VALUES (5138, 5, 7, 25, 'פְּסִילֵי elohim-deles queimar-vos-eis no-fogo não desejar-a prata-o e-ouro sobre-eles para-ti para-que-não para-que-não vocês-concorrem-por que porque yhwh yhwh ele ela');
INSERT INTO verses VALUES (5139, 5, 7, 26, 'e-não trarás-a abominação-a a seu lar e-você-seja anátema-o como ele abominar-se vós-abominareis e-vos-aborrecereis vós-aborrecereis porque ele ela');
INSERT INTO chapters VALUES (161, 5, 8, 20);
INSERT INTO verses VALUES (5140, 5, 8, 1, 'todo a-mandamento eu אָנֹכִי o-dia o-dia guardareis laasot para-que viverdes-ei e-multiplicar-vos-eis e-vireis e-possuirão a yhwh que jurou yhwh a-pais-vossos');
INSERT INTO verses VALUES (5141, 5, 8, 2, 'e-lembrareis a todo o-caminho yhwh leva-te-a yhwh Elohim-teu este quarenta ano no-deserto para-que para-conhecer para-ensaiar-vos para-conhecer a que em-o-teu-corpo se-guardarás se não');
INSERT INTO verses VALUES (5142, 5, 8, 3, 'e-ele-te-afli-rá e-ele-te-fará-fome e-ele-te-alimentou o-ma-nãh que não soubeste e-não conhecerão os-teus-pais para-que faz-conhecê-lo-a-ti que não sobre sozinho em-o-separado o-homem que porque sobre todo o-homem pí- yhwh viverá o-homem');
INSERT INTO verses VALUES (5143, 5, 8, 4, 'tua-roupa não perdeu-a me''al-eka e-tuas-pernas não em-farinha este quarenta anos');
INSERT INTO verses VALUES (5144, 5, 8, 5, 'e-sabereis com que porque como Yahweh-te-aflixe homem yhwh seu-filho yhwh seus-elohim te-aflixando-vos');
INSERT INTO verses VALUES (5145, 5, 8, 6, 'e-guardareis a yhwh yhwh teu-Elohim para-andar nos seus caminhos ele a-ele');
INSERT INTO verses VALUES (5146, 5, 8, 7, 'que yhwh teu-Elohim trazendo-vos a terra terra terra nascentes-de-rios águas fontes e-as-tasmas saindo na-vale e-na-montanha');
INSERT INTO verses VALUES (5147, 5, 8, 8, 'terra chittha e a uvas e a vinha e as figos e os melões terra-de olivas óleo e-mel');
INSERT INTO verses VALUES (5148, 5, 8, 9, 'terra que não em-pobreza תֹּֽאכַל־ pão Belém não falta terra nela terra que suas-pedras de-ferro e-de-seus-montes cavarás bronze');
INSERT INTO verses VALUES (5149, 5, 8, 10, 'e-comerás e-satisfar-te-ás e-bendires a yhwh teu-Elohim sobre a-terra o-muito-bom que dou- para-ti');
INSERT INTO verses VALUES (5150, 5, 8, 11, 'hisshamer a-ti para-que-não não esqueças a para-não teu-Elohim sem guarda mandamentos-seus e-juízos-seus eu que o-dia dizendo o-dia');
INSERT INTO verses VALUES (5151, 5, 8, 12, 'para-que-não comerás e-satisfar-te-ás e-batim tobim construirás-a e-estarás');
INSERT INTO verses VALUES (5152, 5, 8, 13, 'e em teu gado e em tua ovelha multiplicarão-se e prata e ouro יִרְבֶּה־ e-tudo e-todo que a-ti יִרְבֶּֽה׃');
INSERT INTO verses VALUES (5153, 5, 8, 14, 'e-רָם ao-teu-corpo e-esquecerás a yhwh teu-Elohim o-que-te-saiu de-terra-de Egito de-casa-de servos');
INSERT INTO verses VALUES (5154, 5, 8, 15, 'o-que-te-conduziu no-deserto o-grande o-grande serpente serafim e-escorpião e-seca que não-há águas o-mostrante para-ti a-ti águas a-chalamish');
INSERT INTO verses VALUES (5155, 5, 8, 16, 'aquele que come-te de no-deserto que não sabem os teus pais para-que a tua resposta e-para-a-cau-sa-de o teu teste para te bem no-fim-de-te');
INSERT INTO verses VALUES (5156, 5, 8, 17, 'e-dirás bilbavekha força-te e-força minha-mão fez a-mim a a-fé a-esta');
INSERT INTO verses VALUES (5157, 5, 8, 18, 'e-lembrar-te-ás a yhwh que ele ele a-ti para-ti força para fazer força para-que ele-upara a além dele que jurou yhwh como-o-dia a-esta');
INSERT INTO verses VALUES (5158, 5, 8, 19, 'e-foi se para-esquecer você-esquecerá a yhwh teu-Elohim e-andaras depois-de Elohim outros a-eles e-você-se-curvará para-eles o-dia que o-dia porque servirás vocês-perderão');
INSERT INTO verses VALUES (5159, 5, 8, 20, 'כַּגּוֹיִ֗ם que yhwh destruidor de-diante-vosso assim vocês-perderão por-causa-de não vocês-ouvirão בְּקוֹל yhwh vosso-Elohim');
INSERT INTO chapters VALUES (162, 5, 9, 29);
INSERT INTO verses VALUES (5160, 5, 9, 1, 'ouviu Israel tu passando o-dia a o-Jordão para-vir para-possuir nações grandes e-grandes de ti cidades grandes e-em-pedras em-os-ceus-verso');
INSERT INTO verses VALUES (5161, 5, 9, 2, 'com grande e-alto filhos-de anaqueus tu tu tu-conheceste e-tu quem quem ele-se-estabelecerá diante-de filhos-de anak');
INSERT INTO verses VALUES (5162, 5, 9, 3, 'e-conhecerás o-dia que yhwh Elohim-teu ele o-passante em-te fogo ele ele destruir-êis e-ele subjugar-êis diante-de-ti [וְהַֽאַבַדְתָּם֙] e-destruir-êis apressado como yhwh para-ti para-ti');
INSERT INTO verses VALUES (5163, 5, 9, 4, 'a dizes no-cor-teu yhwh yhwh eles eles de-perante-ti dizendo em-justiça-meu trouxe-me yhwh para-possuir a a-terra esta e-em-perversidade as-nações yhwh yhwh rejeitando-os de-diante-tua');
INSERT INTO verses VALUES (5164, 5, 9, 5, 'não em-justiça-teu e-em-retidão para-o-teu-coracao tu veio para-possuir a que porque em-perversidade as-nações estes yhwh Elohim-teu rejeitando-os diante de ti e-para-o-fim-de levantar-á a a-palavra que yhwh yhwh aos-pais-teus le-abraham para-Isaque e-a-o-Jaĩo');
INSERT INTO verses VALUES (5165, 5, 9, 6, '[וְיָדַעְתָּ֗] que não em-a-justi-ça-de-vocë yhwh o teu Elohim deu a-ti a a-terra [הַזֹּ֖את] a-esta que porque com qshe- costas tu');
INSERT INTO verses VALUES (5166, 5, 9, 7, 'macho a esquecerás com que irritaste-o a yhwh teu-Elohim no-deserto de-o [מִצְרַ֗יִם] que saíste da-terra Egito até em-voces até o-lugar esta rebeldes fosteis com yhwh');
INSERT INTO verses VALUES (5167, 5, 9, 8, 'e-em-Chorob ira-estes-vos a yhwh yhwh yhwh em-vos para-destruir a-vós');
INSERT INTO verses VALUES (5168, 5, 9, 9, 'quando-elevar a-montanha para-levar tavas-de-pedra as pedras tavas-de-pedra a-aliança que yhwh yhwh com-vós e-estabeleci-me na-montanha dia dia e quarenta pão não não com-ido-a não não beb-ido-e');
INSERT INTO verses VALUES (5169, 5, 9, 10, 'E-colocou yhwh a-mim a segundo tábuas das-pedras kethubhim com-dedo Elohim e-em-eles como-todo-o as-coisas yhwh palavra yhwh com-vocês na-montanha de-meio o-fogo em-dia o povo');
INSERT INTO verses VALUES (5170, 5, 9, 11, 'e-houve de-fim quarenta dia e quarenta noite dar yhwh a-mim a segundo as-tavas as pedras lu-hot do pacto:');
INSERT INTO verses VALUES (5171, 5, 9, 12, 'E-disse yhwh a-mim levantou desce apressado deste-lado que corrompeu o-povo-tuo que saíste de-Egito desviaram-se rapidamente de o-caminho que tzivitim a-eles a-eles de-a-massecá');
INSERT INTO verses VALUES (5172, 5, 9, 13, 'E-disse yhwh a-mim-adai dizendo vi a o-povo este e-eis ele qshe- costas ela');
INSERT INTO verses VALUES (5173, 5, 9, 14, 'e-rep de-mim e-ashmidem e-emcheh a debaixo-de de-debaixo-de os-céus e-eeshah o-teka le-goy- nós e abundante de-nós');
INSERT INTO verses VALUES (5174, 5, 9, 15, 've-aefen e-ei-desce de o-monte e-o-monte queimando no-fogo e-dois tabelas sobre sobre duas-de minhas-mãos');
INSERT INTO verses VALUES (5175, 5, 9, 16, 'vaerae e-eis vocês-pecaram a-yhwh Elohim-vosso vocês-fizeram a-vós egel para-ídolo vocês-se-desviaram rápido de a-caminho yhwh ordenou yhwh a-vós');
INSERT INTO verses VALUES (5176, 5, 9, 17, 'e-eu-apanhei em-dois הַלֻּחֹ֔ת e-eu-joguei-os de-cima-de duas mãos-meuas e-eu-parti-los diante-de-olhos-vossos');
INSERT INTO verses VALUES (5177, 5, 9, 18, 'e-cai diante-de yhwh como-primeiro-vez quarenta dia e quarenta noite pão não comi-eu e-agua não bebi sobre todo pecado-vos que pecasteis para-fazer o-mal yhwh yhwh para-irritar-ele');
INSERT INTO verses VALUES (5178, 5, 9, 19, 'que temi-eu de-diante-de ha-af ve-ha-chemah que ira-se yhwh sobre-vós para-destruir a-vós E-ouviu yhwh a-mim também na-vez aquela');
INSERT INTO verses VALUES (5179, 5, 9, 20, 'e-com-Aaron ira-se yhwh muito para-destruir-o e-eu-roguei também por-causa-de אַהֲרֹן aquela a-isso');
INSERT INTO verses VALUES (5180, 5, 9, 21, 'e-a pecado-vos que fizestes a ele eu-tomei e-eu-queimei isso ele e-eu-cortei a-ele-o até hei-tev até que דַּ֖ק para pó e-eu-joguei a o-pó-dele a o-nachal o-descendo de o-monte');
INSERT INTO verses VALUES (5181, 5, 9, 22, 'e-na-queimada e-no-fumo e-nas-tumbas da-avareza queimadores fosteis a yhwh');
INSERT INTO verses VALUES (5182, 5, 9, 23, 'e-em-shaloch yhwh a-vos miqdash barne''ah dizendo aluh e-possuí a a-terra dei a-vós a-vós vatamaru yhwh פי yhwh אֱלֹהִים-de-vós a-ele he''emantem a-ele e-não ouviram na-sua-voz');
INSERT INTO verses VALUES (5183, 5, 9, 24, 'rebeldeiros fosteis com yhwh de-dia minha-mente a-vós');
INSERT INTO verses VALUES (5184, 5, 9, 25, 'e-cai diante-de yhwh a quarenta o-dia e-a quarenta a-noite que caí-te-eu yhwh disse yhwh para-destruir a-vós');
INSERT INTO verses VALUES (5185, 5, 9, 26, 'e-recebi-graças a yhwh e-disse-eu Adonai yhwh a destruirás seu-people vénaḥlát''echa que resgataste-vos em-teu-grandeza que saíste de-misraim com-mão forte');
INSERT INTO verses VALUES (5186, 5, 9, 27, 'macho para-o-servos-teus para-Abraao para-Isaque e-para-JaŃob a a túnica a o teu esforço o-povo esta e-a seu pecado e-a sua iniquidade');
INSERT INTO verses VALUES (5187, 5, 9, 28, 'para-que-não a-terra a-terra que saíste-nos da-quela por-causa-de yhwh yhwh para-trazê-los a a-eles que palavra para-eles e-da-sua-aversão a-eles saiu-os para-a-morte-deles no-deserto');
INSERT INTO verses VALUES (5188, 5, 9, 29, 'e-eles o-povo-teu e-a-herança-teu que tu-e-saiu-te com-força-tua o-grande e-em-a-tua-braca a-viciada-verso-final');
INSERT INTO chapters VALUES (163, 5, 10, 22);
INSERT INTO verses VALUES (5189, 5, 10, 1, 'na-epoca aquela disse yhwh a-mim esculpe- para-você dois placas-de-pedra pedras como-primeiro-vezes e-folha-de-arvore a-mim a-montanha e-farás árvore arca עֵֽץ׃');
INSERT INTO verses VALUES (5190, 5, 10, 2, 'e-eu-escreverei sobre הַלֻּחֹ֔ת a as-palavras que foram sobre as-tábuas הָרִאשֹׁנִ֖ים que quebraste-vos e-colocastes-os em-o-arca-verso');
INSERT INTO verses VALUES (5191, 5, 10, 3, 'eu fiz arca-de madeiras-de sete e cortei duas tabuas de pedra como primeiras e levantei a-montanha e-dois-de as tábuas בְּיָדִי׃');
INSERT INTO verses VALUES (5192, 5, 10, 4, 'e-ele-escriviu sobre as-tábu-la-s como-escrita o-primeiro a dez as-palavras que yhwh yhwh a-vocês na-montanha de-meio o-fogo em-dia-de a-assembleia yhwh yhwh para-mim');
INSERT INTO verses VALUES (5193, 5, 10, 5, 'e-virei e-desci de a-montanha e-ponha a הַלֻּחֹ֔ת na-arca que faça e-estavam nome yhwh mandaram-me yhwh');
INSERT INTO verses VALUES (5194, 5, 10, 6, 'e-filhos-de Israel das-fontes filhos-de Jaacan Moserah nome morreu Arão e-enterrou nome e-ele-o-consagrou Elazar filho-seu em-lugar-dele');
INSERT INTO verses VALUES (5195, 5, 10, 7, 'de-aí eles-partiram o-Gudgodá e-de o-Gudgodá terra terra os-rivos águas');
INSERT INTO verses VALUES (5196, 5, 10, 8, 'em-o-tempo aquela hivdávil yhwh a tribo-de o-levita para levar a arca em-aliança-de yhwh lá amód diante-de yhwh até o-dia bíshamó até o-dia a-esta');
INSERT INTO verses VALUES (5197, 5, 10, 9, 'sobre kéen não foi lélevi porção yhwh ele seus-irmaos yhwh ele yhwh como-que a-ele yhwh teu-Elohim a-ele');
INSERT INTO verses VALUES (5198, 5, 10, 10, 'e-eu estou-em-pé na-montanha como-os-dias os-primeiros quarenta dia e quarenta noite E-ouviu yhwh a-mim também na-vez aquela não yhwh yhwh a-destruir-te');
INSERT INTO verses VALUES (5199, 5, 10, 11, 'E-disse yhwh a-mim levantou vai para-o-sacrifício diante-de o-povo e-virão e-possuirão a a-terra que jurei a-eles a-dar para-eles');
INSERT INTO verses VALUES (5200, 5, 10, 12, 'e-agora Israel quanto yhwh teu-Elohim pedindo de-contigo que se para-a-treva a yhwh Elohim-teu para-andar ele caminhos-seus e-para-amor a-ele וְלַֽעֲבֹד֙ a yhwh Elohim-teu em-todo do-teu-cor e-em-todo alma-tua');
INSERT INTO verses VALUES (5201, 5, 10, 13, 'para-guardar a yhwh yhwh e-a eu que o-dia mandado-te para-ti para-bom para-ti');
INSERT INTO verses VALUES (5202, 5, 10, 14, 'eis a-yhwh teu-Elohim os-céus e-ceus os-céus a-terra e-todo que nela');
INSERT INTO verses VALUES (5203, 5, 10, 15, 'somente em-pais-seus apaixonou yhwh para-amor eles e-ele-escolheu de-a-semente-deles depois-deles [בָּכֶ֛ם] de-todo os-povos como-o-dia este');
INSERT INTO verses VALUES (5204, 5, 10, 16, 'e-mordereis a prepúcio-de os vossos corações e-o-cabeca-de-voces não voces-esmagareis ainda');
INSERT INTO verses VALUES (5205, 5, 10, 17, 'que yhwh Elohim-vosso ele Elohim-de הָֽאֱלֹהִ֔ים e-dono os-donos o-elohim o-grande o-gibor e-o-noraa que não levou face e-não ele-tome sód');
INSERT INTO verses VALUES (5206, 5, 10, 18, 'fez mispat יָת֖וֹם e-almana וְאֹהֵב ger para-dar a-ele pão vesimla');
INSERT INTO verses VALUES (5207, 5, 10, 19, 'e-voces-amem a o-ger porque גרים voces-foram em-terra-de Egito');
INSERT INTO verses VALUES (5208, 5, 10, 20, 'a yhwh Elohim-teu ele a-ele servir-lhe-es e-com-ele voces-se-apaixonarao e-no-seu-nome-o jures.');
INSERT INTO verses VALUES (5209, 5, 10, 21, 'ele tua-aleluias e-ele teu-Elohim que fez ''itkha a as-grandes-coisas e-a os-assustadores os-estes que Ra''u de-tus-teus-olhos');
INSERT INTO verses VALUES (5210, 5, 10, 22, 'em-setenta alma desceram os-teus-avós de-Egito e-agora e-nome-teu yhwh teu-Elohim como-estrelas-de os-céus para-multidão');
INSERT INTO chapters VALUES (164, 5, 11, 32);
INSERT INTO verses VALUES (5211, 5, 11, 1, 'v''áhabtá a yhwh teu-Elohim v''sháratlá guarda-dele v''chúqótiy u''mishpátáy u''mitzvótáy todo os dias');
INSERT INTO verses VALUES (5212, 5, 11, 2, 'v''idá''atem o-dia que não não b''né''kem que não souberam e-que não yhwh a mússar yhwh vosso-Elohim a seu-gdlo a sua-mão a-hzkah e-zruo a-nthy');
INSERT INTO verses VALUES (5213, 5, 11, 3, 'e-a ototav e-com maasav no-meio-de fez em-meio-de Egito para-Faraó rei-de Egito e-para-todo- terra-dele');
INSERT INTO verses VALUES (5214, 5, 11, 4, 'e-que fez le-chail Egito lesusav e-a-sua-carruagem que ele-espalhou a águas-de mar-de Suf sobre suas faces yhwh até o-dia yhwh até o-dia a-esta');
INSERT INTO verses VALUES (5215, 5, 11, 5, 'e-que fez a-vós no-deserto até ao-virdes-vós até o-lugar a-esta');
INSERT INTO verses VALUES (5216, 5, 11, 6, 'e-que fez latan e aviram filhos-de eliav filho-de reuvem que a-terra a-terra a boca-dela e foram engolidos e-a בתיהם e-a suas tendas e-a todo de-cima-de que pelos seus pés vida todo Israel');
INSERT INTO verses VALUES (5217, 5, 11, 7, 'que vossos-olhos os-vendo a yhwh o-grande yhwh o-grande que fez');
INSERT INTO verses VALUES (5218, 5, 11, 8, 'e-guardardes a todo eu que o-dia mandado-te o-dia para-que fortificai-vos e-vireis e-possuirão a a-terra que vós ovrim para lá para-possuí-la');
INSERT INTO verses VALUES (5219, 5, 11, 9, 'e-para-o-fim-de estendei dias sobre a-terra que yhwh yhwh aos-vossos-pais a-eles a-eles terra terra fluindo-de leite e-mel');
INSERT INTO verses VALUES (5220, 5, 11, 10, 'que a-terra que tu que-veio lá-baixo não não como-terra ela ele que onde-saiestes de-lá que semeareis a zera-ka e-irrigareis com-vosso-pé como-jardim o-verde-;');
INSERT INTO verses VALUES (5221, 5, 11, 11, 'E-a-terra que vós ovrim lá-baixo para-a-posse-de-la terra os-montes e-na-fissuras para-a-chuva os-céus você-beberá- águas');
INSERT INTO verses VALUES (5222, 5, 11, 12, 'terra que yhwh teu-Elohim pedir-te-á a-ela os-olhos-de yhwh yhwh teu-Elohim em-ela do-princípio o-ano e-até último anos');
INSERT INTO verses VALUES (5223, 5, 11, 13, 'e-foi se ouviu ouvi-reis a eu que eu o-dia vos o-dia para-amor a yhwh Elohim-vosso e-para-servi-lo em-todo nosso coração e-em-todo nossas almas:');
INSERT INTO verses VALUES (5224, 5, 11, 14, 'e eu dar-ei chuva- vossa terra em seu tempo que ensinarei e que ferirá e recolher-eis vossa cevada e o teu mosto e a tua azeitona;');
INSERT INTO verses VALUES (5225, 5, 11, 15, 'e-darei erva-de em-seu-campo para-teu-animais e-comerás e-satisfazer-te-ao');
INSERT INTO verses VALUES (5226, 5, 11, 16, 'cuidem-se a-vós para-que-não ele-conduzirá os vossos corações e-vos-vireis e-servi-vos Elohim outros e-vos-inclinar-eis a-eles');
INSERT INTO verses VALUES (5227, 5, 11, 17, 'e arderá também yhwh em vós e reterá a os-céus e-não não chuva e a terra não dará de-cima-de a-terra e destruireis rapidamente yhwh a-terra a-vós que yhwh deu a-vós');
INSERT INTO verses VALUES (5228, 5, 11, 18, 'e colocareis a Estas estas sobre no vosso coração eles e na vossa alma e amarrar e-sejam לְאֹת֙ entre vossos-olhos a-ti em totapot entre vossos olhos');
INSERT INTO verses VALUES (5229, 5, 11, 19, 'e-aprendereis eles a benechem para-falar neles em-a-tua-sentar-te em-a-tua-casa e-em-a-tua-andares no-caminho e-em-a-tua-deitares-te e-em-a-tua-levantares-te');
INSERT INTO verses VALUES (5230, 5, 11, 20, 'e-escrit-os sobre mezuzot na-casa-tua e-na-por-do-teu');
INSERT INTO verses VALUES (5231, 5, 11, 21, 'para-que se multipliquem vosso tempo e os dias de vossos filhos sobre a-terra que jura yhwh para os pais-vos para-dar a-eles nos-dias os-céus sobre a-terra');
INSERT INTO verses VALUES (5232, 5, 11, 22, 'que se guardareis vós-guardardes-ei a todo eu desta que eu mandando-o vos para-fazer-a para-amor a yhwh Elohim-vosso para-andar em-todo seus-caminhos e-para-adherir-a-o nele-verso');
INSERT INTO verses VALUES (5233, 5, 11, 23, 'e-esvaecer yhwh a todo os-povos estes de-vos e-possuirão nações grandes e-grandes de-vós');
INSERT INTO verses VALUES (5234, 5, 11, 24, 'todo o-lugar que pisará palma-de a-vós será para-vós yihye de o-deserto e-o-libano o-mar o-river será perat e-ate ha-yam o-ultimo será vossa-fronteira');
INSERT INTO verses VALUES (5235, 5, 11, 25, 'não se-posicionará homem ante vós o vosso temor e o vosso medo dará yhwh vosso-Elohim sobre face-de todo a-terra que vos atormentem a-vós conforme palavra a-vós');
INSERT INTO verses VALUES (5236, 5, 11, 26, 'viu eu deu diante-de-vós o-dia ברכה [וּקְלָלָֽה]');
INSERT INTO verses VALUES (5237, 5, 11, 27, 'a [אֲשֶׁ֣ר] que [אֶל־מִצְוֺת֙] yhwh mandamentos yhwh eu que eu o-dia vós o-dia');
INSERT INTO verses VALUES (5238, 5, 11, 28, '[וְהַקְּלָלָ֗ה] se não vocês-ouvirão yhwh mandamentos yhwh Elohim-vosso [אֲשֶׁ֧ר] eu o-caminho que o-dia mandando-o vos o-dia para-andar depois-de Elohim outros que não יְדַעְתֶּֽם׃');
INSERT INTO verses VALUES (5239, 5, 11, 29, 'e-foi que יְבִֽיאֲךָ֙ yhwh teu-Elohim a a-terra que tu veio para lá לְרִשְׁתָּהּ e dará a a bênção sobre monte-de os-garfos e-a a maldição sobre monte-de evém:');
INSERT INTO verses VALUES (5240, 5, 11, 30, 'não-é eles em-além-de o-Jordão o-caminho-de caminho pôr-de o-sol na-terra o-kenaani o-que-habitava no deserto em-frente-a o-Gilgal junto dos oliveiras instrutor:');
INSERT INTO verses VALUES (5241, 5, 11, 31, 'que vós passando a o-Jordão para entrar para-possuir a a-terra que a-vós Elohim de-vós deu a-vós e herdardes a-ela que nela');
INSERT INTO verses VALUES (5242, 5, 11, 32, 'e-guardareis para-fazer a todo as leis e-a eu que eu o-dia diante-de-vós o-dia');
INSERT INTO chapters VALUES (165, 5, 12, 31);
INSERT INTO verses VALUES (5243, 5, 12, 1, 'Estas as leis e os juízos que guardareis a fazer na-a-terra que dar yhwh Elohim-de os teus pais a-ti para herdar todo os-dias vida vós a-terra sobre a-terra');
INSERT INTO verses VALUES (5244, 5, 12, 2, '[אַבֵּ֣ד] [תְּ֠אַבְּדוּן] a todo [עָֽבְדוּ־שָׁ֣ם] que serviram- nome [יֹרְשִׁ֥ים] eles vós [עַל־הֶהָרִ֤ים] eles a elohim-deles sobre [רַעֲנָן] e-sobre todo árvore');
INSERT INTO verses VALUES (5245, 5, 12, 3, '[וְנִתַּצְתֶּ֣ם] a [וְשִׁבַּרְתֶּם֙] e-vos-partireis a [תִּשְׂרְפ֣וּן] [בָּאֵ֔שׁ] queimar-vos-eis no-fogo [תְּגַדֵּע֑וּן] [וְאִבַּדְתֶּ֣ם] [אֶת־שְׁמָ֔ם] [מִן־הַמָּק֖וֹם] a de o-lugar a-aquela');
INSERT INTO verses VALUES (5246, 5, 12, 4, 'não [כֵּ֔ן] assim a-yhwh Elohim-vosso');
INSERT INTO verses VALUES (5247, 5, 12, 5, 'que se a yhwh que ser-elecionado yhwh Elohim-vosso de-todo [לְשִׁכְנ֥וֹ] להשם a nome-de-ele nome ali');
INSERT INTO verses VALUES (5248, 5, 12, 6, 'vahavetem ali עֹלֹתֵיכֶם vezivcheichem e-את maasorteichem e-a oferta-de yedchem vindreichem vindboiteichem ubokerot bekarkhem e-vosso-rebanho:');
INSERT INTO verses VALUES (5249, 5, 12, 7, 'e-vós-comereis- nome yhwh yhwh Elohim-vosso e-vós-festearéis- em-todo de-vos-lançado- vossas-mãos- vós e-em-vossas-filhas- que yhwh yhwh Elohim-tua');
INSERT INTO verses VALUES (5250, 5, 12, 8, 'não fazeis-vós- conforme-tudo que nos-somos agindo aqui o-dia homem todo o-justo em-seus-olhos');
INSERT INTO verses VALUES (5251, 5, 12, 9, 'que não até [אֶל־הַמְּנוּחָה֙] a [אֲשֶׁר־יְהוָ֥ה] e-a [נֹתֵ֥ן] para-ti yhwh seus-elohim deu para-ti');
INSERT INTO verses VALUES (5252, 5, 12, 10, '[וַעֲבַרְתֶּם֮] a o-Jordão [בָּאָ֔רֶץ] na-terra que yhwh Elohim de-vós [וְהֵנִ֨יחַ] a-vós [מִכָּל־אֹיְבֵיכֶ֛ם] [מִסָּבִ֖יב] de-todo inimigos-vossos ao-redor betach');
INSERT INTO verses VALUES (5253, 5, 12, 11, 'e-foi o-lugar que yhwh yhwh Elohim em-ele para-habitarem nome-dele nome ali trazei a eu que eu ordenando a-vós vosso holocausto e vosso(s) sacrifício(s) e vossas décimas e-tudo de vós e-todo dos melhores nidrechem que tidru para-יהוה');
INSERT INTO verses VALUES (5254, 5, 12, 12, '[וּשְׂמַחְתֶּ֗ם] [לִפְנֵי֮] yhwh Elohim-vossos vocês e-seus-filhos [וּבְנֹ֣תֵיכֶ֔ם] [וְעַבְדֵיכֶ֖ם] [וְאַמְהֹתֵיכֶ֑ם] והלווי que [בְּשֽׁ͏ַעֲרֵיכֶ֔ם] que não-há a-ele uma-parte e herança אִתְּכֶֽם׃');
INSERT INTO verses VALUES (5255, 5, 12, 13, 'hisshamer a-ti para-que-não ta`ale [בְּכָל־מָק֖וֹם] em-todo lugar que você-ver-irá');
INSERT INTO verses VALUES (5256, 5, 12, 14, 'que se no lugar yhwh será escolhido yhwh em um dos seus tribos nome subirá as suas holocaustos וְשָׁם faça eu que eu conforme a vossa ordem:');
INSERT INTO verses VALUES (5257, 5, 12, 15, 'somente em-todo a vaca nafshecha vós ofereceréis e-comerás בָּשָׂר כְּבִרְכַּת yhwh Elohim-teu que deu a-ti em-todo שְׂעָרֶיךָ הַטָּמֵא וְהַטָּהוֹר יֹאכְלוּ כַּצְּבִי וְכָאַיָל׃');
INSERT INTO verses VALUES (5258, 5, 12, 16, 'somente o-sangue não comereis sobre a-terra será derramado nele כַּמַּיִם׃');
INSERT INTO verses VALUES (5259, 5, 12, 17, 'não [לֶאֱכֹ֣ל] para-a-c-hol [מַעְשַׂ֤ר] [דְּגָֽנְךָ֙] [וְתִֽירֹשְׁךָ֣] e-vinho-teu [וּבְכֹרֹ֥ת] [בְּקָרְךָ֖] [וְצֹאנֶ֑ךָ] [וְכָל־נְדָרֶ֙יךָ֙] e-todo [תִּדֹּ֔ר] que [וּתְרוּמַ֥ת] [יָדֶֽךָ] יָדֶֽךָ׃');
INSERT INTO verses VALUES (5260, 5, 12, 18, 'que se yhwh yhwh Elohim-teu [בַּמָּקוֹם֙] בַּמָּקוֹם֙ que yhwh yhwh os-teus-elohim tu אתה וּבִנְךָ֤ וּבִתֶּ֙ךָ֙ ועבדך e a serva-te [אֲשֶׁ֣ר] que nas-tuas-cabeças [לִפְנֵי֙] yhwh yhwh teu-Elohim em-todo enviando יָדֶֽךָ׃');
INSERT INTO verses VALUES (5261, 5, 12, 19, 'hisshamer a-ti para-que-não תעזוב a [עַל־אַדְמָתֶֽךָ׃] todo os teus dias sobre');
INSERT INTO verses VALUES (5262, 5, 12, 20, 'porque yhwh yhwh [אֶֽת־גְּבֽוּלְךָ֮] a [דִּבֶּר־לָךְ֒] como-que falou [בָשָׂ֔ר] [כִּֽי־תְאַוֶּ֥ה] [נַפְשְׁךָ֖] carne porque [בְּכָל־אַוַּ֥ת] alma-tua comerás carne em-todo alma-tua você-comerá carne');
INSERT INTO verses VALUES (5263, 5, 12, 21, 'porque יִרְחַ֨ק מִמְּךָ o-lugar que yhwh yhwh os-teus-elohimes לָשׂ֣וּם שְׁמ֣וֹ nome e sacrificarás de teus rebanhos e de teus rebanhos dar yhwh a-ti para-ti conforme e-comerás e comerás bi-shaarecha em-todo a alma-tua');
INSERT INTO verses VALUES (5264, 5, 12, 22, 'somente como-que será comido a a-beleza e-a o cervo assim o comeréis o impuro e o puro juntos será comido:');
INSERT INTO verses VALUES (5265, 5, 12, 23, 'somente forte para-não comer o-sangue que o-sangue ele a-alma e-não você comerá a-alma com o carne:');
INSERT INTO verses VALUES (5266, 5, 12, 24, 'não vós comereis sobre a-terra תִּשְׁפְּךֶ֖נּוּ como água:');
INSERT INTO verses VALUES (5267, 5, 12, 25, 'não vós comereis para-que será bom a-ti e os filhos tuos de-te porque fazás o-reto yhwh yhwh');
INSERT INTO verses VALUES (5268, 5, 12, 26, 'apenas as santificações que a-ti a-ti e as vossas promessas levá-las-ás e entrá-las-ás a yhwh que será escolhido yhwh');
INSERT INTO verses VALUES (5269, 5, 12, 27, 'e-farás os holocaustos-vossos o carne e o sangue sobre yhwh yhwh teu-Elohim e o sangue- dos teus sacrifícios- yhwh sobre mizbakh comerás teu-Elohim e a carne- comerás');
INSERT INTO verses VALUES (5270, 5, 12, 28, 'שְׁמֹ֣ר e ouvirás- a todo as-palavras estes eu eu que te ordeno- a-fim-de a-ti para ti e-seus-batons depois de ti- que eternidade porque fazes- o-bom yhwh em-olhos-de yhwh Elohim-tua');
INSERT INTO verses VALUES (5271, 5, 12, 29, 'porque yhwh yhwh אֱלֹהִים-teu a tu que tu veio para-aí para-possuir eles de-diante-de-você e herdarias- a-eles e-habitarás na sua terra∶');
INSERT INTO verses VALUES (5272, 5, 12, 30, 'hisshamer a-ti para-que-não te enterrarias- de-elles atrás-de הִשָׁמְדָ֣ם de-diante-de-você e-não-que dizendo לֵֽאלֹהֵיהֶ֜ם dizendo אֵיכָ֨ה יַעַבְד֜וּ הַגּוֹיִ֤ם estes a a-ti וְאֶעֱשֶׂה־ dizendo também eu');
INSERT INTO verses VALUES (5273, 5, 12, 31, 'não farás assim a-yhwh que porque yhwh תּוֹעֲבַ֨ת yhwh que odiou que לֵאלֹ֣הֵיהֶ֔ם porque também a os-filhos-deles e-a בְּנֹ֣תֵיהֶ֔ם יִשְׂרְפ֥וּ em-chamas para os seus elohim:');
INSERT INTO chapters VALUES (166, 5, 13, 19);
INSERT INTO verses VALUES (5274, 5, 13, 1, 'a todo a-palavra eu eu ordenando ele ele guardem laasot não acrescentes sobre-ele nós subtraias de-nós');
INSERT INTO verses VALUES (5275, 5, 13, 2, 'porque arise em-a-vossa-interior profeta ou sonhador sonho e colocou a-ti sinal ou milagre:');
INSERT INTO verses VALUES (5276, 5, 13, 3, 'e vindo o sinal e o milagre que palavra dizendo dizendo נֽ͏ֵלְכָ֞ה apos Elohim אֲחֵרִ֛ים que não יְדַעְתָּ֖ם וְנָֽעָבְדֵֽם׃');
INSERT INTO verses VALUES (5277, 5, 13, 4, 'não [תִשְׁמַ֗ע] a palavras-de הַנָּבִ֣יא aquele ou a [הַה֑וּא] que o-aquele yhwh [אֱלֹֽהֵיכֶם֙] yhwh para-conhecer vos para-saber [אֶת־יְהוָ֣ה] [Elohim] a yhwh elohim-vos em-todo nosso coração e-em-todo nossas almas:');
INSERT INTO verses VALUES (5278, 5, 13, 5, 'apos yhwh Elohim-vosso andareis e-aquele-o temereis e-a suas-m Mandamentos guardareis e-no-sua-voz ouvireis e-a-ele servireis ובו e-adherireis:');
INSERT INTO verses VALUES (5279, 5, 13, 6, 'e o profeta o-hu ou que sonha o sonhador o-aquele morre que disse Sara sobre yhwh vosso Elohim o que vos trouxe vós da-terra Egito e te expulsou de-casa-de serviço- para te afastar de a-de-ré-kh yhwh ordenou-te yhwh teu-Elohim para-andar nela e arderás a-má do-teu-interno');
INSERT INTO verses VALUES (5280, 5, 13, 7, 'que ele te tentará seu irmão filho-de sua mãe ou seu filho ou seu filha ou mulher-de seu companheiro ou seu amigo que dizendo em segredo dizendo vamos e adoraremos Elohim não que tu soubeste tu e vossos pais:');
INSERT INTO verses VALUES (5281, 5, 13, 8, 'de elohimes dos povos que ao-voltar-vos os-que-estão-próximos a-ti ou os-que-estão-longínquos de-vós do-fim a-terra e-até a-terra a-terra');
INSERT INTO verses VALUES (5282, 5, 13, 9, 'não a-ele a-ele e-não a-ele a-ela e-não [עָלָ֔יו] [וְלֹֽא־תַחְמֹ֥ל] sobre-ele e-não e-não sobre-ele');
INSERT INTO verses VALUES (5283, 5, 13, 10, 'que [הָרֹג֙] [תַּֽהַרְגֶ֔נּוּ] [יָ֥דְךָ֛] será- nele [לַהֲמִית֑וֹ] [וְיַ֥ד] e-a-mão todo o-povo בָּאַחֲרֹנָה׃');
INSERT INTO verses VALUES (5284, 5, 13, 11, '[וּסְקַלְתּ֥וֹ] בָאֲבָנִ֖ים ומות que [בִקֵּ֗שׁ] [לְהַדִּֽיחֲךָ֙] de-cima-de yhwh teu-Elohim o-que-te-saiu de-terra-de Egito de-casa-de servos');
INSERT INTO verses VALUES (5285, 5, 13, 12, 'e-todo Israel ouvirão [וְלֹֽא־יוֹסִ֣פוּ] e-não יוֹסִ֣פוּ לַעֲשׂ֗וֹת como a palavra o mal este em-te');
INSERT INTO verses VALUES (5286, 5, 13, 13, 'porque ouvires em-uma-de [אֲשֶׁר֩] yhwh yhwh Elohim-teu a-ti para-ti para-habitar dizendo para-dizer');
INSERT INTO verses VALUES (5287, 5, 13, 14, '[יָצְא֞וּ] homens filhos-de [מִקִּרְבֶּ֔ךָ] [וַיַּדִּ֛יחוּ] [אֶת־יֹשְׁבֵ֥י] a dizendo Urãm dizendo andemos [אֲחֵרִ֖ים] Elohim outros que não יְדַעְתֶּֽם׃');
INSERT INTO verses VALUES (5288, 5, 13, 15, 'וְדָרַשְׁתָּ֧ e procuraste e perguntaste faça-a boa e-eis verdade firme a-palavra será feita a abominação a-esta dentro de ti');
INSERT INTO verses VALUES (5289, 5, 13, 16, 'atinge atingas a a-cidade à-boca-de espada que seja anátema ela e-a todo que בָּ֛הּ e-a בְּהֶמְתָּ֖הּ à-boca-de espada');
INSERT INTO verses VALUES (5290, 5, 13, 17, 'e-a todo [אֶל־תּ֣וֹךְ] [רְחֹבָהּ֒] a meio-de [אֶת־הָעִ֤יר] [וְאֶת־כָּל־שְׁלָלָהּ֙] [כָּלִ֔יל] a a-cidade e-a todo eternidade não a-yhwh teu-Elohim וְהָיְתָה֙ Tel eterno não tibaneh ainda');
INSERT INTO verses VALUES (5291, 5, 13, 18, 'e-não [בְּיָדְךָ֛] [מְא֖וּמָה] [מִן־הַחֵ֑רֶם] de o-herem yhwh [מֵחֲר֣וֹן] yhwh de-a-ira [רַחֲמִים֙] [וְרִֽחַמְךָ֣] para-ti [כַּאֲשֶׁ֥ר] [נִשְׁבַּ֖ע] [לַאֲבֹתֶֽיךָ] como-que jurou para os teus pais:');
INSERT INTO verses VALUES (5292, 5, 13, 19, 'que [תִשְׁמַ֗ע] em-voz yhwh teu-Elohim [לִשְׁמֹר֙] a todo eu que o-dia mandado-te o-dia para-fazer yhwh em-olhos-de yhwh Elohim-tua');
INSERT INTO chapters VALUES (167, 5, 14, 29);
INSERT INTO verses VALUES (5293, 5, 14, 1, 'filhos אַתֶּ֔ם a-yhwh vosso-Elohim não [תִתְגֹּֽדְד֗וּ] e-não [קָרְחָ֛ה] entre vossos-olhos [לָמֵֽת]');
INSERT INTO verses VALUES (5294, 5, 14, 2, 'que povo santo tu a-yhwh teu-Elohim [וּבְךָ֞] escolheu yhwh para-ser a-ele לְעַ֣ם סְגֻלָּ֔ה de-toda os-povos que sobre a-terra a-terra');
INSERT INTO verses VALUES (5295, 5, 14, 3, 'não comerás todo תּוֹעֵבָה׃');
INSERT INTO verses VALUES (5296, 5, 14, 4, 'esta os-animais que [תֹּאכֵ֑לוּ] [שׁ֕וֹר] [שֵׂ֥ה] [כְשָׂבִ֖ים] [וְשֵׂ֥ה] [עִזִּֽים]');
INSERT INTO verses VALUES (5297, 5, 14, 5, '[אַיָּ֥ל] [וּצְבִ֖י] [וְיַחְמ֑וּר] [וְאַקּ֥וֹ] [וְדִישֹׁ֖ן] [וּתְא֥וֹ] [וָזָֽמֶר]');
INSERT INTO verses VALUES (5298, 5, 14, 6, 'e-todo animal esmaga-ora esmagou-a e-esmagando-a esmagou duas [מַעֲלַ֥ת] eleva-a gume-da em-animais a-ela comereis-vos');
INSERT INTO verses VALUES (5299, 5, 14, 7, 'porém a não comereis תֹֽאכְלוּ֙ מִמּֽ͏ַעֲלֵ֣י a-geração וּמִמַּפְרִיסֵ֥י הַפַּרְסָ֖ה a-carruagem a o-camelo e-a a-antepe e-a o-coelho não subida ferida eles a-vós não dividiram-se a-vós eles a-vós');
INSERT INTO verses VALUES (5300, 5, 14, 8, 'e-a o-porco-da-sela porque ele cortaram ele e-não ele a-vós ele não de-lhes não não e-em-lhes não tigge''u:');
INSERT INTO verses VALUES (5301, 5, 14, 9, 'a este de-toda de-todo que nas-águas todo que para-ele unha-grande e-unha-pequena comereis-vos');
INSERT INTO verses VALUES (5302, 5, 14, 10, 'e-tudo que não-há para-ele unha-grande não não to-a-chelu ele a-vós para-vocês');
INSERT INTO verses VALUES (5303, 5, 14, 11, 'todo pássaro-de tehorah comereis-vos');
INSERT INTO verses VALUES (5304, 5, 14, 12, 'e-este que não to''chlu deles hannesher ve''haperes va''azniniyah:');
INSERT INTO verses VALUES (5305, 5, 14, 13, 've''hara''ah e-a a-ayáh conforme-sua-espécie lémínah');
INSERT INTO verses VALUES (5306, 5, 14, 14, 'e-a todo conforme-sua-espécie');
INSERT INTO verses VALUES (5307, 5, 14, 15, 'e-את בת há-yé''áná e-a hátachmas e-a conforme-sua-espécie e-a hánez lémínehu');
INSERT INTO verses VALUES (5308, 5, 14, 16, 'a hácós e-a háyanšúf vé-hátinšamet');
INSERT INTO verses VALUES (5309, 5, 14, 17, 'e a queimada e-com a misericordiosa e-a a lançadora');
INSERT INTO verses VALUES (5310, 5, 14, 18, 'e a piedosa e a fúlgida conforme-sua-espécie e a doce e o atilado');
INSERT INTO verses VALUES (5311, 5, 14, 19, 'e-tudo coisa-que-se-arrasta a-ave impuro ele a-vós não serão comidos');
INSERT INTO verses VALUES (5312, 5, 14, 20, 'todo ave puro comereis-vos');
INSERT INTO verses VALUES (5313, 5, 14, 21, 'não comereis todo carne podre para o estrangeiro que nas-árreycha títtnená v''akhláh ou que l''nakhri porque tu santo atá a-yhwh teu-Elohim não sua-mãe g''di sua-mãe mãe-de ele');
INSERT INTO verses VALUES (5314, 5, 14, 22, 'dez t''asur a todo t''vúath זַרְעֶ֑ךָ hayytzéa o-campo ano anos');
INSERT INTO verses VALUES (5315, 5, 14, 23, 'e-comerás em-frente-de yhwh yhwh בַּמָּק֣וֹם que [אֲשֶׁר־יִבְחַר֮] para-acampar שְׁמ֣וֹ nome [מַעְשַׂ֤ר] [דְּגָֽנְךָ֙] תִּֽירֹשְׁךָ֣ [וְיִצְהָרֶ֔ךָ] [וּבְכֹרֹ֥ת] [בְּקָרְךָ֖] [וְצֹאנֶ֑ךָ] para-que [תִּלְמַ֗ד] [לְיִרְאָ֛ה] a yhwh teu-Elohim todo os dias');
INSERT INTO verses VALUES (5316, 5, 14, 24, 'e-quando יִרְבֶּ֨ה מִמְּךָ֜ que não não תוּכַל֘ שְׂאֵתוֹ֒ porque יִרְחַ֤ק de-tu o-lugar yhwh יִבְחַר֙ yhwh teu-Elohim para que nome yhwh ele te bendiga yhwh Elohim-tua');
INSERT INTO verses VALUES (5317, 5, 14, 25, '[וְנָתַתָּ֖ה] bakkasaf [וְצַרְתָּ֤] a-prata em-tua-mão ve-halakhta a o-lugar que yhwh yhwh teu-Elohim em-ele');
INSERT INTO verses VALUES (5318, 5, 14, 26, 'e-darás o prata em-todo que desejarás nafshecha no gado e no rebanho e no vinho e na cevada e em tudo que pedirás-te e-comerás e comearias nome yhwh yhwh teu-Elohim tu tu e em tua casa:');
INSERT INTO verses VALUES (5319, 5, 14, 27, 'וְהַלֵּוִ֥י que não não que porque a-ele para-ele uma-parte e herança contigo');
INSERT INTO verses VALUES (5320, 5, 14, 28, 'de cima,  três dois tirarás a todo dezimo da tua colheita,  aquela aquele e colocarás em teus portões:');
INSERT INTO verses VALUES (5321, 5, 14, 29, 'וּבָ֣א o levita que não-há a-ele parte e herança com-te e o estrangeiro e ó orfão e ó viúva que bi-shaarecha e comerão e se fartarão para-que yhwh yhwh teu-Elohim em-todo obra-de mão-tua que farás');
INSERT INTO chapters VALUES (168, 5, 15, 23);
INSERT INTO verses VALUES (5322, 5, 15, 1, 'depois que sete- dois farás sabáto;');
INSERT INTO verses VALUES (5323, 5, 15, 2, 'וְזֶה֮ palavra הַשְּׁמִטָּה֒ שָׁמַ֗ט todo בַּעַל sua-mão mão-de-ele que יַשֵּׁה בְּרֵעֵ֑הוּ não יִגְוַשׂ a seu-amigo e-a irmão-seu porque chamou שְׁמִיתָ para-יהוה');
INSERT INTO verses VALUES (5324, 5, 15, 3, 'a הַנּוֹכְרִי תִּגְוַשׂ será a-ti para-ti a irmão-teu תַּשְׁמֵט יָדֶֽךָ׃');
INSERT INTO verses VALUES (5325, 5, 15, 4, 'אֶפֶס que não ele-será- em-te pobre porque yhwh יְבָֽרֶכְךָ֙ yhwh yhwh que yhwh teu-Elohim נֹֽתֵן־ para-ti herança para-possuí-la');
INSERT INTO verses VALUES (5326, 5, 15, 5, 'somente se שָׁמ֣וֹעַ תִּשְׁמַ֔ע yhwh yhwh teu-Elohim para-guardar para-fazer a todo eu a-esta o-dia eu mandado-te o-dia');
INSERT INTO verses VALUES (5327, 5, 15, 6, 'porque yhwh Elohim-teu בֵּֽרַכְךָ֔ conforme falou a-ti וְהֽ͏ַעֲבַטְתָּ֞ nações não e-tu não תַעֲבֹ֔ט וּמָֽשַׁלְתָּ֙ בְּגוֹיִ֣ם não וּבְךָ֖ não serão governados׃');
INSERT INTO verses VALUES (5328, 5, 15, 7, 'porque será֩ em ti֨ pobre de um teu-irmão em um porta(s) tua(s) em teu(a) terra(s) que yhwh para-ti não a-ti não te fortalecerás a no teu coração e-não תִקְפֹּץ֙ a יָ֣דְךָ֔ מֵאָחִ֖יךָ הָאֶבְיֽוֹן׃');
INSERT INTO verses VALUES (5329, 5, 15, 8, 'porque פָתֹ֧חַ תִּפְתַּ֛ח a-ele mão-tua a-ele וְהַעֲבֵט֙ תַּעֲבִיטֶ֔נּוּ דֵּ֚י מַחְסֹר֔וֹ a-ele יֶחְסַ֖ר a-ele');
INSERT INTO verses VALUES (5330, 5, 15, 9, 'hisshamer a-ti para-que-não será palavra com dizendo בְלִיַּ֜עַל dizendo קָֽרְבָ֣ה שְׁנַֽת־ הַשֶּׁבַע֮ ano-de הַשְּׁמִטָּה֒ וְרָעָ֣ה עֽ͏ֵינְךָ֗ בְּאָחִ֙יךָ֙ a-ele e-não תִתֵּ֖ן a-ele e chamou sobre-ti a yhwh e-acontecerá em ti pecado;');
INSERT INTO verses VALUES (5331, 5, 15, 10, 'dará dês a-ele e-não mau do-teu-cor a-ele que porque por causa de a-coisa este bendirei-te yhwh teu-Elohim em-todo o teu trabalho e em tudo enviando a tua mão;');
INSERT INTO verses VALUES (5332, 5, 15, 11, 'que não cessará אֶבְי֖וֹן a-terra a-terra eu כֵּ֞ן dizendo mandamentos-teus dizendo פָּ֠תֹחַ תִּפְתַּ֨ח a a-tua-mão לְאָחִ֧יךָ לַעֲנִיֶּ֛ךָ וּלְאֶבְיֹנְךָ בְּאַרְצֶֽךָ׃');
INSERT INTO verses VALUES (5333, 5, 15, 12, 'porque a-ti a ti אָחִ֣יךָ הָֽעִבְרִ֗י ou הָֽעִבְרִיָּ֔ה e o teu servo seis dois e na sétima a sétima libertes-lhe em liberdade de ti');
INSERT INTO verses VALUES (5334, 5, 15, 13, 'e-quando libertes-lhe em liberdade não não libertes-lhe vazios');
INSERT INTO verses VALUES (5335, 5, 15, 14, 'perdoares תַּעֲנִיק a-ele מִצּוֹאֶךָ וּמִגַּרְנֶךָ וּמִיַּקְבֵךָ que בְּרָכְךָ yhwh teu-Elohim tu-darás a-ele');
INSERT INTO verses VALUES (5336, 5, 15, 15, 'וְזָכַרְתָּ que servo הָיִיתָ em-terra-de Egito וַיִּפְדֶּךָ yhwh teu-Elohim sobre eu אָנֹכִי os-seus-mandamentos a o-dia este o-dia');
INSERT INTO verses VALUES (5337, 5, 15, 16, 'e-foi porque diga não não אֵצֵא que porque אֲהֵבְךָ e-a a-ele porque bom para-ele contigo');
INSERT INTO verses VALUES (5338, 5, 15, 17, 'וְלָקַחְתָּ a הַמַּרְצֵ֗עַ וְנָתַתָּ֤ בְאָזְנוֹ֙ וּבַדֶּ֔לֶת a-ti a-ti eternidade eternidade וְאַ֥ף para-serva-tua farás- assim');
INSERT INTO verses VALUES (5339, 5, 15, 18, 'não será-difícil בְעֵינֶ֗ךָ ele a-ele-o חָפְשִׁי֙ que porque מִשְׁנֶה֙ salário aluguel teu servo seis dois yhwh yhwh teu-Elohim em-todo que farás');
INSERT INTO verses VALUES (5340, 5, 15, 19, 'todo o primogênito que nascido em tua pastagem e em teu rebanho o macho  santificarás a-yhwh não não תַּעֲבֹד no primogênito seu-šoréka e-não tagoza em-primogênito zóanekha׃');
INSERT INTO verses VALUES (5341, 5, 15, 20, 'em-frente-de-a yhwh eloheka taokalénunu ano beshana no-lugar- que yhwh tu tu uveiteka׃');
INSERT INTO verses VALUES (5342, 5, 15, 21, 'e-quando nele bo mum pischa ou עִוֵּר todo mal não não תִּזְבַּחֹ a-yhwh Elohim-tua');
INSERT INTO verses VALUES (5343, 5, 15, 22, 'בִּשְׁעָרֶיךָ תֹּאכֲלֶ֑נּוּ הַטָּמֵא וְהַטָּהוֹר juntos כַּצְבִּי וְכָאַיָּל׃');
INSERT INTO verses VALUES (5344, 5, 15, 23, 'somente a não não תֹּאכֶל sobre a-terra תִּשְׁפְּךֶ֖נּוּ כַּמַּיִם׃');
INSERT INTO chapters VALUES (169, 5, 16, 22);
INSERT INTO verses VALUES (5345, 5, 16, 1, 'שָׁמוֹר֙ a novo הָאָבִ֔יב e-farás Pessach a-yhwh que porque em-mês-de הָֽאָבִ֗יב yhwh yhwh Elohim-teu noite noite');
INSERT INTO verses VALUES (5346, 5, 16, 2, 'וְזָבַ֥חְתָּ Pésach para-יהוה teu-Elohim ovelhas וּבָקָ֑ר בַּמָּקוֹם֙ que yhwh yhwh para-fazer-habitar nome-de-ele nome');
INSERT INTO verses VALUES (5347, 5, 16, 3, 'não תֹאכַ֤ל sobre-ele fermentado sete יָמִ֛ים תֹּֽאכַל־ pão não-fermentados que עֹ֑נִי porque בְחִפָּז֗וֹן יָצָ֙אתָ֙ da-terra Egito para-que תִּזְכֹּר֔ a dia צֵֽאתְךָ֙ dias-de tua-vida todo dias-de vidas-tuas');
INSERT INTO verses VALUES (5348, 5, 16, 4, 'e-não a-ti para-ti שְׂאֹ֛ר em-todo גְּבֻלְךָ sete dias e-não יָלִ֣ין de no-dia que תִּזְבַּ֥ח em-olho no-dia dizendo para-a-manhã:');
INSERT INTO verses VALUES (5349, 5, 16, 5, 'não poderas lizboh a o-pascha em-um seus-mil que yhwh para-ti deu para-ti');
INSERT INTO verses VALUES (5350, 5, 16, 6, 'que se a yhwh que ser-elecionado yhwh teu-Elohim para-acampar seu-nome nome você-ofereça a o-páscoa em-olho quando-vir o-sol encontro saída-te de-Egito');
INSERT INTO verses VALUES (5351, 5, 16, 7, 'e assarás e-comerás no lugar que será escolhido yhwh teu-Elohim nele e voltarás em-a-manhã e caminharás para a tenda tua');
INSERT INTO verses VALUES (5352, 5, 16, 8, 'seis-de dias comerás pães peregrinação e-no-dia o-sétimo congregação a-yhwh teu-Elohim não você-fará obra');
INSERT INTO verses VALUES (5353, 5, 16, 9, 'sete [שָׁבֻעֹ֖ת] [תִּסְפָּר־לָ֑ךְ] a-ti [חֶרְמֵשׁ֙] [בַּקָּמָ֔ה] [תָּחֵ֣ל] [לִסְפֹּ֔ר] [שִׁבְעָ֖ה] sete');
INSERT INTO verses VALUES (5354, 5, 16, 10, 'e farás חַ֤ג שָׁבֻעוֹת֙ a-yhwh teu-Elohim מִסַּ֛ת נדבה tua-mao que תתן como-que יברךך yhwh teu-Elohim');
INSERT INTO verses VALUES (5355, 5, 16, 11, 'ושמחת em-frente-de yhwh yhwh אתה tu וביתך ועבדך ואמתך והלווי que bi-shaarecha והגר וְהַיָּת֥וֹם וְהָאַלְמָנָ֖ה que בְּקִרְבֶּ֑ךָ בַּמָּק֗וֹם que יִבְחַר֙ yhwh yhwh para-fazer-habitar nome-de-ele nome');
INSERT INTO verses VALUES (5356, 5, 16, 12, '[וְזָ֣כַרְתָּ֔] porque servo [בְּמִצְרָ֑יִם] em-Egito [וְעָשִׂ֔יתָ] [אֶת־הֽ͏ַחֻקִּ֖ים] a');
INSERT INTO verses VALUES (5357, 5, 16, 13, '[חַ֧ג] [הַסֻּכֹּ֛ת] farás a-ti sete-de dias [בְּאָ֨סְפְּךָ֔] [מִֽגָּרְנְךָ֖] [וּמִיִּקְבֶֽךָ]');
INSERT INTO verses VALUES (5358, 5, 16, 14, 'וְשָׂמַחְתָּ֖ בְּחַגֶּ֑ךָ tu וּבִנְךָ֤ וּבִתֶּ֙ךָ֙ וְעַבְדְּךָ֣ e a serva-te e o levita e o estrangeiro e o órfão e a viúva que em teus portões:');
INSERT INTO verses VALUES (5359, 5, 16, 15, 'sete-de dias celebras-te a-yhwh teu-Elohim no-lugar- que yhwh que porque yhwh yhwh Elohim-teus em-todo as tuas colheitas e-em-todo obra-de mãos-teu serás somente alegre');
INSERT INTO verses VALUES (5360, 5, 16, 16, '[שָׁל֣וֹשׁ] [פְּעָמִ֣ים] [׀] [בַּשָּׁנָ֡ה] todo [כָל־זְכוּרְךָ֜] a faces-de yhwh Elohim-teus בַּמָּקוֹם֙ que [יִבְחָ֔ר] [בְּחַ֧ג] ha-matz-oth e no chag as-sabû''ôt e no chag as sukkot e-não será visto a yhwh yhwh vazios');
INSERT INTO verses VALUES (5361, 5, 16, 17, 'homem como uma dádiva sua-mão como uma bênção yhwh teu-Elohim que deu para-ti');
INSERT INTO verses VALUES (5362, 5, 16, 18, 'juízes e os sotrim darás- a-ti em-todo yhwh que yhwh a-ti deu a-ti para-seus-tribos e-julguem a o-povo que צֶֽדֶק׃');
INSERT INTO verses VALUES (5363, 5, 16, 19, 'não purifiquem não não conhecereis face e-não que suborno porque os-olhos-de olvidareis os-olhos-de חֲכָמִ֔ים וִֽיסַלֵּף palavras-de justos');
INSERT INTO verses VALUES (5364, 5, 16, 20, 'justiça justiça perseguireis para-que viveres e herdarás a a-terra que yhwh para-ti deu para-ti');
INSERT INTO verses VALUES (5365, 5, 16, 21, 'não a-ti para-ti a aserah todo árvore yhwh o altar yhwh teu-Elohim que farás- para-ti');
INSERT INTO verses VALUES (5366, 5, 16, 22, 'e-não a-ti a-ti a coluna que yhwh yhwh אֱלֹהִים-tua');
INSERT INTO chapters VALUES (170, 5, 17, 20);
INSERT INTO verses VALUES (5367, 5, 17, 1, 'não oferecerás a yhwh Elohim-teu boi e a vaca será nele nele מום todo mal que porque yhwh yhwh ele ela');
INSERT INTO verses VALUES (5368, 5, 17, 2, 'porque será achado no meio de ti בְּאַחַ֣ד שְׁעָרֶ֔יךָ que yhwh para-ti deu a-ti homem ou mulher que fará a o-mal em-olhos-de yhwh- teu-Elohim para-passar בְּרִיתֽוֹ׃');
INSERT INTO verses VALUES (5369, 5, 17, 3, 'E-andou [וֽ͏ַיַּעֲבֹד֙] Elohim outros e-prostrou-se a-eles [וְלַשֶּׁ֣מֶשׁ] ou [א֣וֹ] ou para-todo exército-de os-céus que não');
INSERT INTO verses VALUES (5370, 5, 17, 4, 'וְהֻֽגַּד־ a-ti וְשָׁמָ֑עְתָּ וְדָרַשְׁתָּ֣ hei-tev e-eis verdade firme a-palavra ne-eshta ha-to''evah a-esta em-Israel');
INSERT INTO verses VALUES (5371, 5, 17, 5, 've-ho-chezeta a o-homem הַהוּא ou aquela a-mulher ha-hi que asu a had-davar ha-ra o-este a she''ar-ekha a ha-ish ou a a mulher e os esmagou em pedras e-morreram');
INSERT INTO verses VALUES (5372, 5, 17, 6, 'sobre o meu dois testemunhas ou três testemunhas yumath o-morto não será morta sobre o meu um um');
INSERT INTO verses VALUES (5373, 5, 17, 7, 'mão as testemunhas será- בוֹ primeiramente para matá-lo e-a-mão todo o-povo no-último e-queimaste a-má de-te');
INSERT INTO verses VALUES (5374, 5, 17, 8, 'que será-multiplicado de-te palavra para-julgamento entre sangue- -sangue entre julgamento e-entre e-entre pulogem para-a-praga palavras-de altura nas-tuas-cabeças e-te-elevaste e-asceste-te a o-lugar yhwh será-escolhido yhwh teu-Elohim em-ele');
INSERT INTO verses VALUES (5375, 5, 17, 9, 'e-virás a aos-sacerdotes os-levitas e-a será que será em-os-dias os-aqueles a-ti e-relataram para-ti a palavra a-julgamento');
INSERT INTO verses VALUES (5376, 5, 17, 10, 'וְעָשִׂ֗יתָ sobre פִּ֤י a-palavra que a-ti a-ti de o-lugar aquele yhwh יִבְחַ֣ר yhwh וְשָׁמַרְתָּ֣ para-fazer כְּכֹ֖ל que יוֹרֽוּךָ׃');
INSERT INTO verses VALUES (5377, 5, 17, 11, 'sobre [הַתּוֹרָ֜ה] [אֲשֶׁ֣ר] que [וְעַל־הַמִּשְׁפָּ֛ט] e-sobre a-ti que não a-ti [מִן־הַדָּבָ֛ר] não a-ti de [וּשְׂמֹֽאל] que');
INSERT INTO verses VALUES (5378, 5, 17, 12, 'וְהָאִ֞ישׁ que fará para-não לְבִלְתִּ֨י ouviu a o-sacerdote הָעֹמֵ֞ד לְשָׁ֤רֶת nome a yhwh teu-Elohim ou a הַשֹּׁפֵ֑ט וּמֵת֙ o-homem aquele וּבִֽעַרְתָּ֥ a-má מִיִּשְׂרָאֵֽל׃');
INSERT INTO verses VALUES (5379, 5, 17, 13, 'e-todo o-povo יִשְׁמְע֣וּ e irão ver e-não yizidun ainda');
INSERT INTO verses VALUES (5380, 5, 17, 14, 'porque virá a yhwh que yhwh para-ti deu para-ti e herdarás e habitará nela e dirás acusarei sobre-mim rei conforme-toda as-nações que minhas voltas:');
INSERT INTO verses VALUES (5381, 5, 17, 15, 'som tashim sobre-ti rei que ser-escogido yhwh teu-Elohim nele de-meio-de seus-irmãos vós-pondereis sobre-ti rei não podes-te-capaz-de para-dar sobre-ti homem estrangeiro que não ele ela');
INSERT INTO verses VALUES (5382, 5, 17, 16, 'apenas não multiplique-se para-ele cavalos e-não restituir-vos-irá a o-povo Egito-para disse a-vós não e-יהוה disse a-vós não vós-adicionareis para-voltar no-caminho este ainda');
INSERT INTO verses VALUES (5383, 5, 17, 17, 'e-não יַרְבֶּה- a-ele mulheres e-não יָס֖וּר לבבו e-prata não não muito para-ele muito');
INSERT INTO verses VALUES (5384, 5, 17, 18, 'e-foi [כְשִׁבְתּ֔וֹ] sobre trono-de [מַמְלַכְתּ֑וֹ] [וְכָ֨תַב] a-ele a [הַתּוֹרָ֤ה] [הַזֹּאת֙] esta sobre livro-de os-levitas');
INSERT INTO verses VALUES (5385, 5, 17, 19, 'e-foi com-ele וְקָ֥רָא nele todo dias-de חַיָּ֑יו para-que יִלְמַ֗ד לְיִרְאָה֙ a yhwh Elohim-dele para-guardar a todo דִּבְרֵ֞י a instrução esta e-a הַחֻקִּ֥ים estes para-fazer-los');
INSERT INTO verses VALUES (5386, 5, 17, 20, 'para-não רוּם־ לְבָבוֹ֙ מֵֽאֶחָ֔יו וּלְבִלְתִּ֛י ס֥וּר de da-mandamento direita e-esquerda a-fim-de יַאֲרִ֨יךְ ele sobre מַמְלַכְתּ֛וֹ ele e-seus-filhos em-meio-de Israel');
INSERT INTO chapters VALUES (171, 5, 18, 22);
INSERT INTO verses VALUES (5387, 5, 18, 1, 'não será para-os-sacerdotes dos-Levitas todo tribo levi porção e-herança yhwh Israel fogos yhwh e-sua-herança comerão:');
INSERT INTO verses VALUES (5388, 5, 18, 2, 'e-herança não ele-será- a-ele yhwh ele yhwh ele herança-sua conforme falou a-ele');
INSERT INTO verses VALUES (5389, 5, 18, 3, 'e-isto será juízo os-sacerdotes de-junto-de o povo de-junto-de que-sacrificam do-sacrifício se boi se cordeiro vênatan ao-cohên que-plantou e-as-carnes e-a-velha');
INSERT INTO verses VALUES (5390, 5, 18, 4, 'primeira דְּגֽׄנְךָ֜ תִּֽירֹשְׁךָ֣ וְיִצְהָרֶ֗ךָ וְרֵאשִׁ֛ית גֵּ֥ז צֹאנְךָ֖ tu-darás para-ele');
INSERT INTO verses VALUES (5391, 5, 18, 5, 'que nele [בָּחַ֛ר] yhwh teu-Elohim de-todo [לַעֲמֹ֨ד] [לְשָׁרֵ֧ת] [בְּשֵׁם־יְהוָ֛ה] ele yhwh ele todo');
INSERT INTO verses VALUES (5392, 5, 18, 6, 'e-quando [הַלֵּוִ֜י] [מֵאַחַ֤ד] [שְׁעָרֶ֙יךָ֙] [מִכָּל־יִשְׂרָאֵ֔ל] de-todo Israel que ele [בְּכָל־אַוַּ֣ת] nome [אֶל־הַמָּק֖וֹם] em-todo yhwh a que yhwh');
INSERT INTO verses VALUES (5393, 5, 18, 7, 'והשרות בשם yhwh Elohim-dele conforme-toda irmãos-de-ele os-levitas הומדים nome yhwh yhwh');
INSERT INTO verses VALUES (5394, 5, 18, 8, 'porção כ חלק יאכלו'' לבד dos-mesmos sobre os-pais');
INSERT INTO verses VALUES (5395, 5, 18, 9, 'que tu veio a a-terra que yhwh para-ti deu a-ti não aprenda para-fazer detestáveis as-nações ha-hem');
INSERT INTO verses VALUES (5396, 5, 18, 10, 'não será-achado-a em-ti passar seu-filho e-sua-filha no-fogo a-divinador divinações que-consulte e-a-mago e məkhaššaf׃');
INSERT INTO verses VALUES (5397, 5, 18, 11, 'e chōver chāber e šō''al ōv e yiddā''oni e dōreš a os hāmetim׃');
INSERT INTO verses VALUES (5398, 5, 18, 12, 'porque yhwh yhwh Estas fez estes e biglal yhwh os-estes yhwh teu-Elohim morish eles de-diante-tua');
INSERT INTO verses VALUES (5399, 5, 18, 13, '[תָּמִ֣ים] [תִּֽהְיֶ֔ה] povo yhwh teu-Elohim');
INSERT INTO verses VALUES (5400, 5, 18, 14, 'que as-nações estes que tu tu a-eles a [אֶל־מְעֹנְנִ֥ים] e-a [יִשְׁמָ֑עוּ] [וְאַתָּ֕ה] não não assim a-ti yhwh teu-Elohim');
INSERT INTO verses VALUES (5401, 5, 18, 15, 'profeta [מִקִּרְבְּךָ֤] [מֵאַחֶ֙יךָ֙] [כָּמֹ֔נִי] [יָקִ֥ים] a-ti yhwh teu-Elohim a-ele [תִּשְׁמָעֽוּן]');
INSERT INTO verses VALUES (5402, 5, 18, 16, 'como-todo que pediste yhwh yhwh Elohim-teu em-choreve em-dia dizendo não não eu-recolher-ei para-ouvir yhwh voz yhwh meu-Elohim e-a a-fogo o-grande esta não eu-ver-ei a-ele e-não morrer-ei:');
INSERT INTO verses VALUES (5403, 5, 18, 17, 'E-disse yhwh a-mim melhoraram que diguem-vos');
INSERT INTO verses VALUES (5404, 5, 18, 18, 'profeta eu-levantarei a-eles de-meio-de irmaos-deles como-tu e-darei minhas-palavras em-seu-boca וְדִבֶּ֣ר a-eles a todo que Atzavenu:');
INSERT INTO verses VALUES (5405, 5, 18, 19, 'e-foi o-homem que não Yishma'' a דברי que eu Bishmi eu Edros de-com-ele');
INSERT INTO verses VALUES (5406, 5, 18, 20, 'porém Ha''nabi'' que Yazid L''daber palavra Bishmi a que não Tziutiyo L''daber e-que יְדַבֵּ֔ר yhwh Elohim outros e morrerá o nabi a-aquela');
INSERT INTO verses VALUES (5407, 5, 18, 21, 'e-que tu teirim no levavéka eiyka nédāʿ a a-palavra que yhwh se dibró yhwh');
INSERT INTO verses VALUES (5408, 5, 18, 22, 'que yedaber o-profeta em-nome-de yhwh e-não sera a-palavra e-não ele ele a-palavra que yhwh se dibró yhwh bázaddon não o-profeta nós tágur de-nós');
INSERT INTO chapters VALUES (172, 5, 19, 21);
INSERT INTO verses VALUES (5409, 5, 19, 1, 'porque yhwh yhwh Elohim-teu a yhwh que yhwh a-ti deu a-ti a aratzákm e herdaste-os e habitarás em suas cidades e em seus muros;');
INSERT INTO verses VALUES (5410, 5, 19, 2, 'três cidades separarás para-ti no-meio-de tua-terra que yhwh teu-Elohim deu a-ti para-possuí-la');
INSERT INTO verses VALUES (5411, 5, 19, 3, 'farás a-ti o caminho; e dividirás em três a fronteira tua-terra que yhwh yhwh teu-Elohim e-será para-Nus para lá todo assassino:');
INSERT INTO verses VALUES (5412, 5, 19, 4, 'וְזֶה֙ palavra הָרֹצֵ֔חַ que יָנ֥וּס para lá וָחָ֑י que יַכֶּ֤ה a seu-proximo em-bilí- a-ele e-ele não odiou para-ele מִתְּמֹ֥ל anteontem');
INSERT INTO verses VALUES (5413, 5, 19, 5, 'וַאֲשֶׁר֩ יָבֹ֨א a רֵעֵ֥הוּ בַיַּעַר֮ para escrever madeiras- sua-mão sua-mão no jardim a-árvore o-arvore e tirou o ferro de o-arvore e achou ele seu-proximo ומות ele salvado a uma as cidades- estes e-viveu');
INSERT INTO verses VALUES (5414, 5, 19, 6, 'para-que-não perseguirá vindicador o-sangue depois-de o-matar porque aquecer-se-á no-seu-coração e-o-açogel porque multiplicar-se-á o-caminho e-o-bater-lhe alma que não julgamento-do ele a-ele não odiou ele para-ele de-ontem terceiro-dia');
INSERT INTO verses VALUES (5415, 5, 19, 7, 'sobre eu eu dizendo dizendo três cidades para-ti');
INSERT INTO verses VALUES (5416, 5, 19, 8, 'e-se yhwh yhwh Elohim-teu a fronteira-teu-a como-que jurou a-ti e-o-dar para-ti a todo a-terra que palavra a-dar para os teus pais:');
INSERT INTO verses VALUES (5417, 5, 19, 9, 'porque guarda a todo a lei eu para a fazer o-dia eu que te foi ordenado hoje para-amar a yhwh Elohim-teu a-ti nos seus caminhos todo os-dias sobre para-ti ainda três cidades sobre as três as estas');
INSERT INTO verses VALUES (5418, 5, 19, 10, 'e-não será derramada sangue נָקִי em-meio-de tua-terra que yhwh teu-Elohim deu a-ti herança e-acontecerá sobre-ti דּוֹמִים׃');
INSERT INTO verses VALUES (5419, 5, 19, 11, 'e-quando será homem odiou para-o-amigo a-ele a-ele e-levou-se sobre-ele e-mo-bateu-lhe alma ומות e-salvou-o a uma as-cidades הָאֵֽל׃');
INSERT INTO verses VALUES (5420, 5, 19, 12, 'e-enviaram-no anciãos-de sua-cidade e-levaram-no ele de-lá ve-natenu ele na-mão גּוֹאֵל o-sangue e-morreu');
INSERT INTO verses VALUES (5421, 5, 19, 13, 'não pouparas עֵינֶֽךָ֖ sobre-ele וּבִעַרְתָּ֧ דַֽם־ הַנָּקִ֛ para-ti e-bom para-ti');
INSERT INTO verses VALUES (5422, 5, 19, 14, 'não [תַסִּיג֙] território [רֽ͏ֵעֲךָ֔] que [גָּבְל֖וּ] [רִאשֹׁנִ֑ים] [בְּנַחֲלָֽתְךָ֙] que [תִּנְחַ֔ל] na-a-terra que yhwh teu-Elohim deu a-ti para-possuí-la');
INSERT INTO verses VALUES (5423, 5, 19, 15, 'não [עֵ֨ד] um um [לְכָל־עָוֺן֙] para-todo [בְּכָל־חֵ֖טְא] e-para-todo- [יֽ͏ֶחֱטָ֑א] em-todo [׀] que [עֵדִ֗ים] sobre [עַל־פִּ֥י] segundo [יָק֥וּם] ou sobre palavra');
INSERT INTO verses VALUES (5424, 5, 19, 16, 'porque [עֵד־חָמָ֖ס] até violência [בּ֖וֹ] [סָרָֽה]');
INSERT INTO verses VALUES (5425, 5, 19, 17, 'e se levantem dois os-homens que a-eles yhwh diante-de yhwh diante-de os-sacerdotes e os juízes que serão nos dias ha-hem');
INSERT INTO verses VALUES (5426, 5, 19, 18, 'e busquem e os juízes façam bem e-eis até mentira o testemunho שֶׁׁקֶר respondeu a seu irmão:');
INSERT INTO verses VALUES (5427, 5, 19, 19, 'e fareis a-ele como conspirou para fazer contra seu irmão e o matarás a-má do-teu-interno');
INSERT INTO verses VALUES (5428, 5, 19, 20, 'e-os-restantes ouvirão e temerão e-não continuarão a fazer ainda como a palavra o mal este em-te');
INSERT INTO verses VALUES (5429, 5, 19, 21, 'e-não olhes nos-teus-olhos alma em-alma olho em-olho na-mente em-mente mão em-mão perna em-perna');
INSERT INTO chapters VALUES (173, 5, 20, 20);
INSERT INTO verses VALUES (5430, 5, 20, 1, 'porque sairá para-a-marcha-de-guerra sobre os-teus-inimigos e-verás cavalo e-carruagem povo não de-te não temer-te-iras deles porque yhwh Elohim-teu contigo o-teu-poder dizendo Egito');
INSERT INTO verses VALUES (5431, 5, 20, 2, 'e-será como-vos a a-guerra e-avançar-se-á o-sacerdote וְדִבֶּ֥ר a o-povo');
INSERT INTO verses VALUES (5432, 5, 20, 3, 'e-disse para-eles ouviu Israel vós קְרֵבִ֥ים o-dia para-a-guerra sobre אֹיְבֵיכֶ֑ם a יֵרַ֣ךְ para-coracoes-vos a תִּֽירְא֧וּ e-a תַּחְפְּז֛וּ e-a תּֽ͏ַעַרְצ֖וּ de-faces-deles');
INSERT INTO verses VALUES (5433, 5, 20, 4, 'que yhwh Elohim-vosso o-que-vai com-vós para-lutar a-vós com אֹיְבֵיכֶ֖ם lehoshiaבa a-vós');
INSERT INTO verses VALUES (5434, 5, 20, 5, 'וְדִבְּר֣וּ הַשֹֽׁוטְרִים֮ a dizendo dizendo quem edificar que בנה casa-de novo e-não חנך-o ira e-ele-voltará לבית-ו para-que-não morrera na-guerra e-homem outro יחנך-ו׃');
INSERT INTO verses VALUES (5435, 5, 20, 6, 'ומי- האישׁ que נטע כרם e-não חללו-ו ira e-ele-voltará לבית-ו para-que-não morrera na-guerra e-homem outro profanará');
INSERT INTO verses VALUES (5436, 5, 20, 7, 'ומי- האישׁ que ê-erâš mulher e-não ele-a-tomou ira e-ele-voltará לבית-ו para-que-não morrera na-guerra e-homem outro yiqkâneh');
INSERT INTO verses VALUES (5437, 5, 20, 8, 've-yasfû hashtôrîm para-falar a o-povo e-diretriz quem o-homem o-teme verakh hallebâb ira e-ele-voltará para-sua-casa e-não irá-moçar a coração seus-irmãos como-seu-coração:');
INSERT INTO verses VALUES (5438, 5, 20, 9, 'e será como-ela-foi os-oficiais para-falar a o-povo príncipes-de de-exércitos no-começo o-povo');
INSERT INTO verses VALUES (5439, 5, 20, 10, 'porque vir-se-ao a cidade para-lutar sobre-ela e-lerás para-ela em-paz');
INSERT INTO verses VALUES (5440, 5, 20, 11, 'e-foi se שָלוֹם ouvi-te para-ti a-ti e-será todo o-povo a-ti ב-הּ serao a-ti toca-lhe e-servi-te:');
INSERT INTO verses VALUES (5441, 5, 20, 12, 'e-se não satisfazes contigo e fará contigo guerra e comprimirá');
INSERT INTO verses VALUES (5442, 5, 20, 13, 'e dará yhwh teu-Elohim em-mão-tua e-golpeaste a todo sua memória à-boca-de espada');
INSERT INTO verses VALUES (5443, 5, 20, 14, 'somente as mulheres e os filhos e-o-animal e-tudo que será na cidade todo seu despojo para-ti e-comerás e comerá a despojo dar yhwh deu para-ti teu-Elohim para-ti');
INSERT INTO verses VALUES (5444, 5, 20, 15, 'assim [תַּעֲשֶׂה֙] para-todo [הָרְחֹקֹ֥ת] [מִמְּךָ֖] muito muito que não de-cidades-de');
INSERT INTO verses VALUES (5445, 5, 20, 16, 'somente מערי os-povos estes que yhwh teu-Elohim deu a-ti נחלה não תחיה todo נשמא׃');
INSERT INTO verses VALUES (5446, 5, 20, 17, 'porque החרם תחarrivם o-חִתִּ֤י והאמורי֙ הכנעני e-o-perizeu o-hivi e-o-jebuseu como-que yhwh yhwh Elohim-tua');
INSERT INTO verses VALUES (5447, 5, 20, 18, 'para-que que não [אֶתְכֶם֙] vos para-fazer como-tudo [אֲשֶׁ֥ר] que fizeram [וַחֲטָאתֶ֖ם] [לַיהוָ֥ה] para-יהוה');
INSERT INTO verses VALUES (5448, 5, 20, 19, 'porque תָצ֣וּר a cidade יָמִים רַבִּים לְהִלָּחֵם עָלֶיהָ לְתָפְשָׂהּ não destrua a que nós sobre-ele e afiaste não de-mim que e-o árvore cortarás porque o-homem madeira-de o-campo para entrar de ti diante בְּמָצֽוֹר׃');
INSERT INTO verses VALUES (5449, 5, 20, 20, 'apenas árvore que sabes alimento ele ele alimento ele ele destrua e cortarás e construísti mâцор sobre a-cidade até hî'' fez com ti guerra até ridístha');
INSERT INTO chapters VALUES (174, 5, 21, 23);
INSERT INTO verses VALUES (5450, 5, 21, 1, 'porque será-achado-a chălal na terra yhwh yhwh Elohim-teu a-ti para-ti para-a-posse-de-la caído não não quem quem castiga-o');
INSERT INTO verses VALUES (5451, 5, 21, 2, 'e saíram זְקֵנֶ֖יךָ וְשֹׁפְטֶ֑יךָ וּמָדְדוּ֙ a as-cidades que em-torno-de הֶחָלָֽל׃');
INSERT INTO verses VALUES (5452, 5, 21, 3, 'e-foi a-cidade [הַקְּרֹבָ֖ה] a [וְלָֽקְח֡וּ] [זִקְנֵי֩] [הָעִ֨יר] aquela [עֶגְלַ֣ת] [בָּקָ֗ר] manhã que não servo em-ela que não');
INSERT INTO verses VALUES (5453, 5, 21, 4, 'e ensinai ziquei a-cidade aquela a a egla a vale-de Eitan que não será sacrificado nele e-não sow e despeçam nome a a egla no manancial׃');
INSERT INTO verses VALUES (5454, 5, 21, 5, 'e se aproximaram hakôhânîm filhos-de levi que neles escolheu yhwh Elohim-teu para servir-o e abençoar no-nome-de yhwh e-sobre será será todo dispute e-todo toque');
INSERT INTO verses VALUES (5455, 5, 21, 6, 'e-tudo os anciãos a-cidade aquela os que estão perto a o desossado serão lavados a mãos-deles sobre a cabra o desossado pela torrente');
INSERT INTO verses VALUES (5456, 5, 21, 7, 'responderão e dirão nossas mãos não a do-sangue este e nossos olhos não não');
INSERT INTO verses VALUES (5457, 5, 21, 8, 'כַּפֵּר֩ לְעַמְּךָ֨ Israel que yhwh yhwh e-a dês sangue נָקִי בְּקֶ֖רֶב teu-povo a-eles וְנִכַּפֵּ֥ר a-eles הַדָּֽם׃');
INSERT INTO verses VALUES (5458, 5, 21, 9, 'e-tu [תְּבַעֵ֛ר] [הַדָּ֥ם] [הַנָּקִ֖י] [מִקִּרְבֶּ֑ךָ] porque [הַיָּשָׁ֖ר] o-reto yhwh yhwh');
INSERT INTO verses VALUES (5459, 5, 21, 10, 'porque sairás para-a-guerra sobre yhwh וּנְתָנ֞וֹ yhwh Elohim-teu em-tua-mão e-libertaste de-sí');
INSERT INTO verses VALUES (5460, 5, 21, 11, 'e-vereste em-seu-cativeiro mulher-de fará-te escreveste e-desejaste nela a-ti a-ti para-mulher');
INSERT INTO verses VALUES (5461, 5, 21, 12, 'e-levaste-a a meio-de בֵּיתֶ֑ךָ e-cortaste a sua-cabeça e fará a as asas');
INSERT INTO verses VALUES (5462, 5, 21, 13, 'e removerá a a manta o prêmio de si e se assentará em-a-casa-teu a seu pai e-a sua mãe o mês dias e-achar ken tavoa para-ela a-ti e-será a-ti para-mulher');
INSERT INTO verses VALUES (5463, 5, 21, 14, 'e-será se não chapatzta bah veshalachta-ha lenafsha umakor não timkerenah bakkasaf debaixo תִתְעַמֵּ֣ר em-ela sob que עִנִּיתָֽהּ׃');
INSERT INTO verses VALUES (5464, 5, 21, 15, 'porque תִהְיֶ֨יןָ לְאִ֜ישׁ duas נָשִׁ֗ים הָאַחַ֤ת אֲהוּבָה֙ וְהָאַחַ֣ת שְׂנוּאָ֔ה filhos a-ele filhos אֲהוּבָה֙ e a odiada e será o filho o primogênito ao odiado');
INSERT INTO verses VALUES (5465, 5, 21, 16, 'e-foi em-dia-de herdou-o a filhos-dele a a-ele não a-ele não poderia para primogênito a filho-de a amada sobre face-de filho-de a odiada o primogênito');
INSERT INTO verses VALUES (5466, 5, 21, 17, 'que a o primogênito filho-de a abominada a-ele dar a-ele boca-de dois a-ele que ser encontrado a-ele a-ele ele רֵאשִׁ֣ית onão para-ele משפט a primogênita:');
INSERT INTO verses VALUES (5467, 5, 21, 18, 'porque será filho filho o rebelde e a rebelde não há ouviu seu-pai pai-dele sua-mãe mãe-dele ele a-ele e-não ouvirá a-eles');
INSERT INTO verses VALUES (5468, 5, 21, 19, 'e tomem nele seu-pai e sua mãe e levem ele a anciãos-de cidade-dele e-a portão-de de seu lugar');
INSERT INTO verses VALUES (5469, 5, 21, 20, 'e dirão a anciãos-de sua cidade nossos filhos este insurgente e professor não-ela ouviu com nossa voz זולל וסובא׃');
INSERT INTO verses VALUES (5470, 5, 21, 21, 'ורגםוהוּ todo homens-de êrô em pedras vâmêt e-queimaste a-má מִקִּרְבֶּ֑ךָ e-todo Israel אֵלֶּה יִשְׁמְעוּ וְיִרָֽאוּ׃');
INSERT INTO verses VALUES (5471, 5, 21, 22, 'e-quando será בְאִ֗ישׁ חֵ֛טְא julgamento-do morte ele וְתָלִ֥יתָ a-ele sobre עֵֽץ׃');
INSERT INTO verses VALUES (5472, 5, 21, 23, 'não תָלִ֨ין נִבְלָת֜וֹ sobre a-árvore no-dia קָב֤וֹר תִּקְבְּרֶ֙נּוּ֙ no-dia aquele porque maldição Elohim pendurado yhwh será contaminado a a-ti que yhwh teu-Elohim deu a-ti herança');
INSERT INTO chapters VALUES (175, 5, 22, 29);
INSERT INTO verses VALUES (5473, 5, 22, 1, 'não verás a vaca seu-irmão ou a seu corpo נִדָּחִים e se alegrará deles retornar vos devolverei לְאָחִֽיךָ׃');
INSERT INTO verses VALUES (5474, 5, 22, 2, 'e-se não próximo אחיך a-ti e-não conhecerá e reunirei-o a meio-de seu lar até em-voce até ele irmão-teu a-ele e o trarás a-ele');
INSERT INTO verses VALUES (5475, 5, 22, 3, 'e também farás do seu burro e-assim farás para sua túnica e-assim para-todo perda אחיך que nós dele não não poderas para se espantar');
INSERT INTO verses VALUES (5476, 5, 22, 4, 'não vês a חֲמ֨וֹר seu-irmão ou seu burro caindo-s em-a-caminho e te espantes deles e-levantem תקים com-ele');
INSERT INTO verses VALUES (5477, 5, 22, 5, 'não sera כלי- גבר- sobre mulher e-não que gever yhwh mulher porque Estas yhwh teu-Elohim todo fez Estas');
INSERT INTO verses VALUES (5478, 5, 22, 6, 'que será-chamada KEN- ציפור- לפניך- BADREK- em-todo עץ- ou sobre a-terra אפרוחים- ou ביצים- e a ave que se encontra sobre as crias ou sobre os ovos não a-ti a ave sobre os filhotes:');
INSERT INTO verses VALUES (5479, 5, 22, 7, 'enviou lançará a a ave e-a הַבָּנִים tiqqa''·- para-ti a-fim-de melhor yhwh e alongará dias');
INSERT INTO verses VALUES (5480, 5, 22, 8, 'que [תִבְנֶה֙] casa novo e-farás [מַעֲקֶ֖ה] [לְגַגֶּ֑ךָ] e-não [דָּמִים֙] [בְּבֵיתֶ֔ךָ] [כִּֽי־יִפֹּ֥ל] porque nós');
INSERT INTO verses VALUES (5481, 5, 22, 9, 'não תִזְרַ֥ע תזרע כַּרְמְךָ֖ כרםך כִּלְאָ֑יִם כלאים para-que-não תִּקְדַּ֗שׁ תקדש a plenitude o semente que serás semeadas e colhidas o vinhedo');
INSERT INTO verses VALUES (5482, 5, 22, 10, 'não serás arados com o burro e com o jumento juntos-verso');
INSERT INTO verses VALUES (5483, 5, 22, 11, 'não serás vestidas com açafrão צֶ֥מֶר וּפִשְׁתּ֖ים juntos-verso');
INSERT INTO verses VALUES (5484, 5, 22, 12, '[גְּדִלִ֖ים] farás- para-ti sobre quatro [אֲשֶׁ֥ר] [תְּכַסֶּה־בָּֽהּ׃] que');
INSERT INTO verses VALUES (5485, 5, 22, 13, 'porque ele-tomará homem mulher [אֵלֶ֖יהָ] para-ela');
INSERT INTO verses VALUES (5486, 5, 22, 14, 'וְשָׂ֥ם a-ela עֲלִילֹ֣ת דְּבָרִ֔ים וְהוֹצִ֥יא sobre-ela nome mal e-dirá a a-mulher esta Eu tomei e aproximei-me a ela e-não encontrei para-ela virgens;');
INSERT INTO verses VALUES (5487, 5, 22, 15, 'e-tome pai-de e sua mãe e levem a virgens a anciãos-de a-cidade haššaʿarah:');
INSERT INTO verses VALUES (5488, 5, 22, 16, 'veamar pai-de a dos anciãos a filha-minha dei para o homem este para a mulher e ela o aborreceu;');
INSERT INTO verses VALUES (5489, 5, 22, 17, 'e-eis אֹн nome עֲלִילוֹת dizendo dizendo não encontrei לְבִתֶּךָ בְּתוּלוֹת e-estes בְּתוּלוֹת בִּתִי וּפָרְשׂוּ הַשִּׂמְלָה diante-de anciãos-de a-cidade');
INSERT INTO verses VALUES (5490, 5, 22, 18, 'anciãos-de העיר- a-essa a o-homem ele ele');
INSERT INTO verses VALUES (5491, 5, 22, 19, 'וְעָנְשׁוּ ele cem prata וְנָתְנוּ para-pai a-moça que tirou nome mal sobre virgem-a Israel e-a-ele sera para-esposa não poderia libertá-la todo seus-dias:');
INSERT INTO verses VALUES (5492, 5, 22, 20, 'e-se ser foi a palavra esta não foram-encontrados virgens');
INSERT INTO verses VALUES (5493, 5, 22, 21, 'e-saquem a a entrada-de casa-de אָבִ֗יהָ e-deram-na-a homens-de sua-coração com-pedras e-morreu porque fizeste insensatez em-Israel para zinar casa seu pai e-queimaste a-má do-teu-interno');
INSERT INTO verses VALUES (5494, 5, 22, 22, 'porque será achado homem dormindo - com mulher na concubina - marido - [הָאִ֛ישׁ] também dois-deles o-homem o que estava deitado com a-mulher e a mulher e-queimaste a-má מִיִּשְׂרָאֵֽל׃');
INSERT INTO verses VALUES (5495, 5, 22, 23, 'que será virgem m''orashá para-homem e achá-la homem na-cidade e deitou-se עִמָּֽהּ׃');
INSERT INTO verses VALUES (5496, 5, 22, 24, 'e saídestes a os dois deles a porta aquela daquela eles a eles em pedras e morreram a sobre palavra que não grito em-a-ir e- o-homem sobre palavra que a-inha a mulher-de companheiro-seu e-queimaste a-má do-teu-interno');
INSERT INTO verses VALUES (5497, 5, 22, 25, 'וְֽאִם־ em-o-sadê ser-encontrado o-homem a a-herança e-pegar- n-a-lha o homem com-ela com-ela e-matar-se o-homem com-ela sozinho com-ela sozinho');
INSERT INTO verses VALUES (5498, 5, 22, 26, 'não farás palavra não-há pecado morte porque como-que levantar-se que sobre seu-proximo e o assassino alma assim a-palavra a-esta');
INSERT INTO verses VALUES (5499, 5, 22, 27, 'que no campo achá-la grito a herança e-não-há salvador a-ela');
INSERT INTO verses VALUES (5500, 5, 22, 28, 'porque ser-achado homem virgem que não herdeira e a prenderá וְשָׁכַ֣ב com-ela וְנִמְצָֽאוּ׃');
INSERT INTO verses VALUES (5501, 5, 22, 29, 'וְ֠נָתַן o-homem הַשֹׁכֵ֥ב com-ela לַאֲבִ֥י cinquenta prata e-a-ele sera para-esposa em-lugar-de debaixo עִנָּ֔הּ não יוּכַ֥ל שַׁלְּחָ֖ה todo seus-dias:');
INSERT INTO chapters VALUES (176, 5, 23, 26);
INSERT INTO verses VALUES (5502, 5, 23, 1, 'não ele-tomará homem seu-pai mulher-de seu-pai e-não seu-pai asa seu-pai');
INSERT INTO verses VALUES (5503, 5, 23, 2, 'não [פְצֽוּעַ־דַּכָּ֛א] [וּכְר֥וּת] [שָׁפְכָ֖ה] [בִּקְהַ֥ל] yhwh yhwh');
INSERT INTO verses VALUES (5504, 5, 23, 3, 'não virá מַמְזֵ֖ר yhwh também também geração עֲשִׂירִ֔י a-ele יָ֥בֹא yhwh yhwh yhwh');
INSERT INTO verses VALUES (5505, 5, 23, 4, 'não יָבֹ֧א עַמּוֹנִ֛י וּמוֹאָבִ֖י yhwh também também geração עֲשִׂירִ֔י a-eles virá yhwh בִּקְהַ֥ל yhwh até eternidade');
INSERT INTO verses VALUES (5506, 5, 23, 5, 'sobre palavra que não [בַּלֶּ֣חֶם] vos [בַּדֶּ֖רֶךְ] [בְּצֵאתְכֶ֣ם] no-caminho [וַאֲשֶׁר֩] de-Egito [עָלֶ֜יךָ] [אֶת־בִּלְעָ֣ם] [בֶּן־בְּע֗וֹר] a [אֲרַ֥ם] filho-de [לְקַֽלְלֶֽךָּ]');
INSERT INTO verses VALUES (5507, 5, 23, 6, 'e-não yhwh yhwh Elohim-teu para-ouvir a yhwh [Elohim] yhwh [אֶת־הַקְּלָלָ֖ה] [לִבְרָכָ֑ה] que [אֲהֵֽבְךָ֖] yhwh porque yhwh');
INSERT INTO verses VALUES (5508, 5, 23, 7, 'não [שְׁלֹמָ֖ם] [וְטֹבָתָ֑ם] [כָּל־יָמֶ֖יךָ] todo');
INSERT INTO verses VALUES (5509, 5, 23, 8, 'não [אֲדֹמִ֔י] que porque ele ele não [מִצְרִ֔י] egípcio porque [בְאַרְצֽוֹ]');
INSERT INTO verses VALUES (5510, 5, 23, 9, 'filhos que a-eles a-eles geração terceiro a-eles a-eles yhwh yhwh');
INSERT INTO verses VALUES (5511, 5, 23, 10, 'porque sairás [עַל־אֹיְבֶ֑יךָ] sobre de-toda [דָּבָ֥ר] mal palavra mau');
INSERT INTO verses VALUES (5512, 5, 23, 11, 'porque sera em-ti homem que não será puro מִקְּרֵה־ noite não a de-fora para-o-machane não vira a dentro-de o-acampamento');
INSERT INTO verses VALUES (5513, 5, 23, 12, 'e-acontecerá לִפְנֽוֹת־ tarde lavará nas-águas וּכְבֹ֣א o-sol vira a dentro-de');
INSERT INTO verses VALUES (5514, 5, 23, 13, 'וְיָד֙ será a-ti fora-de para-o-lager וְיָצָ֥אתָ para lá חווץ:');
INSERT INTO verses VALUES (5515, 5, 23, 14, '[וְיָתֵ֛ד] será a-ti sobre [וְהָיָה֙] e-foi [ח֔וּץ] [וְחָפַרְתָּ֣ה] [בָ֔הּ] nela [וְכִסִּ֥יתָ] [אֶת־צֵאָתֶֽךָ] a');
INSERT INTO verses VALUES (5516, 5, 23, 15, 'que yhwh Elohim-teu passeando em-meio-de [בְּקֶ֣רֶב] [מַחֲנֶ֗ךָ] וְלָתֵ֤ת seus-inimigos∶ diante-de-ti e-acontecerá [וְהָיָ֥ה] santo e-não Verá em-ti nudez-de palavra וְשָׁ֖ב [מֵאַחֲרֶֽיךָ׃]');
INSERT INTO verses VALUES (5517, 5, 23, 16, 'não [עֶ֖בֶד] servo a seu-mestre que yinnatsé''l a-ti de-com אֲדֹנָֽיו׃');
INSERT INTO verses VALUES (5518, 5, 23, 17, 'com-te habitou no-seu-interior em-lugar que será escolhido em-um seus-pés a-ele não não chama-la');
INSERT INTO verses VALUES (5519, 5, 23, 18, 'não תִהְיֶה santa filhas de Israel e-não será santo de-filhos-de Israel');
INSERT INTO verses VALUES (5520, 5, 23, 19, 'não leva eu-darei prostituta e vender cão yhwh yhwh teu-Elohim que voto yhwh abominação yhwh teu-Elohim também dois-deles');
INSERT INTO verses VALUES (5521, 5, 23, 20, 'não enganar para o teu irmão jugo prata jugo comida jugo todo palavra que ישׂךְ׃');
INSERT INTO verses VALUES (5522, 5, 23, 21, '[לַנָּכְרִ֣י] [תַשִּׁ֔יךְ] [וּלְאָחִ֖יךָ] não [תַשִּׁ֑יךְ] para-que [יְבָרֶכְךָ֜] yhwh Elohim-teus em-todo [מִשְׁלַ֣ח] mão-tua sobre a-terra que tu');
INSERT INTO verses VALUES (5523, 5, 23, 22, 'porque [נֶ֙דֶר֙] נֶ֙דֶר֙ a-yhwh não não תְּאָחֵר [כִּֽי־דָרֹ֨שׁ] porque yhwh irá buscá-lo yhwh Elohim-teu de ti e-acontecerá que pecado;');
INSERT INTO verses VALUES (5524, 5, 23, 23, 'e-que te calarás para jurares não será em ti pecado;');
INSERT INTO verses VALUES (5525, 5, 23, 24, 'saída as tuas lábios guardares e farás como-que juraste a-יהוה Elohim-teu oferta voluntária que falaste no teu');
INSERT INTO verses VALUES (5526, 5, 23, 25, 'que vem no vinhedo seu e-comerás uvas como a tua satisfação e-a não não darás;');
INSERT INTO verses VALUES (5527, 5, 23, 26, 'que vem na colheita seu וְקָטַפְתָּ֥ [מְלִילֹ֖ת] em-mão-tua וְחֶרְמֵשׁ֙ não תָנִ֔יף sobre קָמַ֥ת teu-companheiro');
INSERT INTO chapters VALUES (177, 5, 24, 22);
INSERT INTO verses VALUES (5528, 5, 24, 1, 'porque ele-tomará homem mulher [וְהָיָ֞ה] e-será se não [כִּי־מָ֤צָא] [בָהּ֙] [עֶרְוַ֣ת] porque [וְכָ֨תַב] nela [סֵ֤פֶר] palavra [וְנָתַ֣ן] para-ela [וְשִׁלְּחָ֖הּ] [מִבֵּיתֽוֹ]');
INSERT INTO verses VALUES (5529, 5, 24, 2, '[וְיָצְאָ֖ה] [מִבֵּית֑וֹ] [וְהָלְכָ֖ה] e-será [לְאִישׁ־אַחֵֽר]');
INSERT INTO verses VALUES (5530, 5, 24, 3, 'ושנאנה֘ o-homem האחרון֒ וְכָ֨תַב para-ela ספר כריתות e-dava em-mã e a envie de sua casa ou porque morrera o-homem o último que a-ele a-ele para-mulher');
INSERT INTO verses VALUES (5531, 5, 24, 4, 'não podera do seu marido harašôn que e a envie para voltar a-ele a ser a-ele para-esposa depois-de que ela porque yhwh ela diante-de yhwh e-não yhwh a a-terra a-ti yhwh teu-Elohim deu a-ti herança');
INSERT INTO verses VALUES (5532, 5, 24, 5, 'porque ele-tomará homem mulher não não ele sairá para a guerra e-não passará sobre-ele será palavra Naki sera le-beito ano uma ve-simma a ishto que tomou');
INSERT INTO verses VALUES (5533, 5, 24, 6, 'não ya-khavel rekhayim וָרָכֶב ele alma ele kholel');
INSERT INTO verses VALUES (5534, 5, 24, 7, 'porque será-achado-a homem ganev alma me-achav de-filhos-de Israel ve-hit''amar- nele e o vendeu וּמֵת֙ o ladrão aquele e-queimaste a-má do-teu-interno');
INSERT INTO verses VALUES (5535, 5, 24, 8, 'הישמר a lepra- a lepra muito muito e façam como-todo que ensinarão a-vós os-sacerdotes הלוים como ordenaram guardem para-fazer');
INSERT INTO verses VALUES (5536, 5, 24, 9, 'lembrai-vos com que yhwh yhwh teu-Elohim de Miriam no-caminho בּצֵאתְכֶם de-Egito');
INSERT INTO verses VALUES (5537, 5, 24, 10, 'porque [בְרֵֽעֲךָ] [מַשַּׁ֣את] [מְא֑וּמָה] [לֹא־תָבֹ֥א] não entrará a');
INSERT INTO verses VALUES (5538, 5, 24, 11, 'בּח֖וּץ תּוֹאֲמֹד e-o-homem que tu נֹשֶׁה nele יוֹצִיא a-ti a הַעֲבֹט para-a-fora');
INSERT INTO verses VALUES (5539, 5, 24, 12, 'e-se homem ele não não tischab ba''avoto:');
INSERT INTO verses VALUES (5540, 5, 24, 13, 'hashive tashiv a-ele a ha''avot kevoa o-sol veshakab b''shalmato ve''erekhekka ulkha será tsedaka yhwh yhwh Elohim-tua');
INSERT INTO verses VALUES (5541, 5, 24, 14, 'não תַעֲשׁוֺק שׂכִיר afligido וְאֶבְי֑וֹן מֵאַחֶיךָ ou מִגּרְךָ que בּארְצְךָ em teus portões:');
INSERT INTO verses VALUES (5542, 5, 24, 15, 'בּיוֹמוֹ תִתֶן שׂכרֹו e-não תָבוֹא sobre-ele que porque ele ele ele ele נֹשֵא a sua-alma e-não irá sobre-ti a yhwh a-ti que pecado;');
INSERT INTO verses VALUES (5543, 5, 24, 16, 'não serão mortos avós sobre בָּנִים e-filhos não serão mortos sobre אָב֑וֹת בְּחֶטְא֖וֹ serão mortos:');
INSERT INTO verses VALUES (5544, 5, 24, 17, 'não teate juízo forasteiro yatôm e-não tachabol biged אלמנוה');
INSERT INTO verses VALUES (5545, 5, 24, 18, 'וְזָכַרְתָּ que servo הָיִיתָ em-Egito e te livrou yhwh teu-Elohim de-lá sobre eu eu-sou mandamentos-teus para-fazer a a palavra a-esta');
INSERT INTO verses VALUES (5546, 5, 24, 19, 'que tikzor קְצִֽירְךָ֨ בְשָׂדֶ֜ךָ וְשֽׁ͏ָכַחְתָּ֧ עֹ֣מֶר basadeh não תָשׁוּב֙ לְקַחְתּ֔וֹ לַגֵּ֛ר לַיָּת֥וֹם וְלָאַלְמָנָ֖ה será para-que bendirei-te yhwh teu-Elohim em-todo obra-de יָדֶֽיךָ׃');
INSERT INTO verses VALUES (5547, 5, 24, 20, 'que [תַחְבֹּט֙] [זֵֽיתְךָ֔] não [תְפַאֵ֖ר] depois-de-ti [לַגֵּ֛ר] [לַיָּת֥וֹם] [וְלָאַלְמָנָ֖ה] será');
INSERT INTO verses VALUES (5548, 5, 24, 21, 'que [תִבְצֹר֙] [כַּרְמְךָ֔] não [תְעוֹלֵ֖ל] depois-de-ti [לַגֵּ֛ר] [לַיָּת֥וֹם] [וְלָאַלְמָנָ֖ה] será');
INSERT INTO verses VALUES (5549, 5, 24, 22, 'וְזָ֣כַרְתָּ֔ porque servo הָיִ֖יתָ em-terra-de Egito eu כֵּ֞ן eu-sou mandamentos-teus para-fazer a a palavra a-esta');
INSERT INTO chapters VALUES (178, 5, 25, 19);
INSERT INTO verses VALUES (5550, 5, 25, 1, 'porque será entre entre [וְנִגְּשׁ֥וּ] [אֶל־הַמִּשְׁפָּ֖ט] a [וְהִצְדִּ֙יקוּ֙] [אֶת־הַצַּדִּ֔יק] [וְהִרְשִׁ֖יעוּ] a a');
INSERT INTO verses VALUES (5551, 5, 25, 2, 'e será se filho הַכּ֖וֹת הָרָשָׁ֑ע e o arremessará [וְהִכָּ֣הוּ] e-o-bater-lhe diante-dele para a sua iniqüidade em número');
INSERT INTO verses VALUES (5552, 5, 25, 3, 'quarenta o castigará não continuará a para-que-não continuará a o castigá-lo sobre estes castigo multiplicai e será levada irmão-teu para-os-olhos-teus');
INSERT INTO verses VALUES (5553, 5, 25, 4, 'não por causa de bovino no seu deserto');
INSERT INTO verses VALUES (5554, 5, 25, 5, 'porque vivam irmãos juntos e morto um deles e filho não-há a-ele não será esposa-de o morto o-lá-fora a homem-de זָ֑ר a-ele vira sobre-ela e tomada para-ele para mulher e-a-iv-ba-ma-ha');
INSERT INTO verses VALUES (5555, 5, 25, 6, 'e-foi o-primogênito que ta-el-e-da ya-qu-va-ma sobre nome irmão-seu o-morto e-não será apagado tomou מִיִּשְׂרָאֵֽל׃');
INSERT INTO verses VALUES (5556, 5, 25, 7, 'e-se não ya-chaf-pa-tsua o-homem para-tomar a ye-bi-ma-tu-o ve-aa-la-ta-ha ye-bi-ma-tu-o ha-sha-aa-ra-ha a os-anciãos ve-a-am-ra-ha me-e-in meu yibum para estabelecer não nome em-Israel não pai seu yibum:');
INSERT INTO verses VALUES (5557, 5, 25, 8, 'e chamem- a-ele os anciãos- a-ele וְדִבְּר֣וּ a-ela não e ele disse: não חָפַ֖צְתִּי lekachta');
INSERT INTO verses VALUES (5558, 5, 25, 9, 'e se aproximasse sua yibuma a-ele aos-olhos-de os anciãos- e a libertasse seu calçado de-cima-de sua perna e sua coxa ante seus olhos e respondeu e disse assim será feito para-o homem que não ele edificará a casa seu irmão');
INSERT INTO verses VALUES (5559, 5, 25, 10, 'e será chamado nome-de-ele em-Israel casa abre-estrada o calçado:');
INSERT INTO verses VALUES (5560, 5, 25, 11, 'porque serão vencidos homens yachdav homem e seu irmão e se aproximou o-primeiro do único para salvar a espos-a de-mão-de da maldição e estendeu sua mão e segurou בִּמְבֻשָֽׁיו׃');
INSERT INTO verses VALUES (5561, 5, 25, 12, '[וְקַצֹּתָ֖ה] a não não [עֵינֶֽךָ׃]');
INSERT INTO verses VALUES (5562, 5, 25, 13, 'não a-ti para-ti pedra [וָאָ֑בֶן] [גְּדוֹלָ֖ה] [וּקְטַנָּֽה׃]');
INSERT INTO verses VALUES (5563, 5, 25, 14, 'não a-ti para-ti em-casa-tua [וְאֵיפָ֑ה] [גְּדוֹלָ֖ה] [וּקְטַנָּֽה]');
INSERT INTO verses VALUES (5564, 5, 25, 15, 'pedra שְׁלֵמָ֤ה וָצֶ֙דֶק֙ ele-será- para-ti אֵיפָ֧ה שֶׁלֶם וּצֶדֶק sera para-ti para-que sobre יְמֵיכֶם sobre a-terra que para-ti teu-Elohim deu para-ti');
INSERT INTO verses VALUES (5565, 5, 25, 16, 'que [תוֹעֲבַ֛ת] yhwh teu-Elohim todo Estas estes todo fez');
INSERT INTO verses VALUES (5566, 5, 25, 17, 'זָכֹור a que a-ti a-ti עֲמָלֵק no-caminho בְּצֵאתֵיכֶם de-Egito');
INSERT INTO verses VALUES (5567, 5, 25, 18, 'que קָרְךָ֜ no-caminho וַיְזַנֵּב be-ka todo a herança depois de ti e-tu עָיֵ֣ף e ferirá temer temendo Elohim');
INSERT INTO verses VALUES (5568, 5, 25, 19, 'e-será em que puser yhwh o teu Elohim a-vos a-ti teus inimigos מִסָּבִ֗יב na-terra que yhwh o teu Elohim a-ti para-ti herança para-a-posse-de-la será apagada a debaixo-de Amaleque não os-céus não serás esquecida');
INSERT INTO chapters VALUES (179, 5, 26, 19);
INSERT INTO verses VALUES (5569, 5, 26, 1, 'e-foi porque vai a yhwh que yhwh a-ti deu a-ti herança e herdarás e habitarás nela');
INSERT INTO verses VALUES (5570, 5, 26, 2, 'e tomaste do princípio todo fruto a-terra que traga da tua terra que yhwh Elohim-teu deu para-ti וְשׂ-מָתָ֣ em-no ve-halakhta a o-lugar que yhwh yhwh teu-Elohim para-fazer-habitar nome-de-ele nome');
INSERT INTO verses VALUES (5571, 5, 26, 3, 'e-entrarás a o-sacerdote será será em-os-dias os-aqueles a-ele a-ele o-dia o-dia a-yhwh teu-Elohim porque eu-vim- a yhwh que jura yhwh aos nossos pais a-ele para-nós');
INSERT INTO verses VALUES (5572, 5, 26, 4, 'e-tome o-sacerdote em-no do teu lado e o colocará diante-de altar-de yhwh teu-Elohim');
INSERT INTO verses VALUES (5573, 5, 26, 5, 'e responderás e dirás em-frente-de yhwh yhwh arameu perdido pai-meu e-desceu Egito-para e habitou nome em meio a pequena e-foi nome para-povo grande grande e grande:');
INSERT INTO verses VALUES (5574, 5, 26, 6, 'e fizeram-nos a-nós os egípcios e nos afligiram e-eles-distribuíram sobre nós serviço dura-:');
INSERT INTO verses VALUES (5575, 5, 26, 7, 'e clamamos a yhwh Elohim-de nossos-pais yhwh yhwh E-viu nossa-voz E-viu a e nos humilharam e-a nossa toila e-a nos esmagou');
INSERT INTO verses VALUES (5576, 5, 26, 8, 'e nos tirou yhwh do-Egito na mão forte e-com-braco estendida e com medo גדול ובאותות ובמופתים׃');
INSERT INTO verses VALUES (5577, 5, 26, 9, 'ויבאנוּ a o-lugar esta e-ele-deu a-nós terra a-terra a-esta terra fluindo-de leite e-mel');
INSERT INTO verses VALUES (5578, 5, 26, 10, 'e-agora eis [הֵבֵ֙אתִי֙] a fruto a-terra [אֲשֶׁר־נָתַ֥תָּה] a-mim yhwh para-mim yhwh yhwh diante-de yhwh teu-Elohim yhwh diante-de yhwh');
INSERT INTO verses VALUES (5579, 5, 26, 11, 'ושמחתָ֣ em-todo התוב que yhwh para-ti yhwh tu ולביתךָ tu והלווי e-o-estrangeiro que em-te');
INSERT INTO verses VALUES (5580, 5, 26, 12, 'que תכל לַעְשֵׂר a todo מַעְשַׂר תְּבוּאָתְךָ בּשָׁנָה הַשְׁלִישִׁית ano-de הַֽמַּעֲשֵׂר e-darás לַלֵּוִי לַגֵּר לַיָּת֣וֹם וְלֽאַלְמָנָ֔ה e-comerão em-teus-pentes e-terem-sido-nouridos:');
INSERT INTO verses VALUES (5581, 5, 26, 13, 'e-dizer-ás em-frente-de-a yhwh Elohim-teu eu-fiz-a-queimar o-santo de a-casa e-tambem eu-lhe-dêi para-levi e-para-o-habitante para-o-vagabundo e-para-a-mulher-solteira conforme-toda mandamento-te que ordenaste-me não transgredi de-tuas-mandamentos e-não esqueci-me');
INSERT INTO verses VALUES (5582, 5, 26, 14, 'não comi nós de-l-o nós imputei do-que-ele nós e-não dei dele yhwh ouvi em-voz yhwh meu-Elohim fiz que que mandaste-me:');
INSERT INTO verses VALUES (5583, 5, 26, 15, 'olhares-te do-seu-reposeiro santidade-tua de os-céus e-bendigaste a seu-people a-terra Israel deste a-terra que dei-te para-nós terra juraste-te aos-nossos-pais terra fluindo-de leite e-mel');
INSERT INTO verses VALUES (5584, 5, 26, 16, 'o-dia o-este yhwh Elohim-teu מְצַוְּךָ֧ para-fazer a הַחֻקִּ֥ים estes e-a as-julgamentos וְשָׁמַרְתָּ֤ וְעָשִׂ֙יתָ֙ a-eles em-todo do-teu-cor e-em-todo alma-tua');
INSERT INTO verses VALUES (5585, 5, 26, 17, 'a yhwh o-dia o-dia a-ti [לֽ͏ֵאלֹהִ֜ים] [וְלָלֶ֣כֶת] [בִּדְרָכָ֗יו] [וְלִשְׁמֹ֨ר] [חֻקָּ֧יו] [וּמִצְוֺתָ֛יו] [וּמִשְׁפָּטָ֖יו] [וְלִשְׁמֹ֥עַ] [בְּקֹלֽוֹ]');
INSERT INTO verses VALUES (5586, 5, 26, 18, '[וַֽיהוָ֞ה] [הֶאֱמִֽירְךָ֣] o-dia a-ser a-ele [לְעַ֣ם] [סְגֻלָּ֔ה] conforme falou a-ti [כָּל־מִצְוֺתָֽיו] todo');
INSERT INTO verses VALUES (5587, 5, 26, 19, 'וּֽלְתִתְּךָ֣ עֶלְי֗וֹן sobre todo as-nações que fez לִתְהִלָּ֖ה וּלְשֵׁ֣ם וּלְתִפְאָרֶת וְלִֽהְיֹתְךָ֧ com santuário para-יהוה teu-Elohim como-que palavra');
INSERT INTO chapters VALUES (180, 5, 27, 26);
INSERT INTO verses VALUES (5588, 5, 27, 1, 'E-ordenou Moisés e-os-idosos Israel a dizendo dizendo guardar a eu a mandação que o-dia mandando-o vós o-dia');
INSERT INTO verses VALUES (5589, 5, 27, 2, 'e-foi no-dia que transgredireis a o-Jordão a a-terra que para-ti teu-Elohim a-ti a-ti e estabeleceres para-ti eles grandes e cultivares eles nele');
INSERT INTO verses VALUES (5590, 5, 27, 3, 'e escreverás nelas a todo palavras a instrução a-esta em-te para que vá a a-terra que a-ti terra deu para-ti terra que-mana leite yhwh como-que para-ti yhwh Elohim-de os-teus-avós para-ti');
INSERT INTO verses VALUES (5591, 5, 27, 4, 'e-será-que em-vós a o-Jordão ergueis a as-pedras eu que eu o-dia a-vós o-dia em-monte-de Eival e-cultivares eles em-sede');
INSERT INTO verses VALUES (5592, 5, 27, 5, 'edificaste nome altar a-yhwh teu-Elohim altar-de pedras não agitarás sobre-eles ברזל׃');
INSERT INTO verses VALUES (5593, 5, 27, 6, '[אֲבָנִ֤ים] [שְׁלֵמוֹת֙] [תִּבְנֶ֔ה] a yhwh yhwh teu-Elohim [עָלָיו֙] sobre-ele [לַיהוָ֖ה] a-yhwh');
INSERT INTO verses VALUES (5594, 5, 27, 7, 'וזבחת paz e-comerás nome ושמחת diante-de yhwh teu-Elohim');
INSERT INTO verses VALUES (5595, 5, 27, 8, '[וְכָתַבְתָּ֣] sobre [אֶֽת־כָּל־דִּבְרֵ֛י] a todo [בַּאֵ֥ר] [הֵיטֵֽב׃]');
INSERT INTO verses VALUES (5596, 5, 27, 9, 'e-falou Moisés וְהַכֹּהֲנִים os-levitas a todo dizendo dizendo הַסְכָּתֶ֥ךָ ׀ וּשְׁמַע֙ Israel o-dia este נִהְיֵיתָֽ para-povo a-yhwh teu-Elohim');
INSERT INTO verses VALUES (5597, 5, 27, 10, '[וְשָׁ֣מַעְתָּ֔] [בְּק֖וֹל] yhwh teu-Elohim e-farás a [וְאֶת־חֻקָּ֔יו] e-[OBJ] eu que o-dia');
INSERT INTO verses VALUES (5598, 5, 27, 11, 'E-ordenou Moisés a no-dia no-dia dizendo');
INSERT INTO verses VALUES (5599, 5, 27, 12, 'Estas יַעֲמִדוּ para abençoar a o-povo sobre monte-de os-garfos por-vocês a o Jordão Simeão e Levi e-Yehuda וְיִשָׂשכָ֖ר e-José e-Benjamin:');
INSERT INTO verses VALUES (5600, 5, 27, 13, 'e-estes se-manem sobre a-maldição em-monte-de Eival Rúben Gad e-bendito-seja e-Zabulom Dã וְנַפְתָּלִֽי׃');
INSERT INTO verses VALUES (5601, 5, 27, 14, 'e-responda-ao os-levitas a todo homem voz voz alto:');
INSERT INTO verses VALUES (5602, 5, 27, 15, 'maldito o homem que faz-o figura e panela abominação-de yhwh obra mãos-de artífice e pôs em segredo e responderam todo o-povo e-direão amém');
INSERT INTO verses VALUES (5603, 5, 27, 16, 'maldito báculo seu-pai ואימה e-disse todo o-povo amém');
INSERT INTO verses VALUES (5604, 5, 27, 17, 'maldito castigador território companheiro-seu e-disse todo o-povo amém');
INSERT INTO verses VALUES (5605, 5, 27, 18, 'maldito vigilante עִוֵּר בַּדָּ֑רֶךְ e-disse todo o-povo amém');
INSERT INTO verses VALUES (5606, 5, 27, 19, 'maldito מַטֶּה משפט estrangeiro- יָתוֹם וְאַלְמָנָה e-disse todo o-povo amém');
INSERT INTO verses VALUES (5607, 5, 27, 20, 'maldito [שֹׁכֵב֙] com seu-pai que porque [כְּנַ֣ף] seu-pai pai-seu e-disse todo');
INSERT INTO verses VALUES (5608, 5, 27, 21, 'maldito [שֹׁכֵ֖ב] com todo animal e-disse todo');
INSERT INTO verses VALUES (5609, 5, 27, 22, 'maldito [שֹׁכֵב֙] com [בַּת־אָבִ֖יו] filha-de pai-dele ou filha-de mãe-dele todo');
INSERT INTO verses VALUES (5610, 5, 27, 23, 'maldito שֹׁכֵב com no-seu-cunhado e-disse todo o-povo amém');
INSERT INTO verses VALUES (5611, 5, 27, 24, 'maldito מַכֶּה seu-proximo em-secreto e-disse todo o-povo amém');
INSERT INTO verses VALUES (5612, 5, 27, 25, 'maldito tomou suborno para-ferir alma sangue נָקִ֑י e-disse todo o-povo amém');
INSERT INTO verses VALUES (5613, 5, 27, 26, 'maldito que não ergue-se a palavras-de a-tora- a-esta para fazer eles e-disse todo o-povo amém');
INSERT INTO chapters VALUES (181, 5, 28, 69);
INSERT INTO verses VALUES (5614, 5, 28, 1, 'e-foi se ouvinte em-voz yhwh teu-Elohim para-guardar para-fazer a todo eu que o-dia mandado-te yhwh e-dado-te yhwh sobre altíssimo a-terra todo nações-de a-terra');
INSERT INTO verses VALUES (5615, 5, 28, 2, 'e-vieram sobre-te todo as bênçãos estes que porque ouvires yhwh yhwh Elohim-tua');
INSERT INTO verses VALUES (5616, 5, 28, 3, 'bendito tu na-cidade e bendito tu no-campo');
INSERT INTO verses VALUES (5617, 5, 28, 4, 'bendito fruto- do teu ventre e fruto da tua terra e fruto das tuas bestas שַׁגַּר אֲלָפֶיךָ וְעַשׁתְּרֹות zóanekha׃');
INSERT INTO verses VALUES (5618, 5, 28, 5, 'bendito טַנְאַךָ וּמִשְׁאַרְתֶּךָ׃');
INSERT INTO verses VALUES (5619, 5, 28, 6, 'bendito tu בְּבֹאֶךָ וּבָרַכְךָ tu בְּצֵאתֶךָ׃');
INSERT INTO verses VALUES (5620, 5, 28, 7, 'יִתֵּן yhwh a אֹיְבֶיךָ os que se levantam sobre-ti as aspas diante-de-ti um um saírão a-ti [דְרָכִ֖ים] caminhos subirão diante-de-você.');
INSERT INTO verses VALUES (5621, 5, 28, 8, 'ordenará yhwh contigo a a bênção em vossas mãos e em tudo enviada tua-mao e bendigá-lo na-a-terra que yhwh para-ti deu para-ti');
INSERT INTO verses VALUES (5622, 5, 28, 9, 'e erguê-lo yhwh a-ele para o povo santo conforme juro- que porque você guarde yhwh mandamentos-de yhwh teu-Elohim e caminharás nos seus caminhos');
INSERT INTO verses VALUES (5623, 5, 28, 10, 'e vejam todo a-terra que porque yhwh yhwh encontrou-se sobre-ti e temam מִמֶּֽךָּ׃');
INSERT INTO verses VALUES (5624, 5, 28, 11, 'e retém-te yhwh para o bem em frutos בִטְנְךָ֛ וּבִפְרִ֥י וּבִפְרִ֣י אַדְמָתֶ֑ךָ sobre sobre a-terra jura yhwh yhwh para-dar para-ti');
INSERT INTO verses VALUES (5625, 5, 28, 12, 'יִפְתַּ֣ח yhwh a-vos a-ti אוֹצָר֨וֹ הַטּ֜וֹב a os-céus para-dar מְטַֽר־ אַרְצְךָ֙ בְּעִתּ֔וֹ e bendigas a todo obra-de tua-mao e enriquecerás não muitos e-tu não enriquecerás;');
INSERT INTO verses VALUES (5626, 5, 28, 13, 'e darás yhwh ao topo e-não ao rabo serás somente acima e-não será abaixo porque ouvires a yhwh yhwh Elohim-teus eu אָנֹכִי o-dia o-dia לשמור [sem-traducao]');
INSERT INTO verses VALUES (5627, 5, 28, 14, 'e-não [תָס֗וּר] de-todo palavras-as eu eu mandando-o o-dia o-dia direita e-esquerda para-andar depois-de Elohim outros [sem-traducao]');
INSERT INTO verses VALUES (5628, 5, 28, 15, 'e-foi se não [בְּקוֹל֙] yhwh yhwh teu-Elohim para-guardar para-fazer a todo eu [מְצַוְּךָ֖] o-dia eu mandado-te o-dia e-vieram sobre-te todo [sem-traducao] estes [sem-traducao]');
INSERT INTO verses VALUES (5629, 5, 28, 16, 'maldito tu na-cidade [וְאָר֥וּר] tu no-campo');
INSERT INTO verses VALUES (5630, 5, 28, 17, 'maldito [טַנְאֲךָ֖] [וּמִשְׁאַרְתֶּֽךָ]');
INSERT INTO verses VALUES (5631, 5, 28, 18, 'maldito fruto- [וּפְרִ֣י] e fruto אַדְמָתֶ֑ךָ שַׁגַּר אֲלָפֶיךָ וְעַשׁתְּרֹות zóanekha׃');
INSERT INTO verses VALUES (5632, 5, 28, 19, 'maldito tu [בְּבֹאֶ֑ךָ] [וְאָר֥וּר] tu [בְּצֵאתֶֽךָ]');
INSERT INTO verses VALUES (5633, 5, 28, 20, 'ישלח yhwh [׀] a [אֶת־הַמְּאֵרָ֤ה] a [וְאֶת־הַמִּגְעֶ֔רֶת] e-a [יָדְךָ֖] em-todo enviando até que תַּעֲשֶׂ֑ה até de-diante-de e-até [מֽ͏ַעֲלָלֶ֖יךָ] [אֲשֶׁ֥ר] [עֲזַבְתָּֽנִי] mau [sem-traducao] que [sem-traducao]');
INSERT INTO verses VALUES (5634, 5, 28, 21, '[יַדְבֵּ֧ק] yhwh em-te a até até [אֹֽתְךָ֔] de-cima-de de-sobre a-terra que tu veio para lá para-possuí-la');
INSERT INTO verses VALUES (5635, 5, 28, 22, '[יַכְּכָ֣ה] yhwh [בַּשַּׁחֶ֨פֶת] [וּבַקַּדַּ֜חַת] [וּבַדַּלֶּ֗קֶת] [וּבַֽחַרְחֻר֙] [וּבַחֶ֔רֶב] [וּבַשִּׁדָּפ֖וֹן] [וּבַיֵּרָק֑וֹן] [וּרְדָפ֖וּךָ] até [אָבְדֶֽךָ]');
INSERT INTO verses VALUES (5636, 5, 28, 23, 'e-sejam [שָׁמֶ֛יךָ] que sobre [נְחֹ֑שֶׁת] E-a-terra [אֲשֶׁר־תַּחְתֶּ֖יךָ] que');
INSERT INTO verses VALUES (5637, 5, 28, 24, 'dê yhwh a [אַרְצְךָ֖] [אָבָ֣ק] [וְעָפָ֑ר] [מִן־הַשָּׁמַ֙יִם֙] de os-céus até sobre-ti até [sem-traducao]');
INSERT INTO verses VALUES (5638, 5, 28, 25, '[יִתֶּנְךָ֨] yhwh [׀] diante-de [לִפְנֵ֣י] בְּדֶ֤רֶךְ um um para-ele a-ele caminhos [דְרָכִ֖ים] diante-dele [לְפָנָ֑יו] [וְהָיִ֣יתָ] para-todo a-todo a-terra');
INSERT INTO verses VALUES (5639, 5, 28, 26, 'e-será [נִבְלָֽתְךָ֙] para-alimento para-todo ave os-céus a-terra a-terra [מַחֲרִֽיד]');
INSERT INTO verses VALUES (5640, 5, 28, 27, '[יַכְּכָ֨ה] yhwh [בִּשְׁחִ֤ין] Mitzrayim [*ובעפלים] [**וּבַטְ[q]**חֹרִ֔ים] que não poderas [לֹא־תוּכַ֖ל]');
INSERT INTO verses VALUES (5641, 5, 28, 28, '[יַכְּכָ֣ה] yhwh [בְּשִׁגָּע֖וֹן] [וּבְעִוָּר֑וֹן] [וּבְתִמְה֖וֹן] coração');
INSERT INTO verses VALUES (5642, 5, 28, 29, '[וְהָיִ֜יתָ] [מְמַשֵּׁ֣שׁ] [בַּֽצָהֳרַ֗יִם] como-que [יְמַשֵּׁ֤שׁ] [הַעִוֵּר֙] [בָּאֲפֵלָ֔ה] e-não [תַצְלִ֖יחַ] a caminhos-te [אַ֣ךְ] porém [וְגָז֛וּל] [כָּל־הַיָּמִ֖ים] todo os-dias e-não-há [sem-traducao]');
INSERT INTO verses VALUES (5643, 5, 28, 30, 'mulher [תְאָרֵ֗שׂ] e-homem outro casa [**יִשְׁכָּבֶ֔נָּה] e-não תֵשֵׁ֣ב nele carmelo [כֶּ֥רֶם] e-não [וְלֹ֥א]');
INSERT INTO verses VALUES (5644, 5, 28, 31, '[שׁוֹרְךָ֞] [טָב֣וּחַ] [לְעֵינֶ֗יךָ] e-não comerás nós [חֲמֹֽרְךָ֙] [גָּז֣וּל] ante ti e-não ישוב para-ti [צֹֽאנְךָ֙] [נְתֻנ֣וֹת] [לְאֹיְבֶ֔יךָ] e-não-há a-ti [מוֹשִֽׁיעַ]');
INSERT INTO verses VALUES (5645, 5, 28, 32, '[בָּנֶ֨יךָ] [וּבְנֹתֶ֜יךָ] [נְתֻנִ֨ים] [לְעַ֤ם] outro ve-ay-ne-kha [רֹא֔וֹת] [וְכָל֥וֹת] a-eles todo o-dia e-não-há [יָדֶֽךָ] יָדֶֽךָ׃');
INSERT INTO verses VALUES (5646, 5, 28, 33, 'fruto [אַדְמָֽתְךָ֙] e-todo [יֹאכַ֥ל] comera povo que não ידעתי [עָשׁ֥וּק] somente [כָּל־הַיָּמִֽים] [sem-traducao] todo os dias');
INSERT INTO verses VALUES (5647, 5, 28, 34, 'serás [מְשֻׁגָּ֑ע] [מִמַּרְאֵ֥ה] olhos-teus que você-ver-irá');
INSERT INTO verses VALUES (5648, 5, 28, 35, '[יַכְּכָ֨ה] yhwh [בִּשְׁחִ֣ין] mal sobre [וְעַל־הַשֹּׁקַ֔יִם] e-sobre [לֹא־תוּכַ֖ל] que não poderas [וְעַ֥ד] da-mão-de [sem-traducao] e-ate [sem-traducao]');
INSERT INTO verses VALUES (5649, 5, 28, 36, '[יוֹלֵ֨ךְ] yhwh [אֹֽתְךָ֗] e-[OBJ] [אֲשֶׁ֣ר] que [עָלֶ֔יךָ] sobre-ti a nação tu não [וְעָבַ֥דְתָּ] tu e-teus-pais [אֲחֵרִ֖ים] árvore Elohim');
INSERT INTO verses VALUES (5650, 5, 28, 37, '[וְהָיִ֣יתָ] para-a-luz [לְמָשָׁ֖ל] [וְלִשְׁנִינָ֑ה] em-todo os-povos que yhwh yhwh ali');
INSERT INTO verses VALUES (5651, 5, 28, 38, 'semente muito [תּוֹצִ֣יא] o-campo [וּמְעַ֣ט] [תֶּאֱסֹ֔ף] que [יַחְסְלֶ֖נּוּ] o-arvèh:');
INSERT INTO verses VALUES (5652, 5, 28, 39, '[כְּרָמִ֥ים] [תִּטַּ֖ע] [וְעָבָ֑דְתָּ] e vinho não [וְלֹ֣א] e-não que porque [הַתֹּלָֽעַת] [sem-traducao]');
INSERT INTO verses VALUES (5653, 5, 28, 40, '[זֵיתִ֛ים] serao a-ti em-todo teu-limite não não que porque [זֵיתֶֽךָ] [sem-traducao]');
INSERT INTO verses VALUES (5654, 5, 28, 41, 'filhos [וּבָנ֖וֹת] [תּוֹלִ֑יד] e-não para-ti que porque irao [sem-traducao]');
INSERT INTO verses VALUES (5655, 5, 28, 42, 'todo [וּפְרִ֣י] e fruto אַדְמָתֶ֑ךָ [הַצְּלָצַֽ[t]ל]');
INSERT INTO verses VALUES (5656, 5, 28, 43, 'הַגֵּר֙ que [בְּקִרְבְּךָ֔] subia sobre-ti [מַ֣עְלָה] [מָּ֑עְלָה] ve-a-ta-ha [תֵרֵ֖ד] [מַ֥טָּה] [מָּֽטָּה]');
INSERT INTO verses VALUES (5657, 5, 28, 44, 'ele [יַלְוְךָ֔] e-tu não [תַלְוֶ֑נּוּ] ele será [לְרֹ֔אשׁ] e-tu serás [לְזָנָֽב]');
INSERT INTO verses VALUES (5658, 5, 28, 45, 'e-entraram sobre ti todo [הָאֵ֗לֶּה] estes [וְהִשִּׂיג֔וּךָ] até até [כִּי־לֹ֣א] porque não yhwh em-voz yhwh teu-Elohim [וְחֻקֹּתָ֖יו] [אֲשֶׁ֥ר] e-chukkótiav que [sem-traducao]');
INSERT INTO verses VALUES (5659, 5, 28, 46, 'e-sejam em-ti para-sinal [וּלְמוֹפֵ֑ת] [וּֽבְזַרְעֲךָ֖] até eternidade');
INSERT INTO verses VALUES (5660, 5, 28, 47, 'debaixo que não [אֶת־יְהוָ֣ה] a yhwh teu-Elohim [לֵבָ֑ב] [מֵרֹ֖ב] [כֹּֽל] todo');
INSERT INTO verses VALUES (5661, 5, 28, 48, '[וְעָבַדְתָּ֣] a os-teus-inimigos que yhwh sobre-ti em-você [וּבְצָמָ֛א] [וּבְעֵירֹ֖ם] [וּבְחֹ֣סֶר] [כֹּ֑ל] todo e-deu sobre barzel até [הִשְׁמִיד֖וֹ] até [sem-traducao] te:');
INSERT INTO verses VALUES (5662, 5, 28, 49, 'levou yhwh [עָלֶ֨יךָ] nação [מֵרָחוֹק֙] da-extremidade-de a-terra como-que [יִדְאֶ֖ה] [הַנָּ֑שֶׁר] nação que não [לְשֹׁנֽוֹ] [sem-traducao]');
INSERT INTO verses VALUES (5663, 5, 28, 50, 'nação [עַ֣ז] face que não yisa face [וְנַ֖עַר] não não [sem-traducao]');
INSERT INTO verses VALUES (5664, 5, 28, 51, 'e-coma fruto [בְהֶמְתְּךָ֥] [וּפְרִֽי־אַדְמָתְךָ֮] até até [אֲשֶׁ֨ר] que a-ti [דָּגָן֙] para-ti grão תִּירוֹשׁ e-Izar שַׁגַּר אֲלָפֶיךָ até [הַאֲבִיד֖וֹ] até [sem-traducao] te:');
INSERT INTO verses VALUES (5665, 5, 28, 52, '[וְהֵצַ֨ר] a-ti em-todo até até [חֹמֹתֶ֙יךָ֙] [הַגְּבֹה֣וֹת] [וְהַבְּצֻר֔וֹת] [אֲשֶׁ֥ר] tu tu [בָּהֵ֖ן] nelas em-todo a-ti [בְּכָל־שְׁעָרֶ֔יךָ] para-ti em-todo dar yhwh tua-terra para-ti deu yhwh teu-Elohim para-ti');
INSERT INTO verses VALUES (5666, 5, 28, 53, 'e-comerás [פְרִֽי־בִטְנְךָ֗] [בְּשַׂ֤ר] carne filhos-teus e-filhas-tuas que yhwh a-ti yhwh teu-Elohim em-maçor a-ti que a-ti a-ti [sem-traducao]');
INSERT INTO verses VALUES (5667, 5, 28, 54, 'o-homem [הָרַ֣ךְ] a-você [וְהֶעָנֹ֖ג] muito [תֵּרַ֨ע] [עֵינ֤וֹ] [בְאָחִיו֙] [וּבְאֵ֣שֶׁת] [חֵיק֔וֹ] [וּבְיֶ֥תֶר] seus-filhos que [יוֹתִֽיר]');
INSERT INTO verses VALUES (5668, 5, 28, 55, '[מִתֵּ֣ת] [׀] מֵהֶ֗ם [מֵהֶ֗ם] filhos-dele que [אֲשֶׁ֣ר] sem deixar-restar a-ele todo em-maçor e-em-macok que [יָצִ֥יק] a-ti [אֹיִבְךָ֖] em-todo [sem-traducao]');
INSERT INTO verses VALUES (5669, 5, 28, 56, '[הָרַכָּ֨ה] [בְךָ֜] [וְהָעֲנֻגָּ֗ה] que não [כַף־רַגְלָהּ֙] כַף־ [עַל־הָאָ֔רֶץ] [מֵהִתְעַנֵּ֖ג] sobre a-terra [עֵינָהּ֙] [בְּאִ֣ישׁ] [חֵיקָ֔הּ] [וּבִבְנָ֖הּ] em-cada-homem [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (5670, 5, 28, 57, '[וּֽבְשִׁלְיָתָ֞הּ] [הַיּוֹצֵ֣ת] מִבֵּ֣ין [מִבֵּ֣ין] [רַגְלֶ֗יהָ] que ta-el-e-da porque [כִּֽי־תֹאכְלֵ֥ם] [בְּחֹֽסֶר־כֹּ֖ל] todo em segredo em-maçor e-em-macok que a-ti para-ti [בִּשְׁעָרֶֽיךָ] em teus portões:');
INSERT INTO verses VALUES (5671, 5, 28, 58, 'se não [לַעֲשׂ֗וֹת] [אֶת־כָּל־דִּבְרֵי֙] a todo palavras-de [בַּסֵּ֣פֶר] a-esta [לְ֠יִרְאָה] [אֶת־הַשֵּׁ֞ם] esta [וְהַנּוֹרָא֙] a [OBJ] yhwh e-o-terrível a yhwh');
INSERT INTO verses VALUES (5672, 5, 28, 59, '[וְהִפְלָ֤א] yhwh a e-[OBJ] e-[OBJ] [זַרְעֶ֑ךָ] [מַכּ֤וֹת] [גְּדֹלוֹת֙] [וְנֶ֣אֱמָנ֔וֹת] [וָחֳלָיִ֥ם] [רָעִ֖ים] más');
INSERT INTO verses VALUES (5673, 5, 28, 60, '[וְהֵשִׁ֣יב] [בְּךָ֗] a todo [מִצְרַ֔יִם] Egito que [מִפְּנֵיהֶ֑ם] de-face-deles sobre-ti');
INSERT INTO verses VALUES (5674, 5, 28, 61, 'também todo [וְכָל־מַכָּ֔ה] e-todo não que não [הַתּוֹרָ֣ה] בספר hatorah yhwh yhwh até até [sem-traducao]');
INSERT INTO verses VALUES (5675, 5, 28, 62, 'e-vocês-permanecerão em meio a [מְעָ֔ט] debaixo que [הֱיִיתֶ֔ם] como-estrelas-de os-céus em-abundância porque não ouvi-que yhwh yhwh Elohim-tua');
INSERT INTO verses VALUES (5676, 5, 28, 63, 'e será conforme- yhwh yhwh sobre-vocês [אֶתְכֶם֮] a-vós [אֶתְכֶם֒] vós assim yhwh yhwh sobre-vós [אֶתְכֶ֖ם] vos [אֶתְכֶ֑ם] a-vós de-cima-de de-sobre a-terra que tu veio para lá para-possuí-la');
INSERT INTO verses VALUES (5677, 5, 28, 64, '[וֶהֱפִֽיצְךָ֤] yhwh em-todo os-povos a-terra a-terra a-terra fim a-terra e-servirás nome Elohim [לֹא־יָדַ֛עְתָּ] tu não árvore tu [sem-traducao] árvore e-rocha;');
INSERT INTO verses VALUES (5678, 5, 28, 65, '[וּבַגּוֹיִ֤ם] aqueles não [תַרְגִּ֔יעַ] e-não será descanso para-planta-de yhwh a-ti yhwh para-ti nome coração [עֵינַ֖יִם] [וְדֽ͏ַאֲב֥וֹן] [נָֽפֶשׁ] [sem-traducao] alma');
INSERT INTO verses VALUES (5679, 5, 28, 66, 'e-sejam tua-vida [תְּלֻאִ֥ים] a-ti [מִנֶּ֑גֶד] [וּפָֽחַדְתָּ֙] noite [וְיוֹמָ֔ם] e-não [תַאֲמִ֖ין] [בְּחַיֶּֽיךָ]');
INSERT INTO verses VALUES (5680, 5, 28, 67, '[בַּבֹּ֤קֶר] dirás quem tarde tarde [תֹּאמַ֖ר] [מִֽי־יִתֵּ֣ן] manhã dará manhã [אֲשֶׁ֣ר] [תִּפְחָ֔ד] que [עֵינֶ֖יךָ] [אֲשֶׁ֥ר] olhos-teus que você-ver-irá');
INSERT INTO verses VALUES (5681, 5, 28, 68, '[וֶֽהֱשִֽׁיבְךָ֨] yhwh Egito [מִצְרַיִם֮] no-caminho que [אֲשֶׁ֣ר] a-ti a-ti תֹסִ֥יף ainda [לִרְאֹתָ֑הּ] [וְהִתְמַכַּרְתֶּ֨ם] nome [לְאֹיְבֶ֛יךָ] לַעֲבָדִ֥ים [וְלִשְׁפָח֖וֹת] e-não-há [קֹנֶֽה׃]');
INSERT INTO verses VALUES (5682, 5, 28, 69, 'Estas [דִבְרֵ֨י] [הַבְּרִ֜ית] que yhwh yhwh a Moisés [יִשְׂרָאֵ֖ל] a filhos-de Israel em-terra-de Moabe [אִתָּ֖ם] a-aliança que');
INSERT INTO chapters VALUES (182, 5, 29, 28);
INSERT INTO verses VALUES (5683, 5, 29, 1, 'E-chamou Moisés a E-disse Israel E-disse a-eles vós vistes a yhwh que fez yhwh [לְפַרְעֹ֥ה] em-terra-de Egito para-Faraó e-para-todo- servos-dele e-para-todo- terra-dele');
INSERT INTO verses VALUES (5684, 5, 29, 2, '[הַמַּסּוֹת֙] [הַגְּדֹלֹ֔ת] que Ra''u teus-olhos [הָאֹתֹ֧ת] [וְהַמֹּפְתִ֛ים] os-grandes ha-hem');
INSERT INTO verses VALUES (5685, 5, 29, 3, 'e-não yhwh a-vós para-vós para-conhecer [וְעֵינַ֥יִם] para-ver para-ver [לִשְׁמֹ֑עַ] até o-dia o-dia');
INSERT INTO verses VALUES (5686, 5, 29, 4, 'e-o-olékh a-vós quarenta ano no-deserto não [שַׂלְמֹֽתֵיכֶם֙] [מֵעֲלֵיכֶ֔ם] [וְנַֽעַלְךָ֥] [לֹֽא־בָלְתָ֖ה] de-cima-de [רַגְלֶֽךָ] de-sobre [sem-traducao]');
INSERT INTO verses VALUES (5687, 5, 29, 5, 'pão não [אֲכַלְתֶּ֔ם] e-vinho [וְשֵׁכָ֖ר] não [שְׁתִיתֶ֑ם] a-fim-de [תֵּֽדְע֔וּ] que eu yhwh Elohim-vosso');
INSERT INTO verses VALUES (5688, 5, 29, 6, 'e vieram a o-lugar esta e-saiu סִיחֹ֣ן rei-de [מֶֽלֶךְ־הַבָּשָׁ֧ן] [לִקְרָאתֵ֛נוּ] rei-de [וַנַּכֵּֽם] [sem-traducao] que [sem-traducao]');
INSERT INTO verses VALUES (5689, 5, 29, 7, '[וַנִּקַּח֙] a terra-deles [לְנַחֲלָ֔ה] [לָרֽאוּבֵנִ֖י] para-reuveni e-para-gadi e-para-metade-de bastão [sem-traducao]');
INSERT INTO verses VALUES (5690, 5, 29, 8, 'ushamartem a palavras-de a aliança a-esta eles a-eles para-que [OBJ] a todo que vós-fareis');
INSERT INTO verses VALUES (5691, 5, 29, 9, 'vós [נִצָּבִ֤ים] o-dia [כֻּלְּכֶ֔ם] diante-de yhwh vosso-Elohim [רָאשֵׁיכֶ֣ם] tribos-vossas [זִקְנֵיכֶם֙] [וְשֹׁ֣טְרֵיכֶ֔ם] todo homem Israel');
INSERT INTO verses VALUES (5692, 5, 29, 10, '[טַפְּכֶ֣ם] neshechem [וְגֵ֣רְךָ֔] que em-meio-de [מַחֲנֶ֑יךָ] [מֵחֹטֵ֣ב] [עֵצֶ֔יךָ] até [שֹׁאֵ֥ב] [מֵימֶֽיךָ]');
INSERT INTO verses VALUES (5693, 5, 29, 11, '[לְעָבְרְךָ֗] [בִּבְרִ֛ית] yhwh teu-Elohim [וּבְאָלָת֑וֹ] que yhwh teu-Elohim [כֹּרֵ֥ת] contigo o-dia');
INSERT INTO verses VALUES (5694, 5, 29, 12, 'para-que [הָקִֽים־אֹתְךָ֩] o-dia [׀] a-ele le-am e-ele ele-será- para-ti para-Elohim conforme falou a-ti [לַאֲבֹתֶ֔יךָ] [לְאַבְרָהָ֥ם] [לְיִצְחָ֖ק] para-Abraao para-Isaque [sem-traducao]');
INSERT INTO verses VALUES (5695, 5, 29, 13, 'e-não com-vocês [לְבַדְּכֶ֑ם] eu [כֹּרֵת֙] a a aliança esta e-a [sem-traducao] a esta');
INSERT INTO verses VALUES (5696, 5, 29, 14, 'que a que [פֹּ֗ה] [עִמָּ֙נוּ֙] [עֹמֵ֣ד] o-dia o-dia yhwh yhwh Elohim-nosso e-a que [פֹּ֖ה] aqui o-dia o-dia');
INSERT INTO verses VALUES (5697, 5, 29, 15, 'porque vós Yedautem a que [מִצְרָ֑יִם] em-terra-de Egito ve-et que [אֲשֶׁ֥ר] em-meio-de as-nações que [sem-traducao]');
INSERT INTO verses VALUES (5698, 5, 29, 16, '[וַתִּרְאוּ֙] a e-[OBJ] e-a árvore arvore e-eu-mostrarei [וְזָהָ֖ב] וְזָהָ֖ב que [sem-traducao]');
INSERT INTO verses VALUES (5699, 5, 29, 17, 'para-que-não há [אִ֣ישׁ] homem ou mulher [אוֹ־שֵׁ֗בֶט] [אֲשֶׁר֩] ou [פֹנֶ֤ה] o-dia [מֵעִם֙] yhwh o-dia [לָלֶ֣כֶת] para-lavrar Elohim-nosso para-andar [הָהֵ֑ם] a Elohim-de as-nações os-aqueles para-que-não há frutificai cabeça');
INSERT INTO verses VALUES (5700, 5, 29, 18, 'e-será [בְּשָׁמְעוֹ֩] a palavras [הַזֹּ֗את] desta [בִּלְבָב֤וֹ] dizendo para-dizer שָלוֹם que para-mim porque [אֵלֵ֑ךְ] לִבִּ֖י irei para-fim-de SEPOT [sem-traducao] a [sem-traducao]');
INSERT INTO verses VALUES (5701, 5, 29, 19, 'não yhwh yhwh a-ele que porque [יֶעְשַׁ֨ן] [אַף־יְהוָ֤ה] também yhwh [הַה֔וּא] [וְרָ֤בְצָה־[c]] aquele em-ele todo [בַּסֵּ֣פֶר] [הַזֶּ֑ה] [וּמָחָ֤ה] yhwh [אֶת־שְׁמ֔וֹ] debaixo-de a os-céus');
INSERT INTO verses VALUES (5702, 5, 29, 20, '[וְהִבְדִּיל֤וֹ] yhwh para-mal de-toda tribos-de Israel como-tudo [אָל֣וֹת] a-aliança [הַכְּתוּבָ֕ה] besefer a-torah a-esta');
INSERT INTO verses VALUES (5703, 5, 29, 21, '[וְאָמַ֞ר] a-geração [הֽ͏ָאַחֲר֗וֹן] filhos-vossos que e-levantar-se-ão [מֵאַ֣חֲרֵיכֶ֔ם] [וְהַ֨נָּכְרִ֔י] que vira da-terra [רְחוֹקָ֑ה] [וְ֠רָאוּ] a a-terra aquela [וְאֶת־תַּ֣חֲלֻאֶ֔יהָ] e-a yhwh que [sem-traducao] yhwh nela');
INSERT INTO verses VALUES (5704, 5, 29, 22, 'gafrit [וָמֶלַח֮] [שְׂרֵפָ֣ה] todo não não [וְלֹ֣א] e-não [וְלֹֽא־יַעֲלֶ֥ה] e-não subirá nela todo [וַעֲמֹרָה֙] [אַדְמָ֣ה] סְדֹ֤ם [**וּצְבוֹיִ֔ם] [אֲשֶׁר֙] revolver yhwh yhwh [וּבַחֲמָתֽוֹ] [sem-traducao]');
INSERT INTO verses VALUES (5705, 5, 29, 23, 'וְאָמְרוּ todo as-nações sobre yhwh fez yhwh assim a-terra esta מֶה [הַגָּד֖וֹל] [הַזֶּֽה] o-grande a-esta');
INSERT INTO verses VALUES (5706, 5, 29, 24, 'e disseram sobre que abandonaram a yhwh yhwh Elohim-de pais-deles que [עִמָּ֔ם] com-eles eles eles de-terra-de Egito');
INSERT INTO verses VALUES (5707, 5, 29, 25, 'e-foram [וַיַּֽעַבְדוּ֙] Elohim outros [וַיִּֽשְׁתַּחֲוּ֖וּ] a-eles Elohim que não [וְלֹ֥א] e-não a-eles');
INSERT INTO verses VALUES (5708, 5, 29, 26, 'e-acendeu-se- yhwh yhwh aquela aquele para trazer- sobre-ela a todo [הַזֶּֽה] [sem-traducao] [sem-traducao] a-esta');
INSERT INTO verses VALUES (5709, 5, 29, 27, '[וַיִּתְּשֵׁ֤ם] yhwh de-cima-de sua terra [בְּאַ֥ף] e na chama e-no-rancor grande [וַיַּשְׁלִכֵ֛ם] a terra [כַּיּ֥וֹם] como-o-dia a-esta');
INSERT INTO verses VALUES (5710, 5, 29, 28, '[הַ֨נִּסְתָּרֹ֔ת] a-yhwh nosso-Elohim [וְהַנִּגְלֹ֞ת] até eternidade לַעֲשׂוֹת a todo palavras-de a instrução a esta');
INSERT INTO chapters VALUES (183, 5, 30, 20);
INSERT INTO verses VALUES (5711, 5, 30, 1, 'e-será porque [עָלֶ֜יךָ] sobre ti todo as-palavras estes [אֲשֶׁ֥ר] dei que dei diante-de-ti [בְּכָל־הַגּוֹיִ֔ם] a teu-coração yhwh as-nações que [sem-traducao] yhwh teu-Elohim ali');
INSERT INTO verses VALUES (5712, 5, 30, 2, '[וְשַׁבְתָּ֞] até yhwh teu-Elohim [בְקֹל֔וֹ] [כְּכֹ֛ל] conforme-tudo que o-dia tu o-dia tu [וּבְכָל־נַפְשֶֽׁךָ] em-todo do-teu-cor e-em-todo alma-tua');
INSERT INTO verses VALUES (5713, 5, 30, 3, 'vesheva yhwh Elohim-teu a [וְרִחֲמֶ֑ךָ] [וְשָׁ֗ב] e voltar-se-á [מִכָּל־הָ֣עַמִּ֔ים] de-todo os-povos yhwh [Elohim] yhwh teu-Elohim ali');
INSERT INTO verses VALUES (5714, 5, 30, 4, 'se será [בִּקְצֵ֣ה] em-extremidade os-céus de-lá yhwh yhwh teu-Elohim e-de-lá');
INSERT INTO verses VALUES (5715, 5, 30, 5, '[וֶהֱבִֽיאֲךָ֞] yhwh Elohim-teus a a-terra que [וִֽירִשְׁתָּ֑הּ] os-teus-avós [וְהִרְבְּךָ֖] [מֵאֲבֹתֶֽיךָ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (5716, 5, 30, 6, '[וּמָ֨ל] yhwh Elohim-teu a do-teu-cor e-a לְבַ֣ב [אֶת־יְהוָ֧ה] para-amar a yhwh Elohim-teu tua-vida ao-teu-coração e-em-todo alma-tua para vidas-tuas');
INSERT INTO verses VALUES (5717, 5, 30, 7, 'vênatan yhwh teu-Elohim a todo [הָאֵ֑לֶּה] estas sobre [אֲשֶׁ֥ר] e-sobre [sem-traducao] que [sem-traducao]');
INSERT INTO verses VALUES (5718, 5, 30, 8, 'e-tu [תָשׁ֔וּב] e-ouvirás com-voz yhwh וְעָשִׂ֙יתָ֙ a todo eu que o-dia dizendo o-dia');
INSERT INTO verses VALUES (5719, 5, 30, 9, '[וְהוֹתִֽירְךָ֩] yhwh Elohim-teu em-todo obra-de [מַעֲשֵׂ֣ה] [יָדֶ֗ךָ] [בִּפְרִ֨י] [בִטְנְךָ֜] [וּבִפְרִ֧י] וּבִפְרִ֥י da tua terra [אַדְמָתְךָ֖] que que yhwh [יָשׁ֣וּב] yhwh [לָשׂ֤וּשׂ] conforme- seis sobre [עַל־אֲבֹתֶֽיךָ]');
INSERT INTO verses VALUES (5720, 5, 30, 10, 'que [תִשְׁמַ֗ע] em-voz yhwh teu-Elohim para-guardar mandamentos-seus [וְחֻקֹּתָ֔יו] [הַכְּתוּבָ֕ה] besefer a-torah esta que תָשׁוּב֙ a yhwh teu-Elohim em-todo do-teu-cor e-em-todo alma-tua');
INSERT INTO verses VALUES (5721, 5, 30, 11, 'que [הַמִּצְוָ֣ה] a-esta que eu mandado-te o-dia não ela ela-foi de-te e-não ela e-la');
INSERT INTO verses VALUES (5722, 5, 30, 12, 'não bas-shamayim ela dizendo quem subirá- [הַשָּׁמַ֙יְמָה֙] [וְיִקָּחֶ֣הָ] [לָּ֔נוּ] para-nos [אֹתָ֖הּ] a-ela [sem-traducao]');
INSERT INTO verses VALUES (5723, 5, 30, 13, 'e-não do-outro-lado ela dizendo quem quem יַעֲבָר־ o-mar a alado o mar [אֹתָ֖הּ] para-nos [sem-traducao] a-ela [sem-traducao]');
INSERT INTO verses VALUES (5724, 5, 30, 14, 'porque próximo [הַדָּבָ֖ר] muito muito [וּבִֽלְבָבְךָ֖] [לַעֲשֹׂתֽוֹ׃]');
INSERT INTO verses VALUES (5725, 5, 30, 15, 'viu dei diante-de-ti o-dia a [וְאֶת־הַטּ֑וֹב] e-a [וְאֶת־הָרָֽע] e-a [sem-traducao] e-a [sem-traducao]');
INSERT INTO verses VALUES (5726, 5, 30, 16, 'que eu que te foi ordenado o-dia para-amar a yhwh Elohim-teu para-andar [וְלִשְׁמֹ֛ר] [מִצְוֺתָ֥יו] [וְחֻקֹּתָ֖יו] e-chukkótiav [וְחָיִ֣יתָ] [וְרָבִ֔יתָ] [וּבֵֽרַכְךָ֙] yhwh yhwh teu-Elohim na-a-terra que tu veio para lá para-possuí-la');
INSERT INTO verses VALUES (5727, 5, 30, 17, 'e-se [לְבָבְךָ֖] do-teu-cor e-não [וְנִדַּחְתָּ֗] [וְהִֽשְׁתַּחֲוִ֛יתָ] [לֵאלֹהִ֥ים] לֵאלֹהִ֥ים outros [sem-traducao]');
INSERT INTO verses VALUES (5728, 5, 30, 18, '[הִגַּ֤דְתִּי] a-vós o-dia que [אָבֹ֖ד] [תֹּאבֵד֑וּן] não seu-tempo dias sobre tu que tu passando a o-Jordão para entrar para lá para-possuí-la');
INSERT INTO verses VALUES (5729, 5, 30, 19, '[הַעִידֹ֨תִי] em-vós o-dia a os-céus a-vida a-terra dei [לְפָנֶ֔יךָ] dei diante-de-ti habrakhah vehakhlalah [לְמַ֥עַן] [תִּחְיֶ֖ה] tu [וְזַרְעֶֽךָ] tu [sem-traducao]');
INSERT INTO verses VALUES (5730, 5, 30, 20, '[לְאַֽהֲבָה֙] a yhwh teu-Elohim para-ouvir בְּקֹל֖וֹ que ele tua-vida ele [יָמֶ֔יךָ] [לָשֶׁ֣בֶת] יְמֵיכֶם para-habitar sobre yhwh que jura yhwh a-os-pais-tuus para-Abraão a-eles e-a-jacob a-dar para-eles');
INSERT INTO chapters VALUES (184, 5, 31, 30);
INSERT INTO verses VALUES (5731, 5, 31, 1, 'E-andou Moisés e-ele-falou a as-palavras estes a todo Israel');
INSERT INTO verses VALUES (5732, 5, 31, 2, 'E-disse a-eles filho-de cem e-vinte eu o-dia o-dia não posso ainda לָצֵא disse e-יהוה não a-mim não passes a o-jordão a-esta');
INSERT INTO verses VALUES (5733, 5, 31, 3, 'yhwh Elohim-teu ele passando em-te ele [הֽוּא־יַשְׁמִ֞יד] a as-nações os-estes [וִֽירִשְׁתָּ֑ם] [יְהוֹשֻׁ֗עַ] ele ele passando diante-de-ti conforme yhwh yhwh');
INSERT INTO verses VALUES (5734, 5, 31, 4, '[וְעָשָׂ֤ה] yhwh a-eles como-que fez [לְסִיח֥וֹן] [וּלְע֛וֹג] reis-de o-amorreu [וּלְאַרְצָ֑ם] que [הִשְׁמִ֖יד] eles');
INSERT INTO verses VALUES (5735, 5, 31, 5, '[וּנְתָנָ֥ם] yhwh [לִפְנֵיכֶ֑ם] וַעֲשׂיתֶם a-eles conforme-toda a mandação que ordenei a-vós');
INSERT INTO verses VALUES (5736, 5, 31, 6, 'fortalecei [וְאִמְצ֔וּ] a [וְאַל־תַּעַרְצ֖וּ] e-a que de-face-deles yhwh yhwh ele o-que-vai [עִמָּ֔ךְ] não não [וְלֹ֥א] e-não [sem-traducao]');
INSERT INTO verses VALUES (5737, 5, 31, 7, 'E-chamou Moisés [לִֽיהוֹשֻׁ֗עַ] E-disse a-ele aos-olhos-de todo Israel forte que tu tu virá a o-povo esta a yhwh que jura a-eles [וְאַתָּ֖ה] para-dar para-eles e-tu [sem-traducao] a-eles');
INSERT INTO verses VALUES (5738, 5, 31, 8, '[וַֽיהוָ֞ה] ele [׀] o-que-vai ele ele será não não e-não [וְלֹ֣א] não não e-não [וְלֹ֥א]');
INSERT INTO verses VALUES (5739, 5, 31, 9, 'e-escreveu Moisés a hatorah esta [אֶל־הַכֹּהֲנִים֙] a aos-sacerdotes filhos-de Levi [בְּרִ֣ית] yhwh arca aliança yhwh e-a todo anciãos-de Israel');
INSERT INTO verses VALUES (5740, 5, 31, 10, 'E-ordenou Moisés e-os dizendo מקץ ׀ sete dois [שָׁנִ֗ים] ano-de [שְׁנַ֥ת] [הַשְּׁמִטָּ֖ה] as tendas');
INSERT INTO verses VALUES (5741, 5, 31, 11, 'em-vir todo Israel para-ver yhwh face-de yhwh teu-Elohim no-lugar- que [אֶת־הַתּוֹרָ֥ה] [הַזֹּ֛את] diante a instrução esta diante-de todo Israel em-os-ouvidos-deles');
INSERT INTO verses VALUES (5742, 5, 31, 12, '[הַקְהֵ֣ל] a o povo [וְהַנָּשִׁים֙] [וְהַטַּ֔ף] e-os-crianças-pequenas [אֲשֶׁ֣ר] que nas-tuas-cabeças para-que ouvirão [יִלְמְד֗וּ] [וְיָֽרְאוּ֙] [אֶת־יְהוָ֣ה] a yhwh Elohim-de-vos [אֶת־כָּל־דִּבְרֵ֖י] para-fazer a todo palavras-de a instrução a esta');
INSERT INTO verses VALUES (5743, 5, 31, 13, '[וּבְנֵיהֶ֞ם] que não sabiam ouvirem [לְיִרְאָ֖ה] [אֶת־יְהוָ֣ה] a yhwh vosso-Elohim todo vida que vós vidos sobre a-terra que vós passantes a o Jordão para lá para-possuí-la');
INSERT INTO verses VALUES (5744, 5, 31, 14, 'E-disse yhwh a eis eis eles-se-aproximaram [לָמוּת֒] [קְרָ֣א] chamou a Josué [מוֹעֵ֖ד] em-tenda encontro [מֹשֶׁה֙] E-andou Moisés [בְּאֹ֥הֶל] va-yit-ya-tsăbū em-tenda encontro');
INSERT INTO verses VALUES (5745, 5, 31, 15, 'E-viu yhwh na-tenda [בְּעַמּ֣וּד] [עָנָ֑ן] [וַיַּעֲמֹ֛ד] [עַמּ֥וּד] ha-eanan sobre porta o-tenda');
INSERT INTO verses VALUES (5746, 5, 31, 16, 'E-disse yhwh a Moisés veja-você שֹׁכֵב com [הָעָ֨ם] [הַזֶּ֜ה] o-povo o-este [אַחֲרֵ֣י] depois-de Elohim-de [נֵֽכַר־הָאָ֗רֶץ] a-terra ele ele veio lá-baixo em-meio-seu [אֶת־בְּרִיתִ֔י] [אֲשֶׁ֥ר] a beriti que כרתי com-ele');
INSERT INTO verses VALUES (5747, 5, 31, 17, 'והרה minha-ira nele no-dia-de הַ֠הוּא [וְהִסְתַּרְתִּ֨י] [פָנַ֤י] face-de deles e-foi [וּמְצָאֻ֛הוּ] [רָע֥וֹת] [רַבּ֖וֹת] [וְצָר֑וֹת] [וְאָמַר֙] no-dia em-o-dia aquele sobre sobre porque não-há אֱלֹהַי [הָרָע֥וֹת] [הָאֵֽלֶּה] [sem-traducao] as estas');
INSERT INTO verses VALUES (5748, 5, 31, 18, 'e-eu [הַסְתֵּ֨ר] [אַסְתִּ֤יר] face-de no-dia aquele sobre todo [אֲשֶׁ֣ר] que que porque [אֶל־אֱלֹהִ֖ים] a Elohim');
INSERT INTO verses VALUES (5749, 5, 31, 19, 'e-agora [כִּתְב֤וּ] a-vós a a canção a-esta [אֶת־בְּנֵי־יִשְׂרָאֵ֖ל] a filhos-de Israel [תִּהְיֶה־לִּ֜י] [הַשִּׁירָ֥ה] para-que tihyéh- [בִּבְנֵ֥י] [יִשְׂרָאֵֽל] esta לְעֵ֖ד de-filhos Israel');
INSERT INTO verses VALUES (5750, 5, 31, 20, '[כִּֽ[t]י־אֲבִיאֶ֜נּוּ] a [׀] que nishebatti [זָבַ֤ת] que-mana leite e-coma ve''akal [וְדָשֵׁ֑ן] [וּפָנָ֞ה] [אֶל־אֱלֹהִ֤ים] a Elohim Achērim [וְהֵפֵ֖ר] [אֶת־בְּרִיתִֽי] [sem-traducao] a em-pacto-meu');
INSERT INTO verses VALUES (5751, 5, 31, 21, 'e será porque ele a-ele רָע֣וֹת [וְצָרוֹת֒] [וְ֠עָנְתָה] [הַשִּׁירָ֨ה] [הַזֹּ֤את] esta diante-dele que não não [מִפִּ֣י] sua-semente que porque eu-sei a ele que o-dia fez o-dia betereim-acento-águia [אֲשֶׁ֥ר] a a-terra que [sem-traducao]');
INSERT INTO verses VALUES (5752, 5, 31, 22, '[וַיִּכְתֹּ֥ב] Moisés a [הַזֹּ֖את] no-dia em-o-dia o-aquele [אֶת־בְּנֵ֥י] a filhos-de Israel');
INSERT INTO verses VALUES (5753, 5, 31, 23, 'E-ordenou a Yehoshua E-disse Nun E-disse que tu porque tu [יִשְׂרָאֵ֔ל] a filhos-de a-eles a a-terra que nishebatti a-eles e-eu é-ehyé contigo');
INSERT INTO verses VALUES (5754, 5, 31, 24, 'e-houve kechaloth Moisés [מֹשֶׁ֗ה] a palavras-de a-tora- a-esta até livro até foram-acabados');
INSERT INTO verses VALUES (5755, 5, 31, 25, 'E-ordenou Moisés a os-levitas [אֲר֥וֹן] arca dizendo yhwh');
INSERT INTO verses VALUES (5756, 5, 31, 26, 'tomou a סֵ֤פֶר a-torá este [וְשַׂמְתֶּ֣ם] ele [מִצַּ֛ד] arca em-aliança-de yhwh vosso-Elohim e-haverá- nome em-te [sem-traducao]');
INSERT INTO verses VALUES (5757, 5, 31, 27, 'que eu conheci a [וְאֶֽת־עָרְפְּךָ֖] e-com eis [בְּעוֹדֶנִּי֩] vida [עִמָּכֶ֜ם] o-dia com-vos o-dia [עִם־יְהֹוָ֔ה] [וְאַ֖ף] com yhwh [sem-traducao] porque atrás-de [sem-traducao]');
INSERT INTO verses VALUES (5758, 5, 31, 28, '[הַקְהִ֧ילוּ] a-mim a todo anciãos-de de-vosso-sajam [בְאָזְנֵיהֶ֗ם] e-falarei-eu em suas orelhas a as-palavras os-estes ואעידנה contra-eles a os-céus e-a a-terra');
INSERT INTO verses VALUES (5759, 5, 31, 29, 'que יָדַ֗עְתִּי depois-de [מוֹתִי֙] porque [תַּשְׁחִת֔וּן] vocês-destruirão [מִן־הַדֶּ֔רֶךְ] de [צִוִּ֖יתִי] que ordenei a-vós [הֽ͏ָרָעָה֙] a-vos a-maldição no fundo os-dias porque yhwh a o-mal em-olhos-de yhwh [sem-traducao] биммаасе [sem-traducao]');
INSERT INTO verses VALUES (5760, 5, 31, 30, 'e-falou Moisés [בְּאָזְנֵי֙] todo assembleia Israel a palavras-de até esta até foram-acabados');
INSERT INTO chapters VALUES (185, 5, 32, 52);
INSERT INTO verses VALUES (5761, 5, 32, 1, 'הַאֲזִ֥ינוּ os-céus e-eu-falar e-ouvirá a-terra palavras-de a boca:');
INSERT INTO verses VALUES (5762, 5, 32, 2, '[יַעֲרֹ֤ף] [כַּמָּטָר֙] [לִקְחִ֔י] [תִּזַּ֥ל] [כַּטַּ֖ל] palavra-de-mim [כִּשְׂעִירִ֣ם] sobre [וְכִרְבִיבִ֖ים] [עֲלֵי־עֵֽשֶׂב]');
INSERT INTO verses VALUES (5763, 5, 32, 3, 'que nome yhwh clamarei dai [גֹ֖דֶל] א-לוהינו');
INSERT INTO verses VALUES (5764, 5, 32, 4, '[הַצּוּר֙] תָּמִ֣ים [פָּעֳל֔וֹ] que todo [מִשְׁפָּ֑ט] juízo El [וְאֵ֣ין] e-não-há enganho justo ele ela');
INSERT INTO verses VALUES (5765, 5, 32, 5, '[שִׁחֵ֥ת] a-ele não filhos-seus [מוּמָ֑ם] dor IQUEשׁ [וּפְתַלְתֹּֽל]');
INSERT INTO verses VALUES (5766, 5, 32, 6, '[הֲ־לַיְהוָה֙] [תִּגְמְלוּ־זֹ֔את] [עַ֥ם] Isto povo tolo e-não sabio porventura-não ele [עָֽשְׂךָ֖] [וַֽיְכֹנְנֶֽךָ] ele [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (5767, 5, 32, 7, 'macho [יְמ֣וֹת] eternidade [בִּ֖ינוּ] שְׁנ֣וֹת [דּוֹר־וָד֑וֹר] e geração [אָבִ֙יךָ֙] teu-pai [זְקֵנֶ֖יךָ] זְקֵנֶ֖יךָ para-ti para-ti');
INSERT INTO verses VALUES (5768, 5, 32, 8, '[בְּהַנְחֵ֤ל] [עֶלְיוֹן֙] nações [בְּהַפְרִיד֖וֹ] filhos-de homem [יַצֵּב֙] [גְּבֻלֹ֣ת] nações conforme-número-de filhos-de Israel');
INSERT INTO verses VALUES (5769, 5, 32, 9, 'que porção yhwh povo-seu Jacó [חֶ֥בֶל] herança-dele');
INSERT INTO verses VALUES (5770, 5, 32, 10, '[יִמְצָאֵ֙הוּ֙] em-terra-de [מִדְבָּ֔ר] [וּבְתֹ֖הוּ] [יְלֵ֣ל] [יְשִׁמֹ֑ן] [יְסֹֽבְבֶ֙נְהוּ֙] [יְב֣וֹנְנֵ֔הוּ] [יִצְּרֶ֖נְהוּ] [כְּאִישׁ֥וֹן] sua face');
INSERT INTO verses VALUES (5771, 5, 32, 11, '[כְּנֶ֙שֶׁר֙] iluminará [קִנּ֔וֹ] sobre [יְרַחֵ֑ף] [יִפְרֹ֤שׂ] [כְּנָפָיו֙] [יִקָּחֵ֔הוּ] [יִשָּׂאֵ֖הוּ] [עַל־אֶבְרָתֽוֹ] sobre [sem-traducao]');
INSERT INTO verses VALUES (5772, 5, 32, 12, 'yhwh [בָּדָ֣ד] [יַנְחֶ֑נּוּ] e-não-há com-ele El [נֵכָֽר]');
INSERT INTO verses VALUES (5773, 5, 32, 13, '[יַרְכִּבֵ֙הוּ֙] sobre terra [אָ֔רֶץ] e-comeu Shaddai [שָׂדָ֑י] [וַיֵּנִקֵ֤הֽוּ] [דְבַשׁ֙] [מִסֶּ֔לַע] [וְשֶׁ֖מֶן] Zur');
INSERT INTO verses VALUES (5774, 5, 32, 14, '[חֶמְאַ֨ת] manhã [וַחֲלֵ֣ב] [צֹ֗אן] com [כָּרִ֜ים] [וְאֵילִ֤ים] [בְּנֵֽי־בָשָׁן֙] filhos-de [עִם־חֵ֖לֶב] [כִּלְי֣וֹת] com gordura [תִּשְׁתֶּה־חָֽמֶר]');
INSERT INTO verses VALUES (5775, 5, 32, 15, '[וַיִּשְׁמַ֤ן] [יְשֻׁרוּן֙] [וַיִּבְעָ֔ט] [שָׁמַ֖נְתָּ] [עָבִ֣יתָ] [כָּשִׂ֑יתָ] [וַיִּטֹּשׁ֙] [אֱל֣וֹהַ] [עָשָׂ֔הוּ] [וַיְנַבֵּ֖ל] [צ֥וּר] [יְשֻׁעָתֽוֹ]');
INSERT INTO verses VALUES (5776, 5, 32, 16, '[יַקְנִאֻ֖הוּ] [בְּזָרִ֑ים] [בְּתוֹעֵבֹ֖ת] [יַכְעִיסֻֽהוּ]');
INSERT INTO verses VALUES (5777, 5, 32, 17, '[יִזְבְּח֗וּ] [לַשֵּׁדִים֙] não [אֱלֹ֔הַ] Elohim não [יְדָע֑וּם] [חֲדָשִׁים֙] [מִקָּרֹ֣ב] vieram não [שְׂעָר֖וּם] [אֲבֹתֵיכֶֽם]');
INSERT INTO verses VALUES (5778, 5, 32, 18, '[צ֥וּר] [יְלָדְךָ֖] [תֶּ֑שִׁי] [וַתִּשְׁכַּ֖ח] El [מְחֹלְלֶֽךָ]');
INSERT INTO verses VALUES (5779, 5, 32, 19, 'E-viu yhwh [וַיִּנְאָ֑ץ] [מִכַּ֥עַס] [בָּנָ֖יו] [וּבְנֹתָֽיו]');
INSERT INTO verses VALUES (5780, 5, 32, 20, 'E-disse [אַסְתִּ֤ירָה] face-de de-eles [אֶרְאֶ֖ה] que [אַחֲרִיתָ֑ם] que [ד֤וֹר] [תַּהְפֻּכֹת֙] eles filhos não [בָּֽם]');
INSERT INTO verses VALUES (5781, 5, 32, 21, 'eles [קִנְא֣וּנִי] [בְלֹא־אֵ֔ל] El [בְּהַבְלֵיהֶ֑ם] [וַאֲנִי֙] e-eu [בְּלֹא־עָ֔ם] [בְּג֥וֹי] povo [אַכְעִיסֵֽם]');
INSERT INTO verses VALUES (5782, 5, 32, 22, 'porque fogo [בְאַפִּ֔י] [וַתִּיקַ֖ד] [עַד־שְׁא֣וֹל] até e-comeste terra [וִֽיבֻלָ֔הּ] terra [מוֹסְדֵ֥י] [הָרִֽים]');
INSERT INTO verses VALUES (5783, 5, 32, 23, '[אַסְפֶּ֥ה] [עָלֵ֖ימוֹ] [רָע֑וֹת] [חִצַּ֖י] [אֲכַלֶּה־בָּֽם]');
INSERT INTO verses VALUES (5784, 5, 32, 24, '[מְזֵ֥י] [רָעָ֛ב] [וּלְחֻ֥מֵי] [רֶ֖שֶׁף] [וְקֶ֣טֶב] [מְרִירִ֑י] [וְשֶׁן־בְּהֵמוֹת֙] [אֲשַׁלַּח־בָּ֔ם] [עִם־חֲמַ֖ת] contra-eles pó');
INSERT INTO verses VALUES (5785, 5, 32, 25, 'de-fora [תְּשַׁכֶּל־חֶ֔רֶב] espada [אֵימָ֑ה] [גַּם־בָּחוּר֙] também [יוֹנֵ֖ק] também [שֵׂיבָֽה] com homem');
INSERT INTO verses VALUES (5786, 5, 32, 26, '[אָמַ֖רְתִּי] [אַפְאֵיהֶ֑ם] [אַשְׁבִּ֥יתָה] [מֵאֱנ֖וֹשׁ] [זִכְרָֽם]');
INSERT INTO verses VALUES (5787, 5, 32, 27, '[לוּלֵ֗י] [כַּ֤עַס] [אוֹיֵב֙] [אָג֔וּר] [פֶּֽן־יְנַכְּר֖וּ] [צָרֵ֑ימוֹ] [פֶּן־יֹֽאמְרוּ֙] para-que-não [רָ֔מָה] [וְלֹ֥א] yhwh e-não yhwh todo');
INSERT INTO verses VALUES (5788, 5, 32, 28, 'porque nação [עֵצ֖וֹת] [הֵ֑מָּה] [וְאֵ֥ין] e-não-há [תְּבוּנָֽה]');
INSERT INTO verses VALUES (5789, 5, 32, 29, '[ל֥וּ] [חָכְמ֖וּ] [יַשְׂכִּ֣ילוּ] esta [יָבִ֖ינוּ] [לְאַחֲרִיתָֽם]');
INSERT INTO verses VALUES (5790, 5, 32, 30, '[אֵיכָ֞ה] [יִרְדֹּ֤ף] um mil [וּשְׁנַ֖יִם] [יָנִ֣יסוּ] [רְבָבָ֑ה] se não porque [וַֽיהוָ֖ה] [הִסְגִּירָֽם]');
INSERT INTO verses VALUES (5791, 5, 32, 31, 'que não [כְצוּרֵ֖נוּ] [צוּרָ֑ם] [וְאֹיְבֵ֖ינוּ] [פְּלִילִֽים]');
INSERT INTO verses VALUES (5792, 5, 32, 32, 'porque [סְדֹם֙] [גַּפְנָ֔ם] [וּמִשַּׁדְמֹ֖ת] [עֲמֹרָ֑ה] [עֲנָבֵ֙מוֹ֙] [עִנְּבֵי־ר֔וֹשׁ] [אַשְׁכְּלֹ֥ת] [מְרֹרֹ֖ת] [לָֽמוֹ]');
INSERT INTO verses VALUES (5793, 5, 32, 33, '[חֲמַ֥ת] [תַּנִּינִ֖ם] [יֵינָ֑ם] [וְרֹ֥אשׁ] [פְּתָנִ֖ים] [אַכְזָֽר]');
INSERT INTO verses VALUES (5794, 5, 32, 34, 'não-é ele comigo [חָתֻ֖ם] [בְּאוֹצְרֹתָֽי]');
INSERT INTO verses VALUES (5795, 5, 32, 35, 'para-mim [נָקָם֙] [וְשִׁלֵּ֔ם] [לְעֵ֖ת] [תָּמ֣וּט] [רַגְלָ֑ם] que proximo dia [אֵידָ֔ם] [וְחָ֖שׁ] [עֲתִדֹ֥ת] a-eles');
INSERT INTO verses VALUES (5796, 5, 32, 36, 'porque yhwh yhwh povo-seu e-sobre que [יִרְאֶה֙] porque mão porque [עָצ֥וּר] mão');
INSERT INTO verses VALUES (5797, 5, 32, 37, '[וְאָמַ֖ר] [אֵ֣י] [אֱלֹהֵ֑ימוֹ] rocha [חָסָ֥יוּ] nele');
INSERT INTO verses VALUES (5798, 5, 32, 38, 'que [חֵ֤לֶב] [זְבָחֵ֙ימוֹ֙] [יֹאכֵ֔לוּ] [יִשְׁתּ֖וּ] [יֵ֣ין] [נְסִיכָ֑ם] [יָק֙וּמוּ֙] [וְיַעְזְרֻכֶ֔ם] haja sobre-vós [סִתְרָֽה]');
INSERT INTO verses VALUES (5799, 5, 32, 39, '[רְא֣וּ] agora porque que eu ele ele Elohim de-pe-comigo comigo [אֲנִ֧י] [אָמִ֣ית] [וַאֲחַיֶּ֗ה] e-eu [וַאֲנִ֣י] e-não-há [וְאֵ֥ין] [מִיָּדִ֖י]');
INSERT INTO verses VALUES (5800, 5, 32, 40, 'porque [אֶל־שָׁמַ֖יִם] a céus vida eu para-sempre');
INSERT INTO verses VALUES (5801, 5, 32, 41, 'se [בְּרַ֣ק] [חַרְבִּ֔י] [וְתֹאחֵ֥ז] [בְּמִשְׁפָּ֖ט] [יָדִ֑י] [אָשִׁ֤יב] [נָקָם֙] [לְצָרָ֔י] [וְלִמְשַׂנְאַ֖י] [אֲשַׁלֵּֽם]');
INSERT INTO verses VALUES (5802, 5, 32, 42, '[אַשְׁכִּ֤יר] [חִצַּי֙] [מִדָּ֔ם] [וְחַרְבִּ֖י] comerás carne de-sangue [חָלָל֙] [וְשִׁבְיָ֔ה] [מֵרֹ֖אשׁ] [פַּרְע֥וֹת] inimigo');
INSERT INTO verses VALUES (5803, 5, 32, 43, '[הַרְנִ֤ינוּ] nações seu-povo que [דַם־עֲבָדָ֖יו] [יִקּ֑וֹם] [וְנָקָם֙] [יָשִׁ֣יב] [לְצָרָ֔יו] [וְכִפֶּ֥ר] e-fará-expiação [עַמּֽוֹ׃] seu-povo');
INSERT INTO verses VALUES (5804, 5, 32, 44, 'E-veio Moisés [וַיְדַבֵּ֛ר] a todo palavras-de [הָעָ֑ם] ele em-orelhas-de o-povo filho-de');
INSERT INTO verses VALUES (5805, 5, 32, 45, 'E-terminou Moisés [לְדַבֵּ֛ר] a todo as-palavras a todo Israel');
INSERT INTO verses VALUES (5806, 5, 32, 46, 'E-disse para-eles [שִׂ֣ימוּ] [לְבַבְכֶ֔ם] para-todo as-palavras eu eu [בָּכֶ֖ם] o-dia o-dia que [אֶת־בְּנֵיכֶ֔ם] a [לַעֲשׂ֔וֹת] [אֶת־כָּל־דִּבְרֵ֖י] para-fazer a todo');
INSERT INTO verses VALUES (5807, 5, 32, 47, 'que não palavra ele ele de-vós porque ele [הַזֶּ֗ה] [תַּאֲרִ֤יכוּ] o-este [עַל־הָ֣אֲדָמָ֔ה] dias sobre a-terra que vós [לְרִשְׁתָּֽהּ׃] a');
INSERT INTO verses VALUES (5808, 5, 32, 48, 'e-falou yhwh a Moisés o-dia o-dia dizendo');
INSERT INTO verses VALUES (5809, 5, 32, 49, 'folhas-de a [הָעֲבָרִ֨ים] [הַזֶּ֜ה] o-este monte-de [בְּאֶ֣רֶץ] que em-terra-de Moabe que sobre face-de Jericó [אֲשֶׁ֨ר] a terra Canaã que eu deu Israel');
INSERT INTO verses VALUES (5810, 5, 32, 50, '[וּמֻ֗ת] [בָּהָר֙] que tu subindo ali [וְהֵאָסֵ֖ף] a [כּֽ͏ַאֲשֶׁר־מֵ֞ת] [אַהֲרֹ֤ן] morreu אַהֲרֹן irmão-teu [וַיֵּאָ֖סֶף] a-montanha a');
INSERT INTO verses VALUES (5811, 5, 32, 51, 'sobre que [מְעַלְתֶּ֜ם] [בִּ֗י] no-meio-de filhos-de Israel [בְּמֵֽי־מְרִיבַ֥ת] [קָדֵ֖שׁ] [מִדְבַּר־צִ֑ן] sobre [אֲשֶׁ֤ר] sobre que no-meio-de [בְּנֵ֥י] [יִשְׂרָאֵֽל] filhos-de Israel');
INSERT INTO verses VALUES (5812, 5, 32, 52, 'que em-frente [תִּרְאֶ֣ה] a a-terra não não [אֶל־הָאָ֕רֶץ] a a-terra que eu deu Israel');
INSERT INTO chapters VALUES (186, 5, 33, 29);
INSERT INTO verses VALUES (5813, 5, 33, 1, '[וְזֹ֣את] [הַבְּרָכָ֗ה] que abençoou Moisés homem Elohim a filhos-de Israel diante-de');
INSERT INTO verses VALUES (5814, 5, 33, 2, 'E-disse yhwh [מִסִּינַ֥י] veio [וְזָרַ֤ח] [מִשֵּׂעִיר֙] [לָ֔מוֹ] [הוֹפִ֙יעַ֙] de-montanha-de [פָּארָ֔ן] [וְאָתָ֖ה] [מֵרִבְבֹ֣ת] santidade [מִֽימִינ֕וֹ] a-eles');
INSERT INTO verses VALUES (5815, 5, 33, 3, 'certamente [חֹבֵ֣ב] [עַמִּ֔ים] todo [בְּיָדֶ֑ךָ] em-mão-tua e-eles [לְרַגְלֶ֔ךָ] [יִשָּׂ֖א] [מִדַּבְּרֹתֶֽיךָ] [sem-traducao]');
INSERT INTO verses VALUES (5816, 5, 33, 4, '[תּוֹרָ֥ה] [צִוָּה־לָ֖נוּ] para-nós Moisés [קְהִלַּ֥ת] [יַעֲקֹֽב] Jacó');
INSERT INTO verses VALUES (5817, 5, 33, 5, 'e-houve [בִישֻׁר֖וּן] rei [בְּהִתְאַסֵּף֙] [רָ֣אשֵׁי] povo [יַ֖חַד] tribos-de Israel');
INSERT INTO verses VALUES (5818, 5, 33, 6, '[יְחִ֥י] [רְאוּבֵ֖ן] e-a e-seja E-foi [מִסְפָּֽר׃]');
INSERT INTO verses VALUES (5819, 5, 33, 7, '[וְזֹ֣את] [לִֽיהוּדָה֮] E-disse ouviu yhwh voz Judá e-a [תְּבִיאֶ֑נּוּ] [יָדָיו֙] suas-maos a-ele a-ele [מִצָּרָ֖יו] [תִּהְיֶֽה׃] [sem-traducao]');
INSERT INTO verses VALUES (5820, 5, 33, 8, '[וּלְלֵוִ֣י] disse [תֻּמֶּ֥יךָ] [וְאוּרֶ֖יךָ] para-homem [חֲסִידֶ֑ךָ] que [נִסִּיתוֹ֙] [בְּמַסָּ֔ה] [תְּרִיבֵ֖הוּ] sobre [מְרִיבָֽה] [sem-traducao]');
INSERT INTO verses VALUES (5821, 5, 33, 9, '[הָאֹמֵ֞ר] [לְאָבִ֤יו] [וּלְאִמּוֹ֙] não [רְאִיתִ֔יו] e-[OBJ] não não [וְאֶת־*בנו] e-[OBJ] não conheceu que [שָֽׁמְרוּ֙] [אִמְרָתֶ֔ךָ] [וּבְרִֽיתְךָ֖] [יִנְצֹֽרוּ]');
INSERT INTO verses VALUES (5822, 5, 33, 10, '[יוֹר֤וּ] [מִשְׁפָּטֶ֙יךָ֙] a-Jacó [וְתוֹרָתְךָ֖] [לְיִשְׂרָאֵ֑ל] [יָשִׂ֤ימוּ] [קְטוֹרָה֙] [בְּאַפֶּ֔ךָ] [וְכָלִ֖יל] sobre [sem-traducao]');
INSERT INTO verses VALUES (5823, 5, 33, 11, 'abençoou yhwh [חֵיל֔וֹ] [וּפֹ֥עַל] mãos-dele [תִּרְצֶ֑ה] [מְחַ֨ץ] [מָתְנַ֧יִם] [קָמָ֛יו] [וּמְשַׂנְאָ֖יו] de');
INSERT INTO verses VALUES (5824, 5, 33, 12, '[לְבִנְיָמִ֣ן] disse [יְדִ֣יד] yhwh [יִשְׁכֹּ֥ן] [לָבֶ֖טַח] sobre-ele [חֹפֵ֤ף] sobre-ele todo e-entre e-entre [שָׁכֵֽן׃]');
INSERT INTO verses VALUES (5825, 5, 33, 13, '[וּלְיוֹסֵ֣ף] disse [מְבֹרֶ֥כֶת] yhwh terra-dele [מִמֶּ֤גֶד] céus [מִטָּ֔ל] [וּמִתְּה֖וֹם] [רֹבֶ֥צֶת] [תָּֽחַת]');
INSERT INTO verses VALUES (5826, 5, 33, 14, '[וּמִמֶּ֖גֶד] [תְּבוּאֹ֣ת] [שָׁ֑מֶשׁ] [וּמִמֶּ֖גֶד] [גֶּ֥רֶשׁ] meses');
INSERT INTO verses VALUES (5827, 5, 33, 15, '[וּמֵרֹ֖אשׁ] [הַרְרֵי־קֶ֑דֶם] [וּמִמֶּ֖גֶד] [גִּבְע֥וֹת] eternidade');
INSERT INTO verses VALUES (5828, 5, 33, 16, '[וּמִמֶּ֗גֶד] terra [וּמְלֹאָ֔הּ] [וּרְצ֥וֹן] [שֹׁכְנִ֖י] [סְנֶ֑ה] [תָּב֙וֹאתָה֙] para-cabeca José [וּלְקָדְקֹ֖ד] [נְזִ֥יר] [אֶחָֽיו]');
INSERT INTO verses VALUES (5829, 5, 33, 17, '[בְּכ֨וֹר] [שׁוֹר֜וֹ] [הָדָ֣ר] a-ele [וְקַרְנֵ֤י] [רְאֵם֙] [קַרְנָ֔יו] [בָּהֶ֗ם] [עַמִּ֛ים] [יְנַגַּ֥ח] juntos extremidades-de terra e-eles [אֶפְרַ֔יִם] Efraim e-eles milhares-de [sem-traducao]');
INSERT INTO verses VALUES (5830, 5, 33, 18, '[וְלִזְבוּלֻ֣ן] disse [שְׂמַ֥ח] Zebulom [בְּצֵאתֶ֑ךָ] [וְיִשָּׂשכָ֖ר] [בְּאֹהָלֶֽיךָ]');
INSERT INTO verses VALUES (5831, 5, 33, 19, '[עַמִּים֙] monte-de [שָׁ֖ם] nome [זִבְחֵי־צֶ֑דֶק] que justica mares [יִינָ֔קוּ] [וּשְׂפוּנֵ֖י] [טְמ֥וּנֵי] [חֽוֹל׃] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (5832, 5, 33, 20, '[וּלְגָ֣ד] disse [בָּר֖וּךְ] [מַרְחִ֣יב] Gade [כְּלָבִ֣יא] [שָׁכֵ֔ן] [וְטָרַ֥ף] [זְר֖וֹעַ] também');
INSERT INTO verses VALUES (5833, 5, 33, 21, 'E-viu [רֵאשִׁית֙] a-ele porque nome campo-de [סָפ֑וּן] [וַיֵּתֵא֙] [רָ֣אשֵׁי] [עָ֔ם] povo yhwh yhwh fez [עִם־יִשְׂרָאֵֽל׃] com Israel');
INSERT INTO verses VALUES (5834, 5, 33, 22, '[וּלְדָ֣ן] disse [דָּ֖ן] [גּ֣וּר] [אַרְיֵ֑ה] [יְזַנֵּ֖ק] de');
INSERT INTO verses VALUES (5835, 5, 33, 23, '[וּלְנַפְתָּלִ֣י] disse [נַפְתָּלִי֙] sete [רָצ֔וֹן] [וּמָלֵ֖א] [בִּרְכַּ֣ת] yhwh mar [וְדָר֖וֹם] [יְרָֽשָׁה׃]');
INSERT INTO verses VALUES (5836, 5, 33, 24, '[וּלְאָשֵׁ֣ר] disse [בָּר֥וּךְ] [מִבָּנִ֖ים] que haja [רְצוּי֙] [אֶחָ֔יו] [וְטֹבֵ֥ל] [בַּשֶּׁ֖מֶן] [רַגְלֽוֹ]');
INSERT INTO verses VALUES (5837, 5, 33, 25, '[בַּרְזֶ֥ל] [וּנְחֹ֖שֶׁת] [מִנְעָלֶ֑יךָ] [וּכְיָמֶ֖יךָ] [דָּבְאֶֽךָ]');
INSERT INTO verses VALUES (5838, 5, 33, 26, 'não-há [כָּאֵ֖ל] [יְשֻׁר֑וּן] [רֹכֵ֤ב] céus [בְעֶזְרֶ֔ךָ] [וּבְגַאֲוָת֖וֹ] [שְׁחָקִֽים]');
INSERT INTO verses VALUES (5839, 5, 33, 27, '[מְעֹנָה֙] [Elohim] oriente [וּמִתַּ֖חַת] [זְרֹעֹ֣ת] eternidade [וַיְגָ֧רֶשׁ] [מִפָּנֶ֛יךָ] [אוֹיֵ֖ב] E-disse [הַשְׁמֵֽד]');
INSERT INTO verses VALUES (5840, 5, 33, 28, '[וַיִּשְׁכֹּן֩] Israel [בֶּ֤טַח] [בָּדָד֙] olho Jacó a terra [וְתִיר֑וֹשׁ] [אַף־שָׁמָ֖יו] também [טָֽל]');
INSERT INTO verses VALUES (5841, 5, 33, 29, '[אַשְׁרֶ֨יךָ] Israel quem [כָמ֗וֹךָ] povo [נוֹשַׁ֣ע] em-יהוה escudo-de [עֶזְרֶ֔ךָ] [וַאֲשֶׁר־חֶ֖רֶב] espada [וְיִכָּֽחֲשׁ֤וּ] [אֹיְבֶ֙יךָ֙] para-ti para-ti e-tu sobre');
INSERT INTO chapters VALUES (187, 5, 34, 12);
INSERT INTO verses VALUES (5842, 5, 34, 1, 'e-subiu Moisés [מֵֽעַרְבֹ֤ת] Moabe a monte-de [רֹ֚אשׁ] cabeça [אֲשֶׁ֖ר] que sobre face-de yhwh [אֶת־כָּל־הָאָ֛רֶץ] yhwh a todo a-terra a até');
INSERT INTO verses VALUES (5843, 5, 34, 2, 'e-[OBJ] todo Naftali e-[OBJ] terra e-[OBJ] [כָּל־אֶ֣רֶץ] e-[OBJ] até o-mar Judá até o-mar o-último');
INSERT INTO verses VALUES (5844, 5, 34, 3, 'e-[OBJ] [וְֽאֶת־הַכִּכָּ֞ר] e-[OBJ] [יְרֵח֛וֹ] [עִ֥יר] [הַתְּמָרִ֖ים] cidade até');
INSERT INTO verses VALUES (5845, 5, 34, 4, 'E-disse yhwh a-ele esta a-terra que [נִ֠שְׁבַּעְתִּי] para-Abraão para-Isaque [וּֽלְיַעֲקֹב֙] dizendo [לְזַרְעֲךָ֖] [אֶתְּנֶ֑נָּה] [הֶרְאִיתִ֣יךָ] [בְעֵינֶ֔יךָ] [וְשָׁ֖מָּה] não [תַעֲבֹֽר]');
INSERT INTO verses VALUES (5846, 5, 34, 5, 'E-morreu nome Moisés servo- yhwh em-terra-de Moabe yhwh yhwh');
INSERT INTO verses VALUES (5847, 5, 34, 6, '[וַיִּקְבֹּ֨ר] ele [בַגַּיְ֙] em-terra-de Moabe [מ֖וּל] casa [פְּע֑וֹר] e-não conheceu homem até o-dia até');
INSERT INTO verses VALUES (5848, 5, 34, 7, 'e-Moisés filho-de cem e-vinte ano [לֹֽא־כָהֲתָ֥ה] não [וְלֹא־נָ֥ס] [לֵחֹֽה] e-não');
INSERT INTO verses VALUES (5849, 5, 34, 8, '[וַיִּבְכּוּ֩] filhos-de Israel a Moisés [מוֹאָ֖ב] Moabe dia dia dias-de dias-de [אֵ֥בֶל] [מֹשֶֽׁה] Moisés');
INSERT INTO verses VALUES (5850, 5, 34, 9, '[וִֽיהוֹשֻׁ֣עַ] filho-de Nun espírito espírito [כִּֽי־סָמַ֥ךְ] porque [אֶת־יָדָ֖יו] Moisés a a-ele sobre-ele [וַֽיַּעֲשׂ֔וּ] [כַּאֲשֶׁ֛ר] filhos-de yhwh [אֶת־מֹשֶֽׁה] como ordenou yhwh a Moisés');
INSERT INTO verses VALUES (5851, 5, 34, 10, 'e-não [נָבִ֥יא] profeta ainda [כְּמֹשֶׁ֑ה] [אֲשֶׁר֙] que yhwh yhwh face a face');
INSERT INTO verses VALUES (5852, 5, 34, 11, 'para-todo [וְהַמּוֹפְתִ֗ים] [אֲשֶׁ֤ר] que yhwh yhwh para-fazer em-terra-de Egito [וּלְכָל־עֲבָדָ֖יו] e-para-todo-');
INSERT INTO verses VALUES (5853, 5, 34, 12, '[וּלְכֹל֙] [הַיָּ֣ד] [הַחֲזָקָ֔ה] [וּלְכֹ֖ל] [הַמּוֹרָ֣א] [הַגָּד֑וֹל] que fez Moisés aos-olhos-de todo Israel');
INSERT INTO books VALUES (6, 'JOS', 'Josué', 'AT', 24);
INSERT INTO chapters VALUES (188, 6, 1, 18);
INSERT INTO verses VALUES (5854, 6, 1, 1, 'e-houve depois-de morrendo Moisés servo yhwh E-disse yhwh a Yehoshua filho-de Nun dizendo Moisés para-dizer');
INSERT INTO verses VALUES (5855, 6, 1, 2, 'Moisés servo-meu morreu e-agora levantou passa a o-Jordão tu tu e-todo o-povo esta eu a-terra a-eles eu deu a-eles para-filhos-de Israel');
INSERT INTO verses VALUES (5856, 6, 1, 3, 'todo lugar que pisará palma-de a-vós nele para-vós dei-o como-que falei a Moisés');
INSERT INTO verses VALUES (5857, 6, 1, 4, 'desde-o-deserto e-o-Líbano o-este e-até o-rio o-grande rio-de terra todo terra os-heteus e-até o-mar será pôr-de o-sol será território-vosso');
INSERT INTO verses VALUES (5858, 6, 1, 5, 'não se-posicionará homem diante-de-ti dias-de tua-vida vida-tua como estive com Moisés não contigo não te-abandonarei e-não te-deixarei');
INSERT INTO verses VALUES (5859, 6, 1, 6, 'forte e-corajoso que tu farás-herdar a o-povo esta a a-terra que a-eles para-pais-deles a-dar para-eles');
INSERT INTO verses VALUES (5860, 6, 1, 7, 'somente forte e-corajoso muito para-guardar para-fazer conforme-toda a-Torah que ordenou-te Moisés servo-meu nós te-desviará dele direita e-esquerda para-que prosperarás em-todo que andares');
INSERT INTO verses VALUES (5861, 6, 1, 8, 'não se-afastará livro-de a-Torah o-este de-boca-tua e-meditarás em-ele dia e-noite a-fim-de guardares para-fazer conforme-toda o-escrito nele porque então farás-prosperar a caminhos-teus e-então prosperarás');
INSERT INTO verses VALUES (5862, 6, 1, 9, 'não ordenei-te forte e-corajoso a temerás que te-desanimarás yhwh contigo yhwh Elohim-teu em-todo que andares');
INSERT INTO verses VALUES (5863, 6, 1, 10, 'E-ordenou Yehoshua a oficiais-de dizendo para-dizer');
INSERT INTO verses VALUES (5864, 6, 1, 11, 'passai em-meio-de o-acampamento e-ordenai a o-povo dizendo preparai a-vós provisão que em-ainda três-de dias vós passando a o-Jordão esta para-vir para-possuir a a-terra yhwh yhwh Elohim-vosso a-vós para-vocês para-possuí-la');
INSERT INTO verses VALUES (5865, 6, 1, 12, 'e-para-o-rubenita e-para-o-gadita e-para-metade-de tribo-de o-Manassés disse Yehoshua dizendo');
INSERT INTO verses VALUES (5866, 6, 1, 13, 'lembrar a a-palavra que ordenou a-vós Moisés dizendo yhwh para-dizer yhwh a-vós dando-descanso a-vós e colocou para-vocês a a-terra a esta');
INSERT INTO verses VALUES (5867, 6, 1, 14, 'mulheres-de-vocês crianças-de-vocês e-gado-de-vocês habitarão na-a-terra que dar a-vós Moisés em-além-de o Jordão e-vocês passarão armados diante-de irmãos-de-vocês todo valentes-de a-força e-ajudarão a-eles');
INSERT INTO verses VALUES (5868, 6, 1, 15, 'até que yhwh יְהוָה para-irmãos-de-vocês como-vocês e-possuirão também eles a a-terra que a-eles אֱלֹהִים-de-vocês deu para-eles e-retornarão para-terra-de herança-de-vocês e-possuirão dar a-vós deu para-vós yhwh servo yhwh em-além-de o Jordão nascente-de o-sol');
INSERT INTO verses VALUES (5869, 6, 1, 16, 'e-responderam a dizendo para-dizer todo que ordenaste-nos foi-feito e-a todo que enviares-nos iremos');
INSERT INTO verses VALUES (5870, 6, 1, 17, 'como-tudo que ouvimos a Moisés assim ouviremos será yhwh será yhwh Elohim-teu ser como-que foi com Moisés');
INSERT INTO verses VALUES (5871, 6, 1, 18, 'todo homem que rebelar-se a a-todo e-não ouvir a palavras-de-ti para-todo que ordenares-nos morrerá somente forte e-corajoso');
INSERT INTO chapters VALUES (189, 6, 2, 24);
INSERT INTO verses VALUES (5872, 6, 2, 1, 'e-enviou Nun de a-Shittim dois homens espiões secretamente dizendo ide vede a a-terra e-a Jericó e-foram e-vieram casa-de mulher prostituta e-nome-de-ela Rahab e-deitaram-se ali');
INSERT INTO verses VALUES (5873, 6, 2, 2, 'E-disse para-rei-de Jericó dizendo eis homens vieram aqui a-noite de-filhos-de Israel para-escavar a a-terra');
INSERT INTO verses VALUES (5874, 6, 2, 3, 'e-enviou rei Jericó a dizendo para-dizer tira os-homens os-vindo para-ti que que para-casa-de-ti porque para-escavar a todo a-terra vieram');
INSERT INTO verses VALUES (5875, 6, 2, 4, 'e-tomou a-mulher a segundo os-homens E-disse e-disse sim vieram a-mim os-homens e-não conheci de-onde eles');
INSERT INTO verses VALUES (5876, 6, 2, 5, 'e-houve o-portão para-fechar na-a-escuridão e-os-homens saíram não soube para-onde foram os-homens persegui rapidamente atrás-de-eles que alcançarão-eles');
INSERT INTO verses VALUES (5877, 6, 2, 6, 'e-ela subiu-eles o-telhado e-escondeu-eles em-linho-de a-árvore as-arrumadas para-ela sobre o-teto');
INSERT INTO verses VALUES (5878, 6, 2, 7, 'e-os-homens perseguiram atrás-deles o-caminho-de o-Jordão sobre as-passagens e-o-portão fecharam depois como saíram os-perseguidores depois-deles');
INSERT INTO verses VALUES (5879, 6, 2, 8, 'e-eles ainda-não se-deitarão e-ela subiu sobre-eles sobre o-teto');
INSERT INTO verses VALUES (5880, 6, 2, 9, 'E-disse a os-homens eu-sei yhwh a-vós yhwh para-vocês a a-terra e-porque caiu terror-vosso a-terra e-que derreteram todo habitantes-de a-terra de-diante-vosso');
INSERT INTO verses VALUES (5881, 6, 2, 10, 'que ouvimos a que yhwh yhwh a águas-de mar-de Suf de-diante-vosso em-sair-vosso de-Egito e-que fizestes a-dois-de reis-de o-amorreu que em-lado-de o-Jordão a-Siom e-a-Ogue que destruístes eles');
INSERT INTO verses VALUES (5882, 6, 2, 11, 'e-ouvimos e-derreteu coração-nosso e-não levantou espírito espírito em-homem que yhwh yhwh ele ele Elohim nos-céus de-acima e-sobre a-terra de-baixo');
INSERT INTO verses VALUES (5883, 6, 2, 12, 'e-agora jurai agora a-mim em-יהוה porque fiz com-vós bondade e-fareis também vós com casa pai-meu bondade e-dareis para-mim sinal-de verdade');
INSERT INTO verses VALUES (5884, 6, 2, 13, 'e-preservareis a pai-meu e-a mãe-minha e-a irmãos-meus e-a a-eles todo que para-eles e-livrareis a almas-nossas de-morte');
INSERT INTO verses VALUES (5885, 6, 2, 14, 'e-disseram para-ela os-homens alma-nossa debaixo-vosso para-morrer mãe não revelardes a palavra-nossa esta e-será em-dar yhwh a-nós a a-terra e-faremos contigo bondade e-verdade');
INSERT INTO verses VALUES (5886, 6, 2, 15, 'e-desceu-eles com-corda através-de a-janela que casa-dela em-muro-de a-muralha e-na-muralha ela habitava');
INSERT INTO verses VALUES (5887, 6, 2, 16, 'E-disse a-eles a-montanha ide para-que-não encontrem em-vós os-perseguidores e-escondei-vos para-lá três-de até até voltaram os-perseguidores e-depois ireis para-caminho-vosso');
INSERT INTO verses VALUES (5888, 6, 2, 17, 'e-disseram para-ela os-homens livres nós de-juramento-teu este que fizeste-jurar-nos');
INSERT INTO verses VALUES (5889, 6, 2, 18, 'eis nós vindo em-a-terra a corda-de fio o-escarlate o-este amarrarás na-janela que nele nele e-a pai-teu e-a mãe-tua e-a irmãos-teus e-את todo casa pai-teu reunirás para-ti a-casa-para');
INSERT INTO verses VALUES (5890, 6, 2, 19, 'e-será todo que sair de-portas-de casa-tua a-fora sangue-seu em-cabeça-sua e-nós livres e-tudo que será contigo na-casa sangue-seu em-cabeça-nossa se mão será- em-ele');
INSERT INTO verses VALUES (5891, 6, 2, 20, 'e-se contares a palavra-nossa esta e-seremos livres de-juramento-teu que fizeste-jurar-nos');
INSERT INTO verses VALUES (5892, 6, 2, 21, 'E-disse conforme-palavras-vossas assim ele e-enviou-os e-foram e-amarrou a corda-de o-escarlate na-janela');
INSERT INTO verses VALUES (5893, 6, 2, 22, 'e-foram e-vieram a-montanha e-permaneceram nome três-de dias até voltaram os-perseguidores e-procuraram os-perseguidores em-todo o-caminho e-não acharam');
INSERT INTO verses VALUES (5894, 6, 2, 23, 'e-voltaram segundo os-homens e-desceram de-o-monte e-atravessaram e-vieram a Yehoshua filho-de נ֑וּן e-contaram a-ele a todo as-que-acharam a-eles');
INSERT INTO verses VALUES (5895, 6, 2, 24, 'e-disseram a Yehoshua yhwh deu yhwh em-mão-nossa a a-terra a-terra e-também derreteram todo habitantes-de a-terra de-face-nossa');
INSERT INTO chapters VALUES (190, 6, 3, 17);
INSERT INTO verses VALUES (5896, 6, 3, 1, 'e-levantou-cedo יְהוֹשֻׁעַ na-manhã e-partiram de-הַשִׁטִּ֗ים e-vieram até ele ele e-todo filhos-de Israel ainda-não nome antes atravessassem');
INSERT INTO verses VALUES (5897, 6, 3, 2, 'e-houve de-fim-de três-de dias e-atravessaram os-oficiais em-meio-de o-acampamento');
INSERT INTO verses VALUES (5898, 6, 3, 3, 'e-ordenaram a dizendo dizendo quando-verdes-vós com arca em-aliança-de yhwh אֱלֹהִים-de-vós e-os-sacerdotes ele carregando a-ela e-vós partireis de-lugar-de-vós e-andareis atrás-dele');
INSERT INTO verses VALUES (5899, 6, 3, 4, 'somente distante será será como-duas-mil côvado na-medida a vos-aproximeis a-ele para-que a-ele saibais a o-caminho que andais que não não passastes no-caminho de-ontem terceiro-dia');
INSERT INTO verses VALUES (5900, 6, 3, 5, 'E-disse יְהוֹשֻׁעַ a o-povo que porque amanhã yhwh yhwh em-meio-de-vós maravilhas');
INSERT INTO verses VALUES (5901, 6, 3, 6, 'E-disse יְהוֹשֻׁעַ a dizendo para-dizer levantai a arca a-aliança e-passai diante-de o-povo e-levantaram a arca a-aliança e-foram diante-de o-povo');
INSERT INTO verses VALUES (5902, 6, 3, 7, 'E-disse yhwh a o-dia o-dia o-este começarei engrandecer-te em-olhos-de todo Israel que saberão porque como-que estive com Moisés estarei contigo');
INSERT INTO verses VALUES (5903, 6, 3, 8, 'e-tu ordenarás a os-sacerdotes carregadores-de dizendo a-aliança para-dizer quando-virdes até extremidade-de águas-de o-Jordão no-Jordão ficareis-em-pé');
INSERT INTO verses VALUES (5904, 6, 3, 9, 'E-disse Yehoshua a filhos-de Israel aproximai-vos elas e-ouvi yhwh palavras-de yhwh אֱלֹהִים-de-vós');
INSERT INTO verses VALUES (5905, 6, 3, 10, 'E-disse Yehoshua nisto sabereis que El vida em-meio-vosso e-despossuir despossuirá de-diante-de-vós a o-cananeu e-a o-heteu e-a o-heveu e-a o-perizeu e-a o-girgaseu e-o-amorreu e-o-jebuseu');
INSERT INTO verses VALUES (5906, 6, 3, 11, 'eis arca a-aliança senhor-de todo a-terra passando diante-de-vós no-Jordão');
INSERT INTO verses VALUES (5907, 6, 3, 12, 'e-agora tomai a-vós segundo dez homem de-tribos-de Israel homem um homem um para-a-tribo');
INSERT INTO verses VALUES (5908, 6, 3, 13, 'e-será quando-repousar plantas-de pés-de os-sacerdotes carregadores-de arca-de yhwh senhor todo a-terra em-águas-de o-Jordão águas-de o-Jordão serão-cortadas as-águas as-descendo de-acima e-ficarão-em-pé um um');
INSERT INTO verses VALUES (5909, 6, 3, 14, 'e-houve quando-partiram o-povo de-tendas-deles para-passar a o Jordão e-os-sacerdotes a-arca a-aliança diante-de o-povo');
INSERT INTO verses VALUES (5910, 6, 3, 15, 'e-quando-vir carregadores-de a-arca até o-Jordão e-pés-de os-sacerdotes carregadores-de a-arca mergulharam as-águas as-águas e-o-Jordão enchei sobre dias-de margens-suas todo dias-de colheita');
INSERT INTO verses VALUES (5911, 6, 3, 16, 'e-pararam as-águas os-descentes de-acima levantaram-se monte- um muito muito a-cidade que de-lado-de Tsaretã e-os-descentes sobre sobre mar mar- o-sal acabaram foram-cortados e-o-povo atravessaram diante Jericó');
INSERT INTO verses VALUES (5912, 6, 3, 17, 'e-pararam os-sacerdotes carregadores-de a-arca em-aliança-de yhwh no-meio-de em-meio-de o Jordão o-firme e-todo Israel até no-seco até que acabou todo a-nação para-atravessar a o-Jordão');
INSERT INTO chapters VALUES (191, 6, 4, 24);
INSERT INTO verses VALUES (5913, 6, 4, 1, 'e-houve conforme- acabaram todo a-nação para-atravessar E-disse yhwh E-disse dizendo a Yehoshua para-dizer');
INSERT INTO verses VALUES (5914, 6, 4, 2, 'tomem a-vós de o-povo dois dez homens homem um homem um de-tribo');
INSERT INTO verses VALUES (5915, 6, 4, 3, 'e-ordenem a-eles dizendo carreguem- para-vocês deste de-meio-de o-Jordão de-lugar-fixo-de pés-de os-sacerdotes preparado duas- dez pedras e-façam-atravessar elas com-vocês e-depositem a-eles nele a-noite pernoitarão em-ele a-noite');
INSERT INTO verses VALUES (5916, 6, 4, 4, 'E-chamou Josué a dois os-doze homem que preparou de-filhos-de Israel homem um homem um de-tribo');
INSERT INTO verses VALUES (5917, 6, 4, 5, 'E-disse a-eles Yehoshua atravessem diante-de arca-de yhwh אֱלֹהִים-de-vocês a meio-de o Jordão a-vós para-vocês pedra uma uma sobre ombro-seu conforme-número-de tribos-de filhos-de Israel');
INSERT INTO verses VALUES (5918, 6, 4, 6, 'para-que seja esta sinal em-meio-vosso porque perguntarem filhos-de-vocês dizendo dizendo que as-pedras a-vós para-vocês');
INSERT INTO verses VALUES (5919, 6, 4, 7, 'e-dirão a-eles que foram-cortadas de-águas-de o-Jordão de-diante-de arca-de em-aliança-de yhwh em-atravessar-sua no-Jordão foram-cortadas águas-de e-sejam e-serão as-pedras estes para-memória para-filhos-de Israel até eternidade');
INSERT INTO verses VALUES (5920, 6, 4, 8, 'e-fizeram assim filhos-de Israel como-que ordenou Yehoshua e-levantaram duas-de dez pedras de-meio-de yhwh como-que palavra yhwh a Yehoshua conforme-número-de tribos-de filhos-de Israel e-fizeram-passar-eles com-eles a o-lugar-de-pernoite e-colocaram-eles nome');
INSERT INTO verses VALUES (5921, 6, 4, 9, 'e-duas dez pedras levantou Yehoshua no-meio-de o-Jordão debaixo lugar-de pés-de os-sacerdotes carregadores-de arca-de a-aliança e-estavam nome até o-dia a-esta');
INSERT INTO verses VALUES (5922, 6, 4, 10, 'e-os-sacerdotes carregadores-de a-arca permanecendo no-meio-de o-Jordão até completar-se todo a-palavra yhwh ordenou yhwh a יְהוֹשֻׁעַ para-falar a o-povo conforme-tudo que ordenou Moisés a Yehoshua e-apressaram-se o-povo e-passaram-se');
INSERT INTO verses VALUES (5923, 6, 4, 11, 'e-houve como- completou todo o-povo de-passar e-passou arca-de yhwh e-os-sacerdotes diante-de o-povo');
INSERT INTO verses VALUES (5924, 6, 4, 12, 'e-passaram filhos-de Reuben e-filhos-de Gad e-metade-de tribo-de o-Manasseh armados diante-de filhos-de Israel como palavra a-eles Moisés');
INSERT INTO verses VALUES (5925, 6, 4, 13, 'como-quarenta mil armados-de o-exército passaram diante-de yhwh para-a-guerra a planícies-de Jericó');
INSERT INTO verses VALUES (5926, 6, 4, 14, 'no-dia aquele engrandeceu yhwh a Yehoshua em-olhos-de todo ele e-reverenciaram a-ele como reverenciaram a Moisés todo dias-de vida-dele');
INSERT INTO verses VALUES (5927, 6, 4, 15, 'E-disse yhwh a dizendo para-dizer');
INSERT INTO verses VALUES (5928, 6, 4, 16, 'ordena a os-sacerdotes carregadores-de arca-de o-testemunho e-subam de o-Jordão');
INSERT INTO verses VALUES (5929, 6, 4, 17, 'E-ordenou Yehoshua a dizendo para-dizer subam de o-Jordão');
INSERT INTO verses VALUES (5930, 6, 4, 18, 'e-houve os-sacerdotes carregadores-de arca-de em-aliança-de yhwh de-meio-de o-Jordão foram-arrancados solas-de pés-de os-sacerdotes El a e-voltaram águas-de o-Jordão para-lugar-deles e-caminharam como-ontem anteontem sobre todo margens-dele');
INSERT INTO verses VALUES (5931, 6, 4, 19, 'e-o povo subiram de o-Jordão em-o décimo para-o-mês o-primeiro e-acamparam em-o Gilgal em-extremidade-de oriente Jericó');
INSERT INTO verses VALUES (5932, 6, 4, 20, 'e-את duas-de quinze as pedras os-estes que tomaram de o Jordão levantou Yehoshua em-o Gilgal');
INSERT INTO verses VALUES (5933, 6, 4, 21, 'E-disse a filhos-de dizendo para-dizer que perguntarem filhos-de-vocês amanhã dizendo pais-de-eles para-dizer que as pedras as estas');
INSERT INTO verses VALUES (5934, 6, 4, 22, 'e-fareis-conhecer a dizendo para-dizer em-a seca passou Israel a o Jordão a-esta');
INSERT INTO verses VALUES (5935, 6, 4, 23, 'que yhwh yhwh אֱלֹהִים-de-vós a águas-de o Jordão de-faces-de-vós até yhwh como-que fez yhwh אֱלֹהִים-de-vós para-mar-de juncos que secou de-faces-de-nós até passarmos-nós');
INSERT INTO verses VALUES (5936, 6, 4, 24, 'para-propósito-de conhecimento todo a-terra a-terra yhwh que yhwh porque forte ela para-propósito-de temerdes-vós a yhwh Elohim de-vós todo os dias');
INSERT INTO chapters VALUES (192, 6, 5, 15);
INSERT INTO verses VALUES (5937, 6, 5, 1, 'e-houve como-ouvir-de todo reis-de o amorreus que em-lado-de o Jordão mar-direção e-todo reis-de o-cananeu que sobre yhwh את que de-diante-de yhwh a águas-de o Jordão de-faces-de filhos-de Israel até espírito de-diante-de e-não foi em-eles ainda espírito de-face-de filhos-de Israel');
INSERT INTO verses VALUES (5938, 6, 5, 2, 'em-o-tempo a aquela disse yhwh a Yehoshua a-ti para-ti espadas-de pedras e-retorna circuncidar a filhos-de Israel segunda');
INSERT INTO verses VALUES (5939, 6, 5, 3, 'e-fez para-ele Yehoshua espadas-de pedras e-circuncidou a filhos-de Israel a colina-de os prepúcios');
INSERT INTO verses VALUES (5940, 6, 5, 4, 'e-esta a palavra que circuncidou Yehoshua todo o-povo o-saindo de-a-Egito os-masculinos todas homens-de a-guerra [בַמִּדְבָּר֙] em-o-deserto em-a-caminho em-sair-de-eles de-Egito');
INSERT INTO verses VALUES (5941, 6, 5, 5, 'porque sendo-os foram todo o-povo os-saindo e-todo o-povo os-nascendo em-o-deserto em-a-caminho na-saída-deles de-misraim não encheram.');
INSERT INTO verses VALUES (5942, 6, 5, 6, 'que quarenta ano caminharam filhos-de Israel no-o-deserto até acabou todo o-povo homens-de a-guerra os-que-saem do-Egito que yhwh ouviram com-voz yhwh a-eles para-não yhwh a-eles para-não mostrá-los yhwh a-terra que jura terra aos-seus-pais para-dar para-nós terra fluindo-de leite e-mel');
INSERT INTO verses VALUES (5943, 6, 5, 7, 'e-a os-filhos-deles levantou eles eles circuncidou Yehoshua porque que foram-se porque não circuncidaram-se eles no-caminho');
INSERT INTO verses VALUES (5944, 6, 5, 8, 'e-houve conforme- terminaram todo o-povo para-ser-circuncidado e-habitaram até no-acampamento até vivas-eles');
INSERT INTO verses VALUES (5945, 6, 5, 9, 'E-disse yhwh a o-dia o-dia revelarei a desonra E-chamou de-vocês E-chamou nome o-lugar até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (5946, 6, 5, 10, 'e-acamparam filhos-de Israel em-Gilgal e-fizeram a o-Pesque dia dez dia para-o-mês na-noite nas-arvores Jericó');
INSERT INTO verses VALUES (5947, 6, 5, 11, 'e-comeram de-a a-terra da-o o-páscoa massots e-lavado בְּעֶ֖צֶם o-dia a-esta');
INSERT INTO verses VALUES (5948, 6, 5, 12, 'e-parou o-manne da-o em-comerem de-a a-terra e-não foi ainda para-filhos-de Israel de e-comeram terra terra Canaã na-ano a-ela');
INSERT INTO verses VALUES (5949, 6, 5, 13, 'e-houve em-ser Yehoshua e-Biriohu va-yiss-a os-seus-olhos E-viu e-eis- homem ficou-em-pé para-o-frente-dele e-sua-espada desembainhada na-sua-mão E-andou a-ele E-disse a-ele a-ele tu tu se para-nossos-inimigos');
INSERT INTO verses VALUES (5950, 6, 5, 14, 'E-disse não não que príncipe-de exército- yhwh agora venho-eu e-ele-caiu יְהוֹשֻׁעַ a de-seus-faces E-disse a-ele E-disse a-ele que Adonai que-está-falando a seu-servo');
INSERT INTO verses VALUES (5951, 6, 5, 15, 'E-disse príncipe-de yhwh yhwh a de-cima-de deite-se- que de-sobre teus-pés tu o-lugar que tu ele sobre-ele santo-de ele E-fez Yehoshua assim');
INSERT INTO chapters VALUES (193, 6, 6, 27);
INSERT INTO verses VALUES (5952, 6, 6, 1, 'e-Jericó fechada e-fechando-se de-diante-de filhos-de Israel não-há saindo e-não-há veio');
INSERT INTO verses VALUES (5953, 6, 6, 2, 'E-disse yhwh a Yehoshua dei dei em-tua-mão a Jericó e-a de-a-sua-majestade os-gibores da-habilidade');
INSERT INTO verses VALUES (5954, 6, 6, 3, 'e-vos-sabei a a-cidade todo homens-de a-guerra o-circumfere vez a-cidade vez um assim você-fará seis-de dias');
INSERT INTO verses VALUES (5955, 6, 6, 4, 'e-sete os-sacerdotes elevá-los sete trombetas dos-jubileus diante-de o-arca e-no-dia o-sétimo virem-se a a-cidade sete vezes e-os-sacerdotes tocarão com-trombetas');
INSERT INTO verses VALUES (5956, 6, 6, 5, 'e-será ao-som bqueren hayovel a voz-de o-shofar yarieu todo o-povo grito grande venafelah chomath a-cidade tachatetha vealou o-povo homem negdoo');
INSERT INTO verses VALUES (5957, 6, 6, 6, 'E-chamou Josué filho-de Nun E-disse os-sacerdotes E-disse a-eles saeu a arca a-aliança veshivah sacerdotes elevem sete chifres yhwh diante-de arca yhwh');
INSERT INTO verses VALUES (5958, 6, 6, 7, 'a o-povo transponham e-virem-se a a-cidade e-o-avançado passe diante-de arca yhwh');
INSERT INTO verses VALUES (5959, 6, 6, 8, 'e-houve como-diz Yehoshua a o-povo e-sete os-sacerdotes levando-os sete trombetas das-trombetas-do-yovel yhwh yhwh passaram e-sopram [וֽ͏ַאֲרוֹן֙] e-a-arca yhwh yhwh andou depois-deles');
INSERT INTO verses VALUES (5960, 6, 6, 9, 'e-o-líder andou diante-de os-sacerdotes o-de-trombetas e-o-coletor andou depois-de a-arca indo e-soprar na-trombeta');
INSERT INTO verses VALUES (5961, 6, 6, 10, 'e-a o-povo ordenou dizendo não não [וְלֹֽא־תַשְׁמִ֣יעוּ] e-não [וְלֹא־יֵצֵ֥א] a vozes-vos até dia de-vossas palavra até dia dizei aleichem tirate e-tirastes');
INSERT INTO verses VALUES (5962, 6, 6, 11, 'e-voltou-se arca-de yhwh a vez o-circunvalhe vez um e-vieram o-acampamento e-acamparam-se no-lager');
INSERT INTO verses VALUES (5963, 6, 6, 12, 'e-se-levantou Yehoshua no-manhã e-levantaram os-sacerdotes a yhwh yhwh');
INSERT INTO verses VALUES (5964, 6, 6, 13, 'e-sete os-sacerdotes levando-os sete trombetas das-trombetas diante-de arca yhwh andando-os indo-o e-soprem-os com-trombetas e-o-avante andou em-frente-de-eles e-o-coletor andou depois-de arca yhwh e-soprará em-os-trumpetes');
INSERT INTO verses VALUES (5965, 6, 6, 14, 'e-viraram-se a no-dia no-dia vez uma uma e-eles-retornaram o-acampamento assim fizeram seis-de dias');
INSERT INTO verses VALUES (5966, 6, 6, 15, 'e-houve em-o-dia no-dia e-levantaram-se como-subir no-alvorada e-viraram-se a a-cidade como-o-julgamento este sete vezes somente no-dia aquele deram-volta a a-cidade sete vezes');
INSERT INTO verses VALUES (5967, 6, 6, 16, 'e-houve na-vez a-sétima tocarão os-sacerdotes com-a-trombeta E-disse Josué a o-povo toquem yhwh a-vós yhwh para-vocês a a-cidade');
INSERT INTO verses VALUES (5968, 6, 6, 17, 'e-será a-cidade anátema ela e-todo que nela para-יהוה somente Rachav a-zonah tichye ela e-todo que itah na-casa porque hechbaatah a os-mensageiros que shalachnu');
INSERT INTO verses VALUES (5969, 6, 6, 18, 've-rak- vós shimru de ha-cherev para-que-não tacharimu e-tomem de o-herem e-simetem a de-acampamento Israel para-o-herem e-espalharam isso');
INSERT INTO verses VALUES (5970, 6, 6, 19, 'e-tudo prata e-ouro e-ferramentas-de de-bronze e-ferro santidade-de ele ele tesouro yhwh yhwh');
INSERT INTO verses VALUES (5971, 6, 6, 20, 'e-ele-se-arruinou o-povo e-eles-bombaram com-os-trumpetes e-houve quando-ouviram o-povo a voz-de o-trumpete e-eles-tocaram o-povo grito grande e-caiu a parede abaixo-dela e-subiu o-povo a-cidade homem em-o-seu-frente e-eles-conquistaram a a-cidade');
INSERT INTO verses VALUES (5972, 6, 6, 21, 'e-eles-consagraram-a-destruição a todo que na-cidade de-homem e-até mulher do-jovem e-até até-o-vieiro e-ad boi e-ovelha e-jumento à-boca-de com-espada');
INSERT INTO verses VALUES (5973, 6, 6, 22, 'e-a-dois os-homens os-espionas a disse disse Yehoshua entrem casa-de a-mulher a-prostituta e-saquem de-aqui a a-mulher e-a todo que para-ela como-que jurastes a-ela');
INSERT INTO verses VALUES (5974, 6, 6, 23, 'e-vieram os-jovens os-espionas e-saíram a Rahab e-a seu-pai e-a sua-mãe e-a seus-irmãos e-a todo que para-ela e-a todo de-seu-clã e-eles-saíram e-ele-os-deixou fora-de para-o-acampamento Israel');
INSERT INTO verses VALUES (5975, 6, 6, 24, 'e-a-cidade e-eles-queimaram em-chamas e-todo que nela somente o-prata e-o-ouro e-ferramentas-de o-bronze e-o-ferro deram tesouro casa-de yhwh');
INSERT INTO verses VALUES (5976, 6, 6, 25, 'e-a Rahab a-prostituta e-a casa seu-pai e-a todo que a-ela até o-dia e-sentou que Israel até o-dia esta porque escondeu-a a os-anjos que enviou Yehoshua para-espiar a Jericó');
INSERT INTO verses VALUES (5977, 6, 6, 26, 'e-jurou Yehoshua em-o tempo aquela dizendo maldito o-homem diante-de yhwh que levante-se e-construa a a-cidade esta a Jericó em-sua-primeira fundará-a e-em-seu-pequeno estabelecerá suas-portas');
INSERT INTO verses VALUES (5978, 6, 6, 27, 'e-houve yhwh a e-houve E-foi seu-ouvido em-todo a-terra');
INSERT INTO chapters VALUES (194, 6, 7, 26);
INSERT INTO verses VALUES (5979, 6, 7, 1, 'e-ele-subiu filhos-de Israel ofensa E-tomou E-tomou Acaão filho-de de-Karémi filho-de Zabdi filho-de [וַיִּֽחַר־אַ֥ף] yhwh Judá de o-anátema e-acendeu-se- nariz yhwh de-filhos Israel');
INSERT INTO verses VALUES (5980, 6, 7, 2, 'e-enviou יְהוֹשֻׁעַ homens de-Mirihô o-Ai que com casa ao-oriente do-leste E-disse El dizendo a-eles dizendo subam e-pé a a-terra e-ele-subiram os-homens e-espiaram a a-ay');
INSERT INTO verses VALUES (5981, 6, 7, 3, 'e-voltaram a Josué a-ele a-ele a subirá todo o-povo como-dois-mil homem ou [יַעֲל֖וּ] milhares homem eles-subirão e-golpearão que a-Ai a você-queixará-se-de lá-baixo a todo o-povo porque pouco eles');
INSERT INTO verses VALUES (5982, 6, 7, 4, 'e-eles-subiram de o-povo ali em-três dois-mil homem e-eles-fugiram diante-de homens-de a-ay');
INSERT INTO verses VALUES (5983, 6, 7, 5, 'e-eles-feriram dentre-eles homens-de a-o-ayin e-trinta וְשִׁשָׁה֙ homem e-os-perseguiram diante-de o-sha-ur até o-shav-riy e-os-golpearam na-murada e-o-derreteu e-houve o-povo E-foi para-a-agua');
INSERT INTO verses VALUES (5984, 6, 7, 6, 'e-ele-arrancou Josué as-suas-roupas e-ele-caiu-se sobre suas-faces na-terra diante-de yhwh yhwh ele no-crepúsculo ele e-os-idosos pó e-eles-subiram pó sobre de-seu-cabeça');
INSERT INTO verses VALUES (5985, 6, 7, 7, 'E-disse Josué ah-ah Adonai yhwh por-quê haveste-nos-passado a-passar a o-povo o-este a o-Jordão a-dar a-nós em-mão-de o-amorreu para-nos-destruirmos e-tendo jurar-nos e-nos-assentamos em-além-de o-Jordão');
INSERT INTO verses VALUES (5986, 6, 7, 8, 'em-mi Adonai que disse depois-de que revolver Israel costas diante-de oyevav');
INSERT INTO verses VALUES (5987, 6, 7, 9, 'e-eles-ouvirão o-canaanita e-tudo habitantes-de a-terra e-nasavu sobre-nós e-hikritu a shemenu de a-terra umah- taaseh leshimcha o-grande');
INSERT INTO verses VALUES (5988, 6, 7, 10, 'E-disse yhwh a Yehoshua para-ti a-ti por-que tu tu caído sobre teu-rosto');
INSERT INTO verses VALUES (5989, 6, 7, 11, 'chatav Israel e-também abru a beriti que ordenei eles e-também lakhu de o-exterminação e-também rouberam e-também e-esconderam e-também colocaram em-seus-instrumentos');
INSERT INTO verses VALUES (5990, 6, 7, 12, 'e-não poderiam filhos-de Israel levantar-se diante-de contra-osseus-inimigos costas virão diante-de inimigos-deles que foram para-o-exílio não aumentar para-ser com-vocês se não exterminem o-exílio de-a-vosso-interior');
INSERT INTO verses VALUES (5991, 6, 7, 13, 'arise santifica a o-povo e-dirás consagrem-vos que porque disse yhwh yhwh Elohim-de Israel exílio em-a-vossa-interior não não podes-te-capaz-de para-levantar-se diante-de teus-inimigos até retirai-vos a-anátema de-meio-de-vós');
INSERT INTO verses VALUES (5992, 6, 7, 14, 'e-vós-vos-aproximar-eis na-manhã para-tribos-de-vós e-será o-bastão que yhwh yhwh se-aproximará para-as-famílias e-a-família yhwh será-capturado-as yhwh te-aproximes para-os-lares e-o-lar yhwh será-capturado-ele yhwh será-aproximado para-os-homens');
INSERT INTO verses VALUES (5993, 6, 7, 15, 'e-foi o-que-for-capturado no-herem queimar-se no-fogo ele e-a que que a-ele yhwh passou a aliança yhwh e-porque fez torpeza em-Israel');
INSERT INTO verses VALUES (5994, 6, 7, 16, 'e-ele-se-levantou יְהוֹשֻׁעַ de-manhã e-ele-se-aproximou a Israel para-os-de-sua-fração e-ele-capturou-se bastão Judá');
INSERT INTO verses VALUES (5995, 6, 7, 17, 'e-aproximou a de-família Judá e-ele-roubou-se a de-a-família o-zarqi va-yakrev a família-de o-zarqi para-os-homens e-ele-se-apoderou-de zabdi');
INSERT INTO verses VALUES (5996, 6, 7, 18, 'e-ele-se-achegou-a a casa-dele para-os-homens e-ele-se-apoderou-de achan filho-de de-Carmi filho-de Zabdi filho-de Zerá para-matate Judá');
INSERT INTO verses VALUES (5997, 6, 7, 19, 'E-disse Josué a Ochan filhos-de põe- por-favor kavod para-יהוה Elohim-de Israel e-tenha a-ele todah e-hagge por-favor para-mim que oashtata a de-mim');
INSERT INTO verses VALUES (5998, 6, 7, 20, 'e-respondeu Achan a Yehoshua E-disse eu eu-sou pecado-eu a-yhwh Elohim-de Israel e-assim-desta-maneira e-assim-desta-maneira fiz');
INSERT INTO verses VALUES (5999, 6, 7, 21, 'nas-presas-da-guerra manto-de Shinar uma bem-boa uma pesos-de-prata prata e-língua dourado um ouro um de-seu-peso e-eu-amei-os e-eu-tomei-os e-eles escondidos na-terra em-meio-de o-meu-tenda no-meio-de abaixo-de-a');
INSERT INTO verses VALUES (6000, 6, 7, 22, 'e-estendeu יְהוֹשֻׁעַ mensageiros e-eles-correram a-tenda-a e-eis ocultação em-o-seu-tenda e-o-prata abaixo-dela-verso');
INSERT INTO verses VALUES (6001, 6, 7, 23, 'e-eles-tomaram-os de-meio-de a-tenda e-eles-trouxeram-os a e-para e-a todo filhos-de Israel yhwh diante-de yhwh');
INSERT INTO verses VALUES (6002, 6, 7, 24, 'E-tomou Yehoshua a Achan filho-de Zerah e-a o-ouro e-a a-adoreret e-a língua-de o-zahav e-a os-banaiu e-a as-bnotaiu e-a eles e-a o-chamoruo e-a o-tsonuo e-com a-aholuo e-a todo que a-ele e-todo Israel com-euomo e-eles-subiram eles emeq akhor');
INSERT INTO verses VALUES (6003, 6, 7, 25, 'E-disse יְהוֹשֻׁעַ que achartanu in-e-o-terra yhwh no-dia esta e-os-lançou-pedras ele todo pedra pedra eles a-elas no-fogo eles eles com-as-pedras');
INSERT INTO verses VALUES (6004, 6, 7, 26, 'e-ele-levantaram sobre-ele montículo-de pedras até o-dia o-dia esta yhwh yhwh de-a-ira seu-nariz chamou assim chamou nome o-lugar o-aquele até o-dia até o-dia a-esta');
INSERT INTO chapters VALUES (195, 6, 8, 35);
INSERT INTO verses VALUES (6005, 6, 8, 1, 'E-disse yhwh a יְהוֹשֻׁעַ a tire-a e-a techa-at toma em-voce a folhas-de povo a-guerra ve-kum dei ha-aya veja dei be-yadecha a rei ha-ay e-a povo-seu e-a cidade-dele e-a terra-dele');
INSERT INTO verses VALUES (6006, 6, 8, 2, 've-asita la-ay ule-malka como-que o-fez-tu Lirihoh u-le-malkah somente shelahah u-be-hemtah a-vós a-vós sim- para-ti orev la-ir me-a-char-e-ha');
INSERT INTO verses VALUES (6007, 6, 8, 3, 'E-levantou יְהוֹשֻׁעַ e-todo povo ha-milchamah para-subir ha-ay va-yibchar Yehôšuwaʻ trinta mil homem valentes-de a-força noite noite');
INSERT INTO verses VALUES (6008, 6, 8, 4, 'E-ordenou eles dizendo re’u atem orvim la-ir de-depois-de a-cidade a tarḥiqu muito e-sereis muito vehitytem voces-todos nekhonim');
INSERT INTO verses VALUES (6009, 6, 8, 5, 'e-eu e-todo o-povo que comigo nikrab a a-cidade e-foi porque yetseu em-nos-a-frente como no-primeiro-tempo e-nós-sairemos diante-deles');
INSERT INTO verses VALUES (6010, 6, 8, 6, 'e-eles-sairão de-nos-a-trás até o-nosso-tique a-eles de que porque dirão nós-sairemos diante-de-nós como no-primeiro-tempo e-nós-sairemos diante-deles');
INSERT INTO verses VALUES (6011, 6, 8, 7, 'e-vós vocês-se-levantarão do-auréu e-vacilareis a a-cidade yhwh yhwh אֱלֹהִים-de-vocês em-mão-vossa');
INSERT INTO verses VALUES (6012, 6, 8, 8, 'e-será com-vossas-mãos a a-cidade תַּצִּ֤יתוּ a a-cidade yhwh conforme-palavra-de yhwh fazeis-vós רְא֖וּ mandei-eu a-vós');
INSERT INTO verses VALUES (6013, 6, 8, 9, 'e-os-enviou Josué e-andaram a o-espião entre entre e-entre El e-entre a-Ai águas [יְהוֹשֻׁ֛עַ] e-ele-pernoitou יְהוֹשֻׁעַ no-meio-de o-aquele em-meio-de o-povo');
INSERT INTO verses VALUES (6014, 6, 8, 10, 'e-ele-levantou-se יְהוֹשֻׁעַ de-manhã e-contou a o-povo ele ele e-os-veteranos-de Israel diante-de o-povo a-ay');
INSERT INTO verses VALUES (6015, 6, 8, 11, 'e-todo o-povo da-guerra que com-ele subiram e-eles-se-aproximaram diante em-frente-de a-cidade e-acamparam do-norte para-a-Ai e-o-valle e-entre a-ay');
INSERT INTO verses VALUES (6016, 6, 8, 12, 'E-tomou como-cinco dois-mil homem e-ele-postou a-eles espião entre casa-de e-entre e-entre a-Ai águas para-a-cidade');
INSERT INTO verses VALUES (6017, 6, 8, 13, 'e-eles-postaram o-povo a todo o-acampamento que do-norte para-a-cidade e-a seu-calcanhar águas para-a-cidade E-andou no-meio-de na-noite o-aquele em-meio-de o-vale:');
INSERT INTO verses VALUES (6018, 6, 8, 14, 'e-houve quando-veem rei-de o-aai e-eles-se-apressaram e-eles-saíram-cedo e-eles-saíram os-homens-de- a-cidade ele Israel para-a-guerra ele e-todo povo-dele não saber o-deserto a-ele não conheceu porque espião para-ele de-após a-cidade');
INSERT INTO verses VALUES (6019, 6, 8, 15, 'יְהוֹשֻׁ֥עַ e-todo Israel em-frente-de-eles e-eles-fugiram o-caminho-de o-meadero');
INSERT INTO verses VALUES (6020, 6, 8, 16, 'e-eles-clamaram todo o-povo que para-perseguir depois-deles e-eles-perseguiram depois-de Yehoshua e-se-separaram de a-cidade');
INSERT INTO verses VALUES (6021, 6, 8, 17, 'e-não ficou homem na-cidade e-Beit El que não saíram depois-de Israel e-eles-abandonaram a a-cidade aberta e-perseguiram atrás-de Israel');
INSERT INTO verses VALUES (6022, 6, 8, 18, 'E-disse yhwh a Josué inclina com-a-lança que que a o-Ai porque em-mão-tua a-ele-aqui e-ele-esticou יְהוֹשֻׁעַ com-a-lança que em-sua-mão a a-cidade');
INSERT INTO verses VALUES (6023, 6, 8, 19, 'e-o-espião levantou-se rapidamente de-sua-locacao e-eles-correram contorção sua-mão e-vieram a-cidade e-os-pegaram-na-a e-eles-se-apressaram e-ele-acendeu a a-cidade em-a-chama');
INSERT INTO verses VALUES (6024, 6, 8, 20, 'e-eles-viraram-se os-homens-de a-Ai atrás-dos-eles e-eles-viram e-eis subir fumo a-cidade dos-céus e-não foi neles mãos para-nascer para-cá e-eis e-o-povo [הַמִּדְבָּ֔ר] o-deserto virado a que-persegue');
INSERT INTO verses VALUES (6025, 6, 8, 21, 'e-Josué e-todo Israel viram porque pegou o-que-espreita subir a-cidade e-que subiu fumo a-cidade e-eles-voltaram e-eles-feriram a homens-de a-ay');
INSERT INTO verses VALUES (6026, 6, 8, 22, 've-Eleh sairam de a-cidade para-eles e-eram para-o-Israel Estas estes de-este e-estes deste e-eles-feriram a-eles até para-não deixar-restar para-ele restante e-fugitivo');
INSERT INTO verses VALUES (6027, 6, 8, 23, 'e-a rei o-Ai tapesu viveu ele ele a יְהוֹשֻֽׁעַ');
INSERT INTO verses VALUES (6028, 6, 8, 24, 'e-houve kechaloth Israel laharog a todo yoshevei haay basadeh bamidbar que redafum nele vayiflu kulam à-boca-de espada até tum-mum e-voltaram todo Israel ha-ay e-eles-feriram a-ela à-boca-de cha-rev');
INSERT INTO verses VALUES (6029, 6, 8, 25, 'e-houve todo no-dia ba-yom o-aquele me-ish e-até mulher dois dez mil todo homens-de a-ay');
INSERT INTO verses VALUES (6030, 6, 8, 26, 've-Yehoshu-a não sua-mão mão-de-ele que na-tah até até que he-chrim a todo habitantes-de a-ay');
INSERT INTO verses VALUES (6031, 6, 8, 27, 'somente os-animais u-shelal a-cidade aquela ba-zez a-eles Israel conforme-a-palavra-de yhwh que ordenou a יְהוֹשֻֽׁעַ');
INSERT INTO verses VALUES (6032, 6, 8, 28, 'e-ele-queimou Yehoshua a a-Ai e-ele-fez-a tumulo- até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (6033, 6, 8, 29, 'e-a rei de-Ai pendurou sobre a-árvore até tempo a-tarde e-quando-entrar o-sol ordenou Josué e-eles-lançaram a sua-carne de a-árvore e-eles-deram a-ela a porta-de até o-dia e-ele-levantaram sobre-ele montículo-de- pedras grande até o-dia a-esta');
INSERT INTO verses VALUES (6034, 6, 8, 30, 'então ele-construirá יְהוֹשֻׁעַ altar a-yhwh Elohim-de Israel na-montanha evém:');
INSERT INTO verses VALUES (6035, 6, 8, 31, 'como-que deu-ordem Moisés servo- yhwh a filhos-de Israel como-está-escrito no-livro lei-de Moisés mizbakh avanim shlemot que não henif alehen barzel vayaalu sobre-o holocaustos para-יהוה shlamim');
INSERT INTO verses VALUES (6036, 6, 8, 32, 'vikhtav- nome sobre as-pedras com segunda lei-de Moisés que escreveu diante-de filhos-de Israel');
INSERT INTO verses VALUES (6037, 6, 8, 33, 'e-todo Israel e-seus-anciãos [׀] e-seus-julgadores estão-stando [מִזֶּ֣ה] [׀] para-a-arca em-frente-de os-sacerdotes diante [הַכֹּהֲנִ֨ים] arca em-aliança-de yhwh como-estrangeiro como-cidadão a-sua-metade a em-face-de monte-de os-garfos e-a-sua-metade a em-face-de monte-de Eival como tzivva Moisés servo- yhwh levarèkh a o-povo Israel barishonah');
INSERT INTO verses VALUES (6038, 6, 8, 34, 'veacharei- chamou chamou a todo palavras-de ha-torah habrakhah vehakhlalah conforme-toda o-escrito besefer ha-torah');
INSERT INTO verses VALUES (6039, 6, 8, 35, 'não foi de-toda de-todo que ordenou Moisés que diante chamou Josué em-frente-de todo assembleia o-que-vai e-as-mulheres e-os-crianças-pequenas e-o-estrangeiro o-andando em-meio-deles-versículo-final');
INSERT INTO chapters VALUES (196, 6, 9, 27);
INSERT INTO verses VALUES (6040, 6, 9, 1, 'e-houve como-ouvir-de todo os-reis que em-lado-de o Jordão na-montanha e-na-planície e-em-todo o-mar ha-yam a-grande a de-frente o-לְבָנ֑וֹן o-hitita e-o-amorreu o-cananeu o-prizi o-hivi e-o-jebuseu');
INSERT INTO verses VALUES (6041, 6, 9, 2, 'e-eles-se-agruparam juntos para-lutar com Yehoshua e-com- um boca um');
INSERT INTO verses VALUES (6042, 6, 9, 3, 'e-os-habitantes-de Gibeon ouvirem את que fez יְהוֹשֻׁעַ a-Lirihoh e-la-ay');
INSERT INTO verses VALUES (6043, 6, 9, 4, 'va-yassu também eles be-ar-mah e-foram va-itz-tay-ro-u ve-yikhu [בָּלִים֙] [לַחֲמ֣וֹרֵיהֶ֔ם] [וְנֹאד֥וֹת] [יַ֙יִן֙] do-vinho [וּמְבֻקָּעִ֖ים] [וּמְצֹרָרִֽים]');
INSERT INTO verses VALUES (6044, 6, 9, 5, '[וּנְעָל֨וֹת] [בָּל֤וֹת] [וּמְטֻלָּאוֹת֙] em-seus-pés [וּשְׂלָמ֥וֹת] [בָּל֖וֹת] sobre-eles e-tudo pão [צֵידָ֔ם] [יָבֵ֖שׁ] ser [נִקֻּדִֽים]');
INSERT INTO verses VALUES (6045, 6, 9, 6, 'e-foram a יְהוֹשֻׁעַ a o-acampamento a-ele e-disseram a-ele e-a homem Israel e-agora [כִּרְתוּ־לָ֥נוּ] [בְרִֽית] para-nós');
INSERT INTO verses VALUES (6046, 6, 9, 7, 'אִישׁ- Israel a [אֶל־הַחִוִּ֑י] talvez [בְּקִרְבִּי֙] tu [יוֹשֵׁ֔ב] e como para-ti [בְרִֽית]');
INSERT INTO verses VALUES (6047, 6, 9, 8, 'e-disseram a Yehoshua servos-teus E-disse E-disse [יְהוֹשֻׁ֛עַ] quem quem vós  ומעין');
INSERT INTO verses VALUES (6048, 6, 9, 9, 'e-disseram a-ele de-terra-de [רְחוֹקָ֤ה] muito vieram teus-servos para-Shem yhwh teu-Elohim porque [שָׁמְע֔וֹ] e-[OBJ] e-a todo que fez em-Egito');
INSERT INTO verses VALUES (6049, 6, 9, 10, 'e-את todo que fez para-dois reis-de o-amorreu que em-além-de o Jordão [לְסִיחוֹן֙] rei Hesbom [וּלְע֥וֹג] rei-de o-Basã que');
INSERT INTO verses VALUES (6050, 6, 9, 11, 'e-disseram אֵלֵינוּ זְקֵינֵינוּ e-todo yoshevei dizendo dizendo tomem בְּיָדֵיכֶם צֵידָה לַדֶּרֶךְ e arrependei-vos para-enfrentá-los e diríamos a-eles nosso servo e-agora e agora cortei-vos para-nós além de um pacto');
INSERT INTO verses VALUES (6051, 6, 9, 12, 'este nossas pães quente nosso fome ele ele em-dia nossas saídas para-andar a-vós e-agora e-agora eis e-foi נקודות׃');
INSERT INTO verses VALUES (6052, 6, 9, 13, 've-Eleh נOADות o-vinho que milLEAnu חֲדָשִ֔ים e-eis hitbAKAQu e-estes שַׁלְמֹתֵינו֙ vUNAAlEyinu balu de-abundância-de o-caminho muito');
INSERT INTO verses VALUES (6053, 6, 9, 14, 'vaYiqCHAchu haANashim mitzCIDam e-a yhwh não não perguntaram:');
INSERT INTO verses VALUES (6054, 6, 9, 15, 'E-fez a-eles יְהוֹשֻׁעַ paz e cortou: a-eles berith para mantê-los: e juraram: a-eles príncipes-de a assembleia:');
INSERT INTO verses VALUES (6055, 6, 9, 16, 'e-houve de-a-extremidade-de três-de dias depois que a-eles a-eles aliança e ouviram: eles a-ele eles: eles e no meio deles: eles moravam:');
INSERT INTO verses VALUES (6056, 6, 9, 17, 'e-partiram filhos-de Israel וַיָּבוֹאֻ no-dia ar-ye-hem em-o-dia terceiro e suas cidades: Gbão e a Kefirá e as Be''orot e a Qiryat Jearim');
INSERT INTO verses VALUES (6057, 6, 9, 18, 'e-não os feriram filhos-de Israel porque a-eles para-eles príncipes-de a-congregação em-יהוה Elohim-de Israel e juraram todo a-congregação sobre os príncipes:');
INSERT INTO verses VALUES (6058, 6, 9, 19, 'e-disseram todo [אֶל־כָּל־הָ֣עֵדָ֔ה] a todo a-eles nós juramos a-eles e-agora não Israel e-agora não nuchal para-sair neles');
INSERT INTO verses VALUES (6059, 6, 9, 20, 'esta faremos a-eles e a vida eles e-não será sobre-nos ira sobre a-eles que juramos para-eles');
INSERT INTO verses VALUES (6060, 6, 9, 21, 'disseram a eles os principais viverão e foram os cortadores de madeiras e os buscadores de águas para-todo a-congregação a-eles דִּבְּר֥וּ a-eles os-néssaim:');
INSERT INTO verses VALUES (6061, 6, 9, 22, 'E-chamou a-eles Yehoshua e-falou a-eles dizendo lamá: rimítitem nós dizendo rakhóqim nós de-vós muito e-vós bəqirvénu yoshvim:');
INSERT INTO verses VALUES (6062, 6, 9, 23, 'e-agora arúrim vós e-não יִכָּרֵת mikem: servo vechotvéi etsim וְשֹֽׁאֲבֵי־ águas segundo-casa-de yhwh');
INSERT INTO verses VALUES (6063, 6, 9, 24, 'e-responderam a Josué que porque foi-relatado foi dito [OBJ] את que yhwh yhwh Elohim-teu a Moisés a-vós [אֶת־כָּל־הָאָ֔רֶץ] para-vocês a a-terra a-terra [וַנִּירָ֨א] muito todo habitantes-de a-terra [אֶת־הַדָּבָ֥ר] [הַזֶּֽה] de-diante-vosso a a-palavra a-esta');
INSERT INTO verses VALUES (6064, 6, 9, 25, 'e-agora [הִנְנ֣וּ] em-mão-tua [כַּטּ֨וֹב] [וְכַיָּשָׁ֧ר] [בְּעֵינֶ֛יךָ] para-fazer para-nós fez');
INSERT INTO verses VALUES (6065, 6, 9, 26, 'E-fez a-eles assim [וַיַּצֵּ֥ל] a-eles de-mão-de filhos-de Israel e-não');
INSERT INTO verses VALUES (6066, 6, 9, 27, 'והיתנם Josué no-dia aquele חוטבי עצים VAShe''ovei águas לאעדת׃ e-no altar yhwh até o-dia este a o-lugar que Ibcar:');
INSERT INTO chapters VALUES (197, 6, 10, 43);
INSERT INTO verses VALUES (6067, 6, 10, 1, 'e-houve quando-ouviram senhor-de justiça rei Jerusalém porque para-capturar Yehoshua a o-áia e-ele proibiu-a como fez para-Lírio u-le-malkah kén- fez para-o-áia e-no-rei e-que hishlimu habitantes-de Gib''ōn a Israel e-foram em-meio-deles-versículo-final');
INSERT INTO verses VALUES (6068, 6, 10, 2, 'vayir''e''u muito que cidade g''dolah Gib''ōn como-uma cidades-de hammamlākhā ve-ki ela g''dolah de o-Ai e-todo ''anāshēhā gibbōrim');
INSERT INTO verses VALUES (6069, 6, 10, 3, 'e-enviou [אֲדֹנִי־צֶ֜דֶק] [מֶ֣לֶךְ] rei Jerusalém a [וְאֶל־פִּרְאָ֨ם] rei-de [וְאֶל־יָפִ֧יעַ] e-a [וְאֶל־דְּבִ֥יר] rei-de dizendo e-a rei-de e-a Debir rei-de para-dizer');
INSERT INTO verses VALUES (6070, 6, 10, 4, 'על- a-mim ואזירני e-nacchē a gibbe''ōn porque hislimā a Yehoshua e-a filhos-de Israel');
INSERT INTO verses VALUES (6071, 6, 10, 5, 'vayya''asēpu vayya''alū cinco-de reis-de o-amorreu rei Jerusalém rei-de cheberōn rei-de yarmut rei-de eles rei-de eglūn eles e-todo machneihem e-acamparam sobre gibbe''ōn e-lutaram sobre-ela');
INSERT INTO verses VALUES (6072, 6, 10, 6, 'e-eles-enviaram os-homens-de [גִבְע֨וֹן] a Josué a dizendo [אַל־תֶּ֥רֶף] dizendo a folhas-de [אֵלֵ֣ינוּ] [מְהֵרָ֗ה] [וְהוֹשִׁ֤יעָה] para-nós rapidamente que a-nós [אֵלֵ֔ינוּ] porque [הָאֱמֹרִ֖י] a-nos todo מַלְכֵ֥י o-amorreu habitantes-de o-monte');
INSERT INTO verses VALUES (6073, 6, 10, 7, 'e-subiu Josué de ele ele e-todo povo e-tudo com-ele e-todo homens valentes da-habilidade');
INSERT INTO verses VALUES (6074, 6, 10, 8, 'E-disse yhwh a יְהוֹשֻׁעַ a que de-eles porque em-mão-tua [אִ֛ישׁ] não estabelecerá homem de-eles');
INSERT INTO verses VALUES (6075, 6, 10, 9, 'E-veio neles Yehoshua פִּתְאֹ֑ם todo subir subiu de o-Gilgal');
INSERT INTO verses VALUES (6076, 6, 10, 10, 'e-estimularam-se yhwh diante-de Israel e-ele-golpeou-vos punição- grande em-Gibeão o-caminho-de caminho subida casa-de Horon e-ele-golpeou-vos até arquearia e-até Makdá:');
INSERT INTO verses VALUES (6077, 6, 10, 11, 'e-houve em-nosso de-diante-de de-diante-de e-eles eles casa-de חָרֹן וַיְהֹוָה הִשְׁלִיכָ עַל־אֹתָם pedras גְּדוֹלוֹת de os-céus até עַצְקָה וַיָּמוּתֻ muitos que morreram בְּאֲבֹנֶיהָ o-barad do-que הָרְגוּ filhos-de Israel pela-espada');
INSERT INTO verses VALUES (6078, 6, 10, 12, 'então [יְדַבֵּ֤ר] a-yhwh em-dia-de dar yhwh yhwh o-amorreu diante-de filhos-de Israel E-disse aos-olhos-de Israel [יִשְׂרָאֵ֗ל] בְּגִבְע֣וֹן [בְּגִבְע֣וֹן] וְיָרֵ֖חַ na-vale [בְּעֵ֥מֶק]');
INSERT INTO verses VALUES (6079, 6, 10, 13, 'וַיִּדְּמֹ֨ם שֶׁמֶשׂ וְיָרֵ֣חַ ficou-em-pé até יִקְּמֹ֥ה nação אֹֽיְבָ֔יו não-é ela escrita sobre livro o retiro WAYYAA''MOD o-sol em-meio os-céus e-não atze para-vir como o dia perfeito');
INSERT INTO verses VALUES (6080, 6, 10, 14, 'e-não ser como o dia o-aquele diante-dele e depois dele para-ouvir yhwh com-voz homem que yhwh foi-luta para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (6081, 6, 10, 15, 'e-ele-retornou יְהוֹשֻׁעַ e-todo Israel com-ele a o-acampamento');
INSERT INTO verses VALUES (6082, 6, 10, 16, 'e-eles-fugiram cinco de os-reis estes e esconderam-se na caverna em Macaca׃');
INSERT INTO verses VALUES (6083, 6, 10, 17, 'e-ele-foi-dito [לִיהוֹשֻׁ֣עַ] dizendo [נִמְצְאוּ֙] cinco-de os-reis [נֶחְבְּאִ֥ים] [בַּמְּעָרָ֖ה] [בְּמַקֵּדָֽה]');
INSERT INTO verses VALUES (6084, 6, 10, 18, 'E-disse Yehoshua [גֹּ֛לּוּ] pedras grandes a boca-de הַמְּעָרָ֑ה [עָלֶ֛יהָ] em-a homens');
INSERT INTO verses VALUES (6085, 6, 10, 19, 'e-vós a vai-vos-em perseguam depois-de os-inimigos-vossos e-atingi-lhes eles a dar-vos-eis que a yhwh porque dai-os yhwh Elohim de-vós em-mão-vossa');
INSERT INTO verses VALUES (6086, 6, 10, 20, 'e-houve como-terminarem Josué e-filhos-de Israel para-matar-los golpe grande- muito até tum-mum e os sobreviventes sobraram de-eles e-vieram a cidades-de do acampamento');
INSERT INTO verses VALUES (6087, 6, 10, 21, 'e voltaram todo o-povo a o acampamento a יְהוֹשֻׁעַ de Mageda em-a-paz não cortaram ser Israel para cada um a de sua língua');
INSERT INTO verses VALUES (6088, 6, 10, 22, 'E-disse Yehoshua abriram a boca-de a caverna e saíram a-mim a cinco-vezes os reis estes de a caverna');
INSERT INTO verses VALUES (6089, 6, 10, 23, 'e fizeram assim e saíram a-ele a cinco-vezes os reis estes de a caverna com rei Jerusalém a rei Carmelo a rei Jarmut a rei לָכִ֖ישׁ a rei עֶגְלֽוֹן׃');
INSERT INTO verses VALUES (6090, 6, 10, 24, 'e-houve [כְּֽהוֹצִיאָ֞ם] a os-reis הָאֵלֶּה֮ E-chamou Yehoshua E-chamou Josué E-disse todo homem Israel E-disse a [אִתּ֔וֹ] homens-de a-guerra [אֶת־רַגְלֵיכֶ֔ם] com-ele [הַמְּלָכִ֣ים] [הָאֵ֑לֶּה] a vossos-pés sobre [עַל־צַוְּארֵיהֶֽם] os-reis estas e-os-colocaram a pés-deles sobre');
INSERT INTO verses VALUES (6091, 6, 10, 25, 'E-disse a-eles Yehoshua a temais e-a תֵּחָ֑תּוּ que [כָ֗כָה] porque yhwh fará yhwh para-todo [נִלְחָמִ֥ים] que vós a-eles');
INSERT INTO verses VALUES (6092, 6, 10, 26, '[וַיַּכֵּ֨ם] Josué depois-de assim [וַיִּתְלֵ֕ם] sobre sobre cinco עֵצִ֑ים e-foram תּלֻיִ֥ים sobre as madeiras até no entardecer');
INSERT INTO verses VALUES (6093, 6, 10, 27, 'e-houve le-et vem trazer tsi-vu-a יְהוֹשֻׁעַ וַיֹּֽרִידֻמ֙ de-sobre de-cima-de וַיַּ֨שְׁלִכֻ֔ם a a caverna que foram escondidas - nome e colocaram - pedras grandes - sobre boca-de o-dia até ossos o-dia a-esta');
INSERT INTO verses VALUES (6094, 6, 10, 28, 'e-a para queimar - para aprisionar - no-dia em-o-dia aquele e feriu-a - à-boca-de espada - e-a rainha - הֶחֱרִ֣ם não e-a todo הַנֶּ֙פֶשׁ֙ que em-ela não deixou שָׂרִ֑יד E-fez como-rei מַקֵּדָ֔ה como-que fez para-rei-de Jericó');
INSERT INTO verses VALUES (6095, 6, 10, 29, 'vayaavor Yehôšuwaʻ e-todo Israel com-ele [לִבְנָ֑ה] [וַיִּלָּ֖חֶם] וַיִּלָּחֶם com');
INSERT INTO verses VALUES (6096, 6, 10, 30, 'E-colocou yhwh também אותה na-mão-de Israel e-a [לְפִי־חֶ֗רֶב] [וְאֶת־כָּל־הַנֶּ֙פֶשׁ֙] à-boca-de espada e-a todo הַנֶּ֙פֶשׁ֙ que em-ela não deixou nela sarayid E-fez como-que fez para-rei-de Jericó');
INSERT INTO verses VALUES (6097, 6, 10, 31, 'vayaavor Yehôšuwaʻ e-todo Israel com-ele [לָכִ֑ישָׁה] a cintura [עָלֶ֔יהָ] sobre-ela וַיִּלָּחֶם nela');
INSERT INTO verses VALUES (6098, 6, 10, 32, 'E-colocou yhwh a [בְּיַ֣ד] em-mão-de Israel no-dia em-o-dia o-segundo [לְפִי־חֶ֔רֶב] à-boca-de espada e-a todo a-alma que nela conforme-tudo que fez');
INSERT INTO verses VALUES (6099, 6, 10, 33, 'então subir HORAM rei גֶּ֔זֶר לַעְזֹ֖ר a לָכִ֑ישׁ e-ele-o-feriu יְהוֹשֻׁעַ e-a povo-seu até para-não deixar-restar para-ele sobrevivente');
INSERT INTO verses VALUES (6100, 6, 10, 34, 'vayaavor Yehôšuwaʻ e-todo Israel com-ele [עֶגְלֹ֑נָה] [וַיַּחֲנ֣וּ] e-acamparam sobre-ela e-lutaram sobre-ela');
INSERT INTO verses VALUES (6101, 6, 10, 35, '[וַֽיִּלְכְּד֜וּהָ] no-dia o-aquele [וַיַכּ֣וּהָ] à-boca-de espada e-את todo no-dia que em-ela no-dia o-aquele [לְלָכִֽישׁ׃] conforme-tudo que fez');
INSERT INTO verses VALUES (6102, 6, 10, 36, 'e-subiu Yehôšuwaʻ e-todo Israel com-ele מֵעֶגְל֖וֹנָה Hevrona e-lutaram sobre-ela');
INSERT INTO verses VALUES (6103, 6, 10, 37, 'e a prendeu e mataram-a- à-boca-de espada e-a sua rainha e-a todo suas cidades e-a todo a alma que nela não deixaram restante-o conforme-tudo que fez para Eglon e destruíram ela e-a todo a-alma que nela');
INSERT INTO verses VALUES (6104, 6, 10, 38, 'e-estabeleceu-se יְהוֹשֻׁעַ e-todo Israel com-ele [וַיִּלָּ֖חֶם] וַיִּלָּחֶם sobre-ela');
INSERT INTO verses VALUES (6105, 6, 10, 39, '[וַֽיִּלְכְּדָ֞הּ] e-a [וְאֶת־כָּל־עָרֶ֙יהָ֙] e-a todo [וַֽיַּחֲרִ֙ימוּ֙] e-feriram-eles à-boca-de não e-eles-consagraram-a-destruição a todo alma que em-ela não deixou sarayid como-que fez [וּלְמַלְכָּֽהּ] כֵּן־ fez u-le-malkah vekaʾasher fez');
INSERT INTO verses VALUES (6106, 6, 10, 40, 'e-golpeou Yehoshua a todo a-terra הָהָר֩ e o Negev e a Sefela e as Ashdot não todo seus reis não deixou eu não subi e-a todo yhwh he-chrim como-que ele yhwh Elohim-de Israel');
INSERT INTO verses VALUES (6107, 6, 10, 41, 'e os atingiu יְהוֹשֻׁעַ em Miqueas no Barneu e-até Gaza e-a todo terra Gozene e-até Gibeon');
INSERT INTO verses VALUES (6108, 6, 10, 42, 'e-a todo os reis estes e-a terra-deles vez Yehoshua que yhwh porque yhwh Elohim-de Israel que para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (6109, 6, 10, 43, 'e-ele-retornou יְהוֹשֻׁעַ e-todo Israel com-ele a o-acampamento');
INSERT INTO chapters VALUES (198, 6, 11, 23);
INSERT INTO verses VALUES (6110, 6, 11, 1, 'e-houve ouvir Jabim rei-de cativeiro e-enviou a יוֹבָב֙ rei Madô e-a rei Shimrôn e-a rei Achshaf:');
INSERT INTO verses VALUES (6111, 6, 11, 2, 'e-a os reis que Mitzpô no monte e no deserto Nebeg como rios e na depressão e nas baixadas geração águas');
INSERT INTO verses VALUES (6112, 6, 11, 3, 'o-cananeu do oriente e do mar e o amalequita e o hitita וְהַפְּרִזִּ֥י וְהַיְבוּסִ֖י na-montanha וְהַֽחִוִּי֙ debaixo חֶרְמ֔וֹן em-terra-de hamatzpah');
INSERT INTO verses VALUES (6113, 6, 11, 4, 'e-eles-saíram eles e-todo [עִמָּ֔ם] com-eles com muito como-areia que sobre borda-de o-mar em-abundância muito muito');
INSERT INTO verses VALUES (6114, 6, 11, 5, '[וַיִּוָּ֣עֲד֔וּ] todo os-reis estes e-vieram [וַיַּחֲנ֤וּ] yachdav a águas-de [לְהִלָּחֵ֖ם] para-lutar com Israel');
INSERT INTO verses VALUES (6115, 6, 11, 6, 'E-disse yhwh a Yehoshua a tire-a de-lhes porque eu como tempo-de desta eu deu a todos-os traspassados diante-de Israel a cavalos-seus arrancará e-a carruagens-seus queimará em-a-chama');
INSERT INTO verses VALUES (6116, 6, 11, 7, 'E-veio Josué e-todo povo a-batalha com-ele sobre-eles sobre águas-de de-cima פתאום e-caíram neles');
INSERT INTO verses VALUES (6117, 6, 11, 8, 'e-lhes-deu yhwh por-mão- Israel e atingiram-os e-os-perseguiram até Tsido''n multiplicai águas fornos águas e-até buraco observatório מִזְרָ֑חָה e atingiram-os até para-não deixar-restar a-eles sobrevivente');
INSERT INTO verses VALUES (6118, 6, 11, 9, 'E-fez a-eles Yehoshua como-que palavras-de yhwh yhwh a seus cavalos raiz e-a suas carretas queimar em-a-chama');
INSERT INTO verses VALUES (6119, 6, 11, 10, 'e voltou Josué em-o-tempo a-essa e-ele-pegou a Chatzar e-a מַלְכָּהּ bateu becháreb porque [רֹ֖אשׁ] [כָּל־הַמַּמְלָכ֥וֹת] ela cabeça todo as estas');
INSERT INTO verses VALUES (6120, 6, 11, 11, '[וַ֠יַּכּוּ] a todo [לְפִי־חֶ֙רֶב֙] que não à-boca-de [כָּל־נְשָׁמָ֑ה] [וְאֶת־חָצ֖וֹר] não restante todo e-a queimar em-a-chama');
INSERT INTO verses VALUES (6121, 6, 11, 12, 'e-a todo cidades-de [לָכַ֧ד] [יְהוֹשֻׁ֛עַ] e-a todo [הֶחֱרִ֣ים] [אוֹתָ֑ם] יְהוֹשֻׁעַ e-ele-golpeou-vos à-boca-de espada yhwh eles como-que deu-mandamento Moisés servo yhwh');
INSERT INTO verses VALUES (6122, 6, 11, 13, 'somente todo [הָעֹֽמְדוֹת֙] [עַל־תִּלָּ֔ם] não [שְׂרָפָ֖ם] não [זוּלָתִ֛י] Israel [לְבַדָּ֖הּ] a [יְהוֹשֻֽׁעַ] queimar יְהוֹשֻֽׁעַ');
INSERT INTO verses VALUES (6123, 6, 11, 14, 'e-tudo [שְׁלַ֞ל] [הֶעָרִ֤ים] estes [וְהַבְּהֵמָ֔ה] ba-zez a-eles filhos-de Israel somente a todo o-homem hikchu à-boca-de não até [כָּל־נְשָׁמָֽה] a-eles não todo  נְשָׁמָֽה׃');
INSERT INTO verses VALUES (6124, 6, 11, 15, 'como-que tsi-vu-a yhwh a Moisés servo-seu כֵּן־ ordenou Moisés a Yehoshua e também fez de-toda não yhwh palavra de-todo que ordenou yhwh a Moisés');
INSERT INTO verses VALUES (6125, 6, 11, 16, 'E-tomou Josué a todo a-terra desta e-[OBJ] e-a todo o-sul e-את todo terra [וּשְׁפֵלָתֹֽה] e-a a-plana-terra e-a e-a monte-de Israel');
INSERT INTO verses VALUES (6126, 6, 11, 17, 'de o monte a divisão o subindo Seir e-até Baal Gad debaixo halbānōn sob monte-de Cheremón e-a todo מלכיהם Lacád e os bateram e mataram:');
INSERT INTO verses VALUES (6127, 6, 11, 18, 'dias muitos fez יְהוֹשֻׁעַ a todo os reis estes guerra');
INSERT INTO verses VALUES (6128, 6, 11, 19, 'não ela-foi cidade que haviam subjugado a filhos-de Israel para-não o-hivi habitantes-de גִבְע֑וֹן a o-ouro tomaram na guerra:');
INSERT INTO verses VALUES (6129, 6, 11, 20, 'que de-junto-de yhwh foi era a em seus corações ao-encontro-de a guerra a Israel para-que para-não para-não ser que com misericórdia porque para-que destruíram yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (6130, 6, 11, 21, 'E-veio Josué em-o-tempo a aquela e-cortou a os-ânakis de o-har de Hevroc de palavra de u-nab e-de-todo monte-de Judá e-de-todo monte-de Israel com ar-ye-hem o-cherímmam יְהוֹשֻֽׁעַ');
INSERT INTO verses VALUES (6131, 6, 11, 22, 'não no-tar ânakis em-terra-de filhos-de Israel somente b-âzah b-gat e-em Ashdod permaneceram');
INSERT INTO verses VALUES (6132, 6, 11, 23, 'E-tomou Josué a todo a-terra conforme-tudo yhwh palavra yhwh a Moisés e-lhe deu יְהוֹשֻׁעַ por herança E-a-terra como divisões para seus tribos E-a-terra estava em paz de guerra:');
INSERT INTO chapters VALUES (199, 6, 12, 24);
INSERT INTO verses VALUES (6133, 6, 12, 1, 'e-estes reis-de a-terra a-terra deram golpes filhos-de Israel e tomaram posse a terra-deles em-além-de o Jordão do oriente o-sol מִנְחָל אַרְנֹן até monte-de חֶרְמ֔וֹן e-todo a-aravah mizrachah');
INSERT INTO verses VALUES (6134, 6, 12, 2, '[סִיחוֹן֙] rei o-amorreu o-que-habita em-Hesbom [מֹשֵׁ֡ל] [מֵעֲרוֹעֵ֡ר] que sobre borda-de ribeiro-de [הַנַּ֙חַל֙] [וַחֲצִ֣י] [הַגִּלְעָ֔ד] וַחֲצִ֣י Gileade e-ate Yabok o-nachal guvul filhos-de Amom');
INSERT INTO verses VALUES (6135, 6, 12, 3, '[וְהָעֲרָבָה֩] até [כִּנְר֜וֹת] [מִזְרָ֗חָה] [וְ֠עַד] mar mar [יָם־הַמֶּ֙לַח֙] mar- o-caminho-de para-o-nascente caminho casa debaixo [אַשְׁדּ֥וֹת] sob da-cima');
INSERT INTO verses VALUES (6136, 6, 12, 4, 'וגבול Ogue rei o basanita miteser הרפאים היוושב בעשתרות e-em-adreuci:');
INSERT INTO verses VALUES (6137, 6, 12, 5, 'e-moshelem em-har chermon e-salkaha e-em-todo o basanita até fronteira-de o-gesuritas e-ham-ma''acati va-chazi Gileade guvul סִיח֥וֹן rei-de cheshbon:');
INSERT INTO verses VALUES (6138, 6, 12, 6, 'Moisés servo- yhwh e-filhos-de Israel hikkum va-yitnaha Moisés servo- yhwh ירשת לראובני e-para-o-gadita e-para-metade-de não המנשה׃');
INSERT INTO verses VALUES (6139, 6, 12, 7, 'e-estes reis-de a-terra que [הִכָּ֨ה] Josué e-filhos-de Israel em-lado-de o-Jordão ao-lado-direito [מִבַּ֤עַל] [גָּד֙] [בְּבִקְעַ֣ת] הַלְּבָנ֔וֹן e-até a-montanha [הָעֹלֶ֣ה] [שֵׂעִ֑ירָה] [וַיִּתְּנָ֨הּ] [יְהוֹשֻׁ֜עַ] Josué [יִשְׂרָאֵ֛ל] Israel [כְּמַחְלְקֹתָֽם]');
INSERT INTO verses VALUES (6140, 6, 12, 8, 'na-montanha e-na-planície [וּבָֽעֲרָבָה֙] [וּבָ֣אֲשֵׁד֔וֹת] [וּבַמִּדְבָּ֖ר] [וּבַנֶּ֑גֶב] o-hitita o amorreu e-o-canaanita o-prizi o-hivi e-o-jebuseu');
INSERT INTO verses VALUES (6141, 6, 12, 9, 'rei Jericó um rei de-Ai que do lado de um El um');
INSERT INTO verses VALUES (6142, 6, 12, 10, 'rei Jerusalém um rei Hebrom um');
INSERT INTO verses VALUES (6143, 6, 12, 11, 'rei יַרְמוּת֙ um rei lachish um');
INSERT INTO verses VALUES (6144, 6, 12, 12, 'rei [עֶגְלוֹן֙] um rei Gezer um');
INSERT INTO verses VALUES (6145, 6, 12, 13, 'rei palavra um rei [גֶּ֖דֶר] um');
INSERT INTO verses VALUES (6146, 6, 12, 14, 'rei [חָרְמָה֙] um rei [עֲרָ֖ד] um');
INSERT INTO verses VALUES (6147, 6, 12, 15, 'rei [לִבְנָה֙] um rei [עֲדֻלָּ֖ם] um');
INSERT INTO verses VALUES (6148, 6, 12, 16, 'rei [מַקֵּדָה֙] um rei casa-de um um');
INSERT INTO verses VALUES (6149, 6, 12, 17, 'rei [תַּפּ֙וּחַ֙] um rei [חֵ֖פֶר] um');
INSERT INTO verses VALUES (6150, 6, 12, 18, 'rei [אֲפֵק֙] um rei [לַשָּׁר֖וֹן] um');
INSERT INTO verses VALUES (6151, 6, 12, 19, 'rei [מָדוֹן֙] um rei [חָצ֖וֹר] um');
INSERT INTO verses VALUES (6152, 6, 12, 20, 'rei [שִׁמְר֤וֹן] [מְראוֹן֙] um rei [אַכְשָׁ֖ף] um');
INSERT INTO verses VALUES (6153, 6, 12, 21, 'rei תּעַנַּךְ um rei Megido um');
INSERT INTO verses VALUES (6154, 6, 12, 22, 'rei [קֶ֙דֶשׁ֙] um rei-de [לַכַּרְמֶ֖ל] um um');
INSERT INTO verses VALUES (6155, 6, 12, 23, 'rei [דּ֛וֹר] [לְנָפַ֥ת] [דּ֖וֹר] um rei-de nações um um');
INSERT INTO verses VALUES (6156, 6, 12, 24, 'rei [תִּרְצָ֖ה] um todo me-lachim trinta e-um');
INSERT INTO chapters VALUES (200, 6, 13, 33);
INSERT INTO verses VALUES (6157, 6, 13, 1, 'vayehôshûa'' velho veio em-os dias E-disse yhwh a-ele tu זָקַ֙נְתָּה֙ בָּ֣אתָ בַּיָּמִ֔ים E-a-terra נִשְׁאֲרָ֥ה הַרְבֵּֽה־ muito para-possuí-la');
INSERT INTO verses VALUES (6158, 6, 13, 2, 'esta a-terra [הַנִּשְׁאָ֑רֶת] todo [הַפְּלִשְׁתִּ֖ים] os-felistinos e-todo');
INSERT INTO verses VALUES (6159, 6, 13, 3, 'de הַשִּׁיח֞וֹר que sobre face-de Egito e-ad fronteira-de-a עֶקְרוֹן֙ do norte לַֽכְּנַעֲנִ֖י תֵּחָשֵׁ֑ב cinco-de príncipes-de פְלִשְׁתִּ֗ים הָעַזָּתִ֤י וְהָאַשְׁדּוֹדִי֙ הָאֶשְׁקְלוֹנִ֣י הַגִּתִּ֔י וְהָעֶקְרוֹנִ֖י וְהָעַוִּֽים׃');
INSERT INTO verses VALUES (6160, 6, 13, 4, '[מִתֵּימָ֞ן] todo terra o-canaanita [אֲשֶׁ֥ר] que [עַד־אֲפֵ֑קָה] até [גְּב֥וּל] até fronteira-de o-amorreu');
INSERT INTO verses VALUES (6161, 6, 13, 5, 'E-a-terra [הַגִּבְלִ֗י] e-todo de-o-Líbano do-leste o-sol de-baal debaixo sob até [לְב֥וֹא] até para-entrada-de חֲמָֽת');
INSERT INTO verses VALUES (6162, 6, 13, 6, 'todo habitantes-de [מִֽן־הַלְּבָנ֞וֹן] de águas até eu águas de-diante-de [בְּנֵ֣י] eu [רַ֠ק] de-face-de filhos-de Israel somente ordenei-te para-o-Israel conforme');
INSERT INTO verses VALUES (6163, 6, 13, 7, 'e-agora [חַלֵּ֞ק] a a-terra esta na-inheritance [הַשְּׁבָטִ֑ים] [וַחֲצִ֖י] וַחֲצִי [הַֽמְנַשֶּֽׁה]');
INSERT INTO verses VALUES (6164, 6, 13, 8, 'com-ela o roévéní e hagádi tomaram sua herança que dar a-eles Moisés em-lado-de o-Jordão para-o-nascente como dar a-eles Moisés servo yhwh');
INSERT INTO verses VALUES (6165, 6, 13, 9, 'de arú''êr que sobre borda-de ribeiro-de Arnon e-a-cidade que em-meio-de o náchal e-todo הַמִּשְׁחֹ֥ר de midbá até דִּבֹּן׃');
INSERT INTO verses VALUES (6166, 6, 13, 10, 'e-tudo עָרֵי֙ Sicon rei o-amorreu que rei em-Hesbom até guvul filhos-de Amon');
INSERT INTO verses VALUES (6167, 6, 13, 11, '[וְהַגִּלְעָ֞ד] [וּגְב֧וּל] [הַגְּשׁוּרִ֣י] [וְהַמַּעֲכָתִ֗י] e-tudo monte-de hermon- e-todo o-Basã até salka');
INSERT INTO verses VALUES (6168, 6, 13, 12, 'todo [עוֹג֙] [בַּבָּשָׁ֔ן] em-Bashan que rei ele [נִשְׁאַר֙] ele [הָרְפָאִ֔ים] de-restante-de [מֹשֶׁ֖ה] e-ele-golpeou-vos Moisés');
INSERT INTO verses VALUES (6169, 6, 13, 13, 'e-não [הוֹרִ֙ישׁוּ֙] filhos-de Israel a o-gesuritas e-a [גְּשׁ֤וּר] e-ele-habitou [בְּקֶ֣רֶב] [יִשְׂרָאֵ֔ל] até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (6170, 6, 13, 14, 'somente [לְשֵׁ֣בֶט] o-levita não dar herança [אִשֵּׁ֨י] yhwh Elohim-de Israel ele herança-sua como falou a-ele');
INSERT INTO verses VALUES (6171, 6, 13, 15, 'E-colocou Moisés para-matate filhos-de reuven para-famílias-deles');
INSERT INTO verses VALUES (6172, 6, 13, 16, 'e-houve a-eles [הַגְּב֗וּל] [מֵעֲרוֹעֵ֡ר] que sobre borda-de ribeiro-de [אֲשֶׁ֧ר] e-a-cidade que em-meio-de e-todo o-plano sobre');
INSERT INTO verses VALUES (6173, 6, 13, 17, '[חֶשְׁבּ֥וֹן] e-todo cidades-dele que [דִּיבוֹן֙] [וּבָמ֣וֹת] [בַּ֔עַל] [וּבֵ֖ית] וּבֵ֖ית Baal m-eon');
INSERT INTO verses VALUES (6174, 6, 13, 18, '[וְיַ֥הְצָה] [וּקְדֵמֹ֖ת] [וּמֵפָֽעַת]');
INSERT INTO verses VALUES (6175, 6, 13, 19, '[וְקִרְיָתַ֣יִם] [וְשִׂבְמָ֔ה] [וְצֶ֥רֶת] [הַשַּׁ֖חַר] em-monte-de o-vale:');
INSERT INTO verses VALUES (6176, 6, 13, 20, 'e-casa-de [פְּע֛וֹר] [וְאַשְׁדּ֥וֹת] ha-pisga e-casa-de [הַיְשִׁמֽוֹת]');
INSERT INTO verses VALUES (6177, 6, 13, 21, 'e-tudo cidades-de [הַמִּישֹׁ֔ר] e-todo [סִיחוֹן֙] [מֶ֣לֶךְ] rei o-amorreu que rei em-Hesbom que [מֹשֶׁ֜ה] ele [׀] e-[OBJ] príncipes-de Midiã a [וְאֶת־צ֤וּר] e-[OBJ] [וְאֶת־רֶ֔בַע] e-[OBJ] [סִיח֔וֹן] e-[OBJ] a-terra e-[OBJ] a-terra');
INSERT INTO verses VALUES (6178, 6, 13, 22, 'e-[OBJ] [בֶּן־בְּע֖וֹר] filho-de [הָרְג֧וּ] [בְנֵֽי־יִשְׂרָאֵ֛ל] [בַּחֶ֖רֶב] filhos-de Israel a');
INSERT INTO verses VALUES (6179, 6, 13, 23, 'e-houve [גְּבוּל֙] filhos-de Rúben o Jordão [וּגְב֑וּל] esta [נַחֲלַ֤ת] filhos-de Rúben [הֶעָרִ֖ים] as-cidades');
INSERT INTO verses VALUES (6180, 6, 13, 24, 'E-colocou Moisés [לְמַטֵּה־גָ֔ד] Gade para-filhos-de');
INSERT INTO verses VALUES (6181, 6, 13, 25, 'e-houve a-eles o-limite יַעְזֵר֙ e-todo cidades-de Gileade terra terra filhos-de Amom até עֲרוֹעֵ֕ר que sobre face-de multiplicai');
INSERT INTO verses VALUES (6182, 6, 13, 26, '[וּמֵחֶשְׁבּ֛וֹן] até [הַמִּצְפֶּ֖ה] [וּבְטֹנִ֑ים] [וּמִֽמַּחֲנַ֖יִם] [עַד־גְּב֥וּל] até');
INSERT INTO verses VALUES (6183, 6, 13, 27, 'וּבָעֵ֡מֶק casa הָרָם֩ וּבֵ֨ית נִמְרָ֜ה וְסֻכּ֣וֹת וְצָפ֗וֹן יֶ֚תֶר מַמְלְכ֗וּת Sicon rei Hesbom o Jordão e-guvul até extremidade-de mar- כִּנֶּ֔רֶת Éber o Jordão mizrachah');
INSERT INTO verses VALUES (6184, 6, 13, 28, 'esta [נַחֲלַ֥ת] filhos-de [לְמִשְׁפְּחֹתָ֑ם] segundo-famílias-deles as-cidades');
INSERT INTO verses VALUES (6185, 6, 13, 29, 'E-colocou Moisés para-metade-de tribo-de Manassés e-houve [לַחֲצִ֛י] bastão-de filhos-de [לְמִשְׁפְּחוֹתָֽם]');
INSERT INTO verses VALUES (6186, 6, 13, 30, 'e-houve גְבוּלָ֗ם de-campeis todo a-basã todo mamlakta Og rei-de o-Basã e-todo cavutas ja-ir que em-a-Bashan sessenta cidade');
INSERT INTO verses VALUES (6187, 6, 13, 31, 'e-meia o-Gileade e-ashtorot e-adreui cidades-de mamlakta Ogue em-basã para-filhos-de Maquir filho-de Manassés para-a-cortada filhos-de מכיר para-as-machos-lhes:');
INSERT INTO verses VALUES (6188, 6, 13, 32, 'Estas que cortado Moisés nas-areias Moabe do-outro-lado para-o-jordão Jericó mizrachah');
INSERT INTO verses VALUES (6189, 6, 13, 33, 'e-para-a-castaça o-levita não deu Moisés yhwh yhwh Elohim-de ele ele sua-cortada como a-eles para-eles');
INSERT INTO chapters VALUES (201, 6, 14, 15);
INSERT INTO verses VALUES (6190, 6, 14, 1, 'e-estes que cortaram-se filhos-de Israel na-terra assim que foram-cortados aqueles-o Elazar o-sacerdote vayehôshûa'' filho-de Nun וְרָאשֵׁ֛י אֲב֥וֹת הַמַּטּ֖וֹת para-filhos-de Israel');
INSERT INTO verses VALUES (6191, 6, 14, 2, '[בְּגוֹרַ֖ל] [נַחֲלָתָ֑ם] como [צִוָּ֤ה] yhwh por-mão-de Moisés [הַמַּטּ֖וֹת] [וַחֲצִ֥י] e-metade-de');
INSERT INTO verses VALUES (6192, 6, 14, 3, 'porque deu Moisés נַחֲלַ֨ת segundo הַמַּטּוֹת֙ e-meio הַמַּטּ֔ה מֵעֵ֖בֶר para-o-jordão e-para-os-lévitas não deu herança em-meio-de-eles');
INSERT INTO verses VALUES (6193, 6, 14, 4, 'porque foram filhos-de José segundo varas manassés e-efraim e-não deram que e-para-os-lévitas na terra porque se Arim que e-suas-terras para os seus ganhos e para a aquisição;');
INSERT INTO verses VALUES (6194, 6, 14, 5, 'como-que tsi-vu-a yhwh a Moisés assim fizeram filhos-de Israel e dividiram a a-terra');
INSERT INTO verses VALUES (6195, 6, 14, 6, 'e-aproximaram-se filhos-de Judá a E-disse a-ele E-disse para-ele Calebe tu sempre o Kenazita tu yhwh a a palavra sobre palavra yhwh a Moisés homem-de ouro sobre minhas palavras e-sobre as tuas palavras em santidade Barneia');
INSERT INTO verses VALUES (6196, 6, 14, 7, 'filho-de quarenta eu eu [מֹשֶׁ֨ה] Moisés servo- yhwh [בַּרְנֵ֖עַ] [לְרַגֵּ֣ל] [אֶת־הָאָ֑רֶץ] [וָאָשֵׁ֤ב] ele a-terra [כַּאֲשֶׁ֖ר] ele palavra com');
INSERT INTO verses VALUES (6197, 6, 14, 8, '[וְאַחַי֙] que [עָל֣וּ] comigo [הִמְסִ֖יו] a coração o-povo e-eu [אַחֲרֵ֖י] yhwh yhwh');
INSERT INTO verses VALUES (6198, 6, 14, 9, 'e jurou Moisés no-dia הַהוּא֮ dizendo se a-terra a-terra que caminho teu pé a-ti para ti será herança e-aos-seus-filhos que eternidade porque yhwh atrás-de yhwh yhwh');
INSERT INTO verses VALUES (6199, 6, 14, 10, 'e-agora eis animou-me a mim como-que palavra isto quarenta e cinco ano מֵ֠אָז palavra yhwh a yhwh o-este a Moisés que andou Israel e-agora eis eu o-dia o-dia filho-de cinco וּשְׁמוֹנִ֖ים anos');
INSERT INTO verses VALUES (6200, 6, 14, 11, 'עוֹדֶ֨נִּי o-dia חָזָ֗ק כּֽ͏ַאֲשֶׁר֙ no-dia enviou a-mim Moisés כְּכֹ֥חִי entao וּכְכֹ֣חִי עָ֑תָּה para-a-guerra וְלָצֵ֥את וְלָבֽוֹא׃');
INSERT INTO verses VALUES (6201, 6, 14, 12, 'e-agora dá- para-mim a o-monte yhwh no-dia palavra que em-o-dia o-aquele porque אתה־ שׁמעת no-dia o-aquele porque ענקים yhwh וערים גדלוות בְּצֻר֔וֹת אוּלַ֨י yhwh a-mim וְה֣וֹרַשׁׁתִ֔ים conforme palavra yhwh');
INSERT INTO verses VALUES (6202, 6, 14, 13, 'e o bendisse Yehoshua E-colocou a Hevron para-Calev filho-de foi plantada para herança');
INSERT INTO verses VALUES (6203, 6, 14, 14, 'sobre assim foi Hevron para Calebe filho-de até o-dia como herança até o-dia este porque yhwh enchei depois yhwh Elohim-de Israel');
INSERT INTO verses VALUES (6204, 6, 14, 15, 'e-nome-de Hevron לְפָנִים cidade-de quatro o-homem o grande em anões ele E-a-terra שָׁקְטָה מִמְלָחָמָה׃');
INSERT INTO chapters VALUES (202, 6, 15, 63);
INSERT INTO verses VALUES (6205, 6, 15, 1, 'e-houve [הַגּוֹרָ֗ל] [לְמַטֵּ֛ה] filhos-de Judá segundo-famílias-deles a [אֱד֧וֹם] [מִדְבַּר־צִ֛ן] [נֶ֖גְבָּה] [מִקְצֵ֥ה] [תֵימָֽן]');
INSERT INTO verses VALUES (6206, 6, 15, 2, 'e-houve a-eles fronteira נֶגֶב de-fim-de mar הַמֶּלַח de a língua o rosto ao-sul');
INSERT INTO verses VALUES (6207, 6, 15, 3, 'e saiu a do Negev para cima עַקְרָבִים e passou deserto e-subirá do-negueb para o santuário no ventre e passou Hezrom e suba adará e se levante a terra');
INSERT INTO verses VALUES (6208, 6, 15, 4, 'e passou por si mesma e-saiu vale-de Egito saias a fronteira para-o-mar este será para-vocês a-vós negue:');
INSERT INTO verses VALUES (6209, 6, 15, 5, 'e a fronteira leste mar ha-melah até קְצֵ֖ה o Jordão e a fronteira לִפְאָת הצפון o-mar o-mar de-fim-de o-Jordão');
INSERT INTO verses VALUES (6210, 6, 15, 6, '[וְעָלָ֤ה] [הַגְּבוּל֙] casa [חָגְלָ֔ה] [וְעָבַ֕ר] norte para-casa-de [הָעֲרָבָ֑ה] [וְעָלָ֣ה] [הַגְּב֔וּל] pedra [בֹּ֖הַן] filho-de');
INSERT INTO verses VALUES (6211, 6, 15, 7, 'e-subiu הַגְּב֬וּל דְבַרָה de-emeque achor e-tzafonah fonah a o-galgal que nochach para-maaleh adomim que do-negueb nachal e passou o-gabul a e-sejam olho shemesh e-serão תֹצְאֹתָיו a olho רֹגֵֽל׃');
INSERT INTO verses VALUES (6212, 6, 15, 8, 'e-subiu הַגְּב֜וּל גֵּ֣י filho-de הִנֹּ֗ם a ombro o-jebuseu מִנֶּ֔גֶב ela jerusalém e-subiu o-gvul a cabeça o monte que sobre face-de גֵֽי־ הִנֹּם֙ será amarga que no fundo\ עֵֽמֶק־ רְפָאִ֖ים norte-para');
INSERT INTO verses VALUES (6213, 6, 15, 9, 'e desenhou o-gvul do começo o monte a מעין águas-de aberto e saiu a cidades-de monte-de Efron e desenhou a fronteira em cima de ela Quiriate Jearim');
INSERT INTO verses VALUES (6214, 6, 15, 10, 'e levantou a fronteira יָמָֹה a monte-de Seir e passou a כַּפֶּ monte-de יְעָרֵ מִצְפֹּ ela כְּסַלֹּ וְיָרֵ casa-de sol וְעָבֵ תִּמְנָ');
INSERT INTO verses VALUES (6215, 6, 15, 11, 'e saiu הַגְבֻּ a cetef עֶקְרׇוֹן צפון וְתָאַר הַגֲּבוּל֙ שִׁכְּר֔וֹנָה וְעָבַ֥ר monte-de הַֽבַּעֲלָ֖ה e-sejam יַבְנְאֵ֑ל וְהָי֛וּ תֹּצְא֥וֹת הַגֲּבוּל֙ para-o-mar');
INSERT INTO verses VALUES (6216, 6, 15, 12, 'וּגְב֣וּל mar o mar o-grande -fronteira zeh -fronteira filhos-de יְהוּדָה ao-redor para-famílias-deles');
INSERT INTO verses VALUES (6217, 6, 15, 13, '-a todo Calebe filho-de dar deu no-meio-de em-meio-de filhos-de yhwh a de-seu yhwh para Josué a Quiriate quatro pai-de o gigante ela Hebrom');
INSERT INTO verses VALUES (6218, 6, 15, 14, 'e invadiu de-lá Calebe a שָׁלֹשׁ filhos-de o Anak a sexto e-a Achimam e-a Talmai filhos de o-Enaque');
INSERT INTO verses VALUES (6219, 6, 15, 15, 'e-subiu de-lá a moradores palavra e-Shem palavra yhwh cidade-de- livro');
INSERT INTO verses VALUES (6220, 6, 15, 16, 'E-disse Calebe que ferir a cidade-de- a-ele e-capturar-a e-darei para-ele a Acsa filha-minha para-mulher');
INSERT INTO verses VALUES (6221, 6, 15, 17, 'e tomou-a Otniel filho-de Quenaz Ai Calebe e-ele-deu para-ele a Acsa filha-dele para-mulher');
INSERT INTO verses VALUES (6222, 6, 15, 18, 'e-houve em-vir-dela e-ela-incitou-o para-pedir de-com pai-dela campo de-cima-de de-sobre o-jumento e-ele-disse para-ela Calebe que- para-ti');
INSERT INTO verses VALUES (6223, 6, 15, 19, 'E-disse [תְּנָה־לִּ֣י] para-mim que terra terra o-sul tu-me-deste e-tu-darás a-mim fontes-de águas e-ele-deu para-ela a e-[OBJ] [גֻּלֹּ֥ת] e-[OBJ]');
INSERT INTO verses VALUES (6224, 6, 15, 20, 'esta [נַחֲלַ֛ת] bastão-de filhos-de Judá');
INSERT INTO verses VALUES (6225, 6, 15, 21, 'e-foram [הֶעָרִ֗ים] [מִקְצֵה֙] para-tribo-de filhos-de Judá a fronteira-de Edom [וְעֵ֖דֶר] [וְיָגֽוּר]');
INSERT INTO verses VALUES (6226, 6, 15, 22, '[וְקִינָ֥ה] [וְדִֽימוֹנָ֖ה] [וְעַדְעָדָֽה]');
INSERT INTO verses VALUES (6227, 6, 15, 23, 'e santidade e a muralha e será dado:');
INSERT INTO verses VALUES (6228, 6, 15, 24, 'falso e a balança e-em-alturas-verso');
INSERT INTO verses VALUES (6229, 6, 15, 25, 'e a muralha de cunho e as entradas Hezrom ela a muralha:');
INSERT INTO verses VALUES (6230, 6, 15, 26, 'verdadeiramente e ouve e nascimento;');
INSERT INTO verses VALUES (6231, 6, 15, 27, 'e-atrio-de gadá e chesmon e-casa-de palét;');
INSERT INTO verses VALUES (6232, 6, 15, 28, 'e-atrio-de shual e be''er sete e bizotiyah;');
INSERT INTO verses VALUES (6233, 6, 15, 29, 'ba''alá e uiyim e-a-ço-m:');
INSERT INTO verses VALUES (6234, 6, 15, 30, 'e-al-tol-ad u-c-sil e-char-ma-h:');
INSERT INTO verses VALUES (6235, 6, 15, 31, 'e-tz-qlag u-mad-dman-na-h e-sans-san-na-h:');
INSERT INTO verses VALUES (6236, 6, 15, 32, 'u-le-ba-ot e-shil-chim ve-ayín ve-rimon todo cidades vinte e-que-nove e-seus-átrios');
INSERT INTO verses VALUES (6237, 6, 15, 33, 'be-sha-fela-ah: אֶשׁתָּא֥וֹל וְצָרְעָ֖ה וְאַשְׁנָֽה׃');
INSERT INTO verses VALUES (6238, 6, 15, 34, '[וְזָנ֙וֹחַ֙] [וְעֵ֣ין] [גַּנִּ֔ים] [תַּפּ֖וּחַ] [וְהָעֵינָֽם]');
INSERT INTO verses VALUES (6239, 6, 15, 35, '[יַרְמוּת֙] [וַעֲדֻלָּ֔ם] [שׂוֹכֹ֖ה] [וַעֲזֵקָֽה]');
INSERT INTO verses VALUES (6240, 6, 15, 36, 'וְשַׁעֲרַ֙יִם֙ וַעֲדִיתַ֔יִם וְהַגְּדֵרָ֖ה וּגְדֵרֹתָ֑יִם cidades quatro- dez e-seus-átrios');
INSERT INTO verses VALUES (6241, 6, 15, 37, '[צְנָ֥ן] [וַחֲדָשָׁ֖ה] [וּמִגְדַּל־גָּֽד]');
INSERT INTO verses VALUES (6242, 6, 15, 38, '[וְדִלְעָ֥ן] [וְהַמִּצְפֶּ֖ה] [וְיָקְתְאֵֽל]');
INSERT INTO verses VALUES (6243, 6, 15, 39, '[לָכִ֥ישׁ] [וּבָצְקַ֖ת] [וְעֶגְלֽוֹן]');
INSERT INTO verses VALUES (6244, 6, 15, 40, 'וְכַבּ֥וֹן e-lhasem וְכִתְלִֽישׁ׃');
INSERT INTO verses VALUES (6245, 6, 15, 41, 'וּגְדֵר֕וֹת casa-de דָּג֥וֹן e Naama e Makdá cidades seis-de dez e-seus-átrios');
INSERT INTO verses VALUES (6246, 6, 15, 42, 'para Libna e Eter e Ashan');
INSERT INTO verses VALUES (6247, 6, 15, 43, 'e Yiftá e Assá e Nitzav');
INSERT INTO verses VALUES (6248, 6, 15, 44, 'e Quíla וְאַכְזִ֖יב e Marésha cidades nove e-seus-átrios');
INSERT INTO verses VALUES (6249, 6, 15, 45, 'Ekron ובנותיה e suas cidades:');
INSERT INTO verses VALUES (6250, 6, 15, 46, 'de Ekron e Jamnia todo que sobre mão Ashdod e-seus-átrios');
INSERT INTO verses VALUES (6251, 6, 15, 47, 'Ashdod suas filhas e suas cidades Azah suas filhas e suas muralhas até vale-de Egito e-o-mar e seu limite;');
INSERT INTO verses VALUES (6252, 6, 15, 48, 'e no monte שָׁמִיר e Jattir e Socho;');
INSERT INTO verses VALUES (6253, 6, 15, 49, 'e Danna e a cidade de Sana ela palavra');
INSERT INTO verses VALUES (6254, 6, 15, 50, 'e Anab e Eshtemoa e-ânim:');
INSERT INTO verses VALUES (6255, 6, 15, 51, 'וְגֹ֥שֶׁן e-chôlôn e-gilô cidades um- dez e-seus-átrios');
INSERT INTO verses VALUES (6256, 6, 15, 52, 'arab e-rômâ e-êšʿân:');
INSERT INTO verses VALUES (6257, 6, 15, 53, 'e-casa-de tapputôakh e-apēkh:');
INSERT INTO verses VALUES (6258, 6, 15, 54, 'e-chumtá e-queriá quatro ela Hebrom וְצִיעֹ֑ר cidades nove e-seus-átrios');
INSERT INTO verses VALUES (6259, 6, 15, 55, 'ma-ún kar-mel va-zíf e-yútá');
INSERT INTO verses VALUES (6260, 6, 15, 56, 'e-izréel e-yakdéam e-zanóch');
INSERT INTO verses VALUES (6261, 6, 15, 57, '[הַקַּ֖יִן] [גִּבְעָ֣ה] [וְתִמְנָ֑ה] cidades dez e-seus-átrios');
INSERT INTO verses VALUES (6262, 6, 15, 58, '[חַלְח֥וּל] casa-de rocha');
INSERT INTO verses VALUES (6263, 6, 15, 59, '[וּמַעֲרָ֥ת] e-casa-de [וְאֶלְתְּקֹ֑ן] [עָרִ֥ים] cidades seis');
INSERT INTO verses VALUES (6264, 6, 15, 60, 'cidade-de- בַּ֗עַל ela Quiriate de-árvores וְהָֽרַבָּ֑ה cidades שְׁתַּ֖יִם e-seus-átrios');
INSERT INTO verses VALUES (6265, 6, 15, 61, 'no-deserto casa a arábia midim e sucata:');
INSERT INTO verses VALUES (6266, 6, 15, 62, 'e nabashan e a cidade- o-sal e ou- gedi cidades seis e-seus-átrios');
INSERT INTO verses VALUES (6267, 6, 15, 63, 'e-a o-jebuseu habitantes-de Jerusalém não filhos-de Judá para horisham e-ele-habitou o-jebuseu a filhos-de até o-dia até o-dia a-esta');
INSERT INTO chapters VALUES (203, 6, 16, 10);
INSERT INTO verses VALUES (6268, 6, 16, 1, 'e-saiu hagoral para-filhos-de José de jordan Jericó para os Jericó do-oeste no deserto sube de-irique na-montanha casa-de El');
INSERT INTO verses VALUES (6269, 6, 16, 2, 'e-saiu do-o El luzah e-passou a fronteira-de o arco atarot');
INSERT INTO verses VALUES (6270, 6, 16, 3, 'e-desceu- para-o-mar a até o-japhleti até /fronteira casa-de e-sejam inferior e-até gazar a-ti para-o-mar');
INSERT INTO verses VALUES (6271, 6, 16, 4, 'e herdaram filhos-de José Manassés Efraim:');
INSERT INTO verses VALUES (6272, 6, 16, 5, 'e-houve fronteira-de filhos-de Efraim e-houve E-foi fronteira-de-a sua herança para-o-nascente Atarots אַדָּר até casa Choron altíssimo');
INSERT INTO verses VALUES (6273, 6, 16, 6, 'e saiu a/esta fronteira o mar as ondas mitzafon e eleveu a fronteira do oriente o vento Shiloh e-passou com-ele do leste Yanohá:');
INSERT INTO verses VALUES (6274, 6, 16, 7, 'e desceu מִיּוֹנָחָה עֲטָרוֹת וְנַעֲרָתָה וּפָגַע֙ בִּֽירִיח֔וֹ וְיָצָ֖א o-Jordão');
INSERT INTO verses VALUES (6275, 6, 16, 8, 'מִתַּפּ֜וּחַ יֵלֵ֨ךְ o-gu-bo-l יָ֙מָּה֙ vale-de comprou e-sejam os saídos dele o mar esta herança bastão-de filhos-de Efraim para-famílias-deles');
INSERT INTO verses VALUES (6276, 6, 16, 9, 'e as montanhas as divisões aos-filhos-de Efraim no-meio-de herança filhos-de Manassés todo as-cidades e-seus-átrios');
INSERT INTO verses VALUES (6277, 6, 16, 10, 'e-não possuíram a o-cananeu o-habitante em-Gezer e-ele-habitou o cananeu בְּקֶ֤רֶב אֶפְרַיִם até e-houve esta E-foi até servo');
INSERT INTO chapters VALUES (204, 6, 17, 18);
INSERT INTO verses VALUES (6278, 6, 17, 1, 'e-houve o sorteio para-tribo-de Manassés porque ele primogênito-de José a Machir בְּכוֹר menasheh pai-de que ele ser foi homem guerra e-foi a-ele הַגִּלְעָ֥ד וְהַבָּשָֽׁן׃');
INSERT INTO verses VALUES (6279, 6, 17, 2, 'e-houve para-os-filhos-de Manassés הַנּוֹתָרִים֮ לְמִשְׁפְּחֹתֵיהֶֽם para-os-filhos-de אֲבִיעֶ֜זֶר וְלִבְנֵי־ חֵ֗לֶק e filhos de אַשְׂרִיאֵל֙ e-lixos- sekeim e-lixos- Estas e-para-filhos-de shamida'' eileh filhos-de m''nashe filho-de José הַזּכָּרִים para-famílias-deles');
INSERT INTO verses VALUES (6280, 6, 17, 3, 'e-litzlapachad- filho-de khefer filho-de gil''ead filho-de a-ele filho-de que não hayu para-ele filhos porque se filhas e-estes nomes-de filhas Machla e Noa Chagla de-Malka e Tirtza');
INSERT INTO verses VALUES (6281, 6, 17, 4, 'e ofereceram-na em-frente-de-a Elazar o-sacerdote ante Yehoshua filho-de Nun ante os príncipes dizendo yhwh ordenou a Moisés para-dar no-meio-de heranca E-colocou a-eles E-deu yhwh a no-meio-de yhwh נֶחֱלָה no-meio-de irmãos-de seu-pai');
INSERT INTO verses VALUES (6282, 6, 17, 5, 'e caíram חַבְלוֹי- מְנַשֶּׁה Asaraha לְבַד מֵאֶרֶץ o-Gileade וְהַבָּשָׁן que do-outro-lado לַיַּרְדֵּן׃');
INSERT INTO verses VALUES (6283, 6, 17, 6, 'que filhas-de Manassés נָחֲלוּ heranca no-meio-de filhos e-terra-de Gileade era filhos-de מְנַשֶּׁה הַנּוֹתְרִים׃');
INSERT INTO verses VALUES (6284, 6, 17, 7, 'e-houve [גְבוּל־מְנַשֶּׁה֙] [מֵֽאָשֵׁ֔ר] [הַֽמִּכְמְתָ֔ת] [אֲשֶׁ֖ר] que sobre face-de [הַגְּבוּל֙] [אֶל־הַיָּמִ֔ין] [אֶל־יֹשְׁבֵ֖י] a [תַּפּֽוּחַ] a olho');
INSERT INTO verses VALUES (6285, 6, 17, 8, 'para-Manassés era terra תַּפּ֑וּחַ וְתַפּ֛וּחַ a fronteira-de מְנַשֶּׁ֖ה Efrayim');
INSERT INTO verses VALUES (6286, 6, 17, 9, 'e desce o limite ribeiro-de compra Nebába para o vale cidades estes para-Efraim no-meio-de cidades-de Manassés e limite מְנַשֶּׁה do-norte para o vale e-houve suas saídas o mar:');
INSERT INTO verses VALUES (6287, 6, 17, 10, 'NEGEB para-EFRÁIM e-TZAFONAH para-MENASHE e-houve o-mar sua-/fronteira e-em-AÍSER se-encontrarão mitzafon e-em-YISSÁKAR do-mrzach:');
INSERT INTO verses VALUES (6288, 6, 17, 11, 'e-houve para-MENASHE בְּיִשָׂשכָ֣ר וּבְאָשֵׁ֗ר casa-de Shean וּ֠בְנוֹתֶיהָ וְיִבְלְעָ֨ם וּבְנוֹתֶ֜יהָ e-a habitantes-de דֹ֣אר וּבְנוֹתֶ֗יהָ וְיֹשְׁבֵ֤י עֵֽין־ דֹּר֙ e-as filhas delas e-os habitantes de a confissão e-as filhas delas ve-yoshevi Megido e-as filhas delas três a desolada:');
INSERT INTO verses VALUES (6289, 6, 17, 12, 'e-não poderiam filhos-de Manassés expulsar a as cidades estas e-concordou o-kenaani para-habitar na-terra a esta');
INSERT INTO verses VALUES (6290, 6, 17, 13, 'e-foi que fortaleceram-se filhos-de Israel e-eles-distribuíram a o-cananeu lapsou-se não não despojou-o');
INSERT INTO verses VALUES (6291, 6, 17, 14, 'e falaram filhos-de José a dizendo dizendo deste a-mim para mim herança um um um um e eu até muito até yhwh até disse abençoarei-te yhwh');
INSERT INTO verses VALUES (6292, 6, 17, 15, 'E-disse a-eles Josué se tu folhas-de a-ti sobe para-ti a-ti e farás crescer para-ti nome em-terra-de o-perizzita a-ti porque firmeza a-ti monte-de Efrayim');
INSERT INTO verses VALUES (6293, 6, 17, 16, 'e-disseram filhos-de José não será encontrado para-nós o-monte e carro ברזל em-todo o-cananeu o-que-está-sentado em-terra-de הערך לאשׁר na-casa-de sha-an ובנותיה לאשׁר na-vale Jeová-sara');
INSERT INTO verses VALUES (6294, 6, 17, 17, 'E-disse יְהוֹשֻׁעַ a casa José [וְלִמְנַשֶּׁ֖ה] dizendo dizendo tu muito [גָּדוֹל֙] para-ti grande a-ti não um um');
INSERT INTO verses VALUES (6295, 6, 17, 18, 'que הר ele-será- para-você ele bosque ele a-ti e-será a-ti יצואותיו que טוריש a a-ele que carro-de ele a-ele porque forte ela');
INSERT INTO chapters VALUES (205, 6, 18, 28);
INSERT INTO verses VALUES (6296, 6, 18, 1, 'va-yikkhalu todo congregação-de filhos-de Israel Siló e habitamos nome E-a-terra tenda reunião E-a-terra e fomos submetidas diante-deles');
INSERT INTO verses VALUES (6297, 6, 18, 2, 'e foram separadas filhos-de Israel que não e dividiram a sua herança sete tribos:');
INSERT INTO verses VALUES (6298, 6, 18, 3, 'E-disse Yehoshua a filhos-de Israel até [מִתְרַפִּ֔ים] vós [לָרֶ֣שֶׁת] para-vir para-possuir dar a-vós yhwh deu a-vós yhwh');
INSERT INTO verses VALUES (6299, 6, 18, 4, 'dai a-vós três homens para a tribo e enviarei-lhes e levantar-se-ão e andarão na-terra e escreverão ela: por sua herança e entrarem para-mim');
INSERT INTO verses VALUES (6300, 6, 18, 5, 'e dividirem-se a-ela sete partes Judá irá-se-estabelecer sobre gevuló -do-negue e-casa-de José irá-se-estabelecer-vos sobre e-sejam -do-zaphôn');
INSERT INTO verses VALUES (6301, 6, 18, 6, 'e-vós escrivereis a a-terra Sete -de-chalák e-vós-levareis para-mim aqui-estes a-vós a-vos -do-goral אֵלֶּה yhwh yhwh Elohim-nosso');
INSERT INTO verses VALUES (6302, 6, 18, 7, 'que não-há חֵ֤לֶק לַלְוִיִּ֔ם no meio de vós yhwh כְּהֻנָּתָ֖ה yhwh נַחֲלָתוֹ וְגָד וּרְאוּבֵן וַחֲצִי שֵׁבֶט הַמְנַשֶּׁה tomaram a herança do outro lado do rio ao Jordão dar a-eles deu a-eles yhwh servo yhwh');
INSERT INTO verses VALUES (6303, 6, 18, 8, 'e levantaram-se os-homens e-foram E-ordenou Josué a aqueles que andavam para escrever dizendo a-terra dizendo na-terra e caminharam na terra e escrevam a-ela e retornem a-mim a-vós lançarei para-vós yhwh diante-de yhwh em-Silo');
INSERT INTO verses VALUES (6304, 6, 18, 9, 'e saíram os-homens e-passaram na-terra e escreveram-na para as cidades sete partes sobre livro e vieram a יְהוֹשֻׁעַ a muito Shiloh:');
INSERT INTO verses VALUES (6305, 6, 18, 10, 'e lançou a-eles Josué sorteio em Betsálem diante-de yhwh e partilhou nome Josué a a-terra para-filhos-de Israel como haviam partido');
INSERT INTO verses VALUES (6306, 6, 18, 11, 'e-subiu sorteio bastão-de filhos-de Benjamim segundo-famílias-deles e-saiu território entre entre filhos-de e-entre e-entre filhos-de José');
INSERT INTO verses VALUES (6307, 6, 18, 12, 'e-houve a-eles a fronteira ao lado de צָפ֖וֹנָה de o Jordão e subirá o limite a a axila Jericó do Zafon e subirá no monte ים suas saídas do deserto casa iniquidade');
INSERT INTO verses VALUES (6308, 6, 18, 13, 'e passará mishšām hagbūl luẓāh a ombro luẓāh negbābah ela casa-de El veyarad hagbul ʿattarōt ʾaddār sobre hahāhar que מִן-נֶגֶב para-casa-de חֹרֵון תחתון׃');
INSERT INTO verses VALUES (6309, 6, 18, 14, '[וְתָאַ֣ר] [הַגְּבוּל֩] [וְנָסַ֨ב] [לִפְאַת־יָ֜ם] [נֶ֗גְבָּה] para-o-sul de [עַל־פְּנֵ֥י] que sobre face-de casa-de [תֹֽצְאֹתָ֗יו] [אֶל־קִרְיַת־בַּ֙עַל֙] [הִ֚יא] a cidade-de- [עִ֖יר] ela cidade-de esta cidade filhos-de');
INSERT INTO verses VALUES (6310, 6, 18, 15, '[וּפְאַת־נֶ֕גְבָּה] [מִקְצֵ֖ה] de-fim-de cidade-de Jearim [הַגְּבוּל֙] [יָ֔מָּה] [וְיָצָ֕א] [אֶל־מַעְיַ֖ן] a [נֶפְתּֽוֹחַ]');
INSERT INTO verses VALUES (6311, 6, 18, 16, 'וירד הגבול a fim o monte que sobre face-de גי filho-de hinnom que na-vale rephaim para-o-norte e descerá valley hinnom a ombro o-jebuseu negeb e descerá olho rodado:');
INSERT INTO verses VALUES (6312, 6, 18, 17, 'e marcará mizpeh e-saiu olho shemesh e-saiu a גְּלִיל֔וֹת que נחבק מַעֲלֵ֣ה pedra וְיָרַ֕ד pedra בֹּ֖הַן filho-de Reuven-verso');
INSERT INTO verses VALUES (6313, 6, 18, 18, '[וְעָבַ֛ר] a [מוּל־הֽ͏ָעֲרָבָ֖ה] [צָפ֑וֹנָה] [וְיָרַ֖ד] [הָעֲרָבָֽתָה]');
INSERT INTO verses VALUES (6314, 6, 18, 19, 'e-passou הַגְּב֜וּל a côtof casa-de chagláh tsafoná o gúvel a lóshôn mar- o mélakh tsáfoneh a extremidade o Jordão négvá este fronteira-de negue:');
INSERT INTO verses VALUES (6315, 6, 18, 20, 'e o Jordên igúvel- ele esta קדמה zóh נַחֲלַת֩ filhos-de בִנְיָמִ֧ן לִגְבֽוּלֹתֶ֛יהָ ao-redor para-famílias-deles');
INSERT INTO verses VALUES (6316, 6, 18, 21, 'e-sejam [הֽ͏ֶעָרִ֗ים] [לְמַטֵּ֛ה] filhos-de [בִנְיָמִ֖ן] [לְמִשְׁפְּחֽוֹתֵיהֶ֑ם] [יְרִיח֥וֹ] e-casa-de [וְעֵ֥מֶק] [קְצִֽיץ]');
INSERT INTO verses VALUES (6317, 6, 18, 22, '[וּבֵ֧ית] [הֽ͏ָעֲרָבָ֛ה] [וּצְמָרַ֖יִם] [וּבֵֽית־אֵֽל] El');
INSERT INTO verses VALUES (6318, 6, 18, 23, '[וְהָעַוִּ֥ים] [וְהַפָּרָ֖ה] [וְעָפְרָֽה]');
INSERT INTO verses VALUES (6319, 6, 18, 24, '[וּכְפַ֧ר] [*העמני] [**הָֽעַמֹּנָ֛ה] cidades duas- dez e-seus-átrios');
INSERT INTO verses VALUES (6320, 6, 18, 25, 'Gbouon e Harama e Be''orot');
INSERT INTO verses VALUES (6321, 6, 18, 26, 'e Hamatzpe e Hacfeira e Hamotza');
INSERT INTO verses VALUES (6322, 6, 18, 27, 'e-Rekem e Yirpeal e Teraala');
INSERT INTO verses VALUES (6323, 6, 18, 28, 'e Tsela Ha''elef וְהַיְבוּסִ֨י ela יְרֽוּשָׁלִַ֙ם֙ colina-de קִרְיַ֔ת cidades אַרְבַּֽע־ dez esta זֹ֛את נַֽחֲלַ֥ת filhos-de dizendo para-famílias-deles');
INSERT INTO chapters VALUES (206, 6, 19, 51);
INSERT INTO verses VALUES (6324, 6, 19, 1, 'e-saiu הַגּוֹרָ֤ל o-segundo לְשִׁמְע֔וֹן para-matate filhos-de שִׁמְע֖וֹן e-houve E-foi no-meio-de em-meio-de herança filhos-de Judá');
INSERT INTO verses VALUES (6325, 6, 19, 2, 'e-houve a-eles בְּנַֽחֲלָתָ֑ם בְּאֵֽר־ sete e sete e nascimento:');
INSERT INTO verses VALUES (6326, 6, 19, 3, 'e-atrio-de shual e balah e osso:');
INSERT INTO verses VALUES (6327, 6, 19, 4, 'e gerou-se e virgem e harma:');
INSERT INTO verses VALUES (6328, 6, 19, 5, 'e zicalag e-casa-de as caravelas e-atrio-de Susa:');
INSERT INTO verses VALUES (6329, 6, 19, 6, 'e-casa-de para-ovos e-sarochen cidades três- dez e-seus-átrios');
INSERT INTO verses VALUES (6330, 6, 19, 7, 'olho rimmon e-uter e-fumou cidades quatro e-seus-átrios');
INSERT INTO verses VALUES (6331, 6, 19, 8, 'e-todo os-chetzerim que ao-redor-de as-urim os-estes até na-alat no-er esta Nebeg esta herança-de bastão-de filhos-de שמעון para-famílias-deles');
INSERT INTO verses VALUES (6332, 6, 19, 9, '[מֵחֶ֙בֶל֙] filhos-de Judá [נַחֲלַ֖ת] filhos-de Simeão porque foi [בְּנֵֽי־יְהוּדָה֙] filhos-de Judá muito de-eles no-meio-de filhos-de');
INSERT INTO verses VALUES (6333, 6, 19, 10, 'e-subiu [הַגּוֹרָ֣ל] o-terceiro para-filhos-de Zebulom segundo-famílias-deles e-houve fronteira-de [נַחֲלָתָ֖ם] até');
INSERT INTO verses VALUES (6334, 6, 19, 11, 'e-subiu גבולם ⁃ לים ⁄ e mar''ălā e pāga'' em-dabbāšēt e pāga'' a o-nachal que sobre face-de adquiri-os:');
INSERT INTO verses VALUES (6335, 6, 19, 12, 'וְשָׁ֣ב do-sarīḏ le-kedāmā do-mizrāḵ o-sol sobre fronteira-de como-selōṯ tāḇōr e-saiu a a palavra e-subirá faça brilhar;');
INSERT INTO verses VALUES (6336, 6, 19, 13, 'e de lá, passou oriente para-o-nascente Gatá Chéfer Uta Katsín e saiu; Rimon o anunciado a jovem;');
INSERT INTO verses VALUES (6337, 6, 19, 14, 'e elevou-se ele o limite norte a generosidade e-sejam seus caminhos rios e abriria El');
INSERT INTO verses VALUES (6338, 6, 19, 15, 'e se estendesse e floresceria e prosperaria e se tornaria frutífera e-Beit pão cidades duas- dez e-seus-átrios');
INSERT INTO verses VALUES (6339, 6, 19, 16, 'esta herança filhos-de Zebulom para suas famílias as cidades estes e-seus-átrios');
INSERT INTO verses VALUES (6340, 6, 19, 17, 'para Zebulom sair o sorteio o-quarto para-os-filhos-de Issacar para suas famílias:');
INSERT INTO verses VALUES (6341, 6, 19, 18, 'e-houve seu limite Jizreel e as cisternas e a Sion:');
INSERT INTO verses VALUES (6342, 6, 19, 19, 'e Chapharaim וְשִׁיאֹ֖ן וַאֲנָחֲרַֽת׃');
INSERT INTO verses VALUES (6343, 6, 19, 20, '[וְהָֽרַבִּ֥ית] [וְקִשְׁי֖וֹן] [וָאָֽבֶץ]');
INSERT INTO verses VALUES (6344, 6, 19, 21, '[וְרֶ֧מֶת] [וְעֵין־גַּנִּ֛ים] [וְעֵ֥ין] [חַדָּ֖ה] [וּבֵ֥ית] e-casa-de');
INSERT INTO verses VALUES (6345, 6, 19, 22, 'e se encontrou o limite de Tábor e-Beit shemesh seriam saídas e-sejam o Jordão cidades seis-de dez e-seus-átrios');
INSERT INTO verses VALUES (6346, 6, 19, 23, 'esta herança bastão-de filhos-de Issacar segundo-famílias-deles as-cidades e-seus-átrios');
INSERT INTO verses VALUES (6347, 6, 19, 24, 'e-saiu הַגּוֹרָ֣ל o quinto para-matate filhos-de que para suas famílias:');
INSERT INTO verses VALUES (6348, 6, 19, 25, 'e-houve [גְּבוּלָ֑ם] campo-de [וַחֲלִ֖י] [וָבֶ֥טֶן] [וְאַכְשָֽׁף]');
INSERT INTO verses VALUES (6349, 6, 19, 26, 'ואלמלך ועמעד ומשaal ופגעה בככרמל הים e na Sichor Líbna:');
INSERT INTO verses VALUES (6350, 6, 19, 27, 'e voltará do oriente da luz do sol casa Dagon e se chocou com Zebulom e em Gabei Iftach- El הצפון casa העמק ונויאל e-saiu a כובל משם׃');
INSERT INTO verses VALUES (6351, 6, 19, 28, '[וְעֶבְרֹ֥ן] [וּרְחֹ֖ב] [וְחַמּ֣וֹן] [וְקָנָ֑ה] até Sidom multiplicai');
INSERT INTO verses VALUES (6352, 6, 19, 29, 'ושוב o-guér-bul הָֽרָמָ֔ה e-até cidade mib-tsár- tsóh vé-sháv o-guér-bul chosáh totséótáy hayyámah mehével akhzává');
INSERT INTO verses VALUES (6353, 6, 19, 30, 'e-umá e-apêk e-rakhôv cidades vinte e-shethêym e-seus-átrios');
INSERT INTO verses VALUES (6354, 6, 19, 31, 'esta herança bastão-de filhos-de que segundo-famílias-deles as-cidades estes e-seus-átrios');
INSERT INTO verses VALUES (6355, 6, 19, 32, 'aos-filhos-de Naftali sair o-gôrâl o-shêshî para-filhos-de Naftali para-famílias-deles');
INSERT INTO verses VALUES (6356, 6, 19, 33, 'e-houve seu-gublâm em-chêlep de-êlôn בּ-צַעֲנַנּוֹת וַאֲדָמִי הַנֶּ֔קֶב וְיַבְנְאֵ֑ל até e-houve E-foi תֹצְאֹתָ֑יו o-Jordão');
INSERT INTO verses VALUES (6357, 6, 19, 34, 'וְשָׁ֔ב הַגְּב֥וּל יָ֙מָּה֙ אַזְנ֣וֹת Tabor e-saiu de-lá חוּקֹ֑קָה e se encontrei -vizlûn do Neguebe e em Asher atacou águas e em Judá o Jordão nascente-de o-sol');
INSERT INTO verses VALUES (6358, 6, 19, 35, 'e cidades de Mitzar os zidim Cer e Hamat רַקַּ֥ת וְכִנָּֽרֶת׃');
INSERT INTO verses VALUES (6359, 6, 19, 36, '[וַאֲדָמָ֥ה] [וְהָרָמָ֖ה] [וְחָצֽוֹר]');
INSERT INTO verses VALUES (6360, 6, 19, 37, '[וְקֶ֥דֶשׁ] [וְאֶדְרֶ֖עִי] [וְעֵ֥ין] [חָצֽוֹר]');
INSERT INTO verses VALUES (6361, 6, 19, 38, 'וְיִרְאוֹן֙ e-migdal- El charem e-casa-de anat e-Beit sol cidades teshá- dez e-seus-átrios');
INSERT INTO verses VALUES (6362, 6, 19, 39, 'esta nachalat- bastão-de filhos-de Naftali segundo-famílias-deles as-cidades e-seus-átrios');
INSERT INTO verses VALUES (6363, 6, 19, 40, 'para-matate filhos-de Dan sair יצאה hagoral o sétimo');
INSERT INTO verses VALUES (6364, 6, 19, 41, 'e-houve território nachalatham tsara veshataol- ve''ir do-sol');
INSERT INTO verses VALUES (6365, 6, 19, 42, 'vesha''alabin וְאַיָּל֖וֹן וְיִתְלָֽה׃');
INSERT INTO verses VALUES (6366, 6, 19, 43, '[וְאֵיל֥וֹן] [וְתִמְנָ֖תָה] [וְעֶקְרֽוֹן]');
INSERT INTO verses VALUES (6367, 6, 19, 44, '[וְאֶלְתְּקֵ֥ה] [וְגִבְּת֖וֹן] [וּבַעֲלָֽת]');
INSERT INTO verses VALUES (6368, 6, 19, 45, '[וִיהֻ֥ד] [וּבְנֵֽי־בְרַ֖ק] [וְגַת־רִמּֽוֹן]');
INSERT INTO verses VALUES (6369, 6, 19, 46, '[וּמֵ֥י] [הַיַּרְק֖וֹן] [וְהָֽרַקּ֑וֹן] com [מ֥וּל] [יָפֽוֹ]');
INSERT INTO verses VALUES (6370, 6, 19, 47, 'e-ele-saiu [גְבוּל־בְּנֵי־דָ֖ן] filhos-de Dan deles e-subiram filhos-de [וַיִּלְכְּד֥וּ] [אוֹתָ֣הּ] com [וַיַּכּ֧וּ] [אוֹתָ֣הּ] [לְפִי־חֶ֗רֶב] [וַיִּֽרְשׁ֤וּ] [אוֹתָהּ֙] à-boca-de espada [וַיִּקְרְא֤וּ] a-ela [דָּ֔ן] nela [דָּ֥ן] [אֲבִיהֶֽם]');
INSERT INTO verses VALUES (6371, 6, 19, 48, 'esta [נַחֲלַ֛ת] bastão-de filhos-de Dan segundo-famílias-deles [הָאֵ֖לֶּה] estes');
INSERT INTO verses VALUES (6372, 6, 19, 49, 'e se cessaram para a herança- a a-terra para as porções dela va-yittenu filhos-de Israel herança a Josué filho-de נוּן em-meio-de-eles');
INSERT INTO verses VALUES (6373, 6, 19, 50, 'sobre yhwh yhwh a-ele para-ele a a-cidade que perguntou-se a Timná- Seráque em-monte-de Efraim e edificou a a-cidade e-habitou nela');
INSERT INTO verses VALUES (6374, 6, 19, 51, 'Estas as heranças que nichlu Eleazar o-sacerdote vayuhashua filho-de nuwn ve''rashei ha''avot lematot filhos-de yisra''el bego''al besiloh diante-de yhwh yhwh tenda reunião vayekallu מֵֽחַלֵּ֖ק a a-terra');
INSERT INTO chapters VALUES (207, 6, 20, 9);
INSERT INTO verses VALUES (6375, 6, 20, 1, 'e-falou yhwh a dizendo');
INSERT INTO verses VALUES (6376, 6, 20, 2, 'palavra a filhos-de dizendo dizendo a-vós a-vós a cidades-de o-refugio que falei a-vós por-mão-de Moisés');
INSERT INTO verses VALUES (6377, 6, 20, 3, '[לָנ֥וּס] [שָׁ֙מָּה֙] [רוֹצֵ֔חַ] [מַכֵּה־נֶ֥פֶשׁ] alma em-erro e-sejam a-vós e-serão a-vós [הַדָּֽם]');
INSERT INTO verses VALUES (6378, 6, 20, 4, 'וְנָ֞ס a אַחַ֣ת ׀ מֵהֶעָרִ֣ים estes e-estandou פתח portão a-cidade וְדִבֶּ֛ר nos-ouvidos aquela a as-palavras e-gatherem-se ele a-cidade a-eles e-derem lugar lugar e-sentar-se-á com-eles');
INSERT INTO verses VALUES (6379, 6, 20, 5, 'e-que perseguir-ele-vai-a-perseguir גּוֹאֵל ha-dam atrás-dele e-não e-fecharem a que na-sua-mão porque sem דַ֙עַת֙ ele a-ele companheiro-seu e-não odiou ele para-ele de-ontem terceiro-dia');
INSERT INTO verses VALUES (6380, 6, 20, 6, 'e-sentar-se-á na-cidade a aquela até עָמְדוֹ diante-de הָעֵדָה לַמִּשְׁפּוֹט até môt o-sacerdote a-grande será será em-os-dias os-aqueles אָז voltara הָרוֹצֵחַ e vindo a עִירוֹ e-a casa-dele a a-cidade que Nas de-lá');
INSERT INTO verses VALUES (6381, 6, 20, 7, 'וַיַּקְדִּישׁוּ a quedês em-a-galil em-monte-de Naftali e-a שְׁכֶם em-monte-de Efraim e-a Quiriate quatro ela Hebrom em-monte-de Judá');
INSERT INTO verses VALUES (6382, 6, 20, 8, 'e-de-ao-lado לְיַרְדּוֹן יְרִיחוֹ para-o-nascente נָתְנ֞וּ a בֶּ֧צֶר no-deserto בַּמִּישֹׁ֖ר de-a-tribo Rúben e-a Ramat em-a-Gilead מִמַּטֵּה־ Gade e-a em-a-Bashan מִמַּטֵּ֥ה מְנַשֶֽׁה׃');
INSERT INTO verses VALUES (6383, 6, 20, 9, 'Estas הָיוּ֩ עָרֵ֨י הַמּֽוּעָדָ֜ה a-todo filhos-de Israel e ao estrangeiro o estrangeiro entre vós לָנ֣וּס ali todo מַכֵּה־ alma בִּשְׁגָגָ֑ה e-não morrerá em-mão-de גֹּאֵ֣ל o-sangue até עָמְד֖וֹ diante-de הָעֵדָֽה׃');
INSERT INTO chapters VALUES (208, 6, 21, 45);
INSERT INTO verses VALUES (6384, 6, 21, 1, '[וַֽיִּגְּשׁ֗וּ] [רָאשֵׁי֙] [אֲב֣וֹת] os-levitas a Eleazar o-sacerdote e-a Yehoshua filho-de נ֑וּן e-a cabeças-de Israel');
INSERT INTO verses VALUES (6385, 6, 21, 2, 'וַיְדַבְּר֨וּ a-eles בְּשִׁלֹ֗ה em-terra Canaan dizendo yhwh ordenou na-mao-de Moisés para-dar para-nós cidades para se estabelecerem e de suas possessões para nossos animais');
INSERT INTO verses VALUES (6386, 6, 21, 3, 'va-yittenu filhos-de Israel aos levitas de sua herança yhwh boca-de yhwh a as-cidades estes e-a de suas possessões');
INSERT INTO verses VALUES (6387, 6, 21, 4, 'e-ele-saiu a sorte para-famílias-de o-coatita e-houve para os filhos de Arão o-sacerdote de os-levitas de-a-tribo Yehudah e-de-a-tribo do ouvinte e-de-a-tribo Benjamim no-o-sorteio cidades três dez');
INSERT INTO verses VALUES (6388, 6, 21, 5, 'e-a-filhos-de Qehath ha-notharim [מִמִּשְׁפְּחֹ֣ת] bastao-de- Efraim e-de-a-tribo- דָ֞ן וּמֵחֲצִ֨י מַטֵּ֧ה mennasheh ba-goral cidades dez');
INSERT INTO verses VALUES (6389, 6, 21, 6, 'e-para-filhos-de גֵרְשׁ֗וֹן מִמִּשְׁפְּח֣וֹת bastao-de- יִשָׂשכָ֣ר מַטֵּ֧ה que e-de-a-tribo נַפְתָּלִ֜י וּ֠מֵחֲצִי matteh- מְנַשֶּׁ֤ה בהברושָׁן֙ no-o-sorteio cidades três dez');
INSERT INTO verses VALUES (6390, 6, 21, 7, 'para-os-filhos-de מְרָרִ֜י למשפחותם ממטטה Rúben וממטטה־ גד e-de-a-tribo Zebulom cidades dois dez');
INSERT INTO verses VALUES (6391, 6, 21, 8, 'e-eles-deram filhos-de Israel [אֶת־הֶעָרִ֥ים] a [וְאֶת־מִגְרְשֵׁיהֶ֑ן] estes e-[OBJ] yhwh como-que ordenou yhwh Moisés');
INSERT INTO verses VALUES (6392, 6, 21, 9, 'WAYITTNU ממטטהה filhos-de Judá e-de-matate filhos-de Simeão a העריא֣ם os-estes que יִקְרָ֥א a-elas בשם׃');
INSERT INTO verses VALUES (6393, 6, 21, 10, 'e-aconteceu aos-filhos-de Arão [מִמִּשְׁפְּח֥וֹת] [הַקְּהָתִ֖י] de-filhos-de Levi que a-eles ser [הַגּוֹרָ֖ל] [רִיאשֹׁנָֽה]');
INSERT INTO verses VALUES (6394, 6, 21, 11, 'va-yittenu a-eles a קִרְיַת֩ quatro Pai a Anoq ela Hebrom em-monte-de Judá e-a de sua propriedade em-o-seus-vicinhanças-verso-final');
INSERT INTO verses VALUES (6395, 6, 21, 12, 'e-a campo-de a-cidade e-a cortiãos-dela para-Calev filho-de se estendesse em sua posse');
INSERT INTO verses VALUES (6396, 6, 21, 13, 'e-lixos- Aarão o-sacerdote e deram a cidade refúgio הָרֹצֵ֔חַ a Hebrom e-a de sua propriedade e-a para-Bet-Lahem e-a de sua propriedade');
INSERT INTO verses VALUES (6397, 6, 21, 14, 'e-a e além disso e-a seus-arredores e-a ouvi e-a de sua propriedade');
INSERT INTO verses VALUES (6398, 6, 21, 15, 'e-[OBJ] [וְאֶת־מִגְרָשֶׁ֔הָ] e-[OBJ] seus-arredores e-[OBJ] palavra e-[OBJ]');
INSERT INTO verses VALUES (6399, 6, 21, 16, 'e-a olho e-a migrašěhā e-a יֻטָּה֙ e-a seus-arredores a casa sol e-a migrašěhā cidades nove de-a segundo הַשְּׁבָטִ֖ים as estas');
INSERT INTO verses VALUES (6400, 6, 21, 17, 'e-de-a-tribo Benjamim a גִּבְעוֹן e-a migrašěhā a גֶּ֖בַע e-a migrašěhā');
INSERT INTO verses VALUES (6401, 6, 21, 18, 'a [וְאֶת־מִגְרָשֶׁ֔הָ] e-[OBJ] seus-arredores e-[OBJ] [אַרְבַּֽע] e-[OBJ] quatro');
INSERT INTO verses VALUES (6402, 6, 21, 19, 'todo cidades-de filhos-de אַהֲרֹן הַכֹּֽהֲנִ֑ים três- doze cidades וּמִגְרְשֵׁיהֶֽן׃');
INSERT INTO verses VALUES (6403, 6, 21, 20, 'וּלְמִשְׁפְּח֤וות filhos-de Qehath- os-levitas הַנּוֹתָרִ֖ים de-filhos-de e-houve E-foi cidades-de גורלָם mi-matteh Efrayim');
INSERT INTO verses VALUES (6404, 6, 21, 21, 'va-yittenu a-eles a cidade מִקְלַט הָרֹצֵחַ a Shekem e-a migrašěhā em-monte-de Efraim e-a Gezer e-a migrašěhā');
INSERT INTO verses VALUES (6405, 6, 21, 22, 'e-[OBJ] [וְאֶת־מִגְרָשֶׁ֔הָ] e-[OBJ] seus-arredores e-[OBJ] casa [אַרְבַּֽע׃] e-[OBJ] quatro');
INSERT INTO verses VALUES (6406, 6, 21, 23, '[וּמִמַּ֨טֵּה־דָ֔ן] Dã a [אֶֽת־גִּבְּת֖וֹן] e-[OBJ] a e-[OBJ]');
INSERT INTO verses VALUES (6407, 6, 21, 24, 'a ayylon e-a seus-arredores a gat- rimmon e-a מִגְרָשֶׁהָ cidades quatro');
INSERT INTO verses VALUES (6408, 6, 21, 25, 'u-mim-machatiyth tribo-de Manassés a תּעַנַּךְ e-a seus-arredores e-a gat- rimmon e-a de-mercês cidades sh-t-y-im');
INSERT INTO verses VALUES (6409, 6, 21, 26, 'todo cidades dez [לְמִשְׁפְּח֥וֹת] [בְּנֵֽי־קְהָ֖ת] filhos-de');
INSERT INTO verses VALUES (6410, 6, 21, 27, '[וְלִבְנֵ֣י] [גֵרְשׁוֹן֮] [מִמִּשְׁפְּחֹ֣ת] [הַלְוִיִּם֒] [מֵחֲצִ֞י] tribo-de Menasheh a cidade [הָרֹצֵ֔חַ] [אֶת־*גלון] a [בַּבָּשָׁן֙] e-[OBJ] seus-arredores e-[OBJ] [עָרִ֖ים] e-[OBJ]');
INSERT INTO verses VALUES (6411, 6, 21, 28, '[וּמִמַּטֵּ֣ה] [יִשָׂשכָ֔ר] a [וְאֶת־מִגְרָשֶׁ֑הָ] e-[OBJ] [וְאֶת־מִגְרָשֶֽׁהָ] a e-[OBJ]');
INSERT INTO verses VALUES (6412, 6, 21, 29, 'a [וְאֶת־מִגְרָשֶׁ֔הָ] e-[OBJ] seus-arredores a olho [אַרְבַּֽע׃] e-[OBJ] quatro');
INSERT INTO verses VALUES (6413, 6, 21, 30, 'e-de-a-tribo que a MISSÃO e-a מִגְרָשֶׁ֑הָ a abdon e-a מִגְרָשֶֽׁהָ׃');
INSERT INTO verses VALUES (6414, 6, 21, 31, 'a [וְאֶת־מִגְרָשֶׁ֔הָ] e-[OBJ] seus-arredores e-[OBJ] [אַרְבַּֽע׃] e-[OBJ] quatro');
INSERT INTO verses VALUES (6415, 6, 21, 32, 'e-de-a-tribo נַפְתָּלִי a עִיר מִקְלַט הָרֹצֵחַ a קֶדֶשׁ בַּגָּלִ֤יל e-a מִגְרָשֶׁהָ e-a [וְאֶת־קַרְתָּ֖ן] דּאֹר e-a seus-arredores e-a [sem-traducao] e-a de-migrašéhā cidades três');
INSERT INTO verses VALUES (6416, 6, 21, 33, 'todo cidades-de o-gersonita segundo-famílias-deles três- doze cidade e-migrešéyen');
INSERT INTO verses VALUES (6417, 6, 21, 34, 'e-lémishpókhat filhos-de amar-doce os levitas os-restantes de-com tribo-de Zebulom a comprá''em e-a מִגְרָשֶׁ֑הָ a cortáh e-a מִגְרָשֶׁ֑הָ');
INSERT INTO verses VALUES (6418, 6, 21, 35, 'a dimnáh e-a seus-arredores a nahalál e-a מִגְרָשֶׁ֑הָ cidades quatro');
INSERT INTO verses VALUES (6419, 6, 21, 36, 'e-de-a-tribo Rúben a betsér e-a מִגְרָשֶׁ֑הָ e-a yatza e-a מִגְרָשֶׁ֑הָ');
INSERT INTO verses VALUES (6420, 6, 21, 37, 'a kedemot e-a seus-arredores e-a mipá''at e-a em-megrašeḥā cidades quatro');
INSERT INTO verses VALUES (6421, 6, 21, 38, 'e-mimatte Gad a cidade miklat הָרֹצֵ֔חַ a Ramote de-Gileade e-a em-megrašeḥā e-com acampamentos e-a em-megrašeḥā');
INSERT INTO verses VALUES (6422, 6, 21, 39, 'a Hesbom e-a seus-arredores a Ya''zer e-a em-megrašeḥā todo cidades quatro');
INSERT INTO verses VALUES (6423, 6, 21, 40, 'todo ha''arim para-filhos-de מררי לְמִשְׁפְּחֹתָ֔ם ha''notarim mimishpachot e-houve E-foi gorlam cidades dois dez');
INSERT INTO verses VALUES (6424, 6, 21, 41, 'todo cidades-de os-levitas no-meio-de achuzat filhos-de Israel cidades quarenta e-oito u''migrshehen');
INSERT INTO verses VALUES (6425, 6, 21, 42, 'תִּהְיוּ ha-arim os-estes cidade cidade u''migrashayha seu-volta-tes assim para-todo as-cidades as estas');
INSERT INTO verses VALUES (6426, 6, 21, 43, 'yhwh yhwh a a-terra que nishebá para-dar para os pais e-lhe-er-rash-o-ha e-habitaram em-ela');
INSERT INTO verses VALUES (6427, 6, 21, 44, 'e-nah yhwh a-eles de-ao-redor conforme-tudo que nishebá para os pais e-não ficou-em-pé homem em-seu-rosto-les de-todo dar yhwh todo dar deu yhwh com-a-mão-deles');
INSERT INTO verses VALUES (6428, 6, 21, 45, 'não caindo de-toda de-todo a-palavra o-bom yhwh palavra yhwh a casa Israel o-ouro veio');
INSERT INTO chapters VALUES (209, 6, 22, 34);
INSERT INTO verses VALUES (6429, 6, 22, 1, 'então chamaria Yehoshua para-reuveni e-para-gadi e-para-metade-de bastão-de Mênashé:');
INSERT INTO verses VALUES (6430, 6, 22, 2, 'E-disse a-eles vós guardai a todo que ordenou vos Moisés yhwh yhwh e-vocês-ouvir-ais a-todo para-todo que ordenei a-vós');
INSERT INTO verses VALUES (6431, 6, 22, 3, 'não עֲזַבְתֶּ֣ם a irmãos-de-vocês este até o-dia até o-dia este e-guardai yhwh guarda mandamento yhwh Elohim-vosso');
INSERT INTO verses VALUES (6432, 6, 22, 4, 'e-agora deixar yhwh Elohim-vosso para-vos conforme palavra a-eles e-agora avançai-vos e-avançai a-vós para-vossas-casa a terra possui-vos que dar a-vós Moisés servo yhwh em-além-de o-Jordão');
INSERT INTO verses VALUES (6433, 6, 22, 5, 'somente shimru muito muito a a mandar e-a a-torah que ordenou a-vós Moisés servo- yhwh para-amar a yhwh vos-elohimes e para a sua marcha em-todo seus caminhos e-para-guardar suas mandamentos que ele e para servi-lo em-todo nosso coração e-em-todo nossas almas:');
INSERT INTO verses VALUES (6434, 6, 22, 6, 'e os abençoou Yehoshua e-ele-enviou-os e-foram a suas tendas:');
INSERT INTO verses VALUES (6435, 6, 22, 7, 'e a metade da tribo-de Manassés deu dar na Basã e-lhe-pressionou deu dar com irmãos-deles o Jordão para-o-mar e-tambem porque e-silhacou que a seus-em-campamentos e-lhes-benzeu:');
INSERT INTO verses VALUES (6436, 6, 22, 8, 'E-disse a-eles dizendo em-cavernas רַבִּים שֻׁבוּ a seus-campamentos e-em-gado chefe-de muito Be-khesef e-em-ouro e-em-negros e-em-ferrares muito muito muito chilquem shelal- אֹיְבֵיכֶ֖ם com acheychem:');
INSERT INTO verses VALUES (6437, 6, 22, 9, 'e-voltaram vayyalku filhos-de Reuben e-filhos-de Gad vaḥatsi tribo-de hamenashsheh de-com filhos-de Israel mishiloh que em-terra-de assim para andar a terra hagilead a terra yhwh que noachazu- nela sobre yhwh yhwh por-mão-de Moisés');
INSERT INTO verses VALUES (6438, 6, 22, 10, 'e-vieram a gellelot o-Jordão que em-terra-de assim e edificaram filhos-de Reuben e-filhos-de Gad וַחֲצִ֣י tribo da Manassés nome um-altar à-vista o-Jordão um altar grande para ver');
INSERT INTO verses VALUES (6439, 6, 22, 11, 'וַיִּשְׁמְע֥וּ filhos-de dizendo eis eis e edificaram filhos-de Reuben e-filhos-de Gad e a metade da tribo terra a o-altar a móel terra Canaã a gállilótes o-Jordão a éver filhos-de Israel');
INSERT INTO verses VALUES (6440, 6, 22, 12, 'וַֽיִּשְׁמְע֖וּ filhos-de Israel vayíqqáhălu todo congregação-de filhos-de Israel Siló a-subir sobre-eles látsaba');
INSERT INTO verses VALUES (6441, 6, 22, 13, 'e-enviaram filhos-de Israel a filhos-de réuven e-a filhos-de gad e-a metade-de bastão-de- ménashé a terra o-gileade a pínchas filho-de Eleazar o-sacerdote');
INSERT INTO verses VALUES (6442, 6, 22, 14, 'vá''ăśarah נשִׂיאִים com-ele נשִׂיא um נשִׂיא um para-casa-de pai a-todo tribos-de Israel e-homem cabeça casa-de pais-deles eles לאלפי Israel');
INSERT INTO verses VALUES (6443, 6, 22, 15, 'e-vieram a filhos-de [וְאֶל־חֲצִ֥י] e-a filhos-de [הַגִּלְעָ֑ד] e-a metade-de dizendo a terra');
INSERT INTO verses VALUES (6444, 6, 22, 16, 'assim [אָמְר֞וּ] todas congregação-de yhwh yhwh [מָֽה־הַמַּ֤עַל] este que [מְעַלְתֶּם֙] [בֵּאלֹהֵ֣י] Israel para-voltar o-dia de-após yhwh [בִּבְנֽוֹתְכֶ֤ם] a-vós altar [לִמְרָדְכֶ֥ם] o-dia [בַּיהוָֽה]');
INSERT INTO verses VALUES (6445, 6, 22, 17, '[הַמְעַט־לָ֙נוּ֙] a-nós a iniquidade [לֹֽא־הִטַּהַ֙רְנוּ֙] nós até o-dia dele e-houve o-dia esta yhwh yhwh');
INSERT INTO verses VALUES (6446, 6, 22, 18, 'e-vós [תָּשֻׁ֣בוּ] o-dia de-após yhwh e-foi [אַתֶּ֞ם] [תִּמְרְד֤וּ] o-dia em-יהוה [וּמָחָ֕ר] a todo [יִקְצֹֽף] Israel');
INSERT INTO verses VALUES (6447, 6, 22, 19, 'e-somente se terra terra aquisição-vos a-vós para-vocês a yhwh aquisição yhwh que yhwh nome tabernáculo-de yhwh e-aceitar-se-ão no-médio-nós e-em-Yahweh a a-vós e-nos a vibrar-se-ão yhwh para-vocês altar sem-médio-de yhwh yhwh Elohim-nosso');
INSERT INTO verses VALUES (6448, 6, 22, 20, 'não-haveria Acaão filho-de Zera subida מעל no-herem e-sobre todo ser Israel foi קatsef um não um não tremeu בְּעָוֹן׃');
INSERT INTO verses VALUES (6449, 6, 22, 21, '[וַֽיַּעֲנוּ֙] filhos-de Reuben e-filhos-de Gade [הַֽמְנַשֶּׁ֑ה] tribo-de o-Manassés [אַלְפֵ֥י] a Israel');
INSERT INTO verses VALUES (6450, 6, 22, 22, 'El [׀] yhwh [׀] yhwh yhwh ele soube [׀] yhwh ele sabe [וְיִשְׂרָאֵ֖ל] ele [יֵדָ֑ע] em-יהוה a [בַּֽיהוָ֔ה] o-dia o-dia');
INSERT INTO verses VALUES (6451, 6, 22, 23, 'para-construir a-nós altar para-retornar de-depois-de yhwh e-se [עָלָ֜יו] sobre-ele [וּמִנְחָ֗ה] [וְאִם־לַעֲשׂ֤וֹת] e-se [זִבְחֵ֣י] sobre-ele yhwh ele yhwh');
INSERT INTO verses VALUES (6452, 6, 22, 24, 'e-se não מִדְּאָגָה֙ מִדָּבָ֔ר עָשִׂ֥ינוּ dizendo esta dizendo amanhã dizem dizendo para nossos dizendo que vós e para יְהוָה Elohim-de Israel');
INSERT INTO verses VALUES (6453, 6, 22, 25, 'e fronteira deu yhwh entre nós e entre vós filhos-de Rúben e-filhos-de Gad a o-Jordão não-há para-vós para-não em-יהוה e destruam vossos filhos a בָּנֵ֔ינוּ para-não יְרֹ֥א a yhwh');
INSERT INTO verses VALUES (6454, 6, 22, 26, '[וַנֹּ֕אמֶר] [נַעֲשֶׂה־נָּ֣א] agora para-nós para-construir não o-altar não [לְזָֽבַח] e-não');
INSERT INTO verses VALUES (6455, 6, 22, 27, 'que até ele [בֵּינֵ֣ינוּ] [וּבֵינֵיכֶ֗ם] e-entre [דֹּרוֹתֵינוּ֮] [אַחֲרֵינוּ֒] para-lavrar a yhwh yhwh diante-dele [וּבִזְבָחֵ֖ינוּ] [וּבִשְׁלָמֵ֑ינוּ] [וְלֹא־יֹאמְר֨וּ] e-não [מָחָר֙] [לְבָנֵ֔ינוּ] amanhã [חֵ֖לֶק] não-há');
INSERT INTO verses VALUES (6456, 6, 22, 28, 'וַנֹּ֕אמֶר e-foi porque dirao אֵלֵ֛ינוּ e-a דֹּרֹתֵ֖ינוּ amanhã- וְאָמַ֡רְנוּ Reu yhwh Tábinit altar-de não que fizeram Avóteynu não ele e-não Lézevach porque até ele [sem-traducao] e-entre-voces');
INSERT INTO verses VALUES (6457, 6, 22, 29, 'infelizmente Lánu nós Limrod BáYahawah Vésabov o-dia de-depois-de yhwh para-edificar altar para-oferta Lémnachá e para matar apenas mizbakh yhwh nosso-Elohim que diante-de de sua tenda:');
INSERT INTO verses VALUES (6458, 6, 22, 30, 'E-ouviu Pinhas o-sacerdote e os chefes a-congregação e-cabeças-de milhares de Israel que com-ele a as-palavras que disseram filhos-de Reuben e-filhos-de Gad e-filhos-de Manassés e-foi-bom em seus olhos:');
INSERT INTO verses VALUES (6459, 6, 22, 31, 'E-disse Pinhas filho-de Eleazar הַכֹּהֵן a filhos-de Reuben o-dia filhos-de Gad e-a yhwh Menasheh hoje sabemos porque em-nos yhwh que não voc-ele-alteram em-יהוה yhwh esta que salva-vo-lo a filhos-de Israel de-mão-de yhwh');
INSERT INTO verses VALUES (6460, 6, 22, 32, 'e-estabeleceu-se pinhas filho-de Eleazar o-sacerdote e-os-príncipes de-junto-de filhos-de reuven e-de filhos-de Gad da-terra-de a-gileadeus a terra kena''an a filhos-de Israel ele eles palavra');
INSERT INTO verses VALUES (6461, 6, 22, 33, 'e-foi-bom a-palavra nosso-olhos filhos-de Israel e-benzeram Elohim filhos-de Israel e-não אָמְר֗וּ para subir sobre-eles la-tzava para destruir a a-terra que filhos-de Reuben e-filhos-de que moradores nela');
INSERT INTO verses VALUES (6462, 6, 22, 34, 'e-chamaram filhos-de [וּבְנֵי־גָ֖ד] e-filhos-de que para-o-altar ele até que yhwh porque yhwh');
INSERT INTO chapters VALUES (210, 6, 23, 16);
INSERT INTO verses VALUES (6463, 6, 23, 1, 'e-aconteceu dos mares muitos depois-de que yhwh yhwh para Israel de-todo seus inimigos em-o-redor וִיהוֹשֻׁ֣עַ velho veio nos tempos:');
INSERT INTO verses VALUES (6464, 6, 23, 2, 'E-chamou יְהוֹשֻׁעַ para-todo Israel para seus velhos e para suas cabeças e para seus juízes E-disse E-disse a-eles eu eu me envelheci eu vim nos-dias:');
INSERT INTO verses VALUES (6465, 6, 23, 3, 'e-vós vistes את todo que yhwh yhwh Elohim-vosso para-todo as-nações que yhwh porque ele vosso-Elohim a-vós o-nilhám a-vós');
INSERT INTO verses VALUES (6466, 6, 23, 4, 'vêem eu-spaltei a-vós a os-povos os-que-restaram os-estes na-inheritance para-tribos-de-vós de o-Jordão e-todo as-nações que eu-cortei e-o-mar o-grande מְב֥וֹא o-sol');
INSERT INTO verses VALUES (6467, 6, 23, 5, 'e-יהוה vosso-Elohim ele as-impelirei de-diante-vosso e expulsará eles de-vos e herdarão a terra-deles como-que yhwh yhwh a-vós a-vós');
INSERT INTO verses VALUES (6468, 6, 23, 6, 'e fortalecer-vos-á muito para guardar e para fazer a todo o escrito בספר lei-de para-não para-não vai-te dele direita e-esquerda');
INSERT INTO verses VALUES (6469, 6, 23, 7, 'para-não venha em-nos os povos estes os que restaram estes convosco e pelo nome deles os elohimes não lembrai-vos e-não sacreditai-os e-não servei-os a-eles e adorai-os para-eles');
INSERT INTO verses VALUES (6470, 6, 23, 8, 'que se em耶和华 Elohim de-vós e clingais como até o-dia o-dia a-esta');
INSERT INTO verses VALUES (6471, 6, 23, 9, 'e expulsou yhwh de-diante-vosso nações gordéis e fortes e-vós não ficou-em-pé homem até o-dia o-dia a-esta');
INSERT INTO verses VALUES (6472, 6, 23, 10, 'homem-de um de vós que mil yhwh yhwh ele ele a-vós a-vós conforme a-vós a-vós');
INSERT INTO verses VALUES (6473, 6, 23, 11, 'venishmartem muito para as vossas almas em amor a yhwh Elohim-vosso');
INSERT INTO verses VALUES (6474, 6, 23, 12, 'que se voltaram voltares-vos e clingais-vos em excesso as-nações os-estes o que restou estes convosco e suplicastes-vos בָּהֶ֛ם וּבָאתֶ֥ם neles e-eles em-vos:');
INSERT INTO verses VALUES (6475, 6, 23, 13, 'יָד֙וֹעַ֙ תֵּֽדְע֔וּ que não יוֹסִ֜יף yhwh אֱלֹהִים-vo/ós לְהוֹרִ֛ישׁ a as-nações estes e-sejam a-vós para-vocês לְפַ֣ח וּלְמוֹקֵ֗שׁ וּלְשֹׁטֵ֤ט בְּצִדֵּיכֶם֙ e-lícenines em-ueincêem de-cima-de a-terra de-al a terra a-tôváh dar a-vós yhwh a-vós yhwh Elohim-vosso');
INSERT INTO verses VALUES (6476, 6, 23, 14, 'e-eis eu holêk o-dia em-caminho-de todo a-terra e-idâutêm em-todo que e-em-todo de-vossas-almas um de-toda nafal palavra um de-tol as-palavras yhwh que palavra yhwh vosso-elohim a-vós o-tudo nós a-vós um cair dele palavra um');
INSERT INTO verses VALUES (6477, 6, 23, 15, 'e-foi conforme- veio sobre-vós todo a-coisa o-bom yhwh palavra yhwh Elohim de-vós a-vós yhwh יביא yhwh sobre-vocês a todo a-coisa de-cima-de a-terra que-destruiu o-vos de-acima dar a-vós yhwh que deu a-vós yhwh Elohim-vosso');
INSERT INTO verses VALUES (6478, 6, 23, 16, 'em-vós a yhwh yhwh vosso-elohim que ordenou vós e se vós marchardes e-servi-vos Elohim outros a-eles para-eles e-ardeu também yhwh em-vós de-cima-de a-terra de-sobre a-terra dar a-vós deu a-vós');
INSERT INTO chapters VALUES (211, 6, 24, 33);
INSERT INTO verses VALUES (6479, 6, 24, 1, 'e-reuniu-se יְהוֹשֻׁעַ a todo tribos-de E-chamou Siquém E-chamou para-os-velhos Israel e-para-os-cabeças e-lhos-pétāvō e-lhot-trāvō va-yit-ya-tsăbū diante-de Elohim');
INSERT INTO verses VALUES (6480, 6, 24, 2, 'E-disse Josué a todo yhwh assim disse yhwh o-rio Israel em-além-de o-nahar yash-bū vossos-pais mē-ʿōlām Terach pai-de Abraão e-pai-de Nacor e-serviram Elohim aḥērim');
INSERT INTO verses VALUES (6481, 6, 24, 3, 'va-ʾe-qăḵā a avīkhem a o-rio de-über o-rio e-o-olékh com-ele em-todo terra assim a s-seu-zaréu e-e-tétên- para-ele a Isaque');
INSERT INTO verses VALUES (6482, 6, 24, 4, 'e-e-tétên para-isaque a Jacó e-a Esaú e-e-tétên para-av-esóav a o-har שֵׂעִיר֙ para-possuir com-ele e-yáqób e-seus-filhos desceram Egito');
INSERT INTO verses VALUES (6483, 6, 24, 5, 'e-e-shelekh a Moisés e-com Arão e enchi a Egito como fiz em-meio-dele e-depois הוציתי a-vós');
INSERT INTO verses VALUES (6484, 6, 24, 6, 'e saí a vossos-pais do-Egito e vieram o mar e perseguiram Egito atrás-de seus-pai ברכב e em barcos mar-de juncos');
INSERT INTO verses VALUES (6485, 6, 24, 7, 'e gritaram a yhwh e-ele-postou ainda que entre vós e-entre os egípcios e-trouxe sobre-o a o mar e cobriu-o vossos-olhos vosso olhos a que fiz em-Egito e-habitastes no deserto dias muitos');
INSERT INTO verses VALUES (6486, 6, 24, 8, 'a-vos a terra o amorite aquele que habita em-além-de o-Jordão e-lutaram convosco e dei os em vossas mãos e herdastes a terra-deles e exterminai-os de-diante-vosso');
INSERT INTO verses VALUES (6487, 6, 24, 9, 'E-levantou Balak filho-de Cipor rei Moabe וַיִּלָּחֶם em-Israel E-chamou E-chamou para Balaão filho-de no deserto para maldizê-lo a-vós');
INSERT INTO verses VALUES (6488, 6, 24, 10, 'e-não minha sogra para-ouvir para Balaão E-abençoou abençoe vos e resgatei vos de sua mão');
INSERT INTO verses VALUES (6489, 6, 24, 11, 'e atravessaram a o Jordão— e chegaram a a Jericó— e-combateram em-vós dos elohimes dos Jericó— os amorreus— e os pivieus— e os cananeus— e os hititas— e o gregos הֽ͏ַחִוּ֖י e-o-jebuseu eles eles em-mão-vossa');
INSERT INTO verses VALUES (6490, 6, 24, 12, 'e-enviei ante vós a a serpente e expulsou elas de-diante-vosso segundo reis-de não não com a tua espada e-não com a tua arco');
INSERT INTO verses VALUES (6491, 6, 24, 13, 'e dei a-vós terra que não e te feriste bah e cidades que não que vossas edificastes e ficaram com-eles como videiros e oliveiras que não plantastes vós comerdes');
INSERT INTO verses VALUES (6492, 6, 24, 14, 'e-agora virão a ver a yhwh ele ele em verdade e em realidade e removerão a Elohim que servireis o-rio em-lado-de o-river e-em-Misraim e-servei a yhwh');
INSERT INTO verses VALUES (6493, 6, 24, 15, 'e-se mau em-vossos-olhos para-lavrar a yhwh a-vós o-dia ho-dia-- a quem vós-servireis mãe a Elohim que serviram o-rio que o-rio e se a Elohim-de o-amorreu que vós yoshvim-acento-grave em-a-terra-deles e-eu e-nha-casa nós-serviremos a yhwh');
INSERT INTO verses VALUES (6494, 6, 24, 16, 'e-respondeu o-povo E-disse longe-seja [לָּ֔נוּ] [מֵעֲזֹ֖ב] a para-lavrar para-servir Elohim');
INSERT INTO verses VALUES (6495, 6, 24, 17, 'que yhwh Elohim-nosso ele הַמַּעֲלֶ֨ה אֹתָ֧נוּ e-a אֲבוֹתֵ֛ינוּ de-terra-de Egito de-casa-de עֲבָדִ֑ים e-que fez לְעֵינֵ֗ינוּ a הָאֹת֤וֹת הַגְּדֹלוֹת֙ estes וַֽיִּשְׁמְרֵ֗נוּ em-todo o-caminho que נחנו nela e-em-todo os-povos que עברנו em-meio-deles-versículo-final');
INSERT INTO verses VALUES (6496, 6, 24, 18, '[וַיְגָ֨רֶשׁ] yhwh a todo [יֹשֵׁ֥ב] a-terra o-emori habitou a-terra [אֶת־יְהוָ֔ה] também [אֱלֹהֵֽינוּ׃] a yhwh porque');
INSERT INTO verses VALUES (6497, 6, 24, 19, 'E-disse Josué a não não para-lavrar [אֶת־יְהוָ֔ה] a yhwh ele Elohim ele ele a [וּלְחַטֹּאותֵיכֶֽם] não');
INSERT INTO verses VALUES (6498, 6, 24, 20, 'que taʿazvu a yhwh vaʿavadtem Elohim-de ne-char vesheva a-vós a-vós e-terminou vos depois-de a-vós hiteiv a-vós');
INSERT INTO verses VALUES (6499, 6, 24, 21, 'E-disse o-povo a não que porque a yhwh');
INSERT INTO verses VALUES (6500, 6, 24, 22, 'E-disse Josué a o povo testemunhas vós bekhem porque a-vós becharchtem para-lavrar a yhwh laʿavod otto e-disseram edim');
INSERT INTO verses VALUES (6501, 6, 24, 23, 'e-agora [הָסִ֛ירוּ] a Elohim-de [אֲשֶׁ֣ר] que em-meio-vosso [אֶת־לְבַבְכֶ֔ם] a [Elohim] a yhwh Israel');
INSERT INTO verses VALUES (6502, 6, 24, 24, 'e-disseram o-povo a Yehoshua a yhwh Elohim-nosso [נִשְׁמָֽע]');
INSERT INTO verses VALUES (6503, 6, 24, 25, 'וַיִּכְרֹ֨ת יְהוֹשֻׁ֧עַ em-o-brith ao-povo no-dia o-aquele e-colocou a-ele חֹ֥ק וּמִשְׁפָּ֖ט בִּשְׁכֶם׃');
INSERT INTO verses VALUES (6504, 6, 24, 26, 'וַיִּכְתֹּ֤ב יְהוֹשֻׁעַ a as-palavras os-estes בספר lei-de E-tomou pedra pedra grande e levantou-a debaixo em-lugar-de a-aláh que yhwh yhwh');
INSERT INTO verses VALUES (6505, 6, 24, 27, 'E-disse Josué a eis o povo eis a pedra esta será- e colocaram-na para-assembléia porque yhwh ouviram-na a todo palavras yhwh que palavra com-nosso e-será que para-assembléia para-que-não tremem nos vossos elohimes:');
INSERT INTO verses VALUES (6506, 6, 24, 28, 'e-ele-mandou יְהוֹשֻׁעַ a o-povo homem para-sua-inheritance');
INSERT INTO verses VALUES (6507, 6, 24, 29, 'e-houve depois-de as-palavras os-estes E-morreu יְהוֹשֻׁ֥עַ filho-de נוּן yhwh yhwh filho-de cem e-dez dois');
INSERT INTO verses VALUES (6508, 6, 24, 30, 'e-sepultaram ele em-limite-de herança-sua em-תִמְנַת־ [אֲשֶׁ֣ר] que em-monte-de Efraim');
INSERT INTO verses VALUES (6509, 6, 24, 31, '[וַיַּעֲבֹ֤ד] Israel a yhwh dias-de dias-de e-tudo e-todo dias-de os-anciãos que prolongaram dias depois-de Yehoshua e-que [יָדְע֗וּ] a todo yhwh yhwh que fez');
INSERT INTO verses VALUES (6510, 6, 24, 32, 'e-a suas próprias יוֹסֵף que elevaram filhos-de יִשְׂרָאֵ֥ל מִמִּצְרַיִם֮ קָבְר֣וּ בִשְׁכֶם֒ בְּחֶלְקַ֣ת o-campo que קָנָ֧ה Jacó de-junto-de filhos-de Hamor pai-de sh-keim בְּמֵאָ֣ה קְשִׂיטָ֑ה E foram filhos-de José לְנַחֲלָֽה׃');
INSERT INTO verses VALUES (6511, 6, 24, 33, 'Elaúzar filho-de אַהֲרֹן morreu ele a-ele bigivata Pinhas seu-filho que נִתַּן־ a-ele em-monte-de Efrayim');
INSERT INTO books VALUES (7, 'JDG', 'Juízes', 'AT', 21);
INSERT INTO chapters VALUES (212, 7, 1, 36);
INSERT INTO verses VALUES (6512, 7, 1, 1, 'e-houve depois-de morrendo Yehoshua e-perguntaram filhos-de Israel em-יהוה dizendo quem subirá- para-nós a o-cananeu em-o-início para-lutar em-ele');
INSERT INTO verses VALUES (6513, 7, 1, 2, 'E-disse yhwh יְהוּדָה subia eis dei a a-terra em-mão-sua');
INSERT INTO verses VALUES (6514, 7, 1, 3, 'E-disse יְהוּדָה para-Simeão irmão-dele folhas-de comigo em-sorte-minha e-lutaremos em-o-cananeu e-irei também eu contigo em-sorte-tua E-andou com-ele Simeão');
INSERT INTO verses VALUES (6515, 7, 1, 4, 'e-subiu Judá E-colocou yhwh a o-cananeu e-o-perizeu em-mão-deles e-feriram-eles em-Bezeque dez dois-mil homem');
INSERT INTO verses VALUES (6516, 7, 1, 5, 'e-encontraram a Adonai Bezeque em-Bezeque e-lutaram nele e-feriram a o-cananeu e-a o-perizeu');
INSERT INTO verses VALUES (6517, 7, 1, 6, 'e-fugiu Adonai Bezeque e-perseguiram atrás-dele e-agarraram ele e-cortaram a polegares-de mãos-dele e-pés-dele');
INSERT INTO verses VALUES (6518, 7, 1, 7, 'E-disse adonai-de Bezeque setenta reis polegares-de mãos-deles e-pés-deles cortados eram catando debaixo mesa-minha como-que fiz assim pagou- para-mim Elohim e-trouxeram-no Jerusalém E-morreu nome');
INSERT INTO verses VALUES (6519, 7, 1, 8, 'e-lutaram filhos-de יְהוּדָה em-Jerusalém e-capturaram ela e-feriram-na à-boca-de espada e-a a-cidade puseram em-o-fogo');
INSERT INTO verses VALUES (6520, 7, 1, 9, 'e-depois desceram filhos-de Judá para-lutar em-o-cananeu habitante-de a-montanha e-o-neguebe e-a-planície');
INSERT INTO verses VALUES (6521, 7, 1, 10, 'E-andou Judá a o-cananeu o-habitante em-Hebrom e-Shem Hebrom antes cidade-de quatro e-feriram a sexto e-a Aimã e-a Talmai');
INSERT INTO verses VALUES (6522, 7, 1, 11, 'E-andou de-lá a habitantes-de Debir e-Shem Debir antes cidade-de- livro');
INSERT INTO verses VALUES (6523, 7, 1, 12, 'E-disse Calebe que ferir a cidade-de- a-ele e-capturar-a e-darei para-ele a Acsa filha-minha para-mulher');
INSERT INTO verses VALUES (6524, 7, 1, 13, 'e-capturou-a Otniel filho-de Quenaz irmão-de o-pequeno nós de-ele e-ele-deu para-ele a Acsá filha-dele para-mulher');
INSERT INTO verses VALUES (6525, 7, 1, 14, 'e-houve em-vir-dela e-ela-incitou-o para-pedir de-com pai-dela o-campo de-cima-de de-sobre o-jumento e-ele-disse para-ela Calebe que- para-ti');
INSERT INTO verses VALUES (6526, 7, 1, 15, 'E-disse a-ele dá para-mim que terra terra o-sul tu-me-deste e-tu-darás para-mim fontes-de águas e-ele-deu para-ela Calebe את fontes-de superiores e-a fontes-de inferiores');
INSERT INTO verses VALUES (6527, 7, 1, 16, 'e-filhos-de queneus sogro-de Moisés subiram de-cidade-de as-palmeiras a filhos-de Judá deserto-de Judá que em-sul-de Arade E-andou e-habitou a o-povo');
INSERT INTO verses VALUES (6528, 7, 1, 17, 'E-andou Judá a Simeão irmão-seu e-feriram a o-cananeu habitante-de Zefate E-chamou a-ela E-chamou a nome-de a-cidade Hormá');
INSERT INTO verses VALUES (6529, 7, 1, 18, 'e-ele-capturou Judá a Gaza e-a território-dela e-com Asquelom e-a território-dela e-a Ecrom e-a território-dela');
INSERT INTO verses VALUES (6530, 7, 1, 19, 'e-houve yhwh a Judá e-ele-possuiu que não porque não para-desapossar a habitantes-de a-eles porque carros-de ferro para-eles');
INSERT INTO verses VALUES (6531, 7, 1, 20, 'e-eles-deram para-Calebe a Hebrom como-assim palavra Moisés e-ele-desapossou de-lá a três filhos-de o-Enaque');
INSERT INTO verses VALUES (6532, 7, 1, 21, 'e-a o-jebuseu habitou não não eles-desapossaram filhos-de Benjamim e-ele-habitou o-jebuseu a filhos-de até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (6533, 7, 1, 22, 'e-subiram casa-de José também eles casa-de El e-יהוה com-eles');
INSERT INTO verses VALUES (6534, 7, 1, 23, 'e-eles-exploraram casa-de José em-Betel El e-Shem a-cidade antes Luz');
INSERT INTO verses VALUES (6535, 7, 1, 24, 'e-eles-viram os-guardas homem saindo de a-cidade a-ele para-ele mostra-nos por-favor a pôr-de a-cidade e-faremos contigo bondade');
INSERT INTO verses VALUES (6536, 7, 1, 25, 'e-ele-mostrou-lhes a pôr-de a-cidade e-eles-feriram a a-cidade ao-fio-de espada e-a o-homem e-a todo família-dele eles-enviaram');
INSERT INTO verses VALUES (6537, 7, 1, 26, 'E-andou o-homem terra os-heteus E-edificou cidade E-chamou nome-dela Luz ele nome-dela até o-dia a-esta');
INSERT INTO verses VALUES (6538, 7, 1, 27, 'e-não ele-desapossou Menasheh a casa-de Shean e-a em-filhas-suas e-a Taanak e-a em-filhas-suas e-a Dor e-a em-filhas-suas e-a habitantes-de Yivleam e-a em-filhas-suas e-a habitantes-de Megido e-a em-filhas-suas e-concordou o-kenaani para-habitar na-terra a esta');
INSERT INTO verses VALUES (6539, 7, 1, 28, 'e-aconteceu porque forte Israel e-colocou a o-cananeu não e-despojar não despojou-o');
INSERT INTO verses VALUES (6540, 7, 1, 29, 'e-Efrayim não despojou a o-cananeu o-habitante em-Gezer e-habitou o-cananeu em-meio-seu em-Gezer');
INSERT INTO verses VALUES (6541, 7, 1, 30, 'Zevulun não despojou a habitantes-de Kitron e-a habitantes-de Nahalol e-habitou o-cananeu em-meio-seu e-foram para-tributo');
INSERT INTO verses VALUES (6542, 7, 1, 31, 'que não despojou a habitantes-de Ako e-a habitantes-de Tsidon e-a Ahlab e-a Akziv e-a Helbah e-a Afik e-a Rehov');
INSERT INTO verses VALUES (6543, 7, 1, 32, 'e-habitou o-asheri em-meio-de o-cananeu habitantes-de a-terra que não despojou-o');
INSERT INTO verses VALUES (6544, 7, 1, 33, 'Naftali não despojou a habitantes-de casa-de Shemesh e-a habitantes-de casa-de a-terra e-habitou em-meio-de o-cananeu habitantes-de a-terra a-eles casa-de Shemesh e-Beit Anat foram a-eles para-tributo');
INSERT INTO verses VALUES (6545, 7, 1, 34, 'e-oprimiram o-emori a filhos-de Dan a-montanha porque não deu-o para-descer ao-vale');
INSERT INTO verses VALUES (6546, 7, 1, 35, 'e-concordou o-emori para-habitar em-monte-de Heres em-Ayalon e-em-Shaalbim e-pesou mão casa-de José e-foram para-tributo');
INSERT INTO verses VALUES (6547, 7, 1, 36, 'e-fronteira-de o-amorreu desde-subida-de Akrabim desde-a-rocha e-para-cima');
INSERT INTO chapters VALUES (213, 7, 2, 23);
INSERT INTO verses VALUES (6548, 7, 2, 1, 'e-subiu anjo-de yhwh de o-Gilgal E-disse o-Bokim E-disse fiz-subir a-vós desde-Mitsrayim e-trouxe a-vós a a-terra que jurei para-pais-de-vocês e-eu-disse não eu-quebrarei aliança-minha com-vocês para-eternidade');
INSERT INTO verses VALUES (6549, 7, 2, 2, 'e-vós não vocês-cortareis aliança a-terra a-terra esta altares-deles vocês-quebrareis e-não vocês-ouviram em-voz-minha que- esta vocês-fizeram');
INSERT INTO verses VALUES (6550, 7, 2, 3, 'e-também eu-disse não eu-expulsarei eles e-sejam a-vós para-vocês para-lados e-elohim-deles a-vós para-vocês para-laço');
INSERT INTO verses VALUES (6551, 7, 2, 4, 'e-houve como-falar-de mensageiro-de yhwh a as-palavras os-estes a todo filhos-de Israel e-levantaram o-povo a voz-deles e-choraram');
INSERT INTO verses VALUES (6552, 7, 2, 5, 'e-chamaram nome-de o-lugar o-aquele choradores e-sacrificaram nome para-יהוה');
INSERT INTO verses VALUES (6553, 7, 2, 6, 'e-enviou Yehoshua a o-povo e-foram filhos-de Israel homem para-herança-sua para-possuir a a-terra');
INSERT INTO verses VALUES (6554, 7, 2, 7, 'e-serviram o-povo a yhwh dias-de dias-de e-tudo e-todo dias-de os-anciãos que prolongaram dias depois-de יְהוֹשׁ֔וּעַ que viram com todo yhwh yhwh a-grande que fez para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (6555, 7, 2, 8, 'E-morreu יְהוֹשֻׁ֥עַ filho-de נוּן yhwh yhwh filho-de cem e-dez dois');
INSERT INTO verses VALUES (6556, 7, 2, 9, 'e-sepultaram ele em-limite-de herança-sua em-תִמְנַת־ חֶרֶס em-monte-de Efraim norte para-monte-de גָעַשׁ');
INSERT INTO verses VALUES (6557, 7, 2, 10, 'e-também todo a-geração a-aquela foram-recolhidos a pais-seus E-levantou geração outra depois-deles que não conheceram a yhwh e-também a a-obra que fez para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (6558, 7, 2, 11, 'e-fizeram filhos-de Israel a yhwh em-olhos-de yhwh e-serviram a os-בַעַל');
INSERT INTO verses VALUES (6559, 7, 2, 12, 'e-abandonaram a יהוה Elohim-de pais-deles o-que-tirou a-eles de-terra-de Egito e-foram depois-de Elohim outros de-elohim-de os-povos que arredores-deles e-prostraram-se para-eles a-eles a yhwh');
INSERT INTO verses VALUES (6560, 7, 2, 13, 'e-abandonaram a yhwh e-serviram para-o-בַעַל e-para-as-עַשְׁתָּרוֹת');
INSERT INTO verses VALUES (6561, 7, 2, 14, 'e-acendeu-se- yhwh yhwh em-Israel e-deu-eles por-mão-de saqueadores e-saquearam eles e-vendeu-eles em-mão-de inimigos-deles de-ao-redor e-não puderam ainda para-ficar-em-pé diante-de inimigos-deles');
INSERT INTO verses VALUES (6562, 7, 2, 15, 'em-todo que saíram mão-de yhwh estava em-eles para-mal como-que yhwh yhwh e-como-que yhwh a-eles para-eles a-eles muito muito');
INSERT INTO verses VALUES (6563, 7, 2, 16, 'E-levantou yhwh juízes e-salvou-os de-mão-de saqueadores-deles');
INSERT INTO verses VALUES (6564, 7, 2, 17, 'e-também a não não que porque prostituíram-se depois-de Elohim outros a-eles para-eles desviaram-se rapidamente de o-caminho que andaram pais-deles para-ouvir mandamentos-de yhwh não fizeram assim');
INSERT INTO verses VALUES (6565, 7, 2, 18, 'e-porque yhwh יְהוָה a-eles juízes e-era yhwh com o-juiz e-salvava-os de-mão-de inimigos-deles dias-de dias-de o-juiz yhwh arrependia-se de-diante-de de-gemido-deles de-faces-de opressores-deles e-aflitos-deles');
INSERT INTO verses VALUES (6566, 7, 2, 19, 'e-era em-morte-de o-juiz voltavam e-corrompiam mais-que-pais-deles para-andar atrás-de Elohim outros para-servi-los e-para-prostrar-se para-eles a-eles não de-ações-deles e-de-caminho-deles o-duro');
INSERT INTO verses VALUES (6567, 7, 2, 20, 'e-acendeu-se- yhwh yhwh E-disse E-disse porque que transgrediram a-nação o-este a aliança-minha que ordenei a pais-deles e-não ouviram para-voz-minha');
INSERT INTO verses VALUES (6568, 7, 2, 21, 'também não não acrescentarei para-desapossar homem de-face-deles de as-nações que deixou Yehoshua E-morreu');
INSERT INTO verses VALUES (6569, 7, 2, 22, 'para-fim-de provar com-eles a Israel eles eles yhwh caminho yhwh para-andar em-eles como guardaram pais-deles se não');
INSERT INTO verses VALUES (6570, 7, 2, 23, 'e-deixou yhwh a as-nações para-não para-não desapossá-las rapidamente e-não entregou-as por-mão-de יְהוֹשֻֽׁעַ');
INSERT INTO chapters VALUES (214, 7, 3, 31);
INSERT INTO verses VALUES (6571, 7, 3, 1, 'e-estes as-nações que deixou yhwh para-provar com-eles a Israel את todo que não conheceram את todo guerras-de כְּנָֽעַן');
INSERT INTO verses VALUES (6572, 7, 3, 2, 'somente a-fim-de conhecimento gerações-de filhos-de Israel para-ensinar-lhes guerra somente não antes não conheceram-nas');
INSERT INTO verses VALUES (6573, 7, 3, 3, 'cinco-de príncipes-de פְלִשְׁתִּ֗ים e-todo o-cananeu e-o-צִּידֹנִ֔י e-o-חִוִּ֔י habitou monte-de o-לְבָנ֑וֹן de-monte-de בַּ֣עַל חֶרְמ֔וֹן até para-entrada-de חֲמָֽת');
INSERT INTO verses VALUES (6574, 7, 3, 4, 'e-eram para-provar com-eles a para-conhecer para-saber se-ouvirão yhwh mandamentos-de yhwh que ordenou a pais-deles por-mão-de Moisés');
INSERT INTO verses VALUES (6575, 7, 3, 5, 'e-filhos-de Israel habitaram em-meio-de o-כְּנַעֲנִ֑י o-חִתִּ֤י e-o-amorreu e-o-perizeu e-o-heveu e-o-jebuseu');
INSERT INTO verses VALUES (6576, 7, 3, 6, 'e-tomaram a a-eles para-eles para-mulheres e-a filhas-deles deram para-filhos-de-eles e-serviram a אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (6577, 7, 3, 7, 'e-fizeram filhos-de Israel a yhwh em-olhos-de yhwh e-esqueceram a yhwh אֱלֹהֵיהֶם-de-eles e-serviram a os-baalins e-a as-aserás');
INSERT INTO verses VALUES (6578, 7, 3, 8, 'e-acendeu-se- yhwh yhwh em-Israel e-vendeu-os em-mão-de Cusã Risataim rei Arã Naraim e-serviram filhos-de Israel a Cusã Risataim oito dois');
INSERT INTO verses VALUES (6579, 7, 3, 9, 'e-clamaram filhos-de Israel a yhwh E-levantou yhwh salvador para-filhos-de Israel e-salvou-os את Otniel filho-de o-pequeno nós Calebe o-pequeno de-nós');
INSERT INTO verses VALUES (6580, 7, 3, 10, 'e-foi sobre-ele espírito-de yhwh e-julgou a Israel E-colocou yhwh E-deu yhwh em-mão-de-ele a Cusã Risataim sua-mão sobre e-fortaleceu mão-de-ele sobre Cusã Risataim');
INSERT INTO verses VALUES (6581, 7, 3, 11, 'e-descansou a-terra quarenta ano E-morreu Otniel filho-de Quenaz');
INSERT INTO verses VALUES (6582, 7, 3, 12, 'e-adicionaram filhos-de Israel para-fazer o-mal em-olhos-de yhwh e-fortaleceu yhwh a Eglom rei-de sobre sobre Israel sobre yhwh fizeram a o-mal em-olhos-de yhwh');
INSERT INTO verses VALUES (6583, 7, 3, 13, 'e-reuniu a-ele a filhos-de Amom e-Amaleque E-andou e-golpeou a Israel e-possuíram a cidade as-palmeiras');
INSERT INTO verses VALUES (6584, 7, 3, 14, 'e-serviram filhos-de Israel a Eglom rei-de Moabe oito dez anos');
INSERT INTO verses VALUES (6585, 7, 3, 15, 'e-clamaram filhos-de Israel a yhwh a-eles yhwh para-eles salvador a Eúde filho-de gera filho-de o-benjaminita homem fechado mão-de direita-de-ele e-enviaram filhos-de Israel em-mão-de-ele oferenda para-Eglom rei Moabe');
INSERT INTO verses VALUES (6586, 7, 3, 16, 'E-fez a-ele Eúde espada e-para-ela segundo dois-gumes côvado comprimento-de-ela e-cingiu a-ela debaixo-de para-roupas-de-ele sobre lado-de direita-de-ele');
INSERT INTO verses VALUES (6587, 7, 3, 17, 'e-aproximou a a oferta-cereais para-Eglom rei Moabe e-Eglom homem muito muito');
INSERT INTO verses VALUES (6588, 7, 3, 18, 'e-houve como-que terminou para-oferecer a a-oferenda e-enviou a o-povo carregadores-de a-oferenda');
INSERT INTO verses VALUES (6589, 7, 3, 19, 'e-ele retornou de os-ídolos que E-disse o-Gilgal E-disse palavra-de segredo E-disse a-ti o-rei E-disse silêncio e-saíram de-sobre-ele todo os-que-estavam-de-pé sobre-ele');
INSERT INTO verses VALUES (6590, 7, 3, 20, 'e-Eúde veio a-ele a-ele habitou em-quarto-alto-de o-verão que sozinho E-disse E-disse Eúde palavra-de Elohim para-mim de-cima-de E-levantou de-sobre o-trono');
INSERT INTO verses VALUES (6591, 7, 3, 21, 'e-estendeu Eúde a mão E-tomou E-tomou de-cima-de a-espada de-sobre coxa direita-de-ele e-ele-a-cravou em-ventre-dele');
INSERT INTO verses VALUES (6592, 7, 3, 22, 'E-veio também o-cabo atrás-de e-fechou e-ele-fechou a-gordura através-de que não não a-espada a-espada de-ventre-dele e-ele-saiu ha-pardona');
INSERT INTO verses VALUES (6593, 7, 3, 23, 'e-ele-saiu Eúde o-pórtico e-fechou portas-de a-câmara-alta atrás-dele e-ele-fechou');
INSERT INTO verses VALUES (6594, 7, 3, 24, 'e-ele sair e-servos-dele vieram e-eles-viram e-eis portas-de a-câmara-alta fechadas e-disseram porém cobrindo ele a pés-dele em-câmara-de o-frescor');
INSERT INTO verses VALUES (6595, 7, 3, 25, 'e-eles-esperaram até envergonhar e-eis não-ela abrindo portas-de a-câmara-alta e-tomaram a a-chave e-eles-abriram e-eis adonai-deles caído terra-para morreu');
INSERT INTO verses VALUES (6596, 7, 3, 26, 'e-Eúde escapou até demora-deles e-ele passou a os-ídolos e-ele-escapou a-Seirata');
INSERT INTO verses VALUES (6597, 7, 3, 27, 'e-houve em-vir-dele e-ele-tocou na-trombeta em-monte-de Efraim e-eles-desceram com-ele filhos-de Israel de o-monte e-ele diante-deles');
INSERT INTO verses VALUES (6598, 7, 3, 28, 'E-disse para-eles persegui após-mim porque yhwh yhwh a inimigos-vossos a Moabe em-mão-vossa e-desceram após-ele e-eles-capturaram a vaus-de o-Jordão para-Moabe e-não eles-deram homem para-passar');
INSERT INTO verses VALUES (6599, 7, 3, 29, 'e-eles-feriram a Moabe em-o-tempo a aquela como-dez-de milhares homem todo gordo e-todo homem força e-não escapou homem');
INSERT INTO verses VALUES (6600, 7, 3, 30, 'e-ela-foi-subjugada Moabe no-dia o-aquele debaixo mão Israel e-descansou a-terra oitenta anos');
INSERT INTO verses VALUES (6601, 7, 3, 31, 'e-após-ele ser Shamgar filho-de Anate e-ele-feriu a filisteus seis-de centenas-de homem com-aguilhão-de o-gado e-ele-salvou também ele a Israel');
INSERT INTO chapters VALUES (215, 7, 4, 24);
INSERT INTO verses VALUES (6602, 7, 4, 1, 'e-adicionaram filhos-de Israel para-fazer o-mal em-olhos-de yhwh e-Eúde morreu');
INSERT INTO verses VALUES (6603, 7, 4, 2, 'e-ele-os-vendeu yhwh em-mão-de Jabim rei-de Canaã que rei em-Hazor e-príncipe-de exército-dele Sísera e-ele habitante em-Harosete os-gentios');
INSERT INTO verses VALUES (6604, 7, 4, 3, 'e-clamaram filhos-de Israel que yhwh porque nove a-ele carro-de barzel a-ele ve-hu lachat a filhos-de Israel be-chazaqa vinte anos');
INSERT INTO verses VALUES (6605, 7, 4, 4, 've-dvorah mulher neviaha mulher-de lapidot ela juíza a Israel em-o tempo a-ela');
INSERT INTO verses VALUES (6606, 7, 4, 5, 'e-ela sentada debaixo-de tamar entre entre e-entre e-entre casa-de El em-monte-de Efraim e-eles-subiram a-ela filhos-de Israel para-o-julgamento');
INSERT INTO verses VALUES (6607, 7, 4, 6, 'e-ele-enviou e-ela-chamou para-barak filho-de Abinuam de-Qedeshe E-disse a-ele a-ele não comandou- yhwh Elohim-de- Israel vai [בְּהַ֣ר] em-monte-de Tabor וְלָקַחְתָּ em-voce dez milhares homem de-filhos-de Naftali e-dos-filhos Zevulun-');
INSERT INTO verses VALUES (6608, 7, 4, 7, 'e-mashachtiti eleicha a vale-de kishon a sisra- príncipe-de exército-de yavin- e-a rikbo- e-a hamono- unehtatehu em-mão-teu');
INSERT INTO verses VALUES (6609, 7, 4, 8, 'E-disse para-ela barak se vai com-mim e-andei e-se não não com-mim não irei.');
INSERT INTO verses VALUES (6610, 7, 4, 9, 'E-disse andou irei com-te no-entanto que não serás tua-glória sobre o-caminho tu tu que porque em-a-mão- yhwh venderá yhwh a Sisra e-levantou-se Debora e-partiu-se com Barak santa');
INSERT INTO verses VALUES (6611, 7, 4, 10, 'e-clamou Barak a Zevulun e-a Nafthali Kedeshah e-subiu berreglai dez alfei homem vataal com-ele Dvorah');
INSERT INTO verses VALUES (6612, 7, 4, 11, 'vechever o-keini nifrad mikain de-filhos-de [חֹבָ֖ב] cons- sogro Moisés e-ele-esticou אֲהֽוֹלוֹ até [*בצענים] que a [אֶת־קֶֽדֶשׁ]');
INSERT INTO verses VALUES (6613, 7, 4, 12, 'e-contaram [לְסִֽיסְרָ֑א] que subir [בָּרָ֥ק] filho-de [הַר־תָּבֽוֹר׃] monte-de');
INSERT INTO verses VALUES (6614, 7, 4, 13, 'e-ele-clamou Sisra-a a todo seu-exército nove novecentos carros ferro todo o-povo que com-ele de-o-vale as-nações a ribeiro-de Kishon-:');
INSERT INTO verses VALUES (6615, 7, 4, 14, 'E-disse Debora-a a Barak-o que porque o-dia o-dia dar yhwh yhwh a Sisra-a yhwh sair yhwh saiu diante-de-ti e-ele-descerrou Barak-o de-montanha-de Tabor e-ashéret alafim homem atrás-dele');
INSERT INTO verses VALUES (6616, 7, 4, 15, 'vayáham yhwh a Sisrá e-a todo a-arákeve e-a todo o-macháne de-cima-de espada diante-de Barak וַיֵּ֧רֶד Sisrá de-sobre a-m-carro-a e-fugiu em-pés-seus');
INSERT INTO verses VALUES (6617, 7, 4, 16, 'e-o-raio perseguir depois-de o-carro e-depois-de o-acampamento até haroshet as-nações e-caiu todo de-acampamento siserá não espada não permaneceu até um');
INSERT INTO verses VALUES (6618, 7, 4, 17, 'e-siserá fugiu em-seus-pés a tenda Yael esposa-de-a Hever que porque entre entre Jabim e-entre Chatzar e-entre casa Hever o-Qeni');
INSERT INTO verses VALUES (6619, 7, 4, 18, 'e-saiu-a Yael ao-encontro-de Siserá E-disse a-ele sura Adonai sura para-mim a tire-a e-removeu para-ela ha-ohelah ve-takasehu bas-mikha');
INSERT INTO verses VALUES (6620, 7, 4, 19, 'E-disse ele-a hashqini- agora que águas porque tsameiti ve-tifata a naoode hechalahv vatashqehu vtkassehu');
INSERT INTO verses VALUES (6621, 7, 4, 20, 'E-disse a ela ficou-em-pé entrada-de haohel e-será se homem yavo ushaelkech veamar hayeish- poh homem e-disseste não.');
INSERT INTO verses VALUES (6622, 7, 4, 21, 'e-tomou Yoal esposa-de amizade a prego a-tenda e-colocou a a-ele em-a-mão-seu e-entrou a-ele a-sorrateiramente e-ela-soprou a o-marrete em-o-raio-seu e-ela-caiu em-a-terra e-ele dormindo e-ele-vooou E-morreu');
INSERT INTO verses VALUES (6623, 7, 4, 22, 'e-eis em-raio perseguindo a סִֽיסְרָא֒ e-saiu יָעֵל֙ E-disse a-ele a-ele vai e-eu-te-verei a o homem que tu pedindo E-veio a ela e-eis Sisra caindo morreu e-o-estaca em-sua-lança');
INSERT INTO verses VALUES (6624, 7, 4, 23, 'e-ele-se-curvou Elohim no-dia aquele a Jabim rei-de assim diante-de filhos-de Israel');
INSERT INTO verses VALUES (6625, 7, 4, 24, 'e-ela-andou mão filhos-de Israel indo sobre sobre Jabim até assim até que e-cortaram a entenderá rei-de כְּנָֽעַן');
INSERT INTO chapters VALUES (216, 7, 5, 31);
INSERT INTO verses VALUES (6626, 7, 5, 1, 'e-ela-cantou Debora e-luz filho-de no-dia no-dia dizendo para-dizer');
INSERT INTO verses VALUES (6627, 7, 5, 2, 'em-o-romper rompimentos em-Israel com-a-vontade povo abençoem yhwh');
INSERT INTO verses VALUES (6628, 7, 5, 3, 'ouvi reis o-ouçam cavaleiros eu-sou para-יהוה eu cantarei azamerm a-yhwh Elohim-de Israel');
INSERT INTO verses VALUES (6629, 7, 5, 4, 'yhwh em-saída-teu de-seir em-passo-teu de-sade Edom terra tremeu também céus deram-se também nuvens deram-se águas');
INSERT INTO verses VALUES (6630, 7, 5, 5, 'os-montes deram-se de-diante-de yhwh este Sinai de-diante-de yhwh Elohim-de Israel');
INSERT INTO verses VALUES (6631, 7, 5, 6, 'nos-dias Shamgar filho-de Anat em-dias-de Yael cessaram caminhos e-andantes sendes andarão [עֲקַלְקַלּֽוֹת]');
INSERT INTO verses VALUES (6632, 7, 5, 7, '[חָדְל֧וּ] [פְרָז֛וֹן] em-Israel cessaram até [שַׁקַּ֙מְתִּי֙] Debora [שַׁקַּ֥מְתִּי] mãe em-Israel');
INSERT INTO verses VALUES (6633, 7, 5, 8, 'יִבְחַר֙ Elohim [חֲדָשִׁ֔ים] então pão-o portas-as escudo-o se será-visto-ele e-lança-a em-quarenta-os mil em-Israel');
INSERT INTO verses VALUES (6634, 7, 5, 9, 'coração-meu para-leis-dos-escritores Israel dos-oferecedores-os no-povo-o abençoem-vós yhwh');
INSERT INTO verses VALUES (6635, 7, 5, 10, 'cavaleiros-de jumentas brancas habitantes-de sobre Midian e-andantes-de sobre caminho sichu');
INSERT INTO verses VALUES (6636, 7, 5, 11, 'de-a-voz dividindo-se entre sugadores nome juntem-se justiças yhwh justiça sua-cidade-fortaleza em-Israel então desceram para-as-portas com yhwh');
INSERT INTO verses VALUES (6637, 7, 5, 12, '[עוּרִ֤י] acorde-se devorá acorde-se arrega-a fala-o- canta-o levantou relâmpago e-recolhe presa-teu filho-de Avinoam-verso-final');
INSERT INTO verses VALUES (6638, 7, 5, 13, 'então desce-o restante-o para-poderosos povo yhwh jerrad- a-mim nos-gigantes');
INSERT INTO verses VALUES (6639, 7, 5, 14, 'מִנִּי Efrayim sharsham ba-amalek acharecha binyamin ba-amamecha מִנִּי machir desceram machokkim u''mizbullan moshchim bashbet soper:');
INSERT INTO verses VALUES (6640, 7, 5, 15, 'vesaray byishshaskar com devorah viishshaskar assim barak em-o-vale enviou com-seus-pés para-partilhar Rúben gadolim de-leis- coração');
INSERT INTO verses VALUES (6641, 7, 5, 16, 'por-que voces-deitaste entre os-das-justiças para-ouvir shrikot os-de-adas para-partilhar Rúben grandes pesquisadores-de- coração');
INSERT INTO verses VALUES (6642, 7, 5, 17, 'Gilade em-lado-de o-Jordão habitará e-Dan por-que Yagur navios que habitou para-o-litoral mares e-sobre de-seus-portos morará');
INSERT INTO verses VALUES (6643, 7, 5, 18, 'Zevulun povo cheref nafsho para-morrer ve-naphtali sobre meromei sadeh');
INSERT INTO verses VALUES (6644, 7, 5, 19, 'vieram melachim nilchamu então nilcham reis-de Canaan beteanakh sobre águas-de Megido em vão não não lakahu');
INSERT INTO verses VALUES (6645, 7, 5, 20, 'de céus as-estrelas as-estrelas mimsilotam nilchamu com sisra');
INSERT INTO verses VALUES (6646, 7, 5, 21, 'ribeiro-de kishon grapam ribeiro-de qodumim vale-de [קִישׁ֑וֹן] te-darchi alma-minha o-oz:');
INSERT INTO verses VALUES (6647, 7, 5, 22, 'az ha-lmu iqvei- su-sus mi-daharot daharot abirav:');
INSERT INTO verses VALUES (6648, 7, 5, 23, 'orvru me-roz disse anjo yhwh ilumina-mi ameuço-te os-sentados-a que não entraram yhwh yhwh yhwh yhwh nos-gigantes');
INSERT INTO verses VALUES (6649, 7, 5, 24, 'serás-bendita de-presentes Iáel mulher-de amizade o-quenita de-oferendas na-tenda ser-abençoado-você');
INSERT INTO verses VALUES (6650, 7, 5, 25, 'águas ele-pediu leite deu-ela em-tremoço grandes ofereceu-ela gordura');
INSERT INTO verses VALUES (6651, 7, 5, 26, 'mão-seu para-o-marrete lança-a e-a-direita-seu para-moer moinhos e-ela-moia Siserá apagou cabeça-sua e-partiu-a-meia e-passou raca-to');
INSERT INTO verses VALUES (6652, 7, 5, 27, 'entre ragle-ha karah cair shakav entre ragle-ha karah naphal ba-asher karah nome cair shadud');
INSERT INTO verses VALUES (6653, 7, 5, 28, 'em-o a-janela brilhou e-ela-clamou mãe Sisera através-de a-anca madua'' adiamou-se seu-cavalo para-vir por-que partam-se passos-de de-sua-cavalo');
INSERT INTO verses VALUES (6654, 7, 5, 29, '[חַכְמ֥וֹת] [שָׂרוֹתֶ֖יהָ] [תַּעֲנֶ֑ינָּה] também ela tu-devolverás [לָֽהּ] a-ela');
INSERT INTO verses VALUES (6655, 7, 5, 30, 'não-é-que [יִמְצְא֜וּ] יְחַלְּק֣וּ [שָׁלָ֗ל] [רַ֤חַם] [רַחֲמָתַ֙יִם֙] para-o-cabeça homem despojo cores para-Sisera despojo cores tecido-entrelaçado cor tecidos-duplos para-os-cervicais despojo');
INSERT INTO verses VALUES (6656, 7, 5, 31, 'assim perderão todo yhwh yhwh e-os-seus-amados como-a-saída o-sol com-a-sua-valorosidade a-terra a-terra quarenta anos');
INSERT INTO chapters VALUES (217, 7, 6, 40);
INSERT INTO verses VALUES (6657, 7, 6, 1, 'e-fizeram filhos-de Israel o-mal yhwh yhwh yhwh yhwh por-mão-de מִדְיָן sete dois');
INSERT INTO verses VALUES (6658, 7, 6, 2, 'e-ele-se-encheu-de-coragem mão-de מִדְיָן de-diante-de Israel de-perante a-eles para-elas filhos-de Israel a das-lanterna que nas-montanhas e-a as-cavernas e-a os-abrigos');
INSERT INTO verses VALUES (6659, 7, 6, 3, 'e-foi se plantou Israel e-subiu Midian e-Amalec e-filhos-de ao-norte vealou sobre-ele');
INSERT INTO verses VALUES (6660, 7, 6, 4, 'e-acamparam em-eles e-destruiram a a-terra a-terra até vem-de-vós- Gaza e-não guardarão-os-eles alimento-da-carne em-Israel e-cordeiro e-touro e-ásno-:');
INSERT INTO verses VALUES (6661, 7, 6, 5, 'que eles e-de-seus-animais subirão-eles e-lugares-de-acampamento-de-eles para- arvèh para-o-muitos e-para-eles e-para-os-camelo-de-eles não-há de-número e-vieram em-a-terra na-terra');
INSERT INTO verses VALUES (6662, 7, 6, 6, 'e-ele-se-dividiu Israel muito de-diante-de Midiã e-eles-gritaram filhos-de Israel a yhwh');
INSERT INTO verses VALUES (6663, 7, 6, 7, 'e-houve porque gritaram filhos-de sobre a yhwh sobre de-louvores de-Madian');
INSERT INTO verses VALUES (6664, 7, 6, 8, 'e-ele-mandou yhwh homem profeta a filhos-de E-disse a-eles para-eles yhwh disse יהוה Elohim-de eu eu e-eu-ergui vos do-Egito e-eu-saí vos de-casa-de servos');
INSERT INTO verses VALUES (6665, 7, 6, 9, 'e-eu-protegi vos de-mão-de Egito e-de-mão-de todo opressores-vos e-eu-expulsei elas de-diante-vosso a-vós para-vocês a terr-os');
INSERT INTO verses VALUES (6666, 7, 6, 10, 'e-eu-disse a-vós eu yhwh elohim-vos não temereis a Elohim-de o-amorreu que vós sentando-se em-a-terra-deles e-não ouviram na-voz-meu');
INSERT INTO verses VALUES (6667, 7, 6, 11, 'E-veio anjo yhwh e-habitou debaixo a-elohim-aquele que em-poeira que para-ioash pai-de o-ajudante e-Gideom filho-seu [חֹבֵ֤ט] trigo-s -no-tanque para-vencer de-diante-de Midian-');
INSERT INTO verses VALUES (6668, 7, 6, 12, 'E-viu a-ele yhwh yhwh E-disse a-ele yhwh heroi- da-habilidade');
INSERT INTO verses VALUES (6669, 7, 6, 13, 'E-disse a-ele Gideom- por-mim Adonai e-ha yhwh conosco-s e-porque encontrou-nos todo esta e-onde todo maravilhas-seus que dizendo para-nos pais-nossos dizendo yhwh e-agora [נְטָשָׁ֣נוּ] yhwh e-agora [בְּכַף־מִדְיָֽן] yhwh com-a-palma- de-diadã');
INSERT INTO verses VALUES (6670, 7, 6, 14, 'e-voltou-se a-ele yhwh E-disse vai com-força-tua este e-salvarei-te a Israel da-palma Midiã não-é enviaste-te');
INSERT INTO verses VALUES (6671, 7, 6, 15, 'E-disse a-ele por-mim Adonai em-ela salvarei a eis eis milhares-de o-pobre em-manesse e-eu o-menor em-casa-de pai-meu');
INSERT INTO verses VALUES (6672, 7, 6, 16, 'E-disse a-ele yhwh que serei contigo e-golpeaste a מִדְיָן um um');
INSERT INTO verses VALUES (6673, 7, 6, 17, 'E-disse a-ele se por-favor encontrei graça em-olhos-teus a-mim para-mim sinal que-tu que-está-falando comigo');
INSERT INTO verses VALUES (6674, 7, 6, 18, 'a por-favor andarás de-este até vem-me para-ti e-saia-eu a minha-oferta eu diante-de-ti até eu eu-estarei até te-voltando-te');
INSERT INTO verses VALUES (6675, 7, 6, 19, 'e-Gideão veio E-fez gadi- cabras e-eifa- qemakh de-massas o-batido nome em-o-sal e-o-ma-rak nome a-ele e-ele-saiu para-ele a em-baixo-de o-ela e-ele-se-aproximou');
INSERT INTO verses VALUES (6676, 7, 6, 20, 'E-disse a-ele anjo os-Elohim toma a o-batido e-a os-ma-tzot e-o-nach a o-sela o-este e-a o-molho derramado E-fez assim');
INSERT INTO verses VALUES (6677, 7, 6, 21, 'e-enviou anjo yhwh a extremidade o-depósito que em-mão-de-ele e-toque em-a-carne e-no-pães e-subiu a-chama e-comeste o-tsur e-ko-lal a yhwh andar ha-matzot e-mensageiro yhwh andou mi-einav');
INSERT INTO verses VALUES (6678, 7, 6, 22, 'E-viu gid''on porque yhwh ele ele E-disse gid''on ahah Adonai yhwh porque sobre assim yhwh anjo yhwh face a face');
INSERT INTO verses VALUES (6679, 7, 6, 23, 'E-disse a-ele yhwh shalom a-ti a não morrerás morrerás');
INSERT INTO verses VALUES (6680, 7, 6, 24, 'E-edificou nome gid''on um-altar a-yhwh e ele chamou yhwh yhwh até o-dia o-dia esta odenu em-poeira pai-de o-ajudante');
INSERT INTO verses VALUES (6681, 7, 6, 25, 'e-houve na-noite aquele E-disse a-ele yhwh toma a bezerro- o-touro que para-teu-pai e-bezerro o-segundo sete dois e-destruirás a altar-de o-mestre que para-teu-pai e-a a-áshera que sobre-ele tornar-vós');
INSERT INTO verses VALUES (6682, 7, 6, 26, 'e-construirás em-o-átrio a-yhwh Elohim-teus sobre cabeça o-refúgio este na-batalha e-tomarás a o-touro o-segundo e-elevarás holocausto em-a-árvore a-asereia que tornem-se-cravos-verso-final');
INSERT INTO verses VALUES (6683, 7, 6, 27, 'E-tomou gideão dez homens de-seus-servos E-fez como palavra a-ele yhwh e-houve como-que temer a seu-pai seu-pai e-a homens-de a-cidade de-fazer noite E-fez noite');
INSERT INTO verses VALUES (6684, 7, 6, 28, 'e-eles-se-levantaram homens-de a-cidade de-manhã e-eis foi-negado altar-de o-Baal e-a-asereia que sobre-ele foi-cortada e-את o-touro o-segundo elevação sobre o-altar');
INSERT INTO verses VALUES (6685, 7, 6, 29, 'e-disseram homem a quem quem fez a-coisa esta e-eles-procuraram e-ele-pediu e-disseram Gideão filho-de Joás fez a-palavra a-esta');
INSERT INTO verses VALUES (6686, 7, 6, 30, 'e-disseram homens-de a-cidade a Joás tire a que E-morreu porque derrubou a altar-de o-Baal e-que cortou a-ashehrah que sobre-ele');
INSERT INTO verses VALUES (6687, 7, 6, 31, 'E-disse ioash a-todo que amadu sobre-ele o-ateim teribun la-bal se vós toshiyun com-ele que a-ele para-ele será-morto até ele se a-ele que yarev a-ele porque natatz a mizbho');
INSERT INTO verses VALUES (6688, 7, 6, 32, 'e ele chamou a-ele em-o-dia- dizendo יְרֻבַּ֣עַל dizendo disputou que o-Baal porque lançou a o-sacrifício-seu');
INSERT INTO verses VALUES (6689, 7, 6, 33, 'e-todo Midian e-Amalec e-filhos-de no-oriental reuniram-se juntos e-atravessaram e-acamparam na-vale Jeová-sara');
INSERT INTO verses VALUES (6690, 7, 6, 34, 'e-Espírito-de yhwh vestiu-a a Gedeão e-blastou em-o chifre e-clamou Abiezéu atrás-dele');
INSERT INTO verses VALUES (6691, 7, 6, 35, 'e-anjos enviou em-todo Manassés e-clamou também ele atrás-dele e-anjos enviou em-Aser e-o-zebulon e-no-fetali e-ele-levantaram-se para-encontro-deles');
INSERT INTO verses VALUES (6692, 7, 6, 36, 'E-disse gideon a o-Elohim se haja-tu salvador na-mao-de-me a Israel como-que dibartā׃');
INSERT INTO verses VALUES (6693, 7, 6, 37, 'eis eu mostrando a gizat o-lã-coração em-o-moinho mãe será for sobre a-separação para-a-sua e-sobre todo a-terra o-calor e-eu-conheci porque ele-salvará em-a-minha-mão a Israel como-que dibartā׃');
INSERT INTO verses VALUES (6694, 7, 6, 38, 'e-foi assim e-ele-levantou-se de-amanhã e-ele-semeou a a-gizza e-ele-recolheu orvalho de a-gizza encher-de o-sefel águas');
INSERT INTO verses VALUES (6695, 7, 6, 39, 'E-disse gideon a Elohim a se-irar teu-apo em-mim e-eu-falarei porém a-vez tentarei por-favor- somente a-vez em-a-gozah seja- por-favor secas a a-gozah para-a-sua-conta e-sobre todo a-terra ele-será- orvalho:');
INSERT INTO verses VALUES (6696, 7, 6, 40, 'E-fez Elohim assim na-noite aquele e-foi secas a a-gozah ser e-sobre todo a-terra foi orvalho:');
INSERT INTO chapters VALUES (218, 7, 7, 25);
INSERT INTO verses VALUES (6697, 7, 7, 1, 'e-ele-se-levantou Yerubbaal ele Gidown e-todo o-povo que com-ele e-acamparam sobre olho Charod u-machaneh Midiã ha-yah- a-ele mitzafon migbaat hamooreh ba-emek');
INSERT INTO verses VALUES (6698, 7, 7, 2, 'E-disse yhwh a Gidown muito o-povo que com-tu de-me a מִדְיָן em-mão-deles para-que-não dizendo sobre-mim Israel a-mim minha-mão salva para-mim');
INSERT INTO verses VALUES (6699, 7, 7, 3, 'e-agora chamou por-favor em-orelhas-de o-povo dizendo quem teme e-treme habitou e-espere de-montanha-de o-gileade e-estabeleceu-se de o povo vinte e-dois mil e-a-década dois-mil permaneceram');
INSERT INTO verses VALUES (6700, 7, 7, 4, 'E-disse yhwh a Gideão mais o-povo muito fazer-descer elas a a-ti e-reunirei-o a-ti nome e-será que disse a-você este irei ele ele irei e-tudo e-todo que disse a-ti este ele não contigo ele não irá');
INSERT INTO verses VALUES (6701, 7, 7, 5, 'e-desceu a o-povo a E-disse yhwh yhwh a Gedeão todo que yaloq bilshono de as-águas como-que yalok e-tudo tatsig ele levad e-todo que yikra'' sobre birchav lishtho');
INSERT INTO verses VALUES (6702, 7, 7, 6, 'e-houve mispar os-malakim em-a-sua-mão a a-seu-boca três centenas e-tudo e-todo Jetro o-povo agacharam-se sobre com-a-sua-joelhos para-beber águas');
INSERT INTO verses VALUES (6703, 7, 7, 7, 'E-disse yhwh a Gideão em-três centenas o-homem os-malakim salvador vos e-darei a מִדְיָן em-mão-tua e-todo o-povo eiremos homem para-lugar-dele');
INSERT INTO verses VALUES (6704, 7, 7, 8, 'e-eles-tomaram a presa o-povo em-a-mão-deles e-a de-trombetas-deles e-a todo homem Israel enviou homem para-as-tendas-dele e-com-três- centenas o homem ser a-ele debaixo-de foi para-ele de-baixo no-vale');
INSERT INTO verses VALUES (6705, 7, 7, 9, 'e-aconteceu na-noite aquele E-disse a-ele yhwh levantou desce na-campanha que eu-o-deti em-mão-teu');
INSERT INTO verses VALUES (6706, 7, 7, 10, 'e-se tu tu para-descer tu tu e-foi-lancada jovem-teu a o-acampamento');
INSERT INTO verses VALUES (6707, 7, 7, 11, 'e-ouviste que dirão-eles e-depois sejam-fortes mãos-teu e-descereste no-lager ele ele e-espalhará jovem-de ele a extremidade os-armados que no-lager');
INSERT INTO verses VALUES (6708, 7, 7, 12, 'e-Midian e-Amaleque e-todo filhos-de em-o-orient-e caindo-s na-val-e como-gafanhoto em-abundância e-para-os-sua-cam-eis não-há de-número o-mar sobre-o- beira-de o-mar para-multidão');
INSERT INTO verses VALUES (6709, 7, 7, 13, 'E-veio Gideão וְהִ֨נֵּה־ homem מְסַפֵּ֥ר ao seu vizinho E-disse eis הִנֵּ֧ה sonho חָלַ֗מְתִּי e-eis לֶ֤חֶם pão מִתְהַפֵּךְ em-acampamento-de Midian E-veio até הָ֠אֹהֶל e-ele-o-feriu e-ele-caiu e-ele-o-virou para-a-alta e-caiu o-tenda');
INSERT INTO verses VALUES (6710, 7, 7, 14, 'e-ele-respondeu seu-amigo E-disse não-há esta sem se espada Gideão filho-de Yoash dar Israel deu הָֽאֱלֹהִים em-mão-de-ele a מִדְיָן e-a todo o-acampamento');
INSERT INTO verses VALUES (6711, 7, 7, 15, 'e-houve quando-ouviram Gideom a em-o-número o-honho e-a seu-pedaço e-ele-se-inclinou e-ele-voltou E-disse acampamento-de Israel yhwh levantem-se porque deu yhwh com-a-sua-mão a acampamento-de de-Madian');
INSERT INTO verses VALUES (6712, 7, 7, 16, 'e-dividiu a três- centenas o homem E-colocou cabeças-de E-deu chifres-de por-mão-de todos-os no-meio-de vazios-os e-pedras-de-luz em-meio-de os-vess-eis');
INSERT INTO verses VALUES (6713, 7, 7, 17, 'E-disse a-eles de-mim vocês-verão e-assim fazeis-vós e-eis eu veio em-extremidade o-acampamento e-acontecerá como-que eu-farei assim vós-fareis');
INSERT INTO verses VALUES (6714, 7, 7, 18, 'e-blastarei em-o chifre eu e-todo que comigo e-vocareis em-os-trumpetes também vocês ao-redor-de todo o-acampamento e-disseis para-יהוה e-a-gideão');
INSERT INTO verses VALUES (6715, 7, 7, 19, 'E-veio gideão e-de-cem- homem que com-ele em-extremidade o-acampamento cabeça a-noite a-mediada somente e-levantem e-ele-levantaram a os-guarda-dores e-eles-tocaram com-a-trombeta-s e-nos-destruamos as-jarras que com-a-mão-deles');
INSERT INTO verses VALUES (6716, 7, 7, 20, 'e-ele-tocaram três-de os-chefes [בַּשּֽׁוֹפָרוֹת֮] e-partiram os-recipientes [וַיַּחֲזִ֤יקוּ] por-mão-de- [בַּלַּפִּדִ֔ים] [וּבְיַ֨ד־יְמִינָ֔ם] [הַשּׁוֹפָר֖וֹת] [לִתְק֑וֹעַ] [וַֽיִּקְרְא֔וּ] espada cherev a-yhwh e-a-gideão');
INSERT INTO verses VALUES (6717, 7, 7, 21, 'e-pararam homem em-lugar-dele ao-redor para-o-lager [וַיָּ֧רָץ] todo a-câmera e-eles-alegraram-se');
INSERT INTO verses VALUES (6718, 7, 7, 22, 'e tocou-se três- centenas-de as trombetas yhwh yhwh espada espada homem em seu redor e-em-todo o-acampamento e despediu-se a acampada até até o acampamento centro até borda-de luto cortejo sobre Tabbat:');
INSERT INTO verses VALUES (6719, 7, 7, 23, 'E gritou אִישׁ- Israel de Naftili e-de que e-de todo Manassés e-perseguiram atrás-de de-Madian');
INSERT INTO verses VALUES (6720, 7, 7, 24, 'e anjos enviou Gideão em-todo a montanha dizendo dizendo descendam para a presença de Midiã a-eles para-eles até as-águas até casa Bara e-a o Jordão e gritou todo até אֶפְרַיִם e-capturaram a as-águas até casa ברא e-a o-Jordão');
INSERT INTO verses VALUES (6721, 7, 7, 25, '[וַֽיִּלְכְּד֡וּ] dois príncipes-de [אֶת־עֹרֵ֣ב] a tarde e-a [בְּצוּר־עוֹרֵב֙] [וְאֶת־זְאֵב֙] a [בְיֶֽקֶב־זְאֵ֔ב] em-rocha- [אֶל־מִדְיָ֑ן] e-a lobo-menor hargu [אֶל־גִּדְע֔וֹן] [מֵעֵ֖בֶר] e-perseguiram a Midiã tarde a gid''on מעבר');
INSERT INTO chapters VALUES (219, 7, 8, 35);
INSERT INTO verses VALUES (6722, 7, 8, 1, 'e-disseram a-ele homem Efrayim que a-coisa este fizeste para-não para-não [לָ֔נוּ] que porque andaste para-lutar [וַיְרִיב֥וּן] [אִתּ֖וֹ] com-ele');
INSERT INTO verses VALUES (6723, 7, 8, 2, 'E-disse a-eles que fiz agora kha-chem bom bom o-le-lo-t Efraim mi-btsir a-vi-ez-er:');
INSERT INTO verses VALUES (6724, 7, 8, 3, 'b-yed-khem dar Elohim a príncipes-de Midiã a tarde e-a ze-ev e-que yak-hol-ti fazer kha-chem então רָפְתָ֤ה רוּחָם֙ de-sobre-ele בְּדַבְּר֖וֹ a-palavra a-esta');
INSERT INTO verses VALUES (6725, 7, 8, 4, 'E-veio [גִדְע֖וֹן] [הַיַּרְדֵּ֑נָה] passando ele e-três- centenas o-homem que com-ele [וְרֹדְפִֽים]');
INSERT INTO verses VALUES (6726, 7, 8, 5, 'E-disse לְאַנְשֵׁ֣י סֻכּ֔וֹת תְּנוּ־ por-favor pão Belém ao-povo que com os pés eles exaustos eles e-eu perseguidor depois-de sacrifício e sombra reis-de de-Madian');
INSERT INTO verses VALUES (6727, 7, 8, 6, 'E-disse príncipes-de carruagens por que oferta e sombra agora em-mão-tua porque deu para o exército pão');
INSERT INTO verses VALUES (6728, 7, 8, 7, 'E-disse gid''on portanto [בְּתֵ֧ת] yhwh a sacrifício e-a [וְדַשְׁתִּי֙] b''yadi [אֶת־קוֹצֵ֥י] a [וְאֶת־הַֽבַּרְקֳנִֽים] a הַמִּדְבָּ֖ר e-a');
INSERT INTO verses VALUES (6729, 7, 8, 8, 'e-subiu de-lá [פְּנוּאֵ֔ל] e-falou a-eles assim [וַיַּעֲנ֤וּ] ele homens-de [פְנוּאֵ֔ל] como-que [עָנ֖וּ] homens-de sukot');
INSERT INTO verses VALUES (6730, 7, 8, 9, 'E-disse também para-os-homens-de dizendo dizendo [בְשָׁל֔וֹם] [אֶתֹּ֖ץ] [אֶת־הַמִּגְדָּ֥ל] a a-esta');
INSERT INTO verses VALUES (6731, 7, 8, 10, 'וזבח וצלמן בקרקור e-campeias com-eles quinto dez mil todo dos-que-restaram de-toda acampamento-de filhos-de antes e-os-caídos cem e-vinte mil homem desloca espada');
INSERT INTO verses VALUES (6732, 7, 8, 11, 'e-subiu gid''on o-caminho-de os-habitantes em-carraspeiros ao-oriente para-escaramuça e-eleva-se e-golpeou a o-acampamento ser foi seguro:');
INSERT INTO verses VALUES (6733, 7, 8, 12, 'e se levantaram o-sacrifício e de-a e-ele-perseguiu apos-eles e se prendeu a dois reis-de Midiã a oferta e-a e de-a e-todo muito e proclamou:');
INSERT INTO verses VALUES (6734, 7, 8, 13, 'e se voltou Gideão filho-de Joás de a-guerra de cima e desmoronou:');
INSERT INTO verses VALUES (6735, 7, 8, 14, 'e-o prendeu- jovem -dos homens Sucote e-o perguntou-lhe- a-ele a-ele a príncipes-de Succoth e-a suas velhas setenta e-sete homem');
INSERT INTO verses VALUES (6736, 7, 8, 15, 'E-veio a homens-de E-disse eis hein sacrifício-de e-tremeluzentes que honorastes dizendo dizendo que-feriste sacrifício-de וְצַלְמֻנּ֤ע agora que porque deu לַאֲנָשֶׁ֥יךָ הַיְּעֵפִ֖ים pão');
INSERT INTO verses VALUES (6737, 7, 8, 16, 'E-tomou a anciãos-de a-cidade e-a [וְאֶת־הַֽבַּרְקֳנִ֑ים] הַמִּדְבָּ֖ר e-a [OBJ] [אַנְשֵׁ֥י] neles a homens-de sukot');
INSERT INTO verses VALUES (6738, 7, 8, 17, 'e-a torre-de [נָתָ֑ץ] natazs e matou a homens-de a-cidade');
INSERT INTO verses VALUES (6739, 7, 8, 18, 'E-disse a oferta e-a Zalmona אֵיפֹה֙ os-homens que vocês mataram em Betabor e disseram um como eles um segundo a descrição filhos-de o rei');
INSERT INTO verses VALUES (6740, 7, 8, 19, 'E-disse meus irmãos filhos-de eles eles vive yhwh eis que não a-eles não hרגתי a-vós');
INSERT INTO verses VALUES (6741, 7, 8, 20, 'E-disse [לְיֶ֣תֶר] [בְּכוֹר֔וֹ] levantou [הֲרֹ֣ג] eles e-não [הַנַּ֤עַר] [חַרְבּוֹ֙] que temer que porque ainda-aquele menino');
INSERT INTO verses VALUES (6742, 7, 8, 21, 'E-disse sacrifício-de [וְצַלְמֻנָּ֗ע] levantou tu e-ataca que porque [גְּבוּרָת֑וֹ] giburato E-levantou gid''on וַֽיַּהֲרֹג֙ a E-tomou e-a [אֲשֶׁ֖ר] E-tomou a que');
INSERT INTO verses VALUES (6743, 7, 8, 22, 'e-disseram אִישׁ- Israel a gid''on [גַּם־בִּנְךָ֖] também também que também filho-teu também filho-de be-nos-teu porque de-mão-de de-Madian');
INSERT INTO verses VALUES (6744, 7, 8, 23, 'E-disse para-eles gid''on não [אֲנִי֙] eu em-vós e-não reinará yhwh em-vocês yhwh reinará em-vos:');
INSERT INTO verses VALUES (6745, 7, 8, 24, 'E-disse a-para-eles gid''on [אֶשְׁאֲלָ֤ה] de-vós [שְׁאֵלָ֔ה] וּתְנוּ־ לִ֕י homem anel [כִּֽי־נִזְמֵ֤י] ouro a-eles que a-eles eles eles');
INSERT INTO verses VALUES (6746, 7, 8, 25, 'e-disseram נָתֹן deu וַיִּפְרְשׂוּ֙ a הַשֻּׂמְלָה וַיַּשְׁלִ֣יכוּ ali homem nezem shelalo:');
INSERT INTO verses VALUES (6747, 7, 8, 26, 'e-houve mishqal nizimei o-ouro que shala: mil e-sete- ouro ouro para-fora de ha-sharonim ve-hanetifot u-bigdei ha-argaman she''al reis-de Midian e-somente de as-mamães que pelos deles-ovinos');
INSERT INTO verses VALUES (6748, 7, 8, 27, 'E-fez ele Gideão para-a-acerca e-exibiu ele em-suas-cidades em-poeira e se contaminaram todo Israel atrás-dele e-houve E-foi a Gideão e em sua casa para-laço');
INSERT INTO verses VALUES (6749, 7, 8, 28, 'e se humilharam Midiã diante-de filhos-de Israel e-não e se curvaram para levar cabeça-deles e-descansou a-terra quarenta ano nos dias de Gideão:');
INSERT INTO verses VALUES (6750, 7, 8, 29, 'E-andou Jirel filho-de Joás e-habitou bebeto:');
INSERT INTO verses VALUES (6751, 7, 8, 30, 'e a Gideão foram setenta filhos יוצאים ירךיו porque mulheres רבות a-ele a-ele');
INSERT INTO verses VALUES (6752, 7, 8, 31, '[וּפִֽילַגְשׁוֹ֙] que בִּשְׁכֶם deu-a-parida para-ele filho ela filho e-colocou a nome-de-ele Avimélek');
INSERT INTO verses VALUES (6753, 7, 8, 32, 'E-morreu Gideão filho-de Yoash no verão bom-a [בְּקֶ֙בֶר֙] בְּקֶ֙בֶר֙ seu-pai pai-dele [אֲבִ֥י] pai-de');
INSERT INTO verses VALUES (6754, 7, 8, 33, 'e-houve como-que morreu gid''on e voltaram filhos-de Israel e se deitaram depois-de os senhores e puseram a-eles Baal berith para-Elohim');
INSERT INTO verses VALUES (6755, 7, 8, 34, 'e-não e se lembraram filhos-de Israel a yhwh Elohim-deles o que salva eles de-mão-de todo eles misaviv');
INSERT INTO verses VALUES (6756, 7, 8, 35, 'e-não fizeram bondade com casa Jérubal Gedeão conforme-toda a-boa que fez com Israel');
INSERT INTO chapters VALUES (220, 7, 9, 57);
INSERT INTO verses VALUES (6757, 7, 9, 1, 'E-andou Avimeleque filho-de Jérubal Siquém sua-mãe irmãos mãe-dele e-falou a-eles sua-mãe dizendo família casa-de pai-de sua-mãe para-dizer');
INSERT INTO verses VALUES (6758, 7, 9, 2, 'disseram- por-favor em-o-ouvido todo aos chefes a-vós que bom vós que governa sobre vós setenta homem todo filhos-de Jrubaal um governo em-vós homem um e recordareis porque e-no-sro-kem aní:');
INSERT INTO verses VALUES (6759, 7, 9, 3, 'וַיְדַבְּר֨וּ aché- immo sobre-ele ba-aznei todo ba''alé Siquem a todo as-palavras estas vayyet que depois-de Abimélek ele ele achinu ela');
INSERT INTO verses VALUES (6760, 7, 9, 4, 'vayitnu- a-ele setenta prata mibeit Ba''al aliança e deitou-se neles avimalek homens vazios e ocultos e-foram atrás-dele');
INSERT INTO verses VALUES (6761, 7, 9, 5, 'E-veio casa-de seu-pai em poeira e matou a seus irmãos filhos-de Jearobael setenta homem sobre pedra o-pequeno que Yoțam filho-de Yeruabal não porque Nechva:');
INSERT INTO verses VALUES (6762, 7, 9, 6, 'Va''yasafo todo Ba''alei Shekem e-todo casa Milu'' Va''yalku Va''ymlichu a Avimelekh L''melekh com אלון משׁבים que בישכום:');
INSERT INTO verses VALUES (6763, 7, 9, 7, 'disseram [לְיוֹתָ֗ם] E-andou e-yaa-amod na-cabeça monte-de os-garfos e-levantou E-chamou E-disse a-eles para-ela-os ouvi a-mim aos chefes Siquem E-ouviu El Elohim');
INSERT INTO verses VALUES (6764, 7, 9, 8, 'halokh andaram [הָעֵצִ֔ים] [לִמְשֹׁ֥חַ] sobre-eles rei e-disseram [לַזַּ֖יִת] sobre-nós');
INSERT INTO verses VALUES (6765, 7, 9, 9, 'E-disse a-eles [הַזַּ֔יִת] [הֶחֳדַ֙לְתִּי֙] a [אֲשֶׁר־בִּ֛י] que em-mim [וַאֲנָשִׁ֑ים] Elohim [לָנ֖וּעַ] [עַל־הָעֵצִֽים] sobre os-árvores:');
INSERT INTO verses VALUES (6766, 7, 9, 10, 'e-disseram as madeiras [לַתְּאֵנָ֑ה] [לְכִי־אַ֖תְּ] אתָ [עָלֵֽינוּ] sobre-nós');
INSERT INTO verses VALUES (6767, 7, 9, 11, 'E-disse a-eles a-téená he-chódeltí a mátqiy e-a túnabáti ha-tóvá vé-halakhtí lanuá sobre os-árvores:');
INSERT INTO verses VALUES (6768, 7, 9, 12, 'e-disseram as madeiras lagáfên lécí- אַ֖תְּ sobre-nós');
INSERT INTO verses VALUES (6769, 7, 9, 13, 'E-disse a-eles hagáfên הֶחֳדַ֙לְתִּי֙ a תִּ֣ירוֹשִׁ֔י o-que-alegra Elohim וַאֲנָשִׁ֑ים וְהָ֣לַכְתִּ֔י לָנ֖וּעַ sobre os-árvores:');
INSERT INTO verses VALUES (6770, 7, 9, 14, 'e-disseram todo as madeiras a tu vai tu rei-de sobre-nós');
INSERT INTO verses VALUES (6771, 7, 9, 15, 'E-disse הָאָטָד֮ a הָעֵצִים֒ mãe בֶּאֱמֶ֣ת אַתֶּם֩ מֹשְׁחִ֨ים meu para-o-rei sobre-vós entrem cobrirei no-meu e-se não sairá fogo de o-atoad e-comerá a carvalhos do-Libanon');
INSERT INTO verses VALUES (6772, 7, 9, 16, 'e-agora se em-verdade e-perfeitos que-fizessem e vós governastes a Avimelekh e-se boa ''SITMW com יְרֻבַּ֣עַל a-ele casa-dele e-se como medida mãos-dele vós fizestes a-ele');
INSERT INTO verses VALUES (6773, 7, 9, 17, 'que e lutastes pai-meu sobre-vós e lançou a a sua alma em-frente e-çel vos de-mão-de de-Madian');
INSERT INTO verses VALUES (6774, 7, 9, 18, 'e vós levantastes-vos sobre casa o-dia o-dia e matastes a os-filhos-dele setenta homem sobre pedra um e governastes a que filho-de ele sobre בעלים Siquem porque אחיםכם ela');
INSERT INTO verses VALUES (6775, 7, 9, 19, 'e-se [וּבְתָמִ֧ים] [עֲשִׂיתֶ֛ם] fizestes com o-dia e-com- casa-dele o-dia esta [גַּם־ה֖וּא] [בָּכֶֽם] também ele em-vos:');
INSERT INTO verses VALUES (6776, 7, 9, 20, 'e-se אין יצאה fogo de-Avimelque e-comerá a baalei Shimshon e-a casa de-luz e-sairá Fogo dos-dono(s) Shimshon e-de-casa de-luz e-comerá a Avimélek');
INSERT INTO verses VALUES (6777, 7, 9, 21, 'e-fugiu Yoța'' Vayibrach E-andou Be''era'' e-sentou nome de-diante-de Avímelekh irmão-dele');
INSERT INTO verses VALUES (6778, 7, 9, 22, 'Vayasa'' Avímelekh sobre Israel três dois');
INSERT INTO verses VALUES (6779, 7, 9, 23, 'e-estendeu Elohim espírito maldade entre Abimélek e-entre Ba''ale Šekem Vayibgedu Ba''ale- שֹׁכְמָה בַּאֲבִימֶלֶךְ׃');
INSERT INTO verses VALUES (6780, 7, 9, 24, '[לָב֕וֹא] [חֲמַ֖ס] setenta filhos-de [וְדָמָ֗ם] [לָשׂ֞וּם] para sobre [אֲשֶׁ֣ר] [הָרַ֣ג] que hārag a-eles e-sobre aos chefes Siquem que [אֶת־אֶחָֽיו] a mãos-dele a אֶחָֽיו׃');
INSERT INTO verses VALUES (6781, 7, 9, 25, 'e colocaram a-ele [בַעֲלֵ֨י] [שְׁכֶ֜ם] [מְאָרְבִ֗ים] sobre cabeças-de as montanhas [וַיִּגְזְל֗וּ] a todo que passará sobre-eles בַּדָּ֑רֶךְ e-ele-foi-dito');
INSERT INTO verses VALUES (6782, 7, 9, 26, 'E-veio [גַּ֤עַל] filho-de servo e-irmãos-de-o e passaram-se [וַיִּבְטְחוּ־ב֖וֹ] [בַּעֲלֵ֥י] em-ele baalei shchem');
INSERT INTO verses VALUES (6783, 7, 9, 27, 'e-saíram o-de-a-terra [וַֽיִּבְצְר֤וּ] a [וַֽיִּדְרְכ֔וּ] [וַֽיַּעֲשׂ֖וּ] e-fizeram [וַיָּבֹ֙אוּ֙] e-vieram casa [וַיֹּֽאכְלוּ֙] e-eles-comeram e-eles-beberam [אֶת־אֲבִימֶֽלֶךְ] a Avimélek');
INSERT INTO verses VALUES (6784, 7, 9, 28, 'E-disse [׀] filho-de servo quem [וּמִֽי־שְׁכֶם֙] que shikem porque [בֶן־יְרֻבַּ֖עַל] não filho-de [עִבְד֗וּ] [אֶת־אַנְשֵׁ֤י] [חֲמוֹר֙] [אֲבִ֣י] a homens-de jumento pai-de Siquem e-por-que nós-verso');
INSERT INTO verses VALUES (6785, 7, 9, 29, 'e-quem dará a o-povo o-este por-mi e-eu-guardarei E-disse Avimélek E-disse [צְבָאֲךָ֖] multiplicai');
INSERT INTO verses VALUES (6786, 7, 9, 30, 'E-ouviu Zebul príncipe-de a-cidade a palavras-de Gaal filho-de servo a-ele Afô');
INSERT INTO verses VALUES (6787, 7, 9, 31, 'e-ele-mandou anjos a Avimelekh dizendo eis Hinnêh Ga''al filho-de servo ve-echav Ba''îm Šêchemâ e-eis-eles Tsārîm a a-cidade sobre-te');
INSERT INTO verses VALUES (6788, 7, 9, 32, 'e-agora levantou noite tu ve-ha''âm que contigo ve-Êrôb no-campo');
INSERT INTO verses VALUES (6789, 7, 9, 33, 'e-era pela-manhã kîzrōach o-sol tâšakkîm u-pāštattâ sobre a-cidade e-eis- ele e o povo que com-ele para-ele para-ti e-farás a-ele conforme encontrou yadcha');
INSERT INTO verses VALUES (6790, 7, 9, 34, 'E-levantou Avimeleque e-todo o-povo noite com-ele noite quatro sobre Siquem quatro cabeças');
INSERT INTO verses VALUES (6791, 7, 9, 35, 'e-saiu Gaal filho-de servo e pôs-se em posição de entrada-de portão a-cidade E-levantou Avimeleque e-o-povo que com-ele de guarda');
INSERT INTO verses VALUES (6792, 7, 9, 36, 'e-viu- Gaal E-disse o-povo E-disse a Zebul eis-que- E-disse a-ele dos principais as montanhas E-disse a-ele tu a sombra as montanhas tu viu como homens:');
INSERT INTO verses VALUES (6793, 7, 9, 37, 'e-continuou ainda o pasto para-falar E-disse eis-que- povo os que desce de-com a-terra a-terra e a cabeça de um veio do caminho olival de repouso:');
INSERT INTO verses VALUES (6794, 7, 9, 38, 'E-disse a-ele [זְבֻ֗ל] [אַיֵּ֨ה] [אֵפ֥וֹא] [פִ֙יךָ֙] que תּוֹאַמָר quem Avimelech que [נַעַבְדֶ֑נּוּ] não-é-que este o-povo que [מָאַ֣סְתָּה] nele sai- agora agora [בּֽוֹ׃] em-ele');
INSERT INTO verses VALUES (6795, 7, 9, 39, '[וַיֵּ֣צֵא] [גַ֔עַל] diante-de aos chefes שַׂכְמֵ֑ן וַיִּלָּחֶם [בַּאֲבִימֶֽלֶךְ]');
INSERT INTO verses VALUES (6796, 7, 9, 40, '[וַיִּרְדְּפֵ֣הוּ] Abimélek e-estendeu-se de-face-dele [וַֽיִּפְּל֛וּ] que-são-desecrados muitos até porta a-por-ta');
INSERT INTO verses VALUES (6797, 7, 9, 41, 'e-habitou Avimelekh BAARUMA e expulsou Zebul a Gaál e-a seus-irmãos mishbet em Berséfim:');
INSERT INTO verses VALUES (6798, 7, 9, 42, 'e-houve de-amanhã e-ele-saiu o-povo o-campo e-contaram ao Abimeleque:');
INSERT INTO verses VALUES (6799, 7, 9, 43, 'E-tomou a o-povo e partiu-o em três cabeças e Arão E-viu E-viu e-eis sai saindo de a-cidade E-levantou sobre-eles e os bateram;');
INSERT INTO verses VALUES (6800, 7, 9, 44, 'e Abimelque e os chefes; que com-ele despacharam-se; e se levantaram; entrada portão a-cidade e-dois os chefes despacharam-se; sobre todo que no-campo e os bateram;');
INSERT INTO verses VALUES (6801, 7, 9, 45, 'e Abimelque lutou בעיר todo o-dia aquele e prendeu a a-cidade e-a o-povo que nela matou e lançou a a-cidade e semeou sal');
INSERT INTO verses VALUES (6802, 7, 9, 46, 'e-ouviram todo em-lhes torre-do Siquém e-vieram a cortado casa El em-brisa');
INSERT INTO verses VALUES (6803, 7, 9, 47, 'e-ele-foi-dito a-Avimélek que [הִֽתְקַבְּצ֔וּ] todo בעלים shchem');
INSERT INTO verses VALUES (6804, 7, 9, 48, 'e-subiu Avimélek monte-de ele הוא֮ e-todo E-tomou que ITHO E-tomou אבימעל֨ a הקרדוםות בידיוֹ WAYYIKRETH SCOCHATH E-disse WAYYSHEASAHA e pôs sobre SHICMOM E-disse a o-povo que com-ela que reitem fiz corram façam como-ei');
INSERT INTO verses VALUES (6805, 7, 9, 49, 'va-yikr''tu também todo o-povo homem [אַחֲרֵ֤י] e-foram depois-de Avimelech e colocaram sobre [אֶֽת־הַצְּרִ֖יחַ] [בָּאֵ֑שׁ] sobre-eles também [כָּל־אַנְשֵׁ֧י] no-fogo [כְּאֶ֖לֶף] também todo homens-de Shekem homem');
INSERT INTO verses VALUES (6806, 7, 9, 50, 'E-andou Avimelech a [וַיִּ֥חַן] ve-yachan [וַֽיִּלְכְּדָֽהּ] e tomou-a;');
INSERT INTO verses VALUES (6807, 7, 9, 51, 'UMגדל- ser foi no-meio-de a-cidade WAYANUSU para-lá e-tudo os-homens והנשים e-todo בעלים- a-cidade e entregaram para ele e-ele-levantaram-se sobre gága o mígdel:');
INSERT INTO verses VALUES (6808, 7, 9, 52, 'E-veio Avimelech até o mígdel e lutou nele e se aproximou até porta o mígdel para queimá-lo em-o-fogo');
INSERT INTO verses VALUES (6809, 7, 9, 53, '[וַתַּשְׁלֵ֞ךְ] mulher uma [פֶּ֥לַח] [רֶ֖כֶב] sobre cabeça Avimélek [אֶת־גֻּלְגָּלְתּֽוֹ] a');
INSERT INTO verses VALUES (6810, 7, 9, 54, 'E-chamou מהרה a o-jovem levando-o kēlā''ı̂ E-disse a-ele שלף חרבךא ומתתי׃ para-que-não יאמרו׃ a-mim mulher הרגתוהו׃ e lhe recordou seu jovem E-morreu');
INSERT INTO verses VALUES (6811, 7, 9, 55, 'e-eles-deram-conta אִישׁ- que porque morreu Avimélek e-foram homem para-lugar-dele');
INSERT INTO verses VALUES (6812, 7, 9, 56, 'e-ele-estabeleceu Elohim a mau Avimelekh que fez לאבי֔ para matar a setenta seus irmãos');
INSERT INTO verses VALUES (6813, 7, 9, 57, 'e-a todo mau homens-de Siquem retornou Elohim em cima deles e-veio a-eles maldição Jotão filho-de Jarubal');
INSERT INTO chapters VALUES (221, 7, 10, 18);
INSERT INTO verses VALUES (6814, 7, 10, 1, 'E-levantou apos Avimélek para salvar a Israel תוֹלָ֧ע filho-de פּוּאָה filho-de dó-dó homem Issacar e-ele habitou בְּשָׁמִיר em-monte-de Efrayim');
INSERT INTO verses VALUES (6815, 7, 10, 2, '[וַיִּשְׁפֹּט֙] a Israel vinte e-três ano E-morreu e-foi-enterrado');
INSERT INTO verses VALUES (6816, 7, 10, 3, 'E-levantou depois-dele [יָאִ֖יר] [הַגִּלְעָדִ֑י] [וַיִּשְׁפֹּט֙] a Israel vinte e Sítim anos');
INSERT INTO verses VALUES (6817, 7, 10, 4, 'e-foi a-lhe trinta [רֹֽכְבִים֙] [עַל־שְׁלֹשִׁ֣ים] sobre trinta [עֲיָרִ֖ים] a-eles a-eles para-eles [׀] [חַוֺּ֣ת] aldeias-de até o-dia o-dia esta que em-terra-de o-Gileade');
INSERT INTO verses VALUES (6818, 7, 10, 5, 'E-morreu Jair e-ele-foi-sepultado [בְּקָמֽוֹן׃]');
INSERT INTO verses VALUES (6819, 7, 10, 6, 'וַיֹּסִ֣פוּ filhos-de Israel para fazer הָרַע֮ em-olhos-de yhwh yhwh a הַבְּעָלִ֣ים e-a הָעַשְׁתָּר֡וֹת e-a Elohim-de אֲרָם֩ e-a Elohim-de צִיד֜וֹן e-את Elohim-de Moabe e-את Elohim-de filhos-de Amom e-a Elohim-de pelos-filisteus e se afastaram a yhwh e-não o servirem; e o servirem:');
INSERT INTO verses VALUES (6820, 7, 10, 7, 'e-acendeu-se- yhwh yhwh em-Israel e venderam por-mão-de filisteus e na mão filhos-de Amon');
INSERT INTO verses VALUES (6821, 7, 10, 8, 'e se exaltaram e se alegraram a filhos-de Israel na-ano aquela oito esre ano a todo filhos-de Israel que em-além-de o-Jordão em-terra-de o-amorreu que em Gileade; e em Gileade:');
INSERT INTO verses VALUES (6822, 7, 10, 9, 'e-eles-passaram filhos-de Amom a o-Jordão para a guerra também em Judá e em Benjamim e-em-o lar muito e-a-ter para-israel muito');
INSERT INTO verses VALUES (6823, 7, 10, 10, 'e-vezeku filhos-de Israel a dizendo dizendo para-ti para-ti e-que abrimos a Elohim-nosso e-nos-servimos a os-בַעַל');
INSERT INTO verses VALUES (6824, 7, 10, 11, 'E-disse yhwh a filhos-de Israel não- de-Egito e-de o-amorreu e-de filhos-de Amom e-de filisteus');
INSERT INTO verses VALUES (6825, 7, 10, 12, 'e-tzidonim e-amaleque e-ma-on pressionaram a-vós e gritaram a-mim e salve vos mi-yada:');
INSERT INTO verses VALUES (6826, 7, 10, 13, 'e-vós עֲזַבְתֶּ֣ם me e serviram Elohim outros por isso não e farei lehoshiaבa a-vós');
INSERT INTO verses VALUES (6827, 7, 10, 14, 'vinde e gritem a Elohim que e-vós-escolhestes neles הֵ֛מָּה a-vós para-vocês na prova de vós:');
INSERT INTO verses VALUES (6828, 7, 10, 15, 'e-disseram filhos-de Israel a yhwh חָטָ֔אנוּ faça- tu para-nós conforme-toda o-bom o-dia somente que nos salve por-favor o-dia a-esta');
INSERT INTO verses VALUES (6829, 7, 10, 16, 'e levaram a Elohim-de o estrangeiro do meio deles e-serviram a yhwh e encurtou-se sua alma com trabalho Israel');
INSERT INTO verses VALUES (6830, 7, 10, 17, 'e clamaram filhos-de Amom e-acamparam em Gileade e reuniram-se filhos-de Israel e-acamparam em-o-monte-Mispa');
INSERT INTO verses VALUES (6831, 7, 10, 18, 'e-disseram o-povo príncipes-de Gilád homem a quem quem o-homem que Yachél para-lutar filhos-de será Yihyé a-todo para-todo habitantes-de Gileade');
INSERT INTO chapters VALUES (222, 7, 11, 40);
INSERT INTO verses VALUES (6832, 7, 11, 1, 'Ve''iftách Ha''Giládi ser homem valente e-ele filho-de mulher Zoná e-gerou Gilád a Iftách:');
INSERT INTO verses VALUES (6833, 7, 11, 2, 'e-deleveu esposa-de a-ele a-ele בָּנִים Va''yigg''dlú Bené- a mulher e foram expulsos a-ele Yiftach e-disseram que não herdaria na-casa-de que porque filho-de mulher outra tu');
INSERT INTO verses VALUES (6834, 7, 11, 3, 'e fugiu Yiftach de-diante-de seus-irmãos e-habitou em-terra-de bom e recolheram a Yiftach homens vazios ויצאו com-ele');
INSERT INTO verses VALUES (6835, 7, 11, 4, 'e-houve dos mares e lutaram filhos-de Amom com Israel');
INSERT INTO verses VALUES (6836, 7, 11, 5, 'e-houve conforme- [בְנֵֽי־עַמּ֖וֹן] filhos-de Amom com Israel e-andaram anciãos-de Gileade bom a bom');
INSERT INTO verses VALUES (6837, 7, 11, 6, 'e-disseram לְיִפְתָּ֔ח לְכָ֕ה וְהָיִ֥יתָה para-nós לְקָצִ֑ין וְנִֽלָּחֲמָ֖ה de-filhos Amon');
INSERT INTO verses VALUES (6838, 7, 11, 7, 'E-disse יִפְתָּח֙ לְזִקְנֵ֣י Gileade acaso-nao vós sn-eatem ou-me וַתְּגָרְשׁ֖וּנִי de-casa-de pai-meu E por que vistes-vos a-mim até-agora conforme aperto a-vós');
INSERT INTO verses VALUES (6839, 7, 11, 8, 'e-disseram anciãos-de Giláad a Iftach portanto agora nós voltamos para-ti e caminhamos conosco-s e lutamos filhos-de Amom serias a-nós a-todo para-todo habitantes-de Gileade');
INSERT INTO verses VALUES (6840, 7, 11, 9, 'E-disse יִפְתָּח a anciãos-de Giláad se מְשִׁיבִ֨ים vós a-mim para lutar filhos-de yhwh וְנָתַ֧ן yhwh eu diante-de-mim a-vós estarei a-vós לְרֹֽאשׁ׃');
INSERT INTO verses VALUES (6841, 7, 11, 10, 'e-disseram [זִקְנֵֽי־גִלְעָ֖ד] [אֶל־יִפְתָּ֑ח] yhwh será yhwh [בֵּֽינוֹתֵ֔ינוּ] ouviu [כִדְבָרְךָ֖] se não');
INSERT INTO verses VALUES (6842, 7, 11, 11, 'E-andou יִפְתָּח֙ com anciãos-de Gileade e-eles-postaram o-povo אֹתוֹ sobre-eles para-cabeca וּלְקָצִ֑ין e-falou יפתח a yhwh דבריו diante-de yhwh em-o-monte-Mispa');
INSERT INTO verses VALUES (6843, 7, 11, 12, 'e-estendeu [יִפְתָּח֙] mensageiros a rei dizendo Amom dizendo que para-mim e-para-ti porque');
INSERT INTO verses VALUES (6844, 7, 11, 13, 'E-disse rei filhos-de Amon a mensageiros-de יפתח porque tomou Israel a קנמי בעולתו e-agora de-Arnon e-até היאבק e-até o Jordão e-agora הָשִׁ֥יבָה a-elas em-paz');
INSERT INTO verses VALUES (6845, 7, 11, 14, 'וַיּ֥וֹסֶף ainda יִפְתָּ֑ח e-enviou mensageiros a rei filhos-de Amon');
INSERT INTO verses VALUES (6846, 7, 11, 15, 'E-disse a-ele assim disse יִפְתָּ֑ח não tomou Israel a terra Moabe e-a terra filhos-de Amon');
INSERT INTO verses VALUES (6847, 7, 11, 16, 'que בַּעֲלוֹתָ֣ם de-Egito E-andou Israel bamidbar até mar-de Suf E-veio קָדֵֽשָׁה׃');
INSERT INTO verses VALUES (6848, 7, 11, 17, 'e-enviou Israel מַלְאָכִ֣ים ׀ a rei אֱד֨וֹם ׀ Dize dizendo agora בְאַרְצֶ֗ךָ e-não ouviu rei Edom e-tambem a rei Moabe enviou e-não אָבָ֑ה e-habitou Israel בְּקָדֵֽשׁ׃');
INSERT INTO verses VALUES (6849, 7, 11, 18, 'E-andou no-deserto וַיָּ֜סָב a terra Edom e-a terra Moabe E-veio מִמִּזְרַח־ Shemesh לְאֶ֣רֶץ Moabe em-além-de אַרְנ֑וֹן e-não que em-limite-de Moabe porque אַרְנ֖וֹן fronteira-de Moabe');
INSERT INTO verses VALUES (6850, 7, 11, 19, 'e-estendeu Israel mensageiros a [מֶֽלֶךְ־הָאֱמֹרִ֖י] rei-de o-amorreu E-disse a-ele E-disse a-ele Israel [עַד־מְקוֹמִֽי] até');
INSERT INTO verses VALUES (6851, 7, 11, 20, 'e-não [סִיח֤וֹן] [אֶת־יִשְׂרָאֵל֙] a Israel [וַיֶּאֱסֹ֤ף] [סִיחוֹן֙] [אֶת־כָּל־עַמּ֔וֹ] [וַֽיַּחֲנ֖וּ] a todo povo-seu com Israel');
INSERT INTO verses VALUES (6852, 7, 11, 21, 'E-colocou yhwh Elohim-de Israel a סִיח֧וֹן e-a todo povo-dele em-mão-de Israel e atingiram-no וַיִּירַשׁ֙ Israel a-terra todo terra o-amorreu habitante a-terra a-ela');
INSERT INTO verses VALUES (6853, 7, 11, 22, 'e-virreram-se a todo território o-emorí de-arnôn e-até o-yabbôq e-de o-midbar e-até o-Jordão');
INSERT INTO verses VALUES (6854, 7, 11, 23, 'e-agora yhwh Elohim-de Israel despojou a o-amorreu de-diante-de seu-povo Israel e-tu nossa-nosvirreremos');
INSERT INTO verses VALUES (6855, 7, 11, 24, 'não-acaso a que te-virre como-mosso teu-Elohim אֹתוֹ tiráš e-את todo que yhwh yhwh Elohim nosso de-faces-de-nós אֹתוֹ נִרָֽשׁ׃');
INSERT INTO verses VALUES (6856, 7, 11, 25, 'e-agora hátov bom tu mibbálak filho-de cípor rei Moabe hárov muito com Israel se nílachom nílacham em-eles');
INSERT INTO verses VALUES (6857, 7, 11, 26, 'בְּשֶׁ֣בֶת Israel bécheshavóon e nas suas filhas e na sua pele e nas suas filhas e-em-todo as cidades que sobre mãos-de Arnon três centenas ano e por que não vocês me salvaram em-o tempo a-ela');
INSERT INTO verses VALUES (6858, 7, 11, 27, 'e-eu não para-ti para-ti e-tu fez comigo maldade para-lutar em-mim yhwh yhwh o-dia entre entre filhos-de e-entre e-entre filhos-de Amon');
INSERT INTO verses VALUES (6859, 7, 11, 28, 'e-não ouviu rei filhos-de Amom a palavras-de Jiftach que a-ele a-ele');
INSERT INTO verses VALUES (6860, 7, 11, 29, 'e-foi sobre espírito yhwh yhwh e-ele-passou a a Gileade e-a Manassés e passou a מצפה Gileade ומימ Mitspeh Gileade עבר filhos-de Amon');
INSERT INTO verses VALUES (6861, 7, 11, 30, '[וַיִּדַּ֨ר] [יִפְתָּ֥ח] [נֶ֛דֶר] a-yhwh E-disse se [תִּתֵּ֛ן] [אֶת־בְּנֵ֥י] a filhos-de');
INSERT INTO verses VALUES (6862, 7, 11, 31, 'e-foi היווצה que יֵצֵ֜א מִדּוֹלְתֵ֤י בֵיתִי֙ לִקְרָאִתִי בְּשׁוּבִ֥י em paz de-filhos-de Amom e-foi a-yhwh וְהַעֲלִיתִ֖הוּ עוֹלָֽה׃');
INSERT INTO verses VALUES (6863, 7, 11, 32, 'e-ele-passou יִפְתָּ֛ח a filhos-de Amom para-lutar neles yhwh yhwh em-mão-sua');
INSERT INTO verses VALUES (6864, 7, 11, 33, 'וַיַּכֵּ֡ם מֵעֲרוֹעֵר֩ e-até בוֹאֲךָ֨ minnit vinte cidade e-ate Abel karamim ferida muito muito va-yikkanevu filhos-de de-diante-de de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (6865, 7, 11, 34, 'E-veio yiftach hamatzpah a beito e-eis bito yotse ao-encontro-dele betufim uvimacholot וְרַק֙ ela יְחִידָ֔ה nós filho de-ele filho ou בַֽת׃');
INSERT INTO verses VALUES (6866, 7, 11, 35, 'e-houve כִרְאוֹת֨וֹ אוֹתָ֜הּ e-ele-partiu a E-disse E-disse אֲהָ֤הּ filha-minha הַכְרֵ֣עַ הִכְרַעְתִּ֔נִי וְאַ֖תְּ הָיִ֣יתְ nas raízes e-eu Eu fui quebrantado— minha boca— a yhwh e-não posso para voltar;—');
INSERT INTO verses VALUES (6867, 7, 11, 36, 'E-disse a-ele pai-meu você quebrou— a boca-tua a yhwh fez sair conforme saiu de ti— depois de; após;— a-ti yhwh para-ti yhwh vindictas;— dos teus inimigos;— de-filhos-de Amon');
INSERT INTO verses VALUES (6868, 7, 11, 37, 'E-disse a seu-pai a-mim para-mim a-coisa esta retira-te; afaste-te;— de mim— dois חדשים ואילכחה וירדתני sobre os-montes eu sobre בתולאי eu');
INSERT INTO verses VALUES (6869, 7, 11, 38, 'E-disse [לֵ֔כִי] e-enviou [אוֹתָ֖הּ] segundo meses e-foi ela [וְרֵ֣עוֹתֶ֔יהָ] [וַתֵּ֥בְךְּ] sobre [עַל־הֶהָרִֽים] sobre');
INSERT INTO verses VALUES (6870, 7, 11, 39, 'e-houve de-ano dois חדשים VASHAV Vatasheb a seu-pai E-fez para-ela a nidrō que nādā'' vehi''ă não yad''ă''ă homem e-ela-tornou-se chōq em-Israel');
INSERT INTO verses VALUES (6871, 7, 11, 40, 'de-dias yāmīmâ tēlā''kănāhă filhas-de Israel lətanōt para-filha-de יִפְתַּח haggil''ē''ădī quatro dias bāšānāhō');
INSERT INTO chapters VALUES (223, 7, 12, 15);
INSERT INTO verses VALUES (6872, 7, 12, 1, 'e invocou homem Efraim e-atravessou para-o-norte e-disseram aifetá por que passaste para-lutar nos filhos de amom e para nós não não para-andar contigo na tua casa furestes sobre-ti em-a-chama');
INSERT INTO verses VALUES (6873, 7, 12, 2, 'E-disse ifetá a-eles homem rix estive eu ve''ami u''venei- muito muito va''ezake vos e-não hoshateem otie mi-yada:');
INSERT INTO verses VALUES (6874, 7, 12, 3, 'va''are''e porque einakha- moshi'' va''asima nafshi bikappi va''e''baarah a filhos-de yhwh vayitenem yhwh beyadi velama o-dia a-mim o-dia este para-lutar em-mim');
INSERT INTO verses VALUES (6875, 7, 12, 4, 'vayiqatz yiftach a todo homens-de Gileade vayillachem a Efraim vayikchu que Giláad a Efraim porque disseram no-meio-de Efraim no-meio-de Giláad no-meio-de Efraim no-meio-de מְנַשֶּֽׁה׃');
INSERT INTO verses VALUES (6876, 7, 12, 5, 'e prendeu Giláad a as que atravessam o Jordão a Éfraim que porque אומרים refugiados Efraim que atravessarei a-ele para-ele os-homens-de- tu E-disse tu não não');
INSERT INTO verses VALUES (6877, 7, 12, 6, 'e-disseram a-ele dize por-favor E-disse E-disse סִבּוֹלֶת e-não יָכִין֙ para-falar assim e-agarraram com-ele וַיִּשְׁחָט֖וּהוּ a מַעְבְּר֣וֹת o Jordão e-caiu em-o-tempo הַהִיא֙ מֵֽאֶפְרַ֔יִם quarenta וּשְׁנַ֖יִם mil');
INSERT INTO verses VALUES (6878, 7, 12, 7, 'e julgou יִפְתָּ֛ח a Israel seis dois E-morreu יִפְתָּח֙ o-gileadi e-ele-foi-sepultado em-cidades-de Gileade');
INSERT INTO verses VALUES (6879, 7, 12, 8, 'e-julgou atrás-dele a Israel אִבְצָ֖ן de-casa-de pão');
INSERT INTO verses VALUES (6880, 7, 12, 9, 'e-foi a-ele trinta בָּנִ֗ים e-trinta בָּנוֹת֙ enviou הַח֔וּץָה וּשְׁלֹשִׁ֣ים בָּנ֔וֹת trouxe para-ele de הַח֑וּץ וַיִּשְׁפֹּ֥ט a Israel sete dois');
INSERT INTO verses VALUES (6881, 7, 12, 10, 'E-morreu [אִבְצָ֔ן] e-ele-foi-sepultado em-casa-de pão');
INSERT INTO verses VALUES (6882, 7, 12, 11, 'e-julgou אַחֲרֵי a Israel אֵילוֹן הַזְבֻּלוֹנִי וַיִּשָּׁפֵט a Israel dez dois');
INSERT INTO verses VALUES (6883, 7, 12, 12, 'E-morreu Elom הַזְבֻּלוֹנִי e-foi-enterrado em-Ayalon em-terra-de זְבֻּלוֹן׃');
INSERT INTO verses VALUES (6884, 7, 12, 13, '[וַיִּשְׁפֹּ֥ט] atrás-dele a Israel [בֶּן־הִלֵּ֖ל] filho-de');
INSERT INTO verses VALUES (6885, 7, 12, 14, 'e-foi a-ele quarenta בָּנִים וּשְׁלֹשִׁים֙ filhos filhos רוכבים sobre setenta ערyıמים e julgou a Israel oito dois');
INSERT INTO verses VALUES (6886, 7, 12, 15, 'E-morreu עבדון filho-de הילל הפרעאתוני וייקבר no-exame em-terra-de Efraim na-montanha הערmaaleki׃');
INSERT INTO chapters VALUES (224, 7, 13, 25);
INSERT INTO verses VALUES (6887, 7, 13, 1, 'e-adicionaram filhos-de Israel para-fazer o-mal em-olhos-de yhwh WAYITTEM yhwh por-mão-de Filisteus quarenta anos');
INSERT INTO verses VALUES (6888, 7, 13, 2, 'e-houve homem um מצראעה de-família-de הדני e-nome-de-ele מנוח e-esposa-dele de-Aquerá e-não yaladá:');
INSERT INTO verses VALUES (6889, 7, 13, 3, 'E-viu anjo-de yhwh E-disse [אֵלֶ֗יהָ] E-disse [אַתְּ־עֲקָרָה֙] eis-que- por-favor [OBJ] estéril filho filho');
INSERT INTO verses VALUES (6890, 7, 13, 4, 'e-agora guarda-te por-favor e-a toma-te vinho e pão e-a comeres todo טָמֵֽא׃');
INSERT INTO verses VALUES (6891, 7, 13, 5, 'que eis-te grávida e-parirás filho וּמוֹרָה֙ não subir sobre cabeça-sua será nazireu Elohim será o-menino de o-ba-tên וְה֗וּא yaché-hu lehoshiaבa a Israel de-mão-de filisteus');
INSERT INTO verses VALUES (6892, 7, 13, 6, 'e-veio a-mulher E-disse le-íšah dizendo homem o-Elohim veio a-mim ú-mara-ehu kamara-eh anjo o-Elohim נורא muito e-não ša''iltiyhu ei- ele ele e-a seu-nome não declarou a-mim');
INSERT INTO verses VALUES (6893, 7, 13, 7, 'E-disse a-mim eis-a grávida e-parirás filho e-agora a tish-ti vinho e salário e-a tó-akli todo impureza será nezír Elohim será o jovem de o-ba-tên até dia מותו׃');
INSERT INTO verses VALUES (6894, 7, 13, 8, 'e aturá Manoach a yhwh E-disse por-mim אדונָי homem a Elohim que tenslachtá irá- por-favor ainda nossel e yorenu que foi-feito para na''ar o julad:');
INSERT INTO verses VALUES (6895, 7, 13, 9, 'E-ouviu o-Elohim com-voz Manoach E-veio malakh הָאֱלֹהִים ainda a a-mulher וְהִיא֙ sentada no-campo וּמָנ֥וֹחַ espos-a com-ela com ela:');
INSERT INTO verses VALUES (6896, 7, 13, 10, 'וַתְּמַהֵר֙ a-mulher ela correu e-relatou לְאִישָׁ֑הּ E-disse a-ele eis foi vista a-mim o-homem que veio בַיּ֖וֹם para-mim');
INSERT INTO verses VALUES (6897, 7, 13, 11, 'E-levantou E-andou descanso depois-de mulher-sua E-veio a E-disse a-ele para-ele és-tu o-homem que E-disse a E-disse');
INSERT INTO verses VALUES (6898, 7, 13, 12, 'E-disse מָנ֔וֹחַ agora vira דְבָרֶ֑יךָ que יִּֽהְיֶ֥ה מִשְׁפַּט־ o-menino e o seu fez:');
INSERT INTO verses VALUES (6899, 7, 13, 13, 'E-disse [מַלְאַ֥ךְ] yhwh a de-toda de-todo que disse a');
INSERT INTO verses VALUES (6900, 7, 13, 14, 'de-toda que sair מִגֶּ֨פֶן não comerás comer e vinho e-escorume a beber e-todo impureza a comer todo que צִוַּתְהֶ֔י guarda');
INSERT INTO verses VALUES (6901, 7, 13, 15, 'E-disse descanso a yhwh yhwh eu me contenho agora a-ti e façamos diante-de-ti carneiro cabritos :');
INSERT INTO verses VALUES (6902, 7, 13, 16, 'E-disse anjo-de yhwh a repouso se eu me contenho não come em-teu-pão e-se que a-subida a-yhwh אתעלאנה yhwh ele conheceu ele porque yhwh yhwh ela');
INSERT INTO verses VALUES (6903, 7, 13, 17, 'E-disse descanso a yhwh quem quem o-teu-nome porque virá e-augusto-teu');
INSERT INTO verses VALUES (6904, 7, 13, 18, 'E-disse para-ele anjo yhwh por-que isto תִּשְׁאַ֣ל para-o-nome-meu ve-hu-');
INSERT INTO verses VALUES (6905, 7, 13, 19, 'E-tomou descanso a cordeiro as-oveis e-a a oferta-cereais e-ofereceu sobre a-rocha para-יהוה e-maravilhoso para-fazer e-descanso e-esposa-dele vêes');
INSERT INTO verses VALUES (6906, 7, 13, 20, 'e-houve em-ascer הַלָּהַב de-cima-de o-altar dos-céus e-ofereceu anjo-de yhwh בְּ lahַב o-altar Manoach וְאִשְׁתֹּ רֹאִים וַיִּפְל֤וּ sobre faces-deles para-terra');
INSERT INTO verses VALUES (6907, 7, 13, 21, 'e-não [עוֹד֙] ainda yhwh yhwh [אֶל־מָנ֣וֹחַ] a [אָ֚ז] saber mulher-sua então yhwh ele porque yhwh');
INSERT INTO verses VALUES (6908, 7, 13, 22, 'E-disse [מָנ֛וֹחַ] a morrendo morte-de que porque Elohim');
INSERT INTO verses VALUES (6909, 7, 13, 23, 'E-disse a-ele esposa-dele [לוּ֩] [חָפֵ֨ץ] yhwh [לַהֲמִיתֵ֙נוּ֙] não tomou [עֹלָ֣ה] holocausto [וְלֹ֥א] e-não [אֶת־כָּל־אֵ֑לֶּה] a não estes [כָּזֹֽאת] não');
INSERT INTO verses VALUES (6910, 7, 13, 24, 'ela-deu-a-luz- a-mulher filho e-chamou a seu-nome שִׁמְשׁ֑וֹן וַיִּגְדַּ֣ל o jovem yhwh yhwh');
INSERT INTO verses VALUES (6911, 7, 13, 25, 'e comeu espírito yhwh em-pelo em-câne- entre entre e-entre e-entre ashtola:');
INSERT INTO chapters VALUES (225, 7, 14, 20);
INSERT INTO verses VALUES (6912, 7, 14, 1, 'e-desceu Shimshon Timnat- E-viu mulher em-Timnat- מבנות filisteus');
INSERT INTO verses VALUES (6913, 7, 14, 2, 'e-subiu e contou para-seu-pai e-a-mãe- E-disse mulher vi בתימנתה מבנות filisteus e-agora tomai a-mim para-mim para-mulher');
INSERT INTO verses VALUES (6914, 7, 14, 3, 'E-disse a-ele seu-pai ve-im-mo האין בבנות אחיך e-em-todo meu-povo mulher porque tu הלך tomar mulher E-disse הערלים E-disse שימשון a seu-pai אותה toma- de-cima-de porque ela ישרה em-me');
INSERT INTO verses VALUES (6915, 7, 14, 4, 'e seu pai e sua mãe não sabiam que por yhwh ela porque desejo ele buscando dos filisteus e-no-tempo-de aquela Filisteus príncipes em-Israel');
INSERT INTO verses VALUES (6916, 7, 14, 5, 'e desceu שִׁמְשׁוֹן וְאָבִ֥יו וְאִמּ֖וֹ תִּמְנָ֑תָה e-vieram até כַּרְמֵ֣י תִּמְנָ֔תָה e-eis כְּפִ֣יר arayot שֹׁאֵ֖ג לִקְרָאתֽוֹ׃');
INSERT INTO verses VALUES (6917, 7, 14, 6, 'וַתִּצְלַ֨ח sobre-ele espírito yhwh e o fez estremecer como se estremecesse o gazela e a fêmea não-há na-sua-mão e-não declarou para-seu-pai e da mãe a que fez');
INSERT INTO verses VALUES (6918, 7, 14, 7, 'e-ele-descerrou e-falou para a mulher ela se estremera em-olhos-de Samson');
INSERT INTO verses VALUES (6919, 7, 14, 8, 'e-ele-retornou dos rios para tomar e tirou para-ver a caída a ursos e-eis congregação-de de formigas na garganta a ursos e-mel');
INSERT INTO verses VALUES (6920, 7, 14, 9, 'e o esmagou a com suas mãos E-andou caminhar e comeu E-andou a E-colocou a-eles mãe-dele E-deu a-eles que e-não relatou a-eles porque מִגּוֹויָה הָאַרְיֵה dominai הַדְּבָֽשׁ׃');
INSERT INTO verses VALUES (6921, 7, 14, 10, 'e-desceu [אָבִ֖יהוּ] a [וַיַּ֨עַשׂ] E-fez nome [מִשְׁתֶּ֔ה] que porque assim [הַבַּחוּרִֽים]');
INSERT INTO verses VALUES (6922, 7, 14, 11, 'e-houve כִּרְאוֹתָם אוֹתֹו e-eles-levaram trinta מֵרֵעִ֔ים e-foram com-ele');
INSERT INTO verses VALUES (6923, 7, 14, 12, 'E-disse a-eles שִׁמְשׁוֹן אָחֽוּדָה־ a-vós para-vocês חִידָ֑ה se הַגֵּ֣ד תַּגִּidoוּ֩ אוֹתָ֨הּ dias-de שִׁיבְעַ֨ת יְמֵ֤י הַמִּשְׁתֶּה֙ a-vós e-darei para-vocês trinta sedínim e-trinta chălipôth begadim');
INSERT INTO verses VALUES (6924, 7, 14, 13, 'e-se não tûkêluָ para-dizer para-mim u''nêtâttem vós a-mim trinta sedínim e-trinta chălipôth bבgadîm a-ele a-ele chûdâh chidâtêkâ vênishmâ''ênâ');
INSERT INTO verses VALUES (6925, 7, 14, 14, 'E-disse a-eles de-a-oçel sair alimento e-az sair ma-tóq e-não יָכְל֛וּ para anunciar a-chidá três dias');
INSERT INTO verses VALUES (6926, 7, 14, 15, 'e-houve no-dia no-dia e-disseram para-a-esht shimshon pati a ish-ekh e dirá- a-nós a a-chidá para-que-não nisrof te-a e-a casa seu-pai no-fogo o-nossos-herdeiros vocês-chamaram para-nós não');
INSERT INTO verses VALUES (6927, 7, 14, 16, 'e-você-chorou esposa-de shimshon sobre-ele E-disse somente me-desgostaste e-não você-me-amaras o-palpite eu-disse aos-filhos-de povo-meu não não E-disse E-disse eis eis לְאָבִ֧י não não הִגַּ֖דְתִּי וְלָ֥ךְ אַגִּֽיד׃');
INSERT INTO verses VALUES (6928, 7, 14, 17, 'וַתֵּ֤בְךְּ sobre-ele sete-de os-dias que a-eles a-eles e-houve e-foi no-dia o-sétimo e-contou que porque הֱצִיקַ֔תְהוּ e disse הַחִידָ֖ה para-filhos-de a-sua-pena;');
INSERT INTO verses VALUES (6929, 7, 14, 18, 'e-disseram a-ele homens-de a-cidade no-dia o-sétimo בטרעם vira הַחַ֔רְסָה que מָּת֣וֹק מִדְּבַ֔שׁ e-me força E-disse a-eles a-eles se-lulé charrash''tem não não metsa''tem chidáti:');
INSERT INTO verses VALUES (6930, 7, 14, 19, 'vata-tslekh sobre-ele espírito yhwh e-descer Ashkelon e-feriu mehem @ trinta homem E-tomou E-tomou [אֶת־חֲלִ֣יצוֹתָ֔ם] E-colocou as chalípovot para-maggeidi a-chidá e-acendeu-se sua-ira e-ele-subiu casa avíhu');
INSERT INTO verses VALUES (6931, 7, 14, 20, 'e-foi mulher-de shimshon para-mera''ehu que re''a a-ele');
INSERT INTO chapters VALUES (226, 7, 15, 20);
INSERT INTO verses VALUES (6932, 7, 15, 1, 'e-houve míyim em-dias-de ceifa-de Chittim e-ele-fiscalizou shimshon a אִשְׁתּוֹ֙ E-disse אִיזֻים E-disse אָבוֹאָה a אִישְׁתִּי הֶחָדְרָה e-não נְתָנוֹ אָבִיהָ לָבֽוֹא׃');
INSERT INTO verses VALUES (6933, 7, 15, 2, 'E-disse אָבִיהָ disse dissesse porque odiou שְׂנֵאתָהּ וָאֶתְּנֶנָּה לְמֵרֵעֶךָ não-é-que irmã dela a pequena boa de-a a-ti agora a-ti abaixo-de-a');
INSERT INTO verses VALUES (6934, 7, 15, 3, 'E-disse a-eles Shimshon eu arranquei desta-vez dos filisteus porque fez eu com-eles mal');
INSERT INTO verses VALUES (6935, 7, 15, 4, 'E-andou Shimshon וַיִּלְכֹּ֖ד três- centenas-de E-tomou E-tomou aos filhos de e se voltou cauda a cauda um לַפִּ֥יד um entre segundo הַזְּנָב֖וֹת בַּתָּֽוֶךְ׃');
INSERT INTO verses VALUES (6936, 7, 15, 5, '[וַיַּבְעֶר־אֵשׁ֙] fogo [וַיְשַׁלַּ֖ח] e-enviou [פְּלִשְׁתִּ֑ים] filisteus [מִגָּדִ֥ישׁ] [וְעַד־קָמָ֖ה] e-até [זָֽיִת]');
INSERT INTO verses VALUES (6937, 7, 15, 6, 'e-disseram filistim: quem fez esta e-disseram shimshon: cunhado: da-timi: que tomou a mulher-dele e-lhe-deu: para-sua-cunhada: e-subiram filisteus e-queimaram: ela: e-a seu-pai: em-a-chama');
INSERT INTO verses VALUES (6938, 7, 15, 7, 'E-disse a-eles [שִׁמְשׁ֔וֹן] se [כָּזֹ֑את] que porque se [וְאַחַ֥ר] [אֶחְדָּֽל]');
INSERT INTO verses VALUES (6939, 7, 15, 8, 'vayyakh אוֹתָם שֹׁק sobre יָרֶךְ punição grande e-desceu וַיֵּשֶׁב בִּסְעִיף סֶלַע עֵיטָֽם׃');
INSERT INTO verses VALUES (6940, 7, 15, 9, 'e-subiram filisteus e-acamparam em-Judá e-eles-deram בַּלֶּֽחִי׃');
INSERT INTO verses VALUES (6941, 7, 15, 10, 'e-disseram homem Judá [לָמָ֖ה] [עֲלִיתֶ֣ם] sobre-nós e-disseram [לֶאֱס֤וֹר] a [עָלִ֔ינוּ] [לַעֲשׂ֣וֹת] a-ele a-ele conforme fez');
INSERT INTO verses VALUES (6942, 7, 15, 11, 'וַיֵּרְד֡וּ שְׁלֹשֶׁת֩ אֲלָפִ֨ים homem מִיְהוּדָה a סְעִיף סֶלַע עֵיטָם e-disseram לְשִׁמְשׁוֹן acaso-nao tu-conheceste porque מֹשְׁלִים בָּנוּ filisteus e-que E-disse a-eles para-nos E-disse a-eles como fizeram a-eles dizendo fiz para-eles');
INSERT INTO verses VALUES (6943, 7, 15, 12, 'e-disseram a-ele לֶאֱסָרְךָ יָרַדְנוּ לְתִתְּךָ֖ por-mão-de E-disse a-eles para-eles שִׁמְשׁוֹן hissabu a-mim para-que-não tipgeun em-mi atam:');
INSERT INTO verses VALUES (6944, 7, 15, 13, 'e-disseram a-ele dizendo não porque asor neasarrekha unetannukha byadam não não nemitekha vayassuruhu bishnayim עֲבוֹתִים חֲדָשִׂים וַיַּעֲלוּהוּ de הַסֶּֽלַע׃');
INSERT INTO verses VALUES (6945, 7, 15, 14, 'ele veio até [הֵרִ֣יעוּ] [לִקְרָאת֑וֹ] [וַתִּצְלַ֨ח] [עָלָ֜יו] espírito yhwh espírito yhwh [אֲשֶׁ֣ר] [עַל־זְרוֹעוֹתָ֗יו] que sobre [בָּעֲר֣וּ] [בָאֵ֔שׁ] que [אֱסוּרָ֖יו] de-cima-de [יָדָֽיו]');
INSERT INTO verses VALUES (6946, 7, 15, 15, '[וַיִּמְצָ֥א] [לְחִֽי־חֲמ֖וֹר] [טְרִיָּ֑ה] [וַיִּשְׁלַ֤ח] sua-mão mão-dele e-tomou-a [אֶ֥לֶף] nela mil homem');
INSERT INTO verses VALUES (6947, 7, 15, 16, 'E-disse שִׁמְשׁוֹן בִּלְחִי o-jumento חֲמֹר חֲמֹרָתַיִם בִּלְחִי o-jumento הִכּוֹתִי mil homem');
INSERT INTO verses VALUES (6948, 7, 15, 17, 'e-houve כְּכַלוֹ לְדַבֵּר וַיִּשְׁלָךְ הַלּחִי מִיָּדֹו E-chamou para-o-lugar o-aquele רָמַת לֶֽחִי׃');
INSERT INTO verses VALUES (6949, 7, 15, 18, 'וַיִּצְמָא֮ muito E-chamou a yhwh tu tu נָתַ֣תָּ בְיַֽד־ teu-servo a e-agora a-grande esta e-agora אָמ֣וּת בַּצָּמָ֔א וְנָפַלְתִּ֖י em-mão-de os-incircuncisos');
INSERT INTO verses VALUES (6950, 7, 15, 19, 'וַיִּבְקַ֨ע Elohim a הַמַּכְתֵּ֣שׁ que nós águas mimnu águas e-a e-ela-voltou-se rucho vayachi chamou ken chamou shama olho haqore até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (6951, 7, 15, 20, 'e-julgou a Israel בִּימֵ֥י dos-filisteus vinte anos');
INSERT INTO chapters VALUES (227, 7, 16, 31);
INSERT INTO verses VALUES (6952, 7, 16, 1, 'E-andou shimshon azata e-viu- nome mulher zonah E-veio a-ela');
INSERT INTO verses VALUES (6953, 7, 16, 2, '[לֽ͏ַעַזָּתִ֣ים] dizendo dizendo [בָּ֤א] elas [הֵ֔נָּה] [וַיָּסֹ֛בּוּ] a-ele todo [בְּשַׁ֣עַר] [הָעִ֑יר] a-cidade [כָל־הַלַּ֙יְלָה֙] dizendo a-noite dizendo até luz');
INSERT INTO verses VALUES (6954, 7, 16, 3, 'e-ele-deitou שִׁמְשׁוֹנָה até metade הַלַּיְלָה e-elevantou-se- em-meio a-noite וַיֵּאָחֵז nas-portas shaar- a-cidade e-nas as-mezuzot e-os-sacou com a-cortina e pôs sobre por-suas-costas e-os-leveu a cabeça yhwh que sobre face-de Hebrom');
INSERT INTO verses VALUES (6955, 7, 16, 4, 'e-aconteceu assim e amou mulher pela torrente estreito e-nome-dela de-pouco');
INSERT INTO verses VALUES (6956, 7, 16, 5, 'vayaalu a-ela príncipes-de פְלִשְׁתִּ֗ים e-disseram para-ela פתיתי אותו e-verás במה כחו grande ובמה נווכלים a-ele ואסרנווהו לאונטו e-nós foi-dado- para-ti homem mil e-cem כסף׃');
INSERT INTO verses VALUES (6957, 7, 16, 6, 'E-disse [דְּלִילָה֙] a [הַגִּֽידָה־נָּ֣א] [לִ֔י] agora a-mim [גָד֑וֹל] [וּבַמֶּ֥ה] grande [לְעַנּוֹתֶֽךָ]');
INSERT INTO verses VALUES (6958, 7, 16, 7, 'E-disse para-ela [שִׁמְשׁ֔וֹן] se [בְּשִׁבְעָ֛ה] [יְתָרִ֥ים] [לַחִ֖ים] [אֲשֶׁ֣ר] que não [וְהָיִ֖יתִי] como-um-de o-homem o-homem');
INSERT INTO verses VALUES (6959, 7, 16, 8, 'e subiram- para ela príncipes-de פְלִשְׁתִּ֗ים sete mais vivos que não foram destruídos e prendeu-o neles');
INSERT INTO verses VALUES (6960, 7, 16, 9, 'e o urso habitou a-ela no quarto E-disse a-ele filisteus sobre-ti Шимшон e-natqâ a hay塔rîm como-que ynnâtêk p̄tîl- hannâ''oretâ bha哈rîkhô fogo e-não quem kôkhô׃');
INSERT INTO verses VALUES (6961, 7, 16, 10, 'E-disse d̆lîlâhâ a eis behold hetalta em-mim e falaste para-mim כּזָבִים agora diga-a agora a-mim E-disse תּאָסֵר׃');
INSERT INTO verses VALUES (6962, 7, 16, 11, 'E-disse a ela se אסור יאסרון בעבותים חדשים que não obra neles trabalho como-um-de o-homem como-um-de o-homem');
INSERT INTO verses VALUES (6963, 7, 16, 12, 'e-tomou דלילה עבותים חדשים ותאסרהוּ בהם E-disse a-ele פלשתים sobre-ti שׁמשון והערב habitou בחדר WAYYENATQEM de-cima-de זרועותיו כּחוט׃');
INSERT INTO verses VALUES (6964, 7, 16, 13, 'E-disse דלילה a שׁמשון até HENNAH hetaletta em-mim vatadebber a-mim a-mim declara para-mim E-disse teasar E-disse a ela se taargi a sete machalpot minha-cabeça com hamasshet');
INSERT INTO verses VALUES (6965, 7, 16, 14, 'vataqaa bayyad E-disse a-ele philistim sobre-ti shimshon e acordou de sua vigília e levantou-se a a tenda o estrado e-a o candelabro;');
INSERT INTO verses VALUES (6966, 7, 16, 15, 'E-disse a-ele como תֹאמַר eu te amei e o teu coração não-há comigo este três vezes tu caíste em-mim e-não a-mim para-mim com-o-que em tua força grande');
INSERT INTO verses VALUES (6967, 7, 16, 16, 'e-houve porque para-ele [בִדְבָרֶ֛יהָ] [כָּל־הַיָּמִ֖ים] todo os-dias [נַפְשׁ֖וֹ] [לָמֽוּת]');
INSERT INTO verses VALUES (6968, 7, 16, 17, 'e-contou para-ela E-disse todo coração-dele E-disse a-ela mórah não subiu sobre roshi porque nəzīr Elohim eu מבטן mim-i se גללחתי֙ e-se-apartará ממני força-mi como-um-de o-homem conforme-toda o-homem');
INSERT INTO verses VALUES (6969, 7, 16, 18, 'E-viu dilalah porque disse-lhe a-lá-ela a todo seu-coração e-enviou-a dizendo para-sarnei desta-vez para-dizer עֲל֣וּ esta-vez porque disse-lhe a todo seu-coração e-subiram para-ela príncipes-de filisteus e-eles-subiram E-disse com-a-mão-deles');
INSERT INTO verses VALUES (6970, 7, 16, 19, 'e aconchegou-o sobre nas suas coxas e-ela-le-u para-o homem e lhe despiu a sete roupas sua-cabeça e começou a para-oprimir-ele e ele se desviou sua força me''alayo');
INSERT INTO verses VALUES (6971, 7, 16, 20, 'E-disse filisteus sobre-ti samson e acordou do seu sono E-disse Saírei Cada Em cada e levantarei-me e-ele não saber que yhwh sir me''alayo');
INSERT INTO verses VALUES (6972, 7, 16, 21, 'E pegaram-no filisteus e gritaram a seus olhos וַיּוֹרִ֨idoּ a ele força e-os-sr-uhu e-houve E-foi to-ch-en em-casa-de');
INSERT INTO verses VALUES (6973, 7, 16, 22, 'va-yach-el sa-ar- cabeça-sua le-tzam-ma-ch como-que gu-l-la-ch');
INSERT INTO verses VALUES (6974, 7, 16, 23, 'e-ossos פְלִשְׁתִּ֗ים ne-es-pu para-sacrificar zevach- grande le-da-gon Elohim-deles va-le-sim-ma-ha dar deu Elohim-nosso be-yad-en-u a שִׁמְשׁוֹן אֹיְבֵֽינוּ׃');
INSERT INTO verses VALUES (6975, 7, 16, 24, '[וַיִּרְא֤וּ] ele o-povo [וַֽיְהַלְל֖וּ] a que porque dar deu [בְיָדֵ֙נוּ֙] [אֶת־א֣וֹיְבֵ֔נוּ] e-[OBJ] [מַחֲרִ֣יב] e-[OBJ] [וַאֲשֶׁ֥ר] [הִרְבָּ֖ה] e-que a');
INSERT INTO verses VALUES (6976, 7, 16, 25, 'e-houve לִבָּ֔ם e-disseram chamem para Shimshon e Yischaque para-nós e chamaram para Shimshon de-casa-de e se zangou em-frente-de-eles e puseram com-ele entre as-colunas');
INSERT INTO verses VALUES (6977, 7, 16, 26, 'E-disse para Shimshon a o rapaz que segurava em-sua-mão deixaste meu a as-pilares que a-casa firme sobre-eles e-nos-escondeste sobre-eles');
INSERT INTO verses VALUES (6978, 7, 16, 27, 'e-a-casa enchei os-homens e-as-mulheres e-a-luz todo príncipes-de pelos-filisteus e-sobre o-teto como-três milhares homem e-a-mulher הראים בשוח שמשון׃');
INSERT INTO verses VALUES (6979, 7, 16, 28, 'E-chamou שמשון a yhwh E-disse Adonai yhwh זכרי por-favor והצignKey por-favor desta-vez הפעם o-este os-Elohim ואינקמה נקמה־ uma משתי a-vós de-flítseem:');
INSERT INTO verses VALUES (6980, 7, 16, 29, 'e-velpát shimshon a shene colunas-de ha-távek que a-casa firme sobre-eles e-samék sobre-eles um bí-yaminó e-um bí-shomálo:');
INSERT INTO verses VALUES (6981, 7, 16, 30, 'E-disse shimshon tamot נַפְשׁוֹ com פֲּלִשְׁתִּים e-ele-esticou בְּכֹחַ e-caíram a-casa sobre os-sranim e-sobre todo o-povo que nele e-foram הַמֵּתִים que הֵמִית בְּמוֹתוֹ רַבִּים do-que הֵמִית בְּחַיָּיו׃');
INSERT INTO verses VALUES (6982, 7, 16, 31, 'e-eles-desceram seus irmãos e-todo casa אָבִיהוּ ele אֹתוֹ וַֽיַּעֲלוּ וַיִּקְבְּרוּ אוֹת֗וֹ entre צָרְעָה e-entre אֶשְׁתָּאֹ֔ל בְּקֶ֖בֶר מָנ֣וֹחַ seu-pai e-ele juiz a Israel vinte anos');
INSERT INTO chapters VALUES (228, 7, 17, 13);
INSERT INTO verses VALUES (6983, 7, 17, 1, 'e-foi homem [וּשְׁמ֥וֹ] [מִיכָֽיְהוּ]');
INSERT INTO verses VALUES (6984, 7, 17, 2, 'E-disse לְאִמּ֡וֹ mil e cem o prata que foi tomado a ti Alit e-também אָמַ֣רְתְּ em minhas orelhas: eis-a o prata comigo eu você tenha tomado E-disse sua-mãe bendito filhos-de a-yhwh');
INSERT INTO verses VALUES (6985, 7, 17, 3, 'e ele entrou a mil e cem E-disse sua-mãe e-ela-disse sua-mãe a-santificada santifiquei a o-ouro para יְהוָ֨ה do-meu meu-filho e-agora escultura para-ti e-agora devolveremos para-ti');
INSERT INTO verses VALUES (6986, 7, 17, 4, 'e-o-santificou a o-ouro e-tomou sua-mãe sua-mãe מאות prata ותתנהוהו לצרף WAYYAA''SEHU פסל e-houve E-foi em-casa-de Micha׃');
INSERT INTO verses VALUES (6987, 7, 17, 5, 'e-o-homem Micha a-ele casa Elohim E-fez אףוד وترפימ WAYYIMALA a mão um de-suas-edições e-foi para-ele para-o-sacerdote:');
INSERT INTO verses VALUES (6988, 7, 17, 6, 'em-os-dias aqueles não-há rei em-Israel homem o-justo nos-seus-olhos ele-fará');
INSERT INTO verses VALUES (6989, 7, 17, 7, 'e-foi rapaz pão pão Judá de-família-de Judá e-ele Levi e-ele habita nome');
INSERT INTO verses VALUES (6990, 7, 17, 8, 'E-andou o-homem do-cidade de-casa-de pão Judá para-o-morador ba-asher יִמְצָא E-veio monte-de Efraim até casa de-Miqueas para-fazer seu-caminho:');
INSERT INTO verses VALUES (6991, 7, 17, 9, 'e-foi-dito- a-ele de-Miqueas de-onde E-disse a-ele a-ele eu Eu mesmo pão pão Judá e-eu andou morar em-o-que אֶמְצָא׃');
INSERT INTO verses VALUES (6992, 7, 17, 10, 'E-disse a-ele Micheas Saba comigo e serás para-mim pai e sacerdote e-eu eu darei para ti dez prata para os tempos e prolongarás בגדים ומחיותך E-andou הלוי׃');
INSERT INTO verses VALUES (6993, 7, 17, 11, 'e-ele-consentiu o-levita para-habitar a e-houve E-foi a-ele como-um-de [מִבָּנָֽיו]');
INSERT INTO verses VALUES (6994, 7, 17, 12, '[וַיְמַלֵּ֤א] [מִיכָה֙] a mão o-levita e-foi a-ele e-houve [בְּבֵ֥ית] E-foi');
INSERT INTO verses VALUES (6995, 7, 17, 13, 'E-disse [מִיכָ֔ה] agora soube porque yhwh yhwh que porque [הַלֵּוִ֖י] para-mim');
INSERT INTO chapters VALUES (229, 7, 18, 31);
INSERT INTO verses VALUES (6996, 7, 18, 1, 'em-os-dias aqueles não-há rei em-Israel [וּבַיָּמִ֣ים] aqueles tribo-de [הַדָּנִ֞י] [מְבַקֶּשׁ־ל֤וֹ] para-ele [לָשֶׁ֔בֶת] que porque para-ele [עַד־הַיּ֥וֹם] [הַה֛וּא] até o-dia [בְּנַחֲלָֽה׃] Israel');
INSERT INTO verses VALUES (6997, 7, 18, 2, 'e-eles-enviaram filhos-de דָ֣ן ׀ מִֽמִּשְׁפַּחְתָּ֡ם cinco homens מִקְצוֹתָם֩ homens filhos-de חַ֜יִל מִצָּרְעָ֣ה וּמֵֽאֶשְׁתָּאֹ֗ל לְרַגֵּ֤ל a a-terra וּלְחָקְרָ֔הּ e-disseram a-eles ide חִקְר֣וּ a a-terra e-entroum monte-de אֶפְרַיִם até casa מִיכָ֔ה e-acamparam-se nome');
INSERT INTO verses VALUES (6998, 7, 18, 3, 'eles com casa מִיכָ֔ה e-eles reconheceram a voz o-menino הַלֵּוִ֑י וַיָּס֣וּרוּ a-ele e-disseram a-ele quem הֱבִיאֲךָ֣ הֲלֹ֔ם וּמָֽה־ tu fez em-isso ele a-você פֹֽה׃');
INSERT INTO verses VALUES (6999, 7, 18, 4, 'E-disse a-eles כָּזֹ֣ה e assim fez a-mim Mica e me fez beber e-estive a-ele a sacerdote:');
INSERT INTO verses VALUES (7000, 7, 18, 5, 'e disseram a-ele pergunta- por-favor em Elohim e saibamos se nos será possível nossa estrada que nos andando sobre-ela');
INSERT INTO verses VALUES (7001, 7, 18, 6, 'E-disse a-eles o-sacerdote ide para-paz estaremos justificados yhwh vossa estrada que andais em-ela');
INSERT INTO verses VALUES (7002, 7, 18, 7, 'e-foram cinco-de os-homens e-vieram para ganhar E viram a o-povo que no-centro-de-a-sua- יוֹשֶׁבֶת- לָבֶטַח כְּמִשְׁפַּט צִדֹנִים שׁוֹקֵ֣ט וּבֹטֵ֗חַ e-não-há מַכְלִ֨ים palavra na-terra יוֹרֵ֣שׁ עֶ֔צֶר וּרְחֹקִ֥ים eles מִצְידֹנִים וְדָבָר não-há a-eles com homem');
INSERT INTO verses VALUES (7003, 7, 18, 8, 'e-vieram a irmãos-deles [וְאֶשְׁתָּאֹ֑ל] [וַיֹּאמְר֥וּ] a-eles a-eles [מָ֥ה] que');
INSERT INTO verses VALUES (7004, 7, 18, 9, 'e-disseram ק֚וּמָה e-nos-calhemos sobre-eles que רָאִ֙ינוּ֙ a a-terra e-eis muito muito וְאַתֶּ֣ם מַחְשִׁ֔ים a תֵּעָ֣צְל֔וּ para-andar לָבֹ֖א para-possuir a a-terra');
INSERT INTO verses VALUES (7005, 7, 18, 10, 'כּוֹבַעֲכֶ֞ם תָבוֹאֻ֣ו a povo בּוֹטֵ֗חַ E-a-terra largura-de mãos porque deu-a Elohim lugar lugar que não-há nome מַחְס֔וֹר todo palavra que na-terra');
INSERT INTO verses VALUES (7006, 7, 18, 11, 'וַיִּסְעוּ de-lá mi-mishpachath הַדּוֹנִ֔י מִצְרָעָ֖ה וּמֵאֶשְׁתַּאֹ֑ל seis-de centenas-de homem cingido instrumentos-de guerra');
INSERT INTO verses VALUES (7007, 7, 18, 12, 'וַיַּעֲלוּ e acamparam-se bekiryat de-árvores בִּיְהוּדָ֑ה sobre assim קָרְאוּ לַמָּק֨וֹם o-aquele até o-dia até eis esta הִנֵּ֕ה atrás-de Quiriate Jearim');
INSERT INTO verses VALUES (7008, 7, 18, 13, 'e-atravessaram de-lá monte-de Efraim e-vieram até casa');
INSERT INTO verses VALUES (7009, 7, 18, 14, '[וַֽיַּעֲנ֞וּ] cinco-de os-homens [הַהֹלְכִים֮] [לְרַגֵּל֮] a a-terra [וַיֹּֽאמְרוּ֙] e-disseram a que [יֵ֣שׁ] porque há [אֵפ֣וֹד] estes [וּפֶ֖סֶל] [וּמַסֵּכָ֑ה] e-agora [דְּע֥וּ] [מַֽה־תַּעֲשֽׂוּ]');
INSERT INTO verses VALUES (7010, 7, 18, 15, '[וַיָּס֣וּרוּ] ali [וַיָּבֹ֛אוּ] a casa-de o-menino o-levita casa [לְשָׁלֽוֹם]');
INSERT INTO verses VALUES (7011, 7, 18, 16, 'e-seis- centenas-de homem חֲגוּרִים֙ instrumentos-de מִלְחַמְתָּ֔ם estando-plantados entrada-de a-porta que filhos de- Dan:-');
INSERT INTO verses VALUES (7012, 7, 18, 17, 'e subiram- cinco-de os-homens os que andavam- por costume- a a-terra vieram ali levaram- a a imagem- e-a o ephod- e-a as terafim∶ e-a a chapa- e-o-sacerdote ניצָב entrada-de o-portão e-seis- centenas-de o-homem o cinto- instrumentos-de A guerra:');
INSERT INTO verses VALUES (7013, 7, 18, 18, 'e-estes vieram casa מִיכָ֔ה e-eles-levaram a פֶּ֣סֶל הָאֵפ֔וֹד e-a E-disse e-a הַמַּסֵּכָ֑ה E-disse a-eles o-sacerdote que vós עֹשִֽׂים׃');
INSERT INTO verses VALUES (7014, 7, 18, 19, 'וַיֹּ֩אמְרוּ֩ a-ele הַחֲרֵ֜שׁ põe- יָדְךָ֤ sobre boca-tua e-vaia conosco-s וֶֽהְיֵה־ para-nós לְאָ֣ב וּלְכֹהֵ֑ן הֲטוֹב הֱיֹתְךָ sacerdote um homem um ou הֱיֹתְךָ sacerdote לְשׁוֹבֶט וּלְמִשְׁפַּחָה em-Israel');
INSERT INTO verses VALUES (7015, 7, 18, 20, 'e-foi-bom coração o-sacerdote E-tomou a [וְאֶת־הַתְּרָפִ֖ים] e-[OBJ] [וַיָּבֹ֖א] e-[OBJ] [הָעָֽם] E-veio');
INSERT INTO verses VALUES (7016, 7, 18, 21, '[וַיִּפְנ֖וּ] e-foram [וַיָּשִׂ֨ימוּ] a [וְאֶת־הַמִּקְנֶ֛ה] e-[OBJ] [לִפְנֵיהֶֽם] e-[OBJ]');
INSERT INTO verses VALUES (7017, 7, 18, 22, 'eles [הִרְחִ֖יקוּ] de-casa-de [מִיכָ֑ה] e-os-homens que [בַּבָּתִּים֙] que com casa [נִֽזְעֲק֔וּ] [וַיַּדְבִּ֖יקוּ] [אֶת־בְּנֵי־דָֽן] a');
INSERT INTO verses VALUES (7018, 7, 18, 23, '[וַֽיִּקְרְאוּ֙] a filhos-de Dã [וַיֹּאמְר֣וּ] [לְמִיכָ֔ה] e-disseram que que porque');
INSERT INTO verses VALUES (7019, 7, 18, 24, 'E-disse a Elohim-vos que faizest-vos levastes-vos e-a o-sacerdote e-vos e-que para-mim ainda ele זֹה dizeis-vós para-mim que- para-ti');
INSERT INTO verses VALUES (7020, 7, 18, 25, 'e-disseram a-ele filhos-de Dã a ouvireis-vós vossa-voz com-nosso para-que-não farão-vos em-vós homens amarres alma e arrepliaria alma-tua e-alma em teu lar:');
INSERT INTO verses VALUES (7021, 7, 18, 26, 'e-caminharam filhos-de Dan E-viu E-viu Micaías porque nós eles dele e-virou-se e-voltou a casa-dele');
INSERT INTO verses VALUES (7022, 7, 18, 27, 'e seriam tomaram com que fez Micaías e-a o sacerdote que ha-yah- para-ele e-vieram sobre para o israelita sobre povo que repousa e confia e-eles-feriram eles à-boca-de espada e-a a-cidade e-eles-queimaram em-o-fogo');
INSERT INTO verses VALUES (7023, 7, 18, 28, 'e não há מַצִּיל que רְחֹקָה- ela מִצִּידֹון וְדָבָר não-há para-eles com homem וְהִיא em-o-vale que para-casa-de רְחֹב וַיִּבְנוּ a a-cidade e-habitaram em-ela');
INSERT INTO verses VALUES (7024, 7, 18, 29, 'e-eles-chamaram nome-de a-cidade דן בְּשֵׁם֙ דָּן pai-deles que יוּלַד לְיִשְׂרָאֵ֑ל e-no entanto לַיִשׁ nome-de a-cidade para-o-primeiro:');
INSERT INTO verses VALUES (7025, 7, 18, 30, 'e ergueram a-eles filhos-de Dan a o-pêsel e-jehonatan ele gershom filho-de ele e-seus-filhos eram kohanim para-tribo a-terra até dia גְּל֥וֹת a-terra');
INSERT INTO verses VALUES (7026, 7, 18, 31, 'e-puseram a-eles a pêsel mica que fez estar dias הֱי֥וֹת casa-de Elohim em-Silo');
INSERT INTO chapters VALUES (230, 7, 19, 30);
INSERT INTO verses VALUES (7027, 7, 19, 1, 'e-houve em-os-dias aqueles וּמֶ֖לֶךְ não-há em-Israel e-houve homem לֵוִ֗י גָּ֚ר בְּיַרְכְּתֵ֣י monte-de Efraim e-tomou a-ele mulher פִילֶ֔גֶשׁ pão pao Judá');
INSERT INTO verses VALUES (7028, 7, 19, 2, 'וַתִּזְנֶ֤ה sobre-ele פִּֽילַגְשׁ֔וֹ e-foi מֵֽאִתּוֹ֙ a casa seu-pai pão casa pao Judá quatro nome dias quatro meses');
INSERT INTO verses VALUES (7029, 7, 19, 3, 'E-levantou marido-dela E-andou אַחֲרֶ֗יהָ para-falar sobre לִבָּהּ֙ e seu servo com-ele e o yôm cavalos e trouxe-o casa seu-pai e viu-o pai-de a-moça e alegrou-se com sua chegada');
INSERT INTO verses VALUES (7030, 7, 19, 4, 'e fortaleceu-se nele seu cunhado pai-de a-moça e-habitou com-ele três-de dias e comeram e-eles-beberam e-acamparam-se nome');
INSERT INTO verses VALUES (7031, 7, 19, 5, 'e-houve no-dia o-quarto e se levantaram no-bom-dia E-levantou para-andar E-disse pai a-narazinha a no-cunhado Sad no-seu-coração pedaço-de pão e-depois ireis');
INSERT INTO verses VALUES (7032, 7, 19, 6, 'e sentaram-se e comeram os-dois juntos e comeu E-disse abí- a moça a o-homem e-ol agora e lin e teve לִבֶּֽךָ');
INSERT INTO verses VALUES (7033, 7, 19, 7, 'E-levantou o homem para-andar e-ele-precipitar-se em-ele seu cunhado e voltou e desfaleceu nome');
INSERT INTO verses VALUES (7034, 7, 19, 8, 'e-ele-se-levantou na-manhã no-dia o quinto para andar E-disse pai-de a moça Saúd- por-favor para-o-teu-coração e se maravilhem até o-dia o-dia e-eles- comeram dois-deles');
INSERT INTO verses VALUES (7035, 7, 19, 9, 'E-levantou o-homem לָלֶךֶת ele e sua concubina e seu servo E-disse a-ele seu sogro pai-de a moça eis por-favor deitou-se o-dia no arborio Lino- eis eis o-dia o-dia linho aqui וְיִיטַ֣ב teu-coração וְהִשְׁכַּמְתֶּ֤ם amanhã לְדַרְכְּכֶ֔ם וְהָלַכְתָּ֖ לְאֹהָלֶֽךָ׃');
INSERT INTO verses VALUES (7036, 7, 19, 10, 'e-não [הָאִישׁ֙] o-homem [וַיָּ֣קָם] E-levantou E-andou E-veio até [הִ֖יא] [יְרוּשָׁלָ֑͏ִם] ela Jerusalém [חֲמוֹרִים֙] [חֲבוּשִׁ֔ים] [וּפִילַגְשׁ֖וֹ] [עִמּֽוֹ]');
INSERT INTO verses VALUES (7037, 7, 19, 11, 'eles com [וְהַיּ֖וֹם] [רַ֣ד] muito E-disse E-disse [אֶל־אֲדֹנָ֗יו] a [וְנָס֛וּרָה] [אֶל־עִֽיר־הַיְבוּסִ֥י] [הַזֹּ֖את] [וְנָלִ֥ין] a');
INSERT INTO verses VALUES (7038, 7, 19, 12, 'E-disse a-ele seu-senhor não naser a cidade nachri que não de-filhos-de Israel aqui-estes וְעָבַ֖רְnoּ até giva');
INSERT INTO verses VALUES (7039, 7, 19, 13, 'E-disse a-jovem-dele a-ti e se aproximou em um as lugares e para ele na montanha ou em Ramá:');
INSERT INTO verses VALUES (7040, 7, 19, 14, 'e passaram-se e-foram e-ela-veio a-eles o-sol ao-lado-de a montanha que para Benjamim:');
INSERT INTO verses VALUES (7041, 7, 19, 15, 'e foram trazidos nome para-vir para o luto em-Gibeá E-veio e-habitou no meio da cidade a-cidade e-não-há homem מאסף- אותם הביתה para-aquilo');
INSERT INTO verses VALUES (7042, 7, 19, 16, 'והנה homem זקן veio de מעשהו de o-campo na-atardecer והאיש de-montanha-de Efraim ve-hu- גר em-Gibeá ואנשי o-lugar filhos-de benjamita');
INSERT INTO verses VALUES (7043, 7, 19, 17, 'e levantou os-seus-olhos E-viu a o-homem האורח ברחוב E-disse E-disse האיש הזקן andarás תלך ומעין תבא׃');
INSERT INTO verses VALUES (7044, 7, 19, 18, 'E-disse a-ele [עֹבְרִ֨ים] [אֲנַ֜חְנוּ] [מִבֵּֽית־לֶ֣חֶם] pão [עַד־יַרְכְּתֵ֣י] até [מִשָּׁ֣ם] eu [וָאֵלֵ֕ךְ] de-lá pão [יְהוּדָ֑ה] até yhwh pão Judá e-[OBJ] casa yhwh eu andou homem');
INSERT INTO verses VALUES (7045, 7, 19, 19, 'e-também pedra também מספוא há pão e-tambem pão WAYYAYIN há a-mim ואלאמתך ואלנער com servos-teus não מחסור todo palavra');
INSERT INTO verses VALUES (7046, 7, 19, 20, 'E-disse o-homem [הַזָּקֵן֙] [שָׁל֣וֹם] para-ti somente todo [עָלָ֑י] [רַ֥ק] somente [אַל־תָּלַֽן] a');
INSERT INTO verses VALUES (7047, 7, 19, 21, 'וַיְבִיאֵ֣הוּ para-a-sua-casa וַיָּ֖בָול לַחֲמוֹרִ֑ים וַֽיִּרְחֲצוּ֙ רַגְלֵיהֶ֔ם e comeram e beberam:');
INSERT INTO verses VALUES (7048, 7, 19, 22, '[הֵמָּה֮] [מֵיטִיבִ֣ים] a [וְהִנֵּה֩] e-eis homens-de a-cidade homens-de filhos-de [אֶת־הַבַּ֔יִת] [מִֽתְדַּפְּקִ֖ים] a a-casa [אֶל־הָ֠אִישׁ] sobre [הַבַּ֤יִת] e-disseram dizendo [הוֹצֵ֗א] בַּ֣עַל a-casa [אֶל־בֵּיתְךָ֖] dizendo a que veio a');
INSERT INTO verses VALUES (7049, 7, 19, 23, 'e-saiu a-eles o-homem בַּ֣עַל a-casa E-disse a-eles a meus-irmãos a תרועוּ נָ֑א depois-de que veio o-homem o-este a em-o-casa a farão a הנבלה a esta');
INSERT INTO verses VALUES (7050, 7, 19, 24, 'eis filha a virgem e a concubina dele tirei- agora a-eles e sejam feitas a-eles a-eles a-eles o-bom em-os-vossos-olhos e para o homem não não fareis palavra a profanação a esta');
INSERT INTO verses VALUES (7051, 7, 19, 25, 'e-não e conceberam os-homens a-ele a-ele e se fortaleceu o-homem em sua concubina e-saiu a-eles e-souberam e conheciam אֵ֠ת הַזֹּאת וַיִּתְעַלְּלוּ־ בָ֤הּ todo a-noite até a-manhã וַיְשַׁלֵּחֶהָ o amanhecer:');
INSERT INTO verses VALUES (7052, 7, 19, 26, 'וַתָּבוֹא a-mulher לִפְנֹות הַבָּקֵ֑ר וַתִּפֹּל פֶּתַח casa-de o-homem que אֲדֹנָ֥יו nome até a luz:');
INSERT INTO verses VALUES (7053, 7, 19, 27, 'E-levantou sua senhora na-manhã e abriu-se-lhe portas-de a-casa e-ele-saiu para-andar em sua jornada e-eis a-mulher sua concubina caída entrada-de a-casa e suas mãos sobre o véu:');
INSERT INTO verses VALUES (7054, 7, 19, 28, 'E-disse a-ela arrie e vamos e-não-há que-escute e tomou-a sobre o-jumento E-levantou o-homem E-andou para-lugar-dele');
INSERT INTO verses VALUES (7055, 7, 19, 29, 'E-veio a E-tomou E-tomou a a que come e fortaleceu-se em sua concubina e a cortou em seus ossos לִשְׁנֵ֥ים dez ossos e enviou-a em-todo fronteira-de Israel');
INSERT INTO verses VALUES (7056, 7, 19, 30, 'e-foi todo aquele que vê e-ele-disse não ficou e-não viu-se Assim até o dia subir até o-dia da-terra Egito até o-dia esta porventura para-vós sobre-ela fortaleçam-se e falam');
INSERT INTO chapters VALUES (231, 7, 20, 48);
INSERT INTO verses VALUES (7057, 7, 20, 1, 'e saíram todo filhos-de Israel e reuniu-se a-congregação um um para julgamento e-até poço sete e a terra o-gileade a yhwh a manifestação׃');
INSERT INTO verses VALUES (7058, 7, 20, 2, 'e se postaram as narinas todo o povo todo tribos-de Israel no convés povo o-Elohim quatro centenas mil homem minha perna que tirou espada');
INSERT INTO verses VALUES (7059, 7, 20, 3, 'e ouviram filhos-de Benjamim porque subiram filhos-de Israel a manifestação e-disseram filhos-de Israel disseram como tornou-se a-maldade a esta');
INSERT INTO verses VALUES (7060, 7, 20, 4, 'e respondeu o-homem הַלֵּוִ֗י homem a-mulher a vingada E-disse as colinas que a Benjamim que veio eu e a concubina para-aquilo');
INSERT INTO verses VALUES (7061, 7, 20, 5, 'e-eles-se-levantaram sobre-mim aos chefes das colinas e-viraram-se sobre-mim a noite noite a-mim e deram para matar e-a פִּילַגְשִׁ֥י עִנּ֖וּ וַתָּמֹֽת׃');
INSERT INTO verses VALUES (7062, 7, 20, 6, 'וָֽאֹחֵ֤ז בְּפִֽילַגְשִׁי֙ וָֽאֲנַתְּחֶ֔הָ וֽ͏ָאֲשַׁלְּחֶ֔הָ em-todo os-campos נַחֲלַ֣ת que porque o-fez-e zimah וּנְבָלָ֖ה em-Israel');
INSERT INTO verses VALUES (7063, 7, 20, 7, 'eis כֻלְּכֶ֖ם filhos-de Israel dai a-vós palavra וְעֵצָ֖ה וְהִנֵּה׃');
INSERT INTO verses VALUES (7064, 7, 20, 8, 'E-levantou todo o-povo um dizendo não não [אִ֣ישׁ] homem [וְלֹ֥א] e-não [אִ֥ישׁ] homem');
INSERT INTO verses VALUES (7065, 7, 20, 9, 'e-agora este a-palavra que נַעֲשֶׂה לַגּוֹבֵעָ֑ה sobre-ela בְּגוֹרָל׃');
INSERT INTO verses VALUES (7066, 7, 20, 10, 'וְלָקַחְנוּ עֲשָׂרָה֩ homens לְמֵאָה a-todo tribos-de Israel e cem para mil e um milhar para muitos tomar justiça para-o-povo לַעֲשׂ֗וֹת para Bovo para Geba בִּנְיָמִן conforme-toda a Nabal que fez em-Israel');
INSERT INTO verses VALUES (7067, 7, 20, 11, 'e foi reunido todo homem Israel a um como-homem um companheiros:');
INSERT INTO verses VALUES (7068, 7, 20, 12, 'e enviaram tribos Israel homens em-todo tribos-de dizendo dizendo quanto a má esta que tornou-se em-vos:');
INSERT INTO verses VALUES (7069, 7, 20, 13, 'e-agora dai-vos a os-homens filhos-de בְלִיַּ֜עַל que na-GBa''a e matareis-vos e queimareis maldade de-Israel e-não e-ABu בִּנְיָמִן para-ouvir בְּקוֹל אֲחַיֶּהָ filhos-de Israel');
INSERT INTO verses VALUES (7070, 7, 20, 14, 'וַיֵּאָסְפוּ filhos-de בִּנְיָמִין de as-cidades הַגּוֹבְעָתָה לָצֵאת para-a-guerra com filhos-de Israel');
INSERT INTO verses VALUES (7071, 7, 20, 15, 'וַיִּתְפַּקְדּוּ filhos-de בִּנְיָמִין no-dia o-aquele מֵהֶעָרִים vinte e-seis mil homem desembainhando espada para-fora מִיּוֹשְׁבֵי a gíbua se dispuseram sete centenas homem o moço:');
INSERT INTO verses VALUES (7072, 7, 20, 16, 'de-toda o-povo este sete novecentos homem moço fechado mão-de direita-de-ele todo este quebra em pedra a a rocha e-não pecará:');
INSERT INTO verses VALUES (7073, 7, 20, 17, 'e-homem Israel se dispuseram só de-Benjamin quatro centenas mil homem desembainhando espada todo este homem guerra');
INSERT INTO verses VALUES (7074, 7, 20, 18, 'e se levantaram e-subiram casa-de El e perguntaram em elohim e-disseram filhos-de quem quem subirá- para-nós no princípio para-a-guerra E-disse yhwh Benjamim E-disse yhwh um no princípio;');
INSERT INTO verses VALUES (7075, 7, 20, 19, 'e se levantaram filhos-de Israel no-manhã e acamparam-se sobre a montanha;');
INSERT INTO verses VALUES (7076, 7, 20, 20, 'e-saiu homem Israel para-a-guerra com Binyamin e-dispuseram-se com eles homem-de Israel guerra a a montanha;');
INSERT INTO verses VALUES (7077, 7, 20, 21, 'e-saíram filhos-de Benjamim de a-guerra no-dia em-israel no-dia aquele dois e-vinte mil homem para-terra');
INSERT INTO verses VALUES (7078, 7, 20, 22, 'e-aumentaram-se o-povo homem Israel e-adicionaram para-longo guerra no lugar que prepararam no-dia no-dia o-primeiro:');
INSERT INTO verses VALUES (7079, 7, 20, 23, 'e-subiram filhos-de Israel e-choraram diante-de- yhwh até dizendo e-pediram em-יהוה dizendo o-que-sobraria LAGESHET para-a-guerra E-disse yhwh Benjamim a-ele E-disse yhwh ALU a-ele');
INSERT INTO verses VALUES (7080, 7, 20, 24, 'VAHIQREBU filhos-de Israel a no-dia Benjamim no-dia o-segundo');
INSERT INTO verses VALUES (7081, 7, 20, 25, 'e-saiu BINYAMIN LIKRAATAM de HAGIVeah no-dia no-dia VAHASCHITU BIBNEI Israel ainda SHMONAT dez mil homem terra todo estes SHOLEFAY espada');
INSERT INTO verses VALUES (7082, 7, 20, 26, 'e-subiram todo filhos-de Israel e-todo o-povo e-vieram casa-de El e choraram yhwh nome diante-de yhwh e fizeram jejum no-dia-de aquele até yhwh e subiram holocaustos e holocaustos diante-de yhwh');
INSERT INTO verses VALUES (7083, 7, 20, 27, 'e perguntaram filhos-de Israel em-יהוה e ali arca-de aliança o-Elohim em-os-dias ha-hem');
INSERT INTO verses VALUES (7084, 7, 20, 28, 'e Pinhas filho-de Elazar filho-de Arão estando diante-dele em-os-dias dizendo dizendo o que arrecadar ainda para sair para-a-guerra com filhos-de E-disse yhwh se que E-disse yhwh subam porque dizendo eu lhe darei em tua mão:');
INSERT INTO verses VALUES (7085, 7, 20, 29, 'e-ele-colocou Israel arautos a a colina ao-redor');
INSERT INTO verses VALUES (7086, 7, 20, 30, 'e-subiram filhos-de Israel a no-dia Benjamim no-dia o terceiro e-ele-arranjaram a a colina vez em vez');
INSERT INTO verses VALUES (7087, 7, 20, 31, 'e-eles-saíram filhos-de Benjamim ao-encontro-de o-povo הנתתקו de a-cidade ויחלוּ להכות מעם חללים כפעהם בפעהם במסילות uma אחת holocausto casa-de El e-uma גבעתא no-campo trinta homem em-Israel');
INSERT INTO verses VALUES (7088, 7, 20, 32, 'e-disseram filhos-de Benjamim נִגָּפִים eles diante-nos כְּבָרִאשֹׁנָ֑ה e-filhos-de Israel אָמְר֗וּ נָנ֙וּסָה֙ וּֽנְתַקְּנֻ֔הוּ de a-cidade a הַֽמְסִלּֽוֹת׃');
INSERT INTO verses VALUES (7089, 7, 20, 33, 'e-tudo homem Israel קָ֚מוּ מִמְּקוֹמ֔וֹ וַיַּעַרְכ֖וּ em-Baal תָּמָ֑ר וְאֹרֵ֧ב Israel מֵגִ֥יחַ מִמְּקֹמ֖וֹ גָֽבַע׃');
INSERT INTO verses VALUES (7090, 7, 20, 34, 'e-ele-chegou מִנֶּ֨גֶד לַגִּבְעָ֜ה עֲשֶׂרֶת֩ אֲלָפִ֨ים homem בָּחוּר֙ de-todo Israel וְהַמִּלְחָמָ֖ה căbêdâ não não conheceram porque nôgât sobre-eles hărâ''â');
INSERT INTO verses VALUES (7091, 7, 20, 35, 'vayiggâph yhwh a binnêyâmîn diante-de Israel vayishchitû filhos-de Israel babbinnêyâmîn no-dia aquele vinte ve-chamisha mil e-cem homem todo estes shôlê''ef espada');
INSERT INTO verses VALUES (7092, 7, 20, 36, 'e-eles-deram-conta filhos-de que porque niggâfu va-yittenu lugar Israel que lebinnêyâmîn porque בָֽטְחוּ֙ a הָ֣אֹרֵ֔ב שָׂ֖moּ a הַגִּבְעָֽה׃');
INSERT INTO verses VALUES (7093, 7, 20, 37, '[וְהָאֹרֵ֣ב] [הֵחִ֔ישׁוּ] [וַֽיִּפְשְׁט֖וּ] a [וַיִּמְשֹׁךְ֙] [הָאֹרֵ֔ב] [וַיַּ֥ךְ] e-feriu a todo');
INSERT INTO verses VALUES (7094, 7, 20, 38, 'וְהַמּוֹעֵ֗ed ser para-um Israel com o-arrebatador a-partilha para-elevá-los transporte a-fumaça de a-cidade');
INSERT INTO verses VALUES (7095, 7, 20, 39, 'e-virou-se homem-de Israel em-batalha e-venezuelano começou-a para matar mortos em-homem- Israel que homem porque disseram só-que ele foi-afligida ele diante-de-nós como-guerra a-primeira:');
INSERT INTO verses VALUES (7096, 7, 20, 40, 'e-a-carga ela-começou a-subir de a-cidade piléster em-ás e-voltou-se benjamita apos-ele subir subiu כְלִיל־ a-cidade הַשָׁמָֽיְמָה׃');
INSERT INTO verses VALUES (7097, 7, 20, 41, 'e-homem Israel revolver וַיִבָּהֵ֖ל homem Binyamin que ver porque נָגְעָ֥ה sobre-ele הָרָעָֽה׃');
INSERT INTO verses VALUES (7098, 7, 20, 42, 'וַיִּפְנ֞וּ diante-de homem Israel a caminho o-deserto וְהַמִּלְחָמָ֖ה הִדְבִּיקָ֑תְהוּ וַאֲשֶׁר֙ מֵהֶ֣עָרִ֔ים מַשְׁחִיתִ֥ים com-ele no seu');
INSERT INTO verses VALUES (7099, 7, 20, 43, 'escrevam a benjamita perseguí-lo descanso até até porque a montanha do oriente- do-sol');
INSERT INTO verses VALUES (7100, 7, 20, 44, 'e caíram de-Benjamin oito- dez mil homem a todo estes homens de força');
INSERT INTO verses VALUES (7101, 7, 20, 45, 'e se aproximaram e levantaram-se o-deserto-para a pedra Hermom e quebraram-no em pedaços cinco-de milhares homem e espetaram-no depois-dele até nós e-eles-feriram dele será homem');
INSERT INTO verses VALUES (7102, 7, 20, 46, 'e-houve todo os caídos de Benjamim vinte e cinco mil homem espada no-dia no-dia aquele a todo estes homens de força');
INSERT INTO verses VALUES (7103, 7, 20, 47, 'e se apresentaram e levantaram-se o-deserto-para a rocha Hermom seis centenas homem e assentaram-se na rocha quatro quatro meses');
INSERT INTO verses VALUES (7104, 7, 20, 48, 'e-homem Israel voltaram a filhos-de Benjamim e deram-lhes à-boca-de espada de-cidade-de até animal também todo o encontrado também todo as-cidades os encontrados puseram em-o-fogo');
INSERT INTO chapters VALUES (232, 7, 21, 25);
INSERT INTO verses VALUES (7105, 7, 21, 1, 'e-homem Israel jurou em Matfá dizendo homem nós não dará filha-dele para Benjamim para-mulher');
INSERT INTO verses VALUES (7106, 7, 21, 2, 'E-veio o-povo casa-de El e-permaneceram nome até no-crepúsculo diante-de o-Elohim e-tomaram seu som e-choraram porque grande');
INSERT INTO verses VALUES (7107, 7, 21, 3, 'e-disseram por que yhwh Elohim-de Israel era zot em-Israel para ser julgado o-dia de Israel bastão um');
INSERT INTO verses VALUES (7108, 7, 21, 4, 'e-houve de-amanhã e-eles-se-levantaram-cedo o-povo e construíram nome מִזְבֵּ֑חַ e-eles-subiram holocaustos ushlaimim-');
INSERT INTO verses VALUES (7109, 7, 21, 5, 'e-disseram filhos-de Israel quem que não subiram no convés de-todo tribos-de que a yhwh era a juramento a grande foi para aquele dizendo morrendo a yhwh a montanha para-dizer morrer será-morto');
INSERT INTO verses VALUES (7110, 7, 21, 6, 'e se acalmaram filhos-de Israel a Benjamim irmão-dele e-disseram o-dia o-dia um um מִיִּשְׂרָאֵֽל׃');
INSERT INTO verses VALUES (7111, 7, 21, 7, 'que a-eles a-eles aos sobreviventes para as mulheres e-nós juramos para-não sem dar a-eles das nossas filhas para-nas-mulheres:');
INSERT INTO verses VALUES (7112, 7, 21, 8, 'e-disseram quem um de-tribos-de Israel que não subiu a yhwh não e-eis não veio homem a a-câmera do-deserto Gileade a o povo');
INSERT INTO verses VALUES (7113, 7, 21, 9, 'e-estabeleceu-se-em o-povo e-eis não-há nome homem dos-habitantes-de deserto gil-ad');
INSERT INTO verses VALUES (7114, 7, 21, 10, 'e-enviaram- nome a congregação doze dez mil homem de-filhos-de הֶחָיִל dizendo a-eles dizendo vão-vós e-golpeareis a yošbé'' יָבֵ֤שׁ Gil''ad à-boca-de espada e-as-mulheres e-as-crianças');
INSERT INTO verses VALUES (7115, 7, 21, 11, 'e-esta a palavra que fazeis-vós todo macho e-todo mulher Yodáat Mishkab- macho Taḥaríimu∶');
INSERT INTO verses VALUES (7116, 7, 21, 12, 'Va''yimméts''e''u Miyyoshvéi ％ Jabes Gilade quatro novecentos jovem virgem que não Yadá''ah homem Lemishkab macho Va''yaví''u os a o-acampamento Siló que em-terra-de כְּנָֽעַן');
INSERT INTO verses VALUES (7117, 7, 21, 13, 'e-enviaram todo a-congregação Va''yédabbré''u a filhos-de Benjamim que em-pedro a-eles e-cham-los a-eles paz');
INSERT INTO verses VALUES (7118, 7, 21, 14, 'e-ele-retornou benjamita em-o-tempo aquela e-eles-deram a-eles as-mulheres que respiraram dos-dentes secou-se Galaad e-não a-eles a-eles assim');
INSERT INTO verses VALUES (7119, 7, 21, 15, 'e-o-povo consolaram-se a-leviãmen porque yhwh yhwh פֶּרֶץ [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (7120, 7, 21, 16, 'e-disseram-que anciaos-de a-congregação que fazemos-nos para os noutarim para as nashim porque nismodah de Benjamim mulher');
INSERT INTO verses VALUES (7121, 7, 21, 17, 'e-disseram herança refúgio para Benjamim e-não será apagado shevet מִיִּשְׂרָאֵֽל׃');
INSERT INTO verses VALUES (7122, 7, 21, 18, 'e nós não podemos dar- a-eles mulheres de-nossas porque dizendo maldito Israel dizendo maldito deu mulher para-Benjamin:');
INSERT INTO verses VALUES (7123, 7, 21, 19, 'disseram- eis festa- yhwh em-Siló de-dias por-dias que do-norte para-a-casa-de El do-leste o-sol para-imitação a queimada do-o El Siquém e do-sudeste até-Líbano');
INSERT INTO verses VALUES (7124, 7, 21, 20, 'a filhos-de Benjamim dizendo dizendo e floresceram nas vinhas');
INSERT INTO verses VALUES (7125, 7, 21, 21, 'e-vistes e-eis se saíram filhas-de Siló lapsaram em-lhes e-saiam a-vós os-carmelitas e-arrebenta-los-vós a-vós homem mulher-sua terra Siloa e-andareis terra Benjamin');
INSERT INTO verses VALUES (7126, 7, 21, 22, 'e-será porque virao seus-pai ou seus-irmãos a-nos e-dizemos-nós a-eles חָנּוּנוּ a-eles porque não que não mulher-sua בַּמִּלְחָמָ֑ה porque não que não a-eles agora a-eles');
INSERT INTO verses VALUES (7127, 7, 21, 23, 'e-ele-fizeram- assim filhos-de Benjamim וַיִּשְׂא֤וּ mulheres לְמִסְפָּרָ֔ם de הַמְּחֹלְל֖וֹת que גָּזָ֑לוּ e-foram וַיָּשׁ֙וּבוּ֙ a נַ֣חֲלָתָ֔ם e-construíram a as-cidades e-habitaram neles');
INSERT INTO verses VALUES (7128, 7, 21, 24, 'וַיִּתְהַלְּכ֨וּ de-aqui filhos-de Israel em-o-tempo aquela homem לְשִׁבְט֖וֹ וּלְמִשְׁפַּחְתּ֑וֹ e-eles-saíram de-lá homem para-sua-inheritance');
INSERT INTO verses VALUES (7129, 7, 21, 25, 'em-os-dias aqueles não-há rei em-Israel homem the-just em-suas-olhos ele-fará');
INSERT INTO books VALUES (8, 'RUT', 'Rute', 'AT', 4);
INSERT INTO chapters VALUES (233, 8, 1, 22);
INSERT INTO verses VALUES (7130, 8, 1, 1, 'e-houve em-os-dias-de julgar os-juízes e-houve fome em-a-terra E-andou homem de-casa-de pão Judá para-habitar em-campos-de Moabe ele e-esposa-dele e-dois-de filhos-dele');
INSERT INTO verses VALUES (7131, 8, 1, 2, 'e-nome-de o-homem Elimelech e-nome-de esposa-dele Naomi e-nome-de dois filhos-dele Mahlon e-Quilion efratitas de-casa-de pão Judá e-vieram campos-de Moabe e-foram nome');
INSERT INTO verses VALUES (7132, 8, 1, 3, 'E-morreu Elimelech homem Naomi e-restou ela e-dois-de filhos-dela');
INSERT INTO verses VALUES (7133, 8, 1, 4, 'e-tomaram a-eles mulheres moabitas nome a-uma Orfa e-nome-de a-segunda Rute e-habitaram nome como-dez dois');
INSERT INTO verses VALUES (7134, 8, 1, 5, 'e-morreram também dois-deles Mahlon e-Quilion e-restou a-mulher de-dois-de filhos-dela e-de-marido-dela');
INSERT INTO verses VALUES (7135, 8, 1, 6, 'e-levantou-se ela e-noras-dela e-retornou de-campos-de Moabe que ouviu em-campo-de Moabe porque yhwh yhwh a a-eles a-dar a-eles pão');
INSERT INTO verses VALUES (7136, 8, 1, 7, 'e-saiu de o-lugar que estava ali com-ela noras-dela com-ela e-andaram no-caminho para-retornar a terra Judá');
INSERT INTO verses VALUES (7137, 8, 1, 8, 'E-disse Naomi para-duas-de noras-dela ide voltai mulher para-casa-de mãe-dela yhwh com-vós yhwh como-que fizestes com os-mortos e-comigo');
INSERT INTO verses VALUES (7138, 8, 1, 9, 'dará yhwh a-vós e-acheis descanso mulher casa marido-dela e-beijou a-elas e-levantaram voz-delas e-choraram');
INSERT INTO verses VALUES (7139, 8, 1, 10, 'e-disseram a-ela porque contigo retornaremos para-povo-teu');
INSERT INTO verses VALUES (7140, 8, 1, 11, 'E-disse Naomi voltai filhas-minhas por-que ireis comigo há-ainda filhos filhos e-sejam a-vós para-vocês para-homens');
INSERT INTO verses VALUES (7141, 8, 1, 12, 'voltai filhas-minhas ide que envelheci de-ser para-homem que dissesse há a-mim também também estive a-noite para-homem e-também filhos filhos');
INSERT INTO verses VALUES (7142, 8, 1, 13, 'acaso-para-elas esperareis até até crescerão acaso-para-elas vos-detereis para-não para-não estar El filhas-minhas porque amargo muito muito de-vós porque saiu em-mim mão-de yhwh');
INSERT INTO verses VALUES (7143, 8, 1, 14, 'e-levantaram voz-delas e-choraram ainda e-beijou Orfa para-sogra-dela e-Rute apegou-se nela');
INSERT INTO verses VALUES (7144, 8, 1, 15, 'E-disse eis voltou cunhada-tua a povo-dela e-a Elohim-dela volta atrás-de cunhada-tua');
INSERT INTO verses VALUES (7145, 8, 1, 16, 'E-disse Rute a insistas em-mim para-deixar-te que de-atrás-de-ti porque a que irás irei e-em-onde pernoitares pernoitarei povo-teu povo-meu e-Elohim-teu Elohim-meu');
INSERT INTO verses VALUES (7146, 8, 1, 17, 'em-onde morreres morrerei e-ali serei-sepultada assim fará yhwh a-mim e-assim acrescentará que a-morte separará entre-mim e-entre-ti');
INSERT INTO verses VALUES (7147, 8, 1, 18, 'E-viu porque estava-determinada ela para-andar com-ela e-cessou de-falar a-ela');
INSERT INTO verses VALUES (7148, 8, 1, 19, 'e-andaram duas-delas até chegaram casa e-houve E-foi quando-chegaram pão Belém e-agitou-se todo a-cidade sobre-eles e-disseram esta Noemi');
INSERT INTO verses VALUES (7149, 8, 1, 20, 'E-disse a-elas a chameis para-mim Noemi chamai a-mim Mara porque fez-amargo muito para-mim muito');
INSERT INTO verses VALUES (7150, 8, 1, 21, 'eu cheia fui e-vazia me-trouxe-de-volta yhwh por-que aconteçam a-mim Noemi e-יהוה testificou em-mim e-Shadai fez-mal para-mim');
INSERT INTO verses VALUES (7151, 8, 1, 22, 'e-voltou Noemi e-Rute a-moabita nora-dela com-ela a-que-voltou de-campos-de Moabe e-elas vieram casa pão no-início-de ceifa-de cevada');
INSERT INTO chapters VALUES (234, 8, 2, 23);
INSERT INTO verses VALUES (7152, 8, 2, 1, 'e-para-Noemi para-marido-dela homem homem valente de-família-de אֱלִימֶלֶךְ e-nome-dele בֹּעַז');
INSERT INTO verses VALUES (7153, 8, 2, 2, 'E-disse ר֨וּת a-moabita a נָעֳמִי irei agora o-campo e-respigo em-as-espigas atrás-de que E-disse graça em-olhos-dele e-disse para-ela vai filha-minha');
INSERT INTO verses VALUES (7154, 8, 2, 3, 'e-foi e-veio e-respigou no-campo atrás-de os-ceifadores e-aconteceu acaso-dela porção-de o-campo de-בֹעַז que de-família-de אֱלִימֶלֶךְ');
INSERT INTO verses VALUES (7155, 8, 2, 4, 'e-eis- בֹעַז veio pão E-disse E-disse yhwh yhwh com-vós a-ele para-ele yhwh yhwh');
INSERT INTO verses VALUES (7156, 8, 2, 5, 'E-disse בֹעַז a-jovem-dele o-posto sobre os-ceifadores de-quem a-jovem a esta');
INSERT INTO verses VALUES (7157, 8, 2, 6, 'e-respondeu o-jovem o-posto sobre os-ceifadores E-disse jovem moabita ela a-que-retornou com נָעֳמִי de-campo-de Moabe');
INSERT INTO verses VALUES (7158, 8, 2, 7, 'E-disse respigo agora e-ajunto em-os-feixes atrás-de os-ceifadores e-veio e-ficou-em-pé desde a-manhã e-até até-agora este sentar-dela a-casa pouco');
INSERT INTO verses VALUES (7159, 8, 2, 8, 'E-disse בֹעַז a ר֜וּת não ouviste filha-minha a vás para-respigar em-campo não e-também não passes deste e-assim te-apegarás com jovens-minhas');
INSERT INTO verses VALUES (7160, 8, 2, 9, 'olhos-teus no-campo que ceifam e-andaste atrás-delas não ordenei para-não os-jovens para-não tocar-te e-tiveres-sede e-irás a os-vasos e-beberás do-que tiram os-jovens');
INSERT INTO verses VALUES (7161, 8, 2, 10, 'e-caiu sobre face-dela e-se-prostrou E-disse a-ele a-ele por-que achei graça em-olhos-teus para-conhecer-me e-eu estranha');
INSERT INTO verses VALUES (7162, 8, 2, 11, 'e-respondeu בֹעַז E-disse para-ela foi-relatado foi-relatado para-mim todo que fizeste a morrendo após morte-de homem-teu e-abandonaste pai-teu e-mãe-tua e-terra-de nascimento-teu e-foste a povo que não conheceste ontem terceiro-dia');
INSERT INTO verses VALUES (7163, 8, 2, 12, 'pague yhwh trabalho-teu e-seja salário-teu completo de-com yhwh Elohim-de Israel que vieste para-buscar-refúgio debaixo-de asas-dele');
INSERT INTO verses VALUES (7164, 8, 2, 13, 'E-disse encontre graça em-olhos-teus que porque consolaste-me e-que falaste sobre coração não e-eu não serei como-uma servas-tuas');
INSERT INTO verses VALUES (7165, 8, 2, 14, 'E-disse para-ela Boaz ao-tempo-de a-comida aproxima-te aqui e-comerás de o-pão e-molharás pedaço-teu no-vinagre e-sentou de-lado-de os-ceifadores e-ofereceu e-comeste grão-tostado e-comeu e-saciou-se e-sobrou');
INSERT INTO verses VALUES (7166, 8, 2, 15, 'e-levantou-se para-respigar E-ordenou בֹעַז a dizendo também entre entre os-feixes respigue e-não envergonheis-ela');
INSERT INTO verses VALUES (7167, 8, 2, 16, 'e-também puxar puxareis para-ela de os-molhos e-deixareis e-respigará e-não repreendais em-ela');
INSERT INTO verses VALUES (7168, 8, 2, 17, 'e-respigou no-campo até a-tarde e-debulhou com e-houve respigou E-foi como-efa-de cevada');
INSERT INTO verses VALUES (7169, 8, 2, 18, 'e-carregou e-veio a-cidade E-viu sogra-dela com que E-produziu e-tirou e-deu para-ela a que sobrou de-saciedade-dela');
INSERT INTO verses VALUES (7170, 8, 2, 19, 'E-disse para-ela sogra-dela onde respigaste o-dia e-onde fizeste haja reconheceu-te bendito e-relatou para-sogra-dela a que trabalhou E-disse e-disse nome o-homem que trabalhei o-dia o-dia בֹּעַז');
INSERT INTO verses VALUES (7171, 8, 2, 20, 'E-disse Naomi para-nora-dela bendito ele para-יהוה que não abandonou bondade-dele a E-disse e-a os mortos e-disse para-ela Noemi próximo ele o-homem de-remidores-nossos ela');
INSERT INTO verses VALUES (7172, 8, 2, 21, 'E-disse Rute a moabita também porque disse a-mim com os jovens que até aderir até se terminaram a todo a colheita que para-mim');
INSERT INTO verses VALUES (7173, 8, 2, 22, 'E-disse Noemi a Rute bom bom que porque sairás com jovens-dele e-não encontrarão em-ti em-campo outro');
INSERT INTO verses VALUES (7174, 8, 2, 23, 'e-aderiu em-jovens בֹעַז para-colher até terminar colheita-de as cevadas e-colheita os trigos e-habitou a sogra-dela');
INSERT INTO chapters VALUES (235, 8, 3, 18);
INSERT INTO verses VALUES (7175, 8, 3, 1, 'E-disse para-ela Noemi sogra-dela filha-minha não buscarei para-ti descanso que será-bom para-ti');
INSERT INTO verses VALUES (7176, 8, 3, 2, 'e-agora não Boaz conhecido-nosso que estavas a jovens-dele eis-que- ele joeirando a-noite eira as cevadas a-noite');
INSERT INTO verses VALUES (7177, 8, 3, 3, 'e-lavarás e-ungirás e-colocarás sobre-ti a eira a serás-conhecida para-o homem até terminar-dele para-comer e-para-beber');
INSERT INTO verses VALUES (7178, 8, 3, 4, 'e-seja em-deitar-dele e-saberás a o-lugar que deitará nome e-entrarás e-descobrirás pés-dele e-ele dirá para-ti את que farás');
INSERT INTO verses VALUES (7179, 8, 3, 5, 'E-disse para-ela todo que dirás farei');
INSERT INTO verses VALUES (7180, 8, 3, 6, 'e-desceu a eira e-fez conforme-tudo que ordenou-ela sogra-dela');
INSERT INTO verses VALUES (7181, 8, 3, 7, 'e-comeu Boaz e-bebeu e-foi-bom coração-dele E-veio para-deitar em-extremidade o monte e-veio em-segredo e-descobriu pés-dele e-deitou');
INSERT INTO verses VALUES (7182, 8, 3, 8, 'e-houve em-meio a-noite e-tremeu o homem e-virou-se e-eis mulher deitada pés-dele');
INSERT INTO verses VALUES (7183, 8, 3, 9, 'E-disse quem E-disse eu eu Rute serva-tua e-estenderás asa-tua que serva-tua porque resgatador tu');
INSERT INTO verses VALUES (7184, 8, 3, 10, 'E-disse bendita tu para-יהוה filha-minha fizeste-bem bondade-tua a-última de o-primeiro para-não ir depois-de os-jovens se pobre e-se rico');
INSERT INTO verses VALUES (7185, 8, 3, 11, 'e-agora filha-minha a temas todo que que farei para-ti porque que todo portão povo-meu porque mulher-de valor tu');
INSERT INTO verses VALUES (7186, 8, 3, 12, 'e-agora que verdadeiramente que resgatador eu eu há resgatador próximo de-mim');
INSERT INTO verses VALUES (7187, 8, 3, 13, 'passa-a-noite a-noite e-era pela-manhã se te-resgatará bom resgate e-se não desejar para-resgatar-te eu eu vive yhwh deita até a-manhã');
INSERT INTO verses VALUES (7188, 8, 3, 14, 'e-deitou até a-manhã e-levantou reconheça homem a companheiro-seu E-disse a E-disse porque veio a-mulher a-eira');
INSERT INTO verses VALUES (7189, 8, 3, 15, 'E-disse traz o-manto que sobre-ti e-segura nela e-segurou nela e-mediu seis-de cevadas e-pôs sobre-ela E-veio a-cidade');
INSERT INTO verses VALUES (7190, 8, 3, 16, 'e-veio a E-disse e-disse quem tu filha-minha e-contou objeto-direto todo que fez para-ela o-homem');
INSERT INTO verses VALUES (7191, 8, 3, 17, 'E-disse seis-de as-cevadas dar deu que disse disse a virás vazia a sogra-tua');
INSERT INTO verses VALUES (7192, 8, 3, 18, 'E-disse senta filha-minha até que saberás como cairá palavra que não descansará o-homem porque se o-dia a palavra o-dia');
INSERT INTO chapters VALUES (236, 8, 4, 22);
INSERT INTO verses VALUES (7193, 8, 4, 1, 'e-Boaz subir o-portão e-sentou nome e-eis o-resgatador passando que falou E-disse E-disse desvia senta aqui fulano sicrano e-desviou e-sentou');
INSERT INTO verses VALUES (7194, 8, 4, 2, 'E-tomou dez homens de-anciãos-de a-cidade E-disse sentai aqui e-sentaram');
INSERT INTO verses VALUES (7195, 8, 4, 3, 'E-disse para-o-resgatador porção-de o-campo que para-irmão-nosso para-Elimeleque vendeu Naomi a-que-voltou de-campo-de Moabe');
INSERT INTO verses VALUES (7196, 8, 4, 4, 'e-eu disse revelarei ouvido-teu dizendo compra diante os que-habitam e-diante-de anciãos-de povo-meu se redimirás redime e-se não a-mim declara para-mim que não-há exceto-tu para-redimir e-eu depois-de-ti E-disse eu redimirei');
INSERT INTO verses VALUES (7197, 8, 4, 5, 'E-disse Boaz em-dia-de comprares-tu o-campo de-mão-de Naomi e-de-com Rute a-moabita esposa-de o morto para-levantar nome-de o morto sobre herança-dele');
INSERT INTO verses VALUES (7198, 8, 4, 6, 'E-disse o redentor não posso para-mim para-que-não destruiria a tu redime- que tu a redenção-minha porque não posso redimir');
INSERT INTO verses VALUES (7199, 8, 4, 7, 'e-esta anteriormente em-Israel sobre a redenção e-sobre a troca para-confirmar todo palavra tirava homem sandália-sua e-dava para-companheiro-seu e-esta a testemunha em-Israel');
INSERT INTO verses VALUES (7200, 8, 4, 8, 'E-disse o redentor para-Boaz compra- para-ti e-tirou sandália-sua');
INSERT INTO verses VALUES (7201, 8, 4, 9, 'E-disse בֹעַז para-os anciãos e-todo o povo testemunhas o-dia que porque comprei a tudo-de que para-Elimeleque e-a todo que para-Quiliom e-Malom de-mão-de Naomi');
INSERT INTO verses VALUES (7202, 8, 4, 10, 'e-também a Rute a moabita esposa-de Malom comprei a-mim para-esposa para-levantar nome-de o morto sobre herança-dele e-não será-cortada nome-de o morto de-com o-dia e-de-portão-de lugar-seu testemunhas vós o-dia');
INSERT INTO verses VALUES (7203, 8, 4, 11, 'e-disseram todo o povo que no-portão e-os anciãos yhwh dê yhwh את- a mulher a que-entra a casa-tua como-Raquel e-como-Lia que edificaram duas-delas a casa Israel e-faze- força em-Efrata e-proclama- nome em-casa-de pão');
INSERT INTO verses VALUES (7204, 8, 4, 12, 'e-seja casa-sua como-casa-de פֶּרֶץ que ela-deu-à-luz תָמָר para-יְהוּדָה de a-semente yhwh a-ti yhwh para-ti de a-jovem a esta');
INSERT INTO verses VALUES (7205, 8, 4, 13, 'E-tomou Boaz a רוּת e-ela-tornou-se para-ele para-esposa E-colocou yhwh E-deu yhwh para-ela filho e-deu-à-luz filho');
INSERT INTO verses VALUES (7206, 8, 4, 14, 'e-disseram as-mulheres a נָעֳמִי yhwh yhwh não não para-ti para-ti o-dia o-dia E-chamou nome-de-ele em-Israel');
INSERT INTO verses VALUES (7207, 8, 4, 15, 'e-será para-ti para-restaurador-de alma e-para-sustentar a que porque nora-sua que ela-te-amou ela-o-deu-à-luz para-ti ela boa para-ti mais-que-sete filhos');
INSERT INTO verses VALUES (7208, 8, 4, 16, 'e-tomou נָעֳמִי a a-criança e-ela-o-colocou em-colo-dela e-ela-tornou-se para-ele para-ama');
INSERT INTO verses VALUES (7209, 8, 4, 17, 'e-chamaram a-ele as-vizinhas nome dizendo nasceu filho para-נָעֳמִי e-chamaram nome-dele ele ele pai-de יִשַׁי pai-de Davi');
INSERT INTO verses VALUES (7210, 8, 4, 18, 'e-estes gerações פֶּרֶץ פֶּרֶץ gerou a חֶצְרוֹן');
INSERT INTO verses VALUES (7211, 8, 4, 19, 'e-חֶצְרוֹן gerou a רָם e-רָם gerou a עַמִּינָדָב');
INSERT INTO verses VALUES (7212, 8, 4, 20, 'e-עַמִּינָדָב gerou a נַחְשׁוֹן e-נַחְשׁוֹן gerou a שַׂלְמוֹן');
INSERT INTO verses VALUES (7213, 8, 4, 21, 'e-שַׂלְמוֹן gerou a Boaz e-בֹּעַז gerou a עוֹבֵד');
INSERT INTO verses VALUES (7214, 8, 4, 22, 'e-עוֹבֵד gerou a יִשַׁי e-יִשַׁי gerou a Davi');
INSERT INTO books VALUES (9, '1SA', '1 Samuel', 'AT', 31);
INSERT INTO chapters VALUES (237, 9, 1, 28);
INSERT INTO verses VALUES (7215, 9, 1, 1, 'e-houve homem um de as-Ramatáim Sofim de-montanha-de Efraim e-nome-dele Elcana filho-de Jeroão filho-de Eliú filho-de Toú filho-de Suf efrateu');
INSERT INTO verses VALUES (7216, 9, 1, 2, 'e-para-ele duas mulheres nome uma Ana e-nome-de a-segunda Penina e-houve para-Penina filhos e-para-Ana não filhos');
INSERT INTO verses VALUES (7217, 9, 1, 3, 'e-subiu o-homem o-aquele de-cidade-dele de-dias dias-para para-prostrar-se e-para-sacrificar para-יהוה de-exércitos em-Siló e-ali segundo filhos-de Eli Hofni e-Fineias sacerdotes para-יהוה');
INSERT INTO verses VALUES (7218, 9, 1, 4, 'e-houve o-dia e-sacrificou Elcana e-deu para-Penina esposa-dele e-para-todo filhos-dela e-filhas-dela porções');
INSERT INTO verses VALUES (7219, 9, 1, 5, 'e-para-Ana ele-dará porção-de uma face que a Ana amou fechar fechou útero-dela');
INSERT INTO verses VALUES (7220, 9, 1, 6, 'e-irritou-ela rival-dela também irritação por-causa-de fazer-tremer-ela yhwh fechou yhwh por-causa-de útero-dela');
INSERT INTO verses VALUES (7221, 9, 1, 7, 'e-assim ele-fará ano em-ano desde subir-dela em-casa-de yhwh assim ela-irritava-ela e-ela-chorou e-não comerás');
INSERT INTO verses VALUES (7222, 9, 1, 8, 'E-disse para-ela Elcana marido-dela Ana por-que tu-choras e-por-que não tu-comes e-por-que é-mau coração-teu não eu bom para-ti de-dez filhos');
INSERT INTO verses VALUES (7223, 9, 1, 9, 'e-levantou-se Ana depois-de ela-comeu em-Siló e-depois-de ela-bebeu e-Eli o-sacerdote habitou sobre a-cadeira sobre yhwh templo-de yhwh');
INSERT INTO verses VALUES (7224, 9, 1, 10, 'e-ela amarga-de alma e-ela-orou sobre yhwh e-chorar ela-chorará');
INSERT INTO verses VALUES (7225, 9, 1, 11, 'e-ela-fez-voto voto e-ela-disse yhwh de-exércitos se viu tu-verás em-aflição-de serva-tua e-tu-lembrarás-me e-não esquecerás a serva-tua semente para-serva-tua descendência homens e-deste-o para-יהוה todo dias-de vidas-dele e-navalha não subirá sobre cabeça-dele');
INSERT INTO verses VALUES (7226, 9, 1, 12, 'e-será que multiplicaste para-orar-se diante-de yhwh e-Eli guardando a boca-dela');
INSERT INTO verses VALUES (7227, 9, 1, 13, 'e-Ana ela falando sobre coração-dela somente lábios-dela movendo-se não não será-ouvida e-pensou-a Eli para-embriagada');
INSERT INTO verses VALUES (7228, 9, 1, 14, 'E-disse para-ela Eli até até-quando embriagar-te-ás remove a vinho-teu de-sobre-ti');
INSERT INTO verses VALUES (7229, 9, 1, 15, 'e-respondeu Ana E-disse não Adonai mulher dura-de- eu eu e-vinho não não bebi e-derramei a yhwh diante-de yhwh');
INSERT INTO verses VALUES (7230, 9, 1, 16, 'a dês a serva-tua diante-de filha-de Belial porque de-abundância-de conversa-minha e-aflição-minha falei até até-aqui');
INSERT INTO verses VALUES (7231, 9, 1, 17, 'e-respondeu Eli E-disse vai para-paz e-Elohim-de Israel dará a petição-tua que pediste de-com-ele');
INSERT INTO verses VALUES (7232, 9, 1, 18, 'E-disse encontre serva-tua graça em-olhos-teus e-foi a-mulher para-caminho-dela e-comeste e-face-dela não eram- para-ela ainda');
INSERT INTO verses VALUES (7233, 9, 1, 19, 'e-levantaram-cedo na-manhã e-prostraram-se diante-de yhwh e-retornaram e-vieram a casa-deles a-Ramá e-conheceu Elcana a Ana yhwh e-ele-a-recordou yhwh');
INSERT INTO verses VALUES (7234, 9, 1, 20, 'e-houve para-voltas-de os-dias e-concebeu Ana e-deu-à-luz filho e-chamou a nome-dele que porque de-יהוה pedi-o');
INSERT INTO verses VALUES (7235, 9, 1, 21, 'e-subiu o-homem Elcana e-todo casa-dele para-sacrificar para-יהוה a sacrifício os-dias e-a voto-dele');
INSERT INTO verses VALUES (7236, 9, 1, 22, 'e-Ana não subiu porque disse até até for-desmamado o-menino e-trouxe-o e-aparecerá yhwh face-de yhwh e-habitará nome até eternidade');
INSERT INTO verses VALUES (7237, 9, 1, 23, 'E-disse para-ela Elcana marido-dela faze o-bom em-olhos-teus habita até ele a-ele somente yhwh yhwh a palavra-dele e-habitou a-mulher e-amamentou ele filho-seu até desmamou-o a-ele');
INSERT INTO verses VALUES (7238, 9, 1, 24, 'e-fez-subir-o com-ela como-que desmamar-o em-touros três e-efa-de uma farinha e-odre-de vinho e-trouxe-o casa-de yhwh Shilo e-o-menino menino');
INSERT INTO verses VALUES (7239, 9, 1, 25, 'e-sacrificaram a o-touro e-trouxeram a o-menino a Eli');
INSERT INTO verses VALUES (7240, 9, 1, 26, 'E-disse por-mim Adonai viveu alma-tua Adonai eu a-mulher a-que-estava contigo neste para-orar-se a yhwh');
INSERT INTO verses VALUES (7241, 9, 1, 27, 'a o-menino este E-colocou yhwh yhwh a-mim a pedi que pedi de-com-ele');
INSERT INTO verses VALUES (7242, 9, 1, 28, 'e-também eu emprestei-o para-יהוה todo os-dias ser ele ele Saul para-יהוה e-prostrou-se nome para-יהוה');
INSERT INTO chapters VALUES (238, 9, 2, 36);
INSERT INTO verses VALUES (7243, 9, 2, 1, 'e-orou Ana e-disse exultou coração-meu em-יהוה exaltou-se chifre-meu em-יהוה alargou-se boca-minha sobre que porque alegrei-me em-salvação-tua');
INSERT INTO verses VALUES (7244, 9, 2, 2, 'não-há santo que porque não-há exceto-tu e-não-há rocha como-Elohim-nosso');
INSERT INTO verses VALUES (7245, 9, 2, 3, 'a multipliquem falem alta alta saia arrogante que porque El yhwh yhwh são-pesadas ações');
INSERT INTO verses VALUES (7246, 9, 2, 4, 'arco-de valentes quebrados e-tropeçantes cingiram força');
INSERT INTO verses VALUES (7247, 9, 2, 5, 'fartos por-pão alugaram-se e-famintos cessaram até estéril deu-à-luz sete e-a-que-tinha-muitos filhos definhou');
INSERT INTO verses VALUES (7248, 9, 2, 6, 'yhwh mata e-vivifica faz-descer sepulcro e-faz-subir');
INSERT INTO verses VALUES (7249, 9, 2, 7, 'yhwh empobrece e-enriquece humilha também e-exalta');
INSERT INTO verses VALUES (7250, 9, 2, 8, 'levanta do-pó pobre do-monturo ele-levantará necessitado para-assentar com nobres e-trono-de glória que porque para-יהוה terra terra herdar-os sobre-eles mundo');
INSERT INTO verses VALUES (7251, 9, 2, 9, 'pés-de guardará e-ímpios na-escuridão silenciarão porque não por-força prevalecerá homem');
INSERT INTO verses VALUES (7252, 9, 2, 10, 'yhwh serão-quebrados nos-céus ele-trovejará yhwh ele-julgará extremidades-de terra yhwh força para-rei-dele e-ele-exaltará chifre-de ungido-dele');
INSERT INTO verses VALUES (7253, 9, 2, 11, 'E-andou Elcana a-Ramá sobre casa-dele ser foi servindo a yhwh a face-de Eli o-sacerdote');
INSERT INTO verses VALUES (7254, 9, 2, 12, 'e-filhos-de Eli filhos-de Belial não eles-conheceram a yhwh');
INSERT INTO verses VALUES (7255, 9, 2, 13, 'e-direito-de os-sacerdotes a o-povo todo homem sacrificando sacrifício e-ele-veio jovem o-sacerdote como-cozinhar a-carne e-o-garfo três-de os-dentes em-mão-sua');
INSERT INTO verses VALUES (7256, 9, 2, 14, 'e-ele-golpeou na-panela ou na-caldeira ou na-caldeirão ou na-panela todo que subia o-garfo ele-tomará o-sacerdote nele assim eles-faziam para-todo Israel os-que-vêm nome em-Silo');
INSERT INTO verses VALUES (7257, 9, 2, 15, 'também antes-de eles-queimarem a a-gordura e-ele-veio jovem o-sacerdote e-ele-disse para-o-homem o-sacrificante dá carne para-assar para-o-sacerdote e-não ele-tomará de-ti carne que porque se viveu');
INSERT INTO verses VALUES (7258, 9, 2, 16, 'E-disse a-ele o-homem queimar eles-queimarão como-o-dia a-gordura e-toma para-ti como-que ela-deseja alma-tua e-ele-disse porque agora que e-se não eu-tomarei com-força');
INSERT INTO verses VALUES (7259, 9, 2, 17, 'e-foi pecado-de os-jovens grande muito a yhwh que porque eles-desprezaram os-homens את yhwh yhwh');
INSERT INTO verses VALUES (7260, 9, 2, 18, 'e-Samuel servindo a yhwh yhwh jovem cingido éfode linho');
INSERT INTO verses VALUES (7261, 9, 2, 19, 'e-manto pequeno farás- sua-mãe mãe-dele a-ele para-ele de-dias para-dias no-subir-dela a marido-dela para-sacrificar a sacrifício os dias');
INSERT INTO verses VALUES (7262, 9, 2, 20, 'e-ele-abençoou Eli a Elcana e-a esposa-dele yhwh a-ti semente para-ti semente debaixo a-mulher a-esta em-lugar-de a-petição que ele-pediu para-יהוה e-eles-foram para-lugar-dele');
INSERT INTO verses VALUES (7263, 9, 2, 21, 'porque yhwh yhwh a Ana e-ela-concebeu e-deu-à-luz três-de filhos e-duas-de filhas e-cresceu o-menino שְׁמוּאֵל com yhwh');
INSERT INTO verses VALUES (7264, 9, 2, 22, 'e-עֵלִי velho muito e-ouviu את todo que fazem filhos-dele para-todo-de Israel e-a que deitam-se a as-mulheres as-que-servem entrada-de tenda-de encontro');
INSERT INTO verses VALUES (7265, 9, 2, 23, 'E-disse a-eles por-que fazeis como-as-coisas estas que eu ouviu a palavras-de-vós más de-com Estas o-povo estes');
INSERT INTO verses VALUES (7266, 9, 2, 24, 'El filhos-de que não boa a-fama eu eu ouviu fazem-passar com yhwh');
INSERT INTO verses VALUES (7267, 9, 2, 25, 'se pecar homem para-homem e-orarao Elohim e-se para-יהוה quem homem quem orará à-voz-de e-não ouvirem yhwh pai-deles porque desejava yhwh para-matá-los');
INSERT INTO verses VALUES (7268, 9, 2, 26, 'e-o-jovem שְׁמוּאֵל andou e-crescendo e-bom também com yhwh e-também com homens');
INSERT INTO verses VALUES (7269, 9, 2, 27, 'E-veio homem Elohim E-disse a-ele E-disse disse yhwh disse yhwh acaso-revelar-se me-revelei a casa pai-teu em-estar-eles em-Egito segundo-casa-de פַּרְעֹה');
INSERT INTO verses VALUES (7270, 9, 2, 28, 'e-escolher ele de-todo tribos-de Israel a-mim para-sacerdote para-subir sobre altar-meu para-queimar incenso para-levar éfode diante-de-mim e-dei para-casa-de pai-teu a todo ofertas-de-fogo-de filhos-de Israel');
INSERT INTO verses VALUES (7271, 9, 2, 29, 'por-que desprezais em-sacrifício-meu e-em-oferta-minha que ordenei habitação e-honraste a filhos-teus mais-que-a-mim para-engordar-vos de-primícia-de todo oferenda-de Israel para-povo-meu');
INSERT INTO verses VALUES (7272, 9, 2, 30, 'portanto oráculo-de yhwh Elohim-de Israel dizer eu-disse casa-tua e-Beit pai-teu andarão diante-de-mim e-agora eternidade e-agora a-mim yhwh longe-seja para-mim porque os-que-me-honram honrarei e-os-que-me-desprezam serão-desprezados');
INSERT INTO verses VALUES (7273, 9, 2, 31, 'eis dias vindo e-cortarei a braço-teu e-a braço-de casa pai-teu de-haver velho em-casa-tua');
INSERT INTO verses VALUES (7274, 9, 2, 32, 'e-olharás angústia-de habitação em-todo que fará-bem a Israel e-não será velho em-casa-tua todo os dias');
INSERT INTO verses VALUES (7275, 9, 2, 33, 'e-homem não a-ti para-ti de-com altar-meu para-consumir a olhos-teus e-para-entristecer a alma-tua e-todo aumento-de casa-tua morrerão homens');
INSERT INTO verses VALUES (7276, 9, 2, 34, 'e-este para-ti o-sinal que virá a segundo filhos-teus a um e-Finéias em-dia um morrerão dois-deles');
INSERT INTO verses VALUES (7277, 9, 2, 35, 'e-levantarei a-mim sacerdote fiel como em-coração-meu e-em-alma-minha fará e-edificarei a-ele casa fiel e-andará diante-de ungido-meu todo os dias');
INSERT INTO verses VALUES (7278, 9, 2, 36, 'e-será todo o-restante em-casa-tua virá a-ele a-ele para-moeda-de prata e-pedaço-de pão e-dirá junta-me por-favor a uma as-funções-sacerdotais para-comer pedaço-de pão');
INSERT INTO chapters VALUES (239, 9, 3, 21);
INSERT INTO verses VALUES (7279, 9, 3, 1, 'e-o-jovem Samuel servindo a yhwh diante-de Eli ser yhwh foi preciosa em-os-dias aqueles não-há visão frequente');
INSERT INTO verses VALUES (7280, 9, 3, 2, 'e-houve no-dia a-aquela e-Eli deitado em-lugar-seu começaram escurecer não podia não');
INSERT INTO verses VALUES (7281, 9, 3, 3, 'e-lâmpada-de Elohim ainda-não se-apagará e-Samuel deitado em-templo-de yhwh que nome aron Elohim');
INSERT INTO verses VALUES (7282, 9, 3, 4, 'E-chamou yhwh a E-disse E-disse eis-me');
INSERT INTO verses VALUES (7283, 9, 3, 5, 'e-correu a E-disse E-disse eis-me a-mim E-disse para-mim E-disse não chamaste volta deita E-andou e-deitou-se');
INSERT INTO verses VALUES (7284, 9, 3, 6, 'e-continuou yhwh chamou mais Samuel E-levantou Samuel E-andou a E-disse E-disse que porque chamaste E-disse E-disse não chamei filhos-de volta deita');
INSERT INTO verses VALUES (7285, 9, 3, 7, 'e-Samuel ainda-não saber a yhwh e-ainda-não a-ele a-ele palavra-de yhwh');
INSERT INTO verses VALUES (7286, 9, 3, 8, 'e-continuou yhwh chamar Samuel na-terceira-vez E-levantou E-andou E-disse Eli que eis-me porque chamaste para-mim que yhwh porque yhwh chamou para-o-jovem');
INSERT INTO verses VALUES (7287, 9, 3, 9, 'E-disse Eli para-Samuel vai deita e-será se chamar para-ti e-dirás palavra yhwh que ouviu servo-teu E-andou שְׁמוּאֵל e-deitou-se em-lugar-seu');
INSERT INTO verses VALUES (7288, 9, 3, 10, 'E-veio yhwh e-postou-se E-chamou como-vez em-vez Samuel Samuel E-disse Samuel palavra que ouviu servo-teu');
INSERT INTO verses VALUES (7289, 9, 3, 11, 'E-disse yhwh a eis eu eu fez palavra em-Israel que todo ouvinte-seu duas-de ouvidos-seus');
INSERT INTO verses VALUES (7290, 9, 3, 12, 'no-dia o-aquele levantarei a Eli objeto-direto todo que falei a casa-dele começar e-terminar');
INSERT INTO verses VALUES (7291, 9, 3, 13, 'e-eu-declararei a-ele porque julgando eu a casa-dele até para-sempre a-eles que conheceu porque amaldiçoando para-eles filhos-dele e-não repreendeu em-eles');
INSERT INTO verses VALUES (7292, 9, 3, 14, 'e-portanto eu-jurei para-casa-de Eli se será-expiado iniquidade-de casa-de Eli com-sacrifício e-com-oferta até eternidade');
INSERT INTO verses VALUES (7293, 9, 3, 15, 'e-deitou-se Samuel até a-manhã e-abriu a portas-de temer yhwh e-Samuel temia de-contar a a-visão a para-Eli');
INSERT INTO verses VALUES (7294, 9, 3, 16, 'E-chamou Eli a E-disse E-disse Samuel E-disse E-disse eis-me');
INSERT INTO verses VALUES (7295, 9, 3, 17, 'E-disse que a-palavra que palavra para-ti a agora escondas de-mim assim fara- para-ti Elohim e-assim acrescentará se esconderes de-mim palavra de-todo a palavra que palavra para-ti');
INSERT INTO verses VALUES (7296, 9, 3, 18, 'e-contou para-ele Samuel a todo nós e-não yhwh ele E-disse yhwh ele o-bom em-olhos-dele ele-fará');
INSERT INTO verses VALUES (7297, 9, 3, 19, 'e-cresceu Samuel e-יהוה ser com-ele e-não fez-cair de-todo palavras-dele para-terra');
INSERT INTO verses VALUES (7298, 9, 3, 20, 'e-soube todo Israel desde-Dã e-até que sete porque estabelecido שְׁמוּאֵל como-profeta para-יהוה');
INSERT INTO verses VALUES (7299, 9, 3, 21, 'e-continuou yhwh a-aparecer em-Siló porque yhwh yhwh a Samuel yhwh pela-palavra-de yhwh');
INSERT INTO chapters VALUES (240, 9, 4, 22);
INSERT INTO verses VALUES (7300, 9, 4, 1, 'e-houve palavra-de שְׁמוּאֵל para-todo Israel e-saiu Israel ao-encontro-de filisteus para-a-guerra e-acamparam sobre a-pedra da-ajuda e-filisteus acamparam em-Afeque');
INSERT INTO verses VALUES (7301, 9, 4, 2, 'e-dispuseram-se filisteus ao-encontro-de Israel e-se-estendeu a-guerra e-foi-ferido Israel diante-de pelos-filisteus e-feriram na-formação-de-batalha no-campo cerca-de-quatro dois-mil homem');
INSERT INTO verses VALUES (7302, 9, 4, 3, 'E-veio o-povo a o-acampamento e-disseram anciãos-de Israel por-que yhwh o-dia o-dia diante-de pelos-filisteus tomaremos para-nós de-Siló a yhwh aliança yhwh E-veio em-meio-de-nós e-nos-salvará da-mão-de inimigos-nossos');
INSERT INTO verses VALUES (7303, 9, 4, 4, 'e-estendeu o-povo Siló e-tomaram de-lá com arca-de em-aliança-de yhwh dos-exércitos os-querubins os-querubins e-ali segundo filhos-de Eli com arca-de aliança os-Elohim Hofni e-Finéias');
INSERT INTO verses VALUES (7304, 9, 4, 5, 'e-houve como-vir arca em-aliança-de yhwh a o-acampamento e-gritaram todo Israel a-terra grande e-soou a-terra');
INSERT INTO verses VALUES (7305, 9, 4, 6, 'e-ouviram filisteus a voz-de o-grito e-disseram voz voz-de o-grito a-grande esta em-acampamento-de e-souberam que porque yhwh yhwh veio a o-acampamento');
INSERT INTO verses VALUES (7306, 9, 4, 7, 'e-temeram os-filisteus que disseram veio Elohim a o-acampamento e-disseram ai que não era foi como-esta ontem anteontem');
INSERT INTO verses VALUES (7307, 9, 4, 8, 'ai para-nós quem nos-livrará de-mão-de os-Elohim os-majestosos estes Estas eles os-Elohim os-que-ferem a Egito em-todo ferida no-deserto');
INSERT INTO verses VALUES (7308, 9, 4, 9, 'sede-fortes e-sede para-os-homens filisteus para-que-não sirvais aos-hebreus como-que serviram a-vós e-sereis para-homens e-combatei');
INSERT INTO verses VALUES (7309, 9, 4, 10, 'e-combateram פְלִשְׁתִּ֗ים e-foi-ferido Israel e-fugiram homem para-tendas-suas e-foi a-ferida grande muito e-caiu de-Israel trinta mil de-pé');
INSERT INTO verses VALUES (7310, 9, 4, 11, 'e-arca-de Elohim foi-tomada e-dois-de filhos-de Eli morreram Hofni e-Finéias');
INSERT INTO verses VALUES (7311, 9, 4, 12, 'e-correu homem benjamita de-a-batalha E-veio no-dia em-o-dia o-aquele e-vestes-suas rasgadas e-terra sobre cabeça-dele');
INSERT INTO verses VALUES (7312, 9, 4, 13, 'e-veio e-eis Eli habitou sobre a-cadeira caminho o-caminho-de porque foi coração-seu ansioso sobre arca o-Elohim e-o-homem veio para-dizer na-cidade e-ela-gritou todo a-cidade');
INSERT INTO verses VALUES (7313, 9, 4, 14, 'E-ouviu Eli a voz-de E-disse E-disse voz voz o-tumulto este e-o-homem apressado E-veio e-revelou para-Eli');
INSERT INTO verses VALUES (7314, 9, 4, 15, 'e-Elí filho-de noventa e-oito ano e-seus-o-olhos levantou-a-si-mesma e-não para-ver para-ver');
INSERT INTO verses VALUES (7315, 9, 4, 16, 'E-disse o-homem a eu eu o-que-vinha de a-marcha e-eu o-dia E-disse tentei-eu o-dia E-disse de-o- foi a palavra filhos-de');
INSERT INTO verses VALUES (7316, 9, 4, 17, 'e-ele-respondeu o-anunciador E-disse fugiu Israel diante-de filisteus e-também pandemia grande era no p''um e-também segundo filhos-teus de-os-mortos Hofni e-Pinhas e-arca-de Elohim foi-tomada');
INSERT INTO verses VALUES (7317, 9, 4, 18, 'e-houve como-o-recordá-lo a arca os-Elohim e-caiu de-em-cima-de o-trono traseira em-defesa-de mão o-porta e-ela-partiu-se de-sua-articulação E-morreu porque envelheceu o homem e-se-tornou-grave e-ele juiz a Israel quarenta anos');
INSERT INTO verses VALUES (7318, 9, 4, 19, 'e-sua-nora esposa-de Pinhas gravida-foi bateu e-ela-ouviu a a ele-o-levou arca os-Elohim e-ele-morreu seu-sogro e-seu-marido e-ela-caiu e-ela-pariu porque viraram-se sobre-ela seus-dentes');
INSERT INTO verses VALUES (7319, 9, 4, 20, 'e-no-tempo mor-te-a e-ela-s-fal-a-m as-est-a-das sobre-ela a que porque filho par-i-u-e e-não res-po-n-di-u e-não be-b-eu a-cri-a-da-la');
INSERT INTO verses VALUES (7320, 9, 4, 21, 'e-ela-le-u a-o-jov-e-n não- dizendo dizendo revelou-se glória de-Israel a ele-o-levou arca os-Elohim e-a sogro-seu e-homem-seu');
INSERT INTO verses VALUES (7321, 9, 4, 22, 'E-disse revelou-se glória de-Israel que foi-tomado arca Elohim');
INSERT INTO chapters VALUES (241, 9, 5, 12);
INSERT INTO verses VALUES (7322, 9, 5, 1, 'e-Philistines tomaram a arca o-Elohim e-os-trouxeram de-a-pedra o-ajudante a-asdoda');
INSERT INTO verses VALUES (7323, 9, 5, 2, 'e-tomaram filisteus a arca os-Elohim ele ele casa dagom ele ele ao-lado-de dagom');
INSERT INTO verses VALUES (7324, 9, 5, 3, 'e-eles-se-levantaram asdodim de-amanhã e-eis dagom caindo diante-dele terra-para diante-de arca yhwh e-eles-levaram a dagon ele ele para-o-lugar-seu');
INSERT INTO verses VALUES (7325, 9, 5, 4, 'e-levantaram-cedo no-manhã de-a-amanhã e-eis dagon caindo diante-dele terra-para diante-de arca yhwh e-cabeça dagon e-dois plantas-de as-sua-mãos cortadas a o-tapete somente dagon permaneceu sobre-ele');
INSERT INTO verses VALUES (7326, 9, 5, 5, 'sobre assim não dirigir-se-ão sacerdotes-de dagon e-todo os-vindo casa-de até o-dia de-o-pátio Dagon em-Ashdod até o-dia a-esta');
INSERT INTO verses VALUES (7327, 9, 5, 6, 'e-ela-se-fez-pesada mão-de yhwh a os-Ashdodites eles a-elas a Ashdod e-a de-sua-fronteira');
INSERT INTO verses VALUES (7328, 9, 5, 7, 'e-eles-deram-conta os-homens-de- Ashdod porque assim e-diretriz não habitou arca-de Elohim-de sua-mão conosco-s porque estendeu-se mão-dele sobre-nós e-sobre דָּג֥וֹן Elohim-nosso');
INSERT INTO verses VALUES (7329, 9, 5, 8, 'e-eles-enviaram e-eles-reuniram-se a todo oficiais-de filisteus a-eles e-disseram que será-feito para-o-arca Elohim-de Israel e-disseram cidade ele-voltará arca Elohim-de Israel e-viraram a arca Elohim-de Israel');
INSERT INTO verses VALUES (7330, 9, 5, 9, 'e-houve depois-de viraram a-ele ele mão-de יהוה na-cidade confusão grande muito muito a homens-de a-cidade de-pequeno e-até grande a-eles a-eles');
INSERT INTO verses VALUES (7331, 9, 5, 10, 'e-enviaram a arca Elohim e-houve E-foi como-vir arca o-Elohim Ecrom e-gritaram dizendo dizendo viraram a-mim a arca-de Elohim-de Israel para-matar-me e-a povo-meu');
INSERT INTO verses VALUES (7332, 9, 5, 11, 'e-enviaram e-ele-reuniram a todo príncipes-de פְלִשְׁתִּ֗ים e-disseram e-ela-enviou a arca-de Elohim-de Israel e-ele-voltará para-o-lugar-seu e-não matará me-a e-a muito porque foi-ela de-tumulto-de morte em-todo a-cidade pesada muito mão Elohim nome');
INSERT INTO verses VALUES (7333, 9, 5, 12, 'e-os-homens que não morreram foram-feridos e-subiu súplica-de a-cidade os-céus');
INSERT INTO chapters VALUES (242, 9, 6, 21);
INSERT INTO verses VALUES (7334, 9, 6, 1, 'e-houve arca-de yhwh no-campo dos-filisteus sete meses');
INSERT INTO verses VALUES (7335, 9, 6, 2, 'e-chamaram פְלִשְׁתִּ֗ים aos-sacerdotes e-para-os-astrólogos dizendo que foi-feito yhwh yhwh dai-nos-sabedoria com-o-que nós-enviaremos-no para-a-sua-posição');
INSERT INTO verses VALUES (7336, 9, 6, 3, 'e-disseram se enviando a arca-de Elohim-de ele a vocês-enviarão ele a-ele porque retornar vocês-retornarão a-ele a-vós então vocês-serão-curados sua-mão a-vós por-que não vire-se mão-sua de-vós');
INSERT INTO verses VALUES (7337, 9, 6, 4, 'e-disseram que o-pecado que nós-daremos a-ele e-disseram de-número príncipes-de filisteus cinco ouro e-cinco ouro ouro porque ouro uma uma e-para-vosso-soldado');
INSERT INTO verses VALUES (7338, 9, 6, 5, 'e-fareis imagens-de e-imagens-de acres-vos o-destruidores a a-terra e-dareis a-אלהים Israel glória talvez aliviar-se a mão-dele de-vos e-de Elohim de-vós e-de terra-vos');
INSERT INTO verses VALUES (7339, 9, 6, 6, 'e-porque voces-honre a para-coracoes-vos como-que honrem Mitzraim e-Pharaoh a coracoes-eles não-verdade como voces-oprimiu neles e-os-enviaram veyelechu');
INSERT INTO verses VALUES (7340, 9, 6, 7, 'e-agora tomem e-façam roda nova uma e-duas mulas sobre-as que não subiu sobre-eles sobre e-vos-amarrai a as-ovelhas com-a-carreta e-voltareis os-filhos-deles de-trás-deles a-casa-para');
INSERT INTO verses VALUES (7341, 9, 6, 8, 'e-tomareis a yhwh yhwh ele ele até- a-carreta e-את o-ouro o-ouro que a-ele a-ele pecado colocareis em-a-argaz de-o-lado-dele ele ele e-andou');
INSERT INTO verses VALUES (7342, 9, 6, 9, 'e-vistes se caminho subia ele-subirá casa ele ele fez para-nós a a-maldade a-grande não não que não sua-mão mão-dele toque-a em-nós ele ser foi para-nós');
INSERT INTO verses VALUES (7343, 9, 6, 10, 'va-yassu os-homens assim e-eles-tomaram duas pássaros subidas e-eles-vincularam-os em-a-carreta e-a nos-seus-filhos terminaram na-casa');
INSERT INTO verses VALUES (7344, 9, 6, 11, 'e-eles-colocaram a yhwh yhwh para-a a-carreta e-a o-caixote o-ouro aloevri o-ouro e-a tsalmey tchoreihem');
INSERT INTO verses VALUES (7345, 9, 6, 12, 'vayisharnah haparovot no-caminho sobre caminho casa shemesh uma uma halchu andou vegaoh e-não saru direita e-esquerda vesarney filisteus andando-os de-elles até guvul casa do-sol');
INSERT INTO verses VALUES (7346, 9, 6, 13, 'e-Beit sol ceifadores ceifa-de trigo na-vala e-tomaram a olhos-dos e-eles-viram para-ver o-arca e-alegraram-se para-ver');
INSERT INTO verses VALUES (7347, 9, 6, 14, 'e-a-carreta no-campo a campos-de Josué casa-de do-sol e-parou pedra e-ali pedra-a grande e-perfuraram-os a madeiras-de a-carreta e-a as-vacas elevaram holocausto para-יהוה');
INSERT INTO verses VALUES (7348, 9, 6, 15, 'e-os-levitas [הוֹרִ֣ידוּ] a arca yhwh e-a o-caixote que com-ele que nele-o utensilios-de- ouro [בֵֽית־שֶׁ֗מֶשׁ] a a-pedra o-grande e-homens-de no-dia sol-o elevaram ofertas-de-sacrifício e-ele-sacrificaram zvachim no-dia o-aquele para-יהוה');
INSERT INTO verses VALUES (7349, 9, 6, 16, 've-chamisha sarnei- pelishtim rau [עֶקְר֖וֹן] no-dia no-dia a-aquela');
INSERT INTO verses VALUES (7350, 9, 6, 17, 'e-estes tchoriei o-ouro que heshibu fishtim a-oferta-pelo-pequeno-erro para-יהוה [לְאַשְׁדּ֨וֹד] um para-o-Azza um para-a-Ascalom um para-a-Gat um para-o-Eqron um');
INSERT INTO verses VALUES (7351, 9, 6, 18, 'e-Achborim o-ouro mispar todo cidades-de filisteus a-Chamesheth os-sranim de-a-cidade do-fortaleza e-até Cofar o-prazí e-ate-a avel a-grande que deixaram sobre-ela a arca yhwh até o-dia este em-o-campo Yehoshua casa-de o-solitário');
INSERT INTO verses VALUES (7352, 9, 6, 19, 'e-golpeou em-homens casa-de que porque viram yhwh yhwh e-ele-feriu em-o-povo setenta homem cinquenta mil homem e-eles-se-lamentaram o-povo yhwh ele-golpeou yhwh em-o-povo golpe grande');
INSERT INTO verses VALUES (7353, 9, 6, 20, 'e-disseram homens-de casa-de quem quem pode para-estar-de-pé yhwh yhwh o-Elohim o-santo esta subia quem subirá de-acima-nos');
INSERT INTO verses VALUES (7354, 9, 6, 21, 'e-enviaram mensageiros a habitantes-de dizendo de-árvores dizendo eles-retornaram yhwh a arca ele descer-vos subi a-ele a-vós');
INSERT INTO chapters VALUES (243, 9, 7, 17);
INSERT INTO verses VALUES (7355, 9, 7, 1, 'e-vieram homens-de cidade-de árvores e-eles-subiram a arca yhwh e-ele-trouxeu ele a casa Avinadav em-Gibeá e-a Elazar filho-o consagrem-os yhwh a arca yhwh');
INSERT INTO verses VALUES (7356, 9, 7, 2, 'e-houve de-dia assento a-arca na-cidade Jearim e-ele-multiplicaram-se-os os-dias e-foram vinte ano e-ele-estabeleceram-no todo casa Israel yhwh yhwh');
INSERT INTO verses VALUES (7357, 9, 7, 3, 'E-disse Shemu''el a todo dizendo Israel dizendo se em-todo para-coracoes-vos vós voltando-se-os a yhwh retire-m-no a Elohim-de o-estrangeiro sozinho e-as-asterotes e-preparai-m-no para-o-vosso-coracao a yhwh e-servi-lo para-somente-dele vós de-mão-de filisteus');
INSERT INTO verses VALUES (7358, 9, 7, 4, 'e-retiraram-m-no filhos-de Israel a os-baalins e-a as-asterotes sozinho a yhwh para-ele-somente');
INSERT INTO verses VALUES (7359, 9, 7, 5, 'E-disse שְׁמוּאֵל reunam-se a todo Israel a-montanha [אֶל־יְהוָֽה] em-vos-a-vez-de a yhwh');
INSERT INTO verses VALUES (7360, 9, 7, 6, 'e-reuniram-se a-montanha e-apa-receram-se águas e-despejaram-se diante-de yhwh e-jejumaram-se no-dia aquele e-disseram nome pecamos a-yhwh e-julgou Samuel a filhos-de Israel em-o-monte-Mispa');
INSERT INTO verses VALUES (7361, 9, 7, 7, 'e-ouviram פְלִשְׁתִּ֗ים porque reunem-se filhos-de Israel da-monte-Mispa e-eles-subiram sarnei- Filisteus a Israel de-diante-de filhos-de Israel e-viram de-faces-de Filisteus');
INSERT INTO verses VALUES (7362, 9, 7, 8, 'e-disseram filhos-de Israel a nós a se-cala dele de-grito a yhwh Elohim-nosso e-nos-salvará de-mão-de filisteus');
INSERT INTO verses VALUES (7363, 9, 7, 9, 'E-tomou Shmu''el ovelha leite um subida inteiro para-יהוה e-ele-gritou Shemu''el a yhwh através-de Israel e-ele-respondeu-lhe yhwh');
INSERT INTO verses VALUES (7364, 9, 7, 10, 'e-houve Samuel subindo a-oferta e-filisteus chegaram para-a-guerra em-Israel e-os-espantou yhwh com-a-voz-de grande no-dia o-aquele sobre filisteus e-os-confundiu e-os-golpearam diante-de Israel');
INSERT INTO verses VALUES (7365, 9, 7, 11, 'e-saíram homens-de Israel de da-montanha-da-espera e-perseguiram a filisteus e-os-feriram até de-debaixo-de segundo-casa-de car:');
INSERT INTO verses VALUES (7366, 9, 7, 12, 'E-tomou Shemuel pedra uma e-ele-colocou entre e-entre e-entre E-chamou E-chamou pedra shema-ha- eben ha-azer E-disse yhwh henah yhwh');
INSERT INTO verses VALUES (7367, 9, 7, 13, 'va-yikkanevu os-filisteus e-não yaspu ainda para-vir em-limite-de Israel e-foi mão-de yhwh dias-de todo dias-de Shemuel:');
INSERT INTO verses VALUES (7368, 9, 7, 14, 'vata-shovenah as-cidades que tomaram-o os-filisteus de-a israel para-o-Israel de-akezon e-até gat e- gebulan salvou Israel e-houve filisteus entre paz e-entre Israel e-entre o-amorreu');
INSERT INTO verses VALUES (7369, 9, 7, 15, 'e-julgou Samuel a Israel dias-de dias-de vida-dele');
INSERT INTO verses VALUES (7370, 9, 7, 16, 'e-andou desde ano em-anos e-rodou casa-de El e-o-gigirl e-a-Mispá e-julgou a Israel a todo os-lugares as estas');
INSERT INTO verses VALUES (7371, 9, 7, 17, 'e-sua-resposta a-Ramathah porque nome casa-dele e-ali julgou a Israel e-ele-construiu nome altar para-יהוה');
INSERT INTO chapters VALUES (244, 9, 8, 22);
INSERT INTO verses VALUES (7372, 9, 8, 1, 'e-houve como-que velho Samuel e-ele-posto a os-filhos-dele juízes para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (7373, 9, 8, 2, 'e-houve nome- filho-o o-primogênito Yoel e-nome-de de-seu-igual Abiá-a juízes em-a-fonte sete');
INSERT INTO verses VALUES (7374, 9, 8, 3, 'e-não halchu seus-filhos e-ele-viraram depois-de o-prejuízo e-eles-tomaram- suborno e-ele-virou-se juízo');
INSERT INTO verses VALUES (7375, 9, 8, 4, 'e-eles-se-agruparam todo anciãos-de Israel e-vieram a שְׁמוּאֵל a-altura');
INSERT INTO verses VALUES (7376, 9, 8, 5, 'e-disseram a-ele eis tu você-envelheceu e-seus-filhos não foram em-tuas-estradas agora põe-a para-nos rei para-julgar-nos conforme-toda os-gentios');
INSERT INTO verses VALUES (7377, 9, 8, 6, 'e-mal a-palavra em-olhos-de שְׁמוּאֵל como-que disseram dá- para-nos rei para-julgar-nos e-ele-orou שְׁמוּאֵל a yhwh');
INSERT INTO verses VALUES (7378, 9, 8, 7, 'E-disse yhwh a שְׁמוּאֵל ouviu com-voz a-todo para-todo que que não porque não o-te rejeitaram porque me desdenharam-os de-reinar sobre-eles');
INSERT INTO verses VALUES (7379, 9, 8, 8, 'como-todo- os-trabalhos que fizeram eles a-subida-meu eles de-Egito e-até o-dia este e-eles-me-abandonaram e-serviram Elohim outros assim eles fazendo também para-ti');
INSERT INTO verses VALUES (7380, 9, 8, 9, 'e-agora ouviu com-a-sua-voz então porque o-testemunho testificará neles a-eles a-eles juízo o-rei que ele-reinará sobre-eles');
INSERT INTO verses VALUES (7381, 9, 8, 10, 'E-disse שְׁמוּאֵל a todo yhwh yhwh a o-povo os-que-peguem-em-loan de-com-ele rei');
INSERT INTO verses VALUES (7382, 9, 8, 11, 'E-disse este será juízo o-rei que ele-reinará sobre-vós a filhos-vossos ele-tomará a-ele a-ele em-a-carroça-dele e-em-os-cavaleiros e-corram diante-de o-carro-dele');
INSERT INTO verses VALUES (7383, 9, 8, 12, 'e-para-pôr a-ele príncipes-de dois-mil e-príncipes-de cinquenta e-para-arar a-aragem-dele e-para-colher o-campo-dele e-para-fazer os-ferramentas-de a-guerra-dele e-vessãis carros-eu');
INSERT INTO verses VALUES (7384, 9, 8, 13, 'e-a filhas-vos tomar-ah para-farmaceuticos-os e-para-cozinheiros-as e-para-padeiros-os');
INSERT INTO verses VALUES (7385, 9, 8, 14, 'e-a campos-vos e-a vinhas-vos ve''zitechem hatovim tomar-ah e deu-lhes para-servos-seus');
INSERT INTO verses VALUES (7386, 9, 8, 15, 'sementes-vossas vossos-plantios separará e colocou aos eunucos e aos servos-vossos:');
INSERT INTO verses VALUES (7387, 9, 8, 16, 'e-a abdas-vosso e-a sifchat-vossas e-a jovens-vosso os-boas e-a asinos-vosso tomará e-fará para-o-trabalho-seu');
INSERT INTO verses VALUES (7388, 9, 8, 17, 'rebanhos-vosso separará e-vós serão- a-ele para-servos');
INSERT INTO verses VALUES (7389, 9, 8, 18, 'e-clamareis no-dia aquele de-diante-de vossos-reis que e-vós-escolhestes a-vós e-não yhwh yhwh no-dia no-dia a-aquela');
INSERT INTO verses VALUES (7390, 9, 8, 19, 'o-povo para-ouvir com-voz Samuel e-disseram não porque que rei será sobre-nós');
INSERT INTO verses VALUES (7391, 9, 8, 20, 'e-nos-seremos também nós-mesmos conforme-toda as-nações e-julgareis-nos re-no-sseu e-sairá diante-de-nós e-lutaremos a guerras-nossas');
INSERT INTO verses VALUES (7392, 9, 8, 21, 'E-ouviu שְׁמוּאֵל a todo palavras-de o-povo e-disse-os yhwh yhwh');
INSERT INTO verses VALUES (7393, 9, 8, 22, 'E-disse yhwh a Samuel ouviu em-a-sua-voz a-eles a-eles E-disse E-disse Samuel a homens-de Israel ide homem para-cidade-sua');
INSERT INTO chapters VALUES (245, 9, 9, 27);
INSERT INTO verses VALUES (7394, 9, 9, 1, 'e-foi homem e-seu-nome quish filho-de abi-eil filho-de tzror filho-de de-a-primeira-filha filho-de afich filho-de homem da-minha-direita poderoso força');
INSERT INTO verses VALUES (7395, 9, 9, 2, 'e-para-ele- foi filho e-seu-nome Saul jovem-moço e-bom e-não-há homem de-filhos-de bom nós de-ele de-o-seu-lado e-para-cima alta-alta de-todo o-povo');
INSERT INTO verses VALUES (7396, 9, 9, 3, 'e-perderam-se-as as-jumentas cavalos pai-de שָׁאוּל E-disse cavalo a Saul filho-seu toma por-favor contigo a um de-os-jovens e-levante-se vá pequisar a as-jumentas');
INSERT INTO verses VALUES (7397, 9, 9, 4, 'e-passou em-monte-de Efraim e-ele-passou em-terra-de terceira e-não encontraram e-eles-passaram em-terra- de-hasteiras e-não e-ele-passou em-terra-de direita-mi e-não acharam');
INSERT INTO verses VALUES (7398, 9, 9, 5, 'eles vieram em-terra-de tsof e-shaul disse para-jovem-seu que com-ele vem e-voltaremos para-que-não cessará meu-pai de as-juntas-as-amelexes-seu e-preocupar-se para-nós');
INSERT INTO verses VALUES (7399, 9, 9, 6, 'E-disse a-ele eis-que- por-favor homem-de Elohim na-cidade a-esta e-o-homem nobre trazer que ele-falará vem virá agora iremos nome talvez dirá para-nós a nosso-caminho que andamos sobre-ela');
INSERT INTO verses VALUES (7400, 9, 9, 7, 'E-disse Saul para-a-jovem e-eis iremos e-que profeta que porque o-pão partiu de-nossos-macios e-rodela não-há para-trazer a homem-de o-Elohim que com-nos');
INSERT INTO verses VALUES (7401, 9, 9, 8, 'e-ele-aumentou o-menino para-responder a E-disse eis behold foi-achado em-minha-mão quarto sheqel- prata e-n-d-e-rei a homem-de o-Elohim e-h-i-g-u-r para-nós a d-a-r-c-k-h-n-u');
INSERT INTO verses VALUES (7402, 9, 9, 9, 'l-e-f-a-n-i-m b-y-i-s-r-a-e-l assim disse o-homem b-l-e-k-t-h-o l-i-d-r-o-sh Elohim para-voces-andem e-n-e-l-c-h-a até que porque o-dia será-chamada será-chamado antes h-a-r-o-e');
INSERT INTO verses VALUES (7403, 9, 9, 10, 'E-disse s-h-a-u-l para-o-jovem bom de-tua-palavra vamos nós-andemos e-andaram a a-cidade que nome homem Elohim');
INSERT INTO verses VALUES (7404, 9, 9, 11, 'eles subindo em-a-ascensão a-cidade e-eles encontraram jovens saindo para-sugar águas e-disseram a-elas há-é em-isso o-vendo');
INSERT INTO verses VALUES (7405, 9, 9, 12, 'e-responderam a-eles e-disseram há eis diante-de-ti apressar-se agora porque que o-dia para-a-cidade porque que o-dia o-dia na-câmara');
INSERT INTO verses VALUES (7406, 9, 9, 13, 'kevo-achem a-cidade assim encontrareis ele antes-de subia a-plataforma para-comer que não ele-comes o-povo até ele ele abençoará o-sacrifício depois-de assim e-agora os-chamados e-agora subam porque ele como-o-dia encontrareis a-ele');
INSERT INTO verses VALUES (7407, 9, 9, 14, 'e-ele-levantaram-se a-cidade eles os-vindo no-meio-de a-cidade e-eis Samuel sai para-eles para-subir a-plataforma');
INSERT INTO verses VALUES (7408, 9, 9, 15, 'e-יהוה revelou a o-ouvido dia um um diante-de dizendo emprestado para-dizer');
INSERT INTO verses VALUES (7409, 9, 9, 16, 'como-a-hora amanhã eu-enviarei a-você homem da-terra Benjamim e-o-ungerá para-governante sobre meu-povo Israel e-ele-salvará a povo-meu de-mão-de que porque vi que povo-meu porque veio-a de-seu-clamor para-mim');
INSERT INTO verses VALUES (7410, 9, 9, 17, 'e-Samuel ver a שָׁאוּל e-יהוה eis eis o-homem que eu-disse para-ti este restringe em-o-povo-meu');
INSERT INTO verses VALUES (7411, 9, 9, 18, 'e-veio-aproximar-se Shaul a no-meio-de em-meio-de E-disse E-disse diga-a agora a-mim qual este casa o-vendo');
INSERT INTO verses VALUES (7412, 9, 9, 19, 'e-ele-respondeu Shmu''el a E-disse eu eu folhas-de vem diante-de-mim a-altar e-comereis o-dia o-dia e-enviarei-te e-tudo e-todo que com-o-coracao-tu para-ti para-ti');
INSERT INTO verses VALUES (7413, 9, 9, 20, 'e-as-jumentas as-perdidas a-ti o-dia três-de os-dias a colocarás a-eles que a-eles porque foram-encontrados e-a-quem todo a-ti Israel não para-ti e-a-todos casa pai-teu');
INSERT INTO verses VALUES (7414, 9, 9, 21, 'e-ele-respondeu Saul E-disse porventura-não filho-de eu eu-sou do-menores tribos-de Israel e-da-minha-família a-pequena de-todo famílias-de-as tribos-de Benjamim e-por-que falaste a-mim de-a-palavra a-esta');
INSERT INTO verses VALUES (7415, 9, 9, 22, 'E-tomou Samuel a Saul e-com jovem-de ele E-colocou a-eles lugar para-eles lugar na-cabeça os-chamados e-eles trinta homem');
INSERT INTO verses VALUES (7416, 9, 9, 23, 'E-disse Samuel para-o-tabelião dará a o-número dei para-ti a-ti que eu-disse a-ti colocar a-ela contigo');
INSERT INTO verses VALUES (7417, 9, 9, 24, 'e-ele-levantou o-tabelião a ha-shok e-ha-ealehah ve-yasem diante-de Saul E-disse eis o-que-restou sim- diante de ti que porque para-o-festival dizendo para-ti para-dizer o-povo e-comeu e-comesse Shaul no-dia שְׁמוּאֵל no-dia a-aquela');
INSERT INTO verses VALUES (7418, 9, 9, 25, 'וירדוּ da-plataforma a-cidade e-falou com emprestado sobre o-teto');
INSERT INTO verses VALUES (7419, 9, 9, 26, 'e-eles-levantaram-se e-houve quando-subiu o-alvorde E-chamou Shemu''el a Saul dizendo dizendo e-eu-te-enviarei E-levantou שָׁאוּל e-eles-saíram os-dois ele ele para-a-fora');
INSERT INTO verses VALUES (7420, 9, 9, 27, 'eles descendo-os em-extremidade a-cidade e-Shemu''el disse a שָׁאוּל disse para-o-jovem e-passar diante-nos e-ele-passou e-tu ficou-em-pé como-o-dia e-farei-som-te a palavra Elohim');
INSERT INTO chapters VALUES (246, 9, 10, 27);
INSERT INTO verses VALUES (7421, 9, 10, 1, 'E-tomou שְׁמוּאֵ֜ל a vaso do-óleo e-ele-esguichou sobre E-disse e-o-beijou-ele E-disse yhwh porque de-ungiu-te yhwh sobre a-herança-seu para-o-príncipe');
INSERT INTO verses VALUES (7422, 9, 10, 2, 'em-a-andada-teu o-dia de-a-partida-mim e-achou-tu segundo homens com a-gravura Raquel na-montanha Benjamim Betzeltzach e-disseram a-ti n-imtza-u ha-atonot que halachtah le-baqesh e-eis natash teu-pai a palavras-de a-vós dizendo para-vocês dizendo que eu-farei para-meu-filho');
INSERT INTO verses VALUES (7423, 9, 10, 3, 've-chalaptah de-lá va-hala-ah e-vindo-a até Elom Tabor e-achando-te nome três homens subindo a um casa-de El um no-sê- três ovelhas-grosas e-um levando-o pão bolos-de-massas Belém flabelo- yayin:');
INSERT INTO verses VALUES (7424, 9, 10, 4, 'e-perguntarão a-ti para-paz e-darão a-ti duas- Belém e-lakachta de-suas-mãos');
INSERT INTO verses VALUES (7425, 9, 10, 5, 'depois sim virá colina-de os-Elohim que nome oficiais e-seja E-foi em-vos nome a-cidade e-ateis região-de profetas descendo de-a-bamah e-ante-eles tamborim e-tom e-flauta e-a-cítara e-eles de-profetas-:');
INSERT INTO verses VALUES (7426, 9, 10, 6, 'e-se-rejou sobre-ti espírito yhwh e-te-profetizaste עִמָּם e-foste-invertido- para-um outro');
INSERT INTO verses VALUES (7427, 9, 10, 7, 'e-foi que as-sinais estes a-ti fez para-ti que a-ti mão-tua porque o-Elohim que');
INSERT INTO verses VALUES (7428, 9, 10, 8, 'e-descenderás- em-frente-a-mim- o-gilgal- e-eis eu descendo-é a-ti para-levar-acima holocaustos para-sacrificar zibchei paz sete dias touhel até boi para-ti a-ti para-ti a que farás');
INSERT INTO verses VALUES (7429, 9, 10, 9, 'e-foi keh-hafnoto shikmo para-andar de-com שְׁמוּאֵל vaya''hafakh- para-ele Elohim coração acher and-they-entered todo no-dia estes no-dia a-aquela');
INSERT INTO verses VALUES (7430, 9, 10, 10, 'וַיָּבוּ nome hagib''ataha e-eis chevel- os-profetas likrato vatitzlakh espírito espirito Elohim e-ele-proferiu em-meio-de-eles');
INSERT INTO verses VALUES (7431, 9, 10, 11, 'e-houve todo sabe-o de-ontem antes-de-ontem e-eles-viram e-eis com E-disse profetizou E-disse o-povo homem ser companheiro-seu que isto foi para-filho-de קיס também emprestado nos-profetas');
INSERT INTO verses VALUES (7432, 9, 10, 12, 'e-ele-respondeu homem de-lá E-disse e-quem de-seu-pai sobre era ela-foi para-exemplo também emprestado nos-profetas');
INSERT INTO verses VALUES (7433, 9, 10, 13, 'E-terminou de-profetizar E-veio a-plataforma');
INSERT INTO verses VALUES (7434, 9, 10, 14, 'E-disse Davi Saul a-ele e-a seu jovem onde E-disse E-disse para-buscar a as-atonot e-nos-vimos porque não-há e-nos-vimos a Shemuel:');
INSERT INTO verses VALUES (7435, 9, 10, 15, 'E-disse Davi שָׁאוּל diga-a agora a-mim a-vós disse para-vocês Shemuel:');
INSERT INTO verses VALUES (7436, 9, 10, 16, 'E-disse Saul a seu-tio declarou disse-ele que porque nos-encontramos as-as-negras e-a palavra a-ele não disse a-ele que disse Shemuel:');
INSERT INTO verses VALUES (7437, 9, 10, 17, 'vayatz''ek Samuel a o-povo a yhwh hamatzpah');
INSERT INTO verses VALUES (7438, 9, 10, 18, 'E-disse a filhos-de Israel assim disse yhwh Elohim-de Israel eu eu-levantei a Israel de-Egito e-eu-salvei vos de-mão-de Egito e-mi-yad todo as-mamlekhót ha-lochatzim a-vós');
INSERT INTO verses VALUES (7439, 9, 10, 19, 'e-vós o-dia me-asstem a אֱלֹהִים-vo/ós que a-vós moshi''a la-chem de-todo a-ele ve-tsaro-teichem va-tomeru a-ele e-agora rei põe yhwh e-agora hit-yatzvu diante-de yhwh le-sheveteychem u-le-alpeichem');
INSERT INTO verses VALUES (7440, 9, 10, 20, 'e-ele-se-aproximou שְׁמוּאֵל a todo tribos-de Israel e-ele-capturou-se bastão Benjamin');
INSERT INTO verses VALUES (7441, 9, 10, 21, 'va-yakrev a tribo-de benjamita e-foi-retido de-família a-chuva e-foi-retido Saul filho-de Kiš e buscarem-no e-não foi achado:');
INSERT INTO verses VALUES (7442, 9, 10, 22, 'e perguntaram- ainda em-יהוה vem ainda não homem E-disse yhwh eis-que- ele foi escondido a os vasos:');
INSERT INTO verses VALUES (7443, 9, 10, 23, 'e correram e levaram-no de-lá e se estabeleceu no-meio-de o-povo e se exaltou de-todo o-povo de sua mão e-para-cima');
INSERT INTO verses VALUES (7444, 9, 10, 24, 'E-disse Shemuel a todo o-povo haraitem yhwh que nele-o yhwh porque não-há como-ele em-todo o-povo e-eles-se-curvaram todo o-povo e-disseram viva o rei');
INSERT INTO verses VALUES (7445, 9, 10, 25, 'e-falou Shemuel a o-povo a juízo a-realeza e-escreveu no-livro e-ele-deixou yhwh yhwh e-ele-enviou Samuel a todo o-povo homem para-sua-casa');
INSERT INTO verses VALUES (7446, 9, 10, 26, 'וְגַ֨ם־ andar andou a seu lar Gibeá e-andaram com-ele [אֲשֶׁר־נָגַ֥ע] que- toque Elohim em-os-coracoes-verso-final');
INSERT INTO verses VALUES (7447, 9, 10, 27, 'e-filhos-de sem-beneficio אָמְר֗וּ que salvando-nos este e-eles-o-escarneceram a-ele trouxeram e-houve oferta E-foi como-silencioso-verso-final');
INSERT INTO chapters VALUES (247, 9, 11, 15);
INSERT INTO verses VALUES (7448, 9, 11, 1, 'e-subiu  נחש  o-ammonita וַיִּחָנֶ֖ה sobre secou-se  Galaad e-disseram todo homens-de [כְּרָת־לָ֥נוּ] a serpente cortando- para-nós berith e-adoraremos-te');
INSERT INTO verses VALUES (7449, 9, 11, 2, 'E-disse a-eles  נחש  o-amônita nisto eu-cortarei a-vós em-o-perfurador a-vós todo olho direito e-colocarei-a humilhação sobre todo Israel');
INSERT INTO verses VALUES (7450, 9, 11, 3, 'e-disseram a-ele anciãos-de vergonha levantou-se a-nós sete-de e será lançada mensageiros em-todo território Israel e-se não-há salvador a-nós וְיָצָ֥אנוּ para-ti');
INSERT INTO verses VALUES (7451, 9, 11, 4, 'וַיָּבוּ ha-mal-akh-im colina-de Shaul va-yed-ab-bru as-palavras em-orelhas-de o-povo va-yis-sa-u todo o-povo a voz-deles e-choraram');
INSERT INTO verses VALUES (7452, 9, 11, 5, 'e-eis שָׁאוּל veio depois-de o-bovino de E-disse E-disse Shaul que la-a-am porque yi-bku e-contaram a-ele a palavras-de homens-de ya-be-ish');
INSERT INTO verses VALUES (7453, 9, 11, 6, 'va-titz-la-ha espírito-de Elohim sobre Shaul a as-palavras estas se encolerizou muito muito');
INSERT INTO verses VALUES (7454, 9, 11, 7, 'E-tomou cemed manhã e o dividiu e enviou em-todo território Israel em-mão-de os anjos dizendo que não há sai depois-de Saul e-apos שְׁמוּאֵל assim será-fazido para visitá-lo e caiu medo- yhwh sobre o-povo um como-homem um');
INSERT INTO verses VALUES (7455, 9, 11, 8, 'e-contou-os be-bazek e-foram filhos-de Israel três centenas-de mil e-homem Judá trinta mil');
INSERT INTO verses VALUES (7456, 9, 11, 9, 'e-eles-disseram la-malakhim ha-va''im assim tomru-n para-homem Jabes Gileade ma-char ser-á para-vós salvação o-sol e-vieram os-anjos e-eles-disseram para-os-homens-de Yabesh e-eles-se-alegraram');
INSERT INTO verses VALUES (7457, 9, 11, 10, 'וַֽיֹּאמְרוּ֙ homens-de vergonha-se amanhã sair-ei a-vós e faréis para-nos conforme-toda o-bom nosso-em-vossos:');
INSERT INTO verses VALUES (7458, 9, 11, 11, 'e-houve da-o e-ele-postou Saul a o-povo três cabeças וַיָּבוּ em-o-centro-de- o-acampamento em-Ashmorah a-manhã e-eles-feriram o-dia e-houve até raiva o-dia E-foi os sobreviventes e-eles-se-espalharam e-não eles-se-deram-como-restos neles dois juntos');
INSERT INTO verses VALUES (7459, 9, 11, 12, 'E-disse o-povo a quem quem o-dizendo Saul reinará sobre-nós deite os-homens e-eu-matarei-vos');
INSERT INTO verses VALUES (7460, 9, 11, 13, 'E-disse Saul não será morta no-dia no-dia que o-dia o-dia fez yhwh salvação em-Israel');
INSERT INTO verses VALUES (7461, 9, 11, 14, 'E-disse Samuel a o-povo ide e-nos-caminharemos o-gilgal e-nhadash nome o-reino');
INSERT INTO verses VALUES (7462, 9, 11, 15, 'e-elechu todo o-povo o-gilgal e-eymalkhu nome a yhwh diante-de yhwh em-o Gilgal e-sacrificaram nome yhwh paz diante-de yhwh e-eisamach nome Shaul e-todo homens-de Israel até muito');
INSERT INTO chapters VALUES (248, 9, 12, 25);
INSERT INTO verses VALUES (7463, 9, 12, 1, 'E-disse Samuel a eis Israel behold a-todo em-kolchekhem para-todo que אֲמַרְתֶּ֖ם a-mim ve-ameleich sobre-vós rei');
INSERT INTO verses VALUES (7464, 9, 12, 2, 'e-agora eis o-rei me-tehallek passeando e-eu zaqantiti e-sentei-me e-filhos-de-mim eis-os convosco e-eu andei diante-de-vós de-juventude-minha até o-dia a-esta');
INSERT INTO verses VALUES (7465, 9, 12, 3, 'eis-me responder-vós em-mim diante yhwh e-diante-de mashiycho a boi- quem tombei-eu e-jumento quem tombei-eu e-a quem [אֶת־מִ֣י] a quem desejando e-imediatamente- de-quem tomei propina e-esconder-ei a-vós nele e-devolver-ei para-vocês');
INSERT INTO verses VALUES (7466, 9, 12, 4, 'e-disseram não oprimistes-nos e-não desejastes-nos e-não tomaste da-mão- homem qualquer-coisa');
INSERT INTO verses VALUES (7467, 9, 12, 5, 'E-disse a-eles até yhwh בָּכֶ֗ם e-o-testemunho o-mesias-seu o-dia esta que não encontraram-vos em-a-mão-meia verdadeiramente E-disse até');
INSERT INTO verses VALUES (7468, 9, 12, 6, 'E-disse שְׁמוּאֵל a yhwh yhwh que fez a Moisés e-com Arão e-que He''ala a pais-vosso de-terra-de Egito');
INSERT INTO verses VALUES (7469, 9, 12, 7, 'e-agora estabelecer-se-eis e-julgarei-eu com-vocês diante-de yhwh a todo yhwh yhwh que fez com-vocês e-a vosso avós:');
INSERT INTO verses VALUES (7470, 9, 12, 8, 'quando veio Jacó Egito e-clamaram pais-vosso a yhwh e-enviou yhwh a Moisés e-com Arão e-saíram-eles a pais-vossos de-o-Egito e-estabeleceram-no no-lugar a-esta');
INSERT INTO verses VALUES (7471, 9, 12, 9, 'e-esqueceram a yhwh elohim-deles eles אֹתָ֡ם em-mão-de Sísra príncipe-de tzva chatzor e-em-mão- pelisthim e-em-a-mão rei Moabe e-lutaram em-eles');
INSERT INTO verses VALUES (7472, 9, 12, 10, 'e-clamaram a yhwh chatanu porque que a yhwh vannaabad a os-baalins e-agora haastorot e-agora hatzilenu de-mão-de oyveinu venaaddekha');
INSERT INTO verses VALUES (7473, 9, 12, 11, 'e-estendeu yhwh a יְרֻבַּ֣עַל e-a b''dan e-a yif''tach e-a Samuel va-yatzel a-vós מִיַּ֤ד o''yev''chem de-ao-redor e ficaram betach');
INSERT INTO verses VALUES (7474, 9, 12, 12, 'va-tireu porque nachash rei filhos-de amom veio aleichem não a-mim não porque rei reinará sobre-nós v''yhwh Elohim de-vós melechem');
INSERT INTO verses VALUES (7475, 9, 12, 13, 'e-agora eis o-rei que e-vós-escolhestes que perguntastes e-eis dar yhwh sobre-vós rei');
INSERT INTO verses VALUES (7476, 9, 12, 14, 'se temereis a ele e-serveis ele e-ouvis em-voz-dele e-não yhwh a boca-de yhwh e-sei-reis também vocês e-também yhwh que rei em-vos depois yhwh Elohim-vosso');
INSERT INTO verses VALUES (7477, 9, 12, 15, 'e-se não vocês-ouvirão yhwh yhwh e-estardes yhwh boca-de yhwh e-será mão-de yhwh vocês e-em-vossos-pais');
INSERT INTO verses VALUES (7478, 9, 12, 16, 'também agora estai-vos e-vedei a a-palavra o-grande yhwh que yhwh fez diante-de-olhos-vossos');
INSERT INTO verses VALUES (7479, 9, 12, 17, 'não ceifa-de o-dia o-dia chamarei a yhwh E-deu vozes e neve e-conheçam e-vejam porque maldade-vos multiplicai yhwh fazeis a-vós yhwh para-pedir para-vocês rei');
INSERT INTO verses VALUES (7480, 9, 12, 18, 'E-chamou Samuel a E-colocou yhwh yhwh vozes no-dia em-o-dia o-aquele e-tremeu muito o-povo muito a yhwh e-a Shemuel:');
INSERT INTO verses VALUES (7481, 9, 12, 19, 'e-disseram todo o-povo a Shemu''el ele-orou em-nome-de servos-teus a yhwh teu-Elohim e-a que-nós-moirtemos porque e-continuaram sobre todo nosso-pecado maldade para-solicitar para-nós rei');
INSERT INTO verses VALUES (7482, 9, 12, 20, 'E-disse Shemu''el a o-povo a vós-temais vós que-fizessem a todo o-mal esta yhwh a e-voltaram-se de-depois-de yhwh e servireis a yhwh em-todo no vosso coração:');
INSERT INTO verses VALUES (7483, 9, 12, 21, 'e-não considerai-vos que depois-de aquele vazio que não façam e-não salvem porque sem-forma eles');
INSERT INTO verses VALUES (7484, 9, 12, 22, 'que não yhwh yhwh a povo-seu por-causa-de que aquele grande yhwh quis yhwh a-ele a-vós para-ele para o povo:');
INSERT INTO verses VALUES (7485, 9, 12, 23, 'também eu que-não-seja a-mim de-pecar a-yhwh de-tremelique para-se-afastar em-vosso-lugar e-eu-ensinarei vos em-a-caminho hatovah e-a-retidão');
INSERT INTO verses VALUES (7486, 9, 12, 24, 'somente yire''u a yhwh va-avadtem ele be-emet em-todo que porque re''u a que higdil com-vos');
INSERT INTO verses VALUES (7487, 9, 12, 25, 'e-se o-mal vós-proferireis também vós também seu-rei vocês-sarão');
INSERT INTO chapters VALUES (249, 9, 13, 23);
INSERT INTO verses VALUES (7488, 9, 13, 1, 'filho-de ano Saul em-seu-reinado e-duas-de dois rei sobre Israel');
INSERT INTO verses VALUES (7489, 9, 13, 2, 'e-ele-escolheu-para-o a-ele Saul três-de אלפים֮ de-israel e-eles-foram com Saul duzentos em-micmas e-no-har casa-de El e-um-mil foram com jonathan em-gibeate Benjamim e-Yetzer o-povo enviou homem לְאֹהָלָֽיו׃');
INSERT INTO verses VALUES (7490, 9, 13, 3, 'e-feriu יוֹנָתָן a נְצִ֤יב filisteus que בְּגֶ֔בַע וַֽיִּשְׁמְע֖וּ filisteus וְשָׁאוּל֩ תָּקַ֨ע בַּשּׁוֹפָ֤ר em-todo dizendo dizendo ouvirão os hebreus:');
INSERT INTO verses VALUES (7491, 9, 13, 4, 'e-todo Israel dizendo dizendo bateu Saul a Netziv filisteus e-também Israel Ba-Pelishtim e-eles-clamaram o-povo atrás-de emprestado o-Gilgal');
INSERT INTO verses VALUES (7492, 9, 13, 5, 'e-fois foram-reunidos para-lutar com Israel trinta mil רֶ֙כֶב֙ e-sesset milhares pastores e-povo como-areia que sobre da-boca-de o-mar em-abundância e-ele-subiram ao-oriente-de em-mikmas na-ante-parte casa iniquidade');
INSERT INTO verses VALUES (7493, 9, 13, 6, 'e-homem Israel viram que angústia que porque e-se-aproximou o-povo e-eles-esconderam-se o-povo em-as-cavernas e-em-os-estandartes e-em-os-pedregulhos e-em-os-estercos e-em-as-trincheiras');
INSERT INTO verses VALUES (7494, 9, 13, 7, '-and-Ebri- -passed-over a terra terra Gad e Gileade e Saulo ainda-ele no Gilgal e-todo o-povo temiam atrás-dele');
INSERT INTO verses VALUES (7495, 9, 13, 8, 'sete dias para-o-moead que שְׁמוּאֵל e-não veio שְׁמוּאֵל a-gilgal e-dispersou o-povo dele');
INSERT INTO verses VALUES (7496, 9, 13, 9, 'E-disse Shaul a-gishu a-mim a-holocausto e-o-sacrifício-de-paz e-ele-subiu a-elevação');
INSERT INTO verses VALUES (7497, 9, 13, 10, 'e-houve quando ele acabasse para-levar-acima a-holocausto e-eis שְׁמוּאֵל veio e-ele-saiu Shaul para-o-encontro-dele para-ben-lo');
INSERT INTO verses VALUES (7498, 9, 13, 11, 'E-disse שְׁמוּאֵל que fizeste E-disse Shaual porque vi porque nafatz o-povo de-aloai e-tu não veata para-moead os-dias e-filisteus reunidos de-ferro-verso');
INSERT INTO verses VALUES (7499, 9, 13, 12, 'e-disse agora descerão fishtim a-mim o-Gilgal e-faces-de yhwh não comecei-eu e-me-apaguei e-subi a-elevação');
INSERT INTO verses VALUES (7500, 9, 13, 13, 'E-disse Samuel a emprestado não não shamartha yhwh de-mandamento yhwh Elohim-teu que mandaste-tu porque yhwh preparou yhwh a teu-reino a Israel até eternidade');
INSERT INTO verses VALUES (7501, 9, 13, 14, 'e-agora teu-reino não arrebataram-se yhwh a-ele a-ele homem com-seu-coracao yhwh yhwh para-governante que não porque não guardaste yhwh que cum-pronunciaste yhwh');
INSERT INTO verses VALUES (7502, 9, 13, 15, 'E-levantou Shemu''el e-subiu de o-Gilgal colina-de Binyamin e-ele-contou שָׁאוּל a o-povo os-que-foram-encontrados com-ele seis centenas homem');
INSERT INTO verses VALUES (7503, 9, 13, 16, 'e-Saul e-Jonatan filho-seu e-o-povo que estava com-eles habitavam em-Gibea Binyamin e-filisteus acamparam em-mesha''');
INSERT INTO verses VALUES (7504, 9, 13, 17, 'e-ele-saiu o-destruidor de-acampamento-de dos-filisteus três cabeças-de o-cabo um virá a caminho para-a-terra a terra raposa''');
INSERT INTO verses VALUES (7505, 9, 13, 18, 'e-a-cabeça um virá o-caminho-de casa a-corda e-a-cabeça um virá o-caminho-de o-limite o refletido sobre os as aves o deserto');
INSERT INTO verses VALUES (7506, 9, 13, 19, 'e o forjador não היה מוצא em-todo terra Israel porque filisteus para que para-que-não os hebreus espada espada o ferrete');
INSERT INTO verses VALUES (7507, 9, 13, 20, 'e desceram todo Israel os filisteus para espoliar homem a sua macharas e-a nele e-a seu cardom e-a sua machares');
INSERT INTO verses VALUES (7508, 9, 13, 21, 'e seria a pessara pímes para as machares e para os aetim e-lis-hoś qil-lośh u-lē-ha-qar-dōm-im u-lē-ha-tsīb ha-dār-bān');
INSERT INTO verses VALUES (7509, 9, 13, 22, 'e-foi no-dia mil-ḥēmet e-não nim-tsa'' espada va-ḥāniṭ na-mão-de todo o-povo que a Saul e-a yo-nāt-an vat-tim-mats-ē'' לְשָׁא֔וּל וּלְיוֹנָתָ֖ן filho-seu');
INSERT INTO verses VALUES (7510, 9, 13, 23, 'e-saiu fundamento filisteus a passagem de-machado');
INSERT INTO chapters VALUES (250, 9, 14, 52);
INSERT INTO verses VALUES (7511, 9, 14, 1, 'e-houve o-dia E-disse יונתן filho-de Saul a o-menino levando-o seus-vesséis vem e-nos-passaremos a posto filisteus que não declarou e-a-seu-pai não disse');
INSERT INTO verses VALUES (7512, 9, 14, 2, 'e-Saul habitante- em-extremidade das colinas debaixo o-rimona que em-migron e-o-povo que com-ele keshet centenas homem');
INSERT INTO verses VALUES (7513, 9, 14, 3, 'e-ahiahu filho-de achituv o-irmão ikavod filho-de finchas filho-de Eli yhwh yhwh em-shiloh levando-o epód não saber que andar andou jonatan');
INSERT INTO verses VALUES (7514, 9, 14, 4, 'e-entre ha-ma''abrot que bikesh jonatan la''avor sobre matzav filisteus shen- ha-sela me-ha''ever deste-lado e-dente- o-sela o-primeiro deste ve-shem o-primeiro que-partiu e-nome-de o-único seneh:');
INSERT INTO verses VALUES (7515, 9, 14, 5, 'o shén o-primeiro precioso do norte em-face-de de-mais e o um do-negueb mül gávā''');
INSERT INTO verses VALUES (7516, 9, 14, 6, 'E-disse Yehonatan a o-jovem levando-o seus-vessōis לְכוּ e-nos-passaremos a lugar-de os-impuros os-estes talvez yhwh yhwh que porque não-há para-יהוה de-prisõn lehoshiaבa com-muitos ou em-pouco');
INSERT INTO verses VALUES (7517, 9, 14, 7, 'E-disse a-ele levando-o seus-vessōis fez todo que no levavéka para-ti para-ti eis-me contigo com-tuas-entranhas');
INSERT INTO verses VALUES (7518, 9, 14, 8, 'E-disse Jônatas eis nós passamos a os-homens e-nos-revelaremos para-eles');
INSERT INTO verses VALUES (7519, 9, 14, 9, 'se assim dirão a-nos [עַד־הַגִּיעֵ֖נוּ] até [וְעָמַ֣דְנוּ] a-vós [וְלֹ֥א] [נַעֲלֶ֖ה] e-não para-eles');
INSERT INTO verses VALUES (7520, 9, 14, 10, 'e-se [יֹאמְר֜וּ] yomru ''alu sobre-nos ve''alu''inu yhwh natanam yhwh be''yadeinu e-este para-nós ha''ot');
INSERT INTO verses VALUES (7521, 9, 14, 11, 'e-eles-se-revelaram dois-deles a posto filisteus e-disseram eis eis hebreus saindo de os-de-hor que se-esconderam- nome');
INSERT INTO verses VALUES (7522, 9, 14, 12, 'e-eles-responderam homens-de o-posto-da a jonathan- e-a levando-o os-seus-vessŏis e-disseram subam a-nos e-nos-diremos vos palavra E-disse Yonatan a leva-o folhas-de sobe após-mim yhwh e-dos-deles-dar yhwh em-mão-de Israel');
INSERT INTO verses VALUES (7523, 9, 14, 13, 'e-subiu Yonatan sobre de-suas-mãos e-sobre seus-pes e-leva-o os-seus-vessŏis atrás-dele e caíram diante-de Jônatas e-leva-o seus-vessōis morto atrás-dele');
INSERT INTO verses VALUES (7524, 9, 14, 14, 'e-foi a-machī a-primeira que ele-golpeou Yonatan e-levanta seus-vessōis como-vinte homem como-meio resposta cem-de sadeh');
INSERT INTO verses VALUES (7525, 9, 14, 15, 'e-ela-ficou hara-dah em-o-machane no-sade e-em-todo o-povo ha-matzav e-ha-mashchit char-du também a-terra e-ela-tevegou a-terra e-foi le-hara-dat Elohim');
INSERT INTO verses VALUES (7526, 9, 14, 16, 'e-viram os-observadores -a-saulo na-cerro Binyamin e-eis aquele-montão -a-namog E-andou e-olhem');
INSERT INTO verses VALUES (7527, 9, 14, 17, 'E-disse שָׁאוּל para-o-povo que com-ele contem- por-favor quem andar andou de-nos e-eles-contaram e-eis não-há Jonatã e-levará seus-vesséis-verso');
INSERT INTO verses VALUES (7528, 9, 14, 18, 'E-disse Saul a-Acaia que deu arca o-Elohim porque foi arca-de no-dia no-dia o-aquele e-filhos-de Israel');
INSERT INTO verses VALUES (7529, 9, 14, 19, 'e-houve até palavra Saul a o-sacerdote e a multidão que em-acampamento-de filisteus E-andou indo e o grande E-disse Shaul a o-sacerdote -a-colheu yadcha');
INSERT INTO verses VALUES (7530, 9, 14, 20, 'e gritou שָׁאוּל e-todo o-povo que com-ele e-vieram até era espada foi espada homem contra ele muito grande muito');
INSERT INTO verses VALUES (7531, 9, 14, 21, 'e os hebreus eram aos filisteus como ontem sempre que que subiram com eles no-acampamento ao-redor e-também eles ser com Israel que com emprestado e Jônatan');
INSERT INTO verses VALUES (7532, 9, 14, 22, 'e-tudo homem Israel aqueles que se escondem em-monte-de אֶפְרַיִם ouviram porque levantaram-se filisteus e se apegaram também הֵ֛מָּה atrás-de-eles na-guerra');
INSERT INTO verses VALUES (7533, 9, 14, 23, 've-Yoshua yhwh no-dia o-aquele a Israel ve-ha-milchama averah a casa iniquidade');
INSERT INTO verses VALUES (7534, 9, 14, 24, 'e-homem- Israel no-dia em-o-dia o-aquele veyoel Saul dizendo maldito dizendo maldito pão que yochal pão até o-crepúsculo e-n-vingarei d-e-inimigos e-não t-prova todo o-povo pão');
INSERT INTO verses VALUES (7535, 9, 14, 25, 'e-todo a-terra vieram e-houve E-foi d-mel sobre face-de o-campo');
INSERT INTO verses VALUES (7536, 9, 14, 26, 'E-veio o-povo a a-floresta e-eis andou d-mel sua-mão m-alcançando mão-dele a de-sua-boca porque tem medo o-povo a o-juramento');
INSERT INTO verses VALUES (7537, 9, 14, 27, 'e-Yonatan não ouviu seu-pai אָבִיו֮ a o-povo e-enviou a extremidade o-m-flecha que em-mão-de-ele e-banhou-se sinal-aquela sua-mão o-mel e-ele-sentou-se mão-dele a de-sua-boca os-seus-olhos');
INSERT INTO verses VALUES (7538, 9, 14, 28, 'e-ele-respondeu homem de-o-povo E-disse o-juramento ele-jurou teu-pai a dizendo maldito maldito o-homem pão o-dia pão o-dia e-ele-vooou o-povo');
INSERT INTO verses VALUES (7539, 9, 14, 29, 'E-disse Yonatan obstruiu pai-meu a a-terra vieu- por-favor que ora meus-olhos porque gostei pouco mel a-esta');
INSERT INTO verses VALUES (7540, 9, 14, 30, 'certamente que Lûa comer comer o-dia o-povo Mishlal Oyevâv que encontrou que Attâ não Rabta ferida Bappélishštim:');
INSERT INTO verses VALUES (7541, 9, 14, 31, 'e atingiram no-dia o-aquele na filistim de micmas aiyalonah e voou o-povo muito');
INSERT INTO verses VALUES (7542, 9, 14, 32, 'o-povo a e-tomaram o rebanho u''vekar e-filhos-de manhã e sacrificaram- terra e comeu o-povo e-comeu o sangue:');
INSERT INTO verses VALUES (7543, 9, 14, 33, 'e-eles-anunciaram para-Saulo dizendo eis o-povo os-chotaim a-yhwh para-a-c-hol sobre E-disse E-disse vog-datem o-dia pedra o-dia pedra g-odola');
INSERT INTO verses VALUES (7544, 9, 14, 34, 'E-disse Saul futzu entre-o-povo e-dirão a-eles o-aproximem a-mim homem o-vaca-seu e-homem e-o-levre e-voces-imoltem com-isso e-voces-comam e-não voces-pecarem a-yhwh para-comer a o-sangue e-os-ajeitaram todo o-povo homem seu-touro בְיָד֛וֹ a-noite e-eles-esfolaram nome');
INSERT INTO verses VALUES (7545, 9, 14, 35, 'E-edificou Shaul altar para-יהוה ele começou para-construir altar para-יהוה');
INSERT INTO verses VALUES (7546, 9, 14, 36, 'E-disse Saul depois-de Filisteus noite e-eles-espreitaram em-eles até luz a-manhã e-não permaneceu neles homem e-disseram todo o-bom nos-teus-olhos fez E-disse E-disse niqurebah halom a Elohim');
INSERT INTO verses VALUES (7547, 9, 14, 37, 'e-ele-perguntou Saul be-elohim haereder depois-de filisteus se-você-dá-los em-mão-de Israel e-não anahu no-dia a-aquela');
INSERT INTO verses VALUES (7548, 9, 14, 38, 'E-disse Shaul goshu halom todo as narinas o-povo udewu e-vedei bamma hachatata a-esta o-dia');
INSERT INTO verses VALUES (7549, 9, 14, 39, 'que vive yhwh o-salvador que Israel porque se que morrendo filhos-de porque morte-de morra e-não-há responde-o de-todo o-povo');
INSERT INTO verses VALUES (7550, 9, 14, 40, 'E-disse a todo Israel vós um para-o-lado-de um va-ani e-yonatan filhos-de um para-o-lado-de um e-disseram o-povo a Shaul o-bom nos-teus-olhos fez');
INSERT INTO verses VALUES (7551, 9, 14, 41, 'E-disse שָׁאוּל a yhwh Elohim-de Israel dá perfeito e-pegou-se Yonatan ve-Shaul e-o-povo sairam');
INSERT INTO verses VALUES (7552, 9, 14, 42, 'E-disse Saul o-jogaram entre-mim e-entre yonatan filhos-de e-ele-capturou-se yonatan');
INSERT INTO verses VALUES (7553, 9, 14, 43, 'E-disse Saul a Yônāṯān a-mim para-mim que tu-fizeste e-contou E-disse Yônāṯān E-disse ṭāʿōm ṭāʿamtti biqṣēh hammatte que na-mao-de-me pouco dḇaš eis-me morrer-ei:');
INSERT INTO verses VALUES (7554, 9, 14, 44, 'E-disse Saul assim fara Elohim e-assim yosif-acento-águia morrerás morrer morra Yônāṯān');
INSERT INTO verses VALUES (7555, 9, 14, 45, 'E-disse o-povo a Saul הֲ-יוֹנָתָ֤ן ׀ morrera que fez הַיְשׁוּעָ֨ה הַגְּדוֹלָ֣ה הַזֹּאת֮ בּ-יִשְׂרָאֵל֒ chaliyla vive yhwh se yiphol misaaarat rosho terra-para o-dia com Elohim fez o-dia esta va''yifdu o-povo a Jonatã e-não morreu');
INSERT INTO verses VALUES (7556, 9, 14, 46, 'e-subiu Shaul de-após filisteus e-filisteus e-caminharam limkoomam');
INSERT INTO verses VALUES (7557, 9, 14, 47, 'vesha''ul lakad hammeluka sobre Israel ao-redor em-todo oiyvayo bemo''av e nos filhos de- Amom e em Edom e nos reis de- Tzováh e na Filístia e em todos que irá-se e se exibirá:');
INSERT INTO verses VALUES (7558, 9, 14, 48, 'E-fez valente e bateu a אמלאק e-çel a Israel de-mão-de e-sesu:');
INSERT INTO verses VALUES (7559, 9, 14, 49, 'e-foram filhos-de Shaul jonatan e-yiswiy e-rei- sua e-shem duas em-as-filhas-dele nome a-primeira de-rav e-nome-de a-keṭannah mikhal:');
INSERT INTO verses VALUES (7560, 9, 14, 50, 've-shem mulher-de Shaul [אֲחִינֹ֖עַם] filha-de [וְשֵׁ֤ם] ve-shem príncipe-de exército-dele [דּ֥וֹד] filho-de neṛ Davi שָׁאוּל');
INSERT INTO verses VALUES (7561, 9, 14, 51, '[וְקִ֧ישׁ] avi- Shaul [אֲבִֽי־אַבְנֵ֖ר] avi- Abner filho-de');
INSERT INTO verses VALUES (7562, 9, 14, 52, 'e-foi a-guerra חֲזָקָ֣ה sobre filisteus dias-de dias-de שָׁאוּל וְרָאָ֨ה Saul todo homem גִּבּוֹר֙ a-ele filho-de valente e-assemblei-os a-ele');
INSERT INTO chapters VALUES (251, 9, 15, 35);
INSERT INTO verses VALUES (7563, 9, 15, 1, 'E-disse Samuel a Shaul oti yhwh yhwh [לְמֶ֔לֶךְ] para-o-rei sobre e-agora sobre à-voz-de e-agora yhwh palavras-de yhwh');
INSERT INTO verses VALUES (7564, 9, 15, 2, 'assim disse yhwh exércitos eu-fiz-aviso a que fez Amaleque לְיִשְׂרָאֵ֑ל a-ele nome a-ele em-a-caminho em-su-sobe de-Egito');
INSERT INTO verses VALUES (7565, 9, 15, 3, 'agora vai e-atingas a Amaleque e-destruam a todo que a-ele e-não תַחְמֹ֖ל sobre-ele וְהֵמַתָּ֞ה me-ish até mulher מֵֽעֹלֵל֙ e-até יוֹנֵ֔ק מִשּׁ֣וֹר e-até שֶׂ֔ה מִגָּמָ֖ל e-até חֲמֽוֹר׃');
INSERT INTO verses VALUES (7566, 9, 15, 4, 'E-ouviu Saul a o-povo וַֽיִּפְקְדֵם֙ בַּטְּלָאִ֔ים duzentos mil de-pé e-a-década dois-mil a homem Judá');
INSERT INTO verses VALUES (7567, 9, 15, 5, 'E-veio Saul até cidade אמלאק e-fozou-se-em no-ravano:');
INSERT INTO verses VALUES (7568, 9, 15, 6, 'E-disse Saul a o-comprei venham vão-se descendam do-meio-de do-amaleque para-que-não reúna-te com-ele e-tu fizeste hesed com todo filhos-de Israel בַּעֲלוֹתָ֖ם de-Egito e ele se desviou קֵינִ֖י de-meio עֲמָלֵק׃');
INSERT INTO verses VALUES (7569, 9, 15, 7, 'e-feriu Saul a עֲמָלֵק [בּוֹאֲךָ֣] [שׁ֔וּר] [אֲשֶׁ֖ר] que sobre face-de Egito');
INSERT INTO verses VALUES (7570, 9, 15, 8, '[וַיִּתְפֹּ֛שׂ] a [מֶֽלֶךְ־עֲמָלֵ֖ק] rei-de [וְאֶת־כָּל־הָעָ֖ם] viveu e-a todo o-povo à-boca-de com-espada');
INSERT INTO verses VALUES (7571, 9, 15, 9, 'וַיַּחְמֹל֩ Saul e o povo sobre Aga e-sobre Meitav o rebanho e o gado e os instrumentos e-sobre as árvores e-sobre todo o-bom e-não aboveram os condenados à morte e-todo o trabalho נְמִבְזָה וְנָמֵ֖ס essa-a הֶחֱרִֽימוּ׃');
INSERT INTO verses VALUES (7572, 9, 15, 10, 'e-houve palavra-de yhwh dizendo שְׁמוּאֵל para-dizer');
INSERT INTO verses VALUES (7573, 9, 15, 11, '[נִחַ֗מְתִּי] porque [אֶת־שָׁאוּל֙] a Saul para-o-rei porque não de-áahiray e-a as-minhas-palavras não [אֶל־יְהוָ֖ה] [כָּל־הַלָּֽיְלָה] a yhwh todo a-noite');
INSERT INTO verses VALUES (7574, 9, 15, 12, '[וַיַּשְׁכֵּ֧ם] Samuel para-encontro-de emprestado no-manhã וַיֻּגַּ֨ד [לִשְׁמוּאֵ֜ל] dizendo veio [הַכַּרְמֶ֙לָה֙] [וְהִנֵּ֨ה] e-eis a-ele mão mão [וַֽיַּעֲבֹ֔ר] e passou e-ele-descerrou o-Gilgal');
INSERT INTO verses VALUES (7575, 9, 15, 13, 'E-veio שְׁמוּאֵל a E-disse a-ele a-ele שָׁאוּל tu tu a-yhwh [אֶת־דְּבַ֥ר] yhwh palavra yhwh');
INSERT INTO verses VALUES (7576, 9, 15, 14, 'E-disse שְׁמוּאֵל e-me som-de o-rebanho este בְּאָזְנָ֑י e-voz o-bovino eu eu ouviu');
INSERT INTO verses VALUES (7577, 9, 15, 15, 'E-disse Saul de-Amaleque הֱבִיא֗וּם que chamal o-povo sobre meitav o-rebanho vehabbakar para zebach a-yhwh teu-Elohim e-a hayoter hecharamnu');
INSERT INTO verses VALUES (7578, 9, 15, 16, 'E-disse Samuel a Shaul levantamento veagidah lekha את que yhwh yhwh a-noite a-noite a-ele a-ele');
INSERT INTO verses VALUES (7579, 9, 15, 17, 'E-disse שְׁמוּאֵל halo se tu tu em-tua-olho cabeça tribos-de Israel tu yhwh yhwh para-rei sobre Israel');
INSERT INTO verses VALUES (7580, 9, 15, 18, 'e te enviou yhwh bederekh E-disse vai vehacharamta a as-erros a nele até nele eles -los-ei-os-lhes eles');
INSERT INTO verses VALUES (7581, 9, 15, 19, 'e-porque não ouviste yhwh yhwh -ta-atuou a o-selo e foi feito yhwh em-olhos-de yhwh');
INSERT INTO verses VALUES (7582, 9, 15, 20, 'E-disse Saul a Shemu''el que ouvi yhwh yhwh -eu-vi no-caminho yhwh enviou-me yhwh -eu-troux-te a Agag rei nele e-a עֲמָלֵ֖ק -eu-extermin-ei');
INSERT INTO verses VALUES (7583, 9, 15, 21, 'E-tomou o povo do-selo rebanho e-vacas רֵאשִׁ֖ית o-herem para-o-vitima a-יהוה teu-Elohim em-o Gilgal');
INSERT INTO verses VALUES (7584, 9, 15, 22, 'E-disse Shemu''el o desejo a-yhwh nas oferendas e sacrifícios como ouvir com-voz yhwh eis ouviu de-sacrifício-de bom para escutar do gordo ovelhas');
INSERT INTO verses VALUES (7585, 9, 15, 23, 'que חַטָּאֹת- encanto alegria e vaidade e imagens הַפְצַר porque מָאַסְתָּ yhwh palavra yhwh וַיִּמְאָסְךָ֖ מִמֶּֽלֶךְ׃');
INSERT INTO verses VALUES (7586, 9, 15, 24, 'E-disse [שָׁא֤וּל] a Samuel [כִּֽי־עָבַ֥רְתִּי] porque transgredi que boca-de yhwh e-a [בְּקוֹלָֽם] porque a o-povo ve-eshmáh com-voz-deles');
INSERT INTO verses VALUES (7587, 9, 15, 25, 'e-agora se por-favor a [וְשׁ֣וּב] [עִמִּ֔י] comigo [לַֽיהוָֽה] para-יהוה');
INSERT INTO verses VALUES (7588, 9, 15, 26, 'E-disse Samuel a não não אָשׁ֖וּב que porque más-ta yhwh palavra yhwh vay-mas-ka- yhwh de-ser rei sobre Israel');
INSERT INTO verses VALUES (7589, 9, 15, 27, 'vay-sa-bo שְׁמוּאֵל para-andar e-segurou be-knaf- me-il-o e-se-riu');
INSERT INTO verses VALUES (7590, 9, 15, 28, 'E-disse a-ele שְׁמוּאֵל qara'' yhwh a mamlékhet Israel o-dia o-dia v-natan-ha le-re''akha- o-bom de-te');
INSERT INTO verses VALUES (7591, 9, 15, 29, 'e-também netza'' Israel não יְשׁוֹקֵ֖ר e-não יִנְחֵ֑ם que não homem ele לְהִנַּחֵֽם׃');
INSERT INTO verses VALUES (7592, 9, 15, 30, 'E-disse [חָטָ֔אתִי] agora [כַּבְּדֵ֥נִי] por-favor diante [זִקְנֵֽי־עַמִּ֖י] povo-meu e-diante-de Israel [עִמִּ֔י] comigo [לַֽיהוָ֥ה] a-יהוה Elohim-tua');
INSERT INTO verses VALUES (7593, 9, 15, 31, 'e-voltou שְׁמוּאֵל depois-de שָׁאוּל e-prostrou-se emprestado para-יהוה');
INSERT INTO verses VALUES (7594, 9, 15, 32, 'E-disse Shemu''el הַגִּישׁוּ a-mim a אֲגַג֙ rei עֲמָלֵ֔ק a-ele para-ele Agag E-disse E-disse Agag certamente sir amargo הַמָּֽוֶת');
INSERT INTO verses VALUES (7595, 9, 15, 33, 'E-disse שְׁמוּאֵל como-que Shiclah mulheres a tua espada כֵּן־ terás de matar filhos de Manassés mãe-tua e juntou-se Samuel a yhwh diante-de yhwh em-o Gilgal');
INSERT INTO verses VALUES (7596, 9, 15, 34, 'E-andou שְׁמוּאֵל a-Ramá וְשָׁא֛וּל subir a casa-dele colina-de שָׁאוּל');
INSERT INTO verses VALUES (7597, 9, 15, 35, 'e-não יָסַ֨ף para-ver para ver a Saul até dia sua morte porque se entristeceu שְׁמוּאֵל a שָׁאוּל e-יהוה lamentou-se porque fez-reinar a emprestado sobre Israel');
INSERT INTO chapters VALUES (252, 9, 16, 23);
INSERT INTO verses VALUES (7598, 9, 16, 1, 'E-disse yhwh a Shemu''el tu quando tu se entristecendo a Shaul e-eu se desgostando dele do rei sobre Israel enchei sua coroa óleo e vai e-šlāḵā a isai casa-de o pão porque eu vi em seus filhos yhwh rei');
INSERT INTO verses VALUES (7599, 9, 16, 2, 'E-disse Samuel como eu irei e ouvi emprestado e me matou E-disse E-disse yhwh manhã tu-tomarás em-tua-mão וְאָ֣מַרְתָּ֔ para sacrifício a-yhwh בָּֽאתִי׃');
INSERT INTO verses VALUES (7600, 9, 16, 3, 'e-lerás a Isaías no sacrifício e eu o-di-ă-kha a que faça u-ma-sha-ta a-mim a que disse para-ti');
INSERT INTO verses VALUES (7601, 9, 16, 4, 'E-fez Shemu''el a que palavra yhwh E-veio casa pão va-yech-er-du זִקְנֵ֤י a-cidade ao-encontro-dele E-disse sha-lo בּוֹאֶֽךָ׃');
INSERT INTO verses VALUES (7602, 9, 16, 5, 'E-disse shalom li-zva-kha a-yhwh ba-a-ti hi-ta-qad-shu u-ba-tem a-ti ba-zza-ba-kha e-santificou a ישׁע e-a E-chamou a-eles a-eles לַזּוֹבַח׃');
INSERT INTO verses VALUES (7603, 9, 16, 6, 'e-houve [בְּבוֹאָ֔ם] E-viu a E-disse E-disse diante yhwh yhwh ungido-dele');
INSERT INTO verses VALUES (7604, 9, 16, 7, 'E-disse yhwh a Shemu''el a [וְאֶל־גְּבֹ֥הַּ] a que e-a que [׀] não [אֲשֶׁ֤ר] que o-homem que o-homem o-homem porque o-homem virão-ve: [לַלֵּבָֽב] וַיהוָ֖ה verá');
INSERT INTO verses VALUES (7605, 9, 16, 8, 'E-chamou isiá a Avinadab e-fez-passar-ele diante-de E-disse E-disse também yhwh não yhwh');
INSERT INTO verses VALUES (7606, 9, 16, 9, 'e passou יִשַׁי sama E-disse também em-isso yhwh escolheu yhwh');
INSERT INTO verses VALUES (7607, 9, 16, 10, 'e passou isiá sete seus filhos diante-de Samuel E-disse Samuel a isiá yhwh escolheu yhwh nestes');
INSERT INTO verses VALUES (7608, 9, 16, 11, 'E-disse Samuel a isiá foram todos E-disse E-disse ainda arremessou o pequeno e-eis ⚗ה E-disse E-disse Shemu''el a ישׁי que וְקָחֶ֔נּוּ porque não נָסֹ֖ב até בֹּא֥וֹ פֹֽה׃');
INSERT INTO verses VALUES (7609, 9, 16, 12, 'e-estendeu וַיְבִיאֵ֙הוּ֙ e-ele vermelho-escarlate com יפחה [וְט֣וֹב] e-bom roei E-disse yhwh levantou [מְשָׁחֵ֖הוּ] porque ele ela');
INSERT INTO verses VALUES (7610, 9, 16, 13, 'E-tomou Shemuel a קֶ֣רֶן [וַיִּמְשַׁ֣ח] ele nele em-meio-de [וַתִּצְלַ֤ח] vatitzlakh espírito-de yhwh a Davi [וַיָּ֣קָם] o-aquele e-para-cima E-levantou שְׁמוּאֵל E-andou a-altura');
INSERT INTO verses VALUES (7611, 9, 16, 14, 'e-Espírito-de yhwh [סָ֖רָה] de-com שָׁאוּל [וּבִֽעֲתַ֥תּוּ] espírito-de maldade yhwh yhwh');
INSERT INTO verses VALUES (7612, 9, 16, 15, 'e-disseram servos-de- a-ele a-ela eis-que- por-favor espírito-de Elohim');
INSERT INTO verses VALUES (7613, 9, 16, 16, 'יֹאמַר־ por-favor nosso-mestre teus-servos diante-de-ti procurem sabe conheceu tocando no-cinor e-foi sendo sobre-te espírito-de Elohim maldade e-tocaremos para-ti e-bom para-ti');
INSERT INTO verses VALUES (7614, 9, 16, 17, 'E-disse emprestado a servos-dele Vede— por-favor para-mim homem é-bom para-toque e-vocês-levem para-mim');
INSERT INTO verses VALUES (7615, 9, 16, 18, 'e-ele-respondeu um de-os-jovens E-disse eis vi filho para-Yishai casa o-pão-meu sabe tocarei e-herói חַ֜יִל וְאִ֧ישׁ milchama e-saberei palavra e-homem a-aparência e- יהוה com-ele');
INSERT INTO verses VALUES (7616, 9, 16, 19, 'e-enviou Shaul [מַלְאָכִ֖ים] a E-disse E-disse [אֵלַ֛י] a-mim a Davi filho-teu que');
INSERT INTO verses VALUES (7617, 9, 16, 20, 'E-tomou [יִשַׁ֜י] χamor pão [וְנֹ֣אד] vinho [וּגְדִ֥י] cabras um e-enviou por-mão-de Davi filho-seu a שָׁאוּל');
INSERT INTO verses VALUES (7618, 9, 16, 21, 'E-veio Davi a Shaul e-se-posicionou diante-dele muito muito e-foi a-ele leva');
INSERT INTO verses VALUES (7619, 9, 16, 22, 'e-enviou Saul a dizendo dizendo vai-estar-de-pé por-favor Davi diante-de-mim porque graça be-einai');
INSERT INTO verses VALUES (7620, 9, 16, 23, 'e-foi [בִּֽהְי֤וֹת] espírito-de Elohim e-tome Saul e tomará Davi a [וְרָוַ֤ח] [לְשָׁאוּל֙] na-sua-mão a-ele para-Saulo e-bom espírito e-vai-se dos seus pés espírito hărâ''â');
INSERT INTO chapters VALUES (253, 9, 17, 58);
INSERT INTO verses VALUES (7621, 9, 17, 1, 'e reuniram-se filistins a suas acampadas para-a-guerra e reuniram-se soco que a judá e acamparam-se entre שֹׂכֹה e-entre em azekah בְּאֶ֥פֶס דַּמִּֽים׃');
INSERT INTO verses VALUES (7622, 9, 17, 2, '[וְשָׁא֤וּל] e-homem- Israel [וַֽיַּחֲנ֖וּ] e-acamparam בְּעֵ֣מֶק [וַיַּעַרְכ֥וּ] e-ele-arranjaram guerra para-encontro-de filisteus');
INSERT INTO verses VALUES (7623, 9, 17, 3, 'e-fois [עֹמְדִ֤ים] a o-montanha deste-lado [עֹמְדִ֥ים] em-pé a o-monte deste');
INSERT INTO verses VALUES (7624, 9, 17, 4, 'e-saiu אִישׁ- [מִמַּחֲנ֣וֹת] [פְּלִשְׁתִּ֔ים] filisteus Galá nome-de-ele [גָּבְה֕וֹ] [שֵׁ֥שׁ] seis côvados');
INSERT INTO verses VALUES (7625, 9, 17, 5, 'וְכ֤וֹבַע de-bronze sobre cabeça-sua וְשִׁרְי֥וֹן ele ele לָב֑וּשׁ e-pesado o-pancado cinco-de milhares escalam de-niqureto:');
INSERT INTO verses VALUES (7626, 9, 17, 6, 'e-cara bronze sobre seus-pés e-espada entre entre seus-bracos:');
INSERT INTO verses VALUES (7627, 9, 17, 7, 'sua-coroa como-estrelas de-or e-à-faixa o-carro seis-de centenas escalam barzel e-o-portador a-canga andou diante-de-ele');
INSERT INTO verses VALUES (7628, 9, 17, 8, 'e-estabeleceu-se E-chamou a as-filhas E-disse a-eles a-eles por-que saíram-as para-estender-se guerra eu eu o-filisteu e-vós avádim para-Saulo ברו- para-vós homem ויארד para-mim');
INSERT INTO verses VALUES (7629, 9, 17, 9, 'se [לְהִלָּחֵ֤ם] [אִתִּי֙] אתי [וְהָיִ֥ינוּ] a-vós para-vocês לַעֲבָדִ֑ים e-se eu e-sereis a-ele [לַעֲבָדִ֔ים] וִהְיִתֶם a-nós la-abadim vaʿavadtem');
INSERT INTO verses VALUES (7630, 9, 17, 10, 'E-disse [הַפְּלִשְׁתִּ֔י] eu [חֵרַ֛פְתִּי] a [יִשְׂרָאֵ֖ל] o-dia o-dia esta dai- a-mim homem juntos');
INSERT INTO verses VALUES (7631, 9, 17, 11, 'E-ouviu Saul e-todo Israel a palavras-de הַפְּלִשְׁתִּי estas muito e-viram muito');
INSERT INTO verses VALUES (7632, 9, 17, 12, '[וְדָוִד֩] filho-de homem [הַזֶּ֗ה] o-este pão pão Judá e-nome-de-ele -Isai [שְׁמֹנָ֣ה] filhos filhos והאיש em-dias-de Shaul velho veio');
INSERT INTO verses VALUES (7633, 9, 17, 13, 'e-foram três-de filhos-de os-grandes os grandes הלכו depois-de emprestado para-a-guerra e o nome três-de filhos-seus que foram na-guerra Eliaabe o primogênito e seu companheiro Avinadab e o terceiro quem é');
INSERT INTO verses VALUES (7634, 9, 17, 14, 'e-David ele o-pequeno e-três os-grandes foram depois-de שָׁאוּל');
INSERT INTO verses VALUES (7635, 9, 17, 15, 'e-David andou e Arão de-cima-de שָׁאוּל para pastorear a seu-pai seu-pai pão');
INSERT INTO verses VALUES (7636, 9, 17, 16, 'e-veio-aproximar-se o filisteu o-manhã e apanhou e estabeleceu-se quarenta dia');
INSERT INTO verses VALUES (7637, 9, 17, 17, 'E-disse Ishai a-Davi filho-seu toma por-favor para teus irmãos Efat o quilitai este e dez pão este e Hertz o-acampamento para-seus-irmãos;');
INSERT INTO verses VALUES (7638, 9, 17, 18, 'e dez cortadores do-leite os-estes traga-vos para-o o-primeiro e-a teus-irmaos ordene para-a-paz e-a sua-mistura levem-vos;');
INSERT INTO verses VALUES (7639, 9, 17, 19, '[וְשָׁא֤וּל] e-eles e-todo homem Israel be-emek [נִלְחָמִ֖ים] [עִם־פְּלִשְׁתִּֽים] com filisteus');
INSERT INTO verses VALUES (7640, 9, 17, 20, 'e-ele-se-levantou Davi na-manhã [וַיִּטֹּ֤שׁ] a o-rebanho sobre שֹׁמֵר e levantou E-andou como-que ordenou-o Jesai E-veio [הַיֹּצֵא֙] [אֶל־הַמַּ֣עֲרָכָ֔ה] [וְהֵרֵ֖עוּ] a na-guerra');
INSERT INTO verses VALUES (7641, 9, 17, 21, 'vata''arokh Israel uflishtim ma''arakah para-encontro-de ma''arakah');
INSERT INTO verses VALUES (7642, 9, 17, 22, 'vayittosh Davi a hakelim me''alayo sobre mão guardiao os-vasos vayarahats hamma''arakah E-veio e-pediu para-seus-irmãos em-paz');
INSERT INTO verses VALUES (7643, 9, 17, 23, 'e-ele falando-é com-eles e-eis homem as-crianças subindo Golias o-filisteu sh-mo de-Gath filisteus וַיְדַבֵּ֖ר como-as-coisas estas E-ouviu Davi');
INSERT INTO verses VALUES (7644, 9, 17, 24, 'e-tudo homem Israel para-que-os-viessem-ver a o-homem e-fugiram diante-dele muito muito');
INSERT INTO verses VALUES (7645, 9, 17, 25, 'E-disse homem Israel haraitem o-homem aquele-que-subia esta porque que a Israel עֹלֶה e-foi o-homem que יַכֶּ֜נּוּ יַעְשְׁרֶ֥נּוּ o rei dez grande e-a בִּתּוֹ֙ dê a-ele seu-pai casa pai-dele ele-fará חָפְשִׁ֖י em-Israel');
INSERT INTO verses VALUES (7646, 9, 17, 26, 'E-disse Davi a os-homens [עִמּוֹ֮] dizendo dizendo que [אֲשֶׁ֤ר] para-o-homem que [הַלָּ֔ז] a [חֶרְפָּ֖ה] de-cima-de e removeu que quem Israel porque quem que [חֵרֵ֔ף] esta porque vida Elohim vivos');
INSERT INTO verses VALUES (7647, 9, 17, 27, 'E-disse a-ele o-povo kadavar este dizendo assim ye''ashe la''ish que yakenu:');
INSERT INTO verses VALUES (7648, 9, 17, 28, 'E-ouviu [אֱלִיאָב֙] [אָחִ֣יו] a-grande [בְּדַבְּר֖וֹ] a os-homens e-acendeu-se- [בְּדָוִ֜ד] E-disse [׀] e-ele-disse por-que isto [נָטַ֜שְׁתָּ] e-sobre mi [הָהֵ֙נָּה֙] [בַּמִּדְבָּ֔ר] o rebanho [יָדַ֣עְתִּי] no-deserto eu eu-sei a que e-את mau teu-coracao porque para-fim-de ver ha-milchamah');
INSERT INTO verses VALUES (7649, 9, 17, 29, 'E-disse Davi מֶ֥ה fiz agora acaso-nao palavra ele');
INSERT INTO verses VALUES (7650, 9, 17, 30, 'וַיִּסֹּ֤ב de-lui a em-face-de E-disse E-disse como-dizer este e-sentou-os o-povo palavra de-a-palavra o-primeiro:');
INSERT INTO verses VALUES (7651, 9, 17, 31, 'as-palavras que palavra Davi e-disseram diante-de- Saul e-ele-o-tomou-verso');
INSERT INTO verses VALUES (7652, 9, 17, 32, 'E-disse Davi a Shaul a cairá coração-de homem sobre-ele seu-escravo-teu-servo irá e-lutaremos com o-philistino a-esta');
INSERT INTO verses VALUES (7653, 9, 17, 33, 'E-disse Saul a não não tu-ka-lam para-andar a o-philistino esta para-lutar tu porque jovem tu e-ele homem guerra dos-seus-jovens');
INSERT INTO verses VALUES (7654, 9, 17, 34, 'E-disse Davi a Shaul ser foi servo teu para-seu-pai no-gado e vindo o ari e-a o dove e-levará a sua do arado');
INSERT INTO verses VALUES (7655, 9, 17, 35, 'e eu saí depois-dele e eu castigarei e eu resgatar de seu boca E-levantou sobre-mim e eu fortaleci em sua velhice e o machucaria e o mataria');
INSERT INTO verses VALUES (7656, 9, 17, 36, 'também a o leão também o urso bateu servo-teu e-foi o filisteu como-um-de o-este que de-eles porque vida vida Elohim vivos');
INSERT INTO verses VALUES (7657, 9, 17, 37, 'E-disse Davi yhwh que salva-me da mão de do leão e-de-mão-de do urso ele salve-me de-mão-de o philistino esta E-disse E-disse a Davi vá e-יהוה será contigo');
INSERT INTO verses VALUES (7658, 9, 17, 38, 'e vestiu saúl a Davi seu manto e deu o calçado bronze sobre ele e vestiu a-ele a armadura');
INSERT INTO verses VALUES (7659, 9, 17, 39, 'e amarrou Davi a de-cima-de de cima lémadiyv vayá''el que porque E-disse nisáh E-disse não a שָׁאוּל não que não bá''eleh porque não nissítī vayísrem Davi me''ālāy');
INSERT INTO verses VALUES (7660, 9, 17, 40, 'E-tomou makkelo beyado e-ele-escolheu-para-o a-ele cinco ăvanim de o-nachal eles aqueles-eles -bikli ha-ro''im que para-ele u-bayyalakut ve-kalla''o -byado va-yiggash a ha-philistiy');
INSERT INTO verses VALUES (7661, 9, 17, 41, 'E-andou ha-philistiy andou ve-karav a Davi e o homem נֹשֵׂ֥א a tzedá diante-de-ele');
INSERT INTO verses VALUES (7662, 9, 17, 42, 'ele olhou o filisteu ele viu a Davi ele o repeliu porque foi jovem vista com belo aparência');
INSERT INTO verses VALUES (7663, 9, 17, 43, 'E-disse o filisteu a Davi eu eu porque tu veio- para-mim com as báculos e maldizera o filisteu a Davi a seus elohimes');
INSERT INTO verses VALUES (7664, 9, 17, 44, 'E-disse o filisteu a Davi vem a-mim e lhe dará a no teu carne ao pássaro os-céus a-terra o-campo');
INSERT INTO verses VALUES (7665, 9, 17, 45, 'E-disse Davi a tu tu veio a-mim com a espada e com o escudo e com o cídio e-eu veio- yhwh בְּשֵׁם֙ yhwh exércitos Elohim מַעַרְכ֥וֹת Israel que חֵרַֽפְתָּ׃');
INSERT INTO verses VALUES (7666, 9, 17, 46, 'o-dia הַזֶּ֡ה יְסַגֶּרְךָ֩ yhwh בְּיָדִ֜י וְהִכִּיתִ֗ךָ וַהֲסִרֹתִ֤י a רֹֽאשְׁךָ֙ de-te e-darei pegar de-acampamento o-dia o-dia este para-pássaro os-céus a-terra a-terra e-sabem que a-terra porque há Elohim para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (7667, 9, 17, 47, 'e saibam todo a-assembleia esta porque não be-cher-ev yhwh que yhwh porque para-יהוה a-guerra e colocou vós b''yadenu:');
INSERT INTO verses VALUES (7668, 9, 17, 48, 'e-foi porque levantou-se o-philistino E-andou e se aproximou ao-encontro-de Davi vayemaher Davi e-ele-correu a formação para-encontro-de o filisteu:');
INSERT INTO verses VALUES (7669, 9, 17, 49, 'e-enviou Davi a mão-sua E-tomou o utensílio pedra מסמך pedra e desferiu e-feriu a o filisteu a no seu olho e cravou a pedra em seu olho e-caiu sobre sua-face para-terra');
INSERT INTO verses VALUES (7670, 9, 17, 50, 'e fortaleceu-se Davi de o filisteu no cajado e na pedra e-feriu a o filisteu e-matou-o e espada não por-mão-de Davi');
INSERT INTO verses VALUES (7671, 9, 17, 51, 'e-correu Davi e levantou-se a E-tomou E-tomou a sua espada e a espetou de seu cajado e o matou e-cortaram- nela a sua-cabeça e-viram- os-filisteus- porque morreu seus-guerreiros- e-sucederam-se-');
INSERT INTO verses VALUES (7672, 9, 17, 52, 'e-elevaram-se- os-homens-de Israel e-juda- e-festejaram- e-eles-perseguiram a os-filisteus até em-vocês- gaiá- e-até שַׁעֲרֵ֣י Ecrom e caíram calê filisteus no-caminho portas e-até gat e-até');
INSERT INTO verses VALUES (7673, 9, 17, 53, 'e-voltaram-se filhos-de Israel destruíram depois-de pelos-filisteus e-saquearam a suas tendas:');
INSERT INTO verses VALUES (7674, 9, 17, 54, 'E-tomou Davi a cabeça filisteu e trouxe-o Jerusalém e-a seus utensílios nome em sua tenda:');
INSERT INTO verses VALUES (7675, 9, 17, 55, '[וְכִרְא֨וֹת] Saul a sai [לִקְרַ֣את] ao-encontro-de disse disse a אַבְנֵר comandante-de [הַנַּ֖עַר] filho-de E-disse este o-menino Abner E-disse Abner נַפְשְׁךָ֥ o-rei se eu-conheci');
INSERT INTO verses VALUES (7676, 9, 17, 56, 'E-disse o-rei [שְׁאַ֣ל] tu filho-de quem este');
INSERT INTO verses VALUES (7677, 9, 17, 57, '[וּכְשׁ֣וּב] Davi [מֵֽהַכּוֹת֙] a E-tomou ele ele Abner [לִפְנֵ֣י] diante-de שָׁאוּל ve-rosh הַפְּלִשְׁתִּי em-mão-sua');
INSERT INTO verses VALUES (7678, 9, 17, 58, 'E-disse a-ele Shaul filho-de tu tu E-disse E-disse Davi filho-de avadcha יִשַׁי casa');
INSERT INTO chapters VALUES (254, 9, 18, 30);
INSERT INTO verses VALUES (7679, 9, 18, 1, 'e-houve כְּכַלֹּתוֹ֙ para-falar a Shaul e-nepesh Jônatas niksharah bennepesh Davi Jonatas kenafsho');
INSERT INTO verses VALUES (7680, 9, 18, 2, 'vayikkachuhu Saul no-dia aquele e-não natanu para-retornar casa seu-pai');
INSERT INTO verses VALUES (7681, 9, 18, 3, 'e-ele-cortou Yehonatan e-David aliança ba''ahavato ele kenafsho');
INSERT INTO verses VALUES (7682, 9, 18, 4, '[וַיִּתְפַּשֵּׁ֣ט] [יְהוֹנָתָ֗ן] a [אֲשֶׁ֣ר] que sobre-ele [לְדָוִ֑ד] para-Davi [וְעַד־חַרְבּ֥וֹ] e-até [וְעַד־חֲגֹרֽוֹ] e-até e-até');
INSERT INTO verses VALUES (7683, 9, 18, 5, 'e-saiu Davi em-todo que [יִשְׁלָחֶ֤נּוּ] Saul [יַשְׂכִּ֔יל] [וַיְשִׂמֵ֣הוּ] Saul sobre homens-de a-guerra e-foi-bom aos-olhos-de todo o-povo e também em-olhos-de servos-de שָׁאוּל');
INSERT INTO verses VALUES (7684, 9, 18, 6, 'e-houve [בְּבוֹאָ֗ם] [בְּשׁ֤וּב] Davi [מֵהַכּ֣וֹת] a [וַתֵּצֶ֨אנָה] e-saíram [מִכָּל־עָרֵ֤י] de-todo cidades-de Israel [וְהַמְּחֹל֔וֹת] para-encontro-de Saul o-rei [בְּתֻפִּ֥ים] [בְּשִׂמְחָ֖ה] [וּבְשָׁלִשִֽׁים]');
INSERT INTO verses VALUES (7685, 9, 18, 7, 'e responderam as mulheres as que se contorciam e disseram bateu Saul e-David em suas multidões:');
INSERT INTO verses VALUES (7686, 9, 18, 8, 'e ficou chateado a Saulo muito e-mal nos seus olhos a-coisa esta E-disse eles deram para-Davi multidões e para mim deram milhares וְע֥וֹד a-ele somente o-reino');
INSERT INTO verses VALUES (7687, 9, 18, 9, 'e-houve emprestado a Davi de-este o-aquele e-ha-la-a:');
INSERT INTO verses VALUES (7688, 9, 18, 10, 'e-houve da-o ela-se-exauriu espírito Elohim mau- a Saul e-ele-propheteou no-meio-de a-casa e-David -tocando em-sua-mão como-dia- no-dia e-a-canita por-mão-de שָׁאוּל');
INSERT INTO verses VALUES (7689, 9, 18, 11, 'e-ele-pegou Saul a E-disse E-disse אַכֶּ֥ה בְדָוִ֖ד וּבַקִּ֑יר וַיִּסֹּ֥ב Davi מִפָּנָ֖יו duas-vezes');
INSERT INTO verses VALUES (7690, 9, 18, 12, 'E-viu emprestado de-diante-de Davi porque yhwh yhwh com-ele [שָׁא֖וּל] emprestado');
INSERT INTO verses VALUES (7691, 9, 18, 13, '[וַיְסִרֵ֤הוּ] Saul [מֵֽעִמּ֔וֹ] [וַיְשִׂמֵ֥הוּ] a-ele príncipe-de mil e-ele-saiu E-veio diante-de');
INSERT INTO verses VALUES (7692, 9, 18, 14, 'e-houve Davi para-todo [מַשְׂכִּ֑יל] [וַֽיהוָ֖ה] e-יהוה');
INSERT INTO verses VALUES (7693, 9, 18, 15, 'E-viu Shaul que ele muito muito e-ele-estabeleceu-se de-face-dele');
INSERT INTO verses VALUES (7694, 9, 18, 16, 'e-todo Israel e-Judá amou a Davi porque ele');
INSERT INTO verses VALUES (7695, 9, 18, 17, 'E-disse Saul a eis [בִתִּ֨י] [הַגְּדוֹלָ֤ה] [מֵרַב֙] [אֹתָהּ֙] a-ela darei para-ti para-esposa somente [וְהִלָּחֵ֖ם] para-mim yhwh valente disse [אַל־תְּהִ֤י] yhwh [בּ֔וֹ] disse a');
INSERT INTO verses VALUES (7696, 9, 18, 18, 'E-disse Davi a quem eu eu e-quem viva família meu-pai em-Israel porque estarei voz para-o rei');
INSERT INTO verses VALUES (7697, 9, 18, 19, 'e-houve será dada a de Rab filha-de Saul para-Davi e ela foi dada a Adriel minha noiva para-mulher');
INSERT INTO verses VALUES (7698, 9, 18, 20, 'e amou מיכאל filha-de Saul a Davi e-eles-diziram ל Saulo e ele cantou a palavra em-seus-olhos');
INSERT INTO verses VALUES (7699, 9, 18, 21, 'E-disse Saul eu lhe dei para-ele e-será a-ele para-apanhar e-será E-disse mão-de filisteus E-disse Saul a o-dia em bismas serás colocada em-mi o-dia');
INSERT INTO verses VALUES (7700, 9, 18, 22, 'E-ordenou Saul a para seu servo e disseram a dizendo eis dizendo eis queria be-ka o-rei e-agora servos-dele amar-te-ia e-agora hitchatnֵn bamַlekה:');
INSERT INTO verses VALUES (7701, 9, 18, 23, 'vay''dabberu servos-de Saul em-orelhas-de Davi a as-palavras E-disse E-disse Davi hanakalla''ה be''eyneichemב hitchatnֵn bamַlekה'' e-eu אִישׁ- rash רnikle''ה:');
INSERT INTO verses VALUES (7702, 9, 18, 24, 'vayaggdu servos-de Shaul a-ele dizendo segundo os palavras estes palavra Davi');
INSERT INTO verses VALUES (7703, 9, 18, 25, 'E-disse Saul assim dizeis para-David não-há prazer que por meio de pagamento porque em cento עָרְל֣וֹת filisteus para vingar-se contra os inimigos o-rei e Saulo considerou para derrubar a Davi por-mão-de filisteus');
INSERT INTO verses VALUES (7704, 9, 18, 26, 'e disseram seus servos para-Davi a as-palavras os-estes e ordenou a-palavra em-olhos-de Davi para se ajoelhar ante o rei e-não מָלְא֖וּ os dias');
INSERT INTO verses VALUES (7705, 9, 18, 27, 'E-levantou Davi e foi ele ele e-feriu entre os filisteus maatayim homem E-veio e-trouxe a suas circuncisões e os encheram para-o-rei para se ajoelhar no-מלך e-ele-deu a-ele Shaul a מיכאל não para-mulher');
INSERT INTO verses VALUES (7706, 9, 18, 28, 'E-viu Saul e-viu que yhwh com Davi e-מיכאל filha-de emprestado amar-lhe:');
INSERT INTO verses VALUES (7707, 9, 18, 29, 'e-reuniu-se שָׁאוּל para-ver de-diante-de Davi ainda e-houve Shaul inimigo a Davi todo os dias');
INSERT INTO verses VALUES (7708, 9, 18, 30, 'e-saíram príncipes-de pelos-filisteus e-houve sempre-de seus-saídos conseguiu Davi de-todo de-toda Shaul e foi chamado nome-de-ele muito');
INSERT INTO chapters VALUES (255, 9, 19, 24);
INSERT INTO verses VALUES (7709, 9, 19, 1, 'e-falou שָׁאוּל a João filho-o e-a todo seus-servos para-matar a Davi muito filho-de Shaul desejava a Davi muito');
INSERT INTO verses VALUES (7710, 9, 19, 2, 'e-contou Jehonathan a-Davi dizendo buscando Saul pai-meu para te matar e-agora fique em guarda por-favor em-a-manhã וְיָשַׁבְתָּ֥ em segredo e se esconda');
INSERT INTO verses VALUES (7711, 9, 19, 3, 'e-eu eu saindo e eu me levantei ליד־ pai-meu בַּשָּׂדֶה֙ tu tu nome e-eu falarei em ti a pai-meu e vi para-ti e relatei para-ti');
INSERT INTO verses VALUES (7712, 9, 19, 4, 'e-falou Jônatan- a Davi bom a seu-pai E-disse a-ele para ele a pecar o-rei que em Davi porque para-ti chatav para-ti e-que muito bom - para-ti muito');
INSERT INTO verses VALUES (7713, 9, 19, 5, 'e-ele-colocou a sua alma em sua mão e-feriu a yhwh E-fez yhwh Salvamento Grande para-todo Israel Vi E se alegrou e-porque Faltaste No sangue Inocente para matar a Davi por-nada:');
INSERT INTO verses VALUES (7714, 9, 19, 6, 'E-ouviu Saul com-voz Jonatã E jurou Saul vive yhwh se será-morto');
INSERT INTO verses VALUES (7715, 9, 19, 7, 'E-chamou Jonatã para-David e-contou a-ele Jonatas a todo e-trouxe estas E-veio Jônatan- e-houve Davi a Shaul E-foi diante-dele como ontem terceiro-dia');
INSERT INTO verses VALUES (7716, 9, 19, 8, 'e acresceu ha-milchamah a ser e-saiu Davi e lutou contra os filisteus e-ele-feriu בָּהֶם֙ punição grande e-eles-fugiram de-face-dele');
INSERT INTO verses VALUES (7717, 9, 19, 9, 'e aconteceu que espírito yhwh mal a Shaul e-ele em sua casa morando e sua tenda na-sua-mão e-David tocando harpa por mão:');
INSERT INTO verses VALUES (7718, 9, 19, 10, 'e buscou Saul para matar na chaminha em Davi e na bacia e cortou de-diante-de Shaul e-feriu a a chaminha na-parede e-David salvou-se e-ele-escapou ele ela');
INSERT INTO verses VALUES (7719, 9, 19, 11, 'e-enviou Saul anjos a casa Davi para guardá-lo e para matá-lo no-manhã e-relatou para-David Михаль dizendo dizendo se ain''t thou libertando-o a tu a-noite dizendo tu morrendo');
INSERT INTO verses VALUES (7720, 9, 19, 12, 'e-ela-desceu Mical a Davi através-de a janela E-andou e fugiu e escapou');
INSERT INTO verses VALUES (7721, 9, 19, 13, 'e-tomou Mical a as profetisas e-a colocou até- a-cama e-את -grande- as ovelhas -colocou- em-cabeça e-ela-cobriu -no-pano-:');
INSERT INTO verses VALUES (7722, 9, 19, 14, 'e-enviou Shaul -anjos- -para-levar- a E-disse e-disse ele ela');
INSERT INTO verses VALUES (7723, 9, 19, 15, 'e-estendeu Saul a para-ver para-ver dizendo Davi ele -levem- -ele- -na-cama- para-mim para a morte∶');
INSERT INTO verses VALUES (7724, 9, 19, 16, 'e-vieram [הַמַּלְאָכִ֔ים] e-eis [הַתְּרָפִ֖ים] a [וּכְבִ֥יר] [הָעִזִּ֖ים] os-cabritos');
INSERT INTO verses VALUES (7725, 9, 19, 17, 'E-disse Saul a [לָ֤מָּה] por-que [רִמִּיתִ֔נִי] [וַתְּשַׁלְּחִ֥י] [אֶת־אֹיְבִ֖י] a E-disse [מִיכַל֙] [אֶל־שָׁא֔וּל] [הוּא־אָמַ֥ר] a Saul ele disse');
INSERT INTO verses VALUES (7726, 9, 19, 18, 'ודוד ברח WAYYIMMETAL E-veio a Samuel הרמתה WAYYAGAD- a-ele a todo que ele a-ele שָׁאוּל E-andou ele وشموئל e-habitaram');
INSERT INTO verses VALUES (7727, 9, 19, 19, 'e-ele-foi-dito ל Saul dizendo eis Davi ברמה׃');
INSERT INTO verses VALUES (7728, 9, 19, 20, 'e-enviou Saul mensageiros לקחת a E-viu E-viu a להקט os-profetas נביאים e-Samuel ficou-em-pé está-postado sobre-eles ותהי espírito mensageiros-de Saul espírito Elohim E se pronunciaram também eles');
INSERT INTO verses VALUES (7729, 9, 19, 21, 'e-eles-diziram לشاול e-enviou מלאכים outros E se pronunciaram também הֵם e-continuou Saul e-enviou מלאכים שלשים E se pronunciaram também eles');
INSERT INTO verses VALUES (7730, 9, 19, 22, 'E-andou também ele הרמה E-veio até בור a-grande que E-disse וַיִּשְׁאַ֣ל E-disse אֵיפֹ֥ה E-disse eis E-disse hein בָּרָמָֽה׃');
INSERT INTO verses VALUES (7731, 9, 19, 23, 'E-andou nome a בָּרָמָ֑ה וַתְּהִי֩ sobre-ele também espírito espírito Elohim E-andou caminhar וַיִּתְנַבֵּ֔א até בֹּא֖וֹ בָּרָמָֽה׃');
INSERT INTO verses VALUES (7732, 9, 19, 24, 'וַיִּפְשַׁ֨ט também ele em-suas-roupas e-o-propheta-predisse também ele diante-de שְׁמוּאֵל e-caiu naked todo o-dia aquele e-todo a-noite sobre assim dirão também emprestado nos profetas:');
INSERT INTO chapters VALUES (256, 9, 20, 42);
INSERT INTO verses VALUES (7733, 9, 20, 1, 'e-saiu Davi em-armona E-veio e-ele-disse diante-de E-disse que faço-tenho-feito de-o- minha-iniquidade e-que pecado-eu diante-de pai-teu porque que a alma-de-mim');
INSERT INTO verses VALUES (7734, 9, 20, 2, 'E-disse a-ele ainda-seja não tamat eis Pai palavra grande ou palavra pequeno e-não yigleh a azni umdode yastir abi mimeni a a-palavra este não-há esta');
INSERT INTO verses VALUES (7735, 9, 20, 3, 'vayishba ainda Davi E-disse conheceu saber pai-de-ti porque encontrei graça E-disse E-disse a yada esta Jonatas para-que-não ye''atzev que vive yhwh e-entre a-tua-vida porque כְ֖פֶ֣שׂׂע e-entre e-entre a-morte:');
INSERT INTO verses VALUES (7736, 9, 20, 4, 'E-disse Jonatas a Davi que dizerás alma-tua וְאֶֽעֱשֶׂה־ para-ti');
INSERT INTO verses VALUES (7737, 9, 20, 5, 'E-disse Davi a [הִֽנֵּה־חֹ֙דֶשׁ֙] [מָחָ֔ר] novo [יָשֹׁב־אֵשֵׁ֥ב] [עִם־הַמֶּ֖לֶךְ] [לֶאֱכ֑וֹל] [וְשִׁלַּחְתַּ֙נִי֙] com o-rei até [הָעֶ֥רֶב] [הַשְּׁלִשִֽׁית] até');
INSERT INTO verses VALUES (7738, 9, 20, 6, 'se recordar ele me recordará teu-pai e dirás será perguntado será interrogado de mim Davi para correr casa-de que sua cidade porque )(((זֶ֧בַח)) (((הַיָּמִ֛ים))) nome para-todo (((הַמִּשְׁפָּחָֽה׃)))');
INSERT INTO verses VALUES (7739, 9, 20, 7, 'se assim bom bom [לְעַבְדֶּ֑ךָ] [וְאִם־חָרֹ֤ה] e-se a-ele [דַּ֕ע] a-ele [הָרָעָ֖ה] porque');
INSERT INTO verses VALUES (7740, 9, 20, 8, 'e-farás hesed sobre que porque yhwh yhwh )(((הֵבֵ֥אתָ))) a servo-teu contigo e-se tu em-mim )(((עָוֺן֙))) )(((הֲמִיתֵ֣נִי))) tu e-até não a-vós dia )(((תְבִיאֵֽנִי׃)))');
INSERT INTO verses VALUES (7741, 9, 20, 9, 'E-disse Jonatas longe-seja para-ti que se conheceu אֵדַע porque כָלְתָה הָרָעָה de-com pai-meu para-vir sobre-ti e-não a-ela para-ti para-ti');
INSERT INTO verses VALUES (7742, 9, 20, 10, 'E-disse Davi a quem quem dirá a-mim ou que יַּעַנְךָ֥ não dura-:');
INSERT INTO verses VALUES (7743, 9, 20, 11, 'E-disse יְהֽוֹנָתָן֙ a Davi לְכָ֖ה וְנֵצֵ֣א o-campo וַיֵּצְא֥וּ dois-deles o-campo');
INSERT INTO verses VALUES (7744, 9, 20, 12, 'E-disse יְהוֹנָתָ֜ן a yhwh yhwh Elohim-de Israel porque אֶחְקֹ֣ר a pai-meu em-tempo amanhã a-terceira e-eis bom a Davi e-não então eu lançarei para-ti e libertarei a Seus ouvidos:');
INSERT INTO verses VALUES (7745, 9, 20, 13, 'assim yhwh yhwh para-jeonatan e-assim ele acrescentará porque será bom a meu-pai a a-malícia-a sobre-ti e libertarei e-seja yhwh e enviarei-te e caminhaste ser E-foi yhwh contigo como-que foi com pai-meu');
INSERT INTO verses VALUES (7746, 9, 20, 14, 'e-não se enquanto eu viveu comigo fazes yhwh bondade yhwh e-não morreremos');
INSERT INTO verses VALUES (7747, 9, 20, 15, 'e-não corte a o teu favor de-com em-o-casa até yhwh e-não no corte yhwh de-cima-de face-de a-terra homem de-sobre face-de a-terra');
INSERT INTO verses VALUES (7748, 9, 20, 16, 'e cortou Jonatas com casa Davi yhwh yhwh de-mão-de os teus inimigos Davi');
INSERT INTO verses VALUES (7749, 9, 20, 17, 'e fez Jehonathan para satisfação a Davi ele a-ele porque amor para-ele o ames');
INSERT INTO verses VALUES (7750, 9, 20, 18, 'e-ele-disse a-ele Jonatas amanhã novo que porque será ordenado o teu convívio');
INSERT INTO verses VALUES (7751, 9, 20, 19, 'e dividirás תֵּרֵד muito e-entrarás a o-lugar que estarias escondida nome no-dia o que acontecerá e habitarias junto a pedra o arreio;');
INSERT INTO verses VALUES (7752, 9, 20, 20, 'e-eu três as setas a cidadã o oráculo para enviar- a-mim a-ele');
INSERT INTO verses VALUES (7753, 9, 20, 21, 'e-eis eu enviarei a o jovem vai encontre a as setas se eis disse ao jovem eis as setas de ti e aqui leva-o e vêm a-ti shalom para-ti e-não-há palavra vive yhwh');
INSERT INTO verses VALUES (7754, 9, 20, 22, 'e-se assim disse eis eis as setas de ti e veja que porque yhwh yhwh');
INSERT INTO verses VALUES (7755, 9, 20, 23, 'e a palavra que nós falamos eu e-a eis yhwh entre-mim e-te até eternidade');
INSERT INTO verses VALUES (7756, 9, 20, 24, 'ele-ocultou-se Davi no-campo e-houve o-mês e-habitou o-rei o pão para-comer:');
INSERT INTO verses VALUES (7757, 9, 20, 25, 'e-sentou o-rei sobre seu-lugar -vez- de-cada-vez a lugar o-parede E-levantou Jonatas e-habitou Abner de-lado-de שָׁאוּל e foi ordenado lugar Davi');
INSERT INTO verses VALUES (7758, 9, 20, 26, 'e-não palavra Shaul no-dia no-dia que disse disse ele ele para-não ele ele porque não puro');
INSERT INTO verses VALUES (7759, 9, 20, 27, 'e-houve do dia seguinte o mês o-segundo e foi ordenado lugar Davi E-disse E-disse a Yehonatan seu-filho por-que não veio filho-de Isai também ontem também o-dia a o pão');
INSERT INTO verses VALUES (7760, 9, 20, 28, 'e-respondeu Jonatas a שָׁאוּל foi pedido foi perguntado Davi de mim até casa pão');
INSERT INTO verses VALUES (7761, 9, 20, 29, 'E-disse שַׁלְחֵ֣נִי נָ֡א que זֶבַח֩ מִשְׁפָּחָ֨ה nun- בָּעִ֗יר e-ele צִוּֽה־ para-mim e-agora e-agora se encontrei graça em-tua-olho אִמָּ֥לְטָה נָּ֖א וְאֶרְאֶ֣ה a אֶחָ֑י sobre assim não veio a שֻׁלְחָן o rei');
INSERT INTO verses VALUES (7762, 9, 20, 30, '[וַיִּֽחַר־אַ֤ף] [שָׁאוּל֙] Saul E-disse a-ele a-ele filho-de [הֲל֣וֹא] [יָדַ֗עְתִּי] porventura-não tu porque [לְבָ֨שְׁתְּךָ֔] tu [עֶרְוַ֥ת] [אִמֶּֽךָ]');
INSERT INTO verses VALUES (7763, 9, 20, 31, 'que todo הַיָּמִים que vida ישע não sobre tu não e-agora tu e o teu reino ele enviou que ele ele porque filho-de morte ela');
INSERT INTO verses VALUES (7764, 9, 20, 32, 'e-respondeu Jonatas a seu-pai E-disse a-ele a-ele por-que será-morto que fez');
INSERT INTO verses VALUES (7765, 9, 20, 33, 'e tomou s-h-a-u-l a a espada sobre-ele para matá-lo e-soube Jonatas porque toda seu-pai de-com seu-pai para matar a Davi');
INSERT INTO verses VALUES (7766, 9, 20, 34, 'E-levantou João de-com a mesa com-seu-escolhido tambem e-não אכל pão que o-segundo Belém que estava angustiado seu-pai Davi porque הִכְלִמ֖וֹ seu-pai');
INSERT INTO verses VALUES (7767, 9, 20, 35, 'e-houve em-a-manhã e-ele-saiu יְהוֹנָתָ֛ן o-campo לְמוֹעֵ֣ד Davi e-ná-ar pequeno com-ele');
INSERT INTO verses VALUES (7768, 9, 20, 36, 'E-disse a-jovem-dele רֻ֗ץ מְצָ֥א por-favor a הַ֣חִצִּ֔ים eu eu Moreh o-jovem רָ֔ץ e-ele יָרָ֥ה הַחֵ֖צִי לְהַעֲבִרֽוֹ׃');
INSERT INTO verses VALUES (7769, 9, 20, 37, 'E-veio o-menino até lugar o-háçîy que yârâ E-chamou E-chamou yêhônātân depois-de E-disse E-disse não o-háçîy de-tu vâ-hâlē''â');
INSERT INTO verses VALUES (7770, 9, 20, 38, 'E-chamou yêhônātân depois-de o jovem depressa chûshâ a tâ''ămōd vay''lakkēt jovem yêhônātân a E-veio a seu senhor');
INSERT INTO verses VALUES (7771, 9, 20, 39, 'e-o-menino não conheceu coisa-alguma somente יהוהונתן וְדָוִ֗ד conheceram a a-palavra');
INSERT INTO verses VALUES (7772, 9, 20, 40, 'E-colocou יהוהונתן a utensílios-dele a E-disse a-ele a-ele E-disse a-ele vai הָבֵ֥יא a-cidade');
INSERT INTO verses VALUES (7773, 9, 20, 41, 'הַנַּעַר֮ veio וְדָוִ֗ד קָ֚ם מֵאֵ֣צֶל o-sul e-caiu לְאַפָּ֥יו אַ֛רְצָה e-prostrou-se três vezes e beberam homem a companheiro-seu e choraram homem a companheiro-seu até Davi e cresceu;');
INSERT INTO verses VALUES (7774, 9, 20, 42, 'E-disse יְהוֹנָתָ֛ן para-David vai para-paz que נִשְׁבַּ֨עְנוּ שְׁנֵ֜ינוּ nós בְּשֵׁ֤ם yhwh dizendo yhwh será entre-mim וּבֵינֶ֗ךָ e-entre e-entre e-entre e-entre tua-semente eternidade');
INSERT INTO chapters VALUES (257, 9, 21, 16);
INSERT INTO verses VALUES (7775, 9, 21, 1, 'E-levantou E-andou [וִיהוֹנָתָ֖ן] veio a-cidade');
INSERT INTO verses VALUES (7776, 9, 21, 2, 'E-veio Davi נֹ֔בֶה a Achimeleque o-sacerdote e achou-se apavorado Achimeleque ao-encontro-de E-disse a-ele a-ele tu tu apenas contigo e-homem não-há contigo');
INSERT INTO verses VALUES (7777, 9, 21, 3, 'E-disse Davi para Achimeleque o-sacerdote הַמֶּלֶךְ֮ ordenou-me palavra E-disse a-mim homem a conheceu maldita a a-palavra que eu que envias-te e-que ordenaste-te e-a os-jovens eu sabia a מָקוֹם פּוֹלְנִי אֲלָמְנוֹי׃');
INSERT INTO verses VALUES (7778, 9, 21, 4, 'e-agora que יֵשׁ debaixo-de yadcha חֲמִישָה־ pao dá בְּיַדִ֑י ou הַנִּמְצָא׃');
INSERT INTO verses VALUES (7779, 9, 21, 5, 'e-ele-respondeu o-sacerdote a E-disse E-disse não-há pão-de חֹל a debaixo-de minha-mão porque se לֶחֶם santo יֵשׁ se נִשְׁמְרוּ os-jovens somente מֵאִשָּׁה׃');
INSERT INTO verses VALUES (7780, 9, 21, 6, 'e-ele-respondeu Davi a E-disse a-ele que porque se mulher עֲצֻרָה־ a-nós como-ontem anteontem בְּצֵאתִי e-foram o-caminho-de os-jovens santidade que o-dia חֹל וְאַף porque o-dia יִקְדַּשׁ בַּכֶּֽלִי׃');
INSERT INTO verses VALUES (7781, 9, 21, 7, 'e-ele-deu a-ele o-sacerdote que porque não pão nome לֶ֗חֶם porque se yhwh הַפָּנִים֙ pão de-diante-de yhwh כדי-להשים pão fogo em-dia -הילקחו׃');
INSERT INTO verses VALUES (7782, 9, 21, 8, 'ושם homem מעבדי Saul no-dia aquele -נעזרא׃ diante-de yhwh e-nome-dele דואג האדומי -אביר׃ os-pastores que -LEASEול׃');
INSERT INTO verses VALUES (7783, 9, 21, 9, 'E-disse Davi לאחIMElek וְאִ֛ין há poh debaixo-de tua-mao que ou espada porque também חַרְבִּ֤י e-também כֵּלַי֙ não tomei em-minha-mão porque foi palavra-de o-rei נָחֽוּץ׃');
INSERT INTO verses VALUES (7784, 9, 21, 10, 'E-disse o-sacerdote espada גָּלְיָ֨ת הַפְּלִשְׁתִּ֜י que הִכִּ֣יתָ ׀ בְּעֵ֣מֶק הָאֵלָ֗ה eis הִ֞יא Lua na-simlalah depois-de o-efod se ela-a que a-ti pegue porque não-há E-disse esse-lá-dele neste E-disse Davi a-mim como-ela tenele a-mim');
INSERT INTO verses VALUES (7785, 9, 21, 11, 'E-levantou Davi וַיִּבְרַ֥ח no-dia- de-diante-de de-diante-de שָׁאוּל E-veio a acis rei Gat:');
INSERT INTO verses VALUES (7786, 9, 21, 12, 'e-disseram servos-de Achis a-ele porventura-não este Davi a-terra a-terra porventura-não a isto responderão dizendo dizendo bateu Saul e-David');
INSERT INTO verses VALUES (7787, 9, 21, 13, 'e-ele-posto Davi a as-palavras estes no coração dele muito de-diante-de de-diante-de Achis rei-de Gat:');
INSERT INTO verses VALUES (7788, 9, 21, 14, 'e o transformaram a sua provação em-olhos-deles e se exaltou em-mão-deles sobre portas-de o-portão רִירוֹ a זְקָנוֹ׃');
INSERT INTO verses VALUES (7789, 9, 21, 15, 'E-disse אָכִישׁ a eis eis תִרְאוּ֙ homem מִשְׁתַּגֵּ֔עַ por-que ele ele para-mim');
INSERT INTO verses VALUES (7790, 9, 21, 16, 'חֲסַ֤ר מְשֻׁגָּעִים֙ eu porque הֲבֵאתֶ֣ם a este לְהִשְׁתַּגֵּ֖עַ sobre mim הֲזֶ֖ה virá a casa-minha');
INSERT INTO chapters VALUES (258, 9, 22, 23);
INSERT INTO verses VALUES (7791, 9, 22, 1, 'E-andou Davi de-lá e-ele-escapou a מערת עֲדֻלַּם e-ouviram irmãos-de-ele seu-pai casa a-ele וירדוּ a-ele ali');
INSERT INTO verses VALUES (7792, 9, 22, 2, 'e-eles-se-agruparam a-ele todo homem מצוק e-todo homem que para-ele e-houve e-todo homem amargo alma E-foi sobre-eles para-Sar e-foram com-ele כארבּע centenas homem');
INSERT INTO verses VALUES (7793, 9, 22, 3, 'E-andou Davi de-lá mitspeh Moabe E-disse a rei Moabe saiu- por-favor אבי ואמי até até que eu-saberei que יהעשׂה- para-mim Elohim');
INSERT INTO verses VALUES (7794, 9, 22, 4, 'WAYYANCHEM a face-de rei Moabe e-habitaram com-ele todo dias-de היות- Davi на-мацуда∶');
INSERT INTO verses VALUES (7795, 9, 22, 5, 'E-disse גד o-profeta a não não תישוב на-мацуда vai terra para ti terra Judá E-andou Davi E-veio יער חרת∶');
INSERT INTO verses VALUES (7796, 9, 22, 6, 'E-ouviu Saul que נודע Davi e-homens que com-ele וشاול יושב בגבעה debaixo-de o eshêl barâmá e chânitô na mão dele e-todo servos-dele estavam plantados sobre-ele');
INSERT INTO verses VALUES (7797, 9, 22, 7, 'E-disse Saul para seus servos aqueles que estavam plantados sobre-ele ouvi por-favor filhos-de da-minha-direita também para todos vós dará filho-de isiá as sêdot e-carmim- para-vos -sejam príncipes-de milhares e-príncipes-de centenas');
INSERT INTO verses VALUES (7798, 9, 22, 8, 'que -vós-ajuntastes de-vos עָלַ֗י e-não-há -expulso a -minha-ouvido -em-corte filhos-de com filho-de -Isai que -doente de-vós sobre-mim e-gole a a-zi-ni porque heqim filhos-de a עבדי sobre-mim le-or-ev como-o-dia a-esta');
INSERT INTO verses VALUES (7799, 9, 22, 9, 'e respondeu do-eg ha-adomi e-ele stood sobre servos-de Saul E-disse vi a filho-de yishay veio nove a achimelech filho-de achituv');
INSERT INTO verses VALUES (7800, 9, 22, 10, 'e perguntou- a-ele em-יהוה dar a-ele para-ele espada espada Galá dar a-ele a-ele');
INSERT INTO verses VALUES (7801, 9, 22, 11, 'e-enviou o-rei para ler- a Achimeleque filho-de Achituv o-sacerdote seu-pai todo casa Abiú os-sacerdotes que [אֶל־הַמֶּֽלֶךְ׃] e-vieram todos eles a o rei');
INSERT INTO verses VALUES (7802, 9, 22, 12, 'E-disse Saul ouve: por-favor E-disse Achituv E-disse eis-me Adonai');
INSERT INTO verses VALUES (7803, 9, 22, 13, 'E-disse Saul por-que vocês amarraram- sobre-mim tu e-filho-de tu no seio de vossa a-ele a-ele pão וְשָׁא֥וֹל a-ele a-ele לָק֥וּם a-mim לְאֹרֵ֖ב como-o-dia a-esta');
INSERT INTO verses VALUES (7804, 9, 22, 14, 'e-respondeu אֲחִימֶ֛לֶךְ a o-rei E-disse e-quem em-todo teus-servos כְּדָוִ֣ד fiel וַחֲתַ֥ן o-rei וְסָ֥ר a מִשְׁמַעְתֶּ֖ךָ וְנִכְבָּ֥ד em-casa-tua');
INSERT INTO verses VALUES (7805, 9, 22, 15, 'o-dia הַחִלֹּ֛תִי a-ele בֵאלֹהִ֖ים longe-seja a-mim a יָשֵׂם֩ o-rei בְּעַבְדּ֤וֹ palavra em-todo que meu-pai porque não conheceu teu-servo em-todo Isto palavra pequeno ou grande');
INSERT INTO verses VALUES (7806, 9, 22, 16, 'E-disse o-rei morrendo morrerás [אֲחִימֶ֑לֶךְ] tu e-todo casa');
INSERT INTO verses VALUES (7807, 9, 22, 17, 'E-disse o-rei לָרָצִים֩ ha-nitzavim sobre-ele סֹ֥בּוּ וְהָמִ֣יתוּ ׀ כֹּהֲנֵ֣י yhwh yhwh que yadam com Davi e-que conheceram ele בֹרֵ֣חַ ele e-não גָל֖וּ a e-não אָב֖וּ servos-de o-rei לִשְׁלֹ֣חַ a yhwh לִפְגֹ֖עַ בְּכֹהֲנֵ֥י yhwh');
INSERT INTO verses VALUES (7808, 9, 22, 18, 'E-disse o-rei סֹ֣ב אתָ וּפְגַ֖ע tu וַיִּסֹּ֞ב הָאֲדֹמִ֗י e-ele-atacou- ele בַּכֹּ֣הֲנִ֔ים וַיָּ֣מֶת ׀ no-dia aquele [וַיָּ֣מֶת] [׀] no-dia נֹשֵא éfode linho');
INSERT INTO verses VALUES (7809, 9, 22, 19, 'e-a [נֹ֤ב] cidades- os-sacerdotes bateu à-boca-de espada de-homem e-até mulher [וַחֲמ֛וֹר] e-até [לְפִי־חָֽרֶב] [sem-traducao] [sem-traducao] o-शׂה à-boca-de espada');
INSERT INTO verses VALUES (7810, 9, 22, 20, '[וַיִּמָּלֵ֣ט] filho-de um לַאֲחִימֶ֙לֶךְ֙ filho-de אֲחִט֔וּב e-nome-dele אֶבְיָתָ֑ר וַיִּבְרַ֖ח atrás-de Davi');
INSERT INTO verses VALUES (7811, 9, 22, 21, 'e-revelou evyatar para-Davi que hārag Saul a כֹּהֲנֵ֥י yhwh');
INSERT INTO verses VALUES (7812, 9, 22, 22, 'E-disse Davi לְאֶבְיָתָ֗ר יָדַ֜עְתִּי no-dia o-aquele porque nome הָאֲדֹמִ֔י porque הַגֵּ֥ד ele-declarará de-שָׁאוּל eu סַבֹּ֔תִי em-todo alma casa pai-teu');
INSERT INTO verses VALUES (7813, 9, 22, 23, 'שְׁבָ֤ה אתי a que porque que יְבַקּוֹשׁ a alma-minha tu comigo e-comerás porque guarda-de tu comigo-');
INSERT INTO chapters VALUES (259, 9, 23, 28);
INSERT INTO verses VALUES (7814, 9, 23, 1, 'וַיַגְדּוּ para-David dizendo eis filisteus נִלְחֲמוּ בִּקְעַיָּלָה e-eles שׁוֹסִים a הַגְּרָנוֹת׃');
INSERT INTO verses VALUES (7815, 9, 23, 2, 'e-ele-perguntou Davi em-yhwh dizendo הַאֵלֶךְ וְהִכְתִּיבָה בַּפְּלִשְׁתִּים estes E-disse E-disse yhwh Davi vai e atingirás os filisteus e salvares a Queila');
INSERT INTO verses VALUES (7816, 9, 23, 3, 'e-disseram homens-de Davi a-ele eis nós poa em juízo temores e também porque andaremos com grande força a de suas marchas filisteus');
INSERT INTO verses VALUES (7817, 9, 23, 4, 'וַיּ֨וֹסֶף ainda Davi para perguntar em-יהוה e-ele-respondeu-lhe yhwh yhwh E-disse desce קְעִילָ֔ה porque eu deu a Filisteus em-mão-teu');
INSERT INTO verses VALUES (7818, 9, 23, 5, 'E-andou Davi קְעִילָ֜ה וַיִּלָּחֵם בַּפְּלִשְׁתּ֗ים e conduziu a מִקְנֵיהֶ֔ם e-feriu neles מַכָּ֣ה grande וַיֹּ֣שַׁע Davi a habitantes-de Queila');
INSERT INTO verses VALUES (7819, 9, 23, 6, 'e-houve [בִּ֠בְרֹחַ] [אֶבְיָתָ֧ר] filho-de [אֶל־דָּוִ֖ד] a Davi [יָרַ֥ד] [בְּיָדֽוֹ]');
INSERT INTO verses VALUES (7820, 9, 23, 7, 'vayuggad Саулу porque veio Davi E-disse E-disse Saul ele a-ele Elohim que porque נסגר para-vir בעיר דלותים ובריח׃');
INSERT INTO verses VALUES (7821, 9, 23, 8, 'E-ouviu Shaul a todo o-povo para-a-guerra לארדת KEEP-ILAH לאצר a Davi e-a אנשי׃');
INSERT INTO verses VALUES (7822, 9, 23, 9, 'e-soube Davi que sobre-ele Saul מחrias a má E-disse a אֶבְיָתָר o-sacerdote que deu הָאֵפֽוֹד׃');
INSERT INTO verses VALUES (7823, 9, 23, 10, 'E-disse Davi yhwh Elohim-de Israel ouviu ouviu teu-servo porque que busca Saul para-vir a enganosidade para-destruir la-ir por mim');
INSERT INTO verses VALUES (7824, 9, 23, 11, 'e me entregarão seus senhores enganosidade בְּיָדוֹ e descerá Saul como-que ouviu seu servo yhwh Elohim-de Israel conta por-favor para-servidor-teu E-disse yhwh irá:');
INSERT INTO verses VALUES (7825, 9, 23, 12, 'E-disse Davi haverão de segurá-lo: dos senhores: destruição: me e-a minha gente: E-disse yhwh E-disse yhwh segurá-lo-ão:');
INSERT INTO verses VALUES (7826, 9, 23, 13, 'E-levantou Davi e sua gente: por seis: centenas-de homem vayyats''û destruição: e andaram: ba-asher יִתְהַלָּ֑כוּ e-para-Saul הֻגַּ֗ד porque נִמְלַ֤ט Davi מִקְּעִילָ֔ה וַיֶּחְדַּ֖ל לָצֵֽאת׃');
INSERT INTO verses VALUES (7827, 9, 23, 14, 'e-ele-habitou Davi bamidbar בַּמְּצָד֔וֹת e-habitou na-montanha בְּמִדְבַּר־ Zife וַיְבַקְשֵׁ֤הוּ Saul todo os-dias e-não נְתָנ֥וֹ Elohim em-mão-sua');
INSERT INTO verses VALUES (7828, 9, 23, 15, 'E-viu Davi porque [שָׁא֖וּל] Saul [אֶת־נַפְשׁ֑וֹ] a sua-alma [בַּחֹֽרְשָׁה׃]');
INSERT INTO verses VALUES (7829, 9, 23, 16, 'E-levantou Yehonatan filho-de Saul E-andou a Davi חֹ֑רְשָׁה e-estreitou a mão-sua בֵּאלֹהִֽים׃');
INSERT INTO verses VALUES (7830, 9, 23, 17, 'E-disse a-ele a que não não תִֽמְצָאֲךָ֙ mão Saul meu-pai e-tu תִּמְלֹ֣ךְ sobre Israel e-eu אֶֽהְיֶה־ para-ti sabe e-também Saul pai-meu conheceu assim');
INSERT INTO verses VALUES (7831, 9, 23, 18, 'וַיִּכְרְת֧וּ os-dois berith diante-de yhwh e-habitou Davi o-chereshah vi-yehonatan andar para-sua-casa');
INSERT INTO verses VALUES (7832, 9, 23, 19, 'e-eles-subiram zipim a Saul dizendo dizendo porventura-não Davi mistatser im-anu bamatzdoto o-chereshah bigivata ha-chakilah que mimayin הַיְשִׁימֽוֹן׃');
INSERT INTO verses VALUES (7833, 9, 23, 20, 'e-agora para-todo [נַפְשְׁךָ֥] [הַמֶּ֛לֶךְ] o-rei [רֵ֑ד] [וְלָ֥נוּ] [הַסְגִּיר֖וֹ] [בְּיַ֥ד] na-mão-de');
INSERT INTO verses VALUES (7834, 9, 23, 21, 'E-disse Saul בְּרוּכִ֥ים vós para-יהוה que חֲמַלְתֶּ֖ם sobre-mim');
INSERT INTO verses VALUES (7835, 9, 23, 22, 'לכו- por-favor הָכִ֣ינוּ ainda e saibam e-vede a seu lugar que quem sua perna quem que disse porque nu a-mim ele levantará ela');
INSERT INTO verses VALUES (7836, 9, 23, 23, 'e vede e saibam de-toda os que estão escondidos que se esconderá nome e voltareis a-mim a certamente e caminharei convosco e-foi na-terra ישנו ele והציפתי a-ele em-todo milhares-de Judá');
INSERT INTO verses VALUES (7837, 9, 23, 24, 'ויקום e-caminharam זיפה diante-de שָׁאוּל והודע ואנשיו בהמדבר מעון בערבבה a Direito הישימון׃');
INSERT INTO verses VALUES (7838, 9, 23, 25, 'E-andou Saul e seus homens buscassem disseram para-David e-desceu o-a pedra e-habitou em-deserto-de habitação E-ouviu Saul e-perseguiu אחרי- Davi deserto-de refúgio:');
INSERT INTO verses VALUES (7839, 9, 23, 26, 'E-andou Saul do lado de o-montanha deste-lado e Davi e seus homens do lado de o-monte deste e-houve Davi estava escondido para-andar de-diante-de Saul e Saulo e seus homens a Davi e-a seus homens para pegá-los:');
INSERT INTO verses VALUES (7840, 9, 23, 27, 'e anjo veio a dizendo dizendo apressadamente e vá porque se estendeu dos-filisteus sobre a-terra');
INSERT INTO verses VALUES (7841, 9, 23, 28, 'e-estabeleceu-se Saul persegui-los depois-de Davi E-andou ao-encontro-de filisteus sobre assim chamaram para aquele lugar aquele סלע as-separações');
INSERT INTO chapters VALUES (260, 9, 24, 23);
INSERT INTO verses VALUES (7842, 9, 24, 1, 'e-ofereceu Davi de-lá e-habitou בmitesadot עין- gádi:');
INSERT INTO verses VALUES (7843, 9, 24, 2, 'e-houve como-que retornou Saul de-após filisteus e-contaram a-ele dizendo eis Davi em-o-deserto olho gádi:');
INSERT INTO verses VALUES (7844, 9, 24, 3, 'E-tomou Saul [שְׁלֹ֧שֶׁת] [אֲלָפִ֛ים] homem [בָּח֖וּר] de-todo Israel E-andou [אֶת־דָּוִד֙] a Davi [צוּרֵ֥י] sobre face-de');
INSERT INTO verses VALUES (7845, 9, 24, 4, 'E-veio a גדרות o rebanho sobre o caminho e ali a caverna E-veio Saul para medir a seus pés e-David e seus homens בְּיַרְכְּתֵ֥י הַמְּעָרָ֖ה assentam-se');
INSERT INTO verses VALUES (7846, 9, 24, 5, 'e-disseram homens-de Davi a-ele eis o-dia que yhwh yhwh eis eu eu deu a em tua mão e-farás para-ele como será bom em-olhos-teus E-levantou Davi e cortou a côrpo-do o manto que a Saúl em-lá;');
INSERT INTO verses VALUES (7847, 9, 24, 6, 'e-houve depois-de assim e-feriu ele sobre a-ele sobre que cortou a as asas que a Saúl;');
INSERT INTO verses VALUES (7848, 9, 24, 7, 'E-disse aos seus homens infelizmente a-mim מֵיְהוָה se אֶעֱשֶׂה a had-davar ha-zeh yhwh לִמְשִׁיחַ yhwh לִשְׁלֹ֥חַ minha-mão yhwh ele yhwh yhwh ela');
INSERT INTO verses VALUES (7849, 9, 24, 8, 'וַיְשַׁסַּ֨ע Davi a אֲנָשָׁיו֙ בַּדְּבָרִ֔ים e-não entregou-as arising a שָׁאוּל וְשָׁא֛וּל קָ֥ם מֵהַמְּעָרָ֖ה E-andou no-caminho');
INSERT INTO verses VALUES (7850, 9, 24, 9, 'E-levantou Davi depois-de assim e-saiu E-chamou depois-de E-chamou para-dizer dizendo o-rei E olhou Saul atrás-dele e queimou Davi dois terra-para e-prostrou-se');
INSERT INTO verses VALUES (7851, 9, 24, 10, 'E-disse Davi Саулу por-que ouviste a homem dizendo eis eis Davi que buscas a tua maldade');
INSERT INTO verses VALUES (7852, 9, 24, 11, 'eis o-dia o-este viram os-teus-olhos a que de ti yhwh hoje o-dia na-caverna e-disse e te inclinaste sobre-ti e-disse não eu lançarei mão-minha ante-meu-senhor porque ungido-de yhwh yhwh');
INSERT INTO verses VALUES (7853, 9, 24, 12, 'e meu pai viu também viu a asa מְעִילְךָ que porque בְּכָרְתִי֩ a asa מְעִֽילְךָ֜ e-não הֲרַגְתִּ֗יךָ que וּרְאֵה֙ porque nao-ha בְּיָדִ֜י רָעָ֤ה para-ti e-não pecado-eu para-ti e-tu צֹדֶ֥ה a alma-minha lekachta');
INSERT INTO verses VALUES (7854, 9, 24, 13, 'יִשְׁפֹּ֤ט yhwh entre-mim וּבֵינֶ֔ךָ e a vingança-mi yhwh de ti e a mão-mi não será- em-ti');
INSERT INTO verses VALUES (7855, 9, 24, 14, 'como dará-dize príncipe o antigo dos ímpios יצא רֶ֑שַׁע e a mão-mi não será- em-ti');
INSERT INTO verses VALUES (7856, 9, 24, 15, 'apos quem sair rei Israel depois-de quem tu perseguidor atrás-de כֶּ֣לֶב morreu depois-de פַּרְעֹ֥שׁ um');
INSERT INTO verses VALUES (7857, 9, 24, 16, 'e-será yhwh לְדַיָּ֔ן וְשָׁפַ֖ט entre-mim e-entre-tu E-viu וְיָרֵ֣ב a רִיבִ֔י וְיִשְׁפְּטֵ֖נִי de-mão-tua');
INSERT INTO verses VALUES (7858, 9, 24, 17, 'e-houve kechaloth Davi para-falar a hadavarim estes a E-disse E-disse Saul הֲקֹלְךָ֥ este filhos-de Davi e-levantou Shaul seu-grito וַיֵּֽבְךְּ׃');
INSERT INTO verses VALUES (7859, 9, 24, 18, 'E-disse a Davi tu tu que tu tu גְּמַלְתַּ֣נִי a-boa e-eu garticka hărâ''â');
INSERT INTO verses VALUES (7860, 9, 24, 19, 'הִגַּ֣דְתָּ o-dia a o-dia asita ITHI boa a que sigarni yhwh yhwh e-não hargtani');
INSERT INTO verses VALUES (7861, 9, 24, 20, 'e-quando ymtzaa homem a oayavo veshillecho no-caminho boa e-יהוה debaixo o-dia em-lugar-de o-dia este que asita a-mim');
INSERT INTO verses VALUES (7862, 9, 24, 21, 'e-agora eis soube que rei timloch veqama em-tua-mão mamleket Israel');
INSERT INTO verses VALUES (7863, 9, 24, 22, 'e-agora hisheba a-mim em-יהוה se takrit a zarei acharai e-se tashmid a nome-meu de-casa-de pai-meu');
INSERT INTO verses VALUES (7864, 9, 24, 23, 'e-ele-jurou Davi de-שָׁאוּל E-andou Saul a casa-dele e-David e-os-seus-homens subiram sobre a-muradura');
INSERT INTO chapters VALUES (261, 9, 25, 44);
INSERT INTO verses VALUES (7865, 9, 25, 1, 'E-morreu שְׁמוּאֵל e-que-coletassem todo Israel e disseram- a-ele e o sepultaram em-casa-dele em Barama- E-levantou Davi e-ele-descerrou a deserto-de em Paran-');
INSERT INTO verses VALUES (7866, 9, 25, 2, 'e-homem no morar- e seu fazer- no Carmelo- והאיש grande muito e para ele- rebanho três- milhares e um milhar e-houve E-foi em Gazez- a rebanho-seu no Carmelo-');
INSERT INTO verses VALUES (7867, 9, 25, 3, 've-shem o-homem נָבָ֔ל e-nome-de mulher-sua אֲבִגָ֑יִל וְהָאִשׁׁ֤ה טוֹבַת־ שֶׂ֙כֶל֙ וִ֣יפַת תֹּ֔אַר e-o-homem קָשֶׁ֛ה וְרַ֥ע מַעֲלָלִ֖ים e-ele');
INSERT INTO verses VALUES (7868, 9, 25, 4, 'E-ouviu Davi no-deserto porque gozez tolo a seu rebanho');
INSERT INTO verses VALUES (7869, 9, 25, 5, 'e-enviou Davi asarah ne''arim E-disse Davi lanne''arim aluu karmelah uva''item a naval ushelitem- a-ele bishmi em-paz');
INSERT INTO verses VALUES (7870, 9, 25, 6, 'e vós direis assim a vida e-tu paz e o teu lar paz e-tudo que a-ti paz');
INSERT INTO verses VALUES (7871, 9, 25, 7, 'e-agora eu ouvi que o pastoreando para-ti agora os que pastoreiam que a-ti eram não não e os desenganados a-eles estão julgados a-eles dizia-se todo dias-de sejam eles no Carmelo');
INSERT INTO verses VALUES (7872, 9, 25, 8, 'pergunte a a vossos jovens para-ti a ti e achem os jovens graça em-tua-olho bom sobre dia bom BANU dá- por-favor a que achares tu mão-tua para-o-servos-teus e para o teu filho de-Davi');
INSERT INTO verses VALUES (7873, 9, 25, 9, 'e-vieram jovens Davi e falaram a Nabal conforme-toda as-palavras estes no-nome-de Davi e se assustaram:');
INSERT INTO verses VALUES (7874, 9, 25, 10, 'e-ele-respondeu Nabal a servos-de E-disse quem quem Davi e-quem o-dia Jesai o-dia muitos escravos de-diante-de homem de-faces-de אֲדֹנָֽיו׃');
INSERT INTO verses VALUES (7875, 9, 25, 11, 'e eu tomaria a לַחְמִי֙ e-a minha água e-את meu gado que eu mataria l''gozzay e-n-d-e-rei não que não soube onde de-este eles');
INSERT INTO verses VALUES (7876, 9, 25, 12, 'va''y''hafchu jovens-de Davi l''darcham e-voltaram-se e-vieram a-ele a-ele כְּכֹ֖ל as-palavras as estas');
INSERT INTO verses VALUES (7877, 9, 25, 13, 'E-disse Davi la''anosay chigru homem a charbo va''y''achguro homem a sua espada va''y''chor também Davi a charbo va''y''aluu depois-de Davi quatro novecentos homem Um''ayim viveram sobre os-utensílios:');
INSERT INTO verses VALUES (7878, 9, 25, 14, 'e-Abigail mulher-de Nabal declarou jovem- um dizendo eis eis enviou Davi mensageiros do-deserto לְבָרֵ֥ךְ a nosso-senhhor e-ajudou neles');
INSERT INTO verses VALUES (7879, 9, 25, 15, 'e os homens bem a-nos muito e-não הָכְלַ֙מְנוּ֙ e-não פָקַ֣דְנוּ dizia-se todo os-dias הִתְהַלַּ֣כְנוּ com-elas-os בִּֽהְיוֹתֵ֖נוּ no-campo');
INSERT INTO verses VALUES (7880, 9, 25, 16, 'חוֹמָה֙ eram sobre-nós também noite também de-dia todo יְמֵ֛י הֱיוֹתֵ֥נוּ com-eles רֹעִ֥ים o-rebanho');
INSERT INTO verses VALUES (7881, 9, 25, 17, 'e-agora דְּעִ֤י וּרְאִי֙ que faz porque toda a má a nosso-senhor e-sobre todo a-ele e-ele filho-de sem falando a-ele');
INSERT INTO verses VALUES (7882, 9, 25, 18, 'e se apressou e tomou duzentos e-tomou e dois pão יַ֗יִן e-cinco ovelhas e-cinco seim grão-tostado e cem cimquím e-doiscentos davelim e pôs sobre os camelos:');
INSERT INTO verses VALUES (7883, 9, 25, 19, 'E-disse para suas moças passai diante-de-mim eis-me-aqui atrás de vós virá e para ela tolo não higiда׃');
INSERT INTO verses VALUES (7884, 9, 25, 20, 'e-será hi ׀ rochevet sobre haхamor veyoredet בְּסֵ֣תֶר o-monte e-eis Davi va''анashay yordim para-a-sua-frente vatipgаs eles');
INSERT INTO verses VALUES (7885, 9, 25, 21, 'e-David disse só-que lasheker shamariti a todo que לזה no-deserto e-não ניפקד de-todo debaixo a-ele coisa-alguma WAYYASHAB- para-mim maldade debaixo-de boa');
INSERT INTO verses VALUES (7886, 9, 25, 22, 'assim yhwh Elohim LE''AVVEI Davi e-assim YOSEIF se ASHER de-todo que para-ele até e-agora MASHTIN B''QIR:');
INSERT INTO verses VALUES (7887, 9, 25, 23, 'E-viu AVIGAYIL a Davi VATMAHER de-cima-de de-sobre o-jumento וַתִּפֹּל לְאַפֵּ֤י Davi sobre face-dela e-se-prostrou terra');
INSERT INTO verses VALUES (7888, 9, 25, 24, '[וַתִּפֹּל֙] sobre E-disse [בִּי־אֲנִ֥י] [Adonai] eu Adonai [אֲמָֽתְךָ֙] [בְּאָזְנֶ֔יךָ] por-favor [OBJ] [דִּבְרֵ֥י] [אֲמָתֶֽךָ] a');
INSERT INTO verses VALUES (7889, 9, 25, 25, 'a por-favor יָשִׂ֣ים Adonai ׀ a seu-lábo a homem o-bli-yá-al que sobre nabal porque ki-shém-o assim ele Nabal seu-nome não com-ele e eu sou serva-tua não vi a na-á-rei Adonai que shálakh-tá:');
INSERT INTO verses VALUES (7890, 9, 25, 26, 'e-agora Adonai vive yhwh e-vive nafsh-ká yhwh mén-á-akha yhwh mi-bo''á bédamim para-ti e-agora a-ti e-agora serão cankabal teus-inimigos e os que buscam a Adonai mal');
INSERT INTO verses VALUES (7891, 9, 25, 27, 'e-agora a bênção esta que trouxe sua serva ao meu senhor e foi dada aos jovens que andam pelos pés Adonai');
INSERT INTO verses VALUES (7892, 9, 25, 28, 'se por-favor para-paixão sua-serva que faça- yhwh yhwh para-seu-mestre casa fiel yhwh guerras yhwh Adonai se-lance e-male não será-encontrada que de-tus-dias∶');
INSERT INTO verses VALUES (7893, 9, 25, 29, 'E-levantou homem para-te-persegui∶ e-te-pesquises∶ a alma-tua e-será∶ alma Adonai enrolada ׀ em-enrolamento a-vida a yhwh teu-Elohim e-a alma seus-inimigos∶ ela-arranque∶ no-meio-de palma o-arranhão∶');
INSERT INTO verses VALUES (7894, 9, 25, 30, 'e-foi porque yhwh yhwh para-o-senhore∶ conforme-tudo que palavra a hatovah sobre-ti e te ordenará para-o-nagid sobre Israel');
INSERT INTO verses VALUES (7895, 9, 25, 31, 'e-não sera esta a ti a-ti e para tentação coração ao meu senhor e para derramá-lo sangue por nada e para livrá-lo Adonai a-ele e para beneficiá-lo yhwh ao meu senhor e lembra-te a -a tua serva');
INSERT INTO verses VALUES (7896, 9, 25, 32, 'E-disse Davi a Abigail bendito yhwh Elohim-de Israel que enviaste o-dia este [לִקְרָאתִֽי]');
INSERT INTO verses VALUES (7897, 9, 25, 33, 'e bendito [טַעְמֵ֖ךְ] [וּבְרוּכָ֣ה] você-é que [כְּלִתִ֜נִי] o-dia este mi-bo''á bédamim [וְהֹשֵׁ֥עַ] minha-mão a-mim');
INSERT INTO verses VALUES (7898, 9, 25, 34, 'e-entretanto vive yhwh Elohim-de Israel que [מֵהָרַ֖ע] [אֹתָ֑ךְ] que que se-nao-fosse [מִהַ֗רְתְּ] לִקְרָאתִ֔י porque se que [אִם־נוֹתַ֧ר] até luz [הַבֹּ֖קֶר] MASHTIN B''QIR:');
INSERT INTO verses VALUES (7899, 9, 25, 35, 'E-tomou Davi [מִיָּדָ֔הּ] a que a-ele a-ele disse disse ali [לְבֵיתֵ֔ךְ] para-casa-de-ti [שָׁמַ֣עְתִּי] שָׁמַ֣עְתִּי [וָאֶשָּׂ֖א] [פָּנָֽיִךְ] face-tua');
INSERT INTO verses VALUES (7900, 9, 25, 36, 'e-veio [אֲבִיגַ֣יִל] a [אֶל־נָבָ֡ל] e-eis a-ele [בְּבֵית֜וֹ] [כְּמִשְׁתֵּ֣ה] [הַמֶּ֗לֶךְ] o-rei [נָבָל֙] bom bom sobre-ele e-ele [עַד־מְאֹ֑ד] até para-ele e-não ela-contou [וְגָד֖וֹל] palavra pequeno [sem-traducao] até luz a-manhã');
INSERT INTO verses VALUES (7901, 9, 25, 37, 'e-houve na-manhã na saída o-vinho [מִנָּבָ֔ל] [וַתַּגֶּד־ל֣וֹ] a-ele mulher-dele a as-palavras estes E-morreu coração-seu ser e-ele foi [sem-traducao]');
INSERT INTO verses VALUES (7902, 9, 25, 38, 'e-houve [כַּעֲשֶׂ֣רֶת] os-dias [וַיִּגֹּ֧ף] yhwh a tolo E-morreu');
INSERT INTO verses VALUES (7903, 9, 25, 39, 'E-ouviu Davi que morreu [נָבָל֒] E-disse בָּר֣וּךְ yhwh que muito a [חֶרְפָּתִ֜י] [מִיַּ֣ד] da-mão-de nabal e-a seu-aervo e-[OBJ] [רָעַ֣ת] e-את [הֵשִׁ֥יב] yhwh retornou yhwh [דָּוִד֙] e-estendeu Davi e-falou a-ele [לְאִשָּֽׁה] para-ele para-mulher');
INSERT INTO verses VALUES (7904, 9, 25, 40, 'e-vieram servos-de Davi a [הַכַּרְמֶ֑לָה] [וַיְדַבְּר֤וּ] [אֵלֶ֙יהָ֙] dizendo dizendo Davi [אֵלַ֔יִךְ] אֵלַ֔יִךְ a-ele a-ele para-mulher');
INSERT INTO verses VALUES (7905, 9, 25, 41, 'e-levantou [וַתִּשְׁתַּ֥חוּ] Apaim terra E-disse eis אֲמָֽתְךָ֙ [לְשִׁפְחָ֔ה] [לִרְחֹ֕ץ] [רַגְלֵ֖י] servos-de Adonai');
INSERT INTO verses VALUES (7906, 9, 25, 42, '[וַתְּמַהֵ֞ר] e-levantou-se [אֲבִיגַ֗יִל] [וַתִּרְכַּב֙] sobre o-jumento e cinco [הַהֹלְכ֖וֹת] [לְרַגְלָ֑הּ] [וַתֵּ֗לֶךְ] e-ela-partiu atrás-de mensageiros-de Davi e-ela-tornou-se para-ele para-mulher');
INSERT INTO verses VALUES (7907, 9, 25, 43, 'e-[OBJ] tomou tomou Davi [וַתִּהְיֶ֛יןָ] [גַּֽם־שְׁתֵּיהֶ֥ן] a-ele [לְנָשִֽׁים׃]');
INSERT INTO verses VALUES (7908, 9, 25, 44, '[וְשָׁא֗וּל] dar a [בִּתּ֖וֹ] [אֵ֣שֶׁת] mulher-de Davi [בֶן־לַ֖יִשׁ] filho-de [מִגַּלִּֽים] que [sem-traducao]');
INSERT INTO chapters VALUES (262, 9, 26, 25);
INSERT INTO verses VALUES (7909, 9, 26, 1, '[וַיָּבֹ֤אוּ] [הַזִּפִים֙] a Saul dizendo dizendo porventura-não Davi [בְּגִבְעַ֣ת] [הַחֲכִילָ֔ה] sobre face-de face-de');
INSERT INTO verses VALUES (7910, 9, 26, 2, 'E-levantou Saul [וַיֵּ֙רֶד֙] a no deserto- [שְׁלֹֽשֶׁת־אֲלָפִ֥ים] [אִ֖ישׁ] três- milhares homem be-churei Israel para-buscar a Davi בְּמִדְבַּר־ [sem-traducao]');
INSERT INTO verses VALUES (7911, 9, 26, 3, '[וַיִּ֨חַן] Saul [בְּגִבְעַ֣ת] [הַחֲכִילָ֗ה] que sobre face-de [עַל־הַדָּ֑רֶךְ] sobre ha-dar''ke'' e-David E-viu que E-viu porque veio Shaul atrás-dele [sem-traducao]');
INSERT INTO verses VALUES (7912, 9, 26, 4, 'e-enviou Davi [מְרַגְּלִ֑ים] e-ele-conheceu porque veio Saul a [sem-traducao]');
INSERT INTO verses VALUES (7913, 9, 26, 5, 'E-levantou Davi E-veio a o-lugar que [שָׁאוּל֒] E-viu [דָּוִ֗ד] E-viu Davi a o-lugar que [בֶּן־נֵ֖ר] nome Saul [שֹׁכֵ֣ב] filho-de neṛ príncipe-de [*סביבתו] [**סְבִיבֹתָֽיו] deitado [sem-traducao] e-o-povo [sem-traducao]');
INSERT INTO verses VALUES (7914, 9, 26, 6, 'e-ele-respondeu Davi E-disse a [אֶל־אֲחִימֶ֣לֶךְ] [הַחִתִּ֗י] e-a [בֶּן־צְרוּיָ֜ה] filho-de צְרוּיָה dizendo Joabe dizendo quem [אֶל־הַֽמַּחֲנֶ֑ה] E-disse a Saul a o-acampamento E-disse Abisai eu [sem-traducao] contigo');
INSERT INTO verses VALUES (7915, 9, 26, 7, 'E-veio Davi [וַאֲבִישַׁ֥י] a o-povo noite e-eis Saul dormindo velho [בַּמַּעְגָּ֔ל] [וַחֲנִית֥וֹ] [מְעוּכָֽה־בָאָ֖רֶץ] em-a-terra e-אַבְנֵר e-o-povo [וְהָעָ֔ם]');
INSERT INTO verses VALUES (7916, 9, 26, 8, 'E-disse [אֲבִישַׁי֙] a Davi entregou o-dia o-dia a e-agora em-mão-tua [נָ֜א] [בַּחֲנִ֤ית] por-favor vez uma vez uma a-ele [sem-traducao] a-ele');
INSERT INTO verses VALUES (7917, 9, 26, 9, 'E-disse Davi a [אַל־תַּשְׁחִיתֵ֑הוּ] que quem porque sua-mão enviou yhwh [וְנִקָּֽה׃] yhwh');
INSERT INTO verses VALUES (7918, 9, 26, 10, 'E-disse Davi vive que porque se yhwh [יָבוֹא֙] ou [א֧וֹ] virá vâmêt ou [sem-traducao] יֵרֵ֖ד [sem-traducao]');
INSERT INTO verses VALUES (7919, 9, 26, 11, '[חָלִ֤ילָה] a-mim מֵֽיהוָ֔ה [מִשְּׁלֹ֥חַ] minha-mão [בִּמְשִׁ֣יחַ] yhwh e-agora toma por-favor a a-lança que e-a [הַמַּ֖יִם] as-águas [לָּֽנוּ] para nós');
INSERT INTO verses VALUES (7920, 9, 26, 12, 'E-tomou Davi a a-lança e-a [מֵרַאֲשֹׁתֵ֣י] as-águas [וַיֵּלְכ֖וּ] a-eles e-foram a-eles e-não-há viu וְאֵ֨ין [מֵקִ֗יץ] que [כֻלָּם֙] porque que [תַּרְדֵּמַ֣ת] yhwh [נָפְלָ֖ה] yhwh caiu sobre-eles');
INSERT INTO verses VALUES (7921, 9, 26, 13, 'e-ele-passou Davi [הָעֵ֔בֶר] e-estabeleceu sobre cume-de o-monte [הַמָּק֖וֹם] muito o-lugar [sem-traducao]');
INSERT INTO verses VALUES (7922, 9, 26, 14, 'E-chamou Davi a o-povo e-a dizendo filho-de Ner dizendo não [אַבְנֵר֙] E-disse quem tu E-disse quem tu [sem-traducao] a o rei');
INSERT INTO verses VALUES (7923, 9, 26, 15, 'E-disse Davi a Abner tu homem tu e-quem [וְלָ֙מָּה֙] não e-por-que não guardaste a senhor-teu o-rei porque veio um o-povo [sem-traducao] a o-rei seus-mestres');
INSERT INTO verses VALUES (7924, 9, 26, 16, 'não bom a-palavra hazeh que [חַי־יְהוָ֗ה] que yhwh porque filhos-de morte אַתֶּ֔ם que yhwh e-agora sobre [רְאֵ֗ה] sobre [הַמֶּ֛לֶךְ] yhwh e-agora viu ei- [**מְרַאֲשֹׁתָֽיו] o-rei e-a [sem-traducao] as-águas que');
INSERT INTO verses VALUES (7925, 9, 26, 17, 'e reconheceu Saul a voz-de E-disse E-disse [זֶ֖ה] este filhos-de E-disse E-disse Davi קולי Adonai o rei');
INSERT INTO verses VALUES (7926, 9, 26, 18, 'E-disse por-que isto Adonai [רֹדֵ֖ף] depois-de seu-servo que que fiz e-que em-a-mão-meia mal');
INSERT INTO verses VALUES (7927, 9, 26, 19, 'e-agora [יִֽשְׁמַֽע־נָא֙] por-favor Adonai o-rei a palavras-de seu-servo se yhwh [יָרַ֣ח] [מִנְחָ֔ה] [וְאִ֣ם] oferenda e-se o-homem o-homem eles [לִפְנֵ֣י] yhwh yhwh o-dia [מֵהִסְתַּפֵּ֜חַ] o-dia yhwh dizendo yhwh dizendo vai servo Elohim aḥērim');
INSERT INTO verses VALUES (7928, 9, 26, 20, 'e-agora a [דָּֽמִי֙] [אַ֔רְצָה] terra-para face-de yhwh yhwh porque [יִשְׂרָאֵ֗ל] rei Israel um a [יִרְדֹּ֥ף] um como [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (7929, 9, 26, 21, 'E-disse Saul [חָטָ֜אתִי] volta [בְּנִֽי־דָוִ֗ד] que porque a-ti [ע֔וֹד] debaixo ainda [יָקְרָ֥ה] que [בְּעֵינֶ֖יךָ] o-dia nos-teus-olhos eis este eis [הַרְבֵּ֥ה] muito muito muito');
INSERT INTO verses VALUES (7930, 9, 26, 22, 'e-respondeu Davi E-disse eis o-rei [**חֲנִ֣ית] um [וְיַעֲבֹ֛ר] um');
INSERT INTO verses VALUES (7931, 9, 26, 23, 'e-יהוה יָשִׁיב para-o homem a [וְאֶת־אֱמֻנָת֑וֹ] e-a [נְתָנְךָ֨] yhwh [׀] o-dia o-dia [וְלֹ֣א] e-não [לִשְׁלֹ֥חַ] לִשְׁלֹ֥חַ minha-mão yhwh yhwh');
INSERT INTO verses VALUES (7932, 9, 26, 24, 'e-eis como [גָּדְלָ֧ה] [נַפְשְׁךָ֛] o-dia este em-o-s-olhos assim [תִּגְדַּ֤ל] alma-minha aos-olhos-de yhwh [וְיַצִּלֵ֖נִי] de-todo angústia');
INSERT INTO verses VALUES (7933, 9, 26, 25, 'E-disse Saul a Davi tu tu filhos-de também também fez [וְגַ֖ם] e-também podia [וַיֵּ֤לֶךְ] E-andou Davi [וְשָׁא֖וּל] ve-Shaul retornou para-o-lugar-seu');
INSERT INTO chapters VALUES (263, 9, 27, 12);
INSERT INTO verses VALUES (7934, 9, 27, 1, 'E-disse Davi a coração-dele עַתָּ֛ה [יוֹם־אֶחָ֖ד] dia-de um bom que não-há para-mim bom porque [פְּלִשְׁתִּ֗ים] [וְנוֹאַ֨שׁ] a terra [לְבַקְשֵׁ֤נִי] [עוֹד֙] [בְּכָל־גְּב֣וּל] Saul [וְנִמְלַטְתִּ֖י] ainda em-todo território Israel [sem-traducao] imediatamente');
INSERT INTO verses VALUES (7935, 9, 27, 2, 'E-levantou Davi vayaavor ele e-seis- centenas homem que com-ele a Achis filho-de [sem-traducao] rei Gat:');
INSERT INTO verses VALUES (7936, 9, 27, 3, 'e-ele-estabeleceu-se Davi com Achis ele ele [אִ֣ישׁ] homem e-casa-sua Davi e-duas-de [אֲחִינֹ֙עַם֙] Ainoã a-jezreelita [אֵֽשֶׁת־נָבָ֖ל] esposa-de tolo a-carmelita');
INSERT INTO verses VALUES (7937, 9, 27, 4, 'vayuggad Саулу porque [דָּוִ֖ד] Davi [וְלֹֽא־*יוסף] e-não ainda [לְבַקְשֽׁוֹ׃]');
INSERT INTO verses VALUES (7938, 9, 27, 5, 'E-disse Davi a [אִם־נָא֩] se por-favor achei graça lugar deem para-mim lugar [וְאֵ֣שְׁבָה] cidades-de o-campo [יֵשֵׁ֧ב] nome [בְּעִ֥יר] habitou עַבְדְּךָ֛ em-cidade-de o-reino contigo');
INSERT INTO verses VALUES (7939, 9, 27, 6, 'e-ele-deu a-ele no-dia no-dia aquele a era portanto foi-ela [יְהוּדָ֔ה] até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (7940, 9, 27, 7, 'e-houve número os-dias que habitou Davi em-campo-de pelos-filisteus dias e-quatro meses');
INSERT INTO verses VALUES (7941, 9, 27, 8, 'e-subiu Davi [וֽ͏ַאֲנָשָׁ֔יו] [וַֽיִּפְשְׁט֛וּ] a [*והגרזי] [**וְהַגִּזְרִ֖י] porque que [הֵ֜נָּה] a-terra a-terra mē-ʿōlām [מֵֽעוֹלָ֔ם] [בּוֹאֲךָ֥] e-até terra Egito');
INSERT INTO verses VALUES (7942, 9, 27, 9, '[וְהִכָּ֤ה] Davi a a-terra e-não [אִ֣ישׁ] homem e-tome [צֹ֨אן] [וּבָקָ֜ר] [וַחֲמֹרִ֤ים] [וּגְמַלִּים֙] [וּבְגָדִ֔ים] [וַיָּ֖שָׁב] [וַיָּבֹ֥א] E-veio a');
INSERT INTO verses VALUES (7943, 9, 27, 10, 'E-disse Aichis a o-dia E-disse E-disse Davi sobre [וְעַל־נֶ֣גֶב] Judá e-sobre Neguebe [sem-traducao] e-a Nēgēb o-Qeni');
INSERT INTO verses VALUES (7944, 9, 27, 11, 'e-homem [וְאִשָּׁ֜ה] não [דָוִ֗ד] Davi para-trazer dizendo dizendo para-que-não dizendo sobre nós dizendo assim fez Davi e-assim [יָשַׁ֖ב] todo [פְלִשְׁתִּֽים] que habitou no-campo Filisteus');
INSERT INTO verses VALUES (7945, 9, 27, 12, '[וַיַּאֲמֵ֥ן] acis [בְּדָוִ֣ד] dizendo [הַבְאֵ֤שׁ] [הִבְאִישׁ֙] [בְּעַמּ֣וֹ] ביישרא엘 [וְהָ֥יָה] a-mim [לְעֶ֥בֶד] eternidade');
INSERT INTO chapters VALUES (264, 9, 28, 25);
INSERT INTO verses VALUES (7946, 9, 28, 1, 'e-houve em-os-dias aqueles [וַיִּקְבְּצ֨וּ] [פְלִשְׁתִּ֤ים] a [לַצָּבָ֔א] la-tzava para-lutar E-disse E-disse Achis a Davi que sabes porque אתי tu [וַאֲנָשֶֽׁיךָ] tu [sem-traducao]');
INSERT INTO verses VALUES (7947, 9, 28, 2, 'E-disse Davi a Aichis tu tu [OBJ] a que E-disse servo-teu E-disse Achis a Davi portanto [כָּל־הַיָּמִֽים׃] [sem-traducao] [sem-traducao] todo os dias');
INSERT INTO verses VALUES (7948, 9, 28, 3, 'e-Samuel morreu e disseram- a-ele todo Israel e o sepultaram [וְשָׁא֗וּל] [הֵסִ֛יר] [הָאֹב֥וֹת] [וְאֶת־הַיִּדְּעֹנִ֖ים] [מֵהָאָֽרֶץ] e-a [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (7949, 9, 28, 4, 'e-reuniram-se filisteus e-vieram e-acamparam [בְשׁוּנֵ֑ם] וַיִּקְבֹּ֤ץ Saul a todo Israel e-acamparam em Gileade:');
INSERT INTO verses VALUES (7950, 9, 28, 5, 'E-viu Saul a acampamento-de pelos-filisteus E-viu e-tremeu muito muito');
INSERT INTO verses VALUES (7951, 9, 28, 6, 'e-ele-perguntou Saul em-יהוה e-não [עָנָ֖הוּ] yhwh também [בַּחֲלֹמ֛וֹת] também [בָּאוּרִ֖ים] também [בַּנְּבִיאִֽם]');
INSERT INTO verses VALUES (7952, 9, 28, 7, 'E-disse Saul [לַעֲבָדָ֗יו] [בַּקְּשׁוּ־לִי֙] para-mim mulher-de [וְאֵלְכָ֥ה] [אֵלֶ֖יהָ] [וְאֶדְרְשָׁה־בָּ֑הּ] para-ela [עֲבָדָיו֙] a-ele eis seus-servos a-ele [בְּעֵ֥ין] mulher-de [sem-traducao] א֖וֹב [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (7953, 9, 28, 8, '[וַיִּתְחַפֵּ֣שׂ] Saul [וַיִּלְבַּשׁ֙] roupas outros E-andou ele e-dois-de homens com-ele e-vieram a noite E-disse E-disse por-favor para-mim [וְהַ֣עֲלִי] [לִ֔י] a-mim a que disse [sem-traducao]');
INSERT INTO verses VALUES (7954, 9, 28, 9, 'E-disse [הָֽאִשָּׁ֜ה] a-ele eis tu [יָדַ֙עְתָּ֙] a que fez Saul que [אֶת־הָאֹב֥וֹת] a [מִן־הָאָ֑רֶץ] e-[OBJ] tu de a-terra [לַהֲמִיתֵֽנִי]');
INSERT INTO verses VALUES (7955, 9, 28, 10, '[וַיִּשָּׁ֤בַֽע] a-ela Saul em-יהוה dizendo vive yhwh se [בַּדָּבָ֥ר] עון em-a-palavra a-esta');
INSERT INTO verses VALUES (7956, 9, 28, 11, 'E-disse a-mulher a quem E-disse para-ti E-disse a שְׁמוּאֵל [sem-traducao] a-mim');
INSERT INTO verses VALUES (7957, 9, 28, 12, 'E-viu a-mulher a שְׁמוּאֵל e-ela-gritou com-voz E-disse [הָאִשָּׁ֨ה] a-mulher dizendo s-h-a-u-l para-dizer por-que [שָׁאֽוּל] ve-a-ta-ha שָׁאוּל');
INSERT INTO verses VALUES (7958, 9, 28, 13, 'E-disse a-ela o-rei a que porque que E-disse e ela disse a-mulher a Saul Elohim vi subindo de a-terra');
INSERT INTO verses VALUES (7959, 9, 28, 14, 'E-disse a-ela que E-disse e-disse homem [עֹלֶ֔ה] [וְה֥וּא] e-ele [מְעִ֑יל] [וַיֵּ֤דַע] e-conheceu Saul ele Samuel ele e ardeu dois terra-para e-prostrou-se');
INSERT INTO verses VALUES (7960, 9, 28, 15, 'E-disse Samuel a Saul por-que [לְהַעֲל֣וֹת] para-levar-acima E-disse E-disse [צַר־לִ֨י] muito para-mim muito [נִלְחָמִ֣ים] נִלְחֲמוּ [וֵֽאלֹהִ֞ים] [סָ֤ר] saiu [וְלֹֽא־עָנָ֣נִי] e-não também ainda também [וָאֶקְרָאֶ֣ה] a-ti também [מָ֥ה] [אֶעֱשֶֽׂה׃] a-ti [sem-traducao] que [sem-traducao]');
INSERT INTO verses VALUES (7961, 9, 28, 16, 'E-disse שְׁמוּאֵל e-para-que [תִּשְׁאָלֵ֑נִי] וַיהוָ֛ה [סָ֥ר] [מֵעָלֶ֖יךָ] e-houve [עָרֶֽךָ]');
INSERT INTO verses VALUES (7962, 9, 28, 17, 'E-fez yhwh a-ele como palavra b''yadi e-ele-arrancou yhwh a [מִיָּדֶ֔ךָ] [וַֽיִּתְּנָ֖הּ] [לְרֵעֲךָ֥] [לְדָוִֽד] de-Davi');
INSERT INTO verses VALUES (7963, 9, 28, 18, 'como não ouviste-sha- yhwh yhwh e-não fiz-te [עַל־כֵּן֙] sua-ira [הַזֶּ֔ה] sobre yhwh o-dia este עָשָֽׂה־ para-ti yhwh o-dia a-esta');
INSERT INTO verses VALUES (7964, 9, 28, 19, 'E-deu yhwh também a Israel contigo pela-mão-de tu וּמָחָ֕ר tu também comigo também a yhwh Israel dará yhwh por-mão-de filisteus');
INSERT INTO verses VALUES (7965, 9, 28, 20, 'vayemaher Saul [וַיִּפֹּ֤ל] [מְלֹא־קֽוֹמָתוֹ֙] [אַ֔רְצָה] terra-para muito muito [שְׁמוּאֵ֑ל] Samuel também nele que não comer pão não [וְכָל־הַלָּֽיְלָה] Belém todo o-dia e-todo a-noite');
INSERT INTO verses VALUES (7966, 9, 28, 21, 'e-entrou a-mulher a E-viu e-ela-viu muito E-disse a-ele eis a-ele eis [בְּקוֹלֶ֔ךָ] [וָאָשִׂ֤ים] [נַפְשִׁי֙] [בְּכַפִּ֔י] alma-minha [אֶת־דְּבָרֶ֔יךָ] [אֲשֶׁ֥ר] a devarêchá que a-ele para-mim');
INSERT INTO verses VALUES (7967, 9, 28, 22, 'e-agora shema- por-favor também tu com-voz [לְפָנֶ֛יךָ] [פַּת־לֶ֖חֶם] לְפָנֶ֛יךָ e-seja pao [כֹּ֔חַ] que andarás כֹּחַ porque תלך no-caminho');
INSERT INTO verses VALUES (7968, 9, 28, 23, '[וַיְמָאֵ֗ן] E-disse não [אֹכַ֔ל] [וַיִּפְרְצוּ־ב֤וֹ] em-ele seus-servos e-também a-mulher E-ouviu [מֵֽהָאָ֔רֶץ] E-levantou [אֶל־הַמִּטָּֽה] e-habitou a o-leito');
INSERT INTO verses VALUES (7969, 9, 28, 24, '[וְלָאִשָּׁ֤ה] [עֵֽגֶל־מַרְבֵּק֙] [בַּבַּ֔יִת] na-casa [וַתִּזְבָּחֵ֑הוּ] [וַתִּקַּח־קֶ֣מַח] [וַתָּ֔לָשׁ] qemakh [מַצּֽוֹת] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (7970, 9, 28, 25, '[וַתַּגֵּ֧שׁ] diante-de- Shaul e-diante-de servos-dele וַיֹּאכֵ֑לוּ [וַיֵּלְכ֖וּ] e-foram na-noite a-aquela');
INSERT INTO chapters VALUES (265, 9, 29, 11);
INSERT INTO verses VALUES (7971, 9, 29, 1, '[וַיִּקְבְּצ֧וּ] [פְלִשְׁתִּ֛ים] a todo [וְיִשְׂרָאֵ֣ל] [חֹנִ֔ים] [בַּעַ֖יִן] [אֲשֶׁ֥ר] [בְּיִזְרְעֶֽאל] que');
INSERT INTO verses VALUES (7972, 9, 29, 2, 'vesarney filisteus ovrim [לְמֵא֖וֹת] [וְלַאֲלָפִ֑ים] e-David e seus homens [עֹֽ[m]בְרִ֛ים] com [עִם־אָכִֽישׁ]');
INSERT INTO verses VALUES (7973, 9, 29, 3, 'e-disseram príncipes-de filisteus que [הָעִבְרִ֣ים] estes E-disse [אָכִ֜ישׁ] a príncipes-de פְלִשְׁתִּ֗ים acaso-nao isto Davi [שָׁא֣וּל] Saul rei-de ser que foi אתי este dias ou nele dois e-não encontrei nele dizia-se desde-dia [sem-traducao] até o-dia a-esta');
INSERT INTO verses VALUES (7974, 9, 29, 4, '[וַיִּקְצְפ֨וּ] sobre-ele príncipes-de פְלִשְׁתִּ֗ים e-disseram a-ele príncipes-de filisteus [הָשֵׁ֣ב] a o-homem e-voltará a seu lugar que [וְלֹֽא־יֵרֵ֤ד] nome e-não [וְלֹא־יִֽהְיֶה־לָּ֥נוּ] [לְשָׂטָ֖ן] na-guerra e-não sera para-nos [אֶל־אֲדֹנָ֔יו] em-batalha [בְּרָאשֵׁ֖י] [הָאֲנָשִׁ֥ים] este a a-ele [sem-traducao] [sem-traducao] os homens ha-hem');
INSERT INTO verses VALUES (7975, 9, 29, 5, 'porventura-não este Davi que [בַּמְּחֹל֖וֹת] dizendo [הִכָּ֤ה] dizendo bateu Saul [*ברבבתו] e-David');
INSERT INTO verses VALUES (7976, 9, 29, 6, 'E-chamou [אָכִ֜ישׁ] a E-disse a-ele [חַי־יְהוָ֞ה] vive tu porque ישׁר tu e-bom [אִתִּי֙] [בַּֽמַּחֲנֶ֔ה] que אתי no-acampamento porque não [בֹּאֲךָ֥] em-ti maldade [הַזֶּ֑ה] em-você a-mim até o-dia esta e-no-livro [sem-traducao] não bom tu');
INSERT INTO verses VALUES (7977, 9, 29, 7, 'e-agora volta e-vaia em-a-paz e-não mal mau em-olhos-de [פְלִשְׁתִּֽים׃] Filisteus');
INSERT INTO verses VALUES (7978, 9, 29, 8, 'E-disse Davi a que porque [עָשִׂ֙יתִי֙] eu fiz e-que [מִיּוֹם֙] [אֲשֶׁ֣ר] מִיּוֹם֙ que até o-dia até que não porque não [בְּאֹיְבֵ֖י] [Adonai] [הַמֶּֽלֶךְ] Adonai o rei');
INSERT INTO verses VALUES (7979, 9, 29, 9, 'e-respondeu [אָכִישׁ֮] E-disse a Davi que bom tu tu em-olhos-meus [הָאֱלֹהִ֔ים] Elohim somente príncipes-de filisteus disseram não subirá [sem-traducao] na-guerra');
INSERT INTO verses VALUES (7980, 9, 29, 10, 'e-agora o-manhã de-manhã [וְעַבְדֵ֥י] senhor-teu que vieram contigo [בַּבֹּ֔קֶר] de-manhã a-vós a-vós [sem-traducao]');
INSERT INTO verses VALUES (7981, 9, 29, 11, 'e-ele-se-levantou Davi ele e-os-seus-homens para-andar de-manhã para-retornar a terra filisteus e-filisteus subiram Jeová-sara');
INSERT INTO chapters VALUES (266, 9, 30, 31);
INSERT INTO verses VALUES (7982, 9, 30, 1, 'e-houve [בְּבֹ֨א] Davi e seus homens [צִֽקְלַ֖ג] no-dia o terceiro [וַעֲמָלֵקִ֣י] [פָֽשְׁט֗וּ] a [וְאֶל־צִ֣קְלַ֔ג] e-a [אֶת־צִ֣קְלַ֔ג] va-yakku'' a [בָּאֵֽשׁ] [sem-traducao] a-ela em-a-chama');
INSERT INTO verses VALUES (7983, 9, 30, 2, '[וַיִּשְׁבּ֨וּ] a [אֲשֶׁר־בָּהּ֙] que nela não e-até grande não [וַיֵּלְכ֖וּ] homem [sem-traducao] e-foram [sem-traducao]');
INSERT INTO verses VALUES (7984, 9, 30, 3, 'E-veio Davi e-os-seus-homens a a-cidade e-eis [בָּאֵ֑שׁ] no-fogo [וּבְנֵיהֶ֥ם] [וּבְנֹתֵיהֶ֖ם] [נִשְׁבּֽוּ] [sem-traducao]');
INSERT INTO verses VALUES (7985, 9, 30, 4, '[וַיִּשָּׂ֨א] Davi [וְהָעָ֧ם] que [אֶת־קוֹלָ֖ם] a até [אֲשֶׁ֧ר] até que não-há');
INSERT INTO verses VALUES (7986, 9, 30, 5, 'e-dois mulheres-de Davi [אֲחִינֹ֙עַם֙] Ainoã a-jezreelita e-Abigail mulher-de Nabal o-carmelita');
INSERT INTO verses VALUES (7987, 9, 30, 6, '[וַתֵּ֨צֶר] [לְדָוִ֜ד] muito porque [הָעָם֙] o-povo [כִּֽי־מָ֙רָה֙] porque [כָּל־הָעָ֔ם] alma todo o-povo homem sobre e-sobre [בַּיהוָ֖ה] [אֱלֹהָֽיו׃] Davi');
INSERT INTO verses VALUES (7988, 9, 30, 7, 'E-disse Davi a [הַכֹּהֵן֙] o-sacerdote filho-de [לִ֖י] [הָאֵפֹ֑ד] [וַיַּגֵּ֧שׁ] a-mim [אֶת־הָאֵפֹ֖ד] [אֶל־דָּוִֽד] a a Davi');
INSERT INTO verses VALUES (7989, 9, 30, 8, 'e-ele-perguntou Davi em-yhwh dizendo [אֶרְדֹּ֛ף] depois-de [הַגְּדוּד־הַזֶּ֖ה] este E-disse a-ele a-ele [כִּֽי־הַשֵּׂ֥ג] porque [וְהַצֵּ֥ל] [תַּצִּֽיל] e-o-salve libertar-te-:');
INSERT INTO verses VALUES (7990, 9, 30, 9, 'E-andou Davi ele e-seis- centenas homem que com-ele e-vieram até vale-de [עָמָֽדוּ] [sem-traducao] estavam:');
INSERT INTO verses VALUES (7991, 9, 30, 10, '[וַיִּרְדֹּ֣ף] Davi ele e-quatro-de centenas-de homem e-pararam maatayim homem que [מֵעֲבֹ֖ר] m-av-v-r a ribeiro-de [sem-traducao]');
INSERT INTO verses VALUES (7992, 9, 30, 11, 'e-os-acharam homem-de [בַּשָּׂדֶ֔ה] no-campo ele ele a pão e-comeu a-ele pão [sem-traducao] [sem-traducao] águas');
INSERT INTO verses VALUES (7993, 9, 30, 12, 'e deram- a-ele [דְּבֵלָ֜ה] [וּשְׁנֵ֤י] e-dois-de e-comeu [וַתָּ֥שָׁב] e-ela-voltou-se a-ele que porque pão [וְלֹא־שָׁ֣תָה] águas e-não [יָמִ֖ים] águas três dias [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (7994, 9, 30, 13, 'E-disse a-ele Davi [לְֽמִי־אַ֔תָּה] tu e-qualquer de-este E-disse E-disse [מִצְרִ֣י] eu [עֶ֚בֶד] servo para-homem [וַיַּעַזְבֵ֧נִי] [Adonai] que porque o-dia o-dia três');
INSERT INTO verses VALUES (7995, 9, 30, 14, '[אֲנַ֡חְנוּ] [פָּשַׁ֜טְנוּ] [נֶ֧גֶב] [הַכְּרֵתִ֛י] e-sobre que para juáda e-sobre Neguebe [שָׂרַ֥פְנוּ] e-a [sem-traducao] [sem-traducao] em-o-fogo');
INSERT INTO verses VALUES (7996, 9, 30, 15, 'E-disse a-ele Davi [הֲתוֹרִדֵ֖נִי] a [הַזֶּ֑ה] E-disse E-disse a-mim [בֵֽאלֹהִ֜ים] [אִם־תְּמִיתֵ֗נִי] se [בְּיַד־אֲדֹנִ֔י] e-se [אֶל־הַגְּד֥וּד] pela-mão-de Adonai a');
INSERT INTO verses VALUES (7997, 9, 30, 16, '[וַיֹּ֣רִדֵ֔הוּ] e-eis [נְטֻשִׁ֖ים] sobre face-de todo a-terra [וְחֹ֣גְגִ֔ים] [בְּכֹל֙] [הַשָּׁלָ֣ל] em-todo [אֲשֶׁ֥ר] a-grande que [פְּלִשְׁתִּ֖ים] da-terra-de Filisteus [sem-traducao] Judá');
INSERT INTO verses VALUES (7998, 9, 30, 17, 'e-ele-golpeou-vos Davi [מֵהַנֶּ֥שֶׁף] e-até [לְמָֽחֳרָתָ֑ם] [וְלֹֽא־נִמְלַ֤ט] e-não נִמְלַ֤ט que homem porque se quatro centenas homem-de [sem-traducao] que [sem-traducao] sobre os-camelo [sem-traducao]');
INSERT INTO verses VALUES (7999, 9, 30, 18, '[וַיַּצֵּ֣ל] Davi a todo que tomaram עֲמָלֵק e-a duas-de suas mulheres: salvou Davi');
INSERT INTO verses VALUES (8000, 9, 30, 19, 'e-não [נֶעְדַּר־לָ֠הֶם] לַהֲמֵם de [וְעַד־בָּנִ֤ים] e-até o-grande e-até filhos [לָקְח֖וּ] a-eles ve-ad todo que tomaram a-eles o-ouro retornou Davi');
INSERT INTO verses VALUES (8001, 9, 30, 20, 'E-tomou Davi a todo a-o-rebanho [לִפְנֵי֙] [הַמִּקְנֶ֣ה] diante-de [וַיֹּ֣אמְר֔וּ] aquele e-disseram este despojo Davi');
INSERT INTO verses VALUES (8002, 9, 30, 21, 'E-veio Davi a duzentos os-homens que [מִלֶּ֣כֶת] [׀] depois-de Davi [וַיֹּֽשִׁיבֻם֙] בְּנַחַל [הַבְּשׂ֔וֹר] e-saíram ao-encontro-de Davi [וְלִקְרַ֖את] o-povo que com-ele וַיִּגַּ֤שׁ Davi a a-eles e-pediu a-eles em-paz');
INSERT INTO verses VALUES (8003, 9, 30, 22, 'e respondeu todo homem-de mau [אֲשֶׁ֣ר] [הָלְכ֣וּ] que caminharam com Davi e-disseram porque que a-eles caminharam comigo não deu a-eles [וְאֶת־בָּנָ֔יו] que [וְיֵלֵֽכוּ׃] porque se homem a dizendo e-a filhos-dele [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (8004, 9, 30, 23, 'E-disse Davi não [כֵ֖ן] assim [OBJ] a yhwh deu yhwh a-nós E-colocou a-nós E-deu a [בְּיָדֵֽנוּ] הַבּ֥א sobre nós b''yadenu:');
INSERT INTO verses VALUES (8005, 9, 30, 24, 'e-quem [יִשְׁמַ֣ע] a-vós [לַדָּבָ֖ר] este que [כְּחֵ֣לֶק] [׀] [הַיֹּרֵ֣ד] [בַּמִּלְחָמָ֗ה] o-sentado sobre os-vasos [יַחְדָּ֥ו] [יַחֲלֹֽקוּ׃]');
INSERT INTO verses VALUES (8006, 9, 30, 25, 'e-houve [מֵֽהַיּ֥וֹם] aquele e-para-cima [וַיְשִׂמֶ֜הָ] [לְחֹ֤ק] [וּלְמִשְׁפָּט֙] para-Israel até o-dia a-esta');
INSERT INTO verses VALUES (8007, 9, 30, 26, 'E-veio Davi a [וַיְשַׁלַּ֧ח] [מֵֽהַשָּׁלָ֛ל] [לְזִקְנֵ֥י] [יְהוּדָ֖ה] Judá dizendo eis a-vós a-vós [מִשְּׁלַ֖ל] [אֹיְבֵ֥י] yhwh yhwh');
INSERT INTO verses VALUES (8008, 9, 30, 27, '[לַאֲשֶׁ֧ר] em-Betel El [בְּרָמֽוֹת־נֶ֖גֶב] [וְלַאֲשֶׁ֥ר] Nēgēb [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (8009, 9, 30, 28, '[וְלַאֲשֶׁ֧ר] [בַּעֲרֹעֵ֛ר] [וְלַאֲשֶׁ֥ר] [בְּשִֽׂפְמ֖וֹת] [וְלַאֲשֶׁ֥ר] [בְּאֶשְׁתְּמֹֽעַ׃]');
INSERT INTO verses VALUES (8010, 9, 30, 29, '[וְלַאֲשֶׁ֣ר] [בְּרָכָ֗ל] [וְלַֽאֲשֶׁר֙] em-cidades-de [הַיְּרַחְמְאֵלִ֔י] [וְלַאֲשֶׁ֖ר] em-cidades-de o-Qeni');
INSERT INTO verses VALUES (8011, 9, 30, 30, '[וְלַאֲשֶׁ֧ר] [בְּחָרְמָ֛ה] [וְלַאֲשֶׁ֥ר] [בְּבוֹר־עָשָׁ֖ן] [וְלַאֲשֶׁ֥ר] [בַּעֲתָֽךְ]');
INSERT INTO verses VALUES (8012, 9, 30, 31, '[וְלַאֲשֶׁ֖ר] em-Hebron e-para-todo [אֲשֶֽׁר־הִתְהַלֶּךְ־שָׁ֥ם] que ele nome Davi ele e-os-seus-homens');
INSERT INTO chapters VALUES (267, 9, 31, 13);
INSERT INTO verses VALUES (8013, 9, 31, 1, 'e-filisteus נִלְחֲמוּ em-Israel [וַיָּנֻ֜סוּ] homens-de Israel de-diante-de filisteus וייפלוּ traspassados em-monte-de [הַגִּלְבֹּֽעַ]');
INSERT INTO verses VALUES (8014, 9, 31, 2, '[וַיַּדְבְּק֣וּ] filisteus a Saul e-a seus filhos e-eles-feriram פְלִשְׁתִּ֗ים a [בְּנֵ֥י] e-a [sem-traducao] e-a [sem-traducao] Sua filhos-de שָׁאוּל');
INSERT INTO verses VALUES (8015, 9, 31, 3, '[וַתִּכְבַּ֤ד] a-guerra a Saul [הַמּוֹרִ֖ים] [אֲנָשִׁ֣ים] homens [וַיָּ֥חֶל] muito muito [sem-traducao]');
INSERT INTO verses VALUES (8016, 9, 31, 4, 'E-disse [שָׁאוּל֩] [לְנֹשֵׂ֨א] [כֵלָ֜יו] [שְׁלֹ֥ף] [חַרְבְּךָ֣] [׀] ב-הּ para-que-não [פֶּן־יָ֠בוֹאוּ] [הָעֲרֵלִ֨ים] [הָאֵ֤לֶּה] [וּדְקָרֻ֙נִי֙] [וְהִתְעַלְּלוּ־בִ֔י] em-mim e-não [נֹשֵׂ֣א] levando-o que temer muito E-tomou E-tomou Saul a a-espada e-cairam sobre-ela');
INSERT INTO verses VALUES (8017, 9, 31, 5, 'E-viu [נֹשֵֽׂא־כֵלָ֖יו] que porque morreu שָׁאוּל e-caiu também ele sobre sua-espada E-morreu com-ele');
INSERT INTO verses VALUES (8018, 9, 31, 6, 'E-morreu [שָׁא֡וּל] e-três-de [בָּנָיו֩] [וְנֹשֵׂ֨א] [כֵלָ֜יו] também todo no-dia no-dia aquele juntos-verso');
INSERT INTO verses VALUES (8019, 9, 31, 7, 'וַיִּרְא֣וּ os-homens-de- Israel que em-lado-de [׀] [בְּעֵ֣בֶר] em-além-de o-Jordão porque [יִשְׂרָאֵ֔ל] homens-de Israel e-se [וַיַּעַזְב֤וּ] Saul e-seus-filhos [וַיָּבֹ֣אוּ] a [וַיֵּֽשְׁב֖וּ] [בָּהֶֽן׃] e-vieram filisteus [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (8020, 9, 31, 8, 'e-houve [מִֽמָּחֳרָ֔ת] [וַיָּבֹ֣אוּ] filisteus [לְפַשֵּׁ֖ט] a [וֽ͏ַיִּמְצְא֤וּ] [אֶת־שָׁאוּל֙] a Saul e-[OBJ] [בְּהַ֥ר] [הַגִּלְבֹּֽעַ]');
INSERT INTO verses VALUES (8021, 9, 31, 9, '[וַֽיִּכְרְתוּ֙] a [וַיַּפְשִׁ֖יטוּ] [אֶת־כֵּלָ֑יו] a [בְאֶֽרֶץ־פְּלִשְׁתִּ֜ים] [סָבִ֗יב] em-terra-de [בֵּ֥ית] [עֲצַבֵּיהֶ֖ם] [וְאֶת־הָעָֽם] casa [sem-traducao] e-[OBJ] o-povo');
INSERT INTO verses VALUES (8022, 9, 31, 10, '[וַיָּשִׂ֙מוּ֙] a [בֵּ֖ית] casa [וְאֶת־גְּוִיָּתוֹ֙] e-[OBJ] [בְּחוֹמַ֖ת] [בֵּ֥ית] [שָֽׁן] casa');
INSERT INTO verses VALUES (8023, 9, 31, 11, '[וַיִּשְׁמְע֣וּ] a-ele [יֹשְׁבֵ֖י] [יָבֵ֣ישׁ] [גִּלְעָ֑ד] a que [פְלִשְׁתִּ֖ים] [לְשָׁאֽוּל]');
INSERT INTO verses VALUES (8024, 9, 31, 12, '[וַיָּק֜וּמוּ] todo homem [וַיֵּלְכ֣וּ] [כָל־הַלַּיְלָה֒] todo [אֶת־גְּוִיַּ֣ת] [שָׁא֗וּל] e-[OBJ] [גְּוִיֹּ֣ת] Saul e-[OBJ] [בֵּ֣ית] [שָׁ֑ן] [וַיָּבֹ֣אוּ] casa [וַיִּשְׂרְפ֥וּ] eles [שָֽׁם] nome');
INSERT INTO verses VALUES (8025, 9, 31, 13, '[וַיִּקְחוּ֙] a [וַיִּקְבְּר֥וּ] [תַֽחַת־הָאֶ֖שֶׁל] debaixo-de [וַיָּצֻ֖מוּ] [שִׁבְעַ֥ת] [יָמִֽים׃] sete dias');
INSERT INTO books VALUES (10, '2SA', '2 Samuel', 'AT', 24);
INSERT INTO chapters VALUES (268, 10, 1, 27);
INSERT INTO verses VALUES (8026, 10, 1, 1, 'e-houve depois-de morrendo Shaul e-David retornou de-o-golpear a o-amaleque e-habitou Davi em-Ziclague dias dois');
INSERT INTO verses VALUES (8027, 10, 1, 2, 'e-houve em-o-dia no-dia e-eis homem veio de o-acampamento de-com Shaul e-vestes-suas rasgadas e-terra sobre e-houve E-foi em-vir-seu a Davi e-caiu terra-para e-prostrou-se');
INSERT INTO verses VALUES (8028, 10, 1, 3, 'E-disse a-ele Davi onde de-este vens E-disse a-ele de-acampamento-de Israel escapei');
INSERT INTO verses VALUES (8029, 10, 1, 4, 'E-disse a-ele Davi que foi a palavra conta E-disse para-mim E-disse que fugiu cair de a-guerra e-também muito caiu de o-povo e-morreram e-também Shaul e-Yehonatan filho-seu morreram');
INSERT INTO verses VALUES (8030, 10, 1, 5, 'E-disse Davi a o-menino a-ele para-ele como soubeste porque morreu emprestado e-Yehonatan filho-seu');
INSERT INTO verses VALUES (8031, 10, 1, 6, 'E-disse o-jovem o-que-conta para-ele a-ele encontrei-me em-monte-de o-Gilboa e-eis emprestado apoiado sobre lança-sua e-eis os-carros e-senhores-de os-cavaleiros alcançaram-no');
INSERT INTO verses VALUES (8032, 10, 1, 7, 'e-virou-se atrás-dele e-viu-me E-chamou para-mim e-disse eis-me');
INSERT INTO verses VALUES (8033, 10, 1, 8, 'E-disse para-mim quem tu para-ele a-ele eu');
INSERT INTO verses VALUES (8034, 10, 1, 9, 'E-disse a-mim fica-em-pé por-favor sobre-mim que porque agarrou-me o-espasmo porque todo ainda alma-minha em-mim');
INSERT INTO verses VALUES (8035, 10, 1, 10, 'e-fiquei-em-pé sobre-ele e-matei-o que soube que não viverá depois-de queda-sua e-tomei a-coroa que sobre cabeça-sua e-a-pulseira que sobre braço-seu e-trouxe-os a Adonai até-aqui');
INSERT INTO verses VALUES (8036, 10, 1, 11, 'e-segurou Davi e-rasgou-as e-também todo os-homens que com-ele');
INSERT INTO verses VALUES (8037, 10, 1, 12, 'e-prantearam e-choraram e-jejuaram até a-tarde sobre Shaul e-sobre yhwh filho-seu e-sobre que yhwh e-sobre casa Israel porque caíram pela-espada');
INSERT INTO verses VALUES (8038, 10, 1, 13, 'E-disse Davi a o-menino a-ele a-ele onde de-este E-disse E-disse filho-de homem eu amalequita eu');
INSERT INTO verses VALUES (8039, 10, 1, 14, 'E-disse a-ele Davi como não temeste para-estender mão-tua para-destruir a yhwh yhwh');
INSERT INTO verses VALUES (8040, 10, 1, 15, 'E-chamou Davi para-um de-os-jovens E-disse aproxima-te ataca nele e-golpeou-o E-morreu');
INSERT INTO verses VALUES (8041, 10, 1, 16, 'E-disse a-ele Davi sobre cabeça-tua porque que respondeu em-ti para-dizer dizendo eu a ungido-de yhwh');
INSERT INTO verses VALUES (8042, 10, 1, 17, 'e-lamentou Davi a a-lamentação esta sobre emprestado e-sobre Yehonatan filho-seu');
INSERT INTO verses VALUES (8043, 10, 1, 18, 'E-disse para-ensinar filhos-de יְהוּדָה eis eis escrita sobre livro-de o-Yashar');
INSERT INTO verses VALUES (8044, 10, 1, 19, 'a-beleza Israel sobre em-lugares-altos-teus traspassado como caíram guerreiros');
INSERT INTO verses VALUES (8045, 10, 1, 20, 'a conteis em-Gat a anuncieis em-ruas-de Asquelom para-que-não se-alegrem filhas-de filisteus para-que-não exultem filhas-de os-incircuncisos');
INSERT INTO verses VALUES (8046, 10, 1, 21, 'montes-de em-o-Gilboa a orvalho e-a chuva sobre-vós que ofertas porque nome foi-contaminado escudo-de guerreiros escudo-de Shaul sem ungido com-o óleo');
INSERT INTO verses VALUES (8047, 10, 1, 22, 'de-sangue-de traspassados de-gordura-de guerreiros arco-de Jônatas não retrocedia para-trás e-espada-de Shaul não voltava vazios');
INSERT INTO verses VALUES (8048, 10, 1, 23, 'Saul e-Jônatas os-amados e-os-queridos em-vida-deles e-em-morte-deles não foram-separados de-águias eram-velozes de-leões eram-fortes');
INSERT INTO verses VALUES (8049, 10, 1, 24, 'filhas-de Israel a emprestado chorai o-que-vos-vestia segundo com delicadezas ouro sobre ouro sobre sobre-veste-vossa');
INSERT INTO verses VALUES (8050, 10, 1, 25, 'como caíram guerreiros no-meio-de a-guerra Jônatas sobre em-lugares-altos-teus traspassado');
INSERT INTO verses VALUES (8051, 10, 1, 26, 'angústia a-mim sobre-ti irmão-meu Jônatas a-mim muito muito foi-maravilhoso amor-teu para-mim de-amor-de mulheres');
INSERT INTO verses VALUES (8052, 10, 1, 27, 'como caíram guerreiros e-pereceram instrumentos-de guerra');
INSERT INTO chapters VALUES (269, 10, 2, 32);
INSERT INTO verses VALUES (8053, 10, 2, 1, 'e-houve depois-de assim e-perguntou Davi em-יהוה dizendo subirei em-uma-de cidades-de Judá E-disse yhwh a-ele folhas-de E-disse Davi para-onde subirei E-disse Hebrom-a');
INSERT INTO verses VALUES (8054, 10, 2, 2, 'e-subiu nome Davi e-também duas mulheres-suas Ainoã a-jezreelita e-Abigail mulher-de Nabal o-carmelita');
INSERT INTO verses VALUES (8055, 10, 2, 3, 'e-homens-seus que com-ele fez-subir Davi homem e-casa-sua e-habitaram em-cidades-de Hebrom');
INSERT INTO verses VALUES (8056, 10, 2, 4, 'e-vieram homens-de Judá e-ungiram nome a Davi para-rei sobre casa dizendo e-contaram para-Davi para-dizer homens-de Jabes Gileade que sepultaram a שָׁאוּל');
INSERT INTO verses VALUES (8057, 10, 2, 5, 'e-estendeu Davi mensageiros a homens-de יָבֵישׁ E-disse E-disse a-eles vós para-יהוה que fizestes a-bondade o-este com adonai-de-vós com ele e-sepultastes a-ele');
INSERT INTO verses VALUES (8058, 10, 2, 6, 'e-agora faça yhwh com-vós bondade e-verdade eu eu farei com-vós a-boa a-esta que fizestes a-palavra a-esta');
INSERT INTO verses VALUES (8059, 10, 2, 7, 'e-agora sejam-fortes mãos-de-vós e-sede para-filhos-de valente porque morreu adonai-de-vós שָׁאוּל e-também a-mim ungiram casa-de יְהוּדָה para-rei sobre-eles');
INSERT INTO verses VALUES (8060, 10, 2, 8, 'e-אַבְנֵר filho-de נֵר príncipe-de exército tomou de-שָׁאוּל tomou a homem בֹּשֶׁת filho-de Shaul e-fez-passar-ele מַחֲנַיִם');
INSERT INTO verses VALUES (8061, 10, 2, 9, 'e-fez-reinar-ele a Gileade e-a a-אֲשׁוּרִי e-a יִזְרְעֶאל e-sobre אֶפְרַיִם e-sobre בִּנְיָמִן e-sobre Israel tudo-ele');
INSERT INTO verses VALUES (8062, 10, 2, 10, 'filho-de quarenta ano אִישׁ- בֹּשֶׁת filho-de Saul em-reinar-ele sobre Israel e-dois dois rei somente casa Judá foram atrás-de Davi');
INSERT INTO verses VALUES (8063, 10, 2, 11, 'e-houve número os-dias que ser Davi rei em-חֶבְרוֹן sobre casa Judá sete dois e-seis meses');
INSERT INTO verses VALUES (8064, 10, 2, 12, 'e-saiu אַבְנֵר filho-de נֵר e-servos-de אִישׁ- בֹּשֶׁת filho-de שָׁאוּל de-מַחֲנַיִם גִּבְעוֹן-para');
INSERT INTO verses VALUES (8065, 10, 2, 13, 'e-יוֹאָב filho-de צְרוּיָה e-servos-de Davi saíram e-encontraram-eles sobre tanque-de גִּבְעוֹן Estas e-assentaram estes sobre o-tanque deste-lado e-aqueles sobre o-tanque deste-lado');
INSERT INTO verses VALUES (8066, 10, 2, 14, 'E-disse אַבְנֵר a יוֹאָב levantem-se por-favor os-jovens e-brinquem E-disse E-disse יוֹאָב levantem-se');
INSERT INTO verses VALUES (8067, 10, 2, 15, 'e-levantaram-se e-passaram em-número dois dez para-בִּנְיָמִן e-para-אִישׁ בֹּשֶׁת filho-de Saul e-doze dez de-servos-de Davi');
INSERT INTO verses VALUES (8068, 10, 2, 16, 'e-agarraram homem na-cabeça companheiro-seu e-espada-sua no-lado companheiro-seu e-caíram juntos E-chamou E-chamou a-aquela campo-de as-pedras que em-Gibeon');
INSERT INTO verses VALUES (8069, 10, 2, 17, 'e-foi a-guerra dura até no-dia em-o-dia o-aquele e-foi-ferido Abner e-homens-de Israel diante-de servos-de Davi');
INSERT INTO verses VALUES (8070, 10, 2, 18, 'e-foram nome três filhos-de Zeruiah Joab e-Abishai e-Asahel e-Asahel ligeiro como-um-de como-um-de as-gazelas que no-campo');
INSERT INTO verses VALUES (8071, 10, 2, 19, 'e-perseguiu Asahel depois-de Abner e-não desviou para-andar sobre a-direita e-sobre a-esquerda de-após Abner');
INSERT INTO verses VALUES (8072, 10, 2, 20, 'e-voltou-se Abner atrás-dele E-disse és-tu este E-disse E-disse');
INSERT INTO verses VALUES (8073, 10, 2, 21, 'E-disse a-ele Abner desvia a-ti sobre tua-direita ou sobre a-ti um para-ti um de-os-jovens e-toma para-ti a armadura-dele e-não quis Asahel para-desviar de-atrás-dele');
INSERT INTO verses VALUES (8074, 10, 2, 22, 'e-acrescentou ainda Abner dizendo a Asahel a-ti para-ti de-atrás-de-mim por-que te-ferirei terra-para e-como levantarei face-de a Joab irmão-teu');
INSERT INTO verses VALUES (8075, 10, 2, 23, 'e-recusou para-desviar e-feriu-o Abner com-extremidade-de a-lança a o-abdômen e-saiu a-lança de-atrás-dele e-caiu nome E-morreu e-houve todo o-que-vinha a o-lugar que caiu nome E-morreu e-pararam');
INSERT INTO verses VALUES (8076, 10, 2, 24, 'e-perseguiram Joab e-Abishai depois-de Abner e-o-sol veio e-eles vieram até colina-de Ammah que o-caminho-de face-de Giah caminho deserto-de Gibeon');
INSERT INTO verses VALUES (8077, 10, 2, 25, 'e-se-reuniram filhos-de Benjamim depois-de Abner e-foram para-grupo um sobre sobre cume-de colina uma');
INSERT INTO verses VALUES (8078, 10, 2, 26, 'E-chamou Abner a E-disse E-disse comerás espada espada não conheceste porque amarga será no-final e-até quando não dirás para-o-povo para-retornar de-após irmãos-deles');
INSERT INTO verses VALUES (8079, 10, 2, 27, 'E-disse Joab vida הָֽאֱלֹהִ֔ים que se-não falaste que então de-a manhã subimos o-povo homem de-depois-de irmão-dele');
INSERT INTO verses VALUES (8080, 10, 2, 28, 'e-tocou Joabe em-o chifre e-pararam todo o-povo e-não perseguiram mais depois-de Israel e-não acrescentaram mais para-lutar');
INSERT INTO verses VALUES (8081, 10, 2, 29, 'e-Abner e-homens-dele andaram em-a planície todo a noite o-aquele e-passaram a o-Jordão e-andaram todo o Bitron e-vieram Maanaim');
INSERT INTO verses VALUES (8082, 10, 2, 30, 'e-Joabe retornou de-depois-de Abner e-ajuntou a todo o-povo e-contaram de-servos-de Davi nove- dez homem e-dez- El');
INSERT INTO verses VALUES (8083, 10, 2, 31, 'e-servos-de Davi feriram de-Benjamin e-em-homens-de Abner três- centenas e-sessenta homem morreram');
INSERT INTO verses VALUES (8084, 10, 2, 32, 'e-levantaram a Asahel e-sepultaram-o seu-pai pai-dele que casa pão e-andaram todo a-noite Joabe a-eles e-amanheceu a-eles em-Hebron');
INSERT INTO chapters VALUES (270, 10, 3, 39);
INSERT INTO verses VALUES (8085, 10, 3, 1, 'e-foi a-guerra longa entre casa Saul e-entre casa Davi e-David andou e-forte e-casa-de emprestado andando e-fracos');
INSERT INTO verses VALUES (8086, 10, 3, 2, 'para-David filhos em-Hebron E-foi primogênito-dele e-houve para-Ainoã a jezreelita');
INSERT INTO verses VALUES (8087, 10, 3, 3, 'e-segundo-dele Quileabe mulher-de Nabal o carmelita e-o-terceiro Absalão filho-de Maaca filha-de Talmai rei Gesur');
INSERT INTO verses VALUES (8088, 10, 3, 4, 'e-o quarto Adonias filho-de Hagite e-o quinto Sefatias filho-de Abital');
INSERT INTO verses VALUES (8089, 10, 3, 5, 'Itreão para-Egla mulher-de Davi estes Estas para-David em-Hebron');
INSERT INTO verses VALUES (8090, 10, 3, 6, 'e-houve em-ser a-guerra entre casa Shaul e-entre casa Davi e-Abner ser fortalecendo-se em-casa-de שָׁאוּל');
INSERT INTO verses VALUES (8091, 10, 3, 7, 'e-para-Saul concubina e-nome-dela Rispa filha-de E-disse E-disse a Abner por-que entrastes a concubina-de pai-meu');
INSERT INTO verses VALUES (8092, 10, 3, 8, 'e-acendeu para-Abner muito sobre palavras-de E-disse Is-Bosete E-disse eu cão eu o-dia para-Judá o dia farei bondade com casa-de Saul pai-de-ti a irmãos-de-ele e-a de-amigo-de-ele e-não te-achou o-dia Davi e-visitastes sobre-mim iniquidade-de a-mulher o-dia');
INSERT INTO verses VALUES (8093, 10, 3, 9, 'assim fara Elohim para-Abner e-assim a-ele que porque como-que yhwh yhwh para-David porque assim farei- para-ele');
INSERT INTO verses VALUES (8094, 10, 3, 10, 'para-transferir o-reino de-casa-de שָׁאוּל e-para-levantar a trono-de Davi sobre Israel e-sobre Judá desde-Dã e-até em-Beer sete');
INSERT INTO verses VALUES (8095, 10, 3, 11, 'e-não podia ainda para-responder a Abner ele de-temor-de-ele a-ele');
INSERT INTO verses VALUES (8096, 10, 3, 12, 'e-enviou Abner mensageiros a Davi para-dizer para-quem- dizendo para-dizer dizendo aliança-de-ti comigo e-eis mão-de-mim contigo para-girar a-ti a todo Israel');
INSERT INTO verses VALUES (8097, 10, 3, 13, 'E-disse bom eu cortarei contigo aliança porém palavra um eu pedindo de-ti dizendo não verás que face-de que se diante-de trouxeres-ti את Mical para-ver Shaul em-vir-de-ti para-ver a face-de');
INSERT INTO verses VALUES (8098, 10, 3, 14, 'e-estendeu Davi mensageiros a homem-de dizendo filho-de emprestado para-dizer dá a mulher-de-mim a Mical que desposei para-mim em-cem prepúcios-de filisteus');
INSERT INTO verses VALUES (8099, 10, 3, 15, 'e-enviou homem Bosete e-tomou-a de-com homem de-com Paltiel filho-de');
INSERT INTO verses VALUES (8100, 10, 3, 16, 'E-andou com-ela marido-dela indo e-chorando atrás-de-ela até E-disse a-ele para-ele Abner vai volta e-voltou');
INSERT INTO verses VALUES (8101, 10, 3, 17, 'e-palavra-de ser foi com dizendo Israel para-dizer também ontem também anteontem éreis buscando a Davi para-rei sobre-vós');
INSERT INTO verses VALUES (8102, 10, 3, 18, 'e-agora fazei que yhwh disse a dizendo para-dizer em-mão-de Davi servo-de-mim salvar a povo-de-mim Israel de-mão-de filisteus e-de-mão-de todo inimigos-de-eles');
INSERT INTO verses VALUES (8103, 10, 3, 19, 'e-falou também Abner em-orelhas-de Benjamin E-andou também Abner para-falar em-orelhas-de Davi em-Hebrom a todo que bom em-olhos-de Israel e-em-olhos-de todo casa Benjamin');
INSERT INTO verses VALUES (8104, 10, 3, 20, 'E-veio Abner a Davi Hebrom e-com-ele vinte homens E-fez Davi para-Abner e-para-os-homens que com-ele banquete');
INSERT INTO verses VALUES (8105, 10, 3, 21, 'E-disse Abner a Davi levantarei e-irei e-eu-ajuntarei a Adonai o-rei a todo Israel e-eles-cortarão contigo aliança e-tu-reinarás em-todo que ela-deseja alma-tua e-ele-enviou Davi a Abner E-andou em-paz');
INSERT INTO verses VALUES (8106, 10, 3, 22, 'e-eis servos-de Davi e-Joabe veio de-a-tropa e-despojo muito com-eles eles-trouxeram e-Abner não-ele com Davi que porque ele-o-enviou E-andou em-paz');
INSERT INTO verses VALUES (8107, 10, 3, 23, 'e-Joabe e-todo o-exército que com-ele eles-vieram dizendo para-Joabe para-dizer veio Abner filho-de Ner a o-rei e-ele-o-enviou E-andou em-paz');
INSERT INTO verses VALUES (8108, 10, 3, 24, 'E-veio Joabe a E-disse E-disse que tu-fizeste eis-que- veio Abner para-ti por-que isto tu-o-enviaste E-andou indo');
INSERT INTO verses VALUES (8109, 10, 3, 25, 'tu-conheceste a Abner que Ner porque para-te-enganar veio e-para-conhecer a tua-saída e-a e-para-conhecer tu todo que tu fez');
INSERT INTO verses VALUES (8110, 10, 3, 26, 'e-saiu Joabe de-com Davi e-estendeu mensageiros depois-de Abner e-eles-retornaram ele de-poço-de a-Sira e-David não conheceu');
INSERT INTO verses VALUES (8111, 10, 3, 27, 'e-ele-retornou Abner Hebrom e-ele-o-desviou Joabe a meio-de o-portão de-falar com-ele em-o-sossego e-ele-o-feriu nome o-ventre E-morreu por-sangue-de ele-fez El irmão-seu');
INSERT INTO verses VALUES (8112, 10, 3, 28, 'E-ouviu Davi depois-de assim E-disse inocente eu e-reino-meu de-com yhwh até eternidade de-sangues-de Abner filho-de Ner');
INSERT INTO verses VALUES (8113, 10, 3, 29, 'eles-girarão sobre cabeça e-para e-a seu-pai casa pai-seu e-a ele-será-cortado de-casa-de Joabe fluindo e-leproso e-segurando em-o-fuso e-caindo pela-espada e-faltando pão');
INSERT INTO verses VALUES (8114, 10, 3, 30, 'e-Joabe e-Abisai irmão-seu eles-mataram para-Abner sobre que ele-matou a ele-fez El irmão-deles em-Gibeom na-guerra');
INSERT INTO verses VALUES (8115, 10, 3, 31, 'E-disse Davi a Joabe e-a todo o-povo que com-ele rasgai vestes-vossas e-cingi sacos e-lamentai diante-de Abner e-o-rei Davi andou atrás-de o-leito');
INSERT INTO verses VALUES (8116, 10, 3, 32, 'e-eles-sepultaram a Abner em-Hebron e-levantou o-rei a voz-dele e-chorou a sepultura-de Abner e-choraram todo o-povo');
INSERT INTO verses VALUES (8117, 10, 3, 33, 'e-lamentou o-rei a Abner E-disse como-morrer-de tolo morrerá Abner');
INSERT INTO verses VALUES (8118, 10, 3, 34, 'mãos-tuas não amarradas e-pés-teus não para-bronze foram-aproximados como-cair-de diante-de filhos-de iniquidade caíste e-acrescentaram todo o-povo para-chorar sobre-ele');
INSERT INTO verses VALUES (8119, 10, 3, 35, 'E-veio todo o povo para-fazer-comer pão Davi o-dia em-ainda o-dia dizendo Davi para-dizer assim fará- para-mim que e-assim acrescentará porque se diante-de vir-de o-sol provarei pão ou todo qualquer-coisa');
INSERT INTO verses VALUES (8120, 10, 3, 36, 'e-todo o-povo reconheceram e-foi-bom em-olhos-deles como-tudo que fez o-rei em-olhos-de bom o-povo bom');
INSERT INTO verses VALUES (8121, 10, 3, 37, 'e-souberam todo o-povo no-dia Israel que não era não foi de-o-rei para-matar a Abner filho-de Ner');
INSERT INTO verses VALUES (8122, 10, 3, 38, 'E-disse o-rei a servos-dele não sabeis porque cair o-dia caiu o-dia este em-Israel');
INSERT INTO verses VALUES (8123, 10, 3, 39, 'e-eu o-dia tenro e-untoido rei e-os-homens os-estes filhos-de formada duras de-mim pagará yhwh para-o-fazendo o-mal de-seu-joelho-verso');
INSERT INTO chapters VALUES (271, 10, 4, 12);
INSERT INTO verses VALUES (8124, 10, 4, 1, 'E-ouviu filho-de que porque morreu אַבְנֵר em-Hebrom e-eles-se-endireitaram mãos-dele e-todo Israel temeram-verso');
INSERT INTO verses VALUES (8125, 10, 4, 2, 'e-dois homens senhores-de- batalhões foram filho-de o-primeiro nome o-primeiro em-o-Aná e-o-nome o-segundo Rechav filhos-de Rimon de-filhos-de que porque também em-as-fontes é-considerada sobre Benjamin');
INSERT INTO verses VALUES (8126, 10, 4, 3, 'e-eles-fugiram os-das-fontes Gat-aima e-eles-foram nome até o-dia o-dia a-esta');
INSERT INTO verses VALUES (8127, 10, 4, 4, 'e-a-o-Yonatan filho-de filho filho machuca pés filho-de ser dois foi em-a-entrada de-a-notícia Saul e-o-Yonatan de-Mi-zreel e-ela-o-elevar e-houve e-ela-o-fugir E-foi com-pressa para-nadar e-caiu e-ele-passou-a-Páscoa e-nome-dele Mefiboshet');
INSERT INTO verses VALUES (8128, 10, 4, 5, 'e-foram filhos-de Rimon da-berço Rechav e-na-Aná e-vieram o-dia o-dia a casa homem com-vergonha e-ele deitando a deitamento as-meio-dia');
INSERT INTO verses VALUES (8129, 10, 4, 6, 'e-eis vieram até dentro-de a-casa tomadores trigo e-os-feriram a a-quinta-parte e-carros e-na-espiga irmão-seu escaparam');
INSERT INTO verses VALUES (8130, 10, 4, 7, 'e-vieram a-casa e-ele dormindo sobre em-a-sua-cama na-câmara de-seu-dormir e-os-golpearam-nole e-os-mataram-nole e-os-removeram a sua-cabeça o-caminho-de a cabeça-sua caminho a-aravah todo a-noite');
INSERT INTO verses VALUES (8131, 10, 4, 8, 'e-os-trouxeram a cabeça אִישׁ- em-baston a Davi Hevron e-disseram a o-rei eis-a cabeça אִישׁ- E-colocou yhwh Saul o-teu-inimigo que o-dia a alma-tua E-deu yhwh para-o-adonai o-rei as-tua-vindicta o-dia esta de-Shaul e-de-seu-sêmen');
INSERT INTO verses VALUES (8132, 10, 4, 9, 'e-ele-respondeu Davi a o-carro e-a em-Anah o-seu-irmão filhos-de o-Rimon E-disse a-eles para-eles vive yhwh que ele-resgatou a alma-minha de-todo angústia');
INSERT INTO verses VALUES (8133, 10, 4, 10, 'que que-anuncia para-mim dizendo eis-que- morreu שָׁאוּל e-ele foi como-anunciador nele e-eu-peguei nele e-eu-matei-o em-Tziklag que para-dar- para-ele em-boas-novas');
INSERT INTO verses VALUES (8134, 10, 4, 11, 'certamente porque homens maus e-mataram a homem-de e-agora em-casa-dele sobre de-seu-dormir e-agora porventura-não eu-peço a seu-sangue de-vos e-eu-lavarei vós de a-terra');
INSERT INTO verses VALUES (8135, 10, 4, 12, 'E-ordenou Davi a os-jovens e-deram-lhes-morte e tremeram a suas-mãos e-a suas-pernas e foram pendurados sobre o-tanque em-Hebron e-a cabeça אִישׁ- בֹּשֶׁת levaram-os e-eles-sepultaram em-o-tumba- Abner em-Hebron');
INSERT INTO chapters VALUES (272, 10, 5, 25);
INSERT INTO verses VALUES (8136, 10, 5, 1, 'e-vieram todo de-a-famílias-de Israel a Davi dizendo e-disseram dizendo eis-nos a-tua-própria e-com-a-carne-de-teu nós-verso');
INSERT INTO verses VALUES (8137, 10, 5, 2, 'também ontem também antes-dois-dias na-vez-de Saul tu sobre-nós tu a Israel E-disse yhwh para-ti E-disse yhwh a-ti tu a Israel e-tu será para-o-nagid sobre Israel');
INSERT INTO verses VALUES (8138, 10, 5, 3, 'e-vieram todo anciãos-de Israel a o rei a-eles e-ele-cortou a-elas o-rei Davi em-o-brith yhwh diante-de yhwh e-eles-ungeram a Davi para-rei sobre Israel');
INSERT INTO verses VALUES (8139, 10, 5, 4, 'filho-de trinta ano Davi em-seu-reinado quarenta ano rei');
INSERT INTO verses VALUES (8140, 10, 5, 5, 'em-hebron rei sobre Judá sete dois e-seis meses e-em-jerusalém rei trinta e-três sobre sobre todo Israel e-Judá');
INSERT INTO verses VALUES (8141, 10, 5, 6, 'E-andou o-rei e-os-seus-homens Jerusalém a o-jebuseu a-terra E-disse E-disse dizendo para-dizer não que elas porque se dizendo os-averrinos e-os-pisheus dizendo não ele-vir-a Davi até-aqui');
INSERT INTO verses VALUES (8142, 10, 5, 7, 'e-ele-pegou Davi a de-a-cidadela Sião ela cidade Davi');
INSERT INTO verses VALUES (8143, 10, 5, 8, 'E-disse Davi no-dia aquele todo punição jebuseu e-ele-tocou בַּצִּנּ֔וֹר e-a os-passageiros e-a os-olimpados alma Davi sobre assim dirão não -piscado não virá a a-casa');
INSERT INTO verses VALUES (8144, 10, 5, 9, 'e-habitou Davi em-a-mezuda e ele chamou para-ela cidade E-edificou va-yiben Davi ao-redor de o-millu e-na-casa');
INSERT INTO verses VALUES (8145, 10, 5, 10, 'E-andou Davi indo e-grande וַיהוָ֛ה Elohim-de de-exércitos com-ele');
INSERT INTO verses VALUES (8146, 10, 5, 11, 'e-yi-shelakh chi-ram rei-de tsor mensageiros a Davi ve-a-tse árvore ve-ha-rase pedra ve-ha-rase pedra-a qi-yir va-yi-bnu- casa le-david');
INSERT INTO verses VALUES (8147, 10, 5, 12, 'e-soube Davi porque yhwh yhwh para-rei sobre Israel e-que foi-elevar-se seu-reino por-causa-de seu-povo Israel');
INSERT INTO verses VALUES (8148, 10, 5, 13, 'E-tomou Davi ainda as-pilagshim e-mulheres de-Jerusalém depois-de seu-vindo de-hebron e-eles-nasceram ainda para-David filhos e-filhas');
INSERT INTO verses VALUES (8149, 10, 5, 14, 'e-estes nomes os-nascidos a-ele em-Jerusalém Shamuwa'' e-Soevav e-Natã e-Salomoh');
INSERT INTO verses VALUES (8150, 10, 5, 15, 'e-Ibhar e-Elishua'' e-Nepeg e-Jafia');
INSERT INTO verses VALUES (8151, 10, 5, 16, 'e-Elishama'' e-Elyada'' e-Elifelet');
INSERT INTO verses VALUES (8152, 10, 5, 17, 'e-ouviram פְלִשְׁתִּ֗ים porque meschuhu a Davi para-o-rei sobre Israel e-eles-subiram todo Filisteus para-pedir a Davi E-ouviu Davi e-ele-descerrou a a-muradura');
INSERT INTO verses VALUES (8153, 10, 5, 18, 'e-filisteus eles-vieram e-eles-deram na-vale refains');
INSERT INTO verses VALUES (8154, 10, 5, 19, 'e-ele-perguntou Davi em-yhwh dizendo a-eu-subirei a filisteus se-você-dá-los E-disse yhwh yhwh folhas-de Davi sobe porque deu eu-darei a os-felistinos em-mão-teu');
INSERT INTO verses VALUES (8155, 10, 5, 20, 'E-veio Davi em-Baal- e-Prazim e-os-golpeou nome E-disse E-disse yhwh yhwh a meus-inimigos diante-de-mim כְּפֶ֣רֶץ chamou sobre sim chamou nome-de o-lugar o-aquele Baal Prazim.');
INSERT INTO verses VALUES (8156, 10, 5, 21, 'e-os-abandonaram- nome a seus-idolos e-os-elevaram Davi e-os-seus-homens');
INSERT INTO verses VALUES (8157, 10, 5, 22, 'e-acrescentaram ainda Filisteus para-subir e-eles-o-deram na-vale refains');
INSERT INTO verses VALUES (8158, 10, 5, 23, 'e-ele-perguntou Davi em-יהוה E-disse não suba o-vire-se a depois-deles a-eles a-eles de-em-frente-de com-choro');
INSERT INTO verses VALUES (8159, 10, 5, 24, 'e-seja a voz passo no-princípio os-chorões então você-apressará porque que saiu sair yhwh para-golpear no-acampamento Filisteus');
INSERT INTO verses VALUES (8160, 10, 5, 25, 'E-fez Davi assim como-que ordenou-o yhwh e-golpeou a filisteus de-abaixo até em-você decidiu');
INSERT INTO chapters VALUES (273, 10, 6, 23);
INSERT INTO verses VALUES (8161, 10, 6, 1, 'e-continuou ainda Davi a todo jovem em-Israel trinta mil');
INSERT INTO verses VALUES (8162, 10, 6, 2, 'e-elevantou-se- E-andou Davi e-todo o-povo que com-ele de-aqueles-que-são-dono-de Judá para-levar-acima de-lá a arca os-Elohim que encontrou-se nome yhwh yhwh exércitos os-querubins os-querubins sobre-ele');
INSERT INTO verses VALUES (8163, 10, 6, 3, 'e-eles-montaram a arca הָֽאֱלֹהִים a carroça nova e-ele-o-levantou de-casa-de Avinadav que em-Gibeá e-Uza e-Achiyo filhos-de Avinadab nohagim a ha-agalah');
INSERT INTO verses VALUES (8164, 10, 6, 4, 'desde-casa-de Avinadab que bagibbah povo arca o-Elohim e-Achiyo andou diante-de a-arca');
INSERT INTO verses VALUES (8165, 10, 6, 5, 've-David e-todo casa Israel meschakim diante-de yhwh em-todo madeiras-de beroshim e em seus liras e em suas flautas e-em-tumim e em seus instrumentos de tocação e em seus tamborins');
INSERT INTO verses VALUES (8166, 10, 6, 6, 'e-vieram até aranha-de נָכ֑וֹן e-enviou o-azom a arca הָֽאֱלֹהִים que nele porque deram-se os-bois');
INSERT INTO verses VALUES (8167, 10, 6, 7, 'yhwh yhwh e-ferrou-o nome o-Elohim sobre o-sal E-morreu nome povo arca o-Elohim');
INSERT INTO verses VALUES (8168, 10, 6, 8, 'e-acendeu-se para-David sobre que rompeu yhwh פֶּרֶץ em-Ouzá E-chamou para-o-lugar o-aquele Perez Ouzá até o-dia a-esta');
INSERT INTO verses VALUES (8169, 10, 6, 9, 'E-viu Davi a no-dia no-dia E-disse E-disse como virá a-mim yhwh yhwh');
INSERT INTO verses VALUES (8170, 10, 6, 10, 'e-não quis Davi a-ele para-ele yhwh arca yhwh sobre cidade Davi e-esticou-o Davi casa servo-de Edom o-giti');
INSERT INTO verses VALUES (8171, 10, 6, 11, 'e-ele-estabeleceu-se arca-de yhwh casa servo homem o-giti três meses E-abençoou yhwh a servo homem e-a todo casa-dele');
INSERT INTO verses VALUES (8172, 10, 6, 12, 'e-lhe-foi-dito para-o-rei Davi dizendo abençoou yhwh a casa servo homem e-a todo que a-ele por-causa-de arca o-Elohim E-andou Davi e-subiu a arca-de os-אלהים de-a-casa servo homem cidade Davi em-simcha');
INSERT INTO verses VALUES (8173, 10, 6, 13, 'e-houve que eles-andaram carregadores-de arca-de yhwh seis passos e-ele-imolou bovino e-meria');
INSERT INTO verses VALUES (8174, 10, 6, 14, 'e-David mercador em-todo força yhwh yhwh e-David cingido éfode linho');
INSERT INTO verses VALUES (8175, 10, 6, 15, 'e-David e-todo casa Israel subindo yhwh arca yhwh em-troeira e-em-a-voz chifre');
INSERT INTO verses VALUES (8176, 10, 6, 16, 'e-foi arca yhwh veio cidade Davi e-Mical filha-de Saul nischqapha- através-de ha-chalon E-viu a o-rei Davi que-espanta um-karcher yhwh yhwh a-ele a-ele belibah-');
INSERT INTO verses VALUES (8177, 10, 6, 17, 'vayyaviu a yhwh yhwh ele ele no-meio-de em-meio-de a-tenda que natah- a-ele Davi e-subiu Davi yhwh diante-de yhwh ushlaimim-');
INSERT INTO verses VALUES (8178, 10, 6, 18, 'E-terminou Davi me-haalot a-holocausto e-o-sacrifício-de-paz E-abençoou a o-povo yhwh yhwh exércitos');
INSERT INTO verses VALUES (8179, 10, 6, 19, 'e-ele-distribuiu para-todo o-povo para-todo multidão Israel para-cada-homem e-até pão uma massa-de-pão um uma e-farinha-de-trigo um e-azedas um E-andou todo o-povo homem para-sua-casa');
INSERT INTO verses VALUES (8180, 10, 6, 20, 'e-voltou Davi para-abençoar a casa-dele e-saiu Михаль filha-de Saul E-disse Davi o-dia que nichbad o-hoje rei o-dia que niglah o-dia para-os-olhos-de amehot seus-servos como-foram-reveladas niglot um os-vazios');
INSERT INTO verses VALUES (8181, 10, 6, 21, 'E-disse Davi a Mical- yhwh yhwh que escolheu- em-mim de-teu-pai e-de-todo casa-dele para-comando yhwh príncipe sobre povo yhwh sobre Israel e-joguei-me diante-de yhwh');
INSERT INTO verses VALUES (8182, 10, 6, 22, 'e-eu-alivio ainda de-isto e-eu-serei baixo em-o-s-olhos e-com- as-verdades que disse-te com-eles honra-a');
INSERT INTO verses VALUES (8183, 10, 6, 23, 'e-para-Mical filha-de Shaul não foi até dia até dia sua-morte');
INSERT INTO chapters VALUES (274, 10, 7, 29);
INSERT INTO verses VALUES (8184, 10, 7, 1, 'e-houve porque habitou o-rei em-a-casa-seu e-yhwh deixou- a-ele ao-redor de-todo oyevav');
INSERT INTO verses VALUES (8185, 10, 7, 2, 'E-disse o rei a deu o-profeta viu eu eu habitante em-casa-de árvores-de-cedro e-caix-a הָֽאֱלֹהִ֔ים no-meio-de em-meio-de a-tenda');
INSERT INTO verses VALUES (8186, 10, 7, 3, 'E-disse deu a o-rei todo que com-o-coracao-tu vai que yhwh yhwh contigo');
INSERT INTO verses VALUES (8187, 10, 7, 4, 'e-houve na-noite aquele e-houve palavra-de yhwh dizendo deu para-dizer');
INSERT INTO verses VALUES (8188, 10, 7, 5, 'vai e-dirás a servo-meu a disse yhwh disse yhwh tu-o construirás- para-mim casa para-residir-me');
INSERT INTO verses VALUES (8189, 10, 7, 6, 'que não sentei em-casa de-dia a-elevar-me a filhos-de Israel do-Egito o-dia o-dia este passeando em-andar na-tenda e-na-tenda');
INSERT INTO verses VALUES (8190, 10, 7, 7, 'em-todo que eu-andei em-todo filhos-de Israel para-falar falei-eu a um tribos-de Israel que ordenei-eu dizendo a povo-meu a Israel dizendo por-que não voces-construiram para-mim casa ciprestes');
INSERT INTO verses VALUES (8191, 10, 7, 8, 'e-agora assim dizes para-o-meu-servo para-David disse yhwh yhwh exércitos eu para-levar-te de o-abrigo de-trás-de do-rebanho para-ser príncipe sobre povo-meu sobre Israel');
INSERT INTO verses VALUES (8192, 10, 7, 9, 'e-eu-fui em-voce em-todo que e-você-andou e-eu-atelei-te a todo teus-inimigos a-ti e-fará para-ti nome os-grandes como-o-nome os-grandes que na-terra');
INSERT INTO verses VALUES (8193, 10, 7, 10, 'e-postarei lugar para-o-povo-meu para-Israel e-plantar-ei-ele e-habitará em-lugar-dele e-não ele-tremeará ainda e-não eles-acrescentarão filhos-de iniquidade para-oprimir-ele conforme em-primeiro');
INSERT INTO verses VALUES (8194, 10, 7, 11, 'e-de-o o-dia que comandei-eu juízes sobre meu-povo a-ti e-deixei-eu a-ti a-ti yhwh e-disse para-ti yhwh porque casa fará- a-você yhwh');
INSERT INTO verses VALUES (8195, 10, 7, 12, 'que encherão-eles os-se-u-dias e-deitaste a avós-teus e-elevar-ei a zera-ka de-te que sairá de-aos-teus-intestinos e-prepararei a seu-reino');
INSERT INTO verses VALUES (8196, 10, 7, 13, 'ele construirá casa para-o-nome-meu e-consagrarei a trono-de seu-reino até eternidade');
INSERT INTO verses VALUES (8197, 10, 7, 14, 'eu eu-ser-ei- para-ele para-pai e-ele ser- para-mim para-filho que em-o-suas-faltas e-eu-te-repreenderia com-vara homens homem filhos-de homem');
INSERT INTO verses VALUES (8198, 10, 7, 15, 'e-meu-pecado não nós de-ele como-que não-retiraria-eu de-com Shaul que não-retiraria-eu de-a-frente-de-você-versículo-final');
INSERT INTO verses VALUES (8199, 10, 7, 16, 'e-fiél em-a-tua-casa e-teu-reino até eternidade diante-de-ti será será certo até eternidade');
INSERT INTO verses VALUES (8200, 10, 7, 17, 'como-tudo as-palavras os-estes e-com-tudo o-visionar esta assim palavra deu a Davi');
INSERT INTO verses VALUES (8201, 10, 7, 18, 'E-veio o-rei Davi e-habitou diante-de yhwh E-disse quem eu Adonai yhwh e-quem de-meu-casa que para-trazer-me até וְהִנֵּה׃');
INSERT INTO verses VALUES (8202, 10, 7, 19, 'e-você-se-tornou-pequeno ainda esta em-olhos-teus Adonai yhwh e falou também a casa-de servo-teu de-longe o-homem torat o-homem Adonai yhwh');
INSERT INTO verses VALUES (8203, 10, 7, 20, 'e-que yosif Davi ainda para-falar a-ti e-tu yadathta a servo-teu Adonai yhwh');
INSERT INTO verses VALUES (8204, 10, 7, 21, 'baavur dibhrakhah ukhlivkha asita a todo hagdulah esta lehodiao a servo-teu');
INSERT INTO verses VALUES (8205, 10, 7, 22, 'sobre assim gadaltah Adonai yhwh porque não-há como-tu e-não-há Elohim além-de-tu em-todo que ouvimos em-a-ouvido-nos');
INSERT INTO verses VALUES (8206, 10, 7, 23, 'e-quem como-povo-de-tu como-Israel nação um em-a-terra que ide-para Elohim para-resgatar-para a-ele a-ele e-para-colocar a-ele a-vós e-para-fazer para-vocês a-grandeza de-diante-de para-a-tua-terra de-diante-de o-teu-povo que resgatou-te para-ti do-Egito nações e-seus-אֱלֹהִים');
INSERT INTO verses VALUES (8207, 10, 7, 24, 'e-fundouste a-ti a o-teu-povo Israel a-ti para-o-povo até eternidade yhwh yhwh a-eles a-eles para-elohim');
INSERT INTO verses VALUES (8208, 10, 7, 25, 'e-agora yhwh Elohim a-palavra que falaste sobre teu-servo e-sobre casa-dele erguer até eternidade e-fazes como-que dibartā׃');
INSERT INTO verses VALUES (8209, 10, 7, 26, 'e-grande-seja seu-nome até dizendo yhwh yhwh exercitos Elohim sobre Israel e-a-casa será Davi será certo diante-de-você.');
INSERT INTO verses VALUES (8210, 10, 7, 27, 'porque yhwh yhwh de-exércitos Elohim-de Israel expostaste a dizendo teu-servo dizendo casa encontrou para-ti sobre sim achou teu-servo a coração-dele para-se-afastar para-ti a a-oração a esta');
INSERT INTO verses VALUES (8211, 10, 7, 28, 'e-agora Adonai yhwh você- ele הָֽאֱלֹהִ֔ים e-palavras-teu serão verdade e-você-falou a teu-servo a hatovah a esta');
INSERT INTO verses VALUES (8212, 10, 7, 29, 'e-agora clama e-bençãos a casa teu-servo a-ser para-sempre diante-de-ti porque você Adonai yhwh falaste e-de-bençãos-teu seja-bendito casa-de servo-teu para-eternidade');
INSERT INTO chapters VALUES (275, 10, 8, 18);
INSERT INTO verses VALUES (8213, 10, 8, 1, 'e-houve e-feriu Davi a Filisteus e-os-subjugou E-tomou Davi a freio a-almofada de-mão-de filisteus');
INSERT INTO verses VALUES (8214, 10, 8, 2, 'e-feriu a Moabe e-os-mediu com-a-corda o-deitar e-os terra-para e-mediu dois cordas- para-matar e-cheio-de o-corda para-viver-fazer e-foi Moabe para-David aos-escravos carregadores-de oferta-:');
INSERT INTO verses VALUES (8215, 10, 8, 3, 'e-feriu Davi a Hadar-ezer filho-de Rechob rei Zobah sua-mão para-responder mão-sua em-o-rio');
INSERT INTO verses VALUES (8216, 10, 8, 4, 'e-ele-comeu Davi nós mil e-sete- novecentos pastores e-vinte mil homem de-pé e-ele-examinou Davi a nós o-carro e-ele-removeu dele cem cavalo');
INSERT INTO verses VALUES (8217, 10, 8, 5, 'e-ela-veio Arã de-Damasco em-azor para-haddadezer rei Zobah e-ele-feriu Davi em-aram vinte- u-shnayim mil homem');
INSERT INTO verses VALUES (8218, 10, 8, 6, 'e-ele-postou Davi que-ficaram em Aram de-Damasco e-foi Aram para-David aos-escravos levadores oferta e-resgatou yhwh a Davi em-todo que andou');
INSERT INTO verses VALUES (8219, 10, 8, 7, 'E-tomou Davi a sh''ltei o-ouro que foram a servos-de Hadarazeer va-yevia''em Jerusalém');
INSERT INTO verses VALUES (8220, 10, 8, 8, 'u-mibetach u-miberotai cidades-de Hadarazeer tomou o-rei Davi bronze muito muito');
INSERT INTO verses VALUES (8221, 10, 8, 9, 'E-ouviu perdido-s rei calor-fervente que bateu Davi a todo força hadadezer');
INSERT INTO verses VALUES (8222, 10, 8, 10, 'e-enviou errante a joram- -seu-filho a o-rei sobre para-perguntar- a-ele para-paz e-para-bendizê-lo sobre que luta ser e-ele-o-feriu porque homem guerras-de perdido-s foi Hadarazeer e-com-a-sua-mão foram os-ferramentas-de prata e-vesséis-de- ouro e-vessãis bronze');
INSERT INTO verses VALUES (8223, 10, 8, 11, 'também deles consagrou o-rei Davi para-יהוה com a-prata e-o-ouro que hiq''dish de-todo ha-goyim que sujeitai');
INSERT INTO verses VALUES (8224, 10, 8, 12, 'me-ar''am e-de-Moav e-de-filhos Amom e-de-Filisteus e-de-Amalec e-de-spoil Hadar-ezer filho-de Rechob rei továh');
INSERT INTO verses VALUES (8225, 10, 8, 13, 'E-fez Davi nome beshúvo me-hakotó a Arã begai- sal shmonáh dez mil');
INSERT INTO verses VALUES (8226, 10, 8, 14, 'e-ele-postou be-edóm netzívim em-todo Edom nome e-houve E-foi todo Edom avádim yhwh vayóshá yhwh a Davi em-todo que andou');
INSERT INTO verses VALUES (8227, 10, 8, 15, 'e-reinou Davi sobre e-houve Israel E-foi Davi fez mishpat u-tsedakah para-todo povo-dele');
INSERT INTO verses VALUES (8228, 10, 8, 16, 'e-Joabe filho-de tsruyah sobre o-exército viyohoshaphat filho-de achilud mazkir');
INSERT INTO verses VALUES (8229, 10, 8, 17, 'vetzadoq filho-de achitub va-akhimelekh filho-de evyatar sacerdotes e-sraviah escritor');
INSERT INTO verses VALUES (8230, 10, 8, 18, 'e-Benaia filho-de Joiada e-o-quereteu e-o-peleteu e-filhos-de Davi sacerdotes eram');
INSERT INTO chapters VALUES (276, 10, 9, 13);
INSERT INTO verses VALUES (8231, 10, 9, 1, 'E-disse Davi pois há ainda que restante para-casa-de שָׁאוּל e-farei com-ele bondade por-causa-de jehonathan');
INSERT INTO verses VALUES (8232, 10, 9, 2, 'e-a-casa-de שָׁא֥וּל servo e-nome-de-ele Цива e-ele-chamou- a-ele E-disse Davi a-ele o-rei para-ele E-disse Цива E-disse servo-teu');
INSERT INTO verses VALUES (8233, 10, 9, 3, 'E-disse o rei o-a-peça-de-madeira ainda homem para-casa-de Shaul e-eu-farei com-ele bondade Elohim E-disse Цива a o-rei filho filho para-Ионафан ferido pés-vos');
INSERT INTO verses VALUES (8234, 10, 9, 4, 'e-ele-disse a-ele o-rei ele E-disse E-disse Tsiva- a o-rei eis-que- ele casa Maquir filho-de Amiel- em-o-lo palavra');
INSERT INTO verses VALUES (8235, 10, 9, 5, 'e-enviou o-rei Davi e-ele-o-tomou de-a-casa Maquir filho-de Amiel- em-o-lo palavra');
INSERT INTO verses VALUES (8236, 10, 9, 6, 'E-veio Mefiboshet- filho-de Jônatan- filho-de Saul a Davi E-disse sobre sua-face E-disse eis Davi Mefiboshet E-disse eis servo-teu');
INSERT INTO verses VALUES (8237, 10, 9, 7, 'E-disse a-ele Davi a que porque fez eu-farei com-você hesed em-vez-de Yehonatan pai-teu a-ti para-ti a todo os-campos comerás pão e-tu você-comerá pão sobre mesa-meu sempre');
INSERT INTO verses VALUES (8238, 10, 9, 8, 'e-ele-se-curvou E-disse que servo-teu que voltaste a o-cão o morto que como-eu');
INSERT INTO verses VALUES (8239, 10, 9, 9, 'E-chamou o rei a Tsibá jovem E-disse a-ele a-ela todo ser foi para-Saulo dei casa-dele dei para-filho-de seus-mestres');
INSERT INTO verses VALUES (8240, 10, 9, 10, 'e-servirás para-ele a tu tu e-seus-filhos e-teus-escravos e-tu-o-trarás e-será para-filho-de teu-adonai pão e-o-comerás e-Mefiboshet filho-de pão comerá permanente pão sobre mesa-meu e-para-Tsiba cinco dez filhos e-vinte servos');
INSERT INTO verses VALUES (8241, 10, 9, 11, 'E-disse Tsiba a o-rei como-todo que ele-comanda Adonai o-rei a servo-seu assim fará servo-teu e-Mephibosheth como-um-de sobre mesa-minha como-um de-filhos-de o rei');
INSERT INTO verses VALUES (8242, 10, 9, 12, 'e-a-Mephibosheth filho-de pequeno e-nome-de-ele e-tudo e-todo morada casa-de Tsiba servos a-Mephibosheth');
INSERT INTO verses VALUES (8243, 10, 9, 13, 'e-Mephibosheth habitou em-Jerusalém que sobre shulchan o-rei ele ele comer e-ele pisque duas-de de-seus-pés');
INSERT INTO chapters VALUES (277, 10, 10, 19);
INSERT INTO verses VALUES (8244, 10, 10, 1, 'e-houve depois-de assim E-morreu rei filhos-de Amom e-reinou gracioso filho-seu em-lugar-dele');
INSERT INTO verses VALUES (8245, 10, 10, 2, 'E-disse Davi farei- misericórdia com gracioso filho-de serpente seu-pai comigo pai-de-ele comigo bondade e-enviou Davi para-consolá-lo por-mão-de servos-dele a terra e-vieram servos-de Davi terra filhos-de Amom');
INSERT INTO verses VALUES (8246, 10, 10, 3, 'e-disseram príncipes-de filhos-de Amom a gracioso de-seus-mestres o-que-exalta Davi a a-ti em-tua-olho porque enviou a-ti consoladores não-é por-causa-de exame a a-cidade e-para-seus-pés e-para-virá-la enviou Davi a servos-dele para-ti');
INSERT INTO verses VALUES (8247, 10, 10, 4, 'E-tomou gracioso a servos-de Davi e-ele-apeanhou a metade os-seus-cabelos e-ele-cortou até as-maças-deles em-meio até os-lábios-deles e-ele-mandou-os');
INSERT INTO verses VALUES (8248, 10, 10, 5, 'e-contaram para-Davi e-enviou para-eles porque foram os-homens muito E-disse E-disse o rei morai-vós em-a-lua-seu até ele-fará-germinar idosos-vos e-voltareis');
INSERT INTO verses VALUES (8249, 10, 10, 6, 'e-eles-viram filhos-de Amom que profetizaram em-David e-eles-enviaram filhos-de Ammon e-eles-compraram a Aram casa-de Reobe e-a Arã Zoba vinte mil pé-mi e-a bom obra-a mil homem e-homem bom doze dez mil homem');
INSERT INTO verses VALUES (8250, 10, 10, 7, 'E-ouviu Davi e-enviou a יוֹאָב e-a todo o-exército os-valentes');
INSERT INTO verses VALUES (8251, 10, 10, 8, 'e-saíram filhos-de Amom e-ele-arranjaram guerra entrada-de a-porta e-Aram Zoba e-largo e-homem- bom e-ma''acha le-baddam no-campo');
INSERT INTO verses VALUES (8252, 10, 10, 9, 'E-viu Joabe porque a-ele face-de face-de a-guerra mi-panim u-me-achor de-toda de-todo be-churei e-arranjou para-encontro-de aram');
INSERT INTO verses VALUES (8253, 10, 10, 10, 'e-את Jetro o-povo dar em-mão abshai irmão-dele va-yay''arokh para-encontro-de filhos-de Amon');
INSERT INTO verses VALUES (8254, 10, 10, 11, 'E-disse se te-chezaq aram mais-que-a-mim a-mim para-mim li-yeshuah e-se filhos-de עַמּוֹן֙ se-fortalecerão de-te para-ti para-salvar para-ti');
INSERT INTO verses VALUES (8255, 10, 10, 12, 'חזק e-nos-fortaleceremos בְּעַד־ povo-nostrum וּבְעַ֖ד cidades-de nosso-Elohim e-יהוה ele-fará o-bom em-seus-olhos');
INSERT INTO verses VALUES (8256, 10, 10, 13, 'e-veio-aproximar-se Joabe e-o-povo que com-ele para-a-guerra em-a-Aram e-eles-fugiram de-face-dele');
INSERT INTO verses VALUES (8257, 10, 10, 14, 'e filhos-de Amom viram porque fugiu Arã de-diante-de de-diante-de Abisai e-vieram a-cidade e-estabeleceu-se de-cima-de de-sobre filhos-de Amom E-veio Jerusalém');
INSERT INTO verses VALUES (8258, 10, 10, 15, 'E-viu Arã que foi-atingido diante-de Israel e-foram-reunidos juntos');
INSERT INTO verses VALUES (8259, 10, 10, 16, 'e-enviou Hadezezer e-saiu a Aram que o-rio o-rio e-vieram chelam veshovach príncipe-de exército-de hadadezer diante-deles');
INSERT INTO verses VALUES (8260, 10, 10, 17, 'vayuggad ledavid vaeessof a todo Israel vayaavor a o-Jordão E-veio chelamah vayaarchu aram ao-encontro-de Davi e-lutaram com-ele-verso');
INSERT INTO verses VALUES (8261, 10, 10, 18, 'e-fugiu Aram-em de-diante-de Israel e-matou Davi de-Aram sete novecentos carros e-quarenta mil cavaleiros e-a retornando-o príncipe-de exército-seu atingiu E-morreu nome');
INSERT INTO verses VALUES (8262, 10, 10, 19, 'e-eles-viram todo os-reis servos-de que porque niggu״fuֿ diante-de Israel va-yashluבimu a Israel va-yaabdu״um e-reverenciaram Arã lehoshiaבa ainda a filhos-de Amom');
INSERT INTO chapters VALUES (278, 10, 11, 27);
INSERT INTO verses VALUES (8263, 10, 11, 1, 'e-houve litshuvata hashana״ah le-et tseet hamalakim e-enviou Davi a yoav e-a os-seus-escravos com-ele e-a todo Israel e-eles-destruiram a filhos-de Amom e-eles-construíram sobre multiplicai e-David habitante em-Jerusalém');
INSERT INTO verses VALUES (8264, 10, 11, 2, 'e-houve ao-tempo-de o-crepúsculo E-levantou Davi de-sobre de-cima-de e-ele-caminhou sobre telhado casa-de E-viu E-viu mulher de-cima-de de-sobre o-telhado e-a-mulher vista muito muito');
INSERT INTO verses VALUES (8265, 10, 11, 3, 'e-enviou Davi e-ele-procurou para-a-mulher E-disse porventura-não esta filha-de sete filha-de Eliam mulher-de Uriah o-heteu');
INSERT INTO verses VALUES (8266, 10, 11, 4, 'e-enviou Davi anjos e-ele-levou-a e-entrou a-ele e-ele-deitou e ela sanctificando-se de-a-sua-imundícia e-retornou a casa-de-a-ela');
INSERT INTO verses VALUES (8267, 10, 11, 5, 'e-concebeu a-mulher e-ele-mandou e-relatou para-David E-disse grávida eu');
INSERT INTO verses VALUES (8268, 10, 11, 6, 'e-estendeu Davi a יוֹאָב enviou a-mim a Uriah o-heteu e-enviou Joab a Uriah a Davi');
INSERT INTO verses VALUES (8269, 10, 11, 7, 'E-veio Uriah a-ele ele perguntou Davi para-shalom Joabe para-shalom o-povo para-shalom ha-milchamah');
INSERT INTO verses VALUES (8270, 10, 11, 8, 'E-disse Davi Desce para o teu lar e lava teus pés e-saiu Ário de-casa-de o-rei e saiu atrás-dele a carga de o rei');
INSERT INTO verses VALUES (8271, 10, 11, 9, 'e-ele-deitou Uriah פֶּ֚תַח casa o-rei a todo servos-de seu-mestre e-não desceu a casa-dele');
INSERT INTO verses VALUES (8272, 10, 11, 10, 'e-contaram para-Davi dizendo não ירד Uri-yah E-disse casa-dele E-disse Davi a tu não de-caminho-de tu veio por-que não desceste-te a em-a-casa-tua');
INSERT INTO verses VALUES (8273, 10, 11, 11, 'E-disse Uri-yah a Davi o-aron e-Israel e-Juda yoshvim-acento-grave nas-sucot e-meu-adonai Joabe e-servos-de Adonai sobre face-de o-campo חֹנִ֔ים e-eu virei a casa-meu para-comer e-para-dois e-deitar com אִשְׁתִּ֑י vida-teu e-viva a-tua-vida se eu-farei a a-palavra a-esta');
INSERT INTO verses VALUES (8274, 10, 11, 12, 'E-disse Davi a Uriah retornou nesta também o-dia e-amanhã ašalchecha'' e-ele-habitou no-dia em-Jerusalém no-dia o-aquele e-depois-amanhã');
INSERT INTO verses VALUES (8275, 10, 11, 13, 'e ele chamou a-ele e-comeu e-comesse perante-ele e-bebeu e-o-embriagou e-saiu na-noite para-deitar-se no-seu-leito com servos-de não e-a casa-dele não desceu');
INSERT INTO verses VALUES (8276, 10, 11, 14, 'e-houve em-a-manhã e-escreveu Davi livro a Joabe e-enviou em-mão-de Urias');
INSERT INTO verses VALUES (8277, 10, 11, 15, 'e-escreveu no-livro dizendo dai a Urias face-de móel face-de a-guerra a-forteza e-vos-senteis de-aquele-o e-se-fere e-morreu');
INSERT INTO verses VALUES (8278, 10, 11, 16, 'e-houve em-a-guarda יוֹאָב a E-colocou E-deu a Uriah saber que que conheceu porque homens de valor nome');
INSERT INTO verses VALUES (8279, 10, 11, 17, 'e-saíram homens-de a-cidade e-combateram a יוֹאָב e-caiu de o-povo de-aos-servos-de também E-morreu também Uriah o-heteu');
INSERT INTO verses VALUES (8280, 10, 11, 18, 'e-enviou Joabe e-anunciou para-David a todo palavras-de a-guerra');
INSERT INTO verses VALUES (8281, 10, 11, 19, 'E-ordenou a dizendo dizendo quando-vos-terminais a todo palavras-de ha-milchamah de-falar a o rei');
INSERT INTO verses VALUES (8282, 10, 11, 20, 'e-foi se subireis ira o-rei a-ti para-ti por-que niggeshtem a a-cidade לְתַלְיָחֵ֑ם não Yedautem de-cima-de que yoru de-sobre ha-choma');
INSERT INTO verses VALUES (8283, 10, 11, 21, 'quem bateu a Avimelek filho-de Yerubeshet não mulher de-cima-de alav pelach carruagem de-sobre ha-chomah E-morreu bet-tevetz também niggeshtem a ha-chomah e dirás também עַבְדְּךָ֛ Uriah do Hítie morreu');
INSERT INTO verses VALUES (8284, 10, 11, 22, 'E-andou ham-malach E-veio e-anunciou para-David a todo que envi-o יוֹאָב׃');
INSERT INTO verses VALUES (8285, 10, 11, 23, 'E-disse o-anjo a Davi porque forç-aram aleinu os-homens e-saíram a-nós o-campo e-nos-torn-amos sobre-eles até porta a-por-ta');
INSERT INTO verses VALUES (8286, 10, 11, 24, 'a o-teu-serv-o de-sobre a muralha e-eles-morr-eram de-cima-de o-rei e-também עַבְדְּךָ֛ Uriah do Hítie morreu');
INSERT INTO verses VALUES (8287, 10, 11, 25, 'E-disse Davi a hammaleakh assim dizes a Joabe a será-mau em-olhos-teus comerás a-palavra este porque assim e-assim comerá a-espada a a-cidade');
INSERT INTO verses VALUES (8288, 10, 11, 26, 'vatisma mulher-de uriyah porque morreu אוּרִיָּ֣ה marido-dela vitsafod sobre ba''aluh');
INSERT INTO verses VALUES (8289, 10, 11, 27, 'vayaavor ha''evel e-enviou Davi e-a-colheu a sua-casa e-ela-tornou-se a-ele a-ele filho a-ele filho e-mau a-palavra que yhwh Davi em-olhos-de yhwh');
INSERT INTO chapters VALUES (279, 10, 12, 31);
INSERT INTO verses VALUES (8290, 10, 12, 1, 'e-ele-mandou yhwh a deu a a-ele E-disse a-ele E-disse a-ele segundo homens foram um uma um ashir e-um cabeça');
INSERT INTO verses VALUES (8291, 10, 12, 2, 'para o rico ser rebanho e-vacas muito muito');
INSERT INTO verses VALUES (8292, 10, 12, 3, 'velarah não-há que porque uma kivshah uma pequeno que comprou e viveu-a e cresceu com-ele e-com- comerás juntos de seu berço comeria e de sua cobertura bebiera em-seu-rosto dormiria e-ela-tornou-se para-ele cobaia');
INSERT INTO verses VALUES (8293, 10, 12, 4, 'E-veio andou a homem-de o rico e teve compaixão tomar de seu rebanho e de sua ovelha para fazer para o estrangeiro o que vem E-tomou E-tomou a כִּבְשַׂת֙ o-homem a cabeça e fez-a a-ele o que vem a-ele');
INSERT INTO verses VALUES (8294, 10, 12, 5, 'e-acendeu-se- nariz Davi muito E-disse E-disse a que vive yhwh porque esta morte o homem esta-ali');
INSERT INTO verses VALUES (8295, 10, 12, 6, 'e-a [יְשַׁלֵּ֣ם] pagará [עֵ֗קֶב] [אֲשֶׁ֤ר] que fez a a-coisa esta e-sobre que não');
INSERT INTO verses VALUES (8296, 10, 12, 7, 'E-disse deu a tu tu o-homem yhwh disse yhwh eu Israel eu [עַל־יִשְׂרָאֵ֔ל] para-o-rei sobre Israel e-eu de-mão-de שָׁאוּל');
INSERT INTO verses VALUES (8297, 10, 12, 8, 'va-etthana a-ti a casa [וְאֶת־נְשֵׁ֤י] e-a [בְּחֵיקֶ֔ךָ] [וָאֶתְּנָ֣ה] a-ti e-dei para-ti a casa Israel e Judá e-se-que- [וְכָהֵֽנָּה] para ti');
INSERT INTO verses VALUES (8298, 10, 12, 9, 'por-que viste a palavra yhwh para fazer o mal a urias o-hitita castigaste com a espada e- mulher-dele levaste a ti para-mulher e-aquele-o mataste com a espada filhos-de Amon');
INSERT INTO verses VALUES (8299, 10, 12, 10, 'e-agora não espada espada de tua casa até que עֵ֚קֶב e-tomou em-mi e-ta-qqa a esht a-ti ha-khitti a-ser a-ti para-mulher');
INSERT INTO verses VALUES (8300, 10, 12, 11, 'assim disse disse yhwh levanta al-ekha mal mi-betekha e-lakaqtie a nashaycha perante ti e eu dar-ei lera''ekha וְשָׁכַב֙ com נָשֶׁ֔יךָ aos-olhos-de הַשּׁ֥מֶשׁ a esta');
INSERT INTO verses VALUES (8301, 10, 12, 12, 'que tu fizeste [בַסָּ֑תֶר] e-eu [אֶעֱשֶׂה֙] a a-coisa diante diante-de todo Israel e-diante-de o-sol');
INSERT INTO verses VALUES (8302, 10, 12, 13, 'E-disse Davi a deu [לַֽיהוָ֑ה] para-יהוה E-disse deu a Davi também yhwh não [תָמֽוּת] não morra');
INSERT INTO verses VALUES (8303, 10, 12, 14, '[אֶ֗פֶס] porque [נִאַ֙צְתָּ֙] [אֶת־אֹיְבֵ֣י] yhwh [בַּדָּבָ֖ר] yhwh também este também a-ti morrendo a-ti morrer morra');
INSERT INTO verses VALUES (8304, 10, 12, 15, 'E-andou deu a casa-dele yhwh yhwh a [יָלְדָ֧ה] que [לְדָוִ֖ד] esposa-de Urias para-David');
INSERT INTO verses VALUES (8305, 10, 12, 16, 've-yevakesh Davi a o-Elohim através-de [וַיָּ֤צָם] [דָּוִד֙] Davi צָמֹ֔א וּבָ֥א [וְשָׁכַ֥ב] e deitou-se para-terra');
INSERT INTO verses VALUES (8306, 10, 12, 17, 'e levantaram-se זִקְנֵ֤י em-a-casa-seu sobre-ele para levantá-lo de a-terra e-não pai e-não criou com-eles pão');
INSERT INTO verses VALUES (8307, 10, 12, 18, 'e-houve no-dia ha-shevi-i E-morreu o menino e viram servos-de Davi para anunciar a-ele porque morreu o-menino que disseram eis em sua existência o menino vida falamos a-ele e-não ouviu com nossa voz e como a-ele a-ele morreu o-menino e fez mal');
INSERT INTO verses VALUES (8308, 10, 12, 19, 'E-viu Davi que seus-servos que sussurram e edificou Davi que morreu o menino E-disse Davi a seus servos há morte o-menino e disseram morreu');
INSERT INTO verses VALUES (8309, 10, 12, 20, 'E-levantou Davi da terra e lavou e ungiu e trocou E-veio casa-de yhwh e-ele-se-inclinou E-veio a casa-dele e perguntou e-os-colocaram a-ele pão e-comeu');
INSERT INTO verses VALUES (8310, 10, 12, 21, 'e-disseram seus-servos a-ele que a-palavra este que tu-fizeste por-causa-de vida viveu que se absteve de comer e chorou e-que morreu o-menino e-comeste e-comeu pão');
INSERT INTO verses VALUES (8311, 10, 12, 22, 'E-disse בְּעוֹד֙ o-ninho vida eu-ficrei e-chorava que dissesse quem sabe yhwh e-está yhwh');
INSERT INTO verses VALUES (8312, 10, 12, 23, 'e-agora morreu por-que isto eu fome aquele-que-comer לַהֲשִׁיב֖וֹ ainda eu andou para-ele a-ele não volta para-mim');
INSERT INTO verses VALUES (8313, 10, 12, 24, 'e-nachem Davi a filha-de sete mulher-dele E-veio para-ela com-ela com-ela filho filho a nome-dele Shelomoh וַיהוָ֖ה אֲהֵבֽוֹ׃');
INSERT INTO verses VALUES (8314, 10, 12, 25, 'e-enviou em-mão-de deu o-profeta E-chamou a nome-de-ele [בַּעֲב֖וּר] yhwh yhwh');
INSERT INTO verses VALUES (8315, 10, 12, 26, 'וַיִּלָּחֵם יוֹאָב em-Rabá filhos-de Amom [וַיִּלְכֹּ֖ד] a cidade o-reino');
INSERT INTO verses VALUES (8316, 10, 12, 27, 'e-enviou Joab [מַלְאָכִ֖ים] a E-disse E-disse [בְרַבָּ֔ה] [גַּם־לָכַ֖דְתִּי] também as-águas a cidade as-águas');
INSERT INTO verses VALUES (8317, 10, 12, 28, 'e-agora אֱסֹף֙ a Jetro o-povo וַחֲנֵ֥ה sobre a-cidade וְלָכְדָ֑הּ para-que-não Elcód eu a a-cidade e foi chamada nome-meu sobre-ela');
INSERT INTO verses VALUES (8318, 10, 12, 29, 'e-reuniu-se Davi a todo o-povo E-andou Rabba e lhe combatia espírito e prendeu-a');
INSERT INTO verses VALUES (8319, 10, 12, 30, 'E-tomou a de-cima-de do seu rei de cima de sua cabeça ouro como uma ouro e pedra preciosa e-foi sobre cabeça Davi e-despojo-de muito tirou muito muito');
INSERT INTO verses VALUES (8320, 10, 12, 31, 'e-a o-povo que nela הוֹצִ֗יא e-colocou בַּ֠מְּגֵרָה וּבַחֲרִצֵ֨י הַבַּרְזֶ֜ל וּֽבְמַגְזְרֹ֣ת o bronze וְהֶעֱבִ֤יר a-eles e-assim faz a-todo cidades-de filhos-de Amom e-estabeleceu-se Davi e-todo o-povo Jerusalém');
INSERT INTO chapters VALUES (280, 10, 13, 39);
INSERT INTO verses VALUES (8321, 10, 13, 1, 'e-houve depois-de assim וּלְאַבְשָׁל֧וֹם filho-de Davi אָח֥וֹת יָפָ֖ה e-nome-dela תָּמָ֑ר e amou-a era filho-de Davi');
INSERT INTO verses VALUES (8322, 10, 13, 2, 'e encolerizou-se para Amnôim para se exibir em-vez-de Tamar sua irmã que virgem ela e fez em-olhos-de Amnôim para-fazer para-ela qualquer-coisa');
INSERT INTO verses VALUES (8323, 10, 13, 3, 'e para Amnôim mau e seu nome יֽוֹנָדָ֔ב filho-de שִׁמְעָ֖ה Ai Davi וְי֣וֹנָדָ֔ב homem muito muito');
INSERT INTO verses VALUES (8324, 10, 13, 4, 'E-disse a-ele por-que tu assim דַּ֤ל filho-de o rei ba-voker de-manhã acaso-nao תַּגִּ֣יד E-disse a-ele a-ele אַמְנ֔וֹן a תָּמָ֗ר אֲח֛וֹת אַבְשָׁלֹ֥ם irmão-meu eu amou');
INSERT INTO verses VALUES (8325, 10, 13, 5, 'E-disse a-ele יְה֣וֹנָדָ֔ב שָׁכַב sobre de-dormir-teu וַיִּתֶּן-בוֹא וַיֵּבֶא אָבִיךָ לִרְאוֹתֶךָ a-ele אֵלָיו תַּבֹּא por-favor תָּמָר אֲחוֹתִי pão לֶחֶם e farás perante mim a a criatura a-fim-de que eu veria e comei imediatamente dela:');
INSERT INTO verses VALUES (8326, 10, 13, 6, 'e-ele-deitou Amnôen e se propôs E-veio o-rei a vê-lo E-disse Amnôen a o rei vem- por-favor תמר irmã-meu e-alevave para-meus-olhos duas nos-seus-corações e-abrerei imediatamente-ela');
INSERT INTO verses VALUES (8327, 10, 13, 7, 'e-enviou Davi a [הַבַּ֣יְתָה] dizendo dizendo vai agora casa amnon [וַעֲשִׂי־ל֖וֹ] [הַבִּרְיָֽה] para-ele');
INSERT INTO verses VALUES (8328, 10, 13, 8, 'e-ela-partiu-se [תָּמָ֗ר] casa [אַמְנ֥וֹן] [אָחִ֖יהָ] e-ele deitado e-tomou a [*ותלוש] [**וַתָּ֙לָשׁ֙] [וַתְּלַבֵּ֣ב] [לְעֵינָ֔יו] a [אֶת־הַלְּבִבֽוֹת]');
INSERT INTO verses VALUES (8329, 10, 13, 9, 'e-tomou a a-mashreth vatitzok diante-dele vayma''en E-disse E-disse Ammôn hitz''u todo homem de-sobre-mim vayts''au todo homem me''alayo');
INSERT INTO verses VALUES (8330, 10, 13, 10, 'E-disse Ammôn a Tâmár havi a-criação e-abrê da-te e-tomou tamar a as-corações que ela-fez e-levou para-amnô seu-irmão a-sala');
INSERT INTO verses VALUES (8331, 10, 13, 11, 'e-expulsou a-ele para comer e fortaleceu-se- E-disse E-disse para-ela em mim dormir-me com-mim irmã-meu:');
INSERT INTO verses VALUES (8332, 10, 13, 12, 'E-disse a-ele a irmão-meu que consolai-me porque não faz-se assim em-Israel a taaseh a a profanação a esta');
INSERT INTO verses VALUES (8333, 10, 13, 13, 'e-eu eis que comeria a cherpáti e-tu como-um-de como-um-de os-nabalim e-agora e-agora diga- que não o-rei porque não אימנעי de-te');
INSERT INTO verses VALUES (8334, 10, 13, 14, 'e-não pai para-ouvir em sua voz e-ele-firmou de ela e respondeu-a e-deitou-se a-ela');
INSERT INTO verses VALUES (8335, 10, 13, 15, 'e odiou-a Amnô odio grande muito que grande o ódio que senha-a de-ahava que aheva-ha e-foi-dito- para-ela Amnon qumi vai:');
INSERT INTO verses VALUES (8336, 10, 13, 16, 'E-disse a-ele a odot ha-ra''a hagadolah a-esta de-outra que fiz-te com-mim para-me-enviar e-não pai para-ouvir a-ela');
INSERT INTO verses VALUES (8337, 10, 13, 17, 'E-chamou a [מְשָׁ֣רְת֔וֹ] E-disse E-disse enviaram- agora a esta sobre mim o-exterior a-porta atrás-de-ela');
INSERT INTO verses VALUES (8338, 10, 13, 18, 'e-na-ela tunica faixas que assim vestirdes-vos filhas- o-rei as virgens manto-s וַיֹּצֵ֨א ela serviçã-lo o-fora e-calçastes a-porta atrás-de-ela');
INSERT INTO verses VALUES (8339, 10, 13, 19, 'e-tomou Tamar farinha sobre cabeça-ela e a túnica as faixas que sobre-ela arrancou e-pôs mão-seu sobre sua cabeça e-foi indo e gritou:');
INSERT INTO verses VALUES (8340, 10, 13, 20, 'E-disse a-ela Absalão seu irmão Amminadabe irmão teu ser com--te e-agora meu irmão Cherujim seu-irmão ele a -eu-destruirei a -teu-coração para-a-palavra esta e-habitou -tu-amarás -e-silenciaste casa אַבְשָׁלוֹם -seu-irmão-a');
INSERT INTO verses VALUES (8341, 10, 13, 21, 'e-o-rei Davi ouviu a todo as-palavras estas a-ele muito muito');
INSERT INTO verses VALUES (8342, 10, 13, 22, 'e-não palavra absalom com amnon -para-mal e-até bom porque odiou Absalão a amnon sobre palavra que עִנּוּ a תְּמָר אֲחוֹתֶיהָ׃');
INSERT INTO verses VALUES (8343, 10, 13, 23, 'e-houve [לִשְׁנָתַ֣יִם] dias e-foram [גֹֽזְזִים֙] [לְאַבְשָׁל֔וֹם] em-Baal [חָצ֖וֹר] que com E-chamou E-chamou [לְכָל־בְּנֵ֥י] para-todo filhos-de o rei');
INSERT INTO verses VALUES (8344, 10, 13, 24, 'E-veio Absalão a E-disse E-disse eis-que- agora o pastoreando para-servidor-teu andará- agora o-rei com servo-teu');
INSERT INTO verses VALUES (8345, 10, 13, 25, 'E-disse o-rei a אַבְשָׁל֗וֹם a filhos-de a por-favor נֵלֵךְ [עָלֶ֑יךָ] e-não [וְלֹֽא־אָבָ֥ה] sobre-ti e-ele-rompeu- nele e-não para-andar');
INSERT INTO verses VALUES (8346, 10, 13, 26, 'E-disse Absalão e-não andará- por-favor com-nós amnon E-disse a-ele a-ele o-rei por-que [עִמָּֽךְ] contigo');
INSERT INTO verses VALUES (8347, 10, 13, 27, 'e-ele-rompeu- nele [וַיִּשְׁלַ֤ח] e-estendeu com-ele a [כָּל־בְּנֵ֥י] e-a todo filhos-de o rei');
INSERT INTO verses VALUES (8348, 10, 13, 28, 'E-ordenou [אַבְשָׁל֨וֹם] a dizendo dizendo Reu por-favor [לֵב־אַמְנ֤וֹן] coração-de [וְאָמַרְתִּ֣י] [אֲלֵיכֶ֔ם] e-disser a-vós [וַהֲמִתֶּ֥ם] ele [אַל־תִּירָ֑אוּ] [הֲל֗וֹא] que eu temei-vos halo porque eu ordenei a-vós fortaleceis ve-heyu para-filhos-de força');
INSERT INTO verses VALUES (8349, 10, 13, 29, 'WAYYISA''OUM נערֵי Absalão לאמנון como-que ordenou אבשalom WAYYAKUMU ⃡ todo filhos-de o rei e levaram homem sobre seus puros e foram arrebatados');
INSERT INTO verses VALUES (8350, 10, 13, 30, 'e-houve eles no-caminho e a notícia veio a dizendo dizendo bateu Absalão a todo filhos-de um e-não notar deles um');
INSERT INTO verses VALUES (8351, 10, 13, 31, 'E-levantou o-rei e rasgou a suas vestes e-ele-deitou terra e-todo seus-servos estando-plantados rasgadas vestes');
INSERT INTO verses VALUES (8352, 10, 13, 32, 'e respondeu Yoナdaב filho-de Shimעה meu-irmão- E-disse E-disse a dizei Adonai a todo os jovens sozinho o rei e mataram porque era apenas ele morreu porque sobre פי Absalão era Suמה desde o dia que sua voz a Tamar sua-irmã;');
INSERT INTO verses VALUES (8353, 10, 13, 33, 'e-agora a ele-nomeou; Adonai o-rei a dizendo palavra dizendo todo filhos-de sozinho e-eles-morreram; porque era sozinho morreu');
INSERT INTO verses VALUES (8354, 10, 13, 34, 'e-ele-foi-em-fuga; Absalão; e-ele-levantou; o-jovem; que-estava-vigilando; a E-viu E-viu com muito andando do-caminho; atrás-dele de-frente; a-montanha');
INSERT INTO verses VALUES (8355, 10, 13, 35, 'E-disse [יֽוֹנָדָב֙] a eis eis filhos-de o-rei eles-vieram conforme-palavra-de ser assim foi');
INSERT INTO verses VALUES (8356, 10, 13, 36, 'e-houve [׀] [כְּכַלֹּת֣וֹ] e-eis filhos-de o rei vieram e-levantaram voz-deles e-vibku e-também o rei e-todo seus-servos [גָּד֥וֹל] muito grande muito');
INSERT INTO verses VALUES (8357, 10, 13, 37, 'ואבשלאם ברח E-andou a תלמי filho-de rei Geshur WAYIT''AVVEL sobre filho-seu todo os dias');
INSERT INTO verses VALUES (8358, 10, 13, 38, '[וְאַבְשָׁל֥וֹם] [בָּרַ֖ח] E-andou Geshur e-foi nome três dois');
INSERT INTO verses VALUES (8359, 10, 13, 39, '[וַתְּכַל֙] Davi o-rei [לָצֵ֖את] a [כִּֽי־נִחַ֥ם] porque niḥam sobre porque morreu');
INSERT INTO chapters VALUES (281, 10, 14, 33);
INSERT INTO verses VALUES (8360, 10, 14, 1, 'sabendo יוֹאָב filho-de צריה porque coração o-rei sobre אַבְשָׁלוֹם');
INSERT INTO verses VALUES (8361, 10, 14, 2, 'e-estendeu Joabe תקועה E-tomou de-lá mulher חכמה E-disse אליה hita''aballi- por-favor velibshi- por-favor bigdei- e''avel e-a tasuocyi- óleo vehayit- ke''isha- este dias muitos mita''abbet- sobre morreu');
INSERT INTO verses VALUES (8362, 10, 14, 3, '[וּבָאת֙] a o-rei a-ele a-ele como-dizer este e-ele-posto Joab a as-palavras');
INSERT INTO verses VALUES (8363, 10, 14, 4, 'E-disse a-mulher a queimada a o-rei e caiu sobre sua ira E-disse e se prostraram e-disse Salva o rei');
INSERT INTO verses VALUES (8364, 10, 14, 5, 'e-ele-disse para-ela o-rei E-disse para-ti e-disse porém אִשָּֽׁה־ אלמנה ani E-morreu meu-homem-verso');
INSERT INTO verses VALUES (8365, 10, 14, 6, 'e sua serva segundo filhos e foram vencidos dois-deles no-campo e-não-há resgatador בֵּֽינֵיהֶ֑ם וַיַּכּ֧וֹ o-primeiro a הָאֶחָ֖ד ele ele');
INSERT INTO verses VALUES (8366, 10, 14, 7, 'e-eis levantou todo הַמִּשְׁפָּחָ֜ה sobre שִׁפְחָתֶ֗ךָ e-disseram תְּנִ֣י ׀ a מַכֵּ֣ה o-seu-irmão וּנְמִיתֵ֙הוּ֙ בְּנֶ֤פֶשׁ seu-irmao que também וְנַשְׁמִ֖ידָה também a o herdeiro e cobri para-não eu me encolhi que fiquei para nada a-terra nome e restou sobre face-de a-terra');
INSERT INTO verses VALUES (8367, 10, 14, 8, 'E-disse o-rei a a-mulher vai para o teu lar e-eu mandaremos sobre ti');
INSERT INTO verses VALUES (8368, 10, 14, 9, 'E-disse a-mulher [הַתְּקוֹעִית֙] a o-rei [Adonai] Adonai o-rei [וְעַל־בֵּ֣ית] e-sobre casa pai-meu e-o-rei נקי׃');
INSERT INTO verses VALUES (8369, 10, 14, 10, 'E-disse o-rei [הַֽמְדַבֵּ֤ר] para-ti [וַֽהֲבֵאת֣וֹ] a-mim e-não yo-sif ainda sobre-ti em-ti');
INSERT INTO verses VALUES (8370, 10, 14, 11, 'E-disse [יִזְכָּר־נָ֨א] por-favor o-rei a yhwh Elohim-teus [גֹּאֵ֤ל] ha-dam [לְשַׁחֵ֔ת] e-não [יַשְׁמִ֖ידוּ] a E-disse E-disse vive yhwh se [אָֽרְצָה] filho-de-você para-terra');
INSERT INTO verses VALUES (8371, 10, 14, 12, 'E-disse a-mulher [תְּדַבֶּר־נָ֧א] por-favor serva-tua a Adonai E-disse palavra E-disse');
INSERT INTO verses VALUES (8372, 10, 14, 13, 'E-disse a-mulher [וְלָ֧מָּה] [חָשַׁ֛בְתָּה] como-esta sobre povo Elohim [הַמֶּ֜לֶךְ] o-rei a-coisa o-este para-não sem [הַמֶּ֖לֶךְ] o-rei a');
INSERT INTO verses VALUES (8373, 10, 14, 14, 'porque morte-de morremos e como as águas os que gemem terra-para não não serão reunidos e-não levarei Elohim alma para-não pensamentos nós despeçarei dele e lançarei');
INSERT INTO verses VALUES (8374, 10, 14, 15, 'e-agora que venho para falar a o-rei Adonai que a-coisa esta E-disse e me vereis o-povo e ela disse serva-te falar-ei-a agora a o-rei talvez ele-fará o-rei a palavra sua-serva');
INSERT INTO verses VALUES (8375, 10, 14, 16, 'que אֵֽהַר o-rei para-resgatar a sua-serva da-palma o-homem para-destruir mim e-a filhos-de junto de-herança Elohim');
INSERT INTO verses VALUES (8376, 10, 14, 17, 'E-disse serva-te ele-será- נָא palavra-de Adonai que לִמְנוּחָה que כְּמַלְאַ֣ךְ o-Elohim assim Adonai o-rei para ouvir o-bom וְהָרָ֔ע e-יהוה haja seja contigo');
INSERT INTO verses VALUES (8377, 10, 14, 18, 'e-respondeu o-rei E-disse a a-mulher a por-favor [דָּבָ֔ר] de-mim eu que eu E-disse a-ti e-disse a-mulher YEDABER- por-favor Adonai o rei');
INSERT INTO verses VALUES (8378, 10, 14, 19, 'E-disse o-rei הֲיַ֥ד Joab אִתָּ֖ךְ em-todo esta וַתַּ֣עַן E-disse e disse viva - a tua alma - Adonai o-rei se homem - de-toda e para fazer de-todo que palavra Adonai ele porque servo-teu Joabe ele ordenou-me וְה֗וּא nome por minha boca serva tua - a todo as-palavras as estas');
INSERT INTO verses VALUES (8379, 10, 14, 20, 'para ao redor de a face-de a-palavra fez avadcha יוֹאָב a a-coisa esta e-meu-senhor sábio por-inteligência para-conhecer os-Elohim para-conhecer a todo que na-terra');
INSERT INTO verses VALUES (8380, 10, 14, 21, 'E-disse o rei a יוֹאָב eis-que- agora fiz a a-coisa esta e-vai retornar a o-menino a אַבְשָׁלוֹם');
INSERT INTO verses VALUES (8381, 10, 14, 22, 'e-ele-caiu יהOAv a de-seus-faces prostrou-se E-abençoou E-abençoou E-disse o-rei o-dia saber o-hoje conheceu servo-teu porque achei graça em-olhos-teus Adonai o-rei que fez o-rei a palavra');
INSERT INTO verses VALUES (8382, 10, 14, 23, 'E-levantou יוֹאָב E-andou gessura e-trouxe a absalão Jerusalém');
INSERT INTO verses VALUES (8383, 10, 14, 24, 'E-disse o rei vir-vai a casa-dele não não ele-verá e-ele-vir Absalão a casa-dele não ver não viu');
INSERT INTO verses VALUES (8384, 10, 14, 25, '[וּכְאַבְשָׁל֗וֹם] não foi homem-de [לְהַלֵּ֣ל] muito Israel para-louvar muito [קָדְקֳד֔וֹ] [לֹא־הָ֥יָה] nele [מֽוּם] não foi em-ele');
INSERT INTO verses VALUES (8385, 10, 14, 26, 'וּֽבְגַלְּחוֹ֮ a רֹאשׁוֹ֒ e-foi מִקֵּ֨ץ יָמִ֤ים ׀ aos-dias que irá-escurecer porque grande sobre-ele e-o-escurecimento e-pesou a cabelo cabeça-sua duzentos escalam em pedra o rei');
INSERT INTO verses VALUES (8386, 10, 14, 27, 'e-eles-geraram para-absaolom três filhos e-filha uma e-nome-dela תָּמָר ela era mulher יְפַת vista');
INSERT INTO verses VALUES (8387, 10, 14, 28, 'e-habitou [אַבְשָׁל֛וֹם] birushalaim dois anos dias e-faces-de o-rei não ver');
INSERT INTO verses VALUES (8388, 10, 14, 29, 'e-enviou [אַבְשָׁל֜וֹם] a Joabe ele ele a o-rei e-não a-ele para-vir a-ela e-enviou ainda segunda-noite e-não pai');
INSERT INTO verses VALUES (8389, 10, 14, 30, 'E-disse a עֲבָדָ֜יו רְאוּ֩ חֶלְקַ֨ת Yoav a mão-minha e-para-ele- nome semente-de-trigo ide no-fogo e estacaram-se servos Absalão a a parte em-a-chama');
INSERT INTO verses VALUES (8390, 10, 14, 31, 'E-levantou יוֹאָב E-veio a Absalão E-disse a-ele a-ele por-que e acenderam seu servo a a parte que yhwh em-a-chama');
INSERT INTO verses VALUES (8391, 10, 14, 32, 'E-disse Absalão a eis eis enviei-eu [׀] dizendo veio [הֵ֠נָּה] [וְאֶשְׁלְחָה֩] [אֹתְךָ֨] a dizendo dizendo por-que ven-ei bom bom a-mim até e-agora nome face-de [הַמֶּ֔לֶךְ] face-de o-rei e-se há em-mi עון');
INSERT INTO verses VALUES (8392, 10, 14, 33, 'E-veio יוֹאָב a הַמֶּלֶךְ֮ E-chamou para-ele E-chamou a Absalão a-ele a o-rei [לִפְנֵ֣י] para-ele sobre [הַמֶּ֖לֶךְ] terra-para diante-de o-rei e-ele-beijou o-rei');
INSERT INTO chapters VALUES (282, 10, 15, 37);
INSERT INTO verses VALUES (8393, 10, 15, 1, 'e-houve depois-de assim E-fez a-ele Absalão [מֶרְכָּבָ֖ה] [וְסֻסִ֑ים] e-cinquenta homem correndo diante-de-ele');
INSERT INTO verses VALUES (8394, 10, 15, 2, 'e levantar-se-á Absalão e estabelecer-se-á sobre o-caminho-de caminho e-houve E-foi todo o-homem que ser- E-chamou disputa a-ele E-disse o-rei para julgamento tu E-disse a-ele E-disse ei- mizze cidade tu E-disse de um tribo de Israel servo-teu');
INSERT INTO verses VALUES (8395, 10, 15, 3, 'E-disse a-ele Absalão viu seu discurso bons e fortes e ouvinte não-há a-ti de-com o rei');
INSERT INTO verses VALUES (8396, 10, 15, 4, 'E-disse Absalão quem [שֹׁפֵ֖ט] שפט em-a-terra [יָב֛וֹא] [כָּל־אִ֛ישׁ] todo homem que ser- dispute וּמִשְׁפָּ֖ט');
INSERT INTO verses VALUES (8397, 10, 15, 5, 'e-foi [בִּקְרָב־אִ֔ישׁ] homem a-ele a-ele [אֶת־יָד֛וֹ] a a-ele e-o-estreitou a-ele a-ele');
INSERT INTO verses VALUES (8398, 10, 15, 6, 'E-fez [אַבְשָׁל֜וֹם] como-palavra o-este para-todo Israel que virão para-a-jurisdição a o-rei [אַנְשֵׁ֥י] Absalão a coração homens-de Israel');
INSERT INTO verses VALUES (8399, 10, 15, 7, 'e-houve ao-fim-de quarenta ano E-disse Absalão a o-rei irei por-favor [אֶת־נִדְרִ֛י] a [לַֽיהוָ֖ה] que para-יהוה em-Hebron');
INSERT INTO verses VALUES (8400, 10, 15, 8, 'porque [נָדַ֣ר] [עַבְדְּךָ֔] teu-servo [בִגְשׁ֛וּר] [בַּאֲרָ֖ם] dizendo dizendo se [יְשִׁיבֵ֤נִי] yhwh Jerusalém [וְעָבַדְתִּ֖י] a yhwh');
INSERT INTO verses VALUES (8401, 10, 15, 9, 'e-ele-disse a-ele o-rei vai em-a-paz E-levantou E-andou');
INSERT INTO verses VALUES (8402, 10, 15, 10, 'e-estendeu Absalão [מְרַגְּלִ֔ים] em-todo tribos-de dizendo dizendo [אֶת־ק֣וֹל] a voz-de [מָלַ֥ךְ] e-vós-direis rei em-Hebron');
INSERT INTO verses VALUES (8403, 10, 15, 11, 'e-a אַבְשָׁל֗וֹם [מָאתַ֤יִם] duzentos homem de-Jerusalém [וְהֹלְכִ֣ים] [לְתֻמָּ֑ם] [וְלֹ֥א] e-não eles-conheceram todo palavra');
INSERT INTO verses VALUES (8404, 10, 15, 12, 'e-enviou [אַ֠בְשָׁלוֹם] a [הַגִּֽילֹנִ֜י] [יוֹעֵ֣ץ] יוֹעֵ֣ץ Davi de-cidade-dele [בְּזָבְח֖וֹ] [אֶת־הַזְּבָחִ֑ים] e-houve [הַקֶּ֙שֶׁר֙] E-foi [וְהָעָ֛ם] [הוֹלֵ֥ךְ] והעם andando e abundante a אַבְשָׁלוֹם');
INSERT INTO verses VALUES (8405, 10, 15, 13, 'E-veio [הַמַּגִּ֔יד] a dizendo ser foi לֶב־ homem Israel atrás-de אַבְשָׁלוֹם');
INSERT INTO verses VALUES (8406, 10, 15, 14, 'E-disse Davi para-todo os-seus-escravos que com-ele [וְנִבְרָ֔חָה] que [לֹא־תִֽהְיֶה־לָּ֥נוּ] porque de-diante-de será- para-nos [לָלֶ֗כֶת] de-diante-de [וְהִשִּׂגָ֙נוּ֙] [וְהִדִּ֤יחַ] para-andar para-que-não [וְהִכָּ֥ה] [הָעִ֖יר] [לְפִי־חָֽרֶב] aleinu a do-mal וְהִכָּ֥ה a-cidade à-boca-de com-espada');
INSERT INTO verses VALUES (8407, 10, 15, 15, 'e-disseram servos-de- o-rei a o-rei [Adonai] que eis Adonai o-rei eis servos-teus');
INSERT INTO verses VALUES (8408, 10, 15, 16, 'e-ele-saiu o-rei e-todo casa-dele com-seus-pés e abandonou o-rei a dez [פִּֽלַגְשִׁ֖ים] [לִשְׁמֹ֥ר] לשמור a-casa');
INSERT INTO verses VALUES (8409, 10, 15, 17, 'e-ele-saiu o-rei e-todo o-povo com-seus-pés e-eles-se-puseram-em-pé casa');
INSERT INTO verses VALUES (8410, 10, 15, 18, 'e-todo seus-servos [עַל־יָד֔וֹ] sobre mão-de-ele e-todo [שֵׁשׁ־מֵא֣וֹת] e-todo [אֲשֶׁר־בָּ֤אוּ] e-todo [מִגַּ֔ת] seis-de centenas-de homem que vieram passamos sobre face-de o rei');
INSERT INTO verses VALUES (8411, 10, 15, 19, 'E-disse o-rei a [הַגִּתִּ֔י] הַגִּתִּ֔י andarás [גַּם־אַתָּ֖ה] também tu אִתָּ֑נוּ volta [כִּֽי־נָכְרִ֣י] tu o-rei tu [לִמְקוֹמֶֽךָ] tu e-também tu');
INSERT INTO verses VALUES (8412, 10, 15, 20, '[תְּמ֣וֹל] [׀] [בּוֹאֶ֗ךָ] [וְהַיּ֞וֹם] [*אנועך] e-eu indo sobre que eu sobre volta [הוֹלֵ֑ךְ] a [וְהָשֵׁ֧ב] contigo bondade e-verdade');
INSERT INTO verses VALUES (8413, 10, 15, 21, 'e-respondeu [אִתַּ֛י] a o-rei E-disse vive yhwh [הַמֶּ֔לֶךְ] que o-rei porque [יִֽהְיֶה־שָּׁ֣ם] que ele-será- [הַמֶּ֗לֶךְ] Adonai o rei se será se porque nome será servo-teu');
INSERT INTO verses VALUES (8414, 10, 15, 22, 'E-disse Davi a [לֵ֣ךְ] vai [וַֽיַּעֲבֹ֞ר] [אִתַּ֤י] [הַגִּתִּי֙] [וְכָל־אֲנָשָׁ֔יו] e-todo seus-homens e-todo que com-ele');
INSERT INTO verses VALUES (8415, 10, 15, 23, 'e-todo a-terra voz voz-de grande e-todo o-povo que passam e-o-rei passando pela torrente Cedrom e-todo o-povo que passam sobre face-de caminho a o-meadero');
INSERT INTO verses VALUES (8416, 10, 15, 24, 'e-eis também Tsadoque e-todo os levitas com-ele que levantam a arca-de aliança os-Elohim e clamaram a arca os-Elohim e-ele-subiu Efaítar até perfeito todo o-povo לַעֲב֥וֹר de a-cidade');
INSERT INTO verses VALUES (8417, 10, 15, 25, 'E-disse o rei [לְצָד֔וֹק] [הָשֵׁ֛ב] a arca Elohim a-cidade se encontro yhwh em-olhos-de yhwh ele e-me-oir a-ele e-a');
INSERT INTO verses VALUES (8418, 10, 15, 26, 'e se assim [יֹאמַ֔ר] não חָפַ֖צְתִּי sobre-ti [הִנְנִ֕י] fará- [כַּאֲשֶׁ֖ר] conforme em-seus-olhos');
INSERT INTO verses VALUES (8419, 10, 15, 27, 'E-disse o rei a Tsadoq o-sacerdote tu אתָ [הָעִ֖יר] a-cidade em-a-paz [בִּנְךָ֜] [וִיהוֹנָתָ֧ן] [בֶּן־אֶבְיָתָ֛ר] filho-de [בְנֵיכֶ֖ם] segundo filhos-vos אִתְּכֶֽם׃');
INSERT INTO verses VALUES (8420, 10, 15, 28, 'olhem: eu [מִתְמַהְמֵ֔הַּ] a-deserto até vem até trazer para-dizer para-mim');
INSERT INTO verses VALUES (8421, 10, 15, 29, 'e-retornou [צָד֧וֹק] [וְאֶבְיָתָ֛ר] a arca Elohim Jerusalém e-habitaram nome');
INSERT INTO verses VALUES (8422, 10, 15, 30, 'וְדָוִ֡ד עֹלֶה֩ בְמַעֲלֵ֨ה הַזֵּיתִ֜ים עֹלֶ֣ה ׀ וּבוֹכֶ֗ה e-cabeça a-ele a-ele e-ele andou יָחֵ֑ף e-todo o-povo que com-ele חָפוּ֙ homem cabeça-sua vealou עָלֹ֖ה וּבָכֹֽה׃');
INSERT INTO verses VALUES (8423, 10, 15, 31, 'e-David declarou dizendo Achitofel Baqashrim com E-disse E-disse Davi Sakcal- por-favor yhwh Atzat Achitofel yhwh');
INSERT INTO verses VALUES (8424, 10, 15, 32, 'e-houve Davi veio até o-primeiro que Yishtachaveh nome Le''Elohim e-eis para encontrá-lo Chusay Ha''arki Qarua'' כּתּוֹ e-terra sobre cabeça-dele');
INSERT INTO verses VALUES (8425, 10, 15, 33, 'E-disse a-ele Davi mãe [עָבַ֣רְתָּ] comigo [וְהָיִ֥תָ] sobre-mim para-a-alçada');
INSERT INTO verses VALUES (8426, 10, 15, 34, 'e-se a-cidade [וְאָמַרְתָּ֤] e-dirás [עַבְדְּךָ֨] seu-escravo eu o-rei serei servo teu-pai va-ani e-agora [וַאֲנִ֣י] e-eu servo-teu [לִ֔י] a-mim a עֲצַ֥ת');
INSERT INTO verses VALUES (8427, 10, 15, 35, 'Eis que contigo nome Zadoque e-Abiatar os sacerdotes e-foi todo a-palavra que vocês ouvirão de-casa-de o-rei e contareis a Zadoque e a Abiafar os sacerdotes:');
INSERT INTO verses VALUES (8428, 10, 15, 36, 'eis-que- nome com-eles segundo seus filhos Achimatsu a Zadoque וִיהוֹנָתָ֖ן לְאֶבְיָתָ֑ר וּשְׁלַחְתֶּ֤ם em-a-sua-mão a-mim todo palavra que תִּשְׁמָֽעוּ׃');
INSERT INTO verses VALUES (8429, 10, 15, 37, 'E-veio [חוּשַׁ֛י] amigo Davi a-cidade [וְאַבְשָׁלֹ֔ם] yavo Jerusalém');
INSERT INTO chapters VALUES (283, 10, 16, 23);
INSERT INTO verses VALUES (8430, 10, 16, 1, 'וְדָוִ֗ד עָבַ֤ר מְעַט֙ מֵֽהָרֹ֔אשׁ e-eis Tsibá jovem de-á vergonha ao-encontro-dele e-carroça cavalos montados e-sobre-eles pão pao e-cem carruagens e-cem verão e-cisne יָֽיִן׃');
INSERT INTO verses VALUES (8431, 10, 16, 2, 'E-disse o-rei a Цива o-quê E-disse para-ti E-disse [לְבֵית־הַמֶּ֜לֶךְ] [לִרְכֹּ֗ב] para-casa-de o-rei [וְהַקַּ֙יִץ֙] [לֶאֱכ֣וֹל] para-comer os-jovens [לִשְׁתּ֥וֹת] para-beber [בַּמִּדְבָּֽר] no-deserto');
INSERT INTO verses VALUES (8432, 10, 16, 3, 'E-disse o-rei [וְאַיֵּ֖ה] filho-de E-disse E-disse [אֶל־הַמֶּ֗לֶךְ] eis o rei behold que disse o-dia disse o-dia [בֵּ֣ית] a-mim casa Israel a pai-meu');
INSERT INTO verses VALUES (8433, 10, 16, 4, 'E-disse o rei [לְצִבָ֔א] eis a-ti todo que [לִמְפִי־בֹ֑שֶׁת] E-disse E-disse Цива [אֶמְצָא־חֵ֥ן] encontre favor nos-teus-olhos Adonai o rei');
INSERT INTO verses VALUES (8434, 10, 16, 5, 'e-virá o-rei Davi até [וְהִנֵּ֣ה] e-eis [אִ֨ישׁ] homem [מִמִּשְׁפַּ֣חַת] mi-mishpachath casa-de שָׁאוּל [בֶן־גֵּרָ֔א] sai filho-de [וּמְקַלֵּֽל] saindo');
INSERT INTO verses VALUES (8435, 10, 16, 6, '[וַיְסַקֵּ֤ל] [בָּֽאֲבָנִים֙] a Davi e-a todo [וְכָל־הָעָם֙] o-rei Davi e-todo o-povo e-todo do seu lado direito e do seu lado esquerdo:');
INSERT INTO verses VALUES (8436, 10, 16, 7, 'Ve-koh- disse שִׁמְעִ֖י בְּקַֽלְל֑וֹ Saia Saia homem os hematomas e-homem o inexistente');
INSERT INTO verses VALUES (8437, 10, 16, 8, 'retornou sobre ti yhwh todas sangues-de casa-de Saul que reinaste E-deu yhwh E-colocou yhwh na-mão-de Absalão benekha e tu em tua maldade porque que sangues tu');
INSERT INTO verses VALUES (8438, 10, 16, 9, 'E-disse Ávishay filho-de Tsəryāh a o-rei por-que yəqallēl ha-kelēv o morto este a Adonai o-rei eu-passarei--- na'' ve''āsīrāh a cabeça-dele');
INSERT INTO verses VALUES (8439, 10, 16, 10, 'E-disse o-rei que para-mim velaḵem filhos-de Tsəryāh yəqallēl yhwh disse a-ele yhwh disse a-ele e-quem yo''amar por-que ʿāśitāh assim');
INSERT INTO verses VALUES (8440, 10, 16, 11, 'E-disse Davi a אבישי eis todo seus-servos eis filhos-de que יצא *</miyy''ay* buscando a a-ele ואף que *</attah*> yhwh *</hey''miny* *</hannikhu*> a-ele ויקלל porque palavras-de para-ele yhwh');
INSERT INTO verses VALUES (8441, 10, 16, 12, 'talvez verá yhwh e-devolver-á yhwh a-mim yhwh debaixo-de [טוֹבָ֔ה] debaixo a-esta');
INSERT INTO verses VALUES (8442, 10, 16, 13, 'E-andou Davi [וַאֲנָשָׁ֖יו] בַּדָּ֑רֶךְ [ס] andou [הֹלֵךְ֩] o-monte [הָהָ֜ר] caminhar [הָלוֹךְ֙] [וַיְקַלֵּ֔ל] [וַיְסַקֵּ֤ל] [בָּֽאֲבָנִים֙] [לְעֻמָּת֔וֹ] [וְעִפַּ֖ר]');
INSERT INTO verses VALUES (8443, 10, 16, 14, 'E-veio o-rei e-todo o-povo que com-ele [שָֽׁם] nome');
INSERT INTO verses VALUES (8444, 10, 16, 15, '[וְאַבְשָׁל֗וֹם] e-todo o-povo homem Israel entraram Jerusalém וַאֲחִיתֹ֖פֶל com-ele');
INSERT INTO verses VALUES (8445, 10, 16, 16, 'e-houve quando veio [הָאַרְכִּ֛י] [רֵעֶ֥ה] amigo Davi E-disse [חוּשַׁי֙] E-disse [יְחִ֥י] a אַבְשָׁלֹ֔ם viva o-rei viva o rei');
INSERT INTO verses VALUES (8446, 10, 16, 17, 'E-disse Absalão a minha esperança este o teu perdão a re''ekha por-que não não a teu-companheiro');
INSERT INTO verses VALUES (8447, 10, 16, 18, 'E-disse minha esperança a não que porque que yhwh yhwh e-o-povo este e-todo homem Israel serei e com ele eu assentarei-me;');
INSERT INTO verses VALUES (8448, 10, 16, 19, 'e a segunda ל-מי eu א-עֱבֹד acaso-nao diante-de ב-נוֹ como-que ע-בדתִי֙ diante-de pai-teu assim estarei diante-de-você.');
INSERT INTO verses VALUES (8449, 10, 16, 20, 'E-disse [אַבְשָׁל֖וֹם] a [הָב֥וּ] a-vós a-vós עֵצָ֖ה que');
INSERT INTO verses VALUES (8450, 10, 16, 21, 'E-disse [אֲחִיתֹ֙פֶל֙] a trazer [אֶל־פִּלַגְשֵׁ֣י] a [אֲשֶׁ֥ר] pai-teu que [הַבָּ֑יִת] לִשְׁמ֣וֹר a-casa וְשָׁמַ֤ע todo Israel porque [כָּל־אֲשֶׁ֥ר] a pai-teu mãos-de todo que contigo');
INSERT INTO verses VALUES (8451, 10, 16, 22, 'Vayattu L''Avshalom ha-o-hel sobre o-telhado E-veio Absalão seu-pai Feligshi pai-dele aos-olhos-de todo Israel');
INSERT INTO verses VALUES (8452, 10, 16, 23, 'e conselho Ahitophel que יָעַץ֙ em-os-dias aqueles como-que יִשְׁאַל־ em-palavra-de o-Elohim assim todo עֲצַ֣ת אֲחִיתֹ֔פֶל também para-David também לְאַבְשָׁלֹֽם׃');
INSERT INTO chapters VALUES (284, 10, 17, 29);
INSERT INTO verses VALUES (8453, 10, 17, 1, 'E-disse אֲחִיתֹ֖פֶל a [אֶבְחֲרָ֣ה] [נָּ֗א] por-favor doze dez mil homem [אַחֲרֵי־דָוִ֖ד] a-noite Davi a-noite');
INSERT INTO verses VALUES (8454, 10, 17, 2, '[וְאָב֣וֹא] sobre-ele e-ele [יָגֵ֙עַ֙] [וּרְפֵ֣ה] mãos [וְהַֽחֲרַדְתִּ֣י] ele [וְנָ֖ס] todo o-povo que com-ele sozinho a o-rei para-ele-somente');
INSERT INTO verses VALUES (8455, 10, 17, 3, '[וְאָשִׁ֥יבָה] todo o-povo a-ti [הַכֹּ֔ל] o todo o-homem tu tu [כָּל־הָעָ֖ם] será o-povo será paz');
INSERT INTO verses VALUES (8456, 10, 17, 4, 'e-ele-dispos a palavra aos-olhos-de [אַבְשָׁלֹ֑ם] e-em-olhos-de todo anciãos-de Israel');
INSERT INTO verses VALUES (8457, 10, 17, 5, 'E-disse Absalão chamou por-favor também [לְחוּשַׁ֣י] [הָאַרְכִּ֑י] [וְנִשְׁמְעָ֥ה] que [גַּם־הֽוּא] também ela');
INSERT INTO verses VALUES (8458, 10, 17, 6, 'E-veio [חוּשַׁי֮] a E-disse E-disse a-ele dizendo dizendo como-palavra o-este palavra [הֲנַעֲשֶׂ֖ה] [אֶת־דְּבָר֑וֹ] a tu se palavra');
INSERT INTO verses VALUES (8459, 10, 17, 7, 'E-disse [חוּשַׁ֖י] a [לֹֽא־טוֹבָ֧ה] não [אֲשֶׁר־יָעַ֥ץ] [אֲחִיתֹ֖פֶל] que [הַזֹּֽאת]');
INSERT INTO verses VALUES (8460, 10, 17, 8, 'E-disse Chusai tu soube a teu pai que seus homens porque גִבֹּרִ֣ים eles e ardentes alma eles como urso destruíram no-campo e teu pai homem guerra e-não יָלִ֖ין a o-povo');
INSERT INTO verses VALUES (8461, 10, 17, 9, 'eis agora ele נֶחְבָּא֙ em-uma-de הַפְּחָתִ֔ים ou em um הַמְּקוֹמֹ֑ת e-foi כִּנְפֹ֤ל neles no-primeiro וְשָׁמַ֤ע הַשֹּׁמֵ֙עַ֙ era foi מַגֵּפָ֔ה בָּעָ֕ם que atrás-de אַבְשָׁלֹֽם׃');
INSERT INTO verses VALUES (8462, 10, 17, 10, 'e-ele também filho-de fortes que seu-lábo como-cão o-leão ele-foi ele-terá-se porque conheceu todo Israel porque gênro pai-teu e-filhos-de valor que com-ele');
INSERT INTO verses VALUES (8463, 10, 17, 11, 'que eu-conselhei-me ele-foi-reunido ele-será-reunido sobre-te todo Israel מִדּוֹן e-até poço sete como-o-campo que sobre o-mar em-abundância וּפָנֶיךָ הֹלְכִים בַּקְרָב׃');
INSERT INTO verses VALUES (8464, 10, 17, 12, 'וּבָ֣אנוּ a-ele הַמְּקוֹמֹת֙ que foi-achado nome e nós sobre-ele como cairá הַטַּ֖ל sobre a-terra-a e-não נ֥וֹתַר nele e-em-todo הָאֲנָשִׁ֥ים que com-ele também um');
INSERT INTO verses VALUES (8465, 10, 17, 13, 'e-se a cidade [כָֽל־יִשְׂרָאֵ֛ל] [אֶל־הָעִ֥יר] todo Israel a ele [עַד־הַנַּ֔חַל] até [אֲשֶֽׁר־לֹא־נִמְצָ֥א] ele até até que não nome também');
INSERT INTO verses VALUES (8466, 10, 17, 14, 'E-disse Absalão e-todo homem Israel [עֲצַת֙] [חוּשַׁ֣י] [הָאַרְכִּ֔י] [מֵעֲצַ֖ת] [אֲחִיתֹ֑פֶל] [וַיהוָ֣ה] [צִוָּ֗ה] [לְהָפֵ֞ר] [אֶת־עֲצַ֤ת] a [הַטּוֹבָ֔ה] [לְבַעֲב֗וּר] a-boa yhwh [אֶל־אַבְשָׁל֖וֹם] yhwh a a');
INSERT INTO verses VALUES (8467, 10, 17, 15, 'E-disse [חוּשַׁ֗י] a [וְאֶל־אֶבְיָתָר֙] e-a [כָּזֹ֣את] os-sacerdotes [יָעַ֤ץ] [אֲחִיתֹ֙פֶל֙] [אֶת־אַבְשָׁלֹ֔ם] e-[OBJ] a [יִשְׂרָאֵ֑ל] e-[OBJ] [וְכָזֹ֖את] Israel [אָֽנִי]');
INSERT INTO verses VALUES (8468, 10, 17, 16, 'e-agora שִׁלְח֣וּ מְהֵרָה֩ וְהַגִּ֨ידוּ לְדָוִ֜ד dizendo a תָּ֤לֶן a-noite nas-areias o-deserto e-também עָבֹר para-que-não para que יְבוּלַע para-o-rei e-para-todo- o-povo que com-ele');
INSERT INTO verses VALUES (8469, 10, 17, 17, 'וִיהוֹנָתָן וַאֲחִימַעַץ estão-stando בְּעֵין- רֹגֵל וְהָלְכָה הַשִׁפְחָה֙ a-eles a-eles e-eles e-eles-irão וְהִגִּידוּ para-o-rei que não não יוּכְלוּ para mostrar para-vir a cidade:');
INSERT INTO verses VALUES (8470, 10, 17, 18, 'E-viu eles jovem e-anunciou לְאַבְשָׁלֹ֑ם e eles foram os dois מהרה e chegaram a casa-de homem com jovens e para ele em poço no-limiar e-desceram nome');
INSERT INTO verses VALUES (8471, 10, 17, 19, 'e-tomou a-mulher e-estendeu-se-a a o-covcho sobre face-de הַבְּאֵ֔ר e-prostrou-se-a sobre-ele as-escadas e-não quem palavra');
INSERT INTO verses VALUES (8472, 10, 17, 20, 'e-vieram servos Absalão a a mulher a-casa e-disseram onde Achimaats E-disse a-eles para-eles a-mulher atravessaram as-águas as-águas e-buscaram e-não encontraram e-eles-retornaram Jerusalém');
INSERT INTO verses VALUES (8473, 10, 17, 21, 'e-houve depois-de para-lhes e-eles-subiram do-pirâmide Va''yalku e-contaram para-o-rei Davi e-disseram a Davi levantai-vos e-corram depressa a as-águas porque assim יָעַ֥ץ sobre-vós Achitofel:');
INSERT INTO verses VALUES (8474, 10, 17, 22, 'E-levantou Davi e-todo o-povo que com-ele [אֶת־הַיַּרְדֵּ֑ן] a o Jordão até não [נֶעְדָּ֔ר] até um não que não a');
INSERT INTO verses VALUES (8475, 10, 17, 23, 'e-Achitofel ver que não foi feita sua conselheira [וַיַּחֲבֹ֣שׁ] a o burro E-levantou E-andou a E-ordenou a seu e ordenou a casa-dele seu-pai E-morreu e-ele-foi-sepultado no sepulcro seu-pai');
INSERT INTO verses VALUES (8476, 10, 17, 24, 'e-David veio acampada e Absalão passou a ele ele e-todo homem Israel com-ele');
INSERT INTO verses VALUES (8477, 10, 17, 25, 'e-[OBJ] [שָׂ֧ם] nome debaixo debaixo-de יוֹאָב sobre o-exército [וּשְׁמוֹ֙] filho-de homem [אֲשֶׁר־בָּא֙] [אֶל־אֲבִיגַ֣ל] [בַּת־נָחָ֔שׁ] que veio mãe [יוֹאָֽב] mãe');
INSERT INTO verses VALUES (8478, 10, 17, 26, '[וַיִּ֤חַן] Israel [וְאַבְשָׁלֹ֔ם] terra o-Gileade');
INSERT INTO verses VALUES (8479, 10, 17, 27, 'e-houve [כְּב֥וֹא] Davi [מַחֲנָ֑יְמָה] [וְשֹׁבִ֨י] filho-de [מֵרַבַּ֣ת] [בְּנֵֽי־עַמּ֗וֹן] filhos-de [בֶּן־עַמִּיאֵל֙] [מִלֹּ֣א] filho-de [וּבַרְזִלַּ֥י] enchei palavra');
INSERT INTO verses VALUES (8480, 10, 17, 28, 'מִשְׁכָּ֤ב וְסַפּוֹת֙ e-utensílios criador e-trigo e-cascas e-massa e-fermento e-pó e-acasalamentos e-fermento;');
INSERT INTO verses VALUES (8481, 10, 17, 29, 'e-mel e cera e ovelhas e bocas manhã e trouxeram para-David e ao povo que com-ele que porque disseram o-povo fome e cansado e sede no-deserto');
INSERT INTO chapters VALUES (285, 10, 18, 32);
INSERT INTO verses VALUES (8482, 10, 18, 1, 'e-ele-contou Davi a o-povo que com-ele e-colocou sobre-eles príncipes-de dois-mil e-príncipes-de centenas');
INSERT INTO verses VALUES (8483, 10, 18, 2, 'e enviou Davi a o povo a-terceira por-mão-de Joabe e a terceira MANUAL AVISAI filho-de ZERUIA Ai יוֹאָב E HÁSHALISHÍT em-mão E-disse HAGGITI E-disse o rei a o-povo SAIR EU SAI também eu com-vos');
INSERT INTO verses VALUES (8484, 10, 18, 3, 'E-disse o-povo não ELA SAIRÁ que se NOS NÓS não yasum para-nós coração e-se yamatu chetziynu não yasum elaynu coração e-agora bom kamenu עֲשָׂרָ֣ה milhares e-agora bom porque tihiye para-nos me''ir');
INSERT INTO verses VALUES (8485, 10, 18, 4, 'E-disse a-eles o-rei que seja-bom be''eyneichem e''asah WAYYAA''MOD o rei a mão o-portão e-todo o-povo saíram לְמֵא֖וֹת וְלַאֲלָפִֽים׃');
INSERT INTO verses VALUES (8486, 10, 18, 5, 'E-ordenou o-rei a [וְאֶת־אֲבִישַׁ֤י] e-[OBJ] dizendo e-[OBJ] [לַנַּ֣עַר] dizendo [וְכָל־הָעָ֣ם] a-mim [בְּצַוֺּ֥ת] [הַמֶּ֛לֶךְ] e-todo o-povo [אַבְשָׁלֽוֹם] a todo sobre palavra');
INSERT INTO verses VALUES (8487, 10, 18, 6, 'e-ele-saiu o-povo o-campo ao-encontro-de Israel e-foi ha-milchamah בְּיַ֥ער Efrayim');
INSERT INTO verses VALUES (8488, 10, 18, 7, 'וַיִּנָּ֤גְפוּ nome povo Israel diante-de servos-de Davi e-ela-tornou-se nome a maggáfa no-dia no-dia o-aquele vinte mil');
INSERT INTO verses VALUES (8489, 10, 18, 8, 'e-ela-tornou-se nome a-guerra sobre face-de todo a-terra e verrou o ayár para-comer no-povo do-que a-espada no-dia no-dia a-aquela');
INSERT INTO verses VALUES (8490, 10, 18, 9, 'E-chamou Absalão diante-de servos-de Davi e abshalóm rocheb sobre a pered E-veio debaixo em-lugar-de sobékh a eláh a gódolah e hacházak seu rosh בָאֵלָ֗ה entre entre e-entre a-terra a-terra וְהַפּ֥רֶד que em-lugar-dele עָבָֽר׃');
INSERT INTO verses VALUES (8491, 10, 18, 10, 'E-viu homem um [וַיַּגֵּ֖ד] [לְיוֹאָ֑ב] E-disse eis vi a [תָּל֖וּי] [בָּאֵלָֽה]');
INSERT INTO verses VALUES (8492, 10, 18, 11, 'E-disse Joabe para-o-homem o-que-conta a-ele e-eis viste וּמַדּ֛וּעַ não הִכִּית֥וֹ nome terra וְעָלַ֗י a-ti a-ti dez prata e-cangaça uma');
INSERT INTO verses VALUES (8493, 10, 18, 12, 'E-disse o-homem a Joabe eu eu sobre as-mãos mil prata não lançarei minha-mão que filho-de o-rei porque em-nossos-ouvidos ordenou o-rei dizendo e-a Avissai e-a com-mim para-dizer guardem- quem no-negro בְּאַבְשָׁלֽוֹם׃');
INSERT INTO verses VALUES (8494, 10, 18, 13, 'ou asiti mentira e-todo palavra não יִכָּחֵ֣ד de o-rei e-tu תִּתְיַצֵּ֥ב מִנֶּֽגֶד׃');
INSERT INTO verses VALUES (8495, 10, 18, 14, 'E-disse Joabe não assim אֹחִ֣ילָה E-tomou E-tomou שְׁלֹשָׁ֨ה שְׁבָטִ֜ים בְּכַפּ֗וֹ וַיִּתְקָעֵם֙ בְּלֵ֣ב Absalão vida viveu no-lado o-Elohim:');
INSERT INTO verses VALUES (8496, 10, 18, 15, 'e-viraram-se-para עֲשָׂרָ֣ה os-jovens carregadores-de utensílios-de Joabe e-eles-feriram a Absalão e-deram-lhe-morte:');
INSERT INTO verses VALUES (8497, 10, 18, 16, 'e-tocou Joabe com-a-saxa e-estabeleceu-se o-povo perseguição depois-de Israel porque escuridão יוֹאָב a o-povo');
INSERT INTO verses VALUES (8498, 10, 18, 17, 'e-eles-tomaram a אבשלום ele a-ele no-mato a a-baixa a-grande e-estabeleceram sobre-ele muito אֲבָנִ֖ים grande muito e-todo Israel levantaram-se homem');
INSERT INTO verses VALUES (8499, 10, 18, 18, 'e-Absalão tomou e-estabeleceu- para-ele a má-staiva que em-valley- que disse disse não-há a-mim filho por-causa-de E-chamou meu-nome E-chamou para-má-staiva sobre seu-nome E-chamou até o-dia Absalão até o-dia a-esta');
INSERT INTO verses VALUES (8500, 10, 18, 19, 'e-Achimaats filho-de disse disse caminho נָא וַאֲבַשְּׂרָה a yhwh porque שְׁפָט֥וֹ yhwh de-mão-de oyevav');
INSERT INTO verses VALUES (8501, 10, 18, 20, 'E-disse a-ele Joabe não homem בְּשֹׂרָ֤ה tu o-dia esta וּבִשַּׂרְתָּ֖ em-dia-de outro וְהַיּ֤וֹם o-este não תְבַשֵּׂ֔ר porque filho-de o-rei morreu');
INSERT INTO verses VALUES (8502, 10, 18, 21, 'E-disse Joabe לַכּוּשִׁ֔י vai הַגֵּ֥ד ao-rei que רָאִ֑יתָה e-ele-se-prostrou Cushi a Joabe e correu:');
INSERT INTO verses VALUES (8503, 10, 18, 22, 'e-continuou ainda Acimaus filho-de E-disse E-disse e-seja יוֹאָב E-foi o que corremos- nā'' E-disse אני֖ depois-de tu E-disse Joabe por que- isto tu correu filhos-de e caia não-há com a trombeta Saiu:');
INSERT INTO verses VALUES (8504, 10, 18, 23, 'וִיהִי־ que E-disse a-ele a-ele -Rouç e-correu o-caminho-de caminho ה-кїкїр e-atravessou a -Cushi:');
INSERT INTO verses VALUES (8505, 10, 18, 24, '-e Davi habitante entre segundo -as Portas E-andou -a Vigia a -Telhado o-sha-ur a E-viu va-yiss-a a sozinho E-viu e-eis homem -Correu sozinho');
INSERT INTO verses VALUES (8506, 10, 18, 25, 'E-chamou הַצֹּפֶה֙ -E contou para-o-rei E-disse o-rei se -apenas a ele בְּשׂוֹרָ֣ה em-boca-sua E-andou indo וְקָרֵֽב׃');
INSERT INTO verses VALUES (8507, 10, 18, 26, 'E-viu [הַצֹּפֶה֮] homem-de [רָץ֒] E-chamou E-chamou [אֶל־הַשֹּׁ֔[c]עֵ֔ר] E-disse E-disse eis-que- sozinho E-disse sozinho-dele E-disse o-rei também');
INSERT INTO verses VALUES (8508, 10, 18, 27, 'E-disse הַצֹּפֶ֔ה eu viu a מְרוּצַ֣ת harishon כִּמְרּูצַ֖ת אֲחִימַ֣עַץ E-disse צָד֑וֹק E-disse o-rei homem-de bom este e-a בְּשׂוֹרָ֥ה bem yhwh');
INSERT INTO verses VALUES (8509, 10, 18, 28, 'E-chamou אֲחִימַ֗עַץ E-disse a o-rei paz e-ele-se-prostrou para-o-rei לְאַפָּ֖יו terra E-disse בָּרוּךְ֙ yhwh teu-Elohim que סִגַּר֙ a os-homens que נָשְׂא֥וּ a mão-deles בַּֽאדֹנִ֥י o rei');
INSERT INTO verses VALUES (8510, 10, 18, 29, 'E-disse o-rei shalom לַנַּ֖עַר לְאַבְשָׁל֑וֹם E-disse אֲחִימַ֡עַץ eu-vei הֶהָמ֨וֹן o-grande לִ֠שְׁלֹחַ a servo o-rei Joabe e-a עַבְדֶּ֔ךָ e-não conheci מָֽה׃');
INSERT INTO verses VALUES (8511, 10, 18, 30, 'E-disse o-rei rodear הִתְיַצֵּ֣ב כֹּ֑ה [וַיִּסֹּ֖ב] וַיַּעֲמֹד');
INSERT INTO verses VALUES (8512, 10, 18, 31, 'e-eis [הַכּוּשִׁ֖י] veio E-disse [הַכּוּשִׁ֗י] [יִתְבַּשֵּׂר֙] Adonai o-rei porque yhwh o-dia o-dia de-mão-de todo');
INSERT INTO verses VALUES (8513, 10, 18, 32, 'E-disse o rei a o Cushite hashalom para o jovem E-disse E-disse o Cushite serao como um jovem os inimigos de Adonai e-tudo e-todo que levantaram-se sobre-ti lerâah');
INSERT INTO chapters VALUES (286, 10, 19, 44);
INSERT INTO verses VALUES (8514, 10, 19, 1, 'e se assustou o rei e-subiu sobre câmara-alta-de hasha''ar e chorou assim, pois disse em sua marcha filhos-de Absalão filhos-de filhos-de Absalão quem dará מֵתִ֙י eu תַּחְתֹּ֥ךָ אַבְשָׁלוֹם filhos-de filhos-de');
INSERT INTO verses VALUES (8515, 10, 19, 2, '[וַיֻּגַּ֖ד] [לְיוֹאָ֑ב] eis o-rei [בֹּכֶ֛ה] [וַיִּתְאַבֵּ֖ל] sobre');
INSERT INTO verses VALUES (8516, 10, 19, 3, 'e-foi הַתְּשׁוּעָה no-dia aquele לְאֵבֶל para-todo o-povo porque no-dia o povo dizendo o-aquele dizendo נִעֲצַב o-rei sobre filho-seu');
INSERT INTO verses VALUES (8517, 10, 19, 4, 'e-o-roubo o-povo no-dia o-aquele para-vir a-cidade como-que o-roubo o-povo os-enganados seus-enganos na-guerra');
INSERT INTO verses VALUES (8518, 10, 19, 5, 'e-o-rei a-paz a rosto-dele e clamou voz voz-de grande filhos-de Absalão absalão filhos-de filhos-de');
INSERT INTO verses VALUES (8519, 10, 19, 6, 'E-veio Joab a o-rei E-disse E-disse o-dia o-hoje a face-de todo o-dia os-que-fugiram a a-tua-alma o-dia e-a alma filhos-teus e-filhas-tuas e-alma as-tuas-mulheres e alma teu desejo');
INSERT INTO verses VALUES (8520, 10, 19, 7, 'de amor a que te odeia e te odeia que que te ama que o-dia que porque a-ti para-ti príncipes que que eu-sei o-dia que אַבְשָׁלוֹם viveu e todos nós vida morremos o-dia entao retido em-olhos-teus');
INSERT INTO verses VALUES (8521, 10, 19, 8, 'e-agora levantou sai וְדַבֵּ֖ר sobre coração que porque בַיהוָ֨ה נִשְׁבַּ֜עְתִּי porque einakha- יוֹצֵ֗א se יָלִ֨ין homem a-ti esta וְרָעָ֧ה para-ti esta de-todo o-mal que veio sobre-ti מִנְּעֻרֶ֖יךָ até agora');
INSERT INTO verses VALUES (8522, 10, 19, 9, 'E-levantou o-rei e-sentou [בַּשָּׁ֑עַר] e-para-todo o-povo dizendo eis eis o rei habitante-de [וַיָּבֹ֤א] E-veio todo o-povo diante-de o-rei [אִ֥ישׁ] [לְאֹהָלָֽיו׃] homem');
INSERT INTO verses VALUES (8523, 10, 19, 10, 'e-houve todo o-povo נָד֔וֹן em-todo dizendo Israel dizendo o-rei הִצִּילָ֣נוּ da-palma אֹיְבֵ֗ינוּ e-ele מִלְּטָ֙נוּ֙ da-palma e-agora e-agora בָּרַ֥ח de-cima-de a-terra de-sobre אַבְשָׁלוֹם');
INSERT INTO verses VALUES (8524, 10, 19, 11, 'וְאַבְשָׁלוֹם֙ que מָשַׁ֣חְנוּ sobre-nós morreu בַּמִּלְחָמָ֑ה e-agora לָמָ֥ה vós מחרשים para-responder a o rei');
INSERT INTO verses VALUES (8525, 10, 19, 12, 'e-o-rei Davi enviou a Tsadoq e-a dizendo הכהנים dizendo דברו dizendo זקנים Judá dizendo por-que תהייתם אחרונים para-responder a o-rei a casa-dele ודבר todo Israel veio a o-rei a casa-dele');
INSERT INTO verses VALUES (8526, 10, 19, 13, 'irmãos-meus vós meu-próprio e-meu-corpo vós ואלמה תהייתם אחרונים para-responder a o rei');
INSERT INTO verses VALUES (8527, 10, 19, 14, 'e-para-a-amássā'' dizei acaso-nao meu-próprio e-meu-corpo tu assim fará- para-mim Elohim e-assim acrescentará se não príncipe-de exército debaixo ante-mim todo os-dias debaixo-de Joabe');
INSERT INTO verses VALUES (8528, 10, 19, 15, 'e-estendeu a coração todo um Judá כְּאִ֣ישׁ um tu a o-rei volta tu e-todo servos-teus');
INSERT INTO verses VALUES (8529, 10, 19, 16, 'e-estabeleceu-se o-rei E-veio até o Jordão e-Judá veio a-Gilgal para-andar ao-encontro-de o-rei para-transpor a o-rei a o-Jordão');
INSERT INTO verses VALUES (8530, 10, 19, 17, 'e se apressou Simei filho-de gera filho-de o-benjaminita que dos jovens e desceu com homem Judá para-encontro-de o-rei Davi');
INSERT INTO verses VALUES (8531, 10, 19, 18, 'e mil homem com ele dos filhos de Benjamim e o exército jovem casa e cinco dez os-filhos-dele e-vinte servos-dele com-ele e prosperaram o Jordão diante-de o rei');
INSERT INTO verses VALUES (8532, 10, 19, 19, 'וְעָבְרָ֣ה הָעֲבָרָ֗ה לַֽעֲבִיר֙ a casa o-rei e-para-fazer o-bom e-שִׁמְעִי filho-de גֵּרָ֗א cair diante-de o-rei בְּעָבְר֖וֹ no-Jordão');
INSERT INTO verses VALUES (8533, 10, 19, 20, 'E-disse a o rei a [עָוֺן֒] a-mim Adonai [אֲשֶׁ֣ר] e-a [עַבְדְּךָ֔] no-dia que [אֲדֹנִֽי־הַמֶּ֖לֶךְ] teu-servo [לָשׂ֥וּם] que adonai-meu a');
INSERT INTO verses VALUES (8534, 10, 19, 21, 'que saber teu-servo que eu [חָטָ֑אתִי] [וְהִנֵּֽה־בָ֣אתִי] o-dia o-dia [לְכָל־בֵּ֣ית] para-todo casa José [Adonai] para-encontro-de Adonai');
INSERT INTO verses VALUES (8535, 10, 19, 22, 'e-ele-respondeu [אֲבִישַׁ֤י] filho-de E-disse E-disse esta não não será-morto que porque [אֶת־מְשִׁ֥יחַ] yhwh yhwh');
INSERT INTO verses VALUES (8536, 10, 19, 23, 'E-disse Davi que para-mim [בְּנֵ֣י] filhos-de Zeruiah o-dia [לְשָׂטָ֑ן] o-dia o-dia [אִישׁ֙] o-dia que homem em-Israel que o-dia soube porque rei sobre Israel');
INSERT INTO verses VALUES (8537, 10, 19, 24, 'E-disse o-rei a não não [וַיִּשָּׁ֥בַֽע] a-ele a-ele');
INSERT INTO verses VALUES (8538, 10, 19, 25, 'וּמְפִבֹ֙שֶׁת֙ filho-de Shaul desceu ao-encontro-de o-rei e-não fez רַגְלָ֜יו e-não não שְׂפָמ֗וֹ e-a בְּגָדָיו֙ não כִבֵּ֔ס desde o-dia לֶ֣כֶת o-rei até o-dia que veio em paz');
INSERT INTO verses VALUES (8539, 10, 19, 26, 'e-houve porque veio Jerusalém ao-encontro-de E-disse a-ele a-ele o-rei por-que não andaste com-mim Mefiboshet');
INSERT INTO verses VALUES (8540, 10, 19, 27, 'E-disse Adonai o-rei servo-meu רִמָּ֑נִי porque disse servo-teu אֶחְבְּשָׁה־ לִּי֩ הַחֲמ֨וֹר וְאֶרְכַּ֤ב sobre-ela que a o-rei porque pisque servo-teu');
INSERT INTO verses VALUES (8541, 10, 19, 28, 'וַיְרַגֵּ֣ל בְּעַבְדְּךָ֔ a Adonai o-rei וַאדֹנִ֤י o-rei כְּמַלְאַ֣ךְ o-Elohim וַעֲשֵׂ֥ה o-bom em-olhos-teus');
INSERT INTO verses VALUES (8542, 10, 19, 29, 'que não ser todo casa que porque se ANASH''E- morte לַאדֹנִ֣י o-rei וַתָּ֙שֶׁת֙ a teu-servo בְּאֹכְלֵ֖י mesa-tua e-que há- para-mim ainda צְדָקָ֔ה e-para-chamar a-ele a o rei');
INSERT INTO verses VALUES (8543, 10, 19, 30, 'E-disse a-ele o-rei por-que fale ainda as-tuas-palavras eu-disse-que tu e-exército vós-dividais a o-campo');
INSERT INTO verses VALUES (8544, 10, 19, 31, 'E-disse a-escarnecida a também também a o todo tomar-ah depois-de que veio Adonai o-rei em-paz a casa-dele');
INSERT INTO verses VALUES (8545, 10, 19, 32, 'וּבַרְזִלַּי֙ o-gileadi desceu dos-mergos e-ele-passou a o rei o-Jordão para-o-lance-lo a');
INSERT INTO verses VALUES (8546, 10, 19, 33, 'e-barzilai velho muito filho-de o-ochenta ano e-ele ciclo a o rei em-suas-viagens ele muito homem grande ele muito');
INSERT INTO verses VALUES (8547, 10, 19, 34, 'E-disse o-rei a tu tu עֲבֹ֣ר comigo e-cicletei comigo com-mim em-Jerusalém');
INSERT INTO verses VALUES (8548, 10, 19, 35, 'E-disse e-barzilai a o-rei dias-de os-dias segundo minha-vida porque eu-elevarei a o-rei Jerusalém');
INSERT INTO verses VALUES (8549, 10, 19, 36, 'filho-de oitenta eu o-dia o-hoje o saber entre bom para o mal se provará teu-servo a que comerá e-a que beberá se escutarei será pelo som cabras e cabras e por que será avadcha ainda para a satisfação a Adonai o rei');
INSERT INTO verses VALUES (8550, 10, 19, 37, 'כִּמְעַ֞ט יַעֲבֹ֧ר servo-teu a o Jordão a o-rei e-por-que יגמלני o-rei הַגְּמוּלָ֖ה a esta');
INSERT INTO verses VALUES (8551, 10, 19, 38, 'יָֽשָׁב־ por-favor teu-servo וְאָמֻ֣ת בְּעִירִ֔י povo קֶ֥בֶר pai-meu וְאִמִּ֑י והנהviderha seu-escravo-teu-servo כִמְהָ֗ם יַֽעֲבֹר֙ com Adonai o-rei e-faze- ל֕וֹ a que bom em-olhos-teus');
INSERT INTO verses VALUES (8552, 10, 19, 39, 'E-disse o rei אִתִּי֙ passar como-eles e-eu farei- a-ele a e-tudo em-olhos-teus e-todo que e-escolherá sobre-mim farei para-ti');
INSERT INTO verses VALUES (8553, 10, 19, 40, 'e-passou todo o-povo a o Jordão e-o-rei passar e-berrou o-rei a-Berzilai e-bençoe-o E-tomou para-lugar-dele');
INSERT INTO verses VALUES (8554, 10, 19, 41, 'e-ele-passou o-rei a-Gilgalá e-como-eles passou com-ele e-todo povo Judá a o-rei e-também metade povo Israel');
INSERT INTO verses VALUES (8555, 10, 19, 42, 'e-eis todo homem Israel Ba''îm a o- rei e-disseram a o-rei por-que גְּנָב֨וּךָ אַחֵ֜ינוּ homem Judá וַיַּעֲבִ֨רוּ a o-rei e-a sua-casa a o-Jordão e-todo homens-de Davi com-ele');
INSERT INTO verses VALUES (8556, 10, 19, 43, 'e-ele-respondeu todo homem Judá sobre homem Israel porque קָר֤וֹב o-rei a-mim a-ti isto acendeu-se a-ti sobre a palavra este הֶאָכ֤וֹל אָכַ֙לְנוּ֙ de o-rei se נִשֵּׂ֥את נִשָּׂ֖א para-nós');
INSERT INTO verses VALUES (8557, 10, 19, 44, 'e-respondeu homem-de Israel a E-disse Judá E-disse עֶֽשֶׂר־ יָד֨וֹת para-mim no rei e-também em Davi eu de ti וּמַדּ֙וּעַ֙ exalte-me e-não foi minha palavra primeiro a-mim LÉHĀŠÍV a meu-rei e buscou palavra-de homem Judá no deserto homem Israel');
INSERT INTO chapters VALUES (287, 10, 20, 26);
INSERT INTO verses VALUES (8558, 10, 20, 1, 'e ali foi chamado homem בלייעל ושמו sete filho-de בכרי homem da-minha-direita WAYYITQAA E-disse E-disse não-há para-nos חלק בדוד e-não נחלה- a-nós no filho de ישאי homem לאוהלויהו Israel');
INSERT INTO verses VALUES (8559, 10, 20, 2, 'e-ele-subiu todo homem Israel de-depois-de Davi depois-de sete filho-de בכרי e-homem Judá דָּבְק֣וּ בְמַלְכָּ֔ם de o Jordão e-até Jerusalém');
INSERT INTO verses VALUES (8560, 10, 20, 3, 'E-veio Davi a בֵּיתוֹ֮ E-tomou E-tomou o-rei a עֶֽשֶׂר־ נָשִׁ֣ים ׀ פִּלַגְשִׁ֡ים que הִנִּיחַ֩ para-guardar a-casa וַֽיִּתְּנֵ֤ם casa-de guarda-de וַֽיְכַלְכְּלֵ֔ם וַאֲלֵיהֶ֖ם não veio vai ter sido enroladas até dia em nós viuvez vida:');
INSERT INTO verses VALUES (8561, 10, 20, 4, 'E-disse o-rei a Amasa grite- para-mim a homem-de Judá três-de dias e-tu poh ficou-em-pé');
INSERT INTO verses VALUES (8562, 10, 20, 5, 'E-andou amasa para gritar a Judá de o convocado que convocou-o:');
INSERT INTO verses VALUES (8563, 10, 20, 6, 'E-disse Davi a Abisai agora יֵרַע nós sete filho-de tu de אַבְשָׁל֑וֹם אַתָּה קַח a servos-de a-ele וּרְדֹף apos-ele para-que-não מָצָא para-ele cidades בְּצֻר֖וֹת וְהִצִּ֥יל עֵינֵֽנוּ׃');
INSERT INTO verses VALUES (8564, 10, 20, 7, 'e-eles-saíram atrás-dele homens-de Joabe וְהַכְּרֵתִ֥י e a faltei e-todo os giborim e-saíram de-Jerusalém para raf depois-de sete filho-de no cheri:');
INSERT INTO verses VALUES (8565, 10, 20, 8, 'eles com a eben a g''dolah que em Gib''at-on e Amasa veio diante-deles e Yoav carrado de-seu vestuário cinto espada espada sobre suas coxas em sua face e-ele sair e caiu:');
INSERT INTO verses VALUES (8566, 10, 20, 9, 'E-disse Joabe para Amasa hashalom tu meu irmão e agarrou-se a mão-de יְמִ֥ין Joab pelo cabelo de Amasa para o nascimento a-ele');
INSERT INTO verses VALUES (8567, 10, 20, 10, 'e-a não foi-guardado com-espada que pela-mão-de Joabe e-o-cacou-lhe n-a a o-quinto e-o-espalhou dos-seus-entresossos a-ele e-não ano a-ele E-morreu e-Joabe e-Abisai irmão-seu perseguio depois-de sete filho-de בִּכְרִֽי׃');
INSERT INTO verses VALUES (8568, 10, 20, 11, 'e-homem ficou-em-pé sobre-ele מִֽנַּעֲרֵ֖י Joabe E-disse quem que חָפֵ֧ץ בְּיוֹאָ֛ב e-quem que para-David depois-de יוֹאָֽב׃');
INSERT INTO verses VALUES (8569, 10, 20, 12, '[וַעֲמָשָׂ֛א] [מִתְגֹּלֵ֥ל] [בַּדָּ֖ם] no-meio-de [הַֽמְסִּלָּ֑ה] E-viu [הָאִ֜ישׁ] porque ficou-em-pé todo o-povo [מִן־הַֽמְסִלָּ֤ה] a [וַיַּשְׁלֵ֤ךְ] de [בֶּ֔גֶד] [כַּאֲשֶׁ֣ר] ver sobre-ele [עָלָ֖יו] como viu todo');
INSERT INTO verses VALUES (8570, 10, 20, 13, 'como [הֹגָ֖ה] de [עָבַ֤ר] [כָּל־אִישׁ֙] todo homem depois-de [אַחֲרֵ֖י] [שֶׁ֥בַע] depois-de sete filho-de');
INSERT INTO verses VALUES (8571, 10, 20, 14, 'e passou em-todo tribos-de Israel avela e-casa-de מַעֲכָ֖ה e-todo os valeres e-vieram também atrás-dele');
INSERT INTO verses VALUES (8572, 10, 20, 15, 'e-vieram e fizeram-se sobre-ele em avela casa a calamidade [וַיִּשְׁפְּכ֤וּ] sela a a-cidade e-ela-ficou-em-pé no chelo e-todo o-povo que a Joabe destruidores para derrubar a muralha:');
INSERT INTO verses VALUES (8573, 10, 20, 16, 'e chamou mulher sabedoria de a-cidade ouvi ouvireis dizei por-favor a Joabe se aproximaram até elas e-eu-falarei para-ti');
INSERT INTO verses VALUES (8574, 10, 20, 17, 'e se aproximaram a ela E-disse a-mulher és-tu יוֹאָב E-disse eu E-disse a-ele ouviu palavras-de serva-tua E-disse ouviu eu');
INSERT INTO verses VALUES (8575, 10, 20, 18, 'E-disse dizendo palavra e falariam no princípio dizendo Sheol Sheol em-abel e-assim e consumiram');
INSERT INTO verses VALUES (8576, 10, 20, 19, 'eu shlumei emuney Israel tu buscando para matar cidade e-êm em-Israel por-que engolirá נַחֲלַ֥ת yhwh');
INSERT INTO verses VALUES (8577, 10, 20, 20, 'e-respondeu [יוֹאָ֖ב] E-disse [חָלִ֤ילָה] [חָלִ֙ילָה֙] a-mim se [וְאִם־אַשְׁחִֽית]');
INSERT INTO verses VALUES (8578, 10, 20, 21, 'não assim que porque homem מהר אֶפְרַ֜יִם sete filho-de בקורי sua-mão נשא mão-dele במלך sozinho תנו־ de-cima-de para-somente-dele E-disse de-sobre a-cidade eis a-mulher a Joabe eis cabeça-sua משלח a-ti por-causa-de החומה׃');
INSERT INTO verses VALUES (8579, 10, 20, 22, 'e veio a-mulher a todo o-povo por-sua-sabedoria e cortaram a cabeça sete filho-de [בַּשּׁוֹפָ֔ר] [וַיָּפֻ֥צוּ] a Joabe e-blastou em-o chifre [שָׁ֥ב] de-em-cima-de a-cidade homem [sem-traducao] e-Joabe retornou Jerusalém a o rei');
INSERT INTO verses VALUES (8580, 10, 20, 23, 'וְיוֹאָ֕ב a todo o-exército Israel [בֶּן־יְה֣וֹיָדָ֔ע] filho-de Joiada sobre e-sobre הפלטי׃');
INSERT INTO verses VALUES (8581, 10, 20, 24, 'ואדורם sobre הַמָּס viyohoshaphat filho-de achilud o-mencionador-versículo');
INSERT INTO verses VALUES (8582, 10, 20, 25, 'סֹפֵר e-Sadoque e-Abiatar sacerdotes-versículo');
INSERT INTO verses VALUES (8583, 10, 20, 26, 'e-também עִירָא הַיָּאִרִי ser sacerdote de-Davi');
INSERT INTO chapters VALUES (288, 10, 21, 22);
INSERT INTO verses VALUES (8584, 10, 21, 1, 'e-houve [רָעָב֩] [בִּימֵ֨י] Davi três dois ano depois-de ano [וַיְבַקֵּ֥שׁ] Davi a yhwh yhwh E-disse yhwh a Saul e-a casa [אֶת־הַגִּבְעֹנִֽים] sobre que a');
INSERT INTO verses VALUES (8585, 10, 21, 2, 'E-chamou o-rei לַגּוֹבְעֹנִים E-disse a-eles וְהַגּוֹבְעֹנִים não filhos Israel eles que se de-restante-de o-amorreu e-filhos-de Israel a-eles a-eles e buscou Saul para matá-los por causa dele filhos-de Israel e-Judá');
INSERT INTO verses VALUES (8586, 10, 21, 3, 'E-disse Davi a as Gibeões que a-vós a-vós e no que eu me empenhei וברכו yhwh para-ti yhwh');
INSERT INTO verses VALUES (8587, 10, 21, 4, 'e-disseram a-ele הַגִּבְעֹנִ֗ים não-há prata וזהב com Saul e-com- casa-dele e-nao-ha para-nós homem E-disse em-Israel E-disse que a-vós אומרים אעשה a-vós');
INSERT INTO verses VALUES (8588, 10, 21, 5, 'e-disseram a o-rei o-homem que כלנו ואשר דמייה- para-nós נשמadanu מהתיצב em-todo גבול Israel');
INSERT INTO verses VALUES (8589, 10, 21, 6, 'לָ֜נוּ sete homens מבנותיו והוקענום a-yhwh на горе Saul выбранной yhwh E-disse E-disse eu אֶתְנָה');
INSERT INTO verses VALUES (8590, 10, 21, 7, 'и пощадил o-rei sobre из уст стыда filho-de yhwh filho-de שָׁאוּל entre присяги e-entre que между ними entre Davi e-entre Yehonatan filho-de שָׁאוּל');
INSERT INTO verses VALUES (8591, 10, 21, 8, 'E-tomou o-rei a segundo filhos-de пола filha-de левой que deu-à-luz Саулу a ארמניפי e-a מְפִבֹשֶׁת e-a חֲמֵשֶׁת filhos-de Mical filha-de Shaul que יָלְדָה לְעַדְרִיאֵל filho-de בַּרְזִלַּי הַמְּחֹלָתִי׃');
INSERT INTO verses VALUES (8592, 10, 21, 9, 'וַֽיִּתְּנֵ֞ם na-mão-de הַגִּבְעֹנִ֗ים וַיֹּקִיעֻ֤ם בהר diante-de yhwh וייפלוּ juntamente הומתוּ בימי קָצִיר֙ בראשונים ceifa-de cevada');
INSERT INTO verses VALUES (8593, 10, 21, 10, 'e-tomou רצפה filha-de איה a השק ותטהוּ para-ela a até /mitachat/ קציר até foi-deposto- ave sobre-eles de os-céus e-não deu-a ave noite para-nascer sobre-eles diariamente e-a vivente-de o-campo noite');
INSERT INTO verses VALUES (8594, 10, 21, 11, 'e-ele-foi-dito para-Davi com que fez-a piso filha-de por-que concubina שָׁאוּל');
INSERT INTO verses VALUES (8595, 10, 21, 12, 'E-andou Davi E-tomou a ossos Saul e-a ossos Yehonatan seu-filho de-a בעלים Jabes Galaad eles roubaram -os do vale casa-de Shan que no-dia para matar Philistinos a Saul em Gileade:');
INSERT INTO verses VALUES (8596, 10, 21, 13, 'e-subiu de-lá a suas próprias Saul e-a ossos Yehonatan filho-seu e-reuniram a עצמות הַמּוּקָעִים׃');
INSERT INTO verses VALUES (8597, 10, 21, 14, 'וַיִּקְבְּר֣וּ a suas próprias- Saul וִיהוֹנָֽתָן־ בְּ֠נוֹ בְּאֶ֨רֶץ בִּנְיָמִ֜ן seu-pai בְּקֶ֙בֶר֙ quish pai-dele וַֽיַּעֲשׂ֔וּ todo que ordenou o-rei וַיֵּעָתֵ֧ר Elohim para a terra depois-de assim');
INSERT INTO verses VALUES (8598, 10, 21, 15, 'e-ela-tornou-se ainda em guerra aos filisteus a Israel e-descer Davi e seus servos com-ele e lutaram a Filisteus e voou Davi');
INSERT INTO verses VALUES (8599, 10, 21, 16, '[*וישבו] que nas colinas de da rapa e pesou seu peso três novecentos peso bronze e-ele חָגוּר חֲדָשָה E-disse para-ferir a E-disse');
INSERT INTO verses VALUES (8600, 10, 21, 17, 'וַיַּעֲזָר־ a-ele אֲבִישַׁי filho-de Zeruiah e-feriu a הַפְּלִשְׁתִּי e-matou-o a-ele dizendo homens de Davi a-ele dizendo não sairá ainda com-nos para-a-guerra e-não תְּכַבֶּה a נֵר Israel');
INSERT INTO verses VALUES (8601, 10, 21, 18, 'e-houve depois-de assim e-ela-tornou-se ainda a-guerra בְּגוֹב com filisteus entao הִכָּה סִבְּכַי a minhoca a puro que nas filhas da cura');
INSERT INTO verses VALUES (8602, 10, 21, 19, 'e-ela-tornou-se ainda a-guerra no fundo com filisteus e bateu Eliacãm filho-de nas florestas os carvalhos casa minha pão a גָּלְיָ֣ת הַגִּתִּ֔י וְעֵ֣ץ חֲנִית֔וֹ כּ-מְנ֖וֹר אֹרְגִֽים׃');
INSERT INTO verses VALUES (8603, 10, 21, 20, 'e-ela-tornou-se ainda guerra e-houve e-foi homem e-estubaot as-mãos e-estubaot os-pés seis e-coração vinte e-quatro de-número e-também ele nascido-se para-terapia;');
INSERT INTO verses VALUES (8604, 10, 21, 21, 'וַיְחָרֵ֖ף a Israel וַיַּכֵּ֙הוּ֙ Jonatas filho-de irmão-de Davi');
INSERT INTO verses VALUES (8605, 10, 21, 22, 'a Estas estes nasceram para-terapia בגת וייפלוּ na-mao-de Davi e-na-mão seus-servos');
INSERT INTO chapters VALUES (289, 10, 22, 51);
INSERT INTO verses VALUES (8606, 10, 22, 1, 'e-falou Davi a-yhwh a palavras-de a canção esta em-dia yhwh ele ele da-mão-de todo seus inimigos e a palma da mão שָׁאוּל');
INSERT INTO verses VALUES (8607, 10, 22, 2, 'E-disse yhwh minha pedra e minha fortaleza e meu refúgio— a-mim');
INSERT INTO verses VALUES (8608, 10, 22, 3, 'Elohim-de minha rocha eu confiarei— nele meu escudo e minha coroa ישועי משגבי umanusesi MOSTUI מעCHAMAS TUŠIENI׃');
INSERT INTO verses VALUES (8609, 10, 22, 4, 'MAHULAL e-que-ra yhwh UMEAIVAY AIUSA׃');
INSERT INTO verses VALUES (8610, 10, 22, 5, 'que AFAPUNI מִשְׁבְּרֵי־ morte נַחֲלֵ֥י בְלִיַּ֖עַל יְבַעֲתֻֽנִי׃');
INSERT INTO verses VALUES (8611, 10, 22, 6, 'חֶבְלֵ֥י sepulcro סַבֻּ֑נִי קִדְּמֻ֖נִי מָֽוֶת׃');
INSERT INTO verses VALUES (8612, 10, 22, 7, 'בַּצַּר־ para-mim yhwh yhwh e-a Elohim-meu clamarei E-ouviu מֵהֵֽיכָלוֹ֙ voz-de-mim וְשַׁוְעָתִ֖י em-suas-ouvidos:');
INSERT INTO verses VALUES (8613, 10, 22, 8, 'e-tremeu a-terra suas-fundações a-terra tremem e-torceram-se porque foi-irada a-ele');
INSERT INTO verses VALUES (8614, 10, 22, 9, 'subir fumo em-suas-fúrias e-fogo de-seu-brejo comerás risos de-iradas nós');
INSERT INTO verses VALUES (8615, 10, 22, 10, 'e-virou céus e desceu e arfa debaixo de-seus-pés');
INSERT INTO verses VALUES (8616, 10, 22, 11, 'e se agitaram sobre cérubim e voou E-viu sobre as asas de espírito');
INSERT INTO verses VALUES (8617, 10, 22, 12, 'herdar-os escuridão suas circunvoltações tenda HASHARAT- águas sedas de brilho');
INSERT INTO verses VALUES (8618, 10, 22, 13, 'de-sua diante-de-lho em-ara cavidades-das אֵֽשׁ׃');
INSERT INTO verses VALUES (8619, 10, 22, 14, 'elevou-se de yhwh yhwh e-superior dará sua-voz:');
INSERT INTO verses VALUES (8620, 10, 22, 15, 'e-enviou setas e-lançou-os Barak');
INSERT INTO verses VALUES (8621, 10, 22, 16, 'e-veeram אֲפִיקֵי mar יִגָּלוּ מֹסְד֣וֹת תֵּבֵל בְּגַעֲרַ֣ת yhwh מִנִּשְׁמַ֖ת espírito אַף׃');
INSERT INTO verses VALUES (8622, 10, 22, 17, 'יִשְׁלַ֥ח מִמָּר֖וֹם יִקָּחֵ֑נִי יַֽמְשֵׁ֖נִי de-ma''im muitos');
INSERT INTO verses VALUES (8623, 10, 22, 18, 'salve-me de-oi''vi força de-mi''sone''i que fortaleceram-se de-mim');
INSERT INTO verses VALUES (8624, 10, 22, 19, 'me-antecipem no-dia ida''i e-houve yhwh de-sh''an a-mim');
INSERT INTO verses VALUES (8625, 10, 22, 20, 'e-saiu para-a-mar a-mim resgate-me porque חָ֥פֵֽץ em-mim');
INSERT INTO verses VALUES (8626, 10, 22, 21, 'governem-me yhwh segundo-a-verdade destruição minhas-mãos residirá a-mim');
INSERT INTO verses VALUES (8627, 10, 22, 22, 'que guardara caminhos yhwh e-não fiz-rebeldia de-Eloáhi:');
INSERT INTO verses VALUES (8628, 10, 22, 23, 'que todo para-negdi e-chukkótiav não ásur de-elas');
INSERT INTO verses VALUES (8629, 10, 22, 24, 'e-ehyéh tamíms a-ele e-ash-tammráh de-avóni:');
INSERT INTO verses VALUES (8630, 10, 22, 25, 'e-estabeleceu-se yhwh a-mim como-tsédqáti como-bóri para-em-frente-de os-seus-olhos');
INSERT INTO verses VALUES (8631, 10, 22, 26, 'com [תִּתְחַסָּ֑ד] [עִם־גִּבּ֥וֹר] com [תִּתַּמָּֽם]');
INSERT INTO verses VALUES (8632, 10, 22, 27, 'com [תִּתָּבָ֑ר] [וְעִם־עִקֵּ֖שׁ] [תִּתַּפָּֽל]');
INSERT INTO verses VALUES (8633, 10, 22, 28, 'e-[OBJ] povo [תּוֹשִׁ֑יעַ] [וְעֵינֶ֥יךָ] [עַל־רָמִ֖ים] sobre');
INSERT INTO verses VALUES (8634, 10, 22, 29, 'porque tu yhwh yhwh [יַגִּ֥יהַּ] [חָשְׁכִּֽי]');
INSERT INTO verses VALUES (8635, 10, 22, 30, 'que [בְכָ֖ה] [אָר֣וּץ] [גְּד֑וּד] [בֵּאלֹהַ֖י] [אֲדַלֶּג־שֽׁוּר]');
INSERT INTO verses VALUES (8636, 10, 22, 31, 'o-elohim תָּמִ֣ים caminho dele אִמְרַת yhwh צְרוּפָה escudo-de ele a-todo הַחֹסִ֥ים nele');
INSERT INTO verses VALUES (8637, 10, 22, 32, 'que quem El yhwh yhwh e-quem rocha מִֽבַּלְעֲדֵ֥י Elohim-nosso');
INSERT INTO verses VALUES (8638, 10, 22, 33, 'o-Elohim מָעוּזִּ֖י força וַיַּתֵּ֥ר perfeito');
INSERT INTO verses VALUES (8639, 10, 22, 34, '[מְשַׁוֶּ֥ה] [*רגליו] e-sobre [כָּאַיָּל֑וֹת] [וְעַ֥ל]');
INSERT INTO verses VALUES (8640, 10, 22, 35, 'ensinando מְאַדַּי para-a-guerra וְנִכַּת קֶשֶׁת־ נְחֻשָׁה זְרֹעוֹתַי׃');
INSERT INTO verses VALUES (8641, 10, 22, 36, 'e-deu a-mim escudo-de יִשֻׁעֶךָ וַעֲנוֹתְךָ֖ תַּרְבֵּינִי׃');
INSERT INTO verses VALUES (8642, 10, 22, 37, '[תַּרְחִ֥יב] [צַעֲדִ֖י] [תַּחְתֵּ֑נִי] e-não [מָעֲד֖וּ] [קַרְסֻלָּֽי]');
INSERT INTO verses VALUES (8643, 10, 22, 38, '[אֶרְדְּפָ֥ה] [אֹיְבַ֖י] [וָאַשְׁמִידֵ֑ם] e-não [אָשׁ֖וּב] até');
INSERT INTO verses VALUES (8644, 10, 22, 39, 'וָאֲכַלֵּם וָאֶמְחָצֵם e-não יְקוּמֹנքוּ e-caíram debaixo rágalay:');
INSERT INTO verses VALUES (8645, 10, 22, 40, 'וַתָּזְרֶינִי valor para-a-guerra תַּכְרִיעֲךָ קָמַֽאֲנֵי תַּחְתֵּינִי׃');
INSERT INTO verses VALUES (8646, 10, 22, 41, '[וְאֹ֣יְבַ֔י] [תַּ֥תָּה] a-mim [עֹ֑רֶף] [מְשַׂנְאַ֖י] [וָאַצְמִיתֵֽם]');
INSERT INTO verses VALUES (8647, 10, 22, 42, '[יִשְׁע֖וּ] e-não-há [מֹשִׁ֑יעַ] a yhwh e-não');
INSERT INTO verses VALUES (8648, 10, 22, 43, '[וְאֶשְׁחָקֵ֖ם] [כַּעֲפַר־אָ֑רֶץ] terra [אֲדִקֵּ֖ם] [אֶרְקָעֵֽם]');
INSERT INTO verses VALUES (8649, 10, 22, 44, '[וַֽתְּפַלְּטֵ֔נִי] [מֵרִיבֵ֖י] meu-povo [תִּשְׁמְרֵ֙נִי֙] [לְרֹ֣אשׁ] nações povo não [יַעַבְדֻֽנִי]');
INSERT INTO verses VALUES (8650, 10, 22, 45, 'filhos-de [נֵכָ֖ר] [יִתְכַּֽחֲשׁוּ־לִ֑י] a-mim [אֹ֖זֶן] [יִשָּׁ֥מְעוּ] [לִֽי]');
INSERT INTO verses VALUES (8651, 10, 22, 46, 'filhos-de [נֵכָ֖ר] [יִבֹּ֑לוּ] [וְיַחְגְּר֖וּ] [מִמִּסְגְּרוֹתָֽם]');
INSERT INTO verses VALUES (8652, 10, 22, 47, 'vive yhwh e-barchu tsuri ve-yarum Elohim-de tsur ישעי׃');
INSERT INTO verses VALUES (8653, 10, 22, 48, 'ha-eil ha-natan nekamot a-mim u-morid povo-es ta-chti-ni:');
INSERT INTO verses VALUES (8654, 10, 22, 49, 'e-saúde-me de-inimigos-meu e-de-minha-casa resgatemos-me מֵאִ֥ישׁ injustiças salvai-me:');
INSERT INTO verses VALUES (8655, 10, 22, 50, 'sobre assim yhwh yhwh em-nações e-por-teu-nome cantei:');
INSERT INTO verses VALUES (8656, 10, 22, 51, 'salvações seu-meu-rei e-fazendo- misericórdia para-seu-messias para-davíd e-para-seu-descendente até eternidade');
INSERT INTO chapters VALUES (290, 10, 23, 39);
INSERT INTO verses VALUES (8657, 10, 23, 1, 'e-estes palavras-de Davi os-últimos oráculo-de Davi filho-de jesaí e-diz-se o-homem הֻ֣קַם sobre מְשִׁ֙יחַ֙ Elohim-de Jacó וּנְעִ֖ים זְמִר֥וֹת Israel');
INSERT INTO verses VALUES (8658, 10, 23, 2, 'espírito yhwh [דִּבֶּר־בִּ֑י] em-mim [עַל־לְשׁוֹנִֽי] sobre');
INSERT INTO verses VALUES (8659, 10, 23, 3, 'disse Elohim-de Israel para-mim palavra צ֣וּר Israel rege בָּאָדָ֔ם צַדִּ֕יק מוֹשֵׁ֖ל יראת Elohim');
INSERT INTO verses VALUES (8660, 10, 23, 4, '[וּכְא֥וֹר] manhã [יִזְרַח־שָׁ֑מֶשׁ] manhã não não [מִנֹּ֥גַהּ] [מִמָּטָ֖ר] [דֶּ֥שֶׁא] [מֵאָֽרֶץ]');
INSERT INTO verses VALUES (8661, 10, 23, 5, 'porque não assim em-o-casa com eternidade ברית עולם nome para-mim ערוכָה em-todo ושׁמרָה porque todo ישׁעי e-todo debaixo porque não יאצmpiח׃');
INSERT INTO verses VALUES (8662, 10, 23, 6, '[וּבְלִיַּ֕עַל] [כְּק֥וֹץ] [מֻנָ֖ד] [כֻּלָּ֑הַם] porque não [יִקָּֽחוּ]');
INSERT INTO verses VALUES (8663, 10, 23, 7, 'e-homem irá neles irá ferro וְעֵ֣ץ arado e no fogo queimador serão queimados no deserto:');
INSERT INTO verses VALUES (8664, 10, 23, 8, 'Estas nomes-de os homens valentes que para-Davi habitou no deserto: תּחְכּוֹמֹנִי cabeça [רֹ֣אשׁ] ele ele sobre oito centenas traspassado בְּפַעַם');
INSERT INTO verses VALUES (8665, 10, 23, 9, 'Eleazar filho-de filho-de אֲחֹהִי בִּשְׁלֹשָׁה com Davi בְּחָרְפָ֤ם בַּפְּלִשְׁתִּים֙ נֶאֱסְפוּ־ nome para-a-guerra e-ele-levantaram-se homem Israel');
INSERT INTO verses VALUES (8666, 10, 23, 10, 'ele levantou-se vayyakh בַּפְּלִשְׁתִּ֜ים até porque יָגְעָ֣ה sua-mão ותידבק sua-mão a a-espada yhwh yhwh תְּשׁוּעָה no-dia no-dia aquele והעם ישבו atrás-dele somente לפשתט׃');
INSERT INTO verses VALUES (8667, 10, 23, 11, 'e-depois-dele שָׁמָ֥א filho-de אָגֵ֖א הָרָרִ֑י וַיֵּאָסְפ֨וּ filisteus לַחַיָּ֗ה e-ela-tornou-se nome porção-de o-campo cheia עֲדָשִׂים de-diante-de נָס de-faces-de Filisteus');
INSERT INTO verses VALUES (8668, 10, 23, 12, '[וַיִּתְיַצֵּ֤ב] [בְּתוֹךְ־הַֽחֶלְקָה֙] [וַיַּצִּילֶ֔הָ] [וַיַּ֖ךְ] [אֶת־פְּלִשְׁתִּ֑ים] a yhwh E-fez yhwh');
INSERT INTO verses VALUES (8669, 10, 23, 13, 'e-eles-desceram מֵהַשּׁׁלֹשִׁים cabeça וַיָּבוּ a קָצִיר֙ a Davi a מְעָרָת עֲדֻלַּם וְחַיָּה filisteus חֹנָה na-vale refains');
INSERT INTO verses VALUES (8670, 10, 23, 14, 'e-David entao בַּמְצוּדָה וּמַצָּב filisteus entao casa pão');
INSERT INTO verses VALUES (8671, 10, 23, 15, '[וַיִּתְאַוֶּ֥ה] Davi E-disse quem [יַשְׁקֵ֣נִי] águas [מִבֹּ֥אר] casa-de [אֲשֶׁ֥ר] que');
INSERT INTO verses VALUES (8672, 10, 23, 16, 'וַיִּבְקְעוּ três-de os-guerreiros em-acampamento-de פְלִשְׁתִּ֗ים e-apa-receram-se águas de-água casa-de pão que no-portão va-yis-av-u e-ele-trouxeu a Davi e-não eles para-beber-lhes e-estendeu-se eles para-יהוה');
INSERT INTO verses VALUES (8673, 10, 23, 17, 'E-disse infelizmente a-mim yhwh de-minha-fé esta sangue-que os-homens aqueles-que-andam em-suas-almas e-não pai para-los Estas fizeram três os-valentes');
INSERT INTO verses VALUES (8674, 10, 23, 18, 'e-Avivay irmão- יוֹאָב filho-de צְרוּיָה ele cabeça e-ele acordar a חֲנִית֔וֹ sobre três centenas traspassado e-para-ele- nome na-três:');
INSERT INTO verses VALUES (8675, 10, 23, 19, 'de os-três pois e-houve a-eles a-eles para-Sar e-até os-três não veio');
INSERT INTO verses VALUES (8676, 10, 23, 20, 'e-בְנָיָה filho-de Joia-da filho-de homem-de chefe-de ele de-Miqqabce''el ele hikka a segundo Ariel Moabe ve-hu yarad ve-hikka no-meio-de em-meio-de ha-ba''or em-dia ha-shagle');
INSERT INTO verses VALUES (8677, 10, 23, 21, 've-hu- hikka a homem mitzri vista e-com-a-mão-de ham-mitzriy chániyt e-desceu a-ele beshávet vayigzól a chániyt da-mão-de o-egípcio vayehargéhu báchániyt');
INSERT INTO verses VALUES (8678, 10, 23, 22, 'Estas fez baniyahu filho-de Yehoyada e-para-ele- nome bisheleshó os-valentes');
INSERT INTO verses VALUES (8679, 10, 23, 23, 'de hashéloshim nobre e-a hashélosha não veio vayesámehu Davi a de-sua-ouvi-dão:');
INSERT INTO verses VALUES (8680, 10, 23, 24, 'ele-fez El meu-irmão- יוֹאָב em-trinta Elaquán filho-de דֹּד֖וֹ casa pão');
INSERT INTO verses VALUES (8681, 10, 23, 25, 'que o-Haredi Eliká o-Haredi:');
INSERT INTO verses VALUES (8682, 10, 23, 26, 'cavalo o-ferrete עִירָא filho-de עִקֵּשׁ הַתְּקוֹעִי׃');
INSERT INTO verses VALUES (8683, 10, 23, 27, '[אֲבִיעֶ֙זֶר֙] [הָֽעֲ[c]נְּתֹתִ֔י] [מְבֻנַּ֖י]');
INSERT INTO verses VALUES (8684, 10, 23, 28, '[צַלְמוֹן֙] [הָֽאֲחֹחִ֔י] [מַהְרַ֖י] [הַנְּטֹפָתִֽי׃]');
INSERT INTO verses VALUES (8685, 10, 23, 29, '[חֵ֥לֶב] filho-de [הַנְּטֹפָתִ֑י] [ס] [אִתַּי֙] filho-de [מִגִּבְעַ֖ת] [בְּנֵ֥י] filhos-de');
INSERT INTO verses VALUES (8686, 10, 23, 30, 'Benaia פִּרְעָ֣תֹנִ֔י הִדַּ֖י מִנַּ֥חֲלֵי גָֽעַשׁ׃');
INSERT INTO verses VALUES (8687, 10, 23, 31, 'pai-de עַלְבוֹן֙ הָֽעַרְבָתִ֔י Azmavete הַבַּרְחֻמִֽי׃');
INSERT INTO verses VALUES (8688, 10, 23, 32, 'אֶלְיַחְבָּא֙ הַשַׁ֣עַלְבֹנִ֔י filhos-de velho jehonathan');
INSERT INTO verses VALUES (8689, 10, 23, 33, '[שַׁמָּה֙] [הַֽהֲרָרִ֔י] [אֲחִיאָ֥ם] filho-de [הָארָרִֽי׃]');
INSERT INTO verses VALUES (8690, 10, 23, 34, '[אֱלִיפֶ֥לֶט] filho-de [בֶּן־הַמַּֽעֲכָתִ֑י] filho-de [אֱלִיעָ֥ם] [בֶּן־אֲחִיתֹ֖פֶל] filho-de');
INSERT INTO verses VALUES (8691, 10, 23, 35, '[*חצרו] [**חֶצְרַי֙] [הַֽכַּרְמְלִ֔י]');
INSERT INTO verses VALUES (8692, 10, 23, 36, '[יִגְאָ֤ל] filho-de deu [ס] filhos-de [הַגָּדִֽי׃]');
INSERT INTO verses VALUES (8693, 10, 23, 37, 'צֶלֶק הָעַמּוֹנִי נַחְרַי הַבְּאֵרֹתִי kléi- Joab filho-de צְרֻיָה׃');
INSERT INTO verses VALUES (8694, 10, 23, 38, '[עִירָא֙] [הַיִּתְרִ֔י] [גָּרֵ֖ב] [הַיִּתְרִֽי׃]');
INSERT INTO verses VALUES (8695, 10, 23, 39, 'auriyyah֑ a hitita todo trinta e-sete');
INSERT INTO chapters VALUES (291, 10, 24, 25);
INSERT INTO verses VALUES (8696, 10, 24, 1, 'e ele fez adicionar também yhwh para marcar em-Israel e ela foi a dizendo neles dizendo vai o contador a Israel e-a Judá');
INSERT INTO verses VALUES (8697, 10, 24, 2, 'E-disse o-rei a joab ׀ príncipe-de a força que com-ele andar— por-favor em-todo tribos Israel מִדָן e-até poço sete וּפִקְדוּ a o-povo וְיָדַעְתִּי a número o-povo');
INSERT INTO verses VALUES (8698, 10, 24, 3, 'E-disse Joabe a o-rei yhwh yhwh Elohim a o-povo כָּהֵ֤ם וְכָהֵם֙ cem פְעָמִ֔ים וְעֵינֵ֥י senhor-meu o-rei רֹאֹות וַאדֹנִי o-rei por-que חָפֵ֖ץ em-a-palavra a-esta');
INSERT INTO verses VALUES (8699, 10, 24, 4, 'e-ele-firmou palavra-de o-rei a Joabe e-sobre príncipes-de הֶחָיִל e-saiu Joabe e-príncipes-de הַחֲיִל֙ diante-de o-rei para contar a o-povo a Israel');
INSERT INTO verses VALUES (8700, 10, 24, 5, 'e passaram-se a o Jordão e-acamparam no Aróer Direito a-cidade que em-meio-de o-vale o Gade e-a Jazer:');
INSERT INTO verses VALUES (8701, 10, 24, 6, 'e-vieram a Gileade e-a terra em baixo Chadesi e-vieram Dana porque e ao redor a Sidom:');
INSERT INTO verses VALUES (8702, 10, 24, 7, 'e-vieram de Sior e-todo cidades-de o-hivi e o Cananeu a Nebeg Judá em-Beer sete');
INSERT INTO verses VALUES (8703, 10, 24, 8, 'e se voltaram em-todo a-terra e-vieram de nove חדשים dia dia Jerusalém');
INSERT INTO verses VALUES (8704, 10, 24, 9, 'E-colocou Joab a número מִפְקַד- o-povo a o-rei וַתְּהִי Israel oito centenas espada homem-de חייל desembainhando espada e-homem Judá חֲמֵשׁ- centenas mil homem');
INSERT INTO verses VALUES (8705, 10, 24, 10, 'e-ele-feriu coração-de ele a-ele depois-de assim סָפַ֣ר E-disse o-povo E-disse Davi muito yhwh חָטָ֤אתִי e-agora yhwh fiz e-agora yhwh que por-favor muito iniquidade teu-servo porque eu me confundi muito');
INSERT INTO verses VALUES (8706, 10, 24, 11, 'E-levantou Davi no-manhã e-palavra-de yhwh ser a Gad o-profeta o vislumbrador dizendo para-dizer');
INSERT INTO verses VALUES (8707, 10, 24, 12, 'הָל֞וֹךְ e-tu-falarás a Davi disse yhwh yhwh eu eu נוֹטֵ֣ל sobre-ti בְּחַר- para-ti אַֽחַת- deles e-e''asah- para-ti');
INSERT INTO verses VALUES (8708, 10, 24, 13, 'וַיָּבֹא־ גָ֥ד a E-disse a-ele a-ele a-ti lo הֲתָב֣וֹא a-ti sete- שָׁנִ֣ים רָעָ֣ב בְּאַרְצֶ֡ךָ se três חֳ֠דָשִׁים נֻסְךָ֨ diante-de- צָרֶ֜יךָ e-ele רֹדְפֶ֗ךָ e-se הֱ֠יוֹת três-de dias palavra em-teu-terreiro agora sabes e-vê o-quê para-ti שׁוּלְחִי palavra');
INSERT INTO verses VALUES (8709, 10, 24, 14, 'E-disse Davi a גָּד muito para-mim muito caíram- agora na-mao-de yhwh porque muitos e-em-mão- homem a destruição;');
INSERT INTO verses VALUES (8710, 10, 24, 15, 'E-colocou yhwh palavra em-Israel do-amanhecer e-até tempo reunião E-morreu de o-povo de-Dana e-até poço sete setenta mil homem');
INSERT INTO verses VALUES (8711, 10, 24, 16, 'e-enviou sua-mão o-angel- para-destruí-la; e-ele-se-arrependeu yhwh a yhwh E-disse E-disse o-mashchit em-o-povo muito agora levantou-se tua-mao e anjo yhwh yhwh ser goren Hayivsi');
INSERT INTO verses VALUES (8712, 10, 24, 17, 'E-disse Davi a yhwh be-rio''o a o-malak'' o-mache no povo E-disse eis eu pecado-eu e-eu he-aveiti e-aqueles a-o-rebanho que asú Tihi por-favor yadcha em-mi u-b''veit pai-meu');
INSERT INTO verses VALUES (8713, 10, 24, 18, 'וַיָּבֹא־ gad no-dia Davi E-disse a-ele folhas-de para-ele al''e hakeim a-yhwh altar em-eira-de Hayivsi');
INSERT INTO verses VALUES (8714, 10, 24, 19, 'e-subiu Davi por a palavra- gad como yhwh yhwh');
INSERT INTO verses VALUES (8715, 10, 24, 20, 'e olhou- Arauña-Arauña E-viu a o-rei e-a seus-servos passamos sobre-ele e-saiu Arauña-Arauña e-ele-se-prostrou para-o-rei rosto-seu para-terra');
INSERT INTO verses VALUES (8716, 10, 24, 21, 'E-disse Arauña-Arauña por-que veio senhor-meu o-rei E-disse seu-servo E-disse Davi comprar- de ti- a o grão- para-construir um-altar de-cima-de e aperte a praga de-sobre o-povo');
INSERT INTO verses VALUES (8717, 10, 24, 22, 'E-disse Arauña-Arauña a Davi ele-tomará e subir- Adonai o-rei o-bom viu o boi para-a-oferta e-que-moçam e-vessãis o-bovino para-os-árvores:');
INSERT INTO verses VALUES (8718, 10, 24, 23, 'todo-o dar arôna o-rei ao-rei E-disse E-disse a o-rei yhwh teu-Elohim te-alegrei:');
INSERT INTO verses VALUES (8719, 10, 24, 24, 'E-disse o-rei a não não porque ele-comprou eu-comprei de-você com-preço e-não אַעֲלֶה para-יהוה Elohim-meu עֹלוֹת חִנָּ֑ם וַיִּ֨קֶן Davi a הַגֹּ֙רֶן֙ e-a o-bovino בְּכֶ֖סֶף שְׁקָלִ֥ים חֲמִשִּֽׁים׃');
INSERT INTO verses VALUES (8720, 10, 24, 25, 'E-edificou nome Davi um-altar a-yhwh e-ofereceu holocaustos e-pacíficos וַיֵּעָתֵ֤ר yhwh לָאָ֔רֶץ וַתֵּעָצַ֥ר a praga de-cima-de Israel');
INSERT INTO books VALUES (11, '1KI', '1 Reis', 'AT', 22);
INSERT INTO chapters VALUES (292, 11, 1, 53);
INSERT INTO verses VALUES (8721, 11, 1, 1, 'e-o rei Davi velho veio em-os dias e-cobriram-o com-as roupas e-não aqueceu a-ele');
INSERT INTO verses VALUES (8722, 11, 1, 2, 'e-disseram a-ele servos-de-ele busquem para-adonai-de-mim o rei jovem virgem e-ficará-em-pé diante-de o-rei e-será para-ele cuidadora e-deitará em-seio-de-você e-aquecerá para-adonai-de-mim o rei');
INSERT INTO verses VALUES (8723, 11, 1, 3, 'e-buscaram jovem bela em-todo território Israel e-encontraram a אֲבִישַׁג a שונמית e-trouxeram a-ela para-o rei');
INSERT INTO verses VALUES (8724, 11, 1, 4, 'e-a jovem bela até muito e-foi para-o rei cuidadora e-serviu-o não não conheceu-a');
INSERT INTO verses VALUES (8725, 11, 1, 5, 'e-אֲדֹנִיָּה filho-de חַגִּית dizendo para-dizer eu reinarei a-ele para-ele carruagem e-cavaleiros e-cinquenta homem correndo diante-de-ele');
INSERT INTO verses VALUES (8726, 11, 1, 6, 'e-não seu-pai pai-de-ele dizendo para-dizer por-que assim fizeste e-também muito bom forma muito e-a-ele deu-à-luz atrás-de אַבְשָׁלוֹם');
INSERT INTO verses VALUES (8727, 11, 1, 7, 'e-foram palavras-de-ele povo יוֹאָב filho-de Zeruiah e-com אֶבְיָתָר o-sacerdote e-ajudaram atrás-de אֲדֹנִיָּה');
INSERT INTO verses VALUES (8728, 11, 1, 8, 'e-צָדוֹק o sacerdote e-בְנָיָה filho-de יְהוֹיָדָע e-נָתָן o profeta e-שִׁמְעִי e-רֵעִי e-os valentes que não não foram com אֲדֹנִיָּה');
INSERT INTO verses VALUES (8729, 11, 1, 9, 'e-sacrificou אֲדֹנִיָּה ovelhas e-gado e-animais-cevados povo pedra a זֹחֶלֶת que junto olho E-chamou E-chamou a todo irmãos-de-ele filhos-de o-rei e-para-todo- homens-de יְהוּדָה servos-de o rei');
INSERT INTO verses VALUES (8730, 11, 1, 10, 'e-a deu o profeta e-בְנָיָה e-a os valentes não chamou irmão-seu não chamou');
INSERT INTO verses VALUES (8731, 11, 1, 11, 'E-disse deu a filha-de dizendo se שְׁלֹמֹה que não ouviste porque rei אֲדֹנִיָּה não Hagite e-adonai-de-nós Davi não conheceu');
INSERT INTO verses VALUES (8732, 11, 1, 12, 'e-agora vai aconselharei-você por-favor conselho e-salva a alma-de-você e-a alma filho-de-você שְׁלֹמֹה');
INSERT INTO verses VALUES (8733, 11, 1, 13, 'vai e-entra a o-rei Davi e-dirás a-ele não você Adonai o rei juraste dizendo para-dizer porque שְׁלֹמֹה filho-de-você reinará após-mim e-ele habitou sobre trono-de-mim e-por-que rei Adonias');
INSERT INTO verses VALUES (8734, 11, 1, 14, 'eis ainda-tu falando nome com o-rei e-eu eu-entrarei depois-de-ti e-completarei a palavras-tuas');
INSERT INTO verses VALUES (8735, 11, 1, 15, 'e-veio filha-de sete a o rei o-quarto muito velho muito e-Abisague a שונמית servindo a o rei');
INSERT INTO verses VALUES (8736, 11, 1, 16, 'e-ela-se-curvou filha-de sete e-se-prostrou E-disse E-disse o-rei que- para-ti');
INSERT INTO verses VALUES (8737, 11, 1, 17, 'E-disse a-ele Adonai tu tu-juraste em-יהוה Elohim-teu para-serva-tua porque Salomão filho-teu reinará depois-de-mim e-ele habitou sobre trono-meu');
INSERT INTO verses VALUES (8738, 11, 1, 18, 'e-agora eis Adonias rei e-agora Adonai o-rei não tu-soubeste');
INSERT INTO verses VALUES (8739, 11, 1, 19, 'e-ele-sacrificou boi e-animal-engordado e-ovelhas E-chamou E-chamou para-todo filhos-de o-rei e-para-Abiatar o-sacerdote e-para-Joabe comandante-de o-exército não chamou não chamou');
INSERT INTO verses VALUES (8740, 11, 1, 20, 'e-tu Adonai o-rei os-olhos-de todo Israel sobre-ti a-eles quem quem habitou sobre trono-de adonai-meu o-rei atrás-dele');
INSERT INTO verses VALUES (8741, 11, 1, 21, 'e-será quando-deitar adonai-meu o-rei com pais-seus e-eu-serei eu e-filho-meu Salomão pecadores');
INSERT INTO verses VALUES (8742, 11, 1, 22, 'e-eis ainda-ela falando com o-rei e-Natã o-profeta veio');
INSERT INTO verses VALUES (8743, 11, 1, 23, 'e-eles-anunciaram para-o-rei dizendo eis deu o-profeta E-veio diante-de o-rei e-ele-se-prostrou para-o-rei sobre rosto-seu para-terra');
INSERT INTO verses VALUES (8744, 11, 1, 24, 'E-disse deu Adonai o-rei tu tu-disseste Adonias reinará depois-de-mim e-ele habitou sobre trono-meu');
INSERT INTO verses VALUES (8745, 11, 1, 25, 'que ele-desceu o-dia o-dia boi e-animal-engordado e-ovelhas em-abundância E-chamou para-todo filhos-de o-rei e-para-comandantes-de o-exército e-para-Abiatar o-sacerdote e-eis-eles comendo e-bebendo diante-dele e-disseram viva o-rei אֲדֹנִיָּה');
INSERT INTO verses VALUES (8746, 11, 1, 26, 'e-para-mim eu servo-teu e-para-Zadoque o sacerdote e-para-Benaia filho-de Joiada não chamou não chamou');
INSERT INTO verses VALUES (8747, 11, 1, 27, 'mãe de-com Adonai o-rei aconteceu a-coisa esta e-não tu-fizeste-conhecer את- quem quem sobre trono-de adonai-meu o-rei atrás-dele');
INSERT INTO verses VALUES (8748, 11, 1, 28, 'e-ele-respondeu o-rei Davi E-disse chamai para-mim para-filha-de sete e-ela-veio diante-de o-rei e-ela-ficou-em-pé diante-de o rei');
INSERT INTO verses VALUES (8749, 11, 1, 29, 'e-ele-jurou o-rei E-disse vive yhwh que ele-resgatou a alma-minha de-todo angústia');
INSERT INTO verses VALUES (8750, 11, 1, 30, 'que como-que eu-jurei para-ti em-יהוה Elohim-de Israel dizendo porque שְׁלֹמֹה filho-teu reinará após-mim e-ele habitou sobre que em-lugar-de-mim porque o-dia eu-farei o-dia a-esta');
INSERT INTO verses VALUES (8751, 11, 1, 31, 'e-ela-inclinou filha-de sete terra terra e-se-prostrou E-disse e-disse que-viva Adonai o-rei para-sempre para-sempre');
INSERT INTO verses VALUES (8752, 11, 1, 32, 'E-disse o-rei Davi chamai- para-mim para-Tsadoq o-sacerdote e-para-Natan o-profeta e-para-Benayahu filho-de Yehoyada e-vieram diante-de o rei');
INSERT INTO verses VALUES (8753, 11, 1, 33, 'E-disse o-rei a-eles tomai com-vós a servos-de adonai-de-vós e-vós-fareis-montar a Shelomoh filhos-de sobre ele que para-mim e-vós-fareis-descer a-ele a Gihon');
INSERT INTO verses VALUES (8754, 11, 1, 34, 'e-ungirá ele nome Tsadoq o sacerdote e-Natan o-profeta para-rei sobre Israel e-vós-tocareis em-o chifre e-vós-direis que-viva o-rei שְׁלֹמֹה');
INSERT INTO verses VALUES (8755, 11, 1, 35, 'e-vós-subireis após-ele e-ele-virá e-ele-assentar-se-á sobre trono-meu e-ele ele-reinará em-lugar-de-mim e-a-ele eu-ordenei para-ser príncipe sobre Israel e-sobre Judá');
INSERT INTO verses VALUES (8756, 11, 1, 36, 'e-ele-respondeu Benayahu filho-de Yehoyada E-disse o-rei e-ele-disse amém assim yhwh yhwh Elohim-de Adonai o rei');
INSERT INTO verses VALUES (8757, 11, 1, 37, 'como-que ser yhwh com Adonai o-rei assim com Shelomoh e-que-ele-engrandeça a trono-dele mais-que-trono-de Adonai o-rei Davi');
INSERT INTO verses VALUES (8758, 11, 1, 38, 'e-desceu Tsadoq o sacerdote e-Natan o-profeta e-Benayahu filho-de Yehoyada e-os-queretitas e-os-peletitas e-eles-fizeram-montar a Shelomoh sobre mula-de ele Davi e-eles-fizeram-ir a-ele sobre Gihon');
INSERT INTO verses VALUES (8759, 11, 1, 39, 'E-tomou Tsadoq o sacerdote a chifre-de o-óleo de a-tenda e-ele-ungiu a Shelomoh e-eles-tocaram em-o chifre e-disseram todo o-povo que-viva o-rei שְׁלֹמֹה');
INSERT INTO verses VALUES (8760, 11, 1, 40, 'e-eles-subiram todo o-povo atrás-dele e-o-povo tocando com-flautas e-alegrando-se alegria grande a-terra a-terra com-voz-deles');
INSERT INTO verses VALUES (8761, 11, 1, 41, 'E-ouviu אֲדֹנִיָּה e-todo os-convidados que com-ele e-eles eles-terminaram de-comer E-ouviu Joabe a E-disse o-shofar E-disse por-que som-de a-cidade está-agitada');
INSERT INTO verses VALUES (8762, 11, 1, 42, 'ainda-ele falando e-eis Yonatan filho-de Evyatar o-sacerdote E-disse E-disse Adoniyahu que porque homem tu tu e-bom anuncias');
INSERT INTO verses VALUES (8763, 11, 1, 43, 'e-respondeu Jônatas E-disse para-Adonias certamente adonai-nosso o-rei Davi fez-reinar a שְׁלֹמֹה');
INSERT INTO verses VALUES (8764, 11, 1, 44, 'e-enviou com-ele o-rei a Zadoque o sacerdote e-a deu o-profeta e-Benaia filho-de ele sobre e-o-peleteu e-fizeram-montar a-ele sobre mula-de o rei');
INSERT INTO verses VALUES (8765, 11, 1, 45, 'e-ungiram ele Zadoque o-sacerdote e-Natã o-profeta para-rei em-Giom e-eles-subiram de-lá alegres e-soou a-cidade ele ele que ouvistes');
INSERT INTO verses VALUES (8766, 11, 1, 46, 'e-também habitou Shelomoh sobre trono-de o-reino');
INSERT INTO verses VALUES (8767, 11, 1, 47, 'e-também vieram servos-de o-rei para-abençoar a adonai-nosso dizendo Davi dizendo torne-bom a nome שְׁלֹמֹה de-nome-teu e-engrandeça a trono-dele de-trono-teu e-prostrou-se o-rei sobre a-cama');
INSERT INTO verses VALUES (8768, 11, 1, 48, 'e-também disse disse o-rei yhwh yhwh Elohim-de Israel dar o-dia o-dia habitou sobre trono-meu e-olhos-meus vendo');
INSERT INTO verses VALUES (8769, 11, 1, 49, 'e-tremeram e-levantaram-se todo os-convidados que para-Adonias e-foram homem para-caminho-dele');
INSERT INTO verses VALUES (8770, 11, 1, 50, 'e-Adonias temer de-diante-de Shelomoh E-levantou E-andou e-segurou em-chifres-de o-altar');
INSERT INTO verses VALUES (8771, 11, 1, 51, 'e-foi-contado para-Salomão dizendo eis Adonias temer a o-rei Shelomoh e-eis segurou em-chifres-de dizendo para-dizer jure para-mim como-o-dia o-rei Shelomoh se matará a servo-dele pela-espada');
INSERT INTO verses VALUES (8772, 11, 1, 52, 'E-disse Shelomoh mãe será para-filho-de valente não cairá de-cabelo-dele terra e-se mal for-achado em-ele e-morreu');
INSERT INTO verses VALUES (8773, 11, 1, 53, 'e-enviou o-rei Salomão e-fizeram-descer-ele de-cima-de o altar E-veio e-prostrou-se para-o-rei Shelomoh e-ele-disse para-ele Salomão vai para-casa-tua');
INSERT INTO chapters VALUES (293, 11, 2, 46);
INSERT INTO verses VALUES (8774, 11, 2, 1, 'e-aproximaram-se dias-de Davi E-ordenou e-ordenou a dizendo filho-dele para-dizer');
INSERT INTO verses VALUES (8775, 11, 2, 2, 'eu andou em-caminho-de todo a-terra e-fortalece-te e-sê para-homem');
INSERT INTO verses VALUES (8776, 11, 2, 3, 'e-guardarás a guarda-de yhwh Elohim-teus para-andar em-caminhos-seus para-guardar estatutos-seus mandamentos-seus e-juízos-seus e-testemunhos-seus conforme-o-escrito em-lei-de Moisés para-que tu-prosperarás את todo que tu-farás e-a todo que tu-te-voltares nome');
INSERT INTO verses VALUES (8777, 11, 2, 4, 'a-fim-de ele-estabeleça yhwh a palavra-sua que palavra dizendo dizendo se eles-guardarem filhos-teus a caminho-deles para-andar diante-de-mim dizendo em-todo a-ti e-em-todo de-cima-de dizendo não será-cortado para-ti homem de-sobre trono-de Israel');
INSERT INTO verses VALUES (8778, 11, 2, 5, 'e-também tu tu-conheceste את que fez para-mim יוֹאָב filho-de צְרוּיָה que fez a-dois-de príncipes-de exércitos Israel para-Abner filho-de נֵר e-a-עֲמָשָׂא filho-de E-colocou e-ele-matou-eles e-colocou sangues-de guerra em-paz E-deu sangues-de guerra em-cinto-seu que em-lombos-seus e-em-sandália-sua que em-pés-seus');
INSERT INTO verses VALUES (8779, 11, 2, 6, 'e-tu-farás conforme-sabedoria-tua e-não tu-farás-descer velhice-sua em-paz שְׁאוֹל');
INSERT INTO verses VALUES (8780, 11, 2, 7, 'e-a-filhos-de בַרְזִלַּי o-גִּלְעָדִי tu-farás e-sejam e-serão em-comedores-de mesa-tua porque assim eles-se-aproximaram de-diante-de em-fugir-meu de-face-de אַבְשָׁלוֹם irmão-teu');
INSERT INTO verses VALUES (8781, 11, 2, 8, 'e-eis contigo שִׁמְעִי filho-de גֵּרָא filho-de o-יְמִינִי de-בַּחֻרִים e-ele ele-me-amaldiçoou maldição severa em-dia ir-meu מַחֲנַיִם e-ele ele-desceu a-ele o-Jordão dizendo para-ele em-יהוה para-dizer se matá-lo-tu pela-espada');
INSERT INTO verses VALUES (8782, 11, 2, 9, 'e-agora a que porque homem sábio tu e-tu-saberás com que tu-farás a-ele e-tu-farás-descer a velhice-sua com-sangue שְׁאוֹל');
INSERT INTO verses VALUES (8783, 11, 2, 10, 'e-ele-deitou Davi com pais-seus e-ele-foi-sepultado em-cidade-de Davi');
INSERT INTO verses VALUES (8784, 11, 2, 11, 'e-os-dias que rei Davi sobre Israel quarenta ano em-חֶבְרוֹן rei sete dois e-em-jerusalém rei trinta e-três dois');
INSERT INTO verses VALUES (8785, 11, 2, 12, 'e-שְׁלֹמֹה habitou sobre trono-de seu-pai pai-seu e-ela-se-estabeleceu muito muito');
INSERT INTO verses VALUES (8786, 11, 2, 13, 'E-veio אֲדֹנִיָּה filho-de a filha-de E-disse se Shelomoh E-disse pergunta-paz vir-teu E-disse paz');
INSERT INTO verses VALUES (8787, 11, 2, 14, 'E-disse palavra para-mim a-ti E-disse palavra');
INSERT INTO verses VALUES (8788, 11, 2, 15, 'E-disse tu tu-soubeste porque era ela-foi o-reino e-sobre-mim eles-puseram todo Israel faces-deles para-reinar e-ela-circundou a-realeza que para-irmão-meu era para-ele ela-foi para-ele');
INSERT INTO verses VALUES (8789, 11, 2, 16, 'e-agora pedido uma eu pedindo de-com-ti a tu-farás-voltar E-disse a-ele e-disse a-ele palavra');
INSERT INTO verses VALUES (8790, 11, 2, 17, 'E-disse dize- por-favor para-שְׁלֹמֹה que porque não ele-fará-voltar a face-tua e-ele-dará- para-mim a אֲבִישַׁג a-שּׁוּנַמִּית para-mulher');
INSERT INTO verses VALUES (8791, 11, 2, 18, 'E-disse filha-de bom eu eu falarei sobre-ti a o rei');
INSERT INTO verses VALUES (8792, 11, 2, 19, 'e-ela-veio filha-de sete a o-rei Shelomoh para-falar- para-ele sobre אֲדֹנִיָּה E-levantou o-rei para-encontro-dela e-ele-prostrou-se para-ela e-habitou sobre trono-dele e-ele-colocou trono para-mãe o-rei e-habitou à-direita-dele');
INSERT INTO verses VALUES (8793, 11, 2, 20, 'E-disse pedido uma pequeno eu pedindo de-com-ti a farás-voltar a face-de e-ele-disse para-ela que pede mãe-minha porque não farei-voltar a face-tua');
INSERT INTO verses VALUES (8794, 11, 2, 21, 'E-disse seja-dado a אֲבִישַׁג a-שֻּׁנַמִּית para-אֲדֹנִיָּה irmão-teu para-mulher');
INSERT INTO verses VALUES (8795, 11, 2, 22, 'e-ele-respondeu o-rei שְׁלֹמֹה E-disse para-mãe-dele e-por-que tu pedindo a אֲבִישַׁג a-shunamita para-אֲדֹנִיָּה e-pede- que ele o-reino porque ele irmão-meu o-grande de-mim e-para-ele e-para-אֶבְיָתָר o-sacerdote e-para-יוֹאָב filho-de צְרוּיָה');
INSERT INTO verses VALUES (8796, 11, 2, 23, 'e-ele-jurou o-rei Shelomoh em-יהוה dizendo assim fará- para-mim Elohim e-assim que porque em-alma-dele palavra Adonias a a palavra a-esta');
INSERT INTO verses VALUES (8797, 11, 2, 24, 'e-agora vive yhwh que estabeleceu-me sobre trono Davi pai-meu e-que fez para-mim casa como-que que o-dia o-dia será-morto אֲדֹנִיָּה');
INSERT INTO verses VALUES (8798, 11, 2, 25, 'e-enviou o-rei Shelomoh em-mão בְּנָיָה filho-de יְהוֹיָדָע e-ele-atacou- nele E-morreu');
INSERT INTO verses VALUES (8799, 11, 2, 26, 'e-para-אֶבְיָתָר o sacerdote disse o rei עֲנָתֹת vai sobre que porque homem morte tu e-em-o-dia não não sair-teu porque tu-carregaste a arca-de Adonai yhwh diante-de Davi pai-meu e-porque tu-te-afligiste em-todo que afligiu-se pai-meu');
INSERT INTO verses VALUES (8800, 11, 2, 27, 'e-ele-expulsou שְׁלֹמֹה a אֶבְיָתָר de-ser sacerdote para-יהוה para-cumprir yhwh palavra yhwh que palavra sobre casa Eli em-Silo');
INSERT INTO verses VALUES (8801, 11, 2, 28, 'e-a-notícia veio até que porque Joabe inclinou depois-de Adonias e-após-de não não inclinou e-fugiu Joabe yhwh tenda yhwh e-ele-fortaleceu em-chifres-de o-altar');
INSERT INTO verses VALUES (8802, 11, 2, 29, 'e-foi-contado para-o-rei Salomão que fugiu Joabe a yhwh yhwh e-eis junto-a o-altar e-enviou שְׁלֹמֹה a dizendo filho-de Joiada para-dizer vai ataca em-ele');
INSERT INTO verses VALUES (8803, 11, 2, 30, 'E-veio Benaia a yhwh E-disse a-ele a-ele assim disse E-disse sai não que porque aqui morrerei e-retornou Benaia a dizendo palavra para-dizer assim palavra יוֹאָב e-assim respondeu-me');
INSERT INTO verses VALUES (8804, 11, 2, 31, 'E-disse a-ele o-rei fez como-que palavra e-ataca nele e-enterrá-lo-ás e-removerás sangues-de sem-causa que derramou יוֹאָב de-sobre-mim e-de-sobre casa pai-meu');
INSERT INTO verses VALUES (8805, 11, 2, 32, 'e-retornará yhwh a sangue-dele sobre cabeça-sua que atacou em-dois-de nós justos e-bons do-que-ele e-matou-os não e-Abner Davi não conheceu a Abner filho-de Ner príncipe-de exército-de Israel e-a Amasa filho-de Jeter príncipe-de exército-de Judá');
INSERT INTO verses VALUES (8806, 11, 2, 33, 'e-retornarão sangues-deles na-cabeça יוֹאָב e-em-cabeça-de sua-semente para-sempre e-a-Davi e-a-semente-dele e-a-casa-dele e-a-trono-dele será paz até eternidade yhwh yhwh');
INSERT INTO verses VALUES (8807, 11, 2, 34, 'e-subiu Benaia filho-de Joiada e-ele-atacou- nele e-matou-o e-foi-enterrado em-casa-dele no-deserto');
INSERT INTO verses VALUES (8808, 11, 2, 35, 'E-colocou o-rei a Benayahu filho-de Joiada em-lugar-dele sobre dar e-a debaixo o-sacerdote deu o-rei sob Abiatar');
INSERT INTO verses VALUES (8809, 11, 2, 36, 'e-estendeu o-rei E-chamou a-Simei E-disse a-ele constrói para-ti casa em-Jerusalém e-habitarás nome e-não sairás de-lá onde e-onde');
INSERT INTO verses VALUES (8810, 11, 2, 37, 'e-era no-dia saída-tua e-passares a vale-de Cedrom conheceu saberás que morrendo morrerás sangue-teu será em-cabeça-tua');
INSERT INTO verses VALUES (8811, 11, 2, 38, 'E-disse Simei para-o-rei bom a-palavra como-que palavra Adonai o-rei assim fará servo-teu e-habitou Simei birushalaim dias muitos');
INSERT INTO verses VALUES (8812, 11, 2, 39, 'e-houve de-fim três dois e-eles-deram-refúgio dois servos a-Simei a Achis filho-de Maacha rei dizendo eis para-shimi dizendo eis servos-teus na-Beth-Gamul');
INSERT INTO verses VALUES (8813, 11, 2, 40, 'E-levantou Simei e-ele-faz-força a o-mula-seu E-andou em-o-tanque a Aichis para-pedir a e-trouxe E-andou Shimei E-veio a servos-dele de-o-tanque');
INSERT INTO verses VALUES (8814, 11, 2, 41, 'e-ele-foi-dito para-Salomão porque andou Shimei de-Jerusalém gat e-voltou');
INSERT INTO verses VALUES (8815, 11, 2, 42, 'e-enviou o-rei E-chamou le-shim''i E-disse a-ele não hisbat''tikha ba-Yahweh va''ad be-ka dizendo no-dia saída-tua ve-halakhta aneh va''ana conheceu saberás que morrendo morrerás E-disse a-mim bom a palavra shama''ti');
INSERT INTO verses VALUES (8816, 11, 2, 43, 'e-porque não guardaste a de-o-selo yhwh e-a da-mandamento que mandei-eu sobre-te');
INSERT INTO verses VALUES (8817, 11, 2, 44, 'E-disse o-rei a tu tu tu-conheceste a todo saber que conheceu para-o-teu-coracao que fiz-te- a-David yhwh e-devolveu yhwh a teu-mal em-a-cabeça-vosso-verso');
INSERT INTO verses VALUES (8818, 11, 2, 45, 'e-o-rei Salomão bendito e cadeira Davi será certo diante-de yhwh até eternidade');
INSERT INTO verses VALUES (8819, 11, 2, 46, 'E-ordenou o rei a Benaia filho-de Joiada e-ele-saiu e-ele-atacou- nele E-morreu e-o-reino certa por-mão-de שְׁלֹמֹה');
INSERT INTO chapters VALUES (294, 11, 3, 28);
INSERT INTO verses VALUES (8820, 11, 3, 1, 'e-ele-se-casou Shelomoh a פַּרְעֹה rei E-tomou E-tomou a filha-de פַּרְעֹה até a cidade Davi até yhwh para-construir a sua-casa e-a casa yhwh e-a muro-de jerusalém ao-redor');
INSERT INTO verses VALUES (8821, 11, 3, 2, 'somente o-povo de-mesquitas na-altar que não nibnah casa yhwh até até ha-yamim ha-hem');
INSERT INTO verses VALUES (8822, 11, 3, 3, 'vaye-eahav שְׁלֹמֹה a yhwh lalechet be-chukot seu-pai pai-seu somente ele ele me-zabeh umak-tir');
INSERT INTO verses VALUES (8823, 11, 3, 4, 'E-andou o-rei gib-ownah lizboh nome que ela a-elevada o-grande mil holocaustos subia Shelomoh sobre o-altar a-aquela');
INSERT INTO verses VALUES (8824, 11, 3, 5, 'em-gibeon foi-visto yhwh a Salomão a-noite E-disse e-disse Elohim pede que darei para-ti');
INSERT INTO verses VALUES (8825, 11, 3, 6, 'E-disse Salomão tu fiz-te com seu-escravo Davi meu-pai bondade grande andar andou diante-de-você com-verdade e-com-justiça e-em-retidão-de coração contigo e-vigiaste- para-ele a a-graça a-grande esta e-deu a-ele filho habitou sobre trono-dele como-o-dia a-esta');
INSERT INTO verses VALUES (8826, 11, 3, 7, 'e-agora yhwh Elohim-meus tu reinaste a debaixo sob Davi pai-meu e-eu jovem não não eu-saberei tset e-vindo-.');
INSERT INTO verses VALUES (8827, 11, 3, 8, 'e-servidor-teu no-meio-de o-povo-teu que escolheste com muito que não ele-maneira e-não será-contado de-multidão');
INSERT INTO verses VALUES (8828, 11, 3, 9, 'e-darás para-o-servidor-teu coração ouviu para-julgar a o-povo-tuo para-entender entre que quem porque quem pode para-julgar a povo-teu o-grave a-esta');
INSERT INTO verses VALUES (8829, 11, 3, 10, 'e-foi-bom a palavra em-olhos-de Adonai que pediu Shelomoh a a palavra a-esta');
INSERT INTO verses VALUES (8830, 11, 3, 11, 'E-disse Elohim a-ele porque que pediste a a-coisa o-este e-não pediste para-você dias muitos e-não perguntaste para-ti dez e-não perguntaste alma teus-inimigos e-perguntaste a-ti entendeu para-ouvir juízo');
INSERT INTO verses VALUES (8831, 11, 3, 12, 'eis fiz segundo-teus-palavras eis dei dei a-ti sábio e-inteligente que como-ti não foi diante-de-ti e-depois-de-ti não levantar-se como-você');
INSERT INTO verses VALUES (8832, 11, 3, 13, 'e-tambem que não dei para-ti para-ti também dez também glória que não foi como-você homem em-os-reis todo teus-dias');
INSERT INTO verses VALUES (8833, 11, 3, 14, 'e-se andarás nos-caminhos-meus para-guardar os-mandamentos-meus e-os-comandos-meus como andou andar pai-teu e-estender-eu a teus-dias');
INSERT INTO verses VALUES (8834, 11, 3, 15, 'e-ele-adiou Salomão e-eis sonho e-ele-vieram Jerusalém e-ele-estabeleceu-se em-frente-de arca em-aliança-de Adonai e-subiu holocaustos E-fez paz E-fez banquete para-todo seus-servos');
INSERT INTO verses VALUES (8835, 11, 3, 16, 'então vireis duas mulheres meretrizes a o-rei e-vos-estabeleceis diante-de-ele');
INSERT INTO verses VALUES (8836, 11, 3, 17, 'E-disse a-mulher a-uma por-mim Adonai eu e-a-mulher a-esta habitando em-casa um e-eu-nasci com-ela na-casa');
INSERT INTO verses VALUES (8837, 11, 3, 18, 'e-houve no-dia o-terceiro para-parir e-ela-pariu também a-mulher esta e-nós juntos não-há estrangeiro com-nos na-casa exceto-eu dois- nós-mesmos em-a-casa:');
INSERT INTO verses VALUES (8838, 11, 3, 19, 'E-morreu filho-de a-mulher noite noite que deitou-se sobre-ele');
INSERT INTO verses VALUES (8839, 11, 3, 20, 'e-ele-levantou-se no-meio-de na-noite e-tomou a filhos-de de-mim e-a-sua-escrava dormiu e-ele-deitou-o em-o-peito-a e-a o-filho-a o morto e-deitou-a em-o-peito-meu');
INSERT INTO verses VALUES (8840, 11, 3, 21, 'e-ele-se-levantou na-manhã para-amamentar a filhos-de e-eis- a-ele e-ele-refletiu a-ele de-manhã e-eis não foi filhos-de que eu-pari');
INSERT INTO verses VALUES (8841, 11, 3, 22, 'E-disse a-mulher a-outra não porque filhos-de o-vivo e-filho-de-a o-morto e-esta dizendo não porque filho-de-a o morto e-filho-meu o-vivo e-disseram diante-de o rei');
INSERT INTO verses VALUES (8842, 11, 3, 23, 'E-disse o-rei esta dizendo este filhos-de o-vivo e-filho-teu o-morto e-esta não não porque filho-de-a o morto e-filho-meu o-vivo:');
INSERT INTO verses VALUES (8843, 11, 3, 24, 'E-disse o-rei tomem para-mim- espada a-espada a-espada diante-de o rei');
INSERT INTO verses VALUES (8844, 11, 3, 25, 'E-disse o-rei decidiram a o-menino o-vivo para-dois e-deite a o-meio para-uma e-com o-meio para-uma');
INSERT INTO verses VALUES (8845, 11, 3, 26, 'E-disse a-mulher que o-filho-seu o-vivo a o rei porque E-disse seus-compassivos sobre sua-filha e-disse por-mim Adonai dai- a-ela a o-nascido o-vivo e-o-morto não será e-esta dizendo-a também para-mim também para-ti não será decidam');
INSERT INTO verses VALUES (8846, 11, 3, 27, 'e-ele-respondeu o-rei E-disse dai- a-ela a o-nascido não e-a-morte não sua-mãe ela mãe-de ele');
INSERT INTO verses VALUES (8847, 11, 3, 28, 'e-ouviram todo Israel a o-julgamento que julgou de-diante-de e-viram que o-rei porque vede porque sabedoria-de Elohim em-meio-seu para-fazer juízo');
INSERT INTO chapters VALUES (295, 11, 4, 20);
INSERT INTO verses VALUES (8848, 11, 4, 1, 'e-houve o-rei Shelomoh rei sobre todo Israel');
INSERT INTO verses VALUES (8849, 11, 4, 2, 'e-aqueles os-senhores que a-ele Azariau filho-de Zadoque o-sacerdote');
INSERT INTO verses VALUES (8850, 11, 4, 3, 'Eliequor e-Achiea filhos-de Sisa dos-escreventes Jeosafá filho-de achilud o-mencionador-versículo');
INSERT INTO verses VALUES (8851, 11, 4, 4, 'e-Benaiáhu filho-de Jeoiada sobre o-exército e-Sadoque e-Abiatar sacerdotes-versículo');
INSERT INTO verses VALUES (8852, 11, 4, 5, 'e-Azarias filho-de deu sobre os-estabelecidos e-Zabud filho-de deu sacerdote amigo o rei');
INSERT INTO verses VALUES (8853, 11, 4, 6, 'e-Achishar sobre a-casa e-Adoniram filho-de servo-a sobre da-imposto');
INSERT INTO verses VALUES (8854, 11, 4, 7, 'e-para-salomo doze dez estabelecidos sobre todo Israel e-provisionaram-se a será e-a casa-dele novo na-ano será sobre para-provisão');
INSERT INTO verses VALUES (8855, 11, 4, 8, 'e-estes nomes-deles filho-de Hur em-monte-de Efrayim');
INSERT INTO verses VALUES (8856, 11, 4, 9, 'filho-de desequilíbrio em-o-macaco e-no-shaalvim e-Beit sol e-eilon casa Hanan');
INSERT INTO verses VALUES (8857, 11, 4, 10, 'filho-de Hesed a-ele a-ele soco e-todo terra chepor');
INSERT INTO verses VALUES (8858, 11, 4, 11, 'filho-de Avinadab todo Nafat [בַּת־שְׁלֹמֹ֔ה] era para-ele Shelomoh ela-foi a-ele para-mulher');
INSERT INTO verses VALUES (8859, 11, 4, 12, 'ban-anah filho-de achilud- taanakh- umegido- e-todo casa sha-an que debaixo-de tsartanah- mitachat- leyizreel- até sha-an até até mecola até meever leyaqommaam');
INSERT INTO verses VALUES (8860, 11, 4, 13, 'filho-de gever beratomot a-ele lo chavot yaair filho-de menasheh a-ele bagilad a-ele região-de Argob que em-Bashan [גְּדֹל֔וֹת] cidades grandes muralha e-como bronze');
INSERT INTO verses VALUES (8861, 11, 4, 14, 'Ahinadav filho-de Idoa acampamento-suíço-verso');
INSERT INTO verses VALUES (8862, 11, 4, 15, 'irmão-forte em-naphtali também tomou tomou a balsama filha-de Salomão para-mulher');
INSERT INTO verses VALUES (8863, 11, 4, 16, 'de-anã filho-de chusi em-asher e-em-alturas-verso');
INSERT INTO verses VALUES (8864, 11, 4, 17, 'Jeosafá filho-de purocha em-issacar-verso');
INSERT INTO verses VALUES (8865, 11, 4, 18, 'Shimi filho-de exceto em-Benjamim');
INSERT INTO verses VALUES (8866, 11, 4, 19, 'homem filho-de Uri em-terra-de terra terra Sihon rei o-amorreu e-Agog rei o basanita e-Nitzav um que na-terra');
INSERT INTO verses VALUES (8867, 11, 4, 20, 'Judá e-Israel muitos como-o-campo que sobre o-mar em-abundância comendo e-bebendo e-suficientes');
INSERT INTO chapters VALUES (296, 11, 5, 32);
INSERT INTO verses VALUES (8868, 11, 5, 1, 'e-Salomão ser rege em-todo as-mamlekhót terra o-river terra filisteus e-até território Egito fazendo aproximar oferta e-servos a Salomão todo dias-de vida-dele');
INSERT INTO verses VALUES (8869, 11, 5, 2, 'e-houve pão- Salomão um um trinta cor sōlet e-seis cor farinha-');
INSERT INTO verses VALUES (8870, 11, 5, 3, 'dez manhã em-os-bodes e-vinte manhã pastor e-de-cem ovelhas- para-fora de-capricórnios e-das-antilopes e-de-cabras-do-deserto e-de-caprinos abusim');
INSERT INTO verses VALUES (8871, 11, 5, 4, 'porque ele rodé- em-todo o-rio o-nahar mitpesach e-até azza o-rio melechey- ser a-ele veshalom foi para-ele de-todo avaraiv misaviv');
INSERT INTO verses VALUES (8872, 11, 5, 5, 'e-ele-estabeleceu-se Juda e-Israel em-segurança homem debaixo seus-olhos e-embaixo-de suas-macieiras desde-Dã e-até poço sete dias-de dias-de שְׁלֹמֹה');
INSERT INTO verses VALUES (8873, 11, 5, 6, 'e-houve para-Salomão quarenta mil coberturas-de-tenda cavaleiros para-sua-carroça e-dois- dez mil parashim');
INSERT INTO verses VALUES (8874, 11, 5, 7, 'e-killchu ha-nitzavim ha-eleh a o-rei Salomão ve-et todo ha-qarav a shulchan não Salomão homem chadsho não ye-adru palavra');
INSERT INTO verses VALUES (8875, 11, 5, 8, 've-ha-seorim e-o-tebem para-os-cavaleiros e-para-os-carros-de-guerra trarão a o-lugar que ele-será- nome homem conforme-seu-julgamento');
INSERT INTO verses VALUES (8876, 11, 5, 9, 'E-colocou Elohim sabedoria para-salomo e-entendimento muito muito e-largura coração como-o-cinzento que sobre o-mar o-mar:');
INSERT INTO verses VALUES (8877, 11, 5, 10, 'e-ela-se-multiplicou sabedoria-de Shelomoh de-sabedoria-de todo filhos-de antes e-de-todo sabedoria-de Egito');
INSERT INTO verses VALUES (8878, 11, 5, 11, 'e-ele-se-fez-sábio de-todo o-homem de-Eitan o-estrangeiro e-heiman e-kalkol e-darda filhos-de machol e-hiyeh- shemo em-todo ha-goyim ao-redor');
INSERT INTO verses VALUES (8879, 11, 5, 12, 'e-daber três dois-mil mashal e-houve seu-cântico cinco e-eu-aprendi');
INSERT INTO verses VALUES (8880, 11, 5, 13, 'e-falou sobre os-da-árvores de o-cedro que em-o-Líbano e-ate sai que saindo na-parede e-ele-falou sobre a-animal e-sobre a-ave e-sobre o-réptil e-sobre os-peixes');
INSERT INTO verses VALUES (8881, 11, 5, 14, 'e-vieram de-todo os-povos para-ouvir a sabed-ade Shelomoh de-com a-terra reis-de a-terra que ouviram a sabed-ad-o');
INSERT INTO verses VALUES (8882, 11, 5, 15, 'e-yi-shelakh chi-ram rei-de tiro a que a que ele ouviu porque debaixo ungir-am que em-lugar-de ser porque amou foi hiram para-David todo os dias');
INSERT INTO verses VALUES (8883, 11, 5, 16, 'e-enviou Shelomoh a dizendo para-dizer');
INSERT INTO verses VALUES (8884, 11, 5, 17, 'tu sab-e-s-tu a Davi que não não pode-r para-construir casa yhwh yhwh de-diante-de de-faces-de ha-milchamah que até até eles debaixo a-eles sob taças');
INSERT INTO verses VALUES (8885, 11, 5, 18, 'e-agora deixar yhwh Elohim-me a-mim em-o-redor não-há satan e-não-há encontro mal');
INSERT INTO verses VALUES (8886, 11, 5, 19, 'e-eis-me-aqui disse para-construir casa para-Shem yhwh Elohim-me como-que palavra yhwh yhwh Davi pai-meu dizendo seu-filho que darei sob-te sobre o-teu-trono ele construirá a-casa para-o-meu-nome');
INSERT INTO verses VALUES (8887, 11, 5, 20, 'e-agora ordene e-eles-cortarão- para-mim cedros de o-líbano e-meus-servos serão com teus-servos a-ti servos-teus darei para-ti que que tu que que conheceste porque não-há sabe homem conheceu para-cortar- madeiras como-os-fenícios');
INSERT INTO verses VALUES (8888, 11, 5, 21, 'e-houve quando-ouviu hiram a palavras-de Salomão muito E-disse E-disse yhwh o-dia o-dia dar deu filho filho chakham sobre o-povo haharav a-esta');
INSERT INTO verses VALUES (8889, 11, 5, 22, 'e-estendeu Hiram a dizendo dizendo ouvira a que enviara a-mim eu farei a todo o-teu-desejo em-a-árvore árvores-de-arazim e-na-materiais-de de-bet-roshim');
INSERT INTO verses VALUES (8890, 11, 5, 23, 'meus-servos descerão de do-libano mar-direção e-eu os-colocarei em-dobreth na-mar até o-lugar que enviar-ás a-mim e-dispersar-nos-eis nome e-tu levantarás e-tu pão a desejo-meu a-dar pão-de casa-minha');
INSERT INTO verses VALUES (8891, 11, 5, 24, 'e-houve Hirão deu para-Salomão árvores- ciprestes e-árvores- de-bros todo o-seu-desejo');
INSERT INTO verses VALUES (8892, 11, 5, 25, 'e-salomao dar para-chiram vinte mil cor trigo-s machalet para-a-sua-casa e-vinte cor óleo katit assim dê Salomão para-Hiram ano em-ano');
INSERT INTO verses VALUES (8893, 11, 5, 26, 'e-yhwh dar sabedoria para-Salomão conforme falou e-houve E-foi entre entre e-entre e-entre Shelomoh e-eles-cortaram berith dois-deles');
INSERT INTO verses VALUES (8894, 11, 5, 27, 'e-subiu o-rei Salomão tributo de-todo e-houve E-foi do-tributo trinta mil homem');
INSERT INTO verses VALUES (8895, 11, 5, 28, 'e-os-enviou de-Levona dez milhares em-o-mês trocas novo serão em-Levona dois novos em-a-casa-seu e-Adoniram sobre a-imposto');
INSERT INTO verses VALUES (8896, 11, 5, 29, 'e-houve para-Salomao setenta mil levando-o carregar e-oitenta mil cortando na-montanha');
INSERT INTO verses VALUES (8897, 11, 5, 30, 'para-afastamento de-ofícios os-estabelecidos para-Salomão que sobre a-obra três dois-mil e-três centenas os-comandantes no-povo os-fazendo na-trabalho');
INSERT INTO verses VALUES (8898, 11, 5, 31, 'E-ordenou o-rei e-ele-partiram pedras grandes pedras preciosas para-fundar a-casa pedras-de calcareas');
INSERT INTO verses VALUES (8899, 11, 5, 32, 'e-ele-rejeitou filhos-de Salomão e-construtores quiramo e-os-gibelins e-eles-prepararam os-madeiras e-as-pedras para-construir a-casa');
INSERT INTO chapters VALUES (297, 11, 6, 38);
INSERT INTO verses VALUES (8900, 11, 6, 1, 'e-houve em-oitenta ano e-quatro centenas-de anos para-sair filhos-de Israel de-a-terra-de Misraim em-a-ano a-quarta ele ziv ele o-mês o-segundo para-reinar E-edificou sobre Israel e-ele-construiu a-casa para-יהוה');
INSERT INTO verses VALUES (8901, 11, 6, 2, 'e-a-casa que edificar o-rei שְׁלֹמֹה a-yhwh e-trinta- cubit seu-comprimento e-vinte largura-dele e-trinta côvado altura-dele');
INSERT INTO verses VALUES (8902, 11, 6, 3, 'e-o-pátio sobre face-de o-santuário a-casa vinte côvado comprimento-dele sobre face-de largura a-casa dez em-a-unidade-de-medida de-sua-largura sobre face-de o-casa');
INSERT INTO verses VALUES (8903, 11, 6, 4, 'E-fez para-o-casa janelas-de translúcidas fechadas');
INSERT INTO verses VALUES (8904, 11, 6, 5, 'E-edificou sobre parede a-casa ao-redor a paredes a-casa ao-redor para-a-salão e-para-o-lugar E-fez costas ao-redor');
INSERT INTO verses VALUES (8905, 11, 6, 6, 'a-inferior cinco com-a-cubit largura-seu e-a-média seis na-côvado largura-dela e-a-terceira sete em-a-amá largura-sua porque de-molduras que para-a-casa dar fora para-não agarrar-se para-não da-casa');
INSERT INTO verses VALUES (8906, 11, 6, 7, 'e-o-lar em-a-sua-construção pedra- perfeita expedição foi-construído e-marretas e-a-machadinha todo instrumento de-ferro não foi-ouvido na-casa em-o-construí-lo');
INSERT INTO verses VALUES (8907, 11, 6, 8, 'porta a-costela a-ticônah a kêtêf a-casa a-direita e-blulím ya''alú sobre a-ticônah e-de a-te-média a a-shlísim');
INSERT INTO verses VALUES (8908, 11, 6, 9, 'E-edificou a a-casa ve-khaléhu ve-yispón a a-casa gebím e-suas-filas em-a-raizes');
INSERT INTO verses VALUES (8909, 11, 6, 10, 'E-edificou a sobre todo a-casa cinco côvados a-sua-altura e-pegou-se a a-casa em-a-árvore ciprestes');
INSERT INTO verses VALUES (8910, 11, 6, 11, 'e-houve palavra-de yhwh dizendo Salomão para-dizer');
INSERT INTO verses VALUES (8911, 11, 6, 12, 'o-casa o-este que tu construindo se vai-andar em-meus-regulamentos e-a e-em-meus-julgamentos tu-farás e-guardarás a todo as-minhas-mandamentos para-andar com-eles e-estabelecerei a minha-palavra com-tu que falei a Davi pai-teu');
INSERT INTO verses VALUES (8912, 11, 6, 13, 'e-habitar-ei-me no-meio-de filhos-de Israel e-não eu-deixarei a povo-meu Israel');
INSERT INTO verses VALUES (8913, 11, 6, 14, 'E-edificou Salomão a a-casa e-ele-o-completou');
INSERT INTO verses VALUES (8914, 11, 6, 15, 'E-edificou a muros a-casa de-a-casa em-as-sombras cedros de-a-terra a-casa até paredes árvore revestiu árvore de-casa e-ele-queimou a terra a-casa em-as-sombras de-cedros');
INSERT INTO verses VALUES (8915, 11, 6, 16, 'E-edificou a vinte cubit a-casa em-as-sombras cedros de a-terra até E-edificou a-ele a-ele de-casa para-o-lugar-santo para-a-santidade os-santos');
INSERT INTO verses VALUES (8916, 11, 6, 17, 'e-quarenta em-a-amá ser a-casa ele a-heicál para-frente-dele');
INSERT INTO verses VALUES (8917, 11, 6, 18, 'e-erez a a-casa pnimá de-maquela peka''im e-peturéi titsim o-todo erez pedra eben nireah');
INSERT INTO verses VALUES (8918, 11, 6, 19, 'udibir em-meio-de a-casa de-dentro hechin letiten nome a yhwh berit yhwh');
INSERT INTO verses VALUES (8919, 11, 6, 20, 'velifnei hadibir esrim cubit-o comprimento-o e-vinte cubit-a largura-o e-vinte côvado altura-dele e-cobriu-o-com ouro puro e-cobriu altar cedro-o');
INSERT INTO verses VALUES (8920, 11, 6, 21, 'e-cobriu Shlomoh a a-casa ouro ouro puro e-yavber zahav ouro o-santo-dos-santos ve-ytzapehu ouro');
INSERT INTO verses VALUES (8921, 11, 6, 22, 'e-a todo ouro revestiu ouro até completar-se todo ouro e-todo o-altar que la-dvir revestiu ouro');
INSERT INTO verses VALUES (8922, 11, 6, 23, 'E-fez no-oráculo segundo keruvim madeiras-de óleo dez côvados altura-dele');
INSERT INTO verses VALUES (8923, 11, 6, 24, 've-chamesh amos kenaf ha-keruv a-uma e-cinco côvados asa do-querubim a-segunda dez côvados das-pontas de-asas-sua e-até pontas asas-dele');
INSERT INTO verses VALUES (8924, 11, 6, 25, 'e-dez na-côvado o-querubim o-segundo medida uma e-extremidade um para-dois os-querubins');
INSERT INTO verses VALUES (8925, 11, 6, 26, 'altura o-querubim o-primeiro dez em-a-amá e-assim o-querubim o-segundo');
INSERT INTO verses VALUES (8926, 11, 6, 27, 'E-colocou com-o os-querubins no-meio-de a-casa o-interno e-eles-se-estenderam a as-asas os-querubins e-toque asa-de-o o-um na-parede e-asa o-querub o-segundo tangente-a em-o-muro o-segundo e-asas-deles a meio-de asa tangentes-a asa a asa');
INSERT INTO verses VALUES (8927, 11, 6, 28, 'e-estendeu a ouro ouro');
INSERT INTO verses VALUES (8928, 11, 6, 29, 'e-את todo muros a-casa de-em-redor rasgou aberturas de-ferraduras querubins e-tamarizes e-peturéi titsim de-dentro e-o-lacção-verso');
INSERT INTO verses VALUES (8929, 11, 6, 30, 'e-a terra a-casa ouro ouro em-a-internidade e-o-lacção-verso');
INSERT INTO verses VALUES (8930, 11, 6, 31, 'e-את entrada-de o-santo-dos-santos fez portas-de madeiras-de óleo o-abelhaia as-mezuzot a-cinquentanesima');
INSERT INTO verses VALUES (8931, 11, 6, 32, 'e-dois portas-de madeiras-de de-oleo e-furou em-eles de-furos de-querubins e-de-tamaris e-livres-de tumarcos ouro ouro e-descerrou sobre os-querubins e-sobre as-tamariscos a o-ouro');
INSERT INTO verses VALUES (8932, 11, 6, 33, 'e-assim fez para-a-porta do-templo os-laterais madeiras-de óleo de-com quartilho');
INSERT INTO verses VALUES (8933, 11, 6, 34, 'e-dois portas árvores-de beroshim segundo costelas a-porta a-uma rodilhos e-dois cordões a-porta a-segunda rodilhos');
INSERT INTO verses VALUES (8934, 11, 6, 35, 'e-cordão querubins e-datas e-folhas-de ramos e-oliveiras ouro que-foram-endireitadas sobre a-cortada');
INSERT INTO verses VALUES (8935, 11, 6, 36, 'E-edificou a o-pátio o-interno três de-muros de-pedra e-tur k-rutot ciprestes');
INSERT INTO verses VALUES (8936, 11, 6, 37, 'b-shana h-revi''it yussad casa yhwh b-yerah ziv');
INSERT INTO verses VALUES (8937, 11, 6, 38, 'u-b-shana h-achat esre em-o-luar no-mês-de-bul ele o-mês o-oitavo completou-a a-casa para-todo palavras-dele e-para-todo- e-ele-construiu-o sete dois');
INSERT INTO chapters VALUES (298, 11, 7, 51);
INSERT INTO verses VALUES (8938, 11, 7, 1, 'e-a edificar construiu-a Shelomoh três dez E-terminou e-ele-terminou a todo casa-dele');
INSERT INTO verses VALUES (8939, 11, 7, 2, 'E-edificou a casa-de bosque do-líbano cem cubit seu-comprimento e-cinquenta côvado em-ele-o-largura-seu e-trinta côvado de-le-o-altura-seu sobre quatro das-colunas-de colunas-de cedros e-cortes árvores-de-arazim sobre as-colunas');
INSERT INTO verses VALUES (8940, 11, 7, 3, 'e-ocultado na-cedro de-acima sobre as-maneiras que sobre os-pilares quarenta e-cinco cinco dez a-fileira-verso');
INSERT INTO verses VALUES (8941, 11, 7, 4, 'e-transparentes três fileiras e-o-visionamento a o-visionamento três vezes');
INSERT INTO verses VALUES (8942, 11, 7, 5, 'e-todo os-em-portas e-as-mezuzot quadrados o-espejo e-em-face-de o-visionamento a o-visionamento três vezes');
INSERT INTO verses VALUES (8943, 11, 7, 6, 'e-a o-hall as-colunas fez cinquenta côvado comprimento-dele e-trinta côvado largura-dele e-entretanto sobre suas faces e-colunas e-nuvem sobre em-seus-faces');
INSERT INTO verses VALUES (8944, 11, 7, 7, 'e-ou-lam o-cisso'' que יִשְׁפָּט־ nome a-lam o-mishpat fez e-sapun ba-erez'' de-hakarake'' até o-karake'':');
INSERT INTO verses VALUES (8945, 11, 7, 8, 'e-sua-casa que habitou nome courtyard- a-outra de-a-casa para-o-pátio como-o-trabalho ser foi e-na-casa fará para-filha-de tomou que tomou Shelomoh como-o-pátio a-esta');
INSERT INTO verses VALUES (8946, 11, 7, 9, 'todo estas אבנים preciosas- de-medidas de-pedra megerorot [מִבַּ֣יִת] de-casa e-de-fora e-de-a-sede até as-tapachot e-de-fora até o recinto a-grande');
INSERT INTO verses VALUES (8947, 11, 7, 10, 'e meyusad as avanim que sejam preciosas pedras grandes pedras dez covados e pedras oito amôtes׃');
INSERT INTO verses VALUES (8948, 11, 7, 11, 'uem-lmaalah pedras preciosas kemidot gazit waarez:');
INSERT INTO verses VALUES (8949, 11, 7, 12, 'vechatser a grande ao-redor três טוּרִ֣ים gazit e-tur krotot árvores-de-cedro velachatser casa-de yhwh happenimit e-para-a-parte-mais-interna a-casa');
INSERT INTO verses VALUES (8950, 11, 7, 13, 'e-enviou o-rei Shelomoh E-tomou a חִירָ֖ם de-Tsor');
INSERT INTO verses VALUES (8951, 11, 7, 14, 'filho-de mulher ele ele de-a-tribo Naftali e-pai-seu homem-de tsori carver nechosheth e-ele-cheio a a-chamah e-a ha-tevunah e-a ha-daat para-fazer todo trabalho de-nichoshet e-vaevoah a o-rei Shelomoh E-fez a todo trabalho-seu');
INSERT INTO verses VALUES (8952, 11, 7, 15, 'e-vayyatzar a segundo as-colunas bronze oito esre côvado altura o-primeiro הָאֶחָד ve-chut duas- dez Ammah yasev a ha-amud o-segundo');
INSERT INTO verses VALUES (8953, 11, 7, 16, 'u-shtey kotarot fez latet sobre topos-de ha-amudim fundido bronze cinco amos altura a-cortante a-uma ve-chamesh côvados altura a-cortante הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (8954, 11, 7, 17, 'espinhosos obra-de espinheira cabelos obra-de cordões para-a-cortante que sobre cabeça os-pilares sete- para-a-coroa a-uma e-sete para-a-coroa הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (8955, 11, 7, 18, 'E-fez a os postes e dois TOURÍM SÁVIB sobre HAŠŠAVAKÁH a primeira LÉKASÚT a HAČÓTARÓTÁN que sobre cabeça as figueiras e-assim fez LÁKOTÉRET HAŠŠENÍT:');
INSERT INTO verses VALUES (8956, 11, 7, 19, '[וְכֹֽתָרֹ֗ת] que sobre cabeça os-pilares obra-de rosa na-sala-de-entrada quatro cubits');
INSERT INTO verses VALUES (8957, 11, 7, 20, '[וְכֹתָרֹ֗ת] sobre segundo os-pilares também de-acima de-frente-para-a o-abdomen que para-o-lado-de e-os-citrus duzentos colunas ao-redor sobre a-que-corta הַשֵׁנִֽית׃');
INSERT INTO verses VALUES (8958, 11, 7, 21, 'E-levantou a os-marcadores para-o-pavilhão o-templo E-levantou a E-chamou o-direito E-chamou a nome-dele Jaquim E-chamou a a-coluna o-esquerdo E-chamou a nome-de-ele בֹּעַז');
INSERT INTO verses VALUES (8959, 11, 7, 22, 'e-sobre cabeça as-colunas obra-de rosa e-ela-se-esvaziou obra-de as-colunas');
INSERT INTO verses VALUES (8960, 11, 7, 23, 'E-fez a o-mar fundido dez em-a-amá da-borda-dele até borda-dele roda-ele ao-redor e-cinco na-côvado altura-seu trinta na-côvado ele-virá ele ele');
INSERT INTO verses VALUES (8961, 11, 7, 24, 'e-furos debaixo-de para-a-borda-seu ao-redor vá-girando a-ele ele na-côvado encirculando a o-mar ao-redor segundo fileiras os-furos forjados em-o-forjo-seu');
INSERT INTO verses VALUES (8962, 11, 7, 25, 'ficou-em-pé sobre segundo dez manhã três ponim para-o-norte e-três ponim para-o-mar ushloshah face para-o-sul e-três face para-o-nascente e-o-mar sobre-eles de-acima e-todo as-costas-deles para-dentro');
INSERT INTO verses VALUES (8963, 11, 7, 26, 'e-espessura-dele palmo e-a-língua-seu כְּמַעֲשֵׂ֥ה borda-de כוס floresceu de-rosa duzentos-e-cinquenta filha-de conterá');
INSERT INTO verses VALUES (8964, 11, 7, 27, 'E-fez a das-máquinas dez bronze quatro na-cubit comprimento-de da-máquina a-uma וְאַרְבַ֤ע na-côvado largura-dela e três em-a-amá altura-dela');
INSERT INTO verses VALUES (8965, 11, 7, 28, 'e-este obra-de a-máquina de-as-fechaduras a-eles e-de-as-fechaduras entre das-estacas');
INSERT INTO verses VALUES (8966, 11, 7, 29, 'e-sobre as-fechaduras que entre das-estacas leões manhã e-querubins e-sobre das-estacas assim  de cima e-mtachat para-a-ariot e-para-o-bakar lo-yot obra-de morad');
INSERT INTO verses VALUES (8967, 11, 7, 30, 'e-arbaa ofanei nechoshet para-a-mkona a-uma e-sarnei bronze e-quatro pés-seus omoplatas a-eles debaixo-de para-a-vasilha das-omoplatas forjas meever homem para-unir');
INSERT INTO verses VALUES (8968, 11, 7, 31, 'e-sua-boca de-a-casa para-a-coroa e-para-alto na-côvado e-sua-boca rodado obra-de- assim côvado וַחֲצִ֣י a-amá e-também sobre em-o-seu-fundo não e-suas-fechaduras quadradas não rodadas');
INSERT INTO verses VALUES (8969, 11, 7, 32, 'e-quatro-de- os-rolos para-baixo para-as-mesquitras e-as-mãos as-rodas na-plataforma e-a-altura-de a-roda o-primeiro côvado e-metade-de o-cubit-versículo-final');
INSERT INTO verses VALUES (8970, 11, 7, 33, 'e-ação אוֹפַנִּים como-ação o opên a merkabah suas-mãos e as coberturas e os folegos e as costuras todo o que forja');
INSERT INTO verses VALUES (8971, 11, 7, 34, 'e-quatro de-os-ombros a quatro as-parteiras a-maquina a-uma de a-maquina de-seus-ombros');
INSERT INTO verses VALUES (8972, 11, 7, 35, 'e-na-cabeça a-maquina chatzi- o-om que se levantem rodado ao-redor e-sobre cabeça a-maquina de-seus-braços e-de-sua-fechaduras de-elas');
INSERT INTO verses VALUES (8973, 11, 7, 36, 'e-abriu sobre os-tabuin de-a-sua-mão e-sobre querubins lebres e-tamarindos como-caverna- homem e-lavandas ao-redor');
INSERT INTO verses VALUES (8974, 11, 7, 37, 'assim fez a dez as-máquinas fundido um medida uma cabeça-de-ferro um para-todas-as');
INSERT INTO verses VALUES (8975, 11, 7, 38, 'E-fez dez כִּי-יוֹרֹת bronze quarenta bat- ya''cil- o cáiro o primeiro o-primeiro na-côvado o cáiro o primeiro o-primeiro um um a-mo-ca-na a primeira para dez as-bases');
INSERT INTO verses VALUES (8976, 11, 7, 39, 'E-colocou a as machonot cinco sobre ombro a-casa direito e cinco sobre kêtêf dar de-su-lho e-a o-mar deu do-lado o-bi-t a-direita ao-oriente de-em-frente-de negue:');
INSERT INTO verses VALUES (8977, 11, 7, 40, 'E-fez Hirom a os-bacias e-a E-terminou e-a as-bacias e-completou Hiram para-fazer a todo a-obra yhwh fez para-o-rei Salomão casa yhwh');
INSERT INTO verses VALUES (8978, 11, 7, 41, 'colunas dois e-bolhas as-cotárot que sobre cabeça os-amadim duas e-as-redes dois para-cobrir a dois-de fontes-de as cortarot que sobre cabeça as-colunas');
INSERT INTO verses VALUES (8979, 11, 7, 42, 'e-a os-ramidnim quatro centenas para-duas-de as-redes dois fileiras-de rimdim para-a-rede a-uma para-cobrir a dois-de fontes-de as cortarot que sobre face-de as-colunas');
INSERT INTO verses VALUES (8980, 11, 7, 43, 'e-a as-bases dez e-a as-kiyorot asará sobre as-bases');
INSERT INTO verses VALUES (8981, 11, 7, 44, 'e-a o-primeiro o-echad e-a debaixo o-mar dez debaixo-de o-mar');
INSERT INTO verses VALUES (8982, 11, 7, 45, 'e-a as-sirot e-a os-yayim e-a as-mizraquot e-את todo os utensílios que fez hiram para-o-rei yhwh casa yhwh bronze מְמֹרָֽט׃');
INSERT INTO verses VALUES (8983, 11, 7, 46, 'em-planície-de o-Jordão fundiu-os o-rei bemaave a-terra entre Sucote e-entre tsartan');
INSERT INTO verses VALUES (8984, 11, 7, 47, 'e-deixou שְׁלֹמֹה a todo muito muito não muito não investigado peso-de o-bronze');
INSERT INTO verses VALUES (8985, 11, 7, 48, 'E-fez Shelomoh a todo os-vasos que yhwh yhwh a o-ouro o-ouro e-a hashulchan pão sobre-ele ouro as-faces ouro');
INSERT INTO verses VALUES (8986, 11, 7, 49, 'e-a hammanorot cinco de-a-direita והמשה mismaol diante-de ouro ouro puro e-a-flor vehannerot ouro ouro');
INSERT INTO verses VALUES (8987, 11, 7, 50, 'vesifot e-as-tesouras e-as-bacias e-as-colheres e-os-incensários ouro puro vephotot ledaltoth o-casa o-interno para-santo-de os-santos para-as-portas a-casa para-o-templo ouro');
INSERT INTO verses VALUES (8988, 11, 7, 51, 'e-foi-completada todo a-obra que fez o-rei Salomão yhwh e-trouxe E-veio שְׁלֹמֹה a santos-de seu-pai pai-de-ele a a-prata dar o-ouro e-a yhwh deu em-tesouros-de casa yhwh');
INSERT INTO chapters VALUES (299, 11, 8, 66);
INSERT INTO verses VALUES (8989, 11, 8, 1, 'entao yakheil Shelomoh a anciaos-de Israel a todo cabeças-de ha-matot nesiei os-pais li-bnei Israel a o-rei Salomão Jerusalém para-fazer-subir a arca-de em-aliança-de yhwh de-cidade-de Davi ela צִיּֽוֹן');
INSERT INTO verses VALUES (8990, 11, 8, 2, 'vayíqqáhălu a o-rei שְׁלֹמֹה todo homem Israel no-mês-de ele na-festa ele o-mês הַשְׁבִיעִֽי׃');
INSERT INTO verses VALUES (8991, 11, 8, 3, 'e-vieram todo anciãos-de Israel e-levantaram os-sacerdotes a a-arca');
INSERT INTO verses VALUES (8992, 11, 8, 4, 'va-ya''alu a yhwh yhwh e-a tenda encontro e-com todo instrumentos-de eles que na-tenda e-subiram a-eles os-sacerdotes ve-halviyim');
INSERT INTO verses VALUES (8993, 11, 8, 5, 'e-o-rei Salomão e-todo congregação-de Israel os-nomades sobre-ele com-ele diante-de o-arca sacrificando ovelhas e-gado que não serão-contados e-não serão-numerados de-multidão');
INSERT INTO verses VALUES (8994, 11, 8, 6, 'e-ele-trouxeu os-sacerdotes a arca-de em-aliança-de yhwh a lugar-de-ele a Debir a-casa a santo-de ha-kodashim a sob asas-de os-querubins');
INSERT INTO verses VALUES (8995, 11, 8, 7, 'que os-querubins estendendo asas a lugar-de o-aron os-querubins os-querubins sobre a-arca e-sobre varas-de-ela de-acima');
INSERT INTO verses VALUES (8996, 11, 8, 8, 'e-os-alargaram as-varas e-foram-vistas cabeças-de as-varas de a-santidade sobre face-de o-santo-dos-santos e-não serão-vistas o-exterior até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (8997, 11, 8, 9, 'não-havia na-arca somente segundo as-tábuas הָאֲבָנִים que ele-deitou nome Moisés em-חֹרֵב que cortou yhwh com filhos-de Israel em-sair-de-eles de-terra-de Egito');
INSERT INTO verses VALUES (8998, 11, 8, 10, 'e-houve em-sair os-sacerdotes de a-santidade e-a-névoa enchei yhwh casa yhwh');
INSERT INTO verses VALUES (8999, 11, 8, 11, 'e-não podiam hakohanim para-estar de-diante-de de-diante-de o-nuvem porque enchei yhwh yhwh a casa yhwh');
INSERT INTO verses VALUES (9000, 11, 8, 12, 'então disse Shelomoh yhwh disse liscón na-trevas');
INSERT INTO verses VALUES (9001, 11, 8, 13, 'bano baniti casa zbul para-ti makhon para-a-tua-sentada pelos-dias');
INSERT INTO verses VALUES (9002, 11, 8, 14, 'e-voltou-se o rei a E-abençoou E-abençoou a todo assembleia Israel e-todo assembleia Israel ficou-em-pé');
INSERT INTO verses VALUES (9003, 11, 8, 15, 'E-disse bendito yhwh Elohim-de Israel que palavra em-seu-boca a Davi pai-meu e em sua mão enchei dizendo');
INSERT INTO verses VALUES (9004, 11, 8, 16, 'de o-dia que eu tirei a meu-povo a Israel de-toda não bacharti em-cidade de-todo tribos-de Israel para-construir casa a-ser nome-meu nome e-eleger b''David ser sobre povo-meu Israel');
INSERT INTO verses VALUES (9005, 11, 8, 17, 'e-houve com para-coracao Davi pai-meu para-construir casa yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (9006, 11, 8, 18, 'E-disse yhwh a Davi pai-meu porque ser foi com para-o-teu-coracao para-construir casa que ser porque foi com ao-teu-coração');
INSERT INTO verses VALUES (9007, 11, 8, 19, 'somente tu não construire-a a-casa que se filho-te o-saído do-seu-arranjo ele construirá a-casa para-o-meu-nome');
INSERT INTO verses VALUES (9008, 11, 8, 20, 'E-levantou yhwh a palavra-seu que palavra debaixo em-baixo Davi meu-pai e-eu-sentei-me sobre trono-de Israel como-que yhwh yhwh e-eu-construí a-casa yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (9009, 11, 8, 21, 'va''asem nome lugar laaron que nome yhwh yhwh que cortou- com eles em-sair-o eles de-terra-de Egito');
INSERT INTO verses VALUES (9010, 11, 8, 22, 'e-ficou-em-pé Salomão diante-de altar-de yhwh diante todo assembleia Israel vayifros as-suas-mãos os-céus');
INSERT INTO verses VALUES (9011, 11, 8, 23, 'E-disse yhwh Elohim-de Israel não-há como-tu Elohim nos-céus de-acima e-sobre a-terra de-baixo-de guardador-de a-aliança e-o-chessed laavadecha haholchim diante-de-ti em-todo os-cor-deles');
INSERT INTO verses VALUES (9012, 11, 8, 24, 'que shamartha para-servo-teu Davi pai-meu a que a-ele a-ele vate-daber be-picha uveyadcha miletha como-o-dia a-esta');
INSERT INTO verses VALUES (9013, 11, 8, 25, 'e-agora yhwh Elohim-de Israel guarda para o teu servo Davi pai-meu a que falaste a-ele para-ele dizendo ser cortada a-ti homem de-diante-de-mim habitou sobre trono-de Israel somente se eles-guardarem vossos filhos a דַּרְכָּם para-andar diante-de-mim como-que não perante mim:');
INSERT INTO verses VALUES (9014, 11, 8, 26, 'e-agora Elohim-de Israel se-crede-seja por-favor que falaste para-servir-teu Davi pai-meu');
INSERT INTO verses VALUES (9015, 11, 8, 27, 'que o-aumenta-se-realmente- habitou Elohim sobre eis eis que os-céus e-nomes-de não não certamente também porque a casa este que construí-eu');
INSERT INTO verses VALUES (9016, 11, 8, 28, 'e voltaste a oração servo teu yhwh sua misericórdia yhwh meu-Elohim para ouvir a gritaste e-a esta oração o-dia servo teu que ora diante-de-ti o-dia');
INSERT INTO verses VALUES (9017, 11, 8, 29, 'para-ser as-olhos-teus abertos a a-casa o-este noite e-o-dia a o-lugar será tu-disseste será nome-meu nome para-ouvir a a-oração que oraará a-escravo-teu a o-lugar a-esta');
INSERT INTO verses VALUES (9018, 11, 8, 30, 'e-audirás a súplica teu-servo e-o-povo-teu Israel que orarão a o-lugar esta e-tu audirás a lugar-de da-estada-teu a os-céus e-ouvirás e-perdonarás');
INSERT INTO verses VALUES (9019, 11, 8, 31, 'את que pecará homem para-o-amigo e-perdoar-á nele אָלָ֖ה para-cursar-no-lei-o-seu e-vem curse diante-de do-tua-altar na-casa a-esta');
INSERT INTO verses VALUES (9020, 11, 8, 32, 'e-você tishma os-céus וְעָשִׂ֙יתָ֙ e-julgara-á a teus-servos para-harcevar perverso-o a-dar caminho-dele na-sua-cabeça e-para-o-justificar צַדִּיק para-dar a-ele como-a-sua-justiça');
INSERT INTO verses VALUES (9021, 11, 8, 33, 'em-o-nagref o-seu-povo Israel diante-de o-inimigo que pecarão- a-ti e-retornarão a-ti e-confessarão a nome-teu e-vi-tefalo e-vocem-se-implorarão a-ti na-casa a-esta');
INSERT INTO verses VALUES (9022, 11, 8, 34, 'e-tu tishma os-céus e-perdoarás para-o-peca-do teu-povo Israel e-hashbotham a a-terra que nathastha לאבותם׃');
INSERT INTO verses VALUES (9023, 11, 8, 35, 'em-o-eatser céus e-não será que porque pecarão- a-ti e-vi-tefalo a o-lugar o-este e-confessarão que nome-teu u-mekhatatham voltarão-eles porque castigá-los');
INSERT INTO verses VALUES (9024, 11, 8, 36, 'e tu ouvir-vos-ereis os-céus e perdoaste por transgressão teus-servos e ao teu povo Israel porque que a o caminho hatovah que vão nela e dará por chuva sobre tua-terra que yhwh ao teu povo para herança');
INSERT INTO verses VALUES (9025, 11, 8, 37, 'fome porque na-terra na-terra palavra porque será multiplicarei yerakon que será que será porque formou- para-ele o-inimigo-seu na-terra suas-portas todo praga todo doença');
INSERT INTO verses VALUES (9026, 11, 8, 38, 'todo oração todo súplica que a-todo para-todo o-homem para-todo teu-povo Israel que conhecerão homem praga coração-dele e-esticou as-suas-mãos a a casa a-esta');
INSERT INTO verses VALUES (9027, 11, 8, 39, 'e-tu você-escutará os-céus deposição sentar-se-teu e-perdoarás וְעָשִׂ֔יתָ e-tu-porás para-o-homem conforme-toda seus-caminhos que saberás a לבבו porque tu tu-conheceste o-homem a para-coracao todo filhos-de o-homem');
INSERT INTO verses VALUES (9028, 11, 8, 40, 'a-fim-de temer-te-ão todo os-dias vida eles a-terra sobre deste a-adama que dei-te para-os-avós-nossos');
INSERT INTO verses VALUES (9029, 11, 8, 41, 'e-também a o-extranjero que não ele Israel ele e-virá de-terra-de afastada para שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (9030, 11, 8, 42, 'que eles-ouvirão a teu-nome a-grande e-a mão-tua a-posse-forte e-a-tua-mão ha-netuya וּבָ֥א e-orarás a a casa a-esta');
INSERT INTO verses VALUES (9031, 11, 8, 43, 'tu você-ouvirá os-céus lugar sua-ocupação e farás conforme-tudo que ele-chamará a-ti o-extranjero para-que sabê-lo-ão a-terra nações-de a-terra a seu-nome para-o-timor o-te כּוּעַםֶךָ֣ Israel e-para-conhecer porque teu-nome é-chamado sobre a casa este que construí-eu');
INSERT INTO verses VALUES (9032, 11, 8, 44, 'porque ele-sairá seu-povo para-a-guerra sobre oayavo no-caminho que lançar-e-os o-caminho-de a yhwh caminho a-cidade que escolheste-tu em-ela e-o-bayit que construí para-nome-teu');
INSERT INTO verses VALUES (9033, 11, 8, 45, 'e-ouviste-tu os-céus a oração-deles e-a súplica-deles e-tu-farás juízo-deles');
INSERT INTO verses VALUES (9034, 11, 8, 46, 'que pecarão-e que porque homem homem que não pecaram: e-furioso-te -os e-dar-vos-eles diante-de אֹיֵב e-voltá-los voltados-deles a terra o-inimigo afastada ou próxima');
INSERT INTO verses VALUES (9035, 11, 8, 47, 'e-voltar-eles a libbam na-terra que foram-capturados- nome e-voltar-os e-suplicaram a-ti em-a-terra dizendo dizendo chatanu e-voltá-nos reprovamos-vos');
INSERT INTO verses VALUES (9036, 11, 8, 48, 'e-voltarão a-ti em-todo para-o-coracao-deles e-em-todo נַפְשָׁ֔ם em-terra-de eles que voltaram o-caminho-de e-vocem-se-implorarão a-ti deste a-sua-terra que nattaha para-os-pais-eles a-cidade que escolheste-o e-o-bayit que para-nome-teu');
INSERT INTO verses VALUES (9037, 11, 8, 49, 'e-ouviste os-céus de-lugar da-sentada-tua a oração-deles e-a súplica-deles e-tu-farás juízo-deles');
INSERT INTO verses VALUES (9038, 11, 8, 50, 'e-perdoarás para-povo-teu que chatu- para-ti e-para-todo- das-transgressões-deles que transgrediram- bakh e-darás-eis para-misericórdias diante-de das-conversões-deles');
INSERT INTO verses VALUES (9039, 11, 8, 51, 'porque povo-teu eles eles que lançaste do-Egito de-meio-de cova o-ferro-verso');
INSERT INTO verses VALUES (9040, 11, 8, 52, 'ser os teus olhos abertos a misericórdia teu-servo e-a misericórdia teu-povo Israel para-ouvir a-eles em-todo chamá-los para-ti');
INSERT INTO verses VALUES (9041, 11, 8, 53, 'porque você a-ti para-ti de-toda de-todo a-terra a-terra como-que falaste em-mão-de Moisés teu servo que me tiraste a nosso pais de-misraim Adonai yhwh');
INSERT INTO verses VALUES (9042, 11, 8, 54, 'e-houve kechaloth Salomão para orar a yhwh a todo a oração e a misericórdia esta levantou-se diante de yhwh yhwh de joelhos sobre nas pernas e nas mãos abertas os-céus');
INSERT INTO verses VALUES (9043, 11, 8, 55, 'e-levantou-se E-abençoou a todo assembleia voz voz dizendo para-dizer');
INSERT INTO verses VALUES (9044, 11, 8, 56, 'bendito yhwh que dar מנוחה לעמו Israel como tudo que palavra não נפל um de-toda de-todo דברו o-bom que palavra em-mão Moisés seu-servo');
INSERT INTO verses VALUES (9045, 11, 8, 57, 'haja yhwh אֱלֹהִים-nosso conosco-s como-que ser com nossos-pais a יעזבנו e-a יתשנו׃');
INSERT INTO verses VALUES (9046, 11, 8, 58, 'להטות לבבנו a-ele para-andar em-todo דרכיו ולשמור suas-m Mandamentos e-sus Statutos e-sus Testemunhos que ordenou a nosso-Pai');
INSERT INTO verses VALUES (9047, 11, 8, 59, 'e-sejam minhas-Palavras Estas que implorando diante-de yhwh próximos a yhwh Elohim-nosso dia e-noite para-fazer juízo seu servo e julgamento seu-povo Israel palavra-de dia em-dia-de-o');
INSERT INTO verses VALUES (9048, 11, 8, 60, 'para-que conhecimento todo a-terra que yhwh ele ele o-Elohim não ainda');
INSERT INTO verses VALUES (9049, 11, 8, 61, 'e-era vosso-coração paz povo yhwh Elohim-nosso para andar em suas leis e-para-guardar em seus mandamentos como-o-dia a-esta');
INSERT INTO verses VALUES (9050, 11, 8, 62, 'e-o-rei e-todo Israel com-ele oferecendo-sacrifícios sacrifício-masculino-singular yhwh yhwh');
INSERT INTO verses VALUES (9051, 11, 8, 63, 'e-sacrificou Salomão a sacrifício-de as-ofertas-de-paz que sacrificou para-יהוה manhã vinte e-dois mil e-ovelhas cem e-vinte mil e-eles-beberam a yhwh yhwh o-rei e-todo filhos-de Israel');
INSERT INTO verses VALUES (9052, 11, 8, 64, 'no-dia aquele consagrou o-rei a meio-de haçaçér que diante-de casa-de yhwh porque fez ali a ha-olah e-a a oferta-cereais e-a de-a-cremes yhwh porque altar-de o-bronze que diante-de yhwh pequeno desde-o-início a a-oferta-quente e-a a oferta-cereais e-a de-a-gordura os-sacrifícios-de-paz');
INSERT INTO verses VALUES (9053, 11, 8, 65, 'E-fez Shelomoh na-época- -essa a o-festival e-todo Israel com-ele assembleia grande de-levar ira- até vale-de yhwh diante-de yhwh nosso-Elohim sete dias quatro dias dia dez dia');
INSERT INTO verses VALUES (9054, 11, 8, 66, 'no-dia o sétimo enviou a o-povo e-ele-bendizem a o-rei e-andaram para-os-tendas-deles alegres- sobre coração sobre todo yhwh que fez yhwh a-David servo-seu e-a-israel povo-dele');
INSERT INTO chapters VALUES (300, 11, 9, 28);
INSERT INTO verses VALUES (9055, 11, 9, 1, 'e-houve kechaloth Shelomoh para-construir a casa-de yhwh e-a casa o-rei e-את todo cheshek Shelomoh que חָפֵ֖ץ para-fazer');
INSERT INTO verses VALUES (9056, 11, 9, 2, 'E-viu yhwh a Salomão segunda como a-ele a-ele em-Gibeon');
INSERT INTO verses VALUES (9057, 11, 9, 3, 'E-disse yhwh a-ele ouvira-eu a oração-teu e-a súplica-teu que suplicaste para-perante-mim consagrei-eu a a-casa o-este que construíste e-sejam שמי nome até eternidade e-foram meus-olhos e-meu-coração nome todo os dias');
INSERT INTO verses VALUES (9058, 11, 9, 4, 'e-tu se andarás ante-me andar andou Davi teu-pai b''tam- coração e em prosperidade para fazer ordenei-te que tzuitichakha minhas leis não guarda');
INSERT INTO verses VALUES (9059, 11, 9, 5, 'e-elevar-eu a trono seu-reino para-sempre Israel para-sempre como-que falei-eu dizendo Davi a-ti dizendo de-cima-de será-cortado para-ti homem de-sobre trono-de Israel');
INSERT INTO verses VALUES (9060, 11, 9, 6, 'se novamente voltareis vós e-seus-filhos de-mim e-não guardareis mandamentos-meus minhas ordenanças dei dei diante-vos e se vós marchardes e-servireis Elohim outros a-eles para-eles');
INSERT INTO verses VALUES (9061, 11, 9, 7, 'e-cortarei a de-cima-de face-de a-terra a-terra dei a-eles a-eles e-a a-casa que o-sanctifiquei-eu de-cima-de eu lançarei de-sobre face-de ve-hâyâ: Israel para-exemplo e-para-repetição em-todo o-povos');
INSERT INTO verses VALUES (9062, 11, 9, 8, 'e-a-casa o-este será altíssimo todo passando sobre-ele ele-dormirá e-grasnará e-diretriz sobre yhwh fez yhwh assim para-a-terra a-esta e-a-casa a-esta');
INSERT INTO verses VALUES (9063, 11, 9, 9, 'e-diretriz sobre que deixaram a yhwh deles os elohimes que trouxe a seus pais da-terra Egito e se fortaleceram em elohim outros a-eles e serviram-lhes sobre sim yhwh yhwh sobre-eles a todo o-mal a esta');
INSERT INTO verses VALUES (9064, 11, 9, 10, 'e-houve de-a-extremidade-de vinte ano que banah Salomão a segundo yhwh a casa yhwh e-a casa o rei');
INSERT INTO verses VALUES (9065, 11, 9, 11, 'Cirem rei-de צר nishshua a שְׁלֹמֹה ba''atzey arazim uva''atzey beroshim uva''zahav para-todo chafetzoo az dê o-rei שְׁלֹמֹה lechiram vinte cidade em-terra-de o galil');
INSERT INTO verses VALUES (9066, 11, 9, 12, 'e-saiu chiram mitzar para-ver a as-cidades que natan- a-ele Shelomoh e-não yasru em-seus-olhos');
INSERT INTO verses VALUES (9067, 11, 9, 13, 'E-disse quanto ha-arim estes que a-mim para-mim E-chamou a-eles terra terra até o-dia o-dia a-esta');
INSERT INTO verses VALUES (9068, 11, 9, 14, 'e-enviou chiram para o rei cem e-vinte cicar ouro');
INSERT INTO verses VALUES (9069, 11, 9, 15, 'וְזֶ֨ה palavra-de o mas que e levou o-rei Salomão para construir yhwh casa yhwh e-a sua-casa e-a o repleto e-a muro-de Jerusalém e-a a muralha e-a Megido e-a Gazerá:');
INSERT INTO verses VALUES (9070, 11, 9, 16, 'Faraó rei-de subir subiu e-ele-capturou a Gazerá e queimou-a no-fogo e-a o-cananeu o morador na cidade הרג וה נתנה֙ שליחים לבתוֹ mulher-de שְׁלֹמֹה');
INSERT INTO verses VALUES (9071, 11, 9, 17, 'E-edificou שְׁלֹמֹה a [וְאֶת־בֵּ֥ית] e-a casa');
INSERT INTO verses VALUES (9072, 11, 9, 18, 'e-com [וְאֶת־*תמר] e-a em-o-midbar na-terra');
INSERT INTO verses VALUES (9073, 11, 9, 19, 'e-a todo cidades-de hamiskenot que foram para-Salomão e-את cidades-de o-carro e-a cidades-de hapharashim e-את cheshek Salomão que chasak para-construir [בִּירוּשָׁלִַ֙ם֙] uvavalbonon e em tudo terra sua soberania:');
INSERT INTO verses VALUES (9074, 11, 9, 20, 'todo o-povo hano''tar de o-amorreu o-חִתִּ֤י o-perizeu hachivi vehayevusi que não de-filhos-de Israel eles');
INSERT INTO verses VALUES (9075, 11, 9, 21, 'בְּנֵיהֶ֗ם que [נֹתְר֤וּ] depois-deles na-terra que não conseguiram- filhos-de Israel [וַיַּעֲלֵ֤ם] e-ele-subiu-os שְׁלֹמֹה até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (9076, 11, 9, 22, 'e-de-filhos-de Israel não deu Salomão servo porque eles homens-de a-guerra e-de-sus-servos [וְשָׂרֵ֥י] [רִכְבּ֖וֹ] e-príncipes-de rikbo- e-os-cavaleiros-seus');
INSERT INTO verses VALUES (9077, 11, 9, 23, 'Estas príncipes-de [שָׂרֵ֣י] que sobre הַמְּלָאכָה para-Salomão cinquenta e-cinco centenas os-comandantes no-povo os-fazendo na-trabalho');
INSERT INTO verses VALUES (9078, 11, 9, 24, 'porém filha-de פַּרְעֹה alathah de-a-cidade Davi a na-casa-de-ela que edificar para ela então banah a');
INSERT INTO verses VALUES (9079, 11, 9, 25, 'e-ele-ofereceu [שְׁלֹמֹ֡ה] três [פְּעָמִ֨ים] [בַּשָּׁנָ֜ה] עֹלוֹת [וּשְׁלָמִ֗ים] sobre o-altar edificar construiu-a para-יהוה [אִתּ֔וֹ] com-ele que yhwh yhwh [אֶת־הַבָּֽיִת] a a-casa');
INSERT INTO verses VALUES (9080, 11, 9, 26, 'וָאֳנִ֡י fez o-rei שְׁלֹמֹה em- Zionist homem que a altos sobre beira-de mar-de suf em-terra-de Edom');
INSERT INTO verses VALUES (9081, 11, 9, 27, 'e-enviou Chiram em- navio a seus-servos homens-de conhecendo o-mar ha-yam povo servos-de שְׁלֹמֹה');
INSERT INTO verses VALUES (9082, 11, 9, 28, 'e-vieram Ophir e-tomaram de-lá ouro ארבע- centenas e-vinte cicero e trouxeram a o-rei שְׁלֹמֹה');
INSERT INTO chapters VALUES (301, 11, 10, 29);
INSERT INTO verses VALUES (9083, 11, 10, 1, 'e a rainha- שָׁבְא ouvindo-a a ouviu yhwh para-nome-de yhwh וַתָּבוֹא לִנְסֹתֵהוּ בְּחִידֹות׃');
INSERT INTO verses VALUES (9084, 11, 10, 2, 'e-veio [יְרוּשָׁלְַ֗מָה] [בְּחַיִל֮] pesado muito [גְּ֠מַלִּים] noseim em-samesh e-ouro chefe-de muito e-eben yekara e-ela-veio a a-ele e falou para-ele ser todo que foi com cor-a-dele-ela-marcador');
INSERT INTO verses VALUES (9085, 11, 10, 3, 'e-contou para-ela Salomão a todo palavras-a-dele-ela-acento não foi não declarou de o-rei que não disse a-ela');
INSERT INTO verses VALUES (9086, 11, 10, 4, 'E-viu rainha-da Sheba-a-acento a todo sabedoria-de Shelomoh edificar que construiu-marcador');
INSERT INTO verses VALUES (9087, 11, 10, 5, 'e alimento sua mesa e convívio os seus servos e os que administram e suas vestimentas e seus bezerros e seu holocausto que subira casa subia e-não yhwh nela ainda espírito');
INSERT INTO verses VALUES (9088, 11, 10, 6, 'E-disse a o-rei ser foi a-palavra que ouvi em-a-terra-meu sobre palavras-teus e-sobre sabedoria-tua');
INSERT INTO verses VALUES (9089, 11, 10, 7, 'e-não creu-ei até até que ven-ei e-viu-as meus-olhos e-eis não הִגַּד־ a-mim [אֶל־הַשְּׁמוּעָ֖ה] [אֲשֶׁ֥ר] sabedoria e-bom a o-ouvido que shama''ti');
INSERT INTO verses VALUES (9090, 11, 10, 8, 'אַשְׁרֵי homens-teus אַשְׁרֵ֖י servos-teus Estas [הָֽעֹמְדִ֤ים] em-te תמיד [הַשֹּׁמְעִ֖ים] a sabedoria-tua');
INSERT INTO verses VALUES (9091, 11, 10, 9, 'haja yhwh Elohim-teu bendito que querendo a-você [לְתִתְּךָ֖] sobre trono-de Israel yhwh yhwh para-sempre Israel para-sempre [לַעֲשׂ֥וֹת] para-o-rei para-fazer e justiça');
INSERT INTO verses VALUES (9092, 11, 10, 10, 'e-deu para-o-rei cem e-vinte circularidade ouro ouro muito muito muito yekara não veio [כַבֹּ֨שֶׂם] o mesmo ainda para-o-muitos que Natanah: rainha-da sabeu para-o-rei שְׁלֹמֹה');
INSERT INTO verses VALUES (9093, 11, 10, 11, 'e-também Aní Cirão que ouro ouro do Ophir- trouxe do Ophir- madeiras de álmugues muito muito e-pedra-de 莊嚴׃');
INSERT INTO verses VALUES (9094, 11, 10, 12, 'E-fez o-rei a madeiras-de as-almeús comida para-casa-de yhwh -e-casa o-rei -e-liras não para-os-musicos não veio- assim de-árvore até o-dia foi-visto até o-dia a-esta');
INSERT INTO verses VALUES (9095, 11, 10, 13, '-e-o-rei שְׁלֹמֹה dar para- rainha- Sh''va a todo seu- desejo- que sha''alá מִלּוֹבַד que deu para-ela como-seu- braço- o-rei Shelomoh e- ela- se virou- e-foi para-sua- terra- ela e- seus- servos-');
INSERT INTO verses VALUES (9096, 11, 10, 14, 'e-aconteceu peso o-ouro que veio para-Salomão no ano um seis de-cem sessenta e-mármore ouro ouro');
INSERT INTO verses VALUES (9097, 11, 10, 15, 'sozinho- de-homens dos-eretos e-mischar dos-receptores e-todo reis-de a-noite a-terra a-terra');
INSERT INTO verses VALUES (9098, 11, 10, 16, 'E-fez o-rei Salomão duzentos tinah ouro escorrido seis-de ouro subia ele-subirá sobre a-tinah HA''ECHAT:');
INSERT INTO verses VALUES (9099, 11, 10, 17, 'e-três- centenas ouro ouro que-estava-sedento três-de ouro subia subira sobre o escudo a-uma e-lhes deu-os o-rei casa a floresta os montes');
INSERT INTO verses VALUES (9100, 11, 10, 18, 'E-fez o-rei trono- cavalo grande ouro ouro paz');
INSERT INTO verses VALUES (9101, 11, 10, 19, 'seis subidas para o trono e cabeça- circular para-a-capa de-tras-dele e-as-mãos mizze e-da-esse a lugar a-sabáte e-duas arayot em-pé ao-lado-de as-yadot');
INSERT INTO verses VALUES (9102, 11, 10, 20, 'e-duas dez arayim em-pé nome sobre seis as que subem deste e-dela não naasah assim para-todo mamlekhôt:');
INSERT INTO verses VALUES (9103, 11, 10, 21, 'e-tudo keli mashekhê o-rei שְׁלֹמֹה ouro e-tudo keli casa-de ya''ar ouro ouro puro não-há não não nakhshav beyimei Salomão lim''umah:');
INSERT INTO verses VALUES (9104, 11, 10, 22, 'que ''onî Tarshish para-o-rei no-yan povo Oni Chiram uma para três dois virá Oni Tarshish levante-se ouro ouro carruagens e cavalos e-vocareis');
INSERT INTO verses VALUES (9105, 11, 10, 23, 'ele-foi-crecido o-rei Shelomoh de-toda reis-de a-terra para-riches e-sabedoria');
INSERT INTO verses VALUES (9106, 11, 10, 24, 'e-todo a-terra mevaksheem a face-de Shelomoh para-ouvir a chokmatho que deu Elohim em-coração-seu');
INSERT INTO verses VALUES (9107, 11, 10, 25, 'e-eles [מְבִאִ֣ים] homem minhatto instrumentos-de prata e-utensílios ouro e-acordos [וְנֵ֣שֶׁק] e-com-perfumes cavaleiros e-divisões palavra-de ano em-anos');
INSERT INTO verses VALUES (9108, 11, 10, 26, 'e-reuniu Salomão carros e-cavaleiros e-foi para-ele mil e-quatro-de novecentos carros e-dois- dez mil פָּרַשִׂים [וְעִם־הַמֶּ֖לֶךְ] em-cidades-de o-carro e-com- o-rei em-Jerusalém');
INSERT INTO verses VALUES (9109, 11, 10, 27, 'E-colocou o-rei a o dinheiro birushalaim como-as-pedras e-a dar deu como-os-sicômoros que na-planície para-multidão');
INSERT INTO verses VALUES (9110, 11, 10, 28, 'e-saída-de os-cavalos que para-Salomão de-Egito [וּמִקְוֵ֕ה] comerciantes-de o-rei tomem [מִקְוֵ֖ה] por-preço');
INSERT INTO verses VALUES (9111, 11, 10, 29, 'וַֽ֠תַּעֲלֶה e saiu merkava de-Egito por-seis centenas-de prata e-cavalo por-cinquenta e-cem e-assim para-todo reis-de הַחִתִּ֛ים e reis Arã por-mão-deles saíram');
INSERT INTO chapters VALUES (302, 11, 11, 43);
INSERT INTO verses VALUES (9112, 11, 11, 1, 'e-o-rei Salomão amou mulheres nacriyot rabbot e-a filha-de Faraó moaviyot amaniyot adomiyot צדנות חיתות׃');
INSERT INTO verses VALUES (9113, 11, 11, 2, 'de [אֲשֶׁ֣ר] que palavras-de yhwh a filhos-de Israel não vai-vos [אָכֵן֙] [יַטּ֣וּ] não entrarão [אֱלֹהֵיהֶ֑ם] certamente unir-se a para-coracoes-vos atrás-de elohim-deles בָּהֶ֛ם Salomão');
INSERT INTO verses VALUES (9114, 11, 11, 3, 'e-foi a-ele נָשִׁ֗ים [שְׁבַ֣ע] sete centenas [שְׁלֹ֣שׁ] três centenas וַיַּטּ֥וּ suas mulheres: a coração-dele');
INSERT INTO verses VALUES (9115, 11, 11, 4, 'e-houve [לְעֵת֙] [זִקְנַ֣ת] Shelomoh suas mulheres levantai a coração-dele depois-de Elohim outros e-não foi seu-lábbo שָׁלוֹם com yhwh seu-pai Davi pai-seu');
INSERT INTO verses VALUES (9116, 11, 11, 5, 'E-andou Shelomoh depois-de אֵשֶׁת Elohim-de Tsídonim e-depois-de Milkom Shikkus Ammonim');
INSERT INTO verses VALUES (9117, 11, 11, 6, 'E-fez Salomão o-mal aos-olhos-de yhwh e-não enchei depois-de yhwh Cedavíd seu-pai');
INSERT INTO verses VALUES (9118, 11, 11, 7, 'então Yibnê שְׁלֹמֹה Bamá Likhmosh Shikkus Moabe Bahar que sobre face-de Jerusalém e-para-rei escárnio filhos-de Amon');
INSERT INTO verses VALUES (9119, 11, 11, 8, 'e-assim fez para-todo suas-mulheres as-negras caídas e-ofertoras a-suas-deusas');
INSERT INTO verses VALUES (9120, 11, 11, 9, 'e-ira-se yhwh em-solomão porque desviou no-seu-coração yhwh yhwh Elohim-de Israel a-ele a-ele duas-vezes');
INSERT INTO verses VALUES (9121, 11, 11, 10, 'e ordenou a-ele sobre a-coisa esta para não para-ir atrás-de Elohim outros e-não guardar yhwh que ordenou yhwh');
INSERT INTO verses VALUES (9122, 11, 11, 11, 'E-disse yhwh para-Salomão porque que seria guardada isto contigo e-não você guardou minha aliança e minhas leis que ordenei sobre-ti que rasguei rasgaria a הַמְּמֹלַךְ de ti e a lhe darei para te servir:');
INSERT INTO verses VALUES (9123, 11, 11, 12, 'somente não não farei: para-que Davi pai-teu de-mão-de filho-teu rasgarei:');
INSERT INTO verses VALUES (9124, 11, 11, 13, 'apenas: a não הַמְּמֹלַךְ não um bastão um darei para teu filho: a-fim-de Davi servo-meu e para: Jerusalém que eu escolhi:');
INSERT INTO verses VALUES (9125, 11, 11, 14, 'E-levantou yhwh שָׂטָן: para-Salomão a Hadade הָאֲדֹמִי: do sementes: o-rei ele בֶּאֱדֽוֹם׃');
INSERT INTO verses VALUES (9126, 11, 11, 15, 'e-houve [בִּֽהְי֤וֹת] Davi a Edom [יוֹאָב֙] Joabe comandante-de [לְקַבֵּ֖ר] [אֶת־הַחֲלָלִ֑ים] a [כָּל־זָכָ֖ר] e-feriu todo macho');
INSERT INTO verses VALUES (9127, 11, 11, 16, 'que [שֵׁ֧שֶׁת] חדשים [יָֽשַׁב־שָׁ֥ם] nome יוֹאָב e-todo Israel até todo macho');
INSERT INTO verses VALUES (9128, 11, 11, 17, 'e-saiu Adad ele e-homens edomitas de-servos-de seu-pai com-ele para-vir Egito e-Haddad jovem pequeno');
INSERT INTO verses VALUES (9129, 11, 11, 18, 'e-levantaram-se de-Midian e-vieram paraan e-levaram homens com-eles de-Aran e-entraram Mitzrayim a faráoh rei-de Egito e-ele-deu disse a-ele e-pão dar a-ele e-terra deu a-ele');
INSERT INTO verses VALUES (9130, 11, 11, 19, 'e-encontrou haddad grace em-olhos-de Pharaoh muito e-ele-deu para-ele mulher a achot- mulher-dele irmã Tecupnis a-mulher:');
INSERT INTO verses VALUES (9131, 11, 11, 20, 'e-deu-a a-ele achot- תחפנס a גנבה seu-filho e o criou תחפנס no-meio-de casa Faraó e-houve גנבאת casa Faraó no-meio-de filhos-de Faraó');
INSERT INTO verses VALUES (9132, 11, 11, 21, 'והaddonad ouviu במצרים porque שכב Davi com seus-pais e-que- E-disse יוֹאָב שר- o-exército E-disse addonad a Faraó שלחני ואlek a ארצי׃');
INSERT INTO verses VALUES (9133, 11, 11, 22, 'E-disse a-ele Faraó que o-quê tu [עִמִּ֔י] comigo ve-hincha que buscas para-andar E-disse a tua terra não que porque enviou');
INSERT INTO verses VALUES (9134, 11, 11, 23, 'E-levantou Elohim a-ele satan a [בֶּן־אֶלְיָדָ֑ע] filho-de Eliaua que [הֲדַדְעֶ֥זֶר] [מֶֽלֶךְ־צוֹבָ֖ה] Hadar-ezer rei-de אֲדֹנָֽיו׃');
INSERT INTO verses VALUES (9135, 11, 11, 24, 'e-queixou-se sobre-ele homens e-houve príncipe-de gud em-harog eles a-eles e-deram-se damaskos e-ele-estabeleceram-se nela e-reinaram-se em-damaskos:');
INSERT INTO verses VALUES (9136, 11, 11, 25, 'e-houve satã para-o-Israel todo dias-de Shelomoh e-a o-mal que Hadade e-acordou-se em-Israel e-reinou sobre aram');
INSERT INTO verses VALUES (9137, 11, 11, 26, '[וְיָרָבְעָם֩] filho-de [אֶפְרָתִ֜י] [מִן־הַצְּרֵדָ֗ה] de sua-mãe ve-shem sua-mãe [אַלְמָנָ֔ה] mulher [לִשְׁלֹמֹ֑ה] servo mão [בַּמֶּֽלֶךְ] mão');
INSERT INTO verses VALUES (9138, 11, 11, 27, '[וְזֶ֣ה] a-palavra que mão mão [שְׁלֹמֹה֙] edificar construiu-a fechar [אֶת־פֶּ֕רֶץ] [עִ֖יר] a seu-pai cidade Davi pai-seu');
INSERT INTO verses VALUES (9139, 11, 11, 28, 'e-o-homem Jeroboão homem força E-viu שְׁלֹמֹה a [כִּֽי־עֹשֵׂ֤ה] obra ele obra ele [לְכָל־סֵ֖בֶל] a-ele para-todo casa José');
INSERT INTO verses VALUES (9140, 11, 11, 29, 'e-houve em-o-tempo aquela [וְיָֽרָבְעָ֖ם] sair de-Jerusalém e-ele-encontrou ele [אֲחִיָּה֩] [הַשִּׁילֹנִ֨י] o-profeta no-caminho e-ele [מִתְכַּסֶּה֙] [בְּשַׂלְמָ֣ה] nova [וּשְׁנֵיהֶ֥ם] le-baddam no-campo');
INSERT INTO verses VALUES (9141, 11, 11, 30, '[וַיִּתְפֹּ֣שׂ] [אֲחִיָּ֔ה] [בַּשַּׂלְמָ֥ה] [הַחֲדָשָׁ֖ה] que sobre-ele [וַיִּ֨קְרָעֶ֔הָ] dois dez pedaços');
INSERT INTO verses VALUES (9142, 11, 11, 31, 'E-disse [לְיָֽרָבְעָ֔ם] toma a-ti asarah que porque disse yhwh yhwh Elohim-de Israel eis-me [אֶת־הַמַּמְלָכָה֙] a הַמֶּלֶךְ- de-mão-de a-ti e-darei para-ti a');
INSERT INTO verses VALUES (9143, 11, 11, 32, 've-a-shav-te o-primeiro ele-será- para-ele para-a-cau-sa-de servo-meu Davi e-para-a-cau-sa-de Jerusalém a-cidade que ba-khar-tti nela de-toda tribos-de Israel');
INSERT INTO verses VALUES (9144, 11, 11, 33, 'ya-ên que Deixem-me va-yi-sha-tcha-hu-ma le-ash-tho-reth Elohim-de tsi-don-im li-kmo-sho Elohim-de Moabe ve-li-mil-ko-m Elohim-de filhos-de Amom e-não caminharam nos-meus-caminhos para-fazer o-justo nos-meus-olhos e-meu-selos e-meus-decretos seu-pai seu-pai');
INSERT INTO verses VALUES (9145, 11, 11, 34, 'e-não tomarei a que o-reino do-seu-imediato que príncipe dias-de todo dias-de vidas-dele para-que Davi meu- servo ele eu-escolhi a-ele que שָׂמַר מִצְוֹתַ֥י וְחֻקּוֹתָֽי׃');
INSERT INTO verses VALUES (9146, 11, 11, 35, 'e-tomaria hammeluka da-mão-de filho-seu וּנְתַתְּ֣יהָ לָךָ֔ a dez הַשֹּׁבְטִים׃');
INSERT INTO verses VALUES (9147, 11, 11, 36, 'וְלִבְנֹ darei bastão-de- um para-que ser- נִ֣יר לְדַוִֽד־ עַ֠בְדִּי todo os dias diante-de-mim em-Jerusalém a-cidade que eu escolhi a-mim para nome-meu nome');
INSERT INTO verses VALUES (9148, 11, 11, 37, 'e ti eu tomarei e-tu-reinarás em-todo que ela-deseja alma-tua e-você-seja rei sobre Israel');
INSERT INTO verses VALUES (9149, 11, 11, 38, 'e-foi se tu ouvirás a todo que e caminharias em minhas sendas ve-asita o reto nos meus olhos para guardar חֻקּוֹתַי֙ e-os-comandos-meus como-que fez Davi עַבְדִּ֑י וְהָיִ֣יתִי a-ti וּבָנִ֨יתִי para-ti casa-de נֶאֱמָן֙ como-que a-ti para-David e-darei a-ti a Israel');
INSERT INTO verses VALUES (9150, 11, 11, 39, '[וַֽאעַנֶּ֛ה] a semente Davi esta esta não não todo os dias');
INSERT INTO verses VALUES (9151, 11, 11, 40, 've-yevakesh Salomão para-matar a Járobaom E-levantou [וַיִּבְרַ֤ח] [מִצְרַ֙יִם֙] Mitzrayim a e-houve rei-de Egito E-foi em-o-Egito até morrer שְׁלֹמֹה');
INSERT INTO verses VALUES (9152, 11, 11, 41, 'e-resto-de dibre Salomão e-todo que fez ve-chokmato não eles k''tuvim sobre a-ele palavras-de שְׁלֹמֹה');
INSERT INTO verses VALUES (9153, 11, 11, 42, 'e-os-dias que rei שְׁלֹמֹה b''yerushalayim sobre todo Israel quarenta anos');
INSERT INTO verses VALUES (9154, 11, 11, 43, 'e-deitou-se שְׁלֹמֹה com seus-pais [בְּעִ֖יר] בעיר seu-pai pai-seu e-reinou Rechav''am filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (303, 11, 12, 33);
INSERT INTO verses VALUES (9155, 11, 12, 1, 'E-andou Rechav''am שַׂכְמֵ֑ן que Shekem veio todo Israel ele a-ele');
INSERT INTO verses VALUES (9156, 11, 12, 2, 'e-houve quando-ouvir Jeroboão filho-de nebat e-ele ainda-ele בְמִצְרַ֔יִם que barach de-diante-de o-rei Shelomoh e-habitou Jeroboão em-Egito');
INSERT INTO verses VALUES (9157, 11, 12, 3, 'e-enviaram e-ele-chamou- a-ele Jeroboão e-todo assembleia Israel va''yedaberu a dizendo para-dizer');
INSERT INTO verses VALUES (9158, 11, 12, 4, 'Avicha hiqsha a [וְאַתָּ֡ה] e-tu agora leva-o de-a-trabalho teu-pai a-dura e-de-a-carga o-pesado que deu sobre nós e-adoraremos-te');
INSERT INTO verses VALUES (9159, 11, 12, 5, 'E-disse a-eles para-voces-andem até três dias e-voltai a-mim e-foram o-povo');
INSERT INTO verses VALUES (9160, 11, 12, 6, 'e-ele-conselhou-se o-rei Raquebãm a os-velhos que eram estando-de-pé seu-pai face-de vida dizendo [אֵ֚יךְ] viveu dizendo como vós seja-conselheiros para-responder a o-povo- este palavra');
INSERT INTO verses VALUES (9161, 11, 12, 7, 'a-ele dizendo a-ele dizendo será- servo ao-povo este [וַֽעֲבַדְתָּ֔ם] [וַעֲנִיתָ֕ם] e-falares a-eles דְּבָרִ֣ים [טוֹבִ֑ים] e-sejam a-ti servos todo os dias');
INSERT INTO verses VALUES (9162, 11, 12, 8, 'e-olvidou a עֲצַ֥ת os velhos que conselheiros-os e ele conselhou-se a os-meninos que cresceram com-ele que os-que-estavam-de-pé diante-de-ele');
INSERT INTO verses VALUES (9163, 11, 12, 9, 'E-disse a-eles quanto vós seja-conselheiros ve-ná-shív palavra a o-povo este que dibb-rú dizendo dizendo ha-qel de ha-ol que deu Avicha sobre-nós');
INSERT INTO verses VALUES (9164, 11, 12, 10, 'e-falaram a-ele os-meninos que cresceram it-to dizendo assim dirás ao-povo הַזֶּ֡ה que [אֵלֶ֜יךָ] dizendo dizendo teu-pai pesou-duramente a nosso-grave-fardo e-tu leva-leve de-nos assim falarias a-eles pequeno-eu pesado-fui de-cintura pai-meu');
INSERT INTO verses VALUES (9165, 11, 12, 11, 'e-agora pai-meu fez-pesado sobre-vós sobre pesado e-eu [אוֹסִ֣יף] sobre o-vosso-peso pai-meu i-sar vos b-a-s-hotim e-eu [אֶתְכֶ֖ם] vos');
INSERT INTO verses VALUES (9166, 11, 12, 12, 'Jeroboão e-todo o-povo a Rechav''am no-dia o terceiro como-que palavra o rei dizendo retornem para-mim no-dia o-terceiro');
INSERT INTO verses VALUES (9167, 11, 12, 13, 'e-respondeu o-rei a o-povo dura e-olvidou a עֲצַ֥ת os velhos que');
INSERT INTO verses VALUES (9168, 11, 12, 14, 'e-falou a-eles conforme-a-conselho os-meninos dizendo pai-meu pesou-duramente a vossa-carga e-eu a-sufir sobre o-vosso-peso pai-meu i-sar vos b-a-s-hotim e-eu [בָּעַקְרַבִּֽים] vós');
INSERT INTO verses VALUES (9169, 11, 12, 15, 'e-não ouviu o-rei a o-povo porque yhwh [לְמַ֜עַן] de-com yhwh para levantar-á yhwh palavra-sua que palavra yhwh em-mão-de a Yarav''am filho-de נְבוֹט׃');
INSERT INTO verses VALUES (9170, 11, 12, 16, 'E-viu todo que porque não ouviu o rei a-eles וַיָּשׁ֣בוּ o-povo a dizendo דָּבָ֣ר ׀ Dize que nós parte בְּדָוִ֜ד e-não herança no filho de Isai para as tuas tendas Israel agora viu na tua casa Davi E-andou Israel para as suas tendas:');
INSERT INTO verses VALUES (9171, 11, 12, 17, 'e-filhos-de Israel os-habitantes em-cidades-de Judá e-reinou sobre-eles Rachabãm');
INSERT INTO verses VALUES (9172, 11, 12, 18, 'e-enviou o-rei Raquebãm a [אֲשֶׁ֣ר] que sobre do-tributo e-os-lançou-pedras pedra Israel nele eben E-morreu e-o-rei Raquebãm fortaleceu-se para-subir na-carroça para-nascer Jerusalém');
INSERT INTO verses VALUES (9173, 11, 12, 19, 'e-ele-se-apaixonou Israel na-casa-de Davi até o-dia a-esta');
INSERT INTO verses VALUES (9174, 11, 12, 20, 'e-houve ainda que ouvi todo Israel porque retornou Jeroboao ele e-eles-chamaram ele ele a-congregação não ser sobre todo Israel não sozinho depois-de casa-de Davi exceto-eu bastão-de- יְהוּדָה sozinho');
INSERT INTO verses VALUES (9175, 11, 12, 21, 'Rachabam Jerusalém e-ele-reuniu a todo casa Judá e-a tribo-de Benjamim cem e-oitenta mil בָּחוּר fez guerra para-lutar com casa Israel para-retornar a o-reino filho-de שְׁלֹמֹה');
INSERT INTO verses VALUES (9176, 11, 12, 22, 'e-houve palavra o elohim a [אִישׁ־הָאֱלֹהִ֖ים] dizendo Elohim para-dizer');
INSERT INTO verses VALUES (9177, 11, 12, 23, 'disse a [בֶּן־שְׁלֹמֹה֙] filho-de שְׁלֹמֹה rei Judá e-a todo casa dizendo o-povo para-dizer');
INSERT INTO verses VALUES (9178, 11, 12, 24, 'assim disse yhwh não subi-e e-não [בְּנֵֽי־יִשְׂרָאֵ֗ל] com irmãos-vossos filhos-de que Shuvu@ homem para-a-sua-casa porque [וַיִּשְׁמְעוּ֙] aconteceu yhwh este [לָלֶ֖כֶת] a yhwh yhwh para-andar conforme-palavra-de yhwh');
INSERT INTO verses VALUES (9179, 11, 12, 25, 'E-edificou Jeroboão a Shekem em-monte-de e-sentou nela e-saiu de-lá E-edificou a');
INSERT INTO verses VALUES (9180, 11, 12, 26, 'E-disse Jeroboão בַּלִּבּוֹ עַתָּ֛ה retornarás o-reino segundo-casa-de Davi');
INSERT INTO verses VALUES (9181, 11, 12, 27, 'se [׀] o-povo o-este לַעֲשׂ֨וֹת [זְבָחִ֤ים] na-casa-de yhwh em-Jerusalém [לֵ֣ב] coração o-povo o-este a adonai-deles a Rechav''am rei Judá [מֶֽלֶךְ־יְהוּדָֽה] e-eles-voltarão a Rechav''am rei-de Judá');
INSERT INTO verses VALUES (9182, 11, 12, 28, '[וַיִּוָּעַ֣ץ] o-rei E-fez segundo ovelhas-de ouro E-disse a-eles chefe-de para-vocês [יְרוּשָׁלִַ֔ם] eis eis Elohim-teu Israel que elevaram-vos de-terra-de Egito');
INSERT INTO verses VALUES (9183, 11, 12, 29, 'e-colocou a o-único em-Betel dar e-a o-único deu em-Bdán');
INSERT INTO verses VALUES (9184, 11, 12, 30, 'e-houve a-palavra este para-oferta-de-pecado e-caminharam o-povo diante-de o-primeiro até dan');
INSERT INTO verses VALUES (9185, 11, 12, 31, 'E-fez a casa [וַיַּ֤עַשׂ] E-fez sacerdotes [הָעָ֔ם] o-povo que não foram de-filhos-de Levi');
INSERT INTO verses VALUES (9186, 11, 12, 32, 'E-fez [יָרָבְעָ֣ם] [׀] no-mês הַשְּׁמִינִ֣י [הַשְּׁמִינִ֣י] dez dia [׀] [לַחֹ֜דֶשׁ] que em-Juda e-subiu sobre o altar assim fez em-Betel El [לְזַבֵּ֖חַ] [לָעֲגָלִ֣ים] que fez e-estabelecerá em-casa-de El a כֹּהֲנֵ֥י as baamas que fez');
INSERT INTO verses VALUES (9187, 11, 12, 33, 'e-ele-subiu sobre [׀] que fez em-Betel El dia dez dia no-mês o-oitavo no-mês que [וַיַּ֤עַשׂ] E-fez [לִבְנֵ֣י] aos-filhos-de Israel e-ofereceu sobre o-altar');
INSERT INTO chapters VALUES (304, 11, 13, 34);
INSERT INTO verses VALUES (9188, 11, 13, 1, 'והנה homem Elohim veio [בָּ֧א] pela-palavra-de yhwh yhwh casa-de El [עֹמֵ֥ד] ficou-em-pé sobre o-altar');
INSERT INTO verses VALUES (9189, 11, 13, 2, 'E-chamou sobre o-altar yhwh E-disse E-disse מזבחMZbech altar disse yhwh yhwh eis-a filho נולדNolad para-casa-de Davi יוashiyahuYoshiyahu seu-nome e sacrificou sobre-ti a os sacerdotes homem aqueles que regam sobre-ti e ossos homem queimarão sobre-te');
INSERT INTO verses VALUES (9190, 11, 13, 3, 'e-ele-dará no-dia o-aquele milagre dizendo este o milagre que palavra yhwh eis o-altar foi rasgado e derramado o fumo que sobre-ele');
INSERT INTO verses VALUES (9191, 11, 13, 4, 'e-houve quando-ouviram o-rei a palavra homem-de chamou que chamou sobre o-altar em-Betel de-cima-de e-enviou dizendo a sua mão de-sobre sua-mão Dize explica-o e se despedaçou mão-dele que enviou a-ele e-não יכל para devolvê-la a-ele');
INSERT INTO verses VALUES (9192, 11, 13, 5, 'e o altar foi rasgado e derramou-o a-cinza de o-altar como um espetáculo dar deu homem o-Elohim yhwh yhwh');
INSERT INTO verses VALUES (9193, 11, 13, 6, 'e-ele-respondeu o-rei E-disse a homem o-Elohim Cala-se por-favor yhwh face-de yhwh teu-Elohim e orou para mim e voltarás minha-mão a-mim ele começou a yhwh הָֽאֱלֹהִים a a-ele yhwh e-retornou mão-de o-rei para-ele e-foi já em primeiro');
INSERT INTO verses VALUES (9194, 11, 13, 7, 'e-falou o-rei a homem o-Elohim venha comigo a casa a-ti e-eu-darei a-ti de dádiva');
INSERT INTO verses VALUES (9195, 11, 13, 8, 'E-disse homem-de הָֽאֱלֹהִים a o-rei se não para-mim a metade pão não eu entrarei contigo e-não comerei pão e-não Eu beberei- águas no-lugar- a-esta');
INSERT INTO verses VALUES (9196, 11, 13, 9, 'porque assim ordenou a-mim -no discurso yhwh dizendo não pão pão e-não você beberei- águas e-não volverás- no-caminho que -você andaste');
INSERT INTO verses VALUES (9197, 11, 13, 10, 'E-andou no-caminho outro e-não retornou em-a-caminho que veio nela a casa-de El');
INSERT INTO verses VALUES (9198, 11, 13, 11, '-e profeta um velho habitou em-Betel El e veio- -seu filho e contou- a-ele a todo o-dia que fez homem-de -Elohim o-hoje em-Betel El a as palavras que palavra a o-rei e lhes narraram a seus pais:');
INSERT INTO verses VALUES (9199, 11, 13, 12, 'e-falou para-eles pai-deles ei- este o-caminho andou vayire''u seus filhos a andar que andou homem os-Elohim que veio de Judá:');
INSERT INTO verses VALUES (9200, 11, 13, 13, 'E-disse a filhos-dele e armaram-se a-mim o-jumento e armaram-se a-ele o-jumento e montaram sobre-ele');
INSERT INTO verses VALUES (9201, 11, 13, 14, 'E-andou atrás-de homem os-Elohim e encontraram-no habitou debaixo aquele E-disse a-ele o at thee homem-de o-Elohim que E-disse de juhuda E-disse eu');
INSERT INTO verses VALUES (9202, 11, 13, 15, 'E-disse a-ele vai com eu a-casa e comer pão');
INSERT INTO verses VALUES (9203, 11, 13, 16, 'E-disse não eu comer para voltar com ti e vir contigo e-não pão pão e-não águas contigo águas no-lugar- a-esta');
INSERT INTO verses VALUES (9204, 11, 13, 17, 'porque palavra a-mim yhwh yhwh pão comerás Belém e-não terás beber nome águas não volverás para andar no-caminho que andaste nela');
INSERT INTO verses VALUES (9205, 11, 13, 18, 'E-disse a-ele também eu profeta como tu e anjo palavra אלאי֩ yhwh dizendo dizendo restitúe-o contigo a pão e-ele-comerá pão e terás comido a-ele como se escondeu a-ele');
INSERT INTO verses VALUES (9206, 11, 13, 19, 'e-estabeleceu-se com-ele e-comeu pão em-casa-dele e-bebeu águas');
INSERT INTO verses VALUES (9207, 11, 13, 20, 'e-houve eles habitavam a [פ] e-houve palavra-de yhwh a o-profeta que');
INSERT INTO verses VALUES (9208, 11, 13, 21, 'E-chamou a homem os-Elohim que dizendo [כֹּ֖ה] disse yhwh disse que porque porque yhwh boca-de yhwh e-não [אֲשֶׁ֥ר] a yhwh que yhwh');
INSERT INTO verses VALUES (9209, 11, 13, 22, '[וַתָּ֗שָׁב] e-comeste pão [וַתֵּ֣שְׁתְּ] águas [בַּמָּקוֹם֙] que palavra para-ti a pão pão e-a [לֹֽא־תָב֥וֹא] águas não [אֲבֹתֶֽיךָ] a');
INSERT INTO verses VALUES (9210, 11, 13, 23, 'e-houve depois-de [אָכְל֥וֹ] pão e-depois-de [שְׁתוֹת֑וֹ] [וַיַּחֲבָשׁ־ל֣וֹ] a-ele [לַנָּבִ֖יא] [אֲשֶׁ֥ר] que');
INSERT INTO verses VALUES (9211, 11, 13, 24, 'E-andou וַיִּמְצָאֵ֧הוּ אַרְיֵ֛ה no-caminho e-matou-o e-foi נִבְלָתוֹ֙ מֻשְׁלֶ֣כֶת em-a-caminho וְהַחֲמוֹר֙ ficou-em-pé אֶצְלָ֔הּ e a arreia ficou-em-pé ao-lado-de a velha:');
INSERT INTO verses VALUES (9212, 11, 13, 25, 'e-eis homens passam e-viram a a velha destruída em-a-caminho e-a a arreia ficou-em-pé junto-a a velha e-vieram e-falaram na cidade que o profeta o velho habitou nela');
INSERT INTO verses VALUES (9213, 11, 13, 26, 'E-ouviu o נָבִיא que הֶשְׁבִּיו de E-disse E-disse homem ele ele que מַרָה yhwh boca-de yhwh וַיִתְןֶהוּ yhwh לָאַרְיֵה וַיִשְׁבַּרֵהוּ yhwh conforme-palavra-de yhwh que falou a-ele');
INSERT INTO verses VALUES (9214, 11, 13, 27, '[וַיְדַבֵּ֤ר] a dizendo dizendo [אֶֽת־הַחֲמ֑וֹר] a-mim a');
INSERT INTO verses VALUES (9215, 11, 13, 28, 'E-andou e-encontrou a נִבְלָתֹו מֻשְׁלֶכֶת em-a-caminho o chamor e a aryeh em-pé junto-a a nabelah não comeu a aryeh a a nabelah e-não quebrou a o chamor');
INSERT INTO verses VALUES (9216, 11, 13, 29, 'e-ele-leva o-profeta a nabelath e-o-colocou o-Elohim e o deixou a o burro e o deixou E-veio a cidade הַנָּבִ֣יא o velho para lamentos e para sepultá-lo');
INSERT INTO verses VALUES (9217, 11, 13, 30, 'e pôs a seu cadáver em sua sepultura e lamentos sobre-ele ai meu-irmão');
INSERT INTO verses VALUES (9218, 11, 13, 31, 'e-houve depois-de sepultá-lo ele E-disse a dizendo dizendo בְּמוֹתִי֙ וּקְבַרְתֶּ֣ם a-mim בַּקֶּ֕בֶר que homem Elohim קָב֣וּר nele אֵ֚צֶל עַצְמֹתָ֔יו הַנִּ֖יחוּ a עַצְמֹתָֽי׃');
INSERT INTO verses VALUES (9219, 11, 13, 32, 'que foi será a-palavra que chamou em-palavra-de yhwh sobre o-altar que em-Betel El e-sobre todo [בְּעָרֵ֥י] [שֹׁמְרֽוֹן׃] que');
INSERT INTO verses VALUES (9220, 11, 13, 33, 'outro a-coisa esta não retornou Jeroboão de-seu-caminho a-maldade e-estabeleceu-se E-fez de-suas-extremidades o-povo sacerdotes em-ervas o-que-gostou preencheria e-seja mão-de-ele E-foi sacerdotes em-ervas:');
INSERT INTO verses VALUES (9221, 11, 13, 34, 'e-houve בַּדָּבָ֣ר esta por transgressão casa ירבעם וּלְהַכְחִיד֙ וּלְהַשְׁמִ֔יד de-cima-de face-de a-terra');
INSERT INTO chapters VALUES (305, 11, 14, 31);
INSERT INTO verses VALUES (9222, 11, 14, 1, 'em-o-tempo aquela [חָלָ֖ה] Abias filho-de');
INSERT INTO verses VALUES (9223, 11, 14, 2, 'E-disse יָרָבְעָ֜ם לְאִשְׁתּ֗וֹ levanta-te por-favor וְהִשְׁתַּנּ֔ית e-não יֵֽדְע֔וּ porque mulher-de ירבעם וְהָלַ֣כְתְּ שִׁלֹ֗ה eis-que- nome אֲחִיָּה o-profeta ele palavra sobre-mim para-rei sobre o-povo a-esta');
INSERT INTO verses VALUES (9224, 11, 14, 3, 'e tomará em tua mão dez pão e pontos e na caixa דְּבַשׁ e entrará a-ele ele dirá para-ti que será para-o-jovem');
INSERT INTO verses VALUES (9225, 11, 14, 4, 'e-fez-se assim mulher-de Jeroboao e-ele-se-levantou e-ela-partiu-se Siló e veio casa Achia e Achiahu não para-ver que porque levantaram-se seus-olhos de-sibô:');
INSERT INTO verses VALUES (9226, 11, 14, 5, 'e-יהוה disse a eis eis mulher-de Já-ravâm בָּאָ֗ה para-dorash palavra de-ímêkha a ele porque chôle ele kazô e-seja falarias para-ela E-foi kevô''âh e-ela mitnakrâ:');
INSERT INTO verses VALUES (9227, 11, 14, 6, 'e-houve quando-ouviram Áchiyahu a voz ragle-ha בָּאָ֗ה E-disse E-disse bô''î mulher-de ירבעם por-que זֹה אַתָּ מִתְנַכֶּרָה וְאָנֹכִי שָׁלוּחַ para-ti dura-:');
INSERT INTO verses VALUES (9228, 11, 14, 7, 'vai imri לְיָרָבְעָם assim yhwh yhwh Elohim-de Israel porque que הַרִּמֹּתִיךָ do-meio-de o-povo וָאֵתֶןְךָ sobre sobre povo-meu Israel');
INSERT INTO verses VALUES (9229, 11, 14, 8, 'וָאֶקְרַע a הַמֹּמְלָכָה de-casa-de Davi para-ti a-ti e-não havíta ka''ávadi Davi que shámár mițwótay va''asher- andou אַחֲרַי֙ em-todo coração-dele la''ásot somente hayyáshar be''eynay׃');
INSERT INTO verses VALUES (9230, 11, 14, 9, 'vátara para-fazer de-toda que foram diante-de-ti vátelek e fez-te- para ti- Elohim outros- e coberturas- para me irritar- e comigo- lançaste-me- atrás-de teu-:');
INSERT INTO verses VALUES (9231, 11, 14, 10, 'portanto eis-me מֵבִ֤יא mal a casa Jeroboao e cortarei- para Yarobão- מַשַּׂית בְּקִיר עָצֹר וְעָזֹב em-Israel וּבִעַרְתִּי depois-de casa-de Jeroboao como יְבַעֵר הַגָּלָל até תּוֹמָא׃');
INSERT INTO verses VALUES (9232, 11, 14, 11, 'הַמֵּת לְיָרָבְעָם na-cidade comerão os cães e o morto no-campo eles-comerão ave os-céus que yhwh palavra');
INSERT INTO verses VALUES (9233, 11, 14, 12, 'e tu ar Levanta-te vai para a tua casa em vindo as tuas pernas a cidade e-ele-morreu o-menino');
INSERT INTO verses VALUES (9234, 11, 14, 13, 'e lamentem-se para-ele todo ele e sepultem-no sozinho porque este para-somente-dele virá לְיָרָבְעָם a bom porque נִמְצָא־ ב֞וֹ palavra bom a yhwh Elohim-de Israel em-casa-de Já-boém;');
INSERT INTO verses VALUES (9235, 11, 14, 14, '[וְהֵקִים֩] yhwh a-ele rei sobre Israel que [אֶת־בֵּ֥ית] a casa o-dia este o-dia também');
INSERT INTO verses VALUES (9236, 11, 14, 15, 'e-ele-golpeou yhwh a Israel como-que יָנ֣וּד הַקָּנֶה֮ בַּמַּיִם֒ וְנָתַ֣שׁ de-cima-de a-terra de-cima a-terra a-bons-a dar que deu aos-pai-s e-seus-ramos מֵעֵ֣בֶר ao-río porque que fizeram a que-lhes irritam a yhwh');
INSERT INTO verses VALUES (9237, 11, 14, 16, 'E-deu a Israel por-causa-de pecados yarav''am que erro e-que fez-pecar a Israel');
INSERT INTO verses VALUES (9238, 11, 14, 17, 'e-ele-se-levantou mulher-de Jeroboao e saiu e-veio sua vontade ela veio por a-casa e o rapaz morreu');
INSERT INTO verses VALUES (9239, 11, 14, 18, 'e-eles-sepultaram ele e conversaram a-ele todo yhwh segundo a palavra yhwh que palavra pela-mão-de servo-dele seu irmão o profeta:');
INSERT INTO verses VALUES (9240, 11, 14, 19, 'וְיֶ֙תֶר֙ palavras-de יָֽרָבְעָ֔ם que נִלְחַ֖ם e-que rei eis-os escritos sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9241, 11, 14, 20, 'וְהַיָּמִים֙ que rei Jeroboao vinte וּשְׁתַּ֖יִם ano וַיִּשְׁכַּב֙ com seus-pais e-reinou נָדָ֥ב filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9242, 11, 14, 21, 'וּרְחַבְעָם֙ filho-de Shelomoh rei בִּֽיהוּדָ֑ה filho-de quarenta e-uma ano Rechabeom em seu reinado e sete doze ano rei בִּירוּשָׁלִַ֗ם a cidade yhwh בָּחַ֨ר yhwh para ser chamada de-toda shemo nome de-todo sua-mãe Israel e-nome-de sua-mãe נַעֲמָ֖ה הָעַמֹּנִֽית׃');
INSERT INTO verses VALUES (9243, 11, 14, 22, 'E-fez Judá o-mal aos-olhos-de yhwh וַיְקַנְא֣וּ ele de-toda que fizeram pais-deles בְּחַטֹּאתָ֖ם que חָטָֽאוּ׃');
INSERT INTO verses VALUES (9244, 11, 14, 23, 'וַיִּבְנ֨וּ também a-eles a-eles בָּמ֥וֹת וּמַצֵּב֖וֹת sobre sobre todo גִּבְעָ֣ה alta e-debaixo-de todo árvore רַעֲנָֽן׃');
INSERT INTO verses VALUES (9245, 11, 14, 24, 'e-também ser na-terra na terra fizeram como-tudo as abominações as-nações que yhwh de-diante-de de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (9246, 11, 14, 25, 'e-houve em ano a quinta para-o-rei Roboão subir rei-de Egito sobre Jerusalém');
INSERT INTO verses VALUES (9247, 11, 14, 26, 'E-tomou a אֹצְר֣וֹת casa-de yhwh e-a os seus tesouros casa E-tomou e-a o-ouro tomou E-tomou a todo guardiões o-ouro que fez שְׁלֹמֹה');
INSERT INTO verses VALUES (9248, 11, 14, 27, 'E-fez o-rei רְחַבְעָם֙ debajo deles guardiões bronze e governou sobre mão príncipes-de os corredores os-guardas entrada casa o rei');
INSERT INTO verses VALUES (9249, 11, 14, 28, 'e-houve de veio o-rei yhwh yhwh serão esvaziados os que correm e os retornarão a a os corredores:');
INSERT INTO verses VALUES (9250, 11, 14, 29, 'e-resto-de palavras-de Roboao e-todo que fez não-é eles escritos sobre livro palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9251, 11, 14, 30, 'e guerra era entre- e-entre e-entre Jeroboão todo os dias');
INSERT INTO verses VALUES (9252, 11, 14, 31, 'e sepeliu רחבעם com seus-pais e enterrou com אֲבֹתָיו֙ na-cidade sua-mãe e-nome-de sua-mãe נַעֲמָ֖ה a amonita e-reinou avimeleque filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (306, 11, 15, 34);
INSERT INTO verses VALUES (9253, 11, 15, 1, 'e no ano de oito dezoito ao-rei Jeroboão filho-de nebat rei avimeleque sobre Judá');
INSERT INTO verses VALUES (9254, 11, 15, 2, 'três dois rei em-Jerusalém e-nome-de sua-mãe מַעֲכָ֖ה filha-de avissolom:');
INSERT INTO verses VALUES (9255, 11, 15, 3, 'E-andou em-todo seu-pai seu-pai que fez diante-dele e-não foi seu coração shalem com seu-pai de-diante-de כּלֵּב Davi seu-pai');
INSERT INTO verses VALUES (9256, 11, 15, 4, 'que para-que Davi dar yhwh Elohim a-ele נִיר em-Jerusalém para-levantar a filho-o apos-ele וּלְהַעֲמִ֖יד a Jerusalém');
INSERT INTO verses VALUES (9257, 11, 15, 5, 'que fez Davi a o-reto yhwh yhwh de-toda סָר de-todo dias-de צִוָּ֗הוּ todo dias-de vidas-dele somente בִּדְבַ֖ר Uriah o-heteu');
INSERT INTO verses VALUES (9258, 11, 15, 6, 'וּמִלְחָמָ֨ה era בֵין־ e-entre e-entre Jeroboão todo dias-de vida-dele');
INSERT INTO verses VALUES (9259, 11, 15, 7, 'e-resto-de palavras de אֲבִיָּם֙ e-todo que fez acaso-nao eles escritos sobre livro palavras-de os-dias era entre e guerra e-entre entre abiam e-entre Já-boém;');
INSERT INTO verses VALUES (9260, 11, 15, 8, 'e-deitou-se abiam com seus-pais ele ele na-cidade Davi e-reinou Asa seu-filho em-lugar-dele');
INSERT INTO verses VALUES (9261, 11, 15, 9, 'e-em-ano-de vinte para jerebaum rei Israel rei Asa rei Judá');
INSERT INTO verses VALUES (9262, 11, 15, 10, 'e quarenta e uma ano rei em-Jerusalém e-nome-de sua-mãe מַעֲכָ֖ה filha-de abissalom:');
INSERT INTO verses VALUES (9263, 11, 15, 11, 'E-fez asa o-reto aos-olhos-de yhwh como david seu-pai');
INSERT INTO verses VALUES (9264, 11, 15, 12, 'e passou os santificados de a-terra e-removeu a todo as esferas que fizeram pais-dele');
INSERT INTO verses VALUES (9265, 11, 15, 13, 'e-tambem a מעכה sua-mãe e tirou-a do véu que fez da plêce para aseráh e cortou אָסָא a da plêce e queimou בְּנַ֥חַל קִדְרֽוֹן׃');
INSERT INTO verses VALUES (9266, 11, 15, 14, 'e as baamas não סָ֑רוּ somente ser Asa foi inteiro com yhwh todo יامיו׃');
INSERT INTO verses VALUES (9267, 11, 15, 15, 'e-trouxe a seu-pai pai-dele casa yhwh yhwh וְזָהָ֖ב וְכֵלִֽים׃');
INSERT INTO verses VALUES (9268, 11, 15, 16, '[וּמִלְחָמָ֨ה] era entre [אָסָ֗א] e-entre [בַּעְשָׁ֥א] rei-de Israel todo');
INSERT INTO verses VALUES (9269, 11, 15, 17, 'e-subiu בַּעְשָׁ֤א rei-de Israel E-edificou Judá para-não a sai לְבִלְתִּ֗י põe saindo e veio para Assa rei Judá');
INSERT INTO verses VALUES (9270, 11, 15, 18, 'E-tomou Assa a todo o prata e o ouro os restantes em suas arca(s) casa-de yhwh e-a arca(s) casa e-colocou-os pela-mão-de servos-dele e os enviou o-rei Asa a filho-de הֲדַד filho-de טַבְרִימֹ֤ן dizendo חֶזְיוֹן rei Arã הַיּוֹשֵׁב בְּדַמּוֹסֶק para-dizer');
INSERT INTO verses VALUES (9271, 11, 15, 19, 'בְּרִית entre-mim וּבֵינֶךָ entre meu-pai e-entre teu-pai eis שָׁלַחְתּי a-ti שֹׁחַד prata e-ouro vai הָפֵרָה a בריתך a בעשה rei-de Israel ויעלה מעלי');
INSERT INTO verses VALUES (9272, 11, 15, 20, 'E-ouviu filho-de [אֶל־הַמֶּ֣לֶךְ] a o-rei [אֶת־שָׂרֵ֨י] [הַחֲיָלִ֤ים] a [עַל־עָרֵ֣י] [יִשְׂרָאֵ֔ל] que a-ele sobre e-[OBJ] Israel [בֵּֽית־מַעֲכָ֑ה] e-[OBJ] [כָּל־כִּנְר֔וֹת] sobre [כָּל־אֶ֥רֶץ] e-[OBJ] casa-de e-[OBJ] todo sobre todo terra');
INSERT INTO verses VALUES (9273, 11, 15, 21, 'e-houve [כִּשְׁמֹ֣עַ] [בַּעְשָׁ֔א] [וַיֶּחְדַּ֕ל] [מִבְּנ֖וֹת] a [וַיֵּ֖שֶׁב] e-habitou');
INSERT INTO verses VALUES (9274, 11, 15, 22, 'e-orei-melech Asa הִשְׁמִ֤יעַ a todo Judá não-há נָקִ֔י e-ele-sustiveram-no a אַבְנֵ֤י edificar e-a E-edificou que בנה בעשה va-yiben bam- o-rei de-diante-de a גביע Benjamim e-a hamatzpah');
INSERT INTO verses VALUES (9275, 11, 15, 23, 'וְיֶ֣תֶר todo דברי- אסא e-todo גבורה-ו e-todo edificar fez והערים- que בנה acaso-nao eles escritos sobre livro palavras-de os-dias למלכי Judá somente ao-tempo-de זקנים-ו chalah a de-seus-pés');
INSERT INTO verses VALUES (9276, 11, 15, 24, 'e-deitou-se אָסָא com seus-pais e foi sepultado com seus-pais seu-pai Davi seu-pai e-reinou Jeosafá filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9277, 11, 15, 25, 'e Nadav filho-de Jároabeom rei sobre Israel no-ano-de dois para Assa rei Judá e-reinou sobre Israel dois anos:');
INSERT INTO verses VALUES (9278, 11, 15, 26, 'E-fez o-mal aos-olhos-de yhwh E-andou no-caminho seu-pai e em sua oferta de arrependimento que fez-pecar a Israel');
INSERT INTO verses VALUES (9279, 11, 15, 27, 'e amarrou sobre-ele em uma madeira filho-de Achiya para-casa-de Issacar e-feriu-o בַעְשָׁ֔א בְּגִבְּת֖וֹן que לַפְּלִשְׁתִּ֑ים וְנָדָב֙ e-todo Israel צָרִ֖ים sobre בְּגִבְּת֖וֹן');
INSERT INTO verses VALUES (9280, 11, 15, 28, 'וַיְּמִתֵ֣הוּ בַעְשָׁ֔א no-ano-de três לְאָסָ֖א rei Judá e-reinou em-lugar-dele');
INSERT INTO verses VALUES (9281, 11, 15, 29, 'e-houve כְמָלְכ֗וֹ hika a todo casa Jeroboao não ele-deixou todo yhwh le-yarav''am até his''mido conforme-a-palavra-de yhwh que palavra por-mão-de servo-dele a''chiya ha-shiloni');
INSERT INTO verses VALUES (9282, 11, 15, 30, 'sobre chatot yarav''am que chata e-que fez-pecar a Israel be-kacso que hikacis a yhwh Elohim-de Israel');
INSERT INTO verses VALUES (9283, 11, 15, 31, 'e-resto-de palavras-de Nadabe e-todo que fez não-é eles escritos sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9284, 11, 15, 32, 'e-milhama era entre Asa e-entre ba''asua rei-de Israel todo yemehem');
INSERT INTO verses VALUES (9285, 11, 15, 33, 'no-ano-de três le''asa rei Judá rei ba''asua filho-de achiyya sobre todo Israel bitirzah vinte ve''arba'' anos');
INSERT INTO verses VALUES (9286, 11, 15, 34, 'E-fez o-mal aos-olhos-de yhwh E-andou no-caminho Jeroboao v''chattato que fez-pecar a Israel');
INSERT INTO chapters VALUES (307, 11, 16, 34);
INSERT INTO verses VALUES (9287, 11, 16, 1, 'e-houve palavra-de yhwh a [עַל־בַּעְשָׁ֖א] dizendo sobre');
INSERT INTO verses VALUES (9288, 11, 16, 2, 'porque que [הֲרִימֹתִ֙יךָ֙] de [וָאֶתֶּנְךָ֣] [נָגִ֔יד] sobre sobre meu-povo Israel [׀] no-caminho [יָרָבְעָ֗ם] [וַֽתַּחֲטִא֙] a meu-povo Israel [בְּחַטֹּאתָֽם]');
INSERT INTO verses VALUES (9289, 11, 16, 3, 'eis-me מַבְעִ֛יר depois-de בַּעֲשָׁא e-depois-de בֵּיתוֹ e-n-d-e-rei a בַּיְתְךָ֔ כְּבֵית يروبعام filho-de נְבוֹט׃');
INSERT INTO verses VALUES (9290, 11, 16, 4, 'הַמֵּת לִבַּעֲשָׁא֙ na-cidade יֹאכֵלוּ os cães e o morto a-ele no-campo eles-comerão ave os-céus');
INSERT INTO verses VALUES (9291, 11, 16, 5, 'e-resto-de palavras-de -em Baasha- e-que fez e sua força não-é eles escritos sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9292, 11, 16, 6, 'e-deitou-se -em Baasha- com seus-pais e-ele-foi-sepultado -em Tirza- e-reinou estas seu-filho em-lugar-dele');
INSERT INTO verses VALUES (9293, 11, 16, 7, 'e também pela-mão-de Ele filho-de Hanani ser palavra-de yhwh foi a -em Baasha- e-a seu lar e-sobre yhwh a má que fez aos-olhos-de yhwh para irritá-lo por meio de suas mãos ele como-casa-de Járobaom e-sobre que atingiu ele');
INSERT INTO verses VALUES (9294, 11, 16, 8, 'em-ano-de vinte e seis ano para Asa rei Judá rei אלה filho-de בעשא sobre Israel בתירצה שנתים׃');
INSERT INTO verses VALUES (9295, 11, 16, 9, 'ויקשור sobre-ele עבדו זמרי príncipe מחצית הרכב e-ele בתירצה שֹׁתֶה שִׁכּ֔וֹר casa אַרְצָ֔א que sobre a-casa בְּתִרְצָֽה׃');
INSERT INTO verses VALUES (9296, 11, 16, 10, 'E-veio זִמְרִי֙ e-feriu-o וַיְמִיתֵ֔הוּ no-ano-de vinte וָשֶׁ֔בַע לְאָסָ֖א rei Judá e-reinou em-lugar-dele');
INSERT INTO verses VALUES (9297, 11, 16, 11, 'e-houve בְמָלְכ֜וֹ quando-sentou-se sobre seu-trono bateu a todo a-ele em-nome não deixou a-ele cavas na-parede e-seus-redentores e-seus-amigos');
INSERT INTO verses VALUES (9298, 11, 16, 12, '[וַיַּשְׁמֵ֣ד] [זִמְרִ֔י] a todo casa [כִּדְבַ֤ר] yhwh yhwh que palavra a [יֵה֥וּא] na-mão-de');
INSERT INTO verses VALUES (9299, 11, 16, 13, 'a todo [בַּעְשָׁ֔א] [וְחַטֹּ֖אות] [אֵלָ֣ה] [בְנ֑וֹ] [אֲשֶׁ֣ר] que [וַאֲשֶׁ֤ר] e-que [אֶת־יִשְׂרָאֵ֔ל] a Israel [Elohim] a yhwh Israel');
INSERT INTO verses VALUES (9300, 11, 16, 14, 'e-resto-de palavras-de Elá e-todo que fez acaso-nao eles escritos sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9301, 11, 16, 15, 'בִּשְׁנַת֩ vinte וָשֶׁ֜בַע ano לְאָסָא֙ rei Judá rei זִמְרִ֛י sete dias בְּתִרְצָ֑ה וְהָעָ֣ם חֹנִ֔ים sobre Gbthon que para os Pletsim:');
INSERT INTO verses VALUES (9302, 11, 16, 16, 'E-ouviu o-povo os acampados dizendo conectou Zimri e-também bateu a o-rei e reinaram todo Israel a no-dia príncipe-de exército sobre Israel no-dia o-aquele no-lager');
INSERT INTO verses VALUES (9303, 11, 16, 17, 'e-elevou-וַיַּעֲלֶ֥ה Amri e-todo Israel com-ele de Gbthon e-eles-construíram sobre Tirza:');
INSERT INTO verses VALUES (9304, 11, 16, 18, 'e-houve כּ-רֵא-וֹת זִ-מְרִי porque נִ-לְכַּדָּה a-cidade E-veio a אַ-רְמֹן casa-de o-rei וַיִ-שָׂרַף sobre-ele a casa-de rei com-fogo E-morreu');
INSERT INTO verses VALUES (9305, 11, 16, 19, 'sobre que חָ-טָא para-fazer o-mal aos-olhos-de yhwh yhwh no-caminho Jeroboao וּבְחַ-תָּאוֹ que fez לְהַ-חֲטִיא a Israel');
INSERT INTO verses VALUES (9306, 11, 16, 20, 'וְיֶ֙תֶר֙ palavras-de זִ-מְרִי וְקִ-שׁוֹר que קָשׁוֹר acaso-nao eles escritos sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9307, 11, 16, 21, 'אָז יֵחָלֵק o-povo Israel לַחֵצִי חֲצִי o-povo ser apos תִבְنִי filho-de גִּינַת לְהַמְלִיכוֹ וְהַחֲצִי depois-de עָמְרִֽי׃');
INSERT INTO verses VALUES (9308, 11, 16, 22, 'e-ele-firmou o-povo que depois-de עָמְרִי a o-povo que depois-de תִּבְנִ֣י filho-de גִּינַ֑ת E-morreu תִּבְנִ֔י e-reinou עָמְרִֽי׃');
INSERT INTO verses VALUES (9309, 11, 16, 23, 'בִּשְׁנַת֩ trinta וְאַחַ֜ת ano לְאָסָא֙ rei Judá rei עָמְרִי֙ sobre Israel dois dez ano בְּתִרְצָ֖ה rei seis-de dois');
INSERT INTO verses VALUES (9310, 11, 16, 24, 'וַיִּקְנֶ֣ה a a-montanha שֹׁמְר֛וֹן מֵ֥אֶת שָׁמֵר בְּכִכּוֹרַיִם E-edificou e-construiu E-chamou o-monte E-chamou a edificar sobre que בָּנָה sobre nome- שָׁמֵר Adonai a-montanha Samaria');
INSERT INTO verses VALUES (9311, 11, 16, 25, 'וַיַּעֲשֶׂה עָמְרִי o-mal aos-olhos-de yhwh וַיָּרָע de-toda que diante-de-ele');
INSERT INTO verses VALUES (9312, 11, 16, 26, 'E-andou em-todo caminho Jeroboão filho-de [**וּבְחַטָּאת֔וֹ] que [הֶחֱטִ֖יא] a Israel [אֶת־יְהוָ֛ה] a yhwh Elohim-de Israel');
INSERT INTO verses VALUES (9313, 11, 16, 27, 'e-resto-de דְּבָרַי עָמְרִי que fez וּגְבוּרַתוֹ que fez acaso-nao eles escritos sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9314, 11, 16, 28, 'e-deitou-se עָמְרִי com seus-pais e-ele-foi-sepultado בְּשֹׁמְרֹנָה e-reinou אַחְאָב filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9315, 11, 16, 29, 'וְאַחְאָב filho-de עָמְרִי rei sobre Israel em-ano-de trinta וּשְׁמֹנֶה ano לְאָסַא rei Judá e reinou Acaías filho-de Amari sobre Israel em-Samaria vinte e Sítim anos');
INSERT INTO verses VALUES (9316, 11, 16, 30, 'E-fez Acaías filho-de Amari o-mal yhwh de-toda de-todo que diante-de-ele');
INSERT INTO verses VALUES (9317, 11, 16, 31, 'e-houve será levado em sua viagem por cordeados Jeroboão filho-de E-tomou E-tomou mulher a Izabel filha-de אֶת-בַּעַל rei צִידֹנִים E-andou a-ele a o-Baal e-prostrou-se a-ele');
INSERT INTO verses VALUES (9318, 11, 16, 32, 'E-levantou altar לַבָּ֑עַל casa o-Baal que edificar בְּשֹׁמְרֽוֹן׃');
INSERT INTO verses VALUES (9319, 11, 16, 33, 'E-fez Acabe a הָאֲשֵׁרָ֑ה וַיּ֨וֹסֶף Acabe לַעֲשׂ֗וֹת לְהַכְעִיס֙ a yhwh Israel reis-de Israel que foram diante-de-ele');
INSERT INTO verses VALUES (9320, 11, 16, 34, 'בְּיָמָ֞יו edificar חִיאֵ֛ל casa הָאֱלִ֖י a Jericó no Abira seu primogênito ele a fortificou e seu jovem estabeleceu suas portas conforme-a-palavra-de yhwh yhwh palavra na-mão-de יְהוֹשֻׁ֥עַ filho-de Nun:');
INSERT INTO chapters VALUES (308, 11, 17, 24);
INSERT INTO verses VALUES (9321, 11, 17, 1, 'E-disse Elias da Tisbe de habitantes de Giláad a Achav vive yhwh Elohim-de Israel que estou-em-pé diante-dele se será os anos que chuva e neve porque se por minha palavra');
INSERT INTO verses VALUES (9322, 11, 17, 2, 'e-houve palavra-de a-ele dizendo');
INSERT INTO verses VALUES (9323, 11, 17, 3, 'vai deste-lado e voltarás para ti קדמה וְנִסְתַּרְתָּ בְּנַחַל כְּרִית que sobre face-de o-Jordão');
INSERT INTO verses VALUES (9324, 11, 17, 4, 'e-foi מֵהַנַּחַל תִּשָּׁתֶה e-a הָעֹרְבִים eu ordenei לְכַלְכֵּלְךָ nome');
INSERT INTO verses VALUES (9325, 11, 17, 5, 'E-andou E-fez conforme-a-palavra-de yhwh E-andou e-habitou בְּנַחַל כְּרִית que sobre face-de o-Jordão');
INSERT INTO verses VALUES (9326, 11, 17, 6, 'e os águias trazendo a-ele pão e carne de-manhã e-pão e-carne no entardecer e-de o-nachal יִשְׁתֶּֽה׃');
INSERT INTO verses VALUES (9327, 11, 17, 7, 'e-houve depois que dias e secou o rio que não foi a chuva na-terra');
INSERT INTO verses VALUES (9328, 11, 17, 8, 'e-houve palavra-de a-ele dizendo');
INSERT INTO verses VALUES (9329, 11, 17, 9, 'levantou vai Cafarata que para Zidon e-habitarás nome eis mandei-eu nome mulher viúva para te refrescar');
INSERT INTO verses VALUES (9330, 11, 17, 10, 'e-elevantou-se- E-andou forjada E-veio a entrada-de a-cidade e eis que nome mulher viúva quebrada E-chamou E-chamou para-ela E-disse leva-me por-favor para mim pouco- águas no vaso e eu beberei');
INSERT INTO verses VALUES (9331, 11, 17, 11, 'ela foi לָקַ֑חַת E-chamou para-ela E-disse לִֽקְחִי־ por-favor a-mim pedaço-de pão בְּיָדֵֽךְ׃');
INSERT INTO verses VALUES (9332, 11, 17, 12, 'E-disse vive yhwh teu-Elohim se que para-mim מָע֔וֹג porque se enchei כַף־ farinha בַּכּ֣ד וּמְעַט־ שֶׁ֖מֶן בַּצַּפָּ֑חַת וְהִנְנִ֨י מְקֹשֶׁ֜שֶׁת dois árvores e-vim e-fez-o a-mim e-para-meu-filho e-comemos-o e-mossemortos');
INSERT INTO verses VALUES (9333, 11, 17, 13, 'E-disse a-ela אֵלִיָּ֙הוּ֙ a temas quando-vim עֲשׂוּ segundo-teu-palavra somente faze- מִ֠שָּׁם massa pequena בָּרִאשׁוֹנָה וְהוֹצֵאתְ a-mim וְלָךְ וְלִבְנֵךְ ta-as-i בָּאַחֲרֹנָה׃');
INSERT INTO verses VALUES (9334, 11, 17, 14, 'que כֹּה disse yhwh Elohim-de Israel כַּ הַקֶּמַח não תִּכְלָה וְצַפַּחַת o-a-sínden não teksar até dia yhwh gešem sobre a-terra a-terra');
INSERT INTO verses VALUES (9335, 11, 17, 15, 'e-foi vata''asáh conforme-a-palavra-de אֵלִיָּ֑הוּ e-comeste u-vetáh dias');
INSERT INTO verses VALUES (9336, 11, 17, 16, 'kad ha-qemákh não kaláta ve-tsapháhat o-a-sínden não חָסֵר כִּדְבַ֤ר yhwh que palavra na-mão-de Elias');
INSERT INTO verses VALUES (9337, 11, 17, 17, 'e-houve [אַחַר֙] as-palavras estes [חָלָ֕ה] filho-de [בַּעֲלַ֣ת] [הַבָּ֑יִת] e-houve E-foi [חָזָ֣ק] muito até até que não');
INSERT INTO verses VALUES (9338, 11, 17, 18, 'E-disse a Elias que para-mim וָלָ֖ךְ homem o-Elohim בָּ֧אתָ a-mim לְהַזְכִּ֥יר a iniquidade-minha וּלְהָמִ֥ית a filhos-de');
INSERT INTO verses VALUES (9339, 11, 17, 19, 'E-disse para-ela Dizei- para-mim a filho-vos- e-o-levou- da-cadeia- e-o-elevou- a a-elevação- que ele habitou nome e-o-deitou- sobre em-a-sua-cama');
INSERT INTO verses VALUES (9340, 11, 17, 20, 'E-chamou a yhwh yhwh yhwh meu-Elohim Será-que sobre a-viúva- com-ela eu de-murmuração- com-ela haréuota lehamit a o-filho-seu.');
INSERT INTO verses VALUES (9341, 11, 17, 21, 'vayitmoded sobre a-criança três E-chamou E-chamou a yhwh E-disse yhwh meu-Elohim tashav por-favor alma-de o-menino este sobre kirbo');
INSERT INTO verses VALUES (9342, 11, 17, 22, 'E-ouviu yhwh com-voz אֵלִיָּ֑הוּ vatashab alma-de hayeled sobre kirbo e-viveu-verso-final');
INSERT INTO verses VALUES (9343, 11, 17, 23, 'E-tomou Elias a o-menino vayoredahu de a subida a-casa E-disse para a mãe E-disse vida viveu seu filho:');
INSERT INTO verses VALUES (9344, 11, 17, 24, 'E-disse a-mulher a Elias agora este que porque homem Elohim tu e-palavra-de yhwh por tua boca verdade');
INSERT INTO chapters VALUES (309, 11, 18, 46);
INSERT INTO verses VALUES (9345, 11, 18, 1, 'e-houve dias muitos e-palavra-de ser foi a Elias dizendo a terceira dizendo vai veja a Acabe a-terra que sobre face-de a-terra');
INSERT INTO verses VALUES (9346, 11, 18, 2, 'E-andou Elias para mostrar a Acabe e a fome força בְּשֹׁמְרֽוֹן׃');
INSERT INTO verses VALUES (9347, 11, 18, 3, 'E-chamou Acabe a [אֲשֶׁ֣ר] que sobre ser temer foi muito a yhwh');
INSERT INTO verses VALUES (9348, 11, 18, 4, 'e-houve בְּהַכְרִ֣ית אִיזֶ֔בֶל a profetas-de yhwh E-tomou עֹבַדְיָ֜הוּ cem נְבִאִ֗ים וַֽיַּחְבִּיאֵ֞ם cinquenta homem na-caverna וְכִלְכְּלָ֖ם pão וָמָֽיִם׃');
INSERT INTO verses VALUES (9349, 11, 18, 5, 'E-disse Acabe a עֹבַדְיָ֔הוּ vai na-terra a e-para ma''yanê as-águas e-a todo ha-nachalim u''li foi-achado chatsir unehayyêh sus vafered e não nachrit me-habbehamah');
INSERT INTO verses VALUES (9350, 11, 18, 6, '[וַֽיְחַלְּק֥וּ] a-eles a a-terra [אַחְאָ֞ב] andar [בְּדֶ֤רֶךְ] um sozinho um andar [בְּדֶרֶךְ־אֶחָ֖ד] sozinho um');
INSERT INTO verses VALUES (9351, 11, 18, 7, 'e-houve עֹבַדְיָ֙הוּ֙ em-a-caminho e-eis אֵלִיָּ֖הוּ ao-encontro-dele וַיַּכִּרֵ֙הוּ֙ e-caiu sobre E-disse E-disse és-tu este Adonai Elias');
INSERT INTO verses VALUES (9352, 11, 18, 8, 'E-disse a-ele eu vai disse לַאדֹנֶ֖יךָ eis Elias');
INSERT INTO verses VALUES (9353, 11, 18, 9, 'E-disse que חָטָ֑אתִי porque você deu a עַבְדְּךָ֛ por-mão-de Acabe לַהֲמִיתֵֽנִי׃');
INSERT INTO verses VALUES (9354, 11, 18, 10, 'vida yhwh yhwh se há nação e-mamlekháh que não enviou Adonai nome labbekqesh-ka'' e-direão a''ayin ve-hishbí''a que não e-a a-nação porque não yimtsá''ekh:');
INSERT INTO verses VALUES (9355, 11, 18, 11, 'e-agora tu disse vai disse lá-adonéka eis Elias');
INSERT INTO verses VALUES (9356, 11, 18, 12, 'e-será ani'' irei me''et-ka'' ve-rúacha e-Espírito-de yhwh sobre que sobre edá'' e eu entrarei para dizer a Achabe e-não que encontre-te e me matará e o teu servo tem medo temer yhwh dos meus jovens');
INSERT INTO verses VALUES (9357, 11, 18, 13, 'acaso-nao foi dito ao meu senhor a que fiz בהרג איסבל yhwh profetas-de yhwh yhwh מנביאים yhwh cem homem cinquenta cinquenta homem pão ואכלclsם pão-de ומים׃');
INSERT INTO verses VALUES (9358, 11, 18, 14, 'e-agora tu disse vai disse לאדונךא eis אֵלִיָּ֑הוּ והרגני׃');
INSERT INTO verses VALUES (9359, 11, 18, 15, 'E-disse אליהו vida yhwh exércitos que עמדתי diante-dele que o-dia אראה a-ele');
INSERT INTO verses VALUES (9360, 11, 18, 16, 'E-andou עֹבַדְיָ֛הוּ para-encontro-de Acabe e-contou a-ele E-andou Acabe para-encontro-de Elias');
INSERT INTO verses VALUES (9361, 11, 18, 17, 'e-houve כִּרְא֥וֹת Acabe a E-disse E-disse a-ele a-ele és-tu este עֹכֵ֥ר Israel');
INSERT INTO verses VALUES (9362, 11, 18, 18, 'E-disse não עָכַ֙רְתִּי֙ a que porque se tu e-Beit teu-pai yhwh a mandamentos-de yhwh וַתֵּ֖לֶךְ atrás-de os-בַעַל');
INSERT INTO verses VALUES (9363, 11, 18, 19, 'e-agora enviou קְבֹ֥ץ a-mim a todo Israel a monte-de o-Carmelo e-a נְבִיאֵ֨י הַבַּ֜עַל quatro centenas-de וַחֲמִשִּׁ֗ים וּנְבִיאֵ֤י הָאֲשֵׁרָה֙ quatro centenas אֹכְלֵ֖י shulchan אִיזָֽבֶל׃');
INSERT INTO verses VALUES (9364, 11, 18, 20, 'e-enviou Acabe em-todo filhos-de Israel וַיִּקְבֹּ֥ץ a os-profetas a monte-de הַכַּרְמֶֽל׃');
INSERT INTO verses VALUES (9365, 11, 18, 21, 'e-ele-aproximou-se Elias a E-disse o-povo E-disse até מָתַ֞י vós פֹּסְחִים֮ sobre duas הַסְּעִפִּים֒ se yhwh הָֽאֱלֹהִים ide apos-ele ele הַבַּ֖עַל ide atrás-dele e-não ele o-povo a-ele palavra');
INSERT INTO verses VALUES (9366, 11, 18, 22, 'E-disse אֵלִיָּ֙הוּ֙ a o-povo eu נָתַרְתִּי profeta a-yhwh sozinho וּנְבִיאֵי o-Baal אַרְבַּע־ centenas ouro homem');
INSERT INTO verses VALUES (9367, 11, 18, 23, 'וְיִתְּנוּ־ לָ֜נוּ dois פָּרִ֗ים a-eles a-elas o-primeiro הָאֶחָ֜ד וִֽינַתְּחֻ֗הוּ וְיָשִׂ֙ימוּ֙ sobre não וְאֵ֖שׁ não ישׂוּ e-eu Eu farei o-primeiro o-touro o único e-n-d-e-rei não as árvores e fogo não eu colocarei');
INSERT INTO verses VALUES (9368, 11, 18, 24, 'e chamareis no-nome-de vosso-Elohim e eu sou e-que-ra em nome de yhwh ve-hâyâ: o-Elohim que ele em-chamas ele o-Elohim e-respondeu bom o-povo e-disseram bom a-palavra');
INSERT INTO verses VALUES (9369, 11, 18, 25, 'E-disse Elias לנביאים o-Baal chamai a-vós o-bezerro o-primeiro e-façam רִאשׁוֹנָה que vós הָרַבִּים וְקִרְאוּ no-nome-de vosso-Elohim וְאֵשׁ não תָּשִׂימוּ׃');
INSERT INTO verses VALUES (9370, 11, 18, 26, 've-yikchu a הַפָּ֫ר a-eles deu לָהֶם֮ וַיַּעֲשׂוּ֒ e-chamaram בְּשֵׁם־ dizendo מֵהַבָּקֶר e-até as-cinzas voz o-dono ouça-nos e-não-há voz e-não-há que-escute e-passaram-se sobre ele que fez');
INSERT INTO verses VALUES (9371, 11, 18, 27, 'e-houve nas-cinzas e-estenderam-se neles Elias E-disse Chamem em-voz- grande ele que ele porque a-ele e-quando a-ele a-ele e-quando ele a-ele talvez velho ele e-acordará:');
INSERT INTO verses VALUES (9372, 11, 18, 28, 'e-criaram com-voz grande e-tornaram-se como-julgamento em-deserto e-em-ramas até derramou-se sangue sobre-eles');
INSERT INTO verses VALUES (9373, 11, 18, 29, 'e-houve como-passageio as-meridians e-proferiram até para-subir a-oferenda e-nao-ha voz e-não-há tristeza e-não-há קָֽשֶׁב׃');
INSERT INTO verses VALUES (9374, 11, 18, 30, 'E-disse [אֵלִיָּ֤הוּ] para-todo o-povo [אֵלַ֔י] a-mim [כָל־הָעָ֖ם] a-ele o-povo [אֶת־מִזְבַּ֥ח] yhwh a yhwh');
INSERT INTO verses VALUES (9375, 11, 18, 31, 'E-tomou Elias dois dez pedras כְּמִסְפַּ֖ר tribos-de filhos-de Jacó ser foi a-ele dizendo a-ele será Israel será שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (9376, 11, 18, 32, 'וַיִּבְנֶ֧ה a as-pedras altar yhwh yhwh E-fez תְּעָלָ֗ה כְּבֵית֙ semente זרע ao-redor para o altar:');
INSERT INTO verses VALUES (9377, 11, 18, 33, '[וַֽיַּעֲרֹ֖ךְ] a [וַיְנַתַּח֙] [אֶת־הַפָּ֔ר] a [עַל־הָעֵצִֽים] sobre');
INSERT INTO verses VALUES (9378, 11, 18, 34, 'E-disse מלאו quatro כדים águas ויתקו sobre a-holocausto E-disse os-madeiras E-disse E-disse VASHNU E-disse שלשו VASHALLSHU׃');
INSERT INTO verses VALUES (9379, 11, 18, 35, 'e-andaram as-águas ao-redor para-o-altar e-também a a oferenda cheio de águas');
INSERT INTO verses VALUES (9380, 11, 18, 36, 'e-houve em subida a-oferenda [הַמִּנְחָ֗ה] Eliseu o profeta E-disse yhwh yhwh Abraão Isaque e Israel o-dia o-dia porque você Elohim em-Israel e-eu servo-teu fiz a todo as-palavras as estas');
INSERT INTO verses VALUES (9381, 11, 18, 37, 'escute-me yhwh escute-me e saibam o-povo este porque yhwh yhwh o-Elohim e-tu você fará voltar a seus corações atrás');
INSERT INTO verses VALUES (9382, 11, 18, 38, 'e-caiu fogo- e-comeste e-ko-lal a ha-olah e-a as madeiras e-a as pedras e-a a poeira e-a as-águas que em fúria para se deleitar');
INSERT INTO verses VALUES (9383, 11, 18, 39, 'E-viu todo o-povo [עַל־פְּנֵיהֶ֑ם] sobre yhwh ele yhwh yhwh ele yhwh');
INSERT INTO verses VALUES (9384, 11, 18, 40, 'E-disse Elias a-eles tipshu a profetas-de habba''al homem a yimmalet deles vayitpshuwm vayoredhem elijjahu a vale-de kisohon vayishchatem nome');
INSERT INTO verses VALUES (9385, 11, 18, 41, 'E-disse elijjahu le''achav folhas-de אכל וסתה porque voz multidao הַגָּֽשֶׁם׃');
INSERT INTO verses VALUES (9386, 11, 18, 42, 'e-elevou-וַיַּעֲלֶ֥ה Acabe para-comer ואשתות e-אֵלִיָּהוּ subir a cabeça הַכַּרְמֶל֙ e-ele-teve-frio terra-para e-colocou entre entre');
INSERT INTO verses VALUES (9387, 11, 18, 43, 'E-disse a נערו עליה־ por-favor הבט דרך־ E-disse e-subiu וַיַּבֵּ֔ט E-disse não-há coisa-alguma E-disse retornou sete vezes');
INSERT INTO verses VALUES (9388, 11, 18, 44, 'e-aconteceu no-sétimo E-disse eis á-vel pequena como-palma- homem E-disse folhas-de E-disse sobre-a disse a Acabe encadeada e-vermelha e-não será-impedida-a a-chuva:');
INSERT INTO verses VALUES (9389, 11, 18, 45, 'e-houve até assim e-até assim e os céus se encolham e-Espírito-de e-houve E-foi גשם grande e se agitaram Acabe E-andou Jezabel:');
INSERT INTO verses VALUES (9390, 11, 18, 46, 'e a mão- era foi a Elias e levantou seus joelhos e-o correu diante-de Acabe até em-sua-comer Jezabel:');
INSERT INTO chapters VALUES (310, 11, 19, 21);
INSERT INTO verses VALUES (9391, 11, 19, 1, 'e-contou Acabe para Izabel a todo que fez אֵלִיָּ֑הוּ e-a todo que matou a todo os-profetas pela-espada');
INSERT INTO verses VALUES (9392, 11, 19, 2, 'e ela enviou A Isabel an anjo a dizendo dizendo assim fazem Elohim e-assim José porque naquele tempo amanhã enganos a a sua alma como alma um de-eles');
INSERT INTO verses VALUES (9393, 11, 19, 3, 'E-viu E-levantou E-andou a naphshô E-veio em-Beer sete que para-יְהוּדָה וישן a seu jovem nome');
INSERT INTO verses VALUES (9394, 11, 19, 4, 'e-ele andou o-caminho-de dia dia E-veio debaixo sob eles se encolheram e-ele-perguntou a נפשוֹ para-morrer E-disse muito עַתָּה yhwh yhwh nafshi porque não eu eu me''abotay');
INSERT INTO verses VALUES (9395, 11, 19, 5, 'vayishkav vayishan debaixo rotem um vehinneh- este מַלְאָךְ nog''ah E-disse a-ele a-ele levantou e''chol');
INSERT INTO verses VALUES (9396, 11, 19, 6, 'vayavbet e-eis mera''ashotay עֻגַ֥ת רְצָפִ֖ים וְצַפַּ֣חַת águas e-comeu וַיֵּ֔שְׁתְּ וַיָּ֖שָׁב e-deitou-se');
INSERT INTO verses VALUES (9397, 11, 19, 7, 'va-yashav anjo-de yhwh שֵׁנִית֙ וַיִּגַּע־ nele E-disse levantou אֱכֹ֑ל que muito de-vós הַדָּֽרֶךְ׃');
INSERT INTO verses VALUES (9398, 11, 19, 8, 'E-levantou e-comeu וַיִּשְׁתֶּ֑ה E-andou בְּכֹ֣חַ הָאֲכִילָ֣ה a aquela quarenta dia dia noite até até o-Elohim חֹרֵֽב׃');
INSERT INTO verses VALUES (9399, 11, 19, 9, 'וַיָּבֹא־ nome a הַמְּעָרָ֖ה וַיָּ֣לֶן nome a-ele E-disse a-ele a-ele E-disse a-ele que- a-você e-agora Elias');
INSERT INTO verses VALUES (9400, 11, 19, 10, 'E-disse קַנֹּ֨א קִנֵּ֜אתִי לַיהוָ֣ה ׀ Elohim-de exércitos porque עָזְב֤וּ aliança-de-ti filhos-de Israel a mizbóchoteikha harasú e-a nebiéikhá hargu becháreb vaiuté eu lebadí e-buscaram a alma-minha lekachta');
INSERT INTO verses VALUES (9401, 11, 19, 11, 'E-disse çeá véamadta בָהָר֮ diante-de yhwh e-eis yhwh עֹבֵ֗ר e-Espírito-de גְּדוֹלָ֡ה וְחָזָ֞ק מְפָרֵק֩ הָרִ֨ים וּמְשַׁבֵּ֤ר סְלָעִים֙ diante-de yhwh não בָר֖וּחַ yhwh וְאַחַ֤ר הרוח רעש não ברעש yhwh');
INSERT INTO verses VALUES (9402, 11, 19, 12, 'ואחר הרעש fogo não em-chamas yhwh e-apos o-fogo voz דממה דקה׃');
INSERT INTO verses VALUES (9403, 11, 19, 13, 'e-houve כשמע Elias WAYYALET פניו בְּאַדַּרְתּ֔וֹ e-ele-saiu e-se-posicionou entrada-de הַמְּעָרָ֑ה e-eis a-ele a-ele voz E-disse a-você פֹ֖ה Elias');
INSERT INTO verses VALUES (9404, 11, 19, 14, 'E-disse קַנֹּ֨א קִנֵ֜אתִי לַיהוָ֣ה Elohim-de exércitos porque עָזְב֤וּ aliança-de-ti filhos-de Israel a מִזְבְּחֹתֶ֣יךָ הָרָ֔סוּ e-a נְבִיאֶ֖יךָ הרגו בחָרב ואיטרה eu לבדי e-buscaram a alma-minha לקחתה׃');
INSERT INTO verses VALUES (9405, 11, 19, 15, 'E-disse yhwh a-ele vai volta לדרכךָ מדברָה דמשק ובאתה ומשחתה֧ a חזהאל para-rei sobre aram');
INSERT INTO verses VALUES (9406, 11, 19, 16, 'e-[OBJ] [יֵה֣וּא] filho-de [תִּמְשַׁ֥ח] [לְמֶ֖לֶךְ] [עַל־יִשְׂרָאֵ֑ל] sobre Israel e-[OBJ] [מְחוֹלָ֔ה] filho-de [לְנָבִ֖יא] [תַּחְתֶּֽיךָ]');
INSERT INTO verses VALUES (9407, 11, 19, 17, 'e-foi הנמלט מ חרב חזהאל ימית יהוה וְהַנִּמְלָ֛ט מֵחֶ֥רֶב יֵה֖וּא matará אֱלִישָֽׁע');
INSERT INTO verses VALUES (9408, 11, 19, 18, '[וְהִשְׁאַרְתִּ֥י] [בְיִשְׂרָאֵ֖ל] sete [אֲלָפִ֑ים] todo [אֲשֶׁ֤ר] que não [וְכָ֨ל־הַפֶּ֔ה] [אֲשֶׁ֥ר] e-todo a-ele que não');
INSERT INTO verses VALUES (9409, 11, 19, 19, 'E-andou מִ֠שָּׁם e achou a e-l-i-sh-a filho-de julgador e-ele serrante doze dez par de ferramentas diante-dele e-ele em dois a-ele e-ele-passou Eliahu a-ele e lançou sua adarga a-ele');
INSERT INTO verses VALUES (9410, 11, 19, 20, 'e abandonou a o gado e-o correu depois-de E-disse E-disse eu beberei agora para meu pai e para minha mãe E-disse a-ele E-disse a-ele que volta para-ti a-ele fiz para-ti');
INSERT INTO verses VALUES (9411, 11, 19, 21, 'e voltou de trás dele E-tomou a arado o boi e o sacrificou e no utensílio o-bovino בִּשְּׁלָ֣ם E-colocou E-deu ao-povo וַיֹּאכֵ֑לוּ E-levantou E-andou depois-de אֵלִיָּ֖הוּ וַיְשָׁרְתֵֽהוּ׃');
INSERT INTO chapters VALUES (311, 11, 20, 43);
INSERT INTO verses VALUES (9412, 11, 20, 1, 'e-filho-de Hadade rei-de אֲרָ֗ם קָבַץ֙ a todo חֵיל֔וֹ וּשְׁלֹשִׁ֨ים u-shnayim rei com-ele וְס֣וּס וָרָכֶב e-subiu וַיָּ֙צַר֙ sobre שֹׁ֣מְר֔וֹן וַיִלָּ֖חֶם nela');
INSERT INTO verses VALUES (9413, 11, 20, 2, '[וַיִּשְׁלַ֧ח] [מַלְאָכִ֛ים] a [מֶֽלֶךְ־יִשְׂרָאֵ֖ל] rei-de Israel');
INSERT INTO verses VALUES (9414, 11, 20, 3, 'E-disse a-ele assim disse filho-de Hadade ככספך׃ וזהבך׃ לי— ele ונשים׃ e-filhos-teus הטובים para-mim- eles');
INSERT INTO verses VALUES (9415, 11, 20, 4, 'e-respondeu rei-de E-disse E-disse כדברך׃ Adonai a-ti para-ti eu e-todo que a-mim');
INSERT INTO verses VALUES (9416, 11, 20, 5, 'e-voltaram-se os-anjos e-disseram assim disse dizendo חัดד dizendo dizendo shalachti a-ti dizendo o teu dinheiro e o teu ouro e as tuas mulheres também para-mim darás;');
INSERT INTO verses VALUES (9417, 11, 20, 6, 'que se como tempo-de amanhã eu lançarei a minha serva a-ti e procurarão a em tua casa e-a nas tuas servos-teus e-foi todo dignidades os olhos serão puestos em suas mãos e tomarão');
INSERT INTO verses VALUES (9418, 11, 20, 7, 'E-chamou rei-de Israel a-terra E-disse a-terra E-disse que por-favor e-vede porque maldade este pedindo porque enviou a-mim para minhas filhas e para meus filhos nós e para meu ouro e-não eu retenho de-nós');
INSERT INTO verses VALUES (9419, 11, 20, 8, 'e-disseram a-ele todo os velhos e-todo o-povo a vós ouvi e não desejo');
INSERT INTO verses VALUES (9420, 11, 20, 9, 'E-disse para-angels filho-de Hadad dizeis ao-senhhor o-rei todo que enviaste a servo-teu no-primeiro não e-a-mensagem este não posso laasot e-andaram os-anjos e-resspondeu-lhe palavra');
INSERT INTO verses VALUES (9421, 11, 20, 10, 'e-estendeu a-ele filho-de E-disse E-disse assim farão a-mim Elohim e-assim acrescentaram se יִשְׂפֹּק֙ o-pó שֹׁמְר֔וֹן לִשְׁעָלִ֕ים para-todo o-povo que בְּרַגְלָֽי׃');
INSERT INTO verses VALUES (9422, 11, 20, 11, '[וַיַּ֤עַן] rei-de E-disse E-disse [אַל־יִתְהַלֵּ֥ל] a [כִּמְפַתֵּֽחַ]');
INSERT INTO verses VALUES (9423, 11, 20, 12, 'e-houve כִּשְׁמֹ֙עַ֙ a a-palavra este e-ele ele ele וְהַמְּלָכִ֖ים E-disse E-disse a seus-servos שִׂ֔ימוּ e-foram-colocados sobre a-cidade');
INSERT INTO verses VALUES (9424, 11, 20, 13, 'והנה profeta um um a Acabe rei-de E-disse E-disse disse yhwh yhwh הֵרְאִתָ a todo הֶהָמוֹן o-grande este eis-me o-dia בְּיָדֶךָ o-dia yhwh porque eu yhwh');
INSERT INTO verses VALUES (9425, 11, 20, 14, 'E-disse Acabe בְּמִי E-disse assim yhwh yhwh בְּנַעֲרֵי príncipes-de E-disse E-disse quem E-disse ha-milchamah E-disse tu');
INSERT INTO verses VALUES (9426, 11, 20, 15, 'וַיִּפְקֹד a נַעֲרֵי֙ príncipes-de הַמּדִינ֔וֹת וַיִּהְיוּ duzentos dois וּשְלֹשִׁים וְאַחֲרֵיהֶם פָּקַד a todo o-povo todo filhos-de Israel sete mil:');
INSERT INTO verses VALUES (9427, 11, 20, 16, 'e-saíram בָּצְהָרָיִם e-filho-de הֲדַד֩ שֹׁתֶ֨ה שִׁכּ֜וֹר ele ele וְהַמְּלָכִ֛ים שְׁלֹשִֽׁים־ u-shnayim ele עֹזֵ֥ר ele');
INSERT INTO verses VALUES (9428, 11, 20, 17, 'e-eles-saíram נַעֲרֵ֛י príncipes-de as-províncias no-primeiro-tempo e-enviou filho-de Hadad a-ele dizendo dizendo אֲנָשִׁ֕ים saíram mi-shomron');
INSERT INTO verses VALUES (9429, 11, 20, 18, 'E-disse se לְשָׁל֥וֹם יָצָ֖אוּ vida vivos e se לְמִלְחָמָ֛ה vida chayyim tipshuwm:');
INSERT INTO verses VALUES (9430, 11, 20, 19, 'e-estes saíram de a-cidade na''are príncipes-de ha-medinot ve-ha-chayil que depois-deles');
INSERT INTO verses VALUES (9431, 11, 20, 20, 'va-yakku'' homem isho va-yannusu Arã va-yir''defem Israel va-yimmale''t filho-de הֲדַד rei Arã sobre ס֖וּס e-cavaleiros');
INSERT INTO verses VALUES (9432, 11, 20, 21, '[וַיֵּצֵא֙] rei Israel e-feriu a [וְאֶת־הָרָ֑כֶב] e-[OBJ] [בַאֲרָ֖ם] [מַכָּ֥ה] [גְדוֹלָֽה]');
INSERT INTO verses VALUES (9433, 11, 20, 22, 'וַיִּגַּ֤שׁ o profeta a rei E-disse a-ele a-ele vai fortaleceu-se וְדַ֥ע e-veja a que תַּעֲשֶׂ֑ה porque לִתְשׁוּבַ֣ת השנה rei Arã olé sobre-te');
INSERT INTO verses VALUES (9434, 11, 20, 23, 'וְעַבְדֵ֨י rei-de ארם a-ele a-ele Elohim-de montes אֱלֹ֣הֵיהֶ֔ם sobre nós chazku de-ele e-entretanto nilachem itam bamishor se não nechazak de-eles');
INSERT INTO verses VALUES (9435, 11, 20, 24, 'e-a a-palavra este fez haseir hamalkim homem mikom וְשִׂ֥ים pachot sob eles');
INSERT INTO verses VALUES (9436, 11, 20, 25, 'e-tu timneh- lekha- חַ֡יִל כַּחַיִל֩ הַנֹּפֵ֨ל מֵאוֹתָ֜ךְ וְס֣וּס כַּסּ֣וּס ׀ וְרֶ֣כֶב כָּרֶ֗כֶב וְנִֽלָּחֲמָ֤ה a-eles בַּמִּישׁ֔וֹר se não נֶחֱזַ֖ק deles E-ouviu para o seu grito E-fez assim');
INSERT INTO verses VALUES (9437, 11, 20, 26, 'e-houve para a sua volta השנה e-contou filho-de חัดד a Arã e-subiu afékah que com Israel');
INSERT INTO verses VALUES (9438, 11, 20, 27, 'e-filhos-de Israel e se agitaram e se contorceram e-foram para-enfrentá-los e acamparam filhos-de Israel diante deles como dois carnes ez''im e Aram מִלְא֖וּ a a-terra');
INSERT INTO verses VALUES (9439, 11, 20, 28, '[וַיִּגַּ֞שׁ] homem o-Elohim E-disse a rei E-disse E-disse yhwh disse yhwh porque que אָמְר֤וּ Aram yhwh montes yhwh ele Elohim-de עֲמָקִ֖ים ele וְ֠נָתַתִּי a todo הֶהָמ֨וֹן yhwh o-este yhwh e-voces-sabereis porque eu yhwh');
INSERT INTO verses VALUES (9440, 11, 20, 29, 'וַֽיַּחֲנ֧וּ Estas נֹֽכַח־ estes sete e-houve e-foi no-dia o-sétimo וַתִּקְרַב֙ a-guerra e-eles-feriram filhos-de Israel a אֲרָ֛ם cem um minha perna em-dia um');
INSERT INTO verses VALUES (9441, 11, 20, 30, 'e se levantaram os sobreviventes Apequeh a a-cidade e-caiu a muralha sobre vinte e-sete mil homem osRestantes e-filho-de Hadade se levantou E-veio a a-cidade quarto no quarto:');
INSERT INTO verses VALUES (9442, 11, 20, 31, 'e-disseram a-ele seus servos eis-a por-favor que porque reis casa Israel porque eles Hesed eles Nasima não שַׂקִּים בְּמָתְנֵ֜ינוּ וַחֲבָלִ֣ים בְּרֹאשֵׁ֗נוּ וְנֵצֵא֙ a rei Israel אוּלַ֖י יְחַיֶּ֥ה a alma-tua');
INSERT INTO verses VALUES (9443, 11, 20, 32, 'וַיַּחְגְּרוּ֩ שַׂקִּים בְּמָתְנֵיהֶ֜ם וַחֲבָלִ֣ים no-primeiro-deles e-vieram a rei Israel e-disseram servo-teu disse Haddad disse E-disse por-favor vida E-disse ele viveu achi ela');
INSERT INTO verses VALUES (9444, 11, 20, 33, 'e-os-homens e-prevejam e-agitaram-se e-decidiram deles e-disseram אָחִ֣יךָ filho-de E-disse E-disse בֹּ֣אוּ tomaram-no a-ele a-ele filho-de Hadade e-subiram-no sobre a merkabah׃');
INSERT INTO verses VALUES (9445, 11, 20, 34, 'E-disse a-ele ha-arim que l''akha— meu pai de-a teu-pai ashevi'' a-ti tashvim para-ti b''dammešek'' conforme- nome pai-meu em-Samaria e-eu b''barit ašalchecha'' va''yikra— a-ele berith va''yashlachu''׃');
INSERT INTO verses VALUES (9446, 11, 20, 35, 'e-homem um de-filhos-de os profetas disse a re''ehu'' yhwh yhwh o כֵּ֣יני נָ֑א e וַיְמָאֵ֥ן o homem para matá-lo׃');
INSERT INTO verses VALUES (9447, 11, 20, 36, 'E-disse a-ele porque que não ouviste-sha- yhwh yhwh eis-você holêk de-mi- e mata-lo- o aryeh E-andou de-lui- e achou-o o aryeh e o acertou:');
INSERT INTO verses VALUES (9448, 11, 20, 37, 'e-ele-achou homem outro E-disse acerta-o נָ֑א e-ferrou-o o homem bate-o e feriu:');
INSERT INTO verses VALUES (9449, 11, 20, 38, 'E-andou o-profeta e-estabeleceu ao-rei sobre ha-dar''ke'' e se esticou: no pó sobre os-seus-olhos');
INSERT INTO verses VALUES (9450, 11, 20, 39, 'e-houve o-rei passando e-ele chamou a E-disse E-disse seu servo: sair dentro de a-guerra e eis que e-trouxe סָר E-veio E-disse homem E-disse שְׁמֹר֙ a o-homem este se debaixo יִפָּקֵ֔ד e-será nafsh-ká debaixo-de debaixo ou ouro prata תִּשְׁקֽוֹל׃');
INSERT INTO verses VALUES (9451, 11, 20, 40, 'e-houve [עַבְדְּךָ֗] fez [הֵ֛נָּה] [וָהֵ֖נָּה] e-ele [אֵינֶ֑נּוּ] E-disse a-ele rei-de Israel assim tu tu');
INSERT INTO verses VALUES (9452, 11, 20, 41, 'וַיְמַהֵ֕ר e-removeu a הָ֣אֲפֵ֔ר os olhos e reconheceu ele ele Israel porque que ele');
INSERT INTO verses VALUES (9453, 11, 20, 42, 'E-disse a-ele assim disse yhwh porque enviei a homem-de meu devasso imediatamente debaixo nafsh-ká debaixo-de debaixo e o teu povo debaixo-de seu-povo');
INSERT INTO verses VALUES (9454, 11, 20, 43, 'E-andou rei-de Israel sobre casa-dele príncipe e a ira E-veio Safarom:');
INSERT INTO chapters VALUES (312, 11, 21, 29);
INSERT INTO verses VALUES (9455, 11, 21, 1, 'e-houve outro as-palavras estes vinho ser לְנָב֥וֹת הַיִּזְרְעֵאלִ֖י que בְּיִזְרְעֶ֑אל אֵ֚צֶל o-santuário Acabe rei Samaria');
INSERT INTO verses VALUES (9456, 11, 21, 2, 'e-falou Acabe a נָב֣וֹת ׀ dizendo dá- לִּ֨י a כַּרְמְךָ֜ e-seja que ele יָרָ֗ק porque ele proximo a-ti em-o-casa וְאֶתְּנָ֤ה bom nós כֶּ֖רֶם bom de-ele mãe bom em-tua-olho אֶתְנָה- para-ti prata מְחִ֥יר este');
INSERT INTO verses VALUES (9457, 11, 21, 3, 'E-disse Nabote a Acabe a-mim para-mim מֵֽיהוָ֔ה מִתִּתִּ֛י a para-ti pais-meus para-ti');
INSERT INTO verses VALUES (9458, 11, 21, 4, 'E-veio Acaías a seu lar סַ֣ר וְזָעֵ֗ף sobre a-ele que palavra E-disse נָבוֹת֙ a-ti E-disse não darei a-ti a נַחֲלַ֣ת אֲבוֹתָ֑י vayishkav sobre מִטָּת֔וֹ vayassab a sua-face e-não אָ֥כַל pão');
INSERT INTO verses VALUES (9459, 11, 21, 5, 'וַתָּבוֹא a-ele Ízébel mulher-sua e falou a-ele que isto Ruach-ka Sara e-ainekha comia pão');
INSERT INTO verses VALUES (9460, 11, 21, 6, 'e-falou a-ela porque adabber a Nabot a-ele va-omar para-ele dá- para-mim a tu bikesef ou se E-disse אתָ a-ti para-ti kerem tachthayo E-disse não darei a-ti a כרמי׃');
INSERT INTO verses VALUES (9461, 11, 21, 7, 'E-disse a-ele [אִיזֶ֣בֶל] [אִשְׁתּ֔וֹ] tu [עַתָּ֛ה] farás [מְלוּכָ֖ה] sobre Israel levantou [וְיִטַ֣ב] pão [אֲנִי֙] [אֶתֵּ֣ן] a-ti darei [נָב֥וֹת] a');
INSERT INTO verses VALUES (9462, 11, 21, 8, 'וַתִּכְתֹּ֤ב cartas no-nome-de Acabe e selou com o seu selo e enviou a os anciãos e-a as viúvas que em sua cidade os-habitantes a Naboth:');
INSERT INTO verses VALUES (9463, 11, 21, 9, 'e escreveu nos livros dizendo leiam צָמֹ֔א וְהוֹשִׁיבֻ֣ו a Nabote no-começo o-povo');
INSERT INTO verses VALUES (9464, 11, 21, 10, 'וְהוֹשִׁיבֻ֣ו dois homens filhos-de בְּלִיַּעַל֮ נֶגְדּוֹ֒ dizendo dizendo ברכת Elohim e-rei וְהוֹצִיאֻ֣הוּ וְסִיקְלוּ֥הוּ E-morreu');
INSERT INTO verses VALUES (9465, 11, 21, 11, 'וַיַּעַשׂ֩וּ homens-de עִירוֹ הַזְּקֵנִ֣ים e os poços que os-habitam em sua cidade como enviou a-eles Izabel como foi escrito nos livros que enviou a-eles');
INSERT INTO verses VALUES (9466, 11, 21, 12, 'קָרְא֖וּ jejuem e trouxeram a Nabote no-começo o-povo');
INSERT INTO verses VALUES (9467, 11, 21, 13, 'e-vieram segundo os homens filhos-de sem ele e-habitaram נֶגְדּוֹ וַיְעִדֻהוּ homens-de הַבְּלִיַּעַל diante נָב֗וֹת dizendo o-povo dizendo abençoou נָב֛וֹת Elohim e-rei וַיֹּצִאֻ֙הוּ֙ de-fora para-a-cidade וַיִּסְקְלֻ֥הוּ בָאֲבָנִ֖ים E-morreu');
INSERT INTO verses VALUES (9468, 11, 21, 14, 'וַֽיִּשְׁלְח֖וּ a dizendo dizendo סֻקַּ֥ל Nabote E-morreu');
INSERT INTO verses VALUES (9469, 11, 21, 15, 'e-houve כשמע אִיזֶ֔בֶל porque סֻקַּ֥ל Nabote E-disse וַתֹּ֨אמֶר אִיזֶ֜בֶל a Acabe levantou רֵ֞שׁ a כֶּ֣רֶם ׀ נָב֣וֹת הַיִּזְרְעֵאלִ֗י que מֵאֵן֙ que a-ti בְכֶ֔סֶף vida não-há נָב֛וֹת viveu porque morreu');
INSERT INTO verses VALUES (9470, 11, 21, 16, 'e-houve [כִּשְׁמֹ֥עַ] Acabe que morreu [נָב֑וֹת] E-levantou [אַחְאָ֗ב] [לָרֶ֛דֶת] a [נָב֥וֹת] [הַיִּזְרְעֵאלִ֖י] [לְרִשְׁתּֽוֹ׃]');
INSERT INTO verses VALUES (9471, 11, 21, 17, 'e-houve palavra-de yhwh a dizendo');
INSERT INTO verses VALUES (9472, 11, 21, 18, 'levantou רֵ֗ד לִקְרַ֛את אַחְאָב rei-de Israel que eis behold no vinhedo נָב֔וֹת que וירד nome לרשותיו׃');
INSERT INTO verses VALUES (9473, 11, 21, 19, 'e falaste a-ele dizendo assim disse yhwh הרגתָ e-também ירשתָ a-ele dizendo dizendo disse yhwh yhwh em-o-lugar que לקקוּ הכלבים֙ a sangue נבות ילוקוּ הכלבים֙ a sangue-teu também tu');
INSERT INTO verses VALUES (9474, 11, 21, 20, 'E-disse Acabe a Elias המצאתני E-disse E-disse [יַ֚עַן] porque [לַעֲשׂ֥וֹת] para-fazer o-mal yhwh yhwh');
INSERT INTO verses VALUES (9475, 11, 21, 21, 'eis-me a-ti maldade [אֵלֶ֙יךָ֙] depois-de-ti [וּבִעַרְתִּ֖י] לְאַחְאָב֙ cavas [לְאַחְאָב֙] [מַשְׁתִּ֣ין] [בְּקִ֔יר] em-Israel');
INSERT INTO verses VALUES (9476, 11, 21, 22, 'e-darei a [כְּבֵית֙] [יָרָבְעָ֣ם] Jeroboão filho-de [בַּעְשָׁ֣א] [בֶן־אֲחִיָּ֑ה] [אֶל־הַכַּ֙עַס֙] filho-de [הִכְעַ֔סְתָּ] a [אֶת־יִשְׂרָאֵֽל] que a Israel');
INSERT INTO verses VALUES (9477, 11, 21, 23, 'וְגַ֨ם־ para Izabel yhwh dizendo dizendo הַכְּלָבִ֛ים comerão a אִיזֶ֖בֶל בְּחֵ֥ל Jeová-sara');
INSERT INTO verses VALUES (9478, 11, 21, 24, 'הַמֵּת לְאַחְאָב֙ na-cidade eles-comerão os cães e o morto no-campo eles-comerão ave os-céus');
INSERT INTO verses VALUES (9479, 11, 21, 25, 'somente não foi -como Ahab que foi vendido para-fazer o-mal yhwh yhwh ele ocultou-se ele -A Isabel esposa-dele');
INSERT INTO verses VALUES (9480, 11, 21, 26, 'e aborreceu muito para-andar depois-de as turbas como-tudo que fizeram o-amorreu que ele-desapossou yhwh de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (9481, 11, 21, 27, 'e-houve quando-ouviram Acabe a hadavarim estes e-ele-partiu as-roupas-seu e pôs-se a caixão sobre a-carne-dele e fastiou-se e-ele-deitou no-saqu e-foi at:');
INSERT INTO verses VALUES (9482, 11, 21, 28, 'e-aconteceu palavra-de yhwh a dizendo o-Tisbita para-dizer');
INSERT INTO verses VALUES (9483, 11, 21, 29, 'viste? porque se-abaixou Acabe מִלְּפָנָ֑י porque porque se-abaixou perante-me não a-maldição nos-seus-dias em-dias-de be-no levarei o-mal sobre casa-dele');
INSERT INTO chapters VALUES (313, 11, 22, 54);
INSERT INTO verses VALUES (9484, 11, 22, 1, 'e-habitaram três dois não-havia guerra entre Arã e-entre Israel');
INSERT INTO verses VALUES (9485, 11, 22, 2, 'e-houve em-a-ano o-terceiro e desceu Jeosafá rei-de Judá a rei Israel');
INSERT INTO verses VALUES (9486, 11, 22, 3, 'E-disse rei-de Israel a seus-servos que vistes porque a-nos altura Galaad e-nós de pensamentos da recepção a-ela de-mão-de rei aram');
INSERT INTO verses VALUES (9487, 11, 22, 4, 'E-disse a Jeosafá irás comigo para-a-guerra altura E-disse E-disse jehosafat a rei Israel como-eu como-tu como-povo-meu como-povo-teu como-cavalos-meus como-cavalos-teus');
INSERT INTO verses VALUES (9488, 11, 22, 5, 'E-disse Josafá a rei Israel buscou por-favor yhwh a palavra yhwh');
INSERT INTO verses VALUES (9489, 11, 22, 6, 'e reuniu rei-de Israel a os profetas quatro E-disse homem E-disse a-eles הַאֵלֵ֞ךְ sobre Ramote גִּלְעָ֛ד folhas-de se אֶחְדָּ֑ל e-disseram sobe E-deu Adonai em-mão-de o rei');
INSERT INTO verses VALUES (9490, 11, 22, 7, 'E-disse Jeosafá não-há poh profeta a-yhwh ainda וְנִדְרְשָׁ֖ה מֵאוֹתֽוֹ׃');
INSERT INTO verses VALUES (9491, 11, 22, 8, 'E-disse rei-de [׀] a [ע֣וֹד] [אִישׁ־אֶחָ֡ד] homem-de um [מֵאֹת֜וֹ] a yhwh que e-eu [עָלַ֥י] bom que [אִם־רָ֔ע] [מִיכָ֖יְהוּ] bom E-disse se mau [הַמֶּ֖לֶךְ] filho-de E-disse a');
INSERT INTO verses VALUES (9492, 11, 22, 9, 'E-chamou rei Israel a um E-disse E-disse [מִיכָ֥יְהוּ] [בֶן־יִמְלָֽה] filho-de');
INSERT INTO verses VALUES (9493, 11, 22, 10, 'e-rei Israel וִֽיהוֹשָׁפָ֣ט rei-de יהודה ישבים homem sobre seu trono מלובשים בגדים בגורן entrada portão Samaria e-todo os-profetas MITנבאים diante-deles');
INSERT INTO verses VALUES (9494, 11, 22, 11, 'E-fez a-ele [צִדְקִיָּ֥ה] filho-de [קַרְנֵ֣י] [בַרְזֶ֑ל] E-disse E-disse yhwh disse yhwh [אֶת־אֲרָ֖ם] [עַד־כַּלֹּתָֽם] a até');
INSERT INTO verses VALUES (9495, 11, 22, 12, 'e-todo הנביאים נבאים dizendo folhas-de עליה רמות Gil''ad והצלחה yhwh yhwh na-mão-de o rei');
INSERT INTO verses VALUES (9496, 11, 22, 13, 'e o mensageiro que e-caminhou para chamar Micaías palavra a-ele dizendo eis por-favor palavras os profetas bom um bom a o-rei será por-favor segundo a palavra um deles e falaste bom');
INSERT INTO verses VALUES (9497, 11, 22, 14, 'E-disse Micaías vive que porque a yhwh diga ele a-mim ele אֲדַבֵּֽר׃');
INSERT INTO verses VALUES (9498, 11, 22, 15, 'e veio a E-disse E-disse a-ele a-ele Michaiohu Hanelke a Ramote Giluad E-disse a-ele folhas-de E-disse a-ele yhwh veHatzloch e colocou yhwh em-mão-de o rei');
INSERT INTO verses VALUES (9499, 11, 22, 16, 'E-disse a-ele o-rei até kamme feAmim eu Mashbe''ekha que não tedaber a-mim yhwh Emet yhwh yhwh');
INSERT INTO verses VALUES (9500, 11, 22, 17, 'E-disse eu vi a todo Israel nafotsim a as montanhas -o rebanho E-disse yhwh a-eles o pastor E-disse yhwh não senhores para os retornarão homem-de a seu lar em-paz');
INSERT INTO verses VALUES (9501, 11, 22, 18, 'E-disse rei-de Israel a יהוהSPORTÁFAT não-verdade eu-disse a-ti bom que sobre-mim bom porque se mau');
INSERT INTO verses VALUES (9502, 11, 22, 19, 'E-disse portanto ouviu palavra-de yhwh eu vi a yhwh habitou sobre trono-dele e-todo exército os-céus ficou-em-pé sobre-ele do seu lado direito e do seu lado esquerdo:');
INSERT INTO verses VALUES (9503, 11, 22, 20, 'E-disse yhwh quem -a beleza a Acabe e-suba וְיִפֹּ֖ל beratomot E-disse E-disse este בְּכֹ֔ה e-esta disse בְּכֹֽה׃');
INSERT INTO verses VALUES (9504, 11, 22, 21, 'e-saiu הָר֗וּחַ e-yaa-amod diante-de yhwh E-disse eu אֲפַתֶּ֑נּוּ E-disse yhwh a-ele בַּמָּֽה׃');
INSERT INTO verses VALUES (9505, 11, 22, 22, 'E-disse אֵצֵא֙ וְהָיִ֙יתִי֙ espírito mentira por-me todo E-disse E-disse תְּפַתֶּה֙ e-também תּוּכָ֔ל sai e-faze- assim');
INSERT INTO verses VALUES (9506, 11, 22, 23, 'e-agora eis dar yhwh espírito mentira por-me todo Estas estes e-יהוה palavra sobre-ti mal');
INSERT INTO verses VALUES (9507, 11, 22, 24, 'e se aproximou tsidqiyahu filho-de kenaanah e feriu a E-disse sobre a-lhechi E-disse qual isto passou espírito-de yhwh de mim de-falar te');
INSERT INTO verses VALUES (9508, 11, 22, 25, 'E-disse de Micaia veja-você viu no-dia aquele que vai quarto no quarto para o esconder');
INSERT INTO verses VALUES (9509, 11, 22, 26, 'E-disse rei Israel qach a de Micaia e o reterei a Amon príncipe-de a-cidade e-a Yoash filho-de o rei');
INSERT INTO verses VALUES (9510, 11, 22, 27, 'e dirás assim disse o-rei שִׂ֥ימוּ a este casa do leão pão לֶחֶם ao aperto e águas até até venha em paz');
INSERT INTO verses VALUES (9511, 11, 22, 28, 'E-disse de Micaia se volta volverás em-paz yhwh palavra E-disse em-mim E-disse ouvi para-sempre כלם׃');
INSERT INTO verses VALUES (9512, 11, 22, 29, 'e-subiu rei-de Israel e-jo-sha-fat rei-de Judá Ramote gil-ad');
INSERT INTO verses VALUES (9513, 11, 22, 30, 'E-disse rei Israel a Jeosafá se-preparou e-vai para-a-marcha e-tu vestir-te com-tus-roupas e-se-preparou rei Israel e-vai na-guerra');
INSERT INTO verses VALUES (9514, 11, 22, 31, 'e-rei arã ordenou a שַׂרִים הָרֶכֶב que a-ele dizendo não dizendo não תַּלְיֽיחֲמוּ que pequeno e-a sozinho porque se a rei Israel sozinho');
INSERT INTO verses VALUES (9515, 11, 22, 32, 'e-houve כְּרָא֥וֹת príncipes-de הָרֶכֶב a Jeosafá וְהֵ֤ם disseram somente ele Israel ele וַיִּסְר֖וּ sobre-ele לְתַלְיָחֵ֑ם וַיִּזְעַ֖ק יְהוֹשָׁפַֽט׃');
INSERT INTO verses VALUES (9516, 11, 22, 33, 'e-houve [כִּרְאוֹת֙] príncipes-de [הָרֶ֔כֶב] porque não ele Israel ele');
INSERT INTO verses VALUES (9517, 11, 22, 34, 'e-homem מָשַׁ֤ךְ בַּקֶּ֙שֶׁת֙ לְתֻמּ֔וֹ וַיַּכֶּה֙ a rei entre entre e-entre e-entre E-disse E-disse לְרַכָּב֗וֹ הֲפֹ֥ךְ yadcha וְהוֹצִיאֵ֥נִי que o-acampamento porque הָחֳלֵֽיתִי׃');
INSERT INTO verses VALUES (9518, 11, 22, 35, 'וַתַּעֲלֶ֤ה a-guerra no-dia aquele e-o-rei ser STAAMD BaMRRKBa nachach Arã E-morreu na-atardecer VYTTZQ DAM- a-ferida a KHAK aquele que monta');
INSERT INTO verses VALUES (9519, 11, 22, 36, 'e-ele-passou HaRNNAH no-acampamento KVB o-sol dizendo homem a cidade-dele e-homem a terra-dele');
INSERT INTO verses VALUES (9520, 11, 22, 37, 'E-morreu o-rei VYVA Samaria e-eles-sepultaram a o-rei בְּשֹׁמְרֽוֹן׃');
INSERT INTO verses VALUES (9521, 11, 22, 38, 'VYTSTFP a sobre sobre BRKHT shomron VYLOQY os-cães a seu-sangue e-as-adúlfas lavem-se yhwh yhwh que palavra');
INSERT INTO verses VALUES (9522, 11, 22, 39, 'e-remanescente palavras Acabe e-todo que fez e-casa da-árvore edificar בָּנָה e-todo edificar que construiu acaso-nao eles escritos sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9523, 11, 22, 40, 'e-ele-deitou Acabe com pais-seus e-reinou Acazias seu-filho em-lugar-dele');
INSERT INTO verses VALUES (9524, 11, 22, 41, 'e-Joás filho-de Asa rei sobre Judá no-ano-de quatro לְאַחְאָב rei Israel');
INSERT INTO verses VALUES (9525, 11, 22, 42, 'Jeosafá filho-de trinta e-cinco ano no seu reinado e-vinte e cinco ano rei em-Jerusalém sua-mãe sua-mãe deserto filha-de enviei:');
INSERT INTO verses VALUES (9526, 11, 22, 43, 'E-andou em-todo caminho seu-pai seu-pai nós desviou de-ele para-fazer yhwh em-olhos-de yhwh');
INSERT INTO verses VALUES (9527, 11, 22, 44, 'somente as baamas não se-marcharam ainda o-povo מְזַבְּחִ֥ים וּֽמְקַטְּרִ֖ים בַּבָּמֽוֹת׃');
INSERT INTO verses VALUES (9528, 11, 22, 45, 'וַיַּשְׁלֵ֥ם Josafá com rei Israel');
INSERT INTO verses VALUES (9529, 11, 22, 46, 'e-resto-de palavras Joash וּגְבוּרָת֥וֹ que fez e-que נִלְחָ֑ם acaso-nao eles escritos sobre livro palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9530, 11, 22, 47, 'וְיֶ֙תֶר֙ הַקָּדֵ֔שׁ que נִשְׁאַ֔ר nos-dias אָסָ֣א seu-pai em-o-fogo de a-terra');
INSERT INTO verses VALUES (9531, 11, 22, 48, 'e-rei-de אֵ֛ין בֶּאֱד֖וֹם stood rei');
INSERT INTO verses VALUES (9532, 11, 22, 49, 'יְהוֹשָׁפָ֡ט אֳנִיּ֨וֹת תַּרְשִׁ֜ישׁ לָלֶ֧כֶת אוֹפִ֛ירָה לַזָּהָ֖ב e-não andou porque navios em-Ezion homem:');
INSERT INTO verses VALUES (9533, 11, 22, 50, 'אָ֠ז disse אֲחַזְיָ֤הוּ filho-de Acabe a Jeosafá [עִם־עֲבָדֶ֖יךָ] [בָּאֳנִיּ֑וֹת] com servos-teus [יְהוֹשָׁפָֽט] e-não pai יְהוֹשָׁפַֽט׃');
INSERT INTO verses VALUES (9534, 11, 22, 51, 'e-deitou-se jehosafat com seus-pais [עִם־אֲבֹתָ֔יו] com seus-pais seu-pai Davi seu-pai e-reinou יהורם filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9535, 11, 22, 52, 'אֲחַזְיָ֣הוּ filho-de Acabe rei sobre Israel em-Samaria no-ano-de sete dezoito para-Josafá rei Judá e-reinou sobre Israel שנתים׃');
INSERT INTO verses VALUES (9536, 11, 22, 53, 'E-fez o-mal aos-olhos-de yhwh E-andou בְּדֶ֤רֶךְ seu-pai [וּבְדֶ֣רֶךְ] sua-mãe [וּבְדֶ֙רֶךְ֙] Jeroboão filho-de נְבוֹת que fez-pecar a Israel');
INSERT INTO verses VALUES (9537, 11, 22, 54, '[וַֽיַּעֲבֹד֙] a o-Baal a-ele a-ele [אֶת־יְהוָה֙] a yhwh Elohim-de Israel seu-pai que fez seu-pai');
INSERT INTO books VALUES (12, '2KI', '2 Reis', 'AT', 25);
INSERT INTO chapters VALUES (314, 12, 1, 18);
INSERT INTO verses VALUES (9538, 12, 1, 1, 'e-rebelou Moabe em-Israel atrás-de morrendo Acabe');
INSERT INTO verses VALUES (9539, 12, 1, 2, 'e-caiu Acazias através-de a-grade em-câmara-alta-sua que em-Samaria e-adoeceu e-enviou mensageiros E-disse para-eles ide consultai em-Baal Zebube Elohim-de Ecrom se viverei de-doença-minha este');
INSERT INTO verses VALUES (9540, 12, 1, 3, 'e-mensageiro yhwh palavra a Elias o-Tisbita folhas-de sobe para-encontro-de mensageiros-de rei-de Samaria e-fala a-eles a-por-não não-há Elohim em-Israel vós ides para-consultar em-Baal Zebube Elohim-de Ecrom');
INSERT INTO verses VALUES (9541, 12, 1, 4, 'e-portanto assim yhwh yhwh a-cama que subiste nome que morrendo morrerás porque morte-de morrerás E-andou Elias');
INSERT INTO verses VALUES (9542, 12, 1, 5, 'e-voltaram os-mensageiros a-ele E-disse a-eles que- isto voltastes');
INSERT INTO verses VALUES (9543, 12, 1, 6, 'e-disseram a-ele homem subiu subir E-disse E-disse ide voltai a o-rei que enviou vós a-ele a-ele disse yhwh yhwh a-por-não não-há tu em-Israel tu enviou para-consultar em-Baal Zebube Elohim-de Ecrom portanto a-cama que subiste nome morrerás descerás dela porque morrer morrerás');
INSERT INTO verses VALUES (9544, 12, 1, 7, 'e-falou a-eles que juízo o-homem que subir para-encontro-vosso e-falou a-vós a as-palavras as estas');
INSERT INTO verses VALUES (9545, 12, 1, 8, 'e-disseram a-ele homem בַּ֣עַל cabelo e-cinto pele cingido em-lombos-seus E-disse Elias o-Tisbita ele');
INSERT INTO verses VALUES (9546, 12, 1, 9, 'e-enviou a-ele príncipe-de cinquenta e-comandante-seus a-ele a-ele e-eis habitou sobre cabeça a-ele e-falou para-ele homem הָֽאֱלֹהִ֔ים o-rei palavra dominai');
INSERT INTO verses VALUES (9547, 12, 1, 10, 'e-respondeu Elias e-falou a comandante-de o-cinquenta e-se- homem Elohim eu desce fogo de os-céus e-consuma a-ti e-a e-comeste ele fogo de os-céus e-comeu a-ele e-a cinquenta-seus');
INSERT INTO verses VALUES (9548, 12, 1, 11, 'e-voltou e-enviou a-ele príncipe-de cinquenta outro e-comandante-seus e-respondeu a-ele para-ele homem os-Elohim assim disse o-rei depressa dominai');
INSERT INTO verses VALUES (9549, 12, 1, 12, 'e-respondeu Elias e-falou a-eles se homem האלהים eu desce fogo de os-céus e-consuma a-ti e-a cinquenta-teu e-comeste ele Elohim de os-céus e-comeu a-ele e-a cinquenta-seus');
INSERT INTO verses VALUES (9550, 12, 1, 13, 'e-voltou e-enviou príncipe-de cinquenta terceiros e-comandante-seus e-subiu E-veio príncipe-de o-cinquenta o-terceiro e-ajoelhou sobre joelhos-dele diante-de a-ele e-suplicou a-ele e-falou para-ele homem הָֽאֱלֹהִ֔ים seja-preciosa por-favor Estas e-alma-de servos-teus estes cinquenta em-olhos-teus');
INSERT INTO verses VALUES (9551, 12, 1, 14, 'eis desceu fogo de e-comeste e-consumiu a segundo chefes-de o-cinquenta e-agora e-a cinquentas-deles e-agora seja-preciosa alma-minha em-olhos-teus');
INSERT INTO verses VALUES (9552, 12, 1, 15, 'e-falou mensageiro-de yhwh a Elias desce com-ele a temas de-face-dele E-levantou e-desceu com-ele a o rei');
INSERT INTO verses VALUES (9553, 12, 1, 16, 'e-falou a-ele assim yhwh yhwh porque que enviaste mensageiros para-consultar em-Baal Zebube Elohim-de Ecrom a-por-não não-há Elohim em-Israel para-consultar em-palavra-dele portanto a-cama que subiste morrerás não descerás dela porque morrer morrerás');
INSERT INTO verses VALUES (9554, 12, 1, 17, 'E-morreu conforme-palavra-de yhwh que palavra Elias e-reinou Jeorão em-lugar-dele em-ano-de dois para-Jeorão filho-de Josafá rei Judá que não a-ele filho filho');
INSERT INTO verses VALUES (9555, 12, 1, 18, 'e-resto-de palavras-de Acazias que fez não eles escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO chapters VALUES (315, 12, 2, 25);
INSERT INTO verses VALUES (9556, 12, 2, 1, 'e-houve quando-subir yhwh a Elias na-tempestade os-céus E-andou Elias e-Eliseu de o-Gilgal');
INSERT INTO verses VALUES (9557, 12, 2, 2, 'E-disse Elias a Eliseu fica que yhwh porque yhwh E-disse até casa-de El E-disse Eliseu vive yhwh e-vive alma-tua se te-deixarei e-desceram casa-de El');
INSERT INTO verses VALUES (9558, 12, 2, 3, 'e-saíram filhos-de os-profetas que casa-de a-ele a que o-dia yhwh sabes porque de-cima-de yhwh E-disse a adonai-teu de-sobre cabeça-tua E-disse também eu conheci cala-te');
INSERT INTO verses VALUES (9559, 12, 2, 4, 'E-disse a-ele Elias Eliseu fica por-favor aqui que yhwh enviou-me Jericó E-disse vive yhwh e-vive alma-tua se te-deixarei e-vieram Jericó');
INSERT INTO verses VALUES (9560, 12, 2, 5, 'e-aproximaram-se filhos-de os-profetas que em-Jericó a-ele Eliseu que o-dia yhwh porque o-dia de-cima-de tomou E-disse adonai-teu de-sobre cabeça-tua E-disse também eu conheci cala-te');
INSERT INTO verses VALUES (9561, 12, 2, 6, 'E-disse a-ele Elias fica por-favor que yhwh yhwh enviou-me E-disse E-disse vive yhwh e-vive alma-tua se te-deixarei e-foram dois-deles');
INSERT INTO verses VALUES (9562, 12, 2, 7, 'e-cinquenta homem de-filhos-de os-profetas foram e-se-posicionaram em-frente de-longe e-dois-deles se-posicionaram sobre o-Jordão');
INSERT INTO verses VALUES (9563, 12, 2, 8, 'E-tomou Elias a manto-seu e-enrolou e-golpeou a as-águas e-se-dividiram para-cá e-para-lá e-atravessaram dois-deles em-terra-seca');
INSERT INTO verses VALUES (9564, 12, 2, 9, 'e-houve quando-atravessaram e-אֵלִיָּהוּ disse a אֱלִישָׁע pede que farei para-ti antes-de E-disse de-contigo E-disse Eliseu e-seja por-favor boca-de dois em-espírito-teu para-mim');
INSERT INTO verses VALUES (9565, 12, 2, 10, 'E-disse dificultaste para-pedir se vires a-mim tomou de-contigo será para-ti não será não não será');
INSERT INTO verses VALUES (9566, 12, 2, 11, 'e-houve eles caminhando caminhar e-falar e-eis carro-de fogo e-cavalos-de fogo entre entre dois-deles e-subiu Elias na-tempestade os-céus');
INSERT INTO verses VALUES (9567, 12, 2, 12, 'e-אֱלִישָׁע viu e-ele gritando pai-meu pai-meu carro-de Israel e-cavaleiros-seus e-não viu-o ainda e-ele-fortaleceu em-roupas-suas e-rasgou-as em-dois pedaços');
INSERT INTO verses VALUES (9568, 12, 2, 13, 'e-levantou a manto-de אֵלִיָּ֔הוּ que caiu de-sobre-ele e-voltou e-se-posicionou sobre beira-de o-Jordão');
INSERT INTO verses VALUES (9569, 12, 2, 14, 'E-tomou a manto-de Elias que caiu de-sobre-ele e-golpeou a yhwh E-disse onde yhwh Elohim-de אֵלִיָּ֑הוּ também ele e-golpeou a as-águas e-se-dividiram para-cá e-para-cá e-atravessou אֱלִישָֽׁע');
INSERT INTO verses VALUES (9570, 12, 2, 15, 'e-viram-o filhos-de os-profetas que em-יְרִיחוֹ em-frente espírito descansou espírito אֵלִיָּ֖הוּ sobre אֱלִישָׁ֑ע e-vieram ao-encontro-dele e-se-prostraram para-ele para-terra');
INSERT INTO verses VALUES (9571, 12, 2, 16, 'e-disseram a-ele eis-que- por-favor há a servos-teus cinquenta homens filhos-de fortes irão espírito yhwh a adonai-de-ti para-que-não levantaram-o espírito yhwh e-lançaram-o E-disse não ou em-uma-de E-disse não enviareis');
INSERT INTO verses VALUES (9572, 12, 2, 17, 'e-insistiram nele E-disse envergonhar E-disse enviai e-enviaram cinquenta homem e-buscaram três-de dias e-não encontraram-o');
INSERT INTO verses VALUES (9573, 12, 2, 18, 'e-voltaram a-ele e-ele habitou em-Jericó E-disse a-eles não disse a-vós a ireis');
INSERT INTO verses VALUES (9574, 12, 2, 19, 'e-disseram homens-de a-cidade a Eliseu eis-que- por-favor bom a-cidade bom como-que Adonai viu E-a-terra más e-a-terra aborta');
INSERT INTO verses VALUES (9575, 12, 2, 20, 'E-disse tomai a-mim recipiente nova e-colocai nome sal a-ele a-ele');
INSERT INTO verses VALUES (9576, 12, 2, 21, 'e-saiu a fonte-de as-águas e-lançou E-disse sal yhwh assim disse yhwh curei para-as-águas os-estes não será de-lá mais morte e-aborto');
INSERT INTO verses VALUES (9577, 12, 2, 22, 'e-foram-curadas as-águas até o-dia esta conforme-palavra-de Eliseu que palavra');
INSERT INTO verses VALUES (9578, 12, 2, 23, 'e-ofereceu de-lá casa-de El e-ele subindo no-caminho e-jovens pequenos saíram de a-cidade e-zombaram-de a-ele folhas-de a-ele folhas-de careca sobe careca');
INSERT INTO verses VALUES (9579, 12, 2, 24, 'e-voltou-se atrás-dele e-viu-os e-amaldiçoou-os no-nome-de yhwh e-saíram duas ursas de a-floresta e-despedaçaram de-eles quarenta e-dois filhos');
INSERT INTO verses VALUES (9580, 12, 2, 25, 'E-andou de-lá a monte-de o-Carmelo e-de-lá retornou Samaria');
INSERT INTO chapters VALUES (316, 12, 3, 27);
INSERT INTO verses VALUES (9581, 12, 3, 1, 'e-Jorão filho-de Acabe rei sobre Israel em-Samaria no-ano-de oito dezoito para-Josafá rei Judá e-reinou duas- doze anos');
INSERT INTO verses VALUES (9582, 12, 3, 2, 'e-fez o-mal em-olhos-de yhwh somente não como-pai-seu e-como-mãe-sua e-removeu a coluna-de o-Baal que seu-pai pai-seu');
INSERT INTO verses VALUES (9583, 12, 3, 3, 'somente em-pecados-de Jeroboão filho-de Nebate que fez-pecar a Israel aderiu não apartou de-elas');
INSERT INTO verses VALUES (9584, 12, 3, 4, 'e-Mesa rei-de ser foi criador-de-ovelhas e-pagava para-rei-de Israel cem mil cordeiros e-cem mil carneiros lã');
INSERT INTO verses VALUES (9585, 12, 3, 5, 'e-houve como-morte-de Acabe e-rebelou-se rei-de Moabe em-rei-de Israel');
INSERT INTO verses VALUES (9586, 12, 3, 6, 'e-saiu o-rei Jeorão no-dia o-aquele de-Samaria e-contou a todo Israel');
INSERT INTO verses VALUES (9587, 12, 3, 7, 'E-andou e-enviou a Jeosafá dizendo Judá para-dizer rei Moabe rebelou-se em-mim irás comigo E-disse Moabe para-a-guerra E-disse subirei como-eu como-tu como-povo-meu como-povo-teu como-cavalos-meus como-cavalos-teus');
INSERT INTO verses VALUES (9588, 12, 3, 8, 'E-disse qual este o-caminho E-disse o-caminho-de caminho deserto-de Edom');
INSERT INTO verses VALUES (9589, 12, 3, 9, 'E-andou rei Israel e-rei-de יְהוּדָה e-rei-de Edom o-caminho-de caminho sete-de dias águas foi águas para-o-acampamento e-para-o-gado que em-pés-deles');
INSERT INTO verses VALUES (9590, 12, 3, 10, 'E-disse rei Israel ah porque yhwh yhwh para-três-de os-reis os-estes a-dar eles por-mão-de Moabe');
INSERT INTO verses VALUES (9591, 12, 3, 11, 'E-disse Jeosafá não-há aqui profeta para-יהוה e-consultaremos a yhwh de-ele um um de-servos-de E-disse Israel E-disse aqui Eliseu águas Safá que derramou águas sobre mãos-de Elias');
INSERT INTO verses VALUES (9592, 12, 3, 12, 'E-disse Jeosafá há ele palavra-de yhwh a-ele a-ele rei Israel e-Jeosafá e-rei-de Edom');
INSERT INTO verses VALUES (9593, 12, 3, 13, 'E-disse Eliseu a rei Israel que- para-mim e-para-ti vai a profetas-de E-disse a-ele profetas-de mãe-tua E-disse para-ele yhwh Israel El porque chamou yhwh para-três-de os-reis os-estes a-dar eles por-mão-de Moabe');
INSERT INTO verses VALUES (9594, 12, 3, 14, 'E-disse Eliseu vive yhwh dos-exércitos que estou-em-pé que porque face-de face-de Jeosafá rei-de יְהוּדָה eu levanto se olharei a-ti e-se te-verei');
INSERT INTO verses VALUES (9595, 12, 3, 15, 'e-agora tomai a-mim músico e-será como-tocar o-músico e-foi sobre-ele mão-de yhwh');
INSERT INTO verses VALUES (9596, 12, 3, 16, 'E-disse assim disse yhwh fez o-vale este cisternas cisternas');
INSERT INTO verses VALUES (9597, 12, 3, 17, 'porque assim disse yhwh não espírito espírito e-não vereis chuva e-o-vale o-aquele se-encherá águas e-bebereis vós e-rebanhos-vossos e-animais-vossos');
INSERT INTO verses VALUES (9598, 12, 3, 18, 'e-leve esta em-olhos-de yhwh e colocou a Moabe em-mão-vossa');
INSERT INTO verses VALUES (9599, 12, 3, 19, 'e-golpeareis todo cidade fortaleza e-todo cidade bom e-todo árvore bom e-tudo e-todo fontes-de águas obstruireis e-todo a-porção a-boa danificareis com-as-pedras');
INSERT INTO verses VALUES (9600, 12, 3, 20, 'e-houve pela-manhã como-subir a oferta-cereais e-eis- águas vêm de-caminho-de Edom a-terra a-terra a as-águas');
INSERT INTO verses VALUES (9601, 12, 3, 21, 'e-todo Moabe ouviram porque subiram os-reis para-lutar de-toda e-eles-gritaram de-todo cingindo cinto e-para-cima e-eles-se-puseram-em-pé sobre a-fronteira');
INSERT INTO verses VALUES (9602, 12, 3, 22, 'e-eles-se-levantaram-cedo em-a-manhã e-o-sol ela-brilhou sobre as-águas e-eles-viram Moabe de-diante a as-águas vermelhas como-sangue');
INSERT INTO verses VALUES (9603, 12, 3, 23, 'e-disseram sangue este sendo-destruído eles-foram-destruídos os-reis e-eles-feriram homem a e-agora e-agora para-o-despojo Moabe');
INSERT INTO verses VALUES (9604, 12, 3, 24, 'e-eles-vieram a acampamento-de Israel e-eles-se-levantaram Israel e-eles-feriram a Moabe e-eles-fugiram de-face-deles nela e-ferir a Moabe');
INSERT INTO verses VALUES (9605, 12, 3, 25, 'e-as-cidades eles-destruirão e-todo porção boa eles-lançarão homem pedra-dele e-eles-a-encherão e-todo fonte-de águas eles-obstruirão e-todo árvore-de bom eles-farão-cair até ele-deixou pedras-dela em-a-parede Quir-Haresete e-eles-cercaram os-fundeiros e-eles-a-feriram');
INSERT INTO verses VALUES (9606, 12, 3, 26, 'E-viu rei Moabe porque nós dele E-tomou E-tomou a-ele sete-de centenas espada desembainhando espada para-abrir-caminho a rei Edom e-não eles-puderam');
INSERT INTO verses VALUES (9607, 12, 3, 27, 'E-tomou a filho-dele o-primogênito que reinará em-lugar-dele e-ele-o-ofereceu e-houve sobre a-muralha E-foi ira-de grande sobre Israel e-eles-partiram de-sobre-ele e-eles-retornaram para-a-terra');
INSERT INTO chapters VALUES (317, 12, 4, 44);
INSERT INTO verses VALUES (9608, 12, 4, 1, 'e-mulher uma de-mulheres-de filhos-de os-profetas ela-gritou dizendo Eliseu para-dizer servo-teu marido-meu morreu que soubeste ser temer foi temendo a yhwh e-o-credor veio a-ele a segundo filhos-meus para-ele para-servos');
INSERT INTO verses VALUES (9609, 12, 4, 2, 'E-disse a-ela אֱלִישָׁע que eu-farei- para-ti conta para-mim que- há- E-disse e-disse não-há para-serva-tua todo que porque se jarro-de azeite');
INSERT INTO verses VALUES (9610, 12, 4, 3, 'E-disse vai pede- para-ti vasos de o-fora de-com todo vasos vazios a tu-diminuas');
INSERT INTO verses VALUES (9611, 12, 4, 4, 'e-tu-entrarás e-tu-fecharás a-porta atrás-de-ti e-atrás-de- filhos-teus sobre sobre todo os-vasos estas e-o cheio tu fazes partir');
INSERT INTO verses VALUES (9612, 12, 4, 5, 'e-foi de-com ele e ela fechou a porta atrás-de ela e atrás-de filhos-de ela eles fazendo aproximar para-ela e ela');
INSERT INTO verses VALUES (9613, 12, 4, 6, 'e-houve como encher-de os recipientes e ela disse E-disse filho-de ela faze aproximar a-mim ainda recipiente E-disse a ela não mais recipiente e-se-posicionou o óleo');
INSERT INTO verses VALUES (9614, 12, 4, 7, 'e ela veio e ela contou a homem-de os-Elohim E-disse vai vende a o óleo e paga a e tu tu viverás em-o restante');
INSERT INTO verses VALUES (9615, 12, 4, 8, 'e-houve o-dia e-passou Eliseu a שׁוּנֵ֗ם e ali mulher grande e ela forçou e-houve para comer pão E-foi sempre-de passar-de ele ele se desviará para lá para comer pão');
INSERT INTO verses VALUES (9616, 12, 4, 9, 'E-disse a marido-dela eis-que- que soube porque homem ele santo ele passando sobre nós sempre');
INSERT INTO verses VALUES (9617, 12, 4, 10, 'faremos agora quarto-superior-de parede a-ele e poremos para-ele nome cama e mesa e cadeira e candelabro e será em vir-de ele a-nós ele se desviará ali');
INSERT INTO verses VALUES (9618, 12, 4, 11, 'e-houve o-dia E-veio para-lá e ele se desviou a a-câmara-alta e ele se deitou ali');
INSERT INTO verses VALUES (9619, 12, 4, 12, 'E-disse a גֵּחֲזִ֣י jovem-de ele chamou para-a שׁוּנַמִּית esta e ele chamou para-ela e-ela-ficou-em-pé diante-de-ele');
INSERT INTO verses VALUES (9620, 12, 4, 13, 'E-disse a-ele dize por favor eis eis tu tremeste a nós a todo o tremor esta para-ti para fazer para-ti há para-falar- para-ti a E-disse no-meio-de a eu o-exército e-disse em-meio-de povo-meu eu habitando');
INSERT INTO verses VALUES (9621, 12, 4, 14, 'E-disse e que para fazer para ela E-disse גֵּיחֲזִ֗י porém filho não há para-ela e homem-de ela velho');
INSERT INTO verses VALUES (9622, 12, 4, 15, 'E-disse chama para ela e ele chamou para-ela e-ela-ficou-em-pé na abertura');
INSERT INTO verses VALUES (9623, 12, 4, 16, 'E-disse para-o tempo o-este como tempo-de vivente abraçando filho e-disse filho E-disse homem os-Elohim a tu mentirás em serva-de ti');
INSERT INTO verses VALUES (9624, 12, 4, 17, 'e-concebeu a-mulher e-deu-à-luz filho para-o tempo o-este como tempo-de vivente que palavra para-ela אֱלִישָֽׁע');
INSERT INTO verses VALUES (9625, 12, 4, 18, 'e-cresceu o menino e-houve o-dia e-ele-saiu a pai-dele a os ceifadores');
INSERT INTO verses VALUES (9626, 12, 4, 19, 'E-disse a pai-dele cabeça-de mim cabeça-de mim E-disse a o jovem carrega ele a mãe-de ele');
INSERT INTO verses VALUES (9627, 12, 4, 20, 'e ele o carregou e ele o trouxe a mãe-dele e-habitou sobre em-joelhos-dela até o-meio-dia E-morreu');
INSERT INTO verses VALUES (9628, 12, 4, 21, 'e-ele-subiu e-el-a-deitou-o sobre de-a-cama homem o-Elohim e-ela-fechou atrás-dele e-ele-saiu');
INSERT INTO verses VALUES (9629, 12, 4, 22, 'e-ela-chamou-a a E-disse e-disse envia-a por-favor um um de os-jovens e-uma as-as-negras e-eu-corri até homem Elohim e-eu-voltarei');
INSERT INTO verses VALUES (9630, 12, 4, 23, 'E-disse por-que a-ele o-dia não novo a-ele o-dia e-disse paz');
INSERT INTO verses VALUES (9631, 12, 4, 24, 'e-ela-teceu a-jumenta E-disse a jovem-sua dirija e-vá a que para-mim para-ti porque se disse para-ti');
INSERT INTO verses VALUES (9632, 12, 4, 25, 'e-ela-partiu e-ela-chegou a homem o-Elohim a e-houve o-Carmelo E-foi para-ver homem-de E-disse a-ela em-frente eis a Giehazi jovem-de ele hein a-shunammit ha-laz');
INSERT INTO verses VALUES (9633, 12, 4, 26, 'atah rutz- por-favor liqra''atha ve-emar- para-ti hashalom para-ti hashalom le-ish''ekh E-disse para-o-nascer e-disse paz');
INSERT INTO verses VALUES (9634, 12, 4, 27, 'e-ela-vieram a homem הָֽאֱלֹהִים a o-monte e-ela-forte-se-tornou com-seus-pés e-ele-aproximou-se E-disse para-a-derrubá-la E-disse homem os-Elohim a-pausa-seja a-ela porque sua-alma amarga-seja declarou e-יהוה e-esconderam mais-que-a-mim e-não disse para-mim');
INSERT INTO verses VALUES (9635, 12, 4, 28, 'E-disse suplicaste filho de-junto-de Adonai porventura-não eu-disse não deitar-te-ás de-mim');
INSERT INTO verses VALUES (9636, 12, 4, 29, 'E-disse para-Gehazi cinto as-tua-cintura e-toma do-meu-apoio com-a-tua-mão e-anda porque encontra-se não não abençoa-o e-quando não homem não responde-a e-tu-colocarás de-meu-apoio sobre face-de o-jovem');
INSERT INTO verses VALUES (9637, 12, 4, 30, 'E-disse mãe o jovem vive yhwh e-vive alma-tua se te-deixarei E-levantou E-andou atrás-de-ela');
INSERT INTO verses VALUES (9638, 12, 4, 31, 'e-Gehazi passou em-frente-a-eles e-ele-colocou a o-depósito sobre face-de voz e-não-há voz e-não-há ouve-se e-ele-retornou dizendo não a-ele dizendo não levanta-se o-jovem');
INSERT INTO verses VALUES (9639, 12, 4, 32, 'E-veio Eliseu a-casa e-eis o-menino morreu deitado sobre em-a-sua-cama');
INSERT INTO verses VALUES (9640, 12, 4, 33, 'E-veio e-fechou a-porta através-de dois-deles e-ele-orou a yhwh');
INSERT INTO verses VALUES (9641, 12, 4, 34, 'e-ele-subiu e-ele-deitou sobre o-menino e-ele-colocou de-seu-boca sobre de-seu-boca e-de-seus-olhos sobre os-seus-olhos e-de-seus-mãos sobre e-ele-apressou sobre-ele e-ele-quentou de-a-carne o-menino');
INSERT INTO verses VALUES (9642, 12, 4, 35, 'e-voltou E-andou em-a-casa uma eis-aqui e-uma elas e-ele-subiu e-ele-teve-frio sobre-ele e-ele-tremeu o-menino até sete vezes e-ele-abriu o-menino a os-seus-olhos');
INSERT INTO verses VALUES (9643, 12, 4, 36, 'E-chamou a E-disse E-disse chamou a a-shunamita a-esta a-ele E-disse a-ela E-disse sai em-o-filho-teu');
INSERT INTO verses VALUES (9644, 12, 4, 37, 'e-ela-veio e-caiu sobre seus-pes e-se-prostrou terra e-ela-alçou-a a em-a-filha-sua e-saiu');
INSERT INTO verses VALUES (9645, 12, 4, 38, 'e-Elisha retornou o-Gilgal e-a-fome na-terra e-filhos-de os-profetas habitavam diante-dele E-disse para-a-jovem disse o-sir o-grande e-o-cozinhar sopa para-filhos-de os-profetas');
INSERT INTO verses VALUES (9646, 12, 4, 39, 'e-saiu um a o-campo para-colher manjedouras e-ele-achou vinha campo nós de-ele quebras campo enchei roupa-seu E-veio e-dividiu a panela o-cozido porque não sabiam');
INSERT INTO verses VALUES (9647, 12, 4, 40, 'e-vertiu para-homens para-comer e-houve como-eles-comiam de-o-nazido e-eles gritaram e-disseram morte no-sir homem o-Elohim e-não puderam para-comer');
INSERT INTO verses VALUES (9648, 12, 4, 41, 'E-disse e-tomem- farinha e-ele-jogou E-disse a-sira E-disse tzaq para-o-povo ser e-não mal palavra mau em-o-sir');
INSERT INTO verses VALUES (9649, 12, 4, 42, 'e-homem veio de-baal terceiro e-trouxe para-homem os-אלהים pão das-primeiras-colheitas vinte- pão semente-de-trigo e-carne E-disse E-disse dê ao-povo e-eles-comam.');
INSERT INTO verses VALUES (9650, 12, 4, 43, 'E-disse o-serviço-seu quanto darei este diante-de cem homem E-disse dê ao-povo e-eles-comam que assim disse yhwh comer e-tenha-sobra.');
INSERT INTO verses VALUES (9651, 12, 4, 44, 'E-colocou diante-deles e-comeram e-restaram conforme-palavra-de yhwh');
INSERT INTO chapters VALUES (318, 12, 5, 27);
INSERT INTO verses VALUES (9652, 12, 5, 1, 'e-naaman príncipe-de tzva ser ארם foi homem grande diante-de adonai-o e-nasha face porque nele dou- ser salvação para-Aram e-o-homem foi heroi- valor métzora');
INSERT INTO verses VALUES (9653, 12, 5, 2, 'e-arameu saíram gédudim e-quiseram-capturar de-terra-de Israel jovem qetaná e-tornou-se diante-de mulher-de naamán');
INSERT INTO verses VALUES (9654, 12, 5, 3, 'E-disse a giboráta achalei Adonai diante-de o-profeta que בְּשֹׁמְרֹנָה então ele ele de-a-sua-lepra');
INSERT INTO verses VALUES (9655, 12, 5, 4, 'E-veio e-revelou para-o-seu-mestre dizendo assim-e-assim e-assim-e-assim falou-a-moça a-moça que de-terra-de Israel');
INSERT INTO verses VALUES (9656, 12, 5, 5, 'E-disse rei-de aram vai-para veio e-eu-enviarei livro a E-tomou Israel E-andou E-tomou em-a-sua-mão dez ouro prata e-sesset milhares ouro e-esser halifot begadim');
INSERT INTO verses VALUES (9657, 12, 5, 6, 'e-trouxe ha-sefer a rei dizendo e-agora e-agora como-vir o-sefer o-este eis eis shalachti a-ti a naaman servo-meu va-asaphto mitzraato');
INSERT INTO verses VALUES (9658, 12, 5, 7, 'e-houve como-chamar rei-de Israel a o-sefer E-disse em-seus-vestes E-disse o-Elohim אנני para-matar e-para-viver porque este enviou a-mim que homem de-sua-lepra porque ele conhecem-se por-favor e-vedei porque se-complai ele para-mim');
INSERT INTO verses VALUES (9659, 12, 5, 8, 'e-houve quando-ouvir Eliseu homem-de os-Elohim porque dividiu rei-de Israel a dizendo e-enviou a o-rei dizendo por-que dividiste que vem- por-favor a-mim e-saberei porque há profeta em-Israel');
INSERT INTO verses VALUES (9660, 12, 5, 9, 'E-veio Naamã e-no-seu-cavalo e-estabeleceu pe-tach- a-casa a-Elisama');
INSERT INTO verses VALUES (9661, 12, 5, 10, 'e-enviou a-ele Eliseu anjo dizendo andando e-lavaste sete- vezes no-Jordão e-sentou-se a-ti a-ti e-ficaste-puro');
INSERT INTO verses VALUES (9662, 12, 5, 11, 'e-ira-se Naamã E-andou E-disse eis disse a-mim sairá sair e-estandou e-chamou em-o-nome-de yhwh de-seus-Elohimes e-sacrou sua-mão a o-lugar e-recolheu o-leproso');
INSERT INTO verses VALUES (9663, 12, 5, 12, 'não-é bom e-espalhou rios de-a-damas de-todo de-a-água de-toda não eu-lavarei neles e-santificarei-me e-virou-se E-andou com-ira');
INSERT INTO verses VALUES (9664, 12, 5, 13, 'e-aproximaram-se os-servos-dele e-falaram a-ele e-disseram pai-meu palavra grande o-profeta palavra a-ti não fazes e-af porque disse a-ti r-hatz u-tehar');
INSERT INTO verses VALUES (9665, 12, 5, 14, 'e-ele-desce e-banhou-se be-yarden sete vezes ke-dvar homem o-Elohim e-estabeleceu-se be-saro ke-basar jovem pequeno va-yitahar');
INSERT INTO verses VALUES (9666, 12, 5, 15, 'va-yashav a homem ele ele e-todo machanehu E-veio E-disse diante-de-ele E-disse que por-favor soube porque que Elohim e-agora a-terra porque se em-Israel e-agora toma agora bendição de-a servo-teu');
INSERT INTO verses VALUES (9667, 12, 5, 16, 'E-disse vive yhwh que estou-estacionado diante-dele se eu-tomarei e-ele-precipitar-se nele para-tomar e-ele-recusou-se');
INSERT INTO verses VALUES (9668, 12, 5, 17, 'E-disse Naamã e-não será-dado- por-favor para-teu-servo massa- terra que terra-a porque não faz-o ainda servo-teu holocausto que para-Elohim outros porque se para-יהוה');
INSERT INTO verses VALUES (9669, 12, 5, 18, 'para-a-palavra esta perdoa-ele yhwh para-servidor-teu em-vir Adonai casa-de rumo-a para-adorar para-lá e-ele apoiado sobre mão-meu e-me-curvo-eu casa rumo-o em-minha-adoração casa rumo-o yhwh yhwh para-servir-teu em-a-palavra a-esta');
INSERT INTO verses VALUES (9670, 12, 5, 19, 'E-disse a-ele vai para-paz E-andou de-com-ele como-um terra');
INSERT INTO verses VALUES (9671, 12, 5, 20, 'E-disse גֵּיחֲזִ֗י jovem Eliseu homem-de eis eis escuridão Adonai a Naamã o-arameu esta de-tomar מִיָּד֖וֹ a que trouxe vive yhwh porque se corri depois-dele e-tomaria de-com-ele qualquer-coisa');
INSERT INTO verses VALUES (9672, 12, 5, 21, 'e-perseguiu Gichazi depois-de Naamã e-ele-viu Naaman correu depois-dele e-caiu de-cima-de a-carroça para-o-encontro-dele E-disse h-shalom:');
INSERT INTO verses VALUES (9673, 12, 5, 22, 'E-disse shalom Adonai enviou-me dizendo dizendo eis zeh vieram ela-i dois ne-arim me-ha-mar Efraim de-filhos-de ha-nnvi-im dá- a-eles para-eles k-khar- prata u-sh-tei ch-lifot roupas-');
INSERT INTO verses VALUES (9674, 12, 5, 23, 'E-disse Naaman o-háuèl toma ciccarayim e-ele-rompeu- nele e-ele-apertou- ciccarayim prata em-dois har-tim u-shtey chal-pot E-colocou E-deu a segundo os-jovens-seus va-yis-av-u diante-de-ele');
INSERT INTO verses VALUES (9675, 12, 5, 24, 'E-veio a E-tomou E-tomou mi-yadam e-ele-contou ba-bayit e-enviou a os-homens veyelechu');
INSERT INTO verses VALUES (9676, 12, 5, 25, 've-hu- veio e-ficou-em-pé E-disse a-ele E-disse a-ele Eliseu ge-chazi E-disse não andou servo-teu onde e-onde');
INSERT INTO verses VALUES (9677, 12, 5, 26, 'E-disse a-ele não andar andou como-que de-cima-de homem de-sobre mer-khav-to li-qra-techa a-ora tomar a a-prata e-tomar roupas e-azeites e-vinhedos e-rebanhos e-gado e-servos e-escravas');
INSERT INTO verses VALUES (9678, 12, 5, 27, 'e-lepra Naaman se-aderirá a-você e-no-teu-semente para-sempre e-ele-saiu de-ante-o-lhe lepree como-a-neve');
INSERT INTO chapters VALUES (319, 12, 6, 33);
INSERT INTO verses VALUES (9679, 12, 6, 1, 'e-disseram filhos-de os-profetas a אֱלִישָׁ֑ע eis-a por-favor o-lugar que nós moradores nós diante-de-ti aperto de-nós');
INSERT INTO verses VALUES (9680, 12, 6, 2, 'vamos-ir agora até o-Jordão e-nos-tomaremos de-lá homem cortiça uma lugar para-nos nome E-disse para-habitar nome E-disse ide-vós');
INSERT INTO verses VALUES (9681, 12, 6, 3, 'E-disse o-primeiro vai por-favor e-vaia a E-disse E-disse eu irei.');
INSERT INTO verses VALUES (9682, 12, 6, 4, 'E-andou com-eles e-vieram o-jordânessa e-ele-decretou os-árvores:');
INSERT INTO verses VALUES (9683, 12, 6, 5, 'e-houve o-primeiro derrubando a-corda e-a cair caindo a E-disse e clamou E-disse ahh Adonai e-ele שָׁאוּל');
INSERT INTO verses VALUES (9684, 12, 6, 6, 'E-disse homem-de Elohim onde caiu e-o-viu a o-lugar e-espantou-se- madeira e-lançou ali e-ele-espalhou o-ferro-verso');
INSERT INTO verses VALUES (9685, 12, 6, 7, 'E-disse a-alta para-ti e-enviou sua-mão e-ele-o-tomou-verso');
INSERT INTO verses VALUES (9686, 12, 6, 8, 'e-rei-de Arã ser foi-luta em-Israel e-ele-conselhou-se a dizendo dizendo a lugar de-Peloní Almôni meus-acampamentos-verso');
INSERT INTO verses VALUES (9687, 12, 6, 9, 'e-enviou homem os-Elohim a rei dizendo dizendo h-sh-m-r m-av-v-r o-lugar esta porque nome a-r-am n-ch-t-t-im');
INSERT INTO verses VALUES (9688, 12, 6, 10, 'e-enviou rei Israel a o-lugar que palavras-de para-ele homem-de o-Elohim w-n-sh-m-r não uma uma e-não sh-t-y-im');
INSERT INTO verses VALUES (9689, 12, 6, 11, 'v-y-s-s-er coração rei-de Arã sobre E-chamou esta E-disse a seus-servos E-disse a-eles quem conteis a-mim quem m-sh-l-n-u a rei Israel');
INSERT INTO verses VALUES (9690, 12, 6, 12, 'E-disse um de-seus-servos l-o Adonai o-rei porque e-l-i-sh-a o profeta que em-Israel dirá como-rei Israel a as-palavras que falarias em-câmara-de de-teu-dormir');
INSERT INTO verses VALUES (9691, 12, 6, 13, 'E-disse ide e-vi-deis assim ele e-e-soltarei e-o-tomarei e-lhe-foi-dito dizendo eis eis em-Dotã-');
INSERT INTO verses VALUES (9692, 12, 6, 14, 'e-ele-mandou- para-aí cavalos e-carroças e-exército pesado e-vieram noite e-eles-cercaram sobre a-cidade');
INSERT INTO verses VALUES (9693, 12, 6, 15, 'e-ele-levantou-se servo homem Elohim לָקֻוֶם e-ele-saiu e-eis חַיִל סֹובֶב a a-cidade E-disse וָרָכֶב a-ele נַעֲרוֹ para-ele אֲהָהּ Adonai como נַעֲשׂוֺהַ');
INSERT INTO verses VALUES (9694, 12, 6, 16, 'E-disse a que porque רַבִּים que אִתָּנוּ de-o-que a-eles');
INSERT INTO verses VALUES (9695, 12, 6, 17, 'e-ele-orou אֱלִישָׁע E-disse yhwh abriu- por-favor a seus-olhos yhwh e-ele-abriu yhwh a os-olhos-de o jovem E-viu e-eis o-monte enchei cavaleiros e-carros fogo em-torno-de אֱלִישָֽׁע');
INSERT INTO verses VALUES (9696, 12, 6, 18, 'e-eles-desceram a-ele e-ele-orou Eliseu a yhwh E-disse o-golpe- agora a o-povo- este em-os-sinuosos e-ele-golpeou-vos em-os-sinuosos conforme-palavra-de אֱלִישָֽׁע');
INSERT INTO verses VALUES (9697, 12, 6, 19, 'E-disse a-para-eles Eliseu não este o-caminho e-não este-aqui a-cidade ide após-mim e-levará vos a o homem que vocês-pedirão E-andou eles Safarom:');
INSERT INTO verses VALUES (9698, 12, 6, 20, 'e-houve quando-eles-entrarem Samaria E-disse Eliseu yhwh abrir a olhos- estes yhwh e-ele-abriu yhwh a no-meio-de e-eles-viram e-eis em-meio-de Samaria');
INSERT INTO verses VALUES (9699, 12, 6, 21, 'E-disse rei-de Israel a Eliseu כִּרְאֹת֖וֹ eles a-machucada machucada pai-meu');
INSERT INTO verses VALUES (9700, 12, 6, 22, 'E-disse não -machuca o-que levaste com-a-sua-espada e-com-a-sua-flecha tu machucando colocando pão e-aguá em-frente-a-eles e-eles-comerão e-eles-beberão e-eles-irão a adonaies-deles');
INSERT INTO verses VALUES (9701, 12, 6, 23, 'e-ele-cavou a-eles cavou grande e-eles-comeram e-eles-beberam e-ele-enviou-os e-foram a seus-mestres e-não acrescentaram-se ainda de-tropas Arã para-vir em-terra-de Israel');
INSERT INTO verses VALUES (9702, 12, 6, 24, 'e-houve depois-de assim e-ele-reunir-ia filho-de haddad rei-de Arã a todo de-o-lager-dele e-ele-subir-ia e-ele-apertar-ia sobre Samaria');
INSERT INTO verses VALUES (9703, 12, 6, 25, 'e-houve fome grande em-Samaria e-eis feridos sobre-ela até estar cume-de jumento em-oitenta prata e-quarto o-cav em-o-cinco- prata:');
INSERT INTO verses VALUES (9704, 12, 6, 26, 'e-houve rei Israel transitorio- sobre a-muralha e-mulher a-ele dizendo dizendo salva-o Adonai o rei');
INSERT INTO verses VALUES (9705, 12, 6, 27, 'E-disse a yhwh yhwh de-onde eu-salvarei-te acaso-de o-aranha ou de a-cavidade:');
INSERT INTO verses VALUES (9706, 12, 6, 28, 'e-ele-disse para-ela o-rei E-disse para-ti e-disse a-mulher a-esta disse a-mim dá-a o-dia o-seu-filho e-nós-o-comeremos o-dia e-a filhos-de nós-comeremos amanhã');
INSERT INTO verses VALUES (9707, 12, 6, 29, 'e-nós-o-cozemos a filhos-de e-nós-o-comemos e-eu-disse no-dia no-dia o-outro dá-a a o-seu-filho e-nos-comer-no-lo e-escondeu a o-filho-seu.');
INSERT INTO verses VALUES (9708, 12, 6, 30, 'e-houve quando-ouviram o-rei a palavras de a-mulher e-ele-partiu a as-roupas-seu e-ele E-viu sobre a-muralha E-viu o-povo e-eis o-saco sobre a-carne-dele de-a-casa-verso');
INSERT INTO verses VALUES (9709, 12, 6, 31, 'E-disse assim fara- para-mim Elohim e-assim yosif-acento-águia se yaamod-acento-grave cabeça o-dia filho-de shapat-acento-agudo sobre-ele o-dia');
INSERT INTO verses VALUES (9710, 12, 6, 32, 'veelishaacento-águia habitou em-casa-de-ele e-os anciãos yoshvim-acento-grave com-ele e-enviou homem milpanav-acento-agudo betereim-acento-águia yavo-acento-grave ha-malac-h-acento-agudo a-ele e-ele disse disse os-anciãos haraitem porque enviou filho-de hameratzeha o-este lehahsir a roshi re''u kevoa hammaleakh sigru ele ulechatstem ele voz halo som-que pés-de adonai-aus atrás-dele');
INSERT INTO verses VALUES (9711, 12, 6, 33, 'ainda-ele falando-é com-eles e-eis o-mensagem-elohim descendo-é a-ele E-disse eis-a esta a-malícia-a yhwh yhwh que esperarei-eu para-יהוה ainda');
INSERT INTO chapters VALUES (320, 12, 7, 20);
INSERT INTO verses VALUES (9712, 12, 7, 1, 'E-disse Eliseu ouvi palavra-de yhwh assim disse yhwh em-tempo amanhã sa-a flor-farinha com-saquele e-saateim se-orim com-saquele em-porta-de Samaria');
INSERT INTO verses VALUES (9713, 12, 7, 2, 'e-respondeu ha-shalish que para-o-rei nisha-an sobre mão-sua a eis yhwh E-disse eis yhwh fez arubot em-os-céus E-disse a-coisa esta E-disse eis-aqui não em-tua-olho e-de-lá não você-comerá');
INSERT INTO verses VALUES (9714, 12, 7, 3, 'e-quatro homens foram de-leprosos entrada-de a-porta e-disseram homem a companheiro-seu o-que nós estamos-sentados aqui até morremos');
INSERT INTO verses VALUES (9715, 12, 7, 4, 'se dissemos-nós vamos-vir a-cidade e-a-fome na-cidade e-matamos nome e-se moramos e-agora e-matamos e-agora vão-vocês e-cairemos a acampamento-de Arã se viver-nos-ao vivamos e-se nos-matarão e-mossemortos');
INSERT INTO verses VALUES (9716, 12, 7, 5, 'e-ele-levantaram-se na-noite para-vir a acampamento-de Arã e-vieram até extremidade-de acampamento-de Arã e-eis não há nome homem');
INSERT INTO verses VALUES (9717, 12, 7, 6, 'וַאדֹנָ֞י הִשְׁמִ֣יעַ ׀ a acampamento-de אֲרָ֗ם voz רֶ֙כֶב֙ voz ס֔וּס voz força grande e-eles-disseram homem a eis eis שָֽׂכַר־ em-nós rei Israel a reis-de הַחִתִּ֛ים e-a מַלְכֵ֥י Egito לָב֥וֹא sobre-nós');
INSERT INTO verses VALUES (9718, 12, 7, 7, 'e-ele-levantaram-se e-eles-se-esconderam na-noite e-ele-deixou a as-sacas-deles e-a os-cavalos-deles e-a os-animais-da-montaria-deles o-acampamento conforme- ela e-eles-fugiram a alma-deles');
INSERT INTO verses VALUES (9719, 12, 7, 8, 'e-ele-chegou os-leprosos ha-eleh até fim o-acampamento e-vieram um tenda-de um e-eles-comeram e-eles-beberam e-tomaram de-lá prata וזהב e-roupas e-foram e-os-ocultaram e voltaram e-vieram a tenda outro e-tomaram de-lá e-foram e-os-ocultaram-verso-final');
INSERT INTO verses VALUES (9720, 12, 7, 9, 'e-disseram homem a seu companheiro não assim nós o-dia o-dia este ele bo-a ele e-nós ma-chshim-im ve-hhik-ku-nu até luz e-agora u-metz-ta-anu av-on e-agora ide ve-na-vo-a-ha ve-nag-id-a-ha casa o rei');
INSERT INTO verses VALUES (9721, 12, 7, 10, 'e-vieram va-yi-qre-u a sho-eer ha-ir a-eles dizendo dizendo vimos-nos a acampamento-de Arã e-eis não-há homem que e-voz homem porque se o-cavalo amarrado e-o-jumento amarrado e-tendas conforme- eles');
INSERT INTO verses VALUES (9722, 12, 7, 11, 'E-chamou as-portas e-disseram casa o-rei dentro');
INSERT INTO verses VALUES (9723, 12, 7, 12, 'E-levantou o-rei noite E-disse a seus-servos a-vós agora a-vós a que fizeram para-nós Arã sabem porque famintos nós e-eles-saíram dizendo o-acampamento para-serem-pegos dizendo vida yetseu de a-cidade e-eles-seriam-agarrados viventes e-a a-cidade vamos');
INSERT INTO verses VALUES (9724, 12, 7, 13, 'e-ele-respondeu um de-seus-servos E-disse e-eles-tomarão- por-favor cinco de os-cavalos os-nos-restantes que eles-se-deram-como-restos em-a eis-eles conforme-toda Israel que eles-se-deram-como-restos nela eis-eles conforme-toda multidão Israel que terminaram e-foi-enviada e-se-verá');
INSERT INTO verses VALUES (9725, 12, 7, 14, 'e-eles-tomaram segundo carros cavaleiros e-enviou o-rei atrás-de acampa-se- dizendo para-dizer para-voces-andem e-vede;');
INSERT INTO verses VALUES (9726, 12, 7, 15, 'e-andaram depois-deles até o-Jordão e-eis todo o-caminho cheia- em-vestes e-em-vasos que lançaram Arã e-voltaram-se os-anjos e-contaram para-o rei');
INSERT INTO verses VALUES (9727, 12, 7, 16, 'e-saiu o-povo e-eles-escarneceram a acampamento-de Arã e-houve  Seah- farinha-de-trigo -em-sheqel e-sea- de-cevada -em-sheqel yhwh yhwh');
INSERT INTO verses VALUES (9728, 12, 7, 17, 'e-o-rei- colocou a o-tersário que nicho-an sobre mão-dele sobre o-portão e-vir-mes-su-hu o-povo be-sha-ar E-morreu como-que palavra homem os-Elohim a-ele palavra be-red-et o-rei a-ele');
INSERT INTO verses VALUES (9729, 12, 7, 18, 'e-houve ke-daber homem os-Elohim a dizendo dizendo sa-atayim so-er-im be-she-qel u-se-a- será be-she-qel yihye como tempo-de amanhã em-a-porta Samaria');
INSERT INTO verses VALUES (9730, 12, 7, 19, 'e-ele-respondeu o-terceiro a homem os-elohim E-disse yhwh yhwh fez as-cela no-ceu se-será como-dizer E-disse E-disse eis-você viu em-tua-olho não não você-comerá');
INSERT INTO verses VALUES (9731, 12, 7, 20, 'e-foi a-ele assim ele ele o-povo em-a-porta E-morreu');
INSERT INTO chapters VALUES (321, 12, 8, 29);
INSERT INTO verses VALUES (9732, 12, 8, 1, 'e-אֱלִישָׁע palavra a a-mulher que dizendo a o-de-a-sua-filha dizendo levanta-te e-anda e-casa-de-a-tua e-estabelece-te ba-asher serás-estabelecida yhwh chamou yhwh para-a-fome e-também veio a a-terra sete dois');
INSERT INTO verses VALUES (9733, 12, 8, 2, 'e-ele-se-levantou a-mulher e-fez conforme-a-palavra homem o-Elohim e-foi ela e-o-casa-de-ela e-ele-morou em-terra-de Filisteus sete dois');
INSERT INTO verses VALUES (9734, 12, 8, 3, 'e-houve de-a-extremidade-de sete dois e-ela-voltou-se a-mulher da-terra filisteus e-ele-saiu para-gritar a o-rei a na-casa-de-ela e-a o-campo-de-ela');
INSERT INTO verses VALUES (9735, 12, 8, 4, 'e-o-rei fala- a Gechazi jovem dizendo Elohim dizendo Safra- agora a-mim a todo as-grandes-coisas que fez אֱלִישָֽׁע');
INSERT INTO verses VALUES (9736, 12, 8, 5, 'e-houve ele conta- para-o-rei a que reviveu a o-morto- e-eis a mulher que reviveu a filho-de ela E-disse a o-rei sobre esta e-sobre seu-campo E-disse Gecazi Adonai o-rei esta a-mulher e-este filha-dele que viveu אֱלִישָֽׁע');
INSERT INTO verses VALUES (9737, 12, 8, 6, 'e-pediu o-rei para-a-mulher e-contou- a-ele e-ele-deu para-ela um dizendo um dizendo o-retornar a todo que a-ela e-את todo as-colheitas o-campo de-o-dia abandonou-a a a-terra e-até agora');
INSERT INTO verses VALUES (9738, 12, 8, 7, 'E-veio אֱלִישָׁע de-Damasco e-filho-de haddad rei-de Arã dizendo e-lhe-foi-dito a-ele dizendo veio homem Elohim até até-aqui');
INSERT INTO verses VALUES (9739, 12, 8, 8, 'E-disse o-rei a visão-de-Elohim toma em-a-mão-tua oferenda e-va-lekh para-encontro-de homem o-Elohim ve-darashtah a dizendo me-e-to dizendo ha-akh-yeh de-doença-minha este');
INSERT INTO verses VALUES (9740, 12, 8, 9, 'E-andou khaza-el li-kra-to E-tomou min-khah be-yado e-todo bom de-Damasco Massá quarenta גּוֹמָל E-veio e-ficou-em-pé E-disse E-disse em-o-teu-filho filho-de hadad rei-de dizendo enviaram-me a-ti dizendo ha-akh-yeh de-doença-minha este');
INSERT INTO verses VALUES (9741, 12, 8, 10, 'E-disse a-ele Eliseu vai dize /DD/ /DD/ e-me-mostrou yhwh yhwh morrer morre/;');
INSERT INTO verses VALUES (9742, 12, 8, 11, 'e-ele-montou a sua-face e-colocou até em-vergonha e-ele-chorou homem Elohim');
INSERT INTO verses VALUES (9743, 12, 8, 12, 'E-disse Chazeael por-que Adonai chorando E-disse porque eu soube a que fazes para-os-filhos-de Israel mau de seus dentes lançarás em-o-fogo e nos seus jovens com-a-espada massacres e-os-seus-criadinhos tu-reteis e-as-seus-ensinadores tu-baqeis');
INSERT INTO verses VALUES (9744, 12, 8, 13, 'E-disse veja-a-Elohim que que teu-servo o-cão que fazê-lo-á a-palavra o-grande este E-disse Eliseu mostrou-me yhwh a-ti rei sobre aram');
INSERT INTO verses VALUES (9745, 12, 8, 14, 'e-foi de-junto-de Eliseu E-veio a seu-senhor E-disse a-ele que a-ti a-ti E-disse disse disse a-mim viva viva:');
INSERT INTO verses VALUES (9746, 12, 8, 15, 'e-houve da-o E-tomou o-grande e-batizou em água vayifros sobre sua-face E-morreu e-reinou veja-ael em-lugar-dele');
INSERT INTO verses VALUES (9747, 12, 8, 16, 'e-em-ano-de cinco para-yoram filho-de Acabe rei Israel e-Jeosafá rei Judá rei jehoram filho-de Josafá rei Judá');
INSERT INTO verses VALUES (9748, 12, 8, 17, 'filho-de trinta e-shethayim ser foi em-malko e-shemonah rei em-Jerusalém');
INSERT INTO verses VALUES (9749, 12, 8, 18, 'E-andou no caminho reis-de Israel como-que fizeram casa Acabe porque que Acabe hָayְthָa- a-ele para-mulher E-fez o-mal yhwh yhwh');
INSERT INTO verses VALUES (9750, 12, 8, 19, 'e-não yhwh yhwh para-destruir a Judá para-que Davi seu-escravo como-que a-ele para-ele para-dar a-ele Nir  levanay  todo os dias');
INSERT INTO verses VALUES (9751, 12, 8, 20, 'em seus dias rebelou-se Edom debaixo-de mão-de Judá e-manteve-no-trono sobre-eles rei');
INSERT INTO verses VALUES (9752, 12, 8, 21, 'e-ele-passou Yoram pequena e-todo o-carro com-ele e-foi ele levantou-se noite e-feriu a-ele Edom o-circundante a-ele e-את príncipes-de o-carro e-fugiu o-povo לְאֹהָלָֽיו׃');
INSERT INTO verses VALUES (9753, 12, 8, 22, 'e-pecou Edom debaixo-de mão-de até o-dia o-dia esta então se estenda para-Bet-Lahem em-o tempo a-ela');
INSERT INTO verses VALUES (9754, 12, 8, 23, 'e-resto-de palavras-de Joram e-todo que fez não eles escritos sobre livro-de palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9755, 12, 8, 24, 'e-deitou-se Joram com seus-pais e-foi-enterrado com pais-dele na-cidade Davi e-reinou Acazias filho-dele em-lugar-dele');
INSERT INTO verses VALUES (9756, 12, 8, 25, 'no-ano-de duas- dez ano a-Joram filho-de Acabe rei Israel rei Acazias filho-de יְהוֹרָ֖ם rei Judá');
INSERT INTO verses VALUES (9757, 12, 8, 26, 'filho-de vinte וּשְׁתַּ֤יִם ano אֲחַזְיָ֣הוּ em-seu-reinado uma uma rei em-Jerusalém sua-mãe sua-mãe Ataliahu filha-de Amri rei Israel');
INSERT INTO verses VALUES (9758, 12, 8, 27, 'E-andou בְּדֶ֙רֶךְ֙ casa Acabe E-fez o-mal em-olhos-de yhwh como-casa-de Acabe que noivo-de casa-de ele ela');
INSERT INTO verses VALUES (9759, 12, 8, 28, 'E-andou a Joram filho-de Acabe para-a-guerra com Haza-el rei-de Arã beratomot  Galaad e-eles-feriram aramitas a jorama:');
INSERT INTO verses VALUES (9760, 12, 8, 29, 'va-yashav JORÃO o-rei para se curar em JIZREEL de o que mata que JACOVO ARÁMIOS em ARAMEIA na batalha a veja EL rei Arã Va''ăchazyāhū filho-de Yehōrām para-ver Judá Yarad Lir''ōt a ele filho-de Akhāv Biyizrē''el porque ele ela');
INSERT INTO chapters VALUES (322, 12, 9, 37);
INSERT INTO verses VALUES (9761, 12, 9, 1, 'veelishaacento-águia o-profeta chamou para-um de-filhos-de ha-nnvi-im E-disse a-ele cinto as-tua-cintura e-toma vaso o-óleo este em tua mão e-vai alturas gil-ad');
INSERT INTO verses VALUES (9762, 12, 9, 2, 'e-virás para-lá e-vejas- nome Yehu filho-de Jehosafat filho-de estaria e-vindo-a e-o-levantará ele seus-irmãos e-o-trarás a-ele quarto no-quarto:');
INSERT INTO verses VALUES (9763, 12, 9, 3, 'e tomaste vaso-de- o-óleo ויצקת sobre cabeça-sua yhwh assim disse yhwh unção-teu para-rei a Israel e-o-abrirás a-porta e-nos-tareis e-não t-cha-che-he');
INSERT INTO verses VALUES (9764, 12, 9, 4, 'E-andou o-jovem o-menino o-profeta ra-mot gil-ad');
INSERT INTO verses VALUES (9765, 12, 9, 5, 'E-veio e-eis príncipes-de הַחֲיִל֙ yoshvim E-disse palavra para-mim a-ti ha-shar E-disse ye-hu-a a quem E-disse E-disse e-le-cha ha-shar');
INSERT INTO verses VALUES (9766, 12, 9, 6, 'E-levantou E-veio a-casa e-ele-esguichou o-a-sínden a E-disse a-ele para-ele yhwh disse yhwh Elohim-de Israel m-schat-ti-chakha yhwh a povo yhwh a Israel');
INSERT INTO verses VALUES (9767, 12, 9, 7, 'vehikkita a casa Acabe adonaykha veniqmati dei meus-servos hanevim u dei todo yhwh yhwh de-mão-de iizabel:');
INSERT INTO verses VALUES (9768, 12, 9, 8, 'וְאָבַ֖ד todo casa Acabe e-cortarei לְאַחְאָב֙ cavas na-parede e-prenderei e-abandonei em-Israel');
INSERT INTO verses VALUES (9769, 12, 9, 9, 'e-n-d-e-rei a casa Acabe כְּבֵית Jeroboão filho-de Nebat e-com-a-casa Besa filho-de Ahias');
INSERT INTO verses VALUES (9770, 12, 9, 10, 'e-a Izabel yo''chlu as cadelas em parte Jezreel e-não-há sepultar e abriu a-porta e-o');
INSERT INTO verses VALUES (9771, 12, 9, 11, 'e-Jeu sair a servos-de E-disse a-ele a-ele se-salve por-que veio o-madman E-disse a-ti E-disse a-eles vós voces-conheceram a o homem e-a seu-grito');
INSERT INTO verses VALUES (9772, 12, 9, 12, 'e-disseram mentira conta por-favor E-disse E-disse assim-e-assim disse disse dizendo dizendo disse yhwh yhwh te-ungiu para-rei a Israel');
INSERT INTO verses VALUES (9773, 12, 9, 13, 'e-elese-apressaram e-eles-levaram homem em-seu-vestimenta e-os-colocaram abaixo-dele a gêrem das-escadas e-eles-tocaram em-o chifre e-disseram rei Jeu');
INSERT INTO verses VALUES (9774, 12, 9, 14, 'e se comprimiu Jeová filho-de Jeosafá filho-de estendi-me ser Jorão e Jorão foi ele beratomot de-diante-de ele e-todo Israel de-face-de rei-de aram');
INSERT INTO verses VALUES (9775, 12, 9, 15, 'va-yashav João o-rei para ser curado em Jizreel de os que matam que ele os bata aramitas na guerra dele a Chazeel E-disse Arã E-disse Jehu se há as vossas almas a sairá salvador de a-cidade para-andar em Jezreel:');
INSERT INTO verses VALUES (9776, 12, 9, 16, 've-yarakhav Jeu E-andou Zeelah que Yoram deitado para-lá e-Achaziah rei Judá desceu para-ver a jorama:');
INSERT INTO verses VALUES (9777, 12, 9, 17, 'e-o-espia ficou-em-pé sobre do-monte E-viu E-viu a multidão-de E-disse em-o-seu-vir E-disse multidão-de E-disse viu E-disse Jehoram pe-go cavaleiro para-encontro-deles E-disse h-shalom:');
INSERT INTO verses VALUES (9778, 12, 9, 18, 'E-andou רֹכֵ֨ב o-cavalo para-o-sua-frente E-disse assim disse o-rei E-disse E-disse Jeu que a-você e-para-a-paz סֹ֣ב a dizendo e-contou o-espião dizendo veio o-malac até eles e-não retornou');
INSERT INTO verses VALUES (9779, 12, 9, 19, 'e-enviou monta cavalo segundo E-veio a-eles E-disse assim disse o-rei E-disse E-disse Jeu que a-você e-para-a-paz volta a depois-de-mim');
INSERT INTO verses VALUES (9780, 12, 9, 20, 'e-contou o-que-vigia dizendo veio até a-eles e-não retornou e-o-modo como-modo que filho-de נִמְשִׁ֔י porque ele-vigiará');
INSERT INTO verses VALUES (9781, 12, 9, 21, 'E-disse Jeorão אֱסֹר-(manter como está, não há tradução direta) e-ajuntou-se seu-carro e-saiu Jehoão rei-de Israel e-Acaziah-(nome próprio) rei-de Judá homem em-seu-carro e-saíram ao-encontro-de Jeú e-eles-o-acharam em-parte נָב֥וֹת הַיִּזְרְעֵאלִֽי׃');
INSERT INTO verses VALUES (9782, 12, 9, 22, 'e-houve כּ-רֵא-וֹת Jeorão a E-disse E-disse pergunta-paz E-disse E-disse que a-paz até zenu-nêi iz-evel אִמְּךָ֛ u-kesh-ap-ha os-muitos-verso-final');
INSERT INTO verses VALUES (9783, 12, 9, 23, 'va-yah-poch Jeorão mãos-dele va-yan-os E-disse a Acazias mirm-ma achaz-yah');
INSERT INTO verses VALUES (9784, 12, 9, 24, 've-ye-hu enchei sua-mão baq-qesheth e-ele-feriu a entre entre zro-a-o e-ele-saiu o-meio de-o-seu-coracao e-ele-abaixou-se em-a-sua-cavalaria');
INSERT INTO verses VALUES (9785, 12, 9, 25, 'E-disse a com-flecha o-queiro e-ele-jogou-o em-a-partilha-de os-campos נָב֣וֹת o-yizraelita porque macho eu e-eu-vim a cavaleiros par de ferramentas atrás-de Acaab seu-pai e-יהוה levou sobre-ele a [הַזֶּֽה] a-esta');
INSERT INTO verses VALUES (9786, 12, 9, 26, 'se não a sangues-de Naboote e-a de-ossos seus-filhos eu vi a-ti oráculo-de yhwh e-pagarei e-agora em-parte a-esta oráculo-de yhwh yhwh Saae o-espante-o em-parte conforme-palavra-de yhwh');
INSERT INTO verses VALUES (9787, 12, 9, 27, 'e-Achaziahu rei-de ver viu o-caminho-de caminho o-jardim o-jardim e-yirdof acharo E-disse E-disse também אֹת֞וֹ [בְּמַֽעֲלֵה־גוּר֙] a a-carruagem bemaale- Gur que a Yiblamo e-fugiu Megido E-morreu nome');
INSERT INTO verses VALUES (9788, 12, 9, 28, 'veyarchivu ele servos-dele Yerushalama e-enterraram ele bikvuroto com pais-dele em-cidade-de Davi');
INSERT INTO verses VALUES (9789, 12, 9, 29, 'e-na-ano uma dez ano para-Yoram filho-de Acabe rei Ahaziah sobre Judá');
INSERT INTO verses VALUES (9790, 12, 9, 30, 'e veio jeova jizreel e-abel ouviu-se e-pôs em-olho suas-olhos e enxameou a cabeça-ela e olhou por-causa-de a-janela');
INSERT INTO verses VALUES (9791, 12, 9, 31, 'e-Jeú veio no-pátio E-disse será-quieto Zimri matou seu senhor');
INSERT INTO verses VALUES (9792, 12, 9, 32, 'va-yiss-a de-seus-faces a E-disse quem quem quem quem a-ele para-ele dois três eunucos:');
INSERT INTO verses VALUES (9793, 12, 9, 33, 'E-disse e-ele-abaixaram-na-a e-ele-vomitou de-seu-sangue a o-muro e-a הַסּוּסִ֖ים e-o-remexeu-a');
INSERT INTO verses VALUES (9794, 12, 9, 34, 'E-veio e-comeu e-bebeu-ele E-disse contem- por-favor a a-maldita que e-enterraram-a porque filha-de rei ela');
INSERT INTO verses VALUES (9795, 12, 9, 35, 'e-foram para-o-tombo-a e-não acharam que porque se a-gulhéte e-os-pés e-as-mãos das-mãos');
INSERT INTO verses VALUES (9796, 12, 9, 36, 'e-eles-voltaram-se ויאגוּ a-ele E-disse palavra-de ele ele que palavra por-mão-de seu servo dizendo o-Tisbita dizendo em-parte Jizreel comerão os cães a de-a-carne אִיזָֽבֶל׃');
INSERT INTO verses VALUES (9797, 12, 9, 37, 'corpo-morto-de Izabel de-Kedem sobre face-de o-campo em-parte יִזְרְעֶאל que não e-eles-dizem esta אִיזָֽבֶל׃');
INSERT INTO chapters VALUES (323, 12, 10, 36);
INSERT INTO verses VALUES (9798, 12, 10, 1, 'e-a-Acau setenta filhos בְּשֹׁמְרֹנָה e-ele-escreveu Ele livros e-enviou shomron a príncipes-de Jizreel os-ancianos e-a dizendo Acabe para-dizer');
INSERT INTO verses VALUES (9799, 12, 10, 2, 'e-agora descer o-livro o-este a-vós e-com-voces filhos-de adonai-vosso e-com-voces o-carro e-os-cavalo-s וְעִ֥יר de-fortaleza e-o-beijo-verso');
INSERT INTO verses VALUES (9800, 12, 10, 3, 'e-vistes o-bom e-o-retirado de-filhos-de adonai-de-vós e-postareis sobre seu-pai pai-seu e-lutaram sobre casa seus-mestres-verso');
INSERT INTO verses VALUES (9801, 12, 10, 4, 'e-temeram muito muito e-disseram eis segundo os-reis não עָמְד֖וּ diante-dele e como nós-pararemos nós-verso');
INSERT INTO verses VALUES (9802, 12, 10, 5, 'e-enviou que sobre a-casa e-que sobre a-cidade e-os-anciãos dizendo a Jeoá e-tudo servos-teus nós e-todo que dizerás a-nós façamos-nós não nosso-reinaremos homem o-bom nos-teus-olhos fez');
INSERT INTO verses VALUES (9803, 12, 10, 6, 'e-escreveu a-eles livro segundo dizendo dizendo para-mim vós e-a-mim-ouvindo vós ouvintes levem a ra-shei homens-de filhos-de adonai-de-vós e-virem a-mim agora מחר a-Jezreel e-filhos-de o-rei setenta homem a grande-s a-cidade aumentando-s a-eles');
INSERT INTO verses VALUES (9804, 12, 10, 7, 'e-houve quando-entrar o-livro a-eles e-eles-levaram a filhos-de o-rei e-sacrificaram setenta homem e-puseram a os-cabeças-deles a-ele e-ele-mandou a-ele Jezabel:');
INSERT INTO verses VALUES (9805, 12, 10, 8, 'E-veio o-anjo e-contou dizendo dizendo e-trouxeram cabeças-de E-disse o-rei eles colocaram os-eles segundo povo-s porta o-porta até a-manhã');
INSERT INTO verses VALUES (9806, 12, 10, 9, 'e-houve pela-manhã e-saiu e-ele-estabeleceu-se E-disse a todo o-povo eis vós eis eu eu-liguei sobre Adonai e-eu-matei-o e-quem atingiu a todo estes');
INSERT INTO verses VALUES (9807, 12, 10, 10, 'sabedoria então que não ele-cairá do-deserto yhwh terra-para que yhwh yhwh sobre casa Acabe e-יהוה fez a que palavra em-mão seu-escravo Elias');
INSERT INTO verses VALUES (9808, 12, 10, 11, 'e-feriu Jeoacaz a todo os-restantes para-casa-de Ahav em-Yesreel e-todo seus-grandes e-seus-conhecidos e-seus-sacerdotes até para-não deixar-restar para-ele sobrevivente');
INSERT INTO verses VALUES (9809, 12, 10, 12, 'E-levantou E-veio E-andou Samaria ele casa-de laço os-pastores no-caminho');
INSERT INTO verses VALUES (9810, 12, 10, 13, 'e-Yehu encontrou a irmãos-de אֲחַזְיָ֣הוּ E-disse quem E-disse quem vós e-disseram irmãos [וַנֵּ֛רֶד] nós e-nos-descemos para-a-paz filhos-de o-rei e-filhos-de a-grande-mulher-:');
INSERT INTO verses VALUES (9811, 12, 10, 14, 'E-disse e-os-prenderam vida e-eles-os-prenderam vida e-eles-os-exterminaram a cova casa-de o-nó quarenta e-dois homem e-não deixou homem de-eles');
INSERT INTO verses VALUES (9812, 12, 10, 15, 'E-andou de-daí e-ele-encontrou a Yehonadab filho-de reboque E-disse a-ele E-disse a-ele haja-esse a de-teu-coracao retto E-disse no meu coração com teu-coracao E-disse Yehonadav E-colocou sua-mão dá a-ele teu-mão E-deu mão-de-ele e-ele-alçou-o a-ele a a merkabah׃');
INSERT INTO verses VALUES (9813, 12, 10, 16, 'E-disse vem comigo e-veja em-minha-ira a-yhwh e-eles-reboquaram ele com-seu-reboque');
INSERT INTO verses VALUES (9814, 12, 10, 17, 'E-veio Samaria e-ele-golpeou a todo os-restantes a Achabe em-Samaria yhwh destrui-o conforme-a-palavra-de yhwh que palavra a Elias');
INSERT INTO verses VALUES (9815, 12, 10, 18, 'e-queixou-se Jeho a E-disse o-povo E-disse lavrar Achabe servo a o Baal um pouco o-ouro servir-lhe-ão mais');
INSERT INTO verses VALUES (9816, 12, 10, 19, 'e-agora todo profetas-de Baal-e todo seus-servos e-todo seus-sacerdotes chamaram que homem a ser-contado porque zevach grande não לַבַּ֔עַל todo que ser-ordenado não viverá e-Jeuá fez em-o-calcanhar para o-perderá a עֹבְדֵ֥י o-dono');
INSERT INTO verses VALUES (9817, 12, 10, 20, 'E-disse Jeú santificai-vos assembléia para-o-בַעַל e-eles-chamaram');
INSERT INTO verses VALUES (9818, 12, 10, 21, 'e-estendeu Jeú em-todo Israel e-vieram todo servidores-de o-Baal e-não permaneceu homem que não veio e-vieram casa o-Baal e-cheio casa-de הַבַּ֖עַל boca para-a-boca');
INSERT INTO verses VALUES (9819, 12, 10, 22, 'E-disse para-o-que sobre da-meltinga Saia a-todo para-todo servidores-de do-senhor a-eles a-eles do-vestido');
INSERT INTO verses VALUES (9820, 12, 10, 23, 'E-veio Jeú e-Yehonadab filho-de Rechav casa E-disse E-disse para-o-servos-de o Senhor procurem-no-os e-vi-deis para-que-não há yhwh que de-aos-servos-de yhwh porque se עֹבְדֵ֥י הַבַּ֖עַל para-eles-mesmos-verso-final');
INSERT INTO verses VALUES (9821, 12, 10, 24, 'e-vieram para-fazer sacrifícios e-oferendas וְיֵה֞וּא dele para-ele בַחוּץ֙ oitenta E-disse E-disse o-homem que se esconderá de os-homens que eu debaixo sobre vossas mãos para-ele debaixo-de a sua alma:');
INSERT INTO verses VALUES (9822, 12, 10, 25, 'e-houve -quando ele tiver acabado para fazer a-oferta E-disse E-disse para os corredores e para os trinta -venham matem-no homem a ele sairá e-os-golpearam à-boca-de espada -e lançaram os corredores [וַיֵּלְכ֖וּ] e-foram até cidade casa-de o senhor:');
INSERT INTO verses VALUES (9823, 12, 10, 26, 'e saíram a os lugares casa-de do senhor e a queimaram');
INSERT INTO verses VALUES (9824, 12, 10, 27, 'e-eles-fizeram-se a coluna-de o-baal e-eles-fizeram-se a casa o-Baal e-ele-o-colocaram-no-lo até o-dia');
INSERT INTO verses VALUES (9825, 12, 10, 28, 'e destruiu Jeová a o Baal de Israel:');
INSERT INTO verses VALUES (9826, 12, 10, 29, 'somente pecados Yarav''am filho-de נְבָת que a-iniquidade a Israel não ele-se-apartou o-ouro de-a-trás-deles ovelhas-de-leite- o-ouro que casa-de El e-o-que em-Bdán');
INSERT INTO verses VALUES (9827, 12, 10, 30, 'E-disse yhwh a Jeu por-causa-de que fiz-bem- לַעֲשׂוֹת o-retido diante de mim como-tudo que com-o-coração-meu fiz-te- para-casa-de Acabe filhos-de a-ti morarão a-ti sobre trono-de Israel');
INSERT INTO verses VALUES (9828, 12, 10, 31, 'e-Jeu não guardou para-andar em-a- yhwh Elohim-de- não em-todo de-cima-de não se-apartou de-sobre חַטֹּ֣אות יָרָבְעָם que fez-pecar a Israel');
INSERT INTO verses VALUES (9829, 12, 10, 32, 'em-os-dias aqueles começou yhwh para-cortar em-Israel e-ele-golpeou-vos חזהאל em-todo fronteira-de Israel');
INSERT INTO verses VALUES (9830, 12, 10, 33, 'de o-Jordão do-leste o-sol a todo terra Gileade da-gad e-do-reuben e-da-menashe de-arorer que sobre vale-de Arnon e-o-gileade e-o-bashan');
INSERT INTO verses VALUES (9831, 12, 10, 34, 'e-resto-de palavras-de jeu e-todo que fez e-todo giburato não eles escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9832, 12, 10, 35, 'e-deitou-se jeu com seus-pais ele ele בְּשֹׁמְרֹנָה e-reinou jeoacaz filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9833, 12, 10, 36, 'e-os-dias que rei jeu sobre Israel vinte e-oito- ano בְּשֹׁמְרֽוֹן׃');
INSERT INTO chapters VALUES (324, 12, 11, 20);
INSERT INTO verses VALUES (9834, 12, 11, 1, 'e-ataliah mãe אחזיהוּ porque morreu que e-ele-se-levantou ve-te-abed a todo semente the-kingdom');
INSERT INTO verses VALUES (9835, 12, 11, 2, 'e-tomou Jeoviasbe filha-de o-rei Joram irmã- Acaziohu a ele filho-de Acazia e roubou ele ele filhos-de o-rei ele e-a ele de-diante-de as matas e-os-esconderam a-ele de-faces-de עֲתַלְיָ֖הוּ e-não foi-morto');
INSERT INTO verses VALUES (9836, 12, 11, 3, 'e-houve com ela casa yhwh se esconde seis dois e Atalia rainha sobre a-terra');
INSERT INTO verses VALUES (9837, 12, 11, 4, 'e-no-ano a-setima enviou יְהוֹיָדָע E-tomou a príncipes-de para-o-cariri e-os-ratos E-veio a-eles e-trouxe eles a-ele e-ele-fez-contrato yhwh em-o-contrato a-eles a-elas na-casa-de eles E-viu yhwh E-viu eles o rei');
INSERT INTO verses VALUES (9838, 12, 11, 5, 'e ordenou-lhes dizendo este a palavra que façam-no a-terceira de-vós veio-a o-sábado e-os-guarda guarda-de casa o rei');
INSERT INTO verses VALUES (9839, 12, 11, 6, 'e-a-trigesima no-porta afastar-se e-a-o-trigesímo-terceiro be-sha-ar atrás-de os-ratos e-vigiai a guarda-de a-casa massach-');
INSERT INTO verses VALUES (9840, 12, 11, 7, 'e-duas ha-yadot em-vós todo yotsei do sabbat ve-shamru a guarda-de casa-de yhwh a o rei');
INSERT INTO verses VALUES (9841, 12, 11, 8, 've-hiqqaptem sobre o-rei ao-redor homem vekelayo em-mão-de-ele vehabba a ha-sderot morrerá ve-heyu a o-rei be-tzeto u-v-bo''o-');
INSERT INTO verses VALUES (9842, 12, 11, 9, 'e fizeram príncipes-de como todo que ordem Joacim o-sacerdote e-eles-levaram homem a seus homens em o sábado povo que saem do sábado e-vieram a Joacim o-sacerdote');
INSERT INTO verses VALUES (9843, 12, 11, 10, 'E-colocou o sacerdote para-gerentes a chániyt e-a os oficiais que para-o-rei Davi que em-casa-de yhwh');
INSERT INTO verses VALUES (9844, 12, 11, 11, 'e-ele-estabeleceram os-corredores homem vekelayo em-a-mão-dele do lado a-casa da direita até lado a-casa a esquerda para o altar e para a casa sobre o-rei ao-redor');
INSERT INTO verses VALUES (9845, 12, 11, 12, 'e-ele-saiu a E-colocou o rei E-deu sobre-ele a ele e-a a testemunha e-eles-reinaram ele e-eles-ungeram-nole e-eles-golpearam- palma e-disseram viva o rei');
INSERT INTO verses VALUES (9846, 12, 11, 13, 'e-ela-ouviu atalya a voz os-corridos o-povo e veio a yhwh casa yhwh');
INSERT INTO verses VALUES (9847, 12, 11, 14, 'E-viu e-eis הַמֶּלֶךְ֩ ficou-em-pé sobre o-amudo como-mispat e-os-sarim e-as-chatzrot a a-terra e-todo povo a-terra sam-eich ve-toke-a ba-chatzrot va-tikra Atal-yah a בּ-גָדֶ֔יהָ e-chamou קֶ-שׁ֥ר kasher:');
INSERT INTO verses VALUES (9848, 12, 11, 15, 'E-ordenou Joada o sacerdote a príncipes-de pequdei hachayil E-disse a-eles E-disse a-ela a de-casa-de para-as-filas vehabba atrás-de-ela a-morte com a espada porque que disse a tumat casa yhwh');
INSERT INTO verses VALUES (9849, 12, 11, 16, 'e-ele-estabeleceram a-ela mãos e-ela-chegou דרך־ מְב֥וֹא הַסּוּסִ֖ים casa o-rei e-tumat nome');
INSERT INTO verses VALUES (9850, 12, 11, 17, 'וַיִּכְרֹ֨ת יְהוֹיָדָע a entre yhwh e-entre e-entre e-entre e-entre o-povo a-ser para-o-povo e-entre e-entre e-entre e-entre o-povo');
INSERT INTO verses VALUES (9851, 12, 11, 18, 'e-vieram todo a-terra a-terra casa-de הַבַּ֜עַל e-ele-os-separou a e-a as-sombras-dele quebraram hei-tev e-a ofertas sacerdote o-Baal eles-mataram diante-de das-areias-dos-altar e-ele-posto o-sacerdote yhwh sobre casa yhwh');
INSERT INTO verses VALUES (9852, 12, 11, 19, 'E-tomou a príncipes-de as-milhar e-a a-cári e-a os-racim a-terra todo povo a-terra yhwh a o rei de-casa-de yhwh e-venham caminho-de portão-de os-racim casa o-rei e-habitou sobre trono-de os reis:');
INSERT INTO verses VALUES (9853, 12, 11, 20, 'e alegrou-se todo com a-terra e a cidade Shaqatáh e-a Atalyahu e mataram com a espada casa');
INSERT INTO chapters VALUES (325, 12, 12, 22);
INSERT INTO verses VALUES (9854, 12, 12, 1, 'filho-de sete dois Jeoaas em-seu-reinado');
INSERT INTO verses VALUES (9855, 12, 12, 2, 'no ano de sete para-ele-Yehu rei Yehoash e quarenta ano rei be-Yerushalaim sua-mãe mãe-dele Zivá da fonte sete');
INSERT INTO verses VALUES (9856, 12, 12, 3, 'E-fez Yehoash HaYYāšar em-olhos-de yhwh todo seus-dias que orde-nho-o Jeoiada o-sacerdote');
INSERT INTO verses VALUES (9857, 12, 12, 4, 'somente as baamas não se-marcharam ainda o-povo מְזַבְּחִ֥ים וּֽמְקַטְּרִ֖ים בַּבָּמֽוֹת׃');
INSERT INTO verses VALUES (9858, 12, 12, 5, 'E-disse Yehoash a os-sacerdotes todo prata-o os-santos que será-trazido casa-de yhwh prata que-passa homem prata almas subia sobre prata que ele-subirá yhwh לֶב־ homem para-trazer casa yhwh');
INSERT INTO verses VALUES (9859, 12, 12, 6, 'tomem a-eles os-sacerdotes homem de-junto-de de-seu-vendedor e-eles [יְחַזְּקוּ֙] a em-inspeção a-todo para-todo que será-encontrado nome inspeção');
INSERT INTO verses VALUES (9860, 12, 12, 7, 'e-houve em-ano-de ʿešrīm [וְשָׁלֹ֛שׁ] ano para-o-rei Joás não [הַכֹּהֲנִ֖ים] os-sacerdotes a בדק a-casa');
INSERT INTO verses VALUES (9861, 12, 12, 8, 'E-chamou o-rei Yehoash Liyyohiyda'' o-sacerdote [וְלַכֹּ֣הֲנִ֔ים] E-disse a-eles por-que não-vós [מְחַזְּקִ֖ים] a em-inspeção e-agora e-agora a [מַכָּֽרֵיכֶ֔ם] prata de-junto-de [תִּתְּנֻֽהוּ] porque a-casa');
INSERT INTO verses VALUES (9862, 12, 12, 9, '[וַיֵּאֹ֖תוּ] הַכֹּֽהֲנִ֑ים para-não [קְחַת־כֶּ֙סֶף֙] prata de-junto-de o-povo ולבלתי [אֶת־בֶּ֥דֶק] a בדק a-casa');
INSERT INTO verses VALUES (9863, 12, 12, 10, 'E-tomou יהודה o-sacerdote arca um [וַיִּקֹּ֥ב] [חֹ֖ר] [בְּדַלְתּ֑וֹ] E-colocou ele [אֵ֨צֶל] o-mizbeach [*בימין] homem casa yhwh yhwh [וְנָֽתְנוּ־שָׁ֤מָּה] os-sacerdotes os guardiões [הַסַּ֔ף] a todo o dinheiro casa-de yhwh');
INSERT INTO verses VALUES (9864, 12, 12, 11, 'e-houve para ver-los porque muito o cêsfe no arôn e-subiu sopher o-rei e o kohen a-grande e deram forma a e dividiram a o cefes o nemtsá casa-de yhwh');
INSERT INTO verses VALUES (9865, 12, 12, 12, 'e natanu a o-prata o metukkán sobre os a-obra casa yhwh e yotziáhum yhwh a-árvore e lavenim a-árvore casa yhwh');
INSERT INTO verses VALUES (9866, 12, 12, 13, '[וְלַגֹּֽדְרִים֙] [וּלְחֹצְבֵ֣י] a-pedra e para comprar árvores e pedras monumento לחזק a em-inspeção casa-de yhwh e-para-todo que saia sobre a-casa');
INSERT INTO verses VALUES (9867, 12, 12, 14, 'só-que não ser-ará casa yhwh [סִפּ֥וֹת] prata [מְזַמְּר֤וֹת] [מִזְרָקוֹת֙] [חֲצֹ֣צְר֔וֹת] todo ouro ouro e-vesselário- prata de o dinheiro casa-de yhwh');
INSERT INTO verses VALUES (9868, 12, 12, 15, 'porque [הַמְּלָאכָ֖ה] a-obra [וְחִזְּקוּ־ב֖וֹ] [אֶת־בֵּ֥ית] yhwh a casa yhwh');
INSERT INTO verses VALUES (9869, 12, 12, 16, 'e-não [יְחַשְּׁב֣וּ] a os-homens que darão a a-prata sobre a-mão-dele que [בֶאֱמֻנָ֖ה] eles porque e-ele-s עֹשִׂ֣ים׃');
INSERT INTO verses VALUES (9870, 12, 12, 17, 'prata [אָשָׁם֙] e-prata [חַטָּא֔וֹת] não [יוּבָ֖א] casa yhwh para-os-sacerdotes ser-ão');
INSERT INTO verses VALUES (9871, 12, 12, 18, 'então subia [חֲזָאֵל֙] rei Arã e lutou sobre gat [וַיָּ֤שֶׂם] e-ele-colocou [פָּנָ֔יו] rosto-dele para-subir sobre Jerusalém');
INSERT INTO verses VALUES (9872, 12, 12, 19, 'E-tomou [יְהוֹאָ֣שׁ] rei-de Judá a todo [יְהוֹשָׁפָ֣ט] que [וַאֲחַזְיָ֨הוּ] יְהוֹשָׁפָ֣ט [מַלְכֵ֤י] e-achaziahu [וְאֶת־קֳדָשָׁ֔יו] reis-de Judá e-a [בְּאֹצְר֥וֹת] e-a todo o-ouro [וַיִּשְׁלַ֗ח] [לַֽחֲזָאֵל֙] casa-de yhwh e-Beit de-cima-de e-enviou rei e-ele-subiu de-sobre Jerusalém');
INSERT INTO verses VALUES (9873, 12, 12, 20, 'e-resto-de palavras-de Yoash e-todo que fez porventura-não eles escritos sobre livro-de palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9874, 12, 12, 21, 'WAYYAKUMU servos-dele WAYYIQSHRU- קָ֑שֶׁר WAYYAKCHU a Joás casa enchei o-yored silaa');
INSERT INTO verses VALUES (9875, 12, 12, 22, 'e-jozavad filho-de shim''at e-yozavad filho-de שׁומר seus-servos chiku E-morreu ele a-ele com pais-dele na-cidade Davi e-reinou amatsiya filho-dele em-lugar-dele');
INSERT INTO chapters VALUES (326, 12, 13, 25);
INSERT INTO verses VALUES (9876, 12, 13, 1, 'em-ano-de vinte e-três ano [לְיוֹאָ֥שׁ] filho-de Acazias rei Judá rei [בֶּן־יֵה֤וּא] filho-de [בְּשֹׁ֣מְר֔וֹן] sobre Israel em-Samaria sete dez anos');
INSERT INTO verses VALUES (9877, 12, 13, 2, 'E-fez o-mal em-olhos-de yhwh E-andou aḥar [חַטֹּ֜את] Jeroboão filho-de Nebate que fez-pecar a Israel não ele-se-apartou de-elas');
INSERT INTO verses VALUES (9878, 12, 13, 3, 'e-acendeu-se- yhwh yhwh em-Israel וַֽיִּתְּנֵ֞ם em-mão-de חֲזָאֵ֣ל rei-de אֲרָ֗ם e-na-mao-de filho-de haddad filho-de חזהאל todo os dias');
INSERT INTO verses VALUES (9879, 12, 13, 4, 'וַיְחַ֥ל יהוה-אחז a yhwh yhwh a-ele yhwh que ver viu a PRESSÃO eles porque PRESSOU eles rei aram');
INSERT INTO verses VALUES (9880, 12, 13, 5, 'E-colocou yhwh para-o-Israel SALVADOR e-eles-saem debaixo-de mão-de Arã E SEDERAM-SE filhos-de Israel EM SUAS TENDAS כִּתְמ֥וֹל terceiro-dia');
INSERT INTO verses VALUES (9881, 12, 13, 6, 'MAS não ELES SE LEVANTARAM de-pecados casa-de יְהוֹרָבְעָם que a Israel בָּ֣הּ andou e-também הָאֲשֵׁרָ֔ה עָמְדָ֖ה בְּשֹׁמְרֽוֹן׃');
INSERT INTO verses VALUES (9882, 12, 13, 7, 'que não הִשְׁאִ֨יר לִיהוֹאָחָ֜ז povo que se cinquenta פָּֽרָשִׁים֙ וַעֲשָׂ֣רָה carros e-a-década dois-mil que porque אִבְּדָם֙ rei Arã e os colocou כֶּֽעָפָ֖ר ладушׁ׃');
INSERT INTO verses VALUES (9883, 12, 13, 8, 'e-resto-de palavras [יְהוֹאָחָ֛ז] e-todo que fez וּגְבוּרָת֑וֹ porventura-não eles escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9884, 12, 13, 9, 'e-deitou-se Yehoáquim com seus-pais e-o-enteraram-lá בְּשֹׁמְרֹנָה e-reinou Joás filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9885, 12, 13, 10, 'em-ano-de trinta e-sete ano para-ioash rei Judá rei [יְהוֹאָ֨שׁ] filho-de [עַל־יִשְׂרָאֵל֙] sobre Israel em-Samaria seis dez anos');
INSERT INTO verses VALUES (9886, 12, 13, 11, 'o-mal em-olhos-de yhwh yhwh não de-todo [מִכָּל־חַטֹּ֞אות] Jeroboão filho-de Nebate que fez-pecar a Israel n-a-lha andou');
INSERT INTO verses VALUES (9887, 12, 13, 12, 'e-resto-de palavras de Yoash e-todo que fez e sua força que ele lutou povo Amazias rei-de Judá não eles escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9888, 12, 13, 13, 'e-deitou-se Yoash com seus-pais וירבעם habitou sobre seu trono e enterrou Yoash em-Samaria povo reis-de Israel');
INSERT INTO verses VALUES (9889, 12, 13, 14, 'e Eliasao ele sofreu a חליו que morreu nele a-ele a-ele Joas rei-de Israel e chorou sobre suas faces E-disse pai-meu pai-meu carros-de Israel וּפָרָשָֽׁיו׃');
INSERT INTO verses VALUES (9890, 12, 13, 15, 'E-disse a-ele Eliseu leva arco e arcos E-tomou a-ele arco-de e arcos:');
INSERT INTO verses VALUES (9891, 12, 13, 16, 'E-disse como-rei Israel montou mão-tua sobre a arco e montou sua-mão e-ele-posto Elias mãos-dele sobre mãos-de o rei');
INSERT INTO verses VALUES (9892, 12, 13, 17, 'E-disse abriu a janela ao-oriente e abriu e-l-i-sh-a arqueiro e disparou E-disse E-disse salvação para-יהוה e seta salvação em Aram e feriu a ארם em Aphek até כלה');
INSERT INTO verses VALUES (9893, 12, 13, 18, 'E-disse pe-go [הַחִצִּ֖ים] E-tomou E-disse para-rei-de Israel o-golpe- terra-para e-feriu פעמים');
INSERT INTO verses VALUES (9894, 12, 13, 19, '[וַיִּקְצֹ֨ף] sobre-ele homem os-Elohim E-disse para matar cinco ou seis vezes então [אֶת־אֲרָ֖ם] a e-agora até [פְּעָמִ֖ים] e-agora três פעמים a aram');
INSERT INTO verses VALUES (9895, 12, 13, 20, 'E-morreu Eliseu [וַֽיִּקְבְּרֻ֑הוּ] [וּגְדוּדֵ֥י] Moabe virão na-terra veio anos');
INSERT INTO verses VALUES (9896, 12, 13, 21, 'e-houve eles [׀] homem e-eis viram a הַגְּד֔וּד e lançaram- a o homem [אֱלִישָׁ֑ע] אֱלִישָׁ֑ע E-andou [הָאִישׁ֙] o-homem [אֱלִישָׁ֔ע] Eliseu e-viveu E-levantou sobre de-seus-pés');
INSERT INTO verses VALUES (9897, 12, 13, 22, 'וַֽחֲזָאֵל֙ rei Arã לָחַ֖ץ a Israel dias-de dias-de yehoachaz');
INSERT INTO verses VALUES (9898, 12, 13, 23, 'e acampou yhwh eles e teve misericórdia deles e-ele-virou a-eles para-que aliança-dele a Abraão Isaque e Jacó e-não queria destruí-los e-não lançou-os de-em-cima-de sua-face até agora');
INSERT INTO verses VALUES (9899, 12, 13, 24, 'E-morreu Hazael rei-de Arã e-reinou filho-de haddad filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9900, 12, 13, 25, 'e-voltou יהוהואָשׁ filho-de E-tomou E-tomou a as-cidades de-mão-de filho-de tomou filho-de Hazael seu-pai tomou de-mão-de Joaquim pai-dele em-mo-batalha três vezes o feriu Joás e-assentou-se a cidades-de Israel');
INSERT INTO chapters VALUES (327, 12, 14, 29);
INSERT INTO verses VALUES (9901, 12, 14, 1, 'em-ano-de dois para-joás filho-de joás rei Israel rei amatsiáhu filho-de Joás rei Judá');
INSERT INTO verses VALUES (9902, 12, 14, 2, 'filho-de vinte e-cinco ser foi em-seu-reinado e-vinte וָתֵ֙שַׁע֙ ano rei em-Jerusalém sua-mãe mãe-dele de Jerusalém');
INSERT INTO verses VALUES (9903, 12, 14, 3, 'E-fez o-justo em-olhos-de yhwh somente não como-davíd seu-pai כְּכֹ֧ל que fez seu-pai pai-dele fez');
INSERT INTO verses VALUES (9904, 12, 14, 4, 'somente as-moedas não eram-erigidos ainda o-povo oferecimentos e-queimadores בַּבָּמֽוֹת׃');
INSERT INTO verses VALUES (9905, 12, 14, 5, 'e-houve como חָזְקָ֥ה o-reino na-sua-mão e-golpeou a seus-servos os que matam seu-pai o-rei seu-pai');
INSERT INTO verses VALUES (9906, 12, 14, 6, 'e-a filhos-de não não [כַּכָּת֣וּב] [בְּסֵֽ[t]פֶר] [תּֽוֹרַת־מֹ֠שֶׁה] Moisés yhwh dizendo yhwh dizendo não [וּבָנִים֙] אָב֤וֹת sobre que וּבָנִים֙ não serão mortos sobre אָב֔וֹת porque se homem בְּחֶטְא֖וֹ');
INSERT INTO verses VALUES (9907, 12, 14, 7, 'ele bateu a Edom begai- dez milhares e-pegou a E-chamou em-mo-batalha E-chamou até o-dia Yakhtêel até o-dia a-esta');
INSERT INTO verses VALUES (9908, 12, 14, 8, 'enviou Amatsiya mensageiros a Jehoash filho-de Jehoacaz filho-de Je-hu dizendo Israel dizendo לְכָ֖ה foi-visto face');
INSERT INTO verses VALUES (9909, 12, 14, 9, 'e-enviou [יְהוֹאָ֣שׁ] rei-de Israel a dizendo rei-de יהודה֮ dizendo o cedro que no Líbano enviou dizendo o cedro que בַּלְּבָנוֹן֙ dizendo animal-de a בִּתְּךָ֥ Libni para-mulher וַֽתַּעֲבֹ֞ר animal-de o-campo que em-o-Líbano וַתִּרְמֹ֖ס a הַחֽוֹחַ׃');
INSERT INTO verses VALUES (9910, 12, 14, 10, '[הַכֵּ֤ה] bateste a Edom [לִבֶּ֑ךָ] teu-coração [וְשֵׁ֣ב] [בְּבֵיתֶ֔ךָ] em-a-casa-teu e-porque תִתְגָּרֶה֙ בְּרָעָ֔ה tu tu וִיהוּדָ֥ה contigo');
INSERT INTO verses VALUES (9911, 12, 14, 11, 'e-não ouviu אֲמַצְיָ֔הוּ e-subiu [מֶֽלֶךְ־יִשְׂרָאֵל֙] rei-de Israel ele face ele וַאֲמַצְיָ֣הוּ rei-de Judá em-casa-de sol que para-Judá');
INSERT INTO verses VALUES (9912, 12, 14, 12, 'e-foi-ferido Judá diante-de Israel e-eles-fugiram homem');
INSERT INTO verses VALUES (9913, 12, 14, 13, 'e-את וַאֲמַצְיָ֣הוּ rei-de Judá filho-de YehoAosh filho-de Achaziya tapas YehoAosh rei-de Israel na-casa-de sol Jerusalém vayiprots b''chomat Jerusalém b''sh''ar אֶפְרַיִם até portão hapinnah quatro centenas amah');
INSERT INTO verses VALUES (9914, 12, 14, 14, 'e-tome a tudo-de o-zazáv- e ha-kessef e-a todo hakelim o nimtséim be- yhwh uva''otserot casa o-rei e-a filhos-de ha-ta''aruboth E-tomou Shomronah');
INSERT INTO verses VALUES (9915, 12, 14, 15, 've-yetser devaré Yehoáš que fez e sua força e-que נִלְחַ֔ם povo Amazias rei-de Judá não-é eles escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9916, 12, 14, 16, 'e-deitou-se Joas com seus-pais e foi sepultado em-Samaria povo reis-de Israel e-reinou يروبعام filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9917, 12, 14, 17, 'e viveu Amazias filho-de Joas rei Judá morrendo mōth Joas filho-de Joaquim rei Israel cinco dez anos');
INSERT INTO verses VALUES (9918, 12, 14, 18, '[וְיֶ֖תֶר] palavras-de [אֲמַצְיָ֑הוּ] não-é eles escritos sobre livro-de palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9919, 12, 14, 19, 'e-queixaram-se sobre-ele e-queixaram-se birushalaim e-fugiu לָכִ֑ישָׁה e-eles-deram atrás-dele לָכִ֔ישָׁה וַיְמִתֻ֖הוּ nome');
INSERT INTO verses VALUES (9920, 12, 14, 20, 'e-levantaram ele sobre הַסּוּסִ֑ים [בִּירוּשָׁלַ֛͏ִם] [עִם־אֲבֹתָ֖יו] com pais-dele em-cidade-de Davi');
INSERT INTO verses VALUES (9921, 12, 14, 21, 've-yikhu todo povo Judá a Azarias e ele filho-de seis ele debaixo seu-pai a-ele sob Amazias:');
INSERT INTO verses VALUES (9922, 12, 14, 22, 'ele edificar a אֵילַ֔ת e-a para-יְהוּדָה atrás-de שְׁכַֽב־ o-rei com pais-dele');
INSERT INTO verses VALUES (9923, 12, 14, 23, 'no-ano-de cinco dez ano לַאֲמַצְיָ֥הוּ filho-de Joás rei Judá rei יָרָבְעָ֨ם filho-de יוֹאָ֤שׁ rei-de Israel em-Samaria quarenta e-uma anos');
INSERT INTO verses VALUES (9924, 12, 14, 24, 'E-fez o-mal em-olhos-de yhwh não se-apartou de-todo [יָרָבְעָ֣ם] Jeroboão filho-de נְבוֹת que fez-pecar a Israel');
INSERT INTO verses VALUES (9925, 12, 14, 25, 'ele [הֵשִׁיב֙] a território Israel de-levar Hamate até mar yhwh  כִּדְבַ֤ר  yhwh Elohim-de Israel que palavra por-mão-de seu-escravo [אֲשֶׁ֖ר] filho-de [הַחֵֽפֶר] o-profeta que');
INSERT INTO verses VALUES (9926, 12, 14, 26, 'porque yhwh yhwh a aflição-de muito [וְאֶ֤פֶס] muito [וְאֶ֣פֶס] [עָז֔וּב] [וְאֵ֥ין] [עֹזֵ֖ר] e-não-há para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (9927, 12, 14, 27, 'e-não yhwh yhwh para-machos a debaixo-de Israel de-debaixo-de os-céus וַיּ֣וֹשִׁיעֵ֔ם na-mão-de dizendo filho-de יוֹאָשׁ׃');
INSERT INTO verses VALUES (9928, 12, 14, 28, 'e-remanescente palavras [יָרָבְעָ֜ם] e-todo que fez [אֲשֶׁר־נִלְחָ֔ם] que se-lance e-que [וְאֶת־חֲמָ֛ת] a de-damasco e-a [כְּתוּבִ֗ים] para-Juda em-Israel não-é eles escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9929, 12, 14, 29, 'e-deitou-se yarav''am com seus-pais povo reis-de Israel e-reinou Zekaryá seu-filho em-lugar-dele');
INSERT INTO chapters VALUES (328, 12, 15, 38);
INSERT INTO verses VALUES (9930, 12, 15, 1, 'em-ano-de vinte e-sete ano [לְיָרָבְעָ֖ם] rei Israel rei Azarias filho-de Amatziyah rei Judá');
INSERT INTO verses VALUES (9931, 12, 15, 2, 'filho-de seis quinze ser foi em-seu-reinado e-cinquenta וְשֵׁתַיִם֙ ano rei em-Jerusalém sua-mãe mãe-dele [מִירוּשָׁלָֽ͏ִם] de-i-ru-shalaim');
INSERT INTO verses VALUES (9932, 12, 15, 3, 'E-fez o-reto em-olhos-de yhwh conforme-tudo que fez seu-pai pai-seu');
INSERT INTO verses VALUES (9933, 12, 15, 4, 'somente as baamas não se-marcharam ainda o-povo מְזַבְּחִ֥ים וּֽמְקַטְּרִ֖ים בַּבָּמֽוֹת׃');
INSERT INTO verses VALUES (9934, 12, 15, 5, 'e-nagge yhwh a e-houve E-foi metzora até dia [בְּבֵ֣ית] e-habitou em-casa-de [בֶּן־הַמֶּ֙לֶךְ֙] וְיוֹתָ֤ם filho-de o rei a-terra a-casa שפט a povo a-terra');
INSERT INTO verses VALUES (9935, 12, 15, 6, 'e-resto-de palavras-de [עֲזַרְיָ֖הוּ] e-todo que fez não-é eles escritos sobre livro-de palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9936, 12, 15, 7, 'e-deitou-se [עֲזַרְיָה֙] com seus-pais ele a-ele com pais-dele na-cidade Davi e-reinou Jotão filho-seu em-lugar-dele');
INSERT INTO verses VALUES (9937, 12, 15, 8, 'em-ano-de trinta e-šəmōneh ano lə-ăzarjahū rei Judá rei zə-kharyāhū filho-de Jeroboão sobre Israel em-Samaria šeš meses');
INSERT INTO verses VALUES (9938, 12, 15, 9, 'E-fez o-mal em-olhos-de yhwh como-que fizeram pais-seus não se-apartou [מֵֽחַטֹּאות֙] Jeroboão filho-de נְבוֹת que fez-pecar a Israel');
INSERT INTO verses VALUES (9939, 12, 15, 10, 'wa-yiqšōr sobre-ele šallūm filho-de yāḇēš e-ferrou-o qābal povo e-matou-o e-reinou em-lugar-dele');
INSERT INTO verses VALUES (9940, 12, 15, 11, 'wə-yetēr palavras-de Zacharyáh eis-os escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9941, 12, 15, 12, 'ele palavra-de yhwh que palavra dizendo ye-hu-a dizendo filhos-de a-ti morarão a-ti sobre trono-de Israel e-foi assim');
INSERT INTO verses VALUES (9942, 12, 15, 13, 'Shallum filho-de [מָלַ֔ךְ] rei em-ano-de trinta וָתֵ֙שַׁע֙ ano [מֶ֣לֶךְ] rei Judá e-reinou [בְּשֹׁמְרֽוֹן] dias בְּשֹׁמְרֽוֹן׃');
INSERT INTO verses VALUES (9943, 12, 15, 14, 'e-subiu מְנַחֵ֨ם filho-de גָּדִ֜י מִתִּרְצָ֗ה E-veio Samaria e bateu a shalom filho-de tinha vergonha בְּשֹׁמְר֑וֹן e matou-o e-reinou em-lugar-dele');
INSERT INTO verses VALUES (9944, 12, 15, 15, 'e sobreviventes palavras-de shalom e seu cinto que amarrava eis-os escrito sobre livro palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9945, 12, 15, 16, 'então [יַכֶּֽה־מְ֠נַחֵם] [אֶת־תִּפְסַ֨ח] a [וְאֶת־גְּבוּלֶ֙יהָ֙] e-a que não [פָתַ֖ח] e-a [OBJ] [כָּל־הֶהָ֥רוֹתֶ֖יהָ] porque não a todo');
INSERT INTO verses VALUES (9946, 12, 15, 17, 'em-ano-de trinta וָתֵ֙שַׁע֙ ano [לַעֲזַרְיָ֖ה] rei Judá rei [מְנַחֵ֨ם] filho-de [עַל־יִשְׂרָאֵ֛ל] sobre Israel dez dois בְּשֹׁמְרֽוֹן׃');
INSERT INTO verses VALUES (9947, 12, 15, 18, 'E-fez o-mal aos-olhos-de yhwh não [סָ֠ר] de-cima-de [חַטֹּ֜אות] Jeroboão filho-de Nebate que fez-pecar a Israel todo seus-dias:');
INSERT INTO verses VALUES (9948, 12, 15, 19, 'veio [פ֤וּל] rei-de ʾaššur E-colocou a-terra E-deu [אֶ֖לֶף] [כִּכַּר־כָּ֑סֶף] mil k-khar- prata para-ser de-suas-mãos com-ele o-reino em-mão-sua');
INSERT INTO verses VALUES (9949, 12, 15, 20, 'e-saiu-o m''nachem a o prata sobre Israel sobre todo valentes-de a-força para dar como-rei Assur cinquenta um prata a homem-de um e-ele-voltou rei Assur e-não ficou-em-pé nome na-terra');
INSERT INTO verses VALUES (9950, 12, 15, 21, 'e-resto-de palavras-de m''nachem e-todo que fez porventura-não eles escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9951, 12, 15, 22, 'e-ele-deitou m''nachem com pais-seus e-reinou p''kachya filho-dele em-lugar-dele');
INSERT INTO verses VALUES (9952, 12, 15, 23, 'no-ano-de cinquenta ano para-aazaryah rei Judá rei p''kachya filho-de m''nachem sobre Israel em-Samaria anos');
INSERT INTO verses VALUES (9953, 12, 15, 24, 'E-fez o-mal em-olhos-de yhwh não afastou-se das-inferiões Jeroboão filho-de נְבָ֔ט que fez-pecar a Israel');
INSERT INTO verses VALUES (9954, 12, 15, 25, 'e-ela-cordou עֲלֵיהוּ פֶּ֨קַח filho-de Ramalyahu terço e-ela-o-castigou em-Someron em-Armon casa-de a Argob e-a a arábia e-o cinquenta homem de-filhos-de giládís e o matou e-reinou em-lugar-dele');
INSERT INTO verses VALUES (9955, 12, 15, 26, 'e-resto-de palavras-de [פְקַחְיָ֖ה] e-todo que fez eis-os escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9956, 12, 15, 27, 'em-ano-de cinquenta e-shtayim ano para azaryá rei Judá rei פקחיה filho-de remalíyaú sobre Israel em-Samaria vinte anos');
INSERT INTO verses VALUES (9957, 12, 15, 28, 'E-fez o-mal em-olhos-de yhwh não afastou-se de chatóat Jeroboão filho-de נְבָ֔ט que fez-pecar a Israel');
INSERT INTO verses VALUES (9958, 12, 15, 29, 'nos-dias [פֶּ֣קַח] rei-de Israel veio [פִּלְאֶסֶר֮] [מֶ֣לֶךְ] rei E-tomou E-tomou a [בֵּֽית־מַעֲכָ֡ה] e-a avel casa-de [וְאֶת־הַגִּלְעָד֙] e-a [כֹּ֖ל] terra קֶדֶשׁ e-a [אַשּֽׁוּרָה] e-a o-Gileade e-a todo terra Naftali');
INSERT INTO verses VALUES (9959, 12, 15, 30, '[וַיִּקְשָׁר־קֶ֜שֶׁר] [הוֹשֵׁ֣עַ] [בֶּן־אֵלָ֗ה] filho-de [בֶּן־רְמַלְיָ֔הוּ] sobre [וַיְמִיתֵ֔הוּ] filho-de [תַּחְתָּ֑יו] וַיַּכֵּ֙הוּ֙ וַיְמִיתֵ֔הוּ e-reinou tachthayo em-ano-de vinte filho-de');
INSERT INTO verses VALUES (9960, 12, 15, 31, '[וְיֶ֥תֶר]  דּ-בְרֵי-  [וְכָל־אֲשֶׁ֣ר] e-todo que fez eis-os escritos sobre livro-de palavras-de os-dias para-reis-de Israel');
INSERT INTO verses VALUES (9961, 12, 15, 32, 'no-ano-de dois [לְפֶ֥קַח] filho-de Remaljahu rei Israel rei Jotão filho-de [יְהוּדָֽה] rei Judá');
INSERT INTO verses VALUES (9962, 12, 15, 33, 'filho-de vinte e-cinco ser foi em-seu-reinado e-seis- dez ano rei sua-mãe e-nome-de sua-mãe Jerusalém filha-de צָדֽוֹק׃');
INSERT INTO verses VALUES (9963, 12, 15, 34, 'E-fez o-reto aos-olhos-de yhwh [כְּכֹ֧ל] que fez seu-pai pai-dele fez');
INSERT INTO verses VALUES (9964, 12, 15, 35, 'apenas [הַבָּמוֹת֙] não [סָ֔רוּ] ainda o-povo מְזַבְּחִ֥ים וּֽמְקַטְּרִ֖ים na-altar ele edificar a portão-de casa-de yhwh');
INSERT INTO verses VALUES (9965, 12, 15, 36, 'e-resto-de palavras-de Yoțam que fez não-é eles escritos sobre livro-de palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9966, 12, 15, 37, 'em-os-dias aqueles começou yhwh [לְהַשְׁלִ֙יחַ֙] em juáda retzin rei Arã e-a [פֶּ֥קַח] filho-de Remaljahu');
INSERT INTO verses VALUES (9967, 12, 15, 38, 'e-deitou-se Yoțam com seus-pais e-enterrou com seus-pais seu-pai Davi pai-seu e-reinou Acaz filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (329, 12, 16, 20);
INSERT INTO verses VALUES (9968, 12, 16, 1, 'no-ano-de sete- dez ano para-Pekach filho-de רְמַלְיָהוּ rei Acaz filho-de Yoțam rei Judá');
INSERT INTO verses VALUES (9969, 12, 16, 2, 'filho-de vinte ano Açãz no-seu-reino e-seis- dez ano rei em-Jerusalém e-não yhwh o que é reto nos olhos de seu-pai Elohim-seu seu-pai seu-pai');
INSERT INTO verses VALUES (9970, 12, 16, 3, 'E-andou em-caminho-de reis-de Israel e-também a filho-o ele fez passar no-fogo coisas-que-são-loathable as-nações que yhwh eles de-diante-de de-face-de filhos-de Israel');
INSERT INTO verses VALUES (9971, 12, 16, 4, 'e ofereceu em holocausto e faz queimarem em as baamas e-sobre as colinas e-debaixo-de todo árvore Raanã:');
INSERT INTO verses VALUES (9972, 12, 16, 5, 'então subia רְצִ֣ין rei-de ארם וּפֶ֨קַח filho-de Remaliahu rei-de Israel Jerusalém para-a-guerra e se fortificaram sobre achaz e-não puderam para-lutar');
INSERT INTO verses VALUES (9973, 12, 16, 6, 'em-o-tempo a aquela devolveu princípio rei-de Arameus a Elat Arameus e desviou a os Judeus de Elão vieram Elat e-ele-estabeleceram-se até o-dia o-dia a-esta');
INSERT INTO verses VALUES (9974, 12, 16, 7, 'e-enviou [אָחָ֜ז] mensageiros a [פְּלֶ֤סֶר] [מֶֽלֶךְ־אַשּׁוּר֙] dizendo ʾaššur dizendo avadcha folhas-de eu sobre-a [מֶֽלֶךְ־אֲרָ֗ם] da-palma rei-de אֲרָ֗ם [הַקּוֹמִ֖ים] rei Israel sobre-mim');
INSERT INTO verses VALUES (9975, 12, 16, 8, 'E-tomou [אָחָ֜ז] a o-prata e-a o-ouro yhwh casa yhwh [הַמֶּ֑לֶךְ] casa o-rei e-enviou para-rei-de sód');
INSERT INTO verses VALUES (9976, 12, 16, 9, 'E-ouviu a-ele rei Assur e-subiu rei אַשׁוּר a דַּמְשֶׂק e se estendeu e expulsou-a cidadela e-a רְצִ֖ין הֵמִֽית׃');
INSERT INTO verses VALUES (9977, 12, 16, 10, 'E-andou o-rei Acaz para Tiglate Pilpar rei-de Assuero E-viu E-viu a o-altar que em Damasco e-enviou o-rei Acaz a אוּרִיָּ֣ה o-sacerdote a semelhança o-altar e-a suas-estruturas para-todo seus-feitos');
INSERT INTO verses VALUES (9978, 12, 16, 11, 'E-edificou Uriah o-sacerdote a o-altar como-todo que enviou o-rei Acaz Midiámesque assim fez אוּרִיָּ֣ה o-sacerdote até vir o-rei dizendo Midiámesque');
INSERT INTO verses VALUES (9979, 12, 16, 12, 'E-veio o-rei Midiámesque E-viu o-rei a o-altar e-ele-se-aproximou o-rei sobre o-altar e-ofereceu sobre-ele');
INSERT INTO verses VALUES (9980, 12, 16, 13, 'e-ele-queimou-com-incenso a sua-oferta e-a sua-oferta e-ferrou a seu-sacrifício e-lançou a דְּמַ— הַשְּלָמִ֥ים que para-ele sobre o-altar');
INSERT INTO verses VALUES (9981, 12, 16, 14, 'e-a [הַמִּזְבַּ֣ח] [הַנְּחֹשֶׁת֮] que diante-de yhwh [וַיַּקְרֵ֗ב] de-com face-de a-casa do meio o altar [וּמִבֵּ֖ין] casa yhwh E-colocou ele sobre lado-de o-altar tsāphōnā');
INSERT INTO verses VALUES (9982, 12, 16, 15, 'o-rei אָ֠חָז a אוּרִיָּ֨ה o sacerdote dizendo sobre הַמִּזְבֵּ֣חַ הַגָּד֡וֹל o incenso a oferenda de fumaça - do manhã - e-a minhá da tarde e-a oferta de fumaça - o-rei a-terra minhá e oferta de fumaça - todo povo a-terra minhá e seus caldeirões - e-todo דם holocausto e-todo דם sacrifício-masculino-singular sobre-ele תזרוק e o altar הנחושת ele-será- para-mim לבקר׃');
INSERT INTO verses VALUES (9983, 12, 16, 16, 'E-fez Uriah o-sacerdote conforme-tudo que ordenou o-rei acegaz:');
INSERT INTO verses VALUES (9984, 12, 16, 17, 'ויתקצץ֩ o-rei Acaz a המסגרות המכונות e-removeu de-lhes o-círio e-a de-cima-de descer de-acima o-gado a-nexos E-colocou ele sobre a-ele sobre már-capé a-banim-kaf-segol');
INSERT INTO verses VALUES (9985, 12, 16, 18, 'e-a o-sabá que eles-fizeram no-casa e-a ingresso o rei a-saída volveu-se yhwh de-diante-de de-face-de rei אַשּׁוּר׃');
INSERT INTO verses VALUES (9986, 12, 16, 19, 'e-resto-de palavras-de agarrado que fez não-é eles escritos sobre livro-de palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (9987, 12, 16, 20, 'e-deitou-se אָחָז֙ com seus-pais e-foi-enterrado com pais-dele na-cidade Davi e-reinou Ezequias filho-dele em-lugar-dele');
INSERT INTO chapters VALUES (330, 12, 17, 41);
INSERT INTO verses VALUES (9988, 12, 17, 1, 'no-ano-de שִׁיתִֽים dezoito אחז rei Judá rei Oseias filho-de elohimes em-Someron sobre Israel nove dois');
INSERT INTO verses VALUES (9989, 12, 17, 2, 'E-fez o-mal em-olhos-de yhwh somente não como-reis Israel que foram diante-de-ele');
INSERT INTO verses VALUES (9990, 12, 17, 3, 'sobre-ele subir Salamanceir rei Assur e-foi para-ele Hoshea servo a-ele a-ele oferta-:');
INSERT INTO verses VALUES (9991, 12, 17, 4, 'e achou rei-de Assur בּוֹהוֹשֵׁעַ cabo que enviou mensageiros a Sua rei-de Egito e-não fez-subir oferta para-rei-de Assíria como ano no ano rei Assíria e prendeu-o casa como leão:');
INSERT INTO verses VALUES (9992, 12, 17, 5, 'e-ofereceu rei-de Assíria em-todo a-terra e-subiu Samaria e comprimiu sobre-ela três dois');
INSERT INTO verses VALUES (9993, 12, 17, 6, 'em-ano-de ninth a Hosea pegou rei-de Açãur a Samaria e fez a eles Assúria e habitou lhes em Chalach e em Chaborá נְהַ֥ר גּוֹזָ֖ן e as cidades מָדָֽי׃');
INSERT INTO verses VALUES (9994, 12, 17, 7, 'e-houve porque חָטְא֤וּ filhos-de Israel a-yhwh eles הַמַּעֲלֶ֤ה eles debaixo-de Egito מִתַּ֕חַת mão faráoh rei-de Egito a-ele Elohim outros:');
INSERT INTO verses VALUES (9995, 12, 17, 8, 'e-andaram [בְּחֻקּ֣וֹת] as-nações que ele-desapossou yhwh de-diante-de filhos-de Israel e-reis-de Israel que fizeram');
INSERT INTO verses VALUES (9996, 12, 17, 9, '[וַיְחַפְּא֣וּ] filhos-de Israel palavras que não assim sobre a-eles elohim-deles [בְּכָל־עָ֣רֵיהֶ֔ם] para-eles [נוֹצְרִ֖ים] em-todo arehem de-monte até cidade Mibzar');
INSERT INTO verses VALUES (9997, 12, 17, 10, '[וַיַּצִּ֧בוּ] a-eles [מַצֵּב֖וֹת] [וַאֲשֵׁרִ֑ים] sobre todo [גְבֹהָ֔ה] alta [כָּל־עֵ֥ץ] todo');
INSERT INTO verses VALUES (9998, 12, 17, 11, 'וַיְקַטֵּרוּ nome em-todo בָּמוֹת yhwh que הֶגְלָה yhwh de-face-deles e fizeram palavras más para provocar ira a yhwh');
INSERT INTO verses VALUES (9999, 12, 17, 12, 'e serviram as imagens de fundo que disse yhwh a-eles não fareis a a-palavra a-esta');
INSERT INTO verses VALUES (10000, 12, 17, 13, 'e testemunhou yhwh em Israel e em Judá por mão de todo todo profeta dizendo Returnai-vos dos vossos caminhos as más e guardem meus-mandamentos minhas-chuquqotay como todos os ha-torah que ordenei a vosso pais que enviei-eu a-vós em-mão minha servos os-profetas');
INSERT INTO verses VALUES (10001, 12, 17, 14, 'e-não ouvirem e endureceram a os seus braços a face pais-deles não não e creram em-יהוה אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (10002, 12, 17, 15, 'e fizeram a seus mandamentos e-a sua aliança que cortou a pais-deles e-את suas testemunhas que testemunhou neles e foram depois-de ה hebé vayehbálu ve''acharei as-nações que yhwh eles para-não yhwh a-eles para-não fazer כָּהֶֽם׃');
INSERT INTO verses VALUES (10003, 12, 17, 16, 'vayazavú a yhwh mandamentos-de yhwh a-eles e-fizeram a-eles mas''kah agálim e-fizeram ašérah e-prostraram-se para-todo exército-de os-céus e-serviram a habba''al');
INSERT INTO verses VALUES (10004, 12, 17, 17, 'vay''abíru a filhos-les e-a filhas-elas no-fogo e-eles-sacraram-se-por-pacto קְסָמִ֖ים e-eles-consultaram-se-a-sorte e-eles-venderam-se para-fazer yhwh em-olhos-de yhwh para-irritar-ele');
INSERT INTO verses VALUES (10005, 12, 17, 18, 'e-ele-irritou-se yhwh muito em-Israel e-eles-sacaram-lhes de-cima-de perante-ele não restou somente bastão Judá sozinho');
INSERT INTO verses VALUES (10006, 12, 17, 19, 'também não não guardar yhwh mandamentos yhwh Elohim-deles e andaram nas suas leis Israel que fizeram');
INSERT INTO verses VALUES (10007, 12, 17, 20, 'e devastaram yhwh em-todo semente Israel e afligiram e-colocou-os até sementes até que e lançaram de-face-dele');
INSERT INTO verses VALUES (10008, 12, 17, 21, 'porque arrancou de-cima-de de-sobre casa Davi e reinaram a Jeroboão filho-de nabateus Jeroboao a yhwh de-depois-de yhwh e os pecadores pecadora grande:');
INSERT INTO verses VALUES (10009, 12, 17, 22, 'e-andaram filhos-de Israel em-todo pecados Jeroboão que fez não saru de-elas');
INSERT INTO verses VALUES (10010, 12, 17, 23, 'até que yhwh yhwh de-cima-de Israel de-sobre rosto-dele como palavra na-mão-de todo os seus servos de-cima-de e expulsou Israel até o-dia Assíria até o-dia a-esta');
INSERT INTO verses VALUES (10011, 12, 17, 24, 'e-trouxe rei-de Assíria de Babel e de Cutha e de Ava e-pela e-sparwaim e-yešab em-cidades-de debaixo sob filhos-de Israel e-os-ru a Shomeron e-yešabu em-suas-cidades:');
INSERT INTO verses VALUES (10012, 12, 17, 25, 'e-houve no-início-de sua-morada nome não e-temeram a yhwh yhwh yhwh neles a as arálias e foram matavam neles');
INSERT INTO verses VALUES (10013, 12, 17, 26, 'e-disseram como-rei אַשׁוּר dizendo הגוים que expulsaste e habitou em-cidades-de Samaria não sabiam a מִשְׁפַּ֖ט a-terra a-terra e enviou- em-eles a as arálias e eis-lhes מְמִיתִ֣ים a-eles como איןם a-terra a a-terra Elohim-de a-terra');
INSERT INTO verses VALUES (10014, 12, 17, 27, 'E-ordenou rei-de dizendo dizendo [שָׁ֙מָּה֙] um um [אֲשֶׁ֣ר] que [מִשָּׁ֔ם] de-lá [וְיֵ֣שְׁבוּ] [שָׁ֑ם] nome [אֶת־מִשְׁפַּ֖ט] a a-terra a-terra');
INSERT INTO verses VALUES (10015, 12, 17, 28, 'E-veio um [מֵהַכֹּהֲנִ֗ים] que [הִגְלוּ֙] [מִשֹּׁ֣מְר֔וֹן] e-habitou em-Betel e-houve E-foi eles a-eles como [אֶת־יְהוָֽה] a yhwh');
INSERT INTO verses VALUES (10016, 12, 17, 29, 'e-foram fazendo nação nação Elohim-dele e-estabeleceram em-casa-de as-baals que fizeram os-samaritanos nação nação em-os seus que eles eles nome');
INSERT INTO verses VALUES (10017, 12, 17, 30, 'e-homens-de Babel fizeram a סוכות filhas-de e-homens-do Cute fizeram a Nergal וְאַנְשֵׁ֥י חֲמָ֖ת fizeram a אֲשִׁימָֽא׃');
INSERT INTO verses VALUES (10018, 12, 17, 31, 'e os avuim fizeram נִבְחַ֖ז e-a תַּרְתָּ֑ק וְהַסְפַרְוִ֗ים שֹׂרְפִ֤ים a os-filhos-deles no-fogo לְאַדְרַמֶּ֥לֶךְ וַֽעֲנַמֶּ֖לֶךְ');
INSERT INTO verses VALUES (10019, 12, 17, 32, 'e-foram [יְרֵאִ֖ים] a yhwh a-eles para-eles [כֹּהֲנֵ֣י] [בָמ֔וֹת] [וַיִּהְי֛וּ] [עֹשִׂ֥ים] a-eles a-eles em-casa-de');
INSERT INTO verses VALUES (10020, 12, 17, 33, 'a yhwh foram [וְאֶת־אֱלֹֽהֵיהֶם֙] e-[OBJ] [עֹֽבְדִ֔ים] foram [הַגּוֹיִ֔ם] [אֲשֶׁר־הִגְל֥וּ] eles que');
INSERT INTO verses VALUES (10021, 12, 17, 34, 'até o-dia o-este eles fazendo como-julgamentos os-primeiros não-eles יראים a yhwh e-não-eles עֹשְׂיֵם como-leis e-julgamentos e-torah e-m Mandamentos que yhwh yhwh a filhos-de Jacó que nome tomou Israel');
INSERT INTO verses VALUES (10022, 12, 17, 35, 'e-cortou yhwh itam aliança e-ordenou-lhes dizendo não temais Elohim outros e-não a-eles a-eles e-não servi-los e-não a-eles para-eles');
INSERT INTO verses VALUES (10023, 12, 17, 36, 'que se a yhwh que העלה a-vós da-terra-de Egito בְּכֹ֧חַ grande ele pendente a-ele temereis e-lá adorem-no e-lá e-sacrifiquem-se:');
INSERT INTO verses VALUES (10024, 12, 17, 37, 'e-a as-leis e-a os-julgamentos e-a-torah e a mandar a-vós escrito a-vós guardareis-vós para-fazer todo os-dias e-não temais Elohim אֲחֵרִ֖ים׃');
INSERT INTO verses VALUES (10025, 12, 17, 38, 'e-a-aliança que eu-cortei não não ser-vos-olvidados e-não temais Elohim אֲחֵרִ֖ים׃');
INSERT INTO verses VALUES (10026, 12, 17, 39, 'que se a yhwh Elohim de-vós temais e-ele resgatará vos de-mão-de todo inimigos-vossos');
INSERT INTO verses VALUES (10027, 12, 17, 40, 'e-não [שָׁמֵ֑עוּ] que se [הָֽרִאשׁ֖וֹן] eles eles');
INSERT INTO verses VALUES (10028, 12, 17, 41, 'וַיִּהְיוּ as-nações estes יְרֵאִים a yhwh e-a פְּסִילֵיהֶם foram עֹבְדִים também בְּנֵיהֶם e-filhos-de filhos como-que asau eles eles até o-dia o-dia a-esta');
INSERT INTO chapters VALUES (331, 12, 18, 37);
INSERT INTO verses VALUES (10029, 12, 18, 1, 'e-houve em-ano-de três [לְהוֹשֵׁ֥עַ] filho-de Elá rei Israel rei [בֶן־אָחָ֖ז] filho-de [יְהוּדָֽה] rei');
INSERT INTO verses VALUES (10030, 12, 18, 2, 'filho-de vinte e-cinco ser foi em-seu-reinado e-vinte e-nove ano rei em-Jerusalém sua-mãe mãe-dele pai-de filha-de zacharyah:');
INSERT INTO verses VALUES (10031, 12, 18, 3, 'E-fez o-reto em-olhos-de yhwh conforme-tudo que fez seu-pai');
INSERT INTO verses VALUES (10032, 12, 18, 4, 'ele ele-derreteu a הַבָּמ֗וֹת וְשִׁבַּר֙ a הַמַּצֵּבֹות e cortará a a-asherah e-ele-escreveu nachash a-nacsoth que fez Moisés porque até os-dias a-ele eram filhos-de Israel mekatthrim a-ele e ele chamou para-ele nacshuthan');
INSERT INTO verses VALUES (10033, 12, 18, 5, 'בַּיהוָ֥ה Elohim-de Israel בָּטָח וְאַחֲרָ֞יו não foi kamohu em-todo reis-de Judá e-que foram diante-de-ele');
INSERT INTO verses VALUES (10034, 12, 18, 6, 'vayidbeq em-יהוה não apartou me-acharyav e guardou mitzvotayav yhwh ordenou yhwh a Moisés');
INSERT INTO verses VALUES (10035, 12, 18, 7, 'e-era yhwh com-ele em-todo que sairá yashqil וַיִּמְרֹ֥ד בְּמֶֽלֶךְ־ Assíria e-não עֲבָדֽוֹ׃');
INSERT INTO verses VALUES (10036, 12, 18, 8, 'ele [אֶת־פְּלִשְׁתִּ֛ים] a [וְאֶת־גְּבוּלֶ֑יהָ] até [נוֹצְרִ֖ים] e-[OBJ] [מִבְצָֽר׃] até cidade');
INSERT INTO verses VALUES (10037, 12, 18, 9, 'e-houve בַּשָׁנָ֤ה-no-ano הָֽרְבִיעִית֙ para-o-rei חִזְקִיָּ֔הוּ ela o ano a-sétima לְהוֹשֵׁ֥עַ filho-de Elá rei subir עָלָה Salmancaser rei-de Assíria sobre שרֹן e aprisionou sobre-ela');
INSERT INTO verses VALUES (10038, 12, 18, 10, 'e a aprisionaram de-a-extremidade-de três dois no-shanat- seis para Hezíah ela שנת－ nove para Josué rei Israel foi aprisionada Samaria');
INSERT INTO verses VALUES (10039, 12, 18, 11, 'e levou rei-de Açor a Israel Assúria e os fez em-chalach וּבְחָב֛וֹר nhar Gozan e as cidades mdiá:');
INSERT INTO verses VALUES (10040, 12, 18, 12, 'sobre que não ouviram em-voz yhwh Elohim-seus e-atravessaram a aliança-dele a todo que צִוּ֔ה yhwh servo yhwh e-não ouviram e-não fizeram');
INSERT INTO verses VALUES (10041, 12, 18, 13, 'e-em-quatro dez ano para-o-rei חִזְקִיָּ֗ה subir סַנְחֵרִ֤יב rei-de sobre sobre todo arei Judá as-cavernas וַֽיִּתְפְּשֵֽׂם׃');
INSERT INTO verses VALUES (10042, 12, 18, 14, 'e-enviou חִזְקִיָּ֣ה rei-de יְהוּדָה a rei-de Aššur dizendo לֵאמֹ֤ר ׀ pecado-eu volta de-sobre-mim a que dareis sobre-mim אֶשָּׂ֑א e-ele-postou rei-de אַשּׁ֜וּר sobre chizqiyah rei-de Judá três ouro k-khar- prata e-trinta ouro ouro');
INSERT INTO verses VALUES (10043, 12, 18, 15, 'E-colocou chizqiyah a todo o-ouro ha-nimtsa'' casa-de yhwh e nas-áreas casa o rei');
INSERT INTO verses VALUES (10044, 12, 18, 16, 'em-o-tempo a aquela kitzatz חִזְקִיָּ֜ה a dalot yhwh yhwh e-a ha-omnot que tsippah חִזְקִיָּ֖ה rei Judá e-colocou-os para-rei-de אַשּׁוּר׃');
INSERT INTO verses VALUES (10045, 12, 18, 17, 'e-enviou rei-de [אֶת־תַּרְתָּ֥ן] a [׀] e-[OBJ] chefe-de [אֶל־הַמֶּ֧לֶךְ] e-[OBJ] chefe-de [כָּבֵ֖ד] de [וַֽיַּעֲלוּ֙] a o-rei [וַיַּעֲל֣וּ] [וַיָּבֹ֗אוּ] [וַיַּֽעַמְדוּ֙] Jerusalém [הַבְּרֵכָ֣ה] e-vieram Jerusalém e-subiram e-vieram e-pararam que');
INSERT INTO verses VALUES (10046, 12, 18, 18, 'וַֽיִּקְרְאוּ֙ a o-rei e-ele-saiu a-para-eles אֶלְיָקִ֥ים filho-de חלקייהו que sobre a-casa ושבנה o escriba ויואח filho-de asaf o-mencionador-versículo');
INSERT INTO verses VALUES (10047, 12, 18, 19, 'E-disse para-eles chefe-de [אִמְרוּ־נָ֖א] [אֶל־חִזְקִיָּ֑הוּ] por-favor a [הַגָּדוֹל֙] assim disse o-rei a-grande rei Assur [בָּטָֽחְתָּ] que');
INSERT INTO verses VALUES (10048, 12, 18, 20, 'dis-e-stu somente palavra-de lábios-de-duas conselho וגבראה para-a-guerra agora que quem te-te-batechta porque te-maredhta em-mim');
INSERT INTO verses VALUES (10049, 12, 18, 21, 'agora eis batacht para-te sobre de-escante o-compre o-correto o-este sobre Egito que ele-te-samar homem sobre-ele וּבָ֥א com-suas-mãos e a cavidade assim faráoh rei-de Egito para-todo os que se acham em segurança sobre-ele');
INSERT INTO verses VALUES (10050, 12, 18, 22, 'וְכִי־ תֹאמְר֣וּן a-mim a yhwh Elohim-nosso nos temos confiado porventura-não ele que ele tirou E-disse a dos seus templos e-a de suas oferendas E-disse para-Judá וЛИרושׁאלם diante-de o altar esta vai adorar em-Jerusalém');
INSERT INTO verses VALUES (10051, 12, 18, 23, 'e-agora e se envolveu por-favor a Adonai a rei a-ti e deu-lhe para-ti אלף-ע''ח cavalos a-ti עהת-מי para-dar a-ti רבום-י sobre-eles');
INSERT INTO verses VALUES (10052, 12, 18, 24, '[וְאֵ֣יךְ] [תָּשִׁ֗יב] a face-de Paate um servos-de Adonai [הַקְּטַנִּ֑ים] [וַתִּבְטַ֤ח] a-ti sobre Egito [וּלְפָרָשִֽׁים]');
INSERT INTO verses VALUES (10053, 12, 18, 25, 'agora [הֲמִבַּלְעֲדֵ֣י] yhwh [עָלִ֛יתִי] sobre o-lugar este yhwh disse disse folhas-de [עַל־הָאָ֥רֶץ] sobre a-terra');
INSERT INTO verses VALUES (10054, 12, 18, 26, 'E-disse [אֶלְיָקִ֣ים] filho-de [וְשֶׁבְנָ֨ה] [וְיוֹאָ֜ח] [אֶל־רַב־שָׁקֵ֗ה] a chefe-de [אֲרָמִ֔ית] que por-favor a [וְאַל־תְּדַבֵּ֤ר] [עִמָּ֙נוּ֙] porque [בְּאָזְנֵ֣י] [הָעָ֔ם] e-a [עַל־הַחֹמָֽה] que sobre');
INSERT INTO verses VALUES (10055, 12, 18, 27, 'E-disse a-eles chefe-de שָׁקֵ֗ה הַעַ֨ל teu-senhor e-para-ti enviou-me Adonai para-falar a as-palavras estes porventura-não sobre os-homens os-habitam sobre a-muralha para-comer וְלִשְׁתּ֛וֹת a com-vos');
INSERT INTO verses VALUES (10056, 12, 18, 28, '[וַֽיַּעֲמֹד֙] chefe-de E-chamou E-chamou [יְהוּדִ֑ית] grande E-disse e-falou E-disse [הַגָּד֖וֹל] palavra-de o-rei rei');
INSERT INTO verses VALUES (10057, 12, 18, 29, 'assim disse o-rei a a-vós para-vocês [כִּי־לֹ֣א] porque não [אֶתְכֶ֖ם] [מִיָּדֽוֹ]');
INSERT INTO verses VALUES (10058, 12, 18, 30, 'e-a confie a-vos fortaleza dizendo yhwh dizendo yhwh salve-nos yhwh e-não forneça a a-cidade a-esta na-mão-de rei אַשּׁוּר׃');
INSERT INTO verses VALUES (10059, 12, 18, 31, 'a ouvireis que fortaleza disse assim disse rei Assiria façam comigo bênção e saiam a-mim e comeiem homem-de seus-olhos e-homem suas-macieiras e bebêem homem águas-de no seu');
INSERT INTO verses VALUES (10060, 12, 18, 32, 'até vindo e-eu-tomarei a-vós a terra como a vossa terra terra terra pão terra terra e vinhas terra oliveira figo e mel e vivam e-não morrem e-a ouvireis dizendo yhwh porque yasitt a-vós para-dizer yhwh yatzilenu:');
INSERT INTO verses VALUES (10061, 12, 18, 33, 'ha-hahtzal hitzilu Elohim-de as-nações homem a terra-dele de-mão-de rei אַשּׁוּר׃');
INSERT INTO verses VALUES (10062, 12, 18, 34, 'aiye Elohim-de hamat ve-arpad aiye Elohim-de sarpavyim henaa וְעִוָּ֑ה porque הִצִּ֥ילוּ a שרֹן מִיָּדִֽי׃');
INSERT INTO verses VALUES (10063, 12, 18, 35, 'quem em-todo Elohim-de [אֲשֶׁר־הִצִּ֥ילוּ] que [מִיָּדִ֑י] a yhwh [אֶת־יְרוּשָׁלַ֖͏ִם] porque yhwh a');
INSERT INTO verses VALUES (10064, 12, 18, 36, '[וְהֶחֱרִ֣ישׁוּ] o-povo e-não ele ele palavra porque [הִ֛יא] dizendo não [תַעֲנֻֽהוּ] não');
INSERT INTO verses VALUES (10065, 12, 18, 37, 'E-veio [אֶלְיָקִ֣ים] filho-de [אֲשֶׁר־עַל־הַ֠בַּיִת] que sobre [וְיוֹאָ֨ח] [בֶּן־אָסָ֧ף] [הַמַּזְכִּ֛יר] [אֶל־חִזְקִיָּ֖הוּ] filho-de [בְגָדִ֑ים] [וַיַּגִּ֣דוּ] a-ele Ezequias [רַב־שָׁקֵֽה]');
INSERT INTO chapters VALUES (332, 12, 19, 37);
INSERT INTO verses VALUES (10066, 12, 19, 1, 'e-houve כישמע o-rei חזקיהו וַיִּקְרַע a com suas vestes וַיִּתְכַּס בַּשָּׂק E-veio yhwh yhwh');
INSERT INTO verses VALUES (10067, 12, 19, 2, '[וַ֠יִּשְׁלַח] a [אֲשֶׁר־עַל־הַבַּ֜יִת] que sobre e-[OBJ] [זִקְנֵ֣י] [הַכֹּֽהֲנִ֔ים] e-[OBJ] [בַּשַּׂקִּ֑ים] [אֶל־יְשַֽׁעְיָ֥הוּ] [הַנָּבִ֖יא] [בֶּן־אָמֽוֹץ] a filho-de');
INSERT INTO verses VALUES (10068, 12, 19, 3, 'e-disseram a-ele assim disse חִזְקִיָּ֔הוּ dia-de צָרָ֧ה וְתוֹכֵחָ֛ה o-dia o-dia que porque filhos filhos até não-havia וְכֹ֥חַ não-havia לְלֵדָֽה׃');
INSERT INTO verses VALUES (10069, 12, 19, 4, 'אוּלַ֡י יִשְׁמַע֩ yhwh Elohim-teu com todo palavras-de chefe-de שָׁקֵ֗ה que שְׁלָח֨וֹ rei-de Aššur adonai-o para escarnecer vida viveu e provará nos palavras que yhwh yhwh teu-Elohim e levantará oração por-causa-de a remanescente aquela que foi achada');
INSERT INTO verses VALUES (10070, 12, 19, 5, 'e-vieram servos o-rei Ezequias a Yeshayáhu');
INSERT INTO verses VALUES (10071, 12, 19, 6, 'E-disse a-eles Yeshayáhu assim תֹאמְר֖וּנ a אֲדֹֽנֵיכֶ֑ם assim disse yhwh a de-diante-de מִפְּנֵ֤י הדברים֙ que שָׁמַ֔עְתָּ que גִּדְּפ֛וּ נַעֲרֵ֥י rei-de Assíria de-mim');
INSERT INTO verses VALUES (10072, 12, 19, 7, 'eis-me deu nele espírito e ouvi obediência וְשָׁ֣ב לְאַרְצ֑וֹ וְהִפַּלְתִּ֥יו com-a-espada na-sua-terra');
INSERT INTO verses VALUES (10073, 12, 19, 8, '[וַיָּ֙שָׁב֙] chefe-de [וַיִּמְצָא֙] [אֶת־מֶ֣לֶךְ] a rei Assíria que sobre que porque ouviu porque');
INSERT INTO verses VALUES (10074, 12, 19, 9, 'E-ouviu a תרחקה dizendo eis sair eis יצאה para-lutar contigo e-ele-voltou e-enviou dizendo a Ezequias para-dizer');
INSERT INTO verses VALUES (10075, 12, 19, 10, 'assim תאמרון a חזקיהוּ dizendo Judá dizendo a tu teu-Elohim que dizendo não nele dizendo não תנתן Jerusalém na-mão-de rei אַשּׁוּר׃');
INSERT INTO verses VALUES (10076, 12, 19, 11, 'eis tu tu a que עשו reis-de אשׁור para-todo a-terras: להחריםם e-tu תינצל׃');
INSERT INTO verses VALUES (10077, 12, 19, 12, '[הַהִצִּ֨ילוּ] eles Elohim-de [הַגּוֹיִם֙] que [שִׁחֲת֣וּ] [אֲבוֹתַ֔י] a [וְאֶת־חָרָ֑ן] e-[OBJ] [וּבְנֵי־עֶ֖דֶן] [אֲשֶׁ֥ר] [בִּתְלַאשָּֽׂר] que');
INSERT INTO verses VALUES (10078, 12, 19, 13, 'אַיּ֤וֹ rei-de חֲמָת֙ e-rei אַרְפָּ֔ד e rei para a cidade סְפַרְוָ֑יִם deitou-se e foi');
INSERT INTO verses VALUES (10079, 12, 19, 14, 'E-tomou Cezíah a os livros de-mão-de os-mensageiros e os leu e-subiu yhwh yhwh e os explicou Ezequias yhwh yhwh');
INSERT INTO verses VALUES (10080, 12, 19, 15, 'e-ele-orou Cezíah diante-de yhwh E-disse yhwh Elohim-de Israel habitou os-querubins você- ele הָֽאֱלֹהִים a-todo para-todo a-terra tu tu oashtata a os-céus e-a a-terra');
INSERT INTO verses VALUES (10081, 12, 19, 16, 'e levantou-se yhwh seu-ouvido e-ouviu פְּקַ֧ח yhwh yhwh e-vê-se e-ouvires a palavras-de Sancarív que ele-enviou-o para-desafiá-lo Elohim viveu');
INSERT INTO verses VALUES (10082, 12, 19, 17, 'realmente yhwh e-destruíram reis-de Assuér a as-nações e-a terr-os');
INSERT INTO verses VALUES (10083, 12, 19, 18, 'e-dê-los a Elohim-deles que não não Elohim que porque se árvore יְדֵֽי־ homem árvore e pedra e destruí-los:');
INSERT INTO verses VALUES (10084, 12, 19, 19, 'e-agora yhwh nosso-Elohim salvai-nos por-favor imediatamente dele e saibam todo a-terra que tu yhwh yhwh Elohim apenas de ti:');
INSERT INTO verses VALUES (10085, 12, 19, 20, 'e-enviou Isaías filho-de Amots dizendo Ezequias yhwh assim disse yhwh Elohim-de Israel que oraistei-me a-mim a Sancheriv rei-de Assíria shama''ti');
INSERT INTO verses VALUES (10086, 12, 19, 21, 'este a-palavra que yhwh yhwh sobre-ele a-ti a ti a-ti para-ti virgem filha-de Sião אחריך cabeça soltou-a filha-de Jerusalém');
INSERT INTO verses VALUES (10087, 12, 19, 22, 'a quem humilhaste-me וְגִדַּ֔פְתָּ e-sobre quem הֲרִימ֣וֹתָ קּ֑וֹל e-ela-alçou-a מָר֛וֹם olhos-teus sobre santo Israel');
INSERT INTO verses VALUES (10088, 12, 19, 23, 'na-mão-de מַלְאָכֶיךָ֮ honoraste-me Adonai e-disse E-disse eu עָלִ֛יתִי מְר֥וֹם as-montanhas ירכתי Líbano וְאֶכְרֹ֞ת קוֹמַ֤ת אֲרָזָיו֙ מִבְח֣וֹר בְּרֹשָׁ֔יו וְאָב֙וֹאָה֙ מְלוֹן קִצֹּ֔ה floresta כַּרְמִלּֽוֹ׃');
INSERT INTO verses VALUES (10089, 12, 19, 24, 'eu קַ֔רְתִּי וְשָׁתִ֖יתִי águas estrangeiros וְאַחְרִב֙ com-a-palma- פְּעָמַ֔י todo יְאֹרֵ֥י מַזָּר׃');
INSERT INTO verses VALUES (10090, 12, 19, 25, 'acaso-nao שָׁמַעְתָּ לְמֵֽרָחוֹק֙ aquela fiz oriente ao-norte e a formaste agora levaste-a e se torne para fazer tremer galés nictímines cidades nas rochas,:');
INSERT INTO verses VALUES (10091, 12, 19, 26, 'וְיֹֽשְׁבֵיהֶן֙ וְיֹֽשְׁבֵיהֶן capitais de mão חַ֖תּוּ e se envergonharam היוּ erva שַׂדֶה וִירַק דֶשֶא חֲצִיר גָּגּוֹת וּשְׁדֵפָ֖ה diante-de קָמָה׃');
INSERT INTO verses VALUES (10092, 12, 19, 27, '[וְשִׁבְתְּךָ֛] [וְצֵאתְךָ֥] [וּבֹאֲךָ֖] [יָדָ֑עְתִּי] e-[OBJ] [הִֽתְרַגֶּזְךָ֥] a-mim');
INSERT INTO verses VALUES (10093, 12, 19, 28, 'porque הִתְרַגֶּזְךָ֣ a-mim וְשַׁאֲנַנְךָ֖ subir בְאָזְנָ֑י e colocarei חַחִ֜י בְּאַפֶּ֗ךָ וּמִתְגִּי֙ בִּשְׂפָתֶ֔יךָ וַהֲשִׁ֣בֹתִ֔יךָ no-caminho que בָּאתָ nela');
INSERT INTO verses VALUES (10094, 12, 19, 29, 'e-este para-ti הָא֔וֹת אָכ֤וֹל הַשָּׁנָה֙ סָפִיחַ e-no-ano a-segunda סָחִ֑ישׁ e-no-ano הַשְׁלִישִ֗ית זִרְע֧וּ וְקִצְר֛וּ וְנִטְע֥וּ כְרָמִ֖ים e comessem פריהוּמ׃');
INSERT INTO verses VALUES (10095, 12, 19, 30, 'e jazaria פליטה֣ת casa-de Judá הנישארָה שורשׁ abaixo e fez פרי para-cima');
INSERT INTO verses VALUES (10096, 12, 19, 31, 'que מירושליםִַ֙ם֙ תיצא שארית e salva de-montanha-de Sião קינאת yhwh tu-farás esta');
INSERT INTO verses VALUES (10097, 12, 19, 32, 'portanto assim yhwh yhwh a não Assíria não virá a a-cidade esta e-não יורה nome /DDD e-não JQKDMMNNH MGN e-não יִשְׁפֹּ֥ךְ sobre-ela SLLH');
INSERT INTO verses VALUES (10098, 12, 19, 33, 'no-caminho que vira בָּ֣הּ YSHVB e-a não esta não vira oráculo-de yhwh');
INSERT INTO verses VALUES (10099, 12, 19, 34, 'e-ganotí a a-cidade esta LHSYAH LMANI e-para-alma Davi AVDI');
INSERT INTO verses VALUES (10100, 12, 19, 35, 'e-houve na-noite aquele VYCTA anjo yhwh yhwh em-acampamento-de Assíria cem oitenta e-cinco mil e-eles-se-levantaram-cedo em-a-manhã e-eis todos eles FGRIM mortos∶');
INSERT INTO verses VALUES (10101, 12, 19, 36, 'e-ele-partiu E-andou וַיָּ֖שָׁב Sancarív rei-de Assíria e-habitou Βενινώη:');
INSERT INTO verses VALUES (10102, 12, 19, 37, 'e-houve ele adoração∶ casa-de cetro∶ Elohim∶ e Adramélux e Sarácerto matá-lo b''cherev e-elas fugiram∶ terra Araart terra אֵֽסַר־ Chadon filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (333, 12, 20, 21);
INSERT INTO verses VALUES (10103, 12, 20, 1, 'em-os-dias aqueles chalah Ezequias para morrer E-veio a-ele Yeshayahu filho-de Amots E-disse a-ele a-ele yhwh disse yhwh que lebetekha tu morreu tu e-não tichye:');
INSERT INTO verses VALUES (10104, 12, 20, 2, 'vayassab a sua-face a haqir dizendo a yhwh para-dizer');
INSERT INTO verses VALUES (10105, 12, 20, 3, 'Anah yhwh lembra-de por-favor a que andei em-te בֶּֽאֱמֶת֙ uvelabbav paz vehatov nos-teus-olhos faça וַיֵּ֥בְךְּ Ezequias porque grande');
INSERT INTO verses VALUES (10106, 12, 20, 4, 'e-houve Yeshayahu não sair a ticná e-palavra-de yhwh foi ser a-ele');
INSERT INTO verses VALUES (10107, 12, 20, 5, 'volta e dirijais a a força dele nigd- yhwh assim disse yhwh Elohim-de Davi pai-teu ouvi a tphilá-teka para-ti no-dia dim`á-teka eis-me rofe yhwh no-dia o-terceiro ta`ale casa yhwh');
INSERT INTO verses VALUES (10108, 12, 20, 6, 'vesofte sobre os-se-u-dias cinco dez ano ve-mikaf rei-de ʾaššur atzilkeka e-a a-cidade esta ve-ganotie sobre a-cidade esta para mim e-para-alma Davi servo:');
INSERT INTO verses VALUES (10109, 12, 20, 7, 'E-disse יְשַֽׁעְיָ֔הוּ peguem davelãt tãenim e pegaram e-os-colocaram sobre a sãin e-viveu-verso-final');
INSERT INTO verses VALUES (10110, 12, 20, 8, 'E-disse Chizqiyahu a Yeshayahu que sinal yhwh curará yhwh no-dia וְעָלִ֛יתִי no-dia yhwh casa yhwh');
INSERT INTO verses VALUES (10111, 12, 20, 9, 'E-disse יְשַׁעְיָ֗הוּ este para-ti הָאוֹת֙ yhwh que porque yhwh yhwh a a palavra andar palavra andou הַצֵּל֙ dez מַֽעֲל֔וֹת se ישוב dez מַֽעֲל֔וֹת');
INSERT INTO verses VALUES (10112, 12, 20, 10, 'E-disse יְחִזְקִיָּ֔הוּ נָקֵ֣ל לַצֵּ֔ל para se inclinar dez מַעֲל֑וֹת não porque יָשׁוּב הַצֵּ֛ל אֲחֹרַנִּ֖ית dez מַעֲלֽוֹת׃');
INSERT INTO verses VALUES (10113, 12, 20, 11, 'E-chamou יְשַׁעְיָ֥הוּ o-profeta a yhwh e-ele-estabeleceu a הַצֵּ֗ל בַּֽ֠מַּעֲלוֹת que יָרְדָ֜ה בְּמַעֲל֥וֹת אָחָ֛ז אֲחֹֽרַנִּ֖ית dez maalot:');
INSERT INTO verses VALUES (10114, 12, 20, 12, 'em-o-tempo ha-hi enviou bar-odakh bal-adan filho-de bal-adan rei-de Babilônia sefarim que a que porque ouviu porque chala chizkiyyahu:');
INSERT INTO verses VALUES (10115, 12, 20, 13, 'E-ouviu al-eyhem chizkiyyahu e levantou-se a todo casa nós seremos feridos a o prata e-a o ouro e-a as báseis e-את óleo התוב e-את casa utensílios-dele e-a todo que foi achado em suas arcações não foi palavra que não e mostrou-se a sua força em-casa-dele e-em-todo sua soberania:');
INSERT INTO verses VALUES (10116, 12, 20, 14, 'E-veio Yesayáhu o-profeta a o-rei E-disse a-ele a-ele que Amarū os-homens estes uMeyain virao a-ti E-disse חִזְקִיָּ֔הוּ da-terra-de Roká entraram Mibavel');
INSERT INTO verses VALUES (10117, 12, 20, 15, 'E-disse que Ra''u bBeiteka E-disse Chizqiyáhu a todo que bBeiti Ra''u não foi palavra que não הִרְאִיתִ֖ם בְּאֹצְרֹתָֽי׃');
INSERT INTO verses VALUES (10118, 12, 20, 16, 'E-disse [יְשַׁעְיָ֖הוּ] a [שְׁמַ֖ע] ouviu yhwh');
INSERT INTO verses VALUES (10119, 12, 20, 17, 'eis [יָמִ֣ים] [בָּאִים֒] [וְנִשָּׂ֣א] todo que [בְּבֵיתֶ֗ךָ] e-que [אָצְר֧וּ] [אֲבֹתֶ֛יךָ] até o-dia este [לֹֽא־יִוָּתֵ֥ר] não disse yhwh disse yhwh');
INSERT INTO verses VALUES (10120, 12, 20, 18, 'וּמִבָּנֶ֜יךָ que יֵצְאוּ de-ti que תּוֹלִיד וְהָיוּ֙ סָרִיסִים e-sejam rei Babilônia');
INSERT INTO verses VALUES (10121, 12, 20, 19, 'E-disse חִזְקִיָּהוּ a bom bom palavra-de yhwh E-disse falaste E-disse acaso-nao será shalom e-verdade será בְיָמָי׃');
INSERT INTO verses VALUES (10122, 12, 20, 20, 'e-resto-de דְּבָרַי חִזְקִיָּהוּ e-todo גְּב֣וּרָת֔וֹ e-que fez a e-trouxe e-a הַתְּעָלָ֔ה E-veio a as-águas a-cidade não-é eles escritos sobre livro palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (10123, 12, 20, 21, 'e-ele-deitou Ezequias com pais-seus e-reinou Manassés seu-filho em-lugar-dele');
INSERT INTO chapters VALUES (334, 12, 21, 26);
INSERT INTO verses VALUES (10124, 12, 21, 1, 'filho-de duas-de quinze ano מְנַשֶּׁ֣ה em-seu-reinado e-cinquenta e cinco ano rei em-Jerusalém sua-mãe אִמּ֖וֹ chéfzí- em-ela');
INSERT INTO verses VALUES (10125, 12, 21, 2, 'E-fez o-mal aos-olhos-de yhwh kótóʿávot- as-nações que ele-desapossou yhwh de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (10126, 12, 21, 3, 'e-voltou E-edificou a havvámot- que íbbad seu-pai seu-pai E-levantou mizbókhôt la-bal E-fez ʾăšérāh como fez Acabe rei Israel e-abaixou-se para-todo exercito eles váyaʿabód eles');
INSERT INTO verses VALUES (10127, 12, 21, 4, 'úvaná mizbókhôt na-casa-de yhwh que disse yhwh birushalaim ʾāśîm a שְׁמִֽי׃');
INSERT INTO verses VALUES (10128, 12, 21, 5, 'E-edificou מִזְבְּח֖וֹת para-todo exercito os-céus בִּשְׁתֵּ֖י חַצְר֥וֹת casa-de yhwh');
INSERT INTO verses VALUES (10129, 12, 21, 6, 'וְהֶעֱבִ֤יר a filho-o no-fogo וְעוֹנֵ֣ן וְנִחֵ֔שׁ e fizer א֖וֹב וְיִדְּעֹנִ֑ים הִרְבָּ֗ה para-fazer o-mal yhwh yhwh לְהַכְעִֽיס׃');
INSERT INTO verses VALUES (10130, 12, 21, 7, 'e pôs a figura a-asereia que fez em-a-casa disse yhwh yhwh a Davi e-a Shelomoh be-no no templo o-este de-toda que eu escolhi de-todo tribos-de Israel eu farei a nome-meu para-eternidade');
INSERT INTO verses VALUES (10131, 12, 21, 8, 'e-não e reunirei para mostrar רגל Israel de a-terra dei dei aos pais somente se guardem לַעֲשׂ֗וֹת como-tudo que mandamentos; e-para-todo- eles que ordenou eles עבדי Moisés');
INSERT INTO verses VALUES (10132, 12, 21, 9, 'e-não e ouvirão e provou מְנַשֶּׁה para fazer a o mal de [הִשְׁמִ֣יד] yhwh de-diante-de yhwh de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (10133, 12, 21, 10, 'e-ele-falou yhwh pela-mão-de seus-servos dizendo para-dizer');
INSERT INTO verses VALUES (10134, 12, 21, 11, 'porque que fez Manassés rei-de Judá [הָאֵ֔לֶּה] estes de-toda de-todo que fizeram o-amorreu que diante-dele e pecou também a יְהוּדָה por seus ídolos');
INSERT INTO verses VALUES (10135, 12, 21, 12, 'portanto assim yhwh yhwh Elohim-de Israel eis-me que traria maldade sobre Jerusalém e Judá que todo nos faria cair duas-de ouvidos-seus');
INSERT INTO verses VALUES (10136, 12, 21, 13, 'e estenderei sobre Jerusalém a קָו Samaria e-a de peso casa Acabe e desfizerei a Jerusalém quando será destruída a a ardência destruição e virrei sobre suas-faces:');
INSERT INTO verses VALUES (10137, 12, 21, 14, 'e despejarei a remanescente minha herança e lançareis na-mão-de os seus inimigos e-sejam para zombar e para escarnecer para-todo inimigos-de-eles');
INSERT INTO verses VALUES (10138, 12, 21, 15, 'porque que asau a o-mal diante de mim e-foram macheisim a-mim de o-dia que sairam pais-deles o-dia e-até o-dia a-esta');
INSERT INTO verses VALUES (10139, 12, 21, 16, 'e-também sangue justo derramou מְנַשֶּׁה muito muito até que enchei a Jerusalém a boca na face só de-sua-iniquidade que a-iniquidade a Judá yhwh o-mal em-olhos-de yhwh');
INSERT INTO verses VALUES (10140, 12, 21, 17, 'e-resto-de דְּבָרַי מְנַשֶּׁה e-todo que fez e-seu-penitente que pecou não-é eles escritos sobre livro palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (10141, 12, 21, 18, 'e-deitou-se מְנַשֶּׁה com seus-pais e-foi-enterrado em-para-o casa-dele em-para-o Ozã e-reinou Amom filho-seu em-lugar-dele');
INSERT INTO verses VALUES (10142, 12, 21, 19, 'filho-de vinte וּשְׁתַּ֤יִם ano אָמ֣וֹן no seu reinado e-duas dois rei em-Jerusalém sua-mãe sua-mãe restituídas filha-de tricoteira de será-beneficiada:');
INSERT INTO verses VALUES (10143, 12, 21, 20, 'E-fez o-mal aos-olhos-de yhwh como fez Manassés seu-pai');
INSERT INTO verses VALUES (10144, 12, 21, 21, 'E-andou em-todo o-caminho seu-pai andou seu-pai e serviu-se lavrar seu-pai que a-eles pai-dele e-prostrou-se para-eles');
INSERT INTO verses VALUES (10145, 12, 21, 22, 'e abandonou a yhwh Elohim-de pais-seus andar andou yhwh yhwh');
INSERT INTO verses VALUES (10146, 12, 21, 23, 'e ligaram servos-de Aomôn sobre-ele e mataram a o-rei no seu lar:');
INSERT INTO verses VALUES (10147, 12, 21, 24, 'e-golpeou com a-terra a todo os que ligavam sobre o-rei Aomôn e reinaram com a-terra a Josias filho-dele em-lugar-dele');
INSERT INTO verses VALUES (10148, 12, 21, 25, 'e-resto-de palavras-de Aomôn que fez não-é eles escritos sobre livro palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (10149, 12, 21, 26, 'ele ele no jardim- עוזיא e-reinou Josias seu-filho em-lugar-dele');
INSERT INTO chapters VALUES (335, 12, 22, 20);
INSERT INTO verses VALUES (10150, 12, 22, 1, 'filho-de oito ano [בְמָלְכ֔וֹ] em-seu-reinado [וְאַחַת֙] [שָׁנָ֔ה] ano rei em-Jerusalém sua-mãe sua-mãe [בַת־עֲדָ֖יָה] [מִבָּצְקַֽת]');
INSERT INTO verses VALUES (10151, 12, 22, 2, 'E-fez o-reto aos-olhos-de yhwh E-andou em-todo caminho seu-pai pai-dele e-não apartou direita e-esquerda');
INSERT INTO verses VALUES (10152, 12, 22, 3, 'e-houve בשמונה dez ano ao-rei יוashiyahu enviou o-rei a שפן filho-de אצלייהו filho-de yhwh dizendo casa yhwh para-dizer');
INSERT INTO verses VALUES (10153, 12, 22, 4, 'folhas-de a חלקייהו o-sacerdote a-grande והתים a a-prata yhwh casa yhwh que אספו שמרי הסף de-a o-povo');
INSERT INTO verses VALUES (10154, 12, 22, 5, 'sobre mão feitores a-obra המשופדים yhwh ויתנו a-ele yhwh הַמְּלָאכָה ele na-casa-de yhwh לחזק בדק yhwh');
INSERT INTO verses VALUES (10155, 12, 22, 6, 'לחרשים e para os filhos e para as paredes e para comprar árvores e pedras monumento para fortalecer a a-casa');
INSERT INTO verses VALUES (10156, 12, 22, 7, 'somente não será contado com-elas-os o dinheiro o doado que אֲדַמָּ eles בְּאֵמוּנָ֖ה eles עֹשִׂ֣ים׃');
INSERT INTO verses VALUES (10157, 12, 22, 8, 'E-disse חִלְקִיָּ֖הוּ o-sacerdote a-grande sobre שַׁפַּ֣ן הַסּוֹפֵ֔ר סֵ֖פֶר הַתּוֹרָ֛ה מָצָ֖אתִי yhwh E-colocou E-deu חִלְקִיָּ֧ה a o sefer a shafan e o chamou shaphan;');
INSERT INTO verses VALUES (10158, 12, 22, 9, 'E-veio shafan o sefer a o-rei ele-assentou-se a E-disse palavra E-disse elevem-se teus-servos a a-prata que estava no beit e o entregaram sobre mão yhwh a-obra os mofkedim casa yhwh');
INSERT INTO verses VALUES (10159, 12, 22, 10, 'e contou שָׁפָן הַסּוֹפֵר para-o-rei dizendo סֵפֶר dar a-mim חִלְקִיָּה o-sacerdote וַיִּקְרָאֵהוּ שָׁפָן diante-de o rei');
INSERT INTO verses VALUES (10160, 12, 22, 11, 'e-houve כשמע o-rei a palavras-de livro a-Torah e rasgou a suas roupas:');
INSERT INTO verses VALUES (10161, 12, 22, 12, 'E-ordenou o-rei a חִלְקִיָּה הַכֹּהֵן e-a Aquicam filho-de שָׁפָן e-a עַכְבּוֹר filho-de Michaiah e-את Shaphan dizendo e-a asaya servo- o-rei para-dizer');
INSERT INTO verses VALUES (10162, 12, 22, 13, 'vovem busquem a yhwh comigo e-atrás-de- o-povo e para todo Judá sobre palavras o livro yhwh este porque grande sobre yhwh que ela se estabeleceu sobre nós sobre que não ouviram אֲבֹתֵינוּ sobre palavras-de o sefer esta para-fazer conforme-toda o khatuv sobre-nós');
INSERT INTO verses VALUES (10163, 12, 22, 14, 'E-andou chilikiyahu o sacerdote va''achikam ve''akavor veshafan va''asayah a chulda a nebiya a eshet שלום filho-de תִּקְוָה filho-de חַרְחַס guardião-de os-vestidos e-ela יֹשֶׁ֥בֶת birushalaim בַּמִּשְׁנֶ֑ה וַֽיְדַבְּר֖וּ a-ela');
INSERT INTO verses VALUES (10164, 12, 22, 15, 'E-disse a-eles assim yhwh yhwh Elohim-de Israel אִמְר֣וּ para-o homem que enviou vós para-mim');
INSERT INTO verses VALUES (10165, 12, 22, 16, 'assim disse yhwh eis-me מֵבִ֥יא maldade a o-lugar este e-sobre יֹֽשְׁבָ֑יו a todo chamou ha-sefer que chamou rei Judá');
INSERT INTO verses VALUES (10166, 12, 22, 17, 'debaixo que עֲזָב֗וּנִי וַֽיְקַטְּרוּ֙ para-Elohim outros para-que que-me-ira em-todo obra-de suas-mãos e-sairá minha-ira no-lugar este e-não tikbeh');
INSERT INTO verses VALUES (10167, 12, 22, 18, 'e-a rei Judá aquele-q-dispõe vos inquirir a yhwh a-ele dirão-vós yhwh assim disse yhwh Elohim-de Israel as-palavras que ouvirás');
INSERT INTO verses VALUES (10168, 12, 22, 19, 'porque suave- לבבך ותינעה de-diante-de yhwh בשמעך que דברתי sobre המקום o-este e-sobre ישבו para-ser לשם ולקללה ותקרעה a בגדיך eu diante-de-mim e-também eu ouvi oráculo-de yhwh');
INSERT INTO verses VALUES (10169, 12, 22, 20, 'portanto eis-me אֲסִיפְךָ sobre אֲבוֹתֶיךָ וְנִאֱסַפְתָּ a קִבְרֹתֶיךָ בְּשׁוֹלֵם e-não תִרְאֶינָה os olhos em-todo הָרַעָה que eu מֵבִיא sobre o-lugar esta וַיְשׁוּבוּ a o-rei palavra');
INSERT INTO chapters VALUES (336, 12, 23, 37);
INSERT INTO verses VALUES (10170, 12, 23, 1, 'e-enviou o-rei וַיְאַסְפוּ a-ele todo anciãos-de Judá Jerusalém:');
INSERT INTO verses VALUES (10171, 12, 23, 2, 'e-subiu o-rei casa-de yhwh e-todo homem יְהוּדָה e-todo yoshevei Jerusalém com-ele e-os-sacerdotes e os profetas E-chamou o-povo para pequeno e-até grande E-chamou em suas orelhas yhwh todo palavras-de livro a-aliança yhwh em-casa-de yhwh');
INSERT INTO verses VALUES (10172, 12, 23, 3, 'e-ficou-em-pé o-rei sobre o poste vayikrot a a aliança yhwh yhwh para andar yhwh yhwh וְלִשְׁמֹ֨ר suas mandamentos e-a suas testemunhos e-a seus estatutos em-todo coração e-em-todo alma para erigir a palavras-de a aliança esta os escritos sobre o livro esta e-estabeleceu todo o-povo na aliança:');
INSERT INTO verses VALUES (10173, 12, 23, 4, 'E-ordenou o-rei a Chilkiyyahu o-sacerdote o-grande e-a כֹּהֲנֵ֣י o segundo e-a os guardiões yhwh para trazer do templo yhwh a todo os recipientes os feitos para Baal e para Asherah e-a-todos exercito os-céus e os queimou do lado de fora para Jerusalém em desertos Cedrom e-levará a sua cinzas casa-de El');
INSERT INTO verses VALUES (10174, 12, 23, 5, 'e destruiu a as carmas que e deram reis-de Judá e queimou em as baalot em-cidades-de Judá e mesibbe Jerusalém e-a os queimadores la-bal ao sol e à lua e às estrelas e-a-todos exército-de os-céus');
INSERT INTO verses VALUES (10175, 12, 23, 6, 'e saiu a a asherah yhwh yhwh do lado de fora para Jerusalém a vale-de Cedrom e-ele-queimou ela BENACHAL kidron e fez-se para pó e lançou a o pó dela sobre um sepulcro filhos-de o-povo');
INSERT INTO verses VALUES (10176, 12, 23, 7, 'e entrou a nas tuas as santidades que yhwh yhwh que as-mulheres orgãos nome casarim para assemelhar-se');
INSERT INTO verses VALUES (10177, 12, 23, 8, 'e-trouxe a todo os-sacerdotes מערי Judá e contaminou a as baamas que queimaram - lá-baixo os-sacerdotes de-abaixo até poço sete e destruíram - a nas cavernas as portas que entrada-de porta-de יְהוֹשֻׁעַ príncipe-de a-cidade que sobre esquerda homem em-porta-de a-cidade');
INSERT INTO verses VALUES (10178, 12, 23, 9, 'somente não ya''alú כֹּהֲנֵ֣י as baamas a yhwh yhwh que porque se no-meio-de não-fermentados no-meio-de irmãos-deles');
INSERT INTO verses VALUES (10179, 12, 23, 10, 'e contaminaram - a a tofa que nos para-não para não para-transpor homem a seu-filho e-a filha-dele com-fogo para o rei:');
INSERT INTO verses VALUES (10180, 12, 23, 11, 'e se calou a os-cavalos que deram reis-de Judá ao sol de entrada casa-de yhwh a para a dado- rei o eunuco que nas carroças e-a מרכבות a-ele queimar em-a-chama');
INSERT INTO verses VALUES (10181, 12, 23, 12, 'e-com הַמִּזְבְּח֡וֹת que sobre הַגָּג֩ עֲלִיַּ֨ת Acaz que fizeram reis-de Judá e-a הַֽמִּזְבְּחוֹת֙ que fez בִּשְׁתֵּ֛י חַצְר֥וֹת casa-de yhwh נָתַ֣ץ o-rei e-correu de-lá וְהִשְׁלִ֥יךְ a עֲפָרָ֖ם a ribeiro-de Kidron:');
INSERT INTO verses VALUES (10182, 12, 23, 13, 'e-a as baamoth que sobre face-de Jerusalém que do lado direito para-monte-de edificar que construiu Salomão rei-de Israel para Ashtaroth escárnio da Zidon e a Khemos escárnio Moabe e Milcom abominação-de filhos-de Amom טִמֵא o rei');
INSERT INTO verses VALUES (10183, 12, 23, 14, '[וְשִׁבַּר֙] a [וַיִּכְרֹ֖ת] [אֶת־הָאֲשֵׁרִ֑ים] a [אֶת־מְקוֹמָ֖ם] [עַצְמ֥וֹת] homem homem');
INSERT INTO verses VALUES (10184, 12, 23, 15, 'e-tambem a o-mizbeach que em-Betel El הַבָּמָה que fez Jeroboao filho-de נְבָת também הֶחֱטִיא a Israel também a o mizbêa aquele e-a a bamá natazs vayishruf a a bamá hedak lê''afar e-queimará ʾăšerah׃');
INSERT INTO verses VALUES (10185, 12, 23, 16, 'e-ele-virou joashiyahu E-viu a as kvarim que nome E-tomou e-enviou E-tomou a as-atzmot de as-kvarim yhwh sobre chamou e-te-ma-e-hu conforme-a-palavra-de yhwh chamou chamou homem os-Elohim que chamou a as-palavras as estas');
INSERT INTO verses VALUES (10186, 12, 23, 17, 'E-disse quanto o-tsion o-este que eu viu e-disseram a-ele homens-de a-cidade o-kver homem-de הָֽאֱלֹהִים que E-chamou de-yehuda E-chamou a hadavarim sobre que oashtata sobre o-mizbach casa-de El');
INSERT INTO verses VALUES (10187, 12, 23, 18, 'E-disse e-nichu a-ele homem a yanah asatzmot-o e-mallatu atzmotay a suas próprias o-profeta que veio mi-shomron');
INSERT INTO verses VALUES (10188, 12, 23, 19, 'e-também a todo battei habbamot que em-cidades-de shomron que asu reis-de Israel le-hacais hesisir yoashiyahu a-eles a-eles conforme-toda os-atos que fez em-Betel El');
INSERT INTO verses VALUES (10189, 12, 23, 20, 'e-ele-sacrificou a todo os-cohães as-ba-mot que nome homem os-mizbóchot e-queimou a suas próprias homem sobre-eles E-tomou Jerusalém');
INSERT INTO verses VALUES (10190, 12, 23, 21, 'E-ordenou o-rei a dizendo o-povo dizendo asu pesach a-yhwh sobre conforme-o-escrito sobre livro a-aliança a-esta');
INSERT INTO verses VALUES (10191, 12, 23, 22, 'que não foi-feito pesach este desde-dias-de os-juízes que julgaram a e-tudo dias-de יְמֵ֛י reis-de Israel e-reis-de Judá');
INSERT INTO verses VALUES (10192, 12, 23, 23, 'que se [עֶשְׂרֵה֙] dez ano ao-rei [נַעֲשָׂ֞ה] [הַפֶּ֧סַח] [הַזֶּ֛ה] este a-yhwh');
INSERT INTO verses VALUES (10193, 12, 23, 24, 'e-também a הָאֹב֣וֹת e-a הַ֠יִּדְּעֹנִים e-a הַתְּרָפִ֨ים e-a הַגִּלֻּלִ֜ים e-a todo הַשִּׁקֻּצִ֗ים que נִרְאוּ֙ em-a-terra Judá e-ir-ushalaim em-o-fogo yao-shi-yah-u para-propósito-de o-estabelecido encontrou דְּבָרַי a-torá os-escritos yhwh ha-sefer que encontrou chi-lqi-yah-u o-sacerdote casa yhwh');
INSERT INTO verses VALUES (10194, 12, 23, 25, 'e-como-ele não foi diante-dele rei que retornou a yhwh em-todo seu-lábbo e-em-todo נפשוֹ e-em-todo mê-ódoo que lei-de Moisés e-depois-dele não קָ֥ם como-ele-verso-final');
INSERT INTO verses VALUES (10195, 12, 23, 26, 'somente não retornou yhwh mê-kharóon ápoo a-grande que chára sua-ira sobre sobre todo o-keásim que hikéisisoo Mênashé:');
INSERT INTO verses VALUES (10196, 12, 23, 27, 'E-disse yhwh também a Judá de-cima-de de-sobre face-de como não-retiraria-eu a Israel e-maássti a a-cidade esta que בָּחַ֙רְתִּי֙ será Jerusalém e-a a-casa que eu-disse será nome-meu nome');
INSERT INTO verses VALUES (10197, 12, 23, 28, 'e-resto-de palavras-de יֹאשִׁיָּ֖הוּ e-todo que fez não-é eles escritos sobre livro palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (10198, 12, 23, 29, '[בְּיָמָ֡יו] subir [פַרְעֹ֨ה] [נְכֹ֧ה] rei-de [עַל־מֶ֥לֶךְ] sobre rei Assíria sobre [יֹאשִׁיָּ֙הוּ֙] [לִקְרָאת֔וֹ] E-andou o-rei [כִּרְאֹת֖וֹ] ele');
INSERT INTO verses VALUES (10199, 12, 23, 30, 'וַיַּרְכִּבֻ֨הוּ seus-servos morreu de-Migdol e-levaram-no Jerusalém e-o-enteraram-lá em-su-sua-tumba E-tomou com a-terra a Yehoáquim ele José ele debaixo seu-pai a-ele debaixo-de seu-pai');
INSERT INTO verses VALUES (10200, 12, 23, 31, 'filho-de vinte e-três ano Yehoáquim no seu reinado e-três meses rei em-Jerusalém sua-mãe sua-mãe Chamate בַּֽת־ Jeremias de-linho:');
INSERT INTO verses VALUES (10201, 12, 23, 32, 'E-fez o-mal aos-olhos-de yhwh conforme-tudo que fizeram pais-dele');
INSERT INTO verses VALUES (10202, 12, 23, 33, 'e-o-s-ter-ho-u Faraó Neco em-Ribla na-terra Chamath em-Jerusalém e-ele-deu pun-i-to sobre a-terra cem de prata ouro ouro');
INSERT INTO verses VALUES (10203, 12, 23, 34, 'e-o-m-ble-xo-u Faraó Neco a Eliaquim debaixo יוֹאשִׁיַּ֑הוּ seu-pai יוֹאשִׁיַּ֗הוּ pai-dele וַיַּסֵּ֥ב a seu-nome Jeoaquim e-a יְהוֹאָחָ֣ז tomou E-veio Egito E-morreu nome');
INSERT INTO verses VALUES (10204, 12, 23, 35, 'וְהַכֶּ֣סֶף e-o-ouro dar יְהוֹיָקִים֙ para-Faraó somente הֶעֱרִ֣יךְ a a-terra a-dar a הַכֶּ֖סֶף sobre boca-de Faraó homem כְּעֶרְכּ֗וֹ נָגַ֞שׂ a-terra a-prata e-a o-ouro a povo a-terra a-dar para-Faraó Neco:');
INSERT INTO verses VALUES (10205, 12, 23, 36, 'filho-de vinte e-cinco ano Joiás no seu reinado e-uma dez ano rei em-Jerusalém sua-mãe sua-mãe filha-de Padiá de Roma:');
INSERT INTO verses VALUES (10206, 12, 23, 37, 'E-fez o-mal aos-olhos-de yhwh conforme-tudo que fizeram pais-dele');
INSERT INTO chapters VALUES (337, 12, 24, 20);
INSERT INTO verses VALUES (10207, 12, 24, 1, 'nos-seus-dias subir Nabucodonosor rei Babilônia e-foi a-ele Joiás servo três dois וַיָּ֖שָׁב וימרד־ em-ele');
INSERT INTO verses VALUES (10208, 12, 24, 2, 'וַיְשַׁלַּ֣ח yhwh nele a de-tropas caldeus- e-a גדודים ארם e-את de-tropas Moabe e-את de-tropas filhos-de Amom VASHELACHEM em juízo LEHA''VIDO yhwh yhwh que palavra na-mão-de seus-servos os-profetas');
INSERT INTO verses VALUES (10209, 12, 24, 3, 'somente sobre boca-de yhwh era em juáda LEHASIR de-cima-de perante-ele BCHATATO Manassés כְּכֹ֖ל que fez');
INSERT INTO verses VALUES (10210, 12, 24, 4, 'e-também DAM- HANAKIY que SHAFACH VAYMALA a Jerusalém sangue yhwh e-não yhwh yhwh para perdoar');
INSERT INTO verses VALUES (10211, 12, 24, 5, 'e-resto-de palavras-de Yehoyaqim e-todo que fez não-é eles escritos sobre livro palavras-de os-dias para-reis-de Judá');
INSERT INTO verses VALUES (10212, 12, 24, 6, 'e-ele-deitou Yehoyaqim com pais-seus e-reinou Jehoquia filho-seu em-lugar-dele');
INSERT INTO verses VALUES (10213, 12, 24, 7, 'e-não adicionou ainda rei Egito [מֵֽאַרְצ֑וֹ] [כִּֽי־לָקַ֞ח] porque tomou rei Bavel [עַד־נְהַר־פְּרָ֔ת] Egito até era [לְמֶ֥לֶךְ] todo que era para-rei-de Egito');
INSERT INTO verses VALUES (10214, 12, 24, 8, 'filho-de oito quinze ano [בְּמָלְכ֔וֹ] no seu reinado e-três meses rei em-Jerusalém sua-mãe sua-mãe [בַת־אֶלְנָתָ֖ן] filha-de [sem-traducao] de-i-ru-shalaim');
INSERT INTO verses VALUES (10215, 12, 24, 9, 'E-fez o-mal aos-olhos-de yhwh conforme-tudo que seu-pai seu-pai');
INSERT INTO verses VALUES (10216, 12, 24, 10, 'em-o-tempo aquela servos-de Nebucadnezzar rei-de Babilônia Jerusalém וַתָּבוֹא a-cidade בְּמָצֽוֹר׃');
INSERT INTO verses VALUES (10217, 12, 24, 11, 'E-veio Nevucadnezar rei-de Babilônia sobre a-cidade [עָלֶֽיהָ] [sem-traducao] sobre-ela');
INSERT INTO verses VALUES (10218, 12, 24, 12, 'e-saiu [יְהוֹיָכִ֤ין] rei-de Judá sobre ele Babilônia ele [וְשָׂרָ֣יו] [וְסָֽרִיסָ֑יו] E-tomou ele E-tomou ele rei Babilônia em-ano-de oito [sem-traducao]');
INSERT INTO verses VALUES (10219, 12, 24, 13, '[וַיּוֹצֵ֣א] de-lá a todo yhwh casa yhwh [הַמֶּ֑לֶךְ] casa o-rei o-ouro a todo utensílios-de o-ouro que yhwh שְׁלֹמֹה rei-de yhwh em-templo-de yhwh [sem-traducao] palavra yhwh');
INSERT INTO verses VALUES (10220, 12, 24, 14, '[וְהִגְלָ֣ה] a todo e-[OBJ] e-a todo [הַחַ֗יִל] e-את todo valentes-de hachayil milhares [וְהַמַּסְגֵּ֑ר] não [נִשְׁאַ֔ר] [זוּלַ֖ת] não נִשְׁאַ֔ר [sem-traducao] [sem-traducao] com a-terra');
INSERT INTO verses VALUES (10221, 12, 24, 15, '[וַיֶּ֥גֶל] a [בָּבֶ֑לָה] [וְאֶת־אֵ֣ם] e-[OBJ] mãe [הַמֶּ֜לֶךְ] e-[OBJ] e-[OBJ] o-rei e-[OBJ] a-terra e-[OBJ] a-terra [מִירוּשָׁלַ֖͏ִם] [בָּבֶֽלָה]');
INSERT INTO verses VALUES (10222, 12, 24, 16, 'e-את todo homens-de [שִׁבְעַ֣ת] sete [וְהֶחָרָ֤שׁ] [וְהַמַּסְגֵּר֙] [אֶ֔לֶף] mil o-tudo [עֹשֵׂ֣י] feitores guerra [מֶֽלֶךְ־בָּבֶ֛ל] rei-de Babilônia [sem-traducao] Bavelah;');
INSERT INTO verses VALUES (10223, 12, 24, 17, '[וַיַּמְלֵ֧ךְ] rei-de Babilônia a [תַּחְתָּ֑יו] [וַיַּסֵּ֥ב] tachthayo vayassab a tomou Tsidqiyahu');
INSERT INTO verses VALUES (10224, 12, 24, 18, 'filho-de vinte e-uma ano tsidqiyahu em-seu-reinado e-uma dez ano rei em-Jerusalém sua-mãe sua-mãe בַּֽת־ Jeremias de-linho:');
INSERT INTO verses VALUES (10225, 12, 24, 19, 'E-fez o-mal aos-olhos-de yhwh conforme-tudo que fez [sem-traducao]');
INSERT INTO verses VALUES (10226, 12, 24, 20, 'que sobre tambem yhwh era [בִירוּשָׁלִַ֙ם֙] [וּבִ֣יהוּדָ֔ה] até eles de-cima-de de-sobre perante-ele [צִדְקִיָּ֖הוּ] Zedeias em-rei-de Babilônia');
INSERT INTO chapters VALUES (338, 12, 25, 30);
INSERT INTO verses VALUES (10227, 12, 25, 1, 'e-houve [בִשְׁנַ֨ת] [הַתְּשִׁיעִ֜ית] [לְמָלְכ֗וֹ] no-mês [הָעֲשִׂירִי֮] בֶּעָשׂ֣וֹר [לַחֹדֶשׁ֒] veio [נְבֻכַדְנֶאצַּ֨ר] rei-de ele ele e-todo [וַיִּ֣חַן] sobre Jerusalém [עָלֶ֛יהָ] sobre-ela [סָבִֽיב] em-a [sem-traducao] ao-redor');
INSERT INTO verses VALUES (10228, 12, 25, 2, 'וַתָּבוֹא a-cidade [בַּמָּצ֑וֹר] até Ashthai dez ano ao-rei Tsidqiyahu');
INSERT INTO verses VALUES (10229, 12, 25, 3, '[בְּתִשְׁעָ֣ה] do-mês e fortaleceu a-fome na-cidade e-não pão pao a-terra a-terra');
INSERT INTO verses VALUES (10230, 12, 25, 4, '[וַתִּבָּקַ֣ע] a-cidade e-todo homens-de [׀] a-noite o-caminho-de porta entre entre que sobre [עַל־גַּ֣ן] o-rei [וְכַשְׂדִּ֥ים] sobre a-cidade ao-redor o-caminho-de caminho [sem-traducao]');
INSERT INTO verses VALUES (10231, 12, 25, 5, '[וַיִּרְדְּפ֤וּ] [חֵיל־כַּשְׂדִּים֙] [אַחַ֣ר] atrás-de o-rei ele ele [יְרֵח֑וֹ] Jericó e-todo חֵיל֔וֹ [sem-traducao] dele');
INSERT INTO verses VALUES (10232, 12, 25, 6, '[וַֽיִּתְפְּשׂוּ֙] a o-rei ele ele a rei Babilônia [אִתּ֖וֹ] [מִשְׁפָּֽט] com-ele juízo');
INSERT INTO verses VALUES (10233, 12, 25, 7, 'e-a filhos-de Zedequias [לְעֵינָ֑יו] לאعينו e-a [עִוֵּ֔ר] Tsidiyyahu עִוֵּר [וַיְבִאֵ֖הוּ] [בָּבֶֽל׃] [sem-traducao] Babilônia');
INSERT INTO verses VALUES (10234, 12, 25, 8, '[וּבַחֹ֤דֶשׁ] [הֽ͏ַחֲמִישִׁי֙] [בְּשִׁבְעָ֣ה] do-mês ela [שְׁנַת֙] teshá- dez ano ao-rei [מֶֽלֶךְ־בָּבֶ֑ל] rei-de Babilônia veio [עֶ֥בֶד] chefe-de [יְרוּשָׁלָֽ͏ִם] servo rei-de Babel Jerusalém');
INSERT INTO verses VALUES (10235, 12, 25, 9, 'e-ele-queimou a casa-de yhwh e-a casa o-rei e-a todo [שָׂרַ֥ף] Jerusalém e-a todo casa grande queimar em-a-chama');
INSERT INTO verses VALUES (10236, 12, 25, 10, 'e-a [יְרוּשָׁלַ֖͏ִם] Jerusalém ao-redor [כָּל־חֵ֣יל] todo força dos-caldeus que chefe-de [sem-traducao]');
INSERT INTO verses VALUES (10237, 12, 25, 11, 'e-[OBJ] [יֶ֨תֶר] o-povo [הַנִּשְׁאָרִ֣ים] [בָּעִ֗יר] e-[OBJ] [אֲשֶׁ֤ר] que [עַל־הַמֶּ֣לֶךְ] sobre e-[OBJ] Babilônia e-[OBJ] [הֶגְלָ֕ה] [נְבוּזַרְאֲדָ֖ן] [רַב־טַבָּחִֽים]');
INSERT INTO verses VALUES (10238, 12, 25, 12, '[וּמִדַּלַּ֣ת] a-terra deixou chefe-de [לְכֹֽרְמִ֖ים] [וּלְיֹגְבִֽים] [sem-traducao]');
INSERT INTO verses VALUES (10239, 12, 25, 13, 'e-a pilares [אֲשֶׁ֣ר] que casa-de yhwh e-a [אֲשֶׁ֥ר] e-a [שִׁבְּ֣רוּ] [כַשְׂדִּ֑ים] que na-casa-de yhwh [sem-traducao] [sem-traducao] e-levantaram a [sem-traducao] Bavelah;');
INSERT INTO verses VALUES (10240, 12, 25, 14, 'e-[OBJ] [וְאֶת־הַיָּעִ֜ים] e-[OBJ] [וְאֶת־הַכַּפּ֗וֹת] e-[OBJ] [כָּל־כְּלֵ֧י] e-[OBJ] [אֲשֶׁ֥ר] e-[OBJ] todo que');
INSERT INTO verses VALUES (10241, 12, 25, 15, 'e-a [וְאֶת־הַמִּזְרָק֗ות] e-a ouro ouro ouro ouro tomou prata prata tomou chefe-de [sem-traducao]');
INSERT INTO verses VALUES (10242, 12, 25, 16, '[הָעַמּוּדִ֣ים] dois hayyam- o-mar o-primeiro que fez Salomão para-casa-de yhwh não foi מִשְׁקָ֔ל [כָּל־הַכֵּלִ֥ים] todo os-utensílios as estas');
INSERT INTO verses VALUES (10243, 12, 25, 17, 'oito dez cubit [קוֹמַ֣ת] [׀] o único o-primeiro [וְכֹתֶ֨רֶת] [עָלָ֥יו] [׀] [נְחֹשֶׁת֮] três [הַכֹּתֶרֶת֮] [שָׁלֹ֣שׁ] sobre [**אַמּוֹת֒] ao-redor o-todo bronze [סָבִ֖יב] [הַכֹּ֣ל] o-segundo sobre [לַֽעַמּ֥וּד]');
INSERT INTO verses VALUES (10244, 12, 25, 18, 'E-tomou chefe-de [אֶת־שְׂרָיָה֙] a [הָרֹ֔אשׁ] sacerdote [כֹּהֵ֣ן] e-[OBJ] [וְאֶת־שְׁלֹ֖שֶׁת] sacerdote [הַסַּֽף] e-[OBJ]');
INSERT INTO verses VALUES (10245, 12, 25, 19, 'e-de tomou tomou um um que ele [עַל־אַנְשֵׁ֣י] sobre homens-de a-guerra e cinco homens [אֲשֶׁ֣ר] penei- o-rei asher foram achados em-a-ir e-a o sefer comandante-de a-terra [וְשִׁשִּׁ֥ים] a povo a-terra e-seis homem a-terra a-terra [sem-traducao] em-a-cidade');
INSERT INTO verses VALUES (10246, 12, 25, 20, 'E-tomou eles [נְבוּזַרְאֲדָ֖ן] chefe-de [וַיֹּ֧לֶךְ] eles a-eles sobre rei Babel [sem-traducao]');
INSERT INTO verses VALUES (10247, 12, 25, 21, 'e-feriu eles rei [בָּבֶ֧ל] [וַיְמִיתֵ֛ם] [בְּרִבְלָ֖ה] na-terra Hamate [וַיִּ֥גֶל] Judá de-cima-de sua terra:');
INSERT INTO verses VALUES (10248, 12, 25, 22, 'e-o povo [הַנִּשְׁאָר֙] na-terra Judá que [הִשְׁאִ֔יר] [נְבֽוּכַדְנֶאצַּ֖ר] rei Babilônia [וַיַּפְקֵ֣ד] sobre-eles a [בֶּן־אֲחִיקָ֥ם] filho-de [sem-traducao] filho-de [sem-traducao]');
INSERT INTO verses VALUES (10249, 12, 25, 23, 'e-eles-ouviram todo príncipes-de [הֵ֣מָּה] eles e-os-homens porque [אֶת־גְּדַלְיָ֔הוּ] rei-de Babilônia a [וְיִשְׁמָעֵ֣אל] e-vieram a [בֶּן־קָ֠רֵחַ] a manifestação e-Ismael filho-de [וְיַֽאֲזַנְיָ֙הוּ֙] [בֶּן־הַמַּ֣עֲכָתִ֔י] filho-de [וְאַנְשֵׁיהֶֽם] [sem-traducao] filho-de [sem-traducao] [sem-traducao] [sem-traducao] filho-de [sem-traducao] eles [sem-traducao]');
INSERT INTO verses VALUES (10250, 12, 25, 24, '[וַיִּשָּׁבַ֨ע] a-eles גְּדַלְיָ֙הוּ֙ [וּלְאַנְשֵׁיהֶ֔ם] E-disse a-eles a temais [הַכַּשְׂדִּ֑ים] os-cassitas na-terra [וְעִבְד֛וּ] [אֶת־מֶ֥לֶךְ] a rei a-vós [sem-traducao] a-vós');
INSERT INTO verses VALUES (10251, 12, 25, 25, 'e-houve no-mês o-sétimo veio ismael filho-de [בֶּן־נְ֠תַנְיָה] filho-de [מִזֶּ֣רַע] מִזֶּ֣רַע [וַעֲשָׂרָ֤ה] vá''ăśarah homens com-ele e-eles-feriram a [וְאֶת־הַיְּהוּדִים֙] E-morreu e-a [אִתּ֖וֹ] e-a que que foram com-ele em-o-monte-Mispa');
INSERT INTO verses VALUES (10252, 12, 25, 26, 'וַיָּקֻמוּ todo o-povo [וְעַד־גָּדוֹל֙] e-até grande e-príncipes-de [מִצְרָ֑יִם] que Egito de-diante-de [כַשְׂדִּֽים׃] de-faces-de [sem-traducao]');
INSERT INTO verses VALUES (10253, 12, 25, 27, 'e-houve [בִשְׁלֹשִׁ֨ים] וָשֶׁ֜בַע ano [לְגָלוּת֙] [יְהוֹיָכִ֣ין] rei-de Judá [עָשָׂר֙] dez novo [וְשִׁבְעָ֖ה] [לַחֹ֑דֶשׁ] para-o-mês [אֱוִ֣יל] Evil [מֶ֨לֶךְ] rei בבל no-ano-de [אֶת־רֹ֛אשׁ] a cabeça Jehoquia rei-de יְהוּדָה de-casa-de [sem-traducao]');
INSERT INTO verses VALUES (10254, 12, 25, 28, 'e-falou com-ele [טֹב֑וֹת] E-colocou a de-cima-de de-a trono [אֲשֶׁ֥ר] que com-ele [sem-traducao]');
INSERT INTO verses VALUES (10255, 12, 25, 29, '[וְשִׁנָּ֕א] a das-roupas [כִלְא֑וֹ] e-coma pão permanente diante-dele todo dias-de vida-dele');
INSERT INTO verses VALUES (10256, 12, 25, 30, '[וַאֲרֻחָת֗וֹ] [אֲרֻחַ֨ת] [תָּמִ֧יד] [נִתְּנָה־לּ֛וֹ] לו de-com o-rei palavra-de dia dias-de todo dias-de [sem-traducao]');
INSERT INTO books VALUES (13, '1CH', '1 Crônicas', 'AT', 29);
INSERT INTO chapters VALUES (339, 13, 1, 54);
INSERT INTO verses VALUES (10257, 13, 1, 1, 'homem Sete Enos');
INSERT INTO verses VALUES (10258, 13, 1, 2, 'Queinã Maalalel Jarede');
INSERT INTO verses VALUES (10259, 13, 1, 3, 'Hanoque Metusalá Lameque');
INSERT INTO verses VALUES (10260, 13, 1, 4, 'Noé nome Cam e-Jafé');
INSERT INTO verses VALUES (10261, 13, 1, 5, 'filhos-de Jafé Gômer e-Magogue e-Madai e-Javã e-Tubal e-Meseque e-Tirás');
INSERT INTO verses VALUES (10262, 13, 1, 6, 'e-filhos-de Gômer Asquenaz e-Difate e-Togarma');
INSERT INTO verses VALUES (10263, 13, 1, 7, 'e-filhos-de Javã Elisá e-Társis Quitim e-Rodanim');
INSERT INTO verses VALUES (10264, 13, 1, 8, 'filhos-de Cam Cuxe e-Misraim Pute e-Canaã');
INSERT INTO verses VALUES (10265, 13, 1, 9, 'e-filhos-de Cuxe Sebá e-Havilá e-Sabtá e-Raamá e-Sabtecá e-filhos-de Raamá Sabá e-Dedã');
INSERT INTO verses VALUES (10266, 13, 1, 10, 'e-Cuxe dar-à-luz a ele ele começou a-ser poderoso na-terra');
INSERT INTO verses VALUES (10267, 13, 1, 11, 'e-Misraim dar-à-luz a e-a Ludim e-a Leabim e-a Naftuim');
INSERT INTO verses VALUES (10268, 13, 1, 12, 'e-a Patrusim e-a Casluim que saíram de-lá Filisteus e-a Caftorim');
INSERT INTO verses VALUES (10269, 13, 1, 13, 'e-Canaã dar-à-luz a Sidom primogênito-seu e-a Hete');
INSERT INTO verses VALUES (10270, 13, 1, 14, 'e-a o-jebuseu e-a o-amorreu e-a o-girgaseu');
INSERT INTO verses VALUES (10271, 13, 1, 15, 'e-a o-heveu e-a o-arqueu e-a o-sineu');
INSERT INTO verses VALUES (10272, 13, 1, 16, 'e-a o-arvadeu e-a o-zemareu e-a o-hamateu');
INSERT INTO verses VALUES (10273, 13, 1, 17, 'filhos-de nome Elão e-Assur e-Arfaxade e-Lude e-Arã e-Uz e-Hul e-Geter e-Meseque');
INSERT INTO verses VALUES (10274, 13, 1, 18, 'e-Arfaxade dar-à-luz a enviou dar-à-luz gerou a Éber');
INSERT INTO verses VALUES (10275, 13, 1, 19, 'e-a-Éber nasceu segundo filhos nome o-primeiro Pelegue que em-dias-seus foi-dividida a-terra e-nome-de irmão-seu Joctã');
INSERT INTO verses VALUES (10276, 13, 1, 20, 'e-Joctã dar-à-luz a Almodá e-a Salefe e-a Hazarmavé e-a Jerá');
INSERT INTO verses VALUES (10277, 13, 1, 21, 'e-a Hadorão e-a Uzal e-a Diclá');
INSERT INTO verses VALUES (10278, 13, 1, 22, 'e-a Obal e-a Abimael e-a Sabá');
INSERT INTO verses VALUES (10279, 13, 1, 23, 'e-a Ofir e-a Havilá e-a Jobabe todo estes filhos-de Joctã');
INSERT INTO verses VALUES (10280, 13, 1, 24, 'Sem Arfaxade enviou');
INSERT INTO verses VALUES (10281, 13, 1, 25, 'Éber Pelegue Reu');
INSERT INTO verses VALUES (10282, 13, 1, 26, 'Serugue Naor Terá');
INSERT INTO verses VALUES (10283, 13, 1, 27, 'Abrão ele Abraão');
INSERT INTO verses VALUES (10284, 13, 1, 28, 'filhos-de Abraão Isaque e Ismael');
INSERT INTO verses VALUES (10285, 13, 1, 29, 'Estas gerações-de-eles em primogênito-de Ismael Nebaiote e Quedar e Adbeel e Mibsão');
INSERT INTO verses VALUES (10286, 13, 1, 30, 'Misma e Dumá Massá Hadade e Temá');
INSERT INTO verses VALUES (10287, 13, 1, 31, 'Jetur Nafis e Quedemá Estas eles filhos-de Ismael');
INSERT INTO verses VALUES (10288, 13, 1, 32, 'e filhos-de Quetura concubina-de Abraão ela gerou a Zinrã e Jocsã e Medã e Midiã e Isbaque e Suá e-filhos-de Jocsã Sabá e Dedã');
INSERT INTO verses VALUES (10289, 13, 1, 33, 'e-filhos-de Midiã Efá e Efer e Enoque e Abida e Eldaá todo estes filhos-de Quetura');
INSERT INTO verses VALUES (10290, 13, 1, 34, 'e-gerou Abraão a Isaque filhos-de Isaque Esaú e Israel');
INSERT INTO verses VALUES (10291, 13, 1, 35, 'filhos-de Esaú Elifaz Reuel e Jeús e Jalão e Corá');
INSERT INTO verses VALUES (10292, 13, 1, 36, 'filhos-de Elifaz Temã e Omar Zefi e Gaatã Quenaz e Timna e Amaleque');
INSERT INTO verses VALUES (10293, 13, 1, 37, 'filhos-de Reuel Naate Zerá Samá e Mizá');
INSERT INTO verses VALUES (10294, 13, 1, 38, 'e-filhos-de Seir Lotã e Sobal e Zibeão e Aná e Disom e Ezer e Disã');
INSERT INTO verses VALUES (10295, 13, 1, 39, 'e-filhos-de Lotã Hori e Hemã e irmã-de Lotã Timna');
INSERT INTO verses VALUES (10296, 13, 1, 40, 'filhos-de Sobal Alvã e Manaate e Ebal Sefi e Onã e-filhos-de Zibeão Aiá e Aná');
INSERT INTO verses VALUES (10297, 13, 1, 41, 'filhos-de Aná Disom e-filhos-de Disom Henrã e Esbã e Itrã e Querã');
INSERT INTO verses VALUES (10298, 13, 1, 42, 'filhos-de Ezer Bilã e Zaavã Jaacã filhos-de Disã Uz e-Arã');
INSERT INTO verses VALUES (10299, 13, 1, 43, 'e-estes os-reis que reinaram em-terra-de Edom diante-de rei-de rei a-filhos-de Israel Bela filho-de filho-de-Beor e-nome-de cidade-dele Dinhaba');
INSERT INTO verses VALUES (10300, 13, 1, 44, 'E-morreu Bela e-reinou em-lugar-dele Jobabe filho-de Zera de-Bozra');
INSERT INTO verses VALUES (10301, 13, 1, 45, 'E-morreu Jobabe e-reinou em-lugar-dele Husã de-terra-de o-temanita');
INSERT INTO verses VALUES (10302, 13, 1, 46, 'E-morreu Husã e-reinou em-lugar-dele Hadade filho-de filho-de-Bedade o-que-feriu a Midiã em-campo-de Moabe e-nome-de cidade-dele');
INSERT INTO verses VALUES (10303, 13, 1, 47, 'E-morreu Hadade e-reinou em-lugar-dele Samla de-Masreca');
INSERT INTO verses VALUES (10304, 13, 1, 48, 'E-morreu Samla e-reinou em-lugar-dele emprestado de-Reobote o-rio');
INSERT INTO verses VALUES (10305, 13, 1, 49, 'E-morreu שָׁאוּל e-reinou em-lugar-dele Baal Hanã filho-de Acbor');
INSERT INTO verses VALUES (10306, 13, 1, 50, 'E-morreu בַּ֣עַל Hanã e-reinou em-lugar-dele Hadade e-nome-de cidade-dele Paú e-nome-de esposa-dele Meetabel filha-de Matrede filha-de ouro ouro');
INSERT INTO verses VALUES (10307, 13, 1, 51, 'E-morreu Hadade e-foram chefes-de Edom chefe Timna chefe chefe Jetete');
INSERT INTO verses VALUES (10308, 13, 1, 52, 'chefe Aolibama chefe Elá chefe Pinon');
INSERT INTO verses VALUES (10309, 13, 1, 53, 'chefe Quenaz chefe Temã chefe Mibzar');
INSERT INTO verses VALUES (10310, 13, 1, 54, 'chefe Magdiel chefe Irã Estas chefes-de Edom');
INSERT INTO chapters VALUES (340, 13, 2, 55);
INSERT INTO verses VALUES (10311, 13, 2, 1, 'Estas filhos-de Israel Rúben Simeão Levi e-Judá Issacar e-Zebulom');
INSERT INTO verses VALUES (10312, 13, 2, 2, 'Dã José e-Benjamim Naftali Gade e-Aser');
INSERT INTO verses VALUES (10313, 13, 2, 3, 'filhos-de Judá Er e-Onã e-Selá três nasceu a-ele de-filha-de Sua e-houve E-foi Er primogênito-de Judá mau em-olhos-de yhwh e-matou-o');
INSERT INTO verses VALUES (10314, 13, 2, 4, 'e-Tamar nora-dele deu-à-luz para-ele a Perez e-a Zera todo filhos-de יְהוּדָה cinco');
INSERT INTO verses VALUES (10315, 13, 2, 5, 'filhos-de Perez Hezrom e-Hamul');
INSERT INTO verses VALUES (10316, 13, 2, 6, 'e-filhos-de Zera Zinri e-Eitan e-Heiman e-Calcol e-Darda todos-eles cinco');
INSERT INTO verses VALUES (10317, 13, 2, 7, 'e-filhos-de Carmi Acar perturbador-de Israel que ele-cometeu-transgressão em-o-anátema');
INSERT INTO verses VALUES (10318, 13, 2, 8, 'e-filhos-de Eitan Azarias');
INSERT INTO verses VALUES (10319, 13, 2, 9, 'e-filhos-de Hezrom que foi-gerado para-ele a Jerameel e-a Ram e-a Quelubai');
INSERT INTO verses VALUES (10320, 13, 2, 10, 'e-רָם gerou a Aminadabe e-Aminadabe gerou a נַחְשׁוֹן príncipe-de filhos-de Judá');
INSERT INTO verses VALUES (10321, 13, 2, 11, 'e-Nasom gerou a Salma e-Salma gerou a בֹּעַז');
INSERT INTO verses VALUES (10322, 13, 2, 12, 'e-Boaz gerou a Obede e-Obede gerou a Jessé');
INSERT INTO verses VALUES (10323, 13, 2, 13, 'e-Jessé gerou a primogênito-seu a Eliabe e-Abinadabe o-segundo e-Simea o-terceiro');
INSERT INTO verses VALUES (10324, 13, 2, 14, 'Netanel o-quarto Radai o-quinto');
INSERT INTO verses VALUES (10325, 13, 2, 15, 'Ozem o-sexto David o-sétimo');
INSERT INTO verses VALUES (10326, 13, 2, 16, 'Zeruia e-Abigail e-filhos-de צְרוּיָה Abisai e-Joabe e-dez- El três');
INSERT INTO verses VALUES (10327, 13, 2, 17, 'e-Abigail deu-à-luz a Amasa e-pai-de Amasa Jeter o-ismaelita');
INSERT INTO verses VALUES (10328, 13, 2, 18, 'e-Calebe filho-de Hezrom ele-gerou a Azuba mulher e-a Jeriote e-estes filhos-dela Jeser e-Sobabe e-Ardom');
INSERT INTO verses VALUES (10329, 13, 2, 19, 'e-ela-morreu Azuba e-tomou para-ele Calebe a a-ele e-deu-à-luz para-ele a Hur');
INSERT INTO verses VALUES (10330, 13, 2, 20, 'e-Hur gerou a Uri e-Uri gerou a Bezalel');
INSERT INTO verses VALUES (10331, 13, 2, 21, 'e-depois veio Hezrom a filha-de Maquir pai-de Gileade e-ele ele-a-tomou e-ele filho-de a-ele ano e-deu-à-luz para-ele a Segube');
INSERT INTO verses VALUES (10332, 13, 2, 22, 'e-Segube gerou a Jair e-foi para-ele vinte e-três cidades em-terra-de o-Gileade');
INSERT INTO verses VALUES (10333, 13, 2, 23, 'E-tomou Gesur e-Aram a aldeias-de Jair de-com-eles a Quenate e-a filhas-dela sessenta cidade todo estes filhos-de Maquir pai-de Gileade');
INSERT INTO verses VALUES (10334, 13, 2, 24, 'e-depois morte-de Hezrom em-Calebe Efrata e-esposa-de Hezrom Abias a-ele a-ele a Ashur pai-de Tecoa');
INSERT INTO verses VALUES (10335, 13, 2, 25, 'e-eles-foram filhos-de Jerameel em-primogênito Hezrom o-primogênito Ram e-Buna e-Orem e-Ozem Ahias');
INSERT INTO verses VALUES (10336, 13, 2, 26, 'e-foi mulher outra para-Jerameel e-nome-dela Atara ela mãe Onam');
INSERT INTO verses VALUES (10337, 13, 2, 27, 'e-foram filhos-de Ram primogênito-de Jerameel Maaz e-Jamim e-Equer');
INSERT INTO verses VALUES (10338, 13, 2, 28, 'e-foram filhos-de Onam Samai e-Jada e-filhos-de Samai Nadabe e-Abisur');
INSERT INTO verses VALUES (10339, 13, 2, 29, 'e-nome mulher-de Abisur Abiail e-deu-à-luz a-ele a Abam e-a Molide');
INSERT INTO verses VALUES (10340, 13, 2, 30, 'e-filhos-de Nadabe Seled e-Apaim E-morreu Seled não filhos');
INSERT INTO verses VALUES (10341, 13, 2, 31, 'e-filhos-de Apaim Isei e-filhos-de Isei Sesã e-filhos-de Sesã Alai');
INSERT INTO verses VALUES (10342, 13, 2, 32, 'e-filhos-de conheceu Ai Samai Jeter e-Jonatã E-morreu Jeter não filhos');
INSERT INTO verses VALUES (10343, 13, 2, 33, 'e-filhos-de Jonatã Pelet e-Zaza Estas foram filhos-de Jerameel');
INSERT INTO verses VALUES (10344, 13, 2, 34, 'e-não foi para-Sesã que porque se filhas e-para-Sesã servo egípcio e-nome-dele Jara');
INSERT INTO verses VALUES (10345, 13, 2, 35, 'E-colocou Sesã a filha-dele para-Jara servo-dele para-mulher a-ele para-ele a Atai');
INSERT INTO verses VALUES (10346, 13, 2, 36, 'e-Atai gerou a deu e-Natã gerou a Zabade');
INSERT INTO verses VALUES (10347, 13, 2, 37, 'e-Zabade gerou a Eflal e-Eflal gerou a עוֹבֵד');
INSERT INTO verses VALUES (10348, 13, 2, 38, 'e-Obede gerou a Jeú e-Jeú gerou a Azarias');
INSERT INTO verses VALUES (10349, 13, 2, 39, 'e-Azarias gerou a Helez e-Helez gerou a Elasa');
INSERT INTO verses VALUES (10350, 13, 2, 40, 'e-Elasa gerou a Sismai e-Sismai gerou a Salum');
INSERT INTO verses VALUES (10351, 13, 2, 41, 'e-Salum gerou a Jecamias e-Jecamias gerou a Elisama');
INSERT INTO verses VALUES (10352, 13, 2, 42, 'e-filhos-de Calebe Ai Jerameel Mesa primogênito-seu ele pai-de Zife e-filhos-de Maresa pai-de Hebrom');
INSERT INTO verses VALUES (10353, 13, 2, 43, 'e-filhos-de Hebrom Coré e-Tapua e-Rekem e-Shama');
INSERT INTO verses VALUES (10354, 13, 2, 44, 'e-Shema gerou a Raham pai-de Jorqueam e-Rekem gerou a Shamai');
INSERT INTO verses VALUES (10355, 13, 2, 45, 'e-filho-de Shamai habitação e-Maom pai-de casa-de Zur');
INSERT INTO verses VALUES (10356, 13, 2, 46, 'e-Eifa concubina-de Calebe deu-à-luz a Haram e-a Moza e-a Gazez e-Haram gerou a Gazez');
INSERT INTO verses VALUES (10357, 13, 2, 47, 'e-filhos-de Jahdai Regem e-Jotam e-Geshan e-Pelet e-Eifa e-Shaaf');
INSERT INTO verses VALUES (10358, 13, 2, 48, 'concubina-de Calebe Maaca dar-à-luz Sheber e-com Tirhana');
INSERT INTO verses VALUES (10359, 13, 2, 49, 'e-deu-à-luz Shaaf pai-de Madmana a Sheva pai-de Makbena e-pai-de Gibea e-filha-de Calebe Acsa');
INSERT INTO verses VALUES (10360, 13, 2, 50, 'Estas foram filhos-de Calebe filho-de Hur primogênito-de Efrata Shobal pai-de Quiriate Jearim');
INSERT INTO verses VALUES (10361, 13, 2, 51, 'Salma pai-de casa-de Lahem Haref pai-de casa-de Gader');
INSERT INTO verses VALUES (10362, 13, 2, 52, 'e-foram filhos para-Shobal pai-de cidade-de Jearim o-Haroe metade-de os-Menuot');
INSERT INTO verses VALUES (10363, 13, 2, 53, 'e-famílias-de cidade-de Jearim os-itritas e-os-putitas e-os-shumatitas e-os-misraítas de-estes saíram os-zoritas e-os-eshtaolitas');
INSERT INTO verses VALUES (10364, 13, 2, 54, 'filhos-de Salma casa pão e-netofatitas Atrot casa Joabe e-metade-de os-manaatitas os-zoritas');
INSERT INTO verses VALUES (10365, 13, 2, 55, 'e-famílias-de escribas Jabez tiratitas simeatitas sucatitas eles os-queneus os-que-vieram de-Hamate pai-de casa-de Recabe');
INSERT INTO chapters VALUES (341, 13, 3, 24);
INSERT INTO verses VALUES (10366, 13, 3, 1, 'e-estes foram filhos-de David que nasceram para-ele em-Hebron o-primogênito Amnon para-Ahinoam a-jezreelita segundo Daniel para-Abigail a-carmelita');
INSERT INTO verses VALUES (10367, 13, 3, 2, 'o-terceiro para-Absalom filho-de Maaca filha-de Talmai o-quarto Geshur o-quarto Adonias filho-de Hagite');
INSERT INTO verses VALUES (10368, 13, 3, 3, 'o-quinto Shefatias para-Abital o-sexto Itream para-Eglah esposa-dele');
INSERT INTO verses VALUES (10369, 13, 3, 4, 'seis nasceram- para-ele em-Hebron e-ele-reinou- nome sete dois e-seis meses e-trinta e-três ano rei em-Jerusalém');
INSERT INTO verses VALUES (10370, 13, 3, 5, 'e-aqueles nasceram- para-ele em-Jerusalém Shimea e-Shobab e-נָתָן quatro quatro para-filha-de Shua filha-de Ammiel');
INSERT INTO verses VALUES (10371, 13, 3, 6, 'e-Ibhar e-Elisama e-Elifelet');
INSERT INTO verses VALUES (10372, 13, 3, 7, 'e-Nogah e-Nefeg e-Jafia');
INSERT INTO verses VALUES (10373, 13, 3, 8, 'e-Elisama e-Eliada e-Elifelet nove');
INSERT INTO verses VALUES (10374, 13, 3, 9, 'todo filhos-de David além-de filhos-de concubinas e-Tamar irmã-deles');
INSERT INTO verses VALUES (10375, 13, 3, 10, 'e-filho-de Salomão Roboão Abias filho-dele Asa filho-dele Jeosafá filho-seu');
INSERT INTO verses VALUES (10376, 13, 3, 11, 'Jorão filho-dele Acazias filho-dele Joás filho-seu');
INSERT INTO verses VALUES (10377, 13, 3, 12, 'Amazias filho-dele Azarias filho-dele Jotão filho-seu');
INSERT INTO verses VALUES (10378, 13, 3, 13, 'Acaz filho-dele Ezequias filho-dele Manassés filho-dele');
INSERT INTO verses VALUES (10379, 13, 3, 14, 'Amom filho-seu Josias filho-dele');
INSERT INTO verses VALUES (10380, 13, 3, 15, 'e-filhos-de Josias o-primogênito Joanã o-segundo Jeoaquim o-terceiro Zedequias o-quarto Salum');
INSERT INTO verses VALUES (10381, 13, 3, 16, 'e-filhos-de Jeoaquim Jeconias filho-dele Zedequias filho-dele');
INSERT INTO verses VALUES (10382, 13, 3, 17, 'e-filhos-de Jeconias o-prisioneiro Shealtiel filho-seu');
INSERT INTO verses VALUES (10383, 13, 3, 18, 'e-Malquirão e-Pedaías e-Shenazar Jecamias Hosama e-Nedabias');
INSERT INTO verses VALUES (10384, 13, 3, 19, 'e-filhos-de Pedaías Zorobabel e-Simei e-filho-de Zorobabel Mesulão e-Hananias e-Selomite irmã-deles');
INSERT INTO verses VALUES (10385, 13, 3, 20, 'e-Hashubá e-Oel e-Berequias e-Hasadyah Yushab Hesed cinco');
INSERT INTO verses VALUES (10386, 13, 3, 21, 'e-filho-de Hananyah Pelatyah e-Yeshayah filhos-de Refayah filhos-de Arnan filhos-de Obadyah filhos-de Shekanyah');
INSERT INTO verses VALUES (10387, 13, 3, 22, 'e-filhos-de Shekanyah Shemayah e-filhos-de Shemayah Hatush e-Yigal e-Bariach e-Nearyah e-Shafat seis');
INSERT INTO verses VALUES (10388, 13, 3, 23, 'e-filho-de Nearyah Elyoenai e-Hizkiyah e-Azrikam três');
INSERT INTO verses VALUES (10389, 13, 3, 24, 'e-filhos-de Elyoenai e-Elyashib e-Pelayah e-Akub e-Yohanan e-Delayah e-Anani sete');
INSERT INTO chapters VALUES (342, 13, 4, 43);
INSERT INTO verses VALUES (10390, 13, 4, 1, 'filhos-de Judá Peretz Hetzron e-karmi e-hur e-shoval');
INSERT INTO verses VALUES (10391, 13, 4, 2, 'u-reaya filho-de shoval gerou a yachat e-yachat holid Estas achumai e-a lahad estes famílias a-sua-pulverização-verso-final');
INSERT INTO verses VALUES (10392, 13, 4, 3, 'e-estes pai-de animal-de-prey Jeové-dará-Elohim e-ouvi e-mel-fizeram e-nome-de irmã-deles a-trombeta-seu');
INSERT INTO verses VALUES (10393, 13, 4, 4, 'e-face-de-Elohim pai-de muro e-o-ajudador pai-de chushah Estas filhos-de chur primogênito-de efratah pai-de casa pão');
INSERT INTO verses VALUES (10394, 13, 4, 5, 'e-a-ashchure pai-de tekoa foram duas mulheres chelaah e-naarah');
INSERT INTO verses VALUES (10395, 13, 4, 6, 'e-deu-a a-ele naarah a achuzzam e-a chepar Estas têmni e-a ha-a-chash-tari estes filhos-de naarah');
INSERT INTO verses VALUES (10396, 13, 4, 7, 'e-filhos-de chelaah tseret ve-etnan');
INSERT INTO verses VALUES (10397, 13, 4, 8, 'E-espinhos gerou a anav e-a ha-tsovevah umishpachot a-har-chel filho-de ha-ru-m');
INSERT INTO verses VALUES (10398, 13, 4, 9, 'e-houve Jabez ni-khbad me-echa-hao ve-im-mo ka-re-ah sh-mo ya-a-betz dizendo que ya-la-d-ti be-ot-sev');
INSERT INTO verses VALUES (10399, 13, 4, 10, 'E-chamou jazer- a-elohim- Israel dizendo se abençoou me-bençoes- e-multiplica- a minha-fronteira- e-será tua-mão- comigo para-não de-pastagem- e-trouxe idolos-de E-veio Elohim a que pediu-');
INSERT INTO verses VALUES (10400, 13, 4, 11, 'e-gaiola- meu-irmão- conversa gerou ele preço ele pai-de eu-estou-ansioso-verso-final');
INSERT INTO verses VALUES (10401, 13, 4, 12, 'e-escondendo-se gerou a casa Rafá e-a Paseá e-a súplica Estas cidade serpente estes homens-de macia');
INSERT INTO verses VALUES (10402, 13, 4, 13, 'e-filhos-de Quenaz Ateniel e-Sravia e-filhos-de Atneiel Chatat');
INSERT INTO verses VALUES (10403, 13, 4, 14, 'e-Meonotai gerou a Aphra e-Sravia holid a Joabe ab-i que Charashim porque Charashim eram');
INSERT INTO verses VALUES (10404, 13, 4, 15, 'e-filhos-de Kalev filho-de yefunneh ireu Elá vanaam e-filhos-de Elá uknaz');
INSERT INTO verses VALUES (10405, 13, 4, 16, 'e-filhos-de yehalelael zif vezifah tirya vashrael');
INSERT INTO verses VALUES (10406, 13, 4, 17, 'e-filho-de ezrah resto e-mered e-efar e-yalon e-concebeu a miryam e-a Samai e-a yishbakh pai-de eshthemoa''');
INSERT INTO verses VALUES (10407, 13, 4, 18, 'e-ishtho ha-yehudiyah ela gerou a yered abí- gedor- e-a chever- pai-de soco- e-a yutiael- pai-de zanoch- e-estes filhos-de tomou filha-de Faraó que tomou mar-ed-');
INSERT INTO verses VALUES (10408, 13, 4, 19, 'e-filhos-de mulher-de hodiyah- achot- nacham- pai-de Queila o-garmi e-ouvir-eu o-maachati');
INSERT INTO verses VALUES (10409, 13, 4, 20, 'e-filhos-de shimon amnon e-rinha filho-de Hanã e-filhos-de yishai zoche-te e-filho-de zoche-te');
INSERT INTO verses VALUES (10410, 13, 4, 21, 'filhos-de shela filho-de Judá arre pai-de lecha ve-la-adah pai-de mara-sha u-mish-pachot casa-de serviço-de ha-butz segundo-casa-de ash-bea');
INSERT INTO verses VALUES (10411, 13, 4, 22, 've-yoqim e-homens-de kozeva ve-yaash e-seraf que ba-alu le-moav ve-yashubi pão ve-hadavarim atikim');
INSERT INTO verses VALUES (10412, 13, 4, 23, 'eles ha-yotserim ve-yoshevi netaim u-gedera com o-rei em-seu-trabalho eles-sentaram-se nome');
INSERT INTO verses VALUES (10413, 13, 4, 24, 'filhos-de Simeão Nemuel e-Jamin rebelde Zerach שָׁאוּל');
INSERT INTO verses VALUES (10414, 13, 4, 25, 'Shallum filho-dele Mibsam filho-seu Misma filho-seu');
INSERT INTO verses VALUES (10415, 13, 4, 26, 'e-filhos-de do-som Chammu''el filho-dele Zachur filho-seu Shimi filho-dele');
INSERT INTO verses VALUES (10416, 13, 4, 27, 'e-l-Shimi banim [שִׁשָּׁ֤ה] dez ve-banot seis u-le-achav não filhos muitos e-tudo misphachtam não hivru até filhos-de Judá');
INSERT INTO verses VALUES (10417, 13, 4, 28, 'e-estabeleceram-se be-bear- sete [וַחֲצַ֥ר] [שׁוּעָֽל] raposa''');
INSERT INTO verses VALUES (10418, 13, 4, 29, '[וּבְבִלְהָ֥ה] [וּבְעֶ֖צֶם] [וּבְתוֹלָֽד]');
INSERT INTO verses VALUES (10419, 13, 4, 30, '[וּבִבְתוּאֵ֥ל] [וּבְחָרְמָ֖ה] [וּבְצִֽיקְלָֽג]');
INSERT INTO verses VALUES (10420, 13, 4, 31, 'e-no-casa מַרְכָּבוֹת֙ וּבַחֲצַ֣ר cavalos e-em-bayt be-ri-yi e-em-sha-a-ra-iym Estas ar-ye-hem até rei Davi');
INSERT INTO verses VALUES (10421, 13, 4, 32, 'e-os-cortiços-deles de-seu e-o-olho Rimon e-o-interior e-fumou cidades cinco');
INSERT INTO verses VALUES (10422, 13, 4, 33, 'e-todo courts-deles que em-torno as-cidades estes esta o-dono esta a-eles e-se-vestiram para-eles');
INSERT INTO verses VALUES (10423, 13, 4, 34, 'e-voltado e-fará-rei e-sentou-se filho-de Amatziyah');
INSERT INTO verses VALUES (10424, 13, 4, 35, 'e-Yoel e-Jeuá filho-de Josibeia filho-de Saria filho-de Asiel');
INSERT INTO verses VALUES (10425, 13, 4, 36, 'e-o-Elioeinai e-a-Jaakovah e-Ischochaiyah e-Assayah e-Addieal e-Ismael e-Benaja');
INSERT INTO verses VALUES (10426, 13, 4, 37, 'e-Ziza filho-de de-seu-ramo filho-de Alom filho-de Jedaías filho-de Shimi filho-de Shemaia');
INSERT INTO verses VALUES (10427, 13, 4, 38, 'Estas os-que-vieram em-os-nomes príncipes em-o-sangue-deles e-a-casa os-pais-deles quebraram para-o-muitos');
INSERT INTO verses VALUES (10428, 13, 4, 39, 'e-foram para-a-entrada do-parede até ao-leste da-vala para-buscar do-pastor para-o-rebanho-deles');
INSERT INTO verses VALUES (10429, 13, 4, 40, 'e-os-acharam de-pasto gorduroso e-bom E-a-terra largura-de mãos e-quieto e-descansado que de cham os-que-habitam nome para-frente-versículo-final');
INSERT INTO verses VALUES (10430, 13, 4, 41, 'e-eles-vieram Estas os-escritos em-seus-nomes nos-dias-de Jeováz-quando-rei rei-de Judá e-eles-feriram a as-tendas-deles e-a que foram-encontrados- lá-baixo e-ele-consagrou-os até o-dia esta e-habitaram embaixo-deles porque do-pastor para-a-sua-ovelha nome');
INSERT INTO verses VALUES (10431, 13, 4, 42, 'e-deles de filhos-de Shimon- foram para-o-monte Seir homens cinco centenas e-Pelatyah e-Nearyah e-Raphayah e-Uzziael filhos-de Yeshi em-o-cabeça-deles-verso-final');
INSERT INTO verses VALUES (10432, 13, 4, 43, 'e-feriram a restante a-salvação para-Amaleque e-ele-estabeleceram-se até o-dia o-dia a-esta');
INSERT INTO chapters VALUES (343, 13, 5, 41);
INSERT INTO verses VALUES (10433, 13, 5, 1, 'e filhos-de Reuben em-o-primeiro-nato que ele ele o-primeiro-nato e-em-sua-impuração seu-pai pai-dele foi-dada a-primeira-partesia-dele para-filhos-de José filho-de Israel e-não para-se-mofar para-a-primeira-vidaː');
INSERT INTO verses VALUES (10434, 13, 5, 2, 'que Judá dominou em-o-seus-irmãos e-a-primeiro nós e-a-bocorah para-yossefː');
INSERT INTO verses VALUES (10435, 13, 5, 3, 'filhos-de reuven primogênito-de Israel Hanoque e-palu Hezrom e-karmiː');
INSERT INTO verses VALUES (10436, 13, 5, 4, 'filhos-de yoel Shema-yah filho-dele Gog filho-seu Shimi filho-dele');
INSERT INTO verses VALUES (10437, 13, 5, 5, 'Mikha filho-dele Re-ayah filho-dele Baal filho-seu');
INSERT INTO verses VALUES (10438, 13, 5, 6, 'Be-erah be-no que ele-exilou Til-gat Pil-ne-ser rei que ele príncipe la-Ruveni');
INSERT INTO verses VALUES (10439, 13, 5, 7, 've-echav para-o-sua-famílias com-a-ridículo para-os-seus-descendentes o-cabeça Yeiel e-Zacarias');
INSERT INTO verses VALUES (10440, 13, 5, 8, 'e-Bela filho-de Aza filho-de ele filho-de yoel ele habitante-de Baarorer e-até Nebo e-baal m-eon');
INSERT INTO verses VALUES (10441, 13, 5, 9, 've-la-mizrah habitou até le-bo mi-dvarah de-o que p-rat porque mi-kneihem ravu em-terra-de gil-ad');
INSERT INTO verses VALUES (10442, 13, 5, 10, 'e-em-dias-de שָׁאוּל asau guerra com os-ha-greiims e-caíram em-mão-deles e-eles-se-assentaram em-o-sus-aholes sobre todo face-de do-leste a-gilad');
INSERT INTO verses VALUES (10443, 13, 5, 11, 'e-filhos-de gad para-frente-deles e-ele-se-assentou em-terra-de o-Basã até salka');
INSERT INTO verses VALUES (10444, 13, 5, 12, 'Yo''el o-cabeça e-seu-saliva ha-mishne''h e-ele-respondam-me e-Shafat em-o-Basã');
INSERT INTO verses VALUES (10445, 13, 5, 13, 'e-seus-irmãos para-casa-de seus-pais מִֽיכָאֵ֡ל e-Meshullam e-sete e-ele-instrua-me e-Yachan e-sudor e-outra-parte sete');
INSERT INTO verses VALUES (10446, 13, 5, 14, 'Estas filhos-de Abi-Hail filho-de Hor-e filho-de lunar filho-de Gilead filho-de Micael filho-de Jesai filho-de Yahdo filho-de Buz');
INSERT INTO verses VALUES (10447, 13, 5, 15, 'irm-ao filho-de abdias filho-de guni cabeça segundo-casa-de avos-eus');
INSERT INTO verses VALUES (10448, 13, 5, 16, 'e-estabeleceram-se em-gileade em-a-Bashan e-na-sus-filhas e-em-todo-o de-seus-campos sharon sobre saídas-deles-verso');
INSERT INTO verses VALUES (10449, 13, 5, 17, 'todos-os se-fizeram-justos nos-dias يوتم rei-de Judá e-nos-dias يروبعام rei-de Israel');
INSERT INTO verses VALUES (10450, 13, 5, 18, 'filhos-de Reuben e-gadi e-metade-de bastão-de- menashe de filhos-de força homens carregadores-de escudo-o e-espada e-dos-cavaleiros arco e-de-a-instrução guerra quarenta e-quatro exército e-sete- centenas e-sessenta saídos-de exército');
INSERT INTO verses VALUES (10451, 13, 5, 19, 'e-fizeram guerra com os-os-grandes e-de-a-inspeção e-de-a-pesquisa e-nodab');
INSERT INTO verses VALUES (10452, 13, 5, 20, 'e-foram-ajudados sobre-eles e-foram-dados em-mão-de-eles os-graveis e-tudo em-a-sua-quietude que a-elohim gritaram na-guerra e-um-ladrão a-eles porque nele nele-verso');
INSERT INTO verses VALUES (10453, 13, 5, 21, 'e-eles-raptaram de-seus-bens seus-camelenos cinquenta mil e-o-cordeiro duzentos e-cinquenta mil e-ásnos dois-mil e-alma homem cem mil');
INSERT INTO verses VALUES (10454, 13, 5, 22, 'porque mortos רַבִּים que porque de-Alohim a-guerra e-habitaram em-baixo-deles até o-exílio');
INSERT INTO verses VALUES (10455, 13, 5, 23, 'e-filhos meio- tribo-de Manassés habitaram em-a-terra de-bashan até baal- hermon- e-senir e-har- hermon eles multiplicaram-se');
INSERT INTO verses VALUES (10456, 13, 5, 24, 'e-estes cabeças-de casa-de pais-deles e-efer e-yeshi e-Elieiel e-Azriaiele e-Yirmeya e-Hodaviah e-Yachdiaiel homens gibbori valente homens-de nomes cabeças segundo-casa-de avotam');
INSERT INTO verses VALUES (10457, 13, 5, 25, 've-yimaelu be-Elohei avoteihem e-ele-cometeram-adúlterio depois-de Elohim-de povos- a-terra que- ele-destruiu Elohim de-faces-deles');
INSERT INTO verses VALUES (10458, 13, 5, 26, 'e-ele-fazendo-sair Elohim-de Israel a espírito- Pul rei-de Assiria e-a espírito Tellegat Pulneser rei Assur e-ele-exilou-os para-o-ruveiniano e-para-o-gadita e-para-metade-de tribo-de Manassés e-ele-trou-los a-Cha-la-ch e-Ha-bo-r e-a-Ra-ah até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (10459, 13, 5, 27, 'filhos-de Levi Gérson Coate e-Merari');
INSERT INTO verses VALUES (10460, 13, 5, 28, 'e-filhos-de Qe-hat Anrão Yit-shar e-Chevron e-Uziel');
INSERT INTO verses VALUES (10461, 13, 5, 29, 'e-filhos-de Amram Aarão e-Mo-she e-Mi-ri-am e-filhos-de Arão Nadav e-Avi-hu-a Elazar e-Itamar');
INSERT INTO verses VALUES (10462, 13, 5, 30, 'Eleazar gerou a pena-khas pena-khas gerou a o-abishua');
INSERT INTO verses VALUES (10463, 13, 5, 31, 'e-o-abishua gerou a buki e-buki gerou a o-uzi');
INSERT INTO verses VALUES (10464, 13, 5, 32, 'e-o-uzi gerou a Zerachyah e-Zerachyah gerou a meryot');
INSERT INTO verses VALUES (10465, 13, 5, 33, 'meriyot gerou a amaraya ve-amarya gerou a achitub');
INSERT INTO verses VALUES (10466, 13, 5, 34, 've-achitub gerou a tsadoq ve-tsadoq gerou a achimawats');
INSERT INTO verses VALUES (10467, 13, 5, 35, 've-achimawats gerou a Azarias e-Azaria gerou a Jo-hanan');
INSERT INTO verses VALUES (10468, 13, 5, 36, 'e-Jo-hanan gerou a ele ele que sacerdote em-o-bayit que banah Salomão em-Jerusalém');
INSERT INTO verses VALUES (10469, 13, 5, 37, 'e-gerou Azaria a Amarya e-Amarya gerou a Ahitub');
INSERT INTO verses VALUES (10470, 13, 5, 38, 'e-Ahitub gerou a Tsadoq e-Tsadoq gerou a Salum');
INSERT INTO verses VALUES (10471, 13, 5, 39, 'e-Salum gerou a Chilqiya e-Chilqiya gerou a Azarias');
INSERT INTO verses VALUES (10472, 13, 5, 40, 'e-Azarias gerou a Shrayah e-sraviah gerou a Yehotsadaq');
INSERT INTO verses VALUES (10473, 13, 5, 41, 'e-Yehotsadaq andar be-haglôt yhwh a Judá e-Ierusalim na-mão-de Nebucadnetsar');
INSERT INTO chapters VALUES (344, 13, 6, 66);
INSERT INTO verses VALUES (10474, 13, 6, 1, 'filhos-de Levi Gershom Coate e-Merari');
INSERT INTO verses VALUES (10475, 13, 6, 2, 'e-estes nomes-de filhos-de Gerson para-meu-filho e-Simei');
INSERT INTO verses VALUES (10476, 13, 6, 3, 'e-filhos-de Qehat Anrão e-Izar e-Chevron e-Uziel');
INSERT INTO verses VALUES (10477, 13, 6, 4, 'filhos-de miseria Mahli e-Mushi e-estes mishpachot o-levita la-aboteihem');
INSERT INTO verses VALUES (10478, 13, 6, 5, 'para-gurseom para-meu-filho filho-dele Yachat filho-seu zimah filho-dele');
INSERT INTO verses VALUES (10479, 13, 6, 6, 'Yoach filho-o Iddo ben-o Zerach filho-seu Yaateray filho-seu');
INSERT INTO verses VALUES (10480, 13, 6, 7, 'filhos-de Qehath Amminadab seu-filho Coré filho-seu Assir filho-seu');
INSERT INTO verses VALUES (10481, 13, 6, 8, 'Elkanah filho-dele ve-Evyasaf filho-seu ve-Assir filho-seu');
INSERT INTO verses VALUES (10482, 13, 6, 9, 'debaixo filho-o Uriel seu-filho Uzzia filho-dele e-shaul filho-seu');
INSERT INTO verses VALUES (10483, 13, 6, 10, 'e-filhos-de Elcana Amasi e-Achimot');
INSERT INTO verses VALUES (10484, 13, 6, 11, 'Elcana Elcana Tsophai filho-seu e-Nachat filho-seu');
INSERT INTO verses VALUES (10485, 13, 6, 12, 'Eliav filho-dele Yeroham filho-seu Elcana filho-dele');
INSERT INTO verses VALUES (10486, 13, 6, 13, 'e-filhos-de Samuel o-primeiro e-a-segunda e-o-abia');
INSERT INTO verses VALUES (10487, 13, 6, 14, 'filhos-de miseria de-mahli para-meu-filho filho-dele Shimi filho-dele ozea filho-dele');
INSERT INTO verses VALUES (10488, 13, 6, 15, 'ouvir filho-dele festa-de-elohim filho-dele asaya filho-dele');
INSERT INTO verses VALUES (10489, 13, 6, 16, 'e-estes que estabeleceu Davi sobre por-meio-de- yhwh casa yhwh de-Minoch a-arca');
INSERT INTO verses VALUES (10490, 13, 6, 17, 'e-eles-foram servos diante-de tabernáculo tenda-de encontro em-o-salmo até filhas yhwh a casa yhwh em-Jerusalém e-se-posicionaram como-seus-julgamentos sobre serviço-deles');
INSERT INTO verses VALUES (10491, 13, 6, 18, 'e-aqueles os-que-estavam-de-pé e-os-seus-filhos de-os-filhos o-qehathi Heman- o-mashorer filho-de Yoel- filho-de Shemuel:');
INSERT INTO verses VALUES (10492, 13, 6, 19, 'filho-de Elcana filho-de Yeroham- filho-de Eliel- filho-de Toch-');
INSERT INTO verses VALUES (10493, 13, 6, 20, 'filho-de filho-de Elkana- filho-de machat- filho-de Amasya-');
INSERT INTO verses VALUES (10494, 13, 6, 21, 'filho-de Elcana filho-de Yoel filho-de Azarya- filho-de Tséphan-yáh');
INSERT INTO verses VALUES (10495, 13, 6, 22, 'filho-de ta-chát filho-de a-sír filho-de e-byásaf filho-de qó-rakh');
INSERT INTO verses VALUES (10496, 13, 6, 23, 'filho-de Yitsháhár filho-de Qehat filho-de Levi filho-de Israel');
INSERT INTO verses VALUES (10497, 13, 6, 24, 've-áchiv Asafe ha-oméd sobre direita-de-ele Ásaf filho-de Berekhyáhu filho-de Shimaa-');
INSERT INTO verses VALUES (10498, 13, 6, 25, 'filho-de Michael filho-de Baaseya- filho-de Malchiyah-');
INSERT INTO verses VALUES (10499, 13, 6, 26, 'filho-de Ethni- filho-de Zerá filho-de Adaya-');
INSERT INTO verses VALUES (10500, 13, 6, 27, 'filho-de Eitan- filho-de zimmáh filho-de Shimi-');
INSERT INTO verses VALUES (10501, 13, 6, 28, 'filho-de Yachat filho-de גרשם filho-de Levi');
INSERT INTO verses VALUES (10502, 13, 6, 29, 'e-filhos-de Merari os-irmãos-deles sobre o-esquerdo אֵיתָן֙ filho-de de-Kish filho-de servo-meu filho-de reinado');
INSERT INTO verses VALUES (10503, 13, 6, 30, 'filho-de Chashavya filho-de Amatziyah filho-de Chilquiyah');
INSERT INTO verses VALUES (10504, 13, 6, 31, 'filho-de de-Amatsi filho-de filhos-de filho-de guarda-verso');
INSERT INTO verses VALUES (10505, 13, 6, 32, 'filho-de de-Mahli filho-de de-Mushi filho-de miseria filho-de Levi');
INSERT INTO verses VALUES (10506, 13, 6, 33, 'e-irmãos-deles os-levitas doados para-todo serviço-de tabernáculo casa Elohim');
INSERT INTO verses VALUES (10507, 13, 6, 34, 'e-Aharon e-seus-filhos queimam-incenso sobre altar-de a-oferta-quemada e-sobre a-todo o-a fragrância para-todo trabalho santo-de ha-kodashim para-kapitar sobre Israel como-tudo que deu-mandamento Moisés servo Elohim');
INSERT INTO verses VALUES (10508, 13, 6, 35, 'e-estes filhos-de Aarão Elazar filho-dele Pinchas filho-seu Abishua filho-seu');
INSERT INTO verses VALUES (10509, 13, 6, 36, 'Buki filho-dele u-zi filho-dele Zerahyah filho-dele');
INSERT INTO verses VALUES (10510, 13, 6, 37, 'Merayot filho-dele Amaryah filho-dele Ahitub filho-seu');
INSERT INTO verses VALUES (10511, 13, 6, 38, 'Zadoque filho-seu Ahimaz filho-seu');
INSERT INTO verses VALUES (10512, 13, 6, 39, 'e-estes em-o-sentados-deles para-a-cidades-deles na-fronteira-deles para-filhos-de Arão le-mishpachat o-qehathi que a-eles ser da-sortes');
INSERT INTO verses VALUES (10513, 13, 6, 40, 'e-eles-distribuíram a-eles a Hebrom em-terra-de Judá e-a dos-terrenos-seus em-o-seus-vicinhanças-verso-final');
INSERT INTO verses VALUES (10514, 13, 6, 41, 'e-a campo-de a-cidade e-a cortiãos-dela deram para-Calev filho-de sera-virado-verso-final');
INSERT INTO verses VALUES (10515, 13, 6, 42, 'e-para-filhos-de Arão deram-eles a cidades-de o-refugio a Hebrom e-a para-Bet-Lahem e-a de-seus-amparos e-a excesso e-com ouvi e-a seus-campos');
INSERT INTO verses VALUES (10516, 13, 6, 43, 'e-a saiu e-a de-seus-campos a lugar-santo e-a seus-campos');
INSERT INTO verses VALUES (10517, 13, 6, 44, 'e-a fumo e-a de-seus-campos e-a casa sol e-a seus-campos');
INSERT INTO verses VALUES (10518, 13, 6, 45, 'e-de-a-tribo Benjamin a גֶּ֤בַע e-a de-seu-margem e-a עָלֶ֣מֶת e-a de-seus-campos e-a עֲנָת֖וֹת e-a de-seu-margem todo seus-cidades três- doze cidade segundo-suas-famílias');
INSERT INTO verses VALUES (10519, 13, 6, 46, 'e-a-filhos-de Qehath ha-notharim mi-mishpachath ham-matteh mi-mmachatzith matteh- chatzi- mennasheh ba-goral cidades dez');
INSERT INTO verses VALUES (10520, 13, 6, 47, 'e-a-filhos-de gereshom para-o-sua-família de-a-tribo יִ֠שָׂשכָר e-de-a-tribo que e-de-a-tribo Naftali e-de-a-tribo מְנַשֶּׁה em-Bashan cidades três dez');
INSERT INTO verses VALUES (10521, 13, 6, 48, 'para-o-filho-de מְרָרִ֜י para-o-sua-família de-a-tribo רְ֠אוּבֵן e-de-a-tribo- גָ֞ד e-de-a-tribo זְבוּלֻן֙ no-o-sorteio cidades dois dez');
INSERT INTO verses VALUES (10522, 13, 6, 49, 'e-eles-distribuíram filhos-de Israel para-os-Levitas a as-cidades e-a de-seus-campos-verso-final');
INSERT INTO verses VALUES (10523, 13, 6, 50, 'e-eles-distribuíram no-goral de-matate filhos-de Judá e-de-matate filhos-de Simeão e-de-matate filhos-de Benjamim a ha-arim estes que chamam a-eles em-nomes');
INSERT INTO verses VALUES (10524, 13, 6, 51, 'e-de-famílias filhos-de Qehath e-houve cidades-de gevulam mi-matteh Efrayim');
INSERT INTO verses VALUES (10525, 13, 6, 52, 'va-yittenu a-eles a arei ha-miklat a Shekem e-a migra-sehah em-monte-de Efraim e-a Gezer e-a migra-sehah');
INSERT INTO verses VALUES (10526, 13, 6, 53, 'e-com yakm''ama e-a mi-gresha-ha e-a casa choron e-a mi-gresha-ha:');
INSERT INTO verses VALUES (10527, 13, 6, 54, 'e-a ayylon e-a mi-gresha-ha e-a gat- rimmon e-a mi-gresha-ha:');
INSERT INTO verses VALUES (10528, 13, 6, 55, 'u-mim-machatiyth tribo-de Manassés a Aner e-a de-seus-campos e-a בִּלְעָם e-a de-seus-amparos le-mishpachat para-filhos-de Coate הַנּוֹתָרִים׃');
INSERT INTO verses VALUES (10529, 13, 6, 56, 'libnei Gershon de-a-família meio- tribo-de Manassés a golan em-a-Bashan e-a em-o-grassy-ela e-a ash-ta-roth e-a em-o-grassy-ela-pontuação');
INSERT INTO verses VALUES (10530, 13, 6, 57, 'e-de-a-maneira-de Yissachar a Qedesch e-a em-o-grassy-ela a dab-rath e-a em-o-grassy-ela-pontuação');
INSERT INTO verses VALUES (10531, 13, 6, 58, 'e-a Raamoth e-a em-o-migrašeha e-a anem e-a em-o-migraše-ha');
INSERT INTO verses VALUES (10532, 13, 6, 59, 've-em-o-matte que a mashal e-a em-o-migraše-ha e-a abdon e-a em-o-migraše-ha');
INSERT INTO verses VALUES (10533, 13, 6, 60, 'e-a chuqoq e-a em-o-migrašeha e-a Rechob e-a de-a-sua-mesada');
INSERT INTO verses VALUES (10534, 13, 6, 61, 'e-de-a-tribo Naftali a quedês em-a-galil e-a de-a-sua-mesada e-a chamom e-a de-a-sua-mesada e-a cidade-dupla e-a de-a-sua-mesada');
INSERT INTO verses VALUES (10535, 13, 6, 62, 'aos-filhos-de amar-doce os-restantes de-a-tribu Zebulom a de-Rimon e-a do-margem-seu a Tabor e-a do-margem-seu');
INSERT INTO verses VALUES (10536, 13, 6, 63, 'e-de-ao-lado para-o-Jordão Jericó para-o-levantar o-Jordão de-a Rúben a be-tser em-o-midbar e-a de-seu-migraze e-a yatza e-a de-seu-migraze');
INSERT INTO verses VALUES (10537, 13, 6, 64, 'e-a kedemot e-a de-seu-migraze e-a meipaat e-a de-seu-migraze');
INSERT INTO verses VALUES (10538, 13, 6, 65, 'e-de-a Gade a alturas de-Gileade e-a seus-margens e-com acampamentos e-a seus-margens');
INSERT INTO verses VALUES (10539, 13, 6, 66, 'e-a Hesbom e-a seus-margens e-a Jaazer e-a seus-margens');
INSERT INTO chapters VALUES (345, 13, 7, 40);
INSERT INTO verses VALUES (10540, 13, 7, 1, 'e-os-filhos-de יִשָׂשכָ֗ר תוֹלָ֧ע e-pouah e-shimron quatro');
INSERT INTO verses VALUES (10541, 13, 7, 2, 'e-filhos-de תוֹלָ֗ע ozi e-raphiah e-riel e-yahmay e-yibsham u-shmuel raashim para-casa-de pais-deles le-to-la gibo-rei valor le-toldotam misparam em-dias-de Davi vinte- u-shnayim mil e-seis centenas');
INSERT INTO verses VALUES (10542, 13, 7, 3, 'e-filhos-de uzzi yizraeyah e-filhos-de yizraeyah מִֽיכָאֵ֡ל e-abadyah e-yoel yishiyah chamishah roshim כליהם׃');
INSERT INTO verses VALUES (10543, 13, 7, 4, 'e-sobre-eles para-as-gerações-deles para-casa-de pais-deles exércitos-de exército-de guerra trinta [וְשִׁשָּׁ֖ה] mil porque הִרְבּ֥וּ mulheres e-filhos');
INSERT INTO verses VALUES (10544, 13, 7, 5, 'e-irmãos-de-eles a-todo mi-sh-p-ho-th Yissachar os-gibores homens-de-guerra oitenta e-sete mil se-prepararam para-todo');
INSERT INTO verses VALUES (10545, 13, 7, 6, 'Benjamim belom e-pela-manhã vidi-ael três');
INSERT INTO verses VALUES (10546, 13, 7, 7, 'e-filhos-de bel-a etz-bon ve-uzy ve-uziel vi-yimot ve-iiri cinco ra-shei casa אָב֔וֹת os-gibores cha-yalim ve-hityachsham vinte e-dois mil e-trinta e-quatro');
INSERT INTO verses VALUES (10547, 13, 7, 8, 'e-filhos-de becer zemirah ve-yoash ve-eliezer ve-elyoinai ve-amri vi-yeremot va-abiyah va-anatot ve-alamet todo estes filhos-de no-primeiro-dia-verso');
INSERT INTO verses VALUES (10548, 13, 7, 9, 'e-se-fizeram-preparados para-as-gerações-deles cabeças-de casa pais-deles os-gibores força vinte mil e-duzentos');
INSERT INTO verses VALUES (10549, 13, 7, 10, 'e-filhos-de Yediael Belhan e-filhos-de Belhan [*יעיש] e-Ehud e-Canaã e-o-zite e-a-tarshish e-achischar');
INSERT INTO verses VALUES (10550, 13, 7, 11, 'todo estas filhos-de yediael para-os-cabeças os-avos os-gibores soldados sete- dez mil exército saídos-de exército para a guerra:');
INSERT INTO verses VALUES (10551, 13, 7, 12, 'e-sufim e-chufim filhos-de cidade chushim filhos-de outro');
INSERT INTO verses VALUES (10552, 13, 7, 13, 'filhos-de Naftali yahatziael veguni veyetser veshalum filhos-de bilhah');
INSERT INTO verses VALUES (10553, 13, 7, 14, 'filhos-de Manassés ashriael que yaladah pilegsho haaramiyah filha a Makhir pai-de Gileade');
INSERT INTO verses VALUES (10554, 13, 7, 15, 'e-Makhir tomou mulher para-cobertos e-para-sujos ve-shem sua-irmã Maaca e-nome-de o-segundo Tselaqhad e-foram Tselaqhad banoth');
INSERT INTO verses VALUES (10555, 13, 7, 16, 'e-deu-a Maaca esposa-de filho filho e-chamou nome-dele fero e-nome-de irmão-seu sharèsh e-seus-filhos oulam waraqem');
INSERT INTO verses VALUES (10556, 13, 7, 17, 'e-filhos-de oulam bedan Estas filhos-de Gileade filho-de makhir filho-de Mênashé:');
INSERT INTO verses VALUES (10557, 13, 7, 18, 'va''achoto hamolekhet yalda a ishhod e-a Abiezéu e-a doença-verso');
INSERT INTO verses VALUES (10558, 13, 7, 19, 'e-foram filhos-de destruição-acento ahyan-acentuado e-vos-verso e-meu-retirar-acento e-eles-mover-verso');
INSERT INTO verses VALUES (10559, 13, 7, 20, 'e-filhos-de Efraim shotalach e-verdura-acentuado filho-o e-embaixo-de seu-filho e-eladah-acento filho-dele ve-ta-xat filho-seu');
INSERT INTO verses VALUES (10560, 13, 7, 21, 'e-zabad-acento filho-dele e-shutelah-acentuado filho-seu e-Azer e-Elad e-matar-os homens de Gat os-nascidos que porque desceram para-tomar a miqnehem');
INSERT INTO verses VALUES (10561, 13, 7, 22, 'e-se-lamentou Efraim seu-pai dias muitos e-vieram seus-irmãos para-consolá-lo');
INSERT INTO verses VALUES (10562, 13, 7, 23, 'E-veio a mulher-dele e-concebeu filho E-chamou E-chamou a que com-gritaria era em-mal haytah no seu lar:');
INSERT INTO verses VALUES (10563, 13, 7, 24, 'e-a-sua-filha Seara e-ela-construiu a casa-de Horon o-inferior e-a o mais alto e-a Ozen Seara');
INSERT INTO verses VALUES (10564, 13, 7, 25, 'e-Refa filho-seu e-Resef e-Telah filho-seu e-tachan filho-seu');
INSERT INTO verses VALUES (10565, 13, 7, 26, 'para Amram: filho-dele ammi-hud filho-seu elishama filho-seu');
INSERT INTO verses VALUES (10566, 13, 7, 27, 'non filho-seu יְהוֹשֻׁ֥עַ filho-seu');
INSERT INTO verses VALUES (10567, 13, 7, 28, 'וַאֲחֻזָּתָם֙ e suas moradas casa-de El e suas filhas e para o oriente naarân e para o ocidente Gêzer e suas filhas Scâm e suas filhas até Aia e-as-sua-filhas:');
INSERT INTO verses VALUES (10568, 13, 7, 29, 'e-sobre mãos-de filhos-de Menasheh casa-de Shaan e-filhas-de-a-ela Taanak e-filhas-de-a-ela Megido e-filhas-dela dor e-suas-filhas be-eleh yashvu filhos-de José filho-de Israel');
INSERT INTO verses VALUES (10569, 13, 7, 30, 'filhos-de que yimnah veyishvah veyishvi uberi''ah veserach irmã-deles');
INSERT INTO verses VALUES (10570, 13, 7, 31, 'e-filhos-de בְרִיעָ֔ה chever umalki''el ele pai-de');
INSERT INTO verses VALUES (10571, 13, 7, 32, 'e-querer gerou a ele-libertar e-a guarda e-a emblema e-a grito irmã-deles');
INSERT INTO verses VALUES (10572, 13, 7, 33, 'e-filhos-de ele-libertar passou e-com-paciência e-fazendo Estas filhos-de ele-libertar-verso-final');
INSERT INTO verses VALUES (10573, 13, 7, 34, 'e-filhos-de guarda-acento irmão-de e-Aram');
INSERT INTO verses VALUES (10574, 13, 7, 35, 'e-filho-de He-lem irmão-dele Tofach ve-Yimna ve-Shelesh ve-Amal');
INSERT INTO verses VALUES (10575, 13, 7, 36, 'filhos-de Tofach Sucha ve-Charnaper ve-Shual e-seu e-ela-grita');
INSERT INTO verses VALUES (10576, 13, 7, 37, '[בֶּ֣צֶר] e-vaidade e-silencio e-três e-mais e-no-abismo');
INSERT INTO verses VALUES (10577, 13, 7, 38, 'e-filhos-de יֶ֑תֶר ele-vira e-partes e-eu-vi-:');
INSERT INTO verses VALUES (10578, 13, 7, 39, 'e-filhos-de olá-a ele-preparou- e-Chaníael-e e-Ritzia-:');
INSERT INTO verses VALUES (10579, 13, 7, 40, 'todo estes filhos-de que cabeças-de casa-de os-pais purificados-u valentes-de soldados-i ראשׁי os-nobres-a e-ele-se-preparou em-a-arma-da na-guerra de-seu-número homens vinte mil');
INSERT INTO chapters VALUES (346, 13, 8, 40);
INSERT INTO verses VALUES (10580, 13, 8, 1, 'e-com-Benjamim gerou a Belal de-seu-primeiro-filho Asbel o-segundo e-Achar o-terceiro');
INSERT INTO verses VALUES (10581, 13, 8, 2, 'Nocha o-quarto e-rifar o-quinto');
INSERT INTO verses VALUES (10582, 13, 8, 3, 'e-foram filhos [לְבָ֑לַע] adár e-géra e-abihud');
INSERT INTO verses VALUES (10583, 13, 8, 4, 'e-avishua e-naamán e-aachoh');
INSERT INTO verses VALUES (10584, 13, 8, 5, 'e-géra e-shfupan e-Huram-');
INSERT INTO verses VALUES (10585, 13, 8, 6, 'e-estes filhos-de e-chudh Estas eles cabeças-de avós le-yoshvei geva- vayaglum a manachat-');
INSERT INTO verses VALUES (10586, 13, 8, 7, 'e-naamahn e-Achiea e-gera- ele heglam וְהוֹלִ֥יד a uzzah e-a Ahichud');
INSERT INTO verses VALUES (10587, 13, 8, 8, 've-shacharayim holid em-campo-de Moabe de eles a-eles chushim e-com ba-ara nashav');
INSERT INTO verses VALUES (10588, 13, 8, 9, 'e-gerou de novo mulher-sua a Yovav e-a Tzivyah e-a Meisha e-a Malcam');
INSERT INTO verses VALUES (10589, 13, 8, 10, 'e-a conselheiros e-a Estas e-a מִרְמָה estes filhos-dele topos-de pais-');
INSERT INTO verses VALUES (10590, 13, 8, 11, '-e-de-homens gerou a abitub e-a elpal-');
INSERT INTO verses VALUES (10591, 13, 8, 12, 'e-filhos-de elpal Éber -e-de-mandações -e-shamed ele edificar a onohu e-a lod e-suas-filhas-:');
INSERT INTO verses VALUES (10592, 13, 8, 13, 'e-na-rua e-a-ouça eles cabeças-de as-mães: para-os-donos Aialôn eles e-espalharam-se a aos-donos Gat:');
INSERT INTO verses VALUES (10593, 13, 8, 14, 'e-seu-cunhado shashak e-irmo-t');
INSERT INTO verses VALUES (10594, 13, 8, 15, 'וּזְבַדְיָ֥ה e-arad e-adar');
INSERT INTO verses VALUES (10595, 13, 8, 16, 'u-michael ve-yishfa ve-yocha filhos-de be-reia-ha');
INSERT INTO verses VALUES (10596, 13, 8, 17, 'וּזְבַדְיָ֥ה e-Mesulão ve-chizi e-chaver');
INSERT INTO verses VALUES (10597, 13, 8, 18, 've-yishmrai [וְיִזְלִיאָ֛ה] [וְיוֹבָ֖ב] filhos-de elpal-');
INSERT INTO verses VALUES (10598, 13, 8, 19, '[וְיָקִ֥ים] e-zichri [וְזַבְדִּֽי]');
INSERT INTO verses VALUES (10599, 13, 8, 20, 'וֶאֱלִיעֵנַ֥י e-me-escondas e-Eloel:');
INSERT INTO verses VALUES (10600, 13, 8, 21, 'e-adiáh e-braíyah e-shémrat filhos-de shémui:');
INSERT INTO verses VALUES (10601, 13, 8, 22, 'e-yishpán e-outra-parte e-Eloel:');
INSERT INTO verses VALUES (10602, 13, 8, 23, 'e-avdôn e-zikrí וְחָנָֽן׃');
INSERT INTO verses VALUES (10603, 13, 8, 24, '[וַחֲנַנְיָ֥ה] [וְעֵילָ֖ם] e-anotei-yah');
INSERT INTO verses VALUES (10604, 13, 8, 25, 'e-ipdiah filhos-de shashak');
INSERT INTO verses VALUES (10605, 13, 8, 26, 'e-shamsherai u-schariyah ve-ateliyah');
INSERT INTO verses VALUES (10606, 13, 8, 27, 'e-yarreshiyah e-eliyah e-zichri filhos-de yeroham');
INSERT INTO verses VALUES (10607, 13, 8, 28, 'Estas topos-de pais para-as-suas-gerações cabeças-de Estas viveram em-Jerusalém');
INSERT INTO verses VALUES (10608, 13, 8, 29, 'e-em-Gibeão habitaram pai-de Gibeão e-nome-de mulher-sua ma''akah');
INSERT INTO verses VALUES (10609, 13, 8, 30, 'e-no-seu-filho o primogênito Abdôn וְצ֥וּר e-Qish e-baal e-Nadab');
INSERT INTO verses VALUES (10610, 13, 8, 31, 'e-Gedor e-o-Achiyo e-zacher');
INSERT INTO verses VALUES (10611, 13, 8, 32, 'e suas caixas gerou a shimah diante eles neged acheyhem viveram בירושלם com irmãos-deles');
INSERT INTO verses VALUES (10612, 13, 8, 33, 'e-ner gerou a קיס e-Qish gerou a שָׁאוּל e-Saul holid a Yehonatan e-a Malchi- Shua e-a Avinadab e-a eu-juro-pelo');
INSERT INTO verses VALUES (10613, 13, 8, 34, 'e-filho-de Yehonatan contendente o-dono e-contendente בעאל gerou a Mica-');
INSERT INTO verses VALUES (10614, 13, 8, 35, 'e-filhos-de Mica Piton e-rei e-encontre-se e-pegue');
INSERT INTO verses VALUES (10615, 13, 8, 36, 'e-Ahaz gerou a Yehoaddah e-Yehoaddah ele-gerou a Alemet e-a Azmavete e-a Zimri e-Zimri gerou a Motza-');
INSERT INTO verses VALUES (10616, 13, 8, 37, 'e-Motza gerou a Benaa Rapha filho-dele Elasah filho-dele atzel filho-seu');
INSERT INTO verses VALUES (10617, 13, 8, 38, 'u-le-atzel seis filhos e-estes shemotam Azrikam bokhru e-Ismael u-shaaryah ve-ovadyah ve-chanan todo estes filhos-de atzel');
INSERT INTO verses VALUES (10618, 13, 8, 39, 'e-filhos-de amor-próprio irmão-dele porta-larga filho-primogênito-seu Yôsh o-segundo e-Eliphelet o terceiro');
INSERT INTO verses VALUES (10619, 13, 8, 40, 'e-eles-foram filhos-de porta-larga homens giborê- Chayil dôrchei arco e-muitos filhos e-filhos-de filhos cem e-cinquenta todo estes de-filhos-de בִנְיָמִֽן׃');
INSERT INTO chapters VALUES (347, 13, 9, 44);
INSERT INTO verses VALUES (10620, 13, 9, 1, 'e-todo Israel se-fizeram-justos e-eles escritos sobre livro reis-de Israel e-Juda foram-exilados para-Babilônia por-meio-de-eles:');
INSERT INTO verses VALUES (10621, 13, 9, 2, 'e-os-que-habitavam os-primeiros que na-sua-posse em-cidades-de-eles Israel os-sacerdotes os-levitas e-os-Neteuim');
INSERT INTO verses VALUES (10622, 13, 9, 3, 'e em jerusalém vivem de filhos-de Judá e-de filhos-de Benjamim e-de filhos-de Efraim e manassés:');
INSERT INTO verses VALUES (10623, 13, 9, 4, 'utai filho-de ammiud filho-de amarai filho-de imri filho-de filhos-de Perez filho-de Judá');
INSERT INTO verses VALUES (10624, 13, 9, 5, 'e-de ha-Shiloni asaya o primogênito e-banav');
INSERT INTO verses VALUES (10625, 13, 9, 6, 'e-de filhos-de Zerá Yeuel e-irmãos-deles seis-de centenas e-nove-dez-verso');
INSERT INTO verses VALUES (10626, 13, 9, 7, 'e-de filhos-de Binyamin Salu filho-de Meshullam filho-de Hodaviah filho-de ha-Sneah');
INSERT INTO verses VALUES (10627, 13, 9, 8, 'e-yibniah filho-de Yeroham- ve-elah filho-de uzzi filho-de mikri umeshullam filho-de Sefatias filho-de רְעוּאֵל filho-de yibniyah');
INSERT INTO verses VALUES (10628, 13, 9, 9, 'va-achehem le-toldotam nove centenas e cinquenta e-seis todo estes homens topos-de pais segundo-casa-de אֲבֹתֵיהֶֽם׃');
INSERT INTO verses VALUES (10629, 13, 9, 10, 'e-de o-sacerdotes yedayaiah vi-yohyarib veyakin');
INSERT INTO verses VALUES (10630, 13, 9, 11, 'e-Azariah filho-de Chilquiah filho-de Mesulão filho-de Zadoq filho-de meriyot filho-de Ahitub negid casa Elohim');
INSERT INTO verses VALUES (10631, 13, 9, 12, 'e-Adajah filho-de Yeroham- filho-de Pascur filho-de Malquiah e-ma''asi filho-de Adiel filho-de retornará filho-de Mesulão filho-de reparadora filho-de disse');
INSERT INTO verses VALUES (10632, 13, 9, 13, 'e-os-seus-irmãos cabeças para-casa-de pais-deles mil e-sete centenas e-sessenta gibbori exército trabalho serviço casa-de Elohim');
INSERT INTO verses VALUES (10633, 13, 9, 14, 'e-de- os-levitas ouvinte-de-Yahweh filho-de importante filho-de ajude-o-povo filho-de chasbiyah de filhos-de Merari');
INSERT INTO verses VALUES (10634, 13, 9, 15, 've-baqvar chereshe ve-galal u-matanyah filho-de mikhaa filho-de memória-minha filho-de אָסָֽף׃');
INSERT INTO verses VALUES (10635, 13, 9, 16, 've-ovadyah filho-de shemiyah filho-de galal filho-de yedutun [הַיּוֹשֵׁ֖ב] filho-de Ezequias filho-de Elcana o-que-habita');
INSERT INTO verses VALUES (10636, 13, 9, 17, '[וְהַשֹּׁעֲרִים֙] [שַׁלּ֣וּם] [וְעַקּ֔וּב] [וְטַלְמֹ֖ן] [וַאֲחִימָ֑ן] [וַאֲחִיהֶ֥ם] shalum הראש׃');
INSERT INTO verses VALUES (10637, 13, 9, 18, 'e-até elas em-porta-de o-rei mizraha eles ha-sha-arei lemachanot filhos-de Levi');
INSERT INTO verses VALUES (10638, 13, 9, 19, 'veshalum filho-de qore filho-de evyasaaf filho-de qorach sobre para-casa-de אביו hakarchim sobre trabalho haavodah שמרי yhwh laohel vaabotehem sobre acampamento-de yhwh guardadores-de o-entrando-verso-final');
INSERT INTO verses VALUES (10639, 13, 9, 20, 'e-Pinchas filho-de Elazar ser foi sobre-eles yhwh יְהוָה com-ele');
INSERT INTO verses VALUES (10640, 13, 9, 21, 'Zacarias filho Meslimia porta-guarda entrada-de para-tenda encontro');
INSERT INTO verses VALUES (10641, 13, 9, 22, 'kullem habburirim l''shsha''rim basippim duzentos ushnem dez הן b''chatsreyhem hityachshuwm eles yisda Davi uShmu''el o-Haroe be''emunatam');
INSERT INTO verses VALUES (10642, 13, 9, 23, 'e-eles e-os-filhos-deles sobre os-portães para-casa-de yhwh para-a-casa-de ha-o-hel para-as-guardas');
INSERT INTO verses VALUES (10643, 13, 9, 24, 'para-quatro ventos serão das-portas do-leste ao-poente setentrionalmente e-meridionalmente');
INSERT INTO verses VALUES (10644, 13, 9, 25, 'va-achei-hem be-chatzreihem la-bo le-shiv''ata ha-yamim מֵעֵ֥ת a Tempo com Estas');
INSERT INTO verses VALUES (10645, 13, 9, 26, 'que [בֶאֱמוּנָ֞ה] eles [אַרְבַּ֙עַת֙] [גִּבֹּרֵ֣י] [הַשֹּׁעֲרִ֔ים] eles os-levitas e-sejam sobre dos tronos： e-sobre [בֵּ֥ית] casa Elohim');
INSERT INTO verses VALUES (10646, 13, 9, 27, '[וּסְבִיב֥וֹת] casa-de Elohim [כִּֽי־עֲלֵיהֶ֣ם] porque em-eles de-serviço e-eles sobre ve-labberak para-a-manhã:');
INSERT INTO verses VALUES (10647, 13, 9, 28, 'e-de-eles sobre instrumentos-de a-obra porque em-número os-trarão-eles-os e-em-número e-sairão-eles-os');
INSERT INTO verses VALUES (10648, 13, 9, 29, 'e-de-eles designados sobre os-vasos e-sobre todo instrumentos-de a-santidade e-sobre a-selva e o vinho e a gordura e o incenso e as especiarias:');
INSERT INTO verses VALUES (10649, 13, 9, 30, 'e-de filhos-de os-sacerdotes as perfumistas da perfumaria para as especiarias:');
INSERT INTO verses VALUES (10650, 13, 9, 31, 'e Matitias de ele ele o primogênito para o pagamento o quebrado sobre sobre obra-de as junturas:');
INSERT INTO verses VALUES (10651, 13, 9, 32, 'e-de filhos-de o-que-pertence-a-Kehath de os-irmãos-deles sobre pão a arranjada para-preparar sábado sábado:');
INSERT INTO verses VALUES (10652, 13, 9, 33, 'e-estes os informantes cabeças-de pais para os levitas pelos lados porque de-dia e na-noite sobre-eles na-trabalho');
INSERT INTO verses VALUES (10653, 13, 9, 34, 'Estas cabeças-de os-pais [לַלְוִיִּ֛ם] para-as-gerações-deles cabeças-de Estas viveram em-Jerusalém');
INSERT INTO verses VALUES (10654, 13, 9, 35, 'e-em-Gibeão viveram avi- Gibeom e-nome-de mulher-sua ma''akah');
INSERT INTO verses VALUES (10655, 13, 9, 36, 'e-no-seu-filho o primogênito Abdôn e-Salmo e-Kish e-baal e-Ner e-Neftali');
INSERT INTO verses VALUES (10656, 13, 9, 37, 'e-Gedor e-Achiyo u-Zekaryah u-Miklot');
INSERT INTO verses VALUES (10657, 13, 9, 38, 'e suas caixas gerou a Shimam diante Eles Neged Acheyhem viveram Bi-Rushalaim com irmãos-deles');
INSERT INTO verses VALUES (10658, 13, 9, 39, 'Ve-Ner gerou a קיס e-Qish gerou a שָׁאוּל e-Saul holid a Yehonatan e-a malqu-i- shua- e-a Avinadav e-a esch-baal-');
INSERT INTO verses VALUES (10659, 13, 9, 40, 'e-filho-de yehonatan meriv o-dono umeri- baal gerou a mica-');
INSERT INTO verses VALUES (10660, 13, 9, 41, 'e-filhos-de micha pithon e-o-rei e-tachre''');
INSERT INTO verses VALUES (10661, 13, 9, 42, 'e-ahaz gerou a ya''arah e-ya''arah ele-gerou a alemeth e-a Azmavete e-a zimri e-zimri gerou a motza''');
INSERT INTO verses VALUES (10662, 13, 9, 43, 'umotza gerou a binoa urafaya filho-dele elasa filho-dele atzele filho-seu');
INSERT INTO verses VALUES (10663, 13, 9, 44, 'ulatzele seis filhos e-estes shmotam azrikam bokhru e-Ismael usharya veovadya e-hananim estes Estas atsal.');
INSERT INTO chapters VALUES (348, 13, 10, 14);
INSERT INTO verses VALUES (10664, 13, 10, 1, 'e-filisteus nichlachu na-isaarãel e-fugiu אִישׁ- de-diante-de de-diante-de filisteus vayippolu traspassados em-monte-de gilboa:');
INSERT INTO verses VALUES (10665, 13, 10, 2, 'vayyadbuqu filisteus atrás-de emprestado e-depois-de seus-filhos e-eles-feriram פְלִשְׁתִּ֗ים a jonatan e-a abinadab e-a malchi- Sua filhos-de שָׁאוּל');
INSERT INTO verses VALUES (10666, 13, 10, 3, 'e-ela-se-tornou-pesada a-guerra sobre Shaul e-eles-o-encontraram os-mirra em-a-seda e-ele-iniciou de os-flechas');
INSERT INTO verses VALUES (10667, 13, 10, 4, 'E-disse Saulo a levante-se seus utensílios desperte sua espada, e me esfaquele nela para-que-não entraram as arélas estes e se contendassem - em-mim e-não abateu-se que temer muito temendo E-tomou E-tomou Saul a a-espada e caiu sobre-ela');
INSERT INTO verses VALUES (10668, 13, 10, 5, 'E-viu levando- que porque morreu שָׁאוּל e-caiu também ele sobre a-espada E-morreu');
INSERT INTO verses VALUES (10669, 13, 10, 6, 'E-morreu Saul e-três-de filhos-dele e-todo casa-dele juntos morreram');
INSERT INTO verses VALUES (10670, 13, 10, 7, 'e-viram todo homem Israel que no-valle porque foram e-se morram Saul e-seus-filhos e-eles-abandonaram as-cidades-deles e-eles-fugiram e-vieram fishtim e-habitaram neles');
INSERT INTO verses VALUES (10671, 13, 10, 8, 'e-houve de-amanhã e-vieram filisteus para-despir a os-mortos e-os-acharam a Saul e-a filhos-dele caindo em-monte-de gibea');
INSERT INTO verses VALUES (10672, 13, 10, 9, 'e-eles-o-despiram e-levantaram a cabeça-sua e-a seu recipiente e-eles-o-enviaram em-terra- filisteus ao-redor para-vesti-los a de-seus-idolos e-a o-povo');
INSERT INTO verses VALUES (10673, 13, 10, 10, 'e-eles-postaram a utensílios-dele casa elohim-deles e-a seu-calvario fixaram casa dagom');
INSERT INTO verses VALUES (10674, 13, 10, 11, 'e-ouviram todo Jabes גִּלְעָ֑ד a todo que fizeram dos-filisteus para-saulo');
INSERT INTO verses VALUES (10675, 13, 10, 12, 'e-ele-levantou-se todo homem força e-ele-alçou a tumba שָׁאוּל e-את tumbas filhos-dele e-eles-lhes-levaram javesh debaixo a ossos-deles em-lugar-de a-árvore em-o-seco e-eles-abstiveram-se sete dias');
INSERT INTO verses VALUES (10676, 13, 10, 13, 'E-morreu Saul em-a-avareza que avariou em-יהוה sobre yhwh yhwh que não guardou e-também para-pedir com-o-tamagô para-pesquisar');
INSERT INTO verses VALUES (10677, 13, 10, 14, 'e-não pesquisou em-יהוה e-ele-matou-o e-conduziu a o-reino a-Davi filho-de Jessé');
INSERT INTO chapters VALUES (349, 13, 11, 47);
INSERT INTO verses VALUES (10678, 13, 11, 1, 'e-se-reuniram todo Israel a dizendo eis dizendo behold a-tua-própria e-com-a-carne-de-teu nós-verso');
INSERT INTO verses VALUES (10679, 13, 11, 2, 'também temporalmente também antes-dois-dias também sendo tu rei tu aquele que trazia E-disse yhwh Israel a-ti tu Elohim-teu para-ti אַתָּ֨ה pastorear a meu-povo sobre Israel e-tu será príncipe sobre povo-meu Israel');
INSERT INTO verses VALUES (10680, 13, 11, 3, 'e-vieram todo anciãos-de Israel a o-rei a-eles e cortou para eles Davi em-o-brith yhwh diante-de yhwh e ungiram a Davi yhwh sobre Israel conforme-palavra-de yhwh por-mão-de Shemuel:');
INSERT INTO verses VALUES (10681, 13, 11, 4, 'E-andou David e-todo Israel Jerusalém ela Jebus e ali o Jebusiense a-terra a-terra');
INSERT INTO verses VALUES (10682, 13, 11, 5, 'e-disseram habitantes-de Jebus a David não vires aqui-estes e-ele-capturou Davi a de-a-cidadela Sião ela cidade Davi');
INSERT INTO verses VALUES (10683, 13, 11, 6, 'E-disse Davi todo o que atinge Jebusiense será será a cabeça e a cintura e-subiu בָּרִאשׁוֹנָה Joab e-houve formada E-foi לְרֹֽאשׁ׃');
INSERT INTO verses VALUES (10684, 13, 11, 7, 'e-habitou David [בַּמְצָ֑ד] sobre assim [עִ֥יר] a-ele cidade Davi');
INSERT INTO verses VALUES (10685, 13, 11, 8, 'E-edificou a-cidade de-ao-redor de o-millu e-até [יְחַיֶּ֖ה] [אֶת־שְׁאָ֥ר] [הָעִֽיר] a resto a-cidade');
INSERT INTO verses VALUES (10686, 13, 11, 9, 'E-andou David indo e-grande v''yhwh de-exércitos com-ele');
INSERT INTO verses VALUES (10687, 13, 11, 10, 've-Eleh cabeças-de os-guerra-ros que para-davíd os-auxiliados com-ele na-sua-majestade com todo Israel yhwh conforme-palavra-de yhwh sobre Israel');
INSERT INTO verses VALUES (10688, 13, 11, 11, 'e-estes número os-guerra-ros que para-davíd jurarão filho-de sabedoria-sua cabeça ele acordar a seu-camastro sobre três- centenas traspassado em-páh-am uma');
INSERT INTO verses VALUES (10689, 13, 11, 12, 'e-depois-dele Eleazar filho-de dó-dó ele ele bis-hlós-áh os-valentes');
INSERT INTO verses VALUES (10690, 13, 11, 13, 'ele foi com dávid báf-ps dám-mí vé-haf-lísht-tím nés-apú- nome para-a-guerra váthí- campo-de o-campo cheia de-diante-de e-o-povo levantaram-se de-faces-de Filisteus');
INSERT INTO verses VALUES (10691, 13, 11, 14, 'vái-tiyats-bú no-meio-de a-hálekha vayatsiluhu e-eles-feriram a yhwh vayoshua yhwh tshu''ah g''dolah');
INSERT INTO verses VALUES (10692, 13, 11, 15, 'vayeredu shlosha de hashloshim cabeça sobre ha-tsur a Davi a me''arah עֲדֻלַּם וּמַחֲנֶה filisteus חֹנָה na-vale refains');
INSERT INTO verses VALUES (10693, 13, 11, 16, 've-David então בַּמְצוּדָה [וּנְצִ֣יב] filisteus então em-casa-de pão');
INSERT INTO verses VALUES (10694, 13, 11, 17, 'David E-disse quem יַשְׁקֵנִי quem מִבּ֥וֹר águas pão que בַּשַּׁעַר׃');
INSERT INTO verses VALUES (10695, 13, 11, 18, 'וַיִּבְקְע֨וּ as três em-acampamento-de פְלִשְׁתִּ֗ים e-apa-receram-se águas do poço casa-de pão que no-saar va-yis-av-u e-ele-trouxeu a Davi e-não eles Davi para-lessem-no e-nasch eles para-יהוה');
INSERT INTO verses VALUES (10696, 13, 11, 19, 'E-disse chaliyla: a-mim de-Elohei de-achot esta הֲדַ֣ם os-anashim: estas-hale eu beber em suas almas que em suas almas e trouxeram-los e-não pai para beberem-lhes Estas fizeram três os valentes:');
INSERT INTO verses VALUES (10697, 13, 11, 20, 'וְאַבְשַׁ֣י meu-irmão- ele ser foi cabeça as três e-ele acordar a o-carro sobre três centenas traspassado nome na terceira:');
INSERT INTO verses VALUES (10698, 13, 11, 21, 'de [בַשְּׁנַ֙יִם֙] [נִכְבָּ֔ד] e-houve a-eles a-eles para-Sar e-até não veio');
INSERT INTO verses VALUES (10699, 13, 11, 22, '[בְּנָיָ֨ה] filho-de Joia-da filho-de אִישׁ- ele chefe-de [OBJ] de [אֲרִיאֵל֙] ele הִכָּה a segundo [אֶֽת־הָאֲרִ֛י] no-meio-de ve-hu yarad ve-hikka a em-meio-de em-dia ha-shagle');
INSERT INTO verses VALUES (10700, 13, 11, 23, 'e-ele hikka a o-homem [מִדָּ֣ה] homem [חָמֵ֣שׁ] cinco na-cubit [הַמִּצְרִ֤י] [חֲנִית֙] [כִּמְנ֣וֹר] [אֹרְגִ֔ים] [וַיֵּ֥רֶד] a-ele a-ele beshávet vayigzól a chániyt de-mão-de o-egípcio vayehargéhu báchániyt');
INSERT INTO verses VALUES (10701, 13, 11, 24, 'Estas fez baniyahu filho-de Yehoyada e-para-ele- nome os-valentes');
INSERT INTO verses VALUES (10702, 13, 11, 25, 'de הַשְׁלֹשִׁים הִנֵּה ele ele e-a הַשְׁלֹשָׁה não veio e o colocou dizendo sobre de sua ouvência:');
INSERT INTO verses VALUES (10703, 13, 11, 26, 'e os valentes dos soldados ele-fez El Ai יוֹאָב Elcana filho-de seu primo de-casa-de pão');
INSERT INTO verses VALUES (10704, 13, 11, 27, 'Shammoth do Horei Chelatz הפלוני׃');
INSERT INTO verses VALUES (10705, 13, 11, 28, '[עִירָ֤א] filho-de [הַתְּקוֹעִ֔י] [אֲבִיעֶ֖זֶר] Abiezéu');
INSERT INTO verses VALUES (10706, 13, 11, 29, 'סִבְּכַי a minhoca [עִילַ֖י] [הָאֲחוֹחִֽי׃]');
INSERT INTO verses VALUES (10707, 13, 11, 30, 'mahray a-n-t-o-p-a-t-i hdl filho-de בענה a-nettofati:');
INSERT INTO verses VALUES (10708, 13, 11, 31, 'i-tai filho-de ri-bai mi-gibat filhos-de Benjamim be-naya a-paratoni:');
INSERT INTO verses VALUES (10709, 13, 11, 32, 'chu-ai מִנַּ֣חֲלֵי ga-as avi-el ha-arebat:');
INSERT INTO verses VALUES (10710, 13, 11, 33, '[עַזְמָ֙וֶת֙] [הַבַּ֣חֲרוּמִ֔י] [אֶלְיַחְבָּ֖א] [הַשַּׁעַלְבֹנִֽי׃]');
INSERT INTO verses VALUES (10711, 13, 11, 34, 'filhos-de [הָשֵׁם֙] [הַגִּ֣זוֹנִ֔י] [יוֹנָתָ֥ן] filho-de [הַהֲרָרִֽי׃]');
INSERT INTO verses VALUES (10712, 13, 11, 35, 'אֲחִיאָ֧ם filho-de שָׂכָ֛ר o harári elifal filho-de luz');
INSERT INTO verses VALUES (10713, 13, 11, 36, 'chafar o mikeratáti achiya הפלוני׃');
INSERT INTO verses VALUES (10714, 13, 11, 37, 'chetsero o karmeli náray filho-de ezvay');
INSERT INTO verses VALUES (10715, 13, 11, 38, '[יוֹאֵל֙] Ai deu [מִבְחָ֖ר] filho-de');
INSERT INTO verses VALUES (10716, 13, 11, 39, 'צֶלֶק [הָעַמּוֹנִ֑י] נַחְרַי [הַבֵּ֣רֹתִ֔י] [נֹשֵׂ֕א] kléi- Joab filho-de צְרוּיָה');
INSERT INTO verses VALUES (10717, 13, 11, 40, 'עִירָא הַיּוֹתֵרִי גָּרֵב o sobrante׃');
INSERT INTO verses VALUES (10718, 13, 11, 41, 'Ário ha-khitti זָבָ֖ד filho-de Alai');
INSERT INTO verses VALUES (10719, 13, 11, 42, '[עֲדִינָ֨א] filho-de [הָרֽאוּבֵנִ֗י] [רֹ֛אשׁ] cabeça para-reuveni sobre ele');
INSERT INTO verses VALUES (10720, 13, 11, 43, '[חָנָן֙] filho-de Maaca [הַמִּתְנִֽי׃]');
INSERT INTO verses VALUES (10721, 13, 11, 44, 'עֻזִיָּ֖א a-aşšartáti ouviu filhos-de חוטם הערוריה׃');
INSERT INTO verses VALUES (10722, 13, 11, 45, 'yediael filho-de [וְיֹחָ֥א] [אָחִ֖יו] irmão-seu');
INSERT INTO verses VALUES (10723, 13, 11, 46, '[אֱלִיאֵל֙] [הַֽמַּחֲוִ֔ים] [וִירִיבַ֥י] [וְיוֹשַׁוְיָ֖ה] filhos-de [אֶלְנָ֑עַם] [וְיִתְמָ֖ה] [הַמּוֹאָבִֽי]');
INSERT INTO verses VALUES (10724, 13, 11, 47, '[אֱלִיאֵ֣ל] [וְעוֹבֵ֔ד] [וְיַעֲשִׂיאֵ֖ל] [הַמְּצֹבָיָֽה׃]');
INSERT INTO chapters VALUES (350, 13, 12, 41);
INSERT INTO verses VALUES (10725, 13, 12, 1, 'e-estes os-vindo a Davi [ע֣וֹד] ainda de-diante-de de-face-de Saul filho-de [בַּגִּבּוֹרִ֔ים] e-eles [הַמִּלְחָמָֽה] ha-milchamah');
INSERT INTO verses VALUES (10726, 13, 12, 2, 'נֹ֣שְׁקֵי קֶשֶׁת maidsim usamalim ba''avanim ubachitzim bakqashet מֵאֲחֵ֥י emprestado mivnayamin');
INSERT INTO verses VALUES (10727, 13, 12, 3, 'hara''ash achiezer ve''yoshi'' filhos-de hashma''ah a-cúpula e-Pelet filhos-de a-ferro e-a-bênção e-Jeú a-resposta');
INSERT INTO verses VALUES (10728, 13, 12, 4, 'וְיִֽשְׁמַֽעְיָ֧ה o-cupulário heroi- em-trinta e-sobre os-trinta');
INSERT INTO verses VALUES (10729, 13, 12, 5, 'e-irmá e-jaciel e-joão וְיוֹזָבָ֖ד הַגְּדֵרָתִֽי׃');
INSERT INTO verses VALUES (10730, 13, 12, 6, '[אֶלְעוּזַ֤י] [וִירִימוֹת֙] [וּבְעַלְיָ֣ה] [וּשְׁמַרְיָ֔הוּ] [וּשְׁפַטְיָ֖הוּ]');
INSERT INTO verses VALUES (10731, 13, 12, 7, '[אֶלְקָנָ֡ה] [וְ֠יִשִׁיָּהוּ] [וַעֲזַרְאֵ֧ל] [וְיוֹעֶ֛זֶר] [וְיָשָׁבְעָ֖ם] [הַקָּרְחִֽים]');
INSERT INTO verses VALUES (10732, 13, 12, 8, '[וְיוֹעֵאלָ֧ה] [וּזְבַדְיָ֛ה] filhos-de [יְרֹחָ֖ם] de');
INSERT INTO verses VALUES (10733, 13, 12, 9, 'e-de [נִבְדְּל֣וּ] [אֶל־דָּוִיד֩] a Davi  [גִּבֹּרֵ֣י] [הַחַ֗יִל] [אַנְשֵׁ֤י] exército homens-de [עֹרְכֵ֥י] para-a-guerra [וָרֹ֑מַח] tinah [אַרְיֵה֙] e-faces a-rí-e suas faces [לְמַהֵֽר׃] sobre');
INSERT INTO verses VALUES (10734, 13, 12, 10, 'auxiliar a-cabeça [עֹבַדְיָה֙] o-segundo Eliabe o terceiro');
INSERT INTO verses VALUES (10735, 13, 12, 11, '[מִשְׁמַנָּה֙] o-quarto [יִרְמְיָ֖ה] [הַחֲמִשִֽׁי]');
INSERT INTO verses VALUES (10736, 13, 12, 12, '[עַתַּי֙] o-sexto Eliel- o-sétimo');
INSERT INTO verses VALUES (10737, 13, 12, 13, '[יֽוֹחָנָן֙] o-oitavo [אֶלְזָבָ֖ד] [הַתְּשִׁיעִֽי]');
INSERT INTO verses VALUES (10738, 13, 12, 14, 'Jeremias o-tenth [ס] [מַכְבַּנַּ֖י] dez');
INSERT INTO verses VALUES (10739, 13, 12, 15, 'Estas מִבְנֵי- Gad cabeças-de um um לְמֵאָה o pequeno וְהַגָּדוֹל לְאָלֶף׃');
INSERT INTO verses VALUES (10740, 13, 12, 16, 'Estas eles que עָבְרוּ a o-Jordão no-mês harishon e-ele que preenche sobre todo e fugiram a todo as profundezas para o oriente e para o ocidente:');
INSERT INTO verses VALUES (10741, 13, 12, 17, 'e-vieram de filhos-de Benjamim e-Yehuda até para a fortaleza a Davi:');
INSERT INTO verses VALUES (10742, 13, 12, 18, 'e-saiu Davi diante deles, e-respondeu E-disse a-eles se para a paz vocês vieram a-mim para auxiliá- me ele-será- para mim sobre-vós coração לְיָחַד וְאִֽם־ para me exaltar para me irritar sem injustiça nas minhas mãos ele verá Elohim-de nosso pais וְיוֹכַֽח׃');
INSERT INTO verses VALUES (10743, 13, 12, 19, 'e-Espírito-de [לָבְשָׁ֗ה] a [רֹ֣אשׁ] cabeça para-ti a-ti [דָוִיד֙] filho-de -Isai [שָׁל֨וֹם] [׀] para-ti a-ti [וְשָׁלוֹם֙] porque que teu-Elohim [Elohim] Davi e-colocou-os no-princípio [בְּרָאשֵׁ֥י]');
INSERT INTO verses VALUES (10744, 13, 12, 20, '[וּמִֽמְּנַשֶּׁ֞ה] caíram sobre david בְּבֹא֨וֹ com פלשתים sobre Shaul que e-não [שִׁלְּחֻ֜הוּ] porque [פְלִשְׁתִּים֙] dizendo [בְּרָאשֵׁ֕ינוּ] filisteus dizendo [שָׁאֽוּל] a אדוניו שָׁאוּל');
INSERT INTO verses VALUES (10745, 13, 12, 21, 'בַּלֶּכְתּוֹ a Tsiklag caíram sobre ele de Manassés Adonac e Jozabad e Idaiel e Michael e Jozabad e Eliuá e Ziltai topos-de os milhares que para manassés:');
INSERT INTO verses VALUES (10746, 13, 12, 22, 'e-elas ajudem com Davi sobre o corpo de tropas porque valentes valor todos eles e-foram capitães no exército:');
INSERT INTO verses VALUES (10747, 13, 12, 23, 'que na época de dia no dia virão sobre David para ajudá-lo até para-acampamento-de grande como-cânea Elohim');
INSERT INTO verses VALUES (10748, 13, 12, 24, 'e-elas contados cabeças-de o-primeiro la-tzava viram sobre David Cerovã para-virar real a-ele a-ele yhwh yhwh');
INSERT INTO verses VALUES (10749, 13, 12, 25, 'filhos-de Judá carregadores-de ziná e-romach שֵׁ֧שֶׁת milhares e-še-mōne centenas chă-luțe exército');
INSERT INTO verses VALUES (10750, 13, 12, 26, 'de filhos-de Shimon- gibbôrē חַ֙יִל֙ la-tzava sete milhares e cem:');
INSERT INTO verses VALUES (10751, 13, 12, 27, 'de filhos-de o-levita quatro dois-mil e-seis centenas');
INSERT INTO verses VALUES (10752, 13, 12, 28, 'vı̂-yo-yāda hăn-na-gid lê-ă-ha-rôn e-o três milhares e-sete centenas');
INSERT INTO verses VALUES (10753, 13, 12, 29, 'e-Sadoque menino homem força e-casa-de ă-bi-yō sārîm vinte e-dois');
INSERT INTO verses VALUES (10754, 13, 12, 30, 'e-de filhos-de binyāmîn irmãos-de emprestado três-de milhares e-até eis-aqui מרביתם שמורים guarda-de casa שָׁאוּל');
INSERT INTO verses VALUES (10755, 13, 12, 31, 'e-de filhos-de Efraim vinte mil e oitava centenas gibbori valente homens-de [לְבֵ֥ית] segundo-casa-de avos-eus');
INSERT INTO verses VALUES (10756, 13, 12, 32, '[וּמֵחֲצִי֙] tribo-de Manassés shmonáh dez mil que [נִקְּבוּ֙] em-os-nomes para-vir [לְהַמְלִ֥יךְ] a Davi');
INSERT INTO verses VALUES (10757, 13, 12, 33, 'וּמִבְּנֵ֣י יששכר ידעו בינה para os tempos para-conhecer que faz Israel seus cabeças duzentos e-todo irmaos-deles sobre suas bocas:');
INSERT INTO verses VALUES (10758, 13, 12, 34, 'de um buraco que saem exército fabricantes de milchama em-todo instrumentos-de guerra cinquenta mil e para Ador sem coração e o coração');
INSERT INTO verses VALUES (10759, 13, 12, 35, 'e de Naphtali שַׂרִים mil e com eles no deserto e Chanat trinta e sete mil');
INSERT INTO verses VALUES (10760, 13, 12, 36, 'e-de o Dan os que fazem guerra vinte- e oito mil e-seis centenas');
INSERT INTO verses VALUES (10761, 13, 12, 37, 'e de Asher יוֹצְאֵ֥י exército לַעֲרֹ֥ךְ guerra quarenta mil');
INSERT INTO verses VALUES (10762, 13, 12, 38, '[וּמֵעֵ֣בֶר] [לַ֠יַּרְדֵּן] de [וְהַגָּדִ֜י] [וַחֲצִ֣י] vaḥatsi  tribo-de Menasheh em-todo utensílios-de exército-de guerra cem e-vinte mil');
INSERT INTO verses VALUES (10763, 13, 12, 39, 'todo estas homens-de מִלְחָמָה֮ עֹדְרֵ֣י מַעֲרָכָה֒ no-lévabá שָׁלוֹם vieram chevroná para-malík a David sobre todo Israel um todo shérít Israel coração um ele a Davi');
INSERT INTO verses VALUES (10764, 13, 12, 40, 'vayyihyu- nome com Davi dias sháloshá oçlím a-eles porque hecínu a-eles irmãos-deles');
INSERT INTO verses VALUES (10765, 13, 12, 41, 'e-também [הַקְּרֽוֹבִים־אֲ֠לֵיהֶם] אֲ֠לֵיהֶם até [וְנַפְתָּלִ֗י] [מְבִיאִ֣ים] pão meviim [וּבַגְּמַלִּ֣ים] [וּבַפְּרָדִ֣ים] [׀] [וּֽבַבָּקָ֡ר] alimento [קֶ֠מַח] [דְּבֵלִ֨ים] [וְצִמּוּקִ֧ים] [וְיַֽיִן־וְשֶׁ֛מֶן] [וּבָקָ֥ר] [וְצֹ֖אן] [לָרֹ֑ב] que em-abundância porque em-Israel');
INSERT INTO chapters VALUES (351, 13, 13, 14);
INSERT INTO verses VALUES (10766, 13, 13, 1, '[וַיִּוָּעַ֣ץ] david com chefes-de [וְהַמֵּא֖וֹת] e dos centenas para-todo');
INSERT INTO verses VALUES (10767, 13, 13, 2, 'E-disse דּוֹוִד a-todo assembleia Israel se em-vocês bom e-de yhwh nosso-Elohim [נִשְׁלְחָ֞ה] [עַל־אַחֵ֣ינוּ] sobre irmãos-nossos [אַרְצ֣וֹת] em-todo [וְעִמָּהֶ֛ם] Israel e-com-ela os-sacerdotes e-os-levitas em-cidades-de [אֵלֵֽינוּ] a-nós');
INSERT INTO verses VALUES (10768, 13, 13, 3, '[וְנָסֵ֛בָּה] a arca Elohim-nosso a-nós porque não [שָׁאֽוּל] nos-dias שָׁאוּל');
INSERT INTO verses VALUES (10769, 13, 13, 4, 'e-disseram todo a-congregação para fazer assim porque yashar a palavra em-olhos-de todo o-povo');
INSERT INTO verses VALUES (10770, 13, 13, 5, '[וַיַּקְהֵ֤ל] Davi a todo Israel de [חֲמָ֑ת] Egito e-até le-bo calor-fervente para-trazer a arca os-Elohim de-cidade Jearim');
INSERT INTO verses VALUES (10771, 13, 13, 6, 'e-subiu Davi e-todo Israel בַּעֲלָתָה a Quiriate de-árvores que a judá para-levar-acima de-lá את arca-de yhwh yhwh habitante הַכּוֹרְבִים que foi-chamado nome');
INSERT INTO verses VALUES (10772, 13, 13, 7, '[וַיַּרְכִּ֜יבוּ] a arca o-Elohim sobre carroça nova da-casa [וְאַחְי֔וֹ] e-Uza e-Achiyo nohagim');
INSERT INTO verses VALUES (10773, 13, 13, 8, 'e-dá-ví- e-todo Israel mescháqâkîm diante-de Elohim em-todo ó'' e-bé-she-rí- e-békinnôrôt'' e-com-harpas e-em-tumpos e-bém-tsíl-tá''im e-bá-ḥătsó-tsôrôt:');
INSERT INTO verses VALUES (10774, 13, 13, 9, 'e-vieram até aranha-de [וַיִּשְׁלַ֨ח] e-enviou o-azom a mão-sua que a o-arca porque os-bois');
INSERT INTO verses VALUES (10775, 13, 13, 10, 'e-acendeu-se- yhwh yhwh [וַיַּכֵּ֕הוּ] sobre sobre sua-mão enviou mão-sua sobre a-arca e-morreu nome diante-de Elohim');
INSERT INTO verses VALUES (10776, 13, 13, 11, 'e-acendeu-se [לְדָוִ֔יד] porque yhwh yhwh פֶּרֶץ E-chamou E-chamou para-o-lugar o-aquele Perez até o-dia o-dia a-esta');
INSERT INTO verses VALUES (10777, 13, 13, 12, 'e-temeu Davi a no-dia no-dia dizendo dizendo [אָבִ֣יא] trarei a-mim a arca Elohim');
INSERT INTO verses VALUES (10778, 13, 13, 13, 'e-não [דָּוִ֧יד] דָּוִד a-ele [אֶל־עִ֣יר] a-ele a cidade Davi [הַגִּתִּֽי] a casa servo-de homem o-giti');
INSERT INTO verses VALUES (10779, 13, 13, 14, 'e-ele-estabeleceu-se arca-de os-אלהים com casa servo homem em-casa-dele três E-abençoou yhwh yhwh a casa servo-de homem e-a todo que a-ele');
INSERT INTO chapters VALUES (352, 13, 14, 17);
INSERT INTO verses VALUES (10780, 13, 14, 1, 'e-yi-shelakh rei-de tsor mensageiros a Davi ve-a-tse cedros ve-ha-rase [קִ֔יר] [וְחָרָשֵׁ֖י] עֵצִ֑ים para-construir a-ele casa');
INSERT INTO verses VALUES (10781, 13, 14, 2, 'e-soube Davi porque yhwh yhwh para-rei sobre Israel porque nisśê''et para cima reino-dele por-causa-de seu-povo Israel');
INSERT INTO verses VALUES (10782, 13, 14, 3, 'E-tomou Davi ainda mulheres em-Jerusalém e gerou Davi ainda filhos e-filhas');
INSERT INTO verses VALUES (10783, 13, 14, 4, 'e-estes nomes-de הַיְלוּדִ֔ים que eram- a-ele em-Jerusalém Shamuwa'' e-Soevav deu e-Salomoh');
INSERT INTO verses VALUES (10784, 13, 14, 5, 'e-Ibhar e-Elishua'' וְאֶלְפָּֽלֶט׃');
INSERT INTO verses VALUES (10785, 13, 14, 6, 'e-Nogah e-Nefeg e-Jafia');
INSERT INTO verses VALUES (10786, 13, 14, 7, 'e-Elishama'' וּבְעֶלְיָדָ֖ע e-Elifelet');
INSERT INTO verses VALUES (10787, 13, 14, 8, 'e-ouviram פְלִשְׁתִּ֗ים porque נִמְשַׁ֨ח Davi para-o-rei sobre todo Israel e-eles-subiram todo Filisteus para-pedir a Davi E-ouviu Davi e-ele-saiu diante-deles');
INSERT INTO verses VALUES (10788, 13, 14, 9, 'e-filisteus eles-vieram וַֽיִּפְשְׁט֖וּ na-vale refains');
INSERT INTO verses VALUES (10789, 13, 14, 10, 'e-ele-perguntou Davi בֵּאלֹהִים֙ dizendo a-eu-subirei sobre e-dar-vos-eles b''yadi E-disse E-disse a-ele yhwh folhas-de em-mão-teu');
INSERT INTO verses VALUES (10790, 13, 14, 11, 'e-eles-subiram em-Baal- e-Prazim e-os-golpeou nome E-disse E-disse Davi [הָֽאֱלֹהִ֧ים] [אֶת־אוֹיְבַ֛י] a [כְּפֶ֣רֶץ] em-a-mão-meia כְּפֶ֣רֶץ águas sobre sim [בַּ֥עַל] nome-de o-lugar o-aquele Baal Prazim.');
INSERT INTO verses VALUES (10791, 13, 14, 12, 'e-os-abandonaram- nome E-disse אֱלֹהֵיהֶם-de-eles E-disse Davi em-a-chama');
INSERT INTO verses VALUES (10792, 13, 14, 13, '[וַיֹּסִ֤יפוּ] ainda filisteus וַֽיִּפְשְׁט֖וּ ba-emek');
INSERT INTO verses VALUES (10793, 13, 14, 14, 'e-ele-perguntou ainda Davi be-elohim E-disse a-ele הָֽאֱלֹהִ֔ים não [תֽ͏ַעֲלֶ֖ה] [אֽ͏ַחֲרֵיהֶ֑ם] o-vire-se [מֵֽעֲלֵיהֶ֔ם] [וּבָ֥אתָ] a-eles de-em-frente-de [הַבְּכָאִֽים]');
INSERT INTO verses VALUES (10794, 13, 14, 15, 'e-seja [כְּֽשָׁמְעֲךָ֞] a voz [בְּרָאשֵׁ֣י] [הַבְּכָאִ֔ים] [אָ֖ז] então  תיצא [כִּֽי־יָצָ֤א] porque saiu הָֽאֱלֹהִים diante-de-ti para-golpear a acampamento-de Filisteus');
INSERT INTO verses VALUES (10795, 13, 14, 16, 'E-fez Davi como-aquela ordenou-o o-Elohim va-yakku'' a acampamento-de filisteus [וְעַד־גָּֽזְרָה] e-até');
INSERT INTO verses VALUES (10796, 13, 14, 17, 'e-ele-saiu nome-de David em-todo dar [אֶת־פַּחְדּ֖וֹ] deu a sobre todo os-gentios');
INSERT INTO chapters VALUES (353, 13, 15, 29);
INSERT INTO verses VALUES (10797, 13, 15, 1, '[וַיַּֽעַשׂ־ל֥וֹ] a-ele casas na-cidade Davi lugar lugar [הֽ͏ָאֱלֹהִ֔ים] o elohim e-esticou- para-ele');
INSERT INTO verses VALUES (10798, 13, 15, 2, 'então disse Davi não lashet a arca que porque se os-levitas porque yhwh escolheu yhwh yhwh a arca-de yhwh até eternidade');
INSERT INTO verses VALUES (10799, 13, 15, 3, 'vai-qahel Davi a todo Israel a yhwh para levá-lo a a-ele yhwh a meqom-o que hechin a-ele');
INSERT INTO verses VALUES (10800, 13, 15, 4, 'e-reuniu-se Davi a filhos-de a-aharon e-a os-levitas');
INSERT INTO verses VALUES (10801, 13, 15, 5, 'libnei Qe-hat Uriel hashar e-seus-irmãos cem e-vinte');
INSERT INTO verses VALUES (10802, 13, 15, 6, 'libnei Merari asaya-a hashar e-seus-irmãos duzentos e-vinte');
INSERT INTO verses VALUES (10803, 13, 15, 7, 'libnei gereshom-om Yoel hashar e-seus-irmãos cem e-trinta');
INSERT INTO verses VALUES (10804, 13, 15, 8, 'filhos de Elizefan Shema-yah o sar e seus irmãos duzentos');
INSERT INTO verses VALUES (10805, 13, 15, 9, 'filhos de Hebrom Eliael o sar e seus irmãos Oitenta:');
INSERT INTO verses VALUES (10806, 13, 15, 10, 'filhos Uziel Amminadab hashar e irmãos cem e-doze dez');
INSERT INTO verses VALUES (10807, 13, 15, 11, 'E-chamou Davi a Zadoque e a Abiafar הַכֹּֽהֲנִ֑ים וְלַלְוִיִּ֗ם para Uríel Ashéyah וְיוֹאֵ֣ל Shémayah e Eliel e Amminadab');
INSERT INTO verses VALUES (10808, 13, 15, 12, 'E-disse a-eles vós topos-de os avôs para-os-Levitas se santificem vós e vós mesmos e levantai-vos a arca yhwh Elohim-de Israel a a-ele a-ele');
INSERT INTO verses VALUES (10809, 13, 15, 13, 'que para a primícia não vós quebrado yhwh Elohim-nosso אֵלֶּה porque não busquemos-o como-o-julgamento');
INSERT INTO verses VALUES (10810, 13, 15, 14, 'e se santificaram os-sacerdotes e-os-levitas para levantar a yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (10811, 13, 15, 15, 'e-tomaram filhos-de os-levitas a arca הָֽאֱלֹהִ֔ים como ordenou Moisés yhwh yhwh em-suas-costas em-seus-pauzes sobre-eles');
INSERT INTO verses VALUES (10812, 13, 15, 16, 'E-disse davíd para-os-príncipes dos-levitas para-sustentar a אֲחֵיהֶם֙ aqueles-que-murmuram com-utensílios-de cântico desordeiros וְכִנֹּר֖וֹת e-metsilthayim mashmiy''im lehirim- yhwh le-simhah-:');
INSERT INTO verses VALUES (10813, 13, 15, 17, 'e-estabeleceram os-levitas a hayman filho-de Yoel e-de seus-irmãos אסף filho-de berkeyahu e-de filhos-de marari irmãos-deles Eitan filho-de kušayahu-:');
INSERT INTO verses VALUES (10814, 13, 15, 18, 'e-com-as seus-irmãos as-memórias Zacarias filho e-Úzias e-Simiramot ויחיאל e-Enni Eliau e-Benaihu e os feitos dele e Matityahu e Elishu e os bens dele e o servo homem e Ieuel os que bateram');
INSERT INTO verses VALUES (10815, 13, 15, 19, 'e os que sopram Heman Asaf וְאֵיתָ֑ן בִּמְצִלְתַּ֥יִם bronze לְהַשְׁמִֽיעַ׃');
INSERT INTO verses VALUES (10816, 13, 15, 20, '[וּזְכַרְיָ֨ה] [וַעֲזִיאֵ֜ל] [וּשְׁמִֽירָמ֤וֹת] ויחיאל [וְעֻנִּ֣י] [וֽ͏ֶאֱלִיאָ֔ב] מעשייו [וּבְנָיָ֑הוּ] com nablas sobre');
INSERT INTO verses VALUES (10817, 13, 15, 21, '[וּמַתִּתְיָ֣הוּ] [וֶאֱלִֽיפְלֵ֗הוּ] [וּמִקְנֵיָ֙הוּ֙] [וְעֹבֵ֣ד] homem [וִֽיעִיאֵ֖ל] [וַעֲזַזְיָ֑הוּ] com cetres sobre [לְנַצֵּֽחַ]');
INSERT INTO verses VALUES (10818, 13, 15, 22, 'e Canelas senhor de os-levitas em Mashae Yasar que porque ele ela');
INSERT INTO verses VALUES (10819, 13, 15, 23, 'וּבֶֽרֶךְיָה֙ e Eliacim os porteiros para o arca');
INSERT INTO verses VALUES (10820, 13, 15, 24, '[וּשְׁבַנְיָ֡הוּ] [וְיֽוֹשָׁפָ֡ט] [וּנְתַנְאֵ֡ל] [וַעֲמָשַׂ֡י] [וּ֠זְכַרְיָהוּ] [וּבְנָיָ֤הוּ] [וֽ͏ֶאֱלִיעֶ֙זֶר֙] os-sacerdotes בּ-הֲצֹ֣צְר֔וֹת diante-de arca o-Elohim [אֲר֣וֹן] homem [וְעֹבֵ֤ד] [אֱדֹם֙] [וִֽיחִיָּ֔ה]');
INSERT INTO verses VALUES (10821, 13, 15, 25, 'e-houve דָּוִד e os anciãos Israel e-príncipes-de os mil הַהֹלְכִים׃ para-fazer-subir a arca-de em-aliança-de yhwh de casa servo-de homem em-simcha');
INSERT INTO verses VALUES (10822, 13, 15, 26, 'e-aconteceu [בֶּעְזֹ֣ר] o elohim et- os-levitas carregadores-de arca em-aliança-de yhwh [וְשִׁבְעָ֥ה] [אֵילִֽים]');
INSERT INTO verses VALUES (10823, 13, 15, 27, 'וְדָוִ֞יד מְכֻרְבָּ֣ל בִּמְעִ֣יל linho-fino e-todo os-levitas הַנֹּשְׂאִ֣ים a o-arca e os que murmuram וּכְנַנְיָ֛ה הַשַּׂ֥ר הַמַּשּׂ֖א e os que murmuram e-sobre David éfode linho');
INSERT INTO verses VALUES (10824, 13, 15, 28, 'e-todo Israel [אֶת־אֲר֣וֹן] a arca em-aliança-de yhwh [וּבַחֲצֹצְר֖וֹת] [וּבִמְצִלְתָּ֑יִם] [מַשְׁמִעִ֕ים] [בִּנְבָלִ֖ים] [וְכִנֹּרֽוֹת]');
INSERT INTO verses VALUES (10825, 13, 15, 29, 'e-houve arca-de aliança yhwh veio até cidade Davi e-Mical filha-de Saul nischqapha- através-de E-viu וַתֵּ֨רֶא a o-rei Davi מְרַקֵּ֣ד a-ele וַתִּ֥בֶז para-ele belibah-');
INSERT INTO chapters VALUES (354, 13, 16, 43);
INSERT INTO verses VALUES (10826, 13, 16, 1, '[וַיָּבִ֙יאוּ֙] a arca [וַיַצִּ֣יגוּ] ele no-meio-de em-meio-de a-tenda que estendeu a-ele Davi [וּשְׁלָמִ֖ים] [לִפְנֵ֥י] [הָאֱלֹהִֽים]');
INSERT INTO verses VALUES (10827, 13, 16, 2, 'E-terminou Davi me-haalot a-holocausto e-o-sacrifício-de-paz E-abençoou a o-povo yhwh yhwh');
INSERT INTO verses VALUES (10828, 13, 16, 3, '[וַיְחַלֵּק֙] para-todo homem Israel de-homem e-até mulher para-homem [וַאֲשִׁישָֽׁה]');
INSERT INTO verses VALUES (10829, 13, 16, 4, 'E-colocou diante-de arca-de yhwh de os-levitas מְשָרְתִים וּלְהַזְכִּיר֙ וּלְהוֹדֹות e para louvar a-yhwh Elohim-de Israel');
INSERT INTO verses VALUES (10830, 13, 16, 5, 'Ásaf a-cabeça e-segundo-dele Zacharyáh Yeaíel e Shimmiramot Vieiaíel e Mattityáh Veeliáv e Beniáhu e oved homem Vieiaíel בִּכְלֵ֤י נְבָלִים֙ וּבְכִנֹּר֔וֹת וְאָסָ֖ף בַּֽמְצִלְתַּ֥יִם מַשְׁמִֽיעַ׃');
INSERT INTO verses VALUES (10831, 13, 16, 6, 'e-Benaiáhu וְיַחֲזִיאֵ֖ל os sacerdotes בַּחֲצֹצְר֣וֹת תָּמִ֔יד diante-de arca em-aliança-de Elohim');
INSERT INTO verses VALUES (10832, 13, 16, 7, 'no-dia aquele então dar Davi [בָּרֹ֔אשׁ] [לְהֹד֖וֹת] a-yhwh por-mão-de [וְאֶחָֽיו׃]');
INSERT INTO verses VALUES (10833, 13, 16, 8, 'hodu para-יהוה chorem no seu nome anunciem בעמים עלילותיו׃');
INSERT INTO verses VALUES (10834, 13, 16, 9, '[שִׁ֤ירוּ] a-ele [זַמְּרוּ־ל֔וֹ] a-ele [בְּכָל־נִפְלְאֹתָֽיו] em-todo');
INSERT INTO verses VALUES (10835, 13, 16, 10, 'hithallelu no-nome-de קדשוֹ ישמח coração מְבַקְשֵׁ֥י yhwh');
INSERT INTO verses VALUES (10836, 13, 16, 11, 'busquem yhwh וְעֻזּ֔וֹ בַּקְּשׁ֥וּ פָנָ֖יו sempre');
INSERT INTO verses VALUES (10837, 13, 16, 12, '[זִכְר֗וּ] [נִפְלְאֹתָיו֙] que fez [מֹפְתָ֖יו] [וּמִשְׁפְּטֵי־פִֽיהוּ]');
INSERT INTO verses VALUES (10838, 13, 16, 13, 'semente Israel servo-seu filhos-de Jacó בְּחִירָֽיו׃');
INSERT INTO verses VALUES (10839, 13, 16, 14, 'ele yhwh nosso-Elohim em-todo a-terra seus juízos:');
INSERT INTO verses VALUES (10840, 13, 16, 15, 'lembrai-vos para sempre aliança-dele palavra ordenou para-mil דּוֹר׃');
INSERT INTO verses VALUES (10841, 13, 16, 16, 'que como-cortei a Abraão e sua aliança: para-Yitzkhak');
INSERT INTO verses VALUES (10842, 13, 16, 17, 'e-a-עמדנה לְיַעֲקֹב֙ como lei para Israel berit eternidade');
INSERT INTO verses VALUES (10843, 13, 16, 18, 'dizendo a-ti darei terra-de como Canaã por herança sua herança:');
INSERT INTO verses VALUES (10844, 13, 16, 19, 'בִּֽהְיֽוֹתְכֶם֙ homens-de de-número כִּמְעַ֖ט וְגָרִ֥ים nela');
INSERT INTO verses VALUES (10845, 13, 16, 20, 'e andaram מִגּ֣וֹי a nação וּמִמַמְּלָכָ֖ה a povo outro');
INSERT INTO verses VALUES (10846, 13, 16, 21, 'não [לְאִישׁ֙] para-homem [וַיּ֥וֹכַח] [עֲלֵיהֶ֖ם] sobre-eles');
INSERT INTO verses VALUES (10847, 13, 16, 22, 'a תִּגְּעוּ֙ em-Messiahi e-em-nabiay a voces-griteis');
INSERT INTO verses VALUES (10848, 13, 16, 23, 'Cantai para-יהוה todo a-terra em-shoru de-yaom- a dia salvação-o:');
INSERT INTO verses VALUES (10849, 13, 16, 24, 'contai בַגּוֹיִ֖ים a sua-glória-o: em-todo os povos suas-maravilhas-o:');
INSERT INTO verses VALUES (10850, 13, 16, 25, 'que grande yhwh e-alelado muito e temor ele sobre todo Elohim');
INSERT INTO verses VALUES (10851, 13, 16, 26, 'que todo Elohim-de הָעַמִּים֙ elohimes e- יהוה céus fez');
INSERT INTO verses VALUES (10852, 13, 16, 27, 'glória e honra diante-dele força e alegria em seu lugar');
INSERT INTO verses VALUES (10853, 13, 16, 28, 'dai para-יהוה famílias אַمּוֹת dai a-yhwh כבוד ועז׃');
INSERT INTO verses VALUES (10854, 13, 16, 29, 'dai a-yhwh glória-de seu-nome levantem oferta-cereais ובאוּ diante-dele הישתחוו a-yhwh בהדרת־ קדושׁ׃');
INSERT INTO verses VALUES (10855, 13, 16, 30, '[חִ֤ילוּ] [מִלְּפָנָיו֙] todo a-terra também [בַּל־תִּמּֽוֹט]');
INSERT INTO verses VALUES (10856, 13, 16, 31, '[יִשְׂמְח֤וּ] os-céus [וְתָגֵ֣ל] a-terra [וְיֹאמְר֥וּ] [בַגּוֹיִ֖ם] yhwh rei');
INSERT INTO verses VALUES (10857, 13, 16, 32, '[יִרְעַ֤ם] o-mar [וּמְלוֹא֔וֹ] [יַעֲלֹ֥ץ] o-campo e-todo que');
INSERT INTO verses VALUES (10858, 13, 16, 33, 'entao יְרַנּ֖נוּ madeiras-de o jardim de-diante-de yhwh porque veio para julgar a a-terra');
INSERT INTO verses VALUES (10859, 13, 16, 34, 'dai graças para-יהוה que bom que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (10860, 13, 16, 35, 'e digam salvai-nos Elohim-de nosso socorro e congregai-nos e libertai-nos de as-nações para dar graças para-nome-de a vossa santidade para se oferecer em vossas alianças');
INSERT INTO verses VALUES (10861, 13, 16, 36, 'bendito yhwh Elohim-de Israel de o mundo e-até- o mundo e-disseram todo o-povo ássem e a alê para-יהוה');
INSERT INTO verses VALUES (10862, 13, 16, 37, 'e deixou- nome diante-de arca em-aliança-de yhwh para assaf e para seus irmãos para servir diante-de o aron תָּמִ֑יד por palavra de dia em-dia-de-o');
INSERT INTO verses VALUES (10863, 13, 16, 38, 'e o que serve homem e-irmãos-deles sessenta e sete e o que serve homem filho-de deitamento e a que cobre para os governadores');
INSERT INTO verses VALUES (10864, 13, 16, 39, 'e-את Tsadoq o-sacerdote ve-echav os-sacerdotes diante-de tabernáculo-de yhwh yhwh que em-Gibeon');
INSERT INTO verses VALUES (10865, 13, 16, 40, 'para levantar ofertas para yhwh sobre no altar a queimada תָּמִ֑יד para-a-manhã e no ocaso e-para-todo- yhwh em-lei-de yhwh que ordenou sobre Israel');
INSERT INTO verses VALUES (10866, 13, 16, 41, 'e com eles haiman e fizeram e-restante-de os claros que foram-designados בְּשֵׁמֹות para declarar a-yhwh que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (10867, 13, 16, 42, 'e com eles haiman וִֽidoת֜וּן חֲצֹצְר֤וֹת וּמְצִלְתַּ֙יִם֙ לְמַשְׁמִיעִ֔ים וּכְלֵ֖י שִׁ֣יר o-Elohim e-filhos-de יְדַעְתֶּם לַשָּֽׁעַר׃');
INSERT INTO verses VALUES (10868, 13, 16, 43, 'e-caminharam todo o-povo homem לְבֵית֑וֹ vay-sa-bo David לְבָרֵ֥ךְ a casa-dele');
INSERT INTO chapters VALUES (355, 13, 17, 27);
INSERT INTO verses VALUES (10869, 13, 17, 1, 'e-houve como habitou David em-a-casa-seu E-disse דּוֹוִד a deu eis eu eu-sou yoshaveh em-casa-de הָאֲרָזִים e-arca-de debaixo yhwh debaixo-de יְרִיעוֹת׃');
INSERT INTO verses VALUES (10870, 13, 17, 2, 'E-disse deu a Davi todo que com-o-coração-tu que porque Elohim contigo');
INSERT INTO verses VALUES (10871, 13, 17, 3, 'e-houve na-noite o-aquele e-houve palavra-de Elohim dizendo deu');
INSERT INTO verses VALUES (10872, 13, 17, 4, 'vai וְאָמַרְתָּ a Davi servo-meu disse yhwh não tu tu construirás- para-mim a-casa para-sentar-se;');
INSERT INTO verses VALUES (10873, 13, 17, 5, 'que não sentei [בְּבַ֔יִת] de o-dia que [אֶת־יִשְׂרָאֵ֔ל] até o-dia até o-dia esta [אֶל־אֹ֖הֶל] de-tenda-de a');
INSERT INTO verses VALUES (10874, 13, 17, 6, 'em-todo que eu-andei em-todo Israel para-falar falei-eu a um שֹׁפְטֵ֣י Israel que dizendo לִרְע֥וֹת a povo-meu dizendo por-que não voces-construiram yhwh casa ciprestes');
INSERT INTO verses VALUES (10875, 13, 17, 7, 'e-agora assim dizes para-o-meu-servo לְדָוִ֗יד assim disse yhwh exércitos eu para-levar-te de o-abrigo de atrás-de do-rebanho sobre príncipe sobre povo-meu Israel');
INSERT INTO verses VALUES (10876, 13, 17, 8, 'e-serei em-voce em-todo que e-você-andou וָאַכְרִ֥ית a todo os teus inimigos a-ti e farei para-ti nome como-o-nome as grandes que na-terra');
INSERT INTO verses VALUES (10877, 13, 17, 9, 'e-postarei lugar para-o-povo-meu Israel e plantarei-os e-habitará em-lugar-dele e-não ele-tremeará ainda e-não e acrescentarão filhos-de iniquidade para tentá-lo conforme em-primeiro');
INSERT INTO verses VALUES (10878, 13, 17, 10, 'e para os tempos que comandei-eu juízes sobre meu-povo Israel e eu humilharei a para-ti os teus inimigos e declarei yhwh e-casa יבנה- a-você yhwh');
INSERT INTO verses VALUES (10879, 13, 17, 11, 'e-foi porque מָלְא֤וּ יامي-ך para-andar com avós-teus והקיםתי- a será de-te que será מבני-ך וַהֲכִינֹתִ֖י a seu-reino');
INSERT INTO verses VALUES (10880, 13, 17, 12, 'ele construirá para-mim casa וכוננתי- a trono-dele até eternidade');
INSERT INTO verses VALUES (10881, 13, 17, 13, 'eu איהי- para-ele para-pai e-ele sera para-mim para-filho והחסדי- não אסיר- מֵֽעִמּ֔וֹ ser הֲסִיר֔וֹתִי do-que foi diante-de-você.');
INSERT INTO verses VALUES (10882, 13, 17, 14, 'וְהַֽעֲמַדְתִּ֛יהוּ בְּבֵיתִ֥י וּבְמַלְכוּתִ֖י até הָעוֹלָ֑ם será será certo até eternidade');
INSERT INTO verses VALUES (10883, 13, 17, 15, 'como-tudo as-palavras os-estes [וּכְכֹ֖ל] [הֶחָז֣וֹן] esta assim palavra deu a');
INSERT INTO verses VALUES (10884, 13, 17, 16, 'E-veio o-rei Davi e-habitou diante-de yhwh E-disse quem yhwh yhwh Elohim e-quem que porque [עַד־הֲלֹֽם] até');
INSERT INTO verses VALUES (10885, 13, 17, 17, 'וַתִּקְטַ֨ן esta em-olhos-teus Elohim e falaste sobre casa-de servo-teu para longe o-homem כְּת֧וֹר yhwh הַֽמַּעֲלָ֖ה yhwh Elohim');
INSERT INTO verses VALUES (10886, 13, 17, 18, 'que [ע֥וֹד] ainda Davi a-ti [אֶת־עַבְדֶּ֑ךָ] a servo-teu e-tu a');
INSERT INTO verses VALUES (10887, 13, 17, 19, 'yhwh baavur teu-servo ukhlivkha asita a todo hagdulah esta להודיע a todo הגדولات׃');
INSERT INTO verses VALUES (10888, 13, 17, 20, 'yhwh não-há como כָּמוֹךָ e-não-há Elohim zoletecha זולתהך em-todo que ouvimos em-a-ouvido-nos');
INSERT INTO verses VALUES (10889, 13, 17, 21, 'e-quem כּוּעַםֶךָ֣ Israel nação um em-a-terra que andar os-אלהים para fazer a-ele povo לָשׂ֤וּם a-ti nome גדولات ונוראות׃ para-garesh de-diante-de o-teu-povo que fadi-te de-misraim goyim:');
INSERT INTO verses VALUES (10890, 13, 17, 22, 'e-deu a o-teu-povo Israel a-ti para-o-povo até eternidade yhwh yhwh a-eles a-eles para-elohim');
INSERT INTO verses VALUES (10891, 13, 17, 23, 'e-agora yhwh a-palavra que falaste sobre teu-servo e-sobre casa-dele irá-fulfillir-se até eternidade e-fazes como-que dibartā׃');
INSERT INTO verses VALUES (10892, 13, 17, 24, 'e-irá-fulfillir-se e-grande-seja seu-nome até dizendo yhwh yhwh dos-exércitos Elohim-de Israel Elohim para-yeśraʾel e-casa-de Davi servo-teu certo diante-de-você.');
INSERT INTO verses VALUES (10893, 13, 17, 25, 'que tu tu גָּלִ֙יתָ֙ a o-ouvido teu-servo para-construir a-ele casa sobre encontrou encontrou teu-servo para-orar-se diante-de-você.');
INSERT INTO verses VALUES (10894, 13, 17, 26, 'e-agora yhwh você- ele o-Elohim e-você-falou sobre teu-servo hatovah a esta');
INSERT INTO verses VALUES (10895, 13, 17, 27, 'e-agora e-alei-te para-benzer a casa teu-servo a-ser para-sempre diante-de-ti yhwh tu yhwh ברכת ומברך para-eternidade');
INSERT INTO chapters VALUES (356, 13, 18, 17);
INSERT INTO verses VALUES (10896, 13, 18, 1, 'e-houve depois-de assim e-feriu Davi a E-tomou [אֶת־גַּ֥ת] E-tomou a [פְּלִשְׁתִּֽים]');
INSERT INTO verses VALUES (10897, 13, 18, 2, 'WAYYAKACH a Moabe e-foram Moabe avádim לדוד carregadores-de oferta-:');
INSERT INTO verses VALUES (10898, 13, 18, 3, 'e-feriu Davi a Hadar-ezer rei-de צבבה חמתה sua-mão להצב mão-sua em-o-rio Eufrates');
INSERT INTO verses VALUES (10899, 13, 18, 4, 'WAYYALAKED דוד nós mil רֶכֶב וְשִׁבְעַ֤ת milhares פָּֽרָשִׁ֔ים e-vinte mil homem de-pé e-ele-examinou Davi a todo nós e-ele-removeu dele cem cavalo');
INSERT INTO verses VALUES (10900, 13, 18, 5, 'E-veio Arã דַּרְמֶ֔שֶׂק לַעְז֕וֹר לַהֲדַדְעֶ֖זֶר rei Zobah e-ele-feriu Davi בַּאֲרָ֔ם vinte- u-shnayim mil homem');
INSERT INTO verses VALUES (10901, 13, 18, 6, 'e-ele-colocou Davi em Aram דַּרְמֶ֔שֶׂק e-houve Aram לְדָוִ֔יד servos carregadores-de oferta vayóshá yhwh לְדָוִ֔יד em-todo que andou');
INSERT INTO verses VALUES (10902, 13, 18, 7, 'E-tomou דָּוִ֗יד a שָׂרִים o-ouro que foram sobre servos-de Hadarazeer וַיְבִיאֵ֖ם Jerusalém');
INSERT INTO verses VALUES (10903, 13, 18, 8, 'e da matibachath וּמִכּוּן֙ cidades-de Hadadezer tomou Davi bronze multiplicai muito nela fez Salomão a mar o-bronze e-a hā-âmûdîm e-a instrumentos-de o-bronze');
INSERT INTO verses VALUES (10904, 13, 18, 9, 'E-ouviu tou rei Hamate que bateu Davi a todo exército Hadar-ezer rei-de továh');
INSERT INTO verses VALUES (10905, 13, 18, 10, 'e-enviou a Hadoram- -seu-filho a o-rei sobre a-ele para-paz e-para-bendizê-lo sobre que luta em Hadadezer ser porque e-tudo guerras-de ouro foi Hadarazeer e-todo keli ouro e prata e-nacashet:');
INSERT INTO verses VALUES (10906, 13, 18, 11, 'também os-los santificou-o o-rei Davi para-יהוה com a-prata e-ha-zahav que levantou de-todo as-nações de-edom e-moab וּמִבְּנֵ֣י não וּמִפְּלִשְׁתּ֖ים e-me''amaleque:');
INSERT INTO verses VALUES (10907, 13, 18, 12, 'וְאַבְשַׁ֣י filho-de צְרוּיָה bateu a Edom em-gaia ha-melah shmonáh dez mil');
INSERT INTO verses VALUES (10908, 13, 18, 13, 'e-ele-colocou no-edom נצבים e-foram todo Edom avádim לדוד yhwh yhwh a Davi em-todo que andou');
INSERT INTO verses VALUES (10909, 13, 18, 14, 'e-reinou David sobre e-houve Israel E-foi fez mishpat e-justica para-todo seu-povo');
INSERT INTO verses VALUES (10910, 13, 18, 15, 'e-Joabe filho-de formada sobre o-exército viyohoshaphat filho-de achilud mazkir');
INSERT INTO verses VALUES (10911, 13, 18, 16, 'vetzadoq filho-de achitub ואבימלך filho-de evyatar sacerdotes VASha escritor');
INSERT INTO verses VALUES (10912, 13, 18, 17, 'e-Benaia filho-de Joiada sobre [וּבְנֵי־דָוִ֥יד] e-o-peleteu e-filhos-de [הַמֶּֽלֶךְ׃]');
INSERT INTO chapters VALUES (357, 13, 19, 19);
INSERT INTO verses VALUES (10913, 13, 19, 1, 'e-houve depois-de assim E-morreu nāchāš rei filhos-de Amom e-reinou filho-seu em-lugar-dele');
INSERT INTO verses VALUES (10914, 13, 19, 2, 'E-disse דוד farei misericórdia com gracioso filho-de seu-pai porque fez pai-de-ele comigo bondade e-enviou Davi angéis לנחמו sobre seu-pai e-ele-chegou servos-de דוד a terra filhos-de עַמּוֹן a חָנֻן לְנַחֲמֹו׃');
INSERT INTO verses VALUES (10915, 13, 19, 3, 'e-disseram príncipes-de filhos-de Amon לְחָנֻן o-que-exalta Davi a teu-pai a-ti porque enviou a-ti מְנַחֲמִים não-é בַּ֠עֲבוּר a-terra וְלַהֲפֹךְ וּלְרַגֵּל֙ a-terra a-noite servos-dele para-ti');
INSERT INTO verses VALUES (10916, 13, 19, 4, 'E-tomou gracioso a servos-de Davi וַֽיְגַלְּחֵם e-ele-cortou a as-maças-deles em-meio até הַמִּפְשׂעָה e-ele-mandou-os');
INSERT INTO verses VALUES (10917, 13, 19, 5, 'e saíram וַיַּגּוּדֹוּ לְדָוִד sobre os-homens e-enviou para-eles porque foram muito E-disse muito E-disse o rei até em-a-lua-seu até que ele-fará-germinar idosos-vos e-voltareis');
INSERT INTO verses VALUES (10918, 13, 19, 6, 'e-eles-viram filhos-de Amom que הִתְבַּאֲשׁוּ com Davi e-enviou חֲנֻן e filhos-de Amon mil k-khar- a-eles לִשְׂכֹּר לַהֲמֵם de Aram נַחֲרַיִם e-de Arameus Maaca e-mitzvah recheb e-cavaleiros');
INSERT INTO verses VALUES (10919, 13, 19, 7, 'e-vasishkru a-eles dois e-sheloshim mil recheb e-a rei maacah e-a povo-seu e-vieram e-acamparam diante-de midba e-filhos-de ammon nesafu me-areihem e-vieram para a guerra∶');
INSERT INTO verses VALUES (10920, 13, 19, 8, 'E-ouviu Davi e-enviou a e-[OBJ] e-[OBJ] todo');
INSERT INTO verses VALUES (10921, 13, 19, 9, 'e saíram∶ filhos-de Amom e contaram∶ guerra entrada-de a-cidade e os reis∶ que vieram le-baddam no-campo');
INSERT INTO verses VALUES (10922, 13, 19, 10, 'E-viu Joabe porque havia∶ a-ele a-guerra a-ele face e Achor∶ e escolheu∶ de-todo o jovem∶ em-Israel e-arranjou para-encontro-de aram');
INSERT INTO verses VALUES (10923, 13, 19, 11, 'e-[OBJ] Jetro o-povo dar em-mão [אַבְשַׁ֣י] irmão-dele [וַיַּ֣עַרְכ֔וּ] para-encontro-de filhos-de Amon');
INSERT INTO verses VALUES (10924, 13, 19, 12, 'E-disse se te-chezaq de-mim Arã a-mim para-mim para-a-salvação e-se filhos-de Amom Yechezqu de-vós e-te-hosai:');
INSERT INTO verses VALUES (10925, 13, 19, 13, 'forte e-nos-fortaleçamos בְּעַד־ עַמֵּנוּ וּבְעַ֖ד cidades-de Elohim-nosso e-יהוה o-bom em-suas-olhos ele-fará');
INSERT INTO verses VALUES (10926, 13, 19, 14, 'e-ele-aproximou-se Joabe e-o-povo que com-ele diante-de Arã para-a-guerra e-eles-se-mesmo-sucedeceram de-face-dele');
INSERT INTO verses VALUES (10927, 13, 19, 15, 'e filhos-de Amom viram porque fugiu Arã e-eles-se-esconderam de-diante-de Eles mipnay abshai irmão-seu e-vieram a-cidade E-veio יוֹאָב Jerusalém');
INSERT INTO verses VALUES (10928, 13, 19, 16, 'E-viu אֲרָ֗ם que foram-atingidos diante-de Israel e-enviaram mensageiros e saíram a Arã que o-rio o-rio e-derramar-se-á príncipe-de exército-de hadadezer diante-deles');
INSERT INTO verses VALUES (10929, 13, 19, 17, 'vayuggad para-Davi vaeessof a todo Israel vayaavor o-Jordão E-veio a-eles e-arranjou a-eles e estendeu Davi para Aram guerra e-lutaram com-ele');
INSERT INTO verses VALUES (10930, 13, 19, 18, 'e-fugiu Aram-em de-diante-de Israel e-matou Davi de-Aram shib-aat milhares carros e-quarenta mil homem de-pé e-a derramar chefe o-exército e matou:');
INSERT INTO verses VALUES (10931, 13, 19, 19, 'e-eles-veem servos-de Hadezezer que niggu״fuֿ diante-de Israel e completaram com David e serviram-no e-não quis Arã lehoshiaבa a filhos-de Amom ainda');
INSERT INTO chapters VALUES (358, 13, 20, 8);
INSERT INTO verses VALUES (10932, 13, 20, 1, 'e-houve no tempo de teshuvat hashana״ah le-et tseet os-reis vayinheg yoav a chail ha-tsava vayashchet a terra filhos-de Ammon E-veio vayetsar a multiplicai ve-David habitou be-Yerushalaim e-feriu Joab a multiplicai vayeheresheha');
INSERT INTO verses VALUES (10933, 13, 20, 2, 'E-tomou Davi a de-cima-de seu-rei de-cima sua-cabeça e-encontrou-a peso k-khar- pedra e-na-ela pedra preciosa e-foi sobre cabeça Davi e-despojo-de muito tirou muito muito');
INSERT INTO verses VALUES (10934, 13, 20, 3, 'e-a o-povo que בָּ֜הּ saíu e-dispuu no-magreza e nos carvalhos o ferro e nas minas e também a-todo Davi para-todo cidades-de filhos-de Amom e-estabeleceu-se Davi e-todo o-povo Jerusalém');
INSERT INTO verses VALUES (10935, 13, 20, 4, 'e-houve e pôs-se em guerra em Gerez com filisteus então bateu minha frota meu exército a סיפַי מִילִ֦די הָרְפָאִ֑ים וַיִּכָּנֵֽעוּ׃');
INSERT INTO verses VALUES (10936, 13, 20, 5, 'e-ela-tornou-se ainda guerra a filisteus [בֶּן־*יעור] [**יָעִ֗יר] filho-de a [גָּלְיָ֣ת] [הַגִּתִּ֔י] [וְעֵ֣ץ] [חֲנִית֔וֹ] [כִּמְנ֖וֹר] [אֹרְגִֽים]');
INSERT INTO verses VALUES (10937, 13, 20, 6, 'e-ela-tornou-se ainda guerra e-houve [׀] homem [מִדָּ֗ה] [וְאֶצְבְּעֹתָ֤יו] seis-de [עֶשְׂרִ֣ים] vinte [וְגַם־ה֖וּא] e-também ele');
INSERT INTO verses VALUES (10938, 13, 20, 7, '[וַיְחָרֵ֖ף] a Israel [יְה֣וֹנָתָ֔ן] Jônatas filho-de [דָוִֽיד]');
INSERT INTO verses VALUES (10939, 13, 20, 8, 'El נולדוּ להרפאה בגת וייפלוּ na-mao-de David e-em-mão- seus-servos');
INSERT INTO chapters VALUES (359, 13, 21, 30);
INSERT INTO verses VALUES (10940, 13, 21, 1, 'WAYY''AMOD שָׂטָן sobre Israel WAYYSAT a Davi למנות a Israel');
INSERT INTO verses VALUES (10941, 13, 21, 2, 'E-disse Davi a Joabe e-a príncipes-de o-povo vinde [מִבְּאֵ֥ר] a Israel [וְהָבִ֣יאוּ] sete e-até [אֶת־מִסְפָּרָֽם] a');
INSERT INTO verses VALUES (10942, 13, 21, 3, 'E-disse Joabe יוֹסֵף֩ yhwh sobre עַמּ֤וֹ ׀ כָּהֵם֙ cem פְעָמִ֔ים הֲלֹא֙ Adonai o-rei todos-eles לַאדֹנִ֖י לַעֲבָדִ֑ים por-que יְבַקּוֹשׁ esta Adonai por-que será לְאַשְׁמָה para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (10943, 13, 21, 4, 'e-palavra-de o-rei forte sobre Joabe e-saiu Joabe e-ele-caminhou em-todo Israel E-veio Jerusalém');
INSERT INTO verses VALUES (10944, 13, 21, 5, 'E-colocou Joab a número מִפְקַד- e-houve a Davi E-foi todo Israel mil אֲלָפִים espada mil homem desembainhando espada וִֽיהוּדָ֕ה quatro centenas וְשִׁבְעִים mil homem espada espada');
INSERT INTO verses VALUES (10945, 13, 21, 6, '[וְלֵוִי֙] e-Benjamim não [פָקַ֖ד] [בְּתוֹכָ֑ם] porque [דְּבַר־הַמֶּ֖לֶךְ] palavra-de a');
INSERT INTO verses VALUES (10946, 13, 21, 7, 'e foi mau em-olhos-de os-Elohim sobre a palavra esta e bateu a Israel');
INSERT INTO verses VALUES (10947, 13, 21, 8, 'E-disse Davi a Elohim muito muito que fiz a e-agora esta e-agora o abra que a muito teu-servo porque eu me confundi muito');
INSERT INTO verses VALUES (10948, 13, 21, 9, 'e-falou yhwh a gad o vislumbrador dizendo para-dizer');
INSERT INTO verses VALUES (10949, 13, 21, 10, 'vai e falaste a dizendo dizendo disse yhwh yhwh três eu inclinado sobre-ti uma para-ti uma מֵהֵ֖נָּה e-e''asah- para-ti');
INSERT INTO verses VALUES (10950, 13, 21, 11, 'E-veio [גָ֖ד] a E-disse a-ele para-ele yhwh disse yhwh');
INSERT INTO verses VALUES (10951, 13, 21, 12, 'se [שָׁנִ֜ים] dois [וְאִם־שְׁלֹשָׁ֨ה] e-se [נִסְפֶּ֥ה] [מִפְּנֵי־צָרֶיךָ֮] [וְחֶ֣רֶב] [אוֹיְבֶ֣ךָ] [׀] e-espada-de [וְאִם־שְׁלֹ֣שֶׁת] [יָ֠מִים] espada yhwh [וְדֶ֙בֶר֙] [בָּאָ֔רֶץ] yhwh yhwh na-terra e-mensageiro yhwh e-agora em-todo território Israel [דָּבָֽר׃] viu a palavra');
INSERT INTO verses VALUES (10952, 13, 21, 13, 'E-disse Davi a [צַר־לִ֣י] muito a-mim muito [כִּֽי־רַבִּ֤ים] agora muito yhwh porque homem a');
INSERT INTO verses VALUES (10953, 13, 21, 14, 'E-colocou yhwh palavra em-Israel e-caiu de-Israel setenta mil homem');
INSERT INTO verses VALUES (10954, 13, 21, 15, 'e-enviou הָאֱלֹהִ֨ים מַלְאָ֥ךְ לִֽירוּשָׁלִַם֮ para destruí-la e para destruir viu yhwh ver yhwh a má E-disse E-disse aquele que destrói muito agora levantou-se tua-mao e anjo yhwh yhwh com goren Ornã o-jebuseu');
INSERT INTO verses VALUES (10955, 13, 21, 16, 'e-ele-leva Davi a E-viu E-viu yhwh mensageiro-de entre a-terra e-entre a-terra e-entre os-céus e sua espada cortou em-mão-de-ele pendurado sobre Jerusalém e-caiu דָּוִד וְהַזְּקֵנִים מְכֻסִים בַּשַּׁקְּקִים sobre em-seus-faces');
INSERT INTO verses VALUES (10956, 13, 21, 17, 'E-disse Davi a הָאֱלֹהִים הֲלֹא֩ eu disse לִמְנ֣וֹת no povo e eu ele que pecado-eu וְהָרֵ֣עַ Haruaoti e-aqueles yhwh que asú yhwh אֱלֹהַי Tihi por-favor mão-tua Bi não meu-pai uBeAmakha não lemagga');
INSERT INTO verses VALUES (10957, 13, 21, 18, 'uMalakh yhwh disse a dizendo Leomar que que subia David para-levantar um-altar a-yhwh em-eira-de Ornã Hayivsi');
INSERT INTO verses VALUES (10958, 13, 21, 19, 'e-subiu Davi Bidvar- גד que palavra yhwh yhwh');
INSERT INTO verses VALUES (10959, 13, 21, 20, '[וַיָּ֣שָׁב] [אָרְנָ֗ן] E-viu a [וְאַרְבַּ֧עַת] [בָּנָ֛יו] [עִמּ֖וֹ] com-ele [וְאָרְנָ֖ן] [דָּ֥שׁ] [חִטִּֽים]');
INSERT INTO verses VALUES (10960, 13, 21, 21, 'E-veio דוד até ארナン E olhou E-viu E-viu a Davi e-saiu de הַגֹּ֔רֶן e-ele-se-prostrou para Davi Apaim para-terra');
INSERT INTO verses VALUES (10961, 13, 21, 22, 'E-disse Davi a Aran dá- para-mim lugar הַגֹּ֔רֶן e edifiquei nele altar a-yhwh com prata enchei dê-lhe de-cima-de e aperte a praga de-sobre o-povo');
INSERT INTO verses VALUES (10962, 13, 21, 23, 'E-disse Aran a Davi toma- para-ti E-fez Adonai o-rei o-bom dei viu Eu dei o gado para a oferta e os que arrastam para as árvores e as ovelhas para a oferta pão tudo Eu dei:');
INSERT INTO verses VALUES (10963, 13, 21, 24, 'E-disse o-rei Davi a Arnaom não porque compre eu comprarei em-cobre que porque não eu pagarei que para-ti para-יהוה e-ele levarei holocausto; gratuitamente');
INSERT INTO verses VALUES (10964, 13, 21, 25, 'E-colocou Davi para-Arnon no-lugar de-cobre ouro peso seis centenas');
INSERT INTO verses VALUES (10965, 13, 21, 26, 'E-edificou nome Davi um-altar para-יהוה e-ofereceu holocaustos e-pacíficos E-chamou a yhwh ele-o respondeu-lhe no-fogo sobre os-céus sobre yhwh a-elevação');
INSERT INTO verses VALUES (10966, 13, 21, 27, 'E-disse yhwh para-o anjo ele-assentou-se sua-espada a acusa-lá:');
INSERT INTO verses VALUES (10967, 13, 21, 28, 'em-o-tempo aquela em-suas-vistas Davi porque yhwh yhwh em-eira-de arnean hivita e-sacrificou nome');
INSERT INTO verses VALUES (10968, 13, 21, 29, 'e o tabernáculo yhwh que fez Moisés no deserto e o altar a-holocausto em-o-tempo aquela na plataforma em-Gibeon');
INSERT INTO verses VALUES (10969, 13, 21, 30, 'e-não poderia Davi para-andar diante-dele inquirir que porque de-diante-de espada espada yhwh yhwh');
INSERT INTO chapters VALUES (360, 13, 22, 19);
INSERT INTO verses VALUES (10970, 13, 22, 1, 'E-disse Davi este ele casa yhwh o-Elohim e-este do altar para-oferta para-יִשְׂרָאֵל');
INSERT INTO verses VALUES (10971, 13, 22, 2, 'E-disse Davi entrar a os estrangeiros que em-terra-de Israel e pôs-se חֹֽצְבִ֗ים לַחְצוֹב֙ pedras-de גָזִ֔ית para-construir casa Elohim');
INSERT INTO verses VALUES (10972, 13, 22, 3, 'וּבַרְזֶ֣ל ׀ לָ֠רֹב לַֽמִּסְמְרִ֞ים לְדַלְת֧וֹת הַשְׁעָרִ֛ים וְלַֽמְחַבְּר֖וֹת הֵכִ֣ין Davi e-nacashet para-multiplicar não-há misqal:');
INSERT INTO verses VALUES (10973, 13, 22, 4, 'וַעֲצֵ֥י árvores-de-arazim para-nao-haver de-número porque heviu ha-tsidonim ve-ha-tzorim atzei ciprestes para-multiplicar le-david:');
INSERT INTO verses VALUES (10974, 13, 22, 5, 'E-disse david Shelomoh filhos-de jovem va-reakha ve-ha-bayit para-edificar a-yhwh para aumentar para cima para o nome e para a beleza para-todo as-áreas faça-me por favor a-ele e assim fez Davi para-multiplicar diante-de sua morte:');
INSERT INTO verses VALUES (10975, 13, 22, 6, 'E-chamou para-שְׁלֹמֹה בְנ֑וֹ e ordenou-lhe para-edificar casa a-yhwh Elohim-de Israel');
INSERT INTO verses VALUES (10976, 13, 22, 7, 'E-disse David para-Salomão eu foi com ser para-edificar casa para-Shem yhwh yhwh');
INSERT INTO verses VALUES (10977, 13, 22, 8, 'e-houve sobre-mim palavra-de dizendo dizendo sangue para muitos derramaste e guerras grandes fizeste não construirás que para o meu nome porque sangue muitos derramaste terra-para לְפָנַֽי׃');
INSERT INTO verses VALUES (10978, 13, 22, 9, 'eis-que- filho para-ti ele será yihye homem descanso a-ele para-ele de-todo que em-o-redor será שְׁלֹמֹה será seu-nome e paz e tranquilidade darei sobre Israel nos seus dias:');
INSERT INTO verses VALUES (10979, 13, 22, 10, 'ele construirá casa para o meu nome e-ele ser- para-mim para Ben e eu a-ele para Ab e preparei-o trono seu reino sobre Israel até eternidade');
INSERT INTO verses VALUES (10980, 13, 22, 11, 'agora filhos-de haja yhwh contigo e o faria prosperar e edificaria casa yhwh teu-Elohim conforme palavra sobre-te');
INSERT INTO verses VALUES (10981, 13, 22, 12, 'porém ele dará yhwh yhwh discernimento e-entendimento e ordenareis-vos sobre Israel yhwh a ela yhwh Elohim-tua');
INSERT INTO verses VALUES (10982, 13, 22, 13, 'então que tenhas sucesso se guarda para-fazer a as leis e-a yhwh que ordenou yhwh a Moisés sobre Israel forte e-corajoso a temas e-a desanimes');
INSERT INTO verses VALUES (10983, 13, 22, 14, 'e-eis em minha humildade preparei-me para-casa-de ouro ouro de cícaros cem de mil e prata mil milhares כִּכָּרִים וְלַנְּחֹ֤שֶׁת וְלַבַּרְזֶל֙ que מִשְׁקָ֔ל ser para-multiplicar foi וְעֵצִ֤ים וַאֲבָנִים֙ הֲכִינ֔וֹתִי e-sobre-elas תּוֹסִֽיף׃');
INSERT INTO verses VALUES (10984, 13, 22, 15, 'וְעִמְּךָ֤ לָרֹב֙ feitores obra חֹצְבִ֕ים וְחָרָשֵׁ֥י pedra וָעֵ֑ץ e-todo sábio em-todo obra');
INSERT INTO verses VALUES (10985, 13, 22, 16, 'לַזָּהָ֥ב לַכֶּ֛סֶף וְלַנְּחֹ֥שֶׁת וְלַבַּרְזֶ֖ל não-há de-número levantou וַעֲשֵׂ֔ה e-seja yhwh contigo');
INSERT INTO verses VALUES (10986, 13, 22, 17, 'E-ordenou Davi para-todo príncipes-de Israel [לִשְׁלֹמֹ֥ה] [בְנֽוֹ]');
INSERT INTO verses VALUES (10987, 13, 22, 18, 'não-é-que yhwh Elohim-vosso com-vocês e hajam a-vós em-o-redor que deu dar a habitantes-de a-terra a-terra a-terra a-terra yhwh yhwh seu-povo');
INSERT INTO verses VALUES (10988, 13, 22, 19, 'agora dai vosso-coração e as vossas almas para buscar a-yhwh vosso-Elohim וְק֗וּmoּ e edificai a yhwh yhwh o elohim לְהָבִ֞יא a arca em-aliança-de yhwh e os utensílios santo-de הָֽאֱלֹהִ֔ים para o templo que seja edificado לְשֵׁם־ yhwh');
INSERT INTO chapters VALUES (361, 13, 23, 32);
INSERT INTO verses VALUES (10989, 13, 23, 1, 'וְדָוִ֥יד velho וְשָׂבַ֣ע dias וַיַּמְלֵ֛ךְ a Salomão seu-filho sobre Israel');
INSERT INTO verses VALUES (10990, 13, 23, 2, '[וַיֶּאֱסֹף֙] a todo príncipes-de Israel');
INSERT INTO verses VALUES (10991, 13, 23, 3, 'וַיִּסָּֽפְרוּ֙ os-levitas מִבֶּ֛ן trinta ano e-para-cima e-houve מִסְפָּרָ֤ם לְגֻלְגְּלֹתָם֙ para-os-homens trinta e-oito mil');
INSERT INTO verses VALUES (10992, 13, 23, 4, 'de-estes para-a-vitória sobre obra-de casa-de yhwh vinte e-quatro mil e-juízes e-julgadores seis-de mil:');
INSERT INTO verses VALUES (10993, 13, 23, 5, 'e-quatro milhares de-cabeças e-quatro milhares que-alegram-se a-yhwh com-os-instruimentos-musicais que fiz para alavancar:');
INSERT INTO verses VALUES (10994, 13, 23, 6, 'e os separou: David separações aos-filhos-de Levi para Gershon: Cohath: e-Merari');
INSERT INTO verses VALUES (10995, 13, 23, 7, 'para o Gershoni: para Amram: e-Simei');
INSERT INTO verses VALUES (10996, 13, 23, 8, 'filhos-de para Amram: a cabeça Jehiel וְזֵתָ֥ם וְיוֹאֵ֖ל três');
INSERT INTO verses VALUES (10997, 13, 23, 9, 'filhos-de שִׁמְעִ֗י וַחֲזִיאֵ֛ל ve-o-Ran- שְׁלֹשָׁ֑ה estes topos-de Estas לְלַעְדָּֽן׃');
INSERT INTO verses VALUES (10998, 13, 23, 10, 'e-filhos-de Shimei יַ֣חַת זִינָ֔א e Jeús וּבְרִיעָ֑ה Estas filhos-de quatro quatro');
INSERT INTO verses VALUES (10999, 13, 23, 11, 'e-foi יַ֣חַת o-primeiro e zizah o-segundo vi yuš e brī''āh filhos hirbū filhos pai para-casa-de pai lifkuddāh uma');
INSERT INTO verses VALUES (11000, 13, 23, 12, 'filhos-de Qehat Amram [יִצְהָ֛ר] Hebrom e Uzzi''el quatro');
INSERT INTO verses VALUES (11001, 13, 23, 13, 'filhos-de Amram Aarão e-Mosheh e separou arão para santificá-lo santo santos ele e-filhos-dele até eternidade yhwh diante-de yhwh para servir-o e abençoar em Seu nome até eternidade');
INSERT INTO verses VALUES (11002, 13, 23, 14, 'e-Mo-she homem o-Elohim seus filhos seriam chamados sobre bastão Levi:');
INSERT INTO verses VALUES (11003, 13, 23, 15, 'filhos-de Moisés [גֵּרְשֹׁ֖ם] [וֶאֱלִיעֶֽזֶר]');
INSERT INTO verses VALUES (11004, 13, 23, 16, 'filhos-de Gerson שבועאל הראש׃');
INSERT INTO verses VALUES (11005, 13, 23, 17, 'E foram filhos-de אליעזר רחבייה a-cabeça e-não foi לאליעזר filhos outros e-filhos-de רחבייה רבו para-cima');
INSERT INTO verses VALUES (11006, 13, 23, 18, 'filhos-de [יִצְהָ֖ר] [שְׁלֹמִ֥ית] [הָרֹֽאשׁ׃]');
INSERT INTO verses VALUES (11007, 13, 23, 19, 'filhos-de Hebrom [יְרִיָּ֤הוּ] [הָרֹאשׁ֙] [אֲמַרְיָ֣ה] o-segundo [יַחֲזִיאֵל֙] o-terceiro [וִֽיקַמְעָ֖ם] o-quarto');
INSERT INTO verses VALUES (11008, 13, 23, 20, 'filhos-de Uziel מִיכָ֣ה o-primeiro וְיִשּׁׂיָּ֖ה o-segundo');
INSERT INTO verses VALUES (11009, 13, 23, 21, 'filhos-de מְרָרִי֙ Mahli וּמוּשִׁ֔י filhos-de מַחְלִ֖י Eleazar וְקִֽישׁ׃');
INSERT INTO verses VALUES (11010, 13, 23, 22, 'E-morreu Eleazar e-não a-ele para-ele que porque se filhas וַיִּשָׂא֥וּם filhos-de Quis irmãos-deles');
INSERT INTO verses VALUES (11011, 13, 23, 23, 'filhos-de [מוּשִׁ֗י] [מַחְלִ֥י] [וְעֵ֛דֶר] [וִירֵמ֖וֹת] três');
INSERT INTO verses VALUES (11012, 13, 23, 24, 'Estas filhos-de לֵוִי֩ lebeith אֲבֹתֵיהֶ֜ם רָאשֵׁי הָאָב֣וֹת לִפְקֻדֵיהֶם em-número-de nomes para-cabeças-deles fez a-obra לַעֲבוֹדַת yhwh yhwh מִבֵּן vinte ano e-para-cima');
INSERT INTO verses VALUES (11013, 13, 23, 25, 'que disse Davi הֵנִיחַ yhwh Elohim-de Israel לְעַמּוֹ וַיִּשְׁכֹּן birushalaim até para-eternidade');
INSERT INTO verses VALUES (11014, 13, 23, 26, 'e-também para-os-Levitas não-há לָשׂוֹאַת a o-tabernáculo e-a todo כְּלֵיָיו para a sua adoração:');
INSERT INTO verses VALUES (11015, 13, 23, 27, 'que pelos palavras: Davi dos últimos: eles número filhos-de Levi do filho: vinte ano e para cima:');
INSERT INTO verses VALUES (11016, 13, 23, 28, 'que de seus lugares: na mão de: filhos-de Arão para a adoração: yhwh yhwh sobre das pátios: e-sobre dos tronos: e-sobre טהרה para-todo santidade ומעשה avodat casa Elohim');
INSERT INTO verses VALUES (11017, 13, 23, 29, 'ולחם המערכה ולsoles למנחה ולרקיקים ha-matzot ולמחבת ולמרבכת e-para-todo- משורה e medida:');
INSERT INTO verses VALUES (11018, 13, 23, 30, 'para estar ba-voker de-manhã a dar graças e louvar a-yhwh e-assim ao entardecer:');
INSERT INTO verses VALUES (11019, 13, 23, 31, 'para todo subir holocaustos para-יהוה aos sábados aos meses e aos convocações בְּמִסְפָּ֨ר כְּמִשְׁפּ֧ט sobre-eles תָּמִ֖יד diante-de yhwh');
INSERT INTO verses VALUES (11020, 13, 23, 32, 'וְשָׁמְר֞וּ a de-guarda tenda-de מוֹעֵ֗ד e-את de-guarda o-santuário וּמִשְׁמֶ֕רֶת filhos-de אַהֲרֹן אֲחֵיהֶ֑ם yhwh casa yhwh');
INSERT INTO chapters VALUES (362, 13, 24, 31);
INSERT INTO verses VALUES (11021, 13, 24, 1, 'e-aos-filhos-de אַהֲרֹן מַחְלְקוֹתָ֑ם filhos-de Arão Nadav e-Avi-hu-a Elazar e-Itamar');
INSERT INTO verses VALUES (11022, 13, 24, 2, 'E-morreu נָדָ֤ב וַאֲבִיהוּא֙ diante-de pai-deles e-filhos não a-eles a-eles e os consagraram Elazar e-Itamar');
INSERT INTO verses VALUES (11023, 13, 24, 3, 'e lhes deu parte Davi e Zadoque de filhos-de Eleazar e Achimeleque de filhos-de Eitam para a sua guarda em seu serviço:');
INSERT INTO verses VALUES (11024, 13, 24, 4, 'e encontraram filhos de Eleazar muitos para os chefes de dos homens de filhos-de Aitamar e dividiram-os para-os-filhos-de El''azar raashim para-a-casa-de avós seis dez e filhos de Aitamar segundo-casa-de pais-deles oito');
INSERT INTO verses VALUES (11025, 13, 24, 5, 'e-lhes-quebraram por-sorteios Estas com estes porque eram srs-de- santo e-príncipes-de os-Elohim de-filhos-de Elazar e-nos-filhos aitamar:');
INSERT INTO verses VALUES (11026, 13, 24, 6, '[וֽ͏ַיִּכְתְּבֵ֡ם] [שְֽׁמַֽעְיָה֩] filho-de [הַסּוֹפֵ֜ר] [מִן־הַלֵּוִ֗י] de [הַמֶּ֤לֶךְ] diante-de o-rei e-os-príncipes e-צָדוֹק o-sacerdote [וְרָאשֵׁי֙] filho-de אֶבְיָתָר [וְלַלְוִיִּ֑ם] os-pais um [אָחֻז֙] casa-de pai um [אָחֻ֖ז] [לְאִיתָמָֽר׃]');
INSERT INTO verses VALUES (11027, 13, 24, 7, 'e-saiu הַגּוֹרָ֤ל הָרִאשׁוֹן֙ לִיה֣וֹיָרִ֔יב לִֽידַעְיָ֖ה o-segundo');
INSERT INTO verses VALUES (11028, 13, 24, 8, '[לְחָרִם֙] o-terceiro [לִשְׂעֹרִ֖ים] [הָרְבִעִֽי]');
INSERT INTO verses VALUES (11029, 13, 24, 9, '[לְמַלְכִּיָּה֙] [הַחֲמִישִׁ֔י] [לְמִיָּמִ֖ן] o-sexto');
INSERT INTO verses VALUES (11030, 13, 24, 10, 'לְהַקּוֹץ֙ o sétimo para Abia o oitavo');
INSERT INTO verses VALUES (11031, 13, 24, 11, 'para Jeosua o nono para Schaniah o décimo');
INSERT INTO verses VALUES (11032, 13, 24, 12, 'para Eliashiv Ashthai dez para Yakim dois dez');
INSERT INTO verses VALUES (11033, 13, 24, 13, 'para-cúpula três dez para-Abel quatro dez');
INSERT INTO verses VALUES (11034, 13, 24, 14, 'para-Lagia cinco dez para-Amir seis dez');
INSERT INTO verses VALUES (11035, 13, 24, 15, 'para-Cire sete dez para-explosar shmonáh dez');
INSERT INTO verses VALUES (11036, 13, 24, 16, 'para-Patia nove dez Licequezkel osVINTE:');
INSERT INTO verses VALUES (11037, 13, 24, 17, 'paraYacim um e-vinte paraGamul dois e-vinte');
INSERT INTO verses VALUES (11038, 13, 24, 18, 'paraDelayahu três e-vinte paraMaazyahu quatro e-vinte');
INSERT INTO verses VALUES (11039, 13, 24, 19, 'Estas suasFunções paraSeusTrabalhos vir para-casa-de yhwh como-julgamento em-mão Aarão pai-deles como-que yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (11040, 13, 24, 20, 'e-aos-filhos-de Levi osRestantes para-filhos-de עמרם שובהאל para-filhos-de שובהאל יחדייהו');
INSERT INTO verses VALUES (11041, 13, 24, 21, '[לִרְחַבְיָ֑הוּ] aos-filhos-de [רְחַבְיָ֔הוּ] a-cabeça [יִשִּׁיָּֽה]');
INSERT INTO verses VALUES (11042, 13, 24, 22, '[לַיִּצְהָרִ֣י] [שְׁלֹמ֔וֹת] para-filhos-de [שְׁלֹמ֖וֹת] [יָֽחַת]');
INSERT INTO verses VALUES (11043, 13, 24, 23, '[וּבְנָ֖י] [יְרִיָּ֑הוּ] [אֲמַרְיָ֙הוּ֙] o-segundo [יַחֲזִיאֵל֙] o-terceiro [יְקַמְעָ֖ם] o-quarto');
INSERT INTO verses VALUES (11044, 13, 24, 24, 'filhos-de [עֻזִּיאֵל֙] [מִיכָ֔ה] para-os-filhos-de [מִיכָ֖ה]');
INSERT INTO verses VALUES (11045, 13, 24, 25, 'a-chi מִיכָה֙ ישיה para-os-filhos-de ישיה זכARYahu');
INSERT INTO verses VALUES (11046, 13, 24, 26, 'filhos-de מרARI Mahli ומושI filhos-de יעAZiyahu filho-dele');
INSERT INTO verses VALUES (11047, 13, 24, 27, 'filhos-de Merari ליעAZiyahu be-no והAHam וזכר ואברי');
INSERT INTO verses VALUES (11048, 13, 24, 28, 'לְמַחְלִי֙ Eleazar e-não a-ele a-ele filhos');
INSERT INTO verses VALUES (11049, 13, 24, 29, '[לְקִ֖ישׁ] filhos-de [יְרַחְמְאֵֽל]');
INSERT INTO verses VALUES (11050, 13, 24, 30, 'e-filhos-de de-Mushi מַחְלִ֥י וְעֵ֖דֶר וִירִימ֑וֹת Estas filhos-de os-levitas segundo-casa-de אֲבֹתֵיהֶֽם׃');
INSERT INTO verses VALUES (11051, 13, 24, 31, 'וַיַּפִּילוּ֩ também הֵ֨ם גּוֹרָל֜וֹת לְעֻמַּ֣ת ׀ seus-irmãos filhos-de Arão diante-de Davi o rei e-צָדוֹק e-Achimeleque e-cabeças os-pais para-os-sacerdotes e-para-os levitas pais o-primeiro como seu-irmão o-pequeno;');
INSERT INTO chapters VALUES (363, 13, 25, 31);
INSERT INTO verses VALUES (11052, 13, 25, 1, 'E-separou Davi e-chefe o exército para a servidão para-filhos-de Asafe e Heman e Jedutun com cetres com nablas e com cítricos E-foi em número deles e-houve obra para a sua servidão:');
INSERT INTO verses VALUES (11053, 13, 25, 2, 'aos-filhos-de Asaf זַכּ֧וּר וְיוֹסֵ֛ף וּנְתַנְיָ֥ה וַאֲשַׂרְאֵ֖לָה filhos-de אָסָ֑ף sobre mão-de Asafe הַנִּבָּ֖א sobre mãos-de o rei');
INSERT INTO verses VALUES (11054, 13, 25, 3, '[לִידוּת֑וּן] filhos-de [יְדוּת֡וּן] [גְּדַלְיָ֡הוּ] [וּצְרִ֡י] [וִֽ֠ישַׁעְיָהוּ] [חֲשַׁבְיָ֨הוּ] [וּמַתִּתְיָ֜הוּ] [שִׁשָּׁ֗ה] sobre [יְדֵ֨י] [אֲבִיהֶ֤ם] [יְדוּתוּן֙] [בַּכִּנּ֔וֹר] [הַנִּבָּ֕א] sobre [וְהַלֵּ֖ל] [לַיהוָֽה׃]');
INSERT INTO verses VALUES (11055, 13, 25, 4, 'לְהֵימָ֑ן filhos-de הֵימָ֡ן בֻּקִּיָּ֡הוּ מַתַּנְיָ֡הוּ עֻ֠זִּיאֵל שְׁבוּאֵ֨ל וִֽירִימ֜וֹת Hananias חֲנָ֗נִי אֱלִיאָ֤תָה גִדַּ֙לְתִּי֙ וְרֹמַ֣מְתִּי עֶ֔זֶר יָשְׁבְּקָ֣שָׁה מַלּ֔וֹתִי hoteir מַחֲזִיאֽוֹת׃');
INSERT INTO verses VALUES (11056, 13, 25, 5, 'todo filhos בָנִ֜ים לְהֵימָ֗ן חֹזֵ֥ה o-rei בְּדִבְרֵ֥י Elohim para os montes E-colocou E-deu os-אלהים para Hêiman quatro quatro dez e filhas três:');
INSERT INTO verses VALUES (11057, 13, 25, 6, 'todo estes sobre mãos Abiê yhwh casa yhwh com-címbalos instrumentos musicais e-liras para a adoração sobre o-Elohim sobre maos-de o-rei Ásaf e para o confissão וְהֵימָֽן׃');
INSERT INTO verses VALUES (11058, 13, 25, 7, 'e-houve misparam com irmãos-deles מְלֻמְּדֵי־ שִׁ֖יר a-yhwh todo הַ֨מֵּבִ֔ין duzentos dia וּשְׁמוֹנָֽה׃');
INSERT INTO verses VALUES (11059, 13, 25, 8, '[וַיַּפִּ֜ילוּ] [גּוֹרָל֣וֹת] [מִשְׁמֶ֗רֶת] [לְעֻמַּת֙] [כַּקָּטֹ֣ן] [כַּגָּד֔וֹל] [מֵבִ֖ין] com');
INSERT INTO verses VALUES (11060, 13, 25, 9, 'e-saiu הַגּוֹרָ֧ל הָרִאשׁ֛וֹן לְאָסָ֖ף לְיוֹסֵ֑ף גְּדַלְיָ֙הוּ֙ o-segundo ele וְאֶחָ֥יו e-seus-filhos dois dez');
INSERT INTO verses VALUES (11061, 13, 25, 10, '[הַשְּׁלִשִׁ֣י] [זַכּ֔וּר] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11062, 13, 25, 11, 'o-quarto [לַיִּצְרִ֔י] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11063, 13, 25, 12, '[הַחֲמִישִׁ֣י] [נְתַנְיָ֔הוּ] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11064, 13, 25, 13, '[הַשִׁשִּׁ֣י] [בֻקִּיָּ֔הוּ] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11065, 13, 25, 14, '[הַשְּׁבִעִ֣י] [יְשַׂרְאֵ֔לָה] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11066, 13, 25, 15, '[הַשְּׁמִינִ֣י] [יְשַֽׁעְיָ֔הוּ] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11067, 13, 25, 16, '[הַתְּשִׁיעִ֣י] [מַתַּנְיָ֔הוּ] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11068, 13, 25, 17, 'העשירי Shimei seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11069, 13, 25, 18, '[עַשְׁתֵּֽי־עָשָׂ֣ר] dez [בָּנָ֥יו] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11070, 13, 25, 19, '[הַשְּׁנֵ֤ים] dez [לַחֲשַׁבְיָ֔ה] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11071, 13, 25, 20, '[לִשְׁלֹשָׁ֤ה] dez [שֽׁוּבָאֵ֔ל] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11072, 13, 25, 21, '[לְאַרְבָּעָ֤ה] dez [מַתִּתְיָ֔הוּ] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11073, 13, 25, 22, 'para-a-quinta dez para-as-irmãs seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11074, 13, 25, 23, 'para-a-sexta dez para-chananiasu seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11075, 13, 25, 24, 'para-a-sétima dez para-que-residisse seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11076, 13, 25, 25, 'para-o-oitavo dez para-channani seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11077, 13, 25, 26, 'para-a-nona dez para-malothi seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11078, 13, 25, 27, '[לְעֶשְׂרִים֙] [לֶֽאֱלִיָּ֔תָה] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11079, 13, 25, 28, '[לְאֶחָ֤ד] e-vinte [לְהוֹתִ֔יר] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11080, 13, 25, 29, '[לִשְׁנַ֤יִם] e-vinte [לְגִדַּ֔לְתִּי] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11081, 13, 25, 30, '[לִשְׁלֹשָׁ֤ה] e-vinte [לְמַ֣חֲזִיא֔וֹת] seus-filhos e-seus-irmãos dois dez');
INSERT INTO verses VALUES (11082, 13, 25, 31, '[לְאַרְבָּעָ֤ה] e-vinte [לְרוֹמַ֣מְתִּי] [עָ֔זֶר] seus-filhos e-seus-irmãos dois dez');
INSERT INTO chapters VALUES (364, 13, 26, 32);
INSERT INTO verses VALUES (11083, 13, 26, 1, '[לְמַחְלְק֖וֹת] [לְשֹׁעֲרִ֑ים] [לַקָּרְחִ֕ים] [מְשֶֽׁלֶמְיָ֥הוּ] filho-de chamou de filhos-de');
INSERT INTO verses VALUES (11084, 13, 26, 2, '[וְלִמְשֶֽׁלֶמְיָ֖הוּ] [בָּנִ֑ים] [זְכַרְיָ֤הוּ] o-primogênito [יְדִֽיעֲאֵ֣ל] o-segundo [זְבַדְיָ֙הוּ֙] o-terceiro [יַתְנִיאֵ֖ל] o-quarto');
INSERT INTO verses VALUES (11085, 13, 26, 3, '[עֵילָ֤ם] [הַחֲמִישִׁי֙] [יְהוֹחָנָ֣ן] o-sexto [אֶלְיְהוֹעֵינַ֖י] [הַשְּׁבִיעִֽי]');
INSERT INTO verses VALUES (11086, 13, 26, 4, 'וּלְעֹבֵ֥ד homem בָּנִ֑ים שְׁמַֽעְיָ֤ה o-primogênito יהוֹזָבָ֣ד o-segundo Yoach o-terceiro וְשָׂכָ֣ר o-quarto וּנְתַנְאֵ֖ל o-quinto');
INSERT INTO verses VALUES (11087, 13, 26, 5, '[עַמִּיאֵ֤ל] [הַשִּׁשִּׁי֙] [יִשָׂשכָ֣ר] o-sétimo [פְּעֻלְּתַ֖י] [הַשְּׁמִינִ֑י] que [בֵרֲכ֖וֹ] Elohim');
INSERT INTO verses VALUES (11088, 13, 26, 6, 'וְלִֽשְׁמַֽעְיָ֤ה בְנוֹ נוֹלַד בָּנִים הַמִּמְשָׁלִ֖ים para-casa-de pai-deles porque גִבּ֥וֹרֵי valor eles');
INSERT INTO verses VALUES (11089, 13, 26, 7, 'filhos-de [שְׁמַֽעְיָ֗ה] [עָ֠תְנִי] [וּרְפָאֵ֨ל] [וְעוֹבֵ֧ד] [אֶלְזָבָ֛ד] seus-irmãos filhos-de força [וּסְמַכְיָֽהוּ]');
INSERT INTO verses VALUES (11090, 13, 26, 8, 'todo estas [׀] servo homem [הֵ֤מָּה] [וּבְנֵיהֶם֙] [וַאֲחֵיהֶ֔ם] אִישׁ- [בַּכֹּ֖חַ] [לַעֲבֹדָ֑ה] [שִׁשִּׁ֥ים] sessenta [לְעֹבֵ֥ד] [אֱדֹֽם] homem');
INSERT INTO verses VALUES (11091, 13, 26, 9, 'e-limšelemayahu banim ve-achim filhos-de chayil shmonáh dez');
INSERT INTO verses VALUES (11092, 13, 26, 10, 'u-lechosah de filhos-de miseria banim que haraosh porque não foi bekor va-yashimenu aviyahu para-a-cabeça:');
INSERT INTO verses VALUES (11093, 13, 26, 11, 'separação-o o-segundo imergiu-o o-terceiro זְכַרְיָ֖הוּ [הָרְבִעִ֑י] todo banim ve-achim para-chorar três dez');
INSERT INTO verses VALUES (11094, 13, 26, 12, 'para-as separações as-que-são para os chefes de dos homens as-muradas para-a אֲחֵיהֶ֑ם para-serviço em-casa-de yhwh');
INSERT INTO verses VALUES (11095, 13, 26, 13, 'e-deram sorteados como-pequeno como-grande segundo-casa-de pais-deles para-a-porta e-à-porta:');
INSERT INTO verses VALUES (11096, 13, 26, 14, 'e-caiu o-lar oeste para-Selemayahu: e-Zekaryahu: seu-filho conselheiro de-sabedoria eles-deram sorteios-lhes e-ele-saiu go''ărălō tsāphōnā');
INSERT INTO verses VALUES (11097, 13, 26, 15, 'לעבוד⁥ homem ne''g̠b̠b̠ā e-para-seus-filhos casa hā''ăśûp̄pîm');
INSERT INTO verses VALUES (11098, 13, 26, 16, 'ləšūph̄pîm wələkhōsāh lammā''ărab povo portão šallēk̠eṯ bəməsīl̠lāh hā''ăʿōlā משמר próximo-a משמר׃');
INSERT INTO verses VALUES (11099, 13, 26, 17, 'לַמִּזְרָח֮ os levitas שִׁשָּׁה֒ לַצָּפ֤וֹנָה para o dia quatro לַנֶּ֥גְבָּה para-o-dia quatro וְלָאֲסֻפִּ֖ים dois dois');
INSERT INTO verses VALUES (11100, 13, 26, 18, 'לַפַּרְבָּ֖ר לַֽמַּעֲרָ֑ב quatro לַֽמְסִלָּ֔ה dois para-par');
INSERT INTO verses VALUES (11101, 13, 26, 19, 'Estas machalkot ha-sha-arei para-filhos-de ha-qerchi e-aos-filhos-de Merari');
INSERT INTO verses VALUES (11102, 13, 26, 20, 've-ha-leviyim achiya sobre otzrot casa os-Elohim ule-otzerot os-santos');
INSERT INTO verses VALUES (11103, 13, 26, 21, 'filhos-de la-adan filhos-de ha-gershuni לְלַעְדָּ֗ן רָאשֵׁי os-pais לְלַעְדָּ֥ן o-gersonita יְחִיאֵלִֽי׃');
INSERT INTO verses VALUES (11104, 13, 26, 22, 'filhos-de יְחִֽיאֵלִ֑י זֵתָם֙ e Joel irmão-seu sobre אֹצְר֖וֹת yhwh yhwh');
INSERT INTO verses VALUES (11105, 13, 26, 23, '[לַֽעַמְרָמִי֙] [לַיִּצְהָרִ֔י] [לַֽחֶבְרוֹנִ֖י] [לָֽעָזִּיאֵלִֽי]');
INSERT INTO verses VALUES (11106, 13, 26, 24, '[וּשְׁבֻאֵל֙] filho-de [בֶּן־מֹשֶׁ֔ה] filho-de Moisés sobre');
INSERT INTO verses VALUES (11107, 13, 26, 25, 'e-seus-irmãos [לֶֽאֱלִיעֶ֑זֶר] [רְחַבְיָ֨הוּ] [בְנ֜וֹ] [וִֽישַׁעְיָ֤הוּ] [בְנוֹ֙] [וְיֹרָ֣ם] seu-filho [וְזִכְרִ֥י] filho-dele filho-seu');
INSERT INTO verses VALUES (11108, 13, 26, 26, 'ele שְׁלֹמ֣וֹת e os seus irmãos sobre todo as suas arrecadações os-santos que santificou Davi o rei e os seus chefes os-pais para os seus comandantes dos milhares e dos centenas e-príncipes-de הַצָּבָֽא׃');
INSERT INTO verses VALUES (11109, 13, 26, 27, 'de das batalhas e-de o-salvamento santificaram yhwh segundo-casa-de yhwh');
INSERT INTO verses VALUES (11110, 13, 26, 28, 'e-tudo que santificou Shemu''el הראיה e Saulo filho-de קיס e-אַבְנֵר filho-de נֵר ויואב filho-de sobre todo ה막דיש sobre mão-de שלomit ואחי׃');
INSERT INTO verses VALUES (11111, 13, 26, 29, '[לַיִּצְהָרִ֞י] [כְּנַנְיָ֣הוּ] [וּבָנָ֗יו] [לַמְּלָאכָ֤ה] [הַחִֽיצוֹנָה֙] sobre Israel [וּלְשֹׁפְטִֽים]');
INSERT INTO verses VALUES (11112, 13, 26, 30, 'para o חֶבְרוֹנִ֡י Chashavyahu֩ e seus אֶחָ֨יו filhos-de Chayil mil sobre centenas sobre פקודה Israel do-outro-lado a-todo Ma''arava֑ yhwh obra-de yhwh e para a עֲבֹדַ֖ת o rei');
INSERT INTO verses VALUES (11113, 13, 26, 31, 'para o חֶבְרוֹנִי֙ Yeriyahָ֣ o-primeiro para o Hébronite para as descendências dele para os pais em-ano-de os quarenta para a monarquia Davi foram buscados e achou neles gibo-rei valor em Jazer gil-ad');
INSERT INTO verses VALUES (11114, 13, 26, 32, 'e-irmãos-de-o filhos-de fortes [וּשְׁבַ֥ע] e-sete centenas cabeças-de [וַיַּפְקִידֵ֞ם] [דָּוִ֣יד] Davi o rei sobre [וַחֲצִי֙] [שֵׁ֣בֶט] [הַֽמְנַשִּׁ֔י] tribo-de [הָאֱלֹהִ֖ים] para-todo palavra');
INSERT INTO chapters VALUES (365, 13, 27, 34);
INSERT INTO verses VALUES (11115, 13, 27, 1, 'e-filhos-de יִשְׂרָאֵ֣ל ׀ לְֽמִסְפָּרָ֡ם cabeças-de הָאָב֣וֹת e-príncipes-de הָֽאֲלָפִ֣ים וְהַמֵּא֡וֹת e os juízes os que fazem separar a o-rei para todos o a-todo as divisões que entra e a que sai novo no mês de para-todo os meses das a-todo da divisão a primeira vinte e-quatro mil');
INSERT INTO verses VALUES (11116, 13, 27, 2, 'sobre a-machloket a-primeira para-o-mês harishon yashav''am filho-de zavdiel e-sobre machloket-o vinte e-quatro mil');
INSERT INTO verses VALUES (11117, 13, 27, 3, 'de filhos-de peret ha-rosh para-todo príncipes-de ha-tzva''ot para-o-mes o-primeiro:');
INSERT INTO verses VALUES (11118, 13, 27, 4, 'e-sobre machloket o-mês haseni dodai o meu irmão e sua divisão e suas caixas o distinguidos e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11119, 13, 27, 5, 'comandante-de o exército o-terceiro para-o-mês o-terceiro Benayahu filho-de Joiada o-sacerdote cabeça e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11120, 13, 27, 6, 'ele filho dele heroi- os trinta e-sobre os trinta e sua divisão Amizvad filho-seu');
INSERT INTO verses VALUES (11121, 13, 27, 7, 'o-quarto para-o-mês o-quarto ele-fez El Ai יוֹאָב וּזְבַדְיָ֥ה filho-dele atrás-dele e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11122, 13, 27, 8, 'הַחַמִישׁי֙ no-mês הַחֲמִישִׁ֔י הַשַּׂ֖ר שַׁמְה֣וּת הַיִּזְרָ֑ח e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11123, 13, 27, 9, 'הַשִּׁשִּׁי֙ no-mês o-sexto עִירָא filho-de IQUEשׁ הַתְּקוֹעִ֑י e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11124, 13, 27, 10, 'o sétimo no-mês o-sétimo חֶ֥לֶץ הַפְּלוֹנִ֖י de filhos-de Efraim e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11125, 13, 27, 11, 'o sétimo no-mês o-oitavo סִבְּכַ֥י הַחֻשָׁתִ֖י para-a-rachí e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11126, 13, 27, 12, 'o-ninth para-o-mês o-ninth abiezer o-answered e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11127, 13, 27, 13, 'o-tenth para-o-mês o-tenth my-hurry o-dew para-a-rachí e-sobre a divisão dele vinte e-quatro mil');
INSERT INTO verses VALUES (11128, 13, 27, 14, 'עשתiei- dez para fazer dez o mês de construção da expansão dele de filhos-de Efraim e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11129, 13, 27, 15, 'השנים dez para dois dez o mês minha esperança da gema dele para Atanásio e-sobre sua-divisao vinte e-quatro mil');
INSERT INTO verses VALUES (11130, 13, 27, 16, 'e-sobre tribos-de Israel para Reuven príncipe אליעזר filho-de me lembre para Shimon Shaphatiahu filho-de ma''akah');
INSERT INTO verses VALUES (11131, 13, 27, 17, 'para Levi Chashavya filho-de qemu-el para-Aaron צッドוק׃');
INSERT INTO verses VALUES (11132, 13, 27, 18, 'para-Judá אליהו dos meus irmãos David para Zebulun Amri filho-de Michael');
INSERT INTO verses VALUES (11133, 13, 27, 19, 'para-Zebulom [יִֽשְׁמַֽעְיָ֖הוּ] filho-de [לְנַ֨פְתָּלִ֔י] para-Naftali [בֶּן־עַזְרִיאֵֽל׃] filho-de');
INSERT INTO verses VALUES (11134, 13, 27, 20, 'aos-filhos-de Efraim Hosea filho-de עזיהו לחצי tribo-de Manassés Yoel- filho-de פדיהו');
INSERT INTO verses VALUES (11135, 13, 27, 21, 'לחצי o-Manasseh גלעדא ידדו filho-de זכARYahu a Benjamim יעSAIel filho-de Abner');
INSERT INTO verses VALUES (11136, 13, 27, 22, 'para-Dã עזARYel filho-de Estas estes sarei tribos-de Israel');
INSERT INTO verses VALUES (11137, 13, 27, 23, 'e-não נSHA Davi em número deles למבEN vinte ano que disse yhwh yhwh להרבOT a Israel como-estrelas-de os-céus');
INSERT INTO verses VALUES (11138, 13, 27, 24, 'יהOAv filho-de צְרוּיָה começou para-contar e-não e-houve E-foi בזOA ketsef sobre subir e-não subiu הMASפר em-número דְּבָרַי os-dias para-o-rei Davi');
INSERT INTO verses VALUES (11139, 13, 27, 25, 'e-sobre אֹצְרוֹת o-rei Azmavete filho-de עֲדִיאֵל e-sobre הָאֹצְרוֹת em-o-sadê בֵּעָרִים וּבַכְּפָרִים וּבַמִּגְדָּל֔וֹת Jonatas filho-de עֻזִיָּֽהוּ׃');
INSERT INTO verses VALUES (11140, 13, 27, 26, 'e-sobre עֹשְׂיֵי֙ obra-de o-campo לַעֲבוֹדַת a-terra עֶזְרִ֖י filho-de כּוֹלּוּב׃');
INSERT INTO verses VALUES (11141, 13, 27, 27, 'e-sobre [שִׁמְעִ֖י] [הָרָֽמָתִ֑י] [וְעַ֤ל] e-sobre [לְאֹצְר֣וֹת] [הַיַּ֔יִן] [זַבְדִּ֖י] [הַשִּׁפְמִֽי׃]');
INSERT INTO verses VALUES (11142, 13, 27, 28, 'e-sobre הַזֵּיתִים וְהַשָּׁקְמִים֙ que בַּשֶּׁפֶלָה Baal Hanã הַגְּדֵרִי e-sobre אֹצְרוֹת o-a-sínden יוֹעַשׁ׃');
INSERT INTO verses VALUES (11143, 13, 27, 29, 'e-sobre [הָרֹעִ֣ים] [בַּשָּׁר֔וֹן] [*שטרי] [**שִׁרְטַ֖י] e-sobre o-bovino [בָּֽעֲמָקִ֔ים] [שָׁפָ֖ט] filho-de');
INSERT INTO verses VALUES (11144, 13, 27, 30, 'e-sobre os-gamallis obil o-yishmaelui e-sobre as-atonot yechdayhu o-meronotiy');
INSERT INTO verses VALUES (11145, 13, 27, 31, 'e-sobre a-o-rebanho yaziz o-hagri todo estes príncipes-de harkeush que para-o-rei Davi');
INSERT INTO verses VALUES (11146, 13, 27, 32, '[וִֽיהוֹנָתָ֤ן] [דּוֹד־דָּוִיד֙] Davi [אִישׁ־מֵבִ֥ין] homem-de ele [וִֽיחִיאֵ֥ל] ele [עִם־בְּנֵ֥י] filho-de com filhos-de');
INSERT INTO verses VALUES (11147, 13, 27, 33, 'וַאֲחִיתֹ֖פֶל יוֹעֵ֣ץ ao-rei וְחוּשַׁ֥י הָאַרְכִּ֖י mau o rei');
INSERT INTO verses VALUES (11148, 13, 27, 34, 'e-depois-de [אֲחִיתֹ֗פֶל] [יְהוֹיָדָ֤ע] filho-de Benaia [וְשַׂר־צָבָ֥א] e-príncipe-de [יוֹאָֽב׃]');
INSERT INTO chapters VALUES (366, 13, 28, 21);
INSERT INTO verses VALUES (11149, 13, 28, 1, '[וַיַּקְהֵ֣ל] Davi a todo príncipes-de Israel príncipes-de [הַמַּחְלְק֣וֹת] e-príncipes-de [אֶת־הַמֶּ֟לֶךְ] [וְשָׂרֵ֣י] a [וְשָׂרֵ֣י] e-príncipes-de [וְשָׂרֵ֣י] e-príncipes-de [׀] e-príncipes-de todo [עִם־הַסָּרִיסִ֧ים] [וְהַגִּבּוֹרִ֛ים] [וּֽלְכָל־גִּבּ֥וֹר] [חָ֖יִל] com a');
INSERT INTO verses VALUES (11150, 13, 28, 2, 'E-levantou Davi o rei sobre E-disse E-disse שְׁמָע֖וּנִי irmãos-meus וְעַמִּ֑י eu com לְבָבִ֡י לִבְנוֹת֩ casa מְנוּחָ֜ה para o arão em-aliança-de yhwh e para a haddôm pés-de nosso-Elohim e eu faria para-construir');
INSERT INTO verses VALUES (11151, 13, 28, 3, 'e os elohim disse a-mim não construirás casa que porque homem tu tu e sangue [sem-traducao]');
INSERT INTO verses VALUES (11152, 13, 28, 4, 'e escolheu yhwh elohim Israel em mim de-toda casa-de pai-meu ser para o rei sobre que para-sempre porque em Juda escolheu para o governador u-b''veit Judá casa pai-meu e nos filhos pai-meu por-mim queria para reinar sobre todo Israel');
INSERT INTO verses VALUES (11153, 13, 28, 5, 'e de todos os que porque muitos dar deu yhwh yhwh e escolheu Solomão filhos-de para sentar-se sobre yhwh מלכות yhwh sobre Israel');
INSERT INTO verses VALUES (11154, 13, 28, 6, 'E-disse a-mim Shelomoh seu filho ele construirá minha-casa e-suas-muradas nele eu-escolhi nele a-mim para Ben e-eu אֶֽהְיֶה־ para-ele para-pai');
INSERT INTO verses VALUES (11155, 13, 28, 7, 'e-preparrei a sua-maçonaria até para-sempre se será-fortalecido para-fazer minhas-prescrições não como-o-dia a-esta');
INSERT INTO verses VALUES (11156, 13, 28, 8, 'e-agora perante todo Israel assembleia- yhwh e-em-ouvidos nosso-Elohim shimru yhwh todo mandamentos yhwh vosso-Elohim para-que guardai-vos a a-terra a-boa e-herdar-vos aos-vossos-filhos depois-de-vós até eternidade');
INSERT INTO verses VALUES (11157, 13, 28, 9, 'e-tu salomão- filhos-de sabed a Elohim-de teu-pai e-servi-lo no-coração שָׁלוֹם que חַפְצָה porque yhwh לְבָבֹת דֹּרֵשׁ yhwh e-todo יִצֶר para-ti מֵבִין se תִּדְרַשׁ־נָהּ יִמָּצֵא yhwh e-se תַּעֲזֹב־נָהּ יַזְנִיחֲכֶם לָעַֽד׃');
INSERT INTO verses VALUES (11158, 13, 28, 10, '[רְאֵ֣ה] agora porque yhwh [בָּ֧חַר] [בְּךָ֛] para-construir- casa [חֲזַ֥ק] forte');
INSERT INTO verses VALUES (11159, 13, 28, 11, 'E-colocou Davi para-שְׁלֹמֹה בְנ֡וֹ a תַּבְנִיט הָאוּלָם֩ e-a בָּ֨תָּ֜יו וְגַנְזַכּ֧יו וַעֲלִיֹּתָ֛יו וַחֲדָרָ֥יו os internos e-casa-de ha-kappōret');
INSERT INTO verses VALUES (11160, 13, 28, 12, 'e a modelagem todo que ser pelo vento com-ele para estender casa-de yhwh e-para-todo- as cortinas ao-redor para guardar casa os-Elohim e para guardar os-santos');
INSERT INTO verses VALUES (11161, 13, 28, 13, 'e para dividir os-sacerdotes e os levitas e-para-todo trabalho serviço casa-de yhwh e-para-todo yhwh serviço casa-de yhwh');
INSERT INTO verses VALUES (11162, 13, 28, 14, 'para o ouro no misqal para o ouro para-todo kléi- obra a-todo para-todo instrumentos a-prata no misqal para-todo kléi- obra e obra:');
INSERT INTO verses VALUES (11163, 13, 28, 15, 'e misqal para as manóras o-ouro e-las-elas ouro por-peso-de candeia candeia e-as-luzes-elas e-pelas-candeias a-prata por-peso-de para-a-candeia e-as-luzes-elas segundo-a-trabalho מנורה ומנורה׃');
INSERT INTO verses VALUES (11164, 13, 28, 16, 'e-[OBJ] [מִשְׁקָ֛ל] [לְשֻׁלְחֲנ֥וֹת] [הַֽמַּעֲרֶ֖כֶת] [לְשֻׁלְחַ֣ן] [וְשֻׁלְחָ֑ן] [וְכֶ֖סֶף] [לְשֻׁלְחֲנ֥וֹת] [הַכָּֽסֶף]');
INSERT INTO verses VALUES (11165, 13, 28, 17, 'והמזלגות e-as-bacias e a pressão ouro puro e para os compradores o-ouro em o peso para comprar e para vender e para os compradores o dinheiro em o peso para comprar e para vender');
INSERT INTO verses VALUES (11166, 13, 28, 18, 'e-no altar a-a incenso ouro purificado-está no-pesado e-a forma a-carruagem os-querubins ouro para-desdobrar e-escudos sobre arca em-aliança-de yhwh');
INSERT INTO verses VALUES (11167, 13, 28, 19, 'tudo no-escrevido de-mão-de yhwh sobre-mim entendeu todo מלאכים התבנית׃');
INSERT INTO verses VALUES (11168, 13, 28, 20, 'E-disse דּוֹוִד para-שְׁלֹמֹה בנו חזק ואמצ וַעֲשֵׂ֔ה a temas que yhwh que yhwh Elohim não contigo não ירפכת e-não יעזבך até לכלות todo מלאכת serviço casa-de yhwh');
INSERT INTO verses VALUES (11169, 13, 28, 21, 'e-eis מחולקות os-sacerdotes e os levitas para-todo trabalho casa o-Elohim e contigo em-todo trabalho para-todo generoso com sabedoria para-todo trabalho e os cantores e-todo o-povo para-todo as tuas palavras');
INSERT INTO chapters VALUES (367, 13, 29, 30);
INSERT INTO verses VALUES (11170, 13, 29, 1, 'E-disse Davi o rei para-todo o-a congregação Salomão um um escolheu- nele Elohim jovem e manso que não porque não que הַבִּירָ֔ה porque para-יהוה Elohim');
INSERT INTO verses VALUES (11171, 13, 29, 2, 'e de todo- força me- preparei-me o-ouro אֱלֹהַי o zahav ׀ para o zahav e a kesef para a kesef e o nechoshet [הַבַּרְזֶל֙] o ferro para o barzel e os árvores- para os árvores pedras-de e o cedro e a liba e-tudo pedra e a seda e-todo pedra preciosa e pedras de safira para-multidão');
INSERT INTO verses VALUES (11172, 13, 29, 3, 'e mais em meus alegres contentamentos em-casa-de meu-Elohim há para-mim ouro ouro dei eu-deti para-casa-de אֱלֹהַי acima de-todo a-ele segundo-casa-de o-santuário');
INSERT INTO verses VALUES (11173, 13, 29, 4, 'שלושת אלפים ככר ouro מזהב אוֹפִ֑יר ושביעת milhares k-khar- prata מזוקק לא褊 קירות as-casas');
INSERT INTO verses VALUES (11174, 13, 29, 5, 'לזהב לזהב ולכסף לכסף e-para-todo- obra em-mão-de חָרָשִׁים e-quem מִתְנַדֵּב sua-mão o-dia o-dia para-יהוה');
INSERT INTO verses VALUES (11175, 13, 29, 6, '[וַיִּֽתְנַדְּבוּ֩] príncipes-de os-pais [וְשָׂרֵ֣י] tribos-de Israel e-príncipes-de [וְשָׂרֵ֤י] [הָאֲלָפִים֙] [וְהַמֵּא֔וֹת] obra-de o rei');
INSERT INTO verses VALUES (11176, 13, 29, 7, 'וַֽיִּתְּנ֞וּ לַעֲבוֹדַ֣ת casa-de ouro ouro כִּכָּרִ֣ים חֲמֵֽשׂת־ אלפים֮ ואדרכנִ֣ים רבּוֹ֒ e prata כִּכָּרִים֙ dez milhares וּנְחֹ֕שֶׁת רבּ֛וֹ וּשְׁמוֹנַ֥ת dois-mil כִּכָּרִים וּבַרְזֶ֖ל cem de mil כִּכָּרִֽים׃');
INSERT INTO verses VALUES (11177, 13, 29, 8, '[וְהַנִּמְצָ֤א] com-ele [אֲבָנִ֔ים] deram para-tesouro-de casa-de sobre sobre mão-de');
INSERT INTO verses VALUES (11178, 13, 29, 9, 'וַיִּשְׂמְח֤וּ o-povo sobre que porque b-le-ve paz הִֽתְנַדְּב֖וּ a-yhwh e-também Davi o-rei שָׂמַ֖ח שִׂמְחָ֥ה גְדוֹלָה׃');
INSERT INTO verses VALUES (11179, 13, 29, 10, 'E-abençoou Davi a yhwh aos-olhos-de E-disse a-assembleia E-disse tu yhwh tu yhwh Elohim-de Israel אָבִ֔ינוּ desde-eternidade e-até eternidade');
INSERT INTO verses VALUES (11180, 13, 29, 11, 'a-ti yhwh הַגְּדֻלָּ֨ה וְהַגְּבוּרָ֤ה וְהַתִּפְאֶ֙רֶת֙ e o triunfo e a glória porque todo nos-céus a-ti yhwh yhwh a realeza a-todo para tudo para-a-cabeça:');
INSERT INTO verses VALUES (11181, 13, 29, 12, 'e a riqueza e o esplendor ante ti e-tu senhor em-todo e-com-mão-tua força e a força na tua mão para crescer e fortalecer para-todo');
INSERT INTO verses VALUES (11182, 13, 29, 13, 'e-agora Elohim-nosso declaram nos para-ti e louvadores ao Seu nome Sua beleza');
INSERT INTO verses VALUES (11183, 13, 29, 14, 'e porque quem eu e-quem povo-meu porque [כֹּ֔חַ] כֹּחַ para nos oferecermos assim porque de Ti o todo para-ti נָתַ֥נּוּ para-ti');
INSERT INTO verses VALUES (11184, 13, 29, 15, 'porque [אֲנַ֧חְנוּ] [לְפָנֶ֛יךָ] [וְתוֹשָׁבִ֖ים] [כְּכָל־אֲבֹתֵ֑ינוּ] conforme-toda [׀] [יָמֵ֛ינוּ] [עַל־הָאָ֖רֶץ] sobre a-terra');
INSERT INTO verses VALUES (11185, 13, 29, 16, 'yhwh Elohim-nosso todo הֶהָמ֤וֹן o-este que הֲכִינֹ֔נוּ para-construir- para-ti casa para-nome-de sua santidade da tua mão e para ti tudo');
INSERT INTO verses VALUES (11186, 13, 29, 17, 'eu saberia meu-Elohim que tu בֹּחֵ֣ן לֵבָב e retos serias agradado eu em retidão no meu coração eu me dispus todo e-agora e-agora seu-people הַנִּמְצְאוּ- aqui רָאִ֥יתִי com-alegria לְהִֽתְנַדֶּב- para-ti');
INSERT INTO verses VALUES (11187, 13, 29, 18, 'yhwh Elohim Abraão Isaque e-Israel nossos-pais שֳׁמְרָה- isto para-sempre לְיֵ֥צֶר מַחְשְׁב֖וֹת לְבַ֣ב povo-teu והכן לְבָבָ֖ם para-ti');
INSERT INTO verses VALUES (11188, 13, 29, 19, 'וְלִשְׁלֹמֹ֣ה filhos-de תֵּ֚ן לֵבָ֣ב paz לִשְׁמוֹר֙ מִצְוֺתֶ֔יךָ עֵדְוֺתֶ֖יךָ וְחֻקֶּ֑יךָ וְלַעֲשׂ֣וֹת o todo וְלִבְנ֖וֹת הַבִּירָ֥ה que הֲכִינֽוֹתִי׃');
INSERT INTO verses VALUES (11189, 13, 29, 20, 'E-disse Davi para-todo [בָּ֥רְכוּ] [נָ֖א] por-favor a yhwh vosso-Elohim [לַיהוָה֙] todo [אֲבֹֽתֵיהֶ֔ם] para-יהוה Elohim-de [לַיהוָ֖ה] [וְלַמֶּֽלֶךְ]');
INSERT INTO verses VALUES (11190, 13, 29, 21, 'וַיִּזְבְּח֣וּ לַיהוָ֣ה ׀ זְ֠בָחִים vayaalu ofertas-de-sacrifício a-yhwh לְֽמָחֳרַת֮ o-dia o-dia פָּרִ֨ים mil carneiros mil cordeiros mil e os nisgaihem e os zebachim para-multiplicar para-todo Israel');
INSERT INTO verses VALUES (11191, 13, 29, 22, 'e comeram e beberam diante-de yhwh no-dia aquele בְּשִׂמְחָ֣ה grande e reinaram שֵׁנִית֙ para-שְׁלֹמֹה filho-de Davi e-eles-ungeram לַיהוָ֛ה para nagid e para zadok para kohen');
INSERT INTO verses VALUES (11192, 13, 29, 23, 'e-sentou salomão sobre yhwh Yahweh para rei debaixo-de seu-pai pai-dele e teceu-se-lhe bem a-ele a-ele todo Israel');
INSERT INTO verses VALUES (11193, 13, 29, 24, 'e-todo os-príncipes e os valentes e também todo filhos-de o-rei mão debaixo mão sob Salomão o rei');
INSERT INTO verses VALUES (11194, 13, 29, 25, 'e exaltou-se yhwh a שְׁלֹמֹה acima aos-olhos-de E-colocou Israel E-deu sobre-ele glória reino que não foi sobre todo rei diante-dele sobre Israel');
INSERT INTO verses VALUES (11195, 13, 29, 26, 'e Davi filho-de יִשַׁי rei sobre todo Israel');
INSERT INTO verses VALUES (11196, 13, 29, 27, 'e-os-dias que rei sobre Israel quarenta ano em-חֶבְרוֹן rei sete dois e em Jerusalém rei trinta e três');
INSERT INTO verses VALUES (11197, 13, 29, 28, 'E-morreu no verão טובה sete dias dez וְכָבוֹד e-reinou Salomão filho-dele em-lugar-dele');
INSERT INTO verses VALUES (11198, 13, 29, 29, '[וְדִבְרֵי֙] Davi o-rei [הָרִאשֹׁנִ֖ים] [וְהָאֲחרֹנִ֑ים] eis-os escritos sobre palavras-de Samuel [וְעַל־דִּבְרֵי֙] e-sobre palavras-de deu o-profeta e-sobre');
INSERT INTO verses VALUES (11199, 13, 29, 30, 'povo todo [וּגְבוּרָת֑וֹ] [וְהָעִתִּ֗ים] [אֲשֶׁ֨ר] que [עָלָיו֙] sobre-ele e-sobre Israel e-sobre todo');
INSERT INTO books VALUES (14, '2CH', '2 Crônicas', 'AT', 36);
INSERT INTO chapters VALUES (368, 14, 1, 18);
INSERT INTO verses VALUES (11200, 14, 1, 1, 'e-se-fortaleceu Salomão filho-de David sobre reino-dele e-יהוה Elohim-dele com-ele e-engrandeceu-ele para-cima');
INSERT INTO verses VALUES (11201, 14, 1, 2, 'E-disse Shelomoh para-todo Israel para-príncipes-de os-milhares e-as-centenas e-para-os-juízes e-para-todo príncipe-de para-todo Israel topos-de os-pais');
INSERT INTO verses VALUES (11202, 14, 1, 3, 'e-foram שְׁלֹמֹה e-todo a-assembleia com-ele para-o-lugar-alto que em-Gibeão ser nome foi tenda-de encontro הָֽאֱלֹהִ֔ים que fez Moisés servo- yhwh no-deserto');
INSERT INTO verses VALUES (11203, 14, 1, 4, 'mas arca o-Elohim fez-subir Davi de-Quiriate Jearim quando-preparou a-ele Davi que estendeu para-ele tenda em-Jerusalém');
INSERT INTO verses VALUES (11204, 14, 1, 5, 'e-altar-de o-bronze que fez Bezalel filho-de Uri filho-de Hur nome yhwh tabernáculo-de yhwh e-buscaram-no Salomão e-a-assembleia');
INSERT INTO verses VALUES (11205, 14, 1, 6, 'e-subiu Salomão nome sobre altar-de o-bronze yhwh yhwh que para-tenda-de de-encontro e-subiu sobre-ele holocaustos mil');
INSERT INTO verses VALUES (11206, 14, 1, 7, 'na-noite a-aquela apareceu Elohim para-Salomão E-disse a-ele pede que darei para-ti');
INSERT INTO verses VALUES (11207, 14, 1, 8, 'E-disse שְׁלֹמֹה para-Elohim tu fizeste com Davi pai-meu bondade grande e-fizeste-reinar-me em-lugar-dele');
INSERT INTO verses VALUES (11208, 14, 1, 9, 'agora yhwh Elohim seja-confirmada palavra-tua povo Davi pai-meu que tu fizeste-reinar-me sobre povo muito a-terra a-terra');
INSERT INTO verses VALUES (11209, 14, 1, 10, 'agora sabedoria e-conhecimento dá para-mim e-sairei diante-de o-povo- este e-entrarei porque quem julgará a povo-teu este o-grande');
INSERT INTO verses VALUES (11210, 14, 1, 11, 'e-disse Elohim para-Salomão porque que era esta com coração-teu e-não pediste dez riquezas e-honra e-את alma inimigos-teus não dias muitos não pediste e-pediste para-ti sabedoria e-conhecimento que julgarás a povo-meu que fiz-reinar-te sobre-ele');
INSERT INTO verses VALUES (11211, 14, 1, 12, 'a-sabedoria e-o-conhecimento dado para-ti e-riqueza e-bens e-honra darei para-ti que não foi assim para-os-reis que diante-de-ti não não ele-será- assim');
INSERT INTO verses VALUES (11212, 14, 1, 13, 'E-veio שְׁלֹמֹה do-lugar-alto que em-Gibeão Jerusalém de-diante-de tenda de-encontro e-reinou sobre Israel');
INSERT INTO verses VALUES (11213, 14, 1, 14, 'e-reuniu Salomão carros e-cavaleiros e-foi para-ele mil e-quatro-de novecentos carros e-dois- dez mil cavaleiros e-ele-os-colocou em-cidades-de o-carro e-com- o-rei Birushalaim');
INSERT INTO verses VALUES (11214, 14, 1, 15, 'E-colocou o-rei a a-prata e-a o-ouro birushalaim como-as-pedras dar os-cedros deu como-os-sicômoros que na-planície para-multidão');
INSERT INTO verses VALUES (11215, 14, 1, 16, 'e-saída-de os-cavalos que para-Salomão de-Egito e-de-Que comerciantes-de o-rei de-Que eles-tomarão por-preço');
INSERT INTO verses VALUES (11216, 14, 1, 17, 'e-eles-fizeram-subir e-eles-fizeram-sair de-Egito carro por-seis centenas-de prata e-cavalo por-cinquenta e-cem e-assim para-todo reis-de os-heteus e-reis-de Arã por-mão-deles eles-faziam-sair');
INSERT INTO verses VALUES (11217, 14, 1, 18, 'E-disse Salomão para-construir casa para-nome-de yhwh e-casa para-reino-dele');
INSERT INTO chapters VALUES (369, 14, 2, 17);
INSERT INTO verses VALUES (11218, 14, 2, 1, 'e-ele-contou שְׁלֹמֹה setenta mil homem carregadores e-oitenta mil homem cortadores na-montanha e-supervisores sobre-eles três dois-mil e-seis centenas');
INSERT INTO verses VALUES (11219, 14, 2, 2, 'e-enviou Shelomoh a Hirão dizendo Tiro para-dizer como-que tu-fizeste com Davi pai-meu e-tu-enviaste- para-ele cedros para-construir- para-ele casa para-habitar em-ele');
INSERT INTO verses VALUES (11220, 14, 2, 3, 'eis eu construindo- casa para-nome-de yhwh Elohim-meu para-consagrar a-ele para-queimar diante-dele incenso-de especiarias e-disposição-de contínua e-holocaustos para-a-manhã e-para-a-tarde para-os-sábados e-para-as-luas-novas yhwh yhwh Elohim-nosso esta esta sobre Israel');
INSERT INTO verses VALUES (11221, 14, 2, 4, 'e-a-casa que eu construindo grande porque grande Elohim-nosso de-todo Elohim');
INSERT INTO verses VALUES (11222, 14, 2, 5, 'e-quem deterá- força para-construir- que casa porque os-céus não os-céus não ele-o-conterá e-quem eu que que para-ele casa porque se para-queimar diante-de-ele');
INSERT INTO verses VALUES (11223, 14, 2, 6, 'e-agora envia- a-mim homem sábio para-fazer no-ouro e-na-prata e-no-bronze e-no-ferro e-na-púrpura e-carmesim e-azul e-conhecedor para-gravar gravuras com os-sábios que comigo em-Judá e-em-Jerusalém que preparou Davi pai-meu');
INSERT INTO verses VALUES (11224, 14, 2, 7, 'e-envia para-mim madeiras-de cedros ciprestes e-sândalo que porque eu soube que servos-teus sabem para-cortar madeiras-de Líbano e-eis servos-meus com servos-teus');
INSERT INTO verses VALUES (11225, 14, 2, 8, 'e-para-preparar para-mim madeiras em-abundância que a-casa que eu construo grande e-maravilhosa');
INSERT INTO verses VALUES (11226, 14, 2, 9, 'e-eis para-os-cortadores para-cortadores-de as-madeiras dei trigo dei para-servos-teus coros vinte mil e-cevada coros vinte mil e-vinho batos vinte mil e-óleo batos vinte mil');
INSERT INTO verses VALUES (11227, 14, 2, 10, 'E-disse Hirão rei-de Tiro em-escrito e-enviou a yhwh em-amor-de yhwh a povo-seu deu-te sobre-eles rei');
INSERT INTO verses VALUES (11228, 14, 2, 11, 'E-disse Hirão bendito yhwh Elohim-de Israel que fez a os-céus e-a dar que deu filho o-rei filho sábio conhecedor discernimento e-entendimento que construirá casa para-יהוה e-casa para-reino-seu');
INSERT INTO verses VALUES (11229, 14, 2, 12, 'e-agora enviei homem sábio conhecedor entendimento Hurão pai-meu');
INSERT INTO verses VALUES (11230, 14, 2, 13, 'filho-de mulher de filhas-de Dã e-pai-seu homem tírio conhecedor para fazer em-o-ouro e-em-a-prata em-o-bronze em-o-ferro em-as-pedras e-em-as-madeiras em-a-púrpura em-o-azul e-em-o-linho e-em-o-carmesim e-para-abrir todo gravura e-para-inventar todo invenção que será-dado para-ele com sábios-teus e-sábios-de Adonai Davi pai-teu');
INSERT INTO verses VALUES (11231, 14, 2, 14, 'e-agora o-trigo e-a-cevada o-óleo e-o-vinho que disse Adonai enviará para-servos-seus');
INSERT INTO verses VALUES (11232, 14, 2, 15, 'e-nós cortaremos madeiras de de-o-Líbano conforme-toda a-ti e-traremos-as para-ti jangadas sobre mar eles e-tu subirás eles Jerusalém');
INSERT INTO verses VALUES (11233, 14, 2, 16, 'e-contou Salomão todo os-homens os-estrangeiros que em-terra-de Israel depois-de a-contagem que contou-os seu-pai pai-seu e-foram-achados cem e-cinquenta mil e-três-de dois-mil e-seis centenas');
INSERT INTO verses VALUES (11234, 14, 2, 17, 'E-fez dentre-eles setenta mil carregadores e-oitenta mil cortador na-montanha e-três-de milhares e-seis centenas supervisores para-fazer-trabalhar a o-povo');
INSERT INTO chapters VALUES (370, 14, 3, 17);
INSERT INTO verses VALUES (11235, 14, 3, 1, 'e-esperou Salomão para-construir a casa-de yhwh em-Jerusalém em-monte-de o-Moriá que apareceu para-Davi pai-dele que preparou em-lugar-de Davi em-eira-de Ornã o-jebuseu');
INSERT INTO verses VALUES (11236, 14, 3, 2, 'e-começou para-construir em-o-mês o-segundo em-o-segundo em-ano-de quatro para-reino-dele');
INSERT INTO verses VALUES (11237, 14, 3, 3, 'e-estes foi-fundado Shelomoh para-construir a casa o-Elohim o-comprimento côvados na-medida a-primeira côvados sessenta e-largura côvados vinte');
INSERT INTO verses VALUES (11238, 14, 3, 4, 'e-o-pórtico que sobre face-de o-comprimento sobre face-de largura-de a-casa côvados vinte e-a-altura cem ouro e-cobriu-o de-dentro ouro puro');
INSERT INTO verses VALUES (11239, 14, 3, 5, 'e-את a-casa a-grande cobriu madeira-de árvore e-cobriu-a ouro ouro bom sobre-ele palmeiras e-correntes');
INSERT INTO verses VALUES (11240, 14, 3, 6, 'e-cobriu a pedra pedra preciosa para-beleza e-o-ouro ouro-de Parvaim');
INSERT INTO verses VALUES (11241, 14, 3, 7, 'e-cobriu a a-casa as-vigas os-umbrais e-paredes-dela ouro ouro e-esculpiu querubins sobre as-paredes');
INSERT INTO verses VALUES (11242, 14, 3, 8, 'E-fez a casa-de santo-de os-santos comprimento-dele sobre face-de largura-de a-casa côvados vinte ouro bom vinte e-cobriu-o ouro bom para-talentos seis centenas');
INSERT INTO verses VALUES (11243, 14, 3, 9, 'e-peso-de para-pregos para-siclos cinquenta ouro e-os-aposentos-superiores cobriu ouro');
INSERT INTO verses VALUES (11244, 14, 3, 10, 'E-fez em-Betel santo-de os-santos querubins dois obra-de escultura eles ouro ouro');
INSERT INTO verses VALUES (11245, 14, 3, 11, 'e-asas-de os-querubins comprimento-delas côvados vinte asa o-primeiro para-côvados cinco tocando para-parede-de a-casa e-a-asa a-outra côvados cinco alcançando para-asa-de o-querubim o-outro');
INSERT INTO verses VALUES (11246, 14, 3, 12, 'e-asa-de o-querubim o-primeiro côvados cinco alcançando para-parede a-casa e-a-asa a-outra côvados cinco tocando para-asa-de o-querubim o-outro');
INSERT INTO verses VALUES (11247, 14, 3, 13, 'asas-de os-querubins os-estes estendidas côvados vinte e-eles em-pé sobre pés-deles e-faces-deles para-a-casa');
INSERT INTO verses VALUES (11248, 14, 3, 14, 'E-fez a o-véu azul e-púrpura e-carmesim e-linho-fino e-ofereceu sobre-ele querubins');
INSERT INTO verses VALUES (11249, 14, 3, 15, 'E-fez diante-de a-casa colunas dois côvados trinta e-cinco comprimento e-o-capitel que sobre cabeça-sua côvados cinco');
INSERT INTO verses VALUES (11250, 14, 3, 16, 'E-fez correntes no-oráculo E-colocou sobre cabeça as-colunas E-fez romãs E-colocou E-deu nas-correntes');
INSERT INTO verses VALUES (11251, 14, 3, 17, 'E-levantou a as-colunas sobre um o-templo um da-direita E-chamou da-esquerda E-chamou nome-de Jaquim e-nome-de o-esquerdo בֹּעַז');
INSERT INTO chapters VALUES (371, 14, 4, 22);
INSERT INTO verses VALUES (11252, 14, 4, 1, 'E-fez altar-de bronze vinte côvado comprimento-dele e-vinte côvado largura-dele e-dez côvados altura-dele');
INSERT INTO verses VALUES (11253, 14, 4, 2, 'E-fez a o-mar fundido dez na-côvado da-borda-dele a borda-dele agol ao-redor e-cinco na-côvado altura-dele e-linha trinta na-côvado ele a-ele ao-redor');
INSERT INTO verses VALUES (11254, 14, 4, 3, 'e-semelhança-de bois debaixo a-ele saviv ao-redor cercando a-ele ele na-côvado rodeando a o-mar ao-redor dois fileiras o-bovino fundidos em-fundição-dele');
INSERT INTO verses VALUES (11255, 14, 4, 4, 'em-pé sobre dois dez manhã três ponim para-o-norte e-três ponim para-o-mar ushloshah face para-o-sul e-três face para-o-nascente e-o-mar sobre-eles de-acima e-todo atrás-deles para-dentro');
INSERT INTO verses VALUES (11256, 14, 4, 5, 'e-espessura-dele palmo e-borda-dele como-obra-de borda-de copo flor-de lírio contendo batos três dois-mil conterá');
INSERT INTO verses VALUES (11257, 14, 4, 6, 'E-fez bacias dez E-colocou cinco de-a-direita e-cinco de-a-esquerda para-lavar em-elas a obra-de a-holocausto lavarão em-elas e-o-mar para-lavar para-os-sacerdotes em-ele');
INSERT INTO verses VALUES (11258, 14, 4, 7, 'E-fez a o-ouro o-ouro dez E-colocou E-deu no-templo cinco da-direita e-cinco de-a-esquerda');
INSERT INTO verses VALUES (11259, 14, 4, 8, 'E-fez mesas dez e-pôs no-templo cinco da-direita e-cinco de-a-esquerda E-fez bacias-de ouro cem');
INSERT INTO verses VALUES (11260, 14, 4, 9, 'E-fez átrio-de os-sacerdotes e-o-átrio o-grande e-portas para-o-átrio e-portas-delas revestiu bronze');
INSERT INTO verses VALUES (11261, 14, 4, 10, 'e-a dar deu de-lado-de a-direita ao-oriente de-em-frente-de ao-sul');
INSERT INTO verses VALUES (11262, 14, 4, 11, 'E-fez Hurão a os-caldeirões e-a as-pás E-terminou as-bacias e-completou para-fazer a a-obra que fez para-o-rei Salomão em-casa-de Elohim');
INSERT INTO verses VALUES (11263, 14, 4, 12, 'colunas dois e-os-globos e-os-capitéis sobre cabeça as-colunas duas e-as-redes dois para-cobrir a dois-de globos-de os-capitéis que sobre cabeça as-colunas');
INSERT INTO verses VALUES (11264, 14, 4, 13, 'e-a as-romãs quatro centenas para-duas-de as-redes dois fileiras-de romãs para-a-rede a-uma para-cobrir a dois-de globos-de os-capitéis que sobre face-de as-colunas');
INSERT INTO verses VALUES (11265, 14, 4, 14, 'e-a as-bases fez e-a as-bacias fez sobre as-bases');
INSERT INTO verses VALUES (11266, 14, 4, 15, 'a um um e-a o-gado doze dez em-lugar-dele');
INSERT INTO verses VALUES (11267, 14, 4, 16, 'e-a os-caldeirões e-a as-pás e-a os-garfos seu-pai todo utensílios-deles fez yhwh Abiú para-o-rei Salomão para-casa-de yhwh bronze polido');
INSERT INTO verses VALUES (11268, 14, 4, 17, 'em-planície-de o-Jordão fundiu-os o-rei em-espessura-de a-terra entre Sucote e-entre Zeredá');
INSERT INTO verses VALUES (11269, 14, 4, 18, 'E-fez Salomão todo os-utensílios estes muito que não não investigado peso-de o-bronze');
INSERT INTO verses VALUES (11270, 14, 4, 19, 'E-fez Shelomoh את todo os-vasos que casa Elohim e-את o-ouro o-ouro e-a pão e-sobre-elas pão-de as-faces');
INSERT INTO verses VALUES (11271, 14, 4, 20, 'e-a os-candelabros e-lâmpadas-de-eles para-queimar-as como-o-estatuto diante-de ouro ouro puro');
INSERT INTO verses VALUES (11272, 14, 4, 21, 'e-a-flor e-as-lâmpadas e-as-tenazes ouro ele perfeito-de ouro');
INSERT INTO verses VALUES (11273, 14, 4, 22, 'e-as-tesouras e-as-bacias e-as-colheres e-os-incensários ouro puro e-entrada-de a-casa portas-de-ele as-interiores para-santo-de os-santos e-portas-de a-casa para-o-templo ouro');
INSERT INTO chapters VALUES (372, 14, 5, 14);
INSERT INTO verses VALUES (11274, 14, 5, 1, 'e-foi-completada todo a-obra que fez yhwh para-casa-de e-trouxe E-veio שְׁלֹמֹה a santos-de seu-pai pai-de-ele e-a a-prata dar o-ouro e-a todo os-vasos deu em-tesouros-de casa Elohim');
INSERT INTO verses VALUES (11275, 14, 5, 2, 'então congregou שְׁלֹמֹה a anciãos-de Israel e-a todo cabeças-de as-tribos príncipes-de os-pais para-filhos-de Israel a Jerusalém para-fazer-subir a arca-de em-aliança-de yhwh de-cidade-de David ela צִיּֽוֹן');
INSERT INTO verses VALUES (11276, 14, 5, 3, 'e-congregaram-se a o-rei todo homem ele na-festa ele o-mês o-sétimo');
INSERT INTO verses VALUES (11277, 14, 5, 4, 'e-vieram todo anciãos-de Israel e-levantaram os-levitas a a-arca');
INSERT INTO verses VALUES (11278, 14, 5, 5, 'e-eles-subiram a a-arca e-a tenda encontro e-a todo instrumentos-de eles que na-tenda fizeram-subir a-eles os-sacerdotes os-levitas');
INSERT INTO verses VALUES (11279, 14, 5, 6, 'e-o-rei Salomão e-todo congregação-de Israel os-designados sobre-ele diante-de a-arca sacrificando ovelhas e-gado que não serão-contados e-não serão-numerados de-multidão');
INSERT INTO verses VALUES (11280, 14, 5, 7, 'e-trouxeram os-sacerdotes a arca-de em-aliança-de yhwh a lugar-de-ele a Debir a-casa a santo-de os-santos a sob asas-de os-querubins');
INSERT INTO verses VALUES (11281, 14, 5, 8, 'e-foram os-querubins estendendo asas sobre lugar-de a-arca e-cobriram os-querubins sobre a-arca e-sobre varas-de-ela de-acima');
INSERT INTO verses VALUES (11282, 14, 5, 9, 'e-estenderam as-varas e-foram-vistas cabeças-de as-varas de a-arca sobre face-de o-santo-dos-santos e-não serão-vistas até o-dia nome até o-dia a-esta');
INSERT INTO verses VALUES (11283, 14, 5, 10, 'não-havia na-arca somente segundo as-tábuas que deu Moisés em-חֹרֵב que yhwh yhwh com filhos-de Israel em-sair-de-eles de-Egito');
INSERT INTO verses VALUES (11284, 14, 5, 11, 'e-houve em-sair os-sacerdotes de que porque todo os-sacerdotes os-encontrados se-santificaram não para-guardar para-divisões');
INSERT INTO verses VALUES (11285, 14, 5, 12, 'e-os-levitas os-cantores para-todos-de-eles para-אָסָף para-הֵימָן para-יְדֻתוּן e-para-filhos-de-eles e-para-irmãos-de-eles vestidos linho-fino com-címbalos e-com-harpas e-liras em-pé oriente para-o-altar e-com-eles sacerdotes para-cem e-vinte com-trombetas');
INSERT INTO verses VALUES (11286, 14, 5, 13, 'e-houve como-um e-para-os-cantores para-fazer-ouvir voz-de um para-louvar e-para-dar-graças para-יהוה e-como-levantar voz voz e-com-címbalos e-com-instrumentos-de o-canto e-com-louvar para-יהוה porque que bom que bondade-de-ele e-a-casa enchei nuvem casa yhwh');
INSERT INTO verses VALUES (11287, 14, 5, 14, 'e-não yachlu hakohanim laamod de-diante-de de-diante-de a-nuvoem porque enchei glória-de- yhwh a casa Elohim');
INSERT INTO chapters VALUES (373, 14, 6, 42);
INSERT INTO verses VALUES (11288, 14, 6, 1, 'então disse Shelomoh yhwh disse para-a-sala na-trevas');
INSERT INTO verses VALUES (11289, 14, 6, 2, 'e-eu construi casa-de para-ti a-ti e-lugar para-a-tua-sentada pelos-dias');
INSERT INTO verses VALUES (11290, 14, 6, 3, 'e-voltou-se o-rei a E-abençoou E-abençoou a todo assembleia Israel e-todo assembleia Israel estando');
INSERT INTO verses VALUES (11291, 14, 6, 4, 'E-disse bendito yhwh Elohim-de Israel que palavra em-seu-boca a Davi pai-meu e-em-sua-mão enchei dizendo');
INSERT INTO verses VALUES (11292, 14, 6, 5, 'de o-dia que eu-tirei a povo-meu da-terra Egito de-toda escolhi em-cidade de-todo tribos-de Israel para-construir casa a-ser nome-meu nome e-não escolhi em-homem a-ser príncipe sobre povo-meu Israel');
INSERT INTO verses VALUES (11293, 14, 6, 6, 'e-eu-escolhi em-Jerusalém a-ser nome-meu nome e-eleger b-Davi para-ser sobre povo-meu Israel');
INSERT INTO verses VALUES (11294, 14, 6, 7, 'e-houve com para-coracao Davi pai-meu para-construir casa yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (11295, 14, 6, 8, 'E-disse yhwh a Davi pai-meu porque ser foi com para-o-teu-coracao para-construir casa que ser porque foi com ao-teu-coração');
INSERT INTO verses VALUES (11296, 14, 6, 9, 'somente tu não construire-a a-casa que filho-teu que-sai de-a-cintura-teu ele construirá a-casa para-o-meu-nome');
INSERT INTO verses VALUES (11297, 14, 6, 10, 'E-levantou yhwh a palavra-seu que palavra debaixo em-baixo Davi-d meu-pai e-eu-sentei-me sobre trono-de Israel ka''asher yhwh yhwh e-eu-construí a-casa yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (11298, 14, 6, 11, 'e-eu-postei nome a o-arca que yhwh aliança yhwh que karat com filhos-de Israel');
INSERT INTO verses VALUES (11299, 14, 6, 12, 'e-estacionou-se diante-de altar-de yhwh diante todo assembleia Israel e-ele-espalhou de-seus-mãos');
INSERT INTO verses VALUES (11300, 14, 6, 13, 'porque fez שְׁלֹמֹה refeito-ri nacoshes no-meio-de em-meio-de a-área cinco amós seu-comprimento e-cinco amós em-ele-o-largura-seu e-amós três de-le-o-altura-seu e-ficou-em-pé sobre-ele E-abençoou diante seus-pés frente-a todo assembleia Israel vayifros as-suas-mãos as-maxes:');
INSERT INTO verses VALUES (11301, 14, 6, 14, 'E-disse yhwh אֱלֹהִים-de Israel não-há um Elohim nos-samaxim e-nas-teres guardador-de a-aliança e-hachesed para-tus-servos aqueles-que-andam diante-de-ti em-todo em-seus-corações:');
INSERT INTO verses VALUES (11302, 14, 6, 15, 'que shamartha para-servo-teu Davi pai-meu a que a-ele a-ele vate-daber be-picha uveyadcha miletha como-o-dia a-esta');
INSERT INTO verses VALUES (11303, 14, 6, 16, 'e-agora yhwh Elohim-de Israel guarda para-o-servidor-teu  Davi  pai-meu את que falaste a-ele para-ele dizendo yikaret a-ti homem de-diante-de-mim habitante sobre trono-de Israel somente se eles-guardarem filhos-teus a caminho-deles para-andar em-a-lei-meu como-que andaste לְפָנַֽי׃');
INSERT INTO verses VALUES (11304, 14, 6, 17, 'e-agora yhwh Elohim-de Israel seja-confirmada palavra-tua que falaste para-o-servidor-teu le-david:');
INSERT INTO verses VALUES (11305, 14, 6, 18, 'que o-aumenta-se-realmente- habitou Elohim a o-homem eis a-terra eis que céus não os-céus certamente provisionará-te também porque a casa este que construí-eu');
INSERT INTO verses VALUES (11306, 14, 6, 19, 'e-virias-te a oração servo-teu yhwh sua misericórdia yhwh Elohim-meu para ouvir a grite e-a esta oração que servo-teu que ore diante-de-você.');
INSERT INTO verses VALUES (11307, 14, 6, 20, 'ser seus olhos abertos a a-casa este dia e-noite a o-lugar que tu-disseste para o-teu-nome nome a-ouvir a a-oração que orará teu-servo a o-lugar a-esta');
INSERT INTO verses VALUES (11308, 14, 6, 21, 'e-audirás a súplicas teu-servo e-o-povo-teu Israel que orarão a o-lugar esta e-tu audirás de-o-lugar da-estada-teu de os-céus e-ouvirás e-perdonarás');
INSERT INTO verses VALUES (11309, 14, 6, 22, 'se pecará homem para-o-amigo e-perdoar-á nele אָלָ֖ה para-cursar-no-lei-o-seu e-vem curse diante-de do-tua-altar na-casa a-esta');
INSERT INTO verses VALUES (11310, 14, 6, 23, 'e-você tishma de os-céus וְעָשִׂ֙יתָ֙ e-julgara-á a teus-servos para-retornar para-o-malfeitor a-dar caminho-dele na-sua-cabeça e-para-o-justificar צַדִּיק a-ele a-ele como-a-sua-justiça');
INSERT INTO verses VALUES (11311, 14, 6, 24, 'e se; for afligido; seu povo; Israel diante-de que porque pecar; a-ti e se arrependam; e louvem; a nome-teu e orarem; e-vocem-se-implorarão diante-de-ti no templo a-esta');
INSERT INTO verses VALUES (11312, 14, 6, 25, 'e-tu tishma de os-céus e-perdoarás para-o-peca-do teu-povo Israel e-voltar-e-os a a-eles que deu-te a-eles e-la-aboteiem:');
INSERT INTO verses VALUES (11313, 14, 6, 26, 'em-o-tempo-do-encontro os-céus e-não será que porque pecarão- a-ti e-orarão a o-lugar o-este e-agradecerão que nome-teu de-seus-pecados voltarão-eles porque castigá-los');
INSERT INTO verses VALUES (11314, 14, 6, 27, 'e tu, תִּשְׁמַ֣ע os-céus e te arrependas de pecado servos-teus e o teu povo, Israel porque que a o caminho hatovah que vão nela e dará por chuva sobre tua-terra que yhwh para o teu povo, herança:');
INSERT INTO verses VALUES (11315, 14, 6, 28, 'fome porque na-terra na-terra palavra porque ser-á multiplicarei e-será-rascunhado que será que será porque formou- para-ele seus-inimigos em-terra-de suas-portas todo praga e-todo doença');
INSERT INTO verses VALUES (11316, 14, 6, 29, 'todo oração todo será que yihye para-todo o-homem e-a-todos teu-povo Israel que saber-ão homem seu-contato e-o-seu-dor e-esticou as-suas-mãos a a casa a-esta');
INSERT INTO verses VALUES (11317, 14, 6, 30, 'e-você você-escutará de os-céus deposição sentar-se-teu e-perdoarás וְנָתַתָּ֤ para-o-homem conforme-toda seus-caminhos que que tu לבבו porque tu por-teu-próprio o-homem a para-coracao filhos-de o-homem');
INSERT INTO verses VALUES (11318, 14, 6, 31, 'para-que temerão-te para-andar em-caminhos-vossos todo os-dias vida eles a-terra sobre deste a-adama que dei-te para-os-avós-nossos');
INSERT INTO verses VALUES (11319, 14, 6, 32, 'e-também a o-extranjero não não de-o-povo-teu ele E e-ele-veio da-terra distante para-que seu-nome a-grande e-a-mão-tua a-forte e-o-braco-teu ha-netuya u-ba-u e-orai-vos a a casa a-esta');
INSERT INTO verses VALUES (11320, 14, 6, 33, 'e-tu você-ouvirá de os-céus de-a-base sua-ocupação e farás conforme-tudo que ele-chamará a-ti o-extranjero para-que a-terra todo nações-de a-terra a seu-nome e-para-tremor o-te כּוּעַםֶךָ֣ Israel e-para-conhecer porque teu-nome é-chamado sobre a casa este que eu-construí');
INSERT INTO verses VALUES (11321, 14, 6, 34, 'porque ele-sairá seu-povo para-a-guerra sobre inimigos-seus no-caminho que lançar-e-os o-caminho-de a-ti caminho a-cidade esta que escolheste-tu em-ela e-o-bayit que construi para-nome-teu');
INSERT INTO verses VALUES (11322, 14, 6, 35, 'e-ouviste-tu de os-céus a oração-deles e-a súplica-deles e-tu-farás juízo-deles');
INSERT INTO verses VALUES (11323, 14, 6, 36, 'que pecarão- que porque homem homem que não pecaram: e-furioso-te -os e-dar-vos-eles diante-de אֹיֵב e-voltar-os voltadores-deles a terra afastada ou próxima');
INSERT INTO verses VALUES (11324, 14, 6, 37, 'e-voltar-eles a seu-coração na-terra que foram-capturados- nome e-voltar-os e-suplicaram a-ti em-a-terra dizendo dizendo chatanu pecamos e-fomos-malvados');
INSERT INTO verses VALUES (11325, 14, 6, 38, 'e-retornem a-ti em-todo em-seu-lábem e-em-todo almas-elas em-terra-de eles que o-caminho-de a-eles e orai deste a sua terra que dei-lhes aos seus pais e a cidade que escolhi e-para-a-casa que construi para o teu nome');
INSERT INTO verses VALUES (11326, 14, 6, 39, 'e-ouviste-te de os-céus de-lugar assentamento-teu a oração-eles e-a techinno-teiem e-tu-farás mi-shpatam e-perdoarás  לעמך  que chatu- para-ti');
INSERT INTO verses VALUES (11327, 14, 6, 40, 'agora אֱלֹהַי sejam-eles por-favor os-teus-olhos abertas-elas e-ouvidos-teus inclinadas-elas para-oração o-lugar a-esta');
INSERT INTO verses VALUES (11328, 14, 6, 41, 'e-agora levanta-te yhwh Elohim para-descansar-te tu e-a-arca o-teu-poder os-teus-sacerdotes yhwh Elohim vistam-se a-tua-salvação e-os-teus-santos alegrar-se-ão no-bem');
INSERT INTO verses VALUES (11329, 14, 6, 42, 'yhwh Elohim a face-de face-de o-teu-messias lembre-se para-os-mercéis Davi servo-teu');
INSERT INTO chapters VALUES (374, 14, 7, 22);
INSERT INTO verses VALUES (11330, 14, 7, 1, 'e-quando-acabarem שְׁלֹמֹה para-orar-se e-a-chama desceu de-os-céus e-comeste a-holocausto e-os-sacrifícios e-da-glória yhwh enchei a a-casa');
INSERT INTO verses VALUES (11331, 14, 7, 2, 'e-não puderam os-sacerdotes para-vir a yhwh yhwh porque enchei yhwh yhwh a casa yhwh');
INSERT INTO verses VALUES (11332, 14, 7, 3, 'e-tudo filhos-de Israel vendo bredet o-fogo e-da-glória yhwh yhwh a-casa e-eles-se-curvaram nossos-nascer-do-sol em-a-terra sobre ha-rizfa e-ele-se-inclinaram e-gratidões que bom que porque para-sempre seu-mer-ci-do');
INSERT INTO verses VALUES (11333, 14, 7, 4, 'e o rei e-todo o-povo oferecendo-sacrifícios sacrifício-masculino-singular yhwh yhwh');
INSERT INTO verses VALUES (11334, 14, 7, 5, 'e-ele-ofereceu-o-sacrifício o-rei Salomão a sacrifício-de o gado vinte e-dois mil e-ovelhas cem e-vinte mil e-eles-beberam a casa o elohim o-rei e-todo o-povo');
INSERT INTO verses VALUES (11335, 14, 7, 6, 'e-os-sacerdotes sobre de-seus-turnos estando-de-pé e-os-levitas yhwh cântico yhwh que fez Davi o rei para-graças para-יהוה porque para-sempre bondade-dele em-louvor David em-mão-deles e-os-sacerdotes diante-deles e-todo Israel que se levantam');
INSERT INTO verses VALUES (11336, 14, 7, 7, 'e-consagrou Salomão a dentro-de o-courim que diante-de casa-de yhwh porque fez nome as-oferendas e-a de-a-cremes os-pacíficos porque altar-de não que fez Shelomoh não pode para-incluir a a queimada e-a a oferenda e-a os-de-leite');
INSERT INTO verses VALUES (11337, 14, 7, 8, 'E-fez Shelomoh a o-festival na-epoca essa shib-aat dias e-todo Israel com-ele muito grande muito de-levar Hamate até ribeiro-de Egito');
INSERT INTO verses VALUES (11338, 14, 7, 9, 'e-ele-fizeram no-dia o-sétimo assembléia- que dedicação-de o-altar fizeram sete-de dias e-o-festival sete dias');
INSERT INTO verses VALUES (11339, 14, 7, 10, 'e no dia vinte e-três para-o-mês o-sétimo enviou a o-povo para-os-tendas-deles alegres- e-dos-bons coração sobre da-boas-novas yhwh fez yhwh para-Davi e-para-salomao e-a-israel povo-dele');
INSERT INTO verses VALUES (11340, 14, 7, 11, 'E-terminou Salomão a yhwh yhwh e-a de-a-casa o-rei e-a todo que-vem sobre coração Salomão para-fazer na-casa- yhwh e-em-a-sua-casa sucedeu');
INSERT INTO verses VALUES (11341, 14, 7, 12, 'E-viu yhwh a Salomão E-disse a-ele para-ele ouvi a sua-oração e-escolher-ei em-lugar este a-mim segundo-casa-de eu-ofereci:');
INSERT INTO verses VALUES (11342, 14, 7, 13, 'eis e-etzor os-céus e-não será chuva e-eles eu-mandarei a-terra grilo para-comer a-terra e-se eu-enviarei palavra em-o-povo-meu');
INSERT INTO verses VALUES (11343, 14, 7, 14, 'e-eles-se-curvarão עמי que será chamado שְׁמִ֣י em-eles e-ele-ora-o e-eles-pedem-o face-de e-eles-voltam-se de-os-caminhos-deles os-maus e-eu escutarei de os-céus e-eu-perdoarei-o para-os-pecados-deles e-eu-curarei-o a terr-os');
INSERT INTO verses VALUES (11344, 14, 7, 15, 'agora e-olhos serão as-aberturas e-as-ouvidos que-se-estendem para-a-oração o-lugar a-esta');
INSERT INTO verses VALUES (11345, 14, 7, 16, 'e-agora eu escolhi e santifiquei a a-casa este ser- shimi e-sejam até eternidade ve-hayu eyni ve-libbi nome todo os dias');
INSERT INTO verses VALUES (11346, 14, 7, 17, 'e-tu se andarás lefanai andar andou Davi pai-teu ve-la''asot k-kol ordenei-te tzuitichakha ve-chukkay e-meus-decretos guardai:');
INSERT INTO verses VALUES (11347, 14, 7, 18, 'eu-elevarei a trono-de a-tua-majestade como-que eu-cortei para-davide teu-pai dizendo não a-ti para-ti homem dominador em-Israel');
INSERT INTO verses VALUES (11348, 14, 7, 19, 'e-se voltares-vós vós e-desisteis minhas-chuquqotay e-os-comandos-meus dei dei perante-vos e-vós-irrdes e-vós-servirdes Elohim outros a-eles para-eles');
INSERT INTO verses VALUES (11349, 14, 7, 20, 'e-nosseparareis de-cima-de a-terra-meu que dei a-eles e-a a-casa o-este que o-sanctifiquei-eu para o meu nome de-cima-de de-sobre face-de e-o-darei-eu-a-ela para-exemplo e-para-repetição em-todo o-povos');
INSERT INTO verses VALUES (11350, 14, 7, 21, 'e-a-casa o-este que ser altíssimo para-todo passando sobre-ele [וְאָמַ֗ר] e-dirá com-o-que yhwh yhwh assim para-a-terra a-esta e-a-casa a-esta');
INSERT INTO verses VALUES (11351, 14, 7, 22, 'e-diretriz sobre que ázuvu a יהוה Elohim-de avótehem que hotsiám da-terra Egito e-pegaram-se em-Elohim outros e-adoraram a-eles va-yaabdu״um sobre assim levou sobre-eles a todo o-mal a esta');
INSERT INTO chapters VALUES (375, 14, 8, 18);
INSERT INTO verses VALUES (11352, 14, 8, 1, 'e-houve de-ano vinte ano que construiu edificar a casa yhwh e-a casa-dele');
INSERT INTO verses VALUES (11353, 14, 8, 2, 'e-as-cidades que dar Huram para-Salomão edificar Salomão eles e-ele-estabeleceu nome a filhos-de Israel');
INSERT INTO verses VALUES (11354, 14, 8, 3, 'E-andou שְׁלֹמֹה o-Hamate Tsoba e-ele-fortificou sobre-ela');
INSERT INTO verses VALUES (11355, 14, 8, 4, 'E-edificou a o-Tadmor no-deserto e-את todo cidades-de edificar que ele-construiu em-o-Hamate');
INSERT INTO verses VALUES (11356, 14, 8, 5, 'E-edificou a casa Horon a-superior e-a casa choron o-inferior cidades-de matzor chomot דלותים ובריח׃');
INSERT INTO verses VALUES (11357, 14, 8, 6, 'e-com ba''alat e-a todo cidades-de hamiskenot que foram para-Salomão e-את tudo-de cidades-de o-carro e-a cidades-de hapharashim e-את todo cheshek Salomão que chasak para-construir terra uvavalbonon e em tudo terra sua soberania:');
INSERT INTO verses VALUES (11358, 14, 8, 7, 'todo o-povo hanothar de o-heteu wetha''emori e separarei e-o-hivite não que não de Israel eles');
INSERT INTO verses VALUES (11359, 14, 8, 8, 'de בְּנֵיהֶ֗ם que permanecem depois-deles na-terra que não completo-eles filhos-de Israel e-ele-subiu-os até o-dia até o-dia a-esta');
INSERT INTO verses VALUES (11360, 14, 8, 9, 'e-de filhos-de Israel que não deu Salomão aos-escravos para-o-trabalho-seu porque eles homens-de guerra e-príncipes-de os-oficiais-seus e-príncipes-de rikbo- e-os-cavaleiros-seus');
INSERT INTO verses VALUES (11361, 14, 8, 10, 've-Eleh príncipes-de que para-o-rei Salomão cinquenta e duzentos os-que-contam no-povo');
INSERT INTO verses VALUES (11362, 14, 8, 11, 'e-a filha-de פַּרְעֹה fez-subir שְׁלֹמֹה de-a-cidade Davi para o templo que disse para ela porque disse não você-estará mulher para-mim em-a-casa- Davi rei-de Israel yhwh santo-de eles que a-entrar- a-eles arca yhwh');
INSERT INTO verses VALUES (11363, 14, 8, 12, 'então e levou Salomão holocaustos a-yhwh sobre altar-de yhwh que edificar diante-de e o vale:');
INSERT INTO verses VALUES (11364, 14, 8, 13, 'e no discurso de dia em-dia-de para levá-lo como mandamento Moisés para-os-sábados e-para-as-luas-novas e para as festas três vezes no ano na festa das pães de páscoa e na festa dos sete semanas e no chag as sukkot:');
INSERT INTO verses VALUES (11365, 14, 8, 14, 'e pôs-se conforme-o-julgamento- davíd-de- seu-pai a separações os-sacerdotes sobre trabalho-deles e-os-levitas diante de-sentinela-deles para-louvar e-para-servir em-frente-a os-sacerdotes pela-palavra-de dia que e-os-porteiros em-seus-setores para-portão-de e-no-portão porque assim mandamento Davi homem Elohim');
INSERT INTO verses VALUES (11366, 14, 8, 15, 'e-não se-viraram mandamento o-rei sobre os-sacerdotes e-os-levedores para-todo palavra e-para-as-reservas');
INSERT INTO verses VALUES (11367, 14, 8, 16, 'e-ele-preparou todo trabalho Shelomoh até o-dia estabelecido casa-de yhwh yhwh seus-instrumentos completamente casa yhwh');
INSERT INTO verses VALUES (11368, 14, 8, 17, 'então andar שְׁלֹמֹה para-o-cedro homem e-a o-mar sobre beira-de o-mar em-terra-de Edom');
INSERT INTO verses VALUES (11369, 14, 8, 18, 'e enviou- a-ele Chóram por-mão-de seus servos e os servos que conhecem mar e-vieram com servos-de שְׁלֹמֹה de Ophir e-eles-tomaram de-lá quatro centenas ouro circularidade ouro e trouxeram a o-rei שְׁלֹמֹה');
INSERT INTO chapters VALUES (376, 14, 9, 31);
INSERT INTO verses VALUES (11370, 14, 9, 1, 'e a rainha de Saba Sama a ouviu Salomão e-veio para provar a Salomão em-vidas muito em-chail pesado má-od e-gemalim nossaim em-shamayim e-zahav para-multiplicar e-aven yekarah e-veio a Shelomoh ser com-ele a todo que foi com leváhah:');
INSERT INTO verses VALUES (11371, 14, 9, 2, 'e-contou para-ela Salomão a todo palavras-a-dele-ela-acento e-não não declarou mi-shlomo que não disse a-ela');
INSERT INTO verses VALUES (11372, 14, 9, 3, 'E-viu rainha-da Sheba-a-acento a sabedoria-de Shelomoh e-o-bayit edificar construiu-marcador');
INSERT INTO verses VALUES (11373, 14, 9, 4, 'e-alimento mesa-seu-acento e-assentamento seus-servos e-sua-ordem seus-ministros e-seu-vestimentas e-sua-bebidas e-seu-vestimentas e-sua-alçada que subia casa yhwh e-não foi ainda espírito espírito');
INSERT INTO verses VALUES (11374, 14, 9, 5, 'E-disse a o-rei verdade a-palavra que ouvi em-a-terra-meu sobre palavras-teus e-sobre sabedoria-tua');
INSERT INTO verses VALUES (11375, 14, 9, 6, 'e-não creu-ei até até que ven-ei e-viu-as não e-eis não הִגַּד־ a-mim metade grande sabedoria-teu aument-ei sobre o-ouvido que shama''ti');
INSERT INTO verses VALUES (11376, 14, 9, 7, 'אַשְׁרֵי homens-teus e-felizes servos-teus Estas os-estando em-te תמיד e-ouvindo a sabedoria-te');
INSERT INTO verses VALUES (11377, 14, 9, 8, 'haja yhwh Elohim-teu bendito que querendo בְּךָ֗ para-dar-te sobre trono-seu para-o-rei a-yhwh teu-Elohim em-amor eloheka a Israel para-estabelece-lo para-sempre e-dar-te sobre-eles para-o-rei para-fazer mishpat e justiça');
INSERT INTO verses VALUES (11378, 14, 9, 9, 'e-deu para-o-rei cem e-vinte circularidade ouro ouro לָרֹ֥ב muito muito preciosa e-não foi ser aquele que Natanah: rainha-de Saba para-o-rei שְׁלֹמֹה');
INSERT INTO verses VALUES (11379, 14, 9, 10, 'e-também servos-de e-servos-de Shelomoh que trouxeram ouro de-Ophir trouxeram de troncos de algumim e-pedra-de yekarah');
INSERT INTO verses VALUES (11380, 14, 9, 11, 'E-fez o-rei a madeiras-de ha-algumim mesilot para-casa-de yhwh uleveth o-rei e harpas unbalim lasharim e-não niru kahem antes em-terra-de Judá');
INSERT INTO verses VALUES (11381, 14, 9, 12, 'vehamelch שְׁלֹמֹה dar para-a-mãe-de Saba a todo desejo-seu que pergunta-ela fora-de-a que trouxe-ele a o-rei e-virou-se e-foi para-a-terra-seu ela e-servos-seu');
INSERT INTO verses VALUES (11382, 14, 9, 13, 'e-houve peso o-ouro que veio para-Salomão no ano um seis de-cem e-seis e-mármore ouro ouro');
INSERT INTO verses VALUES (11383, 14, 9, 14, 'somente de-homens os-tarim e-os-socarim trazendo e-todo reis-de tarde a-terra a-terra ouro ouro e-prata para-shlomo');
INSERT INTO verses VALUES (11384, 14, 9, 15, 'E-fez o-rei Salomão duzentos tinah ouro escorrido seis novecentos ouro escorrido subia sobre a-tinah HA''ECHAT:');
INSERT INTO verses VALUES (11385, 14, 9, 16, 'e-três- centenas ouro ouro escorrido três ouro subia ele-subirá sobre ha-magen a-uma e-os-distribuíram o-rei בבית יער o-lbanôn');
INSERT INTO verses VALUES (11386, 14, 9, 17, 'E-fez o-rei trono-de Sên grande ouro ouro puro');
INSERT INTO verses VALUES (11387, 14, 9, 18, 'e-seis elevações para-o-trono e-cordeiro em-ouro para-o-trono agarrando-se e-mãos mizze e deste sobre lugar da-rua e dois lebres em-pé ao-lado-de as-mãos');
INSERT INTO verses VALUES (11388, 14, 9, 19, 'e-doze dez lebres em-pé nome sobre seis as-escadas deste e-deste não naasah assim para-todo reinado');
INSERT INTO verses VALUES (11389, 14, 9, 20, 'e-tudo utensílios de-beber o-rei שְׁלֹמֹה ouro e-tudo utensílios casa-de יער ouro ouro puro não-há prata calculado nos-dias Salomão para-certeza');
INSERT INTO verses VALUES (11390, 14, 9, 21, 'porque navios para-o-rei indo terafim povo servos-de uma uma para-três dois virem navios tartaruga levando ouro e-prata shenhabbim ve-kopim ve-tuchiyim');
INSERT INTO verses VALUES (11391, 14, 9, 22, 'vayyigdal o-rei Shelomoh de-toda reis-de a-terra le-osher ve-chokhmah');
INSERT INTO verses VALUES (11392, 14, 9, 23, 'e-tudo reis-de a-terra mevaksheem a face-de Shelomoh para-ouvir a chokmatho que deu Elohim em-coração-seu');
INSERT INTO verses VALUES (11393, 14, 9, 24, 'e eles meviim homem minhatto instrumentos-de prata e-utensílios ouro e-acordos espada e-com-perfumes cavaleiros e-divisões palavra-de ano em-anos');
INSERT INTO verses VALUES (11394, 14, 9, 25, 'e-houve para-Salomão quatro-de אֲלָפִ֨ים ursos [סוּסִים֙] [וּמַרְכָּב֔וֹת] e-dois- dez mil cavaleiros e-ele-os-colocou em-cidades-de o-carro e-com- o-rei em-Jerusalém');
INSERT INTO verses VALUES (11395, 14, 9, 26, 'e-houve moshel em-todo hamalkim de o-river e-até terra filisteus e-até fronteira-de Egito');
INSERT INTO verses VALUES (11396, 14, 9, 27, 'E-colocou o-rei a o dinheiro birushalaim como-as-pedras e-a dar deu como-os-sicômoros que na-planície para-multidão');
INSERT INTO verses VALUES (11397, 14, 9, 28, 'u-motsi''im susim de-Egito para-Salomão e-de-todo as-terras׃');
INSERT INTO verses VALUES (11398, 14, 9, 29, 'e-restante-de palavras-de Shelomoh הָרִאשֹׁנִ֖ים [וְהָאֲחֲרוֹנִ֑ים] não-é eles escritos sobre palavras-de deu o-profeta e-sobre [וּבַחֲזוֹת֙] [*יעדי] [**יֶעְדּ֣וֹ] [הַחֹזֶ֔ה] [עַל־יָרָבְעָ֖ם] sobre Yarav''am filho-de נְבוֹט׃');
INSERT INTO verses VALUES (11399, 14, 9, 30, 'e-reinou Shlomoh Berushalaim sobre todo Israel quarenta anos');
INSERT INTO verses VALUES (11400, 14, 9, 31, 'e-deitou-se שְׁלֹמֹה com seus-pais e o sepultaram בעיר seu-pai pai-seu e-reinou Rechav''am filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (377, 14, 10, 19);
INSERT INTO verses VALUES (11401, 14, 10, 1, 'E-andou Rechav''am Siquém que Shekem entraram todo Israel ele a-ele');
INSERT INTO verses VALUES (11402, 14, 10, 2, 'e-houve Kishmoa'' Yarav''am filho-de נְבָת e-ele בְּמִצְרַיִם que de-diante-de de-diante-de Shelomoh o-rei e-voltou Jeroboão de-Egito');
INSERT INTO verses VALUES (11403, 14, 10, 3, 'e-enviaram e-ele-chamou- a-ele E-veio Jeroboão e-todo Israel dizendo a Rechav''am para-dizer');
INSERT INTO verses VALUES (11404, 14, 10, 4, 'Avicha hiqsha a e-agora Ve''atah leva-o de-a-trabalho teu-pai a-dura e-de-a-carga o-pesado que deu sobre nós e-te-adoraremos');
INSERT INTO verses VALUES (11405, 14, 10, 5, 'E-disse a-eles ainda três dias e-voltai a-mim E-andou o-povo');
INSERT INTO verses VALUES (11406, 14, 10, 6, 'e-ele-conselhou-se o-rei Raquebãm a os-velhos que foram estando-de-pé seu-pai Shelomoh vida dizendo viveu dizendo como vós seja-conselheiros para-responder para-o-povo- este palavra');
INSERT INTO verses VALUES (11407, 14, 10, 7, 'e-ele-falaram a-ele dizendo se será para-bom ao-povo o-este e-apaixone-se-eles e-falares a-eles דְּבָרִ֣ים e-sejam a-ti para-ti servos todo os dias');
INSERT INTO verses VALUES (11408, 14, 10, 8, 'e-olvidou a עֲצַ֥ת os velhos que conselheiros-os e ele conselhou-se a os-meninos que cresceram com-ele os-que-estavam-de-pé diante-de-ele');
INSERT INTO verses VALUES (11409, 14, 10, 9, 'E-disse a-eles quanto vós nó-at-tsím ve-ná-shív palavra a o-povo esta que dibb-rú dizendo dizendo ha-qel de ha-ol que deu á-vikhá sobre-nós');
INSERT INTO verses VALUES (11410, 14, 10, 10, 'e-falaram com-ele ha-yela-dím que gad-lú it-to dizendo assim to-amár para-o-povo que dizendo eleicha dizendo teu-pai pesou-duramente a nosso-grave-fardo e-tu leva-leve de-nos assim dizes a-eles pequeno-eu pesado-fui de-cintura pai-meu');
INSERT INTO verses VALUES (11411, 14, 10, 11, 'e-agora pai-meu fez-pesado sobre-vós sobre pesado e-eu a-sufir sobre o-vosso-peso pai-meu i-sar vos b-a-s-hotim e-eu b-o-akravim');
INSERT INTO verses VALUES (11412, 14, 10, 12, 'E-veio Jeroboão e-todo o-povo no-dia re-ha-vam em-o-dia o-te-shelishi como-que dizendo o rei dizendo no-dia para-mim no-dia o terceiro');
INSERT INTO verses VALUES (11413, 14, 10, 13, 'v-a-ya-anem o-rei dura v-a-yaa-zob o-rei re-ha-vam a עֲצַ֥ת os-idosos-verso');
INSERT INTO verses VALUES (11414, 14, 10, 14, 'e-falou a-eles conforme-a-conselho os-meninos dizendo elevarei-vos a vossa-carga e-eu acrescentarei sobre-ele pai-meu castigarei vos com-vossas-varas e-eu e-com-vossos-escorpiões-verso');
INSERT INTO verses VALUES (11415, 14, 10, 15, 'e-não ouviu o-rei a o-povo porque foi-ela cavide de-com yhwh a-fim-de que-elevou yhwh a palavra-sua que palavra em-mão-de seu-irmão o-silonita a Jeroboão filho-de olho׃');
INSERT INTO verses VALUES (11416, 14, 10, 16, 'e-todo que porque não a-eles הַמֶּלֶךְ֮ a-eles e-devolveram o-povo dizendo o-rei dizendo que a-nos parte de-David e-não herança em-pedra- jesaí homem para-a-tendas-teus Israel agora viu casa-teu Davi E-andou todo Israel לְאֹהָלָֽיו׃');
INSERT INTO verses VALUES (11417, 14, 10, 17, 'e-filhos-de Israel os-que-habitam em-cidades-de Judá e-reinou sobre-eles Rachabãm');
INSERT INTO verses VALUES (11418, 14, 10, 18, 'e-enviou o-rei Rachabãm a Hadoram que sobre do-tributo pedra nele filhos-de Israel eben E-morreu e-o-rei Rachabãm fortaleceu-se para-subir na-carroça para-nascer Jerusalém');
INSERT INTO verses VALUES (11419, 14, 10, 19, 'e-ele-se-apaixonou Israel na-casa-de Davi até o-dia a-esta');
INSERT INTO chapters VALUES (378, 14, 11, 23);
INSERT INTO verses VALUES (11420, 14, 11, 1, 'E-veio Rachabam Jerusalém e-ele-reuniu a casa Judá e-Benjamim cem e-oitenta mil בָּחוּר fez guerra para-lutar com Israel para-responder a o-reino para-Rachabam');
INSERT INTO verses VALUES (11421, 14, 11, 2, 'e-houve palavra-de yhwh a dizendo homem Elohim para-dizer');
INSERT INTO verses VALUES (11422, 14, 11, 3, 'disse a Rachabam filho-de Salomão e-para Judá e-a todo dizendo em-Juda e-Benjamim para-dizer');
INSERT INTO verses VALUES (11423, 14, 11, 4, 'assim disse yhwh não subi-e e-não luta-i com irmãos-de-vocês que homem para-a-sua-casa porque de-mim-me aconteceu a-coisa yhwh e ouviram a palavras-de yhwh e-eles-retornaram da-rainha a Iaroboam');
INSERT INTO verses VALUES (11424, 14, 11, 5, 'e-habitou Rehavam em-Jerusalém E-edificou cidades para-Maisor em-juda:');
INSERT INTO verses VALUES (11425, 14, 11, 6, 'E-edificou a casa-de pão e-a de-seu e-a Tequoa');
INSERT INTO verses VALUES (11426, 14, 11, 7, 'e-a casa-de tsur e-a socho e-a adulam');
INSERT INTO verses VALUES (11427, 14, 11, 8, 'e-a gat e-a Maresa e-a zif');
INSERT INTO verses VALUES (11428, 14, 11, 9, 'e-a adorayim e-a lachish e-a azeqah');
INSERT INTO verses VALUES (11429, 14, 11, 10, 'e-a tseraah e-a ayalon e-a Hebrom que biyhudah e-em-Binjamim cidades-de defesas-verso-final');
INSERT INTO verses VALUES (11430, 14, 11, 11, 'e-estreitou-se a E-colocou E-deu neles príncipes-de alimento alimento-de ve-shémen e-vinho-verso-final');
INSERT INTO verses VALUES (11431, 14, 11, 12, 'e-em-todo cidade e-cidade-e esconderijos-de e-lanças e-fortalecê-los muito muito e-foi a-ele Judá e-Benjamin:');
INSERT INTO verses VALUES (11432, 14, 11, 13, 'e-os-sacerdotes e os levitas que em-todo Israel estabelecei-vos sobre-ele de-todo de-sua-fronteira');
INSERT INTO verses VALUES (11433, 14, 11, 14, 'porque abandonaram os-levitas a dos-lugares-deles e-posse-deles e-caminharam para-Juda e-para-Jerusalém porque desprezou-os Jeorão e seus filhos de-Aaron para-יהוה');
INSERT INTO verses VALUES (11434, 14, 11, 15, 'e-ele-estabeleceu a-ele os-sacerdotes para-as-altas e-para-os-caprinos e-para-os-carros que fez');
INSERT INTO verses VALUES (11435, 14, 11, 16, 've''achareihem de-toda tribos-de Israel os que dão a no seu coração para buscar a yhwh Elohim-de Israel vieram Jerusalém para sacrificar a-yhwh Elohim-de seus pais');
INSERT INTO verses VALUES (11436, 14, 11, 17, 'e fortaleceram-se a reino Judá e aceitaram a Rechabe filho-de que anos três porque הָלְכוּ בְּדֶרֶךְ Davi וּשְׁלֹמֹה לְשָׁנִים שָׁלֽוֹשׁ׃');
INSERT INTO verses VALUES (11437, 14, 11, 18, 'e-tomou para-ele רְחַבְעָם֙ mulher a מָחֲלַת יְרִימ֖וֹת filho-de Davi אֲבִיהַ֕יִל filha-de Eliabe filho-de Jessé');
INSERT INTO verses VALUES (11438, 14, 11, 19, 'e-deu-à-luz a-ele בָּנִ֑ים a Yeush e-a Shemarya e-a Zaham');
INSERT INTO verses VALUES (11439, 14, 11, 20, 've-achareha tomou a Maacha filha-de a-ele e-deu-à-luz para-ele a Aviya e-a Atai e-a Ziza e-a Shelomit');
INSERT INTO verses VALUES (11440, 14, 11, 21, 'וַיֶּאֱהַ֨ב רחבעם a מעכה filha-de אבשלום que נשיו ופילגשיו porque mulheres שמונה- dez נשה ופילגשים ששים וילוד VINTE E OITO que e-seis FILHAS:');
INSERT INTO verses VALUES (11441, 14, 11, 22, 'põe-se-em-posição À-CABEÇA ROQUEBEÃO a Abias filho-de DOENÇA que EM-SEUS-IRMÃOS porque PARA-REILOGAR-O');
INSERT INTO verses VALUES (11442, 14, 11, 23, 'e-ele-construiu e-ele-rompeu de-todo -seus-filhos para-todo terras a-todo e-Benjamim para-todo E-colocou a-eles E-deu a-eles da-alimentação em-abundância e-ele-pediu multidão mulheres');
INSERT INTO chapters VALUES (379, 14, 12, 16);
INSERT INTO verses VALUES (11443, 14, 12, 1, 'e-houve כְּהָכִ֞ין-como-preparado מַלְכ֤וּת-reino רְחַבְעָם֙-Reoboam וּכְחֶזְקָת֔וֹ-e-sua-fortaleza deixar a yhwh yhwh e-todo Israel com-ele');
INSERT INTO verses VALUES (11444, 14, 12, 2, 'e-houve בַּשָׁנָ֤ה-no-ano a quinta para-o-rei Rechabeom subir Shishak rei-de Egito que Jerusalém porque subiram em-Yahweh:');
INSERT INTO verses VALUES (11445, 14, 12, 3, 'em-mil u''ma''ăṭayim carros [וּבְשִׁשִּׁ֥ים] mil cavaleiros e-não-há מִסְפָּ֗ר para-o-povo que vieram com-ele do-Egito lúvim sukkíyim e-cushitas');
INSERT INTO verses VALUES (11446, 14, 12, 4, 'va-yilcód a cidades-de ha-metzúrot que para-יְהוּדָה E-veio até Jerusalém');
INSERT INTO verses VALUES (11447, 14, 12, 5, 'u-shemáyah o profeta veio a re-ha-vam e-príncipes-de Judá que de-diante-de a E-disse a-eles shíshak yhwh para-eles assim disse yhwh vós azavtéhem oti e-também eu azavtí vós por-mão-de shíshak');
INSERT INTO verses VALUES (11448, 14, 12, 6, 'e-eles-se-curvaram senhores-de- Israel e-o-rei e-disseram justo yhwh');
INSERT INTO verses VALUES (11449, 14, 12, 7, 'e-em-ver yhwh que nos-curvamos ser palavra-de yhwh a dizendo para-dizer não não destruirei-vos a-eles para-eles como-pequeno para-fuga e-não voces-vireis minha-ira birushalaim por-mão-de Siquem');
INSERT INTO verses VALUES (11450, 14, 12, 8, 'que sejam- a-ele לַעֲבָדִ֑ים e-conheçam o-serviço-meu e-o-serviço mamlakhot das nações:');
INSERT INTO verses VALUES (11451, 14, 12, 9, 'e-subiu de-Shishak rei-de Egito E-tomou Jerusalém E-tomou a אֹצְרוֹת casa-de yhwh e-a E-tomou casa o-ouro a o-todo tomou E-tomou a guardas-de o-ouro que fez שְׁלֹמֹה');
INSERT INTO verses VALUES (11452, 14, 12, 10, 'E-fez o-rei Rechavãm debajo deles guardiões bronze e governou sobre mão príncipes-de os corredores os-guardas entrada-de casa o rei');
INSERT INTO verses VALUES (11453, 14, 12, 11, 'e-houve de-a vem o-rei yhwh yhwh vieram os-corredores e-eleves-os e-devolvê-los a câmara os-corredores:');
INSERT INTO verses VALUES (11454, 14, 12, 12, 'e em sua condenação retornou nós também yhwh e-não para destruí-los até à extinção e-também ser foi palavras bem:');
INSERT INTO verses VALUES (11455, 14, 12, 13, 'e-ele-se-fortaleceu o-rei רְחַבְעָ֛ם birushalaim e-ele-se-fez-rei que filho-de quarenta e-uma ano רְחַבְעָ֨ם em-seu-reinado e-sete doze ano rei Birushalaim ha-ir que yhwh yhwh lashum a de-toda nome de-todo tribos-de sua-mãe e-nome-de sua-mãe Naamah ha-ammonit');
INSERT INTO verses VALUES (11456, 14, 12, 14, 'E-fez o mal que não preparou coração-dele para buscar a yhwh');
INSERT INTO verses VALUES (11457, 14, 12, 15, 'vedibre Raquebãm hā-rišōnim vehahachronim não-é הֵ֨ם kethubim bedibre ouvinte-de-Yahweh o-profeta vedido o-que-vê para-se-rir e-guerras Rachabam e-Jaravam todo os dias');
INSERT INTO verses VALUES (11458, 14, 12, 16, 'e-deitou-se רחבעם com seus-pais e-ele-foi-sepultado na-cidade Davi e-reinou Abias filho-dele em-lugar-dele');
INSERT INTO chapters VALUES (380, 14, 13, 23);
INSERT INTO verses VALUES (11459, 14, 13, 1, 'na-ano oito dez para-o-rei Járobaom e-reinou Aviyah sobre Judá');
INSERT INTO verses VALUES (11460, 14, 13, 2, 'três dois rei em-Jerusalém e-nome-de sua-mãe Micaiahu filha-de Uriel de era entre foi e-entre Aviyah e-entre Iaroboam');
INSERT INTO verses VALUES (11461, 14, 13, 3, 'e-ele-estragou Aviyyah a a-guerra be-chayil valentes-de guerra אַרְבַּע־ centenas mil homem bachur ve-Yarav''am ara''akh com-ele guerra bishmonah centenas mil homem בָּחוּר heroi- força');
INSERT INTO verses VALUES (11462, 14, 13, 4, 'E-levantou Aviyyah de-cima-de para-o-monte Tsemarayim que em-monte-de Efraim E-disse שְׁמָע֖וּנִי يروبعام e-todo Israel');
INSERT INTO verses VALUES (11463, 14, 13, 5, 'não- a-vós para-conhecer que yhwh Elohim-de Israel deu dar para Davi sobre Israel para-sempre a-ele e-para-seus-filhos berit sal');
INSERT INTO verses VALUES (11464, 14, 13, 6, 'E-levantou Jeroboão filho-de נְבָ֔ט servo Shelomoh filho-de Davi e se rebelou sobre seu senhor');
INSERT INTO verses VALUES (11465, 14, 13, 7, 'e-reuniram-se sobre-ele homens vazios filhos-de sem Elohim e se fortaleceram sobre Rechabeom filho-de ser e Rechabeom foi jovem e fraco coração e-não hitzaxak diante-deles');
INSERT INTO verses VALUES (11466, 14, 13, 8, 'e-agora vós dizendo-os para-se-esforçar diante-de reino-de yhwh yhwh filhos-de David e-vós multidão muito e-com-vocês ovelhas-de ouro ouro fez a-vós a-vós para-elohim');
INSERT INTO verses VALUES (11467, 14, 13, 9, 'acaso-nao hidachatem a yhwh yhwh a filhos-de אַהֲרֹן a-vós vataasu a-vos kohanim ke''ammei ha''aratzot sua-mão o-que-vem para preencher mão-sua no fogo filho-de manhã e carneiros sete a-ti sacerdote para nada Elohim');
INSERT INTO verses VALUES (11468, 14, 13, 10, 'e-nós yhwh Elohim-nosso e-não abandonamos-ele-o e-sacerdotes servos a-yhwh filhos-de Arão e-os-levitas no-trabalho');
INSERT INTO verses VALUES (11469, 14, 13, 11, 'e-fumegantes la-yhwh עֹלוֹת na-manhã- ba-voker e-na-tarde- na-tarde pão especiarias e-disposição-de pão o-ouro a-mesa o-puro e-candeira-de a-dourada e-luzes-sua para-arder no-pôr-do-sol yhwh porque guardando nós ele guarda-de yhwh Elohim-nosso e-vós deixastes a-ele');
INSERT INTO verses VALUES (11470, 14, 13, 12, 'e-eis com-nós na-cabeça-de os-אֱלֹhim e-seus-sacerdotes e-trombetas da-clarinada para-somar sobre-vós filhos-de Israel a e-lutarem com yhwh Elohim-de- pais-vosso porque não tatslihu');
INSERT INTO verses VALUES (11471, 14, 13, 13, 'e-jeorovam virou-se a o-espião para-vir de-trás-deles e-foram diante-de Judá e-o-espião de-eles');
INSERT INTO verses VALUES (11472, 14, 13, 14, 'e-eles-viraram-se Judá e-eis a-eles a-guerra face e-depois e-ele-clamaram a-yhwh e-os-sacerdotes בַּחֲצֹצְרֽוֹת׃');
INSERT INTO verses VALUES (11473, 14, 13, 15, 'e-ariyu homem Judá e-houve em-harei''a homem Judá e-e-lohim nagaf a jarav''am e-todo Israel diante-de aviya e-Judá');
INSERT INTO verses VALUES (11474, 14, 13, 16, 'e-eles-fugiram filhos-de de-diante-de de-diante-de Judá e-deu-os Elohim com-a-mão-deles');
INSERT INTO verses VALUES (11475, 14, 13, 17, 'e-eles-feriram ne-hem Abias e seu povo punição multiplicai caíram santos de-Israel cinco centenas mil homem jovem');
INSERT INTO verses VALUES (11476, 14, 13, 18, 'e-ele-se-curvaram filhos-de Israel em-o-tempo aquela e-eles-pegaram filhos-de que porque nichshaanu sobre yhwh Elohim-de seus pais:');
INSERT INTO verses VALUES (11477, 14, 13, 19, 'vayyirdoof aviyah depois-de yaravam e-ele-capturou nós cidades a casa-de El e-a bnoteyha e-a yeshana e-a em-filhas-suas e-a e-filhas-de-a-ela');
INSERT INTO verses VALUES (11478, 14, 13, 20, 'e-não impediu força- Jároabeom ainda em-dias-de yhwh e o martirizou yhwh E-morreu');
INSERT INTO verses VALUES (11479, 14, 13, 21, 'e-se-fortaleceu Abiáhu e-eleve- a-ele mulheres quatro dez e-ele-gere vinte e-dois בָּנִים e-seis dez banoth');
INSERT INTO verses VALUES (11480, 14, 13, 22, 'e sobreviventes palavras-de Abias e seus caminhos e suas palavras escritos no midrash o profeta sua vida:');
INSERT INTO verses VALUES (11481, 14, 13, 23, 'e deitou-se com Abia com seus-pais ele ele na-cidade Davi e-reinou Asa filho-dele debajo dele durante seus dias a-terra a-terra dez dois');
INSERT INTO chapters VALUES (381, 14, 14, 14);
INSERT INTO verses VALUES (11482, 14, 14, 1, 'E-fez Asa o-bom e o que era reto em-olhos-de yhwh אֱלֹהִים-dele');
INSERT INTO verses VALUES (11483, 14, 14, 2, 'e tirou a os altares dos estrangeiros e as baamas e quebrou a as estâtuas e cortou a os asherim');
INSERT INTO verses VALUES (11484, 14, 14, 3, 'E-disse para Judá a investigar a yhwh Elohim-de pais-deles e para fazer a instrução e a mandatória:');
INSERT INTO verses VALUES (11485, 14, 14, 4, 'e-removeu de-todo cidades-de Judá a as baamas e-a ha-chammanim e-descansou o-reino diante-de-ele');
INSERT INTO verses VALUES (11486, 14, 14, 5, 'E-edificou cidades-de metsura em-Judá porque a-terra a-terra e-não-há com ele guerra nos anos yhwh a-ele deixou yhwh a-ele');
INSERT INTO verses VALUES (11487, 14, 14, 6, 'E-disse li-yehudah nibenah a ha-arim estes e-naséve choma u-migdalim portas u-brikihim o-denno a-terra le-faneinu que darashnu a yhwh nosso-Elohim darashnu va-yanaq para-nós em-o-redor va-yibnou e-eles-venceram');
INSERT INTO verses VALUES (11488, 14, 14, 7, 'e-houve para-Aasa força levando-o lança e-lança-longa de-Judeu três centenas-de mil e-de-Benjamim carregadores-de escudo e-dos-cavaleiros arco duzentos e-oitenta mil todo estes gibo-rei força');
INSERT INTO verses VALUES (11489, 14, 14, 8, 'e-saiu a-eles Zerach o-cushita em-força mil milhares e-carros três centenas E-veio até moresa');
INSERT INTO verses VALUES (11490, 14, 14, 9, 'e-ele-saiu asa diante-dele e-os-preparou guerra em-valle zefata para-moresa');
INSERT INTO verses VALUES (11491, 14, 14, 10, 'E-chamou Asa a yhwh Seus elohimes yhwh yhwh não-há entre para auxílio entre muito para-nao-haver yhwh noss-a-ajuda yhwh Elohim-nosso porque sobre-você nos-sustentávamos e-pela-tua-nome yhwh sobre tu esta yhwh Elohim-nosso tu a restringe contigo Enos');
INSERT INTO verses VALUES (11492, 14, 14, 11, 'destruiu yhwh a os-cushitas diante-de Asa velifnei Judá e-eles-fugiram os-cushitas:');
INSERT INTO verses VALUES (11493, 14, 14, 12, 'e-perseguiu Asa e-o-povo que com-ele até para-se-dragar e-caíram a-eles para-nao-haver para-eles da-vida porque foram-quebrados diante-de yhwh velifnei muito e-levantaram שָׁלָ֖ל muito muito');
INSERT INTO verses VALUES (11494, 14, 14, 13, 'e-golpearam a todo as-cidades em-torno-de Gerar porque foi medo- yhwh sobre-eles e-eles-abusaram-se era todo as-cidades porque abusaram multiplicai haytah בָהֶֽם׃');
INSERT INTO verses VALUES (11495, 14, 14, 14, 'e-também tendas-de do-rebanho deram-ferroadas e-eles-raptaram ovelhas para muitos e-camelos e-eles-retornaram Jerusalém');
INSERT INTO chapters VALUES (382, 14, 15, 19);
INSERT INTO verses VALUES (11496, 14, 15, 1, 'Azarias filho-de era haytah espírito espirito Elohim');
INSERT INTO verses VALUES (11497, 14, 15, 2, 'e-ele-saiu diante-de Asa E-disse a-ele ouvi-me Asa e-todo יְהוּדָה yhwh yhwh com-vós em-vossa-estar com-ele וְאִֽם־ a-vós será-achado-a a-vós e-se vós-o-deixareis ele-deixará a-vós');
INSERT INTO verses VALUES (11498, 14, 15, 3, 'e-dias muitos לְיִשְׂרָאֵ֑ל para-não Elohim-de verdade para-não sacerdote ensinador e-para-não lei');
INSERT INTO verses VALUES (11499, 14, 15, 4, 'e-ele-voltou בַּצַּר־ a-ele sobre yhwh Elohim-de Israel a-eles e achou para-eles');
INSERT INTO verses VALUES (11500, 14, 15, 5, 'e-no-tempo aqueles não-há paz para-o-saída e-para-a-chegada que de-tumultos grandes sobre todo habitantes-de das nações:');
INSERT INTO verses VALUES (11501, 14, 15, 6, 'e-cortaram-se  nation-  na-nação e-e-cidade em-a-cidade porque Elohim de-terror em-todo angústia');
INSERT INTO verses VALUES (11502, 14, 15, 7, 'e-vós fortaleçam-se e-a ir-povu que porque há salário le-feul-lat-kem');
INSERT INTO verses VALUES (11503, 14, 15, 8, 've-ki-shmoa asa as-palavras estes ve-han-nevua-a Odé ha-navi hit-cha-zak va-yaa-ver ha-shququtzim de-todo terra Judá e-Benjamim e-de as-cidades que la-khad de-montanha-de Efraim yhwh a altar-de yhwh yhwh diante-de oulam yhwh');
INSERT INTO verses VALUES (11504, 14, 15, 9, 'e-ele-reuniu a todo Judá e-Benjamim e-os-estrangeiros com-eles de-Efraim e-Menasseh e-de-Seman porque caíram sobre-o de-Israel para-o-muitos em-vê-los porque yhwh Elohim-seu com-ele-verso');
INSERT INTO verses VALUES (11505, 14, 15, 10, 'e-queixaram-se Jerusalém no-mês o terceiro no ano cinco- dez para a monarquia Asa:');
INSERT INTO verses VALUES (11506, 14, 15, 11, 'e-eles-deram-sacrifício para-יהוה no-dia aquele de o-salvamento eles-trouxeram manhã sete centenas e o gado sete mil:');
INSERT INTO verses VALUES (11507, 14, 15, 12, 'e-vieram na aliança para investigar a yhwh Elohim-de pais-deles em-todo a-ti e-em-todo alma-deles');
INSERT INTO verses VALUES (11508, 14, 15, 13, 'e-tudo que não ele-pesquisará para-יהוה Elohim-de- Israel morrerá de-o pequeno e-até grande para-homem e-até mulher');
INSERT INTO verses VALUES (11509, 14, 15, 14, 'e juraram para-יהוה pela voz grande e pelo trombeta e pelas cornetas e pelo trombeta');
INSERT INTO verses VALUES (11510, 14, 15, 15, 'e-se-rejeitaram todo Judá que a-juramento porque em-todo para-o-coracao-deles se-juraram a-eles de-seu-vontade yhwh a-eles para-eles e-estabeleceu yhwh a-eles misaviv');
INSERT INTO verses VALUES (11511, 14, 15, 16, 'vegam- mãe ʾēm ʾāsā o rei həsirāh miggbirā que ʿašṭā laʾăśerā de-miplatséth e-va-khorkót Asá a de-miplatséth e-vadék e-vishóraf em-nachal Kidron:');
INSERT INTO verses VALUES (11512, 14, 15, 17, 'e-as-altarinhos não saru de-Israel somente ser Asa foi completamente todo seus-dias:');
INSERT INTO verses VALUES (11513, 14, 15, 18, 'e-trouxe a seu-pai Abiú e-seus-santos casa o-Elohim prata וְזָהָ֖ב e-vessis');
INSERT INTO verses VALUES (11514, 14, 15, 19, 'e-guerra não foi-que até ano-de trinta e-cinco para-o-reino Asa');
INSERT INTO chapters VALUES (383, 14, 16, 14);
INSERT INTO verses VALUES (11515, 14, 16, 1, 'em-ano-de trinta e seis para-o-reino Asa subir de-Asa rei-de Israel E-edificou Judá para-não a Ramá para não dar saindo e-vindo para Asa rei Judá');
INSERT INTO verses VALUES (11516, 14, 16, 2, 'e-saiu Asa prata e-ouro de-a-tesouraria casa yhwh e-Beit o-rei e-enviou a filho-de הֲדַד rei Arã dizendo em-o-Damasco para-dizer');
INSERT INTO verses VALUES (11517, 14, 16, 3, 'ברית entre-mim וּבֵינֶ֔ךָ e-entre pai-meu e-entre pai-teu eis eu-enviei a-ti prata e-ouro vai destrua em-teu-convenção a -em Baasha- rei Israel  Ve''yal''e de-acima-de-mim');
INSERT INTO verses VALUES (11518, 14, 16, 4, 'E-ouviu Haddad a o-rei Asa e-yi-shelakh a príncipes-de os-exércitos que a-ele a cidades-de Israel va-yakku'' a inspeção e-a Dan e-a avel águas e-a todo das-pausas cidades nafthal-i');
INSERT INTO verses VALUES (11519, 14, 16, 5, 'e-houve כשמע em-nome e-ele-cessitou de-construir a a-alta e-ele-parou a trabalho-seu');
INSERT INTO verses VALUES (11520, 14, 16, 6, 'e-Asa o rei tomou a todo Judá e-ele-alçou a אבני edificar e-a E-edificou que ele-construiu בַּעְשָׁ֑א e-ele-construiu neles a גֶּ֖בַע e-a a manifestação׃');
INSERT INTO verses VALUES (11521, 14, 16, 7, 'e-na-hora a aquela veio Hanani הָרֹאֶה a Asa rei E-disse a-ele a-ele em-te-apoiando sobre rei aram e-não n-se-ant sobre yhwh teu-Elohim sobre sim n-m-lat força rei-de Arã de-mão-tua');
INSERT INTO verses VALUES (11522, 14, 16, 8, 'não o-kushim e-o-lubim foram l-chayil Larob l-rekev u-l-farasim l-harbeh muito muito sobre yhwh e-dos-deles-dar em-mão-teu');
INSERT INTO verses VALUES (11523, 14, 16, 9, 'que yhwh o-aynau m-shottot em-todo a-terra para-se-fortalecer com a-ele inteiro a-ele que sobre esta porque de-a-ora há contigo de-guerras');
INSERT INTO verses VALUES (11524, 14, 16, 10, 'e-ele-se-irritou Asa a aquele que vê e o colocou casa o-mudança porque com-ira com-ele sobre esta e-ele-esmigalhou Asa de o-povo em-o tempo a-ela');
INSERT INTO verses VALUES (11525, 14, 16, 11, 'e-eis palavras-de Asa os-primeiros e-os-últimos eis escritos sobre livro os-reis para-Juda e Israel');
INSERT INTO verses VALUES (11526, 14, 16, 12, 'e reinou Asa no ano trinta e nove de sua realeza berreglai até para-a-alta chalyō e-também b''chalyō que darash a yhwh porque barof''im');
INSERT INTO verses VALUES (11527, 14, 16, 13, 'e-ele-deitou Asa com pais-seus E-morreu em-o-ano quarenta e-uma lemalcho');
INSERT INTO verses VALUES (11528, 14, 16, 14, 'e-eles-o-enteraram-no-túmulo em-seus-túmulos que curvou-se-para a-ele na-cidade Davi e-eles-o-deitaram-no-leito no-leito que enchei com-perfumes e-adúlteros merukakhim be-mirkhat ato e-queimaram- a-ele queimação grande até limeod:');
INSERT INTO chapters VALUES (384, 14, 17, 19);
INSERT INTO verses VALUES (11529, 14, 17, 1, 'e-reinou Jeosafá filho-seu tachthayo e-fortaleceu-se sobre Israel');
INSERT INTO verses VALUES (11530, 14, 17, 2, 'e deu-lhe valente em-todo cidades-de E-colocou as pedras E-deu estâncias em-terra-de Judá e nas cidades Efraim que seu-pai Asa seu-pai');
INSERT INTO verses VALUES (11531, 14, 17, 3, 'e-houve yhwh com que andar andou em caminhos seu-pai seu-pai dos primeiros e-não buscou a Baalos:');
INSERT INTO verses VALUES (11532, 14, 17, 4, 'que a deusas seu-pai דָּרַשׁ וּבְמִצְוֹתָיו andou e-não כְּמַעֲשֵׂה Israel');
INSERT INTO verses VALUES (11533, 14, 17, 5, 'וַיְכֵן yhwh a הַמֶּלֶךְ- em-mão-de-ele WAYYITTONU todo יְהוּדָה oferta לִיהוֹשָׁפָט- e-foi para-ele עֹשֶׁר- e-honra para-multidão');
INSERT INTO verses VALUES (11534, 14, 17, 6, 'e-ele-se-alçou para-seu-coracao בְּדַרְכֵי- yhwh e mais הֵסִיר a הֶבָּמוֹת e-a as Ashérim de-Juda');
INSERT INTO verses VALUES (11535, 14, 17, 7, 'e-no-ano três para-seu-reinado enviou para-seus-sargentos para-filho-de חייל e-para-Ovadiá e-para-Zacarias e-para-Natanéel e-para-Micah para-instruir em-cidades-de Judá');
INSERT INTO verses VALUES (11536, 14, 17, 8, 'e-ʿimmāhēm os-levitas š-māʿyā''hū e-nṭanī''yā''hū e-zvadyā''hū wa-ʿśāhēl vi-yehōnātān e meu senhor e minha boa e-bom meu senhor os-levitas e com eles Elishama e Jehoram os sacerdotes:');
INSERT INTO verses VALUES (11537, 14, 17, 9, 'e-ele-ensinaram em juáda e-com-eles livro lei-de yhwh e-vir-se-enderam em-todo cidades-de Judá e-ele-ensinou no-povo');
INSERT INTO verses VALUES (11538, 14, 17, 10, 'e-houve medo yhwh yhwh sobre reinos-de as terras que em-volta Judá e-não nilchamu com Joash:');
INSERT INTO verses VALUES (11539, 14, 17, 11, 'e-de pelisthim trazendo a-Josafat oferta e-prata também também os-arábios a-ele a-ele ovelhas aies shib-aat milhares e sete centenas e-tiasim sete dois-mil e-sete centenas');
INSERT INTO verses VALUES (11540, 14, 17, 12, 'e-houve Joash andou e-crescendo até E-edificou e-construiu em-Juda em-cidades-altas e-cidades de-abrigos');
INSERT INTO verses VALUES (11541, 14, 17, 13, 'e-trabalho multiplicai ser a-ele em-cidades-de Judá e-os-homens em guerra gibo-rei valor em-Jerusalém');
INSERT INTO verses VALUES (11542, 14, 17, 14, 'e-aqueles de-a-sua-obrigação para-casa-de avoteihem para-Judá príncipes-de milhares Adna o-sargento e-com-ele gibbori valente três centenas mil');
INSERT INTO verses VALUES (11543, 14, 17, 15, 'e-sobre mão-sua Yehochanan hashar e-o duzentos e-setenta mil');
INSERT INTO verses VALUES (11544, 14, 17, 16, 'e-sobre mão-dele Amasias filho-de Zicri o-voluntário a-yhwh e-com-ele duzentos mil heroi- força');
INSERT INTO verses VALUES (11545, 14, 17, 17, 'e-de בִּנְיָמִן heroi- valor Eliaua e-com-o beijadores-de-a arco-de e-maguen duzentos mil');
INSERT INTO verses VALUES (11546, 14, 17, 18, 'e-sobre mão-sua Yehozabad e-com-o de-cem- e-oitenta exército iniciadores-de-a exército');
INSERT INTO verses VALUES (11547, 14, 17, 19, 'Estas dos-ajudantes a o-rei exceto-o que deu o-rei em-cidades-de do-fortaleza em-todo Judá');
INSERT INTO chapters VALUES (385, 14, 18, 34);
INSERT INTO verses VALUES (11548, 14, 18, 1, 'e-houve a-Josafat dez e-honra em-abundância e-se-casou para-Acaio');
INSERT INTO verses VALUES (11549, 14, 18, 2, 'e-ele-desceu para-o-fim dois a Acauab para-Samaria e-ele-impôs-o-sacrifício- a-ele Acabe ovelhas e-gado para-o-muitos e-ao-povo que com-ele e-ele-lureu-o para-subir a Ramaot gil-ad');
INSERT INTO verses VALUES (11550, 14, 18, 3, 'E-disse Acaab rei-de Israel a jehosafat rei Judá irás com-mim E-disse a-ele E-disse para-ele como-um-mineiro como-tu e-com-o-seu-povo povo-meu e-com-você na-guerra');
INSERT INTO verses VALUES (11551, 14, 18, 4, 'E-disse Josafá a rei Israel buscou agora yhwh a palavra yhwh');
INSERT INTO verses VALUES (11552, 14, 18, 5, 'e reuniu rei-de Israel a os-profetas quatro E-disse homem E-disse a-eles Hanelke a alturas גִּלְעָ֛ד folhas-de se אֶחְדָּ֑ל e-disseram sobe E-deu Elohim em-mão-de o rei');
INSERT INTO verses VALUES (11553, 14, 18, 6, 'E-disse Jeosafá não-há poh profeta a-yhwh ainda וְנִדְרְשָׁ֖ה de-aqui-dele');
INSERT INTO verses VALUES (11554, 14, 18, 7, 'E-disse rei-de יִשְׂרָאֵ֣ל ׀ a יְהוֹשָׁפָ֡ט ainda homem-de um para-dar-uma-pesquisa a yhwh de-aqui-dele e-eu o-sua-aversão-contra-ele porque que prophesying sobre-mim ele porque todo E-disse para-mal ele Miquéias filho-de ele-enchendo E-disse Jeosafá a diga o-rei assim');
INSERT INTO verses VALUES (11555, 14, 18, 8, 'E-chamou rei Israel a um E-disse E-disse apressa-te filho-de enche-se');
INSERT INTO verses VALUES (11556, 14, 18, 9, 'e-rei-de Israel וִֽיהוֹשָׁפָ֣ט rei-de יהודה os-que-sentam homem sobre seu trono מלובשים בגדים e-os-que-sentam בגורן entrada-de portão Samaria e-todo os-profetas MITנבאים diante-deles');
INSERT INTO verses VALUES (11557, 14, 18, 10, 'E-fez a-ele Tsidquiyahu filho-de כנעה  קרני E-disse E-disse yhwh disse yhwh  בעלה  תanga a Arã até כַּלּוֹתֵם׃');
INSERT INTO verses VALUES (11558, 14, 18, 11, 'e-todo os-profetas  נבאים dizendo folhas-de  עליה  רמות Gil''ad  והצלחה yhwh yhwh em-mão-de o rei');
INSERT INTO verses VALUES (11559, 14, 18, 12, 'e o mensageiro que and cam para chamar para-Miqueias palavra a-ele dizendo eis palavras os-profetas boca-de bom bom a o-rei como-um-de por-favor palavras-tuas como-um-de de-eles e falaste bom');
INSERT INTO verses VALUES (11560, 14, 18, 13, 'E-disse Micaías vive que porque a ele diga Elohim-meu ele אֲדַבֵּֽר׃');
INSERT INTO verses VALUES (11561, 14, 18, 14, 'E-veio a E-disse E-disse a-ele a-ele מִיכָה֙  Hanelke a alturas גִּלְעָ֛ד E-disse se אֶחְדָּ֑ל E-disse subam e-os-sucedam e-eles-darão em-mão-vossa');
INSERT INTO verses VALUES (11562, 14, 18, 15, 'E-disse a-ele o-rei até  kamme  feAmim eu que-te-encham que não  tedaber a-mim yhwh  Emet em-nome-de yhwh');
INSERT INTO verses VALUES (11563, 14, 18, 16, 'E-disse eu vi a todo Israel espalhados sobre os-montes -o rebanho E-disse yhwh a-elas o pastor E-disse yhwh não adonaies para os retornarão homem a seu lar em-paz');
INSERT INTO verses VALUES (11564, 14, 18, 17, 'E-disse rei-de Israel a יהושפט הלא eu-disse para-ti bom que sobre-mim bom porque se לרע');
INSERT INTO verses VALUES (11565, 14, 18, 18, 'E-disse portanto ouvi palavra-de yhwh eu vi a yhwh habitante-de sobre trono-dele e-todo exército os-céus estando sobre sua-direita e-sua-esquerda');
INSERT INTO verses VALUES (11566, 14, 18, 19, 'E-disse yhwh quem -a beleza a Acaab rei-de Israel e-suba וְיִפֹּ֖ל E-disse  Galaad E-disse este disse assim vezeh disse assim');
INSERT INTO verses VALUES (11567, 14, 18, 20, 'e-saiu hărōʿaḥ∶ e levantou-se diante-de yhwh E-disse eu afetá-los E-disse yhwh a-ele em qual');
INSERT INTO verses VALUES (11568, 14, 18, 21, 'E-disse eu sairia e eu seria na-brisa-de mentira com minha boca todo E-disse E-disse tupatê-los e-também tucal sai e-faze- assim');
INSERT INTO verses VALUES (11569, 14, 18, 22, 'e-agora eis dar yhwh espírito mentira por-me os-teus-profetas Estas e-יהוה palavra sobre-ti mal');
INSERT INTO verses VALUES (11570, 14, 18, 23, 'e se aproximou tsidqiyahu filho-de kenaanah e-feriu a E-disse sobre a-lhechi E-disse onde este o-caminho passou espírito-de yhwh de mim de-falar te:');
INSERT INTO verses VALUES (11571, 14, 18, 24, 'E-disse de Micaia veja-você viu no-dia o-aquele que entre quarto no quarto para esconderem-se');
INSERT INTO verses VALUES (11572, 14, 18, 25, 'E-disse rei Israel levem a de Micaia e o levem de volta a אָמ֣וֹן príncipe-de a-cidade e-a Yoash filho-de o rei');
INSERT INTO verses VALUES (11573, 14, 18, 26, 'וַאֲמַרְתֶּ֗ם assim disse o-rei שִׂ֥ימוּ este casa do leão e-o-alimentem-no pão ao aperto e águas ao-aperto até volta-te em paz');
INSERT INTO verses VALUES (11574, 14, 18, 27, 'E-disse Micheias se volta volverás em-paz yhwh palavra E-disse em-mim E-disse ouvi para-sempre todos:');
INSERT INTO verses VALUES (11575, 14, 18, 28, 'e-subiu rei-de Israel e-Yehoshafat rei-de Judá a alturas gil-ad');
INSERT INTO verses VALUES (11576, 14, 18, 29, 'E-disse rei Israel a Jeosafá se-preparou e-ele-vai para-a-marcha e-tu vestir-te com-tus-roupas e-se-preparou rei Israel e-vieram na-guerra');
INSERT INTO verses VALUES (11577, 14, 18, 30, 'e-rei-de arã deu-ordem a príncipes-de o-carro dizendo não dizendo não תַּלְיֽיחֲמוּ que o-pequeno a sozinho porque se a rei Israel para-ele-somente');
INSERT INTO verses VALUES (11578, 14, 18, 31, 'e-houve כְּרָא֥וֹת príncipes-de הָרֶכֶב a Jeosafá וְהֵ֤ם amru rei ele ele e-eles-cercaram sobre-ele לְתַלְיָחֵ֑ם e-ele-gritou jehosafat והוה Azaro e-incitou-os nós de-nós');
INSERT INTO verses VALUES (11579, 14, 18, 32, 'e-houve ut videns príncipes-de o-carro que não foi rei Israel e-eles-retornaram de-atrás-dele');
INSERT INTO verses VALUES (11580, 14, 18, 33, 'e-homem tendit per sagittam ad tuncum e-golpeou a rei entre entre e-entre e-entre E-disse E-disse in currum convertens et eduxit me de o-acampamento que exsultavi:');
INSERT INTO verses VALUES (11581, 14, 18, 34, 'e-ele-subiu a-guerra no-dia aquele e-rei-de Israel ser ergue-o na-m-carroça porque Arã até a-tarde E-morreu trazer vem o-sol');
INSERT INTO chapters VALUES (386, 14, 19, 11);
INSERT INTO verses VALUES (11582, 14, 19, 1, 'e-ele-se-estabeleceu Jeosafá rei-de Judá a sua-casa com-a-paz para- Jerusalém');
INSERT INTO verses VALUES (11583, 14, 19, 2, 'e-saiu a as-pnai Ieu filho-de E-disse o-vidente- E-disse a o-rei יְהוֹשָׁפָ֔ט yhwh לַעְזֹ֔ר וּלְשֹׂנְאֵ֥י yhwh תֶּאֱהָ֑ב וּבָזֹאת֙ yhwh קֶּ֔צֶף de-diante-de yhwh');
INSERT INTO verses VALUES (11584, 14, 19, 3, 'certamente דְּבָרִ֥ים bons foram achados contigo porque destruiste as bênçãos de a-terra e preparaste do-teu-cor para buscar Elohim:');
INSERT INTO verses VALUES (11585, 14, 19, 4, 'e-habitou Josafá em-Jerusalém e-voltou e-saiu no povo da fonte sete até monte-de Efraim e os fez voltar a yhwh Elohim-de seus pais:');
INSERT INTO verses VALUES (11586, 14, 19, 5, 'e pôs-se em pé: juízes: na terra: em-todo arei יְהוּדָה as cidades: para a cidade: e para a cidade:');
INSERT INTO verses VALUES (11587, 14, 19, 6, 'E-disse a os juízes: olhem: que que não porque não que julguem: porque a-yhwh e-com pela-palavra-de juízo');
INSERT INTO verses VALUES (11588, 14, 19, 7, 'e-agora haja medo- yhwh sobre-vós shimru e-faça porque não com yhwh nosso-Elohim avala e-mo face e-mo sód');
INSERT INTO verses VALUES (11589, 14, 19, 8, 'e-também jerusalém ele-estabeleceu יהושפט de os levitas e-os-sacerdotes וּמֵרָאשֵׁ֤י הָאָבוֹת֙ para-Israel yhwh yhwh וְלָרִ֑יב e-eles-retornaram Jerusalém');
INSERT INTO verses VALUES (11590, 14, 19, 9, 'E-ordenou sobre-eles dizendo assim תַעֲשׂוּן֙ בְּיִרְאַ֣ת yhwh בֶּאֱמוּנָ֖ה וּבְלֵבָ֥ב שָׁלֵֽם׃');
INSERT INTO verses VALUES (11591, 14, 19, 10, 'e-todo רִיב֩ que virá em-vocês de-vos os-dignantes em-suas-cidades entre sangue- para-sangue- entre lei para-m Mandamentos para-leis eles e-vos-advertistes a-eles e-não serão-impunes para-יהוה e-haverá- queixofer sobre-vós e-sobre vosso-ira fazeis e-não vós-vos-envergonhareis:');
INSERT INTO verses VALUES (11592, 14, 19, 11, 'e-eis amaráiohu sacerdote o-cabo em-vocês a-todo palavra-de yhwh e-zabadihu filho-de Ismael a-todo para-casa-de Judá para-todo palavra-de o-rei e-juízes e-seja yhwh fortalecei e-faça E-foi yhwh com o bom:');
INSERT INTO chapters VALUES (387, 14, 20, 37);
INSERT INTO verses VALUES (11593, 14, 20, 1, 'e-houve vieram filhos-de Moabe e filhos-de Amom e com eles dos amonitas sobre Josafá para a guerra:');
INSERT INTO verses VALUES (11594, 14, 20, 2, 'e-vieram e-eles-anunciaram a Josafá dizendo veio sobre ti o tesouro muito meever para o mar de Aram e eis-los em seu meio Tamar ela olho gádi:');
INSERT INTO verses VALUES (11595, 14, 20, 3, 'E-viu E-colocou Joash a sua-face l-i-d-r-o-sh a-yhwh e ele chamou fastear-se sobre todo Judá');
INSERT INTO verses VALUES (11596, 14, 20, 4, 'e-reuniram-se Judá para-pedir do Senhor também de-todo cidades-de Judá entraram para-buscar a yhwh');
INSERT INTO verses VALUES (11597, 14, 20, 5, 'e-ficou-em-pé Jeosafá no convívio יְהוּדָה Jerusalém em-casa-de yhwh diante-de o recinto a nova');
INSERT INTO verses VALUES (11598, 14, 20, 6, 'E-disse yhwh Elohim-de nos pais não-é-que você- ele Elohim em-os-céus e-tu domina em-todo reinos-de as-nações e na tua mão força e poder e-não-há contigo para se estabelecer');
INSERT INTO verses VALUES (11599, 14, 20, 7, 'não é que tu tu horash''t a yosh''vei a-terra a-esta de-diante-de teu-povo Israel vatitnah lezer''ah Abraão ohav''kha para-eternidade');
INSERT INTO verses VALUES (11600, 14, 20, 8, 'vayishbu- nela a-ti lekha- bah mikdash leshimcha dizendo');
INSERT INTO verses VALUES (11601, 14, 20, 9, 'se tavoa sobre-nós espada espada punição pestilência fome nossa-nos-sustentaremos diante-de a-casa o-este que porque o-teu-nome em-casa esta e-chamaremos a-você de-nossas-angústias e-ouvirá e-aliviador:');
INSERT INTO verses VALUES (11602, 14, 20, 10, 'e-agora eis filhos-de Amom e-Moabe e-har- Seir que não deu-lhes: para-o-Israel para-vir em-elas que da-terra Egito porque subiram de-eles e-não e-destroem-no:');
INSERT INTO verses VALUES (11603, 14, 20, 11, 'e-eis: eles pastores sobre-nós para-vir para-nos-expulsarem מִירֻשּׁׁתֶךָ que הֵרַשְׂתְּנָה׃');
INSERT INTO verses VALUES (11604, 14, 20, 12, 'Elohim-nosso porventura-não תִּשְׁפֹּט־ que porque não-há בָּנֻהָ כֹּחַ לִפְנֵי הֶהָמוֹן הָרַב este o-que-vinha sobre-nós não não נֵדַע que נִעֲשׂוּ porque sobre-ti nosso olhos:');
INSERT INTO verses VALUES (11605, 14, 20, 13, 'e-todo Judá em-pé yhwh yhwh também seu pêlos, suas mamas, e seus filhos:');
INSERT INTO verses VALUES (11606, 14, 20, 14, 'e Jacháel, filho-de Zacariah, filho-de Benaiá, filho-de Jeaíel, filho-de era o-levita espírito yhwh no-meio-de foi-ela sobre-ele espírito yhwh em-meio-de o povo');
INSERT INTO verses VALUES (11607, 14, 20, 15, 'E-disse ouvirem, todo Judá e-habitantes-de Jerusalém e o rei יהוהSPORTÁFAT yhwh a-vós yhwh para-vós אַתֶּם de-diante-de temam e-a תֵּחַתּוּ que não a-vós este que não para-vocês ha-milchamah porque para-elohim');
INSERT INTO verses VALUES (11608, 14, 20, 16, 'amanhã רְד֣וּ sobre-eles הִנָּ֥ם עֹלִ֖ים em-a-ascensão הַצִּ֑יץ וּמְצָאתֶ֤ם eles בְּס֣וֹף o-nachal face-de deserto-de יְרוּאֵֽל׃');
INSERT INTO verses VALUES (11609, 14, 20, 17, 'não a-vós para-lutar nesta estai-vos staís e vede a yhwh yhwh com-vos יְהוּדָה e Jerusalém a temede e-a ba-sua amanhã saí não yhwh com-vos');
INSERT INTO verses VALUES (11610, 14, 20, 18, 'e ardeu Joash Apaim terra e-todo יהודה e-habitantes-de Jerusalém נופלוּ yhwh yhwh להשתתחוֹת para-יהוה');
INSERT INTO verses VALUES (11611, 14, 20, 19, 'e levantaram-se הלוים de filhos-de as Caleútes e-de filhos-de הקרחים להלל para-יהוה Elohim-de Israel בקול grande para-cima');
INSERT INTO verses VALUES (11612, 14, 20, 20, 'e-eles-se-levantaram-cedo em-a-manhã e-saíram para-o-deserto tiquoa e-na-saída-deles ficou-em-pé Jeosafá E-disse escutem-no Judá e-habitantes-de Jerusalém creio-vos em-Yahweh vosso-elohim e-nós-creamos creio-vos em-suas-prophétias e tenham sucesso;');
INSERT INTO verses VALUES (11613, 14, 20, 21, 'e-ele-conselhou-se a o-povo ele pôs-se em pé conselheiros para-יהוה e louvadores para a honra de santidade na saída diante-de o mais velho וְאֹֽמְרִים֙ que para-יהוה porque para-sempre seu-mer-ci-do');
INSERT INTO verses VALUES (11614, 14, 20, 22, 'e na hora começaram a cantar em cânticos e aclamação dar yhwh que se multiplicam sobre filhos-de Amom moabeus e-har- seir os-que-vêm para juáda e foram enganados');
INSERT INTO verses VALUES (11615, 14, 20, 23, 'e se levantaram filhos-de amom e moabeus sobre habitantes-de monte-de Seir para exterminar e para destruí-los e para exterminá-los dos habitantes de Seir ajudaram-se homem em seu auxílio para destruí-los');
INSERT INTO verses VALUES (11616, 14, 20, 24, 'e Judá veio sobre que estava em no deserto e-voltaram-se a aquele exército וְהִנָּ֧ם פְּגָרִ֛ים נֹפְלִ֥ים terra-para e-não-há פְּלֵיטָֽה׃');
INSERT INTO verses VALUES (11617, 14, 20, 25, 'E-veio יְהוֹשָׁפָ֣ט וְעַמּוֹ֮ לָבֹ֣ז a שְׁלָלָם֒ וַיִּמְצְאוּ֩ בָהֶ֨ם para-a-muitidão e-riquezas e-filhos e-utensílios-de desejáveis a-eles a-eles para-a-falta-de carga e-foram dias três que-enganam que o-salvamento porque muito ela');
INSERT INTO verses VALUES (11618, 14, 20, 26, 'e-no-dia o quarto נִקְהֲלוּ֙ לְעֵ֣מֶק בְּרָכָ֔ה porque nome בֵּרֲכ֣וּ a yhwh sobre assim קָֽרְא֞וּ a nome o-lugar a-esse emeq ברכה até o-dia');
INSERT INTO verses VALUES (11619, 14, 20, 27, 'e-voltaram todo homem Judá וִֽירוּשָׁלִַ֙ם֙ וִֽיהוֹשָׁפָ֣ט בְּרֹאשָׁ֔ם לָשׁ֥וּב a Jerusalém yhwh porque שִׂמְּחָ֥ם yhwh de seus inimigos:');
INSERT INTO verses VALUES (11620, 14, 20, 28, 'e-vieram Jerusalém em-nabalims e-cinorots e com trombetas a yhwh yhwh');
INSERT INTO verses VALUES (11621, 14, 20, 29, 'e-houve medo Elohim sobre todo reinos-de as-terras que porque yhwh yhwh povo de-inimigos Israel');
INSERT INTO verses VALUES (11622, 14, 20, 30, 'e-tishqot reino Joash e-yanach a-ele Elohav misaviv');
INSERT INTO verses VALUES (11623, 14, 20, 31, 'e-reinou Josafá sobre Judá filho-de trinta e-cinco ano em-seu-reino e-vinte e-cinco ano rei sua-mãe e-nome-de mãe-dele deserto filha-de enviei:');
INSERT INTO verses VALUES (11624, 14, 20, 32, 'E-andou em-caminho seu-pai asa e-não desviou מִמֶּנָּה para-fazer o-reto yhwh yhwh');
INSERT INTO verses VALUES (11625, 14, 20, 33, 'entretanto as baamas não se-marcharam e-também o-povo não preparamos seu-coração לֵאלֹהֵ֖י אֲבֹתֵיהֶֽם׃');
INSERT INTO verses VALUES (11626, 14, 20, 34, 'וְיֶ֙תֶר֙ palavras-de יְהוֹשָׁפָ֔ט הָרִאשֹׁנִ֖ים וְהָאַחֲרֹנִ֑ים eis-os escritos בְּדִבְרֵי֙ Jeu filho-de חֲנָ֔נִי que elevação sobre livro reis-de Israel');
INSERT INTO verses VALUES (11627, 14, 20, 35, 'אֶתְחַבַּר֙ יְהוֹשָׁפָ֣ט rei-de Judá povo  Achazia  rei-de ele ele  instruiu  para-fazer');
INSERT INTO verses VALUES (11628, 14, 20, 36, 'e lhe uniu  com-ele para-fazer  navios  para-andar  Tarshis  e-fizeram  navios   em-Ezion   homem:');
INSERT INTO verses VALUES (11629, 14, 20, 37, 'e profetizou   Elizeu  filho-de amado-dele-será de-mares dizendo Josafá dizendo e-te-unirás yhwh -Achazyahu quebrou yhwh a suas obras e-eles-francaram-se navios e-não e-estancaram para-andar a tarshish:');
INSERT INTO chapters VALUES (388, 14, 21, 20);
INSERT INTO verses VALUES (11630, 14, 21, 1, 'e-deitou-se jehosafat com seus-pais e-foi-enterrado com pais-dele na-cidade Davi e-reinou יהורם filho-seu em-lugar-dele');
INSERT INTO verses VALUES (11631, 14, 21, 2, 'e-a-ele אחימ filhos-de Jeosafá עזARYה ויחיאל וזכריהו ואזARYhue ומיכאל ושPTYhue todo estes filhos-de Josafá rei-de Israel');
INSERT INTO verses VALUES (11632, 14, 21, 3, 'E-colocou a-eles אבימ מתנות רבבות לכסף ולזהב ומגדנות com cidades-de מצורות ביוחדה e-a dar deu ליהורם porque ele הbachor:');
INSERT INTO verses VALUES (11633, 14, 21, 4, 'E-levantou יהורם sobre seu-pai avivo WAYYITCHAZAQ e matou a todo seus-irmãos com a espada e-também príncipes Israel');
INSERT INTO verses VALUES (11634, 14, 21, 5, 'filho-de trinta e dois ano Jehoão em-seu-reinado e oitava dois rei em-Jerusalém');
INSERT INTO verses VALUES (11635, 14, 21, 6, 'E-andou no caminho reis-de Israel como fizeram casa Acabe porque que Acabe era para-ele mulher E-fez o-mal em-olhos-de yhwh');
INSERT INTO verses VALUES (11636, 14, 21, 7, 'e-não yhwh yhwh para destruir a casa Davi para-que a-aliança que karat disse como a-ele para-dar a-ele Nir e-para-seus-filhos todo os dias');
INSERT INTO verses VALUES (11637, 14, 21, 8, 'em seus dias rebelou-se Edom debaixo-de mão-de Judá e reinaram sobre-eles rei');
INSERT INTO verses VALUES (11638, 14, 21, 9, 'e passou Jeorão com seus sêrâvay e-todo e-houve com-ele E-foi levantou-se noite o-que-rodeia a-ele Edom aquele que gira para-ele e-a príncipes aquele que monta');
INSERT INTO verses VALUES (11639, 14, 21, 10, 'e se estendeu Edom debaixo-de mão-de até o-dia o-dia esta então se estenda para Libna em-o tempo debaixo-de sua-mão que deixar עָזַ֔ב a yhwh Elohim-de pais-dele');
INSERT INTO verses VALUES (11640, 14, 21, 11, 'também ele עָשָֽׂה־ בָמ֖וֹת בְּהָרֵ֣י Judá וַיֶּ֙זֶן֙ a habitantes-de Jerusalém וַיַּדַּ֖ח a Judá');
INSERT INTO verses VALUES (11641, 14, 21, 12, 'E-veio a-ele מִכְתָּ֔ב מֵֽאֵלִיָּ֥הוּ o-profeta dizendo assim disse disse yhwh Davi pai-teu תַּ֗חַת debaixo não הָלַ֙כְתָּ֙ בְּדַרְכֵי֙ יְהוֹשָׁפָ֣ט pai-teu וּבְדַרְכֵ֖י Asa rei-de Judá');
INSERT INTO verses VALUES (11642, 14, 21, 13, 'e-ela-partiu בְּדֶ֙רֶךְ֙ reis-de Israel וַתַּזְנֶ֤ה a Judá e-a habitantes-de Jerusalém כְּהַזְנ֖וֹת casa Acabe e-tambem a אַחֶ֧יךָ casa-de אָבִ֛יךָ הַטּוֹבִ֥ים de-vós הָרָֽגְתָּ׃');
INSERT INTO verses VALUES (11643, 14, 21, 14, 'eis yhwh נוגף pandemia grande בהעםך ובבניך ובנותיך e-em-todo רכושך׃');
INSERT INTO verses VALUES (11644, 14, 21, 15, 'e-tu בחוליים muitos במחלה מעיך até yetseu מעיך de החולי dias sobre dias');
INSERT INTO verses VALUES (11645, 14, 21, 16, 'e arrouvou yhwh sobre Jehoram espírito espírito os filisteus e os arvães que sobre mão cushitas:');
INSERT INTO verses VALUES (11646, 14, 21, 17, 'e-eles-subiram em Juda e dividiram-na e tomaram-na a todo o riqueza que estava para-casa-de o-rei e-também seus-filhos filho que ficaram- a-ele filho porque se yoãoaz pequeno seus filhos:');
INSERT INTO verses VALUES (11647, 14, 21, 18, 'e-apos-- todo esta yhwh Yahweh em-suas-mamas para-chorar-- para-nada-- cura--');
INSERT INTO verses VALUES (11648, 14, 21, 19, 'e-houve por-dias-- dos-mares e-no-tempo saída o-queixo para os dias dois sairam dos-seus com seu-munço E-morreu em-estômagos males e-não a-ele a-ele povo-dele queimação como-queimação pais-dele');
INSERT INTO verses VALUES (11649, 14, 21, 20, 'filho-de trinta ser foi em-seu-reinado e oitava dois rei em-Jerusalém E-andou bəlō'' ḥemdá'' e-sepultaram-o na-cidade Davi e-não bəqivrót hā-melakím׃');
INSERT INTO chapters VALUES (389, 14, 22, 12);
INSERT INTO verses VALUES (11650, 14, 22, 1, 'wa-yəmlichū yošbé'' Jerusalém a ʾăḥazyā''hû o-pequeno o-pequeno que porque todo hā-rišōnim hārag הַגְּד֔וּד הַבּ֥א בָֽעַרְבִ֖ים para-o-lager e-reinou Acazias filho-de יְהוֹרָ֖ם rei Judá');
INSERT INTO verses VALUES (11651, 14, 22, 2, 'filho-de quarenta וּשְׁתַּ֤יִם ano אֲחַזְיָ֣הוּ em-seu-reinado uma uma rei בִּֽירוּשָׁלָ֑͏ִם sua-mãe mãe-dele עֲתַלְיָ֖הוּ filha-de עָמְרִֽי׃');
INSERT INTO verses VALUES (11652, 14, 22, 3, 'também andar andou בְּדַרְכֵ֖י casa que sua-mãe era haytah o-aconselhou-o para-ensinar:');
INSERT INTO verses VALUES (11653, 14, 22, 4, 'E-fez o-mal em-olhos-de yhwh como-casa-de Acabe porque eles foram- a-ele morrendo seu-pai morrer a-ele para-destruir a-ele');
INSERT INTO verses VALUES (11654, 14, 22, 5, 'também segundo-sua-conselhos— andar E-andou a Jorão filho-de Acabe rei Israel para-a-guerra sobre Chazeel rei-de Arã nas-Beramas  Galaad e-eles-feriram as-horamim a jorama:');
INSERT INTO verses VALUES (11655, 14, 22, 6, 'e-voltou para-se-recuperar em-yizreel que aqueles-que-matam que matá-lo em-horamah nao-é-possível-mantener-estrutura-gramatical-original a veja-ael rei Arã e-azariahu filho-de יהורם rei para-ver ירד ראהוּ a יהורם ele אחזאב בייזרא엘 porque -doente ela');
INSERT INTO verses VALUES (11656, 14, 22, 7, 'ומאלהוה era תבוסת אחזיהוּ para-vir a יורם sair saiu com Jeorão a Ieu yhwh נִמְשִׁ֔י que מְשָׁח֣וֹ yhwh לְהַכְרִ֖ית a casa Acabe');
INSERT INTO verses VALUES (11657, 14, 22, 8, 'e-houve כְּהִשָּׁפֵ֥ט יֵה֖וּא com casa Acabe וַיִּמְצָא֩ a príncipes-de Judá e filhos-de אֲחֵ֧י אֲחַזְיָ֛הוּ מְשָׁרְתִ֥ים לַאֲחַזְיָ֖הוּ e mataram:');
INSERT INTO verses VALUES (11658, 14, 22, 9, 'e buscou a Acazias e prendeu-o ele se escondia em Samaria e trouxeram-no a João que e o sepultaram porque ele filho-de יהושפט ele que דרש a yhwh em-todo לבבו ואין para-casa-de אחזיהו לעצר כח למלוכה׃');
INSERT INTO verses VALUES (11659, 14, 22, 10, 'ואתליהוּ mãe אחזיהוּ viu-a que morreu -nha e se levantou e falou a todo semente o-reino segundo-casa-de Judá');
INSERT INTO verses VALUES (11660, 14, 22, 11, 'e-tomou -Joshabáat filha-de o-rei a Joas ele -Achazyahu e roubou ele e-deu ele o rei as mortas e-deu a-ele e-a de seu ninho na-câmara as matas e ocultou-o Yehoshabat que o-rei era esposa de Joada de-diante-de porque ela foi a-ele Achaziahu de-faces-de Athaliah e-não matou-os');
INSERT INTO verses VALUES (11661, 14, 22, 12, 'e-houve itam na-casa-de הָֽאֱלֹהִ֔ים estava-se escondendo seis dois וַעֲתַלְיָ֖ה מֹלֶ֥כֶת sobre a-terra');
INSERT INTO chapters VALUES (390, 14, 23, 21);
INSERT INTO verses VALUES (11662, 14, 23, 1, 'וּבַשָּׁנָ֨ה הַשְּׁבִעִ֜ית הִתְחַזַּ֣ק Yehoyada E-tomou a príncipes-de הַמֵּא֡וֹת לַעֲזַרְיָ֣הוּ filho-de יְרֹחָ֡ם וּלְיִשְׁמֵעֵ֣אל filho-de יְ֠הוֹחָנָן e-azaryahu filho-de ouvéd e-a ma''aseyahu filho-de adayahu e-a elishafat filho-de memória-minha im-o na aliança:');
INSERT INTO verses VALUES (11663, 14, 23, 2, 'e-vir-se-enderam em juáda e-ajuntaram-se a os-levitas de-todo cidades-de Judá וְרָאשֵׁ֥י הָאָב֖וֹת לְיִשְׂרָאֵ֑ל e-vieram a Jerusalém');
INSERT INTO verses VALUES (11664, 14, 23, 3, 'וַיִּכְרֹ֨ת todo הַקָּהָ֥ל em-o-brith em-casa-de Elohim E-disse a-eles eis para-ela-os eis filho-de o rei yhwh como palavra yhwh sobre filhos-de דָוִֽיד׃');
INSERT INTO verses VALUES (11665, 14, 23, 4, 'este a palavra que fazeis-vós o-trigésimo מִכֶּ֜ם בָּאֵ֣י הַשַׁבָּ֗ת aos-cohãnicos e-los-lévitas aos-senhores das-pedras');
INSERT INTO verses VALUES (11666, 14, 23, 5, 'e-a-trigesima em-casa-de o-rei e-a-trigesima no-porta do-fundamento e-todo o-povo nas-cortes yhwh yhwh');
INSERT INTO verses VALUES (11667, 14, 23, 6, 'e-a virá que yhwh porque se os-sacerdotes e-os-que-guardam aos levitas eles yavu porque santo-de yhwh e-todo o-povo יִשְׁמְר֖וּ guarda-de yhwh');
INSERT INTO verses VALUES (11668, 14, 23, 7, 'vehikkipu haliviyim a o-rei ao-redor homem vekelayo em-mão-de-ele vehabba a a-casa morrerá vihiyu a o-rei em vir-de ele u''beetzato:');
INSERT INTO verses VALUES (11669, 14, 23, 8, 'e-fizeram dos-Levitas e-todo Judá kakol que tziva Yehoyada o-sacerdote e-eles-levaram homem a seus-homens veio-ele a-sabá que não a-sabá porque não libertou yehoyada o-sacerdote a as-separações');
INSERT INTO verses VALUES (11670, 14, 23, 9, 'E-colocou Joada o sacerdote para-gerentes as-centenas a as chãos e-a as armaduras e-a os oficiais que para-o-rei Davi que casa Elohim');
INSERT INTO verses VALUES (11671, 14, 23, 10, 'e pôs-se em pé: a todo o-povo e cada um seu cajado em sua mão do lado a-casa da direita até lado a-casa a esquerda para o altar e para a casa sobre o-rei ao-redor');
INSERT INTO verses VALUES (11672, 14, 23, 11, 'e saíram a filho-de o rei e-eles-deram sobre-ele a ele e-a a testemunha e reinaram a-ela e ungiram-no Yehoyada e seus filhos e-disseram viva o rei');
INSERT INTO verses VALUES (11673, 14, 23, 12, 'e-ela-ouviu עֲתַלְיָ֗הוּ a voz o-povo הָֽרָצִ֔ים וְהַֽמְהַֽלְלִ֖ים a o-rei וַתָּב֥וֹא yhwh o-povo casa yhwh');
INSERT INTO verses VALUES (11674, 14, 23, 13, 'E-viu e-eis הַמֶּלֶךְ֩ עוֹמֵ֨ד sobre עַמּוּד֜וֹ בַּמָּב֗וֹא וְהַשָּׂרִ֣ים וְהַחֲצֹצְרוֹת֮ sobre a-terra e-todo povo a-terra alegre-se e toque בּ-הֲצֹ֣צְר֔וֹת וְהַ-מְשׁ-ֽוֹרֲרִים֙ em-vasos-de הַ-שׁ-֔יר וּמֹדִיעִ֖ים לְהַ-לֵּ֑ל E-disse [קֶ֥שֶׁר] a');
INSERT INTO verses VALUES (11675, 14, 23, 14, 'vayotze'' Yehoyada o-sacerdote a príncipes-de ha-ma''ot pikuday hachayil E-disse para-eles hotzi''uhah a de-casa-de hashaderot ve-habba atrás-de-ela yumath que disse disse não não תְמִית֖וּהָ yhwh yhwh');
INSERT INTO verses VALUES (11676, 14, 23, 15, 'e-puseram a-ela mãos e-ela-chegou a מְב֥וֹא shaar- הַסּוּסִ֖ים casa o-rei וַיְמִית֖וּהָ nome');
INSERT INTO verses VALUES (11677, 14, 23, 16, 'וַיִּכְרֹ֤ת יְהוֹיָדָע֙ aliança בֵּינ֕וֹ e-entre todo e-entre e-entre o-rei a-ser para-o-povo para-יהוה');
INSERT INTO verses VALUES (11678, 14, 23, 17, 'וַיָּבֹ֨אוּ todo o-povo casa-de o-mestre וַֽיִּתְּצֻ֔הוּ e-a מִזְבְּחֹתָ֥יו e-a suas-imagens que-bateram e-a ofertas sacerdote o-Baal eles-mataram diante-de os-mizbótes');
INSERT INTO verses VALUES (11679, 14, 23, 18, 'e-ele-colocou Yehoyada פּ-קֻדֹּ֜ת casa yhwh na-mão-de os-sacerdotes os-levitas que partiu Davíd sobre yhwh yhwh para-fazer-subir yhwh yhwh כַּכָּת֛וּב בְּתוֹרַ֥ת Moisés בְּשִׂמְחָ֣ה sobre sobre mãos-de דָוִֽיד׃');
INSERT INTO verses VALUES (11680, 14, 23, 19, '[וַֽיַּעֲמֵד֙] [הַשּׁ֣וֹעֲרִ֔ים] sobre [בֵּ֣ית] yhwh yhwh e-não virá para-todo palavra');
INSERT INTO verses VALUES (11681, 14, 23, 20, 'E-tomou a príncipes-de הַמֵּא֡וֹת e-a הָֽאַדִּירִים֩ e-a הַמּֽוֹשְׁלִ֨ים no-people a-terra todo povo a-terra yhwh a o rei de-casa-de yhwh and-they-entered in-the-middle-of portão-de sobre casa o-rei and-they-seated a o-rei sobre trono-de the-kingdom');
INSERT INTO verses VALUES (11682, 14, 23, 21, 'and-they-rejoiced todo com a-terra and-the-city shakatá e-a atalyahu and-they-killed com-a-espada');
INSERT INTO chapters VALUES (391, 14, 24, 27);
INSERT INTO verses VALUES (11683, 14, 24, 1, 'filho-de sete dois Yoash no seu reinado e quarenta ano rei em Jerusalém sua-mãe mãe-dele Zivá de Beir sete');
INSERT INTO verses VALUES (11684, 14, 24, 2, 'E-fez Yoash o-reto em-olhos-de yhwh todo dias de Joade o-sacerdote');
INSERT INTO verses VALUES (11685, 14, 24, 3, 'e-ele-levantou- a-ele Jeoiada as-nascidas duas e-gerou filhos e-filhas');
INSERT INTO verses VALUES (11686, 14, 24, 4, 'e-houve depois de vós ser com coração Joás para o novo yhwh casa yhwh');
INSERT INTO verses VALUES (11687, 14, 24, 5, 'e juntou-se a os-sacerdotes E-disse a-eles a eles saíam para as cidades de Judá e se juntaram de-todo Israel prata para fortalecer a casa vosso-Elohim desde ano em-anos e-vós aprontassem-se para a palavra e-não מִֽהֲר֖וּ הַֽלְוִיִּֽם׃');
INSERT INTO verses VALUES (11688, 14, 24, 6, 'E-chamou [הַמֶּלֶךְ֮] [לִֽיהוֹיָדָ֣ע] [הָרֹאשׁ֒] E-disse a-ele [מַדּ֙וּעַ֙] não [עַל־הַלְוִיִּ֔ם] sobre os-levitas [וּמִֽירוּשָׁלִַ֗ם] [אֶת־מַשְׂאַת֙] [מֹשֶׁ֣ה] a [וְהַקָּהָ֖ל] Moisés [לְאֹ֖הֶל] yhwh');
INSERT INTO verses VALUES (11689, 14, 24, 7, 'que [עֲתַלְיָ֙הוּ֙] [הַמִּרְשַׁ֔עַת] [בָּנֶ֥יהָ] [פָרְצ֖וּ] a casa o-Elohim [כָּל־קָדְשֵׁ֣י] todo [עָשׂ֖וּ] casa-de yhwh');
INSERT INTO verses VALUES (11690, 14, 24, 8, 'E-disse o-rei e-fizeram arca um וַֽיִּתְּנֻ֛הוּ em-porta-de casa-de yhwh חֽוּצָה׃');
INSERT INTO verses VALUES (11691, 14, 24, 9, 'e deram- קוֹל em-Judá e em Jerusalém- para trazer- a-yhwh carga- Moisés servo- o-Elohim sobre Israel no-deserto');
INSERT INTO verses VALUES (11692, 14, 24, 10, 'e alegrou-se- todo os-senhores e-todo o-povo e trouxeram- e lançaram- no arca- até para ser guardado∶');
INSERT INTO verses VALUES (11693, 14, 24, 11, 'e-houve [בְּעֵת֩] [יָבִ֨יא] a [אֶל־פְּקֻדַּ֣ת] a [בְּיַ֣ד] [הַלְוִיִּם֒] em-mão-de [כִּי־רַ֣ב] [הַכֶּ֗סֶף] porque muito [הַמֶּ֙לֶךְ֙] e-ele-veio [כֹּהֵ֣ן] o rei [וִיעָ֙רוּ֙] sacerdote [וְיִשָּׂאֻ֖הוּ] [וִֽישִׁיבֻ֣הוּ] a [כֹּ֤ה] [עָשׂוּ֙] [לְי֣וֹם] a [בְּי֔וֹם] assim fizeram');
INSERT INTO verses VALUES (11694, 14, 24, 12, 'וַיִּתְּנֵ֨הוּ o-rei וִֽיהוֹיָדָ֗ע a עוֹשֵׂה֙ מְלֶ֙אכֶת֙ serviço casa-de yhwh e-eram alugadores cortadores e forjadores yhwh casa yhwh e-tambem para os ferro e bronze yhwh a casa yhwh');
INSERT INTO verses VALUES (11695, 14, 24, 13, 'e fizeram feitores a-obra e-ela-subiu arca para-a-trabalho em-mão-deles e-estabeleceram-no a casa o-elohim sobre segundo-seu-propósito e-aceitaram-no');
INSERT INTO verses VALUES (11696, 14, 24, 14, 'e-quando-acabaram-os trouxeram em-frente-de-a o-rei e-yoida a havia o-prata e-fez-o כליים para-casa-de yhwh instrumentos-de שרת והעלות ouro e-vessãis ouro וכסף ויהיו maalims אולות na-casa-de dias-de תמיד todo dias-de יהודה׃');
INSERT INTO verses VALUES (11697, 14, 24, 15, 'ויזקן Joiada e jurou dias E-morreu filho-de cem e-trinta ano em-sua-morte:');
INSERT INTO verses VALUES (11698, 14, 24, 16, 'e o sepultaram na-cidade- David com da-cidades porque fez boa em-Israel e-com Elohim e-seu-casa:');
INSERT INTO verses VALUES (11699, 14, 24, 17, 'e-depois morrendo Joiada vieram príncipes-de Judá e-prostraram-se ao-rei então ouviu o-rei a-eles');
INSERT INTO verses VALUES (11700, 14, 24, 18, 'e-sairam a yhwh yhwh Elohim-de seus-pai e serviram a as Ashérim e-a os Ídolos e-foi esta sobre Judá e Jerusalém em sua iniqüidade esta-ali');
INSERT INTO verses VALUES (11701, 14, 24, 19, 'e-estendeu neles profetas para devolvê-los a yhwh e testemunharam neles e-não ouviram:');
INSERT INTO verses VALUES (11702, 14, 24, 20, 'e-Espírito-de Elohim vesti-vos a Zacarias filho-de Joada de-cima-de e-se-posicionou E-disse a-eles E-disse para-eles disse disse o-Elohim לָ-מָ֩ה vós transgredis yhwh מִצְוֺ֤ת yhwh e-não ser-vi-rá-de-sucedê-lo porque deixastes a yhwh e deixou a-vós');
INSERT INTO verses VALUES (11703, 14, 24, 21, 'e uniram sobre-ele e jogaram-no pedra na ordem da o-rei na-corte casa yhwh');
INSERT INTO verses VALUES (11704, 14, 24, 22, 'e-não macho Joas o-rei amor que fez seu-pai seu-pai com-ele e matou a disse e como ele morreu yhwh ele veria yhwh e investigaria:');
INSERT INTO verses VALUES (11705, 14, 24, 23, 'e-houve [׀] [לִתְקוּפַ֣ת] subiu subir força [חֵ֣יל] e-vieram a Judá [וִיר֣וּשָׁלִַ֔ם] [וַיַּשְׁחִ֛יתוּ] a todo príncipes-de o-povo [שִׁלְּח֖וּ] e-todo [דַּרְמָֽשֶׂק]');
INSERT INTO verses VALUES (11706, 14, 24, 24, 'que במצער homens בוּ׀ força אֲרָ֗ם e-יהוה deu dar חייל para muitos muito muito que a yhwh Elohim-de pais-deles e-a Joás fizeram juízos:');
INSERT INTO verses VALUES (11707, 14, 24, 25, 'e na sua marcha nós porque ele nele muitos se uniram sobre-ele servos-de-ele pelos sinais de filhos-de Joia o-sacerdote e o mataram sobre de sua cama E-morreu e-sepultaram-o na-cidade Davi e-não e o sepultaram בְּקִבְר֥וֹת הַמְּלָכִֽים׃');
INSERT INTO verses VALUES (11708, 14, 24, 26, 'e-estes [הַמִּתְקַשְּׁרִ֣ים] sobre-ele [זָבָ֗ד] filho-de [הָֽעַמּוֹנִ֔ית] [וִיה֣וֹזָבָ֔ד] [בֶּן־שִׁמְרִ֖ית] filho-de');
INSERT INTO verses VALUES (11709, 14, 24, 27, '[וּבָנָ֞יו] [*ורב] sobre-ele [הַמַּשָּׂ֣א] casa os-Elohim eis-os [הָאֱלֹהִ֔ים] sobre [כְּתוּבִ֔ים] livro [סֵ֣פֶר] e-reinou [וַיִּמְלֹ֛ךְ] filho-dele em-lugar-dele');
INSERT INTO chapters VALUES (392, 14, 25, 28);
INSERT INTO verses VALUES (11710, 14, 25, 1, 'filho-de vinte e-cinco ano rei [וְעֶשְׂרִי֤ם] [וָתֵ֙שַׁע֙] [שָׁנָ֔ה] ano rei em-Jerusalém sua-mãe mãe-dele [מִירוּשָׁלָֽיִם]');
INSERT INTO verses VALUES (11711, 14, 25, 2, 'E-fez o-reto em-olhos-de yhwh somente não [בְּלֵבָ֥ב] [שָׁלֵֽם]');
INSERT INTO verses VALUES (11712, 14, 25, 3, 'e-houve como [חָזְקָ֥ה] o-reino sobre-ele [וַֽיַּהֲרֹג֙] a seus-servos [אֶת־הַמֶּ֥לֶךְ] seu-pai');
INSERT INTO verses VALUES (11713, 14, 25, 4, 'e-[OBJ] não não que porque [בַּתּוֹרָ֡ה] [בְּסֵ֣פֶר] [מֹשֶׁה֩] Moisés yhwh dizendo yhwh dizendo não [וּבָנִים֙] [לֹא־יָמ֣וּתוּ] sobre que [אִ֥ישׁ] não [יָמֽוּתוּ׃] sobre porque homem');
INSERT INTO verses VALUES (11714, 14, 25, 5, 'וַיִּקְבֹּ֤ץ Amatsyahu a Judá וַיַּֽעֲמִידֵ֣ם para-casa-de אָב֗וֹת לְשָׂרֵ֤י הָאֲלָפִים֙ e-lasaréi os-ma''ot para-todo Judá e-Benjamim e-ve-piqdêm para construir vinte ano e-para-cima e achou-os três- exército mil בָּחוּר֙ saindo exército segurando arco e flecha');
INSERT INTO verses VALUES (11715, 14, 25, 6, 'e alugou-o do Israel cem mil heroi- chayil por cento de כַּסֶּפֶת׃');
INSERT INTO verses VALUES (11716, 14, 25, 7, 'e-homem o-Elohim veio a-ele dizendo do rei a virá contigo exercito que porque yhwh yhwh com Israel todo filhos-de Efrayim');
INSERT INTO verses VALUES (11717, 14, 25, 8, 'que se tu [עֲשֵׂ֖ה] fez [לַמִּלְחָמָ֑ה] [יַכְשִֽׁילְךָ֤] [הָֽאֱלֹהִים֙] הָֽאֱלֹהִים diante-de que porque há [לַעְז֥וֹר] [וּלְהַכְשִֽׁיל]');
INSERT INTO verses VALUES (11718, 14, 25, 9, 'E-disse Amatsyahu a homem-de os-Elohim umah- לאעשׂות֙ למאת ה-кїкїр dei dei לגוד E-disse E-disse homem הָֽאֱלֹהִ֔ים ישׁ a-yhwh a-ti a-ti muito deste-lado');
INSERT INTO verses VALUES (11719, 14, 25, 10, 'e os separou Amatsiú para marchar que a-ele a-ele מֵֽאֶפְרַ֔יִם para-andar em seu lugar e ardeu muito muito em juáda e-voltaram para seu lugar com-seu-escolhido também');
INSERT INTO verses VALUES (11720, 14, 25, 11, 'e Amatsiú fortaleceu-se e conduziu a povo-seu E-andou vale o sal e-feriu a filhos-de Seir dez mil:');
INSERT INTO verses VALUES (11721, 14, 25, 12, 'e-a-dez milhares vida e-deram filhos-de Judá e-eles-lhes-levaram para-cabeca o-saco e-eles-lhes-lançaram de-cima-de o-saco e-todos-eles quebraram-se');
INSERT INTO verses VALUES (11722, 14, 25, 13, 'e-filhos-de o-estalo que הֵשִׁ֤יב Amatsyahu מִלֶּ֤כֶת com-ele para-a-guerra וַֽיִּפְשְׁטוּ֙ em-cidades-de Judá מִשֹׁמְר֖וֹן e-até casa חוֹר֑וֹן e-feriram deles três-de milhares וַיָּבֹ֖זּוּ בִּזָּ֥ה multiplicai');
INSERT INTO verses VALUES (11723, 14, 25, 14, 'e-houve apos ב֤וֹא Amatsyahu מֵֽהַכּ֣וֹת a e-trouxe E-veio a Elohim-de filhos-de a-ele וַיַּֽעֲמִידֵ֥ם a-ele para-Elohim וְלִפְנֵיהֶ֥ם irá adorá-lo e-para-eles irá queimar');
INSERT INTO verses VALUES (11724, 14, 25, 15, 'e-acendeu-se- yhwh yhwh em Amazias a-ele a-ele E-disse a-ele para-ele por-que buscaste a Elohim-de o-povo que não salvai a seu povo de-mão-tua');
INSERT INTO verses VALUES (11725, 14, 25, 16, 'e-houve em sua palavra a-ele a-ele E-disse a-ele para-o-rei deixaste deixou de a-ti por-que atingir-te-ão e parou o-profeta E-disse יָדַ֗עְתִּי porque conselhou-se Elohim para te destruir porque fizeste esta e-não ouviste pelo meu conselho:');
INSERT INTO verses VALUES (11726, 14, 25, 17, 'e ele conselhou-se Amatsyahu rei Judá e-yi-shelakh a João filho-de Joaquim filho-de dizendo rei Israel dizendo foi revelado face');
INSERT INTO verses VALUES (11727, 14, 25, 18, 'e-enviou Joas rei-de Israel a dizendo rei-de יהודה֮ dizendo o cedro que no Líbano enviou dizendo o cedro que בַּלְּבָנוֹן֙ dizendo animal-de a בִּתְּךָ֥ Libni para-mulher וַֽתַּעֲבֹ֞ר animal-de o-campo que em-o-Líbano וַתִּרְמֹ֖ס a הַחֽוֹחַ׃');
INSERT INTO verses VALUES (11728, 14, 25, 19, 'אָמַ֗רְתָּ eis bateste a Edom וּנְשָׂאֲךָ֥ לִבְּךָ֖ לְהַכְבִּ֑יד agora שְׁבָ֣ה em-a-casa-teu por-que תִתְגָּרֶה֙ בְּרָעָ֔ה tu tu וִיהוּדָ֥ה contigo');
INSERT INTO verses VALUES (11729, 14, 25, 20, 'e-não ouviu que porque [הִ֔יא] [לְמַ֖עַן] para-que [בְּיָ֑ד] que porque [OBJ] a Elohim-de');
INSERT INTO verses VALUES (11730, 14, 25, 21, 'e-subiu יוֹאָ֤שׁ rei-de Israel וַיִּתְרָא֣וּ ele ele וַאֲמַצְיָ֣הוּ rei-de Judá em-casa-de sol que para-Judá');
INSERT INTO verses VALUES (11731, 14, 25, 22, 'e-foi-ferido Judá diante-de Israel e-eles-fugiram homem [לְאֹהָלָֽיו]');
INSERT INTO verses VALUES (11732, 14, 25, 23, 'e-את Amatsiáhu rei-de Judá filho-de Joas filho-de Yehoachaz tapaś Joás rei-de Israel em-casa-de sol וַיְבִיאֵ֙הוּ֙ Jerusalém vayiprots b''chomat Jerusalém miša''ar אֶפְרַיִם até portão hafoneh quatro centenas jardim; jardim:');
INSERT INTO verses VALUES (11733, 14, 25, 24, 'e-todo hazahav ve''hassef e-a todo ha''kelim os-encontrados na-casa-de os-אלהים com servo Edom e-a armazéns casa o-rei e-a filhos-de as-carregadoras E-tomou Samaria');
INSERT INTO verses VALUES (11734, 14, 25, 25, 'e-vidoe-se Amatsiú filho-de Joás rei Judá morrendo morte Joás filho-de yoãoaz rei Israel cinco dez anos');
INSERT INTO verses VALUES (11735, 14, 25, 26, 'וְיֶ֙תֶר֙ palavras-de אֲמַצְיָ֔הוּ הָרִאשֹׁנִ֖ים e-os-últimos הֲלֹא֙ eis-os כְּתוּבִ֔ים sobre livro-de reis-de יְהוּדָה e Israel');
INSERT INTO verses VALUES (11736, 14, 25, 27, 'e-do-tempo que saiu Amatsyahu yhwh yhwh e uniram-lhe sobre-ele cinto birushalaim e-fugiu a cintura e-eles-deram depois-dele a cintura e mataram-no nome');
INSERT INTO verses VALUES (11737, 14, 25, 28, 'e levaram-no sobre הַסּוּסִ֑ים ele a-ele com pais-dele em-cidade-de Judá');
INSERT INTO chapters VALUES (393, 14, 26, 23);
INSERT INTO verses VALUES (11738, 14, 26, 1, 've-yikhu todo povo Judá a Uzias e ele filho-de seis ele debaixo seu-pai a-ele sob seu-pai Amazias:');
INSERT INTO verses VALUES (11739, 14, 26, 2, 'ele edificar a ervas e a levou para-יְהוּדָה atrás-de שַׁכַּב־ o-rei com pais-dele');
INSERT INTO verses VALUES (11740, 14, 26, 3, 'filho-de seis quinze ano עֻזִּיָּהוּ em-seu-reinado e-cinquenta וְשֵׁתַיִם֙ ano rei em-Jerusalém sua-mãe mãe-dele de Jerusalém');
INSERT INTO verses VALUES (11741, 14, 26, 4, 'E-fez o-reto em-olhos-de yhwh conforme-tudo que fez seu-pai');
INSERT INTO verses VALUES (11742, 14, 26, 5, 'e-houve [לִדְרֹ֣שׁ] Elohim em-dias-de [זְכַרְיָ֔הוּ] [הַמֵּבִ֖ין] [בִּרְאֹ֣ת] o-Elohim [וּבִימֵי֙] [דָּרְשׁ֣וֹ] a yhwh [הָאֱלֹהִֽים׃]');
INSERT INTO verses VALUES (11743, 14, 26, 6, 'e-saiu [וַיִּלָּ֣חֶם] [בַּפְּלִשְׁתִּ֔ים] [וַיִּפְרֹ֞ץ] a [גַּ֗ת] e-[OBJ] e-[OBJ] muro-de e-[OBJ] e-[OBJ] [אַשְׁדּ֑וֹד] [וַיִּבְנֶ֣ה] [עָרִ֔ים] [בְּאַשְׁדּ֖וֹד] [וּבַפְּלִשְׁתִּֽים]');
INSERT INTO verses VALUES (11744, 14, 26, 7, '[וַיַּעְזְרֵ֨הוּ] [הָֽאֱלֹהִ֜ים] sobre [וְעַל־*הערביים] e-sobre [הַיֹּשְׁבִ֥ים] [בְּגוּר־בָּ֖עַל] [וְהַמְּעוּנִֽים]');
INSERT INTO verses VALUES (11745, 14, 26, 8, 'WAYYITTONU העמון- oferta לעזיהוּ E-andou nome-dele até le-bo que porque HEYCHAZIK até para-cima');
INSERT INTO verses VALUES (11746, 14, 26, 9, 'E-edificou עזיהוּ מגדל- em-Jerusalém sobre שַׁעַר הַפִּנָּה e-sobre portão-de o-vale e-sobre הַמִּקְצֹעַ וַיְחַזְּקוּ׃');
INSERT INTO verses VALUES (11747, 14, 26, 10, 'E-edificou [מִגְדָּלִ֜ים] [בַּמִּדְבָּ֗ר] [וַיַּחְצֹב֙] [בֹּר֣וֹת] muitos que [מִקְנֶה־רַּב֙] ser a-ele a-ele [וּבַמִּישׁ֑וֹר] [אִכָּרִ֣ים] [וְכֹֽרְמִ֗ים] [בֶּהָרִים֙] [וּבַכַּרְמֶ֔ל] [כִּֽי־אֹהֵ֥ב] terra ser foi');
INSERT INTO verses VALUES (11748, 14, 26, 11, 'e-houve לְעֻזִּיָּהוּ חַיִל fez מִלְחָמָה יוֹצְאֵי exército לִגְד֗וּד em-número-de פקודתם em-mão-de הסופר מעשייו o-comandante sobre mão-de sobre misiónרי o rei');
INSERT INTO verses VALUES (11749, 14, 26, 12, 'todo mispar cabeças-de הָאָבוֹת֙ לגבורות חיל dois-mil e-seis centenas');
INSERT INTO verses VALUES (11750, 14, 26, 13, 'e-sobre [חֵ֨יל] exército [שְׁלֹ֧שׁ] três centenas-de mil [אֲלָפִים֙] milhares [מֵא֔וֹת] centenas [מִלְחָמָ֖ה] guerra [חָ֑יִל] força [לַמֶּ֖לֶךְ] ao-rei sobre');
INSERT INTO verses VALUES (11751, 14, 26, 14, 'והכן֩ a-eles עזיהוּ para-todo הצבא מגינים ורמחים֙ וכובעים֔ וה Shiryonot e arcos e pedras e cravos');
INSERT INTO verses VALUES (11752, 14, 26, 15, 'E fez em Jerusalém e cestas mesa escritor para-ser sobre as torres e-sobre as pombas לִירֹא בַּחִצִּים וּבָאֲבָנִים גְּדֹלוֹת e-saiu nome-dele até porque até לְהֵעַזֵר até porque חָזָק׃');
INSERT INTO verses VALUES (11753, 14, 26, 16, 'וּכְחֶזְקָתוֹ גָּבַהּ coração-seu até לְהַשְׁחִית וַיִּמְעַל בַּיהוָ֣ה Elohim-dele E-veio yhwh o-santuário yhwh para queimar sobre yhwh haqtōret');
INSERT INTO verses VALUES (11754, 14, 26, 17, 'E-veio atrás-dele Azaryahu o-sacerdote e com ele kohanim לַיהוָ֛ה oitenta filhos-de força');
INSERT INTO verses VALUES (11755, 14, 26, 18, 'e colocaram sobre Uzziyah o rei a-ele a-ele não para-ti Uzziyah que a-yhwh porque para os kohanim filhos-de Aarao os santificados que saia de o santuário porque transgrediste e-não para-ti para-honra de-yhwh Elohim');
INSERT INTO verses VALUES (11756, 14, 26, 19, 'e se irritou Ozias e em sua mão incenso para incensar e em sua ira com os-sacerdotes e a lepra brilhou em-mizacho diante-de os-sacerdotes yhwh de-cima-de de-sobre para-mizbach haqtōret');
INSERT INTO verses VALUES (11757, 14, 26, 20, 'e-ele-virou a-ele azarayahu sacerdote o-rosh e-todo os-sacerdotes e-eis ele metzora em-mizacho e-avahiluhu de-lá e-também que nichaf yhwh porque nigua yhwh');
INSERT INTO verses VALUES (11758, 14, 26, 21, 'e-houve uziyyahu o-rei מְצֹרָ֣ע até dia מוֹת֗וֹ וַיֵּ֜שֶׁב casa מְצֹרָ֔ע porque foi-decretado que yhwh וְיוֹתָ֤ם yhwh sobre casa o-rei שׁוֹפֵ֖ט a povo a-terra');
INSERT INTO verses VALUES (11759, 14, 26, 22, '[וְיֶ֙תֶר֙] palavras-de [עֻזִּיָּ֔הוּ] [הָרִאשֹׁנִ֖ים] [וְהָאֲחֲרֹנִ֑ים] [כָּתַ֛ב] [יְשַֽׁעְיָ֥הוּ] filho-de [הַנָּבִֽיא]');
INSERT INTO verses VALUES (11760, 14, 26, 23, 'וישכב עזיהו com seus-pais ele a-ele com אביו בסדה הקבורה que למלכים porque ele מצורע ele e-reinou Jotão filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (394, 14, 27, 9);
INSERT INTO verses VALUES (11761, 14, 27, 1, 'filho-de vinte e-cinco ano [בְּמָלְכ֔וֹ] [וְשֵׁשׁ־עֶשְׂרֵ֣ה] e-seis- dez ano rei sua-mãe e-nome-de mãe-dele');
INSERT INTO verses VALUES (11762, 14, 27, 2, 'E-fez o direito em-olhos-de yhwh como-tudo que fez seu-pai pai-dele somente não yhwh a o-santuário yhwh e mais o-povo destroem');
INSERT INTO verses VALUES (11763, 14, 27, 3, 'ele edificar a portão-de casa-de yhwh o mais alto edificar a altura edificar para-multidão');
INSERT INTO verses VALUES (11764, 14, 27, 4, 'e cidades edificar em-monte-de Judá edificar בָּנָה nas buracos e torres');
INSERT INTO verses VALUES (11765, 14, 27, 5, 've-hu lutarão com rei filhos-de amom e fortaleceu-se sobre-eles e deram- a-ele filhos-de Amon em-a-ano a aquela cem k-khar- prata e-dez milhares esta trigo a-ele dez milhares esta responderam a-ele filhos-de não e-no-ano a-segunda e-na-terceira');
INSERT INTO verses VALUES (11766, 14, 27, 6, 'e-fortaleceu-se Joatham que הֵכִ֣ין seus-caminhos diante-de yhwh Elohim-dele');
INSERT INTO verses VALUES (11767, 14, 27, 7, 'e-resto palavras-de Yoțām e-todo Milḥāmōṯav uDěrāḵav eis-os כְּתוּבִ֔ים sobre livro-de reis- Israel e-Judá');
INSERT INTO verses VALUES (11768, 14, 27, 8, 'filho-de ʿešrīm wəḥāmeš ser foi bemālḵō e-seis- dez ano rei em-Jerusalém');
INSERT INTO verses VALUES (11769, 14, 27, 9, 'e-deitou-se Yoțām com seus-pais ele ele na-cidade Davi e-reinou Acaz filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (395, 14, 28, 27);
INSERT INTO verses VALUES (11770, 14, 28, 1, 'filho-de vinte ano ʾĀḥāḏ no seu reinado e-seis- dez ano rei em-Jerusalém e-não yhwh HaYYāšar seu-pai yhwh ḵəDāwīḏ seu-pai');
INSERT INTO verses VALUES (11771, 14, 28, 2, 'E-andou בְּדַרְכֵ֖י reis-de Israel e-também massoth fez לַבְּעָלִֽים׃');
INSERT INTO verses VALUES (11772, 14, 28, 3, 'e-ele queimou-um-sacrifício no vale filho-de hinnom e ardeu a filhos-dele no-fogo coisas abomináveis as-nações yhwh de-diante-de yhwh de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (11773, 14, 28, 4, 'e sacrificou e ofereceu em fumaça em bamos e-sobre as colinas e-debaixo-de todo árvore רענן׃');
INSERT INTO verses VALUES (11774, 14, 28, 5, 'e o deu yhwh seu Elohim na-mão-de rei ארם e atingiram- nele nós do-que-ele Shibuya grande e trouxeram- Darmashak e-tambem pela-mão-de rei Israel deu e atingiram- nele golpe גְדוֹלָה׃');
INSERT INTO verses VALUES (11775, 14, 28, 6, 'e mataram- Pekach filho-de Remalyahu em Judá cem e-vinte mil um um o-todo filhos-de força quando se afastaram a yhwh Elohim-de avos-eus');
INSERT INTO verses VALUES (11776, 14, 28, 7, 'e mataram sua memória homem Efraim a seus feitos filho-de o-rei e-a Azrikam nobre a-casa e-a Elcana ensinamento o rei');
INSERT INTO verses VALUES (11777, 14, 28, 8, 'e foram aprisionados filhos-de Israel de seus irmãos maatayim mil mulheres filhos וּבָנ֔וֹת e-também sua riqueza muito e se deleitaram deles e-trouxeram a o-salvamento para-Someron:');
INSERT INTO verses VALUES (11778, 14, 28, 9, 'e-lá ser profeta para- יהוה Odé seu-nome e-saiu diante-de o-exército o-que-vinha para-Someron E-disse a-eles eis com-ira yhwh Elohim-de seus-pai sobre Judá deles-recebeu em-mão-vossa até neles בְּזַעַף até לַשָּׁמַ֖יִם הִגִּֽיעַ׃');
INSERT INTO verses VALUES (11779, 14, 28, 10, 'e-agora filhos-de Judá וִֽירוּשָׁלִַ֙ם֙ vós אֹמְרִ֔ים לִכְבֹּ֛שׁ לַעֲבָדִ֥ים a-vós a-vós acaso-nao somente vós עִמָּכֶ֣ם אֲשָׁמ֔וֹת a-yhwh Elohim-vosso');
INSERT INTO verses VALUES (11780, 14, 28, 11, 'e-agora [שְׁמָע֔וּנִי] [וְהָשִׁ֙יבוּ֙] [הַשִּׁבְיָ֔ה] que [שְׁבִיתֶ֖ם] [מֵאֲחֵיכֶ֑ם] que [חֲר֥וֹן] também yhwh');
INSERT INTO verses VALUES (11781, 14, 28, 12, '[וַיָּקֻ֨מוּ] [אֲנָשִׁ֜ים] [מֵרָאשֵׁ֣י] filhos-de [עֲזַרְיָ֤הוּ] [בֶן־יְהֽוֹחָנָן֙] filho-de [בֶן־מְשִׁלֵּמ֔וֹת] [וִֽיחִזְקִיָּ֙הוּ֙] filho-de [וַעֲמָשָׂ֖א] [בֶּן־חַדְלָ֑י] filho-de [מִן־הַצָּבָֽא] filho-de sobre de');
INSERT INTO verses VALUES (11782, 14, 28, 13, 'e-disseram a-eles não [אֶת־הַשִּׁבְיָה֙] a que [לְאַשְׁמַ֨ת] yhwh [עָלֵ֙ינוּ֙] yhwh [אֹמְרִ֔ים] vós [עַל־חַטֹּאתֵ֖ינוּ] [וְעַל־אַשְׁמָתֵ֑ינוּ] sobre [אַשְׁמָה֙] e-sobre [וַחֲר֥וֹן] porque multiplicai sobre Israel');
INSERT INTO verses VALUES (11783, 14, 28, 14, 'e abandonou הֶֽחָל֗וּץ a הַשִׁבְיָה֙ e-a הַבִּזָּ֔ה diante-de os-senhores e-todo o povo');
INSERT INTO verses VALUES (11784, 14, 28, 15, 'וַיָּקֻ֣מוּ הָאֲנָשִׁים֩ que נִקְּב֨וּ בְשֵׁמ֜וֹת וַיַּחֲזִ֣יקוּ na-šavya e-todo ma-ărummehem hilbšu de ha-shalal va-yallabšuwm va-yănăneluwm va-yăkhaluwm va-yashqûwm va-yăsûkûwm va-yănăhaluwm בּ-חֲמֹרִים֙ para-todo כּוֹשֵׁ֔ל וַיְבִיא֛וּם יְרֵח֥וֹ cidades- הַתְּמָרִ֖ים junto-a אֲחֵיהֶ֑ם וַיָּשׁ֖וּבוּ Samaria');
INSERT INTO verses VALUES (11785, 14, 28, 16, 'em-o-tempo a aquela enviou o-rei אָחָ֛ז sobre reis-de Assíria a-ele a-ele');
INSERT INTO verses VALUES (11786, 14, 28, 17, 'וְע֥וֹד אֲדוֹמִ֖ים eles-vieram e-eles-feriram Em Judá וַיִּשְׁבּוּ- sevi:');
INSERT INTO verses VALUES (11787, 14, 28, 18, 'e-filisteus estenderam nas-cidades a-fértil e-o-negbe para-Judá e-pegaram a casa-de sol e-a a-de-alma e-a as-feridas e-a o-escondido וּבְנוֹתֶ֙יהָ֙ e-a a-timna uvénoteíha e-a גּימְזוֹ e-a benotayha e-habitaram nome');
INSERT INTO verses VALUES (11788, 14, 28, 19, 'porque yhwh yhwh a Judá [מֶֽלֶךְ־יִשְׂרָאֵ֑ל] que rei-de Israel porque [מַ֖עַל] [בַּיהוָֽה]');
INSERT INTO verses VALUES (11789, 14, 28, 20, 'E-veio sobre-ele Til-gat Pil-ne-ser rei Assíria וַיָּ֥צַר a-ele e-não חֲזָקֽוֹ׃');
INSERT INTO verses VALUES (11790, 14, 28, 21, 'porque [אָחָז֙] [אֶת־בֵּ֣ית] yhwh casa yhwh e-[OBJ] E-colocou o-rei [אַשּׁ֔וּר] E-deu como-rei a-ele e-não');
INSERT INTO verses VALUES (11791, 14, 28, 22, 'וּבְעֵת֙ הָצֵ֣ר a-ele Vejoséf em-muol em-Javé ele o-rei acegaz:');
INSERT INTO verses VALUES (11792, 14, 28, 23, 'Vayizbach a-Elohei Darmesek: os-machim nele; E-disse que Elohim-de reis- eles Eles auxiliadores a-eles a-eles azabbach va''ya''zarni e-eles foram- a-ele le''hakshilo e-para-todo- Israel');
INSERT INTO verses VALUES (11793, 14, 28, 24, 'וַיֶּאֱסֹ֨ף Acaz a utensílios-de casa-de o-Elohim va''yakatzes e-fechou utensílios-de casa-de הָֽאֱלֹהִ֔ים a-ele a portas-de casa-de yhwh E-fez um mizbechot em-todo pinah em-Jerusalém');
INSERT INTO verses VALUES (11794, 14, 28, 25, 'e-em-todo cidade va''ir para-Judá fez bamot le''katver le''Elohim outros e se irritou a yhwh Elohim-de pais-dele');
INSERT INTO verses VALUES (11795, 14, 28, 26, 'e remanescente suas palavras e-todo seus caminhos הָרִאשֹׁנִ֖ים e os últimos eis-os כְּתוּבִ֔ים sobre livro reis- יְהוּדָה e Israel');
INSERT INTO verses VALUES (11796, 14, 28, 27, 'e deitou-se Acaz com seus-pais e o sepultaram em cidade que não não e levaram-no para sepultura reis-de Israel e-reinou Yechizkiyyahu seu-filho em-lugar-dele');
INSERT INTO chapters VALUES (396, 14, 29, 36);
INSERT INTO verses VALUES (11797, 14, 29, 1, 'Jeováz-quando-rei rei filho-de vinte e cinco ano e-vinte וָתֵ֙שַׁע֙ ano rei em-Jerusalém sua-mãe sua-mãe Aviyah filha-de זכARYahu');
INSERT INTO verses VALUES (11798, 14, 29, 2, 'E-fez o-reto aos-olhos-de yhwh conforme-tudo que fez seu-pai seu-pai');
INSERT INTO verses VALUES (11799, 14, 29, 3, 'ele no ano primeiro para seu reinado no-mês o-primeiro abriu a portas-de casa-de yhwh e fortaleceu-os:');
INSERT INTO verses VALUES (11800, 14, 29, 4, 'e-trouxe a os-sacerdotes e-a os-levitas e reuniu-os no pátio o-oriente');
INSERT INTO verses VALUES (11801, 14, 29, 5, 'E-disse a-eles [שְׁמָע֣וּנִי] [הַלְוִיִּ֑ם] [עַתָּ֣ה] [הִֽתְקַדְּשׁ֗וּ] [וְקַדְּשׁוּ֙] a yhwh yhwh Elohim-de [וְהוֹצִ֥יאוּ] [אֶת־הַנִּדָּ֖ה] a de');
INSERT INTO verses VALUES (11802, 14, 29, 6, 'porque מָעֲלוּ אֲבֹתֵינוּ e façam o-mal em-olhos-de yhwh nosso-Elohim וַיַּעַזְבֻהוּ וַיַּסּבוּ yhwh do-mishkân yhwh e-comeu na face:');
INSERT INTO verses VALUES (11803, 14, 29, 7, 'também sâ-sargû portas-de hâ-aulâm wa-yakhbû a hannêrôt não não hiqtiyrû ve-ôlâ não fizeram-subir ba-qodesh לֵאלֹהֵ֖י Israel');
INSERT INTO verses VALUES (11804, 14, 29, 8, 'e-houve qêtsêph yhwh sobre Judá e-Ierusalim wa-yittem para-a e-para-a como vós vendo בְּעֵינֵיכֶֽם׃');
INSERT INTO verses VALUES (11805, 14, 29, 9, 'e-eis caíram nosso-abos com a espada e-nossos-filhos e-nossas-filhas e-nossas-mulheres no-tempo sobre esta-ali');
INSERT INTO verses VALUES (11806, 14, 29, 10, 'agora com לְבָבִ֔י para-cortar aliança a-yhwh Elohim-de Israel nós dele חֲרֹן אַף׃');
INSERT INTO verses VALUES (11807, 14, 29, 11, 'filhos-de agora a serem-cortadas porque yhwh escolheu yhwh para aprender diante-dele a-ele e ser a-ele מְשָׁרְתִ֥ים e fazer chuva');
INSERT INTO verses VALUES (11808, 14, 29, 12, 'e levantaram-se os levitas maldição filho-de de Amasi e Joel filho-de Azaryahu de filhos-de da casa de Kehat e-de filhos-de Merari קִישׁ filho-de servo-meu וַעֲזַרְיָ֖הוּ filho-de yehalelael e-de הַגֵּ֣רְשֻׁנּי יוֹאָח֙ filho-de זִמָּ֔ה וְעֵ֖דֶן filho-de יוֹאָֽח׃');
INSERT INTO verses VALUES (11809, 14, 29, 13, 'e-de filhos-de אֱלִ֣itzָפָ֔ן Shimi e-de filhos-de Asafe זְכַרְיָ֖הוּ וּמַתַּנְיָֽהוּ׃');
INSERT INTO verses VALUES (11810, 14, 29, 14, 'e-de filhos-de HEMEIMAN e-Simei e-de filhos-de YEDUTUN SHMAIAH e-Uziel');
INSERT INTO verses VALUES (11811, 14, 29, 15, 'VAYASAFU a ACHVEIMAHEM VAYITKADSHU e-vieram KEMITSVAH- yhwh B''DIVREI yhwh yhwh casa yhwh');
INSERT INTO verses VALUES (11812, 14, 29, 16, 'e-vieram os-sacerdotes LIFNIMA casa-de yhwh LETAHER e-foram-saí-los a todo a-tum-a-dá que yhwh em-templo-de yhwh yhwh casa yhwh e-receberam-los os-levitas para-sair para-o-nha-lá- kidron חֽוּצָה׃');
INSERT INTO verses VALUES (11813, 14, 29, 17, 'e-começaram-los no-um no-mês o-primeiro para-santificar e-no-dia oitava no mês vieram para sempre yhwh e santificaram a casa-de yhwh para os dias oitava e no dia seis dez para-o-mes dizendo terminaram');
INSERT INTO verses VALUES (11814, 14, 29, 18, 'e vieram para dentro a a força dele o-rei e-disseram נְתַהֲרֻ yhwh todo casa yhwh a altar-de הָעֹלָה e-a todo utensílios-dele e-a shulchan הַמְּעַרֶ֑כֶת e-a todo כּוֹלָיו׃');
INSERT INTO verses VALUES (11815, 14, 29, 19, 'e-a todo os recipientes que הִזְנַחַ o-rei אָחַז בְּמַלְכוּתוֹ בְּמַעֲלוֹ הִכַּנֻּ וְהִקְדַּשְׁנוּ e-eles diante-de yhwh yhwh');
INSERT INTO verses VALUES (11816, 14, 29, 20, 'e-ele-levantou-se Jeováz-quando-rei o-rei e-ajuntou a príncipes-de a-cidade e-ele-subiu casa yhwh');
INSERT INTO verses VALUES (11817, 14, 29, 21, 'e-trouxeram ovos- sete- cordeiros-e- sete- cabritos-e- sete pombas-e- ovejas-e- sete- para-transgressão sobre a-mo-lemá E-disse a-miq-dá-sh e-sobre Judá E-disse para-filhos-de yhwh os-sacerdotes l-va-alót sobre yhwh yhwh');
INSERT INTO verses VALUES (11818, 14, 29, 22, 'e sacrificaram o-bovino wa-y-kha-bé-lu os-sacerdotes a o-sangue wa-ya-zé-ré-qú o altar-para wa-ya-shé-kha-tú há-ê-lí-m wa-ya-zé-ré-qú ha-dam ao-altar e sacrificaram a-khá-bas-im wa-ya-zé-ré-qú o-sangue o-altar-para');
INSERT INTO verses VALUES (11819, 14, 29, 23, 'e-foram-lhes-enviados a o-velhos a-transgressão diante-de o-rei e-o-congregação e-foram-sustentados maos-deles sobre-eles');
INSERT INTO verses VALUES (11820, 14, 29, 24, 'e-foram-estripados-e-moídos os-sacerdotes e-sacrificaram-no a sangue-o ao-altar para-ter-expiação que todo disse porque para-todo Israel disse o-rei a-holocausto e-a-oferta-de-sacrifício-versículo-final');
INSERT INTO verses VALUES (11821, 14, 29, 25, 'e-estabeleceu a dos-Levitas yhwh yhwh com-címbalos בִּנְבָלִ֣ים וּבְכִנֹּר֔וֹת בְּמִצְוַ֥ת Davi וְגָ֥ד חֹזֵֽה־ o-rei que o-profeta porque na-mao-de yhwh da-mandamento por-mão-de נְבִיאָֽיו׃');
INSERT INTO verses VALUES (11822, 14, 29, 26, 'וַיַּֽעַמְד֤וּ os-levitas em-vasos-de Davi e-os-sacerdotes בַּחֲצֹצְרֽוֹת׃');
INSERT INTO verses VALUES (11823, 14, 29, 27, 'E-disse חִזְקִיָּ֔הוּ para-oferecer a-holocausto לְהַמִּזְבֵּ֑חַ e na época começou a holocausto começou שיר－ yhwh e os cornos e-sobre as mãos kléi- Davi rei-de Israel');
INSERT INTO verses VALUES (11824, 14, 29, 28, 'e-todo o convocados de adoração e a canção que toca e os cornos o-tudo até até a-elevação');
INSERT INTO verses VALUES (11825, 14, 29, 29, 'e quando terminou para levá-lo - o-rei e-todo os achados com-ele וַיִּֽשְׁתַּחֲוֽוּ׃');
INSERT INTO verses VALUES (11826, 14, 29, 30, 'E-disse Yehozaque o-rei e-os-príncipes aos levitas para-louvar a-yhwh בְּדִבְרֵ֥י דוד e Asaf o profeta e louvaram até para alegria e-inclinaram-se וַיִּֽשְׁתַּחֲוֽוּ׃');
INSERT INTO verses VALUES (11827, 14, 29, 31, 'e-ele-respondeu Yehozaque E-disse agora millete''em yedke''m a-yhwh goshu vehabio''u zevachim vetodot para-casa-de yhwh vayabio''u o convocados sacrifícios vetodot e-todo n''div coração olot');
INSERT INTO verses VALUES (11828, 14, 29, 32, 'e-houve número a holá que trouxeram o kahal manhã setenta carneiros cem cordeiros duzentos para a holá a-yhwh todo Estas');
INSERT INTO verses VALUES (11829, 14, 29, 33, 'e as santificações manhã seis centenas e o gado três mil:');
INSERT INTO verses VALUES (11830, 14, 29, 34, 'apenas os-sacerdotes eram em pequena quantidade e-não יָכְלוּ לְהַפְשִׁית a todo הָעֹלוֹת וַיִּחַזְקוּם seus-irmãos os-levitas até כְּלוֹת הַמְּלָאכָה que יִתְקַדֵּשׁוּ הַכֹּהֲנִים porque os-levitas יִשְׁרֵי לֵבָב para se santificar de-אַכּוֹנִים׃');
INSERT INTO verses VALUES (11831, 14, 29, 35, 'e-também oferta holocausto para-a-muitidão em-בַּחֲלֵבֶיהָ os-de-paz e-em os nesakim para a oferta holocausto e-a ela se estabeleceu serviço casa-de yhwh');
INSERT INTO verses VALUES (11832, 14, 29, 36, 'e-o deleitou-se Yehozaque e-todo sobre sobre aquele preparou o-Elohim que porque ser foi a-palavra');
INSERT INTO chapters VALUES (397, 14, 30, 27);
INSERT INTO verses VALUES (11833, 14, 30, 1, 'e-enviou Yechizquiyyahu sobre todo Israel וִֽיהוּדָ֗ה e também- cartas escreveu- sobre Efraim e Manassés- para-vir para-a-casa-de yhwh בִּֽירוּשָׁלָ֑͏ִם para fazer Pessach a-yhwh Elohim-de Israel');
INSERT INTO verses VALUES (11834, 14, 30, 2, 'e deliberaram- o-rei e seus generais- e-todo a-congregação em-Jerusalém para-fazer o-páscoa no mês- o-segundo');
INSERT INTO verses VALUES (11835, 14, 30, 3, 'que não conseguiram- para-fazer-o em-o-tempo aquela que aos-sacerdotes não consagrem-vos para-meu-ensinar e-o-povo não de-diante-de para- Jerusalém');
INSERT INTO verses VALUES (11836, 14, 30, 4, 'e-ele-dispos a palavra aos-olhos-de o-rei e-em-olhos-de todo o povo');
INSERT INTO verses VALUES (11837, 14, 30, 5, 'e-eles-erigiram palavra para-transpor voz em-todo Israel de-Aveir- sete e-até Dan para-vir para-fazer Pésach que não Israel em-Jerusalém porque não Larob fizeram como-escrito');
INSERT INTO verses VALUES (11838, 14, 30, 6, 'Va''yelchu@ Haratzim Ba''agorot Miyad@ o-rei Ve''sarav@ em-todo Israel e-Yehuda U''kemitzvath dizendo dizendo filhos-de Israel Shuvu@ a yhwh Elohim-de Abraão Isaque e Israel e-voltará a-vós a-destruição o-que-restou a-vós de-cada reis-de Aššúrā');
INSERT INTO verses VALUES (11839, 14, 30, 7, 'e-a vocês-serão como-vossos-pais [אֲשֶׁ֣ר] que subiram em-יהוה Elohim-de pais-deles e-os-distribuíram para-a-luz como vós os-que-vêem-verso-final');
INSERT INTO verses VALUES (11840, 14, 30, 8, 'agora a durem vossos-cabeças como-vossos-pais dai- mão a-yhwh e-entrem para-seu-lugar-santo que consagrou para-sempre e-servireis a yhwh vosso-Elohim e-yashov de vós nós אַף׃');
INSERT INTO verses VALUES (11841, 14, 30, 9, 'que em-vos-retornando sobre yhwh vossos-irmãos e-vossos-filhos para-misericórdias diante-de retornando-os e-para-retornar a-terra esta porque yhwh e-misericordioso yhwh vosso-Elohim e-não afastará a-ele de-vós se tornem-se a-ele');
INSERT INTO verses VALUES (11842, 14, 30, 10, 'e-eles-foram os-corredores עברים de-a-cidade para-a-cidade em-terra-de Efraim e-Menasseh e-até Zebulun e-foram zombando sobre-eles [בָּֽם] em-eles');
INSERT INTO verses VALUES (11843, 14, 30, 11, 'somente homens de-Asher e-Menashe e-de-Zebulun se-curvaram e-vieram');
INSERT INTO verses VALUES (11844, 14, 30, 12, 'também em-Juda era mão o-Elohim a-dar a-eles coração um לַעֲשׂ֞וֹת mandamento-de o-rei e-os-senhores pela-palavra-de yhwh');
INSERT INTO verses VALUES (11845, 14, 30, 13, 'e-se-reuniram Jerusalém com muito para-fazer a festa-de a matzot no-mês o-segundo muito לָרֹ֥ב muito');
INSERT INTO verses VALUES (11846, 14, 30, 14, 'e-levantaram-se e-retiraram-m-no a os-mizbóchot que em-Jerusalém e-a todo as-fumantes retire-m-os e-eles-deram-lancem para-o-riff Kidron:');
INSERT INTO verses VALUES (11847, 14, 30, 15, 'wa-ya-shé-kha-tú o-passo בְּאַרְבָּעָ֥ה dez no-mês o-segundo e-os-sacerdotes e-os-levitas foram-encobertos-m VAYITKADSHU e-trouxeram holocaustos casa yhwh');
INSERT INTO verses VALUES (11848, 14, 30, 16, 'וַיַּֽעַמְד֤וּ sobre estavam-parados-eles como-julgamento como-fumaça Moisés homem-de o-Elohim os-sacerdotes lançando-m-os a o-sangue de-mão-de os-levitas');
INSERT INTO verses VALUES (11849, 14, 30, 17, 'porque grande em-a-sembléia que não santificaram-se e-os-levitas a-todo não os-pasqueiros para-todo não puro para-santificar para-יהוה');
INSERT INTO verses VALUES (11850, 14, 30, 18, 'que grande o-povo grande de-Éfrem e-Menassés Issacar e-Zebulom não purifiquem-se porque comam a o-páscoa que como-escrito porque ora-se dizendo yhwh dizendo yhwh o-bom perdoará em-o-lugar-de');
INSERT INTO verses VALUES (11851, 14, 30, 19, 'todo para-a-sua-mente preparou para-pesquisar os-elohim yhwh Elohim-de pais-seus e-não de-ta-hora-th o-santuário');
INSERT INTO verses VALUES (11852, 14, 30, 20, 'E-ouviu yhwh a יְחִזְקִיָּ֔הוּ e-yir-fah a o-povo');
INSERT INTO verses VALUES (11853, 14, 30, 21, 'e-fizeram filhos-de Israel os-encontrados em-Jerusalém a חַ֧ג ha-matz-oth sete dias בְּשִׂמְחָ֣ה grande dia la-yhwh י֣וֹם ׀ be-yom ha-lev-i-im ve-ha-kho-ha-nim com-utensílios-de força para-יהוה');
INSERT INTO verses VALUES (11854, 14, 30, 22, 'e-falou Yechizkiyahu sobre coração todo os-levitas ha-mash-khil-im she-ke-l bom a-yhwh e-eles-comeram a o-festival sete os-dias sacrificando sacrificios-de paz e-se-confessando a-yhwh Elohim-de seus pais:');
INSERT INTO verses VALUES (11855, 14, 30, 23, 'e-eles-conselharam-se todo o-a congregação לַעֲשׂוֹת sete dias outros e-fizeram sete- dias alegria:');
INSERT INTO verses VALUES (11856, 14, 30, 24, 'que a força dele rei-de Yehudah subidas [אֶ֣לֶף] mil novilhos e-sete milhares ovelhas e-os-senhores levantaram-se [לַקָּהָל֙] parí mil e o gado dez milhares e-eles-se-santificaram sacerdotes para-multidão');
INSERT INTO verses VALUES (11857, 14, 30, 25, '[וַֽיִּשְׂמְח֣וּ] todo assembleia Judá e-os-sacerdotes e os levitas e-todo a-congregação os-que-vieram de-Israel e-os-estrangeiros os-que-vêm da-terra Israel e-os-habitantes em-juda:');
INSERT INTO verses VALUES (11858, 14, 30, 26, 'e-foi alegria- grande que porque de-dias שְׁלֹמֹה filho-de Davi não Israel não assim em-Jerusalém');
INSERT INTO verses VALUES (11859, 14, 30, 27, 'e se levantaram os-sacerdotes os-levitas וַיְבָרֲכ֣וּ a o-povo E-ouviu com-a-sua-voz e-veio oração-deles para-lugar santo-seu aos-céus');
INSERT INTO chapters VALUES (398, 14, 31, 21);
INSERT INTO verses VALUES (11860, 14, 31, 1, 'e-quando-acabou todo esta saíram todo Israel os-que-foram-encontrados para-as-cidades יְהוּדָה֒ e-eles-partiram as-matrizes e-eles-cortaram os-asheres e-eles-demoliram a as-altarinhos e-a as-matrizes de-todo Judá [כָּל־בְּנֵ֧י] e-em-Efraim e-Menashe até para-completar e-eles-voltaram todo filhos-de Israel homem para-a-posse-dele para-as-cidades-deles');
INSERT INTO verses VALUES (11861, 14, 31, 2, 'e pôs-se Yechizyahu a partes os-sacerdotes e-os-levitas sobre [׀] homem segundo serviço-dele para-os-sacerdotes e-los-lévitas para-oferta e-para-as-pacificações para-o-servir e-para-a-gratidão e-para-o-louvar nas-portas-de yhwh yhwh');
INSERT INTO verses VALUES (11862, 14, 31, 3, 'e-a-partilha o-rei de do-seu-bem-estar para-as-oferendas para-as-oferendas a-manhã e-a-noite e-as-ofertas para-os-sabados e-para-os-novos-meses e aos convocações conforme-o-escrito yhwh yhwh');
INSERT INTO verses VALUES (11863, 14, 31, 4, 'E-disse para-o-povo para-os-habitantes-de Jerusalém para-dar porção os-sacerdotes e-os-levitas para [יֶחֶזְק֖וּ] בְּתוֹרַ֥ת yhwh');
INSERT INTO verses VALUES (11864, 14, 31, 5, 'e-quebrantem a-palavra aumentaram filhos-de Israel רֵאשִׁ֣ית dagan tirosh veyitzhar e-tudo e-todo תְּבוּאַ֣ת sadeh umashar hakol para-multiplicar heviu');
INSERT INTO verses VALUES (11865, 14, 31, 6, 'e-filhos-de Israel וִֽיהוּדָ֗ה hayoshvim em-cidades-de Yehuda também Eles mashar manhã e-os-cordeiros e-o-décimo santos os santificados a-yhwh Elohim-deles os-trouxe e-eles-se-dividiram acervos acervos:');
INSERT INTO verses VALUES (11866, 14, 31, 7, 'em-o-mês o-terceiro começaram as-acervos para-a-fundação e-no-mês ha-shevi-i terminaram');
INSERT INTO verses VALUES (11867, 14, 31, 8, 'e-vieram Jeováz-quando-rei e-os-príncipes e-eles-viram a as-aré-mos e-eles-benço-aram a yhwh e-a seu-povo Israel');
INSERT INTO verses VALUES (11868, 14, 31, 9, 'e-ele-procurou Ieciquiau sobre [וְהַלְוִיִּ֖ם] e-os-levitas sobre as-aré-mos-verso-final');
INSERT INTO verses VALUES (11869, 14, 31, 10, 'E-disse a-ele Azarias o-sacerdote a-cabeça para-casa-de Zadoque E-disse des-de-o-início da-oferta para-o-livro casa-de yhwh ako-l e-satisfazer e-o-resto que yhwh porque yhwh abençoou a seu-povo e-o-no-te-ro a הֶהָמוֹן a-esta');
INSERT INTO verses VALUES (11870, 14, 31, 11, 'E-disse Yechizqiyyahu para-preparar para-os-cômodos em-casa-de yhwh e-eles-preparam');
INSERT INTO verses VALUES (11871, 14, 31, 12, 'Va''yaví''u a a-teruma e-o-mais-dez e-os-santos em-a-fé e-sobre-eles um-líder o-levita e-Shimi seu-irmão um-igual');
INSERT INTO verses VALUES (11872, 14, 31, 13, 'e-Jiielel e-Azaziahu e-Nachat e-faz-Elohim e-ri-mo-t e-yo-zab-ad [וֶאֱלִיאֵ֣ל] e-is-makh-ya-hu u-ma-chat u-bna-yahu pe-qi-di-im מִיַּ֤ד e-שִׁמְעִי irmão-seu be-mif-qad Jeováz-quando-rei o-rei וַעֲזַרְיָ֖הוּ principe casa-de o-Elohim');
INSERT INTO verses VALUES (11873, 14, 31, 14, 'e-kore-a filho-de yim-na o-levi o-shoer sobre sobre n-davot o-Elohim לָתֵת֙ yhwh yhwh e-kodeshei os-santos');
INSERT INTO verses VALUES (11874, 14, 31, 15, 'e-sobre Éden eden u-miniamin e-Jesua u-shemiyahu amar-yahu u-schanyahu em-cidades-de os-sacerdotes be-emuna para-dar para-os-irmãos em-partes como-grande [sem-traducao]');
INSERT INTO verses VALUES (11875, 14, 31, 16, 'exceto se-fizeram para-os-masculinos de-filho-de três dois e-para-alto para-todo הַבּ֥א para-a-casa-de yhwh por-causa-de dia em-o-seu-dia para-a-obra-deles em-as-miradas-deles como-em-partes-deles-verso');
INSERT INTO verses VALUES (11876, 14, 31, 17, 'e-a se-ridicularizou aos-sacerdotes para-casa-de seus-pai e-os-levitas מִבֶּ֛ן vinte ano e-para-alto em-as-miradas-deles em-partes-deles-verso');
INSERT INTO verses VALUES (11877, 14, 31, 18, 'e-para-se-ridicularizar em-todo os-filhos-deles [וּבְנֵיהֶ֥ם] [וּבְנוֹתֵיהֶ֖ם] [לְכָל־קָהָ֑ל] que [בֶאֱמוּנָתָ֖ם] porque [sem-traducao] se-sanctifiquem- קֹדֶשׁ׃');
INSERT INTO verses VALUES (11878, 14, 31, 19, '[וְלִבְנֵי֩] Aarao os-sacerdotes nas-terrains do-campo de-sua-cidade em-todo cidade e-a-cidade אֲנָשִׁ֕ים que foram-designados em-os-nomes para-dar [לְכָל־זָכָר֙] para-todo macho בַּכֹּ֣הֲנִ֔ים e-para-todo- se-rixeu em-levi-im');
INSERT INTO verses VALUES (11879, 14, 31, 20, 'E-fez assim Yechizyahu em-todo Judá E-fez o-bom e-o-retirado e-a-verdade yhwh yhwh Elohim-dele');
INSERT INTO verses VALUES (11880, 14, 31, 21, 'e-em-todo-o obra que começou em-a-serve casa-de o-Elohim e-na-lei e-no-preceito para-consultar para-seus-elohimes em-todo ao-sua-coração fez e-teve-sucesso');
INSERT INTO chapters VALUES (399, 14, 32, 33);
INSERT INTO verses VALUES (11881, 14, 32, 1, 'apos hadavarim e-a-verdade estes veio Sancarív rei-de Assíria E-veio בִֽיהוּדָ֗ה e-acampou sobre E-disse as-batzurot a-ele para-a-biqea a-ele');
INSERT INTO verses VALUES (11882, 14, 32, 2, 'E-viu יְחִזְקִיָּ֔הוּ porque veio Sanheriv e-as-suas-faces para-a-guerra sobre Jerusalém');
INSERT INTO verses VALUES (11883, 14, 32, 3, 'e ele conselhou-se com os-senhores-dele e-os-seus-giborim para-estomar a de-a-água as-a-yanaot que de-fora para-a-cidade e-ele-ajudou-o');
INSERT INTO verses VALUES (11884, 14, 32, 4, 'e-reuniram-se com muito e-eles-estomaram a todo as-ma-yanaot dizendo o-nachal o-shotev em-meio-de a-terra dizendo águas venham reis-de Assur e-matzu águas muitos');
INSERT INTO verses VALUES (11885, 14, 32, 5, 'e-vitkhatzak E-edificou a todo o-choma ha-prutza e-subiu sobre ham-migdalot ve-la-chutsa o-choma אַחֶ֔רֶת e-estreitou a o-enchimento cidade Davi E-fez enviou para-multiplicar e-guardiões');
INSERT INTO verses VALUES (11886, 14, 32, 6, 'E-colocou príncipes-de de-guerras sobre o-povo a-ele a-ele a a-largura portão a-cidade dizendo sobre a-ti para-dizer');
INSERT INTO verses VALUES (11887, 14, 32, 7, 'fortalecei e-alcancem a temam de-diante-de [מֶ֣לֶךְ] mipnay rei Assíria e-de-frente-aos todo o todo que com-ele porque o-dia muito de-com-ele');
INSERT INTO verses VALUES (11888, 14, 32, 8, 'com-ele de-braco de-carne [וְעִמָּ֜נוּ] yhwh Elohim-nosso para-a-ajuda-de-nos [וּלְהִלָּחֵ֖ם] as-guerras-dos-nossos e-eles-apoiaram o-povo sobre palavras-de Yecizquiahu rei-de Judá');
INSERT INTO verses VALUES (11889, 14, 32, 9, 'depois-de este enviou Sanheriv rei-de [עֲבָדָיו֙] seus-servos Jerusalah e-ele sobre Lachish e-todo mimshaltô com-ele sobre Yehozaque rei dizendo e-sobre todo יְהוּדָה que birushalaim para-dizer');
INSERT INTO verses VALUES (11890, 14, 32, 10, 'assim disse Sanheriv rei Assíria sobre ma'' vós botchim veyoshvim bematzor em-Jerusalém');
INSERT INTO verses VALUES (11891, 14, 32, 11, 'acaso-nao Yehozaque massit vos para-dar vos lamut beraav uvetzama dizendo yhwh nosso-Elohim yatzilenu de-a-palma rei Aššúrā');
INSERT INTO verses VALUES (11892, 14, 32, 12, 'não-é ele יְחִזְקִיָּ֔הוּ hésir a E-disse e-a de-seus-altar-es dizendo לִֽיהוּדָ֤ה e-a-Jerusalém um diante-de altar um sobre ele queimareis');
INSERT INTO verses VALUES (11893, 14, 32, 13, 'porventura-não sabereis o-que eu fiz eu e-meus-pais a-todo povos as-terras poderiam puderam Elohim-de nação as-terras para salvar a a-terra-deles de-mim');
INSERT INTO verses VALUES (11894, 14, 32, 14, 'quem em-todo elohim-de os-povos estes que eles-consagraram avotai que pode para salvar a que de-mim porque pode אֱלֹהִים-de-vós para salvar vós de-mim');
INSERT INTO verses VALUES (11895, 14, 32, 15, 'e-agora a ele-derribará a-vocês Cezíah e-a ele-conduzira אֶתְכֶ֣ם a-ele e-a você-crerá para-ele porque não poderia todo elohim todo nação certamente que povo-dele מיידי e-de-mão-de אֲבוֹתָ֑י certamente porque os-elohimes-seus não יַצִּ֥ילוּ vós de-mim');
INSERT INTO verses VALUES (11896, 14, 32, 16, 'e-mais falaram seus-servos sobre yhwh o-Elohim e-sobre יהוחזקיוהו seu-servo');
INSERT INTO verses VALUES (11897, 14, 32, 17, 'e-sefarim escreveu para-o-rir a-yhwh Elohim-de Israel e-para-dizer sobre-ele dizendo como-אלהי nação as-áratsot que não resgataram amam de-mimyadi assim não salvar-á Elohim-de יְחִזְקִיָּ֛הוּ que de-mim');
INSERT INTO verses VALUES (11898, 14, 32, 18, 'e-ele-chamaram em-voz- grande יְהוּדִ֗ית sobre povo Jerusalém que sobre a-muralha para-que-treme-os e-a-pavorá-los para-que serão-apreendidos a a-cidade');
INSERT INTO verses VALUES (11899, 14, 32, 19, 'וַיְדַבְּר֔וּ a Elohim-de Jerusalém contra Elohim-de a-terra a-terra obra-de o-homem o-homem');
INSERT INTO verses VALUES (11900, 14, 32, 20, 'e-ele-orou Jeováz-quando-rei o-rei וִֽישַֽׁעְיָ֧הוּ filho-de forte o-profeta sobre esta e-ele-clamaram os-céus');
INSERT INTO verses VALUES (11901, 14, 32, 21, 'e-estendeu yhwh an anjo e-ele-escondeu todo heroi- חייל e-príncipe e-superior em-o-acampamento rei Assíria va-yashav em-a-vergonha face para-a-terra-dele E-veio casa Elohim-dele de-os-intestinos-seus nome e-eles-jogaram-nochão com-a-espada');
INSERT INTO verses VALUES (11902, 14, 32, 22, 'e-Yoshua yhwh a Yehozaque e-את habitantes-de Jerusalém de-mão-de Sanheriv rei-de Assíria e-mi-yad- todo va-yenahelem misaviv');
INSERT INTO verses VALUES (11903, 14, 32, 23, 've-rabim trazendo minchah para-יהוה a-Jerusalém um-migdanoth le-Hezekiahu rei Judá va-yinnase para-olhos-de todo as-nações me-a-chari- assim');
INSERT INTO verses VALUES (11904, 14, 32, 24, 'em-os-dias aqueles chalah Yechizqiyyahu até la-mut ve-yitpallel E-disse a-ele E-disse dar a-ele deu a-ele');
INSERT INTO verses VALUES (11905, 14, 32, 25, 'e-não kigmul sobre-ele hêshı̂yb que porque gavah e-houve E-foi sobre-ele ira e-sobre יְהוּדָה Jerusalém:');
INSERT INTO verses VALUES (11906, 14, 32, 26, 'vayyikkanna'' Yehozaque begovah coração-dele ele e-habitantes-de Jerusalém e-não veio sobre-eles yhwh yhwh nos-dias Yechizqiyyahu');
INSERT INTO verses VALUES (11907, 14, 32, 27, 'e-houve liychizqiyyahu dez vekhavod muito muito veotsarot fez lo [וּלְזָהָ֜ב] [וּלְאֶ֣בֶן] [יְקָרָ֗ה] [וְלִבְשָׂמִים֙] [וּלְמָ֣גִנִּ֔ים] [וּלְכֹ֖ל] e-a-todos instrumentos-de desejo');
INSERT INTO verses VALUES (11908, 14, 32, 28, '[וּמִ֨סְכְּנ֔וֹת] [לִתְבוּאַ֥ת] [דָּגָ֖ן] [וְתִיר֣וֹשׁ] e-Izhar e-uravot para-todo animal e-behema ve-adarim la-averot');
INSERT INTO verses VALUES (11909, 14, 32, 29, 'e cidades fez a-ele u-mikne- rebanho e-vacas que porque deu a-ele Elohim muito muito muito');
INSERT INTO verses VALUES (11910, 14, 32, 30, 'e-ele Yechizqiya-hu satom a motza de-águas-de Gichon a-superior e-os-endireitou para-baixo- do-oeste para-a-cidade Davi e-ele-teve-sucesso Yechizqiya em-todo maasehu');
INSERT INTO verses VALUES (11911, 14, 32, 31, 'e-assim com-os-conselhos- príncipes-de Bavel dos-enviados sobre-ele para-pesquisar o-mofet que foi ser na-terra o-Elohim para-nasuto para-daat para-conhecer em-o-levavo');
INSERT INTO verses VALUES (11912, 14, 32, 32, 'e-resto-de palavras-de Yechizyahu e-hesado eis-os escritos em-o-chazon Yeshayahu filho-de Amots o-profeta sobre livro מַלְכֵי־ יְהוּדָה e Israel');
INSERT INTO verses VALUES (11913, 14, 32, 33, 'וישכב Yehozaque com seus-pais e-yikberuhu em-o-alto sepulcros-de filhos-de Давид e-honra fizeram- a-ele na-morte-dele todo Judá e-habitantes-de Jerusalém e-reinou Manassés filho-dele em-lugar-dele');
INSERT INTO chapters VALUES (400, 14, 33, 25);
INSERT INTO verses VALUES (11914, 14, 33, 1, 'filho-de dois dez-o ano מְנַשֶּׁ֣ה bemālḵō e-cinquenta e cinco ano rei em-Jerusalém');
INSERT INTO verses VALUES (11915, 14, 33, 2, 'E-fez o-mal aos-olhos-de yhwh idolatrias as-nações que ele-desapossou yhwh de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (11916, 14, 33, 3, 'e-voltou E-edificou a havvámot- que derrubaram seu-pai seu-pai E-levantou altáres para-Baalim E-fez Aseroth e-abaixou-se para-todo exercito eles váyaʿabód eles');
INSERT INTO verses VALUES (11917, 14, 33, 4, 'úvaná מִזְבְּח֖וֹת na-casa-de yhwh que disse yhwh Birushalaim sera shemi para-eternidade');
INSERT INTO verses VALUES (11918, 14, 33, 5, 'E-edificou מִזְבְּח֖וֹת para-todo exercito os-céus בִּשְׁתֵּ֖י חַצְר֥וֹת casa-de yhwh');
INSERT INTO verses VALUES (11919, 14, 33, 6, 'e-ele heeviyr a seus-filhos em-o-fogo nos filho-de de Hinom ve-onen venicheish ve-kishef e fizer א֖וֹב veyidoniy הִרְבָּ֗ה para-fazer yhwh em-olhos-de yhwh para-irritar-ele');
INSERT INTO verses VALUES (11920, 14, 33, 7, 'e pôs a figura hassemel que fez na-casa-de o-Elohim disse disse Elohim a Davi e-a Shelomoh be-no no templo o-este de-toda que eu escolhi de-todo tribos-de Israel ʾāśîm a nome-meu le-eilom');
INSERT INTO verses VALUES (11921, 14, 33, 8, 'e-não osif para-sair a רגל de-cima-de de-sobre a-terra que eu-estabeleci para-os-pais-vosso somente se guardem לַעֲשׂ֗וֹת a todo que mandamentos; para-todo הַתּוֹרָ֛ה e-as-leis e-os-julgamentos por-mão-de Moisés');
INSERT INTO verses VALUES (11922, 14, 33, 9, 'e-ele-se-perdeu Manassés a Judá e-habitantes-de Jerusalém mal mau de os-povos yhwh de-diante-de yhwh de-diante-de filhos-de Israel');
INSERT INTO verses VALUES (11923, 14, 33, 10, 'e-ele-falou yhwh a Manassés e-a amav e-não e-ouviram');
INSERT INTO verses VALUES (11924, 14, 33, 11, 'e-trouxe yhwh sobre-eles a príncipes-de o-exército que como-rei Assíria e-eles-capturaram a ménashé com-fraudes e-eles-encadearam-no em-metalo e-os-leve-o Bavelah;');
INSERT INTO verses VALUES (11925, 14, 33, 12, 'e-como-grama a-ele comeu-a a yhwh yhwh Elohim-dele muito muito de-diante-de Elohim-de pais-dele');
INSERT INTO verses VALUES (11926, 14, 33, 13, 'e-ele-orou a-ele e-o-aceitou a-ele E-ouviu súplica-seu e-ele-devolveu-o Jerusalém para-reinado-seu e-soube Manassés que yhwh ele Elohim:');
INSERT INTO verses VALUES (11927, 14, 33, 14, 'e-depois-de edificar construiu-a muralha exterior para-a-cidade- [מַעְרָ֩בָה֩] ocidental para-gichon no-nachal e-entrar [הַדָּגִים֙] dos-peixes e-rodar para-o-escuro muito muito e-ele-posto srs-de- חַיִל em-todo as-cidades as cidades: em-juda:');
INSERT INTO verses VALUES (11928, 14, 33, 15, 'e-ele-removeu a Elohim-de o-extranho e-a yhwh de-casa-de yhwh edificar os-araeos que construiu em-monte-de casa-de yhwh e-em-Jerusalém e-ele-jogou fora para-a-cidade');
INSERT INTO verses VALUES (11929, 14, 33, 16, 'a altar-de yhwh yhwh sobre-ele sacrifícios-de paz e-teses E-disse E-disse para-o-servir a yhwh Elohim-de Israel');
INSERT INTO verses VALUES (11930, 14, 33, 17, 'mas ainda o-povo ofre-him na-altar somente para-יהוה אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (11931, 14, 33, 18, 'e-resto-de palavras-de menashe e-sua-oração a seus-elohimes וְדִבְרֵי os-videntes a-ele a-ele yhwh yhwh Elohim-de Israel eis-eles sobre palavras-de reis-de Israel');
INSERT INTO verses VALUES (11932, 14, 33, 19, 'e-sua-oração e-se-prepare a-ele e-todo pecado-suo e-sua-altura edificar que construiu-a neles nos-altar e-estabelecerá os-as-erim e-os-pesilim diante-de ficou-humilde-o sobre כְּתוּבִ֔ים sobre palavras-de visionários-verso-final');
INSERT INTO verses VALUES (11933, 14, 33, 20, 'e-deitou-se מְנַשֶּׁה com seus-pais e-o-enteraram-lá casa-dele e-reinou Amom filho-seu em-lugar-dele');
INSERT INTO verses VALUES (11934, 14, 33, 21, 'filho-de ʿešrīm e dois ano אָמ֣וֹן em-seu-reinado e-duas dois rei em-a-Jerusalém-verso-final');
INSERT INTO verses VALUES (11935, 14, 33, 22, 'E-fez o-mal aos-olhos-de yhwh como fez מְנַשֶּׁ֣ה seu-pai e-para-todo os-pesilim que fez seu-pai pai-dele sacrifício Aomôn e-os-adorou-eles-verso-final');
INSERT INTO verses VALUES (11936, 14, 33, 23, 'e-não ficou-humilde de-diante-de yhwh como-ficou-humilde מְנַשֶּׁ֣ה seu-pai que ele Aomôn multiplicou-se culpa');
INSERT INTO verses VALUES (11937, 14, 33, 24, 'e-conspiraram sobre-ele seus-servos e mataram-no no seu lar:');
INSERT INTO verses VALUES (11938, 14, 33, 25, 'va-yakku'' com a-terra a todo os-que-amarram sobre o-rei Aomôn e reinaram com a-terra a Josias filho-dele em-lugar-dele');
INSERT INTO chapters VALUES (401, 14, 34, 33);
INSERT INTO verses VALUES (11939, 14, 34, 1, 'filho-de oito dois יוashiyahu bemālḵō e-trinta וְאַחַת֙ ano rei em-Jerusalém');
INSERT INTO verses VALUES (11940, 14, 34, 2, 'E-fez o-reto aos-olhos-de yhwh E-andou בְּדַרְכֵי֙ Davi seu-pai e-não apartou direita e-esquerda');
INSERT INTO verses VALUES (11941, 14, 34, 3, 'e-com-oito dois para-seu-reino e-ele ainda-ele o-jovem começou a-procurar לֵאלֹהֵ֖י Davi seu-pai e-com-duas dez ano eu comecei a para-fazer-santo a Judá e Jerusalém de os-altar e-os-ashereis e-os-fsilim e-as-massechot');
INSERT INTO verses VALUES (11942, 14, 34, 4, 'e-natzu diante-dele a mizvoth הַבְּעָלִ֔ים e-os-hammanim que lemahaloh mealehem gedeoh ve-haashereim e-os-idólatras e-as-imagens-de-sacrifício quebrou e-limpou e-jogou-fora sobre face-de a-eles os-sacrificantes para-eles');
INSERT INTO verses VALUES (11943, 14, 34, 5, 'e-os-ossos sacerdotes queimou sobre e-santificou a Judá e-a Jerusalém');
INSERT INTO verses VALUES (11944, 14, 34, 6, 'e-cidade Menasheh e-Efrayim e-Shimeon e-até Naftali ao-redor');
INSERT INTO verses VALUES (11945, 14, 34, 7, 'e-espalhou a os-altar e-a as-asereiros e-os-idólos abaixo para-limpar e-todo os-quentes cortou em-todo terra Israel E-tomou a-Jerusalém');
INSERT INTO verses VALUES (11946, 14, 34, 8, 'e-no-ano oito dez para-reinar-dele para-purificar a-terra e-a-casa enviou a שפן filho-de Azalía e-a Maaséia príncipe-de a-cidade e Yoach yhwh Yoachaz [sem-traducao] [sem-traducao] a casa yhwh Elohim-dele');
INSERT INTO verses VALUES (11947, 14, 34, 9, 'e-vieram a [׀] o-sacerdote a-grande [וַֽיִּתְּנוּ֮] a [הַמּוּבָ֣א] [בֵית־אֱלֹהִים֒] casa-de Elohim que [הַסַּ֜ף] os-levitas [מְנַשֶּׁ֣ה] [וְאֶפְרַ֗יִם] Miyad@ מְנַשֶּׁ֣ה [יִשְׂרָאֵ֔ל] e-de-todo remanescente Israel e-de-todo Judá yhwh Jerusalém:');
INSERT INTO verses VALUES (11948, 14, 34, 10, 'e-eles-se-prepararam sobre mão fez a-obra המשופדים yhwh yhwh ele a-ele os-fazendo da-trabalho que fazem yhwh yhwh para-examinar e fortalecer a-casa');
INSERT INTO verses VALUES (11949, 14, 34, 11, 'e-eles-se-prepararam aos-ferramentas e-aos-tijolos para-comprar pedras-de monumento e-madeiras para-os-amigos e-para-ler a as-bat-tiym que destruiram reis-de Judá');
INSERT INTO verses VALUES (11950, 14, 34, 12, 'e-os-homens fazendo com-fidelidade na-trabalho [וַעֲלֵיהֶ֣ם] [׀] יַ֣חַת [יַ֣חַת] os-levitas de filhos-de Merari [וּזְכַרְיָ֧ה] [וּמְשֻׁלָּ֛ם] de filhos-de as Caleútes [וְהַ֨לְוִיִּ֔ם] e-os-levitas todo ele com-utensílios-de שיר׃');
INSERT INTO verses VALUES (11951, 14, 34, 13, 'e-sobre [הַסַּבָּלִ֗ים] [וּֽמְנַצְּחִים֙] a-todo fez obra [לַעֲבוֹדָ֖ה] [וַעֲבוֹדָ֑ה] [וּמֵֽהַלְוִיִּ֔ם] [סוֹפְרִ֥ים] e-oficiais [וְשׁוֹעֲרִֽים]');
INSERT INTO verses VALUES (11952, 14, 34, 14, '[וּבְהוֹצִיאָ֣ם] a a-prata [בֵּ֣ית] yhwh encontrou [חִלְקִיָּ֣הוּ] chilikiyahu o-sacerdote a livro [sem-traducao] yhwh por-mão-de Moisés');
INSERT INTO verses VALUES (11953, 14, 34, 15, 'e-respondeu [חִלְקִיָּ֗הוּ] E-disse a שַׁפַּ֣ן הסופר סֵ֖פֶר הַתּוֹרָ֛ה מָצָ֖אתִי yhwh E-colocou E-deu [אֶת־הַסֵּ֖פֶר] a o-livro a [sem-traducao]');
INSERT INTO verses VALUES (11954, 14, 34, 16, 'e-trouxe shafan a [אֶל־הַמֶּ֔לֶךְ] a o-rei e-retornou ainda dizendo o-rei palavra dizendo eles que deu por-mão-de servos-teus eles עֹשִׂ֣ים׃');
INSERT INTO verses VALUES (11955, 14, 34, 17, '[וַיַּתִּ֕יכוּ] a o dinheiro que estava na-casa-de yhwh [הַמֻּפְקָדִ֔ים] sobre mão [הַמְּלָאכָֽה] e-sobre mão עשׂאים o-trabalho');
INSERT INTO verses VALUES (11956, 14, 34, 18, 'e contou shafan [הַסּוֹפֵר֙] para-o-rei dizendo סֵפֶר dar a-mim chi-li-ya-hu o-sacerdote e ele chamou nele shafan diante-de o rei');
INSERT INTO verses VALUES (11957, 14, 34, 19, 'e-houve כשמע o-rei a palavras-de a-Torah e rasgou a suas roupas:');
INSERT INTO verses VALUES (11958, 14, 34, 20, 'E-ordenou o-rei a [וְאֶת־אֲחִיקָ֣ם] e-a Aquicam filho-de שָׁפָן e-a [שָׁפָ֣ן] filho-de e-[OBJ] e-את שַׁפַּ֣ן dizendo e-a asaya servo- o-rei para-dizer');
INSERT INTO verses VALUES (11959, 14, 34, 21, 'vovem busquem a yhwh [וּבְעַד֙] e para [בְּיִשְׂרָאֵ֣ל] [וּבִֽיהוּדָ֔ה] [עַל־דִּבְרֵ֥י] sobre palavras-de o-livro que [חֲמַת־יְהוָה֙] porque [נִתְּכָ֣ה] Hamate sobre que [לֹא־שָׁמְר֤וּ] sobre nós sobre yhwh não [כְּכָל־הַכָּת֖וּב] [עַל־הַסֵּ֥פֶר] a palavra yhwh לַעֲשׂוֹת conforme-toda o-escrito sobre o livro a-esta');
INSERT INTO verses VALUES (11960, 14, 34, 22, 'E-andou חִלְקִיָּ֖הוּ e-que o-rei a chulda a nebiya a eshet שלום filho-de filho-de [בֶּן־חַסְרָה֙] guardiao os-vestidos e-ela [יוֹשֶׁ֥בֶת] birushalaim בַּמִּשְׁנֶ֑ה [וַיְדַבְּר֥וּ] para-ela [כָּזֹֽאת׃]');
INSERT INTO verses VALUES (11961, 14, 34, 23, 'E-disse a-eles assim yhwh yhwh Elohim-de Israel אִמְר֣וּ para-o homem que enviou vós para-mim');
INSERT INTO verses VALUES (11962, 14, 34, 24, 'assim disse yhwh eis-me מֵבִ֥יא maldade sobre o-lugar este e-sobre [כָּל־הָאָלוֹת֙] a todo [אֲשֶׁ֣ר] [קָֽרְא֔וּ] sobre ha-sefer que [sem-traducao] diante-de rei Judá');
INSERT INTO verses VALUES (11963, 14, 34, 25, 'debaixo que עֲזָב֗וּנִי le''Elohim outros para-que que-me-ira em-todo [לְמַ֙עַן֙] suas-mãos [בְּכֹ֖ל] minha-ira no-lugar este e-não tikbeh');
INSERT INTO verses VALUES (11964, 14, 34, 26, 'e-a rei Judá aquele-q-dispõe vos l-i-d-r-o-sh em-יהוה assim a-ele a-ela assim yhwh yhwh Elohim-de Israel as-palavras que ouvirás');
INSERT INTO verses VALUES (11965, 14, 34, 27, 'porque suave- לבבך ותינעה de-diante-de Elohim [בְּשָׁמְעֲךָ֤] a suas palavras sobre o-lugar este e-sobre [וַתִּקְרַ֥ע] [אֶת־בְּגָדֶ֖יךָ] diante-de-mim [לְפָנָ֑י] a [שָׁמַ֖עְתִּי] [נְאֻם־יְהוָֽה] diante-de-mim e-também eu ouvi oráculo-de yhwh');
INSERT INTO verses VALUES (11966, 14, 34, 28, 'eis-me [אֹֽסִפְךָ֜] a [וְנֶאֱסַפְתָּ֣] [אֶל־קִבְרֹתֶיךָ֮] a [וְלֹא־תִרְאֶ֣ינָה] [עֵינֶ֔יךָ] e-não [הָֽרָעָ֔ה] [אֲשֶׁ֨ר] em-todo [מֵבִ֛יא] que eu [וְעַל־יֹשְׁבָ֑יו] sobre o-lugar este e-sobre a palavra');
INSERT INTO verses VALUES (11967, 14, 34, 29, 'e-enviou o-rei e-ajuntou a todo anciãos-de יְהוּדָה Jerusalém:');
INSERT INTO verses VALUES (11968, 14, 34, 30, 'e-subiu o-rei casa-de yhwh e-todo homem Judá e-habitantes-de Jerusalém e-os-sacerdotes e os levitas e-todo E-chamou [בְאָזְנֵיהֶ֗ם] e-até pequeno E-chamou em suas orelhas a yhwh palavras-de livro a-aliança yhwh casa yhwh');
INSERT INTO verses VALUES (11969, 14, 34, 31, '[וַיַּעֲמֹ֨ד] o-rei sobre [וַיִּכְרֹ֣ת] e-ele-cortou a yhwh diante-de yhwh yhwh depois-de yhwh [וְעֵֽדְוֺתָ֣יו] a mandamentos-seus [וּבְכָל־נַפְשׁ֑וֹ] [לַעֲשׂוֹת֙] em-todo [הַבְּרִ֔ית] e-em-todo sua-alma para-fazer a palavras-de a-aliança [sem-traducao] sobre o livro a-esta');
INSERT INTO verses VALUES (11970, 14, 34, 32, '[וַיַּעֲמֵ֕ד] a todo [בִירוּשָׁלַ֖͏ִם] בירושלם e-Benjamim e fizeram habitantes-de Jerusalém conforme-aliança-de Elohim Elohim-de seus pais:');
INSERT INTO verses VALUES (11971, 14, 34, 33, 'e-retirou [יֹֽאשִׁיָּ֜הוּ] a todo [אֲשֶׁ֣ר] de-todo [יִשְׂרָאֵל֒] que aos-filhos-de Israel [בְּיִשְׂרָאֵ֔ל] a todo [אֱלֹהֵיהֶ֑ם] em-Israel não a yhwh yhwh todo [אֲבוֹתֵיהֶֽם׃] não [sem-traducao] [sem-traducao] yhwh Elohim-de seus pais:');
INSERT INTO chapters VALUES (402, 14, 35, 27);
INSERT INTO verses VALUES (11972, 14, 35, 1, 'E-fez [יֹאשִׁיָּ֧הוּ] [בִֽירוּשָׁלַ֛͏ִם] Pésach a-yhwh wa-ya-shé-kha-tú o-passo בְּאַרְבָּעָ֥ה dez para-o-mes o-primeiro:');
INSERT INTO verses VALUES (11973, 14, 35, 2, '[וַיַּעֲמֵ֥ד] os-sacerdotes sobre [וַֽיְחַזְּקֵ֔ם] [לַעֲבוֹדַ֖ת] [בֵּ֥ית] yhwh yhwh');
INSERT INTO verses VALUES (11974, 14, 35, 3, 'E-disse [לַ֠לְוִיִּם] para-todo Israel [לְכָל־יִשְׂרָאֵ֜ל] a-yhwh dai a arca-de a-santidade [אֲשֶׁ֨ר] edificar [שְׁלֹמֹ֤ה] שְׁלֹמֹה filho-de Davi rei Israel não-há para-vós profecia [אֶת־יְהוָ֣ה] agora e-[OBJ] a yhwh Elohim-vosso e-a seu-povo Israel');
INSERT INTO verses VALUES (11975, 14, 35, 4, '[וְהָכִ֥ונוּ] para-a-casa-de pais-vossos [בִּכְתָ֗ב] [דָּוִיד֙] Davi rei Israel [שְׁלֹמֹ֥ה] Salomão filho-dele');
INSERT INTO verses VALUES (11976, 14, 35, 5, '[וְעִמְד֣וּ] [בַקֹּ֗דֶשׁ] [לִפְלֻגּוֹת֙] casa os-pais [לַאֲחֵיכֶ֖ם] filhos-de o-povo [וַחֲלֻקַּ֥ת] casa-de pai [sem-traducao]');
INSERT INTO verses VALUES (11977, 14, 35, 6, '[וְשַׁחֲט֖וּ] o-pascha [וְהִתְקַדְּשׁוּ֙] [וְהָכִ֣ינוּ] [לַאֲחֵיכֶ֔ם] para-fazer por a palavra- yhwh por-mão-de Moisés');
INSERT INTO verses VALUES (11978, 14, 35, 7, 'e-ele-levantou יוashiyahu [לִבְנֵ֪י] [הָעָ֟ם] [צֹ֞אן] cordeiros e-filhos-de [הַכֹּ֣ל] o-todo [לְכָל־הַנִּמְצָ֗א] para-todo [שְׁלֹשִׁ֣ים] [אֶ֔לֶף] trinta mil e-vacas Estas milhares estes [sem-traducao] o rei');
INSERT INTO verses VALUES (11979, 14, 35, 8, '[וְשָׂרָ֞יו] [לִנְדָבָ֥ה] para-o-povo [לַכֹּהֲנִ֥ים] [וְלַלְוִיִּ֖ם] [הֵרִ֑ימוּ] [חִלְקִיָּ֨ה] [וּזְכַרְיָ֜הוּ] [וִֽיחִיאֵ֗ל] [נְגִידֵי֙] casa o-Elohim [לַכֹּהֲנִ֞ים] deram [לַפְּסָחִ֗ים] [אַלְפַּ֙יִם֙] e-seis centenas e-vacas três centenas');
INSERT INTO verses VALUES (11980, 14, 35, 9, '[*וכונניהו] [**וְ֠כָֽנַנְיָהוּ] irmãos-seus [וּנְתַנְאֵ֜ל] [אֶחָ֗יו] [וַחֲשַׁבְיָ֧הוּ] príncipes-de os-levitas [שָׂרֵ֣י] [הַלְוִיִּ֑ם] [הֵרִ֨ימוּ] cinco-de milhares e-vacas cinco centenas');
INSERT INTO verses VALUES (11981, 14, 35, 10, 'e-a ela se estabeleceu [הָעֲבוֹדָ֑ה] [וַיַּֽעַמְד֨וּ] os-sacerdotes sobre [וְהַלְוִיִּ֥ם] [עַל־מַחְלְקוֹתָ֖ם] sobre [הַמֶּֽלֶךְ] [sem-traducao] o rei');
INSERT INTO verses VALUES (11982, 14, 35, 11, 'e-sacrificaram o-pascha wa-ya-zé-ré-qú aos-sacerdotes dos seus olhos e-os-levitas [מַפְשִׁיטִֽים]');
INSERT INTO verses VALUES (11983, 14, 35, 12, '[וַיָּסִ֨ירוּ] a-sacrifício [לְ֠תִתָּם] [לְמִפְלַגּ֤וֹת] para-a-casa-de avós aos-filhos-de o-povo [לַיהוָ֔ה] a-yhwh conforme-o-escrito בְּסֵ֣פֶר Moisés e-assim [sem-traducao]');
INSERT INTO verses VALUES (11984, 14, 35, 13, '[וַֽיְבַשְּׁל֥וּ] [הַפֶּ֛סַח] com-fogo como-o-juízo [וְהַקֳּדָשִׁ֣ים] [בִּשְּׁל֗וּ] [בַּסִּיר֤וֹת] [וּבַדְּוָדִים֙] [וּבַצֵּ֣לָח֔וֹת] [וַיָּרִ֖יצוּ] para-todo filhos-de o-povo');
INSERT INTO verses VALUES (11985, 14, 35, 14, 'e-depois [הֵכִ֤ינוּ] a-eles [וְלַכֹּ֣הֲנִ֔ים] que aos-sacerdotes filhos-de Arão [בְּהַֽעֲל֛וֹת] [הָעוֹלָ֥ה] [וְהַחֲלָבִ֖ים] até noite [הֵכִ֣ינוּ] a-eles a-eles [בְּנֵ֥י] filhos-de Aharon');
INSERT INTO verses VALUES (11986, 14, 35, 15, '[וְהַמְשֹֽׁרֲרִ֨ים] filhos-de [עַל־מַעֲמָדָ֗ם] sobre [דָּוִיד֙] [וְאָסָ֞ף] Davi [וִֽידֻתוּן֙] [חוֹזֵ֣ה] [הַמֶּ֔לֶךְ] [וְהַשֹּׁעֲרִ֖ים] o-rei [וָשָׁ֑עַר] para-portão-de a-eles não-há de-cima-de [עֲבֹֽדָתָ֔ם] de-sobre [הַלְוִיִּ֖ם] porque a-eles os-levitas [sem-traducao] para-eles');
INSERT INTO verses VALUES (11987, 14, 35, 16, '[וַ֠תִּכּוֹן] todo yhwh no-dia no-dia o-aquele para fazer o-passo והעלות sobre sobre yhwh yhwh [הַמֶּ֥לֶךְ] o-rei [sem-traducao]');
INSERT INTO verses VALUES (11988, 14, 35, 17, 'e-fizeram filhos-de Israel [אֶת־הַפֶּ֖סַח] a o-páscoa em-o-tempo aquela e-a festa-de a matzot sete dias');
INSERT INTO verses VALUES (11989, 14, 35, 18, 'e-não [פֶ֤סַח] [כָּמֹ֙הוּ֙] [בְּיִשְׂרָאֵ֔ל] em-Israel [שְׁמוּאֵ֣ל] Samuel o-profeta e-todo reis-de יִשְׂרָאֵ֣ל ׀ não [אֲשֶׁר־עָשָׂ֣ה] pesach que fez [וְכָל־יְהוּדָה֙] e-os-sacerdotes e-os-levitas e-todo Judá [sem-traducao] [sem-traducao] [sem-traducao] Jerusalém');
INSERT INTO verses VALUES (11990, 14, 35, 19, '[בִּשְׁמוֹנֶ֤ה] dez ano para-reinado יוashiyahu [נַעֲשָׂ֖ה] [הַפֶּ֥סַח] a-esta');
INSERT INTO verses VALUES (11991, 14, 35, 20, 'depois-de todo esta que [יֹֽאשִׁיָּ֙הוּ֙] [אֶת־הַבַּ֔יִת] subir a-casa [מֶֽלֶךְ־מִצְרַ֛יִם] [לְהִלָּחֵ֥ם] rei-de Egito para-lutar [לִקְרָאת֖וֹ] sobre p-rat e-ele-saiu para-o-encontro-dele [sem-traducao]');
INSERT INTO verses VALUES (11992, 14, 35, 21, 'e-enviou a-ele [מַלְאָכִ֣ים] [׀] dizendo לִּ֨י [מַה־לִּ֨י] rei Judá não [לֹא־עָלֶ֨יךָ] tu o-dia que a casa [וֵאלֹהִ֖ים] disse disse [חֲדַל־לְךָ֛] deixou de para-ti [וְאַל־יַשְׁחִיתֶֽךָ] que com-mim e-a [sem-traducao]');
INSERT INTO verses VALUES (11993, 14, 35, 22, 'e-não [יֹאשִׁיָּ֨הוּ] [פָנָ֜יו] nós que porque [הִתְחַפֵּ֔שׂ] nele [שָׁמַ֛ע] e-não ouviu a palavras-de [וַיָּבֹ֕א] de-boca-de Elohim E-veio para-lutar [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (11994, 14, 35, 23, '[וַיֹּרוּ֙] [הַיֹּרִ֔ים] ao-rei [יֹאשִׁיָּ֑הוּ] E-disse o-rei [לַעֲבָדָיו֙] [הַעֲבִיר֔וּנִי] que [הָחֳלֵ֖יתִי] muito');
INSERT INTO verses VALUES (11995, 14, 35, 24, '[וַיַּֽעֲבִירֻ֨הוּ] [עֲבָדָ֜יו] de a-carruagem sobre sobre carros o segundo que para-ele [וַיָּ֕מָת] Jerusalém E-morreu e-ele-foi-sepultado [וְכָל־יְהוּדָה֙] pais-seus e-todo Judá e Jerusalém [sem-traducao] sobre [sem-traducao]');
INSERT INTO verses VALUES (11996, 14, 35, 25, '[וַיְקוֹנֵ֣ן] ירמיהוּ֮ sobre [וַיֹּאמְר֣וּ] e-disseram todo [וְ֠הַשָּׁרוֹת] [בְּקִינ֨וֹתֵיהֶ֤ם] [עַל־יֹאשִׁיָּ֙הוּ֙] sobre יֹאשִׁיָּ֙הוּ֙ até o-dia [וְהִנָּ֥ם] [כְּתוּבִ֖ים] sobre Israel [sem-traducao] [sem-traducao] sobre [sem-traducao]');
INSERT INTO verses VALUES (11997, 14, 35, 26, 'e-resto-de palavras-de יֹאשִׁיָּ֖הוּ [וַחֲסָדָ֑יו] conforme-o-escrito בְּתוֹרַ֥ת yhwh');
INSERT INTO verses VALUES (11998, 14, 35, 27, '[וּדְבָרָ֕יו] הָרִאשֹׁנִ֖ים וְהָאַחֲרֹנִ֑ים eis-os כְּתוּבִ֔ים sobre livro reis- Israel e-Judá');
INSERT INTO chapters VALUES (403, 14, 36, 23);
INSERT INTO verses VALUES (11999, 14, 36, 1, 'e-eles-levaram com a-terra a yoãoaz filho-de יוashiyahu [sem-traducao] debaixo-de pai-dele em-Jerusalém');
INSERT INTO verses VALUES (12000, 14, 36, 2, 'filho-de [וְעֶשְׂרִ֛ים] e-vinte ano [בְּמָלְכ֑וֹ] em-seu-reinado e-três meses rei em-Jerusalém');
INSERT INTO verses VALUES (12001, 14, 36, 3, '[וַיְסִירֵ֥הוּ] rei-de Egito בִּֽירוּשָׁלָ֑͏ִם [אֶת־הָאָ֔רֶץ] a a-terra cem ouro prata ouro ouro');
INSERT INTO verses VALUES (12002, 14, 36, 4, '[וַיַּמְלֵ֨ךְ] rei-de Egito a Eliaquim o-seu-irmão sobre Judá e Jerusalém vayassab a tomou Jeoaquim e-a [מִצְרָֽיְמָה׃] ele tomou [sem-traducao] e ele o trouxe de Egito:');
INSERT INTO verses VALUES (12003, 14, 36, 5, 'filho-de vinte e-cinco ano Joiás no seu reinado e-uma dez ano rei em-Jerusalém E-fez [בְּעֵינֵ֖י] yhwh yhwh Elohim-dele');
INSERT INTO verses VALUES (12004, 14, 36, 6, 'sobre-ele subir Nabucodonosor rei Babilônia [וַיַּֽאַסְרֵ֙הוּ֙] [בַּֽנְחֻשְׁתַּ֔יִם] [לְהֹלִיכ֖וֹ] Bavelah;');
INSERT INTO verses VALUES (12005, 14, 36, 7, '[וּמִכְּלֵי֙] casa yhwh trouxe Nabucodonosor para-Babel [וַיִּתְּנֵ֥ם] [בְּהֵיכָל֖וֹ] [בְּבָבֶֽל]');
INSERT INTO verses VALUES (12006, 14, 36, 8, 'e-remanescente palavras [יְהֽוֹיָקִ֜ים] [וְתֹֽעֲבֹתָ֤יו] que fez [עָלָ֔יו] sobre-ele eis-os escritos sobre livro reis-de Israel e Judá e-reinou Jehoquia filho-seu em-lugar-dele');
INSERT INTO verses VALUES (12007, 14, 36, 9, 'filho-de [שָׁנִים֙] dois [בְּמָלְכ֔וֹ] no seu reinado [חֳדָשִׁים֙] [וַעֲשֶׂ֣רֶת] [יָמִ֔ים] dias rei em-Jerusalém E-fez o-mal yhwh yhwh');
INSERT INTO verses VALUES (12008, 14, 36, 10, '[וְלִתְשׁוּבַ֣ת] o ano enviou o-rei [נְבֽוּכַדְנֶאצַ֔[t]ר] [וַיְבִאֵ֣הוּ] [בָבֶ֔לָה] com kléi- [בֵּית־יְהוָ֑ה] casa-de yhwh [אָחִ֔יו] a tsidqiyahu irmão-seu sobre יְהוּדָה [sem-traducao]');
INSERT INTO verses VALUES (12009, 14, 36, 11, 'filho-de ʿešrīm [שָׁנָ֖ה] ano tsidqiyahu bemālḵō e-uma dez ano rei em-Jerusalém');
INSERT INTO verses VALUES (12010, 14, 36, 12, 'E-fez [הָרַ֔ע] em-olhos-de yhwh Elohim-dele não [נִכְנַ֗ע] [מִלִּפְנֵ֛י] Jeremias o-profeta מפי yhwh');
INSERT INTO verses VALUES (12011, 14, 36, 13, 'e-tambem [בַּמֶּ֤לֶךְ] Nebucodnasor [מָרָ֔ד] que [הִשְׁבִּיע֖וֹ] em Elohim [וַיֶּ֤קֶשׁ] a [וַיְאַמֵּ֣ץ] [אֶת־לְבָב֔וֹ] a coração-dele [Elohim] a yhwh Elohim-de Israel');
INSERT INTO verses VALUES (12012, 14, 36, 14, 'também todo príncipes-de os-sacerdotes e-o-povo hirbū [כְּכֹ֖ל] em-alto כְּכֹ֖ל [וַֽיְטַמְּאוּ֙] as-nações yhwh a casa yhwh que [sem-traducao] em-Jerusalém');
INSERT INTO verses VALUES (12013, 14, 36, 15, '[וַיִּשְׁלַ֡ח] yhwh Elohim-de [אֲבוֹתֵיהֶ֧ם] sobre-eles na-mão-de [מַלְאָכָ֖יו] o-manhã [וְשָׁל֑וֹחַ] porque [עַל־עַמּ֖וֹ] sobre que e-sobre [sem-traducao]');
INSERT INTO verses VALUES (12014, 14, 36, 16, 'e-eram [מַלְעִבִים֙] [בְּמַלְאֲכֵ֣י] o-Elohim [וּבוֹזִ֣ים] davarav [וּמִֽתַּעְתְּעִ֖ים] [בִּנְבִאָ֑יו] até [עֲל֧וֹת] Hamate yhwh [עַד־לְאֵ֥ין] até para-nada-- cura--');
INSERT INTO verses VALUES (12015, 14, 36, 17, 'e-subiu sobre-eles a rei e-matou [וַיַּהֲרֹ֨ג] pela espada na-casa-de [בְּבֵ֣ית] e-não [וְלֹ֥א] sobre jovem [וּבְתוּלָ֖ה] velho [וְיָשֵׁ֑שׁ] [הַכֹּ֖ל] dar em-mão-sua');
INSERT INTO verses VALUES (12016, 14, 36, 18, 'e-tudo [כְּלֵ֞י] casa o-Elohim os-grandes [וְהַקְּטַנִּ֔ים] [וְאֹֽצְרוֹת֙] casa yhwh [וְאֹצְר֥וֹת] o-rei [וְשָׂרָ֑יו] [הַכֹּ֖ל] trouxe [בָבֶֽל]');
INSERT INTO verses VALUES (12017, 14, 36, 19, '[וַֽיִּשְׂרְפוּ֙] a casa o-Elohim [OBJ] a muro-de Jerusalém e-todo [בָאֵ֔שׁ] [וְכָל־כְּלֵ֥י] em-a-chama e-todo instrumentos-de [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (12018, 14, 36, 20, '[וַיֶּ֛גֶל] [הַשְּׁאֵרִ֥ית] de a-espada a Babilônia e-eles-foram para-ele e-para-seus-filhos [פָּרָֽס] até rei מלכות Pérsia');
INSERT INTO verses VALUES (12019, 14, 36, 21, '[לְמַלֹּ֤אות] palavra-de yhwh [יִרְמְיָ֔הוּ] Jeremias a-terra [אֶת־שַׁבְּתוֹתֶ֑יהָ] a-terra a [שָׁבָ֔תָה] todo [שִׁבְעִ֥ים] [שָׁנָֽה׃]');
INSERT INTO verses VALUES (12020, 14, 36, 22, 'e-em-ano-de uma para-Ciro rei Pérsia para-completar palavra-de yhwh בְּפִ֣י Jeremias yhwh yhwh a espírito [וַיַּֽעֲבֶר־קוֹל֙] rei-de Pérsia dizendo voz em-todo reino-dele e-também em-escrito para-dizer');
INSERT INTO verses VALUES (12021, 14, 36, 23, 'assim disse [׀] rei para-Paras todo a-terra dar deu yhwh yhwh Elohim-de os-céus e-ele visitou sobre-mim para-construir- a-ele casa birushalaim que yhwh quem em-vós de-todo povo-dele yhwh Elohim disse [sem-traducao]');
INSERT INTO books VALUES (15, 'EZR', 'Esdras', 'AT', 10);
INSERT INTO chapters VALUES (404, 15, 1, 11);
INSERT INTO verses VALUES (12022, 15, 1, 1, 'e-em-ano-de uma para-Ciro rei Pérsia para-completar palavra-de yhwh de-boca-de Jeremias yhwh yhwh a espírito Ciro rei-de Pérsia dizendo voz em-todo reino-dele e-também em-escrito para-dizer');
INSERT INTO verses VALUES (12023, 15, 1, 2, 'assim disse Ciro rei Pérsia todo reinos-de a-terra dar para-mim yhwh Elohim-de os-céus e-ele visitou sobre-mim para-construir- para-ele casa birushalaim que em-Judá');
INSERT INTO verses VALUES (12024, 15, 1, 3, 'quem- em-vós haja povo-dele seja Elohim-dele com-ele e-suba para-Jerusalém que em-Judá yhwh a casa ele Elohim-de Israel ele Elohim que em-Jerusalém');
INSERT INTO verses VALUES (12025, 15, 1, 4, 'e-todo o-restante de-todo ele que ele habita nome levantem-no homens-de lugar-dele com-prata e-com-ouro e-com-bens e-com-gado com a-oferta-voluntária segundo-casa-de Elohim que em-Jerusalém');
INSERT INTO verses VALUES (12026, 15, 1, 5, 'e-levantaram-se cabeças-de os-pais para-Judá e-Benjamim e-os-sacerdotes e-os-levitas a-todo despertou o-Elohim a espírito-dele para-subir para-construir yhwh casa yhwh que em-Jerusalém');
INSERT INTO verses VALUES (12027, 15, 1, 6, 'e-todo ao-redor-deles fortaleceram em-mãos-deles com-utensílios-de prata e-sobre-os-animais com-bens e-com-o-gado e-com-as-coisas-preciosas além-de sobre todo ofereceu-voluntariamente');
INSERT INTO verses VALUES (12028, 15, 1, 7, 'e-o-rei Ciro tirou a instrumentos-de casa-de yhwh que tirou Nabucodonosor de-Jerusalém e-colocou-os em-casa-de Elohim-dele');
INSERT INTO verses VALUES (12029, 15, 1, 8, 'e-tirou-os Ciro rei Pérsia sobre mão Mitredate o-tesoureiro e-contou-os para-Sesbazar o-príncipe para-Judá');
INSERT INTO verses VALUES (12030, 15, 1, 9, 'e-estes número-deles bacias-de ouro trinta bacias-de prata mil mudando nove e-vinte');
INSERT INTO verses VALUES (12031, 15, 1, 10, 'tigelas-de ouro trinta tigelas-de prata segundas quatro centenas e-dez vasos outros mil');
INSERT INTO verses VALUES (12032, 15, 1, 11, 'todo vasos para-o-ouro e-para-a-prata cinco-de dois-mil e-quatro centenas o-tudo fez-subir Sesbazar povo com-o-subir-de o-exílio de-Babilônia');
INSERT INTO chapters VALUES (405, 15, 2, 70);
INSERT INTO verses VALUES (12033, 15, 2, 1, 'e-estes filhos-de a-província os-que-sobem de-cativeiro-de o-exílio que exílio rei-de Babel para-Babel e-retornaram para Jerusalém e-Judá homem para-cidade-sua');
INSERT INTO verses VALUES (12034, 15, 2, 2, 'que vieram com Zorobabel Jesua Neemias Seraías Reelaías Mardoqueu Bilsã Mispar Bigvai Reum Baaná número homens-de povo Israel');
INSERT INTO verses VALUES (12035, 15, 2, 3, 'filhos-de Parós dois-mil cem setenta e-dois');
INSERT INTO verses VALUES (12036, 15, 2, 4, 'filhos-de Sefatias três centenas setenta e-dois');
INSERT INTO verses VALUES (12037, 15, 2, 5, 'filhos-de Ara sete centenas cinco e-setenta');
INSERT INTO verses VALUES (12038, 15, 2, 6, 'filhos-de Paate Moabe para-filhos-de Jesua Joabe dois-mil oito centenas e-doze dez');
