INSERT INTO verses VALUES (12057, 15, 2, 25, 'filhos-de Quiriate Arim Quefira e-Beerote sete centenas e-quarenta e-três');
INSERT INTO verses VALUES (12058, 15, 2, 26, 'filhos-de a-Ramá e-Geba seis centenas vinte e-um');
