INSERT INTO verses VALUES (12086, 15, 2, 54, 'filhos-de Neziah filhos-de Hatipha');
INSERT INTO verses VALUES (12087, 15, 2, 55, 'filhos-de servos-de Shelomoh filhos-de Sotai filhos-de a-Sophereth filhos-de Peruda');
INSERT INTO verses VALUES (12088, 15, 2, 56, 'filhos-de Jaalah filhos-de Darkon filhos-de Giddel');
INSERT INTO verses VALUES (12089, 15, 2, 57, 'filhos-de Shephatiah filhos-de Hattil filhos-de Pokereth a-Zebaim filhos-de Ami');
INSERT INTO verses VALUES (12090, 15, 2, 58, 'todo o-netinins e-filhos-de servos-de Shelomoh três centenas noventa e-dois');
INSERT INTO verses VALUES (12091, 15, 2, 59, 'e-estes o-subindo de-Tel Melah Tel Harsha querubim Addan disse e-não puderam para-declarar casa-de pais-deles e-descendência-deles mãe eles eles');
INSERT INTO verses VALUES (12092, 15, 2, 60, 'filhos-de Delaiah filhos-de Tobiah filhos-de Nekoda seis centenas cinquenta e-dois');
INSERT INTO verses VALUES (12093, 15, 2, 61, 'e-de-filhos-de os-sacerdotes filhos-de Hobaiah filhos-de o-Koz filhos-de Barzillai que tomou de-filhas-de Barzillai o-גִּלְעָדִי mulher E-chamou sobre nome-deles');
INSERT INTO verses VALUES (12094, 15, 2, 62, 'Estas procuraram escrito-deles o-genealogias e-não foram-encontrados e-foram-excluídos de o-sacerdócio');
INSERT INTO verses VALUES (12095, 15, 2, 63, 'E-disse o-governador a-eles que não eles-comerão de-santidade até até ficou-em-pé sacerdote para-Urim e-para-Tumim');
INSERT INTO verses VALUES (12096, 15, 2, 64, 'todo a-congregação como-um quatro miríade dois-mil três- centenas sessenta');
INSERT INTO verses VALUES (12097, 15, 2, 65, 'de-além-de servos-de-eles e-servas-de-eles Estas sete-de milhares três centenas trinta e-sete e-para-eles cantores e-cantoras duzentos');
INSERT INTO verses VALUES (12098, 15, 2, 66, 'cavalos-de-eles sete centenas trinta e-seis mulas-de-eles duzentos quarenta e-cinco');
INSERT INTO verses VALUES (12099, 15, 2, 67, 'camelos-de-eles quatro centenas trinta e-cinco jumentos seis-de milhares sete centenas e-vinte');
INSERT INTO verses VALUES (12100, 15, 2, 68, 'e-de-chefes-de os-pais em-vir-de-eles segundo-casa-de yhwh que em-Jerusalém eles-se-ofereceram-voluntariamente para-casa-de הָֽאֱלֹהִ֔ים para-levantar-o sobre lugar-de-o');
INSERT INTO verses VALUES (12101, 15, 2, 69, 'conforme-força-de-eles eles-deram para-tesouro-de a-obra ouro dracmas seis-de miríades e-mil e-prata minas cinco-de milhares e-túnicas-de sacerdotes cem');
INSERT INTO verses VALUES (12102, 15, 2, 70, 'e-habitaram os-sacerdotes e-os-levitas e-de o-povo e-os-cantores e-os-porteiros e-os-netinins em-cidades-de-eles e-todo Israel em-cidades-de-eles');
INSERT INTO chapters VALUES (406, 15, 3, 13);
INSERT INTO verses VALUES (12103, 15, 3, 1, 'e-chegou o-mês o-sétimo e-filhos-de Israel em-cidades e-eles-se-reuniram o-povo como-homem um um Jerusalém');
INSERT INTO verses VALUES (12104, 15, 3, 2, 'E-levantou Jeshua filho-de Jozadaque e-irmãos-de-o os-sacerdotes e-Zorobabel filho-de Salatiel e-irmãos-de-o e-eles-construíram a altar-de Elohim-de Israel para-oferecer sobre-ele holocaustos conforme-o-escrito em-Lei-de Moisés homem Elohim');
INSERT INTO verses VALUES (12105, 15, 3, 3, 'e-eles-estabeleceram o-altar sobre que porque em-terror sobre-eles de-povos-de as-terras sobre-o holocaustos para-יהוה holocaustos para-a-manhã e-para-a-tarde');
INSERT INTO verses VALUES (12106, 15, 3, 4, 'e-ele-fizeram a festa-de as-cabanas conforme-o-escrito dia dia em-dia-de em-número conforme-ordenança-de palavra-de dia em-dia-de-o');
INSERT INTO verses VALUES (12107, 15, 3, 5, 'e-depois-assim holocausto-de contínuo e-para-as-luas-novas e-para-todo- yhwh yhwh os-santificados e-para-todo de-oferece-voluntariamente oferta-voluntária para-יהוה');
INSERT INTO verses VALUES (12108, 15, 3, 6, 'de-dia um para-o-mês o-sétimo eles-começaram para-oferecer holocaustos para-יהוה e-templo-de yhwh não foi-fundado');
INSERT INTO verses VALUES (12109, 15, 3, 7, 'e-eles-deram prata para-os-cortadores e-para-os-artífices e-comida e-bebida e-óleo para-os-sidônios e-para-os-tírios para-trazer madeiras-de cedros de de-o-Líbano a mar Jope como-permissão-de Ciro rei-de Pérsia sobre-eles');
INSERT INTO verses VALUES (12110, 15, 3, 8, 'e-no-ano a-segunda de-vinda-deles a casa הָֽאֱלֹהִים a-Jerusalém no-mês o-segundo começaram Zorobabel filho-de Sealtiel e-Jesua filho-de Jozadaque e-restante-de irmãos-deles os-sacerdotes e-os-levitas e-todo os-que-vêm de-o-cativeiro Jerusalém e-estabeleceram a os-levitas de-filho-de vinte ano e-para-cima para-supervisionar sobre obra-de casa-de yhwh');
INSERT INTO verses VALUES (12111, 15, 3, 9, 'e-ficou-em-pé Jesua filhos-seus e-irmãos-seus Cadmiel e-filhos-seus filhos-de יְהוּדָה como-um para-supervisionar sobre fez a-obra em-casa-de o-Elohim filhos-de Henadade filhos-deles e-irmãos-deles os-levitas');
INSERT INTO verses VALUES (12112, 15, 3, 10, 'e-fundaram os-construtores a yhwh yhwh e-estabeleceram os-sacerdotes vestidos com-trombetas e-os-levitas filhos-de Asafe com-címbalos para-louvar a yhwh sobre mãos-de Davi rei-de Israel');
INSERT INTO verses VALUES (12113, 15, 3, 11, 'e responderam com-louvor e-com-ação-de-graças para-יהוה que bom porque para-sempre misericórdia-sua sobre Israel e-todo o-povo gritaram grito sobre em-louvor para-יהוה sobre foi-fundado casa-de yhwh');
INSERT INTO verses VALUES (12114, 15, 3, 12, 'e-muitos de-os-sacerdotes e-os-levitas e-cabeças-de os-pais os-anciãos que viram a a-casa a-primeira em-ser-fundado-ele este a-casa em-olhos-deles chorando com-voz grande e-muitos com-grito com-alegria voz voz');
INSERT INTO verses VALUES (12115, 15, 3, 13, 'e-não o povo reconhecendo voz grito-de a-alegria à-voz-de choro-de o-povo que o povo gritando grito grande e-a-voz foi-ouvida até para-longe');
INSERT INTO chapters VALUES (407, 15, 4, 24);
INSERT INTO verses VALUES (12116, 15, 4, 1, 'e-ouviram inimigos-de יְהוּדָה e-Benjamim porque filhos-de o-exílio construindo templo para-יהוה Elohim-de Israel');
INSERT INTO verses VALUES (12117, 15, 4, 2, 'e-aproximaram-se a Zorobabel e-a cabeças-de a-eles e-disseram para-eles que com-vocês porque como-vocês buscamos para-אֱלֹהִים-de-vocês nós sacrificando desde-dias-de Esar Hadom rei Assur o-que-fez-subir a-nós aqui');
INSERT INTO verses VALUES (12118, 15, 4, 3, 'E-disse a-eles Zorobabel e-Jeshua e-restante-de cabeças-de os-pais para-Israel não para-vós e-para-nós para-construir casa que porque nós juntos construiremos para-יהוה Elohim-de Israel como-que ordenou-nos o-rei Ciro rei-de Pérsia');
INSERT INTO verses VALUES (12119, 15, 4, 4, 'e-houve com a-terra enfraquecendo mãos-de com Judá eles para-construir');
INSERT INTO verses VALUES (12120, 15, 4, 5, 'e-contratando sobre-eles conselheiros para-frustrar conselho-deles todo dias-de Ciro rei Pérsia e-até reino-de Dario rei-de Pérsia');
INSERT INTO verses VALUES (12121, 15, 4, 6, 'e-em-reino-de Assuero no-início-de reino-dele escreveram acusação sobre habitantes-de יְהוּדָה Jerusalém:');
INSERT INTO verses VALUES (12122, 15, 4, 7, 'e-em-dias-de Artaxerxes escreveu Bislam Mitredat Tabeel e-restante-de sobre rei Pérsia e-escrita-de a-carta escrito aramaico e-traduzido aramaico');
INSERT INTO verses VALUES (12123, 15, 4, 8, 'Reum senhor-de decreto e-Simsai o-escriba escreveram carta uma sobre Jerusalém para-Artaxerxes o-rei assim');
INSERT INTO verses VALUES (12124, 15, 4, 9, 'então Reum senhor-de decreto e-Simsai o-escriba e-restante-de companheiros-deles os-dinitas e-os-afarsatquitas os-tarfelitas os-afarsitas os-babilônios os-susanquitas os-elamitas');
INSERT INTO verses VALUES (12125, 15, 4, 10, 'e-restante-de as-nações que deportou Asnapar o-grande e-o-honrado e-estabeleceu eles em-cidade-de que Samaria e-restante-de além-de o-rio e-agora');
INSERT INTO verses VALUES (12126, 15, 4, 11, 'esta cópia a-carta que enviaram sobre-ele sobre Artaxerxes o-rei servos-teus homens-de além-de o-rio e-agora');
INSERT INTO verses VALUES (12127, 15, 4, 12, 'conhecido seja ao-rei que os-judeus que subiram de de-junto-ti sobre-nós vieram a-Jerusalém a-cidade a-rebelde edificando e-os-fundamentos terminaram');
INSERT INTO verses VALUES (12128, 15, 4, 13, 'agora conhecido seja ao-rei que eis a-cidade aquela seja-edificada e-os-muros sejam-terminados tributo imposto e-taxa não darão e-finalmente reis prejudicarás');
INSERT INTO verses VALUES (12129, 15, 4, 14, 'agora todo porque que sal-de o-palácio comemos e-desonra-de o-rei não para-nós ver sobre isto enviamos e-fizemos-saber ao-rei');
INSERT INTO verses VALUES (12130, 15, 4, 15, 'que seja-investigado no-livro-de os-registros que pais-teus e-acharás no-livro-de os-registros e-saberás que a-cidade aquela cidade rebelde e-prejudicial a-reis e-províncias e-rebelião fazendo em-meio-dela de dias-de eternidade sobre isto a-cidade por-isso foi-destruída');
INSERT INTO verses VALUES (12131, 15, 4, 16, 'fazemos-saber nós ao-rei que eis a-cidade aquela seja-edificada e-os-muros sejam-terminados diante-de isto parte do-além-de o-rio não comigo para-ti');
INSERT INTO verses VALUES (12132, 15, 4, 17, 'a-palavra enviou o-rei sobre Reum senhor-de decreto e-Simsai o-escriba e-restante-de companheiros-deles que habitam em-Samaria e-restante-de além-de o-rio paz e-agora');
INSERT INTO verses VALUES (12133, 15, 4, 18, 'a-carta que enviastes sobre-nós claramente foi-lida diante-de-mim');
INSERT INTO verses VALUES (12134, 15, 4, 19, 'e-de-mim foi-posto decreto e-investigaram e-acharam que a-cidade esta de desde-dias-de eternidade sobre contra-reis se-levanta e-rebelião e-sedição é-feita nela');
INSERT INTO verses VALUES (12135, 15, 4, 20, 'e-reis poderosos foram sobre Jerusalém e-dominando em-todo além-de o-rio e-tributo não e saiu de Ti para eles:');
INSERT INTO verses VALUES (12136, 15, 4, 21, '[כְּעַן֙] colocaram [טְּעֵ֔ם] [לְבַטָּלָ֖א] גּוֹבְרַיָּא [אִלֵּ֑ךְ] [וְקִרְיְתָ֥א] aquela não [תִתְבְּנֵ֔א] até de-mi [יִתְּשָֽׂם]');
INSERT INTO verses VALUES (12137, 15, 4, 22, '[וּזְהִירִ֥ין] [הֱו֛וֹ] e-enganaram [לְמֶעְבַּ֣ד] sobre Dana [יִשְׂגֵּ֣א] [חֲבָלָ֔א] [לְהַנְזָקַ֖ת] [מַלְכִֽין׃]');
INSERT INTO verses VALUES (12138, 15, 4, 23, 'אֵדַיִן de דִּי פרשהגן nishthavnā'' que o-rei קרי קדם- רחום ושMPIים ספרא וכnanoתון Azalū בבהילו para-ir-ush-le-m sobre ye-hu-da-i-ay-e-a u-be-ta-ti-lu hi-mo be-ed-ra-a-ay ve-chai-l');
INSERT INTO verses VALUES (12139, 15, 4, 24, 'badayin be-ta-te-lat a-bi-da-at casa-de e-la-ha-a di בּירושׁלים וַהֲוָת֙ até até ano-de תּארתֵן para-reinado Dario rei-de Pérsia');
INSERT INTO chapters VALUES (408, 15, 5, 17);
INSERT INTO verses VALUES (12140, 15, 5, 1, 'וְהִתְנַבִּי חגי וּזְכַרְיָ֤ה בַר־ עִידּוא֙ sobre יְהוּדָיֵ֔א que בִיה֖וּד e em Jerusalém por causa de Elohim Israel aliás');
INSERT INTO verses VALUES (12141, 15, 5, 2, 'ainda levantaram-se Zarubabel filho de Salatiel e Yeshua filho de יֽוֹצָדָ֔ק וְשָׁרִ֣יו לְמִבְנֵ֔א casa Elaha que birushalem וְעִמְּה֛וֹן que Elaha מְסָעֲדִ֥ין לְהֽוֹן׃');
INSERT INTO verses VALUES (12142, 15, 5, 3, '[בֵּהּ־זִמְנָא֩] [אֲתָ֨א] [עֲלֵיה֜וֹן] [תַּ֠תְּנַי] [פַּחַ֧ת] [עֲבַֽר־נַהֲרָ֛ה] além-de o-rio [וּכְנָוָתְה֑וֹן] [וְכֵן֙] [אָמְרִ֣ין] e também אָמְרִ֣ין [לְכֹ֜ם] de nome [דְנָה֙] decreto [וְאֻשַּׁרְנָ֥א] [דְנָ֖ה] [לְשַׁכְלָלָֽה׃]');
INSERT INTO verses VALUES (12143, 15, 5, 4, 'adiyin kenema amarnea lähom de innun shamahta gubraya que deneha binyana בָּנַֽיִן׃');
INSERT INTO verses VALUES (12144, 15, 5, 5, '[וְעֵ֣ין] [אֱלָהֲהֹ֗ם] [הֲוָת֙] sobre [יְהוּדָיֵ֔א] [וְלָא־בַטִּ֣לוּ] e-não [עַד־טַעְמָ֖א] eles até [וֶאֱדַ֛יִן] [יְתִיב֥וּן] [נִשְׁתְּוָנָ֖א] [עַל־דְּנָֽה׃] sobre dna:');
INSERT INTO verses VALUES (12145, 15, 5, 6, 'cópia [אִ֠גַּרְתָּא] que enviou [׀] filho-de além-de [וּשְׁתַ֤ר] [בּוֹזְנַי֙] [וּכְנָ֣וָתֵ֔הּ] [אֲפַ֨רְסְכָיֵ֔א] [דִּ֖י] דִּ֖י do-além-de o-rio sobre');
INSERT INTO verses VALUES (12146, 15, 5, 7, 'Pitgama enviaram sobre-alohi Ve''cdnah Kitab Begavu Ladaryāwēš o-rei Shlāma Kollā''');
INSERT INTO verses VALUES (12147, 15, 5, 8, 'ידיעה ׀ seja למלכא que א zalna ליהוד מדינתא לבית Elaha רבא e-ele mitbne''a pedra גלל ואע Mitsasam B''kutelaya'' Va''avidta'' Dach'' Asfarnea Mit''abda'' Umatzlach B''yedhem:');
INSERT INTO verses VALUES (12148, 15, 5, 9, 'Edain Sha''elnea'' לְשָׂבַיָּ֣א אִלֵּ֔ךְ כְּנֵ֖מָא אֲמַ֣רְנָא לְּהֹ֑ם de nome לְכֹ֜ם decreto בַּיְתָ֤א דְּנָה לְמִבְנְיָ֔ה וְאֻשַּׁרְנָ֥א dene''a לְשַׁכְלָלָֽה׃');
INSERT INTO verses VALUES (12149, 15, 5, 10, 'e também que são perguntei-lhes a eles para informá-los דּי foi escrito que força que em seus principais');
INSERT INTO verses VALUES (12150, 15, 5, 11, '[וּכְנֵ֥מָא] [פִתְגָמָ֖א] [הֲתִיב֣וּנָא] [לְמֵמַ֑ר] [אֲנַ֣חְנָא] [הִמּ֡וֹ] [עַבְדוֹהִי֩] [דִֽי־אֱלָ֨הּ] Elohim [וְאַרְעָ֗א] [וּבָנַ֤יִן] [בַּיְתָא֙] [דִּֽי־הֲוָ֨א] que [מִקַּדְמַ֤ת] [דְּנָה֙] [שְׁנִ֣ין] esta [וּמֶ֤לֶךְ] [לְיִשְׂרָאֵל֙] e-melque para-o-Israel muito');
INSERT INTO verses VALUES (12151, 15, 5, 12, 'לָהֵ֗ן de דִּ֨י Harregguzu Avahatanha Leelaha שְׁמַיָּ֔א Yehaba eles Biyada Nebukadnetzar rei-de Babel Uvaytaha דְּנָה Satreh Ve''amma Haglili LEVABEL:');
INSERT INTO verses VALUES (12152, 15, 5, 13, 'BRAM em-ano-de חֲדָה KORUSH o-rei que בָבֶ֑ל CORUSH o-rei nome decreto casa-de Elah dene''a LIBNE:');
INSERT INTO verses VALUES (12153, 15, 5, 14, 'E APF MAANAYA que casa-de ELAHAE que DAHAVAH E KASPA que נְבוּכַדְנֶצַּ֗ר הַנְפֵּק de o-palácio que בִֽירוּשְׁלֶ֔ם וְהֵיבֵ֣ל eles לְהֵיכְלָ֖א que בָבֶ֑ל הַנְפֵּ֨ק הִמּ֜וֹ כּ֣וֹרֶשׁ o-rei de o-palácio que בָבֶ֔ל וִיהִ֙יבוּ֙ לְשֵׁשֲׁבַּצַּ֣ר שְׁמֵ֔הּ que פֶּחַה שֹׂמֵהּ׃');
INSERT INTO verses VALUES (12154, 15, 5, 15, 'וַאֲמַר־ [׀] [*אלה] [**אֵ֚ל] [מָֽאנַיָּ֔א] [שֵׂ֚א] eles [הִמּ֔וֹ] que [דִּ֣י] e-casa-de [וּבֵ֥ית] [אֱלָהָ֖א] sobre [עַל־אַתְרֵֽהּ׃]');
INSERT INTO verses VALUES (12155, 15, 5, 16, '[אֱדַ֙יִן֙] [שֵׁשְׁבַּצַּ֣ר] [דֵּ֔ךְ] [אֲתָ֗א] [יְהַ֧ב] [אֻשַּׁיָּ֛א] que casa [דִּ֣י] que [וּמִן־אֱדַ֧יִן] e-de [מִתְבְּנֵ֖א] e-até [שְׁלִֽם] e-não');
INSERT INTO verses VALUES (12156, 15, 5, 17, '[וּכְעַ֞ן] eis sobre מלכא [יִ֠תְבַּקַּר] [בְּבֵ֨ית] [גִּנְזַיָּ֜א] [דִּי־מַלְכָּ֣א] que מלכא [בְּבָבֶל֒] eis [אִיתַ֗י] aquelas [מַלְכָּא֙] que de [לְמִבְנֵ֛א] o-rei foi-posto [בִּירוּשְׁלֶ֑ם] [וּרְע֥וּת] casa-de [עַל־דְּנָ֖ה] [יִשְׁלַ֥ח] [עֲלֶֽינָא׃] sobre dá יִשְׁלַ֥ח');
INSERT INTO chapters VALUES (409, 15, 6, 22);
INSERT INTO verses VALUES (12157, 15, 6, 1, '[בֵּאדַ֛יִן] Dario o-rei nome [טְעֵ֑ם] [וּבַקַּ֣רוּ] em-casa-de [בְּבֵ֣ית] [סִפְרַיָּ֗א] [דִּ֧י] [גִנְזַיָּ֛א] [מְהַחֲתִ֥ין] [תַּמָּ֖ה]');
INSERT INTO verses VALUES (12158, 15, 6, 2, '[וְהִשְׁתְּכַ֣ח] [בְּאַחְמְתָ֗א] [בְּבִֽירְתָ֛א] די [בְּמָדַ֥י] [מְדִינְתָּ֖ה] [מְגִלָּ֣ה] [חֲדָ֑ה] [וְּ[t]כֵן־כְּתִ֥יב] [בְּגַוַּ֖הּ] [דִּכְרוֹנָֽה׃]');
INSERT INTO verses VALUES (12159, 15, 6, 3, 'em-ano-de [חֲדָ֜ה] [לְכ֣וֹרֶשׁ] o-rei [כּ֣וֹרֶשׁ] MALKĀʾ- nome decreto casa-de [בִֽירוּשְׁלֶם֙] [בַּיְתָ֣א] [יִתְבְּנֵ֔א] [אֲתַר֙] [דִּֽי־דָבְחִ֣ין] que [וְאֻשּׁ֖וֹהִי] [מְסֽוֹבְלִ֑ין] [רוּמֵהּ֙] [אַמִּ֣ין] [שִׁתִּ֔ין] [פְּתָיֵ֖הּ] [אַמִּ֥ין] [שִׁתִּֽין]');
INSERT INTO verses VALUES (12160, 15, 6, 4, '[נִדְבָּכִ֞ין] que even [תְּלָתָ֔א] [וְנִדְבָּ֖ךְ] [דִּי־אָ֣ע] que [וְנִ֨פְקְתָ֔א] [מִן־בֵּ֥ית] [מַלְכָּ֖א] de casa o-rei');
INSERT INTO verses VALUES (12161, 15, 6, 5, 'ואף maanei casa-de אלaea que דַהֲבָ֣ה e o dinheiro que נְבֽוּכַדְנֶצַּ֗ר הַנְפֵּ֛ק de הֵיכְלָ֥א דִי־ בִירוּשְׁלֶ֖ם וְהֵיבֵ֣ל para-Babel יַהֲתִיב֗וּן וִ֠יהָךְ para edificar דִי־ em Jerusalém para arrejar e atet em-casa-de Eloah:');
INSERT INTO verses VALUES (12162, 15, 6, 6, 'כְּעַ֡ן tattani pachath além-de naharah shatar בוזני e a vontade delas אפרסקיה די do-além-de o-rio רחיקין היו de תה');
INSERT INTO verses VALUES (12163, 15, 6, 7, '[שְׁבֻ֕קוּ] [לַעֲבִידַ֖ת] casa-de [דֵ֑ךְ] [פַּחַ֤ת] [יְהוּדָיֵא֙] [וּלְשָׂבֵ֣י] [יְהוּדָיֵ֔א] [בֵּית־אֱלָהָ֥א] casa-de [יִבְנ֥וֹן] [עַל־אַתְרֵֽהּ] sobre');
INSERT INTO verses VALUES (12164, 15, 6, 8, 'e-de-mim foi-posto decreto למה que תעבדון com שבוי יְהוּדִיֵּ֙ אליך למבנה casa-de Elaha דך ומינכסים o-rei que מידת além-de נהרה אספרנא ניפקת תהיה /mit/yah/ba'' לְגֻבְרַיָּ֥א il/ke que não le-bat/tal/a:');
INSERT INTO verses VALUES (12165, 15, 6, 9, 'וּמָ֣ה chas/hachan e-filhos-de tor/in ve-dik/rin ve-imir/in la-al/avan le-eleh os céus chinṭín sal carvalho e unguento como está escrito sacerdote porque em Jerusalém לְהַוֵּא /mitiyehev/ לְהֹ֛ם yom / em-dia dia não shalo''u :/');
INSERT INTO verses VALUES (12166, 15, 6, 10, 'que lehavon mehakrabin niyechoin le''eloh shmayya :/ u''matzlaiyn para as vidas o-rei e-novi:');
INSERT INTO verses VALUES (12167, 15, 6, 11, 'e-de-mim foi-posto decreto que todo homem que que se deleite em palavras de se incline a de em sua e erga-se será-erradicado עֲלֹהִי e na sua serão-erradicados será-servido sobre Dana:');
INSERT INTO verses VALUES (12168, 15, 6, 12, 'e a Elohima que habitará שֶׁמֶהּ ela-terá e a sua todo rei וְעַם֙ דִּ֣י ׀ enviará mano לְהַשְׁנָיָ֛ה לְחַבָּלָ֛ה casa-de Elah דֵ֖ךְ que בִירוּשְׁלֶ֑ם אנָה דָרְיָ֙וֶשׁ֙ שָׂ֣מֶת decreto אָסְפַּ֖רְנָא יִתְעֲבִֽד׃');
INSERT INTO verses VALUES (12169, 15, 6, 13, '[אֱ֠דַיִן] [תַּתְּנַ֞י] [פַּחַ֧ת] além-de o-rio [בּוֹזְנַ֖י] [וּכְנָוָתְה֑וֹן] [לָקֳבֵ֗ל] [דִּֽי־שְׁלַ֞ח] que enviou [כְּנֵ֖מָא] [אָסְפַּ֥רְנָא] [עֲבַֽדוּ]');
INSERT INTO verses VALUES (12170, 15, 6, 14, 'וְשָׂבֵ֤י יהודה בָּנַ֣יִן וּמַצְלְחִ֔ין בִּנְבוּאַת֙ חַגַּ֣י וּזְכַרְיָ-ה בַּר־ עִדּ֑וֹא וּבְנ֣וֹ וְשַׁכְלִ֗לוּ de טעם Elah Israel e-prova כורש ודריVAS וארטHASHAT rei Pérsia');
INSERT INTO verses VALUES (12171, 15, 6, 15, '[וְשֵׁיצִיא֙] [בַּיְתָ֣ה] [דְנָ֔ה] até dia [תְּלָתָ֖ה] [לִירַ֣ח] [אֲדָ֑ר] que ela ano-de Sete [מַלְכָּֽא׃] Dario');
INSERT INTO verses VALUES (12172, 15, 6, 16, 'e serviram filhos-de Israel cohanai e levai e-restante-de filhos-de exila dedicação casa-de Elah dene''a com alegria;');
INSERT INTO verses VALUES (12173, 15, 6, 17, 'e ofereceram para a dedicação casa-de Elaha דנה תורין cem דּיכְרִין מָאתַיִן אִמּירִין quatro cem וּצְפִירֵי עִזּין sobre todo Israel תְּרֵֽי־ dez לְמִנְיָן tribos-de Israel');
INSERT INTO verses VALUES (12174, 15, 6, 18, 'וַהֲקִימוּ כָהֲנַיָא בִּפְלֻגָּתְה֗וֹן וְלֵוָיֵא֙ em-separação-delas sobre trabalho Elaha que בִירוּשְׁלֶ֑ם escrito livro Moisés');
INSERT INTO verses VALUES (12175, 15, 6, 19, 'e-fizeram filhos-de a-exílio a o-pascha בְּאַרְבָּעָ֥ה dez o-primeiro:');
INSERT INTO verses VALUES (12176, 15, 6, 20, 'que hittaharu os-sacerdotes e os levitas como-um כֻּלָּ֣ם tehorim va''yishchato o pésach para-todo filhos-de o-exílio e aos seus irmãos os-sacerdotes e para eles:');
INSERT INTO verses VALUES (12177, 15, 6, 21, 'וַיֹּאכְל֣וּ filhos-de Israel aqueles que retornaram e-tudo e-todo o separado da impureza גוֹיֵֽ־ a-terra a-eles para-consultar a-yhwh Elohim-de Israel');
INSERT INTO verses VALUES (12178, 15, 6, 22, '[וַיַּֽעֲשׂ֧וּ] festa- [שִׁבְעַ֥ת] sete dias que que [שִׂמְּחָ֣ם] yhwh [וְֽהֵסֵ֞ב] coração rei-de ʾaššur sobre-eles [יְדֵיהֶ֔ם] mãos-deles na בִּמְלֶ֥אכֶת casa-de Elohim Elohim-de Israel');
INSERT INTO chapters VALUES (410, 15, 7, 28);
INSERT INTO verses VALUES (12179, 15, 7, 1, 'e-depois as-palavras os-estes [בְּמַלְכ֖וּת] [אַרְתַּחְשַׁ֣סְתְּא] rei-de Pérsia [בֶּן־שְׂרָיָ֔ה] filho-de Shrayah filho-de Azaria filho-de Chilquiyah');
INSERT INTO verses VALUES (12180, 15, 7, 2, 'filho-de [בֶּן־צָד֖וֹק] filho-de Zadoque filho-de achitub');
INSERT INTO verses VALUES (12181, 15, 7, 3, 'filho-de Amaryah filho-de Azaria filho-de meryot');
INSERT INTO verses VALUES (12182, 15, 7, 4, 'filho-de Zerahyah filho-de uzzi filho-de');
INSERT INTO verses VALUES (12183, 15, 7, 5, 'filho-de [בֶּן־פִּֽינְחָס֙] filho-de Pinhas filho-de [הָרֹֽאשׁ] filho-de Aarão o-sacerdote הראש׃');
INSERT INTO verses VALUES (12184, 15, 7, 6, 'ele עזרא subir de Babel e-ele sopher Máhir em-lei-de Moisés yhwh deu yhwh Elohim-de Israel e-ele-deu a-ele o rei conforme-mão-de yhwh Elohim-dele sobre-ele todo -o seu pedido');
INSERT INTO verses VALUES (12185, 15, 7, 7, 'e subiram filhos- Israel e-de os-sacerdotes e os levitas e-os-cantores e-os-tretores e-os-netinins a Jerusalém no ano de sete para-artaxerxes o rei');
INSERT INTO verses VALUES (12186, 15, 7, 8, 'E-veio Jerusalém no-mês o-quinto ela ano-de sétimo para-o rei');
INSERT INTO verses VALUES (12187, 15, 7, 9, 'que em-um para-o-mês harishon ele fundou a-subida de-babilônia e-em-um para-o-mês o-cinco-í veio a Jerusalém conforme-mão-de Elohav a-boa sobre-ele');
INSERT INTO verses VALUES (12188, 15, 7, 10, 'que ezra preparou coração-dele para investigar a yhwh yhwh e para fazer e para ensinar em-Israel lei e para julgar');
INSERT INTO verses VALUES (12189, 15, 7, 11, 'e isto cópia este testemunho que deu dar Artaxerxes לעזרא o-sacerdote o escriba סופר dibre mandamentos-de yhwh e-seus-decretos sobre Israel');
INSERT INTO verses VALUES (12190, 15, 7, 12, 'ארתחשסתא rei malakai''ă לְעֶזְרָ֣א כָ֠הֲנָא sapar dată'' que Elohim shamayă'' gamar e-agora');
INSERT INTO verses VALUES (12191, 15, 7, 13, 'minni''ăm foi-posto decreto que todo מִתְנַדַּ֣ב no-meio-da-mo-que-tu de עַמָּ֨ה Israel וְכָהֲנ֣וֹהִי e levai לִמְהָ֧ךְ לִֽירוּשְׁלֶ֛ם contigo יְהָֽךְ׃');
INSERT INTO verses VALUES (12192, 15, 7, 14, 'todo קֳבֵ֗ל que de קֳדָ֨ם rei וְשִׁבְעַ֤ת YE''ătōhı̂ šəlîaḥ para pastorear sobre Yehūd vəlīrûšēlēm בדדת ʾəlāhāḵ que bı̂ydāḵ:');
INSERT INTO verses VALUES (12193, 15, 7, 15, 'uleheḇālā'' kəsā'' e ouro que מַלְכָּ֣א e se esforçarem-se hitanndavu a Elohim Israel que em Jerusalém mishkneh:');
INSERT INTO verses VALUES (12194, 15, 7, 16, 'e-tudo prata e ouro que será escondida em-todo de um país Babilônia povo הִתְנַדָּב֨וּת עַמָּ֤א וְכָֽהֲנַיָּא֙ מִֽתְנַדְּבִין segundo-casa-de אֱלָהֲהֹ֖ם que בִירוּשְׁלֶֽם׃');
INSERT INTO verses VALUES (12195, 15, 7, 17, 'todo [דְּנָה֩] דְּנָה֩ [תִקְנֵ֜א] [בְּכַסְפָּ֣א] [דְנָ֗ה] [תּוֹרִ֤ין] [׀] [דִּכְרִין֙] [אִמְּרִ֔ין] [וּמִנְחָתְה֖וֹן] [וְנִסְכֵּיה֑וֹן] [וּתְקָרֵ֣ב] eles sobre [דִּ֛י] די casa [דִּ֥י] que');
INSERT INTO verses VALUES (12196, 15, 7, 18, 'וּמָה [דִי֩] e-sobre [**עֲלָ֨ךְ] [וְעַל־*אחי[y]*ך] [**אֶחָ֜ךְ] [יֵיטַ֗ב] [בִּשְׁאָ֛ר] [כַּסְפָּ֥א] [וְדַהֲבָ֖ה] [לְמֶעְבַּ֑ד]');
INSERT INTO verses VALUES (12197, 15, 7, 19, 'וּמָֽאנַיָּא֙ que para-ti para-ti para-sown casa elohim-teu o-completo קֳדָ֖ם elohim jerusalém');
INSERT INTO verses VALUES (12198, 15, 7, 20, 'e-outros profundezas casa elohim-teu que יפּל־ para-ti לְמִנְתַּ֑ן תִּנְתֵּ֕ן de casa גִּנְזֵ֥י מַלְכָּֽא׃');
INSERT INTO verses VALUES (12199, 15, 7, 21, 'e-do אֲנָ֞ה אַרְתַּחְשַׁ֤סְתְּא o-rei foi-posto decreto a-todo גִּזַּֽבְרַיָּ֔א דִּ֖י do-além-de o-rio que todo que יִ֠שְׁאֲלֶנְכוֹן עֶזְרָ֨א כָּהֲנָה סָפַר דָּתָא que Elah שְׁמַיָּ֔א אספרנה יִתְעֲבִד׃');
INSERT INTO verses VALUES (12200, 15, 7, 22, 'até [כַּכְּרִ֣ין] [מְאָה֒] cem e-até [מְאָ֔ה] [וְעַד־חֲמַר֙] cem e-até [וְעַד־בַּתִּ֥ין] [מְשַׁ֖ח] cem e-até [דִּי־לָ֥א] [כְתָֽב] cem não');
INSERT INTO verses VALUES (12201, 15, 7, 23, 'todo די de טעם Elah שְׁמַיָּ֔א יתעrelude אדראזדה para o templo Elah שמיא que לְמָ֤ה לֶֽהֱוֵא֙ קְצַ֔ף sobre מלכות o-rei וּבְנֽוֹהִי׃');
INSERT INTO verses VALUES (12202, 15, 7, 24, '[וּלְכֹ֣ם] [מְהוֹדְעִ֗ין] que todo [וְ֠לֵוָיֵא] [זַמָּ֨רַיָּ֤א] [תָרָֽעַיָּא֙] [נְתִ֣ינַיָּ֔א] [וּפָ֣לְחֵ֔י] [בֵּ֖ית] casa [דְנָ֑ה] [מִנְדָּ֤ה] [בְלוֹ֙] [וַהֲלָ֔ךְ] [לָ֥א] não [לְמִרְמֵ֥א] [עֲלֵיהֹֽם]');
INSERT INTO verses VALUES (12203, 15, 7, 25, 'e-te Esra com-a-sabedoria Eloah-te que בִידָךְ de-mim julgues e-julgues que para-seja para-todo povo que do-além-de נהרה para-todo ידעו דתא אלך saber não conheceu תְּהוֹדְעֽוּן׃');
INSERT INTO verses VALUES (12204, 15, 7, 26, 'e-todo que não להיה servo דתא que אלך והתAEA que o-rei אספרנא Diná eis me adorarei eis eis para morrer eis eis para castigo seriam vendidas e estariam aprisionadas:');
INSERT INTO verses VALUES (12205, 15, 7, 27, 'bendito yhwh Elohim-de nossos pais que dar assim בְּלֵ֣ב o-rei para engravidar a yhwh yhwh que em-Jerusalém');
INSERT INTO verses VALUES (12206, 15, 7, 28, 'e sobre mim ele estendeu-se misericórdia diante-de o rei e seus conselheiros e-para-todo- príncipes-de o-rei os giborim e-eu me fortaleci conforme-mão-de yhwh אֱלֹהַי sobre-mim e juntei-me dos filhos de Israel cabeças para subir comigo');
INSERT INTO chapters VALUES (411, 15, 8, 36);
INSERT INTO verses VALUES (12207, 15, 8, 1, 'e-estes topos-de [אֲבֹתֵיהֶ֖ם] [וְהִתְיַחְשָׂ֑ם] que-subiam [עִמִּ֗י] [בְּמַלְכ֛וּת] [אַרְתַּחְשַׁ֥סְתְּא] o-rei Mibavel');
INSERT INTO verses VALUES (12208, 15, 8, 2, 'de-filhos-de [פִֽינְחָס֙] ger-shom de-filhos-de Aitamar [אִיתָמָ֖ר] de-filhos-de דוד [מִבְּנֵ֥י]');
INSERT INTO verses VALUES (12209, 15, 8, 3, 'de-filhos-de Secanias de-filhos-de פַרְעֹ֖שׁ זְכַרְיָ֑ה וְעִמּ֛וֹ hityachesh lizcharim cem e-cinquenta');
INSERT INTO verses VALUES (12210, 15, 8, 4, 'de-seus filho-de Moabe eliehyoinai filho-de zarachyah e-o duzentos hazcharim');
INSERT INTO verses VALUES (12211, 15, 8, 5, 'de-filhos-de Shekanyah filho-de yachziel ve''immo três centenas hazcharim');
INSERT INTO verses VALUES (12212, 15, 8, 6, 'e filhos de Adim servo filho-de yo-nāt-an e-o cinquenta os machos:');
INSERT INTO verses VALUES (12213, 15, 8, 7, 'e filhos de Elão Yeshaia filho-de Atalia e-o setenta os-masculinos:');
INSERT INTO verses VALUES (12214, 15, 8, 8, 'e filhos de Sefatias Zevadiya filho-de Micael e com ele oitenta os-masculinos:');
INSERT INTO verses VALUES (12215, 15, 8, 9, 'de-filhos-de יוֹאָב Obadyah filho-de Yechiel e-com-o duzentos e-vezes dez os-masculinos:');
INSERT INTO verses VALUES (12216, 15, 8, 10, 'e-dos-filhos שֶׁלּוֹמִית filho-de joséfia e-com-o cem e-sessenta os-mas:');
INSERT INTO verses VALUES (12217, 15, 8, 11, 'e filhos de בֵבַ֔י זכריה filho-de בֵבַ֔י e-com-o vinte e-oito os-zacarim:');
INSERT INTO verses VALUES (12218, 15, 8, 12, 'e filhos de Azgade joachanan filho-de o-keitan e-com-o cem e-esare os-zacarim:');
INSERT INTO verses VALUES (12219, 15, 8, 13, 'e filhos de adonikam ú-acharonim e-estes nomes-deles אֱלִיפֶ֖לֶט יְעִיאֵ֣ל וּשְׁמַעְיָ֑ה וְעִמָּהֶ֖ם sessenta הַזְּכָרִֽים׃');
INSERT INTO verses VALUES (12220, 15, 8, 14, 'e-dos-filhos BIGVAY עוּתַ֣י וְעִמּ֖וֹ setenta הַזְּכָרִֽים׃');
INSERT INTO verses VALUES (12221, 15, 8, 15, 'וָֽאֶקְבְּצֵ֗ם a o-river o-que-vinha a אַהֲוָ֔א e-nachane nome dias shlosha va-abinah ba''am e nos sacerdotes e-dos-filhos Levi não encontrei nome');
INSERT INTO verses VALUES (12222, 15, 8, 16, 'va-eshlacha le-eliezer la-ariel li-shmauya u-le-elnatan e para disputar e para Elnatã e para Natã e para Zaqueu e para Mesulãm cabeças-de e para Joirib e para Elnatã entendemos:');
INSERT INTO verses VALUES (12223, 15, 8, 17, 'elas sobre Ado o-primeiro no cipã o lugar e coloquei em sua boca palavras לְדַבֵּר a e disse seu-irmão em minha moeda o-lugar para trazer para-nós servos segundo-casa-de Elohim-nosso');
INSERT INTO verses VALUES (12224, 15, 8, 18, 'e trouxeram para-nos conforme-mão-de nos-so-bre a-bons-a sobre-nos homem sé-kel de-filhos-de ma-chali filho-de Levi filho-de Israel וְשֵׁרֵֽבְיָ֛ה ובנאי e-seus-irmãos oito dez');
INSERT INTO verses VALUES (12225, 15, 8, 19, 'e-a חשביָה e com ele ye-sha-ya-ha de-filhos-de Merari e-chai-o e-seus-filhos vinte');
INSERT INTO verses VALUES (12226, 15, 8, 20, 'e-de ha-ni-ti-nim shen-na-tan Davi e-os-príncipes la-avod-a-ta os-levitas נְתִינִ֖ים maatayim וְעֶשְׂרִ֑ים kolam נִקְּב֥וּ בְשֵׁמֽוֹת׃');
INSERT INTO verses VALUES (12227, 15, 8, 21, '[וָאֶקְרָ֨א] nome [צוֹם֙] sobre [אַהֲוָ֔א] [לְהִתְעַנּ֖וֹת] [לִפְנֵ֣י] diante-de Elohim-nosso nós o-caminho-de caminho [לָ֥נוּ] para-nós [וּלְכָל־רְכוּשֵֽׁנוּ]');
INSERT INTO verses VALUES (12228, 15, 8, 22, 'que Boschti para-pedir de o rei força uParahsim le''Azrenu me''Oyev בַדָּ֑רֶךְ porque dizendo ao rei dizendo mão-de Eloheynu sobre sobre que-nos-busca le''Tovah ve''Azavo ve''Apav sobre todo Ozavy:');
INSERT INTO verses VALUES (12229, 15, 8, 23, 'e-nos-contraiamos e-nos-pesquisássemos de-oura-elohim sobre esta e-ele-sugestionou para-nós');
INSERT INTO verses VALUES (12230, 15, 8, 24, 'e-divisionei מִשָּׂרֵ֥י os-sacerdotes dois dez para-os-senhores חשביָה e-com-eles de-suas-irmãos dez:');
INSERT INTO verses VALUES (12231, 15, 8, 25, 'a-eles a a-eles e-a o zahav e-a os kelim oferta-de casa-de nosso-Elohim que horeimu o rei e seus yo''atzav e seus saray e-todo Israel os-encontrados:');
INSERT INTO verses VALUES (12232, 15, 8, 26, 'e pesquei sobre suas mãos prata por cícaros seis-de centenas-de e cinquenta e-utensílios- ouro cem para-o-kicarim- ouro cem kicar-:');
INSERT INTO verses VALUES (12233, 15, 8, 27, 'e-copos- ouro vinte para-a-adarchonim- mil וּכְלֵ֨י נחושט metsahav-: boa dois chamudot- kazaz-:');
INSERT INTO verses VALUES (12234, 15, 8, 28, 'e-eu-disse a-eles vós santo-: para-יהוה e os utensílios santidade e o prata e-o-ouro oferta a-yhwh Elohim-de vosso pais');
INSERT INTO verses VALUES (12235, 15, 8, 29, 'se separaram e guardem até e pesarem em-frente-de-a príncipes-de os-sacerdotes e os levitas e os chefes de הָאָב֥וֹת para-israel em-Jerusalém yhwh casa yhwh');
INSERT INTO verses VALUES (12236, 15, 8, 30, 'e receberam os-sacerdotes e levitas מִשְׁקָל הַכֶּסֶף e-o-ouro וְהַכֶּלִים לְהָבִיא לִירוּשָׁלַ֖ם segundo-casa-de Elohim-nosso');
INSERT INTO verses VALUES (12237, 15, 8, 31, 'e saímos do-rivoli אֽהֲוָ֗א בּשְׁנֵ֤ים dez para-o-mês harishon para-andar Jerusalém e-mão- era ela-foi sobre-nós וַיַּצִּילֵנוּ da-mão-de o-ev וְאוֹרֵב sobre a-direção׃');
INSERT INTO verses VALUES (12238, 15, 8, 32, 'e fomos Jerusalém e-nós-assentamos nome dias três');
INSERT INTO verses VALUES (12239, 15, 8, 33, 'e-no-dia o-quarto foram-pesados o-prata e-o-ouro e os utensílios em-casa-de nosso-Elohim sobre mão-de Meremote filho-de auriyea o-sacerdote e-com-ele Eleazar filho-de pinhas e-com-eles יוֹזָבָ֧ד filho-de Jesua וְנֽוֹעַדְיָ֥ה filho-de בִּנּ֖וּי os-levitas');
INSERT INTO verses VALUES (12240, 15, 8, 34, 'בְּמִסְפָּ֥ר de-pesoa para-todo וַיִּכָּתֵ֥ב todo הַמִּשְׁקָ֖ל em-o tempo a-ela');
INSERT INTO verses VALUES (12241, 15, 8, 35, 'הַבָּאִים מֵֽהַשְּׁבִ֨י filhos-de a-exilada הִקְרִ֥יבוּ עֹל֣וֹת ׀ para-Elohim Israel ervas-dos-pariim doze dez sobre todo Israel ervas-dos-ailim noventa e-seshah ervas-dos-kobasim setenta e-shibbah ervas-dos-tzipirei pecado dois dez o todo עולה para-יהוה');
INSERT INTO verses VALUES (12242, 15, 8, 36, 'e-deram-los- a dois o-rei para Achashdarpene o-rei e pachavot עבר o-rio e foram levados a o-povo e-a casa-de Elohim');
INSERT INTO chapters VALUES (412, 15, 9, 15);
INSERT INTO verses VALUES (12243, 15, 9, 1, 'e quando se consumaram Estas se aproximaram para mim os-príncipes dizendo não נִבְדְּל֞וּ o-povo Israel e os sacerdotes וְהַלְוִיִּ֔ם de-povos-de as-terras como suas abominações ao cananeu o-heteu ao perizeu ao ibusita [הַמֹּ֣אָבִ֔י] הַמֹּ֣אָבִ֔י הַמִּצְרִ֖י e o Amorá:');
INSERT INTO verses VALUES (12244, 15, 9, 2, 'porque [מִבְּנֹֽתֵיהֶ֗ם] a-eles para-eles [וְהִתְעָֽרְבוּ֙] semente descendência o-santuário [הָאֲרָצ֑וֹת] as-terras [הַשָּׂרִ֣ים] [וְהַסְּגָנִ֗ים] era [בַּמַּ֥עַל] [הַזֶּ֖ה] este');
INSERT INTO verses VALUES (12245, 15, 9, 3, 'E quando ouvi a a-coisa esta que cortei a BIGDIDI e meu manto eu me rasguei de cima minha cabeça e minha barba eu me sentei מְשׁוֹמֵֽם׃');
INSERT INTO verses VALUES (12246, 15, 9, 4, 'וְאֵלַ֣י serão reunidos todo chared בְּדִבְרֵ֣י Elohim-de sobre sobre em-alto הַגּוֹלָ֑ה e-eu habitou até até לְמִנְחַ֥ת a entardecer:');
INSERT INTO verses VALUES (12247, 15, 9, 5, 'וּבְמִנְחַ֣ת o-crepúsculo קַ֚מְתִּי מִתַּֽעֲנִיתִ֔י e-quebrarei minha-casa e meu manto e criei-me sobre בִּרְכַּ֔י e-despi-ei-me minhas-mãos a yhwh yhwh');
INSERT INTO verses VALUES (12248, 15, 9, 6, 'e- disse אֱלֹהַי vergonha-me e-estranhei-me para-os-montes Elohim-me face-de a-ti que nossas-iniquidades רבוּ para cima cabeça ואשמנוּ גדלה até לשמים׃');
INSERT INTO verses VALUES (12249, 15, 9, 7, 'miesי אבוטינוּ nos באשמנה ge-dolah até o-dia esta ובעונותינוּ ניטנוּ אֲנַחְנוּ֩ מְלָכֵינוּ כֹהֲנֵינוּ em-mão-de reis-de as nações בַּחֶרֶב בַּשְׁבִ֧י וּבַבִּזָּה וּבְבֹשֶׁת face כְּהַיּ֥וֹם a-esta');
INSERT INTO verses VALUES (12250, 15, 9, 8, 'e-agora כִּמְעַט־ era háthā imploração de yhwh nosso-Elohim para deixar a-nós פליטה e dar para-nós verdadeiramente em-lugar-de para-iluminar para iluminar nosso olhos nosso-Elohim e dar-nos de-míya pouco em-nos');
INSERT INTO verses VALUES (12251, 15, 9, 9, 'porque avádim nós não não deixamos-nos nosso-Elohim e-ele-levou sobre-nós misericórdia em-frente-de-a reis-de cortou para-dar a-nos da-vida para-exaltar a casa Elohim-nosso e-para-elevar a as-sarabôtav e-lá-te- até gá-de-r bí-yehu-dá-ha e em Jerusalém:');
INSERT INTO verses VALUES (12252, 15, 9, 10, 'e-agora que nóm-a-r Elohim-nosso que esta porque ázav-nu as-tua-m Mandamentos');
INSERT INTO verses VALUES (12253, 15, 9, 11, 'que tzi-ú-ta bí-yá-da teus-servos os profetas dizendo a-terra que vós os-vindo para-a-posse-de-la terra nídda-ha ela בְּנִדַּ֖ת עַמֵּ֣י as-terras בְּתוֹעֲבֹֽתֵיהֶ֗ם que מִלְאֻ֛הָ מִפֶּ֥ה a boca בְּטֻמְאָתָֽם׃');
INSERT INTO verses VALUES (12254, 15, 9, 12, 'e-agora בְּֽנוֹתֵיכֶ֞ם a תִּתְּנ֣וּ para seus filhos וּבְנֹֽתֵיהֶם֙ a tisau libneichem e-não tidrshu שֶׁלָּם ve-tovatam até eternidade a-terra vocês fortaleçais va-achaltem a bom a-terra ve-horashtem para-vos até eternidade');
INSERT INTO verses VALUES (12255, 15, 9, 13, 've-acharei todo o-que-vinha sobre-nós bemaasenu os maus e pela nossa iniqüidade que que tu nosso-Elohim escurou-se לְמַ֙טָּה֙ de nossa maldade e deu-se a nós פליטה כָּזֹֽאת׃');
INSERT INTO verses VALUES (12256, 15, 9, 14, 'teremos nos arrependido para-frustrar mitzvoteycha e nos convertamos nos povos as abominações estas não envergonharei-vos- בָּנוּ até כלה לְאֵ֥ין perpetuamente e desampararei;');
INSERT INTO verses VALUES (12257, 15, 9, 15, 'yhwh Elohim-de Israel justo tu porque nos deixamos פליטה como hoje esta eis-os diante-de-ti que porque não-há para-está-lo diante-de-ti sobre esta-ali');
INSERT INTO chapters VALUES (413, 15, 10, 44);
INSERT INTO verses VALUES (12258, 15, 10, 1, 'e-orar-se Ezrã e testemunhe-o no monte e-cair-se diante-de casa o-Elohim se-reunam a-ele de-Israel assembleia chefe-de muito homens e-mulheres e-crianças porque beram o-povo hárbeh- בֶֽכֶה׃');
INSERT INTO verses VALUES (12259, 15, 10, 2, 'e-ele-respondeu שַׁכְנִיָּה filho-de Yechiê'' de-filhos-de E-disse E-disse nos ma''alnû bê''elohê''nô vânoshéb mulheres nachriyôt m''âmê a-terra a-terra e-agora מקוה para Israel sobre esta-ali');
INSERT INTO verses VALUES (12260, 15, 10, 3, 'e-agora [נִֽכְרָת־בְּרִ֣ית] aliança [לְהוֹצִ֨יא] [כָל־נָשִׁ֜ים] todo [מֵהֶם֙] [בַּעֲצַ֣ת] deles [וְהַחֲרֵדִ֖ים] Adonai [Elohim] [וְכַתּוֹרָ֖ה] nosso-Elohim');
INSERT INTO verses VALUES (12261, 15, 10, 4, 'levantou porque sobre-te a palavra e-nós contigo forte e-fe');
INSERT INTO verses VALUES (12262, 15, 10, 5, 'E-levantou Esra e-jurou a sáar os-sacerdotes dos-Levitas e-todo Israel para-fazer אֶת-הַדָּבָר este e juraram:');
INSERT INTO verses VALUES (12263, 15, 10, 6, 'E-levantou Esra diante de casa הָֽאֱלֹהִ֔ים E-andou a para a Yehochanan filho-de Eliseu pão nome לֶ֤חֶם não que e-maís não bebeu porque que se lamenta sobre subida do exílio');
INSERT INTO verses VALUES (12264, 15, 10, 7, 'e passaram voz em Judá e Jerusalém a-todo filhos-de o-exílio para reunir Jerusalém');
INSERT INTO verses VALUES (12265, 15, 10, 8, 'e-tudo que não yavo em três os-dias conforme a disposição os-príncipes e os anciãos יָחֳרַ֖ם todo רְכוּשׁ֑וֹ e-ele יִבָּדֵ֖ל מִקְּהַ֥ל הַגּוֹלָֽה׃');
INSERT INTO verses VALUES (12266, 15, 10, 9, 'e-reuniram-se todo os-homens-de- יְהוּדָה וּבִנְיָמִ֨ן ׀ Jerusalém לִשְׁלֹ֣שׁת ele ele novo o nono VINTE NOVEMBRE- e-habitaram todo o povo בִּרְחוֹב֙ casa os-Elohim מַרְעִידִ֥ים sobre a palavra e das chuvas');
INSERT INTO verses VALUES (12267, 15, 10, 10, 'E-levantou Esra o-sacerdote E-disse a-eles vós vocês subirão e responderam נָשִׁים נכריות para adicionar sobre acusações Israel');
INSERT INTO verses VALUES (12268, 15, 10, 11, 'e-agora deite obras de caridade para-יהוה Elohim-de pais-vosso e-façam seu desejo e separaram-se a-terra a-terra e-de as-mulheres as-nocrí-yyot:');
INSERT INTO verses VALUES (12269, 15, 10, 12, 'vay-anu todo ha-qahal voz voz-de grande assim sobre nós para-fazer');
INSERT INTO verses VALUES (12270, 15, 10, 13, 'todavia o-povo muito e a hora geshamim e-não-há força la-amod ba-chuvtz ve-ha-malacha não um um e-não lisnayim porque הִרְבּוּ לִפְשֹׁעַ em-a-palavra a-esta');
INSERT INTO verses VALUES (12271, 15, 10, 14, 'יַעֲמְדוּ por-favor nosso-sára e-tudo הַקָּהָל e-todo que בְּעָרֵינוּ הַהוֹשִׁיב נָשִׁ֤ים נָכְרִיּות virá לְעִתִּים מְזֻמָּנִים e com eles זִקְנֵי־ cidade até e-as-senhoras-julgadoras até לְהָשִׁ֞יב nós até Elohim-nosso dele até para-a-palavra a-esta');
INSERT INTO verses VALUES (12272, 15, 10, 15, 'porém [יוֹנָתָ֧ן] filho-de [וְיַחְזְיָ֥ה] [בֶן־תִּקְוָ֖ה] filho-de [עַל־זֹ֑את] [וּמְשֻׁלָּ֛ם] sobre esta [עֲזָרֻֽם]');
INSERT INTO verses VALUES (12273, 15, 10, 16, 'ו עשו - assim, filhos-de a exila e separaram-se; Esdras o-sacerdote homens cabeças; os-pais segundo-casa-de pais-deles e todos pelos seus nomes e sentaram-se um um no-mês o décimo para Dario a-palavra');
INSERT INTO verses VALUES (12274, 15, 10, 17, 'e cessaram em-todo אֲנָשִׁים הֹשִׁיבוּ נָשִׁים נכריות até dia um para-o-mes o-primeiro:');
INSERT INTO verses VALUES (12275, 15, 10, 18, '[וַיִּמָּצֵא֙] de-filhos-de os-sacerdotes que [הֹשִׁ֖יבוּ] [נָשִׁ֣ים] [נָכְרִיּ֑וֹת] [מִבְּנֵ֨י] [יֵשׁ֤וּעַ] filho-de [וְאֶחָ֔יו] e-irmãos-de-o [וֽ͏ֶאֱלִיעֶ֔זֶר] [וְיָרִ֖יב] [וּגְדַלְיָֽה]');
INSERT INTO verses VALUES (12276, 15, 10, 19, '[וַיִּתְּנ֥וּ] mão-deles [לְהוֹצִ֣יא] [נְשֵׁיהֶ֑ם] [וַאֲשֵׁמִ֥ים] [אֵֽיל־צֹ֖אן] [עַל־אַשְׁמָתָֽם׃] sobre');
INSERT INTO verses VALUES (12277, 15, 10, 20, 'וּמִבְּנֵ֣י disse Chanani e Zevadiyah:');
INSERT INTO verses VALUES (12278, 15, 10, 21, 'e filhos de חָרִ֑ים Maaseyah e Eliyah e Shamaiah: Vichiayel e Uzziyah:');
INSERT INTO verses VALUES (12279, 15, 10, 22, 'e filhos de פסחור אליוועיני מעשייה ismael נתנאל יוֹזָבָ֖ד ואלעSHA׃');
INSERT INTO verses VALUES (12280, 15, 10, 23, '[וּמִֽן־הַלְוִיִּ֑ם] os-levitas [וְשִׁמְעִ֗י] [וְקֵֽלָיָה֙] ele ele [פְּתַֽחְיָ֥ה] [יְהוּדָ֖ה] Judá');
INSERT INTO verses VALUES (12281, 15, 10, 24, 'e-de hammashōrērim אליהו e-de hammashōʿarı̂ym shallūm e a balança ve''ōrī');
INSERT INTO verses VALUES (12282, 15, 10, 25, 'umiyyēšrāʾel de-filhos-de parʿōš ramyā וְיִזִּיָּ֤ה וּמַלְכִּיָּה֙ וּמִיָּמִ֣ן וְאֶלְעָזָר וּמַלְכִּיָּ֖ה e-Benaja');
INSERT INTO verses VALUES (12283, 15, 10, 26, 'וּמִבְּנֵ֖י עֵילָ֑ם מַתַּנְיָ֤ה זְכַרְיָה֙ וִיחִיאֵ֣ל e-servo e-irmãos e-Eliya:');
INSERT INTO verses VALUES (12284, 15, 10, 27, 'e filhos Zattua Elionai Elisab Matanya e-irmãos e-Zavad וַעֲזִיזָֽא׃');
INSERT INTO verses VALUES (12285, 15, 10, 28, 'e filhos בֵּבָ֑י יהוחנן Hananyah זַבַּ֥י עַתְלָֽי׃');
INSERT INTO verses VALUES (12286, 15, 10, 29, 'וּמִבְּנֵ֖י filhos-de מְשֻׁלָּ֤ם מַלּוּךְ֙ וַעֲדָיָ֔ה יָשׁ֖וּב e pergunte');
INSERT INTO verses VALUES (12287, 15, 10, 30, 'e dos filhos de páta Moabe עַדְנָ֣א e em geral Benaiá obras de Mattenya Betsalel e construção עמנואל');
INSERT INTO verses VALUES (12288, 15, 10, 31, 'e-filhos-de חרם אליעזר ישיה מלכייה Shema-yah Simeão');
INSERT INTO verses VALUES (12289, 15, 10, 32, '[בְּנְיָמִ֥ן] [מַלּ֖וּךְ] [שְׁמַרְיָֽה׃]');
INSERT INTO verses VALUES (12290, 15, 10, 33, 'מבני chasum מתְּנַ֤י מתַּתָּה֙ זָבָ֣ד אליפלט יְרֵמַ֥י מְנַשֶּׁה שִׁמְעִֽי׃');
INSERT INTO verses VALUES (12291, 15, 10, 34, 'de-filhos-de filhos-de [מַעֲדַ֥י] [עַמְרָ֖ם] [וְאוּאֵֽל׃]');
INSERT INTO verses VALUES (12292, 15, 10, 35, 'בְּנָיָ֥ה BEDIYA');
INSERT INTO verses VALUES (12293, 15, 10, 36, 'VANYA מרמות Eliasibe');
INSERT INTO verses VALUES (12294, 15, 10, 37, 'MATANIA מַתְּנַ֖י');
INSERT INTO verses VALUES (12295, 15, 10, 38, 'UBANI UBINUI SHIMEI:');
INSERT INTO verses VALUES (12296, 15, 10, 39, 'VESHLEMEIA e-Natã VAADAYA:');
INSERT INTO verses VALUES (12297, 15, 10, 40, 'MACHNADAVI sexto Šāray:');
INSERT INTO verses VALUES (12298, 15, 10, 41, 'ʿAzaryēl vešelemiyāhū Šamarjah');
INSERT INTO verses VALUES (12299, 15, 10, 42, 'shalom אמירה José');
INSERT INTO verses VALUES (12300, 15, 10, 43, 'mibney Nevō Yəʿīēl Mattityāh Zavād Zəbīnā וְיוֹאֵ֖ל בְּנָיָֽה׃');
INSERT INTO verses VALUES (12301, 15, 10, 44, 'todo estes [**נָשְׂא֖וּ] [נָשִׁ֣ים] [נָכְרִיּ֑וֹת] [וְיֵ֣שׁ] mulheres [נָשִׁ֔ים] filhos');
INSERT INTO books VALUES (16, 'NEH', 'Neemias', 'AT', 13);
INSERT INTO chapters VALUES (414, 16, 1, 11);
INSERT INTO verses VALUES (12302, 16, 1, 1, 'palavras-de Neemias filho-de e-houve E-foi em-mês-de ano-de vinte e-eu estava em-Susã a-fortaleza');
INSERT INTO verses VALUES (12303, 16, 1, 2, 'E-veio Hanani um de-irmãos-meus ele e-homens de-Judá e-perguntei-lhes sobre os-judeus o-escape que restaram de o-cativeiro e-sobre Jerusalém');
INSERT INTO verses VALUES (12304, 16, 1, 3, 'e-disseram para-mim os-restantes que restaram de o-cativeiro nome na-província em-mal grande e-em-opróbrio e-muro-de Jerusalém derribado e-portas-suas queimadas em-o-fogo');
INSERT INTO verses VALUES (12305, 16, 1, 4, 'e-houve [כְּשָׁמְעִ֣י] a as-palavras estes sentei e-chorei e-lamentei dias e-estive jejuando e-orando diante-de Elohim-de os-céus');
INSERT INTO verses VALUES (12306, 16, 1, 5, 'e-disse ah yhwh Elohim-de os-céus o-Elohim o-grande e-o-terrível guardador-de a-aliança e-misericórdia para-amadores-seus e-para-guardadores-de mandamentos-seus');
INSERT INTO verses VALUES (12307, 16, 1, 6, 'seja por-favor ouvido-teu atento e-olhos-teus abertos para-ouvir a oração-de eu que eu o-dia diante-de-ti o-dia dia e-noite sobre filhos-de Israel servos-teus e-confessando sobre para-ti filhos-de Israel que pecamos para-ti e-eu e-casa-de pai-meu pecamos');
INSERT INTO verses VALUES (12308, 16, 1, 7, 'corromper corrompemos para-ti e-não guardamos a os-mandamentos e-a os-estatutos e-a os-juízos que ordenaste a Moisés servo-teu');
INSERT INTO verses VALUES (12309, 16, 1, 8, 'lembra-de por-favor a a-palavra que ordenaste dizendo Moisés servo-teu para-dizer vós transgredirdes eu espalharei vós entre-os-povos');
INSERT INTO verses VALUES (12310, 16, 1, 9, 'e-voltardes a-mim e-guardardes mandamentos-meus e-fizerdes eles se for banido-vosso na-extremidade-de os-céus de-lá ajuntá-los-ei a o-lugar que escolhi para-fazer-habitar a nome-meu nome');
INSERT INTO verses VALUES (12311, 16, 1, 10, 'e-eles servos-teus e-povo-teu que resgataste com-força-tua a-grande e-com-mão-tua a-forte');
INSERT INTO verses VALUES (12312, 16, 1, 11, 'ah Adonai seja por-favor ouvido-teu atento a oração-de servo-teu e-a oração-de servos-teus os-desejosos para-temer o-dia nome-teu e-faze-prosperar agora para-servo-teu o-dia e-dá-o para-compaixões diante-de o-homem esta e-eu era copeiro para-o rei');
INSERT INTO chapters VALUES (415, 16, 2, 20);
INSERT INTO verses VALUES (12313, 16, 2, 1, 'e-houve em-mês-de nisã ano-de vinte para-artaxerxes o-rei vinho diante-dele e-levantei a o-vinho e-dei para-o-rei e-não era mau diante-de-ele');
INSERT INTO verses VALUES (12314, 16, 2, 2, 'E-disse para-mim o-rei [מַדּ֣וּעַ] faces-tuas más e-tu não-és doente não-há este porque mãe mau coração e-temi muito muito');
INSERT INTO verses VALUES (12315, 16, 2, 3, 'e-disse para-o-rei o-rei para-sempre viva por-que não serão-más face-de que a-cidade casa-de sepulturas-de pais-meus desolada e-portas-suas consumidos em-o-fogo');
INSERT INTO verses VALUES (12316, 16, 2, 4, 'E-disse a-mim o-rei sobre tu isto tu pedindo e-orei a Elohim-de os-céus');
INSERT INTO verses VALUES (12317, 16, 2, 5, 'e-disse para-o-rei se bom o-rei bom e-se seja-bom servo-teu diante-de-ti que envies-me a Judá a cidade sepulturas-de pais-meus e-edificá-la-ei');
INSERT INTO verses VALUES (12318, 16, 2, 6, 'E-disse para-mim o-rei [וְהַשֵּׁגַ֣ל] sentada junto-a-ele até quando será ida-tua e-quando voltarás e-foi-bom diante-de o rei e-enviou-me a-ele para-ele tempo');
INSERT INTO verses VALUES (12319, 16, 2, 7, 'e-disse ao-rei se bom o-rei bom cartas deem o-rio sobre governadores-de até o-rio que façam-me-passar até que chegue a Judá');
INSERT INTO verses VALUES (12320, 16, 2, 8, 'e-carta a asafe guarda-de o-bosque que do-rei que dê a-mim madeiras para-fazer-vigas a portões-de a-fortaleza que da-casa a-ele a-cidade e-para-a-casa que eu-entrarei a-ela e-ele-deu a-mim o-rei conforme-mão-de Elohim-meu a-boa sobre-mim');
INSERT INTO verses VALUES (12321, 16, 2, 9, 'e-vim a governadores-de o-rio o-rio a-eles a-eles את cartas-de o-rei e-estendeu comigo o-rei príncipes-de valor e-cavaleiros');
INSERT INTO verses VALUES (12322, 16, 2, 10, 'E-ouviu sambalate o-horonita e-tobias o-servo o-amonita e-foi-mal a-eles mal grande que homem homem para-buscar bem para-filhos-de Israel');
INSERT INTO verses VALUES (12323, 16, 2, 11, 'e-vim a Jerusalém e-estive nome dias três');
INSERT INTO verses VALUES (12324, 16, 2, 12, 'e-levantei-me noite eu e-homens poucos comigo e-não contei para-homem o-que אֱלֹהַי deu a coração-meu para-fazer para-Ierusalém e-animal não-há comigo que se a-animal que eu montando nela');
INSERT INTO verses VALUES (12325, 16, 2, 13, 'e-saí em-porta-de o-vale noite e-a face-de olho o-dragão e-a porta-de o-lixo e-estive examinando em-muros-de Jerusalém que e-portas-suas consumidos em-o-fogo');
INSERT INTO verses VALUES (12326, 16, 2, 14, 'e-passei a portão a-fonte e-a tanque-de o-rei e-não-há lugar para-o-animal para-passar debaixo-de-mim');
INSERT INTO verses VALUES (12327, 16, 2, 15, 'e-estive subindo no-ribeiro noite e-estive examinando no-muro e-voltei e-vim em-porta-de o-vale e-voltei');
INSERT INTO verses VALUES (12328, 16, 2, 16, 'e-os-oficiais não souberam onde fui e-o-que eu fez e-para-os-judeus e-para-os-sacerdotes e-para-os-nobres e-para-os-oficiais e-para-resto-de fez a-obra até não não contei');
INSERT INTO verses VALUES (12329, 16, 2, 17, 'e-disse a-eles vós vendo o-mal que nós nela que Jerusalém destruída e-portas-suas queimadas no-fogo vinde e-construamos a muro-de Jerusalém e-não sejamos mais opróbrio');
INSERT INTO verses VALUES (12330, 16, 2, 18, 'e-contei a-eles a mão אֱלֹהַי que ela boa sobre-mim e-também palavras-de o-rei que palavras-de para-mim e-disseram levantemo-nos e-construamos e-fortaleceram mãos-deles para-o-bem');
INSERT INTO verses VALUES (12331, 16, 2, 19, 'E-ouviu Sambalate o-horonita e-Tobias o-servo o-amonita e-Gesém o-árabe e-zombaram para-nós e-desprezaram sobre-nós e-disseram que a-coisa o-este que vós fazendo acaso o-rei vós rebelando');
INSERT INTO verses VALUES (12332, 16, 2, 20, 'e-respondi a-eles palavra e-disse a-eles Elohim-de os-céus ele fará-prosperar para-nós e-nós servos-dele levantaremos e-construiremos e-para-vós não há porção e-justiça e-memorial em-Jerusalém');
INSERT INTO chapters VALUES (416, 16, 3, 38);
INSERT INTO verses VALUES (12333, 16, 3, 1, 'E-levantou Eliasibe o-sacerdote o-grande e-irmãos-de-o os-sacerdotes e-construíram a portão o-rebanho eles consagraram-no [דַּלְתֹתָ֑יו] portas-dele e-até torre-de até consagraram-no até torre-de Hananel');
INSERT INTO verses VALUES (12334, 16, 3, 2, 'e-sobre mão-dele construíram homens-de Jericó e-sobre mão-dele construiu Zacur filho-de Imri');
INSERT INTO verses VALUES (12335, 16, 3, 3, 'e-את portão os-peixes construíram filhos-de os-Senaá eles cobriram-no [וֽ͏ַיַּעֲמִ֙ידוּ֙] portas-dele fechaduras-dele e-ferrolhos-dele');
INSERT INTO verses VALUES (12336, 16, 3, 4, 'e-sobre mão-deles reparou Meremote filho-de Urias filho-de o-Coz e-sobre mão-deles reparou Mesulão filho-de Berequias filho-de Mesezabeel e-sobre mão-deles reparou Zadoque filho-de Baaná');
INSERT INTO verses VALUES (12337, 16, 3, 5, 'e-sobre mão-deles repararam os-tecoítas e-nobres-deles não trouxeram pescoço-deles em-trabalho-de adonaies-deles');
INSERT INTO verses VALUES (12338, 16, 3, 6, 'e-את portão-de a-velha repararam Joiada filho-de Paseá e-Mesulão filho-de Besodias eles cobriram-no [וּמַנְעֻלָ֖יו] portas-dele e-fechaduras-dele e-ferrolhos-dele');
INSERT INTO verses VALUES (12339, 16, 3, 7, 'e-sobre mão-deles reparou Melatias o-gibeonita e-Jadom o-meronotita homens-de Gibeom e-a-Mispá para-trono-de governador-de o-rio o-rio');
INSERT INTO verses VALUES (12340, 16, 3, 8, 'sobre mão-dele reparou Uziel filho-de Haraaías ourives e-sobre mão-dele reparou Hananyah filho-de até e-abandonaram Jerusalém até o-muro a-larga');
INSERT INTO verses VALUES (12341, 16, 3, 9, 'e-sobre mão-deles segurou Refaías filho-de Hur príncipe metade distrito Jerusalém');
INSERT INTO verses VALUES (12342, 16, 3, 10, 'e-sobre mão-deles segurou Jedaías filho-de Harumafe e-diante-de casa-dele e-sobre mão-dele segurou Hatus filho-de Hasabneías');
INSERT INTO verses VALUES (12343, 16, 3, 11, 'medida segunda segurou Malquias filho-de Harim e-Hasube filho-de filho-de Moabe e-a torre-de os-fornos');
INSERT INTO verses VALUES (12344, 16, 3, 12, 'e-sobre mão-dele segurou Salum filho-de o-perfumista príncipe metade ele Jerusalém ele e-filhas-dele');
INSERT INTO verses VALUES (12345, 16, 3, 13, 'את portão-de o-vale segurou Hanum e-habitantes-de Zanoa eles construíram-no [וֽ͏ַיַּעֲמִ֙ידוּ֙] portas-dele fechaduras-dele e-ferrolhos-dele e-mil côvado na-muralha até portão-de o-lixo');
INSERT INTO verses VALUES (12346, 16, 3, 14, 'e-את portão o-lixo segurou Malquias filho-de Recabe príncipe distrito-de casa-de ele ele construirá-o e-levantará portas-dele fechaduras-dele e-ferrolhos-dele');
INSERT INTO verses VALUES (12347, 16, 3, 15, 'e-את portão-de a-fonte segurou Salum filho-de todo Hozé comandante-de ele a-Mispá ele construirá-o e-cobrirá-o portas-dele fechaduras-dele e-ferrolhos-dele e muralha-de tanque-de o-Siloé para-jardim- o-rei e-até os-degraus os-que-descem de-cidade-de Davi');
INSERT INTO verses VALUES (12348, 16, 3, 16, 'depois-dele segurou Neemias filho-de Azboque príncipe metade distrito-de casa-de Zur até diante-de sepulcros-de Davi e-até o-tanque o-feito e-até casa os-valentes');
INSERT INTO verses VALUES (12349, 16, 3, 17, 'depois-dele seguraram os-levitas Reum filho-de filhos-de sobre mão-dele segurou Hasabias príncipe-de metade-de distrito-de Queila para-distrito-dele');
INSERT INTO verses VALUES (12350, 16, 3, 18, 'depois-dele seguraram irmãos-deles em-o Bavai filho-de Henadade príncipe metade-de distrito Queila');
INSERT INTO verses VALUES (12351, 16, 3, 19, 'e-fortaleceu sobre auxiliar Ezer filho-de Jesua príncipe a-Mizpá medida segunda defronte subida-de a-armaduras o-ângulo');
INSERT INTO verses VALUES (12352, 16, 3, 20, 'depois-dele reparou reparou bendito filho-de medida segunda de o-ângulo até porta-de casa Eliasibe o-sacerdote o-grande');
INSERT INTO verses VALUES (12353, 16, 3, 21, 'depois-dele reparou Meremote filho-de Urias filho-de o-Coz medida segunda desde-porta-de casa Eliasibe e-até fim-de casa Eliasibe');
INSERT INTO verses VALUES (12354, 16, 3, 22, 'e-depois-dele repararam os-sacerdotes homens-de a-planície');
INSERT INTO verses VALUES (12355, 16, 3, 23, 'depois-dele reparou Benjamim e-Hasube diante casa-deles depois-dele reparou Azarias filho-de Maaseias filho-de Ananias ao-lado-de casa-dele');
INSERT INTO verses VALUES (12356, 16, 3, 24, 'depois-dele reparou Binui filho-de Henadade medida segunda de-casa-de Azarias até o-ângulo e-até a-esquina');
INSERT INTO verses VALUES (12357, 16, 3, 25, 'Palal filho-de Uzai desde-em-frente-de o-ângulo e-a-torre a-que-sai desde-casa-de o rei a-superior que para-pátio-de a-guarda atrás-dele Pedaías filho-de Parós');
INSERT INTO verses VALUES (12358, 16, 3, 26, 'e-os-netineus foram habitavam em-o-Ofel até diante porta-de as-águas para-o-oriente e-a-torre a-que-sai');
INSERT INTO verses VALUES (12359, 16, 3, 27, 'depois-dele repararam os-tecoítas medida segunda desde-em-frente-de a-torre a-grande a-que-sai e-até muro-de o-Ofel');
INSERT INTO verses VALUES (12360, 16, 3, 28, 'de-cima-de portão os-cavalos repararam os-sacerdotes homem para-em-frente-de casa-dele');
INSERT INTO verses VALUES (12361, 16, 3, 29, 'depois-dele reparou Zadoque filho-de diante em-frente-de casa-dele e-após-ele reparou Semaías filho-de Secanias guardião portão-de o-oriente');
INSERT INTO verses VALUES (12362, 16, 3, 30, 'ele-fortaleceu Hananias filho-de Selemias e-Hanun filho-de Salafe o-sexto medida segundo depois-dele ele-fortaleceu Mesulão filho-de Berequias diante câmara-sua');
INSERT INTO verses VALUES (12363, 16, 3, 31, 'ele-fortaleceu Malquias filho-de o-ourives até casa os-netinins e-os-mercadores diante portão o-posto-de-comando e-até câmara-alta-de a-esquina');
INSERT INTO verses VALUES (12364, 16, 3, 32, 'e-entre câmara-alta-de a-esquina para-portão-de o-rebanho eles-fortaleceram os-ourives e-os-mercadores');
INSERT INTO verses VALUES (12365, 16, 3, 33, 'e-houve como-que ouviu Sambalate porque nós construindo a a-ele e-acendeu-se a-ele e-irou-se muito e-escarneceu sobre os-judeus');
INSERT INTO verses VALUES (12366, 16, 3, 34, 'E-disse diante-de irmãos-seus e-exército-de Samaria E-disse E-disse os-judeus os-miseráveis fazendo acaso-abandonarão para-eles a-eles acaso-completarão em-o-dia acaso-darão-vida a as-pedras de-montões-de o-pó e-elas queimadas');
INSERT INTO verses VALUES (12367, 16, 3, 35, 'e-Tobias o-amonita junto-a-ele E-disse também que eles construindo se subir raposa e-romperá muro-de pedras-deles');
INSERT INTO verses VALUES (12368, 16, 3, 36, 'ouviu Elohim-nosso porque fomos desprezo e-faze-voltar opróbrio-deles a cabeça-deles e-dá-os para-despojo em-terra-de cativeiro');
INSERT INTO verses VALUES (12369, 16, 3, 37, 'e-a cubras sobre iniquidade-deles e-pecado-deles que a seja-apagado porque provocaram-à-ira diante-de os-construtores');
INSERT INTO verses VALUES (12370, 16, 3, 38, 'e-construímos a o-muro e-foi-ligado todo e-houve até metade-sua E-foi coração ao-povo para-fazer');
INSERT INTO chapters VALUES (417, 16, 4, 17);
INSERT INTO verses VALUES (12371, 16, 4, 1, 'e-houve quando ouviu Sambalate e-Tobias e-os-árabes e-os-amonitas e-os-asdoditas porque subiu restauração para-muros-de Jerusalém porque começaram as-brechas a-eles muito a-eles muito');
INSERT INTO verses VALUES (12372, 16, 4, 2, 'e-conspiraram todos-eles juntos para-vir para-lutar em-Jerusalém e-para-fazer a-ele confusão');
INSERT INTO verses VALUES (12373, 16, 4, 3, 'e-oramos a Elohim-nosso e-estabelecemos guarda sobre-eles de-dia e-de-noite de-faces-deles');
INSERT INTO verses VALUES (12374, 16, 4, 4, 'E-disse Judá falhou força o-carregador e-o-pó muito e-nós não podemos para-construir na-muralha');
INSERT INTO verses VALUES (12375, 16, 4, 5, 'e-disseram inimigos-nossos não saberão e-não verão até que viremos a meio-deles e-mataremos-eles e-faremos-cessar a o-trabalho');
INSERT INTO verses VALUES (12376, 16, 4, 6, 'e-houve conforme- vieram os-judeus os-habitantes junto-deles e-disseram a-nós dez vezes de-todo os-lugares que voltareis sobre-nós');
INSERT INTO verses VALUES (12377, 16, 4, 7, 'e-estabeleci de-partes-baixas para-o-lugar de-após para-a-muralha e-estabeleci a o-povo para-famílias com espadas-deles lanças-deles e-arcos-deles');
INSERT INTO verses VALUES (12378, 16, 4, 8, 'e-vi e-levantei-me e-disse a os-nobres e-a os-oficiais e-a Jetro o-povo a temais de-face-deles a Adonai o-grande e-o-terrível lembrai e-lutai sobre irmãos-vossos filhos-vossos e-filhas-vossas mulheres-vossas e-casas-vossas');
INSERT INTO verses VALUES (12379, 16, 4, 9, 'e-houve quando ouviram inimigos-nossos porque foi-conhecido para-nós e-frustrou Elohim a conselho-deles todos-nós a a-muralha homem a trabalho-seu');
INSERT INTO verses VALUES (12380, 16, 4, 10, 'e-houve de o-dia aquele metade jovens-meus fazendo no-trabalho e-metade-deles segurando e-as-lanças os-escudos e-os-arcos e-as-couraças e-os-príncipes atrás-de todo casa Judá');
INSERT INTO verses VALUES (12381, 16, 4, 11, 'os-construtores na-muralha e-os-carregadores na-carga carregando com-uma sua-mão fez no-trabalho e-uma segurando a-arma');
INSERT INTO verses VALUES (12382, 16, 4, 12, 'e-os-construtores homem espada-sua amarrados sobre lombos-seus e-constroem [בַּשּׁוֹפָ֖ר] na-trombeta');
INSERT INTO verses VALUES (12383, 16, 4, 13, 'e-disse a os-nobres e-a os-oficiais e-a Jetro o-povo [וַאֲנַ֗חְנוּ] [נִפְרָדִים֙] [עַל־הַ֣חוֹמָ֔ה] e nós [אִ֥ישׁ] sobre o-muro distantes homem');
INSERT INTO verses VALUES (12384, 16, 4, 14, 'em-o-lugar que ouvi-reis a voz-de o-shofar para lá [אֵלֵ֑ינוּ] a-nós Elohim-nosso [לָֽנוּ] para-nós');
INSERT INTO verses VALUES (12385, 16, 4, 15, 'e nós fazendo [בַּמְּלָאכָ֑ה] e-metade-deles segurando [בָּֽרְמָחִ֔ים] [מֵעֲל֣וֹת] no-alvorada até tset as-estrelas');
INSERT INTO verses VALUES (12386, 16, 4, 16, 'também em-o-tempo הַהִיא֙ eu-disse para-o-povo homem וְנַעֲר֔וֹ יָלִ֖ינוּ no-meio-de Jerusalém e sejam para nós a-noite mishmar obra obra');
INSERT INTO verses VALUES (12387, 16, 4, 17, 'e não há eu e-meus-irmãos e meus jovens e homens do mishmar que após-mim não-há nós פֹּשְׂטִים nossos vestuários homem as-águas as-águas');
INSERT INTO chapters VALUES (418, 16, 5, 19);
INSERT INTO verses VALUES (12388, 16, 5, 1, 'e-foi clamor-de o-povo e suas mulheres grande a irmaos-deles os-judeus');
INSERT INTO verses VALUES (12389, 16, 5, 2, 'e há que אֹמְרִים Nosso filhos וּבְנֹתֵ֖ינוּ nós muitos וְנִקְחָ֥ה דָגָ֖ן וְנֹאכְלָ֥ה וְנִחְיֶֽה׃');
INSERT INTO verses VALUES (12390, 16, 5, 3, 'וְיֵשׁ֙ que אֹמְרִים שְׂדֹתֵ֛ינוּ וּכְרָמֵ֥ינוּ e-nossas-filhas nós עֹרְבִ֑ים e tomaremos grão na fome');
INSERT INTO verses VALUES (12391, 16, 5, 4, 'haverá que אומרים para nós prata segundo a medida o-rei nossas terras e-nossos-carmelos:');
INSERT INTO verses VALUES (12392, 16, 5, 5, 'e-agora como o grão nosso irmão nossos ossos como eles נוּ בָּנֵינֻהוּ e-eis nós כֹ֠בְשִׁים a נוּנֵ֨ינוּ e-a נוֹתֵינֻהוּ בָּנֹות לַעֲבָדִים e há מִבָּנֹותֵינֻהוּ נִכְבַּשׁוֹת֙ e-não-há a-El יָדֵינֻהוּ וּשֲׂדוֹתֵינֻהוּ וּכְרָמֵינֻהוּ לַאֲחֵרִים׃');
INSERT INTO verses VALUES (12393, 16, 5, 6, 'e se fez amargo a-mim muito como-que ouvi a seu-grito e-a as-palavras as estas');
INSERT INTO verses VALUES (12394, 16, 5, 7, 'e reinou meu-líbhi sobre mim e disputei a os que se achavam e-a a-eles e-eu-disse a-eles preço homem-de em seu irmão vós e dei sobre-eles assembleia grande:');
INSERT INTO verses VALUES (12395, 16, 5, 8, 'e-eu-disse a-eles nós Compramos a nosso-irmãos os judeus os vendidos לַגּוֹיִם֙ para vendê-los e-também vós vende-os a seus irmãos e foram vendidos - para-nós e calaram-se e-não מצאו palavra');
INSERT INTO verses VALUES (12396, 16, 5, 9, 'não bom a palavra que vós fazendo Há-lo com medo de Elohim-nosso vocês andem de-herpah as-nações אֹיְבֵֽינוּ׃');
INSERT INTO verses VALUES (12397, 16, 5, 10, 'e-também eu irmãos-meus e-nay nozim neles prata ve-dagan na''azvah- נָ֖א a ha-massa'' a-esta');
INSERT INTO verses VALUES (12398, 16, 5, 11, 'הָשׁוֹבּוּ por-favor a-eles ke-hayyom sadoteyhem karmitheyhem zaytitehem e-as e-milhares-de a-prata e-a-trigo הַתִּ֖רְוֹשׁ e Hitzar que vós levaremos neles');
INSERT INTO verses VALUES (12399, 16, 5, 12, 'e-disseram carregaremos e deles não buscaremos assim seremos-feitos conforme tu e-digo e-chamei a os-sacerdotes e eu os fiz para-fazer אֶת-הַדָּבָר a-esta');
INSERT INTO verses VALUES (12400, 16, 5, 13, 'também dividi-me eu me dividi e eu disse assim seria ungido o Elohim a todo o homem que não levantou-se a será o-este de sua casa e alcançou-o e assim será נעוּר ורק e-disseram todo a-assembleia אמין WAYY''HALLU'' a yhwh E-fez o-povo כַּדָּבָ֥ר a-esta');
INSERT INTO verses VALUES (12401, 16, 5, 14, 'também MIYOM que ordenou a-mim para-ser- Pecham em-terra-de Yehuda Mishnata VINTE VE''AD Shanat trinta e-shtayim para-arthachshata o-rei dois שִׁיתִֽים dez eu e-achi pão a-facha não comi:');
INSERT INTO verses VALUES (12402, 16, 5, 15, 'e as pequenas os-rieloinim que diante-dei prestem-atenção sobre o povo e-tomaram dentre-eles na-lechem e-yayin outro também pesos-de-prata quarenta também seus jovens dominaram sobre de-diante-de e-eu não esta assim de-face-de medo de Elohim');
INSERT INTO verses VALUES (12403, 16, 5, 16, 'e-tambem בִּמְלֶ֜אכֶת a muralha esta eu fortaleci-me e a terra não compramos e-todo meus jovens agrupamentos nome sobre o-trabalho');
INSERT INTO verses VALUES (12404, 16, 5, 17, 'e os judeus e os governadores cem e cinquenta homem e os que vêm nossos de as-nações que nossas voltas sobre minha mesa');
INSERT INTO verses VALUES (12405, 16, 5, 18, 'e que ser se fizeram para-o-dia um boi um ovelhas seis-de puras וְצִפֳּרִים֙ e-entre a-mim וּבֵ֨ין dez יָמִ֛ים em-todo pão לְהַרְבֵּ֑ה não este לֶ֤חֶם הַפֶּחָה֙ não בִקַּ֔שְׁתִּי porque כָֽבְדָ֥ה o-trabalho sobre o-povo a-esta');
INSERT INTO verses VALUES (12406, 16, 5, 19, '[זָכְרָה־לִּ֥י] para-mim Elohim-meu [כֹּ֥ל] todo que fiz sobre o-povo a-esta');
INSERT INTO chapters VALUES (419, 16, 6, 19);
INSERT INTO verses VALUES (12407, 16, 6, 1, 'e-houve quando ouviremos לְסַנְבַלַּ֣ט e-Tobias e para o gershem o árabe - e além disso nossos inimigos que eu edifiquei a o-muro e-não restou também destruição também até o tempo aquela portas não eu edifiquei nos shá''arim:');
INSERT INTO verses VALUES (12408, 16, 6, 2, 'e-enviou [סַנְבַלַּ֤ט] e-Gesém a-mim-adai dizendo [לְכָ֞ה] [וְנִֽוָּעֲדָ֥ה] juntos [בַּכְּפִירִ֖ים] [בְּבִקְעַ֣ת] seu e-eles [חֹֽשְׁבִ֔ים] para-fazer a-mim mal');
INSERT INTO verses VALUES (12409, 16, 6, 3, '[וָאֶשְׁלְחָ֨ה] em-eles mensageiros dizendo obra [גְדוֹלָה֙] eu fez e-não posso para-descer por-que [תִשְׁבַּ֤ת] הַמְּלָאכָה como-que [אַרְפֶּ֔הָ] [וְיָרַדְתִּ֖י] a-vós');
INSERT INTO verses VALUES (12410, 16, 6, 4, 'e-ele-mandou a-mim como a palavra este quatro vezes [וָאָשִׁ֥יב] eles como a palavra a-esta');
INSERT INTO verses VALUES (12411, 16, 6, 5, 'e-enviou אלי Sanvalat kadavar este vez cincentésima a seu jovem e carta aberta em-mão-sua');
INSERT INTO verses VALUES (12412, 16, 6, 6, 'escrito nela [בַּגּוֹיִ֤ם] נִשְׁמַע e chuvas disse tu e os judeus que pensam para se revoltar sobre tu tu construindo a muralha e-tu a-eles para-eles para- Rei segundo-as-palavras as estas');
INSERT INTO verses VALUES (12413, 16, 6, 7, 'e-também profetas tu os estabeleceste לִקְרֹא֩ עָלֶ֨יךָ dizendo dizendo rei e-agora e-agora será ouvido para-o-rei como-as-coisas e-agora e-agora vai וְנִֽוָּעֲצָ֖ה juntos-verso');
INSERT INTO verses VALUES (12414, 16, 6, 8, 'וָאֶשְׁלְחָ֤ה a-ele dizendo não נִֽהְיָה֙ como-as-coisas os-estes que tu אוֹמֵ֑ר que de-te-o tu בוֹדָֽאם׃');
INSERT INTO verses VALUES (12415, 16, 6, 9, 'que כֻלָּ֗ם temendo nós dizendo serão curados mãos-suas de a-obra e-não e-agora וְעַתָּה חזק a יָדָֽי׃');
INSERT INTO verses VALUES (12416, 16, 6, 10, 'e eu [בֵּ֣ית] casa [בֶן־דְּלָיָ֛ה] filho-de [וְה֣וּא] filho-de E-disse e-ele [אֶל־בֵּ֨ית] E-disse [אֶל־תּ֣וֹךְ] a casa os-אלהים a que [בָּאִ֣ים] [לְהָרְגֶ֔ךָ] portas-de o-templo porque vindo para-te-matar');
INSERT INTO verses VALUES (12417, 16, 6, 11, 'e- disse o homem como eu fugirá e-quem como eu que virá a não e viverá não e entrarei');
INSERT INTO verses VALUES (12418, 16, 6, 12, 'e reconheci e-eis não Elohim que porque a visão palavra sobre-mim e-Tobias וְסַנְבַלַּ֖ט sua-recompensa:');
INSERT INTO verses VALUES (12419, 16, 6, 13, 'para-que [שָׂכוּר֙] ele para  [וְאֶֽעֱשֶׂה־כֵּ֖ן] e-e''asah- assim a-eles e-será mal para-nome-de mau para-o-fim-de');
INSERT INTO verses VALUES (12420, 16, 6, 14, 'זָכְרָ֧ה Elohim-me לְטוֹבִיָּ֥ה וּלְסַנְבַלַּ֖ט כְּמַעֲשָׂ֣יו Estas e-tambem לְנוֹעַדְיָ֤ה a profetisa e-leyther os-profetas que foram meiyr''ayim otiy:');
INSERT INTO verses VALUES (12421, 16, 6, 15, 'e-foi-completada a-muralha be-eshrim e-cinco le-elol la-chamishshim u-shanim dia');
INSERT INTO verses VALUES (12422, 16, 6, 16, 'e-houve como ouviram todo ao''eveinu va-yire''u todo as-nações que muito e caíram e-souberam que va-yed''u porque de-junto-de Elohim-nosso foi feita a obra a esta');
INSERT INTO verses VALUES (12423, 16, 6, 17, 'também em-os-dias aqueles multiplicam que enterram Judá suas sepulturas andando sobre bem-aventurados e-que bem-aventurados באות a-eles');
INSERT INTO verses VALUES (12424, 16, 6, 18, 'porque רבים em Judá por seus pais a-ele a-ele ele CHANT ele LISHKANYAH filho-de tomou VIYOHYACHANAN seu-filho tomou a filha-de MESHULAM filho BEREKHYAH');
INSERT INTO verses VALUES (12425, 16, 6, 19, 'também TOVOTAY eram אומרים diante-de-mim UDVARAY foram MOZIYIM a-ele AGOROT enviou Tobiah LEYARENY');
INSERT INTO chapters VALUES (420, 16, 7, 72);
INSERT INTO verses VALUES (12426, 16, 7, 1, 'e-houve como-que ניבנתה הַחוֹמָ֔ה ואימד הדלות ויפקדו os que contam והמשוררים ve-halviyim');
INSERT INTO verses VALUES (12427, 16, 7, 2, '[וָאֲצַוֶּ֞ה] a Hanani meu irmão: e-a [הַבִּירָ֖ה] príncipe a-cidadela sobre Jerusalém porque ele como homem אמת E-viu a Elohim');
INSERT INTO verses VALUES (12428, 16, 7, 3, 'a-eles não a-eles não Jerusalém até Chapelado o-sol e-ad eles eles yigafu hadlatot ve''achozu vehamaid mishmerot habitantes-de Jerusalém homem b''mishmaro e-homem diante-de diante');
INSERT INTO verses VALUES (12429, 16, 7, 4, 'vehaiyr rachbat yadayim e grande e-o-povo pouco b''tokha e-não-há בתים בנונים׃');
INSERT INTO verses VALUES (12430, 16, 7, 5, 'E-colocou אֱלֹהַי a coração-meu [אֶת־הַחֹרִ֧ים] a [וְאֶת־הָעָ֖ם] e-a [וָֽאֶמְצָ֗א] e-a o-povo para-se-rir [בָּרִאשׁוֹנָ֔ה] סֵ֤פֶר [כָּת֥וּב] [בּֽוֹ׃] escrito em-ele');
INSERT INTO verses VALUES (12431, 16, 7, 6, 'Estas filhos-de a-província [הַמְּדִינָ֗ה] de-cativeiro-de o-exílio que ele-exilou [הֶגְלָ֔ה] rei Babilônia [בָּבֶ֑ל] [וַיָּשׁ֧וּבוּ] [לִֽירוּשָׁלַ֛͏ִם] homem para-cidade-sua');
INSERT INTO verses VALUES (12432, 16, 7, 7, 'os-que-vieram com Zorobabel Jesua [עֲ֠זַרְיָה] [רַֽעַמְיָ֨ה] [נַחֲמָ֜נִי] [מָרְדֳּכַ֥י] Mardoqueu Bilsã [בִּגְוַ֖י] Bigvai [בַּעֲנָ֑ה] Baaná número homens-de povo Israel');
INSERT INTO verses VALUES (12433, 16, 7, 8, 'filhos-de Parós dois-mil cem ve-shiv''ím e-dois');
INSERT INTO verses VALUES (12434, 16, 7, 9, 'filhos-de Sefatias três centenas setenta e-dois');
INSERT INTO verses VALUES (12435, 16, 7, 10, 'filhos-de Ara seis centenas cinquenta e-dois');
INSERT INTO verses VALUES (12436, 16, 7, 11, 'filhos-de Paate Moabe para-filhos-de Jesua [אַלְפַּ֕יִם] dois-mil e-oito centenas oito dez');
INSERT INTO verses VALUES (12437, 16, 7, 12, 'filhos-de Elão mil duzentos cinquenta e-quatro');
INSERT INTO verses VALUES (12438, 16, 7, 13, 'filhos-de Zatu oito centenas quarenta e-cinco');
INSERT INTO verses VALUES (12439, 16, 7, 14, 'filhos-de Zacai sete centenas e-sessenta');
INSERT INTO verses VALUES (12440, 16, 7, 15, 'filhos-de [בִנּ֔וּי] seis centenas quarenta e-oito');
INSERT INTO verses VALUES (12441, 16, 7, 16, 'filhos-de Bebai seis centenas vinte e-oito');
INSERT INTO verses VALUES (12442, 16, 7, 17, 'filhos-de Azgade dois-mil três centenas vinte e-dois');
INSERT INTO verses VALUES (12443, 16, 7, 18, 'filhos-de Adonicã seis centenas sessenta e-sete');
INSERT INTO verses VALUES (12444, 16, 7, 19, 'filhos-de Bigvai dois-mil sessenta e-sete');
INSERT INTO verses VALUES (12445, 16, 7, 20, 'filhos-de Adim seis centenas cinquenta e-cinco');
INSERT INTO verses VALUES (12446, 16, 7, 21, 'filhos-de Ater [תִּשְׁעִ֥ים] noventa e-oito');
INSERT INTO verses VALUES (12447, 16, 7, 22, 'filhos-de Hasum três centenas vinte e-oito');
INSERT INTO verses VALUES (12448, 16, 7, 23, 'filhos-de Besai três centenas vinte e-quatro');
INSERT INTO verses VALUES (12449, 16, 7, 24, 'filhos-de [חָרִ֔יף] cem dois dez');
INSERT INTO verses VALUES (12450, 16, 7, 25, 'filhos-de Gibeom noventa e-cinco');
INSERT INTO verses VALUES (12451, 16, 7, 26, 'homens-de casa-de pão [מֵאָ֖ה] cem oitenta e-oito');
INSERT INTO verses VALUES (12452, 16, 7, 27, 'homens-de Anatote cem vinte e-oito');
INSERT INTO verses VALUES (12453, 16, 7, 28, 'homens-de casa-de Azmavete quarenta e-dois');
INSERT INTO verses VALUES (12454, 16, 7, 29, 'homens-de Quiriate [יְעָרִים֙] Quefira e-Beerote sete centenas quarenta e-três');
INSERT INTO verses VALUES (12455, 16, 7, 30, 'homens-de [הָֽרָמָה֙] e-Geba seis centenas vinte e-um');
INSERT INTO verses VALUES (12456, 16, 7, 31, 'homens-de Micmás cem e-vinte e-dois');
INSERT INTO verses VALUES (12457, 16, 7, 32, 'homens-de casa-de El e-a-Ai cem vinte e-três');
INSERT INTO verses VALUES (12458, 16, 7, 33, 'homens-de [נְב֛וֹ] outro cinquenta e-dois');
INSERT INTO verses VALUES (12459, 16, 7, 34, 'filhos-de Elão outro mil duzentos cinquenta e-quatro');
INSERT INTO verses VALUES (12460, 16, 7, 35, 'filhos-de Harim três centenas e-vinte');
INSERT INTO verses VALUES (12461, 16, 7, 36, 'filhos-de Jericó três centenas quarenta e-cinco');
INSERT INTO verses VALUES (12462, 16, 7, 37, 'filhos-de Lode Hadide e-Ono sete centenas e-vinte e-um');
INSERT INTO verses VALUES (12463, 16, 7, 38, 'filhos-de Senaá três-de milhares nove centenas e-trinta');
INSERT INTO verses VALUES (12464, 16, 7, 39, 'o-sacerdotes filhos-de Yedayah para-casa-de Yeshua nove centenas setenta e-três');
INSERT INTO verses VALUES (12465, 16, 7, 40, 'filhos-de disse mil cinquenta e-dois');
INSERT INTO verses VALUES (12466, 16, 7, 41, 'filhos-de Pashur mil duzentos quarenta e-sete');
INSERT INTO verses VALUES (12467, 16, 7, 42, 'filhos-de Harim mil sete dez');
INSERT INTO verses VALUES (12468, 16, 7, 43, 'os-levitas filhos-de Yeshua [לִבְנֵ֥י] para-os-filhos-de [שִׁבְעִ֥ים] setenta e-quatro');
INSERT INTO verses VALUES (12469, 16, 7, 44, 'o-cantores filhos-de Asafe cem quarenta e-oito');
INSERT INTO verses VALUES (12470, 16, 7, 45, 'o-porteiros filhos-de Shallum filhos-de Ater filhos-de [חֲטִיטָ֖א] filhos-de Akkub filhos-de Hatita filhos-de Shobai cem trinta e-oito');
INSERT INTO verses VALUES (12471, 16, 7, 46, 'o-netinins filhos-de [בְנֵי־חֲשֻׂפָ֖א] filhos-de [טַבָּעֽוֹת] filhos-de Tabbaoth');
INSERT INTO verses VALUES (12472, 16, 7, 47, 'filhos-de [בְּנֵי־סִיעָ֖א] filhos-de [פָדֽוֹן] filhos-de Padon');
INSERT INTO verses VALUES (12473, 16, 7, 48, 'filhos-de Lebanah filhos-de Hagabah filhos-de');
INSERT INTO verses VALUES (12474, 16, 7, 49, 'filhos-de chanan filhos-de filhos-de');
INSERT INTO verses VALUES (12475, 16, 7, 50, 'filhos-de Re-ayah filhos-de retzin filhos-de');
INSERT INTO verses VALUES (12476, 16, 7, 51, 'filhos-de [בְּנֵי־עֻזָּ֖א] filhos-de uzzah filhos-de');
INSERT INTO verses VALUES (12477, 16, 7, 52, 'filhos-de [בְּנֵי־מְעוּנִ֖ים] filhos-de [*נפושסים] filhos-de');
INSERT INTO verses VALUES (12478, 16, 7, 53, 'filhos-de Bakbuk filhos-de Hakupha filhos-de Harhur');
INSERT INTO verses VALUES (12479, 16, 7, 54, 'filhos-de [בְּנֵֽי־מְחִידָ֖א] filhos-de Mehida filhos-de Harsha');
INSERT INTO verses VALUES (12480, 16, 7, 55, 'filhos-de Barkos filhos-de Sisera filhos-de Temah');
INSERT INTO verses VALUES (12481, 16, 7, 56, 'filhos-de Neziah filhos-de Hatipha');
INSERT INTO verses VALUES (12482, 16, 7, 57, 'filhos-de servos-de Shelomoh filhos-de [בְּנֵי־סוֹפֶ֖רֶת] filhos-de [פְרִידָֽא] filhos-de');
INSERT INTO verses VALUES (12483, 16, 7, 58, 'filhos-de [בְנֵי־דַרְק֖וֹן] filhos-de Darkon filhos-de Giddel');
INSERT INTO verses VALUES (12484, 16, 7, 59, 'filhos-de Shephatiah filhos-de Hattil filhos-de Pokereth a-Zebaim filhos-de');
INSERT INTO verses VALUES (12485, 16, 7, 60, 'todo [וּבְנֵ֖י] e-filhos-de servos-de Shelomoh três centenas noventa e-dois');
INSERT INTO verses VALUES (12486, 16, 7, 61, 'e-estes [הָֽעוֹלִים֙] de-Tel Melah Tel Harsha querubim [אַדּ֖וֹן] [וְאִמֵּ֑ר] e-não [יָכְל֗וּ] para-declarar casa-de pais-deles e-descendência-deles mãe eles eles');
INSERT INTO verses VALUES (12487, 16, 7, 62, 'filhos-de Delaiah filhos-de Tobiah filhos-de Nekoda seis centenas e-quarenta e-dois');
INSERT INTO verses VALUES (12488, 16, 7, 63, 'e-de os-sacerdotes filhos-de Hobaiah filhos-de o-Koz filhos-de Barzillai tomou tomou de-filhas-de Barzillai o-גִּלְעָדִי mulher E-chamou sobre nome-deles');
INSERT INTO verses VALUES (12489, 16, 7, 64, 'Estas procuraram escrito-deles o-genealogias e-não encontrado-se-é [וַיְגֹֽאֲל֖וּ] de o-sacerdócio');
INSERT INTO verses VALUES (12490, 16, 7, 65, 'E-disse o-governador a-eles que não eles-comerão de-santidade até até ficou-em-pé o-sacerdote para-Urim');
INSERT INTO verses VALUES (12491, 16, 7, 66, 'todo a-congregação como-um quatro miríade dois-mil três- centenas e-sessenta');
INSERT INTO verses VALUES (12492, 16, 7, 67, 'de-além-de servos-de-eles e-servas-de-eles Estas sete-de milhares três centenas trinta e-sete [וְלָהֶ֗ם] conselheiros [וּמְשֹׁ֣רֲר֔וֹת] duzentos e-quarenta e-cinco');
INSERT INTO verses VALUES (12493, 16, 7, 68, '[גְּמַלִּ֕ים] quatro centenas trinta e-cinco jumentos seis-de milhares sete centenas e-vinte');
INSERT INTO verses VALUES (12494, 16, 7, 69, 'e-mí-qtá cabeças-de הֽ͏ָאָב֔וֹת deram לַמְּלָאכָ֑ה הַתִּרְשָׁ֜תָא dar לָאוֹצָ֗ר ouro דַּרְכְּמֹנִ֥ים mil מִזְרָק֣וֹת חֲמִשִּׁ֔ים túnicas-de ko''hanim trinta e-cinco centenas');
INSERT INTO verses VALUES (12495, 16, 7, 70, 'e de cabeças dos pais deram para-tesouro-de a-obra ouro caminhos duas milhares e-prata minas אֶלְףַ֥יִם e-duzentos');
INSERT INTO verses VALUES (12496, 16, 7, 71, 'e-que eles-deram remanescente o-povo ouro dracmas duas miríade e prata centenas dois-mil e-túnicas-de sacerdotes sessenta e-sete');
INSERT INTO verses VALUES (12497, 16, 7, 72, 'e-habitaram os-sacerdotes e levitas e os contadores e os informantes e-de o povo e os cantores e-todo Israel em-cidades-de-eles e-chegou o-mês o-sétimo e-filhos-de Israel em-cidades-de-eles');
INSERT INTO chapters VALUES (421, 16, 8, 18);
INSERT INTO verses VALUES (12498, 16, 8, 1, 'e foram reunidos todo o-povo um um a no lugar público que diante-de shaar- as-águas e-disseram para Ezra o escriba para levar a yhwh lei-de Moisés que ordenou yhwh a Israel');
INSERT INTO verses VALUES (12499, 16, 8, 2, 'e levou Ezra o sacerdote a a lei diante-de o convênio me-ish e-tudo mulher e-todo que entende um em-dia um para-o-mes o sétimo');
INSERT INTO verses VALUES (12500, 16, 8, 3, 'e ele chamou nele diante-de a praça que diante-de shaar- as-águas de o-dia diante meio o-dia diante de os homens e-as-mulheres e os que entendem e ouvidos todo o-povo a livro-de ha-torah');
INSERT INTO verses VALUES (12501, 16, 8, 4, 'e-está-se-levantando Ezra o-escrevendo sobre torre- árvore- que fizeram para-a-palavra e-está-se-levantando ao-lado-de-lui Mattheus e-ouviu וַעֲנָיָה וְאוּרִיָּה וְחִלְקִיָּה וּמַעֲשֵׂיָ֖ה sobre direita-de-ele וּמִשְּׂמֹאל֗וֹ פְּדָיָה וּמִֽישָׁאֵ֧ל וּמַלְכִּיָּ֛ה וְחָשֻׁ֥ם וְחַשְׁבַּדָּ֖נָה Zekaryá Mishllem:');
INSERT INTO verses VALUES (12502, 16, 8, 5, 'e-abri Esra o-séfer aos-olhos-de todo o-povo porque ser todo o-povo foi e-abrindo-o estavam-se todo o-povo');
INSERT INTO verses VALUES (12503, 16, 8, 6, 'E-abençoou Esra a yhwh Elohim o-grande e-responderam todo o-povo אָמֵן אָמֵן בְּמֹ֣עַל mãos-deles וַיִּקְּד֧וּ וַיִּשְׁתַּחֲוֻ֛ a-yhwh אַפַּ֥יִם para-terra');
INSERT INTO verses VALUES (12504, 16, 8, 7, '[וְיֵשׁ֡וּעַ] [וּבָנִ֡י] [וְשֵׁרֵ֥בְיָ֣ה] [׀] [יָמִ֡ין] [עַקּ֡וּב] [שַׁבְּתַ֣י] [׀] [הֽוֹדִיָּ֡ה] [מַעֲשֵׂיָ֡ה] [קְלִיטָ֣א] [עֲזַרְיָה֩] [יוֹזָבָ֨ד] e os levitas [פְּלָאיָה֙] a o-povo [אֶת־הָעָ֖ם] e-o-povo sobre [עַל־עָמְדָֽם]');
INSERT INTO verses VALUES (12505, 16, 8, 8, 'e leram no livro na-lei Elohim escrito e sabedoria sabedoria e entenderam no estudo');
INSERT INTO verses VALUES (12506, 16, 8, 9, 'E-disse Neemias ele a instruções e Ezra o-sacerdote o escriba e-os-levitas os que entendem a o-povo para-todo o-dia o-dia santo- ele a-yhwh vosso-Elohim que [בוֹכִים֙] e-a chorarem porque choram todo o-povo quando ouvirem a palavras-de ha-torah');
INSERT INTO verses VALUES (12507, 16, 8, 10, 'E-disse a-eles venham comam masmanim e bebam mamatakim e enviem ofertas para-nao-haver firme a-ele porque o-dia o-dia para-Adonai-nosso e-a yhwh porque alegria yhwh ela de vossas fortalezas');
INSERT INTO verses VALUES (12508, 16, 8, 11, 'e-os-levitas pensamentos para-todo dizendo dizendo que o-dia o-dia santuário e-a se preparassem');
INSERT INTO verses VALUES (12509, 16, 8, 12, 'e saíram todo o-povo para comer e beber e lançassem maná e para fazer alegria que porque compreenderam nos palavras que a-eles para-eles');
INSERT INTO verses VALUES (12510, 16, 8, 13, 'e-no-dia [הַשֵּׁנִ֡י] [נֶאֶסְפוּ֩] cabeças-de os-pais para-todo o povo os-sacerdotes e os levitas a [וּלְהַשְׂכִּ֖יל] [אֶל־דִּבְרֵ֥י] e-para-saber a palavras-de ha-torah');
INSERT INTO verses VALUES (12511, 16, 8, 14, '[וַֽיִּמְצְא֖וּ] [כָּת֣וּב] [בַּתּוֹרָ֑ה] que tsi-vu-a yhwh pela-mão-de Moisés que vivam filhos-de Israel [בַּחֹ֥דֶשׁ] [הַשְּׁבִיעִֽי] no mês- הַשְׁבִיעִֽי׃');
INSERT INTO verses VALUES (12512, 16, 8, 15, 'e-que yasamû ve''ya''avirû voz em-todo arêhem dizendo dizendo tsavû hahar e trarão sobre zayit va''alei- madeira-de óleo va''alei haddas árvore תמרים ואלי madeira-de אבות para-fazer סוכות ככATOוב׃');
INSERT INTO verses VALUES (12513, 16, 8, 16, 'e-eles-saíram o-povo WAYYABIYU֒ WAYYAASU֩ a-eles סוכות homem sobre גגוֹ֙ ובחצרותיהם֔ e nas chãres casa o-Elohim e nos rivos portão as-águas e no riv portão-de Efrayim');
INSERT INTO verses VALUES (12514, 16, 8, 17, 'e fizeram todo o kahal os shabim de o shibi sukot e-habitaram que porque não fizeram nos dias Jeshua filho-de נ֥וּן até o-dia Israel até o-dia o-aquele muito שִׂמְחָה grande muito');
INSERT INTO verses VALUES (12515, 16, 8, 18, 'E-chamou [בְּסֵ֨פֶר] torah-de o-Elohim dia בְּי֔וֹם de o-dia הָֽרִאשׁ֔וֹן até o-dia [הָאַחֲר֑וֹן] e-ele-fizeram- [שִׁבְעַ֣ת] sete-de dias e-no-dia [עֲצֶ֖רֶת] עֲצֶ֖רֶת como-o-julgamento');
INSERT INTO chapters VALUES (422, 16, 9, 37);
INSERT INTO verses VALUES (12516, 16, 9, 1, '[וּבְיוֹם֩] vinte [וְאַרְבָּעָ֜ה] para-o-mês o-este [נֶאֶסְפ֤וּ] filhos-de Israel [וּבְשַׂקִּ֔ים] [וַאֲדָמָ֖ה] e-terra sobre-eles');
INSERT INTO verses VALUES (12517, 16, 9, 2, 'WAYYIVADLU semente Israel de-toda filhos-de ne-char WAYYAAMDU WAYYITWADU sobre חתאתיהם ואונות אבותיהם׃');
INSERT INTO verses VALUES (12518, 16, 9, 3, 'va-y-qa-ru-mu sobre [וַֽיִּקְרְא֗וּ] [בְּסֵ֨פֶר] [תּוֹרַ֧ת] yhwh yhwh elohim-deles o-dia o-dia [מִתְוַדִּ֣ים] [וּמִֽשְׁתַּחֲוִ֔ים] [לַיהוָ֖ה] a-yhwh אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (12519, 16, 9, 4, 'E-levantou sobre [הַלְוִיִּ֗ם] os-levitas Jeshua [קַדְמִיאֵ֧ל] [שְׁבַנְיָ֛ה] [בֻּנִּ֥י] filhos-de [בָּנִ֣י] filhos-de [וַֽיִּזְעֲקוּ֙] [בְּק֣וֹל] com-voz grande a yhwh אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (12520, 16, 9, 5, 'e-disseram [הַלְוִיִּ֡ם] [יֵשׁ֣וּעַ] [וְ֠קַדְמִיאֵל] filhos-de [חֲשַׁבְנְיָ֜ה] [שֵׁרֵֽבְיָ֤ה] [הֽוֹדִיָּה֙] [שְׁבַנְיָ֣ה] [פְתַֽחְיָ֔ה] [ק֗וּמוּ] [בָּרֲכוּ֙] a yhwh Elohim-vosso de [וִיבָֽרְכוּ֙] até [כְּבוֹדֶ֔ךָ] [וּמְרוֹמַ֥ם] nome kavodecha sobre todo ברכה');
INSERT INTO verses VALUES (12521, 16, 9, 6, 'você- yhwh yhwh לבדך fizeste a os-céus Sheméi os-céus e-todo a-terra a-terra e-todo que sobre-ela os mares e-todo que neles e-tu que vivificas a-ti todos eles e exércitos os-céus para-ti prostram-se');
INSERT INTO verses VALUES (12522, 16, 9, 7, 'você- yhwh yhwh o-Elohim que escolheste em Abraão e o saíste luzeiro como os Caldeus e colocaste seu nome Abraão');
INSERT INTO verses VALUES (12523, 16, 9, 8, 'e achaste a no seu coração estabelecido ante ti e cortaste com-ele a aliança para dar a terra o-cananeu o-heteu o amorriteu e o perizeu וְהַיְבוּסִ֥י וְהַגִּרְגָּשִׁ֖י para-dar לְזַרְע֑וֹ que a דְּבָרֶ֔יךָ porque justo tu');
INSERT INTO verses VALUES (12524, 16, 9, 9, 'E-viu a aflição-de [בְּמִצְרָ֑יִם] em-Egito e-a [עַל־יַם־סֽוּף] ouviste sobre mar-de juncos');
INSERT INTO verses VALUES (12525, 16, 9, 10, 'e-deu [אֹתֹ֨ת] [וּמֹֽפְתִ֜ים] [בְּפַרְעֹ֤ה] e-em-todo seus-servos e-em-todo que אַרְצ֔וֹ que soubeste porque [וַתַּֽעַשׂ־לְךָ֥] sobre-eles e-você-fez- para-ti nome como-no-dia a-esta');
INSERT INTO verses VALUES (12526, 16, 9, 11, '[וְהַיָּם֙] [בָּקַ֣עְתָּ] em-frente-de-eles [וַיַּֽעַבְר֥וּ] em-o-centro-de- o-mar em-a-terra-firmo e-a [בִמְצוֹלֹ֛ת] [כְּמוֹ־אֶ֖בֶן] [בְּמַ֥יִם] como eben');
INSERT INTO verses VALUES (12527, 16, 9, 12, 'וּבְעַמּ֣וּד עָנָן hinchitam de-dia uva''amud fogo noite para-iluminar a-eles a o-caminho que yelchu- em-ela');
INSERT INTO verses VALUES (12528, 16, 9, 13, 'e-sobre monte-de Sinai yaradta ve''aber ''immahem e-deu a-eles para-eles mishpatim yesharim ve''torot אֱמֶ֔ת chuqim e mandamentos bem:');
INSERT INTO verses VALUES (12529, 16, 9, 14, 'e-a sabáth seu santidade a-eles para-eles e mandamentos e estatutos e lei a-eles a-eles em-mão Moisés servo-teu');
INSERT INTO verses VALUES (12530, 16, 9, 15, 'e pão do céu deste a-eles para a fome e água de-miselá tu sacaste a-eles para-litzma''am E-disse a-eles para-vir para-possuir a a-terra que levantas-te a-eles mão-tua a-dar para-eles');
INSERT INTO verses VALUES (12531, 16, 9, 16, 'e-eles e-nossos-pai-s [הֵזִ֑ידוּ] e-ajamaram-se a seus-braços e-não ouviram a as-tua-m Mandamentos');
INSERT INTO verses VALUES (12532, 16, 9, 17, 'e-responderam para-ouvir e-não zakru niflaotekha que fizeste com-eles va''yakshu a arafam vayitnu- cabeça lashuv le''abdatam b''miryam va''atah Elohim סְלִיחוֹת חַנּוּן וְרַחֻם אֶֽרֶךְ־ אַפּוּיִם e-grande e-não עֲזַבְתֶּם׃');
INSERT INTO verses VALUES (12533, 16, 9, 18, 'certamente porque a-eles para-eles bezerro מַסּוֹכָה e-disseram este teu-Elohim que הֶעֱלָךָ֖ de-Egito וַיַעֲשׂוּ נֶאֱצֹת grandes:');
INSERT INTO verses VALUES (12534, 16, 9, 19, 'e-tu por-tus-teu-s os-ma-nos não de-las-e-los no-deserto a c-a-mi-nho o-nu-vem não s-e-á de-las-eles no-sua para-aju-dá-los no-cam-i-nho e-a para-iluminar a-eles בְּלַ֙יְלָה֙ לְהָאִ֣יר a-eles e-a o-caminho que יֵֽלְכוּ־ em-ela');
INSERT INTO verses VALUES (12535, 16, 9, 20, '[וְרוּחֲךָ֙] a-boa [נָתַ֖תָּ] [לְהַשְׂכִּילָ֑ם] [וּמַנְךָ֙] não [מִפִּיהֶ֔ם] [וּמַ֛יִם] deste a-eles a-eles');
INSERT INTO verses VALUES (12536, 16, 9, 21, 'e-quarenta ano כִּלְכַּלְתָּ֥ם em-o-midbar não faltaram as suas alças não foram consumidos e seus pés não tornaram-se ceros');
INSERT INTO verses VALUES (12537, 16, 9, 22, 'e-deu a-eles reinos e povos e lhes partilharam uma metade e herdaram a terra סיחון e-a terra rei Hesbom e-a terra Ogue rei-de הבהשָׁן׃');
INSERT INTO verses VALUES (12538, 16, 9, 23, 'ובניhem HIRBITA ככוכבי os-céus VTAVIAM a a-terra que A MARTA לאבותhem לָב֥וֹא לארשׁת׃');
INSERT INTO verses VALUES (12539, 16, 9, 24, 'e-entrou-ele os filhos WAYYIRSHU a a-terra e se humilhou ante-eles a-terra habitantes-de a-terra os-canaanitas e-lhes em-mão-deles a-terra מלכיהם e-a nacionalidades a-terra para-fazer neles segundo-seu-desejo');
INSERT INTO verses VALUES (12540, 16, 9, 25, 'e-eles-capturaram cidades em-cavernas e-a-terra oito e-possuíram casa מְלֵֽאִים־ todo bom בֹּר֨וֹת חֲצוּבִ֜ים כְּרָמִ֧ים alimento וְעֵ֥ץ מַאֲכָ֖ל em-abundância וַיֹּאכְל֤וּ וַֽיִּשְׂבְּעוּ֙ וַיַּשְׁמִ֔ינוּ e se contaram בְּטוּבְךָ֥ o-grande');
INSERT INTO verses VALUES (12541, 16, 9, 26, 'e disseram e se rebelaram sobre-ti e lançaram a a tua lei depois-de ainda que e-a נְבִיאֶ֣יךָ mataram que e testemunharam neles para devolvê-los a-ti e fizeram perseguições grande:');
INSERT INTO verses VALUES (12542, 16, 9, 27, 'e-lhes deu em-mão-de seus apertos e-apertaram a-eles e-em tempo seu aperto chamariam para-ti e-tu dos céus ouvirias e-pelas tuas misericórdias muitas תִּתֵּ֤ן a-eles מֽוֹשִׁיעִ֔ים וְיוֹשִׁיע֖וּם de-mão-de צָרֵיהֶֽם׃');
INSERT INTO verses VALUES (12543, 16, 9, 28, 'וּכְנ֣וֹחַ a-eles יָשׁ֕וּבוּ para-fazer mau diante-de-ti וַתַּֽעַזְבֵ֞ם em-mão-de אֹֽיְבֵיהֶם֙ וַיִּרְדּ֣וּ em-elas וַיָּשׁ֙וּבוּ֙ e-eles-teimaram-te e-tu de-céus tu-ouvires e-te-libertes-os segundo-tus-compassões muitas tempo:');
INSERT INTO verses VALUES (12544, 16, 9, 29, 'e-te-testemunhaste neles para-devolver-os a Tôrâ-teka e seriam Hêzidû e-não ouviram lémitsvôté-ikhâ úbemishpáṭe-ikhâ homem neles que ele-fará homem véchayá-ha bahêm e-eles-deram kâtéf sôrêret vé''arphám hikshû e-não שְׁמַע׃');
INSERT INTO verses VALUES (12545, 16, 9, 30, '[וַתִּמְשֹׁ֤ךְ] sobre-eles dois [רַבּ֔וֹת] [וַתָּ֨עַד] [בָּ֧ם] [בְּרוּחֲךָ֛] por-mão-de [וְלֹ֣א] e-não [וַֽתִּתְּנֵ֔ם] [בְּיַ֖ד] em-mão [הָאֲרָצֹֽת]');
INSERT INTO verses VALUES (12546, 16, 9, 31, 'e-em-vosso-compasso os-muitos não fizest-lhes plenamente e-não que porque a misericordioso e-compassivo tu');
INSERT INTO verses VALUES (12547, 16, 9, 32, 'e-agora nosso-elohim האל o-grande o-poderoso e-terrível guardiao a aliança e-amorosamente a ele-se-faça-pequeno ante-vos a todo a-maldição que- achamos-nos para-nossos-reis para-nossos-senhores e-nossos-sacerdotes e-nossos-prophetas e-nossos-pai-s e-para-todo- até o-dia reis-de Assur até o-dia a-esta');
INSERT INTO verses VALUES (12548, 16, 9, 33, 'e-tu צדיק sobre todo o-que-vinha sobre-nós porque verdade fiz-te- e-nós hiršāʿenu׃');
INSERT INTO verses VALUES (12549, 16, 9, 34, 'e-a malkheynu sarheiynu kohneynu não não fizeram toratecha e-não hikšivu a mitzvoteycha uledgevedotecha que haʿidota neles');
INSERT INTO verses VALUES (12550, 16, 9, 35, 'vehem no-seu-reino e-no-teu-bem o-grande que a-eles a-eles e-na-terra a-larga e-a-sabedoria que não ante-eles não servi-te e-não voltem-se de-suas-impurezas os maus:');
INSERT INTO verses VALUES (12551, 16, 9, 36, 'eis nós o-dia servos E-a-terra que deu-as-lhes aos nossos pais para comer a eis e-a seu bem הִנֵה nós servos sobre-ela');
INSERT INTO verses VALUES (12552, 16, 9, 37, 'e sua produção abundante aos reis que deu sobre nós com nossas oferendas e-sobre גּוִיּוֹתֵינוּ מֹשְׂלִים וּבִבְהֵמְתֵּנוּ כַּרְצוֹנָם וּבְצָרָה grande nós-verso');
INSERT INTO chapters VALUES (423, 16, 10, 40);
INSERT INTO verses VALUES (12553, 16, 10, 1, 'e-em-todo [אֲנַ֛חְנוּ] [כֹּרְתִ֥ים] [אֲמָנָ֖ה] [וְכֹתְבִ֑ים] [וְעַל֙] e-sobre [שָׂרֵ֥ינוּ] [לְוִיֵּ֖נוּ] [כֹּהֲנֵֽינוּ]');
INSERT INTO verses VALUES (12554, 16, 10, 2, 'e-sobre [הַחֲתוּמִ֑ים] [נְחֶמְיָ֧ה] [הַתִּרְשָׁ֛תָא] filho-de [וְצִדְקִיָּֽה]');
INSERT INTO verses VALUES (12555, 16, 10, 3, 'שְׂרָיָ֥ה Azaria ירמייהו׃');
INSERT INTO verses VALUES (12556, 16, 10, 4, '[פַּשְׁח֥וּר] [אֲמַרְיָ֖ה] [מַלְכִּיָּֽה]');
INSERT INTO verses VALUES (12557, 16, 10, 5, '[חַטּ֥וּשׁ] [שְׁבַנְיָ֖ה] [מַלּֽוּךְ]');
INSERT INTO verses VALUES (12558, 16, 10, 6, '[חָרִ֥ם] [מְרֵמ֖וֹת] [עֹֽבַדְיָֽה]');
INSERT INTO verses VALUES (12559, 16, 10, 7, '[דָּנִיֵּ֥אל] [גִּנְּת֖וֹן] [בָּרֽוּךְ]');
INSERT INTO verses VALUES (12560, 16, 10, 8, 'Mesulão [אֲבִיָּ֖ה] [מִיָּמִֽן]');
INSERT INTO verses VALUES (12561, 16, 10, 9, 'מַֽעַזְיָ֥ה בִלְגַּ֖י שְׁמַֽעְיָ֑ה Estas os cohenim:');
INSERT INTO verses VALUES (12562, 16, 10, 10, '[וְֽהַלְוִיִּ֑ם] [וְיֵשׁ֙וּעַ֙] filho-de [בִּנּ֕וּי] [מִבְּנֵ֥י] de-filhos-de Henadade');
INSERT INTO verses VALUES (12563, 16, 10, 11, '[וַאֲחֵיהֶ֑ם] [שְׁבַנְיָ֧ה] [הֽוֹדִיָּ֛ה] [קְלִיטָ֖א] [פְּלָאיָ֥ה] Hanan');
INSERT INTO verses VALUES (12564, 16, 10, 12, '[מִיכָ֥א] [רְח֖וֹב] [חֲשַׁבְיָֽה]');
INSERT INTO verses VALUES (12565, 16, 10, 13, 'זַכּ֥וּר Šerêbah Šavanyah:');
INSERT INTO verses VALUES (12566, 16, 10, 14, 'Hodiyyah filhos-de Binnu:');
INSERT INTO verses VALUES (12567, 16, 10, 15, 'cabeças de o-povo Par''osh filho-de Moabe Êlam Zattuâ filhos-de');
INSERT INTO verses VALUES (12568, 16, 10, 16, 'filhos-de Azgad Bêbay:');
INSERT INTO verses VALUES (12569, 16, 10, 17, 'Adonias Bigwai עָדִֽין׃');
INSERT INTO verses VALUES (12570, 16, 10, 18, 'Ater [חִזְקִיָּ֖ה] [עַזּֽוּר]');
INSERT INTO verses VALUES (12571, 16, 10, 19, '[הוֹדִיָּ֥ה] [חָשֻׁ֖ם] [בֵּצָֽי]');
INSERT INTO verses VALUES (12572, 16, 10, 20, '[חָרִ֥יף] [עֲנָת֖וֹת]');
INSERT INTO verses VALUES (12573, 16, 10, 21, '[מַגְפִּיעָ֥שׁ] [מְשֻׁלָּ֖ם] [חֵזִֽיר]');
INSERT INTO verses VALUES (12574, 16, 10, 22, '[מְשֵׁיזַבְאֵ֥ל] Zadoque [יַדּֽוּעַ]');
INSERT INTO verses VALUES (12575, 16, 10, 23, '[פְּלַטְיָ֥ה] Hanã [עֲנָיָֽה]');
INSERT INTO verses VALUES (12576, 16, 10, 24, '[הוֹשֵׁ֥עַ] Hananyah [חַשּֽׁוּב]');
INSERT INTO verses VALUES (12577, 16, 10, 25, '[הַלּוֹחֵ֥שׁ] [פִּלְחָ֖א] [שׁוֹבֵֽק]');
INSERT INTO verses VALUES (12578, 16, 10, 26, '[רְח֥וּם] [חֲשַׁבְנָ֖ה] [מַעֲשֵׂיָֽה]');
INSERT INTO verses VALUES (12579, 16, 10, 27, 'wa''ăchīyyāh Hanã ʿănān׃');
INSERT INTO verses VALUES (12580, 16, 10, 28, 'malk̄ ḥārim bʿănāh׃');
INSERT INTO verses VALUES (12581, 16, 10, 29, 'e-restante-de o-povo os-sacerdotes haləwīȳm hāšōʿārîm hamməšōrērim hannatīnîm e-todo o separado de povos das nações a lei-de os-Elohim suas mulheres seus filhos e suas filhas todo conhecedor de compreensão:');
INSERT INTO verses VALUES (12582, 16, 10, 30, 'que seguram sobre seus irmãos suas honras וּבָאִ֞ים בְּאָלָ֣ה וּבִשְׁבוּעָ֗ה para-andar em-lei-de os-Elohim que נִתְּנָ֔ה em-mão Moisés servo- o-Elohim וְלִשְׁמ֣וֹר yhwh a todo mandamentos-de yhwh אֲדֹנֵ֔ינוּ וּמִשְׁפָּטָ֖יו וְחֻקָּֽיו׃');
INSERT INTO verses VALUES (12583, 16, 10, 31, '[וַאֲשֶׁ֛ר] não deu [לְעַמֵּ֣י] a-terra a-terra não [נִקַּ֖ח] não');
INSERT INTO verses VALUES (12584, 16, 10, 32, 'וְעַמֵּ֣י a-terra הַֽמְבִיאִים֩ a הַמַּקָּח֨וֹת e-todo safra בֵּי֥וֹם do sétimo para vender não seríamos tomados deles no sétimo e-no-dia-de santidade e seríamos abandonados a o ano sétimo e a oferta todo mão');
INSERT INTO verses VALUES (12585, 16, 10, 33, 'e estabelecemos-nos sobre-nos [מִצְוֺ֔ת] a-dar sobre nós terça parte o siclo no ano para a obra casa Elohim-nosso');
INSERT INTO verses VALUES (12586, 16, 10, 34, 'para o pão da mesa e a oferta o queimar-continuamente e-a-offerida o queimar-continuamente as-sabáticos os-novilhos aos-momentos e-para-a-santidade e-as-ofertas-por-transgressões ləkappēr sobre e-tudo e-todo obra-de casa-de Elohim-nosso');
INSERT INTO verses VALUES (12587, 16, 10, 35, 'e-a-sorte e-nós-levamos sobre )(((קרובן)) העשִׂים os-sacerdotes הלויִימָ והעָם֒ para-trazer לַבֵּית Elohim para-casa-de אֲבֹתֵ֛ינוּ לְעִתִּ֥ים מְזֻמָּנִ֖ים ano בְשָׁנָ֑ה yhwh sobre mizbakh yhwh nosso-Elohim conforme-o-escrito Torá:');
INSERT INTO verses VALUES (12588, 16, 10, 36, 'e trar a bícuré da terra nossa e bícuré todo fruto todo árvore yhwh no ano para o templo yhwh');
INSERT INTO verses VALUES (12589, 16, 10, 37, 'e-a bícoras nossos filhos e-nossos-animais conforme-o-escrito na-torá e-a nosso-primeiros nossos-vacas e-nossos-ovelhas trazer para-casa-de Elohim-nosso aos-sacerdotes os-que-oferecem em-casa-de Elohim-nosso');
INSERT INTO verses VALUES (12590, 16, 10, 38, 'e-a ré''eshít nossas-arízes e-nossas-oferendas e-frutos todo עֵ֜ץ תִּיר֣וֹשׁ וְיִצְהָ֗ר profeta לַכֹּהֲנִים֙ a לִשְׁכ֣וֹת casa-de Elohim-nosso וּמַעְשַׂ֥ר אַדְמָתֵ֖נוּ para-os-Levitas e-eles os-levitas הַֽמְעַשְּׂרִ֔ים em-todo cidades-de עֲבֹדָתֵֽנוּ׃');
INSERT INTO verses VALUES (12591, 16, 10, 39, 'e-será o-sacerdote filho-de [עִם־הַלְוִיִּ֖ם] com os-levitas [וְהַלְוִיִּ֞ם] os-levitas e-os-levitas [הַֽמַּעֲשֵׂר֙] a [Elohim] [אֶל־הַלְּשָׁכ֖וֹת] para-casa-de Elohim-nosso a');
INSERT INTO verses VALUES (12592, 16, 10, 40, 'que a הַלְשׁוֹכֹת יָבִיאוּ filhos-de Israel e-filhos-de הַלֵּוִי a oferta-de הַדֶגָן֮ as figs וְהַיִצְחָר֒ e ali instrumentos-de do-santuário e os sacerdotes os-servindo e os contador e os reveladores e-não nós abandonemos a casa Elohim-nosso');
INSERT INTO chapters VALUES (424, 16, 11, 36);
INSERT INTO verses VALUES (12593, 16, 11, 1, 'e-habitaram senhores-de- o-povo em-Jerusalém e-restante-de o-povo e lançaram sortes dele para trazer um de a décima para sentar-se em Jerusalém cidade o-santuário e nove as testemunhas nas cidades:');
INSERT INTO verses VALUES (12594, 16, 11, 2, 'e-ele-bendizem o-povo a-todo os-homens os voluntários para-habitar em-Jerusalém');
INSERT INTO verses VALUES (12595, 16, 11, 3, 'e-estes cabeças-de a província que habitaram em-Jerusalém e nas cidades Judá residiram homem em sua posse em suas cidades Israel os sacerdotes e-os-levitas e os levitas e-filhos-de servos-de שְׁלֹמֹה');
INSERT INTO verses VALUES (12596, 16, 11, 4, 'e em Jerusalém residiram de-filhos-de Judá e filhos de Benjamim de-filhos-de Yehudah Atia filho-de Uzias filho-de Zacarias filho-de Amaria filho-de Sefatias filho-de Maalalel filhos de Perez');
INSERT INTO verses VALUES (12597, 16, 11, 5, 'e feitos de filho-de בָּר֣וּךְ filho-de todo observador filho-de visão filho-de testemunho filho-de negociador filho-de זכריה filho-de o-lixílio');
INSERT INTO verses VALUES (12598, 16, 11, 6, 'todo filhos-de abertura os-habitantes em-Jerusalém quatro centenas sessenta e-oito ANASH''E- força');
INSERT INTO verses VALUES (12599, 16, 11, 7, 'e-estes filhos-de Benjamim [סַלֻּ֡א] filho-de [בֶּן־יוֹעֵ֡ד] filho-de [בֶן־ק֨וֹלָיָ֧ה] filho-de [בֶּן־אִֽיתִיאֵ֖ל] filho-de filho-de filho-de filho-de');
INSERT INTO verses VALUES (12600, 16, 11, 8, 'e-depois-dele גַּבַּ֣י סַלָּ֑י nove centenas vinte e-oito');
INSERT INTO verses VALUES (12601, 16, 11, 9, '[וְיוֹאֵ֥ל] filho-de memória-minha [עֲלֵיהֶ֑ם] sobre-eles [בֶן־הַסְּנוּאָ֛ה] filho-de [מִשְׁנֶֽה׃] sobre');
INSERT INTO verses VALUES (12602, 16, 11, 10, 'de o-sacerdotes Jedediah filho-de contenda- fará:');
INSERT INTO verses VALUES (12603, 16, 11, 11, 'Seraías filho-de [בֶּן־מְשֻׁלָּ֣ם] filho-de Mesulão filho-de [נְגִ֖ד] filho-de [הָאֱלֹהִֽים] filho-de casa');
INSERT INTO verses VALUES (12604, 16, 11, 12, 'ואחיהם fazendo- a-tarefa -para-a-casa oito centenas vinte e-duas e-adiantemente filho-de tenha-piedade filho-de פללייה filho-de אמצי filho-de זכARYAH filho-de פסחור filho-de Malakiyya');
INSERT INTO verses VALUES (12605, 16, 11, 13, '[וְאֶחָיו֙] [רָאשִׁ֣ים] [לְאָב֔וֹת] duzentos quarenta [וּשְׁנָ֑יִם] [וַעֲמַשְׁסַ֧י] filho-de [בֶּן־אַחְזַ֥י] filho-de [בֶּן־אִמֵּֽר] filho-de filho-de disse');
INSERT INTO verses VALUES (12606, 16, 11, 14, 'e-los gibbori valente cem vinte וּשְׁמֹנָ֑ה וּפָקִ֣יד sobre-eles זַבְדִּיאֵ֖ל filho-de הַגְּדוֹלִֽים׃');
INSERT INTO verses VALUES (12607, 16, 11, 15, '[וּמִֽן־הַלְוִיִּ֑ם] os-levitas [בֶן־חַשּׁ֛וּב] filho-de [בֶּן־חֲשַׁבְיָ֖ה] filho-de filho-de filho-de');
INSERT INTO verses VALUES (12608, 16, 11, 16, 'וְשַׁבְּתַ֨י וְיוֹזָבָ֜ד sobre הַמְּלָאכָ֤ה הַחִֽיצֹנָה֙ para-casa-de os-Elohim dos principais os-levitas');
INSERT INTO verses VALUES (12609, 16, 11, 17, '[וּמַתַּנְיָ֣ה] filho-de [בֶּן־זַבְדִּ֨י] filho-de [רֹ֗אשׁ] filho-de [יְהוֹדֶ֣ה] cabeça [וּבַקְבֻּקְיָ֖ה] [מִשְׁנֶ֣ה] [מֵאֶחָ֑יו] [וְעַבְדָּא֙] [בֶּן־שַׁמּ֔וּעַ] [בֶּן־גָּלָ֖ל] [בֶּן־*ידיתון] filho-de filho-de filho-de');
INSERT INTO verses VALUES (12610, 16, 11, 18, 'todo os-levitas na-cidade o-santuário duzentos oitenta e-quatro');
INSERT INTO verses VALUES (12611, 16, 11, 19, 'e os contadores Aquav Talmon e-irmãos-deles os guardas nas portas cem setenta e-dois');
INSERT INTO verses VALUES (12612, 16, 11, 20, 'e-restante-de Israel os-sacerdotes os-levitas em-todo cidades-de Judá homem de sua herança:');
INSERT INTO verses VALUES (12613, 16, 11, 21, 'e-os-netinins yoshvim-acento-grave em-o-Ofel e a cisterna e o gisfã sobre os natin:');
INSERT INTO verses VALUES (12614, 16, 11, 22, '[וּפְקִ֤יד] os-levitas [בִּיר֣וּשָׁלִַ֔ם] [עֻזִּ֤י] filho-de filhos-de filho-de [בֶּן־מִיכָ֑א] filho-de [אָסָף֙] filho-de [לְנֶ֖גֶד] [מְלֶ֥אכֶת] Asafe casa-de');
INSERT INTO verses VALUES (12615, 16, 11, 23, 'porque mandamento-de o-rei sobre-eles ואמונה sobre המשורֵרים palavra-de dia em-dia-de-o');
INSERT INTO verses VALUES (12616, 16, 11, 24, 'ופתחיָה filho-de MESHBIZEVEL filhos de- Zérah filho-de Judá -de o-rei para-todo palavra -para o povo:');
INSERT INTO verses VALUES (12617, 16, 11, 25, 'e-a os campos -nas suas de-filhos-de Judá residiram em Cirete da Quatro e suas filhas e Dibom e suas filhas וּבִֽיקַּבְצְאֵ֖ל וַחֲצֵרֶֽיהָ׃');
INSERT INTO verses VALUES (12618, 16, 11, 26, 'וּבְיֵשׁ֥וּעַ וּבְמוֹלָדָ֖ה e-em-bayt פָּֽלֶט׃');
INSERT INTO verses VALUES (12619, 16, 11, 27, 'וּבַחֲצַ֥ר שׁוּעָ֛ל וּבִבְאֵ֥ר sete e-as-sua-filhas:');
INSERT INTO verses VALUES (12620, 16, 11, 28, 'וּבְצִֽקְלַ֥ג וּבִמְכֹנָ֖ה e-em-suas-filhas:');
INSERT INTO verses VALUES (12621, 16, 11, 29, 'e-na-olho rimom e-na-caraça e-no-irmo:');
INSERT INTO verses VALUES (12622, 16, 11, 30, 'zanach adulam e-suas-casas: lachish e-suas-terras: arquearia e suas filhas e-acamparam מִבְּאֵֽר־ sete até גֵּֽיא־ הִנֹּֽם׃');
INSERT INTO verses VALUES (12623, 16, 11, 31, 'e-filhos-de Benjamim מִגָּ֑בַע מִכְמָ֣שׂ וְעַיָּ֔ה וּבֵֽית־ El e-as-sua-filhas:');
INSERT INTO verses VALUES (12624, 16, 11, 32, '[עֲנָת֥וֹת] [נֹ֖ב] [עֲנָֽנְיָֽה]');
INSERT INTO verses VALUES (12625, 16, 11, 33, '[חָצ֥וֹר] [׀] [רָמָ֖ה]');
INSERT INTO verses VALUES (12626, 16, 11, 34, '[חָדִ֥יד] [צְבֹעִ֖ים] [נְבַלָּֽט]');
INSERT INTO verses VALUES (12627, 16, 11, 35, 'לֹ֥ד וְאוֹנ֖וֹ os הַחֲרָשִֽׁים׃');
INSERT INTO verses VALUES (12628, 16, 11, 36, 'e-de os-levitas מַחְלְק֥וֹת Judá לְבִנְיָמִֽין׃');
INSERT INTO chapters VALUES (425, 16, 12, 47);
INSERT INTO verses VALUES (12629, 16, 12, 1, 'e-estes os-sacerdotes [וְהַלְוִיִּ֔ם] que [עָל֛וּ] com [בֶּן־שְׁאַלְתִּיאֵ֖ל] filho-de Shealtiel [יִרְמְיָ֖ה] [עֶזְרָֽא]');
INSERT INTO verses VALUES (12630, 16, 12, 2, 'Amaryah מַלּוּךְ חַטּוּשׁ׃');
INSERT INTO verses VALUES (12631, 16, 12, 3, '[שְׁכַנְיָ֥ה] [רְחֻ֖ם] [מְרֵמֹֽת]');
INSERT INTO verses VALUES (12632, 16, 12, 4, 'idú''ah גינתי אביה:');
INSERT INTO verses VALUES (12633, 16, 12, 5, '[מִיָּמִ֥ין] [מַֽעַדְיָ֖ה] [בִּלְגָּֽה]');
INSERT INTO verses VALUES (12634, 16, 12, 6, 'Shema-yah ויוריב ידayah:');
INSERT INTO verses VALUES (12635, 16, 12, 7, 'סלו עומק חלקייה יְדַעְיָ֑ה Estas ראשי hakohanim e-irmãos-deles nos dias de ישוע׃');
INSERT INTO verses VALUES (12636, 16, 12, 8, 'e-os-levitas Yeshua Binui קדמיאל שריביה יְהוּדָה מתניה sobre ele ele וְאֶחָיו׃');
INSERT INTO verses VALUES (12637, 16, 12, 9, 'ובקבוקיה אֲחֵיהֶם לNEGDEM lemishmarot');
INSERT INTO verses VALUES (12638, 16, 12, 10, 'וישוע gerou a יוֹיָקִ֑ים וְיֽוֹיָקִים֙ gerou a Eliasibe וְאֶלְיָשִׁ֖יב a יוֹיָדָֽע׃');
INSERT INTO verses VALUES (12639, 16, 12, 11, '[וְיוֹיָדָע֙] gerou a Jônatas [הוֹלִ֥יד] gerou a');
INSERT INTO verses VALUES (12640, 16, 12, 12, '[וּבִימֵי֙] [יֽוֹיָקִ֔ים] foram [כֹהֲנִ֖ים] cabeças-de [הָאָב֑וֹת] [לִשְׂרָיָ֣ה] [מְרָיָ֔ה] [לְיִרְמְיָ֖ה] [חֲנַנְיָֽה]');
INSERT INTO verses VALUES (12641, 16, 12, 13, 'לְעֶזְרָ֣א Mesulam לַאֲמַרְיָ֖ה יְהוֹחָנָֽן׃');
INSERT INTO verses VALUES (12642, 16, 12, 14, 'João לִשְׁבַנְיָ֖ה José');
INSERT INTO verses VALUES (12643, 16, 12, 15, '[לְחָרִ֣ם] [עַדְנָ֔א] [לִמְרָי֖וֹת] [חֶלְקָֽי]');
INSERT INTO verses VALUES (12644, 16, 12, 16, '[*לעדיא] [**לְעִדּ֥וֹא] [זְכַרְיָ֖ה]');
INSERT INTO verses VALUES (12645, 16, 12, 17, '[לַאֲבִיָּ֖ה] [זִכְרִ֑י] [לְמִ֨נְיָמִ֔ין] [לְמוֹעַדְיָ֖ה] [פִּלְטָֽי]');
INSERT INTO verses VALUES (12646, 16, 12, 18, 'לְבִלְגָּ֣ה שַׁמּ֔וּעַ לִֽשְׁמַעְיָ֖ה jehonathan');
INSERT INTO verses VALUES (12647, 16, 12, 19, '[וּלְיוֹיָרִ֣יב] [מַתְּנַ֔י] [לִֽידַֽעְיָ֖ה] [עֻזִּֽי]');
INSERT INTO verses VALUES (12648, 16, 12, 20, '[לְסַלַּ֥י] [קַלָּ֖י] [לְעָמ֥וֹק] Éber');
INSERT INTO verses VALUES (12649, 16, 12, 21, 'para-division consideração para-conhecimento Natan-iel');
INSERT INTO verses VALUES (12650, 16, 12, 22, 'os-levitas בִּימֵ֨י Eliazev Joada e-João e-conhecido escritos cabeças-de avos e-os-sacerdotes sobre reino-de Dario o persa:');
INSERT INTO verses VALUES (12651, 16, 12, 23, 'filhos-de Levi cabeças-de os-pais escritos sobre livro palavras-de os-dias e-até dias joão filho-de Eliasibe');
INSERT INTO verses VALUES (12652, 16, 12, 24, 'e cabeças dos levitas cassabia seravbia e jesus filho-de carmiel וַאֲחֵיהֶ֣ם לְנֶגְדָּ֔ם para-louvar לְהוֹד֔וֹת בְּמִצְוַ֖ת Davi homem-de o-Elohim מִשְׁמָ֖ר próximo-a מִשְׁמָֽר׃');
INSERT INTO verses VALUES (12653, 16, 12, 25, '[מַתַּנְיָ֧ה] [וּבַקְבֻּֽקְיָ֛ה] [עֹבַדְיָ֥ה] [מְשֻׁלָּ֖ם] Talmon [עַקּ֑וּב] [שֹׁמְרִ֤ים] [שֽׁוֹעֲרִים֙] [מִשְׁמָ֔ר] [בַּאֲסֻפֵּ֖י] [הַשְּׁעָרִֽים]');
INSERT INTO verses VALUES (12654, 16, 12, 26, 'Estas בִּימֵ֛י יוֹיָקִים filho-de Jesua filho-de יוֹצָדָק וּבִימֵי֙ Neemias הַפֶּּחָה וְעֶזְרָא o-sacerdote o narrador:');
INSERT INTO verses VALUES (12655, 16, 12, 27, 'e na consagração muro-de Jerusalém busquem a os-levitas de-todo seus lugares para levá-los a Jerusalém para fazer dedicação e alegria e louvores וּבְשִׁ֔יר מְצִלְתַּ֖יִם נְבָלִ֥ים וּבְכִנֹּרֽוֹת׃');
INSERT INTO verses VALUES (12656, 16, 12, 28, '[וַיֵּאָ֣סְפ֔וּ] filhos-de [הַמְשֹׁרְרִ֑ים] e-de [סְבִיב֣וֹת] [יְרוּשָׁלִַ֔ם] Jerusalém e-de');
INSERT INTO verses VALUES (12657, 16, 12, 29, 'e do-bayit o-Gilgal e das-sedot gevah e az-mavet que חֲצֵרִ֗ים edificaram a-eles as mash-shor-irim circuitos Jerusalém');
INSERT INTO verses VALUES (12658, 16, 12, 30, 'e vay-ta-har-u os-sacerdotes e-os-levitas e vay-te-har-uh a o-povo e-a as sha-ar-im e-com a muralha:');
INSERT INTO verses VALUES (12659, 16, 12, 31, 'e va-al-e a príncipes-de de-cima-de de-sobre para a-choma e estabeleci duas todas grandes e andaram de-cima-de de-sobre pela muralha para a porta da aspereza');
INSERT INTO verses VALUES (12660, 16, 12, 32, 'E-andou אַחֲרֵיהֶם֙ Hosana וַחֲצִי príncipes-de Judá');
INSERT INTO verses VALUES (12661, 16, 12, 33, 'e Azariah Ezra וּמְשֻׁלָּֽם׃');
INSERT INTO verses VALUES (12662, 16, 12, 34, 'Judá e-Benjamim [וּֽשְׁמַֽעְיָ֖ה] [וְיִרְמְיָֽה׃]');
INSERT INTO verses VALUES (12663, 16, 12, 35, '[וּמִבְּנֵ֥י] os-sacerdotes [בַּחֲצֹצְר֑וֹת] [זְכַרְיָ֨ה] filho-de [בֶּן־שְׁמַֽעְיָ֗ה] filho-de [בֶּן־מִ֣יכָיָ֔ה] filho-de [בֶּן־אָסָֽף] filho-de filho-de filho-de');
INSERT INTO verses VALUES (12664, 16, 12, 36, 'וְֽאֶחָ֡יו שְֽׁמַעְיָ֡ה וַעֲזַרְאֵ֡ל מִֽלֲלַ֡י גִּֽלֲלַ֡י מָעַ֞י נְתַנְאֵ֤ל וִֽיהוּדָה֙ chanani com-utensílios-de cântico David homem o-Elohim וְעֶזְרָ֥א הַסּוֹפֵ֖ר diante-deles');
INSERT INTO verses VALUES (12665, 16, 12, 37, 'e-sobre portão-de a-fonte וְנֶגְדָּ֗ם subiram sobre מַעֲלוֹת֙ cidade Davi בַּֽמַּעֲלֶ֖ה de-cima-de de-sobre para-casa-de Davi ve-ad portão-de as-águas leste;');
INSERT INTO verses VALUES (12666, 16, 12, 38, 'e a todáh a segunda a que vai para Moel e-eu depois dela e-metade-de o-povo de-cima-de para a muralha de-cima-de para o torreão do forno e-até o-muro a-larga');
INSERT INTO verses VALUES (12667, 16, 12, 39, 'e sobre para a porta— אֶפְרַיִם e-sobre portão-de a-velha e-sobre portão הַדּוֹגִים וּמִגְדָּל חֲנַנְאֵל וּמִגְדָּל [הַצֹּ֑אן] e-até portão do-rebanho וְעָמְדוּ entre הַמְּטָרָה׃');
INSERT INTO verses VALUES (12668, 16, 12, 40, 'וַֽתֵּעֲמֹדְנָה duas-de as-todótes na-casa-de o-Elohim e-eu e-metade-de os-sganim comigo');
INSERT INTO verses VALUES (12669, 16, 12, 41, 've-hak-kohanim ele-yaqim ma-asayah mi-nayamin mikayah ele-ouenai zacharyah Hananyah be-chatzotrot:');
INSERT INTO verses VALUES (12670, 16, 12, 42, 'u-ma-asayah וּֽשְׁמַֽעְיָ֜ה וְאֶלְעָזָ֧ר וְעֻזִּ֛י וִֽיהוֹחָנָ֥ן וּמַלְכִּיָּ֖ה וְעֵילָ֣ם וָעָ֑זֶר וַיַּשְׁמִ֙יעוּ֙ הַמְשֹׁ֣רְרִ֔ים וְיִֽזְרַחְיָ֖ה הַפָּקִֽיד׃');
INSERT INTO verses VALUES (12671, 16, 12, 43, 'וַיִּזְבְּח֣וּ no-dia-de הַ֠הוּא זְבָחִ֨ים גְּדוֹלִ֜ים que porque o-Elohim שִׂמְּחָם֙ alegria grande e-também הַנָּשִׁ֛ים וְהַיְלָדִ֖ים שָׂמֵ֑חוּ וַתִּשָּׁמַ֛ע שמחת Jerusalém מרחוק׃');
INSERT INTO verses VALUES (12672, 16, 12, 44, 'e foi ordenado no dia aquele homens sobre das ofertas para serem armazenadas para as ofertas para a primícia e para as décimas para serem trazidas neles para os as cidades מְנָא֣וֹת ha-torah para-os-sacerdotes que porque שִׂמְחַ֣ת Judá sobre הַכֹּהֲנִ֥ים e-sobre os-levitas הָעֹמְדִֽים׃');
INSERT INTO verses VALUES (12673, 16, 12, 45, 'וַֽיִּשְׁמְר֞וּ guardiã אֱלֹֽהֵיהֶם֙ וּמִשְׁמֶ֣רֶת הַֽטָּהֳרָ֔ה וְהַמְשֹׁרְרִ֖ים וְהַשֹּׁעֲרִ֑ים como mandamento David Salomão filho-dele');
INSERT INTO verses VALUES (12674, 16, 12, 46, 'porque nos dias Davíd ao-oriente мїкїдем os que murmuram e cântico- hinos e louvores para-Elohim');
INSERT INTO verses VALUES (12675, 16, 12, 47, 'e-todo Israel בִּימֵ֨י Zorobabel e-em-dias-de Nehemias dando doçuras os-mensageiros e-os-escuteiros palavra-de dia no-seu-dia e-santificam lálevím e levitas san-ti-ficam para-filhos-de Aharon');
INSERT INTO chapters VALUES (426, 16, 13, 31);
INSERT INTO verses VALUES (12676, 16, 13, 1, 'no-dia aquele é-chamado besefer Moisés em-orelhas-de o-povo e-encontrado escrito nele que não vira amônita e-moabita בִּקְהַ֥ל Elohim até eternidade');
INSERT INTO verses VALUES (12677, 16, 13, 2, 'que não [קִדְּמ֛וּ] a filhos-de Israel [וּבַמָּ֑יִם] [וַיִּשְׂכֹּ֨ר] [עָלָ֤יו] sobre-o a [וַיַּהֲפֹ֧ךְ] [Elohim] [הַקְּלָלָ֖ה] Elohim nosso');
INSERT INTO verses VALUES (12678, 16, 13, 3, 'e-houve כְּשָׁמְעָ֣ם a a-Torah וַיַּבְדִּ֥ילוּ todo tarde de Israel:');
INSERT INTO verses VALUES (12679, 16, 13, 4, '[וְלִפְנֵ֣י] deste-lado [אֶלְיָשִׁיב֙] o-sacerdote [נָת֖וּן] [בְּלִשְׁכַּ֣ת] casa-de nosso-Elohim [לְטוֹבִיָּֽה]');
INSERT INTO verses VALUES (12680, 16, 13, 5, 'E-fez a-ele לִשְׁכָּ֣ה grande ושם foram לְפָנִ֟ים נֹ֠תְנִים a הַמִּנְחָ֨ה הַלְּבוֹנָ֜ה וְהַכֵּלִ֗ים וּמַעְשַׂ֤ר הַדָּגָן֙ as figs e-hayitzháras מִצְוַת֙ os-levitas וְהַמְשֹׁרְרִ֖ים וְהַשֹּׁעֲרִ֑ים וּתְרוּמַ֖ת aos-sacerdotes');
INSERT INTO verses VALUES (12681, 16, 13, 6, 'e-em-todo não não estava que porque [שְׁלֹשִׁ֨ים] [וּשְׁתַּ֜יִם] [לְאַרְתַּחְשַׁ֤סְתְּא] [מֶֽלֶךְ־בָּבֶל֙] rei-de Babilônia [וּלְקֵ֥ץ] a o-rei [מִן־הַמֶּֽלֶךְ] de');
INSERT INTO verses VALUES (12682, 16, 13, 7, 'e-vim [לִֽירוּשָׁלָ֑͏ִם] [וָאָבִ֣ינָה] [בָרָעָ֗ה] que fez [אֶלְיָשִׁיב֙] [לְט֣וֹבִיָּ֔ה] para-fazer a-ele [נִשְׁכָּ֔ה] [בְּחַצְרֵ֖י] casa Elohim');
INSERT INTO verses VALUES (12683, 16, 13, 8, 'וַיֵּ֥רַֽע a-mim muito e lancei a todo vasos casa-de de boa fora de do altar');
INSERT INTO verses VALUES (12684, 16, 13, 9, 'e disse foram purificados as pias e tratei nome utensílios-de casa os-Elohim a הַמִּנְחָ֖ה e a cera');
INSERT INTO verses VALUES (12685, 16, 13, 10, 'e-senti porque as-mãos não não foi-dada e-escaparam homem-de para-o-pasto os-levitas e-os-que-revelam-se fazentes-de o-trabalho');
INSERT INTO verses VALUES (12686, 16, 13, 11, 'e-disputei a os-capitães e-om-rāh por-que ne-ez-ba casa-de o-Elohim va-ê-qeb-tsēm va-a-am-idem sobre am-dam׃');
INSERT INTO verses VALUES (12687, 16, 13, 12, 'e-todo Judá he-vi-yū ma-sha-rā ha-d-dagan ve-ha-ti-ros e-hayitzháras para-outras-escrituras:');
INSERT INTO verses VALUES (12688, 16, 13, 13, 'e-outra-escrita sobre outras-escritas shelémiah o sacerdote e-צָדוֹק o-scriptor e-pediajah de os-levitas e-sobre a-mão-dele que filho-de Zacur filho-de matanyah porque neemanim foram-contados e-sobre-elas para-partilhar para-seus-irmãos:');
INSERT INTO verses VALUES (12689, 16, 13, 14, '[זָכְרָה־לִּ֥י] para-mim Elohim-meu sobre esta e-a [עָשִׂ֛יתִי] [בְּבֵ֥ית] que [וּבְמִשְׁמָרָֽיו]');
INSERT INTO verses VALUES (12690, 16, 13, 15, 'em-os-dias הנהָהּ vi ביוחדה ׀ דרכימ- גיתות ׀ בשבת e trazendo as aremas e empurrando sobre os jumentos e-também vinho uvas e figos e-todo carga e trazendo Jerusalém em-dia-de השבת e deparei-me com em-dia dos vinhedos Caça:');
INSERT INTO verses VALUES (12691, 16, 13, 16, 'E os zorites habitaram nela trazem daga e-todo comércio e vendem no sábado para-os-filhos-de Judá e em Jerusalém:');
INSERT INTO verses VALUES (12692, 16, 13, 17, 'Eu argumentei a cavernas Judá e-eu-disse a-eles que הַדָּ֨בָ֨ר הָרָ֤ע este que vós fazendo וּֽמְחַלְּלִ֖ים a dia הַשַׁבָּֽת׃');
INSERT INTO verses VALUES (12693, 16, 13, 18, 'porventura-não [כֹ֤ה] fizeram [אֲבֹ֣תֵיכֶ֔ם] e-trouxe [Elohim] [עָלֵ֗ינוּ] a todo [הַזֹּ֔את] esta e-sobre a-cidade esta [מוֹסִיפִ֤ים] [חָרוֹן֙] [עַל־יִשְׂרָאֵ֔ל] sobre Israel a');
INSERT INTO verses VALUES (12694, 16, 13, 19, 'e-houve como-que [צָֽלֲלוּ֩] portões-de Jerusalém diante-de [הַשַׁבָּ֗ת] [וָאֹֽמְרָה֙] [וַיִּסָּגְר֣וּ] [הַדְּלָת֔וֹת] [וָאֹ֣מְרָ֔ה] que não [יִפְתָּח֔וּם] até atrás-de [הַשַּׁבָּ֑ת] [וּמִנְּעָרַ֗י] [הֽ͏ֶעֱמַ֙דְתִּי֙] sobre [לֹא־יָב֥וֹא] não virá Massá');
INSERT INTO verses VALUES (12695, 16, 13, 20, 'vayyalinu hārochlim u''mokre todo mimkhar de-fora vez פַּ֥עַם u''shtayim:');
INSERT INTO verses VALUES (12696, 16, 13, 21, 'va''ā''idah bahem vā''amrāh a-eles por-que vós lēnim diante a parede se mão mão eu lançarei בכם de o tempo aquela não virão no sétimo dia:');
INSERT INTO verses VALUES (12697, 16, 13, 22, 'e-eu-disse aos levitas que serão purificados e virão guardando as portas para santificar a dia השבת também esta lembra-se para-mim meu-Elohim e ajuda sobre-mim como abrigo חסדך׃');
INSERT INTO verses VALUES (12698, 16, 13, 23, 'também em-os-dias aqueles רָאִ֤יתִי a os judeus retornaram mulheres a moabitas:');
INSERT INTO verses VALUES (12699, 16, 13, 24, 'e seus filhos meio- falando-é adulterina וְאֵינָ֥ם מַכִּירִ֖ים para-falar יְהוּדִ֑ית וְכִלְשׁ֖וֹן povo וָעָֽם׃');
INSERT INTO verses VALUES (12700, 16, 13, 25, 'וָאָרִ֤יב com-eles וָאֲקַֽלְלֵ֔ם וָאַכֶּ֥ה מֵהֶ֛ם homens וָֽאֶמְרְטֵ֑ם e vos jurei em elohim se dei-vos filhas-vossas a seus filhos e-se levastes [וְלָכֶֽם] para-vossos-filhos e-vós');
INSERT INTO verses VALUES (12701, 16, 13, 26, 'não sobre estes pecado- Shelomoh rei Israel e nos povos os muitos não foi rei ser e amado para-Elohim-dele foi e deu-lhes Elohim rei sobre todo Israel também o mesmo corrompe-los as-mulheres as estrangeiras:');
INSERT INTO verses VALUES (12702, 16, 13, 27, 'e para vós vocês ouvir para fazer a todo o mal a g''dolah a-esta para o decaimento em nossos elohimes para fazer voltar mulheres as estrangeiras;');
INSERT INTO verses VALUES (12703, 16, 13, 28, 'e dos filhos de Joiauda filho-de Eleisibe o-sacerdote a-grande cunhado para Senabelet o coronele e o abrihei מעלי');
INSERT INTO verses VALUES (12704, 16, 13, 29, 'lembrança a-eles meu-Elohim sobre redenção a sacerdócio e aliança o sacerdócio e levitas:');
INSERT INTO verses VALUES (12705, 16, 13, 30, 'e santificarei de-todo ne-char e estabeleci os serviços aos-cohanim e-los-leviim homem na-melachto:');
INSERT INTO verses VALUES (12706, 16, 13, 31, 'e-para-kurban as-etsim em-etusim previamente-mazumanot e-para-bikkurim recordação- para-mim Elohim-meu para-bem:');
INSERT INTO books VALUES (17, 'EST', 'Ester', 'AT', 10);
INSERT INTO chapters VALUES (427, 17, 1, 22);
INSERT INTO verses VALUES (12707, 17, 1, 1, 'e-houve em-dias-de Ahasverus ele Ahasverus o-rei desde-Índia e-até Cush sete e-vinte e-cem província');
INSERT INTO verses VALUES (12708, 17, 1, 2, 'em-os-dias os-aqueles quando-sentar o-rei Ahasverus sobre sobre reino-dele que em-Susã a-fortaleza');
INSERT INTO verses VALUES (12709, 17, 1, 3, 'em-ano-de três para-reinar-dele fez banquete para-todo príncipes-dele e-servos-dele exército-de Pérsia e-Média os-nobres e-príncipes-de as-províncias diante-de-ele');
INSERT INTO verses VALUES (12710, 17, 1, 4, 'em-mostrar-dele a dez glória-de reino-dele e- honra-de esplendor-de grandeza-dele dias muitos dia e-cem dia');
INSERT INTO verses VALUES (12711, 17, 1, 5, 'e-em-completar-de os-dias estes fez o-rei para-todo o-povo os-encontrados em-Susã a-cidadela para-desde-grande e-até pequeno banquete sete-de dias em-pátio-de jardim-de palácio-de o rei');
INSERT INTO verses VALUES (12712, 17, 1, 6, 'branco linho-fino e-azul segurado com-cordas-de linho e-púrpura sobre argolas-de prata e-colunas-de seis divãs-de ouro e-prata sobre pavimento-de pórfiro- e-mármore e-madrepérola e-pedra-preciosa');
INSERT INTO verses VALUES (12713, 17, 1, 7, 'e-o-dar-de-beber em-vasos-de ouro e-vasos desde-vasos diferentes e-vinho-de reino muito conforme-mão-de o rei');
INSERT INTO verses VALUES (12714, 17, 1, 8, 'e-o-beber conforme-lei não-há forçar porque assim ele-estabeleceu o rei sobre todo muito casa-dele para-fazer conforme-vontade-de homem e-homem');
INSERT INTO verses VALUES (12715, 17, 1, 9, 'também Vashti a-rainha ela-fez banquete-de mulheres casa o-reino que para-o-rei Ahasverus');
INSERT INTO verses VALUES (12716, 17, 1, 10, 'no-dia o-sétimo conforme-bem-de coração-de o-rei disse disse para-Mehumã Bizta Harbona Bigta e-Abagta Zetar e-Karkas sete-de os-eunucos os-servindo a face-de o-rei Ahasverus');
INSERT INTO verses VALUES (12717, 17, 1, 11, 'para-trazer a Vashti a-rainha diante-de o-rei com-coroa-de reino para-mostrar os-povos e-os-príncipes a vista porque boa-de aparência ela');
INSERT INTO verses VALUES (12718, 17, 1, 12, 'e-recusou a-rainha Vasti para-vir em-palavra-de o-rei que em-mão-de os-eunucos e-irou-se o rei muito e-ira-dele queimou nele');
INSERT INTO verses VALUES (12719, 17, 1, 13, 'E-disse o-rei para-os-sábios conhecendo [הֽ͏ָעִתִּ֑ים] porque assim palavra o-rei diante-de todo conhecedores-de e-juízo');
INSERT INTO verses VALUES (12720, 17, 1, 14, 'e-o-próximo a-ele Carshená Shetar Admatha Tarshish Meres Marsená Memucã sete-de príncipes-de Pérsia e-Média veedores-de face-de face-de os-que-habitam primeira no-reino');
INSERT INTO verses VALUES (12721, 17, 1, 15, 'conforme-lei que para-fazer na-rainha sobre sobre que não fez את- mandado-de o-rei Assuero em-mão os-eunucos');
INSERT INTO verses VALUES (12722, 17, 1, 16, 'E-disse diante-de o rei e-os-príncipes não sobre não para-somente-dele sozinho Vashti a-rainha porque que todo os-príncipes e-sobre todo os-povos que em-todo províncias-de o-rei');
INSERT INTO verses VALUES (12723, 17, 1, 17, 'porque sairá palavra-de a-rainha sobre todo as-mulheres para-desprezar maridos-delas disse em-dizerem-eles o-rei Assuero disse para-trazer a Vashti a-rainha diante-dele e-não veio');
INSERT INTO verses VALUES (12724, 17, 1, 18, 'e-o-dia o-este dirão princesas-de Pérsia e-Média que ouviram a palavra a-todo para-todo príncipes-de o-rei e-conforme-suficiente desprezo e-ira');
INSERT INTO verses VALUES (12725, 17, 1, 19, 'se bom o-rei bom sairá palavra-de reino de-diante-dele e-será-escrito em-leis-de Pérsia e-Madai e-não passará que não virá Vasti diante-de o-rei Assuero e-reino-dela dará o-rei para-companheira-dela a-boa de-elas');
INSERT INTO verses VALUES (12726, 17, 1, 20, 'e-será-ouvido decreto o-rei que fará que reino-dele porque multiplicai ela e-todo as-mulheres darão honra para-maridos-delas para-do-grande e-até pequeno');
INSERT INTO verses VALUES (12727, 17, 1, 21, 'e-foi-bom a-palavra em-olhos-de o-rei e-os-príncipes E-fez o-rei conforme-palavra-de Memucã');
INSERT INTO verses VALUES (12728, 17, 1, 22, 'e-estendeu cartas a todo províncias-de o-rei a província e-província conforme-escrita-dela e-a povo e-povo conforme-língua-dele para-ser todo homem dominando em-casa-de-ele e-falando conforme-língua-de povo-dele');
INSERT INTO chapters VALUES (428, 17, 2, 23);
INSERT INTO verses VALUES (12729, 17, 2, 1, 'outro as-palavras os-estes quando-diminuir ira-de o-rei Ahasverus macho a Vashti e-a que ela-fez e-a que foi-decretado sobre-ela');
INSERT INTO verses VALUES (12730, 17, 2, 2, 'e-disseram jovens-de o-rei servos-de-ele eles-busquem para-o-rei jovens-mulheres virgens vista aparência');
INSERT INTO verses VALUES (12731, 17, 2, 3, 'e-ele-nomeie o-rei oficiais em-todo províncias-de reino-de-ele e-eles-reúnam a vista jovem-mulher virgem boa-de aparência a Susa a-cidadela a casa as-mulheres a mão Hegai eunuco-de o-rei guardião-de as-mulheres e-dado cosméticos-de-elas');
INSERT INTO verses VALUES (12732, 17, 2, 4, 'e-a-jovem-mulher que ela-seja-boa em-olhos-de o-rei ela-reine debaixo Vashti e-foi-bom a-palavra em-olhos-de o-rei E-fez assim');
INSERT INTO verses VALUES (12733, 17, 2, 5, 'homem judeu ser em-Susa a-cidadela e-nome-de-ele Mordecai filho Jair filho-de Simei filho-de Quis homem benjamita');
INSERT INTO verses VALUES (12734, 17, 2, 6, 'que foi-exilado de-Jerusalém com o-exílio que foi-exilada povo Jeconias rei-de Judá que ele-exilou Nabucodonosor rei Babilônia');
INSERT INTO verses VALUES (12735, 17, 2, 7, 'e-houve criando a Hadassa ela Esther que tio-de-ele porque pai para-ela pai e-mãe e-a-jovem-mulher vista forma e-boa-de aparência e-na-morte-de pai-dela a-ele ele-tomou-ela Mordecai para-ele para-filha');
INSERT INTO verses VALUES (12736, 17, 2, 8, 'e-houve ao-ser-ouvido palavra-de o rei e-decreto-de-ele e-ao-serem-reunidas jovens-mulheres muitas a Susa a-cidadela a mão Hegai e-foi-tomada Esther a casa o-rei a mão Hegai guardando as-mulheres');
INSERT INTO verses VALUES (12737, 17, 2, 9, 'e-foi-boa a-jovem-mulher em-olhos-de-ele e-ela-encontrou bondade diante-de-ele e-ele-apressou a cosméticos-de-ela e-a porções-de-ela para-dar para-ela e-את sete as-jovens-mulheres as-apropriadas para-dar para-ela de-casa-de o-rei e-ele-mudou-ela e-a jovens-mulheres-de-ela para-bom casa as-mulheres');
INSERT INTO verses VALUES (12738, 17, 2, 10, 'não ela-contou Esther a que e-a origem-de-ela porque Mordecai ordenou sobre-ela que não');
INSERT INTO verses VALUES (12739, 17, 2, 11, 'e-em-todo dia e no dia passeando em-andar diante-de átrio-de para-conhecer as-mulheres לָדַ֙עַת֙ a שְׁל֣וֹם Esther ele a-ele nela');
INSERT INTO verses VALUES (12740, 17, 2, 12, 'וּבְהַגִּ֡יעַ תֹּר֩ נַעֲרָ֨ה וְנַעֲרָ֜ה לָב֣וֹא ׀ a o-rei Ahasverus מִקֵּץ estar para-ela כְּדָ֤ת as-mulheres dois dez novo que assim יִמְלְא֖וּ dias-de em-rúcye-hên shishah chodeshim beshemen hammor shishah chodeshim nos-bálsamos uvtamrukei as-mulheres');
INSERT INTO verses VALUES (12741, 17, 2, 13, 'uvazeh a-jovem ba''a a o-rei את todo que t''omar ser-irá-dado com-ela para-vir com-ela de-casa-de as-mulheres até casa o rei');
INSERT INTO verses VALUES (12742, 17, 2, 14, '-no-ente ela em-ela e-no-manhã ela שַׁבָּת a casa as-mulheres segundo a mão -de-sombras eunuco-de o-rei guardião-de as-mulheres-de-campos não viras que a o-rei porque se desejava -nela o-rei e-será-chamada -em-nome-');
INSERT INTO verses VALUES (12743, 17, 2, 15, 'e quando chegar tor- esther filha-de avichayil דּוֹד mardokey que לָקַֽח־ a-ele não para-vir a que não buscou palavra porque mãe a que יֹאמַ֛ר e quando chegar saris- o-rei guardião-de as-mulheres e-foi Esther noset chen em-olhos-de todo observadora:');
INSERT INTO verses VALUES (12744, 17, 2, 16, 'e foi tomada Esther a o-rei Acazías a casa reino-dele בַּחֹ֥דֶשׁ o décimo ele novo Tevet no-shanat- sete para-reino-dele');
INSERT INTO verses VALUES (12745, 17, 2, 17, 'וַיֶּאֱהַ֨ב o-rei a Esther de-todo as-mulheres e levou- favor e caridade diante-dele de-todo as vírgidos debaixo coroa: reino em sua cabeça e reinou-a debaixo-de Vashti:');
INSERT INTO verses VALUES (12746, 17, 2, 18, 'E-fez o-rei de-bebida grande para-todo saryav va''avadav את banquete-de Esther vahinachah lamdinot E-colocou E-deu מַשְׂאֵ֖ת conforme-mão-de o rei');
INSERT INTO verses VALUES (12747, 17, 2, 19, 'uviqatz virgens segunda umardokh habitou na-porta-de o rei');
INSERT INTO verses VALUES (12748, 17, 2, 20, 'não-há Esther magidet מֽוֹלַדְתָּה֙ e-a עַמָּ֔הּ como ordenou sobre-ela מָרְדֳּכָ֑י e-a מַאֲמַ֤ר מָרְדֳּכַי֙ Estar era como haytah בְאָמְנָ֖ה com-ele');
INSERT INTO verses VALUES (12749, 17, 2, 21, 'em-os-dias aqueles [וּמָרְדֳּכַ֖י] habitou [בְּשַֽׁעַר־הַמֶּ֑לֶךְ] o-rei [בִּגְתָ֨ן] [וָתֶ֜רֶשׁ] [שְׁנֵֽי־סָרִיסֵ֤י] dois [מִשֹּׁמְרֵ֣י] o rei [וַיְבַקְשׁוּ֙] [לִשְׁלֹ֣חַ] mão [בַּמֶּ֖לֶךְ] mão');
INSERT INTO verses VALUES (12750, 17, 2, 22, 'וַיִּוּדַ֤ע a-palavra לְמָרְדֳּכַ֔י e-anunciou לְאֶסְתֵּ֣ר a-rainha E-disse אֶסְתֵּ֛ר ao-rei em-nome-de מָרְדֳּכָֽי׃');
INSERT INTO verses VALUES (12751, 17, 2, 23, 'e buscou a-palavra e achou e penduraram dois-deles sobre אִילוֹן e escreveu no livro palavras-de os-dias diante-de o rei');
INSERT INTO chapters VALUES (429, 17, 3, 15);
INSERT INTO verses VALUES (12752, 17, 3, 1, 'depois- as-palavras estes Gidal o-rei Acashveros a Haman filho-de a metade o agagita e levou-o e-dispus de-cima-de trono-dele de-al todo os-senhores que com-ele');
INSERT INTO verses VALUES (12753, 17, 3, 2, 'e-todo servos-de o-rei que בְּשַׁעַר o rei joelhos e adorando a Hamã porque assim não para-ele o-rei e Mardoqueu não joelhe-se e-não e adorasse:');
INSERT INTO verses VALUES (12754, 17, 3, 3, 'e-disseram servos-de o-rei que em-porta-de o-rei a Mardoqueu tu tu passando את mandamento-de o rei');
INSERT INTO verses VALUES (12755, 17, 3, 4, 'e-houve a-ele dia a-ele dia ouviu a-eles e disseram לְהָמָ֗ן para-ver הֲיַֽעַמְדוּ֙ para-ver מָרְדֳּכַ֔י porque disse-lhe a-eles a-eles ele יְהוּדִֽי׃');
INSERT INTO verses VALUES (12756, 17, 3, 5, 'E-viu [הָמָ֔ן] porque não-há [כֹּרֵ֥עַ] [וּמִֽשְׁתַּחֲוֶ֖ה] a-ele para-ele [הָמָ֖ן] [חֵמָֽה]');
INSERT INTO verses VALUES (12757, 17, 3, 6, 'וַיִּ֣בֶז em-seus-olhos para-enviar mão a-Mardoqueu sozinho porque a-ele para-ele a povo Mardoqueu e-foi-procurar Hamã para-destruir a todo os judeus que em-todo real Acaśvesor povo Mardoqueu:');
INSERT INTO verses VALUES (12758, 17, 3, 7, 'em-o-mês o-primeiro ele novo Nisan no-ano-de שִׁיתִֽים dezoito ao-rei Ahasverus hippil ele Hu hagoral diante-de המן miyom leyom u''mechodesh lechodesh doze dez ele novo adhar');
INSERT INTO verses VALUES (12759, 17, 3, 8, 'E-disse haman para-o-rei Assuero yesheno com um mefuzzar entre entre os-povos em-todo províncias-de מלכותך e suas religiões שנות de-todo povo e-a דתי o rei איןם fazendo ולמלך não-há שוה להניחם׃');
INSERT INTO verses VALUES (12760, 17, 3, 9, 'se bom o-rei bom יהכתוב לאבדם ואחת milhares k-khar- prata esquele sobre יְדֵי עֹשֵׂי a-obra para-trazer a גִּנְזֵ֥י o rei');
INSERT INTO verses VALUES (12761, 17, 3, 10, 'וַיָּ֧סַר o-rei a de-cima-de sua-mão sua mão וַֽיִּתְּנָ֗הּ לְהָמָ֧ן filho-de הַמְּדָ֛תָא הָאֲגָגִ֖י maldito os-judeus');
INSERT INTO verses VALUES (12762, 17, 3, 11, 'E-disse o rei לְהָמָ֔ן o-ouro dado para-ti וְהָעָ֕ם para-fazer nele כּטוֹב em-olhos-teus');
INSERT INTO verses VALUES (12763, 17, 3, 12, 'וַיִקְרְא֔וּ סֹפְרֵי o-rei no-mês o-primeiro בּישֶׁלושָׁה dez dia בוֹ וַיִכְתָּב como-todos-os que a הָמָ֡ן El אֲחַשׁדְרַפְּנֵי־ o-rei e-a הַפַּח֞וֹת que sobre מְדִינָ֣ה e a nação e-a príncipes povo e o povo província e-província conforme-escrita-dela e o povo e-povo conforme-língua-dele em nome o-rei Ahashverosh foi escrito e selado em selo o rei');
INSERT INTO verses VALUES (12764, 17, 3, 13, '[וְנִשְׁל֨וֹחַ] [סְפָרִ֜ים] em-mão-de [הָרָצִים֮] a todo províncias-de [לַהֲרֹ֣ג] [וּלְאַבֵּ֣ד] para-matar [מִנַּ֨עַר] a todo [וְנָשִׁים֙] [בְּי֣וֹם] um [בִּשְׁלוֹשָׁ֥ה] [עָשָׂ֛ר] [לְחֹ֥דֶשׁ] em-dia-de um [אֲדָ֑ר] dez [לָבֽוֹז] doze dez novo');
INSERT INTO verses VALUES (12765, 17, 3, 14, 'PATSHEN o escrito LEHINATEN DAT em-todo MEDINAH UMEDINAH GALUI para-todo HAAMIM a-ser ATADEM LEYOM a-esta');
INSERT INTO verses VALUES (12766, 17, 3, 15, 'HARATZIM sairam דְחוּפִים֙ em-palavra-de o-rei e a lei foi dada em-Susa a-cidadela e-o rei e Hamã habitaram para-beber e a cidade Sushã estava em turbulência;');
INSERT INTO chapters VALUES (430, 17, 4, 17);
INSERT INTO verses VALUES (12767, 17, 4, 1, 'e Mardoqueu saber a todo que foi feita e rasgou מרדכי a as-roupas-seu e vestiu no-meio-de e-aflorou e-saiu em-meio-de a-cidade וַיִּזְעַ֛ק זְעָקָ֥ה grande וּמָרָֽה׃');
INSERT INTO verses VALUES (12768, 17, 4, 2, '[וַיָּב֕וֹא] até diante-de [שַֽׁעַר־הַמֶּ֑לֶךְ] que porque não [אֶל־שַׁ֥עַר] a portão-de o-rei');
INSERT INTO verses VALUES (12769, 17, 4, 3, 'e-em-todo מְדִינָה וּמְדִינָ֗ה lugar que palavra-de o-rei וְדָתוֹ֙ atinga avel grande aos judeus e jejum e pranto e lamento saco וָאֵ֔פֶר foi oferecido a muitos:');
INSERT INTO verses VALUES (12770, 17, 4, 4, 'e veio-nos נַעֲרֹת אֶסְתַּר וְסָרִיסֶיהָ וַיַּגּוּדּוּ para-ela וַתִּתְחַלָּחַל הַמַּלְכָּה muito E ela enviou בְּגָדִים לְהַלְבִּישׁ את- Mordecai וּלְהָסִיר שַׂקּוֹ de cima dele e-não foi aceito');
INSERT INTO verses VALUES (12771, 17, 4, 5, 'e chamou-se: Estar para ahasque מִסָּרִיסֵ֤י o rei que ele estabeleceu diante dela e ordenou-lhe sobre para-conhecer para saber que- isto e-sobre que- isto:');
INSERT INTO verses VALUES (12772, 17, 4, 6, 'e-ele-saiu a hasque a מרדכי a רחוב a-cidade que diante-de shaar- o rei');
INSERT INTO verses VALUES (12773, 17, 4, 7, 'e-contou para-ele [OBJ] את todo e-[OBJ] [׀] e-את [הַכֶּ֗סֶף] [אֲשֶׁ֨ר] disse disse [לִ֠שְׁקוֹל] [עַל־גִּנְזֵ֥י] sobre [*ביהודי[y]*ים] o-rei [לְאַבְּדָֽם]');
INSERT INTO verses VALUES (12774, 17, 4, 8, 'e-a פתשת escriva- a-dáth que dar a-ele para-destruí-los deu a-ele para-mostrar a Esther e-relatar para ela e-ordenar sobre-ele-a vir a o-rei para-implorar- para-ele e pergunte de-ante-o-lhe sobre a-sua-pena;');
INSERT INTO verses VALUES (12775, 17, 4, 9, 'e veio se é e contou a Esther את palavras-de Mardoqueu');
INSERT INTO verses VALUES (12776, 17, 4, 10, 'E-disse Esther se é e ordenou-lhe a Mardoqueu');
INSERT INTO verses VALUES (12777, 17, 4, 11, 'todo servos-de o-rei povo- reinos o-rei יודעים que todo homem e-a-mulher- que irá a uma a החצר הפנימית que não יהקר uma o-ouro para-matar para-fora não ישט- para-ele o-rei a שרביט dia והיה- e-eu não נקראתי para-vir a o-rei este שלשים dia');
INSERT INTO verses VALUES (12778, 17, 4, 12, 'e disseram a Mardoqueu, את palavras-de Estêr');
INSERT INTO verses VALUES (12779, 17, 4, 13, 'E-disse Mardoqueu faça a Estêr a pensa em ti salva casa-de o-rei de-todo os-judeus');
INSERT INTO verses VALUES (12780, 17, 4, 14, 'que se o surdo cala-te em-o-tempo esta espírito e a salvação estará aos judeus de algum lugar outro e tu e-casa-de seu-pai serás destruída e-quem sabe se ao-tempo-de assim atingirá ao reino');
INSERT INTO verses VALUES (12781, 17, 4, 15, 'E-disse [אֶסְתֵּ֖ר] para-responder a');
INSERT INTO verses VALUES (12782, 17, 4, 16, '[לֵךְ֩] [כְּנ֨וֹס] a todo [בְּשׁוּשָׁ֗ן] [וְצ֣וּמוּ] [עָ֠לַי] [וְאַל־תֹּאכְל֨וּ] [וְאַל־תִּשְׁתּ֜וּ] e-a [יָמִים֙] e-a [וָי֔וֹם] três-de dias noite [כֵּ֑ן] também eu [אֶל־הַמֶּ֙לֶךְ֙] [אֲשֶׁ֣ר] [לֹֽא־כַדָּ֔ת] [וְכַאֲשֶׁ֥ר] [אָבַ֖דְתִּי] a que não');
INSERT INTO verses VALUES (12783, 17, 4, 17, 'e-atravessou [מָרְדֳּכָ֑י] E-fez conforme-tudo que [עָלָ֖יו] sobre-ele');
INSERT INTO chapters VALUES (431, 17, 5, 14);
INSERT INTO verses VALUES (12784, 17, 5, 1, 'e-houve em-o-dia no-dia וַתִּלְבַּ֤שׁ Esther מלכות והתחייבה no-házar casa-de o rei o-interno נחבק casa o-rei והמלך ישוב sobre trono מלכותו em-casa-de o-reino נחבק porta a-casa');
INSERT INTO verses VALUES (12785, 17, 5, 2, 'e-houve כראות o-rei a אסתר a rainha estando no-hatzé'' levou graça em-olhos-dele e estendeu o-rei para Éstir o-ouro cetro o-ouro que em-mão-de-ele e se aproximou Esther e tocou na cabeça o sarbet');
INSERT INTO verses VALUES (12786, 17, 5, 3, 'E-disse a-ela o-rei que para-ti Estar a-rainha e-que וַאֲבֹקֻשְׁתֶּךְ até para-ti o malkhut e yinnaten para-ti');
INSERT INTO verses VALUES (12787, 17, 5, 4, 'E-disse Esther se bom o-rei bom vira o-dia e Haman o-dia a-ele o misheth que fiz a-ele');
INSERT INTO verses VALUES (12788, 17, 5, 5, 'E-disse o-rei meharu a Haman para-fazer a palavra Estar E-veio o rei וְהָמָ֔ן a הַמִּשְׁתֶּ֖ה que ʿašṭā Estér:');
INSERT INTO verses VALUES (12789, 17, 5, 6, 'E-disse o-rei [לְאֶסְתֵּר֙] [בְּמִשְׁתֵּ֣ה] [הַיַּ֔יִן] que [וְיִנָּ֣תֵֽן] para-ti a-ti e-que [הַמַּלְכ֖וּת] até');
INSERT INTO verses VALUES (12790, 17, 5, 7, 'וַתַּ֥עַן Estér: E disse ela שאלהתי e no meu pedido');
INSERT INTO verses VALUES (12791, 17, 5, 8, 'se achei grace em-olhos-de o rei bom sobre o rei bom para dar a pedi e para fazer a no meu pedido virá a-eles e Hamã a הַמִּשְׁתֶּה֙ que farei disse e no dia seguinte farei conforme-palavra-de o rei');
INSERT INTO verses VALUES (12792, 17, 5, 9, 'e-saiu Haman no-dia aquele se alegrasse e-bom coração e viu Haman a Mardoqueu בְּשַׁעַר o-rei e-não nós e-não tremeu dele e encheu-se Haman sobre Mardoqueu Chema:');
INSERT INTO verses VALUES (12793, 17, 5, 10, 'e se apenou Hamã e veio a casa-dele e-trouxe E-veio a seus amores e-a Zeresh esposa-dele');
INSERT INTO verses VALUES (12794, 17, 5, 11, 'e contou a-eles Hamã a glória sua riqueza e rov em seus filhos e-את todo que seu-gro o-rei e-a que sua fama sobre os-senhores e seus servos o rei');
INSERT INTO verses VALUES (12795, 17, 5, 12, 'E-disse Haman certamente não levou Esther a rainha com o-rei que o banquete que fez-a porque se a-m-me e-também לְמָחָ֛ר eu chamar-se-á para-ela com o rei');
INSERT INTO verses VALUES (12796, 17, 5, 13, 'e-todo isto não-ela igual-a a-mim em-todo עֵת que eu viu a mardoqueu o-judeu habitante em-porta-de o rei');
INSERT INTO verses VALUES (12797, 17, 5, 14, 'E-disse a-ele zeres sua-mulher e-todo seus-amores Façam- árvore- altura- cinquenta אמה -e no alvorecer, disse do-rei e pendurem- a Mardoqueu- sobre-ele -e venha- com o-rei a festa alegre-se e-foi-bom a-palavra a-árvore Hamaan E-fez o-árvore:');
INSERT INTO chapters VALUES (432, 17, 6, 14);
INSERT INTO verses VALUES (12798, 17, 6, 1, 'na-noite aquele נָדְדָ֖ה ano-de o-rei E-disse para trazer a ספר as-zicronot palavras-de os-dias e-foram nikra''im diante-de o rei');
INSERT INTO verses VALUES (12799, 17, 6, 2, 'e achou kathuv que declarou Mardokhai sobre bigtan''a vatresh segundo sarise'' o-rei mishe''more'' hasaf que busquem mão mão no- rei Ahasverus');
INSERT INTO verses VALUES (12800, 17, 6, 3, 'E-disse o-rei que נַּעֲשָׂ֞ה glória e grandeza para- Mardoqueu sobre esta e-disseram נערֵי o rei seus-servos não naasah disse palavra');
INSERT INTO verses VALUES (12801, 17, 6, 4, 'E-disse o-rei quem no-pátio e-Haman veio no-pátio casa-de o rei dizendo dizendo para-o-rei ЛИТЛЕВОТ a מרדכי a-ele a-árvore que hechin a-ele');
INSERT INTO verses VALUES (12802, 17, 6, 5, 'e-disseram נַעֲרֵ֤י o rei a-ele eis Hamán ficou-em-pé בהחצר E-disse o-rei יהבא׃');
INSERT INTO verses VALUES (12803, 17, 6, 6, 'WAYYAVAO Hamán E-disse a-ele o-rei que para fazer בהאיש que o-rei agrada-se E-disse E-disse Hamán בליבבו לְמִ֞י יַחְפֹּ֥ץ o-rei para-fazer יקר mais de-mim');
INSERT INTO verses VALUES (12804, 17, 6, 7, 'E-disse [הָמָ֖ן] a o-rei homem que o-rei desejava');
INSERT INTO verses VALUES (12805, 17, 6, 8, '[יָבִ֙יאוּ֙] [לְב֣וּשׁ] [מַלְכ֔וּת] que [לָֽבַשׁ־בּ֖וֹ] nele o-rei [אֲשֶׁ֨ר] que [עָלָיו֙] sobre-ele o-rei e-que deu [מַלְכ֖וּת] reino-de');
INSERT INTO verses VALUES (12806, 17, 6, 9, 'וְנָת֨וֹן הַלְּב֜וּשׁ וְהַסּ֗וּס sobre mão-de homem מִשָׂרֵ֤י o-rei הַֽפַּרְתְּמִ֔ים וְהִלְבִּ֙ישׁוּ֙ a o-homem que o-rei agrada-se בִּֽיקָר֑וֹ e o carreguem-no sobre o cavalo בִּרְח֣וֹב a-cidade e chamem-no diante-dele assim será feito para-o homem que o-rei desejava na sua presença:');
INSERT INTO verses VALUES (12807, 17, 6, 10, 'E-disse o-rei para Hamã logo, depressa toma a o vestido e-a o cavalo como falaste e faça-o assim מרדכי היוודאי o sentado בְּשַׁעַר de-toda a תפל palavra de-todo que dibartā׃');
INSERT INTO verses VALUES (12808, 17, 6, 11, 'E-tomou [הָמָן֙] a [וְאֶת־הַסּ֔וּס] e-[OBJ] [אֶֽת־מָרְדֳּכָ֑י] [וַיַּרְכִּיבֵ֙הוּ֙] a [הָעִ֔יר] E-chamou [לְפָנָ֔יו] a-cidade E-chamou diante-dele assim [הַמֶּ֖לֶךְ] para-o homem que');
INSERT INTO verses VALUES (12809, 17, 6, 12, 'e-voltou [מָרְדֳּכַ֖י] a portão o-rei [נִדְחַ֣ף] [אֶל־בֵּית֔וֹ] a casa-dele [רֹֽאשׁ] cabeça');
INSERT INTO verses VALUES (12810, 17, 6, 13, 'VASAPR וְהָמָן֙ לZRSH sua-mulher e-para-todo- אוحبיו a todo que a-ele וַיֹּ֩אמְרוּ֩ a-ele seus-sábios e-zeres esposa-dele mãe מזרע os-judeus mardoqueu que te-alegrou para-cair a-ele não poderias a-ele porque cair vai-cair diante-de-ele');
INSERT INTO verses VALUES (12811, 17, 6, 14, '[עוֹדָם֙] [מְדַבְּרִ֣ים] com-ele [וְסָרִיסֵ֥י] o-rei [הִגִּ֑יעוּ] [וַיַּבְהִ֙לוּ֙] [לְהָבִ֣יא] a [אֶל־הַמִּשְׁתֶּ֖ה] a [אֶסְתֵּֽר] que');
INSERT INTO chapters VALUES (433, 17, 7, 10);
INSERT INTO verses VALUES (12812, 17, 7, 1, 'E-veio o rei וְהָמָן para-beber com Estar a rainha:');
INSERT INTO verses VALUES (12813, 17, 7, 2, 'E-disse o-rei אסתר também no-dia o-segundo no banquete do vinho que sua solicitação אסתר a rainha: para-ti a-ti e-que em sua solicitação até metade-de o reino e será feito;');
INSERT INTO verses VALUES (12814, 17, 7, 3, 'e-respondeu Estar a-rainha e-disse se achei graça em-olhos-teus o-rei bom sobre o-rei bom תִּנָּֽתֶן־ para-mim morrendo em minha oração e-o-seu-povo na minha busca;');
INSERT INTO verses VALUES (12815, 17, 7, 4, 'que fomos vendidos eu e meu povo para destruí-los para exterminá-los e para os aniquilar e se aos servos e-lishpahot foram vendidos eu ouvi que não-há o perseguidor é por dano o rei');
INSERT INTO verses VALUES (12816, 17, 7, 5, 'E-disse o-rei Assuero E-disse a Esther a-rainha quem ele este e ele ele que מְלָא֥וֹ para-seu-coração para-fazer assim');
INSERT INTO verses VALUES (12817, 17, 7, 6, 'וַתֹּ֣אמֶר־ Esther homem angústia-de e inimigo הָמָ֥ן a-má esta וְהָמָ֣ן נִבְעַ֔ת de-a-frente-de o-rei וְהַמַּלְכָּֽה׃');
INSERT INTO verses VALUES (12818, 17, 7, 7, 'וְהַמֶּ֜לֶךְ קָ֤ם בַּחֲמָתוֹ֙ mímishte o-ayin a גִּנַּ֖ת o-bitan e-haman ficou-em-pé para-que-se-peshe sobre sua-alma que ver porque a-ele porque )(((כָלְתָ֥ה))) a-ele o-mal de-a o rei');
INSERT INTO verses VALUES (12819, 17, 7, 8, 'e-o-melek retornou גִּנַּ֖ת o-bitan a casa-de banquete-de o-vinho וְהָמָ֖ן sobre הַמִּטָּה֙ que Estér sobre-ela E-disse o-rei הֲ֠גַם לִכְבּ֧וֹשׁ a a-rainha com-mim ba-bayit sair יָצָא de-boca-de o-rei e-פְנֵ֥י הָמָ֖ן חָפֽוּ׃');
INSERT INTO verses VALUES (12820, 17, 7, 9, 'E-disse חַ֠רְבוֹנָה um de הַסָּרִיסִ֜ים diante-de também também eis-que- הָעֵ֣ץ que fez Hamán para Mardochéi que falou bom sobre o rei ficou-em-pé E-disse המן alta-alta cinquenta medida E-disse o-rei vocais-se pendureis sobre-ele');
INSERT INTO verses VALUES (12821, 17, 7, 10, 'e penduraram a המן sobre a-árvore que ele-preparou para Mardochéi e ira-se o-rei devez-escândalo');
INSERT INTO chapters VALUES (434, 17, 8, 17);
INSERT INTO verses VALUES (12822, 17, 8, 1, 'no-dia aquele dar o-rei Ahashverosh l''Ester a-rainha a casa Hamán Tsorer uMardokay veio diante-de o-rei porque higga Ester o-que ele a-ela');
INSERT INTO verses VALUES (12823, 17, 8, 2, 'va''yasar o-rei a tavatto que he''ebira מֵהָמָ֔ן e-lhe-deu: לְמָרְדֳּכָ֑י e-colocou Estar a מָרְדֳּכַ֖י sobre casa הָמָֽן׃');
INSERT INTO verses VALUES (12824, 17, 8, 3, 'וַתּ֣וֹסֶף Estar e-você-falou diante-de o-rei e caiu diante-de seus-pés וַתֵּ֣בְךְּ וַתִּתְחַנֶּן־ para-ele לְהַֽעֲבִיר֙ a רעה המן הָאֲגָגִי e-את מחשבתו que חשב sobre os-judeus');
INSERT INTO verses VALUES (12825, 17, 8, 4, 'VASHE''T o rei para-Estêr a שרביט o-ouro e-levantou-se Esther e-ela-ficou-em-pé diante-de o rei');
INSERT INTO verses VALUES (12826, 17, 8, 5, 'E-disse se bom o-rei bom e-se מציתי graca diante-dele וכasher a-palavra diante-de o-rei e boa eu em-olhos-dele será escrito לְהָשִׁ֣יב a os livros escritório Haman filho-de a medida o agagita que será escrito para destruir a os-judeus que em-todo מְדִינ֥וֹת o rei');
INSERT INTO verses VALUES (12827, 17, 8, 6, 'que [אֵיכָכָ֤ה] posso [וְֽרָאִ֔יתִי] [בָּרָעָ֖ה] que [אֶת־עַמִּ֑י] a meu-povo [וְֽרָאִ֔יתִי] posso [מוֹלַדְתִּֽי׃]');
INSERT INTO verses VALUES (12828, 17, 8, 7, 'E-disse o-rei אֲחַשְׁוֵרֹשׁ֙ לְאֶסְתֵּ֣ר a-rainha e-marcardi o-yhudi eis casa-de dei dei para Ésther e-o voc-valeis sobre o-arvore sua-mão que enviou mão-sua');
INSERT INTO verses VALUES (12829, 17, 8, 8, 'e-voi escriv-ei-sedes sobre os judeus como-bom nos-vosso-olhos no-nome-de o-rei e-sel-gardai em-batáttah o-rei porque kéthab que foi escrito em-o-nome-de o-rei vé-nakhthóm em-batáttah o-rei não le-háshev');
INSERT INTO verses VALUES (12830, 17, 8, 9, 'va-yíqrá''u sóferé- o-rei bá''- ha-híya no mês o-terceiro ele novo סיוואן בישלושעה e vinte— בוֹ WAYYIKKATÊV e-para que ordenou מרדכי a היהודים e-a האחשדרפנים e as pequenas VASERÊI המדינות que desde-Índia e-até כוש sete e-vinte וּמֵאָה֙ מְדִינָה província e-província conforme-escrita-dela yhwh e-povo כִּלְשֹׁנ֑וֹ e-a os-judeus כִּכְתָבָ֖ם וְכִלְשׁוֹנָֽם׃');
INSERT INTO verses VALUES (12831, 17, 8, 10, 'וַיִּכְתֹּ֗ב בְּשֵׁם֙ o-rei אֲחַשְׁוֵרֹ֔שׁ וַיַּחְתֹּ֖ם בְּטַבַּ֣עַת o-rei e-enviou סְפָרִים בְּיַד֩ os correndo בַּסּוּסִ֜ים רֹכְבֵ֤י הָרֶ֙כֶשׁ֙ הָֽאֲחַשְׁתְּרָנִ֔ים filhos-de הָֽרַמָּכִֽים׃');
INSERT INTO verses VALUES (12832, 17, 8, 11, 'que dar o-rei לַיְּהוּדִ֣ים que em-todo עִיר־ e a cidade para reunir e para aprender sobre as almas para destruir e para matar e para exterminar a todo eles povo e a cidade os inimigos eles o povoado e-nashtim u-shalalam /laboz/');
INSERT INTO verses VALUES (12833, 17, 8, 12, 'em-dia-de um em-todo províncias-de o-rei Ahasverus בִּשְׁלֹשָׁה dez le-chodesh doze dez ele novo adhar');
INSERT INTO verses VALUES (12834, 17, 8, 13, 'patshagen ha-ketav le-hinaten dat em-todo medina e a cidade exposto para-todo as nações e-serão no dia esta para vingar-se de seus inimigos');
INSERT INTO verses VALUES (12835, 17, 8, 14, 'os corredores montadores de prata os carregadores sairão מבוהלים ודחופים em-palavra-de o-rei e a lei נתנה em-Susã a-fortaleza');
INSERT INTO verses VALUES (12836, 17, 8, 15, 'ומרדכי sair de-diante-de o rei בלבush reino תכלת וחור ואטרeta ouro ouro ותכריכ בּוּץ וְאַרְגָּמָ֑ן e a cidade שׁוּשָׁ֔ן צָהֲלָ֖ה וְשָׂמֵֽחָה׃');
INSERT INTO verses VALUES (12837, 17, 8, 16, 'לַיְּהוּדִ֕ים era אוֹרָ֖ה e alegria וְשָׂשֹׂ֖ן וִיקָֽר׃');
INSERT INTO verses VALUES (12838, 17, 8, 17, 'e-em-todo מְדִינָה וּמְדִינָה e-em-todo cidade e-cidade lugar que palavra-de o-rei וְדָתוֹ֙ מַגּ֔יעַ שִׂמְחָ֤ה וְשָׂשׂוֹן֙ bom banquete וְיוֹם a-terra וְרַבִּ֞ים מֵֽעַמֵּ֤י a-terra מִֽתְיַהֲדִ֔ים porque cair Păchad- ele sobre-eles');
INSERT INTO chapters VALUES (435, 17, 9, 32);
INSERT INTO verses VALUES (12839, 17, 9, 1, 'uvišneim- dez novo ele novo Ădar bı̂shloshā dia dia nele que higgāʻa palavra-de o-rei no-dia lêheʿasōta băyôm que šı̂ḇrū ʾōyevê hayyăhudı̂m para governar ele e invertam ele que governem os judeus eles a seus inimigos:');
INSERT INTO verses VALUES (12840, 17, 9, 2, 'foram honrados os judeus em suas cidades em-todo e em seus distritos o-rei Acosvérus mão mão com os que buscavam רָעָתָם e-homem não ficou-em-pé em-frente-de-eles porque cair פַּחְדָּם sobre todo הָעַמִּים׃');
INSERT INTO verses VALUES (12841, 17, 9, 3, 'e-todo príncipes-de [וְהָאֲחַשְׁדַּרְפְּנִ֣ים] [וְהַפַּח֗וֹת] [וְעֹשֵׂ֤י] [הַמְּלָאכָה֙] [אֲשֶׁ֣ר] que para-o-rei [אֶת־הַיְּהוּדִ֑ים] a [פַּֽחַד־מָרְדֳּכַ֖י] porque');
INSERT INTO verses VALUES (12842, 17, 9, 4, 'porque grande [בְּבֵ֣ית] em-casa-de o-rei [הוֹלֵ֣ךְ] andando em-todo [מָרְדֳּכַ֖י] porque o-homem');
INSERT INTO verses VALUES (12843, 17, 9, 5, 'e-feriram היהודים em-todo אויביהם כata- espada והרג ואבדן e fizeram contra eles segundo-seu-desejo');
INSERT INTO verses VALUES (12844, 17, 9, 6, 'e Susã a cidade mataram os judeus e destruíssem cinco centenas homem');
INSERT INTO verses VALUES (12845, 17, 9, 7, 'e-[OBJ] [׀] [פַּרְשַׁנְדָּ֛תָא] e-[OBJ] [׀] [דַּֽלְפ֖וֹן]');
INSERT INTO verses VALUES (12846, 17, 9, 8, 'e-[OBJ] [׀] [פּוֹרָ֛תָא] e-[OBJ] [׀] [אֲדַלְיָ֖א]');
INSERT INTO verses VALUES (12847, 17, 9, 9, 'e-[OBJ] [׀] e-את e-[OBJ] [׀] [אֲרִיסַ֔י] e-[OBJ] [׀]');
INSERT INTO verses VALUES (12848, 17, 9, 10, 'עֲשֶׂרֶת filhos-de הָמָ֧ן filho-de הַמְּדָ֛תָא צֹרֵ֥ר os judeus mataram não não שָׁלְחוּ a as mãos');
INSERT INTO verses VALUES (12849, 17, 9, 11, 'no-dia aquele veio em-o-número que matem em-Susã a-cidadela diante-de o rei');
INSERT INTO verses VALUES (12850, 17, 9, 12, 'E-disse o-rei a Esther a rainha em-Susa o palácio mataram os judeus וְאַבֵּ֜ד cinco centenas-de homem e-את dez filhos-de הָמָ֔ן בִּשְׁאָ֛ר מְדִינ֥וֹת o-rei que עָשׂוּ e-que para-ti וְיִנָּ֣תֵֽן para-ti e-que בַּקָּשָׁתֵ֥ךְ a-ele וְתֵעָֽשׂ׃');
INSERT INTO verses VALUES (12851, 17, 9, 13, 'E-disse Esther se bom o-rei bom [לַיְּהוּדִים֙] também amanhã [לַעֲשׂ֖וֹת] que o-dia e-[OBJ] [עֲשֶׂ֥רֶת] o-dia e-[OBJ] dez sobre');
INSERT INTO verses VALUES (12852, 17, 9, 14, 'E-disse o-rei para fazer assim foi dada Dáth em Beshúshán e-a dez filhos-de Hamán serão pendurados:');
INSERT INTO verses VALUES (12853, 17, 9, 15, 'e reuniram-se que em Beshúshán também também quatro quatro para o mês אדר e mataram Shushan três centenas homem e em Pesseguine não não a suas mãos:');
INSERT INTO verses VALUES (12854, 17, 9, 16, 'e-restante-de os judeus que em suas províncias o-rei foram honrados וְעָמֹ֣ד sobre נַפְשָׁ֗ם וְנ֙וֹחַ֙ מֵאֹ֣יְבֵיהֶ֔ם וְהָרֹג֙ בְּשֹׂ֣נְאֵיהֶ֔ם cinco e-setenta mil וּבַ֨בִּזּ֔ה não שָֽׁלְח֖וּ a יָדָֽם׃');
INSERT INTO verses VALUES (12855, 17, 9, 17, 'em-dia-de três dez [אֲדָ֑ר] [וְנ֗וֹחַ] [בְּאַרְבָּעָ֤ה] [עָשָׂר֙] dez nele ele dia dia [וְשִׂמְחָֽה]');
INSERT INTO verses VALUES (12856, 17, 9, 18, 'que בשושן נקהלוּ biesheloshah dez nele ובערבעה dez nele ונוח no-chamishah dez nele e-asa a-ele ele dia e alegria');
INSERT INTO verses VALUES (12857, 17, 9, 19, 'sobre kéen os judeus os-yoshvim em-cidades-de as-perazot fazem a dia dia quatro para-chodesh adhar e alegria e beber וְיוֹם bom bom comidas homem para-o');
INSERT INTO verses VALUES (12858, 17, 9, 20, 'e escreveu Mardoqueu a as-palavras estas e-enviou livros a todo os judeus que em-todo estados o-rei Assuero próximos e distantes:');
INSERT INTO verses VALUES (12859, 17, 9, 21, 'לְקַיֵּם֮ עֲלֵיהֶם֒ para-ser- fizeram a dia quatro dez לְחֹ֣דֶשׁ אֲדָ֔ר e-a dia-de cinco dez nele em-todo ano וְשָׁנָֽה׃');
INSERT INTO verses VALUES (12860, 17, 9, 22, 'כַּיָּמִ֗ים que נָ֨חוּ בָהֶ֤ם הַיְּהוּדִים֙ de seus inimigos e o mês que a-eles para-eles מִיּוֹגֹן para alegria e do luto bom bom para fazer dias-de os-dias de-bebida para alegria e de missão ofertas homem para-seu-amigo e presentes aos necessitados:');
INSERT INTO verses VALUES (12861, 17, 9, 23, '[וְקִבֵּל֙] os-judeus a que [לַעֲשׂ֑וֹת] e-[OBJ] e-[OBJ] que [אֲלֵיהֶֽם]');
INSERT INTO verses VALUES (12862, 17, 9, 24, 'que haman filho-de a-mada הָאֲגָגִי צֹרֵר todo os-judeus חָשַׁ֥ב sobre הַיְּהוּדִ֖ים ele וְהִפִּ֥יל פּוּר֙ ele הַגּוֹרָ֔ל para-destruí-los e para destruí-los:');
INSERT INTO verses VALUES (12863, 17, 9, 25, 'וּבְבֹאָהּ֮ diante-de הַמֶּלֶךְ֒ disse com ha-sefer יָשׁ֞וּב suas-máximas הָרָעָה que calculou sobre ele sobre sua-cabeça e-hangaram a-ele e-a comerás sobre o-árvore:');
INSERT INTO verses VALUES (12864, 17, 9, 26, 'sobre assim chamaram aos-mares הָאֵ֤לֶּה purim sobre nome o-pur sobre assim sobre todo palavras-de a-mensagem esta e-que viram sobre ká-ká וּמָ֥ה atingiram a-eles');
INSERT INTO verses VALUES (12865, 17, 9, 27, 'avaliam os judeus neles e-sobre seu semente e-sobre todo aqueles que foram vendidos sobre-eles e-não passará por para-ser- fazem a segundo os-dias os-estes como escritos e no tempo em-todo ano e ano:');
INSERT INTO verses VALUES (12866, 17, 9, 28, 'e os dias הָאֵלֶּה serão lembrados e serão feitos em-todo geração geração família e família nação e nação e cidade e cidade וִימֵ֞י os purim não não passarão de-meio-de os-judeus e a memória deles não o safa do seu germe');
INSERT INTO verses VALUES (12867, 17, 9, 29, 'e escreveu esther a rainha filha-de avichayil וּמָרְדֳּכַ֥י o judeu a todo תֹּ֑קֶף לְקַיֵּ֗ם a אִגֶּ֧רֶת הַפּוּרִ֛ים a-esta a segunda');
INSERT INTO verses VALUES (12868, 17, 9, 30, 'e-enviou סְפָרִ֜ים a todo הַיְּהוּדִ֗ים a sete e-vinte וּמֵאָה֙ מלכה reino-de Ahasverus palavras-de paz e-verdade');
INSERT INTO verses VALUES (12869, 17, 9, 31, '[לְקַיֵּ֡ם] a [הַפֻּרִ֨ים] [הָאֵ֜לֶּה] [בִּזְמַנֵּיהֶ֗ם] [כַּאֲשֶׁר֩] como-que [עֲלֵיהֶ֜ם] [מָרְדֳּכַ֤י] [הַיְּהוּדִי֙] [וְאֶסְתֵּ֣ר] [הַמַּלְכָּ֔ה] a-rainha e-como-que [עַל־נַפְשָׁ֖ם] sobre [דִּבְרֵ֥י] e-sobre [וְזַעֲקָתָֽם]');
INSERT INTO verses VALUES (12870, 17, 9, 32, 'וּמַאֲמַ֣ר Esther קִיַּ֕ם palavras-de os-purímeis estas e-escrito no-sepher:');
INSERT INTO chapters VALUES (436, 17, 10, 3);
INSERT INTO verses VALUES (12871, 17, 10, 1, 'e-ele-colocou o-rei imposto sobre a-terra e-ai o-mar:');
INSERT INTO verses VALUES (12872, 17, 10, 2, 'e-todo Masháv atrapem-no e sua força e-despache-a grandezas mardoqueu que sua-grandezas o-rei porventura-não eles escritos sobre סֵ֙פֶר֙ palavras-de os-dias לְמַלְכֵ֖י מָדַ֥י ופרס׃');
INSERT INTO verses VALUES (12873, 17, 10, 3, 'que מָרְדֳּכַ֣י הַיְּהוּדִ֗י מִשְׁנֶה֙ para-o-rei Assuero וְגָדוֹל֙ לַיְּהוּדִים וְרָצ֖וּי לְרֹ֣ב seus-irmaos דֹּרֵ֥שׁ bom bom וְדֹבֵ֥ר paz para-todo זַרְעֽוֹ');
INSERT INTO books VALUES (18, 'JOB', 'Jó', 'AT', 42);
INSERT INTO chapters VALUES (437, 18, 1, 22);
INSERT INTO verses VALUES (12874, 18, 1, 1, 'homem ser em-terra- conselho Iov seu-nome e-era o-homem aquele tãm e-yashar E-viu Elohim וְסָ֥ר מֵרָע׃');
INSERT INTO verses VALUES (12875, 18, 1, 2, 'vayivuldu a-ele sete filhos veshalosh banoth');
INSERT INTO verses VALUES (12876, 18, 1, 3, 'e-houve miqnehu shivath alfei- tsón e-três-de de-milhares camelos וַחֲמֵ֨שׁ centenas pare-de manhã e-cinco centenas-de as-éguas muito e-houve muito E-foi o-homem a-aquela grande de-todo filhos-de adiante');
INSERT INTO verses VALUES (12877, 18, 1, 4, 'e-andaram seus-filhos e fizeram banquete casa homem seu-dia e-enviaram e-chamaram para-três para-comer e-para-dois com-eles-verso-final');
INSERT INTO verses VALUES (12878, 18, 1, 5, 'e-houve que cercaram dias-de a-festa e-ele-mandou Iov e-os-consagraram e-se-levantaram na-manhã e-ele-ofereceu holocaustos número todos-os-verso-final que disse Iov talvez pecaram filhos-de e-bendizem Elohim com-o-lar-da-mente-deles assim ele-fará Iov todo os dias');
INSERT INTO verses VALUES (12879, 18, 1, 6, 'e-houve o-dia e-vieram filhos-de os-Elohim para-se-posicionar sobre yhwh e-ele-vaiu também o-satanas em-meio-de-eles');
INSERT INTO verses VALUES (12880, 18, 1, 7, 'E-disse yhwh a o diabo de-onde vem e-ele-respondeu o diabo a yhwh E-disse de sedução na-terra e andar nela');
INSERT INTO verses VALUES (12881, 18, 1, 8, 'E-disse yhwh a o-satanas se-estabeleceste לִבְּךָ֖ sobre que i-yov porque não-há como-ele na-terra homem perfeito e-reto temor Elohim וְסָ֥ר מֵרָע׃');
INSERT INTO verses VALUES (12882, 18, 1, 9, 'e-respondeu o-diabo a yhwh E-disse temer tem medo Iyov Elohim');
INSERT INTO verses VALUES (12883, 18, 1, 10, 'não conversaste em-sua-favor e-atrás-de- sua-casa e-em-o todo que para-ele em-o-redor trabalho de-suas-mãos bendisseste e-de-seu-monta-ro estendeu na-terra');
INSERT INTO verses VALUES (12884, 18, 1, 11, 'e-entretanto envia- por-favor mão-tua e-toque em-todo que para-ele se não sobre  פָּנֶ֖יךָ  bendiga-te-o');
INSERT INTO verses VALUES (12885, 18, 1, 12, 'E-disse yhwh a eis eis todo que a-ele em tua mão somente para-ele a tens-lhe face-de yhwh o-satanas de-com face-de yhwh');
INSERT INTO verses VALUES (12886, 18, 1, 13, 'e-houve o-dia e-seus-filhos e-seus-filhas comedores e-bebedores vinho em-o-casa seus-irmãos הbachor:');
INSERT INTO verses VALUES (12887, 18, 1, 14, 'e-anjo veio a Iov E-disse o-bovino foram seus-cortadores-de-mato e-as-jumentas má-sucedidas sobre mãos-deles-verso-final');
INSERT INTO verses VALUES (12888, 18, 1, 15, 'e-caiu-se sheva e-ela-os-tomou e-a os-jovens hikchu à-boca-de espada e-eu-me-salvei somente para-ti sozinho para-dizer para-ti');
INSERT INTO verses VALUES (12889, 18, 1, 16, 'od este m''daber e-isto veio E-disse fogo Elohim caiu de os-céus ela se purificou entre o rebanho e nos jovens ela os comeu e escapei somente eu sozinho para-ti para-ti');
INSERT INTO verses VALUES (12890, 18, 1, 17, 'ainda- este falando וְזֶה֮ veio E-disse dos-caldeus colocaram- três chefes e-eles-despiram-se sobre os-camelos e-eles-tomaram-os e-a os-jovens hikchu à-boca-de espada e-eu-fugira somente eu para-ti para-dizer para-ti');
INSERT INTO verses VALUES (12891, 18, 1, 18, 'até este falando vezeh veio E-disse os-teus-filhos e-as-tuas-filhas comedores e-bebedores vinho בבית seus-irmãos הbachor:');
INSERT INTO verses VALUES (12892, 18, 1, 19, 'e-eis espírito grande veio-a de-über o-deserto e-chegou em-quatro as narinas a-casa e-caiu sobre os-jovens e-eles-morreram e-eu-salvei-me somente eu sozinho para-ti para-ti');
INSERT INTO verses VALUES (12893, 18, 1, 20, 'E-levantou Ió e-ele-partiu a de-sua-veste e-ele-se-encheu a sua-cabeça e-caiu terra-para e-prostrou-se');
INSERT INTO verses VALUES (12894, 18, 1, 21, 'E-disse arom mib-te-en mãe-minha e-arom a-shu-ve shama yhwh deu yhwh dar seja nome haja m-borakh');
INSERT INTO verses VALUES (12895, 18, 1, 22, 'em-todo esta não pecou i-yov e-não deu para-afastar para-elohim');
INSERT INTO chapters VALUES (438, 18, 2, 13);
INSERT INTO verses VALUES (12896, 18, 2, 1, 'e-houve o-dia e-vieram filhos-de הָֽאֱלֹהִ֔ים para-se-posicionar sobre yhwh וַיָּבֹא também o-satanás em-eles para-se-estabelecer sobre yhwh');
INSERT INTO verses VALUES (12897, 18, 2, 2, 'E-disse yhwh a HASATAN onde de-este TABOA e-ele-respondeu o satanás a yhwh E-disse de um atirar na-terra e andando nela');
INSERT INTO verses VALUES (12898, 18, 2, 3, 'E-disse yhwh a o satanás tornaste-te no teu coração a que aquele que é porque nao-ha como tu na terra homem perfeito e retiro o temeu Elohim e-se-apartará de mal e nele contendo nele volveu-me em-ele para engolir em vão:');
INSERT INTO verses VALUES (12899, 18, 2, 4, 'e-respondeu ha-satan a yhwh pele pele e-tudo o''or e-todo que para-o homem irá dar por-causa-de sua-alma:');
INSERT INTO verses VALUES (12900, 18, 2, 5, 'ulam envia- por-favor mão-tua ve-ga'' a at-zmo e-a em-a-carne-dele se não a  פָּנֶ֖יךָ  abençoe-te');
INSERT INTO verses VALUES (12901, 18, 2, 6, 'E-disse yhwh a o-diabo eis-o em-mão-tua mas- a נַפְשׁוֹ guarda');
INSERT INTO verses VALUES (12902, 18, 2, 7, 'e-saiu o-satanas de-com face-de yhwh e-ele-feriu a Iov mal mau da-mão-de ragleo cabelo-dele');
INSERT INTO verses VALUES (12903, 18, 2, 8, 'e-tomou para-ele silencio para-se-despir nele e-ele habitou em-meio-de o-poeira');
INSERT INTO verses VALUES (12904, 18, 2, 9, 'E-disse a-ele mulher-dele ainda-tua contendo em-teu-perfeição abençoou Elohim e-morrerás');
INSERT INTO verses VALUES (12905, 18, 2, 10, 'E-disse a-ela como-falar-de uma as-insanidades תְּדַבֵּ֔רִי também a התוב nós-receberemos de-junto-de os-Elohim não a-má não nós-receberemos em-todo esta não pecado Iov com-sua-boca');
INSERT INTO verses VALUES (12906, 18, 2, 11, 'e-ouviram três amigos Jó com todo a má desta que-vem sobre-ele e-vieram homem mikom Elifaz o-têmanita e-Bildade o-suhita e-Tsophar o-namati e-viuvadu juntos לָב֥וֹא la-nud- para-ele ve-lanachamo:');
INSERT INTO verses VALUES (12907, 18, 2, 12, 'e-visaeu a eyneihem me-rachok e-não hikiruhu e-levantaram voz-deles e-vibku e-viqre''u homem manto-dele pó po-e sobre rosh-em הַשָׁמָֽיְמָה׃');
INSERT INTO verses VALUES (12908, 18, 2, 13, 'e sentaram-se com-ele para a terra sete dias e sete noites e-não-há a-ele a-ele que porque viram porque muito o caos muito');
INSERT INTO chapters VALUES (439, 18, 3, 26);
INSERT INTO verses VALUES (12909, 18, 3, 1, 'depois-de assim abriu Iov a boca-sua e-maldito a seu dia;:');
INSERT INTO verses VALUES (12910, 18, 3, 2, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (12911, 18, 3, 3, 'perder-se dia filho-de-avó nele e-o-noite disse hora גבר׃');
INSERT INTO verses VALUES (12912, 18, 3, 4, 'o-dia aquele haja escuridão a ele-o-procurará Eloah  de cima e-a erupção em-ele rio');
INSERT INTO verses VALUES (12913, 18, 3, 5, 'eles-o-exaltarão escuridão e-trevas descansará- sobre-ele nuvem yebatahu dia dia');
INSERT INTO verses VALUES (12914, 18, 3, 6, 'ha-laylah ha-hu yiqqachehu ofel a yichadd em-dias-de ano em-número yerachim a virá');
INSERT INTO verses VALUES (12915, 18, 3, 7, 'eis a noite ha-hu haja galmud a virá nele nele-verso');
INSERT INTO verses VALUES (12916, 18, 3, 8, 'יִקְּבֻ֥הוּ orrei- dia os-futuros que-estimula Liwyathan');
INSERT INTO verses VALUES (12917, 18, 3, 9, 'eles-esconderão-se de-estrelas seu-vapor esperará- para-a-luz e-não-havia e-a -terá-o nas-páneles-de- alvorde');
INSERT INTO verses VALUES (12918, 18, 3, 10, 'que não fechar portas de-meu-ventre e-ele-escondeu trabalho מֵעֵינָֽי׃');
INSERT INTO verses VALUES (12919, 18, 3, 11, 'por-que não מֵרֶ֣חֶם morrerei de-de-virilha eu-saí e-eu-queixo-me');
INSERT INTO verses VALUES (12920, 18, 3, 12, 'מַ֭דּוּעַ antecede-me de-minhas-canelas e-que que porque inácio');
INSERT INTO verses VALUES (12921, 18, 3, 13, 'porque agora e-eu-deitei-me e-eu-descanso jashanti então yanucha para-mim');
INSERT INTO verses VALUES (12922, 18, 3, 14, 'com malkim ve-oyachei terra os-construtores choravot a-eles');
INSERT INTO verses VALUES (12923, 18, 3, 15, 'ou com ouro a-eles para-eles hammaleim batheyhem כסף׃');
INSERT INTO verses VALUES (12924, 18, 3, 16, 'ou kenefel tamun não ehyeh keolim não luz luz');
INSERT INTO verses VALUES (12925, 18, 3, 17, 'nome ímpios chadlu ira-que e ali descansarão exaustos-de poder');
INSERT INTO verses VALUES (12926, 18, 3, 18, 'יַ֭חַד prisioneiros-que tranquilizai-nós não ouviram voz pastor-que');
INSERT INTO verses VALUES (12927, 18, 3, 19, 'pequeno e-grande nome ele e-escravo livre de-seus-maiores-verso-final');
INSERT INTO verses VALUES (12928, 18, 3, 20, 'por-que dará para-trabalho-duro luz e-vidas para-conta-de alma');
INSERT INTO verses VALUES (12929, 18, 3, 21, 'os que apagam para a morte e não há e cavaram-no dos escondidos;');
INSERT INTO verses VALUES (12930, 18, 3, 22, 'os que se alegram para o gil que porque serão achados- Qever');
INSERT INTO verses VALUES (12931, 18, 3, 23, 'para-o-homem que seu-caminho foi-escondida e-ele-sacrificou Eloah em-seu-lugar');
INSERT INTO verses VALUES (12932, 18, 3, 24, 'porque diante-de para-o-meupão meus-suspiros vem e-ele-foi-separado como-aos-aguas gritos-me');
INSERT INTO verses VALUES (12933, 18, 3, 25, 'que medo temi-eu e-vieram-a-mim e-que tremi-eu irá-se-entrar para-mim');
INSERT INTO verses VALUES (12934, 18, 3, 26, 'não acalmei-eu e-não [וְלֹ֖א] e-não descansei-eu E-veio ira:');
INSERT INTO chapters VALUES (440, 18, 4, 21);
INSERT INTO verses VALUES (12935, 18, 4, 1, 'E respondeu: Elifaz o-timânî E-disse');
INSERT INTO verses VALUES (12936, 18, 4, 2, 'se-experimentou palavra a-ti te-la-e ve-a-tzor be-mil-in quem pode');
INSERT INTO verses VALUES (12937, 18, 4, 3, 'eis yi-sar-ta muitos ve-yada-im ra-foth te-ha-zek');
INSERT INTO verses VALUES (12938, 18, 4, 4, 'ko-shel ye-ki-mun mi-le-kha e-os-teus-juntos curvando-se-as fortalecerás');
INSERT INTO verses VALUES (12939, 18, 4, 5, 'que agora תָּב֣וֹא a-ti e-ela-se-encheu tocarás ʿădêkā e-ele-se-apressou');
INSERT INTO verses VALUES (12940, 18, 4, 6, 'porventura-não temor-teu cintura-teu esperança-teu e-completo as tuas sendas');
INSERT INTO verses VALUES (12941, 18, 4, 7, 'lembra-de quem ele ele inocente perdido e-onde retos escondidos-foram');
INSERT INTO verses VALUES (12942, 18, 4, 8, 'como-que ראיתי֭ aradores iniquidade e-semeadores עָמָ֣ל os-colherão');
INSERT INTO verses VALUES (12943, 18, 4, 9, 'de-a-semente Elohim destruirão-os e-do-sopro do-seu-nariz cessarão');
INSERT INTO verses VALUES (12944, 18, 4, 10, 'de-a-urração leão e-voz שָׁ֑חַל e-das-molares de-jovens-leões arrancaram-no-os');
INSERT INTO verses VALUES (12945, 18, 4, 11, 'para-o-israelita perdido SEM טָ֑רֶף e-filhos-de ao-líbano separem-se-');
INSERT INTO verses VALUES (12946, 18, 4, 12, 'e-a-mim palavra seja-colocado e-tomou a-minha-ouvido sombra de-a-ele-');
INSERT INTO verses VALUES (12947, 18, 4, 13, 'em-os-galhos de-as-visionarias noite quando-cair sono-profundo sobre homens');
INSERT INTO verses VALUES (12948, 18, 4, 14, 'פַּ֣חַד clame-a-mim e-tremor e-muitos ossos-meus temeu');
INSERT INTO verses VALUES (12949, 18, 4, 15, 'e-Espírito-de sobre face-de trocará se-empinará cabelo-de carne-meus');
INSERT INTO verses VALUES (12950, 18, 4, 16, 'estará e-não conheço vista-seu imagem diante-de e-olhos-meus silencio e-voz ouvi');
INSERT INTO verses VALUES (12951, 18, 4, 17, 'o-homem de-elohim sera-justo mãe de-fazer-seu purificar-  homem:');
INSERT INTO verses VALUES (12952, 18, 4, 18, 'eis em-servos-seus não יַאֲמִין e-com-os-seus-mandados põe-se tahalah');
INSERT INTO verses VALUES (12953, 18, 4, 19, 'certamente [׀] casas-de- cimento que em-poeira fundamentos-deles os-oprimirão diante-de- destruição');
INSERT INTO verses VALUES (12954, 18, 4, 20, 'מִבֹּ֣קֶר לָעֶ֣רֶב יֻכַּ֑תּוּ מִבְּלִ֥י משִׂים לָנֶצַח יֹאבדו׃');
INSERT INTO verses VALUES (12955, 18, 4, 21, 'não-é partiu-se e-eles neles morram-ela e-não com-sabedoria');
INSERT INTO chapters VALUES (441, 18, 5, 27);
INSERT INTO verses VALUES (12956, 18, 5, 1, 'chama-a por-favor הֲיֵ֣שׁ resposta-teu e-a quem de-santos vira');
INSERT INTO verses VALUES (12957, 18, 5, 2, 'porque para-estulto matará e-quebrado e-engano morras קינאה׃');
INSERT INTO verses VALUES (12958, 18, 5, 3, 'eu-me- ראיתי֭ insensato empurrador e-eu-gritei o-n o-נָוֵהוּ de-repente');
INSERT INTO verses VALUES (12959, 18, 5, 4, 'se-separarão בָנָ֣יו de-o-salvamento e-os-aprumarão no-santuário e-não matsil');
INSERT INTO verses VALUES (12960, 18, 5, 5, 'que a-recolha-dele fome comerá e-a de-espinhos o-tomará-o e-suspirará jejum-ados seu exército:');
INSERT INTO verses VALUES (12961, 18, 5, 6, 'que não sairá מעפר iniquidade e-de-a-terra não virá-crescer trabalho');
INSERT INTO verses VALUES (12962, 18, 5, 7, 'porque homem para-trabalho nascer-ão e-filhos-de raio elevá-lo ave');
INSERT INTO verses VALUES (12963, 18, 5, 8, 'mas Eu buscarei a El e-a Elohim ʾāśîm davi-tes');
INSERT INTO verses VALUES (12964, 18, 5, 9, 'fez gadol-o-t e-não inquirição nif-la-aot até não מִסְפָּֽר׃');
INSERT INTO verses VALUES (12965, 18, 5, 10, 'ha-not-en ma-tar sobre face-de águas [עַל־פְּנֵ֥י] águas sobre face-de chu-tsot');
INSERT INTO verses VALUES (12966, 18, 5, 11, 'la-sum shefa-lim le-marom e-os-escuros exaltaram-se salvação');
INSERT INTO verses VALUES (12967, 18, 5, 12, 'de-pervertidos מחשבות os-astutos e-não fazerão mãos-deles sabedoria;');
INSERT INTO verses VALUES (12968, 18, 5, 13, '[לֹכֵ֣ד] sábios em-astúcia-deles e-conselho nifthalim nimhara');
INSERT INTO verses VALUES (12969, 18, 5, 14, 'de-dia yefagshu escuridão vechallah yeshashu batzahorayim');
INSERT INTO verses VALUES (12970, 18, 5, 15, 'וַיֹּ֣שַׁע mecherev mipihem e-de-mão-de hazaq EVEYN׃');
INSERT INTO verses VALUES (12971, 18, 5, 16, 'וַתְּהִי laddal TIKvah e-a-sua-oferta saltou-a boca-dela');
INSERT INTO verses VALUES (12972, 18, 5, 17, 'eis אַשְׁרֵי a-humanidade repreenderá-o אֱל֑וֹהַּ e-disciplina Shaddai a abominará-a');
INSERT INTO verses VALUES (12973, 18, 5, 18, 'que ele ferirá-o e-quebrantará-o esmagará-o desgostarão-a');
INSERT INTO verses VALUES (12974, 18, 5, 19, 'por-seis trav-ot ya-tzil-e-kha u-vesh-sha-a não yi-ga bakkha'' mal');
INSERT INTO verses VALUES (12975, 18, 5, 20, 'be-ra-av pa-dcha mi-ma-vet u-bmil-hama mi-dei espada');
INSERT INTO verses VALUES (12976, 18, 5, 21, 'be-sho-t לָ֭שׁוֹן esconde-te e-não teme que porque virá:');
INSERT INTO verses VALUES (12977, 18, 5, 22, 'para-roer e-para-colher risca e-de-animal a-terra a teme');
INSERT INTO verses VALUES (12978, 18, 5, 23, 'que com pedras do-campo em-tua-aliança e-animais da-o-campo a-completa- para-ti');
INSERT INTO verses VALUES (12979, 18, 5, 24, 'e-saberes porque שָלוֹם o-tenda-teu e-examinarás a-casa-teu e-não cairás-no-pecado');
INSERT INTO verses VALUES (12980, 18, 5, 25, 'e-saberes porque muito o-semente-teu e-os-teus-descendentes a-terra a-terra');
INSERT INTO verses VALUES (12981, 18, 5, 26, 'תָּב֣וֹא em-pressa אֶל־ sepultura quando-subirem gaderish na-sua-época');
INSERT INTO verses VALUES (12982, 18, 5, 27, 'eis-que- זֹ֭את examinai-a assim-e ela ouvi-a ve-a-ta-ha sabe- para-ti');
INSERT INTO chapters VALUES (442, 18, 6, 30);
INSERT INTO verses VALUES (12983, 18, 6, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (12984, 18, 6, 2, 'se pesar ser pesado como eu faço em-moedas eles-levarão- juntos');
INSERT INTO verses VALUES (12985, 18, 6, 3, 'porque agora mares יַמִּ֣ים será pesado sobre כֵּ֝֗ן minhas-palavras gritarão');
INSERT INTO verses VALUES (12986, 18, 6, 4, 'que setas Shaddai comigo que de-sua-ira bebedor RUÍ in-o Eloah prepare-me');
INSERT INTO verses VALUES (12987, 18, 6, 5, 'se-nascerá- veado sobre grama mãe se-esfalfará- boi sobre na-noite-seu');
INSERT INTO verses VALUES (12988, 18, 6, 6, 'será-comido inferior SEM sal se há gosto separado sonho');
INSERT INTO verses VALUES (12989, 18, 6, 7, 'recusa-se para-escarnecer minha-alma eles como-depressa pão-meu');
INSERT INTO verses VALUES (12990, 18, 6, 8, 'quem- dará תָּב֣וֹא súplica-minha e-minha-esperança dará אֱלֽוֹהַּ׃');
INSERT INTO verses VALUES (12991, 18, 6, 9, 'e-respondendo Elohim e-dan-ei-me mais sua-mão e-ate-me');
INSERT INTO verses VALUES (12992, 18, 6, 10, 'e-seja ainda minha-consolação e-afirmarei em-a-pressa não não porque não novamente palavras santo');
INSERT INTO verses VALUES (12993, 18, 6, 11, 'que- meu-poder porque ayacheil e-que meu-fim porque alongarei alma-de-mim');
INSERT INTO verses VALUES (12994, 18, 6, 12, 'se força pedras minha-força se carne-meu serpente');
INSERT INTO verses VALUES (12995, 18, 6, 13, 'ou não-há עֶזְרָתִ֣י bi e-sabedoria rejeitada de-mim');
INSERT INTO verses VALUES (12996, 18, 6, 14, 'para-a-maldição de-seu-amigo bondade e-temor Shaddai abandonará');
INSERT INTO verses VALUES (12997, 18, 6, 15, 'meus-irmãos e-eles-fizeram como- herança como-um-levita levitas atravessassem');
INSERT INTO verses VALUES (12998, 18, 6, 16, 'os-negros de-mim gele עָ֝לֵ֗ימוֹ se-esconderá neve');
INSERT INTO verses VALUES (12999, 18, 6, 17, 'em-tempo sangrarão nizmatu bechumo nidwachu mimqomam');
INSERT INTO verses VALUES (13000, 18, 6, 18, 'yllaphtu arhot seu caminho eles-subirão batohu veyovedu');
INSERT INTO verses VALUES (13001, 18, 6, 19, 'hibitu arhot Tema halichot sheva qivu- lahem:');
INSERT INTO verses VALUES (13002, 18, 6, 20, 'vergonharam-se porque batah entraram adeha ve-yechapharu');
INSERT INTO verses VALUES (13003, 18, 6, 21, 'porque agora heyeitem tireu chatat e-vi-r-au-u');
INSERT INTO verses VALUES (13004, 18, 6, 22, 'haki- אָ֭מַרְתִּי ha-bu para-mim ve-mi-kho-chakh-em shi-cha-du ba-a-di');
INSERT INTO verses VALUES (13005, 18, 6, 23, 've-mal-tu-ni da-mão- צר e-de-mão-de a-riz-im ti-pdu-ni');
INSERT INTO verses VALUES (13006, 18, 6, 24, 'ho-ru-ni e-eu silencio e-que errei entendam para-mim');
INSERT INTO verses VALUES (13007, 18, 6, 25, 'que- nímrertzú palavras-de yóšer e-que yočíakh hokéakh de-vós');
INSERT INTO verses VALUES (13008, 18, 6, 26, 'para-repreender מִלּוֹת pensem e-para-o-sopro palavras-de não-satisfeito-verso-final');
INSERT INTO verses VALUES (13009, 18, 6, 27, 'também sobre יָת֥וֹם vocês-cairão-acento e-vocês-cortar-acento sobre amigos-vos-verso-final');
INSERT INTO verses VALUES (13010, 18, 6, 28, 'e-agora por-que virem-se-de bi e-sobre vocês-faces-acento se eu-desapontarei-verso-final');
INSERT INTO verses VALUES (13011, 18, 6, 29, 'retornem-se-de por-favor-acento a seja עַוְלָ֑ה ainda justiça-de-mim- em-ela');
INSERT INTO verses VALUES (13012, 18, 6, 30, 'hayesh em-minha-língua עַוְלָ֑ה se minha-garganta não entenderá das-noites');
INSERT INTO chapters VALUES (443, 18, 7, 21);
INSERT INTO verses VALUES (13013, 18, 7, 1, 'não-é exército para-homem terra שָׂכִיר seus-dias:');
INSERT INTO verses VALUES (13014, 18, 7, 2, 'como-escravo aspira- sombra e-como-mercenário que-espere seu-trabalho');
INSERT INTO verses VALUES (13015, 18, 7, 3, 'assim Eu-lhe-deixei para-mim Rachéis- Vãos- e-noites- dor deles- a-mim');
INSERT INTO verses VALUES (13016, 18, 7, 4, 'se שֶׁכַּבְתִּי e-eu-disse quando levantarei-me e-mediram- tarde e-eu-satisfiz balanços até-o nósef');
INSERT INTO verses VALUES (13017, 18, 7, 5, 'vestiu-se de-meu-carne podridão na poeira de-me-pele pó e-ele-se-desgostou');
INSERT INTO verses VALUES (13018, 18, 7, 6, 'יָמַ֣י levem de-mim sandália e-eles-se-terminaram em vão tikvah');
INSERT INTO verses VALUES (13019, 18, 7, 7, 'macho porque espírito minha vida não para-ver bom para-ver bom');
INSERT INTO verses VALUES (13020, 18, 7, 8, 'não teshureni olho roei olhos-teus por-mim וְאֵינֶֽנִּי׃');
INSERT INTO verses VALUES (13021, 18, 7, 9, 'completou-a anan E-andou assim yored sheol não yaaleh');
INSERT INTO verses VALUES (13022, 18, 7, 10, 'não ele-voltará ainda לבית-ו e-não yakirenu ainda de seu lugar');
INSERT INTO verses VALUES (13023, 18, 7, 11, 'também não não echeshach de-seu adabrah em-o-angustia RUÍ eu-farei-sentir-me com-a-dor alma-de-mim');
INSERT INTO verses VALUES (13024, 18, 7, 12, 'o-mar eu-sou se serpente-grande porque colocarás em-mim משמר׃');
INSERT INTO verses VALUES (13025, 18, 7, 13, 'porque אָ֭מַרְתִּי consolar-me minha-cama e-le-va em-o-verdejar-me de-a-deitar-me');
INSERT INTO verses VALUES (13026, 18, 7, 14, 'e-ameace-me em-o-sonhos e-de-as-visionarias perseguir-me');
INSERT INTO verses VALUES (13027, 18, 7, 15, 'e-escolheu estrangulamento minha-alma -morte de-minhas-ossadas');
INSERT INTO verses VALUES (13028, 18, 7, 16, 'rejeitou-me não para-o-paraever eu-viver-eu cessar de-mim porque הֶבֶל יָמָֽי׃');
INSERT INTO verses VALUES (13029, 18, 7, 17, 'que que porque você-grande-o a-ele você-lugar a-ele לִבֶּֽךָ׃');
INSERT INTO verses VALUES (13030, 18, 7, 18, 'e-você-contou-o para-visitas para-momentos t-vi-xa-nu');
INSERT INTO verses VALUES (13031, 18, 7, 19, 'ka-ma não ti-she-a de-mim não ta-rfe-ni até bi-le-i ru-qi');
INSERT INTO verses VALUES (13032, 18, 7, 20, 'cha-ta-ti que e-fe-al la-kh para-ti o-homem o-homem sa-ma-ta-ni para-o-ferimento a-ti para-ti sobre-mim para-a-alçada');
INSERT INTO verses VALUES (13033, 18, 7, 21, 'umehe não você-levará meu pecado e me perturbe a minha iniquidade porque agora para a poeira eu me deito e escarneça-me e eu não sou');
INSERT INTO chapters VALUES (444, 18, 8, 22);
INSERT INTO verses VALUES (13034, 18, 8, 1, 'e respondeu Bildad הַשּׁׁוּחִ֗י E-disse');
INSERT INTO verses VALUES (13035, 18, 8, 2, 'até aqui e-Espírito-de estes ואורח grande imre- teu-boca:');
INSERT INTO verses VALUES (13036, 18, 8, 3, 'ha-el yeavvet juízo e-se Shaddai yeavvet- צֶֽדֶק׃');
INSERT INTO verses VALUES (13037, 18, 8, 4, 'se benekha chatu- a-ele ve-yeshalchem por-mão-de pishaam-');
INSERT INTO verses VALUES (13038, 18, 8, 5, 'se Tu terá escuridão a El e-a Shaddai terá misericórdia');
INSERT INTO verses VALUES (13039, 18, 8, 6, 'se puro e reto é porque agora ele levantou sobre-ti e pagou não haverá a-tua-justiça:');
INSERT INTO verses VALUES (13040, 18, 8, 7, 'e-foi o-teu-primeiro pequena e-o-teu-ultimo será-profundamente muito');
INSERT INTO verses VALUES (13041, 18, 8, 8, 'porque pergunta- por-favor para-a-geração primeiro e-ordenará para-examinar avos-eus');
INSERT INTO verses VALUES (13042, 18, 8, 9, 'porque ontem nós e-não que porque sombra nosso-dias em-o terra');
INSERT INTO verses VALUES (13043, 18, 8, 10, 'não-é eles eles-te-orientarão para-ti a-ti e-de-seu-corpo e-saírem palavras');
INSERT INTO verses VALUES (13044, 18, 8, 11, 'se-ele-alegrará gome-a bəlō'' bitz-ah yisgeh- ach-u בְלִי־ águas');
INSERT INTO verses VALUES (13045, 18, 8, 12, 'oden-no be-ab-bo não yiqtaef וְלִפְנֵ֖י todo chatz-ir yiibash');
INSERT INTO verses VALUES (13046, 18, 8, 13, 'sim archoth todo esquecedor- El -e-esperança חָנֵ֣ף to-a-ve-d-sefres');
INSERT INTO verses VALUES (13047, 18, 8, 14, 'que recolhe de-seu-estômago e-casa-de de-sua-segurança');
INSERT INTO verses VALUES (13048, 18, 8, 15, 'se-apoiará sobre ביתו e-não se-levantará agarrar-se-á nele e-não יתקום׃');
INSERT INTO verses VALUES (13049, 18, 8, 16, 'molhar-se-á ele diante-de sol e-sobre de-sua-jardim de-seu-penacho saia-');
INSERT INTO verses VALUES (13050, 18, 8, 17, 'sobre rola- seus-roots שָֽׁרָשָׁ֣יו se-reunam- casa pedras veja-');
INSERT INTO verses VALUES (13051, 18, 8, 18, 'se o-devore- de-seu-lugar- e-negou-se não não te-vi-');
INSERT INTO verses VALUES (13052, 18, 8, 19, 'eis- ele- מְשׂ֣וֹשׂ caminho dele e-do-pó outro cresçam');
INSERT INTO verses VALUES (13053, 18, 8, 20, 'eis-que não não se-desesperará- tãm e-não por-mão-de מְ-רֵעִים׃');
INSERT INTO verses VALUES (13054, 18, 8, 21, 'até [שְׂח֣וֹק] [פִּ֑יךָ] os-teus-lábios e-as-tuas-bocas a-clamor');
INSERT INTO verses VALUES (13055, 18, 8, 22, 'os-teus-inimigos vistem-se-de a-vergonha e-o-hel ímpios não há');
INSERT INTO chapters VALUES (445, 18, 9, 35);
INSERT INTO verses VALUES (13056, 18, 9, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (13057, 18, 9, 2, 'אָ֭מְנָם eu-sei porque assim e-que justifica-se o-homem com El');
INSERT INTO verses VALUES (13058, 18, 9, 3, 'se deseja para-litigio com-ele uma responde-nos uma de-quem- mil');
INSERT INTO verses VALUES (13059, 18, 9, 4, 'sábio coração e-forte força quem a-ele a-ele e-cumpriu');
INSERT INTO verses VALUES (13060, 18, 9, 5, 'o que copia os montes e-não sabiam que inversamente em seu fogo:');
INSERT INTO verses VALUES (13061, 18, 9, 6, 'o que amarga terra de seu lugar e seus pilares, serão despedaçados:');
INSERT INTO verses VALUES (13062, 18, 9, 7, 'o que diz para o vazio e-não e se estenderá e para além de estrelas e até o fim;');
INSERT INTO verses VALUES (13063, 18, 9, 8, 'inclinado céus sozinho e-tua-geração sobre mar mar-');
INSERT INTO verses VALUES (13064, 18, 9, 9, 'fazendo faz o-estúpido e-Kimah e-cavernas do-leste');
INSERT INTO verses VALUES (13065, 18, 9, 10, 'fez Gadolot até não-há Chaker até não-há Mispar');
INSERT INTO verses VALUES (13066, 18, 9, 11, 'eis passar Alai e-não Erehe VeYachalof e-não a-ele a-ele');
INSERT INTO verses VALUES (13067, 18, 9, 12, 'eis ele-arrancará quem irá-sentá-lo quem a-ele a-ele que farás');
INSERT INTO verses VALUES (13068, 18, 9, 13, 'Elohim não יָשִׁיב seu-nariz eles-cairão de-ajudantes vasto:');
INSERT INTO verses VALUES (13069, 18, 9, 14, 'certamente porque eu eu-responder-e-o eu-escolherei palavras-meu');
INSERT INTO verses VALUES (13070, 18, 9, 15, 'que se não não eu-responder-e para-o-meu-julgamento e implorareis');
INSERT INTO verses VALUES (13071, 18, 9, 16, 'se chamei e-respondeu-me não cre-u porque ouvirá de-a-minha-voz-');
INSERT INTO verses VALUES (13072, 18, 9, 17, 'que em-o-tempo-do-furacão assoprar-me-á e-multiplicará meus-golpes gratuitamente');
INSERT INTO verses VALUES (13073, 18, 9, 18, 'não dá-me retornar que porque satiar-me de-amargura');
INSERT INTO verses VALUES (13074, 18, 9, 19, 'se com-poder eis eis quem para-justiça quem promete-me');
INSERT INTO verses VALUES (13075, 18, 9, 20, 'se serei-justo boca-de me-condenará soy-perfeito- -eu e-que-eu-sujei-me-verso-final');
INSERT INTO verses VALUES (13076, 18, 9, 21, 'perfeito eu não conheci a minha alma enganou-me minha vida:');
INSERT INTO verses VALUES (13077, 18, 9, 22, 'uma ela sobre assim disse-eu terminou-se ele ele destruidor-verso-final');
INSERT INTO verses VALUES (13078, 18, 9, 23, 'se chance ימית פִּתְאֹ֑ם para-derrotar livres rir-se-de-verso-final');
INSERT INTO verses VALUES (13079, 18, 9, 24, 'terra n-tanah em-a-mão- רָשָׂע face-de- shof-teha yekhasseh se não אֵפ֣וֹא quem ela');
INSERT INTO verses VALUES (13080, 18, 9, 25, 'וְ-יָ-מַי quebrantem-se de-mim corram fugirem não רָא֥וּ boa');
INSERT INTO verses VALUES (13081, 18, 9, 26, 'passaram com navios destruição cavalo tropel sobre devorador:');
INSERT INTO verses VALUES (13082, 18, 9, 27, 'se am-ri eu-esquecerei sihiy eu-abandonarei face-de e-lamentarei');
INSERT INTO verses VALUES (13083, 18, 9, 28, 'temerei todo minhas-tristezas יָדַעְתִּי porque não purifica-me');
INSERT INTO verses VALUES (13084, 18, 9, 29, 'eu eu-ameaçarei por-que זֶּ֝֗ה הֶבֶל lamento');
INSERT INTO verses VALUES (13085, 18, 9, 30, 'se eu-me-lavarei neve e-eu-santificarei בְּבֹ֣ר');
INSERT INTO verses VALUES (13086, 18, 9, 31, 'אָז em-o-sabádo te-batize-me e-ame-o-de-si selvas-das-meu');
INSERT INTO verses VALUES (13087, 18, 9, 32, 'porque não homem como-me responder-ele-o viremos juntos no juízo');
INSERT INTO verses VALUES (13088, 18, 9, 33, 'não há- בֵּינֵ֣ינוּ moquichah sua-mão mão-dele sobre שְׁנֵֽינוּ׃');
INSERT INTO verses VALUES (13089, 18, 9, 34, 'corrija מֵעָלַ֣י bastao-seu e-tremor-seu a perseguir-me');
INSERT INTO verses VALUES (13090, 18, 9, 35, 'a-dab-rah e-não i-ra-en-u que não eu comigo comigo-');
INSERT INTO chapters VALUES (446, 18, 10, 22);
INSERT INTO verses VALUES (13091, 18, 10, 1, 'naq-tah minha-alma be-hay-yai e-ez-bah sobre-mim sihiy a-dab-rah com-a-dor alma-de-mim');
INSERT INTO verses VALUES (13092, 18, 10, 2, 'disse a אֱ֭לוֹהַּ a sobre dize-me sobre que- conteste-me:');
INSERT INTO verses VALUES (13093, 18, 10, 3, 'bem é a-ti porque chame porque desanime toque as tuas mãos e-sobre conselhos ímpios manifestaste-te:');
INSERT INTO verses VALUES (13094, 18, 10, 4, 'haeinei em carne para-ti se kiraot enosh você-ver-irá');
INSERT INTO verses VALUES (13095, 18, 10, 5, 'hakimey enosh os-teus-dias se as-tuas-annos nos-dias-de גבר׃');
INSERT INTO verses VALUES (13096, 18, 10, 6, 'porque tu-buscarás para-o-pecado-meu tu-procurarás');
INSERT INTO verses VALUES (13097, 18, 10, 7, 'sobre a-sabedoria-teu porque não eu-julgarei e-não-há de-a-mão-tua matsil');
INSERT INTO verses VALUES (13098, 18, 10, 8, 'as-mãos-teus pedra-me e-fizeram-me junto em-torno e-vos-devorastes-me');
INSERT INTO verses VALUES (13099, 18, 10, 9, 'lembra-de por-favor porque como-argila fizeste-me e-a poeira vós-tornareis-me');
INSERT INTO verses VALUES (13100, 18, 10, 10, 'porventura-não como-leite vós-moldareis-me e-como-queijo vós-congelareis-me');
INSERT INTO verses VALUES (13101, 18, 10, 11, 'pele e-carne viste-me e-com-ossos e-tendões te-cobrirei');
INSERT INTO verses VALUES (13102, 18, 10, 12, 'vida e-graciosidade fizeste comigo e-tu-comandaste guarda ruchi:');
INSERT INTO verses VALUES (13103, 18, 10, 13, 'e-estes ocultaste no-teu-corazão יָדַעְתִּי porque esta contigo');
INSERT INTO verses VALUES (13104, 18, 10, 14, 'se sou-pecador e-guarda-me não não purifica-me');
INSERT INTO verses VALUES (13105, 18, 10, 15, 'se peco-ei não-é-assim para-mim e-serei-justo não levantarei cabeça-de mim sete obscenidade e-veja minha-necessidade');
INSERT INTO verses VALUES (13106, 18, 10, 16, 'e-se-eleva como-estrela tceze-de-ni ve-tashov titpalla- בי׃');
INSERT INTO verses VALUES (13107, 18, 10, 17, 'techade-sh edei-kha negdi ve-tereb ka-ashe-kha עםADI comigo e-exército comigo');
INSERT INTO verses VALUES (13108, 18, 10, 18, 've-lamma me-rechem sai-me eu-agonizo וְעַ֣יִן não tu-me-vês');
INSERT INTO verses VALUES (13109, 18, 10, 19, 'como-que não hayiti ehyeh de-o-interno para-o-túmulo e-Aval');
INSERT INTO verses VALUES (13110, 18, 10, 20, 'não-é pouco yámy de-mí e-abligá pequena:');
INSERT INTO verses VALUES (13111, 18, 10, 21, 'betereim-acento-águia eu-vou e-não eu-retornarei a terra escuridão e-imagem');
INSERT INTO verses VALUES (13112, 18, 10, 22, 'terra desmaiei como opel tsalmavet e-não sedarim vatofa como אֹֽפֶל׃');
INSERT INTO chapters VALUES (447, 18, 11, 20);
INSERT INTO verses VALUES (13113, 18, 11, 1, 'וַיַּעַן צֹפַר han-naamatyi E-disse');
INSERT INTO verses VALUES (13114, 18, 11, 2, 'harov dvarim não yeaneh e-se homem sfatayim yitzdak');
INSERT INTO verses VALUES (13115, 18, 11, 3, 'em-tu mortos calará-eles e-ridiculizou-você e-não-há silenciando');
INSERT INTO verses VALUES (13116, 18, 11, 4, 'E-disse justos leva-me e-puro era em-teus-olhos');
INSERT INTO verses VALUES (13117, 18, 11, 5, 'vé-ulam quem dará Eloah palavra e-abrirá suas línguas contigo');
INSERT INTO verses VALUES (13118, 18, 11, 6, 'e-contará para-ti ta''alumot chokmah porque kiplayim letushiya veda'' a-ti yasseh para-ti אֱ֝לוֹהַ me''avonekha');
INSERT INTO verses VALUES (13119, 18, 11, 7, 'haheqer Elohim encontrarás mãe até fim-de Shaddai encontrar-você');
INSERT INTO verses VALUES (13120, 18, 11, 8, 'gavhei céus que tif''al profunda de-a-pergunta que- saberás');
INSERT INTO verses VALUES (13121, 18, 11, 9, 'arquah da-terra da-sua-medida e-larga de-mim mar-');
INSERT INTO verses VALUES (13122, 18, 11, 10, 'se trocará e-confinará e-aglomerará e-quem o-devolverá');
INSERT INTO verses VALUES (13123, 18, 11, 11, 'porque saber conheceu por-que שָׁוְא e-viu- -iniquidade e-não yitbownan:');
INSERT INTO verses VALUES (13124, 18, 11, 12, 'e-homem estúpido ilabeb ve-ayir per-e homem irá-levá-dò');
INSERT INTO verses VALUES (13125, 18, 11, 13, 'se atta hakinhota teu-coração a-ele a-ele kapheka');
INSERT INTO verses VALUES (13126, 18, 11, 14, 'se AVEN na tua mão afaste-o e-a habitarás em teu tenda avareza:');
INSERT INTO verses VALUES (13127, 18, 11, 15, 'porque então levantaste teu rosto do desprezo e-você-seja mutsaq e-não tira');
INSERT INTO verses VALUES (13128, 18, 11, 16, 'porque אתה עָמָ֣ל tishchakha kemayim abru lembrar-vos-');
INSERT INTO verses VALUES (13129, 18, 11, 17, 'e-de-missraim יָק֣וּם morreste voar-ás amanhecer será');
INSERT INTO verses VALUES (13130, 18, 11, 18, 'e-confiaste porque há TIKvah e-cavaste em-segurança dormirá');
INSERT INTO verses VALUES (13131, 18, 11, 19, 'e-te-estendeste e-não-há ardente e-iniciaram teu rosto muitos');
INSERT INTO verses VALUES (13132, 18, 11, 20, 'e vossos olhos maus perceberão e vergonha se perderem deles e sua esperança do fôlego alma');
INSERT INTO chapters VALUES (448, 18, 12, 25);
INSERT INTO verses VALUES (13133, 18, 12, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (13134, 18, 12, 2, 'אָ֭מְנָם que vós- povo morrerás morreteis חוכמה׃');
INSERT INTO verses VALUES (13135, 18, 12, 3, 'também para-mim coração como-vos não eu eu [וְאֶת] e-com quem não como- estes');
INSERT INTO verses VALUES (13136, 18, 12, 4, 'riso para-amigo-seu eu-ser-ei chamou para-elohim e-respondeu-lhe riso justo perfeito');
INSERT INTO verses VALUES (13137, 18, 12, 5, 'lápide búz le-aštut shaanan נָ֝כ֗וֹן lemoadêi רָגֶל׃');
INSERT INTO verses VALUES (13138, 18, 12, 6, 'yishlaiyu oalim [׀] ubatutóth lemargizei El para-o-que trouxe Eloah em-mão-sua');
INSERT INTO verses VALUES (13139, 18, 12, 7, 'vé-ulam pergunta- por-favor de-animal e-ave e-pássaro os-céus e-contará- para-ti');
INSERT INTO verses VALUES (13140, 18, 12, 8, 'ou arbusto-de para-a-terra e-tua-instrução e-contarão a-ti de-peixe o-mar');
INSERT INTO verses VALUES (13141, 18, 12, 9, 'quem não conheceu que estes porque mão-de yhwh fez-a esta');
INSERT INTO verses VALUES (13142, 18, 12, 10, 'que em-sua-mão alma todo e-Espírito-de e-espírito todo carne- homem');
INSERT INTO verses VALUES (13143, 18, 12, 11, 'não-é ouvido palavras examinarás e-o-sabor alimento saboreará- a-ele');
INSERT INTO verses VALUES (13144, 18, 12, 12, 'em-o-saboroso sabedoria e-comprimento dias sabedoria:');
INSERT INTO verses VALUES (13145, 18, 12, 13, 'com-ele sabedoria e a força a-ele etza ut-vunah');
INSERT INTO verses VALUES (13146, 18, 12, 14, 'eis destruirá e-não construirá [יִסְגֹּ֥ר] sobre homem e-não abrirá');
INSERT INTO verses VALUES (13147, 18, 12, 15, 'eis retirá em-a-água e-eles-se-tornarão-dry e-ele-os-enviará e-eles-o-voltarão terra');
INSERT INTO verses VALUES (13148, 18, 12, 16, 'com-ele força e-a-prudência a-ele que-está-perdido e-o-conduzindo');
INSERT INTO verses VALUES (13149, 18, 12, 17, 'levando conselheiros despojado e-julgadores Yehôlêl');
INSERT INTO verses VALUES (13150, 18, 12, 18, 'מוּסַ֣ר reis abre-o e-fecha-o cinto em-a-sua-cintura');
INSERT INTO verses VALUES (13151, 18, 12, 19, 'conduzindo sacerdotes trabalhadores e-estendendo ele-extendeu:');
INSERT INTO verses VALUES (13152, 18, 12, 20, 'levou língua para-os-fieis: e-gosto זְקֵנִ֣ים tomará:');
INSERT INTO verses VALUES (13153, 18, 12, 21, 'shofeikh buz sobre n’dibim um’zikhah afikim rifa:');
INSERT INTO verses VALUES (13154, 18, 12, 22, 'megale amqot de-mim escuridão à-luz laor צַלְמָהּ׃');
INSERT INTO verses VALUES (13155, 18, 12, 23, 'masgia lagoyim veyaabdem שֶׁטַח lagoyim vayyanchem:');
INSERT INTO verses VALUES (13156, 18, 12, 24, 'mesir coração cabeças-de com a-terra e-os-perderam em-o-vazio não caminho');
INSERT INTO verses VALUES (13157, 18, 12, 25, 'e-toquem-se escuridão e-não luz e-os-perderam como-bêbados');
INSERT INTO chapters VALUES (449, 18, 13, 28);
INSERT INTO verses VALUES (13158, 18, 13, 1, 'eis- todo viu-ela עֵינִ֑י ouviu-ela a-minha-ouvido e-entendeu a-ela');
INSERT INTO verses VALUES (13159, 18, 13, 2, 'como-voces-sabem eu-sei também eu eu caído eu de-vós');
INSERT INTO verses VALUES (13160, 18, 13, 3, 'mas Eu a Shaddai eu falar e-repreenda a El eu-amo');
INSERT INTO verses VALUES (13161, 18, 13, 4, 'e-no-entanto vós fabricantes-de falsidade medicadores-do elohim vós-todos:');
INSERT INTO verses VALUES (13162, 18, 13, 5, 'quem dará o-silencio voces-sereis-silenciosos a-vós para-vós para-a-sabedoria');
INSERT INTO verses VALUES (13163, 18, 13, 6, 'ouvi agora eu repreender-tei e multidões minhas lábios ouvirdes:');
INSERT INTO verses VALUES (13164, 18, 13, 7, 'o-elohim vocês-falarão עַוְלָ֑ה e-a-ele vocês-falarão רְמִיָּֽה׃');
INSERT INTO verses VALUES (13165, 18, 13, 8, 'as-suas-caras vocês-levantarão se a-o-elohim vocês-contenderão');
INSERT INTO verses VALUES (13166, 18, 13, 9, 'é-bom porque ele-examinará a-vós se como-um-círculo nele tehateilu nele-verso');
INSERT INTO verses VALUES (13167, 18, 13, 10, 'הוֹכֵ֣חַ yochiach a-vós se baseter face tisauun');
INSERT INTO verses VALUES (13168, 18, 13, 11, 'porventura-não [שְׂ֭אֵתוֹ] tevaet a-vós upachduo cairá sobre-vós');
INSERT INTO verses VALUES (13169, 18, 13, 12, 'zichronicheim mishlei- efer para-o-lado-de chumbo atrás-vos');
INSERT INTO verses VALUES (13170, 18, 13, 13, 'a-araiem-se de-mi e-e-falarei-a eu e-passeira sobre-mim מָה׃');
INSERT INTO verses VALUES (13171, 18, 13, 14, 'sobre o-que levantarei na-carne-meu com-a-dente-meu e-minha-alma ʾāśîm com-a-mão-meu');
INSERT INTO verses VALUES (13172, 18, 13, 15, 'eis que-me-lute ayacheil somente meus-caminhos a de-seus-faces repreender-te');
INSERT INTO verses VALUES (13173, 18, 13, 16, 'também ele para-mim li-yeshuah porque não perante-ele chánef virá:');
INSERT INTO verses VALUES (13174, 18, 13, 17, 'ouvi ouvindo milathi e-minha-ternura em-os-ouvidos-vosso');
INSERT INTO verses VALUES (13175, 18, 13, 18, 'eis-que- por-favor עֲרַךְתִּי juízo יָדַעְתִּי porque eu serei-justo');
INSERT INTO verses VALUES (13176, 18, 13, 19, 'quem ele- comigo עםADI porque agora calarei-me e-eu-queixo-me');
INSERT INTO verses VALUES (13177, 18, 13, 20, 'somente duas-vezes comigo farás עםADI não de-te não esconder-me-ei');
INSERT INTO verses VALUES (13178, 18, 13, 21, 'mão-te מֵעָלַ֣י afasta e-tremor-te a perseguir-me');
INSERT INTO verses VALUES (13179, 18, 13, 22, 'e-clama e-eu responder-ei ou falo e-responde-me');
INSERT INTO verses VALUES (13180, 18, 13, 23, 'quão para-mim iniquidades e-pecados transgressão-meu e-peca-meu diga-me-');
INSERT INTO verses VALUES (13181, 18, 13, 24, 'por-que- tuas-faces escondas-te e-pen-sa-em-mim para-ti para-ti');
INSERT INTO verses VALUES (13182, 18, 13, 25, 'o-alto nubloso terrores e-a kash- secou-se perseguir-');
INSERT INTO verses VALUES (13183, 18, 13, 26, 'porque escreverás sobre-mim de-amargura e-esquecer-me pecados os-meus-jovens');
INSERT INTO verses VALUES (13184, 18, 13, 27, 'e-ponha em-o-sedimento רַגְלַ֗י e-vigie todo as-meus-caminhos sobre raízes-de pés-minhas você-seguirá');
INSERT INTO verses VALUES (13185, 18, 13, 28, 'vehu como-aranha ele-viverá como-manto a-com-ele-o destruição');
INSERT INTO chapters VALUES (450, 18, 14, 22);
INSERT INTO verses VALUES (13186, 18, 14, 1, 'homem יְלָד mulher e-cortou yamim e-satisfez-se ira:');
INSERT INTO verses VALUES (13187, 18, 14, 2, 'como-floresce sair e-foi-circuncidado וַיִּבְרַ֥ח [כַּ֝צֵּ֗ל] e-não ele-pararia');
INSERT INTO verses VALUES (13188, 18, 14, 3, 'também sobre isto abriste nos-teus-olhos e-a-mim trarás em-mis-paat contigo');
INSERT INTO verses VALUES (13189, 18, 14, 4, 'quem dará טָ֭הוֹר não um um');
INSERT INTO verses VALUES (13190, 18, 14, 5, 'mãe chru-tzi-im yam-av-yo mis-paar- chod-sha-yo contigo as-ta e-não ya-a-vor');
INSERT INTO verses VALUES (13191, 18, 14, 6, 'sua dele e morrerá até terá prazer como aluguel seu dia');
INSERT INTO verses VALUES (13192, 18, 14, 7, 'que há para a árvore esperança se será cortada e ainda substituirá não não terá fim');
INSERT INTO verses VALUES (13193, 18, 14, 8, 'se envelhecerá na-terra raiz dele e na poeira morrerá seu fruto');
INSERT INTO verses VALUES (13194, 18, 14, 9, 'de-fragrância águas fazer-florescer e-fará קָצִ֣יר como plantou');
INSERT INTO verses VALUES (13195, 18, 14, 10, 'וְגֶ֣בֶר יָ֭מוּת וַֽיֶּחֱלָ֑שׁ וַיִּגְוַ֖ע homem וְאַיּֽוֹ׃');
INSERT INTO verses VALUES (13196, 18, 14, 11, 'foram-se águas de-mim mar e-riv se despedaçará e seca-se');
INSERT INTO verses VALUES (13197, 18, 14, 12, 'e-homem deitou e-não levante-se até não céus não יָקִ֑יצוּ e-não acordem de-sua-sono');
INSERT INTO verses VALUES (13198, 18, 14, 13, 'quem dê em-pesquisa esconda-me você-esconderá-me até volta teu-ira a-mim lei e-te-lembre-de-mim');
INSERT INTO verses VALUES (13199, 18, 14, 14, 'se morrerá homem haverás-de-viver todo dias-de meu-exército ayacheil até -vindo minha-veste');
INSERT INTO verses VALUES (13200, 18, 14, 15, 'chamarás e-eu responder-te-ei para-o-trabalho das-tuas-mãos desejarás');
INSERT INTO verses VALUES (13201, 18, 14, 16, 'porque agora minhas andanças tu ouvis não tu guardas sobre minha transgressão');
INSERT INTO verses VALUES (13202, 18, 14, 17, 'selado em anel pešuʿî וַתִּטְפֹּל sobre עָוֹן׃');
INSERT INTO verses VALUES (13203, 18, 14, 18, 'וְאֻלָּם monte-de נֹפֵל יִבֹּל וְצוּר יֶעְתַּ֥ק מִמְּקֹמֽוֹ׃');
INSERT INTO verses VALUES (13204, 18, 14, 19, 'אֲבָנִ֤ים ׀ [׀] águas águas [תִּשְׁטֹֽף־סְפִיחֶ֥יהָ] [עֲפַר־אָ֑רֶץ] terra -e-esperança o-homem');
INSERT INTO verses VALUES (13205, 18, 14, 20, '[תִּתְקְפֵ֣הוּ] até-sempre [וַֽיַּהֲלֹ֑ךְ] [מְשַׁנֶּ֥ה] [פָ֝נָ֗יו] [וַֽתְּשַׁלְּחֵֽהוּ]');
INSERT INTO verses VALUES (13206, 18, 14, 21, 'serão exaltados em seus filhos e-não conheceu e clamarem e-não entenderá a-eles');
INSERT INTO verses VALUES (13207, 18, 14, 22, 'somente em seu corpo sobre-ele sofrerão e sua alma sobre-ele se angustiará');
INSERT INTO chapters VALUES (451, 18, 15, 35);
INSERT INTO verses VALUES (13208, 18, 15, 1, 'respondeu Elifaz o Hietumense E-disse');
INSERT INTO verses VALUES (13209, 18, 15, 2, 'הֶֽחָכָ֗ם יַעֲנֶ֥ה דַֽעַת־ espírito וִֽימַלֵּ֖א קָדִ֣ים בִּטְנֽוֹ׃');
INSERT INTO verses VALUES (13210, 18, 15, 3, 'הוֹכֵ֣חַ בְּ֭דָבָר não אִסְכּוֹן וּמִלּוֹת não [בָּֽם] em-eles');
INSERT INTO verses VALUES (13211, 18, 15, 4, 'também אתה [יִרְאָ֑ה] [וְתִגְרַ֥ע] [שִׂ֝יחָ֗ה] [לִפְנֵי־אֵֽל] diante-de- El');
INSERT INTO verses VALUES (13212, 18, 15, 5, 'que [יְאַלֵּ֣ף] [עֲוֺנְךָ֣] פִּיךָ [וְ֝תִבְחַ֗ר] língua-de [עֲרוּמִֽים]');
INSERT INTO verses VALUES (13213, 18, 15, 6, '[יַרְשִֽׁיעֲךָ֣] [פִ֣יךָ] e-não eu e-as-vossas-bocas em-te:');
INSERT INTO verses VALUES (13214, 18, 15, 7, 'o-primeiro homem nascerás-no-o וְלִפְנֵ֖י [גְבָע֣וֹת] [חוֹלָֽלְתָּ]');
INSERT INTO verses VALUES (13215, 18, 15, 8, 'o segredo elohim ouvires e separares a-ti sabedoria');
INSERT INTO verses VALUES (13216, 18, 15, 9, 'que eu sou conhecido e-não conhecidos e entenderás ele o-dia ela');
INSERT INTO verses VALUES (13217, 18, 15, 10, 'também retornou também [כַּבִּ֖יר] BANU [יָמִֽים] dias');
INSERT INTO verses VALUES (13218, 18, 15, 11, 'o-ma''at mimakha [תַּנְחֻמ֣וֹת] El [וְ֝דָבָ֗ר] [לָאַ֥ט] contigo');
INSERT INTO verses VALUES (13219, 18, 15, 12, 'que [לִבֶּ֑ךָ] teu-coração e-que de-tus-teus-olhos');
INSERT INTO verses VALUES (13220, 18, 15, 13, 'porque t-remeterá a El [מִפִּ֣יךָ] [מִלִּֽין] palavras');
INSERT INTO verses VALUES (13221, 18, 15, 14, 'que homem porque [יְל֣וּד] e-quando יְלָד mulher');
INSERT INTO verses VALUES (13222, 18, 15, 15, 'eis não יַאֲמִין não não זַכּוּ בְעֵינָיו׃');
INSERT INTO verses VALUES (13223, 18, 15, 16, 'certamente porque נִתְעַב וְנֶאֱלָח homem-de שׁוֹתֶה como-água avareza:');
INSERT INTO verses VALUES (13224, 18, 15, 17, 'meu-irmão；： ouve；： a-mim e-isto；： eu-vi；： e-revelarei；：');
INSERT INTO verses VALUES (13225, 18, 15, 18, 'que חֲכָמִ֥ים e-lessem；： e-não como-muitos；： dos seus pais');
INSERT INTO verses VALUES (13226, 18, 15, 19, 'a-eles para-os；： נִתְּנָה a-terra e-não עָבַר זָר em-meio-de-eles');
INSERT INTO verses VALUES (13227, 18, 15, 20, 'todo dias-de ele ele מִתְחוֹלֵל וּמִסְפַּר dois נִצְפְּנ֥וּ לֶעָרִֽיץ׃');
INSERT INTO verses VALUES (13228, 18, 15, 21, 'voz-de פְּחָדִים בְּאָזְנָ֑יו בַּ֝שָּׁל֗וֹם שֹׁדֵד יְבֹאֶנּוּ׃');
INSERT INTO verses VALUES (13229, 18, 15, 22, 'não יַאֲמִין שׁוּב de-mim escuridão ele אֶל־ com-espada');
INSERT INTO verses VALUES (13230, 18, 15, 23, 'נֹדֵד ele לַלַּחֶם אַיָּה saber porque certo em-mão-seu יוֹם־ escuridão');
INSERT INTO verses VALUES (13231, 18, 15, 24, 'יְבַעֲתֻהוּ angústia-de e-punha atingi-lo-irá como-rei- vai para-a-cisão-;');
INSERT INTO verses VALUES (13232, 18, 15, 25, 'porque desviou sua-mão El sua-mão e-a Shaddai se-exaltará-;');
INSERT INTO verses VALUES (13233, 18, 15, 26, 'correrá a-ele em-cinta no-ventre גַּבֵּ֥י מָֽגִנָּֽיו׃');
INSERT INTO verses VALUES (13234, 18, 15, 27, 'porque כִסָּ֣ה פָנָ֣יו בְּחֶלְבּ֑וֹ E-fez פִּימָ֣ה em-o כָֽסֶל׃');
INSERT INTO verses VALUES (13235, 18, 15, 28, 'וַיִּשְׁכּ֤וֹן ׀ עָ֘רִ֤ים נִכְחָד֗וֹת בָּ֭תִּים não יֵ֣שְׁבוּ a-eles que הִתְעַתְּד֣וּ לְגַלִּֽים׃');
INSERT INTO verses VALUES (13236, 18, 15, 29, 'não יֶ֭עְשַׁר e-não יָק֣וּם חֵיל֑וֹ e-não יִטֶּ֖ה para-a-terra מִנְלָֽם׃');
INSERT INTO verses VALUES (13237, 18, 15, 30, 'não יָס֨וּר ׀ de-mim escuridão יונקתו יבשׁ שלחהבת VASUR no-ruach פי׃');
INSERT INTO verses VALUES (13238, 18, 15, 31, 'a יאמן נתח porque שוה será תמורתו׃');
INSERT INTO verses VALUES (13239, 18, 15, 32, 'בלא- יוֹמוֹ תִּמָּלֵ֑א não não רַעֲנָֽנָה׃');
INSERT INTO verses VALUES (13240, 18, 15, 33, 'יַחְמֹ֣ס כַּגֶּ֣פֶן בִּסְר֑וֹ וְיַשְׁלֵ֥ךְ כַּ֝זַּ֗יִת נִצָּתֽוֹ׃');
INSERT INTO verses VALUES (13241, 18, 15, 34, 'porque congregação-de חָנֵ֣ף גַּלְמ֑וּד וְ֝אֵ֗שׁ ela-comeu אָֽהֳלֵי־ שֹׁ֥֥חַד׃');
INSERT INTO verses VALUES (13242, 18, 15, 35, 'הָרֹ֣ה עָ֭מָל iniquidade וּ֝בִטְנָ֗ם תָּכִ֥ין fraude');
INSERT INTO chapters VALUES (452, 18, 16, 22);
INSERT INTO verses VALUES (13243, 18, 16, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (13244, 18, 16, 2, 'שָׁמַ֣עְתִּי כְאֵ֣לֶּה muitas מְנַחֲמֵ֖י עָמָ֣ל כֻּלְּכֶֽם׃');
INSERT INTO verses VALUES (13245, 18, 16, 3, 'הֲקֵ֥ץ לְדִבְרֵי־ espírito ou que יַּ֝מְרִֽיצְךָ֗ porque תַעֲנֶֽה׃');
INSERT INTO verses VALUES (13246, 18, 16, 4, 'também אָנֹכִי֮ eu אֲדַ֫בֵּ֥רָה ל֤ו־ há almas-vossas debaixo minha-alma amor-me sobre-vós por-palavras e-entranhe-me sobre-vós por-ele minha-cabeça:');
INSERT INTO verses VALUES (13247, 18, 16, 5, 'אֲאַמִּצְכֶ֥ם בְּmo֊ פִ֑י וְn֖id שְׂfַ֣ay יַchֹֻֽock׃');
INSERT INTO verses VALUES (13248, 18, 16, 6, 'se אֲ֭dabָּrָה não יֵchֵֻ֣ock cְּeavִ֑i וְ֝achֻּdָּlָ֗ah que- מִנּוֹ irá');
INSERT INTO verses VALUES (13249, 18, 16, 7, 'somente עַתָּה הֶלְאָנִי הֲשִׁימֹתָ todo עֲדָתִי׃');
INSERT INTO verses VALUES (13250, 18, 16, 8, 'וַתִּקְמְטֵנִי לְעֵד ser E-levantou em-mi כַּחֲשׁוֹ בְּפָנַי יַעֲנֶה׃');
INSERT INTO verses VALUES (13251, 18, 16, 9, 'apão tarp e esquartejou-me espetou sobre-mim com sua boca meu inimigo arrotará seus olhos para-mim');
INSERT INTO verses VALUES (13252, 18, 16, 10, 'exporão עָלַ֨י ׀ com seus dentes em-herpa hikchu lachayai yachad alai yitmalawn');
INSERT INTO verses VALUES (13253, 18, 16, 11, 'yasgirenai El a avil e-sobre mãos-de ímpios yirteni');
INSERT INTO verses VALUES (13254, 18, 16, 12, 'shalev הָיִ֨יתִי ׀ וַֽיְפַרְפְּרֵ֗נִי וְאָחַ֣ז בְּ֭עָרְפִּי וַֽיְפַצְפְּצֵ֑נִי וַֽיְקִימֵ֥נִי ל֝֗וֹ a-ele');
INSERT INTO verses VALUES (13255, 18, 16, 13, 'יָ֘סֹ֤בּוּ עָלַ֨י ׀ רַבָּ֗יו יְפַלַּ֣ח כִּ֭לְיוֹתַי e-não יַחְמ֑וֹל יִשְׁפֹּ֥ךְ לָ֝אָ֗רֶץ מְרֵרָֽתִי׃');
INSERT INTO verses VALUES (13256, 18, 16, 14, 'יִפְרְצֵ֣נִי פֶ֭רֶץ sobre face-de פָ֑רֶץ יָרֻ֖ץ em-mim כְּגִבּֽוֹר׃');
INSERT INTO verses VALUES (13257, 18, 16, 15, 'שַׂק תְּפַרְתִּי sobre גִּלְדּוֹ וְעָלַלְתִּי בַּעֲפָר קַרְנִי׃');
INSERT INTO verses VALUES (13258, 18, 16, 16, 'face-de de-mim בַּחֲכִי e-sobre עַפְעַפָּי צַלְמָהּ׃');
INSERT INTO verses VALUES (13259, 18, 16, 17, 'sobre não violência בַּכַּפֵּי e-oração-mi justo:');
INSERT INTO verses VALUES (13260, 18, 16, 18, 'terra a cobre-te sangue-te lugar seja lugar-meu para-chamada-me:');
INSERT INTO verses VALUES (13261, 18, 16, 19, 'também agora eis-que- nos-céus testemunha-me e-testemunho-mi בַּמְּרוֹמִֽים׃');
INSERT INTO verses VALUES (13262, 18, 16, 20, 'מליץַי רעָי a אֱ֝לוֹהַ דָּלְפָ֥ה עֵינִֽי׃');
INSERT INTO verses VALUES (13263, 18, 16, 21, 'וְיוֹכַ֣ח לְגֶ֣בֶר com אֱל֑וֹהַּ וּֽבֶן־ homem לְרֵעֵֽהוּ׃');
INSERT INTO verses VALUES (13264, 18, 16, 22, 'porque שְׁנ֣וֹת מִסְפָּ֣ר יֶאֱתָ֑יוּ וְאֹ֖רַח não אָשׁ֣וּב אֶהֱלֹֽךְ׃');
INSERT INTO chapters VALUES (453, 18, 17, 16);
INSERT INTO verses VALUES (13265, 18, 17, 1, 'רוּחִ֣י חֻ֭בָּלָה יָמַ֥י נִזְעָ֗כוּ קְבָרִ֥ים para-mim');
INSERT INTO verses VALUES (13266, 18, 17, 2, 'se não comigo עםADI e-em-os talan עֵינִֽי׃');
INSERT INTO verses VALUES (13267, 18, 17, 3, 'põe-a na arbeni quem ele hu para-mi irá-entrar');
INSERT INTO verses VALUES (13268, 18, 17, 4, 'porque em-seu-coração ocultaste da-cabeça não כֵּ֝֗ן não תְרֹמֵֽם׃');
INSERT INTO verses VALUES (13269, 18, 17, 5, 'לְ֭חֵלֶק dirá רֵעִ֑ים וְעֵינֵ֖י בָנָ֣יו תִּכְלֶֽנָה׃');
INSERT INTO verses VALUES (13270, 18, 17, 6, 'וְֽ֭הִצִּגַנִי לִמְשֹׁ֣ל עַמִּ֑ים וְתֹ֖פֶת לְפָנִ֣ים אֶֽהְיֶֽה׃');
INSERT INTO verses VALUES (13271, 18, 17, 7, 'וַתֵּ֣כַהּ מִכַּ֣עַשׂ עֵינִ֑י וִֽיצֻרַ֖י כַּצֵּ֣ל כלם׃');
INSERT INTO verses VALUES (13272, 18, 17, 8, 'יָשֹׁ֣מּוּ יְשָׁרִ֣ים sobre esta e-nquí sobre chánef yi-te-orar:');
INSERT INTO verses VALUES (13273, 18, 17, 9, 'vé-yo-achez justo caminho dele ú-tohar- yadáim yo-sif o-omets:');
INSERT INTO verses VALUES (13274, 18, 17, 10, 'vé-ulam כֻּלּם tás-shubu וּבֹ֣אוּ נָ֑א e-não אֶמְצָ֖א em-vós חָכָֽם׃');
INSERT INTO verses VALUES (13275, 18, 17, 11, 'יָמַ֣י עָ֭בְרוּ זִמֹּתַ֣י נִתְּק֑וּ מ֖וֹרָשֵׁ֣י לְבָבִֽי׃');
INSERT INTO verses VALUES (13276, 18, 17, 12, 'noite para-o-dia ישׂוּ luz próximo מִפְּנֵי־ escuridão');
INSERT INTO verses VALUES (13277, 18, 17, 13, 'se אֲקוּוֹ sho''al בֵּיתִי בָּחֹשֶׁךְ רִפֵּדְתִּי יְצֻוָּי׃');
INSERT INTO verses VALUES (13278, 18, 17, 14, 'לַשַּׁחַת קְרַאְתִּי אֲבִי tu minha-mãe e-minha-irmã para-rimá:');
INSERT INTO verses VALUES (13279, 18, 17, 15, 'e-onde afô minha-esperança e-minha-esperança quem será-justificada:');
INSERT INTO verses VALUES (13280, 18, 17, 16, 'nos-dias abismo תֵּרַדְנָה se יַחַד sobre pó נָחַת׃');
INSERT INTO chapters VALUES (454, 18, 18, 21);
INSERT INTO verses VALUES (13281, 18, 18, 1, 'וַיַּעַן בִּלְדּד הַשׁוֹחִי E-disse');
INSERT INTO verses VALUES (13282, 18, 18, 2, 'até אָנָה תְּשִׂימ֣וּן קִנְצֵי לְמִלִּין תָּבִ֗ינוּ e-depois נְדַבֵּֽר׃');
INSERT INTO verses VALUES (13283, 18, 18, 3, 'מַ֭דּוּעַ נֶחְשַׁ֣בְנוּ כַבְּהֵמָ֑ה נִ֝טְמִ֗ינוּ בְּעֵינֵיכֶֽם׃');
INSERT INTO verses VALUES (13284, 18, 18, 4, 'טֹֽרֵ֥ף נַפְשׁ֗וֹ בְּאַ֫פּ֥וֹ הֲלֵמֹ֣תְךָ תֵּעַזְבֶּֽנּוּ terra וְיִעֲתָּק־ צֹור מִמְּקֹמֽוֹ׃');
INSERT INTO verses VALUES (13285, 18, 18, 5, 'também luz ímpios יִדַעְכֶּ֑ם e-não יִגַּחּוֹ שָׁבִ֣יב אִישָׁיו׃');
INSERT INTO verses VALUES (13286, 18, 18, 6, 'escuridão בְּאֹהֶלֹ֑ו e-luz sobre-ele conhecereis');
INSERT INTO verses VALUES (13287, 18, 18, 7, 'serão-formados passos seu e-lançareis sua-sabedoria');
INSERT INTO verses VALUES (13288, 18, 18, 8, 'porque enviou no-início com-seus-pés e-sobre e-confusão e-vagará');
INSERT INTO verses VALUES (13289, 18, 18, 9, 'יֹאחֵז בְּעָקֵ֣ב פָּ֑ח יַחֲזֵ֖ק sobre-ele צַמִּֽים׃');
INSERT INTO verses VALUES (13290, 18, 18, 10, 'טָמ֣וּן na-terra חַבְל֑וֹ וּ֝מַלְכֻּדְתּ֗וֹ sobre נָתִֽיב׃');
INSERT INTO verses VALUES (13291, 18, 18, 11, 'סָ֭בִיב בִּֽעֲתֻ֣הוּ בַלָּה֑וֹת וֶהֱפִיצֻ֥הוּ לְרַגְלָֽיו׃');
INSERT INTO verses VALUES (13292, 18, 18, 12, 'seja- רָעֵ֥ב אֹנ֑וֹ וְ֝אֵ֗יד נָכ֥וֹן לְצַלְעֽוֹ׃');
INSERT INTO verses VALUES (13293, 18, 18, 13, 'יֹ֭אכַל nos-dias עוֹר֑וֹ comerá בַּ֝דָּ֗יו primogênito-de מָֽוֶת׃');
INSERT INTO verses VALUES (13294, 18, 18, 14, 'יִנָּתֵ֣ק מֵ֭אָהֳלוֹ מִבְטַח֑וֹ וְ֝תַצְעִדֵ֗הוּ como-rei בַּלָּהֽוֹת׃');
INSERT INTO verses VALUES (13295, 18, 18, 15, 'תִּשְׁכּ֣וֹן em-o אֲהֵלֹו SEM a-ele irá-y יִזֹרֶה sobre o-n o-נָוֵהוּ cortina-g גָפְרִית׃');
INSERT INTO verses VALUES (13296, 18, 18, 16, 'debaixo-de seus-roots שָֽׁרָשָׁ֣יו secar-y יִבָ֑שׁוּ e-o  וּמִמַּ֗עַל cortar-y יִמַּ֥ל colheita-k קְצִירֽוֹ׃');
INSERT INTO verses VALUES (13297, 18, 18, 17, 'lembre-se-z זִֽכְרוֹ־ אבד de-mim a-ele e-não nome a-ele sobre face-de חווץ:');
INSERT INTO verses VALUES (13298, 18, 18, 18, 'יהדדווהו luzeiro a escuridão ומיתבלו ינידדוו:');
INSERT INTO verses VALUES (13299, 18, 18, 19, 'não نين a-ele e-não  Necklaced בעમו e-não-há שריד בIMGוריו:');
INSERT INTO verses VALUES (13300, 18, 18, 20, 'sobre יוֹמוֹ נָשַׁ֣מּוּ אַחֲרֹנִ֑ים וְ֝קַדְמֹנִ֗ים אָ֣חֲזוּ שָֽׂעַר׃');
INSERT INTO verses VALUES (13301, 18, 18, 21, 'somente אֵ֭לֶּה מִשְׁכְּנ֣וֹת עַוָּ֑ל וְ֝זֶ֗ה lugar não  יָדַֽע—  El');
INSERT INTO chapters VALUES (455, 18, 19, 29);
INSERT INTO verses VALUES (13302, 18, 19, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (13303, 18, 19, 2, 'até  אָ֭נָה   תּוֹגְי֣וּן  minha-alma  וּֽתְדַכּאוּנַ֥נִי   בְמִלִּֽים׃');
INSERT INTO verses VALUES (13304, 18, 19, 3, 'este dez  פְּ֭עָמִים   תַּכְלִימ֑וּנִי  não  תֵ֝בֹ֗שׁוּ   תַּהְכְּרוּ־  para-mim');
INSERT INTO verses VALUES (13305, 18, 19, 4, 'e-também  אָמְנָ֥ם  שׁגִ֑יתִי אִ֝תִּ֗י תָּלִ֥ין מְשׁוּגָתִֽי׃');
INSERT INTO verses VALUES (13306, 18, 19, 5, 'se אָ֭מְנָם sobre-mim תַּגְדִּ֑ילוּ וְתוֹכִ֥יחוּ עָ֝לַ֗י');
INSERT INTO verses VALUES (13307, 18, 19, 6, 'דְּֽעוּ־ אֵ֭פוֹ porque Eloah עיוותני ומצבדו alai היקף׃');
INSERT INTO verses VALUES (13308, 18, 19, 7, 'eis ETSUAQ חמס e-não ואנה אשווה e-não-há juízo');
INSERT INTO verses VALUES (13309, 18, 19, 8, 'ארchy גדר e-não אֶעֱבֹר e-sobre נְ֟תִיבוֹתַי escuridão יָשׂ֣ים׃');
INSERT INTO verses VALUES (13310, 18, 19, 9, 'כְּֽבוֹדִי מֵעָלַ֣י הִפְשִׁ֑יט וַֽיָּ֗סַר coroa minha-cabeça:');
INSERT INTO verses VALUES (13311, 18, 19, 10, 'יִתְּצֵ֣נִי סָ֭בִיב e-vai ele-sustentou como-árvore minha-esperança:');
INSERT INTO verses VALUES (13312, 18, 19, 11, 'ele-sucedeu-se sobre-mim seu-nariz ele-pensou-em-mim a-ele como-suas-angústias:');
INSERT INTO verses VALUES (13313, 18, 19, 12, 'juntos virão seus-exércitos e tiraram sobre-mim seu caminho e acamparam-se ao redor do meu tendão');
INSERT INTO verses VALUES (13314, 18, 19, 13, 'meus irmãos de mim se afastaram e meus conhecidos somente se foram embora de-mim');
INSERT INTO verses VALUES (13315, 18, 19, 14, 'חָדְלוּ קְרֹבוּי וּמְיֻדְעָי שְׁכָחוּנִי׃');
INSERT INTO verses VALUES (13316, 18, 19, 15, 'גָּרֵי בֵיתִי וְאַמְהֹתַי לְזָר תַּחְשְבוּנִי נָכְרִי era em-lhes');
INSERT INTO verses VALUES (13317, 18, 19, 16, 'para-o-meu-servo eu-chamei e-não responderá em-mo- com-me eu-rogo a-ele');
INSERT INTO verses VALUES (13318, 18, 19, 17, 'espírito-meu está-ferina para-esposa-meu e-rogo-ela para-filhos-de meu ventre:');
INSERT INTO verses VALUES (13319, 18, 19, 18, 'também vadios se rebelaram bi e se levantaram e disseram: בי׃');
INSERT INTO verses VALUES (13320, 18, 19, 19, 'me odeiam todo mortos seu segredo e-isto；： eu amei foram transformados בי׃');
INSERT INTO verses VALUES (13321, 18, 19, 20, 'em-me e-em-bêser-êi pegada em-mim e-me-sobrevivi em-ouro segundo');
INSERT INTO verses VALUES (13322, 18, 19, 21, 'me-acolhe me-acolhe vós me-amor que mão-de Elohim toque-a em-mim');
INSERT INTO verses VALUES (13323, 18, 19, 22, 'לָ֭מָּה תִּרְדְּפֻ֣נִי כְמוֹ־ El não não תִשְׂבָּֽעוּ׃');
INSERT INTO verses VALUES (13324, 18, 19, 23, 'quem dará אֵ֭פוֹ וְיִכָּתְב֣וּן מִלָּ֑י quem irá dar בַּסֵּ֣פֶר וְיֻחָֽקוּ׃');
INSERT INTO verses VALUES (13325, 18, 19, 24, 'בְּעֵט־ ברזל ואופרת לאעד בתצר יחצבנו׃');
INSERT INTO verses VALUES (13326, 18, 19, 25, 'e-eu ידעתי גאלני viveu ואחרון sobre poeira יתקום׃');
INSERT INTO verses VALUES (13327, 18, 19, 26, 'e-apos עורני נִקְּפוּ- esta וּמִבְּשָׂרִ֗י אֶֽחֱזֶ֥ה אֱלֽוֹהַּ׃');
INSERT INTO verses VALUES (13328, 18, 19, 27, 'que אֲנִ֨י ׀ אֶֽחֱזֶה- para-mim וְעֵינַ֣י viram e-não זָ֑ר כָּל֖וּ כִילְיֹתַ֣י no meu');
INSERT INTO verses VALUES (13329, 18, 19, 28, 'que vocês dirão que ser-vos-persegui-dos- a-ele e raiz palavra foi-encontrado- בי׃');
INSERT INTO verses VALUES (13330, 18, 19, 29, 'esconder-se-ão a-vós por causa de espada porque ira iniquidades espada para-que conhecereis');
INSERT INTO chapters VALUES (456, 18, 20, 29);
INSERT INTO verses VALUES (13331, 18, 20, 1, 'e respondeu צֹפַר הַנַּֽעֲמָתִ֗י E-disse');
INSERT INTO verses VALUES (13332, 18, 20, 2, 'לָ֭כֵן שְׂעִפַּ֣י יְשִׁיב֑וּנִי וּ֝בַעֲב֗וּר ח֣וּשִׁי בי׃');
INSERT INTO verses VALUES (13333, 18, 20, 3, 'מוּסַ֣ר כְּלִמָּתִ֣י אֶשְׁמָ֑ע e-Espírito-de de-mináti ja-‘aneni:');
INSERT INTO verses VALUES (13334, 18, 20, 4, 'hazot da''ata de-mim até minni homem homem em-o terra');
INSERT INTO verses VALUES (13335, 18, 20, 5, 'que rinnat ímpios mikkarov ve-simchat chanef ate raga:');
INSERT INTO verses VALUES (13336, 18, 20, 6, 'se subir aos céus dele e sua cabeça ao servo atingirá');
INSERT INTO verses VALUES (13337, 18, 20, 7, 'como seus grilhões para sempre será destruído seus olhos eles-dire-ão ainda');
INSERT INTO verses VALUES (13338, 18, 20, 8, 'בְּחָלוֹם יָעַף e-não יִמְצָאֵהוּ וְיֻדַּד בְּחֶזְיוֹן noite');
INSERT INTO verses VALUES (13339, 18, 20, 9, 'olho שָׁזַף e-não תּוֹסִיף e-não עוֹד תְּשׁוּרֵנּוּ מְקוֹם׃');
INSERT INTO verses VALUES (13340, 18, 20, 10, 'seus-filhos serão-alegrados pobres e-suas-mãos habitarão sua-alegria');
INSERT INTO verses VALUES (13341, 18, 20, 11, 'suas-mãos serão-cheias e-com-ele sobre poeira dormirá');
INSERT INTO verses VALUES (13342, 18, 20, 12, 'se תַּמְתִּ֣יק בְּפִ֣יו maldade debaixo em-lugar-de לְשׁוֹנֽוֹ׃');
INSERT INTO verses VALUES (13343, 18, 20, 13, 'יַחְמֹ֣ל עָ֭לֶיהָ e-não יַֽעַזְבֶ֑נָּה וְ֝יִמְנָעֶ֗נָּה no-meio-de חִכּֽוֹ׃');
INSERT INTO verses VALUES (13344, 18, 20, 14, 'לַ֭חְמוֹ בְּמֵעָ֣יו נֶהְפָּ֑ךְ מְרוֹרַ֖ת פְּתָנִ֣ים em-o-centro-dele');
INSERT INTO verses VALUES (13345, 18, 20, 15, 'força בָּ֭לַע וַיְקִאֶ֑נּוּ מִ֝בִּטְנ֗וֹ יוֹרִשֶׁ֥נּוּ El');
INSERT INTO verses VALUES (13346, 18, 20, 16, 'cume-de פְּתָנִ֥ים יִינָ֑ק תַּֽ֝הַרְגֵ֗הוּ língua-de אֶפְעֶֽה׃');
INSERT INTO verses VALUES (13347, 18, 20, 17, 'a יֵ֥רֶא בִפְלַגּ֑וֹת נַהֲרֵ֥י נַ֝חֲלֵ֗י דְּבַ֣שׁ וְחֶמְאָֽה׃');
INSERT INTO verses VALUES (13348, 18, 20, 18, 'מֵשִׁ֣יב יָ֭גָע e-não יִבְלָ֑ע כּח תּמֻרָתוֹ e-não יַעֲלוֹס׃');
INSERT INTO verses VALUES (13349, 18, 20, 19, 'porque deixar abandonou דָּלִים casa גָּזַל e-não יִבְנֶהוּ׃');
INSERT INTO verses VALUES (13350, 18, 20, 20, 'que não conheceu שָׁלוֹ בִּבְטַנּוֹ בָּחֲמֻדּוֹ não יִמְלַט׃');
INSERT INTO verses VALUES (13351, 18, 20, 21, 'não-há restante para-a-comer sobre também não יָחִ֥יל o-bem-;');
INSERT INTO verses VALUES (13352, 18, 20, 22, 'com-a-cheia sua-saída inclinação a-ele todo mão trabalho virá-o-;');
INSERT INTO verses VALUES (13353, 18, 20, 23, 'haja para-a-cheia seu-ventre ele-enviará- בּ֭וֹ חֲר֣וֹן seu-nariz וְיַמְטֵ֥ר עָ֝לֵ֗ימוֹ בִּלְחוּמֽוֹ׃');
INSERT INTO verses VALUES (13354, 18, 20, 24, 'יִ֭בְרַח מִנֵּ֣שֶׁק barzel תַּ֝חְלְפֵ֗הוּ קֶ֣שֶׁת נְחוּשָֽׁה׃');
INSERT INTO verses VALUES (13355, 18, 20, 25, 'שָׁלַף֮ וַיֵּצֵ֢א מִגְּוָ֥ה וּבָרָק מִמְּרֹרָת֥וֹ יַהֲלֹךְ sobre-ele Emins');
INSERT INTO verses VALUES (13356, 18, 20, 26, 'todo escuridão טָמ֣וּן לִצְפּ֣וּנָיו תְּאֹכְלֵהוּ fogo não נֻפּ֣ח será obscurecido em sua tenda:');
INSERT INTO verses VALUES (13357, 18, 20, 27, 'serão revelados céus seu pecado e a terra, que está em turbulência a-ele');
INSERT INTO verses VALUES (13358, 18, 20, 28, 'virá a gelar seu fruto casa-dele serão despojadas em-dia-de אַף׃');
INSERT INTO verses VALUES (13359, 18, 20, 29, 'este parte de homem ímpio de-Elohim e-nacalath amro de-El');
INSERT INTO chapters VALUES (457, 18, 21, 34);
INSERT INTO verses VALUES (13360, 18, 21, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (13361, 18, 21, 2, 'ouvi ouvindo milathi e-será zot tanchumoteichem');
INSERT INTO verses VALUES (13362, 18, 21, 3, 'saueni e-eu eu falar e-depois dabari taligu:');
INSERT INTO verses VALUES (13363, 18, 21, 4, 'he''anoki le''adam sihiy e-se madua não tiktsar ruchi:');
INSERT INTO verses VALUES (13364, 18, 21, 5, 'penu- a-mim ve''hashammu mão mão sobre pe:');
INSERT INTO verses VALUES (13365, 18, 21, 6, 'e-se Lembrei-me e me espantei e agarrei em meu corpo poder');
INSERT INTO verses VALUES (13366, 18, 21, 7, 'por-que ímpios viverão libertem-se também forçaram-se força');
INSERT INTO verses VALUES (13367, 18, 21, 8, 'seu semente firme diante deles עִמָּם וְצֶאֱצָאֵיהֶם per-ey-nay-hem');
INSERT INTO verses VALUES (13368, 18, 21, 9, 'בָתֵּיהֶם שָלוֹם מִפָּחַד e-não shevet Eloah sobre-eles');
INSERT INTO verses VALUES (13369, 18, 21, 10, 'shoro עִבַּר e-não יַגְעִל תּפַלֵּט פָרָת֗וֹ e-não תְשׁכֵּל׃');
INSERT INTO verses VALUES (13370, 18, 21, 11, 'יְשַׁלְּח֣וּ כַ֭צֹּן עֲוִילֵיהֶ֑ם וְ֝יַלְדֵיהֶ֗ם יְרַקֵּדֽוּן׃');
INSERT INTO verses VALUES (13371, 18, 21, 12, 'יִ֭שְׂאוּ כְּתֹ֣ף וְכִנּ֑וֹר וְ֝יִשְׂמְח֗וּ à-voz-de עוּגָֽב׃');
INSERT INTO verses VALUES (13372, 18, 21, 13, 'בַטּ֣וֹב יְמֵיהֶ֑ם וּ֝בְרֶ֗גַע sho''al יֵחָֽתּוּ׃');
INSERT INTO verses VALUES (13373, 18, 21, 14, 'e-disseram לָ֭אֵל vire-se nós וְדַ֥עַת דְּ֝רָכֶ֗יךָ não חָפָֽצְנוּ׃');
INSERT INTO verses VALUES (13374, 18, 21, 15, 'que Shaddai porque que e-que נּ֝וֹעִ֗יל porque נִפְגַּע־ em-ele');
INSERT INTO verses VALUES (13375, 18, 21, 16, 'eis não בְיָדָ֣ם טוּבָ֑ם עֲצַ֥ת ímpios רָ֣חֲקָה מֶֽנִּי׃');
INSERT INTO verses VALUES (13376, 18, 21, 17, 'כַּמָּ֤ה ׀ נֵר־ רְשָׁ֘עִ֤ים יִדְעָ֗ךְ E-veio עָלֵ֣ימוֹ אֵידָ֑ם חֲ֝בָלִ֗ים יְחַלֵּ֥ק בְּאַפּֽוֹ׃');
INSERT INTO verses VALUES (13377, 18, 21, 18, 'serão כְּתֶ֥בֶן diante-de espírito וּ֝כְמֹ֗ץ גְּנָבַ֥תּוּ סֻףָ׃');
INSERT INTO verses VALUES (13378, 18, 21, 19, 'אֱל֗וֹהַּ יִצְפֹּן־ לְבָנָ֥יו seu a-ele a-ele וְיֵדָֽע׃');
INSERT INTO verses VALUES (13379, 18, 21, 20, 'e-verão כִּיד֑וֹ וּמֵחֲמַ֖ת Shaddai יִשְׁתֶּֽה׃');
INSERT INTO verses VALUES (13380, 18, 21, 21, 'que que חֶפְצ֣וֹ בְּבֵית֣וֹ atrás-dele וּמִסְפַּ֖ר חֳדָשָׁ֣יו חֻצָּֽצוּ׃');
INSERT INTO verses VALUES (13381, 18, 21, 22, 'הלא אל י Lehrme דעאת וهو רמים ישפט׃');
INSERT INTO verses VALUES (13382, 18, 21, 23, 'este ימوت בעצם ת umo כֻּ֝לּ֗וֹ שלאナンnan וְשָׁלֵֽיו׃');
INSERT INTO verses VALUES (13383, 18, 21, 24, 'עֲ֭טִינָיו serão-cheias חָלָ֑ב וּמֹ֖חַ עַצְמוֹתָ֣יו יְשֻׁקֶּֽה׃');
INSERT INTO verses VALUES (13384, 18, 21, 25, 'וְזֶ֗ה יָ֭מוּת בְּנֶ֣פֶשׁ מָרָ֑ה אָכַ֗ל בַּטּוֹבָֽה׃');
INSERT INTO verses VALUES (13385, 18, 21, 26, 'יַ֭חַד sobre pó יִשְׁכָּ֑בוּ וְ֝רִמָּ֗ה תְּכַסֶּ֥ה sobre-eles');
INSERT INTO verses VALUES (13386, 18, 21, 27, 'eis ידעתי מַחְשְׁבֽוֹתֵיכֶ֑ם וּ֝מְזִמּ֗וֹת alai תַּחְמֹֽסוּ׃');
INSERT INTO verses VALUES (13387, 18, 21, 28, 'que תֹֽאמְר֗וּ ayeh casa-de נָדִ֑יב וְ֝אַיֵּ֗ה אֹ֤הֶל ׀ מִשְׁכְּנ֬וֹת רְשָׁעִֽים׃');
INSERT INTO verses VALUES (13388, 18, 21, 29, 'porventura-não שְׁ֭אֶלְתֶּם ע֣וֹבְרֵי caminho וְ֝אֹתֹתָ֗ם não tencarû:');
INSERT INTO verses VALUES (13389, 18, 21, 30, 'que para-o-dia aid yechaschêk mal leyôm avarôth yubalû:');
INSERT INTO verses VALUES (13390, 18, 21, 31, 'quem dirá sobre פנאו quem e-ele fez quem yešallêm- a-ele');
INSERT INTO verses VALUES (13391, 18, 21, 32, 'vehu likvarôt Jubal e-sobre gadîš יִשְׁקֽוֹד׃');
INSERT INTO verses VALUES (13392, 18, 21, 33, 'מָֽתְקוּ־ para-ele רִגְבֵ֫י נָ֥חַל וְ֭אַחֲרָיו todo homem יִמְשׁ֑וֹךְ וּ֝לְפָנָ֗יו não-há מִסְפָּֽר׃');
INSERT INTO verses VALUES (13393, 18, 21, 34, 'וְ֭אֵיךְ תְּנַחֲמ֣וּנִי הָ֑בֶל e-vossas-resspostas ficaram- acima');
INSERT INTO chapters VALUES (458, 18, 22, 30);
INSERT INTO verses VALUES (13394, 18, 22, 1, 'e-respondeu- Elifaz o-Temanita E-disse');
INSERT INTO verses VALUES (13395, 18, 22, 2, 'o-Leil viverá- Geber porque viverá com-ele sabedor:');
INSERT INTO verses VALUES (13396, 18, 22, 3, 'o desejo para os seios que tu o justificares e-se no teu olhar porque tu completarás as tuas sendas');
INSERT INTO verses VALUES (13397, 18, 22, 4, 'pela tua visão tu o provares virá com ti no juízo');
INSERT INTO verses VALUES (13398, 18, 22, 5, 'porventura-não רָעָתְךָ multiplicai e-nao-ha קֵ֝֗ץ לַעֲוֺנֹתֶֽיךָ׃');
INSERT INTO verses VALUES (13399, 18, 22, 6, 'porque תַחְבֹּ֣ל אַחֶ֣יךָ חִנָּ֑ם nus עֲרוּמִּ֣ים תַּפְשִֽׁיט׃');
INSERT INTO verses VALUES (13400, 18, 22, 7, 'não águas עָיֵ֣ף תַּשְׁקֶ֑ה e do fome terás-negado pão');
INSERT INTO verses VALUES (13401, 18, 22, 8, 'e-homem braço a-ele a-terra e levaste face habitou nela');
INSERT INTO verses VALUES (13402, 18, 22, 9, 'viúvas enviaste vazio e as mãos orfanos yeled');
INSERT INTO verses VALUES (13403, 18, 22, 10, 'sobre כֵּ֭ן סְבִיבוֹתֶ֣יךָ פַחִ֑ים וִֽ֝יבַהֶלְךָ פַּ֣חַד פִּתְאֹֽם׃');
INSERT INTO verses VALUES (13404, 18, 22, 11, 'ou escuridão não תִרְאֶ֑ה וְֽשִׁפְעַת־ águas תְּכַסֶּֽךָּ׃');
INSERT INTO verses VALUES (13405, 18, 22, 12, 'הֲ‍ֽלֹא־ Elohim גָּבְהָ céus וּרְאֵה cabeça estrelas porque רָמֻּ');
INSERT INTO verses VALUES (13406, 18, 22, 13, 'וְאָמַרְתָּ que conheceu El הַבְעַד עֲרָפֵל ישפט׃');
INSERT INTO verses VALUES (13407, 18, 22, 14, 'עָבִים סֵתֶר־ a-lui e-não ele-verá וְח֥וּג céus e-vagará');
INSERT INTO verses VALUES (13408, 18, 22, 15, 'הַאֹ֣רַח eternidade תִּשְׁמֹ֑ר que דָּרְכ֣וּ por-que iniquidade');
INSERT INTO verses VALUES (13409, 18, 22, 16, 'que קֻמְּט֥וּ rio o-tempo נָ֝הָ֗ר יוּצַ֥ק יְסוֹדָֽם׃');
INSERT INTO verses VALUES (13410, 18, 22, 17, 'הָאֹמְרִ֣ים para o Elohim afasta-te nós e-que fará Shaddai a-eles');
INSERT INTO verses VALUES (13411, 18, 22, 18, 'e-ele enchei em seus bom e conselho ímpios se afastará de mim:');
INSERT INTO verses VALUES (13412, 18, 22, 19, 'e-verão justos e se alegrarão e-nquí se zombará lahem:');
INSERT INTO verses VALUES (13413, 18, 22, 20, 'se não será confundido קִימָ֑נוּ וְ֝יִתְרָ֗ם אָ֣כְלָה אֵֽשׁ׃');
INSERT INTO verses VALUES (13414, 18, 22, 21, 'הַסְכֶּן־ por-favor com-ele בָּ֝הֶ֗ם תְּֽבוֹאַתְךָ֥ boa');
INSERT INTO verses VALUES (13415, 18, 22, 22, 'toma por-favor מִפִּ֣יו תּוֹרָ֑ה וְשִׂ֥ים אֲ֝מָרָ֗יו no-seu-líbber');
INSERT INTO verses VALUES (13416, 18, 22, 23, 'se volver-te-ás até Shaddai construir-te-ás afastar-te-ás iniquidade מֵאָהלֶֽךָ׃');
INSERT INTO verses VALUES (13417, 18, 22, 24, 'וְשִׁית־ sobre poeira בָּ֑צֶר וּבְצ֖וּר נְחָלִ֣ים opir');
INSERT INTO verses VALUES (13418, 18, 22, 25, 'e-foi Shaddai בְּצָרֶ֑יךָ וְכֶ֖סֶף תּוֹעָפ֣וֹת');
INSERT INTO verses VALUES (13419, 18, 22, 26, 'porque אָז sobre Shaddai תִּתְעַנָּ֑ג וְתִשָּׂ֖א a teu-rosto');
INSERT INTO verses VALUES (13420, 18, 22, 27, 'תַּעְתִּ֣יר a-ele וְיִשְׁמָעֶ֑ךָּ וּנְדָרֶ֥יךָ תְשַׁלֵּֽם׃');
INSERT INTO verses VALUES (13421, 18, 22, 28, 'וְֽתִגְזַר־ E-levantou para-ti e-sobre דְּ֝רָכֶ֗יךָ נָ֣גַֽהּ');
INSERT INTO verses VALUES (13422, 18, 22, 29, 'porque E-disse וַתֹּ֣אמֶר costas וְשַׁ֖ח עֵינַ֣יִם יוֹשִֽׁעַ׃');
INSERT INTO verses VALUES (13423, 18, 22, 30, 'יֽ͏ְמַלֵּ֥ט não- נָקִ֑י וְ֝נִמְלַ֗ט בְּבֹ֣ר כַּפֶּֽיךָ׃');
INSERT INTO chapters VALUES (459, 18, 23, 17);
INSERT INTO verses VALUES (13424, 18, 23, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (13425, 18, 23, 2, 'também o-hoje מְרִ֣י שִׂחַי יָדִי pesada sobre');
INSERT INTO verses VALUES (13426, 18, 23, 3, 'quem dará ידעתי וְאֶמְצָאֵ֑הוּ אָבוֹא até');
INSERT INTO verses VALUES (13427, 18, 23, 4, 'אֶעֱרַךְ diante-dele juízo וּפִי אֲמַלֵּא');
INSERT INTO verses VALUES (13428, 18, 23, 5, 'אֵדְעָה מִלּוֹת יַעֲנֵנִי וְ֝אָבִ֗ינָה que יֹּ֥אמַר para-mim');
INSERT INTO verses VALUES (13429, 18, 23, 6, 'הַבְּרָב־ כֹּ֭חַ comigo não não somente hu יָשִׂ֥ם em-mim');
INSERT INTO verses VALUES (13430, 18, 23, 7, 'nome yashar נוֹכָ֣ח com-ele וַאֲפַלְּטָ֥ה לָ֝נֶ֗צַח מִשֹׁפְטִֽי׃');
INSERT INTO verses VALUES (13431, 18, 23, 8, 'eis oriente אֶהֱלֹ֣ךְ וְאֵינֶ֑נּוּ וְ֝אָח֗וֹר e-não a-ele a-ele');
INSERT INTO verses VALUES (13432, 18, 23, 9, 'שְׂמֹ֣אול בַּעֲשֹׂת֣וֹ e-não אָ֑חַז יַעְטֹ֥ף יָ֝מִ֗ין e-não אֶרְאֶֽה׃');
INSERT INTO verses VALUES (13433, 18, 23, 10, 'porque o-caminho-de comigo עםADI בְּ֝חָנַ֗נִי כַּזָּהָ֥ב Eu saindo:');
INSERT INTO verses VALUES (13434, 18, 23, 11, 'no Ashur Acháza de-pé caminho-dele eu guardei e-não At:');
INSERT INTO verses VALUES (13435, 18, 23, 12, 'mandamento da suas bocas e-não eu disse de minha lei eu escondi palavras-de sua boca:');
INSERT INTO verses VALUES (13436, 18, 23, 13, 'e-ele no-primero e-quem irá-sentá-lo e-seu-espírito será-uma E-fez');
INSERT INTO verses VALUES (13437, 18, 23, 14, 'que completará seu-decreto e-servirá רַבּ֣וֹת com-ele');
INSERT INTO verses VALUES (13438, 18, 23, 15, 'sobre כֵּ֭ן ante-o-seu-rosto e-velará אֶתְבּוֹנֵ֗ן nós de-nós');
INSERT INTO verses VALUES (13439, 18, 23, 16, 'e-a [הֵרַ֣ךְ] meu-coração [וְ֝שַׁדַּ֗י] [הִבְהִילָֽנִי]');
INSERT INTO verses VALUES (13440, 18, 23, 17, 'porque não [מִפְּנֵי־חֹ֑שֶׁךְ] [וּ֝מִפָּנַ֗י] escuridão');
INSERT INTO chapters VALUES (460, 18, 24, 25);
INSERT INTO verses VALUES (13441, 18, 24, 1, 'madua'' não נִצְפְּנ֣וּ עִתִּ֑ים não חָ֥זוּ seus-dias:');
INSERT INTO verses VALUES (13442, 18, 24, 2, 'fronteiras atingirão troupe roubarão e-germinaram:');
INSERT INTO verses VALUES (13443, 18, 24, 3, 'חֲמ֣וֹר viúvos conduzirão enganarão boi אלמנוה');
INSERT INTO verses VALUES (13444, 18, 24, 4, 'tormentearão pobres do-caminho junto choveu os-pobres- terra');
INSERT INTO verses VALUES (13445, 18, 24, 5, 'eis as-filhas-do- no-deserto saíram em-suas-atividades aqueles-que-espanham para-o-lado arabá a-ele a-ele pão');
INSERT INTO verses VALUES (13446, 18, 24, 6, 'em-o-campo na-sua-noite e-vineiro ímpio secarão-se');
INSERT INTO verses VALUES (13447, 18, 24, 7, 'nu pernoitarão מִבְּלִֽי lebuš e-não-há כּוּסוּת ao-amanhecer');
INSERT INTO verses VALUES (13448, 18, 24, 8, 'do-amanhecer os-montes se-moitarão e-mibi makhseh chibqû- Zur');
INSERT INTO verses VALUES (13449, 18, 24, 9, 'yigz''lû mishod yatôm e-sobre עָנִ֥י yachbûlû:');
INSERT INTO verses VALUES (13450, 18, 24, 10, 'nu hilçu beli lebuš e fome levaram um om');
INSERT INTO verses VALUES (13451, 18, 24, 11, 'entre suas sarças chirariam que Jacó seus caminhos e se secaram');
INSERT INTO verses VALUES (13452, 18, 24, 12, 'de cidade morrendo serão-enganados e-alma- que-são-desecrados vociferem e-a-Divindade- não põe-se serão-malditas');
INSERT INTO verses VALUES (13453, 18, 24, 13, 'e-eles foram em-mordedores- luz não conheceram דְרָכָ֑יו e-não יָ֝שְׁב֗וּ בִּנְתִיבֹתָֽיו׃');
INSERT INTO verses VALUES (13454, 18, 24, 14, 'à-luz [יָ֘ק֤וּם] [רוֹצֵ֗חַ] [יִֽקְטָל־עָנִ֥י] [וְאֶבְי֑וֹן] e-na-noite haja seja');
INSERT INTO verses VALUES (13455, 18, 24, 15, 'וְעֵ֤ין נֹאֵ֨ף ׀ שָׁ֤מְרָֽה נשף לֵ֭אמֹר dizendo Teshuveni olho vesetar face יָשׂ֣ים׃');
INSERT INTO verses VALUES (13456, 18, 24, 16, 'chatar b''achoshekh bat''im de-dia chitamu- tsalma''vet luz yad''e''u luz');
INSERT INTO verses VALUES (13457, 18, 24, 17, 'que yachdav ⚬ manhã manhã tsalma''vet porque ויחכיר לאלהות צַלְמָהּ׃');
INSERT INTO verses VALUES (13458, 18, 24, 18, '[קַֽל־ה֤וּא] [׀] sobre face-de águas [בָּאָ֑רֶץ] [לֹֽא־יִ֝פְנֶה] o-caminho-de não caminho');
INSERT INTO verses VALUES (13459, 18, 24, 19, 'צייה também חום serão cortados nos tempos dos neve e-comeste pecaram');
INSERT INTO verses VALUES (13460, 18, 24, 20, 'o esquecerá maternidade - destruíram ruína ainda não será lembrado e quebrou á-ces avareza:');
INSERT INTO verses VALUES (13461, 18, 24, 21, 'ro-a -akarah não -del v-almána não yitib:');
INSERT INTO verses VALUES (13462, 18, 24, 22, 'u-mashak'' -abirim -bokho -qum e-não יאמין בחינה׃');
INSERT INTO verses VALUES (13463, 18, 24, 23, 'dê a-ele [וְיִשָּׁעֵ֑ן] [וְ֝עֵינֵ֗יהוּ] [עַל־דַּרְכֵיהֶֽם] sobre');
INSERT INTO verses VALUES (13464, 18, 24, 24, 'ROOMוּ מעט ׀ ואיננוּ והומכוּ como tudo pularão e como a cabeça safra serão colhidas');
INSERT INTO verses VALUES (13465, 18, 24, 25, 'e-se não quem quem enganará-me e puserá para o Elohim minha palavra');
INSERT INTO chapters VALUES (461, 18, 25, 6);
INSERT INTO verses VALUES (13466, 18, 25, 1, '[וַ֭יַּעַן] [בִּלְדַּ֥ד] [הַשֻּׁחִ֗י] E-disse');
INSERT INTO verses VALUES (13467, 18, 25, 2, 'o rei וָפַחַד com-ele fez שָׁ֝ל֗וֹם בִּמְרֹמָֽיו׃');
INSERT INTO verses VALUES (13468, 18, 25, 3, '[הֲיֵ֣שׁ] [מִ֭סְפָּר] [לִגְדוּדָ֑יו] e-sobre [לֹא־יָק֥וּם] não');
INSERT INTO verses VALUES (13469, 18, 25, 4, 'e-que [אֱנ֣וֹשׁ] [עִם־אֵ֑ל] com El e-que mulher');
INSERT INTO verses VALUES (13470, 18, 25, 5, 'eis até lua e-não irá iluminar e estrelas não זַכּוּ בְעֵינָיו׃');
INSERT INTO verses VALUES (13471, 18, 25, 6, 'certamente porque mortal Rimá e-filho-de homem foi despojada:');
INSERT INTO chapters VALUES (462, 18, 26, 14);
INSERT INTO verses VALUES (13472, 18, 26, 1, 'e-respondeu Jó E-disse');
INSERT INTO verses VALUES (13473, 18, 26, 2, 'que ajudei para sem força salvaste yhwh não o-oz:');
INSERT INTO verses VALUES (13474, 18, 26, 3, 'que conselheira para sem sabedoria וְ֝תוּשִׁיָּ֗ה לָרֹ֥ב הוֹדָֽעְתָּ׃');
INSERT INTO verses VALUES (13475, 18, 26, 4, 'a [הִגַּ֣דְתָּ] [מִלִּ֑ין] [וְנִשְׁמַת־מִ֝י] [יָצְאָ֥ה] [מִמֶּֽךָּ]');
INSERT INTO verses VALUES (13476, 18, 26, 5, '[הָרְפָאִ֥ים] [יְחוֹלָ֑לוּ] debaixo-de águas [וְשֹׁכְנֵיהֶֽם]');
INSERT INTO verses VALUES (13477, 18, 26, 6, 'nu sho''al diante-de-lho e-não-há כּוּסוּת לָאֲבַדּוֹן׃');
INSERT INTO verses VALUES (13478, 18, 26, 7, '[נֹטֶ֣ה] [צָפ֣וֹן] sobre sem-forma terra terra sobre');
INSERT INTO verses VALUES (13479, 18, 26, 8, '[צֹרֵֽר־מַ֥יִם] águas [וְלֹא־נִבְקַ֖ע] e-não [תַּחְתָּֽם]');
INSERT INTO verses VALUES (13480, 18, 26, 9, '[מְאַחֵ֥ז] face-de [פַּרְשֵׁ֖ז] [עָלָ֣יו] sobre-ele');
INSERT INTO verses VALUES (13481, 18, 26, 10, '[חֹֽק־חָ֭ג] [עַל־פְּנֵי־מָ֑יִם] sobre luz águas até luz com escuridão');
INSERT INTO verses VALUES (13482, 18, 26, 11, 'colunas-de céus יְרוֹפָ֑פוּ וְ֝יִתְמְה֗וּ de-sua-ira:');
INSERT INTO verses VALUES (13483, 18, 26, 12, 'por-seu-poder momento o-mar quebrar vasto:');
INSERT INTO verses VALUES (13484, 18, 26, 13, 'por-seu-espírito céus puro quebrantador sua-mão serpente por-seu-cheiro:');
INSERT INTO verses VALUES (13485, 18, 26, 14, 'eis אלה קצוות e-que שמץ palavra nishma- nele ve-ra''am quem yitbownan:');
INSERT INTO chapters VALUES (463, 18, 27, 23);
INSERT INTO verses VALUES (13486, 18, 27, 1, 'e-continuou Iyyov carregar mashal-o E-disse');
INSERT INTO verses VALUES (13487, 18, 27, 2, 'vida El hesisir mispati veshaday fez-amargo alma-de-mim');
INSERT INTO verses VALUES (13488, 18, 27, 3, 'porque todo ainda e-Espírito-de [אֱל֣וֹהַּ] [בְּאַפִּֽי]');
INSERT INTO verses VALUES (13489, 18, 27, 4, 'se [שְׂפָתַ֣י] [עַוְלָ֑ה] [וּ֝לְשׁוֹנִ֗י] [אִם־יֶהְגֶּ֥ה] se');
INSERT INTO verses VALUES (13490, 18, 27, 5, 'longe-seja a-mim se [אֶ֫תְכֶ֥ם] [עַד־אֶגְוָ֑ע] até [תֻּמָּתִ֣י] não');
INSERT INTO verses VALUES (13491, 18, 27, 6, '[בְּצִדְקָתִ֣י] [הֶ֭חֱזַקְתִּי] e-não [אַרְפֶּ֑הָ] não [לְ֝בָבִ֗י] [מִיָּמָֽי]');
INSERT INTO verses VALUES (13492, 18, 27, 7, 'haja כרashaע אויבי e-me-elevarei por-enganos:');
INSERT INTO verses VALUES (13493, 18, 27, 8, 'que que esperança que porque que porque de-sua Eloah sua-alma:');
INSERT INTO verses VALUES (13494, 18, 27, 9, '-sua-choro será-ouvido El porque vires sobre-ele angústia');
INSERT INTO verses VALUES (13495, 18, 27, 10, 'se sobre chamaria será-alegrado chamar-se-á Eloah em-todo tempo:');
INSERT INTO verses VALUES (13496, 18, 27, 11, '[אוֹרֶ֣ה] [אֶתְכֶ֣ם] por-mão-de El que não Shaddai não');
INSERT INTO verses VALUES (13497, 18, 27, 12, 'eis vós [חֲזִיתֶ֑ם] [וְלָמָּה־זֶּ֝֗ה] [הֶ֣בֶל] [תֶּהְבָּֽלוּ]');
INSERT INTO verses VALUES (13498, 18, 27, 13, 'este parte de homem רָשָׁ֥ע ׀ com El וְֽנַחֲלַ֥ת עָ֝רִיצִ֗ים de-mádi יאקקוּ׃');
INSERT INTO verses VALUES (13499, 18, 27, 14, 'se [בָנָ֣יו] [לְמוֹ־חָ֑רֶב] [וְ֝צֶאֱצָאָ֗יו] não [יִשְׂבְּעוּ־לָֽחֶם] não');
INSERT INTO verses VALUES (13500, 18, 27, 15, '[*שרידו] [**שְׂ֭רִידָיו] [בַּמָּ֣וֶת] não [וְ֝אַלְמְנֹתָ֗יו]');
INSERT INTO verses VALUES (13501, 18, 27, 16, 'se יִצְבֹּ֣ר כֶּעָפָ֣ר prata וְ֝כַחֹ֗מֶר fará vestuário:');
INSERT INTO verses VALUES (13502, 18, 27, 17, 'fará e o justo vestirá e prata puro distribuir-');
INSERT INTO verses VALUES (13503, 18, 27, 18, 'edificar como o asaf casa-dele e a cisterna fez guardião:');
INSERT INTO verses VALUES (13504, 18, 27, 19, 'עָשִׁיר יִ֭שְׁכַּב e-não יֵאָסֵ֑ף seus-olhos abrir ve''ēnnū:');
INSERT INTO verses VALUES (13505, 18, 27, 20, '[תַּשִּׂיגֵ֣הוּ] [כַ֭מַּיִם] [בַּלָּה֑וֹת] noite [גְּנָבַ֥תּוּ] [סוּפָֽה]');
INSERT INTO verses VALUES (13506, 18, 27, 21, '[יִשָּׂאֵ֣הוּ] [קָדִ֣ים] E-andou [וִֽ֝ישָׂעֲרֵ֗הוּ] [מִמְּקֹמֽוֹ]');
INSERT INTO verses VALUES (13507, 18, 27, 22, '[וְיַשְׁלֵ֣ךְ] [עָ֭לָיו] e-não [יַחְמֹ֑ל] [מִ֝יָּד֗וֹ] [בָּר֥וֹחַ] [יִבְרָֽח]');
INSERT INTO verses VALUES (13508, 18, 27, 23, '[יִשְׂפֹּ֣ק] [עָלֵ֣ימוֹ] [כַפֵּ֑ימוֹ] [וְיִשְׁרֹ֥ק] [עָ֝לָ֗יו] [מִמְּקֹמֽוֹ]');
INSERT INTO chapters VALUES (464, 18, 28, 28);
INSERT INTO verses VALUES (13509, 18, 28, 1, 'que há [לַכֶּ֣סֶף] [מוֹצָ֑א] [וּ֝מָק֗וֹם] [לַזָּהָ֥ב] [יָזֹֽקּוּ]');
INSERT INTO verses VALUES (13510, 18, 28, 2, '[בַּ֭רְזֶל] [מֵעָפָ֣ר] [יֻקָּ֑ח] [וְ֝אֶ֗בֶן] [יָצ֥וּק] [נְחוּשָֽׁה]');
INSERT INTO verses VALUES (13511, 18, 28, 3, 'קץ nome לחושך e-para-todo תכלית ele חקיר pedra אופל e-imagem');
INSERT INTO verses VALUES (13512, 18, 28, 4, 'quebrou najal de-com gur os-que-forgetados de-mim רָ֑גֶל desceram de-homem andaram');
INSERT INTO verses VALUES (13513, 18, 28, 5, 'terra de-a-ela saiu- pão e-sob-ele se-tornar como אֵֽשׁ׃');
INSERT INTO verses VALUES (13514, 18, 28, 6, '[מְקוֹם־סַפִּ֥יר] [אֲבָנֶ֑יהָ] [וְעַפְרֹ֖ת] ouro a-ele');
INSERT INTO verses VALUES (13515, 18, 28, 7, '[נָ֭תִיב] não [עָ֑יִט] [וְלֹ֥א] e-não [עֵ֣ין] olho');
INSERT INTO verses VALUES (13516, 18, 28, 8, 'não [בְנֵי־שָׁ֑חַץ] filhos-de [עָלָ֣יו] não');
INSERT INTO verses VALUES (13517, 18, 28, 9, '[בַּֽ֭חַלָּמִישׁ] enviou sua-mão revolver [מִשֹּׁ֣רֶשׁ] [הָרִֽים]');
INSERT INTO verses VALUES (13518, 18, 28, 10, '[בַּ֭צּוּרוֹת] [יְאֹרִ֣ים] [בִּקֵּ֑עַ] e-todo [רָאֲתָ֥ה] [עֵינֽוֹ]');
INSERT INTO verses VALUES (13519, 18, 28, 11, 'מִבְּכִֽי נְהָר֣וֹת חִבֵּשׁ e-a-saída saia luz');
INSERT INTO verses VALUES (13520, 18, 28, 12, 'e-a-sabedoria de-onde será-encontrada e-qualquer isto lugar em-inteligência');
INSERT INTO verses VALUES (13521, 18, 28, 13, 'não conheceu mortal será-encontrada e-não será-encontrada em-terra-de serão-vidas');
INSERT INTO verses VALUES (13522, 18, 28, 14, 'abismo disse não [בִי־הִ֑יא] ela disse disse comigo');
INSERT INTO verses VALUES (13523, 18, 28, 15, 'não [סְג֣וֹר] [תַּחְתֶּ֑יהָ] [וְלֹ֥א] e-não [כֶּ֣סֶף] prata');
INSERT INTO verses VALUES (13524, 18, 28, 16, 'não [בְּכֶ֣תֶם] [אוֹפִ֑יר] [בְּשֹׁ֖הַם] [יָקָ֣ר] [וְסַפִּֽיר]');
INSERT INTO verses VALUES (13525, 18, 28, 17, 'não ouro ouro e zóchit e tamaratah vida e faz:');
INSERT INTO verses VALUES (13526, 18, 28, 18, 'raomot e gavish não yizakar e meshek sabedoria de-pnínim:');
INSERT INTO verses VALUES (13527, 18, 28, 19, 'não irákena petdat- kuš não tahor não tesele:');
INSERT INTO verses VALUES (13528, 18, 28, 20, 'e-ḥokmah de-onde vens ve-ai ze lugar binah:');
INSERT INTO verses VALUES (13529, 18, 28, 21, 'e-né-ule-má-ha das-olhos todo viveu e-me-óf os-céus נִסְתּרָה׃');
INSERT INTO verses VALUES (13530, 18, 28, 22, 'avá-dá-von e-ma-vé-t a-óm-rú b-á-a-zé-né-vi-nu שָׁמַ֥עְנוּ shí-ma-há:');
INSERT INTO verses VALUES (13531, 18, 28, 23, 'Elohim hé-bi-n dár-kha-ha וهو saber a mék-o-má-ha:');
INSERT INTO verses VALUES (13532, 18, 28, 24, 'porque ele límites- debaixo olhe sob todo os-céus vere-:');
INSERT INTO verses VALUES (13533, 18, 28, 25, 'para fazer para-a-ventura segundo-peso e-agua- será-disposto em-medida-:');
INSERT INTO verses VALUES (13534, 18, 28, 26, 'quando-fazê-lo para-a-chuva חֹ֑ק וְ֝דֶ֗רֶךְ לַחֲזִ֥יז קֹלֽוֹת׃');
INSERT INTO verses VALUES (13535, 18, 28, 27, 'então viu [וַֽיְסַפְּרָ֑הּ] [הֱ֝כִינָ֗הּ] e-também');
INSERT INTO verses VALUES (13536, 18, 28, 28, 'E-disse לָֽאָדָ֗ם הֵ֤ן eis Adonai ela sabedoria וְס֖וּר de-ma-rá'' biná∶');
INSERT INTO chapters VALUES (465, 18, 29, 25);
INSERT INTO verses VALUES (13537, 18, 29, 1, 'e-continuou Iyyov carregar mesha-lo E-disse');
INSERT INTO verses VALUES (13538, 18, 29, 2, 'quem ytteneni kiyarachey－ antes kayimay Eloah yishmereni∶');
INSERT INTO verses VALUES (13539, 18, 29, 3, 'b''hillo nero sobre cabeça-de mim le-oro אֵלֶּכְ escuridão');
INSERT INTO verses VALUES (13540, 18, 29, 4, 'como-que הָיִיתִי em-dias-de חָרְפִּי בְּס֥וֹד Elohim sobre אָהֳלִֽי׃');
INSERT INTO verses VALUES (13541, 18, 29, 5, 'em-ainda Shaddai comigo [סְבִ֖יבוֹתַ֣י] [נְעָרָֽי]');
INSERT INTO verses VALUES (13542, 18, 29, 6, '[בִּרְחֹ֣ץ] [הֲלִיכַ֣י] [בְּחֵמָ֑ה] [וְצ֥וּר] [יָצ֥וּק] comigo [פַּלְגֵי־שָֽׁמֶן]');
INSERT INTO verses VALUES (13543, 18, 29, 7, '[בְּצֵ֣אתִי] portão sobre [בָּ֝רְח֗וֹב] [אָכִ֥ין] [מוֹשָׁבִֽי]');
INSERT INTO verses VALUES (13544, 18, 29, 8, 'ראוני נְעָרִ֣ים ונחבאוּ וישישים levantaram-se estavam:');
INSERT INTO verses VALUES (13545, 18, 29, 9, 'שַׂרִים עֲצַרֻ בְּמִלּוֹת וְכָף serão puestos לְפִי־הֶם׃');
INSERT INTO verses VALUES (13546, 18, 29, 10, 'voz-de [נֶחְבָּ֑אוּ] [וּ֝לְשׁוֹנָ֗ם] [לְחִכָּ֥ם] [דָּבֵֽקָה]');
INSERT INTO verses VALUES (13547, 18, 29, 11, 'que o-ouvido שׁמעה וַתְּאַשּׁׁרֵנִי וְעַ֥ין רָ֝אֲתָ֗ה וַתְּעִידֵֽנִי׃');
INSERT INTO verses VALUES (13548, 18, 29, 12, 'porque [עָנִ֣י] afligido [וְ֝יָת֗וֹם] [וְֽלֹא־עֹזֵ֥ר] a-ele');
INSERT INTO verses VALUES (13549, 18, 29, 13, '[בִּרְכַּ֣ת] [אֹ֭בֵד] sobre-mim [תָּבֹ֑א] [וְלֵ֖ב] [אַלְמָנָ֣ה] [אַרְנִֽן]');
INSERT INTO verses VALUES (13550, 18, 29, 14, 'justica visto-eu וַיִּלְבָּשֵׁנִי כִּֽמְעִיל וְ֝צָנִ֗יף מִשְׁפָּטִֽי׃');
INSERT INTO verses VALUES (13551, 18, 29, 15, 'עֵינַ֣יִם הָ֭יִיתִי לַֽעִוֵּ֑ר e-pés-me para-passover eu');
INSERT INTO verses VALUES (13552, 18, 29, 16, 'pai eu para-avôns e-dispute não eu-sei eu-investigarei:');
INSERT INTO verses VALUES (13553, 18, 29, 17, 'e-pensei crescendo עַוָּ֑ל e-de-seus lançarei lado:');
INSERT INTO verses VALUES (13554, 18, 29, 18, 'e disse com comprei dor multiplicarei sow dias');
INSERT INTO verses VALUES (13555, 18, 29, 19, 'raiz aberto אֶל־ águas e chuva yalin no tempo da colheita');
INSERT INTO verses VALUES (13556, 18, 29, 20, 'כְּֽבוֹדִי novo comigo e vara na minha mão tachălip̄∶');
INSERT INTO verses VALUES (13557, 18, 29, 21, 'לי— שָׁמְע֥וּ ve''yichello''u ve''ydimmu lemo'' ătsāti∶');
INSERT INTO verses VALUES (13558, 18, 29, 22, 'depois-de de''vari não yishnu''u ve''alē''imo'' tittāph millati∶');
INSERT INTO verses VALUES (13559, 18, 29, 23, 'e se alegrarão como a chuva a-mim e suas bocas se exibirem para maltratá-los:');
INSERT INTO verses VALUES (13560, 18, 29, 24, 'eu risquei lhes não e crerão e a luz face-de não os lançará:');
INSERT INTO verses VALUES (13561, 18, 29, 25, '[אֶֽבֲחַ֣ר] [דַּרְכָּם֮] [וְאֵשֵׁ֢ב] cabeça [וְ֭אֶשְׁכּוֹן] [כְּמֶ֣לֶךְ] [בַּגְּד֑וּד] como [אֲבֵלִ֣ים] [יְנַחֵֽם]');
INSERT INTO chapters VALUES (466, 18, 30, 31);
INSERT INTO verses VALUES (13562, 18, 30, 1, 'e-agora שָֽׂחֲק֣וּ sobre-mim צְעִירִ֥ים מִמֶּ֗נִּי לְיָ֫מִ֥ים que מָאַ֥סְתִּי pais-deles לָ֝שִׁ֗ית com כַּלְבֵ֥י צֹאנִֽי׃');
INSERT INTO verses VALUES (13563, 18, 30, 2, 'também força yed-ei-hem a-mim li עָ֝לֵ֗ימוֹ אָ֣בַד calah');
INSERT INTO verses VALUES (13564, 18, 30, 3, 'בְּחֶ֥סֶר וּבְכָפָ֗ן גַּ֫לְמ֥וּד os-órquins tsiyyah emesh sho''ah u-mesho''ah');
INSERT INTO verses VALUES (13565, 18, 30, 4, 'os-kotfim malakh sobre shiqah veshoresh retamim pão');
INSERT INTO verses VALUES (13566, 18, 30, 5, 'de e e lançarão fora yarieu עָ֝לֵ֗ימוֹ como um ladrão');
INSERT INTO verses VALUES (13567, 18, 30, 6, 'destruídos rios para habitar buracos pó e covas;');
INSERT INTO verses VALUES (13568, 18, 30, 7, 'entre [יִנְהָ֑קוּ] debaixo sob [יְסֻפָּֽחוּ]');
INSERT INTO verses VALUES (13569, 18, 30, 8, 'filhos-de [גַּם־בְּנֵ֣י] também filhos-de [מִן־הָאָֽרֶץ] nome de a-terra');
INSERT INTO verses VALUES (13570, 18, 30, 9, 'e-agora [נְגִינָתָ֣ם] [הָיִ֑יתִי] [וָאֱהִ֖י] a-eles [לְמִלָּֽה]');
INSERT INTO verses VALUES (13571, 18, 30, 10, '[תִּֽ֭עֲבוּנִי] [רָ֣חֲקוּ] [מֶ֑נִּי] [וּ֝מִפָּנַ֗י] não [רֹֽק]');
INSERT INTO verses VALUES (13572, 18, 30, 11, 'porque פתתח WAYaaneni WEResen mpiphanai eles-enviaram');
INSERT INTO verses VALUES (13573, 18, 30, 12, 'sobre ימין פריחח levantem-se-eles רגלי שלחוּ VASOLOU עלאי אָרְח֥וֹת IEDAM');
INSERT INTO verses VALUES (13574, 18, 30, 13, '[נָתְס֗וּ] [נְֽתִיבָ֫תִ֥י] [לְהַוָּתִ֥י] [יֹעִ֑ילוּ] não [עֹזֵ֣ר] a-eles');
INSERT INTO verses VALUES (13575, 18, 30, 14, 'כְּפֶ֣רֶץ Rahab יֶאֱתָ֑יוּ debaixo שֹׁ֝אָ֗ה הִתְגַּלְגָּֽלוּ׃');
INSERT INTO verses VALUES (13576, 18, 30, 15, '[הָהְפַּ֥ךְ] [עָלַ֗י] [בַּלָּ֫ה֥וֹת] [תִּרְדֹּ֣ף] [כָּ֭רוּחַ] [נְדִבָתִ֑י] [וּ֝כְעָ֗ב] [עָבְרָ֥ה] [יְשֻׁעָתִֽי]');
INSERT INTO verses VALUES (13577, 18, 30, 16, 'e-agora [עָ֭לַי] [תִּשְׁתַּפֵּ֣ךְ] minha-alma [יֹ֭אחֲז֣וּנִי] dias-de');
INSERT INTO verses VALUES (13578, 18, 30, 17, 'noite עֲ֭צָמַי נִקַּ֣ר de-mim-sobre וְ֝עֹרְקַ֗י não יִשְׁכָּבֽוּן׃');
INSERT INTO verses VALUES (13579, 18, 30, 18, '[בְּרָב־כֹּ֭חַ] [יִתְחַפֵּ֣שׂ] [לְבוּשִׁ֑י] [כְּפִ֖י] [כֻתָּנְתִּ֣י] [יַֽאַזְרֵֽנִי]');
INSERT INTO verses VALUES (13580, 18, 30, 19, 'הורני לחומר ואתמשל כעפר e-fuligem');
INSERT INTO verses VALUES (13581, 18, 30, 20, '[אֲשַׁוַּ֣ע] [אֵ֭לֶיךָ] e-não [תַעֲנֵ֑נִי] [עָ֝מַ֗דְתִּי] [וַתִּתְבֹּ֥נֶן] em-mim');
INSERT INTO verses VALUES (13582, 18, 30, 21, '[תֵּהָפֵ֣ךְ] [לְאַכְזָ֣ר] a-mim [בְּעֹ֖צֶם] [יָדְךָ֣] [תִשְׂטְמֵֽנִי]');
INSERT INTO verses VALUES (13583, 18, 30, 22, '[תִּשָּׂאֵ֣נִי] a [תַּרְכִּיבֵ֑נִי] [וּ֝תְמֹגְגֵ֗נִי]');
INSERT INTO verses VALUES (13584, 18, 30, 23, 'porque ידעתי מוות תְּשִׁיבֵ֑נִי וּבֵ֖ית na-festa para-todo viveu');
INSERT INTO verses VALUES (13585, 18, 30, 24, 'porém não [יִשְׁלַח־יָ֑ד] [אִם־בְּ֝פִיד֗וֹ] mão se');
INSERT INTO verses VALUES (13586, 18, 30, 25, 'se não [לִקְשֵׁה־י֑וֹם] [עָֽגְמָ֥ה] dia [לָאֶבְיֽוֹן]');
INSERT INTO verses VALUES (13587, 18, 30, 26, 'que bom [קִ֭וִּיתִי] E-veio mal [וַֽאֲיַחֲלָ֥ה] [לְ֝א֗וֹר] E-veio [אֹֽפֶל]');
INSERT INTO verses VALUES (13588, 18, 30, 27, '[מֵעַ֖י] [רֻתְּח֥וּ] e-não [קִדְּמֻ֥נִי] [יְמֵי־עֹֽנִי]');
INSERT INTO verses VALUES (13589, 18, 30, 28, 'קֹדֶר הִלַּכְתִּי bəlō'' חֲמָה קָמְתִּי בַקָּהָל אֲשַׁוְּעַ׃');
INSERT INTO verses VALUES (13590, 18, 30, 29, 'אָח eu-fui לְתַנִּים e rei para-construir responde');
INSERT INTO verses VALUES (13591, 18, 30, 30, 'minha pele alvorada de-mim-sobre e eu mesmo- ardeu de-mim Choreb');
INSERT INTO verses VALUES (13592, 18, 30, 31, 'e-houve para Ebal cítara e o flautista à-voz-de chorando:');
INSERT INTO chapters VALUES (467, 18, 31, 40);
INSERT INTO verses VALUES (13593, 18, 31, 1, 'aliança cortei perante mim e qual eu examinar sobre virgem:');
INSERT INTO verses VALUES (13594, 18, 31, 2, 'e qual חֵ֣לֶק Eloah de cima herança Shaddai de-altos:');
INSERT INTO verses VALUES (13595, 18, 31, 3, 'não-é ain para-ruína: e-verdade: para-trabalhadores: iniquidade');
INSERT INTO verses VALUES (13596, 18, 31, 4, 'não-é ele virão-ve: minhas-caminhos: e-todo meus-passos: serão-contados:');
INSERT INTO verses VALUES (13597, 18, 31, 5, 'se eu-andei com שָׁוְא e arrepiou-se sobre מִרְמָ֣ה minha perna:');
INSERT INTO verses VALUES (13598, 18, 31, 6, 'ele pesará-me em-mozenais justica e conhecerá Elohim minha integridade:');
INSERT INTO verses VALUES (13599, 18, 31, 7, 'mãe purifica assí de-mim o caminho e-apos minhas-olhos andar meu-coração e-em-meu-pés unir-se estão-terrivelmente:');
INSERT INTO verses VALUES (13600, 18, 31, 8, 'Ezreáh e-outro comera e-meus-nascidos serão-plantados:');
INSERT INTO verses VALUES (13601, 18, 31, 9, 'se enganou-se meu-coração sobre mulher e-sobre entrada-de meu-amigo eu-ameacei:');
INSERT INTO verses VALUES (13602, 18, 31, 10, '[תִּטְחַ֣ן] [לְאַחֵ֣ר] [אִשְׁתִּ֑י] [וְ֝עָלֶ֗יהָ] [יִכְרְע֥וּן] [אֲחֵרִֽין]');
INSERT INTO verses VALUES (13603, 18, 31, 11, 'porque [**הִ֥יא] [זִמָּ֑ה] [*והיא]');
INSERT INTO verses VALUES (13604, 18, 31, 12, 'que fogo [הִ֭יא] até comerás [וּֽבְכָל־תְּב֖וּאָתִ֣י] e-em-todo-');
INSERT INTO verses VALUES (13605, 18, 31, 13, 'se [מִשְׁפַּ֣ט] juízo [וַאֲמָתִ֑י] [בְּ֝רִבָ֗ם] comigo');
INSERT INTO verses VALUES (13606, 18, 31, 14, '[וּמָ֣ה] [אֶֽ֭עֱשֶׂה] porque El e-quando [אֲשִׁיבֶֽנּוּ]');
INSERT INTO verses VALUES (13607, 18, 31, 15, 'הֲ‍ֽ֝לֹא־ בַ֭בֶּטֶן עֹשֵׂ֣נִי עָשָׂ֑הוּ e-tenha-o-formado um um');
INSERT INTO verses VALUES (13608, 18, 31, 16, 'se eu-retenha de-desejo דָּלִים וְעֵינֵ֖י אַלְמָנָ֣ה eu-comerei');
INSERT INTO verses VALUES (13609, 18, 31, 17, 'e-comerei minha-pão sozinho e-não comeu orfanato de-elas');
INSERT INTO verses VALUES (13610, 18, 31, 18, 'que dos-jovens engorde-me כְּאָב וּמִבֶּ֖טֶן אִמִּ֣י אַנְחֶֽנָּה׃');
INSERT INTO verses VALUES (13611, 18, 31, 19, 'se [א֭וֹבֵד] [מִבְּלִ֣י] [לְב֑וּשׁ] [וְאֵ֥ין] e-não-há [לָאֶבְיֽוֹן]');
INSERT INTO verses VALUES (13612, 18, 31, 20, 'se não בֵרֲכ֣וּנִי וּמִגֵּ֥ז minha-oveça que-eles-ardem');
INSERT INTO verses VALUES (13613, 18, 31, 21, 'se eu-ergui sobre orfanato minha-mão porque eu-ver-ei no-santuário meu-ajuto');
INSERT INTO verses VALUES (13614, 18, 31, 22, 'minha-costa de-sua-mão caia e-meus-ombros de-compra vai-se-fraturar');
INSERT INTO verses VALUES (13615, 18, 31, 23, 'que medo para-mim eternidade El e-de-sua-obra não eu-comerei');
INSERT INTO verses VALUES (13616, 18, 31, 24, 'se ouro ouro como-cisalharia e-vos-derreterei disse meu-bem-aventurado:');
INSERT INTO verses VALUES (13617, 18, 31, 25, 'se eu-auxilho-me porque muito minha-força e-quando grande encontrada minha-mão:');
INSERT INTO verses VALUES (13618, 18, 31, 26, 'se luz que porque ilumina e-lua precioso andou');
INSERT INTO verses VALUES (13619, 18, 31, 27, 'e-foi בַּסֵּ֣תֶר meu-coração וַתִּשַּׁ֖ק mão-de-mim לְפִֽי׃');
INSERT INTO verses VALUES (13620, 18, 31, 28, 'também [עָוֺ֣ן] [פְּלִילִ֑י] [כִּֽי־כִחַ֖שְׁתִּי] porque [מִמָּֽעַל]');
INSERT INTO verses VALUES (13621, 18, 31, 29, 'se [בְּפִ֣יד] [מְשַׂנְאִ֑י] [וְ֝הִתְעֹרַ֗רְתִּי] [כִּֽי־מְצָ֥אוֹ] mal mau');
INSERT INTO verses VALUES (13622, 18, 31, 30, 'e-não dei para-pecar minha-língua pedir- maldição-a sua-alma:');
INSERT INTO verses VALUES (13623, 18, 31, 31, 'se não אָ֭מְרוּ homens-de tenda-minha quem não de-carne-seu não juro-');
INSERT INTO verses VALUES (13624, 18, 31, 32, 'fora-o não יָלִ֣ין estrangeiro-a minhas-portas para-o-caminho [sem-traducao]');
INSERT INTO verses VALUES (13625, 18, 31, 33, 'se [כְאָדָ֣ם] como-homem meus-pesares para-ferver em-meus-acumulados pecado-meu');
INSERT INTO verses VALUES (13626, 18, 31, 34, 'que temerei- multidão multiplicai e-desprezo- famílias me-aborreçam e-eu-odiei não sair-ei abri');
INSERT INTO verses VALUES (13627, 18, 31, 35, 'quem dê לִ֨י ׀ ouviu para-mim eis teve Shaddai יַעֲנֵנִי e-livro escreveu homem ריבי׃');
INSERT INTO verses VALUES (13628, 18, 31, 36, 'se não sobre meu-ombro o-elevar-e-o o-usarei-e-o coroas a-mim');
INSERT INTO verses VALUES (13629, 18, 31, 37, 'número meus-passos o-contarei-e-o como elevado o-aproximarei-e-o');
INSERT INTO verses VALUES (13630, 18, 31, 38, 'se עֲלֵי terra-meu clama-tu e-junto suas-velhas יבכו׃');
INSERT INTO verses VALUES (13631, 18, 31, 39, 'se força-sua comi-eu בְלִי־ prata e-alma seus-maridos diminui-eu');
INSERT INTO verses VALUES (13632, 18, 31, 40, 'debaixo cevada sairá abóbora e-abaixo-de em-hulha na-fogueira [תַּ֝֗מּוּ] palavras-de Iov:');
INSERT INTO chapters VALUES (468, 18, 32, 22);
INSERT INTO verses VALUES (13633, 18, 32, 1, 'e-eles-se-estabeleceram três-de os-homens os-estes de-respostas a que ele ele justo em-seus-olhos');
INSERT INTO verses VALUES (13634, 18, 32, 2, 'e se fez agradável certamente Eliu-a filho-de Barqueil ha-buzi mi-mishpat-ha Ram be-Iiyoab acendeu-se sua-ira sobre tsadoqo sua-alma me-Elohim');
INSERT INTO verses VALUES (13635, 18, 32, 3, 'u-vishloth reiao que-se-irritou sua-ira sobre que não encontraram resposta e-os-acusaram a Iov');
INSERT INTO verses VALUES (13636, 18, 32, 4, 'e-Elihu esperou a Iyyov que porque nós eles nós para-dias');
INSERT INTO verses VALUES (13637, 18, 32, 5, 'E-viu Elihu que não-há resposta em-a-boca três os-homens se encolerizou אַף׃');
INSERT INTO verses VALUES (13638, 18, 32, 6, 'e-ele-respondeu Elihu filho-de Barkael o-desprezado pequeno eu em-dias e-vós idoso sobre assim rastejei e-temi [׀] sabei-que a-vós');
INSERT INTO verses VALUES (13639, 18, 32, 7, 'אָ֭מַרְתִּי dias יְדַבְּרֻ e-muitos dois conhecem חוכמה׃');
INSERT INTO verses VALUES (13640, 18, 32, 8, 'certamente espírito-de ela no-homem e-espírito-de Shaddai ensinar-vos');
INSERT INTO verses VALUES (13641, 18, 32, 9, 'não muitos sabedoria-os e-anciãos entenderão juízo');
INSERT INTO verses VALUES (13642, 18, 32, 10, 'por-isso אָ֭מַרְתִּי ouvido-de li amar-vos-ei sabei também eu');
INSERT INTO verses VALUES (13643, 18, 32, 11, 'eis esperei para-a-palavras-vossas ouvi até [עַֽד־תַּחְקְר֥וּן] até investigareis palavras');
INSERT INTO verses VALUES (13644, 18, 32, 12, 'e-contra-vos entender-ei e-eis não-há para-Eiuov moquichah ooneh amarau de-vós');
INSERT INTO verses VALUES (13645, 18, 32, 13, 'para-que-não toamru matzanaou sabedoria El yidfenou não homem');
INSERT INTO verses VALUES (13646, 18, 32, 14, 'e-não oarakh a-mim מִלִּ֑ין não não אֲשִׁיבֶֽנּוּ׃');
INSERT INTO verses VALUES (13647, 18, 32, 15, 'chatu não eles responderam ainda hewtiku de-eles palavras');
INSERT INTO verses VALUES (13648, 18, 32, 16, 'e-estarei-em-hora porque não que porque estiveram não responderam ainda');
INSERT INTO verses VALUES (13649, 18, 32, 17, 'responderei também eu minha-parte eu-amarei sabei também eu');
INSERT INTO verses VALUES (13650, 18, 32, 18, 'que falarei palavras me-queimou espírito em-minha-barriga');
INSERT INTO verses VALUES (13651, 18, 32, 19, 'eis-a minha-barriga como-vinho não abrirá como-dores novos partirá');
INSERT INTO verses VALUES (13652, 18, 32, 20, 'falarei e-espalhar-se a-mim [שְׂפָתַ֣י] שְׂfַ֣ay e-eu-responder-ei');
INSERT INTO verses VALUES (13653, 18, 32, 21, 'a por-favor levantarei faces de não e-a homem não eu-espreitar-ei');
INSERT INTO verses VALUES (13654, 18, 32, 22, 'que não eu-sei eu-espreitarei como-pequeno ele-me-levantará fazendo-me');
INSERT INTO chapters VALUES (469, 18, 33, 33);
INSERT INTO verses VALUES (13655, 18, 33, 1, 'vé-ulam shema- por-favor Iov מִלָּ֑י e-todo minhas-palavras ouvi-a-vós:');
INSERT INTO verses VALUES (13656, 18, 33, 2, 'eis-que- por-favor abri-ei פִ֑י falei-a minha-língua em-minha-gengiva:');
INSERT INTO verses VALUES (13657, 18, 33, 3, 'justiça- לִבִּ֥י minhas-palavras וְדַ֥עַת meus-lábios [מִלֵּֽלוּ] palavras-vos:');
INSERT INTO verses VALUES (13658, 18, 33, 4, 'espírito-de El fez-me e-espírito-de Shaddai te-viva-me');
INSERT INTO verses VALUES (13659, 18, 33, 5, 'se pode retorna-me ordem-te perante-mim estabelece-te');
INSERT INTO verses VALUES (13660, 18, 33, 6, 'eis eu de-tua-boca para-o-Elohim de-o-cimento cortei-eu também eu');
INSERT INTO verses VALUES (13661, 18, 33, 7, 'eis medo-meu não solicitação-teu e-minha-responsabilidade em-você não seja-grave');
INSERT INTO verses VALUES (13662, 18, 33, 8, 'mas disseste בְאָזְנָ֑י e-voz palavras ouvi');
INSERT INTO verses VALUES (13663, 18, 33, 9, 'puro eu sem pecado limpo eu e-não עָוֺ֣ן para-mim');
INSERT INTO verses VALUES (13664, 18, 33, 10, 'eis transgressões sobre-mim encontrará contará-me para-inimigo a-ele');
INSERT INTO verses VALUES (13665, 18, 33, 11, 'põe-o em-a caminhos-meus guarda-o todo caminhos-meu');
INSERT INTO verses VALUES (13666, 18, 33, 12, 'eis isto não justificaste-te responder-eu-te porque multiplicar-se-á אֱ֝לוֹהַ desde-homem');
INSERT INTO verses VALUES (13667, 18, 33, 13, '[מַ֭דּוּעַ] a-ele [רִיב֑וֹתָ] que todo não não');
INSERT INTO verses VALUES (13668, 18, 33, 14, 'porque com-uma YEDABER- não e-em-dois não será-justificada:');
INSERT INTO verses VALUES (13669, 18, 33, 15, 'em-sonho-separador visão noite בִּנְפֹ֣ל sono sono-profundo homens em-sonhos sobre de-cama-ponto');
INSERT INTO verses VALUES (13670, 18, 33, 16, 'então revelará o-ouvido homens e-em-seus-ensinamentos selará-ponto');
INSERT INTO verses VALUES (13671, 18, 33, 17, 'para-retirar homem ato e-costa de-homem o-ocultará');
INSERT INTO verses VALUES (13672, 18, 33, 18, 'restringirá sua alma de-mim a-abiss e-seu-animal de-passo no-remanso');
INSERT INTO verses VALUES (13673, 18, 33, 19, 'e-será-provado em-dor sobre de-seu-deitar ossos-seus e-tendo');
INSERT INTO verses VALUES (13674, 18, 33, 20, 'e-sua-imundície sua-fome pão vén-na-fshe-wo alimento desejo');
INSERT INTO verses VALUES (13675, 18, 33, 21, 'pode carne-seu de-meu-vizinho ossos-seus não vejam-vos-');
INSERT INTO verses VALUES (13676, 18, 33, 22, 'e-se-aproximou לַשַּׁחַת sua-alma e-de-sua-vida para-os-mortos-');
INSERT INTO verses VALUES (13677, 18, 33, 23, 'se ha sobre-ele- anjo- mediador- um de-mim mil para-dizer- le''adam sua-retidão-');
INSERT INTO verses VALUES (13678, 18, 33, 24, 'e-o-abençoou E-disse peda-e-hu me-redet shachat encontrei koper');
INSERT INTO verses VALUES (13679, 18, 33, 25, 'rutafash carne-seu min-noar yashuv li-yeme alumav');
INSERT INTO verses VALUES (13680, 18, 33, 26, 'yeatar a Elohim e-o-queria E-viu em-seus-pânis em trombetas ele-assentou-se [לֶ֝אֱנ֗וֹשׁ] tsevkat-o');
INSERT INTO verses VALUES (13681, 18, 33, 27, '[יָשֹׁ֤ר] sobre אֲנָשִׂים E-disse chataati e-yashar heeviti e-não [לִֽי] a-mim');
INSERT INTO verses VALUES (13682, 18, 33, 28, 'resgatou de-passageiro em-o-inferno na-luz você-ver-irá');
INSERT INTO verses VALUES (13683, 18, 33, 29, 'eis todo אֵ֭לֶּה ele-resgatará- El duas-vezes eis com homem:');
INSERT INTO verses VALUES (13684, 18, 33, 30, 'para-retornar sua alma de-mim inferno para-a-luz a-vida a-vida');
INSERT INTO verses VALUES (13685, 18, 33, 31, 'o-escuta Iov ouve: a-mim o-que-silencia e-eu אֲדַבֵּֽר׃');
INSERT INTO verses VALUES (13686, 18, 33, 32, 'se ha de-palavras responde-me palavra porque quis-eu justifica-te');
INSERT INTO verses VALUES (13687, 18, 33, 33, 'se tu tu ouve: a-mim o-que-silencia e-e-ninho-te חוכמה׃');
INSERT INTO chapters VALUES (470, 18, 34, 37);
INSERT INTO verses VALUES (13688, 18, 34, 1, 'e-respondeu Elihu E-disse');
INSERT INTO verses VALUES (13689, 18, 34, 2, 'ouvi sabios מִלָּ֑י e-sabedores הַאֲזִ֥ינוּ para-mim');
INSERT INTO verses VALUES (13690, 18, 34, 3, 'porque ouvido palavras examinarás e-o-sabor ele-provará para-comer');
INSERT INTO verses VALUES (13691, 18, 34, 4, 'mishpat foi-eleita- nós sabedoria entre-nós que- bom');
INSERT INTO verses VALUES (13692, 18, 34, 5, 'porque disse Iov justifiquei-me e-a hésir מִשְׁפָּטִֽי׃');
INSERT INTO verses VALUES (13693, 18, 34, 6, 'sobre meu-julgamento a-enganarei o-anush meu-arco בְלִי־ transgredir-.');
INSERT INTO verses VALUES (13694, 18, 34, 7, 'quem [כְּאִיּ֑וֹב] [יִֽשְׁתֶּה־לַּ֥עַג] [כַּמָּֽיִם]');
INSERT INTO verses VALUES (13695, 18, 34, 8, 'e-fará-caminho para-a-amizade com Paoloֵי iniquidade e-para-andar com homens de res-he');
INSERT INTO verses VALUES (13696, 18, 34, 9, 'porque não não viverá- Geber em-o-susseito-dele com Elohim');
INSERT INTO verses VALUES (13697, 18, 34, 10, 'por-tanto homens-de coração- ouçam para-mim que-não-seja a-o-elohim de-res-he e-shaday de-iniquidade');
INSERT INTO verses VALUES (13698, 18, 34, 11, 'que feito homem yešallêm- a-ele e-ao-modo-de-caminho homem encontrará-no');
INSERT INTO verses VALUES (13699, 18, 34, 12, 'também verdadeiramente El não condenará וְ֝שַׁדַּ֗י não fará-enganoso juízo');
INSERT INTO verses VALUES (13700, 18, 34, 13, 'quem visitará sobre-ele terra e-quem nome mundo toda-a');
INSERT INTO verses VALUES (13701, 18, 34, 14, 'se a-ele a-ele no seu coração seu-sopro a-ele para-ele reunirá');
INSERT INTO verses VALUES (13702, 18, 34, 15, 'se-fatiga todo em-a-carne juntamente וְ֝אָדָ֗ם sobre poeira ישוב׃');
INSERT INTO verses VALUES (13703, 18, 34, 16, 'e-se com-entendimento de-audição à-voz-de הַ֝אֲזִ֗ינָה à-voz-de palavras-meus');
INSERT INTO verses VALUES (13704, 18, 34, 17, 'o-nariz odeia de-justiça ele-prenderá e-se justo grande condenar-');
INSERT INTO verses VALUES (13705, 18, 34, 18, 'o-dizer como-rei Belial רָשָׁע a príncipes-');
INSERT INTO verses VALUES (13706, 18, 34, 19, 'que não evar-llevar face-de sarim e-não conhecido- grito diante-de pobre porque obra-de suas-mãos כלם׃');
INSERT INTO verses VALUES (13707, 18, 34, 20, 'momento-e morram- e-meio noite noite povo e-passarão e-lançarão forte não não');
INSERT INTO verses VALUES (13708, 18, 34, 21, 'porque עֵ֭ינָיו sobre caminhos- homem e-todo de-seus-passos vere-:');
INSERT INTO verses VALUES (13709, 18, 34, 22, 'não-há escuridão e-não-há tsalma''vet para-se-esconder nome Paoloֵי iniquidade');
INSERT INTO verses VALUES (13710, 18, 34, 23, 'que não sobre homem יָשִׂ֣ים ainda -la-ha-lo-kh a El no juízo');
INSERT INTO verses VALUES (13711, 18, 34, 24, 'fará-dano grandes não inquirição e-estabeleceu outros תַּחְתָּֽם׃');
INSERT INTO verses VALUES (13712, 18, 34, 25, 'portanto conhecerá de-seus-trabalhos e-voltará noite e-os-destruirão-verso-final');
INSERT INTO verses VALUES (13713, 18, 34, 26, 'debaixo-de os ímpios de-seus-duvidas בִּמְק֥וֹם os-que-vêem-verso-final');
INSERT INTO verses VALUES (13714, 18, 34, 27, 'que sobre כֵּ֭ן desviaram-se de-após-ele não seus-caminhos não entenderam');
INSERT INTO verses VALUES (13715, 18, 34, 28, 'לְהָבִ֣יא עָ֭לָיו clama-da דל e-clama-da pobres será ouvido:');
INSERT INTO verses VALUES (13716, 18, 34, 29, 'e-ele acalma e-quem condena e-esconderá face e-quem endireitará-o e-sobre nação e-sobre homem juntos');
INSERT INTO verses VALUES (13717, 18, 34, 30, 'de-reinar homem hipócrita מִמֹּ֥קְשֵׁי povo');
INSERT INTO verses VALUES (13718, 18, 34, 31, 'porque a El não evoquei não eu-arrancarei');
INSERT INTO verses VALUES (13719, 18, 34, 32, 'sem eu-vi tu ensina-me se injustiça não não acrescentarei');
INSERT INTO verses VALUES (13720, 18, 34, 33, 'do-teu-interno pagarão-a porque rejeitaste porque tu escolherás e-não eu e-que yadathta palavra');
INSERT INTO verses VALUES (13721, 18, 34, 34, 'homens-de coração dirão a-mim e-homem sábio ouviu para-mim');
INSERT INTO verses VALUES (13722, 18, 34, 35, 'Iyyov não com-o-conhecimento dirá não não no-entendimento');
INSERT INTO verses VALUES (13723, 18, 34, 36, 'pai-meu examinará Iov até eternamente sobre respostas em-homens- iniquidade');
INSERT INTO verses VALUES (13724, 18, 34, 37, 'que acrescentará sobre pecado-suo transgressao בֵּינֵ֣ינוּ ele-se-aproximara e-multiplicara palavras-sus Lael');
INSERT INTO chapters VALUES (471, 18, 35, 16);
INSERT INTO verses VALUES (13725, 18, 35, 1, 'e-respondeu a-ele E-disse');
INSERT INTO verses VALUES (13726, 18, 35, 2, 'esta? pensaste [לְמִשְׁפָּ֑ט] disseras justiça-meu de-El');
INSERT INTO verses VALUES (13727, 18, 35, 3, 'porque dizes que escarnecer-me para-ti que ajudo de-perversidade-meu');
INSERT INTO verses VALUES (13728, 18, 35, 4, 'Eu restituirei-te מִלִּ֑ין e-a amigo-tu contigo');
INSERT INTO verses VALUES (13729, 18, 35, 5, 'הבט céus e-vê-se e-vigia céus elevaram-se מִמֶּֽךָּ׃');
INSERT INTO verses VALUES (13730, 18, 35, 6, 'se pecaste que farás nele e-ajuntar-se-ão de-tus-pesados que- farás- para-ele');
INSERT INTO verses VALUES (13731, 18, 35, 7, 'se justificaste-te que tu-darás a-ele ou que- da tua mão pegará;');
INSERT INTO verses VALUES (13732, 18, 35, 8, 'לאיש- como-a-to de-tu-mal e-de-branco homem צִדְקָתֶֽךָ׃');
INSERT INTO verses VALUES (13733, 18, 35, 9, 'de-vido-a esmagados chamem roguem do-braço muitos');
INSERT INTO verses VALUES (13734, 18, 35, 10, 'e-não disse onde-está Eloah fazendo-o deu hinos na-noite');
INSERT INTO verses VALUES (13735, 18, 35, 11, 'nosso-mal das-estábulos terra e-me-óf os-céus [יְחַכְּמֵֽנוּ]');
INSERT INTO verses VALUES (13736, 18, 35, 12, 'nome clamem e-não responderá de-diante-de orgulho maus');
INSERT INTO verses VALUES (13737, 18, 35, 13, 'somente vaidade não será-ouvido El não não será-justificada:');
INSERT INTO verses VALUES (13738, 18, 35, 14, 'certamente porque não não responder-lhe juízo perante-ele a-ele a-ele');
INSERT INTO verses VALUES (13739, 18, 35, 15, 'e-agora porque não-há visitar sua-ira e-não muito na-ruína muito');
INSERT INTO verses VALUES (13740, 18, 35, 16, 'e-Iov הֶבֶל espalhar- פִּ֑יהוּ em-bilí- conhecimento palavras multiplicará;');
INSERT INTO chapters VALUES (472, 18, 36, 33);
INSERT INTO verses VALUES (13741, 18, 36, 1, 'e-continuou Elihu E-disse');
INSERT INTO verses VALUES (13742, 18, 36, 2, 'como- a-mim pequeno que porque ainda para-o-elohim palavras;');
INSERT INTO verses VALUES (13743, 18, 36, 3, 'levantarei conheça para-o-longe e-para-a-trabalho-meu darei- צֶֽדֶק׃');
INSERT INTO verses VALUES (13744, 18, 36, 4, 'porque אָ֭מְנָם não MENTIRA מִלָּ֑י perfeitos conhecimentos contigo');
INSERT INTO verses VALUES (13745, 18, 36, 5, 'eis El grande e-não rejeitará grande força- coração');
INSERT INTO verses VALUES (13746, 18, 36, 6, 'não יְחַיֶּ֥ה ímpio משפט pobres dê');
INSERT INTO verses VALUES (13747, 18, 36, 7, 'não retire [עֵ֫ינָ֥יו] seus-olhos e-a reis para-o-trono e-os-assentou לָ֝נֶ֗צַח e-os-elevaram');
INSERT INTO verses VALUES (13748, 18, 36, 8, 'e-se amarrados nos-escudos serão-capturados com-cordas-de עֹֽנִי׃');
INSERT INTO verses VALUES (13749, 18, 36, 9, 'e-anunciou a-eles [פָּעֳלָ֑ם] [וּ֝פִשְׁעֵיהֶ֗ם] que [יִתְגַּבָּֽרוּ]');
INSERT INTO verses VALUES (13750, 18, 36, 10, '[וַיִּ֣גֶל] [אָ֭זְנָם] [לַמּוּסָ֑ר] E-disse porque [מֵאָֽוֶן]');
INSERT INTO verses VALUES (13751, 18, 36, 11, 'se [וְֽיַעֲ֫בֹ֥דוּ] [יְכַלּ֣וּ] se-completarão os-seus-dias em-o-bom e-os-seus-anos nos-nobres');
INSERT INTO verses VALUES (13752, 18, 36, 12, 'e-se não ouvirão em-o-envio passarão e-se-fatigarão conforme- דָֽעַת׃');
INSERT INTO verses VALUES (13753, 18, 36, 13, 'e-os-hipócritas coração porão não não que porque os-seus-vassalos-verso');
INSERT INTO verses VALUES (13754, 18, 36, 14, 'morras na-adolescência almas e-os-seus-vivos nas-santos-verso');
INSERT INTO verses VALUES (13755, 18, 36, 15, 'ele-libertará afligido em-seu-necessidade-acento e-ele-espalhará [בַּלַּ֣חַץ] ouvido-deles-verso-final');
INSERT INTO verses VALUES (13756, 18, 36, 16, 'ואַף [הֲסִיתְךָ֨] [׀] [מִפִּי־צָ֗ר] [רַ֭חַב] não [תַּחְתֶּ֑יהָ] תַּחְתֶּ֑יהָ e-Nachat [מָ֣לֵא] enchei [sem-traducao]');
INSERT INTO verses VALUES (13757, 18, 36, 17, '[וְדִין־רָשָׁ֥ע] rashá maleáta dín úmishpát yitmochoû');
INSERT INTO verses VALUES (13758, 18, 36, 18, 'porque ira para-que-não yesítecha besápeq וְרָב־ kópefer a yatécha');
INSERT INTO verses VALUES (13759, 18, 36, 19, 'hayaáróch salva-te não em-o-angústia e-tudo [מַאֲמַצֵּי־כֹֽחַ] poder');
INSERT INTO verses VALUES (13760, 18, 36, 20, 'a a-noite a-noite para-subir povos תַּחְתָּֽם׃');
INSERT INTO verses VALUES (13761, 18, 36, 21, 'cuidado a vira-te a iniquidade porque sobre ze escolheste de-pobreza');
INSERT INTO verses VALUES (13762, 18, 36, 22, 'eis El eleva quem quem como-ele mestre-:');
INSERT INTO verses VALUES (13763, 18, 36, 23, 'quem visitar sobre-ele caminho dele ומי- disse fizeste avareza:');
INSERT INTO verses VALUES (13764, 18, 36, 24, 'macho porque eleva seu-trabalho que dominam homens');
INSERT INTO verses VALUES (13765, 18, 36, 25, 'todo homem viram- nele הָנוֹשׁ olhará de-longe-:');
INSERT INTO verses VALUES (13766, 18, 36, 26, 'eis El eleva e-não nódoa de-número sua-idade e-não חֵֽקֶר׃');
INSERT INTO verses VALUES (13767, 18, 36, 27, 'que cortará gotas-de águas ferirão chuva para-seu-juízo');
INSERT INTO verses VALUES (13768, 18, 36, 28, 'que derramarão céus irrafu al-ei- homem muito');
INSERT INTO verses VALUES (13769, 18, 36, 29, 'certamente se yabin mifreshei- עָ֑ב teshauot sukkato');
INSERT INTO verses VALUES (13770, 18, 36, 30, 'eis parash sobre-ele oroho o-mar ha-yam cobriu-se');
INSERT INTO verses VALUES (13771, 18, 36, 31, 'porque bam ele-julgará עַמִּ֑ים ele dará אֹ֥כֶל para-aumentar;');
INSERT INTO verses VALUES (13772, 18, 36, 32, 'sobre mãos; E-ordenou luz e-ele-comandou; עָלֶיהָ em-toque;');
INSERT INTO verses VALUES (13773, 18, 36, 33, 'dirá sobre-ele amigo; rebanho; certamente sobre subindo;');
INSERT INTO chapters VALUES (473, 18, 37, 24);
INSERT INTO verses VALUES (13774, 18, 37, 1, 'também para-esta; ele-treme; meu-coração e-ele-se-aproxima מִמְּקוֹמֽוֹ׃');
INSERT INTO verses VALUES (13775, 18, 37, 2, 'ouvi שָׁמ֣וֹעַ em-ira de-sua-voz e-o-murmúrio de-seu-boca saira');
INSERT INTO verses VALUES (13776, 18, 37, 3, 'debaixo-de todo os-céus ele-ordenará-a-ele a-terra sobre a-terra a-terra');
INSERT INTO verses VALUES (13777, 18, 37, 4, 'atrás-dele ele-gritará voz ele-terrorizará com-voz de-sua-gloria e-não Yeqabbem porque יִשָּׁמַ֥ע sua-voz:');
INSERT INTO verses VALUES (13778, 18, 37, 5, 'yarreem El be-qolo niflaot fez gedolot e-não nedaa');
INSERT INTO verses VALUES (13779, 18, 37, 6, 'que la-sheleg dará-dize havvee terra ve-geshem matar e-o-geshem de-mitrot o-uzzo');
INSERT INTO verses VALUES (13780, 18, 37, 7, 'por-mão-de todo para-conhecer yachtom le-daat todo homens-de maasehu');
INSERT INTO verses VALUES (13781, 18, 37, 8, 'e-veio vivente be-mo- arev u-bimeonoteha [sem-traducao]');
INSERT INTO verses VALUES (13782, 18, 37, 9, 'de o-cômodo תָּב֣וֹא tempestade e-de-mezarim aconteceu');
INSERT INTO verses VALUES (13783, 18, 37, 10, 'de-nishmat- El dê águas e-largura águas em-mutzak');
INSERT INTO verses VALUES (13784, 18, 37, 11, 'também meu-amigo dar-se-trabalho עָ֑ב espalhar nuvem אוֹרֽוֹ׃');
INSERT INTO verses VALUES (13785, 18, 37, 12, 'e-ele em-si-bo-th de-te-ha-fekh le-pa-a-lam todo que yetzav-em sobre face-de tevel para-terra');
INSERT INTO verses VALUES (13786, 18, 37, 13, 'se le-shevet se le-ar-tzo se le-che-se-d ya-metz-e-hu');
INSERT INTO verses VALUES (13787, 18, 37, 14, 'הַאֲזִ֣ינָה isto i-yov ficou-em-pé e-refl-considera maravilhosas El');
INSERT INTO verses VALUES (13788, 18, 37, 15, 'se-sabes em-o-veneno-de Eloah sobre-eles luz luz עֲנָנֽוֹ׃');
INSERT INTO verses VALUES (13789, 18, 37, 16, 'se-sabes sobre de-a-carne-de עָ֑ב de-maravilhas perfeitos sábios');
INSERT INTO verses VALUES (13790, 18, 37, 17, 'que em-teus-vestidos calor terra terra do-sul');
INSERT INTO verses VALUES (13791, 18, 37, 18, 'batente [עִ֭מּוֹ] aos-céus fortes como-eu fundido');
INSERT INTO verses VALUES (13792, 18, 37, 19, 'nos-diga que a-ele a-ele nossa que escuridão');
INSERT INTO verses VALUES (13793, 18, 37, 20, 'que-se-contem- que eu falar se disse que porque será-devorado׃');
INSERT INTO verses VALUES (13794, 18, 37, 21, 'e-agora não não luz luz ele ele ואורח e-Espírito-de e-as-purificouː');
INSERT INTO verses VALUES (13795, 18, 37, 22, 'do-norte ouro ele-virá sobre Elohim terrível glória׃');
INSERT INTO verses VALUES (13796, 18, 37, 23, 'Shaddai não encontramos-no grande- força não e-muitos- צְ֝דָקָה não responderá-');
INSERT INTO verses VALUES (13797, 18, 37, 24, 'לָ֭כֵן o-temerão homens não -terá-o todo sabedoria- coração');
INSERT INTO chapters VALUES (474, 18, 38, 41);
INSERT INTO verses VALUES (13798, 18, 38, 1, 'e-respondeu- yhwh a Iyyov E-disse');
INSERT INTO verses VALUES (13799, 18, 38, 2, 'quem זֶ֨ה ׀ persigui-lo etza -com-palavras be-li- דָֽעַת׃');
INSERT INTO verses VALUES (13800, 18, 38, 3, 'cinto-se- por-favor como-homem teu-manto e-perguntarei-te e-me-diga-');
INSERT INTO verses VALUES (13801, 18, 38, 4, 'onde- estavas- em-o-fundamento-meu- terra a-novidade se yadathta com-inteligência-');
INSERT INTO verses VALUES (13802, 18, 38, 5, 'quem nome que porque sabes- ou quem na-tah עָלֶיהָ mede-');
INSERT INTO verses VALUES (13803, 18, 38, 6, 'sobre o-que- seu-mestre os-afogaram ou pedra lançou pedra virou-a');
INSERT INTO verses VALUES (13804, 18, 38, 7, 'bramou- יַ֭חַד estrelas-de manhã e-viraram todo filhos-de Elohim');
INSERT INTO verses VALUES (13805, 18, 38, 8, 'e-sacrificou com-mãos-de mar em-grito-seu do-ventre saira');
INSERT INTO verses VALUES (13806, 18, 38, 9, 'em-sua-escrita עָנָ֣ן para-seu-vestiário e-trevas sua-cobertura');
INSERT INTO verses VALUES (13807, 18, 38, 10, 'e-eu-parti sobre-ele seu-decreto e-eu-fiz em-ferrolho e-portas');
INSERT INTO verses VALUES (13808, 18, 38, 11, 'e-disse até aqui você-virá e-não tornar-a-mais e-por- ele-soltará בִּגְא֥וֹן teus-vómitos');
INSERT INTO verses VALUES (13809, 18, 38, 12, 'de-tuas-dias tu-ordenaste manhã de seu lugar');
INSERT INTO verses VALUES (13810, 18, 38, 13, 'para-agarrar-se nas-asas a-terra e-serão-removidos de-elas');
INSERT INTO verses VALUES (13811, 18, 38, 14, 'você-se-virará como-areia emblema e-eles-se-posicionarão como para-vestiário');
INSERT INTO verses VALUES (13812, 18, 38, 15, 'e-ele-será-impedido אורָם e-braco elevada que-se-partirá');
INSERT INTO verses VALUES (13813, 18, 38, 16, 'se-você-trouxe até lágrimas-de mar e-em-inquérito abismo andastes-vos-');
INSERT INTO verses VALUES (13814, 18, 38, 17, 'se-revelaram a-ti portas-de morte e-portas-de trevas você-ver-irá');
INSERT INTO verses VALUES (13815, 18, 38, 18, 'consideraste até largura-de terra a-novidade se yadathta toda-ela');
INSERT INTO verses VALUES (13816, 18, 38, 19, 'qual este a-o-caminho habitará- luz e-a-escuridão qual este de seu lugar');
INSERT INTO verses VALUES (13817, 18, 38, 20, 'que tomarás-no-o a seu-limites e-quando entenderá caminhos-seus casa-dele');
INSERT INTO verses VALUES (13818, 18, 38, 21, 'da''ata porque então nascerás-no-o וּמִסְפַּ֖ר seus-dias muitos');
INSERT INTO verses VALUES (13819, 18, 38, 22, 'trouxe-tu a אֹצְרוֹת neve e-tesouros gelo você-ver-irá');
INSERT INTO verses VALUES (13820, 18, 38, 23, 'que cortei na época de צר לְי֥וֹם guerra e-batalha');
INSERT INTO verses VALUES (13821, 18, 38, 24, 'qual este a-caminho luz luz espalhará קָדִ֣ים sobre terra');
INSERT INTO verses VALUES (13822, 18, 38, 25, 'quem dividido para-a-deriva elevação וְ֝דֶ֗רֶךְ לַחֲזִ֥יז קֹלֽוֹת׃');
INSERT INTO verses VALUES (13823, 18, 38, 26, 'para-ha-mitir sobre terra não homem em-o-deserto não homem em-ele');
INSERT INTO verses VALUES (13824, 18, 38, 27, '[לְהַשְׂבִּ֣יעַ] shoa e-meshoa e-para-hatzmiah motza deshe');
INSERT INTO verses VALUES (13825, 18, 38, 28, 'hayesh pai pai ou quem deu-origem novilhos-de-a orvalho:');
INSERT INTO verses VALUES (13826, 18, 38, 29, 'do-barriga quem sair o-gelo e-cinzento céus quem filhos-dele-verso-final');
INSERT INTO verses VALUES (13827, 18, 38, 30, 'como-pedra águas se-esconderão e-faces-de abismo se-reunirão-verso-final');
INSERT INTO verses VALUES (13828, 18, 38, 31, 'o-te-conecte de-a-adugo-tas como-a-manha ou atrações kasisil você-abra');
INSERT INTO verses VALUES (13829, 18, 38, 32, 'se-você-sairá de-as-estrelas em-seu-tempo e-a-praga sobre בָּנֶ֥יהָ você-consolará');
INSERT INTO verses VALUES (13830, 18, 38, 33, 'haya-daa-ta chu-kho-th céus se ta-shim na-terra na-terra');
INSERT INTO verses VALUES (13831, 18, 38, 34, '[הֲתָרִ֣ים] [לָעָ֣ב] [קוֹלֶ֑ךָ] [וְֽשִׁפְעַת־מַ֥יִם] águas');
INSERT INTO verses VALUES (13832, 18, 38, 35, '[הֽ͏ַתְשַׁלַּ֣ח] [בְּרָקִ֣ים] [וְיֵלֵ֑כוּ] [וְיֹאמְר֖וּ] a-ti [הִנֵּֽנוּ]');
INSERT INTO verses VALUES (13833, 18, 38, 36, 'quem [בַּטֻּח֣וֹת] [חָכְמָ֑ה] sabedoria ou quem deu');
INSERT INTO verses VALUES (13834, 18, 38, 37, 'quem contará [בְּחָכְמָ֑ה] [וְנִבְלֵ֥י] [שָׁ֝מַ֗יִם] quem quem [sem-traducao]');
INSERT INTO verses VALUES (13835, 18, 38, 38, '[בְּצֶ֣קֶת] pó [לַמּוּצָ֑ק] [וּרְגָבִ֥ים] [יְדֻבָּֽקוּ]');
INSERT INTO verses VALUES (13836, 18, 38, 39, '[הֲתָצ֣וּד] [לְלָבִ֣יא] [טָ֑רֶף] [וְחַיַּ֖ת] [כְּפִירִ֣ים] [תְּמַלֵּֽא]');
INSERT INTO verses VALUES (13837, 18, 38, 40, 'porque [בַמְּעוֹנ֑וֹת] [יֵשְׁב֖וּ] [בַסֻּכָּ֣ה] [לְמוֹ־אָֽרֶב]');
INSERT INTO verses VALUES (13838, 18, 38, 41, 'quem fará [לָעֹרֵ֗ב] [צֵ֫יד֥וֹ] porque a El [יְשַׁוֵּ֑עוּ] [יִ֝תְע֗וּ] [לִבְלִי־אֹֽכֶל] comer:');
INSERT INTO chapters VALUES (475, 18, 39, 30);
INSERT INTO verses VALUES (13839, 18, 39, 1, '[הֲיָדַ֗עְתָּ] ética [לֶ֣דֶת] [יַעֲלֵי־סָ֑לַע] סָלַע [אַיָּל֣וֹת] [תִּשְׁמֹֽר] [sem-traducao]');
INSERT INTO verses VALUES (13840, 18, 39, 2, '[תִּסְפֹּ֣ר] [יְרָחִ֣ים] [תְּמַלֶּ֑אנָה] [וְ֝יָדַעְתָּ֗] tempo [לִדְתָּֽנָה]');
INSERT INTO verses VALUES (13841, 18, 39, 3, '[תִּ֭כְרַעְנָה] [יַלְדֵיהֶ֣ן] [תְּפַלַּ֑חְנָה] [חֶבְלֵיהֶ֥ם] [תְּשַׁלַּֽחְנָה]');
INSERT INTO verses VALUES (13842, 18, 39, 4, '[יַחְלְמ֣וּ] [בְ֭נֵיהֶם] [יִרְבּ֣וּ] [בַבָּ֑ר] [יָ֝צְא֗וּ] e-não [לָֽמוֹ]');
INSERT INTO verses VALUES (13843, 18, 39, 5, 'quem enviou bode [וּמֹסְר֥וֹת] [עָ֝ר֗וֹד] quem quem [sem-traducao]');
INSERT INTO verses VALUES (13844, 18, 39, 6, 'que coloquei [בֵית֑וֹ] [וּֽמִשְׁכְּנוֹתָ֥יו] [מְלֵֽחָה]');
INSERT INTO verses VALUES (13845, 18, 39, 7, '[יִ֭שְׂחַק] [לַהֲמ֣וֹן] [קִרְיָ֑ה] [תְּשֻׁא֥וֹת] [נ֝וֹגֵ֗שׂ] não será ouvido:');
INSERT INTO verses VALUES (13846, 18, 39, 8, '[יְת֣וּר] os-montes [מִרְעֵ֑הוּ] e-depois todo [יִדְרֽוֹשׁ] [sem-traducao]');
INSERT INTO verses VALUES (13847, 18, 39, 9, '[הֲיֹ֣אבֶה] [רֵּ֣ים] [עָבְדֶ֑ךָ] se [עַל־אֲבוּסֶֽךָ] sobre');
INSERT INTO verses VALUES (13848, 18, 39, 10, '[הֲ‍ֽתִקְשָׁר־רֵ֭ים] [בְּתֶ֣לֶם] [עֲבֹת֑וֹ] [אִם־יְשַׂדֵּ֖ד] se [אַחֲרֶֽיךָ]');
INSERT INTO verses VALUES (13849, 18, 39, 11, '[הֲֽתִבְטַח־בּ֭וֹ] [כִּי־רַ֣ב] porque muito a-ele [יְגִיעֶֽךָ]');
INSERT INTO verses VALUES (13850, 18, 39, 12, '[הֲתַאֲמִ֣ין] בּ֭וֹ porque [**יָשִׁ֣יב] [זַרְעֶ֑ךָ] reunirá');
INSERT INTO verses VALUES (13851, 18, 39, 13, 'asa-de-o [נֶעֱלָ֑סָה] [אִם־אֶ֝בְרָ֗ה] se [וְנֹצָֽה] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (13852, 18, 39, 14, 'porque [לָאָ֣רֶץ] a-terra [וְֽעַל־עָפָ֥ר] e-sobre poeira [sem-traducao]');
INSERT INTO verses VALUES (13853, 18, 39, 15, '[וַ֭תִּשְׁכַּח] porque [תְּזוּרֶ֑הָ] [וְחַיַּ֖ת] [הַשָּׂדֶ֣ה] [תְּדוּשֶֽׁהָ]');
INSERT INTO verses VALUES (13854, 18, 39, 16, '[הִקְשִׁ֣יחַ] [בָּנֶ֣יהָ] [לְּלֹא־לָ֑הּ] para ela [יְגִיעָ֣הּ] [בְּלִי־פָֽחַד]');
INSERT INTO verses VALUES (13855, 18, 39, 17, 'porque [אֱל֣וֹהַּ] Eloah sabedoria e-não [בַּבִּינָֽה]');
INSERT INTO verses VALUES (13856, 18, 39, 18, '[כָּ֭עֵת] [בַּמָּר֣וֹם] [תַּמְרִ֑יא] [תִּֽשְׂחַ֥ק] [לַ֝סּ֗וּס] [וּלְרֹֽכְבֽוֹ]');
INSERT INTO verses VALUES (13857, 18, 39, 19, '[הֲתִתֵּ֣ן] [לַסּ֣וּס] [גְּבוּרָ֑ה] [הֲתַלְבִּ֖ישׁ] [צַוָּאר֣וֹ] [רַעְמָֽה]');
INSERT INTO verses VALUES (13858, 18, 39, 20, '[הְֽ֭תַרְעִישֶׁנּוּ] [כָּאַרְבֶּ֑ה] [ה֖וֹד] [נַחְר֣וֹ] [אֵימָֽה]');
INSERT INTO verses VALUES (13859, 18, 39, 21, '[יַחְפְּר֣וּ] [בָ֭עֵמֶק] [וְיָשִׂ֣ישׂ] [בְּכֹ֑חַ] [יֵ֝צֵ֗א] [לִקְרַאת־נָֽשֶׁק]');
INSERT INTO verses VALUES (13860, 18, 39, 22, '[יִשְׂחַ֣ק] [לְ֭פַחַד] e-não [יֵחָ֑ת] e-não yashuv que espada');
INSERT INTO verses VALUES (13861, 18, 39, 23, 'עָ֭לָיו [תִּרְנֶ֣ה] [אַשְׁפָּ֑ה] [לַ֖הַב] chániyt [וְכִידֽוֹן]');
INSERT INTO verses VALUES (13862, 18, 39, 24, '[בְּרַ֣עַשׁ] [וְ֭רֹגֶז] [יְגַמֶּא־אָ֑רֶץ] terra e-não [שׁוֹפָֽר] porque');
INSERT INTO verses VALUES (13863, 18, 39, 25, '[בְּדֵ֤י] [שֹׁפָ֨ר] [׀] [יֹ֘אמַ֤ר] [הֶאָ֗ח] [וּֽ֭מֵרָחוֹק] guerra [מִלְחָמָ֑ה] [רַ֥עַם] [שָׂ֝רִים]');
INSERT INTO verses VALUES (13864, 18, 39, 26, '[הֲ‍ֽ֭מִבִּינָ֣תְךָ] [יַֽאֲבֶר־נֵ֑ץ] [יִפְרֹ֖שׂ] [*כנפו] [**כְּנָפָ֣יו]');
INSERT INTO verses VALUES (13865, 18, 39, 27, 'se sobre teu boc [וְ֝כִ֗י] [יָרִ֥ים] [קִנּֽוֹ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (13866, 18, 39, 28, 'pedra [יִ֭שְׁכֹּן] [וְיִתְלֹנָ֑ן] sobre [וּמְצוּדָֽה] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (13867, 18, 39, 29, '[מִשָּׁ֥ם] [חָֽפַר־אֹ֑כֶל] comida [עֵינָ֥יו] [יַבִּֽיטוּ] [sem-traducao]');
INSERT INTO verses VALUES (13868, 18, 39, 30, '[וְאֶפְרֹחָ֥[q]ו] sangue [וּבַאֲשֶׁ֥ר] [חֲ֝לָלִ֗ים] nome ele');
INSERT INTO chapters VALUES (476, 18, 40, 32);
INSERT INTO verses VALUES (13869, 18, 40, 1, '[וַיַּ֖עַן] yhwh a Jó E-disse');
INSERT INTO verses VALUES (13870, 18, 40, 2, '[הֲ֭רֹב] com Shaddai [מוֹכִ֖יחַ] [אֱל֣וֹהַּ] Eloah');
INSERT INTO verses VALUES (13871, 18, 40, 3, 'ויאן Iov a yhwh E-disse');
INSERT INTO verses VALUES (13872, 18, 40, 4, 'eis [קַ֭לֹּתִי] que [אֲשִׁיבֶ֑ךָּ] [יָ֝דִ֗י] coloquei [לְמוֹ־פִֽי]');
INSERT INTO verses VALUES (13873, 18, 40, 5, 'uma [דִּ֭בַּרְתִּי] e-não [אֶֽעֱנֶ֑ה] [וּ֝שְׁתַּ֗יִם] e-não [אוֹסִֽיף׃]');
INSERT INTO verses VALUES (13874, 18, 40, 6, 'e-respondeu- yhwh a Iyyov E-disse');
INSERT INTO verses VALUES (13875, 18, 40, 7, 'cinto-se- por-favor como-homem teu-manto [וְהוֹדִיעֵֽנִי] e-me-diga-');
INSERT INTO verses VALUES (13876, 18, 40, 8, '[הַ֭אַף] [תָּפֵ֣ר] mispati [תַּ֝רְשִׁיעֵ֗נִי] para-que [תִּצְדָּֽק]');
INSERT INTO verses VALUES (13877, 18, 40, 9, 'e-se [כָּאֵ֥ל] [׀] para-ti [וּ֝בְק֗וֹל] [כָּמֹ֥הוּ] [תַרְעֵֽם]');
INSERT INTO verses VALUES (13878, 18, 40, 10, '[עֲדֵ֥ה] por-favor [גָֽא֣וֹן] [וָגֹ֑בַהּ] [וְה֖וֹד] [וְהָדָ֣ר] [תִּלְבָּֽשׁ]');
INSERT INTO verses VALUES (13879, 18, 40, 11, '[הָ֭פֵץ] [עֶבְר֣וֹת] [אַפֶּ֑ךָ] [וּרְאֵ֥ה] todo [וְהַשְׁפִּילֵֽהוּ]');
INSERT INTO verses VALUES (13880, 18, 40, 12, 'viu todo [הַכְנִיעֵ֑הוּ] [וַהֲדֹ֖ךְ] [רְשָׁעִ֣ים] ímpios');
INSERT INTO verses VALUES (13881, 18, 40, 13, '[טָמְנֵ֣ם] [בֶּעָפָ֣ר] juntamente [פְּ֝נֵיהֶ֗ם] [חֲבֹ֣שׁ] [בַּטָּמֽוּן]');
INSERT INTO verses VALUES (13882, 18, 40, 14, 'e-também eu [כִּֽי־תוֹשִׁ֖עַ] a-ti [יְמִינֶֽךָ]');
INSERT INTO verses VALUES (13883, 18, 40, 15, 'eis-que- por-favor [אֲשֶׁר־עָשִׂ֣יתִי] que [חָ֝צִ֗יר] contigo [יֹאכֵֽל]');
INSERT INTO verses VALUES (13884, 18, 40, 16, 'eis por-favor [בְמָתְנָ֑יו] [וְ֝אֹנ֗וֹ] [בִּשְׁרִירֵ֥י] [בִטְנֽוֹ]');
INSERT INTO verses VALUES (13885, 18, 40, 17, '[יַחְפֹּ֣ץ] [זְנָב֣וֹ] [כְמוֹ־אָ֑רֶז] [גִּידֵ֖י] [*פחדו] [**פַחֲדָ֣יו]');
INSERT INTO verses VALUES (13886, 18, 40, 18, '[עֲ֭צָמָיו] [אֲפִיקֵ֣י] [נְחוּשָׁ֑ה] [גְּ֝רָמָ֗יו] [כִּמְטִ֥יל] [בַּרְזֶֽל]');
INSERT INTO verses VALUES (13887, 18, 40, 19, 'ele רֵאשִׁ֣ית caminhos- El [יַגֵּ֥שׁ] [חַרְבּֽוֹ] [sem-traducao]');
INSERT INTO verses VALUES (13888, 18, 40, 20, 'porque [הָרִ֣ים] os-montes [וְֽכָל־חַיַּ֥ת] a-ele e-todo vivente-de [sem-traducao] [sem-traducao] nome');
INSERT INTO verses VALUES (13889, 18, 40, 21, 'debaixo-de [יִשְׁכָּ֑ב] [בְּסֵ֖תֶר] [קָנֶ֣ה] [וּבִצָּֽה]');
INSERT INTO verses VALUES (13890, 18, 40, 22, '[יְסֻכֻּ֣הוּ] [צֶאֱלִ֣ים] [צִֽלֲל֑וֹ] [יְ֝סֻבּ֗וּהוּ] [עַרְבֵי־נָֽחַל]');
INSERT INTO verses VALUES (13891, 18, 40, 23, 'eis [יַעֲשֹׁ֣ק] rio não [יַחְפּ֑וֹז] [יִבְטַ֓ח] porque [כִּֽי־יָגִ֖יחַ] [יַרְדֵּ֣ן] a');
INSERT INTO verses VALUES (13892, 18, 40, 24, '[בְּעֵינָ֥יו] [יִקָּחֶ֑נּוּ] [בְּ֝מֽוֹקְשִׁ֗ים] [יִנְקָב־אָֽף]');
INSERT INTO verses VALUES (13893, 18, 40, 25, '[תִּמְשֹׁ֣ךְ] [לִוְיָתָ֣ן] [בְּחַכָּ֑ה] [וּ֝בְחֶ֗בֶל] [תַּשְׁקִ֥יעַ] [לְשֹׁנֽוֹ]');
INSERT INTO verses VALUES (13894, 18, 40, 26, '[הֲתָשִׂ֣ים] [אַגְמ֣וֹן] [בְּאַפּ֑וֹ] [וּ֝בְח֗וֹחַ] [תִּקּ֥וֹב] [לֶֽחֱיוֹ]');
INSERT INTO verses VALUES (13895, 18, 40, 27, '[הֲיַרְבֶּ֣ה] [אֵ֭לֶיךָ] [תַּחֲנוּנִ֑ים] se ele-falará a-ti');
INSERT INTO verses VALUES (13896, 18, 40, 28, '[הֲיִכְרֹ֣ת] aliança contigo [תִּ֝קָּחֶ֗נּוּ] [לְעֶ֣בֶד] eternidade');
INSERT INTO verses VALUES (13897, 18, 40, 29, '[הֽ͏ַתְשַׂחֶק־בּ֭וֹ] [כַּצִּפּ֑וֹר] [וְ֝תִקְשְׁרֶ֗נּוּ] [לְנַעֲרוֹתֶֽיךָ]');
INSERT INTO verses VALUES (13898, 18, 40, 30, '[יִכְר֣וּ] [עָ֭לָיו] [חַבָּרִ֑ים] [יֶ֝חֱצ֗וּהוּ] entre [כְּֽנַעֲנִֽים]');
INSERT INTO verses VALUES (13899, 18, 40, 31, '[הַֽתְמַלֵּ֣א] [בְשֻׂכּ֣וֹת] [עוֹר֑וֹ] [וּבְצִלְצַ֖ל] [דָּגִ֣ים] cabeça-dele');
INSERT INTO verses VALUES (13900, 18, 40, 32, 'sim- sobre-ele [זְכֹ֥ר] macho [אַל־תּוֹסַֽף] a [sem-traducao]');
INSERT INTO chapters VALUES (477, 18, 41, 26);
INSERT INTO verses VALUES (13901, 18, 41, 1, 'eis [נִכְזָ֑בָה] [הֲגַ֖ם] [אֶל־מַרְאָ֣יו] a');
INSERT INTO verses VALUES (13902, 18, 41, 2, 'não que porque [וּמִ֥י] ele hu ante-mi [sem-traducao]');
INSERT INTO verses VALUES (13903, 18, 41, 3, 'quem [הִ֭קְדִּימַנִי] [וַאֲשַׁלֵּ֑ם] debaixo todo os-céus');
INSERT INTO verses VALUES (13904, 18, 41, 4, '[*לא־**לֽוֹ־אַחֲרִ֥ישׁ] [בַּדָּ֑יו] e-palavra-de [וְחִ֣ין] [עֶרְכּֽוֹ]');
INSERT INTO verses VALUES (13905, 18, 41, 5, 'quem face-de face-de [בְּכֶ֥פֶל] [רִ֝סְנ֗וֹ] quem quem');
INSERT INTO verses VALUES (13906, 18, 41, 6, '[דַּלְתֵ֣י] [פָ֭נָיו] quem [פִתֵּ֑חַ] [סְבִיב֖וֹת] [שִׁנָּ֣יו] [אֵימָֽה]');
INSERT INTO verses VALUES (13907, 18, 41, 7, '[גַּ֭אֲוָה] [אֲפִיקֵ֣י] [מָֽגִנִּ֑ים] [סָ֝ג֗וּר] [חוֹתָ֥ם] [צָֽר]');
INSERT INTO verses VALUES (13908, 18, 41, 8, 'um no-primeiro [יִגַּ֑שׁוּ] e-Espírito-de não virá');
INSERT INTO verses VALUES (13909, 18, 41, 9, 'homem-de [יְדֻבָּ֑קוּ] [יִ֝תְלַכְּד֗וּ] [וְלֹ֣א] e-não');
INSERT INTO verses VALUES (13910, 18, 41, 10, '[עֲ‍ֽ֭טִישֹׁתָיו] [תָּ֣הֶל] luz [וְ֝עֵינָ֗יו] [כְּעַפְעַפֵּי־שָֽׁחַר]');
INSERT INTO verses VALUES (13911, 18, 41, 11, '[מִ֭פִּיו] [לַפִּידִ֣ים] [יַהֲלֹ֑כוּ] [כִּיד֥וֹדֵי] [אֵ֝֗שׁ] [יִתְמַלָּֽטוּ]');
INSERT INTO verses VALUES (13912, 18, 41, 12, '[מִ֭נְּחִירָיו] sairá em-ás [כְּד֖וּד] [נָפ֣וּחַ] [וְאַגְמֹֽן]');
INSERT INTO verses VALUES (13913, 18, 41, 13, 'sua alma [גֶּחָלִ֣ים] [תְּלַהֵ֑ט] [וְ֝לַ֗הַב] de-seu-boca saira');
INSERT INTO verses VALUES (13914, 18, 41, 14, '[בְּֽ֭צַוָּארוֹ] [יָלִ֣ין] [עֹ֑ז] [וּ֝לְפָנָ֗יו] [תָּד֥וּץ] [דְּאָבָֽה]');
INSERT INTO verses VALUES (13915, 18, 41, 15, '[מַפְּלֵ֣י] [בְשָׂר֣וֹ] [דָבֵ֑קוּ] [יָצ֥וּק] [עָ֝לָ֗יו] não');
INSERT INTO verses VALUES (13916, 18, 41, 16, 'no seu coração יָצ֣וּק como pedra [כְּפֶ֣לַח] [תַּחְתִּֽית] inferiores');
INSERT INTO verses VALUES (13917, 18, 41, 17, '[מִ֭שֵּׂתוֹ] ya-guru elohimes [מִ֝שְּׁבָרִ֗ים] [יִתְחַטָּֽאוּ]');
INSERT INTO verses VALUES (13918, 18, 41, 18, '[מַשִּׂיגֵ֣הוּ] espada beli arrebataram-se [חֲנִ֖ית] [מַסָּ֣ע] [וְשִׁרְיָֽה]');
INSERT INTO verses VALUES (13919, 18, 41, 19, '[יַחְשֹׁ֣ב] [לְתֶ֣בֶן] barzel [לְעֵ֖ץ] [רִקָּב֣וֹן] נְחוּשָֽׁה׃');
INSERT INTO verses VALUES (13920, 18, 41, 20, 'não [בֶן־קָ֑שֶׁת] filho-de arco [אַבְנֵי־קָֽלַע] foram transformados a-ele pedras-de [sem-traducao]');
INSERT INTO verses VALUES (13921, 18, 41, 21, '[כְּ֭קַשׁ] [נֶחְשְׁב֣וּ] [תוֹתָ֑ח] [וְ֝יִשְׂחַ֗ק] [לְרַ֣עַשׁ] [כִּידֽוֹן]');
INSERT INTO verses VALUES (13922, 18, 41, 22, '[תַּ֭חְתָּיו] [חַדּ֣וּדֵי] charesh [יִרְפַּ֖ד] esmaga sobre [sem-traducao]');
INSERT INTO verses VALUES (13923, 18, 41, 23, '[יַרְתִּ֣יחַ] [כַּסִּ֣יר] em-afogamento mar põe-se [כַּמֶּרְקָחָֽה]');
INSERT INTO verses VALUES (13924, 18, 41, 24, '[אַ֭חֲרָיו] Jair [נָתִ֑יב] [יַחְשֹׁ֖ב] abismo [לְשֵׂיבָֽה]');
INSERT INTO verses VALUES (13925, 18, 41, 25, 'não-há sobre poeira [לִבְלִי־חָ[c]ת] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (13926, 18, 41, 26, '[OBJ] todo ele ele-verá hu rei sobre todo filhos-de [sem-traducao]');
INSERT INTO chapters VALUES (478, 18, 42, 17);
INSERT INTO verses VALUES (13927, 18, 42, 1, 'ויאן Iov a yhwh E-disse');
INSERT INTO verses VALUES (13928, 18, 42, 2, 'porque todo [כִּי־כֹ֣ל] e-não [וְלֹא־יִבָּצֵ֖ר] de Ti [מְזִמָּֽה]');
INSERT INTO verses VALUES (13929, 18, 42, 3, 'quem [זֶ֨ה] [׀] [מַעְלִ֥ים] [עֵצָ֗ה] [בְּֽלִ֫י] por-isso [לָכֵ֣ן] e-não [וְלֹ֣א] [אָבִ֑ין] [נִפְלָא֥וֹת] e-não [וְלֹ֣א]');
INSERT INTO verses VALUES (13930, 18, 42, 4, 'ouve: por-favor e-eu eu falar [וְהוֹדִיעֵֽנִי] e-me-diga-');
INSERT INTO verses VALUES (13931, 18, 42, 5, '[לְשֵֽׁמַע־אֹ֥זֶן] [שְׁמַעְתִּ֑יךָ] e-agora [עֵינִ֥י] [רָאָֽתְךָ]');
INSERT INTO verses VALUES (13932, 18, 42, 6, 'sobre [אֶמְאַ֣ס] [וְנִחַ֑מְתִּי] [עַל־עָפָ֥ר] sobre');
INSERT INTO verses VALUES (13933, 18, 42, 7, 'e-houve aḥar palavra yhwh a as-palavras estes E-disse yhwh E-disse yhwh a [אַפִּ֤י] [בְךָ֙] [וּבִשְׁנֵ֣י] appi que não [דִבַּרְתֶּ֥ם] porque não [כְּעַבְדִּ֥י] a-mim [sem-traducao] [sem-traducao] Iov:');
INSERT INTO verses VALUES (13934, 18, 42, 8, 'e-agora [קְחֽוּ־לָכֶ֣ם] para-vós [וְשִׁבְעָ֨ה] [אֵילִ֜ים] [וּלְכ֣וּ] [׀] [אֶל־עַבְדִּ֣י] a servo-meu Jó [בּֽ͏ַעַדְכֶ֔ם] [וְאִיּ֣וֹב] [עַבְדִּ֔י] [יִתְפַּלֵּ֖ל] servo-meu que sobre-vós porque para-não פנאו [עִמָּכֶם֙] para-não que não [דִבַּרְתֶּ֥ם] porque não [כְּעַבְדִּ֥י] a-mim [sem-traducao] [sem-traducao] Iov:');
INSERT INTO verses VALUES (13935, 18, 42, 9, 'Va''yelchu@ [אֱלִיפַ֨ז] [הַתֵּֽימָנִ֜י] [וּבִלְדַּ֣ד] [הַשּׁוּחִ֗י] [צֹפַר֙] [הַנַּ֣עֲמָתִ֔י] וַֽיַּעֲשׂ֔וּ como palavra a-eles yhwh e-levantou yhwh a face-de Iov:');
INSERT INTO verses VALUES (13936, 18, 42, 10, 'e-yhwh retornou a [**שְׁב֣וּת] [אִיּ֔וֹב] através-de companheiro-seu e-acrescentou yhwh yhwh todo que [לְמִשְׁנֶֽה] [sem-traducao]');
INSERT INTO verses VALUES (13937, 18, 42, 11, 'e-vieram a-ele todo [וְכָל־*אחיתיו] e-todo e-todo [לְפָנִ֗ים] [וַיֹּאכְל֨וּ] e comeram pão [בְּבֵיתוֹ֒] [וַיָּנֻ֤דוּ] a-ele a-ele ele sobre sobre todo yhwh que trouxe yhwh sobre-ele e deram- para-ele homem ouro um וְאִ֕ישׁ [sem-traducao] ouro um');
INSERT INTO verses VALUES (13938, 18, 42, 12, 'e-yhwh abençoou a finalidade [מֵרֵאשִׁת֑וֹ] [וַֽיְהִי־ל֡וֹ] quatro lo [אֶ֜לֶף] dez mil [אֲלָפִים֙] e-sesset milhares [בָּקָ֖ר] [וְאֶ֥לֶף] [אֲתוֹנֽוֹת] manhã [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (13939, 18, 42, 13, 'e-foi para-ele filhos filhos [בָּנֽוֹת]');
INSERT INTO verses VALUES (13940, 18, 42, 14, 'E-chamou nome-de a-uma [וְשֵׁ֥ם] e-nome-de a-segunda [וְשֵׁ֥ם] e-nome-de a terceira chifre-de [sem-traducao]');
INSERT INTO verses VALUES (13941, 18, 42, 15, 'e-não [נִמְצָ֜א] mulheres [יָפ֛וֹת] [כִּבְנ֥וֹת] [אִיּ֖וֹב] em-todo E-colocou a-eles [אֲבִיהֶ֛ם] [נַחֲלָ֖ה] no-meio-de em-meio-de irmãos-deles');
INSERT INTO verses VALUES (13942, 18, 42, 16, '[וַיְחִ֤י] [אִיּוֹב֙] depois-de Isto cem e quarenta ano a filhos-dele e-a filhos-de quatro quatro [sem-traducao]');
INSERT INTO verses VALUES (13943, 18, 42, 17, 'E-morreu [אִיּ֔וֹב] velho [וּשְׂבַ֥ע] dias');
INSERT INTO books VALUES (19, 'PSA', 'Salmos', 'AT', 150);
INSERT INTO chapters VALUES (479, 19, 1, 6);
INSERT INTO verses VALUES (13944, 19, 1, 1, 'feliz o-homem que não andar na-conselhos os-malvados e-na-caminho de-perversidade não ficou-em-pé e-no-mespertos de-escarnecedores não habitou');
INSERT INTO verses VALUES (13945, 19, 1, 2, 'que mãe na-lei yhwh seu desejo e na sua toráto יֶהְגֶּ֗ה de-dia e na-noite:');
INSERT INTO verses VALUES (13946, 19, 1, 3, 'e-será como-árvore plantado sobre de-aguas águas que seu-fruto dará em-seu-tempo e-sua-folha não e-tudo e-todo que fará prosperará');
INSERT INTO verses VALUES (13947, 19, 1, 4, 'não assim que porque se espírito que te-dfen-no-u espírito');
INSERT INTO verses VALUES (13948, 19, 1, 5, 'sobre כֵּ֤ן ׀ não ya-qu-mu-u ímpios pelo juízo  e os seus pecados  בַּעֲדַ֥ת צַדּיָקִים׃');
INSERT INTO verses VALUES (13949, 19, 1, 6, 'porque yhwh o-caminho-de caminho justos ve-de-re-kh ímpios to-a-ve-d-sefres');
INSERT INTO chapters VALUES (480, 19, 2, 12);
INSERT INTO verses VALUES (13950, 19, 2, 1, 'לָ֭מָּה ra-g-shu-u gentes e para nações- ye-he-gu-u');
INSERT INTO verses VALUES (13951, 19, 2, 2, 'se-arranjarão- reis-de terra e-poderosos serão-fortes- juntamente sobre yhwh e-sobre');
INSERT INTO verses VALUES (13952, 19, 2, 3, 'n-nat-takah a mo-sero-teimo nós de-mim a-voteimo');
INSERT INTO verses VALUES (13953, 19, 2, 4, 'habitante-de nos-céus yish-chak Adonai se zombará lahem:');
INSERT INTO verses VALUES (13954, 19, 2, 5, 'então falar-á Elohim-lhes em-seu-aspero e-em-suas-fúrias ele-los-asperne-e-exaspere');
INSERT INTO verses VALUES (13955, 19, 2, 6, 'e eu eu-exalcei-me meu-rei sobre tsiyyôn monte-de minha-santa-lócus');
INSERT INTO verses VALUES (13956, 19, 2, 7, 'eu-contarei a חֹ֥ק yhwh disse a-mim filhos-de tu eu o-dia tu-gerarei');
INSERT INTO verses VALUES (13957, 19, 2, 8, 'peça מִמֶּ֗נִּי e-eu-dar-ei nações a tua herança e-eu-posso-te extremidades-de terra');
INSERT INTO verses VALUES (13958, 19, 2, 9, 'tu-espalharás-os com-vara barzel como-instrumento יוצר tu-espalharás-eles');
INSERT INTO verses VALUES (13959, 19, 2, 10, 'e-agora reis h-shkilu huvsru shoftei terra');
INSERT INTO verses VALUES (13960, 19, 2, 11, 'servem a yhwh be-yiraah ve-gilu biradah');
INSERT INTO verses VALUES (13961, 19, 2, 12, 'nasqu- bar para-que-não ye-anaf ve-te-abdhu caminho porque que-arde como-pequena seu-nariz nele todo de-os-defensores nele-verso');
INSERT INTO chapters VALUES (481, 19, 3, 9);
INSERT INTO verses VALUES (13962, 19, 3, 1, 'salmo para-Davi בָּרְח֗וֹ de-diante-de אַבְשׁוֹלְמָה filho-seu');
INSERT INTO verses VALUES (13963, 19, 3, 2, 'yhwh que muitos meus-inimigos muitos levantando-se sobre-mim');
INSERT INTO verses VALUES (13964, 19, 3, 3, 'רַבִּים֮ dizendo para-a-meu-alma não-há sua-salvação para-ele ב-אֱלֹהִים Selá');
INSERT INTO verses VALUES (13965, 19, 3, 4, 'e-tu yhwh escudo-de ב-עֲדִי כּ-בֹודִי ו-מֵרִים');
INSERT INTO verses VALUES (13966, 19, 3, 5, 'a yhwh clamarei e respondeu-me de-har sua-santa-montanha Selá');
INSERT INTO verses VALUES (13967, 19, 3, 6, 'eu שָׁכַ֗בְתִּי e-ãnha acordou-me que yhwh me-sustentará');
INSERT INTO verses VALUES (13968, 19, 3, 7, 'não tenha-temor de-muitas povo que em-torno e-deram');
INSERT INTO verses VALUES (13969, 19, 3, 8, 'levanta-te yhwh salva-me אֱלֹהַי porque tu-atingiste a todo ʾōyevay de-jugo segundo os-maledicentes que-você-partiu');
INSERT INTO verses VALUES (13970, 19, 3, 9, 'para-יהוה a-salvação sobre o-povo-teu bênção-teu selá');
INSERT INTO chapters VALUES (482, 19, 4, 9);
INSERT INTO verses VALUES (13971, 19, 4, 1, 'ao-regente com-música salmo le-david');
INSERT INTO verses VALUES (13972, 19, 4, 2, 'em-chamado-me responde-me Elohim-de justiça-meu em-dificuldade alargaste li a-mim וּשְׁמַ֥ע oração-meu');
INSERT INTO verses VALUES (13973, 19, 4, 3, 'filhos-de homem até o-que glória-meu para-a-escravidão vocês-amem vazio vocês-procurarão mentira sela');
INSERT INTO verses VALUES (13974, 19, 4, 4, 'e saibam porque yhwh yhwh a-ele yhwh yhwh ele-ouvirá a-ele a-ele');
INSERT INTO verses VALUES (13975, 19, 4, 5, 'risai e-a pecareis dizeis no vosso coração sobre de vossos leitos e dormirdes Selá');
INSERT INTO verses VALUES (13976, 19, 4, 6, 'zibchu vossos sacrifícios justica e confiem a yhwh');
INSERT INTO verses VALUES (13977, 19, 4, 7, 'muitos dizendo-os quem- bom bom luz sobre-nos yhwh de-vossas-faces yhwh');
INSERT INTO verses VALUES (13978, 19, 4, 8, 'deste alegria em-meu-corpo-interno des-de-tempo pão-deles e-vinhos-deles muitos-');
INSERT INTO verses VALUES (13979, 19, 4, 9, 'em-paz יַחְדָּו֮ eu-deitar-ei-me e-homem porque yhwh yhwh para-sozinho com-segurança você-me-estabelecerá');
INSERT INTO chapters VALUES (483, 19, 5, 13);
INSERT INTO verses VALUES (13980, 19, 5, 1, 'ao-regente a os-vales salmo le-david');
INSERT INTO verses VALUES (13981, 19, 5, 2, 'palavras-meuas vocês-ouçam yhwh yhwh hagigi');
INSERT INTO verses VALUES (13982, 19, 5, 3, 'ha-kshibah le-qol à-voz-de malchi ve-elohai porque eleyka etpallal');
INSERT INTO verses VALUES (13983, 19, 5, 4, 'yhwh manhã tishma קוֹלִ֑י manhã e-erakh לְ֝ךָ֗ va-atzapeh');
INSERT INTO verses VALUES (13984, 19, 5, 5, 'que não não chafetz res-he tu não não mau');
INSERT INTO verses VALUES (13985, 19, 5, 6, 'não se-estabelecerão desprezados diante-de teus-olhos odiaste todo trabalhadores iniquidade');
INSERT INTO verses VALUES (13986, 19, 5, 7, 'perderás faladores kazav homem sangue e-fraude seja-odioso yhwh');
INSERT INTO verses VALUES (13987, 19, 5, 8, 'e-eu em-multidão Sussana-te eu-entrarei em-a-tua-casa eu-me-prosternarei a palácio- קָ֝דְשְׁךָ֗ em-a-tua-santidade');
INSERT INTO verses VALUES (13988, 19, 5, 9, 'yhwh abençoe-me em-teu-justiça para meus-príncipes ante mim teu-caminho');
INSERT INTO verses VALUES (13989, 19, 5, 10, 'que não-existe em-seu-fioh correta-a interior-eles serem-as tumba- aberta-a garganta-eles língua-deles escarnecerão-os');
INSERT INTO verses VALUES (13990, 19, 5, 11, 'os-acusá-los Elohim cairão de-seus-conselhos em-multidão seus-pecados expulsa-os porque rebelaram-se em-te:');
INSERT INTO verses VALUES (13991, 19, 5, 12, 'e se alegrarão todo os que abrigam em ti para-sempre nos rirão e se esconderão sobre eles e se exultarão em ti que amam Seu nome:');
INSERT INTO verses VALUES (13992, 19, 5, 13, 'porque você-masculino bendeces yhwh yhwh como-canoa razão você-o-coronhar-ás');
INSERT INTO chapters VALUES (484, 19, 6, 11);
INSERT INTO verses VALUES (13993, 19, 6, 1, 'para o vencedor com cânticos sobre a-oitava salmo de-Davi');
INSERT INTO verses VALUES (13994, 19, 6, 2, 'yhwh a com-teu-rancor corrigires-nos e-a em-tua-ira disciplinares-nos;');
INSERT INTO verses VALUES (13995, 19, 6, 3, 'perdoai-me yhwh que estou-afliado eu-sou cura-me yhwh que tremem');
INSERT INTO verses VALUES (13996, 19, 6, 4, 'e a minha alma tremeu-se muito yhwh até yhwh');
INSERT INTO verses VALUES (13997, 19, 6, 5, 'volta-te yhwh desata minha-alma hosana-me para-que Sua misericórdia:');
INSERT INTO verses VALUES (13998, 19, 6, 6, 'que não-há בַּמָּ֣וֶת lembra-te em-a-questão quem confessa- para-ti');
INSERT INTO verses VALUES (13999, 19, 6, 7, 'trabalhei-eu em-o-suspiro-meu esconderei em-todo noite de-a-cama-meu em-a-lágrima-meu ar-seu ame-se');
INSERT INTO verses VALUES (14000, 19, 6, 8, 'ela-dormiu de-ira minha-olho ela-libertou-se em-todo meus-angústios');
INSERT INTO verses VALUES (14001, 19, 6, 9, 'afastem-se de-mi todo seus-trabalhos iniquidade yhwh voz yhwh voz-de choro;');
INSERT INTO verses VALUES (14002, 19, 6, 10, 'ouviu yhwh te-hinat-i yhwh te-filat-i pegará;');
INSERT INTO verses VALUES (14003, 19, 6, 11, 'ye-bo-shu ve-yi-ba-halu muito- muito meus-inimigos voltaram יֵבֹשׁוּ raga:');
INSERT INTO chapters VALUES (485, 19, 7, 18);
INSERT INTO verses VALUES (14004, 19, 7, 1, 'erro para-Davi que rei para-יהוה sobre  דּ-בְרֵי-  cush filho-de benjamita');
INSERT INTO verses VALUES (14005, 19, 7, 2, 'yhwh meu-Elohim bakkha'' tive-temor salva-me de-todo perseguidores-meus e-salve-me');
INSERT INTO verses VALUES (14006, 19, 7, 3, 'para-que-não devore כְּאַרְיֵ֣ה minha-alma separando e-não matsil');
INSERT INTO verses VALUES (14007, 19, 7, 4, 'yhwh Elohim-meu se esta esta se há injustiça em-mãos-minhas');
INSERT INTO verses VALUES (14008, 19, 7, 5, 'se servi-eu mal mau e-eu-estranhei opressor-meu vazios');
INSERT INTO verses VALUES (14009, 19, 7, 6, 'ירַדּוּ inimigo a-minha-alma e-ele-persegue e-ele-esmaga para-a-terra minha vida e-meu-honra para-o-pó faz-estar Selá');
INSERT INTO verses VALUES (14010, 19, 7, 7, 'levanta-te yhwh בְּאַפֶּ֗ךָ e-ele-se-eleva em-nuvens engatinhador-me e-esperta-te אֵ֝לַ֗י mishpat ordenaste');
INSERT INTO verses VALUES (14011, 19, 7, 8, 'e-reunião-de para-povos te-sove-ka וְ֝עָלֶ֗יהָ la-maroym shuva');
INSERT INTO verses VALUES (14012, 19, 7, 9, 'yhwh ya-din amim shef-te-nee yhwh ke-tzidki u-ketummi sobre-mim');
INSERT INTO verses VALUES (14013, 19, 7, 10, 'yigmar- na ruim- reshaim e-fundar tzaddiq e-examinador coraçõ-es e-órgaos Elohim tsaddiq:');
INSERT INTO verses VALUES (14014, 19, 7, 11, 'defenso-re sobre Elohim salva-dor retos- coração');
INSERT INTO verses VALUES (14015, 19, 7, 12, 'Elohim juiz justo e-a ira-do em-todo dia');
INSERT INTO verses VALUES (14016, 19, 7, 13, 'se não voltará sua-espada afiará seu-arco caminho e-o-fundou-a');
INSERT INTO verses VALUES (14017, 19, 7, 14, 'e-ló, ele-preparou objetos-de morte seus-flechados para-acesos irá-feito:');
INSERT INTO verses VALUES (14018, 19, 7, 15, 'eis destruirá- iniquidade e-ela-concebeu trabalho e-dele-nasceu mentira');
INSERT INTO verses VALUES (14019, 19, 7, 16, 'bur cará e cavou-o e caiu em-saht fará');
INSERT INTO verses VALUES (14020, 19, 7, 17, 'ele-voltará seu-trabalho em-seu-cabeça e-sobre sua-testa seu-ira irá:');
INSERT INTO verses VALUES (14021, 19, 7, 18, 'odeh yhwh como-seu-direito  וַ֝אֲזַמְּרָ֗ה  nome-de yhwh altíssimo');
INSERT INTO chapters VALUES (486, 19, 8, 10);
INSERT INTO verses VALUES (14022, 19, 8, 1, 'ao-regente sobre a-gente salmo le-david');
INSERT INTO verses VALUES (14023, 19, 8, 2, 'yhwh nosso-adonai que grande שםך em-todo a-terra que ordem ה֝וֹדְךָ֗ sobre os-céus');
INSERT INTO verses VALUES (14024, 19, 8, 3, 'de-seu meninos- -e-meninas fundaste força para teus-inimigos para-cessar inimigo');
INSERT INTO verses VALUES (14025, 19, 8, 4, 'porque eu-verei -teus-céus trabalhos- dedos-tua -lua e estrelas que estabeleceste');
INSERT INTO verses VALUES (14026, 19, 8, 5, 'que homem porque que e-filho-de homem porque ordenar-lhe');
INSERT INTO verses VALUES (14027, 19, 8, 6, 'e-falta-lhe pouco de-Elohim e-honra e-esplendor e-cinturará-lhe');
INSERT INTO verses VALUES (14028, 19, 8, 7, 'e-dominará-lhe em-o-trabalhos de-tuas-mãos todo beber em-o-baixo-de de-seus-pés');
INSERT INTO verses VALUES (14029, 19, 8, 8, 'ovelha e-milhar כלם também-e em-os-animais Shaddai');
INSERT INTO verses VALUES (14030, 19, 8, 9, 'pássaro céus e-peixes-de o-mar passante mares-verso');
INSERT INTO verses VALUES (14031, 19, 8, 10, 'yhwh nosso-adonai que adiri שִׁ֝מְךָ֗ em-todo a-terra');
INSERT INTO chapters VALUES (487, 19, 9, 21);
INSERT INTO verses VALUES (14032, 19, 9, 1, 'לַ֭מְנַצֵּחַ almut laben salmo le-david');
INSERT INTO verses VALUES (14033, 19, 9, 2, 'odeh yhwh em-todo meu-coração asaprah todo נִפְלְאוֹתֶֽיךָ׃');
INSERT INTO verses VALUES (14034, 19, 9, 3, 'esmehah vee-eweltzah bakh azamrah teu-nome altíssimo');
INSERT INTO verses VALUES (14035, 19, 9, 4, 'quando voltar- meus-inimigos para-trás יִכָּשְׁל֥וּ vey-avadu de-diante-tua');
INSERT INTO verses VALUES (14036, 19, 9, 5, 'porque asita de-mi-shpat e-de-dini jashavta le-kise shofet צֶֽדֶק׃');
INSERT INTO verses VALUES (14037, 19, 9, 6, 'gaartta nações ibaddahta ímpio shemam machita para-sempre ve-ed');
INSERT INTO verses VALUES (14038, 19, 9, 7, 'o-inimigo terminaram ruínas para sempre e cidades abandonaste perdeu-se seu-lembrete eles');
INSERT INTO verses VALUES (14039, 19, 9, 8, 'e-yhwh para-sempre habitou estabelece para-o-julgamento כִּסְאֽוֹ׃');
INSERT INTO verses VALUES (14040, 19, 9, 9, 'e-ele julgará- mundo em-justiça julgará le-ummim');
INSERT INTO verses VALUES (14041, 19, 9, 10, 'e-seja yhwh de-altura para-teu de-alto em-tempo em-tribulação');
INSERT INTO verses VALUES (14042, 19, 9, 11, 'e-confiarão em-você os-conhecedores o-teu-nome que não abandonaste yhwh yhwh');
INSERT INTO verses VALUES (14043, 19, 9, 12, 'cante a-יהוה habitou Sião anuntem em-o-povos feitos-seus');
INSERT INTO verses VALUES (14044, 19, 9, 13, 'porque que-procura sangue macho macho não esqueceu clamor-de');
INSERT INTO verses VALUES (14045, 19, 9, 14, 'tenha-piedade-de-mim yhwh viu minha-pobreza de-seu-inimigo que-me-exalta de-os-portões מָֽוֶת׃');
INSERT INTO verses VALUES (14046, 19, 9, 15, 'para a-Azafia todo tua-louvor-teu em-os-portões filha-de Sião a-Agula em-salvação-tua');
INSERT INTO verses VALUES (14047, 19, 9, 16, 'enterraram nações em-a-ruína asú em-o-princípio-de ז֥וּ esconderam-nos foi-capturada pés-deles-verso');
INSERT INTO verses VALUES (14048, 19, 9, 17, 'não-sei-o yhwh yhwh fez em-trabalho mãos-dele pisca ímpio pensamento Selá');
INSERT INTO verses VALUES (14049, 19, 9, 18, 'voltarão ímpios para-pergunta-la todo nações esquecendo Elohim');
INSERT INTO verses VALUES (14050, 19, 9, 19, 'que não até-sempre será-esquecido pobre corda-de perecerá לָעַֽד׃');
INSERT INTO verses VALUES (14051, 19, 9, 20, 'qumah yhwh a ajudará Enos julgarão goyim sobre teu-rosto');
INSERT INTO verses VALUES (14052, 19, 9, 21, 'posição yhwh instrução para-eles a-eles gentes Enos eles selá');
INSERT INTO chapters VALUES (488, 19, 10, 18);
INSERT INTO verses VALUES (14053, 19, 10, 1, 'לָמָ֣ה yhwh permanecerás de-longe sublimidades para-tempo em-tribulação');
INSERT INTO verses VALUES (14054, 19, 10, 2, 'com-arrogância ímpio ele-será-acesa pobre eles-serão-agarrados em-malditos esta eles-pensaram-verso-final');
INSERT INTO verses VALUES (14055, 19, 10, 3, 'porque ele-louvará ímpio sobre será a minha gula sua-alma e-ele-arrancará abençoou yhwh yhwh');
INSERT INTO verses VALUES (14056, 19, 10, 4, 'רָשָׂע como-alto seu-nariz não ele-procurará nao-ha Elohim todo de-seus-cantares');
INSERT INTO verses VALUES (14057, 19, 10, 5, 'eles-esperarão em-todo tempo alto mishpatêkha em-seu-frente todo seus-opressores ele-soprará neles');
INSERT INTO verses VALUES (14058, 19, 10, 6, 'disse no seu coração não em-o-mot para-geração e-dor que não be-raa');
INSERT INTO verses VALUES (14059, 19, 10, 7, 'ah-la pi-hu enchei ve-mirmot ve-tokh debaixo-de debaixo amal ve-aven');
INSERT INTO verses VALUES (14060, 19, 10, 8, 'yesheb em-o-ma-arav chatsrim ba-mishtarim yaharog נָקִ֑י einoav le-chelkah yitzponu');
INSERT INTO verses VALUES (14061, 19, 10, 9, 'yeerov ba-mishtar ke-aryeh em-a-tenda ele-esconderá para-rapinar pobre ele-rapinará pobre com-seu-traction em-sua-escrita');
INSERT INTO verses VALUES (14062, 19, 10, 10, 'ele-espoliará e-caiu com-seus-poderes');
INSERT INTO verses VALUES (14063, 19, 10, 11, 'disse no seu coração esqueceu El ocultou de-seu-frente não viu para sempre;');
INSERT INTO verses VALUES (14064, 19, 10, 12, 'levanta-te yhwh El eleva teu-mão a esquecerás');
INSERT INTO verses VALUES (14065, 19, 10, 13, 'sobre o-que rejeitado רָשָׁ֥ע ׀ Elohim disse disse não não');
INSERT INTO verses VALUES (14066, 19, 10, 14, 'viu-a porque você trabalho e-ira olhar-a para-dar em-mã-o-teu עלך יַעֲזֹ֣ב parte-seu órfão você tu ozér');
INSERT INTO verses VALUES (14067, 19, 10, 15, 'quebrar braço ímpio e-mal procurar- maldade-seu sem- encontrar-você');
INSERT INTO verses VALUES (14068, 19, 10, 16, 'yhwh rei eternidade וָעֶ֑ד perder-eles goyim de-terra-seu');
INSERT INTO verses VALUES (14069, 19, 10, 17, 'desejo os humildes ouviste yhwh תָּכִ֥ין coração-eles escutar-você ouvido-seu');
INSERT INTO verses VALUES (14070, 19, 10, 18, 'julgares orfanos viúvas não e também ainda para a terra הָאֵ֭נוֹשׁ de a-terra');
INSERT INTO chapters VALUES (489, 19, 11, 7);
INSERT INTO verses VALUES (14071, 19, 11, 1, 'ao-regente para-Davi בְּיַהְוֶה eu me arrependi como vós direis para a minha alma elevai-vos pomba:');
INSERT INTO verses VALUES (14072, 19, 11, 2, 'que eis as injustiças יִדְרְכ֬וּן קֶ֗שֶׁת כּוֹנְנ֣וּ חִצָּ֣ם sobre יֶ֑תֶר לִיר֥וֹת בְּmo֠ אֹ֝֗opel לְyishrei֑ coração');
INSERT INTO verses VALUES (14073, 19, 11, 3, 'que das-muralhas serão-derribados צדיק que- trabalho');
INSERT INTO verses VALUES (14074, 19, 11, 4, 'yhwh na-santa-laje seu-santo yhwh yhwh seu-trono os-seus-olhos eles-viram as-suas-pálpebras eles-examinarão filhos-de homem');
INSERT INTO verses VALUES (14075, 19, 11, 5, 'yhwh צדיק ele-examinará e-o-malvado e-amando חָמָס ódio sua-alma:');
INSERT INTO verses VALUES (14076, 19, 11, 6, 'despenderá sobre maus moedas fogo e-Espírito-de ואורח zil''afot m''nat kosam');
INSERT INTO verses VALUES (14077, 19, 11, 7, 'porque yhwh yhwh ts''daqot amou yashar yechezu paneimo');
INSERT INTO chapters VALUES (490, 19, 12, 9);
INSERT INTO verses VALUES (14078, 19, 12, 1, 'ao-regente sobre hashminit salmo le-david');
INSERT INTO verses VALUES (14079, 19, 12, 2, 'hoshi''a yhwh porque gamar חָסִ֑יד porque passem homem de-filhos-de homem');
INSERT INTO verses VALUES (14080, 19, 12, 3, 'vaidade- dirão homem a seu-amigo beira-de partes com-o-corpo e-com-o-corpo dirão-vos');
INSERT INTO verses VALUES (14081, 19, 12, 4, 'cortará yhwh todo שִׂפְתֵ֣י partes a-língua falando grandes-verso');
INSERT INTO verses VALUES (14082, 19, 12, 5, 'que disseram-separador para-a-nossa-língua exaltaremos nossas-bocas אִתָּ֑נוּ quem quem para-nós');
INSERT INTO verses VALUES (14083, 19, 12, 6, 'do-sedutor pobres-pessoas de-gemidos dos-pobres agora levantarei-me diga yhwh אָשִׁ֥ית em-Yeshua respire a-ele');
INSERT INTO verses VALUES (14084, 19, 12, 7, 'palavras-dele yhwh palavras puras prata forjadas em-pecado La-a-ă-re-ts lavadas setevezes');
INSERT INTO verses VALUES (14085, 19, 12, 8, 'você- yhwh t-sh-m-r-e-m t-ts-r-e-n-u de h-d-o-r z-u para-eternidade');
INSERT INTO verses VALUES (14086, 19, 12, 9, 'ao-redor os ímpios y-t-h-l-ch-u-n k-r-u-m z-u-l-l-u-th para-filhos-de homem');
INSERT INTO chapters VALUES (491, 19, 13, 6);
INSERT INTO verses VALUES (14087, 19, 13, 1, 'ao-regente salmo le-david');
INSERT INTO verses VALUES (14088, 19, 13, 2, 'até yhwh yhwh t-sh-k-h-ch-e-n-i eternamente até a-n-a t-s-t-r a faces-tuas');
INSERT INTO verses VALUES (14089, 19, 13, 3, 'até onde colocarei conselhos em-a-meu-espírito angústia no-meu-coração de-dia até onde יָר֖וּם meu inimigo sobre-mim');
INSERT INTO verses VALUES (14090, 19, 13, 4, 'olhares suspirou yhwh meu-Elohim iluminou minha-olho para-que-não homem-fogo a-morte:');
INSERT INTO verses VALUES (14091, 19, 13, 5, 'para-que-não dirá meu inimigo consumirá-no meus-inimigos que porque mover-eu');
INSERT INTO verses VALUES (14092, 19, 13, 6, 'e-eu em-tuas-caridade eu-me-apelei purificar-se-á meu-coração em-te-sua-saúde eu-ser-ei para-יהוה porque que sobre-mim');
INSERT INTO chapters VALUES (492, 19, 14, 7);
INSERT INTO verses VALUES (14093, 19, 14, 1, 'ao-regente para-Davi disse Nabal no-seu-coração não-há Elohim destroi-los odiaram-no pretexto não-há faz- bom');
INSERT INTO verses VALUES (14094, 19, 14, 2, 'yhwh dos-céus olhou sobre para-ver para-ver há ensinador buscador a Elohim');
INSERT INTO verses VALUES (14095, 19, 14, 3, 'todo o que se afastou com ele foram açoitados não-há faz bom não há também um');
INSERT INTO verses VALUES (14096, 19, 14, 4, 'não יָדְעוּ֮ todo po''alay mal אֹכְלֵ֣י עַ֭מִּי pão yhwh não não קָרָֽאוּ׃');
INSERT INTO verses VALUES (14097, 19, 14, 5, 'שָׁ֤ם ׀ temeram temor porque Elohim na-geração צַדִּיק׃');
INSERT INTO verses VALUES (14098, 19, 14, 6, 'conselho- עָנִ֥י que yhwh yhwh refúgio-seu.');
INSERT INTO verses VALUES (14099, 19, 14, 7, 'quem dará de-cisão salvação Israel em-voltar-se yhwh paz povo-seu purificar-se Jacó alegrar-se Israel');
INSERT INTO chapters VALUES (493, 19, 15, 5);
INSERT INTO verses VALUES (14100, 19, 15, 1, 'salmo para-Davi yhwh quem dormir em-tua-casa quem- habitar em-monte-de Sua santidade:');
INSERT INTO verses VALUES (14101, 19, 15, 2, 'andando integro e-operador justiça e-falando verdade em-o-lar-do-corpo');
INSERT INTO verses VALUES (14102, 19, 15, 3, 'não pé sobre na sua língua não fez para seu próximo maldade e palavra não eles sobre que esteja perto');
INSERT INTO verses VALUES (14103, 19, 15, 4, 'é-desprezado em-os-olhos-seus é-rejeitado e-a temor-de yhwh yekabed jurou para-o-mal e-não Yamar:');
INSERT INTO verses VALUES (14104, 19, 15, 5, 'o-seu-argentum não deu em-nosso וְשֹׁ֥חַד sobre não não tomou não estes não ele-tremula para-eternidade');
INSERT INTO chapters VALUES (494, 19, 16, 11);
INSERT INTO verses VALUES (14105, 19, 16, 1, 'de-secreto para-Davi guarda-me El porque esperançei em-te:');
INSERT INTO verses VALUES (14106, 19, 16, 2, 'disseste לַיהוָה Adonai tu benevolencia-meu não sobre-te');
INSERT INTO verses VALUES (14107, 19, 16, 3, 'para-santos que na-terra elas-eram e-gloriosos todo chéfzí- neles:');
INSERT INTO verses VALUES (14108, 19, 16, 4, 'increvam em-o-suspiros-deles outro precipitaram-se não aspirarás os-sacrifícios-deles de-sangue e-negação- elevarei a shmotam sobre minhas-bocas');
INSERT INTO verses VALUES (14109, 19, 16, 5, 'yhwh parte- meu-partilho tu tu te-mantém meu-goralei');
INSERT INTO verses VALUES (14110, 19, 16, 6, 'cordas caíram- para-mim em-os-namidos também herança melhora em-mim');
INSERT INTO verses VALUES (14111, 19, 16, 7, 'abençoarei a yhwh que a-me-ajudar também em-as-noites me-corrijam minhas-vidas');
INSERT INTO verses VALUES (14112, 19, 16, 8, 'eu-fiz yhwh lě-ne-ga-de-ʾi permanente-mente que de-minha-direita não mover-eu');
INSERT INTO verses VALUES (14113, 19, 16, 9, 'por-tanto alegrado-se meu-coração e-ele-foi-exilado minha-glória também em meu corpo ele-ocupará em segurança');
INSERT INTO verses VALUES (14114, 19, 16, 10, 'que não você-abandona נַפְשִׁ֣י para-pedir não תִתֵּ֥ן para-ver para-ver abismo-verso-final');
INSERT INTO verses VALUES (14115, 19, 16, 11, 'mostrar-me-conhecimento caminho vida sete alegrias a de-teu-rosto delicias em-tua-mão-direita eternidade-verso-final');
INSERT INTO chapters VALUES (495, 19, 17, 15);
INSERT INTO verses VALUES (14116, 19, 17, 1, 'oração para-Davi ouviste yhwh justiça escuta minha voz ouve-te minha-oração sem-a bocas engano');
INSERT INTO verses VALUES (14117, 19, 17, 2, 'diante-te minha-justiça sairá os-teus-olhos verás retos');
INSERT INTO verses VALUES (14118, 19, 17, 3, 'bachantta libbi pakadta noite tsaraphtanu bal- timzata זָמֹיתִי não ya''avar- pi:');
INSERT INTO verses VALUES (14119, 19, 17, 4, 'lif''alut homem em-palavra-de seus lábios eu eu guardei caminhos abriu');
INSERT INTO verses VALUES (14120, 19, 17, 5, 'tu te apoias em minha esperança em teus carros não descansaram minhas mãos');
INSERT INTO verses VALUES (14121, 19, 17, 6, 'eu eu invoquei-te porque responde-me El estende a-tua-ouvido para-mi ouviu minha-palavra');
INSERT INTO verses VALUES (14122, 19, 17, 7, 'maravilha-te bondade-tua salva protege dos-que-se-levantam בִּֽימִינֶֽךָ׃');
INSERT INTO verses VALUES (14123, 19, 17, 8, 'shamareni keishon filha-de olho em-a-sombra כְּ֝נָפֶ֗יךָ tastireni');
INSERT INTO verses VALUES (14124, 19, 17, 9, 'de-diante-de ímpios zu shaduni oyevai benephesh circund-arão sobre-mim');
INSERT INTO verses VALUES (14125, 19, 17, 10, 'sua-gordura fecharam-se seus-lábios falaram em-gloria');
INSERT INTO verses VALUES (14126, 19, 17, 11, 'nossas-alianças agora olhos-deles coloc-arão para-voltar na-terra');
INSERT INTO verses VALUES (14127, 19, 17, 12, 'demônio como-leão esconde-se para-devorar e-leopardo habitou em-segredos');
INSERT INTO verses VALUES (14128, 19, 17, 13, 'levanta-te yhwh avança de-sua-frente derruba-o escap-ou minha-alma do-malvado teu-sabre');
INSERT INTO verses VALUES (14129, 19, 17, 14, 'de-mortos mão-tua yhwh yhwh de-a-horda parte-deles na-vida encherá estômagos-deles satisfarão-se filhos e-lançarão excesso-deles filhos');
INSERT INTO verses VALUES (14130, 19, 17, 15, 'eu na-justiça eu-virei-ver em-tua-mente eu-serei-satisfeita com-o-acordar a-tua-imagem');
INSERT INTO chapters VALUES (496, 19, 18, 51);
INSERT INTO verses VALUES (14131, 19, 18, 1, 'para-aquele-que-maneja para-escravo yhwh yhwh que falar para-yhwh a palavras-de a canção esta no-dia salvou- yhwh o-teu da-mão-de todo os-seus-inimigos e-imediatamente שָׁאוּל');
INSERT INTO verses VALUES (14132, 19, 18, 2, 'E-disse eu-te-tornarei-compassivo yhwh fortalece-te');
INSERT INTO verses VALUES (14133, 19, 18, 3, 'yhwh e-minha-fortaleza e-meu-resgate אֵלִ֣י eu-me-aproximarei-de nele defenso-re e-chifre-de minha-salvação de-meu-altura');
INSERT INTO verses VALUES (14134, 19, 18, 4, 'מְ֭הֻלָּל eu chamar yhwh e-de meus inimigos eu salvo-me;');
INSERT INTO verses VALUES (14135, 19, 18, 5, 'e me soprou cabelos de— morte, e os rios, sem testemunha meus inimigos me engolirem;');
INSERT INTO verses VALUES (14136, 19, 18, 6, 'cheveli sho''al sevavuni qidmuni moqshei מָֽוֶת׃');
INSERT INTO verses VALUES (14137, 19, 18, 7, 'בַּצַּר־ para-mim yhwh yhwh Elohim-meu ora-eu ouvirá de-o-santuário-seu קוֹלִ֑י e-a-oração-meu perante-ele vem na-ouvido-seu');
INSERT INTO verses VALUES (14138, 19, 18, 8, 'e-ele-tremeu e-ele-tremeu a-terra a-terra os-montes tremem e-ele-se-irritou porque foi-irada a-ele');
INSERT INTO verses VALUES (14139, 19, 18, 9, 'subir fumo em-a-sua-nariz e-fogo- de-seu-boca comerás de-carvões de-iradas nós');
INSERT INTO verses VALUES (14140, 19, 18, 10, 'e-ele-esticou céus e desceu e-trevas debaixo pés-seus');
INSERT INTO verses VALUES (14141, 19, 18, 11, 'e-ele-sentinela sobre querubim e voou e-ele-estendeu sobre as asas de espírito');
INSERT INTO verses VALUES (14142, 19, 18, 12, 'põe escuridão- seu-esconderijo em-seus-voltas sua-tenda escuridão-de- águas sedas de brilho');
INSERT INTO verses VALUES (14143, 19, 18, 13, 'de-sua: -diante suas-nuvens passaram-: -chovas: e-chamas-: de-fogo:');
INSERT INTO verses VALUES (14144, 19, 18, 14, 'e-ele-os-fazia-subir no-céus yhwh yhwh dará de-sua-voz em-o-fuligem e-os-carvões-de אֵֽשׁ׃');
INSERT INTO verses VALUES (14145, 19, 18, 15, 'e-enviou setas-seus e-lançou-os e-raios muito e-ele-os-ferveu');
INSERT INTO verses VALUES (14146, 19, 18, 16, 'e-viram a-fícies águas águas mo-sdotes te-vel mi-ga-rat-chak yhwh yhwh espírito espírito');
INSERT INTO verses VALUES (14147, 19, 18, 17, 'enviará mimmorom yikkacheni Yamsheni mimayim muitos');
INSERT INTO verses VALUES (14148, 19, 18, 18, 'yat-silenei me-oyvi força u-misnai porque amotzu de-mim');
INSERT INTO verses VALUES (14149, 19, 18, 19, 'antecipem-me no-dia- meu-velho e-foi yhwh para-a-maneira a-mim');
INSERT INTO verses VALUES (14150, 19, 18, 20, 'e-saí-me para-a-planura libertem-me porque desejo em-mim');
INSERT INTO verses VALUES (14151, 19, 18, 21, 'yigmeleni yhwh ketsidki destruição יָ֝דַ֗י residirá para-mim');
INSERT INTO verses VALUES (14152, 19, 18, 22, 'porque shamarati yhwh yhwh e-não rashateti de-Eloáhi:');
INSERT INTO verses VALUES (14153, 19, 18, 23, 'que todo de-seus-mandamentos para-negdi e-de-sua-leis não eu-fiquei-encarcerado מֶֽנִּי׃');
INSERT INTO verses VALUES (14154, 19, 18, 24, 'e-eu-fiquei integro com-ele e-eu-me-cuidei de-avóni:');
INSERT INTO verses VALUES (14155, 19, 18, 25, 'e-retornou-se-lhe yhwh a-mim segundo-sua-justiça porque minhas-mãos diante-de os-seus-olhos');
INSERT INTO verses VALUES (14156, 19, 18, 26, 'com devoto serás-devotado com homem perfeitos serão-perfeitos');
INSERT INTO verses VALUES (14157, 19, 18, 27, 'com liso se-revelar-á e-com- dura ser-engana-á');
INSERT INTO verses VALUES (14158, 19, 18, 28, 'porque Tu com afligido salves e olhos subirão vós despeçareis');
INSERT INTO verses VALUES (14159, 19, 18, 29, 'porque Tu farás brilhar yhwh yhwh meu-Eloah tu dissiparás o escuro');
INSERT INTO verses VALUES (14160, 19, 18, 30, 'porque em-você terra גְּד֑וּד e-com-meus-elohim אֲדַלֶּג־ shur');
INSERT INTO verses VALUES (14161, 19, 18, 31, 'o-Divino tâmid darchô imrat- yhwh tsrufah ele a-todo l''kol ha-chosisim em-ele');
INSERT INTO verses VALUES (14162, 19, 18, 32, 'que quem Elohim mibaladêi yhwh e-quem צֹור exceto-eu Elohim-nosso');
INSERT INTO verses VALUES (14163, 19, 18, 33, 'o-elohim hammeazreni força E-colocou  תָּמִ֣ים  darchî');
INSERT INTO verses VALUES (14164, 19, 18, 34, 'm''shavveh meus-pés כָּאַיָּל֑וֹת e-sobre minhas-em-o-altar ele-me-apoiará');
INSERT INTO verses VALUES (14165, 19, 18, 35, 'ensinando minhas-mãos para-a-guerra e-descansará קֶשֶׁת־ de-prata meus-braços');
INSERT INTO verses VALUES (14166, 19, 18, 36, 'e-deu para-mim escudo teu-salvamento e-a-tua-direita te-alimentar-me e-a-teu-modéstia me-multiplicar');
INSERT INTO verses VALUES (14167, 19, 18, 37, 'abrirás minha caminhada baixas-te para mim e-não meus passos minhas rodas');
INSERT INTO verses VALUES (14168, 19, 18, 38, 'eu-perseguir meus-inimigos e-achsegem e-não ashuv até כַּלּוֹתֵם׃');
INSERT INTO verses VALUES (14169, 19, 18, 39, 'em-chatzem e-não yukhlu levantou debaixo em-lugar-de rágalay:');
INSERT INTO verses VALUES (14170, 19, 18, 40, 'vat-azreni chayil para-a-guerra takhri''a qami debaixo-de-mim');
INSERT INTO verses VALUES (14171, 19, 18, 41, 've-oyevai deste a-mim עֹרֵפִי umeshanei açmitem');
INSERT INTO verses VALUES (14172, 19, 18, 42, 'yeshavu e-não-há moshia'' sobre yhwh e-não עָנָם׃');
INSERT INTO verses VALUES (14173, 19, 18, 43, 've-eshchakem ke-ofar sobre face-de espírito ketit hutzot ariqem');
INSERT INTO verses VALUES (14174, 19, 18, 44, 'tefalteini meribe povo tornem-me para-o-cabeça nações povo não eu-sei me-servirão');
INSERT INTO verses VALUES (14175, 19, 18, 45, 'para-ouvir ouvido eles-ouvirão a-mim filhos-de estrangeiro negarão-se-a para-mim');
INSERT INTO verses VALUES (14176, 19, 18, 46, 'filhos-de estrangeiro יִבֹּ֑לוּ יִבֹּלוּ e-os-ferirão de-seus-trancos');
INSERT INTO verses VALUES (14177, 19, 18, 47, 'vive yhwh e-barchu tsuri e-os-elevarão elohim-de ישעי׃');
INSERT INTO verses VALUES (14178, 19, 18, 48, 'o-elo o-dando vindictas a-mim e-ele-falou povos debaixo-de-mim');
INSERT INTO verses VALUES (14179, 19, 18, 49, 'que-libertando de-meus-inimigos certamente de meu-oponentes e-ele-exaltará-me מֵאִ֥ישׁ injustiça salvai-me:');
INSERT INTO verses VALUES (14180, 19, 18, 50, 'sobre כֵּ֤ן ׀ odecha nas-nações yhwh yhwh azamrah');
INSERT INTO verses VALUES (14181, 19, 18, 51, 'yeshuoth malcho veoseh chesed limshicho para-davíd ulzaro até eternidade');
INSERT INTO chapters VALUES (497, 19, 19, 15);
INSERT INTO verses VALUES (14182, 19, 19, 1, 'ao-regente salmo le-david');
INSERT INTO verses VALUES (14183, 19, 19, 2, 'os-céus mesaprim kavod- El umaase em-seus-mãos a-expansão a-expansão');
INSERT INTO verses VALUES (14184, 19, 19, 3, 'dia para-o-dia jorrará disse e-para-a-noite para-o-lado-da-noite dará-conhecimento- daath:');
INSERT INTO verses VALUES (14185, 19, 19, 4, 'não-há disse e-não-há palavras sem será-ouvido qol-am');
INSERT INTO verses VALUES (14186, 19, 19, 5, 'em-todo a-terra sair levantou e-no-extremo terra deles ao-sol colocou- tenda-de neles');
INSERT INTO verses VALUES (14187, 19, 19, 6, 'e-ele como-noivo sai de-sua-nupcia alegra-se como-heroi larutz caminho');
INSERT INTO verses VALUES (14188, 19, 19, 7, 'de-fim os-ceus saída-o e-ciclo-seu sobre extremos-eles e-não-há escondido de-seu-calor');
INSERT INTO verses VALUES (14189, 19, 19, 8, 'torah yhwh perfeita dadora-de alma testemunho yhwh fiel mãe-de-sabedoria peti');
INSERT INTO verses VALUES (14190, 19, 19, 9, 'piquday yhwh yesharim m''shamachey- coração yhwh yhwh barah me''irat Olhos:');
INSERT INTO verses VALUES (14191, 19, 19, 10, 'Temor de yhwh Pura Está Para sempre Leis de yhwh verdade Justiça juntos-verso');
INSERT INTO verses VALUES (14192, 19, 19, 11, 'Os agradáveis De ouro E de pedra preciosa muito e doces de mel e flor carmelitas:');
INSERT INTO verses VALUES (14193, 19, 19, 12, 'também teu servo guardado com-eles em seus cuidados ekev muito');
INSERT INTO verses VALUES (14194, 19, 19, 13, 'sírios quem entenderá das ocultas Nakki:');
INSERT INTO verses VALUES (14195, 19, 19, 14, 'também Mizziydem escuridão Avdekha a Yimshelu- Bi então Eitam Ve-niqkiyti Mippeša muito');
INSERT INTO verses VALUES (14196, 19, 19, 15, 'Leratzon palavras-de Pivi וְהֶגְי֣וֹן לִבִּ֣י diante-de-ti yhwh צוּרִ֥י וְגֹאֲלִֽי׃');
INSERT INTO chapters VALUES (498, 19, 20, 10);
INSERT INTO verses VALUES (14197, 19, 20, 1, 'ao-regente salmo le-david');
INSERT INTO verses VALUES (14198, 19, 20, 2, 'יַֽעַנְךָ֣ yhwh em-dia-de צָרָ֑ה יְ֝שַׂגֶּבְךָ֗ שֵׁ֤ם ׀ Elohim Jacó');
INSERT INTO verses VALUES (14199, 19, 20, 3, 'יִשְׁלַֽח־ a tua força do santuário e de Sião, ele te sustentará');
INSERT INTO verses VALUES (14200, 19, 20, 4, 'lembre-se todo de tua oferta e de teu holocausto, ele oferecerá sela');
INSERT INTO verses VALUES (14201, 19, 20, 5, 'ele dará para-ti com o teu coração e-todo אֲצַוֶּתְךָ יִמְלֹא׃');
INSERT INTO verses VALUES (14202, 19, 20, 6, 'נוֹרַנְנָה ׀ בִּישׁוּעָתֶךָ וּבְשֵׁם־ Elohim נִדְגֹּל יִמְלֹא yhwh todo מִשְׁאֲלוֹתֶיךָ׃');
INSERT INTO verses VALUES (14203, 19, 20, 7, 'עַתָּה יָדַ֗עְתִּי que הוֹשִׁ֥יעַ yhwh yhwh יַ֭עֲנֵהוּ מִשְּׁמֵ֣י sua-santidade בִּ֝גְבֻר֗וֹת יֵ֣שַׁע direita-de-ele');
INSERT INTO verses VALUES (14204, 19, 20, 8, 'Estas בָ֭רֶכֶב e-estes בַסּוּסִ֑ים וַאֲנַ֓חְנוּ em-o-nome-de yhwh Elohim נַזְכִּֽיר׃');
INSERT INTO verses VALUES (14205, 19, 20, 9, 'הֵ֭מָּה כָּרְע֣וּ וְנָפָ֑לוּ e-nós קַּ֝֗מְנוּ וַנִּתְעוֹדָֽד׃');
INSERT INTO verses VALUES (14206, 19, 20, 10, 'yhwh הוֹשִׁ֑יעָה הַ֝מֶּ֗לֶךְ יַעֲנֵ֥נוּ בְיוֹם־ chamemos');
INSERT INTO chapters VALUES (499, 19, 21, 14);
INSERT INTO verses VALUES (14207, 19, 21, 1, 'ao-regente salmo le-david');
INSERT INTO verses VALUES (14208, 19, 21, 2, 'yhwh na tua força se alegrará rei e na tua salvação que muito');
INSERT INTO verses VALUES (14209, 19, 21, 3, 'será a minha gula no seu coração deste para-ele e o meu canto de sua boca não eu recusei-me selá');
INSERT INTO verses VALUES (14210, 19, 21, 4, 'porque teqaddemenu bom bom tashit leroshovo coroa paz');
INSERT INTO verses VALUES (14211, 19, 21, 5, 'vida pediu mimakha nattaha deste para-ele yamim olam eternidade');
INSERT INTO verses VALUES (14212, 19, 21, 6, 'grande kabodovo bisyuatakecha הוֹד וְהָדָר תּשׁוּעה sobre-ele');
INSERT INTO verses VALUES (14213, 19, 21, 7, 'porque תִישָׁיוֹתֵהוּ בְּרָכוֹת לָעַד תִּחֲדֵֹהוּ בשמחה a teu-rosto');
INSERT INTO verses VALUES (14214, 19, 21, 8, 'porque המלך בָּטֵחַ em-Javé e-em-carinho o-alto não- será-movido:');
INSERT INTO verses VALUES (14215, 19, 21, 9, 'será-encontrada sua-mão para-todo teus-inimigos seu-direito será-encontrado seus-inimigos:');
INSERT INTO verses VALUES (14216, 19, 21, 10, 'os-derreter-vós fornalha fogo— לְעֵ֢ת פָּ֫נֶ֥יךָ yhwh yhwh יְבַלְּעֵ֑ם וְֽתֹאכְלֵ֥ם אֵֽשׁ׃');
INSERT INTO verses VALUES (14217, 19, 21, 11, 'פִּ֭רְיָמוֹ da-terra תְּאַבֵּ֑ד וְ֝זַרְעָ֗ם de-filhos-de homem');
INSERT INTO verses VALUES (14218, 19, 21, 12, 'porque נָט֣וּ עָלֶ֣יךָ maldade  חָשַׂבֻּ   מְזִמָּה  não-  יַכּוּ׃');
INSERT INTO verses VALUES (14219, 19, 21, 13, 'que  תְּשַׁיֶּטֵּהֻ   שָׁכְמֶ֑ךָ   בְּמִתַּרְיָאֵיכֶ֗ם   תְּכַוֵּן  sobre em-seus-faces');
INSERT INTO verses VALUES (14220, 19, 21, 14, 'רֻמָּה  yhwh  בְּעֹזֶךָ   נַשְׂרִיָּה  וּֽ֝נְזַמְּרָה גְּבוּרָתֶֽךָ׃');
INSERT INTO chapters VALUES (500, 19, 22, 32);
INSERT INTO verses VALUES (14221, 19, 22, 1, 'לַ֭מְנַצֵּחַ sobre אַיֶּ֥לֶת הַשַׁ֗חַר salmo le-david');
INSERT INTO verses VALUES (14222, 19, 22, 2, 'אֵלִ֣י אֵ֭לִי לָמָ֣ה עֲזַבְתָּ֑נִי רָח֥וֹק de-me-sua-ça-ô-to palavras-de sa-ga-ta-ô');
INSERT INTO verses VALUES (14223, 19, 22, 3, 'meu-elohim e-que-ra jo-ma-m e-não ta-an-e-ha ve-la-ye-la-ha e-não du-mi-yá-ha para-mim');
INSERT INTO verses VALUES (14224, 19, 22, 4, 've-a-ta-ha santo jo-shé-va te-hi-lo-t Israel');
INSERT INTO verses VALUES (14225, 19, 22, 5, 'em-te se-alegraram-no n-o-s-s-os-p-a-i-s-e-s se-alegraram-no e-lhe-salvou-os');
INSERT INTO verses VALUES (14226, 19, 22, 6, 'a-ti chamaram e-escaparam-se em-te se-alegraram-no e-não tiveram-vergonha');
INSERT INTO verses VALUES (14227, 19, 22, 7, 'e-eu verme e-não homem homem homem וּבְז֥וּי povo');
INSERT INTO verses VALUES (14228, 19, 22, 8, 'todo רֹ֭אַי יַלְעִ֣גוּ a-mim יַפְטִ֥ירוּ בְ֝שָׂפָ֗ה יָנִ֥יעוּ cabeça');
INSERT INTO verses VALUES (14229, 19, 22, 9, 'גֹּ֣ל a yhwh יְפַלְּטֵ֑הוּ que porque חָ֥פֵֽץ em-ele');
INSERT INTO verses VALUES (14230, 19, 22, 10, 'porque tu גֹחִ֣י מבطن מבטיחי sobre Shaddai AMI:');
INSERT INTO verses VALUES (14231, 19, 22, 11, 'עלך HASHalachti de-merékhem de-béten imi eli tu');
INSERT INTO verses VALUES (14232, 19, 22, 12, 'a te-rakhak de-mi porque chára qrová porque não ozér');
INSERT INTO verses VALUES (14233, 19, 22, 13, 'sabavúni parí muitos aviré bashán kitrúni');
INSERT INTO verses VALUES (14234, 19, 22, 14, 'pátsu sobre-mim suas-bocas arié devorador e-arrastador:');
INSERT INTO verses VALUES (14235, 19, 22, 15, 'como-aguas jorraram-se-me e-dividiram-se todo ser foi meu-coração como-um-pombo no-meio-de em-meio-de dos-entres-colos');
INSERT INTO verses VALUES (14236, 19, 22, 16, 'יָבֵשׁ כַּחֶ֨רֶשׂ כֹּחִ֗י וּ֭לְשׁוֹנִי מֻדְבָּ֣ק מַלְקוֹחָ֑י וְֽלַעֲפַר־ morte תִּשְׁפְּתֵֽנִי׃');
INSERT INTO verses VALUES (14237, 19, 22, 17, 'que סְבָב֗וּנִי כְּלָ֫בִ֥ים congregação-de מרעים היקפוני כארי ידאי רגלי׃');
INSERT INTO verses VALUES (14238, 19, 22, 18, 'אספר todo עצמותאי eles  yabbiṭū יראו־ בי׃');
INSERT INTO verses VALUES (14239, 19, 22, 19, 'יְחַלְּק֣וּ בְגָדַ֣י a-eles e-sobre לְ֝בוּשִׁ֗י יַפִּ֥ילוּ גוֹרָֽל׃');
INSERT INTO verses VALUES (14240, 19, 22, 20, 'e-tu yhwh a תִּרְחָ֑ק אֱ֝יָלוּתִ֗י לְעֶזְרָ֥תִי חֽוּשָׁה׃');
INSERT INTO verses VALUES (14241, 19, 22, 21, 'הַצִּ֣ילָה de-arma minha-alma da-mão- c-cão minha-unidade;');
INSERT INTO verses VALUES (14242, 19, 22, 22, 'salva-nos de-boca-de leão e-da-cornos- espinhos atende-nos;');
INSERT INTO verses VALUES (14243, 19, 22, 23, 'anunciar-ei teu-nome para os meus vivos no-meio-de assembleia alelai-te');
INSERT INTO verses VALUES (14244, 19, 22, 24, 'temores yhwh aleluia-lhe todo descendência Jacó glorificai-o e adorem nós todo semente Israel');
INSERT INTO verses VALUES (14245, 19, 22, 25, 'que não semente e-não destruição ענוות עני e-não nós פנאו a-ele ובshawעו a-ele ouviu');
INSERT INTO verses VALUES (14246, 19, 22, 26, 'מאתך תהילהתי בקהל muito נדורי אshallים diante יראו׃');
INSERT INTO verses VALUES (14247, 19, 22, 27, 'יֹאכְל֬וּ עֲנָוִ֨ים וְיִשְׂבָּ֗עוּ יְהַֽלְל֣וּ yhwh yhwh viva לְבַבְכֶ֣ם לָעַֽד׃');
INSERT INTO verses VALUES (14248, 19, 22, 28, 'יִזְכְּר֤וּ וְיָשֻׁ֣בוּ a yhwh todo extremidades-de terra וְיִֽשְׁתַּחֲו֥וּ לְ֝פָנֶ֗יךָ todo famílias goyim:');
INSERT INTO verses VALUES (14249, 19, 22, 29, 'que a-יהוה a-mo-łu-ká-ha u-mós-e-l b-gó-i-im:');
INSERT INTO verses VALUES (14250, 19, 22, 30, 'a-khél-u vá-yi-shít-cha-vu u todo d-she-néi- terra diante-dele yik-ré-u pó yo-ré-dei não vén-na-fshe-wo não khí-yá:');
INSERT INTO verses VALUES (14251, 19, 22, 31, 'semente 伺服祂 必述 我主 世世代代：');
INSERT INTO verses VALUES (14252, 19, 22, 32, '必到 并述说 祂的公义 para-o-povo 生 que fez');
INSERT INTO chapters VALUES (501, 19, 23, 6);
INSERT INTO verses VALUES (14253, 19, 23, 1, 'salmo para-Davi yhwh 我的牧者 não 我必缺乏：');
INSERT INTO verses VALUES (14254, 19, 23, 2, 'בִּנְאוֹת דֶּ֭שַֽא יַרְבִּיצֵנִי sobre מֵ֖י מְנֻח֣וֹת יְנַהֲלֵנִי׃');
INSERT INTO verses VALUES (14255, 19, 23, 3, 'נַפְשִׁ֥י יְשׁוֹבֵב יַֽנְחֵנִי בְמַעְגְּלֵי־ צדקה para-que nome-dele');
INSERT INTO verses VALUES (14256, 19, 23, 4, 'também porque אילך בגיא צלמות mal אירא comigo porque tu עםADI שבטך ומISHענתך eles ינחMUני');
INSERT INTO verses VALUES (14257, 19, 23, 5, 'תעArc ante mim mesa diante-de diante eu dispensei em óleo cabeça-minha copo-meu bebida');
INSERT INTO verses VALUES (14258, 19, 23, 6, 'ach  bom bom perseguir-me-ão todo dias-de minha vida e eu voltarei na-casa-de yhwh para-orékh dias');
INSERT INTO chapters VALUES (502, 19, 24, 10);
INSERT INTO verses VALUES (14259, 19, 24, 1, 'para-David mizemór לַיהוָה a-terra e-méloáh te-bél וְיֹ֣שְׁבֵי em-ela');
INSERT INTO verses VALUES (14260, 19, 24, 2, 'porque ele- sobre יַמִּ֣ים יְסָדָ֑הּ e-sobre נְ֝הָר֗וֹת וַיְכוֹנְנֶֽהָ׃');
INSERT INTO verses VALUES (14261, 19, 24, 3, 'quem subirá בְּהַר- yhwh וּמִי- יָֽקֻם בִּמְק֥וֹם קָדְשֽׁוֹ׃');
INSERT INTO verses VALUES (14262, 19, 24, 4, 'נְקִ֥י כַּפַּ֗יִם וּבַר- לֵ֫בָ֥ב que não levou para a nada minha-alma e-não jurou por engano:');
INSERT INTO verses VALUES (14263, 19, 24, 5, 'levou bênção de-junto-de yhwh e justiça dos elohim sua salvação:');
INSERT INTO verses VALUES (14264, 19, 24, 6, 'isto dor מְבַקְשֵׁ֨י פָנֶ֖יךָ Jacó Selá');
INSERT INTO verses VALUES (14265, 19, 24, 7, 'levantem שְׁעָרִ֨ים ׀ רָֽאשֵׁיכֶ֗ם וְֽ֭הִנָּשְׂאוּ פִּתְחֵ֣י eternidade eternidade rei הַכָּבֽוֹד׃');
INSERT INTO verses VALUES (14266, 19, 24, 8, 'quem זֶה֮ rei הַכָּ֫ב֥וֹד yhwh עִזּ֣וּז e-guerreiro yhwh heroi- guerra');
INSERT INTO verses VALUES (14267, 19, 24, 9, 'levantem c-portas vossos-cabeças e-alteiem abram eternidade eternidade rei a-glória');
INSERT INTO verses VALUES (14268, 19, 24, 10, 'quem ele isto rei a-glória yhwh exércitos ele rei a-glória Selá');
INSERT INTO chapters VALUES (503, 19, 25, 22);
INSERT INTO verses VALUES (14269, 19, 25, 1, 'para-davíd a-ti yhwh nafshi eššāʾ:');
INSERT INTO verses VALUES (14270, 19, 25, 2, 'meu-elohim bakkha'' batakhti a ebošāh a yaʿalṣū ʾōyevay para-mim');
INSERT INTO verses VALUES (14271, 19, 25, 3, 'também todo não yebošu yebošu ha-bogedim vazios');
INSERT INTO verses VALUES (14272, 19, 25, 4, 'דרכיך yhwh הודעני אותךות למדני');
INSERT INTO verses VALUES (14273, 19, 25, 5, 'hdricheni בהאמיתך ולמדני porque אתה Elohim-de Isei אותך קיויתי todo o-dia');
INSERT INTO verses VALUES (14274, 19, 25, 6, 'זְכֹר־ yhwh yhwh que porque  מֵעוֹלָ֣ם eles');
INSERT INTO verses VALUES (14275, 19, 25, 7, 'חַטֹּ֤אות  נְעוּרַ֨י ׀  וּפְשָׁעַ֗י a  תִּ֫זְכֹּ֥ר  כְּחַסְדְּךָ֥ lembra-de para-mim-  אַ֑תָּה yhwh  טוּבְךָ֣ yhwh');
INSERT INTO verses VALUES (14276, 19, 25, 8, 'טוֹב־ yhwh yhwh sobre assim instruindo pecadores no-caminho');
INSERT INTO verses VALUES (14277, 19, 25, 9, 'dirija-os os humildes pelo juízo e ensine-os os humildes seu caminho');
INSERT INTO verses VALUES (14278, 19, 25, 10, 'todo yhwh yhwh bondade e-verdade aos guardiões de sua aliança e suas testemunhas:');
INSERT INTO verses VALUES (14279, 19, 25, 11, 'para  yhwh yhwh e te arrependesses; que porque muito ela');
INSERT INTO verses VALUES (14280, 19, 25, 12, 'quem este o homem yhwh yhwh lhe ensinará no-caminho será escolhido:');
INSERT INTO verses VALUES (14281, 19, 25, 13, 'sua alma no bem viverás e seu fruto irásh terra');
INSERT INTO verses VALUES (14282, 19, 25, 14, 'sód yhwh liréavá úberíthav lehódivám:');
INSERT INTO verses VALUES (14283, 19, 25, 15, 'éyná támid a que porque ele yótsiá méreshet rágalay:');
INSERT INTO verses VALUES (14284, 19, 25, 16, 'apresente-me- a-mim e-tenha-misericórdia-de-mi porque único e-pobre eu:');
INSERT INTO verses VALUES (14285, 19, 25, 17, 'angústias no-meu-coração expandei-vos dos-meus-lixos saíde-mim');
INSERT INTO verses VALUES (14286, 19, 25, 18, 'viu minha-pobreza e-me e-a para-todo minhas-iniquidades:');
INSERT INTO verses VALUES (14287, 19, 25, 19, 've- meus-inimigos porque muitos-são e-odio violência me-odiaram:');
INSERT INTO verses VALUES (14288, 19, 25, 20, 'guardou minha-alma e salve-me a vergonha-me porque esperançei em-te:');
INSERT INTO verses VALUES (14289, 19, 25, 21, 'perfeito- e bem-aventurado que porque foi-te:');
INSERT INTO verses VALUES (14290, 19, 25, 22, 'redime-me Elohim a de-toda de-todo seus-perigos:');
INSERT INTO chapters VALUES (504, 19, 26, 12);
INSERT INTO verses VALUES (14291, 19, 26, 1, 'para-davi julgue-me yhwh yhwh Eu em-me and-foi e-em-Yahweh e-confiei não esperarei;');
INSERT INTO verses VALUES (14292, 19, 26, 2, 'examina-me yhwh e-prova-me minhas-angústias e-meu-coração;');
INSERT INTO verses VALUES (14293, 19, 26, 3, 'porque Sussana-te diante-de e-olhos-meus e andarei em-verdade-te:');
INSERT INTO verses VALUES (14294, 19, 26, 4, 'não assentei-me com por-que não e-com alma-s: não entrarei:');
INSERT INTO verses VALUES (14295, 19, 26, 5, 'odiava assembleia os-enganadores e-com- não não אֵשֵֽׁב׃');
INSERT INTO verses VALUES (14296, 19, 26, 6, 'אֶרְחַ֣ץ בְּנִקָּי֣וֹן כַּפָּ֑י וַאֲסֹבְבָ֖ה a yhwh yhwh');
INSERT INTO verses VALUES (14297, 19, 26, 7, 'לַ֭שְׁמִעַ com-voz תּוֹדָ֑ה וּ֝לְסַפֵּ֗ר todo נִפְלְאוֹתֶֽיךָ׃');
INSERT INTO verses VALUES (14298, 19, 26, 8, 'yhwh אָ֭הַבְתִּי morada בֵּיתֶ֑ךָ וּ֝מְק֗וֹם tabernáculo-de כְּבוֹדֶֽךָ׃');
INSERT INTO verses VALUES (14299, 19, 26, 9, 'a תֶּאֱסֹ֣ף com pecadores minha-alma e-com- homens-de דָמִ֣ים חַיָּֽי׃');
INSERT INTO verses VALUES (14300, 19, 26, 10, 'que בִּידֵיהֶ֥ם זִמָּ֑ה וִימִינָם מָלְאָה שׁוֹחַד׃');
INSERT INTO verses VALUES (14301, 19, 26, 11, 'וַאֲנִי בּתֻמּי irei פּדֵני וְחָנּנִי׃');
INSERT INTO verses VALUES (14302, 19, 26, 12, 'רַגְלִי עָמְדָה בְמִישׁור בְּ֝מַקְהֵלִ֗ים אֲבָרֵ֥ךְ yhwh');
INSERT INTO chapters VALUES (505, 19, 27, 14);
INSERT INTO verses VALUES (14303, 19, 27, 1, 'para-David יהוה yhwh וְ֭יִשְׁעִי מִמִּ֣י אִירָ֑א yhwh מָֽעוֹז־ yhwh מִמִּ֥י אֶפְחָֽד׃');
INSERT INTO verses VALUES (14304, 19, 27, 2, 'בִּקְרֹ֤ב עָלַ֨י ׀ מרעים לאכול a בשרי צרני ואיבני a-mim eles כשלו ונפלו׃');
INSERT INTO verses VALUES (14305, 19, 27, 3, 'se תחנה עלאי מחנה não אֲרַוֶּה לִבִּי se תָקוּמְנָה עֲלֵי guerra בָּזֹאת eu בּוֹטֶהֱׄךְ׃');
INSERT INTO verses VALUES (14306, 19, 27, 4, 'uma שָׁאַלְתִּי de-com yhwh אוֹתָהּ אֲבַקְשֶׁה שִׁיבְתִּי na-casa-de yhwh todo dias-de חַיִּי לָחֵז֥וֹת בְּנוּאַֽמ־ yhwh וּלְבָקֵ֥ר בְּהֵיכָלֽוֹ׃');
INSERT INTO verses VALUES (14307, 19, 27, 5, 'que יִצְפְּנֵ֨נִי ׀ בְּסֻכֹּה֮ בְּיוֹם רָ֫עָ֥ה יַ֭סְתִּרֵנִי בְּסֵ֣תֶר אָהֳל֑וֹ בְּ֝צ֗וּר יְרוֹמְמֵֽנִי׃');
INSERT INTO verses VALUES (14308, 19, 27, 6, 'e-agora יָר֪וּם רֹאשִׁ֡י sobre אֹֽיְבַ֬י סְֽבִיבוֹתַ֗י וְאֶזְבְּחָ֣ה בְ֭אָהֳלוֹ zibchei  תְרוּעָ֑ה   אָשִׁ֥ירָה   וַ֝אֲזַמְּרָ֗ה  para-יהוה');
INSERT INTO verses VALUES (14309, 19, 27, 7, 'שְׁמַע־  yhwh  קוֹלִ֥י   אֶקְרָ֗א   וְחָנֵּ֥נִי   וַעֲנֵֽנִי׃');
INSERT INTO verses VALUES (14310, 19, 27, 8, 'a-ti disse disse  בַּקְּשׁ֣וּ  face-de a  פָּנֶ֖יךָ  yhwh אֲבַקֵּֽשׁ׃');
INSERT INTO verses VALUES (14311, 19, 27, 9, 'a תַּסְתֵּ֬ר פָּנֶ֨יךָ ׀ מִמֶּנִּי֮ a תַּט־ בְּאַ֗ף עַ֫בְדֶּ֥ךָ עֶזְרָתִ֥י הָיִ֑יתָ a תִּטְּשֵׁ֥נִי e-a תעזבנני Elohim-de ישעי׃');
INSERT INTO verses VALUES (14312, 19, 27, 10, 'porque pai-meu ואמי עזבונני והוה IASפני׃');
INSERT INTO verses VALUES (14313, 19, 27, 11, 'הורני yhwh דרךך ונ Cheney בהורах מִישׁוֹר לְ֝מַ֗עַן שׁוֹרְרָֽי׃');
INSERT INTO verses VALUES (14314, 19, 27, 12, 'a תִּ֭תְּנֵנִי בְּנֶ֣פֶשׁ que porque קָֽמוּ־ בִ֥י עֵֽדֵי־ שֶׁ֝֗קֶר וִיפֵ֥חַ violência');
INSERT INTO verses VALUES (14315, 19, 27, 13, 'האמנתי para-ver para-ver yhwh em-terra-de vida');
INSERT INTO verses VALUES (14316, 19, 27, 14, 'קוה a yhwh  חזק   ואמץ  teu-coração  וקוה  a yhwh');
INSERT INTO chapters VALUES (506, 19, 28, 9);
INSERT INTO verses VALUES (14317, 19, 28, 1, 'para-davíd  אליך  yhwh  אֶקְרָ֗א   צורי  a  תחרש  מִמִּ֫מֶּ֥נִּי para-que-não תֶּֽחֱשֶׁ֥ה de-mim וְ֝נִמְשַׁ֗לְתִּי com י֥וֹרְדֵי בֽוֹר׃');
INSERT INTO verses VALUES (14318, 19, 28, 2, 'ouviu voz תַּ֭חֲנוּנַי בְּשַׁוְּעִ֣י a-ti בְּנָשְׂאִ֥י יָ֝דַ֗י a Debir קָדְשֶֽׁךָ׃');
INSERT INTO verses VALUES (14319, 19, 28, 3, 'a timsheni com reshaim e-com- po''alay mal dov''re shalom com re''eyhem ve-ra''ah bilbamo');
INSERT INTO verses VALUES (14320, 19, 28, 4, 'dá lahem ke-p''ala''am e-cora ma-al-lei-ye-hem como-obra-de yed-ei-hem a-eles para-eles ha-sha-ve a-eles para-eles');
INSERT INTO verses VALUES (14321, 19, 28, 5, 'que não ya-bi-inu a yhwh yhwh e-a obra-de mãos-dele ye-he-re-ses-em e-não yi-bne-nem');
INSERT INTO verses VALUES (14322, 19, 28, 6, 'bendito yhwh porque voz voz-de ta-ch-an-na-yi');
INSERT INTO verses VALUES (14323, 19, 28, 7, 'yhwh u-zi u-ma-gin-ni בוֹ בָּטַח meu-coracao וְנֶעֱזָרְתִּי וַיַּעֲלֹז meu-coração וּמִשִּׁירִי');
INSERT INTO verses VALUES (14324, 19, 28, 8, 'yhwh עֹז־ a-eles וּמָע֤וֹז יְשׁוּע֖וֹת ele ela');
INSERT INTO verses VALUES (14325, 19, 28, 9, 'הוֹשִׁיעָה ׀ a עַמֶּ֗ךָ e bendigá-lo a a tua herança e reú-lo e levá-lo até o mundo');
INSERT INTO chapters VALUES (507, 19, 29, 11);
INSERT INTO verses VALUES (14326, 19, 29, 1, 'hino para-Davi dai para yhwh filhos-de elohim traga-m para yhwh glória e força');
INSERT INTO verses VALUES (14327, 19, 29, 2, 'dai לַיהוָה glória-de seu-nome הִשׁתּחֲווּ para yhwh בְּהַדְרַת־ קֹדֶשׁ׃');
INSERT INTO verses VALUES (14328, 19, 29, 3, 'voz yhwh sobre as-águas a yhwh הִרְעִים yhwh sobre águas muitos');
INSERT INTO verses VALUES (14329, 19, 29, 4, 'voz-de yhwh voz yhwh yhwh בֶּהָדָר׃');
INSERT INTO verses VALUES (14330, 19, 29, 5, 'voz yhwh שׁובֵר árvores-de-cedro וַיְשׁבּר yhwh a אַרְזֵי o-lbanôn');
INSERT INTO verses VALUES (14331, 19, 29, 6, 'e-oscilaram como egel lhabanôn e-saryôn como filho-de reemim');
INSERT INTO verses VALUES (14332, 19, 29, 7, 'voz-de yhwh cavador para-queimar fogo');
INSERT INTO verses VALUES (14333, 19, 29, 8, 'voz yhwh יָחִ֣יל מִדְבָּ֑ר יָחִ֥יל yhwh deserto-de קָדֵֽשׁ׃');
INSERT INTO verses VALUES (14334, 19, 29, 9, 'voz yhwh יְחוֹלֵ֣ל אַיָּלוֹת֮ וַֽיֶּחֱשֹׂ֢ף יְעָ֫ר֥וֹת וּבְהֵיכָל֑וֹ כֻּ֝לּ֗וֹ disse כבוד׃');
INSERT INTO verses VALUES (14335, 19, 29, 10, 'yhwh למבול habitou e-habitou yhwh rei para-eternidade');
INSERT INTO verses VALUES (14336, 19, 29, 11, 'yhwh עוז לאמו יתן yhwh יברך a amo בשלום׃');
INSERT INTO chapters VALUES (508, 19, 30, 13);
INSERT INTO verses VALUES (14337, 19, 30, 1, 'מזמור שיר－ dedicação a-casa le-david');
INSERT INTO verses VALUES (14338, 19, 30, 2, 'aromimkha yhwh que dilitani e-não simchata ʾōyevay para-mim');
INSERT INTO verses VALUES (14339, 19, 30, 3, 'yhwh Elohim-me shu''uti eleyka vatirpeini');
INSERT INTO verses VALUES (14340, 19, 30, 4, 'yhwh ha''eleita de sho''al minha-alma chiyyitani bor:');
INSERT INTO verses VALUES (14341, 19, 30, 5, 'zamaru a-yhwh chasidyav v''hodu lezecher kadosho:');
INSERT INTO verses VALUES (14342, 19, 30, 6, 'que regua ba''apovo chayyim vida no-éreb yalin be-khi ve-labberak rinah');
INSERT INTO verses VALUES (14343, 19, 30, 7, 'va-ani eu-disse be-shalvi não emot para-eternidade');
INSERT INTO verses VALUES (14344, 19, 30, 8, 'yhwh biratzonkha he-amadta para arrebatá-lo força escondeste seus rostos era tremei');
INSERT INTO verses VALUES (14345, 19, 30, 9, 'a-ti yhwh clamarei e-a Adonai e implorareis');
INSERT INTO verses VALUES (14346, 19, 30, 10, 'que em vão com sangue a El vocês se agacharão pó na poeira הֲיַגִּ֥יד אֲמִתֶּֽךָ׃');
INSERT INTO verses VALUES (14347, 19, 30, 11, 'שְׁמַע־  yhwh yhwh yhwh הֱ‍ֽיֵה־ עֹזֵ֥ר para-mim');
INSERT INTO verses VALUES (14348, 19, 30, 12, 'הָפַ֣כְתָּ מִסְפְּדִי֮ para-danzar para-mim abriste-te meu-vaso e-me-ajustrei alegria:');
INSERT INTO verses VALUES (14349, 19, 30, 13, 'para-que cante-te glória e-não se-estabeleça yhwh yhwh para-sempre adoro-te:');
INSERT INTO chapters VALUES (509, 19, 31, 25);
INSERT INTO verses VALUES (14350, 19, 31, 1, 'ao-regente salmo le-david');
INSERT INTO verses VALUES (14351, 19, 31, 2, 'yhwh yhwh a vergonha-me para-sempre na-tua-justiça salva-me:');
INSERT INTO verses VALUES (14352, 19, 31, 3, 'הַטֵּ֤ה אֵלַ֨י ׀ אָזְנְךָ֮ מְהֵרָ֢ה הַצִּ֫ילֵ֥נִי foi לִ֨י ׀ לְֽצוּר־ מָ֭עוֹז segundo-casa-de מְצוּד֗וֹת לְהוֹשִׁיעֵֽנִי׃');
INSERT INTO verses VALUES (14353, 19, 31, 4, 'porque סלי וּמְצוּדָתִ֣י tu וּלְמַ֥עַן שִׁ֝מְךָ֗ תַּֽנְחֵ֥נִי וּֽתְנַהֲלֵֽנִי׃');
INSERT INTO verses VALUES (14354, 19, 31, 5, 'תּוֹצִיאֵ֗נִי méreshet ז֭וּ טָ֣מְנוּ a-mim porque você meu-muro:');
INSERT INTO verses VALUES (14355, 19, 31, 6, 'na-sua-mão: de-paquer meu-vento você-me-fê meu yhwh El verdade');
INSERT INTO verses VALUES (14356, 19, 31, 7, 'me-odio os-guardadores: as-vilões-: שָׁוָ֑א e-eu a yhwh בָּטַחְתִּי׃');
INSERT INTO verses VALUES (14357, 19, 31, 8, 'אָגִילָה וְאֶשְׂמַחָה בְּחַסְדֶּךָ que רָאִיתָ a עֲנִיָּה יָדַעְתָּ בְּצָרֹות alma-de-mim');
INSERT INTO verses VALUES (14358, 19, 31, 9, 'e-não הִסְגַּרְתַּנִי pela-mão-de אֹיֵב הֶעֱמַדְתָּ בַמֶּרְחָ֣ב rágalay:');
INSERT INTO verses VALUES (14359, 19, 31, 10, 'חָנֵּ֥נִי yhwh que צַ֫ר־ para-mim עָשְׁשָׁ֖ה בְכַ֥עַס עֵינִ֗י נַפְשִׁ֥י וּבִטְנִֽי׃');
INSERT INTO verses VALUES (14360, 19, 31, 11, 'que כָל֪וּ בְיָג֡וֹן חַיַּי֮ וּשְׁנוֹתַ֢י בַּאֲנָ֫חָ֥ה כָּשַׁ֣ל בַּעֲוֺנִ֣י כֹחִ֑י וַעֲצָמַ֥י עָשׂוּ׃');
INSERT INTO verses VALUES (14361, 19, 31, 12, 'de-todo צֹרְרַי הָיִיתִי חֶרְפָּה וְלִשֲׁכֵנַי ׀ muito וּפַחַד לִֽמְיֻדָּ֫עָ֥י רֹאַי בַּח֑וּץ נָדְד֥וּ de-mim');
INSERT INTO verses VALUES (14362, 19, 31, 13, 'esqueci-me como-morto do-coração eu-havia-sido como-vaso perdi-se');
INSERT INTO verses VALUES (14363, 19, 31, 14, 'que eu-orientei-me דִּבַּ֥ת רַבִּים֮ מָג֢וֹר מִסָּ֫בִ֥יב בְּהִוּסְדָ֣ם יַ֣חַד עָלַ֑י para-tomar נַפְשִׁ֣י זָמָֽמוּ׃');
INSERT INTO verses VALUES (14364, 19, 31, 15, 'e-eu עָלֶ֣יךָ בָטַ֣חְתִּי yhwh yhwh אֱלֹהַ֥י tu');
INSERT INTO verses VALUES (14365, 19, 31, 16, 'בְּיָדְךָ֥ -initialized-me salva-me da-mão- meu-inimigo e-meu-perseguidor:');
INSERT INTO verses VALUES (14366, 19, 31, 17, 'ilumina-te teu-rosto sobre servo-teu salva-nos pela-tua-grandeza:');
INSERT INTO verses VALUES (14367, 19, 31, 18, 'yhwh a que porque chama-te יֵבֹשׁוּ ímpios יִדְּמ֥וּ לִשְׁאֽוֹל׃');
INSERT INTO verses VALUES (14368, 19, 31, 19, 'תֵּ֥אָלַ֗מְנָה שִׂפְתֵ֫י שָׁ֥קֶר הַדֹּבְר֖וֹת sobre justo עָתָ֗ק בְּגַאֲוָ֥ה');
INSERT INTO verses VALUES (14369, 19, 31, 20, 'que רַֽב־ Tubakhma que Tsaphantak Lir''eikha sobre-ti diante Bakh homem filhos-de homem');
INSERT INTO verses VALUES (14370, 19, 31, 21, 'Tas''tirem Beseter Panekha Merukseiy homem Titzphnem Besuka וְאַרְבַּ֖ע לְשׁוֹן׃');
INSERT INTO verses VALUES (14371, 19, 31, 22, 'bendito yhwh que הִפְלָא חֶסֶדְׁוֹ לִֽי׃ na-cidade מַזָּר׃');
INSERT INTO verses VALUES (14372, 19, 31, 23, 'e-eu אָמַרְתִּי בְּחָפְזִי נִגְרַזְתִּי מִנֵּגֶד os teus olhos sim ouviste voz voz na minha angústia para-ti');
INSERT INTO verses VALUES (14373, 19, 31, 24, 'amem a yhwh todo seus santos yhwh guardião yhwh e pague sobre resto fez orgulho:');
INSERT INTO verses VALUES (14374, 19, 31, 25, 'fortalecei e endureçai os vossos corações todo aqueles que esperam para-יהוה');
INSERT INTO chapters VALUES (510, 19, 32, 11);
INSERT INTO verses VALUES (14375, 19, 32, 1, 'para-David o sábio feliz levanta-vos iniquidade cobertura pecado:');
INSERT INTO verses VALUES (14376, 19, 32, 2, 'Ashrei homem não Yachshob yhwh a-ele Avon e-não-há b''rucho Remiyah');
INSERT INTO verses VALUES (14377, 19, 32, 3, 'porque hecharesharti balu atzami b''sha''agati todo o-dia');
INSERT INTO verses VALUES (14378, 19, 32, 4, 'que dia va''yelya תִּכְבַּ֥ד עָלַ֗י יָ֫דֶ֥ךָ se-tornar לְשַׁדִּ֑י בְּחַרְבֹ֖נֵי קַ֣יִץ Selá');
INSERT INTO verses VALUES (14379, 19, 32, 5, 'חַטָּאתִ֨י אוֹדִ֪יעֲךָ֡ וַעֲוֺ֘נִ֤י não כִסִּ֗יתִי disse-ei- Eu confesso sobre meus pecados a-yhwh e tu levaste iniquidade meu pecado sela');
INSERT INTO verses VALUES (14380, 19, 32, 6, 'sobre isto interceda todo misericordioso para ti para a hora o achando somente águas águas a-ele não não virão');
INSERT INTO verses VALUES (14381, 19, 32, 7, 'tu segredo para-mim do estrito e alegria e refúgio virem ao meu redor Selá');
INSERT INTO verses VALUES (14382, 19, 32, 8, 'eu me esconderei diante de ti e a tua luz no caminho ז֥וּ andarás אִֽיעֲצָ֖ה עָלֶ֣יךָ עֵינִֽי׃');
INSERT INTO verses VALUES (14383, 19, 32, 9, 'a תִּֽהְי֤וּ ׀ cavalo כְּפֶרֶד֮ não-há הָ֫בִ֥ין בְּמֶֽתֶג־ וָרֶ֣סֶן עֶדְיֹ לִבְלֹ֑ום בַּ֝֗ל קְרֹ֣ב para-ti');
INSERT INTO verses VALUES (14384, 19, 32, 10, 'muitos מַכְאוֹבִ֗ים לָרָ֫שָׁ֥ע וְהַבּוֹטֵ֥חַ em-Javé חֶ֝֗סֶד יְסוֹבְבֶֽנּוּ׃');
INSERT INTO verses VALUES (14385, 19, 32, 11, 'semear-se-ão no-יהוה e-guitem justos e-cantemos todo retos- coração');
INSERT INTO chapters VALUES (511, 19, 33, 22);
INSERT INTO verses VALUES (14386, 19, 33, 1, 'רָנוּ justos em-יהוה aos-retos bonito הלל׃');
INSERT INTO verses VALUES (14387, 19, 33, 2, 'הודוּ a-yhwh בקינּוֹר בנגֶל עשׂור זמרו־ a-ele');
INSERT INTO verses VALUES (14388, 19, 33, 3, 'שירו־ a-ele שִׁ֣יר novo façam bem נגנוּ בתרועה׃');
INSERT INTO verses VALUES (14389, 19, 33, 4, 'porque ישׁר palavra-de yhwh e-todo מַעֲשֵׂהוּ בֶּאֱמוּנָֽה׃');
INSERT INTO verses VALUES (14390, 19, 33, 5, 'amou justiça e-juízo bondade yhwh cheia a-terra');
INSERT INTO verses VALUES (14391, 19, 33, 6, 'em-palavra-de yhwh céus נַעֲשׂ֑וּ וּבְר֥וּחַ פִּ֝֗יו todo exércitos-deles');
INSERT INTO verses VALUES (14392, 19, 33, 7, 'כֹּנֵ֣ס כַּ֭נֵּד águas-de o-mar deu בְּאֹצָר֣וֹת תְּהוֹמֽוֹת׃');
INSERT INTO verses VALUES (14393, 19, 33, 8, 'יִֽירְא֣וּ מֵ֭יְהוָה todo nós מִמֶּ֥נּוּ יָ֝ג֗וּרוּ todo habitantes-de תֵבֵֽל׃');
INSERT INTO verses VALUES (14394, 19, 33, 9, 'que ele disse E-foi ele צִ֝וָּ֗ה וֽ͏ַיַּעֲמֹֽד׃');
INSERT INTO verses VALUES (14395, 19, 33, 10, 'yhwh הֵפִ֥יר conselho- nações הֵ֝נִ֗יא מַחְשְׁב֥וֹת עַמִּֽים׃');
INSERT INTO verses VALUES (14396, 19, 33, 11, 'עֲצַ֣ת yhwh para-sempre תּוֹאֲמֹד מַחְשְׁב֥וֹת לִבּוֹ le-dor וָדֹר׃');
INSERT INTO verses VALUES (14397, 19, 33, 12, 'אַשְׁרֵי הַגּוֹי que yhwh Elohim-seu הָעָם ׀ בָּחַר לְנַחֲלָה');
INSERT INTO verses VALUES (14398, 19, 33, 13, 'מִשּׁׂאָרֵי מָע֫וֹן híbbit yhwh ver a o-homem filhos-de o-homem');
INSERT INTO verses VALUES (14399, 19, 33, 14, 'mimmékcoon- shibatto'' a El a-terra habitantes-de a-terra');
INSERT INTO verses VALUES (14400, 19, 33, 15, 'hayyóts''er יַ֣חַד coracoes-eles hamméviben a todo maásáyehem:');
INSERT INTO verses VALUES (14401, 19, 33, 16, 'não-há hammalké'' nosha''á בְּרָב־ força gibbór não yinnatsé''l בְּרָב־ FORÇA:');
INSERT INTO verses VALUES (14402, 19, 33, 17, 'MENTIRA O-CABALLO PARA-RESGATE E-POR-MUITOS SEU-EIXO não יִמְלַט׃');
INSERT INTO verses VALUES (14403, 19, 33, 18, 'eis olho yhwh a SUAS-TEMERORES PARA-MONTADORES PARA-SUA-GRACIA:');
INSERT INTO verses VALUES (14404, 19, 33, 19, 'PARA-LIVRAR morta almas e os vivificar bar''ava:');
INSERT INTO verses VALUES (14405, 19, 33, 20, 'nossas almas engolir para-יהוה nosso auxílio e nossa fortaleza ele');
INSERT INTO verses VALUES (14406, 19, 33, 21, 'porque nele alegrar-se-á que porque em nome de seu-santo nos-batemos;');
INSERT INTO verses VALUES (14407, 19, 33, 22, 'será yhwh yhwh sobre-nós como para-ti para-ti');
INSERT INTO chapters VALUES (512, 19, 34, 23);
INSERT INTO verses VALUES (14408, 19, 34, 1, 'para-David em-suas-annos a sabor-seu diante-de Avimélek e-o-gerará E-andou');
INSERT INTO verses VALUES (14409, 19, 34, 2, 'abençoe a yhwh em-todo o-tempo sempre sua-hinos em-sua-boca;');
INSERT INTO verses VALUES (14410, 19, 34, 3, 'בַּ֭יהוָה תִּתְהַלֵּ֣ל minha-alma ouvirão os humildes וְיִשָׂמָֽחוּ׃');
INSERT INTO verses VALUES (14411, 19, 34, 4, 'גַּדְּל֣וּ a-yhwh comigo וּנְרוֹמְמָ֖ה שְׁמ֣וֹ juntos-verso');
INSERT INTO verses VALUES (14412, 19, 34, 5, 'דָּרַ֣שְׁתִּי a yhwh וְעָנָ֑נִי e-de-todo מְ֝גוּרוֹתַ֗י הִצִּילָֽנִי׃');
INSERT INTO verses VALUES (14413, 19, 34, 6, 'híbbitu a-ele vénaharú úfénêhem a יִחְפֹּֽרוּ׃');
INSERT INTO verses VALUES (14414, 19, 34, 7, 'este afligido chamou e-יהוה ouviu e-de-todo tsarátovây hóshiúvo');
INSERT INTO verses VALUES (14415, 19, 34, 8, 'chônehe anjo-de yhwh sáviv líyréa''ay váyeḥallatzem');
INSERT INTO verses VALUES (14416, 19, 34, 9, 'tasteuem eureuem porque yhwh yhwh felizesse o homem será misericordioso em-ele');
INSERT INTO verses VALUES (14417, 19, 34, 10, 'e vereuem a yhwh santosseus porque não-há falta para os que temem');
INSERT INTO verses VALUES (14418, 19, 34, 11, 'como gafanhotos רָשׁוּ וְרָעֵ֑בוּ וְדֹרְשֵׁ֥י yhwh não יַחְסְר֥וּ todo bom');
INSERT INTO verses VALUES (14419, 19, 34, 12, 'לְֽכוּ־ בָ֭נִים ouvi yhwh יִֽרְאַ֥ת yhwh אֲלַמֶּדְכֶֽם׃');
INSERT INTO verses VALUES (14420, 19, 34, 13, 'quem o homem vida vivos amou para-ver bom bom');
INSERT INTO verses VALUES (14421, 19, 34, 14, 'נְצֹ֣ר לְשׁוֹנְךָ֣ מֵרָ֑ע e-as-vossas-bocas מדדבר fraude');
INSERT INTO verses VALUES (14422, 19, 34, 15, 'vire-se de-mau e-faze- bom pequisar שָלוֹם e-persegui-lo-que-ele-fez:');
INSERT INTO verses VALUES (14423, 19, 34, 16, 'os-olhos-de yhwh a justos e-seus-ouvidos a seus-gemidos:');
INSERT INTO verses VALUES (14424, 19, 34, 17, 'face-de yhwh fazentes-de mal לְהַכְרִ֖ית da-terra sua-memória:');
INSERT INTO verses VALUES (14425, 19, 34, 18, 'chamaram e-יהוה ouviu e-de-todo suas-angústias הִצִּילָֽם׃');
INSERT INTO verses VALUES (14426, 19, 34, 19, 'קָר֣וֹב yhwh לְנִשְׁבְּרֵי־ coração e-a דַּכְּאֵי־ espírito יוֹשִֽׁיעַ׃');
INSERT INTO verses VALUES (14427, 19, 34, 20, 'רַ֭בּוֹת רָע֣וֹת justo וּ֝מִכֻּלּ֗ם יַצִּילֶ֥נּוּ yhwh');
INSERT INTO verses VALUES (14428, 19, 34, 21, 'guardando todo uma uma não não נִשְׁבָּֽרָה׃');
INSERT INTO verses VALUES (14429, 19, 34, 22, 'תּוֹמֵת ímpio maldade וְשֹׂנְאֵי justo יֶאְשָֽׁמוּ׃');
INSERT INTO verses VALUES (14430, 19, 34, 23, 'פּוֹדֶה yhwh alma servos-dele e-não יֶ֝אְשְׁמ֗וּ todo הַחֹסִ֥ים em-ele');
INSERT INTO chapters VALUES (513, 19, 35, 28);
INSERT INTO verses VALUES (14431, 19, 35, 1, 'para-David רִיבָ֣ה yhwh yhwh יְרִיבַ֑י לְחַ֗ם a לֹֽחֲמָֽי׃');
INSERT INTO verses VALUES (14432, 19, 35, 2, 'הַחֲזֵ֣ק escudo-de e ziná e qúmá por minha auxílio:');
INSERT INTO verses VALUES (14433, 19, 35, 3, 'e hárake chániyt e ségor ao-encontro-de que me perseguiam disse para minha alma sua salvação eu');
INSERT INTO verses VALUES (14434, 19, 35, 4, 'se-envergonhem e se apacigüem מְבַקְשֵׁ֢י נַ֫פְשִׁ֥י יִסֹּ֣גוּ אָח֣וֹר וְיַחְפְּר֑וּ חֹ֝שְׁבֵ֗י רָעָתִֽי׃');
INSERT INTO verses VALUES (14435, 19, 35, 5, 'יִֽהְי֗וּ כְּמֹ֥ץ diante-de espírito yhwh yhwh דּוֹחֶֽה׃');
INSERT INTO verses VALUES (14436, 19, 35, 6, 'יהי־ דרכם escuridão וחלקלאות yhwh yhwh רדפים׃');
INSERT INTO verses VALUES (14437, 19, 35, 7, 'porque hinam טמנו־ para-mim שחת rishtam hinam חפרו para a minha alma');
INSERT INTO verses VALUES (14438, 19, 35, 8, 'vem-a-lhe destruição não conheceu e possuí-lo que ocultou-se apanhá-lo na destruição ele cairá nela');
INSERT INTO verses VALUES (14439, 19, 35, 9, 'e a minha alma se regozijará em-Javé תָּ֝שִׂישׂ בִּישׁוּעָתֽוֹ׃');
INSERT INTO verses VALUES (14440, 19, 35, 10, 'todo עַצְמוֹתַ֨י ׀ תֹּאמַרְנָה֮ yhwh yhwh quem salvar עָ֭נִי מֵחָזָ֣ק de-ele nós וְ֝אֶבְי֗וֹן מִגֹּזְלֽוֹ׃');
INSERT INTO verses VALUES (14441, 19, 35, 11, 'יְ֭קוּmoּן עֵדֵ֣י חָמָס que não יָדַעְתִּי יִשְׁאָלֽוּנִי׃');
INSERT INTO verses VALUES (14442, 19, 35, 12, 'יְשַׁלְּמ֣וּנִי רָ֭עָה debaixo טוֹבָ֗ה שְׁכ֣וֹל para a minha alma');
INSERT INTO verses VALUES (14443, 19, 35, 13, 'e-eu בַּחֲלוֹתָ֡ם לְב֬וּשִׁי שָׂ֗ק איני בצום minha-alma וּתְפִלָּתִי sobre חכי תשוב');
INSERT INTO verses VALUES (14444, 19, 35, 14, 'כרא- כאח para-mim התהלכתי כאבל- mãe קדר שַׁחֹתִי׃');
INSERT INTO verses VALUES (14445, 19, 35, 15, 'וּבְצַלְעִי֮ שָׂמְח֢וּ וְֽנֶאֱ֫סָ֥פוּ נֶאֶסְפ֬וּ sobre-mim נֵ֭כִים e-não יָדַ֑עְתִּי קָרְעוּ e-não דָֽמּוּ׃');
INSERT INTO verses VALUES (14446, 19, 35, 16, 'בְּ֭חַנְפֵי para os Ma''og Charok sobre-mim seus dentes');
INSERT INTO verses VALUES (14447, 19, 35, 17, 'Adonai como vês retornou minha-alma de seus despojos dos Cefarim minha-unidade;');
INSERT INTO verses VALUES (14448, 19, 35, 18, 'adoro-te בְּקָהָ֣ל muito בְּעַ֖ם עָצ֣וּם אֲהַֽלְלֶֽךָּ׃');
INSERT INTO verses VALUES (14449, 19, 35, 19, 'a יִשְׂמְחוּ־ a-mim ʾōyevay שֶׁ֑קֶר שֹׂנְאַ֥י hinam יִקְרְצוּ־ olho');
INSERT INTO verses VALUES (14450, 19, 35, 20, 'que não shalom יְדַ֫בֵּ֥רוּ e-sobre רִגְעֵי־ terra palavras-de מִ֝רְmmoּת יַחֲשֹׁבוּן׃');
INSERT INTO verses VALUES (14451, 19, 35, 21, 'וַיַּרְחִ֥יבוּ עָלַ֗י פִּ֫יהֶ֥ם אָ֭מְרוּ הֶאָ֣ח ׀ הֶאָ֑ח רָאֲתָ֥ה nosso olhos:');
INSERT INTO verses VALUES (14452, 19, 35, 22, 'רָאִ֣יתָה yhwh a תֶּחֱרַ֑שׁ Adonai a תִּרְחַ֥ק de-mim');
INSERT INTO verses VALUES (14453, 19, 35, 23, 'הָעִ֣ירָה וְ֭הָקִיצָה לְמִשְׁפָּטִ֑י Elohim-meu וַֽאדֹנָ֣י לְרִיבִֽי׃');
INSERT INTO verses VALUES (14454, 19, 35, 24, 'שָׁפְטֵ֣נִי כְ֭צִדְקְךָ yhwh Elohim-meu e-a יִשְׂמְחוּ־ para-mim');
INSERT INTO verses VALUES (14455, 19, 35, 25, 'a dirão בליבָּם הֶאָ֣ח נַפְשֵׁ֑נוּ a יֹ֝אמְר֗וּ בִּֽלַּעֲנֽוּהוּ׃');
INSERT INTO verses VALUES (14456, 19, 35, 26, 'יֵ֘בֹ֤שׁוּ וְיַחְפְּר֨וּ ׀ יַחְדָּו֮ שְׂמֵחֵ֢י רָעָ֫תִ֥י serão vestidos vergonha e vergonha sobre-mim');
INSERT INTO verses VALUES (14457, 19, 35, 27, 'serão envergonhados e se alegrarão desejos justiça e dirão sempre será exaltado yhwh o desejo a paz seu-servo');
INSERT INTO verses VALUES (14458, 19, 35, 28, 'וּ֭לְשׁוֹנִי será proferida sua justiça todo hoje será teu louvor:');
INSERT INTO chapters VALUES (514, 19, 36, 13);
INSERT INTO verses VALUES (14459, 19, 36, 1, 'para o vencedor para o servo yhwh le-david');
INSERT INTO verses VALUES (14460, 19, 36, 2, 'oráculo-de a transgressão ao pecador em-meio-de meu-coração nao-ha-  פּ-חַד  Elohim diante-de os-seus-olhos');
INSERT INTO verses VALUES (14461, 19, 36, 3, 'porque a-ele a-ele em-olhos-dele  לִמְצֹ-א   עֲוֺ-נוֹ   לִשׂ-נֹ-א');
INSERT INTO verses VALUES (14462, 19, 36, 4, 'דּ-בְרֵי-   פִ-יּוֹ   אָ-וֶן   וּמִ-רְמָה   חָדַ-ל   לְהַשׂ-כּוֹל  para bem-aventurado:');
INSERT INTO verses VALUES (14463, 19, 36, 5, 'a-véen ⁄ jach-shoab sobre de-sheb-wo yi-ti-tsav sobre caminho mal não mau não yi-mas:');
INSERT INTO verses VALUES (14464, 19, 36, 6, 'yhwh be-ha-shamayim chasdekha e-munathakha até de brilho');
INSERT INTO verses VALUES (14465, 19, 36, 7, 'tsidqathakha ⁄ כְּֽהַרְרֵי־ El מִ֭שְׁפָּטֶךָ abismo multiplicai אָ֤דָֽם־ וּבְהֵמָ֖ה yhwh yhwh');
INSERT INTO verses VALUES (14466, 19, 36, 8, 'que יָּקָ֥ר teu-chesed Elohim homem homem em-a-sombra כְּ֝נָפֶ֗יךָ יֶחֱסָיֽוּן׃');
INSERT INTO verses VALUES (14467, 19, 36, 9, 'יִ֭רְוִיֻן מִדֶּ֣שֶׁן בֵּיתֶ֑ךָ וְנַ֖חַל עֲדָנֶ֣יךָ תַשְׁקֵֽם׃');
INSERT INTO verses VALUES (14468, 19, 36, 10, 'porque עִ֭מְּךָ vida vivos בְּ֝אוֹרְךָ֗ נִרְאֶה־ luz');
INSERT INTO verses VALUES (14469, 19, 36, 11, 'מְשֹׁ֣ךְ Sussana-te לְיֹדְעֶ֑יךָ וְ֝צִדְקָֽתְךָ֗ לְיִשְׁרֵי־ coração');
INSERT INTO verses VALUES (14470, 19, 36, 12, 'a תְּ֭בוֹאֵנִי רגל גַּאֲוָ֑ה e a mão- os-malvados a תנדני׃');
INSERT INTO verses VALUES (14471, 19, 36, 13, 'nome נפלוּ  Paoloֵי iniquidade  Doughוּ e-não  יכלוּ levantou');
INSERT INTO chapters VALUES (515, 19, 37, 40);
INSERT INTO verses VALUES (14472, 19, 37, 1, 'para-davi a  תתחאר  במרועים a  תתקnea׃  בעושיים avareza:');
INSERT INTO verses VALUES (14473, 19, 37, 2, 'que כֶ֭חָצִיר מְהֵרָ֣ה יִמָּ֑לוּ וּכְיֶ֥רֶק דֶּ֝֗שֶׁא יִבּוֹלֽוּן׃');
INSERT INTO verses VALUES (14474, 19, 37, 3, 'בְּטַ֣ח בַּ֭יהוָה e-faze- bom שְׁכָן־ terra וּרְעֵ֥ה אמונה׃');
INSERT INTO verses VALUES (14475, 19, 37, 4, 'וְהִתְעַנַּ֥ג sobre yhwh וְיִֽתֶּן־ לְ֝ךָ֗ מִשְׁאֲלֹ֥ת לִבֶּֽךָ׃');
INSERT INTO verses VALUES (14476, 19, 37, 5, 'גּ֣וֹל sobre yhwh דַּרְכֶּ֑ךָ וּבְטַ֥ח עָ֝לָ֗יו e-ele ele-fará');
INSERT INTO verses VALUES (14477, 19, 37, 6, 'e-fará-sair como-OR sua justiça e-mish-fá-te-kha como-tzáz-har-ay-im');
INSERT INTO verses VALUES (14478, 19, 37, 7, 'dom para-Yah e-ticholé-l a-ele a-ele titchár no-matzlí-akh caminho dele no-ésh fez mízmōt:');
INSERT INTO verses VALUES (14479, 19, 37, 8, 'levantou-se mê''āf va''ăzōv חֵמָ֑ה a tittakhăr somente- ləhārēʻa:');
INSERT INTO verses VALUES (14480, 19, 37, 9, 'porque מרעים yikkăretūn yhwh yhwh eles yirshû- terra');
INSERT INTO verses VALUES (14481, 19, 37, 10, 'וְע֣וֹד מְ֭עַט e-não-há ímpio vehitbōnnātă sobre mēqōmō ve''ēnnū:');
INSERT INTO verses VALUES (14482, 19, 37, 11, 'va''ănāvîm irão- terra e se alegrarão- sobre muito paz');
INSERT INTO verses VALUES (14483, 19, 37, 12, 'que planeja- ímpio contra o justo- e se separarão- sobre-ele suas gengivas;:');
INSERT INTO verses VALUES (14484, 19, 37, 13, 'Adonai rirá- a-ele porque viu porque virá seu dia;:');
INSERT INTO verses VALUES (14485, 19, 37, 14, 'espada abrirão- reshaim e seus caminhos קַ֫שְׁתּ֥ם לְ֭הַפִּיל afligido וְאֶבְי֑וֹן לִ֝טְב֗וֹחַ retos- caminho');
INSERT INTO verses VALUES (14486, 19, 37, 15, 'חַ֭רְבָּם תָּב֣וֹא בְּלִבֵיהֶם וְ֝קַשְּׁתוֹתָ֗ם תִּשָּׁבַֽרְנָה׃');
INSERT INTO verses VALUES (14487, 19, 37, 16, 'טוֹב־ מְ֭עַט contra o justo- de hamon os ímpios muitos');
INSERT INTO verses VALUES (14488, 19, 37, 17, 'que as suas mãos ímpios serão quebradas e sustentará justos yhwh');
INSERT INTO verses VALUES (14489, 19, 37, 18, 'que conhece yhwh dias-de temimim e a sua herança para-sempre será');
INSERT INTO verses VALUES (14490, 19, 37, 19, 'não terão vergonha na época maldade e-nos-dias רְעָב֣וֹן יִשְׂבָּֽעוּ׃');
INSERT INTO verses VALUES (14491, 19, 37, 20, 'que רְשָׁעִ֨ים ׀ יֹאבֵ֗דוּ וְאֹיְבֵ֣י yhwh yhwh כָּרִ֑ים כָּל֖וּ בֶעָשָׁ֣ן כָּֽלוּ׃');
INSERT INTO verses VALUES (14492, 19, 37, 21, 'לֹוֶ֣ה ímpio e-não יְשַׁלֵּם וְ֝צַדִּ֗יק חוֹנֵ֥ן וְנוֹתֵֽן׃');
INSERT INTO verses VALUES (14493, 19, 37, 22, 'que מְ֭בֹרָכָיו יִ֣ירְשׁוּ terra וּ֝מְקֻלָּל֗יו יִכָּרֵֽתוּ׃');
INSERT INTO verses VALUES (14494, 19, 37, 23, 'מֵ֭יְהוָה מִֽצְעֲדֵי־ גֶ֥בֶר כוננוּ ודרכוֹ יחףָץ׃');
INSERT INTO verses VALUES (14495, 19, 37, 24, 'porque cairá não يوוטָל sua-mão yhwh סומךֶ ידֽוֹ׃');
INSERT INTO verses VALUES (14496, 19, 37, 25, 'נער֤ hayiti֗ também זוקנתִי e-não ראיתי֭ justo נֶעֱזָ֑ב e seu fruto מְבַקֵּשׁ־ pão');
INSERT INTO verses VALUES (14497, 19, 37, 26, 'todo o-hoje חוֹנֵ֣ן וּמַלְוֶ֑ה e seu fruto לִבְרָכָֽה׃');
INSERT INTO verses VALUES (14498, 19, 37, 27, 'vire-se de-mau e-faze- bom וּשְׁכֹ֥ן para-eternidade');
INSERT INTO verses VALUES (14499, 19, 37, 28, 'que yhwh amou מִשְׁפָּ֗ט e-não יַעֲזֹ֣ב a חֲ֭סִידָיו para-sempre נִשְׁמָ֑רוּ e semente ímpios será cortado;');
INSERT INTO verses VALUES (14500, 19, 37, 29, 'justos herdarão terra e habitarão para sempre sobre-ela');
INSERT INTO verses VALUES (14501, 19, 37, 30, 'boca-de justo haverá sabedoria e sua língua falará juízo');
INSERT INTO verses VALUES (14502, 19, 37, 31, 'lei-de seu Elohim בַּלִּבּוֹ não se manterá em silêncio');
INSERT INTO verses VALUES (14503, 19, 37, 32, 'צופנה  ímpio contra o justo-  e-metendo-se   para-a-matar');
INSERT INTO verses VALUES (14504, 19, 37, 33, 'yhwh não  abandonará-o   por-sua-mão  e-não  julgará-o   no-sua-jurisdição');
INSERT INTO verses VALUES (14505, 19, 37, 34, 'ele-olhará a yhwh e-guardará דרכו וירוממך para-possuir terra בהכרת ímpios você-ver-irá');
INSERT INTO verses VALUES (14506, 19, 37, 35, 'ראיתי֭ ímpio עריץ ומתערה כאזרח רענן׃');
INSERT INTO verses VALUES (14507, 19, 37, 36, 'WAYYAVOR e-eis איןנו ואבקשוּ e-não נִמְצָֽא׃');
INSERT INTO verses VALUES (14508, 19, 37, 37, 'שָׁמַר- טָמֵם e-vê יָשָׁר porque אַחֲרִית a homem-de paz');
INSERT INTO verses VALUES (14509, 19, 37, 38, 'וּפֹשְׁעִים נִשְׂמַדּוּ juntos אַחֲרִית ímpios נִכְרָתָה׃');
INSERT INTO verses VALUES (14510, 19, 37, 39, 'וּתְשׁוּעַת justos de-yhwh ma-utzam na época angústia');
INSERT INTO verses VALUES (14511, 19, 37, 40, 'va-etzreim yhwh va-pallateim yepallatem me-rasha''im ve-yosheim porque nele nele-verso');
INSERT INTO chapters VALUES (516, 19, 38, 23);
INSERT INTO verses VALUES (14512, 19, 38, 1, 'mizmor a-David le-hazkir');
INSERT INTO verses VALUES (14513, 19, 38, 2, 'yhwh a em-teu-ira corrigires-nos e-em-teu-ardor disciplinares-nos;');
INSERT INTO verses VALUES (14514, 19, 38, 3, 'porque seus-setes foram-penetrados bi e-te-deram sobre-mim יָדֶֽךָ׃');
INSERT INTO verses VALUES (14515, 19, 38, 4, 'não-há finalmente de-diante-de de-diante-de teu-zelo não-há de-diante-de em-meus-internos de-faces-de  חטָאִי׃');
INSERT INTO verses VALUES (14516, 19, 38, 5, 'que  עֲוֺנֹתַי  abru cabeça-de mim  כְּמַשָּׂ֥א   כָ֝בֵ֗ד   יִכְבְּד֥וּ  de-mim');
INSERT INTO verses VALUES (14517, 19, 38, 6, 'הִבְאִ֣ישׁוּ   נָ֭מַקּוּ   חַבּוּרֹתָ֑י  de-diante-de  אִוַּלְתִּֽי׃');
INSERT INTO verses VALUES (14518, 19, 38, 7, 'נַעֲוֵ֣יתִי  שַׁחֲתִּי até muito todo o-hoje קדר הִלַּכְתִּי׃');
INSERT INTO verses VALUES (14519, 19, 38, 8, 'porque כְ֭סָלַי serão-cheias נִקְלֶה e-não-há מְתוּם בַּבְשָׂרִי׃');
INSERT INTO verses VALUES (14520, 19, 38, 9, 'נְפוּגֹתִי וְנִדְכֵּיתִי até muito שָׁאַגְתִּי מִנַּהֲמַת no meu coração:');
INSERT INTO verses VALUES (14521, 19, 38, 10, 'נֶגְדּךָ todo תַּאֲוָתִי וְאַנְחָתִי de-tu não נִסְתּרָה׃');
INSERT INTO verses VALUES (14522, 19, 38, 11, 'לִבִּ֣י סְחַרְחַר עֲזָבַנִי כֹחִ֑י וְאוֹר־ minha-olho também הֵ֗ם não-há comigo:');
INSERT INTO verses VALUES (14523, 19, 38, 12, 'minha-amor e-meu-amigo desde-em-frente-de tou-tei estão-se e-meus-proximos de-longe estavam:');
INSERT INTO verses VALUES (14524, 19, 38, 13, 'e-quebraram: os-procuradores minha-alma וְדֹרְשֵׁ֣י רָ֭עָתִי falaram הַוּ֑וֹת וּ֝מִרְמ֗וֹת todo o-dia יֶהְגּֽוּ׃');
INSERT INTO verses VALUES (14525, 19, 38, 14, 'e-eu כְ֭חֵרֵשׁ não אֶשְׁמָ֑ע וּ֝כְאִלֵּ֗ם não יִפְתַּח־ פי׃');
INSERT INTO verses VALUES (14526, 19, 38, 15, 'וָאֱהִ֗י כְּ֭אִישׁ que não ouviu e-não-há בְּ֝פִ֗יו תּוֹךָֽחוֹת׃');
INSERT INTO verses VALUES (14527, 19, 38, 16, 'porque yhwh yhwh tu tu תַ֝עֲנֶ֗ה Adonai yhwh');
INSERT INTO verses VALUES (14528, 19, 38, 17, 'porque אָ֭מַרְתִּי para-que-não יִשְׂמְחוּ־ a-mim בְּמ֥וֹט רַ֝גְלִ֗י alai הִגְדִּֽילוּ׃');
INSERT INTO verses VALUES (14529, 19, 38, 18, 'porque Eu לְצֶ֣לַע נָכ֑וֹן e-maçôvî negdî תָמִֽיד׃');
INSERT INTO verses VALUES (14530, 19, 38, 19, 'porque âônî a-gid ê-da-g mê-chattâ''âtî');
INSERT INTO verses VALUES (14531, 19, 38, 20, 've-âoyêvây vida עָצְמוּ verabbû sônê''ây mentira');
INSERT INTO verses VALUES (14532, 19, 38, 21, 'וּמְשַׁלְּמֵ֣י רָ֭עָה debaixo bom-a יִ֝שְׂטְנ֗וּנִי debaixo bom');
INSERT INTO verses VALUES (14533, 19, 38, 22, 'a yhwh yhwh meu-Elohim a תִּרְחַ֥ק de-mim');
INSERT INTO verses VALUES (14534, 19, 38, 23, 'ח֥וּשָׁה לְעֶזְרָתִ֑י Adonai תְּשׁוּעָתִֽי׃');
INSERT INTO chapters VALUES (517, 19, 39, 14);
INSERT INTO verses VALUES (14535, 19, 39, 1, 'ao-regente salmo le-david');
INSERT INTO verses VALUES (14536, 19, 39, 2, 'disse-ei- אֶֽשְׁמְרָ֣ה דְרָכַי֮ מֵחֲט֢וֹא בִלְשׁ֫וֹנִ֥י אֶשְׁמַרְתִּי por מַחְסֹם בּעֹד ímpio לְנֶגְדִּי׃');
INSERT INTO verses VALUES (14537, 19, 39, 3, 'נֵאָלַם דֻּמִּיה הֵחָשַׁתִּי מִטוֹב וּכְאֵבִי נֵעַכְרֶה׃');
INSERT INTO verses VALUES (14538, 19, 39, 4, 'חַם־ לִבִּ֨י ׀ בְּקִרְבִּ֗י בַּהֲגִיגִ֥י תִבְעַר־ fogo דִּ֝בַּ֗רְתִּי בִּלְשֽׁוֹנִי׃');
INSERT INTO verses VALUES (14539, 19, 39, 5, 'הוֹדִ֘יעֵ֤נִי yhwh קִצִּ֗י וּמִדַּ֣ת יָמַ֣י que ela -initialized que has-delayed eu:');
INSERT INTO verses VALUES (14540, 19, 39, 6, 'eis palmas- gave-you- deste and-dreams- like-a opposite-you- entretanto todo הֶבֶל todo homem stood sela');
INSERT INTO verses VALUES (14541, 19, 39, 7, 'somente in-the-image-of- will-walk- homem somente הֶבֶל יֶהֱמָ֑יוּן יִ֝צְבֹּ֗ר e-não conheceu quem אֹסְפָֽם׃');
INSERT INTO verses VALUES (14542, 19, 39, 8, 'e-agora que קִוּ֣יתִי Adonai a-ti para-ti ela');
INSERT INTO verses VALUES (14543, 19, 39, 9, 'de-todo פְּשָׁעַ֥י הַצִּילֵ֑נִי desonra נָ֝בָ֗ל a תְּשִׂימֵֽנִי׃');
INSERT INTO verses VALUES (14544, 19, 39, 10, 'נֶ֭אֱלַמְתִּי não אֶפְתַּח־ que tu tu fiz-te');
INSERT INTO verses VALUES (14545, 19, 39, 11, 'הסר מֵעָלַ֣י נגעך מתגרת ידך eu כליתי');
INSERT INTO verses VALUES (14546, 19, 39, 12, 'בתוכחתוות sobre עון יסרטה homem ותמס כעש חֲמוּדוֹ entretanto הֶ֖בֶל todo homem sela');
INSERT INTO verses VALUES (14547, 19, 39, 13, 'שִֽׁמְעָה־ תְפִלָּתִ֨י ׀ yhwh וְשַׁוְעָתִ֨י ׀ הַאֲזִינָה֮ a דִּמְעָתִ֗י a que porque eu eu contigo תּ֝וֹשָׁ֗ב conforme-toda אֲבוֹתָֽי׃');
INSERT INTO verses VALUES (14548, 19, 39, 14, 'הָשַׁ֣ע מִמֶּ֣נִּי וְאַבְלִ֑יגָה antes-de irei וְאֵינֶֽנִּי׃');
INSERT INTO chapters VALUES (518, 19, 40, 18);
INSERT INTO verses VALUES (14549, 19, 40, 1, 'לַ֝מְנַצֵּ֗חַ para-davíd salmo');
INSERT INTO verses VALUES (14550, 19, 40, 2, 'קַוֺּ֣ה קִוּ֣יתִי yhwh e-virou אֵ֝לַ֗י E-ouviu שַׁוְעָתִֽי׃');
INSERT INTO verses VALUES (14551, 19, 40, 3, 'וַיַּעֲלֵ֤נִי ׀ מִבּ֥וֹר שָׁאוֹן֮ מִטִּ֢יט הַיָּ֫וֵ֥ן E-levantou sobre סֶ֥לַע רַגְלַ֗י כּוֹנֵ֥ן אֲשֻׁרָֽי׃');
INSERT INTO verses VALUES (14552, 19, 40, 4, 'E-colocou בְּפִ֨י ׀ cântico novo תְּהִלָּ֢ה לֵֽאלֹ֫הֵ֥ינוּ e-verão muitos וְיִירָ֑אוּ e se fortalecerão no耶和华׃');
INSERT INTO verses VALUES (14553, 19, 40, 5, 'Ashrei o homem que nome yhwh מִבְטַח֑וֹ e-não virou-se a largos e os כָזָֽב׃');
INSERT INTO verses VALUES (14554, 19, 40, 6, 'muitos tu fizeste você tu Elohim yhwh e-as-máquinas-te nos-so ain estendido a-ti eu-direi e-eu-falar em-si-mesmo que-conta');
INSERT INTO verses VALUES (14555, 19, 40, 7, 'sacrifício e-oferta não desejaste ouvidos cortaste a-mim holocausto e pecado não eu perguntei');
INSERT INTO verses VALUES (14556, 19, 40, 8, 'então disse eu eis-que- venho-eu em rolo de escrito escrito sobre-mim');
INSERT INTO verses VALUES (14557, 19, 40, 9, 'para fazer seu desejo Elohim-me eu-queri no-meio-de em-meio-de dos-entres-colos');
INSERT INTO verses VALUES (14558, 19, 40, 10, 'anunciarei justiça assembleia muito eis eis não não yhwh yhwh tu');
INSERT INTO verses VALUES (14559, 19, 40, 11, 'a-tua-justiça não cobrirei no-meio-de meu-coracao a-tua-fidelidade e-a-tua-salvação eu-disse não כִיחַ֥דְתִּי חַסְדְּךָ֥ וַאֲמִתְּךָ֗ לְקָהָ֥ל muito');
INSERT INTO verses VALUES (14560, 19, 40, 12, 'tu yhwh não תִכְלָ֣א רַחֲמֶ֣יךָ de-mim חַסְדְּךָ֥ וַאֲמִתְּךָ֗ תָּמִ֥יד יִצְּרֽוּנִי׃');
INSERT INTO verses VALUES (14561, 19, 40, 13, 'que אָפְפ֥וּ- עָלַ֨י ׀ רָע֡וֹת até אֵ֬ין מִסְפָּ֗ר הִשִּׂיג֣וּנִי  עֲוֺנֹתַי  para-ver יָכֹ֣לְתִּי לִרְא֑וֹת עָצְמ֥וּ מִשַֽׂעֲר֥וֹת cabeça-minha e-me abandonei;');
INSERT INTO verses VALUES (14562, 19, 40, 14, 'quer yhwh para-me-resgatar yhwh לְעֶזְרָ֥תִי חֽוּשָׁה׃');
INSERT INTO verses VALUES (14563, 19, 40, 15, 'vergonhar-se-ão וְיַחְפְּר֨וּ ׀ juntos que-pesquisam minha-alma suas-línguas sugiram אָחוֹר וְיִכָּלְמ֑וּ חֲפֵץֵי רָעָתִֽי׃');
INSERT INTO verses VALUES (14564, 19, 40, 16, 'יָשֹׁמּוּ sobre ekev בָּשְׁתָּ֑ם הָאֹמְרִ֥ים לִֽי׃ הֶאָ֥ח הֶאָֽח׃');
INSERT INTO verses VALUES (14565, 19, 40, 17, 'יָשִׂ֤ישׂוּ וְיִשְׂמַחוּ ׀ בְּךָ֗ todo מְבַ֫קְשֶׁ֥יךָ dirão sempre será exaltado yhwh אֹֽ֝הֲבֵ֗י תְּשׁוּעָתֶֽךָ׃');
INSERT INTO verses VALUES (14566, 19, 40, 18, 'e-eu afligido וְאֶבְיוֹן֮ Adonai יַחֲשָׁ֫ב para-mim עֶזְרָתִ֣י e-me-refugiar  אַ֑תָּה tu a esperar;');
INSERT INTO chapters VALUES (519, 19, 41, 14);
INSERT INTO verses VALUES (14567, 19, 41, 1, 'ao-regente salmo le-david');
INSERT INTO verses VALUES (14568, 19, 41, 2, 'feliz מַשְׂכּ֣יל a דל em-dia רָ֝עָה yhwh yhwh');
INSERT INTO verses VALUES (14569, 19, 41, 3, 'yhwh guardá-lo e-viver-lhe em-a-terra e-a dar-lhe בְּנֶ֣פֶשׁ oyevav');
INSERT INTO verses VALUES (14570, 19, 41, 4, 'yhwh sustentar-o sobre leito-de por-meus todo de-seu-leito inverteste-me em-suas-roupas:');
INSERT INTO verses VALUES (14571, 19, 41, 5, 'eu-me- yhwh yhwh tenha-me-compasión cura-me minha-alma para-ti sou-pecador para-ti');
INSERT INTO verses VALUES (14572, 19, 41, 6, 'meus-inimigos dirão mau a-mim quando morram e-se-exterminem nome-dele');
INSERT INTO verses VALUES (14573, 19, 41, 7, 'e-se para-ver para-ver שָׁ֤וְא יְדַבֵּ֗ר coração-dele יִקְבָּץ־ a-ele a-ele sairá לַח֣וּץ יְדַבֵּֽר׃');
INSERT INTO verses VALUES (14574, 19, 41, 8, 'יַ֗חַד sobre-mim יִ֭תְלַחֲשׁוּ todo שֹׂנְאָ֑י עָלַ֓י ׀ יַחְשְׁב֖וּ mal para-mim');
INSERT INTO verses VALUES (14575, 19, 41, 9, 'דְּֽבַר־ בליעל יָצ֣וּק nele e-que שָׁ֝כַ֗ב não יוֹסִ֥יף לָקֽוּם׃');
INSERT INTO verses VALUES (14576, 19, 41, 10, 'também homem שְׁלוֹמִ֨י ׀ que nele nele אוֹכֵ֣ל לַחְמִ֑י הִגְדִּ֖יל calcanhar calcanhar');
INSERT INTO verses VALUES (14577, 19, 41, 11, 'e-tu yhwh חָנֵּ֥נִי e levanta-me e eu pagarei a-eles');
INSERT INTO verses VALUES (14578, 19, 41, 12, 'com-isto ידעתי porque chapatzta que porque não alegrar-se-á meu inimigo sobre-mim');
INSERT INTO verses VALUES (14579, 19, 41, 13, 'e-eu em meu meio tu me suportaste em-mim e puseste-me diante de ti para-sempre');
INSERT INTO verses VALUES (14580, 19, 41, 14, 'bendito yhwh Elohim-de Israel dos eternos e-ate o-mundo אָ֘מֵ֥ן ׀ וְאָמֵֽן׃');
INSERT INTO chapters VALUES (520, 19, 42, 12);
INSERT INTO verses VALUES (14581, 19, 42, 1, 'ao-regente מַשְׂכִּ֥יל para-filhos-de qó-rakh');
INSERT INTO verses VALUES (14582, 19, 42, 2, 'como-aleijadinho vai-gemer sobre apices-de águas assim minha-alma anseia a-você Elohim');
INSERT INTO verses VALUES (14583, 19, 42, 3, 'fomei minha-alma a-elohim a-ael viveu quando eu-vou e-eu-verei face-de face-de');
INSERT INTO verses VALUES (14584, 19, 42, 4, 'hָayְthָa- lּi- pão Léchem dia vָla-yָla- bּe-amֹor- a-mim todo o-hoje ayeh Elohim-tua');
INSERT INTO verses VALUES (14585, 19, 42, 5, 'Estas e-zekּrָa- vְe-shafּpְkָa- עָלַ֨י ׀ minha-alma porque e-evebֹr- que e-dadָdֵm- até casa Elohim com-a-voz-de grito-de-alegria vְeto-da-ha- o tesouro chogֵg-');
INSERT INTO verses VALUES (14586, 19, 42, 6, 'que תִּשְׁתּ֬וֹחֲחִ֨י נַפְשִׁי֮ וַתֶּהֱמִ֢י עָ֫לָ֥י הוֹחִ֣ילִי לֵֽ֭אלֹהִים porque ainda אוֹדֶ֗נּוּ יְשׁוּע֥וֹת faces-suas');
INSERT INTO verses VALUES (14587, 19, 42, 7, 'meu-elohim sobre-mim נַפְשִׁ֢י תִשְׁתּ֫וֹחָ֥ח sobre sim e-zkhrakhā da-terra yarden ve-chermonim me-ha-mar mits''ar');
INSERT INTO verses VALUES (14588, 19, 42, 8, 'tēhom- a à-voz-de qore'' para-voz tsinnorêkha todo mishbārekha ve-gallēkha alai ʿavarū');
INSERT INTO verses VALUES (14589, 19, 42, 9, 'יום-מה יחזעה יהוה yhwh comigo תפללה para-o-elohim חַיָּֽי׃');
INSERT INTO verses VALUES (14590, 19, 42, 10, 'אומרה para-o-elohim סלעי למה שכחתי למה- קדר irei בלחץ inimigo:');
INSERT INTO verses VALUES (14591, 19, 42, 11, 'ברצח em-se-mesmo honra-me engatinhador-me em-suas-palavras a-mim todo o-hoje ayeh teu-Elohim');
INSERT INTO verses VALUES (14592, 19, 42, 12, 'que tornaste-te-murmureira minha-alma e-que tremulares-te sobre-mim insultaste-me Elohim porque ainda אוֹדֶנּוּ יְשׁוּעֹת face-de וֵאֱלֹהָי׃');
INSERT INTO chapters VALUES (521, 19, 43, 5);
INSERT INTO verses VALUES (14593, 19, 43, 1, 'julgue-me Elohim וְרִיבָ֤ה רִיבִ֗י de um povo não חָסִ֑יד מֵאִישׁ־ enganosidade וְעַוְלָ֣ה תְפַלְּטֵֽנִי׃');
INSERT INTO verses VALUES (14594, 19, 43, 2, 'porque você Elohim-de meu-muro por-que tu-me-desertaste por-que- קדר eu-andarei com-pressione inimigo');
INSERT INTO verses VALUES (14595, 19, 43, 3, 'envia- seu-luz e-seu-verdade eles me-sustentem יְבִיא֥וּנִי a monte-de קָ֝דְשְׁךָ֗ e-a מִשְׁכְּנוֹתֶֽיךָ׃');
INSERT INTO verses VALUES (14596, 19, 43, 4, 'וְאָב֤וֹאָה ׀ a מִזְבַּ֬ח Elohim a El שִׂמְחַ֢ת גִּ֫ילִ֥י וְאוֹדְךָ֥ com-lira Elohim yhwh');
INSERT INTO verses VALUES (14597, 19, 43, 5, 'que תִּשְׁתּ֬וֹחֲחִ֨י נַפְשִׁי֮ e-que tremulares-te עָ֫לָ֥י הוֹחִ֣ילִי Elohim porque ainda אוֹדֶנּוּ יְשׁוּעֹת face-de וֵאֱלֹהָי׃');
INSERT INTO chapters VALUES (522, 19, 44, 27);
INSERT INTO verses VALUES (14598, 19, 44, 1, 'לַמְנַצֵּ֬חַ para-filhos-de קֹ֬רַח sabedor:');
INSERT INTO verses VALUES (14599, 19, 44, 2, 'Elohim em-nossos-ouvidos ouvimos nosso-pai-s contaram- para-nós feito-trabalho fizeste em-suas-iddiomas nos-seus-iddiomas oriente');
INSERT INTO verses VALUES (14600, 19, 44, 3, 'tu sua-mão nações ensinaste e-plantaste-lhes tu-seduziste le-ummim vat-shalakhem');
INSERT INTO verses VALUES (14601, 19, 44, 4, 'que não be-charvam yarshu terra uzeromam não hoshia lamo porque yeminecha uzerokhacha que per-ni-kha porque Razitam:');
INSERT INTO verses VALUES (14602, 19, 44, 5, 'você- ele Malchi Elohim Tzavu Yeshuot Jacó');
INSERT INTO verses VALUES (14603, 19, 44, 6, 'em-te Tsarenu Nenagha Beshemakh Navus Qamenu:');
INSERT INTO verses VALUES (14604, 19, 44, 7, 'que não Bekashshi אֶבְטָ֑ח וְ֝חַרְבּ֗י não תוֹשִׁיעֵֽנִי׃');
INSERT INTO verses VALUES (14605, 19, 44, 8, 'que ה֭וֹשַׁעְתָּנוּ מִצָּרֵ֑ינוּ וּמְשַׂנְאֵ֥ינוּ הֱבִישֽׁוֹתָ׃');
INSERT INTO verses VALUES (14606, 19, 44, 9, 'בֵּ֭אלֹהִים הִלַּלְ֣נוּ todo o-dia וְשִׁמְךָ֓ ׀ para-sempre נודדה Selá');
INSERT INTO verses VALUES (14607, 19, 44, 10, 'também זנחת ותכלימנו e-não יצאה בקציבאותינו׃');
INSERT INTO verses VALUES (14608, 19, 44, 11, 'תשבנו אָחוֹר de-mim צר ומשנהינו שסעו a-eles');
INSERT INTO verses VALUES (14609, 19, 44, 12, 'תיתנו כְּצֹ֣אן alimento u-ba-go-yim zirtanu:');
INSERT INTO verses VALUES (14610, 19, 44, 13, 'timkor- povo-teu bela- hon e-não ribitata bimchireyhem:');
INSERT INTO verses VALUES (14611, 19, 44, 14, 'tashimenu cherpeha lishechenenu לַעַג וָקֶ֗לֶס לִסְבִיבוֹתֵֽינוּ׃');
INSERT INTO verses VALUES (14612, 19, 44, 15, 'tashimenu מָ֭שָׁל em-nações מְנֽוֹד־ cabeça não- אֻמִּֽים׃');
INSERT INTO verses VALUES (14613, 19, 44, 16, 'todo o-hoje כְּלִמָּתִ֣י נֶגְדִּ֑י וּבֹ֖שֶׁת face-de כִּסָּֽתְנִי׃');
INSERT INTO verses VALUES (14614, 19, 44, 17, 'de-voz irritante e-irrito de-diante-de inimigo e-reclama');
INSERT INTO verses VALUES (14615, 19, 44, 18, 'todo isto vem-nos e-não esquece-te e-não desonra-te na-tua-aliança');
INSERT INTO verses VALUES (14616, 19, 44, 19, 'não ingresso אָח֣וֹר no-nos e-estendeu nossas-esperanças מִנּוֹ seu-caminho');
INSERT INTO verses VALUES (14617, 19, 44, 20, 'que desviaste-nos em-lugar-de tânis e-ela-cobriu sobre-nós em-suas-imagem');
INSERT INTO verses VALUES (14618, 19, 44, 21, 'se esqueceram-nos nome Elohim-nosso e-espalhamos nossas-mãos para-o-elohim זָר׃');
INSERT INTO verses VALUES (14619, 19, 44, 22, 'porventura-não Elohim יַחֲקָר־ esta sabe ele conheceu תַּעֲלֻמ֥וֹת coração');
INSERT INTO verses VALUES (14620, 19, 44, 23, 'porque עלך הֹרַ֣גְנוּ todo o-dia נֶ֝חְשַׁ֗בְנוּ כְּצֹ֣אן טִבְחָֽה׃');
INSERT INTO verses VALUES (14621, 19, 44, 24, 'ע֤וּרָה ׀ לָ֖מָּה תִישַׁ֥ן ׀ Adonai הָ֝קִ֗יצָה a תִּזְנַ֥ח para sempre;');
INSERT INTO verses VALUES (14622, 19, 44, 25, 'למה- as tuas faces ocultar-te-ás esquecer-te-ás nossa angústia e o nosso opróbrio—;');
INSERT INTO verses VALUES (14623, 19, 44, 26, 'que abaixou-se para a poeira נַפְשֵׁ֑נוּ adere para-a-terra Nosso ventre:');
INSERT INTO verses VALUES (14624, 19, 44, 27, 'Levantai-vos; ajuda nós e libertai-nos; para-que Sua misericórdia:');
INSERT INTO chapters VALUES (523, 19, 45, 18);
INSERT INTO verses VALUES (14625, 19, 45, 1, 'ao sobre flores de jasmim; para-filhos-de  קֹ֑רַח faça שִׁ֣יר amor.');
INSERT INTO verses VALUES (14626, 19, 45, 2, 'רָ֘חַ֤שׁ לִבִּ֨י ׀ palavra bom bom eu-sou מַעֲשַׂ֣י לְמֶ֑לֶךְ לְ֝שׁוֹנִ֗י עֵ֤ט ׀ סוֹפֵ֬ר מָהִֽיר׃');
INSERT INTO verses VALUES (14627, 19, 45, 3, 'יָפְיָפִ֡יתָ מִבְּנֵ֬י homem ה֣וּצַק חֵ֭ן בְּשְׂפְתוֹתֶ֑יךָ sobre assim abencoou-te Elohim para-eternidade');
INSERT INTO verses VALUES (14628, 19, 45, 4, 'חֲגוֹר־ חַרְבְּךָ֣ sobre יָרֵ֣ךְ גִּבּ֑וֹר ה֝וֹדְךָ֗ וַהֲדָרֶֽךָ׃');
INSERT INTO verses VALUES (14629, 19, 45, 5, 'וַהֲדָ֬רְךָ֨ ׀ צְלַ֬ח רְכַב sobre palavra-de verdade וְעַנְוָה־ justiça וְתוֹרְךָ נוֹרָא֣וֹת יְמִינֶֽךָ׃');
INSERT INTO verses VALUES (14630, 19, 45, 6, 'חִצֶּ֗יךָ שְׁנ֫וּנִ֥ים עַ֭מִּים תַּחְתֶּ֣יךָ יִפְּל֑וּ בְּ֝לֵ֗ב de-inimigos o rei');
INSERT INTO verses VALUES (14631, 19, 45, 7, 'כִּסְאֲךָ֣ Elohim eternidade וָעֶ֑ד bastão מִ֝ישֹׁ֗ר tribo-de מַלְכוּתֶֽךָ׃');
INSERT INTO verses VALUES (14632, 19, 45, 8, 'אָהַ֣בְתָּ צֶּדֶק֮ וַתִּשְׂנָ֫א רֶ֥שַׁע sobre כֵּ֤ן ׀ מְשָׁחֲךָ֡ Elohim Elohim שֶֽׁמֶן שַֽׂשְׂון מֵחֲבֵרֶיךָ׃');
INSERT INTO verses VALUES (14633, 19, 45, 9, 'מֹר־ וַאֲהָל֣וֹת קְֽצִיעוֹת todo בִּגְדֹתֶיךָ de הֵ֥יכְלֵי שֵׁ֝֗ן מִנּוֹ שִׂמְּחֽוּךָ׃');
INSERT INTO verses VALUES (14634, 19, 45, 10, 'filhas-de מְ֭לָכִים בּיִקְרֹותֶיךָ נִצַּבָה שׁוֹגַל לִימִינְךָ בְּכֶ֣תֶם opir');
INSERT INTO verses VALUES (14635, 19, 45, 11, 'שׁוּמַע־ bat וּרְאֵה וְהַתִּי אֹזֶןְךָ וְשַׁכְחִי עַמֶּךָ e-casa-de seu-pai:');
INSERT INTO verses VALUES (14636, 19, 45, 12, 'e-te-aventure o-rei fa-la-te-belo porque ele adonai-tu e-te-ador-nezes- a-ele');
INSERT INTO verses VALUES (14637, 19, 45, 13, 'e-filha- cetro com-oferenda tu-rosto serão-alegrados עשׂרי povo');
INSERT INTO verses VALUES (14638, 19, 45, 14, 'todo [בַת־מֶ֣לֶךְ] filha-de rei ouro [לְבוּשָֽׁהּ]');
INSERT INTO verses VALUES (14639, 19, 45, 15, '[לִרְקָמוֹת֮] [תּוּבַ֢ל] [לַ֫מֶּ֥לֶךְ] [בְּתוּל֣וֹת] [אַ֭חֲרֶיהָ] [רֵעוֹתֶ֑יהָ] [מ֖וּבָא֣וֹת] para-ti');
INSERT INTO verses VALUES (14640, 19, 45, 16, '[תּ֭וּבַלְנָה] [בִּשְׂמָחֹ֣ת] [וָגִ֑יל] [תְּ֝בֹאֶ֗ינָה] [בְּהֵ֣יכַל] rei');
INSERT INTO verses VALUES (14641, 19, 45, 17, 'debaixo [אֲ֭בֹתֶיךָ] serão [בָנֶ֑יךָ] [תְּשִׁיתֵ֥מוֹ] [לְ֝שָׂרִ֗ים] em-todo a-terra');
INSERT INTO verses VALUES (14642, 19, 45, 18, 'זכרה שםך em-todo dor וָ dor sobre assim para-sempre יהודך para-sempre para-sempre');
INSERT INTO chapters VALUES (524, 19, 46, 12);
INSERT INTO verses VALUES (14643, 19, 46, 1, 'ao-regente para-filhos-de [עַֽל־עֲלָמ֥וֹת] sobre');
INSERT INTO verses VALUES (14644, 19, 46, 2, 'Elohim לנוּ מחסה ועוז Eráh betsárôt nimtsá muito');
INSERT INTO verses VALUES (14645, 19, 46, 3, 'sobre assim não nirá bhemiráy terra úbemót mares mares mares');
INSERT INTO verses VALUES (14646, 19, 46, 4, 'yehehmú yechmérú meymayv yerá''ásu- as-montanhas em-suas-gaivatas Selá');
INSERT INTO verses VALUES (14647, 19, 46, 5, 'rio seus-fracos serão-alegrados cidades- Elohim santo moradas altíssimo');
INSERT INTO verses VALUES (14648, 19, 46, 6, 'Elohim em-seu-midrado não tremam ajudá-la-á Elohim manhã manhã');
INSERT INTO verses VALUES (14649, 19, 46, 7, 'viram nações derribem מלכות dar בקולו תומג terra');
INSERT INTO verses VALUES (14650, 19, 46, 8, 'yhwh צבאות com-nosso משגבה- לנו Elohim-de Jacó Selá');
INSERT INTO verses VALUES (14651, 19, 46, 9, '[לְֽכוּ־חֲ֭זוּ] [מִפְעֲל֣וֹת] yhwh yhwh que nome');
INSERT INTO verses VALUES (14652, 19, 46, 10, 'משבת מלחמות até a-terra a-terra קֶ֣שֶׁת יְשַׁבֵּר וְקִצֵּ֣ץ arado עֲגָל֗וֹת יִשְׂרֹ֥ף em-a-chama');
INSERT INTO verses VALUES (14653, 19, 46, 11, 'הַרְפּ֣וּ וּ֭דְעוּ porque eu Elohim אָר֥וּם entre-as-nações אָר֥וּם na-terra');
INSERT INTO verses VALUES (14654, 19, 46, 12, 'yhwh צְבָא֣וֹת com-nosso משגבה- לנו- Elohim-de Jacó Selá');
INSERT INTO chapters VALUES (525, 19, 47, 10);
INSERT INTO verses VALUES (14655, 19, 47, 1, 'para o vencedor para-filhos-de করах salmo');
INSERT INTO verses VALUES (14656, 19, 47, 2, 'todo העם- תקוון- caph הריעו- לאלוהים- com-voz rinah');
INSERT INTO verses VALUES (14657, 19, 47, 3, 'porque yhwh [נוֹרָ֑א] [מֶ֥לֶךְ] rei grande sobre todo a-terra');
INSERT INTO verses VALUES (14658, 19, 47, 4, 'ידבר- povos substantramos e para nações- debaixo nossos pés:');
INSERT INTO verses VALUES (14659, 19, 47, 5, 'escolherá- para-nós a nossa herança a glória Jacó que amou Selá');
INSERT INTO verses VALUES (14660, 19, 47, 6, 'subir Elohim em trombetas yhwh com-voz chifre');
INSERT INTO verses VALUES (14661, 19, 47, 7, 'zamaru Elohim cantaram cantaram para nosso rei za-me-ro-u');
INSERT INTO verses VALUES (14662, 19, 47, 8, 'que rei todo a-terra Elohim za-mru sabedor:');
INSERT INTO verses VALUES (14663, 19, 47, 9, 'rei Elohim sobre nações Elohim ya-shav sobre ki-se-e קָדְשֽׁוֹ׃');
INSERT INTO verses VALUES (14664, 19, 47, 10, 'ne-di-be-i a-mim ne-es-apu povo elohimes- Abraão porque que -guarda-de terra muito calce-');
INSERT INTO chapters VALUES (526, 19, 48, 15);
INSERT INTO verses VALUES (14665, 19, 48, 1, 'cântico [מִ֝זְמוֹר] para-filhos-de');
INSERT INTO verses VALUES (14666, 19, 48, 2, 'grande yhwh [וּמְהֻלָּ֣ל] muito em-cidade-de [Elohim] monte-de');
INSERT INTO verses VALUES (14667, 19, 48, 3, 'יפחה נוף משוש todo a-terra monte-de ציון ירכתי norte Kiryat rei muito');
INSERT INTO verses VALUES (14668, 19, 48, 4, 'Elohim [בְּאַרְמְנוֹתֶ֗יהָ] conhecido [לְמִשְׂגָּֽב]');
INSERT INTO verses VALUES (14669, 19, 48, 5, 'porque eis [נֽוֹעֲד֑וּ] [עָבְר֥וּ] [יַחְדָּֽו]');
INSERT INTO verses VALUES (14670, 19, 48, 6, 'eles [רָ֭אוּ] assim [תָּמָ֑הוּ] [נִבְהֲל֥וּ] [נֶחְפָּֽזוּ]');
INSERT INTO verses VALUES (14671, 19, 48, 7, 'رعدا أحازتهم nome خيل que-gera');
INSERT INTO verses VALUES (14672, 19, 48, 8, 'pelo-vento קָדִים que-borrifar-se-á navios tarshish:');
INSERT INTO verses VALUES (14673, 19, 48, 9, 'como-que ouvimos assim vimos em-cidade- yhwh exércitos na-cidade Elohim-nosso Elohim ordenará até eternamente Selá');
INSERT INTO verses VALUES (14674, 19, 48, 10, 'דִּמְּנֻ֣י Elohim chasdekha בְּקֶ֥רֶב הֵיכָלֶ֣ךָ');
INSERT INTO verses VALUES (14675, 19, 48, 11, '[כְּשִׁמְךָ֤] Elohim assim [תְּ֭הִלָּתְךָ] sobre [צֶ֝֗דֶק] terra [יְמִינֶֽךָ]');
INSERT INTO verses VALUES (14676, 19, 48, 12, 'יִשְׂמַ֣ח monte-de Siao תָּגֵ֥לְנָה filhas-de Judá לְ֝מַ֗עַן מִשְׁפָּטֶ֥יךָ');
INSERT INTO verses VALUES (14677, 19, 48, 13, 'סֹ֣בּוּ Tsíyyôn ve-ha-qippûhâ sippûrê migdôleihâ');
INSERT INTO verses VALUES (14678, 19, 48, 14, 'shîthû libbêkhem lê-chêlah pasgû armonôtêihâ para têsappûrû לְד֣וֹר אַחֲרֽוֹן׃');
INSERT INTO verses VALUES (14679, 19, 48, 15, 'que [זֶ֨ה] Elohim El [Elohim] eternidade ele ele sobre [עַל־מֽוּת]');
INSERT INTO chapters VALUES (527, 19, 49, 21);
INSERT INTO verses VALUES (14680, 19, 49, 1, 'para o vencedor para-filhos-de קֹ֬רַח salmo');
INSERT INTO verses VALUES (14681, 19, 49, 2, 'ouvi [כָּל־הָֽעַמִּ֑ים] todo [כָּל־יֹ֥שְׁבֵי] [חָֽלֶד] todo');
INSERT INTO verses VALUES (14682, 19, 49, 3, 'também homem homem também filhos-de homem yachad עָשִׁ֥יר וְאֶבְיֽוֹן׃');
INSERT INTO verses VALUES (14683, 19, 49, 4, '[פִּ֭י] [יְדַבֵּ֣ר] [חָכְמ֑וֹת] [וְהָג֖וּת] [לִבִּ֣י] [תְבוּנֽוֹת]');
INSERT INTO verses VALUES (14684, 19, 49, 5, 'אַטֶּ֣ה לְמָשָׁ֣ל a-zi-ni אֶפְתַּ֥ח בְּ֝כִנּ֗וֹר חִידָתֽ͏ִי׃');
INSERT INTO verses VALUES (14685, 19, 49, 6, 'por-que אִ֭ירָא בִּ֣ימֵי mal iniquidade עֲקֵבַ֣י יְסוּבֵּֽנִי׃');
INSERT INTO verses VALUES (14686, 19, 49, 7, 'הַבֹּטְחִ֥ים sobre chelam E-POR-MUITOS עָ֝שְׁרָ֗ם יִתְהַלָּֽלוּ׃');
INSERT INTO verses VALUES (14687, 19, 49, 8, '[אָ֗ח] não [יִפְדֶּ֣ה] [אִ֑ישׁ] homem não [כָּפְרֽוֹ]');
INSERT INTO verses VALUES (14688, 19, 49, 9, 'e houver redenção as suas almas e cessará para-eternidade');
INSERT INTO verses VALUES (14689, 19, 49, 10, 'e viverá ainda não não virão-ve: da destruição;');
INSERT INTO verses VALUES (14690, 19, 49, 11, 'que verá sábios morrerão juntos kasisil e arderam perecerao e abandonaram a outros seu exército:');
INSERT INTO verses VALUES (14691, 19, 49, 12, 'em seu meio eles os invadiram para sempre de suas habitações para-a-geração e geração chamaram בִ֝שְׁמוֹתָ֗ם sobre אֲדָמֽוֹת׃');
INSERT INTO verses VALUES (14692, 19, 49, 13, '[וְאָדָ֣ם] [בִּ֭יקָר] não [נִמְשַׁ֖ל] [כַּבְּהֵמ֣וֹת] [נִדְמֽוּ]');
INSERT INTO verses VALUES (14693, 19, 49, 14, 'este דַ֭רְכָּם כֵּ֣סֶל a-eles e-em-les por-su-boca-os terão-desejo Selá');
INSERT INTO verses VALUES (14694, 19, 49, 15, 'como-ovelhas para-a-tumba e-eles-terão morte pastorear-se-á e-eles-pastorearam neles justos no-láquer para-lálot שְׁא֗וֹל de-mizbúl a-ele');
INSERT INTO verses VALUES (14695, 19, 49, 16, 'somente Elohim ser-ferá minha-alma que sheol porque tomará-me Selá');
INSERT INTO verses VALUES (14696, 19, 49, 17, 'a temer-se-á porque fará-dez homem porque será-multiplicado glória-de casa-dele');
INSERT INTO verses VALUES (14697, 19, 49, 18, 'que não [בְ֭מוֹתוֹ] [יִקַּ֣ח] [הַכֹּ֑ל] não [אַחֲרָ֣יו] depois-dele');
INSERT INTO verses VALUES (14698, 19, 49, 19, 'porque [בְּחַיָּ֣יו] [יְבָרֵ֑ךְ] [וְ֝יוֹדֻ֗ךָ] [כִּי־תֵיטִ֥יב] para-ti');
INSERT INTO verses VALUES (14699, 19, 49, 20, 'vai-vir até geração pais-seus não נֵ֝֗צַח não יראו־ luz');
INSERT INTO verses VALUES (14700, 19, 49, 21, 'homem בִּ֭יקָר e-não entenderá נִמְשַׁ֖ל כּ-בּ-הֵמ֣וֹת נִדְ-מֽוּ׃');
INSERT INTO chapters VALUES (528, 19, 50, 23);
INSERT INTO verses VALUES (14701, 19, 50, 1, 'salmo לְאָ-סָ֥ף אֵ-ל ׀ אֱ-לֹהִ֡ים yhwh yhwh e ele chamou terra do oriente- sol até מְבֹ-אוֹ׃');
INSERT INTO verses VALUES (14702, 19, 50, 2, '[מִצִיּ֥וֹן] [מִכְלַל־יֹ֗פִי] beleza-de Elohim');
INSERT INTO verses VALUES (14703, 19, 50, 3, '[יָ֤בֹ֥א] nosso-Elohim e-a [אֵשׁ־לְפָנָ֥יו] comerás [וּ֝סְבִיבָ֗יו] [נִשְׂעֲרָ֥ה] muito');
INSERT INTO verses VALUES (14704, 19, 50, 4, 'chamaria a os-céus [וְאֶל־הָ֝אָ֗רֶץ] e-a a-terra');
INSERT INTO verses VALUES (14705, 19, 50, 5, '[אִסְפוּ־לִ֥י] para-mim [כֹּרְתֵ֖י] [בְרִיתִ֣י] [עֲלֵי־זָֽבַח]');
INSERT INTO verses VALUES (14706, 19, 50, 6, '[וַיַּגִּ֣ידוּ] céus [צִדְק֑וֹ] porque [׀] [שֹׁפֵ֖ט] ele Selá');
INSERT INTO verses VALUES (14707, 19, 50, 7, '[שִׁמְעָ֤ה] [עַמִּ֨י] [׀] Israel [יִ֭שְׂרָאֵל] [וְאָעִ֣ידָה] sobre-ti El eu');
INSERT INTO verses VALUES (14708, 19, 50, 8, 'não sobre זבחיך o-či-cha ve-ol-o-te-i-ka lě-ne-ga-de-ʾi תָמִֽיד׃');
INSERT INTO verses VALUES (14709, 19, 50, 9, 'não e-qaq-a mi-bet-ka-ʾa pa-ăr mi-mi-khe-le-o-at-ke-ʾa a-tu-di-im');
INSERT INTO verses VALUES (14710, 19, 50, 10, 'porque para-mim todo [בְּהַרְרֵי־אָֽלֶף] mil');
INSERT INTO verses VALUES (14711, 19, 50, 11, '[יָ֭דַעְתִּי] todo ave [וְזִ֥יז] [שָׂ֝דַ֗י] comigo');
INSERT INTO verses VALUES (14712, 19, 50, 12, 'se [לֹא־אֹ֣מַר] para-ti disse a-ti porque');
INSERT INTO verses VALUES (14713, 19, 50, 13, 'האוכל de-carne אברים והדם עַתּוּדִ֣ים אֶשְׁתֶּֽה׃');
INSERT INTO verses VALUES (14714, 19, 50, 14, '[זְבַ֣ח] para-Elohim [תּוֹדָ֑ה] [וְשַׁלֵּ֖ם] [לְעֶלְי֣וֹן] [נְדָרֶֽיךָ]');
INSERT INTO verses VALUES (14715, 19, 50, 15, '[וּ֭קְרָאֵנִי] em-dia-de [צָרָ֑ה] [אֲ֝חַלֶּצְךָ֗] [וּֽתְכַבְּדֵֽנִי]');
INSERT INTO verses VALUES (14716, 19, 50, 16, 'וְלָ֤רָשָׁ֨ע ׀ disse disse que para-te para-relatar minhas-leis e-elevaste-te meu-contrato sobre teu-boca:');
INSERT INTO verses VALUES (14717, 19, 50, 17, 'e-tu odiaste-te disciplina e-ataste-lancaste minhas-palavras depois-de-tu');
INSERT INTO verses VALUES (14718, 19, 50, 18, 'se Vieste ladrão e esters com-ele e-com enganadores teu partilho');
INSERT INTO verses VALUES (14719, 19, 50, 19, 'teu boc enviaste mal e tua língua apertarás engano');
INSERT INTO verses VALUES (14720, 19, 50, 20, 'viverás em-ái-khá דַבֵּר em-bén- em-í-mkhá tu-darás dó-pi');
INSERT INTO verses VALUES (14721, 19, 50, 21, 'Estas tu fizeste vé-he-chérashtí démítá hé-yót- é-ehyé kam-mókhá oakhíkhakha e-areche para-os-olhos-teus');
INSERT INTO verses VALUES (14722, 19, 50, 22, 'binu- esta zot shokechi אֱל֑וֹהַּ para-que-não etref e-não-há matsil');
INSERT INTO verses VALUES (14723, 19, 50, 23, 'sacrificador todah yekabbdaneni וְשָׂ֥ם o-caminho-de arenu beyeshua Elohim');
INSERT INTO chapters VALUES (529, 19, 51, 21);
INSERT INTO verses VALUES (14724, 19, 51, 1, 'ao-regente salmo de-Davi');
INSERT INTO verses VALUES (14725, 19, 51, 2, '[בְּֽבוֹא־אֵ֭לָיו] [נָתָ֣ן] deu o-profeta quando veio a sete');
INSERT INTO verses VALUES (14726, 19, 51, 3, '[חָנֵּ֣נִי] Elohim [כְּחַסְדֶּ֑ךָ] [כְּרֹ֥ב] [רַ֝חֲמֶ֗יךָ] [מְחֵ֣ה] [פְשָׁעָֽי]');
INSERT INTO verses VALUES (14727, 19, 51, 4, 'כַּבְּסֵ֣נִי מֵעֲוֺנִ֑י וּֽמֵחַטָּאתִ֥י purifica-me:');
INSERT INTO verses VALUES (14728, 19, 51, 5, 'porque meus pecados eu conheça e-senhe-me negdî תָמִֽיד׃');
INSERT INTO verses VALUES (14729, 19, 51, 6, 'a-ti apenas-te senha-me e-mal nos-teus-olhos faça-ei a-fim-de justifique-te em-teu-palavra תִּזְכֶּ֥ה בְשָׁפְטֶֽךָ׃');
INSERT INTO verses VALUES (14730, 19, 51, 7, 'eis [חוֹלָ֑לְתִּי] [וּ֝בְחֵ֗טְא] [יֶֽחֱמַ֥תְנִי] [אִמִּֽי]');
INSERT INTO verses VALUES (14731, 19, 51, 8, 'eis verdade chapatzta בַטֻּח֑וֹת וּ֝בְסָתֻ֗ם חָכְמָ֥ה תוֹדִיעֵֽנִי׃');
INSERT INTO verses VALUES (14732, 19, 51, 9, '[תְּחַטְּאֵ֣נִי] [בְאֵז֣וֹב] [וְאֶטְהָ֑ר] [תְּ֝כַבְּסֵ֗נִי] [וּמִשֶּׁ֥לֶג] [אַלְבִּֽין]');
INSERT INTO verses VALUES (14733, 19, 51, 10, 'תַּ֭שְׁמִיעֵנִי florescência וְשִׂמְחָ֑ה תָּ֝גֵ֗לְנָה עֲצָמ֥וֹת דִּכִּֽיתָ׃');
INSERT INTO verses VALUES (14734, 19, 51, 11, '[הַסְתֵּ֣ר] [פָּ֭נֶיךָ] [מֵחֲטָאָ֑י] e-todo [מְחֵֽה]');
INSERT INTO verses VALUES (14735, 19, 51, 12, 'coração [טָ֭הוֹר] [בְּרָא־לִ֣י] para-mim e-Espírito-de [נָ֝כ֗וֹן] [חַדֵּ֥שׁ] novo');
INSERT INTO verses VALUES (14736, 19, 51, 13, 'a תַּשְׁלִיכֵ֥נִי e-Espírito-de ואורח santidade-te a tomarei de-mim');
INSERT INTO verses VALUES (14737, 19, 51, 14, 'retornou a-mim alegria יִשֻׁעֶךָ e-Espírito-de liberalidade me apoiar-te-ás');
INSERT INTO verses VALUES (14738, 19, 51, 15, 'ensinar-me-ás pecadores caminhos-te e os seus pecados a-ti se voltarão');
INSERT INTO verses VALUES (14739, 19, 51, 16, 'salva-me מִדָּמִ֨ים Elohim Elohim-de תְשׁוּעָתִ֑י תְּרַנֵּ֥ן לְ֝שׁוֹנִ֗י צִדְקָתֶֽךָ׃');
INSERT INTO verses VALUES (14740, 19, 51, 17, 'Adonai שְׂfַ֣ay תִּפְתָּ֑ח וּפִי יַגִּ֥יד será teu louvor:');
INSERT INTO verses VALUES (14741, 19, 51, 18, 'que não [לֹא־תַחְפֹּ֣ץ] sacrifício-de [וְאֶתֵּ֑נָה] [ע֝וֹלָ֗ה] não [תִרְצֶֽה]');
INSERT INTO verses VALUES (14742, 19, 51, 19, 'Zibhei Elohim espírito Nishbarah coração-de Nishbar e-esmagado não não Tivze∶');
INSERT INTO verses VALUES (14743, 19, 51, 20, 'Hiteiva Birtzonakh a Sião Tivneh∶ walls Jerusalém');
INSERT INTO verses VALUES (14744, 19, 51, 21, 'então [תַּחְפֹּ֣ץ] [זִבְחֵי־צֶ֭דֶק] [עוֹלָ֣ה] [וְכָלִ֑יל] [אָ֤ז] então eles-subirão sobre');
INSERT INTO chapters VALUES (530, 19, 52, 11);
INSERT INTO verses VALUES (14745, 19, 52, 1, 'ao-regente משכיל de-Davi');
INSERT INTO verses VALUES (14746, 19, 52, 2, 'בבו'' דויאג האדומי WAYYAGGED לشاול E-disse E-disse a-ele Davi a casa אخيימלאך׃');
INSERT INTO verses VALUES (14747, 19, 52, 3, 'que [בְּ֭רָעָה] [הַגִּבּ֑וֹר] [חֶ֥סֶד] bondade El todo');
INSERT INTO verses VALUES (14748, 19, 52, 4, '[הַ֭וּוֹת] [תַּחְשֹׁ֣ב] [לְשׁוֹנֶ֑ךָ] [כְּתַ֥עַר] [מְ֝לֻטָּ֗שׁ] fez [רְמִיָּֽה]');
INSERT INTO verses VALUES (14749, 19, 52, 5, 'אָהַ֣בְתָּ mau מִטוֹב שֶׁ֓קֶר ׀ falando justica Selá');
INSERT INTO verses VALUES (14750, 19, 52, 6, 'אָהַ֥בְתָּ todo דּ-בְרֵי- בָ֗לַע língua-de engano');
INSERT INTO verses VALUES (14751, 19, 52, 7, 'também El serás estendido para sempre serás elevado e será estendido de tenda e tua raiz vida vivos Selá');
INSERT INTO verses VALUES (14752, 19, 52, 8, 'e verão justos e temerão sobre ele Isaque:');
INSERT INTO verses VALUES (14753, 19, 52, 9, 'eis o homem não põe-se Elohim seu-muro e-se-apeitou em-multidão dez-o força-o em-su-espontaneidade');
INSERT INTO verses VALUES (14754, 19, 52, 10, 'e-eu como-oliva nuvem-rápida em-casa-de Elohim confiei em-su-coração Elohim eternidade e-perpetuidade');
INSERT INTO verses VALUES (14755, 19, 52, 11, 'te-adoro para sempre que fizeste e esperarei o teu nome porque diante em-frente-de do teu fiel');
INSERT INTO chapters VALUES (531, 19, 53, 7);
INSERT INTO verses VALUES (14756, 19, 53, 1, 'ao-regente sobre misericórdia sabedoria de-Davi');
INSERT INTO verses VALUES (14757, 19, 53, 2, 'disse Nabal no seu coração não-há Elohim destroi e odeiem enganosidade não-há עֹשֵׂה- bom');
INSERT INTO verses VALUES (14758, 19, 53, 3, 'Elohim מִשֶּׁמַיִם֮ הִשְׁקִיף sobre homem para-ver לִרְאוֹת הֲיֵ֣שׁ משכיל דָּרֵשׁ a Elohim');
INSERT INTO verses VALUES (14759, 19, 53, 4, '[כֻּלּ֥וֹ] [סָג֮] [יַחְדָּ֢ו] [נֶ֫אֱלָ֥חוּ] não-há [עֹֽשֵׂה־ט֑וֹב] bom [גַּם־אֶחָֽד] também um');
INSERT INTO verses VALUES (14760, 19, 53, 5, 'não יָדְעוּ֮ פֹּ֤עֲלֵ֫י iniquidade אֹכְלֵ֣י עַ֭מִּי אָ֣כְלוּ pão Elohim não קָרָֽאוּ׃');
INSERT INTO verses VALUES (14761, 19, 53, 6, '[שָׁ֤ם] [׀] [פָּ֥חֲדוּ] não [לֹא־הָ֢יָ֫[t]ה] porque Elohim [פִּ֭זַּר] [עַצְמ֣וֹת] [חֹנָ֑ךְ] [הֱ֝בִשֹׁ֗תָה] porque Elohim');
INSERT INTO verses VALUES (14762, 19, 53, 7, 'quem dará [מִצִיּוֹן֮] [יְשֻׁע֢וֹת] Israel [בְּשׁ֣וּב] Elohim [שְׁב֣וּת] povo-seu [יָגֵ֥ל] Jacó [יִשְׂמַ֥ח] Israel');
INSERT INTO chapters VALUES (532, 19, 54, 9);
INSERT INTO verses VALUES (14763, 19, 54, 1, 'ao-regente בִּנְגִינֹ֗ת מַשְׂכִּ֥יל de-Davi');
INSERT INTO verses VALUES (14764, 19, 54, 2, 'em-vir הַ֭זִּיפִים e-disseram de-שָׁאוּל não Davi מִסְתַּתֵּ֥ר com-nosso:');
INSERT INTO verses VALUES (14765, 19, 54, 3, 'Elohim [בְּשִׁמְךָ֣] [הוֹשִׁיעֵ֑נִי] [וּבִגְבוּרָתְךָ֥] [תְדִינֵֽנִי]');
INSERT INTO verses VALUES (14766, 19, 54, 4, 'Elohim ouviu תְּפִלָּתִ֑י הַ֝אֲזִ֗ינָה para-palavras-de a boca:');
INSERT INTO verses VALUES (14767, 19, 54, 5, 'que estrangeiros ⁃ arquaram-se עָלַ֗י e estenderam-se buscou-se minha-alma não não Elohim diante-deles Selá');
INSERT INTO verses VALUES (14768, 19, 54, 6, 'eis Elohim עֹזֵר a-mim Adonai em seguros alma-de-mim');
INSERT INTO verses VALUES (14769, 19, 54, 7, 'o mal para os meus conselheiros em tua verdade enrolai-vos:');
INSERT INTO verses VALUES (14770, 19, 54, 8, '[בִּנְדָבָ֥ה] [אֶזְבְּחָה־לָּ֑ךְ] para-ti [שִּׁמְךָ֖] yhwh yhwh porque bom');
INSERT INTO verses VALUES (14771, 19, 54, 9, 'que de-todo [הִצִּילָ֑נִי] [וּ֝בְאֹיְבַ֗י] [רָאֲתָ֥ה] [עֵינִֽי]');
INSERT INTO chapters VALUES (533, 19, 55, 24);
INSERT INTO verses VALUES (14772, 19, 55, 1, 'ao-regente בִּנְגִינֹ֗ת מַשְׂכִּ֥יל de-Davi');
INSERT INTO verses VALUES (14773, 19, 55, 2, '[הַאֲזִ֣ינָה] Elohim [תְּפִלָּתִ֑י] e-a [מִתְּחִנָּתִֽי]');
INSERT INTO verses VALUES (14774, 19, 55, 3, '[הַקְשִׁ֣יבָה] a-mim [וַעֲנֵ֑נִי] [אָרִ֖יד] [בְּשִׂיחִ֣י] [וְאָהִֽימָה]');
INSERT INTO verses VALUES (14775, 19, 55, 4, 'מִקּ֤וֹל אוֹיֵ֗ב de-diante-de עָקַ֣ת ímpio porque יָמִ֥יטוּ alai -iniquidade וּבְאַף me-aborrecerão');
INSERT INTO verses VALUES (14776, 19, 55, 5, 'meu-coração יָחִ֣יל em-o-centro-de-mim e-terror(es) -morte caíram sobre-mim');
INSERT INTO verses VALUES (14777, 19, 55, 6, 'temor e-tremor irá-se-entrar em-mim e-ela-me-cobriu poder');
INSERT INTO verses VALUES (14778, 19, 55, 7, 'e-disse quem dê para-mim costa como-pomba voarei [sem-traducao]');
INSERT INTO verses VALUES (14779, 19, 55, 8, 'eis afastarei vagabundo alin em-o-deserto Selá');
INSERT INTO verses VALUES (14780, 19, 55, 9, 'achisha de-refúgio a-mim do-espírito furacão da-tormenta');
INSERT INTO verses VALUES (14781, 19, 55, 10, 'engoliu-a Adonai dividiu-o de-sua-língua porque vi-a violência e-riv em-a-cidade');
INSERT INTO verses VALUES (14782, 19, 55, 11, 'dia e-noite ele-sobreva-ela sobre as-muralhas-de-aquela e-iniquidade e-trabalho na-sua-entre');
INSERT INTO verses VALUES (14783, 19, 55, 12, 'as-tribulações em-o-interior-de-aquela e-não ele-se-move de-o-largo dentro e-de-enganosa');
INSERT INTO verses VALUES (14784, 19, 55, 13, 'que não inimigo me-insultará e-elevar-ei não de-minha-aversão sobre-mim nós e-esconder-ei de-nós');
INSERT INTO verses VALUES (14785, 19, 55, 14, 'e-tu mortal segundo-a-sequência-minha meu-alto e-mi-yud-ai');
INSERT INTO verses VALUES (14786, 19, 55, 15, 'que yach-dau nam-tik segredo em-casa-de Elohim ne-halech be-ragesh');
INSERT INTO verses VALUES (14787, 19, 55, 16, 'al-eimo yerdu sho''al vivos porque raot bi-meguram vida');
INSERT INTO verses VALUES (14788, 19, 55, 17, 'Eu a Elohim clamarei va-yhwh salva-me-');
INSERT INTO verses VALUES (14789, 19, 55, 18, 'tarde e-a-manhã- e-o-meziodia- eu-cantarei- e-eu-gemerei- E-ouviu de-a-minha-voz-');
INSERT INTO verses VALUES (14790, 19, 55, 19, 'resgatou- em-a-paz- minha-alma de-o-meio-de- a-mim porque comigo foram comigo-');
INSERT INTO verses VALUES (14791, 19, 55, 20, 'ele-ouvirá elohim-| e-eles-responderão- e-o-habitante- do-norte- sela- oriente não-há trocas- a-eles e-não temerão- Elohim');
INSERT INTO verses VALUES (14792, 19, 55, 21, 'enviou suas-mãos- em-sua-paz- profanou- בְּרִיתֽוֹ׃');
INSERT INTO verses VALUES (14793, 19, 55, 22, 'dividam-se súplicas de-a-sua-boca e-queimar o-seu-coração suavizem as-suas-palavras do-oleo e-eles abertas');
INSERT INTO verses VALUES (14794, 19, 55, 23, 'lanca sobre yhwh yehavcha vehu yechalchelcha não irá dar para-sempre mot latzadik');
INSERT INTO verses VALUES (14795, 19, 55, 24, 'e-tu Elohim toridem liber shachat homens-de דָמִ֣ים não se-dividam יְמֵיהֶ֑ם e-eu eu-tenho-confiança-em-o em-ti');
INSERT INTO chapters VALUES (534, 19, 56, 14);
INSERT INTO verses VALUES (14796, 19, 56, 1, 'para-aquele-que-maneja sobre pomba silencioso distantes a-Davi secreto-dele em-o-domínio ele filisteus na-Beth-Gamul');
INSERT INTO verses VALUES (14797, 19, 56, 2, 'חָנֵּ֣נִי Elohim porque respirei Enos todo o-dia guerreiro apertar-me-');
INSERT INTO verses VALUES (14798, 19, 56, 3, 'respiraram meus-príncipes todo o-dia porque muitos guerreiros a-mim -alto');
INSERT INTO verses VALUES (14799, 19, 56, 4, 'dia אִירָ֑א eu a-ti confiarei-');
INSERT INTO verses VALUES (14800, 19, 56, 5, 'em-Elohim exaltarei sua-palavra em-o-אלהים confiei não אִירָ֑א que fará em carne a-mim');
INSERT INTO verses VALUES (14801, 19, 56, 6, 'todo o-dia minhas-palavras os-enfraquecerão sobre-mim todo de-seus-pensamentos para-a-maldição;');
INSERT INTO verses VALUES (14802, 19, 56, 7, 'se-esconderão הֵ֭מָּה עֲקֵבַ֣י os-cuidarão como esperaram alma-de-mim');
INSERT INTO verses VALUES (14803, 19, 56, 8, 'sobre iniquidade expulsou- a-eles com-o-rancor povos faze-descer Elohim');
INSERT INTO verses VALUES (14804, 19, 56, 9, 'minha-estranheza contaste-a אתה colocaste-a minha-choro em-teu-exílio não-é-verdade em-tua-contagem');
INSERT INTO verses VALUES (14805, 19, 56, 10, 'então voltarão meus-inimigos אָחוֹר em-dia-de clamarei este יָדַעְתִּי porque Elohim a-mim');
INSERT INTO verses VALUES (14806, 19, 56, 11, 'בֵּ֭אלֹהִים eu-louvar-ei palavra em-yhwh eu-louvar-ei palavra');
INSERT INTO verses VALUES (14807, 19, 56, 12, 'em-Elohim confiei-em não אִירָ֑א que ele-fará para-mim');
INSERT INTO verses VALUES (14808, 19, 56, 13, 'sobre-mim Elohim teus-votos-teus eu-recompensarei louvores para-ti');
INSERT INTO verses VALUES (14809, 19, 56, 14, 'que resgatou a-minha-alma de-a-morte não רַגְלַ֗י do-seu-falso-elohim para-andar diante-de Elohim na-luz serão-vidas');
INSERT INTO chapters VALUES (535, 19, 57, 12);
INSERT INTO verses VALUES (14810, 19, 57, 1, 'ao a corrompeu a-Davi secreto-dele em-sua-fuga מִפְּנֵי־ Saul em-a-caverna');
INSERT INTO verses VALUES (14811, 19, 57, 2, 'misericordia-me Elohim misericordia-me porque que tende-piedade נַ֫פְשִׁ֥י e-no-escuro-de de-asas-teus eu-me-esconderei até passará das-noites');
INSERT INTO verses VALUES (14812, 19, 57, 3, 'eu-clamarei le''Elohim עֶלְי֑וֹן a-oElohim terminar sobre-mim');
INSERT INTO verses VALUES (14813, 19, 57, 4, 'ele-enviará do-ceu e-me-salve חERGEF me-aspire sela יִשְׁלַ֥ח Elohim חֶסֶדְׁוֹ e-sua-verdade');
INSERT INTO verses VALUES (14814, 19, 57, 5, 'minha-alma em-meio-de no-meio-de eu-deitar-ei-me ardentes filhos-de homem de-seus-dentes chániyt e-flechas וּלְשׂוֹנוֹתָם espada aguda');
INSERT INTO verses VALUES (14815, 19, 57, 6, '[ר֣וּמָה] sobre os-ceus sobre sobre todo a-terra');
INSERT INTO verses VALUES (14816, 19, 57, 7, 'rede preparamos em-meu-passo dobrou-se נַ֫פְשִׁ֥י deram-se ante mim folhagem caíram em-mi-dela Selá');
INSERT INTO verses VALUES (14817, 19, 57, 8, 'certo לִבִּ֣י Elohim firme meu-coração cantarei e-azamereh');
INSERT INTO verses VALUES (14818, 19, 57, 9, 'awura kevod-i awura ha-nevel ve-kinor a-aireh shachar');
INSERT INTO verses VALUES (14819, 19, 57, 10, 'odecha ba-amim Adonai eu-cantarei-te não אֻמִּֽים׃');
INSERT INTO verses VALUES (14820, 19, 57, 11, 'porque grande até céus chasdekha e-até céus אֲמִתֶּֽךָ׃');
INSERT INTO verses VALUES (14821, 19, 57, 12, '[ר֣וּמָה] sobre ceus sobre sobre todo a-terra');
INSERT INTO chapters VALUES (536, 19, 58, 12);
INSERT INTO verses VALUES (14822, 19, 58, 1, 'ao-regente a você-ruina para-davíd segredo-seu');
INSERT INTO verses VALUES (14823, 19, 58, 2, 'realmente silencioso צדיק falem-vos de-retos julgareis filhos-de homem');
INSERT INTO verses VALUES (14824, 19, 58, 3, 'também em-o-lar subida-s fazer-vos-eis em-a-terra violência mãos-vossas esmagar-vos-eis');
INSERT INTO verses VALUES (14825, 19, 58, 4, 'se-afastem ímpios de-merékhem vós-perdereis de-o-interno dizendo כָזָֽב׃');
INSERT INTO verses VALUES (14826, 19, 58, 5, 'Hamate tsalma''vet como-forma Hamate serpente como raposa surdo tornam-lentos o-ouvido-dele');
INSERT INTO verses VALUES (14827, 19, 58, 6, 'que não à-voz-de para-voz sussurando unindo companheiros deles-machucados');
INSERT INTO verses VALUES (14828, 19, 58, 7, 'Elohim destruir- seus-dentes em-seu-paço de-perdição de-leões esmaga-separadamente yhwh');
INSERT INTO verses VALUES (14829, 19, 58, 8, 'se-desgostarão כְמוֹ־ águas andarão- a-eles יִדְרֹ֥ךְ como rir-se-');
INSERT INTO verses VALUES (14830, 19, 58, 9, 'como de-bolha temes yahalokh nefele e-sheth não חָ֥זוּ do-sol');
INSERT INTO verses VALUES (14831, 19, 58, 10, 'betherehem yabino siroteichechem atad como viveu como charon yesarenu');
INSERT INTO verses VALUES (14832, 19, 58, 11, 'alegrar-se-á justo porque viu vingança de-seus-passos se-lavará com-o-sangue הָרָשָֽׁע׃');
INSERT INTO verses VALUES (14833, 19, 58, 12, 'E-disse homem somente fruto contra o justo- somente ha Elohim juízes na-terra');
INSERT INTO chapters VALUES (537, 19, 59, 18);
INSERT INTO verses VALUES (14834, 19, 59, 1, 'ao a corromperá para-David seu-manto em-envio שָׁאוּל e-vigiam a a-casa para-o-matar');
INSERT INTO verses VALUES (14835, 19, 59, 2, 'o-salve-me de-meu-inimigos meu-Elohim de-meu-oponentes e-exalte-me');
INSERT INTO verses VALUES (14836, 19, 59, 3, 'o-salve-me de-fazedores iniquidade e-de-homens [דָ֝מִ֗ים] hosse-ni');
INSERT INTO verses VALUES (14837, 19, 59, 4, 'que eis ar-bu le-na-fshi ya-guru sobre-mim az-im não pishe-i yhwh meu pecado yhwh');
INSERT INTO verses VALUES (14838, 19, 59, 5, 'be-li- a-von ye-rut-sun ve-yikko-nanu arrega-a para-mim e-vê');
INSERT INTO verses VALUES (14839, 19, 59, 6, 'e-tu yhwh Elohim exércitos Elohim-de Israel levanta-a para contar todo as-nações a descansa todo dos-traidores אָ-וֶן Selá');
INSERT INTO verses VALUES (14840, 19, 59, 7, 'voltarão pela-noite gemerão como Caleb e-virarão cidade');
INSERT INTO verses VALUES (14841, 19, 59, 8, 'eis e-manifesterão com seus dentes destruições em-suas-bocas porque quem ouviu');
INSERT INTO verses VALUES (14842, 19, 59, 9, 'e-tu yhwh rirás- a-eles zombarás para-todo goyim:');
INSERT INTO verses VALUES (14843, 19, 59, 10, 'força-seu a-ti guardarei porque Elohim de-meu-altura');
INSERT INTO verses VALUES (14844, 19, 59, 11, 'Elohim-de [*חסדו] Elohim [יְקַדְּמֵ֑נִי] em-ventre-meu');
INSERT INTO verses VALUES (14845, 19, 59, 12, 'a [׀] para-que-não [עַמִּ֗י] [הֲנִיעֵ֣מוֹ] [בְ֭חֵילְךָ] [וְהוֹרִידֵ֑מוֹ] [מָֽגִנֵּ֣נוּ] [אֲדֹנָֽי] Adonai');
INSERT INTO verses VALUES (14846, 19, 59, 13, 'חַטָאת de-seus-bocas דְּֽבַר־ língua-deles e-eles-se-unirão em-sua-preciosidade e-de-maldição e-de-falso dirão-eles');
INSERT INTO verses VALUES (14847, 19, 59, 14, 'termina com-ira termina e-não-há e-conhecerão porque Elohim mochel em-o-Ya''akov a-terra a-terra Selá');
INSERT INTO verses VALUES (14848, 19, 59, 15, 'e-voltarão para-a-crepúsculo se-comoverão como Caleb e-voltar-se-ão cidade');
INSERT INTO verses VALUES (14849, 19, 59, 16, 'הֵ֭מָּה de-comer se não se-satisfarão e-acamparam');
INSERT INTO verses VALUES (14850, 19, 59, 17, 'e-eu eu-cantarei teu-teu-poder e-eu-louvar-ei no-láquer tua-tua-graciosidade porque tu-estiveste de-altura a-mim e-de-fadiga em-dia-de angústia a-mim');
INSERT INTO verses VALUES (14851, 19, 59, 18, 'meu-meu-poder a-ti eu-cantarei porque Elohim misgavi Elohim-de graça-meu');
INSERT INTO chapters VALUES (538, 19, 60, 14);
INSERT INTO verses VALUES (14852, 19, 60, 1, 'לַ֭מְנַצֵּחַ sobre rosa testemunho segredo a-Davi para-aprender');
INSERT INTO verses VALUES (14853, 19, 60, 2, 'em-o-seu-levantar a Arã rios e-a aram tsevah e-ele-retornou Joabe e-feriu a edom begai- sal dois dez mil');
INSERT INTO verses VALUES (14854, 19, 60, 3, 'Elohim desdenhaste-nos [פְרַצְתָּ֑נוּ] irritaste-te virarás-volta para-nós');
INSERT INTO verses VALUES (14855, 19, 60, 4, 'tremeu-te terra [פְּצַמְתָּ֑הּ] afrouxou de-seus-pedaços porque em-baixo');
INSERT INTO verses VALUES (14856, 19, 60, 5, 'mostraste teu-povo dura h-s-q-t-a-n-u vinho t-r-ael-h');
INSERT INTO verses VALUES (14857, 19, 60, 6, 'deste l-y-r-e-kha n-s l-h-t-n-o-s-s de-diante-de q-sh-t Selá');
INSERT INTO verses VALUES (14858, 19, 60, 7, 'a-fim-de y-ch-l-ts-u-n y-d-i-d-kha salva-o y-m-in-kha');
INSERT INTO verses VALUES (14859, 19, 60, 8, 'Elohim palavra em-seu-santo eu-alegrarei-me eu-distribuirei שַׂכְמֵ֑ן e-valley tendas eu-medirei-me');
INSERT INTO verses VALUES (14860, 19, 60, 9, 'para-mim gilad-separador e-para-mim Menasheh e-eferaim refúgio cabeça-de mim יהודה מחקקי');
INSERT INTO verses VALUES (14861, 19, 60, 10, 'מוואב סיר רחצי sobre אדום [אַשְׁלִ֣יךְ] נעלי עָ֝לַ֗י Filisteu התrowsei');
INSERT INTO verses VALUES (14862, 19, 60, 11, 'quem יובלני cidade de cerco quem abençoa-me até Edom');
INSERT INTO verses VALUES (14863, 19, 60, 12, 'não tu Elohim [וְֽלֹא־תֵצֵ֥א] e-nao- sairás Elohim');
INSERT INTO verses VALUES (14864, 19, 60, 13, 'dá para-nós ajuda-de de-aperto e-vaidade homem homem');
INSERT INTO verses VALUES (14865, 19, 60, 14, 'em-elohimes נַעֲשֶׂה־ força וهو jebuseu nosso-aperto');
INSERT INTO chapters VALUES (539, 19, 61, 9);
INSERT INTO verses VALUES (14866, 19, 61, 1, 'para o vencedor sobre de-música de-Davi');
INSERT INTO verses VALUES (14867, 19, 61, 2, 'ouça Elohim risada-meu o-escuta oração-meu');
INSERT INTO verses VALUES (14868, 19, 61, 3, 'de-fim a-terra a-ti chamarei-eu com-cabeça-vestido meu-coração em-rocha- יָר֖וּם מִמֶּ֣נִּי refugia-me');
INSERT INTO verses VALUES (14869, 19, 61, 4, 'porque era-tu esconderijo a-mim de-diante-de força de-faces-de inimigo');
INSERT INTO verses VALUES (14870, 19, 61, 5, 'recolhida em-a-tenda-teu mundos habitar-ei em-o-segredo de-as-ásperas-teu selá');
INSERT INTO verses VALUES (14871, 19, 61, 6, 'porque tu Elohim ouviste para-o-voto-meu destituíste-te herança temores שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (14872, 19, 61, 7, 'dias sobre dias-de rei acrescenta seus-anos como geração וָדֹר׃');
INSERT INTO verses VALUES (14873, 19, 61, 8, 'habitou diante-de Elohim bondade e-verdade de guardarão-o');
INSERT INTO verses VALUES (14874, 19, 61, 9, 'assim canto teu-nome לָעַד para-mim-sacrifício meus-votos dia dia');
INSERT INTO chapters VALUES (540, 19, 62, 13);
INSERT INTO verses VALUES (14875, 19, 62, 1, 'ao-regente sobre seu-domínio salmo de-Davi');
INSERT INTO verses VALUES (14876, 19, 62, 2, 'porém a Elohim [נַפְשִׁ֑י] nós de-men-no minha-salvação');
INSERT INTO verses VALUES (14877, 19, 62, 3, 'somente ele tsuri ve-yeshu''ati misgavi não emot multiplicai');
INSERT INTO verses VALUES (14878, 19, 62, 4, 'até אָנָה tehotetu homem teratzchu kulchem keqir nati-y gader ha-dhuyah');
INSERT INTO verses VALUES (14879, 19, 62, 5, 'somente mis-saeto yaatzu le-hadikh yirtzu kazav be-piv yevarachu e-em-seu-meio maldecam- Selá');
INSERT INTO verses VALUES (14880, 19, 62, 6, 'porém a-elohimes silencioso minha-alma porque dele minha-esperança:');
INSERT INTO verses VALUES (14881, 19, 62, 7, 'somente ele rochedo-meu e-salvação-meu não não mover-eu');
INSERT INTO verses VALUES (14882, 19, 62, 8, 'sobre Elohim salvação-meu e-glória-meu tor- u-zi ma-chsi be-elohim:');
INSERT INTO verses VALUES (14883, 19, 62, 9, 'bit-ḥu nele em-todo e-t povo shif-ku- לְפָנָ֥יו os vossos corações Elohim ma-chese- para-nós Selá');
INSERT INTO verses VALUES (14884, 19, 62, 10, 'ach הֶבֶל filhos-de homem ka-zav filhos-de homem be-moaznayim la-a-lot eles de-vaidade juntos');
INSERT INTO verses VALUES (14885, 19, 62, 11, 'a confiarão em-opressor e-em-roubo a se-perderão força porque de-harvesto a lançareis coração');
INSERT INTO verses VALUES (14886, 19, 62, 12, 'uma palavra Elohim dois- ז֥וּ ouvi que força para-Elohim');
INSERT INTO verses VALUES (14887, 19, 62, 13, 'e-a-para-ti Adonai bondade porque אתה retribuirás a homem-de conforme-o-seu-trabalho');
INSERT INTO chapters VALUES (541, 19, 63, 12);
INSERT INTO verses VALUES (14888, 19, 63, 1, 'salmo para-Davi em-ser-vi em-deserto-de Judá');
INSERT INTO verses VALUES (14889, 19, 63, 2, 'Elohim meu-elohim tu tu fomei para-ti a-ti quanto-a-ela para-ti da-minha-carne a-ti secou e-fraque בְלִי־ águas');
INSERT INTO verses VALUES (14890, 19, 63, 3, 'כֵּ֭ן em-o-santo vi-te para-ver de-teu-poder e-tu-teu-esplendor');
INSERT INTO verses VALUES (14891, 19, 63, 4, 'porque bom Sussana-te de-a-vida meus-lábios abenço-em-vós');
INSERT INTO verses VALUES (14892, 19, 63, 5, 'assim bendirei-te nas-missoes-de-minha-vida em-tu elevarei mãos-mim');
INSERT INTO verses VALUES (14893, 19, 63, 6, 'k-mo חֵּ֣לֶב e-escuro tishbá minha-alma וְשִׂפְתֵ֥י alegrarias glorificarei boca-mim');
INSERT INTO verses VALUES (14894, 19, 63, 7, 'se lembrarei-tu sobre propósitos-meus em-Ashmuroth eu-guardarei- em-ti');
INSERT INTO verses VALUES (14895, 19, 63, 8, 'porque tu-foste a-mim li e-no-sombra das-asas-teus eu-clamarei');
INSERT INTO verses VALUES (14896, 19, 63, 9, 'pegada נַפְשִׁ֣י depois-de-ti em-mim tu-apoiarás יְמִינֶֽךָ׃');
INSERT INTO verses VALUES (14897, 19, 63, 10, 'e-elas para-destruição desejarão minha-alma e-virão em-o-baixo a-terra');
INSERT INTO verses VALUES (14898, 19, 63, 11, 'eles-o-exilarão sobre por-meio-de- espada porção raposas ser-ão');
INSERT INTO verses VALUES (14899, 19, 63, 12, 'e-o-rei alegrar-se-á em-A Elohim glorificar-se-á todo o-juramento que porque será-recompensado boca-de dizentes- mentira');
INSERT INTO chapters VALUES (542, 19, 64, 11);
INSERT INTO verses VALUES (14900, 19, 64, 1, 'ao-regente salmo de-Davi');
INSERT INTO verses VALUES (14901, 19, 64, 2, 'שְׁמַע־ Elohim de-mim em-o-meu-sussurro de-a-terror inimigo tu-encerras חַיָּֽי׃');
INSERT INTO verses VALUES (14902, 19, 64, 3, 'você-esconderá-me de-o-secreto os-enganadores de-a-ira Paoloֵי iniquidade');
INSERT INTO verses VALUES (14903, 19, 64, 4, 'que fazerem-me-fugir como-com-espada de-sua-língua seus-caminhos suas-setas palavra amargo');
INSERT INTO verses VALUES (14904, 19, 64, 5, 'para-atirar nos-segredos tãm פתאום yôrûhû e-não yirāʾû');
INSERT INTO verses VALUES (14905, 19, 64, 6, 'yəḥazzəqu- a-para-eles palavra mal contarão para-tornar-se-imundo pregos disseram quem ver- a-para-eles');
INSERT INTO verses VALUES (14906, 19, 64, 7, 'procurarão ofertas terminaram liberdade mascarado e-interno homem e-coração escondido');
INSERT INTO verses VALUES (14907, 19, 64, 8, 'e-os-levou Elohim חֵ֥ץ de-súbito foram castigos-deles');
INSERT INTO verses VALUES (14908, 19, 64, 9, 'e-os-enganaram עָלֵ֣ימוֹ com-sua-língua se-tornarão-vagabundos todo viu neles:');
INSERT INTO verses VALUES (14909, 19, 64, 10, 'e-eles-temeram todo homem e-eles-denunciaram feito-trabalho Elohim e-seus-trabalhos entenderam');
INSERT INTO verses VALUES (14910, 19, 64, 11, 'alegrar-se-á justo בַּ֭יהוָה e-ele-tremeliqueira nele e-eles-louvarão-se todo retos- coração');
INSERT INTO chapters VALUES (543, 19, 65, 14);
INSERT INTO verses VALUES (14911, 19, 65, 1, 'ao-regente salmo para-davíd שיר׃');
INSERT INTO verses VALUES (14912, 19, 65, 2, 'a-ti silêncio louvor Elohim em Sião e-a-para-ti será-pagado nódo-lo');
INSERT INTO verses VALUES (14913, 19, 65, 3, 'ouviu oração ʿădêkā todo carne virão');
INSERT INTO verses VALUES (14914, 19, 65, 4, 'palavras-de pecados prevaleceram מני transgressões-nossas tu perdoar-as');
INSERT INTO verses VALUES (14915, 19, 65, 5, 'abençoado-este tibḥar e-se-aproximarás habitará em-tuas-cortes nos-satisfaremos com-boas בֵּיתֶ֑ךָ santo הֵיכָלֶ֣ךָ');
INSERT INTO verses VALUES (14916, 19, 65, 6, 'horrores-estes em-justiça nos-responderás Elohim-de nosso-salvação מִבְטָ֥ח todo seus mandamentos terra e-mar distantes');
INSERT INTO verses VALUES (14917, 19, 65, 7, 'fazendo os-montes -bokho ornamento em-força:');
INSERT INTO verses VALUES (14918, 19, 65, 8, 'glorioso שְׁא֣וֹן mares mares de-seus-ondas e-tumulto לְאֻמִּֽים׃');
INSERT INTO verses VALUES (14919, 19, 65, 9, 'e-teveem-pavor habitantes-de extremidades de-ausências-teuas saídas-de- manhã e-o-crepúsculo cantares');
INSERT INTO verses VALUES (14920, 19, 65, 10, 'visitaaste a-terra e-a-sacudiste-ela muita-grandeza faz-te-rica torrente Elohim enchei águas תָּכִ֥ין de-a-seu-pão porque assim e-fará-la');
INSERT INTO verses VALUES (14921, 19, 65, 11, 'e-de-sua-juventude saciá-lo abaixar-se e-de-sua-troopas em-multidões e-esmagá-la sua-erva e-bendirá-a');
INSERT INTO verses VALUES (14922, 19, 65, 12, 'cinturaste ano-de tua-bondade e-tuas-rodas se-cheiarão far-farinha');
INSERT INTO verses VALUES (14923, 19, 65, 13, 'se-cheirarão pastagens מִדְבָּ֑ר e-se-rejubilarão g̅̂ba''ōth vocês-cingirão');
INSERT INTO verses VALUES (14924, 19, 65, 14, 'vestiram querubins o-rebanho e-os-vales cobrir-se- de-barro rebolarão também cantarão-.');
INSERT INTO chapters VALUES (544, 19, 66, 20);
INSERT INTO verses VALUES (14925, 19, 66, 1, 'לַ֭מְנַצֵּחַ שִׁ֣יר hino-de הריעו- para-Elohim todo a-terra');
INSERT INTO verses VALUES (14926, 19, 66, 2, 'cantem glória-de seu-nome שִׂ֥ימוּ glória sua-elogio');
INSERT INTO verses VALUES (14927, 19, 66, 3, 'אִמְר֣וּ para-elohim que terível trabalhos-te em-muitos de-teu-poder a-ti para-ti teus-inimigos');
INSERT INTO verses VALUES (14928, 19, 66, 4, 'todo a-terra se-curvarão a-ti e-cantarão a-ti cantem teu-nome Selá');
INSERT INTO verses VALUES (14929, 19, 66, 5, 'ide eureuem de-ações Elohim terrível ato sobre homem homem');
INSERT INTO verses VALUES (14930, 19, 66, 6, 'revolver mar para-a-terra na-river passarão com-pé nome alegrar-se- em-ele');
INSERT INTO verses VALUES (14931, 19, 66, 7, 'governante em-sua-gloria para sempre eternidade em-nos os povos iluminar-na os-rebeldes a a-eles Selá');
INSERT INTO verses VALUES (14932, 19, 66, 8, 'abençoem nações Elohim-nosso e-anunciem voz-de voz');
INSERT INTO verses VALUES (14933, 19, 66, 9, 'o-nome nossas almas na-vida e-não deu para-cair pés-nos-verso');
INSERT INTO verses VALUES (14934, 19, 66, 10, 'porque provaste-nos Elohim [כִּצְרָף־כָּֽסֶף]');
INSERT INTO verses VALUES (14935, 19, 66, 11, 'trouxe-te-nos na-armadilha põe- abominável na-entranhas-nos-verso');
INSERT INTO verses VALUES (14936, 19, 66, 12, 'montaste-te- Enos para-cabeças-nos vimos- em-a-fogo e-no-mares e-te-levou-nos para-a-beberagem');
INSERT INTO verses VALUES (14937, 19, 66, 13, 'eu-entrarei em-casa-tua com-oferendas que-pagaremos a-ti nossos-votos');
INSERT INTO verses VALUES (14938, 19, 66, 14, 'que abriram lábios-meus e-ele-falará- boca-minha בַּצַּר־ a-mim');
INSERT INTO verses VALUES (14939, 19, 66, 15, 'subidas de-entranhas elevarei- para-ti com fumo aies farei-eu manhã com עַתּוּדִ֣ים Selá');
INSERT INTO verses VALUES (14940, 19, 66, 16, 'vai-em ouvi e-celebrarei todo temor-de Elohim que fez para a minha alma');
INSERT INTO verses VALUES (14941, 19, 66, 17, 'a-ele boca-de [וְ֝רוֹמַ֗ם] debaixo em-lugar-de');
INSERT INTO verses VALUES (14942, 19, 66, 18, 'iniquidade se vi não não ouça-e Adonai');
INSERT INTO verses VALUES (14943, 19, 66, 19, 'certamente ouviu Elohim ouvindo com-voz oração-meu');
INSERT INTO verses VALUES (14944, 19, 66, 20, 'bendito Elohim que não removendo oração-meu e-sua-graça de-mim');
INSERT INTO chapters VALUES (545, 19, 67, 8);
INSERT INTO verses VALUES (14945, 19, 67, 1, 'para-o-musico-de-cabeça בִּנְגִינֹ֗ת salmo שיר׃');
INSERT INTO verses VALUES (14946, 19, 67, 2, '[אֱ[t]לֹהִ֗ים] e-bençoa-nos sua-face ʾittānû Selá');
INSERT INTO verses VALUES (14947, 19, 67, 3, 'para-conhecer na-terra דַּרְכֶּ֑ךָ em-todo nações salvação-teu');
INSERT INTO verses VALUES (14948, 19, 67, 4, 'te-louvarão povos Elohim louvar-te-ão povos כלם׃');
INSERT INTO verses VALUES (14949, 19, 67, 5, 'se-rejou-cem e-can-to-em lĕʿummîm porque tišpôṭ povos מִישׁוֹר e-a-povos na-terra tu-da-ces-e-os Selá');
INSERT INTO verses VALUES (14950, 19, 67, 6, 'po-vos-cono-cer-te povos Elohim louvar-te-ão povos כלם׃');
INSERT INTO verses VALUES (14951, 19, 67, 7, 'terra deu a-renda-da-sua yebareche-nu Elohim nosso-Elohim');
INSERT INTO verses VALUES (14952, 19, 67, 8, 'yebareche-nu Elohim ve-yire-u ele todo extremidades-de terra');
INSERT INTO chapters VALUES (546, 19, 68, 36);
INSERT INTO verses VALUES (14953, 19, 68, 1, 'ao-regente para-David salmo שיר׃');
INSERT INTO verses VALUES (14954, 19, 68, 2, 'יָק֣וּם Elohim yapu-tsu oyevav veyanus-u mesane-av de-face-dele');
INSERT INTO verses VALUES (14955, 19, 68, 3, 'k-hindof ashan tindef como-massas torradas מִפְּנֵי־ fogo perderão de-diante-de de-faces-de Elohim');
INSERT INTO verses VALUES (14956, 19, 68, 4, 'e-os-justos alegrar-se-ão saltitarão diante-de Elohim e-saltitarão em-alegria');
INSERT INTO verses VALUES (14957, 19, 68, 5, 'cantai para-A Elohim cante seu-nome exalte para-o-que-anda em-as-pampas com-a-luz seu-nome e-exultem diante-de-ele');
INSERT INTO verses VALUES (14958, 19, 68, 6, 'pai-de os-órfãos e-o-julgador al-ma-not Elohim be-me-on קָדְשֽׁוֹ׃');
INSERT INTO verses VALUES (14959, 19, 68, 7, 'Elohim mo-shiv ye-chi-dim be-ytah mo-tzi a-sirim be-ko-sharot somente so-rarim shakh-nu cobiça-verso-final');
INSERT INTO verses VALUES (14960, 19, 68, 8, 'Elohim em-saída-teu diante-de povo-teu em-passo-teu em-eshimon Selá');
INSERT INTO verses VALUES (14961, 19, 68, 9, 'terra treme-verso-final também céus deram-se de-diante-de Elohim este sinai-acento-tonsura de-diante-de Elohim Elohim-de Israel');
INSERT INTO verses VALUES (14962, 19, 68, 10, 'גשם ofertas-teu exaltarás Elohim herança-teu e-nela-ah tu ko-na-nat-ha');
INSERT INTO verses VALUES (14963, 19, 68, 11, 'chi-yat-kha habitaram nela preparar-ás em-boas-tua para-o-aflito Elohim');
INSERT INTO verses VALUES (14964, 19, 68, 12, 'Adonai dê disse exército [רָֽב] muito');
INSERT INTO verses VALUES (14965, 19, 68, 13, 'reis-de exércitos derramarão derramarão e-vaso-de casa dividirás despojo');
INSERT INTO verses VALUES (14966, 19, 68, 14, 'se entre entre duas-parte as-asas pomba será-levada com-prata e-suas-entranhas em-raciqueiro dourado');
INSERT INTO verses VALUES (14967, 19, 68, 15, 'com-palha Shaddai reis bah farinha-de-neve em-zalmom');
INSERT INTO verses VALUES (14968, 19, 68, 16, 'monte-de Elohim monte-de basaan monte-de gabunim monte-de basaan');
INSERT INTO verses VALUES (14969, 19, 68, 17, 'por-que vocês-aplaudem-na os-montes de-gabnunim o-ha-har [הָהָ֗ר] desejar para-assento-dele também yhwh ele-ocupará para sempre;');
INSERT INTO verses VALUES (14970, 19, 68, 18, 'carro-de Elohim milhares-de-milhares de-milhares de-shenan Adonai [בָ֝֗ם] Sinae no santuário:');
INSERT INTO verses VALUES (14971, 19, 68, 19, 'subiste ao-mauro retornaste moradia tomaste presentes em-homem וְאַ֥ף rebeldes para-a-sala Yah Elohim');
INSERT INTO verses VALUES (14972, 19, 68, 20, 'bendito Adonai dia dia dia para-nos o-elohim nosso-salvamento Selá');
INSERT INTO verses VALUES (14973, 19, 68, 21, 'o-elohim para-nós El para-a-salvação e-ao-Yahweh Adonai para-a-morte resultados-verso');
INSERT INTO verses VALUES (14974, 19, 68, 22, 'somente Elohim esmagará cabeça seus-inimigos cabeça passeando andando-de em-seus-pesos-verso');
INSERT INTO verses VALUES (14975, 19, 68, 23, 'disse Adonai de-bashan restituirei restituirei de-mezulot mar');
INSERT INTO verses VALUES (14976, 19, 68, 24, 'para-que timmachatz reglekha- beddam- לשון klavekha- meoyvim- minnehu-');
INSERT INTO verses VALUES (14977, 19, 68, 25, 'viram halichotekha- Elohim halichot- eli- Malchi baqodesh-');
INSERT INTO verses VALUES (14978, 19, 68, 26, 'antecedam cantores atrás-de tocadores-de-instrumento-musical no-meio-de virgens tocadoras-de-tambor');
INSERT INTO verses VALUES (14979, 19, 68, 27, 'em-as-multidões abençoai Elohim yhwh de-o-monte Israel');
INSERT INTO verses VALUES (14980, 19, 68, 28, 'nome benjamim-separado-por-barra-vertical pequeno rode-m príncipes-de yehu-dah rigmat-am príncipes-de zevul-un príncipes-de nafthal-i');
INSERT INTO verses VALUES (14981, 19, 68, 29, 'ordenou Elohim-teus teu-poder u-zah Elohim zu fizeste para nós');
INSERT INTO verses VALUES (14982, 19, 68, 30, 'me-heikal-ekhah sobre a-ti para-ti yovilu reis sai');
INSERT INTO verses VALUES (14983, 19, 68, 31, 'ameu animal-de caneca congregação-de abelha-irmãos em-o-carrinho-de povos se-veste em-o-carrinho-de prata com-desdém povos batalhas desejarão');
INSERT INTO verses VALUES (14984, 19, 68, 32, 'virão oleiros de-a Egito Cuxe esmagará em-seus-mãos para-Elohim');
INSERT INTO verses VALUES (14985, 19, 68, 33, 'reinos-de a-terra cantarão para-Elohim cantaram Adonai Selá');
INSERT INTO verses VALUES (14986, 19, 68, 34, 'para-o-cavaleiro em-os-céus céus-de eis eis que dará voz voz-de o-oz:');
INSERT INTO verses VALUES (14987, 19, 68, 35, 'deite עוז para-a-Elohim sobre Israel orgulho-seu e-poder-seu nas-nuvens');
INSERT INTO verses VALUES (14988, 19, 68, 36, 'terrível Elohim de-teus-santuários El Israel ele dando força e-grandes ao-povo bendito Elohim');
INSERT INTO chapters VALUES (547, 19, 69, 37);
INSERT INTO verses VALUES (14989, 19, 69, 1, 'לַמְנַצֵּ֬חַ sobre rosas de-Davi');
INSERT INTO verses VALUES (14990, 19, 69, 2, 'salva-me Elohim que vieram águas até alma');
INSERT INTO verses VALUES (14991, 19, 69, 3, 'afoguei-eu-mesmo em-água no-fundo e-não-há de-pés entrei-eu-mesmo nos-fundos-de águas e-silfolete shtafat-ni');
INSERT INTO verses VALUES (14992, 19, 69, 4, 'yagati be-qari nichar gironi terminaram eini me-yachel le-elohai');
INSERT INTO verses VALUES (14993, 19, 69, 5, 'ravu de-os-pêlos da-cabeça-meu os-inimigos-meus sem-razão elas mesmas meu-esmagador ʾōyevay שֶׁ֑קֶר que não roubei-eu então restituirei-eu');
INSERT INTO verses VALUES (14994, 19, 69, 6, 'Elohim tu da''ata para-a-antiguidade-meu e-as-faltas-meus de-tu não escondidos-foram');
INSERT INTO verses VALUES (14995, 19, 69, 7, 'a יֵ֘בֹ֤שׁוּ em-mi esperança-teu Adonai yhwh exércitos a se-curvarão Bi buscadores-teu Elohim-de Israel');
INSERT INTO verses VALUES (14996, 19, 69, 8, 'porque עלך elevado-eu desonra cobriu-te humilhação face-de');
INSERT INTO verses VALUES (14997, 19, 69, 9, 'eu-fui para os meus vivos e-estrangeiro para-filhos-de AMI:');
INSERT INTO verses VALUES (14998, 19, 69, 10, 'porque quenat- beit-kha- akhal-tani- ve-cherpot- horfe-kha- caíram sobre-mim');
INSERT INTO verses VALUES (14999, 19, 69, 11, 'va-evche- בצום minha-alma e-foi la-cherpot- para-mim');
INSERT INTO verses VALUES (15000, 19, 69, 12, 'e-dei le-vushi- שָׂ֑ק וָאֱהִ֖י a-eles para-exemplo');
INSERT INTO verses VALUES (15001, 19, 69, 13, 'yasiachu em-mi יֹשְׁבֵי porta e-cantares bebedores e se cobriram;');
INSERT INTO verses VALUES (15002, 19, 69, 14, 'e-eu oração-mi para-ti yhwh tempo voluntário Elohim בְּרָב־ chasdekha responde-me em-verdade salvação-tua');
INSERT INTO verses VALUES (15003, 19, 69, 15, 'livra-me de-a-montanha e-a eu-afogo-me eu-salvo-me de-meu-inimigo e-de-os-fundos-de águas');
INSERT INTO verses VALUES (15004, 19, 69, 16, 'a você-me-lava safra águas e-a você-devora-me em-afogamento e-a você-esfola-me sobre-mim poço boca-dela');
INSERT INTO verses VALUES (15005, 19, 69, 17, 'responde-me yhwh porque bom chasdekha כְּרֹ֥ב רַ֝חֲמֶ֗יךָ faze para-mim');
INSERT INTO verses VALUES (15006, 19, 69, 18, 'e-a esconde פָּ֭נֶיךָ de-teu-escravo porque angústia לִֽי׃ apressa responde-me');
INSERT INTO verses VALUES (15007, 19, 69, 19, 'próxima a נַפְשִׁ֣י redime-a para-que ʾōyevay redeeme-me');
INSERT INTO verses VALUES (15008, 19, 69, 20, 'tu conheceste minha-ignomínia e-minha-vergonha e-para-a-meu-abatimento em-frente-de-você todo de-minhas-opressores');
INSERT INTO verses VALUES (15009, 19, 69, 21, 'humilhação quebrada meu-coração e-eu-ameacei e-eu-esperava para-balbuciar e-não-havia e-para-os-consoladores e-não מָצָֽאתִי׃');
INSERT INTO verses VALUES (15010, 19, 69, 22, 'e-eles-distribuíram em-a-sua-verdade cabeça e-para-o-seu-fome fazer-me-beber azedo');
INSERT INTO verses VALUES (15011, 19, 69, 23, 'será de-sua-mesa diante deles para-o-fogo e-para-a-paz para-laço');
INSERT INTO verses VALUES (15012, 19, 69, 24, 'se-esconderão de-seus-olhos de-ver e-suas-entranhas תָּמִ֥יד o-maio');
INSERT INTO verses VALUES (15013, 19, 69, 25, 'derramou-se sobre-alehem teu-zelo וַחֲר֥וֹן ira-teu perseguir-e-os');
INSERT INTO verses VALUES (15014, 19, 69, 26, 'תְּהִי־ sua-torre alma-deles em-suas-tendas a seja habitou');
INSERT INTO verses VALUES (15015, 19, 69, 27, 'porque tu que feriste perseguiram e-a dor vossos-mortos dirão-eles');
INSERT INTO verses VALUES (15016, 19, 69, 28, 'dá- a-von sobre עֲוֺנָ֑ם e-a e-virão em-vossa-justiça');
INSERT INTO verses VALUES (15017, 19, 69, 29, 'serão-aniquilados do-livro vida e-com dos-justos a serão-inscritos');
INSERT INTO verses VALUES (15018, 19, 69, 30, 'וַאֲנִי afligido e-doente teu-salvamento Elohim e-exalte-me');
INSERT INTO verses VALUES (15019, 19, 69, 31, 'glorificarei nome-de Elohim em-o-canto e-e-grandecerei-o em-a-adoração');
INSERT INTO verses VALUES (15020, 19, 69, 32, 'e-será-bom לַיהוָה משור bezerro que-parto partindo');
INSERT INTO verses VALUES (15021, 19, 69, 33, 'viram os humildes se-rejubilarão os-que-procuram Elohim e-viva');
INSERT INTO verses VALUES (15022, 19, 69, 34, 'porque ouviu yhwh pobres não e-a os-seus-prisioneiros não o-desprezou');
INSERT INTO verses VALUES (15023, 19, 69, 35, 'e-lo-louvarão céus e-a-terra mares e-todo réptil em-eles');
INSERT INTO verses VALUES (15024, 19, 69, 36, 'que Elohim e-salvá-la Siao e-construirá cidades-de Judá e-estarão-assentados nome e-e-a-posse-tê-la');
INSERT INTO verses VALUES (15025, 19, 69, 37, 'e-o-semente os-seus-servos inhaluhah ve-ohavei shemo habitare-m em-ela');
INSERT INTO chapters VALUES (548, 19, 70, 6);
INSERT INTO verses VALUES (15026, 19, 70, 1, 'לַ֝מְנַצֵּ֗חַ para-davíd le-hazkir');
INSERT INTO verses VALUES (15027, 19, 70, 2, 'Elohim para-me-resgatar yhwh לְעֶזְרָ֥תִי chushah');
INSERT INTO verses VALUES (15028, 19, 70, 3, 'envergonhar-se-ao veyachphru מְבַקְשֵׁ֢י נַ֫פְשִׁ֥י יִסֹּ֣גוּ אָחוֹר וְיִכָּלְמ֑וּ חֲפֵץֵי רָעָתִֽי׃');
INSERT INTO verses VALUES (15029, 19, 70, 4, 'yashuvu sobre porque בָּשְׁתָּ֑ם ha-omerim הֶאָ֥ח הֶאָֽח׃');
INSERT INTO verses VALUES (15030, 19, 70, 5, 'יָשִׂ֤ישׂוּ וְיִשְׂמַחוּ ׀ בְּךָ֗ todo מְבַ֫קְשֶׁ֥יךָ e dirão sempre será exaltado Elohim ohavei salvação-teu');
INSERT INTO verses VALUES (15031, 19, 70, 6, 'e-eu afligido וְאֶבְיוֹן֮ Elohim apressa-te para-mim ezri e-me-refugiar tu yhwh a esperar;');
INSERT INTO chapters VALUES (549, 19, 71, 24);
INSERT INTO verses VALUES (15032, 19, 71, 1, 'beka- yhwh tive-temor a enrubro-me para-eternidade');
INSERT INTO verses VALUES (15033, 19, 71, 2, 'em-a-tua-justiça tirarás-mim-da-perigo e-salvarás-mim inclinar- a-mim a-tua-orelha e-salva-nos');
INSERT INTO verses VALUES (15034, 19, 71, 3, 'foi לִ֨י ׀ para-a-rocha refúgio para-entrar sempre comandaste para-me-salvar porque rocha-meu וּמְצוּדָתִ֣י tu');
INSERT INTO verses VALUES (15035, 19, 71, 4, 'meu-Eloah livra-me de-mão-de ímpio de-cada de-opressores e-acidulados');
INSERT INTO verses VALUES (15036, 19, 71, 5, 'porque tu minha-esperança Adonai yhwh esperança-meu desde-juventude');
INSERT INTO verses VALUES (15037, 19, 71, 6, 'sobre-você me-apoi-ei de-ventre de-intestinos minha-mãe tu tu em-te minha-louvor תָמִֽיד׃');
INSERT INTO verses VALUES (15038, 19, 71, 7, 'como-maravilha eu-fui para-muitos e-você meu-refúgio- o-oz:');
INSERT INTO verses VALUES (15039, 19, 71, 8, 'se-encherá de-minha-boca teu-louvor-teu todo o-dia Sua beleza');
INSERT INTO verses VALUES (15040, 19, 71, 9, 'a jogue-me ao-tempo-de velhice como-para-comer minha-força não-que abandone-me-vós');
INSERT INTO verses VALUES (15041, 19, 71, 10, 'porque disseram meus-inimigos a-mim e-guardiões minha-alma no-ajem juntos-verso');
INSERT INTO verses VALUES (15042, 19, 71, 11, 'dizendo Elohim azav-o ridfu ve-tefshu-ho porque não-há matsil');
INSERT INTO verses VALUES (15043, 19, 71, 12, 'Elohim a te-rakhak de-mim meu-Eloah לְעֶזְרָ֥תִי');
INSERT INTO verses VALUES (15044, 19, 71, 13, 'envergonhar-se-ao yiklu sotnei נַ֫פְשִׁ֥י yaatuhu cherpeha e vergonha mevakshei רָעָתִֽי׃');
INSERT INTO verses VALUES (15045, 19, 71, 14, 'וַאֲנִי tamid ayacheil e-crearei sobre todo será teu louvor:');
INSERT INTO verses VALUES (15046, 19, 71, 15, 'de-mim dirá justiça-tua todo o-dia salvação-tua que não eu-sei contagem-deles');
INSERT INTO verses VALUES (15047, 19, 71, 16, 'irei-eu em-poderes Adonai lembrarei-eu justiça-tua apenas de ti:');
INSERT INTO verses VALUES (15048, 19, 71, 17, 'Elohim ensinado-me de-minhossenhos e-até eis-aqui darei-testemunho נִפְלְאוֹתֶֽיךָ׃');
INSERT INTO verses VALUES (15049, 19, 71, 18, 'e-também até velhice-separada e-cabeleira Elohim a deixar-me-ás até darei-contar-eu braço-teu para-geração para-todo virá גְּבוּרָתֶֽךָ׃');
INSERT INTO verses VALUES (15050, 19, 71, 19, 'e-teu-justiça Elohim até alta que fiz-te quem Elohim quem como-tu');
INSERT INTO verses VALUES (15051, 19, 71, 20, 'que dificuldades muitas e-más retornarás e-das-profundezas a-terra retornarás e-elevar-me');
INSERT INTO verses VALUES (15052, 19, 71, 21, 'tereb- gdulati- [גְּֽדֻלָּתִ֗י] tenachameni-');
INSERT INTO verses VALUES (15053, 19, 71, 22, 'também eu te-adoro bikli- nevel- ametkha- Elohai- a-ti para-ti bekinnor- santo Israel');
INSERT INTO verses VALUES (15054, 19, 71, 23, 'trarei-a-alegrar-me minhas-bocas que eu-cantarei-a para-ti e-minha-alma que resgatousteu');
INSERT INTO verses VALUES (15055, 19, 71, 24, 'também minhalingua todo o-dia será proferida justica-teu porque envergonham-se porque esconderam-se que-pesquisam רָעָתִֽי׃');
INSERT INTO chapters VALUES (550, 19, 72, 20);
INSERT INTO verses VALUES (15056, 19, 72, 1, 'para-salvação Elohim mishpatêkha como-rei ten wetzidqatkha para-filho-de rei');
INSERT INTO verses VALUES (15057, 19, 72, 2, 'ele-julgará teu-povo be-tsedeq wa-aniyekha em-justiça');
INSERT INTO verses VALUES (15058, 19, 72, 3, 'levarão harim shalom para-o-povo ugboth bitzedakah');
INSERT INTO verses VALUES (15059, 19, 72, 4, '[יִשְׁפֹּ֤ט] os-pobres-de povo salvar-á aos-filhos-de pobre e-esmagará o-opressor');
INSERT INTO verses VALUES (15060, 19, 72, 5, 'temer-te-ão com sol e-diante-de lunar geração gerações');
INSERT INTO verses VALUES (15061, 19, 72, 6, 'descerá como-chuva sobre gêz- kirbivim zarziph terra');
INSERT INTO verses VALUES (15062, 19, 72, 7, 'yiphraḥ- be-yamav justo e-muitos שָׁ֝ל֗וֹם até בְּלִי yerach:');
INSERT INTO verses VALUES (15063, 19, 72, 8, 'veyeredd- águas até mar uminnahar até extremidades-de terra');
INSERT INTO verses VALUES (15064, 19, 72, 9, 'lefananav yikrêwû tsiyim ve-oyevav pó yelachchu');
INSERT INTO verses VALUES (15065, 19, 72, 10, 'melechey tarsish ve-iyyim oferta yashivu reis-de Sabá veseva eshchar yakrivu');
INSERT INTO verses VALUES (15066, 19, 72, 11, 'e-se-inclinar-ao a-ele todo reis todo nele o-abrirão-lhe-o');
INSERT INTO verses VALUES (15067, 19, 72, 12, 'porque ele-salvará-a pobre מְשַׁוּ֑עַ e-pobre a-ele עֹזֵ֥ר a-ele');
INSERT INTO verses VALUES (15068, 19, 72, 13, 'ter-compassão-do sobre o-fraco וְאֶבְי֑וֹן e-almas-de-os pobres יוֹשִֽׁיעַ׃');
INSERT INTO verses VALUES (15069, 19, 72, 14, 'de-meio-de ele-redimirá-a almas e-ele-será-valioso calar-se em-seus-olhos');
INSERT INTO verses VALUES (15070, 19, 72, 15, 'e-viva e-ele-dará- a-ele de-o-ouro de-sheba e-orar-a em-seu-vez permanente todo o-dia abençoará-o');
INSERT INTO verses VALUES (15071, 19, 72, 16, 'haja peça-de- de-bar na-terra em-a-cabeça-de os-montes tremura-terá como-o-Líbano seu-fruto e-brilharão de-a-cidade como-erva a-terra');
INSERT INTO verses VALUES (15072, 19, 72, 17, 'haja seu-nome para sempre diante-de Sol seu-nome e-bençã-o nele todo nele ele-aprovem-no');
INSERT INTO verses VALUES (15073, 19, 72, 18, 'bendito- yhwh yhwh Elohim Israel fez maravilhas para-ele-somente');
INSERT INTO verses VALUES (15074, 19, 72, 19, 'e-bendito- nome glória-seu para-always e-cheio-vai glória-seu a todo a-terra אָ֘מֵ֥ן ׀ וְאָמֵֽן׃');
INSERT INTO verses VALUES (15075, 19, 72, 20, 'terminado orações Davi filho-de Jessé');
INSERT INTO chapters VALUES (551, 19, 73, 28);
INSERT INTO verses VALUES (15076, 19, 73, 1, 'salmo לְאָ-סָ֥ף somente bom para-israel Elohim para-filhos-de de-coração');
INSERT INTO verses VALUES (15077, 19, 73, 2, 'e-eu como-pequeno caminhos-meus como-não-existe אֲשֻׁרָֽי׃');
INSERT INTO verses VALUES (15078, 19, 73, 3, 'porque minha-ira nos-insensatos paz ímpios אֶרְאֶֽה׃');
INSERT INTO verses VALUES (15079, 19, 73, 4, 'que não lajes para-morrem-los e-no-saudável mas');
INSERT INTO verses VALUES (15080, 19, 73, 5, 'em-trabalho mortal não-há-para-ele e-com- não não serão-tocados');
INSERT INTO verses VALUES (15081, 19, 73, 6, 'לָ֭כֵן desdenham-noles orgulho cobrir-se- seis chamas a-eles');
INSERT INTO verses VALUES (15082, 19, 73, 7, 'sair de-gordura das-suas-olhos passaram de-mamadas coração');
INSERT INTO verses VALUES (15083, 19, 73, 8, 'esconderam-se e-falaram mal opressor do-alto dirão-');
INSERT INTO verses VALUES (15084, 19, 73, 9, 'sentar-se- nos-céus suas-bocas וּלְשׂוֹנוֹתָם andará- na-terra');
INSERT INTO verses VALUES (15085, 19, 73, 10, 'por-tanto amo aqui e-aqua enchei secar-se- a-eles');
INSERT INTO verses VALUES (15086, 19, 73, 11, 'e-diremos- como יָדַֽע— El e-há saber- em-Alto-');
INSERT INTO verses VALUES (15087, 19, 73, 12, 'eis-que- estes os ímpios eternidade eternidade higugu- força');
INSERT INTO verses VALUES (15088, 19, 73, 13, 'somente rik זִכִּ֣יתִי לְבָבִ֑י ve-erchatset בְּנִקָּי֣וֹן kapayim:');
INSERT INTO verses VALUES (15089, 19, 73, 14, 've-ehi naguwa'' todo o-dia vetokhakhati labbaqarim:');
INSERT INTO verses VALUES (15090, 19, 73, 15, 'se אָ֭מַרְתִּי asaparah eis eis dor os-teus-filhos traí-tei');
INSERT INTO verses VALUES (15091, 19, 73, 16, 'e-eu-ponderava para-conhecer esta עָמָ֖ל em-meus-olhos');
INSERT INTO verses VALUES (15092, 19, 73, 17, 'até irei a de-sanctuários-de El entendo-eu para-os-fins-deles');
INSERT INTO verses VALUES (15093, 19, 73, 18, 'porém em-partes colocarás a-eles os-derribaste para-o-mal');
INSERT INTO verses VALUES (15094, 19, 73, 19, 'como foram para-a em-um-ponto-do-tempo terminaram cessaram de בַּלָּהֽוֹת׃');
INSERT INTO verses VALUES (15095, 19, 73, 20, 'como-em-sonho do-aquele-que-se-levanta Adonai na-cidade seu-silhueta desdenha-vos');
INSERT INTO verses VALUES (15096, 19, 73, 21, 'que fermentará-se לְבָבִ֑י e-minhas-vidas eu-despojar-me-ei');
INSERT INTO verses VALUES (15097, 19, 73, 22, 'e eu carne e-não conheça בהMZות era contigo');
INSERT INTO verses VALUES (15098, 19, 73, 23, 'e-eu permanente contigo agarraste-te por-mão-de benjamita');
INSERT INTO verses VALUES (15099, 19, 73, 24, 'em-tua-conselho guiar-me וְ֝אַחַ֗ר glória toma-me');
INSERT INTO verses VALUES (15100, 19, 73, 25, 'quem para-mim em-os-céus e-com-você na-terra quis-eu na-terra');
INSERT INTO verses VALUES (15101, 19, 73, 26, 'כָּלָה resto-meu e-corpo-meu tor- coração-meu e-minha-porção Elohim para-eternidade');
INSERT INTO verses VALUES (15102, 19, 73, 27, 'porque eis afastado-você perecerao ela-esmagou todo meretriz-ela מִמֶּֽךָּ׃');
INSERT INTO verses VALUES (15103, 19, 73, 28, 'e-eu proximidade-a Elohim para-mim bom sua-tenda em-Adonai yhwh de-meu-refúgio para-contar todo anjos-teus');
INSERT INTO chapters VALUES (552, 19, 74, 23);
INSERT INTO verses VALUES (15104, 19, 74, 1, 'instrutor- לְאָ-סָ֥ף לָמָ֣ה Elohim abandonaste [לָנֶ֑צַח] que-sonhe teu-ira em-o-rebanho alimento-teu');
INSERT INTO verses VALUES (15105, 19, 74, 2, 'macho assembleia-tua compraste antes resgatouste tribo-de a tua herança monte-de Sion este habita-te em-ele');
INSERT INTO verses VALUES (15106, 19, 74, 3, 'elevaste passos-teus para-estender eternamente todo foi-mau inimigo no santuário:');
INSERT INTO verses VALUES (15107, 19, 74, 4, 'gritaram teus-inimigos em-meio-de teus-festivais שָׂ֖moּ seus-sinais sinais');
INSERT INTO verses VALUES (15108, 19, 74, 5, 'será-conhecido como-trazendo para-alto em-teu madeira cardamos');
INSERT INTO verses VALUES (15109, 19, 74, 6, 'seus-folhas juntos em-fracasso e-em-fraudes polirão-os');
INSERT INTO verses VALUES (15110, 19, 74, 7, 'enviem em-chamas de-teu-santuário לָ֝אָ֗רֶץ profanem tabernáculo- שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (15111, 19, 74, 8, 'disseram בליבָּם nossos juntamente queimaram todo festas- El na-terra');
INSERT INTO verses VALUES (15112, 19, 74, 9, 'sinais-nossos não vimos não-há ainda profeta sabe com-nosso conheceu até מָה׃');
INSERT INTO verses VALUES (15113, 19, 74, 10, 'até quando Elohim blasfemará צר in-ate o-inimigo teu-nome para sempre;');
INSERT INTO verses VALUES (15114, 19, 74, 11, 'por-que t-remeterá sua-mão e-a-tua-direita de-o-centro e-completa');
INSERT INTO verses VALUES (15115, 19, 74, 12, 'e-Elohim Malchi ao-oriente o-fazedor as-salvações em-meio-de a-terra');
INSERT INTO verses VALUES (15116, 19, 74, 13, 'tu tu-deste em-a-tua-forteza mar quebraste topos-de tubarões sobre as-águas');
INSERT INTO verses VALUES (15117, 19, 74, 14, 'tu ela-esmigalhou cabeças-de leviathan te-tornas-te alimento para-o-povo para-os-sábios');
INSERT INTO verses VALUES (15118, 19, 74, 15, 'tu abriste מַעְיָ֣ן e-nachal tu hovash-ta naharot eitan');
INSERT INTO verses VALUES (15119, 19, 74, 16, 'a-ti dia também noite tu tu hakinto-ta luzeiro vashamesh');
INSERT INTO verses VALUES (15120, 19, 74, 17, 'tu histabta todo gevolot terra kayitz tu tu yetartam');
INSERT INTO verses VALUES (15121, 19, 74, 18, 'lembra-de esta cheref yhwh yhwh נָ֝בָ֗ל rejeitaram שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (15122, 19, 74, 19, 'a darás para-a-vida-de alma animal-de vivente-de os-pobres-teus a esquecerás para sempre;');
INSERT INTO verses VALUES (15123, 19, 74, 20, 'olha para-a-aliança que encheram das-sombras- terra pastagens violência');
INSERT INTO verses VALUES (15124, 19, 74, 21, 'a habitou destruído derrotados עָנִ֥י וְ֝אֶבְי֗וֹן jalelu שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (15125, 19, 74, 22, 'qumah Elohim רִיבָ֣ה rivekha macho cherfatkha de-mim נָ֝בָ֗ל todo o-dia');
INSERT INTO verses VALUES (15126, 19, 74, 23, 'a voz voz-de tsorekha inveja qamekha olé תָמִֽיד׃');
INSERT INTO chapters VALUES (553, 19, 75, 11);
INSERT INTO verses VALUES (15127, 19, 75, 1, 'ao-regente a tashcheth mizmor le-asaf שיר׃');
INSERT INTO verses VALUES (15128, 19, 75, 2, 'hodinu lekha Elohim hodinu veqarov o-teu-nome sipporu נִפְלְאוֹתֶֽיךָ׃');
INSERT INTO verses VALUES (15129, 19, 75, 3, 'que e-qaq-a reunião eu mesharim eshpot');
INSERT INTO verses VALUES (15130, 19, 75, 4, 'os-fracos terra e-todo eu eu tikantiti ammudeha selá');
INSERT INTO verses VALUES (15131, 19, 75, 5, 'eu-disse lahollim a taholu e-aos-impíos a תָּרִ֥ימוּ cornice');
INSERT INTO verses VALUES (15132, 19, 75, 6, 'a Tirimú para-o-alto vossa-cornice dizeis no-garganta deslocamento');
INSERT INTO verses VALUES (15133, 19, 75, 7, 'que não do-alvo e-do-oeste e-não do-deserto הָרִים׃');
INSERT INTO verses VALUES (15134, 19, 75, 8, 'porque Elohim juiz-que-julga este e-o-abaisse e-este ele-elevará');
INSERT INTO verses VALUES (15135, 19, 75, 9, 'que copo em-a-mão-de yhwh e vinho de-espuma enchei da-oferta e-ele-recolheu de-deste somente seus-guarda encontrarão beberão todo de-iníquos- terra');
INSERT INTO verses VALUES (15136, 19, 75, 10, 'וַאֲנִי darei-contar-eu para-sempre azammará a-אלהים Jacó');
INSERT INTO verses VALUES (15137, 19, 75, 11, 'e-todo קרני ímpios agadeeá terommanah chifres');
INSERT INTO chapters VALUES (554, 19, 76, 13);
INSERT INTO verses VALUES (15138, 19, 76, 1, 'ao-regente em-nas-linguas-musicais mizmor le-asaf שיר׃');
INSERT INTO verses VALUES (15139, 19, 76, 2, 'conhecido em-Judá Elohim em-Israel grande nome-dele');
INSERT INTO verses VALUES (15140, 19, 76, 3, 'e-houve com-integridade sukho e-nosso-lugares-de-habitação em-Sion');
INSERT INTO verses VALUES (15141, 19, 76, 4, 'ali quebraste raios-de arco escudo e espada e-guerra Selá');
INSERT INTO verses VALUES (15142, 19, 76, 5, 'luziro tu majestoso מֵֽהַרְרֵי־ lado:');
INSERT INTO verses VALUES (15143, 19, 76, 6, 'enganem-se fortes coração silenciem dormitem e-não acharam todo homens de força mãos-deles-verso-final');
INSERT INTO verses VALUES (15144, 19, 76, 7, 'de-teu-ira Elohim-de Jacó adormeceste וְרֶ֣כֶב e-suspira');
INSERT INTO verses VALUES (15145, 19, 76, 8, 'tu terrível tu-eres tu estabelecerá em-te desde-então teu-ira');
INSERT INTO verses VALUES (15146, 19, 76, 9, 'מִשּׁׂאָרֵי מָע֫וֹן fiz-te-ouvir juízo terra temor e-silenciar-se');
INSERT INTO verses VALUES (15147, 19, 76, 10, 'em-levantar- para-o-julgamento Elohim para-salvar todo humilhar-se- terra Selá');
INSERT INTO verses VALUES (15148, 19, 76, 11, 'porque homem homem tu-o-confessarás sheerit ira te-apertarás');
INSERT INTO verses VALUES (15149, 19, 76, 12, 'juraram e-satisfazer-se-ão para-יהוה elohim-vosso todo em-o-seu-redor jubileiem sai para-o-tremor');
INSERT INTO verses VALUES (15150, 19, 76, 13, 'ele-fortificará espírito príncipes terrível para-os-reis- terra');
INSERT INTO chapters VALUES (555, 19, 77, 21);
INSERT INTO verses VALUES (15151, 19, 77, 1, 'ao-regente sobre para-Asaph salmo');
INSERT INTO verses VALUES (15152, 19, 77, 2, 'de-mim a Elohim e-eu-clamo קוֹלִ֥י a Elohim e-ele-presta-atenção para-mim');
INSERT INTO verses VALUES (15153, 19, 77, 3, 'em-dia minha-tristeza Adonai eu-procurei mão-minha noite está-seca e-não desfalece de-aversão ele-consola alma-de-mim');
INSERT INTO verses VALUES (15154, 19, 77, 4, 'eu-recordarei Elohim e-eu-ternamente-amarei eu-conversarei e-você-se-envolverá רוּחִ֣י Selá');
INSERT INTO verses VALUES (15155, 19, 77, 5, 'você-possuiu guardadas meus-olhos eu-me-desgastei e-não אֲדַבֵּֽר׃');
INSERT INTO verses VALUES (15156, 19, 77, 6, '[חִשַּׁ֣בְתִּי] dias ao-oriente anos pelos-dias');
INSERT INTO verses VALUES (15157, 19, 77, 7, 'eu-recordarei minha-música na-noite com coração-meu falarei e-ele-procurou ruchi:');
INSERT INTO verses VALUES (15158, 19, 77, 8, 'os-dos-séculos ele-desdenhará Adonai e-não acrescentará para-querer ainda');
INSERT INTO verses VALUES (15159, 19, 77, 9, 'foi-apaziguado para sempre bondade-de-ele terminou disse para-a-geração וָדֹר׃');
INSERT INTO verses VALUES (15160, 19, 77, 10, 'h-shakhach chanot El se qafatz com-o-rancor rakhamav Selá');
INSERT INTO verses VALUES (15161, 19, 77, 11, 'e disse chaloti ela shnot yamin altíssimo');
INSERT INTO verses VALUES (15162, 19, 77, 12, 'maalley- Yah porque ezkera ao-oriente pilecha');
INSERT INTO verses VALUES (15163, 19, 77, 13, 'e-afirmarei em-todo o-teu-trabalho e-em-tus-maldades falarei-eu');
INSERT INTO verses VALUES (15164, 19, 77, 14, 'Elohim [בַּקֹּ֣דֶשׁ] [דַּרְכֶּ֑ךָ] quem El como-Elohim');
INSERT INTO verses VALUES (15165, 19, 77, 15, 'tu o-elohim fez maravilha manifestaste-vos aos-povos teu-poder');
INSERT INTO verses VALUES (15166, 19, 77, 16, 'g-a-l-t-a com-braco povo-teu filhos-de Jacó e-y-o-s-e-f Selá');
INSERT INTO verses VALUES (15167, 19, 77, 17, 'r-a-u-k-ha m-a-i-m Elohim r-a-u-k-ha águas y-a-ch-il-u אַ֝֗ף certamente t-e-h-o-m-o-t');
INSERT INTO verses VALUES (15168, 19, 77, 18, 'z-o-r-em-u águas a-v-o-t q-o-l voz céus também [אַף־חֲ֝צָצֶ֗יךָ] [יִתְהַלָּֽכוּ]');
INSERT INTO verses VALUES (15169, 19, 77, 19, 'voz [רַעַמְךָ֨] [׀] [בַּגַּלְגַּ֗ל] [הֵאִ֣ירוּ] [בְרָקִ֣ים] [תֵּבֵ֑ל] [רָגְזָ֖ה] a-terra');
INSERT INTO verses VALUES (15170, 19, 77, 20, '[בַּיָּ֤ם] [דַּרְכֶּ֗ךָ] em-aquas muitos [בְּמַ֣יִם] não [וְ֝עִקְּבוֹתֶ֗יךָ]');
INSERT INTO verses VALUES (15171, 19, 77, 21, '[נָחִ֣יתָ] [כַצֹּ֣אן] povo-teu [בְּֽיַד־מֹשֶׁ֥ה] Moisés e-Aarão');
INSERT INTO chapters VALUES (556, 19, 78, 72);
INSERT INTO verses VALUES (15172, 19, 78, 1, 'instrutor- לְאָ-סָ֥ף הַאֲזִ֣ינָה עַ֭מִּי [תּוֹרָתִ֑י] [הַטּ֥וּ] [אָ֝זְנְכֶ֗ם] [לְאִמְרֵי] a boca:');
INSERT INTO verses VALUES (15173, 19, 78, 2, '[אֶפְתְּחָ֣ה] [בְמָשָׁ֣ל] [פִּ֑י] [אַבִּ֥יעָה] [חִ֝יד֗וֹת] de-mim');
INSERT INTO verses VALUES (15174, 19, 78, 3, 'que [שָׁ֭מַעְנוּ] [וַנֵּדָעֵ֑ם] [וַ֝אֲבוֹתֵ֗ינוּ] contaram- para-nós');
INSERT INTO verses VALUES (15175, 19, 78, 4, 'não [נְכַחֵ֨ד] [׀] para-geração [לְד֥וֹר] [אַחֲר֗וֹן] [מְֽ֭סַפְּרִים] yhwh yhwh [וֶעֱזוּז֥וֹ] que fez');
INSERT INTO verses VALUES (15176, 19, 78, 5, 'E-levantou [עֵד֨וּת] [׀] [בְּֽיַעֲקֹ֗ב] nome [שָׂ֤ם] que [אֲשֶׁ֣ר] a [אֶת־אֲבוֹתֵ֑ינוּ] [לְ֝הוֹדִיעָ֗ם] [לִבְנֵיהֶֽם]');
INSERT INTO verses VALUES (15177, 19, 78, 6, 'para-que [יֵדְע֨וּ] geração [דּ֣וֹר] filhos [בָּנִ֣ים] [יִוָּלֵ֑דוּ] [יָ֝קֻ֗מוּ] [וִֽיסַפְּר֥וּ]');
INSERT INTO verses VALUES (15178, 19, 78, 7, '[וְיָשִׂ֥ימוּ] [בֵֽאלֹהִ֗ים] [כִּ֫סְלָ֥ם] e-não [יִ֭שְׁכְּחוּ] [מַֽעַלְלֵי] El [וּמִצְוֺתָ֥יו] [יִנְצֹֽרוּ]');
INSERT INTO verses VALUES (15179, 19, 78, 8, 'e-não [יִהְי֨וּ] [׀] [כַּאֲבוֹתָ֗ם] [דּוֹר֮] [סוֹרֵ֢ר] [וּמֹ֫רֶ֥ה] não הֵכִ֣ין no seu coração e-não [אֶת־אֵ֣ל] a El [sem-traducao]');
INSERT INTO verses VALUES (15180, 19, 78, 9, 'filhos-de Efrayim [רוֹמֵי־קָ֑שֶׁת] [הָ֝פְכ֗וּ] [בְּי֣וֹם] [קְרָֽב]');
INSERT INTO verses VALUES (15181, 19, 78, 10, 'não [שָׁ֭מְרוּ] aliança Elohim [וּ֝בְתוֹרָת֗וֹ] [מֵאֲנ֥וּ] [לָלֶֽכֶת]');
INSERT INTO verses VALUES (15182, 19, 78, 11, '[וַיִּשְׁכְּח֥וּ] [עֲלִילוֹתָ֑יו] [וְ֝נִפְלְאוֹתָ֗יו] que [הֶרְאָֽם]');
INSERT INTO verses VALUES (15183, 19, 78, 12, 'diante [אֲ֭בוֹתָם] fez [פֶ֑לֶא] em-terra-de [מִצְרַ֣יִם] [שְׂדֵה־צֹֽעַן]');
INSERT INTO verses VALUES (15184, 19, 78, 13, '[בָּ֣קַע] mar [וַיַּֽעֲבִירֵ֑ם] [וַֽיַּצֶּב־מַ֥יִם] águas');
INSERT INTO verses VALUES (15185, 19, 78, 14, '[וַיַּנְחֵ֣ם] [בֶּעָנָ֣ן] [יוֹמָ֑ם] e-todo [בְּא֣וֹר] [אֵֽשׁ]');
INSERT INTO verses VALUES (15186, 19, 78, 15, '[יְבַקַּ֣ע] [צֻ֭רִים] no-deserto [וַ֝יַּ֗שְׁקְ] [כִּתְהֹמ֥וֹת] multiplicai');
INSERT INTO verses VALUES (15187, 19, 78, 16, '[וַיּוֹצִ֣א] [נוֹזְלִ֣ים] [מִסָּ֑לַע] [וַיּ֖וֹרֶד] [כַּנְּהָר֣וֹת] águas');
INSERT INTO verses VALUES (15188, 19, 78, 17, '[וַיּוֹסִ֣יפוּ] [ע֖[d]וֹד] a-ele [לַֽמְר֥וֹת] Altissimo [בַּצִּיָּֽה]');
INSERT INTO verses VALUES (15189, 19, 78, 18, '[וַיְנַסּוּ־אֵ֥ל] El [לִֽשְׁאָל־אֹ֥כֶל] [לְנַפְשָֽׁם]');
INSERT INTO verses VALUES (15190, 19, 78, 19, '[וַֽיְדַבְּר֗וּ] [בֵּֽאלֹ֫הִ֥ים] [אָ֭מְרוּ] [הֲי֣וּכַל] El [לַעֲרֹ֥ךְ] [שֻׁ֝לְחָ֗ן] no-deserto');
INSERT INTO verses VALUES (15191, 19, 78, 20, 'eis [הִכָּה־צ֨וּר] [׀] [וַיָּז֣וּבוּ] águas [וּנְחָלִ֢ים] [יִ֫שְׁטֹ֥פוּ] [הֲגַם־לֶ֭חֶם] Léchem [תֵּ֑ת] [אִם־יָכִ֖ין] se [לְעַמּֽוֹ] não para-o-povo-suo');
INSERT INTO verses VALUES (15192, 19, 78, 21, 'por-tanto ouviu yhwh yhwh [וַֽיִּתְעַבָּ֥ר] [וְ֭אֵשׁ] [נִשְּׂקָ֣ה] e-também אַ֝֗ף subir [בְיִשְׂרָאֵֽל]');
INSERT INTO verses VALUES (15193, 19, 78, 22, 'que não [הֶ֭אֱמִינוּ] [בֵּאלֹהִ֑ים] e-não [בָ֝טְח֗וּ] [בִּֽישׁוּעָתֽוֹ]');
INSERT INTO verses VALUES (15194, 19, 78, 23, 'E-ordenou [שְׁחָקִ֣ים] de cima [וְדַלְתֵ֖י] céus [פָּתָֽח]');
INSERT INTO verses VALUES (15195, 19, 78, 24, '[וַיַּמְטֵ֬ר] sobre-eles de de-comer [וּדְגַן־שָׁ֝מַ֗יִם] dar deu a-eles');
INSERT INTO verses VALUES (15196, 19, 78, 25, 'pão [אַ֭בִּירִים] comer homem [צֵידָ֬ה] enviou a-eles [לָשֹֽׂבַע]');
INSERT INTO verses VALUES (15197, 19, 78, 26, '[יַסַּ֣ע] [קָ֭דִים] nos-céus [וַיְנַהֵ֖ג] [בְּעֻזּ֣וֹ] [תֵימָֽן]');
INSERT INTO verses VALUES (15198, 19, 78, 27, '[וַיַּמְטֵ֬ר] sobre-eles כֶּעָפָ֣ר [שְׁאֵ֑ר] [וּֽכְח֥וֹל] mares ave asa');
INSERT INTO verses VALUES (15199, 19, 78, 28, 'E-fez-cair em-meio-de de-o-lager-dele [סָ֝בִ֗יב] [לְמִשְׁכְּנֹתָֽיו]');
INSERT INTO verses VALUES (15200, 19, 78, 29, '[וַיֹּאכְל֣וּ] [וַיִּשְׂבְּע֣וּ] muito [וְ֝תַֽאֲוָתָ֗ם] [יָבִ֥א] a-eles');
INSERT INTO verses VALUES (15201, 19, 78, 30, 'não se foram embora [ע֝֗וֹד] עוֹד [בְּפִיהֶֽם] [sem-traducao]');
INSERT INTO verses VALUES (15202, 19, 78, 31, '[וְאַ֤ף] Elohim [׀] subir [בָהֶ֗ם] [וַֽ֭יַּהֲרֹג] [בְּמִשְׁמַנֵּיהֶ֑ם] Israel [יִשְׂרָאֵ֣ל]');
INSERT INTO verses VALUES (15203, 19, 78, 32, 'em-todo esta [וְלֹֽא־הֶ֝אֱמִ֗ינוּ] ainda e-não');
INSERT INTO verses VALUES (15204, 19, 78, 33, '[וַיְכַל־בַּהֶ֥בֶל] [יְמֵיהֶ֑ם] [וּ֝שְׁנוֹתָ֗ם] [בַּבֶּהָלָֽה]');
INSERT INTO verses VALUES (15205, 19, 78, 34, 'se [וּדְרָשׁ֑וּהוּ] [וְ֝שָׁ֗בוּ] [וְשִֽׁחֲרוּ־אֵֽל] El');
INSERT INTO verses VALUES (15206, 19, 78, 35, '[וַֽ֭יִּזְכְּרוּ] porque Elohim [וְאֵ֥ל] e-a [גֹּאֲלָֽם]');
INSERT INTO verses VALUES (15207, 19, 78, 36, '[וַיְפַתּ֥וּהוּ] [בְּפִיהֶ֑ם] [וּ֝בִלְשׁוֹנָ֗ם] [יְכַזְּבוּ־לֽוֹ]');
INSERT INTO verses VALUES (15208, 19, 78, 37, '[וְ֭לִבָּם] não firme com-ele e-não [בִּבְרִיתֽוֹ] [sem-traducao]');
INSERT INTO verses VALUES (15209, 19, 78, 38, 'e-ele [רַח֨וּם] perdoará [יְכַפֵּ֥ר] e-não [וְֽלֹא־יַ֫שְׁחִ֥ית] [וְ֭הִרְבָּה] para-retornar sua-ira e-não [כָּל־חֲמָתֽוֹ] todo [sem-traducao]');
INSERT INTO verses VALUES (15210, 19, 78, 39, '[וַ֭יִּזְכֹּר] porque [הֵ֑מָּה] espírito espírito [וְלֹ֣א] e-não');
INSERT INTO verses VALUES (15211, 19, 78, 40, '[כַּ֭מָּה] [יַמְר֣וּהוּ] b''midbar [יַ֝עֲצִיב֗וּהוּ] [בִּֽישִׁימֽוֹן]');
INSERT INTO verses VALUES (15212, 19, 78, 41, '[וַיָּשׁ֣וּבוּ] [וַיְנַסּ֣וּ] El [וּקְד֖וֹשׁ] Israel [הִתְווּ]');
INSERT INTO verses VALUES (15213, 19, 78, 42, 'não [אֶת־יָד֑וֹ] dia sua-mão dia que [sem-traducao] de-mim [sem-traducao]');
INSERT INTO verses VALUES (15214, 19, 78, 43, 'que nome [אֹֽתוֹתָ֑יו] [וּ֝מוֹפְתָ֗יו] [בִּשְׂדֵה־צֹֽעַן]');
INSERT INTO verses VALUES (15215, 19, 78, 44, '[וַיַּהֲפֹ֣ךְ] [לְ֭דָם] [יְאֹרֵיהֶ֑ם] [וְ֝נֹזְלֵיהֶ֗ם] não');
INSERT INTO verses VALUES (15216, 19, 78, 45, '[יְשַׁלַּ֬ח] neles tarde [וַיֹּאכְלֵ֑ם] [וּ֝צְפַרְדֵּ֗עַ] [וַתַּשְׁחִיתֵֽם]');
INSERT INTO verses VALUES (15217, 19, 78, 46, 'E-colocou [לֶחָסִ֣יל] [יְבוּלָ֑ם] [וִֽ֝יגִיעָ֗ם] [לָאַרְבֶּֽה]');
INSERT INTO verses VALUES (15218, 19, 78, 47, '[יַהֲרֹ֣ג] [בַּבָּרָ֣ד] [גַּפְנָ֑ם] [וְ֝שִׁקְמוֹתָ֗ם] [בַּֽחֲנָמַֽל]');
INSERT INTO verses VALUES (15219, 19, 78, 48, '[וַיַּסְגֵּ֣ר] [לַבָּרָ֣ד] [בְּעִירָ֑ם] [וּ֝מִקְנֵיהֶ֗ם] [לָרְשָׁפִֽים]');
INSERT INTO verses VALUES (15220, 19, 78, 49, '[יְשַׁלַּח־בָּ֨ם] [׀] [חֲר֬וֹן] [אַפּ֗וֹ] [עֶבְרָ֣ה] [וָזַ֣עַם] [וְצָרָ֑ה] [מִ֝שְׁלַ֗חַת] מלאכים maus');
INSERT INTO verses VALUES (15221, 19, 78, 50, '[יְפַלֵּ֥ס] [נָתִ֗יב] [לְאַ֫פּ֥וֹ] não escuridão morta almas e-os-seus-vivos [הִסְגִּֽיר] [sem-traducao]');
INSERT INTO verses VALUES (15222, 19, 78, 51, 'e-feriu todo primogênito-de em-Egito primeira [בְּאָהֳלֵי־חָֽם] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (15223, 19, 78, 52, '[וַיַּסַּ֣ע] [כַּצֹּ֣אן] povo-seu [וַֽיְנַהֲגֵ֥ם] [כַּ֝עֵ֗דֶר] no-deserto');
INSERT INTO verses VALUES (15224, 19, 78, 53, '[וַיַּנְחֵ֣ם] [לָ֭בֶטַח] e-não [פָחָ֑דוּ] e-[OBJ] [כִּסָּ֥ה] o-mar');
INSERT INTO verses VALUES (15225, 19, 78, 54, '[וַ֭יְבִיאֵם] a território sua-santidade monte-de ze [sem-traducao] direita-de-ele');
INSERT INTO verses VALUES (15226, 19, 78, 55, 'e-ele-expulsou [מִפְּנֵיהֶ֨ם] [׀] [גּוֹיִ֗ם] [וַֽ֭יַּפִּילֵם] herança [נַחֲלָ֑ה] em-suas-tendas tribos-de Israel');
INSERT INTO verses VALUES (15227, 19, 78, 56, '[וַיְנַסּ֣וּ] [וַ֭יַּמְרוּ] a Elohim [וְ֝עֵדוֹתָ֗יו] não não');
INSERT INTO verses VALUES (15228, 19, 78, 57, '[וַיִּסֹּ֣גוּ] [וַֽ֭יִּבְגְּדוּ] [כַּאֲבוֹתָ֑ם] [נֶ֝הְפְּכ֗וּ] [כְּקֶ֣שֶׁת] [רְמִיָּֽה]');
INSERT INTO verses VALUES (15229, 19, 78, 58, '[וַיַּכְעִיס֥וּהוּ] [בְּבָמוֹתָ֑ם] [וּ֝בִפְסִילֵיהֶ֗ם] [יַקְנִיאֽוּהוּ]');
INSERT INTO verses VALUES (15230, 19, 78, 59, 'ouviu Elohim [וַֽיִּתְעַבָּ֑ר] [וַיִּמְאַ֥ס] muito em-Israel');
INSERT INTO verses VALUES (15231, 19, 78, 60, '[וַ֭יִּטֹּשׁ] tabernáculo-de Shilo [אֹ֝֗הֶל] [שִׁכֵּ֥ן] [בָּאָדָֽם]');
INSERT INTO verses VALUES (15232, 19, 78, 61, 'E-colocou [לַשְּׁבִ֣י] עֻזּ֑וֹ [וְֽתִפְאַרְתּ֥וֹ] na-mao-de [sem-traducao]');
INSERT INTO verses VALUES (15233, 19, 78, 62, '[וַיַּסְגֵּ֣ר] [לַחֶ֣רֶב] povo-seu [וּ֝בְנַחֲלָת֗וֹ] [הִתְעַבָּֽר]');
INSERT INTO verses VALUES (15234, 19, 78, 63, '[בַּחוּרָ֥יו] [אָֽכְלָה־אֵ֑שׁ] fogo não não [sem-traducao]');
INSERT INTO verses VALUES (15235, 19, 78, 64, '[כֹּ֭הֲנָיו] com-a-espada [נָפָ֑לוּ] [וְ֝אַלְמְנֹתָ֗יו] não [תִבְכֶּֽינָה]');
INSERT INTO verses VALUES (15236, 19, 78, 65, '[וַיִּקַ֖ץ] [כְּיָשֵׁ֥ן] Adonai [Adonai] [כְּ֝גִבּ֗וֹר] [מִתְרוֹנֵ֥ן]');
INSERT INTO verses VALUES (15237, 19, 78, 66, 'e atingiram- [אָח֑וֹר] para-trás eternidade dar deu a-eles');
INSERT INTO verses VALUES (15238, 19, 78, 67, '[וַ֭יִּמְאַס] em-tenda-de José [וּֽבְשֵׁ֥בֶט] [אֶ֝פְרַ֗יִם] não [בָחָֽר]');
INSERT INTO verses VALUES (15239, 19, 78, 68, '[וַ֭יִּבְחַר] a tribo-de Judá a monte-de Sion que amou');
INSERT INTO verses VALUES (15240, 19, 78, 69, 'E-edificou como [מִקְדָּשׁ֑וֹ] [כְּ֝אֶ֗רֶץ] [יְסָדָ֥הּ] [לְעוֹלָֽם]');
INSERT INTO verses VALUES (15241, 19, 78, 70, '[וַ֭יִּבְחַר] [בְּדָוִ֣ד] seu-servo [וַ֝יִּקָּחֵ֗הוּ] [מִֽמִּכְלְאֹ֥ת] [צֹֽאן]');
INSERT INTO verses VALUES (15242, 19, 78, 71, '[מֵאַחַ֥ר] [עָל֗וֹת] [הֱבִ֫יא֥וֹ] [לִ֭רְעוֹת] [בְּיַעֲקֹ֣ב] povo-seu [וּ֝בְיִשְׂרָאֵ֗ל] herança-dele');
INSERT INTO verses VALUES (15243, 19, 78, 72, '[וַ֭יִּרְעֵם] [כְּתֹ֣ם] [לְבָב֑וֹ] [וּבִתְבוּנ֖וֹת] [כַּפָּ֣יו] [יַנְחֵֽם]');
INSERT INTO chapters VALUES (557, 19, 79, 13);
INSERT INTO verses VALUES (15244, 19, 79, 1, 'salmo לְאָ-סָ֥ף אֱ-לֹהִ֡ים vieram [גוֹיִ֨ם] [׀] [בְּֽנַחֲלָתֶ֗ךָ] a o-santuário sua santidade שָׂ֖moּ a [לְעִיִּֽים] [sem-traducao]');
INSERT INTO verses VALUES (15245, 19, 79, 2, '[נָֽתְנ֡וּ] a [עֲבָדֶ֗יךָ] alimento [לְע֣וֹף] [הַשָּׁמָ֑יִם] os-céus de-a-carne [לְחַיְתוֹ־אָֽרֶץ] [sem-traducao] terra');
INSERT INTO verses VALUES (15246, 19, 79, 3, '[שָׁפְכ֬וּ] [דָמָ֨ם] [׀] [כַּמַּ֗יִם] [סְֽבִ֘יב֤וֹת] e-não-há [וְאֵ֣ין]');
INSERT INTO verses VALUES (15247, 19, 79, 4, 'fomos cherpeha lishechenenu לַעַג וָקֶ֗לֶס לִסְבִיבוֹתֵֽינוּ׃');
INSERT INTO verses VALUES (15248, 19, 79, 5, 'até yhwh yhwh [לָנֶ֑צַח] [תִּ֭[t]בְעַ֥ר] como [קִנְאָתֶֽךָ]');
INSERT INTO verses VALUES (15249, 19, 79, 6, '[שְׁפֹ֤ךְ] tua-ira a [אֲשֶׁ֢ר] que não [מַמְלָכ֑וֹת] e-sobre מלכות não Beshemakh não קָרָֽאוּ׃');
INSERT INTO verses VALUES (15250, 19, 79, 7, 'que comer a Jacó e-[OBJ]');
INSERT INTO verses VALUES (15251, 19, 79, 8, 'a [עֲוֺנֹ֢ת] para-nós [מַ֭הֵר] [יְקַדְּמ֣וּנוּ] [רַחֲמֶ֑יךָ] que [דַלּ֣וֹנוּ] muito [sem-traducao] muito');
INSERT INTO verses VALUES (15252, 19, 79, 9, '[עָזְרֵ֤נוּ] Elohim-de [Elohim] sobre palavra [כְּבֽוֹד־שְׁמֶ֑ךָ] o-teu-nome [וְכַפֵּ֥ר] e-perdoa sobre [שְׁמֶֽךָ] para-que שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (15253, 19, 79, 10, 'por-que dirão [יֹאמְר֣וּ] [הַגּוֹיִם֮] [אַיֵּ֢ה] ser-conhecido [יִוָּדַ֣ע] [*בגיים] DAM- [לְעֵינֵ֑ינוּ] [נִ֝קְמַ֗ת]');
INSERT INTO verses VALUES (15254, 19, 79, 11, '[תָּ֤ב֣וֹא] [לְפָנֶיךָ֮] [אֶנְקַ֢ת] [אָ֫סִ֥יר] [כְּגֹ֥דֶל] [זְרוֹעֲךָ֑] [ה֝וֹתֵ֗ר] filhos-de [תְמוּתָֽה]');
INSERT INTO verses VALUES (15255, 19, 79, 12, '[וְהָ֘שֵׁ֤ב] [לִשְׁכֵנֵ֣ינוּ] [שִׁ֭בְעָתַיִם] a [חֶרְפָּ֘תָ֤ם] [אֲשֶׁ֖ר] que [אֲדֹֽ[c]נָי]');
INSERT INTO verses VALUES (15256, 19, 79, 13, '[וַאֲנַ֤חְנוּ] [עַמְּךָ֨] [׀] [וְצֹ֥אן] [מַרְעִיתֶךָ֮] [נ֤וֹדֶ֥ה] para-sempre para-geração וָ dor [וָדֹ֑ר] será teu louvor:');
INSERT INTO chapters VALUES (558, 19, 80, 20);
INSERT INTO verses VALUES (15257, 19, 80, 1, 'ao-regente a [עֵד֖וּת] [לְאָסָ֣ף] le-asaf salmo');
INSERT INTO verses VALUES (15258, 19, 80, 2, '[רֹ֘עֵ֤ה] [יִשְׂרָאֵ֨ל] [׀] [הַאֲזִ֗ינָה] [נֹהֵ֣ג] José habitou os-querubins [הַכְּרוּבִ֣ים]');
INSERT INTO verses VALUES (15259, 19, 80, 3, 'diante-de [אֶפְרַ֨יִם] [׀] [וּבִנְיָ֘מִ֤ן] [וּמְנַשֶּׁ֗ה] a [אֶת־גְּבֽוּרָתֶ֑ךָ] וּלְכוּ [לִישֻׁעָ֣תָה] para nós');
INSERT INTO verses VALUES (15260, 19, 80, 4, 'Elohim [הֲשִׁיבֵ֑נוּ] [וְהָאֵ֥ר] [פָּ֝נֶ֗יךָ] [וְנִוָּשֵֽׁעָה]');
INSERT INTO verses VALUES (15261, 19, 80, 5, 'yhwh Elohim exércitos até quando [בִּתְפִלַּ֥ת] [עַמֶּֽךָ] povo-tua');
INSERT INTO verses VALUES (15262, 19, 80, 6, '[הֶ֭אֱכַלְתָּם] pão [דִּמְעָ֑ה] [וַ֝תַּשְׁקֵ֗מוֹ] [בִּדְמָע֥וֹת] [שָׁלִֽישׁ]');
INSERT INTO verses VALUES (15263, 19, 80, 7, 'tashimenu [מָ֭דוֹן] lishechenenu [וְ֝אֹיְבֵ֗ינוּ] [יִלְעֲגוּ־לָֽמוֹ] a-eles');
INSERT INTO verses VALUES (15264, 19, 80, 8, 'Elohim [צְבָא֣וֹת] [הֲשִׁיבֵ֑נוּ] [וְהָאֵ֥ר] [פָּ֝נֶ֗יךָ] [וְנִוָּשֵֽׁעָה]');
INSERT INTO verses VALUES (15265, 19, 80, 9, '[גֶּ֭פֶן] [מִמִּצְרַ֣יִם] [תַּסִּ֑יעַ] [תְּגָרֵ֥שׁ] nações [וַתִּטָּעֶֽהָ]');
INSERT INTO verses VALUES (15266, 19, 80, 10, '[פִּנִּ֥יתָ] diante dela [וַתַּשְׁרֵ֥שׁ] [שָׁ֝רָשֶׁ֗יהָ] [וַתְּמַלֵּא־אָֽרֶץ] terra');
INSERT INTO verses VALUES (15267, 19, 80, 11, 'cobrir-se-ão os-montes [צִלָּ֑הּ] [וַ֝עֲנָפֶ֗יהָ] [אַֽרְזֵי־אֵֽל] El');
INSERT INTO verses VALUES (15268, 19, 80, 12, '[תְּשַׁלַּ֣ח] [קְצִירֶ֣הָ] até [וְאֶל־נָ֝הָ֗ר] e-a');
INSERT INTO verses VALUES (15269, 19, 80, 13, '[לָ֭מָּה] [פָּרַ֣צְתָּ] [גְדֵרֶ֑יהָ] [וְ֝אָר֗וּהָ] todo [דָֽרֶךְ] caminho');
INSERT INTO verses VALUES (15270, 19, 80, 14, '[יְכַרְסְמֶ֣נָּֽה] [חֲזִ֣יר] [מִיָּ֑עַ[7]ר] Shaddai [שָׂדַ֣י]');
INSERT INTO verses VALUES (15271, 19, 80, 15, 'Elohim [צְבָאוֹת֮] [שֽׁ֫וּב־נָ֥א] agora הבט [וּרְאֵ֑ה] e-vê-se [גֶּ֣פֶן] esta esta-ali');
INSERT INTO verses VALUES (15272, 19, 80, 16, '[וְ֭כַנָּה] que [יְמִינֶ֑ךָ] [וְעַל־בֵּ֝֗ן] e-sobre filho');
INSERT INTO verses VALUES (15273, 19, 80, 17, '[שְׂרֻפָ֣ה] [בָאֵ֣שׁ] [כְּסוּחָ֑ה] [מִגַּעֲרַ֖ת] faces-tuas [יֹאבֵֽדוּ]');
INSERT INTO verses VALUES (15274, 19, 80, 18, '[תְּֽהִי־יָ֭דְךָ] sua-mão sobre homem [אִמַּ֥צְתָּ] sobre filho-de homem [sem-traducao] para-ti');
INSERT INTO verses VALUES (15275, 19, 80, 19, 'e-não [מִמֶּ֑ךָּ] de ti [וּבְשִׁמְךָ֥] [נִקְרָֽא] [sem-traducao]');
INSERT INTO verses VALUES (15276, 19, 80, 20, 'yhwh Elohim [צְבָא֣וֹת] [הֲשִׁיבֵ֑נוּ] [הָאֵ֥ר] [פָּ֝נֶ֗יךָ] [וְנִוָּשֵֽׁעָה]');
INSERT INTO chapters VALUES (559, 19, 81, 17);
INSERT INTO verses VALUES (15277, 19, 81, 1, 'para o vencedor sobre [עַֽל־הַגִּתִּ֬ית] [לְאָסָֽף]');
INSERT INTO verses VALUES (15278, 19, 81, 2, '[הַ֭רְנִינוּ] para-Elohim [עוּזֵּ֑נוּ] [הָ֝רִ֗יעוּ] [לֵאלֹהֵ֥י] Jacó');
INSERT INTO verses VALUES (15279, 19, 81, 3, '[שְֽׂאוּ־זִ֭מְרָה] [וּתְנוּ־תֹ֑ף] [כִּנּ֖וֹר] [נָעִ֣ים] lira com');
INSERT INTO verses VALUES (15280, 19, 81, 4, '[תִּקְע֣וּ] [בַחֹ֣דֶשׁ] [שׁוֹפָ֑ר] [בַּ֝כֵּ֗סֶה] para-o-dia [חַגֵּֽנוּ]');
INSERT INTO verses VALUES (15281, 19, 81, 5, 'que [חֹ֣ק] [לְיִשְׂרָאֵ֣ל] ele [מִ֝שְׁפָּ֗ט] [לֵאלֹהֵ֥י] Jacó');
INSERT INTO verses VALUES (15282, 19, 81, 6, '[עֵד֤וּת] [׀] [בִּֽיה֘וֹסֵ֤ף] [שָׂמ֗וֹ] sobre terra Egito [שְׂפַ֖ת] não eu-sei');
INSERT INTO verses VALUES (15283, 19, 81, 7, '[הֲסִיר֣וֹתִי] [מִסֵּ֣בֶל] [שִׁכְמ֑וֹ] [כַּ֝פָּ֗יו] [מִדּ֥וּד] [תַּעֲבֹֽרְנָה]');
INSERT INTO verses VALUES (15284, 19, 81, 8, '[בַּצָּרָ֥ה] [קָרָ֗אתָ] [וָאֲחַ֫לְּצֶ֥ךָּ] [אֶ֭עֶנְךָ] [בְּסֵ֣תֶר] [רַ֑עַם] [אֶבְחָֽנְךָ֨] sobre [מְרִיבָ֣ה] [סֶֽלָה]');
INSERT INTO verses VALUES (15285, 19, 81, 9, 'ouviu [עַ֭מִּי] [וְאָעִ֣ידָה] sobre-ti Israel se');
INSERT INTO verses VALUES (15286, 19, 81, 10, 'não será El זָ֑ר e-não [לְאֵ֣ל] a-El estranho:');
INSERT INTO verses VALUES (15287, 19, 81, 11, 'eu yhwh yhwh [Elohim] da-terra Egito [מִצְרָ֑יִם] [הַרְחֶב־פִּ֝֗יךָ] [וַאֲמַּלְאֵֽהוּ]');
INSERT INTO verses VALUES (15288, 19, 81, 12, 'e-não ouviu meu-povo [וְ֝יִשְׂרָאֵ֗ל] [לֹא־אָ֥בָה] não');
INSERT INTO verses VALUES (15289, 19, 81, 13, '[וָֽ֭אֲשַׁלְּחֵהוּ] [בִּשְׁרִיר֣וּת] coracoes-eles [יֵ֝לְכ֗וּ] [בְּֽמוֹעֲצוֹתֵיהֶֽם]');
INSERT INTO verses VALUES (15290, 19, 81, 14, '[ל֗וּ] [עַ֭מִּי] ouviu a-mim Israel [בִּדְרָכַ֥י] [יְהַלֵּֽכוּ]');
INSERT INTO verses VALUES (15291, 19, 81, 15, 'como-pequeno [אוֹיְבֵיהֶ֣ם] [אַכְנִ֑יעַ] e-sobre [צָ֝רֵיהֶ֗ם] [אָשִׁ֥יב] minha-mão:');
INSERT INTO verses VALUES (15292, 19, 81, 16, '[מְשַׂנְאֵ֣י] yhwh [יְכַֽחֲשׁוּ־ל֑וֹ] e-seja E-foi [לְעוֹלָֽם]');
INSERT INTO verses VALUES (15293, 19, 81, 17, '[וֽ͏ַ֭יַּאֲכִילֵהוּ] de-a-graxa [חִטָּ֑ה] [וּ֝מִצּ֗וּר] דְּבַ֣שׁ [אַשְׂבִּיעֶֽךָ]');
INSERT INTO chapters VALUES (560, 19, 82, 8);
INSERT INTO verses VALUES (15294, 19, 82, 1, 'salmo לְאָ-סָ֥ף Elohim stood בַּעֲדַת־ El vida Elohim [sem-traducao]');
INSERT INTO verses VALUES (15295, 19, 82, 2, 'até quando [וּפְנֵ֥י] [רְ֝שָׁעִ֗ים] e-faces-de ímpios [sem-traducao] Selá');
INSERT INTO verses VALUES (15296, 19, 82, 3, '[שִׁפְטוּ־דַ֥ל] [וְיָת֑וֹם] [עָנִ֖י] עני e o restante [sem-traducao]');
INSERT INTO verses VALUES (15297, 19, 82, 4, '[פַּלְּטוּ־דַ֥ל] [וְאֶבְי֑וֹן] [מִיַּ֖ד] de-mão-de ímpios');
INSERT INTO verses VALUES (15298, 19, 82, 5, 'não [יָֽדְע֨וּ] e-não [וְלֹ֥א] [יָבִ֗ינוּ] [בַּחֲשֵׁכָ֥ה] [יִתְהַלָּ֑כוּ] todo [כָּל־מ֥וֹסְדֵי] terra');
INSERT INTO verses VALUES (15299, 19, 82, 6, '[אֲ‍ֽנִי־אָ֭מַרְתִּי] eu-disse Elohim vós e-filhos-de [כֻּלְּכֶֽם]');
INSERT INTO verses VALUES (15300, 19, 82, 7, 'certamente [כְּאָדָ֣ם] [תְּמוּת֑וּן] [וּכְאַחַ֖ד] [הַשָּׂרִ֣ים] [תִּפֹּֽלוּ]');
INSERT INTO verses VALUES (15301, 19, 82, 8, 'qumah Elohim [שָׁפְטָ֣ה] a-terra porque tu [בְּכָל־הַגּוֹיִֽם] em-todo os-gentios');
INSERT INTO chapters VALUES (561, 19, 83, 19);
INSERT INTO verses VALUES (15302, 19, 83, 1, '[שִׁ֖יר] [מִזְמ֣וֹר] [לְאָסָֽף]');
INSERT INTO verses VALUES (15303, 19, 83, 2, 'Elohim a [אַל־תֶּחֱרַ֖שׁ] a-ti a e-a El');
INSERT INTO verses VALUES (15304, 19, 83, 3, 'porque eis [יֶהֱמָי֑וּן] יֶהֱמָי֑וּן [נָ֣שְׂאוּ] levaram cabeça');
INSERT INTO verses VALUES (15305, 19, 83, 4, 'sobre [יַעֲרִ֣ימוּ] [ס֑וֹד] segredo [עַל־צְפוּנֶֽיךָ] sobre [sem-traducao]');
INSERT INTO verses VALUES (15306, 19, 83, 5, '[אָמְר֗וּ] [לְ֭כוּ] [וְנַכְחִידֵ֣ם] [מִגּ֑וֹי] e-não [שֵֽׁם־יִשְׂרָאֵ֣ל] nome-de Israel');
INSERT INTO verses VALUES (15307, 19, 83, 6, 'que [נוֹעֲצ֣וּ] coração juntos [עָ֝לֶ֗יךָ] aliança [יִכְרֹֽתוּ]');
INSERT INTO verses VALUES (15308, 19, 83, 7, 'ahol-ei אדום [וְיִשְׁמְעֵאלִ֗ים] Moabe [וְהַגְרֽ͏ִים]');
INSERT INTO verses VALUES (15309, 19, 83, 8, '[גְּבָ֣ל] [וְ֭עַמּוֹן] e-Amaleque [פְּ֝לֶ֗שֶׁת] com [צֽוֹר]');
INSERT INTO verses VALUES (15310, 19, 83, 9, 'também [נִלְוָ֣ה] [עִמָּ֑ם] [הָ֤י֥וּ] [זְר֖וֹעַ] [לִבְנֵי־ל֣וֹט] para-filhos-de');
INSERT INTO verses VALUES (15311, 19, 83, 10, '[עֲשֵֽׂה־לָהֶ֥ם] a-eles [כְּֽסִֽיסְרָ֥א] [כְ֝יָבִ֗ין] [בְּנַ֣חַל] בְּנַחַל Kishon-:');
INSERT INTO verses VALUES (15312, 19, 83, 11, '[נִשְׁמְד֥וּ] [בְֽעֵין־דֹּ֑אר] [הָ֥יוּ] havú [לָאֲדָמָֽה] [sem-traducao]');
INSERT INTO verses VALUES (15313, 19, 83, 12, '[שִׁיתֵ֣מוֹ] [נְ֭דִיבֵמוֹ] [כְּעֹרֵ֣ב] [וְכִזְאֵ֑ב] [וּֽכְזֶ֥בַח] [וּ֝כְצַלְמֻנָּ֗ע] todo');
INSERT INTO verses VALUES (15314, 19, 83, 13, 'que אָ֭מְרוּ [נִ֣ירֲשָׁה] nós [OBJ] pastagens Elohim');
INSERT INTO verses VALUES (15315, 19, 83, 14, 'meu-Eloah [שִׁיתֵ֥מוֹ] [כַגַּלְגַּ֑ל] [כְּ֝קַ֗שׁ] diante-de espírito');
INSERT INTO verses VALUES (15316, 19, 83, 15, '[כְּאֵ֥שׁ] [תִּבְעַר־יָ֑עַר] [וּ֝כְלֶהָבָ֗ה] [תְּלַהֵ֥ט] [הָרִֽים]');
INSERT INTO verses VALUES (15317, 19, 83, 16, '[כֵּ֭ן] [תִּרְדְּפֵ֣ם] [בְּסַעֲרֶ֑ךָ] [וּבְסוּפָתְךָ֥] [תְבַהֲלֵֽם]');
INSERT INTO verses VALUES (15318, 19, 83, 17, 'enchei [פְנֵיהֶ֣ם] [קָל֑וֹן] [וִֽיבַקְשׁ֖וּ] teu-nome yhwh');
INSERT INTO verses VALUES (15319, 19, 83, 18, '[יֵבֹ֖שׁוּ] [וְיִבָּהֲל֥וּ] ate até [וְיֹאבֵֽדוּ] [sem-traducao]');
INSERT INTO verses VALUES (15320, 19, 83, 19, 'e-conhecerão porque [שִׁמְךָ֣] yhwh yhwh [עֶ֝לְי֗וֹן] Altissimo sobre todo a-terra');
INSERT INTO chapters VALUES (562, 19, 84, 13);
INSERT INTO verses VALUES (15321, 19, 84, 1, 'ao-regente sobre [לִבְנֵי־קֹ֥רַח] para-filhos-de');
INSERT INTO verses VALUES (15322, 19, 84, 2, 'que [מִשְׁכְּנוֹתֶ֗יךָ] yhwh yhwh');
INSERT INTO verses VALUES (15323, 19, 84, 3, '[נִכְסְפָ֬ה] e-também [׀] [נַפְשִׁי֮] [לְחַצְר֢וֹת] [יְ[t]ה֫וָ֥ה] [לִבִּ֥י] [וּבְשָׂרִ֑י] El a viveu');
INSERT INTO verses VALUES (15324, 19, 84, 4, 'também [׀] [מָ֪צְאָה] casa [וּדְר֤וֹר] [׀] [קֵ֥ן] que [אֲשֶׁר־שָׁ֢תָה] [אֶפְרֹ֫חֶ֥יהָ] a yhwh yhwh exércitos [וֵאלֹהָֽי]');
INSERT INTO verses VALUES (15325, 19, 84, 5, 'feliz habitantes-de [בֵיתֶ֑ךָ] עוֹד [יְֽהַלְל֥וּךָ] selá');
INSERT INTO verses VALUES (15326, 19, 84, 6, 'אַשְׁרֵי homem [עֽוֹז־ל֥וֹ] a-ele em-ti [בִּלְבָבָֽם] bilbamo');
INSERT INTO verses VALUES (15327, 19, 84, 7, '[עֹבְרֵ֤י] בְּעֵ֣מֶק [בְּעֵ֣מֶק] מַעְיָ֣ן [מַעְיָ֣ן] também [גַּם־בְּ֝רָכ֗וֹת] [יַעְטֶ֥ה] mestre-:');
INSERT INTO verses VALUES (15328, 19, 84, 8, '[יֵ֭לְכוּ] [מֵחַ֣יִל] a força [אֶל־אֱלֹהִ֣ים] a Elohim');
INSERT INTO verses VALUES (15329, 19, 84, 9, 'yhwh Elohim exércitos ouça [תְפִלָּתִ֑י] [הַאֲזִ֨ינָה] Elohim-de Jacó Selá');
INSERT INTO verses VALUES (15330, 19, 84, 10, '[מָ֭גִנֵּנוּ] viu Elohim [וְ֝הַבֵּ֗ט] face-de [מְשִׁיחֶֽךָ]');
INSERT INTO verses VALUES (15331, 19, 84, 11, 'que bom dia [מֵ֫אָ֥לֶף] [בָּחַ֗רְתִּי] [הִ֭סְתּוֹפֵף] [בְּבֵ֣ית] na-casa-de [מִ֝דּ֗וּר] [בְּאָהֳלֵי־רֶֽשַׁע]');
INSERT INTO verses VALUES (15332, 19, 84, 12, 'que [שֶׁ֨מֶשׁ] [׀] yhwh yhwh chen [חֵ֣ן] dará yhwh yhwh não bom [לַֽהֹלְכִ֥ים] [בְּתָמִֽים]');
INSERT INTO verses VALUES (15333, 19, 84, 13, 'yhwh exércitos felizesse homem [בֹּטֵ֥חַ] sobre-ti');
INSERT INTO chapters VALUES (563, 19, 85, 14);
INSERT INTO verses VALUES (15334, 19, 85, 1, 'para o vencedor para-filhos-de קֹ֬רַח salmo');
INSERT INTO verses VALUES (15335, 19, 85, 2, '[רָצִ֣יתָ] yhwh a tua terra [שַׁ֝֗בְתָּ] Jacó');
INSERT INTO verses VALUES (15336, 19, 85, 3, '[נָ֭שָׂאתָ] iniquidade povo-teu [כִּסִּ֖יתָ] todo [סֶֽלָה] Selá');
INSERT INTO verses VALUES (15337, 19, 85, 4, '[אָסַ֥פְתָּ] todo [הֱ֝שִׁיב֗וֹתָ] [מֵחֲר֥וֹן] [אַפֶּֽךָ]');
INSERT INTO verses VALUES (15338, 19, 85, 5, '[שׁ֭וּבֵנוּ] Elohim-de nosso-salvação [וְהָפֵ֖ר] [כַּֽעַסְךָ֣] com-nosso:');
INSERT INTO verses VALUES (15339, 19, 85, 6, '[הַלְעוֹלָ֥ם] [תֶּֽאֱנַף־בָּ֑נוּ] BANU [אַ֝פְּךָ֗] ira-teu para-a-geração וָדֹר׃');
INSERT INTO verses VALUES (15340, 19, 85, 7, '[הֽ͏ֲלֹא־אַ֭תָּה] [תָּשׁ֣וּב] [תְּחַיֵּ֑נוּ] [וְ֝עַמְּךָ֗] [יִשְׂמְחוּ־בָֽךְ]');
INSERT INTO verses VALUES (15341, 19, 85, 8, '[הַרְאֵ֣נוּ] yhwh chasdekha [וְ֝יֶשְׁעֲךָ֗] tu-darás para-nós');
INSERT INTO verses VALUES (15342, 19, 85, 9, '[אֶשְׁמְעָ֗ה] que [הָאֵ֢ל] [׀] yhwh que [׀] shalom a seu-povo e-a chasidyav e-a retornarão [sem-traducao]');
INSERT INTO verses VALUES (15343, 19, 85, 10, 'ach קָר֣וֹב [קָר֣וֹב] [לִירֵאָ֣יו] [יִשְׁע֑וֹ] Kavod [כָּב֣וֹד]');
INSERT INTO verses VALUES (15344, 19, 85, 11, '[חֶֽסֶד־וֶאֱמֶ֥ת] [נִפְגָּ֑שׁוּ] [צֶ֖דֶק] justiça [נָשָֽׁקוּ] [sem-traducao]');
INSERT INTO verses VALUES (15345, 19, 85, 12, 'verdade da-terra [תִּצְמָ֑ח] [וְ֝צֶ֗דֶק] [מִשָּׁמַ֥יִם] [נִשְׁקָֽף]');
INSERT INTO verses VALUES (15346, 19, 85, 13, 'também yhwh dará [וְ֝אַרְצֵ֗נוּ] [תִּתֵּ֥ן] dareis [sem-traducao]');
INSERT INTO verses VALUES (15347, 19, 85, 14, '[צֶ֭דֶק] diante-dele [יְהַלֵּ֑ךְ] [וְיָשֵׂ֖ם] [לְדֶ֣רֶךְ] [פְּעָמָֽיו]');
INSERT INTO chapters VALUES (564, 19, 86, 17);
INSERT INTO verses VALUES (15348, 19, 86, 1, '[תְּפִלָּ֗ה] para-Davi inclinar- yhwh ouvido-teu [כִּֽי־עָנִ֖י] porque עני eu eu');
INSERT INTO verses VALUES (15349, 19, 86, 2, '[שָֽׁמְרָ֣ה] [נַפְשִׁי֮] porque [אָ֥נִי] [הוֹשַׁ֣ע] [עַ֭בְדְּךָ] tu tu [הַבּוֹטֵ֥חַ] [אֵלֶֽיךָ]');
INSERT INTO verses VALUES (15350, 19, 86, 3, 'חָנֵּ֥נִי Adonai que a-ti [אֶ֝קְרָ֗א] todo o-dia');
INSERT INTO verses VALUES (15351, 19, 86, 4, '[שַׂ֭מֵּחַ] alma servo-teu que a-ti Adonai נַפְשִׁ֥י eššāʾ:');
INSERT INTO verses VALUES (15352, 19, 86, 5, 'porque tu bom bom [וְרַב־חֶ֝֗סֶד] [לְכָל־קֹרְאֶֽיךָ] para-todo');
INSERT INTO verses VALUES (15353, 19, 86, 6, '[הַאֲזִ֣ינָה] yhwh [תְּפִלָּתִ֑י] [וְ֝הַקְשִׁ֗יבָה] com-voz [תַּחֲנוּנוֹתָֽי]');
INSERT INTO verses VALUES (15354, 19, 86, 7, 'no-dia [צָ֭רָתִ֥י] [אֶקְרָאֶ֗ךָּ] que [תַעֲנֵֽנִי]');
INSERT INTO verses VALUES (15355, 19, 86, 8, 'não-há como-te [׀] Adonai e-não-há [כְּֽמַעֲשֶֽׂיךָ]');
INSERT INTO verses VALUES (15356, 19, 86, 9, 'todo [׀] que fizeste [יָב֤וֹאוּ] [׀] diante de ti Adonai [Adonai] [וִֽיכַבְּד֣וּ]');
INSERT INTO verses VALUES (15357, 19, 86, 10, 'porque tu [וְעֹשֵׂ֣ה] [נִפְלָא֑וֹת] tu tu Elohim');
INSERT INTO verses VALUES (15358, 19, 86, 11, '[ה֘וֹרֵ֤נִי] yhwh [׀] [דַּרְכֶּ֗ךָ] [אֲהַלֵּ֥ךְ] [בַּאֲמִתֶּ֑ךָ] ללבבי para-o-timo שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (15359, 19, 86, 12, '[אוֹדְךָ֤] Adonai [Adonai] em-todo [בְּכָל־לְבָבִ֑י] [וַאֲכַבְּדָ֖ה] teu-nome para-sempre');
INSERT INTO verses VALUES (15360, 19, 86, 13, 'porque Sussana-te grande sobre mim [נַ֝פְשִׁ֗י] minha-alma de-tartarus [sem-traducao]');
INSERT INTO verses VALUES (15361, 19, 86, 14, 'Elohim [׀] קָֽמוּ־ עָלַ֗י [וַעֲדַ֣ת] [עָ֭רִיצִים] buscou-se minha-alma e-não [שָׂמ֣וּךָ] [לְנֶגְדָּֽם]');
INSERT INTO verses VALUES (15362, 19, 86, 15, 'e-tu Adonai a [וְחַנּ֑וּן] e-gracioso longo אף-יימ e-grande bondade e-verdade');
INSERT INTO verses VALUES (15363, 19, 86, 16, '[פְּנֵ֥ה] a-mim [וְחָ֫נֵּ֥נִי] [תְּנָֽה־עֻזְּךָ֥] [לְעַבְדֶּ֑ךָ] [וְ֝הוֹשִׁ֗יעָה] [לְבֶן־אֲמָתֶֽךָ]');
INSERT INTO verses VALUES (15364, 19, 86, 17, '[עֲשֵֽׂה־עִמִּ֥י] [א֗וֹת] [לְט֫וֹבָ֥ה] [וְיִרְא֣וּ] [שֹׂנְאַ֣י] sônê''ây [כִּֽי־אַתָּ֥ה] yhwh tu yhwh [sem-traducao] [sem-traducao]');
INSERT INTO chapters VALUES (565, 19, 87, 7);
INSERT INTO verses VALUES (15365, 19, 87, 1, 'para-filhos-de [מִזְמ֣וֹר] [שִׁ֑יר] [יְ֝סוּדָת֗וֹ] [בְּהַרְרֵי־קֹֽדֶשׁ]');
INSERT INTO verses VALUES (15366, 19, 87, 2, 'amou yhwh [שַׁעֲרֵ֣י] Sião de-toda [מִשְׁכְּנ֥וֹת] Jacó');
INSERT INTO verses VALUES (15367, 19, 87, 3, '[נִ֭כְבָּדוֹת] [מְדֻבָּ֣ר] sobre-ti cidade [הָאֱלֹהִ֣ים] Selá');
INSERT INTO verses VALUES (15368, 19, 87, 4, '[אַזְכִּ֤יר] [׀] [רַ֥הַב] [וּבָבֶ֗ל] eis eis [פְלֶ֣שֶׁת] com [עִם־כּ֑וּשׁ] [זֶ֝֗ה] nasceu nome');
INSERT INTO verses VALUES (15369, 19, 87, 5, '[וּֽלֲצִיּ֨וֹן] [׀] homem [אִ֣ישׁ] nasceu nela e-ele [יְכוֹנְנֶ֣הָ] [עֶלְיֽוֹן]');
INSERT INTO verses VALUES (15370, 19, 87, 6, 'yhwh [יִ֭סְפֹּר] [בִּכְת֣וֹב] [עַמִּ֑ים] este nasceu nome');
INSERT INTO verses VALUES (15371, 19, 87, 7, '[וְשָׁרִ֥ים] [כְּחֹלְלִ֑ים] todo sobre-ti');
INSERT INTO chapters VALUES (566, 19, 88, 19);
INSERT INTO verses VALUES (15372, 19, 88, 1, 'cântico salmo [לִבְנֵ֫י] [קֹ֥רַח] [לַמְנַצֵּ֣חַ] sobre [לְעַנּ֑וֹת] [מַ֝שְׂכִּ֗יל] [לְהֵימָ֥ן] [הָאֶזְרָחִֽי] [sem-traducao]');
INSERT INTO verses VALUES (15373, 19, 88, 2, 'yhwh Elohim-de [יְשׁוּעָתִ֑י] dia-de [בַלַּ֣יְלָה] [נֶגְדֶּֽךָ] [sem-traducao]');
INSERT INTO verses VALUES (15374, 19, 88, 3, '[תָּב֣וֹא] [לְ֭פָנֶיךָ] [תְּפִלָּתִ֑י] [הַטֵּֽה־אָ֝זְנְךָ֗] [לְרִנָּתִֽי]');
INSERT INTO verses VALUES (15375, 19, 88, 4, 'porque [בְרָע֣וֹת] [נַפְשִׁ֑י] minha-alma [לִשְׁא֥וֹל] [הִגִּֽיעוּ]');
INSERT INTO verses VALUES (15376, 19, 88, 5, '[נֶ֭חְשַׁבְתִּי] com [ב֑וֹר] [הָ֝יִ֗יתִי] [כְּגֶ֣בֶר] [אֵֽין־אֱיָֽל]');
INSERT INTO verses VALUES (15377, 19, 88, 6, '[בַּמֵּתִ֗ים] [חָ֫פְשִׁ֥י] [כְּמ֤וֹ] [חֲלָלִ֨ים] [׀] [שֹׁ֥כְבֵי] que não não ainda [ע֑וֹד] [וְ֝הֵ֗מָּה] [מִיָּדְךָ֥]');
INSERT INTO verses VALUES (15378, 19, 88, 7, '[שַׁ֭תַּנִי] [בְּב֣וֹר] [תַּחְתִּיּ֑וֹת] [בְּ֝מַחֲשַׁכִּ֗ים] [בִּמְצֹלֽוֹת]');
INSERT INTO verses VALUES (15379, 19, 88, 8, '[עָ֭לַי] [סָמְכָ֣ה] [חֲמָתֶ֑ךָ] e-todo [עִנִּ֥יתָ] [סֶּֽלָה]');
INSERT INTO verses VALUES (15380, 19, 88, 9, '[הִרְחַ֥קְתָּ] [מְיֻדָּעַ֗י] [מִ֫מֶּ֥נִּי] [שַׁתַּ֣נִי] [תוֹעֵב֣וֹת] a-eles [כָּ֝לֻ֗א] e-não [אֵצֵֽא]');
INSERT INTO verses VALUES (15381, 19, 88, 10, '[עֵינִ֥י] [דָאֲבָ֗ה] [מִנִּ֫י] [עֹ֥נִי] [קְרָאתִ֣יךָ] yhwh em-todo dia [אֵלֶ֣יךָ] a-ti');
INSERT INTO verses VALUES (15382, 19, 88, 11, '[הֲלַמֵּתִ֥ים] farás- [אִם־רְ֝פָאִ֗ים] se [׀] [יוֹד֬וּךָ] [סֶּֽלָה]');
INSERT INTO verses VALUES (15383, 19, 88, 12, '[הַיְסֻפַּ֣ר] [בַּקֶּ֣בֶר] [חַסְדֶּ֑ךָ] [אֱ֝מֽוּנָתְךָ֗] [בָּאֲבַדּֽוֹן]');
INSERT INTO verses VALUES (15384, 19, 88, 13, '[הֲיִוָּדַ֣ע] na-escuridão [פִּלְאֶ֑ךָ] na-terra [בְּאֶ֣רֶץ]');
INSERT INTO verses VALUES (15385, 19, 88, 14, 'e-eu a-ti yhwh yhwh [שִׁוַּ֑עְתִּי] [וּ֝בַבֹּ֗קֶר] [תְּֽפִלָּתִ֥י]');
INSERT INTO verses VALUES (15386, 19, 88, 15, '[לָמָ֣ה] yhwh [תִּזְנַ֣ח] minha-alma [תַּסְתִּ֖יר] faces-tuas de-mim');
INSERT INTO verses VALUES (15387, 19, 88, 16, '[עָ֘נִ֤י] eu [וְגֹוֵ֣עַ] [מִנֹּ֑עַר] [נָשָׂ֖אתִי] [אֵמֶ֣יךָ] [אָפֽוּנָה]');
INSERT INTO verses VALUES (15388, 19, 88, 17, '[עָ֭לַי] [עָבְר֣וּ] [חֲרוֹנֶ֑יךָ] [בִּ֝עוּתֶ֗יךָ] [צִמְּתוּתֻֽנִי]');
INSERT INTO verses VALUES (15389, 19, 88, 18, '[סַבּ֣וּנִי] [כַ֭מַּיִם] todo o-dia [עָלַ֣י] sobre-mim');
INSERT INTO verses VALUES (15390, 19, 88, 19, '[הִרְחַ֣קְתָּ] [מִ֭מֶּנִּי] amou [וָרֵ֑עַ] [מְֽיֻדָּעַ֥י] [מַחְשָֽׁךְ]');
INSERT INTO chapters VALUES (567, 19, 89, 53);
INSERT INTO verses VALUES (15391, 19, 89, 1, '[מַ֝שְׂכִּ֗יל] [לְאֵיתָ֥ן] [הָֽאֶזְרָחִֽי]');
INSERT INTO verses VALUES (15392, 19, 89, 2, '[חַֽסְדֵ֣י] yhwh eternidade [אָשִׁ֑ירָה] [לְדֹ֥ר] [וָדֹ֓ר] [׀] [אוֹדִ֖יעַ] [אֱמוּנָתְךָ֣]');
INSERT INTO verses VALUES (15393, 19, 89, 3, 'porque eternidade [חֶ֣סֶד] bondade [שָׁמַ֓יִם] [׀] [תָּכִ֖ן] [אֱמוּנָתְךָ֣] [בָהֶֽם]');
INSERT INTO verses VALUES (15394, 19, 89, 4, '[כָּרַ֣תִּֽי] [בְ֭רִית] [לִבְחִירִ֑י] [נִ֝שְׁבַּ֗עְתִּי] [לְדָוִ֥ד] [עַבְדִּֽי]');
INSERT INTO verses VALUES (15395, 19, 89, 5, 'até [אָכִ֣ין] [זַרְעֶ֑ךָ] [וּבָנִ֨יתִי] [לְדֹר־וָד֖וֹר] [כִּסְאֲךָ֣] [סֶֽלָה]');
INSERT INTO verses VALUES (15396, 19, 89, 6, '[וְי֘וֹד֤וּ] céus [פִּלְאֲךָ֣] yhwh também [בִּקְהַ֥ל] [קְדֹשִֽׁים]');
INSERT INTO verses VALUES (15397, 19, 89, 7, 'que quem [בַ֭שַּׁחַק] [יַעֲרֹ֣ךְ] a-yhwh [יִדְמֶ֥ה] [לַ֝יהוָ֗ה] [בִּבְנֵ֥י] [אֵלִים]');
INSERT INTO verses VALUES (15398, 19, 89, 8, 'El [נַ֭עֲרָץ] [בְּסוֹד־קְדֹשִׁ֣ים] [רַבָּ֑ה] multiplicai [עַל־כָּל־סְבִיבָֽיו] sobre todo');
INSERT INTO verses VALUES (15399, 19, 89, 9, 'yhwh Elohim-de exércitos quem [מִֽי־כָֽמ֖וֹךָ] [חֲסִ֥ין] Yah [יָ֑הּ] [וֶ֝אֱמ֥וּנָתְךָ֗]');
INSERT INTO verses VALUES (15400, 19, 89, 10, 'tu [מ֖[d]וֹשֵׁל] [בְּגֵא֣וּת] o-mar [בְּשׂ֥וֹא] tu tu');
INSERT INTO verses VALUES (15401, 19, 89, 11, 'tu [דִכִּ֣אתָ] [כֶחָלָ֣ל] [רָ֑הַב] [בִּזְר֥וֹעַ] [עֻ֝זְּךָ֗] [פִּזַּ֥רְתָּ] [אוֹיְבֶֽיךָ]');
INSERT INTO verses VALUES (15402, 19, 89, 12, 'a-ti céus também para-ti terra [וּ֝מְלֹאָ֗הּ] tu tu');
INSERT INTO verses VALUES (15403, 19, 89, 13, '[צָפ֣וֹן] [וְ֭יָמִין] tu [בְרָאתָ֑ם] [תָּב֥וֹר] [וְ֝חֶרְמ֗וֹן] [בְּשִׁמְךָ֥] [יְרַנֵּֽנוּ]');
INSERT INTO verses VALUES (15404, 19, 89, 14, 'a-ti [זְ֭רוֹעַ] com [תָּעֹ֥ז] [יָ֝דְךָ֗] [תָּר֥וּם] [יְמִינֶֽךָ]');
INSERT INTO verses VALUES (15405, 19, 89, 15, 'justica [וּ֭מִשְׁפָּט] [מְכ֣וֹן] [כִּסְאֶ֑ךָ] bondade [וֶ֝אֱמֶ֗ת] [יְֽקַדְּמ֥וּ] faces-tuas');
INSERT INTO verses VALUES (15406, 19, 89, 16, '[אַשְׁרֵ֣י] [הָ֭עָם] [יוֹדְעֵ֣י] [תְרוּעָ֑ה] yhwh [בְּֽאוֹר־פָּנֶ֥יךָ] [יְהַלֵּכֽוּן]');
INSERT INTO verses VALUES (15407, 19, 89, 17, '[בְּ֭שִׁמְךָ] [יְגִיל֣וּן] todo o-dia [יָרֽוּמוּ]');
INSERT INTO verses VALUES (15408, 19, 89, 18, 'porque [עֻזָּ֣מוֹ] [אָ֑תָּה] tu [*תרים] [**תָּר֥וּם]');
INSERT INTO verses VALUES (15409, 19, 89, 19, 'que [לַֽ֭יהוָה] [מָֽגִנֵּ֑נוּ] [וְלִקְד֖וֹשׁ] Israel [מַלְכֵּֽנוּ]');
INSERT INTO verses VALUES (15410, 19, 89, 20, 'então [דִּבַּ֥רְתָּֽ־בְחָז֡וֹן] [לַֽחֲסִידֶ֗יךָ] E-disse e-disse auxiliar [עַל־גִּבּ֑וֹר] sobre [בָח֣וּר] [מֵעָֽם]');
INSERT INTO verses VALUES (15411, 19, 89, 21, '[מָ֭צָאתִי] Davi [עַבְדִּ֑י] [בְּשֶׁ֖מֶן] [קָדְשִׁ֣י] [מְשַׁחְתִּֽיו]');
INSERT INTO verses VALUES (15412, 19, 89, 22, 'que [יָ֭דִי] [תִּכּ֣וֹן] com-ele também [תְאַמְּצֶֽנּוּ]');
INSERT INTO verses VALUES (15413, 19, 89, 23, 'não [אוֹיֵ֣ב] [בּ֑וֹ] nele não [יְעַנֶּֽנּוּ] não');
INSERT INTO verses VALUES (15414, 19, 89, 24, '[וְכַתּוֹתִ֣י] [מִפָּנָ֣יו] [צָרָ֑יו] [וּמְשַׂנְאָ֥יו] [אֶגּֽוֹף]');
INSERT INTO verses VALUES (15415, 19, 89, 25, '[וֶֽאֶֽמוּנָתִ֣י] [וְחַסְדִּ֣י] com-ele [וּ֝בִשְׁמִ֗י] [תָּר֥וּם] [קַרְנֽוֹ]');
INSERT INTO verses VALUES (15416, 19, 89, 26, '[וְשַׂמְתִּ֣י] [בַיָּ֣ם] sua-mão [וּֽבַנְּהָר֥וֹת] direita-de-ele');
INSERT INTO verses VALUES (15417, 19, 89, 27, 'ele [יִ֭קְרָאֵנִי] [אָ֣בִי] tu [אֵ֝לִ֗י] [וְצ֣וּר] [יְשׁוּעָתִֽי]');
INSERT INTO verses VALUES (15418, 19, 89, 28, 'também eu primogênito-de [עֶ֝לְי֗וֹן] Altissimo [sem-traducao] terra');
INSERT INTO verses VALUES (15419, 19, 89, 29, '[לְ֭עוֹלָ֗[c]ם] a-ele [חַסְדִּ֑י] [וּ֝בְרִיתִ֗י] [נֶאֱמֶ֥נֶת] a-ele');
INSERT INTO verses VALUES (15420, 19, 89, 30, '[וְשַׂמְתִּ֣י] [לָעַ֣ד] sua-semente [וְ֝כִסְא֗וֹ] [כִּימֵ֥י] céus');
INSERT INTO verses VALUES (15421, 19, 89, 31, 'se [בָ֭נָיו] [תּוֹרָתִ֑י] [וּ֝בְמִשְׁפָּטַ֗י] não não');
INSERT INTO verses VALUES (15422, 19, 89, 32, 'se [יְחַלֵּ֑לוּ] [וּ֝מִצְוֺתַ֗י] não não');
INSERT INTO verses VALUES (15423, 19, 89, 33, '[וּפָקַדְתִּ֣י] [בְשֵׁ֣בֶט] [פִּשְׁעָ֑ם] [וּבִנְגָעִ֥ים] [עֲוֺנָֽם]');
INSERT INTO verses VALUES (15424, 19, 89, 34, '[וְ֭חַסְדִּי] não [מֵֽעִמּ֑וֹ] [וְלֹֽא־אֲ֝שַׁקֵּ֗ר] e-não');
INSERT INTO verses VALUES (15425, 19, 89, 35, 'não [בְּרִיתִ֑י] [וּמוֹצָ֥א] [שְׂ֝פָתַ֗י] não não');
INSERT INTO verses VALUES (15426, 19, 89, 36, 'uma [נִשְׁבַּ֣עְתִּי] [בְקָדְשִׁ֑י] se [אֲכַזֵּֽב]');
INSERT INTO verses VALUES (15427, 19, 89, 37, 'sua-semente para-sempre será [וְכִסְא֖וֹ] [כַשֶּׁ֣מֶשׁ] [נֶגְדִּֽי]');
INSERT INTO verses VALUES (15428, 19, 89, 38, '[כְּ֭יָרֵחַ] [יִכּ֣וֹן] eternidade [וְעֵ֥ד] [בַּ֝שַּׁ֗חַק] [נֶאֱמָ֥ן] Selá');
INSERT INTO verses VALUES (15429, 19, 89, 39, 'e-tu [זָ֭נַחְתָּ] [וַתִּמְאָ֑ס] [הִ֝תְעַבַּ֗רְתָּ] com');
INSERT INTO verses VALUES (15430, 19, 89, 40, '[נֵ֭אַרְתָּה] aliança servo-teu [חִלַּ֖לְתָּ] a-terra [נִזְרֽוֹ]');
INSERT INTO verses VALUES (15431, 19, 89, 41, '[פָּרַ֥צְתָּ] todo [שַׂ֖מְתָּ] [מִבְצָרָ֣יו] [מְחִתָּה]');
INSERT INTO verses VALUES (15432, 19, 89, 42, '[שַׁ֭סֻּהוּ] todo [דָ֑רֶךְ] ser foi [לִשְׁכֵֽנָיו]');
INSERT INTO verses VALUES (15433, 19, 89, 43, '[הֲ֭רִימוֹתָ] [יְמִ֣ין] [צָרָ֑יו] [הִ֝שְׂמַ֗חְתָּ] todo');
INSERT INTO verses VALUES (15434, 19, 89, 44, 'também [צ֣וּר] [חַרְבּ֑וֹ] [וְלֹ֥א] e-não [בַּמִּלְחָמָֽה]');
INSERT INTO verses VALUES (15435, 19, 89, 45, '[הִשְׁבַּ֥תָּ] [מִטְּהָר֑וֹ] [וְ֝כִסְא֗וֹ] [לָאָ֥רֶץ] [מִגַּֽרְתָּה]');
INSERT INTO verses VALUES (15436, 19, 89, 46, '[הִ֭קְצַרְתָּ] dias-de [עֲלוּמָ֑יו] [הֶֽעֱטִ֨יתָ] sobre-ele [בּוּשָׁ֣ה] Selá');
INSERT INTO verses VALUES (15437, 19, 89, 47, 'até yhwh yhwh [לָנֶ֑צַח] [תִּבְעַ֖ר] [כְּמוֹ־אֵ֣שׁ] como');
INSERT INTO verses VALUES (15438, 19, 89, 48, 'lembra-de eu que [בָּרָ֥אתָ] sobre todo homem');
INSERT INTO verses VALUES (15439, 19, 89, 49, 'quem [גֶ֣בֶר] [יִֽ֭חְיֶה] e-não [יִרְאֶה־מָּ֑וֶת] [יְמַלֵּ֨ט] [נַפְשׁ֖וֹ] [מִיַּד־שְׁא֣וֹל] [סֶֽלָה]');
INSERT INTO verses VALUES (15440, 19, 89, 50, '[אַיֵּ֤ה] [׀] [חֲסָדֶ֖יךָ] Adonai [׀] [Adonai] [נִשְׁבַּ֥עְתָּ]');
INSERT INTO verses VALUES (15441, 19, 89, 51, 'macho Adonai [חֶרְפַּ֣ת] servos-teus [שְׂאֵתִ֥י] [בְ֝חֵיקִ֗י] todo muitos');
INSERT INTO verses VALUES (15442, 19, 89, 52, 'que [חֵרְפ֖וּ] [אוֹיְבֶ֥יךָ] yhwh yhwh [אֲשֶׁ֥ר] [חֵ֝רְפ֗וּ] [עִקְּב֥וֹת]');
INSERT INTO verses VALUES (15443, 19, 89, 53, '[בָּר֖וּךְ] yhwh [לְ֝עוֹלָ֗ם] [אָ֘מֵ֥ן] [׀]');
INSERT INTO chapters VALUES (568, 19, 90, 17);
INSERT INTO verses VALUES (15444, 19, 90, 1, '[תְּפִלָּה֮] [לְמֹשֶׁ֢ה] אִישׁ- [אֲ‍ֽדֹנָ֗י] [מָע֣וֹן] tu [הָיִ֥יתָ] [לָּ֗נוּ] [בְּדֹ֣ר] [וָדֹֽר]');
INSERT INTO verses VALUES (15445, 19, 90, 2, '[בְּטֶ֤רֶם] [׀] [הָ֘רִ֤ים] [יֻלָּ֗דוּ] terra terra [וְתֵבֵ֑ל] até [עַד־ע֝וֹלָ֗ם] tu El');
INSERT INTO verses VALUES (15446, 19, 90, 3, '[תָּשֵׁ֣ב] [אֱ֭נוֹשׁ] até E-disse [שׁ֣וּבוּ] [בְנֵי־אָדָֽם] homem');
INSERT INTO verses VALUES (15447, 19, 90, 4, 'que mil dois [בְּֽעֵינֶ֗יךָ] [כְּי֣וֹם] [אֶ֭תְמוֹל] que [יַעֲבֹ֑ר] [וְאַשְׁמוּרָ֥ה] [בַלָּֽיְלָה]');
INSERT INTO verses VALUES (15448, 19, 90, 5, '[זְ֭רַמְתָּם] [שֵׁנָ֣ה] [יִהְי֑וּ] [בַּ֝בֹּ֗קֶר] [כֶּחָצִ֥יר] [יַחֲלֹֽף]');
INSERT INTO verses VALUES (15449, 19, 90, 6, '[בַּ֭בֹּקֶר] [יָצִ֣יץ] [וְחָלָ֑ף] [לָ֝עֶ֗רֶב] [יְמוֹלֵ֥ל] [וְיָבֵֽשׁ]');
INSERT INTO verses VALUES (15450, 19, 90, 7, 'porque [בְאַפֶּ֑ךָ] [וּֽבַחֲמָתְךָ֥] [נִבְהָֽלְנוּ]');
INSERT INTO verses VALUES (15451, 19, 90, 8, '[*שת] [**שַׁתָּ֣ה] [עֲוֺנֹתֵ֣ינוּ] [לְנֶגְדֶּ֑ךָ] [עֲ֝לֻמֵ֗נוּ]');
INSERT INTO verses VALUES (15452, 19, 90, 9, 'que todo [פָּנ֣וּ] [בְעֶבְרָתֶ֑ךָ] [כִּלִּ֖ינוּ] [שָׁנֵ֣ינוּ] [כְמוֹ־הֶֽגֶה]');
INSERT INTO verses VALUES (15453, 19, 90, 10, 'dias-de [בָהֶ֥ם] [שִׁבְעִ֪ים] [שָׁנָ֡ה] [וְאִ֤ם] e-se [׀] [שְׁמ֘וֹנִ֤ים] ano [וְ֭רָהְבָּם] [עָמָ֣ל] [וָאָ֑וֶן] porque [חִ֝֗ישׁ] [וַנָּעֻֽפָה]');
INSERT INTO verses VALUES (15454, 19, 90, 11, 'quem [עֹ֣ז] força [וּ֝כְיִרְאָתְךָ֗] [עֶבְרָתֶֽךָ]');
INSERT INTO verses VALUES (15455, 19, 90, 12, '[לִמְנ֣וֹת] [יָ֭מֵינוּ] assim [הוֹדַ֑ע] [וְ֝נָבִ֗א] [לְבַ֣ב] [חָכְמָֽה]');
INSERT INTO verses VALUES (15456, 19, 90, 13, '[שׁוּבָ֣ה] yhwh até [וְ֝הִנָּחֵ֗ם] [עַל־עֲבָדֶֽיךָ] sobre');
INSERT INTO verses VALUES (15457, 19, 90, 14, '[שַׂבְּעֵ֣נוּ] [בַבֹּ֣קֶר] [חַסְדֶּ֑ךָ] [וּֽנְרַנְּנָ֥ה] [וְ֝נִשְׂמְחָ֗ה] em-todo');
INSERT INTO verses VALUES (15458, 19, 90, 15, '[שַׂ֭מְּחֵנוּ] [כִּימ֣וֹת] [עִנִּיתָ֑נוּ] [שְׁ֝נ֗וֹת] [רָאִ֥ינוּ] mal');
INSERT INTO verses VALUES (15459, 19, 90, 16, '[יֵרָאֶ֣ה] a teus-servos [וַ֝הֲדָרְךָ֗] [עַל־בְּנֵיהֶֽם] sobre [sem-traducao]');
INSERT INTO verses VALUES (15460, 19, 90, 17, 'e-seja [׀] Adonai nosso-Elohim [Elohim] [עָ֫לֵ֥ינוּ] [וּמַעֲשֵׂ֣ה] [יָ֭דֵינוּ] sobre-nós [עָלֵ֑ינוּ] [וּֽמַעֲשֵׂ֥ה] [יָ֝דֵ֗ינוּ]');
INSERT INTO chapters VALUES (569, 19, 91, 16);
INSERT INTO verses VALUES (15461, 19, 91, 1, 'habitou [בְּסֵ֣תֶר] [עֶלְי֑וֹן] [בְּצֵ֥ל] Shaddai [יִתְלוֹנָֽן]');
INSERT INTO verses VALUES (15462, 19, 91, 2, 'disse [לַֽ֭יהוָה] [מַחְסִ֣י] [וּמְצוּדָתִ֑י] meu-Eloah [אֶבְטַח־בּֽוֹ] em-ele');
INSERT INTO verses VALUES (15463, 19, 91, 3, 'que ele [יַ֭צִּֽילְךָ] [מִפַּ֥ח] [יָק֗וּשׁ] [מִדֶּ֥בֶר] [הַוּֽוֹת]');
INSERT INTO verses VALUES (15464, 19, 91, 4, '[בְּאֶבְרָת֨וֹ] [׀] [יָ֣סֶךְ] para-ti [וְתַֽחַת־כְּנָפָ֣יו] [תֶּחְסֶ֑ה] [צִנָּ֖ה] [וְֽסֹחֵרָ֣ה] [אֲמִתּֽוֹ]');
INSERT INTO verses VALUES (15465, 19, 91, 5, 'não [מִפַּ֣חַד] noite noite [יָע֥וּף] [יוֹמָֽם]');
INSERT INTO verses VALUES (15466, 19, 91, 6, '[מִ֭דֶּבֶר] [בָּאֹ֣פֶל] [יַהֲלֹ֑ךְ] [מִ֝קֶּ֗טֶב] [יָשׁ֥וּד] [צָהֳרָֽיִם]');
INSERT INTO verses VALUES (15467, 19, 91, 7, '[יִפֹּ֤ל] [מִצִּדְּךָ֨] mil [אֶ֗לֶף] [וּרְבָבָ֥ה] [מִימִינֶ֑ךָ] não não');
INSERT INTO verses VALUES (15468, 19, 91, 8, '[רַ֭ק] [בְּעֵינֶ֣יךָ] [תַבִּ֑יט] [וְשִׁלֻּמַ֖ת] ímpios [תִּרְאֶֽה]');
INSERT INTO verses VALUES (15469, 19, 91, 9, 'porque yhwh yhwh [עֶ֝לְי֗וֹן] Altissimo [מְעוֹנֶֽךָ] [sem-traducao]');
INSERT INTO verses VALUES (15470, 19, 91, 10, 'não [אֵלֶ֣יךָ] a-ti maldade [לֹא־יִקְרַ֥ב] não');
INSERT INTO verses VALUES (15471, 19, 91, 11, 'que [מַ֭לְאָכָיו] [יְצַוֶּה־לָּ֑ךְ] para-ti [בְּכָל־דְּרָכֶֽיךָ] em-todo');
INSERT INTO verses VALUES (15472, 19, 91, 12, 'sobre [יִשָּׂא֑וּנְךָ] [פֶּן־תִּגֹּ֖ף] para-que-não [רַגְלֶֽךָ]');
INSERT INTO verses VALUES (15473, 19, 91, 13, 'sobre [וָפֶ֣תֶן] [תִּדְרֹ֑ךְ] [תִּרְמֹ֖ס] [כְּפִ֣יר] [וְתַנִּֽין]');
INSERT INTO verses VALUES (15474, 19, 91, 14, 'que [בִ֣י] [חָ֭שַׁק] [וַאֲפַלְּטֵ֑הוּ] [אֲ֝שַׂגְּבֵ֗הוּ] porque conheceu');
INSERT INTO verses VALUES (15475, 19, 91, 15, '[יִקְרָאֵ֨נִי] [׀] [וְֽאֶעֱנֵ֗הוּ] eu [בְצָרָ֑ה] [אֲ֝חַלְּצֵ֗הוּ] [וַֽאֲכַבְּדֵֽהוּ]');
INSERT INTO verses VALUES (15476, 19, 91, 16, 'comprimento [יָ֭מִים] [אַשְׂבִּיעֵ֑הוּ] [וְ֝אַרְאֵ֗הוּ] [בִּֽישׁוּעָתִֽי]');
INSERT INTO chapters VALUES (570, 19, 92, 16);
INSERT INTO verses VALUES (15477, 19, 92, 1, 'salmo [שִׁ֗יר] para-o-dia [הַשַׁבָּֽת]');
INSERT INTO verses VALUES (15478, 19, 92, 2, 'bom [לְהֹד֥וֹת] a-yhwh [וּלְזַמֵּ֖ר] [לְשִׁמְךָ֣] [עֶלְיֽוֹן]');
INSERT INTO verses VALUES (15479, 19, 92, 3, '[לְהַגִּ֣יד] [בַּבֹּ֣קֶר] [חַסְֽדֶּ֑ךָ] [וֶ֝אֱמֽוּנָתְךָ֗] [בַּלֵּילֽוֹת]');
INSERT INTO verses VALUES (15480, 19, 92, 4, '[עֲ‍ֽלֵי־עָ֭שׂוֹר] [וַעֲלֵי־נָ֑בֶל] [עֲלֵ֖י] [הִגָּי֣וֹן] [בְּכִנּֽוֹר]');
INSERT INTO verses VALUES (15481, 19, 92, 5, 'que [שִׂמַּחְתַּ֣נִי] yhwh [בְּפָעֳלֶ֑ךָ] [בְּֽמַעֲשֵׂ֖י] tuas-maos [אֲרַנֵּֽן]');
INSERT INTO verses VALUES (15482, 19, 92, 6, 'que [מַעֲשֶׂ֣יךָ] yhwh muito [עָמְק֥וּ] [מַחְשְׁבֹתֶֽיךָ]');
INSERT INTO verses VALUES (15483, 19, 92, 7, 'אִישׁ- não não conheceu [לֹא־יָבִ֥ין] não entenderá a esta-ali');
INSERT INTO verses VALUES (15484, 19, 92, 8, '[בִּפְרֹ֤חַ] [רְשָׁעִ֨ים] [׀] [כְּמ֥וֹ] [עֵ֗שֶׂב] todo [כָּל־פֹּ֣עֲלֵי] iniquidade [לְהִשָּֽׁמְדָ֥ם] ate até');
INSERT INTO verses VALUES (15485, 19, 92, 9, '[וְאַתָּ֥ה] [מָר֗וֹם] para-sempre yhwh');
INSERT INTO verses VALUES (15486, 19, 92, 10, 'que eis [אֹיְבֶ֡יךָ] yhwh porque eis [יֹאבֵ֑דוּ] perecerao [כָּל־פֹּ֥עֲלֵי] todo [sem-traducao] iniquidade');
INSERT INTO verses VALUES (15487, 19, 92, 11, '[וַתָּ֣רֶם] [כִּרְאֵ֣ים] [קַרְנִ֑י] [בַּ֝לֹּתִ֗י] [בְּשֶׁ֣מֶן] [רַעֲנָֽן]');
INSERT INTO verses VALUES (15488, 19, 92, 12, '[וַתַּבֵּ֥ט] [עֵינִ֗י] [בְּשׁ֫וּרָ֥י] [בַּקָּמִ֖ים] [עָלַ֥י] [מְרֵעִ֗ים] [תִּשְׁמַ֥עְנָה] [אָזְנָֽי]');
INSERT INTO verses VALUES (15489, 19, 92, 13, 'justo [כַּתָּמָ֣ר] [יִפְרָ֑ח] [כְּאֶ֖רֶז] [בַּלְּבָנ֣וֹן] [יִשְׂגֶּֽה]');
INSERT INTO verses VALUES (15490, 19, 92, 14, '[שְׁ֭תוּלִים] na-casa-de yhwh [בְּחַצְר֖וֹת] [Elohim] [יַפְרִֽיחוּ]');
INSERT INTO verses VALUES (15491, 19, 92, 15, '[ע֭וֹד] [יְנוּב֣וּן] [בְּשֵׂיבָ֑ה] [דְּשֵׁנִ֖ים] [וְרַֽעֲנַנִּ֣ים] [יִהְיֽוּ]');
INSERT INTO verses VALUES (15492, 19, 92, 16, '[לְ֭הַגִּיד] porque yhwh yhwh [וְֽלֹא־*עלתה] e-não nele');
INSERT INTO chapters VALUES (571, 19, 93, 5);
INSERT INTO verses VALUES (15493, 19, 93, 1, 'yhwh rei [גֵּא֢וּת] [לָ֫בֵ֥שׁ] [לָבֵ֣שׁ] yhwh força [הִתְאַזָּ֑ר] também [תֵּ֝בֵ֗ל] [בַּל־תִּמּֽוֹט]');
INSERT INTO verses VALUES (15494, 19, 93, 2, 'firme [כִּסְאֲךָ֣] [מֵאָ֑ז] [מֵֽעוֹלָ֣ם] tu');
INSERT INTO verses VALUES (15495, 19, 93, 3, '[נָשְׂא֤וּ] [נְהָר֨וֹת] yhwh yhwh [נָשְׂא֣וּ] [נְהָר֣וֹת] [קוֹלָ֑ם] [יִשְׂא֖וּ] [נְהָר֣וֹת]');
INSERT INTO verses VALUES (15496, 19, 93, 4, '[מִקֹּל֨וֹת] águas águas [רַבִּ֗ים] [אַדִּירִ֣ים] mar [אַדִּ֖יר] [בַּמָּר֣וֹם] yhwh');
INSERT INTO verses VALUES (15497, 19, 93, 5, '[עֵֽדֹתֶ֨יךָ] [׀] [נֶאֶמְנ֬וּ] muito [לְבֵיתְךָ֥] santidade yhwh [לְאֹ֣רֶךְ] dias');
INSERT INTO chapters VALUES (572, 19, 94, 23);
INSERT INTO verses VALUES (15498, 19, 94, 1, 'a yhwh yhwh El [הוֹפִֽיעַ[t]]');
INSERT INTO verses VALUES (15499, 19, 94, 2, '[הִ֭נָּשֵׂא] [שֹׁפֵ֣ט] a-terra [הָשֵׁ֥ב] [גְּ֝מ֗וּל] sobre');
INSERT INTO verses VALUES (15500, 19, 94, 3, 'até até-quando [׀] yhwh até [רְשָׁעִ֥ים] [יַעֲלֹֽזוּ]');
INSERT INTO verses VALUES (15501, 19, 94, 4, '[יַבִּ֣יעוּ] [יְדַבְּר֣וּ] [עָתָ֑ק] [יִֽ֝תְאַמְּר֗וּ] todo [אָֽוֶן]');
INSERT INTO verses VALUES (15502, 19, 94, 5, 'teu-povo yhwh [יְדַכְּא֑וּ] [וְֽנַחֲלָתְךָ֥] [יְעַנּֽוּ]');
INSERT INTO verses VALUES (15503, 19, 94, 6, '[אַ֭לְמָנָה] [וְגֵ֣ר] [יַהֲרֹ֑גוּ] [וִֽיתוֹמִ֣ים] [יְרַצֵּֽחוּ]');
INSERT INTO verses VALUES (15504, 19, 94, 7, '[וַ֭יֹּ֣אמְרוּ] não [יִרְאֶה־יָּ֑הּ] [וְלֹא־יָ֝בִ֗ין] e-não [יַעֲקֹֽב] Jacó');
INSERT INTO verses VALUES (15505, 19, 94, 8, '[בִּ֭ינוּ] [בֹּעֲרִ֣ים] [בָּעָ֑ם] [וּ֝כְסִילִ֗ים] quando [תַּשְׂכִּֽילוּ]');
INSERT INTO verses VALUES (15506, 19, 94, 9, '[הֲנֹ֣טַֽע] [אֹ֭זֶן] porventura-não [יִשְׁמָ֑ע] se olho olho porventura-não');
INSERT INTO verses VALUES (15507, 19, 94, 10, '[הֲיֹסֵ֣ר] [גּ֭וֹיִם] porventura-não [יוֹכִ֑יחַ] [הַֽמְלַמֵּ֖ד] homem [דָּֽעַת]');
INSERT INTO verses VALUES (15508, 19, 94, 11, 'yhwh sabe [מַחְשְׁב֣וֹת] homem porque eles');
INSERT INTO verses VALUES (15509, 19, 94, 12, '[אַשְׁרֵ֤י] [׀] que [אֲשֶׁר־תְּיַסְּרֶ֣נּוּ] [יָּ֑הּ] [וּֽמִתּוֹרָתְךָ֥] [תְלַמְּדֶֽנּוּ]');
INSERT INTO verses VALUES (15510, 19, 94, 13, '[לְהַשְׁקִ֣יט] a-ele [מִ֣ימֵי] mal até [יִכָּרֶ֖ה] [לָרָשָׁ֣ע] [שָֽׁחַת]');
INSERT INTO verses VALUES (15511, 19, 94, 14, 'que não [לֹא־יִטֹּ֣שׁ] yhwh povo-seu [וְ֝נַחֲלָת֗וֹ] não [יַעֲזֹֽב]');
INSERT INTO verses VALUES (15512, 19, 94, 15, 'porque até [מִשְׁפָּ֑ט] voltara juízo [sem-traducao] todo [sem-traducao] coração');
INSERT INTO verses VALUES (15513, 19, 94, 16, 'quem [לִ֭י] para-mim com [לִ֝י] quem se-posicionará com');
INSERT INTO verses VALUES (15514, 19, 94, 17, 'se-nao-fosse yhwh [עֶזְרָ֣תָה] a-mim [כִּמְעַ֓ט] [׀] [שָֽׁכְנָ֖ה] [דוּמָ֣ה]');
INSERT INTO verses VALUES (15515, 19, 94, 18, 'se [מָ֣טָה] [רַגְלִ֑י] [חַסְדְּךָ֥] yhwh yhwh');
INSERT INTO verses VALUES (15516, 19, 94, 19, 'em-multidão [שַׂרְעַפַּ֣י] [בְּקִרְבִּ֑י] [תַּ֝נְחוּמֶ֗יךָ] [יְֽשַׁעַשְׁע֥וּ] [נַפְשִֽׁי]');
INSERT INTO verses VALUES (15517, 19, 94, 20, '[הַֽ֭יְחָבְרְךָ] trono-de [הַוּ֑וֹת] [יֹצֵ֖ר] [עָמָ֣ל] sobre');
INSERT INTO verses VALUES (15518, 19, 94, 21, '[יָ֭גוֹדּוּ] sobre alma justo [נָקִ֣י] [יַרְשִֽׁיעוּ]');
INSERT INTO verses VALUES (15519, 19, 94, 22, 'e-houve yhwh para-mim [לְמִשְׂגָּ֑ב] [וֵ֝אלֹהַ֗י] [לְצ֣וּר] [מַחְסִֽי]');
INSERT INTO verses VALUES (15520, 19, 94, 23, '[וַיָּ֤שֶׁב] [עֲלֵיהֶ֨ם] a [אֶת־אוֹנָ֗ם] [וּבְרָעָתָ֥ם] [יַצְמִיתֵ֑ם] [יַ֝צְמִיתֵ֗ם] yhwh nosso-Elohim');
INSERT INTO chapters VALUES (573, 19, 95, 11);
INSERT INTO verses VALUES (15521, 19, 95, 1, '[לְ֭כוּ] [נְרַנְּנָ֣ה] a-yhwh [נָ֝רִ֗יעָה] [לְצ֣וּר] [יִשְׁעֵֽנוּ]');
INSERT INTO verses VALUES (15522, 19, 95, 2, '[נְקַדְּמָ֣ה] [פָנָ֣יו] [בְּתוֹדָ֑ה] [בִּ֝זְמִר֗וֹת] [נָרִ֥יעַֽ] a-ele');
INSERT INTO verses VALUES (15523, 19, 95, 3, 'que El grande yhwh e-rei-de grande sobre todo Elohim');
INSERT INTO verses VALUES (15524, 19, 95, 4, 'que [בְּ֭יָדוֹ] [מֶחְקְרֵי־אָ֑רֶץ] terra [הָרִ֣ים] a-ele');
INSERT INTO verses VALUES (15525, 19, 95, 5, 'que o-mar [וְה֣וּא] e-ele [וְ֝יַבֶּ֗שֶׁת] [יָדָ֥יו] [יָצָֽרוּ]');
INSERT INTO verses VALUES (15526, 19, 95, 6, '[בֹּ֭אוּ] [נִשְׁתַּחֲוֶ֣ה] [וְנִכְרָ֑עָה] [נִ֝בְרְכָ֗ה] [לִֽפְנֵי־יְהוָ֥ה] yhwh');
INSERT INTO verses VALUES (15527, 19, 95, 7, 'que ele nosso-Elohim [וַאֲנַ֤חְנוּ] povo [מַ֭רְעִיתוֹ] [וְצֹ֣אן] sua-mão o-dia se [תִשְׁמָֽעוּ]');
INSERT INTO verses VALUES (15528, 19, 95, 8, 'a [לְ֭בַבְכֶם] [כִּמְרִיבָ֑ה] [כְּי֥וֹם] [מַ֝סָּ֗ה] [בַּמִּדְבָּֽר]');
INSERT INTO verses VALUES (15529, 19, 95, 9, 'que [נִ֭סּוּנִי] [אֲבוֹתֵיכֶ֑ם] [בְּ֝חָנ֗וּנִי] também [פָעֳלֽ͏ִי]');
INSERT INTO verses VALUES (15530, 19, 95, 10, '[אַרְבָּ֘עִ֤ים] [שָׁנָ֨ה] [׀] [אָ֘ק֤וּט] e-disse povo [עַ֤ם] [תֹּעֵ֣י] eles eles não [לֹא־יָדְע֥וּ] [דְרָכָֽי]');
INSERT INTO verses VALUES (15531, 19, 95, 11, 'que [בְאַפִּ֑י] [אִם־יְ֝בֹא֗וּן] se a');
INSERT INTO chapters VALUES (574, 19, 96, 13);
INSERT INTO verses VALUES (15532, 19, 96, 1, '[שִׁ֣ירוּ] [לַ֭יהוָה] [שִׁ֣יר] novo [שִׁ֥ירוּ] [לַ֝יהוָ֗ה] todo a-terra');
INSERT INTO verses VALUES (15533, 19, 96, 2, '[שִׁ֣ירוּ] [לַ֭יהוָה] [בָּרֲכ֣וּ] seu-nome [בַּשְּׂר֥וּ] [מִיּֽוֹם־לְ֝י֗וֹם] [יְשׁוּעָתֽוֹ]');
INSERT INTO verses VALUES (15534, 19, 96, 3, '[סַפְּר֣וּ] [בַגּוֹיִ֣ם] [כְּבוֹד֑וֹ] em-todo [נִפְלְאוֹתָֽיו]');
INSERT INTO verses VALUES (15535, 19, 96, 4, 'que grande yhwh [וּמְהֻלָּ֣ל] muito [נוֹרָ֥א] ele sobre todo Elohim');
INSERT INTO verses VALUES (15536, 19, 96, 5, 'que todo Elohim-de [הָעַמִּ֣ים] [אֱלִילִ֑ים] [וַֽ֝יהוָ֗ה] céus fez');
INSERT INTO verses VALUES (15537, 19, 96, 6, '[הוֹד־וְהָדָ֥ר] [לְפָנָ֑יו] diante-dele [וְ֝תִפְאֶ֗רֶת] [בְּמִקְדָּשֽׁוֹ]');
INSERT INTO verses VALUES (15538, 19, 96, 7, 'dai a-yhwh [מִשְׁפְּח֣וֹת] [עַמִּ֑ים] dai [לַ֝יהוָ֗ה] [כָּב֥וֹד] [וָעֹֽז]');
INSERT INTO verses VALUES (15539, 19, 96, 8, 'dai [לַ֭יהוָה] glória-de seu-nome carreguem- [וּבֹ֥אוּ] [לְחַצְרוֹתָֽיו]');
INSERT INTO verses VALUES (15540, 19, 96, 9, '[הִשְׁתַּחֲו֣וּ] [לַ֭יהוָה] [בְּהַדְרַת־קֹ֑דֶשׁ] santidade [מִ֝פָּנָ֗יו] [כָּל־הָאָֽרֶץ] todo a-terra');
INSERT INTO verses VALUES (15541, 19, 96, 10, '[אִמְר֤וּ] [בַגּוֹיִ֨ם] yhwh yhwh também [אַף־תִּכּ֣וֹן] [תֵּ֭בֵל] não [יָדִ֥ין] [עַ֝מִּ֗ים] [בְּמֵישָׁרִֽים]');
INSERT INTO verses VALUES (15542, 19, 96, 11, '[יִשְׂמְח֣וּ] os-céus [וְתָגֵ֣ל] a-terra [יִֽרְעַ֥ם] o-mar [וּמְלֹאֽוֹ]');
INSERT INTO verses VALUES (15543, 19, 96, 12, '[יַעֲלֹ֣ז] Shaddai e-todo que nele entao [sem-traducao] todo madeiras-de [sem-traducao]');
INSERT INTO verses VALUES (15544, 19, 96, 13, 'diante-de yhwh porque que porque que [בָא֮] a-terra a-terra [יִשְׁפֹּֽט־תֵּבֵ֥ל] [בְּצֶ֑דֶק] [וְ֝עַמִּ֗ים] [בֶּאֱמוּנָתֽוֹ]');
INSERT INTO chapters VALUES (575, 19, 97, 12);
INSERT INTO verses VALUES (15545, 19, 97, 1, 'yhwh rei [תָּגֵ֣ל] a-terra [יִ֝שְׂמְח֗וּ] [אִיִּ֥ים] muitos');
INSERT INTO verses VALUES (15546, 19, 97, 2, '[עָנָ֣ן] [וַעֲרָפֶ֣ל] [סְבִיבָ֑יו] [צֶ֥דֶק] [וּ֝מִשְׁפָּ֗ט] [מְכ֣וֹן] [כִּסְאֽוֹ]');
INSERT INTO verses VALUES (15547, 19, 97, 3, '[אֵ֭שׁ] diante-dele [תֵּלֵ֑ךְ] [וּתְלַהֵ֖ט] [סָבִ֣יב] [צָרָֽיו]');
INSERT INTO verses VALUES (15548, 19, 97, 4, '[הֵאִ֣ירוּ] [בְרָקָ֣יו] [תֵּבֵ֑ל] [רָאֲתָ֖ה] [וַתָּחֵ֣ל] a-terra');
INSERT INTO verses VALUES (15549, 19, 97, 5, '[הָרִ֗ים] [כַּדּוֹנַ֗ג] [נָ֭מַסּוּ] [מִלִּפְנֵ֣י] yhwh [מִ֝לִּפְנֵ֗י] [אֲד֣וֹן] todo a-terra');
INSERT INTO verses VALUES (15550, 19, 97, 6, '[הִגִּ֣ידוּ] os-céus [צִדְק֑וֹ] [וְרָא֖וּ] todo [כְּבוֹדֽוֹ]');
INSERT INTO verses VALUES (15551, 19, 97, 7, '[יֵבֹ֤שׁוּ] todo [כָּל־עֹ֬בְדֵי] [פֶ֗סֶל] [הַמִּֽתְהַלְלִ֥ים] [בָּאֱלִילִ֑ים] [הִשְׁתַּחֲווּ־ל֝וֹ] [כָּל־אֱלֹהִֽים] todo Elohim');
INSERT INTO verses VALUES (15552, 19, 97, 8, '[שָׁמְעָ֬ה] [וַתִּשְׂמַ֨ח] Siao [צִיּ֗וֹן] filhas-de Judá para-que [לְמַ֖עַן] yhwh');
INSERT INTO verses VALUES (15553, 19, 97, 9, 'porque yhwh yhwh [עַל־כָּל־הָאָ֑רֶץ] muito todo a-terra sobre todo Elohim');
INSERT INTO verses VALUES (15554, 19, 97, 10, '[אֹהֲבֵ֥י] yhwh [שִׂנְא֫וּ] mal [שֹׁ֭מֵר] [נַפְשׁ֣וֹת] [חֲסִידָ֑יו] de-mão-de ímpios [יַצִּילֵֽם]');
INSERT INTO verses VALUES (15555, 19, 97, 11, 'luz [זָרֻ֣עַ] [לַצַּדִּ֑יק] [וּֽלְיִשְׁרֵי־לֵ֥ב] coração');
INSERT INTO verses VALUES (15556, 19, 97, 12, '[שִׂמְח֣וּ] [צַ֭דִּיקִים] [בַּֽיהוָ֑ה] [וְ֝הוֹד֗וּ] [לְזֵ֣כֶר] [קָדְשֽׁוֹ]');
INSERT INTO chapters VALUES (576, 19, 98, 9);
INSERT INTO verses VALUES (15557, 19, 98, 1, '[מִזְמ֡וֹר] [שִׁ֤ירוּ] [לַֽיהוָ֨ה] [׀] novo porque [כִּֽי־נִפְלָא֣וֹת] fez [הוֹשִֽׁיעָה־לּ֥וֹ] [יְ֝מִינ֗וֹ] [וּזְר֥וֹעַ] [קָדְשֽׁוֹ]');
INSERT INTO verses VALUES (15558, 19, 98, 2, '[הוֹדִ֣יעַ] yhwh [יְשׁוּעָת֑וֹ] [לְעֵינֵ֥י] [הַ֝גּוֹיִ֗ם] [גִּלָּ֥ה] [צִדְקָתֽוֹ]');
INSERT INTO verses VALUES (15559, 19, 98, 3, 'macho [חַסְדּ֨וֹ] [׀] [וֶֽאֱֽמוּנָתוֹ֮] Israel [יִשְׂרָ֫אֵ֥ל] todo [כָל־אַפְסֵי־אָ֑רֶץ] terra [OBJ] [אֱלֹהֵֽינוּ]');
INSERT INTO verses VALUES (15560, 19, 98, 4, '[הָרִ֣יעוּ] [לַֽ֭יהוָה] todo a-terra [וְרַנְּנ֣וּ] [וְזַמֵּֽרוּ]');
INSERT INTO verses VALUES (15561, 19, 98, 5, '[זַמְּר֣וּ] a-yhwh [בְּכִנּ֑וֹר] [בְּ֝כִנּ֗וֹר] e-voz [זִמְרָֽה]');
INSERT INTO verses VALUES (15562, 19, 98, 6, '[בַּ֭חֲצֹ֣צְרוֹת] e-voz [שׁוֹפָ֑ר] [הָ֝רִ֗יעוּ] [לִפְנֵ֤י] [׀] yhwh');
INSERT INTO verses VALUES (15563, 19, 98, 7, '[יִרְעַ֣ם] o-mar [וּמְלֹא֑וֹ] [תֵּ֝בֵ֗ל] [וְיֹ֣שְׁבֵי] nela');
INSERT INTO verses VALUES (15564, 19, 98, 8, '[נְהָר֥וֹת] [יִמְחֲאוּ־כָ֑ף] [יַ֝֗חַד] [הָרִ֥ים] [יְרַנֵּֽנוּ]');
INSERT INTO verses VALUES (15565, 19, 98, 9, '[לִֽפְֽנֵי־יְהוָ֗ה] que porque veio a-terra a-terra [בְּצֶ֑דֶק] [וְ֝עַמִּ֗ים] [בְּמֵישָׁרִֽים]');
INSERT INTO chapters VALUES (577, 19, 99, 9);
INSERT INTO verses VALUES (15566, 19, 99, 1, 'yhwh rei [יִרְגְּז֣וּ] [עַמִּ֑ים] habitou [כְּ֝רוּבִ֗ים] [תָּנ֥וּט] a-terra');
INSERT INTO verses VALUES (15567, 19, 99, 2, 'yhwh [בְּצִיּ֣וֹן] grande [וְרָ֥ם] ele sobre todo');
INSERT INTO verses VALUES (15568, 19, 99, 3, '[יוֹד֣וּ] [שִׁ֭מְךָ] grande [וְנוֹרָ֗א] santo ele');
INSERT INTO verses VALUES (15569, 19, 99, 4, '[וְעֹ֥ז] rei [מִשְׁפָּ֢ט] amou tu [כּוֹנַ֣נְתָּ] [מֵישָׁרִ֑ים] [מִשְׁפָּ֥ט] [וּ֝צְדָקָ֗ה] [בְּיַעֲקֹ֤ב] [׀] tu');
INSERT INTO verses VALUES (15570, 19, 99, 5, '[רֽוֹמְמ֡וּ] yhwh nosso-Elohim [וְֽ֭הִשְׁתַּחֲווּ] [לַהֲדֹ֥ם] [רַגְלָ֗יו] santo ele');
INSERT INTO verses VALUES (15571, 19, 99, 6, 'Moisés [וְאַהֲרֹ֨ן] [׀] [בְּֽכֹהֲנָ֗יו] seu-nome [בְּקֹרְאֵ֣י] a yhwh e-ele [וְה֣וּא]');
INSERT INTO verses VALUES (15572, 19, 99, 7, '[בְּעַמּ֣וּד] [עָ֭נָן] [יְדַבֵּ֣ר] a-eles [שָׁמְר֥וּ] [עֵ֝דֹתָ֗יו] [וְחֹ֣ק] deu a-eles');
INSERT INTO verses VALUES (15573, 19, 99, 8, 'yhwh [Elohim] tu [עֲנִ֫יתָ֥ם] El [נֹ֭שֵׂא] [הָיִ֣יתָ] a-eles [וְ֝נֹקֵ֗ם] sobre');
INSERT INTO verses VALUES (15574, 19, 99, 9, '[רֽוֹמְמ֡וּ] yhwh nosso-Elohim [וְ֭הִֽשְׁתַּחֲווּ] [לְהַ֣ר] sua-santidade porque yhwh yhwh אֱלֹהִים-nosso');
INSERT INTO chapters VALUES (578, 19, 100, 5);
INSERT INTO verses VALUES (15575, 19, 100, 1, 'salmo [לְתוֹדָ֑ה] [הָרִ֥יעוּ] [לַ֝יהוָ֗ה] todo a-terra');
INSERT INTO verses VALUES (15576, 19, 100, 2, '[עִבְד֣וּ] a yhwh [בֹּ֥אוּ] [לְ֝פָנָ֗יו] [בִּרְנָנָֽה]');
INSERT INTO verses VALUES (15577, 19, 100, 3, '[דְּע֗וּ] porque ele ele Elohim [*ולא] [**וְל֣וֹ] [אֲנַ֑חְנוּ] [עַ֝מּ֗וֹ] [וְצֹ֣אן] [מַרְעִיתֽוֹ]');
INSERT INTO verses VALUES (15578, 19, 100, 4, '[בֹּ֤אוּ] [שְׁעָרָ֨יו] [׀] [בְּתוֹדָ֗ה] [חֲצֵרֹתָ֥יו] [בִּתְהִלָּ֑ה] [הֽוֹדוּ־ל֝֗וֹ] [בָּרֲכ֥וּ] [שְׁמֽוֹ]');
INSERT INTO verses VALUES (15579, 19, 100, 5, 'porque bom yhwh para-sempre sua-benignidade e-até [אֱמוּנָֽתוֹ] [sem-traducao] [sem-traducao]');
INSERT INTO chapters VALUES (579, 19, 101, 8);
INSERT INTO verses VALUES (15580, 19, 101, 1, '[לְדָוִ֗ד] [מִ֫זְמ֥וֹר] [חֶֽסֶד־וּמִשְׁפָּ֥ט] [אָשִׁ֑ירָה] a-ti yhwh yhwh');
INSERT INTO verses VALUES (15581, 19, 101, 2, '[אַשְׂכִּ֤ילָה] [׀] [בְּדֶ֬רֶךְ] [תָּמִ֗ים] [מָ֭תַי] a-mim [אֵלָ֑י] [אֶתְהַלֵּ֥ךְ] [בְּתָם־לְ֝בָבִ֗י] [בְּקֶ֣רֶב] [בֵּיתִֽי]');
INSERT INTO verses VALUES (15582, 19, 101, 3, 'não [׀] [לְנֶ֥גֶד] [עֵינַ֗י] [דְּֽבַר־בְּלִ֫יָּ֥עַל] [עֲשֹֽׂה־סֵטִ֥ים] [שָׂנֵ֑אתִי] não [יִדְבַּ֣ק] não');
INSERT INTO verses VALUES (15583, 19, 101, 4, '[לֵבָ֣ב] [עִ֭קֵּשׁ] [יָס֣וּר] [מִמֶּ֑נִּי] mal não [אֵדָֽע]');
INSERT INTO verses VALUES (15584, 19, 101, 5, '[*מלושני] [**מְלָשְׁנִ֬י] [בַסֵּ֨תֶר] [׀] [רֵעֵהוּ֮] [אוֹת֢וֹ] [אַ֫צְמִ֥ית] [גְּֽבַהּ־עֵ֭ינַיִם] [וּרְחַ֣ב] não ele');
INSERT INTO verses VALUES (15585, 19, 101, 6, '[עֵינַ֤י] [׀] terra [לָשֶׁ֢בֶת] comigo andou no-caminho [תָּמִ֑ים] ele [יְשָׁרְתֵֽנִי]');
INSERT INTO verses VALUES (15586, 19, 101, 7, 'não [׀] [בְּקֶ֥רֶב] [בֵּיתִי֮] fez [רְמִ֫יָּ֥ה] palavra [שְׁקָרִ֑ים] não [לְנֶ֣גֶד] [עֵינָֽי]');
INSERT INTO verses VALUES (15587, 19, 101, 8, '[לַבְּקָרִ֗ים] [אַצְמִ֥ית] todo [לְהַכְרִ֥ית] terra [כָּל־פֹּ֥עֲלֵי] [אָֽוֶן] yhwh todo');
INSERT INTO chapters VALUES (580, 19, 102, 29);
INSERT INTO verses VALUES (15588, 19, 102, 1, '[תְּ֭פִלָּה] [לְעָנִ֣י] porque [וְלִפְנֵ֥י] yhwh yhwh [שִׂיחֽוֹ]');
INSERT INTO verses VALUES (15589, 19, 102, 2, 'yhwh [שִׁמְעָ֣ה] [תְפִלָּתִ֑י] [וְ֝שַׁוְעָתִ֗י] a-ti [תָבֽוֹא]');
INSERT INTO verses VALUES (15590, 19, 102, 3, 'a [פָּנֶ֨יךָ] [׀] [מִמֶּנִּי֮] [בְּי֢וֹם] [צַ֫ר] para-mim [הַטֵּֽה־אֵלַ֥י] [אָזְנֶ֑ךָ] [בְּי֥וֹם] [אֶ֝קְרָ֗א] [מַהֵ֥ר] [עֲנֵֽנִי]');
INSERT INTO verses VALUES (15591, 19, 102, 4, 'porque [בְעָשָׁ֣ן] [יָמָ֑י] [וְ֝עַצְמוֹתַ֗י] [כְּמוֹ־קֵ֥ד] como');
INSERT INTO verses VALUES (15592, 19, 102, 5, '[הוּכָּֽה־כָ֭עֵשֶׂב] [וַיִּבַ֣שׁ] [לִבִּ֑י] meu-coração porque [לַחְמִֽי]');
INSERT INTO verses VALUES (15593, 19, 102, 6, '[מִקּ֥וֹל] [אַנְחָתִ֑י] [דָּבְקָ֥ה] [עַ֝צְמִ֗י] [לִבְשָׂרִֽי]');
INSERT INTO verses VALUES (15594, 19, 102, 7, '[דָּ֭מִיתִי] [לִקְאַ֣ת] [מִדְבָּ֑ר] [הָ֝יִ֗יתִי] [כְּכ֣וֹס] [חֳרָבֽוֹת]');
INSERT INTO verses VALUES (15595, 19, 102, 8, '[שָׁקַ֥דְתִּי] [וָאֶֽהְיֶ֑ה] [כְּ֝צִפּ֗וֹר] [בּוֹדֵ֥ד] sobre');
INSERT INTO verses VALUES (15596, 19, 102, 9, 'todo o-dia [אוֹיְבָ֑י] [מְ֝הוֹלָלַ֗י] [בִּ֣י] [נִשְׁבָּֽעוּ] [sem-traducao]');
INSERT INTO verses VALUES (15597, 19, 102, 10, 'porque [כַּלֶּ֣חֶם] [אָכָ֑לְתִּי] [וְ֝שִׁקֻּוַ֗י] [בִּבְכִ֥י] [מָסָֽכְתִּי]');
INSERT INTO verses VALUES (15598, 19, 102, 11, '[מִפְּנֵֽי־זַֽעַמְךָ֥] [וְקִצְפֶּ֑ךָ] que porque [וַתַּשְׁלִיכֵֽנִי]');
INSERT INTO verses VALUES (15599, 19, 102, 12, '[יָ֭מַי] [כְּצֵ֣ל] [נָט֑וּי] e-eu [כָּעֵ֥שֶׂב] [אִיבָֽשׁ]');
INSERT INTO verses VALUES (15600, 19, 102, 13, 'e-tu yhwh para-sempre [תֵּשֵׁ֑ב] [וְ֝זִכְרְךָ֗] para-a-geração [וָדֹֽר]');
INSERT INTO verses VALUES (15601, 19, 102, 14, 'tu [תָ֭קוּם] [תְּרַחֵ֣ם] Sião porque tempo [כִּי־בָ֥א] porque veio');
INSERT INTO verses VALUES (15602, 19, 102, 15, 'porque [עֲ֭בָדֶיךָ] [אֶת־אֲבָנֶ֑יהָ] a [יְחֹנֵֽנוּ] e-[OBJ]');
INSERT INTO verses VALUES (15603, 19, 102, 16, '[וְיִֽירְא֣וּ] [ג֭וֹיִם] a yhwh yhwh a-terra reis-de a-terra a');
INSERT INTO verses VALUES (15604, 19, 102, 17, 'porque yhwh yhwh Sião [בִּכְבוֹדֽוֹ]');
INSERT INTO verses VALUES (15605, 19, 102, 18, '[פָּ֭נָה] a [הָעַרְעָ֑ר] [וְלֹֽא־בָ֝זָ֗ה] e-não a');
INSERT INTO verses VALUES (15606, 19, 102, 19, '[תִּכָּ֣תֶב] esta [לְד֣וֹר] [אַחֲר֑וֹן] [וְעַ֥ם] [נִ֝בְרָ֗א] [יְהַלֶּל־יָֽהּ]');
INSERT INTO verses VALUES (15607, 19, 102, 20, 'porque [מִמְּר֣וֹם] [קָדְשׁ֑וֹ] yhwh yhwh [׀] a terra');
INSERT INTO verses VALUES (15608, 19, 102, 21, '[לִ֭שְׁמֹעַ] [אֶנְקַ֣ת] [אָסִ֑יר] [לְ֝פַתֵּ֗חַ] filhos-de [תְמוּתָֽה]');
INSERT INTO verses VALUES (15609, 19, 102, 22, '[לְסַפֵּ֣ר] [בְּ֭צִיּוֹן] nome yhwh [וּ֝תְהִלָּת֗וֹ] [בִּירוּשָׁלָֽ͏ִם]');
INSERT INTO verses VALUES (15610, 19, 102, 23, '[בְּהִקָּבֵ֣ץ] povos juntos [וּ֝מַמְלָכ֗וֹת] para-lavrar a yhwh');
INSERT INTO verses VALUES (15611, 19, 102, 24, '[עִנָּ֖ה] [בַדֶּ֥רֶךְ] [*כחו] [**כֹּחִ֗י]');
INSERT INTO verses VALUES (15612, 19, 102, 25, 'disse [אֵלִ֗י] a [בַּחֲצִ֣י] [יָמָ֑י] [בְּד֖וֹר] [דּוֹרִ֣ים] [שְׁנוֹתֶֽיךָ]');
INSERT INTO verses VALUES (15613, 19, 102, 26, '[לְ֭פָנִים] a-terra [יָסַ֑דְתָּ] [וּֽמַעֲשֵׂ֖ה] tuas-maos céus');
INSERT INTO verses VALUES (15614, 19, 102, 27, '[הֵ֤מָּה] [׀] [יֹאבֵדוּ֮] [וְאַתָּ֢ה] [תַ֫עֲמֹ֥ד] [וְ֭כֻלָּם] [כַּבֶּ֣גֶד] [יִבְל֑וּ] [כַּלְּב֖וּשׁ] [תַּחֲלִיפֵ֣ם]');
INSERT INTO verses VALUES (15615, 19, 102, 28, '[וְאַתָּה־ה֑וּא] ele não não');
INSERT INTO verses VALUES (15616, 19, 102, 29, 'filhos-de [יִשְׁכּ֑וֹנוּ] [וְ֝זַרְעָ֗ם] [לְפָנֶ֥יךָ] [יִכּֽוֹן]');
INSERT INTO chapters VALUES (581, 19, 103, 22);
INSERT INTO verses VALUES (15617, 19, 103, 1, 'a-Davi [׀] minha-alma a yhwh e-todo [אֶת־שֵׁ֥ם] a nome [sem-traducao]');
INSERT INTO verses VALUES (15618, 19, 103, 2, '[בָּרְכִ֣י] minha-alma a yhwh e-a todo');
INSERT INTO verses VALUES (15619, 19, 103, 3, '[הַסֹּלֵ֥חַ] para-todo [הָ֝רֹפֵ֗א] [לְכָל־תַּחֲלֻאָֽיְכִי] para-todo');
INSERT INTO verses VALUES (15620, 19, 103, 4, '[הַגּוֹאֵ֣ל] [מִשַּׁ֣חַת] [חַיָּ֑יְכִי] [הַֽ֝מְעַטְּרֵ֗כִי] [חֶ֣סֶד] [וְרַחֲמִֽים]');
INSERT INTO verses VALUES (15621, 19, 103, 5, '[הַמַּשְׂבִּ֣יעַ] [בַּטּ֣וֹב] [עֶדְיֵ֑ךְ] [תִּתְחַדֵּ֖שׁ] [כַּנֶּ֣שֶׁר] [נְעוּרָֽיְכִי]');
INSERT INTO verses VALUES (15622, 19, 103, 6, 'fez [צְדָק֣וֹת] yhwh [וּ֝מִשְׁפָּטִ֗ים] para-todo');
INSERT INTO verses VALUES (15623, 19, 103, 7, '[יוֹדִ֣יעַ] [דְּרָכָ֣יו] [לְמֹשֶׁ֑ה] para-os-filhos-de Israel [עֲלִילֽוֹתָיו]');
INSERT INTO verses VALUES (15624, 19, 103, 8, '[רַח֣וּם] [וְחַנּ֣וּן] yhwh [אֶ֖רֶךְ] [אַפַּ֣יִם] e-grande bondade');
INSERT INTO verses VALUES (15625, 19, 103, 9, 'não [יָרִ֑יב] [וְלֹ֖א] e-não para-sempre');
INSERT INTO verses VALUES (15626, 19, 103, 10, 'não [כַ֭חֲטָאֵינוּ] fez [לָ֑נוּ] e-não [כַ֝עֲוֺנֹתֵ֗ינוּ] [גָּמַ֥ל] [עָלֵֽינוּ]');
INSERT INTO verses VALUES (15627, 19, 103, 11, 'que [כִגְבֹ֣הַּ] céus sobre a-terra [חַ֝סְדּ֗וֹ] [עַל־יְרֵאָֽיו] sobre');
INSERT INTO verses VALUES (15628, 19, 103, 12, '[כִּרְחֹ֣ק] [מִ֭זְרָח] [מִֽמַּֽעֲרָ֑ב] [הִֽרְחִ֥יק] nós a');
INSERT INTO verses VALUES (15629, 19, 103, 13, '[כְּרַחֵ֣ם] pai sobre [רִחַ֥ם] yhwh yhwh sobre');
INSERT INTO verses VALUES (15630, 19, 103, 14, 'porque saber conheceu [זָ֝כ֗וּר] [כִּי־עָפָ֥ר] porque');
INSERT INTO verses VALUES (15631, 19, 103, 15, '[אֱ֭נוֹשׁ] [כֶּחָצִ֣יר] [יָמָ֑יו] [כְּצִ֥יץ] [הַ֝שָּׂדֶ֗ה] assim [יָצִֽיץ]');
INSERT INTO verses VALUES (15632, 19, 103, 16, 'que espírito [עָֽבְרָה־בּ֣וֹ] nele [וְלֹא־יַכִּירֶ֖נּוּ] e-não [מְקוֹמֽוֹ] ainda [sem-traducao]');
INSERT INTO verses VALUES (15633, 19, 103, 17, '[וְחֶ֤סֶד] yhwh [׀] e-até sobre [עַל־יְרֵאָ֑יו] [וְ֝צִדְקָת֗וֹ] para-os-filhos-de filhos');
INSERT INTO verses VALUES (15634, 19, 103, 18, '[לְשֹׁמְרֵ֥י] [בְרִית֑וֹ] [וּלְזֹכְרֵ֥י] [פִ֝קֻּדָ֗יו] [לַעֲשׂוֹתָֽם]');
INSERT INTO verses VALUES (15635, 19, 103, 19, 'yhwh [בַּ֭שָּׁמַיִם] [הֵכִ֣ין] [כִּסְא֑וֹ] [וּ֝מַלְכוּת֗וֹ] em-todo [מָשָֽׁלָה]');
INSERT INTO verses VALUES (15636, 19, 103, 20, '[בָּרֲכ֥וּ] yhwh [מַלְאָ֫כָ֥יו] [גִּבֹּ֣רֵי] [כֹ֭חַ] [עֹשֵׂ֣י] [דְבָר֑וֹ] [לִ֝שְׁמֹ֗עַ] com-voz [דְּבָרֽוֹ]');
INSERT INTO verses VALUES (15637, 19, 103, 21, '[בָּרֲכ֣וּ] yhwh todo [מְ֝שָׁרְתָ֗יו] [עֹשֵׂ֥י] [רְצוֹנֽוֹ]');
INSERT INTO verses VALUES (15638, 19, 103, 22, '[בָּרֲכ֤וּ] yhwh todo [כָּֽל־מַעֲשָׂ֗יו] em-todo [מֶמְשַׁלְתּ֑וֹ] [בָּרֲכִ֥י] [נַ֝פְשִׁ֗י] [אֶת־יְהוָֽה] a yhwh');
INSERT INTO chapters VALUES (582, 19, 104, 35);
INSERT INTO verses VALUES (15639, 19, 104, 1, '[בָּרֲכִ֥י] [נַפְשִׁ֗י] a yhwh yhwh [גָּדַ֣לְתָּ] [מְּאֹ֑ד] [ה֖וֹד] [וְהָדָ֣ר] [לָבָֽשְׁתָּ]');
INSERT INTO verses VALUES (15640, 19, 104, 2, '[עֹֽטֶה־א֭וֹר] luz [נוֹטֶ֥ה] [שָׁ֝מַ֗יִם] céus');
INSERT INTO verses VALUES (15641, 19, 104, 3, '[הַ֥מְקָרֶֽה] [בַמַּ֗יִם] [עֲ‍ֽלִיּ֫וֹתָ֥יו] [הַשָּׂם־עָבִ֥ים] [רְכוּב֑וֹ] [הַֽ֝מְהַלֵּ֗ךְ] [עַל־כַּנְפֵי־רֽוּחַ] sobre espírito');
INSERT INTO verses VALUES (15642, 19, 104, 4, 'fez [מַלְאָכָ֣יו] [רוּח֑וֹת] [מְ֝שָׁרְתָ֗יו] fogo [לֹהֵֽט]');
INSERT INTO verses VALUES (15643, 19, 104, 5, '[יָֽסַד־אֶ֭רֶץ] terra sobre eternidade não');
INSERT INTO verses VALUES (15644, 19, 104, 6, '[תְּ֭הוֹם] [כַּלְּב֣וּשׁ] [כִּסִּית֑וֹ] sobre [יַ֖עַמְדוּ־מָֽיִם] águas');
INSERT INTO verses VALUES (15645, 19, 104, 7, 'de [יְנוּס֑וּן] [מִן־ק֥וֹל] de voz');
INSERT INTO verses VALUES (15646, 19, 104, 8, '[יַעֲל֣וּ] [הָ֭רִים] [יֵרְד֣וּ] [בְקָע֑וֹת] a [זֶ֤ה] este [יָסַ֬דְתָּ] a-eles');
INSERT INTO verses VALUES (15647, 19, 104, 9, '[גְּֽבוּל־שַׂ֭מְתָּ] [בַּל־יֽ͏ַעֲבֹר֑וּן] não [לְכַסּ֥וֹת] a-terra a-terra');
INSERT INTO verses VALUES (15648, 19, 104, 10, '[הַֽמְשַׁלֵּ֣חַ] [מַ֭עְיָנִים] [בַּנְּחָלִ֑ים] entre [הָ֝רִ֗ים] [יְהַלֵּכֽוּן]');
INSERT INTO verses VALUES (15649, 19, 104, 11, '[יַ֭שְׁקוּ] todo [שָׂדָ֑י] Shaddai [פְרָאִ֣ים] [צְמָאָֽם]');
INSERT INTO verses VALUES (15650, 19, 104, 12, '[עֲ֭לֵיהֶם] [עוֹף־הַשָּׁמַ֣יִם] os-céus [מִבֵּ֥ין] [עֳ֝פָאיִ֗ם] [יִתְּנוּ־קֽוֹל]');
INSERT INTO verses VALUES (15651, 19, 104, 13, '[מַשְׁקֶ֣ה] [הָ֭רִים] [מֵעֲלִיּוֹתָ֑יו] do-fruto-de [מַ֝עֲשֶׂ֗יךָ] [תִּשְׂבַּ֥ע] a-terra');
INSERT INTO verses VALUES (15652, 19, 104, 14, '[מַצְמִ֤יחַ] [חָצִ֨יר] [׀] [לַבְּהֵמָ֗ה] [וְ֭עֵשֶׂב] o-homem o-homem [לְה֥וֹצִיא] pão a-terra');
INSERT INTO verses VALUES (15653, 19, 104, 15, '[וְיַ֤יִן] [׀] [יְשַׂמַּ֬ח] [לְֽבַב־אֱנ֗וֹשׁ] [לְהַצְהִ֣יל] face [מִשָּׁ֑מֶן] [וְ֝לֶ֗חֶם] [לְֽבַב־אֱנ֥וֹשׁ] [יִסְעָֽד]');
INSERT INTO verses VALUES (15654, 19, 104, 16, '[יִ֭שְׂבְּעוּ] árvores-de yhwh [אַֽרְזֵ֥י] [לְ֝בָנ֗וֹן] que [נָטָֽע]');
INSERT INTO verses VALUES (15655, 19, 104, 17, 'que nome [יְקַנֵּ֑נוּ] [חֲ֝סִידָ֗ה] [בְּרוֹשִׁ֥ים] [בֵּיתָֽהּ] casa-de-a-ela');
INSERT INTO verses VALUES (15656, 19, 104, 18, 'os-montes [הַ֭גְּבֹהִים] [לַיְּעֵלִ֑ים] [סְ֝לָעִ֗ים] [מַחְסֶ֥ה] [לַֽשְׁפַנִּֽים]');
INSERT INTO verses VALUES (15657, 19, 104, 19, 'fez [יָ֭רֵחַ] [לְמוֹעֲדִ֑ים] [שֶׁ֝֗מֶשׁ] saber [מְבוֹאֽוֹ]');
INSERT INTO verses VALUES (15658, 19, 104, 20, '[תָּֽשֶׁת־חֹ֭שֶׁךְ] e-seja noite noite [כָּל־חַיְתוֹ־יָֽעַר] todo');
INSERT INTO verses VALUES (15659, 19, 104, 21, '[הַ֭כְּפִירִים] [שֹׁאֲגִ֣ים] [לַטָּ֑רֶף] [וּלְבַקֵּ֖שׁ] [מֵאֵ֣ל] [אָכְלָֽם]');
INSERT INTO verses VALUES (15660, 19, 104, 22, '[תִּזְרַ֣ח] [הַ֭שֶּׁמֶשׁ] [יֵאָסֵפ֑וּן] e-a [יִרְבָּצֽוּן]');
INSERT INTO verses VALUES (15661, 19, 104, 23, '[יֵצֵ֣א] homem [לְפָעֳל֑וֹ] [וְֽלַעֲבֹ֖דָת֣וֹ] ate tarde');
INSERT INTO verses VALUES (15662, 19, 104, 24, '[מָֽה־רַבּ֬וּ] [מַעֲשֶׂ֨יךָ] [׀] yhwh [כֻּ֭לָּם] [בְּחָכְמָ֣ה] [עָשִׂ֑יתָ] [מָלְאָ֥ה] a-terra [קִנְיָנֶֽךָ]');
INSERT INTO verses VALUES (15663, 19, 104, 25, 'este [׀] o-mar [גָּדוֹל֮] [וּרְחַ֢ב] [יָ֫דָ֥יִם] réptil e-não-há [מִסְפָּ֑ר] [חַיּ֥וֹת] [קְ֝טַנּ֗וֹת] com [sem-traducao]');
INSERT INTO verses VALUES (15664, 19, 104, 26, 'nome navios [יְהַלֵּכ֑וּן] [לִ֝וְיָתָ֗ן] este [לְשַֽׂחֶק־בּֽוֹ] [sem-traducao] em-ele');
INSERT INTO verses VALUES (15665, 19, 104, 27, '[כֻּ֭לָּם] a-ti [יְשַׂבֵּר֑וּן] [לָתֵ֖ת] [אָכְלָ֣ם] [בְּעִתּֽוֹ]');
INSERT INTO verses VALUES (15666, 19, 104, 28, '[תִּתֵּ֣ן] a-eles [יִלְקֹט֑וּן] [תִּפְתַּ֥ח] [יָֽ֝דְךָ֗] [יִשְׂבְּע֥וּן] bom');
INSERT INTO verses VALUES (15667, 19, 104, 29, '[תַּסְתִּ֥יר] [פָּנֶיךָ֮] [יִֽבָּהֵ֫ל֥וּן] [תֹּסֵ֣ף] [ר֭וּחָם] [יִגְוָע֑וּן] e-a [יְשׁוּֽבוּ֥ן׃[t]]');
INSERT INTO verses VALUES (15668, 19, 104, 30, '[תְּשַׁלַּ֣ח] [ר֭וּחֲךָ] [יִבָּרֵא֑וּן] [וּ֝תְחַדֵּ֗שׁ] face-de terra');
INSERT INTO verses VALUES (15669, 19, 104, 31, 'haja [כְב֣וֹד] yhwh para-sempre [יִשְׂמַ֖ח] yhwh [בְּמַעֲשָֽׂיו]');
INSERT INTO verses VALUES (15670, 19, 104, 32, '[הַמַּבִּ֣יט] [לָ֭אָרֶץ] [וַתִּרְעָ֑ד] [יִגַּ֖ע] [בֶּהָרִ֣ים] [וְֽיֶעֱשָֽׁנוּ]');
INSERT INTO verses VALUES (15671, 19, 104, 33, '[אָשִׁ֣ירָה] a-yhwh [בְּחַיָּ֑י] [אֲזַמְּרָ֖ה] [לֵאלֹהַ֣י] [בְּעוֹדִֽי]');
INSERT INTO verses VALUES (15672, 19, 104, 34, '[יֶעֱרַ֣ב] sobre-ele [שִׂיחִ֑י] eu [אֶשְׂמַ֥ח] [בַּיהוָֽה]');
INSERT INTO verses VALUES (15673, 19, 104, 35, '[יִתַּ֤מּוּ] [חַטָּאִ֨ים] de a-terra [וּרְשָׁעִ֤ים] ainda [ע֤וֹד] [אֵינָ֗ם] minha-alma a yhwh louvai [sem-traducao]');
INSERT INTO chapters VALUES (583, 19, 105, 45);
INSERT INTO verses VALUES (15674, 19, 105, 1, '[הוֹד֣וּ] [לַ֭יהוָה] [קִרְא֣וּ] [בִשְׁמ֑וֹ] [הוֹדִ֥יעוּ] [בָ֝עַמִּ֗ים] [עֲלִילוֹתָֽיו]');
INSERT INTO verses VALUES (15675, 19, 105, 2, '[שִֽׁירוּ־ל֭וֹ] a-ele [שִׂ֝֗יחוּ] a-ele [sem-traducao] em-todo [sem-traducao]');
INSERT INTO verses VALUES (15676, 19, 105, 3, '[הִֽ֭תְהַלְלוּ] no-nome-de sua-santidade [יִ֝שְׂמַ֗ח] [לֵ֤ב] [׀] yhwh');
INSERT INTO verses VALUES (15677, 19, 105, 4, '[דִּרְשׁ֣וּ] yhwh [וְעֻזּ֑וֹ] [בַּקְּשׁ֖וּ] [פָנָ֣יו] [תָּמִֽיד]');
INSERT INTO verses VALUES (15678, 19, 105, 5, '[זִכְר֗וּ] [נִפְלְאוֹתָ֥יו] que fez [וּמִשְׁפְּטֵי־פִֽיו]');
INSERT INTO verses VALUES (15679, 19, 105, 6, 'semente Abraão seu-servo filhos-de Jacó [בְּחִירָֽיו]');
INSERT INTO verses VALUES (15680, 19, 105, 7, 'ele yhwh nosso-Elohim em-todo a-terra');
INSERT INTO verses VALUES (15681, 19, 105, 8, 'macho para-sempre [בְּרִית֑וֹ] palavra [צִ֝וָּ֗ה] [לְאֶ֣לֶף] [דּֽוֹר]');
INSERT INTO verses VALUES (15682, 19, 105, 9, 'que [כָּ֭רַת] a Abraão [לְיִשְׂחָֽק]');
INSERT INTO verses VALUES (15683, 19, 105, 10, '[וַיַּֽעֲמִידֶ֣הָ] [לְיַעֲקֹ֣ב] [לְחֹ֑ק] [לְ֝יִשְׂרָאֵ֗ל] [בְּרִ֣ית] eternidade');
INSERT INTO verses VALUES (15684, 19, 105, 11, 'dizendo a-ti [אֶתֵּ֥ן] a terra-de assim [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (15685, 19, 105, 12, '[בִּֽ֭הְיוֹתָם] homens-de [מִסְפָּ֑ר] [כִּ֝מְעַ֗ט] [וְגָרִ֥ים] [בָּֽהּ]');
INSERT INTO verses VALUES (15686, 19, 105, 13, '[וַֽ֭יִּתְהַלְּכוּ] [מִגּ֣וֹי] a nação [אֶל־עַ֥ם] a povo');
INSERT INTO verses VALUES (15687, 19, 105, 14, 'não homem homem [וַיּ֖וֹכַח] [עֲלֵיהֶ֣ם] sobre-eles [sem-traducao]');
INSERT INTO verses VALUES (15688, 19, 105, 15, 'a [בִמְשִׁיחָ֑י] [וְ֝לִנְבִיאַי] [אַל־תָּרֵֽעוּ] a');
INSERT INTO verses VALUES (15689, 19, 105, 16, 'E-chamou [רָ֭עָב] sobre a-terra todo');
INSERT INTO verses VALUES (15690, 19, 105, 17, 'enviou [לִפְנֵיהֶ֣ם] homem [לְ֝עֶ֗בֶד] [נִמְכַּ֥ר] [יוֹסֵֽף]');
INSERT INTO verses VALUES (15691, 19, 105, 18, '[עִנּ֣וּ] [בַכֶּ֣בֶל] [*רגליו] [**רַגְל֑וֹ] [בַּ֝רְזֶ֗ל]');
INSERT INTO verses VALUES (15692, 19, 105, 19, 'até tempo [אִמְרַ֖ת] yhwh [צְרָפָֽתְהוּ] yhwh');
INSERT INTO verses VALUES (15693, 19, 105, 20, 'enviou rei [וַיַּתִּירֵ֑הוּ] [מֹשֵׁ֥ל] [עַ֝מִּ֗ים] [וַֽיְפַתְּחֵֽהוּ]');
INSERT INTO verses VALUES (15694, 19, 105, 21, '[שָׂמ֣וֹ] [אָד֣וֹן] [לְבֵית֑וֹ] [וּ֝מֹשֵׁ֗ל] em-todo');
INSERT INTO verses VALUES (15695, 19, 105, 22, '[לֶאְסֹ֣ר] [שָׂרָ֣יו] [בְּנַפְשׁ֑וֹ] [וּזְקֵנָ֥יו] [יְחַכֵּֽם]');
INSERT INTO verses VALUES (15696, 19, 105, 23, 'E-veio Israel Egito [וְ֝יַעֲקֹ֗ב] [גָּ֣ר] [בְּאֶֽרֶץ־חָֽם]');
INSERT INTO verses VALUES (15697, 19, 105, 24, '[וַיֶּ֣פֶר] a muito muito [מִצָּרָֽיו]');
INSERT INTO verses VALUES (15698, 19, 105, 25, 'revolver [לִ֭בָּם] [לִשְׂנֹ֣א] [עַמּ֑וֹ] [לְ֝הִתְנַכֵּ֗ל] [בַּעֲבָדָֽיו]');
INSERT INTO verses VALUES (15699, 19, 105, 26, 'enviou Moisés seu-servo [אַ֝הֲרֹ֗ן] que [בָּֽחַר־בּֽוֹ] em-ele');
INSERT INTO verses VALUES (15700, 19, 105, 27, '[שָֽׂמוּ־בָ֭ם] [דִּבְרֵ֣י] palavras-de [וּ֝מֹפְתִ֗ים] [בְּאֶ֣רֶץ] na-terra');
INSERT INTO verses VALUES (15701, 19, 105, 28, 'enviou escuridão [וַיַּחְשִׁ֑ךְ] e-não [אֶת־*דברוו] a');
INSERT INTO verses VALUES (15702, 19, 105, 29, 'revolver a [לְדָ֑ם] [וַ֝יָּ֗מֶת] E-morreu a');
INSERT INTO verses VALUES (15703, 19, 105, 30, '[שָׁרַ֣ץ] [אַרְצָ֣ם] [צְפַרְדְּעִ֑ים] [בְּ֝חַדְרֵ֗י] [מַלְכֵיהֶֽם]');
INSERT INTO verses VALUES (15704, 19, 105, 31, 'disse E-veio tarde [כִּ֝נִּ֗ים] em-todo');
INSERT INTO verses VALUES (15705, 19, 105, 32, 'dar [גִּשְׁמֵיהֶ֣ם] [בָּרָ֑ד] [אֵ֖שׁ] [לֶהָב֣וֹת] [בְּאַרְצָֽם]');
INSERT INTO verses VALUES (15706, 19, 105, 33, 'e-feriu [גַּ֭פְנָם] [וּתְאֵנָתָ֑ם] [וַ֝יְשַׁבֵּ֗ר] árvore [גְּבוּלָֽם]');
INSERT INTO verses VALUES (15707, 19, 105, 34, 'disse E-veio multiplicarei [וְ֝יֶ֗לֶק] e-não-há [מִסְפָּֽר]');
INSERT INTO verses VALUES (15708, 19, 105, 35, 'e-comeu todo [בְּאַרְצָ֑ם] e-comeu fruto [אַדְמָתָֽם]');
INSERT INTO verses VALUES (15709, 19, 105, 36, 'e-feriu todo [בְּאַרְצָ֑ם] [רֵ֝אשִׁ֗ית] [לְכָל־אוֹנָֽם] para-todo');
INSERT INTO verses VALUES (15710, 19, 105, 37, '[וַֽ֭יּוֹצִיאֵם] [בְּכֶ֣סֶף] [וְזָהָ֑ב] e-nao-ha [בִּשְׁבָטָ֣יו] [כּוֹשֵֽׁל]');
INSERT INTO verses VALUES (15711, 19, 105, 38, '[שָׂמַ֣ח] [מִצְרַ֣יִם] [בְּצֵאתָ֑ם] porque [פַּחְדָּ֣ם] [עֲלֵיהֶֽם] sobre-eles');
INSERT INTO verses VALUES (15712, 19, 105, 39, '[פָּרַ֣שׂ] [עָנָ֣ן] [לְמָסָ֑ךְ] [וְ֝אֵ֗שׁ] para-iluminar noite');
INSERT INTO verses VALUES (15713, 19, 105, 40, '[שָׁאַ֣ל] e-trouxe [שְׂלָ֑ו] [וְלֶ֥חֶם] céus [יַשְׂבִּיעֵֽם]');
INSERT INTO verses VALUES (15714, 19, 105, 41, '[פָּ֣תַח] [צ֭וּר] [וַיָּז֣וּבוּ] águas [הָ֝לְכ֗וּ] [בַּצִּיּ֥וֹת] rio');
INSERT INTO verses VALUES (15715, 19, 105, 42, 'porque macho a palavra sua-santidade a Abraão seu-servo');
INSERT INTO verses VALUES (15716, 19, 105, 43, '[וַיּוֹצִ֣א] [עַמּ֣וֹ] [בְשָׂשׂ֑וֹן] [בְּ֝רִנָּ֗ה] a');
INSERT INTO verses VALUES (15717, 19, 105, 44, 'E-colocou a-eles [אַרְצ֣וֹת] nações [וַעֲמַ֖ל] [לְאֻמִּ֣ים] [יִירָֽשׁוּ]');
INSERT INTO verses VALUES (15718, 19, 105, 45, '[בַּעֲב֤וּר] [׀] [יִשְׁמְר֣וּ] [חֻ֭קָּיו] [וְתוֹרֹתָ֥יו] louvai [הַֽלְלוּ־יָֽהּ]');
INSERT INTO chapters VALUES (584, 19, 106, 48);
INSERT INTO verses VALUES (15719, 19, 106, 1, '[הַֽלְלְויָ֨הּ[c]] a-yhwh porque bom porque que sua-misericórdia');
INSERT INTO verses VALUES (15720, 19, 106, 2, 'quem [יְ֭מַלֵּל] [גְּבוּר֣וֹת] yhwh [יַ֝שְׁמִ֗יעַ] todo voz');
INSERT INTO verses VALUES (15721, 19, 106, 3, '[אַ֭שְׁרֵי] [שֹׁמְרֵ֣י] juízo fez [צְדָקָ֣ה] em-todo');
INSERT INTO verses VALUES (15722, 19, 106, 4, '[זָכְרֵ֣נִי] yhwh [בִּרְצ֣וֹן] [עַמֶּ֑ךָ] [פָּ֝קְדֵ֗נִי] [בִּישׁוּעָתֶֽךָ]');
INSERT INTO verses VALUES (15723, 19, 106, 5, 'para-ver [׀] [בְּט֘וֹבַ֤ת] [בְּחִירֶ֗יךָ] [לִ֭שְׂמֹחַ] [בְּשִׂמְחַ֣ת] [גּוֹיֶ֑ךָ] com [עִם־נַחֲלָתֶֽךָ]');
INSERT INTO verses VALUES (15724, 19, 106, 6, '[חָטָ֥אנוּ] com [הֶעֱוִ֥ינוּ] [הִרְשָֽׁעְנוּ]');
INSERT INTO verses VALUES (15725, 19, 106, 7, '[אֲב֘וֹתֵ֤ינוּ] [בְמִצְרַ֨יִם] não [לֹא־הִשְׂכִּ֬ילוּ] [נִפְלְאוֹתֶ֗יךָ] não [זָ֭כְרוּ] a muito [וַיַּמְר֖וּ] [עַל־יָ֣ם] sobre mar [sem-traducao] juncos');
INSERT INTO verses VALUES (15726, 19, 106, 8, '[וַֽ֭יּוֹשִׁיעֵם] para-que seu-nome [לְ֝הוֹדִ֗יעַ] a');
INSERT INTO verses VALUES (15727, 19, 106, 9, '[וַיִּגְעַ֣ר] [בְּיַם־ס֭וּף] [וֽ͏ַיֶּחֱרָ֑ב] [וַיּוֹלִיכֵ֥ם] [בַּ֝תְּהֹמ֗וֹת] [כַּמִּדְבָּֽר]');
INSERT INTO verses VALUES (15728, 19, 106, 10, '[וַֽ֭יּוֹשִׁיעֵם] da-mão-de [שׂוֹנֵ֑א] [וַ֝יִּגְאָלֵ֗ם] [מִיַּ֥ד] inimigo');
INSERT INTO verses VALUES (15729, 19, 106, 11, '[וַיְכַסּוּ־מַ֥יִם] águas um um não não');
INSERT INTO verses VALUES (15730, 19, 106, 12, '[וַיַּאֲמִ֥ינוּ] [בִדְבָרָ֑יו] [יָ֝שִׁ֗ירוּ] [תְּהִלָּתֽוֹ]');
INSERT INTO verses VALUES (15731, 19, 106, 13, '[מִֽ֭הֲרוּ] [שָׁכְח֣וּ] [מַעֲשָׂ֑יו] não [לַעֲצָתֽוֹ]');
INSERT INTO verses VALUES (15732, 19, 106, 14, '[וַיִּתְאַוּ֣וּ] desejo no-deserto [וַיְנַסּוּ־אֵ֝֗ל] El');
INSERT INTO verses VALUES (15733, 19, 106, 15, 'E-colocou a-eles [שֶׁאֱלָתָ֑ם] [וַיְשַׁלַּ֖ח] [רָז֣וֹן] [בְּנַפְשָֽׁם]');
INSERT INTO verses VALUES (15734, 19, 106, 16, '[וַיְקַנְא֣וּ] [לְ֭מֹשֶׁה] [בַּֽמַּחֲנֶ֑ה] [לְ֝אַהֲרֹ֗ן] santo yhwh');
INSERT INTO verses VALUES (15735, 19, 106, 17, '[תִּפְתַּח־אֶ֭רֶץ] terra [דָּתָ֑ן] [וַ֝תְּכַ֗ס] [עַל־עֲדַ֥ת] sobre');
INSERT INTO verses VALUES (15736, 19, 106, 18, '[וַתִּבְעַר־אֵ֥שׁ] fogo [לֶ֝הָבָ֗ה] [תְּלַהֵ֥ט] [רְשָׁעִֽים] [sem-traducao]');
INSERT INTO verses VALUES (15737, 19, 106, 19, '[יַעֲשׂוּ־עֵ֥גֶל] [בְּחֹרֵ֑ב] [וַ֝יִּשְׁתַּחֲו֗וּ] [לְמַסֵּכָֽה]');
INSERT INTO verses VALUES (15738, 19, 106, 20, '[וַיָּמִ֥ירוּ] a [בְּתַבְנִ֥ית] [שׁ֝֗וֹר] [אֹכֵ֥ל] [עֵֽשֶׂב]');
INSERT INTO verses VALUES (15739, 19, 106, 21, '[שָׁ֭כְחוּ] El [מוֹשִׁיעָ֑ם] fez [גְדֹל֣וֹת] [בְּמִצְרָֽיִם]');
INSERT INTO verses VALUES (15740, 19, 106, 22, '[נִ֭פְלָאוֹת] na-terra [חָ֑ם] [נ֝וֹרָא֗וֹת] sobre mar-de juncos');
INSERT INTO verses VALUES (15741, 19, 106, 23, 'E-disse [לְֽהַשְׁמִ֫ידָ֥ם] [לוּלֵ֡י] Moisés [בְחִיר֗וֹ] ficou-em-pé [בַּפֶּ֣רֶץ] [לְפָנָ֑יו] [לְהָשִׁ֥יב] [חֲ֝מָת֗וֹ] [מֵֽהַשְׁחִֽית]');
INSERT INTO verses VALUES (15742, 19, 106, 24, '[וַֽ֭יִּמְאֲסוּ] na-terra [חֶמְדָּ֑ה] não [לִדְבָרֽוֹ]');
INSERT INTO verses VALUES (15743, 19, 106, 25, '[וַיֵּרָגְנ֥וּ] [בְאָהֳלֵיהֶ֑ם] não [שָׁ֝מְע֗וּ] com-voz yhwh');
INSERT INTO verses VALUES (15744, 19, 106, 26, '[וַיִשָּׂ֣א] sua-mão a-eles [לְהַפִּ֥יל] [א֝וֹתָ֗ם] [בַּמִּדְבָּֽר]');
INSERT INTO verses VALUES (15745, 19, 106, 27, '[וּלְהַפִּ֣יל] [זַ֭רְעָם] [בַּגּוֹיִ֑ם] [וּ֝לְזָרוֹתָ֗ם] [בָּאֲרָצֽוֹת]');
INSERT INTO verses VALUES (15746, 19, 106, 28, '[וַ֭יִּצָּ֣מְדוּ] [לְבַ֣עַל] [פְּע֑וֹר] [וַ֝יֹּאכְל֗וּ] [זִבְחֵ֥י] [מֵתִֽים]');
INSERT INTO verses VALUES (15747, 19, 106, 29, '[וַ֭יַּכְעִיסוּ] [בְּמַֽעַלְלֵיהֶ֑ם] [וַתִּפְרָץ־בָּ֝֗ם] [מַגֵּפָֽה]');
INSERT INTO verses VALUES (15748, 19, 106, 30, '[וַיַּעֲמֹ֣ד] [פִּֽ֭ינְחָס] [וַיְפַלֵּ֑ל] [וַ֝תֵּעָצַ֗ר] [הַמַּגֵּפָֽה]');
INSERT INTO verses VALUES (15749, 19, 106, 31, '[וַתֵּחָ֣שֶׁב] a-ele [לִצְדָקָ֑ה] [לְדֹ֥ר] [וָ֝דֹ֗ר] até eternidade');
INSERT INTO verses VALUES (15750, 19, 106, 32, '[וַ֭יַּקְצִיפוּ] sobre [מְרִיבָ֑ה] [וַיֵּ֥רַע] [לְ֝מֹשֶׁ֗ה] [בַּעֲבוּרָֽם] por-elas');
INSERT INTO verses VALUES (15751, 19, 106, 33, 'porque [אֶת־רוּח֑וֹ] a [בִּשְׂפָתָֽיו]');
INSERT INTO verses VALUES (15752, 19, 106, 34, 'não [אֶת־הָֽעַמִּ֑ים] a disse yhwh a-eles yhwh');
INSERT INTO verses VALUES (15753, 19, 106, 35, '[וַיִּתְעָרְב֥וּ] [בַגּוֹיִ֑ם] [וַֽ֝יִּלְמְד֗וּ] [מַֽעֲשֵׂיהֶֽם]');
INSERT INTO verses VALUES (15754, 19, 106, 36, '[וַיַּעַבְד֥וּ] a [וַיִּהְי֖וּ] a-eles [לְמוֹקֵֽשׁ] para-laço');
INSERT INTO verses VALUES (15755, 19, 106, 37, '[וַיִּזְבְּח֣וּ] a [וְאֶת־בְּנֽוֹתֵיהֶ֗ם] e-[OBJ]');
INSERT INTO verses VALUES (15756, 19, 106, 38, '[וַיִּֽשְׁפְּכ֨וּ] [דָ֪ם] [נָקִ֡י] [דַּם־בְּנֵ֘יהֶ֤ם] [וּֽבְנוֹתֵיהֶ֗ם] [אֲשֶׁ֣ר] que [לַעֲצַבֵּ֣י] [כְנָ֑עַן] [וַתֶּחֱנַ֥ף] a-terra a-terra');
INSERT INTO verses VALUES (15757, 19, 106, 39, '[וַיִּטְמְא֥וּ] [בְמַעֲשֵׂיהֶ֑ם] [וַ֝יִּזְנ֗וּ] [בְּמַ֥עַלְלֵיהֶֽם]');
INSERT INTO verses VALUES (15758, 19, 106, 40, '[וַיִּֽחַר־אַ֣ף] yhwh yhwh [וַ֝יְתָעֵ֗ב] [אֶת־נַחֲלָתֽוֹ] a herança-dele');
INSERT INTO verses VALUES (15759, 19, 106, 41, '[וַיִּתְּנֵ֥ם] pela-mão-de nações [בָ֝הֶ֗ם] [שֹׂנְאֵיהֶֽם] [sem-traducao]');
INSERT INTO verses VALUES (15760, 19, 106, 42, '[וַיִּלְחָצ֥וּם] [אוֹיְבֵיהֶ֑ם] [וַ֝יִּכָּנְע֗וּ] debaixo [יָדָֽם]');
INSERT INTO verses VALUES (15761, 19, 106, 43, '[פְּעָמִ֥ים] [רַבּ֗וֹת] [יַצִּ֫ילֵ֥ם] [וְ֭הֵמָּה] [יַמְר֣וּ] [בַעֲצָתָ֑ם] [וַ֝יָּמֹ֗כּוּ] [בַּעֲוֺנָֽם]');
INSERT INTO verses VALUES (15762, 19, 106, 44, 'E-viu [בַּצַּ֣ר] a-eles [בְּ֝שָׁמְע֗וֹ] a');
INSERT INTO verses VALUES (15763, 19, 106, 45, '[וַיִּזְכֹּ֣ר] a-eles [בְּרִית֑וֹ] [וַ֝יִּנָּחֵ֗ם] [כְּרֹ֣ב]');
INSERT INTO verses VALUES (15764, 19, 106, 46, 'E-colocou [אוֹתָ֣ם] [לְרַחֲמִ֑ים] [לִ֝פְנֵ֗י] todo');
INSERT INTO verses VALUES (15765, 19, 106, 47, '[הוֹשִׁיעֵ֨נוּ] yhwh yhwh [Elohim] de [מִֽן־הַגּ֫וֹיִ֥ם] [לְ֭הֹדוֹת] [לְשֵׁ֣ם] [קָדְשֶׁ֑ךָ] [לְ֝הִשְׁתַּבֵּ֗חַ] [בִּתְהִלָּתֶֽךָ]');
INSERT INTO verses VALUES (15766, 19, 106, 48, 'yhwh [אֱלֹהֵ֪י] Israel de [׀] [וְעַ֬ד] [הָעוֹלָ֗ם] [וְאָמַ֖ר] todo [אָמֵ֗ן] [הַֽלְלוּ־יָֽהּ] louvai [sem-traducao]');
INSERT INTO chapters VALUES (585, 19, 107, 43);
INSERT INTO verses VALUES (15767, 19, 107, 1, '[הֹד֣וּ] a-yhwh porque que porque para-sempre sua-misericórdia');
INSERT INTO verses VALUES (15768, 19, 107, 2, '[יֹ֭אמְרוּ] [גְּאוּלֵ֣י] yhwh que [גְּ֝אָלָ֗ם] [מִיַּד־צָֽר]');
INSERT INTO verses VALUES (15769, 19, 107, 3, '[וּֽמֵאֲרָצ֗וֹת] [קִ֫בְּצָ֥ם] [מִמִּזְרָ֥ח] [וּמִֽמַּעֲרָ֑ב] [מִצָּפ֥וֹן] [וּמִיָּֽם]');
INSERT INTO verses VALUES (15770, 19, 107, 4, '[תָּע֣וּ] [בַ֭מִּדְבָּר] [בִּישִׁימ֣וֹן] caminho cidade [מ֝וֹשָׁ֗ב] não [מָצָֽאוּ]');
INSERT INTO verses VALUES (15771, 19, 107, 5, '[רְעֵבִ֥ים] também [נַ֝פְשָׁ֗ם] [בָּהֶ֥ם] [תִּתְעַטָּֽף]');
INSERT INTO verses VALUES (15772, 19, 107, 6, '[וַיִּצְעֲק֣וּ] a yhwh a-eles a-eles [יַצִּילֵֽם]');
INSERT INTO verses VALUES (15773, 19, 107, 7, '[וַ֭יּֽ͏ַדְרִיכֵם] no-caminho [יְשָׁרָ֑ה] [לָ֝לֶ֗כֶת] a cidade');
INSERT INTO verses VALUES (15774, 19, 107, 8, '[יוֹד֣וּ] a-yhwh sua-benignidade [וְ֝נִפְלְאוֹתָ֗יו] para-os-filhos-de homem');
INSERT INTO verses VALUES (15775, 19, 107, 9, 'porque [נֶ֣פֶשׁ] alma [וְנֶ֥פֶשׁ] [רְ֝עֵבָה] [מִלֵּא־טֽוֹב] bom');
INSERT INTO verses VALUES (15776, 19, 107, 10, '[יֹ֭שְׁבֵי] escuridão [וְצַלְמָ֑וֶת] [אֲסִירֵ֖י] [עֳנִ֣י] [וּבַרְזֶֽל]');
INSERT INTO verses VALUES (15777, 19, 107, 11, 'porque [אִמְרֵי־אֵ֑ל] palavras-de El [נָאָֽצוּ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (15778, 19, 107, 12, '[וַיַּכְנַ֣ע] [בֶּעָמָ֣ל] [לִבָּ֑ם] [כָּ֝שְׁל֗וּ] e-não-há [עֹזֵֽר]');
INSERT INTO verses VALUES (15779, 19, 107, 13, '[וַיִּזְעֲק֣וּ] a yhwh a-eles a-eles [יוֹשִׁיעֵֽם]');
INSERT INTO verses VALUES (15780, 19, 107, 14, '[יֽ֭וֹצִיאֵם] [מֵחֹ֣שֶׁךְ] [וְצַלְמָ֑וֶת] [וּמוֹסְר֖וֹתֵיהֶ֣ם] [יְנַתֵּֽק]');
INSERT INTO verses VALUES (15781, 19, 107, 15, '[יוֹד֣וּ] a-yhwh sua-benignidade [וְ֝נִפְלְאוֹתָ֗יו] para-os-filhos-de homem');
INSERT INTO verses VALUES (15782, 19, 107, 16, 'porque [דַּלְת֣וֹת] [נְחֹ֑שֶׁת] bronze [בַרְזֶ֣ל] [גִּדֵּֽעַ]');
INSERT INTO verses VALUES (15783, 19, 107, 17, '[אֱ֭וִלִים] [מִדֶּ֣רֶךְ] [פִּשְׁעָ֑ם] [וּֽ֝מֵעֲוֺ֥נֹתֵיהֶ֗ם[t]]');
INSERT INTO verses VALUES (15784, 19, 107, 18, 'todo [תְּתַעֵ֣ב] [נַפְשָׁ֑ם] [וַ֝יַּגִּ֗יעוּ] [עַד־שַׁ֥עֲרֵי] até');
INSERT INTO verses VALUES (15785, 19, 107, 19, '[וַיִּזְעֲק֣וּ] a yhwh a-eles a-eles [יוֹשִׁיעֵֽם]');
INSERT INTO verses VALUES (15786, 19, 107, 20, '[יִשְׁלַ֣ח] [דְּ֭בָרוֹ] [וְיִרְפָּאֵ֑ם] [וִֽ֝ימַלֵּ֗ט] [מִשְּׁחִיתוֹתָֽם׃]');
INSERT INTO verses VALUES (15787, 19, 107, 21, '[יוֹד֣וּ] a-yhwh sua-benignidade [וְ֝נִפְלְאוֹתָ֗יו] para-os-filhos-de homem');
INSERT INTO verses VALUES (15788, 19, 107, 22, '[וְ֭יִזְבְּחוּ] sacrificios-de [תוֹדָ֑ה] [וִֽיסַפְּר֖וּ] [מַעֲשָׂ֣יו] [בְּרִנָּֽה׃]');
INSERT INTO verses VALUES (15789, 19, 107, 23, '[יוֹרְדֵ֣י] o-mar [בָּאֳנִיּ֑וֹת] [עֹשֵׂ֥י] obra [בְּמַ֣יִם] [רַבִּֽים׃]');
INSERT INTO verses VALUES (15790, 19, 107, 24, '[הֵ֣מָּה] [רָ֭אוּ] [מַעֲשֵׂ֣י] yhwh [וְ֝נִפְלְאוֹתָ֗יו] [בִּמְצוּלָֽה׃]');
INSERT INTO verses VALUES (15791, 19, 107, 25, 'E-disse [וַֽ֭יַּעֲמֵד] espírito [סְעָרָ֑ה] [וַתְּרוֹמֵ֥ם] [גַּלָּֽיו׃]');
INSERT INTO verses VALUES (15792, 19, 107, 26, '[יַעֲל֣וּ] céus [יֵרְד֣וּ] [תְהוֹמ֑וֹת] [נַ֝פְשָׁ֗ם] [בְּרָעָ֥ה] [תִתְמוֹגָֽג]');
INSERT INTO verses VALUES (15793, 19, 107, 27, '[יָח֣וֹגּוּ] [וְ֭יָנוּעוּ] [כַּשִּׁכּ֑וֹר] e-todo [תִּתְבַּלָּֽע]');
INSERT INTO verses VALUES (15794, 19, 107, 28, '[וַיִּצְעֲק֣וּ] a yhwh a-eles a-eles [יוֹצִיאֵֽם]');
INSERT INTO verses VALUES (15795, 19, 107, 29, '[יָקֵ֣ם] [סְ֭עָרָה] [לִדְמָמָ֑ה] [וַ֝יֶּחֱשׁ֗וּ] [גַּלֵּיהֶֽם]');
INSERT INTO verses VALUES (15796, 19, 107, 30, '[וַיִּשְׂמְח֥וּ] porque [וַ֝יַּנְחֵ֗ם] [אֶל־מְח֥וֹז] a');
INSERT INTO verses VALUES (15797, 19, 107, 31, '[יוֹד֣וּ] a-yhwh sua-benignidade [וְ֝נִפְלְאוֹתָ֗יו] para-os-filhos-de homem');
INSERT INTO verses VALUES (15798, 19, 107, 32, '[וִֽ֭ירֹמְמוּהוּ] [בִּקְהַל־עָ֑ם] povo [זְקֵנִ֣ים] [יְהַלְלֽוּהוּ]');
INSERT INTO verses VALUES (15799, 19, 107, 33, '[יָשֵׂ֣ם] [נְהָר֣וֹת] [לְמִדְבָּ֑ר] [וּמֹצָ֥אֵי] águas [לְצִמָּאֽוֹן]');
INSERT INTO verses VALUES (15800, 19, 107, 34, 'terra fruto [לִמְלֵחָ֑ה] [מֵ֝רָעַ֗ת] [יֹ֣שְׁבֵי] nela');
INSERT INTO verses VALUES (15801, 19, 107, 35, '[יָשֵׂ֣ם] [מִ֭דְבָּר] [לַֽאֲגַם־מַ֑יִם] águas [צִ֝יָּ֗ה] [לְמֹצָ֥אֵי] [מָֽיִם] águas');
INSERT INTO verses VALUES (15802, 19, 107, 36, '[וַיּ֣וֹשֶׁב] nome [רְעֵבִ֑ים] [וַ֝יְכוֹנְנ֗וּ] cidade [מוֹשָֽׁב]');
INSERT INTO verses VALUES (15803, 19, 107, 37, '[וַיִּזְרְע֣וּ] [שָׂ֭דוֹת] [וַיִּטְּע֣וּ] [כְרָמִ֑ים] [וַ֝יַּעֲשׂ֗וּ] fruto [תְבֽוּאָה]');
INSERT INTO verses VALUES (15804, 19, 107, 38, '[וַיְבָרֲכֵ֣ם] [וַיִּרְבּ֣וּ] muito [וּ֝בְהֶמְתָּ֗ם] não [יַמְעִֽיט]');
INSERT INTO verses VALUES (15805, 19, 107, 39, '[וַיִּמְעֲט֥וּ] [וַיָּשֹׁ֑חוּ] [מֵעֹ֖צֶר] [רָעָ֣ה] [וְיָגֽוֹן׃]');
INSERT INTO verses VALUES (15806, 19, 107, 40, '[שֹׁפֵ֣ךְ] [בּ֭וּז] sobre [וַ֝יַּתְעֵ֗ם] [בְּתֹ֣הוּ] [לֹא־דָֽרֶךְ] não caminho');
INSERT INTO verses VALUES (15807, 19, 107, 41, '[וַיְשַׂגֵּ֣ב] [אֶבְי֣וֹן] [מֵע֑וֹנִי] [וַיָּ֥שֶׂם] [כַּ֝צֹּ֗אן] [מִשְׁפָּחֽוֹת]');
INSERT INTO verses VALUES (15808, 19, 107, 42, 'temerao [יְשָׁרִ֣ים] [וְיִשְׂמָ֑חוּ] e-todo [קָ֣פְצָה] [פִּֽיהָ] boca-dela');
INSERT INTO verses VALUES (15809, 19, 107, 43, '[מִי־חָכָ֥ם] [וְיִשְׁמָר־אֵ֑לֶּה] [וְ֝יִתְבּֽוֹנְנ֗וּ] estes yhwh yhwh');
INSERT INTO chapters VALUES (586, 19, 108, 14);
INSERT INTO verses VALUES (15810, 19, 108, 1, '[שִׁ֖יר] [מִזְמ֣וֹר] de-Davi');
INSERT INTO verses VALUES (15811, 19, 108, 2, 'firme [לִבִּ֣י] Elohim [אָשִׁ֥ירָה] [וַ֝אֲזַמְּרָ֗ה] também [sem-traducao]');
INSERT INTO verses VALUES (15812, 19, 108, 3, '[ע֭וּרָֽה] [הַנֵּ֥בֶל] [וְכִנּ֗וֹר] [אָעִ֥ירָה] [שָּֽׁחַר]');
INSERT INTO verses VALUES (15813, 19, 108, 4, '[אוֹדְךָ֖] [בָעַמִּ֥ים] yhwh yhwh não [בַּל־אֻמִּֽים]');
INSERT INTO verses VALUES (15814, 19, 108, 5, 'porque grande [חַסְדֶּ֑ךָ] céus [אֲמִתֶּֽךָ] e-até [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (15815, 19, 108, 6, '[ר֣וּמָה] sobre ceus Elohim e-sobre todo a-terra');
INSERT INTO verses VALUES (15816, 19, 108, 7, 'a-fim-de [יֵחָלְצ֣וּן] [יְדִידֶ֑יךָ] [הוֹשִׁ֖יעָה] [יְמִֽינְךָ֣] [וַעֲנֵֽנִי]');
INSERT INTO verses VALUES (15817, 19, 108, 8, 'Elohim palavra [דִּבֶּ֥ר] [בְּקָדְשׁ֗וֹ] [אֶ֫עְלֹ֥זָה] [אֲחַלְּקָ֥ה] [שְׁכֶ֑ם] [וְעֵ֖מֶק] [סֻכּ֣וֹת]');
INSERT INTO verses VALUES (15818, 19, 108, 9, 'a-mim [גִלְעָ֨ד] a-mim [לִ֤י] [מְנַשֶּׁ֗ה] [וְ֭אֶפְרַיִם] [מָע֣וֹז] [רֹאשִׁ֑י] [יְ֝הוּדָ֗ה]');
INSERT INTO verses VALUES (15819, 19, 108, 10, '[מוֹאָ֤ב] [׀] [סִ֬יר] sobre [עַל־אֱ֭דוֹם] [אַשְׁלִ֣יךְ] [נַעֲלִ֑י] [עֲלֵֽי־פְ֝לֶ֗שֶׁת] [אֶתְרוֹעָֽע]');
INSERT INTO verses VALUES (15820, 19, 108, 11, 'quem [יֹ֭בִלֵנִי] cidade [מִבְצָ֑ר] quem [נָחַ֣נִי] até Edom');
INSERT INTO verses VALUES (15821, 19, 108, 12, 'acaso-nao Elohim [וְֽלֹא־תֵצֵ֥א] e-não [בְּצִבְאֹתֵֽינוּ] Elohim [sem-traducao]');
INSERT INTO verses VALUES (15822, 19, 108, 13, '[הָֽבָה־לָּ֣נוּ] [עֶזְרָ֣ת] [מִצָּ֑ר] [וְ֝שָׁ֗וְא] [תְּשׁוּעַ֥ת] homem homem');
INSERT INTO verses VALUES (15823, 19, 108, 14, '[בֵּֽאלֹהִ֥ים] [נַעֲשֶׂה־חָ֑יִל] [וְ֝ה֗וּא] [יָב֥וּס] [צָרֵֽינוּ]');
INSERT INTO chapters VALUES (587, 19, 109, 31);
INSERT INTO verses VALUES (15824, 19, 109, 1, '[לַ֭מְנַצֵּחַ] a-Davi [מִזְמ֑וֹר] Elohim-de [תְ֝הִלָּתִ֗י] a [sem-traducao]');
INSERT INTO verses VALUES (15825, 19, 109, 2, 'que [פִ֪י] [רָשָׁ֡ע] [וּֽפִי־מִ֭רְמָה] [עָלַ֣י] sobre-mim [דִּבְּר֥וּ] [אִ֝תִּ֗י] [לְשׁ֣וֹן] língua-de mentira');
INSERT INTO verses VALUES (15826, 19, 109, 3, '[וְדִבְרֵ֣י] [שִׂנְאָ֣ה] [סְבָב֑וּנִי] [וַיִּֽלָּחֲמ֥וּנִי] [חִנָּֽם]');
INSERT INTO verses VALUES (15827, 19, 109, 4, '[תַּֽחַת־אַהֲבָתִ֥י] [יִשְׂטְנ֗וּנִי] [וַאֲנִ֥י] [תְפִלָּֽה]');
INSERT INTO verses VALUES (15828, 19, 109, 5, '[וַיָּ֘שִׂ֤ימוּ] sobre-mim [רָ֭עָה] debaixo boa [וְ֝שִׂנְאָ֗ה] debaixo [אַהֲבָתִֽי]');
INSERT INTO verses VALUES (15829, 19, 109, 6, '[הַפְקֵ֣ד] sobre-ele ímpio [וְ֝שָׂטָ֗ן] [יַעֲמֹ֥ד] sobre direita-de-ele');
INSERT INTO verses VALUES (15830, 19, 109, 7, '[בְּ֭הִשָּׁ֣פְטוֹ] [יֵצֵ֣א] ímpio [ו֝תְפִלָּת֗וֹ] será [לַֽחֲטָאָֽה]');
INSERT INTO verses VALUES (15831, 19, 109, 8, '[יִֽהְיֽוּ־יָמָ֥יו] [מְעַטִּ֑ים] [פְּ֝קֻדָּת֗וֹ] [יִקַּ֥ח] [אַחֵֽר] outro');
INSERT INTO verses VALUES (15832, 19, 109, 9, 'serao [יְתוֹמִ֑ים] [וְ֝אִשְׁתּוֹ] [אַלְמָנָֽה] [sem-traducao]');
INSERT INTO verses VALUES (15833, 19, 109, 10, '[וְנ֤וֹעַ] [יָנ֣וּעוּ] [בָנָ֣יו] [וְשִׁאֵ֑לוּ] [וְ֝דָרְשׁ֗וּ] [מֵחָרְבוֹתֵיהֶֽם]');
INSERT INTO verses VALUES (15834, 19, 109, 11, '[יְנַקֵּ֣שׁ] [נ֭וֹשֶׁה] para-todo que a-ele [יְגִיעֽוֹ]');
INSERT INTO verses VALUES (15835, 19, 109, 12, 'a seja a-ele [וְֽאַל־יְהִ֥י] [ח֝וֹנֵ֗ן] e-a seja [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (15836, 19, 109, 13, '[יְהִֽי־אַחֲרִית֥וֹ] [לְהַכְרִ֑ית] [בְּד֥וֹר] [אַ֝חֵ֗ר] [יִמַּ֥ח] [שְׁמָֽם]');
INSERT INTO verses VALUES (15837, 19, 109, 14, '[יִזָּכֵ֤ר] iniquidade [עֲוֺ֣ן] a yhwh [וְחַטַּ֥את] sua-mãe a');
INSERT INTO verses VALUES (15838, 19, 109, 15, 'serão [נֶֽגֶד־יְהוָ֣ה] yhwh [וְיַכְרֵ֖ת] [מֵאֶ֣רֶץ] da-terra');
INSERT INTO verses VALUES (15839, 19, 109, 16, 'porque [אֲשֶׁ֤ר] não não [זָכַר֮] [עֲשׂ֢וֹת] [חָ֥סֶד] homem-de afligido [וְ֭אֶבְיוֹן] [וְנִכְאֵ֨ה] [לֵבָ֬ב] [לְמוֹתֵֽת]');
INSERT INTO verses VALUES (15840, 19, 109, 17, '[וַיֶּאֱהַ֣ב] [קְ֭לָלָה] [וַתְּבוֹאֵ֑הוּ] e-não [בִּ֝בְרָכָ֗ה] [וַתִּרְחַ֥ק] nós de-nós');
INSERT INTO verses VALUES (15841, 19, 109, 18, '[וַיִּלְבַּ֥שׁ] [קְלָלָ֗ה] [כְּמַ֫דּ֥וֹ] [וַתָּבֹ֣א] [כַמַּ֣יִם] [בְּקִרְבּ֑וֹ] [וְ֝כַשֶּׁ֗מֶן] [בְּעַצְמוֹתָֽיו]');
INSERT INTO verses VALUES (15842, 19, 109, 19, '[תְּהִי־ל֭וֹ] a-ele [יַעְטֶ֑ה] [וּ֝לְמֵ֗זַח] [תָּמִ֥יד] [יַחְגְּרֶֽהָ] [sem-traducao]');
INSERT INTO verses VALUES (15843, 19, 109, 20, 'esta [פְּעֻלַּ֣ת] [שֹׂ֭טְנַי] de-junto-de yhwh [וְהַדֹּבְרִ֥ים] mal sobre alma-de-mim');
INSERT INTO verses VALUES (15844, 19, 109, 21, '[וְאַתָּ֤ה] yhwh Adonai [Adonai] [עֲ‍ֽשֵׂה־אִ֭תִּי] para-que [שְׁמֶ֑ךָ] porque bom [הַצִּילֵֽנִי]');
INSERT INTO verses VALUES (15845, 19, 109, 22, 'porque afligido eu [וְ֝לִבִּ֗י] [חָלַ֥ל] [בְּקִרְבִּֽי]');
INSERT INTO verses VALUES (15846, 19, 109, 23, '[כְּצֵל־כִּנְטוֹת֥וֹ] [נֶהֱלָ֑כְתִּי] [נִ֝נְעַ֗רְתִּי] [כָּֽאַרְבֶּֽה]');
INSERT INTO verses VALUES (15847, 19, 109, 24, '[בִּ֭רְכַּי] [כָּשְׁל֣וּ] [מִצּ֑וֹם] [וּ֝בְשָׂרִ֗י] [כָּחַ֥שׁ] [מִשָּֽׁמֶן]');
INSERT INTO verses VALUES (15848, 19, 109, 25, 'e-eu eu-fui [הָיִ֣יתִי] a-eles a-eles [יִ֝רְא֗וּנִי] [יְנִיע֥וּן]');
INSERT INTO verses VALUES (15849, 19, 109, 26, '[עָ֭זְרֵנִי] yhwh meu-Elohim [ה֖וֹשִׁיעֵ֣נִי] [כְחַסְדֶּֽךָ]');
INSERT INTO verses VALUES (15850, 19, 109, 27, '[וְֽ֭יֵדְעוּ] porque [זֹּ֑את] tu yhwh yhwh');
INSERT INTO verses VALUES (15851, 19, 109, 28, '[יְקַֽלְלוּ־הֵמָּה֮] [וְאַתָּ֢ה] [תְבָ֫רֵ֥ךְ] [קָ֤מוּ] [׀] [וַיֵּבֹ֗שׁוּ] [וְֽעַבְדְּךָ֥] [יִשְׂמָֽח]');
INSERT INTO verses VALUES (15852, 19, 109, 29, '[יִלְבְּשׁ֣וּ] [שׂוֹטְנַ֣י] [כְּלִמָּ֑ה] [וְיַעֲט֖וּ] [כַמְעִ֣יל] [בָּשְׁתָּֽם]');
INSERT INTO verses VALUES (15853, 19, 109, 30, '[א֘וֹדֶ֤ה] yhwh muito [בְּפִ֑י] [וּבְת֖וֹךְ] [רַבִּ֣ים] [אֲהַֽלְלֶֽנּוּ]');
INSERT INTO verses VALUES (15854, 19, 109, 31, 'porque [לִימִ֣ין] [אֶבְי֑וֹן] pobre [מִשֹּׁפְטֵ֥י] [נַפְשֽׁוֹ] [sem-traducao]');
INSERT INTO chapters VALUES (588, 19, 110, 7);
INSERT INTO verses VALUES (15855, 19, 110, 1, '[לְדָוִ֗ד] [מִ֫זְמ֥וֹר] oráculo-de yhwh [׀] retornou [שֵׁ֥ב] até [עַד־אָשִׁ֥ית] [אֹ֝יְבֶ֗יךָ] [הֲדֹ֣ם] [לְרַגְלֶֽיךָ]');
INSERT INTO verses VALUES (15856, 19, 110, 2, '[מַטֵּֽה־עֻזְּךָ֗] [יִשְׁלַ֣ח] yhwh yhwh [רְ֝דֵ֗ה] dominai [אֹיְבֶֽיךָ]');
INSERT INTO verses VALUES (15857, 19, 110, 3, 'teu-povo [נְדָבֹת֮] [בְּי֢וֹם] [חֵ֫ילֶ֥ךָ] [בְּֽהַדְרֵי־קֹ֭דֶשׁ] [מֵרֶ֣חֶם] [מִשְׁחָ֑ר] a-ti [טַ֣ל] [יַלְדֻתֶֽיךָ]');
INSERT INTO verses VALUES (15858, 19, 110, 4, '[נִשְׁבַּ֤ע] yhwh e-não [וְלֹ֥א] [יִנָּחֵ֗ם] sacerdote para-sempre sobre [מַלְכִּי־צֶֽדֶק]');
INSERT INTO verses VALUES (15859, 19, 110, 5, 'Adonai sobre [מָחַ֖ץ] [בְּיוֹם־אַפּ֣וֹ] [מְלָכִֽים]');
INSERT INTO verses VALUES (15860, 19, 110, 6, '[יָדִ֣ין] [בַּ֭גּוֹיִם] enchei [גְוִיּ֑וֹת] [מָ֥חַץ] cabeça sobre terra multiplicai');
INSERT INTO verses VALUES (15861, 19, 110, 7, '[מִ֭נַּחַל] [בַּדֶּ֣רֶךְ] [יִשְׁתֶּ֑ה] sobre [יָרִ֥ים] [רֹֽאשׁ] cabeça');
INSERT INTO chapters VALUES (589, 19, 111, 10);
INSERT INTO verses VALUES (15862, 19, 111, 1, 'louvai [יָ֨הּ] [׀] yhwh yhwh [בְּכָל־לֵבָ֑ב] [בְּס֖וֹד] [יְשָׁרִ֣ים] [וְעֵדָֽה]');
INSERT INTO verses VALUES (15863, 19, 111, 2, '[גְּ֭דֹלִים] [מַעֲשֵׂ֣י] yhwh [דְּ֝רוּשִׁ֗ים] para-todo');
INSERT INTO verses VALUES (15864, 19, 111, 3, '[הוֹד־וְהָדָ֥ר] [פָּֽעֳל֑וֹ] [וְ֝צִדְקָת֗וֹ] [עֹמֶ֥דֶת] [לָעַֽד]');
INSERT INTO verses VALUES (15865, 19, 111, 4, 'macho fez [לְנִפְלְאֹתָ֑יו] [חַנּ֖וּן] [וְרַח֣וּם] yhwh');
INSERT INTO verses VALUES (15866, 19, 111, 5, '[טֶ֭רֶף] dar [לִֽירֵאָ֑יו] [יִזְכֹּ֖ר] para-sempre [בְּרִיתֽוֹ]');
INSERT INTO verses VALUES (15867, 19, 111, 6, '[כֹּ֣חַ] [מַ֭עֲשָׂיו] declarou [לְעַמּ֑וֹ] [לָתֵ֥ת] a-eles [נַחֲלַ֥ת] [גּוֹיִֽם]');
INSERT INTO verses VALUES (15868, 19, 111, 7, '[מַעֲשֵׂ֣י] [יָ֭דָיו] [אֱמֶ֣ת] [וּמִשְׁפָּ֑ט] [נֶ֝אֱמָנִ֗ים] todo');
INSERT INTO verses VALUES (15869, 19, 111, 8, '[סְמוּכִ֣ים] [לָעַ֣ד] para-sempre [עֲ֝שׂוּיִ֗ם] [בֶּאֱמֶ֥ת] [וְיָשָֽׁר]');
INSERT INTO verses VALUES (15870, 19, 111, 9, '[פְּד֤וּת] enviou [שָׁ֘לַ֤ח] [לְעַמּ֗וֹ] [צִוָּֽה־לְעוֹלָ֥ם] [בְּרִית֑וֹ] santo [וְנוֹרָ֣א] [שְׁמֽוֹ]');
INSERT INTO verses VALUES (15871, 19, 111, 10, '[רֵ֘אשִׁ֤ית] [חָכְמָ֨ה] [׀] yhwh yhwh bom bom [לְכָל־עֹשֵׂיהֶ֑ם] [תְּ֝הִלָּת֗וֹ] [עֹמֶ֥דֶת] [לָעַֽד]');
INSERT INTO chapters VALUES (590, 19, 112, 10);
INSERT INTO verses VALUES (15872, 19, 112, 1, 'louvai [יָ֨הּ] [׀] homem temer a yhwh [חָפֵ֥ץ] muito muito');
INSERT INTO verses VALUES (15873, 19, 112, 2, '[גִּבּ֣וֹר] [בָּ֭אָרֶץ] será sua-semente [דּ֖וֹר] [יְשָׁרִ֣ים] [יְבֹרָֽךְ]');
INSERT INTO verses VALUES (15874, 19, 112, 3, '[הוֹן־וָעֹ֥שֶׁר] [בְּבֵית֑וֹ] [וְ֝צִדְקָת֗וֹ] [עֹמֶ֥דֶת] [לָעַֽד]');
INSERT INTO verses VALUES (15875, 19, 112, 4, '[זָ֘רַ֤ח] [בַּחֹ֣שֶׁךְ] luz [לַיְשָׁרִ֑ים] [חַנּ֖וּן] [וְרַח֣וּם] [וְצַדִּֽיק]');
INSERT INTO verses VALUES (15876, 19, 112, 5, '[טֽוֹב־אִ֭ישׁ] homem [וּמַלְוֶ֑ה] [יְכַלְכֵּ֖ל] [דְּבָרָ֣יו] [בְּמִשְׁפָּֽט]');
INSERT INTO verses VALUES (15877, 19, 112, 6, 'porque [לֹא־יִמּ֑וֹט] não eternidade será [צַדִּֽיק]');
INSERT INTO verses VALUES (15878, 19, 112, 7, '[מִשְּׁמוּעָ֣ה] [רָ֭עָה] não [יִירָ֑א] [נָכ֥וֹן] [לִ֝בּ֗וֹ] [בָּטֻ֥חַ] [בַּיהוָֽה]');
INSERT INTO verses VALUES (15879, 19, 112, 8, '[סָמ֣וּךְ] [לִ֭בּוֹ] não [יִירָ֑א] até que [בְצָרָֽיו]');
INSERT INTO verses VALUES (15880, 19, 112, 9, '[פִּזַּ֤ר] deu dar [לָאֶבְיוֹנִ֗ים] [צִ֭דְקָתוֹ] [עֹמֶ֣דֶת] [לָעַ֑ד] [קַ֝רְנ֗וֹ] [תָּר֥וּם]');
INSERT INTO verses VALUES (15881, 19, 112, 10, '[רָ֘שָׁ֤ע] [יִרְאֶ֨ה] [׀] [וְכָעָ֗ס] [שִׁנָּ֣יו] [יַחֲרֹ֣ק] [וְנָמָ֑ס] ímpios [רְשָׁעִ֣ים]');
INSERT INTO chapters VALUES (591, 19, 113, 9);
