INSERT INTO verses VALUES (15883, 19, 113, 2, 'haja nome yhwh [מְבֹרָ֑ךְ] [מֵֽ֝עַתָּ֗ה] e-até eternidade');
INSERT INTO verses VALUES (15884, 19, 113, 3, '[מִמִּזְרַח־שֶׁ֥מֶשׁ] [עַד־מְבוֹא֑וֹ] até [שֵׁ֣ם] yhwh nome yhwh');
INSERT INTO verses VALUES (15885, 19, 113, 4, '[רָ֖ם] sobre todo yhwh sobre sobre os-céus');
INSERT INTO verses VALUES (15886, 19, 113, 5, 'quem [כַּיהוָ֣ה] nosso-Elohim [הַֽמַּגְבִּיהִ֥י] [לָשָֽׁבֶת]');
INSERT INTO verses VALUES (15887, 19, 113, 6, '[הַֽמַּשְׁפִּילִ֥י] para-ver [בַּשָּׁמַ֥יִם] [וּבָאָֽרֶץ]');
INSERT INTO verses VALUES (15888, 19, 113, 7, '[מְקִֽימִ֣י] [מֵעָפָ֣ר] [דָּ֑ל] [מֵֽ֝אַשְׁפֹּ֗ת] [יָרִ֥ים] [אֶבְיֽוֹן]');
INSERT INTO verses VALUES (15889, 19, 113, 8, '[לְהוֹשִׁיבִ֥י] com [עִ֝֗ם] povo [עַמּֽוֹ] seu-povo');
INSERT INTO verses VALUES (15890, 19, 113, 9, '[מֽוֹשִׁיבִ֨י] [׀] [עֲקֶ֬רֶת] se [אֵֽם־הַבָּנִ֥ים] [שְׂמֵחָ֗ה] louvai [sem-traducao]');
INSERT INTO chapters VALUES (592, 19, 114, 8);
INSERT INTO verses VALUES (15891, 19, 114, 1, '[בְּצֵ֣את] Israel [מִמִּצְרָ֑יִם] casa Jacó [מֵעַ֥ם] [לֹעֵֽז]');
INSERT INTO verses VALUES (15892, 19, 114, 2, 'era [יְהוּדָ֣ה] [לְקָדְשׁ֑וֹ] Israel [מַמְשְׁלוֹתָֽיו]');
INSERT INTO verses VALUES (15893, 19, 114, 3, 'o-mar ver [וַיָּנֹ֑ס] [הַ֝יַּרְדֵּ֗ן] [יִסֹּ֥ב] [לְאָחֽוֹר]');
INSERT INTO verses VALUES (15894, 19, 114, 4, '[הֶֽ֭הָרִים] [רָקְד֣וּ] [כְאֵילִ֑ים] [גְּ֝בָע֗וֹת] [כִּבְנֵי־צֹֽאן]');
INSERT INTO verses VALUES (15895, 19, 114, 5, 'que o-mar que porque [הַ֝יַּרְדֵּ֗ן] [תִּסֹּ֥ב] [לְאָחֽוֹר]');
INSERT INTO verses VALUES (15896, 19, 114, 6, '[הֶֽ֭הָרִים] [תִּרְקְד֣וּ] [כְאֵילִ֑ים] [גְּ֝בָע֗וֹת] [כִּבְנֵי־צֹֽאן]');
INSERT INTO verses VALUES (15897, 19, 114, 7, '[מִלִּפְנֵ֣י] [אָ֭דוֹן] [ח֣וּלִי] terra [מִ֝לִּפְנֵ֗י] Eloah Jacó');
INSERT INTO verses VALUES (15898, 19, 114, 8, '[הַהֹפְכִ֣י] [הַצּ֣וּר] [אֲגַם־מָ֑יִם] águas [לְמַעְיְנוֹ־מָֽיִם] águas');
INSERT INTO chapters VALUES (593, 19, 115, 18);
INSERT INTO verses VALUES (15899, 19, 115, 1, 'não para-nós yhwh não para-nós porque [תֵּ֣ן] [כָּב֑וֹד] [עַל־חַ֝סְדְּךָ֗] sobre sobre');
INSERT INTO verses VALUES (15900, 19, 115, 2, '[לָ֭מָּה] dirão as-nações [אַיֵּה־נָ֝֗א] [אֱלֹהֵיהֶֽם]');
INSERT INTO verses VALUES (15901, 19, 115, 3, '[וֵֽאלֹהֵ֥ינוּ] [בַשָּׁמָ֑יִם] todo que agrada-se fez');
INSERT INTO verses VALUES (15902, 19, 115, 4, '[עֲ‍ֽ֭צַבֵּיהֶם] prata [וְזָהָ֑ב] [מַ֝עֲשֵׂ֗ה] maos-de homem');
INSERT INTO verses VALUES (15903, 19, 115, 5, '[פֶּֽה־לָ֭הֶם] [וְלֹ֣א] e-não [עֵינַ֥יִם] a-eles [וְלֹ֣א] e-não');
INSERT INTO verses VALUES (15904, 19, 115, 6, '[אָזְנַ֣יִם] a-eles e-não [יִשְׁמָ֑עוּ] certamente a-eles e-não [יְרִיחֽוּן]');
INSERT INTO verses VALUES (15905, 19, 115, 7, '[יְדֵיהֶ֤ם] e-não [וְלֹ֬א] [יְמִישׁ֗וּן] e-não [וְלֹ֣א] não [לֹֽא־יֶ֝הְגּ֗וּ] [בִּגְרוֹנָֽם]');
INSERT INTO verses VALUES (15906, 19, 115, 8, '[כְּ֭מוֹהֶם] serão [עֹשֵׂיהֶ֑ם] todo que [בָּהֶֽם] neles');
INSERT INTO verses VALUES (15907, 19, 115, 9, 'Israel [בְּטַ֣ח] [בַּיהוָ֑ה] [עֶזְרָ֖ם] [וּמָגִנָּ֣ם] ele');
INSERT INTO verses VALUES (15908, 19, 115, 10, 'casa [אַ֭הֲרֹן] [בִּטְח֣וּ] [בַיהוָ֑ה] [עֶזְרָ֖ם] [וּמָגִנָּ֣ם] ele');
INSERT INTO verses VALUES (15909, 19, 115, 11, '[יִרְאֵ֣י] yhwh [בִּטְח֣וּ] [בַיהוָ֑ה] [עֶזְרָ֖ם] [וּמָגִנָּ֣ם] ele');
INSERT INTO verses VALUES (15910, 19, 115, 12, 'yhwh [זְכָרָ֢נוּ] [יְבָ֫רֵ֥ךְ] [יְ֭בָרֵךְ] a casa Israel [אֶת־בֵּ֥ית] a casa Aharon');
INSERT INTO verses VALUES (15911, 19, 115, 13, '[יְ֭בָרֵךְ] [יִרְאֵ֣י] yhwh [הַ֝קְּטַנִּ֗ים] com');
INSERT INTO verses VALUES (15912, 19, 115, 14, '[יֹסֵ֣ף] yhwh [עֲלֵיכֶ֑ם] [עֲ֝לֵיכֶ֗ם] e-sobre');
INSERT INTO verses VALUES (15913, 19, 115, 15, '[בְּרוּכִ֣ים] [אַ֭תֶּם] a-yhwh fez céus [וָאָֽרֶץ]');
INSERT INTO verses VALUES (15914, 19, 115, 16, 'os-céus céus a-yhwh E-a-terra dar [לִבְנֵי־אָדָֽם] homem');
INSERT INTO verses VALUES (15915, 19, 115, 17, 'não [הַ֭מֵּתִים] [יְהַֽלְלוּ־יָ֑הּ] Yah e-não todo [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (15916, 19, 115, 18, '[וַאֲנַ֤חְנוּ] [׀] [נְבָ֘רֵ֤ךְ] [יָ֗הּ] e-até [וְעַד־עוֹלָ֗ם] louvai [sem-traducao]');
INSERT INTO chapters VALUES (594, 19, 116, 19);
INSERT INTO verses VALUES (15917, 19, 116, 1, '[אָ֭הַבְתִּי] porque [׀] yhwh a [תַּחֲנוּנָֽי]');
INSERT INTO verses VALUES (15918, 19, 116, 2, 'porque [אָזְנ֣וֹ] [לִ֑י] a-mim [אֶקְרָֽא]');
INSERT INTO verses VALUES (15919, 19, 116, 3, '[אֲפָפ֤וּנִי] [׀] [חֶבְלֵי־מָ֗וֶת] [וּמְצָרֵ֣י] [שְׁא֣וֹל] [מְצָא֑וּנִי] [צָרָ֖ה] [וְיָג֣וֹן] [אֶמְצָֽא]');
INSERT INTO verses VALUES (15920, 19, 116, 4, '[וּבְשֵֽׁם־יְהוָ֥ה] yhwh clamarei yhwh yhwh [נַפְשִֽׁי] alma-de-mim');
INSERT INTO verses VALUES (15921, 19, 116, 5, '[חַנּ֣וּן] yhwh [וְצַדִּ֑יק] [וֵ֖אלֹהֵ֣ינוּ] [מְרַחֵֽם]');
INSERT INTO verses VALUES (15922, 19, 116, 6, '[שֹׁמֵ֣ר] [פְּתָאיִ֣ם] yhwh [דַּ֝לּוֹתִ֗י] [וְלִ֣י] [יְהוֹשִֽׁיעַ]');
INSERT INTO verses VALUES (15923, 19, 116, 7, '[שׁוּבִ֣י] minha-alma [לִמְנוּחָ֑יְכִי] porque yhwh [עָלָֽיְכִי]');
INSERT INTO verses VALUES (15924, 19, 116, 8, 'que [חִלַּ֥צְתָּ] [נַפְשִׁ֗י] [מִ֫מָּ֥וֶת] a [מִן־דִּמְעָ֑ה] de [מִדֶּֽחִי] a');
INSERT INTO verses VALUES (15925, 19, 116, 9, '[אֶ֭תְהַלֵּךְ] diante-de yhwh [בְּ֝אַרְצ֗וֹת] a-vida');
INSERT INTO verses VALUES (15926, 19, 116, 10, '[הֶ֭אֱמַנְתִּי] que [אֲדַבֵּ֑ר] eu [עָנִ֥יתִי] muito');
INSERT INTO verses VALUES (15927, 19, 116, 11, '[אֲ֭נִי] eu-disse [בְחָפְזִ֑י] todo o-homem');
INSERT INTO verses VALUES (15928, 19, 116, 12, '[מָֽה־אָשִׁ֥יב] [לַיהוָ֑ה] a-yhwh todo');
INSERT INTO verses VALUES (15929, 19, 116, 13, '[כּוֹס־יְשׁוּע֥וֹת] [אֶשָּׂ֑א] [וּבְשֵׁ֖ם] yhwh yhwh');
INSERT INTO verses VALUES (15930, 19, 116, 14, '[נְ֭דָרַי] a-yhwh [אֲשַׁלֵּ֑ם] [נֶגְדָה־נָּ֝֗א] [לְכָל־עַמּֽוֹ] para-todo seu-povo');
INSERT INTO verses VALUES (15931, 19, 116, 15, '[יָ֭קָר] aos-olhos-de yhwh [הַ֝מָּ֗וְתָה] [לַחֲסִידָֽיו]');
INSERT INTO verses VALUES (15932, 19, 116, 16, '[אֽ͏ָנָּ֣ה] yhwh porque [עַ֫בְדֶּ֥ךָ] [אֲ‍ֽנִי־עַ֭בְדְּךָ] [בֶּן־אֲמָתֶ֑ךָ] [פִּ֝תַּ֗חְתָּ] filho-de');
INSERT INTO verses VALUES (15933, 19, 116, 17, '[לְֽךָ־אֶ֭זְבַּח] [זֶ֣בַח] [תּוֹדָ֑ה] [וּבְשֵׁ֖ם] yhwh yhwh');
INSERT INTO verses VALUES (15934, 19, 116, 18, '[נְ֭דָרַי] a-yhwh [אֲשַׁלֵּ֑ם] [נֶגְדָה־נָּ֝֗א] [לְכָל־עַמּֽוֹ] para-todo seu-povo');
INSERT INTO verses VALUES (15935, 19, 116, 19, '[בְּחַצְר֤וֹת] casa yhwh yhwh [בְּֽת֘וֹכֵ֤כִי] louvai [הַֽלְלוּ־יָֽהּ]');
INSERT INTO chapters VALUES (595, 19, 117, 2);
INSERT INTO verses VALUES (15936, 19, 117, 1, '[הַֽלְל֣וּ] a yhwh todo nações [sem-traducao] todo [sem-traducao]');
INSERT INTO verses VALUES (15937, 19, 117, 2, 'que [גָ֘בַ֤ר] [עָלֵ֨ינוּ] [׀] [חַסְדּ֗וֹ] yhwh [לְעוֹלָ֗ם] louvai [sem-traducao]');
INSERT INTO chapters VALUES (596, 19, 118, 29);
INSERT INTO verses VALUES (15938, 19, 118, 1, '[הוֹד֣וּ] a-yhwh porque que porque para-sempre sua-misericórdia');
INSERT INTO verses VALUES (15939, 19, 118, 2, '[יֹֽאמַר־נָ֥א] por-favor que porque para-sempre sua-misericórdia');
INSERT INTO verses VALUES (15940, 19, 118, 3, '[יֹֽאמְרוּ־נָ֥א] por-favor que [לְעוֹלָ֣ם] porque para-sempre sua-misericórdia');
INSERT INTO verses VALUES (15941, 19, 118, 4, '[יֹֽאמְרוּ־נָ֭א] por-favor yhwh que porque para-sempre sua-misericórdia');
INSERT INTO verses VALUES (15942, 19, 118, 5, 'de [קָרָ֣אתִי] [יָּ֑הּ] [עָנָ֖נִי] [בַמֶּרְחָ֣ב] [יָֽהּ]');
INSERT INTO verses VALUES (15943, 19, 118, 6, 'yhwh para-mim não [אִירָ֑א] que [לִ֣י] homem homem');
INSERT INTO verses VALUES (15944, 19, 118, 7, 'yhwh para-mim [בְּעֹזְרָ֑י] e-eu [אֶרְאֶ֥ה] [בְשֹׂנְאָֽי]');
INSERT INTO verses VALUES (15945, 19, 118, 8, 'bom [לַחֲס֥וֹת] [בַּיהוָ֑ה] [מִ֝בְּטֹ֗חַ] [בָּאָדָֽם]');
INSERT INTO verses VALUES (15946, 19, 118, 9, 'bom [לַחֲס֥וֹת] [בַּיהוָ֑ה] [מִ֝בְּטֹ֗חַ] [בִּנְדִיבִֽים]');
INSERT INTO verses VALUES (15947, 19, 118, 10, 'todo nações [בְּשֵׁ֥ם] yhwh que porque [sem-traducao]');
INSERT INTO verses VALUES (15948, 19, 118, 11, '[סַבּ֥וּנִי] também [בְּשֵׁ֥ם] yhwh que porque');
INSERT INTO verses VALUES (15949, 19, 118, 12, '[סַבּ֤וּנִי] [כִדְבוֹרִ֗ים] [דֹּ֭עֲכוּ] [כְּאֵ֣שׁ] [קוֹצִ֑ים] [בְּשֵׁ֥ם] yhwh que [אֲמִילַֽם]');
INSERT INTO verses VALUES (15950, 19, 118, 13, '[דַּחֹ֣ה] [דְחִיתַ֣נִי] [לִנְפֹּ֑ל] [וַ֖יהוָ֣ה] [עֲזָרָֽנִי]');
INSERT INTO verses VALUES (15951, 19, 118, 14, '[עָזִּ֣י] [וְזִמְרָ֣ת] Yah [וַֽיְהִי־לִ֝֗י] [לִֽישׁוּעָֽה] [sem-traducao]');
INSERT INTO verses VALUES (15952, 19, 118, 15, 'voz [׀] [רִנָּ֬ה] [וִֽישׁוּעָ֗ה] [בְּאָהֳלֵ֥י] [צַדִּיקִ֑ים] yhwh yhwh [עֹ֣שָׂה]');
INSERT INTO verses VALUES (15953, 19, 118, 16, '[יְמִ֣ין] yhwh [רוֹמֵמָ֑ה] [יְמִ֥ין] yhwh fez [חָֽיִל]');
INSERT INTO verses VALUES (15954, 19, 118, 17, 'não [אָמ֥וּת] porque [וַ֝אֲסַפֵּ֗ר] [מַֽעֲשֵׂ֥י] [יָֽהּ]');
INSERT INTO verses VALUES (15955, 19, 118, 18, '[יַסֹּ֣ר] [יִסְּרַ֣נִּי] [יָּ֑הּ] [וְ֝לַמָּ֗וֶת] não [נְתָנָֽנִי]');
INSERT INTO verses VALUES (15956, 19, 118, 19, '[פִּתְחוּ־לִ֥י] para-mim [אָֽבֹא־בָ֝ם] justica [יָֽהּ] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (15957, 19, 118, 20, 'este [לַיהוָ֑ה] a-yhwh [יָבֹ֥אוּ] nele nele-verso');
INSERT INTO verses VALUES (15958, 19, 118, 21, '[א֭וֹדְךָ] que [עֲנִיתָ֑נִי] [וַתְּהִי־לִ֝֗י] [לִֽישׁוּעָֽה]');
INSERT INTO verses VALUES (15959, 19, 118, 22, 'pedra [מָאֲס֣וּ] [הַבּוֹנִ֑ים] era para-cabeca [פִּנָּֽה]');
INSERT INTO verses VALUES (15960, 19, 118, 23, 'de-junto-de yhwh era [זֹּ֑את] [הִ֖יא] [נִפְלָ֣את] [בְּעֵינֵֽינוּ]');
INSERT INTO verses VALUES (15961, 19, 118, 24, '[זֶה־הַ֭יּוֹם] o-dia yhwh yhwh [וְנִשְׂמְחָ֣ה] nele nele-verso');
INSERT INTO verses VALUES (15962, 19, 118, 25, '[אָֽנָּ֣א] yhwh [הוֹשִׁ֘יעָ֥ה] [נָּ֑א] [אָֽנָּ֥א] yhwh [הַצְלִ֘יחָ֥ה] [נָּֽא]');
INSERT INTO verses VALUES (15963, 19, 118, 26, '[בָּר֣וּךְ] [הַ֭בָּא] no-nome-de yhwh [בֵּ֝רַֽכְנוּכֶ֗ם] [מִבֵּ֥ית] yhwh');
INSERT INTO verses VALUES (15964, 19, 118, 27, '[אֵ֤ל] yhwh yhwh para-nós [לָ֥נוּ] [אִסְרוּ־חַ֥ג] [בַּעֲבֹתִ֑ים] até [הַמִּזְבֵּֽחַ] o-altar');
INSERT INTO verses VALUES (15965, 19, 118, 28, '[אֵלִ֣י] tu [וְאוֹדֶ֑ךָּ] meu-Eloah [אֲרוֹמְמֶֽךָּ]');
INSERT INTO verses VALUES (15966, 19, 118, 29, '[הוֹד֣וּ] a-yhwh porque que porque para-sempre sua-misericórdia');
INSERT INTO chapters VALUES (597, 19, 119, 176);
INSERT INTO verses VALUES (15967, 19, 119, 1, '[אַשְׁרֵ֥י] [תְמִֽימֵי־דָ֑רֶךְ] caminho [בְּתוֹרַ֥ת] yhwh yhwh');
INSERT INTO verses VALUES (15968, 19, 119, 2, '[אַ֭שְׁרֵי] [נֹצְרֵ֥י] [עֵדֹתָ֗יו] em-todo coração');
INSERT INTO verses VALUES (15969, 19, 119, 3, 'certamente não [עַוְלָ֑ה] [בִּדְרָכָ֥יו] [הָלָֽכוּ]');
INSERT INTO verses VALUES (15970, 19, 119, 4, 'tu [צִוִּ֥יתָה] [פִקֻּדֶ֗יךָ] [לִשְׁמֹ֥ר] muito');
INSERT INTO verses VALUES (15971, 19, 119, 5, '[אַ֭חֲלַי] [יִכֹּ֥נוּ] [דְרָכָ֗י] [לִשְׁמֹ֥ר] [חֻקֶּֽיךָ]');
INSERT INTO verses VALUES (15972, 19, 119, 6, 'entao não [בְּ֝הַבִּיטִ֗י] [אֶל־כָּל־מִצְוֺתֶֽיךָ] a todo [sem-traducao]');
INSERT INTO verses VALUES (15973, 19, 119, 7, '[א֭וֹדְךָ] [בְּיֹ֣שֶׁר] [לֵבָ֑ב] [בְּ֝לָמְדִ֗י] [מִשְׁפְּטֵ֥י] [צִדְקֶֽךָ]');
INSERT INTO verses VALUES (15974, 19, 119, 8, 'a [אֶשְׁמֹ֑ר] [אַֽל־תַּעַזְבֵ֥נִי] a até');
INSERT INTO verses VALUES (15975, 19, 119, 9, '[בַּמֶּ֣ה] [יְזַכֶּה־נַּ֭עַר] [אֶת־אָרְח֑וֹ] a [כִּדְבָרֶֽךָ]');
INSERT INTO verses VALUES (15976, 19, 119, 10, 'em-todo [דְרַשְׁתִּ֑יךָ] [אַל־תַּ֝שְׁגֵּ֗נִי] a');
INSERT INTO verses VALUES (15977, 19, 119, 11, '[בְּ֭לִבִּי] [צָפַ֣נְתִּי] [אִמְרָתֶ֑ךָ] [לְ֝מַ֗עַן] não [אֶֽחֱטָא־לָֽךְ] para-ti');
INSERT INTO verses VALUES (15978, 19, 119, 12, '[בָּר֖וּךְ] tu yhwh [לַמְּדֵ֥נִי] [חֻקֶּֽיךָ]');
INSERT INTO verses VALUES (15979, 19, 119, 13, '[בִּשְׂפָתַ֥י] [סִפַּ֑רְתִּי] todo [מִשְׁפְּטֵי־פִֽיךָ]');
INSERT INTO verses VALUES (15980, 19, 119, 14, '[בְּדֶ֖רֶךְ] [עֵדְוֺתֶ֥יךָ] [שַּׂ֗[t]שְׂתִּי] todo [כָּל־הֽוֹן]');
INSERT INTO verses VALUES (15981, 19, 119, 15, '[בְּפִקֻּדֶ֥יךָ] [אָשִׂ֑יחָה] [וְ֝אַבִּ֗יטָה] [אֹרְחֹתֶֽיךָ]');
INSERT INTO verses VALUES (15982, 19, 119, 16, '[בְּחֻקֹּתֶ֥יךָ] [אֶֽשְׁתַּעֲשָׁ֑ע] não [אֶשְׁכַּ֣ח] [דְּבָרֶֽךָ]');
INSERT INTO verses VALUES (15983, 19, 119, 17, '[גְּמֹ֖ל] sobre [אֶֽחְיֶ֗ה] [וְאֶשְׁמְרָ֥ה] [דְבָרֶֽךָ]');
INSERT INTO verses VALUES (15984, 19, 119, 18, '[גַּל־עֵינַ֥י] [וְאַבִּ֑יטָה] [נִ֝פְלָא֗וֹת] [מִתּוֹרָתֶֽךָ]');
INSERT INTO verses VALUES (15985, 19, 119, 19, '[גֵּ֣ר] eu na-terra a [מִ֝מֶּ֗נִּי] [מִצְוֺתֶֽיךָ]');
INSERT INTO verses VALUES (15986, 19, 119, 20, '[גָּרְסָ֣ה] [נַפְשִׁ֣י] [לְתַאֲבָ֑ה] a [בְכָל־עֵֽת] em-todo');
INSERT INTO verses VALUES (15987, 19, 119, 21, '[גָּ֭עַרְתָּ] [זֵדִ֣ים] [אֲרוּרִ֑ים] [הַ֝שֹּׁגִים] [מִמִּצְוֺתֶֽיךָ]');
INSERT INTO verses VALUES (15988, 19, 119, 22, '[גַּ֣ל] [מֵֽ֭עָלַי] [חֶרְפָּ֣ה] [וָב֑וּז] que [עֵדֹתֶ֣יךָ] [נָצָֽרְתִּי]');
INSERT INTO verses VALUES (15989, 19, 119, 23, 'também [יָֽשְׁב֣וּ] [שָׂ֭רִים] [בִּ֣י] [נִדְבָּ֑רוּ] [עַ֝בְדְּךָ֗] [יָשִׂ֥יחַ] [בְּחֻקֶּֽיךָ]');
INSERT INTO verses VALUES (15990, 19, 119, 24, 'também [שַׁעֲשֻׁעָ֗י] [אַנְשֵׁ֥י] [עֲצָתִֽי]');
INSERT INTO verses VALUES (15991, 19, 119, 25, '[דָּֽבְקָ֣ה] [לֶעָפָ֣ר] minha-alma [חַ֝יֵּ֗נִי] [כִּדְבָרֶֽךָ]');
INSERT INTO verses VALUES (15992, 19, 119, 26, '[דְּרָכַ֣י] [סִ֭פַּרְתִּי] [וַֽתַּעֲנֵ֗נִי] [לַמְּדֵ֥נִי] [חֻקֶּֽיךָ]');
INSERT INTO verses VALUES (15993, 19, 119, 27, '[דֶּֽרֶךְ־פִּקּוּדֶ֥יךָ] [הֲבִינֵ֑נִי] [וְ֝אָשִׂ֗יחָה] [בְּנִפְלְאוֹתֶֽיךָ]');
INSERT INTO verses VALUES (15994, 19, 119, 28, '[דָּלְפָ֣ה] minha-alma [מִתּוּגָ֑ה] [קַ֝יְּמֵ֗נִי] [כִּדְבָרֶֽךָ]');
INSERT INTO verses VALUES (15995, 19, 119, 29, '[דֶּֽרֶךְ־שֶׁ֭קֶר] [הָסֵ֣ר] [מִמֶּ֑נִּי] [וְֽתוֹרָתְךָ֥] [חָנֵּֽנִי]');
INSERT INTO verses VALUES (15996, 19, 119, 30, '[דֶּֽרֶךְ־אֱמוּנָ֥ה] [בָחָ֑רְתִּי] [מִשְׁפָּטֶ֥יךָ] [שִׁוִּֽיתִי]');
INSERT INTO verses VALUES (15997, 19, 119, 31, '[דָּבַ֥קְתִּי] [בְעֵֽדְוֺתֶ֑יךָ] yhwh a');
INSERT INTO verses VALUES (15998, 19, 119, 32, '[דֶּֽרֶךְ־מִצְוֺתֶ֥יךָ] [אָר֑וּץ] que porque [לִבִּֽי]');
INSERT INTO verses VALUES (15999, 19, 119, 33, '[הוֹרֵ֣נִי] yhwh o-caminho-de [חֻקֶּ֗יךָ] [וְאֶצְּרֶ֥נָּה] [עֵֽקֶב]');
INSERT INTO verses VALUES (16000, 19, 119, 34, '[הֲ֭בִינֵנִי] [וְאֶצְּרָ֥ה] [תֽוֹרָתֶ֗ךָ] [וְאֶשְׁמְרֶ֥נָּה] em-todo coração');
INSERT INTO verses VALUES (16001, 19, 119, 35, '[הַ֭דְרִיכֵנִי] [בִּנְתִ֣יב] [מִצְוֺתֶ֑יךָ] porque [חָפָֽצְתִּי]');
INSERT INTO verses VALUES (16002, 19, 119, 36, '[הַט־לִ֭בִּי] [אֶל־עֵדְוֺתֶ֗יךָ] a [אֶל־בָּֽצַע] e-a a');
INSERT INTO verses VALUES (16003, 19, 119, 37, '[הַעֲבֵ֣ר] [עֵ֭ינַי] [מֵרְא֣וֹת] [שָׁ֑וְא] [בִּדְרָכֶ֥ךָ] [חַיֵּֽנִי]');
INSERT INTO verses VALUES (16004, 19, 119, 38, '[הָקֵ֣ם] [לְ֭עַבְדְּךָ] [אִמְרָתֶ֑ךָ] que [לְיִרְאָתֶֽךָ]');
INSERT INTO verses VALUES (16005, 19, 119, 39, '[הַעֲבֵ֣ר] [חֶ֭רְפָּתִי] que [יָגֹ֑רְתִּי] que [מִשְׁפָּטֶ֣יךָ] [טוֹבִֽים]');
INSERT INTO verses VALUES (16006, 19, 119, 40, 'eis [תָּאַ֣בְתִּי] [לְפִקֻּדֶ֑יךָ] [בְּצִדְקָתְךָ֥] [חַיֵּֽנִי]');
INSERT INTO verses VALUES (16007, 19, 119, 41, '[וִֽיבֹאֻ֣נִי] [חֲסָדֶ֣ךָ] yhwh [תְּ֝שׁ֥וּעָתְךָ֗] [כְּאִמְרָתֶֽךָ]');
INSERT INTO verses VALUES (16008, 19, 119, 42, '[וְאֶֽעֱנֶ֣ה] [חֹרְפִ֣י] palavra porque [בִּדְבָרֶֽךָ]');
INSERT INTO verses VALUES (16009, 19, 119, 43, 'e-a [מִפִּ֣י] [דְבַר־אֱמֶ֣ת] palavra-de que até muito porque');
INSERT INTO verses VALUES (16010, 19, 119, 44, '[וְאֶשְׁמְרָ֖ה] [תוֹרָתְךָ֥] [תָמִ֗יד] [לְעוֹלָ֥ם] e-perpetuidade');
INSERT INTO verses VALUES (16011, 19, 119, 45, '[וְאֶתְהַלְּכָ֥ה] [בָרְחָבָ֑ה] que [פִקֻּדֶ֣יךָ] [דָרָֽשְׁתִּי]');
INSERT INTO verses VALUES (16012, 19, 119, 46, '[וַאֲדַבְּרָ֣ה] [בְ֭עֵדֹתֶיךָ] diante [מְלָכִ֗ים] e-não [אֵבֽוֹשׁ]');
INSERT INTO verses VALUES (16013, 19, 119, 47, '[וְאֶשְׁתַּֽעֲשַׁ֥ע] [בְּמִצְוֺתֶ֗יךָ] que [אָהָֽבְתִּי]');
INSERT INTO verses VALUES (16014, 19, 119, 48, '[וְאֶשָּֽׂא־כַפַּ֗י] [אֶֽל־מִ֭צְוֺתֶיךָ] a [אָהָ֗בְתִּי] que [בְחֻקֶּֽיךָ]');
INSERT INTO verses VALUES (16015, 19, 119, 49, '[זְכֹר־דָּבָ֥ר] palavra sobre sobre que');
INSERT INTO verses VALUES (16016, 19, 119, 50, 'esta [נֶחָמָתִ֣י] [בְעָנְיִ֑י] que [אִמְרָתְךָ֣] [חִיָּֽתְנִי]');
INSERT INTO verses VALUES (16017, 19, 119, 51, '[זֵ֭דִים] [הֱלִיצֻ֣נִי] até muito não não');
INSERT INTO verses VALUES (16018, 19, 119, 52, '[זָ֘כַ֤רְתִּי] [מִשְׁפָּטֶ֖יךָ] [מֵעוֹלָ֥ם] yhwh yhwh');
INSERT INTO verses VALUES (16019, 19, 119, 53, '[זַלְעָפָ֣ה] [אֲ֭חָזַתְנִי] [מֵרְשָׁעִ֑ים] [עֹ֝זְבֵ֗י] [תּוֹרָתֶֽךָ]');
INSERT INTO verses VALUES (16020, 19, 119, 54, '[זְ֭מִרוֹת] [הָֽיוּ־לִ֥י] para-mim [בְּבֵ֣ית] na-casa-de');
INSERT INTO verses VALUES (16021, 19, 119, 55, '[זָ֘כַ֤רְתִּי] [בַלַּ֣יְלָה] teu-nome yhwh [וָֽ֝אֶשְׁמְרָ֗ה] [תּוֹרָתֶֽךָ]');
INSERT INTO verses VALUES (16022, 19, 119, 56, 'esta [הָֽיְתָה־לִּ֑י] que porque [נָצָֽרְתִּי]');
INSERT INTO verses VALUES (16023, 19, 119, 57, '[חֶלְקִ֖י] yhwh [אָמַ֗רְתִּי] [לִשְׁמֹ֥ר] [דְּבָרֶֽיךָ]');
INSERT INTO verses VALUES (16024, 19, 119, 58, '[חִלִּ֣יתִי] [פָנֶ֣יךָ] em-todo coração [כְּאִמְרָתֶֽךָ]');
INSERT INTO verses VALUES (16025, 19, 119, 59, '[חִשַּׁ֥בְתִּי] [דְרָכָ֑י] [וָאָשִׁ֥יבָה] [רַ֝גְלַ֗י] a');
INSERT INTO verses VALUES (16026, 19, 119, 60, '[חַ֭שְׁתִּי] e-não [הִתְמַהְמָ֑הְתִּי] [לִ֝שְׁמֹ֗ר] [מִצְוֺתֶֽיךָ]');
INSERT INTO verses VALUES (16027, 19, 119, 61, '[חֶבְלֵ֣י] ímpios [עִוְּדֻ֑נִי] [תּֽ֝וֹרָתְךָ֗] não [שָׁכָֽחְתִּי]');
INSERT INTO verses VALUES (16028, 19, 119, 62, '[חֲצֽוֹת־לַ֗יְלָה] noite [לְהוֹד֣וֹת] para-ti sobre sobre [צִדְקֶֽךָ]');
INSERT INTO verses VALUES (16029, 19, 119, 63, '[חָבֵ֣ר] eu para-todo que [וּ֝לְשֹׁמְרֵ֗י] [פִּקּוּדֶֽיךָ] [sem-traducao]');
INSERT INTO verses VALUES (16030, 19, 119, 64, '[חַסְדְּךָ֣] yhwh [מָלְאָ֥ה] a-terra [חֻקֶּ֥יךָ] [לַמְּדֵֽנִי]');
INSERT INTO verses VALUES (16031, 19, 119, 65, 'bom [עָשִׂ֣יתָ] com yhwh yhwh');
INSERT INTO verses VALUES (16032, 19, 119, 66, 'bom [טַ֣עַם] [וָדַ֣עַת] [לַמְּדֵ֑נִי] que [בְמִצְוֺתֶ֣יךָ] [הֶאֱמָֽנְתִּי]');
INSERT INTO verses VALUES (16033, 19, 119, 67, 'ainda-não [אֶ֭עֱנֶה] eu [שֹׁגֵ֑ג] e-agora [אִמְרָתְךָ֥] [שָׁמָֽרְתִּי]');
INSERT INTO verses VALUES (16034, 19, 119, 68, '[טוֹב־אַתָּ֥ה] tu [לַמְּדֵ֥נִי] [חֻקֶּֽיךָ]');
INSERT INTO verses VALUES (16035, 19, 119, 69, '[טָפְל֬וּ] sobre-mim [שֶׁ֣קֶר] [זֵדִ֑ים] eu em-todo [׀] [אֱצֹּ֬ר] [פִּקּוּדֶֽיךָ]');
INSERT INTO verses VALUES (16036, 19, 119, 70, '[טָפַ֣שׁ] [כַּחֵ֣לֶב] [לִבָּ֑ם] eu [תּוֹרָתְךָ֥] [שִֽׁעֲשָֽׁעְתִּי]');
INSERT INTO verses VALUES (16037, 19, 119, 71, '[טֽוֹב־לִ֥י] para-mim porque [אֶלְמַ֥ד] [חֻקֶּֽיךָ]');
INSERT INTO verses VALUES (16038, 19, 119, 72, '[טֽוֹב־לִ֥י] para-mim [מֵ֝אַלְפֵ֗י] ouro [וָכָֽסֶף]');
INSERT INTO verses VALUES (16039, 19, 119, 73, 'tuas-maos [עָ֭שׂוּנִי] [וַֽיְכוֹנְנ֑וּנִי] [הֲ֝בִינֵ֗נִי] [וְאֶלְמְדָ֥ה] [מִצְוֺתֶֽיךָ]');
INSERT INTO verses VALUES (16040, 19, 119, 74, '[יְ֭רֵאֶיךָ] [יִרְא֣וּנִי] [וְיִשְׂמָ֑חוּ] que [לִדְבָרְךָ֣] [יִחָֽלְתִּי]');
INSERT INTO verses VALUES (16041, 19, 119, 75, 'eu-sei yhwh porque justica [וֶ֝אֱמוּנָ֗ה] [עִנִּיתָֽנִי] [sem-traducao]');
INSERT INTO verses VALUES (16042, 19, 119, 76, 'seja por-favor [לְנַחֲמֵ֑נִי] [כְּאִמְרָתְךָ֥] [לְעַבְדֶּֽךָ] [sem-traducao]');
INSERT INTO verses VALUES (16043, 19, 119, 77, '[יְבֹא֣וּנִי] [רַחֲמֶ֣יךָ] [וְאֶֽחְיֶ֑ה] porque [שַֽׁעֲשֻׁעָֽי]');
INSERT INTO verses VALUES (16044, 19, 119, 78, 'envergonhar-se-ao [זֵ֭דִים] porque [עִוְּת֑וּנִי] [אֲ֝נִ֗י] eu [בְּפִקּוּדֶֽיךָ] [sem-traducao]');
INSERT INTO verses VALUES (16045, 19, 119, 79, '[יָשׁ֣וּבוּ] para-mim [יְרֵאֶ֑יךָ] [*וידעו]');
INSERT INTO verses VALUES (16046, 19, 119, 80, '[יְהִֽי־לִבִּ֣י] [תָמִ֣ים] [בְּחֻקֶּ֑יךָ] [לְ֝מַ֗עַן] não não');
INSERT INTO verses VALUES (16047, 19, 119, 81, '[כָּלְתָ֣ה] [לִתְשׁוּעָתְךָ֣] minha-alma [לִדְבָרְךָ֥] [יִחָֽלְתִּי]');
INSERT INTO verses VALUES (16048, 19, 119, 82, '[כָּל֣וּ] [עֵ֭ינַי] [לְאִמְרָתֶ֑ךָ] dizendo quando [תְּֽנַחֲמֵֽנִי]');
INSERT INTO verses VALUES (16049, 19, 119, 83, 'porque [כְּנֹ֣אד] [בְּקִיט֑וֹר] [חֻ֝קֶּ֗יךָ] não não');
INSERT INTO verses VALUES (16050, 19, 119, 84, '[כַּמָּ֥ה] [יְמֵֽי־עַבְדֶּ֑ךָ] [מָתַ֬י] [תַּעֲשֶׂ֖ה] [בְרֹדְפַ֣י] [מִשְׁפָּֽט]');
INSERT INTO verses VALUES (16051, 19, 119, 85, '[כָּֽרוּ־לִ֣י] para-mim [שִׁיח֑וֹת] [אֲ֝שֶׁ֗ר] não não');
INSERT INTO verses VALUES (16052, 19, 119, 86, 'todo [אֱמוּנָ֑ה] [שֶׁ֖קֶר] [רְדָפ֣וּנִי] [עָזְרֵֽנִי]');
INSERT INTO verses VALUES (16053, 19, 119, 87, '[כִּ֭מְעַט] [כִּלּ֣וּנִי] na-terra e-eu não [פִקֻּודֶֽיךָ] [sem-traducao]');
INSERT INTO verses VALUES (16054, 19, 119, 88, '[כְּחַסְדְּךָ֥] [חַיֵּ֑נִי] [וְ֝אֶשְׁמְרָ֗ה] [עֵד֥וּת] [פִּֽיךָ]');
INSERT INTO verses VALUES (16055, 19, 119, 89, '[לְעוֹלָ֥ם] yhwh [דְּ֝בָרְךָ֗] [נִצָּ֥ב] [בַּשָּׁמָֽיִם]');
INSERT INTO verses VALUES (16056, 19, 119, 90, 'para-a-geração [וָ֭דֹר] [אֱמֽוּנָתֶ֑ךָ] [כּוֹנַ֥נְתָּ] terra [וַֽתַּעֲמֹֽד]');
INSERT INTO verses VALUES (16057, 19, 119, 91, '[לְֽ֭מִשְׁפָּטֶיךָ] [עָמְד֣וּ] o-dia que [הַכֹּ֣ל] [עֲבָדֶֽיךָ]');
INSERT INTO verses VALUES (16058, 19, 119, 92, 'se-nao-fosse [ת֭וֹרָתְךָ] [שַׁעֲשֻׁעָ֑י] [אָ֝֗ז] [אָבַ֥דְתִּי] [בְעָנְיִֽי]');
INSERT INTO verses VALUES (16059, 19, 119, 93, '[לְ֭עוֹלָם] não [פִּקּוּדֶ֑יךָ] que porque [חִיִּיתָֽנִי]');
INSERT INTO verses VALUES (16060, 19, 119, 94, '[לְֽךָ־אֲ֭נִי] [הוֹשִׁיעֵ֑נִי] que porque [דָרָֽשְׁתִּי]');
INSERT INTO verses VALUES (16061, 19, 119, 95, 'a-mim [קִוּ֣וּ] ímpios [לְאַבְּדֵ֑נִי] [עֵ֝דֹתֶ֗יךָ] [אֶתְבּוֹנָֽן]');
INSERT INTO verses VALUES (16062, 19, 119, 96, 'para-todo [רָאִ֣יתִי] vi [רְחָבָ֖ה] [מִצְוָתְךָ֣] muito');
INSERT INTO verses VALUES (16063, 19, 119, 97, '[מָֽה־אָהַ֥בְתִּי] [תוֹרָתֶ֑ךָ] [כָּל־הַ֝יּ֗וֹם] todo o-dia ela [sem-traducao]');
INSERT INTO verses VALUES (16064, 19, 119, 98, '[מֵ֭אֹ֣יְבַי] [תְּחַכְּמֵ֣נִי] [מִצְוֺתֶ֑ךָ] que para-sempre [הִיא־לִֽי]');
INSERT INTO verses VALUES (16065, 19, 119, 99, 'de-todo [הִשְׂכַּ֑לְתִּי] que porque [שִׂ֣יחָה] [לִֽֿי]');
INSERT INTO verses VALUES (16066, 19, 119, 100, '[מִזְּקֵנִ֥ים] [אֶתְבּוֹנָ֑ן] que [פִקּוּדֶ֣יךָ] [נָצָֽרְתִּי]');
INSERT INTO verses VALUES (16067, 19, 119, 101, 'de-todo mal mau [רַגְלָ֑י] [לְ֝מַ֗עַן] [אֶשְׁמֹ֥ר] [דְּבָרֶֽךָ]');
INSERT INTO verses VALUES (16068, 19, 119, 102, '[מִמִּשְׁפָּטֶ֥יךָ] não [כִּֽי־אַ֝תָּ֗ה] porque');
INSERT INTO verses VALUES (16069, 19, 119, 103, 'que [לְ֭חִכִּי] [אִמְרָתֶ֗ךָ] [מִדְּבַ֥שׁ] [לְפִֽי]');
INSERT INTO verses VALUES (16070, 19, 119, 104, '[מִפִּקּוּדֶ֥יךָ] [אֶתְבּוֹנָ֑ן] sobre [שָׂנֵ֤אתִי] todo [כָּל־אֹ֬רַח] [שָֽׁקֶר]');
INSERT INTO verses VALUES (16071, 19, 119, 105, '[נֵר־לְרַגְלִ֥י] [דְבָרֶ֑ךָ] [וְ֝א֗וֹר] [לִנְתִיבָתִֽי]');
INSERT INTO verses VALUES (16072, 19, 119, 106, '[נִשְׁבַּ֥עְתִּי] [וָאֲקַיֵּ֑מָה] [לִ֝שְׁמֹ֗ר] [מִשְׁפְּטֵ֥י] [צִדְקֶֽךָ]');
INSERT INTO verses VALUES (16073, 19, 119, 107, '[נַעֲנֵ֥יתִי] até yhwh yhwh [כִדְבָרֶֽךָ]');
INSERT INTO verses VALUES (16074, 19, 119, 108, '[נִדְב֣וֹת] [פִּ֭י] [רְצֵה־נָ֣א] yhwh yhwh [לַמְּדֵֽנִי]');
INSERT INTO verses VALUES (16075, 19, 119, 109, '[נַפְשִׁ֣י] [בְכַפִּ֣י] [תָמִ֑יד] [וְ֝תֽוֹרָתְךָ֗] não [שָׁכָֽחְתִּי]');
INSERT INTO verses VALUES (16076, 19, 119, 110, '[נָתְנ֬וּ] ímpios [פַּ֣ח] a-mim [וּ֝מִפִּקּוּדֶ֗יךָ] não [תָעִֽיתִי]');
INSERT INTO verses VALUES (16077, 19, 119, 111, '[נָחַ֣לְתִּי] [עֵדְוֺתֶ֣יךָ] para-sempre porque [לִבִּ֣י] [הֵֽמָּה]');
INSERT INTO verses VALUES (16078, 19, 119, 112, '[נָטִ֣יתִי] [לִ֭בִּי] para-fazer [חֻקֶּ֗יךָ] [לְעוֹלָ֥ם] [עֵֽקֶב]');
INSERT INTO verses VALUES (16079, 19, 119, 113, '[סֵעֲפִ֥ים] [שָׂנֵ֑אתִי] [וְֽתוֹרָתְךָ֥] [אָהָֽבְתִּי]');
INSERT INTO verses VALUES (16080, 19, 119, 114, '[סִתְרִ֣י] [וּמָגִנִּ֣י] tu [לִדְבָרְךָ֥] [יִחָֽלְתִּי]');
INSERT INTO verses VALUES (16081, 19, 119, 115, '[סֽוּרוּ־מִמֶּ֥נִּי] [מְרֵעִ֑ים] [וְ֝אֶצְּרָ֗ה] [מִצְוֺ֥ת] [אֱלֹהָֽי]');
INSERT INTO verses VALUES (16082, 19, 119, 116, '[סָמְכֵ֣נִי] [כְאִמְרָתְךָ֣] [וְאֶֽחְיֶ֑ה] e-a [מִשִּׂבְרִֽי]');
INSERT INTO verses VALUES (16083, 19, 119, 117, '[סְעָדֵ֥נִי] [וְאִוָּשֵׁ֑עָה] [וְאֶשְׁעָ֖ה] [בְחֻקֶּ֣יךָ] [תָמִֽיד]');
INSERT INTO verses VALUES (16084, 19, 119, 118, '[סָ֭לִיתָ] todo [מֵחֻקֶּ֑יךָ] [כִּי־שֶׁ֝֗קֶר] porque');
INSERT INTO verses VALUES (16085, 19, 119, 119, '[סִגִ֗ים] [הִשְׁבַּ֥תָּ] todo [לָ֝כֵ֗ן] terra [עֵדֹתֶֽיךָ]');
INSERT INTO verses VALUES (16086, 19, 119, 120, '[סָמַ֣ר] [מִפַּחְדְּךָ֣] [בְשָׂרִ֑י] [וּֽמִמִּשְׁפָּטֶ֥יךָ] [יָרֵֽאתִי]');
INSERT INTO verses VALUES (16087, 19, 119, 121, '[עָ֭שִׂיתִי] [מִשְׁפָּ֣ט] [וָצֶ֑דֶק] não [לְעֹֽשְׁקָֽי]');
INSERT INTO verses VALUES (16088, 19, 119, 122, 'tarde [עַבְדְּךָ֣] [לְט֑וֹב] a [זֵדִֽים]');
INSERT INTO verses VALUES (16089, 19, 119, 123, '[עֵ֭ינַי] [כָּל֣וּ] [לִֽישׁוּעָתֶ֑ךָ] [וּלְאִמְרַ֥ת] [צִדְקֶֽךָ]');
INSERT INTO verses VALUES (16090, 19, 119, 124, 'fez com [כְחַסְדֶּ֗ךָ] [וְחֻקֶּ֥יךָ] [לַמְּדֵֽנִי]');
INSERT INTO verses VALUES (16091, 19, 119, 125, '[עַבְדְּךָ־אָ֥נִי] [הֲבִינֵ֑נִי] [וְ֝אֵדְעָ֗ה] [עֵדֹתֶֽיךָ]');
INSERT INTO verses VALUES (16092, 19, 119, 126, '[עֵ֭ת] [לַעֲשׂ֣וֹת] a-yhwh [הֵ֝פֵ֗רוּ] [תּוֹרָתֶֽךָ]');
INSERT INTO verses VALUES (16093, 19, 119, 127, 'sobre [אָהַ֣בְתִּי] [מִצְוֺתֶ֑יךָ] [מִזָּהָ֥ב] [וּמִפָּֽז]');
INSERT INTO verses VALUES (16094, 19, 119, 128, 'sobre [׀] todo [כֹ֣ל] todo [כָּל־אֹ֖רַח] todo [שָׂנֵֽאתִי]');
INSERT INTO verses VALUES (16095, 19, 119, 129, '[פְּלָא֥וֹת] [עֵדְוֺתֶ֑יךָ] sobre [נְצָרָ֥תַם] [נַפְשִֽׁי]');
INSERT INTO verses VALUES (16096, 19, 119, 130, '[פֵּ֖תַח] [דְּבָרֶ֥יךָ] [יָאִ֗יר] [מֵבִ֥ין] [פְּתָיִֽים]');
INSERT INTO verses VALUES (16097, 19, 119, 131, '[פִּֽי־פָ֭עַרְתִּי] [וָאֶשְׁאָ֑פָה] que porque [יָאָֽבְתִּי]');
INSERT INTO verses VALUES (16098, 19, 119, 132, '[פְּנֵה־אֵלַ֥י] [וְחָנֵּ֑נִי] [כְּ֝מִשְׁפָּ֗ט] [לְאֹהֲבֵ֥י] [שְׁמֶֽךָ]');
INSERT INTO verses VALUES (16099, 19, 119, 133, '[פְּ֭עָמַי] [הָכֵ֣ן] [בְּאִמְרָתֶ֑ךָ] e-a [כָל־אָֽוֶן] todo');
INSERT INTO verses VALUES (16100, 19, 119, 134, '[פְּ֭דֵנִי] [מֵעֹ֣שֶׁק] homem [וְ֝אֶשְׁמְרָ֗ה] [פִּקּוּדֶֽיךָ]');
INSERT INTO verses VALUES (16101, 19, 119, 135, '[פָּ֭נֶיךָ] [הָאֵ֣ר] [בְּעַבְדֶּ֑ךָ] [וְ֝לַמְּדֵ֗נִי] a');
INSERT INTO verses VALUES (16102, 19, 119, 136, '[פַּלְגֵי־מַ֭יִם] águas [עֵינָ֑י] sobre sobre não');
INSERT INTO verses VALUES (16103, 19, 119, 137, 'justo tu yhwh [וְ֝יָשָׁ֗ר] [מִשְׁפָּטֶֽיךָ]');
INSERT INTO verses VALUES (16104, 19, 119, 138, '[צִ֭וִּיתָ] justica [עֵדֹתֶ֑יךָ] [וֶֽאֱמוּנָ֥ה] muito');
INSERT INTO verses VALUES (16105, 19, 119, 139, '[צִמְּתַ֥תְנִי] [קִנְאָתִ֑י] porque [דְבָרֶ֣יךָ] [צָרָֽי]');
INSERT INTO verses VALUES (16106, 19, 119, 140, '[צְרוּפָ֖ה] [אִמְרָתְךָ֥] muito [וְֽעַבְדְּךָ֥] [אֲהֵבָֽהּ]');
INSERT INTO verses VALUES (16107, 19, 119, 141, '[צָעִ֣יר] eu [וְנִבְזֶ֑ה] [פִּ֝קֻּדֶ֗יךָ] não [שָׁכָֽחְתִּי]');
INSERT INTO verses VALUES (16108, 19, 119, 142, '[צִדְקָתְךָ֣] justica para-sempre [וְֽתוֹרָתְךָ֥] [אֱמֶֽת]');
INSERT INTO verses VALUES (16109, 19, 119, 143, '[צַר־וּמָצ֥וֹק] [מְצָא֑וּנִי] [מִ֝צְוֺתֶ֗יךָ] [שַׁעֲשֻׁעָֽי]');
INSERT INTO verses VALUES (16110, 19, 119, 144, '[צֶ֖דֶק] [עֵדְוֺתֶ֥יךָ] [לְעוֹלָ֗ם] [הֲבִינֵ֥נִי] [וְאֶחְיֶֽה]');
INSERT INTO verses VALUES (16111, 19, 119, 145, '[קָרָ֣אתִי] em-todo coração yhwh yhwh [אֶצֹּֽרָה]');
INSERT INTO verses VALUES (16112, 19, 119, 146, '[קְרָאתִ֥יךָ] [הוֹשִׁיעֵ֑נִי] [וְ֝אֶשְׁמְרָ֗ה] [עֵדֹתֶֽיךָ]');
INSERT INTO verses VALUES (16113, 19, 119, 147, '[קִדַּ֣מְתִּי] [בַ֭נֶּשֶׁף] [וָאֲשַׁוֵּ֑עָה] [*לדבריך]');
INSERT INTO verses VALUES (16114, 19, 119, 148, '[קִדְּמ֣וּ] [עֵ֭ינַי] [אַשְׁמֻר֑וֹת] [לָ֝שִׂ֗יחַ] [בְּאִמְרָתֶֽךָ]');
INSERT INTO verses VALUES (16115, 19, 119, 149, '[ק֭וֹלִי] [שִׁמְעָ֣ה] [כְחַסְדֶּ֑ךָ] yhwh [כְּֽמִשְׁפָּטֶ֥ךָ] [חַיֵּֽנִי]');
INSERT INTO verses VALUES (16116, 19, 119, 150, '[קָ֭רְבוּ] [רֹדְפֵ֣י] [זִמָּ֑ה] [מִתּוֹרָתְךָ֥] [רָחָֽקוּ]');
INSERT INTO verses VALUES (16117, 19, 119, 151, '[קָר֣וֹב] tu yhwh e-todo [אֱמֶֽת]');
INSERT INTO verses VALUES (16118, 19, 119, 152, 'oriente [יָ֭דַעְתִּי] [מֵעֵדֹתֶ֑יךָ] que para-sempre [יְסַדְתָּֽם]');
INSERT INTO verses VALUES (16119, 19, 119, 153, '[רְאֵֽה־עָנְיִ֥י] [וְחַלְּצֵ֑נִי] [כִּי־תֽ֝וֹרָתְךָ֗] não [שָׁכָֽחְתִּי] não');
INSERT INTO verses VALUES (16120, 19, 119, 154, '[רִיבָ֣ה] [רִ֭יבִי] [וּגְאָלֵ֑נִי] [לְאִמְרָתְךָ֥] [חַיֵּֽנִי]');
INSERT INTO verses VALUES (16121, 19, 119, 155, '[רָח֣וֹק] [מֵרְשָׁעִ֣ים] [יְשׁוּעָ֑ה] porque não não');
INSERT INTO verses VALUES (16122, 19, 119, 156, '[רַחֲמֶ֖יךָ] [רַבִּ֥ים] yhwh yhwh [כְּֽמִשְׁפָּטֶ֥יךָ]');
INSERT INTO verses VALUES (16123, 19, 119, 157, '[רַ֭בִּים] [רֹדְפַ֣י] [וְצָרָ֑י] [מֵ֝עֵדְוֺתֶ֗יךָ] não [נָטִֽיתִי]');
INSERT INTO verses VALUES (16124, 19, 119, 158, 'vi [בֹ֭גְדִים] [וָֽאֶתְקוֹטָ֑טָה] que [אִ֝מְרָתְךָ֗] não [שָׁמָֽרוּ]');
INSERT INTO verses VALUES (16125, 19, 119, 159, 'viu porque [אָהָ֑בְתִּי] yhwh yhwh [חַיֵּֽנִי]');
INSERT INTO verses VALUES (16126, 19, 119, 160, '[רֹאשׁ־דְּבָרְךָ֥] [אֱמֶ֑ת] verdade [כָּל־מִשְׁפַּ֥ט] todo [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (16127, 19, 119, 161, '[שָׂ֭רִים] [רְדָפ֣וּנִי] [חִנָּ֑ם] [*ומדבריך] [**וּ֝מִדְּבָרְךָ֗]');
INSERT INTO verses VALUES (16128, 19, 119, 162, 'seis eu sobre [כְּ֝מוֹצֵ֗א] [שָׁלָ֥ל] [רָֽב] muito');
INSERT INTO verses VALUES (16129, 19, 119, 163, '[שֶׁ֣קֶר] [שָׂ֭נֵאתִי] [וַאֲתַעֵ֑בָה] [תּוֹרָתְךָ֥] [אָהָֽבְתִּי]');
INSERT INTO verses VALUES (16130, 19, 119, 164, 'sete no-dia [הִלַּלְתִּ֑יךָ] sobre [מִשְׁפְּטֵ֥י] [צִדְקֶֽךָ]');
INSERT INTO verses VALUES (16131, 19, 119, 165, '[שָׁל֣וֹם] muito [לְאֹהֲבֵ֣י] [תוֹרָתֶ֑ךָ] e-nao-ha [מִכְשֽׁוֹל] [sem-traducao]');
INSERT INTO verses VALUES (16132, 19, 119, 166, '[שִׂבַּ֣רְתִּי] [לִֽישׁוּעָתְךָ֣] yhwh [וּֽמִצְוֺתֶ֥יךָ] [עָשִֽׂיתִי]');
INSERT INTO verses VALUES (16133, 19, 119, 167, '[שָֽׁמְרָ֣ה] minha-alma [עֵדֹתֶ֑יךָ] [וָאֹהֲבֵ֥ם] muito');
INSERT INTO verses VALUES (16134, 19, 119, 168, '[שָׁמַ֣רְתִּי] [פִ֭קּוּדֶיךָ] [וְעֵדֹתֶ֑יךָ] que todo [נֶגְדֶּֽךָ]');
INSERT INTO verses VALUES (16135, 19, 119, 169, '[תִּקְרַ֤ב] [רִנָּתִ֣י] [לְפָנֶ֣יךָ] yhwh [כִּדְבָרְךָ֥] [הֲבִינֵֽנִי]');
INSERT INTO verses VALUES (16136, 19, 119, 170, '[תָּב֣וֹא] [תְחִנָּתִ֣י] [לְפָנֶ֑יךָ] [כְּ֝אִמְרָתְךָ֗] [הַצִּילֵֽנִי]');
INSERT INTO verses VALUES (16137, 19, 119, 171, '[תַּבַּ֣עְנָה] [שְׂפָתַ֣י] [תְּהִלָּ֑ה] que [תְלַמְּדֵ֣נִי] [חֻקֶּֽיךָ]');
INSERT INTO verses VALUES (16138, 19, 119, 172, '[תַּ֣עַן] [לְ֭שׁוֹנִי] [אִמְרָתֶ֑ךָ] que todo [צֶּֽדֶק]');
INSERT INTO verses VALUES (16139, 19, 119, 173, '[תְּהִֽי־יָדְךָ֥] [לְעָזְרֵ֑נִי] que porque [בָחָֽרְתִּי]');
INSERT INTO verses VALUES (16140, 19, 119, 174, '[תָּאַ֣בְתִּי] [לִֽישׁוּעָתְךָ֣] yhwh [וְ֝ת֥וֹרָתְךָ֗] [שַׁעֲשֻׁעָֽי]');
INSERT INTO verses VALUES (16141, 19, 119, 175, '[תְּֽחִי־נַ֭פְשִׁי] minha-alma [וּֽמִשְׁפָּטֶ֥ךָ] [יַעֲזְרֻֽנִי]');
INSERT INTO verses VALUES (16142, 19, 119, 176, '[תָּעִ֗יתִי] [כְּשֶׂ֣ה] [אֹ֭בֵד] [בַּקֵּ֣שׁ] [עַבְדֶּ֑ךָ] que [מִ֝צְוֺתֶיךָ֗] não [שָׁכָֽחְתִּי]');
INSERT INTO chapters VALUES (598, 19, 120, 7);
INSERT INTO verses VALUES (16143, 19, 120, 1, '[שִׁ֗יר] [הַֽמַּ֫עֲל֥וֹת] a yhwh a-mim [קָ֝רָ֗אתִי] [וֽ͏ַיַּעֲנֵֽנִי]');
INSERT INTO verses VALUES (16144, 19, 120, 2, 'yhwh [הַצִּ֣ילָה] minha-alma [מִשְּׂפַת־שֶׁ֑קֶר] [מִלָּשׁ֥וֹן] [רְמִיָּֽה]');
INSERT INTO verses VALUES (16145, 19, 120, 3, 'que a-ti [וּמַה־יֹּסִ֥יף] para-ti [לָשׁ֥וֹן] [רְמִיָּֽה]');
INSERT INTO verses VALUES (16146, 19, 120, 4, '[חִצֵּ֣י] [גִבּ֣וֹר] [שְׁנוּנִ֑ים] povo [גַּחֲלֵ֥י] [רְתָמִֽים]');
INSERT INTO verses VALUES (16147, 19, 120, 5, '[אֽוֹיָה־לִ֭י] para-mim porque [שָׁ֝כַ֗נְתִּי] [עִֽם־אָהֳלֵ֥י] [קֵדָֽר] com');
INSERT INTO verses VALUES (16148, 19, 120, 6, '[רַ֭בַּת] [שָֽׁכְנָה־לָּ֣הּ] [נַפְשִׁ֑י] minha-alma povo [שָׁלֽוֹם]');
INSERT INTO verses VALUES (16149, 19, 120, 7, '[אֲ‍ֽנִי־שָׁ֭לוֹם] [וְכִ֣י] [אֲדַבֵּ֑ר] [הֵ֝֗מָּה] [לַמִּלְחָמָֽה]');
INSERT INTO chapters VALUES (599, 19, 121, 8);
INSERT INTO verses VALUES (16150, 19, 121, 1, '[שִׁ֗יר] [לַֽמַּ֫עֲל֥וֹת] [אֶשָּׂ֣א] [עֵ֭ינַי] a [מֵ֝אַ֗יִן] [יָבֹ֥א] virá');
INSERT INTO verses VALUES (16151, 19, 121, 2, '[עֶ֭זְרִי] [מֵעִ֣ם] yhwh fez céus [וָאָֽרֶץ]');
INSERT INTO verses VALUES (16152, 19, 121, 3, 'a [לַמּ֣וֹט] [רַגְלֶ֑ךָ] [אַל־יָ֝נ֗וּם] a');
INSERT INTO verses VALUES (16153, 19, 121, 4, 'eis não [וְלֹ֣א] e-não [שׁ֝וֹמֵ֗ר] [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (16154, 19, 121, 5, 'yhwh [שֹׁמְרֶ֑ךָ] yhwh [צִ֝לְּךָ֗] sobre mão');
INSERT INTO verses VALUES (16155, 19, 121, 6, '[יוֹמָ֗ם] [הַשֶּׁ֥מֶשׁ] não [וְיָרֵ֥חַ] [בַּלָּֽיְלָה]');
INSERT INTO verses VALUES (16156, 19, 121, 7, 'yhwh [יִשְׁמָרְךָ֥] de-todo mau [אֶת־נַפְשֶֽׁךָ] a');
INSERT INTO verses VALUES (16157, 19, 121, 8, 'yhwh [יִשְׁמָר־צֵאתְךָ֥] [וּבוֹאֶ֑ךָ] [מֵֽ֝עַתָּ֗ה] [וְעַד־עוֹלָֽם]');
INSERT INTO chapters VALUES (600, 19, 122, 9);
INSERT INTO verses VALUES (16158, 19, 122, 1, 'cântico [הַֽמַּעֲל֗וֹת] para-Davi [שָׂ֭מַחְתִּי] [בְּאֹמְרִ֣ים] a-mim casa yhwh [נֵלֵֽךְ]');
INSERT INTO verses VALUES (16159, 19, 122, 2, '[עֹ֭מְדוֹת] eram [רַגְלֵ֑ינוּ] [בִּ֝שְׁעָרַ֗יִךְ] Jerusalém');
INSERT INTO verses VALUES (16160, 19, 122, 3, '[יְרוּשָׁלַ֥͏ִם] [הַבְּנוּיָ֑ה] [כְּ֝עִ֗יר] [שֶׁחֻבְּרָה־לָּ֥הּ] [יַחְדָּֽו]');
INSERT INTO verses VALUES (16161, 19, 122, 4, '[שֶׁשָּׁ֨ם] [עָל֪וּ] [שְׁבָטִ֡ים] [שִׁבְטֵי־יָ֭הּ] [עֵד֣וּת] [לְיִשְׂרָאֵ֑ל] [לְ֝הֹד֗וֹת] [לְשֵׁ֣ם] yhwh yhwh');
INSERT INTO verses VALUES (16162, 19, 122, 5, 'que [שָׁ֨מָּה] [׀] [יָשְׁב֣וּ] [כִסְא֣וֹת] [לְמִשְׁפָּ֑ט] para-casa-de [לְבֵ֣ית]');
INSERT INTO verses VALUES (16163, 19, 122, 6, '[שַׁ֭אֲלוּ] [שְׁל֣וֹם] Jerusalém [יִ֝שְׁלָ֗יוּ] [אֹהֲבָֽיִךְ]');
INSERT INTO verses VALUES (16164, 19, 122, 7, '[יְהִֽי־שָׁל֥וֹם] [בְּחֵילֵ֑ךְ] [שַׁ֝לְוָ֗ה] [בְּאַרְמְנוֹתָֽיִךְ]');
INSERT INTO verses VALUES (16165, 19, 122, 8, 'a-fim-de [אַחַ֣י] [וְרֵעָ֑י] [אֲדַבְּרָה־נָּ֖א] [שָׁל֣וֹם] sobre-ti em-ti');
INSERT INTO verses VALUES (16166, 19, 122, 9, 'a-fim-de casa-de yhwh nosso-Elohim bom para-ti para-ti');
INSERT INTO chapters VALUES (601, 19, 123, 4);
INSERT INTO verses VALUES (16167, 19, 123, 1, '[שִׁ֗יר] [הַֽמַּ֫עֲל֥וֹת] [אֵ֭לֶיךָ] [נָשָׂ֣אתִי] a [הַ֝יֹּשְׁבִ֗י] [בַּשָּׁמָֽיִם]');
INSERT INTO verses VALUES (16168, 19, 123, 2, 'eis [כְעֵינֵ֪י] [עֲבָדִ֡ים] a mão [כְּעֵינֵ֣י] [שִׁפְחָה֮] [אֶל־יַ֢ד] a mão [עֵ֭ינֵינוּ] assim [Elohim] até yhwh até');
INSERT INTO verses VALUES (16169, 19, 123, 3, '[חָנֵּ֣נוּ] yhwh [חָנֵּ֑נוּ] porque muito [בֽוּז]');
INSERT INTO verses VALUES (16170, 19, 123, 4, '[רַבַּת֮] [שָֽׂבְעָה־לָּ֢הּ] [נַ֫פְשֵׁ֥נוּ] [הַלַּ֥עַג] [הַשַּׁאֲנַנִּ֑ים] [הַ֝בּ֗וּז] [לִגְאֵ֥יוֹנִֽים]');
INSERT INTO chapters VALUES (602, 19, 124, 8);
INSERT INTO verses VALUES (16171, 19, 124, 1, 'cântico [הַֽמַּעֲל֗וֹת] para-Davi se-nao-fosse yhwh [שֶׁהָ֣יָה] [לָ֑נוּ] [יֹֽאמַר־נָ֝א] [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (16172, 19, 124, 2, 'se-nao-fosse yhwh [שֶׁהָ֣יָה] [לָ֑נוּ] [בְּק֖וּם] [עָלֵ֣ינוּ] homem');
INSERT INTO verses VALUES (16173, 19, 124, 3, '[אֲ֭זַי] vida [בְּלָע֑וּנוּ] [בַּחֲר֖וֹת] [אַפָּ֣ם] [בָּֽנוּ]');
INSERT INTO verses VALUES (16174, 19, 124, 4, '[אֲ֭זַי] as-águas [שְׁטָפ֑וּנוּ] [נַ֗֜[c]חְלָה] sobre [עַל־נַפְשֵֽׁנוּ]');
INSERT INTO verses VALUES (16175, 19, 124, 5, '[אֲ֭זַי] [עָבַ֣ר] sobre [הַ֝מַּ֗יִם] as-águas');
INSERT INTO verses VALUES (16176, 19, 124, 6, '[בָּר֥וּךְ] yhwh [שֶׁלֹּ֥א] [נְתָנָ֥נוּ] [טֶ֝֗רֶף] [לְשִׁנֵּיהֶֽם]');
INSERT INTO verses VALUES (16177, 19, 124, 7, '[נַפְשֵׁ֗נוּ] [כְּצִפּ֥וֹר] [נִמְלְטָה֮] [מִפַּ֢ח] [י֫וֹקְשִׁ֥ים] [הַפַּ֥ח] [נִשְׁבָּ֗ר] [וַאֲנַ֥חְנוּ] [נִמְלָֽטְנוּ]');
INSERT INTO verses VALUES (16178, 19, 124, 8, '[עֶ֭זְרֵנוּ] no-nome-de yhwh fez céus [וָאָֽרֶץ]');
INSERT INTO chapters VALUES (603, 19, 125, 5);
INSERT INTO verses VALUES (16179, 19, 125, 1, '[שִׁ֗יר] [הַֽמַּ֫עֲל֥וֹת] [הַבֹּטְחִ֥ים] [בַּיהוָ֑ה] [כְּֽהַר־צִיּ֥וֹן] [לֹא־יִ֝מּ֗וֹט] não [יֵשֵֽׁב] habitou');
INSERT INTO verses VALUES (16180, 19, 125, 2, '[יְֽרוּשָׁלִַ֗ם] [הָרִים֮] [סָבִ֢יב] a-ela [וַ֭יהוָה] [סָבִ֣יב] [לְעַמּ֑וֹ] [מֵ֝עַתָּ֗ה] e-até eternidade');
INSERT INTO verses VALUES (16181, 19, 125, 3, 'que [׀[t]] não sobre [שֵׁ֤בֶט] [הָרֶ֗שַׁע] sobre não [הַֽצַּדִּ֫יקִ֥ים] [לְמַ֡עַן] [לֹא־יִשְׁלְח֖וּ] [הַצַדִּיקִ֨ים]');
INSERT INTO verses VALUES (16182, 19, 125, 4, '[הֵיטִ֣יבָה] yhwh [לַטּוֹבִ֑ים] [וְ֝לִֽישָׁרִ֗ים] [בְּלִבּוֹתָֽם]');
INSERT INTO verses VALUES (16183, 19, 125, 5, '[וְהַמַּטִּ֤ים] [עַֽקַלְקַלּוֹתָ֗ם] [יוֹלִיכֵ֣ם] yhwh a [הָאָ֑וֶן] [שָׁ֝ל֗וֹם] [עַל־יִשְׂרָאֵֽל] sobre Israel');
INSERT INTO chapters VALUES (604, 19, 126, 6);
INSERT INTO verses VALUES (16184, 19, 126, 1, '[שִׁ֗יר] [הַֽמַּ֫עֲל֥וֹת] [בְּשׁ֣וּב] yhwh a [צִיּ֑וֹן] Sião [כְּחֹלְמִֽים]');
INSERT INTO verses VALUES (16185, 19, 126, 2, '[אָ֤ז] [יִמָּלֵ֪א] [שְׂח֡וֹק] [פִּינוּ֮] [וּלְשׁוֹנֵ֢נוּ] [רִ֫נָּ֥ה] [אָ֭ז] dirão [בַגּוֹיִ֑ם] [הִגְדִּ֥יל] yhwh para-fazer com');
INSERT INTO verses VALUES (16186, 19, 126, 3, '[הִגְדִּ֣יל] yhwh para-fazer [עִמָּ֗נוּ] [הָיִ֥ינוּ] [שְׂמֵחִֽים]');
INSERT INTO verses VALUES (16187, 19, 126, 4, '[שׁוּבָ֣ה] yhwh a [**שְׁבִיתֵ֑נוּ] [כַּאֲפִיקִ֥ים]');
INSERT INTO verses VALUES (16188, 19, 126, 5, '[הַזֹּרְעִ֥ים] [בְּדִמְעָ֗ה] [בְּרִנָּ֥ה] [יִקְצֹֽרוּ]');
INSERT INTO verses VALUES (16189, 19, 126, 6, '[הָ֘ל֤וֹךְ] [יֵלֵ֨ךְ] [׀] [וּבָכֹה֮] [נֹשֵׂ֢א] [מֶֽשֶׁךְ־הַ֫זָּ֥רַע] [בֹּֽא־יָב֥וֹא] virá [נֹ֝שֵׂ֗א] [אֲלֻמֹּתָֽיו]');
INSERT INTO chapters VALUES (605, 19, 127, 5);
INSERT INTO verses VALUES (16190, 19, 127, 1, 'cântico [הַֽמַּֽעֲל֗וֹת] [לִשְׁלֹ֫מֹ֥ה] se [׀] não [בַ֗יִת] casa [׀] [עָמְל֣וּ] [בוֹנָ֣יו] nele se yhwh não [׀] cidade [שׁוֹמֵֽר]');
INSERT INTO verses VALUES (16191, 19, 127, 2, '[שָׁ֤וְא] a-vós [׀] levantou [ק֡וּם] [מְאַֽחֲרֵי־שֶׁ֗בֶת] [אֹ֭כְלֵי] pão [הָעֲצָבִ֑ים] assim [יִתֵּ֖ן] [לִֽידִיד֣וֹ] odiou');
INSERT INTO verses VALUES (16192, 19, 127, 3, 'eis [נַחֲלַ֣ת] yhwh [בָּנִ֑ים] [שָׂ֝כָ֗ר] fruto [הַבָּֽטֶן]');
INSERT INTO verses VALUES (16193, 19, 127, 4, '[כְּחִצִּ֥ים] pela-mão-de [כֵּ֝֗ן] [בְּנֵ֣י] filhos-de');
INSERT INTO verses VALUES (16194, 19, 127, 5, '[אַשְׁרֵ֤י] [הַגֶּ֗בֶר] que enchei a [מֵ֫הֶ֥ם] [לֹֽא־יֵבֹ֑שׁוּ] não [אֶת־אוֹיְבִ֣ים] porque a');
INSERT INTO chapters VALUES (606, 19, 128, 6);
INSERT INTO verses VALUES (16195, 19, 128, 1, '[שִׁ֗יר] [הַֽמַּ֫עֲל֥וֹת] [אַ֭שְׁרֵי] todo yhwh o-que-vai [בִּדְרָכָֽיו]');
INSERT INTO verses VALUES (16196, 19, 128, 2, '[יְגִ֣יעַ] [כַּ֭פֶּיךָ] que [תֹאכֵ֑ל] [אַ֝שְׁרֶ֗יךָ] [וְט֣וֹב] para-ti');
INSERT INTO verses VALUES (16197, 19, 128, 3, '[אֶשְׁתְּךָ֤] [׀] [כְּגֶ֥פֶן] [פֹּרִיָּה֮] [בְּיַרְכְּתֵ֢י] [בֵ֫יתֶ֥ךָ] [בָּ֭נֶיךָ] [כִּשְׁתִלֵ֣י] [זֵיתִ֑ים] [סָ֝בִ֗יב]');
INSERT INTO verses VALUES (16198, 19, 128, 4, 'eis porque [יְבֹ֥רַךְ] [גָּ֗בֶר] [יְרֵ֣א] yhwh yhwh');
INSERT INTO verses VALUES (16199, 19, 128, 5, '[יְבָרֶכְךָ֥] yhwh [מִצִ֫יּ֥וֹן] [וּ֖[d]רְאֵה] Jerusalém todo dias-de dias-de');
INSERT INTO verses VALUES (16200, 19, 128, 6, '[וּרְאֵֽה־בָנִ֥ים] [לְבָנֶ֑יךָ] [שָׁ֝ל֗וֹם] [עַל־יִשְׂרָאֵֽל] sobre Israel');
INSERT INTO chapters VALUES (607, 19, 129, 8);
INSERT INTO verses VALUES (16201, 19, 129, 1, '[שִׁ֗יר] [הַֽמַּ֫עֲל֥וֹת] [רַ֭בַּת] [צְרָר֣וּנִי] [מִנְּעוּרַ֑י] [יֹֽאמַר־נָ֝א] [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (16202, 19, 129, 2, '[רַ֭בַּת] [צְרָר֣וּנִי] [מִנְּעוּרָ֑י] também não [לִֽי]');
INSERT INTO verses VALUES (16203, 19, 129, 3, 'sobre [חָרְשׁ֣וּ] [חֹרְשִׁ֑ים] [הֶ֝אֱרִ֗יכוּ] [*למענותם]');
INSERT INTO verses VALUES (16204, 19, 129, 4, 'yhwh justo [קִ֝צֵּ֗ץ] [עֲב֣וֹת] [רְשָׁעִֽים]');
INSERT INTO verses VALUES (16205, 19, 129, 5, '[יֵ֭בֹשׁוּ] [וְיִסֹּ֣גוּ] [אָח֑וֹר] todo [שֹׂנְאֵ֥י] [צִיּֽוֹן]');
INSERT INTO verses VALUES (16206, 19, 129, 6, '[יִ֭הְיוּ] [כַּחֲצִ֣יר] [גַּגּ֑וֹת] [שֶׁקַּדְמַ֖ת] [שָׁלַ֣ף] [יָבֵֽשׁ]');
INSERT INTO verses VALUES (16207, 19, 129, 7, '[שֶׁלֹּ֤א] enchei [כַפּ֥וֹ] [קוֹצֵ֗ר] [וְחִצְנ֥וֹ] [מְעַמֵּֽר]');
INSERT INTO verses VALUES (16208, 19, 129, 8, 'e-não [אָֽמְר֨וּ] [׀] [הָעֹבְרִ֗ים] yhwh [אֲלֵיכֶ֑ם] [בֵּרַ֥כְנוּ] [אֶ֝תְכֶ֗ם] no-nome-de yhwh');
INSERT INTO chapters VALUES (608, 19, 130, 8);
INSERT INTO verses VALUES (16209, 19, 130, 1, 'cântico [הַֽמַּעֲל֑וֹת] [מִמַּעֲמַקִּ֖ים] [קְרָאתִ֣יךָ] yhwh');
INSERT INTO verses VALUES (16210, 19, 130, 2, 'Adonai [שִׁמְעָ֢ה] [בְק֫וֹלִ֥י] [תִּהְיֶ֣ינָה] [אָ֭זְנֶיךָ] [קַשֻּׁב֑וֹת] à-voz-de [תַּחֲנוּנָֽי]');
INSERT INTO verses VALUES (16211, 19, 130, 3, 'se [תִּשְׁמָר־יָ֑הּ] [Adonai] quem Adonai');
INSERT INTO verses VALUES (16212, 19, 130, 4, 'porque [הַסְּלִיחָ֑ה] [לְ֝מַ֗עַן] [תִּוָּרֵֽא]');
INSERT INTO verses VALUES (16213, 19, 130, 5, '[קִוִּ֣יתִי] yhwh [קִוְּתָ֣ה] minha-alma [וְֽלִדְבָר֥וֹ] [הוֹחָֽלְתִּי]');
INSERT INTO verses VALUES (16214, 19, 130, 6, '[נַפְשִׁ֥י] [לַֽאדֹנָ֑י] [מִשֹּׁמְרִ֥ים] [לַ֝בֹּ֗קֶר] [שֹׁמְרִ֥ים] [לַבֹּֽקֶר]');
INSERT INTO verses VALUES (16215, 19, 130, 7, '[יַחֵ֥ל] Israel a yhwh porque com yhwh [פְדֽוּת]');
INSERT INTO verses VALUES (16216, 19, 130, 8, '[וְ֭הוּא] [יִפְדֶּ֣ה] a de-toda de-todo');
INSERT INTO chapters VALUES (609, 19, 131, 3);
INSERT INTO verses VALUES (16217, 19, 131, 1, 'cântico [הַֽמַּֽעֲל֗וֹת] para-Davi yhwh não [לֹא־גָבַ֣הּ] [לִ֭בִּי] e-não [עֵינַ֑י] [וְלֹֽא־הִלַּ֓כְתִּי] e-não [בִּגְדֹל֖וֹת] [וּבְנִפְלָא֣וֹת] [מִמֶּֽנִּי]');
INSERT INTO verses VALUES (16218, 19, 131, 2, 'se não [׀] [וְדוֹמַ֗מְתִּי] [נַ֫פְשִׁ֥י] [כְּ֭גָמֻל] sobre sua-mãe [כַּגָּמֻ֖ל] sobre-mim [נַפְשִֽׁי]');
INSERT INTO verses VALUES (16219, 19, 131, 3, '[יַחֵ֣ל] Israel a yhwh [וְעַד־עוֹלָֽם]');
INSERT INTO chapters VALUES (610, 19, 132, 18);
INSERT INTO verses VALUES (16220, 19, 132, 1, '[שִׁ֗יר] [הַֽמַּ֫עֲל֥וֹת] [זְכוֹר־יְהוָ֥ה] yhwh para-Davi [OBJ] todo');
INSERT INTO verses VALUES (16221, 19, 132, 2, 'que [נִ֭שְׁבַּע] a-yhwh [נָ֝דַ֗ר] [לַאֲבִ֥יר] Jacó');
INSERT INTO verses VALUES (16222, 19, 132, 3, 'se [בְּאֹ֣הֶל] [בֵּיתִ֑י] [אִם־אֶ֝עֱלֶ֗ה] se [יְצוּעָֽי] sobre');
INSERT INTO verses VALUES (16223, 19, 132, 4, 'se darei [לְעֵינָ֑י] [לְֽעַפְעַפַּ֥י] [תְּנוּמָֽה]');
INSERT INTO verses VALUES (16224, 19, 132, 5, 'até lugar [לַיהוָ֑ה] a-yhwh [לַאֲבִ֥יר] [יַעֲקֹֽב] Jacó');
INSERT INTO verses VALUES (16225, 19, 132, 6, '[הִנֵּֽה־שְׁמַֽעֲנ֥וּהָ] [בְאֶפְרָ֑תָה] [מְ֝צָאנ֗וּהָ] [בִּשְׂדֵי־יָֽעַר]');
INSERT INTO verses VALUES (16226, 19, 132, 7, '[נָב֥וֹאָה] [לְמִשְׁכְּנוֹתָ֑יו] [נִ֝שְׁתַּחֲוֶ֗ה] [לַהֲדֹ֥ם] [רַגְלָֽיו]');
INSERT INTO verses VALUES (16227, 19, 132, 8, '[קוּמָ֣ה] yhwh [לִמְנוּחָתֶ֑ךָ] tu [וַאֲר֥וֹן] [עֻזֶּֽךָ]');
INSERT INTO verses VALUES (16228, 19, 132, 9, '[כֹּהֲנֶ֥יךָ] [יִלְבְּשׁוּ־צֶ֑דֶק] justica [יְרַנֵּֽנוּ] [sem-traducao]');
INSERT INTO verses VALUES (16229, 19, 132, 10, '[בַּ֭עֲבוּר] Davi [עַבְדֶּ֑ךָ] a face-de face-de');
INSERT INTO verses VALUES (16230, 19, 132, 11, '[נִשְׁבַּֽע־יְהוָ֨ה] yhwh [לְדָוִ֡ד] [אֱמֶת֮] não [מִ֫מֶּ֥נָּה] do-fruto-de [בִטְנְךָ֑] [אָ֝שִׁ֗ית] [לְכִסֵּא־לָֽךְ] [sem-traducao] para-ti');
INSERT INTO verses VALUES (16231, 19, 132, 12, 'se [בָנֶ֨יךָ] [׀] [בְּרִיתִי֮] [וְעֵדֹתִ֥י] [ז֗וֹ] [אֲלַ֫מְּדֵ֥ם] também [עֲדֵי־עַ֑ד] ate até [sem-traducao] [sem-traducao] para-ti');
INSERT INTO verses VALUES (16232, 19, 132, 13, 'porque yhwh yhwh [אִ֝וָּ֗הּ] [לְמוֹשָׁ֥ב] a-ele');
INSERT INTO verses VALUES (16233, 19, 132, 14, '[זֹאת־מְנוּחָתִ֥י] [עֲדֵי־עַ֑ד] ate que [אִוִּתִֽיהָ] [sem-traducao] porque [sem-traducao]');
INSERT INTO verses VALUES (16234, 19, 132, 15, '[צֵ֭ידָהּ] abençoou [אֲבָרֵ֑ךְ] [אֶ֝בְיוֹנֶ֗יהָ] [אַשְׂבִּ֥יעַֽ] pão');
INSERT INTO verses VALUES (16235, 19, 132, 16, '[וְֽ֭כֹהֲנֶיהָ] [אַלְבִּ֣ישׁ] [יֶ֑שַׁע] [וַ֝חֲסִידֶ֗יהָ] [רַנֵּ֥ן] [יְרַנֵּֽנוּ]');
INSERT INTO verses VALUES (16236, 19, 132, 17, 'nome [אַצְמִ֣יחַ] [קֶ֣רֶן] para-Davi [עָרַ֥כְתִּי] [נֵ֝֗ר] [לִמְשִׁיחִֽי]');
INSERT INTO verses VALUES (16237, 19, 132, 18, '[א֭וֹיְבָיו] [אַלְבִּ֣ישׁ] [בֹּ֑שֶׁת] [וְ֝עָלָ֗יו] [יָצִ֥יץ] [נִזְרֽוֹ]');
INSERT INTO chapters VALUES (611, 19, 133, 3);
INSERT INTO verses VALUES (16238, 19, 133, 1, 'cântico [הַֽמַּעֲל֗וֹת] para-Davi eis que bom e-que [אַחִ֣ים] [גַּם־יָֽחַד] também');
INSERT INTO verses VALUES (16239, 19, 133, 2, '[כַּשֶּׁ֤מֶן] [הַטּ֨וֹב] sobre [עַל־הָרֹ֗אשׁ] [יֹרֵ֗ד] sobre [זְקַֽן־אַהֲרֹ֑ן] [שֶׁ֝יֹּרֵ֗ד] [עַל־פִּ֥י] [מִדּוֹתָֽיו] sobre');
INSERT INTO verses VALUES (16240, 19, 133, 3, '[כְּטַל־חֶרְמ֗וֹן] [שֶּׁיֹּרֵד֮] [עַל־הַרְרֵ֢י] sobre que [שָׁ֨ם] porque [צִוָּ֣ה] yhwh yhwh vida [עַד־הָעוֹלָֽם] até');
INSERT INTO chapters VALUES (612, 19, 134, 3);
INSERT INTO verses VALUES (16241, 19, 134, 1, '[שִׁ֗יר] [הַֽמַּעֲ֫ל֥וֹת] eis [׀] a yhwh todo yhwh yhwh [בְּבֵית־יְ֝הוָ֗ה] na-casa-de yhwh');
INSERT INTO verses VALUES (16242, 19, 134, 2, '[שְׂאֽוּ־יְדֵכֶ֥ם] [קֹ֑דֶשׁ] santidade [אֶת־יְהוָֽה] a yhwh');
INSERT INTO verses VALUES (16243, 19, 134, 3, '[יְבָרֶכְךָ֣] yhwh [מִצִיּ֑וֹן] fez céus [וָאָֽרֶץ]');
INSERT INTO chapters VALUES (613, 19, 135, 21);
INSERT INTO verses VALUES (16244, 19, 135, 1, 'louvai [יָ֨הּ] [׀] a nome yhwh [הֽ͏ַ֝לְלוּ] [עַבְדֵ֥י] yhwh');
INSERT INTO verses VALUES (16245, 19, 135, 2, '[שֶׁ֣֭עֹֽמְדִים] na-casa-de yhwh [בְּ֝חַצְר֗וֹת] casa nosso-Elohim');
INSERT INTO verses VALUES (16246, 19, 135, 3, '[הַֽ֭לְלוּ־יָהּ] [כִּי־ט֣וֹב] yhwh bom yhwh que [נָעִֽים] porque');
INSERT INTO verses VALUES (16247, 19, 135, 4, 'porque Jacó a-ele a-ele Yah Israel [sem-traducao]');
INSERT INTO verses VALUES (16248, 19, 135, 5, 'que eu [יָ֭דַעְתִּי] porque yhwh yhwh [מִכָּל־אֱלֹהִֽים] de-todo Elohim');
INSERT INTO verses VALUES (16249, 19, 135, 6, 'todo que yhwh yhwh fez [וּבָאָ֑רֶץ] [בַּ֝יַּמִּ֗ים] [וְכָל־תְּהוֹמֽוֹת] e-todo');
INSERT INTO verses VALUES (16250, 19, 135, 7, '[מַֽעֲלֶ֣ה] [נְשִׂאִים֮] [מִקְצֵ֢ה] a-terra [בְּרָקִ֣ים] [לַמָּטָ֣ר] fez [מֽוֹצֵא־ר֝וּחַ] espírito');
INSERT INTO verses VALUES (16251, 19, 135, 8, '[שֶֽׁ֭הִכָּה] [בְּכוֹרֵ֣י] Egito [מֵ֝אָדָ֗ם] até animal');
INSERT INTO verses VALUES (16252, 19, 135, 9, '[שָׁלַ֤ח] [׀] [אֹת֣וֹת] Egito [בְּתוֹכֵ֣כִי] e-em-todo [בְּ֝פַרְעֹ֗ה]');
INSERT INTO verses VALUES (16253, 19, 135, 10, '[שֶֽׁ֭הִכָּה] nações [רַבִּ֑ים] [וְ֝הָרַ֗ג] [מְלָכִ֥ים] [עֲצוּמִֽים]');
INSERT INTO verses VALUES (16254, 19, 135, 11, '[לְסִיח֤וֹן] rei [מֶ֤לֶךְ] [הָאֱמֹרִ֗י] rei [מֶ֣לֶךְ] [הַבָּשָׁ֑ן] reinos [מַמְלְכ֥וֹת]');
INSERT INTO verses VALUES (16255, 19, 135, 12, '[וְנָתַ֣ן] [אַרְצָ֣ם] [נַחֲלָ֑ה] [נַ֝חֲלָ֗ה] [לְיִשְׂרָאֵ֥ל] seu-povo');
INSERT INTO verses VALUES (16256, 19, 135, 13, 'yhwh teu-nome para-sempre yhwh [זִכְרְךָ֥] [לְדֹר־וָדֹֽר]');
INSERT INTO verses VALUES (16257, 19, 135, 14, 'porque yhwh yhwh [וְעַל־עֲ֝בָדָ֗יו] e-sobre');
INSERT INTO verses VALUES (16258, 19, 135, 15, '[עֲצַבֵּ֣י] [הַ֭גּוֹיִם] prata [וְזָהָ֑ב] [מַ֝עֲשֵׂ֗ה] maos-de homem');
INSERT INTO verses VALUES (16259, 19, 135, 16, '[פֶּֽה־לָ֭הֶם] [וְלֹ֣א] e-não [עֵינַ֥יִם] a-eles [וְלֹ֣א] e-não');
INSERT INTO verses VALUES (16260, 19, 135, 17, '[אָזְנַ֣יִם] a-eles e-não [יַאֲזִ֑ינוּ] certamente não-há [בְּפִיהֶֽם] espírito');
INSERT INTO verses VALUES (16261, 19, 135, 18, '[כְּ֭מוֹהֶם] serão [עֹשֵׂיהֶ֑ם] todo que [בָּהֶֽם]');
INSERT INTO verses VALUES (16262, 19, 135, 19, 'casa Israel [בָּרֲכ֣וּ] a yhwh casa [בָּרֲכ֥וּ] [אֶת־יְהוָֽה] a yhwh');
INSERT INTO verses VALUES (16263, 19, 135, 20, 'casa [הַ֭לֵּוִי] [בָּרֲכ֣וּ] a yhwh yhwh yhwh [אֶת־יְהוָֽה] a yhwh');
INSERT INTO verses VALUES (16264, 19, 135, 21, '[בָּ֘ר֤וּךְ] yhwh [׀] [מִצִיּ֗וֹן] [שֹׁ֘כֵ֤ן] louvai [הַֽלְלוּ־יָֽהּ]');
INSERT INTO chapters VALUES (614, 19, 136, 26);
INSERT INTO verses VALUES (16265, 19, 136, 1, '[הוֹד֣וּ] a-yhwh porque que porque para-sempre');
INSERT INTO verses VALUES (16266, 19, 136, 2, '[ה֭וֹדוּ] [לֵֽאלֹהֵ֣י] o-Elohim que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16267, 19, 136, 3, '[ה֭וֹדוּ] [לַאֲדֹנֵ֣י] [הָאֲדֹנִ֑ים] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16268, 19, 136, 4, '[לְעֹ֘שֵׂ֤ה] [נִפְלָא֣וֹת] [גְּדֹל֣וֹת] sozinho que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16269, 19, 136, 5, '[לְעֹשֵׂ֣ה] os-céus [בִּתְבוּנָ֑ה] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16270, 19, 136, 6, '[לְרֹקַ֣ע] a-terra sobre que porque para-sempre');
INSERT INTO verses VALUES (16271, 19, 136, 7, '[לְ֭עֹשֵׂה] [אוֹרִ֣ים] [גְּדֹלִ֑ים] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16272, 19, 136, 8, 'a [לְמֶמְשֶׁ֣לֶת] no-dia que porque para-sempre');
INSERT INTO verses VALUES (16273, 19, 136, 9, 'a [וְ֭כוֹכָבִים] [לְמֶמְשְׁל֣וֹת] [בַּלָּ֑יְלָה] que porque para-sempre');
INSERT INTO verses VALUES (16274, 19, 136, 10, '[לְמַכֵּ֣ה] [מִ֭צְרַיִם] [בִּבְכוֹרֵיהֶ֑ם] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16275, 19, 136, 11, '[וַיּוֹצֵ֣א] Israel [מִתּוֹכָ֑ם] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16276, 19, 136, 12, '[בְּיָ֣ד] [חֲ֭זָקָה] [וּבִזְר֣וֹעַ] [נְטוּיָ֑ה] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16277, 19, 136, 13, '[לְגֹזֵ֣ר] [יַם־ס֭וּף] [לִגְזָרִ֑ים] que porque para-sempre');
INSERT INTO verses VALUES (16278, 19, 136, 14, '[וְהֶעֱבִ֣יר] Israel [בְּתוֹכ֑וֹ] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16279, 19, 136, 15, '[וְנִ֘עֵ֤ר] [פַּרְעֹ֣ה] [וְחֵיל֣וֹ] [בְיַם־ס֑וּף] que porque para-sempre');
INSERT INTO verses VALUES (16280, 19, 136, 16, '[לְמוֹלִ֣יךְ] [עַ֭מּוֹ] no-deserto que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16281, 19, 136, 17, '[לְ֭מַכֵּה] [מְלָכִ֣ים] [גְּדֹלִ֑ים] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16282, 19, 136, 18, '[וֽ͏ַ֭יַּהֲרֹג] [מְלָכִ֣ים] [אַדִּירִ֑ים] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16283, 19, 136, 19, '[לְ֭סִיחוֹן] rei [הָאֱמֹרִ֑י] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16284, 19, 136, 20, '[וּ֭לְעוֹג] rei [הַבָּשָׁ֑ן] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16285, 19, 136, 21, '[וְנָתַ֣ן] [אַרְצָ֣ם] [לְנַחֲלָ֑ה] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16286, 19, 136, 22, '[נַ֭חֲלָה] [לְיִשְׂרָאֵ֣ל] seu-servo que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16287, 19, 136, 23, '[שֶׁ֭בְּשִׁפְלֵנוּ] macho [לָ֑נוּ] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16288, 19, 136, 24, '[וַיִּפְרְקֵ֥נוּ] [מִצָּרֵ֑ינוּ] que para-sempre sua-misericórdia');
INSERT INTO verses VALUES (16289, 19, 136, 25, 'deu pão para-todo que porque para-sempre');
INSERT INTO verses VALUES (16290, 19, 136, 26, '[ה֭וֹדוּ] a-El os-céus que para-sempre sua-misericórdia');
INSERT INTO chapters VALUES (615, 19, 137, 9);
INSERT INTO verses VALUES (16291, 19, 137, 1, 'sobre [נַהֲר֨וֹת] [׀] nome [שָׁ֣ם] também [גַּם־בָּכִ֑ינוּ] [בְּ֝זָכְרֵ֗נוּ] a');
INSERT INTO verses VALUES (16292, 19, 137, 2, 'sobre [בְּתוֹכָ֑הּ] [תָּ֝לִ֗ינוּ] [כִּנֹּרוֹתֵֽינוּ]');
INSERT INTO verses VALUES (16293, 19, 137, 3, 'que nome [שְֽׁאֵל֪וּנוּ] [שׁוֹבֵ֡ינוּ] [דִּבְרֵי־שִׁ֭יר] [וְתוֹלָלֵ֣ינוּ] [שִׂמְחָ֑ה] [שִׁ֥ירוּ] [לָ֝֗נוּ] [מִשִּׁ֥יר] [צִיּֽוֹן]');
INSERT INTO verses VALUES (16294, 19, 137, 4, '[אֵ֗יךְ] [נָשִׁ֥יר] a sobre yhwh sobre');
INSERT INTO verses VALUES (16295, 19, 137, 5, 'se [יְֽרוּשָׁלִָ֗ם] [תִּשְׁכַּ֥ח] [יְמִינֽ͏ִי]');
INSERT INTO verses VALUES (16296, 19, 137, 6, '[תִּדְבַּֽק־לְשׁוֹנִ֨י] [׀] [לְחִכִּי֮] se não [אִם־לֹ֣א] se não sobre a [שִׂמְחָתֽ͏ִי] sobre cabeça');
INSERT INTO verses VALUES (16297, 19, 137, 7, 'macho yhwh [׀] [לִבְנֵ֬י] [OBJ] dia dia [יְֽרוּשָׁ֫לָ֥͏ִם] [הָ֭אֹ֣מְרִים] [עָ֤רוּ] até [עָ֑רוּ] [עָ֝֗ד]');
INSERT INTO verses VALUES (16298, 19, 137, 8, 'filha-de [הַשְּׁד֫וּדָ֥ה] [אַשְׁרֵ֥י] [שֶׁיְשַׁלֶּם־לָ֑ךְ] [אֶת־גְּ֝מוּלֵ֗ךְ] a-ti a');
INSERT INTO verses VALUES (16299, 19, 137, 9, '[אַשְׁרֵ֤י] [׀] [שֶׁיֹּאחֵ֓ז] a [אֶֽת־עֹלָלַ֗יִךְ] a');
INSERT INTO chapters VALUES (616, 19, 138, 8);
INSERT INTO verses VALUES (16300, 19, 138, 1, 'a-Davi [׀] em-todo meu-coração diante Elohim [אֲזַמְּרֶֽךָּ]');
INSERT INTO verses VALUES (16301, 19, 138, 2, '[אֶשְׁתַּחֲוֶ֨ה] a [קָדְשְׁךָ֡] [וְא֘וֹדֶ֤ה] [אֶת־שְׁמֶ֗ךָ] a [וְעַל־אֲמִתֶּ֑ךָ] sobre [עַל־כָּל־שִׁ֝מְךָ֗] e-sobre porque sobre todo');
INSERT INTO verses VALUES (16302, 19, 138, 3, 'no-dia [קָ֭רָֽאתִי] [וַֽתַּעֲנֵ֑נִי] [תַּרְהִבֵ֖נִי] [בְנַפְשִׁ֣י] [עֹֽז]');
INSERT INTO verses VALUES (16303, 19, 138, 4, '[יוֹד֣וּךָ] yhwh todo que terra porque');
INSERT INTO verses VALUES (16304, 19, 138, 5, '[וְ֭יָשִׁירוּ] [בְּדַרְכֵ֣י] yhwh porque grande yhwh yhwh');
INSERT INTO verses VALUES (16305, 19, 138, 6, 'porque yhwh yhwh [יִרְאֶ֑ה] [וְ֝גָבֹ֗הַּ] [מִמֶּרְחָ֥ק] [יְיֵדָֽע]');
INSERT INTO verses VALUES (16306, 19, 138, 7, 'se [׀] [בְּקֶ֥רֶב] [צָרָ֗ה] [תְּחַ֫יֵּ֥נִי] sobre certamente [אֹ֖[d]יְבַי] tua-mao [יָדֶ֑ךָ] [וְת֖וֹשִׁיעֵ֣נִי]');
INSERT INTO verses VALUES (16307, 19, 138, 8, 'yhwh [יִגְמֹ֢ר] [בַּ֫עֲדִ֥י] yhwh [חַסְדְּךָ֣] para-sempre [מַעֲשֵׂ֖י] tuas-maos a [sem-traducao]');
INSERT INTO chapters VALUES (617, 19, 139, 24);
INSERT INTO verses VALUES (16308, 19, 139, 1, '[לַ֭מְנַצֵּחַ] a-Davi [מִזְמ֑וֹר] yhwh [חֲ֝קַרְתַּ֗נִי] [וַתֵּדָֽע]');
INSERT INTO verses VALUES (16309, 19, 139, 2, 'tu [יָ֭דַעְתָּ] [שִׁבְתִּ֣י] [וְקוּמִ֑י] [בַּ֥נְתָּה] [לְ֝רֵעִ֗י] [מֵרָחֽוֹק]');
INSERT INTO verses VALUES (16310, 19, 139, 3, '[אָרְחִ֣י] [וְרִבְעִ֣י] [זֵרִ֑יתָ] e-todo [הִסְכַּֽנְתָּה]');
INSERT INTO verses VALUES (16311, 19, 139, 4, 'que não-há [מִ֭לָּה] [בִּלְשׁוֹנִ֑י] eis yhwh [יָדַ֥עְתָּ] [כֻלָּֽהּ]');
INSERT INTO verses VALUES (16312, 19, 139, 5, '[אָח֣וֹר] [וָקֶ֣דֶם] [צַרְתָּ֑נִי] [וַתָּ֖שֶׁת] sobre-mim [כַּפֶּֽכָה]');
INSERT INTO verses VALUES (16313, 19, 139, 6, '[*פלאיה] [**פְּלִ֣יאָֽה] [דַ֣עַת] não [נִ֝שְׂגְּבָ֗ה] a-ela');
INSERT INTO verses VALUES (16314, 19, 139, 7, '[אָ֭נָ֥ה] [אֵלֵ֣ךְ] [מֵרוּחֶ֑ךָ] [וְ֝אָ֗נָה] [מִפָּנֶ֥יךָ] [אֶבְרָֽח]');
INSERT INTO verses VALUES (16315, 19, 139, 8, 'se [שָׁ֭מַיִם] céus nome tu [שְּׁא֣וֹל] [הִנֶּֽךָּ]');
INSERT INTO verses VALUES (16316, 19, 139, 9, '[אֶשָּׂ֥א] [כַנְפֵי־שָׁ֑חַר] [אֶ֝שְׁכְּנָ֗ה] [בְּאַחֲרִ֥ית] mar');
INSERT INTO verses VALUES (16317, 19, 139, 10, 'também nome [תַנְחֵ֑נִי] [וְֽתֹאחֲזֵ֥נִי] [יְמִינֶֽךָ]');
INSERT INTO verses VALUES (16318, 19, 139, 11, '[וָ֭אֹמַר] somente escuridão [וְ֝לַ֗יְלָה] luz luz');
INSERT INTO verses VALUES (16319, 19, 139, 12, 'também escuridão não [וְ֭לַיְלָה] [כַּיּ֣וֹם] [יָאִ֑יר] [כַּ֝חֲשֵׁיכָ֗ה] [כָּאוֹרָֽה]');
INSERT INTO verses VALUES (16320, 19, 139, 13, 'porque [קָנִ֣יתָ] [כִלְיֹתָ֑י] [תְּ֝סֻכֵּ֗נִי] [בְּבֶ֣טֶן] [אִמִּֽי]');
INSERT INTO verses VALUES (16321, 19, 139, 14, '[אֽוֹדְךָ֗] sobre que [נוֹרָא֗וֹת] [נִ֫פְלֵ֥יתִי] [נִפְלָאִ֥ים] [מַעֲשֶׂ֑יךָ] [וְ֝נַפְשִׁ֗י] [יֹדַ֥עַת] muito');
INSERT INTO verses VALUES (16322, 19, 139, 15, 'não [עָצְמִ֗י] [מִ֫מֶּ֥ךָּ] [אֲשֶׁר־עֻשֵּׂ֥יתִי] que [רֻ֝קַּ֗מְתִּי] [בְּֽתַחְתִּיּ֥וֹת] [אָֽרֶץ] terra');
INSERT INTO verses VALUES (16323, 19, 139, 16, '[גָּלְמִ֤י] [׀] [רָ֘א֤וּ] e-sobre [וְעַֽל־סִפְרְךָ֮] [כֻּלָּ֢ם] [יִכָּ֫תֵ֥בוּ] dias [יֻצָּ֑רוּ] um [**וְל֖וֹ]');
INSERT INTO verses VALUES (16324, 19, 139, 17, '[וְלִ֗י] que [רֵעֶ֣יךָ] El [עָ֝צְמוּ] [רָאשֵׁיהֶֽם]');
INSERT INTO verses VALUES (16325, 19, 139, 18, '[אֶ֭סְפְּרֵם] [מֵח֣וֹל] [יִרְבּ֑וּן] [הֱ֝קִיצֹ֗תִי] [וְעוֹדִ֥י] [עִמָּֽךְ]');
INSERT INTO verses VALUES (16326, 19, 139, 19, 'se [אֱל֥וֹהַּ] [׀] ímpio [וְאַנְשֵׁ֥י] [דָ֝מִ֗ים] [ס֣וּרוּ] [מֶֽנִּי]');
INSERT INTO verses VALUES (16327, 19, 139, 20, 'que [יֹ֭אמְרֻךָ] [לִמְזִמָּ֑ה] [נָשֻׂ֖א] [לַשָּׁ֣וְא] [עָרֶֽיךָ]');
INSERT INTO verses VALUES (16328, 19, 139, 21, 'acaso-nao yhwh [׀] [אֶשְׂנָ֑א] [וּ֝בִתְקוֹמְמֶ֗יךָ] [אֶתְקוֹטָֽט]');
INSERT INTO verses VALUES (16329, 19, 139, 22, '[תַּכְלִ֣ית] [שִׂנְאָ֣ה] [שְׂנֵאתִ֑ים] [לְ֝אוֹיְבִ֗ים] [הָ֣יוּ] a-mim');
INSERT INTO verses VALUES (16330, 19, 139, 23, '[חָקְרֵ֣נִי] El [וְדַ֣ע] [לְבָבִ֑י] [בְּ֝חָנֵ֗נִי] [וְדַ֣ע] [שַׂרְעַפָּֽי]');
INSERT INTO verses VALUES (16331, 19, 139, 24, '[וּרְאֵ֗ה] se [בִּ֑י] [וּ֝נְחֵ֗נִי] em-mim eternidade');
INSERT INTO chapters VALUES (618, 19, 140, 14);
INSERT INTO verses VALUES (16332, 19, 140, 1, 'ao-regente salmo de-Davi');
INSERT INTO verses VALUES (16333, 19, 140, 2, '[חַלְּצֵ֣נִי] yhwh [מֵאָדָ֣ם] mal [מֵאִ֖ישׁ] [חֲמָסִ֣ים] [תִּנְצְרֵֽנִי]');
INSERT INTO verses VALUES (16334, 19, 140, 3, 'que [חָשְׁב֣וּ] [רָע֣וֹת] [בְּלֵ֑ב] todo dia [מִלְחָמֽוֹת]');
INSERT INTO verses VALUES (16335, 19, 140, 4, '[שָֽׁנֲנ֣וּ] [לְשׁוֹנָם֮] [כְּֽמוֹ] [נָ֫חָ֥שׁ] [חֲמַ֥ת] [עַכְשׁ֑וּב] debaixo [שְׂפָתֵ֣ימוֹ] Selá');
INSERT INTO verses VALUES (16336, 19, 140, 5, '[שָׁמְרֵ֤נִי] yhwh [׀] [מִ֘ידֵ֤י] [רָשָׁ֗ע] [מֵאִ֣ישׁ] [חֲמָסִ֣ים] que [אֲשֶׁ֥ר] [חָ֝שְׁב֗וּ] [לִדְח֥וֹת]');
INSERT INTO verses VALUES (16337, 19, 140, 6, '[טָֽמְנֽוּ־גֵאִ֨ים] [׀] [פַּ֡ח] [לִ֗י] [וַחֲבָלִ֗ים] [פָּ֣רְשׂוּ] [רֶ֭שֶׁת] [לְיַד־מַעְגָּ֑ל] [מֹקְשִׁ֖ים] [שָֽׁתוּ־לִ֣י] [סֶֽלָה]');
INSERT INTO verses VALUES (16338, 19, 140, 7, 'eu-disse [לַ֭יהוָה] [אֵ֣לִי] tu [הַאֲזִ֥ינָה] yhwh voz [תַּחֲנוּנָֽי]');
INSERT INTO verses VALUES (16339, 19, 140, 8, 'yhwh Adonai [עֹ֣ז] [יְשׁוּעָתִ֑י] [סַכֹּ֥תָה] [לְ֝רֹאשִׁ֗י] no-dia [נָֽשֶׁק]');
INSERT INTO verses VALUES (16340, 19, 140, 9, 'a yhwh yhwh [רָשָׁ֑ע] ímpio [אַל־תָּ֝פֵ֗ק] a [סֶֽלָה]');
INSERT INTO verses VALUES (16341, 19, 140, 10, 'cabeça [מְסִבָּ֑י] [עֲמַ֖ל] [שְׂפָתֵ֣ימוֹ]');
INSERT INTO verses VALUES (16342, 19, 140, 11, 'sobre-eles [**יִמּ֥וֹטוּ] [עֲלֵיהֶ֗ם] [גֶּֽחָ֫לִ֥ים] [בָּאֵ֥שׁ] [יַפִּלֵ֑ם] [בְּ֝מַהֲמֹר֗וֹת]');
INSERT INTO verses VALUES (16343, 19, 140, 12, 'homem [לָשׁוֹן֮] não [בָּ֫אָ֥רֶץ] [אִישׁ־חָמָ֥ס] mal [יְ֝צוּדֶ֗נּוּ] mau');
INSERT INTO verses VALUES (16344, 19, 140, 13, 'porque [**יָדַ֗עְתִּי] yhwh yhwh [דִּ֣ין] [עָנִ֑י] [מִ֝שְׁפַּ֗ט]');
INSERT INTO verses VALUES (16345, 19, 140, 14, 'somente [צַ֭דִּיקִים] [יוֹד֣וּ] [לִשְׁמֶ֑ךָ] [יֵשְׁב֥וּ] [יְ֝שָׁרִ֗ים] a teu-rosto');
INSERT INTO chapters VALUES (619, 19, 141, 10);
INSERT INTO verses VALUES (16346, 19, 141, 1, 'salmo para-Davi yhwh [קְ֭רָאתִיךָ] [ח֣וּשָׁה] a-mim [הַאֲזִ֥ינָה] [ק֝וֹלִ֗י] [בְּקָרְאִי־לָֽךְ] para-ti');
INSERT INTO verses VALUES (16347, 19, 141, 2, '[תִּכּ֤וֹן] [תְּפִלָּתִ֣י] [קְטֹ֣רֶת] [לְפָנֶ֑יךָ] [מַֽשְׂאַ֥ת] [כַּ֝פַּ֗י] [מִנְחַת־עָֽרֶב] tarde');
INSERT INTO verses VALUES (16348, 19, 141, 3, '[שִׁיתָ֣ה] yhwh [שָׁמְרָ֣ה] [לְפִ֑י] [נִ֝צְּרָ֗ה] sobre [שְׂפָתָֽי]');
INSERT INTO verses VALUES (16349, 19, 141, 4, 'a [לְדָבָ֪ר] [׀] mal mau [עֲלִל֨וֹת] [׀] [בְּרֶ֗שַׁע] a [פֹּֽעֲלֵי־אָ֑וֶן] [וּבַל־אֶ֝לְחַ֗ם] iniquidade');
INSERT INTO verses VALUES (16350, 19, 141, 5, '[יֶֽהֶלְמֵֽנִי־צַדִּ֨יק] [׀] [חֶ֡סֶד] [וְֽיוֹכִיחֵ֗נִי] óleo cabeça a [רֹאשִׁ֑י] [כִּי־ע֥וֹד] porque [בְּרָעוֹתֵיהֶֽם]');
INSERT INTO verses VALUES (16351, 19, 141, 6, '[נִשְׁמְט֣וּ] [בִֽידֵי־סֶ֭לַע] [שֹׁפְטֵיהֶ֑ם] [וְשָׁמְע֥וּ] [אֲ֝מָרַ֗י] que porque');
INSERT INTO verses VALUES (16352, 19, 141, 7, '[כְּמ֤וֹ] [פֹלֵ֣חַ] [וּבֹקֵ֣עַ] [בָּאָ֑רֶץ] [נִפְזְר֥וּ] [עֲ֝צָמֵ֗ינוּ] [לְפִ֣י] [שְׁאֽוֹל]');
INSERT INTO verses VALUES (16353, 19, 141, 8, 'que [אֵלֶ֨יךָ] yhwh Adonai meus-olhos [עֵינָ֑י] [בְּכָ֥ה] a [אַל־תְּעַ֥ר] [נַפְשִֽׁי]');
INSERT INTO verses VALUES (16354, 19, 141, 9, '[שָׁמְרֵ֗נִי] [מִ֣ידֵי] [פַ֭ח] [יָ֣קְשׁוּ] a-mim [וּ֝מֹקְשׁ֗וֹת] [פֹּ֣עֲלֵי] iniquidade');
INSERT INTO verses VALUES (16355, 19, 141, 10, '[יִפְּל֣וּ] [בְמַכְמֹרָ֣יו] [רְשָׁעִ֑ים] [יַ֥חַד] eu até');
INSERT INTO chapters VALUES (620, 19, 142, 8);
INSERT INTO verses VALUES (16356, 19, 142, 1, '[מַשְׂכִּ֥יל] para-Davi [בִּהְיוֹת֖וֹ] [בַמְּעָרָ֣ה] [תְפִלָּֽה]');
INSERT INTO verses VALUES (16357, 19, 142, 2, '[ק֭וֹלִי] a yhwh [ק֝וֹלִ֗י] [אֶל־יְהוָ֥ה] a yhwh');
INSERT INTO verses VALUES (16358, 19, 142, 3, '[אֶשְׁפֹּ֣ךְ] [לְפָנָ֣יו] [שִׂיחִ֑י] [צָ֝רָתִ֗י] [לְפָנָ֥יו] [אַגִּֽיד]');
INSERT INTO verses VALUES (16359, 19, 142, 4, '[בְּהִתְעַטֵּ֬ף] [עָלַ֨י] [׀] [רוּחִ֗י] [וְאַתָּה֮] [יָדַ֢עְתָּ] [נְֽתִיבָ֫תִ֥י] [בְּאֹֽרַח־ז֥וּ] [אֲהַלֵּ֑ךְ] [טָמְנ֖וּ] [פַ֣ח] a-mim');
INSERT INTO verses VALUES (16360, 19, 142, 5, '[הַבֵּ֤יט] [יָמִ֨ין] [׀] e-nao-ha [וְאֵֽין־לִ֢י] [מַ֫כִּ֥יר] [אָבַ֣ד] [מָנ֣וֹס] [מִמֶּ֑נִּי] [אֵ֖ין] [דּוֹרֵ֣שׁ] [לְנַפְשִֽׁי]');
INSERT INTO verses VALUES (16361, 19, 142, 6, '[זָעַ֥קְתִּי] [אֵלֶ֗יךָ] yhwh [אָ֭מַרְתִּי] tu [מַחְסִ֑י] [חֶ֝לְקִ֗י] na-terra a-vida');
INSERT INTO verses VALUES (16362, 19, 142, 7, '[הַקְשִׁ֤יבָה] a [אֶֽל־רִנָּתִי֮] porque muito [הַצִּילֵ֥נִי] [מֵרֹדְפַ֑י] que porque [מִמֶּֽנִּי]');
INSERT INTO verses VALUES (16363, 19, 142, 8, '[ה֘וֹצִ֤יאָה] [מִמַּסְגֵּ֨ר] [׀] [נַפְשִׁי֮] a [אֶת־שְׁ֫מֶ֥ךָ] [בִּ֭י] [יַכְתִּ֣רוּ] [צַדִּיקִ֑ים] que [תִגְמֹ֣ל] [עָלֽ͏ָי]');
INSERT INTO chapters VALUES (621, 19, 143, 12);
INSERT INTO verses VALUES (16364, 19, 143, 1, 'salmo para-Davi yhwh ouviu [שְׁמַ֬ע] [תְּפִלָּתִ֗י] a [אֶל־תַּחֲנוּנַ֑י] [בֶּאֱמֻנָתְךָ֥] [עֲ֝נֵ֗נִי] [בְּצִדְקָתֶֽךָ]');
INSERT INTO verses VALUES (16365, 19, 143, 2, 'e-a [בְ֭מִשְׁפָּט] [אֶת־עַבְדֶּ֑ךָ] que [לֹֽא־יִצְדַּ֖ק] porque não todo viveu');
INSERT INTO verses VALUES (16366, 19, 143, 3, 'que [רָ֘דַ֤ף] [אוֹיֵ֨ב] [׀] [נַפְשִׁ֗י] [דִּכָּ֣א] [לָ֭אָרֶץ] [חַיָּתִ֑י] [הוֹשִׁיבַ֥נִי] [בְ֝מַחֲשַׁכִּ֗ים] eternidade');
INSERT INTO verses VALUES (16367, 19, 143, 4, '[וַתִּתְעַטֵּ֣ף] sobre-mim [רוּחִ֑י] [בְּ֝תוֹכִ֗י] [יִשְׁתּוֹמֵ֥ם] [לִבִּֽי]');
INSERT INTO verses VALUES (16368, 19, 143, 5, '[זָ֘כַ֤רְתִּי] [יָמִ֨ים] [׀] ao-oriente em-todo [בְכָל־פָּעֳלֶ֑ךָ] [בְּֽמַעֲשֵׂ֖ה] tuas-maos [אֲשׂוֹחֵֽחַ]');
INSERT INTO verses VALUES (16369, 19, 143, 6, '[פֵּרַ֣שְׂתִּי] [יָדַ֣י] a-ti [נַפְשִׁ֓י] [׀] [כְּאֶֽרֶץ־עֲיֵפָ֖ה] a-ti Selá');
INSERT INTO verses VALUES (16370, 19, 143, 7, '[מַ֘הֵ֤ר] [עֲנֵ֨נִי] yhwh yhwh [כָּלְתָ֢ה] a [אַל־תַּסְתֵּ֣ר] [פָּנֶ֣יךָ] [מִמֶּ֑נִּי] [וְ֝נִמְשַׁ֗לְתִּי] com [בֽוֹר]');
INSERT INTO verses VALUES (16371, 19, 143, 8, '[הַשְׁמִ֘יעֵ֤נִי] [בַבֹּ֨קֶר] [׀] porque [כִּֽי־בְךָ֢] [בָ֫טָ֥חְתִּי] [הוֹדִיעֵ֗נִי] [דֶּֽרֶךְ־ז֥וּ] [אֵלֵ֑ךְ] [כִּֽי־אֵ֝לֶיךָ] porque [נַפְשִֽׁי]');
INSERT INTO verses VALUES (16372, 19, 143, 9, '[הַצִּילֵ֖נִי] [מֵאֹיְבַ֥י] yhwh yhwh [אֵלֶ֥יךָ]');
INSERT INTO verses VALUES (16373, 19, 143, 10, '[לַמְּדֵ֤נִי] [׀] [לַֽעֲשׂ֣וֹת] porque [כִּֽי־אַתָּ֢ה] [אֱל֫וֹהָ֥י] [רוּחֲךָ֥] boa [תַּ֝נְחֵ֗נִי] na-terra [מִישֽׁוֹר]');
INSERT INTO verses VALUES (16374, 19, 143, 11, '[לְמַֽעַן־שִׁמְךָ֣] yhwh yhwh [בְּצִדְקָתְךָ֓] [׀] [תּוֹצִ֖יא] [מִצָּרָ֣ה] [נַפְשִֽׁי]');
INSERT INTO verses VALUES (16375, 19, 143, 12, '[וּֽבְחַסְדְּךָ֮] [תַּצְמִ֢ית] [אֹ֫יְבָ֥י] [וְֽ֭הַאֲבַדְתָּ] todo [נַפְשִׁ֑י] que porque eu');
INSERT INTO chapters VALUES (622, 19, 144, 15);
INSERT INTO verses VALUES (16376, 19, 144, 1, 'a-Davi [׀] yhwh yhwh [׀] [צוּרִ֗י] [הַֽמְלַמֵּ֣ד] [יָדַ֣י] [לַקְרָ֑ב]');
INSERT INTO verses VALUES (16377, 19, 144, 2, '[חַסְדִּ֥י] [וּמְצוּדָתִי֮] [מִשְׂגַּבִּ֢י] [וּֽמְפַלְטִ֫י] para-mim [מָ֭גִנִּי] [וּב֣וֹ] [חָסִ֑יתִי] [הָרוֹדֵ֖ד] meu-povo [תַחְתָּֽי]');
INSERT INTO verses VALUES (16378, 19, 144, 3, 'yhwh o-quê homem [בֶּן־אֱ֝נ֗וֹשׁ] filho-de');
INSERT INTO verses VALUES (16379, 19, 144, 4, 'homem [לַהֶ֣בֶל] [דָּמָ֑ה] [יָ֝מָ֗יו] [כְּצֵ֣ל] [עוֹבֵֽר]');
INSERT INTO verses VALUES (16380, 19, 144, 5, 'yhwh [הַט־שָׁמֶ֣יךָ] [וְתֵרֵ֑ד] [גַּ֖ע] [בֶּהָרִ֣ים] [וְֽיֶעֱשָֽׁנוּ]');
INSERT INTO verses VALUES (16381, 19, 144, 6, '[בְּר֣וֹק] [בָּ֭רָק] [וּתְפִיצֵ֑ם] enviou [חִ֝צֶּ֗יךָ] [וּתְהֻמֵּֽם]');
INSERT INTO verses VALUES (16382, 19, 144, 7, 'enviou [יָדֶ֗יךָ] [מִמָּ֫ר֥וֹם] [פְּצֵ֣נִי] [וְ֭הַצִּילֵנִי] [מִמַּ֣יִם] [רַבִּ֑ים] [מִ֝יַּ֗ד] filhos-de [נֵכָֽר]');
INSERT INTO verses VALUES (16383, 19, 144, 8, 'que [פִּ֭יהֶם] [דִּבֶּר־שָׁ֑וְא] [וִֽ֝ימִינָ֗ם] [יְמִ֣ין] [שָֽׁקֶר]');
INSERT INTO verses VALUES (16384, 19, 144, 9, 'Elohim [שִׁ֣יר] novo [אָשִׁ֣ירָה] [לָּ֑ךְ] [בְּנֵ֥בֶל] [עָ֝שׂ֗וֹר] [אֲזַמְּרָה־לָּֽךְ] para-ti');
INSERT INTO verses VALUES (16385, 19, 144, 10, '[הַנּוֹתֵ֥ן] [תְּשׁוּעָ֗ה] [לַמְּלָ֫כִ֥ים] [הַ֭פּוֹצֶה] a Davi [מֵחֶ֥רֶב] [רָעָֽה]');
INSERT INTO verses VALUES (16386, 19, 144, 11, '[פְּצֵ֥נִי] [וְהַצִּילֵנִי֮] [מִיַּ֢ד] [בְּֽנֵי־נֵ֫כָ֥ר] [אֲשֶׁ֣ר] que [דִּבֶּר־שָׁ֑וְא] [וִֽ֝ימִינָ֗ם] [יְמִ֣ין] [שָֽׁקֶר]');
INSERT INTO verses VALUES (16387, 19, 144, 12, 'que [בָּנֵ֨ינוּ] [׀] [כִּנְטִעִים֮] [מְגֻדָּלִ֢ים] [בִּֽנְעוּרֵ֫יהֶ֥ם] [בְּנוֹתֵ֥ינוּ] [כְזָוִיֹּ֑ת] [מְ֝חֻטָּב֗וֹת] [תַּבְנִ֥ית]');
INSERT INTO verses VALUES (16388, 19, 144, 13, '[מְזָוֵ֣ינוּ] [מְלֵאִים֮] [מְפִיקִ֥ים] [מִזַּ֗ן] a [צֹאונֵ֣נוּ] [מַ֭אֲלִיפוֹת] [מְרֻבָּב֗וֹת] [בְּחוּצוֹתֵֽינוּ]');
INSERT INTO verses VALUES (16389, 19, 144, 14, '[אַלּוּפֵ֗ינוּ] [מְֽסֻבָּ֫לִ֥ים] não-há [וְאֵ֣ין] e-não-há [וְאֵ֥ין] e-não-há [בִּרְחֹבֹתֵֽינוּ]');
INSERT INTO verses VALUES (16390, 19, 144, 15, '[אַשְׁרֵ֣י] [הָ֭עָם] [שֶׁכָּ֣כָה] para-ele [אַֽשְׁרֵ֥י] [הָ֝עָ֗ם] [שֶׁיֲהוָ֥ה] [אֱלֹהָֽיו]');
INSERT INTO chapters VALUES (623, 19, 145, 21);
INSERT INTO verses VALUES (16391, 19, 145, 1, '[תְּהִלָּ֗ה] para-Davi [אֲרוֹמִמְךָ֣] [אֱלוֹהַ֣י] o-rei [וַאֲבָרֲכָ֥ה] [שִׁ֝מְךָ֗] [לְעוֹלָ֥ם] e-perpetuidade');
INSERT INTO verses VALUES (16392, 19, 145, 2, 'em-todo dia [וַאֲהַלְלָ֥ה] [שִׁ֝מְךָ֗] [לְעוֹלָ֥ם] [וָעֶֽד]');
INSERT INTO verses VALUES (16393, 19, 145, 3, 'grande yhwh [וּמְהֻלָּ֣ל] muito [וְ֝לִגְדֻלָּת֗וֹ] não-há [חֵֽקֶר]');
INSERT INTO verses VALUES (16394, 19, 145, 4, 'geração [לְ֭דוֹר] [יְשַׁבַּ֣ח] [מַעֲשֶׂ֑יךָ] [וּגְב֖וּרֹתֶ֣יךָ] [יַגִּֽידוּ]');
INSERT INTO verses VALUES (16395, 19, 145, 5, '[הֲ֭דַר] [כְּב֣וֹד] [הוֹדֶ֑ךָ] [וְדִבְרֵ֖י] [נִפְלְאוֹתֶ֣יךָ] [אָשִֽׂיחָה]');
INSERT INTO verses VALUES (16396, 19, 145, 6, '[וֶעֱז֣וּז] [נוֹרְאֹתֶ֣יךָ] [יֹאמֵ֑רוּ] [*וגדולתיך]');
INSERT INTO verses VALUES (16397, 19, 145, 7, 'macho chefe-de [יַבִּ֑יעוּ] [וְצִדְקָתְךָ֥] [יְרַנֵּֽנוּ]');
INSERT INTO verses VALUES (16398, 19, 145, 8, '[חַנּ֣וּן] [וְרַח֣וּם] yhwh [אֶ֥רֶךְ] [אַ֝פַּ֗יִם] [וּגְדָל־חָֽסֶד]');
INSERT INTO verses VALUES (16399, 19, 145, 9, '[טוֹב־יְהוָ֥ה] yhwh para-todo [עַל־כָּל־מַעֲשָֽׂיו] sobre todo');
INSERT INTO verses VALUES (16400, 19, 145, 10, '[יוֹד֣וּךָ] yhwh todo [וַ֝חֲסִידֶ֗יךָ] [יְבָרֲכֽוּכָה]');
INSERT INTO verses VALUES (16401, 19, 145, 11, '[כְּב֣וֹד] [מַלְכוּתְךָ֣] [יֹאמֵ֑רוּ] [וּגְבוּרָתְךָ֥] [יְדַבֵּֽרוּ]');
INSERT INTO verses VALUES (16402, 19, 145, 12, '[לְהוֹדִ֤יעַ] aos-filhos-de o-homem o-homem [גְּבוּרֹתָ֑יו] [וּ֝כְב֗וֹד] [הֲדַ֣ר]');
INSERT INTO verses VALUES (16403, 19, 145, 13, '[מַֽלְכוּתְךָ֗] [מַלְכ֥וּת] todo [וּ֝מֶֽמְשֶׁלְתְּךָ֗] [בְּכָל־דּ֥וֹר] em-todo');
INSERT INTO verses VALUES (16404, 19, 145, 14, '[סוֹמֵ֣ךְ] yhwh para-todo [וְ֝זוֹקֵ֗ף] [לְכָל־הַכְּפוּפִֽים] para-todo');
INSERT INTO verses VALUES (16405, 19, 145, 15, '[עֵֽינֵי־כֹ֭ל] todo a-ti [וְאַתָּ֤ה] e-tu [אֶת־אָכְלָ֣ם] a-eles a');
INSERT INTO verses VALUES (16406, 19, 145, 16, '[פּוֹתֵ֥חַ] a tua-mao [לְכָל־חַ֣י] para-todo viveu [sem-traducao]');
INSERT INTO verses VALUES (16407, 19, 145, 17, 'justo yhwh em-todo [וְ֝חָסִ֗יד] [בְּכָל־מַעֲשָֽׂיו] em-todo');
INSERT INTO verses VALUES (16408, 19, 145, 18, '[קָר֣וֹב] yhwh para-todo a-todo para-todo que [בֶאֱמֶֽת]');
INSERT INTO verses VALUES (16409, 19, 145, 19, '[רְצוֹן־יְרֵאָ֥יו] [יַעֲשֶׂ֑ה] [וְֽאֶת־שַׁוְעָתָ֥ם] e-[OBJ] [וְיוֹשִׁיעֵֽם]');
INSERT INTO verses VALUES (16410, 19, 145, 20, 'guardiao yhwh a e-[OBJ] [כָּל־הָרְשָׁעִ֣ים] e-[OBJ] todo [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (16411, 19, 145, 21, '[תְּהִלַּ֥ת] yhwh [יְֽדַבֶּ֫ר] [פִּ֥י] E-abençoou todo [שֵׁ֥ם] nome [לְעוֹלָ֥ם] [וָעֶֽד]');
INSERT INTO chapters VALUES (624, 19, 146, 10);
INSERT INTO verses VALUES (16412, 19, 146, 1, 'louvai [הַלְלִ֥י] [נַ֝פְשִׁ֗י] [אֶת־יְהוָֽה] a yhwh');
INSERT INTO verses VALUES (16413, 19, 146, 2, '[אֲהַלְלָ֣ה] yhwh [בְּחַיָּ֑י] [אֲזַמְּרָ֖ה] [לֵֽאלֹהַ֣י] [בְּעוֹדִֽי]');
INSERT INTO verses VALUES (16414, 19, 146, 3, 'a [בִנְדִיבִ֑ים] [בְּבֶן־אָדָ֓ם] [׀] [שֶׁ֤אֵֽין] a-ele a-ele');
INSERT INTO verses VALUES (16415, 19, 146, 4, '[תֵּצֵ֣א] [ר֭וּחוֹ] habitou [לְאַדְמָת֑וֹ] no-dia [הַ֝ה֗וּא] [אָבְד֥וּ] [עֶשְׁתֹּנֹתָֽיו]');
INSERT INTO verses VALUES (16416, 19, 146, 5, '[אַשְׁרֵ֗י] [שֶׁ֤אֵ֣ל] Jacó [בְּעֶזְר֑וֹ] [שִׂ֝בְר֗וֹ] sobre yhwh');
INSERT INTO verses VALUES (16417, 19, 146, 6, '[עֹשֶׂ֤ה] céus [שָׁ֘מַ֤יִם] a [אֶת־הַיָּ֥ם] e-[OBJ] todo que [לְעוֹלָֽם]');
INSERT INTO verses VALUES (16418, 19, 146, 7, 'fez [מִשְׁפָּ֨ט] [׀] deu [נֹתֵ֣ן] pão yhwh yhwh [מַתִּ֥יר]');
INSERT INTO verses VALUES (16419, 19, 146, 8, 'yhwh [׀] [פֹּ֘קֵ֤חַ] yhwh yhwh [זֹקֵ֣ף] yhwh yhwh [אֹהֵ֥ב]');
INSERT INTO verses VALUES (16420, 19, 146, 9, 'yhwh [׀] a [אֶת־גֵּרִ֗ים] [יָת֣וֹם] [וְאַלְמָנָ֣ה] [יְעוֹדֵ֑ד] [וְדֶ֖רֶךְ] ímpios [יְעַוֵּֽת]');
INSERT INTO verses VALUES (16421, 19, 146, 10, '[יִמְלֹ֤ךְ] yhwh [׀] [לְעוֹלָ֗ם] [אֱלֹהַ֣יִךְ] [צִ֭יּוֹן] [לְדֹ֥ר] louvai [הַֽלְלוּ־יָֽהּ]');
INSERT INTO chapters VALUES (625, 19, 147, 20);
INSERT INTO verses VALUES (16422, 19, 147, 1, 'louvai [יָ֨הּ] porque bom [זַמְּרָ֣ה] nosso-Elohim porque [נָאוָ֥ה] [תְהִלָּֽה] [sem-traducao]');
INSERT INTO verses VALUES (16423, 19, 147, 2, '[בּוֹנֵ֣ה] [יְרוּשָׁלַ֣͏ִם] yhwh [נִדְחֵ֖י] Israel [יְכַנֵּֽס]');
INSERT INTO verses VALUES (16424, 19, 147, 3, '[הָ֭רֹפֵא] [לִשְׁב֣וּרֵי] coração [וּ֝מְחַבֵּ֗שׁ] [לְעַצְּבוֹתָֽם]');
INSERT INTO verses VALUES (16425, 19, 147, 4, '[מוֹנֶ֣ה] [מִ֭סְפָּר] [לַכּוֹכָבִ֑ים] [לְ֝כֻלָּ֗ם] [שֵׁמ֥וֹת] chamaria');
INSERT INTO verses VALUES (16426, 19, 147, 5, 'grande [אֲדוֹנֵ֣ינוּ] e-grande [לִ֝תְבוּנָת֗וֹ] [אֵ֣ין] não-há [sem-traducao]');
INSERT INTO verses VALUES (16427, 19, 147, 6, '[מְעוֹדֵ֣ד] [עֲנָוִ֣ים] yhwh [מַשְׁפִּ֖יל] ímpios ate terra');
INSERT INTO verses VALUES (16428, 19, 147, 7, '[עֱנ֣וּ] a-yhwh [בְּתוֹדָ֑ה] [זַמְּר֖וּ] [לֵאלֹהֵ֣ינוּ] [בְכִנּֽוֹר]');
INSERT INTO verses VALUES (16429, 19, 147, 8, '[הַֽמְכַסֶּ֬ה] [שָׁמַ֨יִם] [׀] [בְּעָבִ֗ים] a-terra [לָאָ֣רֶץ] [מָטָ֑ר] os-montes [הָרִ֣ים]');
INSERT INTO verses VALUES (16430, 19, 147, 9, '[נוֹתֵ֣ן] [לִבְהֵמָ֣ה] [לַחְמָ֑הּ] para-os-filhos-de tarde que [יִקְרָֽאוּ]');
INSERT INTO verses VALUES (16431, 19, 147, 10, 'não [בִגְבוּרַ֣ת] [הַסּ֣וּס] [יֶחְפָּ֑ץ] não [הָאִ֣ישׁ] o-homem [sem-traducao]');
INSERT INTO verses VALUES (16432, 19, 147, 11, '[רוֹצֶ֣ה] yhwh a [אֶת־הַֽמְיַחֲלִ֥ים] a');
INSERT INTO verses VALUES (16433, 19, 147, 12, '[שַׁבְּחִ֣י] [יְ֭רוּשָׁלִַם] a yhwh [אֱלֹהַ֣יִךְ] [צִיּֽוֹן]');
INSERT INTO verses VALUES (16434, 19, 147, 13, 'porque [בְּרִיחֵ֣י] [שְׁעָרָ֑יִךְ] [בֵּרַ֖ךְ] abençoou [בְּקִרְבֵּֽךְ]');
INSERT INTO verses VALUES (16435, 19, 147, 14, '[הַשָּׂם־גְּבוּלֵ֥ךְ] [שָׁל֑וֹם] [חֵ֥לֶב] [חִ֝טִּ֗ים] [יַשְׂבִּיעֵֽךְ]');
INSERT INTO verses VALUES (16436, 19, 147, 15, '[הַשֹּׁלֵ֣חַ] [אִמְרָת֣וֹ] terra até [יָר֥וּץ] [דְּבָרֽוֹ]');
INSERT INTO verses VALUES (16437, 19, 147, 16, '[הַנֹּתֵ֣ן] [שֶׁ֣לֶג] [כַּצָּ֑מֶר] [כְּ֝פ֗וֹר] [כָּאֵ֥פֶר] [יְפַזֵּֽר]');
INSERT INTO verses VALUES (16438, 19, 147, 17, '[מַשְׁלִ֣יךְ] [קַֽרְח֣וֹ] [כְפִתִּ֑ים] diante-de [קָ֝רָת֗וֹ] quem [יַעֲמֹֽד]');
INSERT INTO verses VALUES (16439, 19, 147, 18, '[יִשְׁלַ֣ח] [דְּבָר֣וֹ] [וְיַמְסֵ֑ם] habitou [ר֝וּח֗וֹ] [יִזְּלוּ־מָֽיִם] águas');
INSERT INTO verses VALUES (16440, 19, 147, 19, '[מַגִּ֣יד] [*דברו] [**דְּבָרָ֣יו] [לְיַעֲקֹ֑ב] [חֻקָּ֥יו]');
INSERT INTO verses VALUES (16441, 19, 147, 20, 'não fez [כֵ֨ן] para-todo nação [וּמִשְׁפָּטִ֥ים] não [הַֽלְלוּ־יָֽהּ]');
INSERT INTO chapters VALUES (626, 19, 148, 14);
INSERT INTO verses VALUES (16442, 19, 148, 1, 'louvai [יָ֨הּ] [׀] a yhwh de os-céus [בַּמְּרוֹמִֽים] [sem-traducao]');
INSERT INTO verses VALUES (16443, 19, 148, 2, '[הֽ͏ַלְל֥וּהוּ] todo [הַֽ֝לְל֗וּהוּ] [כָּל־*צבאו] todo');
INSERT INTO verses VALUES (16444, 19, 148, 3, '[הַֽ֭לְלוּהוּ] [שֶׁ֣מֶשׁ] [וְיָרֵ֑חַ] [הַ֝לְל֗וּהוּ] todo luz luz');
INSERT INTO verses VALUES (16445, 19, 148, 4, '[הַֽ֭לְלוּהוּ] [שְׁמֵ֣י] os-céus [וְ֝הַמַּ֗יִם] [אֲשֶׁ֤ר] [׀] de-cima-de');
INSERT INTO verses VALUES (16446, 19, 148, 5, '[יְֽ֭הַֽלְלוּ] a yhwh que ele ele ordenou');
INSERT INTO verses VALUES (16447, 19, 148, 6, '[וַיַּעֲמִידֵ֣ם] [לָעַ֣ד] para-sempre [חָק־נָ֝תַ֗ן] deu e-não');
INSERT INTO verses VALUES (16448, 19, 148, 7, '[הַֽלְל֣וּ] a yhwh de a-terra e-todo');
INSERT INTO verses VALUES (16449, 19, 148, 8, 'fogo [וּ֭בָרָד] [שֶׁ֣לֶג] [וְקִיט֑וֹר] espírito [סְ֝עָרָ֗ה] fez [דְבָרֽוֹ]');
INSERT INTO verses VALUES (16450, 19, 148, 9, '[הֶהָרִ֥ים] e-todo árvore fruto [וְכָל־אֲרָזִֽים] e-todo');
INSERT INTO verses VALUES (16451, 19, 148, 10, '[הַֽחַיָּ֥ה] e-todo animal réptil asa');
INSERT INTO verses VALUES (16452, 19, 148, 11, 'reis-de terra e-todo [וְכָל־שֹׁ֥פְטֵי] [אָֽרֶץ] e-todo [sem-traducao] terra');
INSERT INTO verses VALUES (16453, 19, 148, 12, '[בַּחוּרִ֥ים] e-também [זְ֝קֵנִ֗ים] [עִם־נְעָרֽ͏ִים] com');
INSERT INTO verses VALUES (16454, 19, 148, 13, '[יְהַלְל֤וּ] a nome yhwh porque [שְׁמ֣וֹ] sozinho [ה֝וֹד֗וֹ] [עַל־אֶ֥רֶץ] sobre terra');
INSERT INTO verses VALUES (16455, 19, 148, 14, '[וַיָּ֤רֶם] [קֶ֨רֶן] [׀] [לְעַמּ֡וֹ] para-todo [לְֽכָל־חֲסִידָ֗יו] aos-filhos-de Israel com [הַֽלְלוּ־יָֽהּ]');
INSERT INTO chapters VALUES (627, 19, 149, 9);
INSERT INTO verses VALUES (16456, 19, 149, 1, '[הַ֥לְלוּיָ֨הּ] [׀] [שִׁ֣ירוּ] [לַֽ֭יהוָה] novo [חָדָ֑שׁ] [תְּ֝הִלָּת֗וֹ] [בִּקְהַ֥ל]');
INSERT INTO verses VALUES (16457, 19, 149, 2, '[יִשְׂמַ֣ח] Israel [בְּעֹשָׂ֑יו] filhos-de [יָגִ֥ילוּ] [בְמַלְכָּֽם]');
INSERT INTO verses VALUES (16458, 19, 149, 3, '[יְהַֽלְל֣וּ] [שְׁמ֣וֹ] [בְמָח֑וֹל] [בְּתֹ֥ף] [וְ֝כִנּ֗וֹר] [יְזַמְּרוּ־לֽוֹ]');
INSERT INTO verses VALUES (16459, 19, 149, 4, 'porque yhwh yhwh [יְפָאֵ֥ר] [עֲ֝נָוִ֗ים] [בִּישׁוּעָֽה]');
INSERT INTO verses VALUES (16460, 19, 149, 5, '[יַעְלְז֣וּ] [חֲסִידִ֣ים] [בְּכָב֑וֹד] [יְ֝רַנְּנ֗וּ] sobre');
INSERT INTO verses VALUES (16461, 19, 149, 6, '[רוֹמְמ֣וֹת] El [בִּגְרוֹנָ֑ם] [וְחֶ֖רֶב] [פִּֽיפִיּ֣וֹת] [בְּיָדָֽם]');
INSERT INTO verses VALUES (16462, 19, 149, 7, '[לַעֲשׂ֣וֹת] [נְ֭קָמָה] [בַּגּוֹיִ֑ם] [תּֽ֝וֹכֵחֹ֗ת] não');
INSERT INTO verses VALUES (16463, 19, 149, 8, '[לֶאְסֹ֣ר] [מַלְכֵיהֶ֣ם] [בְּזִקִּ֑ים] [וְ֝נִכְבְּדֵיהֶ֗ם] [בְּכַבְלֵ֥י] [בַרְזֶֽל]');
INSERT INTO verses VALUES (16464, 19, 149, 9, '[לַעֲשׂ֤וֹת] [בָּהֶ֨ם] [׀] [מִשְׁפָּ֬ט] [כָּת֗וּב] ele ele [לְכָל־חֲסִידָ֗יו] louvai [sem-traducao]');
INSERT INTO chapters VALUES (628, 19, 150, 6);
INSERT INTO verses VALUES (16465, 19, 150, 1, '[הַ֥לְלוּיָ֨הּ] louvai El [בְּקָדְשׁ֑וֹ] [הֽ͏ַ֝לְל֗וּהוּ] na-expansão-de [עֻזּֽוֹ]');
INSERT INTO verses VALUES (16466, 19, 150, 2, '[הַֽלְל֥וּהוּ] [בִגְבוּרֹתָ֑יו] [הֽ͏ַ֝לְל֗וּהוּ] [כְּרֹ֣ב] [גֻּדְלֽוֹ]');
INSERT INTO verses VALUES (16467, 19, 150, 3, '[הַֽ֭לְלוּהוּ] [בְּתֵ֣קַע] [שׁוֹפָ֑ר] [הַֽ֝לְל֗וּהוּ] [בְּנֵ֣בֶל] [וְכִנּֽוֹר]');
INSERT INTO verses VALUES (16468, 19, 150, 4, '[הַֽ֭לְלוּהוּ] [בְּתֹ֣ף] [וּמָח֑וֹל] [הַֽ֝לְל֗וּהוּ] [בְּמִנִּ֥ים] [וְעוּגָֽב]');
INSERT INTO verses VALUES (16469, 19, 150, 5, '[הַֽלְל֥וּהוּ] [בְצִלְצְלֵי־שָׁ֑מַע] ouviu [בְּֽצִלְצְלֵ֥י] [תְרוּעָֽה]');
INSERT INTO verses VALUES (16470, 19, 150, 6, 'todo [הַ֭נְּשָׁמָה] [תְּהַלֵּ֥ל] [יָ֗הּ] louvai [sem-traducao]');
INSERT INTO books VALUES (20, 'PRO', 'Provérbios', 'AT', 31);
INSERT INTO chapters VALUES (629, 20, 1, 33);
INSERT INTO verses VALUES (16471, 20, 1, 1, 'mishléi Shelomoh filho-de Davi rei Israel');
INSERT INTO verses VALUES (16472, 20, 1, 2, 'para-conhecer sabedoria u-musár le-habíin palavras com-inteligência-');
INSERT INTO verses VALUES (16473, 20, 1, 3, 'tomar Musar o entendimento justiça e julgamento e retidão;');
INSERT INTO verses VALUES (16474, 20, 1, 4, 'para-dar lifthéiim ármah lenáar conhecimento u-mézimáh');
INSERT INTO verses VALUES (16475, 20, 1, 5, 'ouvirá o-sábio [וְי֣וֹסֶף] tomou e-o-inteligente tece-lãs adquirirá');
INSERT INTO verses VALUES (16476, 20, 1, 6, 'para-entender מָ֭שָׁל e-o-jogo-de-palavras palavras-de חֲ֝כָמִ֗ים e-os-enigmas-dos-mesmos');
INSERT INTO verses VALUES (16477, 20, 1, 7, 'yiráat yhwh ré''eshít dá''át chokhmá ú-musár é''vílim bá-zu');
INSERT INTO verses VALUES (16478, 20, 1, 8, 'ouviu filhos-de מוּסַ֣ר pai-teu e-a tittosh torat אִמֶּֽךָ׃');
INSERT INTO verses VALUES (16479, 20, 1, 9, 'que livyat chen hem eles waanakim legargrothecha');
INSERT INTO verses VALUES (16480, 20, 1, 10, 'filhos-de se yepattukha chatatim a traga-verso-final');
INSERT INTO verses VALUES (16481, 20, 1, 11, 'se dirão-lei para-vem com-nos nos-espreitaremos para-seu-sangue nos-esporearemos para-inocente gratuitamente');
INSERT INTO verses VALUES (16482, 20, 1, 12, 'os-devoraremos como-sheol vida e-os-puros de-a-descentos בֽוֹר׃');
INSERT INTO verses VALUES (16483, 20, 1, 13, 'todo isso precioso foi encontrado cheio nosso ventre despojo');
INSERT INTO verses VALUES (16484, 20, 1, 14, 'sorte-teu destruirá no-médio-nós bolsa um será para-nós-todos');
INSERT INTO verses VALUES (16485, 20, 1, 15, 'filhos-de a andarás no-caminho com-eles impede pé-teu de-a-sua-estrada');
INSERT INTO verses VALUES (16486, 20, 1, 16, 'que seus-pés para-mal correrão e-terão-se-apressado para derramar- sangue;');
INSERT INTO verses VALUES (16487, 20, 1, 17, 'porque sem-motivo de-a-semente a-erva-malvada em-o-coração-de asa Baal asa');
INSERT INTO verses VALUES (16488, 20, 1, 18, 'e-eles para-o-silencio se-esconderão esconder-se-ão para-as-almas-deles-verso-final');
INSERT INTO verses VALUES (16489, 20, 1, 19, 'sim archoth todo que-produz בָּצַע a alma com-seus-donos');
INSERT INTO verses VALUES (16490, 20, 1, 20, 'sabedoria fora tocar-a-trombeta nas-praças dareis voz-dela');
INSERT INTO verses VALUES (16491, 20, 1, 21, 'no-começo gritando lerá em-portas de-portões na-cidade palavras-dela diga');
INSERT INTO verses VALUES (16492, 20, 1, 22, 'até quando ingênuos amem-o jovem e-escarnecedores zombaria a-eles para-eles e-insensatos odiem-no דָֽעַת׃');
INSERT INTO verses VALUES (16493, 20, 1, 23, 'voltares-vos para-a-repreensao-meu eis [אַבִּ֣יעָה] a-vós RUÍ [אוֹדִ֖יעָה] palavras-meu a-vós');
INSERT INTO verses VALUES (16494, 20, 1, 24, 'porque eu chamei e nos fez e estendi minha mão e-não escutando');
INSERT INTO verses VALUES (16495, 20, 1, 25, 'e se curvaram todo minha conselheira não não seus pais');
INSERT INTO verses VALUES (16496, 20, 1, 26, 'também Eu be-eidchem eshchak elag em-a-entrada pachdchem');
INSERT INTO verses VALUES (16497, 20, 1, 27, 'be-bo pavor-vos e-tragédia-vos escondida virá em-entrar sobre-vós dificuldade e-fome');
INSERT INTO verses VALUES (16498, 20, 1, 28, 'então clamarão-me e-não responder-ei buscarão-me e-não encontrarão-me');
INSERT INTO verses VALUES (16499, 20, 1, 29, 'debaixo porque odiem דָ֑עַת e-temor-de não não escolheram');
INSERT INTO verses VALUES (16500, 20, 1, 30, 'não אָב֥וּ para-o-conselho-meu [כָּל־תּוֹכַחְתִּֽי] todo rebuke-meu');
INSERT INTO verses VALUES (16501, 20, 1, 31, 'e-eles-comerão do-fruto-de caminho-dele e-das-conselhos-seus יִשְׂבָּֽעוּ׃');
INSERT INTO verses VALUES (16502, 20, 1, 32, 'que retornar pateiim [תַּֽהַרְגֵ֑ם] veshalvath כְּסִילִ֣ים tea''abdem');
INSERT INTO verses VALUES (16503, 20, 1, 33, 'veshomo''e''a para-mim habitará-  בטַח  vesha''anann de-a-terror raa');
INSERT INTO chapters VALUES (630, 20, 2, 22);
INSERT INTO verses VALUES (16504, 20, 2, 1, 'filhos-de se tu-tomarás minhas-palavras umitzvotai titsphon contigo');
INSERT INTO verses VALUES (16505, 20, 2, 2, 'lehakshiv lahachmah o-teu-ouvido vira para-o-teu-coracao para-a-entendimento');
INSERT INTO verses VALUES (16506, 20, 2, 3, 'que mãe para-a-sabedoria chama para-a-entendimento dareis a-teu-voz');
INSERT INTO verses VALUES (16507, 20, 2, 4, 'se procure como-o-prata e-com-matmoinim ta-chaphshenah');
INSERT INTO verses VALUES (16508, 20, 2, 5, 'então viverás temor yhwh e conhecimento Elohim תִּמְצָֽא׃');
INSERT INTO verses VALUES (16509, 20, 2, 6, 'porque yhwh dará sabedoria conhecimento conhecimento e entendimento');
INSERT INTO verses VALUES (16510, 20, 2, 7, 'aos justos תּוּשִׁיָּ֑ה מָ֝גֵ֗ן לְהֹ֣לְכֵי תֹֽם׃');
INSERT INTO verses VALUES (16511, 20, 2, 8, 'לִ֭נְצֹר caminhos juízo e-caminho יִשְׁמֹֽר׃');
INSERT INTO verses VALUES (16512, 20, 2, 9, 'az tabin tsedeq e-juízo umeysharim todo maagol- bom');
INSERT INTO verses VALUES (16513, 20, 2, 10, 'porque Venha sabedoria no-seu-coração e-conhecimento para-a-tua-alma será-alegria');
INSERT INTO verses VALUES (16514, 20, 2, 11, 'de-perversidade guardarás sobre-ti entendimento você-vigiará');
INSERT INTO verses VALUES (16515, 20, 2, 12, 'para te salvar de-caminho-de mal de-homem que-está-falando vire-se-vire-se;');
INSERT INTO verses VALUES (16516, 20, 2, 13, 'os-abandonando arhot justiça para-andar nas-vias-de escuridão');
INSERT INTO verses VALUES (16517, 20, 2, 14, 'os-felizes para-fazer mal re-joguem-se em-o-reversões mal');
INSERT INTO verses VALUES (16518, 20, 2, 15, 'que de-a-sua-caminhos e-difíceis e-perdidos em-a-sua-voltas');
INSERT INTO verses VALUES (16519, 20, 2, 16, 'para te salvar de-mulher estrangeira de-terra-alheia palavras-de-a desliza-ma');
INSERT INTO verses VALUES (16520, 20, 2, 17, 'deixando-a chefe seus-jovens e-a berith seus-elohim esquecendo-a');
INSERT INTO verses VALUES (16521, 20, 2, 18, 'que caiu a morte sua-casa e-a espíritos-malignos seus-rolamentos');
INSERT INTO verses VALUES (16522, 20, 2, 19, 'todo não não voltem-se e-não vida caminhos vivos');
INSERT INTO verses VALUES (16523, 20, 2, 20, 'para-que vá-tu no-caminho [טוֹבִ֑ים] [וְאָרְח֖וֹת] justos guardareis');
INSERT INTO verses VALUES (16524, 20, 2, 21, 'porque retos terra e-os-puros [יִוָּ֥תְרוּ] em-ela');
INSERT INTO verses VALUES (16525, 20, 2, 22, '[וּ֭רְשָׁעִים] de-terra-de serão-cortados וּ֝בוֹגְדִ֗ים [יִסְּח֥וּ] de-elas');
INSERT INTO chapters VALUES (631, 20, 3, 35);
INSERT INTO verses VALUES (16526, 20, 3, 1, 'filhos-de [תּוֹרָתִ֣י] a tishchakha umitzvotai formar לִבֶּֽךָ׃');
INSERT INTO verses VALUES (16527, 20, 3, 2, 'que comprimento dias e-anos vida e-salvamento eles-aumentarão para-ti');
INSERT INTO verses VALUES (16528, 20, 3, 3, 'bondade e-verdade a deixar-te-á os-seus-cordões sobre as-tua-garganta de-sua-escrita sobre placa לִבֶּֽךָ׃');
INSERT INTO verses VALUES (16529, 20, 3, 4, 'e-achar- graça e-prudência- bom em-olhos-de Elohim e-homem׃');
INSERT INTO verses VALUES (16530, 20, 3, 5, 'בְּטַ֣ח a yhwh em-todo teu-coração e-a na-tua-sabedoria֗ a você-se-apoiará׃');
INSERT INTO verses VALUES (16531, 20, 3, 6, 'em-todo דְּרָכֶ֥יךָ דעהוּ e ele dirige as tuas caminhos:');
INSERT INTO verses VALUES (16532, 20, 3, 7, 'a seja sábio em-olhos-teus temor a yhwh e-vire-se מֵרָע׃');
INSERT INTO verses VALUES (16533, 20, 3, 8, 'ref-e-o seja para-a-sua-vida e-vianda-de-agua para-os-teus-osso');
INSERT INTO verses VALUES (16534, 20, 3, 9, 'כב- a yhwh de-a-tua-cama e-de-o-primeiro todo teu-producao');
INSERT INTO verses VALUES (16535, 20, 3, 10, 'e-estara-cheio as-mo-teus sete e-tirosh yekavei-teus yifrotz-u');
INSERT INTO verses VALUES (16536, 20, 3, 11, 'musar yhwh filhos-de a תּימאָס e-a te provocará na sua repreensão:');
INSERT INTO verses VALUES (16537, 20, 3, 12, 'que a que amará yhwh provará e com dor a filho aceitará:');
INSERT INTO verses VALUES (16538, 20, 3, 13, 'felizes homem encontrou sabedoria e o homem despertará תּוֹבַן׃');
INSERT INTO verses VALUES (16539, 20, 3, 14, 'que bom seu-comércio de-seu-comércio- prata e-de-prata suas produções');
INSERT INTO verses VALUES (16540, 20, 3, 15, 'preciosa הִ֭יא e-todo teus-coisas não não em-ela');
INSERT INTO verses VALUES (16541, 20, 3, 16, 'duração de-dias com-seu-lado-direito em-o-esquerdo-a dez וְכָבֽוֹד׃');
INSERT INTO verses VALUES (16542, 20, 3, 17, 'suas caminhadas caminhos de - beleza e-todo suas trilhas paz');
INSERT INTO verses VALUES (16543, 20, 3, 18, 'árvore- vivos הִ֭יא para-os-mantenedores nela e-apoiadores-a bem-aventurado');
INSERT INTO verses VALUES (16544, 20, 3, 19, 'yhwh com-sabedoria fundou-em- terra כּוֹנֵ֥ן céus entendimento');
INSERT INTO verses VALUES (16545, 20, 3, 20, '[בְּ֭דַעְתּוֹ] abissos se-partiram e-nuvens serão-empapados- orvalho:');
INSERT INTO verses VALUES (16546, 20, 3, 21, 'filhos-de a rir-se-ão de-tua-vista guarda sabedoria e-mente');
INSERT INTO verses VALUES (16547, 20, 3, 22, 'e serão vida para-a-tua-alma e-graciosidade para-os-teus-gargarejos');
INSERT INTO verses VALUES (16548, 20, 3, 23, 'então andarás לָבֶ֣טַח דַּרְכֶּ֑ךָ e-a-tua-pé não tu-serás-ferido');
INSERT INTO verses VALUES (16549, 20, 3, 24, 'se deitar-te-ás não terás-medo e-deitares-te-ás e-será-tua-noite a-tua-noite');
INSERT INTO verses VALUES (16550, 20, 3, 25, 'a temer-se-á de-paor פִּתְאֹ֑ם e-de-tribuicao que porque תָבֹֽא׃');
INSERT INTO verses VALUES (16551, 20, 3, 26, 'porque será será em-teu-insensatez e-guarda teus-pes de-teu-rei');
INSERT INTO verses VALUES (16552, 20, 3, 27, 'a vai-impedir-se bom de-seus-dominadores na-vez-de para-o-Elohim para-fazer');
INSERT INTO verses VALUES (16553, 20, 3, 28, 'a dizes vai e-voltar e-amanhã darei e há contigo');
INSERT INTO verses VALUES (16554, 20, 3, 29, 'a tu-arrochar sobre teu-amigo maldade e-ele habitante לָבֶ֣טַח contigo');
INSERT INTO verses VALUES (16555, 20, 3, 30, 'a com homem חִנָּ֑ם se não teu-camelo raa');
INSERT INTO verses VALUES (16556, 20, 3, 31, 'a תְּ֭קַנֵּא em-cada-homem חָמָס e-a tu-escolherás em-todo seus-caminhos');
INSERT INTO verses VALUES (16557, 20, 3, 32, 'que abominação-teu yhwh estrangeiro e-a retos seu-secreto');
INSERT INTO verses VALUES (16558, 20, 3, 33, 'Luz: yhwh em-casa-de ímpio E-alegria: justos Bendiga:');
INSERT INTO verses VALUES (16559, 20, 3, 34, 'se A-línguas: ele Mordesse: dê חֵֽן׃');
INSERT INTO verses VALUES (16560, 20, 3, 35, 'kavod sábios yinchalu -ukesilim mêrim qalon-');
INSERT INTO chapters VALUES (632, 20, 4, 27);
INSERT INTO verses VALUES (16561, 20, 4, 1, 'ouvi filhos mussar pai e-os-ouvintes para-conhecer em-inteligência');
INSERT INTO verses VALUES (16562, 20, 4, 2, 'que tomou bom dei a-vós torat-i a taazovu');
INSERT INTO verses VALUES (16563, 20, 4, 3, 'porque filho hayiti le-avi rakh ve-yachid diante-de AMI:');
INSERT INTO verses VALUES (16564, 20, 4, 4, 'va-yoreneni E-disse para-mim yitmach- minhas-palavras teu-coração guarda mandamentos-meus e-viva');
INSERT INTO verses VALUES (16565, 20, 4, 5, 'קְנֵ֣ה חָכְמָה Compre a Sabedoria a תִּשְׁכַּ֥ח e-a derrama-te por palavras dos meu bocadilho:');
INSERT INTO verses VALUES (16566, 20, 4, 6, 'a deixa-a e-guarda-te ama-a e-estreita-te');
INSERT INTO verses VALUES (16567, 20, 4, 7, 'רֵאשִׁ֖ית חָכְמָה קְנֵ֣ה sabedoria e-em-todo קִנְיָנְךָ֗ קְנֵ֣ה בִינָה׃');
INSERT INTO verses VALUES (16568, 20, 4, 8, 'encadeia-a e-tu-elevar-te tu-honrar-te que você-abraçará-a');
INSERT INTO verses VALUES (16569, 20, 4, 9, 'תִּתֵּ֣ן para a-cabeça-te para a-companhamento-de grace coroa glória que te-alegre');
INSERT INTO verses VALUES (16570, 20, 4, 10, 'ouviu filhos-de e toma minhas-palavras e-eles-aumentarão a-ti שְׁנ֣וֹת vida');
INSERT INTO verses VALUES (16571, 20, 4, 11, 'no-caminho חָכְמָה הֹרֵתִ֑יךָ הִ֝דְרַכְתִּ֗יךָ בְּמַעְגְּלֵי־ יֹֽשֶׁר׃');
INSERT INTO verses VALUES (16572, 20, 4, 12, 'em-a-tua-andança não ele-formou teu-passo não correrás não cairás');
INSERT INTO verses VALUES (16573, 20, 4, 13, 'o fortaleça pela instrução a quebrada quebrará tua-vida ela vidas-tuas');
INSERT INTO verses VALUES (16574, 20, 4, 14, 'no caminho ímpios a vem e-a serás abençoada no-caminho males:');
INSERT INTO verses VALUES (16575, 20, 4, 15, 'abre-a a passa- nele pastoreia de-lá-dela e-passa');
INSERT INTO verses VALUES (16576, 20, 4, 16, 'que não dormirão se não farão-mal e-será-roubada seu-tempo-de-dormir se não');
INSERT INTO verses VALUES (16577, 20, 4, 17, 'que comerão pão רֶ֑שַׁע e-vinho violentos bebam');
INSERT INTO verses VALUES (16578, 20, 4, 18, 'e-caminho justos כאור brilhante andando e-luz até o-dia o-dia');
INSERT INTO verses VALUES (16579, 20, 4, 19, 'o-caminho-de ímpios como-escuridão não conheceram em-o-que cairão');
INSERT INTO verses VALUES (16580, 20, 4, 20, 'filhos-de para-mim-das-palavras a-ouvir para-mim-dos-discursos vira- ouvido-seu');
INSERT INTO verses VALUES (16581, 20, 4, 21, 'a aleijem-se de-tua-pomba no-meio-de em-meio-de ao-teu-coração');
INSERT INTO verses VALUES (16582, 20, 4, 22, 'porque eles eles para-auxílios-deles e-para-todo na-carne-seu cura--');
INSERT INTO verses VALUES (16583, 20, 4, 23, 'de-todo de-guarda נְצֹ֣ר teu-coração porque vida saídas vivos');
INSERT INTO verses VALUES (16584, 20, 4, 24, 'הסר mimakha dureza boca e-vaidade bocas afaste-se מִמֶּֽךָּ׃');
INSERT INTO verses VALUES (16585, 20, 4, 25, 'os olhos-vossos para-a vista olhem e-as tuas pálpebras alinhem-se diante-de-vós');
INSERT INTO verses VALUES (16586, 20, 4, 26, 'fere roda pé-tu e-todo caminho-tu estabeleçam-se');
INSERT INTO verses VALUES (16587, 20, 4, 27, 'a inclina- direita e-esquerda retira pé-tu מֵרָע׃');
INSERT INTO chapters VALUES (633, 20, 5, 23);
INSERT INTO verses VALUES (16588, 20, 5, 1, 'filhos-de para-sabedoria-meu ouve- para-compreensão-meu inclina- ouvido-seu');
INSERT INTO verses VALUES (16589, 20, 5, 2, 'לשמור mzimot ve-daat sfateicha yin-tzoru');
INSERT INTO verses VALUES (16590, 20, 5, 3, 'que nofet tit-tofenah שִׂפְתֵ֣י zarah ve-chalak de-a-oleo chik-ha');
INSERT INTO verses VALUES (16591, 20, 5, 4, 've-acharitah amará cal-lan-ha chad-dah k-cherev pi-yot');
INSERT INTO verses VALUES (16592, 20, 5, 5, 'rag-le-ha yor-dot morte sheol tz-a-de-ha yitmochoû');
INSERT INTO verses VALUES (16593, 20, 5, 6, 'caminho vida para-que-não te-fal-s na-u não não sabereis-');
INSERT INTO verses VALUES (16594, 20, 5, 7, 'e-agora filhos ouvi para-mim e-a vos-apartareis- de-palavras-de- a boca:');
INSERT INTO verses VALUES (16595, 20, 5, 8, 'afasta-te- de-a-sobre-ele- caminho-teu- e-a te-aproximarás- a porta casa-de-a-ela');
INSERT INTO verses VALUES (16596, 20, 5, 9, 'para-que-não darás a outros glória-teu- e-aos-dias-teus- para-o-fiel-');
INSERT INTO verses VALUES (16597, 20, 5, 10, 'para-que-não satisfarão estrangeiros força-te e-tua-angústia em-casa-de estrangeiro');
INSERT INTO verses VALUES (16598, 20, 5, 11, 'e-se-comerão em-tua-última com-a-conclusão de-teu-carne e-tua-ressíduo');
INSERT INTO verses VALUES (16599, 20, 5, 12, 'e-disseste como odi-ei disciplina e-repreendeu-a espittou no meu coração:');
INSERT INTO verses VALUES (16600, 20, 5, 13, 'e-não ouv-ei com-voz de-meu-ensinador e-de-meu-professor não voltei-ei minha-orelha');
INSERT INTO verses VALUES (16601, 20, 5, 14, 'como-pequeno fui em-todo no-meio-de em-meio-de assembleia e-congregação-:');
INSERT INTO verses VALUES (16602, 20, 5, 15, 'bebe-de-o águas de-bem-aventurado-teu e-sorvedouros de-meio na-fonte-teu-:');
INSERT INTO verses VALUES (16603, 20, 5, 16, 'se-apartem de-sus-túas fora em-á-recho-bótes rios-de- águas');
INSERT INTO verses VALUES (16604, 20, 5, 17, 'sejam-eles para-ti para-você-sozinho e-não-há para-estrangeiros contigo');
INSERT INTO verses VALUES (16605, 20, 5, 18, 'será de-sua-fonte bendito e-saudoso de-a-eshet nao-urca');
INSERT INTO verses VALUES (16606, 20, 5, 19, 'אַיֶּ֥לֶת amados e-elevará da-dehah y-ravuca em-todo o-tempo b-ahevat-ah tisgge תָמִֽיד׃');
INSERT INTO verses VALUES (16607, 20, 5, 20, 'e-porque tirar-se filhos-de em-o-estrangeiro e-você-se-aproximará costas estranha');
INSERT INTO verses VALUES (16608, 20, 5, 21, 'que em-face-de os-olhos-de os-olhos-de yhwh homem e-todo de-suas-rodas que-separe');
INSERT INTO verses VALUES (16609, 20, 5, 22, 'suas-iniquidades ser prendido a o-rash''ăʿ e nos cordos seu pecado ser consumido');
INSERT INTO verses VALUES (16610, 20, 5, 23, 'ele morre na árvore disciplina e na abundância seu deserto יִשְׁגֶּֽה׃');
INSERT INTO chapters VALUES (634, 20, 6, 35);
INSERT INTO verses VALUES (16611, 20, 6, 1, 'filhos-de se arabt para-te taqahta para-zar ka-fei-ka');
INSERT INTO verses VALUES (16612, 20, 6, 2, 'espetaste em-palavras- פִּיךָ n-ilcaddat em-palavras-de teu-boca:');
INSERT INTO verses VALUES (16613, 20, 6, 3, 'fez esta efo filhos-de ve-hinnatzel porque que bekaph- re''ekha vai hitrappes urehab reeka');
INSERT INTO verses VALUES (16614, 20, 6, 4, 'a darás shena le-eineka utnumah para-o-teu-palpebre');
INSERT INTO verses VALUES (16615, 20, 6, 5, 'hinnatsêl como flecha imediatamente e como pomba de-mão-de será buscado');
INSERT INTO verses VALUES (16616, 20, 6, 6, 'vai- a a-formiga o-preguiçoso viu de-seus-caminhos e-sábio');
INSERT INTO verses VALUES (16617, 20, 6, 7, 'que não há para-ela o-príncipe oficial-que-começa-com-sht e-manda-o');
INSERT INTO verses VALUES (16618, 20, 6, 8, 'farás em-a-temporada-de-verao para-o-pão-dela guarda-ela na-temporada-de-colheita alimento-dela-o');
INSERT INTO verses VALUES (16619, 20, 6, 9, 'até até-quando preguiçoso-que-começa-com-ts deitar-se-você quando levanta-te de-a-tua-mudança');
INSERT INTO verses VALUES (16620, 20, 6, 10, 'pouco שֵׁ֭נוֹת pouco תְּנוּמ֑וֹת מְעַ֓ט ׀ חִבֻּ֖ק mãos לִשְׁכָּֽב׃');
INSERT INTO verses VALUES (16621, 20, 6, 11, 'e vêm- como-andando a-tua-cabeça e-a-tua-falta como homem מָגֵ֗ן׃');
INSERT INTO verses VALUES (16622, 20, 6, 12, 'homem בליעל homem iniquidade andando dureza pe:');
INSERT INTO verses VALUES (16623, 20, 6, 13, 'corta em-a-sua-olho engole em-a-pé mostrando com-as-unhas-de-sua');
INSERT INTO verses VALUES (16624, 20, 6, 14, 'virando-se no-cor-do carver mau mal tempo ele-enviará');
INSERT INTO verses VALUES (16625, 20, 6, 15, 'sobre sim de-súbito virá seu-desastre repentinamente que-se-partirá e-não cura--');
INSERT INTO verses VALUES (16626, 20, 6, 16, 'seis- eis-a yhwh yhwh e-sete sua-alma:');
INSERT INTO verses VALUES (16627, 20, 6, 17, 'עֵינַ֣יִם alturas língua-de falsidade e-mãos derramando sangue- נקי׃');
INSERT INTO verses VALUES (16628, 20, 6, 18, 'coração arado מחשבות iniquidade pés mamaretorot larutz laraahe');
INSERT INTO verses VALUES (16629, 20, 6, 19, 'yafichah kazavim até falsidade umeshalech medanin entre achimhe');
INSERT INTO verses VALUES (16630, 20, 6, 20, 'נְצֹ֣ר filhos-de mandamento da pai-teu e-a tittoosh torat אִמֶּֽךָ׃');
INSERT INTO verses VALUES (16631, 20, 6, 21, 'qashreem sobre לִבְּךָ֣ permanente-mente an-de-m sobre gar-gar-ro-te-kha');
INSERT INTO verses VALUES (16632, 20, 6, 22, 'be-hi-ta-lakh-cha ta-nak-he você be-shakh-vakh-a guardares sobre-ti va-ha-kitz-o-ta ela te-sikh-cha');
INSERT INTO verses VALUES (16633, 20, 6, 23, 'que cera mandamento e lei luz e caminho vida repreensões correções');
INSERT INTO verses VALUES (16634, 20, 6, 24, 'li-sh-mar-cha de-a-mulher mal de-a-partilha a-língua estranha');
INSERT INTO verses VALUES (16635, 20, 6, 25, 'a desejarás sua-formosura no levavéka e-a tomarás-a com-seus-párpados');
INSERT INTO verses VALUES (16636, 20, 6, 26, 'que em-o-lugar-de mulher a-moça até circular pão e-mulher homem alma preciosa guarda-a');
INSERT INTO verses VALUES (16637, 20, 6, 27, 'se-afogará homem fogo em-seio-seu e-seus-vestes não serão-queimados');
INSERT INTO verses VALUES (16638, 20, 6, 28, 'se andará homem sobre não e-seus-pés não se-tornar-ão');
INSERT INTO verses VALUES (16639, 20, 6, 29, 'sim o-vindo a mulher-de não não será-lavado todo da-pessoa-que-tocou nela');
INSERT INTO verses VALUES (16640, 20, 6, 30, 'não enganarão que porque ladrão para preencher que porque será fome');
INSERT INTO verses VALUES (16641, 20, 6, 31, 'e-será-encontrado pagará setenta-e-uma-vezes a todo ה֖וֹן em-sua-casa dê');
INSERT INTO verses VALUES (16642, 20, 6, 32, 'adúltero mulher falta- coração destruidor ele ele ele-o-fará');
INSERT INTO verses VALUES (16643, 20, 6, 33, 'praga- e-operação encontrará não não será-apagado');
INSERT INTO verses VALUES (16644, 20, 6, 34, 'porque ciúme ira- Geber e-não ele-tornará-se-misericordioso em-dia-de vingança');
INSERT INTO verses VALUES (16645, 20, 6, 35, 'não face-de face-de todo que e-não amar-a-o porque multiplicar-a-');
INSERT INTO chapters VALUES (635, 20, 7, 27);
INSERT INTO verses VALUES (16646, 20, 7, 1, 'filhos-de guardar minhas-palavras e-mandamentos-meus titsphon contigo');
INSERT INTO verses VALUES (16647, 20, 7, 2, 'guardar mandamentos-meus e-viver e-lei-meu como-um-homem de-tus-teus-olhos');
INSERT INTO verses VALUES (16648, 20, 7, 3, 'amarrar-eles sobre dedos-tua escrevam sobre tabela לִבֶּֽךָ׃');
INSERT INTO verses VALUES (16649, 20, 7, 4, 'disse para-a-sabedoria irmã-de-mim você-é e-aviso para-a-comprensão ler-você');
INSERT INTO verses VALUES (16650, 20, 7, 5, 'para-guardar-tua de-mulher estrangeira de-a-mim-cria palavras-de-a ela-deslizou');
INSERT INTO verses VALUES (16651, 20, 7, 6, 'que no-janela em-minha-casa bedo eshnabi nishqafte:');
INSERT INTO verses VALUES (16652, 20, 7, 7, 'e-eu-vi em-o-patayim entendo em-os-banim jovem falta- coração');
INSERT INTO verses VALUES (16653, 20, 7, 8, 'passando no-mercado junto-a costa-a ve-de-re-kh casa-a andará');
INSERT INTO verses VALUES (16654, 20, 7, 9, 'na-noite- dia dia no-alvorde noite e-escuridão');
INSERT INTO verses VALUES (16655, 20, 7, 10, 'e-eis mulher likrato põe meretriz e-prisioneira coração');
INSERT INTO verses VALUES (16656, 20, 7, 11, 'destruição ela e-rebelde em-a-sua-casa não habitarão as-suas-pernas');
INSERT INTO verses VALUES (16657, 20, 7, 12, 'vez fora vez vez e-a-cima-de todo lado esconder-se-á');
INSERT INTO verses VALUES (16658, 20, 7, 13, 'e-ele-se-agarrará-a nele e beijasse- para-ele a jumenta a-ele ela disse- a-ele');
INSERT INTO verses VALUES (16659, 20, 7, 14, 'zibchei paz-ei sobre mim o-dia paguei-ei nossos-votos');
INSERT INTO verses VALUES (16660, 20, 7, 15, 'sobre כֵּ֭ן eu-saí li-qra-techa para-a-manhã de-teus-faces e-acheguei-tei-você');
INSERT INTO verses VALUES (16661, 20, 7, 16, 'cobertores-ei envolvi-ei minha-cama cana-verde ovelha-cria Egito');
INSERT INTO verses VALUES (16662, 20, 7, 17, 'nafthi deitamento-meu mor tendas e-canela');
INSERT INTO verses VALUES (16663, 20, 7, 18, 'לְכָ֤ה nos-emplumamos [דֹ֭דִים] até הַבָּקֵ֑ר se-enrolou em-amados');
INSERT INTO verses VALUES (16664, 20, 7, 19, 'que não-há o-homem em-a-casa-seu andar no-caminho de-longe-:');
INSERT INTO verses VALUES (16665, 20, 7, 20, 'amarrador- tomou tomou na-sua-mão לְי֥וֹם o-trono virá sua-casa');
INSERT INTO verses VALUES (16666, 20, 7, 21, 'viraram-no em-multidão tomá-la em-parte de-sua-língua expulsá-lo');
INSERT INTO verses VALUES (16667, 20, 7, 22, 'andando de-a repentinamente como-boi a Geraque virá e-como-escorpião a מוסר insensato');
INSERT INTO verses VALUES (16668, 20, 7, 23, 'até dividirá seta pesado-o-seu como-rápido pássaro a פָּ֑ח e-não ele porque em-a-sua-alma ela');
INSERT INTO verses VALUES (16669, 20, 7, 24, 'e-agora filhos ouvi a-mim e-os-ouvintes para-palavras-de a boca:');
INSERT INTO verses VALUES (16670, 20, 7, 25, 'a estão-pervertidos a caminhos-seus teu-coração a perverteu-se em-caminhos-seus');
INSERT INTO verses VALUES (16671, 20, 7, 26, 'porque muitos mortos lançou-os e-gigantes todo mortos-seus');
INSERT INTO verses VALUES (16672, 20, 7, 27, 'caminhos sho''al casa-sua descendo a חדרי- מָֽוֶת׃');
INSERT INTO chapters VALUES (636, 20, 8, 36);
INSERT INTO verses VALUES (16673, 20, 8, 1, 'não sabedoria chama-se e-inteligência- dareis sua-voz:');
INSERT INTO verses VALUES (16674, 20, 8, 2, 'em-o-cume-de altos sobre caminho casa caminhos está-posta');
INSERT INTO verses VALUES (16675, 20, 8, 3, 'na mão de： portas à-boca-de קרת de-entrada');
INSERT INTO verses VALUES (16676, 20, 8, 4, 'a-vocês [אִישִׁ֣ים] אֶקְרָא [וְ֝קוֹלִ֗י] a homem homem');
INSERT INTO verses VALUES (16677, 20, 8, 5, 'Habínu mentirosos Arma uCesilim entendei coração');
INSERT INTO verses VALUES (16678, 20, 8, 6, 'Shímeu porque Negidim אֲדַבְּרָה Umipftach minhas-línguas retamente');
INSERT INTO verses VALUES (16679, 20, 8, 7, 'porque verdade Yehge Chikki e abominações minhas-línguas iniquidade;');
INSERT INTO verses VALUES (16680, 20, 8, 8, 'em justiça todo palavras-de a boca não-há neles se desviou e-iqueš׃');
INSERT INTO verses VALUES (16681, 20, 8, 9, 'כֻּלָּ֣ם fortes para entender e retos לְמֹ֣צְאֵי דָֽעַת׃');
INSERT INTO verses VALUES (16682, 20, 8, 10, '[קְחֽוּ־מוּסָרִ֥י] [וְאַל־כָּ֑סֶף] e-a prata veda''at');
INSERT INTO verses VALUES (16683, 20, 8, 11, 'porque boa חָ֭כְמָה מִפְּנִינִ֑ים não חֲ֝פָצִ֗ים não não em-ela');
INSERT INTO verses VALUES (16684, 20, 8, 12, 'אֲ‍ֽנִי־ חָכְמָה שׁוֹכְנִי עָרְמָה וּדְעָת מְזִמּוֹת אֶמְצָא׃');
INSERT INTO verses VALUES (16685, 20, 8, 13, 'יראת yhwh שׂוֹנֵאת mal גֵּאוֹת וְגָאֹון ׀ e-caminho mau mal inversões odiava:');
INSERT INTO verses VALUES (16686, 20, 8, 14, 'para-mim, conselho e-mentira eu בינה a-mim fortaleza:');
INSERT INTO verses VALUES (16687, 20, 8, 15, 'em-mim, מְלָכִ֣ים reinarão e rosnarão chocar-se-ão צֶֽדֶק׃');
INSERT INTO verses VALUES (16688, 20, 8, 16, 'em mim príncipes arrotarão e-nédivim todo juízes צֶֽדֶק׃');
INSERT INTO verses VALUES (16689, 20, 8, 17, 'Eu amou e me despeirarão me encontrarão;');
INSERT INTO verses VALUES (16690, 20, 8, 18, 'riqueza- e glória comigo e riquezas antigo e justiça׃');
INSERT INTO verses VALUES (16691, 20, 8, 19, 'bom meu fruto de carvalho e de pérola e minha colheita de ouro foi escolhido');
INSERT INTO verses VALUES (16692, 20, 8, 20, '[בְּאֹֽרַח־צְדָקָ֥ה] tsedaka no-meio-de [נְתִיב֥וֹת] caminhos-seus juízo');
INSERT INTO verses VALUES (16693, 20, 8, 21, '[לְהַנְחִ֖יל] [אֹהֲבַ֥י] [׀] [יֵ֑שׁ] e eu preencher');
INSERT INTO verses VALUES (16694, 20, 8, 22, 'yhwh [קָ֭נָנִי] רֵאשִׁ֣ית caminho dele oriente [מִפְעָלָ֣יו] desde então');
INSERT INTO verses VALUES (16695, 20, 8, 23, '[מֵ֭עוֹלָם] [נִסַּ֥כְתִּי] [מֵרֹ֗אשׁ] [מִקַּדְמֵי־אָֽרֶץ] terra');
INSERT INTO verses VALUES (16696, 20, 8, 24, '[בְּאֵין־תְּהֹמ֥וֹת] [חוֹלָ֑לְתִּי] חוֹלָ֑לְתִּי [מַ֝עְיָנ֗וֹת] [נִכְבַּדֵּי־מָֽיִם] nicbadday- águas');
INSERT INTO verses VALUES (16697, 20, 8, 25, 'betereim-acento-águia os-montes os-afogaram diante-de [גְבָע֣וֹת] [חוֹלָֽלְתִּי]');
INSERT INTO verses VALUES (16698, 20, 8, 26, 'até não terra terra [וְ֝רֹ֗אשׁ] [עָ[t]פְר֥וֹת] mundo');
INSERT INTO verses VALUES (16699, 20, 8, 27, '[בַּהֲכִינ֣וֹ] céus nome eu [בְּח֥וּקוֹ] [ח֝֗וּג] sobre abismo');
INSERT INTO verses VALUES (16700, 20, 8, 28, 'em-אַמְּצ֣וֹ shachaqim מִמָּעַל ba''azoz ''unot Tehôm:');
INSERT INTO verses VALUES (16701, 20, 8, 29, 'b''shumô laiyâm chukko u''mayim não não seu-boca בְּ֝חוּק֗וֹ fundamentos terra');
INSERT INTO verses VALUES (16702, 20, 8, 30, 'e-serei junto-a-ele Amon e-serei consolações dia dia dia diante-dele em-todo tempo:');
INSERT INTO verses VALUES (16703, 20, 8, 31, 'esfregando em-mundo terra-dele e-meus-alegres a homem homem');
INSERT INTO verses VALUES (16704, 20, 8, 32, 'e-agora filhos ouvi a-mim וְ֝אַשְׁרֵ֗י minhas-caminhos se-mantenham;');
INSERT INTO verses VALUES (16705, 20, 8, 33, 'ouvi [מוּסָ֥ר] e-eles-sabedoria e-a');
INSERT INTO verses VALUES (16706, 20, 8, 34, 'וְ֝אַשְׁרֵ֗י homem ouviu para-mim para-esconder sobre dia dia dia לִשְׁמֹ֗ר em-o-porta-s פְּתָחָֽי׃');
INSERT INTO verses VALUES (16707, 20, 8, 35, 'que [מֹ֭צְאִי] vivos WAYYPAKEʔ vida MICHAWEH׃');
INSERT INTO verses VALUES (16708, 20, 8, 36, '[וְֽ֭חֹטְאִי] [חֹמֵ֣ס] sua-alma todo [אָ֣הֲבוּ] amarão מָֽוֶת׃');
INSERT INTO chapters VALUES (637, 20, 9, 18);
INSERT INTO verses VALUES (16709, 20, 9, 1, 'sabedoria ela construiu sua casa [חָצְבָ֖ה] ammudeha sete');
INSERT INTO verses VALUES (16710, 20, 9, 2, 'cortou corta-sua tecto vinho-sua certamente preparou mesa-sua:');
INSERT INTO verses VALUES (16711, 20, 9, 3, '[שָֽׁלְחָ֣ה] [נַעֲרֹתֶ֣יהָ] chama sobre [מְרֹ֣מֵי] [קָֽרֶת]');
INSERT INTO verses VALUES (16712, 20, 9, 4, 'quem [יָסֻ֣ר] [הֵ֑נָּה] aqui-estes falta- para-ele para-ele');
INSERT INTO verses VALUES (16713, 20, 9, 5, 'לכוּ comhamu belachami ushto byain masaki');
INSERT INTO verses VALUES (16714, 20, 9, 6, 'uzvu petaim vichyu ve''ishru no-caminho binah');
INSERT INTO verses VALUES (16715, 20, 9, 7, '[יֹ֤סֵ֨ר] [׀] tomou a-ele a-ele [קָל֑וֹן] lerasha [לְרָשָׁ֣ע]');
INSERT INTO verses VALUES (16716, 20, 9, 8, 'a [לֵ֭ץ] לֵ֭ץ para-que-não [לְ֝חָכָ֗ם] [וְיֶאֱהָבֶֽךָּ] para-a-sabedoria');
INSERT INTO verses VALUES (16717, 20, 9, 9, 'dê aos seus entendidos e será entendido ainda faz saber ao justo e Joseph tomou');
INSERT INTO verses VALUES (16718, 20, 9, 10, 'a primeira de sabedoria Írath yhwh e de conhecimento קֳדוֹשִׁים בִּינַה׃');
INSERT INTO verses VALUES (16719, 20, 9, 11, 'porque em-mi יִרְבּוּ os-teus-dias [לְּ֝ךָ֗] [שְׁנ֣וֹת] vida vivos');
INSERT INTO verses VALUES (16720, 20, 9, 12, 'se [חָכַ֣מְתָּ] [לָּ֑ךְ] para-ti [לְֽבַדְּךָ֥] [תִשָּֽׂא]');
INSERT INTO verses VALUES (16721, 20, 9, 13, 'mulher-de kissilut homiya'' patayyut uval- yada''a ma:');
INSERT INTO verses VALUES (16722, 20, 9, 14, 've''yashva para-a-entrada-de be''ita'' sobre kisse'' מרומי קרת׃');
INSERT INTO verses VALUES (16723, 20, 9, 15, 'para-chamar [לְעֹֽבְרֵי־דָ֑רֶךְ] caminho [אֹֽרְחוֹתָֽם]');
INSERT INTO verses VALUES (16724, 20, 9, 16, 'quem [יָסֻ֣ר] [הֵ֑נָּה] aqui-estes e-faltando para-ele para-ele');
INSERT INTO verses VALUES (16725, 20, 9, 17, 'מַֽיִם־ [יִמְתָּ֑קוּ] [וְלֶ֖חֶם] [סְתָרִ֣ים] [יִנְעָֽם] abençoareis');
INSERT INTO verses VALUES (16726, 20, 9, 18, 'e-não conheceu porque רְפָאִ֣ים nome [קְרֻאֶֽיהָ׃] sho''al');
INSERT INTO chapters VALUES (638, 20, 10, 32);
INSERT INTO verses VALUES (16727, 20, 10, 1, '[מִשְׁלֵ֗י] [שְׁלֹ֫מֹ֥ה] filho filho יְשַׂמַּח־ pai [וּבֵ֥ן] כְּ֝סִיל [תּוּגַ֥ת] sua-mãe');
INSERT INTO verses VALUES (16728, 20, 10, 2, 'não [אוֹצְר֣וֹת] [רֶ֑שַׁע] רֶ֑שַׁע e justiça [מִמָּֽוֶת] de-morte');
INSERT INTO verses VALUES (16729, 20, 10, 3, 'não yhwh yhwh alma justo [רְשָׁעִ֣ים] ímpios');
INSERT INTO verses VALUES (16730, 20, 10, 4, 'cabeça fez כַף־ [וְיַ֖ד] [חָרוּצִ֣ים] [תַּעֲשִֽׁיר]');
INSERT INTO verses VALUES (16731, 20, 10, 5, 'אֹגֵ֣ר בַּ֭קַּיִץ filho ensinador dormindo בַּ֝קָּצִ֗יר filho Vergonha:');
INSERT INTO verses VALUES (16732, 20, 10, 6, 'בְּ֭רָכוֹת para-cabeca justo e-boca-de ímpios cubrirá violência');
INSERT INTO verses VALUES (16733, 20, 10, 7, 'macho justo para bênção e o nome ímpios Yirka:');
INSERT INTO verses VALUES (16734, 20, 10, 8, 'sabio coração ele tomará mandamentos e o cegueiro as duas línguas ele se atirará');
INSERT INTO verses VALUES (16735, 20, 10, 9, 'andando [בַּ֭תֹּם] [יֵ֣לֶךְ]  בטַח  [וּמְעַקֵּ֥שׁ] seus-caminhos [יִוָּדֵֽעַ]');
INSERT INTO verses VALUES (16736, 20, 10, 10, '[קֹ֣רֵֽץ] olho dará [עַצָּ֑בֶת] [וֶאֱוִ֥יל] bocas [יִלָּבֵֽט]');
INSERT INTO verses VALUES (16737, 20, 10, 11, 'fonte vida boca-de justo e-boca-de ímpios cubrirá violência');
INSERT INTO verses VALUES (16738, 20, 10, 12, 'שִׂ֭נְאָה [תְּעוֹרֵ֣ר] [מְדָנִ֑ים] e-sobre todo [תְּכַסֶּ֥ה] תְּכַסֶּ֥ה');
INSERT INTO verses VALUES (16739, 20, 10, 13, '[בְּשִׂפְתֵ֣י] nabon [תִּמָּצֵ֣א] sabedoria e a vara para o לֵו falta- coração');
INSERT INTO verses VALUES (16740, 20, 10, 14, 'חֲכָמִ֥ים [יִצְפְּנוּ־דָ֑עַת] דָ֑עַת [מְחִתָּ֥ה] [קְרֹבָֽה]');
INSERT INTO verses VALUES (16741, 20, 10, 15, 'הון עָ֭שִׁיר cidade-de עֻזּ֑וֹ machitá dallim reishám');
INSERT INTO verses VALUES (16742, 20, 10, 16, 'pe''alut justo lechayim t''váhat ímpio para-oferta-pelo-pecado');
INSERT INTO verses VALUES (16743, 20, 10, 17, 'orach para vidas guardiao disciplina ve''ozév repreensao matá''e');
INSERT INTO verses VALUES (16744, 20, 10, 18, 'mecasše siná'' sip̄te- falsidade u-motsí'' ele ele kesil׃');
INSERT INTO verses VALUES (16745, 20, 10, 19, 'em-multidão dvarim não [יֶחְדַּל־פָּ֑שַׁע] [וְחֹשֵׂ֖ךְ] [שְׂפָתָ֣יו] suas línguas sabedor:');
INSERT INTO verses VALUES (16746, 20, 10, 20, 'prata nibháchar língua-de justo coração ímpios um-pouco;');
INSERT INTO verses VALUES (16747, 20, 10, 21, 'שִׂפְתֵי justo irão muitos e-avílim em-carência-de coração morrerão;');
INSERT INTO verses VALUES (16748, 20, 10, 22, 'ברכת yhwh ela enriqueça e-não dor com-ela com ela:');
INSERT INTO verses VALUES (16749, 20, 10, 23, 'como-risada para-um-estúpido fazer intenção e sabedoria a homem-de será-sabedoria');
INSERT INTO verses VALUES (16750, 20, 10, 24, 'de temor ímpio ela entrará e-a-ta''avat justos será dado:');
INSERT INTO verses VALUES (16751, 20, 10, 25, 'como passagem de vapor e-não-há ímpio e justo base-de eternidade');
INSERT INTO verses VALUES (16752, 20, 10, 26, 'como fermento para os dentes e-cão para-olhos assim o-castor para-os');
INSERT INTO verses VALUES (16753, 20, 10, 27, 'Írath yhwh adiciona dias e-anos ímpios colheremos');
INSERT INTO verses VALUES (16754, 20, 10, 28, '[תּוֹחֶ֣לֶת] justos שִׂמְחָה -e-esperança ímpios to-a-ve-d-sefres');
INSERT INTO verses VALUES (16755, 20, 10, 29, 'refúgio [לַ֭תֹּם] o-caminho-de yhwh וּ֝מְחִתָּ֗ה para-trabalhadores: iniquidade');
INSERT INTO verses VALUES (16756, 20, 10, 30, 'justo para-sempre não [וּ֝רְשָׁעִ֗ים] não não habitare-m terra');
INSERT INTO verses VALUES (16757, 20, 10, 31, 'boca-de justo [חָכְמָ֑ה] sabedoria [תַּ֝הְפֻּכ֗וֹת] [תִּכָּרֵֽת]');
INSERT INTO verses VALUES (16758, 20, 10, 32, 'שִׂפְתֵ֣י justo [יֵדְע֣וּן] [רָצ֑וֹן] [וּפִ֥י] ímpios vire-se-vire-se;');
INSERT INTO chapters VALUES (639, 20, 11, 31);
INSERT INTO verses VALUES (16759, 20, 11, 1, '[מֹאזְנֵ֣י] [מִ֭רְמָה] abominação-de yhwh [וְאֶ֖בֶן] [שְׁלֵמָ֣ה] e a vontade');
INSERT INTO verses VALUES (16760, 20, 11, 2, 'veio [וַיָּבֹ֣א] E-veio [וְֽאֶת־צְנוּעִ֥ים] e-a חוכמה׃');
INSERT INTO verses VALUES (16761, 20, 11, 3, '[תֻּמַּ֣ת] יְשָׁרִ֣ים [תַּנְחֵ֑ם] [וְסֶ֖לֶף] [בּוֹגְדִ֣ים]');
INSERT INTO verses VALUES (16762, 20, 11, 4, 'não [ה֭וֹן] [בְּי֣וֹם] em-dia-de [וּ֝צְדָקָ֗ה] e justiça [מִמָּֽוֶת] de-morte');
INSERT INTO verses VALUES (16763, 20, 11, 5, '[צִדְקַ֣ת] integro [תְּיַשֵּׁ֣ר] caminho dele [וּ֝בְרִשְׁעָת֗וֹ] cairá perverso');
INSERT INTO verses VALUES (16764, 20, 11, 6, '[צִדְקַ֣ת] yesharim [תַּצִּילֵ֑ם] [וּ֝בְהַוַּ֗ת] [בֹּגְדִ֥ים] [יִלָּכֵֽדוּ]');
INSERT INTO verses VALUES (16765, 20, 11, 7, '[בְּמ֤וֹת] homem ímpio perderá TIKvah [וְתוֹחֶ֖לֶת] [אוֹנִ֣ים] [אָבָֽדָה]');
INSERT INTO verses VALUES (16766, 20, 11, 8, 'justo [מִצָּרָ֣ה] [נֶחֱלָ֑ץ] E-veio ímpio em-lugar-dele');
INSERT INTO verses VALUES (16767, 20, 11, 9, '[בְּפֶ֗ה] [חָ֭נֵף] [יַשְׁחִ֣ת] companheiro-seu [וּ֝בְדַ֗עַת] justos [יֵחָלֵֽצוּ]');
INSERT INTO verses VALUES (16768, 20, 11, 10, 'com-boas justos [תַּעֲלֹ֣ץ] [קִרְיָ֑ה] [וּבַאֲבֹ֖ד] ímpios rinah');
INSERT INTO verses VALUES (16769, 20, 11, 11, '[בְּבִרְכַּ֣ת] yesharim [תָּר֣וּם] קרת [וּבְפִ֥י] ímpios [תֵּהָרֵֽס]');
INSERT INTO verses VALUES (16770, 20, 11, 12, 'בָּז־ para-o-amigo falta- coração e-homem');
INSERT INTO verses VALUES (16771, 20, 11, 13, 'andando [רָ֭כִיל] [מְגַלֶּה־סּ֑וֹד] [וְנֶאֱמַן־ר֝֗וּחַ] [מְכַסֶּ֥ה] espírito palavra');
INSERT INTO verses VALUES (16772, 20, 11, 14, 'בְּאֵ֣ין [תַּ֭חְבֻּלוֹת] ele cairá povo  וּ֝תְשׁוּעָ֗ה  em-multidão  יוֹעֵֽץ׃');
INSERT INTO verses VALUES (16773, 20, 11, 15, '[רַע־יֵ֭רוֹעַ] [כִּי־עָ֣רַב] porque tarde זָ֑ר [בּוֹטֵֽחַ]');
INSERT INTO verses VALUES (16774, 20, 11, 16, 'esposa-de חֵ֭ן [כָּב֑וֹד] glória [יִתְמְכוּ־עֹֽשֶׁר] dez');
INSERT INTO verses VALUES (16775, 20, 11, 17, 'גֹּמֵ֣ל nafsho homem bondade ve-ore she''ero akhariri:');
INSERT INTO verses VALUES (16776, 20, 11, 18, 'רָשָׂע fez pe''alat- falsidade e-sown tsedakah shekher verdade');
INSERT INTO verses VALUES (16777, 20, 11, 19, 'כֵּן־ tsedakah le-chayyim e perseguindo mal para a morte;');
INSERT INTO verses VALUES (16778, 20, 11, 20, 'abominação-de yhwh [עִקְּשֵׁי־לֵ֑ב] coração וּ֝רְצוֹנ֗וֹ [דָֽרֶךְ] caminho');
INSERT INTO verses VALUES (16779, 20, 11, 21, 'mão na mão não será lavado mau e semente— justos será salvo;');
INSERT INTO verses VALUES (16780, 20, 11, 22, 'anel ouro em fúria porco mulher bonita e saía sabor:');
INSERT INTO verses VALUES (16781, 20, 11, 23, 'ta''avat justos somente bom esperança ímpios útero:');
INSERT INTO verses VALUES (16782, 20, 11, 24, 'há espalhando e acrescentado ainda e escuridão da reta somente para-maçura:');
INSERT INTO verses VALUES (16783, 20, 11, 25, 'alma-de bênção tudáshon e-marve também ele jore:');
INSERT INTO verses VALUES (16784, 20, 11, 26, 'moné bar iquebáhu para-ão e-bênção para-cabeca Mashbir:');
INSERT INTO verses VALUES (16785, 20, 11, 27, 'Shoher Yevakkesh Ratzon Ve''dorash mal Tey''onenu:');
INSERT INTO verses VALUES (16786, 20, 11, 28, 'Botach Be''asoro ele Yifal Ve''ke''aléh צדיקים יפרחו׃');
INSERT INTO verses VALUES (16787, 20, 11, 29, 'perturbador-de ביתו [יִנְחַל־ר֑וּחַ] espírito וְעֶבֶד ê-vil לַחֲכַם־ coração');
INSERT INTO verses VALUES (16788, 20, 11, 30, '[פְּֽרִי־צַ֭דִּיק] árvore vida vivos [נְפָשׂ֣וֹת] [חָכָֽם] חָכָֽם׃');
INSERT INTO verses VALUES (16789, 20, 11, 31, 'eis justo na-terra [יְשֻׁלָּ֑ם] certamente porque rashá');
INSERT INTO chapters VALUES (640, 20, 12, 28);
INSERT INTO verses VALUES (16790, 20, 12, 1, 'amou amou דעאת [דָּ֑עַת] repreensão [תוֹכַ֣חַת]');
INSERT INTO verses VALUES (16791, 20, 12, 2, 'bom [יָפִ֣יק] [רָ֭צוֹן] de-yhwh e-homem intenções [יַרְשִֽׁיעַ]');
INSERT INTO verses VALUES (16792, 20, 12, 3, 'não homem homem [וְשֹׁ֥רֶשׁ] e raiz dos-justos não- será-movido:');
INSERT INTO verses VALUES (16793, 20, 12, 4, 'esposa-de chayil coroa baʿalāh ucreqav beʿatsmotay מְבִישָֽׁה׃');
INSERT INTO verses VALUES (16794, 20, 12, 5, 'מחשבות justos juízo [תַּחְבֻּל֖וֹת] ímpios fraude');
INSERT INTO verses VALUES (16795, 20, 12, 6, 'palavras-de ímpios [אֱרָב־דָּ֑ם] sangue [יְ֝שָׁרִ֗ים] [יַצִּילֵֽם]');
INSERT INTO verses VALUES (16796, 20, 12, 7, '[הָפ֣וֹךְ] ímpios [וְאֵינָ֑ם] וּבֵ֖ית justos [יַעֲמֹֽד]');
INSERT INTO verses VALUES (16797, 20, 12, 8, '[לְֽפִי־שִׂ֭כְלוֹ] [יְהֻלַּל־אִ֑ישׁ] [וְנַעֲוֵה־לֵ֝֗ב] será [לָבֽוּז] coração será');
INSERT INTO verses VALUES (16798, 20, 12, 9, 'bom [נִ֭קְלֶה] E servo a-ele [מִ֝מְּתַכַּבֵּ֗ד] e-faltando pão');
INSERT INTO verses VALUES (16799, 20, 12, 10, 'que conhece justo alma [בְּהֶמְתּ֑וֹ] [וְֽרַחֲמֵ֥י] ímpios');
INSERT INTO verses VALUES (16800, 20, 12, 11, 'servo [אַ֭דְמָתוֹ] [יִֽשְׂבַּֽע־לָ֑חֶם] pão e perseguindo [חֲסַר־לֵֽב] falta- coração');
INSERT INTO verses VALUES (16801, 20, 12, 12, 'desejar ímpio [מְצ֣וֹד] males veshoresh justos dê');
INSERT INTO verses VALUES (16802, 20, 12, 13, 'em-perversidade labios-meus enganado mal e-ele-saiu de-angustia צַדִּֽיק׃');
INSERT INTO verses VALUES (16803, 20, 12, 14, 'do-fruto-de meu-boca homem jurará bom e-reparação por-meio-de- a-ele a-ele');
INSERT INTO verses VALUES (16804, 20, 12, 15, 'o-caminho-de o-avulso retido em-olhos-dele e-שומע para-a-sugestão sábio:');
INSERT INTO verses VALUES (16805, 20, 12, 16, 'רעה no-dia será-sabido de-ira e-cobrirá calão astuto');
INSERT INTO verses VALUES (16806, 20, 12, 17, 'expulsará fidelidade dirá justica e testemunho mentiras engano');
INSERT INTO verses VALUES (16807, 20, 12, 18, 'há como fontes espada e língua sabios cura');
INSERT INTO verses VALUES (16808, 20, 12, 19, 'língua de verdade serás firmes para sempre e-até retiro-me língua-de mentira');
INSERT INTO verses VALUES (16809, 20, 12, 20, 'da mentira בְּלֶב־ mal mau e-auxiliares paz alegria');
INSERT INTO verses VALUES (16810, 20, 12, 21, 'não serão-enganados o-direito todo iniquidade mal estão-cheios mau');
INSERT INTO verses VALUES (16811, 20, 12, 22, 'abominação-de yhwh as-bocas-de falsidade e-fazem a-lealdade o-seu-desejo');
INSERT INTO verses VALUES (16812, 20, 12, 23, 'homem astuto [כֹּ֣סֶה] דעאת  וְלֵ֥ב kesilim chamaria avó:');
INSERT INTO verses VALUES (16813, 20, 12, 24, 'mão-de [תִּמְשׁ֑וֹל] [ו֝רְמִיָּ֗ה] [תִּהְיֶ֥ה] será para-tributo');
INSERT INTO verses VALUES (16814, 20, 12, 25, 'דַּאֲגָה בְּלֵב־ homem yaschenah bom bom yeshammehenah');
INSERT INTO verses VALUES (16815, 20, 12, 26, 'yet merekhehu justo e-caminho ímpios tate''um');
INSERT INTO verses VALUES (16816, 20, 12, 27, 'não yacharok remiyah tsido vehohn- homem yakar חָרֽוּץ׃');
INSERT INTO verses VALUES (16817, 20, 12, 28, '[בְּאֹֽרַח־צְדָקָ֥ה] vida vivos ve-de-re-kh [אַל־מָֽוֶת] a מָֽוֶת׃');
INSERT INTO chapters VALUES (641, 20, 13, 25);
INSERT INTO verses VALUES (16818, 20, 13, 1, 'filho o-sábio mussar pai [וְ֝לֵ֗ץ] não ouviu');
INSERT INTO verses VALUES (16819, 20, 13, 2, 'do-fruto-de פי־ homem bom bom e-alma traidores violência');
INSERT INTO verses VALUES (16820, 20, 13, 3, 'נֹצֵ֣ר píyo guardião-de sua-alma posqé sáfáthay mehítath- a-ele');
INSERT INTO verses VALUES (16821, 20, 13, 4, 'mitávuh va''ayín nafsho atzéyl vénefesh khárutsim טּוֹדַשׁ׃');
INSERT INTO verses VALUES (16822, 20, 13, 5, 'palavra-de שֶׁ֭קֶר יִשְׂנָ֣א justo [יַבְאִ֥ישׁ] [וְיַחְפִּֽיר]');
INSERT INTO verses VALUES (16823, 20, 13, 6, '[צְ֭דָקָה] [תִּצֹּ֣ר] [תָּם־דָּ֑רֶךְ] caminho [תְּסַלֵּ֥ף] [חַטָּֽאת] חטאת：');
INSERT INTO verses VALUES (16824, 20, 13, 7, 'há [מִ֭תְעַשֵּׁר] e-não-há todo [מִ֝תְרוֹשֵׁ֗שׁ] [וְה֣וֹן] muito');
INSERT INTO verses VALUES (16825, 20, 13, 8, 'Cofar [נֶֽפֶשׁ־אִ֣ישׁ] homem dez-o [לֹא־שָׁמַ֥ע] não ouviu');
INSERT INTO verses VALUES (16826, 20, 13, 9, '[אוֹר־צַדִּיקִ֥ים] justos [וְנֵ֖ר] e-Ner ímpios conhecereis');
INSERT INTO verses VALUES (16827, 20, 13, 10, 'somente [יִתֵּ֣ן] dará מַצָּה e-a חוכמה׃');
INSERT INTO verses VALUES (16828, 20, 13, 11, '[ה֭וֹן] [מֵהֶ֣בֶל] [יִמְעָ֑ט] [וְקֹבֵ֖ץ] sobre mão');
INSERT INTO verses VALUES (16829, 20, 13, 12, 'touca feita com doença- coração vida vivos desejo בָאָֽה׃');
INSERT INTO verses VALUES (16830, 20, 13, 13, 'reprovação por palavra que se abra a-ele E-viu mandamento ele יְשׁוּלַם׃');
INSERT INTO verses VALUES (16831, 20, 13, 14, 'lei-de o-sábio fonte vida לָ֝ס֗וּר מִמֹּ֥קְשֵׁי מָֽוֶת׃');
INSERT INTO verses VALUES (16832, 20, 13, 15, 'she-ke-l bom dê graça ve-de-re-kh traidores eitan');
INSERT INTO verses VALUES (16833, 20, 13, 16, 'todo [יַעֲשֶׂ֣ה] fará [וּ֝כְסִ֗יל] וּ֝כְסִ֗יל [אִוֶּֽלֶת] avó:');
INSERT INTO verses VALUES (16834, 20, 13, 17, 'anjo ímpio cairá בְּרָ֑ע [וְצִ֖יר] [אֱמוּנִ֣ים] cura--');
INSERT INTO verses VALUES (16835, 20, 13, 18, 'רֵ֣ישׁ וְ֭קָלוֹן פּוֹרֵ֣עַ disciplina וְשׁוֹמֵ֖ר repreensao יהוה יְכֻבָּֽד׃');
INSERT INTO verses VALUES (16836, 20, 13, 19, '[תַּאֲוָ֣ה] [נִ֭הְיָה] [תֶּעֱרַ֣ב] [לְנָ֑פֶשׁ] [וְתוֹעֲבַ֥ת] kesilim vire-se מֵרָע׃');
INSERT INTO verses VALUES (16837, 20, 13, 20, 'a sabios וְרֹעֶ֖ה כְסִילִ֣ים YE Raoa :');
INSERT INTO verses VALUES (16838, 20, 13, 21, 'de-perversidade TARDDEF maldade e-a Tsadikim Yashalem - bom');
INSERT INTO verses VALUES (16839, 20, 13, 22, 'bom Yanhich filhos-de filhos Vezaphun Latsadik força Chotea :');
INSERT INTO verses VALUES (16840, 20, 13, 23, 'Rav - Nir cabeças-de וְיֵ֥שׁ נִ֝סְפֶּ֗ה sem juízo');
INSERT INTO verses VALUES (16841, 20, 13, 24, 'חוֹשֵׂךְ [שִׁ֭בְטוֹ] odeia בְנ֑וֹ [וְ֝אֹהֲב֗וֹ] [שִֽׁחֲר֥וֹ] de correção:');
INSERT INTO verses VALUES (16842, 20, 13, 25, 'tsaddiq אֹ֭כֵל para-satisfazer sua-alma e-ventre ímpios você faltará');
INSERT INTO chapters VALUES (642, 20, 14, 35);
INSERT INTO verses VALUES (16843, 20, 14, 1, 'sabedoria mulheres ela construiu sua casa e Avelã em-suas-mãos destruí-lo-ás;');
INSERT INTO verses VALUES (16844, 20, 14, 2, 'andando em-suas-retas temerá yhwh e-mostrá-lo-á seus-caminhos destruí-los-ás;');
INSERT INTO verses VALUES (16845, 20, 14, 3, 'em-suas-bocas o-salazar o-pestis גַּאֲוָ֑ה וְשִׂפְתֵ֥י חֲ֝כָמִ֗ים תִּשְׁמוּרֵֽם׃');
INSERT INTO verses VALUES (16846, 20, 14, 4, 'בְּאֵ֣ין אֲ֭לָפִים אֵב֣וּס בָּ֑ר וְרָב־ תְּ֝בוּא֗וֹת בְּכֹ֣חַ שֽׁוֹר׃');
INSERT INTO verses VALUES (16847, 20, 14, 5, 'até אֱ֭מוּנִים não יְכַזֵּ֑ב וְיָפִ֥יחַ כְּ֝זָבִ֗ים até mentira');
INSERT INTO verses VALUES (16848, 20, 14, 6, 'בִּקֶּשׁ־ לֵ֣ץ sabedoria וָאָ֑יִן וְדַ֖עַת לְנָב֣וֹן נָקָֽל׃');
INSERT INTO verses VALUES (16849, 20, 14, 7, 'vai מִ֭נֶּגֶד a homem-de כְּסִ֑יל וּבַל־ יָדַעְתָּ שִׂפְתֵי־ דָֽעַת׃');
INSERT INTO verses VALUES (16850, 20, 14, 8, 'sabedoria-de astuto הָבִ֣ין caminho dele וְאִוֶּ֖לֶת כְּסִילִ֣ים fraude');
INSERT INTO verses VALUES (16851, 20, 14, 9, 'אֱוִילִים יָלִיץ אָשָׁם e-entre יְשָׁרִ֣ים רָצוֹן׃');
INSERT INTO verses VALUES (16852, 20, 14, 10, 'coração יֹודֵעַ מָרָה sua-alma וּבְשִׂמְחָתוֹ não יִתְעַרַב זָר׃');
INSERT INTO verses VALUES (16853, 20, 14, 11, 'casa ímpios יִשֹּׂם e-o-hel יְשָׁרִ֣ים jafri-ach');
INSERT INTO verses VALUES (16854, 20, 14, 12, 'ha o-caminho-de yashar diante-de homem ve-acharitah yhwh מָֽוֶת׃');
INSERT INTO verses VALUES (16855, 20, 14, 13, 'também bishok yikab- coração ve-acharitah- alegria tugah');
INSERT INTO verses VALUES (16856, 20, 14, 14, 'midrakay yisbea ס֣וּג coração וּ֝מֵעָלָ֗יו homem bom');
INSERT INTO verses VALUES (16857, 20, 14, 15, 'פֶּ֭תִי יַאֲמִין para-todo palavra וְ֝עָר֗וּם entenderá לַאֲשֻׁרֽוֹ׃');
INSERT INTO verses VALUES (16858, 20, 14, 16, 'sábio temer e-se-apartará מֵרָ֑ע וּ֝כְסִ֗יל מִתְעַבֵּ֥ר וּבוֹטֵֽחַ׃');
INSERT INTO verses VALUES (16859, 20, 14, 17, 'קְֽצַר־ apêim fará iuteléth e-homem mizimmót yishná''e');
INSERT INTO verses VALUES (16860, 20, 14, 18, 'nachalû [פְתָאיִ֣ם] iuteléth va''arúmim yakhtirû da''ath');
INSERT INTO verses VALUES (16861, 20, 14, 19, 'שַׁחֲוּ רָעִים diante-de bons וּרְשָׁעִים sobre שַׁעֲרֵי צַדִּיק׃');
INSERT INTO verses VALUES (16862, 20, 14, 20, 'também לְרֵעֵהוּ יִשָׂנֵא possuir וְאֹהֲבֵי עָשִׁיר muitos');
INSERT INTO verses VALUES (16863, 20, 14, 21, 'בָּז־ para-o-amigo que-errou e-reparador seu-bem-aventurado');
INSERT INTO verses VALUES (16864, 20, 14, 22, 'não-será? vão-se-perder mal mau e- misericórdia e-verdade bom bom');
INSERT INTO verses VALUES (16865, 20, 14, 23, 'em-todo será será paz e-palavra-de bocas somente- para a falta:');
INSERT INTO verses VALUES (16866, 20, 14, 24, 'coroa sabios dez avó escória avó:');
INSERT INTO verses VALUES (16867, 20, 14, 25, 'salvar almas até verdade e espírito mentirosos fraude');
INSERT INTO verses VALUES (16868, 20, 14, 26, 'בְּיִרְאַ֣ת yhwh segurança- עֹ֑ז será será מַחְסֶֽה׃');
INSERT INTO verses VALUES (16869, 20, 14, 27, 'יִרְאַ֣ת yhwh fonte vida לָ֝ס֗וּר [מִמֹּ֥קְשֵׁי] [מָֽוֶת]');
INSERT INTO verses VALUES (16870, 20, 14, 28, '[בְּרָב־עָ֥ם] povo [וּבְאֶ֥פֶס] rei [מְחִתַּ֥ת] [רָזֽוֹן]');
INSERT INTO verses VALUES (16871, 20, 14, 29, 'erêx ápaim chefe-de tuvana úktsar- espírito mêrim iut:');
INSERT INTO verses VALUES (16872, 20, 14, 30, 'chayyei besharim coração marpe úrakab עצמות קינאה׃');
INSERT INTO verses VALUES (16873, 20, 14, 31, 'OOSEK- DAL חERGEF faz-lhe UMEKHAVDO CHOVEN EVEYN׃');
INSERT INTO verses VALUES (16874, 20, 14, 32, 'BARAATO YIDACHAHEH ímpio e choshe em-mo-to tsaddiq:');
INSERT INTO verses VALUES (16875, 20, 14, 33, 'b-le-ve nabon tanuch sabedoria u-beker kesilim tiydah:');
INSERT INTO verses VALUES (16876, 20, 14, 34, '[צְדָקָ֥ה] [תְרֽוֹמֵֽם־גּ֑וֹי] nação [לְאֻמִּ֣ים] [חַטָּֽאת]');
INSERT INTO verses VALUES (16877, 20, 14, 35, '[רְֽצוֹן־מֶ֭לֶךְ] rei [מַשְׂכִּ֑יל] [וְ֝עֶבְרָת֗וֹ] [תִּהְיֶ֥ה] será');
INSERT INTO chapters VALUES (643, 20, 15, 33);
INSERT INTO verses VALUES (16878, 20, 15, 1, '[מַֽעֲנֶה־רַּ֭ךְ] [יָשִׁ֣יב] [חֵמָ֑ה] [וּדְבַר־עֶ֝֗צֶב] e-palavra-de');
INSERT INTO verses VALUES (16879, 20, 15, 2, 'língua-de חֲ֭כָמִים תֵּיטִ֣יב דעאת e-boca-de כְ֝סִילִ֗ים יַבִּ֥יעַ אִוֶּֽלֶת׃');
INSERT INTO verses VALUES (16880, 20, 15, 3, 'em-todo os-olhos-de yhwh yhwh [רָעִ֥ים] [וטוֹבִֽים]');
INSERT INTO verses VALUES (16881, 20, 15, 4, '[מַרְפֵּ֣א] [לָ֭שׁוֹן] árvore vida [וְסֶ֥לֶף] [בָּ֝֗הּ] [שֶׁ֣בֶר] [בְּרֽוּחַ]');
INSERT INTO verses VALUES (16882, 20, 15, 5, 'אֱוִ֗יל יִ֭נְאַץ מוּסַ֣ר seu-pai וְשֹׁמֵ֖ר repreensao יַעְרִֽם׃');
INSERT INTO verses VALUES (16883, 20, 15, 6, 'casa justo [חֹ֣סֶן] muito [וּבִתְבוּאַ֖ת] ímpio [נֶעְכָּֽרֶת]');
INSERT INTO verses VALUES (16884, 20, 15, 7, '[שִׂפְתֵ֣י] [חֲ֭כָמִים] [יְזָ֣רוּ] [דָ֑עַת] [וְלֵ֖ב] [כְּסִילִ֣ים] não');
INSERT INTO verses VALUES (16885, 20, 15, 8, 'sacrifício-de ímpios abominação-de yhwh e oração יְשָׁרִ֣ים e a vontade');
INSERT INTO verses VALUES (16886, 20, 15, 9, 'abominação-de yhwh o-caminho-de ímpio e perseguindo justiça amará');
INSERT INTO verses VALUES (16887, 20, 15, 10, 'מוּסָ֣ר mal ao abandonar caminho odiando repreensão morra');
INSERT INTO verses VALUES (16888, 20, 15, 11, 'sho''al וַ֭אֲבַדּוֹן diante yhwh certamente porque לִבּ֥וֹת filhos-de homem');
INSERT INTO verses VALUES (16889, 20, 15, 12, 'não [יֶאֱהַב־לֵ֭ץ] [הוֹכֵ֣חַֽ] a-ele a-ele não [יֵלֵֽךְ] não');
INSERT INTO verses VALUES (16890, 20, 15, 13, 'coração [שָׂ֭מֵחַ] [יֵיטִ֣ב] face [וּבְעַצְּבַת־לֵ֝ב] espírito espírito');
INSERT INTO verses VALUES (16891, 20, 15, 14, 'coração [נָ֭בוֹן] [יְבַקֶּשׁ־דָּ֑עַת] [*ופני] [**וּפִ֥י] [כְ֝סִילִ֗ים] [יִרְעֶ֥ה]');
INSERT INTO verses VALUES (16892, 20, 15, 15, 'todo dias-de afligido [וְטֽוֹב־לֵ֝֗ב] [מִשְׁתֶּ֥ה] coração');
INSERT INTO verses VALUES (16893, 20, 15, 16, '[טוֹב־מְ֭עַט] [בְּיִרְאַ֣ת] yhwh yhwh [רָ֝֗ב] muito nele');
INSERT INTO verses VALUES (16894, 20, 15, 17, 'bom [אֲרֻחַ֣ת] [יָ֭רָק] [וְאַהֲבָה־שָׁ֑ם] nome [אָ֝ב֗וּס] [וְשִׂנְאָה־בֽוֹ]');
INSERT INTO verses VALUES (16895, 20, 15, 18, 'homem ira יגרה מדון והארך אף-יימ ישקט רִֽיב׃');
INSERT INTO verses VALUES (16896, 20, 15, 19, 'o-caminho-de [עָ֭צֵל] [כִּמְשֻׂ֣כַת] [חָ֑דֶק] [וְאֹ֖רַח] [יְשָׁרִ֣ים] [סְלֻלָֽה]');
INSERT INTO verses VALUES (16897, 20, 15, 20, 'filho sabio יְשַׂמַּח־ pai homem homem sua-mãe mãe-de ele');
INSERT INTO verses VALUES (16898, 20, 15, 21, '[אִ֭וֶּלֶת] alegria [לַחֲסַר־לֵ֑ב] coração e-homem [יְיַשֶׁר־לָֽכֶת]');
INSERT INTO verses VALUES (16899, 20, 15, 22, 'destrua pensamentos no vazio segredo e em muitos conselheiros arise');
INSERT INTO verses VALUES (16900, 20, 15, 23, 'alegria para o homem por causa de seu-boca e-palavra em-suas-vezes que- bom');
INSERT INTO verses VALUES (16901, 20, 15, 24, 'caminho vida para-cima para-enganar para vire-se de-tartarus torne-se-lado');
INSERT INTO verses VALUES (16902, 20, 15, 25, 'casa vãos ישׂах yhwh yhwh território אלמנוה');
INSERT INTO verses VALUES (16903, 20, 15, 26, 'abominação-de yhwh [מַחְשְׁב֣וֹת] mal [וּ֝טְהֹרִ֗ים] [אִמְרֵי־נֹֽעַם]');
INSERT INTO verses VALUES (16904, 20, 15, 27, 'עכר ביתו בורחא בָּצַע ושונה [מַתָּנֹ֣ת] viverá:');
INSERT INTO verses VALUES (16905, 20, 15, 28, 'coração justo haverá para responder e-boca-de ímpios fará surgir mau:');
INSERT INTO verses VALUES (16906, 20, 15, 29, 'distante yhwh dos ímpios e oração justos será ouvido:');
INSERT INTO verses VALUES (16907, 20, 15, 30, '[מְֽאוֹר־עֵ֭ינַיִם] [יְשַׂמַּֽח־לֵ֑ב] [שְׁמוּעָ֥ה] coração [תְּדַשֶּׁן־עָֽצֶם]');
INSERT INTO verses VALUES (16908, 20, 15, 31, 'אֹ֗זֶן repreensao vivos vida sabios תָּלִֽין׃');
INSERT INTO verses VALUES (16909, 20, 15, 32, '[פּוֹרֵ֣עַ] [מ֭וּסָר] [מוֹאֵ֣ס] sua-alma [וְשׁוֹמֵ֥עַ] [תּ֝וֹכַ֗חַת] [ק֣וֹנֶה] coração');
INSERT INTO verses VALUES (16910, 20, 15, 33, '[יִרְאַ֣ת] yhwh [מוּסַ֣ר] sabedoria [וְלִפְנֵ֖י] [כָב֣וֹד] [עֲנָוָֽה]');
INSERT INTO chapters VALUES (644, 20, 16, 33);
INSERT INTO verses VALUES (16911, 20, 16, 1, 'לְאָדָ֥ם מַֽעַרְכֵי־ coração וּ֝מֵיְהוָ֗ה resposta língua:');
INSERT INTO verses VALUES (16912, 20, 16, 2, 'todo caminhos- homem justos em-olhos-dele yhwh ventos yhwh');
INSERT INTO verses VALUES (16913, 20, 16, 3, 'גֹּ֣ל a yhwh trabalhos-te e-estabelecer-se-ão intenções-te:');
INSERT INTO verses VALUES (16914, 20, 16, 4, 'todo feito yhwh resposta e-também רָשָׁע para-o-dia mal');
INSERT INTO verses VALUES (16915, 20, 16, 5, 'abominação-de yhwh todo mão coração não [יִנָּקֶֽה] não');
INSERT INTO verses VALUES (16916, 20, 16, 6, 'בְּחֵסֶד וֶאֱמֶת יְכֻפָּר Avon וּבְיִרְאַת yhwh afasta-te מֵרָע׃');
INSERT INTO verses VALUES (16917, 20, 16, 7, 'בִּרְצֹות yhwh דָּרְכֵי־ homem também seus-inimigos pagará com-ele');
INSERT INTO verses VALUES (16918, 20, 16, 8, 'טוֹב־ um-pouco em-justiça de-abundância-de seus-frutos sem juízo');
INSERT INTO verses VALUES (16919, 20, 16, 9, 'coração homem contará caminho dele e-耶和华 fará seu passo;');
INSERT INTO verses VALUES (16920, 20, 16, 10, '[קֶ֤סֶם] sobre [עַֽל־שִׂפְתֵי־מֶ֑לֶךְ] rei não não');
INSERT INTO verses VALUES (16921, 20, 16, 11, '[פֶּ֤לֶס] [׀] [וּמֹאזְנֵ֣י] para-יהוה [לַֽיהוָ֑ה] todo [כָּל־אַבְנֵי־כִֽיס]');
INSERT INTO verses VALUES (16922, 20, 16, 12, 'abominação-de מְ֭לָכִים fazer רֶ֑שַׁע que בִ֝צְדָקָ֗ה será trono;');
INSERT INTO verses VALUES (16923, 20, 16, 13, 'desejo reis bocas— justica e falantes— יְשָׁרִ֣ים amarão;');
INSERT INTO verses VALUES (16924, 20, 16, 14, 'Hamate rei anjos— morte e-homem sábio será expiada;');
INSERT INTO verses VALUES (16925, 20, 16, 15, '[בְּאוֹר־פְּנֵי־מֶ֥לֶךְ] vida rei vivos [מַלְקֽוֹשׁ]');
INSERT INTO verses VALUES (16926, 20, 16, 16, '[קְֽנֹה־חָכְמָ֗ה] [מַה־טּ֥וֹב] que bom [בִּ֝ינָ֗ה] [נִבְחָ֥ר] [מִכָּֽסֶף]');
INSERT INTO verses VALUES (16927, 20, 16, 17, 'mísera yesharim afasta-te de-mau guardando sua-alma guardião seu caminho');
INSERT INTO verses VALUES (16928, 20, 16, 18, 'diante-de grão orgulho e-diante-de escálio espírito espírito');
INSERT INTO verses VALUES (16929, 20, 16, 19, 'bom valo- espírito a de-partilhado שָׁ֝לָ֗ל a גֵּאִֽים׃');
INSERT INTO verses VALUES (16930, 20, 16, 20, '[מַשְׂכִּ֣יל] sobre palavra [וּבוֹטֵ֖חַ] bom [אַשְׁרָֽיו]');
INSERT INTO verses VALUES (16931, 20, 16, 21, 'לַחֲכַם־ será-chamada יִקָּרֵ֣א נָב֑וֹן וּמֶ֥תֶק שְׂ֝פָתַ֗יִם yo-sif tomou');
INSERT INTO verses VALUES (16932, 20, 16, 22, 'fonte vida discernimento בעלאו וּמוּסַ֖ר אֱוִילִ֣ים אִוֶּֽלֶת׃');
INSERT INTO verses VALUES (16933, 20, 16, 23, 'coração sabio יַשְׂכִּ֣יל פִּ֑יהוּ e-sobre de sua boca yo-sif tomou');
INSERT INTO verses VALUES (16934, 20, 16, 24, '[צוּף־דְּ֭בַשׁ] [אִמְרֵי־נֹ֑עַם] [מָת֥וֹק] [לַ֝נֶּפֶשׁ] [וּמַרְפֵּ֥א] [לָעָֽצֶם]');
INSERT INTO verses VALUES (16935, 20, 16, 25, '[יֵ֤שׁ] o-caminho-de [יָ֭שָׁר] diante-de homem [דַּרְכֵי־מָֽוֶת]');
INSERT INTO verses VALUES (16936, 20, 16, 26, 'alma [עָ֭מֵל] [עָ֣מְלָה] para-ele porque [עָלָ֣יו] sobre-ele');
INSERT INTO verses VALUES (16937, 20, 16, 27, 'homem [בְּ֭לִיַּעַל] [כֹּרֶ֣ה] maldade e-sobre [**שְׂ֝פָת֗וֹ] [כְּאֵ֣שׁ]');
INSERT INTO verses VALUES (16938, 20, 16, 28, 'homem [תַּ֭הְפֻּכוֹת] [יְשַׁלַּ֣ח] [מָד֑וֹן] [וְ֝נִרְגָּ֗ן[6]] [מַפְרִ֥יד]');
INSERT INTO verses VALUES (16939, 20, 16, 29, 'homem [חָ֭מָס] [יְפַתֶּ֣ה] companheiro-seu [וְ֝הוֹלִיכ֗וֹ] no-caminho não bom');
INSERT INTO verses VALUES (16940, 20, 16, 30, 'עֹצֶה עֵ֭ינָיו לַחְשׁוֹב תַּהְפּוֹךְ֑וֹת קֹרֵץ de sua boca כִּלָּה mal');
INSERT INTO verses VALUES (16941, 20, 16, 31, 'coroa תִּפְאֶרֶת שֵׂיבָה em-a-caminho צְ֝דָקָה תִּמּוֹצֵא׃');
INSERT INTO verses VALUES (16942, 20, 16, 32, 'bom [אֶ֣רֶךְ] [אַ֭פַּיִם] [מִגִּבּ֑וֹר] [וּמֹשֵׁ֥ל] [בְּ֝רוּח֗וֹ] [מִלֹּכֵ֥ד] cidade');
INSERT INTO verses VALUES (16943, 20, 16, 33, '[בַּ֭חֵיק] [יוּטַ֣ל] a [וּ֝מֵיְהוָ֗ה] [כָּל־מִשְׁפָּטֽוֹ] todo');
INSERT INTO chapters VALUES (645, 20, 17, 28);
INSERT INTO verses VALUES (16944, 20, 17, 1, 'bom faz- destruição- e-alegria- nela da-casa- enchei que contenda:');
INSERT INTO verses VALUES (16945, 20, 17, 2, 'servo- instrutor- governará- em-filho- vergonha- e-em irmãos dividirá herança');
INSERT INTO verses VALUES (16946, 20, 17, 3, 'forrador em-prata e-esculpidor em-ouro e-examinará as-cavidades yhwh');
INSERT INTO verses VALUES (16947, 20, 17, 4, '[מֵ֭רַע] [מַקְשִׁ֣יב] sobre borda-de iniquidade [עַל־לְשׁ֥וֹן] [הַוֺּֽת] sobre');
INSERT INTO verses VALUES (16948, 20, 17, 5, 'לוג daraשׁ חreff faz-lhe שמח לאליד não ינקה׃');
INSERT INTO verses VALUES (16949, 20, 17, 6, 'coroa זְ֭קֵנִים filhos-de filhos וְתִפְאֶ֖רֶת filhos avos-eus');
INSERT INTO verses VALUES (16950, 20, 17, 7, 'não [לְנָבָ֣ל] [שְׂפַת־יֶ֑תֶר] certamente [כִּֽי־לְנָדִ֥יב] [שְׂפַת־שָֽׁקֶר] porque');
INSERT INTO verses VALUES (16951, 20, 17, 8, 'pedra- graca הַ֭שֹׁחַד em-olhos-de בְעָלָ֑יו a todo que יִפְנֶ֣ה jashill');
INSERT INTO verses VALUES (16952, 20, 17, 9, 'mekhasses- peshay mevakesh ahavah veshene bedabar maphrid aluf');
INSERT INTO verses VALUES (16953, 20, 17, 10, 'tachat ge''arah bemeb''in de-o-golpear kasisil cem');
INSERT INTO verses VALUES (16954, 20, 17, 11, 'somente merry yebakkesh- mau umal''akh akharizi yeshullakh- em-ele');
INSERT INTO verses VALUES (16955, 20, 17, 12, 'pagos dov שַׁכּ֣וּל בְּאִישׁ e-a כְּ֝סִיל בְּאִוּלְתּוֹ׃');
INSERT INTO verses VALUES (16956, 20, 17, 13, 'מֵשִׁ֣יב רָ֭עָה debaixo boa não רָ֝עָה מִבֵּיתֽוֹ׃');
INSERT INTO verses VALUES (16957, 20, 17, 14, 'פּ֣וֹטֵר águas רֵאשִׁ֣ית מָד֑וֹן e-ante se-revelou a-disputa abandonou-se');
INSERT INTO verses VALUES (16958, 20, 17, 15, 'justo ímpio e-irritou justo toavat yhwh também dois-deles');
INSERT INTO verses VALUES (16959, 20, 17, 16, 'por-que isto Mecir por-mão-de cabisil para-comprar sabedoria e-léb- não.');
INSERT INTO verses VALUES (16960, 20, 17, 17, 'em-todo ética amou háraa'' e-a'' para-tzará irá-levá-dò');
INSERT INTO verses VALUES (16961, 20, 17, 18, 'homem falta- coração touquá'' káf'' tarde árubbá''ah diante-de seu-amigo');
INSERT INTO verses VALUES (16962, 20, 17, 19, 'amou [פֶּ֭שַׁע] amou [מַצָּ֑ה] [מַגְבִּ֥יהַּ] [פִּ֝תְח֗וֹ] [מְבַקֶּשׁ־שָֽׁבֶר]');
INSERT INTO verses VALUES (16963, 20, 17, 20, '[עִקֶּשׁ־לֵ֭ב] não não [וְנֶהְפָּ֥ךְ] bom [יִפּ֥וֹל] [בְּרָעָֽה]');
INSERT INTO verses VALUES (16964, 20, 17, 21, '[יֹלֵ֣ד] [כְּ֭סִיל] [לְת֣וּגָה] a-ele e-não [אֲבִ֣י] pai-de');
INSERT INTO verses VALUES (16965, 20, 17, 22, 'coração [שָׂ֭מֵחַ] [יֵיטִ֣ב] [גֵּהָ֑ה] e-Espírito-de [נְ֝כֵאָ֗ה] [תְּיַבֶּשׁ־גָּֽרֶם]');
INSERT INTO verses VALUES (16966, 20, 17, 23, 'שֹׁ֣חַד מֵ֭חֵיק ímpio tomar-ah לְ֝הַטּ֗וֹת אָרְח֥וֹת juízo');
INSERT INTO verses VALUES (16967, 20, 17, 24, 'a face-de [חָכְמָ֑ה] sabedoria [כְ֝סִ֗יל] [בִּקְצֵה־אָֽרֶץ] terra');
INSERT INTO verses VALUES (16968, 20, 17, 25, '[כַּ֣עַס] [לְ֭אָבִיו] filho [כְּסִ֑יל] [וּ֝מֶ֗מֶר] [לְיוֹלַדְתּֽוֹ]');
INSERT INTO verses VALUES (16969, 20, 17, 26, 'também [עֲנ֣וֹשׁ] [לַצַּדִּ֣יק] bom [לְהַכּ֖וֹת] [נְדִיבִ֣ים] sobre');
INSERT INTO verses VALUES (16970, 20, 17, 27, 'חוֹשֵׂךְ Seus palavras que conhece דעאת espírito homem sabedoria:');
INSERT INTO verses VALUES (16971, 20, 17, 28, 'também Evil que muda sabio seus pensamentos sua mente suas línguas que investiga');
INSERT INTO chapters VALUES (646, 20, 18, 24);
INSERT INTO verses VALUES (16972, 20, 18, 1, 'para a gula busca נִפְרָ֑ד em-todo תּ֝וּשִׁיָּ֗ה יִתְגַּלָּֽע׃');
INSERT INTO verses VALUES (16973, 20, 18, 2, 'não [כְּ֭סִיל] [בִּתְבוּנָ֑ה] que porque se');
INSERT INTO verses VALUES (16974, 20, 18, 3, '[בְּֽבוֹא־רָ֭שָׁע] ímpio veio também [חֶרְפָּֽה]');
INSERT INTO verses VALUES (16975, 20, 18, 4, 'águas [עֲ֭מֻקִּים] palavras-de [פִי־אִ֑ישׁ] homem ribeiro-de [מְק֣וֹר] [חָכְמָֽה]');
INSERT INTO verses VALUES (16976, 20, 18, 5, '[שְׂאֵ֣ת] face-de ímpio não bom [בַּמִּשְׁפָּֽט]');
INSERT INTO verses VALUES (16977, 20, 18, 6, 'שפתים כסיל יבאוּ בריב e-sua-boca para-alegrias chamaria');
INSERT INTO verses VALUES (16978, 20, 18, 7, 'boca-de cisil morte- a-ele e-suas-bocas moqueš sua-alma:');
INSERT INTO verses VALUES (16979, 20, 18, 8, 'palavras-de nirgān como-estranhamente e-eles desceram חדרי- בָֽטֶן׃');
INSERT INTO verses VALUES (16980, 20, 18, 9, 'também [מִתְרַפֶּ֣ה] [בִמְלַאכְתּ֑וֹ] [אָ֥ח] ele [לְבַ֣עַל] [מַשְׁחִֽית]');
INSERT INTO verses VALUES (16981, 20, 18, 10, '[מִגְדַּל־עֹ֭ז] [שֵׁ֣ם] yhwh yhwh [צַדִּ֣יק] [וְנִשְׂגָּֽב]');
INSERT INTO verses VALUES (16982, 20, 18, 11, '[ה֣וֹן] [עָ֭שִׁיר] cidade-de [עֻזּ֑וֹ] [וּכְחוֹמָ֥ה] [נִ֝שְׂגָּבָ֗ה] [בְּמַשְׂכִּיתֽוֹ]');
INSERT INTO verses VALUES (16983, 20, 18, 12, 'diante-de [יִגְבַּ֣הּ] [לֵ[t]ב־אִ֑ישׁ] homem [כָב֣וֹד] [עֲנָוֽ͏ָה]');
INSERT INTO verses VALUES (16984, 20, 18, 13, 'מֵשִׁ֣יב palavra betereim-acento-águia ישמע אילית hi- ל֝֗וֹ וכלימה׃');
INSERT INTO verses VALUES (16985, 20, 18, 14, 'espírito-de homem [מַחֲלֵ֑הוּ] e-Espírito-de [נְ֝כֵאָ֗ה] quem quem');
INSERT INTO verses VALUES (16986, 20, 18, 15, 'coração נבון יקנה－ דעאת e-ozên chakhamim tavbakkeš- daath:');
INSERT INTO verses VALUES (16987, 20, 18, 16, 'matan homem yarhib a-ele velifnei- gedolim yanhenu:');
INSERT INTO verses VALUES (16988, 20, 18, 17, 'justo harašôn em-seu-disputa seu-amigo e-investigá-lo:');
INSERT INTO verses VALUES (16989, 20, 18, 18, 'de-midianitas fará-assentar-se o-sortimento e-entre fortes fará-se-dividir:');
INSERT INTO verses VALUES (16990, 20, 18, 19, 'irmão se-alargou de-mquírat- óz kibrách armôn:');
INSERT INTO verses VALUES (16991, 20, 18, 20, 'do-fruto-de de-pi- homem tishbá betnó tibúath sháfátay yisbá:');
INSERT INTO verses VALUES (16992, 20, 18, 21, '[מָ֣וֶת] [וְ֭חַיִּים] por-mão-de [וְ֝אֹהֲבֶ֗יהָ] [יֹאכַ֥ל] [פִּרְיָֽהּ]');
INSERT INTO verses VALUES (16993, 20, 18, 22, 'encontrou mulher encontrou bom WAYYPAKEʔ רצון MICHAWEH׃');
INSERT INTO verses VALUES (16994, 20, 18, 23, 'תחנונים YEDABER- possuir e o rico יַעֲנֶ֥ה fortalezas:');
INSERT INTO verses VALUES (16995, 20, 18, 24, 'homem amigos para se alegrar e há amou adere do irmão:');
INSERT INTO chapters VALUES (647, 20, 19, 29);
INSERT INTO verses VALUES (16996, 20, 19, 1, 'bom pobre andando em sua integridade de curvado de sua boca e-ele כסיל׃');
INSERT INTO verses VALUES (16997, 20, 19, 2, 'também [בְּלֹא־דַ֣עַת] [נֶ֣פֶשׁ] alma não bom [חוֹטֵֽא]');
INSERT INTO verses VALUES (16998, 20, 19, 3, 'אילית homem תסלף caminho dele e-sobre yhwh יזעף coração-dele');
INSERT INTO verses VALUES (16999, 20, 19, 4, '[ה֗וֹן] [יֹ֭סִיף] [רֵעִ֣ים] muitos [וְ֝דָ֗ל] [מֵרֵ֥עהוּ] divide-se');
INSERT INTO verses VALUES (17000, 20, 19, 5, 'até [שְׁ֭קָרִים] não [יִנָּקֶ֑ה] [וְיָפִ֥יחַ] [כְּ֝זָבִ֗ים] não [יִמָּלֵֽט]');
INSERT INTO verses VALUES (17001, 20, 19, 6, '[רַ֭בִּים] [יְחַלּ֣וּ] [פְנֵֽי־נָדִ֑יב] [וְכָל־הָ֝רֵ֗עַ] e-todo [מַתָּֽן]');
INSERT INTO verses VALUES (17002, 20, 19, 7, 'todo [אֲחֵי־רָ֨שׁ] [׀] [שְֽׂנֵאֻ֗הוּ] certamente que [מְ֭רֵעֵהוּ] [רָחֲק֣וּ] nós [מְרַדֵּ֖ף] [אֲמָרִ֣ים] eles');
INSERT INTO verses VALUES (17003, 20, 19, 8, '[קֹֽנֶה־לֵּ֭ב] coração amou sua-alma guardando [לִמְצֹא־טֽוֹב] bom');
INSERT INTO verses VALUES (17004, 20, 19, 9, 'até [שְׁ֭קָרִים] não [יִנָּקֶ֑ה] [וְיָפִ֖יחַ] [כְּזָבִ֣ים] [יֹאבֵֽד׃]');
INSERT INTO verses VALUES (17005, 20, 19, 10, 'não [לִכְסִ֣יל] [תַּעֲנ֑וּג] certamente [כִּֽי־לְעֶ֤בֶד] porque [מְשֹׁ֬ל] [בְּשָׂרִֽים]');
INSERT INTO verses VALUES (17006, 20, 19, 11, 'discernimento homem [הֶאֱרִ֣יךְ] [אַפּ֑וֹ] [וְ֝תִפאַרְתּ֗וֹ] [עֲבֹ֣ר] sobre');
INSERT INTO verses VALUES (17007, 20, 19, 12, '[נַ֣הַם] [כַּ֭כְּפִיר] [זַ֣עַף] rei [וּכְטַ֖ל] sobre erva');
INSERT INTO verses VALUES (17008, 20, 19, 13, '[הַוֺּ֣ת] [לְ֭אָבִיו] filho [כְּסִ֑יל] [וְדֶ֥לֶף] [טֹ֝רֵ֗ד] [מִדְיְנֵ֥י] mulher');
INSERT INTO verses VALUES (17009, 20, 19, 14, 'casa וָ֭הוֹן נַחֲלַ֣ת אָב֑וֹת e-dios mulher que-escala:');
INSERT INTO verses VALUES (17010, 20, 19, 15, 'enganosidade destruirá sono-profundo e-alma fome será:');
INSERT INTO verses VALUES (17011, 20, 19, 16, 'guardião-de mandamento guardião-de sua-alma destruidor seus-caminhos');
INSERT INTO verses VALUES (17012, 20, 19, 17, 'מלוה yhwh חוןן דל וגמלו yešallêm- a-ele');
INSERT INTO verses VALUES (17013, 20, 19, 18, 'IASer BINeka porque há TIKvah e-a HAMita a תִּשָּׂ֥א alma-tua');
INSERT INTO verses VALUES (17014, 20, 19, 19, 'ira NASo UNes que se תַּ֝צִּ֗יל וְע֣וֹד תּוֹסִֽפ׃');
INSERT INTO verses VALUES (17015, 20, 19, 20, 'ouviu עֵ֭צָה וְקַבֵּ֣ל disciplina לְ֝מַ֗עַן תֶּחְכַּ֥ם בְּאַחֲרִיתֶֽךָ׃');
INSERT INTO verses VALUES (17016, 20, 19, 21, '[רַבּ֣וֹת] [מַחֲשָׁב֣וֹת] [בְּלֶב־אִ֑ישׁ] homem yhwh yhwh ela');
INSERT INTO verses VALUES (17017, 20, 19, 22, '[תַּאֲוַ֣ת] homem bondade-de-ele [וְטֽוֹב־רָ֝שׁ] [מֵאִ֥ישׁ] [כָּזָֽב]');
INSERT INTO verses VALUES (17018, 20, 19, 23, '[יִרְאַ֣ת] yhwh [לְחַיִּ֑ים] [וְשָׂבֵ֥עַ] [יָ֝לִ֗ין] não mal mau');
INSERT INTO verses VALUES (17019, 20, 19, 24, '[טָ֘מַ֤ן] [עָצֵ֣ל] sua-mão [בַּצַּלָּ֑חַת] também não [יְשִׁיבֶֽנָּה] não');
INSERT INTO verses VALUES (17020, 20, 19, 25, 'לֵ֣ץ תַּ֭כֶּה וּפֶ֣תִי יַעְרִ֑ם וְהוֹכִ֥יחַ לְ֝נָב֗וֹן entenderá דָּֽעַת׃');
INSERT INTO verses VALUES (17021, 20, 19, 26, '[מְֽשַׁדֶּד־אָ֭ב] pai mãe filho filho [וּמַחְפִּֽיר]');
INSERT INTO verses VALUES (17022, 20, 19, 27, '[חַֽדַל־בְּ֭נִי] filhos-de para-ouvir [לִ֝שְׁג֗וֹת] [מֵֽאִמְרֵי־דָֽעַת]');
INSERT INTO verses VALUES (17023, 20, 19, 28, 'até bliyʿal yalitz juízo e-boca-de ímpios yevelaʿ־ iniquidade');
INSERT INTO verses VALUES (17024, 20, 19, 29, 'nachonu para os לֵץ as שֹׁפטים e as מהולמות para o לֵו cavaleiros׃');
INSERT INTO chapters VALUES (648, 20, 20, 30);
INSERT INTO verses VALUES (17025, 20, 20, 1, 'לֵץ homem o שׁכר e-todo o שׁגה nele não Sábio:');
INSERT INTO verses VALUES (17026, 20, 20, 2, 'Naham Kakafir Eimath rei Mitabbaro Chatêa Nafsho:');
INSERT INTO verses VALUES (17027, 20, 20, 3, 'Kavod La''ish Shabath mê-rib e-todo ê-vil yi-tgallaʿ');
INSERT INTO verses VALUES (17028, 20, 20, 4, 'mê-choreph ʿatsel não yaḥarosh bakkāṣir vā-ʾayin');
INSERT INTO verses VALUES (17029, 20, 20, 5, 'águas [עֲ֭מֻקִּים] [עֵצָ֣ה] [בְלֶב־אִ֑ישׁ] homem e-homem [יִדְלֶֽנָּה]');
INSERT INTO verses VALUES (17030, 20, 20, 6, '[רָב־אָדָ֗ם] chamaria [אִ֣ישׁ] homem bondade-de-ele e-homem quem quem');
INSERT INTO verses VALUES (17031, 20, 20, 7, 'passeando [בְּתֻמּ֣וֹ] justo [אַשְׁרֵ֖י] [בָנָ֣יו] atrás-dele');
INSERT INTO verses VALUES (17032, 20, 20, 8, 'rei habitante sobre [מְזָרֶ֖ה] [בְעֵינָ֣יו] [כָּל־רָֽע] todo mau');
INSERT INTO verses VALUES (17033, 20, 20, 9, 'quem [זִכִּ֣יתִי] [לִבִּ֑י] meu-coração [מֵחַטָּאתִֽי]');
INSERT INTO verses VALUES (17034, 20, 20, 10, 'pedra וָ֭אֶבֶן אֵיפָ֣ה וְאֵיפָ֑ה toavat yhwh também dois-deles');
INSERT INTO verses VALUES (17035, 20, 20, 11, 'também [בְּ֭מַעֲלָלָיו] [יִתְנַכֶּר־נָ֑עַר] [אִם־זַ֖ךְ] se [פָּעֳלֽוֹ]');
INSERT INTO verses VALUES (17036, 20, 20, 12, 'o-ouvido שֹׁ֭מַעַת וְעַ֣יִן viu yhwh fez também dois-deles');
INSERT INTO verses VALUES (17037, 20, 20, 13, 'a [שֵׁ֭נָה] [פֶּן־תִּוָּרֵ֑שׁ] para-que-não [עֵינֶ֣יךָ] [שְֽׂבַֽע־לָֽחֶם]');
INSERT INTO verses VALUES (17038, 20, 20, 14, 'mau mau dira הַקּוֹנֶה וְאֹזֵל a-ele então יִתְהַלָּֽל׃');
INSERT INTO verses VALUES (17039, 20, 20, 15, 'há ouro [וְרָב־פְּנִינִ֑ים] [וּכְלִ֥י] [יְ֝קָ֗ר] [שִׂפְתֵי־דָֽעַת]');
INSERT INTO verses VALUES (17040, 20, 20, 16, '[לְֽקַח־בִּ֭גְדוֹ] [כִּי־עָ֣רַב] porque tarde [*נכרים] [**נָכְרִיָּ֣ה] [חַבְלֵֽהוּ]');
INSERT INTO verses VALUES (17041, 20, 20, 17, 'tarde [לָ֭אִישׁ] pão falsidade [וְ֝אַחַ֗ר] [יִמָּֽלֵא־פִ֥יהוּ] [חָצָֽץ]');
INSERT INTO verses VALUES (17042, 20, 20, 18, '[מַ֭חֲשָׁבוֹת] [בְּעֵצָ֣ה] [תִכּ֑וֹן] [וּ֝בְתַחְבֻּל֗וֹת] fez guerra');
INSERT INTO verses VALUES (17043, 20, 20, 19, '[גּֽוֹלֶה־סּ֭וֹד] [הוֹלֵ֣ךְ] andando [וּלְפֹתֶ֥ה] [שְׂ֝פָתָ֗יו] não não');
INSERT INTO verses VALUES (17044, 20, 20, 20, '[מְ֭קַלֵּל] seu-pai [וְאִמּ֑וֹ] [יִֽדְעַ֥ךְ] [נֵ֝ר֗וֹ] escuridão');
INSERT INTO verses VALUES (17045, 20, 20, 21, 'נחלה na-primeira ואחריתה não תברך׃');
INSERT INTO verses VALUES (17046, 20, 20, 22, 'a [אֲשַׁלְּמָה־רָ֑ע] [קַוֵּ֥ה] mau [וְיֹ֣שַֽׁע] para-ti');
INSERT INTO verses VALUES (17047, 20, 20, 23, 'abominação-de yhwh pedra [וָאָ֑בֶן] [וּמֹאזְנֵ֖י] [מִרְמָ֣ה] não bom');
INSERT INTO verses VALUES (17048, 20, 20, 24, '[מֵיהוָ֥ה] [מִצְעֲדֵי־גָ֑בֶר] [וְ֝אָדָ֗ם] [מַה־יָּבִ֥ין] que');
INSERT INTO verses VALUES (17049, 20, 20, 25, '[מוֹקֵ֣שׁ] homem [יָ֣לַע] santidade e-depois [נְדָרִ֣ים] [לְבַקֵּֽר]');
INSERT INTO verses VALUES (17050, 20, 20, 26, '[מְזָרֶ֣ה] ímpios rei sabio [וַיָּ֖שֶׁב] sobre-eles אֲפַן׃');
INSERT INTO verses VALUES (17051, 20, 20, 27, '[נֵ֣ר] yhwh [נִשְׁמַ֣ת] homem [חֹ֝פֵ֗שׂ] todo');
INSERT INTO verses VALUES (17052, 20, 20, 28, 'bondade [וֶ֭אֱמֶת] [יִצְּרוּ־מֶ֑לֶךְ] rei [בַּחֶ֣סֶד] [כִּסְאֽוֹ]');
INSERT INTO verses VALUES (17053, 20, 20, 29, '[תִּפְאֶ֣רֶת] [בַּחוּרִ֣ים] [כֹּחָ֑ם] [וַהֲדַ֖ר] [זְקֵנִ֣ים] [שֵׂיבָֽה]');
INSERT INTO verses VALUES (17054, 20, 20, 30, '[חַבֻּר֣וֹת] [פֶּ֭צַע] [*תמריק] [**תַּמְר֣וּק] [בְּרָ֑ע] [וּ֝מַכּ֗וֹת]');
INSERT INTO chapters VALUES (649, 20, 21, 31);
INSERT INTO verses VALUES (17055, 20, 21, 1, '[פַּלְגֵי־מַ֣יִם] águas [בְּיַד־יְהוָ֑ה] rei por-mão-de yhwh sobre todo que');
INSERT INTO verses VALUES (17056, 20, 21, 2, 'todo [יָשָׁ֣ר] homem [וְתֹכֵ֖ן] em-olhos-dele yhwh yhwh');
INSERT INTO verses VALUES (17057, 20, 21, 3, 'fez justiça e-juízo נבחר a-yhwh מזבח׃');
INSERT INTO verses VALUES (17058, 20, 21, 4, '[רוּם־עֵ֭ינַיִם] [וּרְחַב־לֵ֑ב] [נִ֖ר] coração [חַטָּֽאת]');
INSERT INTO verses VALUES (17059, 20, 21, 5, '[מַחְשְׁב֣וֹת] [חָ֭רוּץ] somente [וְכָל־אָ֝֗ץ] e-todo');
INSERT INTO verses VALUES (17060, 20, 21, 6, 'פֹּ֣עַל א֭וֹצָרוֹת bilhôn falsidade הֶבֶל nidáp mevakeshê- מָֽוֶת׃');
INSERT INTO verses VALUES (17061, 20, 21, 7, 'shôd- os ímpios que porque mê''ânû para-fazer juízo');
INSERT INTO verses VALUES (17062, 20, 21, 8, 'haphakpak o-caminho-de homem vazâr vézakh ישׁר פָּעֳלֽוֹ׃');
INSERT INTO verses VALUES (17063, 20, 21, 9, 'bom para-habitar sobre pinat- gôg de-a-eshet mi-da-yanim e-casa-de cha-ber');
INSERT INTO verses VALUES (17064, 20, 21, 10, 'alma ímpio iutah mau não yuchan be-ayno seu-amigo');
INSERT INTO verses VALUES (17065, 20, 21, 11, 'ba-anash לֵ֭ץ yechkham pe-ti u-ba-hashkil para-a-sabedoria tomará-o- daath:');
INSERT INTO verses VALUES (17066, 20, 21, 12, 'מַשְׂכּ֣יל justo para-casa-de ímpio pedra-polida ímpios para-a-maldição;');
INSERT INTO verses VALUES (17067, 20, 21, 13, 'encherá-os seus-ouvidos da-voz-de דל chamaria ele chamará e-não será-respondido;');
INSERT INTO verses VALUES (17068, 20, 21, 14, 'matan em-secreto יִכְפֶּה־ tambem וְשֹׁ֥חַד בַּ֝חֵ֗ק חֵמָ֥ה עַזָּֽה׃');
INSERT INTO verses VALUES (17069, 20, 21, 15, 'alegria לַ֭צַּדִּיק fazer juízo וּ֝מְחִתָּ֗ה para-trabalhadores: iniquidade');
INSERT INTO verses VALUES (17070, 20, 21, 16, 'homem de-caminho-de הַשּׂכֵּ֑ל no convés רְפָאִ֣ים יָנֽוּחַ׃');
INSERT INTO verses VALUES (17071, 20, 21, 17, 'homem [מַ֭חְסוֹר] amou [שִׂמְחָ֑ה] amou [יַֽיִן־וָ֝שֶׁ֗מֶן] não não');
INSERT INTO verses VALUES (17072, 20, 21, 18, 'Cofar לַצַּדִּיק ímpio e-debaixo-de יְשָׁרִ֣ים בּוֹגֵֽד׃');
INSERT INTO verses VALUES (17073, 20, 21, 19, 'bom [שֶׁ֥בֶת] em-terra-de [מֵאֵ֖שֶׁת] [*מדונים] [**מִדְיָנִ֣ים]');
INSERT INTO verses VALUES (17074, 20, 21, 20, '[אוֹצָ֤ר] [׀] agradável [וָ֭שֶׁמֶן] [בִּנְוֵ֣ה] [חָכָ֑ם] homem homem');
INSERT INTO verses VALUES (17075, 20, 21, 21, 'רֹ֭דֵף justiça וָחָ֑סֶד ymtzaa vida tsedaka וְכָבֽוֹד׃');
INSERT INTO verses VALUES (17076, 20, 21, 22, 'cidade גִּ֭בֹּרִים subir sabio וַ֝יֹּ֗רֶד força מִבְטֶחָֽה׃');
INSERT INTO verses VALUES (17077, 20, 21, 23, 'guardião-de פִּ֭יו וּלְשׁוֹנ֑וֹ guardião מִצָּר֣וֹת sua-alma:');
INSERT INTO verses VALUES (17078, 20, 21, 24, '[זֵ֣ד] [יָ֭הִיר] [לֵ֣ץ] seu-nome [ע֝וֹשֶׂ֗ה] [בְּעֶבְרַ֥ת] [זָדֽוֹן]');
INSERT INTO verses VALUES (17079, 20, 21, 25, 'será a minha gula עָצֵ֣ל תְּמִיתֶ֑נּוּ porque recusaram suas-mãos para-fazer');
INSERT INTO verses VALUES (17080, 20, 21, 26, 'todo [הִתְאַוָּ֣ה] desejo [וְצַדִּ֥יק] [יִ֝תֵּ֗ן] [וְלֹ֣א] e-não');
INSERT INTO verses VALUES (17081, 20, 21, 27, 'sacrifício-de ímpios [תּוֹעֵבָ֑ה] certamente porque [יְבִיאֶֽנּוּ]');
INSERT INTO verses VALUES (17082, 20, 21, 28, 'até КІЗАВІМ será destruído e-homem ШОМЕАֿ ЛАНАЦАХ יְדַבֵּֽר׃');
INSERT INTO verses VALUES (17083, 20, 21, 29, 'ХІУЕЗ homem ímpio ВІФАНАЙ ВІЯШАРАֿ ele');
INSERT INTO verses VALUES (17084, 20, 21, 30, 'não-há ХАЧМАХ e-não-há tuvana e-não-há consulta diante-de yhwh');
INSERT INTO verses VALUES (17085, 20, 21, 31, 'cavalo preparado para-o-dia guerra e para Yahweh a salvação');
INSERT INTO chapters VALUES (650, 20, 22, 29);
INSERT INTO verses VALUES (17086, 20, 22, 1, 'escolhido nome dos dezimos muito do ouro e do prata graca bom');
INSERT INTO verses VALUES (17087, 20, 22, 2, 'עָשִׁיר e o restante [נִפְגָּ֑שׁוּ] fez [כֻלָּ֣ם] yhwh');
INSERT INTO verses VALUES (17088, 20, 22, 3, 'astuto viu ver [רָעָ֣ה] [*ויסתר] [**וְנִסְתָּ֑ר]');
INSERT INTO verses VALUES (17089, 20, 22, 4, 'porque [עֲ֭נָוָה] יִרְאַ֣ת yhwh dez [וְכָב֣וֹד] [וְחַיִּֽים]');
INSERT INTO verses VALUES (17090, 20, 22, 5, '[צִנִּ֣ים] [פַּ֭חִים] no-caminho עיקֵשׁ שֹׁמֵר sua-alma יִרְחַק de-eles');
INSERT INTO verses VALUES (17091, 20, 22, 6, '[חֲנֹ֣ךְ] [לַ֭נַּעַר] sobre boca-de também também porque [מִמֶּֽנָּה] não');
INSERT INTO verses VALUES (17092, 20, 22, 7, 'עָ֭שִׁיר בְּרָשִׁים יִמְשׁוֹל וְעֶבֶד לֹוֶה a homem-de MALVEH:');
INSERT INTO verses VALUES (17093, 20, 22, 8, 'ZOR''AH AVLAH iniquidade VESHEVET EBRATO YIKLEH:');
INSERT INTO verses VALUES (17094, 20, 22, 9, 'bom ele ele YEBORAKH porque deu MILLACHMO LADAL:');
INSERT INTO verses VALUES (17095, 20, 22, 10, 'GARESH לֵ֭ץ e saia מדון e habite julgamento e calão:');
INSERT INTO verses VALUES (17096, 20, 22, 11, 'amou coração favor de sua boca רֵעֵ֥הוּ rei');
INSERT INTO verses VALUES (17097, 20, 22, 12, 'os-olhos-de yhwh guardaram דָ֑עַת e deslizou palavras-de mentiroso:');
INSERT INTO verses VALUES (17098, 20, 22, 13, 'disse עָ֭צֵל leão fora no-meio-de ruas assassino:');
INSERT INTO verses VALUES (17099, 20, 22, 14, '[שׁוּחָ֣ה] [עֲ֭מֻקָּה] boca-de [זָר֑וֹת] [זְע֥וּם] yhwh nome');
INSERT INTO verses VALUES (17100, 20, 22, 15, 'אִ֭וֶּלֶת קְשׁוּרָ֣ה בְּלֶב־ נָ֑עַר bastão מ֝וּסָ֗ר nós de-nós');
INSERT INTO verses VALUES (17101, 20, 22, 16, 'עֹ֣שֵֽׁק DAL לְהַרְבּ֣וֹת a-ele deu לְ֝עָשִׁ֗יר somente para a falta:');
INSERT INTO verses VALUES (17102, 20, 22, 17, 'הַ֥ט o teu ouvido palavras-de sábios e o teu coração tashit para a minha conhecimento');
INSERT INTO verses VALUES (17103, 20, 22, 18, 'porque belos porque guarda-los no teu ventre serão juntos sobre as tuas lábios');
INSERT INTO verses VALUES (17104, 20, 22, 19, 'para-ser- בַּ֭יהוָה de-seu-braço te-hodi-a-tei o-dia também tu');
INSERT INTO verses VALUES (17105, 20, 22, 20, 'acaso-nao escrevi a-ti em-conselhos e-te-hodi-a:');
INSERT INTO verses VALUES (17106, 20, 22, 21, 'para-te-hodi-a-los-tei cortadores palavras verdade para-responder palavras verdade para-o-enviador:');
INSERT INTO verses VALUES (17107, 20, 22, 22, 'a que DAL porque de-a- ele e-a que-destrua afligido no-portão:');
INSERT INTO verses VALUES (17108, 20, 22, 23, 'porque yhwh contenda contendas e-defina a que-definem alma');
INSERT INTO verses VALUES (17109, 20, 22, 24, 'a que-chora a בַּ֣עַל tambem não homem ira não vem:');
INSERT INTO verses VALUES (17110, 20, 22, 25, 'para-que-não tealaf e-lakachta מוֹקֵ֣שׁ para-nafshecha');
INSERT INTO verses VALUES (17111, 20, 22, 26, 'a seja na-bate- caph ba-orvim masaot');
INSERT INTO verses VALUES (17112, 20, 22, 27, 'se não-há para-ti para-salém por-que ele-tomará de-cama-teu de-baixo-de-teu;');
INSERT INTO verses VALUES (17113, 20, 22, 28, 'a serás-afastado eternidade eternidade que fizeram pais-tus;');
INSERT INTO verses VALUES (17114, 20, 22, 29, 'viste-que homem- rápido na-sua-trabalho ante- reis יתיצָב não יתיצֵב diante-de חשוכִים׃');
INSERT INTO chapters VALUES (651, 20, 23, 35);
INSERT INTO verses VALUES (17115, 20, 23, 1, 'porque [לִלְח֣וֹם] [אֶת־מוֹשֵׁ֑ל] a [תָּ֝בִ֗ין] entre [לְפָנֶֽיךָ] a que');
INSERT INTO verses VALUES (17116, 20, 23, 2, '[וְשַׂמְתָּ֣] [שַׂכִּ֣ין] [בְּלֹעֶ֑ךָ] se [נֶ֣פֶשׁ] alma');
INSERT INTO verses VALUES (17117, 20, 23, 3, 'a [לְמַטְעַמּוֹתָ֑יו] [וְ֝ה֗וּא] pão pão');
INSERT INTO verses VALUES (17118, 20, 23, 4, 'a [לְֽהַעֲשִׁ֑יר] [מִֽבִּינָתְךָ֥] [חֲדָֽל]');
INSERT INTO verses VALUES (17119, 20, 23, 5, 'עֵינֶ֥יךָ nele וְֽאֵ֫ינֶ֥נּוּ porque fez que para-ele כְנָפַ֑יִם Cneshér os-céus');
INSERT INTO verses VALUES (17120, 20, 23, 6, 'a Tilchám a Léchem mau olho e-a Lematómatótiy:');
INSERT INTO verses VALUES (17121, 20, 23, 7, 'que [׀] Shá''ar Bénafshó Kénen- ele אכל Úštéh Yomár para-ti e-líbbo não contigo');
INSERT INTO verses VALUES (17122, 20, 23, 8, 'pítakha- aḥaltā tqiennā wəšiqhattā daberexa hannʿim∶');
INSERT INTO verses VALUES (17123, 20, 23, 9, 'em-orelhas-de [כְ֭סִיל] a [כִּֽי־יָ֝ב֗וּז] porque [מִלֶּֽיךָ]');
INSERT INTO verses VALUES (17124, 20, 23, 10, 'a [גְּב֣וּל] eternidade eternidade [יְ֝תוֹמִ֗ים] [אַל־תָּבֹֽא] a');
INSERT INTO verses VALUES (17125, 20, 23, 11, 'porque [חָזָ֑ק] [הֽוּא־יָרִ֖יב] ele [אִתָּֽךְ] a');
INSERT INTO verses VALUES (17126, 20, 23, 12, 'הָבִ֣יאָה para-a-moça teu-coração e-te-o-ouvido para-palavras-de דָֽעַת׃');
INSERT INTO verses VALUES (17127, 20, 23, 13, 'a terás-restraindo-te de-adolescente disciplina porque não com-o-bastão não não');
INSERT INTO verses VALUES (17128, 20, 23, 14, 'tu com-o-bastão terás-encantando-te vén-na-fshe-wo de-tartarus libertar-te-:');
INSERT INTO verses VALUES (17129, 20, 23, 15, 'filhos-de se [לִבֶּ֑ךָ] teu-coração [לִבִּ֣י] [גַם־אָֽנִי] também');
INSERT INTO verses VALUES (17130, 20, 23, 16, '[וְתַעְלֹ֥זְנָה] [כִלְיוֹתָ֑י] [בְּדַבֵּ֥ר] [שְׂ֝פָתֶ֗יךָ] [מֵישָׁרִֽים]');
INSERT INTO verses VALUES (17131, 20, 23, 17, 'a [לִ֭בְּךָ] [בַּֽחַטָּאִ֑ים] que porque se yhwh todo');
INSERT INTO verses VALUES (17132, 20, 23, 18, 'que se há [וְ֝תִקְוָתְךָ֗] não não');
INSERT INTO verses VALUES (17133, 20, 23, 19, 'שְׁמַע־ tu filhos-de e sábio e feliz no caminho לִבֶּֽךָ׃');
INSERT INTO verses VALUES (17134, 20, 23, 20, 'a seja o que dá vinho entre os que se deleitam em carne a-eles');
INSERT INTO verses VALUES (17135, 20, 23, 21, 'porque o que dá e se deleita יִוָּרֵ֑שׁ וּ֝קְרָעִ֗ים תַּלְבּ֣ישׁ נוּמָֽה׃');
INSERT INTO verses VALUES (17136, 20, 23, 22, 'ouviu [לְ֭אָבִיךָ] este [יְלָדֶ֑ךָ] e-a [כִּֽי־זָקְנָ֥ה] porque');
INSERT INTO verses VALUES (17137, 20, 23, 23, 'אֱמֶ֣ת compra e-a comércio sabedoria e instrução e sabedoria;');
INSERT INTO verses VALUES (17138, 20, 23, 24, 'pai-de justo sábio em-ele');
INSERT INTO verses VALUES (17139, 20, 23, 25, 'alegrará-o seu pai e sua mãe e glorificará que te gerou;');
INSERT INTO verses VALUES (17140, 20, 23, 26, '[תְּנָֽה־בְנִ֣י] filhos-de [לִ֑י] a-mim [דְּרָכַ֥י] [*תרצנה]');
INSERT INTO verses VALUES (17141, 20, 23, 27, 'porque [עֲמֻקָּ֣ה] [זוֹנָ֑ה] [וּבְאֵ֥ר] [צָ֝רָ֗ה] [נָכְרִיָּֽה]');
INSERT INTO verses VALUES (17142, 20, 23, 28, 'também [כְּחֶ֣תֶף] [תֶּֽאֱרֹ֑ב] [וּ֝בוֹגְדִ֗ים] [בְּאָדָ֥ם] [תּוֹסִֽף]');
INSERT INTO verses VALUES (17143, 20, 23, 29, 'לְמִ֨י אָוי֙ לְמִ֪י אֲב֡וֹי לְמִ֤י לְמִ֥י שִׂ֗יחַ לְ֭מִי פְּצָעִ֣ים חִנָּ֑ם לְ֝מִ֗י חַכְלִל֥וּת Olhos:');
INSERT INTO verses VALUES (17144, 20, 23, 30, '[לַֽמְאַחֲרִ֥ים] sobre [לַ֝בָּאִ֗ים] [לַחְקֹ֥ר] [מִמְסָֽךְ]');
INSERT INTO verses VALUES (17145, 20, 23, 31, 'a [יַּיִן֮] que porque [כִּֽי־יִתֵּ֣ן] porque dará [עֵינ֑וֹ] [יִ֝תְהַלֵּ֗ךְ] [בְּמֵישָׁרִֽים]');
INSERT INTO verses VALUES (17146, 20, 23, 32, '[אַ֭חֲרִיתוֹ] [כְּנָחָ֣שׁ] [יִשָּׁ֑ךְ] [וּֽכְצִפְעֹנִ֥י] [יַפְרִֽשׁ]');
INSERT INTO verses VALUES (17147, 20, 23, 33, 'אֲדַבְּרֵהַ-בְּעֵינֶיךָ temerao זָרֹות e-em-teu-coração יְדַבֵּר vire-se-vire-se;');
INSERT INTO verses VALUES (17148, 20, 23, 34, 'e-serás como-dormindo בְּלֶב־ mar e-dormindo na-cabeça cobiça-cobiça;');
INSERT INTO verses VALUES (17149, 20, 23, 35, 'batei-em-mim sem- eu-me-envergonhei me-vexaram não יָדָ֥עְתִּי quando אָקִ֑יץ אֹסִ֗יף אֲבַקְשֶׁ֥נּוּ ainda');
INSERT INTO chapters VALUES (652, 20, 24, 34);
INSERT INTO verses VALUES (17150, 20, 24, 1, 'a תְּ֭קַנֵּא em-homens maldade e-a a-ser אִתָּֽם׃');
INSERT INTO verses VALUES (17151, 20, 24, 2, 'porque שֹׁ֭ד haverá coracoes-eles וְ֝עָמָ֗ל שִׂפְתֵיהֶ֥ם תְּדַבֵּֽרְנָה׃');
INSERT INTO verses VALUES (17152, 20, 24, 3, '[בְּ֭חָכְמָה] [יִבָּ֣נֶה] casa [וּ֝בִתְבוּנָ֗ה] [יִתְכּוֹנָֽן]');
INSERT INTO verses VALUES (17153, 20, 24, 4, '[וּ֭בְדַעַת] [חֲדָרִ֣ים] [יִמָּלְא֑וּ] todo [יָקָ֣ר] [וְנָעִֽים]');
INSERT INTO verses VALUES (17154, 20, 24, 5, '[גֶּֽבֶר־חָכָ֥ם] [בַּע֑וֹז] [וְאִֽישׁ־דַּ֝֗עַת] [מְאַמֶּץ־כֹּֽחַ]');
INSERT INTO verses VALUES (17155, 20, 24, 6, 'que [בְ֭תַחְבֻּלוֹת] farás- para-ti guerra [בְּרֹ֣ב] em-multidão');
INSERT INTO verses VALUES (17156, 20, 24, 7, '[רָאמ֣וֹת] [לֶֽאֱוִ֣יל] [חָכְמ֑וֹת] [בַּ֝שַּׁ֗עַר] não [יִפְתַּח־פִּֽיהוּ]');
INSERT INTO verses VALUES (17157, 20, 24, 8, '[מְחַשֵּׁ֥ב] [לְהָרֵ֑עַ] a-ele [בַּֽעַל־מְזִמּ֥וֹת] [יִקְרָֽאוּ]');
INSERT INTO verses VALUES (17158, 20, 24, 9, 'intenção אילית חטא וtoaavat le''adam לץ׃');
INSERT INTO verses VALUES (17159, 20, 24, 10, '[הִ֭תְרַפִּיתָ] em-dia [צָרָ֗ה] angústia-de [כֹּחֶֽכָה]');
INSERT INTO verses VALUES (17160, 20, 24, 11, '[הַ֭צֵּל] [לְקֻחִ֣ים] [לַמָּ֑וֶת] [וּמָטִ֥ים] [לַ֝הֶ֗רֶג] se');
INSERT INTO verses VALUES (17161, 20, 24, 12, 'porque eis [לֹא־יָדַ֢עְנ֫וּ] não [הֲ‍ֽלֹא־תֹ֘כֵ֤ן] este [׀] [הֽוּא־יָבִ֗ין] [וְנֹצֵ֣ר] ele ele [יֵדָ֑ע] [וְהֵשִׁ֖יב] ele conheceu');
INSERT INTO verses VALUES (17162, 20, 24, 13, '[אֱכָל־בְּנִ֣י] filhos-de [כִּי־ט֑וֹב] porque bom [עַל־חִכֶּֽךָ] sobre');
INSERT INTO verses VALUES (17163, 20, 24, 14, 'כֵּ֤ן ׀ Deixa-te חָכְמָ֗ה para a tua alma se achaste e há última e a tua esperança não será derramada');
INSERT INTO verses VALUES (17164, 20, 24, 15, 'a arrebatas-te ímpio para a loucura justo a tornar-te-ás dura רִבְצוֹ׃');
INSERT INTO verses VALUES (17165, 20, 24, 16, 'que [שֶׁ֨בַע] [׀] justo [צַדִּ֣יק] [וָקָ֑ם] [וּ֝רְשָׁעִ֗ים] [יִכָּשְׁל֥וּ]');
INSERT INTO verses VALUES (17166, 20, 24, 17, '[בִּנְפֹ֣ל] a [**אֽ֭וֹיִבְךָ] [אַל־תִּשְׂמָ֑ח] a [אַל־יָגֵ֥ל] [לִבֶּֽךָ]');
INSERT INTO verses VALUES (17167, 20, 24, 18, 'para-que-não yhwh yhwh e-mal em-olhos-dele e-retornará de-lá-dela אַף׃');
INSERT INTO verses VALUES (17168, 20, 24, 19, 'a [בַּמְּרֵעִ֑ים] [אַל־תְּ֝קַנֵּ֗א] a');
INSERT INTO verses VALUES (17169, 20, 24, 20, 'que não sera última para-mal neṛ ímpios conhecereis');
INSERT INTO verses VALUES (17170, 20, 24, 21, 'tem-temor a yhwh filhos-de e-rei com que-mudam a serão-confundidos');
INSERT INTO verses VALUES (17171, 20, 24, 22, 'porque [יָק֣וּם] [אֵידָ֑ם] [וּפִ֥יד] [שְׁ֝נֵיהֶ֗ם] quem quem');
INSERT INTO verses VALUES (17172, 20, 24, 23, 'também estes [הַֽכֵּר־פָּנִ֖ים] [בְּמִשְׁפָּ֣ט] face bom');
INSERT INTO verses VALUES (17173, 20, 24, 24, '[אֹ֤מֵ֨ר] [׀] [לְרָשָׁע֮] [צַדִּ֢יק] [אָ֥תָּה] [יִקְּבֻ֥הוּ] [עַמִּ֑ים] [יִזְעָמ֥וּהוּ]');
INSERT INTO verses VALUES (17174, 20, 24, 25, 'וְלַמּוֹכִיחִ֥ים יִנְעָ֑ם וַֽ֝עֲלֵיהֶ֗ם virá בִרְכַּת־ bom');
INSERT INTO verses VALUES (17175, 20, 24, 26, '[שְׂפָתַ֥יִם] [יִשָּׁ֑ק] [מֵ֝שִׁ֗יב] [דְּבָרִ֥ים] [נְכֹחִֽים]');
INSERT INTO verses VALUES (17176, 20, 24, 27, '[הָ֘כֵ֤ן] [בַּח֨וּץ] [׀] [מְלַאכְתֶּ֗ךָ] [וְעַתְּדָ֣הּ] a-ti para-ti [אַ֝חַ֗ר] [וּבָנִ֥יתָ]');
INSERT INTO verses VALUES (17177, 20, 24, 28, 'a seja até [וַ֝הֲפִתִּ֗יתָ] [בִּשְׂפָתֶֽיךָ]');
INSERT INTO verses VALUES (17178, 20, 24, 29, 'a dirigir-te-ás como-que fez para-mim assim farei para-ele farei-voltar para-o-homem segundo-fez');
INSERT INTO verses VALUES (17179, 20, 24, 30, 'sobre campo- homem-de עָצֵ֣ל homem e-sobre como-cerro homem falta- coração');
INSERT INTO verses VALUES (17180, 20, 24, 31, 'e-eis subir todo-o com-escamas cobrir-se-ão פָנָ֣יו como-lombos e-muro suas-pedras נֶהֱרָֽסָה׃');
INSERT INTO verses VALUES (17181, 20, 24, 32, '[וָֽאֶחֱזֶ֣ה] eu [אָשִׁ֣ית] meu-coração [רָ֝אִ֗יתִי] eu-tomarei [מוּסָּֽר]');
INSERT INTO verses VALUES (17182, 20, 24, 33, 'pouco שֵׁ֭נוֹת pouco תְּנוּמ֑וֹת מְעַ֓ט ׀ חִבֻּ֖ק mãos לִשְׁכָּֽב׃');
INSERT INTO verses VALUES (17183, 20, 24, 34, 'e vêm- andando seu-começo e-seu-falta como homem מָגֵ֗ן׃');
INSERT INTO chapters VALUES (653, 20, 25, 28);
INSERT INTO verses VALUES (17184, 20, 25, 1, 'também אֵ֭לֶּה dois Shelomoh que fizeram-antigo homens- fortaleza rei-de Judá');
INSERT INTO verses VALUES (17185, 20, 25, 2, 'glória Elohim escondeu-o palavra e-glória reis- חֲקֹ֣ר palavra');
INSERT INTO verses VALUES (17186, 20, 25, 3, 'céus [לָ֭רוּם] [וָאָ֣רֶץ] [לָעֹ֑מֶק] [וְלֵ֥ב] [מְ֝לָכִ֗ים] não-há [חֵֽקֶר]');
INSERT INTO verses VALUES (17187, 20, 25, 4, 'הָג֣וֹ סִיגִ֣ים מִכָּ֑סֶף e-ele-saiu para-reforçar כֶּֽלִי׃');
INSERT INTO verses VALUES (17188, 20, 25, 5, 'ele- disse ímpio diante-de rei e-será em-justiça sua-cadeira');
INSERT INTO verses VALUES (17189, 20, 25, 6, 'a terá-se-estendido diante-de rei e-em-lugar grandes a terá-se-estabelecido');
INSERT INTO verses VALUES (17190, 20, 25, 7, 'que bom dize- para-ti עַלְ aqui מֵהַשְׁפּ֣ילְךָ diante-de נָדִ֑יב que viram de-tus-teus-olhos');
INSERT INTO verses VALUES (17191, 20, 25, 8, 'a [לָרִ֗ב] [מַ֫הֵ֥ר] para-que-não [מַה־תַּ֭עֲשֶׂה] que [בְּהַכְלִ֖ים] [אֹתְךָ֣] [רֵעֶֽךָ]');
INSERT INTO verses VALUES (17192, 20, 25, 9, '[רִֽ֭יבְךָ] [רִ֣יב] a [וְס֖וֹד] [אַחֵ֣ר] [אַל־תְּגָֽל] a');
INSERT INTO verses VALUES (17193, 20, 25, 10, 'para-que-não [שֹׁמֵ֑עַ] ouviu não não');
INSERT INTO verses VALUES (17194, 20, 25, 11, '[תַּפּוּחֵ֣י] ouro [בְּמַשְׂכִּיּ֣וֹת] prata palavra palavra sobre');
INSERT INTO verses VALUES (17195, 20, 25, 12, '[נֶ֣זֶם] ouro [וַחֲלִי־כָ֑תֶם] [מוֹכִ֥יחַ] [חָ֝כָ֗ם] [עַל־אֹ֥זֶן] sobre');
INSERT INTO verses VALUES (17196, 20, 25, 13, 'כְּצִנַּת־ שֶׁ֨לֶג ׀ בְּי֬וֹם קָצִ֗יר צִ֣יר נֶ֭אֱמָן para-os-enviadores e-alma seu-senhores descanse:');
INSERT INTO verses VALUES (17197, 20, 25, 14, 'principais e-Espírito-de e-chuva a''ayin homem que-alegra-se com-auxílio-de mentira');
INSERT INTO verses VALUES (17198, 20, 25, 15, 'em-longo-tempo apêim se-alegrará que-floresçam e-lá-šōn rā-khā tīšabbār- גָּֽרֶם׃');
INSERT INTO verses VALUES (17199, 20, 25, 16, 'דְּבַ֣שׁ mā-tsāʾatā אכל dāyyekkā para-que-não tīšabbāʿēnu wa-haqētoʾ');
INSERT INTO verses VALUES (17200, 20, 25, 17, 'hōqar rā-gelekka de-casa-de re''ekha para-que-não yīšabbāʿekka e odiará');
INSERT INTO verses VALUES (17201, 20, 25, 18, 'que espalha e a espada e o arco queimado homem que vende ao seu vizinho até mentira');
INSERT INTO verses VALUES (17202, 20, 25, 19, 'na-mente que pastoreia e o pé agendada מִבְטָ֥ח בּ֝וֹגֵ֗ד em-dia-de צָרֽ͏ָה׃');
INSERT INTO verses VALUES (17203, 20, 25, 20, '[מַ֥עֲדֶה] [בֶּ֨גֶד] em-dia-de [בְּי֣וֹם] [קָ֭רָה] sobre [עַל־נָ֑תֶר] [וְשָׁ֥ר] [בַּ֝שִּׁרִ֗ים] sobre [לֶב־רָֽע׃] mau');
INSERT INTO verses VALUES (17204, 20, 25, 21, 'se fome- que-te-sodeia [לָ֑חֶם] pão e-se fome- que-o-beba águas');
INSERT INTO verses VALUES (17205, 20, 25, 22, 'que ganchos- tu cobiça- sobre sua-cabeça וֽ͏ַ֝יהוָ֗ה yešallêm- para-ti');
INSERT INTO verses VALUES (17206, 20, 25, 23, 'espírito norte- תְּח֣וֹלֵֽל גָּ֑שֶׁם וּפָנִ֥ים נִ֝זְעָמִ֗ים língua-de סָֽתֶר׃');
INSERT INTO verses VALUES (17207, 20, 25, 24, 'bom [שֶׁ֥בֶת] sobre [מֵאֵ֥שֶׁת] [*מדונים] [**מִ֝דְיָנִ֗ים] e-casa-de [חָֽבֶר]');
INSERT INTO verses VALUES (17208, 20, 25, 25, 'águas [קָ֭רִים] sobre alma [וּשְׁמוּעָ֥ה] [ט֝וֹבָ֗ה] [מֵאֶ֥רֶץ] de-terra-de');
INSERT INTO verses VALUES (17209, 20, 25, 26, '[מַעְיָ֣ן] [נִ֭רְפָּשׂ] [וּמָק֣וֹר] [מָשְׁחָ֑ת] [צַ֝דִּ֗יק] [מָ֣ט] diante-de');
INSERT INTO verses VALUES (17210, 20, 25, 27, 'comer [דְּבַ֣שׁ] [הַרְבּ֣וֹת] não bom [כְּבֹדָ֣ם] [כָּבֽוֹד]');
INSERT INTO verses VALUES (17211, 20, 25, 28, 'cidade [פְּ֭רוּצָה] não-há [חוֹמָ֑ה] homem que não [מַעְצָ֣ר] [לְרוּחֽוֹ]');
INSERT INTO chapters VALUES (654, 20, 26, 28);
INSERT INTO verses VALUES (17212, 20, 26, 1, '[כַּשֶּׁ֤לֶג] [׀] [בַּקַּ֗יִץ] [וְכַמָּטָ֥ר] assim não [לֹא־נָאוֶ֖ה] [לִכְסִ֣יל] [כָּבֽוֹד]');
INSERT INTO verses VALUES (17213, 20, 26, 2, 'כַּצִּפּ֣וֹר לָ֭נוּד כַּדְּר֣וֹר לָע֑וּף assim קִֽלְלַ֥ת hinam תָבֹֽא׃');
INSERT INTO verses VALUES (17214, 20, 26, 3, 'שׁ֣וֹט לַ֭סּוּס מֶ֣תֶג para o burro e a vara para o לֵו vaidosos:');
INSERT INTO verses VALUES (17215, 20, 26, 4, 'a responde כְּ֭סִיל como a alva para-que-não serás como para-ele também tu');
INSERT INTO verses VALUES (17216, 20, 26, 5, 'responde כסיל como a alva para-que-não será sabio em-seus-olhos');
INSERT INTO verses VALUES (17217, 20, 26, 6, 'que pega as pernas violência שֹׁתֶה enviou דְּבָרִ֣ים por-mão-de כְּסִֽיל׃');
INSERT INTO verses VALUES (17218, 20, 26, 7, '[דַּלְי֣וּ] [שֹׁ֭קַיִם] [מִפִּסֵּ֑חַ] [וּ֝מָשָׁ֗ל] [בְּפִ֣י] [כְסִילִֽים]');
INSERT INTO verses VALUES (17219, 20, 26, 8, '[כִּצְר֣וֹר] pedra [בְּמַרְגֵּמָ֑ה] [כֵּן־נוֹתֵ֖ן] [לִכְסִ֣יל] [כָּבֽוֹד]');
INSERT INTO verses VALUES (17220, 20, 26, 9, '[ח֭וֹחַ] subir [בְיַד־שִׁכּ֑וֹר] [וּ֝מָשָׁ֗ל] [בְּפִ֣י] [כְסִילִֽים]');
INSERT INTO verses VALUES (17221, 20, 26, 10, 'muito [מְחֽוֹלֵֽל־כֹּ֑ל] todo [כְּ֝סִ֗יל] [וְשֹׂכֵ֥ר] [עֹבְרִֽים]');
INSERT INTO verses VALUES (17222, 20, 26, 11, '[כְּ֭כֶלֶב] retornou sobre [כְּ֝סִ֗יל] [שׁוֹנֶ֥ה] [בְאִוַּלְתּֽוֹ]');
INSERT INTO verses VALUES (17223, 20, 26, 12, 'ראית homem sabio em-olhos-dele תוקוה para-o-insensato nós');
INSERT INTO verses VALUES (17224, 20, 26, 13, 'disse [עָ֭צֵל] [שַׁ֣חַל] [בַּדָּ֑רֶךְ] [אֲ֝רִ֗י] entre [הָרְחֹבֽוֹת]');
INSERT INTO verses VALUES (17225, 20, 26, 14, '[הַ֭דֶּלֶת] [תִּסּ֣וֹב] sobre [וְ֝עָצֵ֗ל] [עַל־מִטָּתֽוֹ] sobre');
INSERT INTO verses VALUES (17226, 20, 26, 15, '[טָ֘מַ֤ן] [עָצֵ֣ל] sua-mão [בַּצַּלָּ֑חַת] [נִ֝לְאָ֗ה] [לַֽהֲשִׁיבָ֥הּ] a');
INSERT INTO verses VALUES (17227, 20, 26, 16, 'sabio עָצֵ֣ל em-olhos-dele de-sede-מֵישֶׁבַע aquele-que-devolve-מְשֻׁבֵּי provas-וְתַעֲמֶה׃');
INSERT INTO verses VALUES (17228, 20, 26, 17, '[מַחֲזִ֥יק] [בְּאָזְנֵי־כָ֑לֶב] [עֹבֵ֥ר] passando [עַל־רִ֥יב] sobre não');
INSERT INTO verses VALUES (17229, 20, 26, 18, 'que se agite a que derrama aríquins setas e morte');
INSERT INTO verses VALUES (17230, 20, 26, 19, 'assim homem Rimá a companheiro-seu e disse הֲ‍ֽלֹא־ Mesequê eu');
INSERT INTO verses VALUES (17231, 20, 26, 20, 'em vão truncos תּכְּבֶה־ fogo וּבְאֵ֥ין נִרְגָּ֗ן יִשְׁתֹּ֥ק מָדֽוֹן׃');
INSERT INTO verses VALUES (17232, 20, 26, 21, '[פֶּחָ֣ם] [לְ֭גֶחָלִים] [וְעֵצִ֣ים] [לְאֵ֑שׁ] e-homem [*מדונים] [**מִ֝דְיָנִ֗ים]');
INSERT INTO verses VALUES (17233, 20, 26, 22, 'palavras-de nirgān como-estranhamente e-eles desceram חדרי- בָֽטֶן׃');
INSERT INTO verses VALUES (17234, 20, 26, 23, 'prata סִ֭יגִים מְצֻפֶּ֣ה sobre charesh שְׂפָתַ֖יִם דֹּלְקִ֣ים e-léb- mau');
INSERT INTO verses VALUES (17235, 20, 26, 24, 'יִנָּכֵ֣ר שׂוֹנֵ֑א וּ֝בְקִרְבּ֗וֹ יָשִׁ֥ית engano');
INSERT INTO verses VALUES (17236, 20, 26, 25, 'porque [ק֭וֹלוֹ] [אַל־תַּֽאֲמֶן־בּ֑וֹ] que [שֶׁ֖בַע] nele porque sete');
INSERT INTO verses VALUES (17237, 20, 26, 26, '[תִּכַּסֶּ֣ה] [שִׂ֭נְאָה] [בְּמַשָּׁא֑וֹן] [תִּגָּלֶ֖ה] [רָעָת֣וֹ] [בְקָהָֽל]');
INSERT INTO verses VALUES (17238, 20, 26, 27, '[כֹּֽרֶה־שַּׁ֭חַת] [בָּ֣הּ] [יִפֹּ֑ל] [וְגֹ֥לֵ֥ל] pedra a-ele para-ele');
INSERT INTO verses VALUES (17239, 20, 26, 28, '[לְֽשׁוֹן־שֶׁ֭קֶר] [יִשְׂנָ֣א] [דַכָּ֑יו] [וּפֶ֥ה] [חָ֝לָ֗ק] [יַעֲשֶׂ֥ה] ele-fará');
INSERT INTO chapters VALUES (655, 20, 27, 27);
INSERT INTO verses VALUES (17240, 20, 27, 1, 'a [בְּי֣וֹם] no-dia que porque não dia dia');
INSERT INTO verses VALUES (17241, 20, 27, 2, '[יְהַלֶּלְךָ֣] [זָ֣ר] e-não [נָ֝כְרִ֗י] [וְאַל־שְׂפָתֶֽיךָ] e-a');
INSERT INTO verses VALUES (17242, 20, 27, 3, 'כּוֹבֶד־ אֶבֶן וְנֶתֶל הַחוֹל וְכָעֵס ê-vil כָּבוֹד de suas');
INSERT INTO verses VALUES (17243, 20, 27, 4, 'acerridade ira e chuva tambem e-quem se levante diante-de קינאה׃');
INSERT INTO verses VALUES (17244, 20, 27, 5, 'boa repreensao manifestada de amor oculta');
INSERT INTO verses VALUES (17245, 20, 27, 6, 'fieis feridas אֹהֵב וְנַעְתָּר֗וֹת נְשִׁיק֥וֹת שׂוֹנֵֽא׃');
INSERT INTO verses VALUES (17246, 20, 27, 7, 'alma [שְׂ֭בֵעָה] [תָּב֣וּס] [נֹ֑פֶת] [וְנֶ֥פֶשׁ] [רְ֝עֵבָ֗ה] todo [מָתֽוֹק]');
INSERT INTO verses VALUES (17247, 20, 27, 8, '[כְּ֭צִפּוֹר] [נוֹדֶ֣דֶת] de [כֵּֽן־אִ֝֗ישׁ] assim homem');
INSERT INTO verses VALUES (17248, 20, 27, 9, 'óleo [וּ֭קְטֹרֶת] [יְשַׂמַּֽח־לֵ֑ב] coração [רֵ֝עֵ֗הוּ] [מֵֽעֲצַת־נָֽפֶשׁ] alma');
INSERT INTO verses VALUES (17249, 20, 27, 10, 'רֵ֥עֲךָ֨ אָבִ֡יךָ a תַּעֲזֹ֗ב e-casa-de seu-irmão a vai-vir em-dia-de sua-casa bom morador próximo de-irmão distante');
INSERT INTO verses VALUES (17250, 20, 27, 11, 'sábio filhos-de e-alegre meu-coração e-retornarei [חֹרְפִ֣י] palavra');
INSERT INTO verses VALUES (17251, 20, 27, 12, 'astuto ver mal [נִסְתָּ֑ר] [פְּ֝תָאיִ֗ם] [עָבְר֥וּ] [נֶעֱנָֽשׁוּ]');
INSERT INTO verses VALUES (17252, 20, 27, 13, 'toma [כִּי־עָ֣רַב] porque tarde [נָכְרִיָּ֣ה] [חַבְלֵֽהוּ]');
INSERT INTO verses VALUES (17253, 20, 27, 14, '[מְבָ֘רֵ֤ךְ] [רֵעֵ֨הוּ] com-voz grande ba-voker [בַּבֹּ֣קֶר] [הַשְׁכֵּ֑ים] [קְ֝לָלָ֗ה] a-ele');
INSERT INTO verses VALUES (17254, 20, 27, 15, '[דֶּ֣לֶף] em-dia-de [בְּי֣וֹם] [סַגְרִ֑יר] [וְאֵ֥שֶׁת]');
INSERT INTO verses VALUES (17255, 20, 27, 16, '[צֹפְנֶ֥יהָ] [צָֽפַן־ר֑וּחַ] espírito e-óleo chamaria chamaria');
INSERT INTO verses VALUES (17256, 20, 27, 17, '[בַּרְזֶ֣ל] [בְּבַרְזֶ֣ל] juntamente [וְ֝אִ֗ישׁ] יַ֣חַד face-de- seu-amigo');
INSERT INTO verses VALUES (17257, 20, 27, 18, 'guardião [תְּ֭אֵנָה] comer-á פִּרְיָ֑הּ וְשֹׁמֵ֖ר seu-senhores [יְכֻבָּֽד]');
INSERT INTO verses VALUES (17258, 20, 27, 19, '[כַּ֭מַּיִם] [הַפָּנִ֣ים] [לַפָּנִ֑ים] assim [לֵֽב־הָ֝אָדָ֗ם] o-homem');
INSERT INTO verses VALUES (17259, 20, 27, 20, 'sho''al não [**וַ֭אֲבַדּוֹ] não o-homem não o-homem');
INSERT INTO verses VALUES (17260, 20, 27, 21, 'forrador em-prata e-esculpidor em-ouro [וְ֝אִ֗ישׁ] de-conformidade-com [מַהֲלָלֽוֹ]');
INSERT INTO verses VALUES (17261, 20, 27, 22, 'mãe [תִּכְתּֽוֹשׁ־אֶת־הָאֱוִ֨יל] a [בַּֽמַּכְתֵּ֡שׁ] no-meio-de em-meio-de [בַּֽעֱלִ֑י] [לֹא־תָס֥וּר] não vire-se [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (17262, 20, 27, 23, 'conheceu [תֵּ֭דַע] face-de [צֹאנֶ֑ךָ] [שִׁ֥ית] [לִ֝בְּךָ֗] [לַעֲדָרִֽים]');
INSERT INTO verses VALUES (17263, 20, 27, 24, 'que não para-sempre [חֹ֑סֶן] e-se [לְד֣וֹר] [*דור]');
INSERT INTO verses VALUES (17264, 20, 27, 25, '[גָּלָ֣ה] [חָ֭צִיר] [וְנִרְאָה־דֶ֑שֶׁא] [וְ֝נֶאֶסְפ֗וּ] [עִשְּׂב֥וֹת] [הָרִֽים]');
