INSERT INTO verses VALUES (17276, 20, 28, 10, '[מַשְׁגֶּ֤ה] justos em-a-caminho mau mal ele [הֽוּא־יִפּ֑וֹל] [וּ֝תְמִימִ֗ים] [יִנְחֲלוּ־טֽוֹב] bom');
