INSERT INTO verses VALUES (17343, 20, 30, 22, 'debaixo-de que porque [וְ֝נָבָ֗ל] que porque');
INSERT INTO verses VALUES (17344, 20, 30, 23, 'debaixo [שְׂ֭נוּאָה] que [תִבָּעֵ֑ל] [וְ֝שִׁפְחָ֗ה] porque [גְּבִרְתָּֽהּ׃]');
INSERT INTO verses VALUES (17345, 20, 30, 24, 'quatro eles [קְטַנֵּי־אָ֑רֶץ] terra [חֲכָמִ֥ים] [מְחֻכָּמִֽים]');
INSERT INTO verses VALUES (17346, 20, 30, 25, '[הַ֭נְּמָלִים] povo não força [בַקַּ֣יִץ] [לַחְמָֽם] pão');
INSERT INTO verses VALUES (17347, 20, 30, 26, '[שְׁ֭פַנִּים] povo não [וַיָּשִׂ֖ימוּ] e-foram-colocados [בֵּיתָֽם] [sem-traducao]');
INSERT INTO verses VALUES (17348, 20, 30, 27, 'rei não-há [לָאַרְבֶּ֑ה] e-ele-saiu [חֹצֵ֣ץ] [כֻּלּֽוֹ]');
INSERT INTO verses VALUES (17349, 20, 30, 28, '[שְׂ֭מָמִית] [בְּיָדַ֣יִם] [תְּתַפֵּ֑שׂ] [וְ֝הִ֗יא] em seus palácios rei');
INSERT INTO verses VALUES (17350, 20, 30, 29, 'três הֵ֭מָּה [מֵיטִ֣יבֵי] [צָ֑עַד] [וְ֝אַרְבָּעָ֗ה] [מֵיטִ֥בֵי] para');
INSERT INTO verses VALUES (17351, 20, 30, 30, '[לַ֭יִשׁ] homem em-animais e-não yashuv que todo');
INSERT INTO verses VALUES (17352, 20, 30, 31, '[זַרְזִ֣יר] [מָתְנַ֣יִם] ou [וּ֝מֶ֗לֶךְ] [אַלְק֥וּם] [עִמּֽוֹ]');
INSERT INTO verses VALUES (17353, 20, 30, 32, 'se [בְהִתְנַשֵּׂ֑א] [וְאִם־זַ֝מּ֗וֹתָ] mão [לְפֶֽה] mão');
INSERT INTO verses VALUES (17354, 20, 30, 33, 'que [מִ֪יץ] [חָלָ֡ב] [י֘וֹצִ֤יא] [חֶמְאָ֗ה] [וּֽמִיץ־אַ֭ף] [י֣וֹצִיא] [דָ֑ם] [וּמִ֥יץ] [אַ֝פַּ֗יִם] [י֣וֹצִיא] [רִֽיב׃]');
INSERT INTO chapters VALUES (659, 20, 31, 31);
INSERT INTO verses VALUES (17355, 20, 31, 1, '[דִּ֭בְרֵי] [לְמוּאֵ֣ל] rei [מַ֝שָּׂ֗א] que sua-mãe');
INSERT INTO verses VALUES (17356, 20, 31, 2, 'que meu-amigo umah- [בַּר־נְדָרָֽי] [sem-traducao] [sem-traducao] [sem-traducao] nossos-votos');
INSERT INTO verses VALUES (17357, 20, 31, 3, 'a darás [חֵילֶ֑ךָ] a-riqueza-teu [לַֽמְח֥וֹת] [מְלָכִֽין] [sem-traducao]');
INSERT INTO verses VALUES (17358, 20, 31, 4, 'El [לַֽמְלָכִ֨ים] [׀] El [אַ֣ל] [לַֽמְלָכִ֣ים] vinho [וּ֝לְרוֹזְנִ֗ים] e se cobriram;');
INSERT INTO verses VALUES (17359, 20, 31, 5, 'para-que-não [וְיִשְׁכַּ֣ח] [מְחֻקָּ֑ק] [וִֽ֝ישַׁנֶּה] [דִּ֣ין] [כָּל־בְּנֵי־עֹֽנִי] todo');
INSERT INTO verses VALUES (17360, 20, 31, 6, 'dai- [לְאוֹבֵ֑ד] [וְ֝יַיִן] [לְמָ֣רֵי] [נָֽפֶשׁ] alma');
INSERT INTO verses VALUES (17361, 20, 31, 7, '[יִ֭שְׁתֶּה] [וְיִשְׁכַּ֣ח] [רִישׁ֑וֹ] [וַ֝עֲמָל֗וֹ] não [יִזְכָּר־עֽוֹד]');
INSERT INTO verses VALUES (17362, 20, 31, 8, '[פְּתַח־פִּ֥יךָ] a-tua-boca [אֶל־דִּ֝֗ין] a [חֲלֽוֹף] todo filhos-de [sem-traducao]');
INSERT INTO verses VALUES (17363, 20, 31, 9, '[פְּתַח־פִּ֥יךָ] [שְׁפָט־צֶ֑דֶק] [וְ֝דִ֗ין] [עָנִ֥י] [וְאֶבְיֽוֹן׃]');
INSERT INTO verses VALUES (17364, 20, 31, 10, 'esposa-de quem quem encontrará [מִפְּנִינִ֣ים] [מִכְרָֽהּ] [sem-traducao]');
INSERT INTO verses VALUES (17365, 20, 31, 11, '[בָּ֣טַח] [בָּ֭הּ] coração [בַּעְלָ֑הּ] [וְ֝שָׁלָ֗ל] não [יֶחְסָֽר]');
INSERT INTO verses VALUES (17366, 20, 31, 12, '[גְּמָלַ֣תְהוּ] bom e-não mau dias-de dias-de');
INSERT INTO verses VALUES (17367, 20, 31, 13, '[דָּ֭רְשָׁה] [צֶ֣מֶר] [וּפִשְׁתִּ֑ים] [וַ֝תַּ֗עַשׂ] [בְּחֵ֣פֶץ] [כַּפֶּֽיהָ]');
INSERT INTO verses VALUES (17368, 20, 31, 14, 'era [כָּאֳנִיּ֣וֹת] [סוֹחֵ֑ר] [מִ֝מֶּרְחָ֗ק] trarás [לַחְמָֽהּ]');
INSERT INTO verses VALUES (17369, 20, 31, 15, '[וַתָּ֤קָם] [׀] noite [לַ֗יְלָה] e-deu [טֶ֣רֶף] [לְבֵיתָ֑הּ] [וְ֝חֹ֗ק]');
INSERT INTO verses VALUES (17370, 20, 31, 16, '[זָמְמָ֣ה] [שָׂ֭דֶה] [וַתִּקָּחֵ֑הוּ] do-fruto-de [כַ֝פֶּ֗יהָ] vinhedo');
INSERT INTO verses VALUES (17371, 20, 31, 17, '[חָֽגְרָ֣ה] [בְע֣וֹז] [מָתְנֶ֑יהָ] [וַ֝תְּאַמֵּ֗ץ] [זְרֹעוֹתֶֽיהָ]');
INSERT INTO verses VALUES (17372, 20, 31, 18, '[טָ֭עֲמָה] porque bom [לֹֽא־יִכְבֶּ֖ה] não [**בַלַּ֣יְלָה] [נֵרָֽהּ]');
INSERT INTO verses VALUES (17373, 20, 31, 19, '[יָ֭דֶיהָ] [שִׁלְּחָ֣ה] [בַכִּישׁ֑וֹר] [וְ֝כַפֶּ֗יהָ] [תָּ֣מְכוּ] [פָֽלֶךְ]');
INSERT INTO verses VALUES (17374, 20, 31, 20, '[כַּ֭פָּהּ] [פָּרְשָׂ֣ה] [לֶעָנִ֑י] [וְ֝יָדֶ֗יהָ] [שִׁלְּחָ֥ה] [לָֽאֶבְיֽוֹן]');
INSERT INTO verses VALUES (17375, 20, 31, 21, 'não [לְבֵיתָ֣הּ] [מִשָּׁ֑לֶג] que porque todo [שָׁנִֽים] dois');
INSERT INTO verses VALUES (17376, 20, 31, 22, '[מַרְבַדִּ֥ים] [עָֽשְׂתָה־לָּ֑הּ] a-ela seis [לְבוּשָֽׁהּ]');
INSERT INTO verses VALUES (17377, 20, 31, 23, 'conhecido nas praças [בַּעְלָ֑הּ] [בְּ֝שִׁבְתּ֗וֹ] com os anciãos- terra');
INSERT INTO verses VALUES (17378, 20, 31, 24, '[סָדִ֣ין] [עָ֭שְׂתָה] [וַתִּמְכֹּ֑ר] [וַ֝חֲג֗וֹר] deu [לַֽכְּנַעֲנִֽי]');
INSERT INTO verses VALUES (17379, 20, 31, 25, '[עֹז־וְהָדָ֥ר] [לְבוּשָׁ֑הּ] [וַ֝תִּשְׂחַ֗ק] [לְי֣וֹם] para-o-dia');
INSERT INTO verses VALUES (17380, 20, 31, 26, '[פִּ֭יהָ] [פָּתְחָ֣ה] [בְחָכְמָ֑ה] [וְתֽ[m]וֹרַת] sobre [עַל־לְשׁוֹנָֽהּ]');
INSERT INTO verses VALUES (17381, 20, 31, 27, '[צ֭וֹפִיָּה] [הֲלִיכ֣וֹת] [בֵּיתָ֑הּ] e-pão [עַ֝צְל֗וּת] não você-comerá');
INSERT INTO verses VALUES (17382, 20, 31, 28, 'levantaram-se [בָ֭נֶיהָ] [וַֽיְאַשְּׁר֑וּהָ] [בַּ֝עְלָ֗הּ] [וַֽיְהַֽלְלָהּ]');
INSERT INTO verses VALUES (17383, 20, 31, 29, '[רַבּ֣וֹת] [בָּ֭נוֹת] [עָ֣שׂוּ] força e-[OBJ] [עָלִ֥ית] sobre');
INSERT INTO verses VALUES (17384, 20, 31, 30, 'MENTIRA [הַ֭חֵן] [וְהֶ֣בֶל] [הַיֹּ֑פִי] mulher [יִרְאַת־יְ֝הוָ֗ה] yhwh ela [sem-traducao]');
INSERT INTO verses VALUES (17385, 20, 31, 31, 'dai- do-fruto-de [יָדֶ֑יהָ] [וִֽיהַלְל֖וּהָ] [בַשְּׁעָרִ֣ים] [מַעֲשֶֽׂיהָ] [sem-traducao]');
INSERT INTO books VALUES (21, 'ECC', 'Eclesiastes', 'AT', 12);
INSERT INTO chapters VALUES (660, 21, 1, 18);
INSERT INTO verses VALUES (17386, 21, 1, 1, 'palavras-de [קֹהֶ֣לֶת] filho-de Davi rei');
INSERT INTO verses VALUES (17387, 21, 1, 2, 'הֲבֵ֤ל הֲבֵ֤ל disse קוהלת הֲבֵ֤ל הֲבֵ֤ל todo o que הֲבֵ֤ל');
INSERT INTO verses VALUES (17388, 21, 1, 3, 'que- [לָֽאָדָ֑ם] [בְּכָל־עֲמָל֔וֹ] em-todo debaixo [הַשָּֽׁמֶשׁ] o-sol');
INSERT INTO verses VALUES (17389, 21, 1, 4, '[דּ֤וֹר] andou [וְד֣וֹר] veio E-a-terra para-sempre [עֹמָֽדֶת]');
INSERT INTO verses VALUES (17390, 21, 1, 5, 'וזרח o-sol ובא o-sol e-a מקומו שואף ele ele nome');
INSERT INTO verses VALUES (17391, 21, 1, 6, 'הלך a דרום וְסוֹבֵ֖ב a norte סָבֵ֤ב סובב andando o espírito e-sobre סְבִיבֹתָ֖יו retornou הָרֽוּחַ׃');
INSERT INTO verses VALUES (17392, 21, 1, 7, 'todo [הֹלְכִ֣ים] [אֶל־הַיָּ֔ם] a o-mar [מָלֵ֑א] [אֶל־מְק֗וֹם] enchei a [שָׁ֛ם] eles ides nome');
INSERT INTO verses VALUES (17393, 21, 1, 8, 'todo as-palavras יְגֵעִ֔ים não י-וכ-ל homem olho para-ver תִשְׂבַּ֥ע olho para ver e-não será cheia ore de ouvir:');
INSERT INTO verses VALUES (17394, 21, 1, 9, 'que- ele ele que seja ele שֶׁנּוֹעַשׂ ele que seja feito debaixo todo novo debaixo-de o-sol');
INSERT INTO verses VALUES (17395, 21, 1, 10, 'há palavra que seja dito olha, eis que este ele ele ser foi para os tempos ser foi ante nós:');
INSERT INTO verses VALUES (17396, 21, 1, 11, 'não recordação para-os-primeiros e-tambem para-os-últimos que-sejam não a-eles para-eles memória povo que-sejam para-os-últimos');
INSERT INTO verses VALUES (17397, 21, 1, 12, 'eu Qohelet era rei sobre Israel em-Jerusalém');
INSERT INTO verses VALUES (17398, 21, 1, 13, 'e-darei a meu-coração para-investigar e-para-percorrer sobre sobre todo debaixo será-feita ele os-céus ele mal dar deu Elohim o-homem o-homem para-responder em-ele');
INSERT INTO verses VALUES (17399, 21, 1, 14, 'vi a todo debaixo שֶֽׁנַּעֲשׂ֖וּ em-lugar-de o-sol e-eis o todo espírito espírito espírito');
INSERT INTO verses VALUES (17400, 21, 1, 15, '[מְעֻוָּ֖ת] não [לִתְקֹ֑ן] [וְחֶסְר֖וֹן] [לֹא־יוּכַ֥ל] não');
INSERT INTO verses VALUES (17401, 21, 1, 16, '[דִּבַּ֨רְתִּי] eu com dizendo para-dizer eis eis [וְהוֹסַ֙פְתִּי֙] [חָכְמָ֔ה] sobre sobre todo que foi ver sobre Jerusalém [וָדָֽעַת] viu');
INSERT INTO verses VALUES (17402, 21, 1, 17, 'e deu-lhe coração-meu para-conhecer sabedoria e conhecimento e alegria e temor eu-sei também ele ele espírito espírito');
INSERT INTO verses VALUES (17403, 21, 1, 18, 'que em abundância sabedoria רב- e ira conhecimento conhecimento יוֹסִ֥יף do fardo pesado;');
INSERT INTO chapters VALUES (661, 21, 2, 26);
INSERT INTO verses VALUES (17404, 21, 2, 1, 'Eu disse eu no meu coração לְכָה־ נָא אֲנַשֵׁךְ com-alegria e-vê em boa parte e-eis também ele הבל׃');
INSERT INTO verses VALUES (17405, 21, 2, 2, 'para rir eu-disse de gozo e para alegria que- isto fez');
INSERT INTO verses VALUES (17406, 21, 2, 3, 'eu guardarei no meu coração para-dragar no-óleo a em-meu-corpo e meu coração agindo com-sabedoria e-pegando até até que bom qual o-homem bom para-filhos-de debaixo que façam dias-de os-céus número dias-de suas-vidas');
INSERT INTO verses VALUES (17407, 21, 2, 4, 'eu-cresci minha-ação eu-construí a-mim בָּתִּ֔ים eu-plantei para-mim vinhedos');
INSERT INTO verses VALUES (17408, 21, 2, 5, 'faça-eu para-mim jardins e-paradises e-plantei neles árvore todo frutos');
INSERT INTO verses VALUES (17409, 21, 2, 6, 'fiz para-mim lagos águas para-águas de-eles floresta צומח árvores:');
INSERT INTO verses VALUES (17410, 21, 2, 7, 'comprei avádim e-vasilhas: e-filhos-de ser foi também também gados: manhã e-ovelhas: ser foi de-toda de-todo foram: diante-de-mim em-Jerusalém');
INSERT INTO verses VALUES (17411, 21, 2, 8, 'eu-acumulei: a-mim também prata e-ouro e-riquezas: me-lachim e-as-cidades: faizest-vos para-mim שָׂרִים e-ovos: [בְּנֵ֥י] o-homem o-homem שִׁדָּ֥ה וְשִׁדּֽוֹת׃');
INSERT INTO verses VALUES (17412, 21, 2, 9, '[וְגָדַ֣לְתִּי] [וְהוֹסַ֔פְתִּי] de-toda [שֶׁהָיָ֥ה] diante-de-mim em-Jerusalém certamente [חָכְמָתִ֖י] [עָ֥מְדָה] a-mim');
INSERT INTO verses VALUES (17413, 21, 2, 10, 'e-tudo que [שָֽׁאֲל֣וּ] [עֵינַ֔י] não [אָצַ֖לְתִּי] deles não [אֶת־לִבִּ֜י] a [כִּֽי־לִבִּ֤י] de-todo [מִכָּל־עֲמָלִ֔י] porque [חֶלְקִ֖י] [מִכָּל־עֲמָלִֽי] de-todo foi de-todo');
INSERT INTO verses VALUES (17414, 21, 2, 11, 'וּפָנִיתִי eu em-todo מַעֲשַׂי שֶׁעָשׂוּ יָדַי e-no trabalho eu trabalhei laasot e-eis todo o que הֶ֙בֶל֙ espírito espírito e-não-há debaixo debaixo-de o-sol');
INSERT INTO verses VALUES (17415, 21, 2, 12, 'e-olhei eu para-ver sabedoria e-ho-lemós e-inteligência que que o-homem o-homem depois-de o-rei a que já fiz-o');
INSERT INTO verses VALUES (17416, 21, 2, 13, 'e-vi eu há excesso para a sabedoria de a inteligência a-luz a-luz de a-escuridão');
INSERT INTO verses VALUES (17417, 21, 2, 14, 'o sábio os olhos com-no-cabeça-seu e o tolo na-escuridão que vai e eu saberia também eu um um será chamado a todos:');
INSERT INTO verses VALUES (17418, 21, 2, 15, 'e eu diria eu no meu coração como se chama הַכְּסִיל֙ também eu אינני וְלָ֧מָּה חָכַ֛מְתִּי eu então יוֹתֵ֑ר וְדִבַּ֣רְתִּי בְלִבִּ֔י שֶׁגַּם־ este הָֽבֶל׃');
INSERT INTO verses VALUES (17419, 21, 2, 16, 'que nao-ha זִכְר֧וֹן לֶחָכָ֛ם com הַכְּסִ֖יל para-sempre בְּשֶׁכְּבָ֞ר os-dias os-que-vêm o-todo foi-esquecido e-como morrerá o-sábio com o-estúpido');
INSERT INTO verses VALUES (17420, 21, 2, 17, 'e-repugnei-o a que porque mau sobre-mim a-obra debaixo em-lugar-de o-sol porque todo o que espírito espírito espírito');
INSERT INTO verses VALUES (17421, 21, 2, 18, 'e-repugnei-o eu a todo trabalhador debaixo trabalho em-lugar-de o-sol eu-lhe-deixei para-o-homem será depois-de-mim');
INSERT INTO verses VALUES (17422, 21, 2, 19, 'e-quem sabedor o sábio será ou o prudente e governará em-todo trabalhador שֶׁעָמַ֥לְתִּי debaixo em-lugar-de o-sol também este vãos:');
INSERT INTO verses VALUES (17423, 21, 2, 20, 'e girar-me-ei eu para amar a sobre sobre todo debaixo eu trabalhei debaixo-de o-sol');
INSERT INTO verses VALUES (17424, 21, 2, 21, 'porque homem homem seu trabalho com sabedoria e com conhecimento E-ao-homem e para o homem não haverá עָמַל־ em-ele ser-lhe-á sua parte também este הֶ֖בֶל e a maldição multiplicai');
INSERT INTO verses VALUES (17425, 21, 2, 22, 'que de-o- será para o homem em-todo o seu trabalho e na fertilidade no seu coração debaixo trabalho debaixo-de o-sol');
INSERT INTO verses VALUES (17426, 21, 2, 23, 'que todo seus-dias dor e ira seu assunto também na noite não dormiu ele também este הֶבֶל ela');
INSERT INTO verses VALUES (17427, 21, 2, 24, 'não há bom no homem e comeu e beberá e verá bom nafsho bom no seu trabalho também que vi eu porque de-mão-de Elohim ela');
INSERT INTO verses VALUES (17428, 21, 2, 25, 'que quem comerá e-quem de coragem fora de-mim');
INSERT INTO verses VALUES (17429, 21, 2, 26, 'que para o homem bom diante-dele dar sabedoria וּדְעָת e alegria e o pecador dar עִנְיָן para arrecadar e para entrar para dar para o bem diante-de הָֽאֱלֹהִ֔ים também este הֶ֖בֶל espírito espírito');
INSERT INTO chapters VALUES (662, 21, 3, 22);
INSERT INTO verses VALUES (17430, 21, 3, 1, 'para-todo tempo e tempo para-todo debaixo debaixo-de os-céus');
INSERT INTO verses VALUES (17431, 21, 3, 2, 'tempo para dar à luz e tempo para morrer tempo para errar e tempo para arrancar plantemos.');
INSERT INTO verses VALUES (17432, 21, 3, 3, 'tempo para destruir e tempo para curar tempo para estourar e tempo para-construir');
INSERT INTO verses VALUES (17433, 21, 3, 4, 'tempo para chorar e-út para rir tempo lamento e tempo dançar;');
INSERT INTO verses VALUES (17434, 21, 3, 5, 'hora lançar pedras e hora reunir pedras tempo abraçar e tempo para longe de abraço');
INSERT INTO verses VALUES (17435, 21, 3, 6, 'tempo procurar e hora destruir tempo para guardar e tempo para lançar:');
INSERT INTO verses VALUES (17436, 21, 3, 7, 'tempo para arrancar e-út para perfurar tempo para sussurrar e tempo para falar:');
INSERT INTO verses VALUES (17437, 21, 3, 8, 'tempo para amar e-út para odiar tempo guerra וְעֵ֥ת paz');
INSERT INTO verses VALUES (17438, 21, 3, 9, 'que- [הָֽעוֹשֶׂ֔ה] [בַּאֲשֶׁ֖ר] ele ele');
INSERT INTO verses VALUES (17439, 21, 3, 10, 'vi a [אֲשֶׁ֨ר] dar deu Elohim o-homem o-homem [בּֽוֹ] em-ele');
INSERT INTO verses VALUES (17440, 21, 3, 11, 'a todo o que fez יָפֶ֣ה também também dar הָעֹלָם֙ deu בְּלִבָּ֔ם מִבְּלִ֞י o-homem não יִמְצָ֣א o-homem a o feito que fez Elohim do início e-até fim:');
INSERT INTO verses VALUES (17441, 21, 3, 12, 'eu-sei que não bom neles que se [וְלַעֲשׂ֥וֹת] bom bom');
INSERT INTO verses VALUES (17442, 21, 3, 13, 'e-também todo o-homem que comam e bebam bom bom em-todo trabalho-dele presente Elohim ela');
INSERT INTO verses VALUES (17443, 21, 3, 14, 'יָדַ֗עְתִּי que todo que fará ele será será para-sempre sobre-ele não-há para adicionar e de-lui não-há para retirar e os Elohim fez שֶׁיִּֽרְא֖וּ מִלְּפָנָֽיו׃');
INSERT INTO verses VALUES (17444, 21, 3, 15, 'que- [כְּבָ֣ר] ele ele e-que [כְּבָ֣ר] ser foi [יְבַקֵּ֥שׁ] [אֶת־נִרְדָּֽף] a');
INSERT INTO verses VALUES (17445, 21, 3, 16, 'וְע֥וֹד vi debaixo o-sol lugar-de o-julgamento ali o rebelde וּמְק֥וֹם הַצֶּ֖דֶק שָׁ֥מָּה הָרָֽשַׁע׃');
INSERT INTO verses VALUES (17446, 21, 3, 17, 'אָמַ֤רְתִּֽי eu no-me a o-santo e-a o-perverso julgue o-Elohim porque tempo para-todo yhwh e-sobre todo o feito nome');
INSERT INTO verses VALUES (17447, 21, 3, 18, 'Eu disse eu no-me sobre דְּבַר o-homem o-homem para-os-mesmos o-Elohim e-para-ver que-eles a-eles eles para-eles');
INSERT INTO verses VALUES (17448, 21, 3, 19, 'que reunião filhos-de o-homem os-animais o-gado um a-eles a-eles como este morrendo morte-de e-Espírito-de um um para-todo o-homem o-homem de que ain porque o-ouro הבל׃');
INSERT INTO verses VALUES (17449, 21, 3, 20, 'todo o que הלוך a um um ser foi de a poeira e todo o retornou a a poeira:');
INSERT INTO verses VALUES (17450, 21, 3, 21, 'quem sabe espírito filhos-de o-homem o subido ela para cima e-Espírito-de os-animais a descido ela para baixo para-a-terra');
INSERT INTO verses VALUES (17451, 21, 3, 22, 'e vi que não bom porque se alegrará o-homem em seus trabalhos porque ele que quem quem para-ver para ver em que será atrás-dele');
INSERT INTO chapters VALUES (663, 21, 4, 17);
INSERT INTO verses VALUES (17452, 21, 4, 1, 'e voltarei eu eu vi a todo as ásperas debaixo seremos feitos em-lugar-de o-sol וְהִנֵּ֣ה ׀ lágrimas as tribulações a-eles para-eles consolação e imediatamente suas tribulações força a-eles a-eles מנחם:');
INSERT INTO verses VALUES (17453, 21, 4, 2, '[וְשַׁבֵּ֧חַ] eu a os-mortos [מֵ֑תוּ] [מִן־הַ֣חַיִּ֔ים] de [הֵ֥מָּה] vida eles');
INSERT INTO verses VALUES (17454, 21, 4, 3, '[וְטוֹב֙] [מִשְּׁנֵיהֶ֔ם] a que não ser foi que não viu a [נַעֲשָׂ֖ה] debaixo que o-sol');
INSERT INTO verses VALUES (17455, 21, 4, 4, 'וְרָאִ֨יתִי eu a tudo-de עָמָ֗ל e-את que כִּישׁוֹן a-obra porque ela קִנְאַת־ homem espírito também este הֶ֖בֶל espírito espírito');
INSERT INTO verses VALUES (17456, 21, 4, 5, '[הַכְּסִיל֙] [חֹבֵ֣ק] a [וְאֹכֵ֖ל] [אֶת־בְּשָׂרֽוֹ] a');
INSERT INTO verses VALUES (17457, 21, 4, 6, 'bom enchei [כַ֖ף] [נָ֑חַת] [מִמְּלֹ֥א] [חָפְנַ֛יִם] [עָמָ֖ל] [וּרְע֥וּת] espírito');
INSERT INTO verses VALUES (17458, 21, 4, 7, '[וְשַׁ֧בְתִּי] eu [וָאֶרְאֶ֥ה] הֶ֖בֶל debaixo o-sol');
INSERT INTO verses VALUES (17459, 21, 4, 8, 'há um [וְאֵ֨ין] segundo também filho [וָאָ֣ח] não há para-ele e-não-há [לְכָל־עֲמָל֔וֹ] para-todo [**עֵינ֖וֹ] também não [וּלְמִ֣י] dez [אֲנִ֣י] eu [וּמְחַסֵּ֤ר] [אֶת־נַפְשִׁי֙] a [גַּם־זֶ֥[t]ה] [הֶ֛בֶל] também mal ele mau ela');
INSERT INTO verses VALUES (17460, 21, 4, 9, 'טוֹבים הַשָּׁנַ֖יִם de o-echad que ha bom שָׂכָ֥ר bom בַּעֲמָלָֽם׃');
INSERT INTO verses VALUES (17461, 21, 4, 10, 'que se o-primeiro [יָקִ֣ים] [אֶת־חֲבֵר֑וֹ] a o-primeiro [שֶׁיִפּ֔וֹל] [וְאֵ֥ין] [שֵׁנִ֖י] e-não-há segundo');
INSERT INTO verses VALUES (17462, 21, 4, 11, 'também se יִשְׁכְּב֥וּ dois a-eles para-eles e-um como que-se-aqueça:');
INSERT INTO verses VALUES (17463, 21, 4, 12, 'וְאִֽם־ o-primeiro הָאֶחָ֔ד as-duas se-manterão diante-dele e-o-fio não não com-velocidade será-se-rompido:');
INSERT INTO verses VALUES (17464, 21, 4, 13, 'bom filho misken ve-chakham min-melekh zaken u-kosil que não conheceu le-hizaher ainda');
INSERT INTO verses VALUES (17465, 21, 4, 14, 'porque de-casa-de sair saiu que também também b-malkuto nolad raš');
INSERT INTO verses VALUES (17466, 21, 4, 15, 'vi a todo debaixo ham-melekhim em-lugar-de o-sol povo o-ninho o-segundo que יַעֲמֹ֖ד em-lugar-dele');
INSERT INTO verses VALUES (17467, 21, 4, 16, 'não há [לְכָל־הָעָ֗ם] a-todo o povo para-todo também foi não também [כִּֽי־גַם־זֶ֥ה] não [וְרַעְי֥וֹן] espírito porque também este הֶ֖בֶל espírito');
INSERT INTO verses VALUES (17468, 21, 4, 17, '[שְׁמֹ֣ר] como-que [**רַגְלְךָ֗] a casa os-Elohim [הָאֱלֹהִ֔ים] [וְקָר֣וֹב] [לִשְׁמֹ֔עַ] [מִתֵּ֥ת] [הַכְּסִילִ֖ים] porque [כִּֽי־אֵינָ֥ם] [יוֹדְעִ֖ים] para-fazer mal');
INSERT INTO chapters VALUES (664, 21, 5, 19);
INSERT INTO verses VALUES (17469, 21, 5, 1, 'a [עַל־פִּ֜יךָ] sobre [אַל־יְמַהֵ֛ר] [לְהוֹצִ֥יא] a [לִפְנֵ֣י] [הָאֱלֹהִ֑ים] que diante-de o-Elohim porque [עַל־הָאָ֔רֶץ] [עַֽ[t]ל־כֵּ֛ן] e-tu sobre a-terra');
INSERT INTO verses VALUES (17470, 21, 5, 2, 'que veio [הַחֲל֖וֹם] em-multidão [עִנְיָ֑ן] [וְק֥וֹל] [כְּסִ֖יל] [בְּרֹ֥ב] [דְּבָרִֽים]');
INSERT INTO verses VALUES (17471, 21, 5, 3, 'como-que [תִּדֹּ֨ר] voto [לֽ͏ֵאלֹהִ֗ים] a [לְשַׁלְּמ֔וֹ] que porque não [בַּכְּסִילִ֑ים] [OBJ] a que');
INSERT INTO verses VALUES (17472, 21, 5, 4, 'bom que não [מִשֶׁתִּדּ֖וֹר] [וְלֹ֥א] e-não');
INSERT INTO verses VALUES (17473, 21, 5, 5, 'a [אֶת־פִּ֙יךָ֙] a boca-tua [וְאַל־תֹּאמַר֙] a [הַמַּלְאָ֔ךְ] que [שְׁגָגָ֖ה] diante-de [לָ֣מָּה] porque [הָֽאֱלֹהִים֙] ela por-que [אֶת־מַעֲשֵׂ֥ה] הָֽאֱלֹהִים sobre a obra-de');
INSERT INTO verses VALUES (17474, 21, 5, 6, 'que em-muitos sonhos e-remédios e-de-palavras muito que a Elohim temor;');
INSERT INTO verses VALUES (17475, 21, 5, 7, 'se trabalho pobreza e-ladrão juízo וָצֶ֙דֶק֙ תִּרְאֶ֣ה בַמְּדִינָ֔ה a que sobre de-cima-de porque גָבֹ֜הַּ de-sobre גָּבֹ֙הַ֙ שֹׁמֵ֔ר וּגְבֹהִ֖ים sobre-eles');
INSERT INTO verses VALUES (17476, 21, 5, 8, '[וְיִתְר֥וֹן] terra em-todo rei [**ה֑וּא] [מֶ֥לֶךְ]');
INSERT INTO verses VALUES (17477, 21, 5, 9, 'amou prata não [כֶּ֔סֶף] prata [בֶּהָמ֖וֹן] não [תְבוּאָ֑ה] não [הָֽבֶל] também este');
INSERT INTO verses VALUES (17478, 21, 5, 10, 'בִּרְבוֹת֙ a-boa בִּרְבוֹת֙ אוֹכְלֶ֑יהָ e-que כִּשְׁרוֹן֙ que porque se os-seus-olhos');
INSERT INTO verses VALUES (17479, 21, 5, 11, 'מְתוּקָה֙ ano-de הָעֹבֵ֔ד se má e-se הרבך comera e a fartura para o rico a-ele põe para-ele na língua');
INSERT INTO verses VALUES (17480, 21, 5, 12, 'há mal doença vi debaixo o-sol dez guardado para os seus dentes para o seu dano');
INSERT INTO verses VALUES (17481, 21, 5, 13, 'וְאָבַד הָעֹ֥שֶׁר o-aquele בְּעִנְיַ֣ן mal וְהוֹלִ֣יד filho e-não-há em-sua-mão qualquer-coisa');
INSERT INTO verses VALUES (17482, 21, 5, 14, 'como-que sair מבטן sua-mãe nu volta para-andar כְּשֶׁבָּ֑א וּמְא֙וּמָה֙ não yisa בַעֲמָל֔וֹ שֶׁיֹּלֵ֖ךְ em-mão-sua');
INSERT INTO verses VALUES (17483, 21, 5, 15, 'e-também [רָעָ֣ה] mal [כָּל־עֻמַּ֥ת] todo [כֵּ֣ן] [יֵלֵ֑ךְ] assim a-ele e-que [לָרֽוּחַ] a-ele');
INSERT INTO verses VALUES (17484, 21, 5, 16, 'também todo יָמִים na-escuridão comera וְכָעֵס הרבֶּה וְחָלִיּוֹ e-ira');
INSERT INTO verses VALUES (17485, 21, 5, 17, 'eis que vi bom bom que יָפֶה לֶאֱכֹל־ e-lishtot e-lerot bem-boa em-todo amalo shiye''amol debaixo-de hashemesh em-o-número dias-de que deu para-ele Elohim porque ele chelqo');
INSERT INTO verses VALUES (17486, 21, 5, 18, 'também todo o-homem que deu para-ele הָאֱלֹהִים dez unekasim nós para comer do-que-ele velasa'' a chelqo e-lismoa ba-amalo zoh matat Elohim ela');
INSERT INTO verses VALUES (17487, 21, 5, 19, 'que não harbeh yizkor a dias-de que porque o-Elohim maaneh besimchath coração-dele');
INSERT INTO chapters VALUES (665, 21, 6, 12);
INSERT INTO verses VALUES (17488, 21, 6, 1, 'há maldade que vi debaixo o-sol e muita ela sobre o-homem');
INSERT INTO verses VALUES (17489, 21, 6, 2, 'homem que dê para-ele ha-elohim dez unekasim e glória e não há falta para si mesmo de-toda que será avivado e-não dominará nós que dele porque homem estrangeiro o comerá este mal ele mau ela');
INSERT INTO verses VALUES (17490, 21, 6, 3, 'se [אִ֣ישׁ] homem cem [רַבּ֨וֹת] [יִֽחְיֶ֜ה] [וְרַ֣ב] [׀] [שֶׁיִּהְי֣וּ] dias-de [וְנַפְשׁוֹ֙] [לֹא־תִשְׂבַּ֣ע] não [וְגַם־קְבוּרָ֖ה] de para-ele e-também bom nós foi para-ele bom dele');
INSERT INTO verses VALUES (17491, 21, 6, 4, 'porque בהבל veio e-em-a-ós irá e-em-a-ós shemo cobrir-se-á');
INSERT INTO verses VALUES (17492, 21, 6, 5, 'também Sol não viu e-não conheceu Naate para-este deste-lado');
INSERT INTO verses VALUES (17493, 21, 6, 6, 'e-se viveu mil dois duas-vezes e-bom não ver há não a um um o todo vai; vai:');
INSERT INTO verses VALUES (17494, 21, 6, 7, 'todo o-homem o-homem para a boca; não a-alma não תִמָּלֵֽא׃');
INSERT INTO verses VALUES (17495, 21, 6, 8, 'que que- mais para o sábio de -o tolo; que- diante sabe para a caminhada; diante-de -a vida:');
INSERT INTO verses VALUES (17496, 21, 6, 9, 'bom aspecto olhos de-halek- alma também este espírito espírito espírito');
INSERT INTO verses VALUES (17497, 21, 6, 10, 'que shahayah כְּבָר֙ encontrou-se seu-nome v''noda'' homem ele homem e-não podera ladin nós de-nós');
INSERT INTO verses VALUES (17498, 21, 6, 11, 'que ha palavras הַרְבֵּ֖ה marbim הָ֑בֶל que maior laadam');
INSERT INTO verses VALUES (17499, 21, 6, 12, 'que quem yodé''a que bom laadam nas-vivências מִסְפָּר dias-de chayye הֶבְלוֹ וְיַעֲשֵׂם כַּצֶּל que quem debaixo לָאָדָם que- יִהְיֶה atrás-dele debaixo-de o-sol');
INSERT INTO chapters VALUES (666, 21, 7, 29);
INSERT INTO verses VALUES (17500, 21, 7, 1, 'bom nome de-a-oleo bom וְיוֹם a-morte מֵיֹום הִוַּלְדוֹ׃');
INSERT INTO verses VALUES (17501, 21, 7, 2, 'bom para-andar a casa-de [אֶל־בֵּ֣ית] [מִשְׁתֶּ֔ה] a ele banquete [כָּל־הָאָדָ֑ם] ele [יִתֵּ֥ן] todo o-homem a');
INSERT INTO verses VALUES (17502, 21, 7, 3, 'bom [כַּ֖עַס] [מִשְּׂחֹ֑ק] porque [פָּנִ֖ים] face [לֵֽב] coração');
INSERT INTO verses VALUES (17503, 21, 7, 4, 'coração sábios em-casa-de אֵ֔בֶל וְלֵב כְּסִילִ֖ים em-casa-de alegria');
INSERT INTO verses VALUES (17504, 21, 7, 5, 'bom para-ouvir גַּעֲרַ֣ת sabio de-um ouviu cântico כְּסִילִ֖ים');
INSERT INTO verses VALUES (17505, 21, 7, 6, 'que como-voz os-sirim debaixo os-sirim assim séquok o-císil e-também este ABEL:');
INSERT INTO verses VALUES (17506, 21, 7, 7, 'que há-óshéq yeholél sabio וִֽיאַבֵּ֥ד a coração מַתָּנָֽה׃');
INSERT INTO verses VALUES (17507, 21, 7, 8, 'bom [אַחֲרִ֥ית] palavra [מֽ͏ֵרֵאשִׁית֑וֹ] bom [אֶֽרֶךְ־ר֖וּחַ] espírito espírito');
INSERT INTO verses VALUES (17508, 21, 7, 9, 'a [בְּרֽוּחֲךָ֖] [לִכְע֑וֹס] que porque [בְּחֵ֥יק] [כְּסִילִ֖ים] [יָנֽוּחַ]');
INSERT INTO verses VALUES (17509, 21, 7, 10, 'a תֹּאמַר֙ ser foi שֶׁ֤הַיָּמִים֙ dos primeiros foram טוֹבִ֖ים que não não מֵחָכְמָ֖ה שָׁאַ֥לְתָּ sobre este');
INSERT INTO verses VALUES (17510, 21, 7, 11, 'Továh sabedoria com נַחֲלָ֑ה וְיֹתֵ֖ר לְרֹאֵ֥י o-sol');
INSERT INTO verses VALUES (17511, 21, 7, 12, 'que em-a-sombra הַֽחָכְמָ֖ה בְּצֵ֣ל o-prata וְיִתְר֣וֹן conhecimento הַֽחָכְמָ֖ה תְּחַיֶּ֥ה בְעָלֶֽיהָ׃');
INSERT INTO verses VALUES (17512, 21, 7, 13, 'viu a obra-de que quem quem [לְתַקֵּ֔ן] [OBJ] a que');
INSERT INTO verses VALUES (17513, 21, 7, 14, '[בְּי֤וֹם] boa foi [בְט֔וֹב] [וּבְי֥וֹם] maldade viu também a este [עָשָׂ֣ה] este fez הָֽאֱלֹהִ֔ים sobre o-homem [אַחֲרָ֖יו] [מְאֽוּמָה] o-homem');
INSERT INTO verses VALUES (17514, 21, 7, 15, 'a todo o que vi em-dias-de הֶבְלִי ha just-o אבד בְּצִדְק֔וֹ וְיֵ֣שׁ perverso-o מַאֲרִ֖יךְ בְּרָעָתֽוֹ׃');
INSERT INTO verses VALUES (17515, 21, 7, 16, 'a [צַדִּיק֙] [הַרְבֵּ֔ה] [וְאַל־תִּתְחַכַּ֖ם] e-a [לָ֖מָּה] [תִּשּׁוֹמֵֽם]');
INSERT INTO verses VALUES (17516, 21, 7, 17, 'a [הַרְבֵּ֖ה] [וְאַל־תְּהִ֣י] e-a seja [תָמ֖וּת] por-que [עִתֶּֽךָ]');
INSERT INTO verses VALUES (17517, 21, 7, 18, 'bom que [תֶּאֱחֹ֣ז] neste e-também de-este a [כִּֽי־יְרֵ֥א] [OBJ]- [יֵצֵ֥א] porque Elohim a');
INSERT INTO verses VALUES (17518, 21, 7, 19, 'a sabedoria תועז לחוכם מעשרא שליטים que foram בעיר׃');
INSERT INTO verses VALUES (17519, 21, 7, 20, 'que homem não-há [צַדִּ֖יק] em-a-terra que fará- bom e-não');
INSERT INTO verses VALUES (17520, 21, 7, 21, 'também para-todo [אֲשֶׁ֣ר] que [אַל־תִּתֵּ֖ן] a [אֲשֶׁ֛ר] teu-coração que não a');
INSERT INTO verses VALUES (17521, 21, 7, 22, 'que também [רַבּ֖וֹת] saber conheceu teu-coração que também [קִלַּ֥לְתָּ] [אֲחֵרִֽים]');
INSERT INTO verses VALUES (17522, 21, 7, 23, 'todo [נִסִּ֣יתִי] [בַֽחָכְמָ֑ה] [אָמַ֣רְתִּי] eu-disse [וְהִ֖יא] e-ela [מִמֶּֽנִּי]');
INSERT INTO verses VALUES (17523, 21, 7, 24, '[רָח֖וֹק] que [וְעָמֹ֥ק] [׀] [עָמֹ֖ק] quem [יִמְצָאֶֽנּוּ]');
INSERT INTO verses VALUES (17524, 21, 7, 25, 'סבותי eu ולבבי para-conhecer ולתור ובקש sabedoria וחשבון וְלָדַעַת֙ רֶ֣שַׁע כֶּ֔סֶל וְהַסִּכְל֖וּת הוֹלֵלֽוֹת׃');
INSERT INTO verses VALUES (17525, 21, 7, 26, 'וּמוֹצֶ֨א eu מַ֣ר מִמָּ֗וֶת a a-mulher que הִ֨יא מְצוֹדִ֧ים וַחֲרָמִ֛ים seu-láb bom יָדֶ֑יהָ bom diante-de o-Elohim יִמָּלֵ֣ט de-a וְחוֹטֵ֖א יִלָּ֥כֶד nela');
INSERT INTO verses VALUES (17526, 21, 7, 27, 'viu este מָצָ֔אתִי אָמְרָ֖ה קֹהֶ֑לֶת uma לְאַחַ֖ת para-a-capturar Chesbeon:');
INSERT INTO verses VALUES (17527, 21, 7, 28, 'que עַד־ Busquei-a alma-minha e-não homem um um de mil encontrei-a e mulher não estes não encontrei:');
INSERT INTO verses VALUES (17528, 21, 7, 29, 'sozinho- Eis- este encontrei-a que fez o-Elohim a o-homem justo e-elas busquem caminhos muitos:');
INSERT INTO chapters VALUES (667, 21, 8, 17);
INSERT INTO verses VALUES (17529, 21, 8, 1, 'quem como a sabedoria e-quem que conhece a explicação palavra sabedoria da homem iluminará rosto-dele e o poder sua-face estabelecerá:');
INSERT INTO verses VALUES (17530, 21, 8, 2, 'eu [פִּי־מֶ֣לֶךְ] rei [וְעַ֕ל] e-sobre [שְׁבוּעַ֥ת] juramento-de Elohim');
INSERT INTO verses VALUES (17531, 21, 8, 3, 'a [מִפָּנָיו֙] [תֵּלֵ֔ךְ] [אַֽל־תַּעֲמֹ֖ד] a mal que mau porque todo que');
INSERT INTO verses VALUES (17532, 21, 8, 4, 'em-o-que palavra-de rei שלטון e-quem יאמר־ para-ele que Taase:');
INSERT INTO verses VALUES (17533, 21, 8, 5, 'guardiao mandamento não conheceu palavra mal ואת e julgamento conheceu coração חכם׃');
INSERT INTO verses VALUES (17534, 21, 8, 6, 'que para-todo desejo há tempo e-juízo o-homem maldade-de o-homem multiplicai sobre-ele');
INSERT INTO verses VALUES (17535, 21, 8, 7, 'porque sabe conheceu que que seja será quem será a-ele diga a-ele');
INSERT INTO verses VALUES (17536, 21, 8, 8, 'não-há homem príncipe בָּר֙וּחַ֙ para extinguir a o espírito e-não-há domínio em-dia-de a-morte e-não-há manda em-mo-batalha e-não salve injustiça a nele:');
INSERT INTO verses VALUES (17537, 21, 8, 9, 'a todo este vi e-dará a coração-meu debaixo מעשה que será-feita em-lugar-de o-homem עֵת que a-ele o-homem em-homem a-vós a-ele');
INSERT INTO verses VALUES (17538, 21, 8, 10, 'e-também Eu vi os ímpios sepultados e entraram e de lugar santo יְהַלּוּ וְיִֽשְׁתַּכְּח֥וּ: na cidade que כֵּן־ עָשׂוּ também este Havel:');
INSERT INTO verses VALUES (17539, 21, 8, 11, 'que não-há será feito פִתְגָ֔ם obra-de o-mal מְהֵרָ֑ה sobre assim enchei coração filhos-de mal neles para-fazer mau');
INSERT INTO verses VALUES (17540, 21, 8, 12, 'que [חֹטֶ֗א] fez mal [מְאַ֖ת] [וּמַאֲרִ֣יךְ] a-ele que também [אָ֔נִי] eu que [לְיִרְאֵ֣י] bom [אֲשֶׁ֥ר] o-Elohim que');
INSERT INTO verses VALUES (17541, 21, 8, 13, 'וְטוֹב֙ não será ao-malvado e-não יַאֲרִ֥יךְ dias cásel temer não-ela temendo de-a-frente-de Elohim');
INSERT INTO verses VALUES (17542, 21, 8, 14, 'há hevel que nasa sobre a-terra que há tsaddiqim que magga para-eles como-obra-de harasha''im ve''yesh rasha''im magga a-eles como-obra-de hatzaddiqim Eu disse ainda que este הָבֶל׃');
INSERT INTO verses VALUES (17543, 21, 8, 15, 'e eu louvaria eu a a-alegria que não-há debaixo ao homem que o-sol porque se para comer e para beber e para alegrar-se dias-de seria deleitado por seu trabalho dias-de debaixo que deu a-ele Elohim debaixo-de o-sol');
INSERT INTO verses VALUES (17544, 21, 8, 16, 'como-que dei a para-conhecer para conhecer חָכְמָה וְלִרְאוֹת֙ a הָ֣עִנְיָ֔ן que que sobre no-dia e-na-noite também בַּיּוֹם֙ וּבַלַּ֔יְלָה שֵׁנָ֕ה nos-seus-olhos não-ela viu');
INSERT INTO verses VALUES (17545, 21, 8, 17, 'וְרָאִיתִי֮ a todo que não porque o-homem יוּכַ֜ל o-homem לִמְצוֹא֙ a הַֽמַּעֲשֶׂה֙ que נעשָ debaixo-de o-homem בשֶל que יעמל o-homem para-pedir e-não para-conhecer não se Dará-dizer החכם para-conhecer não podia למצוא׃');
INSERT INTO chapters VALUES (668, 21, 9, 18);
INSERT INTO verses VALUES (17546, 21, 9, 1, 'que a dei [אֶל־לִבִּי֙] [וְלָב֣וּר] a coração-meu [הַצַּדִּיקִ֧ים] a todo este que [גַּֽם־אַהֲבָ֣ה] [גַם־שִׂנְאָ֗ה] [אֵ֤ין] em-mão-de o-homem também [לִפְנֵיהֶֽם] também o-homem');
INSERT INTO verses VALUES (17547, 21, 9, 2, 'o-tudo como-que para-todo [מִקְרֶ֨ה] um [לַצַּדִּ֤יק] [וְלָרָשָׁע֙] [לַטּוֹב֙] [וְלַטָּה֣וֹר] [וְלַטָּמֵ֔א] [וְלַזֹּבֵ֔חַ] [וְלַאֲשֶׁ֖ר] [אֵינֶ֣נּוּ] [זֹבֵ֑חַ] [כַּטּוֹב֙] [כַּֽחֹטֶ֔א] [הַנִּשְׁבָּ֕ע] conforme [שְׁבוּעָ֥ה] temer');
INSERT INTO verses VALUES (17548, 21, 9, 3, 'este mau mal que [אֲשֶֽׁר־נַעֲשָׂה֙] debaixo o-sol porque um um para-todo e-também coração filhos-de o-homem [בִּלְבָבָם֙] mau [וְאַחֲרָ֖יו] [אֶל־הַמֵּתִֽים] a');
INSERT INTO verses VALUES (17549, 21, 9, 4, 'porque quem que El a os vivos há -o seguro porque vida ele bom bom de a ursos os mortos:');
INSERT INTO verses VALUES (17550, 21, 9, 5, 'que a-vida os que conhecem -sejam mortos os mortos: não conhecem מְא֗וּמָה e-nao-ha a-eles para-eles que porque -esquecido zichram:');
INSERT INTO verses VALUES (17551, 21, 9, 6, 'também ahavatam também sin''ataham também qin''atahem kavar abadah vechaleq não-há a-eles ainda debaixo em-todo que que debaixo-de o-sol');
INSERT INTO verses VALUES (17552, 21, 9, 7, 'vai e''kol בֲּשִׂמְחָה lachamekha e beba בְּלֵב־ bom que porque já aceite o-Elohim a seus feitos');
INSERT INTO verses VALUES (17553, 21, 9, 8, 'em-todo tempo serao em suas vestes brancos e óleo sobre sua cabeça a falta');
INSERT INTO verses VALUES (17554, 21, 9, 9, 'viu vida com mulher que ama-te todo os-dias chayyei debaixo que deu dias-de debaixo-de que ele dias-de seu-havel porque ele seu-herde debaixo e-no-teu-trabalho que tu trabalho debaixo-de o-sol');
INSERT INTO verses VALUES (17555, 21, 9, 10, 'todo que encontre tuas-mãos para-fazer no-teu-poder fez que nao-ha Masháv e-chesbôn e-conhecimento e-sabedoria בִּשְׁא֕וֹל que tu andou ali');
INSERT INTO verses VALUES (17556, 21, 9, 11, '[שַׁ֜בְתִּי] [וְרָאֹ֣ה] [תַֽחַת־הַשֶּׁ֗מֶשׁ] que não não [הַמֵּר֜וֹץ] [וְלֹ֧א] e-não [הַמִּלְחָמָ֗ה] a-guerra não não pão pão não não [עֹ֔שֶׁר] dez não não [חֵ֑ן] [כִּי־עֵ֥ת] porque tempo [אֶת־כֻּלָּֽם] a');
INSERT INTO verses VALUES (17557, 21, 9, 12, 'que também não o-homem o-homem a seu tempo como peixes que são agarrados por sua mão maldade e como pombas a ação no seu ninho como eles o-homem filhos-de o-homem ao-tempo-de maldade quando caírem sobre-eles de repente:');
INSERT INTO verses VALUES (17558, 21, 9, 13, 'também isto Eu vi debaixo em-lugar-de o-sol e grande ela para-mim');
INSERT INTO verses VALUES (17559, 21, 9, 14, 'cidade e pequena e homens nela pouco e veio a-ela rei grande e cercou- a-ela e edificou sobre-ela fortalezas grandes-');
INSERT INTO verses VALUES (17560, 21, 9, 15, '[וּמָ֣צָא] [בָ֗הּ] homem [מִסְכֵּן֙] [חָכָ֔ם] [וּמִלַּט־ה֥וּא] ele a a-cidade não [זָכַ֔ר] não macho a');
INSERT INTO verses VALUES (17561, 21, 9, 16, 'וְאָמַ֣רְתִּי eu טוֹבָ֥ה sabedoria מִגְּבוּרָ֑ה וְחָכְמַ֤ת o-misken be-zuia u-dvarai einam nismaim');
INSERT INTO verses VALUES (17562, 21, 9, 17, 'palavras-de חכמים be-nachat nismaim mi-za''qa moshel be-kasalim');
INSERT INTO verses VALUES (17563, 21, 9, 18, 'ótah sabedoria miklê qerav vachotea um יְאַבֵּ֥ד bem hărbeh');
INSERT INTO chapters VALUES (669, 21, 10, 20);
INSERT INTO verses VALUES (17564, 21, 10, 1, 'zevuvê mavet יַבְעִישׁ yabba'' óleo rakea'' precioso de sabedoria de glória סכלות pouco');
INSERT INTO verses VALUES (17565, 21, 10, 2, 'coração sábio à sua direita וְלֵב estúpido à sua esquerda:');
INSERT INTO verses VALUES (17566, 21, 10, 3, 'e-também em-a-caminho andou seu coração falta e-disse para-todo סכל ela');
INSERT INTO verses VALUES (17567, 21, 10, 4, 'se espírito [תַּעֲלֶ֣ה] [עָלֶ֔יךָ] sobre-ti [אַל־תַּנַּ֑ח] que [מַרְפֵּ֔א] porque [חֲטָאִ֥ים] [גְּדוֹלִֽים]');
INSERT INTO verses VALUES (17568, 21, 10, 5, 'há maldade vi debaixo o-sol כשוגגת שיהיה de-a-frente-de o governante');
INSERT INTO verses VALUES (17569, 21, 10, 6, 'deu a sabedoria nos altos muitos e ricos בַּשֵּׁ֥פֶל: יֵשֵֽׁבוּ׃:');
INSERT INTO verses VALUES (17570, 21, 10, 7, 'Vi servos sobre cavaleiros וְשָׂרִ֛ים: andando כַּעֲבָדִ֖ים: sobre a-terra');
INSERT INTO verses VALUES (17571, 21, 10, 8, 'חֹפֵ֥ר: גּוּמָּ֖ץ: nele יִפּ֑וֹל: וּפֹרֵ֥ץ גָּדֵ֖ר יִשְּׁכֶ֥נּוּ נָחָֽשׁ׃');
INSERT INTO verses VALUES (17572, 21, 10, 9, 'מַסִּ֣יעַ pedras יֵעָצֵ֖ב com-eles בּוֹקֵ֥עַ madeiras יִסָּ֥כֶן em-eles');
INSERT INTO verses VALUES (17573, 21, 10, 10, 'se [הַבַּרְזֶ֗ל] [וְהוּא֙] e-ele não face [יְגַבֵּ֑ר] [וְיִתְר֥וֹן] [*הכשי[y]*ר] [**הַכְשֵׁ֖ר] [חָכְמָֽה]');
INSERT INTO verses VALUES (17574, 21, 10, 11, 'se [הַנָּחָ֖שׁ] a-serpente [וְאֵ֣ין] [יִתְר֔וֹן] e-não-há [הַלָּשֽׁוֹן]');
INSERT INTO verses VALUES (17575, 21, 10, 12, 'palavras-de a boca- sábio grace e-lábios -cobiça engolirá-lhe');
INSERT INTO verses VALUES (17576, 21, 10, 13, 'início דְּבָרֵי- sua-boca -prudente e-última boca-sua -risada mal');
INSERT INTO verses VALUES (17577, 21, 10, 14, 'e-a-sábia que multiplique-se palavras não o-homem o-homem que será e-que quem de detrás dele a-ele anunciará a-ele');
INSERT INTO verses VALUES (17578, 21, 10, 15, 'trabalho os preguiçosos tormentarão que não conheceu para-andar a cidade');
INSERT INTO verses VALUES (17579, 21, 10, 16, 'não- terra terra teu reino jovem e teus príncipes בַּבֹּ֥קֶר יֹאכֵֽלוּ׃');
INSERT INTO verses VALUES (17580, 21, 10, 17, '[אַשְׁרֵ֣יךְ] terra [שֶׁמַּלְכֵּ֖ךְ] filho-de [וְשָׂרַ֙יִךְ֙] [בָּעֵ֣ת] em-o-tempo [בִּגְבוּרָ֖ה] [וְלֹ֥א] e-não');
INSERT INTO verses VALUES (17581, 21, 10, 18, 'בַּעֲצַלְתַּ֖יִם יִמַּ֣ךְ o-dragante e-em-pobreza mãos desvendar-á a-casa');
INSERT INTO verses VALUES (17582, 21, 10, 19, 'para-rir-se fazendo pão e-vinho alegrar-se-á vida e-o-prata responder-á a tudo-:');
INSERT INTO verses VALUES (17583, 21, 10, 20, 'também בְּמַדָּֽעֲךָ֗ rei a תְּקַלֵּ֔ל וּבְחַדְרֵי֙ מִשְׁכָּ֣בְךָ֔ a que ave porque ave os-céus יוֹלִ֣יךְ a הַקּ֔וֹל e-baal יַגֵּ֥יד palavra');
INSERT INTO chapters VALUES (670, 21, 11, 10);
INSERT INTO verses VALUES (17584, 21, 11, 1, 'enviou [לַחְמְךָ֖] sobre as-águas as-águas porque [תִּמְצָאֶֽנּוּ]');
INSERT INTO verses VALUES (17585, 21, 11, 2, 'dá porção לְשִׁבְעָ֖ה e-também que não não תֵדַע que יִּהְיֶ֥ה maldade sobre a-terra');
INSERT INTO verses VALUES (17586, 21, 11, 3, 'se [הֶעָבִ֥ים] [גֶּ֙שֶׁם֙] [עַל־הָאָ֣רֶץ] sobre a-terra árvore e-se [וְאִ֣ם] [בַּצָּפ֑וֹן] [מְק֛וֹם] e-se a-árvore [שָׁ֥ם] [יְהֽוּא] nome');
INSERT INTO verses VALUES (17587, 21, 11, 4, 'guardando espírito não [יִזְרָ֑ע] [וְרֹאֶ֥ה] [בֶעָבִ֖ים] não [יִקְצֽוֹר]');
INSERT INTO verses VALUES (17588, 21, 11, 5, 'como-que [אֵֽינְךָ֤] conhecedor que caminho [כַּעֲצָמִ֖ים] [בְּבֶ֣טֶן] [הַמְּלֵאָ֑ה] [כָּ֗כָה] não não [אֶת־מַעֲשֵׂ֣ה] a obra-de הָֽאֱלֹהִ֔ים que a');
INSERT INTO verses VALUES (17589, 21, 11, 6, 'na-manhã זְרַ֣ע a זַרְעֶ֔ךָ e-no-éreb a que tua-mao porque a-en-kha yod-e-a a-ey este yi-kha-sha-r ha-zeh ou este e-se sh-neh-e-hem ke''echad bem-aventurados:');
INSERT INTO verses VALUES (17590, 21, 11, 7, 'u-ma-toq a-luz e-bom la-ay-na-im para-ver a o-sol');
INSERT INTO verses VALUES (17591, 21, 11, 8, 'que se dois ha-rab-be o-homem o-homem em-todos-os-lesmas será-alegrado e-recordará a dias-de a-escuridão porque muito serão todo sétimo havel:');
INSERT INTO verses VALUES (17592, 21, 11, 9, 'alegrar-se-á jovem-moço em-tua-infância לִבֶּֽךָ em-dias-de em-tua-juventude e-andarás nos-caminhos-de para-o-teu-coração e nos vislumbres teus-olhos e conhecimento porque que todo estes levará-te Elohim pelo julgamento');
INSERT INTO verses VALUES (17593, 21, 11, 10, 'e retira ira do teu coração e passarás maldade pela tua esperança porque a gravidez e a aurora Cavel:');
INSERT INTO chapters VALUES (671, 21, 12, 14);
INSERT INTO verses VALUES (17594, 21, 12, 1, 'e lembre-se a de teu criador nos-dias até até que dias-de vão dias-de a má e cheguem dois que תֹּאמַ֔ר não-há para-mim neles prazer:');
INSERT INTO verses VALUES (17595, 21, 12, 2, 'até que não terá escuridão o-sol e a luz ve-ha-yyarach e as estrelas וְשָׁ֥בוּ os nuvens achar a chuva:');
INSERT INTO verses VALUES (17596, 21, 12, 3, 'no-dia tremularem-se שמוראי a-casa e se espantaram homens-de a força e desvaneceram-se as nuvens que de pouca e-a-escuridão as visões בָּאֲרֻבּֽוֹת׃');
INSERT INTO verses VALUES (17597, 21, 12, 4, '[וְסֻגְּר֤וּ] [דְלָתַ֙יִם֙] [בַּשּׁ֔וּק] [בִּשְׁפַ֖ל] voz [הַֽטַּחֲנָ֑ה] [וְיָקוּם֙] à-voz-de [הַצִּפּ֔וֹר] [וְיִשַּׁ֖חוּ] todo filhas-de');
INSERT INTO verses VALUES (17598, 21, 12, 5, 'também de-sua-altura virão e-estremecer-se-ão em-a-caminho e-tremeçam aquele-que-ardia e-torcem-se o-ciclope e-tesourem aquele-que-é-puro porque o-homem o-homem a casa seu-mundo וְסָבְב֥וּ בָשׁ֖וּק הַסֹּפְדִֽים׃');
INSERT INTO verses VALUES (17599, 21, 12, 6, 'até que não região [חֶ֣בֶל] [הַכֶּ֔סֶף] [וְתָרֻ֖ץ] [גֻּלַּ֣ת] o-ouro [וְתִשָּׁ֤בֶר] sobre [עַל־הַמַּבּ֔וּעַ] [וְנָרֹ֥ץ] [הַגַּלְגַּ֖ל] a');
INSERT INTO verses VALUES (17600, 21, 12, 7, 'e-sentou-se a poeira sobre a-terra quando ela foi e a respiração vai voltar a Elohim que ela deu׃');
INSERT INTO verses VALUES (17601, 21, 12, 8, 'vanidade vanidades disse a coletora tudo o vanidade׃');
INSERT INTO verses VALUES (17602, 21, 12, 9, 'e mais que havia sido Qohelet sabio ainda ensinou conhecimento a o-povo e ouviu e investigou corrigiu provérbios mais');
INSERT INTO verses VALUES (17603, 21, 12, 10, 'buscou קוהלת para achar דְּבָרֵי- prazer e escrito justo palavras-de verdade');
INSERT INTO verses VALUES (17604, 21, 12, 11, 'palavras de sábios como a cera e como o ferro plantados aos chefes colhidos foram dados de-rea um');
INSERT INTO verses VALUES (17605, 21, 12, 12, 'e-mais de-eles filhos-de cuidado-se fazer livros multiplique-te não-há destruição e-arraste multiplique יְגִיעַת carne');
INSERT INTO verses VALUES (17606, 21, 12, 13, 'סוֹף palavra o-todo נִשְׁמָע a os-Elohim יְרָא e-a מִצְוֺתָיו שְׁמֹור porque este todo o-homem');
INSERT INTO verses VALUES (17607, 21, 12, 14, 'a todo [הָאֱלֹהִ֛ים] o-Elohim [בְמִשְׁפָּ֖ט] sobre sobre todo [וְאִם־רָֽע] se bom mau');
INSERT INTO books VALUES (22, 'SNG', 'Cantares', 'AT', 8);
INSERT INTO chapters VALUES (672, 22, 1, 17);
INSERT INTO verses VALUES (17608, 22, 1, 1, 'cântico os Cânticos que לisleomo:');
INSERT INTO verses VALUES (17609, 22, 1, 2, 'beijes-me de beijos boca-sua porque bom [מִיָּֽיִן] de água');
INSERT INTO verses VALUES (17610, 22, 1, 3, 'pelo odor dos teus óleos bom she-men-en tuas gotas o-teu-nome sobre assim סימנים אהובך׃');
INSERT INTO verses VALUES (17611, 22, 1, 4, '[מָשְׁכֵ֖נִי] [אַחֲרֶ֣יךָ] [נָּר֑וּצָה] [הֱבִיאַ֨נִי] o-rei [חֲדָרָ֗יו] [נָגִ֤ילָה] [וְנִשְׂמְחָה֙] sobre-ti [נַזְכִּ֤ירָה] [דֹדֶ֙יךָ֙] [מִיַּ֔יִן] [מֵישָׁרִ֖ים] [אֲהֵבֽוּךָ׃]');
INSERT INTO verses VALUES (17612, 22, 1, 5, '[שְׁחוֹרָ֤ה] eu [וְֽנָאוָ֔ה] [בְּנ֖וֹת] Jerusalém [כְּאָהֳלֵ֣י] qedar כּיִרְע֖וֹת שְׁלֹמֹה');
INSERT INTO verses VALUES (17613, 22, 1, 6, 'a [שֶׁאֲנִ֣י] [שְׁחַרְחֹ֔רֶת] [שֶׁשֱּׁזָפַ֖תְנִי] [הַשָּׁ֑מֶשׁ] o-sol filhos-de [נִֽחֲרוּ־בִ֗י] [שָׂמֻ֙נִי֙] [נֹטֵרָ֣ה] [אֶת־הַכְּרָמִ֔ים] [כַּרְמִ֥י] a não [נָטָֽרְתִּי] não');
INSERT INTO verses VALUES (17614, 22, 1, 7, 'declara a-mim שֶׁאָהֵבָה֙ nafshi אֵיכָה תִּרְעֶה׃ אֵיכָה תִּרְבִּי׃ בְּצָהֳרָ֑יִם שַׁלְּמָה אֶהְיֶה כּוּעֹתְיָה sobre עֶדְרֵי חֲבֵרֶיךָ׃');
INSERT INTO verses VALUES (17615, 22, 1, 8, 'se não para-ti para-ti [בַּנָּשִׁ֑ים] [צְֽאִי־לָ֞ךְ] [בְּעִקְבֵ֣י] [הַצֹּ֗אן] [וּרְעִי֙] [אֶת־גְּדִיֹּתַ֔יִךְ] sobre a [הָרֹעִֽים׃] sobre');
INSERT INTO verses VALUES (17616, 22, 1, 9, 'para-seus-cavalos em-teus-carros פַּרְעֹה tuas-fez minha-companheiras;');
INSERT INTO verses VALUES (17617, 22, 1, 10, 'alegraram-se em-teus-dias com-oliveiras tuas-coroa de-turquesas;');
INSERT INTO verses VALUES (17618, 22, 1, 11, '[תּוֹרֵ֤י] ouro [נַעֲשֶׂה־לָּ֔ךְ] para-ti povo [הַכָּֽסֶף]');
INSERT INTO verses VALUES (17619, 22, 1, 12, 'até [בִּמְסִבּ֔וֹ] [נִרְדִּ֖י] dar deu');
INSERT INTO verses VALUES (17620, 22, 1, 13, '[צְר֨וֹר] [הַמֹּ֤ר] [׀] para-mim entre entre [שָׁדַ֖י]');
INSERT INTO verses VALUES (17621, 22, 1, 14, '[אֶשְׁכֹּ֨ל] [הַכֹּ֤פֶר] [׀] para-mim [לִ֔י] olho [עֵ֥ין]');
INSERT INTO verses VALUES (17622, 22, 1, 15, 'הִנּוֹךְ יָפָה רַעְיָתִי eis-a יָפָה עֵינַיִךְ Jonim:');
INSERT INTO verses VALUES (17623, 22, 1, 16, 'Hinnekha֩ Yafe Dodi certamente Na''im também Arshenu֖ Raanana:');
INSERT INTO verses VALUES (17624, 22, 1, 17, 'Korot Betainu֙ cedros Berotim:');
INSERT INTO chapters VALUES (673, 22, 2, 17);
INSERT INTO verses VALUES (17625, 22, 2, 1, 'eu chavatzet hasharon shoshannat ha''amakim');
INSERT INTO verses VALUES (17626, 22, 2, 2, 'keshoshannah entre hachohim assim ra''iyati entre habbanot');
INSERT INTO verses VALUES (17627, 22, 2, 3, 'ketafpo''ach ba''atzey a-floresta assim meus-amores- entre הַבָּנִ֑ים בְּצִלּוֹ֙ חִמַּ֣דְתִּי וְיָשַׁ֔בְתִּי וּפִרְי֖וֹ מָת֥וֹק לְחִכִּֽי׃');
INSERT INTO verses VALUES (17628, 22, 2, 4, '[הֱבִיאַ֙נִי֙] a casa [וְדִגְל֥וֹ] [עָלַ֖י] sobre-mim');
INSERT INTO verses VALUES (17629, 22, 2, 5, '[סַמְּכ֙וּנִי֙] [בָּֽאֲשִׁישׁ֔וֹת] [רַפְּד֖וּנִי] [בַּתַּפּוּחִ֑ים] porque [אַהֲבָ֖ה] [אָֽנִי]');
INSERT INTO verses VALUES (17630, 22, 2, 6, 'שְׂמֹאלוֹ֙ debaixo לְרֹאשִׁ֔י וִימִינ֖וֹ abraça-me:');
INSERT INTO verses VALUES (17631, 22, 2, 7, 'jura-te a-vós filhas Jerusalém de-campistas ou de-ovejas o-campo se acordem ⚫ e se; arrebatem ⚫ até o-amor até que-desejare:');
INSERT INTO verses VALUES (17632, 22, 2, 8, 'voz [דּוֹדִ֔י] eis-que- este veio [עַל־הֶ֣הָרִ֔ים] sobre [עַל־הַגְּבָעֽוֹת] sobre');
INSERT INTO verses VALUES (17633, 22, 2, 9, '[דּוֹמֶ֤ה] [דוֹדִי֙] [לִצְבִ֔י] ou [לְעֹ֣פֶר] [הָֽאַיָּלִ֑ים] eis-que- este [אַחַ֣ר] atrás-de [מַשְׁגִּ֙יחַ֙] [מִן־הַֽחֲלֹּנ֔וֹת] de [מִן־הֽ͏ַחֲרַכִּֽים] de');
INSERT INTO verses VALUES (17634, 22, 2, 10, '[עָנָ֥ה] [דוֹדִ֖י] [וְאָ֣מַר] para-mim [ק֥וּמִי] para-ti [רַעְיָתִ֥י] [יָפָתִ֖י] [וּלְכִי־לָֽךְ] para-ti');
INSERT INTO verses VALUES (17635, 22, 2, 11, 'porque eis [**הַסְּתָ֖יו] [עָבָ֑ר] [הַגֶּ֕שֶׁם] andou andar');
INSERT INTO verses VALUES (17636, 22, 2, 12, 'הַנִּצָּנִים֙ נִרְא֣וּ na-terra tempo הַזָּמִ֖יר הִגִּ֑יעַ e-voz הַתּ֖וֹר foi-ouvido em-nos');
INSERT INTO verses VALUES (17637, 22, 2, 13, 'a-téenáh chanta págêyah ve-hagfánim sémadar natanu re''ach qumi ra''iyati יָפְתִּי וּלְכִי para-ti');
INSERT INTO verses VALUES (17638, 22, 2, 14, 'יוֹנַתִּי בְּחַגוֹווֶ הַסֶּ֗לַע בְּסֵ֙תֶר֙ הַמַּדְרֵגָ֔ה הַרְאִ֙ינִי֙ a מַרְאַ֔יִךְ הַשְׁמִיעִ֖ינִי a voze-te porque voze-te tarde e-te visão nós');
INSERT INTO verses VALUES (17639, 22, 2, 15, 'agarramos a-nós cães- cães- pequenos mordedores de-carris e-nos-castanhais disposto:');
INSERT INTO verses VALUES (17640, 22, 2, 16, 'meu-próximo a-mim e-eu a-ele que-cria nas-flor-de-lis:');
INSERT INTO verses VALUES (17641, 22, 2, 17, 'até e-estendeu o-dia e-elevaram-se as-sombra rodeou pareceu-se-a para ti דוֹדִ֜י li-tzi-ba ou le-afar ha-aiyali-m sobre ha-ri ba-tar');
INSERT INTO chapters VALUES (674, 22, 3, 11);
INSERT INTO verses VALUES (17642, 22, 3, 1, 'sobre mi-shkabi-yah bal-lay-loth בִּקַּ֕שְׁתִּי a she-ahav-ah minha-alma buscou-o e-não encontrei-o');
INSERT INTO verses VALUES (17643, 22, 3, 2, 'arrepiada por favor e andarei ao redor na cidade nos mercados e nas praças buscarei a que eu ame minha-alma buscou-o e-não encontrei-o');
INSERT INTO verses VALUES (17644, 22, 3, 3, 'encontrem-me os-guardas os que andam na-cidade objeto-direto que ame alma-minha vê-los');
INSERT INTO verses VALUES (17645, 22, 3, 4, 'por pouco eu passei de-eles até eu fui achada a que ame minha-alma peguei-o e-não אַרְפֶּ֔נּוּ até שֶׁ֤הֲבֵיאתִיו֙ a casa mãe-minha e-a חֶ֖דֶר הוֹרָתִֽי׃');
INSERT INTO verses VALUES (17646, 22, 3, 5, 'הִשְׁבַּ֨עְתִּי a-vós בְּנ֤וֹת Jerusalém בִּצְבָא֔וֹת ou בְּאַיְל֣וֹת o-campo se תָּעִ֧ירוּ ׀ e se; תְּעֽוֹרְר֛וּ até a-amor até que-deseje');
INSERT INTO verses VALUES (17647, 22, 3, 6, 'quem esta ʿōlāh de o-deserto como-citrinos de-lesmas coroada már de-toda de-todo aberta que-rolle');
INSERT INTO verses VALUES (17648, 22, 3, 7, 'eis em-a-sua-cama de-Solomão sessenta valentes em-volta para ela dos-maiores Israel');
INSERT INTO verses VALUES (17649, 22, 3, 8, 'todos-os das-possuias espada dos-aprendizes guerra homem sua-sabre sobre seus-joelhos do-medo nas-noites');
INSERT INTO verses VALUES (17650, 22, 3, 9, 'a-cupula fez a-ele o-rei Shelomoh dos-troncos do-Libanon');
INSERT INTO verses VALUES (17651, 22, 3, 10, 'de-suas-colunas fez prata refidáto ouro merkábo argamán tocho ratsuíf אַהֲבָ֔ה מִבְּנ֖וֹת Jerusalém');
INSERT INTO verses VALUES (17652, 22, 3, 11, 'zeiná uréiná filhas-de Sião bammelék Shelomoh ba''atará šé''etará לוֹ sua-mãe em-dia-de חתונתוֹ וביום שמחת coração-dele');
INSERT INTO chapters VALUES (675, 22, 4, 16);
INSERT INTO verses VALUES (17653, 22, 4, 1, 'הינך יפחה רעהתי הינך bela עינייך יונים מִבַּ֖עַד לְצַמָּתֵ֑ךְ שַׂעְרֵךְ֙ כְּעֵ֣דֶר העיזים שֶׁגָּלְשׁ֖וּ me-ha-mar gil-ad');
INSERT INTO verses VALUES (17654, 22, 4, 2, '[שִׁנַּ֙יִךְ֙] [כְּעֵ֣דֶר] [הַקְּצוּב֔וֹת] [שֶׁעָל֖וּ] de [שֶׁכֻּלָּם֙] [מַתְאִימ֔וֹת] [וְשַׁכֻּלָ֖ה] [אֵ֥ין] não');
INSERT INTO verses VALUES (17655, 22, 4, 3, '[כְּח֤וּט] [הַשָּׁנִי֙] [שִׂפְתֹתַ֔יִךְ] [וּמִדְבָּרֵ֖יךְ] [נָאוֶ֑ה] [כְּפֶ֤לַח] [הָֽרִמּוֹן֙] [רַקָּתֵ֔ךְ] [מִבַּ֖עַד] [לְצַמָּתֵֽךְ]');
INSERT INTO verses VALUES (17656, 22, 4, 4, 'כְּמִגְדַּל Davi צַוָּארֵךְ בָּנ֖וּי לְתַלְפִּיּ֑וֹת mil הַמָּגֵן֙ תָּל֣וּי sobre-ele todo שִׁלְטֵ֥י os-guerra-rem:');
INSERT INTO verses VALUES (17657, 22, 4, 5, 'segundo seus-poderes como asas gemelos glória os-que-guerram na-flor-de-lótus:');
INSERT INTO verses VALUES (17658, 22, 4, 6, 'até feios o-dia e-venceram הַצְּלָלִים אֵ֤לֶךְ a-mim a monte-de הַמּ֔וֹר e-a colina-de הַלְּבוֹנָֽה׃');
INSERT INTO verses VALUES (17659, 22, 4, 7, '[כֻּלָּ֤ךְ] [יָפָה֙] [רַעְיָתִ֔י] [וּמ֖וּם] não sobre-ti');
INSERT INTO verses VALUES (17660, 22, 4, 8, 'אִתִּ֤י מִלְּבָנוֹן֙ כלה com eu מלבנון תבואי תshawuri מראש אמנה מראש שנייר והרמון ממעונות aray-o-t מֵהַרְרֵ֖י נְמֵרִֽים׃');
INSERT INTO verses VALUES (17661, 22, 4, 9, '[לִבַּבְתִּ֖נִי] [אֲחֹתִ֣י] [כַלָּ֑ה] [לִבַּבְתִּ֙ינִי֙] [*באחד] [**בְּאַחַ֣ת] [מֵעֵינַ֔יִךְ] [בְּאַחַ֥ד]');
INSERT INTO verses VALUES (17662, 22, 4, 10, 'que- יָּפ֥וּ dodayikh achotiy kalah que- tobu dodayikh miyayin ve-reich shmanayikh de-todo beshamayim');
INSERT INTO verses VALUES (17663, 22, 4, 11, 'nafet תִּטֹּ֥פְנָה שִׂפְתוֹתַ֖יִךְ כַּלָּ֑ה דְּבַ֤שׁ וְחָלָב֙ debaixo לְשׁוֹנֵ֔ךְ וְרֵ֥יחַ שַׂלְמֹתַ֖יִךְ כְּרֵ֥יחַ לְבָנֽוֹן׃');
INSERT INTO verses VALUES (17664, 22, 4, 12, 'jardim נעוּל אחותי כלה גל נעוּל manancial חתום׃');
INSERT INTO verses VALUES (17665, 22, 4, 13, '[שְׁלָחַ֙יִךְ֙] [פַּרְדֵּ֣ס] [רִמּוֹנִ֔ים] povo fruto [מְגָדִ֑ים] [כְּפָרִ֖ים] com');
INSERT INTO verses VALUES (17666, 22, 4, 14, '[נֵ֣רְדְּ] [׀] [וְכַרְכֹּ֗ם] [קָנֶה֙] povo todo madeiras-de [לְבוֹנָ֑ה] [מֹ֚ר] [וַאֲהָל֔וֹת] povo todo topos-de');
INSERT INTO verses VALUES (17667, 22, 4, 15, '[מַעְיַ֣ן] [גַּנִּ֔ים] [בְּאֵ֖ר] águas vida [וְנֹזְלִ֖ים] de');
INSERT INTO verses VALUES (17668, 22, 4, 16, '[ע֤וּרִי] [צָפוֹן֙] [וּב֣וֹאִי] [תֵימָ֔ן] [הָפִ֥יחִי] [גַנִּ֖י] [יִזְל֣וּ] [בְשָׂמָ֑יו] [יָבֹ֤א] [דוֹדִי֙] [לְגַנּ֔וֹ] [וְיֹאכַ֖ל] fruto [מְגָדָֽיו]');
INSERT INTO chapters VALUES (676, 22, 5, 16);
INSERT INTO verses VALUES (17669, 22, 5, 1, 'בָּ֣אתִי לְגַנִּי֮ irmã-mi côla- ari-te mori- com besham-iy akhal-ti ya''ari com davis-hi shatiti yeni-ni com meu leite comam seus companheiros bebam e bebam vinho meus parentes');
INSERT INTO verses VALUES (17670, 22, 5, 2, 'eu dorma e meu coração seu ventre voz meu parente דוֹפֵ֗ק פִּתְחִי־ para-mim irmã- רַעְיָתִי֙ יוֹנָתִ֣י תַמָּתִ֔י שֶׁרֹּאשִׁי֙ נִמְלָא־ טָ֔ל קְוֻּצּוֹתַ֖י noite noite');
INSERT INTO verses VALUES (17671, 22, 5, 3, '[פָּשַׁ֙טְתִּי֙] a [אֵיכָ֖כָה] [אֶלְבָּשֶׁ֑נָּה] [רָחַ֥צְתִּי] [אֶת־רַגְלַ֖י] a [אֲטַנְּפֵֽם]');
INSERT INTO verses VALUES (17672, 22, 5, 4, '[דּוֹדִ֗י] enviou sua-mão de [וּמֵעַ֖י] [הָמ֥וּ] [עָלָֽיו] sobre-ele');
INSERT INTO verses VALUES (17673, 22, 5, 5, '[קַ֥מְתִּֽי] eu [לִפְתֹּ֣חַ] [לְדוֹדִ֑י] [וְיָדַ֣י] [נָֽטְפוּ־מ֗וֹר] [וְאֶצְבְּעֹתַי֙] [מ֣וֹר] [עֹבֵ֔ר] sobre sobre [הַמַּנְעֽוּל]');
INSERT INTO verses VALUES (17674, 22, 5, 6, 'Eu abri eu para meu amado e meu amado tremeu passou minha-nפשׁי saíram em sua palavra eu o busquei e-não encontrei-o chamou-o e-não respondeu-me');
INSERT INTO verses VALUES (17675, 22, 5, 7, '[מְצָאֻ֧נִי] [הַשֹּׁמְרִ֛ים] [הַסֹּבְבִ֥ים] [בָּעִ֖יר] [הִכּ֣וּנִי] [פְצָע֑וּנִי] [נָשְׂא֤וּ] a [מֵֽעָלַ֔י] [שֹׁמְרֵ֖י] guardadores-de');
INSERT INTO verses VALUES (17676, 22, 5, 8, '[הִשְׁבַּ֥עְתִּי] vós filhas-de Jerusalém se [אֶת־דּוֹדִ֔י] a a-ele que- conteis a-ele');
INSERT INTO verses VALUES (17677, 22, 5, 9, 'que- [מִדּ֔וֹד] [הַיָּפָ֖ה] [בַּנָּשִׁ֑ים] [מַה־דּוֹדֵ֣ךְ] que- [שֶׁכָּ֖כָה] [הִשְׁבַּעְתָּֽנוּ] fizeste-jurar-nos');
INSERT INTO verses VALUES (17678, 22, 5, 10, 'Dodi Tsach Ve''adom Dagul Mervabah');
INSERT INTO verses VALUES (17679, 22, 5, 11, 'cabeça-sua Ketem Paz Qutzotayav Taltallim Shchorot כּוֹעֵר׃');
INSERT INTO verses VALUES (17680, 22, 5, 12, '[עֵינָ֕יו] [כְּיוֹנִ֖ים] sobre [מָ֑יִם] águas [בֶּֽחָלָ֔ב] [יֹשְׁב֖וֹת] [עַל־מִלֵּֽאת] sobre');
INSERT INTO verses VALUES (17681, 22, 5, 13, 'לְחַיָּו כַּעֲרֻגַת o abominável as alturas os espinhos suas bochechas as flores do campo os cachos o óleo passa');
INSERT INTO verses VALUES (17682, 22, 5, 14, 'suas-maos as circundâncias ouro cheios בת תרשׁיָשׁ מעיו עשׁת שֵׁן מעוללת ספירים');
INSERT INTO verses VALUES (17683, 22, 5, 15, '[שׁוֹקָיו֙] [עַמּ֣וּדֵי] seis [מְיֻסָּדִ֖ים] sobre [מַרְאֵ֙הוּ֙] [כַּלְּבָנ֔וֹן] [בָּח֖וּר] [כָּאֲרָזִֽים]');
INSERT INTO verses VALUES (17684, 22, 5, 16, '[חִכּוֹ֙] [מַֽמְתַקִּ֔ים] [וְכֻלּ֖וֹ] este [זֶ֤ה] [דוֹדִי֙] [וְזֶ֣ה] [רֵעִ֔י] Jerusalém');
INSERT INTO chapters VALUES (677, 22, 6, 12);
INSERT INTO verses VALUES (17685, 22, 6, 1, 'אָ֚נָה andar דּוֹדֵ֔ךְ a bela nas mulheres Aná Pana do teu amado e busquemos-o contigo');
INSERT INTO verses VALUES (17686, 22, 6, 2, 'meu amado ele-desceu para o seu jardim para as suas espinheiras o vergonhoso para pastorear nas jardins e para recolher flores-de-roseiro;');
INSERT INTO verses VALUES (17687, 22, 6, 3, 'eu meu amado e meu amado para-mim que pastorea nas flores-de-roseiro;');
INSERT INTO verses VALUES (17688, 22, 6, 4, 'bonita tu minha pastora כְּתִרְצָ֔ה נָאוָ֖ה כִּירוּשָׁלָ֑͏ִם אֲיֻמָּ֖ה כַּנִּדְגָּלֽוֹת׃');
INSERT INTO verses VALUES (17689, 22, 6, 5, 'הָסֵ֤בִּי עֵינַ֙יִךְ֙ מִנֶּגְדִּ֔י שֶׁ֥הֵ֖ם הִרְהִיבֻ֑נִי seu-cabelo cara-ruiva העיזים caminharam-pé de o-Gileade');
INSERT INTO verses VALUES (17690, 22, 6, 6, 'suas-mãos cara-ruiva tremularam-se subiram-na de lavou-a todos-estes ferventes e toda não neles');
INSERT INTO verses VALUES (17691, 22, 6, 7, 'campo Harmom seu prazer por detrás de para a tua beleza:');
INSERT INTO verses VALUES (17692, 22, 6, 8, 'sessenta eles ushmonim concubinas e almas não Mispar');
INSERT INTO verses VALUES (17693, 22, 6, 9, 'uma ela meu jardim minha beleza uma ela para-a-mãe -virgem ela por-ter-nascido-a e-viram-a -filhas e-abenraram-na -rainhas ופילגשים e-cantaram-na:');
INSERT INTO verses VALUES (17694, 22, 6, 10, 'quem esta -a-que-foi-revelada como -o-dia bela calvá bará chámá ayúmá canágdólot');
INSERT INTO verses VALUES (17695, 22, 6, 11, 'a ginná egoz para-ver para-ver b''ivvé para-ver para-ver hafará hagáfên henetsú הָרִמֹּנִֽים׃');
INSERT INTO verses VALUES (17696, 22, 6, 12, 'não soube [נַפְשִׁ֣י] [שָׂמַ֔תְנִי] [מַרְכְּב֖וֹת] [עַמִּי־נָדִֽיב]');
INSERT INTO chapters VALUES (678, 22, 7, 14);
INSERT INTO verses VALUES (17697, 22, 7, 1, '[שׁ֤וּבִי] [שׁ֙וּבִי֙] [הַשּׁ֣וּלַמִּ֔ית] [שׁ֥וּבִי] volta [וְנֶחֱזֶה־בָּ֑ךְ] [מַֽה־תֶּחֱזוּ֙] que [כִּמְחֹלַ֖ת] [הַֽמַּחֲנָֽיִם]');
INSERT INTO verses VALUES (17698, 22, 7, 2, 'que- [פְעָמַ֛יִךְ] [בַּנְּעָלִ֖ים] [בַּת־נָדִ֑יב] filha-de [יְרֵכַ֔יִךְ] [כְּמ֣וֹ] [חֲלָאִ֔ים] [מַעֲשֵׂ֖ה] [יְדֵ֥י] obra-de mãos-de');
INSERT INTO verses VALUES (17699, 22, 7, 3, '[שָׁרְרֵךְ֙] [אַגַּ֣ן] [הַסַּ֔הַר] a [הַמָּ֑זֶג] [בִּטְנֵךְ֙] [עֲרֵמַ֣ת] [חִטִּ֔ים] [סוּגָ֖ה] [בַּשּׁוֹשַׁנִּֽים]');
INSERT INTO verses VALUES (17700, 22, 7, 4, 'segundo [שָׁדַ֛יִךְ] [כִּשְׁנֵ֥י] [עֳפָרִ֖ים] [תָּאֳמֵ֥י] [צְבִיָּֽה]');
INSERT INTO verses VALUES (17701, 22, 7, 5, '[צַוָּארֵ֖ךְ] [כְּמִגְדַּ֣ל] [הַשֵּׁ֑ן] olhos-teus [בְּרֵכ֣וֹת] [בְּחֶשְׁבּ֗וֹן] sobre [בַּת־רַבִּ֔ים] filha-de muitos [הַלְּבָנ֔וֹן] [צוֹפֶ֖ה] face-de [דַמָּֽשֶׂק] face-de');
INSERT INTO verses VALUES (17702, 22, 7, 6, '[רֹאשֵׁ֤ךְ] sobre-ti [כַּכַּרְמֶ֔ל] [וְדַלַּ֥ת] [רֹאשֵׁ֖ךְ] [כָּאַרְגָּמָ֑ן] rei [אָס֥וּר] [בָּרְהָטִֽים]');
INSERT INTO verses VALUES (17703, 22, 7, 7, 'que- [וּמַה־נָּעַ֔מְתְּ] e-que [בַּתַּֽעֲנוּגִֽים]');
INSERT INTO verses VALUES (17704, 22, 7, 8, 'esta קומתך֙ דמתָ֣ה לתמר VASDAYICH para-ashkolot:');
INSERT INTO verses VALUES (17705, 22, 7, 9, 'dissesse e-ele em-tamar que-achaza em-sansinai e-serão- por-favor seus-seadyikh como-ashkolot hagáfên e-reich teu-apexek como-tapuchim:');
INSERT INTO verses VALUES (17706, 22, 7, 10, 'e-bico como-óleo o-bom הלך para-meu-amado para-linhas-retas dobre bocas dormem;');
INSERT INTO verses VALUES (17707, 22, 7, 11, 'eu para-meu-amado e-sobre-mim sua-desejo;');
INSERT INTO verses VALUES (17708, 22, 7, 12, 'לְכָ֤ה meu-amado sair-ei o-campo נָלִ֖ינָה בַּכְּפָרִֽים׃');
INSERT INTO verses VALUES (17709, 22, 7, 13, 'נַשְׁכִּ֙ימָה֙ לַכְּרָמִ֔ים נִרְאֶ֞ה פָּֽרְחָ֤ה הַגֶּ֙פֶן֙ פִּתַּ֣ח הַסְּמָדַ֔ר הֵנֵ֖צוּ הָרִמּוֹנִים nome אֶתֵּ֥ן a meu-dedo para-ti');
INSERT INTO verses VALUES (17710, 22, 7, 14, '[הַֽדּוּדָאִ֣ים] [נָֽתְנוּ־רֵ֗יחַ] [וְעַל־פְּתָחֵ֙ינוּ֙] e-sobre [חֲדָשִׁ֖ים] todo [דּוֹדִ֖י] [צָפַ֥נְתִּי] para-ti para-ti');
INSERT INTO chapters VALUES (679, 22, 8, 14);
INSERT INTO verses VALUES (17711, 22, 8, 1, 'quem יתןך כאח para-mim jonake Shaddai mim-i אמצاك בַחוּץ֙ ESHakka também não יובזו para-mim');
INSERT INTO verses VALUES (17712, 22, 8, 2, 'ENGagakh ABIakha a casa AMI TALAMDENI aschakkâ meyyayîn hărekakh me''assîs rimmônî');
INSERT INTO verses VALUES (17713, 22, 8, 3, 'šômê''ôlō debaixo roshi vî''imyînô tăchabqêni');
INSERT INTO verses VALUES (17714, 22, 8, 4, 'hisbâ''itti vós filhas-de Jerusalém que- tă''îrû וּֽמַה־ תְּעֹֽרְר֛וּ até הָאַהֲבָ֖ה até שֶׁתֶּחְפָּֽץ׃');
INSERT INTO verses VALUES (17715, 22, 8, 5, 'quem esta ʿōlāh de o-deserto מִתְרַפֶּ֖קֶת debaixo דּוֹדָ֑הּ em-lugar-de הַתַּפּ֙וּחַ֙ עֽוֹרַרְתִּ֔יךָ שָׁ֚מָּה חִבְּלַ֣תְךָ a-teua-mãe para lá חִבְּלָ֥ה יְלָדַֽתְךָ׃');
INSERT INTO verses VALUES (17716, 22, 8, 6, '[שִׂימֵ֨נִי] [כַֽחוֹתָ֜ם] sobre [כַּֽחוֹתָם֙] [עַל־זְרוֹעֶ֔ךָ] sobre [כַמָּ֙וֶת֙] porque [קָשָׁ֥ה] [כִשְׁא֖וֹל] [קִנְאָ֑ה] dura [רִשְׁפֵּ֕י] [אֵ֖שׁ] [שַׁלְהֶ֥בֶתְיָֽה] fogo');
INSERT INTO verses VALUES (17717, 22, 8, 7, 'águas [רַבִּ֗ים] não [יֽוּכְלוּ֙] [לְכַבּ֣וֹת] a [וּנְהָר֖וֹת] não não [אִם־יִתֵּ֨ן] se [אֶת־כָּל־ה֤וֹן] homem a todo [יָב֥וּזוּ] a-ele a-ele');
INSERT INTO verses VALUES (17718, 22, 8, 8, '[אָח֥וֹת] a-nós [קְטַנָּ֔ה] [וְשָׁדַ֖יִם] não-há para ela que [לַאֲחֹתֵ֔נוּ] no-dia [שֶׁיְּדֻבַּר־בָּֽהּ]');
INSERT INTO verses VALUES (17719, 22, 8, 9, 'se [הִ֔יא] ela [עָלֶ֖יהָ] sobre-ela [כָּ֑סֶף] prata e-se [נָצ֥וּר] ela [ל֥וּחַ] sobre-ela');
INSERT INTO verses VALUES (17720, 22, 8, 10, 'eu חוֹמָה וְשָׁדַי כְּמִגְדָּלוֹת então era em-seus-olhos כְּמֹצְאֵת paz');
INSERT INTO verses VALUES (17721, 22, 8, 11, '[כֶּ֣רֶם] ser para-Salomão em-Baal [הָמ֔וֹן] dar a [לַנֹּטְרִ֑ים] [אִ֛ישׁ] homem [בְּפִרְי֖וֹ] [אֶ֥לֶף] mil');
INSERT INTO verses VALUES (17722, 22, 8, 12, '[כַּרְמִ֥י[t]] diante-de-mim [לְפָנָ֑י] para-ti a-ti [שְׁלֹמֹ֔ה] [וּמָאתַ֖יִם] a [אֶת־פִּרְיֽוֹ]');
INSERT INTO verses VALUES (17723, 22, 8, 13, '[הַיוֹשֶׁ֣בֶת] [בַּגַּנִּ֗ים] [חֲבֵרִ֛ים] [מַקְשִׁיבִ֥ים] [לְקוֹלֵ֖ךְ] [הַשְׁמִיעִֽינִי]');
INSERT INTO verses VALUES (17724, 22, 8, 14, '[בְּרַ֣ח] [׀] [דּוֹדִ֗י] para-ti [לִצְבִי֙] ou [לְעֹ֣פֶר] [הָֽאַיָּלִ֔ים] sobre montes-de [בְשָׂמִֽים]');
INSERT INTO books VALUES (23, 'ISA', 'Isaías', 'AT', 66);
INSERT INTO chapters VALUES (680, 23, 1, 31);
INSERT INTO verses VALUES (17725, 23, 1, 1, 'visão-esta Isaías filho-de Amots que חָזָ֔ה sobre יְהוּדָה e-Ierusalim nos-dias-de Ozias Jotam Acaz Ezequias מַלְכֵ֥י Judá');
INSERT INTO verses VALUES (17726, 23, 1, 2, 'ouvi céus e-a-ouvi-me terra que yhwh palavra filhos grande-fiz-eu e-exaltei-eu e-eles transgrediram בי׃');
INSERT INTO verses VALUES (17727, 23, 1, 3, 'saber שור
INSERT INTO verses VALUES (17728, 23, 1, 4, 'ai nação pecador povo pesado pecado descendência semente filhos destruidores abandonaram a yhwh serão apertados a santo Israel se-isolaram atrás');
INSERT INTO verses VALUES (17729, 23, 1, 5, 'sobre מֶה vocês-se-tornarão mais toseifu סָרָה todo cabeça para-o-mal e-todo coração dói');
INSERT INTO verses VALUES (17730, 23, 1, 6, 'de-a-palma- do-pé e-até cabeça não há nele-o perfeita ferida e-curativo e-golpe de-ferida-nova não zoru e-não foram-curados e-não embrulhada com-o óleo');
INSERT INTO verses VALUES (17731, 23, 1, 7, 'erctchem sem semear cidades-vossas queimadas fogo terra-vossa diante-vos זרעים comendo a-ela e-desoladas como-inversão זָרִֽים׃');
INSERT INTO verses VALUES (17732, 23, 1, 8, 'e-permanece filha-de Sião tenda em-a-vinha como-alojamento em-o-carvalho como-cidade fortaleza');
INSERT INTO verses VALUES (17733, 23, 1, 9, 'Se fosse yhwh exércitos deixasse nós sairíamos um pouco como Sodoma fôssemos para Amora seríamos');
INSERT INTO verses VALUES (17734, 23, 1, 10, 'ouvi palavra-de yhwh oficiais-de Sodoma haazinu torat Elohim-nosso povo עֲמֹרָֽה׃');
INSERT INTO verses VALUES (17735, 23, 1, 11, 'por-que para-mim multidão-de yhwh diga yhwh savathti holocaustos אֵילִ֖ים e-gordura de-guillemots e-o-sangue de-toros não e-atos não afeiçô-me');
INSERT INTO verses VALUES (17736, 23, 1, 12, 'que vireis para-o-ver face-de quem esta esta de-vosso esmigalai do-cortiço-meu');
INSERT INTO verses VALUES (17737, 23, 1, 13, 'não acrescentais trazei oferta-de שָׁ֔וְא fumegante abominação ela para-mim novo e-sabáth chamou mi-qrá não posso iniquidade ve-a-tsáráh');
INSERT INTO verses VALUES (17738, 23, 1, 14, 'cha-dshei-chém u-mo-adheichém sán-áh nafshi foram sobre-mim la-tóra-h נִלְאֵ֖יתִי né-sha''');
INSERT INTO verses VALUES (17739, 23, 1, 15, 'ubfarischem ka-ppeichém a-alim e-olhos de-vós também porque tavru tefilah אֵינֶ֣נִּי ouviu suas mãos sangue maleu');
INSERT INTO verses VALUES (17740, 23, 1, 16, 'lavai-vos purificai-vos tirai mau as vossas iniquidades desde-em-frente-de meus-olhos desapeguem-se o mal');
INSERT INTO verses VALUES (17741, 23, 1, 17, 'limdu faze-bo-a busca-i juízo abençoa-e oprimi-o juiza-i órfão litiga-i אלמנוה');
INSERT INTO verses VALUES (17742, 23, 1, 18, 'לכו- por-favor e-se-faca-a yhwh yhwh se seja-ei vossos-pequenos como-ano-s como-neve e-tornar-branco-os se e-fazer-vermelho-os como-tecelagem como-lã ser-ão');
INSERT INTO verses VALUES (17743, 23, 1, 19, 'se e-querer-vos e-ouvir-vos a-terra a-terra comereis-vos');
INSERT INTO verses VALUES (17744, 23, 1, 20, 'e-se e-desdenhar-vos espada chēreb que porque yhwh yhwh palavra');
INSERT INTO verses VALUES (17745, 23, 1, 21, 'eiyka era para-adúltera קִרְיָה fiel-a cheia-de מִשְׁפָּ֗ט justiça yalin nela e-agora de-matar-homens');
INSERT INTO verses VALUES (17746, 23, 1, 22, 'o-teu-argentum ser para-os-esquivos os-teus-sabedores o-circunciso com-a-água');
INSERT INTO verses VALUES (17747, 23, 1, 23, 'os-teus-príncipes os-apostatados e-os-amigos de-los-ladinos todos-ele amou suborno e-o-perseguidor paz-aos órfão-o não julgar-ão e-dispute viúva não virá para-eles');
INSERT INTO verses VALUES (17748, 23, 1, 24, 'portanto oráculo-de o-senhor-o yhwh exércitos forte-o Israel ah! eu-consolarei de-Egito e-eu-vingarei-me de-inimigos-meu');
INSERT INTO verses VALUES (17749, 23, 1, 25, 'e-eu-devolverei mão-minha sobre-ti e-eu-acumularei com-ouro exílios-teus e-eu-guardarei todo em-fundição-teu');
INSERT INTO verses VALUES (17750, 23, 1, 26, 'e-eu-voltarei os-teus-julgadores como-no-primeiro e-os-teus-conselheiros como-no-início depois-de será-chamada para-ti para-ti cidade a-justiça קִרְיָה fiel');
INSERT INTO verses VALUES (17751, 23, 1, 27, 'Sião במשפט serás-redimida e-seus-retornados bitzedakah');
INSERT INTO verses VALUES (17752, 23, 1, 28, 'e-fragmento perversos e-perversores juntos e-abandonadores-de yhwh cessarão');
INSERT INTO verses VALUES (17753, 23, 1, 29, 'que enruborizar-se-ão de-a-senhores que desejastes e-vos-cavareis de-as-hortas que escolhestes');
INSERT INTO verses VALUES (17754, 23, 1, 30, 'que ser-vós como-ela novidade sobre-a e-como-horta que águas não a-ela');
INSERT INTO verses VALUES (17755, 23, 1, 31, 'e-era a-guarda para-a-adolescente e-seu-trabalho para-brilho e-eles-queimaram os-dois juntos e-não-há que-atinge');
INSERT INTO chapters VALUES (681, 23, 2, 22);
INSERT INTO verses VALUES (17756, 23, 2, 1, 'a-palavra que חָזָ֔ה Yeshayahu filho-de Amots sobre יְהוּדָה Jerusalém:');
INSERT INTO verses VALUES (17757, 23, 2, 2, 'e-era no fundo os-dias será-correto será será casa-de yhwh na-cabeça as montanhas e-será-elevado de-cabeças e-fluirão a-ele todo os-gentios');
INSERT INTO verses VALUES (17758, 23, 2, 3, 'e marchem povos muitos e disseram venham e subamos a monte-de yhwh a casa Elohim-de Jacó e ensinemos seus caminhos que em-suas-camininhos porque de-sua-cimeira saia torá e-palavra-de yhwh de-juerusalém');
INSERT INTO verses VALUES (17759, 23, 2, 4, 'e-julgou entre as-nações e-repreenderá aos-povos muitos e-gravaram suas-espadas para-tempo e-lances-deles para-cantares não yisa nação espada nação espada e-não aprendam mais guerra');
INSERT INTO verses VALUES (17760, 23, 2, 5, 'casa Jacó para-voces-andem e-n-e-l-c-h-a com-luz yhwh');
INSERT INTO verses VALUES (17761, 23, 2, 6, 'que ela-estendeu seu-people casa Jacó que encheram ao-oriente e-nascentes como-filisteus e-com-filhos estrangeiros derramarão');
INSERT INTO verses VALUES (17762, 23, 2, 7, 'e-cheia-se terra-o prata e-ouro e-não-há extremidade para-os-ses-trezuros e-cheia-se terra-o cavaleiros e-não-há extremidade para-as-seus-carros');
INSERT INTO verses VALUES (17763, 23, 2, 8, 'e-encheu-se terra-dele elohim-falsos para-o-trabalho de-suas-mãos se-inclinarão para aquele fizeram de-seus-dedos');
INSERT INTO verses VALUES (17764, 23, 2, 9, 'e-ele-se-inclinou homem e-ele-abateu-se homem a-eles carregará para-eles');
INSERT INTO verses VALUES (17765, 23, 2, 10, 'trazer na-rocha e-escondê-lo no-pó de-diante-de medo yhwh e de-hadar ge''on');
INSERT INTO verses VALUES (17766, 23, 2, 11, 'os-olhos-de gav''ut homem shaf''al e shach ru''m homens e nis''gab yhwh sozinho no-dia a-aquela');
INSERT INTO verses VALUES (17767, 23, 2, 12, 'que dia la-Yahweh exércitos sobre todo geéa va-ram e-sobre todo nisá shafeál');
INSERT INTO verses VALUES (17768, 23, 2, 13, 'e-sobre todo arzē'' halbānōn haramīm vehanissśā''im e-sobre todo allone'' habbāshān׃');
INSERT INTO verses VALUES (17769, 23, 2, 14, 'e-sobre todo os-montes as-altas e-sobre todo as-colinas as-elevadas-');
INSERT INTO verses VALUES (17770, 23, 2, 15, 'e-sobre todo torre-de alta-a e-sobre todo muralha em-forma-verso');
INSERT INTO verses VALUES (17771, 23, 2, 16, 'e-sobre todo navios  Tarshis  e-sobre todo escunas a-preciosa-verso');
INSERT INTO verses VALUES (17772, 23, 2, 17, 'e-baixo altura o-homem e-alto elevado homens e-elevar-se yhwh sozinho no-dia a-aquela');
INSERT INTO verses VALUES (17773, 23, 2, 18, 'e-os-idólatras inteiro trocar-');
INSERT INTO verses VALUES (17774, 23, 2, 19, 'e-vieram em-o-cavernas de-a-pedras e-em-as-escadas pó de-diante-de terror yhwh e-de-a-glória de-seu-poder em-sua-levantamento para-o-terrorizar a-terra');
INSERT INTO verses VALUES (17775, 23, 2, 20, 'no-dia o-aquele ele-jogará o-homem את elohim seu dinheiro e-a elohim seu ouro que eles-fizeram- para-ele para-o-adorar para-escavar frutos e-aos-ratos');
INSERT INTO verses VALUES (17776, 23, 2, 21, 'para-vir nas-entranhas das-rochas e-nos-galhos dos-pedregulhos de-diante-de terror yhwh e-do-esplendor de-seu-poder em-a-sua-levantação para-o-terrorizar a-terra');
INSERT INTO verses VALUES (17777, 23, 2, 22, 'cessai a-vós de o-homem que alma em-seu-nariz porque ele foi-contado ela');
INSERT INTO chapters VALUES (682, 23, 3, 26);
INSERT INTO verses VALUES (17778, 23, 3, 1, 'que eis o-senhores yhwh exércitos levou de- Jerusalém e-de-Juda maśʿēn u-mašʿēnā todo mišʿan- e-tudo e-todo mišʿan- águas');
INSERT INTO verses VALUES (17779, 23, 3, 2, 'poderoso e-homem guerra shoferet ve-nabi'' ve-qōse''m ve-zāqen');
INSERT INTO verses VALUES (17780, 23, 3, 3, 'príncipe-de cinquenta unessu''ă face ve-yōʿets e sábio Charashim e discernir para escutar:');
INSERT INTO verses VALUES (17781, 23, 3, 4, 'e-darei jovens seus-príncipes e-perversidades Yimshelu- neles:');
INSERT INTO verses VALUES (17782, 23, 3, 5, 'e se aproximou o-povo homem em-homem e-homem do seu amigo rirabu o-menino bazzaqen vehannikle banikkab');
INSERT INTO verses VALUES (17783, 23, 3, 6, 'porque yitpors homem ba''achi seu-pai pai-dele simla vai katzin será- lana debaixo a-esta debaixo-de yadcha');
INSERT INTO verses VALUES (17784, 23, 3, 7, 'eleva-se no-dia aquele para-dizer dizendo serei costureiro e-na-casa-meu não pão e-não roupa-ornamentada não me-fazes oficial povo');
INSERT INTO verses VALUES (17785, 23, 3, 8, 'que caída Jerusalém e-Juda caiu porque de-seu-língua e-elohim-sua-obra a yhwh para-o-contra de-seu-olho da-sua-glória');
INSERT INTO verses VALUES (17786, 23, 3, 9, 'a-corte suas-faces: respondeu contra-eles e sua oferta de culpa Kesedom higido não kichedu ai lenafsham porque a-eles a-eles raa');
INSERT INTO verses VALUES (17787, 23, 3, 10, 'imru justo porque bom porque peri maalehem yocheleu');
INSERT INTO verses VALUES (17788, 23, 3, 11, 'אוי lerasha mal porque fruto mãos-dele para-ele para-ele');
INSERT INTO verses VALUES (17789, 23, 3, 12, 'meu-povo seus-opressores inexperiente e-mulheres domaram nele meu-povo te-bem-aventuram enganadores e-caminho caminhos-teus devoram-vos');
INSERT INTO verses VALUES (17790, 23, 3, 13, 'estava de pé láriv yhwh וְעֹמֵ֖ד para julgar nations;');
INSERT INTO verses VALUES (17791, 23, 3, 14, 'yhwh במשפט virá com anciãos-de amav e-seus-senhores e-vós purificareis o-vinhedo de-a-roubada do-pobre em-vossas-casas');
INSERT INTO verses VALUES (17792, 23, 3, 15, 'oprimireis povo-meu e-faces-de os-pobres tirchanu oráculo-de Adonai yhwh exércitos');
INSERT INTO verses VALUES (17793, 23, 3, 16, 'E-disse yhwh porque que e-alçai-vos filhas-de Sião e-andastes e-vaselino e-vociferastes olhos הלוך e tamboril vai andando e com seus pés vibrou');
INSERT INTO verses VALUES (17794, 23, 3, 17, 'e trombeta Adonai e corneta filhas-de Sião E Yahweh abrirão YE''AREH:');
INSERT INTO verses VALUES (17795, 23, 3, 18, 'no-dia o-aquele ya-sir Adonai com te-fe-ret ha-achas-im ve-ha-shevis-im ve-ha-shaharon-im');
INSERT INTO verses VALUES (17796, 23, 3, 19, 'as-ninfetas e-as-cantigas e-os-escarnecimentos');
INSERT INTO verses VALUES (17797, 23, 3, 20, 'os-flores e-as-passoas e-os-conexoes e-casas-as a-alma e-os-sussurros');
INSERT INTO verses VALUES (17798, 23, 3, 21, 'as-anelos e-as-aliancas o-nariz');
INSERT INTO verses VALUES (17799, 23, 3, 22, 'as aberturas e as penachos: e as abas e as chăritím:');
INSERT INTO verses VALUES (17800, 23, 3, 23, 'e-hag-gilyonim e-has-sadinim e-hatzniphoth e-har-redidim');
INSERT INTO verses VALUES (17801, 23, 3, 24, 'e-será sub boshem măq será e sub cinta nikpáh e-baixo Masháv cofre cicatriz e-baixo fátil cinta perna porque baixo beleza');
INSERT INTO verses VALUES (17802, 23, 3, 25, 'me-tayikh com-a-espada cairão e-teu-poder na-guerra');
INSERT INTO verses VALUES (17803, 23, 3, 26, 'e-nos-lamentaremos e-faremos-moito-luto suas-portas e-será-purificada para-a-terra תֵּשֵֽׁב׃');
INSERT INTO chapters VALUES (683, 23, 4, 6);
INSERT INTO verses VALUES (17804, 23, 4, 1, 'e-se-estabelecerão sete mulheres em-cada-homem um no-dia o-aquele dizendo o-nosso-pão comeremos e-a-nossa-roupa n-ilbash somente será-chamada שִׁמְךָ sobre-nós e-sof che-refatenu');
INSERT INTO verses VALUES (17805, 23, 4, 2, 'no-dia aquele será צֶ֣מַח yhwh לִצְבִ֖י e para glória e fruto a-terra para orgulho e para beleza para redenção Israel');
INSERT INTO verses VALUES (17806, 23, 4, 3, 'e-era ha-nish-ar be-tziyon e-o-restante em-Jerusalém santo será-dito para-ele a-ele o khatuv para-a-vida em-Jerusalém');
INSERT INTO verses VALUES (17807, 23, 4, 4, 'se lavou-se Adonai את de-excremento  בְּנוֹת־  Sião e-a sangues-de Jerusalém vomitará de-o-interior-dele pelo-vento juízo וּבְר֥וּחַ no-erê');
INSERT INTO verses VALUES (17808, 23, 4, 5, 'e-fará yhwh sobre todo um-lugar monte-de Tsion e-sobre mikra-eha an-an yomam ve-ashan venogah noite que noite porque sobre todo kavod chupah');
INSERT INTO verses VALUES (17809, 23, 4, 6, 'vesukkah será letzel- de-dia do-calor e-para-esconderijo e-para-secreto do-tempo e-da-chuva');
INSERT INTO chapters VALUES (684, 23, 5, 30);
INSERT INTO verses VALUES (17810, 23, 5, 1, 'eu-cantarei agora para-o-amigo-meu canto-de do-meu-amado para-o-carmo כֶּ֛רֶם ser para-amigo-seu em-querne filho-de azeite');
INSERT INTO verses VALUES (17811, 23, 5, 2, 'e-ele-fortaleceu-o e-ele-apedrejou-o e-ele-plantou-o sorok E-edificou torre em-interior-dele e-também lagar cavado nele e-ele-esperou para-fazer uvas E-fez em-os-baixios-verso');
INSERT INTO verses VALUES (17812, 23, 5, 3, 'e-agora habitante Jerusalém e-homem Judá shiftu- na'' e-entre e-entre karmi');
INSERT INTO verses VALUES (17813, 23, 5, 4, 'que- para-fazer ainda para-o-vinhedo-dele e-não fiz nele por-que eu-esperado para-fazer uvas E-fez em-os-baixios-verso');
INSERT INTO verses VALUES (17814, 23, 5, 5, 'e-agora odeia- agora a-vós objeto-direto que eu fez para-o-carmi haseir de-sua-miséria e-foi para-a-destruição rompe seu-muro e-acontecerá para a mira');
INSERT INTO verses VALUES (17815, 23, 5, 6, 'e dar-lhe-ei batah não yizmareh e-não yeader e-subirá shamir vasit e-sobre he-avim atzaveh me-hametir sobre-ele chuva:');
INSERT INTO verses VALUES (17816, 23, 5, 7, 'que כרם yhwh dos-exércitos casa Israel e-homem Judá plantei- sua-auxiliares- e-pregou- para-julgamento- e-eis margens- para-a-direita- e-eis gritos:');
INSERT INTO verses VALUES (17817, 23, 5, 8, 'ah chegando casa em-casa campo no-campo eles-oferecerão até mas lugar e-vocês-serão-estabelecidos para-vos em-meio-de a-terra');
INSERT INTO verses VALUES (17818, 23, 5, 9, 'em-o-ouvido-me yhwh exércitos se não casas רַבִּים para-a יִֽהְי֔וּ grandes e-boas sem morador:');
INSERT INTO verses VALUES (17819, 23, 5, 10, 'que dez parelha-de- כרם farão filha-da um e-semente argila ele-fará eifa:');
INSERT INTO verses VALUES (17820, 23, 5, 11, 'הָוֵי mashchimei baboroqer shechar yirdrofu meacharei na-noite vinho yardliqueim:');
INSERT INTO verses VALUES (17821, 23, 5, 12, 'e-será kinor venevel tof e-hifil e-vayin de-sua-bebida e-a trabalho yhwh não eles-viram e-o-seu-trabalho mãos-dele não viram-;');
INSERT INTO verses VALUES (17822, 23, 5, 13, 'por-isso revelou-se povo-meu SEM דָ֑עַת e-sua-glória mortos רָעָ֔ב e-seu-tesouro grito fome');
INSERT INTO verses VALUES (17823, 23, 5, 14, 'portanto estendeu-a sepulcro alma-sua e-abriu-a boca-seu para-mim- חֹ֑ק e-desceu gloria-sua e-riqueza-seu e-grito-seu e-se-alegrar nela');
INSERT INTO verses VALUES (17824, 23, 5, 15, 'e-ele-se-curvou homem e-ele-se-abateu- homem וְעֵינֵ֥י os-altos vocês-se-abaterão');
INSERT INTO verses VALUES (17825, 23, 5, 16, 'e-ele-se-alçou yhwh de-exércitos pelo juízo e-o-elohim o-santo foi-consagrado bitzedakah');
INSERT INTO verses VALUES (17826, 23, 5, 17, 'e-malvaverão de-cordeiros conforme-eles e-destruições de-água moradores comerão');
INSERT INTO verses VALUES (17827, 23, 5, 18, 'Ai que-puxam o-enganoso pelos-cordões da-vaidade e-que-enganam a-carroça erro');
INSERT INTO verses VALUES (17828, 23, 5, 19, 'os-dizendo se-apressar-se vai-fracassando de-sua-obras para-que se-aparecerá e-você-se-achegará e-você-virá-a conselho-de santo Israel e-será-conhecido-verso');
INSERT INTO verses VALUES (17829, 23, 5, 20, 'oh הָאֹמְרִ֥ים para-o-mal bom e-para-o-bem mal céus escuridão para a luz e-luz para-a-escuridão céus amargo para-o-doce e-doce para-o-amargo');
INSERT INTO verses VALUES (17830, 23, 5, 21, 'הוי sábios em-olhos-deles e-diante-de faces-deles nabonim');
INSERT INTO verses VALUES (17831, 23, 5, 22, 'hoy gibborim lishthoth vinho e-para-os valor [שֵׁכָֽר] e se cobriram;');
INSERT INTO verses VALUES (17832, 23, 5, 23, 'matzdikei rasha ekev shochad ve-tsdaqath justos eles-virão nós');
INSERT INTO verses VALUES (17833, 23, 5, 24, 'por-isto como-comer erva-seca língua-de fogo e-gritaria para-chamas ele-escapará sharsham como-campo será e-florirá como-poeira subia que desdenharam את lei-de-a yhwh exércitos e-a palavra-de-a santo- Israel nietzu');
INSERT INTO verses VALUES (17834, 23, 5, 25, 'sobre assim ira-se também yhwh sua-mão e-ele-esticou mão-de-o sobre-ele e-golpeou-o e-tremeluziram os-montes e-foi carcaças-eles como-suspiro em-meio-de fora-as em-todo esta sua-mão retornou naso-seu e-mais mão-dele virada-a');
INSERT INTO verses VALUES (17835, 23, 5, 26, 'e-elevar-se nes para-as-nações de-longe a-ele para-ele a-terra a-terra e-eis rápido leve-o virá:');
INSERT INTO verses VALUES (17836, 23, 5, 27, 'não-há cansado-o e-não-há não nele não dorme-o e-não descanse-o e-não abre-se-o cinto sua-mola e-não se-partiu enrolado-o seus-calçados-o');
INSERT INTO verses VALUES (17837, 23, 5, 28, 'que suas-setas es-polidos e-todo de-sus-tas de-pressões partes os-cavaleiros como-a-tensão foram-contados e-as-suas-voltas como-a-senhora');
INSERT INTO verses VALUES (17838, 23, 5, 29, 'grito a-ele cães-vadios jovens-leões e-arrasarão vé-yo-achez te''ref e-espalhará e-não-há matsil');
INSERT INTO verses VALUES (17839, 23, 5, 30, 'e-arrasarão sobre-ele no-dia o-aquele de-o-cheiro-de mar e-voltará-se para-a-terra e-eis- escuridão angústia-de e-luz escuridão em-a-alta-ela');
INSERT INTO chapters VALUES (685, 23, 6, 13);
INSERT INTO verses VALUES (17840, 23, 6, 1, 'no ano de mortos o-rei Ozias e-eu-vi a Adonai habitou sobre trono-de alto e-foi-alçado e-seus-lados cheios a o-templo');
INSERT INTO verses VALUES (17841, 23, 6, 2, 'serafins estando-de-pé de-acima a-ele a-ele as-as-aspasas-penas seis como asas para um em-dois cobrirá פָנָ֗יו e-em-dois cobrirá pés-dele em-dois voará');
INSERT INTO verses VALUES (17842, 23, 6, 3, 'e-chamará este a este e ele disse: santo santo santo yhwh exércitos enchei todo a-terra כְּבוֹדֽוֹ׃');
INSERT INTO verses VALUES (17843, 23, 6, 4, 'e-ele-se-moveram côvados os-sifim de voz o-qore e-o-bayit irá asahn');
INSERT INTO verses VALUES (17844, 23, 6, 5, 'e-disse Ó! a-mim que ndmeti porque eu tame- sfatayim eu eu com que lábios-de-duas yhwh habitante porque a o-rei yhwh de-exércitos rau עֵינָֽי׃');
INSERT INTO verses VALUES (17845, 23, 6, 6, 've-yawaf a-mim um de as ardentes e-em-a-sua-mão ritzfa tomou de-cima-de de-sobre o-altar');
INSERT INTO verses VALUES (17846, 23, 6, 7, 'e-toque sobre E-disse eis tocar toque este sobre de-tuas-bocas e-se-apartará teu-perversidade e-teu-pecado ser-perdoado');
INSERT INTO verses VALUES (17847, 23, 6, 8, 'e-eu-ouvi a voz Adonai disse a quem eu-enviarei e-quem andará- para-nós e-disse eis-me envia-me');
INSERT INTO verses VALUES (17848, 23, 6, 9, 'E-disse vai e-dirás ao-povo esta ouvi ouvido e-a entendereis e-vi o-viu e-a voces-sabereis');
INSERT INTO verses VALUES (17849, 23, 6, 10, 'a-gras coração-de o-povo esta e-su-as-orelhas o-pesado e-seus-o-olhos a-sombra para-que-não ele-vera em-suas-olhos e-em-suas-orelhas ouvir-á e-o-seu-coração entenderá a-ele e-curará a-ele');
INSERT INTO verses VALUES (17850, 23, 6, 11, 'e-eu-disse até até-quando E-disse até até que se šā''ū ʿārîm mêʾēn yōšēb homem mêʾēn homem וְהָאֲדָמָ tîšā''eh šəmāmah');
INSERT INTO verses VALUES (17851, 23, 6, 12, 'e-se-apartará yhwh a o-homem e multiplicarei a-deserta a-terra a-terra');
INSERT INTO verses VALUES (17852, 23, 6, 13, 'e mais nela as-sar-yah ve-shav-ah e-será le-ba-eer ka-el-ah ve-ka-al-on que be-shal-le-chet má-ter contra-eles semente santidade mat-sav-tah');
INSERT INTO chapters VALUES (686, 23, 7, 25);
INSERT INTO verses VALUES (17853, 23, 7, 1, 'e-houve em-dias-de a-cha-z filho-de yo-tam filho-de עזיהוּ subir Judá subiu ret-sin rei-de אֲ֠רָם e-abriu filho-de Rmalyahu rei-de Israel Jerusalém para-a-guerra sobre-ela e-não pode para-lutar sobre-ela');
INSERT INTO verses VALUES (17854, 23, 7, 2, 'e-lhe-foi-dito לְבֵ֤ית Davi dizendo nacha Arã sobre Efraim vayanan levavoh ullevab povo-seu kunoa madeiras-de floresta que espírito');
INSERT INTO verses VALUES (17855, 23, 7, 3, 'E-disse yhwh a Yeshayahu sai- por-favor tu apaz- tu e-restante-de ele-voltará be-nos-teu a extre-mo e-le-vas-teu ha-brer-ka ha-ele-yona a de-ca-da-va-dor campo-de ko-ves');
INSERT INTO verses VALUES (17856, 23, 7, 4, 'e-dirás a-ele es-ta-ja-te e-se-quen-te a te-te-mos-te e-cor-a-teu a jerech mishnei zanvot ha-udim ha-asnim estas com-seu-escolhido af Rezin e Aram e-filho-de Remaljahu');
INSERT INTO verses VALUES (17857, 23, 7, 5, 'porque porque yaatz sobre-te Arã maldade Efraim dizendo Remaljahu para-dizer');
INSERT INTO verses VALUES (17858, 23, 7, 6, 'naaleh em Juda e-nos-levantaremos e-nos-partiremos a-nós e-mo-reinaremos rei dentro dela a filho-de tabal-:');
INSERT INTO verses VALUES (17859, 23, 7, 7, 'assim disse Adonai yhwh não tu-levantarás e-não serás');
INSERT INTO verses VALUES (17860, 23, 7, 8, 'que cabeça aram de-Damasco ve-rosh dam-mesheq retz-in u-ve-aod [שִׁשִּׁ֤ים] e cinco ano yechat Efraim me-am');
INSERT INTO verses VALUES (17861, 23, 7, 9, 've-rosh אֶפְרַיִם שֹׁמְר֔וֹן ve-rosh שֹׁמְר֖וֹן filho-de Rimalyahu não não que não não Teameunu');
INSERT INTO verses VALUES (17862, 23, 7, 10, 'vayosef yhwh palavra a dizendo para-dizer');
INSERT INTO verses VALUES (17863, 23, 7, 11, 'pergunta- para-ti sinal yhwh yhwh teu-Elohim haamek shealah ou hageheh para-cima');
INSERT INTO verses VALUES (17864, 23, 7, 12, 'E-disse achaz não eshal e-não anasseh a yhwh');
INSERT INTO verses VALUES (17865, 23, 7, 13, 'E-disse ouvi por-favor casa Davi o que é pequeno de-vós mostrará que porque também também a yhwh');
INSERT INTO verses VALUES (17866, 23, 7, 14, 'portanto dará Adonai ele a-vós sinal eis a virgem grávida e dará à luz filho e chamará seu-nome com nós El');
INSERT INTO verses VALUES (17867, 23, 7, 15, 'a-ira u''dvash ele-comerá para-sua-conhecimento desdenha do-mal e-escolhido em-o-bom');
INSERT INTO verses VALUES (17868, 23, 7, 16, 'que antes-de conheceu o-jovem desdenha do-mal e-escolher em-o-bom você-sairá a-terra que tu fim de-diante-de segundo de-seus-reis');
INSERT INTO verses VALUES (17869, 23, 7, 17, 'יביא yhwh sobre-ti e-sobre povo-teu e-sobre casa seu-pai dias que não de-cima-de para-do-dia vai-te Efraim de-sobre Judá a rei Aššúrā');
INSERT INTO verses VALUES (17870, 23, 7, 18, 'e-era em-o-dia no-dia soprará yhwh yhwh que em-extremidade-de rios Egito e-a-abelha-da que em-terra-de Aššúrā');
INSERT INTO verses VALUES (17871, 23, 7, 19, 'e-entraram e-nahu todos-eles no-nachalê as-batôt e-nikiquei os-sela''im e-em-todo as-na''ătsutsim e-em-todo os-nahalolim:');
INSERT INTO verses VALUES (17872, 23, 7, 20, 'no-dia הַהוּא rasgará Adonai com-a-tesoura a-contratação em-evrei rio com-o-rei Assur a a-cabeça e-cabelo os-pés e-também a o-vieiro cortará');
INSERT INTO verses VALUES (17873, 23, 7, 21, 'e-foi no-dia o-aquele viverá- homem novilha-de manhã e-dois- ovelhas-.');
INSERT INTO verses VALUES (17874, 23, 7, 22, 'e-foi de-muitos fazer leite comer-á ira porque ira e mel comerá todo a-terra em-meio-de a-terra');
INSERT INTO verses VALUES (17875, 23, 7, 23, 'e-foi no-dia aquele será todo lugar que ele-será- nome mil גֶּ֖פֶן em-milhar prata será e-para-o-touro será');
INSERT INTO verses VALUES (17876, 23, 7, 24, 'com-setas e-com-arco virá para-lá porque שָׁמַר e-touro serás todo a-terra');
INSERT INTO verses VALUES (17877, 23, 7, 25, 'e-tudo das-montanhas que na-mangueira sejam-depurados não vai ali temor-de safira e-sai-yit e-foi para-enviar boi e-para-esmolar ovelha');
INSERT INTO chapters VALUES (687, 23, 8, 23);
INSERT INTO verses VALUES (17878, 23, 8, 1, 'E-disse yhwh a-mim toma a-ti placa-de-papel grande e-escrive sobre-ele com-giz Enos para-pressa despojo silencio menos;');
INSERT INTO verses VALUES (17879, 23, 8, 2, 'ואעידנה a-mim testemunhas fiel-mente a Uriah o-sacerdote e-a זְכַרְיָ֖הוּ filho abençoe-Javé;');
INSERT INTO verses VALUES (17880, 23, 8, 3, 'e-eu-aproximei a a-profetisa e-concebeu filho E-disse yhwh yhwh a-mim chamou seu-nome apressa despojo chas baze');
INSERT INTO verses VALUES (17881, 23, 8, 4, 'que betereim conheceu o jovem chamou pai-meu veemi יִשָּׂ֣א ׀ a força de-a-damas e-את despojo שֹׁמְר֔וֹן diante-de rei Aššúrā');
INSERT INTO verses VALUES (17882, 23, 8, 5, 'e-continuou yhwh palavra a-mim ainda dizendo');
INSERT INTO verses VALUES (17883, 23, 8, 6, 'porque que maas o-povo este a águas-de hashiloach aqueles-vaiando umeshos a retzin e-filho-de Remaljahu');
INSERT INTO verses VALUES (17884, 23, 8, 7, 'velachen eis Adonai que-ele-leva sobre-eles a o-rio o-nahar haatzumim e-os-muitos a rei Assíria e-a todo glória-seu e-subiu sobre todo seus-ramificações e-andou sobre todo margens-dele');
INSERT INTO verses VALUES (17885, 23, 8, 8, 'e-passou em-Juda enxaguou e-passou até garganta chegue e-foi encostos de-asas-seu enchei largura-de terra-teu com-nos El');
INSERT INTO verses VALUES (17886, 23, 8, 9, 'pastoreiem אַמּוֹת e-temam-seu e-audiam todo de-longe terra vesti-vos e-vocem vistam-se e-vocem');
INSERT INTO verses VALUES (17887, 23, 8, 10, 'fortaleçam-se עֵצָ֖ה e-será-destruído falem palavra e-não ya''qum que com-nos El');
INSERT INTO verses VALUES (17888, 23, 8, 11, 'que assim disse yhwh para-mim com-a-força-de a-mão e-me-corrijam do-reino em-a-caminho o-povo- dizendo para-dizer');
INSERT INTO verses VALUES (17889, 23, 8, 12, 'não diguin a-todo para-todo que dirá o-povo este cinto e-a temor-seu não tirem e-não honrein-vos');
INSERT INTO verses VALUES (17890, 23, 8, 13, 'a yhwh ele a-ele consagrin e-ele temor-vos e-ele honrein-vos');
INSERT INTO verses VALUES (17891, 23, 8, 14, 'e-foi para-o-santuário e-a-pedra neguef e-a-rocha michshol para-dois-de beitos Israel לְפַ֣ח e-a-armadilha para-o-habitante Jerusalém');
INSERT INTO verses VALUES (17892, 23, 8, 15, 'e-cairão neles muitos e-cairam וְנִשְׁבָּ֔רוּ וְנוֹקְשׁ֖וּ e foram aprisionados:');
INSERT INTO verses VALUES (17893, 23, 8, 16, 'tzor testemunho-a escavado-o lei-a em-meus-estudos-vos');
INSERT INTO verses VALUES (17894, 23, 8, 17, 'e-esperarei-eu para-יהוה o-que-esconde-o sua-face de-casa-de Jacó e-esperarei-eu- a-ele');
INSERT INTO verses VALUES (17895, 23, 8, 18, 'eis eu e-os-meninos que dou- yhwh yhwh para-sinais e-para-maravilhas em-Israel yhwh yhwh exércitos o-habitante em-monte-de צִיּֽוֹן');
INSERT INTO verses VALUES (17896, 23, 8, 19, 'e-quando dirão vós mesmos busquem a as mães e-a os entendidos os que se acham em estado de zombaria e os que meditam porventura-não a-vida a seus elohimes busque por-causa-de E-disse a os mortos');
INSERT INTO verses VALUES (17897, 23, 8, 20, 'para-a-lei e-para-o-testemunho se não dirão como-dizer esta que não-há para-ele alvorde');
INSERT INTO verses VALUES (17898, 23, 8, 21, 'e passou nela נִקְשֶׁ֣ה e fome e-será porque será faminto e se despedaçará e será maldito em-seu-reino e-em-suas-elohim e-para para-cima');
INSERT INTO verses VALUES (17899, 23, 8, 22, 'e-a terra olhe e-eis tribulação e-obscuridade voando fome e-trevas expulso');
INSERT INTO verses VALUES (17900, 23, 8, 23, 'que não voando para-o-que fundido לָהּ֒ como tempo-de o-primeiro levou em-a-terra Zebulom e-a-terra Naftali e-o-ultimo pesou o-caminho-de o-mar alado o-Jordão circuncisao os-gentios');
INSERT INTO chapters VALUES (688, 23, 9, 20);
INSERT INTO verses VALUES (17901, 23, 9, 1, 'o-povo aqueles-que-andam na-escuridao Ra''u luz grande yosh''vei em-terra-de sombra-da-morte luz tocou sobre-eles');
INSERT INTO verses VALUES (17902, 23, 9, 2, 'multiplicaste a-nação elevaste-o a-alegria sejam-felizes em-te como-a-alegria na-colheita como-que se-rejubilem em-seu-dividir despojo');
INSERT INTO verses VALUES (17903, 23, 9, 3, 'que a sobre suportam-no e-את tribo-de ombro-seu shevet o-que-aproveita nele a-destruição como-no-dia de-Madian');
INSERT INTO verses VALUES (17904, 23, 9, 4, 'que todo de-seus só-en em-o-tremor e-a-roupa enrolada em-o-sangue e-será para-a-queimação de-comer אֵֽשׁ׃');
INSERT INTO verses VALUES (17905, 23, 9, 5, 'porque יֶ֣לֶד filho para-nos filho foi-dado- para-nós E-chamou a-misra sobre sichmo E-chamou semo פליאה conselheiro El valente Aviad príncipe-de paz');
INSERT INTO verses VALUES (17906, 23, 9, 6, '[*לם[c]*רבה] u-le-shalom não-há qets sobre kise Davi e-sobre seu-reino le-hachin a-ela u-le-saada-ah be-mishpat e-com-retidão me-at-ha e-até yhwh  קינאת yhwh de-exércitos farás- esta');
INSERT INTO verses VALUES (17907, 23, 9, 7, 'palavra enviou Adonai em-o-Ya''akov e-cairá em-Israel');
INSERT INTO verses VALUES (17908, 23, 9, 8, 'e-conhecem o-povo tudo-o Efraim e-estabelecido Samaria em-altivez e-em-grandeza coração dizendo');
INSERT INTO verses VALUES (17909, 23, 9, 9, 'para-tijolos caíram e-pedra será-construído carobas gudua va-arazim nachalif');
INSERT INTO verses VALUES (17910, 23, 9, 10, 'vayeshaggev yhwh a inimigos-de retzin sobre-ele e-a seus inimigos yesakech');
INSERT INTO verses VALUES (17911, 23, 9, 11, 'aram ao-oriente e-Philistines me-achor e-comeram a Israel em-todo boca em-todo esta sua-mão retornou naso-seu e-mais mão-dele virada-a');
INSERT INTO verses VALUES (17912, 23, 9, 12, 'e-o-povo não retornou até hammachehu não yhwh de-exércitos não e buscaram');
INSERT INTO verses VALUES (17913, 23, 9, 13, 'vayakhrete yhwh do Israel cabeça e-zanab ככף e-agmon dia um');
INSERT INTO verses VALUES (17914, 23, 9, 14, 'envelheceu e levantai- ele ele a-cabeça e profetizai- ele enganos ele a vara');
INSERT INTO verses VALUES (17915, 23, 9, 15, 'e-foram os benditos o-povo- este as provações e os seus bem-aventurados serão engolidos');
INSERT INTO verses VALUES (17916, 23, 9, 16, 'sobre assim sobre os-sua-juvenis não alegrar-se-ele Adonai não os-sua-viúvos que as-sua-juvenis-mulheres não ter-compaixão-ele porque toda-o-seu חָנֵ֣ף e-de-mal e-todo boca palavra sua-mão em-todo esta não retornou naso-seu e-mais mão-dele virada-a');
INSERT INTO verses VALUES (17917, 23, 9, 17, 'porque בָעֲרָ֤ה como fogo iniquidade amar comerás comerás e se curvou em pedaços a-floresta e choraram orgulho em cima');
INSERT INTO verses VALUES (17918, 23, 9, 18, 'em-a-lingua yhwh de-exércitos eles-ficaram-perplexos terra e-houve o-povo como-de-comer fogo homem a não não eles-tornar-se-terão-misericórdia');
INSERT INTO verses VALUES (17919, 23, 9, 19, 'e-ele-cortou sobre direita e-comeu ve-yochal sobre es-maol e-não sabe-u homem carne- zro-o yocheleu');
INSERT INTO verses VALUES (17920, 23, 9, 20, 'Manassés a Efrayim e-Efrayim a Manassés juntos eles sobre Judá em-todo sua-mão não retornou sua-mão e também mão-dele pendurados');
INSERT INTO chapters VALUES (689, 23, 10, 34);
INSERT INTO verses VALUES (17921, 23, 10, 1, 'ai os pedraços de-leis- iniquidade e os gravadores trabalho escreveram');
INSERT INTO verses VALUES (17922, 23, 10, 2, 'le-hattoth midin dalim [וְלִגְזֹ֕ל] juízo de-pobres meu-povo para-ser vi-viúvas o-spoils-deles e-a os-órfãos se-apropriarão');
INSERT INTO verses VALUES (17923, 23, 10, 3, 'umah- vocês-fazerão para-o-dia contagem e-para-perda [תָּב֑וֹא] vens sobre de-quem tens-eis lé''ezráh e-para-onde desamparareis gloria-vos-vos');
INSERT INTO verses VALUES (17924, 23, 10, 4, 'sem agachou-se debaixo a-sír ve-ta-xat feridos cairão em-todo esta não retornou sua-mão e-mais mão-dele virada-a');
INSERT INTO verses VALUES (17925, 23, 10, 5, 'ai Assíria tribo-de ira-meu e-bastao- ele em suas mãos zamí');
INSERT INTO verses VALUES (17926, 23, 10, 6, 'em-o-povo impio que-eu-o-enviarei e-sobre povo hebreu-tei e-eu-o-ordenarei para-destruir despojo e-para-espoliar em-desprezo fraude כּ-חו-מר chu-tsot');
INSERT INTO verses VALUES (17927, 23, 10, 7, 'e-ele não assim ele-será-como e-o-lvbo não que yachshov porque para-destruir bilvabo não nações não pouco');
INSERT INTO verses VALUES (17928, 23, 10, 8, 'que ele dirá não sara-i juntos Reis:');
INSERT INTO verses VALUES (17929, 23, 10, 9, 'não k-karkhmis kalno se não ke-arpad Chamath se não כְ-דאמָסֶק Samaria');
INSERT INTO verses VALUES (17930, 23, 10, 10, 'ka''asher matza minha-mão lemamlakhot ha-elil e-os-suspiros-deles מִירוּשׇׁלַם e-dos-de-Somron');
INSERT INTO verses VALUES (17931, 23, 10, 11, 'não como-que Eu fiz para Sefarom e para seus elohimes assim אֶעֱשֶׂ֥ה para Jerusalém e para suas imagens');
INSERT INTO verses VALUES (17932, 23, 10, 12, 'e-foi porque destruirá-ele Adonai a todo o-trabalho-dele em-monte-de Sião e-em-Jerusalém eu-servirei sobre fruto-de grandeza לְבַ֣ב rei-de Assur e-sobre esplendor-de altura os-seus-olhos');
INSERT INTO verses VALUES (17933, 23, 10, 13, 'que disse com-força mão-minha fiz e-com-sabedoria-meu que entendimento-meu e-eu-farei-cercar limites povos glória-meu e-ele-deriva como-grande moradores');
INSERT INTO verses VALUES (17934, 23, 10, 14, 'e-ela-encontrou como-ninho mão-minha para-exército os-povos e-como-coleto de-ovos abandonadas todo a-terra eu eu-coletei e-não ser exilado asa e-estendendo boca e-mordendo');
INSERT INTO verses VALUES (17935, 23, 10, 15, 'se-irá-gloriar-se a-serra sobre o-cortando nele se se-envergonhar-se-irá a-moinilhadora sobre e-alçando-o khanif שֵׁ֙בֶט֙ e-a merimav khariv matteh não עֵֽץ׃');
INSERT INTO verses VALUES (17936, 23, 10, 16, 'portanto yeshallach o-senhor yhwh exércitos bemishmannav razon vetachat khevodo yeqad yqod kikod אֵֽשׁ׃');
INSERT INTO verses VALUES (17937, 23, 10, 17, 'e-era luz- Israel para-o-fogo e-santo para-a-chama e na areia e come seu siho e seu mirto um um');
INSERT INTO verses VALUES (17938, 23, 10, 18, 'e glória o jardim e o carmelo de todo animal e-até carne o consumirá e-foi como um esfregão נֹסֵֽס׃');
INSERT INTO verses VALUES (17939, 23, 10, 19, 'e-restante-de árvore e-o-selva מִסְפָּ֣ר יִֽהְי֑וּ e-o-jovem ele-os-escreverá');
INSERT INTO verses VALUES (17940, 23, 10, 20, 'e-era em-o-dia no-dia não ele-acrescentará ainda o-restante Israel e-fuga casa-de Jacó para-se-apoiar sobre da maldição e-ele-se-apoiou sobre yhwh santo Israel com-verdade');
INSERT INTO verses VALUES (17941, 23, 10, 21, 'resto ישוב havia Jacó a El gibor');
INSERT INTO verses VALUES (17942, 23, 10, 22, 'que se será seu-povo Israel o-mar o-mar resto ele-voltará nele completo tricoteira lavando justiça');
INSERT INTO verses VALUES (17943, 23, 10, 23, 'que toda e-ele-foi-acamada Adonai yhwh exércitos fez em-meio-de todo a-terra');
INSERT INTO verses VALUES (17944, 23, 10, 24, 'portanto assim disse Adonai yhwh exércitos a tire-a povo-meu habitou Sião de-Assur com-o-bastão bate-a e-matáhu levanta-se- sobre-ti em-a-caminho Egito');
INSERT INTO verses VALUES (17945, 23, 10, 25, 'porque ainda pouco de-pequeno e a vil za''am e-minha-ira sobre você-formará-os');
INSERT INTO verses VALUES (17946, 23, 10, 26, 'e-acorda sobre-ele yhwh dos-exércitos chicote como-macção מִדְיָן em-telha corvo e-matá-lo sobre o-mar e-nosso-o em-a-caminho Egito');
INSERT INTO verses VALUES (17947, 23, 10, 27, 'e-era em-o-dia no-dia yasur sabalo de-sobre de-cima-de e ullo de-sobre de-cima-de e chubbal sobre por azeite');
INSERT INTO verses VALUES (17948, 23, 10, 28, 'veio sobre ayá passou em-migron para-o-mesmo colocará כּוֹלָיו׃');
INSERT INTO verses VALUES (17949, 23, 10, 29, 'passa-ram passagem גֶּ֖בַע hotel para-nós ansiedade a-alta colina-de emprestado tentou');
INSERT INTO verses VALUES (17950, 23, 10, 30, 'צַהֲלִ֥י teu-voz filha-de ondas o-ouvinte para-a-sheva pobreza respostas-dele');
INSERT INTO verses VALUES (17951, 23, 10, 31, 'vagou enfraquecida habitantes-de os-fortes eles-ousaram');
INSERT INTO verses VALUES (17952, 23, 10, 32, 'ainda o-dia בּ-נוֹב para-a-guarda ele-soprará sua-mão monte-de Sião colina-de Jerusalém');
INSERT INTO verses VALUES (17953, 23, 10, 33, 'eis o-senhor yhwh exércitos transportador pura em-o-ódio e-altos a-costa gastos e-os-altos cairão');
INSERT INTO verses VALUES (17954, 23, 10, 34, 'e-será-ferido símbolos-de o-erva em-o-barzil e-o-lvanon em-adir cairá-.');
INSERT INTO chapters VALUES (690, 23, 11, 16);
INSERT INTO verses VALUES (17955, 23, 11, 1, 'e-sairá galho-de de-gema Jesai [וְנֵ֖צֶר] de-seus-origens ele-dará-fruto-verso');
INSERT INTO verses VALUES (17956, 23, 11, 2, 'e-será-acolhido sobre-ele espírito yhwh espírito sabedoria e-com-entendimento espírito עֵצָה e poder espírito conhecimento e-temor-de yhwh');
INSERT INTO verses VALUES (17957, 23, 11, 3, 'e-o-cheiro em-temor yhwh e-não para-a-vista os-seus-olhos julgue e-não por-ouvido seus-ouvidos examinará:');
INSERT INTO verses VALUES (17958, 23, 11, 4, 'e-julgará em-justiça os-pobres וְהוֹכִ֥יחַ em-musicalidade para-humilhação-de terra e-golpeará- terra com-vara de-sua-boca וּבְר֥וּחַ suas-palavras matará perverso');
INSERT INTO verses VALUES (17959, 23, 11, 5, 'e-será justiça cinto seus joelhos e-a-fidelidade cinto calças-dele-verso');
INSERT INTO verses VALUES (17960, 23, 11, 6, 'e-gera lobo-menor com sujeitai e-namar com cordeiro se-apodera-seguramente e-bezerro e-leão-jovem e-avestruz juntos e-moço pequeno pastoreia em-eles');
INSERT INTO verses VALUES (17961, 23, 11, 7, 'e-vaca e-urso trar-einah juntos irbetsu יַלְדֵי-הֶן וְאַרְיֵה כּ-בָקָר יֹאכַל- palha');
INSERT INTO verses VALUES (17962, 23, 11, 8, 'וְשִׁעֲשַׁע יוֹנֵק sobre חֻ֣ר פָּ֑תֶן e-sobre luzeiros צִפְעוֹנִ֔י sua-mão mão-dele הָדָֽה׃');
INSERT INTO verses VALUES (17963, 23, 11, 9, 'não járe''u e-não yash chí''tu em-todo a-terra qad shi porque mála''á a-terra de''áh a yhwh kam mayim laiy am mikhasim');
INSERT INTO verses VALUES (17964, 23, 11, 10, 'e-foi no-dia aquele  שורשׁ jesaí que ficou-em-pé lens nações a-ele nações yidrosu e-será sua-quietude כבוד׃');
INSERT INTO verses VALUES (17965, 23, 11, 11, 'e-era em-o-dia no-dia ele-aumentará Adonai שֵׁנִית֙ mão-de-ele para-comprar sua-mão havia povo-seu que restará de-assiria e-de-misraim e-de-petros e-de-cush e-de-eilam e-de-shinar e-de-hamat e-de-a o-mar:');
INSERT INTO verses VALUES (17966, 23, 11, 12, 'e-levará milagre-o lagōyim e-recolherá exilados-os Israel e-spread-out-as Judá reunirá-o de-quatro-a כַּנְפ֥וֹת a-terra');
INSERT INTO verses VALUES (17967, 23, 11, 13, 'vesarah qin''at Efraim ve-tzorrey Judá serão cortados não fará inveja a Judá e-Judá não forjará a Efrayim');
INSERT INTO verses VALUES (17968, 23, 11, 14, 'e voarão em ombro filisteus será amarga juntos e se despedaçarão a filhos-de antes Edom e Moabe enviado a-mão-dele e-filhos-de Amom de-suas-ouvidos:');
INSERT INTO verses VALUES (17969, 23, 11, 15, 'e-o-que-eles-derreteram yhwh a língua-de mar- Egito sua-mão sua-mão sobre o-río em-espessura sua-ventura e-o-que-lhe-acertou sete rios e-dirigiu-o nas-ña-lí-im:');
INSERT INTO verses VALUES (17970, 23, 11, 16, 'e-será estrada para-o-restante povo-seu que Isaer de-Assur como-que era para-Israel em-dia elevação-o-seu de-terra-de Egito');
INSERT INTO chapters VALUES (691, 23, 12, 6);
INSERT INTO verses VALUES (17971, 23, 12, 1, 'e-dirás no-dia aquele od-kha-: yhwh que anaf-ta: em-mim habitou ap-ka: u-tancham-eni:');
INSERT INTO verses VALUES (17972, 23, 12, 2, 'eis El salvação-meu confiarei-eu e-não temerei-eu porque minha-forteza e-cantares-meu yhwh yhwh e-foi para-mim para-salvação');
INSERT INTO verses VALUES (17973, 23, 12, 3, 'e-levareis-vós águas em-o-sasson de-a-fontes da-salvação');
INSERT INTO verses VALUES (17974, 23, 12, 4, 'e-disseis no-dia aquele confessai para-יהוה chamai no-seu-nome anunciem aos-povos suas-atormentações hazquiru que nishgav nome-dele');
INSERT INTO verses VALUES (17975, 23, 12, 5, 'zamaru yhwh que geut fez esta em-todo esta');
INSERT INTO verses VALUES (17976, 23, 12, 6, 'צַהֲלִ֥י וָרֹ֖נִּי sentada Sião porque grande em-teu-interior santo Israel');
INSERT INTO chapters VALUES (692, 23, 13, 22);
INSERT INTO verses VALUES (17977, 23, 13, 1, 'Massá Babilônia que חָזָ֔ה יְשַׁעְיָ֖הוּ filho-de אָמֽוֹץ׃');
INSERT INTO verses VALUES (17978, 23, 13, 2, 'sobre monte-de נִשְׁפֶּה֙ שׂאו־ voz a-eles voz mão הָנִיפוּ mão וְיָבוֹאֻ ptchiei príncipes-');
INSERT INTO verses VALUES (17979, 23, 13, 3, 'eu tziviti limqudashai também קָרְאִי גִבּוֹרֵי לְאַפִי עַלּוֹזֵי גּאוֹווִי׃');
INSERT INTO verses VALUES (17980, 23, 13, 4, 'voz הָמֹון בְּהָרִים semelhança com voz voz שְׁא֞וֹן מַמְלְכ֤וֹת goyim yhwh yhwh exércitos מְפַקֵּ֖ד exército-de guerra');
INSERT INTO verses VALUES (17981, 23, 13, 5, 'בָּאִ֛ים de-terra-de מֶרְחָ֖ק do-extremo os-céus yhwh e-utensílios-de זַעְמ֔וֹ לְחַבֵּ֖ל todo a-terra');
INSERT INTO verses VALUES (17982, 23, 13, 6, 'הֵילִ֕ילוּ que קָר֖וֹב dia yhwh כְּשֹׁ֖ד de-mádi virá:');
INSERT INTO verses VALUES (17983, 23, 13, 7, 'sobre assim todo mãos serão-arrancadas e-todo coração Enos ele-morrerá:');
INSERT INTO verses VALUES (17984, 23, 13, 8, 'e-terrivelmente cordas e-cordas serão-pegos que-gera temer-se-ão homem a seu-amigo se-maravilhe face-de Leabim em-seus-faces');
INSERT INTO verses VALUES (17985, 23, 13, 9, 'eis yom- yhwh veio fértil e-feroz e-fogo af a-terra a-terra para-a-luz e-seus-pecados destruirá de-elas');
INSERT INTO verses VALUES (17986, 23, 13, 10, 'porque estrelas-dos os-céus não não יהֵילּוּ אורָם escuridão o-sol בְּצֵאת֔וֹ וְיָרֵ֖חַ não יַגִּ֥יהַ אוֹרֽוֹ׃');
INSERT INTO verses VALUES (17987, 23, 13, 11, 'וּפָקַדְתִּ֤י sobre תֵּבֵל֙ maldade e-sobre רְשָׁעִ֖ים עֲוֺנָ֑ם e habitar orgulho zedim e gavat aritzim asfil');
INSERT INTO verses VALUES (17988, 23, 13, 12, 'oqir Enos mifaz e adam micetem opir');
INSERT INTO verses VALUES (17989, 23, 13, 13, 'sobre assim céus ארגִּיז a-terra a-terra מִמּוֹקְמָהּ yhwh yhwh exércitos וּבְיוֹם חֲרֹן אַף׃');
INSERT INTO verses VALUES (17990, 23, 13, 14, 'e-foi כִּצְבִי מֻדָח וּכְצֹאן e-não-há מְקַבֵץ homem a עַמּוֹ יִפְנ֔וּ e-homem a terra-dele יָנֽוּסוּ׃');
INSERT INTO verses VALUES (17991, 23, 13, 15, 'todo הַנִּמְצָ֖א יִדָּקֵ֑ר e-todo הַנִּסְפֶּ֖ה יִפּ֥וֹל pela-espada');
INSERT INTO verses VALUES (17992, 23, 13, 16, 'וְעֹלְלֵיהֶ֥ם יְרֻטְּשׁ֖וּ לְעֵֽינֵיהֶ֑ם יִשַׁ֙סּוּ֙ בָּתֵּיהֶ֔ם וּנְשֵׁיהֶ֖ם');
INSERT INTO verses VALUES (17993, 23, 13, 17, 'הִנְנִ֛י de-cidade-de sobre-eles a מָדָ֑י não prata não não וְזָהָ֖ב não יַחְפְּצוּ־ nele-verso');
INSERT INTO verses VALUES (17994, 23, 13, 18, 'וּקְשָׁת֖וֹת נְעָרִ֣ים תְּרַטַּ֑שְׁנָה וּפְרִי־ não não הִרְחִימוּ sobre filhos não תָחוּס עֵינָם׃');
INSERT INTO verses VALUES (17995, 23, 13, 19, 'e-será בָבֶל֙ צְבִ֣י מַמְלָכ֔וֹת esplendor-de orgulho כַּשְׂדִּ֑ים כְּמַהְפֵּכַ֣ת Elohim a sodom e-a עֲמֹרָֽה׃');
INSERT INTO verses VALUES (17996, 23, 13, 20, 'não תֵשֵׁ֣ב para sempre e-não viverá até geração e geração e-não enxertará nome de areia e pastores não enxertarão nome');
INSERT INTO verses VALUES (17997, 23, 13, 21, 'e enxertar-se-ão nome cistos e-cheios em seus irmãos e habitaram nome filhas-de responderá e ovelhas saltarão nome');
INSERT INTO verses VALUES (17998, 23, 13, 22, 'e responderá rios em-suas-almenotas e dragões em seus palácios עֹנֶג וְקָר֤וֹב para-vir עִתָּ֔הּ וְיָמֶ֖יהָ não יִמָּשֵֽׁכוּ׃');
INSERT INTO chapters VALUES (693, 23, 14, 32);
INSERT INTO verses VALUES (17999, 23, 14, 1, 'que יְרַחֵ֨ם yhwh a Jacó וּבָחַ֥ר ainda em-Israel וְהִנִּיחָ֖ם sobre אַדְמָתָ֑ם וְנִלְוָ֤ה הַגֵּר֙ sobre-eles וְנִסְפְּח֖וּ sobre casa Jacó');
INSERT INTO verses VALUES (18000, 23, 14, 2, 'וּלְקָח֣וּם עַמִּים֮ וֶהֱבִיא֣וּם a מְקוֹמָם֒ וְהִֽתְנַחֲל֣וּם sobre Israel yhwh terra-de yhwh e-sejam וְלִשְׁפָח֑וֹת וְהָיוּ֙ שֹׁבִ֣ים para-os e-deram em-seus-cavos;');
INSERT INTO verses VALUES (18001, 23, 14, 3, 'e-foi no-dia deixou yhwh a-ti da-tua-obra e-do-teu-repugno e-de o-trabalho a-dura que trabalhaste- em-ti');
INSERT INTO verses VALUES (18002, 23, 14, 4, 'e-carregaste o parábola este sobre rei Babilônia e dirás como sabat passa sabat de ouro:');
INSERT INTO verses VALUES (18003, 23, 14, 5, 'quebrará yhwh tribo-de os ímpios shevet dominadores:');
INSERT INTO verses VALUES (18004, 23, 14, 6, 'o que castiga אַמּוֹת בְּעֵבֶרָה מַכַּת בִּלְתִּי סָרָה dominai בָּעַף nações מֻרְדָּף בְּלִי escuridão');
INSERT INTO verses VALUES (18005, 23, 14, 7, 'נָחָה שָׁקְטָה todo a-terra פָּצְח֖וּ rinah');
INSERT INTO verses VALUES (18006, 23, 14, 8, 'também בְּרוֹשִׁ֛ים a-ti a-ti אַרְזֵ֣י Líbano מֵאָ֣ז שָׁכַ֔בְתָּ não subirá הַכֹּרֵ֖ת sobre-nós');
INSERT INTO verses VALUES (18007, 23, 14, 9, 'שְׁא֗וֹל debaixo-de רָגְזָ֥ה a-ti ao-encontro-de בּוֹאֶ֑ךָ עָרֵר a-ti refaim todo עֲתֻדִּים terra הֵקִים todo reis-de גּוֹיִם׃');
INSERT INTO verses VALUES (18008, 23, 14, 10, 'כֻּלּם יַעַנוּ וְיוֹאמְרוּ a-ti também tu חֻלִּיתָ כַּמֽוֹנֵנוּ אֱלִיָּ֥נוּ foi simbolizada:');
INSERT INTO verses VALUES (18009, 23, 14, 11, 'ele aprofundou Sheol sua arrogância sua impudência seu desafio sob-te foi exposto Rimá e sua cobertura foi despojada:');
INSERT INTO verses VALUES (18010, 23, 14, 12, 'como נָפַ֥לְתָּ מִשָׁ֑מַ֖יִם הֵילֵ֣ל filho-de שָׁ֑חַר נִגְדַּ֣עְתָּ לָאָ֔רֶץ חוֹלֵ֖שׁ sobre goyim:');
INSERT INTO verses VALUES (18011, 23, 14, 13, 'e-tu אָמַ֤רְתָּ בִֽלְבָבְךָ֙ os-céus אֶֽעֱלֶ֔ה מִמַּ֥עַל לְכֽוֹכְבֵי־ El אָרִ֣ים trono-de-mim וְאֵשֵׁ֥ב em-monte-de encontro בְּיַרְכְּתֵ֥י צָפֽוֹן׃');
INSERT INTO verses VALUES (18012, 23, 14, 14, 'subirei sobre בָּ֣מֳתֵי עָ֑ב אֶדַּמֶּ֖ה לְעֶלְיֽוֹן׃');
INSERT INTO verses VALUES (18013, 23, 14, 15, 'Aquele a Sheol Turd a Jarktei בֽוֹר׃');
INSERT INTO verses VALUES (18014, 23, 14, 16, 'Roeycha a-ti Yashgiguy a-ti Yitbownanu Haze o-homem Margigz a-terra Mareish mمالكوت׃');
INSERT INTO verses VALUES (18015, 23, 14, 17, 'nome תבל כמדבר וארו הרס אסירים não פתח para-dentro');
INSERT INTO verses VALUES (18016, 23, 14, 18, 'todo reis-de גויים כלם שכבו בקבוד homem no seu lar:');
INSERT INTO verses VALUES (18017, 23, 14, 19, 'e-tu lançaste da tua sepultura como um cipreste foi abominável vestes-te feridos piercados espada descendentes a pedras-de- da cova כּ-פֶ-ר מ-וּ-בָ-ס׃');
INSERT INTO verses VALUES (18018, 23, 14, 20, 'não ת-הַד itam ב-קְבֻרָה porque אַרְצֶךָ֥ שִ-חַ-תָּ teu-povo ה-רָגְתָּ semente será-chamado para-o-tempo semente מְ-רֵעִים׃');
INSERT INTO verses VALUES (18019, 23, 14, 21, 'ה-כִ-ינוּ ל-בָ-נוֹי matevach ba''avon pais-deles não levantar-se-os veyarshu terra e-cheios penei- tevel arim:');
INSERT INTO verses VALUES (18020, 23, 14, 22, 'veqamti sobre-eles oráculo-de yhwh exércitos vehikrati lebabel nome e restante e nin e neced oráculo-de yhwh');
INSERT INTO verses VALUES (18021, 23, 14, 23, 'e samtiha para morash kipod e agmei- águas e teateitihah bematatea hashmed yhwh yhwh exércitos');
INSERT INTO verses VALUES (18022, 23, 14, 24, 'nisbáʿ yhwh de-exércitos dizendo se não como-que dimmiti assim hayata vekaʾasher yaʿatzti ela taqum');
INSERT INTO verses VALUES (18023, 23, 14, 25, 'lisbōr ʾaššur baʿarṣi e-sobre haray אֲבֻסֶ֑נּוּ וְסָ֤ר מֵֽעֲלֵיהֶם֙ עֻלּ֔וֹ de-cima-de de-sobre שִׁכְמ֖וֹ יָסֽוּר׃');
INSERT INTO verses VALUES (18024, 23, 14, 26, 'esta הָעֵצָ֥ה הַיְּעוּצָ֖ה sobre todo a-terra וְזֹ֛את הַיָּ֥ד a estendida sobre todo os-gentios');
INSERT INTO verses VALUES (18025, 23, 14, 27, 'porque yhwh exércitos o conselho e-quem cobrirá e a mão a estendida e quem ela se assentará');
INSERT INTO verses VALUES (18026, 23, 14, 28, 'no ano de morrer o-rei ser foi o dízimo a-esta');
INSERT INTO verses VALUES (18027, 23, 14, 29, 'a alegrar-te-ás  פלשת  que porque  נשבר  tribo-de  מכה  porque  משרש   נחש   יצא   צפע   ופרייו   שרף   מעופף');
INSERT INTO verses VALUES (18028, 23, 14, 30, 'וְרָעוּ֙ בֲּכוֹרֵ֣י דַלִּ֔ים וְאֶבְיוֹנִ֖ים לָבֶ֣טַח יִרְבָּ֑צוּ וְהֵמַתִּ֤י בָֽרָעָב֙ שָׁרְשֵׁ֔ךְ וּשְׁאֵרִיתֵ֖ךְ הרג׃');
INSERT INTO verses VALUES (18029, 23, 14, 31, 'הליליני שער צעקי- cidade Namog Filisteu que porque  Mitsafon Ashan veio e-não-há Boded בموADEיו׃');
INSERT INTO verses VALUES (18030, 23, 14, 32, 'umah- /responda que yhwh porque yhwh ele-estabeleceu Sião e nela será misericordioso os pobres povo-dele');
INSERT INTO chapters VALUES (694, 23, 15, 9);
INSERT INTO verses VALUES (18031, 23, 15, 1, 'profecia Moabe que na noite desolado cidade Moabe se desmoronou que na noite desolado  mural- Moabe  foi-');
INSERT INTO verses VALUES (18032, 23, 15, 2, 'subir הבית e Dibom as baamas -me sobre nebo e-sobre de Midiã Moabe jaleia em-todo -seus קָרְחָ֔ה todo velho גְּרוּעָֽה׃');
INSERT INTO verses VALUES (18033, 23, 15, 3, 'בְּחוּצֹתָ֖יו חָ֣גְרוּ שָׂ֑ק sobre גַּגּוֹתֶ֧יהָ וּבִרְחֹבֹתֶ֛יהָ כֻּלֹּ֥ה יְיֵלִ֖יל יֹרֵ֥ד בַּבֶּֽכִי׃');
INSERT INTO verses VALUES (18034, 23, 15, 4, 'וַתִּזְעַ֤ק Hesbom וְאֶלְעָלֵ֔ה até יַ֖הַץ ouviremos קוֹלָ֑ם sobre sim חֲלֻצֵ֤י Moabe יָרִ֔יעוּ para-ele יָ֥רְעָה para-ele');
INSERT INTO verses VALUES (18035, 23, 15, 5, 'coração-meu לְמוֹאָ֣ב יִזְעָ֔ק בְּרִיחֶהָ até צֹ֖עַר עֶגְלַ֣ת que que מַעֲלֵ֣ה הַלּוּחִ֗ית בִּבְכִי֙ יַֽעֲלֶה־ que o-caminho-de caminho חוֹרֹנַ֔יִם זַעֲקַת־ Sheber se-irão-iluminar');
INSERT INTO verses VALUES (18036, 23, 15, 6, 'porque águas-de נִמְרִים מְשַׁמּ֣וֹת יִֽהְי֑וּ porque יָבֵ֤שׁ חָצִיר֙ verde não ser não foi');
INSERT INTO verses VALUES (18037, 23, 15, 7, 'sobre assim יִתְרָ֣ה fez sobre sobre ribeiro-de הָעֲרָבִ֖ים יִשָׂאֽוּם׃');
INSERT INTO verses VALUES (18038, 23, 15, 8, 'porque הִקִּ֥יפָה הַזְּעָקָ֖ה a território Moabe até אֶגְלַ֙יִם֙ יִלְלָתָ֔הּ não אֵילִ֖ים יִלְלָתָֽהּ׃');
INSERT INTO verses VALUES (18039, 23, 15, 9, 'que águas-de דִימוֹן֙ מָ֣לְאוּ דָ֔ם porque אָשִׁ֥ית sobre דִּימ֖וֹן נוֹסָפ֑וֹת para-ajuda Moabe terra e-para-perpetuidade solo');
INSERT INTO chapters VALUES (695, 23, 16, 14);
INSERT INTO verses VALUES (18040, 23, 16, 1, 'enviaram- car dominador- terra do-pedregal da-deserto a o-montanha filha-de צִיּֽוֹן');
INSERT INTO verses VALUES (18041, 23, 16, 2, 'e-acontecerá como-pássaro- vagaroso- קֶן מְשׁוּלָ֑ח תִּהְיוּ filhas-de Moabe מַעֲבְרֹת לְאַרְנוֹן׃');
INSERT INTO verses VALUES (18042, 23, 16, 3, 'עֵצָה asu פְּלִילָה שִׁיתִי כַּלְיַל צִלָּךְ em-meio-de צָהֳרָיִם no-meio-de נִדָּחִים נֹדֵד a תְּגַלִּֽי׃');
INSERT INTO verses VALUES (18043, 23, 16, 4, 'יָג֤וּרוּ בָךְ֙ נִדָּחַ֔י Moabe הֱוִי־ segredo de-diante-de de-diante-de שׁוֹדֵ֑ד porque אָפֵ֤ס הַמֵּץ֙ terminou שֹׁ֔ד terminaram רֹמֵ֖ס de a-terra');
INSERT INTO verses VALUES (18044, 23, 16, 5, 'וְהוּכַ֤ן בַּחֶ֙סֶד֙ כִּסֵּ֔א וְיָשַׁ֥ב sobre-ele בֶּאֱמֶ֖ת em-tenda-de Davi שֹׁפֵ֛ט וְדֹרֵ֥שׁ juízo וּמְהִ֥ר צֶֽדֶק׃');
INSERT INTO verses VALUES (18045, 23, 16, 6, 'שָׁמַ֥עְנוּ גְאוֹן־ Moabe muito muito גַּאֲוָת֧וֹ וּגְאוֹנ֛וֹ וְעֶבְרָת֖וֹ não assim em-os-seus');
INSERT INTO verses VALUES (18046, 23, 16, 7, 'portanto יְיֵלִ֥יל Moabe le-moav כֻּלֹּ֣ה יְיֵלִ֑יל לַאֲשִׁישֵׁ֧י  mural- חֲרֶ֛שֶׂת תֶּהְגּ֖וּ somente- נְכָאִֽים׃');
INSERT INTO verses VALUES (18047, 23, 16, 8, 'que שַׁדְמוֹת֩ חֶשְׁבּ֨וֹן אֻמְלָ֜ל vinha שִׂבְמָ֗ה בַּעֲלֵ֤י nações hal''mu shur''kiyha até ya''zer nag''u ta''u מִדְבָּ֑ר shelu''chotiyha nittashu mar mar-');
INSERT INTO verses VALUES (18048, 23, 16, 9, 'sobre assim ebkhe bibki ya''zer vinha שִׂבְמָה אֲרַיוֹכֶק דִּימַעְתִּי חֶשְׁבּוֹן que porque sobre קֵיצֵךְ e-sobre קְצִירֵךְ הֵידָד נָפַל׃');
INSERT INTO verses VALUES (18049, 23, 16, 10, 'וְנֶאֱסַף שִׂמְחָה וָגִיל֙ de הַכַּרְמֶ֔ל וּבַכְּרָמִ֥ים não יְרֻנָּ֖ן não יְרֹעָ֑ע יַ֗יִן בַּיְקָבִ֛ים não יִדְרֹ֥ךְ הַדֹּרֵ֖ךְ הֵידָד hístabbiți:');
INSERT INTO verses VALUES (18050, 23, 16, 11, 'sobre assim me-ʻay para-Moabe kakkinnôr yehemû: ve-qirbî ləqîr ḥâreshôn:');
INSERT INTO verses VALUES (18051, 23, 16, 12, 've-hâyâ: porque nirʾâ: porque nilʾâ: Moabe sobre a báma e v''á a do santuário para-orar-se e-não pode');
INSERT INTO verses VALUES (18052, 23, 16, 13, 'este a-palavra que palavra yhwh a Moabe desde então');
INSERT INTO verses VALUES (18053, 23, 16, 14, 'e-agora palavra yhwh dizendo em três dois -dois aluguel e vendida glória-de Moabe em-todo o todo הָרָ֑ב e-restante-de מְעַ֛ט מִזְעָ֖ר não כַבִּֽיר׃');
INSERT INTO chapters VALUES (696, 23, 17, 14);
INSERT INTO verses VALUES (18054, 23, 17, 1, 'profecia דַּמָּ֑שֶׂק eis דַמֶּ֙שֶׂק֙ מוּסָ֣ר מֵעִ֔יר וְהָיְתָ֖ה מְעִ֥י מַפָּלָֽה׃');
INSERT INTO verses VALUES (18055, 23, 17, 2, 'עֲזֻב֖וֹת cidades-de עֲרֹעֵ֑ר לַעֲדָרִ֣ים תִּֽהְיֶ֔ינָה וְרָבְצ֖וּ e-não-há מחרד׃');
INSERT INTO verses VALUES (18056, 23, 17, 3, 'וְנִשְׁבַּ֤ת fortaleza מֵֽאֶפְרַ֔יִם וּמַמְלָכָ֥ה מִדַּמּ֖שֶׂק e-restante-de Arã כִּכְב֤וֹד filhos-de Israel יִֽהְי֔וּ yhwh yhwh exércitos');
INSERT INTO verses VALUES (18057, 23, 17, 4, 'e-foi no-dia aquele יִדַּ֖ל glória-de Jacó וּמִשְׁמַ֥ן a-carne-dele יֵרָזֶֽה׃');
INSERT INTO verses VALUES (18058, 23, 17, 5, 'e-foi כֶּֽאֱסֹף֙ קָצִ֣יר קָמָ֔ה וּזְרֹע֖וֹ שִׁבֳּלִ֣ים יִקְצ֑וֹר e será כִּמְלַקֵּ֥ט שִׁבֳּלִ֖ים na-vale refains');
INSERT INTO verses VALUES (18059, 23, 17, 6, 'וְנִשְׁאַר־ בוֹ עֽוֹלֵלֹת֙ כְּנֹ֣קֶף זַ֔יִת dois שְׁלֹשָׁ֛ה גַּרְגְּרִ֖ים na-cabeça quatro אַרְבָּעָ֣ה cinco em-suas-páginas seu-florido oráculo-de yhwh Elohim-de Israel');
INSERT INTO verses VALUES (18060, 23, 17, 7, 'no-dia aquele será-alegria o-homem sobre faz-lhe e-seus-olhos a santo Israel vireis');
INSERT INTO verses VALUES (18061, 23, 17, 8, 'e-não será-alegria a dos-melhoras-do-sacrifício obra-de mãos-dele e-que asau não não verá e-as-áris e-a-cham-ma-nim∶');
INSERT INTO verses VALUES (18062, 23, 17, 9, 'no-dia o-aquele serão ∞ cidades-de refúgio como-azuváta a-córes e-a-amir∶ que abandonaram de-diante-de de-diante-de Israel seria vazio∶');
INSERT INTO verses VALUES (18063, 23, 17, 10, 'que שָׁכַ֙חַתְּ֙ Elohim-de יִשְׁעֵ֔ךְ וְצ֥וּר מָעֻזֵּ֖ךְ não זָכָ֑רְתְּ sobre assim תִּטְּעִי֙ נִטְעֵ֣י נַעֲמָנִ֔ים וּזְמֹ֥רַת זָ֖ר serás-sown');
INSERT INTO verses VALUES (18064, 23, 17, 11, 'no-dia plantar-te-ás teshoshgegi e-no-manhã seu-sow tesperehi sede colheita em-dia herança e-dormente אנושׁ׃');
INSERT INTO verses VALUES (18065, 23, 17, 12, 'ah המון֙ povos muitos כַּהֲמ֥וֹת mares יֶהֱמָי֑וּן וּשְׁא֣וֹן לְאֻמִּ֔ים כִּשְׁא֛וֹן águas כַּבִּירִ֖ים יִשָּׁאֽוּן׃');
INSERT INTO verses VALUES (18066, 23, 17, 13, 'לְאֻמִּ֗ים כּישׁוא֞ון águas רַבִּים יִשׁוא֔וּן וְגָעַר nele וְנָס מִמּרְחָ֑ק וְרֻדַּף כּmothz os-montes diante-de espírito וּכְגַלְגַּal diante-de סֻףָ׃');
INSERT INTO verses VALUES (18067, 23, 17, 14, 'לְעֵ֥ת tarde e-eis בַlahah֔א בטרעם manhã איןנו este חֵ֣לֶק שוסיאנו וגוראל לbovezainu׃');
INSERT INTO chapters VALUES (697, 23, 18, 7);
INSERT INTO verses VALUES (18068, 23, 18, 1, 'hoi terra צלצל כנפיים que מעבר לנהרי־ כו什׃');
INSERT INTO verses VALUES (18069, 23, 18, 2, 'הַשֹׁלֵ֨חַ בַּיָּ֜ם צִירִ֗ים וּבִכְלֵי־ גֹמֶא֮ sobre face-de águas לַכ֣וּ ׀ מַלְאָכִ֣ים קַלִּ֗ים a nação מְמֻשָּׁ֣ךְ וּמוֹרָ֔ט a povo נורא de ele והלאה nação קָו־ קָו וּמְבוּסָה que בָּזְא֥וּ נְהָרִ֖ים terra-dele');
INSERT INTO verses VALUES (18070, 23, 18, 3, 'todo habitantes-de tevel וְשֹׁ֣כְנֵי terra כִּנְשֹׂא־ nes os-montes tiru ve-tiku''a corneta tishma''u');
INSERT INTO verses VALUES (18071, 23, 18, 4, 'que assim disse yhwh a-mim ve-abita bimkoni kechom צַח sobre luz כְּעָ֥ב טַ֖ל בְּחֹ֥ם colheita');
INSERT INTO verses VALUES (18072, 23, 18, 5, 'porque diante-de קָצִיר֙ כְּתָם־ פֶּ֔רַח será גֹּמֵ֖ל יִֽהְיֶ֣ה נִצָּ֑ה וְכָרַ֤ת הַזַּלְזַלִּים֙ בַּמַּזְמֵר֔וֹת e-a as-nétišot hésir hetaz');
INSERT INTO verses VALUES (18073, 23, 18, 6, 'ye''azbu yachdav le''et harim u-lebehemaht a-terra ve-katz sobre-ele ha''ayit e-todo a-terra a-terra sobre-ele תֶּחֱרָֽף׃');
INSERT INTO verses VALUES (18074, 23, 18, 7, 'בָּעֵת֩ הַהִ֨יא יֽוּבַל־ שַׁ֜י a-yhwh exércitos povo מְמֻשָּׁ֣ךְ וּמוֹרָ֔ט וּמֵעַ֥ם נורא de ele והלאה גוֹי קָו־ קָו וּמְבוּסָ֗ה que בָּזְא֤וּ נְהָרִים֙ אַרְצ֔וֹ a lugar nome-de yhwh de-exércitos monte-de צִיּֽוֹן');
INSERT INTO chapters VALUES (698, 23, 19, 25);
INSERT INTO verses VALUES (18075, 23, 19, 1, 'profecia Egito eis yhwh רֹכֵ֨ב sobre עָ֥ב קַל֙ וּבָ֣א Egito וְנָע֞וּ אֱלִילֵ֤י Egito מִפָּנָ֔יו וּלְבַ֥ב Egito יִמַּ֥ס em-o-centro-dele');
INSERT INTO verses VALUES (18076, 23, 19, 2, 'וְסִכְסַכְתִּ֤י Egito em-Egito וְנִלְחֲמ֥וּ homem-de בְּאָחִ֖יו e-homem בְּרֵעֵ֑הוּ cidade em-cidade na-moção em-na-moção:');
INSERT INTO verses VALUES (18077, 23, 19, 3, 'e-estéril espírito-de Egito em-meio-seu e-sua-conselhos mas-o e-procuraram a os-εlises e-a os-lentos e-a as-mães e-a הַיִּדְּעֹנִֽים׃');
INSERT INTO verses VALUES (18078, 23, 19, 4, 'e eu me exaltar a Egito na-mão-de adonaies dura e-melque forte dominará- contra-eles yhwh o senhor yhwh exércitos');
INSERT INTO verses VALUES (18079, 23, 19, 5, 'e se exaltarem águas do mar e o rio se despedaçará e seca-se');
INSERT INTO verses VALUES (18080, 23, 19, 6, 'e se espalhem rios se desviaram e se destruíram rios de cerco canha e Sufim se agitaram');
INSERT INTO verses VALUES (18081, 23, 19, 7, 'ערות sobre יאור sobre e-tudo יאור e-todo izrā'' יאור  yabash nippēph ve''ēnnū:');
INSERT INTO verses VALUES (18082, 23, 19, 8, 'v''ānu'' hadayyāgīm וְאָ֣בְל֔וּ todo מַשְׁלִיכֵ֥י בַיְא֖וֹר חַכָּ֑ה וּפֹרְשֵׂ֥י מִכְמֹ֛רֶת sobre face-de águas אֻמְלָֽלוּ׃');
INSERT INTO verses VALUES (18083, 23, 19, 9, 'וּבֹ֛שׁוּ עֹבְדֵ֥י פִשְׁתִּ֖ים שִׁרִיקֹת וְאֹרְגִים חֹרֵי׃');
INSERT INTO verses VALUES (18084, 23, 19, 10, 'e-sejam שַׁתֹּתֶיהָ מְדֻכָּאִים todo עֹשֵֵי שַׁכֶּר אַגְמֵי־ alma');
INSERT INTO verses VALUES (18085, 23, 19, 11, 'somente אֱוִילִים֙ שַׁרֵי צֹ֔עַן חַכְמֵי֙ יֹעֲצֵ֣י פַּרְעֹה עֵצָ֖ה נִבְעָרָ֑ה como תֹּאמְר֣וּ a Faraó filho-de חֲכָמִ֥ים eu filho-de מַלְכֵי־ adiante');
INSERT INTO verses VALUES (18086, 23, 19, 12, 'אַיָּם֙ אֵפ֣וֹא sábios-teus וְיַגִּ֥ידוּ por-favor para-ti וְיֵ֣דְע֔וּ que yhwh yhwh exércitos sobre Egito');
INSERT INTO verses VALUES (18087, 23, 19, 13, 'נֽוֹאֲלוּ֙ שַׁרֵי צֹ֔עַן נִשְּׁא֖וּ שַׁרֵי נֹ֑ף הִתְע֥וּ a Egito פִּנַּ֥ת seus-ramos:');
INSERT INTO verses VALUES (18088, 23, 19, 14, 'yhwh cobriu em-seu-interior espírito falsos e-enganaram a Egito em-todo seu-trabalho como-se-enganados cork sabia:');
INSERT INTO verses VALUES (18089, 23, 19, 15, 'e-não será para-Egito מעשה que יהעש cabeça וזנב ככף ואגמון');
INSERT INTO verses VALUES (18090, 23, 19, 16, 'no-dia aquele será Egito ככינים והרד ופחד mipnay de-diante-de mão-de yhwh exércitos que ele מניף sobre-ele');
INSERT INTO verses VALUES (18091, 23, 19, 17, 'והיהת אַדְמַת Judá לְמִצְרַ֙יִם֙ לְחָגָּ֔א todo que יַזְכִּ֥יר ela a-ele יִפְחַד de-diante-de עֲצַת yhwh exércitos que ele יוֹעֵץ sobre-ele');
INSERT INTO verses VALUES (18092, 23, 19, 18, 'no-dia הַהוּא יִהְיוּ cinco עָרִים na-terra Egito מדברות língua Canaã ונישבעות a-yhwh exércitos cidade ההרס יאמר para-uma');
INSERT INTO verses VALUES (18093, 23, 19, 19, 'no-dia aquele será um-altar a-yhwh no-meio-de terra Egito ומצבבה ;base- גבולה para-יהוה');
INSERT INTO verses VALUES (18094, 23, 19, 20, 'e-será לאות ולעד a-יהוה exércitos na-terra Egito porque יחclsquem de-diante-de yhwh de-diante-de a-eles e enviará a-eles salvador e abundante e livrará-os:');
INSERT INTO verses VALUES (18095, 23, 19, 21, 'e será conhecido yhwh para os egípcios e conhecerão Egito a no-dia no-dia aquele e servirão sacrifício-de e oferenda e jurarão— נֵ֥דֶר para-יהוה וְשִׁלֵּֽמוּ׃');
INSERT INTO verses VALUES (18096, 23, 19, 22, 'וְנָגַ֧ף yhwh a Egito נָגֹ֣ף וְרָפ֑וֹא וְשָׁ֙בוּ֙ até a-eles וְנֶעְתַּ֥ר a-eles וּרְפָאָֽם׃');
INSERT INTO verses VALUES (18097, 23, 19, 23, 'no-dia aquele תִּהְיֶ֨ה מְסִלָּ֤ה de-Egito Aššúrā e vêm- Aššúrā em-Egito e Egito- Aššúr e servirão- Egito a Aššúrā');
INSERT INTO verses VALUES (18098, 23, 19, 24, 'no-dia aquele será Israel Três-ésimo para-Egito Aššúr ברכה em-meio-de a-terra');
INSERT INTO verses VALUES (18099, 23, 19, 25, 'que ברך yhwh exércitos dizendo ברוך עמי Egito ומעשה ידי Assíria ונחלתי Israel');
INSERT INTO chapters VALUES (699, 23, 20, 6);
INSERT INTO verses VALUES (18100, 23, 20, 1, 'em-ano-de veio תרタン אסדודאה בישלו ele סרגון rei Assíria e lutou em Ashdod e tomou-a;');
INSERT INTO verses VALUES (18101, 23, 20, 2, 'em-o-tempo a aquela palavra yhwh na-mão-de Isaías filho-de dizendo dizendo vai e abraque de-cima-de de-sobre teus joelhos e teu calçado de-cima-de de-sobre teus pés E-fez assim nu ערום ויחף׃');
INSERT INTO verses VALUES (18102, 23, 20, 3, 'E-disse yhwh como andar עבדי יְשַׁעְיָ֖הוּ nu ויחף três dois אות ומופת sobre Egito e-sobre Cush');
INSERT INTO verses VALUES (18103, 23, 20, 4, 'assim ינוהג rei-de אשׁור a שביה Egito e-a גלות nu נערים וזקנים ערום ויחף וחשופאי Sete nudez-de Egito');
INSERT INTO verses VALUES (18104, 23, 20, 5, 'והתחו ובושו מק Cush מבבטם e-de Egito Tipheret');
INSERT INTO verses VALUES (18105, 23, 20, 6, 'e disse habitou ahi hazeh no-dia aquele eis assim nabatenu que nasnu nome de-diante-de para nos livrar de-diante-de rei Assíria e como nos livrarmos nós-verso');
INSERT INTO chapters VALUES (700, 23, 21, 17);
INSERT INTO verses VALUES (18106, 23, 21, 1, 'profecia no deserto- mar כּס֔וּפֹת בָּנָ֖גֶב לְחַלֹ֔ף מִן־הַמִּדְבָּ֣ר veio מֵאֶ֖רֶץ נוֹרָאָֽה׃');
INSERT INTO verses VALUES (18107, 23, 21, 2, 'חֲזוּת קְשָׁה הִגַּד־ a-mim הַבּוֹגֵ֤ד ׀ בּוֹגֵד֙ e o esfomeado esfomeado ali Eilãm meu rochedo meu fortaleza todo אַנְחָתָ֖ה hístabbiți:');
INSERT INTO verses VALUES (18108, 23, 21, 3, 'sobre assim מָלְא֤וּ מָתְנַי֙ חַלְחָלָ֔ה צִירִים אֲחָז֔וּנִי כְּצִירֵ֖י יֽוֹלֵדָ֑ה  נַעֲוֵ֣יתִי  מִשְּׁמֹ֔עַ נִבְהַ֖לְתִּי מֵרְאֽוֹת׃');
INSERT INTO verses VALUES (18109, 23, 21, 4, 'תָּעָ֣ה לְבָבִ֔י פל Utt בי עתתני a נשף חשקי nome a-mim לחרדah');
INSERT INTO verses VALUES (18110, 23, 21, 5, 'ערוך השלחן צפה הצפית אכול ela-bebeu levantem-se os-senhores מִשׁ֮ח֥וּ מָגֵ֗ן׃');
INSERT INTO verses VALUES (18111, 23, 21, 6, 'que assim disse a-mim Adonai vai הַעֲמֵ֣ד הַֽמְצַפּ֖ה que verá יַגִּֽיד׃');
INSERT INTO verses VALUES (18112, 23, 21, 7, 'וְרָ֣אָה רֶ֗כֶב צֶ֚מֶד פָּֽרָשִׁ֖ים carros-de חֲמ֥וֹר carros גּוֹמָל וְהִקְשִׁיב קֶשֶׂב chefe-de קָֽשֶׁב׃');
INSERT INTO verses VALUES (18113, 23, 21, 8, 'E-chamou leão sobre מִצְפֹּת Adonai eu ficou-em-pé contínuo diariamente e-sobre eu eu está-postado todo הַלָּיְלֹת׃');
INSERT INTO verses VALUES (18114, 23, 21, 9, 'e-eis este veio carros homem צֶמֶד פָּרַשִׂים E-disse E-disse caiu נָפְלוֹת Babilônia e-todo פְּסִילֵי אֱלֹהֶיהָ שִׁבְרָ para-a-terra');
INSERT INTO verses VALUES (18115, 23, 21, 10, 'מְדֻשָּׁתִי e-filho-de גַּרְנִי que ouvi yhwh yhwh exércitos Elohim-de Israel a-vós para-vocês');
INSERT INTO verses VALUES (18116, 23, 21, 11, 'profecia [דּוּמָ֑ה] a-mim chamou [מִשֵּׂעִ֔יר] [שֹׁמֵר֙] que [שֹׁמֵ֖ר] guardião');
INSERT INTO verses VALUES (18117, 23, 21, 12, 'disse [שֹׁמֵ֔ר] [אָתָ֥ה] manhã e-também noite se [שֻׁ֥בוּ] [אֵתָֽיוּ׃]');
INSERT INTO verses VALUES (18118, 23, 21, 13, 'profecia [בַּעְרָ֑ב] [בַּיַּ֤עַר] [בַּעְרַב֙] [תָּלִ֔ינוּ] [אֹֽרְח֖וֹת] [דְּדָנִֽים]');
INSERT INTO verses VALUES (18119, 23, 21, 14, 'para-encontro-de sede se fartaram águas yosh''vei terra diz-se em seu pão se levantaram vagabundo:');
INSERT INTO verses VALUES (18120, 23, 21, 15, 'porque de-faces-de desertos de-diante-de מפני espada abandonada e diante de קֶ֣שֶׁת perseguição e-por cobiда guerra');
INSERT INTO verses VALUES (18121, 23, 21, 16, 'porque disse disse Adonai a-mim enquanto ano -dois aluguel e-terminação todo yhwh Qedar:');
INSERT INTO verses VALUES (18122, 23, 21, 17, 'e-restante-de número de arco-íris homens valentes filhos-de que yhwh porque yhwh Elohim-de Israel palavra');
INSERT INTO chapters VALUES (701, 23, 22, 25);
INSERT INTO verses VALUES (18123, 23, 22, 1, 'profecia vale esperança que para-a אֵפוֹא porque עָלִית כּוֹלָךְ לַגּוֹגֹת׃');
INSERT INTO verses VALUES (18124, 23, 22, 2, '[תְּשֻׁא֣וֹת] [׀] cidade [עִ֚יר] [הֽוֹמִיָּ֔ה] [קִרְיָ֖ה] [עַלִּיזָ֑ה] não não espada e-não [מֵתֵ֥י] guerra');
INSERT INTO verses VALUES (18125, 23, 22, 3, 'todo os teus tesouros se moviam - יַחַד de arco foram aprisionados todo os teus presos foram aprisionados juntos de longe correram :');
INSERT INTO verses VALUES (18126, 23, 22, 4, 'sobre assim eu disse - acordem de-mi amarêr em-béki a [עַל־שֹׁ֖ד] para-nachamêni sobre [sem-traducao] filha-de povo-meu');
INSERT INTO verses VALUES (18127, 23, 22, 5, 'que dia mehúmah e-mebúsah e-mebúcah para-adonai yhwh exércitos no vale חזון מקרקר קיר וSHOWA a a-montanha');
INSERT INTO verses VALUES (18128, 23, 22, 6, 'וUILAM levou אשפה ברכב homem פRSAHIM וקיר ערה Magen:');
INSERT INTO verses VALUES (18129, 23, 22, 7, 'e-houve mibchār- ʿamāqayikh מָ֣לְאוּ rāḵeb ve-haferašim šōt šātu haššaʿarah:');
INSERT INTO verses VALUES (18130, 23, 22, 8, 'va-yegall a masak Judá e olhou no-dia aquele a amor casa a floresta:');
INSERT INTO verses VALUES (18131, 23, 22, 9, 'e-a por entre cidades- Davi e viram porque muitos-são e coletaram a ouro o-tanque a mais baixa');
INSERT INTO verses VALUES (18132, 23, 22, 10, 'e-a por entre Jerusalém e contaram e se separaram as-bat-tiym le-bats-er ha-choma');
INSERT INTO verses VALUES (18133, 23, 22, 11, 'u-miq-va asit-tem entre entre le-me ha-brer-ka ha-yesh-na e-não hibbat-tet-hem a os-eh-ka e criadora de longe não vêem:');
INSERT INTO verses VALUES (18134, 23, 22, 12, 'E-chamou Adonai yhwh exércitos no-dia aquele choro e lamento e arrasto e envolvo cinto:');
INSERT INTO verses VALUES (18135, 23, 22, 13, 'והנה florescência e alegria הרג manhã וְשַׁחֵֽט rebanho comer carne comer vinho אכל וְשָׁת֔וֹ porque מחר que');
INSERT INTO verses VALUES (18136, 23, 22, 14, '[וְנִגְלָ֥ה] [בְאָזְנָ֖י] yhwh exércitos se [הֶעָוֺ֨ן] [הַזֶּ֤ה] a-vós a-vós disse [Adonai] disse Adonai yhwh');
INSERT INTO verses VALUES (18137, 23, 22, 15, 'assim disse Adonai yhwh exércitos vai- veio a o socorrido este sobre que-não-está que sobre a-casa');
INSERT INTO verses VALUES (18138, 23, 22, 16, 'que a-você aqui a-ti a-ti aqui porque cavaste-te a-ti aqui sepultura meu-cavador alto sua-tumba meu-cavado a-ele arca a-ele');
INSERT INTO verses VALUES (18139, 23, 22, 17, 'eis yhwh tremulamente-te טַלְטֵלָ֖ה Geber וְעֹטְךָ֖ עָטֹֽה׃');
INSERT INTO verses VALUES (18140, 23, 22, 18, 'צָנ֤וֹף יִצְנָפְךָ֙ צְנֵפָ֔ה כַּדּ֕וּר a terra largura-de יָדָ֑יִם שָׁ֣מָּה תָמ֗וּת e-shamah markevot kavodecha kelon casa seus-mestres');
INSERT INTO verses VALUES (18141, 23, 22, 19, 'vahadpatich mimatzavecha umima''adecha yeheresecha');
INSERT INTO verses VALUES (18142, 23, 22, 20, 'e-foi no-dia aquele veqara''i leavadi לְאֶלְיָקִ֖ים filho-de חִלְקִיָּֽהוּ׃');
INSERT INTO verses VALUES (18143, 23, 22, 21, '[וְהִלְבַּשְׁתִּ֣יו] כּתּנְתֶךָ וְאַבְנֵֽטְךָ֙ אֲחַזְּקֶ֔נּוּ וּמֶֽמְשֶׁלְתְּךָ֖ darei na-sua-mão e-será לְאָ֛ב לְיוֹשֵׁ֥ב Jerusalém e-para-a-casa-de Judá');
INSERT INTO verses VALUES (18144, 23, 22, 22, 'e-darei [מַפְתֵּ֥חַ] casa-de Davi sobre [וְאֵ֣ין] [סֹגֵ֔ר] e-não-há [וְאֵ֥ין] [פֹּתֵֽחַ]');
INSERT INTO verses VALUES (18145, 23, 22, 23, 'וּתְקַעְתִּ֥יו יָתֵ֖ד em-o-loco נֶאֱמָ֑ן e será לְכִסֵּ֥א glória segundo-casa-de seu-pai');
INSERT INTO verses VALUES (18146, 23, 22, 24, 'וְתָל֨וּ sobre-ele todas glória-de casa-de pai-de-ele as-aceições e-as-cpafot todo utensílios-de o-pequeno de-vasos as-agannot e-até todo instrumentos-de os-nabalim');
INSERT INTO verses VALUES (18147, 23, 22, 25, 'no-dia aquele oráculo-de yhwh exércitos tumash o-yeved a-taquá em-o-loco neeman e será quebrada e cairá e será cortado הַמַּשָּׂ֣א que que yhwh yhwh palavra');
INSERT INTO chapters VALUES (702, 23, 23, 18);
INSERT INTO verses VALUES (18148, 23, 23, 1, 'profecia pedra clamaram navios tartaruga porque desolado de casa de entrada da-terra-de Quitim será revelado a-eles');
INSERT INTO verses VALUES (18149, 23, 23, 2, '[דֹּ֖מּוּ] [יֹ֣שְׁבֵי] [אִ֑י] [סֹחֵ֥ר] [צִיד֛וֹן] passando mar [מִלְאֽוּךְ]');
INSERT INTO verses VALUES (18150, 23, 23, 3, 'וּבְמַ֤יִם רַבִּים semente שִׁיחֹר ceifa-de יאור תְּבוּאָתָ֑הּ e-foi סְחַר goyim:');
INSERT INTO verses VALUES (18151, 23, 23, 4, 'בoshi Tsidon porque mar mar o-mar dizendo dizendo não chaltiti e-não yaladti e-não gidalti בחורים romamtiti betulot');
INSERT INTO verses VALUES (18152, 23, 23, 5, 'quando ouviu Lemitsrayim yachilu kashema צר׃');
INSERT INTO verses VALUES (18153, 23, 23, 6, 'transponham תרשִׁישָה הילִילוּ יוֹשְׁבֵי אי׃');
INSERT INTO verses VALUES (18154, 23, 23, 7, 'esta a-vós עלִיזָה מִימֵי־ קדֶם kadְמָתָהּ֙ יוֹבִיל֣וּהָ ragle-ha márākh lāgur');
INSERT INTO verses VALUES (18155, 23, 23, 8, 'quem ya''ats esta sobre Tiro hammā''ăṭīrāh que sochāryeha sārim kinnā''aneha nichbaddi terra');
INSERT INTO verses VALUES (18156, 23, 23, 9, 'yhwh exércitos yē''ătsāh ləḥallēl orgulho todo Tsévi lehaqel todo nicbadday- terra');
INSERT INTO verses VALUES (18157, 23, 23, 10, 'ivri arzeka kay''or filha-de tarshish não meza ainda');
INSERT INTO verses VALUES (18158, 23, 23, 11, 'sua-mão desviou sobre o-mar hirgazi yhwh yhwh ordenou a Canaã lashemad seu-abrigo');
INSERT INTO verses VALUES (18159, 23, 23, 12, 'E-disse não adiciona-te ainda ao-alegria a-moído virgem-a filha-de sidom arsta-te passa-te também nome para-ti descansa para-ti');
INSERT INTO verses VALUES (18160, 23, 23, 13, 'eis terra terra este o-povo não não ser sua-fundação para-cisnes elevaram acordaram seus-arranhões colocaram-na para-a-cala');
INSERT INTO verses VALUES (18161, 23, 23, 14, 'eles-ilegiram navios Tarshis que Shaddad seus-abrigos');
INSERT INTO verses VALUES (18162, 23, 23, 15, 'e-foi no-dia aquele e-se-ignorará Tiro setenta ano כִּימֵ֖י rei um מִקֵּ֞ץ שִׁבְעִ֤ים ano será לְצֹ֔ר כְּשִׁירַ֖ת הַזּוֹנָֽה׃');
INSERT INTO verses VALUES (18163, 23, 23, 16, '[קְחִ֥י] [כִנּ֛וֹר] [סֹ֥בִּי] cidade [זוֹנָ֣ה] [נִשְׁכָּחָ֑ה] [הֵיטִ֤יבִי] [נַגֵּן֙] [הַרְבִּי־שִׁ֔יר] [לְמַ֖עַן] para-que');
INSERT INTO verses VALUES (18164, 23, 23, 17, 'e-será מקץ ׀ setenta ano יפקד yhwh yhwh Sior ושבה לתנותנה e se deitou a a-terra reinos a-terra sobre face-de a-terra');
INSERT INTO verses VALUES (18165, 23, 23, 18, 'e-será sua e com ela santo a-yhwh não será reuniado e-não será consagrado que aos moradores diante-de yhwh será sua para-comer para satisfação e cobertura עָתִיק׃');
INSERT INTO chapters VALUES (703, 23, 24, 23);
INSERT INTO verses VALUES (18166, 23, 24, 1, 'eis yhwh [בּוֹקֵ֥ק] a-terra [וּבֽוֹלְקָ֑הּ] [וְעִוָּ֣ה] [פָנֶ֔יהָ] [וְהֵפִ֖יץ] [יֹשְׁבֶֽיהָ]');
INSERT INTO verses VALUES (18167, 23, 24, 2, 'e-será כָעָם֙ כַּכֹּהֵ֔ן כַּעֶ֙בֶד֙ como seu senhor como uma serva como uma donzela como um comprador como um vendedor como um empréstimo como uma dívida como uma esposa como o que é levado nele');
INSERT INTO verses VALUES (18168, 23, 24, 3, 'a raposa תִּבּ֛וֹק a-terra a-terra תִּבּ֑וֹז porque yhwh que yhwh a-palavra a-esta');
INSERT INTO verses VALUES (18169, 23, 24, 4, '[אָבְלָ֤ה] [נָֽבְלָה֙] a-terra [אֻמְלְלָ֥ה] [נָבְלָ֖ה] [תֵּבֵ֑ל] [אֻמְלָ֖לוּ] [מְר֥וֹם] com a-terra');
INSERT INTO verses VALUES (18170, 23, 24, 5, 'E-a-terra חָנְפָ֖ה debaixo os-sentados-a porque עָבְר֤וּ תּוֹרֹת חָלְפוּ חֹק הֵפֵרוּ eternidade eternidade');
INSERT INTO verses VALUES (18171, 23, 24, 6, 'sobre assim [אָ֣כְלָה] terra terra [יֹ֣שְׁבֵי] [בָ֑הּ] nela sobre assim terra [וְנִשְׁאַ֥ר] terra [מִזְעָֽר]');
INSERT INTO verses VALUES (18172, 23, 24, 7, '[אָבַ֥ל] [תִּיר֖וֹשׁ] [אֻמְלְלָה־גָ֑פֶן] [נֶאֶנְח֖וּ] [כָּל־שִׂמְחֵי־לֵֽב] todo coração');
INSERT INTO verses VALUES (18173, 23, 24, 8, 'cessou [מְשׂ֣וֹשׂ] [תֻּפִּ֔ים] [חָדַ֖ל] [שְׁא֣וֹן] [עַלִּיזִ֑ים] [שָׁבַ֖ת] [מְשׂ֥וֹשׂ] [כִּנּֽוֹר]');
INSERT INTO verses VALUES (18174, 23, 24, 9, '[בַּשִּׁ֖יר] não [יִשְׁתּוּ־יָ֑יִן] vinho [שֵׁכָ֖ר] [לְשֹׁתָֽיו]');
INSERT INTO verses VALUES (18175, 23, 24, 10, '[נִשְׁבְּרָ֖ה] cidade-de- sem-forma [כָּל־בַּ֖יִת] todo casa');
INSERT INTO verses VALUES (18176, 23, 24, 11, 'clamor sobre o-vinho nas-áreas Arva todo שמחה a-terra sussurro a-terra');
INSERT INTO verses VALUES (18177, 23, 24, 12, 'permaneceu na-cidade Sama e-Saia será-que portão:');
INSERT INTO verses VALUES (18178, 23, 24, 13, 'que assim será em-meio-de a-terra no-meio-de o-povo כְּנֹ֣קֶף זַ֔יִת כּוֹעֵלֹת se כָּלָה בַּצִּיר׃');
INSERT INTO verses VALUES (18179, 23, 24, 14, 'elas יִשָּׂאוּ voz-deles יָרֻנוּ בַּגְּאוֹן yhwh צָהֳלוּ águas');
INSERT INTO verses VALUES (18180, 23, 24, 15, 'sobre assim [כַּבְּד֣וּ] yhwh yhwh o-mar o-mar yhwh yhwh Elohim-de Israel');
INSERT INTO verses VALUES (18181, 23, 24, 16, 'מֵכְנַף a-terra זְמָרֹות ouvimos צְבִ֣י para o justo e disse segredo- para-mim segredo- a-mim ai a-mim traidores בָּגָ֔דוּ e vestes traidores e enganaram');
INSERT INTO verses VALUES (18182, 23, 24, 17, 'פּ-חַד e o perfume e a fragrância sobre-ti habitante a-terra');
INSERT INTO verses VALUES (18183, 23, 24, 18, '[וֽ͏ְ֠הָיָה] [הַנָּ֞ס] [מִקּ֤וֹל] [הַפַּ֙חַד֙] cairá a [וְהָֽעוֹלֶה֙] [מִתּ֣וֹךְ] de-meio-de [יִלָּכֵ֖ד] [בַּפָּ֑ח] [כִּֽי־אֲרֻבּ֤וֹת] porque [נִפְתָּ֔חוּ] [וַֽיִּרְעֲשׁ֖וּ] [מ֥וֹסְדֵי] [אָֽרֶץ] terra');
INSERT INTO verses VALUES (18184, 23, 24, 19, '[רֹ֥עָה] [הִֽתְרֹעֲעָ֖ה] a-terra [פּ֤וֹר] [הִֽתְפּוֹרְרָה֙] terra [מ֥וֹט] [הִֽתְמוֹטְטָ֖ה] terra');
INSERT INTO verses VALUES (18185, 23, 24, 20, 'נוֹעַ תָּנ֤וּעַ terra כַּשִּׁכּ֔וֹר וְהִֽתְנוֹדְדָ֖ה כַּמְּלוּנָ֑ה וְכָבַ֤ד sobre-ela פִּשְׁעָ֔הּ e-caiu e-não תֹסִ֥יף levantou');
INSERT INTO verses VALUES (18186, 23, 24, 21, 'e-foi no-dia aquele יִפְקֹ֧ד yhwh sobre exército-de הַמָּר֖וֹם no-a-cimeira a-terra reis-de que sobre a-terra');
INSERT INTO verses VALUES (18187, 23, 24, 22, 'e-serão-reunidos reunião prisioneiro sobre na-cova e-serão-fechados sobre fechador e-por-muitos dias serão-ordenados:');
INSERT INTO verses VALUES (18188, 23, 24, 23, 'e-terráceara a-lua e-vergonha o-sol porque yhwh yhwh exércitos em-o-pico Siao e-ir-ushalaim e-diante-de seus-idosos כבוד׃');
INSERT INTO chapters VALUES (704, 23, 25, 12);
INSERT INTO verses VALUES (18189, 23, 25, 1, 'yhwh אֱלֹהַי tu aromimkha odeh seu-nome que fiz-te- milagre אֱצֺת מֵרָחֹ֖וק אֱמוּנָה אֹמֶן׃');
INSERT INTO verses VALUES (18190, 23, 25, 2, 'que [שַׂ֤מְתָּ] [מֵעִיר֙] [לַגָּ֔ל] [קִרְיָ֥ה] [בְצוּרָ֖ה] [לְמַפֵּלָ֑ה] [אַרְמ֤וֹן] [זָרִים֙] [מֵעִ֔יר] para-sempre não [יִבָּנֶֽה]');
INSERT INTO verses VALUES (18191, 23, 25, 3, 'sobre assim יחבדוך׃ com força קiryת nações aritzim יראוך׃');
INSERT INTO verses VALUES (18192, 23, 25, 4, 'porque היית מעוז לדל מעוז para-pobre בַּצַּר־ a-ele refúgio do-semente que espírito porque espírito aritzim como-semente parede:');
INSERT INTO verses VALUES (18193, 23, 25, 5, 'como-deserto em-Sion inveja estrangeiros ocultará חֹ֚רֶב בְּצֵ֣ל עָ֔ב זְמִ֥יר עָֽרִיצִ֖ים יַעֲנֶה׃');
INSERT INTO verses VALUES (18194, 23, 25, 6, '[וְעָשָׂה֩] yhwh exércitos para-todo os-povos [הַזֶּ֔ה] este [שְׁמָנִ֖ים] [מִשְׁתֵּ֣ה] banquete-de [שְׁמָנִים֙] [מְמֻ֣חָיִ֔ם] [שְׁמָרִ֖ים] [מְזֻקָּקִֽים]');
INSERT INTO verses VALUES (18195, 23, 25, 7, '[וּבִלַּע֙] [בָּהָ֣ר] este face-de- [׀] [הַלּ֖וֹט] sobre todo [הַנְּסוּכָ֖ה] [עַל־כָּל־הַגּוֹיִֽם] sobre todo');
INSERT INTO verses VALUES (18196, 23, 25, 8, 'בִּלַּ֤ע a morte para sempre e a destruição Adonai yhwh lágrima de-cima-de todo face e a calúnia povo-dele de-cima-de de-sobre que yhwh porque yhwh palavra');
INSERT INTO verses VALUES (18197, 23, 25, 9, 'e-ele-disse no-dia aquele eis Elohim este esperamos a-ele e nos salve este yhwh esperamos a-ele nos alegraremos e nos alegremos בִּישׁוּעָתֽוֹ׃');
INSERT INTO verses VALUES (18198, 23, 25, 10, 'porque alegria mão-de yhwh na-montanha este Moabe em-lugar-dele כּ-הידוד מ-תבון מ-דמן');
INSERT INTO verses VALUES (18199, 23, 25, 11, 'ו-פרשה suas-maos em-meio-seu como י-פרשה ה- Schönah ל- Schön ו- שפל ג-אוות povo א-רבות יָדָֽיו׃');
INSERT INTO verses VALUES (18200, 23, 25, 12, 'e do-forçar do-escudo as-muros-teu ele-destruiu ele-abaixou atingiu para a terra até cimento:');
INSERT INTO chapters VALUES (705, 23, 26, 21);
INSERT INTO verses VALUES (18201, 23, 26, 1, 'no-dia aquele ele-estendeu o-canto- este na-terra Judá cidade a-força- para-nós Salvation will establish walls e-muralha');
INSERT INTO verses VALUES (18202, 23, 26, 2, 'will open portas-as E-veio nation- justo guardando faithful');
INSERT INTO verses VALUES (18203, 23, 26, 3, 'inclinação close will encamp שָׁל֣וֹם ׀ שָׁל֑וֹם porque que in safety');
INSERT INTO verses VALUES (18204, 23, 26, 4, 'sejam-se-berçados no-ye-ho-wa ate que porque yhwh yhwh rocha pelos-dias');
INSERT INTO verses VALUES (18205, 23, 26, 5, 'que queimem-no habitantes-de dos-altos cidade e-elevem-na quebrem-na quebrem-a até terra atingam-na até em-pó');
INSERT INTO verses VALUES (18206, 23, 26, 6, 'תִּרְמְסֶ֖נָּה רָ֑גֶל pés-de עני פַּעֲמֵ֥י דַלִּֽים׃');
INSERT INTO verses VALUES (18207, 23, 26, 7, 'אֹ֥רַח לַצַּדִּ֖יק מֵֽישָׁרִ֑ים יָשָׁ֕ר מַעְגַּ֥ל justo תְּפַלֵּֽס׃');
INSERT INTO verses VALUES (18208, 23, 26, 8, 'certamente אָרַך מִשְׁפָּטֶיךָ yhwh קִוֹֻינ֑וּךָ leshimcha וּלְזִכְרְךָ֖ תַּאֲוַת־ alma');
INSERT INTO verses VALUES (18209, 23, 26, 9, '[נַפְשִׁ֤י] [אִוִּיתִ֙יךָ֙] [בַּלַּ֔יְלָה] também [בְקִרְבִּ֖י] [אֲשַֽׁחֲרֶ֑ךָּ] que porque como [לָאָ֔רֶץ] [צֶ֥דֶק] [לָמְד֖וּ] [יֹשְׁבֵ֥י] habitantes-de');
INSERT INTO verses VALUES (18210, 23, 26, 10, '[יֻחַ֤ן] [רָשָׁע֙] não [צֶ֔דֶק] justiça em-terra-de [יְעַוֵּ֑ל] [וּבַל־יִרְאֶ֖ה] [גֵּא֥וּת] yhwh yhwh');
INSERT INTO verses VALUES (18211, 23, 26, 11, 'yhwh exaltou-se tua-mao não יֶחֱזָי֑וּן יֶחֱז֤וּ e se envergonhem cobiça de povo também fogo necessidade tua comereis vós');
INSERT INTO verses VALUES (18212, 23, 26, 12, 'yhwh vos morderéis paz para-nós que também todo nossas obras fizeste para nós');
INSERT INTO verses VALUES (18213, 23, 26, 13, 'yhwh nosso-Elohim nos dominaste senhores zulateka lebад- em-te nazkir שְׁמֶֽךָ׃');
INSERT INTO verses VALUES (18214, 23, 26, 14, 'metim não yichyu refaim não yakumu lакen pakadta vatasamidem e destruiste todo macho a-eles');
INSERT INTO verses VALUES (18215, 23, 26, 15, 'continuaste a para o povo yhwh continuaste a para o povo foste exaltada distanciaste-te de todo seus mandamentos terra');
INSERT INTO verses VALUES (18216, 23, 26, 16, 'yhwh em-dificuldade te visitaste justos no-ha-lash mo-sar-ka a-eles');
INSERT INTO verses VALUES (18217, 23, 26, 17, 'k-mo הָרָה ta-kriv para-dar-à-luz ta-chil ti-za-ak be-ha-chavaleiha assim hi-yinu de ti diante yhwh');
INSERT INTO verses VALUES (18218, 23, 26, 18, 'harinu hal-nu como נולדהו espírito ישועות não terra terra ובל- יפלוּ habitantes-de תֵבֵֽל׃');
INSERT INTO verses VALUES (18219, 23, 26, 19, 'יחיוּ מתיך נבלתי יְקוּמֹנքוּ הAKEZU ורננוּ שוכני pó que tal orot tallecha va''aretz refains tappihl');
INSERT INTO verses VALUES (18220, 23, 26, 20, 'vai meu-povo veio bachadaricha usgor ba''adcha chavie kim''eit- רֶ֖גַע até זָֽעַם׃');
INSERT INTO verses VALUES (18221, 23, 26, 21, 'porque yhwh sai saindo [לִפְקֹ֛ד] [עֲוֺ֥ן] iniquidade-de [עָלָ֑יו] a-terra a-terra [אֶת־דָּמֶ֔יהָ] a-terra a [עַל־הֲרוּגֶֽיהָ׃] e-não sobre');
INSERT INTO chapters VALUES (706, 23, 27, 13);
INSERT INTO verses VALUES (18222, 23, 27, 1, 'no-dia הַהוּא ele guardará yhwh בְּחַרְב֨וֹ הַקָּשָׁ֜ה e a grande e a forte sobre Leviatã nabo barich e-sobre Leviatã nabo aquallaton e matou a o tanin que dia:');
INSERT INTO verses VALUES (18223, 23, 27, 2, 'no-dia aquele carmelo prazer arrependei-vos- a-ela');
INSERT INTO verses VALUES (18224, 23, 27, 3, 'eu yhwh guardiã- por-tempo asquenásia para-que-não ele guardará sobre-ela noite e-dia- eu-reuni-me-');
INSERT INTO verses VALUES (18225, 23, 27, 4, 'ira não-há a-mim quem me-deu שָׁמַר שַׁיִת na-guerra אֵפְשַׂעַת nela אֲצִיתֶנָּה יְחַד׃');
INSERT INTO verses VALUES (18226, 23, 27, 5, 'ou יַחֲזֶק בְּמָעֻזִּי ele-fará paz a-mim paz יַעֲשֶׂה־ a-mim');
INSERT INTO verses VALUES (18227, 23, 27, 6, 'os-que-vêm יָשַׁרְתּוֹשׁ Jacó יָצַץ e se estenderá Israel e-encheram faces de tevel florescimento;');
INSERT INTO verses VALUES (18228, 23, 27, 7, 'a metade da que o machucará atingi-lo se como um cortejo sua ferida como um cortejo');
INSERT INTO verses VALUES (18229, 23, 27, 8, 'em um vaso de בְּשַׁלְחָ֣הּ תְּרִיבֶ֑נָּה הָגָ֛ה בְּרוּח֥וֹ a-dura em-dia קָדִֽים׃');
INSERT INTO verses VALUES (18230, 23, 27, 9, 'portanto nisto יְכֻפָּר עֲוֺֽן־ Jacó e-este todo פְּרִ֖י הָסִ֣ר חַטָּאת֑וֹ בְּשׂוּמ֣וֹ ׀ todo pedras-de mizbeach como pedras- de gir- dispersas não [sem-traducao] e as [sem-traducao]');
INSERT INTO verses VALUES (18231, 23, 27, 10, 'que cidade em pedra- sozinho elegante enviados e será abandonado como um deserto nome יִרְעֶ֥ה ovelha e ali se encharcará e consumirá suas asas');
INSERT INTO verses VALUES (18232, 23, 27, 11, 'se assustará sua colheita será quebrada mulheres בָּא֖וֹת מְאִיר֣וֹת אוֹתָ֑הּ que não com ele ele sobre assim não não עֹשֵׂ֔הוּ וְיֹצְר֖וֹ não יְחֻנֶּֽנּוּ׃');
INSERT INTO verses VALUES (18233, 23, 27, 12, 'e-foi no-dia aquele יַחְבֹּ֧ט yhwh מִשִּׁבֹּ֥לֶת o-rio até vale-de Egito וְאַתֶּ֧ם תְּלֻקְּט֛וּ um um filhos-de Israel');
INSERT INTO verses VALUES (18234, 23, 27, 13, 'e-era no-dia no-dia יתתקע בshawfā'' grande וּבוּ הָאֹבְדִים na-terra Assíria וְהַנִדָּחִים na-terra Egito וְהִשׁתַחֲווּ לַיהוָ֛ה em-monte-de o-santo em-Jerusalém');
INSERT INTO chapters VALUES (707, 23, 28, 29);
INSERT INTO verses VALUES (18235, 23, 28, 1, '[ה֗וֹי] [עֲטֶ֤רֶת] [גֵּאוּת֙] [שִׁכֹּרֵ֣י] [אֶפְרַ֔יִם] [וְצִ֥יץ] [נֹבֵ֖ל] [צְבִ֣י] [תִפְאַרְתּ֑וֹ] que sobre cabeça [הֲל֥וּמֵי] [יָֽיִן]');
INSERT INTO verses VALUES (18236, 23, 28, 2, 'eis חָזָ֤ק וְאַמִּץ֙ לַֽאדֹנָ֔י כְּזֶ֥רֶם gelo Shaft Katab Kazarim águas Kabirim [שֹׁטְפִ֛ים] Hinach para a terra Byad:');
INSERT INTO verses VALUES (18237, 23, 28, 3, 'Beraglayim Teramasnah Atarah Gloria Amargos Efrayim');
INSERT INTO verses VALUES (18238, 23, 28, 4, 'e será Espigas Queimado צְבִ֣י Bela que sobre cabeça Vale Óleos Primícias betereim-acento-águia Verão que Verá o-vendo ela na-adorá-la em-seu-pão ser-ingerida');
INSERT INTO verses VALUES (18239, 23, 28, 5, 'no-dia aquele será yhwh exércitos para-a-coroa glória e-para-a-pomba ser-decorada para-o-resto seu-povo');
INSERT INTO verses VALUES (18240, 23, 28, 6, 'e-para-a-ventura juízo לוֹשֵׁב sobre הַמִּשְׁפָּט וְלִגְבֻּרָה מְשִׁיבֵי guerra שַׁעֲרָה׃');
INSERT INTO verses VALUES (18241, 23, 28, 7, 'e-também estes [שָׁג֔וּ] [וּבַשֵּׁכָ֖ר] [תָּע֑וּ] [כֹּהֵ֣ן] sacerdote [שָׁג֨וּ] [בַשֵּׁכָ֜ר] [נִבְלְע֣וּ] [מִן־הַיַּ֗יִן] de [מִן־הַשֵּׁכָ֔ר] [שָׁגוּ֙] de [פָּק֖וּ] [פְּלִילִיָּֽה]');
INSERT INTO verses VALUES (18242, 23, 28, 8, 'que todo שֻׁלְחָנ֔וֹת preencheram [צֹאָ֑ה] צֹאָה lugar neste lugar:');
INSERT INTO verses VALUES (18243, 23, 28, 9, 'a quem יוֹרֶ֣ה דֵעָ֔ה e-a quem Jabim שְׁמוּעָ֑ה גְּמוּלֵי֙ מֵֽחָלָ֔ב עַתִּיקֵ֖י מִשָּׁדָֽיִם׃');
INSERT INTO verses VALUES (18244, 23, 28, 10, 'que ordene לָצָו֙ צַ֣ו lázav qáv láqav qáv láqav zé''ir nome zé''ir nome');
INSERT INTO verses VALUES (18245, 23, 28, 11, 'que bəlā''ăgê sápáh úbəláshôn אַחֶ֑רֶת ele-falará a o-povo a-esta');
INSERT INTO verses VALUES (18246, 23, 28, 12, 'que disse disse esta esta הָנִ֣יחוּ לֶֽעָיֵ֔ף e-esta הַמַּרְגֵּעָ֑ה e-não אָב֖וּא שְׁמֽוֹעַ׃');
INSERT INTO verses VALUES (18247, 23, 28, 13, 'e-será a-eles palavra-de yhwh צַ֣ו לָצָ֞ו ordene לָצָו֙ קַ֤ו לָקָו קַ֣ו לָקָ֔ו זְעֵ֥יר nome זְעֵ֣יר nome para-que יֵלְכ֜וּ וְכָשְׁל֤וּ אָחוֹר֙ וְנִשְׁבָּ֔רוּ וְנוֹקְשׁ֖וּ e foram aprisionados:');
INSERT INTO verses VALUES (18248, 23, 28, 14, 'por-isso ouvi palavra-de yhwh homens-de pastores príncipes o-povo este que em-Jerusalém');
INSERT INTO verses VALUES (18249, 23, 28, 15, 'que dizeis cortastes aliança a morte e-com- sepulcro fizemos profeta enxaguador porque não não porque que mentiroso nossos-maçu e-no-shequer nos-nisterun');
INSERT INTO verses VALUES (18250, 23, 28, 16, 'portanto assim disse Adonai yhwh הִנְנִ֛י estad em-tsiyon pedra pedra examinha finta leia musad musad o ma''amin não yaḥiš׃');
INSERT INTO verses VALUES (18251, 23, 28, 17, 'וְשַׂמְתִּ֤י מִשְׁפָּט֙ ləqāʾōv e-justica ləmišqaʾlet ve-yāʿaḥ barad machsheʾ kāzavō vesetar águas yishṭoʿū׃');
INSERT INTO verses VALUES (18252, 23, 28, 18, 'e expiação vossa aliança a morte e vossa visão não sepulcro não arrebataram-se que lavador e-sereis a-ele seríeis para-ele para a mira');
INSERT INTO verses VALUES (18253, 23, 28, 19, 'desde passou-o היאخذ vos porque no começo da manhã na-manhã no-dia no-dia e-no-layáh e-será somente zva''áh habín sh''mú''ah');
INSERT INTO verses VALUES (18254, 23, 28, 20, 'porque qatsár ham-matzá mehiš''táré''ah ve-hamassékáh tsaráh khit''kanés');
INSERT INTO verses VALUES (18255, 23, 28, 21, 'que כְּהַר־ פְּרָצִים֙ yhwh yhwh כְּעֵ֖מֶק בְּגִבְע֣וֹן יִרְגָּ֑ז לַעֲשׂוֹת מַעֲשֵׂ֙הוּ֙ זָר seu-trabalho וְלַֽעֲבֹד֙ עֲבֹ֣דָת֔וֹ נָכְרִיָּ֖ה serviço-seu');
INSERT INTO verses VALUES (18256, 23, 28, 22, 'e-agora a תִּתְלוֹצָ֔צוּ para-que-não יֶחְזְק֖וּ מֽוֹסְרֵיכֶ֑ם porque כָלָ֨ה וְנֶחֱרָצָ֜ה ouvi de-a Adonai yhwh de-exércitos sobre todo a-terra');
INSERT INTO verses VALUES (18257, 23, 28, 23, '[הַאֲזִ֥ינוּ] [וְשִׁמְע֖וּ] [קוֹלִ֑י] [הַקְשִׁ֥יבוּ] [וְשִׁמְע֖וּ] [אִמְרָתִֽי]');
INSERT INTO verses VALUES (18258, 23, 28, 24, 'há-todo o-dia cavará o cavador para semear abrirá e estenderá sua terra:');
INSERT INTO verses VALUES (18259, 23, 28, 25, 'não-verdade se encherá פָנֶ֔יהָ e espalhará o tesouro e como será lançado e puser trigo bola de trigo e grão de trigo sinalado e cobertura seu limite:');
INSERT INTO verses VALUES (18260, 23, 28, 26, 'e seriam para-a-jurisdição seus-elohimes ensine-o');
INSERT INTO verses VALUES (18261, 23, 28, 27, 'que não no-óleo Judá o-ouro e-o-carro carruagem sobre como-a-maneira que porque no-tribo יֵחָ֥בֶט קֶ֖צַח וְכַמֹּ֥ן בַּשָּֽׁבֶט׃');
INSERT INTO verses VALUES (18262, 23, 28, 28, 'pão יוּדָ֔ק que não לָנֶ֖צַח אָד֣וֹשׁ יְדוּשֶׁ֑נּוּ וְ֠הָמַם גִּלְגַּ֧ל sua-egla -e-sua-parasha não serão-escaldados;');
INSERT INTO verses VALUES (18263, 23, 28, 29, 'também isto yhwh yhwh exércitos saíram maravilhou-se conselhos הִגְדִּ֖יל sabedoria;');
INSERT INTO chapters VALUES (708, 23, 29, 24);
INSERT INTO verses VALUES (18264, 23, 29, 1, 'ah! ariel אריאל קרית חנה Davi safu ano sobre ano חגים ינקוּ׃');
INSERT INTO verses VALUES (18265, 23, 29, 2, '[וַהֲצִיק֖וֹתִי] [לַֽאֲרִיאֵ֑ל] e-será [תַֽאֲנִיָּה֙] [וַֽאֲנִיָּ֔ה] [וְהָ֥יְתָה] a-mim [כַּאֲרִיאֵֽל]');
INSERT INTO verses VALUES (18266, 23, 29, 3, 'וְחָנִ֥יתִי כַדּ֖וּר sobre ti וְצַרְתִּ֤י sobre-ti מֻצָּ֔ב וַהֲקֽ͏ִימֹתִ֥י sobre-ti מְצֻרֹֽת׃');
INSERT INTO verses VALUES (18267, 23, 29, 4, 'וְשָׁפַלְתְּ֙ da-terra תְּדַבֵּ֔רִי וּמֵֽעָפָ֖ר תִּשַׁ֣ח אִמְרָתֵ֑ךְ e-foi כְּא֤וֹב מֵאֶרֶץ קוֹלֵ֔ךְ וּמֵעָפָ֖ר אִמְרָתֵ֥ךְ תְּצַפְצֵֽף׃');
INSERT INTO verses VALUES (18268, 23, 29, 5, 'e será כְּאָבָ֥ק דַּ֖ק multidão זָרָ֑יִךְ e como arreios passando multidão estendem-se e-foi no rosto פִּתְאֹֽם׃');
INSERT INTO verses VALUES (18269, 23, 29, 6, 'de yhwh exércitos agita-se em seu mal e em sua aspereza e-voz grande vento e fogo e fagulhas fogo אֹכֵ֗ל');
INSERT INTO verses VALUES (18270, 23, 29, 7, 'e-foi [כַּֽחֲלוֹם֙] [חֲז֣וֹן] noite [הֲמוֹן֙] todo as-nações [עַל־אֲרִיאֵ֑ל] sobre [וּמְצֹ֣דָתָ֔הּ] e-todo [לָֽהּ]');
INSERT INTO verses VALUES (18271, 23, 29, 8, 'e-será como-que יַחֲלוֹם הָרָעֵ֜ב e-eis אֹכֵ֗ל וְהֵקִיץ֮ וְרֵיקָ֣ה נַפְשׁוֹ֒ וְכַאֲשֶׁ֨ר יַחֲלֹ֤ם הַצָּמֵא֙ e-eis שֹׁתֶ֔ה וְהֵקִיץ֙ e-eis עָיֵ֔ף e-seu-espírito שׁוֹקֵקָ֑ה assim será המון֙ todo as-nações os que marcham sobre monte-de צִיּֽוֹן');
INSERT INTO verses VALUES (18272, 23, 29, 9, 'se espantem e se espante se assenhassem e se assenhassem e se cobrirem e-não vinho e se agitaram e-não e se cobriram;');
INSERT INTO verses VALUES (18273, 23, 29, 10, 'porque e se elevaram yhwh espírito sono-profundo e se adormeceram e apagaram a os olhos-vossos a os profetas e-a as-cabeças-vossos os-que-viram cobriu-se');
INSERT INTO verses VALUES (18274, 23, 29, 11, 'e-foi a-vós visão todo-o segundo-as-palavras o sefer o-que-está-fechado que ele a-ele a conhecedor dizendo chamou por favor esta não não que porque ele ela');
INSERT INTO verses VALUES (18275, 23, 29, 12, 'e foi dado o sefer sobre que não conheceu dizendo para-dizer chamou na- não e ele disse: não conheci livro');
INSERT INTO verses VALUES (18276, 23, 29, 13, 'E-disse Adonai porque que ele se aproximou o-povo este com sua boca e com suas lábios honrai-me e seu coração se afastou de-mim e-foi sua temor a-mim mandamento-de homens instruída:');
INSERT INTO verses VALUES (18277, 23, 29, 14, 'portanto eis-me José para fazer maravilhas a o-povo- este maravilha e maravilha e destruição sabedoria-de seus sabedoria e entendimento seu discernimento seria ocultada:');
INSERT INTO verses VALUES (18278, 23, 29, 15, 'הָוֵי הַמַּעֲמִיקִ֥ים מֵֽיהוָ֖ה לַסְתּ֣ר conselho e-será בְמַחְשָׁךְ֙ מַֽעֲשֵׂיהֶ֔ם e-disseram quem רֹאֵ֖נוּ e-quem יוֹדְעֵֽנוּ׃');
INSERT INTO verses VALUES (18279, 23, 29, 16, '[הַ֨פְכְּכֶ֔ם] se [הַיֹּצֵ֖ר] [יֵֽחָשֵׁ֑ב] [כִּֽי־יֹאמַ֨ר] porque [לְעֹשֵׂ֙הוּ֙] não [עָשָׂ֔נִי] não disse [לְיוֹצְר֖וֹ] não [הֵבִֽין] não');
INSERT INTO verses VALUES (18280, 23, 29, 17, 'porventura-não ainda pouco מזער ושׁוב לבanon לכרכמל e o jardim será como a floresta será contado');
INSERT INTO verses VALUES (18281, 23, 29, 18, 'e ouvirão no-dia-de aquele os surdos דּ-בְרֵי- livro os-olhos-de e da escuridão olhos de os cegos vireis');
INSERT INTO verses VALUES (18282, 23, 29, 19, 'e consumirão os humildes em-יהוה שִׂמְחָה e os pobres homem em santidade Israel se alegrarão');
INSERT INTO verses VALUES (18283, 23, 29, 20, 'porque o fraco o covarde e a vil a escarnecedora serão cortados todo os que se exaltam iniquidade');
INSERT INTO verses VALUES (18284, 23, 29, 21, 'מַחֲטִיאֵ֤י homem בְּדָבָ֔ר וְלַמּוֹכִ֥יחַ be-sha-ar יְקֹשׁ֑וּן וַיַּטּ֥וּ בַתֹּ֖הוּ צַדִּיק׃');
INSERT INTO verses VALUES (18285, 23, 29, 22, 'portanto assim yhwh yhwh a casa Jacó que [לֹֽא־עַתָּ֤ה] a Abraão não [עַתָּ֖ה] [פָּנָ֥יו] Jacó e-não');
INSERT INTO verses VALUES (18286, 23, 29, 23, 'que בִ֠רְאֹתוֹ seus-filhos obra-de minhas-mãos em-meio-seu santifiquem o meu nome e-santifiquem a santo Jacó e-a Elohim-de Israel injuriar-vos-');
INSERT INTO verses VALUES (18287, 23, 29, 24, 'e conhecerão enganadores- espírito sabedoria-na e-sussurros aprendam- tomou');
INSERT INTO chapters VALUES (709, 23, 30, 33);
INSERT INTO verses VALUES (18288, 23, 30, 1, 'ai filhos SORRÍM oráculo-de yhwh לַעֲשׂוֹת עֵצָה e-não MINI E LINÇO MASCA e-não RUÍ para-fim-de SEPOT pecado sobre חטאת:');
INSERT INTO verses VALUES (18289, 23, 30, 2, 'OS QUE ANDAM לארדת Egito E MEU BOCO não PERGUNTARAM PARA FORÇA em-oz Faraó e-lachos em-a-sombra Egito');
INSERT INTO verses VALUES (18290, 23, 30, 3, 'e-será a-vós מעוז פַּרְעֹה pel-boche e-hechasu em-tsela Egito para-kelima');
INSERT INTO verses VALUES (18291, 23, 30, 4, 'porque foram em-tzonen seirav e-malakav hanses virão');
INSERT INTO verses VALUES (18292, 23, 30, 5, 'todo sobre povo não [לֹא־יוֹעִ֣ילוּ] a-eles não [לְעֵ֙זֶר֙] e-não [לְהוֹעִ֔יל] que [לְבֹ֖שֶׁת] e-também');
INSERT INTO verses VALUES (18293, 23, 30, 6, 'profecia [בַּהֲמ֣וֹת] [נֶ֑גֶב] [בְּאֶרֶץ֩] [צָרָ֨ה] [וְצוּקָ֜ה] [לָבִ֧יא] [וָלַ֣יִשׁ] [מֵהֶ֗ם] [אֶפְעֶה֙] [וְשָׂרָ֣ף] [מְעוֹפֵ֔ף] [יִשְׂאוּ֩] sobre [עֲיָרִ֜ים] [חֵֽילֵהֶ֗ם] [וְעַל־דַּבֶּ֤שֶׁת] e-sobre [אֽוֹצְרֹתָ֔ם] [עַל־עַ֖ם] não sobre povo não');
INSERT INTO verses VALUES (18294, 23, 30, 7, '[וּמִצְרַ֕יִם] [הֶ֥בֶל] [וָרִ֖יק] [יַעְזֹ֑רוּ] [לָכֵן֙] [קָרָ֣אתִי] [לָזֹ֔את] [רַ֥הַב] eles [שָֽׁבֶת]');
INSERT INTO verses VALUES (18295, 23, 30, 8, 'agora trazer כתבה sobre לֻחַ com-eles e-sobre livro חֻקָּה וּתְהִי֙ para-o-dia אַחֲר֔וֹן eis até eternidade');
INSERT INTO verses VALUES (18296, 23, 30, 9, 'que povo מְרִי֙ ele filhos כֶּחָשִׁ֑ים בָּנִ֕ים não אָב֥וּ שְׁמ֖וֹעַ yhwh yhwh');
INSERT INTO verses VALUES (18297, 23, 30, 10, 'que אָמְר֤וּ לָֽרֹאִים֙ não Tirem e vistos não vejam— a-nos verdades disseram— a-nos partes vejam— maravilhas:');
INSERT INTO verses VALUES (18298, 23, 30, 11, 'voltem-se de caminho הַטּוּ מִנֵּי־ caminho הַשְׁבִּ֥יתוּ de-faces-de-nós a santo Israel');
INSERT INTO verses VALUES (18299, 23, 30, 12, 'portanto assim disse santo Israel [יַ֥עַן] [מָֽאָסְכֶ֖ם] [בַּדָּבָ֣ר] este [וַֽתִּבְטְחוּ֙] [בְּעֹ֣שֶׁק] [וְנָל֔וֹז] [וַתִּֽשָּׁעֲנ֖וּ] sobre-ele');
INSERT INTO verses VALUES (18300, 23, 30, 13, 'portanto será a-vós [הֶעָוֺ֣ן] este [כְּפֶ֣רֶץ] [נֹפֵ֔ל] [נִבְעֶ֖ה] [בְּחוֹמָ֣ה] [נִשְׂגָּבָ֑ה] que [לְפֶ֖תַע] [יָב֥וֹא] virá');
INSERT INTO verses VALUES (18301, 23, 30, 14, 'ושברהה כשבור נבלה יֹצְרִים כּוֹתֶ֥ת não יַחְמֹ֑ל e-não será achado בִּמְכִיתָתוֹ֙ silencio לַחֲתֹות fogo מִיַּקּוּד águas águas מִגֵּבֶא׃');
INSERT INTO verses VALUES (18302, 23, 30, 15, 'que כֹּה־ disse Adonai yhwh santo Israel בְּשׁוּבוֹת וָנָ֙חָת֙ ser-vos-salvos בְּהַשְׁקֵט֙ וּבְבִטְחָ֔ה será גְּבֽוּרַתְכֶ֑ם e-não אֲבִיתֶֽם׃');
INSERT INTO verses VALUES (18303, 23, 30, 16, '[וַתֹּ֨אמְר֥וּ] não porque sobre [עַל־כֵּ֣ן] [תְּנוּס֑וּן] sobre assim [עַל־כֵּ֖ן] e-sobre [רֹדְפֵיכֶֽם] sobre');
INSERT INTO verses VALUES (18304, 23, 30, 17, 'mil um de-diante-de [גַּעֲרַ֣ת] um de-diante-de [גַּעֲרַ֥ת] [חֲמִשָּׁ֖ה] [תָּנֻ֑סוּ] até se [כַּתֹּ֙רֶן֙] [עַל־רֹ֣אשׁ] sobre cabeça o-monte sobre');
INSERT INTO verses VALUES (18305, 23, 30, 18, 'וְלָכֵ֞ן יְחַכֶּ֤ה yhwh לַֽחֲנַנְכֶ֔ם e-portanto יָר֖וּם por vossa misericórdia porque Elohim-de yhwh yhwh אַשְׁרֵ֖י a-ele sábios a-ele');
INSERT INTO verses VALUES (18306, 23, 30, 19, 'porque povo em Sião habitou be-Yerushalaim por vós não choreis à-voz-de vossas tendas para-voz o vosso grito quando ouvi-lo respondeis');
INSERT INTO verses VALUES (18307, 23, 30, 20, 'e deu a-vós Adonai pão צר e águas לחץ e-não יכנף ainda e-sejam e-serão olhos-teus ראות a מורהך׃');
INSERT INTO verses VALUES (18308, 23, 30, 21, 'ואזנך תשמענה palavra מאחרך dizendo este o-caminho ide nele que תאמינו e-que תשמיאלו׃');
INSERT INTO verses VALUES (18309, 23, 30, 22, '[וְטִמֵּאתֶ֗ם] a [פְּסִילֵ֣י] [כַסְפֶּ֔ךָ] [וְאֶת־אֲפֻדַּ֖ת] e-[OBJ] [זְהָבֶ֑ךָ] [תִּזְרֵם֙] [כְּמ֣וֹ] [דָוָ֔ה] [צֵ֖א] [תֹּ֥אמַר] a-ele');
INSERT INTO verses VALUES (18310, 23, 30, 23, 'e-ele-dará מְטַ֨ר tua-semente que sowaste a הָאֲדָמָ֗ה a-terra תְּבוּאַ֣ת a-te-rri-tó-ria e-será דָשֵׁ֖ן וְשָׁמֵ֑ן no-dia מִקְנֶ֛יךָ no-dia aquele כַּ֥ר נִרְחָֽב׃');
INSERT INTO verses VALUES (18311, 23, 30, 24, '[וְהָאֲלָפִ֣ים] [וְהָעֲיָרִ֗ים] [עֹֽבְדֵי֙] a-terra [בְּלִ֥יל] [חָמִ֖יץ] [יֹאכֵ֑לוּ] que [בָרַ֖חַת] [וּבַמִּזְרֶֽה]');
INSERT INTO verses VALUES (18312, 23, 30, 25, 'e-era sobre todo monte-de גָּבְהָ e-sobre todo גִּבְעָ֣ה נִשָּׂאָ֔ה פְּלָגִ֖ים יִבְלֵי־ águas em-dia-de הרג muito בנפל מגדלים׃');
INSERT INTO verses VALUES (18313, 23, 30, 26, 'e-será אור־ הלבנה֙ כאור החממה֔ ואור será será שביעתים֔ כאור sete os-dias em-dia-de yhwh yhwh a שֶׁ֣בֶר seu-povo e-o-machatz machato irpe');
INSERT INTO verses VALUES (18314, 23, 30, 27, 'eis nome-de yhwh veio mimerekhaq queimando sua-ira ve-kobed masa sapatayav מָ֣לְאוּ za''am וּלְשׁוֹנ֖וֹ כְּאֵ֥שׁ ochelet');
INSERT INTO verses VALUES (18315, 23, 30, 28, '[וְרוּח֞וֹ] [כְּנַ֤חַל] [שׁוֹטֵף֙] até [יֶֽחֱצֶ֔ה] [לַהֲנָפָ֥ה] [גוֹיִ֖ם] [בְּנָ֣פַת] [שָׁ֑וְא] [וְרֶ֣סֶן] [מַתְעֶ֔ה] sobre sobre [עַמִּֽים]');
INSERT INTO verses VALUES (18316, 23, 30, 29, 'השיר será a-vós כליל se santifique- comemore- e alegria- coração- como andando- em chalil- para-vir בְּהַר- yhwh a tsur Israel');
INSERT INTO verses VALUES (18317, 23, 30, 30, 'e anunciará- yhwh a glória voz-dele e alegria- sua mão- ele verá- certamente אַף וְלַהַב fogo אוֹכֵלָה נֶפֶץ וָזֶרֶם e-pedra-de barad');
INSERT INTO verses VALUES (18318, 23, 30, 31, 'porque yhwh yhwh [אַשּׁ֑וּר] Assíria [יַכֶּֽה]');
INSERT INTO verses VALUES (18319, 23, 30, 32, 'e-foi todo מַֽעֲבַר֙ tribo-de מֽוּסָדָ֔ה que יָנִ֤יחַ yhwh sobre-ele em-tumpos e-b-cinorot e-b-milchomot oferta-elevação nilecham-');
INSERT INTO verses VALUES (18320, 23, 30, 33, 'porque aruch me-etmul tapteh também para-o-rei huken heimik hirchib meduráthah אֵ֤שׁ véetsim harbê nishmat yhwh kénaḥal gáfrít bó''arah nela');
INSERT INTO chapters VALUES (710, 23, 31, 9);
INSERT INTO verses VALUES (18321, 23, 31, 1, 'ai hayyórdiv Egito lé''ezráh sobre cavalos yishá''enu e se confiaram que carruagem porque muito e-sobre muito porque elas mesmas muito e-não e acordaram não santo Israel e-a yhwh não e buscaram');
INSERT INTO verses VALUES (18322, 23, 31, 2, 'e-também ele e-trouxe mal mau não palavras-dele não ele tirou e levantou-se sobre casa mere''īm e-sobre ajuda trabalhadores iniquidade');
INSERT INTO verses VALUES (18323, 23, 31, 3, 'e Egito homem e-não El e seus cavalos carne e-não espírito sua-mão torne-se inclinado mão-sua e vacile auxiliador e caia auxiliar e juntos todos-eles serão vencidos');
INSERT INTO verses VALUES (18324, 23, 31, 4, 'que assim disse יהוה para mim como gritará o leão e a cipreste sobre seu rabo será-chamada será chamado sobre-ele enchei pastores não não acamparão não não responderá assim yhwh yhwh exércitos para-campear sobre monte-de Sião e-sobre sua montanha');
INSERT INTO verses VALUES (18325, 23, 31, 5, '[כְּצִפֳּרִ֣ים] [עָפ֔וֹת] assim [יָגֵ֛ן] yhwh exércitos sobre [גָּנ֥וֹן] [וְהִצִּ֖יל] [פָּסֹ֥חַ] [וְהִמְלִֽיט]');
INSERT INTO verses VALUES (18326, 23, 31, 6, '[שׁ֗וּבוּ] [לַאֲשֶׁ֛ר] [הֶעְמִ֥יקוּ] [סָרָ֖ה] filhos-de Israel');
INSERT INTO verses VALUES (18327, 23, 31, 7, 'que no-dia aquele serão destruídos homem elohimes seu dinheiro e elohimes seu ouro que fizeram a-vós suas mãos pecado;');
INSERT INTO verses VALUES (18328, 23, 31, 8, 'e cairão ʾaššur pela espada não homem e espada não homem a-ele e levantaram-se a-ele מִפְּנֵי־ espada e nos seus jovens tangiu-se a ser-ão');
INSERT INTO verses VALUES (18329, 23, 31, 9, 'e seu tambor do balcão passará por e as do fio seus generais oráculo-de yhwh a-ele luz a-ele a-ele e o forno para-ele em-Jerusalém');
INSERT INTO chapters VALUES (711, 23, 32, 20);
INSERT INTO verses VALUES (18330, 23, 32, 1, 'eis [לְצֶ֖דֶק] [יִמְלָךְ־מֶ֑לֶךְ] rei [לְמִשְׁפָּ֥ט] [יָשֹֽׂרוּ]');
INSERT INTO verses VALUES (18331, 23, 32, 2, 'וְהָיָה־ homem כְּמַֽחֲבֵא־ espírito וְסֵ֣תֶר זָ֑רֶם כְּפַלְגֵי־ águas em-Sion כְּצֵ֥ל selá- pesado em-terra-de ʿayefāʾ:');
INSERT INTO verses VALUES (18332, 23, 32, 3, 'e-não tishʿenā os-olhos-de roʾim veʾaznei šōmeʿim tikšabnā:');
INSERT INTO verses VALUES (18333, 23, 32, 4, 'וּלְבַ֥ב nimhārim Jabim ladāʿaṯ uvelṣōn עִילָגִים תְּמַהֵר de-falar צָחוֹת׃');
INSERT INTO verses VALUES (18334, 23, 32, 5, 'não [ע֛וֹד] ainda [נָדִ֑יב] [וּלְכִילַ֕י] não não [שֽׁוֹעַ]');
INSERT INTO verses VALUES (18335, 23, 32, 6, 'que נָבַל נְבָלָה יְדַבֵּ֔ר וְלִבּוֹ fará- iniquidade para fazer חֹנֶף e fale a yhwh erro para esvaziar alma fome e sede sede careça');
INSERT INTO verses VALUES (18336, 23, 32, 7, 'e em mim seus vasos males ele intenções conselhos para-que-ha-bale em-palavras-de mentira e-em-dizer אֶבְי֖וֹן juízo');
INSERT INTO verses VALUES (18337, 23, 32, 8, 'e-generoso generosas conselhos e-ele sobre generosas יתקום׃');
INSERT INTO verses VALUES (18338, 23, 32, 9, 'mulheres e-alegres viram-se ouviu minha voz filhas confiantes escutem minha palavra');
INSERT INTO verses VALUES (18339, 23, 32, 10, 'dias sobre ano treme que porque completou-a no cativeiro eu recolherei בְּלִי yhwh');
INSERT INTO verses VALUES (18340, 23, 32, 11, 'chorem as anãs tremor בֹּֽטְח֑וֹת פְּשֹׁ֣טָֽה וְעֹ֔רָה וַחֲג֖וֹרָה sobre חֲלָצָֽיִם׃');
INSERT INTO verses VALUES (18341, 23, 32, 12, 'sobre [סֹֽפְדִ֑ים] [עַל־שְׂדֵי־חֶ֕מֶד] sobre [פֹּרִיָּֽה] sobre');
INSERT INTO verses VALUES (18342, 23, 32, 13, 'sobre solo-de povo-meu espinho שָׁמִיר תַּעֲלֶה que sobre todo nas tuas מָשׂוֹשׂ קִרְיָה עַלּיִזָה׃');
INSERT INTO verses VALUES (18343, 23, 32, 14, 'porque [נֻטָּ֔שׁ] [הֲמ֥וֹן] [עִ֖יר] cidade [עֹ֣פֶל] [וָבַ֜חַן] ser foi [מְעָרוֹת֙] [עַד־עוֹלָ֔ם] até [פְּרָאִ֖ים] [מִרְעֵ֥ה] [עֲדָרִֽים]');
INSERT INTO verses VALUES (18344, 23, 32, 15, 'até [עָלֵ֛ינוּ] espírito espírito [וְהָיָ֤ה] e-será [לַכַּרְמֶ֔ל] [*וכרמל] [**וְהַכַּרְמֶ֖ל] [לַיַּ֥עַר]');
INSERT INTO verses VALUES (18345, 23, 32, 16, 'ושכן em-o-midbar juízo e-justica בכרמל תֵּשֵֽׁב׃');
INSERT INTO verses VALUES (18346, 23, 32, 17, 'e será obra-de הַצְּדָקָ֖ה שָׁל֑וֹם וַֽעֲבֹדַת֙ הַצְּדָקָ֔ה הַשְׁקֵ֥ט וָבֶ֖טַח até eternidade');
INSERT INTO verses VALUES (18347, 23, 32, 18, 'וְיָשַׁ֥ב povo-meu בִּנְוֵ֣ה שָׁל֑וֹם וּֽבְמִשְׁכְּנוֹת֙ מִבְטַחִ֔ים וּבִמְנוּחֹ֖ת שַׁאֲנַנּֽוֹת׃');
INSERT INTO verses VALUES (18348, 23, 32, 19, 'e-barad bredet ha-ya''ar u-bashiphla tishpal a-cidade');
INSERT INTO verses VALUES (18349, 23, 32, 20, 'asreikhem zoreiei sobre todo águas mashlachei regel- השור ve-ha-chamor');
INSERT INTO chapters VALUES (712, 23, 33, 24);
INSERT INTO verses VALUES (18350, 23, 33, 1, 'ai שֹׁדֵד e-tu não שָׁדּוּד וּבֹגֵד e-não nele nele כַּהֲתִימְךָ שֹׁדֵד תּוּשּׁד כַּנּלוֹתְךָ לִבְגּוֹד יִבְגּוּד em-te:');
INSERT INTO verses VALUES (18351, 23, 33, 2, 'yhwh [חָנֵּ֖נוּ] a-ti [קִוִּ֑ינוּ] foi [זְרֹעָם֙] [לַבְּקָרִ֔ים] também [בְּעֵ֥ת] [צָרָֽה]');
INSERT INTO verses VALUES (18352, 23, 33, 3, 'de-a-voz הָמ֔וֹן VAGAROSAMENTE-SE-MOVIMENTARAM עַמִּ֑ים מֵר֣וֹמְמֻתֶ֔ךָ נָפְצ֖וּ goyim:');
INSERT INTO verses VALUES (18353, 23, 33, 4, '[וְאֻסַּ֣ף] [שְׁלַלְכֶ֔ם] [אֹ֖סֶף] [הֶֽחָסִ֑יל] [כְּמַשַּׁ֥ק] [גֵּבִ֖ים] [שׁוֹקֵ֥ק] nele');
INSERT INTO verses VALUES (18354, 23, 33, 5, 'נִשְׂגָּ֣ב yhwh que שֹׁכֵ֖ן מָר֑וֹם enchei Sião juízo e justiça');
INSERT INTO verses VALUES (18355, 23, 33, 6, 'e-foi אֱמוּנַ֣ת עִתֶּ֔יךָ חֹ֥סֶן salvações sabedoria-de ודעת יראת yhwh ela אוצרו׃');
INSERT INTO verses VALUES (18356, 23, 33, 7, 'eis ארעל׃ צעקו׃ fora mensageiros-de paz מר יבכו׃');
INSERT INTO verses VALUES (18357, 23, 33, 8, 'נָשַׁ֣מּוּ מסילות שַׁבָּת passando caminho הפר ברית מס cidades não pensou Enos');
INSERT INTO verses VALUES (18358, 23, 33, 9, 'mas gemeram terra escarnecer לבanon completou-se ser o-sharon e-caaravah e-noer o-bashan e-karmel');
INSERT INTO verses VALUES (18359, 23, 33, 10, 'עַתָּה eu-elevar-me-ei dira yhwh agora eu-alçar-ei agora eu-levantarei');
INSERT INTO verses VALUES (18360, 23, 33, 11, 'voces-exultareis chashech tende-a-geração qash ruachchem fogo tochalchem');
INSERT INTO verses VALUES (18361, 23, 33, 12, 'e-sejam povo-es mishrofot soid qotsim kusuachim בָּאֵ֥שׁ yitztu');
INSERT INTO verses VALUES (18362, 23, 33, 13, 'ouvi distantes que faça e-sabem próximos minha-energia');
INSERT INTO verses VALUES (18363, 23, 33, 14, 'temam em-Sion pecadores agarraram-se tremor hipócritas quem יָג֣וּר para-nos fogo comendo-a quem morando a-nos de-fogueiros eternidade');
INSERT INTO verses VALUES (18364, 23, 33, 15, 'andou justiças e falantes— מֵֽישָׁרִ֑ים desdenhando em-vanidade de-trabalhos jovem das-suas-mãos de-apoio em-suborno fechando a-sua-orelha de-audição sangue e-fechando seus-olhos de-vistas com-mal');
INSERT INTO verses VALUES (18365, 23, 33, 16, 'ele membros-altos habitará lados-dele rochedos de-sua-altura para-seu-pão deu seus-aguas fiéis׃');
INSERT INTO verses VALUES (18366, 23, 33, 17, 'rei em-sua-belleza virem teus-olhos vejam-na terra de-a-longe');
INSERT INTO verses VALUES (18367, 23, 33, 18, 'לִבְּךָ֖ haverá temor onde-a conta onde-a pesa onde conta a os-magnates');
INSERT INTO verses VALUES (18368, 23, 33, 19, 'a povo não não תִרְאֶ֑ה povo fundura língua-impudente de-a-rumor zombado língua não-há em-inteligência');
INSERT INTO verses VALUES (18369, 23, 33, 20, 'vista Sião קרית de-nossos-congregações olhos-teus vejam-na Jerusalém tenda descanse tenda-de não conselheiros não partirá juntamentos-dele para sempre e-todo cordas-dele não se-separarão');
INSERT INTO verses VALUES (18370, 23, 33, 21, 'que se nome yhwh yhwh para-nós מְקוֹם- rios rivers largos יָדָ֑יִם não andará nele não pescador e-cidade majestoso não faça-o-passe-nos');
INSERT INTO verses VALUES (18371, 23, 33, 22, 'que yhwh nos-seja-julgador yhwh nos-seja-legislativo yhwh nossos-reis ele nos-seja-salvador');
INSERT INTO verses VALUES (18372, 23, 33, 23, 'nittashu teus-fios não sejam-fortes assim- vocês-tremam não se-espalharam sinal entao dividido até despojo multiplica pascos roubaram desprezo');
INSERT INTO verses VALUES (18373, 23, 33, 24, 'וּבַל־ diga habita me-revesti o-povo o-sentado nela elevado avon');
INSERT INTO chapters VALUES (713, 23, 34, 17);
INSERT INTO verses VALUES (18374, 23, 34, 1, 'aproximem-se nações para-ouvir e-a-nações o-ouvintes você-ouvirá a-terra e plenitude a-tֵבֵ֖ל e-todo seus-descendentes');
INSERT INTO verses VALUES (18375, 23, 34, 2, 'que ira a-yhwh sobre todo as-nações e-ira sobre todo seu-exército e-os-consagraram e-dos-deles-dar a-o-matador');
INSERT INTO verses VALUES (18376, 23, 34, 3, 'e-os-seus-impuros serão-lancados e-os-seus-cadáveres subia na-queima e-serão-moídos as-montanhas de-seu-sangue');
INSERT INTO verses VALUES (18377, 23, 34, 4, 'e-serão-amolecidos todo exercito os-céus e-nagoluu kas-sepher os-céus e-todo tzva-aam folha kinbol aleh meg-phen uknobelet miteanah');
INSERT INTO verses VALUES (18378, 23, 34, 5, 'porque rivvatha bas-shamayim eis behold sobre edom desce e-sobre povo meu devasso para-o-misso');
INSERT INTO verses VALUES (18379, 23, 34, 6, 'espada a-יהוה cheia sangue foi-declarada de-o-carne de-sangue carvalhos e-tauros de-o-carne rimas aies que sacrifício a-yhwh em-a-gordura e-sacrifício grande em-terra-de Edom');
INSERT INTO verses VALUES (18380, 23, 34, 7, 'e-descerão veados com-eles e-toros com אברים e-irrigará a-sua-terra de-seu-sangue e-a-poeira-deles do-seu-carneiro serão-tributados');
INSERT INTO verses VALUES (18381, 23, 34, 8, 'que dia vinganca para-יהוה ano-de pagamentos para-rivalizar צִיּֽוֹן');
INSERT INTO verses VALUES (18382, 23, 34, 9, 'e-vire-se as-suas-ribeiras para-fração e-seu-pó para-fuligem e-foi a-sua-terra para-fração que-arde-se');
INSERT INTO verses VALUES (18383, 23, 34, 10, 'noite e-no-dia não te-kbeh para-sempre subia fumaça-a de-o-geração para-o-geração ser-destruída-a para-o-sempre eternos-os não-há transitorio- nela');
INSERT INTO verses VALUES (18384, 23, 34, 11, 'e-eles-possuirão-a gata-a e-esquilo-o e-abelha-da-mel e-avestruz habitare-m nela e-esticar em-a corda-m sem-forma e pedras de vazio');
INSERT INTO verses VALUES (18385, 23, 34, 12, 'de-a-sua e-nao-ha nome reinado chamarão e-todo príncipes-a-sua serão afes:');
INSERT INTO verses VALUES (18386, 23, 34, 13, 'e-aleth armonoteha sirim qimosh ve-hochoh be-mibtsareha וְהָיְתָה֙ neveh tanim chatzir para-construir responde');
INSERT INTO verses VALUES (18387, 23, 34, 14, 'e-pegaram aies a iies e-seair chamaria seu rebanho ele-chama somente nome ela-calma lilit e-achou para-ela Manoah');
INSERT INTO verses VALUES (18388, 23, 34, 15, 'שָׁ֣מָּה qinnah kipoz e-t-mallete u-vake-ah ve-dagre-ha be-tzil-laha somente nome nos-aglomeramos day-yot mulher re-utatah');
INSERT INTO verses VALUES (18389, 23, 34, 16, 'dirshu de-em-cima-de yhwh yhwh uma uma não não ne-adarah mulher não não puserem-o ele de-sua-boca ele ele e-de-seu-espírito ele reuniram-no');
INSERT INTO verses VALUES (18390, 23, 34, 17, 'e-ele ele-jogou para-eles sorteio e-de-sua-mão a-eles a-eles com-a-flecha até eterno herdarão-o para-geração e-gera habitarão-o em-ela');
INSERT INTO chapters VALUES (714, 23, 35, 10);
INSERT INTO verses VALUES (18391, 23, 35, 1, 'alegrarão-os deserto e-seia e-alegrará aravah e-florescerá como-ajedrea');
INSERT INTO verses VALUES (18392, 23, 35, 2, 'florescerá se-tornará-verde e-se-rejubilará certamente revelou-a-alegria e-cantará glória de-o-Líbano נִתַּן־ para-ela beleza o-carvalho e-o-cedro elas verão glória-de- yhwh beleza Elohim-nosso');
INSERT INTO verses VALUES (18393, 23, 35, 3, 'fortificai-vos mãos fraquezas e-joelhos trôpegos [אַמֵּֽצוּ]');
INSERT INTO verses VALUES (18394, 23, 35, 4, 'dizei aos-precipitados coração fortaleceis eis temei-vos eis Elohim-vosso vengança vira ele Elohim ele יבוא e-salvar-vos');
INSERT INTO verses VALUES (18395, 23, 35, 5, 'entao vocês-serão-abertas os-olhos-de cegos veʾaznei surdos vocês-serão-abertas');
INSERT INTO verses VALUES (18396, 23, 35, 6, 'entao saltará como-veado pulando e-cantarão língua-de mudos porque se-abriram águas águas e-riviere na-aravah');
INSERT INTO verses VALUES (18397, 23, 35, 7, 'e-será o-sarab para-o-agam e-seca para-as-fontes águas na-nova de-taninim se-estendeu herba para-o-cane e-a-gomea');
INSERT INTO verses VALUES (18398, 23, 35, 8, 'וְהָיָה־ nome caminho e-o-caminho e-a-caminho será-chamada será-chamado para-ela não passara-o impuro o-caminho-de a-eles não caminho e-os-aviles não se-perderao');
INSERT INTO verses VALUES (18399, 23, 35, 9, 'não for nome leão e-arranca חַיּוֹת֙ não ele-alçará não ela-será-encontrada nome e-eles-foram redimidos');
INSERT INTO verses VALUES (18400, 23, 35, 10, 'e-redentos yhwh e-voltarão e-entrarão Siao em-a-risada e-em-a-alegria eternidade sobre cabeça-deles sasom ve-simcha yassigu venasu yagon va-anacha');
INSERT INTO chapters VALUES (715, 23, 36, 22);
INSERT INTO verses VALUES (18401, 23, 36, 1, 'e-houve be-arba dez ano para-o-rei Chizqiyáhu subir Sanheriv rei-de sobre sobre todo arei Judá as cidades: va-yitpesem');
INSERT INTO verses VALUES (18402, 23, 36, 2, 'e-enviou rei-de אַשּׁׁוּר ׀ a chefe-de sheqe mil-lakhi-sh yeru-shal-ma-ha a o-rei Ezequias be-chail pesado e-estacionou-se bi-te-alat ha-brer-ka ha-ele-yona bi-mesil-lat campo-de ko-ves');
INSERT INTO verses VALUES (18403, 23, 36, 3, 'e-ele-saiu a-ele el-yaki-im filho-de chi-li-ya-hu que sobre a-casa ve-she-bna הַסּוֹפֵ֔ר e-joah filho-de asaf o-mencionador-versículo');
INSERT INTO verses VALUES (18404, 23, 36, 4, 'E-disse a-eles muito sheqeh imru- por-favor a חִזְקִיָּ֑הוּ assim disse o-rei a-grande rei Assíria mah ha-bitahon este que batachtah-');
INSERT INTO verses VALUES (18405, 23, 36, 5, 'dissesse somente palavra-de lábios-de-duas etza ugvurah para-a-guerra agora que quem batachtah porque rebelaste em-mim');
INSERT INTO verses VALUES (18406, 23, 36, 6, 'eis confiaste sobre de-apoio o-guadameiro a-fragmentação este sobre Egito que será-marca-te homem sobre-ele וּבָ֥א com-a-sua-mão e-perfura-la assim faráoh rei-de Egito para-todo os-que-confiam sobre-ele');
INSERT INTO verses VALUES (18407, 23, 36, 7, 'e-se dirás a-mim a yhwh nosso-Elohim confi-amos porventura-não ele que retirou E-disse a em-sus-tas-seu e-a de-araes-seu E-disse para-Judá espírito diante-de o-altar este in-cli-na-vos');
INSERT INTO verses VALUES (18408, 23, 36, 8, 'e-agora en-trelaç-ou-se por-favor a Adonai o-rei Assíria a-ti a-ti duas-mil cavalos se a-ti para-dar a-ti cavaleiros sobre-eles');
INSERT INTO verses VALUES (18409, 23, 36, 9, 'e-como re-tornar-ás a face-de Paate um servos-de Adonai os-pequeninos e-ela-se-fez-confiante a-ti sobre Egito para-o-carro e-para-os-cavaleiros');
INSERT INTO verses VALUES (18410, 23, 36, 10, 'e-agora se-não-de-modo-diferente yhwh עָלִ֛יתִי sobre a-terra esta yhwh disse disse folhas-de עֲלֵ֛ה a a-terra a-esta e-ele-a-destruirá');
INSERT INTO verses VALUES (18411, 23, 36, 11, 'E-disse Eliaquim e-Shebna e-Joaach a muito oquebeba diga- por-favor que teus-servos aramita porque šōmeʿim anachnu e-a tadaber a-nós judeita em-orelhas-de o-povo que sobre ha-choma');
INSERT INTO verses VALUES (18412, 23, 36, 12, 'E-disse chefe-de sheqeh ha-el teu-senhor e-para-ti enviou-me Adonai para-falar a as-palavras estes porventura-não sobre os-homens os-habitam sobre o-muro para-comer a ve-lishtot a com-vos');
INSERT INTO verses VALUES (18413, 23, 36, 13, 'e-yaa-amod chefe-de E-chamou E-chamou em-voz- E-disse judeita E-disse shime''u a palavras o-rei o-grande rei Aššúrā');
INSERT INTO verses VALUES (18414, 23, 36, 14, 'assim disse o-rei a a-vós a-vós que porque não podia que a-vós');
INSERT INTO verses VALUES (18415, 23, 36, 15, 'e-a yabta a-vos Chizqiyahu dizendo yhwh dizendo yhwh não yhwh não dê-vos a-cidade esta na-mão-de rei Aššúrā');
INSERT INTO verses VALUES (18416, 23, 36, 16, 'a ouçam a que porque disse disse o-rei Assiria fazei- comigo bênção e-saiam a-mim e-comam homem-de seus-olhos e-homem figa-seu e-bebam homem e-sejam cisterna-seu');
INSERT INTO verses VALUES (18417, 23, 36, 17, 'até vem-me e-tomaria vos a terra como-a-terra-de-voces terra terra pão terra pão e-de-vinhedos');
INSERT INTO verses VALUES (18418, 23, 36, 18, 'para-que-não ele-conduzira a-vos dizendo yhwh yhwh ele-nos-salvaria que-voces-salvaram Elohim-de as-nações homem a אַרְצ֔וֹ de-mão-de rei Aššúrā');
INSERT INTO verses VALUES (18419, 23, 36, 19, 'onde-está Elohim-de חֲמָת֙ e-arpad onde Elohim-de de-seiscentos-e-vinte e-quando salvai a שֹׁמְר֖וֹן de-mim');
INSERT INTO verses VALUES (18420, 23, 36, 20, 'quem em-todo Elohim-de as-terra estes que salvai a yhwh de-mim porque salvará yhwh a Jerusalém de-mim');
INSERT INTO verses VALUES (18421, 23, 36, 21, 'e-eles-ficaram-em-silêncio e-não ele ele palavra porque mandamento dizendo não para-dizer não responder-lhe');
INSERT INTO verses VALUES (18422, 23, 36, 22, 'E-veio Eliaquim filho-de chilikiyahu que sobre a-casa e-Shaphan o-escritor e-Joaquim filho-de Asafe o-que-menciona a-ele Ezequias quebrados-de em-roupas ויאגוּ a-ele a palavras-de muito beba-o');
INSERT INTO chapters VALUES (716, 23, 37, 38);
INSERT INTO verses VALUES (18423, 23, 37, 1, 'e-houve כִּשְׁמֹ֙עַ֙ o-rei חִזְקִיָּ֔הוּ e rasgou a de-seus-vestidos e-ele-vestiu-se no-saqu E-veio yhwh yhwh');
INSERT INTO verses VALUES (18424, 23, 37, 2, 'e-yi-shelakh a Eliacim que sobre a-casa e-את Senaia o-escrevente e-את anciaos-de os-sacerdotes vestindo-se em-o-sacrisdócio a יְשַֽׁעְיָ֥הוּ filho-de אומץ הַנָּבִֽיא׃');
INSERT INTO verses VALUES (18425, 23, 37, 3, 'e-disseram a-ele assim disse חִזְקִיָּ֔הוּ dia-de tristeza e-repreensão o-dia o-dia que porque filhos filhos até não-havia e-força não-havia para-parir');
INSERT INTO verses VALUES (18426, 23, 37, 4, 'tal-mas ele-ouvirá yhwh Elohim-teu com palavras-de dê-a-beber que seu-enviado rei-de [שְׁלָח֨וֹ] adonai-o para-maldizer Elohim viveu e-repreender vida que ouviu yhwh teu-Elohim yhwh oração por-causa-de a-restante que-foi-encontrada-a');
INSERT INTO verses VALUES (18427, 23, 37, 5, 'e-vieram [עַבְדֵ֛י] o-rei Ezequias a');
INSERT INTO verses VALUES (18428, 23, 37, 6, 'E-disse a-eles יְשַֽׁעְיָ֔הוּ assim dizeis-vós a senhor-vosso assim disse yhwh a de-diante-de מִפְּנֵי palavras-as que ouvi-que que repreendeu na-á-rei rei-de Assíria me-lembra-me');
INSERT INTO verses VALUES (18429, 23, 37, 7, 'eis-me dando nele espírito e-ouviu a-notícia e-retornou a terra-dele e-o-derrotou com-a-espada na-sua-terra');
INSERT INTO verses VALUES (18430, 23, 37, 8, 'e-ele-voltou chefe-de o-apagaria e-ele-achou a rei Assíria que sobre que porque ouviu porque partiu-se de-Malqueide');
INSERT INTO verses VALUES (18431, 23, 37, 9, 'E-ouviu sobre Tiraca dizendo sair dizendo yátsá para-lutar contigo E-ouviu e-enviou dizendo a Ezequias para-dizer');
INSERT INTO verses VALUES (18432, 23, 37, 10, 'assim dizeis a Hzqiyahu dizendo Judá dizendo a tu teu-Elohim que dizendo não nele dizendo não tinnaten Jerusalém na-mão-de rei Aššúrā');
INSERT INTO verses VALUES (18433, 23, 37, 11, 'eis tu tu que asu reis-de Assuér para-todo ha-áratsot lehakhrimam e-tu tinnatzel');
INSERT INTO verses VALUES (18434, 23, 37, 12, 'hahitzilu a-eles Elohim-de as-nações que hishtichitu avotai a Gozan e-a Harã e-contínuo e-filhos-de עֶ֖דֶן que em-telashar');
INSERT INTO verses VALUES (18435, 23, 37, 13, 'onde rei-de חֲמָת֙ e-rei אַרְפָּ֔ד e rei para a cidade sefarvayim deitou-se e foi');
INSERT INTO verses VALUES (18436, 23, 37, 14, 'E-tomou Cezíah a os livros de-mão-de os-mensageiros ve-yikraehu e-subiu yhwh yhwh e os explicou Ezequias yhwh yhwh');
INSERT INTO verses VALUES (18437, 23, 37, 15, 've-yitpallel חִזְקִיָּ֔הוּ a dizendo para-dizer');
INSERT INTO verses VALUES (18438, 23, 37, 16, 'yhwh exércitos Elohim-de Israel habitou os-querubins você- ele הָֽאֱלֹהִים a-todo para-todo a-terra tu tu oashtata a os-céus e-a a-terra');
INSERT INTO verses VALUES (18439, 23, 37, 17, 'e levantou-se yhwh seu-ouvido ushema pekaah yhwh yhwh e-vê-se e-ouvires a todo palavras-de Sancarív que enviou para-desafiá-lo Elohim viveu');
INSERT INTO verses VALUES (18440, 23, 37, 18, 'realmente yhwh e-destruíram reis-de Assuér a todo ha-aratzot e-a terr-os');
INSERT INTO verses VALUES (18441, 23, 37, 19, 'e dará a Elohim-deles que não não Elohim que porque se árvore de-mãos- homem árvore e pedra e destruí-los:');
INSERT INTO verses VALUES (18442, 23, 37, 20, 'e-agora yhwh nosso-Elohim salva-nos de-sua-mão e saibam todo a-terra a-terra yhwh tu yhwh apenas de ti:');
INSERT INTO verses VALUES (18443, 23, 37, 21, 'e-enviou Isaías filho-de Amots dizendo Ezequias yhwh assim disse yhwh Elohim-de Israel que ora-esteve a-mim a Sanheriv rei Aššúrā');
INSERT INTO verses VALUES (18444, 23, 37, 22, 'este a-palavra que yhwh yhwh sobre-ele a-ti a ti a-ti para-ti virgem filha-de Sião de-você cabeça soltou-a filha-de Jerusalém');
INSERT INTO verses VALUES (18445, 23, 37, 23, 'a quem humilhaste-me וְגִדַּ֔פְתָּ e-sobre quem elevou-a קּ֑וֹל e-ela-alçou-a מָר֛וֹם olhos-teus a santo Israel');
INSERT INTO verses VALUES (18446, 23, 37, 24, 'na-mão-de seus-servos [חֵרַ֣פְתָּ] Adonai e-disse E-disse meu-carro eu עָלִ֛יתִי מְר֥וֹם as-montanhas ירכתי Líbano וְאֶכְרֹ֞ת קוֹמַ֤ת אֲרָזָיו֙ da escolha בְּרֹשָׁ֔יו e-irei altura o-seu-fim floresta כַּרְמִלּֽוֹ׃');
INSERT INTO verses VALUES (18447, 23, 37, 25, 'eu farei-o e-beberei-a águas וְאַחְרִב֙ com-a-palma- פְּעָמַ֔י todo יְאֹרֵ֥י מַזָּר׃');
INSERT INTO verses VALUES (18448, 23, 37, 26, 'acaso-nao ouviste-a לְמֵֽרָחוֹק֙ a-ela fiz oriente ao-norte e-formei-a agora trarei-a e se torne para-levantar galés nictímines cidades nas rochas,:');
INSERT INTO verses VALUES (18449, 23, 37, 27, 'e-os-seus-habitantes capitais de mão חַ֖תּוּ ובושו היוּ erva שַׂדֶה וִירַק דֶשֶא חֲצִיר גָּגּוֹת e-sua-maneira diante-de קָמָה׃');
INSERT INTO verses VALUES (18450, 23, 37, 28, 'וְשִיבְתֵּךָ֛ וְצֵאתֵךָ֥ e-vindo-a-voce יָדָ֑עְתִּי e-a הִֽתְרַגֶּזְךָ֥ a-mim');
INSERT INTO verses VALUES (18451, 23, 37, 29, 'porque הִתְרַגֶּזְךָ֣ a-mim וְשַׁאֲנַנְךָ֖ subir בְאָזְנָ֑י e-eu-posso חַחִ֜י בְּאַפֶּ֗ךָ וּמִתְגִּי֙ בִּשְׂפָתֶ֔יךָ e-voltarei-a-voce no-caminho que בָּאתָ nela');
INSERT INTO verses VALUES (18452, 23, 37, 30, 'e-este para-ti הָא֔וֹת אָכ֤וֹל הַשָּׁנָה֙ sapiacha e-no-ano a-segunda shachis e-no-ano הַשְׁלִישִ֗ית זִרְע֧וּ וְקִצְר֛וּ וְנִטְע֥וּ כְרָמִ֖ים פריהוּמ׃');
INSERT INTO verses VALUES (18453, 23, 37, 31, 'e-aumentara פליטה֣ת casa-de Judá הנישארָה שורשׁ abaixo e fez פרי para-cima');
INSERT INTO verses VALUES (18454, 23, 37, 32, 'que de-jerusalim תיצא שארית e-fuga de-montanha-de Sião קינאת yhwh exércitos tu-farás esta');
INSERT INTO verses VALUES (18455, 23, 37, 33, 'portanto assim yhwh yhwh a não Assíria não virá a a-cidade esta e-não יורה nome /DDD e-não JQKDMMNNH MGN e-não יִשְׁפֹּ֥ךְ sobre-a-ela SLLH');
INSERT INTO verses VALUES (18456, 23, 37, 34, 'no-caminho que veio בָּ֣הּ YSHVB e-a não esta não יבוא oráculo-de yhwh');
INSERT INTO verses VALUES (18457, 23, 37, 35, 'e-ganoti sobre a-cidade esta LHSYAH LMANI e-para-alma Davi AVDI');
INSERT INTO verses VALUES (18458, 23, 37, 36, 'VYCTA anjo yhwh yhwh em-acampamento-de Assíria cem e-oitenta e-cinco mil e-eles-se-levantaram-cedo em-a-manhã e-eis todos eles FGRIM mortos∶');
INSERT INTO verses VALUES (18459, 23, 37, 37, 'e-ele-partiu E-andou וַיָּ֖שָׁב Sancarív rei-de Assíria e-habitou em-Binoveh');
INSERT INTO verses VALUES (18460, 23, 37, 38, 'e-houve ele adoração∶ casa-de cetro∶ Elohim∶ e Adramélux e Sarácerto filhos-dele matá-lo b''cherev e-elas fugiram∶ terra terra e-reinou esar- Chadon filho-seu em-lugar-dele');
INSERT INTO chapters VALUES (717, 23, 38, 22);
INSERT INTO verses VALUES (18461, 23, 38, 1, 'em-os-dias aqueles chalah Ezequias la-mut vayyavo'' a-ele Yeshayahu filho-de Amots E-disse a-ele a-ele yhwh disse yhwh que lebetekha tu morreu tu e-não tichye:');
INSERT INTO verses VALUES (18462, 23, 38, 2, 've-yassave a sua força sua-face a haqir e-ele-orou a yhwh');
INSERT INTO verses VALUES (18463, 23, 38, 3, 'E-disse anah yhwh lembra-de por-favor a que andei em-te be-emeth uvel-lev paz vehatov nos-teus-olhos faça וַיֵּ֥בְךְּ Ezequias porque grande');
INSERT INTO verses VALUES (18464, 23, 38, 4, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (18465, 23, 38, 5, 'הָל֞וֹךְ e-dirás a Chizqiyáhu yhwh disse yhwh Elohim-de Davi pai-teu ouvi a tphilá-teka vi a dim`á-teka eis-me [שָׁנָֽה] sobre a-terra cinco dez anos');
INSERT INTO verses VALUES (18466, 23, 38, 6, 've-mikaf rei-de ʾaššur atzilkeka e-a a-cidade esta ve-ganoti sobre a-cidade a esta');
INSERT INTO verses VALUES (18467, 23, 38, 7, 'e-este a-você a-sinal yhwh yhwh que yhwh yhwh a a-palavra este que palavra');
INSERT INTO verses VALUES (18468, 23, 38, 8, 'eis-me מֵשִׁ֣יב a sombra as-ascensões que descer-a em-as-ascensões Acaz no-sol אֲחֹרַנִּ֖ית dez מַעֲל֑וֹת e-retornou o-sol dez ascensões em-as-ascensões que descer-a');
INSERT INTO verses VALUES (18469, 23, 38, 9, 'escrita [לְחִזְקִיָּ֣הוּ] rei-de Judá [וַיְחִ֖י] e-viveu [sem-traducao]');
INSERT INTO verses VALUES (18470, 23, 38, 10, 'eu disse-ei- em-o-meus-dias meus-dias irei-eu בְּשַׁעֲרֵ֣י sheol fui-contado-eu resto anos-meus');
INSERT INTO verses VALUES (18471, 23, 38, 11, 'dissesse não verei Yah יָהּ a-vida ה-חַיִּים homem olharei homem ainda com יוֹשְׁבֵי חָדֶל');
INSERT INTO verses VALUES (18472, 23, 38, 12, 'דוֹרִי נִסַּע וְנִגְלָה de-mi כְּאוֹהֶל רוֹעִי קִפַּדְתִּי como-tece vivas de-moeda ele-me-estrague desde-dia até noite você-me-complete');
INSERT INTO verses VALUES (18473, 23, 38, 13, 'eu-estabeleci até manhã como-leão assim ele-partirá todo עצמותאי desde-dia até noite tashlimeni');
INSERT INTO verses VALUES (18474, 23, 38, 14, 'kesus agur assim atzafzef ehage kayonah dalu meus-olhos lamarom Adonai asqah- para-mim arveni');
INSERT INTO verses VALUES (18475, 23, 38, 15, 'que falarei e-disse- a-mim e-ele fez eu-contarei todo os-anos-meus sobre מַ֥ר alma-de-mim');
INSERT INTO verses VALUES (18476, 23, 38, 16, 'Adonai sobre-eles viverão e-para-todo- neles chayyei espírito-meu e-vivificar-me e-viver-me-');
INSERT INTO verses VALUES (18477, 23, 38, 17, 'eis לְשָׁל֖וֹם amargo para-mim amargo e-tu apaixonaste-te alma-minha de-o-sacrifício que porque lançaste depois-de costas-teu todo pecados-meus');
INSERT INTO verses VALUES (18478, 23, 38, 18, 'que não Sheol confessar-te מוות [יְהַלְלֶ֑ךָּ] não [יֽוֹרְדֵי־ב֖וֹר] Yoredi- da cova a אֲמִתֶּֽךָ׃');
INSERT INTO verses VALUES (18479, 23, 38, 19, 'vida vida ele [יוֹדֶ֖ךָ] [כָּמ֣וֹנִי] o-dia pai [לְבָנִ֔ים] [יוֹדִ֖יעַ] a');
INSERT INTO verses VALUES (18480, 23, 38, 20, 'yhwh para-me-salvar e-musica-meus namoscaremos todo dias-de vivos-nosso yhwh casa yhwh');
INSERT INTO verses VALUES (18481, 23, 38, 21, 'E-disse Yeshayahu elevem-eles davelãt tãenim e-movam-se sobre a sãin e-viva');
INSERT INTO verses VALUES (18482, 23, 38, 22, 'E-disse Ezequias que sinal que subirei casa yhwh');
INSERT INTO chapters VALUES (718, 23, 39, 8);
INSERT INTO verses VALUES (18483, 23, 39, 1, 'em-o-tempo aquela enviou Меродах bal-adan filho-de bal-adan rei-de Babilônia sefarim e oferta que חִזְקִיָּ֑הוּ E-ouviu porque chala e-forte-seja');
INSERT INTO verses VALUES (18484, 23, 39, 2, 'e-se-rejou al-eyhem chizkiyyahu e levantou-se a casa a o prata e-a o ouro e-a as báseis e-את o-azeite התוב e-את todo de-a-casa utensílios-dele e-a todo que foi achado em-o-salas-dele não foi palavra que não e mostrou-se a sua força em-casa-dele e-em-todo sua soberania:');
INSERT INTO verses VALUES (18485, 23, 39, 3, 'E-veio Isaías o-profeta a o-rei E-disse a-ele a-ele que Amarū os-homens estes uMeyain virao a-ti E-disse חִזְקִיָּ֔הוּ da-terra-de Roká entraram a-mim Mibavel');
INSERT INTO verses VALUES (18486, 23, 39, 4, 'E-disse que Ra''u bBeiteka E-disse Chizqiyáhu a todo que bBeiti Ra''u não foi palavra que não mostraram-lhes em-minhas-salas');
INSERT INTO verses VALUES (18487, 23, 39, 5, 'E-disse [יְשַׁעְיָ֖הוּ] a [שְׁמַ֖ע] ouviu palavra-de yhwh');
INSERT INTO verses VALUES (18488, 23, 39, 6, 'eis [יָמִ֣ים] [בָּאִים֒] [וְנִשָּׂ֣א] todo que [בְּבֵיתֶ֗ךָ] e-que [אָצְר֧וּ] [אֲבֹתֶ֛יךָ] até o-dia este Babilônia não disse yhwh disse yhwh');
INSERT INTO verses VALUES (18489, 23, 39, 7, 'וּמִבָּנֶ֜יךָ que יֵצְאוּ de-ti que תּוֹלִיד יִקְּחֻ e-sejam eunucos na-casa-de-adoração rei Babilônia');
INSERT INTO verses VALUES (18490, 23, 39, 8, 'E-disse Chizqiyahu a bom bom palavra-de yhwh E-disse que será porque será shalom e-verdade nos-meus-dias');
INSERT INTO chapters VALUES (719, 23, 40, 31);
INSERT INTO verses VALUES (18491, 23, 40, 1, 'consolai-vos consolai-vos meu-povo dirá vosso-Elohim');
INSERT INTO verses VALUES (18492, 23, 40, 2, 'falai sobre coração Jerusalém e-convocai que porque encheu-se que porque agradou-nos que porque tomou-a yhwh yhwh duplicado em-todo suas-pecados');
INSERT INTO verses VALUES (18493, 23, 40, 3, 'voz chamando em-o-deserto [פַּנּ֖וּ] o-caminho-de yhwh fazer-retas בערבבה estrada א-לוהינו');
INSERT INTO verses VALUES (18494, 23, 40, 4, 'todo vale ele-elevar-se-á e-todo monte-de e-colina cairão e-será o-que-vira-se para-o-lado e-os-riscos para-a-fenda');
INSERT INTO verses VALUES (18495, 23, 40, 5, 'e-se-revelou glória-de yhwh e-viram todo carne que porque yhwh yhwh palavra');
INSERT INTO verses VALUES (18496, 23, 40, 6, 'voz disse chamou e-disse que clamarei todo o-carne capim e-todo misericórdia-sua como-floresce o-campo');
INSERT INTO verses VALUES (18497, 23, 40, 7, 'יָבֵ֤שׁ חָצִיר֙ naveleira tsits que espírito yhwh foi-levada nele assim chatzir o-povo');
INSERT INTO verses VALUES (18498, 23, 40, 8, 'deserto chatzir idiota floresce e-palavra-de nosso-Elohim levantar-se para-eternidade');
INSERT INTO verses VALUES (18499, 23, 40, 9, 'sobre monte-de alto sobre- para-ti anunciando Sião ergue com-poder קוֹלֵ֔ךְ anunciando Jerusalém ergue a Tira''i eis le-arei Judá hein Elohim-vosso');
INSERT INTO verses VALUES (18500, 23, 40, 10, 'eis Adonai yhwh be-chazaq vira וּזְרֹע֖וֹ moshelah a-ele eis sakaro com-ele uphulato diante-de-ele');
INSERT INTO verses VALUES (18501, 23, 40, 11, 'keroe ederoh yirehe bizro''o reunirá pássaros e-em-seu-peito levantará subidas guiará');
INSERT INTO verses VALUES (18502, 23, 40, 12, 'quem medirá águas águas e-ceus em-zarolho tornará e-todo [עֲפַ֣ר] a-terra a-terra e-ele-calou em-a-peso harim e-galhos em-as-balancas');
INSERT INTO verses VALUES (18503, 23, 40, 13, 'quem tu-fazes yhwh espírito yhwh e-homem seu-conselho para-o-dizer-lhe-verso-final');
INSERT INTO verses VALUES (18504, 23, 40, 14, 'a quem conselheiro e-ele-entendeu-o e-ele-instruiu-o בהורах juízo e-ele-ensinou-o conhecimento e-caminho entendimentos fazendo-saber-o');
INSERT INTO verses VALUES (18505, 23, 40, 15, 'eis nações como-mar de-medida e-como-brincadeira de-moedas foram-contados eis íyím como-direito tomará-');
INSERT INTO verses VALUES (18506, 23, 40, 16, 'e-de-a não-há de em-o e-da-sua-vida não-há de subida-');
INSERT INTO verses VALUES (18507, 23, 40, 17, 'todo as-nações como-de-nenhum diante-de-lho de-a-vacuidade e-da-vacuidade se-consideraram a-ele');
INSERT INTO verses VALUES (18508, 23, 40, 18, 'e-a quem vocês-se-representarão El e-que a-ele vocês-disporão a-ele');
INSERT INTO verses VALUES (18509, 23, 40, 19, 'o-idolo derramou escultor e-prateleiro em-o-ouro ele-espalhará-no e-ferragens prata que-funde;');
INSERT INTO verses VALUES (18510, 23, 40, 20, 'o-mesquinho oferta árvore não ele-escurecerá ele-escolherá o-fundidor חָכָם יְבַקֶּשׁ- a-ele não escultura não será-movido:');
INSERT INTO verses VALUES (18511, 23, 40, 21, 'não vós-sabereis porventura-não vós-ouvir-eis acaso-nao foi-dito de-cabeça a-vós não-verdade se-entendeis mostrando-o-s a-terra');
INSERT INTO verses VALUES (18512, 23, 40, 22, 'הַיּוֹשֵׁב֙ sobre a-terra a-terra -e-seus-habitantes como-os-grilos o-esticando-o como-a-couve céus e-ele-os-alargou-os como-o-tenda para-sentar-se');
INSERT INTO verses VALUES (18513, 23, 40, 23, 'o-dando-o rosas para-a-nada juízes terra vazio fez');
INSERT INTO verses VALUES (18514, 23, 40, 24, 'certamente não certamente mesmo certamente plantaram ira não [וְגַם־נָשַׁ֤ף] na-terra tronco-deles e-também exalou neles e-seca-forem e-temporada como-cinzas tire-os');
INSERT INTO verses VALUES (18515, 23, 40, 25, 'e-a quem se-me-assemelhem e-e-igualarei dirá santo');
INSERT INTO verses VALUES (18516, 23, 40, 26, 'tirem- vossos-olhos vossos-olhos e-vede Estas criou אֵלֶּה seu-exército em-número seu-exército chamaria no-nome-de ele-chamará de-muitos forças e-forte não homem não nós-nos-separamos-verso-final');
INSERT INTO verses VALUES (18517, 23, 40, 27, 'por-que dirás Jacó e-você-fala Israel eu-me-ocultei meu-caminho de-yhwh e-de-meus-elohimes meu-julgamento ele-passará-verso-final');
INSERT INTO verses VALUES (18518, 23, 40, 28, 'porventura-não sab-e-s-tu se não você-ouviu eternidade para-algum-tempo-eterno-separador yhwh criador קְצֽוֹת a-terra não se-fatigue e-não trabalhe-se não-há pesquisa para-a-sua-comprensão');
INSERT INTO verses VALUES (18519, 23, 40, 29, 'deu para-o-se-fatigue força e-a-falta-de energia corpo multiplicará');
INSERT INTO verses VALUES (18520, 23, 40, 30, 'e-eles-se-fatigam os-jovens e-eles-se-esforçam e-os-moços caem serão-enganados');
INSERT INTO verses VALUES (18521, 23, 40, 31, 'e-os-timoratos yhwh trocarão força subirão lado como-os-águias corram-no e-não trabalharão-eles irao e-não cansar-se-ão');
INSERT INTO chapters VALUES (720, 23, 41, 29);
INSERT INTO verses VALUES (18522, 23, 41, 1, 'o-ararem-no a-mim iies e-a-nações trocarão-eles força se-aproximarão entao dirão-eles juntos para-o-julgamento nos-achegaremos');
INSERT INTO verses VALUES (18523, 23, 41, 2, 'quem acordou do-leste justiça chamá-lo-o para-a-pé-dele יִתֵּן para-diante-dele nações e-reis deram-se dará como-pó sua espada como-feno [נִדָּ֖ף] seu-arco');
INSERT INTO verses VALUES (18524, 23, 41, 3, 'perseguirá-los passará שָׁל֑וֹם אֹ֥רַח com-seus-pés não virá:');
INSERT INTO verses VALUES (18525, 23, 41, 4, 'quem fez e-fará chamou as-gerações do-começo yhwh yhwh primeiro e-a os-últimos eu- ela');
INSERT INTO verses VALUES (18526, 23, 41, 5, 'viram rios e-tremem pontas a-terra tremeo se-aproximam e-vieram');
INSERT INTO verses VALUES (18527, 23, 41, 6, 'homem a seu-proximo יעזו׃ e-para-seu-irmão diga [sem-traducao]');
INSERT INTO verses VALUES (18528, 23, 41, 7, 'e-ele-fortaleceu fabricante a fundidor escorredor [אֶת־ה֣וֹלֶם] a formador vez bom ele bom ele não com-nosso não será-movido:');
INSERT INTO verses VALUES (18529, 23, 41, 8, 'e-tu Israel servo-meu Jacó que escolhi-te semente Abraão meu-amado');
INSERT INTO verses VALUES (18530, 23, 41, 9, 'que fortaleci-te das-pontas a-terra e-dos-altos-dele chama-te e disse a-ti meu-escravo- tu escolhi-te e-não [sem-traducao]');
INSERT INTO verses VALUES (18531, 23, 41, 10, 'a que porque [אַל־תִּשְׁתָּ֖ע] eu a [אִמַּצְתִּ֙יךָ֙] porque eu teu-Elohim [צִדְקִֽי] também [sem-traducao] também [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18532, 23, 41, 11, 'eis [יֵבֹ֙שׁוּ֙] [וְיִכָּ֣לְמ֔וּ] todo [הַנֶּחֱרִ֣ים] sobre-ti [יִֽהְי֥וּ] [כְאַ֛יִן] [וְיֹאבְד֖וּ] homens-de [רִיבֶֽךָ]');
INSERT INTO verses VALUES (18533, 23, 41, 12, '[תְּבַקְשֵׁם֙] e-não [תִמְצָאֵ֔ם] homens-de [מַצֻּתֶ֑ךָ] serao [כְאַ֛יִן] [וּכְאֶ֖פֶס] homens-de [מִלְחַמְתֶּֽךָ]');
INSERT INTO verses VALUES (18534, 23, 41, 13, 'que eu yhwh teu-Elohim contendo [יְמִינֶ֑ךָ] [הָאֹמֵ֥ר] a-ti a temas eu [sem-traducao]');
INSERT INTO verses VALUES (18535, 23, 41, 14, 'a [תּוֹלַ֣עַת] carne-carnuda Jacó [יִשְׂרָאֵ֑ל] Israel eu [נְאֻם־יְהוָ֔ה] oráculo-de yhwh [יִשְׂרָאֵֽל] santo Israel');
INSERT INTO verses VALUES (18536, 23, 41, 15, 'eis [שַׂמְתִּ֗יךְ] [לְמוֹרַג֙] esmaga novo בעאל [פִּֽיפִיּ֑וֹת] [תָּד֤וּשׁ] montes [וְתָדֹ֔ק] e-galhos [כַּמֹּ֥ץ] [תָּשִֽׂים]');
INSERT INTO verses VALUES (18537, 23, 41, 16, 'תִּזְרֵם֙ e-Espírito-de [תִּשָּׂאֵ֔ם] [וּסְעָרָ֖ה] [תָּפִ֣יץ] eles e-tu se regozijará em-יהוה em santidade Israel [תִּתְהַלָּֽל׃]');
INSERT INTO verses VALUES (18538, 23, 41, 17, '[הָעֲנִיִּ֨ים] [וְהָאֶבְיוֹנִ֜ים] [מְבַקְשִׁ֥ים] águas e-não לְשׁוֹנָ֖ם [בַּצָּמָ֣א] [נָשָׁ֑תָּה] eu yhwh [אֶעֱנֵ֔ם] Elohim-de Israel não [אֶעֶזְבֵֽם]');
INSERT INTO verses VALUES (18539, 23, 41, 18, '[אֶפְתַּ֤ח] sobre [נְהָר֔וֹת] rios e-em [מַעְיָנ֑וֹת] [אָשִׂ֤ים] [מִדְבָּר֙] מדבר [וְאֶ֥רֶץ] águas [לְמוֹצָ֥אֵי] secou [sem-traducao] águas');
INSERT INTO verses VALUES (18540, 23, 41, 19, 'darei bamidbar [אֶ֣רֶז] [שִׁטָּ֔ה] [וַהֲדַ֖ס] וְעֵ֣ץ óleo enganos [בָּעֲרָבָ֗ה] [בְּר֛וֹשׁ] [תִּדְהָ֥ר] [וּתְאַשּׁ֖וּר] juntos-verso');
INSERT INTO verses VALUES (18541, 23, 41, 20, 'para-propósito-de temerao [וְיֵדְע֗וּ] [וְיָשִׂ֤ימוּ] [וְיַשְׂכִּ֙ילוּ֙] juntos que mão-de yhwh [זֹּ֑את] [וּקְד֥וֹשׁ] [יִשְׂרָאֵ֖ל] Israel [sem-traducao]');
INSERT INTO verses VALUES (18542, 23, 41, 21, '[קָרְב֥וּ] [רִֽיבְכֶ֖ם] dira yhwh [הַגִּ֙ישׁוּ֙] [עֲצֻמ֣וֹתֵיכֶ֔ם] dirá rei Jacó');
INSERT INTO verses VALUES (18543, 23, 41, 22, '[יַגִּ֙ישׁוּ֙] 并述说 para-nós a que [תִּקְרֶ֑ינָה] [הָרִאשֹׁנ֣וֹת] que eis-aqui [הֵ֗נָּה] [הַגִּ֜ידוּ] [וְנָשִׂ֤ימָה] [לִבֵּ֙נוּ֙] [וְנֵדְעָ֣ה] ou [א֥וֹ] [הַבָּא֖וֹת]');
INSERT INTO verses VALUES (18544, 23, 41, 23, 'הַגִּ֙idoּ֙ [הָאֹתִיּ֣וֹת] [לְאָח֔וֹר] [וְנֵ֣דְעָ֔ה] que Elohim vós também [וְתָרֵ֔עוּ] [וְנִשְׁתָּ֖עָה] [*ונרא] juntos-verso');
INSERT INTO verses VALUES (18545, 23, 41, 24, 'eis vós [וּפָעָלְכֶ֖ם] [מֵאָ֑פַע] [תּוֹעֵבָ֖ה] תּוֹעֵבָה יִבְחַ֥ר em-vos:');
INSERT INTO verses VALUES (18546, 23, 41, 25, '[הַעִיר֤וֹתִי] Mitsafon [וַיַּ֔את] do oriente- chamaria chamar [וְיָבֹ֤א] E-veio [כְּמוֹ־חֹ֔מֶר] como [יוֹצֵ֖ר] [יִרְמָס־טִֽיט] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18547, 23, 41, 26, 'quem [מֵרֹאשׁ֙] [וְנֵדָ֔עָה] [וּמִלְּפָנִ֖ים] [וְנֹאמַ֣ר] [צַדִּ֑יק] certamente tambem certamente [אֵ֣ין] mesmo certamente [אֵין־שֹׁמֵ֖עַ] nariz não-há ouviu [sem-traducao]');
INSERT INTO verses VALUES (18548, 23, 41, 27, 'resheon [לְצִיּ֖וֹן] eis [הִנָּ֑ם] [וְלִירוּשָׁלַ֖͏ִם] [מְבַשֵּׂ֥ר] אֶתְנָה');
INSERT INTO verses VALUES (18549, 23, 41, 28, '[וְאֵ֙רֶא֙] e-não-há homem e-de-os-esse e-não-há [יוֹעֵ֑ץ] [וְאֶשְׁאָלֵ֖ם] [וְיָשִׁ֥יבוּ] palavra');
INSERT INTO verses VALUES (18550, 23, 41, 29, 'eis todos iniquidade [אֶ֖פֶס] [מַעֲשֵׂיהֶ֑ם] espírito [וָתֹ֖הוּ] נִסְכֵּיהֶֽם׃');
INSERT INTO chapters VALUES (721, 23, 42, 25);
INSERT INTO verses VALUES (18551, 23, 42, 1, 'eis [עַבְדִּי֙] [אֶתְמָךְ־בּ֔וֹ] nele [רָצְתָ֣ה] [נַפְשִׁ֑י] dei eu-deti [עָלָ֔יו] sobre-ele juízo [יוֹצִֽיא] [sem-traducao]');
INSERT INTO verses VALUES (18552, 23, 42, 2, 'não [יִצְעַ֖ק] e-não levantará e-não [בַּח֖וּץ] בּח֖וּץ sua-voz:');
INSERT INTO verses VALUES (18553, 23, 42, 3, '[קָנֶ֤ה] [רָצוּץ֙] não [יִשְׁבּ֔וֹר] [וּפִשְׁתָּ֥ה] [כֵהָ֖ה] não [יְכַבֶּ֑נָּה] [לֶאֱמֶ֖ת] יוֹצִיא juízo');
INSERT INTO verses VALUES (18554, 23, 42, 4, 'não [יִכְהֶה֙] e-não [יָר֔וּץ] até põe-se na-terra juízo [אִיִּ֥ים] iyyim [sem-traducao]');
INSERT INTO verses VALUES (18555, 23, 42, 5, 'assim disse [׀] yhwh [בּוֹרֵ֤א] os-céus [וְנ֣וֹטֵיהֶ֔ם] [רֹקַ֥ע] a-terra [וְצֶאֱצָאֶ֑יהָ] deu [נְשָׁמָה֙] ao-povo sobre-ela e-Espírito-de [לַהֹלְכִ֥ים] nela');
INSERT INTO verses VALUES (18556, 23, 42, 6, 'eu yhwh [קְרָאתִ֥יךָֽ] [בְצֶ֖דֶק] [וְאַחְזֵ֣ק] em-mão-tua [וְאֶצָּרְךָ֗] [וְאֶתֶּנְךָ֛] para-o-convenção povo [לְא֥וֹר] goyim:');
INSERT INTO verses VALUES (18557, 23, 42, 7, '[לִפְקֹ֖חַ] עֵינַ֣יִם [עִוְר֑וֹת] [לְהוֹצִ֤יא] [מִמַּסְגֵּר֙] a-sír de-casa-de [כֶּ֖לֶא] יוֹשְׁבֵי escuridão');
INSERT INTO verses VALUES (18558, 23, 42, 8, 'eu yhwh ele o meu nome [וּכְבוֹדִי֙] לְאַחֵ֣ר não [וּתְהִלָּתִ֖י] [לַפְּסִילִֽים] [sem-traducao]');
INSERT INTO verses VALUES (18559, 23, 42, 9, '[הָרִֽאשֹׁנ֖וֹת] eis [וַֽחֲדָשׁוֹת֙] [אֲנִ֣י] eu [בְּטֶ֥רֶם] [תִּצְמַ֖חְנָה] [אַשְׁמִ֥יע] [אֶתְכֶֽם׃]');
INSERT INTO verses VALUES (18560, 23, 42, 10, '[שִׁ֤ירוּ] a-yhwh שִׁ֣יר novo [תְּהִלָּת֖וֹ] da-extremidade-de a-terra [יוֹרְדֵ֤י] o-mar [וּמְלֹא֔וֹ] íyím [וְיֹשְׁבֵיהֶֽם]');
INSERT INTO verses VALUES (18561, 23, 42, 11, 'levarão מדבר e-cidades-suas [חֲצֵרִ֖ים] [תֵּשֵׁ֣ב] [קֵדָ֑ר] [יָרֹ֙נּוּ֙] יֹשְׁבֵי [סֶ֔לַע] [מֵרֹ֥אשׁ] as-montanhas [יִצְוָֽחוּ]');
INSERT INTO verses VALUES (18562, 23, 42, 12, 'serão puestos a-yhwh glória [וּתְהִלָּת֖וֹ] [בָּאִיִּ֥ים] [יַגִּֽידוּ]');
INSERT INTO verses VALUES (18563, 23, 42, 13, 'yhwh [כַּגִּבּ֣וֹר] יֵצֵא como-homem [מִלְחָמ֖וֹת] iluminará [קִנְאָ֑ה] [יָרִ֙יעַ֙] também [עַל־אֹיְבָ֖יו] sobre seus inimigos se-exaltará-;');
INSERT INTO verses VALUES (18564, 23, 42, 14, '[הֶחֱשֵׁ֙יתִי֙] mē-ʿōlām [אַחֲרִ֖ישׁ] [אֶתְאַפָּ֑ק] [כַּיּוֹלֵדָ֣ה] [אֶפְעֶ֔ה] [אֶשֹּׁ֥ם] [וְאֶשְׁאַ֖ף] juntos');
INSERT INTO verses VALUES (18565, 23, 42, 15, '[אַחֲרִ֤יב] montes [וּגְבָע֔וֹת] e-todo [אוֹבִ֑ישׁ] [וְשַׂמְתִּ֤י] וְשַׂמְתִּ֤י [לֽ͏ָאִיִּ֔ים] [וַאֲגַמִּ֖ים] [אוֹבִֽישׁ] [sem-traducao]');
INSERT INTO verses VALUES (18566, 23, 42, 16, '[וְהוֹלַכְתִּ֣י] [עִוְרִ֗ים] בְּדֶ֙רֶךְ֙ não conheceram [בִּנְתִיב֥וֹת] não conheceram [אָשִׂים֩] [מַחְשָׁ֨ךְ] [לִפְנֵיהֶ֜ם] à-luz [וּמַֽעֲקַשִּׁים֙] [לְמִישׁ֔וֹר] Estas estas-estes as-palavras [וְלֹ֥א] e-não [sem-traducao]');
INSERT INTO verses VALUES (18567, 23, 42, 17, '[נָסֹ֤גוּ] אָחוֹר֙ envergonhar-se-ao [בֹ֔שֶׁת] os-que-confiam [בַּפָּ֑סֶל] הָאֹמְרִ֥ים [לְמַסֵּכָ֖ה] vós nosso-Elohim');
INSERT INTO verses VALUES (18568, 23, 42, 18, 'os surdos [שְׁמָ֑עוּ] [וְהַעִוְרִ֖ים] [הַבִּ֥יטוּ] para-ver');
INSERT INTO verses VALUES (18569, 23, 42, 19, 'quem cego que se servo-meu [כְּמַלְאָכִ֣י] [אֶשְׁלָ֑ח] quem quem cego [וְעִוֵּ֖ר] [כְּעֶ֥בֶד] yhwh yhwh');
INSERT INTO verses VALUES (18570, 23, 42, 20, '[*ראית] e-não você-guardará [וְלֹ֣א] [תִשְׁמֹ֑ר] e-não será ouvido:');
INSERT INTO verses VALUES (18571, 23, 42, 21, 'yhwh [חָפֵ֖ץ] para-que [צִדְק֑וֹ] [יַגְדִּ֥יל] [תּוֹרָ֖ה] [וְיַאְדִּֽיר]');
INSERT INTO verses VALUES (18572, 23, 42, 22, '[וְהוּא֮] com [וְשָׁסוּי֒] [הָפֵ֤חַ] [בַּֽחוּרִים֙] [כֻּלָּ֔ם] todos [כְלָאִ֖ים] [הָחְבָּ֑אוּ] [הָי֤וּ] eram [וְאֵ֣ין] e-não-há [מְשִׁסָּ֖ה] [וְאֵין־אֹמֵ֥ר] e-não-há disse [sem-traducao]');
INSERT INTO verses VALUES (18573, 23, 42, 23, 'quem em-vós [יַאֲזִ֣ין] esta [יַקְשִׁ֥ב] E-ouviu [לְאָחֽוֹר]');
INSERT INTO verses VALUES (18574, 23, 42, 24, 'quem deu Jacó [יַעֲקֹ֛ב] [וְיִשְׂרָאֵ֥ל] porventura-não yhwh yhwh pecamos a-ele a-ele e conceberam [בִדְרָכָיו֙] indo-o e-não ouviram [בְּתוֹרָתֽוֹ]');
INSERT INTO verses VALUES (18575, 23, 42, 25, '[וַיִּשְׁפֹּ֤ךְ] sobre-ele [חֵמָ֣ה] sua-ira [וֶעֱז֖וּז] guerra [וַתְּלַהֲטֵ֤הוּ] [מִסָּבִיב֙] e-não conheceu [וַתִּבְעַר־בּ֖וֹ] nele e-não põe-se sobre coração');
INSERT INTO chapters VALUES (722, 23, 43, 28);
INSERT INTO verses VALUES (18576, 23, 43, 1, 'e-agora assim yhwh yhwh [יַעֲקֹ֔ב] Jacó [יִשְׂרָאֵ֑ל] Israel que [גְאַלְתִּ֔יךָ] porque [בְשִׁמְךָ֖] chamei [sem-traducao] para-mim- tu');
INSERT INTO verses VALUES (18577, 23, 43, 2, 'porque [בַּמַּ֙יִם֙] [אִתְּךָ־אָ֔נִי] [וּבַנְּהָר֖וֹת] não [יִשְׁטְפ֑וּךָ] não [בְּמוֹ־אֵשׁ֙] não [תִכָּוֶ֔ה] [וְלֶהָבָ֖ה] não não não');
INSERT INTO verses VALUES (18578, 23, 43, 3, 'que eu yhwh teu-Elohim santo Israel [מוֹשִׁיעֶ֑ךָ] dei [כָפְרְךָ֙] Egito Cuxe [וּסְבָ֖א] תחתיך:');
INSERT INTO verses VALUES (18579, 23, 43, 4, '[מֵאֲשֶׁ֨ר] [יָקַ֧רְתָּ] [בְעֵינַ֛י] [נִכְבַּ֖דְתָּ] e-eu [אֲהַבְתִּ֑יךָ] [וְאֶתֵּ֤ן] homem [תַּחְתֶּ֔יךָ] e-a-nações debaixo alma-tua');
INSERT INTO verses VALUES (18580, 23, 43, 5, 'a que porque [מִמִּזְרָח֙] eu [זַרְעֶ֔ךָ] trarei [אֲקַבְּצֶֽךָּ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18581, 23, 43, 6, 'disse [לַצָּפוֹן֙] [תֵּ֔נִי] [וּלְתֵימָ֖ן] a [הָבִ֤יאִי] [בָנַי֙] filhos-de [וּבְנוֹתַ֖י] [מִקְצֵ֥ה] a-terra a-terra');
INSERT INTO verses VALUES (18582, 23, 43, 7, 'todo [הַנִּקְרָ֣א] [בִשְׁמִ֔י] [וְלִכְבוֹדִ֖י] [בְּרָאתִ֑יו] [יְצַרְתִּ֖יו] também');
INSERT INTO verses VALUES (18583, 23, 43, 8, 'saírei com עִוֵּר [יֵ֑שׁ] [וְחֵרְשִׁ֖ים] [וְאָזְנַ֥יִם] [לָֽמוֹ] a-eles');
INSERT INTO verses VALUES (18584, 23, 43, 9, 'todo os-povos [יַחְדָּ֗ו] juntos [לְאֻמִּ֔ים] quem quem [יַגִּ֣יד] esta Isto [יַשְׁמִיעֻ֑נוּ] [יִתְּנ֤וּ] darão [וְיִצְדָּ֔קוּ] [וְיִשְׁמְע֖וּ] [וְיֹאמְר֥וּ] [אֱמֶֽת] verdade');
INSERT INTO verses VALUES (18585, 23, 43, 10, 'vós [עֵדַי֙] oráculo-de yhwh [אֲשֶׁ֣ר] que [לְמַ֣עַן] para-que [וְתַאֲמִ֨ינוּ] [לִ֤י] a-mim [כִּֽי־אֲנִ֣י] ele eu ele diante-de-mim não não será [sem-traducao] não será');
INSERT INTO verses VALUES (18586, 23, 43, 11, 'eu eu yhwh e-não-há [מִבַּלְעָדַ֖י] [מוֹשִֽׁיעַ]');
INSERT INTO verses VALUES (18587, 23, 43, 12, 'eu [הִגַּ֤דְתִּי] [וְהוֹשַׁ֙עְתִּי֙] [וְהִשְׁמַ֔עְתִּי] e-não-há [בָּכֶ֖ם] [זָ֑ר] [וְאַתֶּ֥ם] [עֵדַ֛י] oráculo-de yhwh El');
INSERT INTO verses VALUES (18588, 23, 43, 13, 'também [אֲנִ֣י] ele ele e-não-há [מַצִּ֑יל] [אֶפְעַ֖ל] [וּמִ֥י] e-quem');
INSERT INTO verses VALUES (18589, 23, 43, 14, 'assim yhwh yhwh [קְד֣וֹשׁ] santo Israel [שִׁלַּ֣חְתִּי] [בָבֶ֗לָה] Babelá [בָֽרִיחִים֙] [כֻּלָּ֔ם] todos [בָּאֳנִיּ֥וֹת] [רִנָּתָֽם] [sem-traducao]');
INSERT INTO verses VALUES (18590, 23, 43, 15, 'eu yhwh [קְדֽוֹשְׁכֶ֑ם] [בּוֹרֵ֥א] Israel [מַלְכְּכֶֽם׃]');
INSERT INTO verses VALUES (18591, 23, 43, 16, 'assim disse yhwh [הַנּוֹתֵ֥ן] no-mar caminho e nos águas [עַזִּ֖ים] [נְתִיבָֽה]');
INSERT INTO verses VALUES (18592, 23, 43, 17, '[הַמּוֹצִ֥יא] carro-de [חַ֣יִל] força [יַחְדָּ֤ו] [יִשְׁכְּבוּ֙] [בַּל־יָק֔וּמוּ] não [כַּפִּשְׁתָּ֥ה] [כָבֽוּ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18593, 23, 43, 18, 'a [רִֽאשֹׁנ֑וֹת] [וְקַדְמֹנִיּ֖וֹת] [אַל־תִּתְבֹּנָֽנוּ] a');
INSERT INTO verses VALUES (18594, 23, 43, 19, 'eis-me fez nova agora [תִצְמָ֔ח] acaso-nao [תֵּֽדָע֑וּהָ] certamente [אָשִׂ֤ים] bamidbar o-caminho-de [בִּֽישִׁמ֖וֹן] [נְהָרֽוֹת]');
INSERT INTO verses VALUES (18595, 23, 43, 20, '[תְּכַבְּדֵ֙נִי֙] animal-de o-campo [תַּנִּ֖ים] [וּבְנ֣וֹת] [יַֽעֲנָ֑ה] porque Eu dei águas águas [בִּֽישִׁימֹ֔ן] [לְהַשְׁק֖וֹת] para-dar-de-beber povo-meu [sem-traducao]');
INSERT INTO verses VALUES (18596, 23, 43, 21, 'com [יָצַ֣רְתִּי] [לִ֔י] a-mim [יְסַפֵּֽרוּ׃]');
INSERT INTO verses VALUES (18597, 23, 43, 22, 'e-não me chamaste Jacó porque [יִשְׂרָאֵֽל] em-mi Israel');
INSERT INTO verses VALUES (18598, 23, 43, 23, 'não a-mim para-mim [עֹלֹתֶ֔יךָ] [וּזְבָחֶ֖יךָ] não não não não [בְּמִנְחָ֔ה] [וְלֹ֥א] e-não [בִּלְבוֹנָֽה] [sem-traducao]');
INSERT INTO verses VALUES (18599, 23, 43, 24, 'não a-mim para-mim [קָנֶ֔ה] [וְחֵ֥לֶב] [זְבָחֶ֖יךָ] não não [אַ֗ךְ] somente [בְּחַטֹּאותֶ֔יךָ] [הוֹגַעְתַּ֖נִי] [בַּעֲוֺנֹתֶֽיךָ׃] [sem-traducao]');
INSERT INTO verses VALUES (18600, 23, 43, 25, 'eu eu ele [מֹחֶ֥ה] [פְשָׁעֶ֖יךָ] [לְמַעֲנִ֑י] [וְחַטֹּאתֶ֖יךָ] não [אֶזְכֹּֽר]');
INSERT INTO verses VALUES (18601, 23, 43, 26, '[הַזְכִּירֵ֕נִי] [נִשָּׁפְטָ֖ה] juntamente conta tu para [תִּצְדָּֽק]');
INSERT INTO verses VALUES (18602, 23, 43, 27, 'seu pai הָרִאשׁ֖וֹן pecou [וּמְלִיצֶ֖יךָ] transgrediram בי׃');
INSERT INTO verses VALUES (18603, 23, 43, 28, '[וַאֲחַלֵּ֖ל] [שָׂ֣רֵי] santidade [וְאֶתְּנָ֤ה] [לַחֵ֙רֶם֙] Jacó [וְיִשְׂרָאֵ֖ל] [לְגִדּוּפִֽים׃]');
INSERT INTO chapters VALUES (723, 23, 44, 28);
INSERT INTO verses VALUES (18604, 23, 44, 1, 'e-agora ouviu Jacó seu-escravo וְיִשְׂרָאֵ֖ל [בָּחַ֥רְתִּי] nele');
INSERT INTO verses VALUES (18605, 23, 44, 2, 'assim yhwh yhwh [וְיֹצֶרְךָ֥] [מִבֶּ֖טֶן] [יַעְזְרֶ֑ךָּ] [אַל־תִּירָא֙] a [יַֽעֲקֹ֔ב] servo-meu Jacó nele [sem-traducao] nele-verso');
INSERT INTO verses VALUES (18606, 23, 44, 3, 'que [אֶצָּק־מַ֙יִם֙] águas sobre [עַל־יַבָּשָׁ֑ה] [אֶצֹּ֤ק] sobre [עַל־זַרְעֶ֔ךָ] [וּבִרְכָתִ֖י] [עַל־צֶאֱצָאֶֽיךָ] sobre sobre');
INSERT INTO verses VALUES (18607, 23, 44, 4, '[וְצָמְח֖וּ] [בְּבֵ֣ין] [חָצִ֑יר] [כַּעֲרָבִ֖ים] sobre águas');
INSERT INTO verses VALUES (18608, 23, 44, 5, 'este diga יֹאמַר֙ para-יהוה eu vezeh chamaria [בְשֵֽׁם־יַעֲקֹ֑ב] Jacó וְזֶ֗ה sua-mão mão-dele a-yhwh [יִשְׂרָאֵ֖ל] Israel [sem-traducao]');
INSERT INTO verses VALUES (18609, 23, 44, 6, 'assim yhwh yhwh rei-de yhwh [צְבָא֑וֹת] yhwh exércitos eu [אַחֲר֔וֹן] e-eu [אֵ֥ין] e-sem-mim Elohim');
INSERT INTO verses VALUES (18610, 23, 44, 7, 'ומי- chamaria [וְיַגִּידֶ֤הָ] [וְיַעְרְכֶ֙הָ֙] [לִ֔י] a-mim [עַם־עוֹלָ֑ם] com eternidade [תָּבֹ֖אנָה] e-que [לָֽמוֹ] [sem-traducao] a-eles');
INSERT INTO verses VALUES (18611, 23, 44, 8, 'a [וְאַל־תִּרְה֔וּ] e-a [מֵאָ֛ז] não [וְהִגַּ֖דְתִּי] [וְאַתֶּ֣ם] [עֵדָ֑י] e-vós [אֱל֙וֹהַּ֙] há [וְאֵ֥ין] [צ֖וּר] e-não-há rocha não [sem-traducao]');
INSERT INTO verses VALUES (18612, 23, 44, 9, '[יֹֽצְרֵי־פֶ֤סֶל] [כֻּלָּם֙] todos-os sem-forma [בַּל־יוֹעִ֑ילוּ] não [הֵׄ֗מָּׄהׄ[4]] [בַּל־יִרְא֛וּ] não [לְמַ֥עַן] וּבַל־ [sem-traducao] para [sem-traducao]');
INSERT INTO verses VALUES (18613, 23, 44, 10, 'quem El [נָסָ֑ךְ] para-não [הוֹעִֽיל]');
INSERT INTO verses VALUES (18614, 23, 44, 11, 'eis todo [יֵבֹ֔שׁוּ] [וְחָרָשִׁ֥ים] [הֵ֖מָּה] eles [יִֽתְקַבְּצ֤וּ] [כֻלָּם֙] todos-eles [יִפְחֲד֖וּ] [יֵבֹ֥שׁוּ] יֵבֹשׁוּ juntos');
INSERT INTO verses VALUES (18615, 23, 44, 12, '[חָרַ֤שׁ] barzel [מַֽעֲצָ֔ד] [וּפָעַל֙] [בַּפֶּחָ֔ם] [וּבַמַּקָּב֖וֹת] [יִצְּרֵ֑הוּ] [וַיִּפְעָלֵ֙הוּ֙] com-braco [כֹּח֔וֹ] também [וְאֵ֣ין] e-não-há כֹּחַ águas be-b-eu águas [sem-traducao]');
INSERT INTO verses VALUES (18616, 23, 44, 13, '[חָרַ֣שׁ] [עֵצִים֮] [נָ֣טָה] [קָו֒] [יְתָאֲרֵ֣הוּ] [בַשֶּׂ֔רֶד] [יַעֲשֵׂ֙הוּ֙] [בַּמַּקְצֻע֔וֹת] [וּבַמְּחוּגָ֖ה] [יְתָאֳרֵ֑הוּ] e fez-o [כְּתַבְנִ֣ית] homem [כְּתִפְאֶ֥רֶת] homem para-habitar casa');
INSERT INTO verses VALUES (18617, 23, 44, 14, 'para-cortar- a-ele E-tomou E-tomou [וְאַלּ֔וֹן] [וַיְאַמֶּץ־ל֖וֹ] [בַּעֲצֵי־יָ֑עַר] plantar [אֹ֖רֶן[6]] ya-a-ăr נטע ve-geshem [sem-traducao]');
INSERT INTO verses VALUES (18618, 23, 44, 15, 'e-será [לְאָדָם֙] [לְבָעֵ֔ר] E-tomou deles [וַיָּ֔חָם] também [וְאָ֣פָה] [לָ֑חֶם] pão também ele-resgatará- El [וַיִּסְגָּד־לָֽמוֹ] [sem-traducao] [sem-traducao] [sem-traducao] a-eles');
INSERT INTO verses VALUES (18619, 23, 44, 16, 'a-sua-metade queimou בְּmo֊ fogo sobre a-sua-metade em-a-carne [צָלִ֖י] [וְיִשְׂבָּ֑ע] [אַף־יָחֹם֙] [וְיֹאמַ֣ר] também [חַמּוֹתִ֖י] E-disse o-irmão [sem-traducao] רָאִ֥יתִי luz');
INSERT INTO verses VALUES (18620, 23, 44, 17, '[וּשְׁאֵ֣רִית֔וֹ] para-o-elohim fez [לְפִסְל֑וֹ] para-ele [וְיִשְׁתַּ֙חוּ֙] e-orará a-ele E-disse [הַצִּילֵ֔נִי] que eli- tu');
INSERT INTO verses VALUES (18621, 23, 44, 18, 'não conheceram e-não [יָבִ֑ינוּ] que [טַ֤ח] [מֵֽרְאוֹת֙] seus olhos [מֵהַשְׂכִּ֖יל] [לִבֹּתָֽם]');
INSERT INTO verses VALUES (18622, 23, 44, 19, 'e-não יָשִׁיב a coração-dele e-não dizendo e-não [שָׂרַ֣פְתִּי] dizendo [וְ֠אַף] [אָפִ֤יתִי] be-mo- pão [אֶצְלֶ֥ה] [בָשָׂ֖ר] sobre [וְיִתְרוֹ֙] Belém [אֶעֱשֶׂ֔ה] [לְב֥וּל] árvore [אֶסְגּֽוֹד] [sem-traducao] de-diante-de [sem-traducao] árvore [sem-traducao]');
INSERT INTO verses VALUES (18623, 23, 44, 20, '[רֹעֶ֣ה] [אֵ֔פֶר] coração [הוּתַ֖ל] [הִטָּ֑הוּ] e-não [אֶת־נַפְשׁוֹ֙] a נפשוֹ e-não [שֶׁ֖קֶר] não dizendo [sem-traducao]');
INSERT INTO verses VALUES (18624, 23, 44, 21, 'lembra-de estes Jacó que porque [יְצַרְתִּ֤יךָ] tu tu servo- não tu Israel não [sem-traducao]');
INSERT INTO verses VALUES (18625, 23, 44, 22, '[מָחִ֤יתִי] [כָעָב֙] [פְּשָׁעֶ֔יךָ] [וְכֶעָנָ֖ן] [חַטֹּאותֶ֑יךָ] [שׁוּבָ֥ה] a-mim que [גְאַלְתִּֽיךָ]');
INSERT INTO verses VALUES (18626, 23, 44, 23, '[רָנּ֨וּ] céus porque yhwh yhwh [תַּחְתִּיּ֣וֹת] [אָ֔רֶץ] terra [הָרִים֙] montes [יַ֖עַר] floresta e-todo arvore yhwh porque [וּבְיִשְׂרָאֵ֖ל] yhwh Jacó e-em-Israel [sem-traducao]');
INSERT INTO verses VALUES (18627, 23, 44, 24, 'assim yhwh yhwh [וְיֹצֶרְךָ֖] [מִבָּ֑טֶן] eu yhwh yhwh fez todo [שָׁמַ֙יִם֙] céus lebadí a-terra a-terra');
INSERT INTO verses VALUES (18628, 23, 44, 25, '[מֵפֵר֙] [אֹת֣וֹת] na-bádim [וְקֹסְמִ֖ים] [יְהוֹלֵ֑ל] [מֵשִׁ֧יב] [חֲכָמִ֛ים] [אָח֖וֹר] [וְדַעְתָּ֥ם] [יְשַׂכֵּֽל]');
INSERT INTO verses VALUES (18629, 23, 44, 26, '[מֵקִים֙] palavra servo-seu e conselho [מַלְאָכָ֖יו] [יַשְׁלִ֑ים] [הָאֹמֵ֨ר] [לִירוּשָׁלִַ֜ם] [תּוּשָׁ֗ב] [וּלְעָרֵ֤י] Judá [תִּבָּנֶ֔ינָה] [וְחָרְבוֹתֶ֖יהָ] [אֲקוֹמֵֽם]');
INSERT INTO verses VALUES (18630, 23, 44, 27, '[הָאֹמֵ֥ר] [לַצּוּלָ֖ה] [חֳרָ֑בִי] [וְנַהֲרֹתַ֖יִךְ] [אוֹבִֽישׁ]');
INSERT INTO verses VALUES (18631, 23, 44, 28, '[הָאֹמֵ֤ר] para-Ciro [רֹעִ֔י] e-todo [יַשְׁלִ֑ם] [וְלֵאמֹ֤ר] [לִירוּשָׁלִַ֙ם֙] para Jerusalém [וְהֵיכָ֖ל] [תִּוָּסֵֽד׃] [sem-traducao]');
INSERT INTO chapters VALUES (724, 23, 45, 25);
INSERT INTO verses VALUES (18632, 23, 45, 1, 'assim yhwh yhwh [לְכ֣וֹרֶשׁ] [אֲשֶׁר־הֶחֱזַ֣קְתִּי] que [לְרַד־לְפָנָיו֙] [גּוֹיִ֔ם] [וּמָתְנֵ֥י] diante-dele nações [לִפְתֹּ֤חַ] me-lachim [דְּלָתַ֔יִם] para abrir não [יִסָּגֵֽרוּ] [sem-traducao] não [sem-traducao]');
INSERT INTO verses VALUES (18633, 23, 45, 2, 'eu diante de ti [אֵלֵ֔ךְ] [וַהֲדוּרִ֖ים] [*אושר] [**אֲיַשֵּׁ֑ר] [דַּלְת֤וֹת] [נְחוּשָׁה֙] ferro [וּבְרִיחֵ֥י]');
INSERT INTO verses VALUES (18634, 23, 45, 3, 'e-darei a-ti [אוֹצְר֣וֹת] escuridão [וּמַטְמֻנֵ֖י] [מִסְתָּרִ֑ים] para-que sabes porque yhwh yhwh [בְשִׁמְךָ֖] [Elohim] Elohim-de Israel');
INSERT INTO verses VALUES (18635, 23, 45, 4, 'para-que servo-meu Jacó וְיִשְׂרָאֵ֖ל [בְּחִירִ֑י] [וָאֶקְרָ֤א] a-ti em-tu-nome [אֲכַנְּךָ֖] e-não [יְדַעְתָּֽנִי]');
INSERT INTO verses VALUES (18636, 23, 45, 5, 'eu yhwh e-não-há ainda [זוּלָתִ֖י] não-há Elohim [אֲאַזֶּרְךָ֖] e-não [יְדַעְתָּֽנִי]');
INSERT INTO verses VALUES (18637, 23, 45, 6, 'para-que [יֵדְע֗וּ] do oriente- Shemesh [כִּי־אֶ֖פֶס] porque [אֲנִ֥י] yhwh eu yhwh e-não-há ainda');
INSERT INTO verses VALUES (18638, 23, 45, 7, 'formador luz [וּבוֹרֵ֣א] escuridão fez paz [וּב֣וֹרֵא] mal eu yhwh fez todo Estas');
INSERT INTO verses VALUES (18639, 23, 45, 8, '[הַרְעִ֤יפוּ] céus de-acima [וּשְׁחָקִ֖ים] יִזָּלֻהוּ־ justica [וְיִפְרוּ־יֶ֗שַׁע] terra [תַצְמִ֙יחַ֙] [יַ֔חַד] [אֲנִ֥י] yhwh [בְּרָאתִֽיו׃] eu yhwh [sem-traducao]');
INSERT INTO verses VALUES (18640, 23, 45, 9, 'ai muito a [חֶ֖רֶשׂ] [אֶת־חַרְשֵׂ֣י] terra [הֲיֹאמַ֨ר] terra-a [לְיֹֽצְרוֹ֙] [מַֽה־תַּעֲשֶׂ֔ה] [וּפָעָלְךָ֖] que a-ele [sem-traducao] não-há [sem-traducao] a-ele');
INSERT INTO verses VALUES (18641, 23, 45, 10, '[ה֛וֹי] disse [לְאָ֖ב] que [וּלְאִשָּׁ֖ה] [מַה־תְּחִילִֽין׃]');
INSERT INTO verses VALUES (18642, 23, 45, 11, 'assim yhwh yhwh santo Israel [הָאֹתִיּ֣וֹת] [שְׁאָל֔וּנִי] [עַל־בָּנַ֛י] sobre filhos-de e-sobre');
INSERT INTO verses VALUES (18643, 23, 45, 12, 'eu עָשִׂ֣יתִי terra e adam עָלֶיהָ [בָרָ֑אתִי] eu ידי נָט֣וּ céus e-todo [צִוֵּֽיתִי] tziviti');
INSERT INTO verses VALUES (18644, 23, 45, 13, 'eu [הַעִירֹתִ֣הֽוּ] [בְצֶ֔דֶק] e-todo [אֲיַשֵּׁ֑ר] [הֽוּא־יִבְנֶ֤ה] ele ele-construirá [יְשַׁלֵּ֔חַ] não [בִמְחִיר֙] não [בְשֹׁ֔חַד] disse yhwh disse yhwh exércitos');
INSERT INTO verses VALUES (18645, 23, 45, 14, 'assim disse disse yhwh Mitzraim [מִצְרַ֥יִם] [וּֽסְחַר־כּוּשׁ֮] [וּסְבָאִים֮] homens-de [מִדָּה֒] sobre-você [יַעֲבֹ֙רוּ֙] וְלָךְ יִֽהְי֔וּ [אַחֲרַ֣יִךְ] irao [בַּזִּקִּ֖ים] passarão [וְאֵלַ֤יִךְ] [יִֽשְׁתַּחֲוּוּ֙] [אֵלַ֣יִךְ] [יִתְפַּלָּ֔לוּ] somente sobre-ti El e-não-há ainda [אֶ֥פֶס] Elohim');
INSERT INTO verses VALUES (18646, 23, 45, 15, '[אָכֵ֕ן] tu El [מִסְתַּתֵּ֑ר] Elohim-de Israel [מוֹשִֽׁיעַ]');
INSERT INTO verses VALUES (18647, 23, 45, 16, '[בּ֥וֹשׁוּ] e também- [כֻּלָּ֑ם] כלם yachdav caminharam [חָרָשֵׁ֖י] chárashey [sem-traducao]');
INSERT INTO verses VALUES (18648, 23, 45, 17, 'Israel [נוֹשַׁ֣ע] [בַּיהוָ֔ה] [תְּשׁוּעַ֖ת] mundos não [וְלֹא־תִכָּלְמ֖וּ] e-não até até [sem-traducao] até');
INSERT INTO verses VALUES (18649, 23, 45, 18, 'que assim disse yhwh [הַשָּׁמַ֜יִם] ele ele o-Elohim a-terra a-terra ele ele [לֹא־תֹ֥הוּ] não sem-forma [יְצָרָ֑הּ] para-habitar yhwh eu yhwh e-não-há ainda');
INSERT INTO verses VALUES (18650, 23, 45, 19, 'não [בַסֵּ֣תֶר] falei-eu בִּמְקוֹם֙ terra escuridão não eu disse - [לְזֶ֥רַע] Jacó sem-forma [בַקְּשׁ֑וּנִי] eu yhwh palavra justiça מַגִּ֖יד משרים׃');
INSERT INTO verses VALUES (18651, 23, 45, 20, '[הִקָּבְצ֥וּ] [וָבֹ֛אוּ] [הִֽתְנַגְּשׁ֥וּ] juntos [פְּלִיטֵ֣י] as-nações não sabiam [הַנֹּֽשְׂאִים֙] a arvore [וּמִתְפַּלְלִ֔ים] [אֶל־אֵ֖ל] não El não יוֹשִֽׁיעַ׃');
INSERT INTO verses VALUES (18652, 23, 45, 21, 'הַגּ֣idoּ [וְהַגִּ֔ישׁוּ] certamente [יִֽוָּעֲצ֖וּ] juntos quem [הִשְׁמִיעַ֩] esta ao-oriente מֵאָ֣ז [הִגִּידָ֗הּ] porventura-não eu yhwh e-nao-ha ainda Elohim [אֵֽל־צַדִּ֣יק] a não-havia [זוּלָתִֽי] não-havia [sem-traducao]');
INSERT INTO verses VALUES (18653, 23, 45, 22, 'penu- a-mim [כָּל־אַפְסֵי־אָ֑רֶץ] que extremidades-de terra porque eu- El e-não-há ainda');
INSERT INTO verses VALUES (18654, 23, 45, 23, 'por-mim jurei sair [מִפִּ֧י] [צְדָקָ֛ה] palavra e-não YSHVB porque para-mim [כָּל־בֶּ֔רֶךְ] todo abençoou [sem-traducao] todo língua:');
INSERT INTO verses VALUES (18655, 23, 45, 24, 'Aquele [בַּיהוָ֛ה] para-mim disse [צְדָק֣וֹת] ועוז [עָדָיו֙] vira [וְיֵבֹ֔שׁוּ] todo [הַנֶּחֱרִ֥ים] nele');
INSERT INTO verses VALUES (18656, 23, 45, 25, '[בַּיהוָ֛ה] [יִצְדְּק֥וּ] [וְיִֽתְהַלְל֖וּ] todo semente Israel');
INSERT INTO chapters VALUES (725, 23, 46, 13);
INSERT INTO verses VALUES (18657, 23, 46, 1, 'karah [בֵּל֙] [קֹרֵ֣ס] [נְב֔וֹ] foram [עֲצַבֵּיהֶ֔ם] [לַחַיָּ֖ה] [וְלַבְּהֵמָ֑ה] [נְשֻׂאֹתֵיכֶ֣ם] [עֲמוּס֔וֹת] profecia [לַעֲיֵפָֽה]');
INSERT INTO verses VALUES (18658, 23, 46, 2, '[קָרְס֤וּ] כָֽרְעוּ֙ juntos não puderam [מַלֵּ֣ט] carga [וְנַפְשָׁ֖ם] [בַּשְּׁבִ֥י] [הָלָֽכָה׃]');
INSERT INTO verses VALUES (18659, 23, 46, 3, 'ouvi a-mim casa Jacó e-todo sheerit casa Israel [מִנִּי־בֶ֔טֶן] de-mim [מִנִּי־רָֽחַם] [sem-traducao] de-mim [sem-traducao]');
INSERT INTO verses VALUES (18660, 23, 46, 4, 'e-até [אֲנִ֣י] ele ele e-até eu [אֲנִ֤י] eu eu fiz e-eu [וַאֲנִ֥י] e-eu [וַאֲמַלֵּֽט׃] [sem-traducao]');
INSERT INTO verses VALUES (18661, 23, 46, 5, '[לְמִ֥י] [תְדַמְי֖וּנִי] [וְתַשְׁו֑וּ] [וְתַמְשִׁל֖וּנִי] [וְנִדְמֶֽה]');
INSERT INTO verses VALUES (18662, 23, 46, 6, '[הַזָּלִ֤ים] ouro [מִכִּ֔יס] וְכֶ֖סֶף baq-qué-né [יִשְׁקֹ֑לוּ] [יִשְׂכְּר֤וּ] [צוֹרֵף֙] [וְיַעֲשֵׂ֣הוּ] El [יִסְגְּד֖וּ] também [sem-traducao]');
INSERT INTO verses VALUES (18663, 23, 46, 7, '[יִ֠שָּׂאֻהוּ] sobre [יִסְבְּלֻ֜הוּ] [וְיַנִּיחֻ֤הוּ] [תַחְתָּיו֙] [וְיַֽעֲמֹ֔ד] [מִמְּקוֹמ֖וֹ] não não [אַף־יִצְעַ֤ק] a-ele [וְלֹ֣א] a-ele e-não não [יוֹשִׁיעֶֽנּוּ׃] não [sem-traducao]');
INSERT INTO verses VALUES (18664, 23, 46, 8, '[זִכְרוּ־זֹ֖את] esta [הָשִׁ֥יבוּ] הָשִׁ֥יבוּ [עַל־לֵֽב] sobre coração');
INSERT INTO verses VALUES (18665, 23, 46, 9, '[זִכְר֥וּ] [רִאשֹׁנ֖וֹת] [מֵעוֹלָ֑ם] que eu El e-não-há ainda Elohim [וְאֶ֥פֶס] como-eu');
INSERT INTO verses VALUES (18666, 23, 46, 10, '[מַגִּ֤יד] [מֵֽרֵאשִׁית֙] [אַחֲרִ֔ית] [וּמִקֶּ֖דֶם] que não [אֹמֵר֙] disse [תָק֔וּם] [וְכָל־חֶפְצִ֖י] e-todo');
INSERT INTO verses VALUES (18667, 23, 46, 11, 'chamou [מִמִּזְרָח֙] [עַ֔יִט] da-terra-de מֶרְחָ֖ק homem também falei-eu também [אַף־אֲבִיאֶ֔נָּה] [יָצַ֖רְתִּי] também [sem-traducao]');
INSERT INTO verses VALUES (18668, 23, 46, 12, 'ouvi a-mim fortes coração [הָרְחוֹקִ֖ים] [מִצְּדָקָֽה]');
INSERT INTO verses VALUES (18669, 23, 46, 13, '[קֵרַ֤בְתִּי] [צִדְקָתִי֙] não [תִרְחָ֔ק] [וּתְשׁוּעָתִ֖י] não תְאַחֵ֑ר e-darei em-Sion [תְּשׁוּעָ֔ה] [לְיִשְׂרָאֵ֖ל] [תִּפְאַרְתִּֽי׃]');
INSERT INTO chapters VALUES (726, 23, 47, 15);
INSERT INTO verses VALUES (18670, 23, 47, 1, '[רְדִ֣י] [׀] sobre [עַל־עָפָ֗ר] virgem filha-de Babilônia [אֵין־כִּסֵּ֖א] para-a-terra que não filha-de כַּשְׂדִּ֑ים porque não [sem-traducao] chamam- yhwh [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18671, 23, 47, 2, 'קְחִ֥י rekhayim [וְטַ֣חֲנִי] [קָ֑מַח] [גַּלִּ֨י] [צַמָּתֵ֧ךְ] [חֶשְׂפִּי־שֹׁ֛בֶל] [גַּלִּי־שׁ֖וֹק] [עִבְרִ֥י] [נְהָרֽוֹת] ivri [sem-traducao]');
INSERT INTO verses VALUES (18672, 23, 47, 3, '[תִּגָּל֙] עֶרְוָתֵ֔ךְ também [תֵּרָאֶ֖ה] [חֶרְפָּתֵ֑ךְ] vengança [אֶקָּ֔ח] e-não [אֶפְגַּ֖ע] homem');
INSERT INTO verses VALUES (18673, 23, 47, 4, '[גֹּאֲלֵ֕נוּ] yhwh exércitos seu-nome santo Israel');
INSERT INTO verses VALUES (18674, 23, 47, 5, '[שְׁבִ֥י] [דוּמָ֛ם] [וּבֹ֥אִי] [בַחֹ֖שֶׁךְ] filha-de que não não [יִקְרְאוּ־לָ֔ךְ] [גְּבֶ֖רֶת] para-ti');
INSERT INTO verses VALUES (18675, 23, 47, 6, '[קָצַ֣פְתִּי] sobre עַמּי [נַחֲלָתִ֔י] minha herança [בְּיָדֵ֑ךְ] [לֹא־שַׂ֤מְתְּ] a-eles [רַחֲמִ֔ים] a-eles [הִכְבַּ֥דְתְּ] sobre muito [sem-traducao] [sem-traducao] muito');
INSERT INTO verses VALUES (18676, 23, 47, 7, '[וַתֹּ֣אמְרִ֔י] para-sempre [אֶהְיֶ֣ה] [גְבָ֑רֶת] até não Estas estes não teu-coração não [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18677, 23, 47, 8, 'e-agora שׁוּמַע־ esta [הַיּוֹשֶׁ֣בֶת] [לָבֶ֔טַח] [הָאֹֽמְרָה֙] [בִּלְבָ֔בָהּ] [אֲנִ֖י] eu [ע֑וֹד] não não [אַלְמָנָ֔ה] [וְלֹ֥א] e-não [שְׁכֽוֹל] [sem-traducao]');
INSERT INTO verses VALUES (18678, 23, 47, 9, '[וְתָבֹאנָה֩] [לָּ֨ךְ] [שְׁתֵּי־אֵ֥לֶּה] [רֶ֛גַע] [בְּי֥וֹם] um um [וְאַלְמֹ֑ן] [כְּתֻמָּם֙] [בָּ֣אוּ] [עָלַ֔יִךְ] sobre-ti em-multidão [בְּעָצְמַ֥ת] [חֲבָרַ֖יִךְ] muito');
INSERT INTO verses VALUES (18679, 23, 47, 10, '[וַתִּבְטְחִ֣י] [בְרָעָתֵ֗ךְ] [אָמַרְתְּ֙] não-há [רֹאָ֔נִי] [חָכְמָתֵ֥ךְ] [וְדַעְתֵּ֖ךְ] ela [שׁוֹבְבָ֑תֶךְ] [וַתֹּאמְרִ֣י] [בְלִבֵּ֔ךְ] eu [וְאַפְסִ֥י] ainda');
INSERT INTO verses VALUES (18680, 23, 47, 11, '[וּבָ֧א] [עָלַ֣יִךְ] [רָעָ֗ה] não [תֵדְעִי֙] [שַׁחְרָ֔הּ] [וְתִפֹּ֤ל] sobre-ti [הֹוָ֔ה] não [תוּכְלִ֖י] [כַּפְּרָ֑הּ] [וְתָבֹ֨א] [עָלַ֧יִךְ] [פִּתְאֹ֛ם] [שׁוֹאָ֖ה] não [תֵדָֽעִי]');
INSERT INTO verses VALUES (18681, 23, 47, 12, '[עִמְדִי־נָ֤א] por-favor [וּבְרֹ֣ב] [כְּשָׁפַ֔יִךְ] [בַּאֲשֶׁ֥ר] [יָגַ֖עַתְּ] [מִנְּעוּרָ֑יִךְ] [אוּלַ֛י] [תּוּכְלִ֥י] [הוֹעִ֖יל] [אוּלַ֥י] [תַּעֲרֽוֹצִי]');
INSERT INTO verses VALUES (18682, 23, 47, 13, '[נִלְאֵ֖ית] em-multidão [עֲצָתָ֑יִךְ] [יַעַמְדוּ־נָ֨א] por-favor [*הברו] céus [שָׁמַ֗יִם] [הַֽחֹזִים֙] [בַּכּ֣וֹכָבִ֔ים] [מֽוֹדִיעִם֙] [לֶחֳדָשִׁ֔ים] [מֵאֲשֶׁ֥ר] [יָבֹ֖אוּ]');
INSERT INTO verses VALUES (18683, 23, 47, 14, 'eis [הָי֤וּ] [כְקַשׁ֙] fogo [שְׂרָפָ֔תַם] não [אֶת־נַפְשָׁ֖ם] a [לֶֽהָבָ֑ה] da-mão-de [לַחְמָ֔ם] não-há [לָשֶׁ֥בֶת] [נֶגְדּֽוֹ] luz');
INSERT INTO verses VALUES (18684, 23, 47, 15, 'assim [הָיוּ־לָ֖ךְ] [אֲשֶׁ֣ר] que [סֹחֲרַ֣יִךְ] [מִנְּעוּרַ֗יִךְ] [אִ֤ישׁ] homem [תָּע֔וּ] [אֵ֖ין] [מוֹשִׁיעֵֽךְ׃]');
INSERT INTO chapters VALUES (727, 23, 48, 22);
INSERT INTO verses VALUES (18685, 23, 48, 1, 'ouvi [בֵּֽית־יַעֲקֹ֗ב] casa-de Jacó [יִשְׂרָאֵ֔ל] no-nome-de Israel [יָצָ֑אוּ] Judá [׀] [בְּשֵׁ֣ם] yhwh yhwh [יִשְׂרָאֵל֙] Israel não não [וְלֹ֥א] e-não');
INSERT INTO verses VALUES (18686, 23, 48, 2, 'porque [הַקֹּ֙דֶשׁ֙] a-santidade [וְעַל־אֱלֹהֵ֥י] e-sobre Elohim-de yhwh [צְבָא֖וֹת] yhwh');
INSERT INTO verses VALUES (18687, 23, 48, 3, '[הָרִֽאשֹׁנוֹת֙] [מֵאָ֣ז] [הִגַּ֔דְתִּי] [וּמִפִּ֥י] [יָצְא֖וּ] [וְאַשְׁמִיעֵ֑ם] [פִּתְאֹ֥ם] fiz [וַתָּבֹֽאנָה]');
INSERT INTO verses VALUES (18688, 23, 48, 4, '[מִדַּעְתִּ֕י] que [קָשֶׁ֖ה] tu [וְגִ֤יד] [בַּרְזֶל֙] [עָרְפֶּ֔ךָ] [וּמִצְחֲךָ֖] [נְחוּשָֽׁה]');
INSERT INTO verses VALUES (18689, 23, 48, 5, '[וָאַגִּ֤יד] a-ti [מֵאָ֔ז] [בְּטֶ֥רֶם] [תָּב֖וֹא] [הִשְׁמַעְתִּ֑יךָ] para-que-não [עָצְבִּ֣י] [עָשָׂ֔ם] [וּפִסְלִ֥י] [וְנִסְכִּ֖י] [צִוָּֽם]');
INSERT INTO verses VALUES (18690, 23, 48, 6, '[שָׁמַ֤עְתָּֽ] [חֲזֵה֙] [כֻּלָּ֔הּ] [וְאַתֶּ֖ם] porventura-não [תַגִּ֑ידוּ] [הִשְׁמַעְתִּ֤יךָ] [חֲדָשׁוֹת֙] [מֵעַ֔תָּה] [וּנְצֻר֖וֹת] e-não [יְדַעְתָּֽם]');
INSERT INTO verses VALUES (18691, 23, 48, 7, '[עַתָּ֤ה] [נִבְרְאוּ֙] e-não [מֵאָ֔ז] [וְלִפְנֵי־י֖וֹם] dia e-não [פֶּן־תֹּאמַ֖ר] eis [יְדַעְתִּֽין]');
INSERT INTO verses VALUES (18692, 23, 48, 8, 'também não também não não também também [לֹא־פִתְּחָ֣ה] não que [יָדַ֙עְתִּי֙] porque [תִּבְגּ֔וֹד] [וּפֹשֵׁ֥עַ] [מִבֶּ֖טֶן] [קֹ֥רָא] para-ti chamou');
INSERT INTO verses VALUES (18693, 23, 48, 9, '[לְמַ֤עַן] [שְׁמִי֙] [אַאֲרִ֣יךְ] [אַפִּ֔י] [וּתְהִלָּתִ֖י] [אֶחֱטָם־לָ֑ךְ] para-não [הַכְרִיתֶֽךָ]');
INSERT INTO verses VALUES (18694, 23, 48, 10, 'eis [צְרַפְתִּ֖יךָ] e-não [בְכָ֑סֶף] [בְּחַרְתִּ֖יךָ] [בְּכ֥וּר] [עֹֽנִי]');
INSERT INTO verses VALUES (18695, 23, 48, 11, '[לְמַעֲנִ֧י] [לְמַעֲנִ֛י] [אֶעֱשֶׂ֖ה] que [אֵ֣יךְ] [יֵחָ֑ל] [וּכְבוֹדִ֖י] [לְאַחֵ֥ר] não');
INSERT INTO verses VALUES (18696, 23, 48, 12, 'ouviu a-mim Jacó [וְיִשְׂרָאֵ֖ל] [מְקֹרָאִ֑י] [אֲנִי־הוּא֙] ele eu certamente [אֲנִ֥י] eu [sem-traducao]');
INSERT INTO verses VALUES (18697, 23, 48, 13, 'também [יָ֣סְדָה] terra terra [טִפְּחָ֣ה] [שָׁמָ֑יִם] céus chamou eu a-eles [יַחְדָּֽו] juntos-verso');
INSERT INTO verses VALUES (18698, 23, 48, 14, '[הִקָּבְצ֤וּ] [כֻלְּכֶם֙] [וּֽשֲׁמָ֔עוּ] quem [בָהֶ֖ם] declarou a yhwh yhwh [יַעֲשֶׂ֤ה] [חֶפְצוֹ֙] [בְּבָבֶ֔ל] [וּזְרֹע֖וֹ] [כַּשְׂדִּֽים]');
INSERT INTO verses VALUES (18699, 23, 48, 15, 'eu eu [דִּבַּ֖רְתִּי] também [הֲבִיאֹתִ֖יו] [וְהִצְלִ֥יחַ] [דַּרְכּֽוֹ] [sem-traducao]');
INSERT INTO verses VALUES (18700, 23, 48, 16, '[קִרְב֧וּ] a-mim ouvi não não [בַּסֵּ֣תֶר] [דִּבַּ֔רְתִּי] [מֵעֵ֥ת] [הֱיוֹתָ֖הּ] [שָׁ֣ם] nome e-agora [Adonai] Adonai yhwh [וְרוּחֽוֹ׃] [sem-traducao]');
INSERT INTO verses VALUES (18701, 23, 48, 17, 'assim yhwh yhwh [קְד֣וֹשׁ] santo Israel yhwh yhwh teu-Elohim [לְהוֹעִ֔יל] [מַדְרִֽיכֲךָ֖] [בְּדֶ֥רֶךְ] [תֵּלֵֽךְ] andares');
INSERT INTO verses VALUES (18702, 23, 48, 18, '[ל֥וּא] [הִקְשַׁ֖בְתָּ] [לְמִצְוֺתָ֑י] e-houve [כַנָּהָר֙] [שְׁלוֹמֶ֔ךָ] [וְצִדְקָתְךָ֖] [כְּגַלֵּ֥י] o-mar');
INSERT INTO verses VALUES (18703, 23, 48, 19, 'e-houve [כַחוֹל֙] [זַרְעֶ֔ךָ] [וְצֶאֱצָאֵ֥י] [מֵעֶ֖יךָ] [כִּמְעֹתָ֑יו] não [וְֽלֹא־יִשָּׁמֵ֛ד] e-não [מִלְּפָנָֽי]');
INSERT INTO verses VALUES (18704, 23, 48, 20, '[צְא֣וּ] [מִבָּבֶל֮] [בִּרְח֣וּ] [מִכַּשְׂדִּים֒] com-voz [רִנָּ֗ה] [הַגִּ֤ידוּ] [הַשְׁמִ֙יעוּ֙] esta [הוֹצִיא֖וּהָ] até a-terra a-terra [גָּאַ֥ל] yhwh yhwh [יַעֲקֹֽב] Jacó');
INSERT INTO verses VALUES (18705, 23, 48, 21, 'e-não [צָמְא֗וּ] [בָּחֳרָבוֹת֙] [הֽוֹלִיכָ֔ם] águas [מִצּ֖וּר] [הִזִּ֣יל] a-eles [וַיִּ֨בְקַע־צ֔וּר] [וַיָּזֻ֖בוּ] [מָֽיִם] águas');
INSERT INTO verses VALUES (18706, 23, 48, 22, 'não-há paz disse yhwh [לָרְשָׁעִֽים׃]');
INSERT INTO chapters VALUES (728, 23, 49, 26);
INSERT INTO verses VALUES (18707, 23, 49, 1, 'ouvi [אִיִּים֙] a-mim [וְהַקְשִׁ֥יבוּ] [לְאֻמִּ֖ים] [מֵרָח֑וֹק] yhwh [מִבֶּ֣טֶן] [קְרָאָ֔נִי] [מִמְּעֵ֥י] [אִמִּ֖י] [הִזְכִּ֥יר] [שְׁמִֽי]');
INSERT INTO verses VALUES (18708, 23, 49, 2, '[וַיָּ֤שֶׂם] [פִּי֙] [כְּחֶ֣רֶב] [חַדָּ֔ה] [בְּצֵ֥ל] sua-mão [הֶחְבִּיאָ֑נִי] [וַיְשִׂימֵ֙נִי֙] [לְחֵ֣ץ] [בָּר֔וּר] [בְּאַשְׁפָּת֖וֹ] [הִסְתִּירָֽנִי]');
INSERT INTO verses VALUES (18709, 23, 49, 3, 'E-disse a-mim [עַבְדִּי־אָ֑תָּה] tu Israel que');
INSERT INTO verses VALUES (18710, 23, 49, 4, '[וַאֲנִ֤י] [אָמַ֙רְתִּי֙] [לְרִ֣יק] [יָגַ֔עְתִּי] [לְתֹ֥הוּ] [וְהֶ֖בֶל] [כֹּחִ֣י] [כִלֵּ֑יתִי] certamente [מִשְׁפָּטִ֣י] a yhwh [אֶת־אֱלֹהָֽי] a yhwh');
INSERT INTO verses VALUES (18711, 23, 49, 5, 'e-agora disse disse yhwh [יֹצְרִ֤י] [מִבֶּ֙טֶן֙] a-ele a-ele Jacó a-ele a-ele [וְיִשְׂרָאֵ֖ל] [*לא] aos-olhos-de yhwh [וְאֶכָּבֵד֙] foi yhwh');
INSERT INTO verses VALUES (18712, 23, 49, 6, 'E-disse [נָקֵ֨ל] [מִֽהְיוֹתְךָ֥] para-mim servo [לְהָקִים֙] a tribos-de Jacó Israel [יִשְׂרָאֵ֖ל] [לְהָשִׁ֑יב] para-luz nações para-ser [לִֽהְי֥וֹת] até [עַד־קְצֵ֥ה] a-terra');
INSERT INTO verses VALUES (18713, 23, 49, 7, '[כֹּ֣ה] disse yhwh [יִשְׂרָאֵ֜ל] Israel [לִבְזֹה־נֶ֜פֶשׁ] [לִמְתָ֤עֵֽב] alma [לְעֶ֣בֶד] nação [מְלָכִים֙] [יִרְא֣וּ] [וָקָ֔מוּ] temerao [וְיִֽשְׁתַּחֲוּ֑וּ] [לְמַ֤עַן] yhwh [אֲשֶׁ֣ר] yhwh que [יִשְׂרָאֵ֖ל] [וַיִּבְחָרֶֽךָּ] Israel [sem-traducao]');
INSERT INTO verses VALUES (18714, 23, 49, 8, '[כֹּ֣ה] disse disse yhwh [בְּעֵ֤ת] [רָצוֹן֙] [עֲנִיתִ֔יךָ] [וּבְי֥וֹם] [יְשׁוּעָ֖ה] [עֲזַרְתִּ֑יךָ] [וְאֶצָּרְךָ֗] [וְאֶתֶּנְךָ֙] povo [עָ֔ם] terra terra [לְהַנְחִ֖יל] [נְחָל֥וֹת]');
INSERT INTO verses VALUES (18715, 23, 49, 9, 'dizendo [לַֽאֲסוּרִים֙] [צֵ֔אוּ] [לַאֲשֶׁ֥ר] [בַּחֹ֖שֶׁךְ] [הִגָּל֑וּ] sobre [יִרְע֔וּ] [וּבְכָל־שְׁפָיִ֖ים] e-em-todo');
INSERT INTO verses VALUES (18716, 23, 49, 10, 'não [יִרְעָ֙בוּ֙] e-não [יִצְמָ֔אוּ] e-não [שָׁרָ֖ב] [וָשָׁ֑מֶשׁ] [כִּי־מְרַחֲמָ֣ם] porque [וְעַל־מַבּ֥וּעֵי] águas e-sobre águas');
INSERT INTO verses VALUES (18717, 23, 49, 11, '[וְשַׂמְתִּ֥י] todo [לַדָּ֑רֶךְ] [וּמְסִלֹּתַ֖י] [יְרֻמֽוּן]');
INSERT INTO verses VALUES (18718, 23, 49, 12, 'eis [מֵרָח֖וֹק] [יָבֹ֑אוּ] [וְהִֽנֵּה־אֵ֙לֶּה֙] [מִצָּפ֣וֹן] estes [וְאֵ֖לֶּה] [מֵאֶ֥רֶץ] [סִינִֽים]');
INSERT INTO verses VALUES (18719, 23, 49, 13, '[רָנּ֤וּ] céus [וְגִ֣ילִי] terra as-montanhas [**וּפִצְח֥וּ] porque [רִנָּ֑ה] yhwh yhwh [עַמּ֔וֹ] [וַעֲנִיָּ֖ו]');
INSERT INTO verses VALUES (18720, 23, 49, 14, 'E-disse Sião [עֲזָבַ֣נִי] yhwh [וַאדֹנָ֖י] [שְׁכֵחָֽנִי]');
INSERT INTO verses VALUES (18721, 23, 49, 15, '[הֲתִשְׁכַּ֤ח] mulher [עוּלָ֔הּ] [מֵרַחֵ֖ם] filho-de [גַּם־אֵ֣לֶּה] também estes não [אֶשְׁכָּחֵֽךְ] não');
INSERT INTO verses VALUES (18722, 23, 49, 16, 'eis sobre [חַקֹּתִ֑יךְ] [חוֹמֹתַ֥יִךְ] [נֶגְדִּ֖י] [תָּמִֽיד]');
INSERT INTO verses VALUES (18723, 23, 49, 17, '[מִֽהֲר֖וּ] [בָּנָ֑יִךְ] [מְהָֽרְסַ֥יִךְ] [וּמַחֲרִבַ֖יִךְ] [מִמֵּ֥ךְ] [יֵצֵֽאוּ]');
INSERT INTO verses VALUES (18724, 23, 49, 18, '[שְׂאִֽי־סָבִ֤יב] [עֵינַ֙יִךְ֙] [וּרְאִ֔י] [כֻּלָּ֖ם] [נִקְבְּצ֣וּ] [בָֽאוּ־לָ֑ךְ] [חַי־אָ֣נִי] a-ti que [כֻלָּם֙] oráculo-de yhwh porque [כַּכַּלָּֽה]');
INSERT INTO verses VALUES (18725, 23, 49, 19, 'que [חָרְבֹתַ֙יִךְ֙] [וְשֹׁ֣מְמֹתַ֔יִךְ] [וְאֶ֖רֶץ] [הֲרִֽסֻתֵ֑יךְ] que agora [תֵּצְרִ֣י] [מִיּוֹשֵׁ֔ב] [וְרָחֲק֖וּ] [מְבַלְּעָֽיִךְ]');
INSERT INTO verses VALUES (18726, 23, 49, 20, 'ainda dirão [בְאָזְנַ֔יִךְ] filhos-de [שִׁכֻּלָ֑יִךְ] [צַר־לִ֥י] para-mim o-lugar [וְאֵשֵֽׁבָה] para-mim [sem-traducao]');
INSERT INTO verses VALUES (18727, 23, 49, 21, '[וְאָמַ֣רְתְּ] [בִּלְבָבֵ֗ךְ] quem [יָֽלַד־לִי֙] para-mim a [שְׁכוּלָ֖ה] [וְגַלְמוּדָ֑ה] [גֹּלָ֣ה] [׀] [וְסוּרָ֗ה] [וְאֵ֙לֶּה֙] quem quem eis [אֲנִי֙] eu [לְבַדִּ֔י] Estas [אֵיפֹ֥ה] eles eles');
INSERT INTO verses VALUES (18728, 23, 49, 22, 'assim disse Adonai eis eis [אֶל־גּוֹיִם֙] a nações [אָרִ֣ים] e-a [וְהֵבִ֤יאוּ] [בָנַ֙יִךְ֙] [בְּחֹ֔צֶן] [וּבְנֹתַ֖יִךְ] [עַל־כָּתֵ֥ף] [תִּנָּשֶֽׂאנָה] [sem-traducao] sobre [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18729, 23, 49, 23, 'e-sejam [מְלָכִ֜ים] [אֹֽמְנַ֗יִךְ] [וְשָׂרֽוֹתֵיהֶם֙] [מֵינִ֣יקֹתַ֔יִךְ] [אַפַּ֗יִם] terra [יִשְׁתַּ֣חֲווּ] para-ti [וַעֲפַ֥ר] [רַגְלַ֖יִךְ] [יְלַחֵ֑כוּ] [וְיָדַ֙עַתְּ֙] porque yhwh yhwh que não');
INSERT INTO verses VALUES (18730, 23, 49, 24, '[הֲיֻקַּ֥ח] [מִגִּבּ֖וֹר] [מַלְק֑וֹחַ] e-se [צַדִּ֖יק] [יִמָּלֵֽט]');
INSERT INTO verses VALUES (18731, 23, 49, 25, 'porque assim disse yhwh também [גִבּוֹר֙] [יֻקָּ֔ח] [וּמַלְק֥וֹחַ] [עָרִ֖יץ] [יִמָּלֵ֑ט] [וְאֶת־יְרִיבֵךְ֙] eu [אָרִ֔יב] [וְאֶת־בָּנַ֖יִךְ] eu e-[OBJ] [sem-traducao] eu [sem-traducao]');
INSERT INTO verses VALUES (18732, 23, 49, 26, '[וְהַאֲכַלְתִּ֤י] a [אֶת־בְּשָׂרָ֔ם] a [דָּמָ֣ם] [יִשְׁכָּר֑וּן] [וְיָדְע֣וּ] [כָל־בָּשָׂ֗ר] que todo yhwh porque eu yhwh [יַעֲקֹֽב׃] Jacó');
INSERT INTO chapters VALUES (729, 23, 50, 11);
INSERT INTO verses VALUES (18733, 23, 50, 1, '[כֹּ֣ה] disse disse yhwh [אֵ֣י] livro [סֵ֣פֶר] [כְּרִית֤וּת] que [אֲשֶׁ֣ר] ou quem quem que [אֲשֶׁר־מָכַ֥רְתִּי] vos a-ele eis [בַּעֲוֺנֹֽתֵיכֶם֙] [נִמְכַּרְתֶּ֔ם] [וּבְפִשְׁעֵיכֶ֖ם] [שֻׁלְּחָ֥ה] [אִמְּכֶֽם]');
INSERT INTO verses VALUES (18734, 23, 50, 2, '[מַדּ֨וּעַ] [בָּ֜אתִי] e-não-há homem [קָרָֽאתִי֮] e-não-há [עוֹנֶה֒] [הֲקָצ֨וֹר] [קָצְרָ֤ה] [יָדִי֙] [מִפְּד֔וּת] e-se não-há [לְהַצִּ֑יל] eis [בְּגַעֲרָתִ֞י] eis mar [אָשִׂ֤ים] [נְהָרוֹת֙] [מִדְבָּ֔ר] [תִּבְאַ֤שׁ] [דְּגָתָם֙] [מֵאֵ֣ין] águas [וְתָמֹ֖ת] águas [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18735, 23, 50, 3, '[אַלְבִּ֥ישׁ] céus [קַדְר֑וּת] [וְשַׂ֖ק] [אָשִׂ֥ים] [כְּסוּתָֽם׃]');
INSERT INTO verses VALUES (18736, 23, 50, 4, 'Adonai yhwh dar para-mim língua-de [לִמּוּדִ֔ים] para-conhecer [לָע֥וּת] a [דָּבָ֑ר] palavra [׀] [בַּבֹּ֣קֶר] [בַּבֹּ֗קֶר] [יָעִ֥יר] para-mim [אֹ֔זֶן] [לִשְׁמֹ֖עַ] [כַּלִּמּוּדִֽים]');
INSERT INTO verses VALUES (18737, 23, 50, 5, 'Adonai yhwh [פָּתַֽח־לִ֣י] para-mim [וְאָנֹכִ֖י] não não [אָח֖וֹר] não não');
INSERT INTO verses VALUES (18738, 23, 50, 6, 'nação dei [לְמַכִּ֔ים] [וּלְחָיַ֖י] [לְמֹֽרְטִ֑ים] face-de não [הִסְתַּ֔רְתִּי] [מִכְּלִמּ֖וֹת] [וָרֹֽק]');
INSERT INTO verses VALUES (18739, 23, 50, 7, '[וַאדֹנָ֤י] yhwh [יַֽעֲזָר־לִ֔י] a-mim não assim não [שַׂ֤מְתִּי] sobre [כַּֽחַלָּמִ֔ישׁ] [וָאֵדַ֖ע] face-de [אֵבֽוֹשׁ] porque não');
INSERT INTO verses VALUES (18740, 23, 50, 8, 'proximo [מַצְדִּיקִ֔י] quem [אִתִּ֖י] [נַ֣עַמְדָה] [יָּ֑חַד] [מִֽי־בַ֥עַל] quem [יִגַּ֥שׁ] [אֵלָֽי] [sem-traducao] para-mim');
INSERT INTO verses VALUES (18741, 23, 50, 9, 'eis Adonai yhwh [יַֽעֲזָר־לִ֔י] a-mim [יַרְשִׁיעֵ֑נִי] eis [כֻּלָּם֙] [כַּבֶּ֣גֶד] [יִבְל֔וּ] [עָ֖שׁ] [יֹאכְלֵֽם]');
INSERT INTO verses VALUES (18742, 23, 50, 10, 'quem [בָכֶם֙] [יְרֵ֣א] yhwh ouviu com-voz seu-servo [אֲשֶׁ֣ר] andou andar e-não-há [וְאֵ֥ין] a-ele a-ele no-nome-de yhwh yhwh [וְיִשָּׁעֵ֖ן]');
INSERT INTO verses VALUES (18743, 23, 50, 11, 'eis [כֻּלְּכֶ֛ם] [קֹ֥דְחֵי] [אֵ֖שׁ] [מְאַזְּרֵ֣י] [זִיק֑וֹת] [לְכ֣וּ] [׀] [בְּא֣וּר] [אֶשְׁכֶ֗ם] [וּבְזִיקוֹת֙] [בִּֽעַרְתֶּ֔ם] [מִיָּדִי֙] [הָיְתָה־זֹּ֣את] a-vós [לְמַעֲצֵבָ֖ה] [תִּשְׁכָּבֽוּן׃]');
INSERT INTO chapters VALUES (730, 23, 51, 23);
INSERT INTO verses VALUES (18744, 23, 51, 1, 'ouvi a-mim [רֹ֥דְפֵי] [צֶ֖דֶק] [מְבַקְשֵׁ֣י] yhwh [הַבִּ֙יטוּ֙] a [חֻצַּבְתֶּ֔ם] [וְאֶל־מַקֶּ֥בֶת] e-a [נֻקַּרְתֶּֽם]');
INSERT INTO verses VALUES (18745, 23, 51, 2, '[הַבִּ֙יטוּ֙] a Abraão [וְאֶל־שָׂרָ֖ה] e-a [כִּי־אֶחָ֣ד] [קְרָאתִ֔יו] porque um');
INSERT INTO verses VALUES (18746, 23, 51, 3, 'porque yhwh yhwh Siao [כָּל־חָרְבֹתֶ֔יהָ] todo [מִדְבָּרָהּ֙] [כְּעֵ֔דֶן] [וְעַרְבָתָ֖הּ] [כְּגַן־יְהוָ֑ה] [שָׂשׂ֤וֹן] [וְשִׂמְחָה֙] yhwh [בָ֔הּ] [תּוֹדָ֖ה] [וְק֥וֹל] [זִמְרָֽה׃] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18747, 23, 51, 4, '[הַקְשִׁ֤יבוּ] a-mim [עַמִּ֔י] [וּלְאוּמִּ֖י] a-mim [הַאֲזִ֑ינוּ] que [תוֹרָה֙] [מֵאִתִּ֣י] [תֵצֵ֔א] [וּמִשְׁפָּטִ֔י] [לְא֥וֹר] [עַמִּ֖ים] [אַרְגִּֽיעַ]');
INSERT INTO verses VALUES (18748, 23, 51, 5, '[קָר֤וֹב] [צִדְקִי֙] sair [יִשְׁעִ֔י] [וּזְרֹעַ֖י] povos [יִשְׁפֹּ֑טוּ] a-mim [אִיִּ֣ים] [יְקַוּ֔וּ] e-a [יְיַחֵלֽוּן]');
INSERT INTO verses VALUES (18749, 23, 51, 6, '[שְׂאוּ֩] [לַשָּׁמַ֨יִם] vossos-olhos [וְֽהַבִּ֧יטוּ] a debaixo-de [כִּֽי־שָׁמַ֜יִם] porque céus E-a-terra [כַּבֶּ֣גֶד] [תִּבְלֶ֔ה] [וְיֹשְׁבֶ֖יהָ] [כְּמוֹ־כֵ֣ן] [יְמוּת֑וּן] como [לְעוֹלָ֣ם] [תִּֽהְיֶ֔ה] [וְצִדְקָתִ֖י] não [תֵחָֽת׃] não');
INSERT INTO verses VALUES (18750, 23, 51, 7, 'ouvi a-mim conhecendo [צֶ֔דֶק] povo [תּוֹרָתִ֣י] [בְלִבָּ֑ם] a [חֶרְפַּ֣ת] [אֱנ֔וֹשׁ] [וּמִגִּדֻּפֹתָ֖ם] [אַל־תֵּחָֽתּוּ] a');
INSERT INTO verses VALUES (18751, 23, 51, 8, 'que [כַבֶּ֙גֶד֙] [יֹאכְלֵ֣ם] [עָ֔שׁ] [וְכַצֶּ֖מֶר] [יֹאכְלֵ֣ם] [סָ֑ס] [וְצִדְקָתִי֙] para-sempre [תִּֽהְיֶ֔ה] [וִישׁוּעָתִ֖י] para-geração [דּוֹרִֽים׃]');
INSERT INTO verses VALUES (18752, 23, 51, 9, '[עוּרִ֨י] [עוּרִ֤י] [לִבְשִׁי־עֹז֙] [זְר֣וֹעַ] yhwh yhwh [כִּ֣ימֵי] oriente [דֹּר֖וֹת] [עוֹלָמִ֑ים] [הֲל֥וֹא] [אַתְּ־הִ֛יא] [OBJ] [רַ֖הַב] [מְחוֹלֶ֥לֶת] monstro-marinho');
INSERT INTO verses VALUES (18753, 23, 51, 10, '[הֲל֤וֹא] [OBJ] ela mar mar [תְּה֣וֹם] [רַבָּ֑ה] multiplicai [מַֽעֲמַקֵּי־יָ֔ם] o-caminho-de mar caminho para-passar [sem-traducao]');
INSERT INTO verses VALUES (18754, 23, 51, 11, '[וּפְדוּיֵ֨י] yhwh [יְשׁוּב֗וּן] [וּבָ֤אוּ] Siao [בְּרִנָּ֔ה] [וְשִׂמְחַ֥ת] eternidade sobre [שָׂשׂ֤וֹן] [וְשִׂמְחָה֙] [יַשִּׂיג֔וּן] [נָ֖סוּ] [יָג֥וֹן] [וַאֲנָחָֽה׃] [sem-traducao]');
INSERT INTO verses VALUES (18755, 23, 51, 12, 'eu eu ele [מְנַחֶמְכֶ֑ם] quem [OBJ] [מֵאֱנ֣וֹשׁ] [יָמ֔וּת] [וּמִבֶּן־אָדָ֖ם] [חָצִ֥יר] homem');
INSERT INTO verses VALUES (18756, 23, 51, 13, '[וַתִּשְׁכַּ֞ח] yhwh [עֹשֶׂ֗ךָ] [נוֹטֶ֣ה] céus [וְיֹסֵ֣ד] terra [וַתְּפַחֵ֨ד] [תָּמִ֜יד] todo de-diante-de [חֲמַ֣ת] [הַמֵּצִ֔יק] [כַּאֲשֶׁ֥ר] como [לְהַשְׁחִ֑ית] [וְאַיֵּ֖ה] [חֲמַ֥ת] [הַמֵּצִֽיק]');
INSERT INTO verses VALUES (18757, 23, 51, 14, '[מִהַ֥ר] [צֹעֶ֖ה] [לְהִפָּתֵ֑חַ] e-não [לַשַּׁ֔חַת] [וְלֹ֥א] e-não [לַחְמֽוֹ]');
INSERT INTO verses VALUES (18758, 23, 51, 15, '[וְאָֽנֹכִי֙] yhwh teu-Elohim [רֹגַ֣ע] o-mar [וַיֶּהֱמ֖וּ] [גַּלָּ֑יו] yhwh exércitos [שְׁמֽוֹ]');
INSERT INTO verses VALUES (18759, 23, 51, 16, '[וָאָשִׂ֤ים] [דְּבָרַי֙] [בְּפִ֔יךָ] [וּבְצֵ֥ל] [יָדִ֖י] [כִּסִּיתִ֑יךָ] [לִנְטֹ֤עַ] céus [וְלִיסֹ֣ד] terra [וְלֵאמֹ֥ר] [לְצִיּ֖וֹן] [עַמִּי־אָֽתָּה׃]');
INSERT INTO verses VALUES (18760, 23, 51, 17, '[הִתְעוֹרְרִ֣י] [הִֽתְעוֹרְרִ֗י] [ק֚וּמִי] Jerusalém que [שָׁתִ֛ית] [מִיַּ֥ד] yhwh a [חֲמָת֑וֹ] [אֶת־קֻבַּ֜עַת] a [הַתַּרְעֵלָ֛ה] [שָׁתִ֖ית] [מָצִֽית]');
INSERT INTO verses VALUES (18761, 23, 51, 18, 'não-há [לָ֔הּ] [מִכָּל־בָּנִ֖ים] de-todo [וְאֵ֤ין] deu-a-luz [בְּיָדָ֔הּ] [מִכָּל־בָּנִ֖ים] [גִּדֵּֽלָה] de-todo que [sem-traducao]');
INSERT INTO verses VALUES (18762, 23, 51, 19, '[שְׁתַּ֤יִם] [הֵ֙נָּה֙] [קֹֽרְאֹתַ֔יִךְ] quem [יָנ֣וּד] para-ti [הַשֹּׁ֧ד] [וְהַשֶּׁ֛בֶר] [וְהָרָעָ֥ב] [וְהַחֶ֖רֶב] quem [אֲנַחֲמֵֽךְ]');
INSERT INTO verses VALUES (18763, 23, 51, 20, '[בָּנַ֜יִךְ] [עֻלְּפ֥וּ] [שָׁכְב֛וּ] [בְּרֹ֥אשׁ] todo [כְּת֣וֹא] [מִכְמָ֑ר] [הַֽמְלֵאִ֥ים] [חֲמַת־יְהוָ֖ה] Hamate yhwh [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18764, 23, 51, 21, 'por-isso [שִׁמְעִי־נָ֥א] esta esta [וּשְׁכֻרַ֖ת] [וְלֹ֥א] e-não [sem-traducao]');
INSERT INTO verses VALUES (18765, 23, 51, 22, 'assim disse yhwh yhwh [יָרִ֣יב] [עַמּ֔וֹ] eis eis [מִיָּדֵ֖ךְ] [אֶת־כּ֣וֹס] a [אֶת־קֻבַּ֙עַת֙] [כּ֣וֹס] a [לֹא־תוֹסִ֥יפִי] [לִשְׁתּוֹתָ֖הּ] [עֽוֹד] não');
INSERT INTO verses VALUES (18766, 23, 51, 23, '[וְשַׂמְתִּ֙יהָ֙] pela-mão-de [אֲשֶׁר־אָמְר֥וּ] que [שְׁחִ֣י] [וְנַעֲבֹ֑רָה] [וַתָּשִׂ֤ימִי] [כָאָ֙רֶץ֙] [גֵּוֵ֔ךְ] [וְכַח֖וּץ] [לַעֹבְרִֽים׃]');
INSERT INTO chapters VALUES (731, 23, 52, 15);
INSERT INTO verses VALUES (18767, 23, 52, 1, '[עוּרִ֥י] [עוּרִ֛י] [לִבְשִׁ֥י] [עֻזֵּ֖ךְ] Sião [לִבְשִׁ֣י] [׀] [בִּגְדֵ֣י] [תִפְאַרְתֵּ֗ךְ] cidade [עִ֣יר] porque que não [יוֹסִ֛יף] [יָבֹא־בָ֥ךְ] ainda [עָרֵ֥ל] [וְטָמֵֽא]');
INSERT INTO verses VALUES (18768, 23, 52, 2, '[הִתְנַעֲרִ֧י] [מֵעָפָ֛ר] [ק֥וּמִי] [שְּׁבִ֖י] [יְרֽוּשָׁלָ֑͏ִם] [*התפתחו] [**הִֽתְפַּתְּחִי֙] [מוֹסרֵ֣י] filha-de [שְׁבִיָּ֖ה]');
INSERT INTO verses VALUES (18769, 23, 52, 3, 'porque disse yhwh yhwh [נִמְכַּרְתֶּ֑ם] [וְלֹ֥א] e-não [תִּגָּאֵֽלוּ]');
INSERT INTO verses VALUES (18770, 23, 52, 4, 'que assim disse Adonai yhwh [מִצְרַ֛יִם] [יָֽרַד־עַמִּ֥י] [בָרִֽאשֹׁנָ֖ה] [לָג֣וּר] [שָׁ֑ם] nome [בְּאֶ֥פֶס] [עֲשָׁקֽוֹ] [sem-traducao]');
INSERT INTO verses VALUES (18771, 23, 52, 5, 'e-agora [*מי־*לי־**מַה־**לִּי־פֹה֙] oráculo-de yhwh porque tomou [*משלו] [**מֹשְׁלָ֤יו] [יְהֵילִ֙ילוּ֙] oráculo-de yhwh [כָּל־הַיּ֖וֹם] todo [מִנֹּאָּֽץ]');
INSERT INTO verses VALUES (18772, 23, 52, 6, 'por-isso conheceu [עַמִּ֖י] [שְׁמִ֑י] [לָכֵן֙] no-dia aquele porque [הַֽמְדַבֵּ֖ר] ele');
INSERT INTO verses VALUES (18773, 23, 52, 7, 'que [עַל־הֶהָרִ֜ים] sobre [מְבַשֵּׂ֗ר] [מַשְׁמִ֧יעַ] [שָׁל֛וֹם] [מְבַשֵּׂ֥ר] bom [מַשְׁמִ֣יעַ] bom [אֹמֵ֥ר] [לְצִיּ֖וֹן] disse [אֱלֹהָֽיִךְ] rei');
INSERT INTO verses VALUES (18774, 23, 52, 8, 'voz [צֹפַ֛יִךְ] [נָ֥שְׂאוּ] voz [יַחְדָּ֣ו] [יְרַנֵּ֑נוּ] que olho [בְּעַ֙יִן֙] [יִרְא֔וּ] [בְּשׁ֥וּב] yhwh [צִיּֽוֹן]');
INSERT INTO verses VALUES (18775, 23, 52, 9, '[פִּצְח֤וּ] [רַנְּנוּ֙] [יַחְדָּ֔ו] [חָרְב֖וֹת] Jerusalém porque yhwh yhwh seu-povo [יְרוּשָׁלָֽ͏ִם] Jerusalém');
INSERT INTO verses VALUES (18776, 23, 52, 10, '[חָשַׂ֤ף] yhwh a [קָדְשׁ֔וֹ] [לְעֵינֵ֖י] aos-olhos-de todo as-nações [OBJ] todo [אֱלֹהֵֽינוּ׃] terra a');
INSERT INTO verses VALUES (18777, 23, 52, 11, '[ס֤וּרוּ] [ס֙וּרוּ֙] [צְא֣וּ] [מִשָּׁ֔ם] [טָמֵ֖א] a [צְא֣וּ] [מִתּוֹכָ֔הּ] [הִבָּ֕רוּ] [נֹשְׂאֵ֖י] [כְּלֵ֥י] yhwh yhwh');
INSERT INTO verses VALUES (18778, 23, 52, 12, 'que não [בְחִפָּזוֹן֙] [תֵּצֵ֔אוּ] [וּבִמְנוּסָ֖ה] não [תֵלֵכ֑וּן] porque andou yhwh yhwh [Elohim] Elohim-de Israel');
INSERT INTO verses VALUES (18779, 23, 52, 13, 'eis [יַשְׂכִּ֖יל] [עַבְדִּ֑י] [יָר֧וּם] [וְנִשָּׂ֛א] [וְגָבַ֖הּ] muito');
INSERT INTO verses VALUES (18780, 23, 52, 14, 'como [שָׁמְמ֤וּ] sobre-ti muitos [כֵּן־מִשְׁחַ֥ת] [מֵאִ֖ישׁ] [מַרְאֵ֑הוּ] [וְתֹאֲר֖וֹ] [מִבְּנֵ֥י] homem homem');
INSERT INTO verses VALUES (18781, 23, 52, 15, 'assim [יַזֶּה֙] nações muitos [עָלָ֛יו] [יִקְפְּצ֥וּ] [מְלָכִ֖ים] [פִּיהֶ֑ם] que que não a-eles a-eles [וַאֲשֶׁ֥ר] e-que não');
INSERT INTO chapters VALUES (732, 23, 53, 12);
INSERT INTO verses VALUES (18782, 23, 53, 1, 'quem [הֶאֱמִ֖ין] [לִשְׁמֻעָתֵ֑נוּ] [וּזְר֥וֹעַ] yhwh sobre quem');
INSERT INTO verses VALUES (18783, 23, 53, 2, 'e-subiu [כַּיּוֹנֵ֜ק] diante-dele [וְכַשֹּׁ֙רֶשׁ֙] da-terra [צִיָּ֔ה] não a-ele a-ele e-não [וְנִרְאֵ֥הוּ] [וְלֹֽא־מַרְאֶ֖ה] e-não aparência [sem-traducao]');
INSERT INTO verses VALUES (18784, 23, 53, 3, '[נִבְזֶה֙] [וַחֲדַ֣ל] [אִישִׁ֔ים] homem [מַכְאֹב֖וֹת] [וִיד֣וּעַ] [חֹ֑לִי] [וּכְמַסְתֵּ֤ר] face nós [נִבְזֶ֖ה] e-não [חֲשַׁבְנֻֽהוּ]');
INSERT INTO verses VALUES (18785, 23, 53, 4, '[אָכֵ֤ן] [חֳלָיֵ֙נוּ֙] ele [נָשָׂ֔א] [וּמַכְאֹבֵ֖ינוּ] [סְבָלָ֑ם] [וַאֲנַ֣חְנוּ] [חֲשַׁבְנֻ֔הוּ] [נָג֛וּעַ] [מֻכֵּ֥ה] Elohim [וּמְעֻנֶּֽה]');
INSERT INTO verses VALUES (18786, 23, 53, 5, 'e-ele [מְחֹלָ֣ל] [מִפְּשָׁעֵ֔נוּ] [מְדֻכָּ֖א] [מֵעֲוֺנֹתֵ֑ינוּ] [מוּסַ֤ר] [שְׁלוֹמֵ֙נוּ֙] sobre-ele [וּבַחֲבֻרָת֖וֹ] [נִרְפָּא־לָֽנוּ]');
INSERT INTO verses VALUES (18787, 23, 53, 6, '[כֻּלָּ֙נוּ֙] [כַּצֹּ֣אן] [תָּעִ֔ינוּ] homem [לְדַרְכּ֖וֹ] [פָּנִ֑ינוּ] [וַֽיהוָה֙] [הִפְגִּ֣יעַ] nele a [עֲוֺ֥ן] [כֻּלָּֽנוּ]');
INSERT INTO verses VALUES (18788, 23, 53, 7, '[נִגַּ֨שׂ] e-ele [נַעֲנֶה֮] e-não [יִפְתַּח־פִּיו֒] [כַּשֶּׂה֙] [לַטֶּ֣בַח] [יוּבָ֔ל] [וּכְרָחֵ֕ל] [לִפְנֵ֥י] diante-de [נֶאֱלָ֑מָה] [וְלֹ֥א] e-não [פִּֽיו]');
INSERT INTO verses VALUES (18789, 23, 53, 8, '[מֵעֹ֤צֶר] [וּמִמִּשְׁפָּט֙] tomou e-[OBJ] quem quem que porque [מֵאֶ֣רֶץ] vida [מִפֶּ֥שַׁע] [עַמִּ֖י] [נֶ֥גַע] [לָֽמוֹ] a-eles');
INSERT INTO verses VALUES (18790, 23, 53, 9, 'E-colocou a [קִבְר֔וֹ] [וְאֶת־עָשִׁ֖יר] e-[OBJ] sobre [לֹא־חָמָ֣ס] sobre não [מִרְמָ֖ה] fez e-não');
INSERT INTO verses VALUES (18791, 23, 53, 10, '[וַיהוָ֞ה] [חָפֵ֤ץ] [דַּכְּאוֹ֙] [הֶֽחֱלִ֔י] se [אָשָׁם֙] [נַפְשׁ֔וֹ] [יִרְאֶ֥ה] semente [יַאֲרִ֣יךְ] [יָמִ֑ים] [וְחֵ֥פֶץ] yhwh yhwh [יִצְלָֽח]');
INSERT INTO verses VALUES (18792, 23, 53, 11, '[מֵעֲמַ֤ל] [נַפְשׁוֹ֙] [יִרְאֶ֣ה] [יִשְׂבָּ֔ע] [בְּדַעְתּ֗וֹ] [יַצְדִּ֥יק] [צַדִּ֛יק] [עַבְדִּ֖י] [לָֽרַבִּ֑ים] [וַעֲוֺנֹתָ֖ם] ele [יִסְבֹּֽל]');
INSERT INTO verses VALUES (18793, 23, 53, 12, 'portanto [אֲחַלֶּק־ל֣וֹ] a-ele [וְאֶת־עֲצוּמִים֮] e-[OBJ] [שָׁלָל֒] debaixo [אֲשֶׁ֨ר] [הֶעֱרָ֤ה] que [נַפְשׁ֔וֹ] [וְאֶת־פֹּשְׁעִ֖ים] [נִמְנָ֑ה] e-[OBJ] [חֵטְא־רַבִּ֣ים] [נָשָׂ֔א] e-ele [יַפְגִּֽיעַ׃]');
INSERT INTO chapters VALUES (733, 23, 54, 17);
INSERT INTO verses VALUES (18794, 23, 54, 1, '[רָנִּ֥י] [עֲקָרָ֖ה] não deu-a-luz [פִּצְחִ֨י] [רִנָּ֤ה] [וְצַהֲלִי֙] não [כִּֽי־רַבִּ֧ים] porque [מִבְּנֵ֥י] [בְעוּלָ֖ה] disse yhwh [sem-traducao] disse yhwh');
INSERT INTO verses VALUES (18795, 23, 54, 2, '[הַרְחִ֣יבִי] lugar [מְק֣וֹם] [אָהֳלֵ֗ךְ] [וִירִיע֧וֹת] [מִשְׁכְּנוֹתַ֛יִךְ] a [אַל־תַּחְשֹׂ֑כִי] [הַאֲרִ֙יכִי֙] [מֵֽיתָרַ֔יִךְ] [וִיתֵדֹתַ֖יִךְ] [חַזֵּֽקִי]');
INSERT INTO verses VALUES (18796, 23, 54, 3, 'porque [וּשְׂמֹ֖אול] [תִּפְרֹ֑צִי] [וְזַרְעֵךְ֙] [גּוֹיִ֣ם] nações [וְעָרִ֥ים] [נְשַׁמּ֖וֹת] [יוֹשִֽׁיבוּ]');
INSERT INTO verses VALUES (18797, 23, 54, 4, 'a [כִּי־לֹ֣א] porque não que não [תַחְפִּ֑ירִי] que não [עֲלוּמַ֙יִךְ֙] porque [וְחֶרְפַּ֥ת] [אַלְמְנוּתַ֖יִךְ] não [תִזְכְּרִי־עֽוֹד] não');
INSERT INTO verses VALUES (18798, 23, 54, 5, 'que [בֹעֲלַ֙יִךְ֙] [עֹשַׂ֔יִךְ] yhwh exércitos seu-nome [וְגֹֽאֲלֵךְ֙] santo Israel Elohim-de todo será-chamada');
INSERT INTO verses VALUES (18799, 23, 54, 6, 'porque [עֲזוּבָ֛ה] [וַעֲצ֥וּבַת] espírito espírito yhwh yhwh [נְעוּרִ֛ים] que porque disse disse');
INSERT INTO verses VALUES (18800, 23, 54, 7, '[בְּרֶ֥גַע] pequeno [עֲזַבְתִּ֑יךְ] [וּבְרַחֲמִ֥ים] [גְּדֹלִ֖ים] [אֲקַבְּצֵֽךְ]');
INSERT INTO verses VALUES (18801, 23, 54, 8, '[בְּשֶׁ֣צֶף] [קֶ֗צֶף] [הִסְתַּ֨רְתִּי] face-de [רֶ֙גַע֙] [מִמֵּ֔ךְ] [וּבְחֶ֥סֶד] eternidade [רִֽחַמְתִּ֑יךְ] disse [גֹּאֲלֵ֖ךְ] yhwh');
INSERT INTO verses VALUES (18802, 23, 54, 9, 'porque [נֹ֙חַ֙] esta [לִ֔י] a-mim que [מֵעֲבֹ֥ר] [מֵי־נֹ֛חַ] [ע֖וֹד] [עַל־הָאָ֑רֶץ] ainda sobre a-terra assim [וּמִגְּעָר־בָּֽךְ]');
INSERT INTO verses VALUES (18803, 23, 54, 10, 'que os-montes [יָמ֔וּשׁוּ] [וְהַגְּבָע֖וֹת] [תְּמוּטֶ֑נָה] [וְחַסְדִּ֞י] [מֵאִתֵּ֣ךְ] não [וּבְרִ֤ית] [שְׁלוֹמִי֙] não não disse disse yhwh yhwh');
INSERT INTO verses VALUES (18804, 23, 54, 11, '[עֲנִיָּ֥ה] [סֹעֲרָ֖ה] não [נֻחָ֑מָה] eis eu [מַרְבִּ֤יץ] [בַּפּוּךְ֙] [אֲבָנַ֔יִךְ] [וִיסַדְתִּ֖יךְ] [בַּסַּפִּירִֽים]');
INSERT INTO verses VALUES (18805, 23, 54, 12, '[וְשַׂמְתִּ֤י] [כַּֽדְכֹד֙] [שִׁמְשֹׁתַ֔יִךְ] [וּשְׁעָרַ֖יִךְ] [לְאַבְנֵ֣י] [אֶקְדָּ֑ח] e-todo [לְאַבְנֵי־חֵֽפֶץ]');
INSERT INTO verses VALUES (18806, 23, 54, 13, 'e-todo [לִמּוּדֵ֣י] yhwh yhwh [שְׁל֥וֹם] [בָּנָֽיִךְ]');
INSERT INTO verses VALUES (18807, 23, 54, 14, '[בִּצְדָקָ֖ה] [תִּכּוֹנָ֑נִי] [רַחֲקִ֤י] [מֵעֹ֙שֶׁק֙] porque não [וּמִ֨מְּחִתָּ֔ה] que porque não');
INSERT INTO verses VALUES (18808, 23, 54, 15, 'eis [גּ֥וֹר] [יָג֛וּר] [אֶ֖פֶס] [מֵֽאוֹתִ֑י] [מִי־גָ֥ר] [אִתָּ֖ךְ] [עָלַ֥יִךְ] [יִפּֽוֹל]');
INSERT INTO verses VALUES (18809, 23, 54, 16, 'eu [**הִנֵּ֤ה] eu [בָּרָ֣אתִי] [חָרָ֔שׁ] [נֹפֵ֙חַ֙] [בְּאֵ֣שׁ] [פֶּחָ֔ם] [וּמוֹצִ֥יא] [כְלִ֖י] [לְמַעֲשֵׂ֑הוּ] [וְאָנֹכִ֛י] [בָּרָ֥אתִי]');
INSERT INTO verses VALUES (18810, 23, 54, 17, 'todo [יוּצַ֤ר] [עָלַ֙יִךְ֙] não não [וְכָל־לָשׁ֛וֹן] e-todo [לַמִּשְׁפָּ֖ט] [תַּרְשִׁ֑יעִי] esta [נַחֲלַת֩] [עַבְדֵ֨י] yhwh [וְצִדְקָתָ֛ם] [מֵאִתִּ֖י] yhwh oráculo-de yhwh');
INSERT INTO chapters VALUES (734, 23, 55, 13);
INSERT INTO verses VALUES (18811, 23, 55, 1, '[ה֤וֹי] todo [לְכ֣וּ] [לַמַּ֔יִם] [וַאֲשֶׁ֥ר] e-que não-há a-ele prata [וֶֽאֱכֹ֔לוּ] [וּלְכ֣וּ] [שִׁבְר֗וּ] [בְּלוֹא־כֶ֛סֶף] [וּבְל֥וֹא] [מְחִ֖יר] [יַ֥יִן] [וְחָלָֽב]');
INSERT INTO verses VALUES (18812, 23, 55, 2, 'por-que [תִשְׁקְלוּ־כֶ֙סֶף֙] [בְּֽלוֹא־לֶ֔חֶם] [וִיגִיעֲכֶ֖ם] [בְּל֣וֹא] [לְשָׂבְעָ֑ה] [שִׁמְע֨וּ] [שָׁמ֤וֹעַ] [אֵלַי֙] [וְאִכְלוּ־ט֔וֹב] a-mim [בַּדֶּ֖שֶׁן] bom');
INSERT INTO verses VALUES (18813, 23, 55, 3, '[הַטּ֤וּ] [אָזְנְכֶם֙] [וּלְכ֣וּ] a-mim ouvi [וּתְחִ֣י] [נַפְשְׁכֶ֑ם] [וְאֶכְרְתָ֤ה] a-vós [בְּרִ֣ית] eternidade [חַֽסְדֵ֥י] Davi [הַנֶּאֱמָנִֽים]');
INSERT INTO verses VALUES (18814, 23, 55, 4, 'eis até [לְאוּמִּ֖ים] [נְתַתִּ֑יו] [נָגִ֥יד] [וּמְצַוֵּ֖ה] [לְאֻמִּֽים]');
INSERT INTO verses VALUES (18815, 23, 55, 5, 'eis nação não [תִּקְרָ֔א] [וְג֥וֹי] [לֹֽא־יְדָע֖וּךָ] não [יָר֑וּצוּ] a-ti yhwh para-que yhwh teu-Elohim que Israel porque');
INSERT INTO verses VALUES (18816, 23, 55, 6, '[דִּרְשׁ֥וּ] yhwh [בְּהִמָּצְא֑וֹ] [קְרָאֻ֖הוּ] [בִּֽהְיוֹת֥וֹ] [קָרֽוֹב]');
INSERT INTO verses VALUES (18817, 23, 55, 7, '[יַעֲזֹ֤ב] [רָשָׁע֙] [דַּרְכּ֔וֹ] [וְאִ֥ישׁ] [אָ֖וֶן] [מַחְשְׁבֹתָ֑יו] [וְיָשֹׁ֤ב] a yhwh [וְאֶל־אֱלֹהֵ֖ינוּ] e-a nosso-Elohim porque [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18818, 23, 55, 8, 'que não [מַחְשְׁבוֹתַי֙] [מַחְשְׁב֣וֹתֵיכֶ֔ם] e-não [דַרְכֵיכֶ֖ם] [דְּרָכָ֑י] oráculo-de yhwh');
INSERT INTO verses VALUES (18819, 23, 55, 9, 'porque [שָׁמַ֖יִם] céus [כֵּ֣ן] assim [דְרָכַי֙] [מִדַּרְכֵיכֶ֔ם] [וּמַחְשְׁבֹתַ֖י] [מִמַּחְשְׁבֹתֵיכֶֽם]');
INSERT INTO verses VALUES (18820, 23, 55, 10, 'que como [יֵרֵד֩] [הַגֶּ֨שֶׁם] [וְהַשֶּׁ֜לֶג] de os-céus não não que porque se [וְהוֹלִידָ֖הּ] a a-terra semente [לַזֹּרֵ֔עַ] [וְלֶ֖חֶם] [לָאֹכֵֽל]');
INSERT INTO verses VALUES (18821, 23, 55, 11, 'assim será [דְבָרִי֙] que [יֵצֵ֣א] [מִפִּ֔י] não [אֵלַ֖י] a-mim que porque se fez a que [שְׁלַחְתִּֽיו] que');
INSERT INTO verses VALUES (18822, 23, 55, 12, 'porque [תֵצֵ֔אוּ] [וּבְשָׁל֖וֹם] [תּֽוּבָל֑וּן] [הֶהָרִ֣ים] [וְהַגְּבָע֗וֹת] [יִפְצְח֤וּ] [לִפְנֵיכֶם֙] [רִנָּ֔ה] [וְכָל־עֲצֵ֥י] e-todo [יִמְחֲאוּ־כָֽף]');
INSERT INTO verses VALUES (18823, 23, 55, 13, 'debaixo [הַֽנַּעֲצוּץ֙] subia [בְר֔וֹשׁ] [*תחת] [**וְתַ֥חַת] [הַסִּרְפַּ֖ד] subia a-yhwh [וְהָיָ֤ה] [לַֽיהוָה֙] [לְשֵׁ֔ם] não eternidade');
INSERT INTO chapters VALUES (735, 23, 56, 12);
INSERT INTO verses VALUES (18824, 23, 56, 1, 'assim disse yhwh [שִׁמְר֥וּ] juízo [וַעֲשׂ֣וּ] [צְדָקָ֑ה] porque [יְשֽׁוּעָתִי֙] [לָב֔וֹא] [וְצִדְקָתִ֖י] [לְהִגָּלֽוֹת]');
INSERT INTO verses VALUES (18825, 23, 56, 2, '[אַשְׁרֵ֤י] [אֱנוֹשׁ֙] [יַעֲשֶׂה־זֹּ֔את] [וּבֶן־אָדָ֖ם] e-filho-de homem [שֹׁמֵ֤ר] [שַׁבָּת֙] [מֵֽחַלְּל֔וֹ] [וְשֹׁמֵ֥ר] sua-mão [מֵעֲשׂ֥וֹת] [כָּל־רָֽע׃] todo mau');
INSERT INTO verses VALUES (18826, 23, 56, 3, 'e-a dira filho-de [אֶל־יְהוָה֙] dizendo a yhwh yhwh de-cima-de [עַמּ֑וֹ] yhwh de-sobre eis e-a árvore [יָבֵֽשׁ׃] eis eu árvore [sem-traducao]');
INSERT INTO verses VALUES (18827, 23, 56, 4, 'porque assim disse yhwh [לַסָּֽרִיסִים֙] que [יִשְׁמְרוּ֙] a [וּבָֽחֲר֖וּ] [בַּאֲשֶׁ֣ר] [חָפָ֑צְתִּי] [וּמַחֲזִיקִ֖ים] [בִּבְרִיתִֽי] [sem-traducao]');
INSERT INTO verses VALUES (18828, 23, 56, 5, '[וְנָתַתִּ֨י] a-eles [בְּבֵיתִ֤י] [וּבְחֽוֹמֹתַי֙] mão [וָשֵׁ֔ם] bom [מִבָּנִ֣ים] [וּמִבָּנ֑וֹת] nome eternidade [אֶתֶּן־ל֔וֹ] a-ele não não');
INSERT INTO verses VALUES (18829, 23, 56, 6, 'e-filhos-de [הַנֵּכָ֗ר] [הַנִּלְוִ֤ים] sobre yhwh [וּֽלְאַהֲבָה֙] [אֶת־שֵׁ֣ם] yhwh nome a-ele para-ser a-ele [שַׁבָּת֙] todo [וּמַחֲזִיקִ֖ים] [בִּבְרִיתִֽי] sua-mão [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18830, 23, 56, 7, '[וַהֲבִיאוֹתִ֞ים] a [קָדְשִׁ֗י] [וְשִׂמַּחְתִּים֙] [בְּבֵ֣ית] na-casa-de [עוֹלֹתֵיהֶ֧ם] [וְזִבְחֵיהֶ֛ם] [לְרָצ֖וֹן] [עַֽל־מִזְבְּחִ֑י] que [בֵיתִ֔י] porque será-chamada casa-de para-todo');
INSERT INTO verses VALUES (18831, 23, 56, 8, 'oráculo-de Adonai yhwh [מְקַבֵּ֖ץ] [נִדְחֵ֣י] Israel ainda [אֲקַבֵּ֥ץ] sobre-ele [לְנִקְבָּצָֽיו]');
INSERT INTO verses VALUES (18832, 23, 56, 9, 'todo [חַיְת֣וֹ] Shaddai [אֵתָ֕יוּ] [לֶאֱכֹ֥ל] todo [בַּיָּֽעַר׃]');
INSERT INTO verses VALUES (18833, 23, 56, 10, '[*צפו] [**צֹפָ֞יו] não conheceram não [יָדָ֔עוּ] [כֻּלָּם֙] não [אִלְּמִ֔ים] não [יוּכְל֖וּ] [לִנְבֹּ֑חַ] [הֹזִים֙] [שֹֽׁכְבִ֔ים]');
INSERT INTO verses VALUES (18834, 23, 56, 11, '[וְהַכְּלָבִ֣ים] [עַזֵּי־נֶ֗פֶשׁ] não não [שָׂבְעָ֔ה] [וְהֵ֣מָּה] [רֹעִ֔ים] não não conheceram [כֻּלָּם֙] [לְדַרְכָּ֣ם] [פָּנ֔וּ] [אִ֥ישׁ] homem [מִקָּצֵֽהוּ] [sem-traducao]');
INSERT INTO verses VALUES (18835, 23, 56, 12, '[אֵתָ֥יוּ] [אֶקְחָה־יַ֖יִן] vinho [שֵׁכָ֑ר] [וְהָיָ֤ה] e-será dia dia [גָּד֖וֹל] grande muito muito');
INSERT INTO chapters VALUES (736, 23, 57, 21);
INSERT INTO verses VALUES (18836, 23, 57, 1, '[הַצַּדִּ֣יק] [אָבָ֔ד] e-não-há homem nome sobre coração [נֶֽאֱסָפִים֙] [בְּאֵ֣ין] [מֵבִ֔ין] [כִּֽי־מִפְּנֵ֥י] [הָרָעָ֖ה] porque [הַצַּדִּֽיק]');
INSERT INTO verses VALUES (18837, 23, 57, 2, 'vira paz [יָנ֖וּחוּ] sobre [הֹלֵ֖ךְ] andou [sem-traducao]');
INSERT INTO verses VALUES (18838, 23, 57, 3, '[וְאַתֶּ֥ם] [קִרְבוּ־הֵ֖נָּה] [בְּנֵ֣י] filhos-de semente [מְנָאֵ֖ף] [וַתִּזְנֶֽה]');
INSERT INTO verses VALUES (18839, 23, 57, 4, 'sobre quem [עַל־מִ֛י] sobre [פֶ֖ה] [תַּאֲרִ֣יכוּ] [לָשׁ֑וֹן] [הֲלֽוֹא־אַתֶּ֥ם] [יִלְדֵי־פֶ֖שַׁע] semente vós [sem-traducao] [sem-traducao] semente mentira');
INSERT INTO verses VALUES (18840, 23, 57, 5, '[הַנֵּֽחָמִים֙] [בָּֽאֵלִ֔ים] debaixo todo arvore [שֹׁחֲטֵ֤י] [הַיְלָדִים֙] as-criancas debaixo [סְעִפֵ֥י] [הַסְּלָעִֽים] [sem-traducao]');
INSERT INTO verses VALUES (18841, 23, 57, 6, '[בְּחַלְּקֵי־נַ֣חַל] [חֶלְקֵ֔ךְ] eles eles [גּוֹרָלֵ֑ךְ] [גַּם־לָהֶ֞ם] também [נֶ֙סֶךְ֙] [הֶעֱלִ֣ית] [מִנְחָ֔ה] [הַ֥עַל] Estas [אֶנָּחֵֽם]');
INSERT INTO verses VALUES (18842, 23, 57, 7, 'sobre [הַר־גָּבֹ֙הַּ֙] [וְנִשָּׂ֔א] [שַׂ֖מְתְּ] [מִשְׁכָּבֵ֑ךְ] [גַּם־שָׁ֥ם] também nome [זָֽבַח]');
INSERT INTO verses VALUES (18843, 23, 57, 8, '[וְאַחַ֤ר] [הַדֶּ֙לֶת֙] [וְהַמְּזוּזָ֔ה] [שַׂ֖מְתְּ] [זִכְרוֹנֵ֑ךְ] que [מֵאִתִּ֞י] [גִּלִּ֣ית] [וַֽתַּעֲלִ֗י] [הִרְחַ֤בְתְּ] [מִשְׁכָּבֵךְ֙] [וַתִּכְרָת־לָ֣ךְ] a-ti [אָהַ֥בְתְּ] [מִשְׁכָּבָ֖ם] mão mão [sem-traducao]');
INSERT INTO verses VALUES (18844, 23, 57, 9, '[וַתָּשֻׁ֤רִי] [לַמֶּ֙לֶךְ֙] [בַּשֶּׁ֔מֶן] [וַתַּרְבִּ֖י] [רִקֻּחָ֑יִךְ] [וַתְּשַׁלְּחִ֤י] [צִרַ֙יִךְ֙] até [וַתַּשְׁפִּ֖ילִי] [עַד־שְׁאֽוֹל] até');
INSERT INTO verses VALUES (18845, 23, 57, 10, '[בְּרֹ֤ב] [דַּרְכֵּךְ֙] [יָגַ֔עַתְּ] não [אָמַ֖רְתְּ] [נוֹאָ֑שׁ] animal-de [יָדֵךְ֙] [מָצָ֔את] sobre não não');
INSERT INTO verses VALUES (18846, 23, 57, 11, 'e-[OBJ] [דָּאַ֤גְתְּ] [וַתִּֽירְאִי֙] que porque [וְאוֹתִי֙] não não [לֹא־שַׂ֖מְתְּ] não [הֲלֹ֨א] sobre [מַחְשֶׁה֙] [וּמֵ֣עֹלָ֔ם] eu não [תִירָֽאִי] não');
INSERT INTO verses VALUES (18847, 23, 57, 12, 'eu [אַגִּ֖יד] [צִדְקָתֵ֑ךְ] e-[OBJ] [וְלֹ֥א] e-não');
INSERT INTO verses VALUES (18848, 23, 57, 13, '[בְּזַֽעֲקֵךְ֙] [יַצִּילֻ֣ךְ] [קִבּוּצַ֔יִךְ] e-[OBJ] [יִשָּׂא־ר֖וּחַ] [יִקַּח־הָ֑בֶל] espírito [בִי֙] [יִנְחַל־אֶ֔רֶץ] [וְיִירַ֖שׁ] [הַר־קָדְשִֽׁי] terra');
INSERT INTO verses VALUES (18849, 23, 57, 14, 'e-disse [סֹֽלּוּ־סֹ֖לּוּ] [פַּנּוּ־דָ֑רֶךְ] [הָרִ֥ימוּ] caminho [מִדֶּ֥רֶךְ] [עַמִּֽי׃]');
INSERT INTO verses VALUES (18850, 23, 57, 15, 'que assim disse [רָ֣ם] [וְנִשָּׂ֗א] [שֹׁכֵ֥ן] até [וְקָד֣וֹשׁ] seu-nome [מָר֥וֹם] [וְקָד֖וֹשׁ] [אֶשְׁכּ֑וֹן] e-[OBJ] [וּשְׁפַל־ר֔וּחַ] [לְהַחֲיוֹת֙] espírito [שְׁפָלִ֔ים] espírito [לֵ֥ב] [נִדְכָּאִֽים] coração [sem-traducao]');
INSERT INTO verses VALUES (18851, 23, 57, 16, 'que não [לְעוֹלָם֙] [אָרִ֔יב] e-não [לָנֶ֖צַח] [אֶקְּצ֑וֹף] porque espírito [יַֽעֲט֔וֹף] [וּנְשָׁמ֖וֹת] [אֲנִ֥י] eu');
INSERT INTO verses VALUES (18852, 23, 57, 17, '[בַּעֲוֺ֥ן] [בִּצְע֛וֹ] [קָצַ֥פְתִּי] [וְאַכֵּ֖הוּ] [הַסְתֵּ֣ר] [וְאֶקְצֹ֑ף] E-andou [שׁוֹבָ֖ב] [בְּדֶ֥רֶךְ] [לִבּֽוֹ]');
INSERT INTO verses VALUES (18853, 23, 57, 18, '[דְּרָכָ֥יו] vi [וְאֶרְפָּאֵ֑הוּ] [וְאַנְחֵ֕הוּ] [וַאֲשַׁלֵּ֧ם] [נִֽחֻמִ֛ים] a-ele [וְלַאֲבֵלָֽיו]');
INSERT INTO verses VALUES (18854, 23, 57, 19, '[בּוֹרֵ֖א] [*נוב] [**נִ֣יב] [שְׂפָתָ֑יִם] [שָׁל֨וֹם] [׀] disse yhwh [וְלַקָּר֛וֹב]');
INSERT INTO verses VALUES (18855, 23, 57, 20, '[וְהָרְשָׁעִ֖ים] [כַּיָּ֣ם] [נִגְרָ֑שׁ] que [הַשְׁקֵט֙] não [יוּכָ֔ל] [וַיִּגְרְשׁ֥וּ] [מֵימָ֖יו] [רֶ֥פֶשׁ] [וָטִֽיט]');
INSERT INTO verses VALUES (18856, 23, 57, 21, 'não-há paz disse [אֱלֹהַ֖י] [לָרְשָׁעִֽים׃]');
INSERT INTO chapters VALUES (737, 23, 58, 14);
INSERT INTO verses VALUES (18857, 23, 58, 1, 'chamou [בְגָרוֹן֙] a [כַּשּׁוֹפָ֖ר] [הָרֵ֣ם] [קוֹלֶ֑ךָ] [וְהַגֵּ֤ד] [לְעַמִּי֙] [פִּשְׁעָ֔ם] [וּלְבֵ֥ית] [יַעֲקֹ֖ב] Jacó');
INSERT INTO verses VALUES (18858, 23, 58, 2, '[וְאוֹתִ֗י] dia dia [יִדְרֹשׁ֔וּן] [וְדַ֥עַת] [דְּרָכַ֖י] [יֶחְפָּצ֑וּן] [כְּג֞וֹי] que [עָשָׂ֗ה] fez [Elohim] não não [יִשְׁאָל֙וּנִי֙] [מִשְׁפְּטֵי־צֶ֔דֶק] [קִרְבַ֥ת] justica [יֶחְפָּצֽוּן] Elohim');
INSERT INTO verses VALUES (18859, 23, 58, 3, 'por-que [צַּ֙מְנוּ֙] e-não [רָאִ֔יתָ] [עִנִּ֥ינוּ] [נַפְשֵׁ֖נוּ] e-não [תֵדָ֑ע] eis [בְּי֤וֹם] [צֹֽמְכֶם֙] [תִּמְצְאוּ־חֵ֔פֶץ] [וְכָל־עַצְּבֵיכֶ֖ם] e-todo');
INSERT INTO verses VALUES (18860, 23, 58, 4, 'eis [לְרִ֤יב] [וּמַצָּה֙] [תָּצ֔וּמוּ] [וּלְהַכּ֖וֹת] [בְּאֶגְרֹ֣ף] [רֶ֑שַׁע] não [כַיּ֔וֹם] [לְהַשְׁמִ֥יעַ] [בַּמָּר֖וֹם] [קוֹלְכֶֽם]');
INSERT INTO verses VALUES (18861, 23, 58, 5, '[הֲכָזֶ֗ה] será [צ֣וֹם] [אֶבְחָרֵ֔הוּ] dia [עַנּ֥וֹת] homem sua-alma [הֲלָכֹ֨ף] [כְּאַגְמֹ֜ן] [רֹאשׁ֗וֹ] [וְשַׂ֤ק] [וָאֵ֙פֶר֙] [יַצִּ֔יעַ] [הֲלָזֶה֙] [תִּקְרָא־צ֔וֹם] [וְי֥וֹם] [רָצ֖וֹן] [לַיהוָֽה]');
INSERT INTO verses VALUES (18862, 23, 58, 6, 'porventura-não [זֶה֮] [צ֣וֹם] [אֶבְחָרֵהוּ֒] [פַּתֵּ֙חַ֙] [חַרְצֻבּ֣וֹת] [רֶ֔שַׁע] [הַתֵּ֖ר] [אֲגֻדּ֣וֹת] [מוֹטָ֑ה] [וְשַׁלַּ֤ח] [רְצוּצִים֙] [חָפְשִׁ֔ים] e-todo [תְּנַתֵּֽקוּ]');
INSERT INTO verses VALUES (18863, 23, 58, 7, 'porventura-não [פָרֹ֤ס] [לָֽרָעֵב֙] [לַחְמֶ֔ךָ] [וַעֲנִיִּ֥ים] [מְרוּדִ֖ים] [תָּ֣בִיא] casa porque [עָרֹם֙] [וְכִסִּית֔וֹ] [וּמִבְּשָׂרְךָ֖] não não');
INSERT INTO verses VALUES (18864, 23, 58, 8, 'entao [יִבָּקַ֤ע] [כַּשַּׁ֙חַר֙] [אוֹרֶ֔ךָ] [וַאֲרֻכָתְךָ֖] [מְהֵרָ֣ה] [תִצְמָ֑ח] [וְהָלַ֤ךְ] diante-de-ti [צִדְקֶ֔ךָ] [כְּב֥וֹד] yhwh [יַאַסְפֶֽךָ]');
INSERT INTO verses VALUES (18865, 23, 58, 9, '[אָ֤ז] [תִּקְרָא֙] [וַיהוָ֣ה] [יַעֲנֶ֔ה] [תְּשַׁוַּ֖ע] E-disse [הִנֵּ֑נִי] se [מִתּֽוֹכְךָ֙] [מוֹטָ֔ה] [שְׁלַ֥ח] enviou [וְדַבֶּר־אָֽוֶן]');
INSERT INTO verses VALUES (18866, 23, 58, 10, '[וְתָפֵ֤ק] [לָֽרָעֵב֙] [נַפְשֶׁ֔ךָ] [וְנֶ֥פֶשׁ] [נַעֲנָ֖ה] [תַּשְׂבִּ֑יעַ] [וְזָרַ֤ח] [בַּחֹ֙שֶׁךְ֙] [אוֹרֶ֔ךָ] [וַאֲפֵלָתְךָ֖] [כַּֽצָּהֳרָֽיִם]');
INSERT INTO verses VALUES (18867, 23, 58, 11, '[וְנָחֲךָ֣] yhwh [תָּמִיד֒] [וְהִשְׂבִּ֤יעַ] [בְּצַחְצָחוֹת֙] [נַפְשֶׁ֔ךָ] [וְעַצְמֹתֶ֖יךָ] [יַחֲלִ֑יץ] [וְהָיִ֙יתָ֙] [כְּגַ֣ן] [רָוֶ֔ה] [וּכְמוֹצָ֣א] águas que não [מֵימָֽיו]');
INSERT INTO verses VALUES (18868, 23, 58, 12, '[וּבָנ֤וּ] [מִמְּךָ֙] [חָרְב֣וֹת] eternidade [מוֹסְדֵ֥י] [דוֹר־וָד֖וֹר] [תְּקוֹמֵ֑ם] [וְקֹרָ֤א] a-ti a-ti [פֶּ֔רֶץ] [מְשֹׁבֵ֥ב] [נְתִיב֖וֹת] [לָשָֽׁבֶת] [sem-traducao]');
INSERT INTO verses VALUES (18869, 23, 58, 13, 'se [מִשַּׁבָּת֙] [רַגְלֶ֔ךָ] [עֲשׂ֥וֹת] [חֲפָצֶ֖יךָ] [בְּי֣וֹם] no-dia [וְקָרָ֨אתָ] [לַשַּׁבָּ֜ת] [עֹ֗נֶג] [לִקְד֤וֹשׁ] yhwh yhwh [וְכִבַּדְתּוֹ֙] [מֵעֲשׂ֣וֹת] [דְּרָכֶ֔יךָ] [מִמְּצ֥וֹא] [חֶפְצְךָ֖] [וְדַבֵּ֥ר] [דָּבָֽר] palavra');
INSERT INTO verses VALUES (18870, 23, 58, 14, '[אָ֗ז] [תִּתְעַנַּג֙] sobre yhwh [עַל־בָּ֣מֳותֵי] sobre [וְהַאֲכַלְתִּ֗יךָ] terra [יַעֲקֹ֣ב] [אָבִ֔יךָ] que [פִּ֥י] yhwh [דִּבֵּֽר׃] yhwh palavra');
INSERT INTO chapters VALUES (738, 23, 59, 21);
INSERT INTO verses VALUES (18871, 23, 59, 1, 'eis não [יַד־יְהוָ֖ה] mão-de yhwh [אָזְנ֖וֹ] e-não');
INSERT INTO verses VALUES (18872, 23, 59, 2, 'que se [הָי֣וּ] eram [בֵּינֵכֶ֕ם] [לְבֵ֖ין] [אֱלֹֽהֵיכֶ֑ם] [וְחַטֹּֽאותֵיכֶ֗ם] [הִסְתִּ֧ירוּ] [פָנִ֛ים] face [מִשְּׁמֽוֹעַ]');
INSERT INTO verses VALUES (18873, 23, 59, 3, 'que [כַפֵּיכֶם֙] [נְגֹאֲל֣וּ] [בַדָּ֔ם] [וְאֶצְבְּעוֹתֵיכֶ֖ם] [בֶּֽעָוֺ֑ן] [שִׂפְתֽוֹתֵיכֶם֙] [דִּבְּרוּ־שֶׁ֔קֶר] mentira [עַוְלָ֥ה] [תֶהְגֶּֽה]');
INSERT INTO verses VALUES (18874, 23, 59, 4, 'não-há chamou [וְאֵ֥ין] e-não-há [בֶּאֱמוּנָ֑ה] [בָּט֤וֹחַ] [עַל־תֹּ֙הוּ֙] sobre sem-forma [עָמָ֖ל] [וְהוֹלֵ֥יד] [אָֽוֶן]');
INSERT INTO verses VALUES (18875, 23, 59, 5, '[בֵּיצֵ֤י] [צִפְעוֹנִי֙] [בִּקֵּ֔עוּ] [וְקוּרֵ֥י] [עַכָּבִ֖ישׁ] [יֶאֱרֹ֑גוּ] [הָאֹכֵ֤ל] [מִבֵּֽיצֵיהֶם֙] [יָמ֔וּת] [וְהַזּוּרֶ֖ה] [תִּבָּקַ֥ע] [אֶפְעֶֽה]');
INSERT INTO verses VALUES (18876, 23, 59, 6, '[קֽוּרֵיהֶם֙] não serão [וְלֹ֥א] e-não [בְּמַֽעֲשֵׂיהֶ֑ם] [מַֽעֲשֵׂיהֶם֙] [מַֽעֲשֵׂי־אָ֔וֶן] [וּפֹ֥עַל] iniquidade [בְּכַפֵּיהֶֽם] violência [sem-traducao]');
INSERT INTO verses VALUES (18877, 23, 59, 7, '[רַגְלֵיהֶם֙] [לָרַ֣ע] [יָרֻ֔צוּ] [וִֽימַהֲר֔וּ] [לִשְׁפֹּ֖ךְ] [דָּ֣ם] [נָקִ֑י] [מַחְשְׁבֽוֹתֵיהֶם֙] [מַחְשְׁב֣וֹת] iniquidade [שֹׁ֥ד] [וָשֶׁ֖בֶר] [בִּמְסִלּוֹתָֽם]');
INSERT INTO verses VALUES (18878, 23, 59, 8, 'o-caminho-de [שָׁלוֹם֙] não conheceram e-não-há juízo [בְּמַעְגְּלוֹתָ֑ם] [נְתִיבֽוֹתֵיהֶם֙] [עִקְּשׁ֣וּ] a-eles todo caminho [בָּ֔הּ] não saber [שָׁלֽוֹם]');
INSERT INTO verses VALUES (18879, 23, 59, 9, 'sobre assim [מִשְׁפָּט֙] nós [וְלֹ֥א] e-não [צְדָקָ֑ה] [נְקַוֶּ֤ה] à-luz [וְהִנֵּה־חֹ֔שֶׁךְ] e-eis escuridão [נְהַלֵּֽךְ]');
INSERT INTO verses VALUES (18880, 23, 59, 10, '[נְגַֽשְׁשָׁ֤ה] [כַֽעִוְרִים֙] [קִ֔יר] [וּכְאֵ֥ין] [עֵינַ֖יִם] [נְגַשֵּׁ֑שָׁה] [כָּשַׁ֤לְנוּ] [בַֽצָּהֳרַ֙יִם֙] [כַּנֶּ֔שֶׁף] [בָּאַשְׁמַנִּ֖ים] [כַּמֵּתִֽים]');
INSERT INTO verses VALUES (18881, 23, 59, 11, '[נֶהֱמֶ֤ה] [כַדֻּבִּים֙] [כֻּלָּ֔נוּ] [וְכַיּוֹנִ֖ים] [הָגֹ֣ה] [נֶהְגֶּ֑ה] [נְקַוֶּ֤ה] [לַמִּשְׁפָּט֙] [וָאַ֔יִן] [לִֽישׁוּעָ֖ה] [רָחֲקָ֥ה] nós');
INSERT INTO verses VALUES (18882, 23, 59, 12, 'porque [פְשָׁעֵ֙ינוּ֙] [נֶגְדֶּ֔ךָ] [וְחַטֹּאותֵ֖ינוּ] [עָ֣נְתָה] [בָּ֑נוּ] [כִּֽי־פְשָׁעֵ֣ינוּ] porque [וַעֲוֺנֹתֵ֖ינוּ] [יְדַֽעֲנֽוּם]');
INSERT INTO verses VALUES (18883, 23, 59, 13, '[פָּשֹׁ֤עַ] [וְכַחֵשׁ֙] [בַּֽיהוָ֔ה] [וְנָס֖וֹג] [מֵאַחַ֣ר] nosso-Elohim [דַּבֶּר־עֹ֣שֶׁק] [וְסָרָ֔ה] [הֹר֧וֹ] [וְהֹג֛וֹ] [מִלֵּ֖ב] [דִּבְרֵי־שָֽׁקֶר]');
INSERT INTO verses VALUES (18884, 23, 59, 14, '[וְהֻסַּ֤ג] [אָחוֹר֙] [מִשְׁפָּ֔ט] e-justica [מֵרָח֣וֹק] [תַּעֲמֹ֑ד] porque [בָֽרְחוֹב֙] [אֱמֶ֔ת] [וּנְכֹחָ֖ה] [לֹא־תוּכַ֥ל] não [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18885, 23, 59, 15, '[וַתְּהִ֤י] [הָֽאֱמֶת֙] [נֶעְדֶּ֔רֶת] [וְסָ֥ר] [מֵרָ֖ע] [מִשְׁתּוֹלֵ֑ל] E-viu yhwh [וַיֵּ֥רַע] [בְּעֵינָ֖יו] porque não-há');
INSERT INTO verses VALUES (18886, 23, 59, 16, 'E-viu porque não-há homem que porque não-há [וַתּ֤וֹשַֽׁע] a-ele a-ele [וְצִדְקָת֖וֹ] [הִ֥יא] [סְמָכָֽתְהוּ]');
INSERT INTO verses VALUES (18887, 23, 59, 17, '[וַיִּלְבַּ֤שׁ] [צְדָקָה֙] [כַּשִּׁרְיָ֔ן] [וְכ֥וֹבַע] [יְשׁוּעָ֖ה] [בְּרֹאשׁ֑וֹ] [וַיִּלְבַּ֞שׁ] [בִּגְדֵ֤י] [נָקָם֙] [תִּלְבֹּ֔שֶׁת] [וַיַּ֥עַט] [כַּמְעִ֖יל] [קִנְאָֽה]');
INSERT INTO verses VALUES (18888, 23, 59, 18, '[כְּעַ֤ל] [גְּמֻלוֹת֙] [כְּעַ֣ל] [יְשַׁלֵּ֔ם] [חֵמָ֣ה] [לְצָרָ֔יו] [גְּמ֖וּל] [לְאֹֽיְבָ֑יו] [לָאִיִּ֖ים] [גְּמ֥וּל] [יְשַׁלֵּֽם]');
INSERT INTO verses VALUES (18889, 23, 59, 19, '[וְיִֽירְא֤וּ] [מִֽמַּעֲרָב֙] a yhwh yhwh [אֶת־כְּבוֹד֑וֹ] [כִּֽי־יָב֤וֹא] a [צָ֔ר] espírito yhwh [נֹ֥סְסָה] nele espírito yhwh');
INSERT INTO verses VALUES (18890, 23, 59, 20, '[וּבָ֤א] [לְצִיּוֹן֙] [גּוֹאֵ֔ל] [וּלְשָׁבֵ֥י] [פֶ֖שַׁע] [בְּיַֽעֲקֹ֑ב] oráculo-de yhwh');
INSERT INTO verses VALUES (18891, 23, 59, 21, 'e-eu esta [בְּרִיתִ֤י] a-eles disse yhwh [רוּחִי֙] que sobre-ti [וּדְבָרַ֖י] que [בְּפִ֑יךָ] [לֹֽא־יָמ֡וּשׁוּ] não [וּמִפִּ֨י] tua-semente [וּמִפִּ֨י] semente tua-semente disse yhwh disse yhwh [sem-traducao] e-até eternidade');
INSERT INTO chapters VALUES (739, 23, 60, 22);
INSERT INTO verses VALUES (18892, 23, 60, 1, '[ק֥וּמִי] [א֖וֹרִי] que veio [אוֹרֵ֑ךְ] [וּכְב֥וֹד] yhwh [עָלַ֥יִךְ] [זָרָֽח]');
INSERT INTO verses VALUES (18893, 23, 60, 2, 'porque [הַחֹ֙שֶׁךְ֙] [יְכַסֶּה־אֶ֔רֶץ] [וַעֲרָפֶ֖ל] terra [וְעָלַ֙יִךְ֙] [יִזְרַ֣ח] yhwh [וּכְבוֹד֖וֹ] yhwh [יֵרָאֶֽה]');
INSERT INTO verses VALUES (18894, 23, 60, 3, '[וְהָלְכ֥וּ] [גוֹיִ֖ם] [לְאוֹרֵ֑ךְ] [וּמְלָכִ֖ים] [לְנֹ֥גַהּ] [זַרְחֵֽךְ]');
INSERT INTO verses VALUES (18895, 23, 60, 4, '[שְׂאִֽי־סָבִ֤יב] [עֵינַ֙יִךְ֙] [וּרְאִ֔י] [כֻּלָּ֖ם] [נִקְבְּצ֣וּ] [בָֽאוּ־לָ֑ךְ] [בָּנַ֙יִךְ֙] a-ti [יָבֹ֔אוּ] [וּבְנֹתַ֖יִךְ] [עַל־צַ֥ד] [תֵּאָמַֽנָה] sobre');
INSERT INTO verses VALUES (18896, 23, 60, 5, '[אָ֤ז] [תִּרְאִי֙] [וְנָהַ֔רְתְּ] [וּפָחַ֥ד] [וְרָחַ֖ב] [לְבָבֵ֑ךְ] porque [עָלַ֙יִךְ֙] sobre-ti mar mar [גּוֹיִ֖ם] nações para-ti para-ti');
INSERT INTO verses VALUES (18897, 23, 60, 6, '[שִֽׁפְעַ֨ת] [גְּמַלִּ֜ים] [תְּכַסֵּ֗ךְ] [בִּכְרֵ֤י] [מִדְיָן֙] [וְעֵיפָ֔ה] [כֻּלָּ֖ם] [מִשְּׁבָ֣א] [יָבֹ֑אוּ] ouro [וּלְבוֹנָה֙] [יִשָּׂ֔אוּ] [וּתְהִלֹּ֥ת] yhwh [יְבַשֵּֽׂרוּ]');
INSERT INTO verses VALUES (18898, 23, 60, 7, 'todo [קֵדָר֙] [יִקָּ֣בְצוּ] para-ti para-ti [נְבָי֖וֹת] [יְשָׁרְת֑וּנֶךְ] [יַעֲל֤וּ] [עַל־רָצוֹן֙] sobre [וּבֵ֥ית] [תִּפְאַרְתִּ֖י] [אֲפָאֵֽר]');
INSERT INTO verses VALUES (18899, 23, 60, 8, '[מִי־אֵ֖לֶּה] [כָּעָ֣ב] [תְּעוּפֶ֑ינָה] [וְכַיּוֹנִ֖ים] [אֶל־אֲרֻבֹּתֵיהֶֽם] a');
INSERT INTO verses VALUES (18900, 23, 60, 9, 'porque [׀] [אִיִּ֣ים] [יְקַוּ֗וּ] [וָאֳנִיּ֤וֹת] [תַּרְשִׁישׁ֙] [בָּרִ֣אשֹׁנָ֔ה] [לְהָבִ֤יא] [בָנַ֙יִךְ֙] [מֵֽרָח֔וֹק] [כַּסְפָּ֥ם] [וּזְהָבָ֖ם] [אִתָּ֑ם] [לְשֵׁם֙] yhwh [אֱלֹהַ֔יִךְ] [וְלִקְד֥וֹשׁ] Israel que [פֵאֲרָֽךְ]');
INSERT INTO verses VALUES (18901, 23, 60, 10, '[וּבָנ֤וּ] filhos-de [חֹמֹתַ֔יִךְ] [וּמַלְכֵיהֶ֖ם] [יְשָׁרְת֑וּנֶךְ] que porque [הִכִּיתִ֔יךְ] [וּבִרְצוֹנִ֖י] [רִֽחַמְתִּֽיךְ]');
INSERT INTO verses VALUES (18902, 23, 60, 11, '[וּפִתְּח֨וּ] [שְׁעָרַ֧יִךְ] [תָּמִ֛יד] [יוֹמָ֥ם] [וָלַ֖יְלָה] não [יִסָּגֵ֑רוּ] [לְהָבִ֤יא] [אֵלַ֙יִךְ֙] força nações [וּמַלְכֵיהֶ֖ם] [נְהוּגִֽים]');
INSERT INTO verses VALUES (18903, 23, 60, 12, 'porque [וְהַמַּמְלָכָ֛ה] [אֲשֶׁ֥ר] que não [וְהַגּוֹיִ֖ם] perecerao [יֶחֱרָֽבוּ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18904, 23, 60, 13, '[כְּב֤וֹד] [הַלְּבָנוֹן֙] [אֵלַ֣יִךְ] vira [בְּר֛וֹשׁ] [תִּדְהָ֥ר] [וּתְאַשּׁ֖וּר] juntos [לְפָאֵר֙] lugar [מִקְדָּשִׁ֔י] [וּמְק֥וֹם] [רַגְלַ֖י] [אֲכַבֵּֽד]');
INSERT INTO verses VALUES (18905, 23, 60, 14, '[וְהָלְכ֨וּ] [אֵלַ֤יִךְ] [שְׁח֙וֹחַ֙] filhos-de [מְעַנַּ֔יִךְ] [וְהִֽשְׁתַּחֲו֛וּ] sobre [רַגְלַ֖יִךְ] [כָּל־מְנַֽאֲצָ֑יִךְ] todo para-ti [עִ֣יר] yhwh cidade yhwh Sião santo Israel');
INSERT INTO verses VALUES (18906, 23, 60, 15, 'debaixo [הֱיוֹתֵ֛ךְ] [עֲזוּבָ֥ה] [וּשְׂנוּאָ֖ה] e-não-há [עוֹבֵ֑ר] [וְשַׂמְתִּיךְ֙] [לִגְא֣וֹן] eternidade [מְשׂ֖וֹשׂ] [דּ֥וֹר] [וָדֽוֹר]');
INSERT INTO verses VALUES (18907, 23, 60, 16, '[וְיָנַקְתְּ֙] [חֲלֵ֣ב] nações [וְשֹׁ֥ד] [מְלָכִ֖ים] [תִּינָ֑קִי] [וְיָדַ֗עַתְּ] que eu yhwh [מֽוֹשִׁיעֵ֔ךְ] [וְגֹאֲלֵ֖ךְ] [אֲבִ֥יר] Jacó');
INSERT INTO verses VALUES (18908, 23, 60, 17, 'debaixo [הַנְּחֹ֜שֶׁת] trarei ouro [וְתַ֤חַת] [הַבַּרְזֶל֙] [אָ֣בִיא] [כֶ֔סֶף] [וְתַ֤חַת] [הָֽעֵצִים֙] [נְחֹ֔שֶׁת] [וְתַ֥חַת] [הָאֲבָנִ֖ים] [בַּרְזֶ֑ל] [וְשַׂמְתִּ֤י] [פְקֻדָּתֵךְ֙] paz [וְנֹגְשַׂ֖יִךְ] [צְדָקָֽה]');
INSERT INTO verses VALUES (18909, 23, 60, 18, 'não [ע֤וֹד] ainda [בְּאַרְצֵ֔ךְ] [שֹׁ֥ד] [וָשֶׁ֖בֶר] [בִּגְבוּלָ֑יִךְ] [וְקָרָ֤את] [יְשׁוּעָה֙] [חוֹמֹתַ֔יִךְ] [וּשְׁעָרַ֖יִךְ] [תְּהִלָּֽה] [sem-traducao]');
INSERT INTO verses VALUES (18910, 23, 60, 19, 'não sera [הַשֶּׁ֙מֶשׁ֙] ainda [יוֹמָ֔ם] para-luz [הַיָּרֵ֖חַ] [לֹא־יָאִ֣יר] para-ti não yhwh a-ti eternidade [וֵאלֹהַ֖יִךְ] yhwh para-luz eternidade e-Elohim-teu [sem-traducao]');
INSERT INTO verses VALUES (18911, 23, 60, 20, 'não virá ainda [וִירֵחֵ֖ךְ] não não que yhwh yhwh sera eternidade para-luz dias-de [אֶבְלֵֽךְ] dias-de [sem-traducao]');
INSERT INTO verses VALUES (18912, 23, 60, 21, '[וְעַמֵּךְ֙] [כֻּלָּ֣ם] [צַדִּיקִ֔ים] para-sempre [יִ֣ירְשׁוּ] terra [נֵ֧צֶר] [*מטעו] [**מַטָּעַ֛י] [מַעֲשֵׂ֥ה]');
INSERT INTO verses VALUES (18913, 23, 60, 22, 'o-pequeno será [לָאֶ֔לֶף] [וְהַצָּעִ֖יר] [לְג֣וֹי] [עָצ֑וּם] eu yhwh [בְּעִתָּ֥הּ] [אֲחִישֶֽׁנָּה׃]');
INSERT INTO chapters VALUES (740, 23, 61, 11);
INSERT INTO verses VALUES (18914, 23, 61, 1, 'espírito Adonai yhwh [עָלָ֑י] [יַ֡עַן] [מָשַׁח֩] yhwh [אֹתִ֜י] [לְבַשֵּׂ֣ר] [עֲנָוִ֗ים] [שְׁלָחַ֙נִי֙] [לַחֲבֹ֣שׁ] [לְנִשְׁבְּרֵי־לֵ֔ב] coração [לִשְׁבוּיִם֙] [דְּר֔וֹר] [וְלַאֲסוּרִ֖ים] [פְּקַח־קֽוֹחַ]');
INSERT INTO verses VALUES (18915, 23, 61, 2, '[לִקְרֹ֤א] [שְׁנַת־רָצוֹן֙] [לַֽיהוָ֔ה] a-yhwh [נָקָ֖ם] vinganca [לְנַחֵ֖ם] [כָּל־אֲבֵלִֽים] todo [sem-traducao]');
INSERT INTO verses VALUES (18916, 23, 61, 3, '[לָשׂ֣וּם] [׀] Siao [צִיּ֗וֹן] [לָתֵת֩] a-eles debaixo-de debaixo [אֵ֗פֶר] [שֶׁ֤מֶן] debaixo-de debaixo [אֵ֔בֶל] [מַעֲטֵ֣ה] [תְהִלָּ֔ה] debaixo espírito [כֵּהָ֑ה] a-eles a-eles [אֵילֵ֣י] [הַצֶּ֔דֶק] yhwh yhwh');
INSERT INTO verses VALUES (18917, 23, 61, 4, '[וּבָנוּ֙] [חָרְב֣וֹת] eternidade [שֹׁמְמ֥וֹת] [רִֽאשֹׁנִ֖ים] [יְקוֹמֵ֑מוּ] [וְחִדְּשׁוּ֙] [עָ֣רֵי] [חֹ֔רֶב] [שֹׁמְמ֖וֹת] [דּ֥וֹר] [וָדֽוֹר]');
INSERT INTO verses VALUES (18918, 23, 61, 5, '[וְעָמְד֣וּ] [זָרִ֔ים] [וְרָע֖וּ] [צֹאנְכֶ֑ם] e-filhos-de [נֵכָ֔ר] [אִכָּרֵיכֶ֖ם] [וְכֹרְמֵיכֶֽם]');
INSERT INTO verses VALUES (18919, 23, 61, 6, '[וְאַתֶּ֗ם] [כֹּהֲנֵ֤י] yhwh [תִּקָּרֵ֔אוּ] [מְשָׁרְתֵ֣י] nosso-Elohim [יֵאָמֵ֖ר] a-vós [חֵ֤יל] nações [תֹּאכֵ֔לוּ] [וּבִכְבוֹדָ֖ם] [תִּתְיַמָּֽרוּ]');
INSERT INTO verses VALUES (18920, 23, 61, 7, 'debaixo [בָּשְׁתְּכֶם֙] [מִשְׁנֶ֔ה] [וּכְלִמָּ֖ה] [יָרֹ֣נּוּ] [חֶלְקָ֑ם] [לָכֵ֤ן] [בְּאַרְצָם֙] [מִשְׁנֶ֣ה] [יִירָ֔שׁוּ] [שִׂמְחַ֥ת] eternidade será a-eles');
INSERT INTO verses VALUES (18921, 23, 61, 8, 'que eu yhwh amou [מִשְׁפָּ֔ט] odiou [גָזֵ֖ל] [בְּעוֹלָ֑ה] e-darei [פְעֻלָּתָם֙] [בֶּאֱמֶ֔ת] [וּבְרִ֥ית] eternidade [אֶכְר֥וֹת] a-eles');
INSERT INTO verses VALUES (18922, 23, 61, 9, '[וְנוֹדַ֤ע] [בַּגּוֹיִם֙] [זַרְעָ֔ם] [וְצֶאֱצָאֵיהֶ֖ם] no-meio-de [הָעַמִּ֑ים] todo [יַכִּיר֔וּם] que eles semente [בֵּרַ֥ךְ] yhwh yhwh');
INSERT INTO verses VALUES (18923, 23, 61, 10, '[שׂ֧וֹשׂ] [אָשִׂ֣ישׂ] [בַּֽיהוָ֗ה] [תָּגֵ֤ל] [נַפְשִׁי֙] [בֵּֽאלֹהַ֔י] que [הִלְבִּישַׁ֙נִי֙] [בִּגְדֵי־יֶ֔שַׁע] [מְעִ֥יל] [צְדָקָ֖ה] [יְעָטָ֑נִי] [כֶּֽחָתָן֙] [יְכַהֵ֣ן] [פְּאֵ֔ר] [וְכַכַּלָּ֖ה] [תַּעְדֶּ֥ה] [כֵלֶֽיהָ]');
INSERT INTO verses VALUES (18924, 23, 61, 11, 'que [כָאָ֙רֶץ֙] [תּוֹצִ֣יא] [צִמְחָ֔הּ] [וּכְגַנָּ֖ה] [זֵרוּעֶ֣יהָ] [תַצְמִ֑יחַ] [כֵּ֣ן] Adonai yhwh [יְהוִ֗ה] [יַצְמִ֤יחַ] [צְדָקָה֙] [וּתְהִלָּ֔ה] diante [כָּל־הַגּוֹיִֽם]');
INSERT INTO chapters VALUES (741, 23, 62, 12);
INSERT INTO verses VALUES (18925, 23, 62, 1, '[לְמַ֤עַן] Siao não [אֶחֱשֶׁ֔ה] [וּלְמַ֥עַן] Jerusalém não [אֶשְׁק֑וֹט] até [כַנֹּ֙גַהּ֙] [צִדְקָ֔הּ] [וִישׁוּעָתָ֖הּ] [כְּלַפִּ֥יד] [יִבְעָֽר] [sem-traducao]');
INSERT INTO verses VALUES (18926, 23, 62, 2, '[וְרָא֤וּ] nações [צִדְקֵ֔ךְ] e-todo [כְּבוֹדֵ֑ךְ] [וְקֹ֤רָא] para-ti [שֵׁ֣ם] nome novo que yhwh yhwh [sem-traducao]');
INSERT INTO verses VALUES (18927, 23, 62, 3, '[וְהָיִ֛יתְ] [עֲטֶ֥רֶת] [תִּפְאֶ֖רֶת] pela-mão-de yhwh [**וּצְנִ֥יף] [מְלוּכָ֖ה] [בְּכַף־אֱלֹהָֽיִךְ]');
INSERT INTO verses VALUES (18928, 23, 62, 4, 'não para-ti [ע֜וֹד] ainda [וּלְאַרְצֵךְ֙] [לֹא־יֵאָמֵ֥ר] não [שְׁמָמָ֔ה] que para-ti será-chamada [חֶפְצִי־בָ֔הּ] [וּלְאַרְצֵ֖ךְ] [בְּעוּלָ֑ה] [כִּֽי־חָפֵ֤ץ] yhwh sobre-ti porque [תִּבָּעֵֽל] yhwh de-cima-de [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18929, 23, 62, 5, 'porque [בָּחוּר֙] [בְּתוּלָ֔ה] [יִבְעָל֖וּךְ] [בָּנָ֑יִךְ] [וּמְשׂ֤וֹשׂ] [חָתָן֙] [עַל־כַּלָּ֔ה] sobre [עָלַ֖יִךְ] [אֱלֹהָֽיִךְ]');
INSERT INTO verses VALUES (18930, 23, 62, 6, 'sobre [יְרוּשָׁלִַ֗ם] Jerusalém [שֹֽׁמְרִ֔ים] [כָּל־הַיּ֧וֹם] todo [תָּמִ֖יד] não [יֶחֱשׁ֑וּ] [הַמַּזְכִּרִים֙] não [אַל־דֳּמִ֖י] a-vós a yhwh a');
INSERT INTO verses VALUES (18931, 23, 62, 7, 'e-a [דֳמִ֖י] a-ele a-ele até [אֶת־יְרֽוּשָׁלַ֛͏ִם] e-até [בָּאָֽרֶץ] a');
INSERT INTO verses VALUES (18932, 23, 62, 8, '[נִשְׁבַּ֧ע] yhwh [בִּֽימִינ֖וֹ] [וּבִזְר֣וֹעַ] [עֻזּ֑וֹ] se [אֶת־דְּגָנֵ֨ךְ] a alimento ainda [וְאִם־יִשְׁתּ֤וּ] [בְנֵֽי־נֵכָר֙] e-se [אֲשֶׁ֥ר] filhos-de [בּֽוֹ] [sem-traducao] que [sem-traducao] em-ele');
INSERT INTO verses VALUES (18933, 23, 62, 9, 'que [מְאַסְפָיו֙] [יֹאכְלֻ֔הוּ] [וְהִֽלְל֖וּ] a yhwh [יִשְׁתֻּ֖הוּ] [בְּחַצְר֥וֹת] [קָדְשִֽׁי׃]');
INSERT INTO verses VALUES (18934, 23, 62, 10, '[עִבְר֤וּ] [עִבְרוּ֙] [בַּשְּׁעָרִ֔ים] [פַּנּ֖וּ] o-caminho-de o-povo [סֹ֣לּוּ] [סֹ֤לּוּ] [הַֽמְסִלָּה֙] [סַקְּל֣וּ] [מֵאֶ֔בֶן] [הָרִ֥ימוּ] [נֵ֖ס] sobre');
INSERT INTO verses VALUES (18935, 23, 62, 11, 'eis yhwh [הִשְׁמִ֙יעַ֙] a a-terra a-terra [לְבַת־צִיּ֔וֹן] eis Sião eis eis veio [אִתּ֔וֹ] [וּפְעֻלָּת֖וֹ] com-ele');
INSERT INTO verses VALUES (18936, 23, 62, 12, '[וְקָרְא֥וּ] a-eles com [גְּאוּלֵ֣י] yhwh yhwh será-chamada [דְרוּשָׁ֔ה] [עִ֖יר] não não');
INSERT INTO chapters VALUES (742, 23, 63, 19);
INSERT INTO verses VALUES (18937, 23, 63, 1, '[מִי־זֶ֣ה] [׀] veio [מֵאֱד֗וֹם] [חֲמ֤וּץ] [בְּגָדִים֙] [מִבָּצְרָ֔ה] este [הָד֣וּר] [בִּלְבוּשׁ֔וֹ] [צֹעֶ֖ה] em-multidão [כֹּח֑וֹ] eu [מְדַבֵּ֥ר] [בִּצְדָקָ֖ה] muito [לְהוֹשִֽׁיעַ]');
INSERT INTO verses VALUES (18938, 23, 63, 2, '[מַדּ֥וּעַ] homem [לִלְבוּשֶׁ֑ךָ] [וּבְגָדֶ֖יךָ] [כְּדֹרֵ֥ךְ] [בְּגַֽת]');
INSERT INTO verses VALUES (18939, 23, 63, 3, '[פּוּרָ֣ה] [׀] [דָּרַ֣כְתִּי] [לְבַדִּ֗י] não-há homem [אִתִּ֔י] [וְאֶדְרְכֵ֣ם] [בְּאַפִּ֔י] [וְאֶרְמְסֵ֖ם] [בַּחֲמָתִ֑י] [וְיֵ֤ז] [נִצְחָם֙] sobre [וְכָל־מַלְבּוּשַׁ֖י] e-todo');
INSERT INTO verses VALUES (18940, 23, 63, 4, 'que dia vinganca [בְּלִבִּ֑י] [וּשְׁנַ֥ת] [גְּאוּלַ֖י] [בָּֽאָה]');
INSERT INTO verses VALUES (18941, 23, 63, 5, '[וְאַבִּיט֙] e-não-há [עֹזֵ֔ר] [וְאֶשְׁתּוֹמֵ֖ם] e-não-há [סוֹמֵ֑ךְ] [וַתּ֤וֹשַֽׁע] para-mim [זְרֹעִ֔י] [וַחֲמָתִ֖י] [הִ֥יא] [סְמָכָֽתְנִי]');
INSERT INTO verses VALUES (18942, 23, 63, 6, '[וְאָב֤וּס] [עַמִּים֙] [בְּאַפִּ֔י] [וַאֲשַׁכְּרֵ֖ם] [בַּחֲמָתִ֑י] [וְאוֹרִ֥יד] [לָאָ֖רֶץ] [נִצְחָֽם׃]');
INSERT INTO verses VALUES (18943, 23, 63, 7, '[חַֽסְדֵ֨י] yhwh [׀] [אַזְכִּיר֙] yhwh yhwh todo que [אֲשֶׁר־גְּמָלָ֖נוּ] yhwh e-grande bom para-casa-de Israel que [וּכְרֹ֥ב] [חֲסָדָֽיו] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18944, 23, 63, 8, 'E-disse somente meu-povo [בָּנִ֖ים] não não e-houve a-eles a-eles');
INSERT INTO verses VALUES (18945, 23, 63, 9, 'em-todo [׀] [*לא] [**ל֣וֹ] [צָ֗ר] [וּמַלְאַ֤ךְ] [פָּנָיו֙] [הֽוֹשִׁיעָ֔ם] ele [וּבְחֶמְלָת֖וֹ] ele [גְאָלָ֑ם] todo dias-de eternidade');
INSERT INTO verses VALUES (18946, 23, 63, 10, '[וְהֵ֛מָּה] [מָר֥וּ] [וְעִצְּב֖וּ] a espírito sua-santidade a-eles a-eles ele ele [sem-traducao] em-eles');
INSERT INTO verses VALUES (18947, 23, 63, 11, '[וַיִּזְכֹּ֥ר] [יְמֵֽי־עוֹלָ֖ם] [מֹשֶׁ֣ה] Moisés [אַיֵּ֣ה] [׀] [הַֽמַּעֲלֵ֣ם] águas a [רֹעֵ֣י] [צֹאנ֔וֹ] [אַיֵּ֛ה] [הַשָּׂ֥ם] [בְּקִרְבּ֖וֹ] a espírito');
INSERT INTO verses VALUES (18948, 23, 63, 12, '[מוֹלִיךְ֙] [לִימִ֣ין] Moisés [זְר֖וֹעַ] [תִּפְאַרְתּ֑וֹ] [בּ֤וֹקֵֽעַ] águas [מִפְּנֵיהֶ֔ם] para-fazer a-ele nome eternidade');
INSERT INTO verses VALUES (18949, 23, 63, 13, '[מוֹלִיכָ֖ם] [בַּתְּהֹמ֑וֹת] [כַּסּ֥וּס] [בַּמִּדְבָּ֖ר] não [יִכָּשֵֽׁלוּ]');
INSERT INTO verses VALUES (18950, 23, 63, 14, '[כַּבְּהֵמָה֙] [בַּבִּקְעָ֣ה] [תֵרֵ֔ד] espírito yhwh [תְּנִיחֶ֑נּוּ] [כֵּ֚ן] [נִהַ֣גְתָּ] [עַמְּךָ֔] para-fazer a-ti nome [תִּפְאָֽרֶת]');
INSERT INTO verses VALUES (18951, 23, 63, 15, '[הַבֵּ֤ט] [מִשָּׁמַ֙יִם֙] [וּרְאֵ֔ה] [מִזְּבֻ֥ל] [קָדְשְׁךָ֖] [וְתִפְאַרְתֶּ֑ךָ] [אַיֵּ֤ה] [קִנְאֽ͏ָתְךָ֙] [וּגְב֣וּרֹתֶ֔ךָ] multidao [מֵעֶ֛יךָ] [וְֽרַחֲמֶ֖יךָ] [אֵלַ֥י] [הִתְאַפָּֽקוּ]');
INSERT INTO verses VALUES (18952, 23, 63, 16, 'porque tu que porque não não [וְיִשְׂרָאֵ֖ל] não não tu yhwh yhwh [גֹּאֲלֵ֥נוּ] [מֵֽעוֹלָ֖ם] [שְׁמֶֽךָ]');
INSERT INTO verses VALUES (18953, 23, 63, 17, '[לָ֣מָּה] [תַתְעֵ֤נוּ] yhwh [מִדְּרָכֶ֔יךָ] [תַּקְשִׁ֥יחַ] [לִבֵּ֖נוּ] [מִיִּרְאָתֶ֑ךָ] [שׁ֚וּב] para-que [עֲבָדֶ֔יךָ] [שִׁבְטֵ֖י] [נַחֲלָתֶֽךָ]');
INSERT INTO verses VALUES (18954, 23, 63, 18, '[לַמִּצְעָ֕ר] [יָרְשׁ֖וּ] com [צָרֵ֕ינוּ] [בּוֹסְס֖וּ] [מִקְדָּשֶֽׁךָ]');
INSERT INTO verses VALUES (18955, 23, 63, 19, '[הָיִ֗ינוּ] [מֵֽעוֹלָם֙] não [בָּ֔ם] [לֹֽא־נִקְרָ֥א] não foi-chamado [לוּא־קָרַ֤עְתָּ] sobre-eles [יָרַ֔דְתָּ] [מִפָּנֶ֖יךָ] céus [נָזֹֽלּוּ] [sem-traducao] os-montes [sem-traducao]');
INSERT INTO chapters VALUES (743, 23, 64, 11);
INSERT INTO verses VALUES (18956, 23, 64, 1, '[כִּקְדֹ֧חַ] fogo [הֲמָסִ֗ים] águas [תִּבְעֶה־אֵ֔שׁ] [לְהוֹדִ֥יעַ] [שִׁמְךָ֖] [לְצָרֶ֑יךָ] [מִפָּנֶ֖יךָ] [גּוֹיִ֥ם] nações [sem-traducao]');
INSERT INTO verses VALUES (18957, 23, 64, 2, '[בַּעֲשׂוֹתְךָ֥] [נוֹרָא֖וֹת] não [נְקַוֶּ֑ה] [יָרַ֕דְתָּ] [מִפָּנֶ֖יךָ] [הָרִ֥ים] [נָזֹֽלּוּ]');
INSERT INTO verses VALUES (18958, 23, 64, 3, '[וּמֵעוֹלָ֥ם] não não não olho olho não [זוּלָ֣תְךָ֔] Elohim [לִמְחַכֵּה־לֽוֹ] faz-o [sem-traducao] a-ele');
INSERT INTO verses VALUES (18959, 23, 64, 4, '[פָּגַ֤עְתָּ] a seis [צֶ֔דֶק] [בִּדְרָכֶ֖יךָ] [יִזְכְּר֑וּךָ] [הֵן־אַתָּ֤ה] [קָצַ֙פְתָּ֙] tu [בָּהֶ֥ם] eternidade [וְנִוָּשֵֽׁעַ]');
INSERT INTO verses VALUES (18960, 23, 64, 5, '[וַנְּהִ֤י] [כַטָּמֵא֙] [כֻּלָּ֔נוּ] [וּכְבֶ֥גֶד] [עִדִּ֖ים] todo [וַנָּ֤בֶל] [כֶּֽעָלֶה֙] [כֻּלָּ֔נוּ] [וַעֲוֺנֵ֖נוּ] [כָּר֥וּחַ] [יִשָּׂאֻֽנוּ]');
INSERT INTO verses VALUES (18961, 23, 64, 6, '[וְאֵין־קוֹרֵ֣א] [בְשִׁמְךָ֔] [מִתְעוֹרֵ֖ר] [לְהַחֲזִ֣יק] sobre-ti [כִּֽי־הִסְתַּ֤רְתָּ] porque nós [וַתְּמוּגֵ֖נוּ] [בְּיַד־עֲוֺנֵֽנוּ]');
INSERT INTO verses VALUES (18962, 23, 64, 7, 'e-agora yhwh [אָבִ֣ינוּ] tu [אֲנַ֤חְנוּ] [הַחֹ֙מֶר֙] e-tu [יֹצְרֵ֔נוּ] [וּמַעֲשֵׂ֥ה] tua-mao [כֻּלָּֽנוּ]');
INSERT INTO verses VALUES (18963, 23, 64, 8, 'a yhwh yhwh até muito e-a eis [הַבֶּט־נָ֖א] [עַמְּךָ֥] [כֻלָּֽנוּ]');
INSERT INTO verses VALUES (18964, 23, 64, 9, 'cidades-de [קָדְשְׁךָ֖] eram [מִדְבָּ֑ר] Siao [מִדְבָּ֣ר] [הָיָ֔תָה] Jerusalém [שְׁמָמָֽה]');
INSERT INTO verses VALUES (18965, 23, 64, 10, 'casa [קָדְשֵׁ֣נוּ] [וְתִפְאַרְתֵּ֗נוּ] que [הִֽלְל֙וּךָ֙] nossos-pais ser [לִשְׂרֵ֣פַת] fogo e-todo ser foi [sem-traducao]');
INSERT INTO verses VALUES (18966, 23, 64, 11, '[הַעַל־אֵ֥לֶּה] [תִתְאַפַּ֖ק] yhwh yhwh [וּתְעַנֵּ֖נוּ] [עַד־מְאֹֽד׃] até');
INSERT INTO chapters VALUES (744, 23, 65, 25);
INSERT INTO verses VALUES (18967, 23, 65, 1, '[נִדְרַ֙שְׁתִּי֙] [לְל֣וֹא] [שָׁאָ֔לוּ] [נִמְצֵ֖אתִי] [לְלֹ֣א] [בִקְשֻׁ֑נִי] [אָמַ֙רְתִּי֙] [הִנֵּ֣נִי] [הִנֵּ֔נִי] a nação não chamou');
INSERT INTO verses VALUES (18968, 23, 65, 2, '[פֵּרַ֧שְׂתִּי] [יָדַ֛י] todo [אֶל־עַ֣ם] a povo [הַדֶּ֣רֶךְ] [לֹא־ט֔וֹב] [אַחַ֖ר] não bom');
INSERT INTO verses VALUES (18969, 23, 65, 3, 'o-povo [הַמַּכְעִיסִ֥ים] [אוֹתִ֛י] sobre face-de [זֹֽבְחִים֙] [בַּגַּנּ֔וֹת] [וּֽמְקַטְּרִ֖ים] [עַל־הַלְּבֵנִֽים] sobre');
INSERT INTO verses VALUES (18970, 23, 65, 4, '[הַיֹּֽשְׁבִים֙] [בַּקְּבָרִ֔ים] [וּבַנְּצוּרִ֖ים] [יָלִ֑ינוּ] [הָאֹֽכְלִים֙] [בְּשַׂ֣ר] [הַחֲזִ֔יר] [*ופרק] [**וּמְרַ֥ק]');
INSERT INTO verses VALUES (18971, 23, 65, 5, '[הָאֹֽמְרִים֙] [קְרַ֣ב] a-ti a que [קְדַשְׁתִּ֑יךָ] Estas [עָשָׁ֣ן] [בְּאַפִּ֔י] [אֵ֥שׁ] [יֹקֶ֖דֶת] fogo [sem-traducao] todo o-dia');
INSERT INTO verses VALUES (18972, 23, 65, 6, 'eis [כְתוּבָ֖ה] [לְפָנָ֑י] não [אֶחֱשֶׂה֙] que se [וְשִׁלַּמְתִּ֖י] [עַל־חֵיקָֽם] sobre');
INSERT INTO verses VALUES (18973, 23, 65, 7, '[עֲ֠וֺנֹתֵיכֶם] [וַעֲוֺנֹ֨ת] [אֲבוֹתֵיכֶ֤ם] [יַחְדָּו֙] disse yhwh que [קִטְּרוּ֙] sobre [וְעַל־הַגְּבָע֖וֹת] e-sobre [וּמַדֹּתִ֧י] [פְעֻלָּתָ֛ם] [רִֽאשֹׁנָ֖ה] [*על־**אֶל־חֵיקָֽם׃]');
INSERT INTO verses VALUES (18974, 23, 65, 8, '[כֹּ֣ה] disse disse yhwh [כַּאֲשֶׁ֨ר] [יִמָּצֵ֤א] [הַתִּירוֹשׁ֙] [בָּֽאֶשְׁכּ֔וֹל] a [אַל־תַּשְׁחִיתֵ֔הוּ] que [בְרָכָ֖ה] nele assim [אֶֽעֱשֶׂה֙] para-que [עֲבָדַ֔י] para-não [הֽ͏ַשְׁחִ֥ית] [הַכֹּֽל]');
INSERT INTO verses VALUES (18975, 23, 65, 9, '[וְהוֹצֵאתִ֤י] [מִֽיַּעֲקֹב֙] semente [וּמִיהוּדָ֖ה] [יוֹרֵ֣שׁ] [הָרָ֑י] [וִירֵשׁ֣וּהָ] [בְחִירַ֔י] [וַעֲבָדַ֖י] [יִשְׁכְּנוּ־שָֽׁמָּה]');
INSERT INTO verses VALUES (18976, 23, 65, 10, 'e-será [הַשָּׁרוֹן֙] [לִנְוֵה־צֹ֔אן] [וְעֵ֥מֶק] [עָכ֖וֹר] [לְרֵ֣בֶץ] [בָּקָ֑ר] manhã [אֲשֶׁ֥ר] que');
INSERT INTO verses VALUES (18977, 23, 65, 11, 'e-vós [עֹזְבֵ֣י] yhwh [הַשְּׁכֵחִ֖ים] a [קָדְשִׁ֑י] [הֽ͏ַעֹרְכִ֤ים] [לַגַּד֙] [שֻׁלְחָ֔ן] [וְהַֽמְמַלְאִ֖ים] [לַמְנִ֥י] [מִמְסָֽךְ]');
INSERT INTO verses VALUES (18978, 23, 65, 12, '[וּמָנִ֨יתִי] [אֶתְכֶ֜ם] [לַחֶ֗רֶב] [וְכֻלְּכֶם֙] [לַטֶּ֣בַח] [תִּכְרָ֔עוּ] por-causa-de [קָרָ֙אתִי֙] e-não [עֲנִיתֶ֔ם] [דִּבַּ֖רְתִּי] e-não [שְׁמַעְתֶּ֑ם] [וַתַּעֲשׂ֤וּ] [הָרַע֙] [בְּעֵינַ֔י] [וּבַאֲשֶׁ֥ר] não [בְּחַרְתֶּֽם׃] [sem-traducao]');
INSERT INTO verses VALUES (18979, 23, 65, 13, 'portanto assim disse Adonai yhwh eis [עֲבָדַ֤י] [׀] [יֹאכֵ֙לוּ֙] [וְאַתֶּ֣ם] [תִּרְעָ֔בוּ] eis [עֲבָדַ֛י] [יִשְׁתּ֖וּ] [וְאַתֶּ֣ם] [תִּצְמָ֑אוּ] eis [עֲבָדַ֛י] [יִשְׂמָ֖חוּ] [וְאַתֶּ֥ם]');
INSERT INTO verses VALUES (18980, 23, 65, 14, 'eis [עֲבָדַ֛י] [יָרֹ֖נּוּ] [מִטּ֣וּב] coração [וְאַתֶּ֤ם] [תִּצְעֲקוּ֙] [מִכְּאֵ֣ב] coração [וּמִשֵּׁ֥בֶר] espírito [תְּיֵלִֽילוּ]');
INSERT INTO verses VALUES (18981, 23, 65, 15, '[וְהִנַּחְתֶּ֨ם] [שִׁמְכֶ֤ם] [לִשְׁבוּעָה֙] [לִבְחִירַ֔י] [וֶהֱמִיתְ֖ךָ] Adonai yhwh [וְלַעֲבָדָ֥יו] chamaria nome [אַחֵֽר]');
INSERT INTO verses VALUES (18982, 23, 65, 16, 'que [הַמִּתְבָּרֵ֜ךְ] [בָּאָ֗רֶץ] [יִתְבָּרֵךְ֙] [בֵּאלֹהֵ֣י] [אָמֵ֔ן] [וְהַנִּשְׁבָּ֣ע] [בָּאָ֔רֶץ] [יִשָּׁבַ֖ע] [בֵּאלֹהֵ֣י] [אָמֵ֑ן] que [נִשְׁכְּח֗וּ] [הַצָּרוֹת֙] [הָרִ֣אשֹׁנ֔וֹת] [וְכִ֥י] [נִסְתְּר֖וּ] [מֵעֵינָֽי]');
INSERT INTO verses VALUES (18983, 23, 65, 17, 'porque eis-me [שָׁמַ֥יִם] céus [וָאָ֣רֶץ] [חֲדָשָׁ֑ה] [וְלֹ֤א] e-não [הָרִ֣אשֹׁנ֔וֹת] [וְלֹ֥א] e-não [עַל־לֵֽב] sobre coração');
INSERT INTO verses VALUES (18984, 23, 65, 18, 'porque se [עֲדֵי־עַ֔ד] [אֲשֶׁ֖ר] ate até que eu [בוֹרֵ֧א] porque eis-me [וְעַמָּ֥הּ] a [sem-traducao] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18985, 23, 65, 19, '[וְגַלְתִּ֥י] [בִירוּשָׁלַ֖͏ִם] [וְשַׂשְׂתִּ֣י] [בְעַמִּ֑י] e-não [בָּהּ֙] [ע֔וֹד] voz voz [וְק֥וֹל] [זְעָקָֽה]');
INSERT INTO verses VALUES (18986, 23, 65, 20, 'não [מִשָּׁ֜ם] [ע֗וֹד] ainda [יָמִים֙] [וְזָקֵ֔ן] [אֲשֶׁ֥ר] que não que a [בֶּן־מֵאָ֤ה] porque [יָמ֔וּת] filho-de cem ano [יְקֻלָּֽל] [sem-traducao] filho-de cem ano [sem-traducao]');
INSERT INTO verses VALUES (18987, 23, 65, 21, '[וּבָנ֥וּ] [בָתִּ֖ים] [וְיָשָׁ֑בוּ] [וְנָטְע֣וּ] vinhas [וְאָכְל֖וּ] [פִּרְיָֽם]');
INSERT INTO verses VALUES (18988, 23, 65, 22, 'não [יִבְנוּ֙] [וְאַחֵ֣ר] habitou não [יִטְּע֖וּ] [וְאַחֵ֣ר] comera porque a-árvore dias-de dias-de [וּמַעֲשֵׂ֥ה] [יְדֵיהֶ֖ם] maos-deles [בְחִירָֽי] [sem-traducao]');
INSERT INTO verses VALUES (18989, 23, 65, 23, 'não [יִֽיגְעוּ֙] [לָרִ֔יק] e-não [יֵלְד֖וּ] [לַבֶּהָלָ֑ה] que semente [בְּרוּכֵ֤י] yhwh [הֵ֔מָּה] [וְצֶאֱצָאֵיהֶ֖ם] [אִתָּֽם]');
INSERT INTO verses VALUES (18990, 23, 65, 24, 'e-será [טֶֽרֶם־יִקְרָ֖אוּ] [וַאֲנִ֣י] e-eu [ע֛וֹד] eles eles [וַאֲנִ֥י] [אֶשְׁמָֽע]');
INSERT INTO verses VALUES (18991, 23, 65, 25, '[זְאֵ֨ב] [וְטָלֶ֜ה] [יִרְע֣וּ] [כְאֶחָ֗ד] [וְאַרְיֵה֙] [כַּבָּקָ֣ר] [יֹֽאכַל־תֶּ֔בֶן] [וְנָחָ֖שׁ] pó [לַחְמ֑וֹ] [לֹֽא־יָרֵ֧עוּ] não [בְּכָל־הַ֥ר] e-não disse yhwh disse yhwh');
INSERT INTO chapters VALUES (745, 23, 66, 24);
INSERT INTO verses VALUES (18992, 23, 66, 1, 'assim disse yhwh os-céus [כִּסְאִ֔י] E-a-terra [הֲדֹ֣ם] [רַגְלָ֑י] [אֵי־זֶ֥ה] [בַ֙יִת֙] casa que [וְאֵי־זֶ֥ה] lugar [מְנוּחָתִֽי]');
INSERT INTO verses VALUES (18993, 23, 66, 2, 'e-[OBJ] todo estes [וַיִּהְי֥וּ] [כָל־אֵ֖לֶּה] [נְאֻם־יְהוָ֑ה] todo [אַבִּ֔יט] oráculo-de yhwh e-a este a espírito sobre');
INSERT INTO verses VALUES (18994, 23, 66, 3, '[שׁוֹחֵ֨ט] [הַשּׁ֜וֹר] [מַכֵּה־אִ֗ישׁ] homem [הַשֶּׂה֙] [עֹ֣רֵֽף] [כֶּ֔לֶב] [מַעֲלֵ֤ה] [מִנְחָה֙] oferta-de-cereais [מַזְכִּ֥יר] [לְבֹנָ֖ה] [מְבָ֣רֵֽךְ] [אָ֑וֶן] [גַּם־הֵ֗מָּה] iniquidade também eles [נַפְשָׁ֥ם] [חָפֵֽצָה] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (18995, 23, 66, 4, 'também eu [בְּתַעֲלֻלֵיהֶ֗ם] [וּמְגֽוּרֹתָם֙] [אָבִ֣יא] a-eles a-eles por-causa-de [וְאֵ֣ין] e-não-há [דִּבַּ֖רְתִּי] [וְלֹ֣א] e-não [וַיַּעֲשׂ֤וּ] [הָרַע֙] [בְּעֵינַ֔י] [וּבַאֲשֶׁ֥ר] [לֹֽא־חָפַ֖צְתִּי] não [sem-traducao] escolheram');
INSERT INTO verses VALUES (18996, 23, 66, 5, '[שִׁמְעוּ֙] palavra-de yhwh [אֶל־דְּבָר֑וֹ] a [אֲחֵיכֶ֨ם] [שֹׂנְאֵיכֶ֜ם] [מְנַדֵּיכֶ֗ם] [לְמַ֤עַן] [שְׁמִי֙] [יִכְבַּ֣ד] yhwh [וְנִרְאֶ֥ה] yhwh [וְהֵ֥ם] [יֵבֹֽשׁוּ]');
INSERT INTO verses VALUES (18997, 23, 66, 6, 'voz [שָׁאוֹן֙] [מֵעִ֔יר] voz [מֵֽהֵיכָ֑ל] voz yhwh [מְשַׁלֵּ֥ם] [גְּמ֖וּל] [לְאֹיְבָֽיו]');
INSERT INTO verses VALUES (18998, 23, 66, 7, '[בְּטֶ֥רֶם] [תָּחִ֖יל] deu-a-luz [בְּטֶ֨רֶם] virá [חֵ֛בֶל] a-ela [וְהִמְלִ֥יטָה] macho');
INSERT INTO verses VALUES (18999, 23, 66, 8, 'quem ouviu quem ver viu [הֲי֤וּחַל] terra terra um um se vez nação [כִּֽי־חָ֛לָה] [גַּם־יָלְדָ֥ה] porque [אֶת־בָּנֶֽיהָ] também a');
INSERT INTO verses VALUES (19000, 23, 66, 9, '[הַאֲנִ֥י] [אַשְׁבִּ֛יר] e-não [אוֹלִ֖יד] dira yhwh se eu [וְעָצַ֖רְתִּי] disse disse [sem-traducao]');
INSERT INTO verses VALUES (19001, 23, 66, 10, '[שִׂמְח֧וּ] a [וְגִ֥ילוּ] [בָ֖הּ] [כָּל־אֹהֲבֶ֑יהָ] todo [אִתָּהּ֙] [מָשׂ֔וֹשׂ] [כָּל־הַמִּֽתְאַבְּלִ֖ים] [עָלֶֽיהָ] todo');
INSERT INTO verses VALUES (19002, 23, 66, 11, '[לְמַ֤עַן] [תִּֽינְקוּ֙] [וּשְׂבַעְתֶּ֔ם] [מִשֹּׁ֖ד] [תַּנְחֻמֶ֑יהָ] [לְמַ֧עַן] [תָּמֹ֛צּוּ] [וְהִתְעַנַּגְתֶּ֖ם] [מִזִּ֥יז] [כְּבוֹדָֽהּ׃]');
INSERT INTO verses VALUES (19003, 23, 66, 12, 'porque assim disse yhwh eis-me [נֹטֶֽה־אֵ֠לֶיהָ] [כְּנָהָ֨ר] [שָׁל֜וֹם] [וּכְנַ֧חַל] [שׁוֹטֵ֛ף] [כְּב֥וֹד] [גּוֹיִ֖ם] nações [עַל־צַד֙] sobre [וְעַל־בִּרְכַּ֖יִם] [תְּשָׁעֳשָֽׁעוּ] e-sobre [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (19004, 23, 66, 13, '[כְּאִ֕ישׁ] que sua-mãe [תְּנַחֲמֶ֑נּוּ] assim eu [אֲנַ֣חֶמְכֶ֔ם] [וּבִירֽוּשָׁלַ֖͏ִם] [תְּנֻחָֽמוּ]');
INSERT INTO verses VALUES (19005, 23, 66, 14, '[וּרְאִיתֶם֙] [וְשָׂ֣שׂ] [לִבְּכֶ֔ם] [וְעַצְמוֹתֵיכֶ֖ם] [כַּדֶּ֣שֶׁא] [תִפְרַ֑חְנָה] [וְנוֹדְעָ֤ה] mão-de yhwh a seus-servos a');
INSERT INTO verses VALUES (19006, 23, 66, 15, 'porque yhwh yhwh [יָב֔וֹא] vira [מַרְכְּבֹתָ֑יו] [לְהָשִׁ֤יב] [בְּחֵמָה֙] [אַפּ֔וֹ] sua-ira [בְּלַהֲבֵי־אֵֽשׁ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (19007, 23, 66, 16, 'que [בָאֵשׁ֙] yhwh [נִשְׁפָּ֔ט] [וּבְחַרְבּ֖וֹ] a todo [חַֽלְלֵ֥י] yhwh yhwh');
INSERT INTO verses VALUES (19008, 23, 66, 17, '[הַמִּתְקַדְּשִׁ֨ים] [וְהַמִּֽטַּהֲרִ֜ים] a [אַחַ֤ר] [*אחד] [**אַחַת֙] [בַּתָּ֔וֶךְ] [אֹֽכְלֵי֙] [בְּשַׂ֣ר] [הַחֲזִ֔יר] [וְהַשֶּׁ֖קֶץ] [וְהָעַכְבָּ֑ר] [יַחְדָּ֥ו] oráculo-de yhwh');
INSERT INTO verses VALUES (19009, 23, 66, 18, '[וְאָנֹכִ֗י] [מַעֲשֵׂיהֶם֙] [וּמַחְשְׁבֹ֣תֵיהֶ֔ם] [בָּאָ֕ה] [לְקַבֵּ֥ץ] a todo as-nações [וְרָא֥וּ] [אֶת־כְּבוֹדִֽי] a');
INSERT INTO verses VALUES (19010, 23, 66, 19, '[וְשַׂמְתִּ֨י] [בָהֶ֜ם] [א֗וֹת] [וְשִׁלַּחְתִּ֣י] [מֵהֶ֣ם] [׀] a [אֶֽל־הַגּוֹיִ֞ם] [תַּרְשִׁ֨ישׁ] [פּ֥וּל] [וְל֛וּד] [מֹ֥שְׁכֵי] [קֶ֖שֶׁת] [תֻּבַ֣ל] [וְיָוָ֑ן] [הָאִיִּ֣ים] [הָרְחֹקִ֗ים] que não [אֶת־שִׁמְעִי֙] a [אֶת־כְּבוֹדִ֔י] e-não viram a [sem-traducao] [sem-traducao] a [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (19011, 23, 66, 20, '[וְהֵבִ֣יאוּ] a todo [׀] de-todo [׀] [לַֽיהוָ֡ה] [בַּסּוּסִ֡ים] [וּ֠בָרֶכֶב] [וּבַצַּבִּ֨ים] [וּבַפְּרָדִ֜ים] [וּבַכִּרְכָּר֗וֹת] sobre sobre [קָדְשִׁ֛י] [יְרוּשָׁלַ֖͏ִם] disse yhwh yhwh como [בְנֵ֨י] filhos-de Israel a [טָה֖וֹר] [בֵּ֥ית] yhwh casa yhwh');
INSERT INTO verses VALUES (19012, 23, 66, 21, 'e-também [אֶקַּ֛ח] [לַכֹּהֲנִ֥ים] [לַלְוִיִּ֖ם] disse yhwh yhwh');
INSERT INTO verses VALUES (19013, 23, 66, 22, 'que [כַאֲשֶׁ֣ר] os-céus [הַ֠חֳדָשִׁים] E-a-terra [הַחֲדָשָׁ֜ה] que eu fez [עֹמְדִ֥ים] [לְפָנַ֖י] oráculo-de yhwh assim [זַרְעֲכֶ֖ם] [וְשִׁמְכֶֽם]');
INSERT INTO verses VALUES (19014, 23, 66, 23, 'e-foi [מִֽדֵּי־חֹ֙דֶשׁ֙] novo [וּמִדֵּ֥י] [שַׁבָּ֖ת] [בְּשַׁבַּתּ֑וֹ] [יָב֧וֹא] [כָל־בָּשָׂ֛ר] todo [לְפָנַ֖י] disse yhwh disse yhwh');
INSERT INTO verses VALUES (19015, 23, 66, 24, '[וְיָצְא֣וּ] [וְרָא֔וּ] [בְּפִגְרֵי֙] [הָאֲנָשִׁ֔ים] [הַפֹּשְׁעִ֖ים] em-mim que [תוֹלַעְתָּ֞ם] não [תָמ֗וּת] [וְאִשָּׁם֙] não [תִכְבֶּ֔ה] e-sejam [דֵרָא֖וֹן] para-todo');
INSERT INTO books VALUES (24, 'JER', 'Jeremias', 'AT', 52);
INSERT INTO chapters VALUES (746, 24, 1, 19);
INSERT INTO verses VALUES (19016, 24, 1, 1, 'palavras-de Jeremias filho-de Chilquiyahu de os-sacerdotes que ba-anatos em-terra-de Benjamin');
INSERT INTO verses VALUES (19017, 24, 1, 2, 'que ser palavra-de a-ele para-ele bi-yemos Josias filho-de Aomôn rei Judá bishlosh- doze ano lemalcho');
INSERT INTO verses VALUES (19018, 24, 1, 3, 'e-houve nos-dias-de Jehoiãquim filho-de יֹאשִׁיָּ֙הוּ֙ rei Judá até tom Ashthai dez ano litzidkiyahu filho-de יֹאשִׁיָּ֖הוּ rei Judá até golot jerusalém no mês- o-quinto');
INSERT INTO verses VALUES (19019, 24, 1, 4, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19020, 24, 1, 5, 'antes-de babeten yedaticha e antes que תֵצֵ֥א de-o-ventre santificaste-te-a profeta para-os-povos e-te-darei');
INSERT INTO verses VALUES (19021, 24, 1, 6, 'e-disse ahah Adonai yhwh eis não conheci palavra eu menino eu');
INSERT INTO verses VALUES (19022, 24, 1, 7, 'E-disse yhwh a-mim a dires eu que porque sobre todo que eu-te-enviarei vires e-a todo que e-eu-te-comandarei tu-falarás');
INSERT INTO verses VALUES (19023, 24, 1, 8, 'a temas de-face-deles porque אִתְּךָ֥ eu para te salvar oráculo-de yhwh');
INSERT INTO verses VALUES (19024, 24, 1, 9, 'e-estendeu yhwh a mão-de-ele e-ele-tochou E-disse yhwh E-disse eis dei behold dei davray no teu');
INSERT INTO verses VALUES (19025, 24, 1, 10, 'viu hipqaddetikha o-dia o-dia sobre as-nações e-sobre as-mamlekhót para-quebrar e-para-esmigalhar e-para-aniquilar velaharos para-construir velintoa');
INSERT INTO verses VALUES (19026, 24, 1, 11, 'e-houve palavra-de yhwh dizendo para-dizer o-quê tu viu Yirmeyahu e-eu-disse vara shaqed eu viu');
INSERT INTO verses VALUES (19027, 24, 1, 12, 'E-disse yhwh para-mim hetavettha para-ver porque aquecido eu sobre minha palavra para fazê-lo:');
INSERT INTO verses VALUES (19028, 24, 1, 13, 'e-houve palavra-de יהוה a-mim shenit dizendo que tu viu e-disse sir nafuch eu viu u-fanav de-diante-de tsāphōnā');
INSERT INTO verses VALUES (19029, 24, 1, 14, 'E-disse yhwh a-mim  Mitsafon tipatach o-mal sobre todo a-terra a-terra');
INSERT INTO verses VALUES (19030, 24, 1, 15, 'que eis-me chamou para-todo mishpakhot mamlakhot tzafonah oráculo-de yhwh uva''u venatnu homem seu trono petakh- shaare Jerusalém e-sobre todo suas muralhas ao-redor e-sobre todo cidades Judá');
INSERT INTO verses VALUES (19031, 24, 1, 16, 'e-eu-falarei de-missoes-meus a-eles sobre todo maldade-deles que עֲזָב֗וּנִי וַֽיְקַטְּרוּ֙ para-Elohim outros e-prostraram-se para-o-trabalho mãos-deles-verso-final');
INSERT INTO verses VALUES (19032, 24, 1, 17, 'e-tu viste-se teus joelhos e-voces-levantaram-se e-tu-falarás a-eles objeto-direto todo eu eu eu-direi-te a caireis de-diante-deles para-que-não irmã-teu diante-deles');
INSERT INTO verses VALUES (19033, 24, 1, 18, 'e-eu eis eu te dei o-dia para uma cidade fortaleza e para o-pilar de-ferro e para as-rochas bronze sobre todo a-terra para os-reis יְהוּדָה para seus lábios a-terra e para o-people a-terra');
INSERT INTO verses VALUES (19034, 24, 1, 19, 'e lucharão a-ti e-não para-ti para-ti porque com-te eu oráculo-de yhwh para-te-resgaste');
INSERT INTO chapters VALUES (747, 24, 2, 37);
INSERT INTO verses VALUES (19035, 24, 2, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19036, 24, 2, 2, 'andou e-anunciarás em-os-ouvidos Jerusalém dizendo assim disse yhwh lembrado-ei para-ti bondade minha-juventude-te amor-de circundantes-teu andar-te depois-mim no-deserto em-terra-de não semente-ela');
INSERT INTO verses VALUES (19037, 24, 2, 3, 'santo-de Israel para-יהוה começo-o colheita-sua todo comedor-seu se-arrependam maldade vem-a a-eles oráculo-de yhwh');
INSERT INTO verses VALUES (19038, 24, 2, 4, 'ouvi palavra-de yhwh casa Jacó e-todo famílias-de-as casa Israel');
INSERT INTO verses VALUES (19039, 24, 2, 5, 'assim disse disse yhwh acharam-os os-vossos-pais em-mim enganho que afastaram-se-eles de-mim-sobre e-forem-eles atrás-de o-vazio e-perderam-se-eles');
INSERT INTO verses VALUES (19040, 24, 2, 6, 'e-não disseram onde-a yhwh o-que-fez-subir a-nós de-terra-de Egito que-conduz-o nós-aos no-deserto בְּאֶ֨רֶץ a-areia e-sussurro na-terra seca e-trevas na-terra não passou nela homem homem habitou homem nome');
INSERT INTO verses VALUES (19041, 24, 2, 7, 'e-trouxe a-vós a terra הַכַּרְמֶ֔ל para-comer fruto-seu e-bom-seu e-entraram e-tornaram-sujos a terra-minha e-herança-minha samtém le-toeaváh');
INSERT INTO verses VALUES (19042, 24, 2, 8, 'os-sacerdotes não amru onde-a yhwh ve-tophséi a-torá não yedáuní ve-haróim pashú bi ve-hanévi''im nibáu ba-ba''al e-após-de não gritai CAMINHARAM:');
INSERT INTO verses VALUES (19043, 24, 2, 9, 'portanto até inimigo com-vocês oráculo-de yhwh e-a filhos-de filhos-vos inimigo.');
INSERT INTO verses VALUES (19044, 24, 2, 10, 'que voltai ilhas-de-a kitios e-vedei e-qedar enviai e-refleti muito e-vi eis era assim');
INSERT INTO verses VALUES (19045, 24, 2, 11, 'o-heimir nação Elohim e-eles não Elohim e-povo-meu heimir kavodo bela yoel');
INSERT INTO verses VALUES (19046, 24, 2, 12, 'shomu céus sobre esta veshaaruu muito muito oráculo-de yhwh');
INSERT INTO verses VALUES (19047, 24, 2, 13, 'porque sh-teiym raot fez meu-povo oti abandonaram fonte- águas vida para-cavar a-eles boreis boreis quebrados que não as-águas as-águas');
INSERT INTO verses VALUES (19048, 24, 2, 14, 'o-escravo Israel se nascido ele ele ser foi labaz');
INSERT INTO verses VALUES (19049, 24, 2, 15, 'sobre-ele clamarão de-cidades deram קוֹלָ֑ם e-ele-colocou terra-o para-a-luz cidades-seus sem habitou');
INSERT INTO verses VALUES (19050, 24, 2, 16, 'também filhos-de colina pastorear-vos topo');
INSERT INTO verses VALUES (19051, 24, 2, 17, 'porventura-não esta farás- para-ti abandonar-te a yhwh Elohim-vosso na-vez levando-te no-caminho');
INSERT INTO verses VALUES (19052, 24, 2, 18, 'e-agora que- para-ti para-o-caminho Egito para-beber águas-de preto e-que a-ti para-o-caminho Assur rio águas-de rio');
INSERT INTO verses VALUES (19053, 24, 2, 19, 'você-endurecerá maldade-tua e-mudanças-tuas repreender-te e-conhecimento וּרְאִי֙ porque mau e-amargura abandono-teu a yhwh Elohim-teu e-não temor-meu אֵלַ֔יִךְ oráculo-de Adonai yhwh exércitos');
INSERT INTO verses VALUES (19054, 24, 2, 20, 'que do-tempo quebrei-eu opressão-teu separei-eu grilhões-teus e-ela-disse não porque sobre que gibeá alta e-em-baixo-de todo madeira-de verdejante אתָ zora meretriz');
INSERT INTO verses VALUES (19055, 24, 2, 21, 'e-eu plantei-te sorok até a totalidade semente verdade e-como inversamente para-mim surí o-gefên estranha');
INSERT INTO verses VALUES (19056, 24, 2, 22, 'que se tu-kabbesi be-neter ve-tarbi- para-ti bo-rith nikhtam avonekha diante-de-mim oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (19057, 24, 2, 23, 'como to-emri não nitmateiti depois-de ha-baalim não fui veja caminho-teu na-terra sabe que עָשִׂ֑ית no parto virgem travessas seus caminhos');
INSERT INTO verses VALUES (19058, 24, 2, 24, 'cabra estuda deserto no vale respira espírito תַּאֲנָתָ֖הּ quem espírito todo quem não יִיעָ֔פוּ não יִמְצָאֽוּנְהָ׃');
INSERT INTO verses VALUES (19059, 24, 2, 25, 'impede teu-pé de-pressa de-sede e-disse não-ash lo porque ahavti estrangeiros ve-achareihem irei.');
INSERT INTO verses VALUES (19060, 24, 2, 26, 'kbo-shet ganav que yimtze assim hovishu casa Israel הֵ֤מָּה reis-deles príncipes-deles ve-koheneyhem unevieyhem');
INSERT INTO verses VALUES (19061, 24, 2, 27, 'dizendo [לָעֵ֜ץ] אֲבִי tu e-para-a-pedra tu porque viraram-se a-mim costas e-não face e-na-hora de-sua-ira dirão levanta-te e-salva-nos');
INSERT INTO verses VALUES (19062, 24, 2, 28, 'e onde Elohim-teu que fizeste para-ti levantem-se se salvem-te na época que porque número vosso muro foram teu-Elohim Judá');
INSERT INTO verses VALUES (19063, 24, 2, 29, 'por-que reivai-vos a-mim todos-vos pecasteis em-mi oráculo-de yhwh');
INSERT INTO verses VALUES (19064, 24, 2, 30, 'לַשָּׁוְא֙ הִכֵּ֣יתִי a filhos-vos não não tomaram comer-ia espadas-vos profetas-vos como-leão מַשְׁחִֽית׃');
INSERT INTO verses VALUES (19065, 24, 2, 31, 'o-dor vós Reu palavra-de yhwh e-midbar eu-fui para-Israel terra terra ma-apleyah por-que אָמְר֤וּ meu-povo nós-odiamos não viremos mais para-ti');
INSERT INTO verses VALUES (19066, 24, 2, 32, 'e-se-esquecerás virgem-na esposa-seu a-noiva suas-ligações e-meu-povo esquece-me dias não מִסְפָּֽר׃');
INSERT INTO verses VALUES (19067, 24, 2, 33, 'que- fazes-bem teu-caminho para-pedir ahavah também também a as-más a minhas-caminhos:');
INSERT INTO verses VALUES (19068, 24, 2, 34, 'também em-tus-as-aspas encontramo-nos sangue almas pobres puros não na-o-montante que porque sobre todo estes');
INSERT INTO verses VALUES (19069, 24, 2, 35, 'e-ela-disse que eu-sou-inocente somente retornou de-seu-nariz de-mim eis-me נִשְׁפּ֣ט você sobre não não eu-passei-peor');
INSERT INTO verses VALUES (19070, 24, 2, 36, 'que- muito muito para-mudar também seu-caminho também de-Egito eu-me-envergonharei conforme- envergonhe-se de-Assur');
INSERT INTO verses VALUES (19071, 24, 2, 37, 'também de-a este sai e-tuas-mãos sobre cabeça-teu porque rejeitou yhwh em-segurança-tua a-eles sucede-teu para-eles');
INSERT INTO chapters VALUES (748, 24, 3, 25);
INSERT INTO verses VALUES (19072, 24, 3, 1, 'dizendo eis irá-se homem a sua e caminhou dele e-foi para um homem- outro irá-se para-ela ainda acaso-nao a-terra implorará a-terra aquela e-você prostituta רֵעִ֣ים muitos וְשׁ֥וֹב para-mim oráculo-de yhwh');
INSERT INTO verses VALUES (19073, 24, 3, 2, 'ergue- seus-olhos sobre lábios não onde não sobre caminhos a-eles a-eles como-aravi no-deserto terra terra em-a-impudicícia-tua e-em-a-maldade-tua');
INSERT INTO verses VALUES (19074, 24, 3, 3, 'e-eles-se-recusaram chuvas-grandes e-mosca não ser e-do-calor mulher meretriz-a ser para-ti de-aversão-tua e-se-esconderam');
INSERT INTO verses VALUES (19075, 24, 3, 4, 'não de-a-ora para-mim pai-meu chefe os-meus-jovens-dias tu');
INSERT INTO verses VALUES (19076, 24, 3, 5, 'se-vigiará para-sempre se ele-guardará eis eis e-você-fazeu as-más-coisas e foi capaz');
INSERT INTO verses VALUES (19077, 24, 3, 6, 'E-disse yhwh a-mim em-os-dias-de Joash o-rei viste que ela-fez משובה Israel que ia ela sobre todo monte-de sua altura e-a em-substituição-a todo árvore Ranã e se deitou com nome');
INSERT INTO verses VALUES (19078, 24, 3, 7, 'e-disse aharei asoteha a todo estes a-mim tashuv e-não shava bagoda achotah Judá');
INSERT INTO verses VALUES (19079, 24, 3, 8, 'vaerae que sobre todo blasfêmias que niafa משובה Israel shilachateha e-eu-deti a livro-de corte-de-a-sua para-ela e-não temeu-ela traidora-ele יְהוּדָה אֲחוהָהּ ela foi וַתִּ֥זֶן também ela');
INSERT INTO verses VALUES (19080, 24, 3, 9, 'e-será de-o-som impudicícia-de-a e-ela-profanou a a-terra e-ela-se-enfureceu a a-pedra e-a o-árvore:');
INSERT INTO verses VALUES (19081, 24, 3, 10, 'e-também em-todo esta não leva-a a-mim trai-dora que יְהוּדָה em-todo para-o-seu-cor porque se em-falso oráculo-de yhwh');
INSERT INTO verses VALUES (19082, 24, 3, 11, 'E-disse yhwh a-mim tsidqā naphshā mēšubbā Israel mibbōgēdā Judá');
INSERT INTO verses VALUES (19083, 24, 3, 12, 'andou e-chamara-tu-a a as-palavras-as ha-eleh para-o-norte e-dizes retorna [יִשְׂרָאֵל֙] Israel oráculo-de yhwh não eu-aplicarei face-de em-vocês não piedoso eu oráculo-de yhwh não eu-arrancarei para-eternidade');
INSERT INTO verses VALUES (19084, 24, 3, 13, 'somente דְּעִ֣י עֲוֺנֵ֔ךְ que בַּיהוָ֥ה אֱלֹהַ֖יִךְ פָּשָׁ֑עַתְּ e espalhaste a דְּרָכַ֜יִךְ debaixo em-lugar-de todo madeira-de רַעֲנָן וּבְקוֹלִ֥י não ouviram oráculo-de yhwh');
INSERT INTO verses VALUES (19085, 24, 3, 14, 'שׁ֣וּבוּ filhos rebeldes oráculo-de que eu eu eu-tomei-posse-de-vos em-vós e-eu-tomarei um um de-cidade e-dois de-família e levar-te-ei vós צִיּֽוֹן');
INSERT INTO verses VALUES (19086, 24, 3, 15, 'e-darei a-vós pastores com-meu-corpo e-malvaverão vós conhecer e-o-sabedoria');
INSERT INTO verses VALUES (19087, 24, 3, 16, 'e-será que vocês-aumentarão e-vocês-semultiplicarão na-terra nos-dias esses-eles oráculo-de yhwh não dirão ainda arca-de subia yhwh e-não ele-subirá sobre coração e-não e-lhes-recordarão nele e-não e-eles-contarão e-não será-fazido ainda');
INSERT INTO verses VALUES (19088, 24, 3, 17, 'em-o-tempo a aquela chamarão para Jerusalém trono-de yhwh e-esperarão a-ela todo as-nações yhwh yhwh para-Ierusalém e-não irão ainda depois de-malícia seus corações o-mal');
INSERT INTO verses VALUES (19089, 24, 3, 18, 'em-os-dias e-eles irão casa-de יְהוּדָה sobre casa Israel e-virão yachdav de-terra-de norte sobre a-terra que dei-herança a vosso avós:');
INSERT INTO verses VALUES (19090, 24, 3, 19, 'e-eu disse-ei- como eu farei com vocês em filhos e darei- terra terra desejo herança cobiça exércitos nações e-disse pai-meu para-mim não não');
INSERT INTO verses VALUES (19091, 24, 3, 20, 'certamente enganou-a mulher de-amigo-seu assim vocês-enganaram b-i casa Israel oráculo-de yhwh');
INSERT INTO verses VALUES (19092, 24, 3, 21, 'voz sobre lábios foi-ouvido porque súplicas-de filhos-de que porque fizeram-perversidade a caminhos-seus esqueceram-se a yhwh אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (19093, 24, 3, 22, 'Shuvu@ filhos voltados-para-o-norte repreensão volta-vos eis-nós a-nos para-ti que tu yhwh Elohim-nosso');
INSERT INTO verses VALUES (19094, 24, 3, 23, 'aḥen lašequer migva''ot hamon harim certamente beyehová Elohim-nosso tšu''at Israel');
INSERT INTO verses VALUES (19095, 24, 3, 24, 'e-o-vergonha comer-á a exaustão-de nosso-abos de-nossas-juventudes a rebanho-deles e-a gado-deles a nos-seus-filhos e-a filhas-de-eles');
INSERT INTO verses VALUES (19096, 24, 3, 25, 'deitamos em-nossa-impudicícia e-vos-cobrireis de-nossa-vergonha que a yhwh Elohim-nosso nos arrependemos nós e-pais-de-nosso da-juventude-nossa e-até o-dia esta e-não ouvi-mo בְּקוֹל yhwh Elohim-nosso');
INSERT INTO chapters VALUES (749, 24, 4, 31);
INSERT INTO verses VALUES (19097, 24, 4, 1, 'se tornar-se-de-volta Israel oráculo-de yhwh para-mim voltarás e-se retirar-te abominações-tua de-perante-mim e-não balançar-te');
INSERT INTO verses VALUES (19098, 24, 4, 2, 'e-jurares vive yhwh בֶּאֱמֶ֖ת com-justiça e-com-retidão nele nele nações e-nele יִתְהַלָּֽלוּ׃');
INSERT INTO verses VALUES (19099, 24, 4, 3, 'porque assim disse yhwh a-o-homem יְהוּדָה e-para-Jerusalém nireu a-vós nir e-a tizrêu a qôtsim');
INSERT INTO verses VALUES (19100, 24, 4, 4, 'himolû la-yhwh vehasirû arôlôt para-coracoes-vos homem יְהוּדָה e-habitantes-de Jerusalém para-que-não תֵּצֵ֨א כָאֵ֜שׁ חֲמָתִ֗י וּבָעֲרָה֙ e-não de-diante-de de-face-de mau מַעַלְלֵיכֶֽם׃');
INSERT INTO verses VALUES (19101, 24, 4, 5, 'הַגּ֣idoּ בִֽיהוּדָ֗ה וּבִירוּשָׁלִַ֙ם֙ הַשְׁמִ֔יעוּ וְאִמְר֕וּ corneta em-a-terra Chamem Preencham e-digam heasêpu venabôah a cidades-de o-mb-tsár:');
INSERT INTO verses VALUES (19102, 24, 4, 6, 'e-levem nes tsi-yó-ná o-ez-zu que ta-am-mo-du eu ra-á eu מֵבִ֥יא מצפון ve-she-ver grande');
INSERT INTO verses VALUES (19103, 24, 4, 7, 'subir a-rí-e mi-su-b-kho e-destruir nações partiu-se sair de-seu-lugar para fazer terra-te para-a-luz teus-cidades você-plantará sem morador:');
INSERT INTO verses VALUES (19104, 24, 4, 8, 'sobre esta cinturam-se de-sacos lamentem que porque não retornou nós também yhwh de-nós');
INSERT INTO verses VALUES (19105, 24, 4, 9, 'e-era em-o-dia- o-aquele oráculo-de yhwh será-perdido coração-de o-rei e-coracao os-príncipes e-nascerão os-sacerdotes e-os-profetas serão-estupefatos');
INSERT INTO verses VALUES (19106, 24, 4, 10, 'e-disse ah-ah Adonai yhwh certamente a-alta a-alta ao-povo o-este e-a-Jerusalém para-dizer dizendo será será a-vós espada espada a-alma');
INSERT INTO verses VALUES (19107, 24, 4, 11, 'em-o-tempo a aquela ye''amor para-o-povo- o-este espírito espírito seco lábios o-caminho-de caminho filha-de meu-povo não para-vestir-se e não para-fazer-branco');
INSERT INTO verses VALUES (19108, 24, 4, 12, 'espírito enchei de-estes virá para-mim agora também eu falarei de-leis a-eles');
INSERT INTO verses VALUES (19109, 24, 4, 13, 'eis como-nuvens ele-subirá subia de-seus-carros levem-se de-machados seus-cavalos אָוי֙ para-nós porque que');
INSERT INTO verses VALUES (19110, 24, 4, 14, 'lava-me de-mal לִבֵּךְ֙ Jerusalém para-que serei-salvo até quando תָּלִ֥ין em-teu-interior מַחְשְׁב֥וֹת teu-vil');
INSERT INTO verses VALUES (19111, 24, 4, 15, 'que voz מַגִּ֖יד de-Dan e-faz-ouvir iniquidade me-ha-mar Efrayim');
INSERT INTO verses VALUES (19112, 24, 4, 16, 'lembrar-vos para os-goyim eis fazeis-ouvir sobre Jerusalém nó-tser-im vêm de-terra-de ha-mer-chak va-yit-to-nu sobre cidades-de יְהוּדָה qol-am');
INSERT INTO verses VALUES (19113, 24, 4, 17, 'kesh-shom-rei Shaddai foram sobre-ela em-o-redor porque me ma-rah-tah oráculo-de yhwh');
INSERT INTO verses VALUES (19114, 24, 4, 18, 'dar-chekh u-ma-al-la-yikh a-so Estas para-ti esta ra-a-tekh que amaro que tocar até do-teu-coracao');
INSERT INTO verses VALUES (19115, 24, 4, 19, 'de-ventre de-ventre קירות do-meu-coracao parecido-com para-mim לִבִּ֖י não silencio porque não chifre que voz guerra');
INSERT INTO verses VALUES (19116, 24, 4, 20, 'שֶׁ֤בֶר sobre quebra que porque ruina todo a-terra de-súbito corram-se tendas-meus רֶ֖גַע coberturas-minhas');
INSERT INTO verses VALUES (19117, 24, 4, 21, 'até até-quando vejo- voz ouço- voz-que chifre');
INSERT INTO verses VALUES (19118, 24, 4, 22, 'que insensato עַמּי de-mim não não filhos tropeçadores eles e-não sábios elas-eram חֲכָמִ֥ים eles para-o-mal e-para-bem não não');
INSERT INTO verses VALUES (19119, 24, 4, 23, 'vi a a-terra e-vazia sem-forma e-no-lar e-a os-céus e-não-há luz-deles-verso');
INSERT INTO verses VALUES (19120, 24, 4, 24, 'vi os-montes e-eis tremendo-estando e-todo as-colinas se-misturaram-verso');
INSERT INTO verses VALUES (19121, 24, 4, 25, 'vi-eu e-eis não-há o-homem e-todo ave os-céus andaram-verso');
INSERT INTO verses VALUES (19122, 24, 4, 26, 'vi-eu e-eis o-carvalho a-deserto e-todo seus-festivais de-diante-de yhwh de-diante-de de-face-de חֲרֹן אַף׃');
INSERT INTO verses VALUES (19123, 24, 4, 27, 'porque disse yhwh yhwh devastação será todo não e-terminação não eu-farei');
INSERT INTO verses VALUES (19124, 24, 4, 28, 'sobre esta você-luto a-terra e-eles-escurecerão os-céus  de cima sobre porque eu-falei minha-ira e-não lamentei e-não retornarei de-elas');
INSERT INTO verses VALUES (19125, 24, 4, 29, 'de-audio ele-separou e-ele-exalta arco borachat- todo a-cidade vieram be-abim ve-bakefim al-u- todo a-cidade azubah- e-não-há habitante nelas homem');
INSERT INTO verses VALUES (19126, 24, 4, 30, 'שָׁד֜וּד que faça porque veste-te segundo porque adorna-te até ouro porque rasga no teu manto teus olhos em vão apresenta-te despreze em-te ogevim nafshekha buscarão');
INSERT INTO verses VALUES (19127, 24, 4, 31, 'que voz como-o-marejado ouvi dificuldade-a como-o-lacrimejante voz filha-de Zion elevará-se-a se-estenderá mãos-suas Ó! por-favor a-mim porque cansada-a alma-minha para-matar');
INSERT INTO chapters VALUES (750, 24, 5, 31);
INSERT INTO verses VALUES (19128, 24, 5, 1, 'andem nas-em-o-luzes Jerusalém e-vi por-favor e-sabem e-peguem-se nas-em-as-ruas-de-a se encontrem homem se haja fez juízo mevakesh emunah e-perdoarei a-ela');
INSERT INTO verses VALUES (19129, 24, 5, 2, 'e-se vive yhwh dirão por isso para a mentira jurarão');
INSERT INTO verses VALUES (19130, 24, 5, 3, 'yhwh olhos-teus não para-a-fidelidade bateu-ela eles e-não caíram-eles esgotaste-os de-se-recusarem tomar disciplina fortaleçam-vos faces-de-eles de-a-pedra de-odiam voltar;');
INSERT INTO verses VALUES (19131, 24, 5, 4, 'e-eu eu-disse somente eles eles que não não o-caminho-de yhwh yhwh juízo אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (19132, 24, 5, 5, 'não-eu-vou para-mim a os-grandes que a-eles porque o-caminho-de yhwh caminho yhwh juízo elohim-deles porém הֵ֤מָּה yachdav quebraram sobre se-separaram mostrando-se-rebelde');
INSERT INTO verses VALUES (19133, 24, 5, 6, 'sobre assim machem arieh-e mei-ar zeh-ev aravot yesheddem namer shoked sobre arehem todo que מֵהֵ֖נָּה yitref porque muitos de-seus-pequenos-pecados atsum');
INSERT INTO verses VALUES (19134, 24, 5, 7, 'onde para-isso para-ti os-teus-filhos abandonaram-me e-eles-juraram bəlō'' Elohim e-eu-jurei elas e-eles-se-irritaram e-casa-de זוֹנָ֖ה se-dividiram');
INSERT INTO verses VALUES (19135, 24, 5, 8, 'cavalos meyuzzaní machkím hayu homem a mulher-de seu-proximo Se alegrarão');
INSERT INTO verses VALUES (19136, 24, 5, 9, 'ha-al- estes não- e-f-qod oráculo-de yhwh não em-um que assim não vengar-se-á alma-de-mim');
INSERT INTO verses VALUES (19137, 24, 5, 10, 'subam em-suas-carneiras e-escaldem-no e-destruam a fazeis-vós levem-fora que porque não a-yhwh eles');
INSERT INTO verses VALUES (19138, 24, 5, 11, 'que pelos-vestidos vestiram-na em-mim casa Israel e-casa-de Judá oráculo-de yhwh');
INSERT INTO verses VALUES (19139, 24, 5, 12, 'kikhashu be-Yahweh e-disseram não ele e-não tavo aleinu maldade e espada e fome não nireh');
INSERT INTO verses VALUES (19140, 24, 5, 13, 've-hanviim serão na-brisa-de ve-hadibber não-há com-eles assim será-fazido a-eles');
INSERT INTO verses VALUES (19141, 24, 5, 14, 'portanto assim yhwh yhwh Elohim-de exércitos porque daberchem a a palavra esta eis-me deu divray bificha para-o-fogo e-o-povo este madeiras e-a-sua-comida');
INSERT INTO verses VALUES (19142, 24, 5, 15, 'eis-me de-trazer em-vocês nação de-longe casa Israel oráculo-de yhwh גוֹי forte ele nação de-sempre ele nação não você-saberá de-sua-língua e-não você-ouvirá que- יְדַבֵּֽר׃');
INSERT INTO verses VALUES (19143, 24, 5, 16, 'sua-lama como-o-túmulo aberto kulam giborim');
INSERT INTO verses VALUES (19144, 24, 5, 17, 'e-coma qtsir-ka e-o-pão-ka yochelu os-filhos-teus u-bnoteka ele-comes tsoneka u-vakareka comerá gafneka e-teu-afeição ele-esvaecerá cidades-de de-tus-fortalezas que tu confiando nelas pela-espada');
INSERT INTO verses VALUES (19145, 24, 5, 18, 'e-também nos dias esses oráculo-de yhwh não אעשה com-vocês completamente');
INSERT INTO verses VALUES (19146, 24, 5, 19, 'e-foi que תֹאמְר֔וּ debaixo o-que fez yhwh Elohim nosso para-nós a todo estes e-dirás a-eles como-que vos-deserdou me e-vocem-serve Elohim-de a-nacionalidade-alheia na-terra-de-voces assim sirvais não a-vós não para-vocês');
INSERT INTO verses VALUES (19147, 24, 5, 20, 'anuntem esta em-casa-de Jacó E proclamem-a Em Judá dizendo');
INSERT INTO verses VALUES (19148, 24, 5, 21, 'ouvi esta Isto povo Sensible e-não-há coração a-eles para-eles e-não verão a-eles a-eles e-não Ouvirão');
INSERT INTO verses VALUES (19149, 24, 5, 22, 'o-sinal-me não tirā''ū oráculo-de yhwh não mippanay não vocem-iniciaram que eu-postei areia fronteira para-o-mar lei- eternidade e-não ele-passara-lo e-eles-se-irritaram e-não poderão e-estragarão suas-ondas e-não passar-nos-os');
INSERT INTO verses VALUES (19150, 24, 5, 23, 'e-ao-povo este ser coração o rebelde e-instrutor saru veyelechu');
INSERT INTO verses VALUES (19151, 24, 5, 24, 'e-não disseram em-seus-corações terá-temor por-favor a yhwh nosso-Elohim dê chuva e-furacão em-seu-tempo jura-s חֻקּ֥וֹת colheu guarda- para-nós');
INSERT INTO verses VALUES (19152, 24, 5, 25, 'pecados-vos voltam- estes e-pecados-vos impedem o-bom de-vós');
INSERT INTO verses VALUES (19153, 24, 5, 26, 'porque foram-encontrados בְּעַמִּי os ímpios endireita-se como-saca lagartixas estabelecer-vos destruidor homens caçarão-eles');
INSERT INTO verses VALUES (19154, 24, 5, 27, 'como-couve enchei ave assim בָּתֵּיהֶ֖ם cheios-de מִרְמָה sobre assim grandes-se-tornaram e-enriqueceram-se');
INSERT INTO verses VALUES (19155, 24, 5, 28, 'engordaram-se fizeram-no também passaram palavras-de- mau julgamento não e-julgaram-se juízo יָתוֹם e-sucederam não os-pobres não julgaram-.');
INSERT INTO verses VALUES (19156, 24, 5, 29, 'por-causa-de-o estes não guardarei oráculo-de yhwh não em-um que assim não vengar-se-á alma-de-mim');
INSERT INTO verses VALUES (19157, 24, 5, 30, 'que e-encaracolaram tornou-se na-terra');
INSERT INTO verses VALUES (19158, 24, 5, 31, 'הַנְּבִיאִ֞ים profetizaram- em-falso e-os-sacerdotes pastorearão sobre mãos-deles e-o-seu-povo amarão assim umah- farão para-o-fim-dele');
INSERT INTO chapters VALUES (751, 24, 6, 30);
INSERT INTO verses VALUES (19159, 24, 6, 1, '[הָעִ֣זוּ] filhos-de Benjamim de-o-interior Jerusalém e-em-tekoa tiqueu shofar e-sobre casa o-vinhedo saeu masset que maldade niskapha מצפון ve-she-ver grande');
INSERT INTO verses VALUES (19160, 24, 6, 2, 'o-deserto e-o-ameunagah parei-me filha-de צִיּֽוֹן');
INSERT INTO verses VALUES (19161, 24, 6, 3, 'a-ela virão pastores e-os-seus-ganhos cravareis em-ela tendas ao-redor pastorearam homem a ידֽוֹ׃');
INSERT INTO verses VALUES (19162, 24, 6, 4, 'santificareis sobre-ela guerra levantem-se e-calçamos na-meio-dia אָוי֙ a-nós porque o-dia que porque estenderão sombra-de tarde');
INSERT INTO verses VALUES (19163, 24, 6, 5, 'levantem-se e-calçamos na-noite e-nos-devoraremos suas-cidadelas');
INSERT INTO verses VALUES (19164, 24, 6, 6, 'que assim disse yhwh exércitos cortem conselhos veshephakū sobre Jerusalém torre ela a-cidade deixou toda ela opressor na-sua-entre');
INSERT INTO verses VALUES (19165, 24, 6, 7, 'como-a-pedra de-a-sua-água assim elevou-a maldade-de-a violência e-roubo será-ouvido em-a sobre face-de תָּמִ֖יד doença e-machucado');
INSERT INTO verses VALUES (19166, 24, 6, 8, 'foi-removido-o Jerusalém para-que-não vociferou alma-minha -de-te para-que-não terra sem semear terra não noshava');
INSERT INTO verses VALUES (19167, 24, 6, 9, 'assim disse yhwh exércitos olel yeollu kagefen remanescente Israel hashav yadcha kvotser sobre salsilot');
INSERT INTO verses VALUES (19168, 24, 6, 10, 'sobre mi adabrah e-eu-jurarei eis behold não-circuncidado as suas orelhas e-não יֻכְלוּ eis eis ser a-eles foi não para-escarnecimento não יַחְפְּצוּ־ nele-verso');
INSERT INTO verses VALUES (19169, 24, 6, 11, 'e-את ira yhwh eu fui cheio eu fui enganado destruí derramai sobre injustiça no-exterior e-sobre segredo em jovens juntos porque também homem com mulher serão enganados velho com enchei dias');
INSERT INTO verses VALUES (19170, 24, 6, 12, 'e-eles-virarão as-casas-deles para-outros campos e-mulheres juntos porque até a a-terra sobre habitantes-de a-terra oráculo-de yhwh');
INSERT INTO verses VALUES (19171, 24, 6, 13, 'que dos pequenos e-até e dos grandes todos fabricante cortou e-propheta- e-até sacerdote todo-o fez enganho:');
INSERT INTO verses VALUES (19172, 24, 6, 14, 'e-curaram- a quebra meu-povo dizendo levada para-dizer paz- paz e-nao-ha paz');
INSERT INTO verses VALUES (19173, 24, 6, 15, 'hovishu que to''evah asu também bo''sh não não também hakelim não conheceram portanto yiphlu disse yhwh pakadtim yhwh disse yhwh');
INSERT INTO verses VALUES (19174, 24, 6, 16, 'assim disse yhwh im-du sobre de-rakhim u-re-u ve-shaal-u li-netivot eternidade qual isto caminho o-bom e-vão nela e-a-cheguem de-sono não e-disseram não iremos');
INSERT INTO verses VALUES (19175, 24, 6, 17, 'e-estabelecerei sobre-vós observando o-ouçam à-voz-de chifre e-disseram não nós-ouviremos');
INSERT INTO verses VALUES (19176, 24, 6, 18, 'portanto ouvi as-nações e-sabedoria assembléia a que em-eles');
INSERT INTO verses VALUES (19177, 24, 6, 19, 'ouça a-terra eis eu מֵבִ֥יא maldade a o-povo fruto fruto que porque não devarai não ouvam-se e-mi-minha-lei e-eles-amearam-se em-ela');
INSERT INTO verses VALUES (19178, 24, 6, 20, 'por-que este para-mim para-a-bálsamo de-o-vazio que-venha e-compre-ele o-bom da-terra a-partir-de-longe não não para a vontade e-vossos-sacrifícios não prepararam para-mim');
INSERT INTO verses VALUES (19179, 24, 6, 21, 'portanto assim disse yhwh eis-me deu a o-povo este en-trapos e-caíram neles pais e-filhos juntos morador e-seu-amigo');
INSERT INTO verses VALUES (19180, 24, 6, 22, 'assim disse yhwh eis povo veio da-terra do-norte e-povo grande ye''or mi-yarchei- terra');
INSERT INTO verses VALUES (19181, 24, 6, 23, 'קֶ֣שֶׁת e-kedon estabelecerão fértil ele e-não הִרְחִימוּ deles-a-voz como-o-mar gemerão e-sobre cavaleiros se-ajuntarão ordenado como-o-homem para-a-guerra sobre-ti filha-de צִיּֽוֹן');
INSERT INTO verses VALUES (19182, 24, 6, 24, 'ouvimos a seu-ouvido secaramos nossas-mãos angústia nos-apanhou tremeluzimos como-que-nascemos:');
INSERT INTO verses VALUES (19183, 24, 6, 25, 'a o-campo uvederekh a porque chēreb que espada misaviv');
INSERT INTO verses VALUES (19184, 24, 6, 26, 'filha-de povo-de-mim chigri- śāq vehitpallāshi bā''ēpher אֵבֶל para-ti עֲשׂוּ para-ti que תַּמְרֻרִים porque פִּתְאֹם virá הַשׁוֹדֵד sobre-nós');
INSERT INTO verses VALUES (19185, 24, 6, 27, 'בָּחֹן נְתַתִּיךָ בְּעַמִּי מִבְצָר וְתֵדָע וּבָחַנְתָּ֖ a דַּרְכָּֽם׃');
INSERT INTO verses VALUES (19186, 24, 6, 28, 'todos-os סָרֵ֣י סֽוֹרְרִ֔ים הֹלְכֵ֥י רָכִ֖יל נְחֹ֣שֶׁת e-ferro todos-eles מַשְׁחִיתִ֖ים eles');
INSERT INTO verses VALUES (19187, 24, 6, 29, 'נָחַ֣ר מַפֻּ֔חַ עֹפָ֑רֶת לַשָּׁוְא֙ צָרַ֣ף צָר֔וֹף וְרָעִ֖ים não נִתָּֽקוּ׃');
INSERT INTO verses VALUES (19188, 24, 6, 30, 'prata נִמְאָ֔ס קָרְא֖וּ a-eles porque yhwh yhwh neles');
INSERT INTO chapters VALUES (752, 24, 7, 34);
INSERT INTO verses VALUES (19189, 24, 7, 1, 'a-palavra que ser a Jeremias yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19190, 24, 7, 2, 'ficou-em-pé בְּשַׁ֙עַר֙ casa yhwh וְקָרָ֣אתָ nome a a palavra esta e dirijais ouvi palavra-de yhwh todo Judá os-que-vêm nas praças os-estes que para-יהוה');
INSERT INTO verses VALUES (19191, 24, 7, 3, 'assim yhwh yhwh dos-exércitos Elohim-de Israel façam bem vos caminhos e vossas obras e eu sussurrai vos no-lugar- a-esta');
INSERT INTO verses VALUES (19192, 24, 7, 4, 'a a-vós a-vós a dizendo a mentira yhwh e entraria yhwh o-santuário yhwh templo-de yhwh eles');
INSERT INTO verses VALUES (19193, 24, 7, 5, 'que se faça bem façam bem a דַּרְכֵיכֶם e-a מַעֲלְלֵיכֶם entre עָשׂוּ e-entre מִשְׁפָּט entre homem e-entre seu-amigo');
INSERT INTO verses VALUES (19194, 24, 7, 6, 'forasteiro יָתוֹם וְאַלְמָנָה não תַּעֲשׂוּקֶם וְדָם נָקִי a תִּשְׁפַּךְ בַּמָּק֣וֹם esta e-depois-de Elohim não não ireis a-vós para-vocês');
INSERT INTO verses VALUES (19195, 24, 7, 7, 'וְשִׁכַּנְתִּ֤י vos בַּמָּק֣וֹם esta na-a-terra que dei לַאֲבֽוֹתֵיכֶ֑ם de-o eternidade e-até eternidade');
INSERT INTO verses VALUES (19196, 24, 7, 8, 'eis vós בֹּטְחִ֣ים a-vós sobre palavras-de para-não para-não הוֹעִֽיל׃');
INSERT INTO verses VALUES (19197, 24, 7, 9, 'הֲגָנֹ֤ב ׀ רָצֹ֙חַ֙ וְהִשָּׁבֵ֥עַ לַשּׁ֖קֶר וְקַטֵּ֣ר לַבָּ֑עַל וְהָלֹ֗ךְ depois-de Elohim outros que não יְדַעְתֶּֽם׃');
INSERT INTO verses VALUES (19198, 24, 7, 10, 'וּבָאתֶ֞ם וַעֲמַדְתֶּ֣ם לְפָנַ֗י בַּבַּ֤יִת o-este que נִקְרָא־ שְׁמִ֣י sobre-ele e-disseis ניצלנו para-que עשות a todo התועבות as estas');
INSERT INTO verses VALUES (19199, 24, 7, 11, 'המע ara פריצים ser הבית este que נקרא- שמי também eu eis eu eis vi-eu oráculo-de yhwh');
INSERT INTO verses VALUES (19200, 24, 7, 12, 'que לכו- agora a מקום moi que בְּשִׁיל֔וֹ que שִׁכַּ֧נְתִּֽי שְׁמִ֛י nome בָּרִֽאשׁוֹנָ֑ה e-vi-deis a-ele de-diante-de עָשִׂ֣יתִי a-ele מִפְּנֵ֕י רָעַ֖ת povo-meu Israel');
INSERT INTO verses VALUES (19201, 24, 7, 13, 'e-agora יַ֧עַן עֲשׂוֹתְכֶ֛ם a todo הַמּֽ͏ַעֲשִׂ֥ים estes oráculo-de yhwh Eu falei vocês o-amanhecer e fale e-não ouvireis eu chamei vós e-não respondeu-vos');
INSERT INTO verses VALUES (19202, 24, 7, 14, 'e farei para o templo que será chamado o meu nome sobre-ele que vós בֹּטְחִ֣ים nele וְלַ֨מָּק֔וֹם que a-vós para-vocês וְלַאֲבֽוֹתֵיכֶ֑ם como-que fiz para ele');
INSERT INTO verses VALUES (19203, 24, 7, 15, 'וְהִשְׁלַכְתִּ֥י vos de-cima-de face-de como-que הִשְׁלַ֙כְתִּי֙ a todo אֲחֵיכֶ֔ם a todo semente Efrayim');
INSERT INTO verses VALUES (19204, 24, 7, 16, 'e-tu a תִּתְפַּלֵּ֣ל ׀ בְּעַד־ o-povo o-este e-a תִּשָׂ֧א para-o alegria e-oração e-a atingirá-te- em-mim porque ainenini ouviu te:');
INSERT INTO verses VALUES (19205, 24, 7, 17, 'ain-te viu que eles fazendo em-cidades-de Judá e-em-ladosas Jerusalém');
INSERT INTO verses VALUES (19206, 24, 7, 18, 'os-filhos colhem árvores וְהָֽאָבוֹת֙ מְבַעֲרִ֣ים a o-fogo e-as-mulheres לָשׁ֣וֹת בָּצֵ֑ק לַעֲשׂ֨וֹת כַּוָּנִ֜ים לִמְלֶ֣כֶת os-céus וְהַסֵּ֤ךְ נְסָכִים֙ para-Elohim outros para-que הַכְעִסֵֽנִי׃');
INSERT INTO verses VALUES (19207, 24, 7, 19, 'a-mi eles macheisim oráculo-de yhwh eles a-eles para-que em-baston em-seus-faces');
INSERT INTO verses VALUES (19208, 24, 7, 20, 'portanto assim disse- Adonai yhwh eis appi vachamathi nitchet a o-lugar esta sobre o-homem e-sobre a-animal a-terra árvore o-campo e-sobre fruto a-terra uva''arah e-não tikbeh');
INSERT INTO verses VALUES (19209, 24, 7, 21, 'assim disse yhwh de-exércitos Elohim-de Israel oloteichem safu sobre zivcheichem e comessem carne;');
INSERT INTO verses VALUES (19210, 24, 7, 22, 'que não falei a pais-vosso e-não mandamentos; em-dia-de eles da-terra Egito sobre palavras-de holocausto; e sacrificassem;');
INSERT INTO verses VALUES (19211, 24, 7, 23, 'que se a a-coisa isto é dizendo os para-dizer ouvi a-vós e eu ser-me-ia para-vocês para-Elohim e-vós serão- a-mim povo; e se vós marchardes em-todo o-caminho que a-vós a-vós para-o-fim-de seja-bom para-vocês');
INSERT INTO verses VALUES (19212, 24, 7, 24, 'e-não ouviram e-não levantai a as suas orelhas e-andaram em seus conselhos em sua trepidação seus corações o mal e-foram para trás e-não para-frente-versículo-final');
INSERT INTO verses VALUES (19213, 24, 7, 25, 'de-o o-dia que sairam pais-vosso da-terra até o-dia o-dia esta e-enviei a vós a dia de-meu-escravo os-profetas dia acordai-vos e envio');
INSERT INTO verses VALUES (19214, 24, 7, 26, 'não ouviram a-mim e-não levantaram a seus ouvidos e esforçaram a suas barbas choraram dos seus pais');
INSERT INTO verses VALUES (19215, 24, 7, 27, 'e falarás a-eles a todo as-palavras os-estes e-não ouvirão a-ti e-lerás a-eles e-não responder-te-ão:');
INSERT INTO verses VALUES (19216, 24, 7, 28, 'e-dirás a-eles este o-nacional que não ouvirem yhwh yhwh de-seus-Elohimes e-não tomaram disciplina perder-se-á a-fidelidade e-ser-lhes-irá-cortada de-suas-bocas:');
INSERT INTO verses VALUES (19217, 24, 7, 29, 'fino o-sacrifício e-lances-o e-seia sobre as-spais que porque yhwh yhwh e-veitó a dor ebraoth');
INSERT INTO verses VALUES (19218, 24, 7, 30, 'porque fizeram filhos-de Judá o-mal em-olhos-meus Dize: yhwh colocaram seus-escarmentos no-casa que foi- chamado- o meu nome sobre-ele - para ser sujo,');
INSERT INTO verses VALUES (19219, 24, 7, 31, '- e construíram, nas cavernas da Topheth que no vale filho-de de Hinom para queimar a filhos-deles e-a não no-fogo que não eu ordenei e-não ascendeu sobre no meu coração:');
INSERT INTO verses VALUES (19220, 24, 7, 32, 'portanto eis-a dias os-vindo oráculo-de yhwh e-não será dito ainda que e vale filho-de de Hinom porque se lugar matou e sepultaram-no em um tamboril de-onde neste lugar:');
INSERT INTO verses VALUES (19221, 24, 7, 33, 'e será נבלת o-povo este para-alimento לעוף os-céus ולבהמה a-terra e-não-há מחרד׃');
INSERT INTO verses VALUES (19222, 24, 7, 34, 'והשבתי ׀ מערי Judá ומחוצות Jerusalém voz voz e-voz שמחה voz voz e-voz כלlah porque que será a-terra');
INSERT INTO chapters VALUES (753, 24, 8, 23);
INSERT INTO verses VALUES (19223, 24, 8, 1, 'em-o-tempo היה oráculo-de yhwh a suas próprias reis- יְהוּדָה e-a suas próprias- seus príncipes- e-a suas próprias os-sacerdotes e-את suas próprias os profetas e-a suas próprias moradores- Jerusalém de-seus-múrtiers');
INSERT INTO verses VALUES (19224, 24, 8, 2, 'e-escavá-los para-o-sol e-para-a-lua e-para-todo exército-de os-céus que amá-los e-que servi-los e-que caminharam depois-deles e-que buscá-los e-que e-adora-los para-eles a-eles não e-não serão sepultados por causa de sobre face-de a-terra serão');
INSERT INTO verses VALUES (19225, 24, 8, 3, 'e escolhido morte dos vivos a-todo a sobrevivente os sobreviventes de a cabana a má esta em-todo os lugares os sobreviventes que הידחhtarim yhwh oráculo-de yhwh exércitos');
INSERT INTO verses VALUES (19226, 24, 8, 4, 'e-dirás a-eles assim disse yhwh הייפלו e-não יתקוום se ישוב e-não ישוב׃');
INSERT INTO verses VALUES (19227, 24, 8, 5, 'מדוע שobbava o-povo este Jerusalém משובה ניצחת repararam בתתרכות de-se-recusarem voltar;');
INSERT INTO verses VALUES (19228, 24, 8, 6, 'escuta-te e ouvi não- assim dirão-eles não-há homem consolado dizendo seu mal para-dizer que faça todo retornou cavalo bebedor na-guerra');
INSERT INTO verses VALUES (19229, 24, 8, 7, 'também חסידה בשמיים ידענה موעדהיה وتر שמרו a tempo באונה ואמי não não a משפט yhwh');
INSERT INTO verses VALUES (19230, 24, 8, 8, 'איך תֹֽאמְרוּ sábios nós וְתוֹרַ֥ת yhwh אִתָּ֑נוּ certamente eis לַשֶׁ֣קֶר fez עֵ֖ט שֶׁ֥קֶר סֹפְרִֽים׃');
INSERT INTO verses VALUES (19231, 24, 8, 9, 'הֹבִ֣ישׁוּ חֲכָמִ֔ים חַ֖תּוּ e os enganaram eis por palavra de yhwh rejeitaram a-eles que para-eles');
INSERT INTO verses VALUES (19232, 24, 8, 10, 'por-isto dar-lhes-ei a suas mulheres aos outros seus campos que porque de pequeno e-até grande até a totalidade fazendo בָּצַע מִנָּבִיא֙ e-até sacerdote até a totalidade fez שָּֽׁקֶר׃');
INSERT INTO verses VALUES (19233, 24, 8, 11, 'וַיְרַפּ֞וּ a שֶׁ֤בֶר filha-de dizendo sobre נְקַלָּ֔ה para-dizer שָׁל֣וֹם ׀ שָׁל֑וֹם e-não-há paz');
INSERT INTO verses VALUES (19234, 24, 8, 12, 'הֹבִ֕שׁוּ que to''evá asú também boš não não ve-hikkalem não sabem-eles portanto yiphlu bannoflíym be''et disse yhwh disse yhwh');
INSERT INTO verses VALUES (19235, 24, 8, 13, 'ásaf ăsifem oráculo-de yhwh ein u''nav''im ''baggefen ve''ein te''anim ''bat-te''enah ve-he''aleh nave''l a-eles a-eles ya''avrum:');
INSERT INTO verses VALUES (19236, 24, 8, 14, 'sobre ma'' nós yoshvim האספוּ וְנָבוֹא a cidades-de que yhwh nome porque yhwh Elohim que וַיָּשֶׂם֩נוּ מֵי־ cabeça porque pecamos para-יהוה');
INSERT INTO verses VALUES (19237, 24, 8, 15, 'קַוֵּ֥ה לְשָׁל֖וֹם e-não-há bom לְעֵ֥ת מַרְפֵּ֖ה e-eis בְעָתָֽה׃');
INSERT INTO verses VALUES (19238, 24, 8, 16, 'מִדָּן נִשְׁמַע נַחְרַת סוּסָיו מִקֹּל מִצְחֲלוֹת אַבִירָיו רָעֲשָה todo a-terra וַיָּבוֹאוּ terra terra וּמְלֹאתָהּ cidade וְיֹ֥שְׁבֵי em-ela');
INSERT INTO verses VALUES (19239, 24, 8, 17, 'que eis-me מְשַׁלֵּ֜חַ בָּכֶ֗ם נְחָשִׁים֙ צִפְעֹנִ֔ים que não-há a-eles לָ֑חַשׁ וְנִשְּׁכ֥וּ vos oráculo-de yhwh');
INSERT INTO verses VALUES (19240, 24, 8, 18, 'מַבְלִ֥יגִיתִ֖י sobre יָג֑וֹן sobre-mim לִבִּ֥י داוָֻי׃');
INSERT INTO verses VALUES (19241, 24, 8, 19, 'eis-que- קוֹל שׁוַעַת filha-de עַמּי מֵאֶרֶץ מַרְחַקִּים הַיְהוָה não-há בְּצִיּון se מַלְכָּהּ não-há nela madua'' הִכְעִיסֻנִי nos seus labirintos em suas divisões estranho:');
INSERT INTO verses VALUES (19242, 24, 8, 20, 'passou colheu terminou no verão e nós não nos movemos:');
INSERT INTO verses VALUES (19243, 24, 8, 21, 'sobre grão filha-de povo-meu quebraste envergonhaste como me fortaleceste');
INSERT INTO verses VALUES (19244, 24, 8, 22, 'o teu aperto não-há em Gileade se médico não-há que porque não não ascendeu longa filha-de povo-meu');
INSERT INTO verses VALUES (19245, 24, 8, 23, 'quem dará águas águas e os meus olhos fonte דִּמְעָ֑ה וְאֶבְכֶּה֙ dia e-noite a חַֽלְלֵ֥י filha-de povo-meu');
INSERT INTO chapters VALUES (754, 24, 9, 25);
INSERT INTO verses VALUES (19246, 24, 9, 1, 'quem יִתְּנֵ֣נִי בַמִּדְבָּ֗ר מְלוֹן֙ אֹֽרְחִ֔ים וְאֶֽעֶזְבָה֙ a povo-meu que de-com-eles porque todos-eles מְנָ֣אֲפִ֔ים עֲצֶ֖רֶת המפרים׃');
INSERT INTO verses VALUES (19247, 24, 9, 2, 'וַיֵּלְכוּ a בשפתם קשתם mentira e-não  tobah na-terra que porque מFROM רעה a רעה יצאו ואיתי não ידעו oráculo-de yhwh');
INSERT INTO verses VALUES (19248, 24, 9, 3, 'homem de-sua-reação e-eles-serão-protegidos e-sobre todo que a e-ele-terá-confiança porque todo irmão aquele-que-supera-pela-costa Jacó e-todo mau maligno irá');
INSERT INTO verses VALUES (19249, 24, 9, 4, 'e-homem em-sua-reação e-eles-serão-enganados e-verdade não יְדַבְּרֻ לִמְדוּ לְשׁוֹנוֹ diga- שֶׁׁקֶר הַעָוְהֻ נִלְאוּ׃');
INSERT INTO verses VALUES (19250, 24, 9, 5, 'שִׁיבְתֶּךָ֖ no-meio-de מִרְמָה בְּמִרְמָה מֵאֲנוּ דַֽעַת־ אוֹתִ֖י oráculo-de yhwh');
INSERT INTO verses VALUES (19251, 24, 9, 6, 'portanto assim disse yhwh exércitos eis-me צוֹרְפָ֖ם וּבְחַנְתִּ֑ים porque como de-diante-de de-face-de filha-de povo-meu');
INSERT INTO verses VALUES (19252, 24, 9, 7, 'חֵ֥ץ לְשׁוֹנָ֖ם מִרְמָ֣ה palavra בְּפִ֗יו שָׁל֤וֹם a seu-amigo יְדַבֵּ֔ר e-em põe-se quatro');
INSERT INTO verses VALUES (19253, 24, 9, 8, 'o-al estes não examinará com-eles oráculo-de não mãe em-um que assim não vengar-se-á alma-de-mim');
INSERT INTO verses VALUES (19254, 24, 9, 9, 'sobre as-montanhas levarei PORQUÉ E-FOI e-sobre SINAIS que CÂMARA porque ESTÃO-SE-POSTANDO SEM homem voz e-não ouviram voz-de COMPRAS AVE os-céus e-até animal VAGAROSAMENTE-SE-MOVIMENTARAM CAMINHARAM:');
INSERT INTO verses VALUES (19255, 24, 9, 10, 'e eu darei a Jerusalém para pilhas morada tânis e-a arei יְהוּדָה darei seu nome sem morador:');
INSERT INTO verses VALUES (19256, 24, 9, 11, 'quem o-homem o sábio וְיָבֵ֣ן a Isto e-que a-ele boca-de yhwh a-ele a-terra sobre ma'' אָבְדָ֣ה a-terra נִצְּתָ֥ה כַמִּדְבּ֖ר עֹבֵֽר׃');
INSERT INTO verses VALUES (19257, 24, 9, 12, 'E-disse yhwh sobre עָזְבָם֙ a dei que dei em-frente-de-eles e-não שָׁמְע֥וּ בְקוֹלִ֖י e-não הָלְכוּ em-ela');
INSERT INTO verses VALUES (19258, 24, 9, 13, 'וַיֵּ֣לְכ֔וּ atrás-de שְׁרִר֣וּת coracoes-eles וְאַחֲרֵי֙ הַבְּעָלִ֔ים que לִמְּד֖וּם avos-eus');
INSERT INTO verses VALUES (19259, 24, 9, 14, 'portanto assim yhwh yhwh dos-exércitos Elohim-de Israel eis-me מַאֲכִילָ֛ם a o-povo este לַֽעֲנָ֑ה וְהִשְׁקִיתִ֖ים e-sejam cabeça');
INSERT INTO verses VALUES (19260, 24, 9, 15, 'וַהֲפִֽצוֹתִים֙ entre-as-nações que não יָדְע֔וּ eles וַֽאֲבוֹתָ֑ם וְשִׁלַּחְתִּ֤י אַֽחֲרֵיהֶם֙ a até até כַּלּוֹתִ֖י a-eles');
INSERT INTO verses VALUES (19261, 24, 9, 16, 'assim disse yhwh exércitos הִתְבּֽוֹנְנ֛וּ וְקִרְא֥וּ לַמְקוֹנְנ֖וֹת וּתְבוֹאֶ֑ינָה e-a הַחֲכָמ֥וֹת שָׁלְחוּ וַתָּבוֹא');
INSERT INTO verses VALUES (19262, 24, 9, 17, 'וַתְּמַהֵר וַתִּשְׁנָה sobre nós נֵהַי וַתֵּרָד עֵינֵי֙נוּ דִּמְעַה וַעֲפַפֵּינּוּ יִזָּלֻהוּ־ águas');
INSERT INTO verses VALUES (19263, 24, 9, 18, 'que voz נְהִי foi-ouvido מִצִיּ֖וֹן como שֻׁדָּ֑דְנוּ בֹּ֤שְׁנֽוּ muito porque עָזַ֣בְנוּ que porque הִשְׁלִ֖יכוּ מִשְׁכְּנוֹתֵֽינוּ׃');
INSERT INTO verses VALUES (19264, 24, 9, 19, 'porque שְׁמַ֤עְנָה mulheres palavra-de yhwh וְתִקַּ֥ח אָזְנְכֶ֖ם palavra-de seu-boca e-nos-ensinar filhas-vossas seja e-mulher sua-mulher lamento:');
INSERT INTO verses VALUES (19265, 24, 9, 20, 'porque subiu morte em-nossos-janelas veio em-nossas-cortinas para-cortar עולאל מחוץ בחורים מרחבות׃');
INSERT INTO verses VALUES (19266, 24, 9, 21, 'palavra assim oráculo-de yhwh ונפלבה o-homem o-homem כדמן sobre face-de o-campo וכעמר de-após הקצר e-não-há מאסף׃');
INSERT INTO verses VALUES (19267, 24, 9, 22, 'assim disse disse yhwh יתהלל חָכָם בְּחָכְמָת֔וֹ e-a יִתְהַלֵּ֥ל הַגִּבּ֖וֹר בִּגְבֽוּרָת֑וֹ a יִתְהַלֵּ֥ל rico בְּעָשְׁרֽוֹ׃');
INSERT INTO verses VALUES (19268, 24, 9, 23, 'que se בְּזֹ֞את יִתְהַלֵּ֣ל הַמִּתְהַלֵּ֗ל הַשְׂכֵּל֮ וְיָדֹ֣עַ que porque yhwh yhwh fez חֶ֛סֶד mishpat u-tsedakah em-a-terra porque בְאֵ֥לֶּה חָפַ֖צְתִּי oráculo-de yhwh');
INSERT INTO verses VALUES (19269, 24, 9, 24, 'eis dias vêm oráculo-de yhwh וּפָ֣קַדְתִּ֔י sobre todo de-frente בְּעָרְלָֽה׃');
INSERT INTO verses VALUES (19270, 24, 9, 25, 'sobre מִצְרַ֣יִם e-sobre Judá e-sobre אֱד֞וֹם e-sobre filhos-de עַמּוֹן֙ e-sobre Moabe que todo קְצוּצֵ֣י פֵאָ֔ה os-habitantes no-deserto porque todo as-nações עֲרֵלִ֔ים e-todo casa Israel עַרְלֵי־ coração');
INSERT INTO chapters VALUES (755, 24, 10, 25);
INSERT INTO verses VALUES (19271, 24, 10, 1, 'ouvi a a-palavra que yhwh yhwh sobre-vós casa Israel');
INSERT INTO verses VALUES (19272, 24, 10, 2, 'assim disse disse yhwh caminho as-nações a תִּלְמָ֔דוּ וּמֵאֹת֥וֹת os-céus a תֵּחָ֑תּוּ porque יֵחַ֥תּוּ ha-goyim מֵהֵֽמָּה׃');
INSERT INTO verses VALUES (19273, 24, 10, 3, 'porque חֻקּ֥וֹת os- povos ele ele porque madeira do- corte cortou-o obra-de mãos- artífice por-si-mesmo;');
INSERT INTO verses VALUES (19274, 24, 10, 4, 'com-prata e-com-ouro será- belo-o por-medisso e-por-cedro fortalecerão-os e não seja feito');
INSERT INTO verses VALUES (19275, 24, 10, 5, 'como palmeira de jardim eles e-não dirão-eles que levem serão levados que não caminharão a temam deles porque não alegrar-se-ão e-também será bom não a-eles');
INSERT INTO verses VALUES (19276, 24, 10, 6, 'sem como-te yhwh grande tu e-grande o-teu-nome em-força:');
INSERT INTO verses VALUES (19277, 24, 10, 7, 'quem não temer-te-irá rei as-nações que a-ti virá-a que em-todo sabedoria as-nações e-em-todo seu-reino de-o como-você');
INSERT INTO verses VALUES (19278, 24, 10, 8, 'e-numa que-arderão e-escarnecerão מוסר הבלים árvore ele');
INSERT INTO verses VALUES (19279, 24, 10, 9, 'prata מרוקע MITARRISH יובא וזהב מעופז obra-de artífice VIDEI צורף תכלת וארגמן לבושם obra-de חכמים כלם׃');
INSERT INTO verses VALUES (19280, 24, 10, 10, 'והוה Elohim אמת ele vida חיים eternidade eternidade מקיצפו a-terra a-terra e-não יכלו גויים  זעם׃');
INSERT INTO verses VALUES (19281, 24, 10, 11, 'כידנה֙ תאמרון להום אלhayא que שמיא וארקא não עבדוּ יהבדוּ de-a-רָא e-de Estas o céu estes');
INSERT INTO verses VALUES (19282, 24, 10, 12, 'fez terra por-seu-cוֹח֔וֹ de-ca-ינ a-tֵבֵ֖ל por-su-s חָכְמָת֑וֹ e-por-su-s תְּבוּנָת֖וֹ deixa-נָטָ֥ה céus');
INSERT INTO verses VALUES (19283, 24, 10, 13, 'à-voz-de a-tִּתּ֜וֹ multidão águas em-os-céus e-elevou-וַיַּעֲלֶ֥ה levantados-nְשִׂאִ֖ים do-extremo brâkim lamatár fez vayotze espírito me''otzrotáv');
INSERT INTO verses VALUES (19284, 24, 10, 14, 'nibár todo homem midádat hobísh todo que mipásel porque šéker niscó e-não espírito em-eles');
INSERT INTO verses VALUES (19285, 24, 10, 15, 'הֶבֶל eles obra-de תַּעְתֻּעִ֑ים בְּעֵ֥ת פְּקֻדָּתָ֖ם יֹאבֵֽדוּ׃');
INSERT INTO verses VALUES (19286, 24, 10, 16, 'não כְאֵ֜לֶּה חֵ֣לֶק Jacó porque ele o-tudo ele וְיִ֨שְׂרָאֵ֔ל yhwh נַֽחֲלָת֑וֹ yhwh de-exércitos nome-dele');
INSERT INTO verses VALUES (19287, 24, 10, 17, 'אִסְפִּ֥י מֵאֶ֖רֶץ כּוֹנְעַתֵ֑ךְ בְּמָצֽוֹר׃');
INSERT INTO verses VALUES (19288, 24, 10, 18, 'porque disse yhwh yhwh eis-me קֹלֶה֔וּ a-terra habitantes-de a-terra na-vez a-eles וָחֲצֵר֣וֹתִי a-eles para יִמְצָֽאוּ׃');
INSERT INTO verses VALUES (19289, 24, 10, 19, 'אָוי֙ a-mim sobre שֵׁבֶר֙ נַחֲלָה מַכָּתִ֑י e-eu eu-disse somente este חֹלִ֖י e-ashšā''nu:');
INSERT INTO verses VALUES (19290, 24, 10, 20, 'ahōli shuddāḏ e-todo meytāray nittāqu filhos-de yetsā''unī ve''ēnām não-há noṭeh ainda ahōli ūmekīm  YEIRIOUTAY:');
INSERT INTO verses VALUES (19291, 24, 10, 21, 'que  NIBAARU''  HA''REI''IM e-a não não  DARSHU'' não assim não  HISHCHILU'' e-todo  MAR''ITAM  NAFOTZAH:');
INSERT INTO verses VALUES (19292, 24, 10, 22, 'voz  SHMOOAH'' eis  BA''AH''  VE''REISH grande da-terra norte para a arei יְהוּדָה seu nome morada tubarões;');
INSERT INTO verses VALUES (19293, 24, 10, 23, 'eu-sei yhwh que não para o caminho dele não a homem-de andou e preparar a seu passo;');
INSERT INTO verses VALUES (19294, 24, 10, 24, 'corriga-me yhwh somente em justiça a em-teu-aspero para-que-não -te-mitenei');
INSERT INTO verses VALUES (19295, 24, 10, 25, 'despeça tua-ira sobre as-nações que não teu-poder e-sobre murmúrios não em-teu-nome não -cham-lhe porque comeram a Jacó e-comessem-no e o fez cessar e-a e o abateu e destruíram');
INSERT INTO chapters VALUES (756, 24, 11, 23);
INSERT INTO verses VALUES (19296, 24, 11, 1, 'a-palavra que ser a Jeremias yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19297, 24, 11, 2, 'ouvireis a palavras-de a aliança esta e falareis dela a homem Judá e-sobre habitantes-de Jerusalém');
INSERT INTO verses VALUES (19298, 24, 11, 3, 'e-dirás a-eles assim yhwh yhwh Elohim-de maldito maldito o-homem não não ouvirá a palavras-de a aliança a esta');
INSERT INTO verses VALUES (19299, 24, 11, 4, 'que ordenei a os vossos pais em-dia-de הוֹצִיאִי e-os de-a-terra-de dizendo מִכּוּר הַבַּרְזֶל dizendo ouvi בְקוֹלִי וַעֲשׂיתֶם a-eles e-sereis que אֲצַוּה a-vós וִהְיִתֶם a-vós para-povo וְאָנֹכִי estarei para-vocês para-elohim');
INSERT INTO verses VALUES (19300, 24, 11, 5, 'a-fim-de הָקִים a הַשְׁבוּעָה que nishebatti a-eles terra para-eles terra fluindo-de chalab u''dvash kayom esta va''anan e-disse yhwh yhwh');
INSERT INTO verses VALUES (19301, 24, 11, 6, 'E-disse yhwh a-mim chamou a todo hadavarim estes em-cidades-de Judá dizendo Jerusalém dizendo shime''u a palavras-de a aliança a-esta e-fizerdes a-eles');
INSERT INTO verses VALUES (19302, 24, 11, 7, 'que ha''ed ha''ido''ti nos vossos pais em-dia eu levantei a-eles da terra Mitzrayim e-até o-dia este acordai-vos dizendo dizendo ouvi na-voz-meu');
INSERT INTO verses VALUES (19303, 24, 11, 8, 'e-não ouviram e-não e estenderam a as suas orelhas e caminharam homem em tremer no seu coração o mal e trago sobre-eles a todo palavras do-pacto- esta que mandei-eu para-fazer e-não fizeram');
INSERT INTO verses VALUES (19304, 24, 11, 9, 'E-disse yhwh a-mim foi-encontrado- ligação em-cada-homem Judá e-em-cada Jerusalém');
INSERT INTO verses VALUES (19305, 24, 11, 10, 'voltaram sobre iniquidades אבותם הראשונים que מענו  לשמוע a דברי e-eles andaram depois-de Elohim outros לעבדם הפרו casa-de Israel e-Beit Judá a בריתי que כרתי a avos-eus');
INSERT INTO verses VALUES (19306, 24, 11, 11, 'portanto assim disse yhwh eis-me מביא a-eles maldade que não יֻכְלוּ לָצֵא מִמֶּנָּה וּזְעַקוּ a-mim e-não אֵשְׁמַע para-eles');
INSERT INTO verses VALUES (19307, 24, 11, 12, 'וַהֲלִכוּ cidades-de Judá וְיֹשְׁבֵי Jerusalém וּזְעַקוּ a Elohim eles eles a-eles a-eles וְהוֹשֵׁעַ a-eles יֹשִׁיעוּ a-eles בְּעֵ֥ת רָעָתָֽם׃');
INSERT INTO verses VALUES (19308, 24, 11, 13, 'que número עָרֶ֔יךָ foram teu-Elohim Judá וּמִסְפַּ֞ר חֻצ֣וֹת Jerusalém שַׂמְתֶּ֤ם מִזְבְּחוֹת֙ לַבֹּ֔שֶׁת מִזְבְּח֖וֹת לְקַטֵּ֥ר לַבָּֽעַל׃');
INSERT INTO verses VALUES (19309, 24, 11, 14, 'e-tu a תִּתְפַּלֵּל֙ בְּעַד־ o-povo este e-a תִּשָּׂ֥א que רִנָּ֣ה וּתְפִלָּ֑ה porque אֵינֶ֣נִּי ouviu בְּעֵ֛ת קָרְאָ֥ם para-mim por-causa-de רָעָתָֽם׃');
INSERT INTO verses VALUES (19310, 24, 11, 15, 'que lididi b''vayti asotah hamzimat haravim uvasar- santidade ya''avoru que porque ra''ateki az ta''alazi:');
INSERT INTO verses VALUES (19311, 24, 11, 16, 'zayit ראַעֲנָן יְפֵה fruto-de chamou yhwh yhwh à-voz-de לְקוֹל הֲמוּלָה גְדֹלָה acendeu fogo sobre-ela וְרָע֖וּ דָּלִיּוֹתָיו׃');
INSERT INTO verses VALUES (19312, 24, 11, 17, 'e-יהוה exércitos הַנּוֹטֵעַ a-ti palavra sobre-ti maldade בִּגְלַל רעה casa-de Israel e-Beit Judá que a-eles a-eles para me irritar para queimar para Baal:');
INSERT INTO verses VALUES (19313, 24, 11, 18, 'e-יהוה informa-me e eu soube então mostra-me seus pecados:');
INSERT INTO verses VALUES (19314, 24, 11, 19, 'e-eu como cordeiro ou carneiro יוּבַ֣ל לִטְב֑וֹחַ e-não יָדַ֜עְתִּי porque עָלַ֣י ׀ חָשְׁב֣וּ מַחֲשָׁב֗וֹת árvore עֵ֤ץ בְּלַחְמוֹ֙ וְנִכְרְתֶ֙נּוּ֙ vida viventes e-nome-dele não יִזָּכֵ֥ר ainda');
INSERT INTO verses VALUES (19315, 24, 11, 20, 'והוה exércitos שופט justiça בוחן כליות ולב אראה נקמתך de-eles que a-ti גיליתי a ריבי׃');
INSERT INTO verses VALUES (19316, 24, 11, 21, 'portanto assim yhwh yhwh sobre homens-de Anatote dizendo não alma-tua dizendo yhwh تينבאה no-nome-de yhwh e-não tamat b''yadenu:');
INSERT INTO verses VALUES (19317, 24, 11, 22, 'portanto assim disse yhwh exércitos eis-me poked sobre-eles habbachurim yamatu b''cherev os-filhos-deles uvnoteyhem yamatu bar''ava:');
INSERT INTO verses VALUES (19318, 24, 11, 23, 'u''se''erit não será a-eles porque levarei maldade a homens-de עֲנָת֖וֹת ano-de seus-assuntos;');
INSERT INTO chapters VALUES (757, 24, 12, 17);
INSERT INTO verses VALUES (19319, 24, 12, 1, 'justo tu yhwh que negociarei a-ti entretanto juízos; falar-ei você madua'' o-caminho-de perversos; enganador e-enganaram todo המַבְגִּידִים הבָּגֶד׃');
INSERT INTO verses VALUES (19320, 24, 12, 2, 'נטַעְתָּם֙ também שֹׁרָ֔שׁוּ eiremos também עָשׂוּ tu קָר֤וֹב tu בְּפִיהֶ֔ם וְרָח֖וֹק מִכִּלְיוֹתֵיהֶֽם׃');
INSERT INTO verses VALUES (19321, 24, 12, 3, 'e-tu yhwh יְדַעְתָּ֔נִי תִּרְאֵ֕נִי וּבָחַנְתָּ֥ לִבִּ֖י contigo הַתִּקֵם֙ כְּצֹ֣אן לְטִבְחָ֔ה וְהַקְדִּשֵׁ֖ם לְי֥וֹם הֲרֵגָֽה׃');
INSERT INTO verses VALUES (19322, 24, 12, 4, 'até quando a-terra a-terra וְעֵ֥שֶׂב todo o-campo ס㎜ssh מ-א-עַת י-וֹשְׁבֵי- ב-הּ que ב-הֵמֹות֙ não porque disseram não verá a א-חֲרִיתֵנוּ׃');
INSERT INTO verses VALUES (19323, 24, 12, 5, 'que a ר-גְלִים ׀ ר-צְתָּה֙ ו-יַלְא֔וּךָ ו-אֵ֥יךְ תְּתַֽחֲרֶ֖ה a הַסּוּסִ֑ים וּבְאֶ֤רֶץ tu tu בוֹטֵ֔חַ ו-אֵ֥יךְ vós-fará בִּגְא֥וֹן o-Jordão');
INSERT INTO verses VALUES (19324, 24, 12, 6, 'que também אַחֶ֣יךָ e-casa-de pai-de-ti também eles enganaram em-você também elas chamaram depois de ti enchei a confiarem contra-eles porque falarão a-ti Tovot:');
INSERT INTO verses VALUES (19325, 24, 12, 7, 'Azavti: a em-o-casa Natashti: dei Nachalati: eu dei a Yedidut: alma-minha Bekaf: Oyveha:');
INSERT INTO verses VALUES (19326, 24, 12, 8, 'estava para-mim Nachalati: כְּאַרְיֵ֣ה deu Natanah: sobre-mim Bekolah: sobre assim seu-odio');
INSERT INTO verses VALUES (19327, 24, 12, 9, 'o-palhaço colorido minha-herança a-mim o-palhaço ao redor sobre-ela vinde reuni-se todo vivente-de o-campo para-alimento para-comida');
INSERT INTO verses VALUES (19328, 24, 12, 10, 'רֹעִ֤ים רַבִּים corromperam meu-terreno invadiram a minha-partilha נָתְנ֛וּ a campo-de חֶמְדָּתִ֖י לְמִדְבַּ֥ר vazio∶');
INSERT INTO verses VALUES (19329, 24, 12, 11, 'שָׂמָה֙ לִשְׁמָמָ֔ה אָבְלָ֥ה sobre-mim שְׁמֵמָ֑ה נָשַׁ֙מָּה֙ todo que porque não-há homem nome sobre coração');
INSERT INTO verses VALUES (19330, 24, 12, 12, 'sobre todo שְׁפָיִ֣ם no-deserto que espada porque חֶ֤רֶב a-yhwh אֹכְלָה a-terra terra e-até fim a-terra não paz para-todo carne');
INSERT INTO verses VALUES (19331, 24, 12, 13, 'זָרְע֤וּ trigo-s וְקֹצִ֣ים קָצָ֔רוּ נֶחְל֖וּ não יוֹעִ֑לוּ וּבֹ֙שׁוּ֙ e a mim מֵחֲר֖וֹן também yhwh');
INSERT INTO verses VALUES (19332, 24, 12, 14, 'assim disse disse yhwh todo שְׁכֵנַי֙ os maus aqueles que tocam em herança que eu lhes dei a povo-meu de-cima-de Israel eis-me eles habitavam de-sobre sua terra e-a casa יְהוּדָה eu os perdoei deles');
INSERT INTO verses VALUES (19333, 24, 12, 15, 'e-foi atrás-de e eu me habituei a-eles אָשׁוּב e os abençoei וַהֲשִׁבֹתִ֛ים homem para-herança-sua e-homem לְאַרְצֽוֹ׃');
INSERT INTO verses VALUES (19334, 24, 12, 16, 'e-será se לָמֹ֣ד יִלְמְדוּ֩ a דַּֽרְכֵ֨י עמי לְהִשָּׁבֵ֤עַ בִּשְׁמִי֙ vive yhwh como לִמְּדוּ֙ a no-meio-de לְהִשָּׁבֵ֖עַ בַּבָּ֑עַל e seriam edificados em-meio-de povo-meu');
INSERT INTO verses VALUES (19335, 24, 12, 17, 'e se não  יִשְׁמָ֑עוּ  e deixasse a o-povo a-esse deixaria e destruísse oráculo-de yhwh');
INSERT INTO chapters VALUES (758, 24, 13, 27);
INSERT INTO verses VALUES (19336, 24, 13, 1, 'assim yhwh yhwh a-mim הָל֞וֹךְ e comprasses para-ti cinto roupas e o vestisseste sobre não e no rio não תְבִאֵֽהוּ׃');
INSERT INTO verses VALUES (19337, 24, 13, 2, 'e adquiri a o cinto yhwh yhwh e pus sobre minha cintura');
INSERT INTO verses VALUES (19338, 24, 13, 3, 'e-houve palavra-de yhwh a-mim dizendo para-dizer');
INSERT INTO verses VALUES (19339, 24, 13, 4, 'toma a o cinto que você adquiriu que sobre seu cinto e levanta-te vai Faraó e-o-ocultou-o nome no-niquique o-a-pedra');
INSERT INTO verses VALUES (19340, 24, 13, 5, 'ואילך e-o-ocultei-o no-fértigo como ordenou yhwh me-lembra-me');
INSERT INTO verses VALUES (19341, 24, 13, 6, 'e-houve ao-fim-de dias muitos E-disse yhwh a-mim levantou vai Faraó e-leva de-lá a o-o-anel ordenei-te eu-te-ordenei para o esconder-lhe- nome');
INSERT INTO verses VALUES (19342, 24, 13, 7, 'e eu andei Faraó e eu cavou e eu peguei a o-o-anel de o-lugar que escondê-lo- para-lá não foi destruído o cinto não será salvo para-todo');
INSERT INTO verses VALUES (19343, 24, 13, 8, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19344, 24, 13, 9, 'assim disse yhwh כָּכָה אַשְׁחִית a גְּא֧וֹן Judá e-a גְּא֥וֹן jerusalém הָרָֽב׃');
INSERT INTO verses VALUES (19345, 24, 13, 10, 'o-povo הַזּ֨ה הָרָ֜ע הַֽמֵּאֲנִ֣ים ׀  לשמוע a דְּבָרַ֗י הַהֹֽלְכִים֙ בּישׁורון libbam e-foram atrás-de Elohim outros para-servi-los e-para-prostrar-se a-eles e-seja כָּעֵז este que não será salvo para-todo');
INSERT INTO verses VALUES (19346, 24, 13, 11, 'que como-que יִדְבּק הָעֵז a מָתְנֵי- homem assim הִדְבּקֶה- אֵלַי a todo casa Israel e-a todo casa Judá oráculo-de yhwh para-ser a-mim para-povo u-lshem וְלִתְהִלָּה וּלְתִפְאָרֶת e-não שָׁמְעֻֽו׃');
INSERT INTO verses VALUES (19347, 24, 13, 12, 'va''amartata a-eles a a-palavra este assim yhwh yhwh Elohim-de Israel todo נֵבֶל se-encherá vinho e-disseram não הֲיָדֹעַ que נֵדַע porque todo נֵבֶל יִמָּלֵא יָיַן׃');
INSERT INTO verses VALUES (19348, 24, 13, 13, 'va''amartata a-eles assim yhwh yhwh eis-me מְמַלֵּא a-terra todo habitantes-de a-terra הַזֹּאת e-a os-reis הַיּוֹשְׁבִים֩ para Davi sobre seu trono e-a os-sacerdotes e-a os profetas e-a todo habitantes-de Jerusalém sua coroa:');
INSERT INTO verses VALUES (19349, 24, 13, 14, 'e se quebrarem homem a irmão-dele e as mães e os filhos juntos oráculo-de yhwh não tenha compaixão e-não deles e-não e os tenha misericórdia dos que destruírem:');
INSERT INTO verses VALUES (19350, 24, 13, 15, 'ouvi e ouvireis a que yhwh yhwh palavra');
INSERT INTO verses VALUES (19351, 24, 13, 16, 'dai-vos a yhwh vosso elohim glória betereim-acento-águia escureça-se e antes que tremem vosso pés sobre eis que tormento e esperareis para a luz e sua sombra para a semelhança dele para o ar');
INSERT INTO verses VALUES (19352, 24, 13, 17, 'e se não vocês ouvirem-na em segredo chorará de-diante-de de-diante-de seu grito e seu suor תִּדְמַ֜ע וְתֵרַ֤ד עֵינִי֙ que porque nishba yhwh yhwh');
INSERT INTO verses VALUES (19353, 24, 13, 18, 'disse para-o-rei וְלַגְּבִירָה הַשְׁפּ֣ילוּ שֵׁ֑בוּ que יָרַד֙ מַרְאֲשׁ֣וֹתֵיכֶ֔ם עֲטֶ֖רֶת תִּֽפְאַרְתְּכֶֽם׃');
INSERT INTO verses VALUES (19354, 24, 13, 19, 'cidades-de o Negue fechem e-não-há abram a galá Judá toda ela a galá de paz');
INSERT INTO verses VALUES (19355, 24, 13, 20, 'vosso olhos os-vindos vossos-olhos onde a coroa נִתַּן־ para-ti CKER  tua beleza:');
INSERT INTO verses VALUES (19356, 24, 13, 21, 'que  dize: porque  ele guardará sobre-ti eles  ensinou-os  a eles sobre-ti  milhares  como chefes não cordas-  agarrar-se-ão a ti  como mulher-de  uma véu:');
INSERT INTO verses VALUES (19357, 24, 13, 22, 'e-que דֹאֲמַרְיִ בִּלְבָבֵ֔ךְ por-que קְרַאֻ֣נִי Estas בְּרֹ֧ב עֲוֺנֵ֛ךְ נִגְל֥וּ שׁוּלַ֖יִךְ נֶחְמְס֥וּ עֲקֵבָֽיִךְ׃');
INSERT INTO verses VALUES (19358, 24, 13, 23, 'הֲיַהֲפֹ֤ךְ כushi seu-oor e-namar suas-chavarburotay também vós considerem para-benefício para-estudo o-malvado');
INSERT INTO verses VALUES (19359, 24, 13, 24, 'e-apertem como-corda- na-brisa-de para-vento deserto:');
INSERT INTO verses VALUES (19360, 24, 13, 25, 'este seu-larão parte- de-te com-ei oráculo-de yhwh que esqueceste-te de-mim e-te-foste-alegraste em-vanidade:');
INSERT INTO verses VALUES (19361, 24, 13, 26, 'e-também eu expor-tei seu-ombro sobre face-tua e-se-viu te-seduzi');
INSERT INTO verses VALUES (19362, 24, 13, 27, 'me-afastei-te e-seus-braços intenção adúltera-te sobre seus-mamilos no-campo vi te-sucedias para-ti para-ti não não Ti-te-hăr-i depois-de até-quando até');
INSERT INTO chapters VALUES (759, 24, 14, 22);
INSERT INTO verses VALUES (19363, 24, 14, 1, 'que ser palavra-de yhwh a Jeremias sobre palavras-de Ha-ba-tsă-rôt');
INSERT INTO verses VALUES (19364, 24, 14, 2, 'Av-la Judá U-shă-ă-re-ha Um-ml-lû Ka-drû La-a-ă-re-ts Ve-tsi-vha Jerusalém Ala');
INSERT INTO verses VALUES (19365, 24, 14, 3, 'Ve-ad-di-re-ha enviaram para-a-mãos vieram sobre vazios não acharam águas voltaram suas-cálices vazos-estavam vergonharam-se e-cobriram-se e-escondiam-se de-seu-cabeça');
INSERT INTO verses VALUES (19366, 24, 14, 4, 'baavur a-terra חַתָּה que não foi a chuva em-a-terra vergonharam-se אִכָּרִ֖ים חָפ֥וּ de-seu-cabeça');
INSERT INTO verses VALUES (19367, 24, 14, 5, 'que também אַיֶּ֙לֶת֙ no-campo deu-à-luz que porque não foi דֶּֽשֶׁא׃');
INSERT INTO verses VALUES (19368, 24, 14, 6, 'וּפְרָאִים֙ עָמְד֣וּ sobre שְׁפָיִ֔ם espírito espírito כַּתַּנִּ֑ים terminaram os olhos porque não erva:');
INSERT INTO verses VALUES (19369, 24, 14, 7, 'se nossas iniquidades eles responderam yhwh yhwh fez para-que o-teu-nome porque a-ti nossos retornos para-ti pecamos');
INSERT INTO verses VALUES (19370, 24, 14, 8, 'esperança Israel que nos salve na época צָרָ֑ה por-que será como estrangeiro na-terra e como anfitrião deixa-נָטָ֥ה para-aquilo');
INSERT INTO verses VALUES (19371, 24, 14, 9, 'por-que será como homem assustado como herói não pode para salvar e tu yhwh yhwh e o teu nome sobre nós foi chamado a תַּנִּחֵֽנוּ׃');
INSERT INTO verses VALUES (19372, 24, 14, 10, 'assim yhwh yhwh ao-povo este assim אָֽהֲבוּ֙ לָנ֔וּעַ não não חָשָׂ֑כוּ não não רָצָ֔ם agora יִזְכֹּ֣ר iniquidade-deles וְיִפְקֹ֖ד a sua culpa:');
INSERT INTO verses VALUES (19373, 24, 14, 11, 'E-disse yhwh a-mim a תִּתְפַּלֵּ֛ל בְּעַד־ o-povo este לְטוֹבָֽה׃');
INSERT INTO verses VALUES (19374, 24, 14, 12, 'que יָצֻ֗מוּ Eu não sou ouviu a a minha alvorada e-que subirão holocausto e oferta אֵינֶ֣נִּי que porque pela espada e pela fome eu eu que consumem a-eles');
INSERT INTO verses VALUES (19375, 24, 14, 13, 'e-disse ah-ah Adonai yhwh eis eis dizemos a-eles a-eles vereis espada e fome não a-vós a-vós porque paz a-vós darei a-vós no-lugar- a-esta');
INSERT INTO verses VALUES (19376, 24, 14, 14, 'E-disse yhwh a-mim שָׁקֶר הַנְּבִיאִים נִבְּאוּ בְּשַׁמִּי não שְׁלַחְתִּים e-não mandamentos; e-não דִּבַּרְתִּי a-eles חֶזְוֵון שָׁקֶר וּקְסֶם libbam eles מִתְנַבְּאוּ a-vós');
INSERT INTO verses VALUES (19377, 24, 14, 15, 'portanto assim yhwh yhwh sobre os profetas os profetas em meu nome e-eu não espada e-eles não será e fome não será na-terra esta pela espada e pela fome serão consumidos os profetas eis que');
INSERT INTO verses VALUES (19378, 24, 14, 16, 'וְהָעָ֣ם que eles a-eles a eles serão משולכים בחוצות de-diante-de מפני הרעב והחרב e-não-há מקבר להם eles נְשֵׁיהֶ֔ם e-seus-filhos ובנותיהם e-spearei sobre-eles a רָעָתָֽם׃');
INSERT INTO verses VALUES (19379, 24, 14, 17, 'e-dirás a-eles a a-palavra este תרדנה minha-olho lágrima noite e-dia que voc-terá-aparecido porque quebra grande quebrada virgem filha-de muito ferida herança muito');
INSERT INTO verses VALUES (19380, 24, 14, 18, 'se eu-saí o-campo e-eis mortos-de espada e se בָּ֣אתִי a-cidade e-eis תַּחֲלוּאֵ֣י רָעָ֑ב porque também profeta também sacerdote סָחֲר֥וּ a terra e-não sabiam');
INSERT INTO verses VALUES (19381, 24, 14, 19, 'הֲמָאֹ֨ס מָאַ֜סְתָּ a Judá se בְּצִיּוֹן֙ גָּעֲלָ֣ה a-tua-vida מַדּ֙וּעַ֙ הִכִּיתָ֔נוּ e-não-há para-nós marpe קַוֵּ֤ה bom e-não-há bom וּלְעֵ֥ת מַרְפֵּ֖א e-eis בְעָתָֽה׃');
INSERT INTO verses VALUES (19382, 24, 14, 20, 'יָדַ֧עְנוּ yhwh רִשְׁעֵ֖נוּ iniquidade אֲבוֹתֵ֑ינוּ que pecamos para-ti');
INSERT INTO verses VALUES (19383, 24, 14, 21, 'a תִּנְאַץ֙ para-que seu-nome a תְּנַבֵּ֖ל trono-de כְבוֹדֶ֑ךָ macho a תָּפֵ֥ר בְּרִֽיתְךָ֖ com-nos');
INSERT INTO verses VALUES (19384, 24, 14, 22, 'há nos desejos as-nações de chuvas e-se os-céus serão dadas em multidões não-é-que yhwh ele yhwh Elohim-nosso e purifiquem-se para-ti porque tu fiz-te- a todo estes');
INSERT INTO chapters VALUES (760, 24, 15, 21);
INSERT INTO verses VALUES (19385, 24, 15, 1, 'E-disse yhwh a-mim se estará Moisés e Samuel diante-de-mim não-há alma-minha a o-povo este enviou de-em-cima-de face-de e sairão;');
INSERT INTO verses VALUES (19386, 24, 15, 2, 'e será porque eles-dire-ão a-ti onde nós sairemos va''amartata a-eles yhwh disse yhwh que para a morte para a morte e-que para a espada para a espada e-que para a fome para-a-fome e-que para o exílio para o exílio');
INSERT INTO verses VALUES (19387, 24, 15, 3, 'e eu visitaria sobre-eles quatro escravidão oráculo-de yhwh a a espada para matar e-a os cães para arrastar a-terra ave os-céus e-a besta-m a-terra para-comer e destruir');
INSERT INTO verses VALUES (19388, 24, 15, 4, 'e deixados para-todo reinos-de a-todo בִּגְלַל a-terra filho-de Yehozaque rei Judá sobre sobre fez em-Jerusalém');
INSERT INTO verses VALUES (19389, 24, 15, 5, 'que quem sofrerá sobre-ti Jerusalém e quem para-ti a-ti e-quem será levado para perguntar para-ti para-ti');
INSERT INTO verses VALUES (19390, 24, 15, 6, 'tu נָטַ֥שׁׁתְ de-mim-me oráculo-de yhwh אָח֣וֹר תֵּלֵ֑כִי וָאַ֨ט a ya-di sobre-ti וָֽאַשְׁחִיתֵ֔ךְ נִלְאֵ֖יתִי הִנָּחֵֽם׃');
INSERT INTO verses VALUES (19391, 24, 15, 7, 'וָאֶזְרֵ֥ם בְּמִזְרֶ֖ה בְּשַׁעֲרֵ֣י a-terra שִׁכַּלְתִּי אִבַּדְתִּי a povo-meu מִדְרָכֵיהֶם não- שָׁבוּ׃');
INSERT INTO verses VALUES (19392, 24, 15, 8, 'עַצְמֻ־ para-mim אַלְמְנוֹתָו֙ mares יַמִּים a-eles a-eles sobre mãe בָּחוּר שֹׁדֵד בָּצְהָרָיִם היפלתיתי sobre-ela pateom cidade ובהלות׃');
INSERT INTO verses VALUES (19393, 24, 15, 9, 'אומללוה ילדה השביעה נפחוה נפשיה שמשיה בעוד de-dia בושוה e escavará e a sua sobrevivência para a espada eu-darei diante-de seus inimigos oráculo-de yhwh');
INSERT INTO verses VALUES (19394, 24, 15, 10, 'Ó! para-mim que porque eu dei à luz homem disputa e-homem Madon para-todo a-terra não eu fiz abortar e-não e abortaram em-mim כֻּלֹּ֥ה maldições:');
INSERT INTO verses VALUES (19395, 24, 15, 11, 'disse yhwh se não para-bem se não- encontrei-me em-te בְּעֵ֥ת maldade e-em angústia a o-inimigo:');
INSERT INTO verses VALUES (19396, 24, 15, 12, 'se-agitará em-ferro ברזל מצפון e-niqureth:');
INSERT INTO verses VALUES (19397, 24, 15, 13, 'חילך ואוצרותיך לבז etenn não במחיר e-em-todo חטאיך e-em-todo גבוליך׃');
INSERT INTO verses VALUES (19398, 24, 15, 14, 'והעביתי a teu inimigo não não ידעתי porque fogo quebrantá-la no meu fogo sobre vós seres destruídos;');
INSERT INTO verses VALUES (19399, 24, 15, 15, 'tu eu soube yhwh lembra-se de mim e me visite e vingar-se para-mim contra os perseguidores a por muito tempo אַפְּךָ֖ תִּקָּחֵ֑נִי דַּ֕ע שְׂאֵתִ֥י sobre-ti opróbrio');
INSERT INTO verses VALUES (19400, 24, 15, 16, 'n-imtza-u דְבָרֶ֙יךָ֙ וָאֹ֣כְלֵ֔ם e-houve a-mim לְשָׂשׂ֖וֹן וּלְשִׂמְחַ֣ת לְבָבִ֑י porque נִקְרָ֤א שִׁמְךָ sobre-mim yhwh yhwh exércitos');
INSERT INTO verses VALUES (19401, 24, 15, 17, 'não יָשׁוֹבְתִי בְּסֹד־ de-diante-de וָאֵעַלְזִי מִפְּנֵי mão-tua בֶּדָ֣ד יָשׁוֹבְתִי porque זַעַם מִלְּאָתַי׃');
INSERT INTO verses VALUES (19402, 24, 15, 18, 'por-que ser כְּאֵבִי֙ נֶ֔צַח וּמַכָּתִ֖י אֲנוּשָׁ֑ה מֵֽאֲנָה֙ הֵֽרָפֵ֔א הָי֨וֹ תִֽהְיֶ֥ה para-mim como אַכְזָ֔ב águas não נֶאֱמָֽנוּ׃');
INSERT INTO verses VALUES (19403, 24, 15, 19, 'portanto assim yhwh yhwh se תָּשׁ֤וּב e eu te reterei ante mim tu te estabelecerás e-se tu trairás preço de valor segundo תִֽהְיֶ֑ה e eles voltarão eles a-ti e-tu não para-eles');
INSERT INTO verses VALUES (19404, 24, 15, 20, 'e eu te dar-te-ei ao-povo este para pedra de-bronze בְּצוּרָ֔ה וְנִלְחֲמ֥וּ a-ti e-não para-ti a-ti porque אִתְּךָ֥ eu לְהוֹשִֽׁיעֲךָ֥ וּלְהַצִּילֶ֖ךָ oráculo-de yhwh');
INSERT INTO verses VALUES (19405, 24, 15, 21, 'וְהִצַּלְתִּ֖יךָ da-mão-de males וּפְדִתִ֖יךָ da-mão-de עָרִצִֽים׃');
INSERT INTO chapters VALUES (761, 24, 16, 21);
INSERT INTO verses VALUES (19406, 24, 16, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19407, 24, 16, 2, 'não a-ti a-ti mulher a-ti serão para-ti filhos וּבָנ֔וֹת no-lugar- a-esta');
INSERT INTO verses VALUES (19408, 24, 16, 3, 'porque assim disse yhwh sobre הַבָּנִים֙ e-sobre הַבָּנ֔וֹת הַיִּילּוֹדִ֖ים בַּמָּק֣וֹם este e-sobre אִמֹּותָ֞ם הַיֹּולְד֣וֹת aqueles-o e-sobre pais-deles הַמּוֹלִדִ֥ים eles na-terra a esta');
INSERT INTO verses VALUES (19409, 24, 16, 4, 'מְמוֹתֵ֨י תַחֲלֻאִ֜ים יָמֻ֗תוּ não יִסָּֽפְדוּ֙ e-não serão sepultados por causa de sobre a-terra a terra יִֽהְי֑וּ וּבַחֶ֤רֶב e pela fome serão reunidos e-será para-alimento para alimento לעוף os-céus a-terra a-terra');
INSERT INTO verses VALUES (19410, 24, 16, 5, 'porque assim disse yhwh a virá casa destruidor e-a andarás a-eles e-a será destruída a-eles porque eu coletei a o meu sossego de-a o-este oráculo-de yhwh a a bondade e-a e a compaixão');
INSERT INTO verses VALUES (19411, 24, 16, 6, 'morreram גדלים וקטנים na-terra esta não יבury e-não a-eles a-eles e-não יתגדד e-não a-eles para-eles');
INSERT INTO verses VALUES (19412, 24, 16, 7, 'e-não a-eles a-eles sobre אֵ֖בֶל לנחמו sobre morreu e-não ישקו a-eles כוס תנחומים sobre pai-dele e-sobre mãe-de ele');
INSERT INTO verses VALUES (19413, 24, 16, 8, 'e-casa-de משתה não vires para-habitar eles para comer e-para-beber');
INSERT INTO verses VALUES (19414, 24, 16, 9, 'que assim disse yhwh exércitos Elohim-de Israel eis-me de repouso de o-lugar este aos vossos olhos voz voz alegria e-voz voz voz noivo e voz casada');
INSERT INTO verses VALUES (19415, 24, 16, 10, 'e-foi que dirigir-te-ás a dizer ao-povo este a todo as-palavras estes e-disseram a-ti sobre yhwh palavra yhwh aleinu a todo a má a grande esta e qual nossos pecados e qual nosso pecado que pecamos a-יהוה Elohim-nosso');
INSERT INTO verses VALUES (19416, 24, 16, 11, 'e-dirás a-eles sobre que abandonaram vossos pais de-mim oráculo-de yhwh e-andaram atrás-de Elohim outros a-eles e se prostraram a-eles e a mim não e-a minha lei não שָׁמְרֻ');
INSERT INTO verses VALUES (19417, 24, 16, 12, 'וְאַתֶּ֛ם Haréuotem para-fazer M''abōteichem e-eis-vós Holkim homem atrás-de שְׁרִר֣וּת Livō- para-não para-não ouviu para-mim');
INSERT INTO verses VALUES (19418, 24, 16, 13, 'Vehtalti vocês de-cima-de a-terra esta sobre a-terra não não Yedautem vós Va''abōteichem e-voces-servireis-ao nome a Elohim Achērim dia a-vós que não darei para-vocês Ḥanina∶');
INSERT INTO verses VALUES (19419, 24, 16, 14, 'por-isso eis-a dias vêm oráculo-de yhwh e-não será-dito ainda vive yhwh que He''ala a filhos-de Israel de-terra-de Egito');
INSERT INTO verses VALUES (19420, 24, 16, 15, 'que se vive yhwh que העלנה a filhos-de Israel da-terra norte e-de-todo הארץ que הידיחום para-lá dei sobre sua terra que dei לאבותם׃');
INSERT INTO verses VALUES (19421, 24, 16, 16, 'eis-me enviou רבימ oráculo-de yhwh ודיגום ואחרי־ assim ESH לashach רבימ צַיָּדִים וְצָד֞וּם de-cima-de todo הַר֙ וּמֵעַ֣ל todo גִּבְעָ֔ה וּמִנְּקִיקֵ֖י הַסְּלָעִֽים׃');
INSERT INTO verses VALUES (19422, 24, 16, 17, 'que e-olhos sobre não דַּרְכֵיהֶ֔ם não נִסְתְּר֖וּ מִלְּפָנָ֑י e-não נִצְפַּ֥ן עֲוֺנָ֖ם מִנֶּ֥גֶד עֵינָֽי׃');
INSERT INTO verses VALUES (19423, 24, 16, 18, 'וְשִׁלַּמְתִּ֣י רִֽאשׁוֹנָ֗ה מִשְׁנֵ֤ה עֲוֺנָם֙ וְחַטָּאתָ֔ם sobre חַלְּלָ֣ם a minha terra de-sujeira suas-escórias e-suas-loaths preencheram a minha-herança:');
INSERT INTO verses VALUES (19424, 24, 16, 19, 'yhwh meu-poder e-meu-poder e-meu-refúgio no-dia צָרָ֑ה a-ti goyim יָבוֹא מֵאַפְסֵי־ terra וְיוֹאמְר֗וּ somente mentira nachalû אֲבֹתֵ֔ינוּ הֶ֖בֶל בָּ֥ם מוֹעִֽיל׃');
INSERT INTO verses VALUES (19425, 24, 16, 20, 'הֲיַעֲשֶׂה־ homem adam Elohim não nao Elohim');
INSERT INTO verses VALUES (19426, 24, 16, 21, 'portanto eis-me מֽוֹדִיעָ֔ם na-vez esta אוֹדִיעֵ֥ם a minha-mão e-a גְּבוּרָתִ֑י yhwh porque שמי yhwh');
INSERT INTO chapters VALUES (762, 24, 17, 27);
INSERT INTO verses VALUES (19427, 24, 17, 1, 'chéttā''ath Judá kătûbâ be-‘êṭ ferro be-tsippōren shāmîr khărušâh sobre lûḥa libbam u-le-qarnōth mizbĕkhōteikhem');
INSERT INTO verses VALUES (19428, 24, 17, 2, 'kizzekhōr os-filhos-deles mizb̅̂chōthām va''ăšērêyhem sobre madeira-de sobre sobre g̅̂ba''ōth hagg̅̂bohōth');
INSERT INTO verses VALUES (19429, 24, 17, 3, 'hărāryi no-campo chēylkā todo ōẓrōthēykā para-saque ʾetṭēn b̅āmothēykā b̅ăchattā''ath em-todo גבוליך׃');
INSERT INTO verses VALUES (19430, 24, 17, 4, 'veshamattá∶ úbekhā∶ minachalatékha∶ que dei para-ti vehaavadtikha∶ a teu inimigo na-terra que não ידעתי porque fogo kedaḵtem∶ beʾappi∶ até olam seres destruídos;');
INSERT INTO verses VALUES (19431, 24, 17, 5, 'assim disse disse yhwh maldito que yibṭa∶ בָּֽאָדָ֔ם וְשָׂ֥ם carne זְרֹע֑וֹ e-de yhwh ele se desviará coração-dele');
INSERT INTO verses VALUES (19432, 24, 17, 6, 'e-foi כְּעַרְעָ֣ר em-a planície e-não verá porque bom bom וְשָׁכַ֤ן חֲרֵרִים֙ terra terra מְלֵחָ֖ה e-não תֵשֵֽׁב׃');
INSERT INTO verses VALUES (19433, 24, 17, 7, 'בָּר֣וּךְ הַגֶּ֔בֶר que irá-se-a-ter em-יהוה e-será yhwh de-sua-segurança');
INSERT INTO verses VALUES (19434, 24, 17, 8, 'e-será como-árvore que-temer sobre águas e-sobre irá-se-firmar irá-se-enviar seus-raízes e-não porque irá-se-entrar fogo e-será nele ראַעֲנָ֑ן וּבִשְׁנַ֤ת בַּצֹּ֙רֶת֙ não יִדְאָ֔ג e-não יָמִ֖ישׁ de-fazer פֶּֽרִי׃');
INSERT INTO verses VALUES (19435, 24, 17, 9, 'עָקֹ֥ב הַלֵּ֛ב de-toda וְאָנֻ֣שׁ ele quem יֵדָעֶֽנּוּ׃');
INSERT INTO verses VALUES (19436, 24, 17, 10, 'eu yhwh חֹקֵ֥ר coração בֹּחֵ֣ן כְּלָי֑וֹת וְלָתֵ֤ת para-homem כִּפְרִ֖י מַעֲלָלָֽיו׃');
INSERT INTO verses VALUES (19437, 24, 17, 11, 'chamou דָגַר֙ e-não יָלָ֔ד fez dez e-não בְמִשָׁ֑פֵט בַּחֲצִ֤י יאזבנהוּ ובאחריתוֹ será נָבָֽל׃');
INSERT INTO verses VALUES (19438, 24, 17, 12, 'trono-de כבוד מרום MERIshon lugar-de MIQdashenu');
INSERT INTO verses VALUES (19439, 24, 17, 13, 'MIKveh Israel yhwh todo עוזביך yebošu na-terra יחתטוּ porque que מקור מַֽיִם־ חיים a yhwh');
INSERT INTO verses VALUES (19440, 24, 17, 14, 'רְפָאֵ֤נִי yhwh וְאֵ֣רָפֵ֔א הוֹשִׁיעֵ֖נִי וְאִוָּשֵׁ֑עָה que תְהִלָּתִ֖י tu');
INSERT INTO verses VALUES (19441, 24, 17, 15, 'eis הֵ֕מָּה אומרים a-mim ayeh palavra-de yhwh יָ֥בוֹא por-favor');
INSERT INTO verses VALUES (19442, 24, 17, 16, 'e-eu não אַ֣צְתִּי ׀ מֵרֹעֶ֣ה אחרך e-dia אנוש não התאוהיתי tu ידעתי fonte-de שפתاي porque  פָּנֶ֖יךָ  ser');
INSERT INTO verses VALUES (19443, 24, 17, 17, 'a תהי a-mim למחות machasi tu em-dia raa');
INSERT INTO verses VALUES (19444, 24, 17, 18, 'יבושו רדפי e-a אֵבֹ֣שָׁה eu serão-quebrados eles e-a אֵחַ֖תָּה eu dia sobre-eles dia maldade וּמִשְׁנֶ֥ה שִׁבָּר֖וֹן שָׁבְרֵֽם׃');
INSERT INTO verses VALUES (19445, 24, 17, 19, 'assim yhwh yhwh a-mim andou וְעָֽמַדְתָּ֙ no-porta filhos-de que venham nele reis-de Judá ואשר יֵ֣צְאוּ nele e em tudo שַׁעֲרֵי Jerusalém');
INSERT INTO verses VALUES (19446, 24, 17, 20, 'e-dirás אֲ֠לֵיהֶם שִׁמְע֨וּ palavra-de yhwh reis-de Judá e-tudo Judá e-todo habitantes-de Jerusalém os-vindos בַּשְּׁעָרִ֥ים as estas');
INSERT INTO verses VALUES (19447, 24, 17, 21, 'assim disse yhwh הִשָּׁמְרוּ בְּנַפְשׁוֹתֵיכֶם e-a תִּשָּׂאוּ מַשָּׂא no-dia הַשָּׁבָת וַהֲבִיאֶם בְּשַׁעֲרֵי Jerusalém');
INSERT INTO verses VALUES (19448, 24, 17, 22, 'e-não תֹּצִיאוּ מַשָּׂא מִבָּתֵּיכֶם no-dia a sábboth não obra não faça-vos e santifiemo-los a dia a sábboth como-que ordenei a vosso avós:');
INSERT INTO verses VALUES (19449, 24, 17, 23, 'e-não ouviram e-não levantaram a seus ouvidos e esforçaram para-não suas barbas para-não mas não um castigo de correção:');
INSERT INTO verses VALUES (19450, 24, 17, 24, 'e será se ouviu que ouvireis a-mim para-não yhwh para não traga peso nas portas a-cidade esta no-dia do sabbat e santifique a para-não o sabbat para-não faça todo obra');
INSERT INTO verses VALUES (19451, 24, 17, 25, 'e-entraram nas portas a-cidade isto מלכים וסרים ישבים sobre כסא Davi רכבים ברכב ובאסוסים eles והשריהם homem Judá e-habitantes-de Jerusalém ושbah העיר- esta para-sempre');
INSERT INTO verses VALUES (19452, 24, 17, 26, 'e-entraram de-cidades- Yehudah e-em-torno-de- Jerusalém e-de-terra Benjamim e-de a-planície e-de o-montanha e-de o-sul que-trazem- oferta-ascendinga e-oferta-vitimária- e-offerência-de-trigo- yhwh e-que-trazem- oferta-de-obras-mãos casa yhwh');
INSERT INTO verses VALUES (19453, 24, 17, 27, 'e-se não אַשְׁמְעוּ a-mim לְקַדֵּשׁ a dia הַשָּׁבָת וּלְבִלְתִּ֣י שאת peso וּבוֹא בְּשַׁעֲרֵי Jerusalém no-dia do sabbat וְהִצַּתִּי fogo בִּשְׁעָרֶיהָ e comearia fortalezas Jerusalém e-não tikbeh');
INSERT INTO chapters VALUES (763, 24, 18, 23);
INSERT INTO verses VALUES (19454, 24, 18, 1, 'a-palavra que ser a Jeremias yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19455, 24, 18, 2, 'levantou e-descereste casa הַיּוֹצֵ֑ר וְשָׁ֖מָּה אַשְׁמִֽיעֲךָ֥ a דְּבָרָֽי׃');
INSERT INTO verses VALUES (19456, 24, 18, 3, 'וָאֵרֵ֖ד casa הַיּוֹצֵ֑ר fez trabalho sobre הָאָבְנָֽיִם׃');
INSERT INTO verses VALUES (19457, 24, 18, 4, 'e sujar-se-á o recipiente que ele fez em-materiais na-mão-de o formador e voltar-se-á e fez-o instrumento outro como retificado em-olhos-de o formador para-fazer');
INSERT INTO verses VALUES (19458, 24, 18, 5, 'e-houve palavra-de yhwh a-mim dize:');
INSERT INTO verses VALUES (19459, 24, 18, 6, 'será o formador o-este não אכל- a-vós a-vós casa Israel eis yhwh eis como-argila na-mão-de הַיּוֹצֵר כֵּן־ vós em-a-mão-meia casa Israel');
INSERT INTO verses VALUES (19460, 24, 18, 7, 'momento אֲדַבֵּ֔ר sobre nação e-sobre מַמָּלָכָ֑ה para-quebrar e-para-esmigalhar e-para-destruir');
INSERT INTO verses VALUES (19461, 24, 18, 8, 'וְשָׁב֙ a-nação aquele מֵרָ֣עָת֔וֹ que falei sobre-ele וְנִֽחַמְתִּי֙ sobre do-mal que חָשַׁ֖בְתִּי a-ele a-ele');
INSERT INTO verses VALUES (19462, 24, 18, 9, 'וְרֶ֣גַע אֲדַבֵּ֔ר sobre nação e-sobre מַמָּלָכָ֑ה לִבְנֹ֖ת וְלִנְטֹֽעַ׃');
INSERT INTO verses VALUES (19463, 24, 18, 10, 'וְעָשָׂ֤ה diante de mim para-não ouviu para-não e consolarei-me sobre a-boa que eu disse para bem isso');
INSERT INTO verses VALUES (19464, 24, 18, 11, 'e-agora dize por-favor a homem-de dizendo e-sobre disse yhwh eis eu disse yhwh eis eu criador sobre-vós maldade e formador sobre-vós pensamento שׁ֣וּבוּ agora homem de Seus caminhos הָרַעָה e façam bem vos caminhos e vossas maldades:');
INSERT INTO verses VALUES (19465, 24, 18, 12, 'e-direão Noaš porque depois-de מחשבותינו iremos ואיש שְׁרִיר֣וּת Livō- a-má serão-feitas:');
INSERT INTO verses VALUES (19466, 24, 18, 13, 'portanto assim disse yhwh שַׁאֲלוּ־ por-favor quem quem ouviu כָּאֵ֑לֶּה שַׁעֲרֻרִת֙ muito muito בּוֹתֻלַ֖ת Israel');
INSERT INTO verses VALUES (19467, 24, 18, 14, 'הֲיַעֲזֹ֥ב מִצּ֛וּר Shaddai שֶׁלֶג Líbano se águas águas זרעים קרעים נוזלים׃');
INSERT INTO verses VALUES (19468, 24, 18, 15, 'porque שכחוני povo-meu para a nada יחטפוּ והכשלום בדרכיהם֙ eternidade eterno para-andar o-caminho-de não não סלולא׃');
INSERT INTO verses VALUES (19469, 24, 18, 16, 'להשם a-terra-deles לשממה eternidade todo eternidade sobre-ela ישׂום ויאניד בראשו:');
INSERT INTO verses VALUES (19470, 24, 18, 17, 'קרוחא- קדימ אפיקזם diante-de אֹיֵב עורף e-não face ארעם em-dia IEDAM');
INSERT INTO verses VALUES (19471, 24, 18, 18, 'e-disseram ide ונחשבה sobre ירמיהוּ֮ que porque não תאבד Torá do sacerdote e conselho de sabedoria e-palavra do profeta vão-vocês e o ouçamos pela língua e-a escutemos a todo suas palavras:');
INSERT INTO verses VALUES (19472, 24, 18, 19, 'ouvindo yhwh a-mim e ouça à-voz-de יְרִיבָֽי׃');
INSERT INTO verses VALUES (19473, 24, 18, 20, 'הַיְשׁוּלָ֤ם debaixo-de boa maldade porque כָּרוּ conversa לְנַפְשׁוֹ זְכֹר ׀ עָמְדִי em-te para-falar sobre-eles טובה para-responder a חֲמָתֶךָ de-eles');
INSERT INTO verses VALUES (19474, 24, 18, 21, 'por-isto תּוֹנֵן a בְּנֵיהֶם לַרְעָב וְהַגִּרֵם֮ sobre por-meio-de- חֶרֶב֒ וְתִֽהְיֶ֨נָה נְשֵׁיהֶ֤ם שַׁכֻּלוֹת֙ וְאַלְמָנ֔וֹת וְאַ֨נְשֵׁיהֶ֔ם יִֽהְי֖וּ הֲרֻ֣גֵי morte בַּח֣וּרֵיהֶ֔ם מֻכֵּי־ espada na-guerra');
INSERT INTO verses VALUES (19475, 24, 18, 22, 'תִּשָׁמַ֤ע זְעָקָה֙ מִבָּ֣תֵּיהֶ֔ם porque תָבִ֧יא sobre-eles גְּד֖וּד פִּתְאֹ֑ם porque כָר֤וּ לְלָכְדֵ֔נִי וּפַחִ֖ים טָמְנוּ לְרַגְלָֽי׃');
INSERT INTO verses VALUES (19476, 24, 18, 23, 'e-tu yhwh sab-e-s-tu a todo עֲצָתָ֤ם sobre-mim לַמָּ֔וֶת a cuprires-te sobre iniquidade-deles e-pecado-deles מִלְּפָנֶ֣יךָ a תֶּ֑מְחִי מֻכְשָׁלִים֙ diante-de-ti בְּעֵ֥ת que fez בָהֶֽם׃');
INSERT INTO chapters VALUES (764, 24, 19, 15);
INSERT INTO verses VALUES (19477, 24, 19, 1, 'assim disse yhwh הָל֛וֹךְ וְקָנִ֥יתָ בקבוק יוצר charesh ו Mizzenai o-povo ו Mizzenai ה כהנים');
INSERT INTO verses VALUES (19478, 24, 19, 2, 'ו יצאת a vale filho-de de Hinom que entrada portão וְקָרָ֣אתָ nome a as-palavras que falarei para-ti');
INSERT INTO verses VALUES (19479, 24, 19, 3, 'e-dirás ouvi palavra-de yhwh reis-de Judá ו יושבי ירVASלם yhwh disse yhwh exércitos Elohim-de Israel eis-me מביא malignidade sobre o-lugar este que todo שמעה תיצלנה ouvidos-seus');
INSERT INTO verses VALUES (19480, 24, 19, 4, 'יַ֣עַן que עֲזָבֻנִי וַיְנַכְּר֞וּ a o-lugar este וַיְקַטְּרוּ־ nele para-Elohim outros que não יְדָע֛וּם eles וַאֲבֽוֹתֵיהֶ֖ם וּמַלְכֵ֣י Judá וּמָֽלְא֛וּ a o-lugar este sangue justo');
INSERT INTO verses VALUES (19481, 24, 19, 5, '- e construíram, a nas cavernas o Senhor לִשְׂרֹ֧ף a os-filhos-deles com-fogo עֹלוֹת לַבָּ֑עַל que não eu-ordenei e-não דִבַּ֔רְתִּי e-não ascendeu sobre no meu coração:');
INSERT INTO verses VALUES (19482, 24, 19, 6, 'portanto eis-a dias os-vindo oráculo-de yhwh e-não יִקְרֵא֩ לַמָּק֨וֹם זה ainda que e vale filho-de hinnom porque se גֵּ֥יא הַהֲרֵגָֽה׃');
INSERT INTO verses VALUES (19483, 24, 19, 7, 'וּ֠בַקֹּתִי a עֲצַ֨ת Judá וִירוּשָׁלִַ֙ם֙ בַּמָּק֣וֹם este וְהִפַּלְתִּ֤ים pela espada diante-de inimigos-deles וּבְיַ֖ד מְבַקְשֵׁ֣י almas e-darei para-alimento נִבְלָתָם֙ לְמַֽאֲכָ֔ל לעוף a-terra e-a-de-vaca a-terra');
INSERT INTO verses VALUES (19484, 24, 19, 8, 'וְשַׂמְתִּי֙ a a-cidade esta לשממה וְלִשְׁרֵקָ֑ה todo passando sobre-ela יִשֹׁ֥ם וְיִשְׁרֹ֖ק sobre todo מַכֹּתֶֽהָ׃');
INSERT INTO verses VALUES (19485, 24, 19, 9, 'וְהַֽאֲכַלְתִּ֞ים a de-carne בְּנֵיהֶ֗ם e-את de-carne filhas-lhes e-homem carne- re-a-hu יאכלו'' em-maçor e-em-macok a-eles picaram a-eles seus inimigos e-pedintes alma-deles');
INSERT INTO verses VALUES (19486, 24, 19, 10, 'e-quebrareis aquele-pedinte para-os-olhos-de os-homens aqueles-vaiando te');
INSERT INTO verses VALUES (19487, 24, 19, 11, 'va''amartata a-eles assim disse- yhwh exércitos assim quebrarei a o-povo este e-a a-cidade esta como יִשְׁבּוֹר a instrumento הַיּוֹצֵר que não poderia לְהֵרָפֵה lugar וּבְתֹפֶת יִקְבּוּר de-onde lugar לִקְבּוֹר׃');
INSERT INTO verses VALUES (19488, 24, 19, 12, 'assim אֶעֱשֶׂה para-o-lugar este oráculo-de yhwh וּלְיֽוֹשֵׁבָיו וְלָתֶת a a-cidade a-esta כְּתֹפֶת׃');
INSERT INTO verses VALUES (19489, 24, 19, 13, 'e-sejam nas tuas Jerusalém וּבָתֵּי֙ reis-de Judá כִּמְק֥וֹם הַתֹּ֖פֶת הַטְּמֵאִ֑ים a-todo הַבָּתִּ֗ים que קִטְּר֜וּ sobre a-todo para-todo exército-de os-céus וְהַסֵּ֥ךְ נְסָכִ֖ים לֵאלֹהִ֥ים aḥērim');
INSERT INTO verses VALUES (19490, 24, 19, 14, 'E-veio Jeremias מֵֽהַתֹּ֔פֶת que שֶׁלַחְיוֹ yhwh nome לִהְיֹת נְבֵא e-yaa-amod בַּחֲצַר casa-de E-disse E-disse a todo o-povo');
INSERT INTO verses VALUES (19491, 24, 19, 15, 'assim yhwh yhwh exércitos Elohim-de Israel eis-me a a-cidade esta e-sobre todo עָרֶיהָ a todo do-mal que falei sobre-ela para-não הִקְשׁוּ a suas barbas para-não שְׁמֹעַ a דְּבָרָֽי׃');
INSERT INTO chapters VALUES (765, 24, 20, 18);
INSERT INTO verses VALUES (19492, 24, 20, 1, 'E-ouviu פַּשׁוּחֹר֙ filho-de disse o-sacerdote e-ele פָּקַד yhwh na-casa-de yhwh a Jeremias נִבְאָה a as-palavras as estas');
INSERT INTO verses VALUES (19493, 24, 20, 2, 'e-golpeou Pashur a Jeremias o-profeta E-colocou ele sobre a-ma-haf-pe-tseh que be-sha-ur benjamita a-superior que yhwh yhwh');
INSERT INTO verses VALUES (19494, 24, 20, 3, 'e-houve de-amanhã e-saiu pa-shu-ur a Jeremias E-disse a-ele E-disse não Jeremias chamou yhwh chamou que nome-teu porque se ma-gor misaviv');
INSERT INTO verses VALUES (19495, 24, 20, 4, 'que assim disse yhwh eis-me no-te-nekh-ah le-ma-gor a-ti e-para-todo- o-hav-eh-kha ve-na-phul-lu be-cher-ev seus inimigos ve-ay-ne-kha רֹאֹות e-a todo Judá אֶתּוֹ na-mão-de rei-de Babilônia e os exilarei em a Babel e destruirei pela-espada');
INSERT INTO verses VALUES (19496, 24, 20, 5, 'e dar-lhes-ei a todo tesouro a-cidade esta e-a todo sua ferida e-a todo seu valor e-a todo suas fortunas reis-de Judá אֶתּוֹ em-mão-de inimigos-deles e lhes venderão e as tomaram וֶהֱבִיא֖וּם Bavelah;');
INSERT INTO verses VALUES (19497, 24, 20, 6, 'e-tu פַשְׁח֗וּר e-tudo habitantes-de ביתך תֵּלְכ֖וּ בַּשֶּׁ֑בִי וּבָבֶ֣ל תָּב֗וֹא וְשָׁ֤ם morrerás e ali תִּקָּבֵ֔ר tu e-todo אֹ֣הֲבֶ֔יךָ a-eles נִבֵּ֥אתָ a-eles em-vanidade:');
INSERT INTO verses VALUES (19498, 24, 20, 7, 'pititani yhwh ve''efat chazakti vata''ocal estive lischoq todo o-dia até a totalidade loeg a-mim');
INSERT INTO verses VALUES (19499, 24, 20, 8, 'porque desde adaber ezak chamas וָשׁוֹד clamarei porque foi palavra-de yhwh a-mim lecherpe וּלְקֶ֖לֶס todo o-dia');
INSERT INTO verses VALUES (19500, 24, 20, 9, 'e-disser não אֶזְכְּרֶ֗נּוּ e-não falarei ainda בִּשְׁמ֔וֹ e-será בְלִבִּי֙ כאEther בֹּעֶ֔רֶת עָצֻ֖ר בְּעַצְמֹתָ֑י וְנִלְאֵ֥יתִי כַּֽלְכֵ֖ל e-não ele');
INSERT INTO verses VALUES (19501, 24, 20, 10, 'que שָׁמַ֜עְתִּי דִּבַּ֣ת רַבִּים֮ מָג֣וֹר מִסָּבִיב֒ הַגִּ֙idoּ֙ וְנַגִּידֶ֔נּוּ todo mortal שְׁלוֹמִ֔י guardadores-de צַלְעִ֑י אוּלַ֤י יְפֻתֶּה֙ וְנ֣וּכְלָה a-ele וְנִקְחָ֥ה נקמהנו nós');
INSERT INTO verses VALUES (19502, 24, 20, 11, 'והוה a-mim כְּגִבֹּר עָרַיצ sobre assim רֹדְפי יִכָּשְלוּ e-não יֻכָלוּ muito muito porque não eternidade não eternidade não תִשָּׂכֵחַ׃');
INSERT INTO verses VALUES (19503, 24, 20, 12, 'e-יהוה exércitos בֹּחֵ֣ן צַדִּיק viu כְלָיוֹת ולב אראה נקמתך de-eles que a-ti גיליתי a ריבי׃');
INSERT INTO verses VALUES (19504, 24, 20, 13, 'שִׁירוּ a-yhwh Além a que porque Salve a alma אֶבְי֖וֹן de-mão-de מְ-רֵעִים׃');
INSERT INTO verses VALUES (19505, 24, 20, 14, 'maldito o-dia que Eu fui nascido nele dia que Me deu à luz Minha mãe a seja Bendito é');
INSERT INTO verses VALUES (19506, 24, 20, 15, 'maldito o-homem que Boa nova a dizendo dizendo filho macho macho Alegria Faz alegar');
INSERT INTO verses VALUES (19507, 24, 20, 16, 'e-foi o-homem aquele Como cidades que yhwh yhwh e-não נִחַ֑ם וְשָׁמַ֤ע זְעָקָה֙ de-manhã וּתְרוּעָ֖ה בְּעֵ֥ת צָהֳרָֽיִם׃');
INSERT INTO verses VALUES (19508, 24, 20, 17, 'que não מוֹתְתַ֖נִי de-merékhem e-ela-tornou-se a-mim אִמִּי֙ קִבְרִ֔י eternidade הֲרַ֥ת eternidade');
INSERT INTO verses VALUES (19509, 24, 20, 18, 'por-que isto מֵרֶ֣חֶם יָצָ֔אתִי para-ver עָמָ֖ל וְיָג֑וֹן e-eles-terminaram בְּבֹ֖שֶׁת יָמָֽי׃');
INSERT INTO chapters VALUES (766, 24, 21, 14);
INSERT INTO verses VALUES (19510, 24, 21, 1, 'a-palavra que foi a yhwh de-junto-de a-ele בִּשְׁלֹ֨חַ a-ele o-rei צִדְקִיָּ֗הוּ a פַּשְׁחוּר֙ filho-de dizendo e-a צְפַנְיָ֧ה filho-de Maaseias o-sacerdote para-dizer');
INSERT INTO verses VALUES (19511, 24, 21, 2, 'buscou por-favor בַעֲדֵ֙נוּ֙ que yhwh porque Nabucadnetzar rei-de Babilônia lham yhwh Ulai fará yhwh Otanu conforme-toda Niflaotay Ve''yal''e de-acima-nos');
INSERT INTO verses VALUES (19512, 24, 21, 3, 'E-disse Jeremias a-eles assim T''amrun a Tsidqiyahu');
INSERT INTO verses VALUES (19513, 24, 21, 4, 'assim yhwh yhwh Elohim-de Israel eis-me Meseb a utensílios-de Hamilchama que בּיֶדְכֶם que vós נִלְחֲמוּ em-eles a rei Babilônia e-a הכָּשְׂדִֹים הַצָּרִים sobre-vós fora-de לַחֹמָה e-ajunto a-eles a o-mar a-cidade a esta');
INSERT INTO verses VALUES (19514, 24, 21, 5, 'וְנִלְחַמְתִּי eu convosco com-mão pendurado e-no-braco חֲזָקָה וּבְאַף e na chama וּבְקֶצֶף grande');
INSERT INTO verses VALUES (19515, 24, 21, 6, '[וְהִכֵּיתִ֗י] a [הָעִ֣יר] a-cidade esta e-[OBJ] o-homem e-[OBJ] [יָמֻֽתוּ] grande');
INSERT INTO verses VALUES (19516, 24, 21, 7, 'e-depois-de assim oráculo-de yhwh darei a tsidqiyahu rei-de יְהוּדָה e-a עבדayv e-a o-povo e-a הנישאארימ בעעיר a-esta de a-praga de a espada e-de הרעab em-mão-de נובךדראתzar rei-de Babilônia e-em-a-mão inimigos-deles UBYdayd מבקשeye de-cima-de והיכm à-boca-de espada não יָחֻס sobre-eles e-não יַחְמֹל e-não יְרַחֵם׃');
INSERT INTO verses VALUES (19517, 24, 21, 8, 'e-a o-povo este [כֹּ֖ה] disse yhwh yhwh eis-me deu [אֶת־דֶּ֥רֶךְ] a-vida caminho [הַמָּֽוֶת] e-[OBJ] caminho');
INSERT INTO verses VALUES (19518, 24, 21, 9, 'הַיּוֹשֵׁב֙ na-cidade esta יָמוּת com-a-espada e pela fome וּבַדָבֶר וְהַיּוֹצֵא e cairá sobre os caldeus os inimigos sobre-vós e será para-ele sua alma para ser espoliada');
INSERT INTO verses VALUES (19519, 24, 21, 10, 'que coloquei face-de na cidade esta-coisa para mal e-não para bem oráculo-de yhwh pela-mão-de rei Babilônia será dada e queimada em-a-chama');
INSERT INTO verses VALUES (19520, 24, 21, 11, '[וּלְבֵית֙] rei Judá ouvi palavra-de yhwh');
INSERT INTO verses VALUES (19521, 24, 21, 12, 'casa Davi assim disse yhwh [דִּ֤ינוּ] [לַבֹּ֙קֶר֙] [מִשְׁפָּ֔ט] [וְהַצִּ֥ילוּ] [גָז֖וּל] da-mão-de [עוֹשֵׁ֑ק] para-que-não [כָאֵ֜שׁ] [חֲמָתִ֗י] [וּבָעֲרָה֙] [וְאֵ֣ין] e-não-há de-diante-de de-diante-de mau');
INSERT INTO verses VALUES (19522, 24, 21, 13, 'eis-me אלייך ישבת העמק tsur o-plano oráculo-de yhwh הָאֹֽמְרִים֙ quem יחת sobre-nós e-quem יבוא במעונותינו׃');
INSERT INTO verses VALUES (19523, 24, 21, 14, 'ופקדתי sobre-vós כפרי maalליכם oráculo-de yhwh והצתי fogo בּיַעְרָ֔הּ e-consumiu todo סְבִיבֶֽיהָ׃');
INSERT INTO chapters VALUES (767, 24, 22, 30);
INSERT INTO verses VALUES (19524, 24, 22, 1, 'assim disse yhwh רֵ֖ד casa-de rei Judá e-tu-falarás nome a a palavra a-esta');
INSERT INTO verses VALUES (19525, 24, 22, 2, 'e-dirás ouviu palavra-de yhwh rei Judá o-que-habitava sobre tu Davi tu וַעֲבָדֶ֙יךָ֙ וְעַמְּךָ os-vindos בַּשְּׁעָרִ֥ים as estas');
INSERT INTO verses VALUES (19526, 24, 22, 3, 'assim disse disse yhwh מִשְׁפָּט֙ וּצְדָקָ֔ה וְהַצּ֥ילוּ גָז֖וּל da-mão-de עָשׁ֑וֹק וְגֵר֩ יָת֨וֹם וְאַלְמָנָ֤ה a תֹּנוּ֙ a תַּחְמֹ֔סוּ וְדָם נָקִי a תִּשְׁפַּךְ no-lugar a-esta');
INSERT INTO verses VALUES (19527, 24, 22, 4, 'que se עָשׂוֹ֙ תַּֽעֲשׂ֔וּ a a palavra este e-entraram nas portas a-casa הַזֶּ֡ה מְלָכִים֩ יֹשְׁבִ֨ים לְדָוִ֜ד sobre seu-trono ele ברכב e nos cavalos ele e seu povo:');
INSERT INTO verses VALUES (19528, 24, 22, 5, 'e se não ouvireis a as-palavras estes em-mim jurei oráculo-de será porque para a destruição será a casa a-esta');
INSERT INTO verses VALUES (19529, 24, 22, 6, 'porque assim disse yhwh sobre casa rei Judá tu tu a-mim cabeça o-לְבָנ֑וֹן se não eu destruirei não cidades não');
INSERT INTO verses VALUES (19530, 24, 22, 7, 'e santificarei sobre-te destruidores homem e seus utensílios e cortarão da escolha as vossas araucárias e derrubem sobre o-fogo');
INSERT INTO verses VALUES (19531, 24, 22, 8, 'e passarem nações muitos sobre a-cidade esta וְאָמְרוּ homem a companheiro-seu sobre yhwh fez yhwh assim para a cidade eu a esta');
INSERT INTO verses VALUES (19532, 24, 22, 9, 'e disseram sobre que abandonaram a yhwh yhwh אֱלֹהֵיהֶם-de-eles וַיִּֽשְׁתַּחֲו֛וּ a Elohim outros e serviram-os:');
INSERT INTO verses VALUES (19533, 24, 22, 10, 'a chorai pela morte a-ele tândeu a-ele békoo que não porque não retornara ainda véra''á a terra moládtó:');
INSERT INTO verses VALUES (19534, 24, 22, 11, 'que assim disse yhwh a shallúm filho-de Yoash debaixo Judá seu-pai em-lugar-de sair pai-dele que yátsá de o-lugar esta não יָשׁוּב nome ainda');
INSERT INTO verses VALUES (19535, 24, 22, 12, 'que em-lugar que ele ele nome morra e-a a-terra esta não verá ainda');
INSERT INTO verses VALUES (19536, 24, 22, 13, 'ai bóné em-a-casa-seu בלא- justiça vá''alíyyotá bəlō'' juízo em-sua-reação ya''ábód por nada não não dê a-ele');
INSERT INTO verses VALUES (19537, 24, 22, 14, '[הָאֹמֵ֗ר] [אֶבְנֶה־לִּי֙] [בֵּ֣ית] casa [וַעֲלִיּ֖וֹת] [מְרֻוָּחִ֑ים] [וְקָ֤רַֽע] a-ele a-ele [וְסָפ֣וּן] [בָּאָ֔רֶז] [וּמָשׁ֖וֹחַ] [בַּשָּׁשַֽׁר]');
INSERT INTO verses VALUES (19538, 24, 22, 15, 'הֲתִֽמְלֹ֔ךְ que tu מְתַחֲרֶ֣ה בָאָ֑רֶז teu-pai não comer וְשָׁתָ֗ה וְעָשָׂ֤ה מִשְׁפָּט֙ וּצְדָקָ֔ה entao bom a-ele');
INSERT INTO verses VALUES (19539, 24, 22, 16, 'דָּ֛ן דִּין־ עָנִ֥י וְאֶבְי֖וֹן bom bom o-conhecimento ela הַדַּ֥עַת me-a oráculo-de yhwh');
INSERT INTO verses VALUES (19540, 24, 22, 17, 'que não-há os-teus-olhos וְלִבְּךָ֔ que se sobre no teu opróbrio e-sobre DAM- HANAKIY para a tua vergonha e-sobre o que é esmagado e-sobre a que é estendida para-fazer');
INSERT INTO verses VALUES (19541, 24, 22, 18, 'portanto assim yhwh yhwh a Jehoiãquim filho-de יֹאשִׁיָּ֙הוּ֙ a-ele Judá não chorarão a-ele ai a-ele eis que irmã não chorarão a-ele ai senhor וְה֥וֹי הֹדֹֽה׃');
INSERT INTO verses VALUES (19542, 24, 22, 19, 'קְבוּרַ֥ת חֲמ֥וֹר יִקָּבֵ֑ר סָח֣וֹב וְהַשְׁלֵ֔ךְ da Heleia לְשַׁעֲרֵ֥י Jerusalém');
INSERT INTO verses VALUES (19543, 24, 22, 20, 'ali de-o-Líbano וּֽצְעָ֔קִי וּבַבָּשָׁן תְּנִ֣י teu-voz e-meu-grito de-ruínas que quebraram-se todo minha-amor-teu');
INSERT INTO verses VALUES (19544, 24, 22, 21, 'eu-falei para-ti com-aflição-teu eu-disse não אֶשְׁמָ֑ע este caminho-teu de-juventude-teu que não שָׁמַעְתְּ na-voz-meu');
INSERT INTO verses VALUES (19545, 24, 22, 22, 'todo [תִּרְעֶה־ר֔וּחַ] [וּֽמְאַהֲבַ֖יִךְ] espírito [יֵלֵ֑כוּ] que [אָ֤ז] porque [וְנִכְלַ֔מְתְּ] de-toda [רָעָתֵֽךְ] de-todo');
INSERT INTO verses VALUES (19546, 24, 22, 23, 'em-o-Líbano בַּאֲרָזִ֑ים que נֵחַנְתְּ בְּבֹא־ a-ti cordas calafrio como-que-gerou');
INSERT INTO verses VALUES (19547, 24, 22, 24, 'vive aini que yhwh porque se será Canaã filho-de Joaquim rei que selo sobre mão da-minha-direita porque de-lá e-te-selar');
INSERT INTO verses VALUES (19548, 24, 22, 25, 'e-te-darei em-mão-de מְבַקְשֵׁ֣י a-tua-vida e-na-mao-de que tu יָג֖וֹר de-face-deles e-na-mao-de נְבוּכַדְרֶאצַּ֥ר rei-de Babilônia e-na-mão הַכַּשְׂדִּֽים׃');
INSERT INTO verses VALUES (19549, 24, 22, 26, '[וְהֵֽטַלְתִּ֣י] [אֹתְךָ֗] e-[OBJ] [אֲשֶׁ֣ר] que sobre a-terra a-terra [אֲשֶׁ֥ר] que não [וְשָׁ֖ם] nome');
INSERT INTO verses VALUES (19550, 24, 22, 27, 'e-sobre a-terra que [אֶת־נַפְשָׁ֖ם] [לָשׁ֣וּב] a [שָׁ֖מָּה] não nome não');
INSERT INTO verses VALUES (19551, 24, 22, 28, 'הַעֶ֨צֶב נִבְזֶ֜ה נָפ֗וּץ o-homem este כָּנְיָ֔הוּ se כְּלִ֔י não-há חֵ֖פֶץ nele מַדּ֤וּעַ ele ele e-seu-semente e-serão-lançados sobre a-terra que não não');
INSERT INTO verses VALUES (19552, 24, 22, 29, 'terra terra terra [שִׁמְעִ֖י] palavra-de yhwh');
INSERT INTO verses VALUES (19553, 24, 22, 30, 'assim disse disse yhwh a o-homem este arirui gever não será-sucesso que não não será-sucesso de-seu-semente homem habitou sobre trono-de Davi וּמֹשֵׁ֥ל a-ele em-juda:');
INSERT INTO chapters VALUES (768, 24, 23, 40);
INSERT INTO verses VALUES (19554, 24, 23, 1, 'ai pastores destruirão e-despeçam a rebanho minha pastoreada oráculo-de yhwh');
INSERT INTO verses VALUES (19555, 24, 23, 2, 'portanto assim yhwh yhwh Elohim-de Israel sobre os que pastoreiam הָרֹעִים a povo-meu atem despedaçastes-vos a eles e vossos inimigos deram-lhes e-não vocês me esqueceram a-eles eis-me eu queiro sobre-vós a mau vosso pecado oráculo-de yhwh');
INSERT INTO verses VALUES (19556, 24, 23, 3, 'e-eu e eu reunirei a remanescente de-toda de-todo as-terras eles eu espalhei-os eles nome e eu trarei de volta serão sobre ninhos e-frutifiquem e multiplicar-se-ão:');
INSERT INTO verses VALUES (19557, 24, 23, 4, 'e estabelecer-ei sobre-eles pastores e pastorearão e-não terão medo ainda e-não e se fartarão e-não ser-lhes-á atribuído oráculo-de yhwh');
INSERT INTO verses VALUES (19558, 24, 23, 5, 'eis dias os-vindo oráculo-de yhwh e-estabelecerei para-David crescerão justo e reinou rei e se agradecerá e fará mishpat e-justica na-terra');
INSERT INTO verses VALUES (19559, 24, 23, 6, 'em seus dias e será salvo Judá וְיִשְׂרָאֵ֖ל e habitará em segurança e-este Seu nome yhwh chamarão יְהוָה sua justiça');
INSERT INTO verses VALUES (19560, 24, 23, 7, 'por-isso eis-a dias vêm oráculo-de yhwh e-não dirão ainda vive yhwh que He''ala a filhos-de Israel dizendo Egito');
INSERT INTO verses VALUES (19561, 24, 23, 8, 'que se vive yhwh que [הֵבִ֜יא] e-que [בֵּ֤ית] a [מֵאֶ֣רֶץ] casa Israel da-terra [אֲשֶׁ֥ר] [הִדַּחְתִּ֖ים] [שָׁ֑ם] que [עַל־אַדְמָתָֽם׃] nome sobre');
INSERT INTO verses VALUES (19562, 24, 23, 9, 'לַנְּבִאִ֞ים נִשְׁבַּ֧ר לִבִּ֣י בְקִרְבִּ֗י רָֽחֲפוּ֙ todo עצמותי היהתי como homem ו Gebor עברו vinho de-diante-de yhwh e-por palavras-de קָדְשֽׁוֹ׃');
INSERT INTO verses VALUES (19563, 24, 23, 10, 'que מנאפים מלאה a-terra porque מִפְּנֵי אָלָה a-terra a-terra יבשוהו pastagens מִדְבָּ֑ר e-foi מרוצתם maldade וגבורותם não assim');
INSERT INTO verses VALUES (19564, 24, 23, 11, 'porque também profeta também sacerdote chanefu também em-meu-casa encontrei seu-mal oráculo-de yhwh');
INSERT INTO verses VALUES (19565, 24, 23, 12, 'portanto será caminho-deles a-eles como-escarros em-aflição e-eles-moverão e-cairão nela porque eu-levarei sobre-alehem maldade ano-de פְּקֻדָּתָ֖ם oráculo-de yhwh');
INSERT INTO verses VALUES (19566, 24, 23, 13, 'e-em-prophetas שֹׁמְר֖וֹן vi desprezo hinnebā''u ba-ba''al vayta''ū a povo-meu a Israel');
INSERT INTO verses VALUES (19567, 24, 23, 14, 'uvinnebā''ei Jerusalém vi ša''arūrah na''ōf vehalōḵ bašequer veḥizzū maos-de mere''īm para-que-se-apaguem- -retornem homem -da-maldade-sua foram- a-mim todos-eles -como-Sodoma -e-seus-habitantes -como-Amorá-');
INSERT INTO verses VALUES (19568, 24, 23, 15, 'portanto assim yhwh yhwh exércitos sobre הנביאים eis-me alimentará a-eles a-Lanã que מֵי־ cabeça porque de-com profetas-de Jerusalém saiu -como-circuncisão para-todo a-terra');
INSERT INTO verses VALUES (19569, 24, 23, 16, 'assim yhwh yhwh exércitos a -vocês-ouvirão sobre a-vós הַנְּבִיאִים os profetas a-vós מהבלים eles a-vós não לבאם yhwh não מפי yhwh');
INSERT INTO verses VALUES (19570, 24, 23, 17, 'dizemos אמור למנאצי palavra yhwh paz será a-vós e-tudo andou ב Shirrut coração-seu disseram não viras sobre-vos mal');
INSERT INTO verses VALUES (19571, 24, 23, 18, 'que quem ficou-em-pé בסוד yhwh E-viu E-ouviu a palavra-dele quem הקשיב E-ouviu');
INSERT INTO verses VALUES (19572, 24, 23, 19, 'eis seauarat yhwh yhwh יצאה e tempestade מִתְחוֹלֵל sobre sobre רְשָׁעִ֖ים vai gemer;');
INSERT INTO verses VALUES (19573, 24, 23, 20, 'não retornara também yhwh até fazê-lo e-até levantá-lo intenções no seu coração no fim os-dias você nos observará nela em-inteligência');
INSERT INTO verses VALUES (19574, 24, 23, 21, 'não enviei-os a os profetas e eles רָצוּ não דִבַּ֥רְתִּי a-eles e-eles נִבָּֽאוּ׃');
INSERT INTO verses VALUES (19575, 24, 23, 22, 'וְאִֽם־ עָמְד֖וּ בְּסוֹדִ֑י וְיַשְׁמִ֤עוּ minhas-palavras a povo-meu וִֽישִׁבוּם֙ מִדַּרְכָּ֣ם o mal וּמֵרֹ֖ע maʿallevayhem:');
INSERT INTO verses VALUES (19576, 24, 23, 23, 'ha-elohay miqkarov ani oráculo-de yhwh e-não Elohim-de de-longe:');
INSERT INTO verses VALUES (19577, 24, 23, 24, 'se yisrat homem bamishtarim e-eu não erenu oráculo-de yhwh porventura-não a os-céus e-a a-terra eu enchei oráculo-de yhwh');
INSERT INTO verses VALUES (19578, 24, 23, 25, 'ouvi a que disseram הנביאים hanabi''im bismi dizendo dizendo chalamtı eu sonhei:');
INSERT INTO verses VALUES (19579, 24, 23, 26, 'até מָתַ֗י há-esse em-o-cor os profetas os-profetas do-engano e-os-profetas de-enganar os-cor-deles');
INSERT INTO verses VALUES (19580, 24, 23, 27, 'os-contabilizando para-fazer-esquecer a meu-povo meu nome- em-os-sonhos-deles que contarão homem para-companheiro-seu como esqueceram pais-deles a nome-meu em-o-Baal');
INSERT INTO verses VALUES (19581, 24, 23, 28, 'o-profeta que com-ele sonho contará sonho e-que minha-palavra com-ele יְדַבֵּר minha-palavra verdade que para-a-tijolos a o-branco oráculo-de yhwh');
INSERT INTO verses VALUES (19582, 24, 23, 29, 'porventura-não assim as-minhas-palavras como-a-chama oráculo-de yhwh e-como-o-ventilador [סָֽלַע׃] pedra.');
INSERT INTO verses VALUES (19583, 24, 23, 30, 'por-isso eis-me sobre os profetas oráculo-de yhwh os-furtando as-minhas-palavras homem de-a seu-amigo');
INSERT INTO verses VALUES (19584, 24, 23, 31, 'eis-me sobre os-profetas oráculo-de yhwh os-tomando de-a-língua-deles e-ele-se-apaixonou oráculo-de');
INSERT INTO verses VALUES (19585, 24, 23, 32, 'hineni sobre nabiim chalomot mentira oráculo-de yhwh e-ele-contou-os e-eles-se-perderam a povo-meu em-a-mentira-deles e-em-o-terror-deles e-eu não shlachtem e-não dei-vos e-ajudará não será-utilidade para-o-povo- este oráculo-de yhwh');
INSERT INTO verses VALUES (19586, 24, 23, 33, 'e-se perguntará-te o-povo o-este ou dizendo ou yhwh dizendo que profecia yhwh e-dirás a-eles a que- leva e-terras-eu-lanciarei vós oráculo-de yhwh');
INSERT INTO verses VALUES (19587, 24, 23, 34, 'וְהַנָּבִ֤יא e-o-sacerdote e-o-povo que dirá levitação yhwh e-visitei sobre o-homem aquele e-sobre casa-dele');
INSERT INTO verses VALUES (19588, 24, 23, 35, 'assim dizeis homem sobre seu-proximo e-homem a yhwh que yhwh yhwh ele palavra yhwh');
INSERT INTO verses VALUES (19589, 24, 23, 36, 'e-levitação yhwh não lembrareis- que porque será será para-homem palavra-seu e-vireis a vida yhwh viventes yhwh de-exércitos Elohim-nosso');
INSERT INTO verses VALUES (19590, 24, 23, 37, 'assim tu teirim a o-profeta yhwh responderás yhwh ele palavra yhwh');
INSERT INTO verses VALUES (19591, 24, 23, 38, 'e-se yhwh yhwh dizei portanto disse yhwh yhwh יַ֧עַן vossa-linguagem a a-palavra yhwh carga yhwh dizendo não dizendo não yhwh massa- yhwh');
INSERT INTO verses VALUES (19592, 24, 23, 39, 'por-isso eis-me e-elevar-ei vos elevar e-precipitar-ei a-vos e-a a-cidade dei a-vós a-vós de-cima-de de-sobre face-de');
INSERT INTO verses VALUES (19593, 24, 23, 40, 'e-darei sobre-vos חֶרְפַּ֣ת eternidade e-abatimento eternidade que não תִשָּׂכֵחַ׃');
INSERT INTO chapters VALUES (769, 24, 24, 10);
INSERT INTO verses VALUES (19594, 24, 24, 1, 'me-revelou yhwh e-eis segundo dudai figos designados diante-de o-santuário yhwh depois-de a-exílio נובךדראתzar rei-de em-Babilônia a Jeconias filho-de Joiás rei-de יְהוּדָה e-a príncipes-de Judá e-a o-artesão e-a o-ferrador de-Jerusalém e-os-trouxeu Babilônia');
INSERT INTO verses VALUES (19595, 24, 24, 2, 'a-trombeta um figos boas muito como-de-figos as-primeiras-frutas e-o-trombeta um figos רָע֣וֹת muito que não serão-comidas do-mal');
INSERT INTO verses VALUES (19596, 24, 24, 3, 'E-disse yhwh a-mim que tu viu Jeremias e-disse tãenim as-figos as-boas muito muito e-as-más muito muito que não serão-comidas do-mal');
INSERT INTO verses VALUES (19597, 24, 24, 4, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (19598, 24, 24, 5, 'assim yhwh yhwh Elohim-de Israel como-ovelhas as-melhores estes assim conheço a exílio Judá que terra de o-lugar este terra cushitas לְטוֹבָֽה׃');
INSERT INTO verses VALUES (19599, 24, 24, 6, 'e-eu-posso meu-olho sobre-eles para o bem e-trarei-os-de-volta sobre a-terra esta e-construirei-eles e-não destruirei e-plantarei-os e-não etosh');
INSERT INTO verses VALUES (19600, 24, 24, 7, 'venatati a-eles coração para-conhecer a-mim que eu yhwh וְהָיוּ־ para-mim para-povo וְאָנֹכִי a-eles a-eles para-Elohim porque ישבו para-mim em-todo libam');
INSERT INTO verses VALUES (19601, 24, 24, 8, 'vekatteinim harot que não teachaln mero porque disse yhwh yhwh assim eten a tsidkiyahu melek- Judá e-a os-senhores-dele e-את remanescente Jerusalém os sobreviventes na-terra esta e-os-que-habitam em-terra-de Egito');
INSERT INTO verses VALUES (19602, 24, 24, 9, 'e-daremos-vos para-mal para-todo reinos-de a-todo para-a-desgraça a-terra para-o-estabelecimento ולקללה em-todo os-lugares que expulsarei-vos nome');
INSERT INTO verses VALUES (19603, 24, 24, 10, 'e-eu-enviarei neles a a-espada a הרעב de-cima-de a-terra até a-eles de-sobre sobre que dei a-eles e-para-os-pais-deles');
INSERT INTO chapters VALUES (770, 24, 25, 38);
INSERT INTO verses VALUES (19604, 24, 25, 1, 'o-matter que foi sobre Jeremias sobre todo povo Judá b-shana a-quarta Li-yohoyaqim filho-de יֹאשִׁיָּ֖הוּ rei Judá ela הַשָּׁנָה֙ ha-ra''shonit li-nbukhadre-tsar rei Babilônia');
INSERT INTO verses VALUES (19605, 24, 25, 2, 'que palavra Yirmeyahu o profeta sobre todo e-para Judá e-a dizendo habitantes-de Jerusalém para-dizer');
INSERT INTO verses VALUES (19606, 24, 25, 3, 'de três dez anos le-yoshiyahu filho-de Amon rei Judá o-dia o-dia este este três e-vinte ser foi palavra-de yhwh a-mim va-adaber aleichem Ashkem ve-daber e-não ouvistes');
INSERT INTO verses VALUES (19607, 24, 25, 4, 've-shalach yhwh vocês a todo os-seus-escravos os-profetas acordai-vos e-enviando e-não ouvistes e-não vireis a אָזְנְכֶ֖ם para-ouvir');
INSERT INTO verses VALUES (19608, 24, 25, 5, 'dizendo voltai-se- por-favor homem de-sua-caminho a-malícia-a e-de-mal das-vossas-obras e-sede sobre dar yhwh a-vós yhwh a-vós וְלַאֲבֽוֹתֵיכֶ֑ם de-o eternidade e-até eternidade');
INSERT INTO verses VALUES (19609, 24, 25, 6, 'e-a иd-eis atrás-de Elohim outros para-servi-los a-eles a-eles e-não вакхису a-mim por meio de иd-еихем a-vós ара a-vós');
INSERT INTO verses VALUES (19610, 24, 25, 7, 'e-não vocês-ouviram a-mim oráculo-de yhwh para-propósito-de биммаасе suas mãos лe-ра a-vós');
INSERT INTO verses VALUES (19611, 24, 25, 8, 'portanto assim disse yhwh exércitos йaан que não ouviram a דְּבָרָֽי׃');
INSERT INTO verses VALUES (19612, 24, 25, 9, 'eis-me enviou вe-лахахти a todo мишпухот цафон oráculo-de yhwh e-a Nabucodonosor rei-de Babel meu-servo e-traria-e-os sobre a-terra esta e-sobre os-habitantes-de-a e-sobre todo eternidade estes ao-redor e-saari-e-os e-posicionaria-e-os para-a e-para-a e-para-cidades-destruidas eternidade');
INSERT INTO verses VALUES (19613, 24, 25, 10, 'e-perderia-e-os מֵהֶ֗ם voz alegria e-voz שמחה voz noivo e-voz כלlah voz rekhayim e a luz Ner');
INSERT INTO verses VALUES (19614, 24, 25, 11, 'e-será todo a-terra esta para-ruina para-a-ruína e-servirão as-nações os-estes a rei Babilônia setenta anos');
INSERT INTO verses VALUES (19615, 24, 25, 12, 'e-foi como-cheios-de setenta anos eu-visitarei sobre rei-de Babilônia e-sobre o-povo aquele oráculo-de yhwh ele עֲוֺנָ֖ם eternidade terra que e-eu-postarei a-ele para-a-desolação-deles eternidade');
INSERT INTO verses VALUES (19616, 24, 25, 13, 'sobre a-terra aquela a todo as-minhas-palavras que eu-falei sobre-ela a todo o-escrito בַּסֵּ֣פֶר este que profetizou Jeremias sobre todo os-gentios');
INSERT INTO verses VALUES (19617, 24, 25, 14, 'que serviram- neles também eles nações muitos e-reis a-eles e-pagarei a-eles conforme-seu-trabalho e-conforme-sua-obra mãos-deles-verso-final');
INSERT INTO verses VALUES (19618, 24, 25, 15, 'que כֹּה disse yhwh Elohim-de Israel a-mim toma a copo do-vinho a-ira esta de-mim ele ele a eu as-nações que eu enviou te a-eles');
INSERT INTO verses VALUES (19619, 24, 25, 16, 'e-beberam e-se-excitaram e-se-descontrolaram de-diante-de a-espada que eu enviou entre-eles-verso-final');
INSERT INTO verses VALUES (19620, 24, 25, 17, 'e-que-ei a ha-kos yhwh yhwh e-bebi a yhwh as-nações que enviou-me yhwh a-eles');
INSERT INTO verses VALUES (19621, 24, 25, 18, 'a Jerusalém e-a cidades-de Judá e-a eles a os-seus-líderes para-dar -os para-destruição para-ruína para-grito e-maldição como-o-dia a-esta');
INSERT INTO verses VALUES (19622, 24, 25, 19, 'a Paro rei-de Egito e-a seus-escravos e-a príncipes-dele e-a todo seu-povo');
INSERT INTO verses VALUES (19623, 24, 25, 20, 'e-את todo no-crepúsculo e-a(o) terra melechey- terra- a-prudente terra todo reis terra filisteus e-a Ascalom e-a Azza- e-a Ecrom e-a restante Asof-dos');
INSERT INTO verses VALUES (19624, 24, 25, 21, 'a Edom e-a Moabe e-a filhos-de Amon');
INSERT INTO verses VALUES (19625, 24, 25, 22, 'e-[OBJ] todo e-[OBJ] [כָּל־מַלְכֵ֣י] e-[OBJ] e-[OBJ] reis-de [הָאִ֔י] e-[OBJ] reis-de o-mar que');
INSERT INTO verses VALUES (19626, 24, 25, 23, 'e-a Dedan e-a diz-se e-a desprezo e-a todo cortados lado-em-o');
INSERT INTO verses VALUES (19627, 24, 25, 24, 'e-[OBJ] todo reis-de e-[OBJ] e-[OBJ] todo reis-de [בַּמִּדְבָּֽר]');
INSERT INTO verses VALUES (19628, 24, 25, 25, 'e-[OBJ] todo reis-de [זִמְרִ֗י] e-[OBJ] todo reis-de e-[OBJ] e-[OBJ] todo');
INSERT INTO verses VALUES (19629, 24, 25, 26, 'e-את todo reis-de o-norte os-próximos e-os-remotos homem a irmão-seu e-את a-terra as-mamlekhut a-terra a-terra sobre face-de a-adama e-rei-de Sushakh yish-teh depois-deles');
INSERT INTO verses VALUES (19630, 24, 25, 27, 'e-dirás el-eihem assim disse yhwh exércitos Elohim-de Israel shetu veshechru uqyu veniflu e-não levanta-vos de-diante-de a-espada que eu enviou entre-vós');
INSERT INTO verses VALUES (19631, 24, 25, 28, 'e-foi que desdenharão tomar- o-copo de-tua-mão para-beber e-dirás a-eles disse yhwh yhwh exércitos bebeu vós-bebereis');
INSERT INTO verses VALUES (19632, 24, 25, 29, 'que eis na-cidade que será chamado שְׁמִ֣י eu eu de-o-início para-o-mal e-vós purifica-o não não que espada espada eu chamou a-terra todo yhwh a-terra oráculo-de yhwh exércitos');
INSERT INTO verses VALUES (19633, 24, 25, 30, 'e-tu vai-profetizar a-eles a todo as-palavras estes e-dirás yhwh yhwh de-a-alta ele-gritará e-de-o-lugar seu-santo dará sua-voz gritará gritar-á sobre sua-tenda Heidad a responder-á a-terra todo a-terra a-terra');
INSERT INTO verses VALUES (19634, 24, 25, 31, 'veio ruído até a-terra que porque contenda a-yhwh entre-as-nações ele ele para-todo carne os-malvados e-dos-deles-dar para-a-espada oráculo-de yhwh');
INSERT INTO verses VALUES (19635, 24, 25, 32, 'assim disse yhwh exércitos eis maldade saindo da-nação a nação e-tempo grande ye''or mi-yarchei- terra');
INSERT INTO verses VALUES (19636, 24, 25, 33, 'e-sejam chal''lei yhwh no-dia aquele mi-qtze a-terra e-até a-terra não não yissapdu e-não ye''aspu e-não serão sepultados por causa de a-terra face-de que serão');
INSERT INTO verses VALUES (19637, 24, 25, 34, 'heililu ha-ro''im ve-za''qu e-vos-espalhareis adirei o-rebanho porque encheram dias-vosso לִטְב֑וֹחַ e-dispersões-vossas e cairão como-vaso desejo');
INSERT INTO verses VALUES (19638, 24, 25, 35, 'e-se-exterminem fuga de os-maus e-fuga de-adirei o-rebanho');
INSERT INTO verses VALUES (19639, 24, 25, 36, 'voz clamação HA''REI''IM e-queixas adire do-rebanho porque yhwh yhwh a maraitam');
INSERT INTO verses VALUES (19640, 24, 25, 37, 'venadammu pastagens a-paz de-diante-de חֲרֹן também yhwh');
INSERT INTO verses VALUES (19641, 24, 25, 38, 'deixar kakhiphir sukho porque foi-ela a-sua-terra de-diante-de mipnay חֲר֣וֹן a-pomba e-por חֲרֹן אַף׃');
INSERT INTO chapters VALUES (771, 24, 26, 24);
INSERT INTO verses VALUES (19642, 24, 26, 1, 'No-princípio mamlcut Joiás filho-de יֹאשִׁיָּ֖הוּ rei ser foi a-palavra este yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19643, 24, 26, 2, 'assim disse disse yhwh בַּחֲצַר casa-de yhwh vedibarta sobre todo cidades-de Judá os-que-vêm lehischavot casa-de yhwh ordenei-te todo as-palavras que eu-te-ordenei para-falar a-eles a tigra palavra');
INSERT INTO verses VALUES (19644, 24, 26, 3, 'tal-mas eles-ouvirão e-voltarão homem de Seus caminhos a má e-arrependerei-me a a-maldade eu eu-sou pensando a-eles de-diante-de de-diante-de mau seus pecados:');
INSERT INTO verses VALUES (19645, 24, 26, 4, 'e-dirás a-eles assim disse yhwh se não vocês-ouvirão a-mim para-andar em-a-lei-meu dei dei diante-vos');
INSERT INTO verses VALUES (19646, 24, 26, 5, 'para-ouvir sobre meus-servos הנביאים que eu enviou a-vós ve-hashkem e-o-enviar e-não ouvistes');
INSERT INTO verses VALUES (19647, 24, 26, 6, 'e-darei a a casa este de-shiloh e-a a-cidade darei para-a-maldição a-todo nações-de a-terra');
INSERT INTO verses VALUES (19648, 24, 26, 7, 'e-eles-ouviram os-sacerdotes e-os-profetas e-todo o-povo a Jeremias falando a yhwh estes em-casa-de yhwh');
INSERT INTO verses VALUES (19649, 24, 26, 8, 'e-houve kechaloth Jeremias para-falar a todo que yhwh yhwh para-falar a ele o-povo e-eles-apanharam a-ele dizendo morrendo morrerás o-povo para-dizer morrer morrerás');
INSERT INTO verses VALUES (19650, 24, 26, 9, 'por-que nibetha em nome de dizendo dizendo será ser-á a-casa este e-a-cidade esta será-destruída de-sem habitante e-ele-reuniu todo o-povo yhwh Jeremias em-casa-de yhwh');
INSERT INTO verses VALUES (19651, 24, 26, 10, 'e-eles-ouviram príncipes-de Judá a as-palavras estes e-eles-subiram de-a-casa o-rei casa yhwh e-estabeleceram-se em-a-porta shaar- yhwh o-novo');
INSERT INTO verses VALUES (19652, 24, 26, 11, 'e-disseram os-sacerdotes e-os-profetas a os-senhores dizendo todo o-povo dizendo que morte para-o-homem este porque profetizou a a-cidade a-esta como-que ouviram em-os-ouvidos-vosso');
INSERT INTO verses VALUES (19653, 24, 26, 12, 'E-disse Jeremias a todo dizendo yhwh todo o-povo dizendo yhwh me-enviou para-profetizar a a-casa este e-a a-cidade a-esta a todo as-palavras que ouvistes');
INSERT INTO verses VALUES (19654, 24, 26, 13, 'e-agora melhoraram os-vossos-caminhos e-os-vossos-trabalhos e-ouvi בְּקוֹל yhwh vosso-Elohim e-ele-consolará yhwh a a-maldade que palavra sobre-vós');
INSERT INTO verses VALUES (19655, 24, 26, 14, 'e-eu eis-me em-vossas-mãos fazei- a-mim como-bom e-como-retido בְּעֵינֵיכֶֽם׃');
INSERT INTO verses VALUES (19656, 24, 26, 15, 'somente conheceu conhecereis porque que mortos אַתֶּם֮ אֹתִי֒ porque sangue inocente vós dando sobre-vós e-a a-cidade que e-a os-sentados-a yhwh em-verdade enviaram-me yhwh sobre-vós para-dizer em-o-ouvido-vosso a todo as-palavras as estas');
INSERT INTO verses VALUES (19657, 24, 26, 16, 'e-disseram os-príncipes e-todo o-povo a os-sacerdotes e-a ha-nnvi-im que ao-homem yhwh julgamento-do morte porque em-o-nome yhwh Elohim-nosso palavra a-nós');
INSERT INTO verses VALUES (19658, 24, 26, 17, 'וַיָּקֻ֣מוּ homens מִזִּקְנֵ֖י a-terra e-disseram a todo dizendo o-povo para-dizer');
INSERT INTO verses VALUES (19659, 24, 26, 18, 'o-morashthi foi profetizou ser a força dele rei-de Judá E-disse E-disse todo povo dizendo para-dizer assim yhwh yhwh exércitos Zion campo cairás-em-silêncio e-Jerusalém aldeias תִּֽהְיֶ֔ה e-o-monte a-casa para-as-alturas bosque');
INSERT INTO verses VALUES (19660, 24, 26, 19, 'o-morto foi-morto Ezequias rei-de Judá e-todo temer não-é teme a yhwh e-ele-suspirou yhwh face-de yhwh e-lamentou yhwh a o-mal que palavra sobre-eles não fazendo mal grande sobre almas-nossas');
INSERT INTO verses VALUES (19661, 24, 26, 20, 'e-também ser foi profetizando yhwh [אֽוּרִיָּ֙הוּ֙] filho-de Shemaiah de-cidade das-árvores e-profetizou sobre a-cidade esta e-sobre a-terra esta que palavras-de Jeremias');
INSERT INTO verses VALUES (19662, 24, 26, 21, 'E-ouviu o-rei Joiaquim e-todo giborav e-todo os-príncipes a davarav ve-yevakesh o-rei ha-mit-o E-ouviu [מִצְרָֽיִם] E-viu וַיִּבְרַ֖ח E-veio Egito');
INSERT INTO verses VALUES (19663, 24, 26, 22, 'e-enviou o-rei Yehoyakim homens Egito a Elnatan filho-de achbor e homens com-ele a Egito');
INSERT INTO verses VALUES (19664, 24, 26, 23, 'e-eles-fizeram-sair a [מִמִּצְרַ֗יִם] desde-Mitsrayim e-levaram-no a o-rei Yehoyakim e-golpeou-o com a espada e lançou a carne-seu a sepulcros-de filhos-de o-povo');
INSERT INTO verses VALUES (19665, 24, 26, 24, 'somente mão Aquicam filho-de era היהתה para-não Jeremias sem dar ele muito o-povo para-o-matar');
INSERT INTO chapters VALUES (772, 24, 27, 22);
INSERT INTO verses VALUES (19666, 24, 27, 1, 'No-princípio reinado-de יְהוֹיָקִ֥ם filho-de יֹאושִׁיָּ֖הוּ rei ser foi a-coisa este a yhwh dizendo yhwh para-dizer');
INSERT INTO verses VALUES (19667, 24, 27, 2, 'assim yhwh yhwh a-mim a-ti a-ti colunas-dele e-mastros e-dar-vos-eles sobre garganta-vossa');
INSERT INTO verses VALUES (19668, 24, 27, 3, 'e-enviar-vós-eles a rei Edom e-a rei Moabe e-a rei filhos-de Amom e-a rei Tiro e-a rei Tsidon em-mão-de mensageiros os-que-vieram Jerusalém a Zedeias rei Judá');
INSERT INTO verses VALUES (19669, 24, 27, 4, 've-tsivita eles a dizendo dizendo yhwh disse yhwh exércitos Elohim-de Israel assim toameru a adoneichem');
INSERT INTO verses VALUES (19670, 24, 27, 5, 'eu עָשִׂ֣יתִי a a-terra a o-homem e-a a-terra que sobre face-de a-terra be-chochi a-grande u-bizroa''i ha-netuya u-netatiha a-ele yashar be-einai');
INSERT INTO verses VALUES (19671, 24, 27, 6, 'e-agora eu dei a todo as-terras estes na-mão Nevucadnezar rei-de Babilônia seu-escravo dei a-ele vivente-de o-campo dei para-ele para-servi-lo');
INSERT INTO verses VALUES (19672, 24, 27, 7, 'e-eles-servirão ele todo as-nações e-a até e-com filho-de filho-seu até nele tempo sua-terra também ele e-eles-o-servirão nele nações muitos e-reis grandes-');
INSERT INTO verses VALUES (19673, 24, 27, 8, 'e-será o-povo e-a-monarquia que não ele ele a Nevucadnezar rei-de Babilônia e-a que não dará a seu-côncavo em-tributo rei Babilônia em-a-espada e-na-fome e-no-poder eles sobre o-povo o-aquele oráculo-de yhwh até vossa-impureza eles em-mão-sua');
INSERT INTO verses VALUES (19674, 24, 27, 9, 'e-vós a ouvir-eis a e-para e-a vossos-astrólogos e-a vossas-sonhos e-a vossos-magos dizendo não que eles dizemos não para-dizer não servireis a rei Babilônia');
INSERT INTO verses VALUES (19675, 24, 27, 10, 'que mentira eles נִבְּאוּ a-vós para-que afastarei vos de-cima-de terra-de-vós e-expulsarei vos e-perderíeis');
INSERT INTO verses VALUES (19676, 24, 27, 11, 'e-o-povo que trará a pescoço-seu em-tributo rei-de Babilônia oráculo-de yhwh e-servireis-a e-habitará nela');
INSERT INTO verses VALUES (19677, 24, 27, 12, 'e-a tsidkiyah rei-de Judá dibberti dizendo as-palavras estes dizendo habiu a ele beol rei-de Bavel ele a-ele veamo e-vivais');
INSERT INTO verses VALUES (19678, 24, 27, 13, 'por-que tamutu tu veamekha com-a-espada barava וּבַדָבֶר como-que palavra yhwh a hagoy que não ya-abod a rei Babilônia');
INSERT INTO verses VALUES (19679, 24, 27, 14, 'e-a -vocês-ouvirão a palavras-de ha-nevi''im dizendo não dizendo não servireis que rei eles porque a-vós eles נבאים a-vós');
INSERT INTO verses VALUES (19680, 24, 27, 15, 'que não שְׁלַחְתִּים oráculo-de yhwh e-eles נבאים bish-mi la-shak-er para-que ha-dikh-i vos va-abad-tehem atem e-os-profetas a-vós a-vós');
INSERT INTO verses VALUES (19681, 24, 27, 16, 'e-a ha-kohanim e-a todo dizendo o-este disse yhwh assim-que disse yhwh a a-vós dizendo eis os-vossos-profetas os-falando a-vós dizendo eis as-vasos que yhwh moradores de-babilônia a-vós rapidamente porque mentira eles נבאים a-vós');
INSERT INTO verses VALUES (19682, 24, 27, 17, 'a vocês-ouçam a-eles servi a rei-de Babilônia e-vivam por-que ser-ás a-cidade a-esta espada:');
INSERT INTO verses VALUES (19683, 24, 27, 18, 'e-se eles eles e-se há palavra-de yhwh com-eles encontrarão por-favor em-o-JHVH exércitos para-não entrai os-vasos| os-restantes na-casa-de yhwh e-casa rei יְהוּדָה e-em-Jerusalém Bavelah;');
INSERT INTO verses VALUES (19684, 24, 27, 19, 'que assim disse yhwh exércitos a os-marcadores e-sobre o-mar e-sobre as-máquinas e-sobre resto os-vasos הַנּוֹתָרִ֖ים na-cidade a esta');
INSERT INTO verses VALUES (19685, 24, 27, 20, 'que não levem-o- Nebucodnasor rei Babilônia em-a-sua-exílio- a Jeconias filho-de Joiaquim rei- Judá מִירוּשׇׁלַם בָּבֶ֑לָה e-a todo destruidores יְהוּדָה Jerusalém:');
INSERT INTO verses VALUES (19686, 24, 27, 21, 'que assim disse yhwh exércitos Elohim-de Israel sobre os recipientes os-restantes yhwh yhwh e-casa-de rei-de יְהוּדָה Jerusalém:');
INSERT INTO verses VALUES (19687, 24, 27, 22, 'Babilônia- e-os-trarão e-a-ali יִֽהְי֑וּ até dia paq-di eles oráculo-de yhwh e-ele-levar-e-os e-ele-devolver-e-os a o-lugar a-esta');
INSERT INTO chapters VALUES (773, 24, 28, 17);
INSERT INTO verses VALUES (19688, 24, 28, 1, 'e-houve em-a-ano a aquela No-princípio reinado-de-a Tsedeki-yah rei-de Judá a-quarta no-mês o-cinco-ésimo disse para mim disse filho-de Azur o-profeta que de-Gibeon na-casa-de yhwh yhwh hakohanim e-todo o-povo dizendo');
INSERT INTO verses VALUES (19689, 24, 28, 2, 'assim yhwh yhwh exercitos Elohim-de dizendo dizendo quebrei a sobre rei Babilônia');
INSERT INTO verses VALUES (19690, 24, 28, 3, 'em-ainda dois anos dias eu de-retornar a o-lugar este a todo yhwh casa tomou que tomou Nebucodonosor rei-de Babilônia de o-lugar esta E-colocou Babilônia');
INSERT INTO verses VALUES (19691, 24, 28, 4, 'e-a Jeconias filho-de Joiás rei-de Yehudah e-a todo exílio Judá os-que-vieram Babilônia que de-retornar a o-lugar este oráculo-de yhwh porque quebrarei a sobre rei Babilônia');
INSERT INTO verses VALUES (19692, 24, 28, 5, 'E-disse Jeremias o-profeta a Hananyah o-profeta aos-olhos-de os-sacerdotes e-aos-olhos-de todo o-povo yhwh em-casa-de yhwh');
INSERT INTO verses VALUES (19693, 24, 28, 6, 'E-disse Irméia o-profeta amen assim fará yhwh yakém yhwh a devarêchá que nibbêtá lehasshib instrumentos casa-de yhwh e-todo o-exílio de-Babilônia a o-lugar a-esta');
INSERT INTO verses VALUES (19694, 24, 28, 7, 'somente shema- por-favor a-palavra eu que eu palavra beaznêchá uvaaznéi todo o-povo');
INSERT INTO verses VALUES (19695, 24, 28, 8, 'os profetas que havvu לְפָנַ֛י e-diante-de-você de o-mundo e-ele-proferiu a terras muitas e-sobre reinados grandes para-guerra e-para-mal e-para-falar');
INSERT INTO verses VALUES (19696, 24, 28, 9, 'o-profeta que proferirá para-paz em-a-vinda palavra o-profeta o-profeta que de-seu-mandado yhwh com-verdade');
INSERT INTO verses VALUES (19697, 24, 28, 10, 'E-tomou Hananiya o profeta a de-cima-de de-a-cima do-pescoço Jeremias o-profeta e-o-partiu');
INSERT INTO verses VALUES (19698, 24, 28, 11, 'E-disse Hananiya perante todo dizendo dizendo disse yhwh yhwh assim quebrarei a oferta Nebucodonosor rei-de Babilônia enquanto de-cima-de dias de-cima pescoço todo as-nações E-andou Jeremias o-profeta para-caminho-dele');
INSERT INTO verses VALUES (19699, 24, 28, 12, 'e-houve palavra-de yhwh a Jeremias depois-de quebrar Hananiya de-cima-de a a-tábua de-a dizendo Yirmeyah o-profeta para-dizer');
INSERT INTO verses VALUES (19700, 24, 28, 13, 'caminhando va''amartata a dizendo dizendo disse yhwh yhwh árvore árvore quebraste e-farás abaixo-de-as troncos ברזל׃');
INSERT INTO verses VALUES (19701, 24, 28, 14, 'que כֹּה־ yhwh yhwh exércitos Elohim-de Israel sobre dei darei sobre pescoço todo para-lavrar estes para-serve a Nebucadnezzar rei-de Babilônia dei a-ele a vivente-de o-campo dei a-ele');
INSERT INTO verses VALUES (19702, 24, 28, 15, 'E-disse Yirmeyah o-profeta a Hanani-yah o-profeta ouvi- por-favor yhwh não envi-a-teu yhwh e-tu promet-eu a o-povo este sobre mentira');
INSERT INTO verses VALUES (19703, 24, 28, 16, 'portanto assim disse yhwh eis-me de-envia-teu de-cima-de face-de a-terra הַשָּׁנָה֙ tu morreu porque desobedeceu falaste a yhwh');
INSERT INTO verses VALUES (19704, 24, 28, 17, 'E-morreu Hanani-yah o-profeta em-a-ano aquela no-mês הַשְׁבִיעִֽי׃');
INSERT INTO chapters VALUES (774, 24, 29, 32);
INSERT INTO verses VALUES (19705, 24, 29, 1, 'e-estes palavras-de ha-sefer que enviou Jeremias o-profeta de-Jerusalém a mais anciaos-de a-exilação e-a os-sacerdotes e-a os-profetas e-a todo o-povo que foi-exilado Nebucodonosor de-Jerusalém Bavelah;');
INSERT INTO verses VALUES (19706, 24, 29, 2, 'depois-de tseet Jeconias- o-rei e-a-grande-mulher e-os-eunucos príncipes-de Judá e-Jerusalém e-o-ourives e-o-masger de-i-ru-shalaim');
INSERT INTO verses VALUES (19707, 24, 29, 3, 'em-mão-de el-asah filho-de shafan u-gmarya filho-de chilqia que enviou tsidqia rei-de Judá a dizendo rei Babel bavela para-dizer');
INSERT INTO verses VALUES (19708, 24, 29, 4, 'assim disse yhwh exércitos Elohim-de Israel para-todo ha-gola que higleiti de-Jerusalém Bavelah;');
INSERT INTO verses VALUES (19709, 24, 29, 5, 'construam casas e-assentem-se e-plante jardins e-comam a de-seu-fruto');
INSERT INTO verses VALUES (19710, 24, 29, 6, 'tomem נָשִׁ֗ים e-gere filhos וּבָנוֹת֒ e-tomem de-vosso-filhos נָשִׁ֗ים e-a filhas-de-vós tenu aos homens e-parirão filhos ובנות e-multiplicai nome e-a diminuireis');
INSERT INTO verses VALUES (19711, 24, 29, 7, 'e-procurareis a a paz a-cidade que expulsei vos ali e-orai em-a-sua-favor que yhwh será a-vós será a-vós paz');
INSERT INTO verses VALUES (19712, 24, 29, 8, 'que assim disse yhwh exércitos Elohim-de Israel a a-vós a-vós que em-meio-de-vós e-vossos-adevinhadores e-a ouvi-reis a vossos-sonhos que vós de-marcadores-de-sonho');
INSERT INTO verses VALUES (19713, 24, 29, 9, 'que em-falso eles נבאים a-vós Bishmi não enviastes-os oráculo-de yhwh');
INSERT INTO verses VALUES (19714, 24, 29, 10, 'porque disse yhwh que porque de-acordo-com de-cheio-de para-Babel setenta ano eu-considerarei a-vós e-estabelecerei sobre-vós a minhas-palavras o-bom para-retornar vos a o-lugar a-esta');
INSERT INTO verses VALUES (19715, 24, 29, 11, 'que eu יָדַ֜עְתִּי a as-pensamentos eu eu pensador sobre-vos oráculo-de yhwh pensamentos paz e-não a-vós a-dar a-vós finalidade e-esperança');
INSERT INTO verses VALUES (19716, 24, 29, 12, 'veqraatem oti'' vahalaktem vehitpalaltem a-mim וְשָׁמַעְתִּ֖י a-vós');
INSERT INTO verses VALUES (19717, 24, 29, 13, 'e-voces-procurareis a-mim umetsatem que tidreshuni em-todo levabchem');
INSERT INTO verses VALUES (19718, 24, 29, 14, 'venimtseti a-vós oráculo-de yhwh veshavti a e reunirei etchem de-todo os-povos e-de-todo os-lugares que expulsei a-vós nome oráculo-de yhwh e-retornei vos a o-lugar que higleiti vós de-lá');
INSERT INTO verses VALUES (19719, 24, 29, 15, 'que אֲמַרְתֶּ֑ם levantou para-nós yhwh os-profetas Bavelah;');
INSERT INTO verses VALUES (19720, 24, 29, 16, 'porque assim disse yhwh a o-rei aquele que habita a trono-de Davi e-a todo o-povo o-que-habita na-cidade esta vossos-irmãos que não saíram com-vocês na-exílio');
INSERT INTO verses VALUES (19721, 24, 29, 17, 'assim disse yhwh exércitos eis-me enviador contra-eles a a-espada a הרעב e-a a-palavra e-darei aqueles-o como-estes hash-shoarim que não serão-comidas do-mal');
INSERT INTO verses VALUES (19722, 24, 29, 18, 'e-perseguirei-vós depois-deles com-a-espada barava וּבַדָבֶר e-dareis para todos o reinos-de a-todo para-maldição e-para-destruição a-terra e-para-opressão em-todo as-nações que expulsarei-vós nome');
INSERT INTO verses VALUES (19723, 24, 29, 19, 'debaixo que não שָׁמְע֥וּ a as-minhas-palavras oráculo-de yhwh que enviei-eu a-eles a meus-servos הַנְּבִיאִים o-manhã e-o-enviar-ei e-não ouviram oráculo-de yhwh');
INSERT INTO verses VALUES (19724, 24, 29, 20, 'e-vós ouvi palavra-de yhwh todo ha-gola que eu-enviei de-Jerusalém Bavelah;');
INSERT INTO verses VALUES (19725, 24, 29, 21, 'assim yhwh yhwh exércitos Elohim-de Israel a Acauã filho-de voz-dele a-vós tsidqiyahu filho-de obras-dele os-profetas a-vós eles falsidade eis-me-aqui deu a-eles em-mão-de Nabucodonosor rei-de Babilônia e-os-ferrei diante-de-olhos-vossos');
INSERT INTO verses VALUES (19726, 24, 29, 22, 'e-sele deles qelalah a-todo exílio Judá que be-bavel dizendo yesimcha yhwh ke-tsidkiyahu uke-achav que qalam rei-de Babel em-a-chama');
INSERT INTO verses VALUES (19727, 24, 29, 23, 'yaan que fizeram nebalah b-y-i-s-r-a-e-l vaynaaphu a mulheres-de re-eihem e-ele-falaram palavra בִּשְׁמִי֙ mentira que não mandei-vos וְאָנֹכִי e-o-testemunha oráculo-de yhwh');
INSERT INTO verses VALUES (19728, 24, 29, 24, 'e-a Shema-yahou o-sonhador dizendo para-dizer');
INSERT INTO verses VALUES (19729, 24, 29, 25, 'assim yhwh yhwh exercitos Elohim-de dizendo dizendo por-causa-de tu tu enviaste em-seu-nome livros a todo o-povo que em-Jerusalém e-para Tséfan Yah dizendo dizendo não e-a todo os-sacerdotes para-dizer');
INSERT INTO verses VALUES (19730, 24, 29, 26, 'yhwh Nétan-ka sacerdote debaixo Yehoyada o-sacerdote l''hýot P''qidim casa yhwh para-todo homem M''shuggá u-mitnabéa ele ele a ha-mahpekhét e-a ha-tzinkóf');
INSERT INTO verses VALUES (19731, 24, 29, 27, 'e-agora por-que não Ga''artá B''yirmeyahu ha-anntoti ham-metnave a-vós');
INSERT INTO verses VALUES (19732, 24, 29, 28, 'que sobre כֵּ֞ן enviou אֵלֵ֛ינוּ dizendo para-dizer arquah ela benu casas veshevu e-plante jardins e-comam a phrihen');
INSERT INTO verses VALUES (19733, 24, 29, 29, 'E-chamou tzefanyah o-sacerdote a o sefer este beaznei Jeremias הַנָּבִֽיא׃');
INSERT INTO verses VALUES (19734, 24, 29, 30, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (19735, 24, 29, 31, 'enviou sobre dizendo o-exílio disse yhwh disse yhwh a shmayah hanechelami a-vós que nun-ba-a não Shemayah va-ani não shel-ach-ti-yo va-yav-tah-ch vós sobre mentira');
INSERT INTO verses VALUES (19736, 24, 29, 32, 'portanto assim yhwh yhwh eis-me po-qe-d sobre shem-a-ya ha-ne-chel-am-i a-ele zar-o-ho não for a-ele homem yo-sh-e-v em-meio-de o-povo este e-não verá bat-tov que eu o-seh- לְעַמִּ֖י oráculo-de yhwh porque desobedeceu palavra sobre yhwh');
INSERT INTO chapters VALUES (775, 24, 30, 24);
INSERT INTO verses VALUES (19737, 24, 30, 1, 'a-palavra que ser a Jeremias yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19738, 24, 30, 2, 'assim yhwh yhwh Elohim-de dizendo dizendo escreveu- para-ti com todo as-palavras que falei a-ti a livro');
INSERT INTO verses VALUES (19739, 24, 30, 3, 'que eis dias os-vindo oráculo-de yhwh e-retornarei a shebut ammi disse yhwh disse yhwh e-retornarei-eles a a-terra que dei a-eles e-possuirão-a');
INSERT INTO verses VALUES (19740, 24, 30, 4, 'e-estes as palavras que palavra yhwh a Israel e-a Judá');
INSERT INTO verses VALUES (19741, 24, 30, 5, 'porque disse yhwh voz voz ansiedade ouvimos terror e-não-há paz');
INSERT INTO verses VALUES (19742, 24, 30, 6, 'peguem- por-favor e-vede macho gerador macho por-que vi-a todo homem de-sua-mão sobre de-seu-irmão-gêmeo como-parindo e-ser-vos-tornar-ão todo face para-Yerocham');
INSERT INTO verses VALUES (19743, 24, 30, 7, 'ai que grande o-dia aquele de-onde como ele e-tempo-de dificuldade ela para-Iacob e-de-a ser-salvo');
INSERT INTO verses VALUES (19744, 24, 30, 8, 'e-será no-dia o-aquele [נְאֻ֣ם] yhwh yhwh eshbor ullo de-sobre de-cima-de umosrotêkha anateq e-não yaabdu- nele ainda זָרִֽים׃');
INSERT INTO verses VALUES (19745, 24, 30, 9, 'veavdhu a yhwh אֱלֹהֵיהֶם-de-eles e-את Davi malcham que aqim a-eles');
INSERT INTO verses VALUES (19746, 24, 30, 10, 'e-tu a tirah servo-teu Jacó oráculo-de yhwh que abaixo Israel porque eis-me salvador-teu de-longe e-com a-semente-teu da-terra cativos-seus e-voltará Jacó e-calmará e-quietará e-não-há מחרד׃');
INSERT INTO verses VALUES (19747, 24, 30, 11, 'porque אִתְּךָ֥ eu oráculo-de que para-te-salvar porque eu-farei completamente em-todo os-povos que [אַ֤ךְ] nome somente o-te não eu-farei completamente não para-o-julgamento e-limparei não te-limpare-ei');
INSERT INTO verses VALUES (19748, 24, 30, 12, 'que assim disse yhwh anush para-o-teu-fragmento נַחֲלָה teu-golpe');
INSERT INTO verses VALUES (19749, 24, 30, 13, 'não-há Dã teu-julgamento para-a-mazôr refuóth te''aláh para-ti para-ti');
INSERT INTO verses VALUES (19750, 24, 30, 14, 'todo meahavayikh shekhéchukh não não que porque makhat oyév hikitikh מוּסַ֣ר sobre sobre muito ''avonék atsum pecados-tua');
INSERT INTO verses VALUES (19751, 24, 30, 15, 'que clamas sobre quebra-tua sobre dor-tua sobre muito iniquidade-tua foram-fortes pecados-teus Estas para-ti para-ti');
INSERT INTO verses VALUES (19752, 24, 30, 16, 'portanto todo comer-tua serão-comidos e-todo dificuldades-tua kulam e-sejam יֵלֵ֑כוּ e-serão shosayikh limshissa e-todo bozeyikh darei labaz');
INSERT INTO verses VALUES (19753, 24, 30, 17, 'que fiz-subir arukha para-ti umimmakhotayikh eu-te-curarei oráculo-de que porque expulsa-a para-ti para-ti Tsion ela dor-sh não-há a-ela');
INSERT INTO verses VALUES (19754, 24, 30, 18, 'assim disse disse yhwh retornou shvu-t ahol-ei ya-aqov u-mish-kho-no-ta-yo ara-chem ve-nib-ne-tha cidade sobre til-la-h ve-ar-mon sobre mish-pa-to habitou');
INSERT INTO verses VALUES (19755, 24, 30, 19, 'e-saiu deles de ação de graças e-voz moc-ha-qim ve-hir-bet-im e-não yi-ma-tu ve-hik-bad-et-im e-não yi-tsaa-ro-u');
INSERT INTO verses VALUES (19756, 24, 30, 20, 'e-sejam seus-filhos ke-qe-dem va-a-da-to ante mim ti-ko-n וּפָ֣קַדְתִּ֔י sobre todo lo-chatz-a-yu');
INSERT INTO verses VALUES (19757, 24, 30, 21, 'e-será a-di-ro nós e-o-moshe-lo de-a-kirv-bo יֵצֵא e-hi-qrav-tiyu ve-nigash a-mim que quem ele ze-he tarde a seu-lábbo la-geshet para-mim oráculo-de yhwh');
INSERT INTO verses VALUES (19758, 24, 30, 22, 'e-sereis a-mim povo; וְאָנֹכִי estarei a-vós para-Elohim');
INSERT INTO verses VALUES (19759, 24, 30, 23, 'eis seauarat yhwh yhwh יצאה sa-ar mit-gorer sobre sobre רְשָׁעִ֖ים vai gemer;');
INSERT INTO verses VALUES (19760, 24, 30, 24, 'não ya-shuv charon também yhwh até fazê-lo e-até levantá-lo intenções no seu coração באחרית os-dias você nos observará em-ela');
INSERT INTO chapters VALUES (776, 24, 31, 40);
INSERT INTO verses VALUES (19761, 24, 31, 1, 'em-o-tempo a-essa oráculo-de yhwh e-he-yeh a-todo para-todo mi-sh-p-ho-th Israel e-eles serao para-mim le-a-m');
INSERT INTO verses VALUES (19762, 24, 31, 2, 'assim disse yhwh encontrou graça no-deserto povo s-r-i-de-y espada indo le-ha-r-gi-o Israel');
INSERT INTO verses VALUES (19763, 24, 31, 3, 'me-ra-cho-k yhwh apareceu a-mim ve-a-ha-vat eternidade ah-ab-ti-ch sobre assim me-sh-ach-ti-ch bondade');
INSERT INTO verses VALUES (19764, 24, 31, 4, 'ainda e-b-ne-ch e-nos-construiremos בּוֹתֻלַ֖ת Israel ainda tu-esperarás teus-tamborins e-sairás em-a-alegria jogando');
INSERT INTO verses VALUES (19765, 24, 31, 5, 'ainda tu-plantarás vinhas nas-montanhas de-Samaria plantaram plantando e-desonrando');
INSERT INTO verses VALUES (19766, 24, 31, 6, 'que há dia chamaram guardando em-monte-de Efraim levantem-se e-calçamos Sião a yhwh Elohim-nosso');
INSERT INTO verses VALUES (19767, 24, 31, 7, 'porque assim disse yhwh grite para-Jaōob שמחה e-sorriam na-cabeça as-nações faÃ§o-ouvir louvem e-digam salva-o yhwh a o-povo-tuo a restante Israel');
INSERT INTO verses VALUES (19768, 24, 31, 8, 'eis-me trazendo a-eles da-terra norte e-reunirei-os mi-yarchei- terra neles cego e-passo grávida e-parindo juntos assembleia grande retornarão até-aqui');
INSERT INTO verses VALUES (19769, 24, 31, 9, 'em-choro virão e-em-súplicas eu-conduzirei-os eu-conduzirei-vos a águas águas no-caminho não não יִכָּשְלוּ nela porque estive para-o-Israel para-pai ele em-seu-primeiro-fruto ela');
INSERT INTO verses VALUES (19770, 24, 31, 10, 'ouvi palavra-de yhwh nações e-anunciem nos-ilhas מִמּרְחָ֑ק e-digam de-muito-longe Israel ele-reunirá-os e-guardarão-o curvado seu-exército');
INSERT INTO verses VALUES (19771, 24, 31, 11, 'porque yhwh yhwh a Jacó e-redimiu-o nós força de-nós');
INSERT INTO verses VALUES (19772, 24, 31, 12, 'e-entraram e-cantaram em-alturas-o sion e-fluiram yhwh bom yhwh sobre grão e-sobre mosto e-sobre Yit-shar e-sobre filhos-de CKER וּבָקָ֑ר e-será não como-jardim regado e-não eles-aumentarão para-tristeza ainda');
INSERT INTO verses VALUES (19773, 24, 31, 13, 'entao alegrar-se-ás virgem-na em-a-rodada e-com-os-jovens וזקנים juntos e-virei a-luto para-alegria-dele e-consolarem-se e-farão-alegres de-suspiros-deles');
INSERT INTO verses VALUES (19774, 24, 31, 14, 'e-vou-derramar alma os-sacerdotes gordura e-povo-meu a bene-da-mim serão-satisfeitos oráculo-de yhwh');
INSERT INTO verses VALUES (19775, 24, 31, 15, 'assim disse disse yhwh voz é-ouvido nhei choro-de tamruirim Rachel mevakhah sobre filhos-de ela meanah lehinnachem sobre que porque não há');
INSERT INTO verses VALUES (19776, 24, 31, 16, 'assim disse disse yhwh qolekha mibeki veenayikh middemah porque que sakhar para-a-teu-trabalho oráculo-de yhwh e-eles-voltarão da-terra-de inimigo');
INSERT INTO verses VALUES (19777, 24, 31, 17, 'e-há- esperança para-a-teu-fim oráculo-de filhos [לִגְבוּלָֽם׃] filhos para-o-limite-deles');
INSERT INTO verses VALUES (19778, 24, 31, 18, 'שָׁמ֣וֹעַ ouvi Efraim balançando-se tu-me-corrigirás e-eu-serei-corrigido como-touro não ensinado responde-me e-voltarei que tu yhwh Elohim-meu');
INSERT INTO verses VALUES (19779, 24, 31, 19, 'porque depois-de volta-te e-eu-me-arrependi e-depois-da e-eu-te-anunciei e-eu-duvidei sobre joelho-teu que e-também e-eu-me-envergonhei porque levantei-sa-ti desonra os-meus-jovens');
INSERT INTO verses VALUES (19780, 24, 31, 20, 'o-filho querido para-mim Efraim mãe menino divertimentos porque desde palavras-mi-as nele macho eu-recordarei-no-lo ainda sobre assim a-ele de-meus-internos a-ele misericórdia eu-terei-misericórdia-no-lo oráculo-de yhwh');
INSERT INTO verses VALUES (19781, 24, 31, 21, 'o-estabelece para-ti marcos meu-nome para-ti amarguras minha-sede teu-coração para-a-estrada o-caminho-de volta-te virgem-a Israel volta-te a teus-cidades estes');
INSERT INTO verses VALUES (19782, 24, 31, 22, 'até quando se-esquivarão a-filha a-que-vira yhwh criou yhwh fêmea na-terra fêmea vira homem:');
INSERT INTO verses VALUES (19783, 24, 31, 23, 'assim yhwh yhwh exércitos Elohim-de Israel ainda dirão a a-palavra este em-a-terra Judá e-na-sua-cidade quando-voltar yhwh seu-exílio abençoará-te yhwh habitação-de- será monte-de o-santuário');
INSERT INTO verses VALUES (19784, 24, 31, 24, 'e-estarão-assentados בָ֛הּ Judá e-todo sua-cidade juntos icarim e-naseu ba-edder');
INSERT INTO verses VALUES (19785, 24, 31, 25, 'que hirveti alma עֲיֵפָה e-todo alma daavah mileiti');
INSERT INTO verses VALUES (19786, 24, 31, 26, 'sobre esta heqitzoti va-ereh ushnati a-mim a-mim');
INSERT INTO verses VALUES (19787, 24, 31, 27, 'eis dias vêm oráculo-de yhwh vezaraeti a casa Israel semente homem Judá animal-doméstico homem e-semente animal');
INSERT INTO verses VALUES (19788, 24, 31, 28, 'e-será como-que vigiei-eu sobre-eles para-destruir e-para-despedaçar e-para-destruir e-para-aniquilar e-para-fazer-mal assim vigilarei-eu sobre-eles para-construir e-para-arvorizar oráculo-de yhwh');
INSERT INTO verses VALUES (19789, 24, 31, 29, 'em-os-dias aqueles não dirão ainda pais אָ֣כְלוּ boser filhos filhos תִּקָּחֶֽינָה׃');
INSERT INTO verses VALUES (19790, 24, 31, 30, 'que se homem baavono morra todo o-homem haokhel haboser tikhenah suas gengivas;:');
INSERT INTO verses VALUES (19791, 24, 31, 31, 'eis dias vêm oráculo-de yhwh vekarati a casa Israel e-a casa יְהוּדָה yhwh chadasha');
INSERT INTO verses VALUES (19792, 24, 31, 32, 'não kabrit que karati a pais-deles em-dia-de hecheziki em-a-sua-mão לְהוֹצִיאָ֖ם da-terra Egito que eles e-peru a aliança-minha וְאָנֹכִי eu-tomei yhwh oráculo-de yhwh');
INSERT INTO verses VALUES (19793, 24, 31, 33, 'que esta a-a-aliança que eu-cortarei a casa Israel apos os-dias aqueles dei yhwh eu-deti a a-minha-lei no-meio-de-eles a-eles seus corações eu-escreverei-a e eu ser-me-ia a-eles para-Elohim e-eles serao para-mim para-o-povo');
INSERT INTO verses VALUES (19794, 24, 31, 34, 'e-não eles-aprendam ainda homem a seu companheiro e-homem dizendo seu-irmao dizendo conheçam a yhwh porque todos-eles eles-conhecerão que para-os-pequenos-dele e-até e-para-os-grandes-dele não yhwh porque eu-perdoarei para-seus-pecados e-para-suas-transgressões não eu-recordarei- ainda');
INSERT INTO verses VALUES (19795, 24, 31, 35, 'assim disse disse yhwh Shemesh para-luz diariamente -destituições -lua e-estrelas para-luz noite noite o mar o-mar -seus-vórtices yhwh yhwh nome-dele');
INSERT INTO verses VALUES (19796, 24, 31, 36, 'se retirar-se-ão הַחֻקִּ֥ים os-estes ante mim também semente também זֶ֨רַע Israel assentar-se-ão de-haver nação ver todo os dias');
INSERT INTO verses VALUES (19797, 24, 31, 37, 'assim disse disse yhwh medir-se-ão céus de-em-cima e-serão-examinados -fundadores-de terra abaixo também eu eu-aborreço em-todo semente Israel sobre todo que fizeram oráculo-de yhwh');
INSERT INTO verses VALUES (19798, 24, 31, 38, 'eis dias oráculo-de yhwh e-será-construída a-cidade a-yhwh de-monte Hananel portão-de a-esquina');
INSERT INTO verses VALUES (19799, 24, 31, 39, 'e-sairá ainda a-medida em-o-seu-frente sobre colina-de sobre e-será-virado seca-verso-final');
INSERT INTO verses VALUES (19800, 24, 31, 40, 'e-todo a-valley os-mortos e-o-cinzento e-todo até ribeiro-de Qidron até pinta- porta-de os-cavalos para-o-nascente santidade para-יהוה não se-desgarrará e-não será-derribado a-ele para-eternidade');
INSERT INTO chapters VALUES (777, 24, 32, 44);
INSERT INTO verses VALUES (19801, 24, 32, 1, 'o-matter que foi a yhwh de-junto-de yhwh a-décima para-Tsidquiahu rei Judá ela a-ano oito- doze ano para-Nebucodonosor');
INSERT INTO verses VALUES (19802, 24, 32, 2, 'e-aquele-tempo exército rei Babilônia inimigos sobre Jerusalém e-Jeremias ser foi encarcerado בַּחֲצַר a-prisão que casa-de rei Judá');
INSERT INTO verses VALUES (19803, 24, 32, 3, 'que encarcelou-o Tsidquiyahu rei-de dizendo dizendo tu אתה dizendo dizendo disse yhwh yhwh eis-me deu a a-cidade esta na-mão-de rei-de Babel e-a-captura');
INSERT INTO verses VALUES (19804, 24, 32, 4, 'Tsidquiyahu rei Judá não será-escapar da-mão-de os-cassitas que dará será-dar na-mão-de rei-de Babilônia e-ele-falará- de-seu-boca com de-sua-boca e-de-seus-olhos a vireis');
INSERT INTO verses VALUES (19805, 24, 32, 5, 'e-Babel yolikh a Tsidiyyahu será ser-á ele pakdi que oráculo-de yhwh não tilakhamu a ha-kasdim não tatslihu');
INSERT INTO verses VALUES (19806, 24, 32, 6, 'E-disse Jeremias ser palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (19807, 24, 32, 7, 'eis Chanameel filho-de Shallum dodheka veio dizendo dizendo a-ti para-ti a Shaddai que a-ti porque para-ti משפט a-redempção para-comprar');
INSERT INTO verses VALUES (19808, 24, 32, 8, 'E-veio אֵלַי Hananel filho-de meu-primo yhwh yhwh a E-disse a-moeda E-disse para mim compra por-favor a Shaddai que em-anotações que na-terra Benjamim porque para-você julgamento a-herança que a-redenção ele para-ti e soube porque palavra-de yhwh ela');
INSERT INTO verses VALUES (19809, 24, 32, 9, 'e-equnei a o-campo de-junto-de chanameil filho-de dodi que ba-anatos e-esheqlah- a-ele a a-prata sete escalam va-asarah הכסף׃');
INSERT INTO verses VALUES (19810, 24, 32, 10, 'e-echtev ba-sefer e-e-cartim e-o-jurei jures e-e-esperei o dinheiro em-as-balancas');
INSERT INTO verses VALUES (19811, 24, 32, 11, 'e-o-tomei a livro o-comprado a o-cartim a-obrigação e-os-regulamentos e-a o-exposto');
INSERT INTO verses VALUES (19812, 24, 32, 12, 'e-eu-deti a o sefer o-comprado a בָּר֣וּךְ filho-de Nériah filho-de Machséia para-os-olhos-de Hanaméel meu-primo e-perante-os-olhos-de os-testemunhas os-escreventes בְּסֵ֣פֶר o-adquirido para-os-olhos-de todo os-judeus os-habitantes dizendo a-matriz');
INSERT INTO verses VALUES (19813, 24, 32, 13, 'e-eu-ordenei bendito le-einehem dizendo');
INSERT INTO verses VALUES (19814, 24, 32, 14, 'assim yhwh yhwh exércitos Elohim-de Israel para-adquirir a os-livros os-estes a livro-de o-adquirido o-este e-a o-escrito e-a סֵ֤פֶר a-pública este e-dar-vos-eles bikli- charesh para eles-se-apresentarão dias muitos');
INSERT INTO verses VALUES (19815, 24, 32, 15, 'que assim disse yhwh exércitos Elohim-de Israel ainda adquiram casas e-campinas e-vindimas na-terra a esta');
INSERT INTO verses VALUES (19816, 24, 32, 16, 'e-eu-orar a yhwh depois-de darás a livro o-adquirimento dizendo bendito filho-de Nerias para-dizer');
INSERT INTO verses VALUES (19817, 24, 32, 17, 'ah Adonai yhwh eis tu tu a os-céus e-a a-terra com-teu-poder a-grande e-em-a-tua-braca ha-netuya não sera-maravilhoso de-vós todo palavra');
INSERT INTO verses VALUES (19818, 24, 32, 18, 'fez hesed para-milhares e-pagando-o iniquidade אָב֔וֹת a KHAK nos-seus-filhos apos-eles o-Elohim a-grande yhwh yhwh exércitos nome-dele');
INSERT INTO verses VALUES (19819, 24, 32, 19, 'grande a-conselho e-muito o-ato-de-fazer que os-vossos-olhos claros sobre homem caminhos filhos-de homem para-dar para-homem segundo-seus-caminhos e-seu-resgate מַעֲלָלָֽיו׃');
INSERT INTO verses VALUES (19820, 24, 32, 20, 'que colocou-te sinais e-maravilhas em-terra-de Egito até o-dia este e-em-Israel e-no-homem e-fazendo- a-você nome como-o-dia a-esta');
INSERT INTO verses VALUES (19821, 24, 32, 21, 'e-tirou a povo-teu a Israel da-terra Egito com-sinais e-com-maravilhas e-na-mão forte e-na-obra estendida e-no-tremor grande');
INSERT INTO verses VALUES (19822, 24, 32, 22, 'e-deu a-eles a a-terra esta que jures-te a-eles terra a-eles terra fluindo-de leite e-mel');
INSERT INTO verses VALUES (19823, 24, 32, 23, 'e-vieram e-ele-herdou אֹתָהּ e-não ouviram na-tua-voz não e-eles-foram a todo que a-eles a-eles não não asú eles a-eles a todo o-mal a esta');
INSERT INTO verses VALUES (19824, 24, 32, 24, 'eis as-muralhas vieram a-cidade para-conquistá-la and-the-city foi-dada em-mão-de os-cashdím os-nilchámim sobre-ela de-diante-de a-espada e a fome e-o-dáver e-que dibartá ser ve-hincha viu');
INSERT INTO verses VALUES (19825, 24, 32, 25, 'e-tu אָמַ֤רְתָּ a-mim Adonai yhwh quneh- a-você הַשֵּׂדֶה com-a-prata e-o-ed edím e-a-cidade nitná na-mão-de הַכַּשְׂדִּֽים׃');
INSERT INTO verses VALUES (19826, 24, 32, 26, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (19827, 24, 32, 27, 'eis eu yhwh Elohim-de todo carne hemimenní se-maravilhar todo palavra');
INSERT INTO verses VALUES (19828, 24, 32, 28, 'portanto assim disse yhwh eis-me deu a a-cidade a-esta na-mão-de os-cassitas e-na-mao-de nabucodonozoro rei-de Babel e-capturá-la');
INSERT INTO verses VALUES (19829, 24, 32, 29, 'e-entraram os-cassitas os-de-batalha sobre a-cidade esta e-atingiriam a a-cidade esta com-fogo e-consumi-la e-a as-casas que queimaram sobre telhados-de-eles la-bal e-queimaram נְסָכִים֙ para-Elohim outros para-que הַכְעִסֵֽנִי׃');
INSERT INTO verses VALUES (19830, 24, 32, 30, 'porque foram filhos-de Israel e-filhos-de Judá somente fazendo o-mal que da-juventude-deles porque filhos-de Israel somente irritando de-mim-me биммаасе mãos-deles oráculo-de yhwh');
INSERT INTO verses VALUES (19831, 24, 32, 31, 'que sobre minha-ira era a-mim foi para-mim a-cidade esta desde o-dia que o-dia ela e-até de-cima-de este para-retirar-a de-sobre face-de');
INSERT INTO verses VALUES (19832, 24, 32, 32, 'sobre todo רעה filhos-de Israel e-filhos-de Judá que fizeram para-irritar-me הֵ֤מָּה reis-deles príncipes-deles sacerdotes-deles e-profetas-deles e-homem Judá ו יושבי Jerusalém');
INSERT INTO verses VALUES (19833, 24, 32, 33, 'e-viraram a-mim costas e-não face e-para-instruir eles o-manhã e-para-instruir e-não-há-deles šōmeʿim tomar de correção:');
INSERT INTO verses VALUES (19834, 24, 32, 34, 'e colocaram seus-escarmentos no-casa que נקרא- שמי sobre-ele - para ser sujo,');
INSERT INTO verses VALUES (19835, 24, 32, 35, 'e-construíram a altos הַבַּ֜עַל que no vale filho-de hinom le-haavir a beneyhem e-a bnoteyhem lamolekh que não dei-vos e-não alathah sobre coração-meu para-fazer hatoevah esta para-que a Judá');
INSERT INTO verses VALUES (19836, 24, 32, 36, 'e-agora por-isso assim yhwh yhwh Elohim-de Israel a a-cidade a-esta que vós dizeis foi-dada na-mão-de rei-de Babilônia com-a-espada uberava ubadaver');
INSERT INTO verses VALUES (19837, 24, 32, 37, 'eis-me meqabbatzam de-todo as-áreas que dispersastes nome em-a-ira-meu e-em-o-calor-meu e-no-rancor grande e-voltarei-eles a o-lugar este e-os-estabelecerão em segurança');
INSERT INTO verses VALUES (19838, 24, 32, 38, 'e-sejam a-mim povo; e-eu estarei a-eles para-Elohim');
INSERT INTO verses VALUES (19839, 24, 32, 39, 'וְנָתַתִּ֨י a-eles coração um e-caminho um para-o-timo אוֹתִ֖י todo os-dias a-eles a-eles e-aos-seus-filhos depois-deles');
INSERT INTO verses VALUES (19840, 24, 32, 40, 'e-farei-convenção a-eles aliança eternidade que não voltarei-eu de-a-tras-deles para-bem-fazer-me eles e-a temor-meu para-não no-coração-eles para-não a-ti de-acima-de-mim');
INSERT INTO verses VALUES (19841, 24, 32, 41, 'e-serei-feliz sobre-eles para-bem-fazer eles e-plantare-eles na-terra esta com-verdade em-todo לִבִּ֖י e-em-todo alma-de-mim');
INSERT INTO verses VALUES (19842, 24, 32, 42, 'porque disse yhwh yhwh como היבeti a o-povo este a todo a-maldade eu esta assim eu מביא eu a todo a-boa que eu palavra sobre-eles');
INSERT INTO verses VALUES (19843, 24, 32, 43, 'e-sera-nosso o-campo na-terra esta que vós dizeis devastação ela de-ausência homem homem nitná na-mão-de הַכַּשְׂדִּֽים׃');
INSERT INTO verses VALUES (19844, 24, 32, 44, 'campos com-o-prata e-os-comprará e-escreverá em-o-livro e-segurará e-o-ed testemunhas בְּאֶ֨רֶץ בִּנְיָמִ֜ן e-em-o-circundante Jerusalém e-em-as-cidades Judá e-em-as-cidades o-monte e-em-as-cidades a-plana-terra e-em-as-cidades do-sul porque eu-devolver-ei a o-cativeiro-deles oráculo-de yhwh');
INSERT INTO chapters VALUES (778, 24, 33, 26);
INSERT INTO verses VALUES (19845, 24, 33, 1, 'e-houve palavra-de yhwh a Jeremias segunda e-ele ainda-ele a-prisão dizendo a-chuva para-dizer');
INSERT INTO verses VALUES (19846, 24, 33, 2, 'assim yhwh yhwh yhwh yhwh formador ela-a yhwh yhwh nome-dele');
INSERT INTO verses VALUES (19847, 24, 33, 3, 'chamou a-mim e-eu-te-responderei e-eu-direi a-ti grandes e-em-pedras não sabereis-os-vos');
INSERT INTO verses VALUES (19848, 24, 33, 4, 'que assim disse yhwh Elohim-de Israel sobre casas-as a-cidade esta e-sobre báttei reis-de Judá das-ruínas a das-muralhas e-a a-espada');
INSERT INTO verses VALUES (19849, 24, 33, 5, 'os-vindo para-lutar a הכָּשְׂדִֹים e-para-seus-ministros o-homem corpos-de o-homem que eu-golpeei no meu fogo e-em-minha-ira e-que escondi-me sobre da-cidade a-esta sobre todo רָעָתָֽם׃');
INSERT INTO verses VALUES (19850, 24, 33, 6, 'eis-me subindo- para-ele-a-lhe arcura e-marpea e-refatem a-eles a-eles ateret paz e-verdade');
INSERT INTO verses VALUES (19851, 24, 33, 7, 've-hashbiti a שְׁב֣וּת Judá e-a שְׁב֣וּת Israel e-bnitim ke-varishona');
INSERT INTO verses VALUES (19852, 24, 33, 8, 've-tiharatem de-todo עֲוֺנָ֖ם que chatu- a-mim ve-salachti os-seus-pecados que pecaram- a-mim ואשר transgrediram בי׃');
INSERT INTO verses VALUES (19853, 24, 33, 9, 'e-será a-mim para o nome alegria para-louvor e-para-esplendor a-todo de-povos a-terra que ouvirão a todo eu que eles fez a-eles sobre e-zangar-se-ão sobre todo a-tôváh eu todo a-paz que eu fez a-ela');
INSERT INTO verses VALUES (19854, 24, 33, 10, 'assim disse disse yhwh será-o-ouvido [יִשָּׁמַ֣ע] deste que vós dizendo-os estará-destruído ele sem homem e-não-haverá animal-doméstico nas-cidades Judá e-na-saídas Jerusalém da-alma sem homem e-não-haverá habitante e-de-a animal-doméstico');
INSERT INTO verses VALUES (19855, 24, 33, 11, 'voz sossego e-voz alegria voz noivo e-voz noiva voz dizendo louvem a yhwh exércitos yhwh bom yhwh porque para-sempre bondade-dele yhwh de ação de graças casa yhwh disse yhwh a exílio- a-terra já-primeiro disse yhwh');
INSERT INTO verses VALUES (19856, 24, 33, 12, 'assim yhwh yhwh exércitos será ser-á בַּמָּק֣וֹם este a-destruição de-não-haver homem e-até animal e-em-todo suas-cidades neveh não currais ovelhas-.');
INSERT INTO verses VALUES (19857, 24, 33, 13, 'nas-cidades o-monte nas-cidades da-planície e-nas-cidades o-sul e-na-terra Benjamim e-em-o-circundante Jerusalém e-em-as-cidades Judá até passar-ela o-rebanho sobre mãos-de disse yhwh yhwh');
INSERT INTO verses VALUES (19858, 24, 33, 14, 'eis dias vêm oráculo-de yhwh e-eu-levantarei a a-palavra o-bom que falei-eu a casa Israel e-sobre casa Judá');
INSERT INTO verses VALUES (19859, 24, 33, 15, 'nos-dias aqueles e-no-tempo-de aquela farei-florescer para-David crescerão justiça e fará mishpat e-justica na-terra');
INSERT INTO verses VALUES (19860, 24, 33, 16, 'nos-dias aqueles e será salvo Judá Jerusalém תִּשְׁכּ֣וֹן em segurança e-esta que yhwh a-ela יְהוָה sua justiça');
INSERT INTO verses VALUES (19861, 24, 33, 17, 'porque disse yhwh yhwh não ele-será-cortado para-David homem habitou sobre trono-de casa-de Israel');
INSERT INTO verses VALUES (19862, 24, 33, 18, 'e-para-os-sacerdotes os-levitas não será-cortado homem מִלְּפָנָ֑י que-ele-leva oferta e-ele-fuma oferta sacrifício todo os dias');
INSERT INTO verses VALUES (19863, 24, 33, 19, 'e-houve palavra-de yhwh a');
INSERT INTO verses VALUES (19864, 24, 33, 20, 'assim disse yhwh se vocês-rompem o-dia minha-aliança a-noite e-a estar a-noite וּלְבִלְתִּ֛י estar dia- não em-seu-tempo');
INSERT INTO verses VALUES (19865, 24, 33, 21, 'também minha-aliança será-rompida a Davi servo-meu de-ser- a-ele filho rei sobre o-seu-trono e-a os-leviata os-sacerdotes seus-ministros');
INSERT INTO verses VALUES (19866, 24, 33, 22, 'que não ser-contado exercito os-céus e-não ser-medido o-mar ha-yam multiplicarei grande a semente Davi servo-meu e-a os-levitas ministros-de de-mim');
INSERT INTO verses VALUES (19867, 24, 33, 23, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (19868, 24, 33, 24, 'porventura-não ראית que o-povo este dizendo dizendo duas as-famílias que yhwh yhwh neles e-os-rejeitou e-a meu-povo in-at-zun de-haver ainda nação diante-deles');
INSERT INTO verses VALUES (19869, 24, 33, 25, 'assim disse yhwh se não a-meu-convenção dia vָla-yָla- huq-qo-t céus va''aretz não so-me-thi');
INSERT INTO verses VALUES (19870, 24, 33, 26, 'também descendência ya-a-ko-v והודע a-bdi אֶמְאַ֗ס mi-qqa-hat mi-zza-re-o מֹשְׁלִים a semente Abraão [כִּֽי־*אשוב] ve-ya-a-ko-v porque a sho-bu-tam e-terá-misericórdia-de-eles');
INSERT INTO chapters VALUES (779, 24, 34, 22);
INSERT INTO verses VALUES (19871, 24, 34, 1, 'a-palavra que foi a yhwh de-junto-de yhwh e-Nebucodonosor rei-de Babilônia-separador terra exército-dele sua-mão reinos-de terra reinado mão-sua dizendo העמים guerras sobre Jerusalém e-sobre todo cidades-dele para-dizer');
INSERT INTO verses VALUES (19872, 24, 34, 2, 'assim yhwh yhwh Elohim-de Israel andou e dirás a Zedeias rei a-ele e-dirás disse yhwh disse yhwh eis-me deu a a-cidade esta na-mão-de rei-de Babilônia e queimada em-a-chama');
INSERT INTO verses VALUES (19873, 24, 34, 3, 'e-tu não será-escapará de-a-mão-sua que agarrará será-agarrado e-em-a-sua-mão darás e-as-tuas-olhos a os-olhos-de rei-de בבל verás e-a-sua-boca a a-tua-boca eu e-Babilônia תבא׃');
INSERT INTO verses VALUES (19874, 24, 34, 4, 'somente ouviu palavra-de yhwh Zedeias rei Judá yhwh disse não sobre-ti não tamat pela-espada');
INSERT INTO verses VALUES (19875, 24, 34, 5, 'em-paz morrerás e-com-as-queimadas avós-teus os-reis os-primeiros que eram em-te assim queimariam- para-ti וְה֥וֹי senhor lamentariam- a-ti porque palavra eu דִּבַּרְתִּי oráculo-de yhwh');
INSERT INTO verses VALUES (19876, 24, 34, 6, 'e-ele-falou Jeremias o-profeta a Zedeias rei Judá a todo as-palavras estes em-Jerusalém');
INSERT INTO verses VALUES (19877, 24, 34, 7, 'e-exército rei-de Bavel de-guerra sobre Jerusalém e-sobre todo cidades-de Judá que a a-Lachish e-a opressão porque eis-aqui permaneceram em-cidades-de יְהוּדָה cidades-de Mibzar');
INSERT INTO verses VALUES (19878, 24, 34, 8, 'a-palavra que foi a yhwh de-junto-de yhwh depois-de cortar o-rei Цидкиюху brah-yth a todo a-eles que biriushalaim para-chamar a-eles dhoror');
INSERT INTO verses VALUES (19879, 24, 34, 9, 'para-lancar homem a seu-escravo e-homem a escrava-seu o-hebreu para-não livres para-não servir-a neles no-judeu irmão-seu homem');
INSERT INTO verses VALUES (19880, 24, 34, 10, 'e-eles-ouviram todo os-senhores e-todo o-povo que vieram em-a-convenção para-enviar homem a para-não e-homem a suas-escravas livres para-não servo-de com-eles ainda וַֽיִּשְׁמְע֖וּ e-eles-enviaram');
INSERT INTO verses VALUES (19881, 24, 34, 11, 'וַיָּשׁ֙וּבוּ֙ depois-de assim e-eles-devolveram a os-servos e-a as-escravas que שילחו livres aos-escravos e-las-servas');
INSERT INTO verses VALUES (19882, 24, 34, 12, 'e-houve palavra-de yhwh a yhwh dizendo yhwh');
INSERT INTO verses VALUES (19883, 24, 34, 13, 'assim yhwh yhwh Elohim-de eu eu cortei aliança a vossos pais no-dia saí-lo a-eles da-terra Egito dizendo servos para-dizer');
INSERT INTO verses VALUES (19884, 24, 34, 14, 'desde-fim-de sete dois vocês-enviarão homem a seu-irmão o-hebreu a-ti [וַעֲבָֽדְךָ֙] para-ti e-servirá-te seis dois e-enviarás-o em liberdade de-com-você e-não ouviram vossos-pais a-mim e-não levantaram a ouvido-deles-verso-final');
INSERT INTO verses VALUES (19885, 24, 34, 15, 'e-eles-voltaram-se vós o-dia e-eles-fizeram a o-retido diante de mim para-chamar liberdade homem para-companheiro-seu e-eles-cortaram aliança diante-de-mim em-o-bayit que foi-chamado nome-meu sobre-ele');
INSERT INTO verses VALUES (19886, 24, 34, 16, 'e-eles-voltaram-se e-eles-profanaram a meu nome- e-eles-voltaram homem a seu-aervo e-homem a escrava-seu que eles livres a-vós e-eles-conquistaram a-eles para-ser a-vós aos-escravos e-para-as-escravas');
INSERT INTO verses VALUES (19887, 24, 34, 17, 'por-isso assim yhwh yhwh vós não ouvistes a-mim para chamar liberdade homem para-seu-irmão e-homem para-companheiro-seu a-vós chamou para-vocês liberdade oráculo-de yhwh a a-espada a a-praga a-todo הָרָעָ֔ב a-terra a-vós para-todo a-todo a-terra');
INSERT INTO verses VALUES (19888, 24, 34, 18, 'e-darei a os-homens os-que-passam a em-a-minha-aliança que não estabeleceram a palavras-de a-aliança que cortaram diante-de-mim o-touro entre cortaram para-dois e passaram-se entre depois-deles-verso-final');
INSERT INTO verses VALUES (19889, 24, 34, 19, 'príncipes-de Judá e-príncipes-de Jerusalém os-eunucos e-os-sacerdotes e-tudo povo a-terra os-que-passam entre em-o o-velho');
INSERT INTO verses VALUES (19890, 24, 34, 20, 'e-darei a-eles na-mão-de inimigos-deles וּבְיַ֖ד מְבַקְשֵׁ֣י almas e-será נִבְלָתָם֙ para-alimento לעוף os-céus e-a-de-vaca a-terra');
INSERT INTO verses VALUES (19891, 24, 34, 21, 'e-a tsidkiyahu rei-de Judá e-a de-seus-príncipes אֶתּוֹ na-mão-de inimigos-deles וּבְיַ֖ד מְבַקְשֵׁ֣י almas e-com-a-mão exército rei Babilônia os-subindo de-vocês');
INSERT INTO verses VALUES (19892, 24, 34, 22, 'eis-me ordenando oráculo-de yhwh e-devolver-los a a-cidade esta e-lutaram sobre-ela e-las-capturarem e-as-queimarem no-fogo e-a arei Judá darei seu nome sem habitou');
INSERT INTO chapters VALUES (780, 24, 35, 19);
INSERT INTO verses VALUES (19893, 24, 35, 1, 'a-palavra que foi a yhwh de-junto-de yhwh nos-dias-de Joiaquim filho-de dizendo rei יְהוּדָה para-dizer');
INSERT INTO verses VALUES (19894, 24, 35, 2, 'o-andando a casa os-carros e-tu-falarás a-eles e-os-trazendo-eles yhwh yhwh a uma as-locações-dele e-irrigará-vos eles יָיַן׃');
INSERT INTO verses VALUES (19895, 24, 35, 3, 'e-tomei a Iezaniah filho-de Jeremias filho-de Habatziyah e-a seus-irmãos e-a todo seus filhos e-a todo casa os-carros');
INSERT INTO verses VALUES (19896, 24, 35, 4, '[וָאָבִ֤א] eles casa yhwh a para-a-sala filhos-de chanan filho-de Yigdal-yahu homem o-Elohim que em-o-lado-de para-a-sala os-senhores que de-acima para-a-sala-de Maasei-yahu filho-de [sem-traducao] guardando o véu:');
INSERT INTO verses VALUES (19897, 24, 35, 5, 'e-eu-deti em-frente-de filhos-de casa-de os-carros as-tigelas cheios vinho e-copos e-eu-falei a-eles bebam- יָיַן׃');
INSERT INTO verses VALUES (19898, 24, 35, 6, 'e-disseram não beberemos- que porque Jônadab filho-de carro nosso-pai dizendo não dizendo não bebam- vinho vós וּבְנֵיכֶם até eternidade');
INSERT INTO verses VALUES (19899, 24, 35, 7, 'e-casa não construireis semente não semeareis vinhedo será a-vós que será a-vós porque em-tendas habitareis todo dias-vosso para-que a-terra dias רַבִּים sobre face-de sobre que vós moradores nome');
INSERT INTO verses VALUES (19900, 24, 35, 8, 'e-nos-ouvimos em-a-voz יְהוֹנָדָ֤ב filho-de רֵכָב a-todo para-todo que para-não para-não de-beber do-vinho todo nosso-s-ano nós nossas-mulheres nosso-filhos e-nossas-filhas');
INSERT INTO verses VALUES (19901, 24, 35, 9, 'וּלְבִלְתִּ֛י filhas-de casarim para-a-nostra-sentada e-o-carmelo e-o-sadhe e-o-zera não sera para nós');
INSERT INTO verses VALUES (19902, 24, 35, 10, 'e-nos-estabelecemos em-os-tendas e-nos-ouvimos e-nos-fizemos conforme-tudo que ordenou-nos Jonadab אָבִֽינוּ׃');
INSERT INTO verses VALUES (19903, 24, 35, 11, 'e-houve em-as-ascensões Nabucadnetzar rei-de Babel a a-terra e-nos-dissemos entrai de-diante-de Jerusalém mipnay força הכָּשְׂדִֹים e-por força Arã e-nos-estabelecemos em-Jerusalém');
INSERT INTO verses VALUES (19904, 24, 35, 12, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (19905, 24, 35, 13, 'assim yhwh yhwh exércitos Elohim-de Israel andou e-dirás para-homem Judá e-para-os-habitantes-de ירVASלם porventura-não tomem disciplina para-ouvir a as-minhas-palavras oráculo-de yhwh');
INSERT INTO verses VALUES (19906, 24, 35, 14, 'foi-elevar a palavras-de Yehonadab filho-de Rechav para-não ordenou a -seus-filhos para-não beberes- que e-não bebem até o-dia este porque ouviram a mandamento da pai-deles e-eu eu-falei não o-manhã e-falar e-não ouviram para-mim');
INSERT INTO verses VALUES (19907, 24, 35, 15, 'e-eis-lancei a-vocês a todo meus-servos os-profetas o-levantando e-eis-lancei dizendo voltem-se por-favor homem de-sua-caminho a-malvada e-eles-fazem-bom mais-vossos e-a ireis apos Elohim Achērim para-servi-los e-sede a-vós a-terra que dei a-vós e-aos-vossos-pais e-não voltastes a ouvidas-vos e-não ouviram para-mim');
INSERT INTO verses VALUES (19908, 24, 35, 16, 'que estabeleceram filhos-de Yehonadab filho-de Recabe a mandamento-de pai-deles que mandaram-los não este não ouviram para-mim');
INSERT INTO verses VALUES (19909, 24, 35, 17, 'portanto assim yhwh yhwh Elohim-de exércitos Elohim-de Israel eis-me que traria e-para Judá e-a todo יֽוֹשְׁבֵי Jerusalém a todo a-maldade que falei sobre-eles porque eu-falei a-eles e-não ouvirem eu chamei a-eles e-não responderam-vos');
INSERT INTO verses VALUES (19910, 24, 35, 18, 'e-a-casa-de os-carros disse Jeremias assim yhwh yhwh exércitos Elohim-de Israel porque que ouvireis sobre mandamento Yehonadav Avikem vatsimru a todo [אֶתְכֶֽם׃] vataasu conforme-tudo que ordenou a-vós');
INSERT INTO verses VALUES (19911, 24, 35, 19, 'portanto assim disse yhwh exércitos Elohim-de Israel não yikaret homem leyonadav filho-de rekhab ficou-em-pé ver todo os dias');
INSERT INTO chapters VALUES (781, 24, 36, 32);
INSERT INTO verses VALUES (19912, 24, 36, 1, 'e-houve em-a-ano hareviit Li-yohoyaqim filho-de יֹאשִׁיָּ֖הוּ rei ser foi a-coisa este a yhwh dizendo yhwh para-dizer');
INSERT INTO verses VALUES (19913, 24, 36, 2, 'toma para-vós megilat- Livro- e escreverás a-ela a todo os-dizeres que falei a-ti sobre Israel e-sobre Judá e-sobre o-dia as-nações de-dia eu-falei a-ti de-os-dias Josias e-até o-dia a-esta');
INSERT INTO verses VALUES (19914, 24, 36, 3, 'אוּלַ֤י ouvirem casa Judá a todo a-maldade eu eu חֹשֵׁ֖ב a-eles a-eles para-que voltaram homem de Seus caminhos o-mal e-perdoei para-os-pecados-deles e-para-as-transgressões-deles');
INSERT INTO verses VALUES (19915, 24, 36, 4, 'E-chamou Jeremias a abençoado filho-de Nerias e-ele-escriviu abençoado de-boca-de Jeremias yhwh todo a-ele yhwh que palavra a-ele sobre rol-de livro');
INSERT INTO verses VALUES (19916, 24, 36, 5, 'e-ele-mandou Jeremias a dizendo dizendo eu não não pode para-vir yhwh yhwh');
INSERT INTO verses VALUES (19917, 24, 36, 6, 'e-vens tu וְקָרָ֣אתָ na-rola que escreveste-de yhwh a palavras yhwh yhwh o-povo casa yhwh no-dia jejuem e-tambem em-os-ouvidos-de todo יְהוּדָה os-que-vêm de-suas-cidades tiqura-ê-m');
INSERT INTO verses VALUES (19918, 24, 36, 7, 'אוּלַ֞י [תִּפֹּ֤ל] techinat-am diante-de yhwh e-voltarão homem de Seus caminhos a má porque grande ha-af ve-ha-chemah yhwh palavra yhwh a o-povo a-esta');
INSERT INTO verses VALUES (19919, 24, 36, 8, 'E-fez barukh filho-de neriyah conforme-tudo que ordenou-o Jeremias o-profeta liqro yhwh palavras-de yhwh casa yhwh');
INSERT INTO verses VALUES (19920, 24, 36, 9, 'e-houve bas-hanah ha-chamishit Liyoqim filho-de Yošiyyahu rei-de Judá no-mês o nono Qara''u yhwh diante-de yhwh todo o-povo be-Yerushalaim e-todo o-povo ha-ba''im de-cidades-de יְהוּדָה em-Jerusalém');
INSERT INTO verses VALUES (19921, 24, 36, 10, 'E-chamou Barukh ba-sefer a palavras-de Jeremias yhwh yhwh be-lisqat Gemaryahu filho-de שפן ha-sofer be-ḥatsér o-áltissimo entrada-de porta-de casa-de yhwh o-novo em-o(s)-ouvido(s) todo o-povo');
INSERT INTO verses VALUES (19922, 24, 36, 11, 'E-ouviu Miquéias filho-de Gemariau filho-de yhwh de-cima-de todo palavras-de yhwh de-sobre o-livro');
INSERT INTO verses VALUES (19923, 24, 36, 12, 'e-ele-descerrou casa-de o-rei sobre para-a-câmara הַסּוֹפֵ֔ר e-eis: nome todo os-senhores os-sentados Elisama o-escrevente e-dalaiahu filho-de shemaiahu ve-elnatan filho-de akbor ugmaryahu filho-de yhwh ve-tsidkiyahu filho-de chananyahu e-todo ha-sarim');
INSERT INTO verses VALUES (19924, 24, 36, 13, 'e-contou a-eles mikayhu a todo as-palavras que ouviu bikro bendito no-livro em-os-ouvidos-de o-povo');
INSERT INTO verses VALUES (19925, 24, 36, 14, 'e-enviaram todo os-senhores a bendito a judeu dizendo N-etan-yahou filho-de S-lem-yahou filho-de cushite dizendo a-megila que chamaste E-tomou em-orelhas-de o-povo tomai-a em-mão-tua e-vá E-tomou yhwh filho-de [sem-traducao] a a-megilha em-mão-de-ele E-veio a-eles');
INSERT INTO verses VALUES (19926, 24, 36, 15, 'e-disseram a-ele retornou por-favor e-leram-a em-o-ouvido-nos E-chamou -bar-kh em-os-ouvidos-deles');
INSERT INTO verses VALUES (19927, 24, 36, 16, 'e-houve quando-ouvirem-a a todo as-palavras temeram homem a companheiro-seu e-disseram a bendito a-contaram nagid para-o-rei a todo as-palavras as estas');
INSERT INTO verses VALUES (19928, 24, 36, 17, 'e- bendito dizendo dizendo conta por-favor para-nós eikh katevta a todo as-palavras estes mi-piv-');
INSERT INTO verses VALUES (19929, 24, 36, 18, 'E-disse a-eles bendito mi-piu chamaria a-mim a todo as-palavras estes e-eu kotev sobre o-livro bad-yo-');
INSERT INTO verses VALUES (19930, 24, 36, 19, 'e-disseram os-príncipes a bendito vai tu tu ve-yirmeyahu e-homem a conheceu eles atemu:');
INSERT INTO verses VALUES (19931, 24, 36, 20, 'וַיָּבוּ a o-rei chatserah e-a ha-megilah [אֱלִישָׁמָ֣ע] [הַסֹּפֵ֑ר] [וַיַּגִּ֙ידוּ֙] [בְּאָזְנֵ֣י] [הַמֶּ֔לֶךְ] em-orelhas-de o-rei a todo [sem-traducao]');
INSERT INTO verses VALUES (19932, 24, 36, 21, 'e-enviou o-rei a [לָקַ֙חַת֙] [אֶת־הַמְּגִלָּ֔ה] a [מִלִּשְׁכַּ֖ת] [אֱלִישָׁמָ֣ע] [הַסֹּפֵ֑ר] [וַיִּקְרָאֶ֤הָ] [יְהוּדִי֙] [בְּאָזְנֵ֣י] [הַמֶּ֔לֶךְ] em-orelhas-de o-rei [הָעֹמְדִ֖ים] de-cima-de os-senhores os-que-estavam-de-pé de-sobre o rei');
INSERT INTO verses VALUES (19933, 24, 36, 22, 'e-o-rei [יוֹשֵׁב֙] casa [הַחֹ֔רֶף] no-mês [הַתְּשִׁיעִ֑י] e-a [לְפָנָ֥יו] לְפָנָ֥יו [sem-traducao]');
INSERT INTO verses VALUES (19934, 24, 36, 23, 'e-houve [׀] [כִּקְר֣וֹא] três [שָׁלֹ֣שׁ] [דְּלָתוֹת֮] [וְאַרְבָּעָה֒] [יִֽקְרָעֶ֙הָ֙] [בְּתַ֣עַר] [הַסֹּפֵ֔ר] a [אֶל־הָאֵ֖שׁ] que a [עַד־תֹּם֙] até [עַל־הָאֵ֖שׁ] todo [עַל־הָאָֽח] sobre que sobre');
INSERT INTO verses VALUES (19935, 24, 36, 24, 'e-não [פָחֲד֔וּ] e-não [קָרְע֖וּ] a [הַמֶּ֙לֶךְ֙] o-rei e-todo seus-servos [כָּל־הַדְּבָרִ֖ים] a todo');
INSERT INTO verses VALUES (19936, 24, 36, 25, 'e-também [אֶלְנָתָ֨ן] [וּדְלָיָ֤הוּ] [וּגְמַרְיָ֙הוּ֙] [הִפְגִּ֣עוּ] [בַמֶּ֔לֶךְ] para-não [שְׂרֹ֖ף] a [וְלֹ֥א] e-não ouviu a-eles');
INSERT INTO verses VALUES (19937, 24, 36, 26, '[וַיְצַוֶּ֣ה] o-rei a [בֶּן־הַמֶּ֜לֶךְ] filho-de o-rei e-a [בֶּֽן־עַבְדְּאֵ֔ל] filho-de [אֶת־בָּר֣וּךְ] e-a e-[OBJ] filho-de [הַנָּבִ֑יא] [וַיַּסְתִּרֵ֖ם] yhwh yhwh dizendo e-a Jeremias a-ele [sem-traducao] yhwh');
INSERT INTO verses VALUES (19938, 24, 36, 27, 'e-houve palavra-de yhwh a Jeremias depois-de [הַמֶּ֗לֶךְ] o-rei a [אֲשֶׁ֨ר] e-a as-palavras que [יִרְמְיָ֖הוּ] dizendo מפי Jeremias para-dizer');
INSERT INTO verses VALUES (19939, 24, 36, 28, 'volta toma a-ti [אַחֶ֑רֶת] אַחֶ֑רֶת [עָלֶ֗יהָ] [OBJ] a todo palavras-as [הָי֗וּ] que הָי֗וּ sobre [שָׂרַ֖ף] [יְהוֹיָקִ֥ים] que [sem-traducao] Joiás rei-de Judá');
INSERT INTO verses VALUES (19940, 24, 36, 29, 'e-sobre Jehoiãquim rei-de Judá disse yhwh tu yhwh אַתָּה [הַזֹּאת֙] dizendo [מַדּוּעַ֩] esta dizendo dizendo [בֹּֽא־יָב֤וֹא] em-aquela dizendo vem [הַזֹּ֔את] rei-de Babilônia homem a a-terra a-esta [sem-traducao] homem homem וּבְהֵמָֽה׃');
INSERT INTO verses VALUES (19941, 24, 36, 30, 'portanto assim yhwh yhwh sobre Joaquim rei Judá não sera para-ele habitante sobre trono-de no-dia [וְלַקֶּ֥רַח] תִּֽהְיֶ֣ה [sem-traducao] [sem-traducao] no-dia [sem-traducao] na-noite');
INSERT INTO verses VALUES (19942, 24, 36, 31, 'e eu visitaria sobre-ele e-sobre [וְעַל־עֲבָדָ֖יו] e-sobre servos-dele a עֲוֺנָ֑ם e trarei em-eles e-sobre yoshevei Jerusalém e-a homem Judá com todo a má que falei a-eles e-não שָׁמְעֻֽו׃');
INSERT INTO verses VALUES (19943, 24, 36, 32, '[וְיִרְמְיָ֜הוּ] tomou [׀] [מְגִלָּ֣ה] [אַחֶ֗רֶת] a בָּר֣וּךְ filho-de [הַסֹּפֵר֒] [וַיִּכְתֹּ֤ב] וַיִּכְתֹּ֤ב sobre-ela de-boca-de Jeremias a todo palavras-de ha-sefer que [מֶֽלֶךְ־יְהוּדָ֖ה] Joiás rei-de Judá no-fogo e-mais [רַבִּ֖ים] sobre-eles דְּבָרִ֥ים muitos [sem-traducao]');
INSERT INTO chapters VALUES (782, 24, 37, 21);
INSERT INTO verses VALUES (19944, 24, 37, 1, 'e-ele-reinou- rei Zedeias debaixo yoashiyahu תַּ֗חַת [אֲשֶׁ֥ר] filho-de [נְבוּכַדְרֶאצַּ֥ר] que [בְּאֶ֥רֶץ] Nabucadnetzar rei-de Babel em-terra-de Judá');
INSERT INTO verses VALUES (19945, 24, 37, 2, 'e-não ouviu ele [וַעֲבָדָ֖יו] [וְעַ֣ם] a-terra a yhwh yhwh que palavra na-mão-de [הַנָּבִֽיא]');
INSERT INTO verses VALUES (19946, 24, 37, 3, 'e-enviou o-rei [צִדְקִיָּ֜הוּ] a [בֶּן־שֶֽׁלֶמְיָ֗ה] filho-de [בֶן־מַֽעֲשֵׂיָה֙] e-a [אֶל־יִרְמְיָ֥הוּ] filho-de dizendo o-sacerdote a Jeremias o-profeta dizendo [sem-traducao] por-favor [sem-traducao] a yhwh Elohim-nosso');
INSERT INTO verses VALUES (19947, 24, 37, 4, '[וְיִרְמְיָ֕הוּ] veio [וְיֹצֵ֖א] no-meio-de o-povo e-não ele ele casa');
INSERT INTO verses VALUES (19948, 24, 37, 5, '[וְחֵ֥יל] פַּרְעֹה sair de-Egito [וַיִּשְׁמְע֨וּ] os caldeus os inimigos sobre Jerusalém a de-cima-de [יְרוּשָׁלָֽ͏ִם׃] de-sobre Jerusalém');
INSERT INTO verses VALUES (19949, 24, 37, 6, 'e-houve palavra-de yhwh a dizendo');
INSERT INTO verses VALUES (19950, 24, 37, 7, 'assim yhwh yhwh Elohim-de Israel assim תֹֽאמְרוּ a rei Judá [אֵלַ֖י] a-vós eis [׀] [חֵ֣יל] força פַּרְעֹה a-vós a-vós lé''ezráh retornou [מִצְרָֽיִם] Egito');
INSERT INTO verses VALUES (19951, 24, 37, 8, '[וְשָׁ֙בוּ֙] [הַכַּשְׂדִּ֔ים] [וְנִלְחֲמ֖וּ] sobre a-cidade esta [וּשְׂרָפֻ֥הָ] [בָאֵֽשׁ׃]');
INSERT INTO verses VALUES (19952, 24, 37, 9, 'assim disse disse yhwh [אַל־תַּשִּׁ֤אוּ] [נַפְשֹֽׁתֵיכֶם֙] dizendo andou [יֵלְכ֥וּ] מֵעָלֵ֖ינוּ os-cassitas porque não andarao');
INSERT INTO verses VALUES (19953, 24, 37, 10, 'que se [כָּל־חֵ֤יל] todo [הַנִּלְחָמִ֣ים] [אִתְּכֶ֔ם] os-nilchámim convosco neles homens [אִ֤ישׁ] homem [יָק֔וּמוּ] [וְשָֽׂרְפ֛וּ] [אֶת־הָעִ֥יר] a a-cidade a-esta em-a-chama');
INSERT INTO verses VALUES (19954, 24, 37, 11, 'e-foi [בְּהֵֽעָלוֹת֙] força הכָּשְׂדִֹים de-cima-de ירVASלם de-diante-de força פַּרְעֹה');
INSERT INTO verses VALUES (19955, 24, 37, 12, 'e-saiu Jeremias de-Jerusalém para-andar terra Binyamin [לַחֲלִ֥ק] de-lá no-meio-de o-povo');
INSERT INTO verses VALUES (19956, 24, 37, 13, 'e-foi ele no-porta Benjamim e ali בַּ֣עַל [וּשְׁמוֹ֙] [יִרְאִיָּ֔יה] [בֶּן־שֶֽׁלֶמְיָ֖ה] filho-de [וַיִּתְפֹּ֞שׂ] filho-de [הַנָּבִיא֙] dizendo a tu o profeta para-dizer a ha-kasdim tu [sem-traducao]');
INSERT INTO verses VALUES (19957, 24, 37, 14, 'E-disse [יִרְמְיָ֜הוּ] [שֶׁ֗קֶר] Eu não sou [נֹפֵל֙] sobre הכָּשְׂדִֹים e-não a-ele a-ela [יִרְאִיָּיה֙] [בְּיִרְמְיָ֔הוּ] [וַיְבִאֵ֖הוּ] [אֶל־הַשָּׂרִֽים] a [sem-traducao]');
INSERT INTO verses VALUES (19958, 24, 37, 15, '[וַיִּקְצְפ֧וּ] [הַשָּׂרִ֛ים] sobre Jeremias ele a-ele [אוֹת֜וֹ] [בֵּ֣ית] casa [בֵּ֚ית] casa [הַסֹּפֵ֔ר] [כִּֽי־אֹת֥וֹ] porque [לְבֵ֥ית] fizeram segundo-casa-de [sem-traducao]');
INSERT INTO verses VALUES (19959, 24, 37, 16, 'que veio [יִרְמְיָ֛הוּ] a casa [וְאֶל־הַֽחֲנֻ֑[t]יוֹת] e-a [יִרְמְיָ֖הוּ] [יָמִ֥ים] nome');
INSERT INTO verses VALUES (19960, 24, 37, 17, '[וַיִּשְׁלַח֩] [הַמֶּ֨לֶךְ] [צִדְקִיָּ֜הוּ] [וַיִּקָּחֵ֗הוּ] [וַיִּשְׁאָלֵ֨הוּ] o-rei [בְּבֵיתוֹ֙] [בַּסֵּ֔תֶר] E-disse [הֲיֵ֥שׁ] palavra de-junto-de yhwh E-disse Jeremias [יֵ֔שׁ] E-disse na-mão-de rei-de Babilônia');
INSERT INTO verses VALUES (19961, 24, 37, 18, 'E-disse Jeremias a o-rei [מֶה֩] [חָטָ֨אתִֽי] a-ti [וְלַעֲבָדֶ֙יךָ֙] [וְלָעָ֣ם] [הַזֶּ֔ה] este porque [אֶל־בֵּ֥ית] [הַכֶּֽלֶא] a casa');
INSERT INTO verses VALUES (19962, 24, 37, 19, '[*ואיו] que [נְבִ֣יאֵיכֶ֔ם] a-vós a-vós [לּ[t]ֵאמֹ֑ר] rei-de Babilônia sobre-vós e-sobre a-terra [הַזֹּֽאת]');
INSERT INTO verses VALUES (19963, 24, 37, 20, 'e-agora [שְֽׁמַֽע־נָ֖א] por-favor Adonai o-rei [תְחִנָּתִי֙] por-favor [וְאַל־תְּשִׁבֵ֗נִי] [בֵּ֚ית] e-a [הַסֹּפֵ֔ר] casa [אָמ֖וּת] [שָֽׁם] e-não nome');
INSERT INTO verses VALUES (19964, 24, 37, 21, '[וַיְצַוֶּ֞ה] o-rei [צִדְקִיָּ֗הוּ] [וַיַּפְקִ֣דוּ] a [בַּחֲצַ֣ר] [הַמַּטָּרָה֒] [וְנָתֹן֩] a-ele a-ele [לַיּוֹם֙] [מִח֣וּץ] [הָאֹפִ֔ים] de-fora [כָּל־הַלֶּ֖חֶם] até [וַיֵּ֣שֶׁב] todo [בַּחֲצַ֖ר] de');
INSERT INTO chapters VALUES (783, 24, 38, 28);
INSERT INTO verses VALUES (19965, 24, 38, 1, 'E-ouviu [שְׁפַטְיָ֣ה] filho-de [וּגְדַלְיָ֙הוּ֙] [בֶּן־פַּשְׁח֔וּר] filho-de [בֶּן־שֶׁ֣לֶמְיָ֔הוּ] [וּפַשְׁח֖וּר] filho-de [אֶ֨ת־הַדְּבָרִ֔ים] [אֲשֶׁ֧ר] filho-de [מְדַבֵּ֥ר] [OBJ] dizendo que a todo');
INSERT INTO verses VALUES (19966, 24, 38, 2, '[כֹּה֮] disse yhwh [הַיֹּשֵׁב֙] [בָּעִ֣יר] esta [יָמ֕וּת] com-a-espada [בָּרָעָ֣ב] [וּבַדָּ֑בֶר] [וְהַיֹּצֵ֤א] a [*יחיה] [**וְחָיָ֔ה] [וְהָיְתָה־לּ֥וֹ] [נַפְשׁ֛וֹ] [לְשָׁלָ֖ל] [וָחָֽי׃]');
INSERT INTO verses VALUES (19967, 24, 38, 3, '[כֹּ֖ה] disse yhwh [הִנָּתֹ֨ן] [תִּנָּתֵ֜ן] a-cidade [הַזֹּ֗את] [בְּיַ֛ד] [חֵ֥יל] rei-de Babilônia');
INSERT INTO verses VALUES (19968, 24, 38, 4, '[וַיֹּאמְר֨וּ] [הַשָּׂרִ֜ים] a o-rei [נָא֮] [אֶת־הָאִ֣ישׁ] a o-homem [הֽוּא־מְרַפֵּ֡א] porque sobre [הַמִּלְחָמָ֜ה] [הַֽנִּשְׁאָרִ֣ים] [׀] a [הַזֹּ֗את] e-[OBJ] [יְדֵ֣י] [כָל־הָעָ֔ם] [לְדַבֵּ֣ר] [אֲלֵיהֶ֔ם] e-[OBJ] maos-de que o-povo [הָאִ֣ישׁ] a-eles [אֵינֶ֨נּוּ] estes [לְשָׁל֛וֹם] o-homem este que [אִם־לְרָעָֽה] [sem-traducao] [sem-traducao] este porque se [sem-traducao]');
INSERT INTO verses VALUES (19969, 24, 38, 5, 'E-disse o-rei [צִדְקִיָּ֔הוּ] eis ele [כִּֽי־אֵ֣ין] porque não-há o-rei [דָּבָֽר] palavra');
INSERT INTO verses VALUES (19970, 24, 38, 6, '[וַיִּקְח֣וּ] a Jeremias ele a-ele a [מַלְכִּיָּ֣הוּ] [בֶן־הַמֶּ֗לֶךְ] filho-de o-rei que [וַיְשַׁלְּח֥וּ] [אֶֽת־יִרְמְיָ֖הוּ] [בַּחֲבָלִ֑ים] a Jeremias que [אִם־טִ֔יט] não-há águas porque se [sem-traducao] [sem-traducao] Jeremias [sem-traducao]');
INSERT INTO verses VALUES (19971, 24, 38, 7, 'E-ouviu [עֶֽבֶד־מֶ֨לֶךְ] rei [אִ֣ישׁ] homem [וְהוּא֙] e-ele na-casa-de o-rei porque [אֶל־הַבּ֑וֹר] a Jeremias a [בִּנְיָמִֽן]');
INSERT INTO verses VALUES (19972, 24, 38, 8, '[וַיֵּצֵ֥א] [עֶֽבֶד־מֶ֖לֶךְ] rei [הַמֶּ֑לֶךְ] o-rei e-falou dizendo');
INSERT INTO verses VALUES (19973, 24, 38, 9, 'Adonai o-rei [הֵרֵ֜עוּ] [הָאֲנָשִׁ֤ים] estes a todo que fizeram [הַנָּבִ֔יא] o-profeta a que [וַיָּ֤מָת] a de-diante-de E-morreu que [אֵ֥ין] [הַלֶּ֛חֶם] porque não-há');
INSERT INTO verses VALUES (19974, 24, 38, 10, '[וַיְצַוֶּ֣ה] o-rei a [עֶֽבֶד־מֶ֥לֶךְ] rei dizendo dizendo toma [מִזֶּה֙] [שְׁלֹשִׁ֣ים] [אֲנָשִׁ֔ים] [וְֽהַעֲלִ֜יתָ] [אֶֽת־יִרְמְיָ֧הוּ] a [מִן־הַבּ֖וֹר] [בְּטֶ֥רֶם] de');
INSERT INTO verses VALUES (19975, 24, 38, 11, 'E-tomou [׀] rei a [בְּיָד֗וֹ] [וַיָּבֹ֤א] E-veio casa-de o-rei E-tomou debaixo-de [בְּלוֹיֵ֣] E-tomou [**סְחָב֔וֹת] [וּבְלוֹיֵ֖] [מְלָחִ֑ים] [וַיְשַׁלְּ[t]חֵ֧ם] a [אֶל־הַבּ֖וֹר] a');
INSERT INTO verses VALUES (19976, 24, 38, 12, 'E-disse [עֶבֶד־מֶ֨לֶךְ] rei [אֶֽל־יִרְמְיָ֗הוּ] a Jeremias [בְּלוֹאֵ֨י] [הַסְּחָב֤וֹת] [וְהַמְּלָחִים֙] debaixo [אַצִּל֣וֹת] [יָדֶ֔יךָ] debaixo-de [לַחֲבָלִ֑ים] [וַיַּ֥עַשׂ] [יִרְמְיָ֖הוּ] E-fez Jeremias assim');
INSERT INTO verses VALUES (19977, 24, 38, 13, '[וַיִּמְשְׁכ֤וּ] a Jeremias [וַיַּעֲל֥וּ] ele ele de [יִרְמְיָ֔הוּ] [בַּחֲצָ֖ר] Jeremias');
INSERT INTO verses VALUES (19978, 24, 38, 14, '[וַיִּשְׁלַ֞ח] o-rei [צִדְקִיָּ֗הוּ] E-tomou a [הַנָּבִיא֙] a-ele a-ele a [אֲשֶׁ֖ר] o-terceiro yhwh E-disse yhwh E-disse o-rei a Jeremias [דָּבָ֔ר] eu [מִמֶּ֖נִּי] palavra a [sem-traducao] [sem-traducao] palavra');
INSERT INTO verses VALUES (19979, 24, 38, 15, 'E-disse Jeremias a que porque a-ti a-ti acaso-nao [תְּמִיתֵ֑נִי] [וְכִי֙] [אִיעָ֣צְךָ֔] não não [אֵלָֽי] para-mim');
INSERT INTO verses VALUES (19980, 24, 38, 16, '[וַיִּשָּׁבַ֞ע] [הַמֶּ֧לֶךְ] [צִדְקִיָּ֛הוּ] a Jeremias dizendo dizendo vive yhwh que [אֶת־הַנֶּ֤פֶשׁ] [הַזֹּאת֙] a [וְאִם־אֶתֶּנְךָ֗] esta se [הָאֵ֔לֶּה] e-se [מְבַקְשִׁ֖ים] [אֶת־נַפְשֶֽׁךָ׃] que a');
INSERT INTO verses VALUES (19981, 24, 38, 17, 'E-disse Jeremias a [כֹּֽה־אָמַ֣ר] yhwh disse yhwh Elohim-de exércitos Elohim-de Israel se [מֶֽלֶךְ־בָּבֶל֙] [וְחָיְתָ֣ה] a príncipes-de rei-de não [תִשָּׂרֵ֖ף] [בָּאֵ֑שׁ] [וְחָיִ֖תָה] tu não [sem-traducao] no-fogo [sem-traducao] tu [sem-traducao]');
INSERT INTO verses VALUES (19982, 24, 38, 18, 'e-se não [אֶל־שָׂרֵי֙] a [בָּבֶ֔ל] rei Babilônia [הַזֹּאת֙] a-cidade esta na-mão-de [בָּאֵ֑שׁ] [וְאַתָּ֖ה] [לֹֽא־תִמָּלֵ֥ט] [מִיָּדָֽם׃] não [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (19983, 24, 38, 19, 'E-disse o-rei [צִדְקִיָּ֖הוּ] a Jeremias eu [אֶת־הַיְּהוּדִ֗ים] a [נָֽפְלוּ֙] que [פֶּֽן־יִתְּנ֥וּ] a [בְּיָדָ֖ם] [וְהִתְעַלְּלוּ־בִֽי׃] a-ti de-mim-me byeidam [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (19984, 24, 38, 20, 'E-disse Jeremias não [יִתֵּ֑נוּ] [שְֽׁמַֽע־נָ֣א] [׀] com-voz yhwh [לַאֲשֶׁ֤ר] eu palavra a-ti [וְיִ֥יטַב] a-ti [וּתְחִ֥י] [נַפְשֶֽׁךָ]');
INSERT INTO verses VALUES (19985, 24, 38, 21, 'e-se tu tu [זֶ֣ה] este [אֲשֶׁ֥ר] que yhwh yhwh');
INSERT INTO verses VALUES (19986, 24, 38, 22, 'e-eis todo [אֲשֶׁ֤ר] que [בְּבֵ֣ית] na-casa-de rei-de Judá [מֶ֣לֶךְ] a [וְהֵ֣נָּה] rei Babilônia [וְיָכְל֤וּ] a-ti [אַנְשֵׁ֣י] [שְׁלֹמֶ֔ךָ] a-ti homens-de [רַגְלֶ֖ךָ] [נָסֹ֥גוּ] [אָחֽוֹר] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (19987, 24, 38, 23, 'e-[OBJ] todo [מֽוֹצִאִים֙] e-[OBJ] [וְאַתָּ֖ה] [לֹא־תִמָּלֵ֣ט] a que [בְיַ֤ד] não [תִּתָּפֵ֔שׂ] [וְאֶת־הָעִ֥יר] porque [תִּשְׂרֹ֥ף] rei-de e-[OBJ]');
INSERT INTO verses VALUES (19988, 24, 38, 24, 'E-disse [צִדְקִיָּ֜הוּ] a Jeremias homem a conheceu [תָמֽוּת] estes e-não [sem-traducao]');
INSERT INTO verses VALUES (19989, 24, 38, 25, 'e-quando [הַשָּׂרִים֮] [כִּֽי־דִבַּ֣רְתִּי] porque [וּבָ֣אוּ] [אֵלֶ֣יךָ] [וְֽאָמְר֪וּ] a-ti [הַגִּֽידָה־נָּ֨א] [לָ֜נוּ] [מַה־דִּבַּ֧רְתָּ] [אֶל־הַמֶּ֛לֶךְ] [אַל־תְּכַחֵ֥ד] nós [וְלֹ֣א] a o-rei a [הַמֶּֽלֶךְ] e-não palavra');
INSERT INTO verses VALUES (19990, 24, 38, 26, 'e-dirás a-eles [מַפִּיל־אֲנִ֥י] eu [לִפְנֵ֣י] diante-de para-não [הֲשִׁיבֵ֛נִי] [בֵּ֥ית] casa Jonatas [שָֽׁם׃] nome');
INSERT INTO verses VALUES (19991, 24, 38, 27, '[וַיָּבֹ֨אוּ] todo [אֶֽל־יִרְמְיָ֙הוּ֙] a ele [וַיַּגֵּ֤ד] a-eles [כְּכָל־הַדְּבָרִ֣ים] a-eles [אֲשֶׁ֥ר] as-palavras estes que nós que [לֹֽא־נִשְׁמַ֖ע] [הַדָּבָֽר׃] porque não');
INSERT INTO verses VALUES (19992, 24, 38, 28, '[וַיֵּ֤שֶׁב] Jeremias [בַּחֲצַ֣ר] [הַמַּטָּרָ֔ה] até dia que [ס] Jerusalém [כַּאֲשֶׁ֥ר] como [יְרוּשָׁלָֽ͏ִם׃]');
INSERT INTO chapters VALUES (784, 24, 39, 18);
INSERT INTO verses VALUES (19993, 24, 39, 1, '[בַּשָּׁנָ֣ה] [הַ֠תְּשִׁעִית] [לְצִדְקִיָּ֨הוּ] rei-de Judá [הָעֲשִׂרִ֗י] [בָּ֠א] veio [מֶֽלֶךְ־בָּבֶ֤ל] rei-de [אֶל־יְר֣וּשָׁלִַ֔ם] e-todo [עָלֶֽיהָ׃] a');
INSERT INTO verses VALUES (19994, 24, 39, 2, '[בְּעַשְׁתֵּֽי־עֶשְׂרֵ֤ה] [שָׁנָה֙] ano [בַּחֹ֥דֶשׁ] o-quarto [בְּתִשְׁעָ֣ה] [לַחֹ֑דֶשׁ] [הָבְקְעָ֖ה] [הָעִֽיר]');
INSERT INTO verses VALUES (19995, 24, 39, 3, 'e-vieram todo príncipes-de rei-de Babilônia [בְּשַׁ֣עַר] [הַתָּ֑וֶךְ] [נֵרְגַ֣ל] [שַׂר־אֶ֠צֶר] [סַֽמְגַּר־נְב֞וּ] [שַׂר־סְכִ֣ים] [רַב־סָרִ֗יס] [נֵרְגַ֤ל] [שַׂר־אֶ֙צֶר֙] [רַב־מָ֔ג] chefe-de [שָׂרֵ֖י] [מֶ֥לֶךְ] [בָּבֶֽל] e-todo rei');
INSERT INTO verses VALUES (19996, 24, 39, 4, 'e-houve como [רָ֠אָם] [צִדְקִיָּ֨הוּ] rei-de e-tudo [׀] homens-de [הַמִּלְחָמָ֗ה] [וַֽ֠יִּבְרְחוּ] [וַיֵּצְא֨וּ] noite de o-caminho-de jardim [הַמֶּ֔לֶךְ] o-rei entre entre [וַיֵּצֵ֖א] o-caminho-de caminho');
INSERT INTO verses VALUES (19997, 24, 39, 5, '[וַיִּרְדְּפ֨וּ] [חֵיל־כַּשְׂדִּ֜ים] [אַחֲרֵיהֶ֗ם] [וַיַּשִּׂ֣גוּ] [אֶת־צִדְקִיָּהוּ֮] a [יְרֵחוֹ֒] [וַיִּקְח֣וּ] ele [וַֽ֠יַּעֲלֻהוּ] a-ele [מֶֽלֶךְ־בָּבֶ֛ל] a [בְּאֶ֣רֶץ] rei-de Babilônia [אִתּ֖וֹ] na-terra calor-fervente dizendo com-ele [sem-traducao]');
INSERT INTO verses VALUES (19998, 24, 39, 6, '[וַיִּשְׁחַט֩] rei [בָּבֶ֜ל] a filhos-de [בְּרִבְלָ֖ה] [לְעֵינָ֑יו] e-[OBJ] e-[OBJ] todo [שָׁחַ֖ט] Judá [בָּבֶֽל] rei');
INSERT INTO verses VALUES (19999, 24, 39, 7, 'e-[OBJ] [צִדְקִיָּ֖הוּ] [עִוֵּ֑ר] [וַיַּאַסְרֵ֙הוּ֙] [בַּֽנְחֻשְׁתַּ֔יִם] [לָבִ֥יא] ele ele');
INSERT INTO verses VALUES (20000, 24, 39, 8, 'e-[OBJ] casa o-rei e-[OBJ] casa o-povo [בָּאֵ֑שׁ] [וְאֶת־חֹמ֥וֹת] [יְרוּשָׁלַ֖͏ִם] e-[OBJ]');
INSERT INTO verses VALUES (20001, 24, 39, 9, 'e-[OBJ] [יֶ֨תֶר] o-povo [הַנִּשְׁאָרִ֣ים] [בָּעִ֗יר] e-[OBJ] [אֲשֶׁ֣ר] que [עָלָ֔יו] e-[OBJ] e-[OBJ] [הָעָ֖ם] o-povo [הֶגְלָ֛ה] [נְבֽוּזַר־אֲדָ֥ן] [רַב־טַבָּחִ֖ים] [בָּבֶֽל]');
INSERT INTO verses VALUES (20002, 24, 39, 10, 'e-de o-povo [אֲשֶׁ֤ר] que não-há a-eles [נְבוּזַרְאֲדָ֥ן] [רַב־טַבָּחִ֖ים] [בְּאֶ֣רֶץ] chefe-de E-colocou a-eles Judá E-deu no-dia [הַהֽוּא]');
INSERT INTO verses VALUES (20003, 24, 39, 11, 'E-ordenou [נְבוּכַדְרֶאצַּ֥ר] rei-de Babilônia sobre Jeremias [רַב־טַבָּחִ֖ים] dizendo chefe-de E-colocou para-dizer');
INSERT INTO verses VALUES (20004, 24, 39, 12, '[קָחֶ֗נּוּ] [וְעֵינֶ֙יךָ֙] [שִׂ֣ים] sobre-ele e-a a-ele a-ele [רָּ֑ע] que porque [כַּֽאֲשֶׁר֙] [יְדַבֵּ֣ר] a-ti assim fez com-ele');
INSERT INTO verses VALUES (20005, 24, 39, 13, '[וַיִּשְׁלַ֞ח] [נְבֽוּזַרְאֲדָ֣ן] chefe-de [וּנְבֽוּשַׁזְבָּן֙[6]] chefe-de [וְנֵרְגַ֥ל] [שַׂר־אֶ֖צֶר] [רַב־מָ֑ג] e-tudo chefe-de [מֶֽלֶךְ־בָּבֶֽל] e-todo rei-de');
INSERT INTO verses VALUES (20006, 24, 39, 14, '[וַיִּשְׁלְחוּ֩] [וַיִּקְח֨וּ] a [מֵחֲצַ֣ר] [הַמַּטָּרָ֗ה] [וַיִּתְּנ֤וּ] ele ele a [בֶּן־שָׁפָ֔ן] filho-de Aquicam filho-de no-meio-de [הָעָֽם׃] a a-casa e-habitou no-meio-de o-povo');
INSERT INTO verses VALUES (20007, 24, 39, 15, 'e-a ser foi palavra-de yhwh [בַּחֲצַ֥ר] [הַמַּטָּרָ֖ה] dizendo');
INSERT INTO verses VALUES (20008, 24, 39, 16, '[הָל֣וֹךְ] [וְאָמַרְתָּ֡] [לְעֶבֶד־מֶ֨לֶךְ] rei dizendo dizendo yhwh disse yhwh exércitos Elohim-de Israel [**מֵבִ֨יא] a [אֶל־הָעִ֥יר] a a-cidade [וְלֹ֣א] [לְטוֹבָ֑ה] e-sejam [לְפָנֶ֖יךָ] no-dia [הַהֽוּא] no-dia a-aquela');
INSERT INTO verses VALUES (20009, 24, 39, 17, '[וְהִצַּלְתִּ֥יךָ] no-dia-de aquele oráculo-de yhwh e-não [הָֽאֲנָשִׁ֔ים] na-mão-de [יָג֖וֹר] que tu [sem-traducao] de-faces-deles');
INSERT INTO verses VALUES (20010, 24, 39, 18, 'que [מַלֵּט֙] [אֲמַלֶּטְךָ֔] [וּבַחֶ֖רֶב] não [תִפֹּ֑ל] [וְהָיְתָ֨ה] a-ti [נַפְשְׁךָ֙] [לְשָׁלָ֔ל] porque [בִּ֖י] [נְאֻם־יְהוָֽה׃] oráculo-de yhwh');
INSERT INTO chapters VALUES (785, 24, 40, 16);
INSERT INTO verses VALUES (20011, 24, 40, 1, '[הַדָּבָ֞ר] que foi a yhwh de-junto-de yhwh [שַׁלַּ֣ח] ele a-ele [רַב־טַבָּחִ֖ים] chefe-de [בְּקַחְתּ֣וֹ] ele [וְהֽוּא־אָס֤וּר] [בָּֽאזִקִּים֙] no-meio-de [כָּל־גָּל֤וּת] [יְרוּשָׁלִַ֙ם֙] [וִֽיהוּדָ֔ה] [הַמֻּגְלִ֖ים] todo [sem-traducao] Jerusalém e-Yehuda [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20012, 24, 40, 2, 'E-tomou chefe-de [לְיִרְמְיָ֑הוּ] E-disse a-ele yhwh yhwh [דִּבֶּר֙] palavra a [אֶל־הַמָּק֖וֹם] esta a');
INSERT INTO verses VALUES (20013, 24, 40, 3, 'e-trouxe E-fez yhwh como palavra porque [לַֽיהוָה֙] a-yhwh e-não [וְהָיָ֥ה] a-vós e-será a-vós [הַזֶּֽה]');
INSERT INTO verses VALUES (20014, 24, 40, 4, 'e-agora eis [פִתַּחְתִּ֣יךָ] o-dia de [אֲשֶׁ֣ר] que sobre [בְּעֵינֶ֜יךָ] se bom [בָבֶ֗ל] [בֹּ֚א] [וְאָשִׂ֤ים] [אֶת־עֵינִי֙] veio [וְאִם־רַ֧ע] a [לָבֽוֹא־אִתִּ֥י] sobre-ti e-se mau [כָּל־הָאָ֣רֶץ] [לְפָנֶ֔יךָ] [אֶל־ט֨וֹב] [וְאֶל־הַיָּשָׁ֧ר] [בְּעֵינֶ֛יךָ] viu todo a-terra a bom e-a');
INSERT INTO verses VALUES (20015, 24, 40, 5, '[וְעוֹדֶ֣נּוּ] não [וְשֻׁ֡בָה] [אֶל־גְּדַלְיָ֣ה] a [בֶּן־שָׁפָ֡ן] filho-de Aquicam filho-de [בְּעָרֵ֣י] que [וְשֵׁ֤ב] rei-de no-meio-de [הָעָ֔ם] Judá [אֶל־כָּל־הַיָּשָׁ֧ר] com-ele [לָלֶ֖כֶת] o-povo [וַיִּתֶּן־ל֧וֹ] a todo [וּמַשְׂאֵ֖ת] [וַֽיְשַׁלְּחֵֽהוּ] para-andar vai e-ele-deu um chefe-de [sem-traducao] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20016, 24, 40, 6, 'E-veio [יִרְמְיָ֛הוּ] a [בֶן־אֲחִיקָ֖ם] filho-de [וַיֵּ֤שֶׁב] [אִתּוֹ֙] no-meio-de com-ele [הַנִּשְׁאָרִ֖ים] o-povo');
INSERT INTO verses VALUES (20017, 24, 40, 7, '[וַיִּשְׁמְעוּ֩] todo [הַחֲיָלִ֜ים] [אֲשֶׁ֣ר] que [הֵ֚מָּה] [וְאַנְשֵׁיהֶ֔ם] [כִּֽי־הִפְקִ֧יד] porque [אֶת־גְּדַלְיָ֥הוּ] rei-de Babilônia a [׀] filho-de [אִתּ֗וֹ] [אֲנָשִׁ֤ים] [וְנָשִׁים֙] [וָטָ֔ף] com-ele a-terra [מֵאֲשֶׁ֥ר] [לֹֽא־הָגְל֖וּ] [בָּבֶֽלָה] a-terra do-que não [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20018, 24, 40, 8, '[וַיָּבֹ֥אוּ] a [הַמִּצְפָּ֑תָה] [וְיִשְׁמָעֵ֣אל] [בֶּן־נְתַנְיָ֡הוּ] filho-de [וְיוֹנָתָ֣ן] [בְּנֵֽי־קָ֠רֵחַ] [וּשְׂרָיָ֨ה] filhos-de [וּבְנֵ֣י] [׀] filho-de [**עֵיפַ֣י] [הַנְּטֹפָתִ֗י] [וִֽיזַנְיָ֙הוּ֙] [בֶּן־הַמַּ֣עֲכָתִ֔י] filho-de [וְאַנְשֵׁיהֶֽם]');
