INSERT INTO verses VALUES (20056, 24, 42, 12, '[וְאֶתֵּ֥ן] a-vós [רַחֲמִ֖ים] [וְרִחַ֣ם] [אֶתְכֶ֑ם] [וְהֵשִׁ֥יב] vos a');
INSERT INTO verses VALUES (20057, 24, 42, 13, 'e-se [אַתֶּ֔ם] não não [בָּאָ֣רֶץ] na-terra para-não [שְׁמֹ֔עַ] ouviu yhwh yhwh');
INSERT INTO verses VALUES (20058, 24, 42, 14, 'dizendo não que terra Egito [נָב֔וֹא] que não [מִלְחָמָ֔ה] guerra [שׁוֹפָ֖ר] não não [וְלַלֶּ֥חֶם] [לֹֽא־נִרְעָ֖ב] não [נֵשֵֽׁב]');
INSERT INTO verses VALUES (20059, 24, 42, 15, 'e-agora por-isso ouvi palavra-de yhwh remanescente Judá yhwh disse yhwh exércitos Elohim-de Israel se [פְּנֵיכֶם֙] [לָבֹ֣א] [מִצְרַ֔יִם] [וּבָאתֶ֖ם] [לָג֥וּר] Egito nome');
INSERT INTO verses VALUES (20060, 24, 42, 16, 'e-foi a-espada que vós [יְרֵאִ֣ים] [מִמֶּ֔נָּה] nome [תַּשִּׂ֥יג] vos na-terra Egito [וְהָרָעָ֞ב] que [׀] [דֹּאֲגִ֣ים] nós nome [יִדְבַּ֧ק] [אַחֲרֵיכֶ֛ם] Egito [וְשָׁ֥ם] [תָּמֻֽתוּ]');
INSERT INTO verses VALUES (20061, 24, 42, 17, '[וְיִֽהְי֣וּ] todo [אֲשֶׁר־שָׂ֨מוּ] que [לָב֤וֹא] a [לָג֣וּר] [שָׁ֔ם] Egito [בַּחֶ֖רֶב] nome [וּבַדָּ֑בֶר] com-a-espada a-eles [שָׂרִ֣יד] e-não de-diante-de a-eles [אֲשֶׁ֥ר] [אֲנִ֖י] [מֵבִ֥יא] [עֲלֵיהֶֽם׃] que');
INSERT INTO verses VALUES (20062, 24, 42, 18, 'que assim disse yhwh [צְבָאוֹת֮] Elohim-de Israel [כַּאֲשֶׁר֩] [נִתַּ֨ךְ] [אַפִּ֜י] [וַחֲמָתִ֗י] sobre [יְר֣וּשָׁלִַ֔ם] Jerusalém assim [חֲמָתִי֙] minha-furia sobre-vós [מִצְרָ֑יִם] e-sereis [לְאָלָ֤ה] [וּלְשַׁמָּה֙] [וְלִקְלָלָ֣ה] [וּלְחֶרְפָּ֔ה] [וְלֹֽא־תִרְא֣וּ] e-não [אֶת־הַמָּק֖וֹם] ainda a o-lugar a-esta');
INSERT INTO verses VALUES (20063, 24, 42, 19, 'palavra yhwh sobre-vós remanescente Judá a [מִצְרָ֑יִם] Egito conheceu [כִּי־הַעִידֹ֥תִי] porque o-dia');
INSERT INTO verses VALUES (20064, 24, 42, 20, 'que [*התעתים] porque [בְּנַפְשֽׁוֹתֵיכֶם֒] [כִּֽי־אַתֶּ֞ם] [שְׁלַחְתֶּ֣ם] a yhwh [אֱלֹֽהֵיכֶם֙] dizendo [הִתְפַּלֵּ֣ל] [בַּעֲדֵ֔נוּ] a yhwh nosso-Elohim [אֲשֶׁ֨ר] que yhwh yhwh [כֵּ֥ן] assim [וְעָשִֽׂינוּ]');
INSERT INTO verses VALUES (20065, 24, 42, 21, '[וָאַגִּ֥ד] a-vós o-dia e-não [שְׁמַעְתֶּ֗ם] [בְּקוֹל֙] yhwh Elohim-de-vos [וּלְכֹ֖ל] que [אֲלֵיכֶֽם] a-vós');
INSERT INTO verses VALUES (20066, 24, 42, 22, 'e-agora conheceu [תֵּֽדְע֔וּ] que [בַּחֶ֛רֶב] [בָּרָעָ֥ב] [וּבַדֶּ֖בֶר] [תָּמ֑וּתוּ] [בַּמָּקוֹם֙] que [חֲפַצְתֶּ֔ם] [לָב֖וֹא] [לָג֥וּר] nome');
INSERT INTO chapters VALUES (788, 24, 43, 13);
INSERT INTO verses VALUES (20067, 24, 43, 1, 'e-houve [כְּכַלּ֨וֹת] [יִרְמְיָ֜הוּ] [לְדַבֵּ֣ר] a todo yhwh a todo palavras-de yhwh [אֱלֹהֵיהֶ֖ם] que [OBJ] yhwh Elohim-deles a-eles a todo as-palavras as estas');
INSERT INTO verses VALUES (20068, 24, 43, 2, 'E-disse [עֲזַרְיָ֤ה] filho-de [וְיוֹחָנָ֣ן] [בֶּן־קָרֵ֔חַ] filho-de Core e-todo [אֶֽל־יִרְמְיָ֗הוּ] [שֶׁ֚קֶר] tu a não [שְׁלָחֲךָ֞] yhwh [Elohim] dizendo [לֹֽא־תָבֹ֥אוּ] yhwh [לָג֥וּר] dizendo não [sem-traducao] Egito [sem-traducao] nome');
INSERT INTO verses VALUES (20069, 24, 43, 3, 'que [בָּרוּךְ֙] filho-de [מַסִּ֥ית] [אֹתְךָ֖] [בָּ֑נוּ] [לְמַעַן֩] [תֵּ֨ת] [אֹתָ֤נוּ] [בְיַֽד־הַכַּשְׂדִּים֙] [לְהָמִ֣ית] [אֹתָ֔נוּ] [וּלְהַגְל֥וֹת] [אֹתָ֖נוּ] [בָּבֶֽל]');
INSERT INTO verses VALUES (20070, 24, 43, 4, 'e-não ouviu [בֶּן־קָרֵ֜חַ] filho-de [הַחֲיָלִ֛ים] e-todo [בְּק֣וֹל] yhwh e-todo o-povo com-voz yhwh');
INSERT INTO verses VALUES (20071, 24, 43, 5, 'E-tomou [יוֹחָנָ֤ן] filho-de [וְכָל־שָׂרֵ֣י] e-todo príncipes-de [כָּל־שְׁאֵרִ֣ית] a todo remanescente Judá que [לָג֖וּר] de-todo [יְהוּדָֽה] que nome');
INSERT INTO verses VALUES (20072, 24, 43, 6, 'a [וְאֶת־הַנָּשִׁ֣ים] e-[OBJ] [וְאֶת־בְּנ֣וֹת] e-[OBJ] e-[OBJ] e-[OBJ] filhas-de [הִנִּ֙יחַ֙] e-[OBJ] todo [אֶת־גְּדַלְיָ֖הוּ] que [בֶּן־שָׁפָ֑ן] e-[OBJ] chefe-de [הַנָּבִ֔יא] a [בֶּן־נֵרִיָּֽהוּ] filho-de filho-de e-[OBJ] e-[OBJ] filho-de');
INSERT INTO verses VALUES (20073, 24, 43, 7, 'e-vieram terra Egito que não [שָׁמְע֖וּ] com-voz yhwh [וַיָּבֹ֖אוּ] até');
INSERT INTO verses VALUES (20074, 24, 43, 8, 'e-houve palavra-de yhwh a dizendo');
INSERT INTO verses VALUES (20075, 24, 43, 9, 'toma [בְּיָדְךָ֞] pedras [גְּדֹל֗וֹת] [וּטְמַנְתָּ֤ם] [בַּמֶּ֙לֶט֙] [בַּמַּלְבֵּ֔ן] que [בְּפֶ֥תַח] casa-de [בְּתַחְפַּנְחֵ֑ס] [לְעֵינֵ֖י] aos-olhos-de [יְהוּדִֽים] [sem-traducao]');
INSERT INTO verses VALUES (20076, 24, 43, 10, 'e-dirás [אֲלֵיהֶ֡ם] assim yhwh yhwh exércitos Elohim-de Israel eis-me enviou [אֶת־נְבוּכַדְרֶאצַּ֤ר] a [עַבְדִּ֔י] rei-de Babilônia [מִמַּ֛עַל] [לָאֲבָנִ֥ים] [הָאֵ֖לֶּה] [אֲשֶׁ֣ר] [טָמָ֑נְתִּי] estes que [**שַׁפְרִיר֖וֹ] [עֲלֵיהֶֽם] a');
INSERT INTO verses VALUES (20077, 24, 43, 11, '[*ובאה] a terra Egito que [אֲשֶׁ֧ר] [לַמָּ֣וֶת] e-que [וַאֲשֶׁ֤ר] [לַשְּׁבִי֙] e-que [וַאֲשֶׁ֥ר] [לַחֶ֖רֶב]');
INSERT INTO verses VALUES (20078, 24, 43, 12, '[וְהִצַּ֣תִּי] [אֵ֗שׁ] [בְּבָתֵּי֙] Elohim-de Egito [וּשְׂרָפָ֖ם] [וְשָׁבָ֑ם] [וְעָטָה֩] a terra Egito [הָֽרֹעֶה֙] [אֶת־בִּגְד֔וֹ] [וְיָצָ֥א] a [בְּשָׁלֽוֹם]');
INSERT INTO verses VALUES (20079, 24, 43, 13, '[וְשִׁבַּ֗ר] a [בֵּ֣ית] casa [אֲשֶׁ֖ר] que na-terra Egito e-[OBJ] [יִשְׂרֹ֥ף] Elohim-de Egito [sem-traducao] em-a-chama');
INSERT INTO chapters VALUES (789, 24, 44, 30);
INSERT INTO verses VALUES (20080, 24, 44, 1, '[הַדָּבָר֙] que ser a a El todo [בְּאֶ֣רֶץ] [מִצְרָ֑יִם] na-terra Egito [וּבְתַחְפַּנְחֵ֣ס] [וּבְנֹ֔ף] [וּבְאֶ֥רֶץ] [פַּתְר֖וֹס] dizendo');
INSERT INTO verses VALUES (20081, 24, 44, 2, 'assim yhwh yhwh exércitos Elohim-de Israel vós [OBJ] [OBJ] todo [הֵבֵ֙אתִי֙] que [וְעַ֖ל] sobre Jerusalém e-sobre todo o-dia Judá [וְאֵ֥ין] [בָּהֶ֖ם] o-dia');
INSERT INTO verses VALUES (20082, 24, 44, 3, 'de-diante-de [רָעָתָ֗ם] que fizeram [לְהַכְעִסֵ֔נִי] [לָלֶ֣כֶת] [לְקַטֵּ֔ר] para-lavrar [לֵאלֹהִ֣ים] [אֲחֵרִ֑ים] que não [יְדָע֔וּם] [הֵ֖מָּה] vós [וַאֲבֹתֵיכֶֽם]');
INSERT INTO verses VALUES (20083, 24, 44, 4, '[וָאֶשְׁלַ֤ח] [אֲלֵיכֶם֙] a todo meus-servos [וְשָׁלֹ֖חַ] dizendo [אַל־נָ֣א] dizendo a por-favor [הַזֹּ֖את] a [שָׂנֵֽאתִי] [sem-traducao] a-esta que [sem-traducao]');
INSERT INTO verses VALUES (20084, 24, 44, 5, 'e-não [שָֽׁמְעוּ֙] e-não [אֶת־אָזְנָ֔ם] a [מֵרָֽעָתָ֑ם] para-não [קַטֵּ֖ר] [לֵאלֹהִ֥ים] [אֲחֵרִֽים]');
INSERT INTO verses VALUES (20085, 24, 44, 6, '[וַתִּתַּ֤ךְ] minha-furia [וְאַפִּ֔י] [וַתִּבְעַר֙] [בְּעָרֵ֣י] Judá [וּבְחֻצ֖וֹת] [יְרֽוּשָׁלָ֑͏ִם] [וַתִּהְיֶ֛ינָה] [לְחָרְבָּ֥ה] [לִשְׁמָמָ֖ה] [כַּיּ֥וֹם] [הַזֶּֽה׃]');
INSERT INTO verses VALUES (20086, 24, 44, 7, 'e-agora assim yhwh yhwh Elohim-de exércitos Elohim-de Israel [אַתֶּ֨ם] [עֹשִׂ֜ים] [רָעָ֤ה] [גְדוֹלָה֙] [אֶל־נַפְשֹׁ֣תֵכֶ֔ם] a a-vós [אִישׁ־וְאִשָּׁ֛ה] [עוֹלֵ֥ל] homem-de [מִתּ֣וֹךְ] [יְהוּדָ֑ה] para-não do-meio-de a-vós [שְׁאֵרִֽית] [sem-traducao] a-vós [sem-traducao]');
INSERT INTO verses VALUES (20087, 24, 44, 8, '[לְהַכְעִסֵ֙נִי֙] [בְּמַעֲשֵׂ֣י] [יְדֵיכֶ֔ם] [לְקַטֵּ֞ר] [לֵאלֹהִ֤ים] [אֲחֵרִים֙] na-terra Egito que vós [לָג֣וּר] [שָׁ֑ם] nome para-que a-vós a-vós [הֱיֽוֹתְכֶם֙] [לִקְלָלָ֣ה] [וּלְחֶרְפָּ֔ה] [בְּכֹ֖ל] em-todo a-terra a-terra');
INSERT INTO verses VALUES (20088, 24, 44, 9, '[הַֽשְׁכַחְתֶּם֩] a [אֲבוֹתֵיכֶ֜ם] [וְאֶת־רָע֣וֹת] e-[OBJ] [מַלְכֵ֣י] reis-de e-[OBJ] e-[OBJ] [נָשָׁ֔יו] e-[OBJ] e-[OBJ] e-[OBJ] e-[OBJ] [נְשֵׁיכֶ֑ם] [אֲשֶׁ֤ר] que fizeram na-terra Judá [יְרוּשָׁלָֽ͏ִם]');
INSERT INTO verses VALUES (20089, 24, 44, 10, 'não [דֻכְּא֔וּ] até o-dia este e-não [יָרְא֗וּ] e-não [בְתֽוֹרָתִי֙] [וּבְחֻקֹּתַ֔י] [אֲשֶׁר־נָתַ֥תִּי] que [וְלִפְנֵ֥י] [אֲבוֹתֵיכֶֽם׃]');
INSERT INTO verses VALUES (20090, 24, 44, 11, 'portanto assim yhwh yhwh exércitos Elohim-de Israel eis-me nome face-de [לְרָעָ֑ה] [וּלְהַכְרִ֖ית] [אֶת־כָּל־יְהוּדָֽה] a todo');
INSERT INTO verses VALUES (20091, 24, 44, 12, '[וְלָקַחְתִּ֞י] a remanescente Judá que [לָב֣וֹא] [אֶֽרֶץ־מִצְרַיִם֮] para-vir terra-de Egito [כֹ֜ל] nome [מִצְרַ֣יִם] todo [בַּחֶ֤רֶב] [בָּֽרָעָב֙] [יִתַּ֔מּוּ] [מִקָּטֹן֙] [וְעַד־גָּד֔וֹל] [בַּחֶ֥רֶב] [וּבָרָעָ֖ב] e-até e-sejam [לְאָלָ֣ה] [לְשַׁמָּ֔ה] [וְלִקְלָלָ֖ה] [וּלְחֶרְפָּֽה] [sem-traducao] de-diante-de [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20092, 24, 44, 13, '[וּפָקַדְתִּ֗י] sobre [הַיּֽוֹשְׁבִים֙] na-terra Egito como [פָּקַ֖דְתִּי] sobre [בַּחֶ֖רֶב] com-a-espada [וּבַדָּֽבֶר]');
INSERT INTO verses VALUES (20093, 24, 44, 14, 'e-não será [פָּלִ֤יט] [וְשָׂרִיד֙] [לִשְׁאֵרִ֣ית] Judá [הַבָּאִ֥ים] [לָגֽוּר־שָׁ֖ם] nome na-terra Egito [׀] terra Judá que [מְנַשְּׂאִ֤ים] [אֶת־נַפְשָׁם֙] a [לָשֶׁ֣בֶת] [שָׁ֔ם] que nome que não porque se');
INSERT INTO verses VALUES (20094, 24, 44, 15, '[וַיַּעֲנ֣וּ] a Jeremias todo [כִּֽי־מְקַטְּר֤וֹת] [נְשֵׁיהֶם֙] porque [אֲחֵרִ֔ים] [וְכָל־הַנָּשִׁ֥ים] [הָעֹמְד֖וֹת] outros e-todo [וְכָל־הָעָ֛ם] [הַיֹּשְׁבִ֥ים] [בְּאֶֽרֶץ־מִצְרַ֖יִם] grande dizendo o-povo os-que-habitam em-terra-de Egito [sem-traducao] para-dizer');
INSERT INTO verses VALUES (20095, 24, 44, 16, '[הַדָּבָ֛ר] que [אֵלֵ֖ינוּ] [בְּשֵׁ֣ם] yhwh yhwh [שֹׁמְעִ֖ים] [אֵלֶֽיךָ]');
INSERT INTO verses VALUES (20096, 24, 44, 17, 'que fez [נַעֲשֶׂ֜ה] a todo [אֲשֶׁר־יָצָ֣א] que [לְקַטֵּ֞ר] [לִמְלֶ֣כֶת] [הַשָּׁמָיִם֮] [וְהַסֵּֽיךְ־לָ֣הּ] os-céus [כַּאֲשֶׁ֨ר] [עָשִׂ֜ינוּ] [אֲנַ֤חְנוּ] como [מְלָכֵ֣ינוּ] [וְשָׂרֵ֔ינוּ] [בְּעָרֵ֣י] [יְהוּדָ֔ה] [וּבְחֻצ֖וֹת] [יְרוּשָׁלָ֑͏ִם] Judá [וַנִּֽהְיֶ֣ה] Jerusalém [וְרָעָ֖ה] não [רָאִֽינוּ] não');
INSERT INTO verses VALUES (20097, 24, 44, 18, 'e-de [חָדַ֜לְנוּ] [לְקַטֵּ֨ר] [לִמְלֶ֧כֶת] [הַשָּׁמַ֛יִם] os-céus [נְסָכִ֖ים] a-ela [כֹ֑ל] [וּבַחֶ֥רֶב] todo [תָּֽמְנוּ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20098, 24, 44, 19, 'e-quando [מְקַטְּרִים֙] [לִמְלֶ֣כֶת] [הַשָּׁמַ֔יִם] os-céus [לָ֖הּ] a-ela [הֲמִֽבַּלְעֲדֵ֣י] [אֲנָשֵׁ֗ינוּ] [עָשִׂ֨ינוּ] [לָ֤הּ] [כַּוָּנִים֙] [לְהַ֣עֲצִבָ֔הֿ[t]] [וְהַסֵּ֥ךְ] a-ela [נְסָכִֽים׃]');
INSERT INTO verses VALUES (20099, 24, 44, 20, 'E-disse Jeremias a todo o-povo sobre [הָעֹנִ֥ים] ele [דָּבָ֖ר] dizendo todo palavra');
INSERT INTO verses VALUES (20100, 24, 44, 21, 'porventura-não a [אֲשֶׁ֨ר] que [בְּעָרֵ֤י] [יְהוּדָה֙] Judá [יְרוּשָׁלִַ֔ם] [אַתֶּ֧ם] [וַאֲבֽוֹתֵיכֶ֛ם] [מַלְכֵיכֶ֥ם] [וְשָׂרֵיכֶ֖ם] [וְעַ֣ם] a-terra eles eles yhwh yhwh [עַל־לִבּֽוֹ] sobre coração-dele');
INSERT INTO verses VALUES (20101, 24, 44, 22, 'e-não yhwh yhwh ainda de-diante-de [רֹ֣עַ] mau de-diante-de [הַתּוֹעֵבֹ֖ת] [אֲשֶׁ֣ר] que [וַתְּהִ֣י] [אַ֠רְצְכֶם] [לְחָרְבָּ֨ה] [וּלְשַׁמָּ֧ה] [וְלִקְלָלָ֛ה] [מֵאֵ֥ין] sem [כְּהַיּ֥וֹם] [הַזֶּֽה] a-esta');
INSERT INTO verses VALUES (20102, 24, 44, 23, 'de-diante-de que [קִטַּרְתֶּ֜ם] [וַאֲשֶׁ֧ר] [חֲטָאתֶ֣ם] a-yhwh e-não [שְׁמַעְתֶּם֙] com-voz yhwh [וּבְתֹרָת֧וֹ] [וּבְחֻקֹּתָ֛יו] [וּבְעֵדְוֺתָ֖יו] não [הֲלַכְתֶּ֑ם] sobre [קָרָ֥את] [אֶתְכֶ֛ם] [הָרָעָ֥ה] [הַזֹּ֖את] esta [הַזֶּֽה׃] a-esta');
INSERT INTO verses VALUES (20103, 24, 44, 24, 'E-disse Jeremias a e-para o-povo e-a todo [כָּל־יְהוּדָ֕ה] [אֲשֶׁ֖ר] palavra-de yhwh todo que');
INSERT INTO verses VALUES (20104, 24, 44, 25, 'assim disse yhwh [יִשְׂרָאֵ֜ל] dizendo Israel dizendo [וַתְּדַבֵּ֣רְנָה] [בְּפִיכֶם֮] [וּבִידֵיכֶ֣ם] [מִלֵּאתֶ֣ם] [׀] dizendo [עָשֹׂ֨ה] fez [אֶת־נְדָרֵ֗ינוּ] a [נָדַ֙רְנוּ֙] que [לִמְלֶ֣כֶת] [הַשָּׁמַ֔יִם] [וּלְהַסֵּ֥ךְ] os-céus [נְסָכִ֑ים] a-ela [תָּקִ֙ימְנָה֙] [אֶת־נִדְרֵיכֶ֔ם] [וְעָשֹׂ֥ה] a [אֶת־נִדְרֵיכֶֽם׃] [sem-traducao] [sem-traducao] a [sem-traducao]');
INSERT INTO verses VALUES (20105, 24, 44, 26, '[לָכֵן֙] ouvi palavra-de yhwh todo [בְּאֶ֣רֶץ] [מִצְרָ֑יִם] na-terra Egito eis-me [הַגָּדוֹל֙] disse yhwh disse yhwh se [נִקְרָ֣א] [׀] [בְּפִ֣י] [׀] [כָּל־אִ֣ישׁ] todo homem Judá disse vive Adonai yhwh em-todo terra');
INSERT INTO verses VALUES (20106, 24, 44, 27, 'eis-me [שֹׁקֵ֧ד] [עֲלֵיהֶ֛ם] [לְרָעָ֖ה] e-não [לְטוֹבָ֑ה] [וְתַמּוּ֩] todo homem Judá que [בַּחֶ֥רֶב] [וּבָרָעָ֖ב] [עַד־כְּלוֹתָֽם] até');
INSERT INTO verses VALUES (20107, 24, 44, 28, '[וּפְלִיטֵ֨י] espada [יְשֻׁב֨וּן] de terra terra terra Judá homens-de [וְֽיָדְע֞וּ] [כָּל־שְׁאֵרִ֣ית] todo remanescente Judá [לָג֣וּר] [שָׁ֔ם] Egito [יָק֖וּם] nome palavra-de que [sem-traducao] de-mim [sem-traducao]');
INSERT INTO verses VALUES (20108, 24, 44, 29, '[וְזֹאת־לָכֶ֤ם] a-vos [נְאֻם־יְהוָ֔ה] oráculo-de yhwh porque [בַּמָּק֣וֹם] eu sobre-vos [תֵּֽדְע֔וּ] que para-que [יָק֧וּמוּ] porque levantou [לְרָעָֽה׃] [sem-traducao] sobre-vós [sem-traducao]');
INSERT INTO verses VALUES (20109, 24, 44, 30, '[כֹּ֣ה] disse disse yhwh deu a [אֶת־פַּרְעֹ֨ה] [חָפְרַ֤ע] rei-de Egito na-mão-de [וּבְיַ֖ד] [מְבַקְשֵׁ֣י] [נַפְשׁ֑וֹ] sua-alma dei [אֶת־צִדְקִיָּ֣הוּ] a [בְּיַ֨ד] rei-de Judá [אֹיְב֖וֹ] [וּמְבַקֵּ֥שׁ] rei-de');
INSERT INTO chapters VALUES (790, 24, 45, 5);
INSERT INTO verses VALUES (20110, 24, 45, 1, 'a-palavra que palavra [יִרְמְיָ֣הוּ] o-profeta a [בֶּֽן־נֵֽרִיָּ֑ה] filho-de [אֶת־הַדְּבָרִ֨ים] [הָאֵ֤לֶּה] a [מִפִּ֣י] [יִרְמְיָ֔הוּ] sobre [הָֽרְבִעִ֔ית] [לִיהוֹיָקִ֧ים] Jeremias [מֶ֥לֶךְ] [יְהוּדָ֖ה] dizendo filho-de rei');
INSERT INTO verses VALUES (20111, 24, 45, 2, 'assim yhwh yhwh Elohim-de Israel [בָּרֽוּךְ]');
INSERT INTO verses VALUES (20112, 24, 45, 3, '[אָמַ֙רְתָּ֙] [אֽוֹי־נָ֣א] por-favor a-mim yhwh [יָג֖וֹן] yhwh [יָגַ֙עְתִּי֙] sobre [וּמְנוּחָ֖ה] não [מָצָֽאתִי׃] não');
INSERT INTO verses VALUES (20113, 24, 45, 4, '[כֹּ֣ה] [׀] a-ele a-ele disse disse yhwh eis [אֲשֶׁר־בָּנִ֙יתִי֙] eu [הֹרֵ֔ס] e-[OBJ] que [אֲנִ֣י] eu [וְאֶת־כָּל־הָאָ֖רֶץ] e-[OBJ] todo a-terra ela');
INSERT INTO verses VALUES (20114, 24, 45, 5, '[וְאַתָּ֛ה] [תְּבַקֶּשׁ־לְךָ֥] [גְדֹל֖וֹת] [אַל־תְּבַקֵּ֑שׁ] que [הִנְנִי֩] porque [רָעָ֤ה] [עַל־כָּל־בָּשָׂר֙] [נְאֻם־יְהוָ֔ה] sobre a-ti [אֶֽת־נַפְשְׁךָ֙] oráculo-de sobre [כָּל־הַמְּקֹמ֖וֹת] [אֲשֶׁ֥ר] a sobre todo que nome');
INSERT INTO chapters VALUES (791, 24, 46, 28);
INSERT INTO verses VALUES (20115, 24, 46, 1, 'que ser palavra-de yhwh a Jeremias o-profeta sobre os-gentios');
INSERT INTO verses VALUES (20116, 24, 46, 2, '[לְמִצְרַ֗יִם] sobre [פַּרְעֹ֤ה] [נְכוֹ֙] [מֶ֣לֶךְ] rei Egito que foi sobre [הִכָּ֗ה] [נְבֽוּכַדְרֶאצַּר֙] [מֶ֣לֶךְ] que [בִּשְׁנַת֙] [הָֽרְבִיעִ֔ית] rei Babilônia [מֶ֥לֶךְ] [יְהוּדָֽה] filho-de rei');
INSERT INTO verses VALUES (20117, 24, 46, 3, '[עִרְכ֤וּ] [מָגֵן֙] [וְצִנָּ֔ה] [וּגְשׁ֖וּ] [לַמִּלְחָמָֽה]');
INSERT INTO verses VALUES (20118, 24, 46, 4, '[אִסְר֣וּ] [הַסּוּסִ֗ים] [וַֽעֲלוּ֙] [הַפָּ֣רָשִׁ֔ים] [וְהִֽתְיַצְּב֖וּ] [בְּכ֥וֹבָעִ֑ים] [מִרְקוּ֙] [הָֽרְמָחִ֔ים] [לִבְשׁ֖וּ] [הַסִּרְיֹנֹֽת]');
INSERT INTO verses VALUES (20119, 24, 46, 5, '[מַדּ֣וּעַ] [רָאִ֗יתִי] [הֵ֣מָּה] [חַתִּים֮] [נְסֹגִ֣ים] [אָחוֹר֒] [וְגִבּוֹרֵיהֶ֣ם] [יֻכַּ֔תּוּ] [וּמָנ֥וֹס] [נָ֖סוּ] e-não [הִפְנ֑וּ] [מָג֥וֹר] [מִסָּבִ֖יב] oráculo-de yhwh');
INSERT INTO verses VALUES (20120, 24, 46, 6, 'a [הַקַּ֔ל] [וְאַל־יִמָּלֵ֖ט] e-a [צָפ֙וֹנָה֙] [עַל־יַ֣ד] [נְהַר־פְּרָ֔ת] sobre mão');
INSERT INTO verses VALUES (20121, 24, 46, 7, '[מִי־זֶ֖ה] este subia [כַּנְּהָר֕וֹת] [יִֽתְגָּעֲשׁ֖וּ] [מֵימָֽיו]');
INSERT INTO verses VALUES (20122, 24, 46, 8, 'Egito [כַּיְאֹ֣ר] subia [וְכַנְּהָר֖וֹת] [יִתְגֹּ֣עֲשׁוּ] águas E-disse [אַֽעֲלֶה֙] [אֲכַסֶּה־אֶ֔רֶץ] terra [עִ֖יר] cidade [בָֽהּ]');
INSERT INTO verses VALUES (20123, 24, 46, 9, '[עֲל֤וּ] [הַסּוּסִים֙] [וְהִתְהֹלְל֣וּ] [הָרֶ֔כֶב] [וְיֵצְא֖וּ] [הַגִּבּוֹרִ֑ים] [כּ֤וּשׁ] [וּפוּט֙] [תֹּפְשֵׂ֣י] [מָגֵ֔ן] [וְלוּדִ֕ים] [תֹּפְשֵׂ֖י] [דֹּ֥רְכֵי] [קָֽשֶׁת]');
INSERT INTO verses VALUES (20124, 24, 46, 10, '[וְֽהַיּ֨וֹם] [הַה֜וּא] [לַאדֹנָ֧י] yhwh exércitos dia [נְקָמָה֙] [לְהִנָּקֵ֣ם] [מִצָּרָ֔יו] [וְאָכְלָ֥ה] espada [וְשָׂ֣בְעָ֔ה] [וְרָוְתָ֖ה] [מִדָּמָ֑ם] que [זֶ֠בַח] [לַאדֹנָ֨י] yhwh exercitos [בְּאֶ֥רֶץ] [צָפ֖וֹן] a rio-de Eufrates');
INSERT INTO verses VALUES (20125, 24, 46, 11, '[עֲלִ֤י] [גִלְעָד֙] [וּקְחִ֣י] [צֳרִ֔י] [בְּתוּלַ֖ת] filha-de Egito [*הרביתי] [**הִרְבֵּ֣ית] [רְפֻא֔וֹת] não-há a-ti');
INSERT INTO verses VALUES (20126, 24, 46, 12, '[שָׁמְע֤וּ] nações [קְלוֹנֵ֔ךְ] [וְצִוְחָתֵ֖ךְ] [מָלְאָ֣ה] a-terra porque [בְּגִבּוֹר֙] [כָּשָׁ֔לוּ] [יַחְדָּ֖יו] [נָפְל֥וּ] [שְׁנֵיהֶֽם׃] dois-deles');
INSERT INTO verses VALUES (20127, 24, 46, 13, '[הַדָּבָר֙] que palavra yhwh a Jeremias [לָב֗וֹא] [נְבֽוּכַדְרֶאצַּר֙] [מֶ֣לֶךְ] rei Babilônia [אֶת־אֶ֥רֶץ] a terra');
INSERT INTO verses VALUES (20128, 24, 46, 14, '[הַגִּ֤ידוּ] [בְמִצְרַ֙יִם֙] [וְהַשְׁמִ֣יעוּ] [בְמִגְדּ֔וֹל] [וְהַשְׁמִ֥יעוּ] [בְנֹ֖ף] [וּבְתַחְפַּנְחֵ֑ס] [אִמְר֗וּ] [הִתְיַצֵּב֙] [וְהָכֵ֣ן] para-ti porque espada espada');
INSERT INTO verses VALUES (20129, 24, 46, 15, '[מַדּ֖וּעַ] [נִסְחַ֣ף] [אַבִּירֶ֑יךָ] não ficou-em-pé que yhwh [הֲדָפֽוֹ]');
INSERT INTO verses VALUES (20130, 24, 46, 16, '[הִרְבָּ֖ה] [כּוֹשֵׁ֑ל] também [אִ֣ישׁ] homem a [ק֣וּמָה] [׀] [וְנָשֻׁ֣בָה] [אֶל־עַמֵּ֗נוּ] a [מֽוֹלַדְתֵּ֔נוּ] de-diante-de espada [הַיּוֹנָֽה]');
INSERT INTO verses VALUES (20131, 24, 46, 17, '[קָרְא֖וּ] nome [פַּרְעֹ֤ה] rei-de Egito [הֶעֱבִ֖יר] [הַמּוֹעֵֽד]');
INSERT INTO verses VALUES (20132, 24, 46, 18, 'vive [נְאֻם־הַמֶּ֔לֶךְ] yhwh o-rei yhwh que seu-nome porque [וּכְכַרְמֶ֖ל] [בַּיָּ֥ם] [יָבֽוֹא]');
INSERT INTO verses VALUES (20133, 24, 46, 19, '[כְּלֵ֤י] [גוֹלָה֙] [עֲשִׂ֣י] para-ti [יוֹשֶׁ֖בֶת] filha-de Egito porque [תִֽהְיֶ֔ה] [וְנִצְּתָ֖ה] sera [יוֹשֵֽׁב׃] sem [sem-traducao]');
INSERT INTO verses VALUES (20134, 24, 46, 20, '[עֶגְלָ֥ה] [יְפֵֽה־פִיָּ֖ה] [מִצְרָ֑יִם] Egito [מִצָּפ֖וֹן] [בָּ֥א] veio veio');
INSERT INTO verses VALUES (20135, 24, 46, 21, 'também [בְקִרְבָּהּ֙] [כְּעֶגְלֵ֣י] [מַרְבֵּ֔ק] [כִּֽי־גַם־הֵ֧מָּה] porque também [יַחְדָּ֖יו] não [עָמָ֑דוּ] que dia [אֵידָ֛ם] porque dia [עֵ֥ת] veio');
INSERT INTO verses VALUES (20136, 24, 46, 22, '[קוֹלָ֖הּ] [כַּנָּחָ֣שׁ] [יֵלֵ֑ךְ] porque [יֵלֵ֔כוּ] irao [בָּ֣אוּ] [לָ֔הּ] [כְּחֹטְבֵ֖י] [עֵצִֽים] [sem-traducao]');
INSERT INTO verses VALUES (20137, 24, 46, 23, '[כָּרְת֤וּ] [יַעְרָהּ֙] oráculo-de que não não que porque [מֵֽאַרְבֶּ֔ה] [וְאֵ֥ין] a-eles a-eles');
INSERT INTO verses VALUES (20138, 24, 46, 24, '[הֹבִ֖ישָׁה] filha-de Egito [בְּיַ֥ד] na-mão-de com');
INSERT INTO verses VALUES (20139, 24, 46, 25, 'disse yhwh exércitos Elohim-de Israel eis-me [פוֹקֵד֙] a [מִנֹּ֔א] [וְעַל־פַּרְעֹה֙] e-sobre [וְעַל־אֱלֹהֶ֖יהָ] e-sobre Egito e-sobre [הַבֹּטְחִ֖ים] e-sobre [sem-traducao] e-sobre Faraó e-sobre [sem-traducao] em-ele');
INSERT INTO verses VALUES (20140, 24, 46, 26, '[וּנְתַתִּ֗ים] [בְּיַד֙] [מְבַקְשֵׁ֣י] [נַפְשָׁ֔ם] e-na-mao-de [נְבֽוּכַדְרֶאצַּ֥ר] rei-de Babilônia [וְאַחֲרֵי[t]] [כֵ֛ן] [תִּשְׁכֹּ֥ן] [כִּֽימֵי־קֶ֖דֶם] [נְאֻם־יְהוָֽה׃] ao-norte oráculo-de yhwh');
INSERT INTO verses VALUES (20141, 24, 46, 27, '[וְ֠אַתָּה] a [עַבְדִּ֤י] [יַֽעֲקֹב֙] Jacó e-a que Israel porque eis-me [וְאֶֽת־זַרְעֲךָ֖] [מֵאֶ֣רֶץ] e-[OBJ] [וְשָׁ֧ב] da-terra [וְשָׁקַ֥ט] [וְשַׁאֲנַ֖ן] [וְאֵ֥ין] [מַחֲרִֽיד׃]');
INSERT INTO verses VALUES (20142, 24, 46, 28, 'tu a [עַבְדִּ֤י] [יַֽעֲקֹב֙] Jacó que yhwh porque que eu porque [בְּכָֽל־הַגּוֹיִ֣ם] [׀] em-todo [הִדַּחְתִּ֣יךָ] que [וְאֹֽתְךָ֙] [לֹא־אֶעֱשֶׂ֣ה] [כָלָ֔ה] não [לַמִּשְׁפָּ֔ט] [וְנַקֵּ֖ה] não [אֲנַקֶּֽךָּ׃] não');
INSERT INTO chapters VALUES (792, 24, 47, 7);
INSERT INTO verses VALUES (20143, 24, 47, 1, 'que ser palavra-de yhwh a Jeremias [בְּטֶ֛רֶם] a filisteus [אֶת־עַזָּֽה׃] ferir dizendo a [sem-traducao]');
INSERT INTO verses VALUES (20144, 24, 47, 2, '[כֹּ֣ה] disse disse yhwh águas [עֹלִ֤ים] [מִצָּפוֹן֙] e-sejam [לְנַ֣חַל] [שׁוֹטֵ֔ף] terra terra cidade [עִ֖יר] [וְיֹ֣שְׁבֵי] [בָ֑הּ] o-homem o-homem todo [כֹּ֖ל] a-terra');
INSERT INTO verses VALUES (20145, 24, 47, 3, '[מִקּ֗וֹל] [שַֽׁעֲטַת֙] [פַּרְס֣וֹת] [אַבִּירָ֔יו] [מֵרַ֣עַשׁ] [לְרִכְבּ֔וֹ] [הֲמ֖וֹן] [גַּלְגִּלָּ֑יו] não [אָבוֹת֙] [אֶל־בָּנִ֔ים] a [יָדָֽיִם]');
INSERT INTO verses VALUES (20146, 24, 47, 4, 'sobre [הַבָּא֙] [לִשְׁד֣וֹד] [אֶת־כָּל־פְּלִשְׁתִּ֔ים] a todo [וּלְצִיד֔וֹן] [כֹּ֖ל] [שָׂרִ֣יד] [עֹזֵ֑ר] todo yhwh [אֶת־פְּלִשְׁתִּ֔ים] porque [אִ֥י] yhwh a');
INSERT INTO verses VALUES (20147, 24, 47, 5, '[בָּ֤אָה] [קָרְחָה֙] a [נִדְמְתָ֥ה] [אַשְׁקְל֖וֹן] [שְׁאֵרִ֣ית] remanescente [עַד־מָתַ֖י] até');
INSERT INTO verses VALUES (20148, 24, 47, 6, 'ai espada a-yhwh até não não [הֵאָֽסְפִי֙] [אַל־תַּעְרֵ֔ךְ] a [וָדֹֽמִּי] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20149, 24, 47, 7, '[אֵ֣יךְ] [תִּשְׁקֹ֔טִי] [וַֽיהוָ֖ה] [צִוָּה־לָ֑הּ] a-ela a o-mar e-a [יְעָדָֽהּ׃] o-mar nome [sem-traducao]');
INSERT INTO chapters VALUES (793, 24, 48, 47);
INSERT INTO verses VALUES (20150, 24, 48, 1, '[לְמוֹאָ֡ב] assim yhwh yhwh exércitos Elohim-de Israel [אֶל־נְבוֹ֙] que [שֻׁדָּ֔דָה] porque [נִלְכְּדָ֖ה] [קִרְיָתָ֑יִם] [הֹבִ֥ישָׁה] [הַמִּשְׂגָּ֖ב] [וָחָֽתָּה]');
INSERT INTO verses VALUES (20151, 24, 48, 2, 'não-há [עוֹד֮] [תְּהִלַּ֣ת] [מוֹאָב֒] [בְּחֶשְׁבּ֗וֹן] [חָשְׁב֤וּ] sobre-ela maldade [לְכ֖וּ] [וְנַכְרִיתֶ֣נָּה] [מִגּ֑וֹי] também [תִּדֹּ֔מִּי] [אַחֲרַ֖יִךְ] [תֵּ֥לֶךְ] [חָֽרֶב] espada');
INSERT INTO verses VALUES (20152, 24, 48, 3, 'voz [צְעָקָ֖ה] [מֵחֹֽרוֹנָ֑יִם] [שֹׁ֖ד] [וָשֶׁ֥בֶר] grande');
INSERT INTO verses VALUES (20153, 24, 48, 4, '[נִשְׁבְּרָ֖ה] [מוֹאָ֑ב] [הִשְׁמִ֥יעוּ] [זְּעָקָ֖ה]');
INSERT INTO verses VALUES (20154, 24, 48, 5, 'que [מַעֲלֵ֣ה] [*הלחות] [**הַלּוּחִ֔ית] [בִּבְכִ֖י] porque que [בְּמוֹרַ֣ד] [חוֹרֹנַ֔יִם] [צָרֵ֥י] [צַֽעֲקַת־שֶׁ֖בֶר] [שָׁמֵֽעוּ]');
INSERT INTO verses VALUES (20155, 24, 48, 6, '[נֻ֖סוּ] [מַלְּט֣וּ] [נַפְשְׁכֶ֑ם] [וְתִֽהְיֶ֔ינָה] [כַּעֲרוֹעֵ֖ר] [בַּמִּדְבָּֽר]');
INSERT INTO verses VALUES (20156, 24, 48, 7, 'que [יַ֣עַן] [בִּטְחֵ֤ךְ] [בְּמַעֲשַׂ֙יִךְ֙] [וּבְא֣וֹצְרוֹתַ֔יִךְ] também [OBJ] [וְיָצָ֤א] [*כמיש] [**כְמוֹשׁ֙] [בַּגּוֹלָ֔ה] [כֹּהֲנָ֥יו]');
INSERT INTO verses VALUES (20157, 24, 48, 8, 'E-veio [שֹׁדֵ֜ד] a todo não [תִמָּלֵ֔ט] não [הָעֵ֖מֶק] [וְנִשְׁמַ֣ד] [הַמִּישֹׁ֑ר] [אֲשֶׁ֖ר] disse yhwh disse yhwh');
INSERT INTO verses VALUES (20158, 24, 48, 9, '[תְּנוּ־צִ֣יץ] [לְמוֹאָ֔ב] que porque [תֵּצֵ֑א] [וְעָרֶ֙יהָ֙] [לְשַׁמָּ֣ה] [תִֽהְיֶ֔ינָה] [מֵאֵ֥ין] sem [בָּהֵֽן]');
INSERT INTO verses VALUES (20159, 24, 48, 10, 'maldito fez [מְלֶ֥אכֶת] yhwh [רְמִיָּ֑ה] [וְאָר֕וּר] [מֹנֵ֥עַ] [חַרְבּ֖וֹ] [מִדָּֽם]');
INSERT INTO verses VALUES (20160, 24, 48, 11, '[שַׁאֲנַ֨ן] [מוֹאָ֜ב] [מִנְּעוּרָ֗יו] [וְשֹׁקֵ֥ט] ele a [וְלֹֽא־הוּרַ֤ק] e-não [אֶל־כֶּ֔לִי] [וּבַגּוֹלָ֖ה] não [הָלָ֑ךְ] [עַל־כֵּ֗ן] não andou sobre assim não [נָמָֽר׃] não');
INSERT INTO verses VALUES (20161, 24, 48, 12, 'portanto [הִנֵּ֖ה־יָמִ֤ים] dias [נְאֻם־יְהוָ֔ה] oráculo-de yhwh [וְצֵעֻ֑הוּ] a-ele [יָרִ֔יקוּ] [וְנִבְלֵיהֶ֖ם] [יְנַפֵּֽצוּ] árvore [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20162, 24, 48, 13, '[וּבֹ֥שׁ] Moabe [מִכְּמ֑וֹשׁ] [כַּאֲשֶׁר־בֹּ֙שׁוּ֙] [בֵּ֣ית] casa Israel [אֵ֖ל] El');
INSERT INTO verses VALUES (20163, 24, 48, 14, '[אֵ֚יךְ] [תֹּֽאמְר֔וּ] [גִּבּוֹרִ֖ים] [אֲנָ֑חְנוּ] [וְאַנְשֵׁי־חַ֖יִל] [לַמִּלְחָמָֽה]');
INSERT INTO verses VALUES (20164, 24, 48, 15, '[שֻׁדַּ֤ד] [מוֹאָב֙] [וְעָרֶ֣יהָ] subir [וּמִבְחַ֥ר] [בַּֽחוּרָ֖יו] [יָרְד֣וּ] [לַטָּ֑בַח] oráculo-de yhwh yhwh exércitos');
INSERT INTO verses VALUES (20165, 24, 48, 16, '[קָר֥וֹב] [אֵיד־מוֹאָ֖ב] Moabe [וְרָ֣עָת֔וֹ] [מִהֲרָ֖ה] muito');
INSERT INTO verses VALUES (20166, 24, 48, 17, '[נֻ֤דוּ] a-ele todo e-tudo conhecendo [שְׁמ֑וֹ] seu-nome [אֵיכָ֤ה] [נִשְׁבַּר֙] [מַטֵּה־עֹ֔ז] [מַקֵּ֖ל] [תִּפְאָרָֽה]');
INSERT INTO verses VALUES (20167, 24, 48, 18, '[רְדִ֤י] [מִכָּבוֹד֙] [*ישבי] [**וּשְׁבִ֣י] filha-de [יֹשֶׁ֖בֶת] porque [כִּֽי־שֹׁדֵ֤ד] [מוֹאָב֙] subir em-ti [שִׁחֵ֖ת] [מִבְצָרָֽיִךְ]');
INSERT INTO verses VALUES (20168, 24, 48, 19, 'a caminho [וְצַפִּ֖י] [יוֹשֶׁ֣בֶת] [עֲרוֹעֵ֑ר] [שַׁאֲלִי־נָ֣ס] [וְנִמְלָ֔טָה] [אִמְרִ֖י] [מַה־נִּֽהְיָֽתָה]');
INSERT INTO verses VALUES (20169, 24, 48, 20, '[הֹבִ֥ישׁ] Moabe porque [*הילילי] [**הֵילִ֣ילוּ] [׀] porque [**וּֽזְעָ֑קוּ] [הַגִּ֣ידוּ]');
INSERT INTO verses VALUES (20170, 24, 48, 21, '[וּמִשְׁפָּ֥ט] veio a terra [אֶל־חֹל֥וֹן] a [וְעַל־*מופעת] e-a e-sobre');
INSERT INTO verses VALUES (20171, 24, 48, 22, 'e-sobre [וְעַל־נְב֔וֹ] e-sobre [דִּבְלָתָֽיִם] e-sobre casa');
INSERT INTO verses VALUES (20172, 24, 48, 23, 'e-sobre [קִרְיָתַ֛יִם] e-sobre casa [וְעַל־בֵּ֥ית] e-sobre casa');
INSERT INTO verses VALUES (20173, 24, 48, 24, 'e-sobre [וְעַל־בָּצְרָ֑ה] e-sobre [כָּל־עָרֵי֙] terra todo [הָרְחֹק֖וֹת] terra');
INSERT INTO verses VALUES (20174, 24, 48, 25, '[נִגְדְּעָה֙] [קֶ֣רֶן] Moabe [וּזְרֹע֖וֹ] [נִשְׁבָּ֑רָה] oráculo-de yhwh');
INSERT INTO verses VALUES (20175, 24, 48, 26, '[הַשְׁכִּירֻ֕הוּ] que sobre yhwh [וְסָפַ֤ק] [מוֹאָב֙] [בְּקִיא֔וֹ] [וְהָיָ֥ה] e-será [גַּם־הֽוּא] também');
INSERT INTO verses VALUES (20176, 24, 48, 27, '[וְאִ֣ם] [׀] [ל֣וֹא] foi ser a-ti se [אִם־בְּגַנָּבִ֖ים] porque [**נִמְצָ֑א] [כִּֽי־מִדֵּ֧י] nele [בּ֖וֹ]');
INSERT INTO verses VALUES (20177, 24, 48, 28, '[עִזְב֤וּ] [עָרִים֙] [וְשִׁכְנ֣וּ] [בַסֶּ֔לַע] [יֹשְׁבֵ֖י] [מוֹאָ֑ב] [וִֽהְי֣וּ] [כְיוֹנָ֔ה] [תְּקַנֵּ֖ן] [בְּעֶבְרֵ֥י] [פִי־פָֽחַת]');
INSERT INTO verses VALUES (20178, 24, 48, 29, '[שָׁמַ֥עְנוּ] [גְאוֹן־מוֹאָ֖ב] Moabe muito muito [וּגְאוֹנ֛וֹ] [וְגַאֲוָת֖וֹ] [וְרֻ֥ם] [לִבּֽוֹ]');
INSERT INTO verses VALUES (20179, 24, 48, 30, 'eu [יָדַ֙עְתִּי֙] oráculo-de yhwh [וְלֹא־כֵ֑ן] e-não [לֹא־כֵ֥ן] [עָשֽׂוּ] não');
INSERT INTO verses VALUES (20180, 24, 48, 31, 'sobre [עַל־מוֹאָ֣ב] sobre [וּלְמוֹאָ֥ב] [כֻּלֹּ֖ה] [אֶזְעָ֑ק] [אֶל־אַנְשֵׁ֥י] [קִֽיר־חֶ֖רֶשׂ] a');
INSERT INTO verses VALUES (20181, 24, 48, 32, '[מִבְּכִ֨י] [יַעְזֵ֤ר] [אֶבְכֶּה־לָּךְ֙] [הַגֶּ֣פֶן] [שִׂבְמָ֔ה] [נְטִֽישֹׁתַ֙יִךְ֙] [עָ֣בְרוּ] mar até mar [יַעְזֵ֖ר] [נָגָ֑עוּ] [עַל־קֵיצֵ֥ךְ] sobre [שֹׁדֵ֥ד] e-sobre');
INSERT INTO verses VALUES (20182, 24, 48, 33, '[וְנֶאֶסְפָ֨ה] [שִׂמְחָ֥ה] [וָגִ֛יל] [מִכַּרְמֶ֖ל] [וּמֵאֶ֣רֶץ] [מוֹאָ֑ב] [וְיַ֙יִן֙] [מִיקָבִ֣ים] [הִשְׁבַּ֔תִּי] não [הֵידָ֔ד] [הֵידָ֖ד] não não');
INSERT INTO verses VALUES (20183, 24, 48, 34, '[מִזַּעֲקַ֨ת] [חֶשְׁבּ֜וֹן] até [עַד־יַ֙הַץ֙] até [קוֹלָ֔ם] [מִצֹּ֙עַר֙] [עַד־חֹ֣רֹנַ֔יִם] [עֶגְלַ֖ת] até que [גַּם־מֵ֣י] [נִמְרִ֔ים] porque também');
INSERT INTO verses VALUES (20184, 24, 48, 35, '[וְהִשְׁבַּתִּ֥י] [לְמוֹאָ֖ב] oráculo-de yhwh [בָמָ֔ה] [וּמַקְטִ֖יר] [לֵאלֹהָֽיו]');
INSERT INTO verses VALUES (20185, 24, 48, 36, 'sobre [לִבִּ֤י] [לְמוֹאָב֙] [כַּחֲלִלִ֣ים] [יֶהֱמֶ֔ה] [וְלִבִּי֙] [אֶל־אַנְשֵׁ֣י] a homens-de [יֶהֱמֶ֑ה] silencio [יִתְרַ֥ת] [עָשָׂ֖ה] sobre assim [sem-traducao] fez [sem-traducao]');
INSERT INTO verses VALUES (20186, 24, 48, 37, 'que todo cabeça [וְכָל־זָקָ֖ן] e-todo sobre [כָּל־יָדַ֙יִם֙] sobre todo [שָֽׂק] e-sobre');
INSERT INTO verses VALUES (20187, 24, 48, 38, 'sobre todo [מוֹאָ֛ב] Moabe [כֻּלֹּ֣ה] [מִסְפֵּ֑ד] [כִּֽי־שָׁבַ֣רְתִּי] porque [כִּכְלִ֛י] a [בּ֖וֹ] [נְאֻם־יְהוָֽה] não há [sem-traducao] nele oráculo-de yhwh');
INSERT INTO verses VALUES (20188, 24, 48, 39, '[אֵ֥יךְ] [חַ֙תָּה֙] [הֵילִ֔ילוּ] [אֵ֛יךְ] [הִפְנָה־עֹ֥רֶף] [מוֹאָ֖ב] Moabe [וְהָיָ֥ה] e-será Moabe [וְלִמְחִתָּ֖ה] [לְכָל־סְבִיבָֽיו׃] para-todo [sem-traducao]');
INSERT INTO verses VALUES (20189, 24, 48, 40, 'porque disse yhwh eis eis [יִדְאֶ֑ה] [וּפָרַ֥שׂ] [כְּנָפָ֖יו] [אֶל־מוֹאָֽב] a');
INSERT INTO verses VALUES (20190, 24, 48, 41, '[נִלְכְּדָה֙] [הַקְּרִיּ֔וֹת] [וְהַמְּצָד֖וֹת] [נִתְפָּ֑שָׂה] e-foi coração [גִּבּוֹרֵ֤י] [מוֹאָב֙] no-dia aquele [כְּלֵ֖ב] mulher [מְצֵרָֽה]');
INSERT INTO verses VALUES (20191, 24, 48, 42, '[וְנִשְׁמַ֥ד] Moabe [מֵעָ֑ם] que sobre yhwh');
INSERT INTO verses VALUES (20192, 24, 48, 43, '[פַּ֥חַד] [וָפַ֖חַת] [וָפָ֑ח] [עָלֶ֛יךָ] [יוֹשֵׁ֥ב] Moabe oráculo-de yhwh');
INSERT INTO verses VALUES (20193, 24, 48, 44, '[*הניס] [**הַנָּ֞ס] de-diante-de a [יִפֹּ֣ל] [אֶל־הַפַּ֔חַת] de [מִן־הַפַּ֔חַת] [יִלָּכֵ֖ד] [בַּפָּ֑ח] porque [אֵלֶ֧יהָ] [אֶל־מוֹאָ֛ב] a Moabe [נְאֻם־יְהוָֽה] [sem-traducao] oráculo-de yhwh');
INSERT INTO verses VALUES (20194, 24, 48, 45, '[בְּצֵ֥ל] [חֶשְׁבּ֛וֹן] [עָמְד֖וּ] [מִכֹּ֣חַ] [נָסִ֑ים] porque sair [מֵחֶשְׁבּ֗וֹן] [וְלֶֽהָבָה֙] [מִבֵּ֣ין] [סִיח֔וֹן] e-comeste [פְּאַ֣ת] [מוֹאָ֔ב] Moabe [בְּנֵ֥י] filhos-de');
INSERT INTO verses VALUES (20195, 24, 48, 46, '[אוֹי־לְךָ֣] a-ti Moabe [עַם־כְּמ֑וֹשׁ] com [בָנֶ֙יךָ֙] porque [וּבְנֹתֶ֖יךָ] [בַּשִּׁבְיָֽה] [sem-traducao] e-filhas-teu [sem-traducao]');
INSERT INTO verses VALUES (20196, 24, 48, 47, '[וְשַׁבְתִּ֧י] [שְׁבוּת־מוֹאָ֛ב] Moabe [הַיָּמִ֖ים] [נְאֻם־יְהוָ֑ה] oráculo-de yhwh até henah [sem-traducao] Moabe');
INSERT INTO chapters VALUES (794, 24, 49, 39);
INSERT INTO verses VALUES (20197, 24, 49, 1, 'aos-filhos-de [עַמּ֗וֹן] assim disse yhwh [הֲבָנִ֥ים] [אֵין֙] [לְיִשְׂרָאֵ֔ל] se [אֵ֣ין] a-ele a-ele [יָרַ֤שׁ] [מַלְכָּם֙] [אֶת־גָּ֔ד] a [בְּעָרָ֥יו] [יָשָֽׁב] habitou');
INSERT INTO verses VALUES (20198, 24, 49, 2, '[לָכֵ֡ן] eis [יָמִ֨ים] [בָּאִ֜ים] oráculo-de yhwh [אֶל־רַבַּ֨ת] a [תְּרוּעַ֣ת] filhos-de Amon [לְתֵ֣ל] [שְׁמָמָ֔ה] [וּבְנֹתֶ֖יהָ] [בָּאֵ֣שׁ] [תִּצַּ֑תְנָה] [וְיָרַ֧שׁ] [יִשְׂרָאֵ֛ל] [אֶת־יֹרְשָׁ֖יו] disse yhwh a [sem-traducao] disse yhwh');
INSERT INTO verses VALUES (20199, 24, 49, 3, '[הֵילִ֨ילִי] [חֶשְׁבּ֜וֹן] que [שֻׁדְּדָה־עַ֗י] [צְעַקְנָה֮] [בְּנ֣וֹת] filhas-de multiplicai [שַׂקִּ֔ים] [סְפֹ֕דְנָה] [וְהִתְשׁוֹטַ֖טְנָה] [בַּגְּדֵר֑וֹת] que porque [בַּגּוֹלָ֣ה] [יֵלֵ֔ךְ] [כֹּהֲנָ֥יו] [וְשָׂרָ֖יו] [יַחְדָּֽיו]');
INSERT INTO verses VALUES (20200, 24, 49, 4, 'que [בָּֽעֲמָקִ֔ים] [זָ֣ב] [עִמְקֵ֔ךְ] [הַבַּ֖ת] [הַשּֽׁוֹבֵבָ֑ה] [הַבֹּֽטְחָה֙] [בְּאֹ֣צְרֹתֶ֔יהָ] quem quem virá para-mim');
INSERT INTO verses VALUES (20201, 24, 49, 5, '[הִנְנִי֩] [מֵבִ֨יא] [עָלַ֜יִךְ] [פַּ֗חַד] oráculo-de Adonai yhwh exércitos de-todo [אִ֣ישׁ] [לְפָנָ֔יו] homem diante-dele e-não-há');
INSERT INTO verses VALUES (20202, 24, 49, 6, '[וְאַחֲרֵי־כֵ֗ן] [אָשִׁ֛יב] [אֶת־שְׁב֥וּת] a [נְאֻם־יְהוָֽה׃] oráculo-de yhwh');
INSERT INTO verses VALUES (20203, 24, 49, 7, '[לֶאֱד֗וֹם] assim disse yhwh exércitos [הַאֵ֥ין] ainda sabedoria [בְּתֵימָ֑ן] [אָבְדָ֤ה] [עֵצָה֙] [מִבָּנִ֔ים] [נִסְרְחָ֖ה] [חָכְמָתָֽם]');
INSERT INTO verses VALUES (20204, 24, 49, 8, '[נֻ֤סוּ] [הָפְנוּ֙] [הֶעְמִ֣יקוּ] [לָשֶׁ֔בֶת] [יֹשְׁבֵ֖י] [דְּדָ֑ן] que [אֵ֥יד] [עֵשָׂ֛ו] [הֵבֵ֥אתִי] sobre-ele tempo [פְּקַדְתִּֽיו]');
INSERT INTO verses VALUES (20205, 24, 49, 9, 'se [בָּ֣אוּ] para-ti não não [עֽוֹלֵל֑וֹת] [אִם־גַּנָּבִ֥ים] se [הִשְׁחִ֥יתוּ] [דַיָּֽם]');
INSERT INTO verses VALUES (20206, 24, 49, 10, 'porque eu [אֶת־עֵשָׂ֗ו] a [אֶת־מִסְתָּרָ֔יו] [וְנֶחְבָּ֖ה] não [יוּכָ֑ל] [שֻׁדַּ֥ד] sua-semente [וְאֶחָ֥יו] [וּשְׁכֵנָ֖יו] [וְאֵינֶֽנּוּ] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20207, 24, 49, 11, '[עָזְבָ֥ה] [יְתֹמֶ֖יךָ] eu [אֲחַיֶּ֑ה] [וְאַלְמְנֹתֶ֖יךָ] [עָלַ֥י] [תִּבְטָֽחוּ׃]');
INSERT INTO verses VALUES (20208, 24, 49, 12, 'porque assim disse yhwh eis que nao-ha [לִשְׁתּ֤וֹת] [הַכּוֹס֙] [שָׁת֣וֹ] [יִשְׁתּ֔וּ] [וְאַתָּ֣ה] ele ele [תִּנָּקֶ֑ה] não não que porque [תִּשְׁתֶּֽה] [sem-traducao]');
INSERT INTO verses VALUES (20209, 24, 49, 13, 'que [בִ֤י] [נִשְׁבַּ֙עְתִּי֙] oráculo-de yhwh porque [לְחֹ֥רֶב] [וְלִקְלָלָ֖ה] [תִּֽהְיֶ֣ה] [בָצְרָ֑ה] [וְכָל־עָרֶ֥יהָ] [תִהְיֶ֖ינָה] e-todo eternidade');
INSERT INTO verses VALUES (20210, 24, 49, 14, '[שְׁמוּעָ֤ה] [שָׁמַ֙עְתִּי֙] de-junto-de yhwh [וְצִ֖יר] [בַּגּוֹיִ֣ם] [שָׁל֑וּחַ] [הִֽתְקַבְּצוּ֙] [וּבֹ֣אוּ] sobre-ela [וְק֖וּמוּ] [לַמִּלְחָמָֽה]');
INSERT INTO verses VALUES (20211, 24, 49, 15, 'porque eis pequeno [בַּגּוֹיִ֑ם] [בָּז֖וּי] [בָּאָדָֽם]');
INSERT INTO verses VALUES (20212, 24, 49, 16, '[תִּֽפְלַצְתְּךָ֞] [הִשִּׁ֤יא] [אֹתָךְ֙] [זְד֣וֹן] [לִבֶּ֔ךָ] [שֹֽׁכְנִי֙] [בְּחַגְוֵ֣י] [הַסֶּ֔לַע] [תֹּפְשִׂ֖י] altura [גִּבְעָ֑ה] porque [כַּנֶּ֙שֶׁר֙] [קִנֶּ֔ךָ] [מִשָּׁ֥ם] [אֽוֹרִידְךָ֖] [נְאֻם־יְהוָֽה] oráculo-de yhwh');
INSERT INTO verses VALUES (20213, 24, 49, 17, '[וְהָיְתָ֥ה] [אֱד֖וֹם] [לְשַׁמָּ֑ה] todo passando sobre-ela [יִשֹּׁ֥ם] [וְיִשְׁרֹ֖ק] sobre todo [sem-traducao]');
INSERT INTO verses VALUES (20214, 24, 49, 18, '[כְּֽמַהְפֵּכַ֞ת] [סְדֹ֧ם] [וַעֲמֹרָ֛ה] [וּשְׁכֵנֶ֖יהָ] disse yhwh não habitou nome homem e-não [בֶּן־אָדָֽם] filho-de homem');
INSERT INTO verses VALUES (20215, 24, 49, 19, 'eis [כְּאַרְיֵ֞ה] subia [מִגְּא֣וֹן] [הַיַּרְדֵּן֮] a [אֵיתָן֒] [כִּֽי־אַרְגִּ֤יעָה] porque [מֵֽעָלֶ֔יהָ] [וּמִ֥י] [בָח֖וּר] e-quem [אֶפְקֹ֑ד] que quem porque quem [יֹעִידֶ֔נִּי] e-quem [רֹעֶ֔ה] [אֲשֶׁ֥ר] este [לְפָנָֽי׃] que');
INSERT INTO verses VALUES (20216, 24, 49, 20, 'portanto ouvi conselho-de yhwh que [אֶל־אֱד֔וֹם] a [אֲשֶׁ֥ר] [חָשַׁ֖ב] que [תֵימָ֑ן] a habitantes-de [צְעִירֵ֣י] se não [יַשִּׁ֛ים] [עֲלֵיהֶ֖ם] [נְוֵהֶֽם] se não [sem-traducao] sobre-eles [sem-traducao]');
INSERT INTO verses VALUES (20217, 24, 49, 21, '[מִקּ֣וֹל] [נִפְלָ֔ם] [רָעֲשָׁ֖ה] a-terra [צְעָקָ֕ה] [בְּיַם־ס֖וּף] [נִשְׁמַ֥ע] [קוֹלָֽהּ]');
INSERT INTO verses VALUES (20218, 24, 49, 22, 'eis [כַנֶּ֙שֶׁר֙] subia [וְיִדְאֶ֔ה] [וְיִפְרֹ֥שׂ] [כְּנָפָ֖יו] sobre [וְֽ֠הָיָה] e-foi coração [אֱדוֹם֙] no-dia no-dia aquele [אִשָּׁ֥ה] mulher [sem-traducao]');
INSERT INTO verses VALUES (20219, 24, 49, 23, '[לְדַמֶּ֗שֶׂק] [בּ֤וֹשָֽׁה] [חֲמָת֙] [וְאַרְפָּ֔ד] porque [רָעָ֛ה] maldade [נָמֹ֑גוּ] [בַּיָּ֣ם] [דְּאָגָ֔ה] [הַשְׁקֵ֖ט] não não');
INSERT INTO verses VALUES (20220, 24, 49, 24, '[רָפְתָ֥ה] [דַמֶּ֛שֶׂק] [הִפְנְתָ֥ה] [לָנ֖וּס] [וְרֶ֣טֶט] [׀] [הֶחֱזִ֑יקָה] [צָרָ֧ה] [וַחֲבָלִ֛ים] [אֲחָזַ֖תָּה]');
INSERT INTO verses VALUES (20221, 24, 49, 25, '[אֵ֥יךְ] não [עִ֣יר] cidade [**תְּהִלָּ֑ת] [קִרְיַ֖ת]');
INSERT INTO verses VALUES (20222, 24, 49, 26, 'por-isso [יִפְּל֥וּ] [בַחוּרֶ֖יהָ] [בִּרְחֹבֹתֶ֑יהָ] e-todo homens-de [יִדַּ֙מּוּ֙] no-dia no-dia aquele yhwh yhwh');
INSERT INTO verses VALUES (20223, 24, 49, 27, '[וְהִצַּ֥תִּי] [אֵ֖שׁ] [בְּחוֹמַ֣ת] [דַּמָּ֑שֶׂק] e-consumiu palacios filho-de [sem-traducao]');
INSERT INTO verses VALUES (20224, 24, 49, 28, '[לְקֵדָ֣ר] [׀] [וּֽלְמַמְלְכ֣וֹת] que [אֲשֶׁ֤ר] rei-de Babilônia [**נְבֽוּכַדְרֶאצַּ֣ר] disse yhwh disse yhwh a [עֲל֣וּ] [אֶל־קֵדָ֔ר] a filhos-de');
INSERT INTO verses VALUES (20225, 24, 49, 29, '[אָהֳלֵיהֶ֤ם] [וְצֹאנָם֙] [יִקָּ֔חוּ] [יְרִיעוֹתֵיהֶ֧ם] e-todo [וּגְמַלֵּיהֶ֖ם] [יִשְׂא֣וּ] a-eles a-eles [עֲלֵיהֶ֛ם] [מָג֖וֹר] [מִסָּבִֽיב]');
INSERT INTO verses VALUES (20226, 24, 49, 30, '[נֻסוּ֩] [נֻּ֨דוּ] muito [הֶעְמִ֧יקוּ] [לָשֶׁ֛בֶת] [יֹשְׁבֵ֥י] [חָצ֖וֹר] oráculo-de yhwh porque [נְבוּכַדְרֶאצַּ֤ר] sobre-vos [עֵצָ֔ה] rei-de Babilônia [**עֲלֵיכֶ֖ם] [מַחֲשָׁבָֽה] [sem-traducao]');
INSERT INTO verses VALUES (20227, 24, 49, 31, '[ק֣וּמוּ] [עֲל֗וּ] a nação [יוֹשֵׁ֥ב] [לָבֶ֖טַח] [נְאֻם־יְהוָ֑ה] oráculo-de yhwh a-ele [בָּדָ֥ד] e-não');
INSERT INTO verses VALUES (20228, 24, 49, 32, 'e-sejam [גְמַלֵּיהֶ֜ם] [לָבַ֗ז] [וַהֲמ֤וֹן] [מִקְנֵיהֶם֙] [לְשָׁלָ֔ל] [וְזֵרִתִ֥ים] para-todo espírito [פֵאָ֑ה] [וּמִכָּל־עֲבָרָ֛יו] [אָבִ֥יא] [אֶת־אֵידָ֖ם] [נְאֻם־יְהוָֽה] a oráculo-de yhwh');
INSERT INTO verses VALUES (20229, 24, 49, 33, '[וְהָיְתָ֨ה] [חָצ֜וֹר] [לִמְע֥וֹן] [תַּנִּ֛ים] [שְׁמָמָ֖ה] até [לֹֽא־יֵשֵׁ֥ב] não habitou nome homem e-não filho-de homem');
INSERT INTO verses VALUES (20230, 24, 49, 34, 'que ser palavra-de yhwh a [אֶל־עֵילָ֑ם] [בְּרֵאשִׁ֗ית] a [צִדְקִיָּ֥ה] No-princípio dizendo rei-de');
INSERT INTO verses VALUES (20231, 24, 49, 35, 'assim disse yhwh exércitos eis-me [שֹׁבֵ֖ר] a [עֵילָ֑ם] [רֵאשִׁ֖ית] [גְּבוּרָתָֽם] [sem-traducao]');
INSERT INTO verses VALUES (20232, 24, 49, 36, '[וְהֵבֵאתִ֨י] a [אַרְבַּ֣ע] quatro [מֵֽאַרְבַּע֙] [קְצ֣וֹת] [הַשָּׁמַ֔יִם] os-céus a-todo para-todo [הָאֵ֑לֶּה] estes e-não [אֲשֶׁ֛ר] [לֹֽא־יָב֥וֹא] que não virá nome');
INSERT INTO verses VALUES (20233, 24, 49, 37, '[וְהַחְתַּתִּ֣י] a [לִפְנֵ֨י] [אֹיְבֵיהֶ֜ם] [וְלִפְנֵ֣י] [׀] [מְבַקְשֵׁ֣י] [נַפְשָׁ֗ם] [וְהֵבֵאתִ֨י] [עֲלֵיהֶ֧ם] maldade a [אֶת־חֲר֥וֹן] [אַפִּ֖י] oráculo-de yhwh [אַֽחֲרֵיהֶם֙] [אֶת־הַחֶ֔רֶב] até [כַּלּוֹתִ֖י] até');
INSERT INTO verses VALUES (20234, 24, 49, 38, '[וְשַׂמְתִּ֥י] [כִסְאִ֖י] [בְּעֵילָ֑ם] [וְהַאֲבַדְתִּ֥י] [מִשָּׁ֛ם] rei [וְשָׂרִ֖ים] oráculo-de yhwh');
INSERT INTO verses VALUES (20235, 24, 49, 39, '[וְהָיָ֣ה] [׀] [בְּאַחֲרִ֣ית] a [*אשוב] oráculo-de yhwh');
INSERT INTO chapters VALUES (795, 24, 50, 46);
INSERT INTO verses VALUES (20236, 24, 50, 1, 'a-palavra que palavra yhwh a Babilônia a terra [יִרְמְיָ֥הוּ] na-mão-de');
INSERT INTO verses VALUES (20237, 24, 50, 2, '[הַגִּ֨ידוּ] [בַגּוֹיִ֤ם] [וְהַשְׁמִ֙יעוּ֙] [וּֽשְׂאוּ־נֵ֔ס] [הַשְׁמִ֖יעוּ] [אַל־תְּכַחֵ֑דוּ] a [נִלְכְּדָ֨ה] [בָבֶ֜ל] [הֹבִ֥ישׁ] [בֵּל֙] [חַ֣ת] [מְרֹדָ֔ךְ] [הֹבִ֣ישׁוּ] [עֲצַבֶּ֔יהָ] [חַ֖תּוּ] [גִּלּוּלֶֽיהָ]');
INSERT INTO verses VALUES (20238, 24, 50, 3, 'que subir [עָלֶ֨יהָ] nação [מִצָּפ֗וֹן] [הֽוּא־יָשִׁ֤ית] [אֶת־אַרְצָהּ֙] a [וְלֹֽא־יִהְיֶ֥ה] [יוֹשֵׁ֖ב] e-não será [וְעַד־בְּהֵמָ֖ה] [נָ֥דוּ] [הָלָֽכוּ] animal');
INSERT INTO verses VALUES (20239, 24, 50, 4, '[בַּיָּמִ֨ים] [הָהֵ֜מָּה] [וּבָעֵ֤ת] [הַהִיא֙] oráculo-de yhwh [בְנֵֽי־יִשְׂרָאֵ֛ל] filhos-de Israel eles [הָל֤וֹךְ] Judá juntos [וְאֶת־יְהוָ֥ה] [אֱלֹהֵיהֶ֖ם] irao e-[OBJ] yhwh Elohim-deles [sem-traducao]');
INSERT INTO verses VALUES (20240, 24, 50, 5, '[צִיּ֣וֹן] [יִשְׁאָ֔לוּ] o-caminho-de [הֵ֣נָּה] [פְנֵיהֶ֑ם] [בֹּ֚אוּ] [וְנִלְו֣וּ] a yhwh eternidade não não');
INSERT INTO verses VALUES (20241, 24, 50, 6, '[צֹ֤אן] [אֹֽבְדוֹת֙] [*היה] [**הָי֣וּ] [עַמִּ֔י] as-montanhas [הִתְע֔וּם] a [*שובבים] [**שֽׁוֹבְב֑וּם] [מֵהַ֤ר] [אֶל־גִּבְעָה֙]');
INSERT INTO verses VALUES (20242, 24, 50, 7, 'todo [אֲכָל֔וּם] [וְצָרֵיהֶ֥ם] [אָמְר֖וּ] não não debaixo [אֲשֶׁ֨ר] que [לַֽיהוָה֙] a-yhwh [וּמִקְוֵ֥ה] [אֲבֽוֹתֵיהֶ֖ם] yhwh yhwh');
INSERT INTO verses VALUES (20243, 24, 50, 8, '[נֻ֚דוּ] do-meio-de Babilônia [וּמֵאֶ֥רֶץ] [כַּשְׂדִּ֖ים] [*יצאו] [**צֵ֑אוּ] diante-de [כְּעַתּוּדִ֖ים]');
INSERT INTO verses VALUES (20244, 24, 50, 9, 'que eis eu [מֵעִיר֩] [וּמַעֲלֶ֨ה] sobre [קְהַל־גּוֹיִ֤ם] [גְּדֹלִים֙] [מֵאֶ֣רֶץ] [צָפ֔וֹן] da-terra norte [מִשָּׁ֖ם] [תִּלָּכֵ֑ד] [חִצָּיו֙] [כְּגִבּ֣וֹר] [מַשְׁכִּ֔יל] não [יָשׁ֖וּב] não [sem-traducao] vazios');
INSERT INTO verses VALUES (20245, 24, 50, 10, '[וְהָיְתָ֥ה] [כַשְׂדִּ֖ים] [לְשָׁלָ֑ל] todo [יִשְׂבָּ֖עוּ] [נְאֻם־יְהוָֽה] oráculo-de yhwh');
INSERT INTO verses VALUES (20246, 24, 50, 11, 'que porque [**תִשְׂמְחוּ֙] que porque [**תַֽעֲלְז֔וּ] [שֹׁסֵ֖י] [נַחֲלָתִ֑י]');
INSERT INTO verses VALUES (20247, 24, 50, 12, '[בּ֤וֹשָׁה] [אִמְּכֶם֙] muito [חָפְרָ֖ה] [יֽוֹלַדְתְּכֶ֑ם] eis [אַחֲרִ֣ית] nações [מִדְבָּ֖ר] [צִיָּ֥ה] [וַעֲרָבָֽה]');
INSERT INTO verses VALUES (20248, 24, 50, 13, '[מִקֶּ֤צֶף] yhwh não [תֵשֵׁ֔ב] [וְהָיְתָ֥ה] [שְׁמָמָ֖ה] [כֻּלָּ֑הּ] todo passando sobre Babilônia [וְיִשְׁרֹ֖ק] [עַל־כָּל־מַכּוֹתֶֽיהָ] sobre todo [sem-traducao]');
INSERT INTO verses VALUES (20249, 24, 50, 14, '[עִרְכ֨וּ] sobre [׀] ao-redor todo [קֶ֔שֶׁת] [יְד֣וּ] [אֵלֶ֔יהָ] [אַֽל־תַּחְמְל֖וּ] a que a [חָטָֽאָה] porque a-yhwh [sem-traducao]');
INSERT INTO verses VALUES (20250, 24, 50, 15, '[הָרִ֨יעוּ] [עָלֶ֤יהָ] ao-redor deu [יָדָ֔הּ] [נָֽפְלוּ֙] [*אשויתיה] [**אָשְׁיוֹתֶ֔יהָ] porque [חֽוֹמוֹתֶ֑יהָ] que ela yhwh [הִיא֙] como [בָ֔הּ] [כַּאֲשֶׁ֥ר] a-ela');
INSERT INTO verses VALUES (20251, 24, 50, 16, '[כִּרְת֤וּ] [זוֹרֵ֙עַ֙] [מִבָּבֶ֔ל] [וְתֹפֵ֥שׂ] [מַגָּ֖ל] [בְּעֵ֣ת] [קָצִ֑יר] de-diante-de espada [הַיּוֹנָ֔ה] homem a [יִפְנ֔וּ] [וְאִ֥ישׁ] [לְאַרְצ֖וֹ] [יָנֻֽסוּ׃]');
INSERT INTO verses VALUES (20252, 24, 50, 17, '[שֶׂ֧ה] [פְזוּרָ֛ה] Israel [אֲרָי֣וֹת] [הִדִּ֑יחוּ] [הָרִאשׁ֤וֹן] [אֲכָלוֹ֙] rei Assíria [וְזֶ֤ה] [הָאַחֲרוֹן֙] [עִצְּמ֔וֹ] [נְבוּכַדְרֶאצַּ֖ר] rei [בָּבֶֽל׃]');
INSERT INTO verses VALUES (20253, 24, 50, 18, 'portanto assim yhwh yhwh exércitos Elohim-de Israel eis-me [אֶל־מֶ֥לֶךְ] a rei Babilônia e-a [אֶל־מֶ֥לֶךְ] como [sem-traducao] a rei [sem-traducao]');
INSERT INTO verses VALUES (20254, 24, 50, 19, '[וְשֹׁבַבְתִּ֤י] a Israel a [הַכַּרְמֶ֖ל] [וְהַבָּשָׁ֑ן] [וּבְהַ֥ר] [אֶפְרַ֛יִם] [וְהַגִּלְעָ֖ד] [תִּשְׂבַּ֥ע] [נַפְשֽׁוֹ]');
INSERT INTO verses VALUES (20255, 24, 50, 20, '[בַּיָּמִ֣ים] [הָהֵם֩] [וּבָעֵ֨ת] [הַהִ֜יא] oráculo-de yhwh [אֶת־עֲוֺ֤ן] a [וְאֵינֶ֔נּוּ] Israel [יְהוּדָ֖ה] e-[OBJ] [תִמָּצֶ֑אינָה] que e-não [לַאֲשֶׁ֥ר] porque');
INSERT INTO verses VALUES (20256, 24, 50, 21, 'sobre a-terra folhas-de [עָלֶ֔יהָ] sobre-ela e-a [חֲרֹ֨ב] [וְהַחֲרֵ֤ם] [אַֽחֲרֵיהֶם֙] [נְאֻם־יְהוָ֔ה] [וַעֲשֵׂ֕ה] oráculo-de yhwh ordenei-te que');
INSERT INTO verses VALUES (20257, 24, 50, 22, 'voz [מִלְחָמָ֖ה] [בָּאָ֑רֶץ] [וְשֶׁ֖בֶר] grande');
INSERT INTO verses VALUES (20258, 24, 50, 23, '[אֵ֤יךְ] [נִגְדַּע֙] [וַיִּשָּׁבֵ֔ר] [פַּטִּ֖ישׁ] todo a-terra era [לְשַׁמָּ֛ה] [בָּבֶ֖ל] Babilônia');
INSERT INTO verses VALUES (20259, 24, 50, 24, '[יָקֹ֨שְׁתִּי] para-ti e-também [בָּבֶ֔ל] Babilônia não não [נִמְצֵאת֙] [וְגַם־נִתְפַּ֔שְׂתְּ] que [בַֽיהוָ֖ה] porque');
INSERT INTO verses VALUES (20260, 24, 50, 25, '[פָּתַ֤ח] yhwh a [וַיּוֹצֵ֖א] [אֶת־כְּלֵ֣י] a utensílios-de [הִ֗יא] porque [יְהוִ֛ה] ela [בְּאֶ֥רֶץ] yhwh de-exércitos em-terra-de coshdeem');
INSERT INTO verses VALUES (20261, 24, 50, 26, '[בֹּֽאוּ־לָ֤הּ] [מִקֵּץ֙] [פִּתְח֣וּ] [מַאֲבֻסֶ֔יהָ] [סָלּ֥וּהָ] [כְמוֹ־עֲרֵמִ֖ים] [וְהַחֲרִימ֑וּהָ] [אַל־תְּהִי־לָ֖הּ] [שְׁאֵרִֽית] a');
INSERT INTO verses VALUES (20262, 24, 50, 27, '[חִרְבוּ֙] todo [יֵרְד֖וּ] [לַטָּ֑בַח] [ה֣וֹי] ai [כִּֽי־בָ֥א] porque veio de-dia tempo [sem-traducao]');
INSERT INTO verses VALUES (20263, 24, 50, 28, 'voz [נָסִ֛ים] [וּפְלֵטִ֖ים] da-terra Babilônia [לְהַגִּ֣יד] [בְּצִיּ֗וֹן] a yhwh yhwh nosso-Elohim [הֵיכָלֽוֹ]');
INSERT INTO verses VALUES (20264, 24, 50, 29, '[הַשְׁמִ֣יעוּ] a [׀] [רַ֠בִּים] todo [קֶ֜שֶׁת] [חֲנ֧וּ] [עָלֶ֣יהָ] [סָבִ֗יב] [אַל־יְהִי־**לָהּ֙[t]] a seja [כְּפָעֳלָ֔הּ] [כְּכֹ֛ל] [אֲשֶׁ֥ר] [עָשְׂתָ֖ה] [עֲשׂוּ־לָ֑הּ] que [אֶל־יְהוָ֛ה] [זָ֖דָה] a-ela porque a yhwh [sem-traducao] a santo Israel');
INSERT INTO verses VALUES (20265, 24, 50, 30, 'por-isso [יִפְּל֥וּ] [בַחוּרֶ֖יהָ] [בִּרְחֹבֹתֶ֑יהָ] e-todo homens-de [יִדַּ֛מּוּ] no-dia no-dia aquele oráculo-de yhwh');
INSERT INTO verses VALUES (20266, 24, 50, 31, 'eis-me a-ti [זָד֔וֹן] oráculo-de Adonai yhwh que porque veio [עֵ֥ת] tempo');
INSERT INTO verses VALUES (20267, 24, 50, 32, '[וְכָשַׁ֤ל] [זָדוֹן֙] [וְנָפַ֔ל] e-não-há a-ele [מֵקִ֑ים] [וְהִצַּ֤תִּי] [אֵשׁ֙] [בְּעָרָ֔יו] e-consumiu todo [sem-traducao]');
INSERT INTO verses VALUES (20268, 24, 50, 33, 'assim disse yhwh exércitos [עֲשׁוּקִ֛ים] filhos-de Israel [יַחְדָּ֑ו] Judá juntos e-todo [מֵאֲנ֖וּ] [שַׁלְּחָֽם]');
INSERT INTO verses VALUES (20269, 24, 50, 34, '[גֹּאֲלָ֣ם] [׀] yhwh yhwh seu-nome [שְׁמ֔וֹ] [רִ֥יב] a [אֶת־רִיבָ֑ם] para-que [הִרְגִּ֣יעַ] a a-terra [לְיֹשְׁבֵ֥י] [בָבֶֽל]');
INSERT INTO verses VALUES (20270, 24, 50, 35, 'espada sobre [נְאֻם־יְהוָ֑ה] oráculo-de yhwh e-a habitantes-de e-a e-a');
INSERT INTO verses VALUES (20271, 24, 50, 36, 'espada a [וְנֹאָ֑לוּ] espada espada a [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20272, 24, 50, 37, 'espada a [וְאֶל־רִכְבּ֗וֹ] e-a [אֲשֶׁ֥ר] e-a e-sejam [לְנָשִׁ֑ים] espada [אֶל־אוֹצְרֹתֶ֖יהָ] [וּבֻזָּֽזוּ] a');
INSERT INTO verses VALUES (20273, 24, 50, 38, '[חֹ֥רֶב] a [וְיָבֵ֑שׁוּ] que terra terra [הִ֔יא] [וּבָאֵימִ֖ים] [יִתְהֹלָֽלוּ]');
INSERT INTO verses VALUES (20274, 24, 50, 39, 'portanto [יֵשְׁב֤וּ] [צִיִּים֙] a [וְיָ֥שְׁבוּ] [בָ֖הּ] [בְּנ֣וֹת] filhas-de [וְלֹֽא־תֵשֵׁ֥ב] e-não [לָנֶ֔צַח] ainda [תִשְׁכּ֖וֹן] e-não [וָדֽוֹר] até');
INSERT INTO verses VALUES (20275, 24, 50, 40, '[כְּמַהְפֵּכַ֨ת] Elohim a [וְאֶת־עֲמֹרָ֛ה] e-[OBJ] [נְאֻם־יְהוָ֑ה] e-[OBJ] [שָׁם֙] oráculo-de yhwh não habitou nome homem e-não filho-de homem');
INSERT INTO verses VALUES (20276, 24, 50, 41, 'eis povo veio [מִצָּפ֑וֹן] [וְג֤וֹי] grande [וּמְלָכִ֣ים] muitos [יֵעֹ֖רוּ] [מִיַּרְכְּתֵי־אָֽרֶץ] terra');
INSERT INTO verses VALUES (20277, 24, 50, 42, '[קֶ֣שֶׁת] [וְכִידֹ֞ן] [יַחֲזִ֗יקוּ] [אַכְזָרִ֥י] eles e-não [יְרַחֵ֔מוּ] [קוֹלָם֙] [כַּיָּ֣ם] [יֶהֱמֶ֔ה] e-sobre cavalos [עָר֗וּךְ] [כְּאִישׁ֙] [לַמִּלְחָמָ֔ה] [עָלַ֖יִךְ] [בַּת־בָּבֶֽל] filha-de Babilônia');
INSERT INTO verses VALUES (20278, 24, 50, 43, 'ouviu rei-de Babilônia a [יָדָ֑יו] [צָרָה֙] suas-maos [חִ֖יל] [כַּיּוֹלֵדָֽה] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20279, 24, 50, 44, 'eis [כְּאַרְיֵ֞ה] subia [מִגְּא֣וֹן] [הַיַּרְדֵּן֮] a [אֵיתָן֒] [כִּֽי־אַרְגִּ֤עָה] porque [**אֲרִיצֵם֙] [מֵֽעָלֶ֔יהָ] e-quem [בָח֖וּר] [אֵלֶ֣יהָ] [אֶפְקֹ֑ד] que quem [כָמ֙וֹנִי֙] e-quem [יוֹעִדֶ֔נִּי] [וּמִֽי־זֶ֣ה] este [אֲשֶׁ֥ר] que [לְפָנָֽי]');
INSERT INTO verses VALUES (20280, 24, 50, 45, 'portanto ouvi conselho-de yhwh que [אֶל־בָּבֶ֔ל] a Babilônia [חָשַׁ֖ב] que [כַּשְׂדִּ֑ים] a terra [צְעִירֵ֣י] se não [יַשִּׁ֛ים] [עֲלֵיהֶ֖ם] [נָוֶֽה] se não [sem-traducao] sobre-eles [sem-traducao]');
INSERT INTO verses VALUES (20281, 24, 50, 46, '[מִקּוֹל֙] [נִתְפְּשָׂ֣ה] [בָבֶ֔ל] [נִרְעֲשָׁ֖ה] a-terra [וּזְעָקָ֖ה] [בַּגּוֹיִ֥ם] [נִשְׁמָֽע׃]');
INSERT INTO chapters VALUES (796, 24, 51, 64);
INSERT INTO verses VALUES (20282, 24, 51, 1, 'assim disse yhwh eis-me [מֵעִ֣יר] sobre Babilônia e-a [קָמָ֑י] espírito [מַשְׁחִֽית] espírito [sem-traducao]');
INSERT INTO verses VALUES (20283, 24, 51, 2, '[וְשִׁלַּחְתִּ֨י] [לְבָבֶ֤ל] [׀] [זָרִים֙] [וְזֵר֔וּהָ] a [אֶת־אַרְצָ֑הּ] porque [עָלֶ֛יהָ] [מִסָּבִ֖יב] [בְּי֥וֹם] [רָעָֽה]');
INSERT INTO verses VALUES (20284, 24, 51, 3, 'a [*ידרך] [הַדֹּרֵךְ֙] [קַשְׁתּ֔וֹ] e-a [בְּסִרְיֹנּ֑וֹ] [וְאַֽל־תַּחְמְלוּ֙] e-a [הַחֲרִ֖ימוּ] a todo');
INSERT INTO verses VALUES (20285, 24, 51, 4, '[וְנָפְל֥וּ] traspassados na-terra [כַּשְׂדִּ֑ים] [וּמְדֻקָּרִ֖ים] [בְּחוּצוֹתֶֽיהָ]');
INSERT INTO verses VALUES (20286, 24, 51, 5, 'que não [יִשְׂרָאֵ֤ל] Israel [מֵֽאֱלֹהָ֔יו] [מֵֽיְהוָ֖ה] [צְבָא֑וֹת] que porque [מָלְאָ֣ה] [אָשָׁ֔ם] [מִקְּד֖וֹשׁ] [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (20287, 24, 51, 6, '[נֻ֣סוּ] do-meio-de [מִתּ֣וֹךְ] [בָּבֶ֗ל] homem [אִ֣ישׁ] a [אַל־תִּדַּ֖מּוּ] [בַּעֲוֺנָ֑הּ] que [עֵ֨ת] [נְקָמָ֥ה] ela a-yhwh [גְּמ֕וּל] ele [מְשַׁלֵּ֖ם] a-ela');
INSERT INTO verses VALUES (20288, 24, 51, 7, '[כּוֹס־זָהָ֤ב] [בָּבֶל֙] Babilônia pela-mão-de yhwh [מִיֵּינָהּ֙] todo a-terra [עַל־כֵּ֖ן] [יִתְהֹלְל֥וּ] nações sobre dizendo [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20289, 24, 51, 8, '[פִּתְאֹ֛ם] [נָפְלָ֥ה] [בָבֶ֖ל] [וַתִּשָּׁבֵ֑ר] [הֵילִ֣ילוּ] [עָלֶ֗יהָ] [קְח֤וּ] [צֳרִי֙] [לְמַכְאוֹבָ֔הּ] [אוּלַ֖י] [תֵּרָפֵֽא]');
INSERT INTO verses VALUES (20290, 24, 51, 9, 'a Babilônia e-não [וְלֹ֣א] [נִרְפָּ֔תָה] [עִזְב֕וּהָ] homem [אִ֣ישׁ] porque [כִּֽי־נָגַ֤ע] a os-céus [וְנִשָּׂ֖א] [עַד־שְׁחָקִֽים] até');
INSERT INTO verses VALUES (20291, 24, 51, 10, '[הוֹצִ֥יא] yhwh a [בֹּ֚אוּ] [וּנְסַפְּרָ֣ה] [בְצִיּ֔וֹן] [אֶֽת־מַעֲשֵׂ֖ה] yhwh [אֱלֹהֵֽינוּ] yhwh');
INSERT INTO verses VALUES (20292, 24, 51, 11, '[הָבֵ֣רוּ] [הַחִצִּים֮] [מִלְא֣וּ] [הַשְּׁלָטִים֒] [הֵעִ֣יר] yhwh a espírito reis-de [כִּֽי־עַל־בָּבֶ֥ל] porque sobre [כִּֽי־נִקְמַ֤ת] yhwh [הִ֔יא] porque [הֵיכָלֽוֹ] yhwh');
INSERT INTO verses VALUES (20293, 24, 51, 12, 'a [בָּבֶ֜ל] [שְׂאוּ־נֵ֗ס] [הַחֲזִ֙יקוּ֙] [הַמִּשְׁמָ֔ר] [הָקִ֙ימוּ֙] [שֹֽׁמְרִ֔ים] [הָכִ֖ינוּ] [הָאֹֽרְבִ֑ים] que [גַּם־זָמַ֣ם] yhwh também [OBJ] yhwh também fez a que palavra a');
INSERT INTO verses VALUES (20294, 24, 51, 13, 'sobre águas muitos [רַבִּ֔ים] [רַבַּ֖ת] veio [בָּ֥א] [קִצֵּ֖ךְ] [אַמַּ֥ת]');
INSERT INTO verses VALUES (20295, 24, 51, 14, '[נִשְׁבַּ֛ע] yhwh exércitos [בְּנַפְשׁ֑וֹ] que se homem homem [וְעָנ֥וּ] [עָלַ֖יִךְ] [הֵידָֽד׃]');
INSERT INTO verses VALUES (20296, 24, 51, 15, 'fez terra [בְּכֹח֔וֹ] [מֵכִ֥ין] [תֵּבֵ֖ל] [בְּחָכְמָת֑וֹ] [וּבִתְבוּנָת֖וֹ] [נָטָ֥ה] céus');
INSERT INTO verses VALUES (20297, 24, 51, 16, 'à-voz-de [תִּתּ֜וֹ] multidao águas [בַּשָּׁמַ֔יִם] [וַיַּ֥עַל] [נְשִׂאִ֖ים] [מִקְצֵה־אָ֑רֶץ] terra [לַמָּטָר֙] [עָשָׂ֔ה] fez espírito espírito [sem-traducao]');
INSERT INTO verses VALUES (20298, 24, 51, 17, '[נִבְעַ֤ר] todo homem [הֹבִ֥ישׁ] [כָּל־צֹרֵ֖ף] todo que [שֶׁ֥קֶר] porque [וְלֹא־ר֥וּחַ] [בָּֽם] e-não espírito');
INSERT INTO verses VALUES (20299, 24, 51, 18, '[הֶ֣בֶל] [הֵ֔מָּה] [מַעֲשֵׂ֖ה] [תַּעְתֻּעִ֑ים] [בְּעֵ֥ת] [פְּקֻדָּתָ֖ם] [יֹאבֵֽדוּ]');
INSERT INTO verses VALUES (20300, 24, 51, 19, 'não [חֵ֣לֶק] [יַעֲק֗וֹב] [כִּֽי־יוֹצֵ֤ר] porque ele [וְשֵׁ֖בֶט] ele yhwh [צְבָא֖וֹת] yhwh');
INSERT INTO verses VALUES (20301, 24, 51, 20, '[מַפֵּץ־אַתָּ֣ה] tu a-mim [מִלְחָמָ֑ה] [וְנִפַּצְתִּ֤י] [בְךָ֙] [גּוֹיִ֔ם] nações [בְךָ֖] [מַמְלָכֽוֹת]');
INSERT INTO verses VALUES (20302, 24, 51, 21, '[וְנִפַּצְתִּ֣י] em-ti [ס֖וּס] [וְרֹֽכְב֑וֹ] [וְנִפַּצְתִּ֣י] em-ti [רֶ֖כֶב] [וְרֹכְבֽוֹ]');
INSERT INTO verses VALUES (20303, 24, 51, 22, '[וְנִפַּצְתִּ֤י] [בְךָ֙] homem [וְאִשָּׁ֔ה] [וְנִפַּצְתִּ֥י] [בְךָ֖] [זָקֵ֣ן] [וָנָ֑עַר] [וְנִפַּצְתִּ֣י] em-ti [בָּח֖וּר] [וּבְתוּלָֽה]');
INSERT INTO verses VALUES (20304, 24, 51, 23, '[וְנִפַּצְתִּ֤י] [בְךָ֙] [רֹעֶ֣ה] [וְעֶדְר֔וֹ] [וְנִפַּצְתִּ֥י] [בְךָ֖] [אִכָּ֣ר] [וְצִמְדּ֑וֹ] [וְנִפַּצְתִּ֣י] em-ti [פַּח֖וֹת] [וּסְגָנִֽים]');
INSERT INTO verses VALUES (20305, 24, 51, 24, '[וְשִׁלַּמְתִּ֨י] [לְבָבֶ֜ל] [וּלְכֹ֣ל] [׀] [יוֹשְׁבֵ֣י] [OBJ] todo [כָּל־רָעָתָ֛ם] que [בְצִיּ֖וֹן] [לְעֵֽינֵיכֶ֑ם] [נְאֻ֖ם] yhwh yhwh');
INSERT INTO verses VALUES (20306, 24, 51, 25, 'eis-me [אֵלֶ֜יךָ] [הַ֤ר] [הַמַּשְׁחִית֙] oráculo-de yhwh [אֶת־כָּל־הָאָ֑רֶץ] a todo a-terra [וְגִלְגַּלְתִּ֙יךָ֙] a [וּנְתַתִּ֖יךָ] [לְהַ֥ר] [שְׂרֵפָֽה] de');
INSERT INTO verses VALUES (20307, 24, 51, 26, 'e-não [מִמְּךָ֙] pedra pedra [וְאֶ֖בֶן] [לְמֽוֹסָד֑וֹת] [כִּֽי־שִׁמְמ֥וֹת] eternidade [תִּֽהְיֶ֖ה] [נְאֻם־יְהוָֽה] [sem-traducao] oráculo-de yhwh');
INSERT INTO verses VALUES (20308, 24, 51, 27, '[שְׂאוּ־נֵ֣ס] [בָּאָ֗רֶץ] [תִּקְע֨וּ] [שׁוֹפָ֤ר] [בַּגּוֹיִם֙] [קַדְּשׁ֤וּ] [עָלֶ֙יהָ֙] sobre-ela nações [עָלֶ֛יהָ] [מַמְלְכ֥וֹת] reinos [מִנִּ֣י] [וְאַשְׁכְּנָ֑ז] [פִּקְד֤וּ] [עָלֶ֙יהָ֙] sobre-ela [הַֽעֲלוּ־ס֖וּס] [כְּיֶ֥לֶק] [סָמָֽר] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20309, 24, 51, 28, '[קַדְּשׁ֨וּ] [עָלֶ֤יהָ] nações a reis-de [אֶת־פַּחוֹתֶ֖יהָ] a e-[OBJ] e-[OBJ] todo [sem-traducao] e-[OBJ] todo terra [sem-traducao]');
INSERT INTO verses VALUES (20310, 24, 51, 29, '[וַתִּרְעַ֥שׁ] a-terra [וַתָּחֹ֑ל] que [קָ֤מָה] sobre Babilônia yhwh yhwh [אֶת־אֶ֧רֶץ] a terra Babilônia [יוֹשֵֽׁב]');
INSERT INTO verses VALUES (20311, 24, 51, 30, '[חָדְלוּ֩] [גִבּוֹרֵ֨י] [בָבֶ֜ל] [לְהִלָּחֵ֗ם] [יָֽשְׁבוּ֙] [בַּמְּצָד֔וֹת] [נָשְׁתָ֥ה] [גְבוּרָתָ֖ם] eram [לְנָשִׁ֑ים] [הִצִּ֥יתוּ] [מִשְׁכְּנֹתֶ֖יהָ] [נִשְׁבְּר֥וּ] [בְרִיחֶֽיהָ]');
INSERT INTO verses VALUES (20312, 24, 51, 31, '[רָ֤ץ] [לִקְרַאת־רָץ֙] [יָר֔וּץ] [וּמַגִּ֖יד] [לִקְרַ֣את] ao-encontro-de [לְהַגִּיד֙] [לְמֶ֣לֶךְ] como-rei Babilônia porque [מִקָּצֶֽה] cidade-dele de-extremidade');
INSERT INTO verses VALUES (20313, 24, 51, 32, '[וְהַמַּעְבָּר֣וֹת] [נִתְפָּ֔שׂוּ] e-[OBJ] [שָׂרְפ֣וּ] [בָאֵ֑שׁ] [וְאַנְשֵׁ֥י] [הַמִּלְחָמָ֖ה] [נִבְהָֽלוּ׃]');
INSERT INTO verses VALUES (20314, 24, 51, 33, 'que assim disse yhwh exércitos Elohim-de Israel filha-de [כְּגֹ֖רֶן] [עֵ֣ת] tempo [ע֣וֹד] [מְעַ֔ט] [וּבָ֥אָה] [עֵֽת־הַקָּצִ֖יר] [לָֽהּ] a colheita a-ela');
INSERT INTO verses VALUES (20315, 24, 51, 34, '[*אכלנו] rei [*הממנו] [**הֲמָמַ֗נִי] [נְבוּכַדְרֶאצַּר֮] [מֶ֣לֶךְ] enchei [*הציגנו] [**הִצִּיגַ֙נִי֙]');
INSERT INTO verses VALUES (20316, 24, 51, 35, '[חֲמָסִ֤י] [וּשְׁאֵרִי֙] sobre Babilônia [יֹשֶׁ֣בֶת] [צִיּ֑וֹן] Sião [אֶל־יֹשְׁבֵ֣י] a habitantes-de [יְרוּשָׁלָֽ͏ִם׃]');
INSERT INTO verses VALUES (20317, 24, 51, 36, 'portanto assim disse yhwh [הִנְנִי־רָב֙] muito a [אֶת־נִקְמָתֵ֑ךְ] [וְהַחֲרַבְתִּי֙] a [וְהֹבַשְׁתִּ֖י] [אֶת־מְקוֹרָֽהּ] a a');
INSERT INTO verses VALUES (20318, 24, 51, 37, '[וְהָיְתָה֩] [בָבֶ֨ל] [׀] [לְגַלִּ֧ים] [׀] [מְעוֹן־תַּנִּ֛ים] [שַׁמָּ֥ה] sem [מֵאֵ֥ין]');
INSERT INTO verses VALUES (20319, 24, 51, 38, 'juntos [כַּכְּפִרִ֣ים] [יִשְׁאָ֑גוּ] [נָעֲר֖וּ] [כְּגוֹרֵ֥י] [אֲרָיֽוֹת]');
INSERT INTO verses VALUES (20320, 24, 51, 39, '[בְּחֻמָּ֞ם] [אָשִׁ֣ית] a [וְהִשְׁכַּרְתִּים֙] [לְמַ֣עַן] para-que [וְיָשְׁנ֥וּ] [שְׁנַת־עוֹלָ֖ם] [וְלֹ֣א] [יָקִ֑יצוּ] e-não yhwh oráculo-de yhwh');
INSERT INTO verses VALUES (20321, 24, 51, 40, '[אֽוֹרִידֵ֖ם] [כְּכָרִ֣ים] [לִטְב֑וֹחַ] [כְּאֵילִ֖ים] com');
INSERT INTO verses VALUES (20322, 24, 51, 41, '[אֵ֚יךְ] [נִלְכְּדָ֣ה] [שֵׁשַׁ֔ךְ] [וַתִּתָּפֵ֖שׂ] [תְּהִלַּ֣ת] todo a-terra era [לְשַׁמָּ֛ה] [בָּבֶ֖ל] Babilônia');
INSERT INTO verses VALUES (20323, 24, 51, 42, 'subir sobre o-mar [בַּהֲמ֥וֹן] [גַּלָּ֖יו] [נִכְסָֽתָה]');
INSERT INTO verses VALUES (20324, 24, 51, 43, '[הָי֤וּ] [עָרֶ֙יהָ֙] [לְשַׁמָּ֔ה] terra [צִיָּ֣ה] [וַעֲרָבָ֑ה] terra não habitou [כָּל־אִ֔ישׁ] todo homem e-não filho-de homem');
INSERT INTO verses VALUES (20325, 24, 51, 44, '[וּפָקַדְתִּ֨י] sobre [בְּבָבֶ֗ל] [וְהֹצֵאתִ֤י] [אֶת־בִּלְעוֹ֙] a [וְלֹֽא־יִנְהֲר֥וּ] a-ele e-não [גּוֹיִ֑ם] a-ele ainda nações também muro-de Babel [sem-traducao]');
INSERT INTO verses VALUES (20326, 24, 51, 45, '[צְא֤וּ] [מִתּוֹכָהּ֙] [עַמִּ֔י] [וּמַלְּט֖וּ] homem a sua-alma [אַף־יְהוָֽה] yhwh');
INSERT INTO verses VALUES (20327, 24, 51, 46, '[וּפֶן־יֵרַ֤ךְ] [לְבַבְכֶם֙] vosso-coração [בַּשְּׁמוּעָ֖ה] [הַנִּשְׁמַ֣עַת] [בָּאָ֑רֶץ] [וּבָ֧א] [בַשָּׁנָ֣ה] [הַשְּׁמוּעָ֗ה] [וְאַחֲרָ֤יו] [בַּשָּׁנָה֙] [הַשְּׁמוּעָ֔ה] [וְחָמָ֣ס] [בָּאָ֔רֶץ] [וּמֹשֵׁ֖ל] [עַל־מֹשֵֽׁל] sobre [sem-traducao]');
INSERT INTO verses VALUES (20328, 24, 51, 47, '[לָכֵן֙] eis dias [בָּאִ֔ים] [וּפָקַדְתִּי֙] sobre [בָבֶ֔ל] [וְכָל־אַרְצָ֖הּ] e-todo [וְכָל־חֲלָלֶ֖יהָ] [יִפְּל֥וּ] e-todo [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20329, 24, 51, 48, '[וְרִנְּנ֤וּ] sobre Babilônia céus e-tudo e-todo que que porque [יָבוֹא־לָ֥הּ] [הַשּׁוֹדְדִ֖ים] a-ela [sem-traducao] oráculo-de yhwh');
INSERT INTO verses VALUES (20330, 24, 51, 49, 'também [לִנְפֹּ֖ל] [חַֽלְלֵ֣י] [יִשְׂרָאֵ֑ל] Israel também [חַֽלְלֵ֥י] [כָל־הָאָֽרֶץ] todo a-terra');
INSERT INTO verses VALUES (20331, 24, 51, 50, '[פְּלֵטִ֣ים] [מֵחֶ֔רֶב] [הִלְכ֖וּ] a [זִכְר֤וּ] [מֵֽרָחוֹק֙] [אֶת־יְהוָ֔ה] a yhwh [עַל־לְבַבְכֶֽם] sobre');
INSERT INTO verses VALUES (20332, 24, 51, 51, '[בֹּ֚שְׁנוּ] porque [חֶרְפָּ֔ה] [כִּסְּתָ֥ה] [כְלִמָּ֖ה] [פָּנֵ֑ינוּ] que porque [זָרִ֔ים] [עַֽל־מִקְדְּשֵׁ֖י] sobre yhwh casa yhwh');
INSERT INTO verses VALUES (20333, 24, 51, 52, 'portanto [הִנֵּֽה־יָמִ֤ים] dias [נְאֻם־יְהוָ֔ה] oráculo-de yhwh [וּבְכָל־אַרְצָ֖הּ] sobre [חָלָֽל] e-em-todo [sem-traducao] [sem-traducao] traspassado');
INSERT INTO verses VALUES (20334, 24, 51, 53, 'porque [בָבֶל֙] [הַשָּׁמַ֔יִם] os-céus [תְבַצֵּ֖ר] [מְר֣וֹם] altura [מֵאִתִּ֗י] [יָבֹ֧אוּ] [שֹׁדְדִ֛ים] [לָ֖הּ] a-ela oráculo-de yhwh');
INSERT INTO verses VALUES (20335, 24, 51, 54, 'voz [זְעָקָ֖ה] [מִבָּבֶ֑ל] [וְשֶׁ֥בֶר] grande da-terra-de [כַּשְׂדִּֽים]');
INSERT INTO verses VALUES (20336, 24, 51, 55, 'porque yhwh yhwh a Babilônia voz [גָּד֑וֹל] [וְהָמ֤וּ] grande [כְּמַ֣יִם] [רַבִּ֔ים] [נִתַּ֥ן] muitos deu');
INSERT INTO verses VALUES (20337, 24, 51, 56, 'que veio [עָלֶ֤יהָ] sobre Babilônia [וְנִלְכְּדוּ֙] [גִּבּוֹרֶ֔יהָ] [חִתְּתָ֖ה] [קַשְּׁתוֹתָ֑ם] que porque El yhwh yhwh [יְשַׁלֵּֽם]');
INSERT INTO verses VALUES (20338, 24, 51, 57, '[וְ֠הִשְׁכַּרְתִּי] [שָׂרֶ֨יהָ] [וַחֲכָמֶ֜יהָ] [פַּחוֹתֶ֤יהָ] [וּסְגָנֶ֙יהָ֙] [וְגִבּוֹרֶ֔יהָ] [וְיָשְׁנ֥וּ] [שְׁנַת־עוֹלָ֖ם] [וְלֹ֣א] e-não [נְאֻ֨ם־הַמֶּ֔לֶךְ] yhwh o-rei yhwh');
INSERT INTO verses VALUES (20339, 24, 51, 58, 'assim yhwh yhwh exércitos [בָּבֶ֤ל] [הָֽרְחָבָה֙] [עַרְעֵ֣ר] [תִּתְעַרְעָ֔ר] [וּשְׁעָרֶ֥יהָ] [הַגְּבֹהִ֖ים] [בָּאֵ֣שׁ] [יִצַּ֑תּוּ] [וְיִֽגְע֨וּ] [עַמִּ֧ים] [בְּדֵי־רִ֛יק] [וּלְאֻמִּ֥ים] [בְּדֵי־אֵ֖שׁ] [וְיָעֵֽפוּ׃]');
INSERT INTO verses VALUES (20340, 24, 51, 59, '[הַדָּבָ֞ר] que [׀] Jeremias [הַנָּבִ֗יא] a [בֶן־נֵרִיָּה֮] filho-de [בְּלֶכְתּ֞וֹ] filho-de [מֶֽלֶךְ־יְהוּדָה֙] [בָּבֶ֔ל] a [הָרְבִעִ֖ית] rei-de Judá Babilônia [מְנוּחָֽה] [sem-traducao] [sem-traducao] e-sraviah príncipe [sem-traducao]');
INSERT INTO verses VALUES (20341, 24, 51, 60, '[וַיִּכְתֹּ֣ב] Jeremias [OBJ] todo [אֲשֶׁר־תָּב֥וֹא] que [אֶל־סֵ֣פֶר] um Babilônia a livro um a todo as-palavras os-estes [sem-traducao] a Babilônia');
INSERT INTO verses VALUES (20342, 24, 51, 61, 'E-disse Jeremias a [כְּבֹאֲךָ֣] [בָבֶ֔ל] [וְֽרָאִ֔יתָ] [וְֽקָרָ֔אתָ] [OBJ] a todo');
INSERT INTO verses VALUES (20343, 24, 51, 62, '[וְאָמַרְתָּ֗] yhwh tu [דִבַּ֜רְתָּ] a [הַזֶּה֙] este para-não [הֱיֽוֹת־בּוֹ֙] [יוֹשֵׁ֔ב] nele [וְעַד־בְּהֵמָ֑ה] [כִּֽי־שִׁמְמ֥וֹת] eternidade animal porque [sem-traducao] eternidade [sem-traducao]');
INSERT INTO verses VALUES (20344, 24, 51, 63, 'e-foi [כְּכַלֹּ֣תְךָ֔] [לִקְרֹ֖א] a [הַזֶּ֑ה] este [עָלָיו֙] pedra [וְהִשְׁלַכְתּ֖וֹ] [אֶל־תּ֥וֹךְ] a');
INSERT INTO verses VALUES (20345, 24, 51, 64, '[וְאָמַרְתָּ֗] [כָּ֠כָה] [תִּשְׁקַ֨ע] [בָּבֶ֤ל] e-não de-diante-de [הָרָעָ֗ה] [אֲשֶׁ֧ר] eu [מֵבִ֥יא] [עָלֶ֖יהָ] [וְיָעֵ֑פוּ] [עַד־הֵ֖נָּה] até [יִרְמְיָֽהוּ׃]');
INSERT INTO chapters VALUES (797, 24, 52, 34);
INSERT INTO verses VALUES (20346, 24, 52, 1, 'filho-de vinte e-uma ano [בְמָלְכ֔וֹ] em-seu-reinado e-uma dez ano rei [וְשֵׁ֣ם] sua-mãe sua-mãe [**חֲמוּטַ֥ל] Jeremias [מִלִּבְנָֽה]');
INSERT INTO verses VALUES (20347, 24, 52, 2, 'E-fez o-mal aos-olhos-de yhwh [כְּכֹ֥ל] que fez');
INSERT INTO verses VALUES (20348, 24, 52, 3, 'que sobre tambem yhwh era [בִּירוּשָׁלַ֣͏ִם] e-Yehuda até [אוֹתָ֖ם] de-cima-de de-sobre [וַיִּמְרֹ֥ד] [צִדְקִיָּ֖הוּ] [בְּמֶ֥לֶךְ] [בָּבֶֽל] Babilônia');
INSERT INTO verses VALUES (20349, 24, 52, 4, 'e-houve [בַשָּׁנָ֨ה] [הַתְּשִׁעִ֜ית] [לְמָלְכ֗וֹ] [בַּחֹ֣דֶשׁ] [הָעֲשִׂירִי֮] [בֶּעָשׂ֣וֹר] [לַחֹדֶשׁ֒] veio [נְבוּכַדְרֶאצַּ֨ר] rei-de ele ele e-todo [וַֽיַּחֲנ֖וּ] sobre Jerusalém e-acamparam sobre-ela [סָבִֽיב] [sem-traducao] [sem-traducao] ao-redor');
INSERT INTO verses VALUES (20350, 24, 52, 5, '[וַתָּבֹ֥א] a-cidade [בַּמָּצ֑וֹר] até [עַשְׁתֵּ֣י] [עֶשְׂרֵ֣ה] ano ao-rei [צִדְקִיָּֽהוּ]');
INSERT INTO verses VALUES (20351, 24, 52, 6, '[בַּחֹ֤דֶשׁ] o-quarto [בְּתִשְׁעָ֣ה] [לַחֹ֔דֶשׁ] [וַיֶּחֱזַ֥ק] [הָרָעָ֖ב] [בָּעִ֑יר] e-não pão pao a-terra a-terra');
INSERT INTO verses VALUES (20352, 24, 52, 7, '[וַתִּבָּקַ֣ע] a-cidade e-todo homens-de [יִבְרְחוּ֩] [וַיֵּצְא֨וּ] [מֵהָעִ֜יר] [לַ֗יְלָה] o-caminho-de caminho [בֵּין־הַחֹמֹתַ֙יִם֙] [אֲשֶׁר֙] [עַל־גַּ֣ן] que sobre [עַל־הָעִ֖יר] o-rei [וַיֵּלְכ֖וּ] o-caminho-de a-cidade caminho');
INSERT INTO verses VALUES (20353, 24, 52, 8, '[וַיִּרְדְּפ֤וּ] [חֵיל־כַּשְׂדִּים֙] [אַחֲרֵ֣י] depois-de o-rei [אֶת־צִדְקִיָּ֖הוּ] a [יְרֵח֑וֹ] [וְכָל־חֵיל֔וֹ] [נָפֹ֖צוּ] e-todo');
INSERT INTO verses VALUES (20354, 24, 52, 9, '[וַֽיִּתְפְּשׂוּ֙] a o-rei ele a-ele a rei Babilônia [חֲמָ֑ת] na-terra Hamate e-falou com-ele [sem-traducao]');
INSERT INTO verses VALUES (20355, 24, 52, 10, '[וַיִּשְׁחַ֧ט] rei-de Babilônia a filhos-de [וְגַ֛ם] [אֶת־כָּל־שָׂרֵ֥י] [יְהוּדָ֖ה] a todo');
INSERT INTO verses VALUES (20356, 24, 52, 11, 'e-[OBJ] [צִדְקִיָּ֖הוּ] [עִוֵּ֑ר] [וַיַּאַסְרֵ֣הוּ] [בַֽנְחֻשְׁתַּ֗יִם] [וַיְבִאֵ֤הוּ] [מֶֽלֶךְ־בָּבֶל֙] rei-de Babilônia [*בבית־**בֵֽית־הַפְּקֻדֹּ֖ת] [עַד־י֥וֹם] [מוֹתֽוֹ] até dia');
INSERT INTO verses VALUES (20357, 24, 52, 12, '[וּבַחֹ֤דֶשׁ] [הֽ͏ַחֲמִישִׁי֙] [בֶּעָשׂ֣וֹר] [לַחֹ֔דֶשׁ] ela [שְׁנַת֙] [תְּשַֽׁע־עֶשְׂרֵ֣ה] [שָׁנָ֔ה] ano ao-rei [מֶֽלֶךְ־בָּבֶ֑ל] rei-de Babilônia veio [עָמַ֛ד] chefe-de [מֶֽלֶךְ־בָּבֶ֖ל] ficou-em-pé diante-de rei-de Babel em-Jerusalém');
INSERT INTO verses VALUES (20358, 24, 52, 13, '[וַיִּשְׂרֹ֥ף] a casa-de yhwh e-[OBJ] casa o-rei e-[OBJ] todo [שָׂרַ֥ף] [בָּאֵֽשׁ] e-[OBJ] todo casa');
INSERT INTO verses VALUES (20359, 24, 52, 14, 'e-[OBJ] todo [סָבִ֑יב] Jerusalém [כָּל־חֵ֣יל] [כַּשְׂדִּ֔ים] todo força que a');
INSERT INTO verses VALUES (20360, 24, 52, 15, '[וּמִדַּלּ֨וֹת] o-povo e-[OBJ] [הָעָ֣ם] [׀] [הַנִּשְׁאָרִ֣ים] [בָּעִ֗יר] e-[OBJ] [אֲשֶׁ֤ר] que [אֶל־מֶ֣לֶךְ] a e-[OBJ] Babilônia e-[OBJ] resto [נְבוּזַרְאֲדָ֖ן] [רַב־טַבָּחִֽים] [sem-traducao] chefe-de [sem-traducao]');
INSERT INTO verses VALUES (20361, 24, 52, 16, '[וּמִדַּלּ֣וֹת] a-terra [הִשְׁאִ֕יר] [נְבוּזַרְאֲדָ֖ן] chefe-de [לְכֹרְמִ֖ים] [וּלְיֹגְבִֽים]');
INSERT INTO verses VALUES (20362, 24, 52, 17, 'e-[OBJ] [הַנְּחֹ֜שֶׁת] [אֲשֶׁ֣ר] que para-a-casa-de yhwh e-[OBJ] [אֲשֶׁ֥ר] e-[OBJ] [שִׁבְּר֣וּ] [כַשְׂדִּ֑ים] que na-casa-de yhwh e-[OBJ] [sem-traducao] e-levantaram a todo [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20363, 24, 52, 18, 'e-[OBJ] [וְאֶת־הַיָּעִ֨ים] e-[OBJ] [וְאֶת־הַמִּזְרָקֹ֣ת] e-[OBJ] e-[OBJ] e-[OBJ] [הַנְּחֹ֛שֶׁת] e-[OBJ] [בָהֶ֖ם] e-[OBJ] todo que');
INSERT INTO verses VALUES (20364, 24, 52, 19, 'e-[OBJ] [וְאֶת־הַמַּחְתּ֨וֹת] e-[OBJ] [וְאֶת־הַסִּיר֣וֹת] e-[OBJ] [וְאֶת־הַכַּפּוֹת֙] e-[OBJ] [אֲשֶׁ֤ר] ouro ouro e-[OBJ] [כָּ֑סֶף] tomou [רַב־טַבָּחִֽים] que tomou');
INSERT INTO verses VALUES (20365, 24, 52, 20, '[הָעַמּוּדִ֣ים] dois [שְׁנַ֗יִם] o-mar um [וְהַבָּקָ֞ר] dez [נְחֹ֙שֶׁת֙] que debaixo-de [אֲשֶׁ֥ר] que fez o-rei [לְבֵ֣ית] yhwh yhwh não foi [כָּל־הַכֵּלִ֥ים] [הָאֵֽלֶּה] todo');
INSERT INTO verses VALUES (20366, 24, 52, 21, '[וְהָעַמּוּדִ֗ים] oito [עֶשְׂרֵ֤ה] [אַמָּה֙] [*קומה] [**קוֹמַת֙] [הָעַמֻּ֣ד] o-primeiro [וְח֛וּט] [שְׁתֵּים־עֶשְׂרֵ֥ה] [אַמָּ֖ה] [יְסֻבֶּ֑נּוּ] quatro [אַרְבַּ֥ע] [אַצְבָּע֖וֹת]');
INSERT INTO verses VALUES (20367, 24, 52, 22, '[וְכֹתֶ֨רֶת] sobre-ele [נְחֹ֗שֶׁת] [וְקוֹמַ֨ת] [הַכֹּתֶ֥רֶת] [הָאַחַת֮] cinco [אַמּוֹת֒] [וּשְׂבָכָ֨ה] [וְרִמּוֹנִ֧ים] sobre [סָבִ֖יב] ao-redor [נְחֹ֑שֶׁת] bronze [לַֽעַמּ֥וּד] [הַשֵּׁנִ֖י] [וְרִמּוֹנִֽים]');
INSERT INTO verses VALUES (20368, 24, 52, 23, '[וַיִּֽהְיוּ֙] [הָֽרִמֹּנִ֔ים] [תִּשְׁעִ֥ים] [וְשִׁשָּׁ֖ה] [ר֑וּחָה] todo [מֵאָ֛ה] cem sobre');
INSERT INTO verses VALUES (20369, 24, 52, 24, 'E-tomou chefe-de [אֶת־שְׂרָיָה֙] a [הָרֹ֔אשׁ] sacerdote o-primeiro e-[OBJ] [וְאֶת־שְׁלֹ֖שֶׁת] sacerdote [הַסַּֽף] e-[OBJ] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (20370, 24, 52, 25, 'e-de tomou tomou um um [פָקִ֣יד] foi [עַל־אַנְשֵׁ֣י] sobre homens-de [אֲנָשִׁ֜ים] [מֵרֹאֵ֤י] [פְנֵי־הַמֶּ֙לֶךְ֙] [אֲשֶׁ֣ר] [נִמְצְא֣וּ] o-rei e-[OBJ] [סֹפֵר֙] [שַׂ֣ר] e-[OBJ] [הַמַּצְבִּ֖א] [אֶת־עַ֣ם] a-terra [וְשִׁשִּׁ֥ים] a povo a-terra [הַֽנִּמְצְאִ֖ים] no-meio-de [הָעִֽיר] a-terra');
INSERT INTO verses VALUES (20371, 24, 52, 26, 'E-tomou [אוֹתָ֔ם] [נְבוּזַרְאֲדָ֖ן] chefe-de [וַיֹּ֧לֶךְ] E-andou eles a rei Babel [sem-traducao]');
INSERT INTO verses VALUES (20372, 24, 52, 27, '[וַיַּכֶּ֣ה] [אוֹתָם֩] rei [בָּבֶ֧ל] [וַיְמִתֵ֛ם] [בְּרִבְלָ֖ה] na-terra Hamate [וַיִּ֥גֶל] Judá de-cima-de [אַדְמָתֽוֹ]');
INSERT INTO verses VALUES (20373, 24, 52, 28, 'este o-povo que [הֶגְלָ֖ה] [נְבֽוּכַדְרֶאצַּ֑ר] [בִּשְׁנַת־שֶׁ֕בַע] sete [שְׁלֹ֥שֶׁת] [אֲלָפִ֖ים] milhares [וּשְׁלֹשָֽׁה] e-três');
INSERT INTO verses VALUES (20374, 24, 52, 29, '[בִּשְׁנַ֛ת] [שְׁמוֹנֶ֥ה] [עֶשְׂרֵ֖ה] [לִנְבֽוּכַדְרֶאצַּ֑ר] [מִיר֣וּשָׁלִַ֔ם] alma oito centenas [שְׁלֹשִׁ֥ים] [וּשְׁנָֽיִם]');
INSERT INTO verses VALUES (20375, 24, 52, 30, '[בִּשְׁנַ֨ת] três [וְעֶשְׂרִים֮] [לִנְבֽוּכַדְרֶאצַּר֒] [הֶגְלָ֗ה] [נְבֽוּזַרְאֲדָן֙] chefe-de [יְהוּדִ֕ים] [נֶ֕פֶשׁ] alma sete centenas [וַחֲמִשָּׁ֑ה] [כָּל־נֶ֕פֶשׁ] todo alma [וְשֵׁ֥שׁ] milhares e-seis centenas');
INSERT INTO verses VALUES (20376, 24, 52, 31, 'e-houve [בִשְׁלֹשִׁ֨ים] [וָשֶׁ֜בַע] [שָׁנָ֗ה] [לְגָלוּת֙] [יְהוֹיָכִ֣ן] rei-de Judá [עָשָׂר֙] dez novo [וַחֲמִשָּׁ֖ה] [לַחֹ֑דֶשׁ] [נָשָׂ֡א] [אֱוִ֣יל] Evil [מֶ֨לֶךְ] rei [בִּשְׁנַ֣ת] no-ano-de [אֶת־רֹאשׁ֙] a cabeça [וַיֹּצֵ֥א] rei-de Judá [*הכליא] [**הַכְּלֽוּא] de-casa-de');
INSERT INTO verses VALUES (20377, 24, 52, 32, 'e-falou com-ele [טֹב֑וֹת] E-colocou a [מִמַּ֗עַל] [לְכִסֵּ֧א] [*מלכים] que com-ele [אִתּ֖וֹ]');
INSERT INTO verses VALUES (20378, 24, 52, 33, '[וְשִׁנָּ֕ה] a [בִּגְדֵ֣י] [כִלְא֑וֹ] e-coma pão [לְפָנָ֛יו] [תָּמִ֖יד] todo dias-de [sem-traducao]');
INSERT INTO verses VALUES (20379, 24, 52, 34, '[וַאֲרֻחָת֗וֹ] [אֲרֻחַת֩] [תָּמִ֨יד] [נִתְּנָה־לּ֜וֹ] [מֵאֵ֧ת] [מֶֽלֶךְ־בָּבֶ֛ל] rei-de Babilônia palavra-de dia [כֹּ֖ל] dias-de dia todo');
INSERT INTO books VALUES (25, 'LAM', 'Lamentações', 'AT', 5);
INSERT INTO chapters VALUES (798, 25, 1, 22);
INSERT INTO verses VALUES (20380, 25, 1, 1, 'Eica יָשַׁבְתָּ בָּדָד a-cidade רַבָּתִי povo הָיְתָה era רַבָּתִי nos-goyim שָׂרָתִי בְּמִדְינֹות הָיְתָה era');
INSERT INTO verses VALUES (20381, 25, 1, 2, 'בָּכ֨וֹ תִּבְכֶּה noite e-lágrimas-ela sobre na-maçã-do-rosto-dele não há para-ela m''nachem de-todo amores-sua todo seus-amigos enganaram nela a-ele para-ela inimigos:');
INSERT INTO verses VALUES (20382, 25, 1, 3, 'גָּלְתָה Judá por-pobreza e-por-muitas trabalhos ela em-ba nos-goyim não encontr-a מנוח todo seus-perseguidores entre entre os-mal-crian');
INSERT INTO verses VALUES (20383, 25, 1, 4, 'דַּרְכֵ֨י Sion lutos מִבְּלִי֙ em-ai encontro todo suas-portas silenciadas coheneyha neenachim betuloteye e ela amargo a-ela');
INSERT INTO verses VALUES (20384, 25, 1, 5, 'היוּ tsareyha lereosh oyeveye shalou porque yhwh sobre sobre rov- peshaeye olaleye הלכו שִׁבְיָ diante-de צר׃');
INSERT INTO verses VALUES (20385, 25, 1, 6, 'e-ele-saiu Sião todo [כָּל־הֲדָרָ֑הּ] foram [שָׂרֶ֗יהָ] [כְּאַיָּלִים֙] não [מִרְעֶ֔ה] [וַיֵּלְכ֥וּ] e-caminharam [לִפְנֵ֥י] [רוֹדֵֽף׃] diante-de');
INSERT INTO verses VALUES (20386, 25, 1, 7, 'זָכְרָה Jerusalém dias-de עָנְיָהּ e-a-merudéyahā todo seu-a que foram de-mais oriente caído-a seu-á-á por-mão-de adversário e-não-há auxiliador para-ela viram-a adversários sobre sobre de-sua-casa');
INSERT INTO verses VALUES (20387, 25, 1, 8, 'erro pecou-a Jerusalém sobre assim para a nida היתה todo suas santificações e derribaram-na porque viram sua nudez também ela e a encharcaram e-ela-voltou-se depois');
INSERT INTO verses VALUES (20388, 25, 1, 9, 'sua impureza em-suas-sulhas não e a lembraram depois dela e-ela-desceu mil não m''nachem para ela viu yhwh a que porque הגדיל inimigo');
INSERT INTO verses VALUES (20389, 25, 1, 10, 'sua-mão פרשה צר sobre todo מחמדיה porque ראתה nações vieram santuário que ציוית para-ti virão בקהל para-ti');
INSERT INTO verses VALUES (20390, 25, 1, 11, 'todo עם נהנחים pão Belém נָתְנ֧וּ בְּאֹ֖כֶל faça alma viu yhwh yhwh porque que זוֹלֵלָֽה׃');
INSERT INTO verses VALUES (20391, 25, 1, 12, 'ל֣וֹא אֲלֵיכֶם֮ todo עֹ֣בְרֵי caminho הַבּ֣יטוּ e-vede se ha מַכְאוֹב֙ כְּמַכְאֹבִ֔י que עוֹלַ֖ל para-mim yhwh הוֹגָ֣ה yhwh em-dia nós אַפּֽוֹ׃');
INSERT INTO verses VALUES (20392, 25, 1, 13, 'מִמָּר֛וֹם שָׁלַח־ fogo בְּעַצְמֹתַ֖י e desceram expôs rede pelas minhas me-trouxe-de-volta trás colocaram-me silenciosa todo o-dia do');
INSERT INTO verses VALUES (20393, 25, 1, 14, 'arrebataram-se sobre מֵעֲוֹנֹתַי beyado ישׂרגוּ subiram sobre צַוָּעֲרִי הִכְשַׁל minha-força נְתַנַּנִי Adonai בִּידֵי não posso levantou');
INSERT INTO verses VALUES (20394, 25, 1, 15, 'סִלַּח todo אַבְרִיַ֤י Adonai בְּקִרְבִּי chamou sobre-mim encontro לִשׁ-בּוֹר בַּחֲוּרָי גַּת caminho Adonai para-remoção filha-de Judá');
INSERT INTO verses VALUES (20395, 25, 1, 16, 'sobre אלה eu בכיה עיני עיני יורדה águas porque רחוק de-mi m''nachem משיב minha-alma eram filhos-de שממים que גבר inimigo');
INSERT INTO verses VALUES (20396, 25, 1, 17, 'פרשה Tsíyyôn bí-yādehā não-há מְנַחֵם֙ para-ela ordenou yhwh para-Jacobe səvı̂bāyw seus inimigos era Yérushālāyim ləniddāh בֵּינֵיהֶֽם׃');
INSERT INTO verses VALUES (20397, 25, 1, 18, 'justo ele yhwh que pı̂hyū mārīty ouvi por-favor todo e-vede makkāvōy bətūlōtway wəbaḥūrāway הלכו בַשֶֽׁבִי׃');
INSERT INTO verses VALUES (20398, 25, 1, 19, 'קָרָ֤אתִי לַֽמְאַהֲבַי֙ eles רִמּ֔וּנִי כֹּהֲנַ֥י וּזְקֵנַ֖י na-cidade גָּוָ֑עוּ porque בִקְשׁ֥וּ אֹ֙כֶל֙ לָ֔moֹ וְיָשִׁ֖יבוּ a alma-deles');
INSERT INTO verses VALUES (20399, 25, 1, 20, 'viu yhwh porque angústia a-mim de-me chamar-marû nehef-pakh que beker-bêri porque mar-âv mar-itî de-fora shiklâ espada BBÍYT kam-mavet');
INSERT INTO verses VALUES (20400, 25, 1, 21, 'שָׁמְעוּ que ne''anachâ eu não-há מְנַחֵם֙ para-mim todo o''evê-bay ouviram minha mágoa que tu tu fizeste )(((הֵבֵ֥אתָ))) dia-de chamaste e sejam como eu');
INSERT INTO verses VALUES (20401, 25, 1, 22, 'venha todo suas mágoas diante-de-ti וְעוֹלֵ֣ל [כַּאֲשֶׁ֥ר] como-que eu sofrer sobre sobre todo meus pecados porque muitas minhas dores e meu coração דַוָּֽי׃');
INSERT INTO chapters VALUES (799, 25, 2, 22);
INSERT INTO verses VALUES (20402, 25, 2, 1, 'Eis que: Deu-se a vê-lo: em-sua-ira Adonai a filha-de Sião Jogou: terra terra esplendor-de Israel e-não macho A vergonha: pés-dele em-dia אַפּֽוֹ׃');
INSERT INTO verses VALUES (20403, 25, 2, 2, 'Engoliu: Adonai Perdoou: את todo pastagens Jacó Destruiu: Na sua brecha: Dos seus dentes: filha-de יְהוּדָה higga para a terra הילל מלכות ושריha:');
INSERT INTO verses VALUES (20404, 25, 2, 3, 'גדעה בחורי certamente todo קרן Israel השיב אחור ימינו de-diante-de אֹיֵב ויבער בייעקב כאש ЛЕХАВА אכלנה ao-redor');
INSERT INTO verses VALUES (20405, 25, 2, 4, 'caminho קשתו KOVAIV נצב ימינו KETSAR WAYYAHARG todo MAḤAMDAY- olho BAʾOHEL filha-de Sião derramou como fogo sua ira');
INSERT INTO verses VALUES (20406, 25, 2, 5, 'ser Adonai ׀ como inimigo engoliu Israel בִּלַּע֙ todo seus exércitos destruiu dos seus fortalezas e rugiu בְּבַת־ Judá תַּאֲנִיָּ֖ה וַאֲנִיָּֽה׃');
INSERT INTO verses VALUES (20407, 25, 2, 6, 'וַיַּחְמֹ֤ס כַּגַּן֙ שֻׂכּ֔וֹ שִׁחֵ֖ת מוֹעֲד֑וֹ שִׁכַּ֨ח yhwh בְּצִיּוֹן֙ na-festa e sábbo e se exaureu em zé''um- sua-ira rei e sacerdote:');
INSERT INTO verses VALUES (20408, 25, 2, 7, 'deitou אדונָ֤י do altar dele acendeu do santuário dele se isolou por-mão-de inimigo חוֹמֹות אַרְמְנוֹתֶיהָ voz eles-deram na-casa-de yhwh como um dia encontro');
INSERT INTO verses VALUES (20409, 25, 2, 8, '[חָשַׁ֨ב] yhwh [׀] muro-de filha-de Sião [נָ֣טָה] [קָ֔ו] não sua-mão mão-sua [וַיּֽ͏ַאֲבֶל־חֵ֥ל] [וְחוֹמָ֖ה] [יַחְדָּ֥ו] [אֻמְלָֽלוּ׃]');
INSERT INTO verses VALUES (20410, 25, 2, 9, 'טָבְע֤וּ na-terra שְׁעָרֶ֔יהָ אִבַּ֥ד וְשִׁבַּ֖ר em-suas-aromas מַלְכָּ֨הּ וְשָׂרֶ֤יהָ בַגּוֹיִם֙ não-há תּוֹרָ֔ה também suas profetisas não מָצְאוּ visão De-Yahweh:');
INSERT INTO verses VALUES (20411, 25, 2, 10, '[יֵשְׁב֨וּ] [לָאָ֤רֶץ] [יִדְּמוּ֙] anciãos-de filha-de Sião pó pó sobre [שַׂקִּ֑ים] [הוֹרִ֤ידוּ] [לָאָ֙רֶץ֙] [רֹאשָׁ֔ן] [בְּתוּלֹ֖ת] [יְרוּשָׁלָֽ͏ִם׃]');
INSERT INTO verses VALUES (20412, 25, 2, 11, '[כָּל֨וּ] [בַדְּמָע֤וֹת] [עֵינַי֙] [חֳמַרְמְר֣וּ] [מֵעַ֔י] [נִשְׁפַּ֤ךְ] [לָאָ֙רֶץ֙] [כְּבֵדִ֔י] sobre Sheber filha-de meu-povo [וְיוֹנֵ֔ק] [בִּרְחֹב֖וֹת] [קִרְיָֽה׃]');
INSERT INTO verses VALUES (20413, 25, 2, 12, 'A-LAS dirão onde GRÃO e-vinho EM-SEUS-VENTOS COMO-U-CHALAL NAS-RUAZINHAS cidade em-te-sheftakh as suas almas a COSTELA E-LAS:');
INSERT INTO verses VALUES (20414, 25, 2, 13, 'que [מָ֣ה] que [הַבַּת֙] [יְר֣וּשָׁלִַ֔ם] [מָ֤ה] Jerusalém que [בְּתוּלַ֖ת] [בַּת־צִיּ֑וֹן] [כִּֽי־גָד֥וֹל] [כַּיָּ֛ם] filha-de quem porque grande para-ti');
INSERT INTO verses VALUES (20415, 25, 2, 14, 'נְבִיאַ֗יִךְ viram para-ti vazio e enganaram e-não exporam sobre seu pecado faça e viram para-ti מַשְׂא֥וֹת vazio e falsos');
INSERT INTO verses VALUES (20416, 25, 2, 15, 'enganaram sobre-vos duas-mãos todo que-passaram caminho cortaram-se e-deram cabeças-as sobre filha-de Jerusalém isto é a-cidade que-dizem concha bonito משׂושׂ para-todo a-terra');
INSERT INTO verses VALUES (20417, 25, 2, 16, '[פָּצ֨וּ] [עָלַ֤יִךְ] [פִּיהֶם֙] todo [שָֽׁרְקוּ֙] [וַיַּֽחַרְקוּ־שֵׁ֔ן] [אָמְר֖וּ] [בִּלָּ֑עְנוּ] [אַ֣ךְ] [זֶ֥ה] o-dia este o-dia [רָאִֽינוּ׃]');
INSERT INTO verses VALUES (20418, 25, 2, 17, 'fez yhwh que zamām bittṣa'' emratō que ordenou mīme- qēdēm hārasa'' e-não חָמָ֑ל wašāmā sobre-ti ōyev hērima'' chifre-de צָרָֽיִךְ׃');
INSERT INTO verses VALUES (20419, 25, 2, 18, '[צָעַ֥ק] [לִבָּ֖ם] a Adonai muro-de filha-de [כַנַּ֤חַל] [דִּמְעָה֙] [יוֹמָ֣ם] [וָלַ֔יְלָה] dia e-noite para-ti [אַל־תִּדֹּ֖ם] [בַּת־עֵינֵֽךְ׃] para-ti a filha-de');
INSERT INTO verses VALUES (20420, 25, 2, 19, 'arsta alegra-te cabeça guardiães derrama-te como-água no teu coração נחבק face-de Adonai levanta-te face-de como as tuas mãos sobre a-ele עֽוֹלָלַ֔יִךְ הָעֲטוּפִ֥ים בְּרָעָ֖ב na cabeça todo חוּץ-וֹת׃');
INSERT INTO verses VALUES (20421, 25, 2, 20, 'viu yhwh [וְֽהַבִּ֔יטָה] de-quem [עוֹלַ֣לְתָּ] [כֹּ֑ה] se [נָשִׁ֤ים] [פִּרְיָם֙] [עֹלֲלֵ֣י] [טִפֻּחִ֔ים] [אִם־יֵהָרֵ֛ג] se [Adonai] [כֹּהֵ֥ן] Adonai sacerdote');
INSERT INTO verses VALUES (20422, 25, 2, 21, 'שָׁכְב֨וּ לָאָ֤רֶץ חוּצוֹת֙ jovem e velho בֲּתוּלֹתַ֥י וּבַחוּרַ֖י caíram בֶחָ֑רֶב הרגתָ em-dia-de אףך טבחתָ não חמלתָ׃');
INSERT INTO verses VALUES (20423, 25, 2, 22, '[תִּקְרָא֩] [כְי֨וֹם] [מוֹעֵ֤ד] [מְגוּרַי֙] de-ao-redor e-não ser em-dia também yhwh [וְשָׂרִ֑יד] [אֲשֶׁר־טִפַּ֥חְתִּי] que [אֹיְבִ֥י] [כִלָּֽם׃]');
INSERT INTO chapters VALUES (800, 25, 3, 66);
INSERT INTO verses VALUES (20424, 25, 3, 1, 'eu [הַגֶּ֙בֶר֙] ver [עֳנִ֔י] [בְּשֵׁ֖בֶט] [עֶבְרָתֽוֹ]');
INSERT INTO verses VALUES (20425, 25, 3, 2, '[אוֹתִ֥י] [נָהַ֛ג] E-andou escuridão e-não luz');
INSERT INTO verses VALUES (20426, 25, 3, 3, 'porém em-mi habitou היפוך sua-mão todo o-dia');
INSERT INTO verses VALUES (20427, 25, 3, 4, '[בִּלָּ֤ה] [בְשָׂרִי֙] [וְעוֹרִ֔י] [שִׁבַּ֖ר] [עַצְמוֹתָֽי]');
INSERT INTO verses VALUES (20428, 25, 3, 5, 'edificar sobre-mim [וַיַּקַּ֖ף] cabeça [וּתְלָאָֽה]');
INSERT INTO verses VALUES (20429, 25, 3, 6, '[בְּמַחֲשַׁכִּ֥ים] [הוֹשִׁיבַ֖נִי] [כְּמֵתֵ֥י] eternidade');
INSERT INTO verses VALUES (20430, 25, 3, 7, '[גָּדַ֧ר] [בַּעֲדִ֛י] e-não [אֵצֵ֖א] [הִכְבִּ֥יד] [נְחָשְׁתִּֽי]');
INSERT INTO verses VALUES (20431, 25, 3, 8, 'também que אֶזְעַק וַאֲשׁ-אוּעַ שׂ-תַמ minha-oração:');
INSERT INTO verses VALUES (20432, 25, 3, 9, '[גָּדַ֤ר] [דְּרָכַי֙] [בְּגָזִ֔ית] [נְתִיבֹתַ֖י] [עִוָּֽה׃]');
INSERT INTO verses VALUES (20433, 25, 3, 10, 'דֹּ֣ב espião ele para-mim בְּמִסְתָּרִֽים׃');
INSERT INTO verses VALUES (20434, 25, 3, 11, 'minhas-caminhos SORER וַֽיְפַשְּׁחֵ֖נִי שָׂמַ֥נִי שֹׁמֵֽם׃');
INSERT INTO verses VALUES (20435, 25, 3, 12, 'caminho [קַשְׁתוֹ֙] [וַיַּצִּיבֵ֔נִי] [כַּמַּטָּרָ֖א] [לַחֵֽץ׃]');
INSERT INTO verses VALUES (20436, 25, 3, 13, '[הֵבִיא֙] [בְּכִלְיוֹתָ֔י] filhos-de [אַשְׁפָּתֽוֹ]');
INSERT INTO verses VALUES (20437, 25, 3, 14, 'estive [שְּׂחֹק֙] para-todo povo-meu [כָּל־הַיּֽוֹם] todo o-dia');
INSERT INTO verses VALUES (20438, 25, 3, 15, 'הִשְׂבִּיעַ֥נִי nos amargos irrigan-me para Aná:');
INSERT INTO verses VALUES (20439, 25, 3, 16, 'e expulsou com o cajado segundo bateu em mim בָּאֵֽפֶר׃');
INSERT INTO verses VALUES (20440, 25, 3, 17, 'e se afastou de Sião alma-minha eu fui lançada boa');
INSERT INTO verses VALUES (20441, 25, 3, 18, 'e-אֹמַר se perderem meu נִצְחִי e-tochalti וְתוֹחַלְתּי מֵיְהוָֽה׃');
INSERT INTO verses VALUES (20442, 25, 3, 19, 'lembra-de [וּמְרוּדִ֖י] [לַעֲנָ֥ה] [וָרֹֽאשׁ]');
INSERT INTO verses VALUES (20443, 25, 3, 20, 'lembra זָכ֣וֹר lembras תִּזְכּ֔וֹר sobre-mim alma-de-mim');
INSERT INTO verses VALUES (20444, 25, 3, 21, 'esta eu retribuirei אָשִׁ֥יב a לבבי sobre assim אוחיל׃');
INSERT INTO verses VALUES (20445, 25, 3, 22, '[חַֽסְדֵ֤י] yhwh que não que porque não');
INSERT INTO verses VALUES (20446, 25, 3, 23, 'חדשים לבקרים multiplicai a tua fidelidade:');
INSERT INTO verses VALUES (20447, 25, 3, 24, 'חלקי yhwh disse nafshi sobre assim a-ele a-ele');
INSERT INTO verses VALUES (20448, 25, 3, 25, 'bom yhwh [לְקֹוָ֔ו] [לְנֶ֖פֶשׁ] [תִּדְרְשֶֽׁנּוּ]');
INSERT INTO verses VALUES (20449, 25, 3, 26, 'bom [וְיָחִיל֙] [וְדוּמָ֔ם] [לִתְשׁוּעַ֖ת] yhwh');
INSERT INTO verses VALUES (20450, 25, 3, 27, 'bom [לַגֶּ֔בֶר] porque [עֹ֖ל] sobre');
INSERT INTO verses VALUES (20451, 25, 3, 28, 'habitou [בָּדָד֙] [וְיִדֹּ֔ם] que [נָטַ֖ל] sobre-ele');
INSERT INTO verses VALUES (20452, 25, 3, 29, 'dará [בֶּֽעָפָר֙] boca-sua [אוּלַ֖י] há [תִּקְוָֽה]');
INSERT INTO verses VALUES (20453, 25, 3, 30, 'dê לִמְכֹּחַ לָחֶד יִשְׁבֹּעַ בְּחֵיק');
INSERT INTO verses VALUES (20454, 25, 3, 31, 'que não [יִזְנַ֛ח] para-sempre Adonai');
INSERT INTO verses VALUES (20455, 25, 3, 32, 'que se [וְרִחַ֖ם] [כְּרֹ֥ב] [*חסדו]');
INSERT INTO verses VALUES (20456, 25, 3, 33, 'que não עִנָּה do-seu-líbbo e-va-jágh homem');
INSERT INTO verses VALUES (20457, 25, 3, 34, 'para-dakkéa debaixo seus-pes todo prisioneiros terra');
INSERT INTO verses VALUES (20458, 25, 3, 35, 'para-totá מִשְׁפַּט־ diante face-de face-de altíssimo');
INSERT INTO verses VALUES (20459, 25, 3, 36, 'para-avét homem בריבו Adonai não ver');
INSERT INTO verses VALUES (20460, 25, 3, 37, 'quem este disse e-tehi Adonai não ordem:');
INSERT INTO verses VALUES (20461, 25, 3, 38, 'de minha Superior não Saia as más e o bom:');
INSERT INTO verses VALUES (20462, 25, 3, 39, 'que- homem homem viveu gever sobre');
INSERT INTO verses VALUES (20463, 25, 3, 40, 'busquemos nosso caminho e investiguemos e voltaremos até yhwh');
INSERT INTO verses VALUES (20464, 25, 3, 41, 'נישעה nossos corações a como as palmas das mãos a El em-os-ceus-verso');
INSERT INTO verses VALUES (20465, 25, 3, 42, 'nós נִפְשַׁעְנוּ וּמָרִינֻהְיוּ tu não סַלְחְתָּ׃');
INSERT INTO verses VALUES (20466, 25, 3, 43, 'סַכְתָּה בַּאֲפֵךְ וַתִּרְדְּפֵינָהּ mataste não hamalta:');
INSERT INTO verses VALUES (20467, 25, 3, 44, 'סַכְתָּה בֵּעָנָן para-ti מֵעַבְרִי oração');
INSERT INTO verses VALUES (20468, 25, 3, 45, 'sí e amos im-nos em-meio-de הָעַמִּים׃');
INSERT INTO verses VALUES (20469, 25, 3, 46, 'quebrarão sobre nós פִיהֶם todo inimigos-nossos');
INSERT INTO verses VALUES (20470, 25, 3, 47, 'medo e temor ser para-nós levado e o trigo:');
INSERT INTO verses VALUES (20471, 25, 3, 48, 'as divisões- águas terá-se dividido Olho sobre Sheber filha-de povo-meu');
INSERT INTO verses VALUES (20472, 25, 3, 49, 'minha vista será enganada e-não parecer-se-á sem הֲפֻגֽוֹת׃');
INSERT INTO verses VALUES (20473, 25, 3, 50, 'até olhará yhwh yhwh dos céus:');
INSERT INTO verses VALUES (20474, 25, 3, 51, 'minha vista עֽוֹלְלָ֣ה לְנַפְשִׁ֔י de-toda filhas-de עִירִֽי׃');
INSERT INTO verses VALUES (20475, 25, 3, 52, 'צ֥וֹד צָד֛וּנִי כַּצִּפּ֖וֹר אֹיְבַ֥י por-nada:');
INSERT INTO verses VALUES (20476, 25, 3, 53, 'צָֽמְת֤וּ בַבּוֹר֙ חַיָּ֔י וַיַּדּוּ־ eben em-mim');
INSERT INTO verses VALUES (20477, 25, 3, 54, '[צָֽפוּ־מַ֥יִם] águas sobre [נִגְזָֽרְתִּי׃] disse');
INSERT INTO verses VALUES (20478, 25, 3, 55, '[קָרָ֤אתִי] [שִׁמְךָ֙] yhwh [מִבּ֖וֹר] [תַּחְתִּיּֽוֹת]');
INSERT INTO verses VALUES (20479, 25, 3, 56, 'קוֹלִ֖י שָׁמָ֑עְתָּ a תַּעְלֵ֧ם אָזְנְךָ֛ para-me-achar para-me-ouvir');
INSERT INTO verses VALUES (20480, 25, 3, 57, 'você-te-approchaste em-dia-de eu-te-chamarei אָמַ֖רְתָּ a você-te-temerá');
INSERT INTO verses VALUES (20481, 25, 3, 58, 'muita-te-foste Adonai רִיבֵ֥י alma-minha exaltaste-te Chayyā∶');
INSERT INTO verses VALUES (20482, 25, 3, 59, 'viste-te yhwh injustiça-me שָׁפְטָה מִשְׁפָּטִי׃');
INSERT INTO verses VALUES (20483, 25, 3, 60, '[רָאִ֙יתָה֙] todo [כָּל־מַחְשְׁבֹתָ֖ם] todo para-mim');
INSERT INTO verses VALUES (20484, 25, 3, 61, '[שָׁמַ֤עְתָּ] [חֶרְפָּתָם֙] yhwh todo [עָלָֽי] sobre-mim');
INSERT INTO verses VALUES (20485, 25, 3, 62, 'שַׂפְתֵ֤י קָמַי֙ e a visão deles sobre-mim todo o-dia');
INSERT INTO verses VALUES (20486, 25, 3, 63, 'a sua sentada e a sua levantamento o olhar eu as suas harpas');
INSERT INTO verses VALUES (20487, 25, 3, 64, 'retornará a-eles גְּמ֛וּל yhwh כְּמַעֲשֵׂה de suas mãos:');
INSERT INTO verses VALUES (20488, 25, 3, 65, 'תִּתֵּ֤ן a-eles de harpa coração a-eles para-eles');
INSERT INTO verses VALUES (20489, 25, 3, 66, 'perseguirás com ira e destruí-los debaixo-de nosso yhwh');
INSERT INTO chapters VALUES (801, 25, 4, 22);
INSERT INTO verses VALUES (20490, 25, 4, 1, 'como povo ouro dormirá o tenebroso הַטּ֑וֹב vai te unir pedras-de santidade no topo todo חוּץ-וֹת׃');
INSERT INTO verses VALUES (20491, 25, 4, 2, 'filhos-de Siao os preciosos os-mussulados no-paz eica nechshubu lenivlei- silencio obra-de mãos-de yozer');
INSERT INTO verses VALUES (20492, 25, 4, 3, 'também חָלְצוּ shad hineiku gureiheen filha-de meu-povo para-acezar no-deserto');
INSERT INTO verses VALUES (20493, 25, 4, 4, 'unir-se para-língua joven a no-escuro olalim perguntaram pão פרוס não a-eles');
INSERT INTO verses VALUES (20494, 25, 4, 5, 'os-que-comem para-mudanças inspiraram-se בַּחוּצ֑וֹת הָאֱמֻנִים֙ sobre תוֹלָ֔ע חִבְּק֖וּ אַשְׁפַּתּֽוֹת׃');
INSERT INTO verses VALUES (20495, 25, 4, 6, 'ele-foi-crecido iniquidade filha-de povo-meu מֵֽחַטַּ֖את Sodoma a invertida כְּמָה־ רָ֔גַע e-não חָ֥לוּ nela יָדָֽיִם׃');
INSERT INTO verses VALUES (20496, 25, 4, 7, 'zakkū neziyréhā ṣaḥū mehalāb admu ʿetsem osso sapir gizzrāṯam');
INSERT INTO verses VALUES (20497, 25, 4, 8, 'escuridão mishḥōr tāʾōrām não foram cortados nas transversais se estendeu sua pele sobre suas carnes ser foi como árvore:');
INSERT INTO verses VALUES (20498, 25, 4, 9, 'Tovim foram traspassados-de espada dos que são contaminados fome e sede יָזֹבֻ֔ו מְדֻקָּרִ֔ים [שָׂדָֽי׃] Shaddai');
INSERT INTO verses VALUES (20499, 25, 4, 10, 'יְדֵ֗י mulheres רַחֲמָ֣נִיּ֔וֹת בִּשּׁׁלוּ filhas eram לְבָרֹות֙ לָהֶם בְּשׁוֹבֵר filha-de povo-meu');
INSERT INTO verses VALUES (20500, 25, 4, 11, 'כּילה yhwh a חמתו שׁפך חרון sua-ira וַיָּצֶת־ e-comeste בְּצִיּון e comeu- suas-fundações:');
INSERT INTO verses VALUES (20501, 25, 4, 12, 'não הֶאֱמִינוּ reis-de terra habitantes-de תֵּבֵל porque que angústia-de e inimigo בְּשַׁעֲרֵי Jerusalém');
INSERT INTO verses VALUES (20502, 25, 4, 13, 'de-eret as-nabiya os-avonot as-cohaniyah os-shophkim em-seu-interior דֹּם צַדִּיקִֽims');
INSERT INTO verses VALUES (20503, 25, 4, 14, 'se-alegraram os-avirim em-suas-exterioridades נְגֹֽאֲל֖וּ no-sangue בְּלֹ֣א יֽוּכְל֔וּ יִגְּע֖וּ בִּלְבֻשֵׁיהֶֽם׃');
INSERT INTO verses VALUES (20504, 25, 4, 15, '[ס֣וּרוּ] [טָמֵ֞א] [קָ֣רְאוּ] [לָ֗מוֹ] [ס֤וּרוּ] [ס֙וּרוּ֙] a que porque [גַּם־נָ֑עוּ] também [בַּגּוֹיִ֔ם] não entre-as-nações não');
INSERT INTO verses VALUES (20505, 25, 4, 16, 'face-de yhwh חליקם não יוסיפ להביטם face-de kohanim não נסאוּ não חnanoו׃');
INSERT INTO verses VALUES (20506, 25, 4, 17, 'תcilנה עינינו a nossa-ajuda הָ֑בֶל em-nossas-campanhas nossas-campanhas a nação não josué');
INSERT INTO verses VALUES (20507, 25, 4, 18, 'se-direcionaram nossos-passos מלכת em-nossas-rua-s qarab nossos-limites se-preencheram נַחֲלֻ֥י porque veio קְצִיתֵֽנוּ׃');
INSERT INTO verses VALUES (20508, 25, 4, 19, 'קָלִ֣ים foram רֹדְפֵ֔ינוּ מִנִּשְרֵ֖י céus sobre הַחֲרִימִ֣ים דְּלַקֻ֔נוּ em-o-midbar אָרְבוּ para-nós');
INSERT INTO verses VALUES (20509, 25, 4, 20, 'espírito [אַפֵּ֙ינוּ֙] [מְשִׁ֣יחַ] yhwh [נִלְכַּ֖ד] [בִּשְׁחִיתוֹתָ֑ם] que [אָמַ֔רְנוּ] [בְּצִלּ֖וֹ] [נִֽחְיֶ֥ה] [בַגּוֹיִֽם׃]');
INSERT INTO verses VALUES (20510, 25, 4, 21, '[שִׂ֤ישִׂי] [וְשִׂמְחִי֙] filha-de Edom em-terra-de [בְּאֶ֣רֶץ] também sobre-ti [תַּעֲבָר־כּ֔וֹס] copo [וְתִתְעָרִֽי׃]');
INSERT INTO verses VALUES (20511, 25, 4, 22, '[תַּם־עֲוֺנֵךְ֙] [בַּת־צִיּ֔וֹן] não Sião não [פָּקַ֤ד] [עֲוֺנֵךְ֙] [בַּת־אֱד֔וֹם] [גִּלָּ֖ה] filha-de sobre');
INSERT INTO chapters VALUES (802, 25, 5, 22);
INSERT INTO verses VALUES (20512, 25, 5, 1, 'macho yhwh de-o- foi para-nós וּרְאֵ֥ה a חֶרְפָּתֵֽנוּ׃');
INSERT INTO verses VALUES (20513, 25, 5, 2, 'נַחֲלָתֵנוּ נֶהֶפְכָה para os zérim nas nossas batá para os nacarim:');
INSERT INTO verses VALUES (20514, 25, 5, 3, 'orfanos fomos nós pai nossas-mães pai');
INSERT INTO verses VALUES (20515, 25, 5, 4, 'de-nos em prata nosso vinho nossas árvores בִּמְחִ֥יר יָבֹֽאוּ׃');
INSERT INTO verses VALUES (20516, 25, 5, 5, 'sobre [צַוָּארֵ֙נוּ֙] [נִרְדָּ֔פְנוּ] [יָגַ֖עְנוּ] [*לא] para-nós');
INSERT INTO verses VALUES (20517, 25, 5, 6, 'Mitzrayim [נָתַ֣נּוּ] mão Assíria [לִשְׂבֹּ֥עַֽ] pão');
INSERT INTO verses VALUES (20518, 25, 5, 7, 'אֲבֹתֵ֤ינוּ חָֽטְאוּ֙ os seus pecados sofreram:');
INSERT INTO verses VALUES (20519, 25, 5, 8, 'עֲבָדִים e falaram vendê-los quebra não-há deles:');
INSERT INTO verses VALUES (20520, 25, 5, 9, 'em nossas almas profeta לַחְמֵ֔נוּ de-diante-de espada o-meadero');
INSERT INTO verses VALUES (20521, 25, 5, 10, 'nosso couro forno foram calcinados de-diante-de zelafot ra''ab׃');
INSERT INTO verses VALUES (20522, 25, 5, 11, 'mulheres betsiyon inu [בְּתֻלֹ֖ת] em-cidades-de Judá');
INSERT INTO verses VALUES (20523, 25, 5, 12, 'sarim em-lhes nitlu face-de zekenim não nehedaru׃');
INSERT INTO verses VALUES (20524, 25, 5, 13, 'bachurim tehon nasa''u u''neirim ba''ets kashalu :');
INSERT INTO verses VALUES (20525, 25, 5, 14, 'זְקֵנִים mishar shavatu em jovens minaginatam :');
INSERT INTO verses VALUES (20526, 25, 5, 15, 'cessou משׂושׂ nosso-líbbo se-tornar para-abel nossa-mechol');
INSERT INTO verses VALUES (20527, 25, 5, 16, 'caímos-naphala coroa nossa-rosh ai-de agora que porque pecamos');
INSERT INTO verses VALUES (20528, 25, 5, 17, 'sobre ser foi davoh nosso-líbbo sobre estes tornaram-se-chashu עֵינֵֽינוּ׃');
INSERT INTO verses VALUES (20529, 25, 5, 18, 'sobre monte-de Siao se-sheshamem sua-šualim הלכו- nele-verso');
INSERT INTO verses VALUES (20530, 25, 5, 19, 'tu yhwh para-sempre [תֵּשֵׁ֔ב] [כִּסְאֲךָ֖] para-geração [וָדֽוֹר]');
INSERT INTO verses VALUES (20531, 25, 5, 20, 'por-que LANETZACH- תישכחנו- תּעַזְבֵ֖נוּ לארך- dias');
INSERT INTO verses VALUES (20532, 25, 5, 21, 'HASHIBENU- yhwh a-ti novo יاما- como-dantes:');
INSERT INTO verses VALUES (20533, 25, 5, 22, 'que se maos me-assustaste-nos foste-irritado sobre nós até muito');
INSERT INTO books VALUES (26, 'EZK', 'Ezequiel', 'AT', 48);
INSERT INTO chapters VALUES (803, 26, 1, 28);
INSERT INTO verses VALUES (20534, 26, 1, 1, 'e-houve em-trinta ano no-quarto em-o-cinco do-mês e-eu dentro-de- a-exílio sobre rio-de já foram-abertas os-céus e-vi visões Elohim');
INSERT INTO verses VALUES (20535, 26, 1, 2, 'em-cinco para-o-mês ela o-ano a-cinquentésima para-o-exílio o-rei Joiakin');
INSERT INTO verses VALUES (20536, 26, 1, 3, 'foi ser palavra-de yhwh a Iequiel filho-de Bozí o-sacerdote em-terra-de cushitas sobre rio-de já e-foi sobre-ele nome mão-de yhwh');
INSERT INTO verses VALUES (20537, 26, 1, 4, 'e-eu-vi e-eis espírito tempestade veio-a de o-norte nuvem grande e-fogo se-separando a-ele para-ele ao-redor e-do-meio-dele fonte-de-água o-chashmal de-meio o-fogo');
INSERT INTO verses VALUES (20538, 26, 1, 5, 'e-do-meio-dele semelhança quatro criaturas-vivas וְזֶה֙ de-seu-aparecimento semelhança homem para-elas-verso-final');
INSERT INTO verses VALUES (20539, 26, 1, 6, 'e-quatro face para-uma e-quatro como asas para-uma a-eles');
INSERT INTO verses VALUES (20540, 26, 1, 7, 'e-pés-deles רגל retas e-soalheira-de-mão de-seus-pés como-pé רגל bezerro e-brilhantes como-olho cobre maldito');
INSERT INTO verses VALUES (20541, 26, 1, 8, 'homem de-baixo-de homem debaixo-de אַרְבַּ֣עַת sobre e-faces-deles e-asas-deles para-quatro-deles');
INSERT INTO verses VALUES (20542, 26, 1, 9, 'unidas mulher a achotah asas-deles não se-virarem em-a-sua-andar homem a Éber de-seus-faces and andarão');
INSERT INTO verses VALUES (20543, 26, 1, 10, 'e-semelhança-de faces-de-eles face-de homem e-de-faces leão a a-direita para-quatro-de-eles e-de-faces- boi de-o-esquerdo para-quatro-de-ele e-as-faces- de-a-águia para-quarenta-verso-final');
INSERT INTO verses VALUES (20544, 26, 1, 11, 'e-as-faces-deles e-as-aspas-deles separadas de-acima para-cada-homem dois unidas homem e-duas cobertas את corpos-deles-verso-final');
INSERT INTO verses VALUES (20545, 26, 1, 12, 'ואיש a Éber sua-face a El que ele-será- em-o a-espírito não eles-andarão não eles-sentar-se-ão em-a-sua-andada');
INSERT INTO verses VALUES (20546, 26, 1, 13, 'e-forma os-animais de-seu-aparência como-de-fogos fogo as-chamas como-a-apariência as-luzes ela entre entre os-animais e-brilho para-o-fogo e-de o-fogo saindo raio');
INSERT INTO verses VALUES (20547, 26, 1, 14, 'e-os-animais correndo e-retornando como-a-aparição do-raio-de- Luz');
INSERT INTO verses VALUES (20548, 26, 1, 15, 'e-eu-vi os-seres-vivos e-eis roda um na-terra ao-lado-de das-criaturas-vivas para-quatro faces-suas');
INSERT INTO verses VALUES (20549, 26, 1, 16, 'da-aparição das-rodas e-os-seus-trabalhos como-de-olho terafim e-forma um para-quarenta e-aparência-deles e-os-seus-trabalhos como será o-disco no-meio-de o-disco:');
INSERT INTO verses VALUES (20550, 26, 1, 17, 'sobre quatro de-seus-quartos em-a-leitei-los não não eles-ser-virão em-a-leitei-eles');
INSERT INTO verses VALUES (20551, 26, 1, 18, 'e-sobre-elas e-alto a-eles e-tremor a-eles e-sobre-eles cheias-de olhos ao-redor para-quarenta');
INSERT INTO verses VALUES (20552, 26, 1, 19, 'e-em-a-andar os-animais irão os-carros junto-deles e-em-a-elevar-se os-animais de-cima-de a-terra eles-serão-elevados os-carros');
INSERT INTO verses VALUES (20553, 26, 1, 20, 'sobre que ele-será- nome o-sopro para-andar eles-andarão lá a-sopro para-andar e-os-ofânicos serão-elevar-se-ão que espírito espírito a-viva em-o-ofânicos');
INSERT INTO verses VALUES (20554, 26, 1, 21, 'na-sua-andar-dos e-eles-andarão e-na-seu-parar e-eles-estabelecer-se-ão e-na-sua-ser-elevado de-cima-de a-terra serão-elevar-se-ão os-ofânicos para-eles que espírito a-viva em-ofanims');
INSERT INTO verses VALUES (20555, 26, 1, 22, 'e-dmut sobre cabeças-de expansão expansão como-ayin o-kerah o-nora natiu sobre rosh-em de-acima');
INSERT INTO verses VALUES (20556, 26, 1, 23, 'e-em-baixo-de a-expansão kanfei-em yesharot mulher a irmã-a para-homem duas cobrindo-os a-elas e-para-homem duas cobrindo-os a-elas את corpos-deles-verso-final');
INSERT INTO verses VALUES (20557, 26, 1, 24, 'e-eu-ouvi a voz-de as-asas-deles águas águas רַבִּ֤ים como-a-voz- voz em-a-sua-caminhada voz enfrentando como-a-voz do-lager em-seu-permanecer vocês-estenderão as-asas-deles-verso');
INSERT INTO verses VALUES (20558, 26, 1, 25, 'e-foi de-cima-de à-expansão para-o-céu que sobre cabeça-deles vocês-estenderão as-asas-deles');
INSERT INTO verses VALUES (20559, 26, 1, 26, 'e-de-em-o-alto à-expansão que sobre o-cabeças-deles como-a-aparência semelhança סַפִּ֖יר semelhança semelhança e-sobre semelhança a-cadeira homem como-a-aparência homem sobre-ele de-acima');
INSERT INTO verses VALUES (20560, 26, 1, 27, 'e vi como olho חַשְׂמָל como visão fogo casa-de a-ela ao-redor de visão lombos-seus e para cima e de visão suas coxas e-lá-ma-tá vi c-ma-ra-á-e- a-ele v-no-gá-h para-ele ao-redor');
INSERT INTO verses VALUES (20561, 26, 1, 28, 'como-aspecto do-arco que será na-névoa em-dia-de da-chuva assim aspecto do-brilho ao-redor ele visão semelhança kavod- yhwh e-eu-vi e-eu-cai sobre voz ve-eshmáh voz-que falando');
INSERT INTO chapters VALUES (804, 26, 2, 10);
INSERT INTO verses VALUES (20562, 26, 2, 1, 'E-disse a-mim filho-de homem ficou-em-pé sobre pés-teus e-eu-falarei te:');
INSERT INTO verses VALUES (20563, 26, 2, 2, 'e-ela-vieram Bi espírito como-que palavra a-mim e-ela-me-manteve sobre caminhos-meus e-eu-ouvi את מדדבר para-mim');
INSERT INTO verses VALUES (20564, 26, 2, 3, 'E-disse a-mim filho-de homem enviando eu você a filhos-de Israel a nações os-rebeldes que rebeldem- bi הֵ֤מָּה o-dia pashú em-mim até osso o-dia a-esta');
INSERT INTO verses VALUES (20565, 26, 2, 4, 'e-os-filhos duras face e-fortes- coração eu enviando te a-eles e-dirás a-eles disse disse Adonai yhwh');
INSERT INTO verses VALUES (20566, 26, 2, 5, 'e-eles se yishme''u que yechedlu porque casa merry que ve-yad''u ser profeta foi betokhem');
INSERT INTO verses VALUES (20567, 26, 2, 6, 'e-tu filho-de homem a temer dentre-eles que a temer porque saravim tu você e-a aqrabim tu habitante que a temera e-mifneihem a techa-at porque casa alegre-se eles');
INSERT INTO verses VALUES (20568, 26, 2, 7, 'e falarás a devarai a-eles se que e-se yechdalu porque alegre-se eles');
INSERT INTO verses VALUES (20569, 26, 2, 8, 'e-tu filho-de homem ouviu a que eu falando-é para-ti a תְּהִי־ meri como-casa-de o-méri petze peicha e-comer a que eu deu para-ti');
INSERT INTO verses VALUES (20570, 26, 2, 9, 'e-eu-vi e-eis- mão emissária a-mim e-eis- em-ele megilat- livro');
INSERT INTO verses VALUES (20571, 26, 2, 10, 'e-ele-se-estendeu a-ela diante-de-mim e ela escrita face e-depois e-escrito a ela ninhos e-grito e-ele-foi');
INSERT INTO chapters VALUES (805, 26, 3, 27);
INSERT INTO verses VALUES (20572, 26, 3, 1, 'E-disse a-mim filho-de homem a que você-encontrará a-comer comer a ha-megilah a-esta e-ir palavra a casa Israel');
INSERT INTO verses VALUES (20573, 26, 3, 2, 'e-eu-abri a meu-boca e-ele-me-comeu את a-manchete a esta');
INSERT INTO verses VALUES (20574, 26, 3, 3, 'E-disse a-mim filho-de homem em-teu-ventre você-comerá e-de-tua-intestino enche את ha-megilah a-esta que eu deu a-ti e-que-eu-comi e-foi por-me como-mel para-doce');
INSERT INTO verses VALUES (20575, 26, 3, 4, 'E-disse a-mim filho-de homem vai-para veio a casa Israel e-falares com-meu-discurso a-eles');
INSERT INTO verses VALUES (20576, 26, 3, 5, 'que não a povo profundidades-de língua e-honras tu tu emissário a casa Israel');
INSERT INTO verses VALUES (20577, 26, 3, 6, 'não a povos muitos fundura língua-impudente e-honrados de-língua que não você-ouvirá palavras-deles se não a-eles enviaste-te eles אֵלֶּה יִשְׁמְעוּ para-ti');
INSERT INTO verses VALUES (20578, 26, 3, 7, 'e-Beit Israel não quererão para-ouvir para-ti porque não-eles cobras para-ouvir que porque todo casa Israel fortes- de-rosto e-duro- coração eles');
INSERT INTO verses VALUES (20579, 26, 3, 8, 'eis dei a de-teu-rosto fortes para-a peneyhem e-com da-testa-de-teu forte próximo-a de-sua-testa');
INSERT INTO verses VALUES (20580, 26, 3, 9, 'como-vidro força de-fortaleza dei da-teu-testa não tremas elas e-não que de-diante-deles porque casa-de alegre-se eles');
INSERT INTO verses VALUES (20581, 26, 3, 10, 'E-disse a-mim filho-de homem a todo davrayikh que falar-ei para-ti pe-go com-o-coracao-tu ve-aza-necha ouviu');
INSERT INTO verses VALUES (20582, 26, 3, 11, 've-lekh veio a o-exílio a filhos-de seu povo e falarás a-eles e-dirás disse assim disse Adonai yhwh se ouvirão e-se yechadlu');
INSERT INTO verses VALUES (20583, 26, 3, 12, 'vat-tissaeni espírito va-eshma após-mim voz raash grande bendito kavod- yhwh מִמְּקוֹמֽוֹ׃');
INSERT INTO verses VALUES (20584, 26, 3, 13, 've-qol as-asas ha-chayot maskhot mulher a אֲחוהָהּ e voz os-carros para-suas-vizinhanças e-voz ruído grande');
INSERT INTO verses VALUES (20585, 26, 3, 14, 'e-Espírito-de elevou-me e-a-levou-me e-ei-viagem amargo em-o-calor espírito-meu e a mão- yhwh sobre-mim forte');
INSERT INTO verses VALUES (20586, 26, 3, 15, 'e-vi a a-exílio Tel abib os-que-sentam-se a rio-de já eles sentando-se nome e-eu-sentei-me nome sete dias destruidores em-meio-de-eles');
INSERT INTO verses VALUES (20587, 26, 3, 16, 'e-houve de-fim-de sete-de dias E-foi e-houve yhwh a-mim dizendo');
INSERT INTO verses VALUES (20588, 26, 3, 17, 'filho-de homem observando eu-deti-te para-casa-de Israel e-ouviste da-boca-de palavra e-advertistes eles de-mim');
INSERT INTO verses VALUES (20589, 26, 3, 18, 'em-minhas-palavras para-o-raso morrendo morrerás e-não hizharto e-não dibart lehazhir para-o-raso midarcho harsaah lehachiot ele רָשָׁע֙ baavono yamut vedamo da tua mão אֲבַקֵּֽשׁ׃');
INSERT INTO verses VALUES (20590, 26, 3, 19, 'e-tu porque hizarta perverso-o e-não retornou me-reshuo ele harshaah ele ba-avono yamut e-tu את- נַפְשְׁךָ֥ hitzalta');
INSERT INTO verses VALUES (20591, 26, 3, 20, 'e-em-retorno justo me-tzido ואsha enganho e-darei mikshol diante-dele ele morra que não hizartohu be-chatato morra e-não lembrareis-vos justiça-seu que fez e-sangue-seu da tua mão אֲבַקֵּֽשׁ׃');
INSERT INTO verses VALUES (20592, 26, 3, 21, 'e-tu que advertistes-ele justo para-não pecar justo e-ele não pecou vida-seu que porque cuidamos-nos e-tu את- נַפְשְׁךָ֥ livrai-vos');
INSERT INTO verses VALUES (20593, 26, 3, 22, 'e-foi sobre-mim nome mão-de E-disse E-disse a-mim levantou sai a a-biqva e-ali falarei te');
INSERT INTO verses VALUES (20594, 26, 3, 23, 'e-elevei-me e-sai a a-biqva e-eis- nome kavod- yhwh ficou-em-pé como-honra que vi sobre rio-de já e-cai sobre face-de');
INSERT INTO verses VALUES (20595, 26, 3, 24, 'e-ela-vem-a espírito espírito e-ela-mante-me sobre caminhos-meus E-disse oti'' E-disse a-mim no-meio-de fechou-se em-meio-de em-a-casa-tua');
INSERT INTO verses VALUES (20596, 26, 3, 25, 'e-tu filho-de eis eis deram sobre-ti cordões e-te-vincularão com-eles e-não sairás em-meio-de-eles');
INSERT INTO verses VALUES (20597, 26, 3, 26, 'e a tua língua advice a teu maxilar e-né-ʔe·lam·tá· a-eles será a-eles que prova porque casa amargura eles');
INSERT INTO verses VALUES (20598, 26, 3, 27, 'e-em-falar-teu sinal-te abrirei a boca-tua e-dirás a-eles disse disse Adonai yhwh o-que-ouve ouvirá e-o-cessar cessará porque que alegre-se eles');
INSERT INTO chapters VALUES (806, 26, 4, 17);
INSERT INTO verses VALUES (20599, 26, 4, 1, 'e-tu filho-de homem toma para-ti para-a-pedra e-tu-darás sinal-aquela diante-de-ti e-copiarás em-a cidade a Jerusalém');
INSERT INTO verses VALUES (20600, 26, 4, 2, 'וְנָתַתָּ֨ה em-aquela מָצ֗וֹר וּבָנִ֤יתָ sobre-ela דָּיֵ֔ק וְשָׁפַךְתָּ֥ sobre-ela SOLDÁ וְנָתַתָּ֨ה al-eha מַחֲנ֛וֹת וְשִׂים־ עָלֶ֥יהָ כָּרִ֖ים ao-redor');
INSERT INTO verses VALUES (20601, 26, 4, 3, 'e-tu toma para-ti machabath ferro ve''natatatha a-ela parede-de entre-ti e-entre e-entre a-cidade vahacinotha a paneika a-ela e-será no-bem-ataque ve''zartha sobre-ela sinal-de ela segundo-casa-de Israel');
INSERT INTO verses VALUES (20602, 26, 4, 4, 'e-tu deita-te sobre do-teu-lado o-esquerdo e-colocarás a iniquidade-de casa-de Israel sobre-ele número-de os-dias que deitar-se-ás sobre-ele carregará a das-suas-iniquidades');
INSERT INTO verses VALUES (20603, 26, 4, 5, 'e-eu dei a-ti a segundo iniquidade-deles para-o-número dias três- dia e-noventa dia e-levanta-te iniquidade-de casa-de Israel');
INSERT INTO verses VALUES (20604, 26, 4, 6, 'e-comerás a estes e-deitares-te-ás sobre lado-tu-o segunda-noite e-levanta-te a iniquidade casa-de dia dia dia dia para-a-ano dia para-ti darás-lhe-o para-ti');
INSERT INTO verses VALUES (20605, 26, 4, 7, 'e-a lepra Jerusalém farás perante-você e-a-tua-mão nua e-você-proferirá sobre-ela');
INSERT INTO verses VALUES (20606, 26, 4, 8, 'e-eis dei sobre-ti capas e-não você-será-virado de-teu-lado a dias-de até com-tua-compleição dias-de teu-muro');
INSERT INTO verses VALUES (20607, 26, 4, 9, 'e-tu toma a-te chia e-aveia e-feno e-acácia e-dávila e-cismó e dará elas um um e farás a-ti para-ti para pão número os-dias que você dormindo sobre do teu lado dia centenas e sessenta dia o comerão');
INSERT INTO verses VALUES (20608, 26, 4, 10, 'e-alimento-vos que comê-lo-vos em-peso vinte siclo para-o-dia de-tempo até tempo comê-lo-vos');
INSERT INTO verses VALUES (20609, 26, 4, 11, 'e-águas em-mesura bebereis sexta הַהִ֑ין de-tempo até tempo beberás');
INSERT INTO verses VALUES (20610, 26, 4, 12, 'e-pãezinho de-espelta a-comerás e-ele/ela por-causas-de saída o-homem seu-pãezinho per-ey-nay-hem');
INSERT INTO verses VALUES (20611, 26, 4, 13, 'E-disse yhwh assim comerão filhos-de Israel a pão-deles impura entre-os-povos que expulsareis-os nome');
INSERT INTO verses VALUES (20612, 26, 4, 14, 'e-disse ahah Adonai yhwh eis alma-minha não impureza e-carne-de-animais-mortos e-carne-mordida-por-felino não comi desde-a-minhiceira-idade e-até até-agora e-não veio por-me de-a-carne rejeitado');
INSERT INTO verses VALUES (20613, 26, 4, 15, 'E-disse a-mim viu dei a-ti a o-bovino sob debaixo o-homem o-homem את- o teu pão sobre-eles');
INSERT INTO verses VALUES (20614, 26, 4, 16, 'E-disse a-mim filho-de homem eis-me quebrando mate- pão em-Jerusalém e-comerão- pão-de em o peso e-com-ansiedade e-agua em-o-corte e-no-deserto bebam');
INSERT INTO verses VALUES (20615, 26, 4, 17, 'para faltara pão e-agua e-nascerão homem e seu irmão e-amargaram em-seus-pecados');
INSERT INTO chapters VALUES (807, 26, 5, 17);
INSERT INTO verses VALUES (20616, 26, 5, 1, 'e tu filho-de homem toma espada chēreb aguda tesoura os-cabelos tomá-la para-ti e-passarás sobre cabeça-teu a-ti barba-tua e-toma para-ti pesadas peso e-partirás-os');
INSERT INTO verses VALUES (20617, 26, 5, 2, 'terça-parte em-aur queimarás no-meio-de a-cidade quando-cheia dias-de a-o-sitio e-tomará a o-terceiro tu-golpearás com-a-espada ao-redor-dela e-a-trigesima tu-espalharás para-o-vento e espada extenso depois-deles');
INSERT INTO verses VALUES (20618, 26, 5, 3, 'e-toma de-lá pouco em-número e-apertarás eles com-as-aspas-teus');
INSERT INTO verses VALUES (20619, 26, 5, 4, 'e deles ainda tomarás e lançaste elas a meio-de o-fogo eles eles nós dele vem a ser fogo a todo casa Israel');
INSERT INTO verses VALUES (20620, 26, 5, 5, 'assim disse Adonai yhwh esta Jerusalém no-meio-de as-nações colocaste-a e-em-torno-de-a terras');
INSERT INTO verses VALUES (20621, 26, 5, 6, 'e se moveu a pelos-meus-julgamentos para-a-ímpia de as-nações e- minhas-leis que a-terras: que suas-sí-cas porque pelos-meus-julgamentos rejeitaram minhas-leis não הלכו בהם׃');
INSERT INTO verses VALUES (20622, 26, 5, 7, 'portanto assim disse- Adonai yhwh por-causa-de voces-se-tornarem de as-nações que em-vosso-redor não não andastes não מִשְׁפָּטַ֖י não עֲשִׂיתֶ֑ם e julgamentos as-nações não vossas voltas não vocês-fizeram');
INSERT INTO verses VALUES (20623, 26, 5, 8, 'portanto assim disse Adonai yhwh eis-me sobre-ti também eu e-eu-fiz em-te de-leis para-olhos-de os-gentios');
INSERT INTO verses VALUES (20624, 26, 5, 9, 'e-fiz-eu em-ti את que não fiz e-a que não אעשה como-esse ainda por-causa-de todo minhas-abominações');
INSERT INTO verses VALUES (20625, 26, 5, 10, 'portanto pais comerão filhos dentro-de-te e-filhos comerão pais-deles e farei em-te justiças e-me-zeritei a todo resto-te para-todo espírito');
INSERT INTO verses VALUES (20626, 26, 5, 11, 'por-isso vive eu oráculo-de Adonai yhwh se não porque a do-meu-santuário tornaste-te-imundo em-todo abominações-tua e-em-todo tuas-abominações não eu arrancarei-eu e-não torrarás-tu meu-olho e-também eu não soprei-eu');
INSERT INTO verses VALUES (20627, 26, 5, 12, 'teu-trigésimo em-a-peste morrerão e pela fome cessarão-eles no-teu-meio e-a-trigésima pela-espada yiphlu em-tuas-vizinhanças e-a-três-ésima para-todo espírito azaração e espada extenso depois-deles');
INSERT INTO verses VALUES (20628, 26, 5, 13, 'e-completa meu-rabicho e-eu-estabeleci minha-ira com-eles e-eu-consolara וְיָדֻעוּ porque yhwh yhwh falei-eu em-minha-irritação quando-eu-acabarei חֲמָתִ֖י em-eles');
INSERT INTO verses VALUES (20629, 26, 5, 14, 'e-te-dar-ei para-a-espada e-para-opressão בַּגּוֹיִ֖ם que em-torno-de-você aos-olhos-de todo passante');
INSERT INTO verses VALUES (20630, 26, 5, 15, 'e será insulto e-maldição מוּסָ֣ר e-desolação para-os-povos que em-torno-de-você em-fazer-me בקיך juízos com-ira e-em-a-ira e-em-repreensões a-ira eu yhwh e eu falei:');
INSERT INTO verses VALUES (20631, 26, 5, 16, 'em-o-meu-envio a de-flechas o-fome os-malvados neles que foram le-mash-chit que eu-enviarei eles para-destruir-vocês e-fome coletando a-vós e-partirei para-vocês mate- pão');
INSERT INTO verses VALUES (20632, 26, 5, 17, 'e-espalharei em-vocês fome וְחַיָּ֤ה malignidade e-despojar-vos-ei e-peste e-sangue יַעֲבָר־ Bakh e-espada trarei sobre-ti yhwh yhwh e eu falei:');
INSERT INTO chapters VALUES (808, 26, 6, 14);
INSERT INTO verses VALUES (20633, 26, 6, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20634, 26, 6, 2, 'filho-de homem colocar  פָּנֶ֖יךָ  a montes-de Israel e profetizarão a-eles');
INSERT INTO verses VALUES (20635, 26, 6, 3, 'e dirás os-montes Israel ouvi palavra-de Adonai yhwh assim disse Adonai yhwh para-os-montes e-para-as-colinas aos-cursos-d''água eis-me eu מביא sobre-vós espada e-destruirei-eu em-vossas-alturas');
INSERT INTO verses VALUES (20636, 26, 6, 4, 'e-nascerão vossos-araís e-serão-partidos vosso-templo e-derribo-ei cadáveres-vosso diante-de idólatras-vosso');
INSERT INTO verses VALUES (20637, 26, 6, 5, 'e dar-lhes-ei a carcaças-de filhos-de Israel diante-de idólatras-seus e-espalharei-eu a ossos-vosso em-torno-de mizbĕkhōteikhem');
INSERT INTO verses VALUES (20638, 26, 6, 6, 'em-todo moradas-vosso ha-arim תֶּחֱרַ֔בְנָה e-altar se-desgostem a-fim-de serão-destruídos e-se-envergonharão de-vossos-álibus e-serão-partidos e-serão-arruinados de-vossas-imagens e-serão-despedaçados vosso-templos e-serão-exterminados os-vossos-trabalhos-verso-final');
INSERT INTO verses VALUES (20639, 26, 6, 7, 'e-caiu profanação em-o-meio-de-vós e-voces-sabereis porque yhwh yhwh');
INSERT INTO verses VALUES (20640, 26, 6, 8, 'e-livrei-vos bi-heyet- a-vós vossos-redentores espada em-países em-vossas-cavernas em-países:');
INSERT INTO verses VALUES (20641, 26, 6, 9, 'e-eles-recordarão vossos-refugiados de-mim nas-nações que foram-capturados- nome que quebrei-me a seus corações a-prostituta que se-apartou de-sobre-mim e-את seus olhos as-prostitutas atrás-de elohimzinhos-deles e-roubarão em-frente-a-eles a-todo as-coisas-más que fizeram para-todo abominações-deles-verso-final');
INSERT INTO verses VALUES (20642, 26, 6, 10, 'e-saberão porque yhwh não não a de-gratis a-eles para-fazer a-eles a-maldade a esta');
INSERT INTO verses VALUES (20643, 26, 6, 11, 'assim disse Adonai yhwh o-ferir em-a-mão-tua e-aplastar em-o-pé-tu a irmão El todo abominações raot casa Israel que com-a-espada em-o-fome-grande e-em-a-praga cairão');
INSERT INTO verses VALUES (20644, 26, 6, 12, 'o-longe em-o-poder morre e-o-próximo com-a-espada cairá e-o-que-resta e-o-guardado em-a-fome morra e-eu-satisfarei חֲמָתִ֖י em-eles');
INSERT INTO verses VALUES (20645, 26, 6, 13, 'וִֽידַעְתֶּם֙ porque yhwh yhwh em-ser no-meio-de בתוך os-seus-idólatras em-torno-de a El todo Gibeá Rama em-todo cabeças-de das-montanhas e-em-o-baixo todo עֵ֤ץ ראַעֲנָן e-em-baixo-de todo אֵלָ֣ה cobertura lugar que a-todo nome aroma suave para-todo elohimzinhos-deles-verso-final');
INSERT INTO verses VALUES (20646, 26, 6, 14, 'וְנָתַ֤יתִי a mão-minha sobre-eles וְנָתַתִּ֨י a a-terra desolação e-desolado de-deserto-de destruição em-todo moradas-deles yhwh porque eu yhwh');
INSERT INTO chapters VALUES (809, 26, 7, 27);
INSERT INTO verses VALUES (20647, 26, 7, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20648, 26, 7, 2, 'e-tu filho-de homem assim disse Adonai yhwh para-a-terra Israel fim veio do-fim sobre a-terra a-terra');
INSERT INTO verses VALUES (20649, 26, 7, 3, 'agora o-fim sobre-ti וְשִׁלַּחְתִּ֤י teu-nariz sobre-ti e-julgarei-te conforme-tuas-rotas e-darei sobre-ti a todo minhas-abominações');
INSERT INTO verses VALUES (20650, 26, 7, 4, 'e-não conservarás minha vista sobre-ti e-não que porque tuas-rotas em-te darei e-tus-abominações em-te ser-eis e-conhece-reis yhwh eu yhwh');
INSERT INTO verses VALUES (20651, 26, 7, 5, 'assim disse Adonai yhwh maldade uma maldade eis em-a');
INSERT INTO verses VALUES (20652, 26, 7, 6, 'fim veio veio o-fim ele-adiantou-se a-ti eis em-a');
INSERT INTO verses VALUES (20653, 26, 7, 7, 'vindo-a a-colheita a-ti habitante-de a-terra veio o-tempo próximo o-dia confusão e-não grito הָרִים׃');
INSERT INTO verses VALUES (20654, 26, 7, 8, 'agora de-a-proximidade eu-virei ira-meu sobre-ti וְכִלֵּיתִ֤י nervo-meu sobre-ti e-julgarei-te segundo-caminho-tua e-darei sobre-ti a todo abominações-tuas');
INSERT INTO verses VALUES (20655, 26, 7, 9, 'e-não terás-terror meu-o-olho e-não eu-soprei como-tus-caminhos em-você eu-darei e-tus-abominações em-teu-interior serás-você que porque yhwh yhwh machucador');
INSERT INTO verses VALUES (20656, 26, 7, 10, 'eis o-dia eis vindo-a saiu-a a-tzfira tzats o-matteh parach a-zadon');
INSERT INTO verses VALUES (20657, 26, 7, 11, 'o-hamas qā·m para-mato- resha'' não de-les e-não de-hamonam e-não me-hamehemem e-não nohah neles');
INSERT INTO verses VALUES (20658, 26, 7, 12, 'veio haet higia o-dia haqoneh a yismah vehamoker que yitabbal porque haron a todo hamona');
INSERT INTO verses VALUES (20659, 26, 7, 13, 'que o-vendedor a não não retornará e mais na-vida de-seus-vivos porque não a todo sua-multidão não não e-homem em-sua-avareza de-seu-vivo não e-fortalecerão-se');
INSERT INTO verses VALUES (20660, 26, 7, 14, 'tocarão no-tocador e-preparou o todo e-não-há andou para-a-guerra que haroni a todo hamonahh');
INSERT INTO verses VALUES (20661, 26, 7, 15, 'a-espada no-exterior e-a-praga e a fome de-casa que no-campo com-a-espada morra e-que na-cidade fome e-praga comerão');
INSERT INTO verses VALUES (20662, 26, 7, 16, 'e-salvar-se-ão fugi-dos-eles e-sejam a as-montanhas de-aves das-almas kulam as-montanhas homem בְּעָוֹן׃');
INSERT INTO verses VALUES (20663, 26, 7, 17, 'todo das-mãos serão-arrancadas e-todo dos-pés andarão águas');
INSERT INTO verses VALUES (20664, 26, 7, 18, 'e-cinturaram-se sacos e-vestiu eles pulsação e-para todo face vergonha e-em-todo cabeças-deles careca');
INSERT INTO verses VALUES (20665, 26, 7, 19, 'prata-deles fora lançarão e-ouro-deles para-imundície será prata-deles e-seu-ouro não pode para-salvá-los em-dia-de yhwh yhwh não não os-abastecerão não não os-encherão porque ser עֲוֺנָ֖ם foi');
INSERT INTO verses VALUES (20666, 26, 7, 20, 'e-aliêns sua-verdade para-gon lhe-fizeram e-imagens-de suas-abominações seus-escarmentos fizeram nele sobre assim a-eles a-eles para-moça');
INSERT INTO verses VALUES (20667, 26, 7, 21, 'e-deste-o com-a-mão-de os-estrangeiros para-o-excesso a-terra a-terra para-a-presa');
INSERT INTO verses VALUES (20668, 26, 7, 22, 'e-virei-para-o-lado-de face-de de-eles e-prostituíram a o-nordeste e-virão-a nela os-transgressores e-vos-profaneis-a');
INSERT INTO verses VALUES (20669, 26, 7, 23, 'fez a-ferida-dele que a-terra encheu-se juízo sangue e-a-cidade cheia violência');
INSERT INTO verses VALUES (20670, 26, 7, 24, 'e-eu-trarei malignos nações e-herdarão a casas-deles e habitar orgulho fortes e-herdarão santos-deles');
INSERT INTO verses VALUES (20671, 26, 7, 25, 'cuidado- veio e-pediram paz vā-ʾayin');
INSERT INTO verses VALUES (20672, 26, 7, 26, 'יהוה sobre יהוה vem-a-ser e-notícia a a-notícia ser-á e-pediram visão do-profeta e-lei perderá de-sacerdote וְעֵצָ֖ה de-anciãos');
INSERT INTO verses VALUES (20673, 26, 7, 27, 'o-rei se-lamentará e-príncipe-de ele-vestirá sem semear e-mãos com a-terra serão-temerosas de-seu-caminho farei elas e-em-seus-juízos eu-julgarei-os e-saberão yhwh eu yhwh');
INSERT INTO chapters VALUES (810, 26, 8, 18);
INSERT INTO verses VALUES (20674, 26, 8, 1, 'e-houve em-a-ano o-sexto na-sexta em-o-cinco do-mês eu habitante-de em-a-meu-casa e-os-anciãos Judá sentando-se diante-de-mim e-caiu-se sobre-mim nome mão Adonai yhwh');
INSERT INTO verses VALUES (20675, 26, 8, 2, 'e-eu-vi e-eis semelhança כאמראה- fogo de-a-aparência de-seus-cintura e-para-baixo fogo e-de-sua-cintura e-para-alto כאמראה- brilho fonte-de-água a-chashmalah:');
INSERT INTO verses VALUES (20676, 26, 8, 3, 'e-enviou תַּבְנִיט mão e-me-levou em-o-tzitzit cabeça-de mim e-ela-encontrou a-mim espírito entre a-terra e-entre os-céus e-ela-me-trouxe oti Jerusalém em-as-visões Elohim a entrada-de porta-de das-internas que se encolhe צָפ֔וֹנָה que nome habitação semelhante a-ira o-conquistador');
INSERT INTO verses VALUES (20677, 26, 8, 4, 'e-eis: nome glória Elohim-de Israel como-a-aparição que vi na-vale');
INSERT INTO verses VALUES (20678, 26, 8, 5, 'E-disse a-mim filho-de homem sair- o-caminho-de olhos-teus caminho ao-norte o-caminho-de e-olhos caminho צָפ֔וֹנָה e-eis  Mitsafon para-portão-de o altar sinal a-ira este na-entrada');
INSERT INTO verses VALUES (20679, 26, 8, 6, 'E-disse a-mim filho-de homem tu tu fazendo abominações grandes que casa-de יִשְׂרָאֵ֣ל ׀ fazendo aqui para-a-longe de-sobre de-meu-santuário de-cima-de volver-te-ás verás abominações grandes-verso');
INSERT INTO verses VALUES (20680, 26, 8, 7, 'e-trouxe me-a a entrada-de a-corte e-eu-vi e-eis cavidade- um na-parede׃');
INSERT INTO verses VALUES (20681, 26, 8, 8, 'E-disse a-mim filho-de homem חֲתָר־ por-favor campo e-ele-ganhei na-parede um porta um');
INSERT INTO verses VALUES (20682, 26, 8, 9, 'E-disse a-mim veio וּרְאֵה֙ a as-abominações as-más eles eles fazendo aqui');
INSERT INTO verses VALUES (20683, 26, 8, 10, 'e-eu-vi e-eu-ve e-eis todo for-ma réptil e-animal ab-nego-cio e-todo גִּלּוּלֵ֖י casa Israel esc-rivo sobre o-muro em-torno- ao-redor');
INSERT INTO verses VALUES (20684, 26, 8, 11, 'e-setenta homem מִזִּקְנֵי casa-de Israel e-Yaazanyahu filho-de sapateiro ficou-em-pé em-eles estão-stando em-frente-de-eles e-homem de-seu-qtor na-sua-mão e-ate an-o o-qtor oleh');
INSERT INTO verses VALUES (20685, 26, 8, 12, 'E-disse para-mim haraita filho-de homem que זִקְנֵ֤י casa-de Israel fazendo be-choshekh homem que maschito porque yhwh não-há yhwh deixar yhwh deixou yhwh a a-terra');
INSERT INTO verses VALUES (20686, 26, 8, 13, 'E-disse a-mim ainda retornarás tireh toevot grandes que eles עֹשִׂ֣ים׃');
INSERT INTO verses VALUES (20687, 26, 8, 14, 'e-trouxe a-mim a porta-de portão casa-de yhwh que a o-setentrional e-eis nome as-mulheres morando chorando a o-tamuz');
INSERT INTO verses VALUES (20688, 26, 8, 15, 'E-disse a-mim viste filho-de homem ainda retornarás verá abominações grandes destes');
INSERT INTO verses VALUES (20689, 26, 8, 16, 'e-trouxe a-mim a átrio-de casa-de yhwh a-interna yhwh entre o-santuário e-entre entre o-ulam e-entre o altar como-vinte e-cinco yhwh os-de-seus-traseiros a e entraria yhwh e-os-de-seus-faces oriente-para e-eles de-vocês-se-curvando ao-oriente para-o-sol');
INSERT INTO verses VALUES (20690, 26, 8, 17, 'E-disse para-mim VISTE? filho-de homem SER-LEVADO? para-casa-de Judá DE-TRABALHOS a as coisas detestáveis que fizeram aqui porque preencheram a a-terra raiva e-voltaram-se para me irritar e-eis-eles enviaram a a canção a sua ira:');
INSERT INTO verses VALUES (20691, 26, 8, 18, 'e-também eu farei com fúria não pouparas minha-olho e-não eu-amarrei-me voz em-minha-ouvido voz-de grande e-não eu-ouvirei a-eles');
INSERT INTO chapters VALUES (811, 26, 9, 11);
INSERT INTO verses VALUES (20692, 26, 9, 1, 'E-chamou em-minha-ouvido voz grande dizendo eles-vieram-se ordens a-cidade e-um-homem instrumento sua-peneira em-mão-sua');
INSERT INTO verses VALUES (20693, 26, 9, 2, 'e-eis seis homens vindo-e de-caminho- portão-de o-alto que voltando-se para-o-norte e-homem instrumento-de espalhador-seu em-mão-de-ele e-homem- um em-o-lhes o-vestiario na-bádim e-manto o-escrevente em-lombos-seus e-vieram e-eles-estabeleceram junto altar-de o-bronze');
INSERT INTO verses VALUES (20694, 26, 9, 3, 'e-honra- Elohim-de Israel naalah de-sobre de-cima-de que foi ser El a a-casa E-chamou E-chamou o-homem o-vestiario os-cordões que manto o-escrevente em-a-entranhas-verso-final');
INSERT INTO verses VALUES (20695, 26, 9, 4, 'E-disse yhwh através em-meio-de a-cidade no-meio-de jerusalém no-meio-de tav sobre frontais os-homens da-lamentação e-dos-lamentos sobre sobre as-averações que-foram-feitas no seu meio:');
INSERT INTO verses VALUES (20696, 26, 9, 5, 'e para os disse em minhas orelhas: traduza na cidade, atrás-dele e matem olhem e-a tenham misericórdia:');
INSERT INTO verses VALUES (20697, 26, 9, 6, 'za-ke-n jovem-moço u-veth-thul-a-ha ve-taph ve-nash-im ta-ha-rag-u le-mash-chi-th e-sobre todo homem que sobre-o a-linha a se-aproximem e-do-meu-sanctuário comecem e-ele-começou nos-homens os-ancianos que diante-de a-casa');
INSERT INTO verses VALUES (20698, 26, 9, 7, 'E-disse a-eles sujem-se a a-casa e-preencham a os-courts chalalim saíam e-sairão e-feriram em-a-cidade');
INSERT INTO verses VALUES (20699, 26, 9, 8, 'e-houve como-as-percussões-deles e-remanesceu eu e-eu-escondi-me sobre face-de e-eu-gritei וָאֹמַר֙ ahah Adonai yhwh tu tu a todo remanescente Israel em-despejando-te a חֲמָתֶךָ sobre Jerusalém');
INSERT INTO verses VALUES (20700, 26, 9, 9, 'E-disse a-mim pecado casa-de Israel e Judá grande muito muito a-terra a-terra sangue e a cidade cheia que porque deixar yhwh yhwh a yhwh e-não-há yhwh viu');
INSERT INTO verses VALUES (20701, 26, 9, 10, 'e também Eu não pouparas minha-olho e-não eu-vexarei-me caminho-lhes em-cabeça-lhes eu-dei');
INSERT INTO verses VALUES (20702, 26, 9, 11, 'e-eis o-homem vestuário as-roupas que a-cáset em-lombos-seus mashív palavra dizendo dizendo tsivítani:');
INSERT INTO chapters VALUES (812, 26, 10, 22);
INSERT INTO verses VALUES (20703, 26, 10, 1, 'e-eu-vi e-eis a a-expansão que os-querubins cabeça os-de-querubins como-a-pedra semelhança como-a-aparição semelhança o-trono apareceu sobre-eles');
INSERT INTO verses VALUES (20704, 26, 10, 2, 'E-disse a o-homem levush os abdins E-disse veio a beinot lagalgal a em-lugar-de lakrubb umalle chafneicha gachalei- fogo mibeinot lakrubbim uzerok sobre a-cidade E-veio para-os-olhos');
INSERT INTO verses VALUES (20705, 26, 10, 3, 'e-os-cruzes estando mimayin para o templo em-vir-seu o-homem e-o-ânio enchei a o recinto o-interno');
INSERT INTO verses VALUES (20706, 26, 10, 4, 'e-ele-se-elevou kavod- de-cima-de de-sobre sobre sobre do-pot a-casa e-ele-se-encheu a-casa a o-ânio e-o-cortiço estava-cheia yhwh nogáh glória yhwh');
INSERT INTO verses VALUES (20707, 26, 10, 5, 'e-som as-asas os-querubins ou-e até o recinto de-a-fora como-som a Shaddai em-falar-ele');
INSERT INTO verses VALUES (20708, 26, 10, 6, 'e-houve em-sua-orda-nán-to a o-homem dizendo os-dá-di-mén dizendo pe-go fogo entre-seus para-a-gal-gál entre-seus para-os-cer-úbi-mén E-veio e-sí-em-o-dén junto o-a-fan:');
INSERT INTO verses VALUES (20709, 26, 10, 7, 'e-enviou o-querubim a mão-sua de-o-lugar para-os-querubins a a-foi os-querubins entre-os E-colocou e-ele-levantou E-deu a E-tomou para-o-vestido הַבַּדִּ֑ים E-tomou e-ele-saiu');
INSERT INTO verses VALUES (20710, 26, 10, 8, 'E-viu para-os-querubins modelo mão-de debaixo sob como suas asas');
INSERT INTO verses VALUES (20711, 26, 10, 9, 'e-eu-vi e-eis quatro ofânnim junto-a ha-kərūbîm ofan um אֵ֚צֶל o-querubim um e-o-carro um junto o-querubim um וּמַרְאֵה֙ as-rodas como-olho pedra tarshish:');
INSERT INTO verses VALUES (20712, 26, 10, 10, 'u-māre‘e-hem semelhança um le-arba‘atam como será o-disco no-meio-de o-disco:');
INSERT INTO verses VALUES (20713, 26, 10, 11, 'em-lékh''tám a árbu''át ríb''eihem não não isabú que porque o-lugar que ipneh harósh não irao não isabú em-suas-andar-cls:');
INSERT INTO verses VALUES (20714, 26, 10, 12, 'e-todo be-shārām e-os-de-seus-costas e-as-mãos-deles e-as-asperas-de-eles e-os-anéis cheios de-olhos ao-redor para-quatro-deles anéis-de-eles');
INSERT INTO verses VALUES (20715, 26, 10, 13, 'aos-anéis a-eles chamando o-galgal em-as-ouvidos');
INSERT INTO verses VALUES (20716, 26, 10, 14, 'e-quatro face para um face-de o-primeiro face-de o-kruv e-faces o-segundo face-de homem e-o terceiro face-de de-leão e-o quarto face-de nsher');
INSERT INTO verses VALUES (20717, 26, 10, 15, 'e-ele-levantaram-se os-kruvim ela a-haya que vi em-o-rio kavar');
INSERT INTO verses VALUES (20718, 26, 10, 16, 'e-em-a-andar os-querubins irão os-carros junto-deles וּבִשְׂאֵ֨ת os-querubins a כַּנְפֵיהֶ֗ם de-cima-de a-terra a-terra não יִסַּ֧בּוּ הָאוֹפַנִּ֛ים também eles מֵאֶצְלָֽם׃');
INSERT INTO verses VALUES (20719, 26, 10, 17, 'בְּעָמְדָ֣ם יַעֲמֹ֔דוּ וּבְרוֹמָ֖ם יֵר֣וֹמּוּ eles que espírito a-viva neles');
INSERT INTO verses VALUES (20720, 26, 10, 18, 'e-saiu glória-de yhwh de-cima-de do-pot a-casa e-se-posicionou sobre os-querubins');
INSERT INTO verses VALUES (20721, 26, 10, 19, 'e-tomaram os-querubins a as-asas-lhes e-elevaram-se de a-terra para-os-olhos-meus na-saída-deles e-as-águas para-suas-vizinhanças e-estacionou-se entrada-de porta-de casa-de yhwh o-primeiro e glória Elohim-de- Israel sobre-eles de-acima');
INSERT INTO verses VALUES (20722, 26, 10, 20, 'ela a vida que vi debaixo Elohim-de- Israel em-o-rio que e soube porque keruvim eles');
INSERT INTO verses VALUES (20723, 26, 10, 21, 'quatro quatro face para um e-quatro como asas para um e semelhança mãos-de homem debaixo como suas asas');
INSERT INTO verses VALUES (20724, 26, 10, 22, 'e-semelhança-de suas faces eles o-das-faces que vi sobre rio-de já suas visões e os homem a Éber de-seus-faces and andarão');
INSERT INTO chapters VALUES (813, 26, 11, 25);
INSERT INTO verses VALUES (20725, 26, 11, 1, 'e levantou-se a-mim espírito e trouxe me a portão-de casa-de yhwh a antiga que se encolhe ante e-eis na porta o-portão vinte e-cinco homem Eu vi no meio deles a jaazaniah filho-de azar e-a flatiyahu filho-de baniyahu sarei o-povo');
INSERT INTO verses VALUES (20726, 26, 11, 2, 'E-disse a-mim filho-de Estas estes os-homens os que planejam aven e os conselheiros conselho- mau na-cidade a esta');
INSERT INTO verses VALUES (20727, 26, 11, 3, 'os-que-dizem não próximo-a filhas-de nas-casas ela aquele-que-retira e nós aquele-da-mensagem:');
INSERT INTO verses VALUES (20728, 26, 11, 4, 'portanto e-foi-proclamado sobre-eles e-foi-proclamado filho-de homem');
INSERT INTO verses VALUES (20729, 26, 11, 5, 'e-caiu sobre-mim espírito yhwh E-disse a-mim disse assim yhwh yhwh assim אֲמַרְתֶּ֖ם casa Israel וּמַעֲל֥וֹת רֽוּחֲכֶ֖ם eu יְדַעְתִּֽיהָ׃');
INSERT INTO verses VALUES (20730, 26, 11, 6, 'הִרְבֵּיתֶ֥ם חַלְלֵיכֶ֖ם na-cidade esta וּמִלֵּאתֶ֥ם חוּצֹתֶ֖יהָ traspassado');
INSERT INTO verses VALUES (20731, 26, 11, 7, 'portanto assim disse Adonai yhwh חַלְלֵיכֶם֙ que שַׂמְתֶּ֣ם dentro dela eles a-carne e-ela a-sira e-vos saírei de dentro dela:');
INSERT INTO verses VALUES (20732, 26, 11, 8, 'espada temeis e-espada trarei sobre-vós oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20733, 26, 11, 9, 'e-saírei vos de dentro dela e-darei vos por-mão-de estrangeiros e-farei em-vós juízos:');
INSERT INTO verses VALUES (20734, 26, 11, 10, 'com-a-espada תִּפֹּ֔לוּ sobre fronteira-de Israel אֶשְׁפּ֣וֹט a-vós e-voces-sabereis yhwh eu yhwh');
INSERT INTO verses VALUES (20735, 26, 11, 11, 'ela-é não a-vós para-vocês לְסִ֔יר וְאַתֶּ֛ם תִּהְי֥וּ בְתוֹכָ֖הּ לְבָשָׂ֑ר a fronteira-de Israel אֶשְׁפֹּ֥ט a-vós');
INSERT INTO verses VALUES (20736, 26, 11, 12, 'וִֽידַעְתֶּם֙ porque yhwh yhwh que não não andastes não não עֲשִׂיתֶ֑ם e julgamentos as-nações que vossas voltas vocês-fizeram');
INSERT INTO verses VALUES (20737, 26, 11, 13, 'e-houve como profetizou-me e libertou-o filho-de minha filha morreu e caí sobre face-de e chorei voz-de grande e disse ahah tu yhwh completo tu fez a restante Israel');
INSERT INTO verses VALUES (20738, 26, 11, 14, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20739, 26, 11, 15, 'filho-de homem seu irmão teu-irmão homens-de glória-teu e-todo casa Israel todas a-eles disseram para-eles habitantes-de de-cima-de yhwh de-sobre yhwh para-nós a-terra foram-dadas a-terra para-herança');
INSERT INTO verses VALUES (20740, 26, 11, 16, 'por-isso disse assim disse Adonai que porque distanciaram-se entre-as-nações e-que difundiram-se nas-terras a-eles para-eles para-o-santuário pouco nas-áreas que entraram nome');
INSERT INTO verses VALUES (20741, 26, 11, 17, 'por-isso disse assim disse Adonai yhwh e-reuni-ei vos de os-povos e-ajunto vos de as-áreas que a-vós com-eles e-darei para-vocês a terra-de Israel');
INSERT INTO verses VALUES (20742, 26, 11, 18, 'e-vieram- para-lá e-removerei a todo seus-despojos e-a todo suas-abominações de-elas');
INSERT INTO verses VALUES (20743, 26, 11, 19, 'e-darei a-eles coração um e-Espírito-de nova darei em-meio-vosso e-removerei coração a-pedra מִבְּשָׂרָ֔ם e-darei a-eles coração carne');
INSERT INTO verses VALUES (20744, 26, 11, 20, 'a-fim-de בְּחֻקֹּתַ֣י eles-andarão e-a מִשְׁפָּטַ֥י יִשְׁמְר֖וּ eles a-eles וְהָיוּ־ a-mim para-povo a-eles estarei a-eles para-elohim');
INSERT INTO verses VALUES (20745, 26, 11, 21, 'e-a coração שִׁקּוּצֵיהֶ֛ם וְתוֹעֲבוֹתֵיהֶ֖ם seus corações andou דַּרְכָּם֙ dei נָתַ֔תִּי oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20746, 26, 11, 22, 'וַיִּשְׂא֤וּ os-querubins a as-pá-vei-hem e-as-águas para-suas-vizinhanças e glória Elohim-de- Israel sobre-eles de-acima');
INSERT INTO verses VALUES (20747, 26, 11, 23, 'e-subiu glória-de yhwh de-cima-de meio-de a-cidade e-yaa-amod sobre o-monte ao-oriente de-mik-dem para-a-cidade');
INSERT INTO verses VALUES (20748, 26, 11, 24, 'e-Espírito-de leva-tni e-tavi-eni cassidim-ah a o-exílio no-mar''e em-espirito Elohim e-subiu de-sobre-mim a-mar''eh que ra''i-ti:');
INSERT INTO verses VALUES (20749, 26, 11, 25, 'va-adabber a ha-golah a yhwh palavras-de yhwh que her''ani:');
INSERT INTO chapters VALUES (814, 26, 12, 28);
INSERT INTO verses VALUES (20750, 26, 12, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20751, 26, 12, 2, 'filho-de no-meio-de em-meio-de tu ha-meri tu habitou a-eles para-ver la-hem li-ra''ot e-não a-eles aznayim para-eles para-ouvir que ouvirem porque eles alegre-se eles');
INSERT INTO verses VALUES (20752, 26, 12, 3, 'e-tu filho-de homem a-ti para-ti instrumentos-de exilada e-exila de-dia לְעֵֽינֵיהֶ֑ם e-exilarás de-seu-lugar a lugar-de outro perante-seus-olhos que verão porque casa alegre-se eles');
INSERT INTO verses VALUES (20753, 26, 12, 4, 'וְהוֹצֵאתָ֨ כֵלֶ֜יךָ כִּכְלֵ֥י גוֹלָ֛ה de-dia לְעֵֽינֵיהֶ֑ם e-tu תֵּצֵ֤א בָעֶ֙רֶב֙ perante-seus-olhos כְּמוֹצָאֵ֖י גוֹלָֽה׃');
INSERT INTO verses VALUES (20754, 26, 12, 5, 'le-einehem חֲתָר־ para-ti campo e sairás em-ele');
INSERT INTO verses VALUES (20755, 26, 12, 6, 'perante os seus olhos sobre ombro levares em ombros mostrando faces-tuas cobrindo e-não verás a a-terra porque milagre eu-deti-te segundo-casa-de Israel');
INSERT INTO verses VALUES (20756, 26, 12, 7, 'e fiz assim como-que eu fui ordenado segundo a minha vontade eu tirei como utensílios destruição diariamente e à noite eu cavava para-mim o-nu em-a-d em-o-alá-ta saí-zi-ti sobre cátéf levantei-sa-ti per-ey-nay-hem');
INSERT INTO verses VALUES (20757, 26, 12, 8, 'e-houve palavra-de yhwh para-mim dizendo para-dizer');
INSERT INTO verses VALUES (20758, 26, 12, 9, 'filho-de homem não-é-que disseram a-você casa Israel casa o-méri tu tu fez');
INSERT INTO verses VALUES (20759, 26, 12, 10, 'disse a-eles assim disse Adonai yhwh o-nasi o masá o-este em-Jerusalém e-todo casa Israel que eles no vosso');
INSERT INTO verses VALUES (20760, 26, 12, 11, 'disse eu sua prova como-que eu fiz assim será feito a-eles na dispersão no retorno and andarão');
INSERT INTO verses VALUES (20761, 26, 12, 12, 'e o príncipe que no vosso meio a ombro yasua em ombros veyetzea bakkar nele lehotsia nele פנאו yekashe porque que ele verá la''ayin ele a a-terra');
INSERT INTO verses VALUES (20762, 26, 12, 13, 'uferashshi a rishshi sobre-ele e se prendeu na minha fortaleza ele a-ele-o terra terra dos-caldeus e aquela não verá e ali morra');
INSERT INTO verses VALUES (20763, 26, 12, 14, 'e-tudo que seus arredores e-todo seus braços cinto para-todo espírito e espada extenso depois-deles');
INSERT INTO verses VALUES (20764, 26, 12, 15, 'e-saberão porque yhwh yhwh בַּהֲפִיצִ֤י a-eles entre-as-nações וְזֵרִיתִ֥י eles בָּאֲרָצֽוֹת׃');
INSERT INTO verses VALUES (20765, 26, 12, 16, 'וְהוֹתַרְתִּ֤י deles homens-de de-número מֵחֶ֖רֶב מֵרָעָ֣ב וּמִדָּ֑בֶר para-que יְסַפְּר֜וּ a todo תּוֹעֲבֽוֹתֵיהֶ֗ם בַּגּוֹיִם֙ que vieram yhwh e-conheçam porque eu yhwh');
INSERT INTO verses VALUES (20766, 26, 12, 17, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20767, 26, 12, 18, 'filho-de homem o teu pão comerás comerás e das tuas águas com prazer e com peixe beberás');
INSERT INTO verses VALUES (20768, 26, 12, 19, 'e-dirás a a-terra a-terra assim disse Adonai yhwh para os que habitam Jerusalém a terra-de Israel seu pão com peixe comerão e dos seus dias em seu nome beberão para serem sua terra de-sua-plenitude desolação todo os-que-habitam nela');
INSERT INTO verses VALUES (20769, 26, 12, 20, 'e as cidades que estavam habitadas תֶּחֱרַ֔בְנָה E-a-terra שְׁמָמָ֣ה תִֽהְיֶ֑ה e-voces-sabereis porque yhwh yhwh');
INSERT INTO verses VALUES (20770, 26, 12, 21, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20771, 26, 12, 22, 'filho-de homem que a-vós o-este a-vós dizendo terra-de Israel dizendo יַֽאַרְכוּ֙ os-dias וְאָבַ֖ד todo חָזֽוֹן׃');
INSERT INTO verses VALUES (20772, 26, 12, 23, 'portanto disse a-eles assim disse Adonai yhwh הִשְׁבַּ֙תִּי֙ a הַמָּשָׁ֣ל ele e-não יִמְשְׁל֥וּ que ainda em-Israel porque se palavra a-eles קָֽרְבוּ֙ os-dias וּדְבַ֖ר todo חָזֽוֹן׃');
INSERT INTO verses VALUES (20773, 26, 12, 24, 'que não será ainda todo חֲז֥וֹן שָׁ֖וְא וּמִקְסַ֣ם no-meio-de em-meio-de casa Israel');
INSERT INTO verses VALUES (20774, 26, 12, 25, 'que eu yhwh yhwh את que אֲדַבֵּ֤ר palavra וְיֵ֣עָשֶׂ֔ה não não ainda porque que casa הַמֶּ֗רִי אֲדַבֵּ֤ר palavra וַעֲשִׂיתִ֔יו oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20775, 26, 12, 26, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20776, 26, 12, 27, 'filho-de eis eis casa-de Israel dizendo-os o vidente que ele o vidente para os dias ele e para os tempos distâncias ele será profetizado:');
INSERT INTO verses VALUES (20777, 26, 12, 28, 'portanto disse a-eles assim disse Adonai yhwh não e falará ainda todo as-minhas-palavras que e eu falar palavra e será feito oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (815, 26, 13, 23);
INSERT INTO verses VALUES (20778, 26, 13, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20779, 26, 13, 2, 'filho-de homem eis que profetizo a נביאים Israel הנביאים e-dirás לנביאים מללבם ouçam palavra-de yhwh');
INSERT INTO verses VALUES (20780, 26, 13, 3, 'assim disse Adonai yhwh הוי sobre הנביאים הנבלים que הלכים achar רוחם ולבלתי viram-;');
INSERT INTO verses VALUES (20781, 26, 13, 4, 'כּ-שׁוּעָלִים בּ-חֲרָב֑וֹת נְבִיאֶךָ Israel eram');
INSERT INTO verses VALUES (20782, 26, 13, 5, 'não עֲלִיתֶם בּ-פַּרְצ֔וֹת וַתִּגְדְּר֥וּ גָדֵר sobre casa Israel לַעֲמֹד בּ-מִלְחָמָ֖ה yhwh yhwh');
INSERT INTO verses VALUES (20783, 26, 13, 6, 'חָזּוּ שָׁוְא֙ וְקֶ֣סֶם כָּזָ֔ב הָאֹֽמְרִים֙ oráculo-de yhwh não não שְׁלָחָ֑ם וְיִֽחֲל֖וּ לְקַיֵּ֥ם palavra');
INSERT INTO verses VALUES (20784, 26, 13, 7, 'não מַֽחֲזֵה־ שָׁוְא֙ חֲזִיתֶ֔ם וּמִקְסַ֥ם כָּזָ֖ב אֲמַרְתֶּ֑ם וְאֹֽמְרִים֙ oráculo-de não e-eu não דִבַּֽרְתִּי׃');
INSERT INTO verses VALUES (20785, 26, 13, 8, 'portanto assim disse Adonai yhwh porque דַּבֶּרְכֶ֣ם שָׁ֔וְא וַחֲזִיתֶ֖ם כָּזָ֑ב portanto eis-me a-vós oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20786, 26, 13, 9, 'e-será mão-meu a הַנְּבִיאִ֞ים os que veem falso e os que juram enganador em segredo meu-povo não serão não casa-de Israel não não e-a terra-de que não virão e conhecereis porque eu Adonai yhwh');
INSERT INTO verses VALUES (20787, 26, 13, 10, 'porque e por causa de enganai a dizendo dizendo paz e-não-há שָׁל֑וֹם e-ele בונה חיץ e-eis-eles ele ele תפל׃');
INSERT INTO verses VALUES (20788, 26, 13, 11, 'disse a ט hei תפל ser יהוה גשם SHOTEF ואתנה אבני elgabish tipolnah e-Espírito-de searot tavake''');
INSERT INTO verses VALUES (20789, 26, 13, 12, 'e-eis cair haqir não-verdade ser-dito a-vós ayeh hatich que tachtem');
INSERT INTO verses VALUES (20790, 26, 13, 13, 'portanto assim disse Adonai yhwh uviqatahi espírito-de searot em-meu-ira e-chuva encharcar-se-á será ser-á e-pedras farfalharem-se em-fermentação para-todas-as-coisas:');
INSERT INTO verses VALUES (20791, 26, 13, 14, 'e-destruirei a a-parede que טַחְתֶּ֥ם תָּפֵ֛ל וְהִגַּעְתִּ֥יהוּ a a-terra וְנִגְלָ֣ה יְסֹד֑וֹ ונפלבה וּכְלִיתֶ֣ם yhwh e-voces-sabereis porque eu yhwh');
INSERT INTO verses VALUES (20792, 26, 13, 15, 'וְכִלֵּיתִ֤י a ira-meu na-parede ele ele תָּפֵ֑ל a-vós para-vocês não-há הַקִּ֔יר e-não-há ele a-ele');
INSERT INTO verses VALUES (20793, 26, 13, 16, 'profetas-de Israel הַֽנִבְּאִים֙ a Jerusalém e os videntes para-ela visão paz e-não-há paz oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20794, 26, 13, 17, 'e-tu filho-de homem ponham suas faces a filhas-de o-povo-tuo as que profetizam de seus corações e profetizarão sobre elas:');
INSERT INTO verses VALUES (20795, 26, 13, 18, 'e dirijais assim disse- Adonai yhwh Hoi para desembranchar como cobertas sobre todo que eu arrebatarei minhas mãos e farei as faixas sobre cabeça todo que se levantem para acusar almas as-nephoshoth tzodedenah para-ami u-nephoshoth lakenah tachaynah');
INSERT INTO verses VALUES (20796, 26, 13, 19, 'vatachelalenah a-mim a עַמּי b-shalei seorim pão lechem para-matar נְפָשׁוֹת֙ que não תְמוּתֶ֔נָה וּלְחַיּ֥וֹת נְפָשׁ֖וֹת que não תִֽחְיֶ֑ינָה בְּכַ֨זֶּבְכֶ֔ם לְעַמִּ֖י שֹׁמְעֵ֥י כָזָֽב׃');
INSERT INTO verses VALUES (20797, 26, 13, 20, 'portanto assim disse- Adonai yhwh eis-me a כִּסְּתוֹתֵיכֶ֙נָה֙ que אתָה מְצֹדְדֹות nome a as-nephoshoth eles de-cima-de a-eles de-sobre זְרוֹעֹותֵיכֶם וְשִׁלַּחְתִּי a הַנְּפָשׁוֹת que vós מְצֹדְדֹות a נְפָשׁוֹת לְפֹרְחֹות׃');
INSERT INTO verses VALUES (20798, 26, 13, 21, 'וְקָרַעְתִּי a vossas-multiplicidades vehitzaltiti a meu-povo meyedken e-não serão ainda beydken yhwh e-conheçais porque eu yhwh');
INSERT INTO verses VALUES (20799, 26, 13, 22, 'porque hakavot coração-de just-o mentira não não hikabtiv uvelchazek mãos-de perverso-o para-não shuv midarcho a-má lehachiyto');
INSERT INTO verses VALUES (20800, 26, 13, 23, 'portanto שָׁוְא não תֵּחָזֶינָה וְקֶסֶֽם não תִּקְסַֽמְנָה ainda vehitzaltiti a meu-povo meyedken yhwh porque eu yhwh');
INSERT INTO chapters VALUES (816, 26, 14, 23);
INSERT INTO verses VALUES (20801, 26, 14, 1, 'וַיָּבֹא a-mim homens מִזִּקְנֵ֖י Israel e-habitaram לְפָנַֽי׃');
INSERT INTO verses VALUES (20802, 26, 14, 2, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20803, 26, 14, 3, 'filho-de homem os-homens estes הֵעָל֤וּ gilulayhem sobre libbam umichshol iniquidade-deles deram nachach peneyhem a-eles iddaresh para-eles');
INSERT INTO verses VALUES (20804, 26, 14, 4, 'por-isso daber- otam va''amartata a-eles assim disse- Adonai yhwh homem homem de-casa-de Israel subia yaaleh a גִּלּוּלָ֜יו a coração-dele וּמִכְשׁ֤וֹל עֲוֺנוֹ֙ יָשִׂים֙ nachach rosto-dele yhwh a a-ele eu yhwh נַעֲנֵ֧יתִי ל֦וֹ em-muitos גִּלּוּלָֽיו׃');
INSERT INTO verses VALUES (20805, 26, 14, 5, 'para-fim-de תְּפֹ֥שׂ a casa-de Israel em-seus-corações que נָזֹ֙רוּ֙ de-sobre-mim בְּגִלּֽוּלֵיהֶ֖ם כלם׃');
INSERT INTO verses VALUES (20806, 26, 14, 6, 'portanto אֱמֹ֣ר ׀ a casa Israel assim disse Adonai yhwh שׁ֣וּבוּ וְהָשׁ֔יבוּ de-cima-de גִּלּֽוּלֵיכֶ֑ם e-de todo תּוֹעֲבֹתֵיכֶ֖ם הָשִׁ֥יבוּ פְנֵיכֶֽם׃');
INSERT INTO verses VALUES (20807, 26, 14, 7, 'que homem homem de-casa-de Israel וּמֵהַגֵּר֮ que יָג֣וּר בְּיִשְׂרָאֵל֒ וְיִנָּזֵ֣ר מֵֽאַחֲרַ֗י וְיַ֤עַל גִּלּוּלָיו֙ a coração-dele umichshol עֲוֺנ֔וֹ יָשִׂ֖ים nachach perante-ele וּבָ֤א a o profeta yhwh a-ele em-mim eu yhwh נַֽעֲנֶה־ a-ele em-mim');
INSERT INTO verses VALUES (20808, 26, 14, 8, 'וְנָתַתִּ֨י face-de בָּאִ֣ישׁ aquele וַהֲשִֽׂמֹתִ֙יהוּ֙ para-sinal וְלִמְשָׁלִ֔ים וְהִכְרַתִּ֖יו de-meio-de meu-povo e-voces-sabereis porque yhwh yhwh');
INSERT INTO verses VALUES (20809, 26, 14, 9, 'וְהַנָּבִ֤יא porque יְפֻתֶּה֙ וְדִבֶּ֣ר palavra yhwh yhwh אֲפִתַּֽיתִי a הַנָּבִ֣יא o-aquele וְנָתַ֤יתִי a mão-minha sobre-ele וְהִשְׁמַֽדְתּוֹ de-meio-de povo-meu Israel');
INSERT INTO verses VALUES (20810, 26, 14, 10, 'וְנָשְׂא֖וּ עֲוֺנָ֑ם כַּעֲוֹן הַדָּרֵ֔שׁ כַּעֲוֹן o-profeta será');
INSERT INTO verses VALUES (20811, 26, 14, 11, 'לְמַעַן não יִתָּעוּ ainda casa-de Israel de-áahiray e-não e-sejam ainda em-todo pešu''eyhem e-serão a-eles le-am va-ani ehyeh para-eles para-Elohim oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20812, 26, 14, 12, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20813, 26, 14, 13, 'filho-de terra que porque techeata- a-mim lim''e''al- em-alto ve-natitie mão-minha sobre-ela veshabartie para-ela mate- pão homem בָ֣הּ רָעָ֔ב nós homem homem וּבְהֵמָֽה׃');
INSERT INTO verses VALUES (20814, 26, 14, 14, 'e-sejam três-de os-homens estes dentro dela Noé וְאִיּ֑וֹב הֵ֤מָּה בְצִדְקָתָם֙ יְנַצְּל֣וּ נַפְשָׁ֔ם oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20815, 26, 14, 15, 'לֽוּ־ חַיָּה maldade אַעֲבִֿר na-terra וְשִׁׂכְלָ֑תָה e-será שְׁמָמָ֙ה מִבְּלִֽי de-diante-de de-diante-de הַחַיָּה׃');
INSERT INTO verses VALUES (20816, 26, 14, 16, 'três-de os-homens הָאֵלֶּה֮ בְּתוֹכָהּ֒ vive eu oráculo-de Adonai yhwh se filhos e-se בָּנוֹת יַצִּילוּ E-a-terra לְבַדָּם֙ יִנָּצֵ֔לוּ ser-á vazio∶');
INSERT INTO verses VALUES (20817, 26, 14, 17, 'ou espada אָבִ֖יא sobre a-terra aquela espada חֶ֚רֶב תַּעֲבֹ֣ר na-terra וְהִכְרַתִּ֥י homem homem וּבְהֵמָֽה׃');
INSERT INTO verses VALUES (20818, 26, 14, 18, 'וּשְׁלֹ֨שֶׁת os-homens הָאֵלֶּה֮ dentro dela vive eu oráculo-de Adonai não não libertarão filhos que eles eles le-baddam serão libertados:');
INSERT INTO verses VALUES (20819, 26, 14, 19, 'ou palavra eu lançarei a a-terra aquela e-verei-despejar minha ira sobre-ela em sangue para cortar homem homem e em animais:');
INSERT INTO verses VALUES (20820, 26, 14, 20, 'e Noé וְאִיּוֹב בְּתוֹכָהּ֒ vive eu oráculo-de Adonai yhwh se filho se filha-de יַצִּילוּ eles בְצִדְקָתָם יַצִּ֥ילוּ alma-deles');
INSERT INTO verses VALUES (20821, 26, 14, 21, 'que assim disse Adonai yhwh certamente porque אַרְבַּ֣עַת שְׁפָטַ֣י הָרָעִ֡ים espada וְרָעָ֞ב וְחַיָּ֤ה malignidade וָדֶ֔בֶר שִׁלַּ֖חְתִּי a Jerusalém para cortar homem homem וּבְהֵמָֽה׃');
INSERT INTO verses VALUES (20822, 26, 14, 22, 'e-eis נֽוֹתְרָה־ בָּ֜הּ פְּלֵטָ֗ה הַֽמּוּצָאִים֮ filhos וּבָנוֹת֒ הִנָּם֙ יווצאים a-vós וראות a דרכם e-a עלילותם וניחמתם sobre a-malícia-a que היבeti sobre Jerusalém a todo que היבeti sobre-ela');
INSERT INTO verses VALUES (20823, 26, 14, 23, 'וניחמו vos porque תראו a דרכם que não e-vocês-sabereis porque não sem motivo eu fiz a todo que esta nela oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (817, 26, 15, 8);
INSERT INTO verses VALUES (20824, 26, 15, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20825, 26, 15, 2, 'filho-de homem que será árvore- da videira ser árvore o cântico que foi em-a-árvore a floresta:');
INSERT INTO verses VALUES (20826, 26, 15, 3, 'será tomado nós árvore para-fazer para o trabalho se nós do-que-ele יָתֵ֔ד לִתְל֥וֹת sobre-ele todo כֶּֽלִי׃');
INSERT INTO verses VALUES (20827, 26, 15, 4, 'eis לָאֵ֖שׁ deu para-alimento את segundo קְצוֹתָ֜יו אָכְלָ֤ה a-foi וְתוֹכ֣וֹ נָחָ֔ר הֲיִצְלַ֖ח לִמְלָאכָֽה׃');
INSERT INTO verses VALUES (20828, 26, 15, 5, 'eis בִּֽהְיוֹת֣וֹ תָמִ֔ים não יֵֽעָשֶׂ֖ה para o trabalho certamente porque אֵ֤שׁ אֲכָלַ֙תְהוּ֙ וַיֵּחָ֔ר וְנַעֲשָׂ֥ה ainda לִמְלָאכָֽה׃');
INSERT INTO verses VALUES (20829, 26, 15, 6, 'portanto assim disse Adonai yhwh como-que עֵץ־ o-gefen -etz a-floresta que para-alimento -le-esh dei assim nata-ti a a-terra Jerusalém');
INSERT INTO verses VALUES (20830, 26, 15, 7, 'e-darei a face-de neles me-ha-esh saíram ve-ha-esh ta-akl-em vi-da-atem yhwh eu yhwh -beshumi a face-de neles');
INSERT INTO verses VALUES (20831, 26, 15, 8, 'e-darei a a-terra shamama porque מעלו em-alto oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (818, 26, 16, 63);
INSERT INTO verses VALUES (20832, 26, 16, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20833, 26, 16, 2, 'filho-de homem הודה a jerusalém a תועבותיה׃');
INSERT INTO verses VALUES (20834, 26, 16, 3, 'e dirijais assim disse Adonai yhwh a-Jerusalém מכורתייך ומולדתייך מֵאֶ֖רֶץ o-כְּנַעֲנִ֑י אביך o-amorreu ואימך כית׃');
INSERT INTO verses VALUES (20835, 26, 16, 4, 'ומולדתייך no-dia הלוודת te-a não  cortou   sua circuncisão   e nos águas  não  lavaste  não  e salgaste  não não  e secaste  não  e circuncidou-te ;');
INSERT INTO verses VALUES (20836, 26, 16, 5, 'não  cobriu  olho olho para-ti uma uma de-estes  com pano   sobre ti  e lançaste a face-de o-campo em-Guál alma-de-você em-dia nascida te:');
INSERT INTO verses VALUES (20837, 26, 16, 6, 'e passei sobre-ti e alonguei-me em-estresse em-teu-sangue e disse para-ti em-teu-sangue viva e disse para-ti em-teus-sangues viva:');
INSERT INTO verses VALUES (20838, 26, 16, 7, 'muitas como-plantinha o-campo eu-te-deixei e-te-multiplicaste e-te-desenvolveste e-viste comigo עֲדָיִ֑ים שָׁדַ֤יִם נָכֹ֙נוּ֙ וּשְׂעָרֵ֣ךְ צִמֵּ֔חַ וְאַ֖תְּ עֵרֹ֥ם וְעֶרְיָֽה׃');
INSERT INTO verses VALUES (20839, 26, 16, 8, 'וָאֶעֱבֹ֨ר עָלַ֜יִךְ e-te-vei e-eis tempo-te tempo nuvens e-espalhei as-asas sobre-ti e-cobri a-vergonha-te e-jurei para-ti e-vi em-aliança você oráculo-de Adonai yhwh serás para-mim');
INSERT INTO verses VALUES (20840, 26, 16, 9, 'eu lavarei em água e eu banharei seu sangue de ti e eu sequei com-o óleo');
INSERT INTO verses VALUES (20841, 26, 16, 10, 'e te vesti tecido e eu me cobri de-tachash e eu escondi no sexto e eu cozinhei meu mesi:');
INSERT INTO verses VALUES (20842, 26, 16, 11, 'e eu jurei para mim e dei bracelos sobre minhas mãos e eu me arrependi sobre ǵronêkhem:');
INSERT INTO verses VALUES (20843, 26, 16, 12, 'váeten nezem sobre áppekhem vá''ágilim sobre áznavayikh vá''atret esplendor-de b́roeshkhem:');
INSERT INTO verses VALUES (20844, 26, 16, 13, 'váta''adéyi ouro e-prata úmalbushkhem וָמֶ֙שִׁי֙ וְרִקְמָ֔ה סֹ֧לֶת וּדְבַ֛שׁ וָשֶׁ֖מֶן וַתִּ֙יפִי֙ em-muito muito וַֽתִּצְלְחִ֖י לִמְלוּכָֽה׃');
INSERT INTO verses VALUES (20845, 26, 16, 14, 'וַיֵּ֨צֵא para-ti nome בַּגּוֹיִ֖ם בּיָפְיֵךְ que כָּלִיל ele ele que coloquei sobre-ti oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20846, 26, 16, 15, 'וַתִּבְטְחִי בְיָפְיֵךְ וַתִּזְנִי sobre שָׁמֵךְ וַתִּשׁפְּכִי a תַּזְנוּתַיִךְ sobre todo עוֹבֵר לוֹ seja');
INSERT INTO verses VALUES (20847, 26, 16, 16, 'E tomaste dos teus vestidos e fizeste para-ti nas cavernas tela e te prostituiaste não não pelas estradas será será');
INSERT INTO verses VALUES (20848, 26, 16, 17, 'E tomaste utensílios-de a tua beleza do meu ouro e do meu dinheiro que dei para-ti e fez-te- para-ti macho macho e te deitaste-com- neles:');
INSERT INTO verses VALUES (20849, 26, 16, 18, 'e tomaste-te- a de-roupas a teu tecido e cobriste-te- e o teu óleo e perfumaste-te- diante-deles');
INSERT INTO verses VALUES (20850, 26, 16, 19, 'e o teu pão que para-ti para ti flor-farinha Óleo e mel comi-te e dei-lhes diante-deles para-aroma tranquilidade E-foi oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20851, 26, 16, 20, 'E tomaste a filhos-te e-a filhas-te que e geraste a-eles e sacrificaste a-eles para-comer o pouco');
INSERT INTO verses VALUES (20852, 26, 16, 21, 'e você matou a filhos-de e você fez na passagem a-eles para-eles');
INSERT INTO verses VALUES (20853, 26, 16, 22, 'e-a todo as abominações não não a dias-de seus dias de mocidade em sua existência naked e nudez se-tornando-se em seu sangue haví:');
INSERT INTO verses VALUES (20854, 26, 16, 23, 'e-houve atrás-de todo ra''atek ai para-ti para-ti oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20855, 26, 16, 24, 'vattibnī- para-ti gev e fez-te- lak rāmā em-todo rakhōv:');
INSERT INTO verses VALUES (20856, 26, 16, 25, 'a o-caminho-de cabeça caminho battinīt rāmātek e te aborreceste a a tua beleza e espalhaste a as tuas pernas para-todo passante e multiplicaste a');
INSERT INTO verses VALUES (20857, 26, 16, 26, 'e te prostituíste a filhos-de Egito as tuas vizinhas grande carne e multiplicaste a taznutêk lehaçaiseni');
INSERT INTO verses VALUES (20858, 26, 16, 27, 'e-eis natitî mão-minha sobre-ti vaegara chukkek vâetnek bênepes sonoatayikh filhas-de filisteus hanikkalmoth midarkhek ziná:');
INSERT INTO verses VALUES (20859, 26, 16, 28, 'vati zeni'' a filhos-de Assur mibültti sabá''áték'' vati zeni'' não não sabá''át''t:');
INSERT INTO verses VALUES (20860, 26, 16, 29, 'vattarbi a taznuték'' a terra kena''an não e-também bázot não sabá''át''t:');
INSERT INTO verses VALUES (20861, 26, 16, 30, 'que אֲמֻלָה֙ לִבָּתֵ֔ךְ oráculo-de Adonai yhwh בַּעֲשׂוֹתֵךְ֙ a todo אֵלֶּה obra-de אִשָּֽׁה־ זוֹנָ֖ה שַׁלָּֽטֶת׃');
INSERT INTO verses VALUES (20862, 26, 16, 31, 'בִּבְנוֹתַ֤יִךְ גַּבֵּךְ֙ na-cabeça todo caminho וְרָמָתֵ֥ךְ em-todo רְח֑וֹב e-não כַּזּוֹנָ֖ה לְקַלֵּ֥ס אֶתְנָֽן׃');
INSERT INTO verses VALUES (20863, 26, 16, 32, 'a-mulher הַמְּנָאָ֑פֶת debaixo marido-dela tome-a a זָרִֽים׃');
INSERT INTO verses VALUES (20864, 26, 16, 33, 'para-todo meretrizes deem נֵ֑דֶה וְאַ֨תְּ נָתַ֤תְּ a נדנאייך para-todo מאהבייך e-feriste-te aqueles-o לָב֥וֹא אליהיך ao-redor בתזנותיהיך׃');
INSERT INTO verses VALUES (20865, 26, 16, 34, 'e-foi בקיך הפך de as-mulheres não ואחריהיך não זוננה ובתיתך não וְאֶתְנַ֛ן não נִתַּן־ para-ti e-foi לְהֶֽפֶךְ׃');
INSERT INTO verses VALUES (20866, 26, 16, 35, 'por-isso זוֹנָ֔ה שִׁמְעִ֖י palavra-de yhwh');
INSERT INTO verses VALUES (20867, 26, 16, 36, 'assim disse Adonai yhwh porque הִשָּׁפֵ֤ךְ נְחֻשְׁתֵּךְ֙ וַתִּגָּלֶ֣ה עֶרְוָתֵ֔ךְ sobre מְאַהֲבָ֑יִךְ e-sobre todo גִּלּוּלֵ֣י תוֹעֲבוֹתַ֔יִךְ וְכִדְמֵ֣י בָנַ֔יִךְ a-eles נָתַ֖תְּ para-eles');
INSERT INTO verses VALUES (20868, 26, 16, 37, 'portanto eis-me מְקַבֵּ֤ץ a todo מְאַהֲבַ֙יִךְ֙ que עָרַ֣בְתְּ sobre-eles e-את todo que אָהַ֔בְתְּ eles todo que שָׂנֵ֑את וְקִבַּצְתִּי֩ elas עָלַ֜יִךְ מִסָּבִ֗יב וְגִלֵּיתִ֤י עֶרְוָתֵךְ֙ a-eles וְרָא֖וּ a todo עֶרְוָתֵֽךְ׃');
INSERT INTO verses VALUES (20869, 26, 16, 38, 'וּשְׁפַטְתִּיךְ֙ מִשְׁפְּטֵ֣י נֹאֲפ֔וֹת e derramaste sangue e dar-te-ei sangue ira e zelo');
INSERT INTO verses VALUES (20870, 26, 16, 39, 'e darei te nas mãos e destruam gabbeh v''nitatsu ramotayich ve''hifshitu otakh bagadayich ve''la''chu instrumentos-de tipheretek ve''hinichukh nu ve''ereya');
INSERT INTO verses VALUES (20871, 26, 16, 40, 'e levem sobre-ti congregação e lançarem te em pedra e em teu espadas');
INSERT INTO verses VALUES (20872, 26, 16, 41, 'e queimem em ti no-fogo e façam em-te as-sufadas aos-olhos-de as-nascidas muitas e-te-arraste do-sustento não eu-darei não dar-te-ei ainda');
INSERT INTO verses VALUES (20873, 26, 16, 42, 'e-reposarei ira-meu sobre-ti e-vai-se minha-quina -de-te e-terracetai e-não eu-me-ira ainda');
INSERT INTO verses VALUES (20874, 26, 16, 43, 'porque que não a dias-de minha-juventude-te e-torpestivaste- a-mim em-todo estes e-também eu ai dei na-cabeça eu-dotei oráculo-de Adonai yhwh e-não a sobre sobre todo minhas-abominações');
INSERT INTO verses VALUES (20875, 26, 16, 44, 'eis todo o-soberano sobre-te dizendo dizendo como-mãe seu-filho;');
INSERT INTO verses VALUES (20876, 26, 16, 45, 'filha-de tua-mãe você-é vendida espos-a e-seus-filhos e-sua-irmã tua-irmã você que foram-vendidas anšéhen uvenéhen immechen kitít va''abíchen emorí׃');
INSERT INTO verses VALUES (20877, 26, 16, 46, 'va''áhotéekha hagdólah šomeron ela uvénoteíha a sentada sobre o esquerdo e tua irmã a pequena de ti a sentada do teu direito sodom e suas filhas:');
INSERT INTO verses VALUES (20878, 26, 16, 47, 'e-não em seus caminhos você andou e-em-suas-loitas como-pequena que-é e-destruí de-las em-todo minhas-caminhos:');
INSERT INTO verses VALUES (20879, 26, 16, 48, 'vive eu oráculo-de Adonai yhwh se fez-a Sedom sua-irmã ela e-suas-filhas como-que fizeste אתָ וּבְנוֹתָֽיִךְ׃');
INSERT INTO verses VALUES (20880, 26, 16, 49, 'eis-que- ser foi iniquidade Sedom אֲחוֹתֵ֑ךְ גָּא֨וֹן שִׂבְעַת־ pão ser הַשְׁקֵ֗ט foi a-ela וְלִבְנוֹתֶ֔יהָ não עָנִ֥י וְאֶבְי֖וֹן não a segurou');
INSERT INTO verses VALUES (20881, 26, 16, 50, 'e se elevaram e fizeram to''evá diante-de-mim e fizera a-elas como-que ra''i-ti:');
INSERT INTO verses VALUES (20882, 26, 16, 51, 'e Samaria como metade seus pecados não errou e se multiplicaram a suas abominações מֵהֵ֔נָּה וַתְּצַדְּקִי֙ a em-todo תּוֹעֲבוֹתַ֖יִךְ que');
INSERT INTO verses VALUES (20883, 26, 16, 52, 'também אַ֣תְּ ׀ e-leva כְלִמָּתֵ֗ךְ que פִּלַּלְתְּ֙ לַֽאֲחוֹתֵ֔ךְ בְּחַטֹּאתַ֛יִךְ que הִתְעַ֥בְתְּ de-las תִּצְדַּ֣קְנָה -de-te e-também אַ֥תְּ בּ֙וֹשִׁי֙ וּשְׂאִ֣י כְלִמָּתֵ֔ךְ בְּצַדֶּקְתֵּ֖ךְ אַחְיוֹתֵֽךְ׃');
INSERT INTO verses VALUES (20884, 26, 16, 53, 'וְשַׁבְתִּי֙ a שְׁבִ֣יתְהֶ֔ן a Sodoma uvénoteíha e-a שֹׁמְר֖וֹן e-suas-filhas שְׁבִיתַ֖יִךְ בְּתוֹכָֽהְנָה׃');
INSERT INTO verses VALUES (20885, 26, 16, 54, 'a-fim-de תִּשְׂאִ֣י כְלִמָּתֵ֔ךְ וְנִכְלַ֕מְתְּ de-toda que עָשִׂ֑ית בְּנַחֲמֵ֖ךְ אֹתָֽן׃');
INSERT INTO verses VALUES (20886, 26, 16, 55, 'וַאֲחוֹתַ֗יִךְ סְדֹ֤ם וּבְנוֹתֶ֙יהָ֙ תָּשֹׁ֣בְןָ לְקַדְמָתָ֔ן וְשֹֽׁמְרוֹן֙ uvénoteíha תָּשֹׁ֖בְןָ לְקַדְמָתָ֑ן וְאַתְּ֙ וּבְנוֹתַ֔יִךְ תְּשֻׁבֶ֖ינָה לְקַדְמַתְכֶֽן׃');
INSERT INTO verses VALUES (20887, 26, 16, 56, 'não era Sedom sua-irmã לִשְׁמוּעָ֖ה בְּפִ֑יךְ em-dia גְּאוֹנָֽיִךְ׃');
INSERT INTO verses VALUES (20888, 26, 16, 57, 'antes-de תִּגָּלֶ֣ה  רָעָתֵךְ   כְּמ֗וֹ   עֵ֚ת   חֶרְפַּ֣ת   בְּנוֹת־  Arã e-todo  סְבִיבוֹתֶ֖יהָ  filhas-de filisteus  הַשָׁאט֥וֹת  te misaviv');
INSERT INTO verses VALUES (20889, 26, 16, 58, 'a  זִמָּתֵ֥ךְ  e-a תּוֹעֲבוֹתַ֖יִךְ tu yhwh oráculo-de yhwh');
INSERT INTO verses VALUES (20890, 26, 16, 59, 'que assim disse Adonai yhwh te como עָשִׂ֑ית que בָּזִ֥ית אָלָ֖ה לְהָפֵ֥ר em-brisa');
INSERT INTO verses VALUES (20891, 26, 16, 60, 'וְזָכַרְתִּ֨י eu a aliança-minha te em-dias-de seus dias de mocidade para-ti para-ti eternidade eternidade');
INSERT INTO verses VALUES (20892, 26, 16, 61, 'וְזָכַ֣רְתְּ a דְּרָכַיִךְ֮ וְנִכְלַמְתְּ֒ בְּקַחְתֵּ֗ךְ a אֲחוֹתַ֙יִךְ֙ הַגְּדֹל֣וֹת de-te a as-pequeninas para-ti וְנָתַתִּ֨י elas para-ti virgens e-não da-aliança-te');
INSERT INTO verses VALUES (20893, 26, 16, 62, 'e-as-elevarei eu a aliança-minha contigo e-saberás-te yhwh eu yhwh');
INSERT INTO verses VALUES (20894, 26, 16, 63, 'para-que e-lembrar-te-ei e-vergonha-te-te-dará e-não ele-será- a-te ainda פתחון de-diante-de de-face-de כלימאתך בקפרי- para-ti para-todo que fizeste oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (819, 26, 17, 24);
INSERT INTO verses VALUES (20895, 26, 17, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20896, 26, 17, 2, 'filho-de homem חד חידה ומשל mashal a casa Israel');
INSERT INTO verses VALUES (20897, 26, 17, 3, 'e dirijais assim disse- Adonai yhwh הנשר a-grande grande הכנפיים erêx ה Everton (correção: אֵבֶר) enchei הנוצה que a-ele הָרִקְמָ֑ה veio E-tomou הַלְּבָנ֔וֹן E-tomou a צַמֶּ֥רֶת הָאָֽרֶז׃');
INSERT INTO verses VALUES (20898, 26, 17, 4, 'a cabeça יְנִֽיקוֹתָ֖יו קָטָ֑ף וַיְבִיאֵ֙הוּ֙ a terra Canaã em-cidade-de רֹכְלִ֖ים שָׂמֽוֹ׃');
INSERT INTO verses VALUES (20899, 26, 17, 5, 'E-tomou מִזֶּ֣רַע a-terra e-o deu-lhe no-terreno- semente levou sobre águas muitos Tsafathá Sám-o:');
INSERT INTO verses VALUES (20900, 26, 17, 6, 'e-o plantou e-houve para-vaso Soráhat Shiflát Coma para-antes as-sális-yotáv a-ele e-s-arásháv ba-tachtáv יִֽהְי֑וּ וַתְּהִי para-gefen e-sa- na-bádim e-salhá- pa-rótes：');
INSERT INTO verses VALUES (20901, 26, 17, 7, 'e-houve neshér－ um grande grande como asas e-muita- נֹצָ֑ה e-eis הַגֶּ֨פֶן a-esta כָּֽפְנָ֧ה שָׁרֳשֶׁ֣יהָ sobre-ele וְדָֽלִיּוֹתָיו֙ שִׁלְחָה־ a-ele לְהַשְׁק֣וֹת ela מֵעֲרֻג֖וֹת מַטָּעָֽהּ׃');
INSERT INTO verses VALUES (20902, 26, 17, 8, 'a שָׂ֥דֶה bom a águas muitos ela שֹׁתֻלָה לַעֲשׂוֹת עָנָף וְלָשׂוּא פְּרִי para-ser לְגֵפֶן אַדְרֵת׃');
INSERT INTO verses VALUES (20903, 26, 17, 9, 'disse assim disse Adonai yhwh תִּצְלַח הֲלֹא֩ a שָׁרָשֶׁיהָ יְנַתֵּ֜ק e-a פִּרְיָ֣הּ יְקוֹסֵ֣ס וְיָבֵ֗שׁ todo טַרְפֵּ֤י צִמְחָהּ֙ תִּיבָ֔שׁ e-não בִזְרֹ֤עַ גְּדוֹלָה֙ וּבְעַם־ muito para-sa-las sinal-aquela de-suas-raízes');
INSERT INTO verses VALUES (20904, 26, 17, 10, 'e-eis plantada vai-ter-sucesso não-verdade como-um-ataque בָּ֜הּ espírito as-primeiras se-desidratará desidratado sobre cicatrizes cimehá tibás;');
INSERT INTO verses VALUES (20905, 26, 17, 11, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20906, 26, 17, 12, 'dize por-favor para-casa-de hammeri não yedautem o-quê estes disse eis-que- E-tomou rei-de Bavel e-trouxe E-tomou a-ele malkah e-a saréhá E-veio a-eles a-ele Bavelah;');
INSERT INTO verses VALUES (20907, 26, 17, 13, 'E-tomou mizra'' o-reino vayikrot com-ele aliança e-trouxe ele בהlah e-a a-terra a-terra tomou');
INSERT INTO verses VALUES (20908, 26, 17, 14, 'להיהot מלכה שפלah para-não התנשאה לשמור a בריתיו להעמודהּ׃');
INSERT INTO verses VALUES (20909, 26, 17, 15, 'וימרד־ nele לשלוח ס干事创业 Egito para-dar a-ele cavaleiros ו העם- muito Estas הֲיִמָּלֵט֙ הָעֹשֵׂ֣ה אֵלֶּה וְהֵפֵ֥ר berith וְנִמְלָֽט׃');
INSERT INTO verses VALUES (20910, 26, 17, 16, 'vive eu oráculo-de Adonai yhwh se não בִּמְקוֹם֙ ele הַמַּמְלִ֣יךְ a-ele que בָּזָה֙ a אָ֣לָת֔וֹ e-que הפר a בְּרִיתוֹ com-ele em-o-centro-de- Babel morra');
INSERT INTO verses VALUES (20911, 26, 17, 17, 'e-não בְּחַיל grande וּבְקָהָל muito fará אוֹתוֹ Pharaoh na-guerra בִּשׁפּוֹךְ סֹלְלָה וּבִבְנֹות דָּיֵק לְהַכְרִ֖ית נְפָשׁוֹת רבבות:');
INSERT INTO verses VALUES (20912, 26, 17, 18, 'ובזה ALA para-frustrar aliança e-eis dar sua-mão e-todo estes não não יִמָּלֵֽט׃');
INSERT INTO verses VALUES (20913, 26, 17, 19, 'portanto assim disse Adonai yhwh vive אני se não אלתי que com o báza ובריתי que הפר e-dar-lhe-e-o בראשו:');
INSERT INTO verses VALUES (20914, 26, 17, 20, 'uferashshi sobre-ele 里斯תּי e se prendeu na minha fortaleza והביאותיהו Babelá e julgar-me-ia com-ele nome sua subida que subindo- em-mim');
INSERT INTO verses VALUES (20915, 26, 17, 21, 'e-a todo em-todo seus desejos com-a-espada cairão e-os-restantes para-todo espírito seriam expostos que porque yhwh yhwh e eu falei:');
INSERT INTO verses VALUES (20916, 26, 17, 22, 'assim disse Adonai yhwh e tomaria eu de um cedro o cedro הָרָמָ֖ה וְנָתָ֑תִּי מֵרֹ֤אשׁ יֹֽנְקוֹתָיו֙ רַ֣ךְ אֶקְטֹ֔ף וְשָׁתַ֣לְתִּי eu sobre monte-de גָּבֹ֖הַ וְתָלֽוּל׃');
INSERT INTO verses VALUES (20917, 26, 17, 23, 'בְּהַ֨ר מרומ Israel אששתלנוו ונasha עָנָף ואsha פריה e-foi לארז אדיר ושכנו תחתיו todo pássaro todo asa em-a-sombra דּוֹלְיֹתָיו תֵּשְׁכַּח׃');
INSERT INTO verses VALUES (20918, 26, 17, 24, 'וְיָדֻעוּ todo madeiras-de que porque yhwh yhwh הֵשַׁפְלִיתִי árvore גָּבְהָ הֵגַבְתִּי árvore שָׁפַל הֵובַשְׂתִּי árvore לָח וְהֵפַרְתִּי árvore צַח eu yhwh falei וְעָשַׂ֣יתִי׃');
INSERT INTO chapters VALUES (820, 26, 18, 32);
INSERT INTO verses VALUES (20919, 26, 18, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (20920, 26, 18, 2, 'que לָכֶם vós מֹשְׂלים֙ a הַמָּשָׁ֣ל esta dizendo terra-de Israel dizendo avós יֹאכְלוּ בָּשֵׂר e-dentes הַבָּנִים תִּקָּחֶֽינָה׃');
INSERT INTO verses VALUES (20921, 26, 18, 3, 'vive אֲנִי oráculo-de Adonai yhwh a-vós será para-vocês ainda מַשְׂול o parábola este em-Israel');
INSERT INTO verses VALUES (20922, 26, 18, 4, 'eis todo as-nephoshoth a-mim elas carnal o pai e carnal o filho para-mim- aqui-estes a-alma a culpa ela morra');
INSERT INTO verses VALUES (20923, 26, 18, 5, 'e-homem porque será justo e fez juízo e justiça');
INSERT INTO verses VALUES (20924, 26, 18, 6, 'a não não comeria não não levou a גִּלּוּלֵ֖י casa Israel não אֵ֤שֶׁת seu-proximo não não e-a mulher e-tudo não יִקְרָֽב׃');
INSERT INTO verses VALUES (20925, 26, 18, 7, 'e-homem não יוֹנֶ֔ה חֲבֹלָת֥וֹ חוֹב֙ יָשִׁ֔יב גְּזֵלָ֖ה não יִגְזֹ֑ל לַחְמוֹ֙ para a fome irá dar e o ermo cobrirá em-pano;');
INSERT INTO verses VALUES (20926, 26, 18, 8, 'no-vento não irá dar não não irá tomar do-ventre sua-mão sua-mão juízo verdade entre entre homem para-homem');
INSERT INTO verses VALUES (20927, 26, 18, 9, 'בְּחֻקּוֹתַ֧י יְהַלֵּ֛ךְ וּמִשְׁפָּטַ֥י שָׁמַ֖ר para fazer verdade justo ele חָיֹ֣ה יִֽחְיֶ֔ה oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20928, 26, 18, 10, 'וְהוֹלִ֥יד filho-de פָּרִ֖יץ שֹׁפֵ֣ךְ sangue וְעָ֣שָׂה irmão de um destas');
INSERT INTO verses VALUES (20929, 26, 18, 11, 'e ele a não estes que fez porque comer a os-montes comeu e-a mulher-de E-a-terra impuriu-se');
INSERT INTO verses VALUES (20930, 26, 18, 12, 'pobre e pobre mamadeira lactares roubou corromper não יָשַׁב e-a הַגְּלֻלִֽים levou עֵינָיו תּוֹעֵבָה fez');
INSERT INTO verses VALUES (20931, 26, 18, 13, '[בַּנֶּ֧שֶׁךְ] dar [וְתַרְבִּ֥ית] tomou [וָחָ֑י] não [יִֽחְיֶ֗ה] a todo [הָאֵ֙לֶּה֙] estes morrendo morte-de [דָּמָ֖יו] [בּ֥וֹ] será');
INSERT INTO verses VALUES (20932, 26, 18, 14, 'e-eis gerou filho E-viu a seu-pai chéto'' pai-dele que fez vayíre''eh e-não faz-o sacerdote');
INSERT INTO verses VALUES (20933, 26, 18, 15, 'sobre não não áchal não não násā'' a gilúlei casa Israel não mulher-de E-a-terra não temé:');
INSERT INTO verses VALUES (20934, 26, 18, 16, 'e-homem não hónah chábal não chabal úgazelá não gazál lachmô lerá''ev deu ve''urôm kissâ- הבָּגֶד׃');
INSERT INTO verses VALUES (20935, 26, 18, 17, 'me''ânî hêshı̂yb sua-mão neshekh ve''tarbit não tomou e-em-meus-julgamentos fez b''chukkotay andou ele não morra em-perversidade seu-pai חַיָּה viverá:');
INSERT INTO verses VALUES (20936, 26, 18, 18, 'seu-pai porque [עֹ֗שֶׁק] [גָּזַל֙] [גֵּ֣זֶל] [אָ֔ח] [וַאֲשֶׁ֥ר] e-que não no-meio-de fez em-meio-de [בַּעֲוֺנֽוֹ] morreu');
INSERT INTO verses VALUES (20937, 26, 18, 19, 'e-vós-direis [מַדֻּ֛עַ] não [הַבֵּ֖ן] [בַּעֲוֺ֣ן] [הָאָ֑ב] [וְהַבֵּ֞ן] [מִשְׁפָּ֧ט] [וּצְדָקָ֣ה] [עָשָׂ֗ה] fez a todo [וַיַּעֲשֶׂ֥ה] eles [חָיֹ֥ה] eles');
INSERT INTO verses VALUES (20938, 26, 18, 20, 'a-alma הַחֹטֵ֖את ela תָמ֑וּת filho não יִשָּׂ֣א ׀ ba''avon הָאָ֗ב וְאָב֙ não yasua ba''avon הַבֵּ֔ן צִדְקַ֤ת הַצַּדִּיק֙ sobre-ele תִּֽהְיֶ֔ה וְרִשְׁעַ֥ת sobre-ele תִּֽהְיֶֽה׃');
INSERT INTO verses VALUES (20939, 26, 18, 21, 'וְהָרָשָׁ֗ע que retornara de-todo que fez וְשָׁמַר֙ a todo חֻקּוֹתַ֔י וְעָשָׂ֥ה juízo e justiça viva não não não');
INSERT INTO verses VALUES (20940, 26, 18, 22, 'todo seus pecados que não não a-ele a-ele em sua justiça que fez viverá:');
INSERT INTO verses VALUES (20941, 26, 18, 23, 'o que deseja desejo morrendo perverso-o oráculo-de Adonai yhwh acaso-nao em seu arrependimento de suas sendas e viverá:');
INSERT INTO verses VALUES (20942, 26, 18, 24, 'e-em-retorno justo de-sua-justiça e-fez enganho como-todo as-abominações que fez o-perverso faz-o וָחָ֑י todo que não não ser-lembrada em-suas-alturas que altura e-em-sua-impiedade que pecou בָּ֥ם não');
INSERT INTO verses VALUES (20943, 26, 18, 25, 'e-vós-direis não será estabelecido o-caminho-de Adonai ouvi por-favor casa Israel não não será estabelecido não não não nos será estabelecido:');
INSERT INTO verses VALUES (20944, 26, 18, 26, 'quando voltar- justo por sua justiça e fizer enganho e-morre sobre-eles por seu enganho que fez não');
INSERT INTO verses VALUES (20945, 26, 18, 27, '[וּבְשׁ֣וּב] [רָשָׁ֗ע] [מֵֽרִשְׁעָתוֹ֙] que fez E-fez juízo [וּצְדָקָ֑ה] ele a [יְחַיֶּֽה]');
INSERT INTO verses VALUES (20946, 26, 18, 28, '[וַיִּרְאֶ֣ה] de-todo [**וַיָּ֔שָׁב] que fez [עָשָׂ֑ה] [חָי֥וֹ] não não');
INSERT INTO verses VALUES (20947, 26, 18, 29, 'וְאָמְרוּ casa Israel não יתַכֵּן o-caminho-de Adonai הַדְרָכַי não יתַכְנוּ casa Israel não vos caminhos não יתַכֵּן׃');
INSERT INTO verses VALUES (20948, 26, 18, 30, '[לָכֵן֩] homem [כִּדְרָכָ֜יו] [אֶשְׁפֹּ֤ט] vos casa Israel oráculo-de Adonai yhwh [שׁ֤וּבוּ] [וְהָשִׁ֙יבוּ֙] de-todo [וְלֹֽא־יִהְיֶ֥ה] a-vós será a-vós');
INSERT INTO verses VALUES (20949, 26, 18, 31, 'Jetei de-vós a todo os-seus-pecados que vossos-pecados a-vós e-fazei a-vós e-Espírito-de novo e-vento חֲדָשָה e-porque morrais casa Israel');
INSERT INTO verses VALUES (20950, 26, 18, 32, 'que não E-desejo em-morte-de o-morto oráculo-de Adonai yhwh e-retornai e-vivais');
INSERT INTO chapters VALUES (821, 26, 19, 14);
INSERT INTO verses VALUES (20951, 26, 19, 1, 'e-tu eleva CÂMARA a príncipes-de Israel');
INSERT INTO verses VALUES (20952, 26, 19, 2, 'e dirás que tua mãe Leviá entre arayot rabatzá no-meio-de kéfirim ribtá suas moradas:');
INSERT INTO verses VALUES (20953, 26, 19, 3, 'e-subiu um de suas moradas kéfir ser e aprendeu לִטְרָף- homem homem אָכָֽל׃');
INSERT INTO verses VALUES (20954, 26, 19, 4, 'וַיִּשְׁמְע֥וּ a-ele nações בְּשַׁחְתָּ֣ם נִתְפָּ֑שׂ וַיְבִאֻ֥הוּ בַֽחַחִ֖ים a terra Egito');
INSERT INTO verses VALUES (20955, 26, 19, 5, 'E-viu que נֽוֹחֲלָ֔ה perdida תִּקְוָתָ֑הּ e-tomou um מִגֻּרֶ֖יהָ כּ-פִ֥יר שׂ-אָמַֽתְהוּ׃');
INSERT INTO verses VALUES (20956, 26, 19, 6, 'e-andou em-meio-de [כְּפִ֣יר] ser foi [לִטְרָף־טֶ֖רֶף] homem [אָכָֽל] homem');
INSERT INTO verses VALUES (20957, 26, 19, 7, 'e-soube אַלְמְנוֹתָ֔יו וְעָרֵיהֶ֖ם הֶחֱרִ֑יב וַתּ-תֵ֤שַׁם terra e plenitude de voz de sua garganta;');
INSERT INTO verses VALUES (20958, 26, 19, 8, 'va-yittenu sobre-ele nações ao-redor das regiões e se separaram sobre-ele seus caminhos em sua vergonha foram presos;');
INSERT INTO verses VALUES (20959, 26, 19, 9, 'e os colocaram em um cesto בַּֽחַחִ֔ים וַיְבִאֻ֖הוּ a rei Babilônia יְבִאֻ֙הוּ֙ בַּמְּצֹד֔וֹת para-que não יִשָּׁמַ֥ע קוֹל֛וֹ ainda a montes-de Israel');
INSERT INTO verses VALUES (20960, 26, 19, 10, 'אִמְּךָ֥ כַגֶּ֛פֶן בְּדָמְךָ֖ sobre águas שְׁתוּלָ֑ה 포רי야 era היהתה de-ma''im muitos');
INSERT INTO verses VALUES (20961, 26, 19, 11, 'e-foram [מַטּ֣וֹת] tribos-de [אֶל־שִׁבְטֵי֙] a [וַתִּגְבַּ֥הּ] [קֽוֹמָת֖וֹ] [עַל־בֵּ֣ין] [עֲבֹתִ֑ים] sobre entre [בְּרֹ֖ב] E-viu');
INSERT INTO verses VALUES (20962, 26, 19, 12, 'וַתֻּתַּ֤שׁ בְּחֵמָה֙ a-terra הֻשְׁלָ֔כָה e-Espírito-de הַקָּדִ֖ים הוֹבִ֣ישׁ פִּרְיָ֑הּ הִתְפָּרְק֧וּ וְיָבֵ֛שׁוּ bastão-de uzzáh fogo acalatuhu');
INSERT INTO verses VALUES (20963, 26, 19, 13, 'e-agora sh''tulá b''midbar em-terra-de tsiyá vétsamá');
INSERT INTO verses VALUES (20964, 26, 19, 14, 'vatese אֵ֜שׁ de-matate badéhah p''riyah ákalah e-não foi בָ֛הּ mate- força tribo-de לִמְשׁ֑וֹל קִ֥ינָה ela e-foi לְקִינָֽה׃');
INSERT INTO chapters VALUES (822, 26, 20, 44);
INSERT INTO verses VALUES (20965, 26, 20, 1, 'e-houve em-a-ano הַשְּׁבִיעִ֗ית בַּֽחֲמִשִׁי֙ בֶּעָשׂ֣וֹר do-mês vieram homens de-anciãos-de Israel inquirir a yhwh e-habitaram לְפָנַֽי׃');
INSERT INTO verses VALUES (20966, 26, 20, 2, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (20967, 26, 20, 3, 'filho-de homem palavra a זִקְנֵ֤י Israel e-dirás disse assim disse Adonai yhwh הֲלִדְרֹ֥שׁ a-mim vós בָּאִ֑ים a-vós אנני se אידארעש a-vós oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (20968, 26, 20, 4, '[הֲתִשְׁפֹּ֣ט] eles [הֲתִשְׁפּ֖וֹט] filho-de homem a [הוֹדִיעֵֽם]');
INSERT INTO verses VALUES (20969, 26, 20, 5, 'e-dirás a-eles assim disse Adonai yhwh em-dia-de בחורי ביישרא엘 VAShasha mão-meu לזרע casa Jacó a-eles a-eles em-terra-de Egito e levantei-me a-eles dizendo dizendo yhwh yhwh Elohim-vosso');
INSERT INTO verses VALUES (20970, 26, 20, 6, 'no-dia aquele eu levantei-os mão-minha a-eles para tirá-los da-terra Egito a terra a-eles e eu carregaria a-eles que-mana leite e mel glória ela para-todo das nações:');
INSERT INTO verses VALUES (20971, 26, 20, 7, 'e-disse a-eles homem as detritos os-seus-olhos lançai-as e com os pilhérios Egito a vós sereis contaminados yhwh yhwh Elohim-vosso');
INSERT INTO verses VALUES (20972, 26, 20, 8, 'e disseram- em mim- e-não e-ABu para-ouvir a-mim homem a não seus olhos- não lançaram- não bolinhas de Egito não abandonaram- e-disse para derramar- minha ira- sobre-eles no-meio-de terra neles no-meio-de terra Egito');
INSERT INTO verses VALUES (20973, 26, 20, 9, 'e fiz- para-que meu nome- para-não הֵחֵ֛ל para-olhos-de as-nações que eles בְתוֹכָ֑ם que נוֹדַ֤עְתִּי a-eles perante-seus-olhos לְהוֹצִיאָ֖ם da-terra-de Egito');
INSERT INTO verses VALUES (20974, 26, 20, 10, '[וָאֽוֹצִיאֵ֖ם] da-terra Egito [וָאֲבִאֵ֖ם] a');
INSERT INTO verses VALUES (20975, 26, 20, 11, '[וָאֶתֵּ֤ן] a-eles a [וְאֶת־מִשְׁפָּטַ֖י] e-[OBJ] [אוֹתָ֑ם] [אֲשֶׁ֨ר] eles que o-homem e-viva o-homem');
INSERT INTO verses VALUES (20976, 26, 20, 12, 'e-também a dei a-eles a-eles para-ser- לְא֔וֹת entre-mim-e-vocês para-conhecer que porque yhwh yhwh מְקַדָּֽשָֽׁם׃');
INSERT INTO verses VALUES (20977, 26, 20, 13, 'וַיַּמְרוּ־ בִ֨י casa-de Israel no-deserto בְּחֻקּוֹתַ֨י não הָלָ֜כוּ e-a eles o-homem e-viva fará eles o-homem muito neles e-a שַׁבְּתֹתַ֖י חִלְּל֣וּ muito e-disse לִשְׁפֹּ֨ךְ חֲמָתִ֧י sobre-eles em-o-midbar para os destruí-los');
INSERT INTO verses VALUES (20978, 26, 20, 14, 'e fiz para-que o meu nome para-não eu comecei a aos-olhos-de as-nações que eu tirei per-ey-nay-hem');
INSERT INTO verses VALUES (20979, 26, 20, 15, 'e-também eu eu levantei a-eles a-eles para-não para destruí-los leva a-eles a a-terra que eu dei que-mana leite e mel o seu prêmio ela para-todo as nações:');
INSERT INTO verses VALUES (20980, 26, 20, 16, 'porque pelos meus juízos se rebelaram e-a minhas leis não caminharam em-elas que minhas cerimônias desafiaram porque atrás-de seus ídolos seus corações andou');
INSERT INTO verses VALUES (20981, 26, 20, 17, 'e se encolheram minha vista sobre-eles מִשַׁחֲתָ֑ם e-não trabalhei eles כָּלָ֖ה no-deserto');
INSERT INTO verses VALUES (20982, 26, 20, 18, '[וָאֹמַ֤ר] a [בַּמִּדְבָּ֔ר] no-deserto [אֲבֽוֹתֵיכֶם֙] [אַל־תֵּלֵ֔כוּ] a [אַל־תִּשְׁמֹ֑רוּ] e-[OBJ] [אַל־תִּטַּמָּֽאוּ] a a');
INSERT INTO verses VALUES (20983, 26, 20, 19, 'eu yhwh vosso-Elohim בְּחֻקּוֹתַ֖י לֵ֑כוּ e-a מִשְׁפָּטַ֥י שִׁמְר֖וּ וַעֲשׂ֥וּ a-eles');
INSERT INTO verses VALUES (20984, 26, 20, 20, 'e-[OBJ] [קַדֵּ֑שׁוּ] e-sejam e-serão [בֵּינִ֣י] [וּבֵֽינֵיכֶ֔ם] para-conhecer que porque yhwh yhwh');
INSERT INTO verses VALUES (20985, 26, 20, 21, 'וַיַּמְרוּ־ Bi הַבָּנִ֗ים בְּחֻקּוֹתַ֣י não הָ֠לָכוּ e-a מִשְׁפָּטַ֨י não שָׁמְרוּ para fazer o-homem e-viva fará os o-homem וַחַי neles a שַׁבְתוֹתַי חִילּוּ e-disse לִשְׁפֹּךְ חֲמָתִי em-eles para-consumir אַפִּי com-eles no-deserto');
INSERT INTO verses VALUES (20986, 26, 20, 22, 'וָהֶשְׁבֹּתִי֙ a minha-mão וָאֲעַשׂ para-que para-não para-não הֵחֵל aos-olhos-de as-nações que הוציתי eles per-ey-nay-hem');
INSERT INTO verses VALUES (20987, 26, 20, 23, 'também eu [אֶת־יָדִ֛י] a-eles [בַּמִּדְבָּ֑ר] a-eles eles [בַּגּוֹיִ֔ם] a-elas entre-as-nações [בָּאֲרָצֽוֹת]');
INSERT INTO verses VALUES (20988, 26, 20, 24, 'porque [מִשְׁפָּטַ֤י] não fizeram [מָאָ֔סוּ] [וְאֶת־שַׁבְּתוֹתַ֖י] e-[OBJ] [וְאַחֲרֵי֙] [גִּלּוּלֵ֣י] [אֲבוֹתָ֔ם] [הָי֖וּ] pais-deles');
INSERT INTO verses VALUES (20989, 26, 20, 25, 'e-também dei a-eles a-eles não não bons não não viverão neles');
INSERT INTO verses VALUES (20990, 26, 20, 26, 'e sujar a-eles com suas ofertas quando passarem todo pêter e ter piedade para-que e os acusarão para-que que saberiam que yhwh yhwh');
INSERT INTO verses VALUES (20991, 26, 20, 27, 'portanto palavra a casa Israel filho-de homem e-dirás disse assim disse Adonai esta ainda esta e se acusaram a-mim vossos pais em sua elevação em-mi acima');
INSERT INTO verses VALUES (20992, 26, 20, 28, 'e levei-os a a-terra que eu-elevei a minha-mão a-eles a-ela para-eles e viram todo Gibeá Rama e-todo madeira-de Abótes e-sacrificaram nome a seus sacrifícios e deram- nome כַּעַס sua oferta e colocaram nome cheiro seus aromas וַיַּסּ֣יכוּ nome a נִסְכֵּיהֶֽם׃');
INSERT INTO verses VALUES (20993, 26, 20, 29, 'e-disse a-eles que a-altar que vós os-vindos nome E-chamou nome-dela até o-dia o-dia a-esta');
INSERT INTO verses VALUES (20994, 26, 20, 30, 'portanto [אֱמֹ֣ר] a casa Israel assim disse Adonai yhwh [הַבְּדֶ֥רֶךְ] [אֲבֽוֹתֵיכֶ֖ם] vós [נִטְמְאִ֑ים] e-após-de [שִׁקּוּצֵיהֶ֖ם] vós [זֹנִֽים]');
INSERT INTO verses VALUES (20995, 26, 20, 31, 'וּבִשְׂאֵ֣ת מַתְּנֹֽתֵיכֶ֡ם בְּֽהַעֲבִיר֩ vos filhos em fogo vós estádes contaminados para-todo vosso engodo até o-dia a-vós se inquirir para-vocês casa Israel vive eu oráculo-de a-vós yhwh se iddaresh a-vós');
INSERT INTO verses VALUES (20996, 26, 20, 32, 'e a oferta elevada sobre o vosso espírito não não תִֽהְיֶ֑ה que vós dizeis se tornemos como-gentios como-famílias as-terras para-serviço árvore e-rocha;');
INSERT INTO verses VALUES (20997, 26, 20, 33, 'vive eu-sou oráculo-de Adonai yhwh se não por-mão forte e-por-braco pendente e na chama escorrida eu exaltarei sobre-vós');
INSERT INTO verses VALUES (20998, 26, 20, 34, 'e-saírei vos de os-povos e reunirei vos de as-áreas que vos ferverei neles na mão forte e-no-braco estendida e na chama escorrida:');
INSERT INTO verses VALUES (20999, 26, 20, 35, 'e trarei vos a do deserto o-povo e julgar-te-ei com-vós nome face a face');
INSERT INTO verses VALUES (21000, 26, 20, 36, 'como-que julgar-te-ei a vos pais terra terra Egito assim serás julgado convosco oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21001, 26, 20, 37, 'e eu trarei vos debaixo a vara e levar-te-ei vos pela herança do pacto:');
INSERT INTO verses VALUES (21002, 26, 20, 38, 'e libertarei mi-kem הַמֹּרְדִ֤ים e-os-perversos em-mim da terra meguřeihem eu-outra-ei a-eles e-a solo-de não não virá e-voces-sabereis yhwh eu yhwh');
INSERT INTO verses VALUES (21003, 26, 20, 39, 'e-vós casa-de Israel assim disse Adonai yhwh homem גִּלּוּלָיו֙ ide servi e-depois se não-vós שומעים a-mim não nome santidade-meu não desacredites- ainda בְּמַתְּנֽוֹתֵיכֶ֖ם וּבְגִלּוּלֵיכֶֽם׃');
INSERT INTO verses VALUES (21004, 26, 20, 40, 'que בְּהַר- קָדְשִׁ֞י בְּהַ֣ר ׀ altura Israel oráculo-de Adonai yhwh nome יַעַבְדֻ֜נִי todo casa Israel até a totalidade em-a-terra nome אֶרְצֵ֔ם e-ali אֶדְר֣וֹשׁ a תְּרוּמֹֽתֵיכֶ֗ם e-a primícias מַשְׂאוֹתֵיכֶ֖ם em-todo קָדְשֵׁיכֶֽם׃');
INSERT INTO verses VALUES (21005, 26, 20, 41, 'בְּרֵ֣יחַ נִיחֹחַ אֶרְצֶ֣ה vós בְּהוֹצִיאִ֤י vos de os-povos וְקִבַּצְתִּ֣י vos de as-áreas que נְפֹצֹתֶ֖ם neles וְנִקְדַּשְׁתִּ֥י em-vós para-olhos-de os-gentios');
INSERT INTO verses VALUES (21006, 26, 20, 42, 'וִֽידַעְתֶּם֙ porque yhwh yhwh בַּהֲבִיאִ֥י vos a solo-de Israel a a-terra que eu-elevei a minha-mão a-dar a-ela לַאֲבֽוֹתֵיכֶֽם׃');
INSERT INTO verses VALUES (21007, 26, 20, 43, '[וּזְכַרְתֶּם־שָׁ֗ם] nome e-[OBJ] [כָּל־עֲלִיל֣וֹתֵיכֶ֔ם] e-[OBJ] todo [בָּ֑ם] que [בִּפְנֵיכֶ֔ם] neles [אֲשֶׁ֥ר] [עֲשִׂיתֶֽם] em-todo que');
INSERT INTO verses VALUES (21008, 26, 20, 44, 'וִֽידַעְתֶּם֙ porque yhwh yhwh בַעֲשׂוֹתִי com-vocês para-que não não כְדַרְכֵיכֶם הָרָעִים וְכַעֲלִילֹתֵיכֶם as-nashachot casa Israel oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (823, 26, 21, 37);
INSERT INTO verses VALUES (21009, 26, 21, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21010, 26, 21, 2, 'filho-de homem [פָּנֶ֙יךָ֙] o-caminho-de caminho [וְהַטֵּ֖ף] [אֶל־דָּר֑וֹם] a [אֶל־יַ֥עַר] [הַשָּׂדֶ֖ה] a');
INSERT INTO verses VALUES (21011, 26, 21, 3, 'e-dirás ליער o-sul ouviu palavra-de yhwh assim disse Adonai yhwh eis-me מצית- בקחהֿ אֵ֡שׁ e comerá em ti todo árvore-de na e-todo árvore יָבֵ֤שׁ não morrerás pela fogo e seriam nela todo face do deserto tsāphōnā');
INSERT INTO verses VALUES (21012, 26, 21, 4, '[וְרָאוּ֙] todo que porque yhwh yhwh não não');
INSERT INTO verses VALUES (21013, 26, 21, 5, 'e-eu-disse [אֲהָ֖הּ] Adonai yhwh eles [אֹמְרִ֣ים] a-mim [הֲלֹ֛א] [מְמַשֵּׁ֥ל] [מְשָׁלִ֖ים] ele');
INSERT INTO verses VALUES (21014, 26, 21, 6, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21015, 26, 21, 7, 'filho-de homem ponham suas faces a Jerusalém וְהַטֵּ֖ף a מִקְדָּשִׁ֑ים e profetizarão a solo-de Israel');
INSERT INTO verses VALUES (21016, 26, 21, 8, 'e dirijais לְאַדְמַ֣ת Israel assim disse yhwh eis-me אֵלַ֔יִךְ vehotsetiti espada-meu de-sua-angústia וְהִכְרַתִּ֥י de-teu justo e-malvado');
INSERT INTO verses VALUES (21017, 26, 21, 9, 'porque que cortei de-teu justo e-malvado portanto תֵּצֵ֨א espada-meu de-sua-angústia a todo carne do-norte צָפֽוֹן׃');
INSERT INTO verses VALUES (21018, 26, 21, 10, '[וְיָֽדְעוּ֙] todo que porque yhwh yhwh [חַרְבִּ֖י] [מִתַּעְרָ֑הּ] não não voltava');
INSERT INTO verses VALUES (21019, 26, 21, 11, '[וְאַתָּ֥ה] filho-de homem [בְּשִׁבְר֤וֹן] [מָתְנַ֙יִם֙] [וּבִמְרִיר֔וּת] [תֵּֽאָנַ֖ח] [לְעֵינֵיהֶֽם]');
INSERT INTO verses VALUES (21020, 26, 21, 12, 'e-foi porque dirão a-ti tu que tu נֶאֱנָ֑ח נְאֻנָּח e-dizer-ás a שְׁמוּעָ֣ה שְׁמִיעַת porque בָאָ֡ה בָּאָה e esfregará todo coração e curará todo eis e se purificará todo espírito e-todo em-braços você-andará águas yhwh no-lugar e se tornará oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21021, 26, 21, 13, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21022, 26, 21, 14, 'filho-de homem e profetizará e dirás disse disse Adonai espada espada espada e será purificado e-também מרוטה׃');
INSERT INTO verses VALUES (21023, 26, 21, 15, 'para-que [טְבֹ֤חַ] [טֶ֙בַח֙] [הוּחַ֔דָּה] [לְמַעַן־הֱיֵה־לָ֥הּ] [בָּ֖רָק] para-ela [א֣וֹ] [נָשִׂ֔ישׂ] ou [בְּנִ֖י] [מֹאֶ֥סֶת] filhos-de todo');
INSERT INTO verses VALUES (21024, 26, 21, 16, 'E-colocou ela לְמָרְטָ֖ה לִתְפֹּ֣שׂ בַּכָּ֑ף הִֽיא־ espada espada e-ela מֹרָ֔טָּה a-dar a-ela por-mão-de הוֹרֵֽג׃');
INSERT INTO verses VALUES (21025, 26, 21, 17, 'זְעַ֤ק וְהֵילֵל֙ filho-de homem porque ela הָיתָ֣ה בְעַמִּ֔י ela em-todo príncipes-de Israel מְגוּרֵ֤י a espada foram a povo-meu portanto סְפֹ֥ק a יָרֵֽךְ׃');
INSERT INTO verses VALUES (21026, 26, 21, 18, 'que [בֹ֔חַן] [וּמָ֕ה] se também não será não [Adonai] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21027, 26, 21, 19, 'e-tu filho-de homem הִנָּבֵ֕א e-derribe כַּ֣ף a espada וְתִכָּפֵ֞ל espada שְׁלִישִׁ֙תָה֙ chēreb espada ela חֶ֚רֶב chālāl a-eles haḥōdēṯ para-eles');
INSERT INTO verses VALUES (21028, 26, 21, 20, 'para-a-cau-sa-de lamūg coração vehārbeh hammēkhešōlīm sobre sobre šāʿrehem dei ʾivḥaṯ- espada ʾaḥ ʿāšūyāh leḇārak מְעֻטָּ֥ה לְטָֽבַח׃');
INSERT INTO verses VALUES (21029, 26, 21, 21, 'הִתְאַחֲדִ֥י הֵימִ֖נִי הָשִׂ֣ימִי הַשְׂמִ֑ילִי אָ֖נָה tu-rosto מֻעָדֽוֹת׃');
INSERT INTO verses VALUES (21030, 26, 21, 22, 'e-também eu [כַפִּי֙] [אֶל־כַּפִּ֔י] a [חֲמָתִ֑י] [אֲנִ֥י] yhwh eu yhwh');
INSERT INTO verses VALUES (21031, 26, 21, 23, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21032, 26, 21, 24, 'e tu filho-de homem sim- lekha- dois דרכים espada chēreb rei-de um de-terra-de um saírão dois-deles יד criou no-começo דרך־ cidade criou');
INSERT INTO verses VALUES (21033, 26, 21, 25, 'o-caminho-de [תָּשִׂ֔ים] para-vir espada a [רַבַּ֣ת] filhos-de Amom e-[OBJ] [בְּצוּרָֽה]');
INSERT INTO verses VALUES (21034, 26, 21, 26, 'porque ficou-em-pé rei-de בבל a mãe o-caminho בראש segundo os caminhos para fazer um sortilégio - sortilégio ver com flechas pediu com sortilégios viu com o fígado:');
INSERT INTO verses VALUES (21035, 26, 21, 27, 'na mão direita dele ser o sortilégio Jerusalém para fazer carvalhos para abrir a boca em matança para subir voz voz para colocar como cidades sobre como portas para derramar סֹלְלָה para-construir daique:');
INSERT INTO verses VALUES (21036, 26, 21, 28, 'e-será a-eles [*כקסום־**כִּקְסָם־שָׁוְא֙] em-olhos-deles [שְׁבֻעֵ֥י] [שְׁבֻע֖וֹת] a-eles e-ele [עָוֺ֖ן] [לְהִתָּפֵֽשׂ׃]');
INSERT INTO verses VALUES (21037, 26, 21, 29, 'portanto assim disse Adonai yhwh porque הזכרכם עוןכם בהגלות פשעיכם להראות חטאיכם em-todo עליותיכם porque recordai-vos na-pata agarrar-vos:');
INSERT INTO verses VALUES (21038, 26, 21, 30, 'e-tu profanado perverso-o príncipe-de Israel que veio seu-dia na-vez iniquidade-de destruição:$');
INSERT INTO verses VALUES (21039, 26, 21, 31, 'assim disse Adonai yhwh levou-se-a-fora o-copinho e-elevou-se a-coroa esta não Isto a baixa e a elevada e a elevada a-Shaphil');
INSERT INTO verses VALUES (21040, 26, 21, 32, 'avareza avareza avareza eu-ponho-a também não ser foi até veio que a-ele ele e lhe darei');
INSERT INTO verses VALUES (21041, 26, 21, 33, 'e-tu filho-de homem veja, profetizei e-dirás disse disse Adonai yhwh a filhos-de Amom espada espada e dirás chēreb חֶ֤רֶב פתוחה לתבח מרוטה להכליל para ברק׃');
INSERT INTO verses VALUES (21042, 26, 21, 34, '[בַּחֲז֥וֹת] para-ti [שָׁ֔וְא] [בִּקְסָם־לָ֖ךְ] para-ti [לָתֵ֣ת] para-dar [אֶֽל־צַוְּארֵי֙] a [רְשָׁעִ֔ים] [אֲשֶׁר־בָּ֣א] [יוֹמָ֔ם] que veio [קֵֽץ]');
INSERT INTO verses VALUES (21043, 26, 21, 35, '[הָשַׁ֖ב] a [בִּמְק֧וֹם] [אֲשֶׁר־נִבְרֵ֛את] que [מְכֻרוֹתַ֖יִךְ] em-terra-de [אֹתָֽךְ]');
INSERT INTO verses VALUES (21044, 26, 21, 36, 'e-eu-despejo sobre-ti זעם באש hebreu-tei apichá sobre ti únentatíkhe em-mão-de homens bó''aríyim chárashey מַשְׁחִֽית׃');
INSERT INTO verses VALUES (21045, 26, 21, 37, 'láiš tíhiyeha para-alimento dámekhe será no-meio-de a-terra não tizázakéri que eu yhwh e eu falei:');
INSERT INTO chapters VALUES (824, 26, 22, 31);
INSERT INTO verses VALUES (21046, 26, 22, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21047, 26, 22, 2, 'e-tu filho-de homem [הֲתִשְׁפֹּ֖ט] [אֶת־עִ֣יר] a cidade [OBJ] [כָּל־תּוֹעֲבוֹתֶֽיהָ] a todo');
INSERT INTO verses VALUES (21048, 26, 22, 3, 'e dirás assim disse Adonai yhwh cidade שֹׁפֶ֥כֶת דָּ֛ם בְּתוֹכָ֖הּ para-vir עִתָּ֑הּ וְעָשְׂתָ֧ה גִלּוּלִ֛ים sobre-ela para a impureza:');
INSERT INTO verses VALUES (21049, 26, 22, 4, 'no teu sangue que tu escorriste tu te culpaste e nos teus ciclos que fizeste você foste impura e ofereceste os teus dias e viste até as tuas épocas sobre assim nattātikkē cherpāh lagōyim veqallāsāh para-todo das nações:');
INSERT INTO verses VALUES (21050, 26, 22, 5, 'haqrōvot veharḥokot mimmekh yitqallasū- em-ti temēʾat hašśēm רבָּת הַמְּהוּמָה׃');
INSERT INTO verses VALUES (21051, 26, 22, 6, 'eis príncipes-de Israel homem לִזְרֹע֖וֹ הָ֣יוּ em-ti para-que derramou-se דָּֽם׃');
INSERT INTO verses VALUES (21052, 26, 22, 7, 'pai וָאֵם֙ הֵקַ֣לּוּ em-ti לַגֵּ֛ר fizeram בַעֹ֖שֶׁק בְּתוֹכֵ֑ךְ יָת֥וֹם e-álmaná hunú em-te:');
INSERT INTO verses VALUES (21053, 26, 22, 8, 'qédasháv bázít e-a שַׁבְּתֹתַ֖י chillált:');
INSERT INTO verses VALUES (21054, 26, 22, 9, 'homens-de rákíl havú em-ti para-que derramou-se sangue e-a os-montes אָ֣כְלוּ em-ti zimmáh fizeram bétokékh:');
INSERT INTO verses VALUES (21055, 26, 22, 10, '[עֶרְוַת־אָ֖ב] pai [טְמֵאַ֥ת] [הַנִּדָּ֖ה] [עִנּוּ־בָֽךְ]');
INSERT INTO verses VALUES (21056, 26, 22, 11, '[וְאִ֣ישׁ] a mulher-de companheiro-seu fez [תּֽוֹעֵבָ֔ה] e-homem a [טִמֵּ֣א] [בְזִמָּ֑ה] [וְאִ֛ישׁ] [אֶת־אֲחֹת֥וֹ] a [עִנָּה־בָֽךְ]');
INSERT INTO verses VALUES (21057, 26, 22, 12, 'שׁוֹחַד tomaram-o em-ti para-que derramou-se sangue נֶ֧שֶׁךְ וְתַרְבִּ֣ית לָקַ֗חַתְּ וַתְּבַצְּעִ֤י רֵעַ֙יִךְ֙ בַּעֹ֔שֶׁק e a mim שָׁכַ֔חַתְּ oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21058, 26, 22, 13, 'e-eis [הִכֵּ֣יתִי] [כַפִּ֔י] a [אֲשֶׁ֣ר] que [וְעַל־דָּמֵ֔ךְ] e-sobre [הָי֖וּ] que');
INSERT INTO verses VALUES (21059, 26, 22, 14, '[הֲיַעֲמֹ֤ד] [לִבֵּךְ֙] se sejam-fortes [לַיָּמִ֕ים] [אֲשֶׁ֥ר] que eu fez [אֲנִ֥י] yhwh yhwh falei');
INSERT INTO verses VALUES (21060, 26, 22, 15, 'וַהֲפִיצוֹתִ֤י otakh entre-as-nações וְזֵרִיתִ֖יךְ nas-terras וַהֲתִמֹּתִ֥י טֻמְאָתֵ֖ךְ de-te');
INSERT INTO verses VALUES (21061, 26, 22, 16, 'e herdarás sobre-ti aos-olhos-de gentes e-saberás-te porque yhwh yhwh');
INSERT INTO verses VALUES (21062, 26, 22, 17, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21063, 26, 22, 18, 'filho-de homem eram- para-mim casa-de Israel todos cobre e separarás e ferro no-meio-de em-meio-de fornos síagos prata eram');
INSERT INTO verses VALUES (21064, 26, 22, 19, 'portanto assim disse Adonai yhwh porque estar voces-todos para síagos portanto eis-me קֹבֵ֣ץ vos a em Jerusalém');
INSERT INTO verses VALUES (21065, 26, 22, 20, '[קְבֻ֣צַת] [כֶּ֡סֶף] [וּ֠נְחֹשֶׁת] [וּבַרְזֶ֨ל] [וְעוֹפֶ֤רֶת] [וּבְדִיל֙] a meio-de [לָפַֽחַת־עָלָ֥יו] [אֵ֖שׁ] sobre-ele fogo [אֶקְבֹּץ֙] assim [וּבַחֲמָתִ֔י] [וְהִנַּחְתִּ֥י] [וְהִתַּכְתִּ֖י] [אֶתְכֶֽם]');
INSERT INTO verses VALUES (21066, 26, 22, 21, '[וְכִנַּסְתִּ֣י] vos [וְנָפַחְתִּ֥י] sobre-vós [בְּאֵ֣שׁ] [עֶבְרָתִ֑י] [וְנִתַּכְתֶּ֖ם] [בְּתוֹכָֽהּ]');
INSERT INTO verses VALUES (21067, 26, 22, 22, 'כְּהִתּ֥וּךְ prata no-meio-de כּ֔וּר assim תֻּתְּכ֣וּ בְתוֹכָ֑הּ וִֽידַעְתֶּם֙ porque yhwh yhwh despejei חֲמָתִ֖י sobre-vós');
INSERT INTO verses VALUES (21068, 26, 22, 23, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21069, 26, 22, 24, 'filho-de homem dize terra não terra não não ela não [זָֽעַם]');
INSERT INTO verses VALUES (21070, 26, 22, 25, 'קֶ֤שֶׁר נְבִיאֶ֙יהָ֙ dentro dela כַּאֲרִ֥י שׁוֹאֵג טֹ֣רֵֽף טָ֑רֶף alma אָכָ֗לוּ חֹ֤סֶן וִיקָר֙ יִקָּ֔חוּ אַלְמְנוֹתֶ֖יהָ הִרְבּ֥וּ בְתוֹכָֽהּ׃');
INSERT INTO verses VALUES (21071, 26, 22, 26, 'כֹּהֲנֶ֜יהָ eles/elas amassaram minha lei e santificaram meus santos entre santo-de não não e separaram e-entre não para o purificado não e informaram e as minhas leis os-altearam seus olhos e calei-me em-meio-de-eles');
INSERT INTO verses VALUES (21072, 26, 22, 27, 'suas saraias em seu meio como raposas caçadores de caça para derramar sangue para destruir almas para-que em seu rugido בָּֽצַע׃');
INSERT INTO verses VALUES (21073, 26, 22, 28, 'וּנְבִיאֶ֗יהָ טָח֤וּ a-eles תָּפֵ֔ל חֹזִ֣ים שָׁ֔וְא וְקֹסְמִ֥ים a-eles כָּזָ֑ב dizeis assim disse Adonai yhwh e-יהוה não palavra');
INSERT INTO verses VALUES (21074, 26, 22, 29, 'povo a-terra עָ֣שְׁקוּ עֹ֔שֶׁק וְגָזְל֖וּ גָּזֵ֑ל e o pobre e pobre e a fome e-a o estrangeiro enganaram sem juízo');
INSERT INTO verses VALUES (21075, 26, 22, 30, 'e pedi deles homem ao redor de - ao redor e permaneceu בַּפֶּ֧רֶץ לְפָנַ֛י a-terra para-não para-não שַׁחֲתָ֑הּ e-não מָצָֽאתִי׃');
INSERT INTO verses VALUES (21076, 26, 22, 31, '[וָאֶשְׁפֹּ֤ךְ] sobre-eles [זַעְמִ֔י] [בְּאֵ֥שׁ] [עֶבְרָתִ֖י] [כִּלִּיתִ֑ים] [דַּרְכָּם֙] [בְּרֹאשָׁ֣ם] dei oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (825, 26, 23, 49);
INSERT INTO verses VALUES (21077, 26, 23, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21078, 26, 23, 2, 'filho-de homem [נָשִׁ֔ים] mulheres filhas-de se');
INSERT INTO verses VALUES (21079, 26, 23, 3, 'וַתִּזְנֶינָה בְּמִצְרַיִם בְּנִעֻרֵיהֶן זָנוּ שָׁמָה מֹעֲכוּ שְׁדֵיהֶן e ali עִשׂוּ דָּדֵי בתולות׃');
INSERT INTO verses VALUES (21080, 26, 23, 4, 'ושמותן אֲהוֹלָה a grande ואֲהוֹליבה אֲחוהָהּ ותהיינה a-mim ותלדנה filhos ובנות ושמותן שֶׁמְרוֹן אָהֳלָ֔ה Jerusalém אָהֳלִיבָֽה׃');
INSERT INTO verses VALUES (21081, 26, 23, 5, 'וַתִּ֥זֶן אָהֳלָ֖ה em-lugar-de-mim וַתַּעְגַּב֙ sobre מְאַהֲבֶ֔יהָ a Assíria קְרוֹבִֽים׃');
INSERT INTO verses VALUES (21082, 26, 23, 6, 'לְבֻשֵׁ֤י תְכֵ֙לֶת֙ פַּח֣וֹת e-seganim bachurei prazer כלם parashim rochbe susim');
INSERT INTO verses VALUES (21083, 26, 23, 7, 'e-deu taznuteha sobre-eles mivchar filhos-de Assíria כלם u-bekhol que agvaha em-todo gilulayhem ficou-imunda-verso-final');
INSERT INTO verses VALUES (21084, 26, 23, 8, 'e-a suas-tentrações não não que porque a-ela acostaram-se em-suas-juventudes e-elas fizeram seus-olhos em-suas-virgindades e-deram suas-tentrações sobre-ela');
INSERT INTO verses VALUES (21085, 26, 23, 9, 'portanto נְתַתִּ֖יהָ por-mão-de em-suas-amores em-mão-de filhos-de Assur que עָגְבָ֖ה sobre-eles');
INSERT INTO verses VALUES (21086, 26, 23, 10, 'הֵמָּה֮ גִּלּ֣וּ עֶרְוָתָהּ֒ בָּנֶ֤יהָ וּבְנוֹתֶ֙יהָ֙ levaram-os וְאוֹתָ֖הּ com-a-espada הָרָ֑גוּ e-ela-tornou-se nome לַנָּשִׁ֔ים וּשְׁפוּטִ֖ים fizeram em-ela');
INSERT INTO verses VALUES (21087, 26, 23, 11, 'E-viu אֲחוֹתָ֣הּ אָהֳלִיבָ֔ה e destruiu sua cabra מִמֶּנָּה e-a suas paixões de bebidas sua irmã');
INSERT INTO verses VALUES (21088, 26, 23, 12, 'a filhos-de Assíria cabra fermentos e soldados próximos vestidos instrumentos quebrados montadores cavaleiros jovens prazer כלם׃');
INSERT INTO verses VALUES (21089, 26, 23, 13, 'e-eu-vi que ficou-imunda o-caminho-de um para-as-senhoras;');
INSERT INTO verses VALUES (21090, 26, 23, 14, 'e-acresceu a E-viu e-veio-a-vista-de homens-de quebrada sobre הַקִּ֔יר imagens chakukim בַּשָׁשַֽׁר׃');
INSERT INTO verses VALUES (21091, 26, 23, 15, 'chagorei ezer bematanheyhem saruhei tevulim berashheyhem marah shalishim כלם semelhança filhos-de בָבֶל֙ terra terra moladtem');
INSERT INTO verses VALUES (21092, 26, 23, 16, 'sobre-eles para-a-visão suas-olhos e-eleveu מלאכים a-eles como-uma-nuvem');
INSERT INTO verses VALUES (21093, 26, 23, 17, 'וַיָּבֹ֨אוּ a-ela filhos-de בָבֶל֙ Lemishkab nuvens e-eles-se-mancharam a-ela em-suas-olho e-ele-se-manchou neles e-ele-se-dividiu não de-eles');
INSERT INTO verses VALUES (21094, 26, 23, 18, 'e-ele-revelou sua-discrição e-revelou a seu-desnudamento e-arrancou alma-minha de-em-o-superior-de-a como foi-arrancada de-cima-de de-sobre sua-irmã');
INSERT INTO verses VALUES (21095, 26, 23, 19, 'e-multiplicou-se a sua-discrição para-lembrar a dias-de suas-juventudes que zân''tā em-terra-de Egito');
INSERT INTO verses VALUES (21096, 26, 23, 20, 'vâ ta''ăg̱''bā sobre pî paligšêyhem que carne- khamôrim bêsārâm vâ zirmât cavalos zirmâm');
INSERT INTO verses VALUES (21097, 26, 23, 21, 'vâ tippqədî a intenção seus dias de mocidade ba''ăśôt de-Egito dadâyikh para-que Shaddai נְעוּרָֽיִךְ׃');
INSERT INTO verses VALUES (21098, 26, 23, 22, 'por-isso [אָהֳלִיבָ֗ה] assim disse Adonai yhwh eis-me de-cidade-de a [OBJ] sobre-ti a que [וַהֲבֵאתִ֥ים] [עָלַ֖יִךְ] deles');
INSERT INTO verses VALUES (21099, 26, 23, 23, 'filhos-de בָבֶ֣ל e-todo dos-cassidim פְּק֤וֹד וְשׁ֙וֹעַ֙ וְק֔וֹעַ todo filhos-de Assíria eles בַּח֨וּרֵי desejo câmaras e seguidores todos trinta e cavalos montadores cavaleiros כלם׃');
INSERT INTO verses VALUES (21100, 26, 23, 24, 'e-entraram sobre ti arqueiro carro-de e carro e na congregação nações adúltera e escudo e confinado serão puestos sobre-ti ao-redor e-darei diante deles מִשְׁפָּט e julgai-vos pelo vosso juízo');
INSERT INTO verses VALUES (21101, 26, 23, 25, 'וְנָתַתִּ֨י minha ciúme sobre-ti e façam otakh בּחֵמָה אַףֵךְ וְאָזְנַיִךְ יָסִירֻ וְאַחֲרִיתֵךְ com-a-espada תִּפּוֹל eles filhos-te וּבְנוֹתַיִךְ יִקָּ֔חוּ וְאַחֲרִיתֵךְ תֵּאָכֵל em-a-chama');
INSERT INTO verses VALUES (21102, 26, 23, 26, '[וְהִפְשִׁיט֖וּךְ] a [וְלָקְח֖וּ] [כְּלֵ֥י] instrumentos-de');
INSERT INTO verses VALUES (21103, 26, 23, 27, 'והשבתי zinmatecha de-te e-a zonatech da-terra Egito e-não תשי עינייםך não e-Misraim não תזכרי－ ainda');
INSERT INTO verses VALUES (21104, 26, 23, 28, 'que assim disse Adonai yhwh eis-me נתנק em-mão que שָׂנֵ֑את na-mão que נוקעה נַפְשֵׁ֖ךְ de-eles');
INSERT INTO verses VALUES (21105, 26, 23, 29, 'וְעָשׂ֨וּ te בְּשִׂנְאָ֗ה וְלָקְחוּ֙ todo יְגִיעֵ֔ךְ nu עֵירֹ֣ם וְעֶרְיָ֑ה וְנִגְלָה֙ nudez-de זְנוּנַ֔יִךְ וְזִמָּתֵ֖ךְ וְתַזְנוּתָֽיִךְ׃');
INSERT INTO verses VALUES (21106, 26, 23, 30, 'fez Estas para-ti בִּזְנוֹתֵךְ֙ depois-de nações sobre que נִטְמֵ֖את בְּגִלּוּלֵיהֶֽם׃');
INSERT INTO verses VALUES (21107, 26, 23, 31, 'em-a-caminho אֲחוֹתֵ֖ךְ הָלָ֑כְתְּ e-darei כוֹסָ֖הּ בְּיָדֵֽךְ׃');
INSERT INTO verses VALUES (21108, 26, 23, 32, 'assim disse Adonai yhwh כּ֤וֹס אֲחוֹתֵךְ֙ תִּשְׁתִּ֔י הָעֲמֻקָּ֖ה e a amplidão será para rir e para se zombar de muita para aumentar');
INSERT INTO verses VALUES (21109, 26, 23, 33, 'carruagem e angústia me encham copo שַׁמָּ֣ה e vazio כוס אחותך Samaria');
INSERT INTO verses VALUES (21110, 26, 23, 34, '[וְשָׁתִ֨ית] [אוֹתָ֜הּ] [וּמָצִ֗ית] e-[OBJ] [תְּגָרֵ֖מִי] [וְשָׁדַ֣יִךְ] [תְּנַתֵּ֑קִי] que porque eu [נְאֻ֖ם] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21111, 26, 23, 35, 'portanto assim disse Adonai yhwh porque esqueceste-te de-mim ותשלכי אוֹתִ֖י depois-de גוועך e-também אתְ sai זיממתך e-a תזנותיך׃');
INSERT INTO verses VALUES (21112, 26, 23, 36, 'E-disse yhwh a-mim filho-de homem [אֶֽת־אָהֳלָ֖ה] a [וְהַגֵּ֣ד] e-[OBJ] [OBJ] [תּוֹעֲבוֹתֵיהֶֽן] a');
INSERT INTO verses VALUES (21113, 26, 23, 37, 'que נאפוּ ודם֙ em-lhes e-a gilulê-hen naifû e-também a benê-hen que a-eles para-alimento he''abirû a-eles para-alimento');
INSERT INTO verses VALUES (21114, 26, 23, 38, 'ainda esta עָשׂוּ a-mim temû a no-dia em-o-dia aquele e-a minhas cerimônias chillêlu');
INSERT INTO verses VALUES (21115, 26, 23, 39, 'u-bashachatam a os-filhos-deles légilulê-hem e chegaram a no-dia miqdashî no-dia o-aquele para santificá-lo no-meio-de assim fizeram no-meio-de casa-minha');
INSERT INTO verses VALUES (21116, 26, 23, 40, 'e também que tu enviarias aos homens vêm מִמּרְחָ֑ק que anjo -enviado- a-eles e-eis viriam para aquele [כָּחַ֥לְתְּ] assim fizeste os teus olhos e a tua testemunha até a eternidade:');
INSERT INTO verses VALUES (21117, 26, 23, 41, 'e te assentarás sobre a mesa de honra e o pão estabelecido diante dela e eu oferecer-te-ei incenso e-samnî samtâ sobre-ela');
INSERT INTO verses VALUES (21118, 26, 23, 42, 'e-voz hamo''n שָׁלוֹ em-a e-a homens homem homem mûvâ''im mimmiddêrâb vayittenu bracelos a yedê''hen vá''atret esplendor-de sobre râ''šê''hen');
INSERT INTO verses VALUES (21119, 26, 23, 43, 'e-eu-disse labbâlâh ni''upîm taznutêhā vahi∶');
INSERT INTO verses VALUES (21120, 26, 23, 44, 'vayyavo'' a ela kavboa a mulher זוֹנָ֑ה assim bavo'' a aholāh e-a aholivā išṣôt hazzimmā∶');
INSERT INTO verses VALUES (21121, 26, 23, 45, 'vā''ănāšîm צדיקים eles יִשְׁפְּט֣וּ אותם משפט נאופות משפט שופכות sangue que נאופות elas ודם בהידיהם׃');
INSERT INTO verses VALUES (21122, 26, 23, 46, 'que assim disse Adonai yhwh העלה sobre-eles congregação e dará a-elas para a maldição e para a vergonha');
INSERT INTO verses VALUES (21123, 26, 23, 47, 'lançarão nelas pedra congregação e criarão elas com suas espadas seus filhos e suas filhas יַהֲרֹ֔גוּ וּבָתֵּיהֶ֖ן בָּאֵ֥שׁ יִשְׂרֹֽפוּ׃');
INSERT INTO verses VALUES (21124, 26, 23, 48, '[וְהִשְׁבַּתִּ֥י] [זִמָּ֖ה] de a-terra [כָּל־הַנָּשִׁ֔ים] todo as-mulheres e-não');
INSERT INTO verses VALUES (21125, 26, 23, 49, 'e-darão זִמַּתְכֶ֙נָה֙ sobre-vos e-vossos gulóleis tisháinah e conhecereis que eu Adonai yhwh');
INSERT INTO chapters VALUES (826, 26, 24, 27);
INSERT INTO verses VALUES (21126, 26, 24, 1, 'e-houve palavra-de yhwh a-mim no-ano o-nono no-mês o-tenth no-dez dizendo para-dizer');
INSERT INTO verses VALUES (21127, 26, 24, 2, 'filho-de homem para-ti o-dia nome o-dia a osso o-dia esta saká o-dia Babilônia a Jerusalém o-dia o-dia a-esta');
INSERT INTO verses VALUES (21128, 26, 24, 3, 'e-mostração a casa-de o meri mashal e-dirás disse assim disse Adonai yhwh shofet o siri shofet e-também yetsok nele águas');
INSERT INTO verses VALUES (21129, 26, 24, 4, 'esaf netaheya a ela todo bom bom יָרֵ֣ךְ ve-katef mivchar ossos enchei');
INSERT INTO verses VALUES (21130, 26, 24, 5, 'seleção o-rebanho tomar e-também tempo os ossos תַּחְתֶּ֑יהָ fértil sua fertilidade também cozidos suas ossadas em seu interior:');
INSERT INTO verses VALUES (21131, 26, 24, 6, 'portanto assim disse Adonai yhwh אוי֮ cidade הַדָּמִים֒ סִ֚יר que חֶלְאָתָ֣ה nela וְחֶ֨לְאָתָ֔הּ não yats''āh מִמֶּנָּה לִנְתָחֶ֤יהָ לִנְתָחֶ֙יהָ֙ הוֹצִיאָ֔הּ não נָפַ֥ל sobre-ela גּוֹרָֽל׃');
INSERT INTO verses VALUES (21132, 26, 24, 7, 'que דָּמָהּ בּוֹכָהּ ser sobre צְחִיחַ סלע não não despejou-o sobre a-terra pó sobre-ele cimento:');
INSERT INTO verses VALUES (21133, 26, 24, 8, 'para-oferecer [חֵמָה֙] [לִנְקֹ֣ם] [נָקָ֔ם] dei a [עַל־צְחִ֣יחַ] sobre para-não [הִכָּסֽוֹת׃]');
INSERT INTO verses VALUES (21134, 26, 24, 9, 'portanto assim disse Adonai yhwh [א֖וֹי] cidade [הַדָּמִ֑ים] também eu [הַמְּדוּרָֽה]');
INSERT INTO verses VALUES (21135, 26, 24, 10, 'הרבך as-madeiras הדליק o-fogo התם הבשר והרקח המרקה e-as-ossadas serão-acendidas');
INSERT INTO verses VALUES (21136, 26, 24, 11, 'e-a-estabeleça-a sobre suas-braseiras vazia para-que se-derreta e-se-acenda sua-de-prata e-se-fundirá em-a-mezzanino sua-imundície vocês-serão-tornados doença-a');
INSERT INTO verses VALUES (21137, 26, 24, 12, 'tristezas doença e-não sairá de-a רבבה doença-a em-chamas doença-a');
INSERT INTO verses VALUES (21138, 26, 24, 13, 'na-imundície-tua זִמָּ֑ה por-causa-de purificar-te e-não purificaste-te de-a-tua-imundície não purifica-te- ainda até sobre-ti a חֲמָתִ֖י em-ti');
INSERT INTO verses VALUES (21139, 26, 24, 14, 'eu yhwh falei-eu veio-a e-fiz-eu não eu-apagarei e-não eu-curarei e-não eu-deixarei-os segundo-a-tua-manifestação e-com-o-teu-adoro julgamento-teu oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21140, 26, 24, 15, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21141, 26, 24, 16, 'filho-de homem eis-me tomou de-ti a amado olhos-teus em-a-peste e-não lamentarás e-não chegarás-a-chorar e não vires lágrima-teu');
INSERT INTO verses VALUES (21142, 26, 24, 17, 'suspirarei calar-me metim luto não fazes de-teu-coroa costura sobre-ti e-tus-sapatos põe em-tus-pés e-não enrolas sobre de-seu-lábio e-pão não não você-comerá');
INSERT INTO verses VALUES (21143, 26, 24, 18, 'e-ele-falou a o-povo de-manhã e-tu-morreste [בָּעָ֑רֶב] no entardecer e-eu-fiz na-manhã como mandei');
INSERT INTO verses VALUES (21144, 26, 24, 19, 'e-disseram a-mim o-povo não diga a-nós o-quê que tu porque tu fez');
INSERT INTO verses VALUES (21145, 26, 24, 20, 'e-disse a-eles [דְּבַ֨ר־יְהוָ֔ה] ser foi dizendo para-dizer');
INSERT INTO verses VALUES (21146, 26, 24, 21, 'אֱמֹ֣ר ׀ para-casa-de Israel assim disse Adonai yhwh eis-me profanador a santo-meu orgulho poder-vos vossos-olhos olhos-vossos e-tenha-cuidado alma-vossa e-vosso-filhos [אֲשֶׁ֥ר] que abandoneis em-a-espada cairão');
INSERT INTO verses VALUES (21147, 26, 24, 22, 'e-fizerdes como-que faça sobre não não vagarais e-pão não não comereis');
INSERT INTO verses VALUES (21148, 26, 24, 23, 'e-vosso-ornamento sobre cabeças-vossas e-calçados-vossos não não lamentareis e-não chorareis e-vos-justificareis em-vossas-perversidades e-vos-consolareis homem a irmão-dele');
INSERT INTO verses VALUES (21149, 26, 24, 24, 'e-será Iehesheval a-vós para-maravilha conforme-tudo que fez fazeis-vós em-a-sua-vinda que porque eu Adonai yhwh');
INSERT INTO verses VALUES (21150, 26, 24, 25, 'e-tu filho-de homem halo no-dia tomarei-eu deles a refugio-grande alegria tua-ta-farate a ma-ham-mad seus olhos- e-a yhwh נַפְשָׁ֔ם não u-bne-to-te-he-im');
INSERT INTO verses VALUES (21151, 26, 24, 26, 'no-dia aquele virá ha-pa-lit a-ti le-hash-ma-ut az-ne-yim');
INSERT INTO verses VALUES (21152, 26, 24, 27, 'no-dia aquele [יִפָּ֤תַח] boca-tua a o-fugitivo u-te-daber e-não te-al-em ainda a-eles para-eles le-mo-fet e-saberão yhwh eu yhwh');
INSERT INTO chapters VALUES (827, 26, 25, 17);
INSERT INTO verses VALUES (21153, 26, 25, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21154, 26, 25, 2, 'filho-de homem colocar פָּנֶ֖יךָ a filhos-de Amom e profetizarão sobre-eles');
INSERT INTO verses VALUES (21155, 26, 25, 3, 'e-dirás aos-filhos-de Amom ouvi palavra-de Adonai yhwh assim disse Adonai yhwh porque diz-te o-irmão a do-meu-santuário que propriedade e-a terra-de que porque respirou e-a casa Judá porque foram na-exílio');
INSERT INTO verses VALUES (21156, 26, 25, 4, 'por-isto eis-me dando-te para-filhos-de antes para-moração e-ocuparão sobre-ti em-você e-daremos em-ti de-sua-habitação eles comerão fruto-de-você e-eles beberão leite-de-você');
INSERT INTO verses VALUES (21157, 26, 25, 5, 'e-darei a multiplicai para a loucura camelos e-a filhos-de Amom para-mimar- yhwh e-voces-sabereis porque eu yhwh');
INSERT INTO verses VALUES (21158, 26, 25, 6, 'que assim disse Adonai yhwh porque teu-sufoco mão e-teu-pé no-pé e-você-se-rejubilou em-todo teu-ódio com-alma a terra-de Israel');
INSERT INTO verses VALUES (21159, 26, 25, 7, 'por-isso eis-me eu-estendi a minha-mão sobre-ti e-dar-te-eu lagōyim e-cortar-te-eu de os-povos e-perder-te-eu de as-terras destruir-te-eu yhwh porque eu yhwh');
INSERT INTO verses VALUES (21160, 26, 25, 8, 'assim disse Adonai yhwh porque disse Moabe e-gente-de-seir eis como-todo- as-nações casa Judá');
INSERT INTO verses VALUES (21161, 26, 25, 9, 'portanto eis-me abre-o a lado Moabe מֵהֶעָרִים de-sua-cidade do-fim-dele terra terra casa das-plainas Baal lugar');
INSERT INTO verses VALUES (21162, 26, 25, 10, 'para-filhos-de em-o-orient-e sobre filhos-de Amom e-dá-la para-a-herança para-fim-de não [sem-traducao] filhos-de Amom b-gó-i-im:');
INSERT INTO verses VALUES (21163, 26, 25, 11, 'e-no-Moabe eu-farei as שֹׁפטים e-saberão porque yhwh yhwh');
INSERT INTO verses VALUES (21164, 26, 25, 12, 'assim disse Adonai yhwh porque fazer Edom em-vingança vinganca para-casa-de Judá e-eles-se-arrependeram culpado e-vingar-se-ão בָהֶֽם׃');
INSERT INTO verses VALUES (21165, 26, 25, 13, 'portanto assim disse Adonai yhwh e-virei mão-minha sobre Edom וְהִכְרַתִּ֥י homem homem e-com-animal [חָרְבָּה֙] deserta do-sul e-dela com-espada cairão');
INSERT INTO verses VALUES (21166, 26, 25, 14, 'וְנָתַתִּ֨י a minha-niqumat em-o-Edom em-mão-de meu-povo Israel e fizeram em-o-Edom conforme-meu-apf e-conforme-minha-hamata וְיָֽדְעוּ֙ וְיָדַעֻהוּ a minha-niqumat oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21167, 26, 25, 15, 'assim disse Adonai yhwh porque fazer Filisteus em-nikama e-eles-fizeram-niqumat niquma bisch''ata benefesh lemashchit eivat eternidade');
INSERT INTO verses VALUES (21168, 26, 25, 16, 'portanto assim disse Adonai yhwh eis-me noteh mão-minha sobre filisteus vehikrati a kretim vehahavdathi o-mar sheerit choph o-mar');
INSERT INTO verses VALUES (21169, 26, 25, 17, 'e-fiz em-eles vindictas grandes dentro-de-repreendimentos חֵמָ֑ה וְיָֽדְעוּ֙ וְיָדַעֻהוּ porque yhwh yhwh em-dar a minha-vindicta em-eles');
INSERT INTO chapters VALUES (828, 26, 26, 21);
INSERT INTO verses VALUES (21170, 26, 26, 1, 'e-houve em-onze-de doze ano no-primeiro ser foi palavra-de dizendo');
INSERT INTO verses VALUES (21171, 26, 26, 2, 'filho-de homem porque que disse Tiro sobre Jerusalém o-irmão quebrada portas-de os-povos voltaram-se a-mim encheram-na a-destruição');
INSERT INTO verses VALUES (21172, 26, 26, 3, 'portanto assim disse Adonai yhwh eis-me sobre-ti pedra e-elevar-ei sobre-ti nações muitos como-a-elevação o-mar para-o-revelar');
INSERT INTO verses VALUES (21173, 26, 26, 4, 'e-destruirão as-muralhas pedra e-arruinarão de-seus-muros e-espalharei poeira-de-a מִמֶּנָּה e-darei a-ela para-cobrir-se pedra.');
INSERT INTO verses VALUES (21174, 26, 26, 5, 'degrau sagrados tíhiyeha no-meio-de o-mar que eu דִבַּ֔רְתִּי oráculo-de Adonai yhwh e-será em-vanidade para-as-nações.');
INSERT INTO verses VALUES (21175, 26, 26, 6, 'וּבְנוֹתֶ֙יהָ֙ que no-campo pela-espada serão-massacradas e-saberão porque yhwh yhwh');
INSERT INTO verses VALUES (21176, 26, 26, 7, 'que assim disse Adonai yhwh eis-me que traria a pedra Nebucodonosor rei-de Babilônia מצפון rei reis em-sus e-em-rebeve e em barcos e-kahal ו העם- muito');
INSERT INTO verses VALUES (21177, 26, 26, 8, 'em-nos-tei-ch no-campo com-a-espada harrog e deu עָלַ֜יִךְ deyek e-shafak sobre-ti solalah e-ele-levantará sobre-ti tenda(s)-de-a');
INSERT INTO verses VALUES (21178, 26, 26, 9, 'e-destruirá em-o-lado-dele irá dar nas-muralhas-tuas e-nos-torres-tuas ele-espalhará com-as-espadas-seus');
INSERT INTO verses VALUES (21179, 26, 26, 10, 'de-a-família-de-a dos-cavalo(s)-seu [יְכַסֵּ֣ךְ] [אֲבָקָ֑ם] [מִקּוֹל֩] [פָּרַ֨שׁ] [וְגַלְגַּ֜ל] [וָרֶ֗כֶב] [תִּרְעַ֙שְׁנָה֙] [חֽוֹמוֹתַ֔יִךְ] [בְּבֹאוֹ֙] [בִּשְׁעָרַ֔יִךְ] como-entradas cidade quebrada');
INSERT INTO verses VALUES (21180, 26, 26, 11, 'em-partes סוּסָיו rir-se-á a todo fora-tua povo-teu com-a-espada matará e-marcas poder-teu para-a-terra desce-vos-');
INSERT INTO verses VALUES (21181, 26, 26, 12, 'e-arrebatam-vos-os forças-vossas e-roubam-vos-as mercadorias-vossas e-demolir-vos-os muradas-vossas e-casas-as desejadas-vossas serão-quebrados e-tuas-pedras e-tus-arvores e-teu-poeiras no-meio-de águas colocarão');
INSERT INTO verses VALUES (21182, 26, 26, 13, 'e-farei-calar multidão teus-cantares e-voz tus-tesouras não יִשָּׁמַ֖ע ainda');
INSERT INTO verses VALUES (21183, 26, 26, 14, 'e-dar-te-eu para-faces pedra mishtach charamim תִּֽהְיֶ֔ה não tibaneh ainda que eu yhwh dibberti oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21184, 26, 26, 15, 'assim disse Adonai yhwh letzor não é que de-a-voz mapalttech beenok chalal behareg hereg betochech tremam as-ilhas:');
INSERT INTO verses VALUES (21185, 26, 26, 16, 'e-descem de-cima-de de-seus-tronos todo príncipes-de o-mar e-tirem a as-suar-vestes e-a de-roupas tecidas-as-deles despiam-se pelas-ansiedades vistam-se sobre a-terra se-ajuntarão e-tremecerão para-os-tranquilos-momentos e-desolaram-se sobre-você-versículo-final');
INSERT INTO verses VALUES (21186, 26, 26, 17, 'e-elevarão sobre-você lamento e-diremos para-ti como perdestes morando dos-dias a-cidade a-louvor que era forte na-mar ela e-moradores-a que eles-deram destruição-seus para-todo moradores-a:');
INSERT INTO verses VALUES (21187, 26, 26, 18, 'agora temerão a-ilha dia de-tua-caída e-eles-serão-terrorizados as-ilhas que no-mar de-tua-saída');
INSERT INTO verses VALUES (21188, 26, 26, 19, 'que assim disse Adonai yhwh em-mi te-a cidade estará-ferida como-cidades que não e-foram-destruídas quando-subir sobre-ti a abismo e-ocultaram-te as-águas os-muitos-verso-final');
INSERT INTO verses VALUES (21189, 26, 26, 20, 'e-te-fará-descer a descendo-os-de cavidade eternidade povo para sempre e-te-fará-estabelecer בְּאֶ֨רֶץ em-baixo-superior-plural como-ruínas desde-tempo-pré-histórico a não cavidade para-que não você-estabelecer-se vida tsví em-terra-de vivos');
INSERT INTO verses VALUES (21190, 26, 26, 21, 'baláhoth etnék véinekh útbeqshí e-não timátséi ainda para-sempre oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (829, 26, 27, 36);
INSERT INTO verses VALUES (21191, 26, 27, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21192, 26, 27, 2, 'e-tu filho-de homem se sobre Tiro lamento:');
INSERT INTO verses VALUES (21193, 26, 27, 3, 'e-dirás létzór sobre mévoth mar mar os-povos a íyím muitos assim disse Adonai yhwh zór tu disse-te eu coroa-de beleza.');
INSERT INTO verses VALUES (21194, 26, 27, 4, 'em-o-cor mares de-tuas-fronteiras teus-construtores enrolaram tua-beleza.');
INSERT INTO verses VALUES (21195, 26, 27, 5, 'ciprestes de-oleiro e colocaram-na para-ti a todo taças-de cedro [לָקָ֔חוּ] levaram-os para-fazer [עָלָֽיִךְ] sobre-você-versículo-final');
INSERT INTO verses VALUES (21196, 26, 27, 6, '[אַלּוֹנִים֙] [מִבָּשָׁ֔ן] fizeram [מִשּׁוֹטָ֑יִךְ] [קַרְשֵׁ֤ךְ] [עָֽשׂוּ־שֵׁן֙] dente filha-de [*כתים] de-a');
INSERT INTO verses VALUES (21197, 26, 27, 7, 'seis-de em-rizoma ser foi de-tua-pluma para-ti para-ti para-sinal tchelãz e-púrpura de-a ser foi que-te-cobre');
INSERT INTO verses VALUES (21198, 26, 27, 8, 'habitantes-de Tsidon e-Arvad foram navios para-ti sábios-teus Tsor- הָ֣יוּ em-ti eles -hovelayikh-');
INSERT INTO verses VALUES (21199, 26, 27, 9, 'anciãos-de geval- -vekhameha- הָ֣יוּ em-ti machazikei- -bedeikh- todo o-mar hayyam- -malacheihem- הָ֣יוּ em-ti laarob- -maarevikh');
INSERT INTO verses VALUES (21200, 26, 27, 10, 'parás e-lud u-pút foram be-chéilekhe homens-de milchamteikhe escudo-o ve-kóvá tilu- em-ti eles eles-deram hadarekhe:');
INSERT INTO verses VALUES (21201, 26, 27, 11, 'filhos-de arvad ve-chéilekhe sobre mur-o-teu ao-redor e-gigantes em-torre-o-teu foram sua-senhoria contar-vos sobre mur-o-teu ao-redor eles reunir-se beleza-teu');
INSERT INTO verses VALUES (21202, 26, 27, 12, 'תַּרְשִׁ֥ישׁ comercio-teu de-a-quantidade-de todo hon com prata barzel com-o-divisor e-da-oferta-seu deram de-a-reserva-tua');
INSERT INTO verses VALUES (21203, 26, 27, 13, 'Iavã Tuval e-Meshech eles de-a-mercadoria-tua bênepes homem e-utensílios-de bronze deram do-o-oeste-tua');
INSERT INTO verses VALUES (21204, 26, 27, 14, 'da-casa Togarmah sussim u-parashim u-peradim deram ezvonayikh');
INSERT INTO verses VALUES (21205, 26, 27, 15, 'filhos-de dadan rochlayikh iyyim muitos sechorat yadekh cornes dente retornaram te-recompensarei');
INSERT INTO verses VALUES (21206, 26, 27, 16, 'a-r-am tu-venderás de-muitos teus-trabalhos em-tuas-plantagens púrpura e-tecido e-Buqts e-Ramot e-Kadkod deram b-ezbo-nayikh');
INSERT INTO verses VALUES (21207, 26, 27, 17, 'Judá ve-erets Israel eles roch-layikh b-chittay minnit u-Panag u-dvash e-óleo e-torrencial deram do-teu-oeste');
INSERT INTO verses VALUES (21208, 26, 27, 18, 'de-damasco teu-comércio em-muitos de-tus-teus-trabalhos de-muito todo hon em-vinho de-helbon e-lã alvorecer-.');
INSERT INTO verses VALUES (21209, 26, 27, 19, 'e-dan e-javã enrolado em-o-teu-sustento deram ferro-. fazerem queimada e-cane em-o-ma-arav-ech ser');
INSERT INTO verses VALUES (21210, 26, 27, 20, 'd-dan rochalt-e-ch be-big-dei- chofesh le-rich-bah');
INSERT INTO verses VALUES (21211, 26, 27, 21, 'tarde e-todo príncipes-de qedar eles comerciantes-de yade-ch be-char-im e-aelim e-tauros com-eles socharayikh');
INSERT INTO verses VALUES (21212, 26, 27, 22, 'rochlei sheva ve-raamah eles rochlayikh berosh todo boshem e-em-todo even yekarah e-ouro deram os-teus-almocares-verso');
INSERT INTO verses VALUES (21213, 26, 27, 23, 'Хaran e-cultivando-o e-Eden de-comerciantes de-Saba Assíria ensinando-o comerciante-te-verso');
INSERT INTO verses VALUES (21214, 26, 27, 24, 'הֵ֤מָּה teus-comerciantes em-maculados em-o-globo tecelagem-azul וְרִקְמָ֔ה e-no-ginzeiro em-o-roxo no-cordao entrelaçados e-enrolados em-a-marcheta-teu');
INSERT INTO verses VALUES (21215, 26, 27, 25, 'navios terafim cânticos-teus o-teu-oeste e-tu-cheias-te e-tu-engrandeces-te muito em-o-coração- mares');
INSERT INTO verses VALUES (21216, 26, 27, 26, 'em-a-agua רַבִּים os-trouxeram-te os-nadadores a-ti espírito do-leste o-teu-quebra em-o-cor mares');
INSERT INTO verses VALUES (21217, 26, 27, 27, 'o-teu-desprezo e-tuas-reservas teus-oeste tuas-sal e-tuas-navegadores mantenedores de-teu-exame e-de-tuas-ocasiões teus-oeste e-todo homens-de tuas-guerras que em-ti e-em-todo congregação-tua que mares cairão b-le-ve mares em-dia destruidora-tua');
INSERT INTO verses VALUES (21218, 26, 27, 28, 'à-voz-de clamor-de parturientes-tuas tremecerão de-ruínas');
INSERT INTO verses VALUES (21219, 26, 27, 29, 'e-descerão de-navios-deles todo agarradores mashot malachim todo chovelai o-mar a a-terra yaamodu');
INSERT INTO verses VALUES (21220, 26, 27, 30, 'vehishmiu sobre-ti em-a-sua-voz veyizequ מָרָ֑ה veyaalu afar sobre raashemhem baefar se-espalharão');
INSERT INTO verses VALUES (21221, 26, 27, 31, 'e-os-trarão para-ti קָרְחָ֔ה e-se-cinturarão de-sacos e-chorarão אליהיך com-a-amarração-de alma de-luto amargo');
INSERT INTO verses VALUES (21222, 26, 27, 32, 'e-elevarão a-vós filhos-deles CÂMARA e-fazem-no-os sobre ti quem como-Tsor como-Duma no-meio-de o-mar');
INSERT INTO verses VALUES (21223, 26, 27, 33, 'na saída reservas-teus de-dias satisfazeste-os povos muitos em-muitos honres-teus e-oeste-teus h''eashart reis-de terra');
INSERT INTO verses VALUES (21224, 26, 27, 34, 'eit nishv''ret miyamim bema''amakei- águas ma''aravekha e-todo kehalekha betochekha nafalu:');
INSERT INTO verses VALUES (21225, 26, 27, 35, 'todo habitantes-de ha''ayim fiquem-desolados sobre ti e-seus-reis cujos-cabelos [שַׂ֔עַר] trovejaram face');
INSERT INTO verses VALUES (21226, 26, 27, 36, 'comerciantes entre-povos rugiram sobre ti em-destruições estavam e-você-não até eternidade');
INSERT INTO chapters VALUES (830, 26, 28, 26);
INSERT INTO verses VALUES (21227, 26, 28, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21228, 26, 28, 2, 'filho-de homem disse para-governar Tsor assim disse Adonai yhwh porque גָּבַהּ E-disse e-disse El eu assento-de Elohim eu-estabeleci-me mares maria-s homem homem e-deu El e-deu לִבְּךָ֖ como-cão Elohim');
INSERT INTO verses VALUES (21229, 26, 28, 3, 'eis sábio tu todo fechado não não');
INSERT INTO verses VALUES (21230, 26, 28, 4, 'em-sua-sabedoria e-em-seu-entendimento fiz-te para ti força e-você-faz ouro e-prata em-tus-o-tesouro-s-teu-verso');
INSERT INTO verses VALUES (21231, 26, 28, 5, 'בְּרֹ֧ב a-sabedoria-teu em-a-benedicteu-teu multiplicaste a-riqueza-teu e-ele-se-alçou do-teu-cor em-a-riqueza-teu-verso');
INSERT INTO verses VALUES (21232, 26, 28, 6, 'portanto assim disse Adonai yhwh porque tu-o-dás a do-teu-cor como-cão Elohim');
INSERT INTO verses VALUES (21233, 26, 28, 7, 'portanto eis-me מביא sobre-ti estrangeiros valentes nações e-levantaram as-armas-deles sobre de-a-beleza da-sabedoria-de-você e-prostituíram a-energia-de-você');
INSERT INTO verses VALUES (21234, 26, 28, 8, 'para-a-ruína e-abater-no-você e-morreu mortes-de traspassado em-o-cor mares');
INSERT INTO verses VALUES (21235, 26, 28, 9, 'dizer-a dirás Elohim eu diante-de que-te-atinge ve-a-ta-ha homem e-não El na-mão-de profanador-te');
INSERT INTO verses VALUES (21236, 26, 28, 10, 'mortes-de uncircuncisos morrerás pela-mão-de que porque eu דִבַּ֔רְתִּי oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21237, 26, 28, 11, 'e-houve palavra-de yhwh a-mim');
INSERT INTO verses VALUES (21238, 26, 28, 12, 'filho-de homem se lamento sobre rei para-ele e-disserás disse assim disse tu yhwh tu fechamento- -técnicas enchei sabedoria e-coroa beleza:');
INSERT INTO verses VALUES (21239, 26, 28, 13, 'em-o-eden jardim- Elohim estavas todo pedra- -preciosa de-teu-adorno homem pedra- e-halom תַּרְשִׁ֥ישׁ shoham e-yashpheh safir nofekh ubarqat וְזָהָב melekhet sobre-ti uneqavekha bakh em-dia hibaraekha estabeleceram-vos-');
INSERT INTO verses VALUES (21240, 26, 28, 14, 'vós- querubim ungido [וּנְתַתִּ֗יךָ] e-te-darei בְּהַ֨ר santo-de Elohim no-meio-de em-meio-de pedras-de fogo andastes-vos-');
INSERT INTO verses VALUES (21241, 26, 28, 15, 'perfeitos tu em-caminhos-vossos de-dia que-criado-te até nimtsá sobre-ti em-ti');
INSERT INTO verses VALUES (21242, 26, 28, 16, 'em-multidão encheram teu-interior violência e-voces-pecaste e-eu-profanei-te do-monte Elohim e-destruí-te querubim querubim de-meio-de pedras-de אֵֽשׁ׃');
INSERT INTO verses VALUES (21243, 26, 28, 17, 'גָּבַהּ teu-coração na-tua-formosura voces-destruiste teu-sabedoria sobre teu-esplendor sobre terra lançaste-te diante-de reis eu-deti-te para-ter-sei em-te:');
INSERT INTO verses VALUES (21244, 26, 28, 18, 'de-muita iniquidade-tua em-putridão multidão-tua [חִלַּ֖לְתָּ] santuário-tua e-ei-saí- אֵ֤שׁ [הִ֣יא] ela eu-te-comer-ei e-eu-te-darei para-poeira sobre a-terra aos-olhos-de todo te-vejo');
INSERT INTO verses VALUES (21245, 26, 28, 19, 'todo que-te-conhece entre-os-povos eles-desolaram-se sobre-ti em-ruínas tu-foste e-ainekha até eternidade');
INSERT INTO verses VALUES (21246, 26, 28, 20, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21247, 26, 28, 21, 'filho-de homem colocar פָּנֶ֖יךָ a Tsidon e profetizarão sobre-ela');
INSERT INTO verses VALUES (21248, 26, 28, 22, 'e dirás assim disse Adonai yhwh eis-me sobre-ti Tsidon e-eu-serei-exaltado בְּתוֹכֵ֑ךְ וְיָדֻעוּ porque yhwh yhwh em-fazer-me בָ֛הּ os-julgamentos e-eu-serei-consagrado em-ela');
INSERT INTO verses VALUES (21249, 26, 28, 23, 'וְשִׁלַּחְתִּי־ nela palavra e-sangue fora-de-a-ela e-ele-será-julgado morto dentro dela be-cher-ev sobre-ela em-o-redor e-saberão yhwh eu yhwh');
INSERT INTO verses VALUES (21250, 26, 28, 24, 'e-não for ainda para-casa-de Israel silo E-espinhos e-espinho de-toda de-todo em-torno-deles os-sapos eles que porque eu Adonai yhwh');
INSERT INTO verses VALUES (21251, 26, 28, 25, 'assim disse Adonai yhwh [׀] a casa Israel de os-povos que espalharam-se neles e-santificarei-me neles aos-olhos-de as-nações e-estarão-eles-se-assentando dei sua terra que dei para-o-meu-servo a-Jacob');
INSERT INTO verses VALUES (21252, 26, 28, 26, 'e-estarão-eles-se-assentando em-a-sua em-segurança e-construíram casas e-plantaram vinhas וְיָשְׁב֖וּ em segurança em-fazer juízes em-todo os-venenosos eles ao-redor-deles e-sabem que eu yhwh אֱלֹהֵיהֶם-de-eles');
INSERT INTO chapters VALUES (831, 26, 29, 21);
INSERT INTO verses VALUES (21253, 26, 29, 1, 'b-shana a-décima em-o-dez de-dois dez para-o-mês ser palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (21254, 26, 29, 2, 'filho-de homem foi-posto perante-você sobre פַּרְעֹה rei Egito e-eis-nabear sobre-ele e-sobre Egito toda-a');
INSERT INTO verses VALUES (21255, 26, 29, 3, 'palavra e dirás assim disse Adonai yhwh eis-me sobre-ti faráoh rei-de Egito os-dragões a-grande no-meio-de em-meio-de seus-nilos disse disse para-mim meu-nilo e-eu fiz-te');
INSERT INTO verses VALUES (21256, 26, 29, 4, 'e-darei com-tua-vida e-eu-vincarei de-peixe- do-teus-riviere em-tuas-botas e-eu-elevar-te-ei de-meio-de teus-riviere e-את tudo-de de-peixe teus-riviere em-tuas-botas tu-vincarás');
INSERT INTO verses VALUES (21257, 26, 29, 5, 'e-te-nego a-mesquiteira te e-את todo peixe-de do-teu-nilo sobre face-de não cairás não serás-coletado e-não a-terra para-a-criatura a-terra e-para-o-pássaro para-alimento נְתַתִּיךָ para-alimento');
INSERT INTO verses VALUES (21258, 26, 29, 6, 'וְיָֽדְעוּ֙ וְיָדַעֻהוּ todo habitantes-de que porque yhwh yhwh יַ֧עַן serem mish''eneth qaneh segundo-casa-de Israel');
INSERT INTO verses VALUES (21259, 26, 29, 7, 'be-tafsh''am bekha ter''otz uvaq''atatha a-eles todo a-eles ube-hisha''anam sobre-ti tish''aber weha''amadatha a-eles a-eles mathnayim');
INSERT INTO verses VALUES (21260, 26, 29, 8, 'portanto assim disse Adonai yhwh הִנְנִ֛י מֵבִ֥יא sobre-ti espada וְהִכְרַתִּ֥י de-você homem וּבְהֵמָֽה׃');
INSERT INTO verses VALUES (21261, 26, 29, 9, 'e-será terra-de Mitzrayim para-desolação e-ruína e-saberão yhwh eu disse יַ֧עַן disse Yeor a-mim e-eu fiz');
INSERT INTO verses VALUES (21262, 26, 29, 10, 'por-isso eis-me a-ti e-a Yeor-de-você e-eu-darei a terra Egito para-ruínas destruição sem semear [וְעַד־גְּב֥וּל] Sveneh e-até fronteira-de Cush');
INSERT INTO verses VALUES (21263, 26, 29, 11, 'não passa- nela homem homem animal-doméstico não não passa- nela e-não habita quarenta anos');
INSERT INTO verses VALUES (21264, 26, 29, 12, 'e-darei a terra em-o-Egito no-meio-de dentro-de-a nações almas e-cidade-a-sua no-meio-de cidades destruídas ser-ás sem semear quarenta ano e-espalharei a Mitzrayim entre-as-nações e-plantearei בָּאֲרָצֽוֹת׃');
INSERT INTO verses VALUES (21265, 26, 29, 13, 'que assim disse Adonai yhwh מִקֵּ֞ץ quarenta ano aglomerarei a Egito de os-povos que espalharam-se ali');
INSERT INTO verses VALUES (21266, 26, 29, 14, 'וְשַׁבְתִּי֙ a שְׁב֣וּת Egito eles terra terra partirão sobre e-sejam de-sua-embriaguez e-serão nome reinado humilhação-verso-final');
INSERT INTO verses VALUES (21267, 26, 29, 15, 'de as-mamlekhut será שפלah e-não eleva-se ainda para-não as-nações e-afirma-os para-não dominar b-gó-i-im:');
INSERT INTO verses VALUES (21268, 26, 29, 16, 'e-não ele-será- ainda lebeith Israel para-segurança lembrando pecado em-sua-volta apos-eles que porque eu Adonai yhwh');
INSERT INTO verses VALUES (21269, 26, 29, 17, 'e-houve vinte e-sete ano no-primeiro no-primeiro para-o-mês ser palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (21270, 26, 29, 18, 'filho-de homem נובךדראתzar rei-de em-Babel fez-trabalhar a seu-exército trabalho grande a Sior todo cabeça a-ele e-todo ombro dobrado e-salário não foi para-ele e-para-o-exército-seu de-Tsor sobre o-trabalho que servo sobre-ela');
INSERT INTO verses VALUES (21271, 26, 29, 19, 'portanto assim disse Adonai yhwh eis-me deu a-Nabucodonosor rei-de Babel a terra Egito וְנָשָׂא o-exército-seu e-saque saque-seu e-roubou roubo-seu e-será salário para-o-exército');
INSERT INTO verses VALUES (21272, 26, 29, 20, 'de-sua-obra que servo dei a-ele a-ele a terra Egito que עָשׂוּ a-mim oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21273, 26, 29, 21, 'no-dia aquele farei-florescer [קֶ֙רֶן֙] para-casa-de Israel [וּלְךָ֛] darei [פִּתְחֽוֹן־פֶּ֖ה] boca entre vós e-saberão yhwh eu yhwh');
INSERT INTO chapters VALUES (832, 26, 30, 26);
INSERT INTO verses VALUES (21274, 26, 30, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21275, 26, 30, 2, 'filho-de homem e profetizará e dirás disse disse Adonai yhwh הילִילוּ [לַיּֽוֹם] [sem-traducao]');
INSERT INTO verses VALUES (21276, 26, 30, 3, 'porque dia dia dia dia dia dia [עֵ֥ת] tempo será');
INSERT INTO verses VALUES (21277, 26, 30, 4, '[וּבָאָ֥ה] espada em-Egito e-será [חַלְחָלָה֙] [בְּכ֔וּשׁ] [בִּנְפֹ֥ל] traspassado em-Egito [וְלָקְח֣וּ] [הֲמוֹנָ֔הּ] [וְנֶהֶרְס֖וּ] [יְסוֹדֹתֶֽיהָ]');
INSERT INTO verses VALUES (21278, 26, 30, 5, '[כּ֣וּשׁ] [וּפ֤וּט] [וְלוּד֙] e-todo [וְכ֔וּב] [וּבְנֵ֖י] terra terra a-aliança com-eles em-a-espada cairão');
INSERT INTO verses VALUES (21279, 26, 30, 6, 'assim disse yhwh [וְנָֽפְלוּ֙] [סֹמְכֵ֣י] Egito [וְיָרַ֖ד] orgulho [עֻזָּ֑הּ] [מִמִּגְדֹּ֣ל] [סְוֵנֵ֗ה] pela espada [יִפְּלוּ־בָ֔הּ] nela oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21280, 26, 30, 7, '[וְנָשַׁ֕מּוּ] no-meio-de nações [נְשַׁמּ֑וֹת] [וְעָרָ֕יו] em-meio-de cidades [תִּֽהְיֶֽינָה] [sem-traducao]');
INSERT INTO verses VALUES (21281, 26, 30, 8, 'e-saberão porque yhwh yhwh [בְּמִצְרַ֔יִם] fogo em-Egito todo');
INSERT INTO verses VALUES (21282, 26, 30, 9, 'no-dia aquele [יֵצְא֨וּ] [מַלְאָכִ֤ים] [מִלְּפָנַי֙] [בַּצִּ֔ים] [לְהַחֲרִ֖יד] a [בֶּ֑טַח] בטַח e-será [בָהֶם֙] [בְּי֣וֹם] em-dia-de que eis hein [sem-traducao]');
INSERT INTO verses VALUES (21283, 26, 30, 10, 'assim disse Adonai yhwh e habitar a multidão Egito em-mão Nabucadnetzar rei-de Babilônia');
INSERT INTO verses VALUES (21284, 26, 30, 11, 'ele [וְעַמּ֤וֹ] com-ele [עָרִיצֵ֣י] nações [מֽוּבָאִ֖ים] para-destruir a-terra e-levantaram as-armas-deles sobre Egito e-encheram a a-terra traspassado');
INSERT INTO verses VALUES (21285, 26, 30, 12, 'e-darei [יְאֹרִים֙] [חָֽרָבָ֔ה] [וּמָכַרְתִּ֥י] a a-terra por-mão-de terra [וּמְלֹאָהּ֙] terra [אֲנִ֥י] yhwh estrangeiros eu yhwh e eu falei:');
INSERT INTO verses VALUES (21286, 26, 30, 13, 'assim disse Adonai yhwh [גִלּוּלִ֜ים] [וְהִשְׁבַּתִּ֤י] [אֱלִילִים֙] [מִנֹּ֔ף] [וְנָשִׂ֥יא] [מֵאֶֽרֶץ־מִצְרַ֖יִם] não Egito não ele-será- ainda e-darei');
INSERT INTO verses VALUES (21287, 26, 30, 14, '[וַהֲשִׁמֹּתִי֙] a partirão e-darei fogo [וְעָשִׂ֥יתִי] [שְׁפָטִ֖ים] os-julgamentos [sem-traducao]');
INSERT INTO verses VALUES (21288, 26, 30, 15, '[וְשָׁפַכְתִּ֣י] [חֲמָתִ֔י] sobre [מָע֣וֹז] refúgio Egito vehikrati a multidão [sem-traducao]');
INSERT INTO verses VALUES (21289, 26, 30, 16, '[וְנָתַ֤תִּי] fogo em-Egito [ח֤וּל] [*תחיל] [**תָּחוּל֙] será [וְנֹ֖א] [תִּהְיֶ֣ה] inimigos-de de-dia');
INSERT INTO verses VALUES (21290, 26, 30, 17, 'bachurei aven [וּפִי־בֶ֖סֶת] [בַּחֶ֣רֶב] com-a-espada [וְהֵ֖נָּה] [בַּשְּׁבִ֥י] [תֵלַֽכְנָה] [sem-traducao]');
INSERT INTO verses VALUES (21291, 26, 30, 18, '[וּבִֽתְחַפְנְחֵס֙] escuridão o-dia [בְּשִׁבְרִי־שָׁם֙] nome a [וְנִשְׁבַּת־בָּ֖הּ] Egito [עֻזָּ֑הּ] nela orgulho [יְכַסֶּ֔נָּה] ela [בַּשְּׁבִ֥י] [תֵלַֽכְנָה]');
INSERT INTO verses VALUES (21292, 26, 30, 19, '[וְעָשִׂ֥יתִי] os-julgamentos em-Egito e-saberão porque yhwh yhwh');
INSERT INTO verses VALUES (21293, 26, 30, 20, 'e-houve com-uma dez ano no-primeiro [בְּשִׁבְעָ֣ה] para-o-mês ser palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (21294, 26, 30, 21, 'filho-de homem a [מֶֽלֶךְ־מִצְרַ֖יִם] [שָׁבָ֑רְתִּי] rei-de Egito [לָתֵ֨ת] e-eis não [חִתּ֛וּל] para-dar [לְחָזְקָ֖הּ] [לִתְפֹּ֥שׂ] [בֶּחָֽרֶב׃]');
INSERT INTO verses VALUES (21295, 26, 30, 22, 'portanto assim disse Adonai yhwh eis-me a faráoh rei-de Egito [אֶת־הַחֲזָקָ֖ה] a [וְהִפַּלְתִּ֥י] a [מִיָּדֽוֹ] e-a [sem-traducao] [sem-traducao] a a-espada imediatamente');
INSERT INTO verses VALUES (21296, 26, 30, 23, '[וַהֲפִצוֹתִ֥י] a Egito [וְזֵרִיתִ֖ם] [בָּאֲרָצֽוֹת]');
INSERT INTO verses VALUES (21297, 26, 30, 24, '[וְחִזַּקְתִּ֗י] a [מֶ֣לֶךְ] rei Babilônia e-darei a espada-meu na-sua-mão [פַּרְעֹ֔ה] a [נַאֲק֥וֹת] Faraó [לְפָנָֽיו] [sem-traducao] traspassado diante-de-ele');
INSERT INTO verses VALUES (21298, 26, 30, 25, '[וְהַחֲזַקְתִּ֗י] a [מֶ֣לֶךְ] rei Babilônia e-os-bracos פַּרְעֹה [וְֽיָדְע֞וּ] וְיָדֻעוּ yhwh eu yhwh em-mi [מֶֽלֶךְ־בָּבֶ֔ל] em-mão-de rei-de Babilônia e-esticar a-ela a terra Egito');
INSERT INTO verses VALUES (21299, 26, 30, 26, '[וַהֲפִצוֹתִ֤י] a Mitzrayim entre-as-nações וְזֵרִיתִ֥י eles nas-terras e-saberão yhwh eu yhwh');
INSERT INTO chapters VALUES (833, 26, 31, 18);
INSERT INTO verses VALUES (21300, 26, 31, 1, 'e-houve com-uma dez ano [בַּשְּׁלִישִׁ֖י] no-primeiro para-o-mês ser palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21301, 26, 31, 2, 'filho-de homem disse a [וְאֶל־הֲמוֹנ֑וֹ] rei-de Egito e-a a');
INSERT INTO verses VALUES (21302, 26, 31, 3, 'eis [אַשּׁ֜וּר] [אֶ֣רֶז] no Líbano יפחה [עָנָ֛ף] [וְחֹ֥רֶשׁ] [מֵצַ֖ל] [וּגְבַ֣הּ] [קוֹמָ֑ה] e-entre [עֲבֹתִ֔ים] era [צַמַּרְתּֽוֹ]');
INSERT INTO verses VALUES (21303, 26, 31, 4, 'águas [גִּדְּל֔וּהוּ] [תְּה֖וֹם] [רֹֽמְמָ֑תְהוּ] a [הֹלֵךְ֙] andou [מַטָּעָ֔הּ] [וְאֶת־תְּעָלֹתֶ֣יהָ] e-[OBJ] a [כָּל־עֲצֵ֥י] El todo');
INSERT INTO verses VALUES (21304, 26, 31, 5, 'sobre assim [קֹמָת֔וֹ] de-toda de-todo madeiras-de o-campo [סַֽרְעַפֹּתָ֜יו] [וַתֶּאֱרַ֧כְנָה] [*פארתו] de-ma''im muitos [רַבִּ֖ים]');
INSERT INTO verses VALUES (21305, 26, 31, 6, '[בִּסְעַפֹּתָ֤יו] [קִֽנְנוּ֙] todo ave os-céus [פֹּֽארֹתָיו֙] [יָֽלְד֔וּ] [כֹּ֖ל] animal-de vivente-de o-campo [יֵֽשְׁב֔וּ] [כֹּ֖ל] todo nações muitos');
INSERT INTO verses VALUES (21306, 26, 31, 7, '[וַיְּיִ֣ף] [בְּגָדְל֔וֹ] be-órekh [דָּֽלִיּוֹתָ֑יו] porque foi [אֶל־מַ֥יִם] a águas muitos');
INSERT INTO verses VALUES (21307, 26, 31, 8, '[אֲרָזִ֣ים] não [בְּגַן־אֱלֹהִים֒] em-para-o não [דָמוּ֙] não [וְעַרְמֹנִ֥ים] a [כְּפֹֽארֹתָ֑יו] [כָּל־עֵץ֙] não foram a-ele todo madeira em-para-o Elohim não [sem-traducao] a-ele [sem-traducao]');
INSERT INTO verses VALUES (21308, 26, 31, 9, '[יָפֶ֣ה] [עֲשִׂיתִ֔יו] [בְּרֹ֖ב] [דָּֽלִיּוֹתָ֑יו] [וַיְקַנְאֻ֙הוּ֙] todo madeiras-de [בְּגַ֥ן] que');
INSERT INTO verses VALUES (21309, 26, 31, 10, 'portanto assim disse Adonai yhwh йaан que [גָּבַ֖הְתָּ] [בְּקוֹמָ֑ה] E-colocou [צַמַּרְתּוֹ֙] a entre [וְרָ֥ם] [לְבָב֖וֹ] [בְּגָבְהֽוֹ] [sem-traducao]');
INSERT INTO verses VALUES (21310, 26, 31, 11, '[וְאֶ֨תְּנֵ֔הוּ] na-mão-de o-touro nações עָשׂוּ [יַֽעֲשֶׂה֙] a-ele [כְּרִשְׁע֖וֹ] [גֵּרַשְׁתִּֽהוּ]');
INSERT INTO verses VALUES (21311, 26, 31, 12, '[וַיִּכְרְתֻ֧הוּ] [זָרִ֛ים] [עָרִיצֵ֥י] [גוֹיִ֖ם] [וַֽיִּטְּשֻׁ֑הוּ] a [וּבְכָל־גֵּ֨אָי֜וֹת] e-em-todo [דָלִיּוֹתָ֗יו] caíram [פֹֽארֹתָיו֙] [בְּכֹל֙] [אֲפִיקֵ֣י] a-terra [וַיֵּרְד֧וּ] a-terra [כָּל־עַמֵּ֥י] a-terra todo a-terra');
INSERT INTO verses VALUES (21312, 26, 31, 13, 'sobre [יִשְׁכְּנ֖וּ] [כָּל־ע֣וֹף] todo ave os-céus e-a animal-de foram todo vivente-de o-campo');
INSERT INTO verses VALUES (21313, 26, 31, 14, '[לְמַ֡עַן] que não [בְקוֹמָתָ֜ם] [כָּל־עֲצֵי־מַ֗יִם] todo madeiras-de águas e-não darão a [בְּגָבְהָ֖ם] a entre [כִּֽי־כֻלָּם֩] e-não [לַמָּ֜וֶת] [אֶל־אֶ֣רֶץ] [תַּחְתִּ֗ית] no-meio-de [בְּנֵ֥י] homem porque [בֽוֹר׃] a terra filhos-de homem a');
INSERT INTO verses VALUES (21314, 26, 31, 15, 'assim disse Adonai yhwh no-dia [שְׁא֙וֹלָה֙] [הֶאֱבַ֜לְתִּי] [כִּסֵּ֤תִי] [עָלָיו֙] sobre-ele a abismo [וַיִּכָּלְא֖וּ] águas [רַבִּ֑ים] águas muitos [לְבָנ֔וֹן] sobre-ele [הַשָּׂדֶ֖ה] e-todo de troncos de o-campo sobre-ele [sem-traducao]');
INSERT INTO verses VALUES (21315, 26, 31, 16, 'מִקּ֤וֹל [מַפַּלְתּוֹ֙] [הִרְעַ֣שְׁתִּי] nações [בְּהוֹרִדִ֥י] ele [שְׁא֖וֹלָה] a [ב֑וֹר] [וַיִּנָּ֨חֲמ֜וּ] [בְּאֶ֤רֶץ] em-a-terra [כָּל־עֲצֵי־עֵ֔דֶן] todo madeiras-de Éden mivchar [sem-traducao] לבanon todo [sem-traducao] águas');
INSERT INTO verses VALUES (21316, 26, 31, 17, 'também Eles [יָרְד֥וּ] desceram [אֶל־חַלְלֵי־חָ֑רֶב] a traspassados-de espada no-meio-de viveram [sem-traducao] no-meio-de goyim:');
INSERT INTO verses VALUES (21317, 26, 31, 18, 'a [דָמִ֥יתָ] [כָּ֛כָה] assim [וּבְגֹ֖דֶל] [בַּעֲצֵי־עֵ֑דֶן] [וְהוּרַדְתָּ֨] [אֶת־עֲצֵי־עֵ֜דֶן] [אֶל־אֶ֣רֶץ] a no-meio-de éden a terra ele [פַרְעֹה֙] [וְכָל־הֲמוֹנֹ֔ה] [נְאֻ֖ם] a traspassados-de espada ser Pharaoh e-todo [sem-traducao] oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (834, 26, 32, 32);
INSERT INTO verses VALUES (21318, 26, 32, 1, 'e-houve nas duas dez ano [בִּשְׁנֵי־עָשָׂ֥ר] dez novo no-primeiro ser foi palavra-de dizendo a-mim para-dizer');
INSERT INTO verses VALUES (21319, 26, 32, 2, 'filho-de homem [קִינָה֙] lamento sobre faráoh a-ele Egito e-dirás para-ele כּ-פִ֥יר nações [בַּיַּמִּ֔ים] e-tu [בְּנַהֲרוֹתֶ֗יךָ] nos-mares [בְּרַגְלֶ֔יךָ] [וַתִּרְפֹּ֖ס] [נַהֲרוֹתָֽם] águas em-tu-pés [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21320, 26, 32, 3, 'assim disse Adonai yhwh uferashshi sobre-ti a 里斯תּי no convés povos muitos [בְּחֶרְמִֽי] [sem-traducao]');
INSERT INTO verses VALUES (21321, 26, 32, 4, 'e-te-nego na-terra sobre face-de o-campo [וְהִשְׁכַּנְתִּ֤י] [עָלֶ֙יךָ֙] sobre-ti todo ave os-céus animal-de de-vós vivente-de todo a-terra');
INSERT INTO verses VALUES (21322, 26, 32, 5, 'e-darei a basar-ka sobre [הַגֵּאָי֖וֹת] [רָמוּתֶֽךָ] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21323, 26, 32, 6, '[וְהִשְׁקֵיתִ֨י] terra [צָפָתְךָ֛] [מִדָּמְךָ֖] a [וַאֲפִקִ֖ים] [יִמָּלְא֥וּן] [מִמֶּֽךָּ]');
INSERT INTO verses VALUES (21324, 26, 32, 7, '[וְכִסֵּיתִ֤י] [בְכַבּֽוֹתְךָ֙] céus [וְהִקְדַּרְתִּ֖י] a [שֶׁ֚מֶשׁ] [בֶּעָנָ֣ן] [אֲכַסֶּ֔נּוּ] [וְיָרֵ֖חַ] [לֹא־יָאִ֥יר] não');
INSERT INTO verses VALUES (21325, 26, 32, 8, 'todo luz luz em-os-céus [עָלֶ֑יךָ] sobre-ti [חֹ֙שֶׁךְ֙] escuridão sobre tua-terra oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21326, 26, 32, 9, '[וְהִ֨כְעַסְתִּ֔י] coração povos muitos [בַּהֲבִיאִ֤י] [שִׁבְרְךָ֙] entre-as-nações sobre [אֲשֶׁ֥ר] que não');
INSERT INTO verses VALUES (21327, 26, 32, 10, '[וַהֲשִׁמּוֹתִ֨י] sobre ti povos muitos e-seus-reis [יִשְׂעֲר֤וּ] sobre-ti [שַׂ֔עַר] [בְּעוֹפְפִ֥י] espada-meu sobre peneyhem [לִרְגָעִים֙] [אִ֣ישׁ] homem [בְּי֖וֹם] em-dia [sem-traducao]');
INSERT INTO verses VALUES (21328, 26, 32, 11, 'que assim disse Adonai yhwh espada rei-de Babel');
INSERT INTO verses VALUES (21329, 26, 32, 12, '[בְּחַרְב֤וֹת] [גִּבּוֹרִים֙] [אַפִּ֣יל] [הֲמוֹנֶ֔ךָ] [עָרִיצֵ֥י] [גוֹיִ֖ם] [כֻּלָּ֑ם] [וְשָֽׁדְדוּ֙] a orgulho Egito [כָּל־הֲמוֹנָֽהּ] todo');
INSERT INTO verses VALUES (21330, 26, 32, 13, '[וְהַֽאֲבַדְתִּי֙] a de-cima-de águas de-sobre águas muitos e-não [ע֔וֹד] regel- animal-doméstico não [תִדְלָחֵֽם] animal não [sem-traducao]');
INSERT INTO verses VALUES (21331, 26, 32, 14, 'então [אַשְׁקִ֣יעַ] [מֵֽימֵיהֶ֔ם] [וְנַהֲרוֹתָ֖ם] [כַּשֶּׁ֣מֶן] [אוֹלִ֑יךְ] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21332, 26, 32, 15, '[בְּתִתִּי֩] a terra Egito שְׁמָמָ֣ה terra terra de-sua-plenitude [אֶת־כָּל־י֣וֹשְׁבֵי] a todo [כִּֽי־אֲנִ֥י] yhwh e-saberão porque eu yhwh');
INSERT INTO verses VALUES (21333, 26, 32, 16, '[קִינָ֥ה] ela [וְק֣וֹנְנ֔וּהָ] filhas-de as-nações [תְּקוֹנֵ֣נָּה] [אוֹתָ֑הּ] sobre [וְעַל־כָּל־הֲמוֹנָהּ֙] e-sobre todo [נְאֻ֖ם] [Adonai] ela oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21334, 26, 32, 17, 'e-houve nas duas dez ano [בַּחֲמִשָּׁ֥ה] dez para-o-mês ser palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (21335, 26, 32, 18, 'filho-de homem [עַל־הֲמ֥וֹן] sobre [וְהוֹרִדֵ֑הוּ] Egito [וּבְנ֨וֹת] [גּוֹיִ֧ם] [אַדִּרִ֛ם] [אֶל־אֶ֥רֶץ] [תַּחְתִּיּ֖וֹת] a terra a');
INSERT INTO verses VALUES (21336, 26, 32, 19, '[מִמִּ֖י] [נָעָ֑מְתָּ] dominai [וְהָשְׁכְּבָ֖ה] a');
INSERT INTO verses VALUES (21337, 26, 32, 20, 'no-meio-de traspassados-de espada espada chēreb [מָשְׁכ֥וּ] [אוֹתָ֖הּ] a-ela e-todo [sem-traducao]');
INSERT INTO verses VALUES (21338, 26, 32, 21, '[יְדַבְּרוּ־ל֞וֹ] a-ele [גִבּוֹרִ֛ים] [מִתּ֥וֹךְ] de-meio sepulcro a [שָׁכְב֥וּ] [הָעֲרֵלִ֖ים] שכבו [sem-traducao] traspassados-de espada');
INSERT INTO verses VALUES (21339, 26, 32, 22, 'nome ʾaššur e-todo [סְבִֽיבוֹתָ֖יו] [קִבְרֹתָ֑יו] [כֻּלָּ֣ם] כֻּלּם [הַנֹּפְלִ֖ים] [בֶּחָֽרֶב] pela-espada');
INSERT INTO verses VALUES (21340, 26, 32, 23, 'que [נִתְּנ֤וּ] [קִבְרֹתֶ֙יהָ֙] [בְּיַרְכְּתֵי־ב֔וֹר] e-houve E-foi [סְבִיב֖וֹת] [קְבֻרָתָ֑הּ] [כֻּלָּ֤ם] [חֲלָלִים֙] [נֹפְלִ֣ים] caindo-s [אֲשֶׁר־נָתְנ֥וּ] que eles-deram vida em-terra-de vivos');
INSERT INTO verses VALUES (21341, 26, 32, 24, 'nome [עֵילָם֙] e-todo [סְבִיב֖וֹת] [קְבֻרָתָ֑הּ] [כֻּלָּ֣ם] [חֲלָלִים֩] [הַנֹּפְלִ֨ים] [בַּחֶ֜רֶב] [אֲ‍ֽשֶׁר־יָרְד֥וּ] que [׀] [אֶל־אֶ֣רֶץ] a terra [נָתְנ֤וּ] que [בְּאֶ֣רֶץ] vida em-terra-de viventes e-levantaram [בֽוֹר] a');
INSERT INTO verses VALUES (21342, 26, 32, 25, 'no-meio-de [חֲ֠לָלִים] [נָתְנ֨וּ] [מִשְׁכָּ֥ב] a-ela em-todo [סְבִֽיבוֹתָ֖יו] [קִבְרֹתֶ֑הָ] [כֻּלָּ֣ם] כֻּלּם [חַלְלֵי־חֶ֡רֶב] traspassados-de [חִתִּיתָ֜ם] porque vida [וַיִּשְׂא֤וּ] em-terra-de [אֶת־י֣וֹרְדֵי] וַיִּשְׂא֤וּ no-meio-de a [נִתָּֽן] e-houve no-meio-de traspassados deu');
INSERT INTO verses VALUES (21343, 26, 32, 26, 'nome [מֶ֤שֶׁךְ] Tuval e-todo [סְבִֽיבוֹתָ֖יו] [קִבְרוֹתֶ֑יהָ] [כֻּלָּ֤ם] [עֲרֵלִים֙] [מְחֻ֣לְלֵי] espada espada porque eles-deram vida em-terra-de vivos');
INSERT INTO verses VALUES (21344, 26, 32, 27, 'e-não [יִשְׁכְּבוּ֙] a guerreiros [מֵעֲרֵלִ֑ים] [אֲשֶׁ֣ר] que [בִּכְלֵֽי־מִלְחַמְתָּם֩] sho''al [אֶת־חַרְבוֹתָ֜ם] debaixo va-yittenu a [עֲוֺֽנֹתָם֙] em-lugar-de [כִּֽי־חִתִּ֥ית] e-foi [בְּאֶ֥רֶץ] vida [sem-traducao] porque [sem-traducao] [sem-traducao] em-terra-de vivos');
INSERT INTO verses VALUES (21345, 26, 32, 28, 'e-tu no-meio-de uncircuncisos [תִּשָּׁבַ֥ר] [וְתִשְׁכַּ֖ב] a traspassados-de espada');
INSERT INTO verses VALUES (21346, 26, 32, 29, 'שָׁ֣מָּה Edom [מְלָכֶ֙יהָ֙] e-todo [אֲשֶׁר־נִתְּנ֥וּ] que [אֶת־חַלְלֵי־חָ֑רֶב] [הֵ֛מָּה] a traspassados-de espada elas a [sem-traducao] [sem-traducao] e-a [sem-traducao] בֽוֹר׃');
INSERT INTO verses VALUES (21347, 26, 32, 30, '[שָׁ֣מָּה] [נְסִיכֵ֥י] [צָפ֛וֹן] [כֻּלָּ֖ם] e-todo [אֲשֶׁר־יָרְד֣וּ] que [בְּחִתִּיתָ֤ם] a traspassados [וַיִּשְׁכְּב֤וּ] [עֲרֵלִים֙] [אֶת־חַלְלֵי־חֶ֔רֶב] [וַיִּשְׂא֥וּ] [כְלִמָּתָ֖ם] a [בֽוֹר] a');
INSERT INTO verses VALUES (21348, 26, 32, 31, 'elas virão-ve: פַּרְעֹה [וְנִחַ֖ם] sobre todo traspassados-de espada faráoh e-todo חֵיל֔וֹ oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21349, 26, 32, 32, 'porque dei a em-terra-de vida [וְהֻשְׁכַּב֩] no-meio-de [עֲרֵלִ֜ים] a traspassados-de espada Faraó e-todo [יְהוִֽה׃] oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (835, 26, 33, 33);
INSERT INTO verses VALUES (21350, 26, 33, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21351, 26, 33, 2, 'filho-de homem palavra a filhos-de terra e-dirás a-eles terra porque levarei sobre-ela um [מִקְצֵיהֶ֔ם] com ele a-eles um [sem-traducao] e-dê-los a-ele a-eles [sem-traducao]');
INSERT INTO verses VALUES (21352, 26, 33, 3, '[וְרָאָ֥ה] a a-espada veio-a sobre a-terra [וְהִזְהִ֥יר] na-trombeta [sem-traducao] a o-povo');
INSERT INTO verses VALUES (21353, 26, 33, 4, '[וְשָׁמַ֨ע] [הַשֹּׁמֵ֜עַ] a voz [וְלֹ֣א] e-não [וַתָּ֥בוֹא] espada espada [דָּמ֥וֹ] sangue-seu será será');
INSERT INTO verses VALUES (21354, 26, 33, 5, 'את voz [הַשּׁוֹפָ֤ר] ouviu e-não [נִזְהָ֔ר] [דָּמ֖וֹ] nele será e-ele [נִזְהָ֖ר] נַפְשׁוֹ [מִלֵּֽט]');
INSERT INTO verses VALUES (21355, 26, 33, 6, '[וְ֠הַצֹּפֶה] porque [אֶת־הַחֶ֜רֶב] a [וְלֹֽא־תָקַ֤ע] [בַּשּׁוֹפָר֙] e-não [לֹֽא־נִזְהָ֔ר] [וַתָּב֣וֹא] espada e-tomou [מֵהֶ֖ם] e-veio ele [בַּעֲוֺנ֣וֹ] deles alma ele [אֶדְרֹֽשׁ׃] [sem-traducao] [sem-traducao] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21356, 26, 33, 7, 'e-tu filho-de homem [נְתַתִּ֖יךָ] eu-deti-te para-casa-de Israel [מִפִּי֙] [דָּבָ֔ר] palavra eles eles de-mim');
INSERT INTO verses VALUES (21357, 26, 33, 8, '[בְּאָמְרִ֣י] [לָרָשָׁ֗ע] רָשָׁע֙ morrendo morrerás e-não [דִבַּ֔רְתָּ] [לְהַזְהִ֥יר] [רָשָׁ֖ע] [מִדַּרְכּ֑וֹ] ele רָשָׁע֙ [בַּעֲוֺנ֣וֹ] [יָמ֔וּת] [וְדָמ֖וֹ] da tua mão אֲבַקֵּֽשׁ׃');
INSERT INTO verses VALUES (21358, 26, 33, 9, '[וְ֠אַתָּה] porque [רָשָׁ֤ע] [מִדַּרְכּוֹ֙] [לָשׁ֣וּב] para-voltar [וְלֹא־שָׁ֖ב] e-não ele [בַּעֲוֺנ֣וֹ] ele [וְאַתָּ֖ה] [נַפְשְׁךָ֥] e-tu');
INSERT INTO verses VALUES (21359, 26, 33, 10, 'e-tu filho-de homem disse a casa Israel dizendo [כִּֽי־פְשָׁעֵ֥ינוּ] dizendo porque [וּבָ֛ם] [אֲנַ֥חְנוּ] sobre-nós [וְאֵ֥יךְ] nós');
INSERT INTO verses VALUES (21360, 26, 33, 11, 'disse a-eles vive [׀] [נְאֻ֣ם] Adonai yhwh se desejo em-morte-de [הָרָשָׁ֔ע] que se [רָשָׁ֛ע] [מִדַּרְכּ֖וֹ] [וְחָיָ֑ה] [שׁ֣וּבוּ] שׁ֣וּבוּ [מִדַּרְכֵיכֶ֧ם] [הָרָעִ֛ים] [וְלָ֥מָּה] e-porque [בֵּ֥ית] casa Israel');
INSERT INTO verses VALUES (21361, 26, 33, 12, 'e-tu filho-de homem disse a filhos-de não [תַצִּילֶ֙נּוּ֙] [בְּי֣וֹם] não [וְרִשְׁעַ֤ת] em-dia-de [לֹֽא־יִכָּ֣שֶׁל] [בָּ֔הּ] [בְּי֖וֹם] não [מֵֽרִשְׁע֑וֹ] em-ela não [יוּכַ֛ל] [לִֽחְי֥וֹת] [בָּ֖הּ] não [חֲטֹאתֽוֹ]');
INSERT INTO verses VALUES (21362, 26, 33, 13, '[בְּאָמְרִ֤י] [לַצַּדִּיק֙] חָיֹ֣ה יִֽחְיֶ֔ה e-ele בָּטַח sobre [עָ֑וֶל] ואsha [**צִדְקֹתָיו֙] não não ser-lembrada [אֲשֶׁר־עָשָׂ֖ה] que fez será não');
INSERT INTO verses VALUES (21363, 26, 33, 14, '[וּבְאָמְרִ֥י] [לָֽרָשָׁ֖ע] morrendo morrerás וְשָׁב֙ [מֵֽחַטָּאת֔וֹ] e fez juízo e justiça');
INSERT INTO verses VALUES (21364, 26, 33, 15, '[חֲבֹ֨ל] restituir-vos-irá רָשָׁע֙ [גְּזֵלָ֣ה] pagará [בְּחֻקּ֤וֹת] a-vida andar para-não fazer [עָ֑וֶל] חַיֹּו viverá não morra');
INSERT INTO verses VALUES (21365, 26, 33, 16, 'todo que חָ-טָא não não a-ele a-ele e-justiça fez חַיֹּו viverá:');
INSERT INTO verses VALUES (21366, 26, 33, 17, '[וְאָמְרוּ֙] filhos-de o-povo-tuo não será estabelecido o-caminho-de Adonai e-eles [דַּרְכָּ֥ם] não יתַכֵּן׃');
INSERT INTO verses VALUES (21367, 26, 33, 18, 'quando voltar- justo [וְעָ֣שָׂה] ואsha [וּמֵ֖ת] e morrerá neles');
INSERT INTO verses VALUES (21368, 26, 33, 19, '[וּבְשׁ֤וּב] רָשָׁע֙ [מֵֽרִשְׁעָת֔וֹ] e fez juízo e justiça sobre-eles ele viverá:');
INSERT INTO verses VALUES (21369, 26, 33, 20, 'e-vós-direis não será estabelecido o-caminho-de Adonai homem [כִּדְרָכָ֛יו] [אֶשְׁפּ֥וֹט] vos casa Israel');
INSERT INTO verses VALUES (21370, 26, 33, 21, 'e-houve [בִּשְׁתֵּ֧י] dez ano [בָּעֲשִׂרִ֛י] [בַּחֲמִשָּׁ֥ה] [לַחֹ֖דֶשׁ] [לְגָלוּתֵ֑נוּ] [בָּא־אֵלַ֨י] [הַפָּלִ֧יט] [מִירוּשָׁלַ֛͏ִם] dizendo para-dizer [הָעִֽיר]');
INSERT INTO verses VALUES (21371, 26, 33, 22, 'e a mão- era foi a-mim [לִפְנֵי֙] trazer vem o-fugitivo e-abriu a [אֵלַ֖י] até vir para-mim no-manhã [נֶאֱלַ֖מְתִּי] [עֽוֹד׃] e-não [sem-traducao] ainda');
INSERT INTO verses VALUES (21372, 26, 33, 23, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21373, 26, 33, 24, 'filho-de homem [הֶחֳרָב֨וֹת] [הָאֵ֜לֶּה] ha-eleh sobre terra-de dizendo um ser um foi Abraão [וַאֲנַ֣חְנוּ] a a-terra e-nós a-terra para-nós foram-dadas a-terra para-herança');
INSERT INTO verses VALUES (21374, 26, 33, 25, 'portanto disse a-eles assim disse Adonai yhwh sobre [׀] [תֹּאכֵ֛לוּ] [וְעֵינֵכֶ֛ם] [תִּשְׂא֥וּ] a [וְדָ֣ם] וְדָם E-a-terra [תִּירָֽשׁוּ] [sem-traducao]');
INSERT INTO verses VALUES (21375, 26, 33, 26, '[עֲמַדְתֶּ֤ם] sobre [עֲשִׂיתֶ֣ן] [תּוֹעֵבָ֔ה] [וְאִ֛ישׁ] [אֶת־אֵ֥שֶׁת] a mulher-de E-a-terra [תִּירָֽשׁוּ׃]');
INSERT INTO verses VALUES (21376, 26, 33, 27, 'assim [אֲלֵהֶ֜ם] a-eles assim disse Adonai yhwh vive אני se não que [עַל־פְּנֵ֣י] com-a-espada cairão e-que sobre face-de o-campo [וּבַמְּעָר֖וֹת] eu-o-deti para-a-comer [sem-traducao] [sem-traducao] [sem-traducao] [sem-traducao] יָמֽוּתוּ׃');
INSERT INTO verses VALUES (21377, 26, 33, 28, 'e-darei a a-terra שְׁמָמָ֣ה [וְנִשְׁבַּ֖ת] [גְּא֣וֹן] orgulho [וְשָֽׁמְמ֛וּ] [הָרֵ֥י] montes-de Israel sem [sem-traducao]');
INSERT INTO verses VALUES (21378, 26, 33, 29, 'e-saberão porque yhwh yhwh em-mi a a-terra sobre [כָּל־תּוֹעֲבֹתָ֖ם] sobre todo [sem-traducao] que fizeram');
INSERT INTO verses VALUES (21379, 26, 33, 30, 'e-tu filho-de homem filhos-de o-teu-povo [בְּךָ֙] be-ka junto-a [וּבְפִתְחֵ֖י] [הַבָּתִּ֑ים] [וְדִבֶּר־חַ֣ד] e-ele-falará- [אִ֤ישׁ] a dizendo homem a seu-irmao dizendo [הַיּוֹצֵ֖א] por-favor yhwh que a-palavra [sem-traducao] de-a yhwh');
INSERT INTO verses VALUES (21380, 26, 33, 31, '[וְיָב֣וֹאוּ] [אֵ֠לֶיךָ] [כִּמְבוֹא־עָ֞ם] povo e se assentarão diante-de-ti povo-meu [אֶת־דְּבָרֶ֔יךָ] a não [יַֽעֲשׂ֑וּ] não [בְּפִיהֶם֙] porque [עֹשִׂ֔ים] [אַחֲרֵ֥י] eles fazendo atrás-de [sem-traducao] seus corações andou');
INSERT INTO verses VALUES (21381, 26, 33, 32, '[וְהִנְּךָ֤] a-eles [כְּשִׁ֣יר] [עֲגָבִ֔ים] יפחה voz [וּמֵטִ֣ב] [נַגֵּ֑ן] [וְשָֽׁמְעוּ֙] a devarêchá [אֵינָ֖ם] [אוֹתָֽם] a-eles');
INSERT INTO verses VALUES (21382, 26, 33, 33, '[וּבְבֹאָ֑הּ] eis BA''AH'' e-sabem que profeta ser no vosso');
INSERT INTO chapters VALUES (836, 26, 34, 31);
INSERT INTO verses VALUES (21383, 26, 34, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21384, 26, 34, 2, 'filho-de homem e-foi-proclamado sobre [הִנָּבֵ֣א] Israel e-foi-proclamado [לָרֹעִ֜ים] [כֹּ֥ה] disse assim disse Adonai yhwh [רֹעֵֽי־יִשְׂרָאֵל֙] [אֲשֶׁ֤ר] Israel que foram רֹעִים a-eles não o-rebanho [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21385, 26, 34, 3, 'a o-gordura [וְאֶת־הַצֶּ֣מֶר] e-a [הַבְּרִיאָ֖ה] [תִּזְבָּ֑חוּ] [הַצֹּ֖אן] não a-o-rebanho não [sem-traducao]');
INSERT INTO verses VALUES (21386, 26, 34, 4, 'a não não [וְאֶת־הַחוֹלָ֣ה] e-[OBJ] [וְלַנִּשְׁבֶּ֙רֶת֙] não [חֲבַשְׁתֶּ֔ם] [וְאֶת־הַנִּדַּ֙חַת֙] não [הֲשֵׁבֹתֶ֔ם] e-[OBJ] não não [וּבְחָזְקָ֛ה] e-[OBJ] eles não');
INSERT INTO verses VALUES (21387, 26, 34, 5, '[וַתְּפוּצֶ֖ינָה] מִבְּלִֽי o pastor [וַתִּהְיֶ֧ינָה] para-alimento para-todo vivente-de o-campo [sem-traducao]');
INSERT INTO verses VALUES (21388, 26, 34, 6, '[יִשְׁגּ֤וּ] [צֹאנִי֙] em-todo [וְעַ֖ל] e-sobre todo גִּבְעָ֣ה [כָּל־פְּנֵ֤י] a-terra todo face-de a-terra espalharam-se [וְאֵ֥ין] e-não-há [sem-traducao] e-não-há [sem-traducao]');
INSERT INTO verses VALUES (21389, 26, 34, 7, 'por-isso pastores ouvi a yhwh yhwh');
INSERT INTO verses VALUES (21390, 26, 34, 8, 'vive [נְאֻ֣ם] [׀] Adonai yhwh se não porque ser- [לָבַ֡ז] [וַתִּֽהְיֶינָה֩] [צֹאנִ֨י] para-alimento [לְכָל־חַיַּ֤ת] para-todo animal-de o-campo de-sem [רֹעַ֖י] e-não [וַיִּרְע֤וּ] meus-ovelheiros a [וְאֶת־צֹאנִ֖י] não [רָעֽוּ׃] a-eles e-a [sem-traducao] não [sem-traducao]');
INSERT INTO verses VALUES (21391, 26, 34, 9, 'portanto HA''REI''IM ouvi palavra-de yhwh');
INSERT INTO verses VALUES (21392, 26, 34, 10, 'assim disse Adonai yhwh eis-me a ha-ro''im [מִיָּדָ֗ם] a [מֵרְע֣וֹת] de-mãos-eles [וְלֹא־יִרְע֥וּ] [ע֛וֹד] rebanho e-não [וְהִצַּלְתִּ֤י] ainda os-pastores eles a-eles para-alimento [sem-traducao] e-não [sem-traducao] a-eles para-alimento');
INSERT INTO verses VALUES (21393, 26, 34, 11, 'que assim disse Adonai yhwh [הִנְנִי־אָ֕נִי] [וְדָרַשְׁתִּ֥י] [אֶת־צֹאנִ֖י] a');
INSERT INTO verses VALUES (21394, 26, 34, 12, '[כְּבַקָּרַת֩] [רֹעֶ֨ה] [עֶדְר֜וֹ] em-dia-de [בְתוֹךְ־צֹאנוֹ֙] no-meio-de צֹאנוֹ֙ [אֲבַקֵּ֣ר] assim [וְהִצַּלְתִּ֣י] a [מִכָּל־הַמְּקוֹמֹת֙] [אֲשֶׁ֣ר] [נָפֹ֣צוּ] de-todo [בְּי֖וֹם] que espalharam-se nome em-dia e-trevas');
INSERT INTO verses VALUES (21395, 26, 34, 13, '[וְהוֹצֵאתִ֣ים] de העמים [מִן־הָ֣אֲרָצ֔וֹת] de as-áreas [וּרְעִיתִים֙] a אַדְמָתָ֑ם [בָּאֲפִיקִ֕ים] a montes-de a-terra [sem-traducao] e em tudo [sem-traducao] a-terra');
INSERT INTO verses VALUES (21396, 26, 34, 14, '[בְּמִרְעֶה־טּוֹב֙] bom eles a-eles [מְרֽוֹם־יִשְׂרָאֵ֖ל] será Israel será [תִּרְבַּ֙צְנָה֙] nome [טּ֔וֹב] [וּמִרְעֶ֥ה] bom [תִּרְעֶ֖ינָה] [אֶל־הָרֵ֥י] [יִשְׂרָאֵֽל] a Israel');
INSERT INTO verses VALUES (21397, 26, 34, 15, 'eu [אֶרְעֶ֤ה] [צֹאנִי֙] e-eu [אַרְבִּיצֵ֔ם] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21398, 26, 34, 16, 'a [אֲבַקֵּשׁ֙] [וְאֶת־הַנִּדַּ֣חַת] e-[OBJ] [וְלַנִּשְׁבֶּ֣רֶת] [אֶחֱבֹ֔שׁ] [וְאֶת־הַחוֹלָ֖ה] [אֲחַזֵּ֑ק] e-[OBJ] [וְאֶת־הַחֲזָקָ֛ה] [אַשְׁמִ֖יד] e-[OBJ] [בְמִשְׁפָּֽט] e-[OBJ]');
INSERT INTO verses VALUES (21399, 26, 34, 17, '[וְאַתֵּ֣נָה] [צֹאנִ֔י] assim disse Adonai yhwh eis-me [שֹׁפֵט֙] entre [לָשֶׂ֔ה] [לָאֵילִ֖ים] [וְלָעַתּוּדִֽים]');
INSERT INTO verses VALUES (21400, 26, 34, 18, 'o-ma''at mi-kem [הַמִּרְעֶ֤ה] [הַטּוֹב֙] [תִּרְע֔וּ] וְיֶ֙תֶר֙ [מִרְעֵיכֶ֔ם] [תִּרְמְס֖וּ] [בְּרַגְלֵיכֶ֑ם] [וּמִשְׁקַע־מַ֣יִם] águas e-[OBJ] e-את [בְּרַגְלֵיכֶ֖ם] [תִּרְפֹּשֽׂוּן] [sem-traducao]');
INSERT INTO verses VALUES (21401, 26, 34, 19, '[וְצֹאנִ֑י] [מִרְמַ֤ס] [רַגְלֵיכֶם֙] [תִּרְעֶ֔ינָה] [וּמִרְפַּ֥שׂ] vosso pés [תִּשְׁתֶּֽינָה׃]');
INSERT INTO verses VALUES (21402, 26, 34, 20, 'portanto assim disse Adonai yhwh [אֲלֵיהֶ֑ם] [הִנְנִי־אָ֕נִי] [וְשָֽׁפַטְתִּי֙] [בֵּֽין־שֶׂ֣ה] entre e-entre [שֶׂ֖ה] e-entre');
INSERT INTO verses VALUES (21403, 26, 34, 21, 'porque [בְּצַ֤ד] [וּבְכָתֵף֙] [תֶּהְדֹּ֔פוּ] [וּבְקַרְנֵיכֶ֥ם] [תְּנַגְּח֖וּ] todo até até que [אוֹתָ֖נָה] [אֶל־הַחֽוּצָה] a');
INSERT INTO verses VALUES (21404, 26, 34, 22, '[וְהוֹשַׁעְתִּ֣י] [לְצֹאנִ֔י] e-não [ע֖וֹד] ainda [וְשָׁ֣פַטְתִּ֔י] entre entre [לָשֶֽׂה]');
INSERT INTO verses VALUES (21405, 26, 34, 23, 'e-elevar-ei sobre-eles רֹעֶ֤ה um וְרָעָ֣ה [אֶתְהֶ֔ן] a servo-meu David ele [יִרְעֶ֣ה] eles [וְהֽוּא־יִהְיֶ֥ה] será [לְרֹעֶֽה] [sem-traducao]');
INSERT INTO verses VALUES (21406, 26, 34, 24, 'e-eu yhwh [אֶהְיֶ֤ה] a-eles [לֵֽאלֹהִ֔ים] [וְעַבְדִּ֥י] Davi [נָשִׂ֣יא] [בְתוֹכָ֑ם] eu yhwh [דִּבַּֽרְתִּי]');
INSERT INTO verses VALUES (21407, 26, 34, 25, '[וְכָרַתִּ֤י] a-eles aliança paz [וְהִשְׁבַּתִּ֥י] [חַיָּֽה־רָעָ֖ה] maldade de a-terra [לָבֶ֔טַח] [וְיָשְׁנ֖וּ] [בַּיְּעָרִֽים]');
INSERT INTO verses VALUES (21408, 26, 34, 26, 'e-darei eles [וּסְבִיב֥וֹת] [גִּבְעָתִ֖י] [בְּרָכָ֑ה] [וְהוֹרַדְתִּ֤י] [הַגֶּ֙שֶׁם֙] [בְּעִתּ֔וֹ] [גִּשְׁמֵ֥י] [בְרָכָ֖ה] serão');
INSERT INTO verses VALUES (21409, 26, 34, 27, 'e-ele-dará árvore [הַשָּׂדֶ֜ה] a E-a-terra [תִּתֵּ֣ן] [יְבוּלָ֔הּ] e-sejam e-serão sobre [וְֽיָדְע֞וּ] [כִּי־אֲנִ֣י] yhwh porque eu yhwh [וְהִ֨צַּלְתִּ֔ים] a [הָעֹבְדִ֥ים] [בָּהֶֽם]');
INSERT INTO verses VALUES (21410, 26, 34, 28, 'e-não [ע֥וֹד] ainda [לַגּוֹיִ֔ם] [וְחַיַּ֥ת] a-terra não não [וְיָשְׁב֥וּ] [לָבֶ֖טַח] [וְאֵ֥ין] e-não-há');
INSERT INTO verses VALUES (21411, 26, 34, 29, 'e-estabelecerei a-eles [מַטָּ֖ע] [לְשֵׁ֑ם] e-não [ע֜וֹד] ainda [רָעָב֙] [בָּאָ֔רֶץ] na-terra e-não [כְּלִמַּ֥ת] ainda');
INSERT INTO verses VALUES (21412, 26, 34, 30, '[וְיָדְע֗וּ] que eu yhwh Elohim-deles [אִתָּ֑ם] e-elas meu-povo casa Israel oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21413, 26, 34, 31, '[וְאַתֵּ֥ן] [צֹאנִ֛י] rebanho [מַרְעִיתִ֖י] homem vós eu אֱלֹהִים-de-vós oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (837, 26, 35, 15);
INSERT INTO verses VALUES (21414, 26, 35, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21415, 26, 35, 2, 'filho-de homem [פָּנֶ֖יךָ] [עַל־הַ֣ר] sobre monte-de [עָלָֽיו]');
INSERT INTO verses VALUES (21416, 26, 35, 3, '[וְאָמַ֣רְתָּ] para-ele assim disse Adonai yhwh eis-me a-ti monte-de [וְנָטִ֤יתִי] [יָדִי֙] mão-minha sobre-ti [שְׁמָמָ֥ה] [וּמְשַׁמָּֽה]');
INSERT INTO verses VALUES (21417, 26, 35, 4, '[עָרֶ֙יךָ֙] [חָרְבָּ֣ה] [אָשִׂ֔ים] e-tu [שְׁמָמָ֣ה] [תִֽהְיֶ֑ה] [וְיָדַעְתָּ֖] porque yhwh yhwh');
INSERT INTO verses VALUES (21418, 26, 35, 5, 'porque estar a-ti [אֵיבַ֣ת] eternidade [וַתַּגֵּ֥ר] a filhos-de Israel sobre [בְּעֵ֖ת] espada [קֵֽץ]');
INSERT INTO verses VALUES (21419, 26, 35, 6, 'por-isso vive eu oráculo-de Adonai yhwh porque [וְדָ֣ם] [יִרְדֲּפֶ֑ךָ] [אִם־לֹ֥א] [דָ֛ם] se não [יִרְדֲּפֶֽךָ]');
INSERT INTO verses VALUES (21420, 26, 35, 7, '[וְנָֽתַתִּי֙] a monte-de Seir [וּשְׁמָמָ֑ה] [וְהִכְרַתִּ֥י] nós dele [וָשָֽׁב]');
INSERT INTO verses VALUES (21421, 26, 35, 8, '[וּמִלֵּאתִ֥י] a [חֲלָלָ֑יו] [גִּבְעוֹתֶ֤יךָ] [וְגֵאוֹתֶ֙יךָ֙] [וְכָל־אֲפִיקֶ֔יךָ] e-todo [יִפְּל֥וּ] traspassados-de espada [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21422, 26, 35, 9, '[שִֽׁמְמ֤וֹת] eternidade [אֶתֶּנְךָ֔] [וְעָרֶ֖יךָ] não [*תישבנה] porque eu yhwh');
INSERT INTO verses VALUES (21423, 26, 35, 10, '[יַ֣עַן] [אֲ֠מָרְךָ] a segundo [וְאֶת־שְׁתֵּ֧י] e-[OBJ] [לִ֥י] [תִהְיֶ֖ינָה] para-mim [וַֽיהוָ֖ה] [שָׁ֥ם] ser nome foi');
INSERT INTO verses VALUES (21424, 26, 35, 11, 'por-isso vive eu oráculo-de Adonai yhwh [כְּאַפְּךָ֙] [וּכְקִנְאָ֣תְךָ֔] [אֲשֶׁ֣ר] que [מִשִּׂנְאָתֶ֖יךָ] [בָּ֑ם] neles [בָ֖ם] neles como-que [sem-traducao]');
INSERT INTO verses VALUES (21425, 26, 35, 12, '[וְֽיָדַעְתָּ֮] porque yhwh yhwh [׀] a todo [אָמַ֛רְתָּ] que [יִשְׂרָאֵ֖ל] dizendo montes-de Israel [**שָׁמֵ֑מוּ] para-nós [נִתְּנ֖וּ] para-alimento');
INSERT INTO verses VALUES (21426, 26, 35, 13, '[וַתַּגְדִּ֤ילוּ] sobre-mim [בְּפִיכֶ֔ם] [וְהַעְתַּרְתֶּ֥ם] sobre-mim palavras-vossas eu [שָׁמָֽעְתִּי׃]');
INSERT INTO verses VALUES (21427, 26, 35, 14, 'assim disse Adonai yhwh [כִּשְׂמֹ֙חַ֙] todo a-terra [אֶעֱשֶׂה־לָּֽךְ]');
INSERT INTO verses VALUES (21428, 26, 35, 15, '[כְּשִׂמְחָ֨תְךָ֜] [לְנַחְלַ֧ת] casa-de sobre sobre que [אֶעֱשֶׂה־לָּ֑ךְ] assim [תִֽהְיֶ֤ה] para-ti [וְכָל־אֱד֣וֹם] [כֻּלָּ֔הּ] monte-de [כִּֽי־אֲנִ֥י] yhwh porque yhwh');
INSERT INTO chapters VALUES (838, 26, 36, 38);
INSERT INTO verses VALUES (21429, 26, 36, 1, 'e-tu filho-de homem [אֶל־הָרֵ֣י] a montes-de Israel [יִשְׂרָאֵ֔ל] [שִׁמְע֖וּ] Israel yhwh');
INSERT INTO verses VALUES (21430, 26, 36, 2, 'assim disse Adonai yhwh porque disse [הָאוֹיֵ֛ב] sobre-vós [הֶאָ֑ח] [וּבָמ֣וֹת] eternidade [לְמֽוֹרָשָׁ֖ה] era [לָּֽנוּ]');
INSERT INTO verses VALUES (21431, 26, 36, 3, 'portanto [הִנָּבֵ֣א] [וְאָמַרְתָּ֔] assim disse Adonai yhwh porque [בְּיַ֡עַן] [שַׁמּוֹת֩] [וְשָׁאֹ֨ף] a-vós [מִסָּבִ֗יב] [לִֽהְיוֹתְכֶ֤ם] [מֽוֹרָשָׁה֙] [לִשְׁאֵרִ֣ית] as-nações [וַתֵּֽעֲל֛וּ] sobre beira-de língua povo');
INSERT INTO verses VALUES (21432, 26, 36, 4, 'portanto montes-de Israel ouvi palavra-de Adonai yhwh assim disse Adonai yhwh [לָאֲפִיקִ֣ים] [וְלַגֵּאָי֗וֹת] [וְלֶחֳרָב֤וֹת] [הַשֹּֽׁמְמוֹת֙] [וְלֶעָרִ֣ים] [הַנֶּעֱזָב֔וֹת] [אֲשֶׁ֨ר] [הָי֤וּ] que eram [לִשְׁאֵרִ֥ית] [הַגּוֹיִ֖ם] [אֲשֶׁ֥ר] as-nações que');
INSERT INTO verses VALUES (21433, 26, 36, 5, 'portanto assim disse Adonai yhwh se não [דִבַּ֛רְתִּי] [עַל־שְׁאֵרִ֥ית] [הַגּוֹיִ֖ם] sobre [כֻּלָּ֑א] as-nações e-sobre [׀] a-eles que [בְּשִׂמְחַ֤ת] a [בִּשְׁאָ֣ט] [נֶ֔פֶשׁ] [לְמַ֥עַן] [מִגְרָשָׁ֖הּ] todo alma');
INSERT INTO verses VALUES (21434, 26, 36, 6, 'portanto [הִנָּבֵ֖א] sobre solo-de Israel [לֶהָרִ֣ים] [וְ֠לַגְּבָעוֹת] [לָאֲפִיקִ֨ים] [וְלַגֵּאָי֜וֹת] [כֹּֽה־אָמַ֣ר] assim disse Adonai yhwh eis-me [וּבַחֲמָתִי֙] [דִּבַּ֔רְתִּי] [יַ֛עַן] porque [גּוֹיִ֖ם] nações [sem-traducao]');
INSERT INTO verses VALUES (21435, 26, 36, 7, 'portanto assim disse Adonai yhwh eu [נָשָׂ֣אתִי] a [אִם־לֹ֤א] se não a-vós que [הֵ֖מָּה] [כְּלִמָּתָ֥ם] [יִשָּֽׂאוּ]');
INSERT INTO verses VALUES (21436, 26, 36, 8, '[וְאַתֶּ֞ם] [הָרֵ֤י] Israel [עַנְפְּכֶ֣ם] [תִּתֵּ֔נוּ] [וּפֶרְיְכֶ֥ם] [תִּשְׂא֖וּ] [לְעַמִּ֣י] Israel que [קֵרְב֖וּ] [לָבֽוֹא]');
INSERT INTO verses VALUES (21437, 26, 36, 9, 'que eis-me a-vós [וּפָנִ֣יתִי] a-vós [וְנֶעֱבַדְתֶּ֖ם] [וְנִזְרַעְתֶּֽם]');
INSERT INTO verses VALUES (21438, 26, 36, 10, '[וְהִרְבֵּיתִ֤י] sobre-vós homem todo casa Israel [וְנֹֽשְׁבוּ֙] [הֶֽעָרִ֔ים] as-cidades [תִּבָּנֶֽינָה]');
INSERT INTO verses VALUES (21439, 26, 36, 11, '[וְהִרְבֵּיתִ֧י] sobre-vós homem [וּבְהֵמָ֖ה] [וְרָב֣וּ] [וּפָר֑וּ] [וְהוֹשַׁבְתִּ֨י] a-vós [כְּקַדְמֽוֹתֵיכֶ֗ם] [וְהֵטִֽבֹתִי֙] [מֵרִאשֹׁ֣תֵיכֶ֔ם] [וִֽידַעְתֶּ֖ם] porque yhwh yhwh');
INSERT INTO verses VALUES (21440, 26, 36, 12, '[וְהוֹלַכְתִּי֩] [עֲלֵיכֶ֨ם] homem a povo-de-mim Israel [וְהָיִ֥יתָ] a-eles a-eles [וְלֹא־תוֹסִ֥ף] e-não [לְשַׁכְּלָֽם׃]');
INSERT INTO verses VALUES (21441, 26, 36, 13, 'assim disse Adonai yhwh porque [אֹמְרִ֣ים] a-vós [אֹכֶ֥לֶת] homem [*אתי] [**אָ֑תְּ]');
INSERT INTO verses VALUES (21442, 26, 36, 14, 'portanto homem não [ע֔וֹד] ainda não não oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21443, 26, 36, 15, 'e-não [אֵלַ֤יִךְ] [עוֹד֙] ainda [הַגּוֹיִ֔ם] as-nações [עַמִּ֖ים] não não [*וגויך] ainda não [ע֔וֹד] ainda oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21444, 26, 36, 16, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21445, 26, 36, 17, 'filho-de homem casa Israel [עַל־אַדְמָתָ֔ם] sobre [אוֹתָ֔הּ] [בְּדַרְכָּ֖ם] ela [כְּטֻמְאַת֙] [הַנִּדָּ֔ה] era [דַרְכָּ֖ם] [לְפָנָֽי]');
INSERT INTO verses VALUES (21446, 26, 36, 18, '[וָאֶשְׁפֹּ֤ךְ] minha-furia sobre-eles sobre [אֲשֶׁר־שָׁפְכ֣וּ] que [וּבְגִלּוּלֵיהֶ֖ם] sobre a-terra [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21447, 26, 36, 19, '[וָאָפִ֤יץ] eles entre-as-nações [וַיִּזָּר֖וּ] [בָּאֲרָצ֑וֹת] [כְּדַרְכָּ֥ם] [וְכַעֲלִילוֹתָ֖ם] [שְׁפַטְתִּֽים]');
INSERT INTO verses VALUES (21448, 26, 36, 20, 'e-veio a as-nações que vieram nome [קָדְשִׁ֑י] a a-eles [עַם־יְהוָ֣ה] Estas para-eles com yhwh');
INSERT INTO verses VALUES (21449, 26, 36, 21, '[וָאֶחְמֹ֖ל] sobre nome [אֲשֶׁ֤ר] que [בֵּ֣ית] casa Israel [אֲשֶׁר־בָּ֥אוּ] que');
INSERT INTO verses VALUES (21450, 26, 36, 22, 'portanto disse [לְבֵֽית־יִשְׂרָאֵ֗ל] Israel disse disse Adonai não não [אֲנִ֥י] eu fez casa que porque se [חִלַּלְתֶּ֔ם] [בַּגּוֹיִ֖ם] que [שָֽׁם] que nome');
INSERT INTO verses VALUES (21451, 26, 36, 23, '[וְקִדַּשְׁתִּ֞י] a [הַגָּד֗וֹל] a-grande [בַּגּוֹיִ֔ם] entre-as-nações que [בְּתוֹכָ֑ם] [וְיָדְע֨וּ] [הַגּוֹיִ֜ם] [כִּי־אֲנִ֣י] yhwh eu yhwh oráculo-de Adonai yhwh [לְעֵינֵיהֶֽם]');
INSERT INTO verses VALUES (21452, 26, 36, 24, '[וְלָקַחְתִּ֤י] vos de as-nações [אֶתְכֶ֖ם] vos de-todo as-terras [אֶל־אַדְמַתְכֶֽם] a');
INSERT INTO verses VALUES (21453, 26, 36, 25, '[וְזָרַקְתִּ֧י] [עֲלֵיכֶ֛ם] águas [טְהוֹרִ֖ים] [וּטְהַרְתֶּ֑ם] de-toda [טֻמְאוֹתֵיכֶ֛ם] [וּמִכָּל־גִּלּ֥וּלֵיכֶ֖ם] [אֲטַהֵ֥ר] [אֶתְכֶֽם]');
INSERT INTO verses VALUES (21454, 26, 36, 26, 'e-darei a-vós coração novo e-Espírito-de [חֲדָשָׁ֖ה] darei [בְּקִרְבְּכֶ֑ם] [וַהֲסִ֨רֹתִ֜י] a coração [מִבְּשַׂרְכֶ֔ם] [וְנָתַתִּ֥י] a-vós a-vós coração');
INSERT INTO verses VALUES (21455, 26, 36, 27, 'e-[OBJ] [אֶתֵּ֣ן] darei em-meio-vosso [OBJ] a que [וּמִשְׁפָּטַ֥י] [תִּשְׁמְר֖וּ] [וַעֲשִׂיתֶֽם]');
INSERT INTO verses VALUES (21456, 26, 36, 28, '[וִישַׁבְתֶּ֣ם] na-terra que dei [לַאֲבֹֽתֵיכֶ֑ם] e-sereis a-mim [לְעָ֔ם] [וְאָ֣נֹכִ֔י] estarei a-vós [לֵאלֹהִֽים]');
INSERT INTO verses VALUES (21457, 26, 36, 29, '[וְהוֹשַׁעְתִּ֣י] vos de-toda [טֻמְאֽוֹתֵיכֶ֑ם] e-chamarei a [וְהִרְבֵּיתִ֣י] ele a-ele e-não [רָעָֽב]');
INSERT INTO verses VALUES (21458, 26, 36, 30, '[וְהִרְבֵּיתִי֙] a a-árvore [וּתְנוּבַ֖ת] [הַשָּׂדֶ֑ה] o-campo para-que não não [ע֛וֹד] ainda [רָעָ֖ב] fome');
INSERT INTO verses VALUES (21459, 26, 36, 31, '[וּזְכַרְתֶּם֙] a [הָרָעִ֔ים] [וּמַעַלְלֵיכֶ֖ם] [אֲשֶׁ֣ר] que não bons sobre [עֲוֺנֹ֣תֵיכֶ֔ם] sobre [תּוֹעֲבֽוֹתֵיכֶֽם] e-sobre [sem-traducao]');
INSERT INTO verses VALUES (21460, 26, 36, 32, 'não [לְמַעַנְכֶ֣ם] eu fez oráculo-de Adonai yhwh a-vós a-vós [וְהִכָּלְמ֛וּ] [מִדַּרְכֵיכֶ֖ם] [בֵּ֥ית] casa Israel');
INSERT INTO verses VALUES (21461, 26, 36, 33, 'assim disse Adonai yhwh em-dia-de [טַהֲרִ֣י] vos de-toda [עֲוֺנֽוֹתֵיכֶ֑ם] [וְהֽוֹשַׁבְתִּי֙] a [וְנִבְנ֖וּ] [הֶחֳרָבֽוֹת]');
INSERT INTO verses VALUES (21462, 26, 36, 34, 'E-a-terra [הַנְּשַׁמָּ֖ה] [תֵּֽעָבֵ֑ד] debaixo que era [שְׁמָמָ֔ה] aos-olhos-de todo');
INSERT INTO verses VALUES (21463, 26, 36, 35, '[וְאָמְר֗וּ] a-terra [הַלֵּ֙זוּ֙] [הַנְּשַׁמָּ֔ה] era [כְּגַן־עֵ֑דֶן] [וְהֶעָרִ֧ים] [הֶחֳרֵב֛וֹת] [וְהַֽנְשַׁמּ֥וֹת] [וְהַנֶּהֱרָס֖וֹת] [בְּצוּר֥וֹת] [יָשָֽׁבוּ]');
INSERT INTO verses VALUES (21464, 26, 36, 36, '[וְיָדְע֣וּ] [הַגּוֹיִ֗ם] que [יִֽשָּׁאֲרוּ֮] [סְבִיבוֹתֵיכֶם֒] que eu yhwh yhwh [בָּנִ֙יתִי֙] [הַנֶּ֣הֱרָס֔וֹת] [נָטַ֖עְתִּי] eu yhwh yhwh [דִּבַּ֥רְתִּי]');
INSERT INTO verses VALUES (21465, 26, 36, 37, 'assim disse Adonai yhwh ainda esta [אִדָּרֵ֥שׁ] [לְבֵֽית־יִשְׂרָאֵ֖ל] Israel a-eles multiplicarei eles a-eles homem homem');
INSERT INTO verses VALUES (21466, 26, 36, 38, '[כְּצֹ֣אן] [קָֽדָשִׁ֗ים] [כְּצֹ֤אן] Jerusalém [בְּמ֣וֹעֲדֶ֔יהָ] assim [תִּהְיֶ֙ינָה֙] [הֶעָרִ֣ים] [הֶחֳרֵב֔וֹת] [מְלֵא֖וֹת] ovelhas homem e-saberão porque yhwh yhwh');
INSERT INTO chapters VALUES (839, 26, 37, 28);
INSERT INTO verses VALUES (21467, 26, 37, 1, 'era [עָלַי֮] mão-de yhwh [בְר֙וּחַ֙] yhwh yhwh no-meio-de em-meio-de [וְהִ֖יא] e-ela cheia');
INSERT INTO verses VALUES (21468, 26, 37, 2, '[וְהֶעֱבִירַ֥נִי] sobre-eles ao-redor ao-redor e-eis [וְהִנֵּ֨ה] [רַבּ֤וֹת] muito face-de [הַבִּקְעָ֔ה] [וְהִנֵּ֖ה] [יְבֵשׁ֥וֹת] muito');
INSERT INTO verses VALUES (21469, 26, 37, 3, 'E-disse a-mim filho-de homem [הָעֲצָמ֣וֹת] [הָאֵ֑לֶּה] estes [Adonai] Adonai tu tu');
INSERT INTO verses VALUES (21470, 26, 37, 4, 'E-disse a-mim [הִנָּבֵ֖א] sobre [הָאֵ֑לֶּה] estes e-dirás a-eles [הַיְבֵשׁ֔וֹת] [שִׁמְע֖וּ] ouvi palavra-de yhwh');
INSERT INTO verses VALUES (21471, 26, 37, 5, 'assim disse Adonai yhwh [לָעֲצָמ֖וֹת] estes eis eu [מֵבִ֥יא] [בָכֶ֛ם] espírito [וִחְיִיתֶֽם]');
INSERT INTO verses VALUES (21472, 26, 37, 6, '[וְנָתַתִּי֩] [עֲלֵיכֶ֨ם] [גִּדִ֜ים] [וְֽהַעֲלֵתִ֧י] [עֲלֵיכֶ֣ם] carne [וְקָרַמְתִּ֤י] sobre-vós pele e-darei [בָכֶ֛ם] espírito [וִחְיִיתֶ֑ם] [וִידַעְתֶּ֖ם] porque yhwh yhwh');
INSERT INTO verses VALUES (21473, 26, 37, 7, '[וְנִבֵּ֖אתִי] como-que [צֻוֵּ֑יתִי] e-foi voz [וְהִנֵּה־רַ֔עַשׁ] e-eis- [עֲצָמ֔וֹת] osso [אֶל־עַצְמֽוֹ] [sem-traducao] a [sem-traducao]');
INSERT INTO verses VALUES (21474, 26, 37, 8, '[וְרָאִ֜יתִי] [וְהִנֵּֽה־עֲלֵיהֶ֤ם] [גִּדִים֙] [וּבָשָׂ֣ר] subir [וַיִּקְרַ֧ם] [עֲלֵיהֶ֛ם] pele [מִלְמָ֑עְלָה] e-Espírito-de [אֵ֥ין] não-há');
INSERT INTO verses VALUES (21475, 26, 37, 9, 'E-disse a-mim [הִנָּבֵ֖א] a [הִנָּבֵ֣א] [בֶן־אָ֠דָם] filho-de homem [כֹּֽה־אָמַ֣ר] a [Adonai] assim disse Adonai yhwh [הָר֔וּחַ] [וּפְחִ֛י] [בַּהֲרוּגִ֥ים] [הָאֵ֖לֶּה] [וְיִֽחְיֽוּ] [sem-traducao] estes [sem-traducao]');
INSERT INTO verses VALUES (21476, 26, 37, 10, '[וְהִנַּבֵּ֖אתִי] como-que [צִוָּ֑נִי] [וַתָּבוֹא֩] [בָהֶ֨ם] [הָר֜וּחַ] [וַיִּֽחְי֗וּ] e-pararam sobre [חַ֖יִל] valor grande');
INSERT INTO verses VALUES (21477, 26, 37, 11, 'E-disse [אֵלַי֒] filho-de homem [הָאֵ֔לֶּה] os-estes todo casa eis [אֹמְרִ֗ים] eis [עַצְמוֹתֵ֛ינוּ] [וְאָבְדָ֥ה] [תִקְוָתֵ֖נוּ] [נִגְזַ֥רְנוּ] [לָֽנוּ]');
INSERT INTO verses VALUES (21478, 26, 37, 12, 'portanto [הִנָּבֵ֨א] [וְאָמַרְתָּ֜] a-eles assim disse Adonai eis [אֲנִ֨י] eu [אֶת־קִבְרֽוֹתֵיכֶ֗ם] a [אֶתְכֶ֛ם] [מִקִּבְרוֹתֵיכֶ֖ם] a-vós [וְהֵבֵאתִ֥י] meu-povo [אֶל־אַדְמַ֥ת] vos a solo-de Israel');
INSERT INTO verses VALUES (21479, 26, 37, 13, '[וִֽידַעְתֶּ֖ם] porque yhwh yhwh [אֶת־קִבְרֽוֹתֵיכֶ֗ם] a [אֶתְכֶ֛ם] [מִקִּבְרוֹתֵיכֶ֖ם] a-vós');
INSERT INTO verses VALUES (21480, 26, 37, 14, '[וְנָתַתִּ֨י] espírito-meu [בָכֶם֙] [וִחְיִיתֶ֔ם] [וְהִנַּחְתִּ֥י] vos sobre [וִידַעְתֶּ֞ם] [כִּי־אֲנִ֧י] yhwh eu yhwh falei [sem-traducao] oráculo-de yhwh');
INSERT INTO verses VALUES (21481, 26, 37, 15, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21482, 26, 37, 16, 'e-tu filho-de homem árvore um madeira-de um [לִֽיהוּדָ֔ה] sobre-ele [יִשְׂרָאֵ֖ל] [*חברו] Israel [וּלְקַח֙] árvore um [וּכְת֣וֹב] sobre-ele [לְיוֹסֵף֙] árvore Efraim e-todo casa Israel');
INSERT INTO verses VALUES (21483, 26, 37, 17, '[וְקָרַ֨ב] eles um a a-ti a-ti um e-sejam [לַאֲחָדִ֖ים] [בְּיָדֶֽךָ]');
INSERT INTO verses VALUES (21484, 26, 37, 18, '[וְכַֽאֲשֶׁר֙] dirão a-ti filhos-de [עַמְּךָ֖] dizendo acaso-nao [לָ֖נוּ] a-nos o-quê Estas para-ti');
INSERT INTO verses VALUES (21485, 26, 37, 19, 'palavra [אֲלֵהֶ֗ם] assim disse Adonai eis [אֲנִ֨י] [לֹקֵ֜חַ] tomou a [אֲשֶׁ֣ר] [בְּיַד־אֶפְרַ֔יִם] que pela-mão-de [*חברו] [**חֲבֵרָ֑יו] Israel [אוֹתָ֨ם] [עָלָ֜יו] sobre-ele a madeira-de Judá um e-sejam um e-serão um');
INSERT INTO verses VALUES (21486, 26, 37, 20, 'e-sejam [הָעֵצִ֜ים] que [עֲלֵיהֶ֛ם] sobre-eles [לְעֵינֵיהֶֽם]');
INSERT INTO verses VALUES (21487, 26, 37, 21, 'e-fala a-eles assim disse Adonai eis eis eu tomou a filhos-de Israel [אֲשֶׁ֣ר] as-nações que eles nome [וְהֵבֵאתִ֥י] a-elas de-ao-redor a');
INSERT INTO verses VALUES (21488, 26, 37, 22, '[וְעָשִׂ֣יתִי] eles [לְג֨וֹי] um [בָּאָ֙רֶץ֙] [בְּהָרֵ֣י] Israel [וּמֶ֧לֶךְ] um será [לְכֻלָּ֖ם] [לְמֶ֑לֶךְ] e-não ainda [לִשְׁנֵ֣י] nações e-não [יֵחָ֥צוּ] ainda [לִשְׁתֵּ֥י] [מַמְלָכ֖וֹת] ainda');
INSERT INTO verses VALUES (21489, 26, 37, 23, 'e-não [יִֽטַמְּא֣וּ] ainda [בְּגִלּֽוּלֵיהֶם֙] [וּבְשִׁקּ֣וּצֵיהֶ֔ם] [וּבְכֹ֖ל] [פִּשְׁעֵיהֶ֑ם] [וְהוֹשַׁעְתִּ֣י] eles de-toda [מוֹשְׁבֹֽתֵיהֶם֙] que [חָטְא֣וּ] em-elas [וְטִהַרְתִּ֤י] elas [וְהָיוּ־לִ֣י] a-mim [וַאֲנִ֕י] e-eu a-eles a-eles');
INSERT INTO verses VALUES (21490, 26, 37, 24, '[וְעַבְדִּ֤י] Davi rei sobre-eles [וְרוֹעֶ֥ה] um será [לְכֻלָּ֑ם] [וּבְמִשְׁפָּטַ֣י] irao [וְחֻקֹּתַ֥י] [יִשְׁמְר֖וּ] [וְעָשׂ֥וּ] a-eles');
INSERT INTO verses VALUES (21491, 26, 37, 25, '[וְיָשְׁב֣וּ] sobre a-terra dei [לְעַבְדִּ֣י] [לְיַֽעֲקֹ֔ב] [אֲשֶׁ֥ר] que habitaram nela [עָלֶ֡יהָ] [הֵ֠מָּה] [וּבְנֵיהֶ֞ם] [וּבְנֵ֤י] [בְנֵיהֶם֙] e-filhos-de [וְדָוִ֣ד] até eternidade a-eles servo-meu príncipe-de a-eles para-eternidade');
INSERT INTO verses VALUES (21492, 26, 37, 26, '[וְכָרַתִּ֤י] a-eles aliança paz [בְּרִ֥ית] eternidade será eles [וּנְתַתִּים֙] [וְהִרְבֵּיתִ֣י] a-eles [וְנָתַתִּ֧י] a [בְּתוֹכָ֖ם] [לְעוֹלָֽם]');
INSERT INTO verses VALUES (21493, 26, 37, 27, 'e-era [מִשְׁכָּנִי֙] sobre-eles [וְהָיִ֥יתִי] a-eles [לֵֽאלֹהִ֑ים] e-eles serao para-mim [sem-traducao]');
INSERT INTO verses VALUES (21494, 26, 37, 28, '[וְיָֽדְעוּ֙] as-nações que eu yhwh [מְקַדֵּ֖שׁ] a Israel [מִקְדָּשִׁ֛י] [בְּתוֹכָ֖ם] [לְעוֹלָֽם׃]');
INSERT INTO chapters VALUES (840, 26, 38, 23);
INSERT INTO verses VALUES (21495, 26, 38, 1, 'e-houve palavra-de yhwh dizendo');
INSERT INTO verses VALUES (21496, 26, 38, 2, 'filho-de homem [פָּנֶ֙יךָ֙] [אֶל־גּוֹג֙] terra [הַמָּג֔וֹג] terra [רֹ֖אשׁ] [מֶ֣שֶׁךְ] cabeça [וְהִנָּבֵ֖א] [עָלָֽיו]');
INSERT INTO verses VALUES (21497, 26, 38, 3, '[וְאָ֣מַרְתָּ֔] assim disse Adonai yhwh eis-me a-ti [גּ֔וֹג] [נְשִׂ֕יא] cabeça [מֶ֥שֶׁךְ] [וְתֻבָֽל]');
INSERT INTO verses VALUES (21498, 26, 38, 4, '[וְשׁ֣וֹבַבְתִּ֔יךָ] e-darei [חַחִ֖ים] [בִּלְחָיֶ֑יךָ] [וְהוֹצֵאתִי֩] [אוֹתְךָ֨] e-[OBJ] todo [וּפָרָשִׁ֗ים] [לְבֻשֵׁ֤י] [מִכְלוֹל֙] [כֻּלָּ֔ם] [קָהָ֥ל] [רָב֙] [צִנָּ֣ה] muito [תֹּפְשֵׂ֥י] [חֲרָב֖וֹת] [כֻּלָּֽם]');
INSERT INTO verses VALUES (21499, 26, 38, 5, '[פָּרַ֛ס] Cuxe [וּפ֖וּט] [אִתָּ֑ם] [כֻּלָּ֖ם] [מָגֵ֥ן] [וְכוֹבָֽע]');
INSERT INTO verses VALUES (21500, 26, 38, 6, '[גֹּ֚מֶר] e-todo [בֵּ֚ית] casa [יַרְכְּתֵ֥י] [צָפ֖וֹן] [וְאֶת־כָּל־אֲגַפָּ֑יו] e-[OBJ] todo [אִתָּֽךְ]');
INSERT INTO verses VALUES (21501, 26, 38, 7, '[הִכֹּן֙] [וְהָכֵ֣ן] a-ti tu e-todo [הַנִּקְהָלִ֣ים] [עָלֶ֑יךָ] sobre-ti a-eles a-eles');
INSERT INTO verses VALUES (21502, 26, 38, 8, '[מִיָּמִ֣ים] [רַבִּים֮] [תִּפָּקֵד֒] [בְּאַחֲרִ֨ית] [הַשָּׁנִ֜ים] [תָּב֣וֹא] a [אֶל־אֶ֣רֶץ] [׀] [מְשׁוֹבֶ֣בֶת] [מֵחֶ֗רֶב] [מְקֻבֶּ֙צֶת֙] muitos sobre sobre Israel que foram [לְחָרְבָּ֖ה] [תָּמִ֑יד] [וְהִיא֙] [מֵעַמִּ֣ים] [הוּצָ֔אָה] [וְיָשְׁב֥וּ] [לָבֶ֖טַח] [כֻּלָּֽם]');
INSERT INTO verses VALUES (21503, 26, 38, 9, '[וְעָלִ֙יתָ֙] [כַּשֹּׁאָ֣ה] [תָב֔וֹא] [כֶּעָנָ֛ן] [לְכַסּ֥וֹת] a-terra [תִּֽהְיֶ֑ה] tu e-todo [וְעַמִּ֥ים] [רַבִּ֖ים] muitos');
INSERT INTO verses VALUES (21504, 26, 38, 10, 'assim disse Adonai yhwh e-era em-o-dia no-dia [הַה֗וּא] [יַעֲל֤וּ] sobre teu-coração [וְחָשַׁבְתָּ֖] [מַחֲשֶׁ֥בֶת] mal');
INSERT INTO verses VALUES (21505, 26, 38, 11, '[וְאָמַרְתָּ֗] [אֶֽעֱלֶה֙] sobre terra [אָבוֹא֙] [הַשֹּׁ֣קְטִ֔ים] [יֹשְׁבֵ֖י] [לָבֶ֑טַח] [כֻּלָּ֗ם] [יֹֽשְׁבִים֙] [בְּאֵ֣ין] [חוֹמָ֔ה] [וּבְרִ֥יחַ] [וּדְלָתַ֖יִם] [אֵ֥ין] a-eles');
INSERT INTO verses VALUES (21506, 26, 38, 12, '[לִשְׁלֹ֥ל] [שָׁלָ֖ל] [וְלָבֹ֣ז] [בַּ֑ז] [לְהָשִׁ֨יב] [יָדְךָ֜] sobre [נוֹשָׁבֹ֗ת] [וְאֶל־עַם֙] e-a povo [עֹשֶׂה֙] [מִקְנֶ֣ה] fez [יֹשְׁבֵ֖י] [עַל־טַבּ֥וּר] a-terra sobre a-terra');
INSERT INTO verses VALUES (21507, 26, 38, 13, '[שְׁבָ֡א] [וּ֠דְדָן] [וְסֹחֲרֵ֨י] [תַרְשִׁ֤ישׁ] e-todo [יֹאמְר֣וּ] a-ti para-ti [שָׁלָל֙] tu tu veio [בַּ֖ז] [הִקְהַ֣לְתָּ] [קְהָלֶ֑ךָ] [לָשֵׂ֣את] [׀] prata [וְזָהָ֗ב] [לָקַ֙חַת֙] [מִקְנֶ֣ה] [וְקִנְיָ֔ן] [לִשְׁלֹ֖ל] [שָׁלָ֥ל] grande');
INSERT INTO verses VALUES (21508, 26, 38, 14, '[לָכֵן֙] [הִנָּבֵ֣א] filho-de homem e-dirás [כֹּ֥ה] disse disse Adonai yhwh [׀] no-dia aquele [בְּשֶׁ֨בֶת] [עַמִּ֧י] Israel [לָבֶ֖טַח] [תֵּדָֽע]');
INSERT INTO verses VALUES (21509, 26, 38, 15, '[וּבָ֤אתָ] [מִמְּקֽוֹמְךָ֙] [מִיַּרְכְּתֵ֣י] norte tu [וְעַמִּ֥ים] muitos contigo [רֹכְבֵ֤י] [סוּסִים֙] [כֻּלָּ֔ם] [קָהָ֥ל] grande [וְחַ֥יִל] muito');
INSERT INTO verses VALUES (21510, 26, 38, 16, '[וְעָלִ֙יתָ֙] sobre meu-povo Israel [לְכַסּ֣וֹת] a-terra a-terra [הַיָּמִ֜ים] [תִּֽהְיֶ֗ה] [וַהֲבִאוֹתִ֙יךָ֙] [עַל־אַרְצִ֔י] sobre conhecimento a-fim-de [אֹתִ֗י] [בְּהִקָּדְשִׁ֥י] a-mim [לְעֵינֵיהֶ֖ם] [גּֽוֹג׃]');
INSERT INTO verses VALUES (21511, 26, 38, 17, 'assim disse Adonai yhwh [אֲשֶׁר־דִּבַּ֜רְתִּי] [בְּיָמִ֣ים] que [בְּיַד֙] [עֲבָדַי֙] [נְבִיאֵ֣י] em-mão-de [הַֽנִבְּאִ֛ים] profetas-de Israel [שָׁנִ֑ים] [לְהָבִ֥יא] [אֹתְךָ֖] dois');
INSERT INTO verses VALUES (21512, 26, 38, 18, 'e-era em-o-dia no-dia no-dia vir trazer sobre solo-de Israel oráculo-de Adonai yhwh subirás [חֲמָתִ֖י] [בְּאַפִּֽי]');
INSERT INTO verses VALUES (21513, 26, 38, 19, '[וּבְקִנְאָתִ֥י] [בְאֵשׁ־עֶבְרָתִ֖י] [דִּבַּ֑רְתִּי] [אִם־לֹ֣א] se no-dia em-o-dia será [רַ֣עַשׁ] [גָּד֔וֹל] sobre sobre solo-de Israel');
INSERT INTO verses VALUES (21514, 26, 38, 20, '[וְרָעֲשׁ֣וּ] [מִפָּנַ֡י] [דְּגֵ֣י] o-mar e-ave os-céus [וְחַיַּ֣ת] o-campo e-todo o-réptil o-que-rasteja e-tudo o-homem e-todo o-homem a-terra sobre face-de [וְנָֽפְלוּ֙] [הַמַּדְרֵג֔וֹת] [וְכָל־חוֹמָ֖ה] [לָאָ֥רֶץ] [תִּפּֽוֹל] e-todo');
INSERT INTO verses VALUES (21515, 26, 38, 21, '[וְקָרָ֨אתִי] sobre-o para-todo espada espada oráculo-de Adonai espada espada homem [תִּֽהְיֶֽה] [sem-traducao]');
INSERT INTO verses VALUES (21516, 26, 38, 22, '[וְנִשְׁפַּטְתִּ֥י] com-ele [בְּדֶ֣בֶר] [וּבְדָ֑ם] [וְגֶ֣שֶׁם] [שׁוֹטֵף֩] [וְאַבְנֵ֨י] [אֶלְגָּבִ֜ישׁ] fogo [וְגָפְרִ֗ית] [אַמְטִ֤יר] sobre-ele e-sobre [וְעַל־עַמִּ֥ים] e-sobre [אֲשֶׁ֥ר] muitos que');
INSERT INTO verses VALUES (21517, 26, 38, 23, '[וְהִתְגַּדִּלְתִּי֙] [וְהִ֨תְקַדִּשְׁתִּ֔י] [וְנ֣וֹדַעְתִּ֔י] aos-olhos-de nações muitos e-saberão porque yhwh yhwh');
INSERT INTO chapters VALUES (841, 26, 39, 29);
INSERT INTO verses VALUES (21518, 26, 39, 1, 'e-tu filho-de homem [עַל־גּ֔וֹג] sobre [כֹּ֥ה] disse assim disse Adonai yhwh eis-me a-ti [רֹ֖אשׁ] [מֶ֥שֶׁךְ] cabeça');
INSERT INTO verses VALUES (21519, 26, 39, 2, '[וְשֹׁבַבְתִּ֙יךָ֙] [וְשִׁשֵּׁאתִ֔יךָ] [וְהַעֲלִיתִ֖יךָ] [מִיַּרְכְּתֵ֣י] norte [וַהֲבִאוֹתִ֖ךָ] sobre [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (21520, 26, 39, 3, '[וְהִכֵּיתִ֥י] [קַשְׁתְּךָ֖] da-mão-de [שְׂמֹאולֶ֑ךָ] [וְחִצֶּ֕יךָ] [מִיַּ֥ד] [יְמִינְךָ֖] [אַפִּֽיל]');
INSERT INTO verses VALUES (21521, 26, 39, 4, 'sobre [יִשְׂרָאֵ֜ל] Israel tu tu e-todo [אֲשֶׁ֣ר] [אִתָּ֑ךְ] que contigo [כָּל־כָּנָ֛ף] [וְחַיַּ֥ת] todo [נְתַתִּ֥יךָ] para-alimento');
INSERT INTO verses VALUES (21522, 26, 39, 5, 'sobre face-de o-campo que porque eu [נְאֻ֖ם] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21523, 26, 39, 6, '[וְשִׁלַּחְתִּי־אֵ֣שׁ] fogo [וּבְיֹשְׁבֵ֥י] [הָאִיִּ֖ים] [לָבֶ֑טַח] [וְיָדְע֖וּ] e-saberão yhwh yhwh');
INSERT INTO verses VALUES (21524, 26, 39, 7, 'e-[OBJ] nome [אוֹדִ֗יעַ] no-meio-de [עַמִּ֣י] meu-povo Israel e-não [ע֑וֹד] a nome-de [כִּי־אֲנִ֣י] yhwh [קָד֖וֹשׁ] as-nações porque yhwh santo');
INSERT INTO verses VALUES (21525, 26, 39, 8, 'eis [בָאָה֙] [וְנִֽהְיָ֔תָה] oráculo-de Adonai yhwh ele o-dia que [דִּבַּֽרְתִּי]');
INSERT INTO verses VALUES (21526, 26, 39, 9, '[וְֽיָצְא֞וּ] [יֹשְׁבֵ֣י] cidades-de Israel [יִשְׂרָאֵ֗ל] [וּבִעֲר֡וּ] [וְ֠הִשִּׂיקוּ] [בְּנֶ֨שֶׁק] [וּמָגֵ֤ן] [וְצִנָּה֙] [בְּקֶ֣שֶׁת] [וּבְחִצִּ֔ים] mão mão [וּבְרֹ֑מַח] [וּבִעֲר֥וּ] fogo sete dois');
INSERT INTO verses VALUES (21527, 26, 39, 10, 'e-não [עֵצִ֜ים] [מִן־הַשָּׂדֶ֗ה] de o-campo e-não que de [יְבַֽעֲרוּ־אֵ֑שׁ] porque [אֶת־שֹׁלְלֵיהֶ֗ם] [וּבָֽזְזוּ֙] fogo [נְאֻ֖ם] a [יְהוִֽה׃] [sem-traducao] a [sem-traducao] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21528, 26, 39, 11, 'e-foi [בַיּ֣וֹם] [הַה֡וּא] darei [לְגוֹג֩] [׀] nome [קֶ֜בֶר] [בְּיִשְׂרָאֵ֗ל] [גֵּ֤י] [הָעֹֽבְרִים֙] ao-oriente-de o-mar [וְחֹסֶ֥מֶת] ela a [וְקָ֣בְרוּ] [שָׁ֗ם] nome a [וְקָ֣רְא֔וּ] e-[OBJ] todo [גּֽוֹג]');
INSERT INTO verses VALUES (21529, 26, 39, 12, '[וּקְבָרוּם֙] casa Israel para-que [טַהֵ֣ר] a a-terra sete');
INSERT INTO verses VALUES (21530, 26, 39, 13, '[וְקָֽבְרוּ֙] todo a-terra a-terra a-eles a-eles dia dia [נְאֻ֖ם] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21531, 26, 39, 14, '[וְאַנְשֵׁ֨י] [תָמִ֤יד] [יַבְדִּ֙ילוּ֙] [עֹבְרִ֣ים] na-terra [מְקַבְּרִ֣ים] a [אֶת־הַנּוֹתָרִ֛ים] a a-terra sobre face-de a-terra [יַחְקֹֽרוּ]');
INSERT INTO verses VALUES (21532, 26, 39, 15, '[וְעָבְר֤וּ] [הָעֹֽבְרִים֙] na-terra [וְרָאָה֙] osso homem [וּבָנָ֥ה] [אֶצְל֖וֹ] [צִיּ֑וּן] até [קָבְר֤וּ] ele [הַֽמְקַבְּרִ֔ים] a [הֲמ֥וֹן] multidao [sem-traducao]');
INSERT INTO verses VALUES (21533, 26, 39, 16, 'e-também [שֶׁם־עִ֛יר] cidade [וְטִהֲר֥וּ] a-terra a-terra');
INSERT INTO verses VALUES (21534, 26, 39, 17, '[וְאַתָּ֨ה] filho-de homem assim disse Adonai yhwh disse [כָּל־כָּנָ֜ף] todo [׀] animal-de vivente-de o-campo [וָבֹ֙אוּ֙] [הֵאָסְפ֣וּ] [מִסָּבִ֔יב] [עַל־זִבְחִ֗י] sobre [אֲנִ֜י] que a-vós [זֶ֣בַח] a-vós sobre grande sobre [וַאֲכַלְתֶּ֥ם] Israel [וּשְׁתִ֥יתֶם] [דָּֽם] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21535, 26, 39, 18, '[בְּשַׂ֤ר] [גִּבּוֹרִים֙] [תֹּאכֵ֔לוּ] [וְדַם־נְשִׂיאֵ֥י] a-terra a-terra [אֵילִ֨ים] [כָּרִ֤ים] [וְעַתּוּדִים֙] [פָּרִ֔ים] [מְרִיאֵ֥י] [בָשָׁ֖ן] [כֻּלָּֽם]');
INSERT INTO verses VALUES (21536, 26, 39, 19, '[וַאֲכַלְתֶּם־חֵ֣לֶב] [לְשָׂבְעָ֔ה] [וּשְׁתִ֥יתֶם] [דָּ֖ם] sangue [מִזִּבְחִ֖י] [אֲשֶׁר־זָבַ֥חְתִּי] a-vós');
INSERT INTO verses VALUES (21537, 26, 39, 20, '[וּשְׂבַעְתֶּ֤ם] sobre [ס֣וּס] [וָרֶ֔כֶב] [גִּבּ֖וֹר] poderoso e-todo homem guerra oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21538, 26, 39, 21, 'e-darei a [בַּגּוֹיִ֑ם] [וְרָא֣וּ] [כָל־הַגּוֹיִ֗ם] todo [אֲשֶׁ֣ר] a [וְאֶת־יָדִ֖י] que fiz e-[OBJ] que');
INSERT INTO verses VALUES (21539, 26, 39, 22, '[וְיָֽדְעוּ֙] casa Israel que eu yhwh אֱלֹהֵיהֶם-de-eles de o-dia o-aquele');
INSERT INTO verses VALUES (21540, 26, 39, 23, '[וְיָדְע֣וּ] [הַ֠גּוֹיִם] que [בַעֲוֺנָ֞ם] [גָּל֣וּ] casa-de sobre sobre que [וָאַסְתִּ֥ר] em-mim [מֵהֶ֑ם] face-de deles [צָרֵיהֶ֔ם] em-mão-de [בַחֶ֖רֶב] [כֻּלָּֽם]');
INSERT INTO verses VALUES (21541, 26, 39, 24, '[כְּטֻמְאָתָ֥ם] [וּכְפִשְׁעֵיהֶ֖ם] [עָשִׂ֣יתִי] eles [וָאַסְתִּ֥ר] face-de de-eles');
INSERT INTO verses VALUES (21542, 26, 39, 25, 'portanto assim disse Adonai yhwh agora [אָשִׁיב֙] a Jacó [יַֽעֲקֹ֔ב] todo casa Israel [וְקִנֵּאתִ֖י] [לְשֵׁ֥ם] [קָדְשִֽׁי]');
INSERT INTO verses VALUES (21543, 26, 39, 26, '[וְנָשׂוּ֙] a [וְאֶת־כָּל־מַעֲלָ֖ם] e-[OBJ] todo [בְּשִׁבְתָּ֧ם] que [לָבֶ֖טַח] em-mim [מַחֲרִֽיד] sobre [sem-traducao] [sem-traducao] e-não-há [sem-traducao]');
INSERT INTO verses VALUES (21544, 26, 39, 27, '[בְּשׁוֹבְבִ֤י] elas de os-povos eles a-eles [אֹֽיְבֵיהֶ֑ם] [וְנִקְדַּ֣שְׁתִּי] [בָ֔ם] neles aos-olhos-de as-nações muitos');
INSERT INTO verses VALUES (21545, 26, 39, 28, '[וְיָדְע֗וּ] que eu yhwh [אֱלֹ֣הֵיהֶ֔ם] [בְּהַגְלוֹתִ֤י] eles a as-nações [עַל־אַדְמָתָ֑ם] sobre [ע֛וֹד] e-não [שָֽׁם] nome');
INSERT INTO verses VALUES (21546, 26, 39, 29, 'e-não [ע֛וֹד] ainda face-de deles que [אֶת־רוּחִי֙] a [יִשְׂרָאֵ֔ל] sobre casa Israel oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (842, 26, 40, 49);
INSERT INTO verses VALUES (21547, 26, 40, 1, '[בְּעֶשְׂרִ֣ים] [וְחָמֵ֣שׁ] ano [לְ֠גָלוּתֵנוּ] [בְּרֹ֨אשׁ] [הַשָּׁנָ֜ה] [בֶּעָשׂ֣וֹר] [לַחֹ֗דֶשׁ] [בְּאַרְבַּ֤ע] dez ano atrás-de que [הֻכְּתָ֖ה] a-cidade [בְּעֶ֣צֶם] o-dia o-dia [הַזֶּ֗ה] era mão-de yhwh e-trouxe a-mim [שָֽׁמָּה]');
INSERT INTO verses VALUES (21548, 26, 40, 2, '[בְּמַרְא֣וֹת] Elohim [הֱבִיאַ֖נִי] a terra Israel [אֶל־הַ֤ר] a muito [וְעָלָ֥יו] muito [מִנֶּֽגֶב] cidade');
INSERT INTO verses VALUES (21549, 26, 40, 3, '[וַיָּבֵ֨יא] [אוֹתִ֜י] [שָׁ֗מָּה] e-eis homem [כְּמַרְאֵ֣ה] [נְחֹ֔שֶׁת] [וּפְתִיל־פִּשְׁתִּ֥ים] [בְּיָד֖וֹ] [וּקְנֵ֣ה] [הַמִּדָּ֑ה] [וְה֥וּא] [עֹמֵ֖ד] e-ele ficou-em-pé [sem-traducao]');
INSERT INTO verses VALUES (21550, 26, 40, 4, '[וַיְדַבֵּ֨ר] a-mim o-homem filho-de homem viu [וּבְאָזְנֶ֨יךָ] [שְּׁמָ֜ע] ouviu [לִבְּךָ֗] a-todo para-todo vista eu que a-ti porque para [הֵ֑נָּה] [הַגֵּ֛ד] [אֶת־כָּל־אֲשֶׁר־אַתָּ֥ה] [רֹאֶ֖ה] a todo que tu viu segundo-casa-de Israel');
INSERT INTO verses VALUES (21551, 26, 40, 5, 'e-eis [חוֹמָ֛ה] de-fora [לַבַּ֖יִת] ao-redor ao-redor [סָבִ֑יב] [וּבְיַ֨ד] [הָאִ֜ישׁ] [קְנֵ֣ה] seis-de [שֵׁשׁ־אַמּ֤וֹת] na-côvado [וָטֹ֔פַח] [וַיָּ֜מָד] a [הַבִּנְיָן֙] [קָנֶ֣ה] um um [קָנֶ֥ה] um um');
INSERT INTO verses VALUES (21552, 26, 40, 6, 'e-veio a [אֲשֶׁ֤ר] que o-caminho-de caminho [וַיַּ֖עַל] [*במעלותו] [**בְּמַֽעֲלוֹתָ֑יו] a [׀] [אֶת־סַ֣ף] [הַשַּׁ֗עַר] um um e-[OBJ] e-[OBJ] um um um um');
INSERT INTO verses VALUES (21553, 26, 40, 7, '[וְהַתָּ֗א] [קָנֶ֨ה] um [אֹ֙רֶךְ֙] [וְקָנֶ֤ה] um [רֹ֔חַב] e-entre [הַתָּאִ֖ים] cinco covados [וְסַ֣ף] [הַ֠שַּׁעַר] [מֵאֵ֨צֶל] [אוּלָ֥ם] [הַשַּׁ֛עַר] [מֵֽהַבַּ֖יִת] [קָנֶ֥ה] um');
INSERT INTO verses VALUES (21554, 26, 40, 8, '[וַיָּ֜מָד] a [הַשַּׁ֛עַר] [מֵהַבַּ֖יִת] [קָנֶ֥ה] um um');
INSERT INTO verses VALUES (21555, 26, 40, 9, '[וַיָּ֜מָד] a [הַשַּׁ֙עַר֙] [שְׁמֹנֶ֣ה] oito covados [**וְאֵילָ֖יו] covados [אַמּ֑וֹת] [וְאֻלָ֥ם] [הַשַּׁ֖עַר]');
INSERT INTO verses VALUES (21556, 26, 40, 10, '[וְתָאֵ֨י] o-portão o-caminho-de [הַקָּדִ֗ים] [שְׁלֹשָׁ֤ה] [מִפֹּה֙] e-três [מִפֹּ֔ה] [מִדָּ֥ה] uma [לִשְׁלָשְׁתָּ֑ם] e-tributo uma [לָאֵילִ֖ם] [מִפֹּ֥ה] [וּמִפּֽוֹ]');
INSERT INTO verses VALUES (21557, 26, 40, 11, '[וַיָּ֛מָד] a [פֶּֽתַח־הַשַּׁ֖עַר] [עֶ֣שֶׂר] [אַמּ֑וֹת] dez covados comprimento o-portão [אַמּֽוֹת] dez [sem-traducao]');
INSERT INTO verses VALUES (21558, 26, 40, 12, '[וּגְב֞וּל] diante-de [הַתָּאוֹת֙] [אַמָּ֣ה] [אֶחָ֔ת] [וְאַמָּה־אַחַ֥ת] uma [מִפֹּ֑ה] [וְהַתָּ֕א] [שֵׁשׁ־אַמּ֣וֹת] seis-de côvados [אַמּ֖וֹת] e-seis');
INSERT INTO verses VALUES (21559, 26, 40, 13, '[וַיָּ֣מָד] a [מִגַּ֤ג] [הַתָּא֙] [לְגַגּ֔וֹ] [רֹ֕חַב] [עֶשְׂרִ֥ים] vinte [אַמּ֑וֹת] covados diante diante-de [sem-traducao]');
INSERT INTO verses VALUES (21560, 26, 40, 14, 'E-fez a [שִׁשִּׁ֣ים] [אַמָּ֑ה] [וְאֶל־אֵיל֙] e-a [הַשַּׁ֖עַר] [סָבִ֥יב] [׀] ao-redor ao-redor');
INSERT INTO verses VALUES (21561, 26, 40, 15, 'e-sobre face-de [הַשַּׁ֣עַר] sobre diante-de [עַל־לִפְנֵ֕י] [אֻלָ֥ם] [הַשַּׁ֖עַר] cinquenta [חֲמִשִּׁ֖ים]');
INSERT INTO verses VALUES (21562, 26, 40, 16, '[וְחַלֹּנ֣וֹת] [אֲטֻמ֣וֹת] a e-para e-a [לִפְנִ֤ימָה] [לַשַּׁ֙עַר֙] [סָבִ֣יב] ao-redor ao-redor [וְכֵ֖ן] [לָאֵֽלַמּ֑וֹת] [וְחַלּוֹנ֞וֹת] [סָבִ֤יב] ao-redor [סָבִיב֙] e-a [וְאֶל־אַ֖יִל] [תִּמֹרִֽים]');
INSERT INTO verses VALUES (21563, 26, 40, 17, '[וַיְבִיאֵ֗נִי] a o-pateo [וְהִנֵּ֤ה] e-eis [וְרִֽצְפָ֔ה] [עָשׂ֥וּי] [לֶחָצֵ֖ר] [סָבִ֣יב] ao-redor ao-redor trinta [לְשָׁכ֖וֹת] a [sem-traducao]');
INSERT INTO verses VALUES (21564, 26, 40, 18, '[וְהָרִֽצְפָה֙] a [הַשְּׁעָרִ֔ים] [לְעֻמַּ֖ת] [אֹ֣רֶךְ] comprimento [הָרִֽצְפָ֖ה] [הַתַּחְתּוֹנָֽה] [sem-traducao]');
INSERT INTO verses VALUES (21565, 26, 40, 19, '[וַיָּ֣מָד] [רֹ֡חַב] [מִלִּפְנֵי֩] [הַשַּׁ֨עַר] [הַתַּחְתּ֜וֹנָה] diante-de [הֶחָצֵ֧ר] [הַפְּנִימִ֛י] [מִח֖וּץ] cem [אַמָּ֑ה] [הַקָּדִ֖ים] [וְהַצָּפֽוֹן]');
INSERT INTO verses VALUES (21566, 26, 40, 20, '[וְהַשַּׁ֗עַר] que [פָּנָיו֙] o-caminho-de [הַצָּפ֔וֹן] [לֶחָצֵ֖ר] [הַחִֽיצוֹנָ֑ה] [מָדַ֥ד] [אָרְכּ֖וֹ] [וְרָחְבּֽוֹ]');
INSERT INTO verses VALUES (21567, 26, 40, 21, '[*ותאו] [**וְתָאָ֗יו] e-três [מִפּוֹ֙] foi [מִפּ֔וֹ] [*ואילו] o-primeiro cinquenta côvado ser [כְּמִדַּ֖ת] cinco e-vinte [חֲמִשִּׁ֤ים]');
INSERT INTO verses VALUES (21568, 26, 40, 22, '[*וחלונו] o-portão que sua-face caminho [**וְתִ֣מֹרָ֔יו] [כְּמִדַּ֣ת] sete [אֲשֶׁ֥ר] nele o-caminho-de');
INSERT INTO verses VALUES (21569, 26, 40, 23, '[וְשַׁ֙עַר֙] [לֶחָצֵ֣ר] [הַפְּנִימִ֔י] diante o-portão [לַצָּפ֖וֹן] [וְלַקָּדִ֑ים] [וַיָּ֧מָד] [מִשַּׁ֛עַר] a porta-de cem');
INSERT INTO verses VALUES (21570, 26, 40, 24, '[וַיּוֹלִכֵ֙נִי֙] o-caminho-de [הַדָּר֔וֹם] e-eis- o-caminho-de caminho [וּמָדַ֤ד] [*אילו] [**אֵילָיו֙] as estas');
INSERT INTO verses VALUES (21571, 26, 40, 25, '[וְחַלּוֹנִ֨ים] a-ele ao-redor ao-redor [סָבִ֣יב] estas [סָבִ֔יב] [כְּהַחֲלֹּנ֖וֹת] comprimento [חֲמִשִּׁ֤ים] cinco [אֹ֔רֶךְ] [וְרֹ֕חַב]');
INSERT INTO verses VALUES (21572, 26, 40, 26, '[וּמַעֲל֤וֹת] [שִׁבְעָה֙] diante-deles [**עֹֽלוֹתָ֔יו] [*ואלמו] um [לִפְנֵיהֶ֑ם] [וְתִמֹרִ֣ים] a-ele um');
INSERT INTO verses VALUES (21573, 26, 40, 27, '[וְשַׁ֛עַר] [לֶחָצֵ֥ר] [הַפְּנִימִ֖י] o-caminho-de [הַדָּר֑וֹם] [וַיָּ֨מָד] [מִשַּׁ֧עַר] a o-caminho-de caminho [מֵאָ֥ה] cem');
INSERT INTO verses VALUES (21574, 26, 40, 28, '[וַיְבִיאֵ֛נִי] a [הַפְּנִימִ֖י] [בְּשַׁ֣עַר] [הַדָּר֑וֹם] [וַיָּ֙מָד֙] [אֶת־הַשַּׁ֣עַר] a [כַּמִּדּ֖וֹת] [הָאֵֽלֶּה]');
INSERT INTO verses VALUES (21575, 26, 40, 29, '[*ותאו] os-estes [*ואילו] para-ele ao-redor ao-redor cinquenta côvado comprimento a-ele vinte e-cinco [סָבִ֣יב]');
INSERT INTO verses VALUES (21576, 26, 40, 30, '[וְאֵֽלַמּ֖וֹת] ao-redor ao-redor comprimento cinco e-vinte Ammah e-largura cinco [חָמֵ֥שׁ]');
INSERT INTO verses VALUES (21577, 26, 40, 31, '[וְאֵלַמָּ֗ו] a [הַחִ֣צוֹנָ֔ה] [וְתִמֹרִ֖ים] [אֶל־*אילו] a [וּמַעֲל֥וֹת] [שְׁמוֹנֶ֖ה]');
INSERT INTO verses VALUES (21578, 26, 40, 32, '[וַיְבִיאֵ֛נִי] a [הַפְּנִימִ֖י] o-caminho-de caminho [וַיָּ֣מָד] [אֶת־הַשַּׁ֔עַר] a o-portão');
INSERT INTO verses VALUES (21579, 26, 40, 33, '[*ותאו] os-estes [*ואלו] para-ele ao-redor ao-redor comprimento-de cinquenta Ammah a-ele cinco e-vinte [סָבִ֣יב]');
INSERT INTO verses VALUES (21580, 26, 40, 34, '[*ואלמו] [**וְאֵלַמָּ֗יו] [לֶֽחָצֵר֙] a [וְתִמֹרִ֥ים] [אֶל־*אלו] e-oito [מִפּ֣וֹ]');
INSERT INTO verses VALUES (21581, 26, 40, 35, '[וַיְבִיאֵ֖נִי] a portão [וּמָדַ֖ד] [כַּמִּדּ֥וֹת] [הָאֵֽלֶּה]');
INSERT INTO verses VALUES (21582, 26, 40, 36, '[*תאו] a-ele ao-redor ao-redor comprimento-de cinquenta Ammah a-ele cinco e-vinte [סָבִ֑יב]');
INSERT INTO verses VALUES (21583, 26, 40, 37, '[*ואילו] [**וְאֵילָ֗יו] [לֶֽחָצֵר֙] a [וְתִמֹרִ֥ים] [אֶל־*אילו] e-oito [מִפּ֣וֹ]');
INSERT INTO verses VALUES (21584, 26, 40, 38, '[וְלִשְׁכָּ֣ה] [וּפִתְחָ֔הּ] [בְּאֵילִ֖ים] [הַשְּׁעָרִ֑ים] nome [יָדִ֥יחוּ] a');
INSERT INTO verses VALUES (21585, 26, 40, 39, '[וּבְאֻלָ֣ם] [הַשַּׁ֗עַר] dois [שֻׁלְחָנוֹת֙] [מִפּ֔וֹ] [וּשְׁנַ֥יִם] [שֻׁלְחָנ֖וֹת] [מִפֹּ֑ה] [לִשְׁח֤וֹט] a-eles [הָעוֹלָ֔ה] [וְהַחַטָּ֖את] [וְהָאָשָֽׁם]');
INSERT INTO verses VALUES (21586, 26, 40, 40, 'e-a [מִח֗וּצָה] [לָעוֹלֶה֙] [לְפֶ֙תַח֙] [הַשַּׁ֣עַר] [הַצָּפ֔וֹנָה] [שְׁנַ֖יִם] dois [וְאֶל־הַכָּתֵ֣ף] e-a [אֲשֶׁר֙] [לְאֻלָ֣ם] que [שְׁנַ֖יִם] [שֻׁלְחָנֽוֹת] dois');
INSERT INTO verses VALUES (21587, 26, 40, 41, 'quatro [שֻׁלְחָנ֜וֹת] [מִפֹּ֗ה] [וְאַרְבָּעָ֧ה] [שֻׁלְחָנ֛וֹת] [מִפֹּ֖ה] [לְכֶ֣תֶף] [הַשָּׁ֑עַר] [שְׁמוֹנָ֥ה] [שֻׁלְחָנ֖וֹת] [אֲלֵיהֶ֥ם] [יִשְׁחָֽטוּ]');
INSERT INTO verses VALUES (21588, 26, 40, 42, '[וְאַרְבָּעָה֩] [שֻׁלְחָנ֨וֹת] [לָעוֹלָ֜ה] pedras-de [גָזִ֗ית] [אֹרֶךְ֩] [אַמָּ֨ה] uma [וָחֵ֙צִי֙] [וְרֹ֨חַב] [אַמָּ֤ה] uma [וָחֵ֔צִי] [וְגֹ֖בַהּ] [אַמָּ֣ה] um a-eles [וְיַנִּ֤יחוּ] a [אֲשֶׁ֨ר] que [אֶת־הָעוֹלָ֛ה] a [וְהַזָּֽבַח] com-eles [sem-traducao]');
INSERT INTO verses VALUES (21589, 26, 40, 43, '[וְהַֽשְׁפַתַּ֗יִם] [טֹ֧פַח] um [מוּכָנִ֥ים] [בַּבַּ֖יִת] ao-redor ao-redor e-a [וְאֶל־הַשֻּׁלְחָנ֖וֹת] [בְּשַׂ֥ר] [הַקָּרְבָֽן]');
INSERT INTO verses VALUES (21590, 26, 40, 44, '[וּמִחוּצָה֩] [לַשַּׁ֨עַר] [הַפְּנִימִ֜י] [לִֽשְׁכ֣וֹת] [שָׁרִ֗ים] [בֶּחָצֵ֤ר] [הַפְּנִימִי֙] que a [שַׁ֣עַר] portão [וּפְנֵיהֶ֖ם] o-caminho-de caminho um um a [הַקָּדִ֔ים] face-de o-caminho-de face-de caminho');
INSERT INTO verses VALUES (21591, 26, 40, 45, '[וַיְדַבֵּ֖ר] a-mim [זֹ֣ה] [הַלִּשְׁכָּ֗ה] que [פָּנֶ֙יהָ֙] o-caminho-de [הַדָּר֔וֹם] [לַכֹּ֣הֲנִ֔ים] guardadores-de guarda-de [הַבָּֽיִת]');
INSERT INTO verses VALUES (21592, 26, 40, 46, '[וְהַלִּשְׁכָּ֗ה] que [פָּנֶ֙יהָ֙] o-caminho-de [הַצָּפ֔וֹן] [לַכֹּ֣הֲנִ֔ים] guardadores-de [מִשְׁמֶ֣רֶת] o-altar eles filhos-de [הַקְּרֵבִ֧ים] [מִבְּנֵֽי־לֵוִ֛י] [אֶל־יְהוָ֖ה] [לְשָׁרְתֽוֹ] a yhwh');
INSERT INTO verses VALUES (21593, 26, 40, 47, '[וַיָּ֨מָד] a [אֹ֣רֶךְ] [׀] cem côvado [וְרֹ֛חַב] cem côvado [מְרֻבָּ֑עַת] [וְהַמִּזְבֵּ֖חַ] diante-de [הַבָּֽיִת]');
INSERT INTO verses VALUES (21594, 26, 40, 48, '[וַיְבִאֵנִי֮] a [הַבַּיִת֒] [וַיָּ֙מָד֙] [אֵ֣ל] El [חָמֵ֤שׁ] cinco [מִפֹּ֔ה] [וְחָמֵ֥שׁ] e-cinco côvados [וְרֹ֣חַב] [הַשַּׁ֔עַר] o-portão três [מִפּ֔וֹ] [וְשָׁלֹ֥שׁ] [אַמּ֖וֹת] côvados');
INSERT INTO verses VALUES (21595, 26, 40, 49, 'comprimento [הָאֻלָ֞ם] vinte côvado [וְרֹ֙חַב֙] [עַשְׁתֵּ֣י] dez Ammah [וּבַֽמַּעֲל֔וֹת] que eles-subirão a-ele [וְעַמֻּדִים֙] a um um [וְאֶחָ֥ד] e-um [sem-traducao]');
INSERT INTO chapters VALUES (843, 26, 41, 26);
INSERT INTO verses VALUES (21596, 26, 41, 1, '[וַיְבִיאֵ֖נִי] a [וַיָּ֣מָד] [אֶת־הָאֵילִ֗ים] a [רֹ֧חַב] seis-de [וְשֵׁשׁ־אַמּֽוֹת־רֹ֥חַב] [מִפּ֖וֹ] [רֹ֥חַב] e-seis-');
INSERT INTO verses VALUES (21597, 26, 41, 2, '[וְרֹ֣חַב] [הַפֶּתַח֮] dez [אַמּוֹת֒] [וְכִתְפ֣וֹת] [הַפֶּ֔תַח] cinco [אַמּוֹת֙] [מִפּ֔וֹ] [וְחָמֵ֥שׁ] [אַמּ֖וֹת] [מִפּ֑וֹ] [וַיָּ֤מָד] [אָרְכּוֹ֙] [אַרְבָּעִ֣ים] [אַמָּ֔ה] [וְרֹ֖חַב] vinte [אַמָּֽה]');
INSERT INTO verses VALUES (21598, 26, 41, 3, '[וּבָ֣א] [לִפְנִ֔ימָה] [וַיָּ֥מָד] [אֵֽיל־הַפֶּ֖תַח] [שְׁתַּ֣יִם] [אַמּ֑וֹת] covados [שֵׁ֣שׁ] seis covados [הַפֶּ֖תַח] [שֶׁ֥בַע] sete [sem-traducao]');
INSERT INTO verses VALUES (21599, 26, 41, 4, '[וַיָּ֨מָד] a [עֶשְׂרִ֣ים] vinte côvado [עֶשְׂרִ֥ים] vinte côvado a E-disse [אֵלַ֔י] E-disse a-mim este');
INSERT INTO verses VALUES (21600, 26, 41, 5, '[וַיָּ֥מָד] [קִֽיר־הַבַּ֖יִת] a-casa seis covados a-costela [אַרְבַּ֨ע] quatro [סָבִ֧יב] [׀] [סָבִ֛יב] [לַבַּ֖יִת] ao-redor');
INSERT INTO verses VALUES (21601, 26, 41, 6, '[וְהַצְּלָעוֹת֩] costela a [שָׁל֧וֹשׁ] [וּשְׁלֹשִׁ֣ים] [פְּעָמִ֗ים] [וּ֠בָאוֹת] [בַּקִּ֨יר] [אֲשֶׁר־לַבַּ֧יִת] que [סָבִ֥יב] [׀] ao-redor ao-redor [אֲחוּזִ֑ים] [וְלֹֽא־יִהְי֥וּ] e-não serao [הַבָּֽיִת] [sem-traducao] a-casa');
INSERT INTO verses VALUES (21602, 26, 41, 7, '[וְֽרָחֲבָ֡ה] [וְֽנָסְבָה֩] [לְמַ֨עְלָה] [לְמַ֜עְלָה] [לַצְּלָע֗וֹת] que [מֽוּסַב־הַ֠בַּיִת] a-casa [לְמַ֜עְלָה] [סָבִ֤יב] [׀] ao-redor [לַבַּ֔יִת] sobre assim largura-de [וְכֵ֧ן] [הַתַּחְתּוֹנָ֛ה] subia [עַל־הָעֶלְיוֹנָ֖ה] subirá sobre');
INSERT INTO verses VALUES (21603, 26, 41, 8, '[וְרָאִ֧יתִי] [לַבַּ֛יִת] [גֹּ֖בַהּ] ao-redor ao-redor [סָבִ֑יב] [*מיסדות] [**מוּסְד֤וֹת] seis côvados [הַקָּנֶ֔ה]');
INSERT INTO verses VALUES (21604, 26, 41, 9, '[רֹ֣חַב] [הַקִּ֧יר] que [אֶל־הַח֖וּץ] a [אַמּ֑וֹת] cinco covados e-que [צְלָע֖וֹת] casa [לַבָּֽיִת] que para-a-casa');
INSERT INTO verses VALUES (21605, 26, 41, 10, 'e-entre [הַלְּשָׁכ֜וֹת] [רֹ֣חַב] vinte [אַמָּ֛ה] ao-redor [לַבַּ֖יִת] ao-redor ao-redor');
INSERT INTO verses VALUES (21606, 26, 41, 11, '[וּפֶ֤תַח] a-costela [לַמֻּנָּ֔ח] [פֶּ֤תַח] um o-caminho-de [הַצָּפ֔וֹן] e-entrada-de um [לַדָּר֑וֹם] [וְרֹ֙חַב֙] lugar [הַמֻּנָּ֔ח] cinco côvados ao-redor ao-redor');
INSERT INTO verses VALUES (21607, 26, 41, 12, '[וְהַבִּנְיָ֡ן] que a face-de [פְּאַ֣ת] [דֶּֽרֶךְ־הַיָּ֗ם] [רֹ֚חַב] [שִׁבְעִ֣ים] [אַמָּ֔ה] setenta Ammah [חָֽמֵשׁ־אַמּ֥וֹת] [רֹ֖חַב] [סָבִ֣יב] [׀] [סָבִ֑יב] ao-redor [תִּשְׁעִ֥ים] [אַמָּֽה] noventa [sem-traducao]');
INSERT INTO verses VALUES (21608, 26, 41, 13, '[וּמָדַ֣ד] a [אֹ֖רֶךְ] [מֵאָ֣ה] cem [וְהַגִּזְרָ֤ה] [וְהַבִּנְיָה֙] [וְקִ֣ירוֹתֶ֔יהָ] [אֹ֖רֶךְ] [מֵאָ֥ה] cem');
INSERT INTO verses VALUES (21609, 26, 41, 14, '[וְרֹחַב֩] face-de [הַבַּ֧יִת] [וְהַגִּזְרָ֛ה] [לַקָּדִ֖ים] cem [אַמָּֽה]');
INSERT INTO verses VALUES (21610, 26, 41, 15, '[וּמָדַ֣ד] [אֹֽרֶךְ־הַ֠בִּנְיָן] [אֶל־פְּנֵ֨י] a face-de [עַל־אַחֲרֶ֧יהָ] que sobre [מִפּ֥וֹ] [וּמִפּ֖וֹ] [מֵאָ֣ה] cem [וְהַֽהֵיכָל֙] [הַפְּנִימִ֔י] [וְאֻֽלַמֵּ֖י] [הֶחָצֵֽר]');
INSERT INTO verses VALUES (21611, 26, 41, 16, '[הַסִּפִּ֡ים] [וְהַחַלּוֹנִ֣ים] [הָ֠אֲטֻמוֹת] [וְהָאַתִּיקִ֤ים] ao-redor [סָבִיב֙] [לִשְׁלָשְׁתָּ֔ם] diante [הַסַּ֛ף] árvore árvore ao-redor [׀] até E-a-terra [עַד־הַֽחַלֹּנ֔וֹת] [וְהַֽחַלֹּנ֖וֹת]');
INSERT INTO verses VALUES (21612, 26, 41, 17, 'sobre de-sobre [וְעַד־הַבַּיִת֩] e-até [וְלַח֜וּץ] [וְאֶל־כָּל־הַקִּ֨יר] [סָבִ֧יב] e-a todo [בַּפְּנִימִ֥י] [וּבַחִיצ֖וֹן] [מִדּֽוֹת]');
INSERT INTO verses VALUES (21613, 26, 41, 18, '[וְעָשׂ֥וּי] querubins [וְתִֽמֹרִ֑ים] [וְתִֽמֹרָה֙] entre [לִכְר֔וּב] [וּשְׁנַ֥יִם] [פָּנִ֖ים] face');
INSERT INTO verses VALUES (21614, 26, 41, 19, '[וּפְנֵ֨י] homem a [מִפּ֔וֹ] [וּפְנֵֽי־כְפִ֥יר] [אֶל־הַתִּֽמֹרָ֖ה] [מִפּ֑וֹ] a [אֶל־כָּל־הַבַּ֖יִת] [סָבִ֥יב] [׀] a todo');
INSERT INTO verses VALUES (21615, 26, 41, 20, '[מֵהָאָ֙רֶץ֙] até de-sobre [הַכְּרוּבִ֥ים] [וְהַתִּֽמֹרִ֖ים] [עֲשׂוּיִ֑ם] [וְקִ֖יר] [הַׄהֵׄיׄכָֽׄלׄ׃[4]]');
INSERT INTO verses VALUES (21616, 26, 41, 21, '[הַֽהֵיכָ֖ל] [מְזוּזַ֣ת] [רְבֻעָ֑ה] [וּפְנֵ֣י] o-santuário [הַמַּרְאֶ֖ה] [כַּמַּרְאֶֽה]');
INSERT INTO verses VALUES (21617, 26, 41, 22, '[הַמִּזְבֵּ֡חַ] árvore [שָׁלוֹשׁ֩] [אַמּ֨וֹת] [גָּבֹ֜הַּ] [וְאָרְכּ֣וֹ] [שְׁתַּֽיִם־אַמּ֗וֹת] [וּמִקְצֹֽעוֹתָיו֙] a-ele a-ele [וְקִֽירֹתָ֖יו] árvore [וַיְדַבֵּ֣ר] e-falou a-mim este [אֲשֶׁ֖ר] que yhwh yhwh');
INSERT INTO verses VALUES (21618, 26, 41, 23, '[וּשְׁתַּ֧יִם] [דְּלָת֛וֹת] [לַֽהֵיכָ֖ל] [וְלַקֹּֽדֶשׁ]');
INSERT INTO verses VALUES (21619, 26, 41, 24, 'e-dois [דְּלָת֖וֹת] [לַדְּלָת֑וֹת] [שְׁ֚תַּיִם] [מוּסַבּ֣וֹת] [דְּלָת֔וֹת] [שְׁ֚תַּיִם] [לְדֶ֣לֶת] [אֶחָ֔ת] [וּשְׁתֵּ֥י] [דְלָת֖וֹת] [לָאַחֶֽרֶת]');
INSERT INTO verses VALUES (21620, 26, 41, 25, '[וַעֲשׂוּיָ֨ה] [אֲלֵיהֶ֜ן] a [הַֽהֵיכָל֙] [כְּרוּבִ֣ים] querubins [כַּאֲשֶׁ֥ר] como-que [לַקִּיר֑וֹת] [וְעָ֥ב] árvore [אֶל־פְּנֵ֥י] a face-de');
INSERT INTO verses VALUES (21621, 26, 41, 26, '[וְחַלּוֹנִ֨ים] [אֲטֻמ֤וֹת] [וְתִֽמֹרִים֙] [מִפּ֣וֹ] [וּמִפּ֔וֹ] a [הָֽאוּלָ֑ם] [וְצַלְע֥וֹת] [הַבַּ֖יִת] [וְהָעֻבִּֽים]');
INSERT INTO chapters VALUES (844, 26, 42, 20);
INSERT INTO verses VALUES (21622, 26, 42, 1, '[וַיּוֹצִאֵ֗נִי] a o-pateo [הַדֶּ֖רֶךְ] o-caminho-de caminho [וָיְבִאֵ֣נִי] [אֶל־הַלִּשְׁכָּ֗ה] a diante que [וַאֲשֶֽׁר־נֶ֥גֶד] [הַבִּנְיָ֖ן] [אֶל־הַצָּפֽוֹן] diante-de [sem-traducao] a [sem-traducao]');
INSERT INTO verses VALUES (21623, 26, 42, 2, 'a face-de [הַמֵּאָ֔ה] côvados [הַצָּפ֑וֹן] entrada-de [חֲמִשִּׁ֥ים] [אַמּֽוֹת]');
INSERT INTO verses VALUES (21624, 26, 42, 3, 'diante [הָֽעֶשְׂרִ֗ים] que [לֶחָצֵ֣ר] [הַפְּנִימִ֔י] e-diante-de [רִֽצְפָ֔ה] que [לֶחָצֵ֣ר] [הַחִֽיצוֹנָ֑ה] [אַתִּ֥יק] a face-de-');
INSERT INTO verses VALUES (21625, 26, 42, 4, '[וְלִפְנֵ֨י] [הַלְּשָׁכ֜וֹת] [מַהֲלַךְ֩] dez côvados [רֹ֙חַב֙] a o-caminho-de caminho [אֶחָ֑ת] um [לַצָּפֽוֹן]');
INSERT INTO verses VALUES (21626, 26, 42, 5, '[וְהַלְּשָׁכ֥וֹת] [הָעֶלְיוֹנֹ֖ת] [קְצֻר֑וֹת] porque [אַתִּיקִ֜ים] [מֵהֵ֗נָה] [מֵֽהַתַּחְתֹּנ֛וֹת] [וּמֵהַתִּֽכֹנ֖וֹת] [בִּנְיָֽן]');
INSERT INTO verses VALUES (21627, 26, 42, 6, 'que [מְשֻׁלָּשׁוֹת֙] elas [וְאֵ֤ין] [לָהֶן֙] [עַמּוּדִ֔ים] [כְּעַמּוּדֵ֖י] [הַחֲצֵר֑וֹת] sobre assim [מֵהַתַּחְתּוֹנ֛וֹת] [וּמֵהַתִּֽיכֹנ֖וֹת] [מֵהָאָֽרֶץ]');
INSERT INTO verses VALUES (21628, 26, 42, 7, '[וְגָדֵ֤ר] que [לְעֻמַּ֣ת] [הַלְּשָׁכ֔וֹת] o-caminho-de caminho [הַחִֽצוֹנָ֖ה] [אֶל־פְּנֵ֣י] a face-de [חֲמִשִּׁ֥ים] [אַמָּֽה]');
INSERT INTO verses VALUES (21629, 26, 42, 8, 'porque comprimento [אֲשֶׁ֛ר] que [הַחִֽצוֹנָ֖ה] [חֲמִשִּׁ֣ים] cinquenta [וְהִנֵּ֛ה] e-eis sobre face-de [אַמָּֽה] cem [sem-traducao]');
INSERT INTO verses VALUES (21630, 26, 42, 9, 'estas [*לשכות] em-vir-seu [**הַלְּשָׁכ֣וֹת] [הָאֵ֑לֶּה] [*המבוא]');
INSERT INTO verses VALUES (21631, 26, 42, 10, '[בְּרֹ֣חַב] [׀] [גֶּ֣דֶר] caminho o-caminho-de a face-de [הַגִּזְרָ֛ה] e-a face-de [לְשָׁכֽוֹת]');
INSERT INTO verses VALUES (21632, 26, 42, 11, '[וְדֶ֙רֶךְ֙] [לִפְנֵיהֶ֔ם] [כְּמַרְאֵ֣ה] [הַלְּשָׁכ֗וֹת] que o-caminho-de [הַצָּפ֔וֹן] [כְּאָרְכָּ֖ן] assim [רָחְבָּ֑ן] e-tudo [מוֹצָ֣אֵיהֶ֔ן] [וּכְמִשְׁפְּטֵיהֶ֖ן] [וּכְפִתְחֵיהֶֽן]');
INSERT INTO verses VALUES (21633, 26, 42, 12, '[וּכְפִתְחֵ֣י] [הַלְּשָׁכ֗וֹת] que o-caminho-de [הַדָּר֔וֹם] entrada-de na-cabeça caminho o-caminho-de [בִּפְנֵי֙] [הַגְּדֶ֣רֶת] [הֲגִינָ֔ה] o-caminho-de [הַקָּדִ֖ים] [בְּבוֹאָֽן]');
INSERT INTO verses VALUES (21634, 26, 42, 13, 'E-disse a-mim [לִֽשְׁכ֨וֹת] [הַצָּפ֜וֹן] [לִֽשְׁכ֣וֹת] [הַדָּרוֹם֮] que a face-de [הֵ֣נָּה] [׀] [לִֽשְׁכ֣וֹת] [הַקֹּ֗דֶשׁ] que [יֹאכְלוּ־שָׁ֧ם] nome [אֲשֶׁר־קְרוֹבִ֥ים] que [קָדְשֵׁ֣י] a-yhwh [שָׁ֞ם] [יַנִּ֣יחוּ] nome [קָדְשֵׁ֣י] [הַקֳּדָשִׁ֗ים] [וְהַמִּנְחָה֙] [וְהַחַטָּ֣את] [וְהָאָשָׁ֔ם] que porque o-lugar');
INSERT INTO verses VALUES (21635, 26, 42, 14, '[בְּבֹאָ֣ם] [הַכֹּהֲנִ֗ים] e-não [מֵהַקֹּ֙דֶשׁ֙] [אֶל־הֶחָצֵ֣ר] a [וְשָׁ֞ם] [יַנִּ֧יחוּ] e-ali [אֲשֶׁר־יְשָׁרְת֥וּ] [בָהֶ֖ן] que [הֵ֑נָּה] [*ילבשו] porque santo-de [אֲחֵרִ֔ים] [וְקָרְב֖וּ] outros [לָעָֽם] a que');
INSERT INTO verses VALUES (21636, 26, 42, 15, '[וְכִלָּ֗ה] a [הַבַּ֣יִת] a-casa [וְהוֹצִיאַ֙נִי֙] o-caminho-de caminho o-portão que o-caminho-de caminho [וּמְדָד֖וֹ] [סָבִ֥יב] ao-redor ao-redor');
INSERT INTO verses VALUES (21637, 26, 42, 16, '[מָדַ֛ד] espírito [הַקָּדִ֖ים] [בִּקְנֵ֣ה] [הַמִּדָּ֑ה] [חֲמֵשׁ־*אמות] [**מֵא֥וֹת] [קָנִ֛ים] [בִּקְנֵ֥ה] ao-redor');
INSERT INTO verses VALUES (21638, 26, 42, 17, '[מָדַ֖ד] espírito [הַצָּפ֑וֹן] [חֲמֵשׁ־מֵא֥וֹת] centenas [בִּקְנֵ֥ה] [הַמִּדָּ֖ה] [סָבִֽיב]');
INSERT INTO verses VALUES (21639, 26, 42, 18, 'a espírito [הַדָּר֖וֹם] [מָדָ֑ד] [חֲמֵשׁ־מֵא֥וֹת] centenas [בִּקְנֵ֥ה] [הַמִּדָּֽה]');
INSERT INTO verses VALUES (21640, 26, 42, 19, 'rodear a o-mar [מָדַ֛ד] [חֲמֵשׁ־מֵא֥וֹת] [קָנִ֖ים] centenas [הַמִּדָּֽה]');
INSERT INTO verses VALUES (21641, 26, 42, 20, '[לְאַרְבַּ֨ע] [רוּח֜וֹת] [מְדָד֗וֹ] [ח֤וֹמָה] a-ele ao-redor ao-redor comprimento-de cinco centenas e-largura cinco centenas [מֵא֑וֹת] para-separar entre [הַקֹּ֖דֶשׁ]');
INSERT INTO chapters VALUES (845, 26, 43, 27);
INSERT INTO verses VALUES (21642, 26, 43, 1, '[וַיּוֹלִכֵ֖נִי] a [שַׁ֕עַר] [אֲשֶׁ֥ר] que o-caminho-de caminho');
INSERT INTO verses VALUES (21643, 26, 43, 2, '[וְהִנֵּ֗ה] [כְּבוֹד֙] Elohim-de Israel veio de-caminho-de [הַקָּדִ֑ים] [וְקוֹל֗וֹ] [כְּקוֹל֙] águas muitos E-a-terra [הֵאִ֥ירָה] [מִכְּבֹדֽוֹ]');
INSERT INTO verses VALUES (21644, 26, 43, 3, '[וּכְמַרְאֵ֨ה] [הַמַּרְאֶ֜ה] que [רָאִ֗יתִי] [כַּמַּרְאֶ֤ה] que vi [לְשַׁחֵ֣ת] para-destruir a a-cidade [אֲשֶׁ֥ר] [רָאִ֖יתִי] que vi a a face-de');
INSERT INTO verses VALUES (21645, 26, 43, 4, '[וּכְב֥וֹד] yhwh veio a o-caminho-de caminho [אֲשֶׁ֥ר] que o-caminho-de caminho');
INSERT INTO verses VALUES (21646, 26, 43, 5, '[וַתִּשָּׂאֵ֣נִי] espírito [וַתְּבִיאֵ֕נִי] a [הַפְּנִימִ֑י] [וְהִנֵּ֛ה] e-eis enchei [הַבָּֽיִת] yhwh');
INSERT INTO verses VALUES (21647, 26, 43, 6, '[וָאֶשְׁמַ֛ע] [מִדַּבֵּ֥ר] para-mim [מֵהַבָּ֑יִת] [וְאִ֕ישׁ] ser ficou-em-pé [אֶצְלִֽי]');
INSERT INTO verses VALUES (21648, 26, 43, 7, 'E-disse a-mim filho-de homem a lugar [כַּפּ֣וֹת] e-[OBJ] [אֲשֶׁ֧ר] [אֶשְׁכָּן־שָׁ֛ם] no-meio-de que [לְעוֹלָ֑ם] nome [יְטַמְּא֣וּ] filhos-de Israel para-sempre e-não [הֵ֤מָּה] [וּמַלְכֵיהֶם֙] casa-de Israel nome [בָּמוֹתָֽם]');
INSERT INTO verses VALUES (21649, 26, 43, 8, '[בְּתִתָּ֨ם] [סִפָּ֜ם] a [וּמְזֽוּזָתָם֙] [אֵ֣צֶל] [מְזוּזָתִ֔י] [וְהַקִּ֖יר] [בֵּינִ֣י] [וּבֵֽינֵיהֶ֑ם] [וְטִמְּא֣וּ] [׀] a nome [בְּתֽוֹעֲבוֹתָם֙] [אֲשֶׁ֣ר] que [וָאֲכַ֥ל] eles eles');
INSERT INTO verses VALUES (21650, 26, 43, 9, '[עַתָּ֞ה] [יְרַחֲק֧וּ] a [וּפִגְרֵ֥י] [מַלְכֵיהֶ֖ם] [מִמֶּ֑נִּי] de-mim [בְתוֹכָ֖ם] [לְעוֹלָֽם׃]');
INSERT INTO verses VALUES (21651, 26, 43, 10, 'tu filho-de homem [אֶת־בֵּֽית־יִשְׂרָאֵל֙] a casa-de Israel a a-casa a');
INSERT INTO verses VALUES (21652, 26, 43, 11, '[וְאִֽם־נִכְלְמ֞וּ] de-toda de-todo que [הַבַּ֡יִת] [וּתְכוּנָת֡וֹ] [וּמוֹצָאָ֡יו] [וּמוֹבָאָ֣יו] [וְֽכָל־צֽוּרֹתָ֡ו] e-[OBJ] e-todo [וְכָל־*צורתי] e-[OBJ] todo [**תּוֹרֹתָיו֙] e-todo e-todo foi-conhecido a-eles [וְיִשְׁמְר֞וּ] [אֶת־כָּל־צוּרָת֛וֹ] [וְאֶת־כָּל־חֻקֹּתָ֖יו] a todo e-[OBJ] todo');
INSERT INTO verses VALUES (21653, 26, 43, 12, 'esta lei-de a-casa sobre cabeça [כָּל־גְּבֻל֞וֹ] todo [׀] [סָבִיב֙] ao-redor santo-de [הִנֵּה־זֹ֖את] eis-que- esta yhwh a-casa');
INSERT INTO verses VALUES (21654, 26, 43, 13, '[וְאֵ֨לֶּה] [מִדּ֤וֹת] o-altar [בָּֽאַמּ֔וֹת] [אַמָּ֥ה] côvado [וָטֹ֑פַח] [וְחֵ֨יק] [הָאַמָּ֜ה] [וְאַמָּה־רֹ֗חַב] [וּגְבוּלָ֨הּ] [אֶל־שְׂפָתָ֤הּ] a [זֶ֣רֶת] o-primeiro [וְזֶ֖ה] [גַּ֥ב] [הַמִּזְבֵּֽחַ]');
INSERT INTO verses VALUES (21655, 26, 43, 14, '[וּמֵחֵ֨יק] a-terra até [הַתַּחְתּוֹנָה֙] [שְׁתַּ֣יִם] [אַמּ֔וֹת] covados e-largura [אֶחָ֑ת] um [הַקְּטַנָּ֜ה] [עַד־הָעֲזָרָ֤ה] até [אַרְבַּ֣ע] [אַמּ֔וֹת] quatro covados e-largura [sem-traducao]');
INSERT INTO verses VALUES (21656, 26, 43, 15, '[וְהַֽהַרְאֵ֖ל] quatro covados [וּמֵהָאֲרִאֵ֣יל] [וּלְמַ֔עְלָה] [הַקְּרָנ֖וֹת] quatro');
INSERT INTO verses VALUES (21657, 26, 43, 16, 'dois dez comprimento [עֶשְׂרֵה֙] dez [בִּשְׁתֵּ֥ים] [עֶשְׂרֵ֖ה] El [רָב֕וּעַ] a');
INSERT INTO verses VALUES (21658, 26, 43, 17, '[וְהָעֲזָרָ֞ה] quatro dez comprimento [בְּאַרְבַּ֤ע] dez [רֹ֔חַב] a [אַרְבַּ֣עַת] [רְבָעֶ֑יהָ] [וְהַגְּבוּל֩] [סָבִ֨יב] [אוֹתָ֜הּ] metade [הָאַמָּ֗ה] [וְהַֽחֵיק־לָ֤הּ] para-ela côvado ao-redor [פְּנ֥וֹת] [קָדִֽים] [sem-traducao]');
INSERT INTO verses VALUES (21659, 26, 43, 18, 'E-disse a-mim filho-de homem disse disse Adonai Estas [חֻקּ֣וֹת] [הַמִּזְבֵּ֔חַ] o altar em-dia [לְהַעֲל֤וֹת] [עָלָיו֙] sobre-ele [וְלִזְרֹ֥ק] [עָלָ֖יו] sobre-ele');
INSERT INTO verses VALUES (21660, 26, 43, 19, '[וְנָתַתָּ֣ה] a [הַלְוִיִּ֡ם] [אֲשֶׁ֣ר] eles [מִזֶּ֨רַע] [צָד֜וֹק] [הַקְּרֹבִ֣ים] [אֵלַ֗י] a-mim oráculo-de Adonai yhwh [פַּ֥ר] [בֶּן־בָּקָ֖ר] filho-de manhã para-oferta-pelo-pecado');
INSERT INTO verses VALUES (21661, 26, 43, 20, '[וְלָקַחְתָּ֣] [מִדָּמ֗וֹ] [וְנָ֨תַתָּ֜ה] sobre quatro [וְאֶל־אַרְבַּע֙] e-a quatro [וְאֶֽל־הַגְּב֖וּל] [סָבִ֑יב] e-a [אוֹת֖וֹ] [וְכִפַּרְתָּֽהוּ]');
INSERT INTO verses VALUES (21662, 26, 43, 21, '[וְלָ֣קַחְתָּ֔] a [הַפָּ֣ר] a-oferta-pelo-pecado [וּשְׂרָפוֹ֙] [בְּמִפְקַ֣ד] a-casa [מִח֖וּץ] [לַמִּקְדָּֽשׁ]');
INSERT INTO verses VALUES (21663, 26, 43, 22, 'e-no-dia o-segundo tu-oferecerás Seir [תָּמִ֖ים] perfeito para-oferta-de-pecado [אֶת־הַמִּזְבֵ֔חַ] a [חִטְּא֖וּ] como-que [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21664, 26, 43, 23, '[בְּכַלּוֹתְךָ֖] [מֵֽחַטֵּ֑א] [תַּקְרִיב֙] touro filho-de manhã [וְאַ֥יִל] [מִן־הַצֹּ֖אן] de');
INSERT INTO verses VALUES (21665, 26, 43, 24, '[וְהִקְרַבְתָּ֖ם] diante-de yhwh [וְהִשְׁלִ֨יכוּ] os-sacerdotes sobre-eles [מֶ֔לַח] [וְהֶעֱל֥וּ] eles holocausto para-יהוה');
INSERT INTO verses VALUES (21666, 26, 43, 25, 'sete-de dias farás Seir pecado [וּפַ֧ר] [בֶּן־בָּקָ֛ר] filho-de manhã [תְּמִימִ֥ים] de');
INSERT INTO verses VALUES (21667, 26, 43, 26, 'sete-de dias [יְכַפְּרוּ֙] a o altar ele e-enchei [*ידו]');
INSERT INTO verses VALUES (21668, 26, 43, 27, '[וִֽיכַלּ֖וּ] a os-dias e-será no-dia [הַשְּׁמִינִ֜י] [וָהָ֗לְאָה] [יַעֲשׂ֨וּ] os-sacerdotes sobre o-altar a [וְרָצִ֣אתִי] e-[OBJ] [נְאֻ֖ם] [Adonai] vos oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (846, 26, 44, 31);
INSERT INTO verses VALUES (21669, 26, 44, 1, '[וַיָּ֣שֶׁב] a-mim o-caminho-de porta-de [הַמִּקְדָּשׁ֙] [הַֽחִיצ֔וֹן] [הַפֹּנֶ֖ה] [קָדִ֑ים] e-ele puro');
INSERT INTO verses VALUES (21670, 26, 44, 2, 'E-disse a-mim yhwh [הַשַּׁ֣עַר] [הַזֶּה֩] [סָג֨וּר] será não [יִפָּתֵ֗חַ] e-homem não nele que yhwh yhwh Elohim-de nele veio nele a-terra puro');
INSERT INTO verses VALUES (21671, 26, 44, 3, 'a [נָ֥שִׂיא] ele ele [לֶאֱכָול־לֶ֖חֶם] nele yhwh pão diante-de yhwh [יָב֔וֹא] [וּמִדַּרְכּ֖וֹ] [יֵצֵֽא] ele ele saira');
INSERT INTO verses VALUES (21672, 26, 44, 4, '[וַיְבִיאֵ֜נִי] [דֶּֽרֶךְ־שַׁ֣עַר] portão [אֶל־פְּנֵ֣י] a face-de [וְהִנֵּ֛ה] [מָלֵ֥א] e-eis enchei yhwh yhwh a casa yhwh a face-de');
INSERT INTO verses VALUES (21673, 26, 44, 5, 'E-disse a-mim yhwh filho-de homem foi-posto [וּרְאֵ֨ה] [בְעֵינֶ֜יךָ] [וּבְאָזְנֶ֣יךָ] [שְּׁמָ֗ע] ouviu a todo que eu [לְכָל־חֻקּ֥וֹת] [בֵּית־יְהוָ֖ה] para-todo [**תּֽוֹרֹתָ֑יו] casa-de yhwh e-para-todo- [הַבַּ֔יִת] [בְּכֹ֖ל] [מוֹצָאֵ֥י] [הַמִּקְדָּֽשׁ] em-todo');
INSERT INTO verses VALUES (21674, 26, 44, 6, '[וְאָמַרְתָּ֤] a [אֶל־בֵּ֣ית] a casa disse assim disse Adonai yhwh chefe-de a-vós de-todo casa Israel');
INSERT INTO verses VALUES (21675, 26, 44, 7, '[בַּהֲבִיאֲכֶ֣ם] filhos-de [עַרְלֵי־לֵב֙] [וְעַרְלֵ֣י] coração [לִהְי֥וֹת] [בְּמִקְדָּשִׁ֖י] para-ser [אֶת־בֵּיתִ֑י] [בְּהַקְרִֽיבְכֶ֤ם] a [חֵ֣לֶב] [וָדָ֔ם] a [אֶת־בְּרִיתִ֔י] a [כָּל־תּוֹעֲבוֹתֵיכֶֽם] [sem-traducao] a beriti El todo [sem-traducao]');
INSERT INTO verses VALUES (21676, 26, 44, 8, 'e-não [שְׁמַרְתֶּ֖ם] [מִשְׁמֶ֣רֶת] [קָדָשָׁ֑י] [וַתְּשִׂימ֗וּן] [לְשֹׁמְרֵ֧י] [מִשְׁמַרְתִּ֛י] [בְּמִקְדָּשִׁ֖י] a-vós');
INSERT INTO verses VALUES (21677, 26, 44, 9, 'assim disse Adonai yhwh todo filho-de [וְעֶ֣רֶל] [בָּשָׂ֔ר] não [יָב֖וֹא] [אֶל־מִקְדָּשִׁ֑י] não [אֲשֶׁ֕ר] no-meio-de [בְּנֵ֥י] para-todo filho-de que filhos-de Israel');
INSERT INTO verses VALUES (21678, 26, 44, 10, 'que se os-levitas que [מֵֽעָלַ֔י] de-sobre-mim [יִשְׂרָאֵל֙] Israel que [מֵֽעָלַ֔י] de-sobre-mim atrás-de [וְנָשְׂא֖וּ] [עֲוֺנָֽם] [sem-traducao]');
INSERT INTO verses VALUES (21679, 26, 44, 11, 'e-sejam [בְמִקְדָּשִׁי֙] [מְשָׁ֣רְתִ֔ים] [פְּקֻדּוֹת֙] a [הַבַּ֔יִת] a-casa [אֶת־הַבָּ֑יִת] a a-casa [אֶת־הָעֹלָ֤ה] [וְאֶת־הַזֶּ֙בַח֙] a [וְהֵ֛מָּה] e-[OBJ] [לִפְנֵיהֶ֖ם] para-o-povo');
INSERT INTO verses VALUES (21680, 26, 44, 12, 'porque que [יְשָׁרְת֤וּ] elas diante-de [גִלּֽוּלֵיהֶ֔ם] e-sejam [לְבֵֽית־יִשְׂרָאֵ֖ל] Israel [עָוֺ֑ן] [עַל־כֵּן֩] sobre [יָדִ֜י] [עֲלֵיהֶ֗ם] [נְאֻם֙] sobre-eles oráculo-de Adonai yhwh [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21681, 26, 44, 13, 'e-não [אֵלַי֙] a-mim [לִ֔י] a-mim [עַל־כָּל־קָ֣דָשַׁ֔י] sobre todo [וְנָֽשְׂאוּ֙] a [וְתוֹעֲבוֹתָ֖ם] os-santos [עָשֽׂוּ] que');
INSERT INTO verses VALUES (21682, 26, 44, 14, 'e-darei a-eles guardadores-de [מִשְׁמֶ֣רֶת] a-casa a-todo [עֲבֹ֣דָת֔וֹ] e-para-todo que [יֵעָשֶׂ֖ה] em-ele');
INSERT INTO verses VALUES (21683, 26, 44, 15, '[וְהַכֹּהֲנִ֨ים] [הַלְוִיִּ֜ם] filhos-de [צָד֗וֹק] que [שָׁמְר֜וּ] a [מִקְדָּשִׁי֙] [בִּתְע֤וֹת] [בְּנֵֽי־יִשְׂרָאֵל֙] filhos-de Israel de-sobre-mim [אֵלַ֖י] [לְשָֽׁרְתֵ֑נִי] para-mim [לְפָנַ֗י] [לְהַקְרִ֥יב] [לִי֙] [חֵ֣לֶב] a-mim [נְאֻ֖ם] [Adonai] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21684, 26, 44, 16, 'eles entrarão a [וְהֵ֛מָּה] [יִקְרְב֥וּ] [אֶל־שֻׁלְחָנִ֖י] a [וְשָׁמְר֖וּ] [אֶת־מִשְׁמַרְתִּֽי] a');
INSERT INTO verses VALUES (21685, 26, 44, 17, 'e-foi [בְּבוֹאָם֙] a [הֶחָצֵ֣ר] [הַפְּנִימִ֔ית] [בִּגְדֵ֥י] [פִשְׁתִּ֖ים] [יִלְבָּ֑שׁוּ] [וְלֹֽא־יַעֲלֶ֤ה] e-não [צֶ֔מֶר] sobre-eles [בְּשַׁעֲרֵ֛י] [הֶחָצֵ֥ר] [הַפְּנִימִ֖ית] [וָבָֽיְתָה]');
INSERT INTO verses VALUES (21686, 26, 44, 18, '[פַּאֲרֵ֤י] [פִשְׁתִּים֙] serão sobre [וּמִכְנְסֵ֣י] [פִשְׁתִּ֔ים] [יִהְי֖וּ] serão não [יַחְגְּר֖וּ] não');
INSERT INTO verses VALUES (21687, 26, 44, 19, '[וּ֠בְצֵאתָם] a [הַחִיצוֹנָ֜ה] [אֶל־הֶחָצֵ֣ר] a [אֶל־הָעָם֒] [יִפְשְׁט֣וּ] a [אֲשֶׁר־הֵ֙מָּה֙] [מְשָׁרְתִ֣ם] a [וְהִנִּ֥יחוּ] que eles [הַקֹּ֑דֶשׁ] [וְלָֽבְשׁוּ֙] [בְּגָדִ֣ים] [אֲחֵרִ֔ים] [וְלֹֽא־יְקַדְּשׁ֥וּ] a-santidade [בְּבִגְדֵיהֶֽם] e-não a');
INSERT INTO verses VALUES (21688, 26, 44, 20, '[וְרֹאשָׁם֙] não [יְגַלֵּ֔חוּ] [וּפֶ֖רַע] não [יְשַׁלֵּ֑חוּ] [כָּס֥וֹם] [יִכְסְמ֖וּ] a');
INSERT INTO verses VALUES (21689, 26, 44, 21, 'e-vinho não [כָּל־כֹּהֵ֑ן] todo sacerdote [הַפְּנִימִֽית] a');
INSERT INTO verses VALUES (21690, 26, 44, 22, '[וְאַלְמָנָה֙] [וּגְרוּשָׁ֔ה] não a-eles a-eles que porque se [בֵּ֣ית] [יִשְׂרָאֵ֔ל] casa Israel [תִּֽהְיֶ֣ה] que [מִכֹּהֵ֖ן] [יִקָּֽחוּ]');
INSERT INTO verses VALUES (21691, 26, 44, 23, 'e-[OBJ] meu-povo entre entre santidade [וּבֵין־טָמֵ֥א] e-entre [יוֹדִעֻֽם]');
INSERT INTO verses VALUES (21692, 26, 44, 24, 'e-sobre [הֵ֚מָּה] eles [*לשפט] [**לְמִשְׁפָּ֔ט] e-[OBJ] [*ושפטהו] e-[OBJ] [וְאֶת־תּוֹרֹתַ֤י] em-todo [בְּכָל־מוֹעֲדַ֣י] [יִשְׁמֹ֔רוּ] e-[OBJ] [יְקַדֵּֽשׁוּ]');
INSERT INTO verses VALUES (21693, 26, 44, 25, 'e-a homem não não [לְטָמְאָ֑ה] que porque se [וּלְבֵ֨ן] [וּלְבַ֜ת] [לְאָ֗ח] [וּלְאָח֛וֹת] [אֲשֶֽׁר־לֹא־הָיְתָ֥ה] [לְאִ֖ישׁ] que não');
INSERT INTO verses VALUES (21694, 26, 44, 26, '[וְאַחֲרֵ֖י] [טָֽהֳרָת֑וֹ] sete dias [יִסְפְּרוּ־לֽוֹ]');
INSERT INTO verses VALUES (21695, 26, 44, 27, '[וּבְיוֹם֩] [בֹּא֨וֹ] a [אֶל־הֶחָצֵ֤ר] a [לְשָׁרֵ֣ת] [בַּקֹּ֔דֶשׁ] [יַקְרִ֖יב] [חַטָּאת֑וֹ] [נְאֻ֖ם] [Adonai] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21696, 26, 44, 28, 'e-será a-eles [לְֽנַחֲלָ֔ה] eu [נַֽחֲלָתָ֑ם] [וַאֲחֻזָּ֗ה] não a-eles para-eles em-Israel eu');
INSERT INTO verses VALUES (21697, 26, 44, 29, 'a-oferenda [וְהַחַטָּ֣את] [וְהָאָשָׁ֔ם] eles [יֹֽאכְל֑וּם] e-todo [בְּיִשְׂרָאֵ֖ל] a-eles será');
INSERT INTO verses VALUES (21698, 26, 44, 30, '[וְרֵאשִׁית֩] todo [כֹ֜ל] todo e-todo de-toda todo de-todo será para-os-sacerdotes [עֲרִסֽוֹתֵיכֶם֙] [תִּתְּנ֣וּ] [לַכֹּהֵ֔ן] [לְהָנִ֥יחַ] [בְּרָכָ֖ה] [אֶל־בֵּיתֶֽךָ] a');
INSERT INTO verses VALUES (21699, 26, 44, 31, 'todo [וּטְרֵפָ֔ה] [מִן־הָע֖וֹף] de não e-de [הַכֹּהֲנִֽים׃] não');
INSERT INTO chapters VALUES (847, 26, 45, 25);
INSERT INTO verses VALUES (21700, 26, 45, 1, '[וּבְהַפִּֽילְכֶ֨ם] a a-terra [תָּרִימוּ֩] [תְרוּמָ֨ה] [לַיהוָ֥ה] [׀] [קֹדֶשׁ֮] de a-terra comprimento cinco e-vinte mil comprimento e-largura [אָ֑לֶף] mil [בְכָל־גְּבוּלָ֖הּ] ele em-todo [sem-traducao] ao-redor');
INSERT INTO verses VALUES (21701, 26, 45, 2, 'será [מִזֶּה֙] a o-santuário cinco centenas [מֵא֖וֹת] centenas [סָבִ֑יב] ao-redor [אַמָּ֔ה] Ammah a-ele a-ele ao-redor');
INSERT INTO verses VALUES (21702, 26, 45, 3, 'e-de [הַזֹּאת֙] esta [אֹ֗רֶךְ] comprimento e-vinte mil [אֶ֔לֶף] dez milhares [אֲלָפִ֑ים] será [הַמִּקְדָּ֖שׁ] [קֹ֥דֶשׁ] [קָדָשִֽׁים]');
INSERT INTO verses VALUES (21703, 26, 45, 4, '[קֹ֣דֶשׁ] de ele [לַכֹּ֨הֲנִ֜ים] [מְשָׁרְתֵ֤י] [הַמִּקְדָּשׁ֙] será [הַקְּרֵבִ֖ים] [לְשָׁרֵ֣ת] [אֶת־יְהוָ֑ה] a a-eles lugar [לְבָ֣תִּ֔ים] [וּמִקְדָּ֖שׁ] [לַמִּקְדָּֽשׁ]');
INSERT INTO verses VALUES (21704, 26, 45, 5, '[וַחֲמִשָּׁ֨ה] [וְעֶשְׂרִ֥ים] mil comprimento [וַעֲשֶׂ֥רֶת] dois-mil [רֹ֑חַב] [*יהיה] [**וְֽהָיָ֡ה] [לַלְוִיִּם֩] a-eles [הַבַּ֧יִת] a-eles [לַאֲחֻזָּ֖ה]');
INSERT INTO verses VALUES (21705, 26, 45, 6, '[וַאֲחֻזַּ֨ת] a-cidade [תִּתְּנ֗וּ] [חֲמֵ֤שֶׁת] milhares [רֹ֔חַב] [וְאֹ֗רֶךְ] cinco e-vinte mil [לְעֻמַּ֖ת] oferta-de a-santidade para-todo casa será');
INSERT INTO verses VALUES (21706, 26, 45, 7, '[וְלַנָּשִׂ֡יא] [מִזֶּ֣ה] [וּמִזֶּה֩] [לִתְרוּמַ֨ת] [הַקֹּ֜דֶשׁ] [וְלַאֲחֻזַּ֣ת] a-cidade a face-de [וְאֶל־פְּנֵי֙] a-santidade e-a face-de [יָ֔מָּה] a-cidade [קָדִ֑ימָה] mar [לְעֻמּוֹת֙] [אַחַ֣ד] ao-oriente [מִגְּב֥וּל] mar [אֶל־גְּב֥וּל] um a');
INSERT INTO verses VALUES (21707, 26, 45, 8, '[לָאָ֛רֶץ] ele-será- para-ele [בְּיִשְׂרָאֵ֑ל] em-Israel e-não [נְשִׂיאַי֙] ainda E-a-terra a povo-meu [לְשִׁבְטֵיהֶֽם׃] Israel');
INSERT INTO verses VALUES (21708, 26, 45, 9, 'assim disse Adonai yhwh chefe-de para-vocês príncipes-de Israel [הָסִ֔ירוּ] [וּמִשְׁפָּ֥ט] [וּצְדָקָ֖ה] [עֲשׂ֑וּ] e-justica fazei de-cima-de [עַמִּ֔י] de-sobre povo-meu oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21709, 26, 45, 10, '[מֹֽאזְנֵי־צֶ֧דֶק] [וְאֵֽיפַת־צֶ֛דֶק] [וּבַת־צֶ֖דֶק] haja a-vós seja');
INSERT INTO verses VALUES (21710, 26, 45, 11, '[הָאֵיפָ֣ה] [וְהַבַּ֗ת] [תֹּ֤כֶן] um será [לָשֵׂ֕את] [מַעְשַׂ֥ר] [הַחֹ֖מֶר] [הַבָּ֑ת] [וַעֲשִׂירִ֤ת] [הַחֹ֙מֶר֙] [הָֽאֵיפָ֔ה] a será será');
INSERT INTO verses VALUES (21711, 26, 45, 12, '[וְהַשֶּׁ֖קֶל] vinte [גֵּרָ֑ה] vinte [שְׁקָלִ֜ים] cinco [וְעֶשְׂרִ֣ים] [שְׁקָלִ֗ים] [עֲשָׂרָ֤ה] [וַחֲמִשָּׁה֙] [שֶׁ֔קֶל] [הַמָּנֶ֖ה] será a-vós');
INSERT INTO verses VALUES (21712, 26, 45, 13, 'esta [הַתְּרוּמָ֖ה] que [תָּרִ֑ימוּ] [שִׁשִּׁ֤ית] [הָֽאֵיפָה֙] [מֵחֹ֣מֶר] [הַֽחִטִּ֔ים] [וְשִׁשִּׁיתֶם֙] [הָֽאֵיפָ֔ה] [מֵחֹ֖מֶר] [הַשְּׂעֹרִֽים]');
INSERT INTO verses VALUES (21713, 26, 45, 14, '[וְחֹ֨ק] [הַשֶּׁ֜מֶן] [הַבַּ֣ת] [הַשֶּׁ֗מֶן] [מַעְשַׂ֤ר] [הַבַּת֙] de [עֲשֶׂ֥רֶת] [הַבַּתִּ֖ים] [חֹ֑מֶר] [כִּֽי־עֲשֶׂ֥רֶת] porque [חֹֽמֶר]');
INSERT INTO verses VALUES (21714, 26, 45, 15, '[וְשֶׂה־אַחַ֨ת] [מִן־הַצֹּ֤אן] de [מִמַּשְׁקֵ֣ה] de [לְמִנְחָ֖ה] [וּלְעוֹלָ֣ה] Israel [לְכַפֵּ֣ר] [עֲלֵיהֶ֔ם] [נְאֻ֖ם] [Adonai] [יְהוִֽה] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21715, 26, 45, 16, 'todo o-povo a-terra [יִהְי֖וּ] a [הַזֹּ֑את] esta [בְּיִשְׂרָאֵֽל]');
INSERT INTO verses VALUES (21716, 26, 45, 17, 'e-sobre será será [וְהַמִּנְחָה֮] [וְהַנֵּסֶךְ֒] [בַּחַגִּ֤ים] [וּבֶחֳדָשִׁים֙] [וּבַשַּׁבָּת֔וֹת] [בְּכָֽל־מוֹעֲדֵ֖י] em-todo [יִשְׂרָאֵ֑ל] casa Israel ele [וְאֶת־הָֽעוֹלָה֙] a [לְכַפֵּ֖ר] e-[OBJ] a-oferenda e-[OBJ] e-[OBJ] casa-de Israel');
INSERT INTO verses VALUES (21717, 26, 45, 18, 'assim disse Adonai yhwh [בְּאֶחָ֣ד] no-primeiro do-mês [פַּר־בֶּן־בָּקָ֖ר] [תָּמִ֑ים] filho-de manhã a');
INSERT INTO verses VALUES (21718, 26, 45, 19, 'e-tome o sacerdote de-sangue-de [הַחַטָּ֗את] [וְנָתַן֙] a [הַבַּ֔יִת] a-casa e-a quatro [לַמִּזְבֵּ֑חַ] [וְעַ֨ל־מְזוּזַ֔ת] para-o-altar e-sobre [הַפְּנִימִֽית]');
INSERT INTO verses VALUES (21719, 26, 45, 20, '[וְכֵ֤ן] [תַּֽעֲשֶׂה֙] [בְּשִׁבְעָ֣ה] [בַחֹ֔דֶשׁ] [מֵאִ֥ישׁ] [שֹׁגֶ֖ה] [וּמִפֶּ֑תִי] [וְכִפַּרְתֶּ֖ם] a');
INSERT INTO verses VALUES (21720, 26, 45, 21, '[בָּ֠רִאשׁוֹן] [בְּאַרְבָּעָ֨ה] dez dia do-mês será a-vós [הַפָּ֑סַח] [חָ֕ג] [שְׁבֻע֣וֹת] dias não-fermentados [יֵאָכֵֽל]');
INSERT INTO verses VALUES (21721, 26, 45, 22, '[וְעָשָׂ֤ה] [הַנָּשִׂיא֙] no-dia aquele [בַּעֲד֕וֹ] [וּבְעַ֖ד] todo a-terra a-terra [חַטָּֽאת]');
INSERT INTO verses VALUES (21722, 26, 45, 23, '[וְשִׁבְעַ֨ת] dias-de [יַעֲשֶׂ֧ה] [עוֹלָ֣ה] [לַֽיהוָ֗ה] a-yhwh sete-de [וְשִׁבְעַ֨ת] [אֵילִ֤ים] [תְּמִימִם֙] [לַיּ֔וֹם] [שִׁבְעַ֖ת] [הַיָּמִ֑ים] os-dias [שְׂעִ֥יר] [עִזִּ֖ים] cabras [sem-traducao]');
INSERT INTO verses VALUES (21723, 26, 45, 24, '[וּמִנְחָ֗ה] [אֵיפָ֥ה] [לַפָּ֛ר] [וְאֵיפָ֥ה] para-o-carneiro [יַֽעֲשֶׂ֑ה] [וְשֶׁ֖מֶן] [הִ֥ין] [לָאֵיפָֽה]');
INSERT INTO verses VALUES (21724, 26, 45, 25, '[בַּשְּׁבִיעִ֡י] [בַּחֲמִשָּׁה֩] dez dia [לַחֹ֙דֶשׁ֙] [בֶּחָ֔ג] ele-fará [כָאֵ֖לֶּה] sete-de os-dias [כַּֽחַטָּאת֙] [כָּעֹלָ֔ה] [וְכַמִּנְחָ֖ה] [וְכַשָּֽׁמֶן׃]');
INSERT INTO chapters VALUES (848, 26, 46, 24);
INSERT INTO verses VALUES (21725, 26, 46, 1, 'assim disse Adonai yhwh [הֶחָצֵ֤ר] [הַפְּנִימִית֙] [הַפֹּנֶ֣ה] [קָדִ֔ים] será será [שֵׁ֖שֶׁת] dias-de dias-de [וּבְי֤וֹם] [הַשַּׁבָּת֙] [יִפָּתֵ֔חַ] [וּבְי֥וֹם] [הַחֹ֖דֶשׁ] [יִפָּתֵֽחַ]');
INSERT INTO verses VALUES (21726, 26, 46, 2, '[וּבָ֣א] [הַנָּשִׂ֡יא] o-caminho-de [אוּלָ֨ם] [הַשַּׁ֜עַר] [מִח֗וּץ] [וְעָמַד֙] sobre [הַשַּׁ֔עַר] [וְעָשׂ֣וּ] [הַכֹּהֲנִ֗ים] [אֶת־עֽוֹלָתוֹ֙] a [וְהִֽשְׁתַּחֲוָ֛ה] e-[OBJ] [הַשַּׁ֖עַר] [וְיָצָ֑א] sobre [לֹֽא־יִסָּגֵ֖ר] [עַד־הָעָֽרֶב] não até');
INSERT INTO verses VALUES (21727, 26, 46, 3, '[וְהִשְׁתַּחֲו֣וּ] com a-terra [הַשַּׁ֣עַר] [הַה֔וּא] aquele [וּבֶחֳדָשִׁ֑ים] [לִפְנֵ֖י] yhwh yhwh');
INSERT INTO verses VALUES (21728, 26, 46, 4, '[וְהָ֣עֹלָ֔ה] que [הַנָּשִׂ֖יא] o-príncipe para-יהוה em-dia-de [שִׁשָּׁ֧ה] seis [תְּמִימִ֖ם] [וְאַ֥יִל] [תָּמִֽים]');
INSERT INTO verses VALUES (21729, 26, 46, 5, '[וּמִנְחָה֙] [אֵיפָ֣ה] [לָאַ֔יִל] [וְלַכְּבָשִׂ֥ים] oferta [מַתַּ֣ת] sua-mão [וְשֶׁ֖מֶן] [הִ֥ין] [לָאֵיפָֽה]');
INSERT INTO verses VALUES (21730, 26, 46, 6, 'e-no-dia-de [הַחֹ֔דֶשׁ] touro-de filho-de manhã [וְשֵׁ֧שֶׁת] [כְּבָשִׂ֛ם] [וָאַ֖יִל] [תְּמִימִ֥ם] [יִהְיֽוּ] ser-ão');
INSERT INTO verses VALUES (21731, 26, 46, 7, 'e-efa-de [לַפָּ֜ר] [וְאֵיפָ֤ה] [לָאַ֙יִל֙] fará oferenda [וְלַ֨כְּבָשִׂ֔ים] como-que [תַּשִּׂ֖יג] sua-mão [וְשֶׁ֖מֶן] [הִ֥ין] [לָאֵיפָֽה]');
INSERT INTO verses VALUES (21732, 26, 46, 8, '[וּבְב֖וֹא] [הַנָּשִׂ֑יא] o-caminho-de [אוּלָ֤ם] [הַשַּׁ֙עַר֙] vira [וּבְדַרְכּ֖וֹ] saira');
INSERT INTO verses VALUES (21733, 26, 46, 9, '[וּבְב֨וֹא] com a-terra yhwh yhwh [הַבָּ֡א] [דֶּרֶךְ־שַׁ֨עַר] [צָפ֜וֹן] portão-de [יֵצֵא֙] [דֶּרֶךְ־שַׁ֣עַר] [נֶ֔גֶב] [וְהַבָּא֙] portão [נֶ֔גֶב] [יֵצֵ֖א] [דֶּרֶךְ־שַׁ֣עַר] portão não [יָשׁ֗וּב] o-caminho-de portão para-o-norte nele que caminho [*יצאו] que veio nele porque [sem-traducao]');
INSERT INTO verses VALUES (21734, 26, 46, 10, '[וְֽהַנָּשִׂ֑יא] [בְּתוֹכָ֤ם] [בְּבוֹאָם֙] vira [וּבְצֵאתָ֖ם] [יֵצֵֽאוּ]');
INSERT INTO verses VALUES (21735, 26, 46, 11, '[וּבַחַגִּ֣ים] [וּבַמּוֹעֲדִ֗ים] [תִּהְיֶ֤ה] a-oferenda [אֵיפָ֤ה] [לַפָּר֙] [וְאֵיפָ֣ה] [לָאַ֔יִל] [וְלַכְּבָשִׂ֖ים] [מַתַּ֣ת] sua-mão [וְשֶׁ֖מֶן] [הִ֥ין] [לָאֵיפָֽה׃]');
INSERT INTO verses VALUES (21736, 26, 46, 12, 'e-quando [הַנָּשִׂ֨יא] [נְדָבָ֜ה] [עוֹלָ֣ה] [אֽוֹ־שְׁלָמִים֮] ou [לַֽיהוָה֒] [וּפָ֣תַֽח] a-ele [אֶת[c]] para-ele [הַפֹּנֶ֣ה] [קָדִ֔ים] [וְעָשָׂ֤ה] [אֶת־עֹֽלָתוֹ֙] a [כַּאֲשֶׁ֥ר] e-[OBJ] [בְּי֣וֹם] como-que [וְיָצָ֛א] no-dia [אֶת־הַשַּׁ֖עַר] [אַחֲרֵ֥י] [צֵאתֽוֹ] a');
INSERT INTO verses VALUES (21737, 26, 46, 13, '[וְכֶ֨בֶשׂ] filho-de [תָּמִ֗ים] [תַּעֲשֶׂ֥ה] farás [לַיּ֖וֹם] [לַֽיהֹוָ֑ה] [בַּבֹּ֥קֶר] [בַּבֹּ֖קֶר] [תַּעֲשֶׂ֥ה] ele');
INSERT INTO verses VALUES (21738, 26, 46, 14, '[וּמִנְחָה֩] [תַעֲשֶׂ֨ה] sobre-ele [בַּבֹּ֤קֶר] [בַּבֹּ֙קֶר֙] [שִׁשִּׁ֣ית] [הָֽאֵיפָ֔ה] [וְשֶׁ֛מֶן] [שְׁלִישִׁ֥ית] [הַהִ֖ין] [לָרֹ֣ס] a [מִנְחָה֙] oferta-cereais a-yhwh eternidade eternidade');
INSERT INTO verses VALUES (21739, 26, 46, 15, 'a [**יַעֲשׂ֨וּ] e-[OBJ] [וְאֶת־הַמִּנְחָ֛ה] e-[OBJ] [בַּבֹּ֣קֶר] [בַּבֹּ֑קֶר] [עוֹלַ֖ת] [תָּמִֽיד׃]');
INSERT INTO verses VALUES (21740, 26, 46, 16, 'assim disse Adonai yhwh porque [מַתָּנָה֙] [לְאִ֣ישׁ] [מִבָּנָ֔יו] a homem-de [הִ֖יא] [לְבָנָ֣יו] ela [אֲחֻזָּתָ֥ם] [הִ֖יא] [בְּנַחֲלָֽה]');
INSERT INTO verses VALUES (21741, 26, 46, 17, 'e-quando [מַתָּנָ֜ה] [מִנַּחֲלָת֗וֹ] [לְאַחַד֙] para-um [וְהָ֤יְתָה] para-ele a-ele até ano-de [לַנָּשִׂ֑יא] [אַ֚ךְ] [נַחֲלָת֔וֹ] somente a-eles [תִּהְיֶֽה] a-eles [sem-traducao]');
INSERT INTO verses VALUES (21742, 26, 46, 18, 'e-não [הַנָּשִׂ֜יא] [מִנַּחֲלַ֣ת] [הָעָ֗ם] o povo [מֵאֲחֻזָּתָ֔ם] [מֵאֲחֻזָּת֖וֹ] [יַנְחִ֣ל] [אֶת־בָּנָ֑יו] a [אֲשֶׁ֣ר] a-fim-de que não [מֵאֲחֻזָּתֽוֹ] homem');
INSERT INTO verses VALUES (21743, 26, 46, 19, '[וַיְבִיאֵ֣נִי] [בַמָּבוֹא֮] que sobre [הַשַּׁעַר֒] [אֶל־הַלִּשְׁכ֤וֹת] a [אֶל־הַכֹּ֣הֲנִ֔ים] a-santidade a os-sacerdotes lugar para-o-norte e-eis- nome lugar para-o-mar');
INSERT INTO verses VALUES (21744, 26, 46, 20, 'E-disse a-mim este [הַמָּק֗וֹם] que [יְבַשְּׁלוּ־שָׁם֙] nome os-sacerdotes a [אֲשֶׁ֤ר] e-[OBJ] [אֶת־הַמִּנְחָ֔ה] para-não [הוֹצִ֛יא] a a oferta-cereais para-não [אֶת־הָעָֽם] a a');
INSERT INTO verses VALUES (21745, 26, 46, 21, '[וַיּוֹצִיאֵ֗נִי] a o-pateo [וַיַּ֣עֲבִירֵ֔נִי] [אֶל־אַרְבַּ֖עַת] a [הֶחָצֵ֑ר] [וְהִנֵּ֤ה] [חָצֵר֙] e-eis [הֶחָצֵ֔ר] [חָצֵ֖ר] [בְּמִקְצֹ֥עַ] [הֶחָצֵֽר] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (21746, 26, 46, 22, '[בְּאַרְבַּ֜עַת] [מִקְצֹע֤וֹת] o-pateo [חֲצֵר֣וֹת] [קְטֻר֔וֹת] quarenta comprimento e-trinta [רֹ֑חַב] medida uma [לְאַרְבַּעְתָּ֖ם]');
INSERT INTO verses VALUES (21747, 26, 46, 23, '[וְט֨וּר] ao-redor [בָּהֶ֛ם] ao-redor [לְאַרְבַּעְתָּ֑ם] [וּמְבַשְּׁל֣וֹת] [עָשׂ֔וּי] debaixo-de [הַטִּיר֖וֹת] ao-redor');
INSERT INTO verses VALUES (21748, 26, 46, 24, 'E-disse a-mim Estas casa [הַֽמְבַשְּׁלִ֔ים] que [יְבַשְּׁלוּ־שָׁ֛ם] nome [הַבַּ֖יִת] [אֶת־זֶ֥בַח] a sacrifício o-povo');
INSERT INTO chapters VALUES (849, 26, 47, 23);
INSERT INTO verses VALUES (21749, 26, 47, 1, '[וַיְשִׁבֵנִי֮] a [הַבַּיִת֒] [וְהִנֵּה־מַ֣יִם] e-eis debaixo-de [מִפְתַּ֤ן] [הַבַּ֙יִת֙] [קָדִ֔ימָה] [כִּֽי־פְנֵ֥י] [הַבַּ֖יִת] porque face-de [יֹרְדִ֗ים] debaixo-de [מִכֶּ֤תֶף] [הַבַּ֙יִת֙] [הַיְמָנִ֔ית] [מִנֶּ֖גֶב] [לַמִּזְבֵּֽחַ]');
INSERT INTO verses VALUES (21750, 26, 47, 2, '[וַיּוֹצִאֵנִי֮] [דֶּֽרֶךְ־שַׁ֣עַר] portão [וַיְסִבֵּ֙נִי֙] o-caminho-de caminho [אֶל־שַׁ֣עַר] a o-caminho-de o-fora caminho [וְהִנֵּה־מַ֣יִם] [מְפַכִּ֔ים] e-eis- águas de');
INSERT INTO verses VALUES (21751, 26, 47, 3, '[בְּצֵאת־הָאִ֥ישׁ] o-homem [וְקָ֣ו] [בְּיָד֑וֹ] na-sua-mão e-mediu mil na-côvado [בַמַּ֖יִם] [מֵ֥י] águas-de');
INSERT INTO verses VALUES (21752, 26, 47, 4, '[וַיָּ֣מָד] mil [וַיַּעֲבִרֵ֥נִי] [בַמַּ֖יִם] águas [בִּרְכָּ֑יִם] [וַיָּ֣מָד] mil [וַיַּעֲבִרֵ֖נִי] águas-de [מָתְנָֽיִם]');
INSERT INTO verses VALUES (21753, 26, 47, 5, '[וַיָּ֣מָד] mil [נַ֕חַל] que não posso [כִּֽי־גָא֤וּ] porque [מֵ֣י] as-águas águas-de [אֲשֶׁ֥ר] [לֹֽא־יֵעָבֵֽר] que não');
INSERT INTO verses VALUES (21754, 26, 47, 6, 'E-disse para-mim [הֲרָאִ֣יתָ] filho-de homem [וַיְשִׁבֵ֖נִי] [שְׂפַ֥ת] beira-de');
INSERT INTO verses VALUES (21755, 26, 47, 7, '[בְּשׁוּבֵ֕נִי] e-eis a [הַנַּ֔חַל] árvore árvore muito muito de-este');
INSERT INTO verses VALUES (21756, 26, 47, 8, 'E-disse a-mim as-águas estes [יוֹצְאִ֗ים] a [הַקַּדְמוֹנָ֔ה] [וְיָרְד֖וּ] [עַל־הָֽעֲרָבָ֑ה] sobre [הַיָּ֔מָּה] [אֶל־הַיָּ֥מָּה] [הַמּֽוּצָאִ֖ים] a [**וְנִרְפּ֥וּ] as-águas as-águas');
INSERT INTO verses VALUES (21757, 26, 47, 9, 'e-foi todo vivente [׀] que a El todo que vira nome [וְהָיָ֥ה] [הַדָּגָ֖ה] e-acontecerá muito que muito porque [הַמַּ֣יִם] para-lá as-águas estes [כֹּ֛ל] [אֲשֶׁר־יָ֥בוֹא] todo que [sem-traducao] para lá [sem-traducao]');
INSERT INTO verses VALUES (21758, 26, 47, 10, 'e-será sobre-ele [**עָמְד֨וּ] [עָלָ֜יו] [דַּוָּגִ֗ים] e-até olho [וְעַד־עֵ֣ין] [עֶגְלַ֔יִם] [מִשְׁט֥וֹחַ] [לַֽחֲרָמִ֖ים] [יִהְי֑וּ] será [תִּהְיֶ֣ה] [דְגָתָ֔ם] o-mar o-mar multiplicai muito');
INSERT INTO verses VALUES (21759, 26, 47, 11, '[*בצאתו] e-não [וּגְבָאָ֛יו] [וְלֹ֥א] foram-dados');
INSERT INTO verses VALUES (21760, 26, 47, 12, 'e-sobre subia subir sobre [׀] [וּמִזֶּ֣ה] [׀] todo árvore-de [עָלֵ֜הוּ] não [פִּרְי֗וֹ] [לָֽחֳדָשָׁיו֙] e-não que [מֵימָ֔יו] [מִן־הַמִּקְדָּ֖שׁ] [הֵ֣מָּה] porque [*והיו] de [פִרְיוֹ֙] para-alimento [וְעָלֵ֖הוּ] [לִתְרוּפָֽה׃]');
INSERT INTO verses VALUES (21761, 26, 47, 13, 'assim disse Adonai yhwh [גֵּ֤ה] [גְבוּל֙] que [תִּתְנַחֲל֣וּ] a a-terra [עָשָׂ֖ר] dez tribos-de Israel [חֲבָלִֽים]');
INSERT INTO verses VALUES (21762, 26, 47, 14, '[וּנְחַלְתֶּ֤ם] [אוֹתָהּ֙] homem [כְּאָחִ֔יו] que [נָשָׂ֙אתִי֙] a [לְתִתָּ֖הּ] [לַאֲבֹֽתֵיכֶ֑ם] [וְנָ֨פְלָ֜ה] a-terra a-terra a-vós a-vós');
INSERT INTO verses VALUES (21763, 26, 47, 15, '[וְזֶ֖ה] fronteira a-terra [לִפְאַ֨ת] [צָפ֜וֹנָה] de [הַגָּד֛וֹל] [הַדֶּ֥רֶךְ] [חֶתְלֹ֖ן] [לְב֥וֹא] [צְדָֽדָה]');
INSERT INTO verses VALUES (21764, 26, 47, 16, '[חֲמָ֤ת] [׀] [בֵּר֙וֹתָה֙] que entre território [דַּמֶּ֔שֶׂק] e-entre território Hamate [חָצֵר֙] [הַתִּיכ֔וֹן] que a fronteira-de [sem-traducao]');
INSERT INTO verses VALUES (21765, 26, 47, 17, 'e-será [גְב֜וּל] de [חֲצַ֤ר] [עֵינוֹן֙] [גְּב֣וּל] território [וְצָפ֥וֹן] [׀] [צָפ֖וֹנָה] [וּגְב֣וּל] Hamate e-[OBJ] [פְּאַ֥ת] [צָפֽוֹן]');
INSERT INTO verses VALUES (21766, 26, 47, 18, '[וּפְאַ֣ת] [קָדִ֡ים] [מִבֵּ֣ין] [חַוְרָ֣ן] [וּמִבֵּין־דַּמֶּשֶׂק֩] [וּמִבֵּ֨ין] [הַגִּלְעָ֜ד] [וּמִבֵּ֨ין] terra terra Israel o-Jordão [עַל־הַיָּ֥ם] sobre o-mar e-[OBJ] [פְּאַ֥ת] e-[OBJ]');
INSERT INTO verses VALUES (21767, 26, 47, 19, '[וּפְאַת֙] Neguebe [תֵּימָ֔נָה] [מִתָּמָ֗ר] até [מְרִיב֣וֹת] [קָדֵ֔שׁ] [נַחֲלָ֖ה] heranca a e-[OBJ] [פְּאַת־תֵּימָ֖נָה] e-[OBJ] canto para-o-sul ao-sul');
INSERT INTO verses VALUES (21768, 26, 47, 20, 'e-lado-de o-mar [הַגָּד֔וֹל] a-grande [עַד־נֹ֖כַח] até [חֲמָ֑ת] esta Hamate esta canto mar');
INSERT INTO verses VALUES (21769, 26, 47, 21, '[וְחִלַּקְתֶּ֞ם] a a-terra a-vós para-vocês [יִשְׂרָאֵֽל] Israel');
INSERT INTO verses VALUES (21770, 26, 47, 22, 'e-foi [תַּפִּ֣לוּ] [אוֹתָהּ֮] [בְּנַחֲלָה֒] a-vós [וּלְהַגֵּרִים֙] [הַגָּרִ֣ים] [בְּתוֹכְכֶ֔ם] que filhos filhos e-sejam a-vós para-vós [בִּבְנֵ֣י] [יִשְׂרָאֵ֔ל] Israel com-vós [בְנַחֲלָ֔ה] no-meio-de em-meio-de tribos-de Israel');
INSERT INTO verses VALUES (21771, 26, 47, 23, 'e-foi [בַשֵּׁ֔בֶט] que [הַגֵּ֖ר] [אִתּ֑וֹ] com-ele nome [נַחֲלָת֔וֹ] herança-sua oráculo-de Adonai yhwh');
INSERT INTO chapters VALUES (850, 26, 48, 35);
INSERT INTO verses VALUES (21772, 26, 48, 1, 'e-estes nomes-de [הַשְּׁבָטִ֑ים] da-extremidade-de para-o-norte a mão [׀] [לְֽבוֹא־חֲמָ֡ת] [חֲצַ֣ר] [עֵינָן֩] átrio-de [דַּמֶּ֤שֶׂק] [צָפ֙וֹנָה֙] [אֶל־יַ֣ד] [חֲמָ֔ת] a mão o-mar [דָּ֥ן] um [sem-traducao] [sem-traducao] o-mar Dã um');
INSERT INTO verses VALUES (21773, 26, 48, 2, 'e-sobre território Dã do-canto [מִפְּאַ֥ת] até canto [אָשֵׁ֥ר] um um');
INSERT INTO verses VALUES (21774, 26, 48, 3, 'e-sobre território que do-canto [מִפְּאַ֥ת] e-até canto [נַפְתָּלִ֥י] um um');
INSERT INTO verses VALUES (21775, 26, 48, 4, 'e-sobre fronteira [גְּב֣וּל] do-canto [מִפְּאַ֥ת] até canto [מְנַשֶּׁ֥ה] um um');
INSERT INTO verses VALUES (21776, 26, 48, 5, 'e-sobre fronteira [גְּב֣וּל] do-canto [מִפְּאַ֥ת] até canto [אֶפְרַ֥יִם] um um');
INSERT INTO verses VALUES (21777, 26, 48, 6, 'e-sobre fronteira Efraim do-canto [מִפְּאַ֥ת] e-até canto [רְאוּבֵ֥ן] um um');
INSERT INTO verses VALUES (21778, 26, 48, 7, 'e-sobre território Rúben do-canto [מִפְּאַ֥ת] até canto [יְהוּדָ֥ה] um um');
INSERT INTO verses VALUES (21779, 26, 48, 8, 'e-sobre território Judá do-canto [קָדִ֖ים] até canto para-o-mar será [חֲמִשָּׁה֩] que [אֶ֜לֶף] [רֹ֗חַב] [וְאֹ֜רֶךְ] como-um-de [הַחֲלָקִים֙] [מִפְּאַ֤ת] [קָדִ֙ימָה֙] [עַד־פְּאַת־יָ֔מָּה] [וְהָיָ֥ה] [הַמִּקְדָּ֖שׁ] até');
INSERT INTO verses VALUES (21780, 26, 48, 9, '[הַתְּרוּמָ֕ה] que [תָּרִ֖ימוּ] para-יהוה comprimento cinco e-vinte mil e-largura dez [אֲלָפִֽים]');
INSERT INTO verses VALUES (21781, 26, 48, 10, '[וּ֠לְאֵ֜לֶּה] será [תְרֽוּמַת־הַקֹּדֶשׁ֮] [לַכֹּֽהֲנִים֒] [צָפ֜וֹנָה] [חֲמִשָּׁ֧ה] cinco [אֶ֗לֶף] mil [רֹ֚חַב] [עֲשֶׂ֣רֶת] dez milhares [רֹ֚חַב] [עֲשֶׂ֣רֶת] dez milhares [אֹ֕רֶךְ] [חֲמִשָּׁ֥ה] cinco e-vinte mil e-acontecerá [בְּתוֹכֽוֹ] yhwh');
INSERT INTO verses VALUES (21782, 26, 48, 11, '[לַכֹּהֲנִ֤ים] [הַֽמְקֻדָּשׁ֙] de-filhos-de [צָד֔וֹק] que [שָׁמְר֖וּ] [מִשְׁמַרְתִּ֑י] que não [בִּתְעוֹת֙] [בְּנֵ֣י] filhos-de Israel como-que [הַלְוִיִּֽם׃]');
INSERT INTO verses VALUES (21783, 26, 48, 12, '[וְהָיְתָ֨ה] a-eles [תְּרוּמִיָּ֛ה] [מִתְּרוּמַ֥ת] a-terra santo-de [קָדָשִׁ֑ים] a [הַלְוִיִּֽם]');
INSERT INTO verses VALUES (21784, 26, 48, 13, 'e-os-levitas [לְעֻמַּת֙] território os-sacerdotes cinco e-vinte mil comprimento e-largura dez milhares todo comprimento cinco e-vinte mil e-largura dez [sem-traducao]');
INSERT INTO verses VALUES (21785, 26, 48, 14, 'e-não nós [וְלֹ֥א] e-não [וְלֹ֥א] e-não [**יַעֲבִ֖יר] a-terra a-terra santidade para-יהוה');
INSERT INTO verses VALUES (21786, 26, 48, 15, '[וַחֲמֵ֨שֶׁת] milhares [הַנּוֹתָ֣ר] [בָּרֹ֗חַב] sobre cinco e-vinte mil [חֹֽל־ה֣וּא] ele [לְמוֹשָׁ֖ב] [וּלְמִגְרָ֑שׁ] [וְהָיְתָ֥ה] [הָעִ֖יר] a-cidade');
INSERT INTO verses VALUES (21787, 26, 48, 16, '[וְאֵלֶּה֮] [מִדּוֹתֶיהָ֒] [פְּאַ֣ת] [צָפ֗וֹן] cinco [מֵאוֹת֙] [וְאַרְבַּ֣עַת] [אֲלָפִ֔ים] e-lado-de [חֲמֵ֥שׁ] cinco centenas [וְאַרְבַּ֣עַת] milhares [וּמִפְּאַ֣ת] [קָדִ֗ים] cinco [מֵאוֹת֙] [וְאַרְבַּ֣עַת] [אֲלָפִ֔ים] e-lado-de [חֲמֵ֥שׁ] cinco centenas [אֲלָפִֽים] [sem-traducao]');
INSERT INTO verses VALUES (21788, 26, 48, 17, 'e-foi [מִגְרָשׁ֮] [לָעִיר֒] [צָפ֙וֹנָה֙] cinquenta [וּמָאתַ֔יִם] [וְנֶ֖גְבָּה] cinquenta [וּמָאתָ֑יִם] [וְקָדִ֙ימָה֙] cinquenta [וּמָאתַ֔יִם] [וְיָ֖מָּה] cinquenta e-duzentos');
INSERT INTO verses VALUES (21789, 26, 48, 18, '[וְהַנּוֹתָ֨ר] [בָּאֹ֜רֶךְ] [לְעֻמַּ֣ת] oferta-de [תְּרוּמַ֣ת] [הַקֹּ֗דֶשׁ] [עֲשֶׂ֨רֶת] [אֲלָפִ֤ים] [קָדִ֙ימָה֙] milhares [אֲלָפִים֙] e-será [וְהָיָ֕ה] oferta-de a-santidade e-será [וְהָיְתָ֤ה] [*תבואתה] a-cidade');
INSERT INTO verses VALUES (21790, 26, 48, 19, '[וְהָעֹבֵ֖ד] a-cidade [יַעַבְד֕וּהוּ] de-toda tribos-de Israel');
INSERT INTO verses VALUES (21791, 26, 48, 20, 'todo [חֲמִשָּׁ֤ה] cinco e-vinte mil [וְעֶשְׂרִ֖ים] e-vinte mil [תָּרִ֙ימוּ֙] [אֶת־תְּרוּמַ֣ת] a oferta-de o-santuário a');
INSERT INTO verses VALUES (21792, 26, 48, 21, '[וְהַנּוֹתָ֣ר] [לַנָּשִׂ֣יא] [מִזֶּ֣ה] [׀] [וּמִזֶּ֣ה] [׀] [לִתְרֽוּמַת־הַקֹּ֣דֶשׁ] [וְלַאֲחֻזַּ֪ת] a face-de [חֲמִשָּׁה֩] [וְעֶשְׂרִ֨ים] [אֶ֥לֶף] [׀] até território [קָדִימָה֒] [וְיָ֗מָּה] sobre face-de cinco e-vinte mil sobre território [חֲלָקִ֖ים] próximo-a [וְהָֽיְתָה֙] [תְּרוּמַ֣ת] e-será oferta-de o-santuário [*בתוכה] a-casa');
INSERT INTO verses VALUES (21793, 26, 48, 22, '[וּמֵאֲחֻזַּ֤ת] os-levitas [וּמֵאֲחֻזַּ֣ת] a-cidade no-meio-de que [לַנָּשִׂ֖יא] será entre território Judá [יְהוּדָ֗ה] e-entre בִּנְיָמִן [בִּנְיָמִ֔ן] será');
INSERT INTO verses VALUES (21794, 26, 48, 23, '[וְיֶ֖תֶר] [הַשְּׁבָטִ֑ים] do-canto [קָדִ֛ימָה] até canto um um');
INSERT INTO verses VALUES (21795, 26, 48, 24, 'e-sobre território [גְּב֣וּל] do-canto [מִפְּאַ֥ת] até canto [שִׁמְע֥וֹן] um um');
INSERT INTO verses VALUES (21796, 26, 48, 25, 'e-sobre território [גְּב֣וּל] do-canto [מִפְּאַ֥ת] até canto [יִשָׂשכָ֥ר] um um');
INSERT INTO verses VALUES (21797, 26, 48, 26, 'e-sobre território [גְּב֣וּל] do-canto [מִפְּאַ֥ת] até canto [זְבוּלֻ֥ן] um um');
INSERT INTO verses VALUES (21798, 26, 48, 27, 'e-sobre fronteira [גְּב֣וּל] do-canto [מִפְּאַ֥ת] até canto [גָּ֥ד] um um');
INSERT INTO verses VALUES (21799, 26, 48, 28, 'e-sobre fronteira [גָּ֔ד] a [נֶ֣גֶב] Neguebe [וְהָיָ֨ה] e-será [מִתָּמָ֗ר] [מֵ֚י] [מְרִיבַ֣ת] [קָדֵ֔שׁ] [נַחֲלָ֖ה] heranca sobre o-mar o-grande');
INSERT INTO verses VALUES (21800, 26, 48, 29, 'esta a-terra que [מִֽנַּחֲלָ֖ה] [לְשִׁבְטֵ֣י] [יִשְׂרָאֵ֑ל] Israel [מַחְלְקוֹתָ֔ם] [נְאֻ֖ם] oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (21801, 26, 48, 30, '[וְאֵ֖לֶּה] [תּוֹצְאֹ֣ת] a-cidade [מִפְּאַ֣ת] norte cinco centenas [וְאַרְבַּ֥עַת] dois-mil [מִדָּֽה]');
INSERT INTO verses VALUES (21802, 26, 48, 31, '[וְשַׁעֲרֵ֣י] a-cidade sobre nomes-de tribos-de Israel [שְׁלוֹשָׁ֖ה] [צָפ֑וֹנָה] para-o-norte portão um um porta-de um um portão-de um um');
INSERT INTO verses VALUES (21803, 26, 48, 32, 'e-a [קָדִ֗ימָה] [חֲמֵ֤שׁ] cinco novecentos [אֲלָפִ֔ים] milhares [שְׁלֹשָׁ֑ה] [וְשַׁ֨עַר] [יוֹסֵ֜ף] um um porta-de um um portão-de um um');
INSERT INTO verses VALUES (21804, 26, 48, 33, 'e-lado-de para-o-sul cinco centenas [אֲלָפִים֙] milhares [וּשְׁעָרִ֖ים] [שְׁלֹשָׁ֑ה] [שַׁ֣עַר] portão um um porta-de um um portão-de um um');
INSERT INTO verses VALUES (21805, 26, 48, 34, 'canto mar-direção cinco novecentos [אֲלָפִ֔ים] milhares [שְׁלֹשָׁ֑ה] [שַׁ֣עַר] portão um um porta-de um um portão-de um um');
INSERT INTO verses VALUES (21806, 26, 48, 35, '[סָבִ֕יב] oito dez mil e-Shem a-cidade yhwh יְהוָה ali');
INSERT INTO books VALUES (27, 'DAN', 'Daniel', 'AT', 12);
INSERT INTO chapters VALUES (851, 27, 1, 21);
INSERT INTO verses VALUES (21807, 27, 1, 1, 'em-ano-de três para-reinado Joiás rei-de Judá veio Nebucadnezzar rei-de Babilônia Jerusalém וַיָּ֥צַר sobre-ela');
INSERT INTO verses VALUES (21808, 27, 1, 2, 'E-colocou Adonai em-a-sua-mão a Joiás rei-de Judá e-miqtsat instrumentos-de casa-de הָֽאֱלֹהִ֔ים ve-yeviam terra-de Shinar casa Elohim-seu e-a hevi casa tesouro Elohim-dele');
INSERT INTO verses VALUES (21809, 27, 1, 3, 'E-disse o-rei le-ashpenaz muito sarisay para trazer filhos Israel e-saemente a-majestade e-de os-aventureiros:');
INSERT INTO verses VALUES (21810, 27, 1, 4, 'filhos que não há neles todo e-bons vista e-inteligentes em-todo sabedoria e os que conhecem conhecimento e compreensivo entendimento e que força neles para-ficar-em-pé em-templo-de o-rei e lhes ensineis livro וּלְשׁ֥וֹן coshdeem');
INSERT INTO verses VALUES (21811, 27, 1, 5, 'e manterá a-eles o-rei palavra-de dia no seu dia de sua בַּ֤ג o rei e de seu dos seus e para os fazer crescer dois três e de parte deles estarão-em-pé diante-de o rei');
INSERT INTO verses VALUES (21812, 27, 1, 6, 'e-houve neles de-filhos-de Judá Daniel Hanãia מִישָׁאֵ֖ל וַעֲזַרְיָֽה׃');
INSERT INTO verses VALUES (21813, 27, 1, 7, 'e-ele-posto a-eles príncipe os sarissim שֵׁמ֑וֹת e-ele-postou לְדָֽנִיֵּ֜אל בֵּ֣לְטְשַׁאצַּ֗ר e-lá-chananyah שַׁדְרַ֔ךְ וּלְמִֽישָׁאֵ֣ל מֵישַׁ֔ךְ וְלַעֲזַרְיָ֖ה servo נְגֽוֹ׃');
INSERT INTO verses VALUES (21814, 27, 1, 8, 'e-ele-colocou daniel sobre coração-dele que não [הַמֶּ֖לֶךְ] [וּבְיֵ֣ין] o-rei [וַיְבַקֵּשׁ֙] [מִשַּׂ֣ר] [הַסָּרִיסִ֔ים] [אֲשֶׁ֖ר] não que não');
INSERT INTO verses VALUES (21815, 27, 1, 9, 'E-colocou הָֽאֱלֹהִים a דנייאל לחסד e para os misericordiosos diante-de príncipe os-eunucos');
INSERT INTO verses VALUES (21816, 27, 1, 10, 'E-disse príncipe [הַסָּרִיסִים֙] לְדָ֣נִיֵּ֔אל temer eu a Adonai o-rei que [אֶת־מַאֲכַלְכֶ֖ם] a [אֲשֶׁ֡ר] e-a [יִרְאֶ֨ה] que por-que ele-vera a [כְּגִֽילְכֶ֔ם] [וְחִיַּבְתֶּ֥ם] de os-meninos que a para-o rei');
INSERT INTO verses VALUES (21817, 27, 1, 11, 'E-disse דָּנִיֵּ֖אל a הַמֶּלְצַ֑ר que מִנָּה֙ comandante-de os sarissim sobre DANIEL Channanyah Mishael וַעֲזַרְיָֽה׃');
INSERT INTO verses VALUES (21818, 27, 1, 12, 'Nas- agora a servos-teus dias Asaraha e enten- nun- de os zar''oim e ne''achela e mayim e bebamos');
INSERT INTO verses VALUES (21819, 27, 1, 13, 'e se verem diante-de-ti nossos olhos וּמַרְאֵה֙ os meninos os comedores את farpeta-gemidos o-rei e conforme vires-te fez com servos-teus');
INSERT INTO verses VALUES (21820, 27, 1, 14, 'E-ouviu a-eles para-a-palavra esta e os ensinou dias dez:');
INSERT INTO verses VALUES (21821, 27, 1, 15, 'e-miqtsat dias dez foi revelada [מַרְאֵיהֶם֙] bom [וּבְרִיאֵ֖י] carne de todo as crianças [פַּתְבַּ֥ג] את o rei');
INSERT INTO verses VALUES (21822, 27, 1, 16, 'e-houve [הַמֶּלְצַ֗ר] [נֹשֵׂא֙] a [וְיֵ֖ין] e-vinho de-sua-bebida a-eles a-eles');
INSERT INTO verses VALUES (21823, 27, 1, 17, '[וְהַיְלָדִ֤ים] estes [אַרְבַּעְתָּ֔ם] dar a-eles o-elohim [מַדָּ֥ע] [וְהַשְׂכֵּ֖ל] em-todo livro [וְדָנִיֵּ֣אל] e Daniel [בְּכָל־חָז֖וֹן] em-todo visão');
INSERT INTO verses VALUES (21824, 27, 1, 18, '[וּלְמִקְצָת֙] os-dias que disse o-rei [וַיְבִיאֵם֙] [שַׂ֣ר] comandante-de [לִפְנֵ֖י] diante-de');
INSERT INTO verses VALUES (21825, 27, 1, 19, 'e-falou [אִתָּם֮] [הַמֶּלֶךְ֒] e-não [נִמְצָא֙] [מִכֻּלָּ֔ם] [כְּדָנִיֵּ֣אל] [חֲנַנְיָ֔ה] [מִֽישָׁאֵ֖ל] [וַעֲזַרְיָ֑ה] [וַיַּֽעַמְד֖וּ] diante-de o rei');
INSERT INTO verses VALUES (21826, 27, 1, 20, 'e-tudo palavra sabedoria-de בִּינָה que בִּקֵּשׁ deles o-rei וַיִּמְצָאֵם dez sobre sobre todo os-sábios as fumaças que em-todo seu-reino');
INSERT INTO verses VALUES (21827, 27, 1, 21, 'e-houve daniel até uma uma cruores o rei');
INSERT INTO chapters VALUES (852, 27, 2, 49);
INSERT INTO verses VALUES (21828, 27, 2, 1, 'e-em-ano-de shtayim para-ملكوته nebuchadnetzar sonhou nebuchadnetzar seus sonhos e se agitaram espírito-dele e a sua segunda tornou-se sobre-ele');
INSERT INTO verses VALUES (21829, 27, 2, 2, 'E-disse o-rei para ler aos charuttim e aos ashatim e-para os-mecâshafim e aos chasdim para dizer ao-rei seus sonhos e-vieram e se levantaram diante-de o rei');
INSERT INTO verses VALUES (21830, 27, 2, 3, 'E-disse a-eles o-rei sonho eu sonhei e as fizeram do-sopro para-conhecer את- o sonho:');
INSERT INTO verses VALUES (21831, 27, 2, 4, 'e falaram e falaram os caldeus os caldeus ao-rei ao rei arameu arameu o-rei rei para sempre para sempre viva viva disse sombra וּפִשְׁרָ֥א ainda');
INSERT INTO verses VALUES (21832, 27, 2, 5, 'respondeu o-rei e disse palavra de mim azada eis não eis sombra e lhe explicarás os hematomas vós os adorareis e-vos não serão feitos');
INSERT INTO verses VALUES (21833, 27, 2, 6, 'e eles o sonho e lhe explicarás vós o tendes a parte וּנְבִזְבָּה֙ e digno שַׁגִּיא vós o aceitareis de קֳדָמָ֑י לָהֵ֕ן חֶלְמָ֥א וּפִשְׁרֵ֖הּ הַחֲוֺֽנִי׃');
INSERT INTO verses VALUES (21834, 27, 2, 7, '[עֲנ֥וֹ] [תִנְיָנ֖וּת] [וְאָמְרִ֑ין] [מַלְכָּ֕א] [חֶלְמָ֛א] [יֵאמַ֥ר] [לְעַבְד֖וֹהִי] [וּפִשְׁרָ֥ה] [נְהַחֲוֵֽה]');
INSERT INTO verses VALUES (21835, 27, 2, 8, '[עָנֵ֤ה] o-rei e ele disse: de saber conheceu [דִּ֥י] que [אַנְתּ֣וּן] [זָבְנִ֑ין] [כָּל־קֳבֵל֙] todo porque que [אַזְדָּ֖א] que [מִלְּתָֽא] מִנּוֹ');
INSERT INTO verses VALUES (21836, 27, 2, 9, 'que eis חלהמה não informe-me uma-vez ela conhecimento e-palavra כִדְבָ֤ה e-destruição para-dizer diante-de-mim até que pobreza será-transformado elas חֶלְמָא֙ אֱמַ֣רוּ para-mim וֽ͏ְאִנְדַּ֕ע que פרשה תְּהַחֲוֻנַּֽנִי׃');
INSERT INTO verses VALUES (21837, 27, 2, 10, '[עֲנ֨וֹ] ANTE- o-rei [קֳדָם־מַלְכָּא֙] não [לָֽא־אִיתַ֤י] [אֲנָשׁ֙] sobre [דִּ֚י] que [מַלְכָּ֔א] o-rei podia [כָּל־קֳבֵ֗ל] todo קבֵל que todo rei muito [לָ֣א] [שְׁאֵ֔ל] [לְכָל־חַרְטֹּ֖ם] não [וְכַשְׂדָּֽי] para-todo');
INSERT INTO verses VALUES (21838, 27, 2, 11, 'וּמִלָּתָא que מלכה שָׁאַל יקרה ואחרנה não איתי que יחVINנה diante-de o-rei להן אליהון que מדRHוון com בשרא não איתיוהי׃');
INSERT INTO verses VALUES (21839, 27, 2, 12, 'todo [דְּנָ֔ה] isto [בְּנַ֖ס] [וּקְצַ֣ף] [שַׂגִּ֑יא] [וַאֲמַר֙] [לְה֣וֹבָדָ֔ה] a-todo para-todo [בָבֶֽל]');
INSERT INTO verses VALUES (21840, 27, 2, 13, 'והדרה נפקת e-sábios mitkatalin וּבְע֛וֹ דָּנִיֵּ֥אל וְחַבְר֖וֹהִי לְהִתְקְטָלָֽה׃');
INSERT INTO verses VALUES (21841, 27, 2, 14, 'בֵּאדַ֣יִן דָּנִיֵּ֗אל הֲתִיב֙ עֵטָ֣א e provou לְאַרְי֕וֹךְ muito טַבָּחַיָּ֖א que o-rei que נְפוֹק לְקַטְּלוֹתָ לְחַכְּמֵי Babilônia');
INSERT INTO verses VALUES (21842, 27, 2, 15, 'עֲנוֹה e-dirá לְאַרְיוֹךְ שַׁלִיטָא que o-rei sobre que דָתָא מְהַחְצְפָ֖ה de diante-de o-rei אֱדַיִן מִלְתָא faz saber Ariokh לְדָנִיֵאל׃');
INSERT INTO verses VALUES (21843, 27, 2, 16, '[וְדָ֣נִיֵּ֔אל] sobre [וּבְעָ֣ה] de o-rei que [יִנְ[t]תֵּן־לֵ֔הּ] [וּפִשְׁרָ֖א] lhe [לְמַלְכָּֽא׃] ao-rei');
INSERT INTO verses VALUES (21844, 27, 2, 17, 'אֱדַ֥יִן דָּֽנִיֵּ֖אל לְבַיְתֵ֣הּ אֲזַ֑ל וְ֠לַחֲנַנְיָה מִֽישָׁאֵ֧ל וַעֲזַרְיָ֛ה חַבְר֖וֹהִי palavra הוֹדַֽע׃');
INSERT INTO verses VALUES (21845, 27, 2, 18, '[וְרַחֲמִ֗ין] [לְמִבְעֵא֙] de [אֱלָ֣הּ] [שְׁמַיָּ֔א] שְׁמַיָ֔א sobre [דִּ֣י] Dana que não [וְחַבְר֔וֹהִי] דנייאל [חַכִּימֵ֥י] com resto');
INSERT INTO verses VALUES (21846, 27, 2, 19, 'אֱדַ֗יִן לְדָנִיֵּ֛אל בְּחֶזְוָ֥א que לֵילְיָ֖א רָזָ֣ה גֲלִי entao דָּֽנִיֵּ֔אל abençoou לֶאֱלָהּ שְׁמַיָּא׃');
INSERT INTO verses VALUES (21847, 27, 2, 20, '[עָנֵ֤ה] Daniel e ele disse: [לֶהֱוֵ֨א] [שְׁמֵ֤הּ] que [מְבָרַ֔ךְ] [מִן־עָלְמָ֖א] de [עָלְמָ֑א] e-até- eternidade [וּגְבוּרְתָ֖א] [דִּ֥י] [לֵֽהּ־הִֽיא] que ela');
INSERT INTO verses VALUES (21848, 27, 2, 21, 've-hu que transforma de sabedoria e tempo que ensina contra-reis e estabelece reis יָהֵ֤ב sabedoria para sábios e entendimento para os que conhecem inteligência;');
INSERT INTO verses VALUES (21849, 27, 2, 22, 'ele revelou profundidade e ocultação; saber que na escuridão, com ela sabedoria;');
INSERT INTO verses VALUES (21850, 27, 2, 23, 'para-ti Elah meu pai מְהוֹדֵ֤א וּמְשַׁבַּח֙ אֲנָ֔ה דִּ֧י חָכְמְתָ֛א וּגְבוּרְתָ֖א יְהַ֣בְתְּ para-mim e-que הֽוֹדַעְתַּ֙נִי֙ que בְעֵ֣ינָא מִנָּ֔ךְ que מִלּוֹת o-rei הוֹדַעְתֶּנָּה׃');
INSERT INTO verses VALUES (21851, 27, 2, 24, 'todo קֻבֵּל דְּנַה sobre sobre sobre אַרְיוֹךְ que מַנֶּי o-rei לְהוֹבָדָה לְחַכְּמֵי בָּבֶל אֲזַל ׀ e-assim אֲמַר־ lhe para-sábios Babel-em a tehovêd o-aleuni diante-de o-rei e-fisha para-malakha achavê:');
INSERT INTO verses VALUES (21852, 27, 2, 25, 'edain arikh בהיתבHALAH הנעל לדניIEL diante-de o-rei e-assim אמר- ליה que השכחת גברא de filhos-de גלותא que יהוד que פרשה para-rei Jehová:');
INSERT INTO verses VALUES (21853, 27, 2, 26, 'respondeu o-rei e-foi-dizer para-Daniel que seu-nome Belteseçasar Cahel para-me-dizer sonho que vi-te e lhe explicará');
INSERT INTO verses VALUES (21854, 27, 2, 27, 'ouvi Daniel ante o-rei e disse segredo que o rei pergunte não sábios confundam חַרְטֻמִּים גּוֹזְרִין יַכְלִין לְהַחֲוֵי ao-rei');
INSERT INTO verses VALUES (21855, 27, 2, 28, '[בְּרַ֡ם] [אִיתַ֞י] [אֱלָ֤הּ] [בִּשְׁמַיָּא֙] [גָּלֵ֣א] [רָזִ֔ין] [וְהוֹדַ֗ע] [לְמַלְכָּא֙] [נְבֽוּכַדְנֶצַּ֔ר] que que [לֶהֱוֵ֖א] no fundo [יוֹמַיָּ֑א] [חֶלְמָ֨ךְ] -e-visiones [רֵאשָׁ֛ךְ] sobre [דְּנָ֥ה] ele ela');
INSERT INTO verses VALUES (21856, 27, 2, 29, '[אַ֣נְתְּה] o-rei [רַעְיוֹנָךְ֙] sobre [סְלִ֔קוּ] [מָ֛ה] que que [אַחֲרֵ֣י] depois-de [וְגָלֵ֧א] [רָזַיָּ֛א] [הוֹדְעָ֖ךְ] [מָה־דִ֥י] o-quê');
INSERT INTO verses VALUES (21857, 27, 2, 30, 'e eu não com sabedoria que estou comigo em-mim de todo vivo vivo segredo e a revela para-mim elas sobre palavra de que פִשְׁרָא֙ לְמַלְכָּ֣א יְהוֹדְע֔וּן וְרַעְיוֹנֵ֥י לִבְבָ֖ךְ תִּנְדַּֽע׃');
INSERT INTO verses VALUES (21858, 27, 2, 31, '[אַ֣נְתְּה] o-rei חָזֵ֤ה [הֲוַ֙יְתָ֙] וַאֲל֨וּ imagem agudo [שַׂגִּ֔יא] [צַלְמָ֨א] [דִכֵּ֥ן] muito [וְזִיוֵ֥הּ] [יַתִּ֖יר] [קָאֵ֣ם] [לְקָבְלָ֑ךְ] [וְרֵוֵ֖הּ] [דְּחִֽיל]');
INSERT INTO verses VALUES (21859, 27, 2, 32, 'ele [צַלְמָ֗א] רֵאשֵׁהּ֙ que [טָ֔ב] [חֲד֥וֹהִי] [וּדְרָע֖וֹהִי] [דִּ֣י] que [מְע֥וֹהִי] [וְיַרְכָתֵ֖הּ] [דִּ֥י] que');
INSERT INTO verses VALUES (21860, 27, 2, 33, '[שָׁק֖וֹהִי] que [פַרְזֶ֑ל] [רַגְל֕וֹהִי] que [**מִנְּהֵין֙] que [פַרְזֶ֔ל]');
INSERT INTO verses VALUES (21861, 27, 2, 34, 'vision [הֲוַ֗יְתָ] até que [הִתְגְּזֶ֤רֶת] pedra que não [וּמְחָ֤ת] [לְצַלְמָא֙] [עַל־רַגְל֔וֹהִי] sobre [פַרְזְלָ֖א] que [וְהַדֵּ֖קֶת] [הִמּֽוֹן]');
INSERT INTO verses VALUES (21862, 27, 2, 35, 'בֵּאדַ֣יִן [דָּ֣קוּ] [כַחֲדָ֡ה] [פַּרְזְלָא֩] [חַסְפָּ֨א] [נְחָשָׁ֜א] [כַּסְפָּ֣א] [וְדַהֲבָ֗א] [וַהֲווֹ֙] [כְּע֣וּר] de [וּנְשָׂ֤א] [הִמּוֹן֙] [רוּחָ֔א] [וְכָל־אֲתַ֖ר] [לָא־הִשְׁתֲּכַ֣ח] e-todo [וְאַבְנָ֣א] não [דִּֽי־מְחָ֣ת] [לְצַלְמָ֗א] [הֲוָ֛ת] que [רַ֖ב] [וּמְלָ֥ת] [כָּל־אַרְעָֽא] muito todo ארעא׃');
INSERT INTO verses VALUES (21863, 27, 2, 36, '[דְּנָ֣ה] [חֶלְמָ֔א] [וּפִשְׁרֵ֖הּ] [נֵאמַ֥ר] ANTE-');
INSERT INTO verses VALUES (21864, 27, 2, 37, 'אנתה o-rei rei מלכיא que Elah שמיא מלכותא חיסנא וְתָקְפָּא E-chamou יהַב־ para-ti');
INSERT INTO verses VALUES (21865, 27, 2, 38, 'e-em-todo que filhos-de אנאשׁא חויאת criou וְעוֹף־ שמיאא יהַב בִּידָ֔ךְ e governarás em todo ele dize ele primeira que de ouro:');
INSERT INTO verses VALUES (21866, 27, 2, 39, 'e depois de ti arise rei depois de mim de ti וּמַלְכוּ אָחֳרִי que נְחָשָׂא que תִשְׁלַ֖ט em-todo אַרְעָא׃');
INSERT INTO verses VALUES (21867, 27, 2, 40, '[וּמַלְכוּ֙] [*רביעיה] [**רְבִ֣יעָאָ֔ה] [תֶּהֱוֵ֥א] todo קבֵל que [דִּ֤י] [פַרְזְלָא֙] [מְהַדֵּ֤ק] [וְחָשֵׁל֙] [כֹּ֔לָּא] que [דִּֽי־מְרָעַ֥ע] todo [תַּדִּ֥ק] [וְתֵרֹֽעַ]');
INSERT INTO verses VALUES (21868, 27, 2, 41, 'וְדִֽי־ viste pé-ela e-dedos-ela chaf que fara parzel malku pilega será e-de estava די פרזלא להיה- בה- todo porque que חזית- פרזלא מערב- בחסף- תינה:');
INSERT INTO verses VALUES (21869, 27, 2, 42, '[וְאֶצְבְּעָת֙] [רַגְלַיָּ֔א] [*מנהון] [**מִנְּהֵ֥ין] de [*ומנהון] מלכותא [חֲסַ֑ף] [מִן־קְצָ֤ת] [מַלְכוּתָא֙] [תֶּהֱוֵ֣ה] [תַקִּיפָ֔ה]');
INSERT INTO verses VALUES (21870, 27, 2, 43, 'chasayta parzala me''arab bachasaf tina mit''arbin lehaven bizar''a anasha e-não lehaven דָּבְקִ֖ין דְּנָ֣ה com דְּנָ֑ה הֵֽא־ כְדִ֣י פַרְזְלָ֔א não מִתְעָרַ֖ב com חַסְפָּֽא׃');
INSERT INTO verses VALUES (21871, 27, 2, 44, 'וּֽבְיוֹמֵיה֞וֹן דִּ֧י מלכיא אנון יקים אלוה שמיא מלוך que לעלמין não תחבל וממלכתה para-o-povo אחרון não tishbotq taddek vesef todo ilayn malkevata e-ela tqum le''almeiya');
INSERT INTO verses VALUES (21872, 27, 2, 45, 'todo kavbel que hazayta que pedra itgazarat אבן que não בידין והdequeת פרזלא נחשא CHASEPAA CASPEA VEDAHAVA אלה muito foi-conhecido ao-rei que que lehove depois-de דנה ויחזיב חלומא ומHEYMAN פרשה');
INSERT INTO verses VALUES (21873, 27, 2, 46, 'BEDAIYN מלכא Nabucodonosor נפל sobre אנפוهي ולדانيיאל /lgad u/minhah ve-nikhohin disse lensakha le-ha:');
INSERT INTO verses VALUES (21874, 27, 2, 47, 'aneh malkea ledanial e-dirá de keshot que ele ele Elohim אלים ומרא contra-reis וגלה רזין que יכלת לגלאה רזא דנה׃');
INSERT INTO verses VALUES (21875, 27, 2, 48, 'עדין מלכא DANIEL RABBI UMATANNAN RABBINAV SAGIYAN YEHAB- LEHU sobre sobre todo MEDINAT sobre e-grande SIGIN sobre todo CHAKHAMIM Babel:');
INSERT INTO verses VALUES (21876, 27, 2, 49, 'e Daniél, Be-ā'' de o-rei sobre sobre Avīd''thā'' que na cidade Babilônia l''Shardakh Mishakh, e-Abede Nego e Daniél, Be-trā'' Rei:');
INSERT INTO chapters VALUES (853, 27, 3, 33);
INSERT INTO verses VALUES (21877, 27, 3, 1, 'Nabucodonosor o-rei servo imagem que dahav ro''meh am''in shittin p''tayeh am''in shet akimeh bivik''at דּוּרָ֔א בִּמְדִינַ֖ת Babilônia');
INSERT INTO verses VALUES (21878, 27, 3, 2, '[וּנְבוּכַדְנֶצַּ֣ר] [מַלְכָּ֡א] enviou [לְמִכְנַ֣שׁ] [׀] [לַֽאֲחַשְׁדַּרְפְּנַיָּ֡א] [סִגְנַיָּ֣א] [וּֽפַחֲוָתָ֡א] [אֲדַרְגָּזְרַיָּא֩] [גְדָ֨בְרַיָּ֤א] [דְּתָבְרַיָּא֙] e-todo e-tudo [שִׁלְטֹנֵ֣י] [מְדִֽינָתָ֑א] [לְמֵתֵא֙] [לַחֲנֻכַּ֣ת] que [דִּ֥י] [הֲקֵ֖ים] [נְבוּכַדְנֶצַּ֥ר]');
INSERT INTO verses VALUES (21879, 27, 3, 3, 'בֵּאדַיִן מִתְכַּנְּשִׁ֡ין אֲחַשְׁדַּרְפְּנַיָּ֡א סִגְנַיָּ֣א וּפַחֲוָתָ֡א אֲדַרְגָּזְרַיָּ֣א גְדָבְרַיָּא֩ דְּתָ֨בְרַיָּ֜א תִּפְתָּיֵ֗א e-tudo שִׁלְטֹנֵ֣י מְדִֽינָתָ֔א para a dedicação de-Salma que eleve Nabucodonosor o-rei diante-de de-Salma que eleve Nabucodonosor:');
INSERT INTO verses VALUES (21880, 27, 3, 4, 'e proclame chamou com força para estabelecer אָמְרִין֙ עַֽמְמַיָּ֔א אֻמַּיָּ֖א וְלִשָּׁנַיָּֽא׃');
INSERT INTO verses VALUES (21881, 27, 3, 5, '[בְּעִדָּנָ֡א] que [קָ֣ל] [קַרְנָ֣א] [מַ֠שְׁרוֹקִיתָא] [*קיתרוס] [**קַתְר֨וֹס] [סַבְּכָ֤א] [פְּסַנְתֵּרִין֙] e-todo e-tudo [זְנֵ֣י] [זְמָרָ֑א] [תִּפְּל֤וּן] [וְתִסְגְּדוּן֙] [לְצֶ֣לֶם] que [דִּ֥י] [הֲקֵ֖ים] [נְבוּכַדְנֶצַּ֥ר]');
INSERT INTO verses VALUES (21882, 27, 3, 6, '[וּמַן־דִּי־לָ֥א] que não [בַּהּ־שַׁעֲתָ֣א] [יִתְרְמֵ֔א] [לְגֽוֹא־אַתּ֥וּן] [נוּרָ֖א] [יָקִֽדְתָּֽא]');
INSERT INTO verses VALUES (21883, 27, 3, 7, 'todo [דְּנָ֡ה] [בֵּהּ־זִמְנָ֡א] [כְּדִ֣י] [שָֽׁמְעִ֣ין] [כָּֽל־עַמְמַיָּ֡א] [קָ֣ל] todo [מַשְׁר֨וֹקִיתָ֜א] [*קיתרס] [**קַתְר֤וֹס] [שַׂבְּכָא֙] [פְּסַנְטֵרִ֔ין] e-tudo e-todo [זְמָרָ֑א] [נָֽפְלִ֨ין] [כָּֽל־עַֽמְמַיָּ֜א] todo [וְלִשָּׁנַיָּ֗א] [סָֽגְדִין֙] [לְצֶ֣לֶם] [דַּהֲבָ֔א] [דִּ֥י] [הֲקֵ֖ים] que [מַלְכָּֽא]');
INSERT INTO verses VALUES (21884, 27, 3, 8, 'todo [דְּנָה֙] esta [קְרִ֖בוּ] [גֻּבְרִ֣ין] [כַּשְׂדָּאִ֑ין] [וַאֲכַ֥לוּ] [קַרְצֵיה֖וֹן] [דִּ֥י] [יְהוּדָיֵֽא] que');
INSERT INTO verses VALUES (21885, 27, 3, 9, '[עֲנוֹ֙] [וְאָ֣מְרִ֔ין] [לִנְבוּכַדְנֶצַּ֖ר] o-rei o-rei para os séculos minha vida:');
INSERT INTO verses VALUES (21886, 27, 3, 10, 'MALKĀʾ- [**אַ֣נְתְּ] [מַלְכָּא֮] que todo ENĀŠ que [דִּֽי־יִשְׁמַ֡ע] [קָ֣ל] [קַרְנָ֣א] [מַ֠שְׁרֹקִיתָא] [*קיתרס] [**קַתְר֨וֹס] e-todo [פְסַנְתֵּרִין֙] [*וסיפניה] [**וְסוּפֹּ֣נְיָ֔ה] e-tudo [זְנֵ֣י] [זְמָרָ֑א]');
INSERT INTO verses VALUES (21887, 27, 3, 11, '[וּמַן־דִּי־לָ֥א] que não [יִתְרְמֵ֕א] [לְגֽוֹא־אַתּ֥וּן]  yitremê''  [יָקִֽדְתָּֽא]');
INSERT INTO verses VALUES (21888, 27, 3, 12, 'אִיתַ֞י גֻּבְרִ֣ין יְהוּדָאיִן que מַנִּ֤יתָ יָתְהוֹן֙ sobre עֲבִידַת֙ מְדִינַ֣ת Babilônia שַׁדְרַ֥ךְ מֵישַׁ֖ךְ e-Abede Nego גֻּבְרַיָּ֣א אֲלֹהִים não שָׂם o-rei decreto não פָּלַחַיִן וְלְצֶלֶם דָּהַב que הִקְמַתְּ não סָגַדְּ');
INSERT INTO verses VALUES (21889, 27, 3, 13, 'בְּאָדַיִן נְבֻכַדְנֶצַּר בָּרַגְז וַחֲמָ֔ה disse לְהַיְתָיָ֔ה לְשַׁדְרַ֥ךְ מֵישַׁ֖ךְ e-Abede Nego בֵּאדַ֙יִן֙ גֻּבְרַיָּ֣א אִלֵּ֔ךְ הֵיתָ֖יוּ קֳדָ֥ם מַלְכָּֽא׃');
INSERT INTO verses VALUES (21890, 27, 3, 14, 'respondeu Nabucodonosor e disse a eles o justo Sardac Mesec e-Abede Nego ó meu Elohim não eu vos peço Belim e ao seu elohim דַהֲבָא que הֲקֵ֖ימֶת não סָֽגְדִֽין׃');
INSERT INTO verses VALUES (21891, 27, 3, 15, 'כְּעַ֞ן eis אִֽיתֵיכ֣וֹן עֲתִידִ֗ין que בְעִדָּנָ֡א que תִשְׁמְע֡וּן קָ֣ל קַרְנָ֣א Mashroqita'' Saba''ka Pshantarin Ve''Sumpnyah e-todo e-tudo Zamar''a Tipulun Ve''Tisgudun LeTzalma que Avdet e-eis não Tisgudun בַּהּ־ שַׁעֲתָ֣ה תִתְרְמ֔וֹן לְגֽוֹא־ אַתּ֥וּן נוּרָ֖א יָקִֽדְתָּ֑א וּמַן־ ele אֱלָ֔הּ דֵּ֥י יְשֵֽׁיזְבִנְכ֖וֹן de יְדָֽי׃');
INSERT INTO verses VALUES (21892, 27, 3, 16, '[עֲנ֗וֹ] [שַׁדְרַ֤ךְ] [מֵישַׁךְ֙] [וַעֲבֵ֣ד] [נְג֔וֹ] [וְאָמְרִ֖ין] [לְמַלְכָּ֑א] [נְבֽוּכַדְנֶצַּ֔ר] não [אֲנַ֧חְנָה] [עַל־דְּנָ֛ה] sobre [לַהֲתָבוּתָֽךְ]');
INSERT INTO verses VALUES (21893, 27, 3, 17, 'eis [אִיתַ֗י] [אֱלָהַ֙נָא֙] que [פָֽלְחִ֔ין] [יָכִ֖ל] [לְשֵׁיזָבוּתַ֑נָא] [מִן־אַתּ֨וּן] de [יָקִֽדְתָּ֛א] [וּמִן־יְדָ֥ךְ] [מַלְכָּ֖א] e-de');
INSERT INTO verses VALUES (21894, 27, 3, 18, '[וְהֵ֣ן] não [יְדִ֥יעַ] [לֶהֱוֵא־לָ֖ךְ] para-ti o-rei que não [לָא־*איתינא] [**אִיתַ֣נָא] [פָֽלְחִ֔ין] que [דַּהֲבָ֛א] não [הֲקֵ֖ימְתָּ]');
INSERT INTO verses VALUES (21895, 27, 3, 19, 'בֵּאדַ֨יִן נְבוּכַדְנֶצַּ֜ר הִתְמְלִ֣י חֱמָ֗א וּצְלֵ֤ם אַנְפּ֙וֹהִי֙ sobre שַׁדְרַ֥ךְ מֵישַׁ֖ךְ e-Abede Nego respondeu e-ele-disse לְמֵזֵ֣א לְאַתּוּנָ֔א חַ֨ד־ sete sobre que חֲזֵ֖ה לְמֵזְיֵֽהּ׃');
INSERT INTO verses VALUES (21896, 27, 3, 20, 'וּלְגֻבְרִ֤ין גִּבָּֽרֵי־ חַ֙יִל֙ que בְחַיְלֵ֔הּ disse לְכַפָּתָ֔ה לְשַׁדְרַ֥ךְ מֵישַׁ֖ךְ e-Abede Nego לְמִרְמֵ֕א לְאַתּ֥וּן נוּרָ֖א יָקִֽדְתָּֽא׃');
INSERT INTO verses VALUES (21897, 27, 3, 21, '[בֵּאדַ֜יִן] [גֻּבְרַיָּ֣א] [אִלֵּ֗ךְ] [כְּפִ֙תוּ֙] [בְּסַרְבָּלֵיהוֹן֙] [*פטי[t][y]*שיהון] [**פַּטְּשֵׁיה֔וֹן] [וְכַרְבְּלָתְה֖וֹן] [וּלְבֻשֵׁיה֑וֹן] [וּרְמִ֕יו] [לְגֽוֹא־אַתּ֥וּן] [נוּרָ֖א]');
INSERT INTO verses VALUES (21898, 27, 3, 22, 'todo קֳבֵ֣ל דְּנָ֗ה de דּי מִלָּה o-rei מַחְצֶפָה וְאַתּוּנָא אֵזֶה יַתִּירָא גּוֹבְרַיָּא אִלֵּךְ que הַסִּקּוּ לְשׁוֹדְרַךְ משׁךְ e-Abede נגו קטל himmon שביבה que נורא');
INSERT INTO verses VALUES (21899, 27, 3, 23, '[וְגֻבְרַיָּ֤א] [אִלֵּךְ֙] [תְּלָ֣תֵּה֔וֹן] [שַׁדְרַ֥ךְ] [מֵישַׁ֖ךְ] [וַעֲבֵ֣ד] [נְג֑וֹ] [נְפַ֛לוּ] [לְגֽוֹא־אַתּוּן־נוּרָ֥א] [יָֽקִדְתָּ֖א] [מְכַפְּתִֽין׃]');
INSERT INTO verses VALUES (21900, 27, 3, 24, 'entao נְבוּכַדְנֶצַּ֣ר o-rei תְּוַ֖הּ וְקָ֣ם בְּהִתְבְּהָלָ֑ה respondeu וְאָמַ֜ר לְהַדָּֽבְר֗וֹהִי הֲלָא֩ גֻבְרִ֨ין תְּלָתָ֜א רְמֵ֤ינָא לְגוֹא־ נוּרָא֙ מְכַפְּתִ֔ין עָנַ֤יִן וְאָמְרִין֙ ao-rei יַצִּיבָ֖א מַלְכָּֽא׃');
INSERT INTO verses VALUES (21901, 27, 3, 25, '[עָנֵ֣ה] e-dirá [הָֽא־אֲנָ֨ה] [חָזֵ֜ה] [גֻּבְרִ֣ין] [אַרְבְּעָ֗ה] [שְׁרַ֙יִן֙] [מַהְלְכִ֣ין] [בְּגֽוֹא־נוּרָ֔א] [וַחֲבָ֖ל] [לָא־אִיתַ֣י] [בְּה֑וֹן] não [דִּ֣י] [*רביעיא] [**רְֽבִיעָאָ֔ה] que [לְבַר־אֱלָהִֽין׃]');
INSERT INTO verses VALUES (21902, 27, 3, 26, '[בֵּאדַ֜יִן] [קְרֵ֣ב] [נְבוּכַדְנֶצַּ֗ר] [לִתְרַע֮] [אַתּ֣וּן] [נוּרָ֣א] [יָקִֽדְתָּא֒] [עָנֵ֣ה] e-dirá [שַׁדְרַ֨ךְ] [מֵישַׁ֧ךְ] [וַעֲבֵד־נְג֛וֹ] [עַבְד֛וֹהִי] [דִּֽי־אֱלָהָ֥א] que [**עִלָּאָ֖ה] [פֻּ֣קוּ] [וֶאֱת֑וֹ] [בֵּאדַ֣יִן] [נָֽפְקִ֗ין] [שַׁדְרַ֥ךְ] [מֵישַׁ֛ךְ] [וַעֲבֵ֥ד] [נְג֖וֹ] de [נוּרָֽא]');
INSERT INTO verses VALUES (21903, 27, 3, 27, 'וּמִֽתְכַּנְּשִׁין אֲחַשְׁדַּרְפְּנַיָּ֞א סיגנaya וּפַחֲוָתָא֮ וְהַדָּבְרֵ֣י מַלְכָּא֒ חָזַ֣יִן para-guerreiros eu-Elohim que não domine luz-se na-chuva e-porta cabeça-sua não estendeu-se e-levou-os não duas-lhes e-chei luz não assembleia neles;');
INSERT INTO verses VALUES (21904, 27, 3, 28, 'respondeu Nabucodonosor e-dirá bêrico elohim-os que sauda-te misca e-Abede nega-o que enviou seu-maláke e-shizib para-abadohi que se-hitrachsoem sobre-alohi e-milat o-rei se-shaniyo e-yihavu que não serão-hiplechun e-não se-sigduen para-todo Elohim לָהֵן לֵאלָֽהֲהֽוֹן׃');
INSERT INTO verses VALUES (21905, 27, 3, 29, 'e-de-mim foi-posto decreto que todo povo אֻמָּה וְלִשָׁ֗ן que יֵאמַ֤ר sobre Elohim que שַׁדְרַ֤ךְ מֵישַׁךְ֙ e-Abede נְג֔וֹא os animais serão servidos e na sua habitação meu despojo serão fartos todo cobiçar que não eu mesmo Elohim outro que poderá para a salvação conforme');
INSERT INTO verses VALUES (21906, 27, 3, 30, 'ainda que o-rei que te salve para libertar-te de ti e serve teu na terra de Babilônia');
INSERT INTO verses VALUES (21907, 27, 3, 31, 'Nabucodonosor o-rei para-todo עַֽמְמַיָּ֞א אֻמַיָּ֧א e-líšnayá que em-todo árā'' šlāmakkōn yisgē:');
INSERT INTO verses VALUES (21908, 27, 3, 32, 'á-tayá'' vé-timhāyá'' que servo comigo Elaha šfar qadā''may para a visão');
INSERT INTO verses VALUES (21909, 27, 3, 33, 'eu o verei como muitos, multidões e maravilhar-se-á como de repente, súbito sua realeza reino para sempre e dominará com דר וְדָֽר׃');
INSERT INTO chapters VALUES (854, 27, 4, 34);
INSERT INTO verses VALUES (21910, 27, 4, 1, '[אֲנָ֣ה] [נְבוּכַדְנֶצַּ֗ר] [שְׁלֵ֤ה] [הֲוֵית֙] [בְּבֵיתִ֔י] [וְרַעְנַ֖ן] [בְּהֵיכְלִֽי]');
INSERT INTO verses VALUES (21911, 27, 4, 2, '[חֵ֥לֶם] [חֲזֵ֖ית] [וִֽידַחֲלִנַּ֑נִי] [וְהַרְהֹרִין֙] sobre [וְחֶזְוֵ֥י] [רֵאשִׁ֖י] [יְבַהֲלֻנַּֽנִי]');
INSERT INTO verses VALUES (21912, 27, 4, 3, '[וּמִנִּי֙] foi-posto [טְעֵ֔ם] [לְהַנְעָלָ֣ה] [קָֽדָמַ֔י] a-todo [חַכִּימֵ֣י] [בָבֶ֑ל] que [חֶלְמָ֖א] [יְהֽוֹדְעֻנַּֽנִי]');
INSERT INTO verses VALUES (21913, 27, 4, 4, '[בֵּאדַ֣יִן] [*עללין] [**עָלִּ֗ין] [חַרְטֻמַיָּא֙] [אָֽשְׁפַיָּ֔א] disse [**כַּשְׂדָּאֵ֖י] [וְגָזְרַיָּ֑א] [וְחֶלְמָ֗א] disse [אֲנָה֙] a-mim');
INSERT INTO verses VALUES (21914, 27, 4, 5, '[וְעַ֣ד] [אָחֳרֵ֡ין] sobre [קָֽדָמַ֨י] [דָּנִיֵּ֜אל] que [בֵּלְטְּשַׁאצַּר֙] [כְּשֻׁ֣ם] [אֱלָהִ֔י] [וְדִ֛י] [רֽוּחַ־אֱלָהִ֥ין] espírito-de [בֵּ֑הּ] [וְחֶלְמָ֖א] [קָֽדָמ֥וֹהִי] [אַמְרֵֽת]');
INSERT INTO verses VALUES (21915, 27, 4, 6, '[בֵּלְטְשַׁאצַּר֮] muito [חַרְטֻמַיָּא֒] [דִּ֣י] [׀] [אֲנָ֣ה] que espírito espírito [אֱלָהִ֤ין] [קַדִּישִׁין֙] sobre-ti [וְכָל־רָ֖ז] não para-ti a-ti [חֶלְמִ֧י] [דִֽי־חֲזֵ֛ית] [וּפִשְׁרֵ֖הּ] [אֱמַֽר] disse');
INSERT INTO verses VALUES (21916, 27, 4, 7, 'וחזוי ראשי sobre de-cama viste ser-ás e-al á-ilan em-gua a-terra e-seu-pico sagie:');
INSERT INTO verses VALUES (21917, 27, 4, 8, 'multiplicai [אִֽילָנָ֖א] [וּתְקִ֑ף] [וְרוּמֵהּ֙] [יִמְטֵ֣א] [לִשְׁמַיָּ֔א] [וַחֲזוֹתֵ֖הּ] [לְס֥וֹף] todo');
INSERT INTO verses VALUES (21918, 27, 4, 9, 'עָפְיֵ֤הּ שַׁפִּיר֙ וְאִנְבֵּ֣הּ שַׂגִּיא וּמָזֹן לְכֹלָּא־ בֵּהּ תּחתֹוהִי תּטלֵל ׀ חֵיתַ criou וּבְעַנְפֹּהִי֙ צִפרֵי שָׁמַיָּא e de-lá se nutra todo no sangue,');
INSERT INTO verses VALUES (21919, 27, 4, 10, 'veja seja nos sonhos, primeira sobre de cama; e alou cidade e sagrado de até נָחִֽת׃');
INSERT INTO verses VALUES (21920, 27, 4, 11, 'chamou [בְחַ֜יִל] e-assim disse [גֹּ֤דּוּ] [אִֽילָנָא֙] [וְקַצִּ֣צוּ] [עַנְפ֔וֹהִי] [אַתַּ֥רוּ] [עָפְיֵ֖הּ] [וּבַדַּ֣רוּ] [אִנְבֵּ֑הּ] [תְּנֻ֤ד] [חֵֽיוְתָא֙] de [וְצִפְּרַיָּ֖א] [מִן־עַנְפֽוֹהִי] de');
INSERT INTO verses VALUES (21921, 27, 4, 12, '[בְּרַ֨ם] [עִקַּ֤ר] [שָׁרְשׁ֙וֹהִי֙] [בְּאַרְעָ֣א] [שְׁבֻ֔קוּ] [וּבֶֽאֱסוּר֙] que [וּנְחָ֔שׁ] [בְּדִתְאָ֖א] [דִּ֣י] que criou [שְׁמַיָּא֙] [יִצְטַבַּ֔ע] [וְעִם־חֵיוְתָ֥א] e-com- [בַּעֲשַׂ֥ב] [אַרְעָֽא]');
INSERT INTO verses VALUES (21922, 27, 4, 13, 'no seu coração de será consolado e no seu ventre será repleto de ela e-sete grais serão trocados por ela');
INSERT INTO verses VALUES (21923, 27, 4, 14, 'בּגְזֵרָה עִירִין פִתְגָמָא וּמֵאֲמַר קַדְשִׁים שְׁאֵלָה até דְבַר que יִנְדָּעֵן חַיָּה que שַׂלִיט בְּמַלְכ֣וּת וּלְמַן־ que יִצְבֵּא֙ יִתְּנִנַּ֔הּ וּשְׁפַ֥ל homens יְקִ֥ים');
INSERT INTO verses VALUES (21924, 27, 4, 15, 'esta [חֶלְמָ֣א] [חֲזֵ֔ית] [אֲנָ֖ה] [מַלְכָּ֣א] [נְבוּכַדְנֶצַּ֑ר] [*ואנתה] [**וְאַ֨נְתְּ] disse todo porque [אֱמַ֗ר] todo [דִּ֣י] [׀] não [מַלְכוּתִ֗י] [לָֽא־יָכְלִ֤ין] [פִּשְׁרָא֙] [לְהוֹדָ֣עֻתַ֔נִי] [*ואנתה] espírito-de [כָּהֵ֔ל] [דִּ֛י] em-ti');
INSERT INTO verses VALUES (21925, 27, 4, 16, 'אֱדָיִן דְּנַיֵּאל que שֶׁמֶהּ בָּלְתְּשַׁאצַּר אֵשְׂתֹּמַם כְּשַׁעָה חֲדָה e minha reiña a envergonhar respondeu rei e-dirá Beltesar sonho e príncipe a a envergonhar-te respondeu Beltesar e-dizer-á sonho e seu príncipe');
INSERT INTO verses VALUES (21926, 27, 4, 17, '[אִֽילָנָא֙] que [חֲזַ֔יְתָ] que multiplicai [וּתְקִ֑ף] [וְרוּמֵהּ֙] [יִמְטֵ֣א] [לִשְׁמַיָּ֔א] [וַחֲזוֹתֵ֖הּ] para-todo');
INSERT INTO verses VALUES (21927, 27, 4, 18, 'וְעָפְיֵ֤הּ שַׁפִּיר֙ e-a segia e-mazon para-todo-o nele debajo-de-mim dormirei criou criou e-em-suas-asas descansará penas céus:');
INSERT INTO verses VALUES (21928, 27, 4, 19, 'ele o-rei que Rabita e Tefphet e Rabbuta-te Rabba e Metat para os céus: e te governar até o fim terra:');
INSERT INTO verses VALUES (21929, 27, 4, 20, 'וְדִ֣י חֲזָ֣ה מַלְכָּ֡א cidade וְקַדִּ֣ישׁ נָחִ֣ת de שְׁמַיָּ֡א וְאָמַר֩ גֹּ֨דּוּ אִֽילָנָ֜א וְחַבְּל֗וּהִי Mas Raiz minha raiz na terra seca-se e na prisão que faraó e serpente na árvore que criou e seca-se שָׁמַיִם יִצְטַבֵּעַ criou חֶיוֹת até חֲלָקְהּ até que sete עִדַּנִּין יַחְלְפוּן עֲלוֹהִי׃');
INSERT INTO verses VALUES (21930, 27, 4, 21, '[דְּנָ֥ה] [פִשְׁרָ֖א] o-rei [וּגְזֵרַ֤ת] ela que [הִ֔יא] sobre [מְטָ֖ת]');
INSERT INTO verses VALUES (21931, 27, 4, 22, 'וְלָ֣ךְ טָֽרְדִ֣ין de אֲנָשָׁ֡א criou חֵיוַ֣ת criou לֶהֱוֵ֨ה מְדֹרָ֜ךְ וְעִשְׂבָּ֥א para-ti a-ti יְטַֽעֲמ֗וּן e-por meio de chuva para-ti a-ti que estendem e-sete que se espalham serão substituídos até até que será lançada que príncipe sobre no reino homens e-para que que יִצְבּוֹא יִתְנוֹן׃');
INSERT INTO verses VALUES (21932, 27, 4, 23, '[וְדִ֣י] [אֲמַ֗רוּ] [לְמִשְׁבַּ֞ק] [עִקַּ֤ר] [שָׁרְשׁ֙וֹהִי֙] que [אִֽילָנָ֔א] [מַלְכוּתָ֖ךְ] para-ti [קַיָּמָ֑ה] de que [דִּ֥י] que [שְׁמַיָּֽא]');
INSERT INTO verses VALUES (21933, 27, 4, 24, 'lahen o-rei מלכי ישפר בתיקנה פרוק ואWAYתך במחן עֲנָ֑יִן הֵ֛ן תֶּהֱוֵ֥א אַרְכָ֖ה לִשְׁלֵוְתָֽךְ׃');
INSERT INTO verses VALUES (21934, 27, 4, 25, '[כֹּ֣לָּא] [מְּטָ֔א] sobre [מַלְכָּֽא׃]');
INSERT INTO verses VALUES (21935, 27, 4, 26, '[לִקְצָ֥ת] [יַרְחִ֖ין] [תְּרֵֽי־עֲשַׂ֑ר] dez sobre [דִּ֥י] [בָבֶ֖ל] que [הֲוָֽה]');
INSERT INTO verses VALUES (21936, 27, 4, 27, '[עָנֵ֤ה] o-rei [וְאָמַ֔ר] [הֲלָ֥א] [דָא־הִ֖יא] ela [רַבְּתָ֑א] [דִּֽי־אֲנָ֤ה] que [לְבֵ֣ית] [מַלְכ֔וּ] para-casa-de [חִסְנִ֖י] [וְלִיקָ֥ר] [הַדְרִֽי]');
INSERT INTO verses VALUES (21937, 27, 4, 28, 'ainda [מִלְּתָא֙] [בְּפֻ֣ם] o-rei [קָ֖ל] de [נְפַ֑ל] para-ti para-ti [נְבוּכַדְנֶצַּ֣ר] [מַלְכָּ֔א] o-rei [עֲדָ֥ת] [מִנָּֽךְ]');
INSERT INTO verses VALUES (21938, 27, 4, 29, 'e-de para-ti [טָֽרְדִ֜ין] [וְֽעִם־חֵיוַ֧ת] criou [מְדֹרָ֗ךְ] criou [כְתוֹרִין֙] para-ti [יְטַעֲמ֔וּן] [וְשִׁבְעָ֥ה] [עִדָּנִ֖ין] e-sete [*עליך] [**עֲלָ֑ךְ] até que [דִּֽי־שַׁלִּ֤יט] que [בְּמַלְכ֣וּת] [אֲנָשָׁ֔א] [וּלְמַן־דִּ֥י] [יִצְבֵּ֖א] [יִתְּנִנַּֽהּ]');
INSERT INTO verses VALUES (21939, 27, 4, 30, 'בַּהּ־ שַׁעֲתָ֗א מִלְּתָא֮ סָ֣פַת sobre נְבוּכַדְנֶצַּר֒ e-de אֲנָשָׁ֣א טְרִ֔יד e-usba cortin será comido e da chuva até sua chuva se estendesse até que sua cabeça carnes multiplicai e-meus pés como penas');
INSERT INTO verses VALUES (21940, 27, 4, 31, 'e-líquida יֽוֹם-יָה אֲנָה נְבוּכַדְנֶצַּ֜ר עַיְנַ֣י לִשְׁמַיָּ֣א נִטְלֵ֗ת וּמַנְדְּעִי֙ עֲלַ֣י יְת֔וּב בָּרְכֵ֔ת וּלְחַ֥י עָלְמָ֖א שַׁבְּחֵ֣ת וְהַדְּרֵ֑ת que שָׁלְטָנֵהּ֙ שָׁלְטָ֣ן עָלַ֔ם וּמַלְכוּתֵ֖הּ com דָּ֥ר וְדָֽר׃');
INSERT INTO verses VALUES (21941, 27, 4, 32, 'e-todo [**דָּיְרֵ֤י] [אַרְעָא֙] [כְּלָ֣ה] [חֲשִׁיבִ֔ין] servo [עָבֵד֙] [בְּחֵ֣יל] [שְׁמַיָּ֔א] e-não [**וְדָיְרֵ֖י] que [וְלָ֤א] [אִיתַי֙] E-disse [בִידֵ֔הּ] que [לֵ֖הּ]');
INSERT INTO verses VALUES (21942, 27, 4, 33, '[בֵּהּ־זִמְנָ֞א] [מַנְדְּעִ֣י] [׀] [יְת֣וּב] [עֲלַ֗י] [וְלִיקַ֨ר] [מַלְכוּתִ֜י] [הַדְרִ֤י] [וְזִוִי֙] [יְת֣וּב] [עֲלַ֔י] [וְלִ֕י] [הַדָּֽבְרַ֥י] [וְרַבְרְבָנַ֖י] [יְבַע֑וֹן] e-sobre [הָתְקְנַ֔ת] e-multiplicai-vos [יַתִּירָ֖ה] [ה֥וּסְפַת] [לִֽי]');
INSERT INTO verses VALUES (21943, 27, 4, 34, 'כאון אנא נבוכדנצר משבח ומROOMים ומHDRאר como-rei שמיא que todo עבדוהיו קSHOTט e o caminho dela julgamento e a vida e-o-andar com altivez poderia abaixá-la');
INSERT INTO chapters VALUES (855, 27, 5, 30);
INSERT INTO verses VALUES (21944, 27, 5, 1, 'Belshazzar o-rei servo para o pão muito para a grandeza dele mil e-lakovel alpa hamra shateh');
INSERT INTO verses VALUES (21945, 27, 5, 2, 'Belišaṣar amar bit''eim hamra lehaytaiyah lemanie דַהֲבָא וְכַסְפָּא que הַנְפֵּק נְבוּכַדְנֶצַּר אֲב֔וּהִי de הֵיכְלָ֖א que בִירוּשְׁלֶ֑ם וְיִשְׁתּ֣וֹן בְּה֗וֹן o-rei וְרַבְרְבָנ֔וֹהִי seglateh ulichenateh');
INSERT INTO verses VALUES (21946, 27, 5, 3, 'badayin haytiyo maanei dahava que hafnequi de heichla que casa Elaha que birushalem ve''ishto בְּה֗וֹן o-rei וְרַבְרְבָנ֔וֹהִי שֵׁגְלָתֵ֖הּ וּלְחֵנָתֵֽהּ׃');
INSERT INTO verses VALUES (21947, 27, 5, 4, '[אִשְׁתִּ֖יו] [חַמְרָ֑א] [וְ֠שַׁבַּחוּ] [לֵֽאלָהֵ֞י] [דַּהֲבָ֧א] [וְכַסְפָּ֛א] [נְחָשָׁ֥א] [פַרְזְלָ֖א] [אָעָ֥א] [וְאַבְנָֽא]');
INSERT INTO verses VALUES (21948, 27, 5, 5, '[בַּהּ־שַׁעֲתָ֗ה] [*נפקו] [**נְפַ֙קָה֙] que mão-de [יַד־אֱנָ֔שׁ] [וְכָֽתְבָן֙] diante-de [נֶבְרַשְׁתָּ֔א] sobre [דִּֽי־כְתַ֥ל] que [דִּ֣י] [מַלְכָּ֑א] que o-rei [פַּ֥ס] [יְדָ֖ה] [דִּ֥י] [כָתְבָֽה]');
INSERT INTO verses VALUES (21949, 27, 5, 6, '[אֱדַ֤יִן] o-rei [זִיוֺ֣הִי] [שְׁנ֔וֹהִי] [וְרַעיֹנֹ֖הִי] [יְבַהֲלוּנֵּ֑הּ] [וְקִטְרֵ֤י] [חַרְצֵהּ֙] [מִשְׁתָּרַ֔יִן] [וְאַ֨רְכֻבָּתֵ֔הּ] [דָּ֥א] [לְדָ֖א] [נָֽקְשָֽׁן]');
INSERT INTO verses VALUES (21950, 27, 5, 7, 'chamou o-rei בּחַיִל לְהֶעָלָה לְאָשְׁפַיָּא וְגָזְרַיָּא respondeu מַלְכָּא וְאָמַר לְחַכִּימֵי בָבֶל que todo אֱנָשׁ que יִקְרֵה כּתָבָה דְנָה וּפִשְׁרֵהּ יְחַוּנּנִי אַרְגּוֹנָא יִלְבַשׁ que דַהֲבָא sobre צַוֹּארֵהּ וְתַלְתִי בְמַלְכוּתָא יִשְׁלַֽט׃');
INSERT INTO verses VALUES (21951, 27, 5, 8, 'entao todo חַכִּימֵ֣י o-rei e-não כָהֲלִ֤ין כְּתָבָא֙ לְמִקְרֵ֔א לְהוֹדָעָ֥ה ao-rei');
INSERT INTO verses VALUES (21952, 27, 5, 9, 'entao מַלְכָּ֤א בֵלְשַׁאצַּר֙ שַׂגִּ֣יא מִתְבָּהַ֔ל e sua glória duas sobre ele vé-rabbarnā''ohī de testemunho');
INSERT INTO verses VALUES (21953, 27, 5, 10, 'reino para receber palavras o-rei e grande-grande-senhor segundo-casa-de de canto אנאת מלכת ואמרת o-rei לאלמיין חיי a יבהלוך ריעונך וזיויך a ישתחנו׃');
INSERT INTO verses VALUES (21954, 27, 5, 11, '[אִיתַ֨י] [גְּבַ֜ר] [בְּמַלְכוּתָ֗ךְ] que espírito [אֱלָהִ֣ין] [קַדִּישִׁין֮] [בֵּהּ֒] [וּבְיוֹמֵ֣י] [אֲב֗וּךְ] [נַהִיר֧וּ] [וְשָׂכְלְתָנ֛וּ] [וְחָכְמָ֥ה] [כְּחָכְמַת־אֱלָהִ֖ין] [הִשְׁתְּכַ֣חַת] [בֵּ֑הּ] [וּמַלְכָּ֤א] [נְבֻֽכַדְנֶצַּר֙] [אֲב֔וּךְ] [רַ֧ב] muito [אָֽשְׁפִ֗ין] [כַּשְׂדָּאִין֙] [גָּזְרִ֔ין] [הֲקִימֵ֖הּ] [אֲב֥וּךְ] [מַלְכָּֽא]');
INSERT INTO verses VALUES (21955, 27, 5, 12, 'todo קבול espírito espírito- יתירה MANDע ושכלתנו משפר חליים e-irmã Achidan e-meser kitrin foi-olvidada nele Danieel que rei dele seu-nome בלטשׁאצּר כאע דנייאל ית氪레이 ופשרא יהחוה׃');
INSERT INTO verses VALUES (21956, 27, 5, 13, '[בֵּאדַ֙יִן֙] [דָּֽנִיֵּ֔אל] [הֻעַ֖ל] [קֳדָ֣ם] o-rei [עָנֵ֨ה] [מַלְכָּ֜א] [וְאָמַ֣ר] [לְדָנִיֵּ֗אל] ele [דָנִיֵּאל֙] que de filhos-de [יְה֔וּד] que [הַיְתִ֛י] que [אַ֖בִי] [מִן־יְהֽוּד] de');
INSERT INTO verses VALUES (21957, 27, 5, 14, 'וְשִׁמְעֵ֣ת דּי espírito אֱלָהִים espírito וְנַהִירֻ sobre-ti וְחָכְמָה יַתִּירָה for esquecida em-ti');
INSERT INTO verses VALUES (21958, 27, 5, 15, '[וּכְעַ֞ן] [הֻעַ֣לּוּ] [קָֽדָמַ֗י] [חַכִּֽימַיָּא֙] [אָֽשְׁפַיָּ֔א] que [דְנָה֙] [יִקְר֔וֹן] [וּפִשְׁרֵ֖הּ] [לְהוֹדָעֻתַ֑נִי] [וְלָֽא־כָהֲלִ֥ין] e-não [לְהַחֲוָיָֽה]');
INSERT INTO verses VALUES (21959, 27, 5, 16, 'וַאֲנָה֙ שִׁמְעֵ֣ת que פִּשְׁרִ֛ין לְמִפְשַׁ֖ר וְקִטְרִ֣ין לְמִשְׁרֵ֑א כְּעַ֡ן הֵן֩ כְּתָבָ֜א לְמִקְרֵ֗א eis para-te-declare argvanâ vestir-te-ás que dahvâ sobre colar-te-ás e-te-sustentares na-majestade reinar-ás');
INSERT INTO verses VALUES (21960, 27, 5, 17, 'ainda responde DANIEL e-ele-disse diante-de o-rei MATNATKHA para-ti LEHEVAYAN UNEVAZVEYATAKHA LE''ACHORAN HAV BARAM KETVA EKREI ao-rei UPISHRA אֲהוֹדְעִנֵּֽהּ׃');
INSERT INTO verses VALUES (21961, 27, 5, 18, 'o-rei [**אַ֖נְתְּ] [מַלְכָּ֑א] [אֱלָהָא֙] E-chamou [**עִלָּאָ֔ה] [מַלְכוּתָ֤א] [וּרְבוּתָא֙] [וִיקָרָ֣א]');
INSERT INTO verses VALUES (21962, 27, 5, 19, 'e-de רְבוּתָא֙ que יְהַב־ lêh todo ʿammayya ʿumayya velišnayya havvô vedachalin de kadamoheyi que havâ ṣāvē havâ קָטֵל וְדִי- הֲוָה צָבֵא הֲוָה מַחֵא וְדִי- הֲוָה צָבֵא הֲוָה מרעים והי- יהוה צבא יהוה משפיל׃');
INSERT INTO verses VALUES (21963, 27, 5, 20, '[וּכְדִי֙] [רִ֣ם] [לִבְבֵ֔הּ] [וְרוּחֵ֖הּ] [תִּֽקְפַ֣ת] [לַהֲזָדָ֑ה] [הָנְחַת֙] de [מַלְכוּתֵ֔הּ] [וִֽיקָרָ֖ה] [הֶעְדִּ֥יו[t]] [מִנֵּֽהּ]');
INSERT INTO verses VALUES (21964, 27, 5, 21, 'e-de filhos-de אנשא טריד וליבבה ׀ com e besta e-com- e areia de sua morada e vegetação e cisternas e se deleitem nelas e da chuva o céu gishmeh yitztaba até que conheceu que shalleit Elohim בְּמַלְכ֣וּת אֲנָשָׁא וּלְמַן־ que יִצְבֵּ֖ה יְהָקֵ֥ים');
INSERT INTO verses VALUES (21965, 27, 5, 22, '[*ואנתה] [**וְאַ֤נְתְּ] não [בֵּלְשַׁאצַּ֔ר] [לָ֥א] todo [לִבְבָ֑ךְ] que todo [כָל־דְּנָ֖ה] [יְדַֽעְתָּ]');
INSERT INTO verses VALUES (21966, 27, 5, 23, 'e-sobre מָרֵֽא־ שְׁמַיָּ֣א ׀ הִתְרוֹמַ֡מְתָּ וּלְמָֽאנַיָּ֨א que בַיְתֵ֜הּ הַיְתִ֣יו שֵֽׁגְלָתָ֣ךְ e-lhe-a-cená-ta-ka-m cham-ra-aa-m shat-a-iin be-ho-n ve-le-aa-la-hei kas-pa-a-m ve-da-ha-ba-a ne-chas-ha-aa par-zla-a aa-a וְאַבְנָ֗א que não חָזַ֧יִן e-não שָׁמְעִ֛ין e-não יָדְעִ֖ין שַׁבַּ֑חְתָּ וְלֵֽאלָהָ֞א que נִשְׁמְתָ֥ךְ בִּידֵ֛הּ e-todo אֹרְחָתָ֥ךְ לֵ֖הּ não a dartha:');
INSERT INTO verses VALUES (21967, 27, 5, 24, 'ba-adayin de kadamo''ihi shaliya'' pas''a que yeda'' u-ketava'' dene''a reshim:');
INSERT INTO verses VALUES (21968, 27, 5, 25, 'u-dene''a כְּתָבָא que רְשׁוֹם מְנֵא מְנֵא תְּקוּל וּפַרְסִין׃');
INSERT INTO verses VALUES (21969, 27, 5, 26, '[דְּנָ֖ה] [פְּשַֽׁר־מִלְּתָ֑א] [מְנֵ֕א] [מְנָֽה־אֱלָהָ֥א] [מַלְכוּתָ֖ךְ] [וְהַשְׁלְמַֽהּ]');
INSERT INTO verses VALUES (21970, 27, 5, 27, '[תְּקֵ֑ל] [תְּקִ֥ילְתָּה] [בְמֹֽאזַנְיָ֖א] [וְהִשְׁתְּכַ֥חַתְּ] [חַסִּֽיר]');
INSERT INTO verses VALUES (21971, 27, 5, 28, '[פְּרֵ֑ס] [פְּרִיסַת֙] [מַלְכוּתָ֔ךְ] [וִיהִיבַ֖ת] [לְמָדַ֥י] [וּפָרָֽס]');
INSERT INTO verses VALUES (21972, 27, 5, 29, 'בדדיִן disse בלשאצאר והלבישו לדנייאל ארגואנא que דהבא sobre צַוְּאָרֵהּ וְהַכְרִ֖זֺוּ sobre-ele que לֶהֱוֵ֖א שַׁלִּ֖יט תַּלְתָּ֖א בְּמַלְכוּתָֽא׃');
INSERT INTO verses VALUES (21973, 27, 5, 30, '[בֵּ֚הּ] [בְּלֵ֣ילְיָ֔א] [קְטִ֕יל] [בֵּלְאשַׁצַּ֖ר] [מַלְכָּ֥א]');
INSERT INTO chapters VALUES (856, 27, 6, 29);
INSERT INTO verses VALUES (21974, 27, 6, 1, '[וְדָרְיָ֙וֶשׁ֙] [מָֽדָיאָ֔] [קַבֵּ֖ל] [מַלְכוּתָ֑א] [כְּבַ֥ר] [שְׁנִ֖ין] [שִׁתִּ֥ין] [וְתַרְתֵּֽין]');
INSERT INTO verses VALUES (21975, 27, 6, 2, '[שְׁפַר֙] [קֳדָ֣ם] [דָּרְיָ֔וֶשׁ] [וַהֲקִים֙] sobre [לַאֲחַשְׁדַּרְפְּנַיָּ֖א] [מְאָ֣ה] cem [דִּ֥י] que [בְּכָל־מַלְכוּתָֽא] em-todo');
INSERT INTO verses VALUES (21976, 27, 6, 3, 'והעל מןהון SURECHIN três-a que Daniyyel had- minhown que lehevon achashdarpnay ilayn yahavin לוֹן טעמה ומלכא não eis נזק');
INSERT INTO verses VALUES (21977, 27, 6, 4, '[אֱדַ֙יִן֙] [דָּנִיֵּ֣אל] isto [הֲוָ֣א] [מִתְנַצַּ֔ח] sobre [וַאֲחַשְׁדַּרְפְּנַיָּ֑א] [כָּל־קֳבֵ֗ל] todo espírito que espírito [וּמַלְכָּ֣א] [עֲשִׁ֔ית] [לַהֲקָמוּתֵ֖הּ] [עַל־כָּל־מַלְכוּתָֽא] sobre todo');
INSERT INTO verses VALUES (21978, 27, 6, 5, '[אֱדַ֨יִן] [סָֽרְכַיָּ֜א] [וַאֲחַשְׁדַּרְפְּנַיָּ֗א] [הֲו֨וֹ] [בָעַ֧יִן] [עִלָּ֛ה] [לְהַשְׁכָּחָ֥ה] [לְדָנִיֵּ֖אל] de-lado-de [מַלְכוּתָ֑א] e-todo [וּשְׁחִיתָ֜ה] [לָא־יָכְלִ֣ין] não [כָּל־קֳבֵל֙] [דִּֽי־מְהֵימַ֣ן] ele porque que [לָ֥א] ele e-todo não');
INSERT INTO verses VALUES (21979, 27, 6, 6, 'entao valentes eu dizemos que não esqueçamos a Daniel dá todo para ela לָהֵ֕ן הַשְׁכַּ֥חְנָֽה עֲל֖וֹהִי בְּדָ֥ת אֱלָהֵֽהּ׃');
INSERT INTO verses VALUES (21980, 27, 6, 7, 'entao סָרְכַיָּ֤א וַאֲחַשְׁדַּרְפְּנַיָּא֙ אִלֵּ֔ן הַרְגִּ֖שׁוּ sobre o-rei e também אָמְרִ֣ין lhe Dario o-rei para os séculos minha vida:');
INSERT INTO verses VALUES (21981, 27, 6, 8, 'e se esforçaram todas seus companheiros a realeza sígnaiá (não alterado, pois é um nome próprio) e achashdrapnayá (não alterado, pois é um nome próprio) a palavra e a glória para aqíma aqím o-rei e talqáfá esár que todo que irá beír e ba''ú de todo Elohim e enash até yomín teláthín Lahên minnek o-rei yitremê'' legob aryavata:');
INSERT INTO verses VALUES (21982, 27, 6, 9, 'ka''an o-rei tikim esara v''tirshum k''tavâ'' que não para a separação como lei- meu amado e separou que não você verá:');
INSERT INTO verses VALUES (21983, 27, 6, 10, 'todo aceite Dana o-rei Darío escreveu escrita וֶאֱסָרָֽא׃');
INSERT INTO verses VALUES (21984, 27, 6, 11, 'וְ֠דָנִיֵּאל כְּדִ֨י conheceu que רְשִׁ֤ים sobre sobre לְבַיְתֵ֔הּ וְכַוּ֨ין פְּתִיחָ֥ן לֵהּ֙ diante נֶ֖גֶד Jerusalém וְזִמְנִין֩ תלתא ele ele abençoou sobre ברכויתי ומצלאה umoadea diante-de אלוהה todo porque que הוא servo de קדמת dna:');
INSERT INTO verses VALUES (21985, 27, 6, 12, 'entao גבריא אליך percebam e caíram a Daniel no vazio e suplicarem ante Elohim');
INSERT INTO verses VALUES (21986, 27, 6, 13, 'ainda que venham e digamos ANTE- MALKĀʾ- sobre ESĀR MALKĀʾ- HALĀʾ- ESĀR reshamta que todo ENĀŠ que YIBʿĒH de todo ELŌḤ e-homem até dias três para-as de-vos o-rei serão-recebidos para-empurrar ursos respondeu rei e-dirá estabelecerá מִלְּתָ֛א כְּדָת־ מָדַ֥י וּפָרַ֖ס que não תֶעְדֵּֽא׃');
INSERT INTO verses VALUES (21987, 27, 6, 14, 'בֵּ֠אדַיִן עֲנ֣וֹ וְאָמְרִין֮ diante-de מַלְכָּא֒ que דָנִיֵּ֡אל que de filhos-de גלוטא que יהודה não nome o-rei decreto e-sobre אסרא que רשמת וזמנין לתאנה ביומא בעא בעעה׃');
INSERT INTO verses VALUES (21988, 27, 6, 15, 'עדין מלכה כי מלטה ouviu שׁגיא בעesh sobre-ele e-sobre דנייאל nome בל לשיזבותיה e-ate מעלי שׁמש הוֹ משׁטדר לְהַצְּלֹוֶֽת׃');
INSERT INTO verses VALUES (21989, 27, 6, 16, '[בֵּאדַ֙יִן֙] [גֻּבְרַיָּ֣א] [אִלֵּ֔ךְ] [הַרְגִּ֖שׁוּ] sobre o-rei [לְמַלְכָּ֗א] [דַּ֤ע] [מַלְכָּא֙] o-rei que [וּפָרַ֔ס] [דִּֽי־כָל־אֱסָ֥ר] [וּקְיָ֛ם] que todo [לָ֥א] [לְהַשְׁנָיָֽה] não');
INSERT INTO verses VALUES (21990, 27, 6, 17, 'BEDADIЙn מלכא disse וְהַיְתִיו֙ לְדָ֣נִיֵּ֔אל וּרְמ֕וֹ לְגֻבָּ֖א que אַרְיָוָתָ֑א respondeu o-rei וְאָמַ֣ר לְדָ֣נִיֵּ֔אל אֱלָהָ֗ךְ que פָּֽלַֽח־ לֵהּ֙ בתדריא ele ele');
INSERT INTO verses VALUES (21991, 27, 6, 18, '[וְהֵיתָ֙יִת֙] pedra [חֲדָ֔ה] [וְשֻׂמַ֖ת] sobre [גֻּבָּ֑א] [וְחַתְמַ֨הּ] [מַלְכָּ֜א] [בְּעִזְקְתֵ֗הּ] [וּבְעִזְקָת֙] [רַבְרְבָנ֔וֹהִי] [דִּ֛י] [לָא־תִשְׁנֵ֥א] não [בְּדָנִיֵּֽאל]');
INSERT INTO verses VALUES (21992, 27, 6, 19, 'entao Azal מלכא לHEYKHELah ו Bat Tevat וְדַחֲוָ֖ן não הַנְעֵ֣ל קָֽדָמ֑וֹהִי וְשִׁנְתֵּ֖הּ נַדַּ֥ת עֲלֽוֹהִי׃');
INSERT INTO verses VALUES (21993, 27, 6, 20, 'בֵּאדַ֣יִן o-rei בִּשְׁפַּרְפָּרָ֖א יְק֣וּם בְּנָגְהָ֑א e na sua contemplação para cima que arrependimento se foi');
INSERT INTO verses VALUES (21994, 27, 6, 21, 'e no meio de para cima a Daniel em todo o seu tristeza choro respondeu מלכא ואמר לדנייאל דנייאל servo Elaha חיya אלהך que פלח- ליה בתדירה haykel para-a-vez-te de ariyavata:');
INSERT INTO verses VALUES (21995, 27, 6, 22, 'entao daniyal com o-rei malal o-rei para-os-mundos chayi:');
INSERT INTO verses VALUES (21996, 27, 6, 23, 'elahi enviou malakheh usaggar pum אריהוֹתָא e-não חבּלוּני todo קבֵל que קדָמוֹהִי זכוּ הִשׁתְּךַ֣חַת a-mim ואַף o-rei חבּולָה não עַבְדֵת׃');
INSERT INTO verses VALUES (21997, 27, 6, 24, '[בֵּאדַ֣יִן] o-rei [שַׂגִּיא֙] [טְאֵ֣ב] sobre-ele [וּלְדָ֣נִיֵּ֔אל] disse [לְהַנְסָקָ֣ה] de [וְהֻסַּ֨ק] [דָּנִיֵּ֜אל] [מִן־גֻּבָּ֗א] de [לָא־הִשְׁתְּכַ֣ח] e-todo [דִּ֖י] não [בֵּאלָהֵֽהּ]');
INSERT INTO verses VALUES (21998, 27, 6, 25, '[וַאֲמַ֣ר] o-rei [וְהַיְתִ֞יו] [גֻּבְרַיָּ֤א] [אִלֵּךְ֙] que [קַרְצ֙וֹהִי֙] [דִּ֣י] que [וּלְגֹ֤ב] [אַרְיָוָתָא֙] [רְמ֔וֹ] [אִנּ֖וּן] [בְּנֵיה֣וֹן] [וּנְשֵׁיה֑וֹן] [וְלָֽא־מְט֞וֹ] e-não [גֻּבָּ֗א] até [דִּֽי־שְׁלִ֤טֽוּ] até que [וְכָל־גַּרְמֵיה֖וֹן] [הַדִּֽקוּ] e-todo');
INSERT INTO verses VALUES (21999, 27, 6, 26, '[בֵּאדַ֜יִן] [דָּרְיָ֣וֶשׁ] o-rei [כְּ֠תַב] para-todo [אֻמַיָּ֧א] [וְלִשָּׁנַיָּ֛א] [דִּֽי־*דארין] que em-todo [שְׁלָמְכ֥וֹן] [יִשְׂגֵּֽא]');
INSERT INTO verses VALUES (22000, 27, 6, 27, 'de [שִׂ֣ים] foi-posto decreto [׀] em-todo [מַלְכוּתִ֗י] [לֶהֱוֺ֤ן] [*זאעין] [**זָיְעִין֙] de [מִן־קֳדָ֖ם] [אֱלָהֵ֣הּ] que [דִּי־ה֣וּא] que ele [חַיָּ֗א] [וְקַיָּם֙] [לְעָ֣לְמִ֔ין] [וּמַלְכוּתֵהּ֙] [דִּֽי־לָ֣א] que não [עַד־סוֹפָֽא] até');
INSERT INTO verses VALUES (22001, 27, 6, 28, 'מְשֵׁית e salve e sirva ain e se maravilhe no céu e na terra que havia inflamado a Daniel de mão Arauta:');
INSERT INTO verses VALUES (22002, 27, 6, 29, 'e Daniel isto o-êxito -no-reino daryôvesh -e-no-reino Ciro');
INSERT INTO chapters VALUES (857, 27, 7, 28);
INSERT INTO verses VALUES (22003, 27, 7, 1, 'em-ano-de chadá levêlêatsar rei Babilônia daniel preço visão -e-visiones רֵאשֶׁת sobre מִשִּׁכְבָּה בֶּאָדָיִן חֲלוֹם כְּתֵב cabeça מִלָּיוֹן disse');
INSERT INTO verses VALUES (22004, 27, 7, 2, 'respondeu דַּנִּיאֵאֵל e ele disse: חֲזוֹת הֵאָמַץ בְּחֶזוֹווּ com לֵילְיָא וַאֲרֻ quatro רוּחֵי שְׁמַיָ֔א מְגִיחָן לְיַמָּא רַבָּא׃');
INSERT INTO verses VALUES (22005, 27, 7, 3, '[וְאַרְבַּ֤ע] [חֵיוָן֙] [רַבְרְבָ֔ן] [סָלְקָ֖ן] de [שָׁנְיָ֖ן] [דָּ֥א] [מִן־דָּֽא] de');
INSERT INTO verses VALUES (22006, 27, 7, 4, 'קַדְמָיְתָ֣א כְאַרְיֵ֔ה וְגַפִּ֥ין que נְשַׁ֖ר לַ֑הּ vision até até que exalou asas- -as- de terra- e-sobre -pés como-homem levantou-se וּלְבַ֥ב -homem dará para ela:');
INSERT INTO verses VALUES (22007, 27, 7, 5, 'e eu carnes atrás de mim foi chamada como um ursinho e para o agudo erectou וּתְלָ֥ת עִלְעִ֛ין entre entre e também אָמְרִ֣ין לַ֔הּ ק֥וּמִֽי אֲכֻ֖לִי de-a-carne שַׂגִּֽיא׃');
INSERT INTO verses VALUES (22008, 27, 7, 6, '[בָּאתַ֨ר] [דְּנָ֜ה] [חָזֵ֣ה] [הֲוֵ֗ית] [וַאֲר֤וּ] [אָֽחֳרִי֙] [כִּנְמַ֔ר] [וְלַ֨הּ] [גַּפִּ֥ין] quatro que ave sobre [וְאַרְבְּעָ֤ה] [רֵאשִׁין֙] [לְחֵ֣יוְתָ֔א] [וְשָׁלְטָ֖ן] [יְהִ֥יב] [לַֽהּ]');
INSERT INTO verses VALUES (22009, 27, 7, 7, 'בָּאתַ֣ר דְּנָה֩ חָזֵ֨ה הֲוֵ֜ית בְּחֶזְוֵ֣י לֵֽילְיָ֗א וַאֲר֣וּ חֵיוָ֣ה דֲּחִילָה וְאֵֽימְתָנִי וְתַקִּיפָא יַתִּ֗ירָא וְשִׁנַּ֨יִן que פַרְזֶ֥ל לַהּ רַבְרְבָ֔ן אָֽכְלָ֣ה וּמַדֱּקָ֔ה e-a rap-sa e-ela mash-ni-ya de todo che-i-wa-ta que kad-ma-yi-ha ve-kar-nay-in dez la-ah:');
INSERT INTO verses VALUES (22010, 27, 7, 8, 'mi-shtak-kal he-vi'' be-kar-nay-a וַ֠אֲלוּ קֶ֣רֶן אָחֳרִ֤י זְעֵירָה֙ סִלְקָ֣ת וּתְלָ֗ת de קַרְנַיָּא֙ קַדְמָ֣יָתָ֔א de וַאֲל֨וּ עַיְנִ֜ין כּ-עַיְנֵ֤י אֲנָשָׁא֙ בּ-קַרְנָא- דָ֔א וּפֻ֖ם מְמַלּ֣ל רַבְרְבָֽן׃');
INSERT INTO verses VALUES (22011, 27, 7, 9, '[חָזֵ֣ה] [הֲוֵ֗ית] até que [כָרְסָוָן֙] [רְמִ֔יו] [וְעַתִּ֥יק] [יוֹמִ֖ין] [יְתִ֑ב] [לְבוּשֵׁ֣הּ] [׀] [כִּתְלַ֣ג] [חִוָּ֗ר] [וּשְׂעַ֤ר] [רֵאשֵׁהּ֙] [כַּעֲמַ֣ר] [נְקֵ֔א] [כָּרְסְיֵהּ֙] que [דִּי־נ֔וּר] [גַּלְגִּלּ֖וֹהִי] [נ֥וּר] [דָּלִֽק]');
INSERT INTO verses VALUES (22012, 27, 7, 10, '[נְהַ֣ר] que [נָגֵ֤ד] [וְנָפֵק֙] [מִן־קֳדָמ֔וֹהִי] de [*אלפים] mil [יְשַׁמְּשׁוּנֵּ֔הּ] [וְרִבּ֥וֹ] [*רבון] [**רִבְבָ֖ן] [קֽ͏ָדָמ֣וֹהִי] [יְקוּמ֑וּן] [דִּינָ֥א] [יְתִ֖ב]');
INSERT INTO verses VALUES (22013, 27, 7, 11, '[חָזֵ֣ה] [הֲוֵ֔ית] [בֵּאדַ֗יִן] de [מִלַּיָּ֣א] [רַבְרְבָתָ֔א] [דִּ֥י] que [מְמַלֱּלָ֑ה] [חָזֵ֣ה] [הֲוֵ֡ית] até até [קְטִילַ֤ת] [חֵֽיוְתָא֙] [וְהוּבַ֣ד] [גִּשְׁמַ֔הּ] [וִיהִיבַ֖ת] [לִיקֵדַ֥ת] [אֶשָּֽׁא]');
INSERT INTO verses VALUES (22014, 27, 7, 12, 'e-restante-de [חֵֽיוָתָ֔א] [הֶעְדִּ֖יו] [שָׁלְטָנְה֑וֹן] [וְאַרְכָ֧ה] [בְחַיִּ֛ין] [יְהִ֥יבַת] [לְה֖וֹן] até [וְעִדָּֽן]');
INSERT INTO verses VALUES (22015, 27, 7, 13, '[חָזֵ֤ה] [הֲוֵית֙] [בְּחֶזְוֵ֣י] [לֵֽילְיָ֔א] [וַאֲרוּ֙] com [שְׁמַיָּ֔א] [כְּבַ֥ר] [אֱנָ֖שׁ] [אָתֵ֣ה] [הֲוָ֑ה] [וְעַד־עַתִּ֤יק] e-até [מְטָ֔ה] [וּקְדָמ֖וֹהִי] [הַקְרְבֽוּהִי]');
INSERT INTO verses VALUES (22016, 27, 7, 14, 'וְלֵ֨הּ יהיב שלטן ויקר וממלכוּ e-tudo עַֽמְמַיָּ֗א אֻמַיָּ֛א וְלִשָּׁנַיָּ֖א לֵ֣הּ serão espantados ela reinará reinante em todo o mundo que não e verá e a sua realeza que não será estabelecida');
INSERT INTO verses VALUES (22017, 27, 7, 15, 'sua força o meu espírito ainda DANIEL BAGO NIDNEH E HEZVEI REISHI YEBHALUNNI:');
INSERT INTO verses VALUES (22018, 27, 7, 16, '[קִרְבֵ֗ת] sobre [מִן־קָ֣אֲמַיָּ֔א] de [אֶבְעֵֽא־מִנֵּ֖הּ] [עַֽל־כָּל־דְּנָ֑ה] [וַאֲמַר־לִ֕י] [וּפְשַׁ֥ר] sobre todo');
INSERT INTO verses VALUES (22019, 27, 7, 17, '[אִלֵּין֙] [חֵיוָתָ֣א] [רַבְרְבָתָ֔א] que [אִנִּ֖ין] quatro [אַרְבְּעָ֥ה] contra-reis [יְקוּמ֥וּן] de');
INSERT INTO verses VALUES (22020, 27, 7, 18, '[וִֽיקַבְּלוּן֙] [מַלְכוּתָ֔א] [קַדִּישֵׁ֖י] [עֶלְיוֹנִ֑ין] [וְיַחְסְנ֤וּן] [מַלְכוּתָא֙] [עֽ͏ַד־עָ֣לְמָ֔א] [וְעַ֖ד] e-até [עָלְמַיָּֽא]');
INSERT INTO verses VALUES (22021, 27, 7, 19, 'עדין צבית לייצבא sobre HEYוְתָא רביעית que הֲוָ֥ת שָֽׁנְיָ֖ה de דְּחִילָ֣ה יַתִּ֗ירָה que פַרְזֶל֙ וְטִפְרַ֣יהּ que נְחָ֔שׁ אָֽכְלָ֣ה מַדֲּקָ֔ה וּשְׁאָרָ֖א pelos-seus-pés enrolou-se;');
INSERT INTO verses VALUES (22022, 27, 7, 20, 'e-sobre as-cornear dez que no-início e-trás-de-mim que caminhou de três e-cornear as-ovais e-a-vênim para-a e-por-a que-murmura Rabban e-sua-virtude muito de sua-amizade');
INSERT INTO verses VALUES (22023, 27, 7, 21, 'veja seja e-corno de-ela עָבְדָ֥ה קְרָ֖ב com קַדִּישִׁ֑ין וְיָכְלָ֖ה לְהֽוֹן׃');
INSERT INTO verses VALUES (22024, 27, 7, 22, 'até que אֲתָ֗ה עַתִּיק֙ יֽוֹמַיָּ֔א וְדִינָ֣א יְהִ֔ב para-santos superiores e-tempo de-sede e-reino nossa-proteção santos:');
INSERT INTO verses VALUES (22025, 27, 7, 23, 'assim disse seu-olho quarto reinado תֶּהֱוֵ֣א בְאַרְעָ֔א que תִשְׁנֵ֖א de todo מַלְכְוָתָ֑א וְתֵאכֻל֙ todo אַרְעָ֔א וּתְדוּשִׁנַּ֖הּ וְתַדְּקִנַּֽהּ׃');
INSERT INTO verses VALUES (22026, 27, 7, 24, '[וְקַרְנַיָּ֣א] dez [מִנַּהּ֙] [מַלְכוּתָ֔ה] [עַשְׂרָ֥ה] contra-reis [יְקֻמ֑וּן] [וְאָחֳרָ֞ן] [יְק֣וּם] [אַחֲרֵיה֗וֹן] e-ele [יִשְׁנֵא֙] de [וּתְלָתָ֥ה] [מַלְכִ֖ין] contra-reis');
INSERT INTO verses VALUES (22027, 27, 7, 25, 'e palavras para o lado irá falar ule-kadishi superiores irá envenenar e discutirá para a contenda tempo e lei e se exaltarem em sua mão até idade e idades e dividir idade');
INSERT INTO verses VALUES (22028, 27, 7, 26, 'e reino e possuirá e dominará e governará para destruição e para divisão até fim;');
INSERT INTO verses VALUES (22029, 27, 7, 27, 'e para a monarquia e para o domínio e para a abundância que monarquia sob todo os céus ele dará para o povo os santos superiores sua realeza reino e-tudo e-todo domineis para ela os maravilhem e ouçam-no:');
INSERT INTO verses VALUES (22030, 27, 7, 28, 'até assim fim que palavra ânah dâniêl sagí ra''ûyânai yebhâlûnnî veziyâ yishtannôn alây e palavra no meu coração foi revelada:');
INSERT INTO chapters VALUES (858, 27, 8, 27);
INSERT INTO verses VALUES (22031, 27, 8, 1, 'em-ano-de três para-reinado Belacar o-rei vista, visão foi revelada a-mim eu Daniel depois-de a revelação para-mim no começo:');
INSERT INTO verses VALUES (22032, 27, 8, 2, '[וָֽאֶרְאֶה֮] [בֶּחָזוֹן֒] e-houve [בִּרְאֹתִ֔י] e-eu em-Susa [הַבִּירָ֔ה] que [בְּעֵילָ֣ם] [הַמְּדִינָ֑ה] [וָאֶרְאֶה֙] [בֶּֽחָז֔וֹן] e-eu estava sobre [אוּלָֽי]');
INSERT INTO verses VALUES (22033, 27, 8, 3, 'e-levantei meus-olhos וָאֶרְאֶ֔ה והנה a-ovelha-machão um um diante-de o abúl e-ló kérana''im e-ha-kérana''im gábohóth e-há-achát alta de הַשֵּׁנִ֔ית e-ha-gábohá holocausto בָּאַחֲרֹנָה׃');
INSERT INTO verses VALUES (22034, 27, 8, 4, 'vi a ha-ayil ménagga'' yá''má וְצָפ֨וֹנָה וָנֶ֗גְבָּה e-todo חַיּוֹת֙ não יַֽעַמְד֣וּ diante-dele e-não-há מַצִּ֖יל מִיָּד֑וֹ e fez כִרְצֹנ֖וֹ וְהִגְדִּֽיל׃');
INSERT INTO verses VALUES (22035, 27, 8, 5, '[וַאֲנִ֣י] [׀] [הָיִ֣יתִי] e-eis [וְהִנֵּ֤ה] [צְפִיר־הָֽעִזִּים֙] veio de [עַל־פְּנֵ֣י] sobre face-de todo a-terra e-não-há [קֶ֥רֶן] em-a-terra entre chifre-de entre');
INSERT INTO verses VALUES (22036, 27, 8, 6, 'E-veio até [בַּ֣עַל] בַּ֣עַל [אֲשֶׁ֣ר] que [עֹמֵ֖ד] ficou-em-pé diante-de [וַיָּ֥רָץ] a-ele a-ele [כֹּחֽוֹ]');
INSERT INTO verses VALUES (22037, 27, 8, 7, 'e vê-lo chegando junto-a o-velo e se irritou a-ele a-ele a o-abelhaue e quebrou a duas seus chifres e-não foi força no carneiro para se opor diante-dele e atirou-o terra e o derrubou e-não foi resgatou para-o-carneiro imediatamente');
INSERT INTO verses VALUES (22038, 27, 8, 8, 'e resplandeceu os-cabritos enormou-se até muito e em si mesmo quebraram-se a coroa o-grande e subiu visão quatro tachatetha para quatro רוחות os-céus');
INSERT INTO verses VALUES (22039, 27, 8, 9, 'e-de [מֵהֶ֔ם] sair [קֶֽרֶן־אַחַ֖ת] [מִצְּעִירָ֑ה] uma [אֶל־הַנֶּ֥גֶב] [וְאֶל־הַמִּזְרָ֖ח] [וְאֶל־הַצֶּֽבִי] a e-a e-a');
INSERT INTO verses VALUES (22040, 27, 8, 10, 'ותגדל até exército-de os-céus e caiu prostrou-se de o-exército e-de as-estrelas e estremeceu;');
INSERT INTO verses VALUES (22041, 27, 8, 11, 'e-ate chefe o-exército aumentou e dele o-contínuo e foi lançado instrumento seu santuário;');
INSERT INTO verses VALUES (22042, 27, 8, 12, 'e exército será dado sobre a-perpétua בְּפָ֑שַׁע וְתַשְׁלֵ֤ךְ verdade terra-para e fará וְהִצְלִֽיחָה׃');
INSERT INTO verses VALUES (22043, 27, 8, 13, '[וָאֶשְׁמְעָ֥ה] [אֶֽחָד־קָד֖וֹשׁ] santo E-disse um um santo [הַֽמְדַבֵּ֗ר] [עַד־מָתַ֞י] até [הַתָּמִיד֙] [וְהַפֶּ֣שַׁע] [שֹׁמֵ֔ם] [תֵּ֛ת] [וְקֹ֥דֶשׁ] [וְצָבָ֖א] [מִרְמָֽס]');
INSERT INTO verses VALUES (22044, 27, 8, 14, 'E-disse a-mim até tarde manhã dois-mil e-três centenas וְנִצְדַּק קֹדֶשׁ׃');
INSERT INTO verses VALUES (22045, 27, 8, 15, 'e-houve [בִּרְאֹתִ֛י] eu [דָנִיֵּ֖אל] a [וָאֲבַקְשָׁ֣ה] [בִינָ֔ה] [וְהִנֵּ֛ה] e-eis ficou-em-pé [כְּמַרְאֵה־גָֽבֶר]');
INSERT INTO verses VALUES (22046, 27, 8, 16, 'VASHMAʿ voz-de entre entre E-chamou E-chamou E-disse GBRIEL HAVEN להראז a המראה׃');
INSERT INTO verses VALUES (22047, 27, 8, 17, 'E-veio junto-a עמדי e quando ele entrar eu estremeci e caí sobre E-disse E-disse a-mim o filho que homem porque na época de a consumação este sonho:');
INSERT INTO verses VALUES (22048, 27, 8, 18, 'e quando ele falou comigo eu caí sobre face-de terra e tocou em-mim e me pôs sobre sta:$');
INSERT INTO verses VALUES (22049, 27, 8, 19, 'E-disse eis-me faz-te saber: a que será no fundo que porque ao convênio destruição:$');
INSERT INTO verses VALUES (22050, 27, 8, 20, 'o-abelhaia que viste: בַּ֣עַל as ovelhas melechey- minha força e separaste:');
INSERT INTO verses VALUES (22051, 27, 8, 21, 'e a zafir o seahr rei Javan e a keren a grande que entre ele ele o-rei o-primeiro:');
INSERT INTO verses VALUES (22052, 27, 8, 22, 'e a nishbaret e elas se estabeleceram quatro תַּחְתֶּ֑יהָ quatro rainhas de um povo elas se estabeleceram e-não em seu poder:');
INSERT INTO verses VALUES (22053, 27, 8, 23, 'e-em-último seu-reino sacerdócio-vos os-perversos se-manterá rei força- face e-compreendendo enigmas:');
INSERT INTO verses VALUES (22054, 27, 8, 24, 'e-potência seu-força e-não por seu poder e maravilhas destruirá e-sucederá e fará e destruirá grandes ו העם- santos:');
INSERT INTO verses VALUES (22055, 27, 8, 25, 'e-sobre e seus entendimentos e triunfará por engano em-mão-de-ele e-no-lábabo ja-gad-dil e-be-shal-va ja-sha-chit muitos e-sobre príncipe-de sar-im mão וּבְאֶ֥פֶס mão yi-sha-ber');
INSERT INTO verses VALUES (22056, 27, 8, 26, 'e-mar-eh ha-er-ev ve-ha-bo-qer que ne-am-ar אֱמֶ֣ת ele e-tu סְתֹ֣ם הֶֽחָז֔וֹן que לְיָמִ֥ים muitos');
INSERT INTO verses VALUES (22057, 27, 8, 27, 'e-eu דָנִיֵּ֗אל נִהְיֵ֤יתִי וְנֽ͏ֶחֱלֵ֙יתִי֙ dias וָאָק֕וּם וָאֶֽעֱשֶׂ֖ה a obra-de o-rei וָאֶשְׁתּוֹמֵ֥ם sobre a-mar''eh e-não-há מֵבִֽין׃');
INSERT INTO chapters VALUES (859, 27, 9, 27);
INSERT INTO verses VALUES (22058, 27, 9, 1, 'no-ano-de uma [לְדָרְיָ֛וֶשׁ] filho-de [מִזֶּ֣רַע] [מָדָ֑י] [אֲשֶׁ֣ר] que sobre sobre [כַּשְׂדִּֽים]');
INSERT INTO verses VALUES (22059, 27, 9, 2, 'em-ano-de uma para-reinar-dele eu דנייאֵל בינתִי בספרִים número הַשָׁנִ֗ים que ser palavra-de yhwh a Jeremias o-profeta para-enchendo para-destruir Jerusalém setenta anos');
INSERT INTO verses VALUES (22060, 27, 9, 3, 'e-dei a face-de a Adonai הָֽאֱלֹהִ֔ים para-buscar oração e-supplicações em-jejum e-de-nu e-fuligem');
INSERT INTO verses VALUES (22061, 27, 9, 4, 'e-eu-orava para-יהוה Elohim-meu e-eu-confessava e-eu-dizia [אָנָּ֤א] Adonai o-Elohim a-grande e-o-noraa guardador-de a-aliança e-o-chessed para-amadores-seus e-para-guardadores-de mandamentos-seus');
INSERT INTO verses VALUES (22062, 27, 9, 5, 'chatanu ve-avinu umardadnu vesor [וּמָרָ֑דְנוּ] ume-mishpatekteka');
INSERT INTO verses VALUES (22063, 27, 9, 6, 'e-não ouvimos a teus-servos os-profetas que diguem em-o-teu-nome a o-nostronois-rei e-para [כָּל־עַ֥ם] a-terra todo povo a-terra');
INSERT INTO verses VALUES (22064, 27, 9, 7, 'a-ti Adonai הַצְּדָקָ֔ה e-a-nos em-baston as-faces kayom este a-o-homem Judá e-aos-que-habitam Jerusalém e-para-todo Israel os-próximos e-os-longínquos em-todo as-terra que expuls-tam nome [מָֽעֲלוּ־בָֽךְ] que maaulu- em-te:');
INSERT INTO verses VALUES (22065, 27, 9, 8, 'yhwh laanu בֹּשֶׁת haapanim limmelacheinu lesareinu [וְלַאֲבֹתֵ֑ינוּ] que pecamos para-ti');
INSERT INTO verses VALUES (22066, 27, 9, 9, '我主 nosso-Elohim harachamim veselsihot que rebelamo nele');
INSERT INTO verses VALUES (22067, 27, 9, 10, 'e-não ouvi-mo בְּקוֹל yhwh nosso-Elohim para-andar em-o-sus-leis que dar diante-de-nós na-mão-de seus-servos os-profetas');
INSERT INTO verses VALUES (22068, 27, 9, 11, 'e-todo Israel passa-ram a para-não e-separa para-não ouve em-a-tua-voz e-te-moves sobre-nós a-curse e-o-swear que escrita-ha em-a-lei-de que servo- a-ele porque pecamos a-ele');
INSERT INTO verses VALUES (22069, 27, 9, 12, 'E-levantou a que palavra sobre-nos e-sobre juízes-nossos que julgai-nos para-trazer sobre nós mal grande que não nós-fomos-feitos debaixo todo os-céus como nós-fomos-feitas em-Jerusalém');
INSERT INTO verses VALUES (22070, 27, 9, 13, 'como foi escrito em-lei-de Moisés a todo a-maldade esta veio sobre-nós e-não início-nosso yhwh faces-de yhwh nosso-Elohim para-retornar de-nossos-pecados e-para-saber em-verdade-te:');
INSERT INTO verses VALUES (22071, 27, 9, 14, 'e-ele-deitou-se yhwh sobre a-maldade e-ele-trouxe-a sobre-nós yhwh justo yhwh nosso-Elohim sobre todo de-seus-atos que fez e-não o-dia na-sua-voz');
INSERT INTO verses VALUES (22072, 27, 9, 15, 'e-agora Adonai nosso-Elohim que tu-saiu-te a povo-tua da terra Egito com a mão forte e-você-fez- para-ti nome kayom este pecamos reprovamos-vos');
INSERT INTO verses VALUES (22073, 27, 9, 16, 'Adonai conforme-toda justiças-teu habita- por-favor teu-apo e-ira-teu de-cidade-teu que monte-de sua santidade porque em-pecados-nosso e-em-iniquidades nossos-pais Jerusalém e-povo-teu para-escarnecimento para-todo [sem-traducao]');
INSERT INTO verses VALUES (22074, 27, 9, 17, 'e-agora ouviu nosso-Elohim a oração-de-a teu-servo e-a súplica-seu e-illumina-o perante-você sobre templo-te-de-a o-desolado para-que Adonai');
INSERT INTO verses VALUES (22075, 27, 9, 18, 'e levantou-se Elohim-me אָזְנְךָ֮ e-ouça-o os-teus-olhos וּרְאֵה֙ [**פְּקַ֣ח] e-a-cidade que foi-chamado o-teu-nome sobre-ela que não que justiças-nossas não derrubando súplicas-nossas diante-de-ti porque sobre que os-muitos-verso-final');
INSERT INTO verses VALUES (22076, 27, 9, 19, 'Adonai ouça Adonai perdôe Adonai ouça-a e-fazes a atrasa por-causa-teu meu-Elohim porque teu-nome é-chamado sobre de-teu-cidade e-sobre povo-tua');
INSERT INTO verses VALUES (22077, 27, 9, 20, 'e-mais eu fala- e-orando e-se-confessa pecado-meu e-pecado meu-povo Israel e-joga súplica-meu diante-de yhwh meu-Elohim sobre monte-de santidade-de yhwh');
INSERT INTO verses VALUES (22078, 27, 9, 21, 'e-mais eu falando em-o-orar e-o-homem Gabriel que vi-a no-vision em-o-primeiro-tempo voando e-voou nog''ah a-mim tempo oferta-de tarde');
INSERT INTO verses VALUES (22079, 27, 9, 22, 'e-ele-compreendeu e-falou comigo E-disse Daniel עַתָּה saí-ei para-te-esclarecer com-inteligência-');
INSERT INTO verses VALUES (22080, 27, 9, 23, 'no-princípio de-tus-suplicas sair palavra e-eu בָּ֣אתִי para-dizer que desejáveis tu e-entenda na-coisa e-entenda no-visionamento');
INSERT INTO verses VALUES (22081, 27, 9, 24, 'semanas setenta te-falhar sobre o-teu-povo e-sobre cidade os-teus-santos para-fazer-circular o-peca e-para-perdoar pecado e-para-trazer justica das-era e-a-timbrar חָז֣וֹן e-propheta e-para-unger santidade-de santos');
INSERT INTO verses VALUES (22082, 27, 9, 25, 'e-serás-sabendo e-fazeres-ponderar de saída palavra para-retornar e-a-construir Jerusalém até mashiaḥ príncipe shavu''im sete ve-shavu''im sessenta ushnayim volverás venibnetah rechov ve-charutz ubtsoq ha-ittim');
INSERT INTO verses VALUES (22083, 27, 9, 26, 've-acharei os-sete sessenta e-dois será-cortado o-messias e-não-há a-ele e-a-cidade e-o-santo destruirá povo o-príncipe o-vindo e-seu-fim com-o-remoinho e-ate fim guerra necoretet shomemot');
INSERT INTO verses VALUES (22084, 27, 9, 27, 've-higbir em-o-brith larabim shavua um e-metade-de hashavua yashbit sacrifício-de וּמִנְחָ֗ה e-sobre kenaf shikkutzim [שִׁקּוּצִים֙] e-até completo venechrata teu-lugar sobre estrangeiro-verso-final');
INSERT INTO chapters VALUES (860, 27, 10, 21);
INSERT INTO verses VALUES (22085, 27, 10, 1, 'no-ano-de três-marcador-pausa para-Ciro rei Pérsia palavra foi-revelado a Daniel que foi-chamado seu-nome Belteshatstsar-acento-ponderado e-verdade a-palavra e-exército grande e-inteligência a a-ele e-entendimento para-ele no-visionamento-verso-final');
INSERT INTO verses VALUES (22086, 27, 10, 2, 'em-os-dias os-aqueles eu Daniel eu-fui de-luto três semanas dias');
INSERT INTO verses VALUES (22087, 27, 10, 3, 'pão desejadas não comi-eu e-carne e-vinho não veio a o meu e-tenda não tendei-eu até cheio três semanas dias');
INSERT INTO verses VALUES (22088, 27, 10, 4, 'e-no-dia vinte e-quatro no-mês o-primeiro e-eu estive sobre mão o-rio o-grande ele Chiddeqel-');
INSERT INTO verses VALUES (22089, 27, 10, 5, 'e-levantei a meus-olhos e-eu-vi e-eis homem-de um para-o-vestiario em-teias e-seus-lombos cinturados não Ophir-');
INSERT INTO verses VALUES (22090, 27, 10, 6, 'e-seu-corpo [כְתַרְשִׁ֗ישׁ] [וּפָנָ֞יו] [כְּמַרְאֵ֤ה] [בָרָק֙] וְעֵינָיו֙ [כְּלַפִּ֣ידֵי] fogo [וּזְרֹֽעֹתָיו֙] [וּמַרְגְּלֹתָ֔יו] [כְּעֵ֖ין] נְחֹ֣שֶׁת [קָלָ֑ל] e voz palavras-dele [כְּק֥וֹל] grande-número;');
INSERT INTO verses VALUES (22091, 27, 10, 7, 'e-vi eu Daniel para-afastado-de-mim a a-visionada e-os-homens que eram não não Ra''u a da-visionada mas terror grande caindo sobre-eles [sem-traducao] em-se-esconder;');
INSERT INTO verses VALUES (22092, 27, 10, 8, 'e-eu nِsharَtִi lebadí ve-eréh a ha-maréah הַגְּדֹלָה֙ esta e-não ficaram- em-mi koach ve-hodí nehphakh sobre-mim le-mash-chit e-não atazrَtִi FORÇA:');
INSERT INTO verses VALUES (22093, 27, 10, 9, 've-eshmáh a voz-de devaráyv ukhashaméyi a voz-de davarav e-eu estive dormindo sobre face-de e-minhas-faces para-terra');
INSERT INTO verses VALUES (22094, 27, 10, 10, 'e-eis mão toque-a em-mim e-me-movimentaram sobre em-minhas-canelas e-palmas-de minhas-mãos');
INSERT INTO verses VALUES (22095, 27, 10, 11, 'E-disse para mim דנייאל homem-de desejados o-filho em-palavras eu eu palavra a-ti e-estacionar que teu-permaneceres porque agora foi-me enviado a-ti e-em-sua-palavra comigo a a-palavra este estou-estacionado tremeu');
INSERT INTO verses VALUES (22096, 27, 10, 12, 'E-disse para-mim a tire-a que que de o-dia o-primeiro que destituíste a teu-corpo para-entender e-para-abster-se diante-de teu-Elohim ouviram teus-palavras e eu venho-eu em-tua-palavras');
INSERT INTO verses VALUES (22097, 27, 10, 13, 'e-sar reino para-Paras ficou-em-pé em-minha-frente vinte ve-echad dia dia Michael um os-sars הָרִאשֹׁנִ֖ים veio para-ajudar-me e-eu permaneço-eu nome junto reis-de Paras');
INSERT INTO verses VALUES (22098, 27, 10, 14, 'e-vim para-a-entenda-te a que ele-chamará לעמך no fundo os-dias porque ainda visão para-os-dias');
INSERT INTO verses VALUES (22099, 27, 10, 15, 'e quando ele falou comigo segundo-as-palavras estes dei face-de terra-para [וְנֶאֱלָֽמְתִּי]');
INSERT INTO verses VALUES (22100, 27, 10, 16, 'e-eis como-a-forma-de filhos-de homem que-toca sobre lábios-meus e-eu-abri-o- meu-boca e-eu-falei e-eu-disse a o-que-está-em-pé para-o-frente-de-mim Adonai em-a-imagem viraram-se meus-companheiros-de-trabalho sobre-mim e-não detive-me FORÇA:');
INSERT INTO verses VALUES (22101, 27, 10, 17, 'e-quando poderia servo Adonai este para-falar com Adonai esta e-eu desde-o-tempo não vai-estar-de-pé não força e-nalma não n-shara- בי׃');
INSERT INTO verses VALUES (22102, 27, 10, 18, 'e-acrescentou וַיִּגַּע־ b-i homem homem v-y-chazqeni:');
INSERT INTO verses VALUES (22103, 27, 10, 19, 'E-disse a t-ira homem-de para-ti shalom para-ti forte v-chazaq u-b-davar-o comigo h-t-chazqati: v-omrata que Adonai porque chazaqtani:');
INSERT INTO verses VALUES (22104, 27, 10, 20, 'E-disse h-conheceste por-que בָּ֣אתִי e-agora e-agora irei-voltar para-lutar com comandante-de Pérsia e-eu saiendo-sairá e-eis príncipe-de Javã veio');
INSERT INTO verses VALUES (22105, 27, 10, 21, 'mas darei-contar-eu a-ti a o-gravado-escrito em-a-letra verdade um um de-se-fortalecer comigo que אֵלֶּה porque se micha-eil príncipe-vosso');
INSERT INTO chapters VALUES (861, 27, 11, 45);
INSERT INTO verses VALUES (22106, 27, 11, 1, 'e-eu no-ano-de uma para-dar-yavesh o-madi está-me-stand para-a-sustentação e-para-o-refúgio a-ele');
INSERT INTO verses VALUES (22107, 27, 11, 2, 'e-agora Emet eu-direi para-ti eis ainda שְׁלֹשָׁ֨ה reis estão-stando para-a-perda e-o-quarto ele-enriquecerá de-toda grande de-todo e-conforme-a-sua-força em-o-seu-ano iluminará o todo a מלכות Yavã');
INSERT INTO verses VALUES (22108, 27, 11, 3, 'e-permanecerá rei גִּבּ֑וֹר e-reinará de-reinado muito e-fará conforme-seu-querer');
INSERT INTO verses VALUES (22109, 27, 11, 4, 'e-conforme-permanecerá será-partida reino-dele e-será-escarnecida para quatro ventos os-céus e-não para-a-sua-fim e-não como-seu-mandato que mashal que será-estabelecido reino-dele e-a-outros fora-de Estas');
INSERT INTO verses VALUES (22110, 27, 11, 5, 'e-se-fortalecerá rei-de o-sul e-de seirav e-se-fortalecerá sobre-ele e-mandato [מֶמְשַׁלְתּֽוֹ] muito sua soberania:');
INSERT INTO verses VALUES (22111, 27, 11, 6, 'e-a-fim dois se-unirão e-da-filha rei-de do-sul virá a rei do-norte para-fazer de-retos e-não [וְלֹ֤א] força do-braco e-não estará [וּמְבִיאֶ֙יהָ֙] [וְהַיֹּ֣לְדָ֔הּ] ela [בָּעִתִּֽים] [sem-traducao] [sem-traducao] [sem-traducao]');
INSERT INTO verses VALUES (22112, 27, 11, 7, '[וְעָמַ֛ד] [מִנֵּ֥צֶר] [שָׁרָשֶׁ֖יהָ] [כַּנּ֑וֹ] E-veio a hachayil E-veio em-o-refúgio rei o-setentrional e fez neles e-estabelecerá');
INSERT INTO verses VALUES (22113, 27, 11, 8, 'e-também os-elohim-deles com as-oferendas-deles com os-ferramentas-de-serviço a-preciosidade-deles prata e-ouro no-tempo trará Egito e-ele dois ele se levantará do-rei o-setentrional');
INSERT INTO verses VALUES (22114, 27, 11, 9, 'e-vem em-malqu-t rei o-sul וְשָׁ֖ב a sua terra:');
INSERT INTO verses VALUES (22115, 27, 11, 10, 'e-tegaru e-asefu המון֙ chayalim muitos וּבָ֥א bo-a e-shataph e-avar e-yashov até');
INSERT INTO verses VALUES (22116, 27, 11, 11, 'e-yitmarmar rei o-sul e-sairá e-lutará com-ele com rei o-norte e-estabelecerá multidão muito e-será-dado o-tumulto em-mão-sua');
INSERT INTO verses VALUES (22117, 27, 11, 12, 'e-será-elevado o-tumulto לבבו e-jogará multidões e-não força');
INSERT INTO verses VALUES (22118, 27, 11, 13, 'וְשָׁב֙ rei do-norte e-o-estabelecerá הָמ֔וֹן muito de o-primeiro e-no-fim os-tempo dois virá vem [גָּד֖וֹל] grande e-com-riqueza muito');
INSERT INTO verses VALUES (22119, 27, 11, 14, 'e-no-tempo aqueles muitos estarão-em-pé sobre rei do-sul [׀] [פָּרִיצֵ֣י] o-teu-povo [יִֽנַּשְּׂא֛וּ] [לְהַעֲמִ֥יד] visão [וְנִכְשָֽׁלוּ]');
INSERT INTO verses VALUES (22120, 27, 11, 15, 'E-veio rei do-norte [וְיִשְׁפֹּךְ֙] [סֽוֹלֲלָ֔ה] [וְלָכַ֖ד] cidade [מִבְצָר֑וֹת] e-os-braços o-sul não יַעֲמֹ֔דוּ e-o-povo de-seleção-dele e-não-há כח para-estar-parado-verso-final');
INSERT INTO verses VALUES (22121, 27, 11, 16, 'E-fez הַבּ֤א a-ele conforme-sua-vontade e-não-há estando diante-dele e-ele-estará-de-pé em-terra-de o-cervo e-completo em-sua-mão');
INSERT INTO verses VALUES (22122, 27, 11, 17, 'e-ele-colocará per-nau-yim para-vir be-toqef todo seu reino ve-yishar-im com-ele e fará u-bat as-mulheres dê a-ele le-hash-chita-ha e-não ta-amod e-não a-ele ela-será');
INSERT INTO verses VALUES (22123, 27, 11, 18, 'per-nau-yim le-ayy-im ve-la-chad muitos ve-hish-bit oficial-ou-capitão sua-desgraça a-ele para-não sua-desgraça a-ele a-ele');
INSERT INTO verses VALUES (22124, 27, 11, 19, 'e-se-estabelecerá rosto-dele para-os-refúgios-de terra-dele e-será-enredado e-cairá e-não será-achado');
INSERT INTO verses VALUES (22125, 27, 11, 20, 'e-se-apresentará sobre como-ele passar nogesh heder reino u-v-yamim a-chadim yish-shaver e-não b-af-payim e-não b-milchama');
INSERT INTO verses VALUES (22126, 27, 11, 21, 'u-amad sobre k-anno nivze e-não eles-deram sobre-ele glória reino וּבָ֣א em-salva e-o-estreitou reino-de no-chalaklako');
INSERT INTO verses VALUES (22127, 27, 11, 22, 'e-os-bracos o-que-flui serao-sufocados de-ante-o-lhe e-serao-partidos e-também principe em-brisa');
INSERT INTO verses VALUES (22128, 27, 11, 23, 'e-de a-ele a-ele fará מִרְמָה e-subirá e-osso com-pouco- nação');
INSERT INTO verses VALUES (22129, 27, 11, 24, 'em-peace e-em-oil de-a-província ele-virá e-fará que não asau אביו e-avós seus-pais em-desprezo e-presa a-eles lahem ele-ará e-sobre de-fortalezas ele-contará pensamentos-seus e-até tempo:');
INSERT INTO verses VALUES (22130, 27, 11, 25, 'e-levantará força-seu e-corpo-seu sobre rei o-sul com-forteza grande e-rei o-sul ele-se-desafiara para-a-guerra com-forteza- grande e-grande até muito e-não ele se levantará porque pensarão sobre-ele pensamentos');
INSERT INTO verses VALUES (22131, 27, 11, 26, 'e-comedores-de de-o bode quebrarão-o e-seu-exército soprará e-cairão que-são-desecrados muitos');
INSERT INTO verses VALUES (22132, 27, 11, 27, 'e-os-duas-deles hamalkim para-seu-coração [לְמֵרָ֔ע] e-sobre um um [יְדַבֵּ֑רוּ] יְדַבְּרֻ e-não [כִּי־ע֥וֹד] porque ainda [sem-traducao] para-a-festa');
INSERT INTO verses VALUES (22133, 27, 11, 28, '[וְיָשֹׁ֤ב] sua-terra [בִּרְכ֣וּשׁ] grande [וּלְבָב֖וֹ] sobre aliança santidade e-fará ושׁוב לְאַרְצֽוֹ׃');
INSERT INTO verses VALUES (22134, 27, 11, 29, '[לַמּוֹעֵ֥ד] ישוב וּבָ֣א [בַנֶּ֑גֶב] e-não תִהְיֶה como-a-primeira-vez e-como-o-finalmente');
INSERT INTO verses VALUES (22135, 27, 11, 30, 'e-entraram nele selvagens como-tartarugas e-se-irritou e-voltará e-zangar-se-á sobre de-pacto- santo e fará e-retornou e-compreenderá sobre abandonadores-de yhwh קֹדֶשׁ׃');
INSERT INTO verses VALUES (22136, 27, 11, 31, 'e-armadores nós estão-se e-profanaram o-santuário a-refúgio e-retiraram o-contínuo e-dêem o-abominável desolador');
INSERT INTO verses VALUES (22137, 27, 11, 32, 'e-perversos da-aliança yachanif bachelakot veam conhecendo Elohav yachazqu veasou');
INSERT INTO verses VALUES (22138, 27, 11, 33, 'umashkilie povo yabino laravim venichshu bchered e-na-chama em-o-prisionamento e-no-desprezo dias');
INSERT INTO verses VALUES (22139, 27, 11, 34, 'e-na-sua-caida serao-ajudados auxiliar pequena e-se-submeterao sobre-eles muitos em-o-mesmo-erro');
INSERT INTO verses VALUES (22140, 27, 11, 35, 'e-de os-sabios cairao para-fundir בָּהֶ֛ם e-livrar e-para-branco até tempo fim porque a-ele para-a-festa');
INSERT INTO verses VALUES (22141, 27, 11, 36, 'e-fará conforme-seu-querer o-rei e-ele-exaltarão [וְיִתְגַּדֵּל֙] sobre todo El e-sobre El elohimes ele-falará niflaot e-ele-sucederá que terminou za''am porque nечharatsа neeshatah');
INSERT INTO verses VALUES (22142, 27, 11, 37, 'e-sobre Elohim-de não não yavin- e-sobre chemdat não e-sobre que elohim não entenderá porque sobre todo yitgadalah');
INSERT INTO verses VALUES (22143, 27, 11, 38, '[וְלֶאֱלֹ֙הַּ֙] maazim sobre seu-copo yekabed velaelohim que não yedaahu seus-pais honrará em-o-ouro e-em-a-prata e-em-a-pedra preciosa e-no-prezado');
INSERT INTO verses VALUES (22144, 27, 11, 39, 'e-fará para-os-castelos de-a-estabilidade com Eloah o-extrangeiro que aumentará [יַרְבֶּ֣ה] [כָב֑וֹד] [וְהִמְשִׁילָם֙] e-terra יְחַלֵּ֥ק por-preço');
INSERT INTO verses VALUES (22145, 27, 11, 40, '[וּבְעֵ֣ת] [קֵ֗ץ] [יִתְנַגַּ֤ח] com-ele rei o-sul [וְיִשְׂתָּעֵ֨ר] sobre-ele rei o-norte [בְּרֶ֙כֶב֙] [וּבְפָ֣רָשִׁ֔ים] [וּבָאֳנִיּ֖וֹת] muitas וּבָ֥א em-a-terra-sua e-lavou e-passou');
INSERT INTO verses VALUES (22146, 27, 11, 41, 'e-ele-virá na-terra o-veado e-muitas cairão e-estes escaparão de-a-mão-sua edom e-Moabe e-primeira filhos-de Amon');
INSERT INTO verses VALUES (22147, 27, 11, 42, 'e enviará sua-mão em-terra-s ve-erets Egito não será liflitâ:');
INSERT INTO verses VALUES (22148, 27, 11, 43, 'e-masal em-mikmanei o-ouro e-o-kesev e em tudo hamudot Egito e-lubim e-kushim em-mitzwadoyv');
INSERT INTO verses VALUES (22149, 27, 11, 44, 'u-shemuot yevehaluhu do-leste e-do-norte e-saiu com-ira grande para-destruir e-para-devastar muitos');
INSERT INTO verses VALUES (22150, 27, 11, 45, 'e-plantará tendas-de Apadno entre mares para-monte-de belo- santidade e-ele-virá até a-ele e-não-há ajudando a-ele');
INSERT INTO chapters VALUES (862, 27, 12, 13);
INSERT INTO verses VALUES (22151, 27, 12, 1, 'e-no-tempo-de a-ela estará Micael o-príncipe a-grande que-está-parado sobre filhos-de povo-teu וְהָיְתָה֙ tempo em-trabalho-difícil que não tornou-se até nação até a-oração aquela e-na-oração a-essa será-escapado o-povo-tuo todo yhwh escrito no-livro');
INSERT INTO verses VALUES (22152, 27, 12, 2, 'e-muitos de-entre terra-de pó Estas estas-estes eternidade eternidade e-aqueles para-os-opositores eternidade eternidade');
INSERT INTO verses VALUES (22153, 27, 12, 3, 'e-os-sábios prevaricarão como-a-luz a-expansão e-os-justos haravim como-os-estrelas para-sempre e-perpetuidade');
INSERT INTO verses VALUES (22154, 27, 12, 4, 'e-tu Daniel fechado as-palavras e-assinatar o-livro até tempo fim andarão muitos e-aumentará o-conhecimento');
INSERT INTO verses VALUES (22155, 27, 12, 5, 'e-vi eu Daniel e-eis dois outros estando um eis-aqui língua-de o-rio e-um henah língua-de o-rio');
INSERT INTO verses VALUES (22156, 27, 12, 6, 'E-disse para-o-homem para-o-vestuário os-cordões que de-acima para-os-agua o-Yor até até-quando a consumação as-maravilhas');
INSERT INTO verses VALUES (22157, 27, 12, 7, 'e-eu-ouvi a o-homem para-o-vestuário os abdins que de-acima para-aos-agua o-Nil vayyârêm seu-direito e-seu-esquerdo a os-céus e-ele-jurou com-a-vida-de que porque para-o-encontro encontros e-meio e-quando-acabou [יַד־עַם־קֹ֖דֶשׁ] mão-de com santidade [sem-traducao] todo Estas');
INSERT INTO verses VALUES (22158, 27, 12, 8, 'e-eu ouvi e-não [אָבִ֑ין] [וָאֹ֣מְרָ֔ה] Adonai que אַחֲרִית Estas');
INSERT INTO verses VALUES (22159, 27, 12, 9, 'E-disse vai [דָּנִיֵּ֑אל] porque [וַחֲתֻמִ֛ים] [הַדְּבָרִ֖ים] as-palavras até tempo destruição:$');
INSERT INTO verses VALUES (22160, 27, 12, 10, '[יִ֠תְבָּֽרֲרוּ] [וְיִֽתְלַבְּנ֤וּ] [וְיִצָּֽרְפוּ֙] muitos [וְהִרְשִׁ֣יעוּ] רשעים e-não entenderão todo os ímpios e-os-sábios entenderão');
INSERT INTO verses VALUES (22161, 27, 12, 11, 'e-desde-o-tempo foi-removido o-contínuo para-dar abominação desencorajador dias mil duzentos e-nove-dez-verso');
INSERT INTO verses VALUES (22162, 27, 12, 12, 'feliz a-que-espera e-chega para-dias mil três centenas trinta e-cinco');
INSERT INTO verses VALUES (22163, 27, 12, 13, 'e-tu vai ao-fim e-descanse e-parar para-teu-sorteio ao-fim [הַיָּמִֽין]');
INSERT INTO books VALUES (28, 'HOS', 'Oséias', 'AT', 14);
INSERT INTO chapters VALUES (863, 28, 1, 9);
INSERT INTO verses VALUES (22164, 28, 1, 1, 'palavra-de יהוה que ser a Hosea filho-de Beeri בִּימֵ֨י Uzzia ヨタム Acaz Yechzekia reis-de Judá e nos tempos de يروبعام filho-de Yoash rei Israel');
INSERT INTO verses VALUES (22165, 28, 1, 2, 'início falou yhwh no tempo de Hosea E-disse yhwh a Hosea vai toma para-te- esposa de prostituição e filhos zenu''im a-terra zanah yhwh a-terra me''acharei yhwh');
INSERT INTO verses VALUES (22166, 28, 1, 3, 'E-andou E-tomou a gomer filha-de diblaim filho vat''teled- para-ele filho');
INSERT INTO verses VALUES (22167, 28, 1, 4, 'E-disse yhwh a-ele chamou nome-de-ele יִזְרְעֶאל porque ainda me''at u''pakdathi a de''mei yizre''el sobre casa Jeú e far-ei mملکوּת casa Israel');
INSERT INTO verses VALUES (22168, 28, 1, 5, 'e-foi no-dia o-aquele e quebra-ei a arco Israel be-emek Jeová-sara');
INSERT INTO verses VALUES (22169, 28, 1, 6, 'ela concebeu-se ainda e-deu-à-luz fái E-disse a-ele chamou shema-ha- não רֻחָ֑מָה que não e farei ainda e arrependerei-me a casa Israel porque a-eles carregarei para-eles');
INSERT INTO verses VALUES (22170, 28, 1, 7, 'e-a casa יְהוּדָה [וְהֽוֹשַׁעְתִּ֖ים] [בַּיהוָ֣ה] [אֱלֹֽהֵיהֶ֑ם] אֱלֹהֵיהֶם-de-eles e-não [בְּקֶ֤שֶׁת] [וּבְחֶ֙רֶב֙] [וּבְמִלְחָמָ֔ה] [בְּסוּסִ֖ים] [וּבְפָרָשִֽׁים]');
INSERT INTO verses VALUES (22171, 28, 1, 8, '[וַתִּגְמֹ֖ל] a não [וַתַּ֖הַר] e-concebeu filho filho');
INSERT INTO verses VALUES (22172, 28, 1, 9, 'E-disse chamou nome-de-ele não meu-povo que vós não povo-meu e-eu não a-vós para-vocês');
INSERT INTO chapters VALUES (864, 28, 2, 25);
INSERT INTO verses VALUES (22173, 28, 2, 1, 'e-foi מִסְפַּ֤ר filhos-de Israel o-mar o-mar que não יִמַּ֖ד e-não יִסָּפֵ֑ר e-foi a-eles que será dito para-eles a-eles meu-povo vós será dito a-eles filhos-de a viveu');
INSERT INTO verses VALUES (22174, 28, 2, 2, 'e se juntarão filhos-de Judá u''venei- Israel a-eles e-os-colocaram um cabeça um que de dia porque grande dia Jeová-sara');
INSERT INTO verses VALUES (22175, 28, 2, 3, 'אִמְר֥וּ aos vossos irmãos meu-povo e às vossas irmãs misericórdia:');
INSERT INTO verses VALUES (22176, 28, 2, 4, 'multiplicaí em vossas mães multiplicaí porque não não minha esposa não não marido-dela e voltai-vos suas zênúnêhâ di-páfneh ve-ná''afúpêhâ mi-bífên shádehâ');
INSERT INTO verses VALUES (22177, 28, 2, 5, 'para-que-não ápshítênah árúmmâh ve-hítzág''tihâ ké-yôm híwaldáhâ e a colocaste como no deserto e a bebeste como-terra- cobiça e mataste-a no deserto:');
INSERT INTO verses VALUES (22178, 28, 2, 6, 'e-a não não com arrependimento porque filhos-de adúlteros eles');
INSERT INTO verses VALUES (22179, 28, 2, 7, 'que adulterou-se sua mãe assustou-as וראתם que אמרה אלכה depois-de מאהבאי נותני לחמי ומAIMי צמרני ופישתי שמיני e-sequer-me');
INSERT INTO verses VALUES (22180, 28, 2, 8, 'por-isso eis-me aqui- sak a caminho-te por-caminhos e-ao-redor-ei não muro-a e-caminhos-ao-lado-de-la não encontre-se');
INSERT INTO verses VALUES (22181, 28, 2, 9, 'e-perseguição a seus-amores eles תַשִּׂג a-eles וּבִקְשָׁתַם e-não תִמְצָא וְאָמְרָה אֵלְכָה e-voltarei que bom הָֽרִאשׁ֔וֹן porque bom para-mim então מֵעָֽתָּה׃');
INSERT INTO verses VALUES (22182, 28, 2, 10, 'vehi''ă não יָֽדְעָ֔ה que eu dei para-ela הַדָּגָ֖ן וְהַתִּיר֣וֹשׁ וְהַיִּצְחָר וְכֶסֶף הִרְבֵּיתִי para-ela וְזָהָ֖ב fizeram לַבָּעַל׃');
INSERT INTO verses VALUES (22183, 28, 2, 11, 'por-isso אָשׁ֔וּב וְלָקַחְתִּ֤י דְגָנִי֙ בְּעִתּ֔וֹ וְתִירוֹשִׁ֖י בְּמֽוֹעֲד֑וֹ e salvei-a cobre-me e esconda para cobrir a seu pudor');
INSERT INTO verses VALUES (22184, 28, 2, 12, 'e-agora envergonhada a sua vergonha aos-olhos-de de seus amores e-homem não salve imediatamente-me');
INSERT INTO verses VALUES (22185, 28, 2, 13, '[וְהִשְׁבַּתִּי֙] todo [חַגָּ֖הּ] [חָדְשָׁ֣הּ] [וְשַׁבַּתָּ֑הּ] e-tudo e-todo');
INSERT INTO verses VALUES (22186, 28, 2, 14, 'וַהֲשִׁמֹּתִ֗י גַּפְנָהּ֙ וּתְאֵ֣נָתָ֔הּ que אָמְרָ֗ה אֶתְנָ֥ה eles para-mim que נָֽתְנוּ־ para-mim que-me-amem e-vos-colocareis no-área animal-de vivente-de o-campo');
INSERT INTO verses VALUES (22187, 28, 2, 15, 'e-vigilasse sobre-ele-a a dias הַבְּעָלִים֙ que a-eles a-eles e-testemunhou sua-cancioneira e-seu-encantamento e saiu depois-de seus-amores e comigo- שָׁכְחָה oráculo-de yhwh');
INSERT INTO verses VALUES (22188, 28, 2, 16, 'portanto eis eu מְפַתְּתֵֽיהֶ֑ה וְהֹלְכְּתִֽיָּ֑ה הַמִּדְבָּ֑ר וְדִבַּרְתִּֽי a-cri-a-da-la');
INSERT INTO verses VALUES (22189, 28, 2, 17, 'וְנָתַתִּֽי para-ela a כְּרָמְתֵּֽיהֶ֑ה de-lá e-a emeq עָכֹ֖ר para-a-entrada-de תקוה וְעָנְתָּ֤ה שָׁמָֹֽה כּ-ימֵי נְעֹרֶיהָ וּ-כְיוֹם עַלּוֹתָהּ não Egito');
INSERT INTO verses VALUES (22190, 28, 2, 18, 'e-era [בַיּוֹם־הַהוּא֙] o-aquele oráculo-de yhwh [וְלֹֽא־תִקְרְאִי־לִ֥י] [ע֖וֹד] e-não para-mim mais');
INSERT INTO verses VALUES (22191, 28, 2, 19, 'וַהֲסִרֹתִי a nomes-de os-baalins מִפּוּיהָ e-não serão lembrados mais em-seu-nome:');
INSERT INTO verses VALUES (22192, 28, 2, 20, 'e-cortarei a-eles בְּרִית no-dia a-aquela com animal-de o-campo e-com- ave a-terra e-veneno a-terra e-arco e-espada e-guerra que-borrarei de a-terra e-exterminarei לָבֶטַח');
INSERT INTO verses VALUES (22193, 28, 2, 21, 'e-erash''tik para-mim para-sempre e-erash''tik a-mim b-tsedeq u-b-mishpat u-b-chesed u-b-rachamim');
INSERT INTO verses VALUES (22194, 28, 2, 22, 'e-erash''tik para-mim be-emu''ah ve-yada''ta a yhwh');
INSERT INTO verses VALUES (22195, 28, 2, 23, 'e-era em-o-dia no-dia e-e''aneh oráculo-de yhwh Eu responderei a os-céus e-eles Eles responderão a a-terra');
INSERT INTO verses VALUES (22196, 28, 2, 24, 'E-a-terra Tu responderás a o trigo e-a as figs e-a הַיִּצְחָר e-eles Eles responderão את- Jeová-sara');
INSERT INTO verses VALUES (22197, 28, 2, 25, 'e a semearás a-mim na-terra e terá compaixão a não compaixão e diria para-não- meu-povo meu-povo- tu e-ele diga Elohim-meu');
INSERT INTO chapters VALUES (865, 28, 3, 5);
INSERT INTO verses VALUES (22198, 28, 3, 1, 'E-disse yhwh a-mim ainda vai amar- mulher amor- mau e-desejo- yhwh yhwh a filhos-de Israel e-eles face a Elohim outros e-os-que-amam- seus- uvas-');
INSERT INTO verses VALUES (22199, 28, 3, 2, 'e-a-cultivei- a-mim בַּחֲמִשָּׁ֥ה dez prata וְחֹ֥מֶר seoras וְלֵ֥תֶךְ cevada');
INSERT INTO verses VALUES (22200, 28, 3, 3, 'e-disse a-ela dias רַבִּים תֵּ֣שְׁבִי para-mim não תִזְנִ֔י e-não תִֽהְיִ֖י para-homem e-também eu me-');
INSERT INTO verses VALUES (22201, 28, 3, 4, 'que dias muitos se-já-sentarão filhos-de Israel não rei e-não שָׂ֔ר e-não-há sacrifício-masculino-singular e-não ma-ts-e-vah-a e-não-há éfode וּתְרָפִֽים׃');
INSERT INTO verses VALUES (22202, 28, 3, 5, 'אַחַ֗ר voltavam filhos-de Israel וּבִקְשׁוּ֙ a yhwh Elohehem e-a Davi Malkeim Ufachdu a yhwh e-a Tuvu mar os dias');
INSERT INTO chapters VALUES (866, 28, 4, 19);
INSERT INTO verses VALUES (22203, 28, 4, 1, 'ouvi palavra-de yhwh filhos-de que porque Riv para-יהוה a-terra que a-terra porque não-há verdade Ve''ein- Chesed e-nao-ha Da''at Elohim na-terra');
INSERT INTO verses VALUES (22204, 28, 4, 2, 'Alah Ve''kachesh e matar e roubar e furtar transgrediram e sangue em sangue atingiram:');
INSERT INTO verses VALUES (22205, 28, 4, 3, 'sobre assim, se entristecerá a-terra e será ferido todo habitante-de em-ela בהחיות e-sobre-as-aves-de e-em-ave os-céus o-mar peixes-de o-mar יהאספו׃');
INSERT INTO verses VALUES (22206, 28, 4, 4, 'somente homem a iarab e-a יוכח homem ואMASKCAMכָא כאמריבבי sacerdote');
INSERT INTO verses VALUES (22207, 28, 4, 5, '[וְכָשַׁלְתָּ֣] o-dia [וְכָשַׁ֧ל] também profeta noite noite [אִמֶּֽךָ]');
INSERT INTO verses VALUES (22208, 28, 4, 6, '[נִדְמ֥וּ] povo-meu [מִבְּלִ֣י] [הַדָּ֑עַת] porque o-conhecimento [מָאַ֗סְתָּ] [וְאֶמְאָֽסְאךָ֙] [מִכַּהֵ֣ן] [לִ֔י] para-mim [תּוֹרַ֣ת] lei-de Elohim-teu [בָּנֶ֖יךָ] [גַּם־אָֽנִי] também');
INSERT INTO verses VALUES (22209, 28, 4, 7, '[כְּרֻבָּ֖ם] assim [חָֽטְאוּ־לִ֑י] para-mim [בְּקָל֥וֹן] [אָמִֽיר]');
INSERT INTO verses VALUES (22210, 28, 4, 8, 'חַטָּאת povo-meu יֹאכְלוּ e-a seu pecado יִשְׂאוּ a sua alma:');
INSERT INTO verses VALUES (22211, 28, 4, 9, 'e-acontecerá כַּעֲם כַּכֹּהֵן וּפָקַדְתִּי sobre-ele דְּרָכָ֔יו e seus alçamentos eu trarei a-ele');
INSERT INTO verses VALUES (22212, 28, 4, 10, 'e comerão e-não e se fartarão e se fartaram e-não e se fartarão porque a yhwh e abandonaram para guardar');
INSERT INTO verses VALUES (22213, 28, 4, 11, 'adúlteria e-vinho וְתִיר֖וֹשׁ e tomará coração');
INSERT INTO verses VALUES (22214, 28, 4, 12, 'meu-povo no tronco dele perguntará e no seu cajado dirá a-ele que espírito sementes atrairá e se deitaram debaixo-de אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (22215, 28, 4, 13, 'sobre cabeças-de as montanhas imolá-los-ão e-sobre debaixo farão cheirar em-lugar-de álamo que bom porque bom sombra dela sobre sim TZINENAH BENOTAYCHEM V''KALOTEICHEM TANAFNA');
INSERT INTO verses VALUES (22216, 28, 4, 14, 'não EFQUOD que BENOTAYCHEM porque que e-sobre KALOTEICHEM porque TANAFNA porque eles: com HZONOT YEFAREDU e-com- santificarão sacrifiquem e povo não entenderá se exaltará');
INSERT INTO verses VALUES (22217, 28, 4, 15, 'se tu tu Israel a ele-será-culpado Judá e-a virão הַגִּלְגָּ֗ל e-a subirão casa iniquidade e-a jurarão vive yhwh');
INSERT INTO verses VALUES (22218, 28, 4, 16, 'que para expiar a rebelião סָרַר Israel agora יִרְעֵ֣ם yhwh כְּכֶ֖בֶשׂ בַּמֶּרְחָֽב׃');
INSERT INTO verses VALUES (22219, 28, 4, 17, '[חֲב֧וּר] [עֲצַבִּ֛ים] [אֶפְרָ֖יִם] [הַֽנַּֽח־לֽוֹ] a-ele');
INSERT INTO verses VALUES (22220, 28, 4, 18, 'apartou סָבְאָ֑ם הַזְנֵ֣ה הִזְנ֔וּ Amem Elevem Calão Sua escudo:');
INSERT INTO verses VALUES (22221, 28, 4, 19, 'Agridem espírito a-ela Com suas asas E vergonhem-se De seus altares');
INSERT INTO chapters VALUES (867, 28, 5, 15);
INSERT INTO verses VALUES (22222, 28, 5, 1, 'ouvi Isto os-sacerdotes E ouvirem casa Israel וּבֵ֤ית o rei הַאֲזִ֔ינוּ que a-vós הַמִּשְׁפּ֑ט porque פַח֙ הֱיִיתֶ֣ם לְמִצְפּ֔ה וְרֶ֖שֶׁת פְּרוּשָׂ֥ה sobre Tábor:');
INSERT INTO verses VALUES (22223, 28, 5, 2, 'וְשַׁחֲטָ֥ה שֵׂטִ֖ים profundem-se e-eu múser para-todos:');
INSERT INTO verses VALUES (22224, 28, 5, 3, 'eu eu-sei Efraim e-israel não foi-avergonhado que porque agora tentaste Efraim está-purificado Israel');
INSERT INTO verses VALUES (22225, 28, 5, 4, 'não dêem seus-pecadores para-retornar a que espírito espírito adúlteros entre-eles não yhwh não não');
INSERT INTO verses VALUES (22226, 28, 5, 5, '[וְעָנָ֥ה] [גְאֽוֹן־יִשְׂרָאֵ֖ל] Israel [וְיִשְׂרָאֵ֣ל] [וְאֶפְרַ֗יִם] [יִכָּֽשְׁלוּ֙] [בַּעֲוֺנָ֔ם] [כָּשַׁ֥ל] [גַּם־יְהוּדָ֖ה] também יְהוּדָה com-eles');
INSERT INTO verses VALUES (22227, 28, 5, 6, '[בְּצֹאנָ֣ם] [וּבִבְקָרָ֗ם] [יֵֽלְכ֛וּ] para-buscar a yhwh e-não [חָלַ֖ץ] [מֵהֶֽם] de-eles');
INSERT INTO verses VALUES (22228, 28, 5, 7, '[בַּיהוָ֣ה] [בָּגָ֔דוּ] porque [זָרִ֖ים] [יָלָ֑דוּ] [עַתָּ֛ה] [יֹאכְלֵ֥ם] [חֹ֖דֶשׁ] novo a');
INSERT INTO verses VALUES (22229, 28, 5, 8, 'תִּקְע֤וּ שופר bagibbah חצוצרה ברמה הריעו casa iniquidade אחריכא בנימין׃');
INSERT INTO verses VALUES (22230, 28, 5, 9, 'אֶפְרַיִם לשם sera em-dia תוכחה בְּשִׁבְטֵי֙ Israel הודיתי נאמנה׃');
INSERT INTO verses VALUES (22231, 28, 5, 10, 'foram príncipes-de Judá [כְּמַסִּיגֵ֖י] [גְּב֑וּל] [עֲלֵיהֶ֕ם] [אֶשְׁפּ֥וֹךְ] [כַּמַּ֖יִם] [עֶבְרָתִֽי]');
INSERT INTO verses VALUES (22232, 28, 5, 11, '[עָשׁ֥וּק] Efraim [רְצ֣וּץ] juízo que [הוֹאִ֔יל] andar depois-de');
INSERT INTO verses VALUES (22233, 28, 5, 12, 'e-eu כָעָ֖שׁ a Éfraim וְכָרָקָ֖ב segundo-casa-de Judá');
INSERT INTO verses VALUES (22234, 28, 5, 13, 'E-viu [אֶפְרַ֜יִם] a [וִֽיהוּדָה֙] [אֶת־מְזֹר֔וֹ] a [אֶפְרַ֙יִם֙] E-andou אֶפְרַיִם a Assur e-enviou não rei [לִרְפֹּ֣א] a-vós não [מִכֶּ֖ם] [מָזֽוֹר] e-não');
INSERT INTO verses VALUES (22235, 28, 5, 14, 'que eu como-aleluia para-Efraim e-cá-capim para-casa-de Judá eu eu eu-arrastarei e-eu-vou carregarei e-não-há que salva');
INSERT INTO verses VALUES (22236, 28, 5, 15, 'eu-vou eu-voltarei a até até que e-eles-acharão e-pesquisem a-eles בַּצַּ֥ר a-eles יְשַׁחֲרֻֽנְנִי׃');
INSERT INTO chapters VALUES (868, 28, 6, 11);
INSERT INTO verses VALUES (22237, 28, 6, 1, '[לְכוּ֙] [וְנָשׁ֣וּבָה] a que ele ele [וְיִרְפָּאֵ֑נוּ] [יַ֖ךְ] [וְיַחְבְּשֵֽׁנוּ]');
INSERT INTO verses VALUES (22238, 28, 6, 2, 'יְחַיֵּ֖נוּ מִיֹּמָ֑יִם no-dia o-terceiro יְקִמֵ֖נוּ e viveremos diante-de-ele');
INSERT INTO verses VALUES (22239, 28, 6, 3, 'e conheceremos seremos perseguidas para-conhecer a yhwh ao amanhecer firme de sua saída e virá como um falso para-nós como um enganador que ensina terra');
INSERT INTO verses VALUES (22240, 28, 6, 4, 'que farei para-ti Efraim que farei- para ti Judá e-vossos-chesdes como-nuvem- manhã e-com-chuva que-fazem andou');
INSERT INTO verses VALUES (22241, 28, 6, 5, 'sobre sim eu-esperei nos-prophetas e-vos-aceitastes-matar be-amrei- luz e-vossas-leis luz saira');
INSERT INTO verses VALUES (22242, 28, 6, 6, 'que bondade eu-queria e-não e-sacrifiquei e conhecimento Elohim de origens');
INSERT INTO verses VALUES (22243, 28, 6, 7, 'e elas como homens abru aliança nome enganaram-se בִֽי׃');
INSERT INTO verses VALUES (22244, 28, 6, 8, 'Giláad Cidade seus-trabalhos iniquidade de Aquabe por sangue');
INSERT INTO verses VALUES (22245, 28, 6, 9, 'e sábios homem גדודים חבר ko''hanim o-caminho-de ירצחו- que porque זִמָּ֖ה fizeram');
INSERT INTO verses VALUES (22246, 28, 6, 10, 'em casa de Israel vi nome זנת para-Efraim נטמא Israel');
INSERT INTO verses VALUES (22247, 28, 6, 11, 'também יהודה beber para-ti para-ti בשובי שבות povo-meu');
INSERT INTO chapters VALUES (869, 28, 7, 16);
INSERT INTO verses VALUES (22248, 28, 7, 1, 'kräפאי ליישרא엘 e será revelado pecado אֶפְרַיִם e maldades Samaria que fizeram falsidade e ladrão vira despojou guedôd no-exterior');
INSERT INTO verses VALUES (22249, 28, 7, 2, 'e com יֹֽאמְרוּ֙ no coração deles todo suas maldades זָכַרְתִּי agora diante מַעֲלְלֵיהֶם diante-de face-de eram');
INSERT INTO verses VALUES (22250, 28, 7, 3, '[בְּרָעָתָ֖ם] [יְשַׂמְּחוּ־מֶ֑לֶךְ] rei [שָׂרִֽים]');
INSERT INTO verses VALUES (22251, 28, 7, 4, 'todos-os מְנַאֲפִים כְּמוֹ תַּנּוּר בּוֹעֵרָה de-a-ofe isboth me-ur milush batsok até chumtsato');
INSERT INTO verses VALUES (22252, 28, 7, 5, 'dia malkeinu hechalu sarim chamath מִיַּ֑יִן מָשַׁ֥ךְ sua-mão a לֹצְצִֽים׃');
INSERT INTO verses VALUES (22253, 28, 7, 6, 'porque [כַתַּנּ֛וּר] [לִבָּ֖ם] [בְּאָרְבָּ֑ם] [כָּל־הַלַּ֙יְלָה֙] todo a-noite manhã ele manhã ele [לֶהָבָֽה]');
INSERT INTO verses VALUES (22254, 28, 7, 7, 'kullem יֵחַ֙מּוּ֙ כּתָנֻר va''aklu a שֹופְטֵיהֶם todo מַלְכֵיהֶם נָפֻלוּ não-há chamou neles para-mim');
INSERT INTO verses VALUES (22255, 28, 7, 8, '[אֶפְרַ֕יִם] [בָּעַמִּ֖ים] ele [יִתְבּוֹלָ֑ל] Efraim ser [עֻגָ֖ה] [בְּלִ֥י] [הֲפוּכָֽה]');
INSERT INTO verses VALUES (22256, 28, 7, 9, '[אָכְל֤וּ] [זָרִים֙] [כֹּח֔וֹ] e-ele não conheceu também [זָ֣רְקָה] [בּ֔וֹ] nele não não conheceu');
INSERT INTO verses VALUES (22257, 28, 7, 10, '[וְעָנָ֥ה] [גְאֽוֹן־יִשְׂרָאֵ֖ל] Israel [וְלֹֽא־שָׁ֙בוּ֙] e-não [אֱלֹֽהֵיהֶ֔ם] a yhwh [בְּכָל־זֹֽאת] e-não em-todo');
INSERT INTO verses VALUES (22258, 28, 7, 11, 'e-houve Efraim קְיווֹנָה פֹּתַה não-há coração Mitzraim קָרְאוּ אַשּׁוּר andarem;');
INSERT INTO verses VALUES (22259, 28, 7, 12, 'como-que [יֵלֵ֗כוּ] [אֶפְר֤וֹשׂ] sobre-eles [רִשְׁתִּ֔י] [כְּע֥וֹף] os-céus [אֽוֹרִידֵ֑ם] [אַיְסִרֵ֕ם] [כְּשֵׁ֖מַע] [לַעֲדָתָֽם׃]');
INSERT INTO verses VALUES (22260, 28, 7, 13, '[א֤וֹי] a-eles porque [מִמֶּ֔נִּי] mais-que-a-mim a-eles a-eles porque [וְאָנֹכִ֣י] [אֶפְדֵּ֔ם] e-eu [דִּבְּר֥וּ] [עָלַ֖י] [כְּזָבִֽים]');
INSERT INTO verses VALUES (22261, 28, 7, 14, 'e-não זָעֲק֤וּ a-mim que porque יְיֵלִ֖ילוּ sobre de-suas-camas sobre grão e-vinho serão-dragados serão-maltratados בִֽי׃');
INSERT INTO verses VALUES (22262, 28, 7, 15, 'e-eu eu-serei-maltratado eu-os-fortaleci suas-mãos e-para-mim pensarão-em mau');
INSERT INTO verses VALUES (22263, 28, 7, 16, '[יָשׁ֣וּבוּ] não não foram [הָיוּ֙] [כְּקֶ֣שֶׁת] [רְמִיָּ֔ה] [יִפְּל֥וּ] [בַחֶ֛רֶב] [שָׂרֵיהֶ֖ם] [מִזַּ֣עַם] [לְשׁוֹנָ֑ם] [ז֥וֹ] em-terra-de Egito');
INSERT INTO chapters VALUES (870, 28, 8, 14);
INSERT INTO verses VALUES (22264, 28, 8, 1, 'a [שֹׁפָ֔ר] [כַּנֶּ֖שֶׁר] [עַל־בֵּ֣ית] yhwh casa yhwh porque [וְעַל־תּוֹרָתִ֖י] [פָּשָֽׁעוּ] e-sobre');
INSERT INTO verses VALUES (22265, 28, 8, 2, 'para-mim [יִזְעָ֑קוּ] [אֱלֹהַ֥י] [יְֽדַעֲנ֖וּךָ] Israel');
INSERT INTO verses VALUES (22266, 28, 8, 3, '[זָנַ֥ח] Israel bom [אוֹיֵ֖ב] [יִרְדְּֽפוֹ]');
INSERT INTO verses VALUES (22267, 28, 8, 4, 'eles הִמְלַכְּתֶּם e-não mais-que-a-mim הֵשִׁירוּ e-não יָדַעְתִּי כַּסְפָּם וּזְהָבָם asau a-eles עֲצַבֵּי para-que יִכָרֶת׃');
INSERT INTO verses VALUES (22268, 28, 8, 5, 'זָנַח tua-egle Samaria chora meu-apo neles até não não poderão limpo:');
INSERT INTO verses VALUES (22269, 28, 8, 6, 'que de-islã e-ele artífice fez-o e-não Elohim ele porque será será עֵ֖גֶל Samaria');
INSERT INTO verses VALUES (22270, 28, 8, 7, 'que espírito irázeu vesufata iráktsoro qama não há para-ele tsema bli fará- qema oula yaashe זָרִ֖ים yiblauhu');
INSERT INTO verses VALUES (22271, 28, 8, 8, 'ser engolido Israel agora foram nos gentios כִּכְלִ֖י não há desejo em-ele');
INSERT INTO verses VALUES (22272, 28, 8, 9, 'porque eles עָל֣וּ Assur gazela a-ele para-ele Efraim serem consumidos amor');
INSERT INTO verses VALUES (22273, 28, 8, 10, 'também porque seriam dados nos gentios agora אֲקַבְּצֵ֑ם e começaram a mê''ât de saída rei שַׂרִים׃');
INSERT INTO verses VALUES (22274, 28, 8, 11, 'porque [אֶפְרַ֛יִם] Efraim [לַחֲטֹ֑א] [הָיוּ־ל֥וֹ] eram- para-ele');
INSERT INTO verses VALUES (22275, 28, 8, 12, 'a-ele [*רבו] como [תּֽוֹרָתִ֑י] [כְּמוֹ־זָ֖ר]');
INSERT INTO verses VALUES (22276, 28, 8, 13, 'sacrificios-de הַבְהָבַי יִזְבְּחוּ בָּשָׂר וַיֹּאכְלוּ yhwh não רָצוּם agora יִזְכֹּר עֲוֹנוֹם וְיִפְקֹד חַטֹּאֵיהֶם eles Mitzraim יָשׁוּבוּ׃');
INSERT INTO verses VALUES (22277, 28, 8, 14, 'וַיִּשְׂכַּח Israel a E-edificou e-construiu הֵיכָלוֹת וִֽיהוּדָ֕ה הִרְבָּ֖ה cidades בְּצֻר֑וֹת וְשִׁלַּחְתִּי־ fogo בְּעָרָ֔יו e-consumiu אַרְמְנֹתֶֽיהָ׃');
INSERT INTO chapters VALUES (871, 28, 9, 17);
INSERT INTO verses VALUES (22278, 28, 9, 1, 'a [יִשְׂרָאֵ֤ל] [׀] a [כָּֽעַמִּ֔ים] que porque de-cima-de de-sobre teu-Elohim [אֶתְנָ֔ן] sobre sobre todo');
INSERT INTO verses VALUES (22279, 28, 9, 2, 'eira [וָיֶ֖קֶב] não [יִרְעֵ֑ם] [וְתִיר֖וֹשׁ] [יְכַ֥חֶשׁ] nela');
INSERT INTO verses VALUES (22280, 28, 9, 3, 'não יֵשְׁב֖וּ em-terra-de yhwh וְשָׁ֤ב אֶפְרַיִם Egito וּבְאַשּׁ֖וּר impuro יֹאכֵֽלוּ׃');
INSERT INTO verses VALUES (22281, 28, 9, 4, 'não [לַיהוָ֥ה] [׀] [יַיִן֮] e-não [יֶֽעֶרְבוּ־לוֹ֒] para-ele [כְּלֶ֤חֶם] [אוֹנִים֙] a-eles a-eles todo [כִּֽי־לַחְמָ֣ם] [לְנַפְשָׁ֔ם] não [יָב֖וֹא] [בֵּ֥ית] yhwh casa yhwh');
INSERT INTO verses VALUES (22282, 28, 9, 5, 'que [לְי֣וֹם] para-o-dia de-encontro [חַג־יְהוָֽה] yhwh');
INSERT INTO verses VALUES (22283, 28, 9, 6, 'porque eis andaram [מִצְרַ֥יִם] [תְּקַבְּצֵ֖ם] [מֹ֣ף] [תְּקַבְּרֵ֑ם] [מַחְמַ֣ד] [לְכַסְפָּ֗ם] [קִמּוֹשׂ֙] [יִֽירָשֵׁ֔ם] [ח֖וֹחַ] [בְּאָהֳלֵיהֶֽם]');
INSERT INTO verses VALUES (22284, 28, 9, 7, '[בָּ֣אוּ] dias-de dias-de vieram dias-de dias-de [הַשִׁלֻּ֔ם] Israel [יִשְׂרָאֵ֑ל] o-profeta [הַנָּבִ֗יא] homem [אִ֣ישׁ] sobre sobre [רֹ֣ב] [עֲוֺנְךָ֔] [וְרַבָּ֖ה]');
INSERT INTO verses VALUES (22285, 28, 9, 8, '[צֹפֶ֥ה] Efraim com [נָבִ֞יא] profeta [יָקוֹשׁ֙] [עַל־כָּל־דְּרָכָ֔יו] sobre todo [אֱלֹהָֽיו]');
INSERT INTO verses VALUES (22286, 28, 9, 9, '[הֶעְמִֽיקוּ־שִׁחֵ֖תוּ] [כִּימֵ֣י] [הַגִּבְעָ֑ה] [יִזְכּ֣וֹר] [עֲוֺנָ֔ם] iniquidade-deles [חַטֹּאותָֽם׃]');
INSERT INTO verses VALUES (22287, 28, 9, 10, 'כַּעֲנָבִ֣ים no-deserto מָצָ֙אתִי֙ Israel כְּבִכּוּרָ֤ה בִתְאֵנָה֙ בְּרֵ֣אשִׁיתָ֔הּ vi os vossos pais eles vieram senhor de Peor e se uniram a vergonha e-foram escândalos como eles');
INSERT INTO verses VALUES (22288, 28, 9, 11, 'Efraim como um pássaro vagarosamente voará כבודם מלידה ובטן והריון׃');
INSERT INTO verses VALUES (22289, 28, 9, 12, 'que se [אֶת־בְּנֵיהֶ֔ם] a [מֵֽאָדָ֑ם] [כִּֽי־גַם־א֥וֹי] a-eles porque também');
INSERT INTO verses VALUES (22290, 28, 9, 13, 'Efraim conforme- Vi לצור שתולה בְנָוֶ֑ה וְאֶפְרַ֕יִם para-sair a הֹרֵ֖ג banayo');
INSERT INTO verses VALUES (22291, 28, 9, 14, '[תֵּן־לָהֶ֥ם] yhwh yhwh que [רֶ֣חֶם] [מַשְׁכִּ֔יל] para-eles [צֹמְקִֽים]');
INSERT INTO verses VALUES (22292, 28, 9, 15, 'todo suas-mal-criações em-golgolá porque sobre seus-ma-ló-cios sobre mau suas-mal-criações não expulsaremos-lhes não José suas-amor-tes todo seus-senhe-res ma-ló-cios');
INSERT INTO verses VALUES (22293, 28, 9, 16, 'foi-moído Efraim שָׁרְשָׁמָּה יָבֵ֖שׁ fruto יַעֲשׂוּנֵהֶם também que יֵלְדוּנֵהֶם וְהֵמַתְּיָה מַחֲמַדְיָה בִּתְנוֹנֵיהֶם׃');
INSERT INTO verses VALUES (22294, 28, 9, 17, 'יִמְאַסְּסֵהוּ meu-Elohim que não ouviram a-ele וְיִהְיוּ נֹדְדוּ בָּגוֹיִם׃');
INSERT INTO chapters VALUES (872, 28, 10, 15);
INSERT INTO verses VALUES (22295, 28, 10, 1, '[גֶּ֤פֶן] [בּוֹקֵק֙] Israel fruto [יְשַׁוֶּה־לּ֑וֹ] para-ele [לְפִרְי֗וֹ] [הִרְבָּה֙] [לַֽמִּזְבְּח֔וֹת] [כְּט֣וֹב] [לְאַרְצ֔וֹ] [הֵיטִ֖יבוּ] [מַצֵּבֽוֹת]');
INSERT INTO verses VALUES (22296, 28, 10, 2, '[חָלַ֥ק] [לִבָּ֖ם] agora [יֶאְשָׁ֑מוּ] ele [יַעֲרֹ֣ף] [מִזְבְּחוֹתָ֔ם] [יְשֹׁדֵ֖ד] [מַצֵּבוֹתָֽם]');
INSERT INTO verses VALUES (22297, 28, 10, 3, 'que agora dirão não-há rei para-nós que não [יָרֵ֙אנוּ֙] a yhwh [מַה־יַּֽעֲשֶׂה־לָּֽנוּ]');
INSERT INTO verses VALUES (22298, 28, 10, 4, 'falaram דְבָרִים אלות שוא כרות aliança ופרחת כראשה משפט sobre תלמי Shaddai');
INSERT INTO verses VALUES (22299, 28, 10, 5, '[לְעֶגְלוֹת֙] casa [אָ֔וֶן] [יָג֖וּרוּ] [שְׁכַ֣ן] [שֹֽׁמְר֑וֹן] porque [עָלָ֜יו] sobre-ele povo-dele [עָלָ֣יו] sobre-ele [עַל־כְּבוֹד֖וֹ] sobre nós porque');
INSERT INTO verses VALUES (22300, 28, 10, 6, 'também ele [יוּבָ֔ל] [מִנְחָ֖ה] oferta como-rei [בָּשְׁנָה֙] [אֶפְרַ֣יִם] [יִקָּ֔ח] [וְיֵב֥וֹשׁ] [יִשְׂרָאֵ֖ל] Israel');
INSERT INTO verses VALUES (22301, 28, 10, 7, 'נִדְמֶה שֹׁמְר֖וֹן de-a-sua-majestade כְּקֶצֶף sobre face-de águas');
INSERT INTO verses VALUES (22302, 28, 10, 8, 'וְנִשְׁמְדוּ בָּמוֹת אוֹן חַטָּאת֙ Israel espinho e-cardos subia sobre מִזְבּוֹחוֹתָ֑ם וְאָמְרוּ em-os como-s-eis e-em-g-ba-ou-t caí-r-se sobre-nós');
INSERT INTO verses VALUES (22303, 28, 10, 9, 'desde-dias-de הַגִּבְעָ֔ה peço-lo Israel nome está-ram não atingi-vos em-g-ba-ú-a guerra sobre filhos-de sobre-lhe:');
INSERT INTO verses VALUES (22304, 28, 10, 10, 'em-a-vu-ti וְאֶסֳּרֵ֑ם וְאֻסְּפ֤וּ sobre-eles nations בְּאָסְרָ֖ם לִשְׁתֵּ֥י');
INSERT INTO verses VALUES (22305, 28, 10, 11, '[וְאֶפְרַ֜יִם] [עֶגְלָ֤ה] [מְלֻמָּדָה֙] [אֹהַ֣בְתִּי] [לָד֔וּשׁ] e-eu [עָבַ֔רְתִּי] sobre bom [אַרְכִּ֤יב] [אֶפְרַ֙יִם֙] אֶפְרַיִם [יְהוּדָ֔ה] Judá [יַעֲקֹֽב] Jacó');
INSERT INTO verses VALUES (22306, 28, 10, 12, '[זִרְע֨וּ] a-vós [לִצְדָקָה֙] [קִצְר֣וּ] à-boca-de bondade a-vós a-vós [וְעֵת֙] [לִדְר֣וֹשׁ] [אֶת־יְהוָ֔ה] a yhwh até a-vós');
INSERT INTO verses VALUES (22307, 28, 10, 13, '[חֲרַשְׁתֶּם־רֶ֛שַׁע] [עַוְלָ֥תָה] [קְצַרְתֶּ֖ם] [אֲכַלְתֶּ֣ם] [פְּרִי־כָ֑חַשׁ] [כִּֽי־בָטַ֥חְתָּ] [בְדַרְכְּךָ֖] porque [גִּבּוֹרֶֽיךָ]');
INSERT INTO verses VALUES (22308, 28, 10, 14, 'e levantou-se שָׁאוֹן em teu povo e-todo de tua fortaleza jushad căshod Shalman casa Arvel em-dia-de mãe mãe sobre que Rutashah');
INSERT INTO verses VALUES (22309, 28, 10, 15, 'assim fez a-vós casa-de de-diante-de de-face-de mau רָעַתְכֶם בַּשַּׁ֕חַר נִדְמֹ֥ה נִדְמָ֖ה rei Israel');
INSERT INTO chapters VALUES (873, 28, 11, 11);
INSERT INTO verses VALUES (22310, 28, 11, 1, 'que jovem Israel וָאֹהֲבֵ֑הוּ וּמִמִּצְרַ֖יִם chamei para-meu-filho');
INSERT INTO verses VALUES (22311, 28, 11, 2, 'קָרְא֖וּ a-eles assim caminharam de-diante-deles לַבְּעָלִ֣ים יְזַבֵּ֔חוּ וְלַפְּסִלִ֖ים יְקַטֵּרֽוּן׃');
INSERT INTO verses VALUES (22312, 28, 11, 3, '[וְאָנֹכִ֤י] [תִרְגַּ֙לְתִּי֙] [לְאֶפְרַ֔יִם] [קָחָ֖ם] sobre [וְלֹ֥א] e-não que porque');
INSERT INTO verses VALUES (22313, 28, 11, 4, 'בְּחַבְלֵ֨י homem אֶמְשְׁךֵם֙ בַּעֲבֹת֣וֹת אַהֲבָ֔ה eu fui a-eles como levantando-se sobre sobre para a sua vida e atá a-ele eu come');
INSERT INTO verses VALUES (22314, 28, 11, 5, 'não retornara a terra Egito ele ele que porque recusaram para voltar;—');
INSERT INTO verses VALUES (22315, 28, 11, 6, 'ela se tornou espada em seus dias e consumiu pelos seus dentes e come de-suas-counsel');
INSERT INTO verses VALUES (22316, 28, 11, 7, 've''ami hanging for-my-return e-a sobre he-shall-be-called não não they-shall-be-raised');
INSERT INTO verses VALUES (22317, 28, 11, 8, 'how I-give-you Efrayim my-compassion Israel como I-give-you like-earth אֲשַׁמְּךָ [כִּצְבֹאיִ֑ם] נֵחֲפוּ sobre-mim coração-meu יַחַד נִכְרָרוּ נִחֻמֵּיכֶם׃');
INSERT INTO verses VALUES (22318, 28, 11, 9, 'não farei חֲרֹון minha ira não אָשַׁב para-destruir Efraim que El eu e-não homem בְּקִרְבֶּךָ֣ santo e-não chegue בְּעִֽיר׃');
INSERT INTO verses VALUES (22319, 28, 11, 10, 'atrás-de yhwh irao כְּאַרְיֵ֣ה יִשְׁאָ֑ג porque ele יִשְׁאַ֔ג filhos filhos águas');
INSERT INTO verses VALUES (22320, 28, 11, 11, '[יֶחֶרְד֤וּ] [כְצִפּוֹר֙] do-Egito [וּכְיוֹנָ֖ה] da-terra Assur [וְהוֹשַׁבְתִּ֥ים] sobre [נְאֻם־יְהוָֽה׃] oráculo-de yhwh');
INSERT INTO chapters VALUES (874, 28, 12, 15);
INSERT INTO verses VALUES (22321, 28, 12, 1, '[סְבָבֻ֤נִי] [בְכַ֙חַשׁ֙] Efraim [וּבְמִרְמָ֖ה] casa Israel [וִֽיהוּדָ֗ה] até [רָד֙] com El e-com-');
INSERT INTO verses VALUES (22322, 28, 12, 2, 'אֶפְרַ֜יִם ⚗ה espírito וְרֹדֵף קָדִים todo הַיּוֹם כָּזָב וָשׁוֹד יַרְבּה וּבְרִית com אַשׁוּר יִכְרֹטוּ e-óleo para-moçarétes jubal:');
INSERT INTO verses VALUES (22323, 28, 12, 3, 'e-dispute a-yhwh com Judá e-contar sobre Jacó segundo-seus-caminhos a-ele a-ele a-ele');
INSERT INTO verses VALUES (22324, 28, 12, 4, 'no-ventre calcanhar a irmão-dele e-em-seu-espírito Sarah a Elohim');
INSERT INTO verses VALUES (22325, 28, 12, 5, 'e-sustentou a מַלְאָךְ e foi feito chorou e rogou- a-ele casa-de El encontrá-lo- e-ali que com-nosso:');
INSERT INTO verses VALUES (22326, 28, 12, 6, 'e-יהוה Elohim-de as hostes yhwh sua memória');
INSERT INTO verses VALUES (22327, 28, 12, 7, 'e-tu em tua deidade volver-te- misericórdia e-julgamento guarda-te esperai a teu-Elohim sempre');
INSERT INTO verses VALUES (22328, 28, 12, 8, 'cananéu em-suas-mãos pesadas enganosidade para esmagar amou');
INSERT INTO verses VALUES (22329, 28, 12, 9, 'E-disse Efraim porém eu cortei encontrei enganador a-mim todo não não היה מצאו- a-mim עון que pecado;');
INSERT INTO verses VALUES (22330, 28, 12, 10, '[וְאָנֹכִ֛י] yhwh teu-Elohim da-terra Egito até [אוֹשִֽׁיבְךָ֥] [בָ[t]אֳהָלִ֖ים] encontro');
INSERT INTO verses VALUES (22331, 28, 12, 11, 'וְדִבַּ֙רְתִּי֙ sobre os-profetas e-eu חָז֣וֹן הִרְבֵּ֑יתִי e-na-mão os-profetas אֲדַמֶּֽה׃');
INSERT INTO verses VALUES (22332, 28, 12, 12, 'se [אָ֙וֶן֙] [אַךְ־שָׁ֣וְא] somente [בַּגִּלְגָּ֖ל] [שְׁוָרִ֣ים] [זִבֵּ֑חוּ] também [מִזְבְּחוֹתָם֙] também sobre [תַּלְמֵ֥י] sobre Shaddai');
INSERT INTO verses VALUES (22333, 28, 12, 13, 'וַיִּבְרַ֥ח Jacó campo- Arã וַיַּעֲבֹ֤ד Israel בְּאִשָּׁ֔ה בְּאִשָּׁ֔ה שָׁמַר׃');
INSERT INTO verses VALUES (22334, 28, 12, 14, '[וּבְנָבִ֕יא] [הֶעֱלָ֧ה] yhwh a Israel de-Egito [נִשְׁמָֽר]');
INSERT INTO verses VALUES (22335, 28, 12, 15, 'הִכְעִ֥יס Efraim תַּמְרֻרִים וְדָמָיו֙ sobre-ele יִטּ֔וֹשׁ וְחֶ֨רְפָּת֔וֹ residirá a-ele אֲדֹנָֽיו׃');
INSERT INTO chapters VALUES (875, 28, 13, 15);
INSERT INTO verses VALUES (22336, 28, 13, 1, '[כְּדַבֵּ֤ר] אֶפְרַיִם [רְתֵ֔ת] [נָשָׂ֥א] ele em-Israel [וַיֶּאְשַׁ֥ם] [בַּבַּ֖עַל] E-morreu');
INSERT INTO verses VALUES (22337, 28, 13, 2, 'e-agora יוֹסִ֣פוּ לַחֲטֹ֗א וַיַּעְשׂ֣וּ a-elas a-eles מִכַּסְפָּ֤ם כִּתְבוּנָם֙ עצבים obra-de חרשים todas para-eles a-eles eles זובחי homem homem ישקוון׃');
INSERT INTO verses VALUES (22338, 28, 13, 3, 'portanto [יִֽהְיוּ֙] [כַּעֲנַן־בֹּ֔קֶר] manhã [מַשְׁכִּ֣ים] [הֹלֵ֑ךְ] andou [יְסֹעֵ֣ר] [מִגֹּ֔רֶן] [וּכְעָשָׁ֖ן] [מֵאֲרֻבָּֽה]');
INSERT INTO verses VALUES (22339, 28, 13, 4, '[וְאָנֹכִ֛י] yhwh teu-Elohim da-terra Egito [וֵאלֹהִ֤ים] [זֽוּלָתִי֙] não [תֵדָ֔ע] [וּמוֹשִׁ֥יעַ] não-havia [בִּלְתִּֽי]');
INSERT INTO verses VALUES (22340, 28, 13, 5, 'eu [יְדַעְתִּ֖יךָ] no-deserto em-terra-de [תַּלְאֻבֽוֹת]');
INSERT INTO verses VALUES (22341, 28, 13, 6, '[כְּמַרְעִיתָם֙] [וַיִּשְׂבָּ֔עוּ] [שָׂבְע֖וּ] [וַיָּ֣רָם] [לִבָּ֑ם] sobre assim');
INSERT INTO verses VALUES (22342, 28, 13, 7, 'e-estive a-eles como [כְּנָמֵ֖ר] [עַל־דֶּ֥רֶךְ] sobre caminho');
INSERT INTO verses VALUES (22343, 28, 13, 8, 'אֶפְגְּשֵׁם֙ כְּדֹ֣ב שַׁחְוֹל וְאֵקְרַע סְגוּר coracoes-eles וְאָכְלֵם nome כְּלַבִּיא animal-de o-campo תְּבַקְעֵם׃');
INSERT INTO verses VALUES (22344, 28, 13, 9, '[שִֽׁחֶתְךָ֥] Israel porque [בְעֶזְרֶֽךָ]');
INSERT INTO verses VALUES (22345, 28, 13, 10, '[אֱהִ֤י] [מַלְכְּךָ֙] [אֵפ֔וֹא] [וְיוֹשִֽׁיעֲךָ֖] em-todo [וְשֹׁ֣פְטֶ֔יךָ] [אֲשֶׁ֣ר] que tu-disseste [מֶ֥לֶךְ] para-mim rei');
INSERT INTO verses VALUES (22346, 28, 13, 11, '[אֶֽתֶּן־לְךָ֥] para-ti rei [וְאֶקַּ֖ח] [בְּעֶבְרָתִֽי׃]');
INSERT INTO verses VALUES (22347, 28, 13, 12, '[צָרוּר֙] iniquidade [אֶפְרָ֔יִם] [צְפוּנָ֖ה] [חַטָּאתֽוֹ]');
INSERT INTO verses VALUES (22348, 28, 13, 13, '[חֶבְלֵ֥י] [יֽוֹלֵדָ֖ה] entrarão a-ele ele não não [כִּֽי־עֵ֥ת] porque tempo não');
INSERT INTO verses VALUES (22349, 28, 13, 14, '[מִיַּ֤ד] [שְׁאוֹל֙] [אֶפְדֵּ֔ם] [מִמָּ֖וֶת] [אֶגְאָלֵ֑ם] [אֱהִ֨י] [דְבָרֶיךָ֜] [מָ֗וֶת] [אֱהִ֤י] [קָֽטָבְךָ֙] [שְׁא֔וֹל] [נֹ֖חַם] [יִסָּתֵ֥ר] [מֵעֵינָֽי]');
INSERT INTO verses VALUES (22350, 28, 13, 15, 'que ele filho irmãos יַפְרִיא vira קָדִים espírito yhwh מִן־הַמִּדְבָּ֣ר עֹלֶה וְיֵב֤וֹשׁ מְקוֹרוֹ וְיֶחֱרַ֣ב מַעְיָנ֔וֹ ele יִשְׁסֶ֔ה אוֹצַ֖ר todo כְּלִ֥י desejo');
INSERT INTO chapters VALUES (876, 28, 14, 10);
INSERT INTO verses VALUES (22351, 28, 14, 1, 'serás condenada Samaria que Martha em suas deusas com-a-espada cairão seus filhos serão estripados e suas fortalezas serão quebrados');
INSERT INTO verses VALUES (22352, 28, 14, 2, 'volta Israel até yhwh teu-Elohim que כָּשַׁלְתָּ בַּעֲוֺנֶֽךָ׃');
INSERT INTO verses VALUES (22353, 28, 14, 3, 'tomai com-vós [דְּבָרִ֔ים] [וְשׁ֖וּבוּ] a yhwh a-ele a-ele todo [וְקַח־ט֔וֹב] [וּֽנְשַׁלְּמָ֥ה] e-toma bom');
INSERT INTO verses VALUES (22354, 28, 14, 4, '[אַשּׁ֣וּר] não não sobre [עַל־סוּס֙] não [נִרְכָּ֔ב] e-não [ע֛וֹד] ainda Elohim-nosso [יָדֵ֑ינוּ] [אֲשֶׁר־בְּךָ֖] que [יָתֽוֹם]');
INSERT INTO verses VALUES (22355, 28, 14, 5, 'אֶרְפַּא מְשׁוּבָתָם אֹהַבֵּם נְדַבָּה que retornou meu-rostro nós');
INSERT INTO verses VALUES (22356, 28, 14, 6, 'ehyeh chuva para-Israel floresça como-rosa e-meu suas-raízes como-cinzela');
INSERT INTO verses VALUES (22357, 28, 14, 7, 'andem seus-ventos e-seja como-azeitona הוֹד֑וֹ וְרֵ֥יחַֽ a-ele כַּלְּבָנֽוֹן׃');
INSERT INTO verses VALUES (22358, 28, 14, 8, 'voltavam habitantes-de [בְצִלּ֔וֹ] [יְחַיּ֥וּ] [דָגָ֖ן] [וְיִפְרְח֣וּ] [כַגָּ֑פֶן] [זִכְר֖וֹ] [כְּיֵ֥ין] [לְבָנֽוֹן׃]');
INSERT INTO verses VALUES (22359, 28, 14, 9, '[אֶפְרַ֕יִם] que para-mim ainda [אֲנִ֧י] [עָנִ֣יתִי] [וַאֲשׁוּרֶ֗נּוּ] [אֲנִי֙] eu [רַֽעֲנָ֔ן] [מִמֶּ֖נִּי] [פֶּרְיְךָ֥] [נִמְצָֽא]');
INSERT INTO verses VALUES (22360, 28, 14, 10, 'quem חָכָם וְיָ֣בֵֽן Estas נָב֖וֹן וְיֵֽדָעֵ֑ם porque יְשָׁרִ֞ים yhwh yhwh וְצַדִּקִים֙ irão neles וּפֹשְׁעִ֖ים יִכָּ֥שְׁלוּ neles:');
INSERT INTO books VALUES (29, 'JOL', 'Joel', 'AT', 4);
INSERT INTO chapters VALUES (877, 29, 1, 20);
INSERT INTO verses VALUES (22361, 29, 1, 1, 'palavra-de yhwh ser foi a filho-de');
INSERT INTO verses VALUES (22362, 29, 1, 2, 'ouvi esta הַזְּקֵנִ֔ים e ouviu todo a-terra a-terra será que haverá זֹאת em vossos dias e se nos dias de vos pais:');
INSERT INTO verses VALUES (22363, 29, 1, 3, 'sobre-ela a vossos filhos contem-lhes uveneychem a seus filhos e-seus-filhos para-geração outro');
INSERT INTO verses VALUES (22364, 29, 1, 4, 'resto o gazam comer a arbeh וְיֶ֥תֶר a arbeh comer o yaleq וְיֶ֣תֶר o yeleq comer o chasil');
INSERT INTO verses VALUES (22365, 29, 1, 5, 'acordai-vos bezerros e chorai e exultai todo שֹׁ֣תֵי vinho que עָסִ֕יס porque נִכְרַ֖ת מִפִּיכֶֽם׃');
INSERT INTO verses VALUES (22366, 29, 1, 6, 'porque subir subiu sobre [וְאֵ֣ין] [מִסְפָּ֑ר] e-não [שִׁנֵּ֣י] [אַרְיֵ֔ה] segundo [לָבִ֖יא] a-ele a-ele');
INSERT INTO verses VALUES (22367, 29, 1, 7, 'nome גַּפְנִי֙ לְשַׁמָּ֔ה וּתְאֵנָתִ֖י para-a-queja descobrirá sua-cara e arremessará iluminemos suas-angústias');
INSERT INTO verses VALUES (22368, 29, 1, 8, 'אֵל destruída cinto-de saco sobre Baal seu-nu-rei-ah');
INSERT INTO verses VALUES (22369, 29, 1, 9, 'corta oferta e-nesek de-casa-de yhwh choram os-sacerdotes servi yhwh');
INSERT INTO verses VALUES (22370, 29, 1, 10, 'Shuddad campo chora terra que Shuddad grão secou vinho אֻמְלַ֥ל יִצְחָֽר׃');
INSERT INTO verses VALUES (22371, 29, 1, 11, 'הֹבִ֣ישׁוּ אִכָּרִ֗ים brilharam כֹּֽרְמִ֔ים sobre חִטָּ֖ה que שְׂעֹרָ֑ה porque אָבַד ceifa-de sadeh');
INSERT INTO verses VALUES (22372, 29, 1, 12, '[הַגֶּ֣פֶן] [הוֹבִ֔ישָׁה] [וְהַתְּאֵנָ֖ה] [אֻמְלָ֑לָה] [רִמּ֞וֹן] também [וְתַפּ֗וּחַ] [כָּל־עֲצֵ֤י] todo [יָבֵ֔שׁוּ] o-campo [שָׂשׂ֖וֹן] porque homem de filhos-de homem');
INSERT INTO verses VALUES (22373, 29, 1, 13, 'חִגְר֨וּ וְסִפְד֜וּ os-sacerdotes brilharam מְשָׁרְתֵ֣י altar entrai לִ֣ינוּ בַשַּׂקּ֔ים מְשָׁרְתֵ֖י meu-Elohim que נִמְנַ֛ע de-casa-de Elohim de-vós oferta-cereais וָנָֽסֶךְ׃');
INSERT INTO verses VALUES (22374, 29, 1, 14, '[קַדְּשׁוּ־צוֹם֙] [קִרְא֣וּ] [עֲצָרָ֔ה] [אִסְפ֣וּ] [זְקֵנִ֗ים] [כֹּ֚ל] todo a-terra a-terra yhwh yhwh vosso-Elohim [אֶל־יְהוָֽה] a yhwh');
INSERT INTO verses VALUES (22375, 29, 1, 15, 'אֲהָ֖הּ לַיּ֑וֹם que proximo dia yhwh וּכְשֹׁ֖ד מִשַׁדַּ֥י יָבֽוֹא׃');
INSERT INTO verses VALUES (22376, 29, 1, 16, 'acaso-nao diante עֵינֵ֖ינוּ alimento נִכְרָ֑ת de-casa-de Elohim-nosso שִׂמְחָ֥ה וָגִֽיל׃');
INSERT INTO verses VALUES (22377, 29, 1, 17, 'abriram-se frutos debaixo suas garras suspiraram guardados cortaram suas cavernas que apavorou דָּגָֽן׃');
INSERT INTO verses VALUES (22378, 29, 1, 18, 'que- suspiraram animal choraram עֶדְרֵי que porque não a-eles para-eles também עֶדְרֵי yhwh נֶאְשָֽׁמוּ׃');
INSERT INTO verses VALUES (22379, 29, 1, 19, 'a-ti yhwh clamarei que fogo אָֽכְלָה֙ pastagens מִדְבָּ֔ר וְלֶ֣הָבָ֔ה לִהֲטָ֖ה todo עֲצֵי o-campo');
INSERT INTO verses VALUES (22380, 29, 1, 20, 'também בַּהֲמֹות campo תַּעֲר֣וֹג que porque יָֽבְשׁוּ֙ אֲפִיקֵי águas ve-esh אָכְלָ֖ה נְא֥וֹת o-meadero');
INSERT INTO chapters VALUES (878, 29, 2, 27);
INSERT INTO verses VALUES (22381, 29, 2, 1, 'tik''u shofar em Sião ve''har''ı̂yu em-monte-de qad''shi yir''gutz todo habitantes-de a-terra porque veio que yhwh porque qarōv');
INSERT INTO verses VALUES (22382, 29, 2, 2, 'dia escuridão va''afelāh dia עָנָן֙ va''ărapel ao amanhecer paru'' sobre ההרים povo muito ve''atzūm não não נִֽהְיָה֙ de não וְאַֽחֲרָיו֙ não José até segundo דּ֥וֹר וָדֽוֹר׃');
INSERT INTO verses VALUES (22383, 29, 2, 3, 'diante-dele אָ֣כְלָה fogo e-depois-dele תְּלַהֵ֣ט לֶֽהָבָ֑ה como-jardim- a-terra a-terra diante-dele וְאַֽחֲרָיו֙ deserto-de שְׁמָמָ֔ה e-também para-ele não ela-foi para-ele');
INSERT INTO verses VALUES (22384, 29, 2, 4, 'כְּמַרְאֵה cavalos מַרְאֵ֑הוּ וּכְפָרָשִׁ֖ים assim יְרוּץֽוּן׃');
INSERT INTO verses VALUES (22385, 29, 2, 5, 'kâ''qol מרכבות sobre cabeças-de os-montes ירקדונ כקול לחבה fogo comedora קש כאעם עצוים ערוך guerra');
INSERT INTO verses VALUES (22386, 29, 2, 6, '[מִפָּנָ֖יו] [יָחִ֣ילוּ] [עַמִּ֑ים] todo face [פָארֽוּר]');
INSERT INTO verses VALUES (22387, 29, 2, 7, 'כְּגִבּוֹרִ֣ים יְרֻצ֔וּן כְּאַנְשֵׁ֥י guerra יַעֲל֣וּ חוֹמָ֑ה e-homem em-caminhos-seus יֵֽלֵכ֔וּן e-não יְעַבְּט֖וּן אֹרְחוֹתָֽם׃');
INSERT INTO verses VALUES (22388, 29, 2, 8, 'e-homem seu-irmao não יִדְחָק֔וּן homem בִּמְסִלָּת֖וֹ יֵֽלֵכ֑וּן וּבְעַ֣ד הַשֶׁ֛לַח יִפֹּ֖לוּ não יִבְצָֽעוּ׃');
INSERT INTO verses VALUES (22389, 29, 2, 9, 'na-cidade יָשֹׁ֗קּוּ בַּֽחוֹמָה֙ ירוצנו בהבתים יעלו בעד הלוחות יבואו כאנב');
INSERT INTO verses VALUES (22390, 29, 2, 10, 'diante-dele [רָ֣גְזָה] terra [רָעֲשׁ֖וּ] céus [שֶׁ֤מֶשׁ] [וְיָרֵ֙חַ֙] [קָדָ֔רוּ] [וְכוֹכָבִ֖ים] [אָסְפ֥וּ] [נָגְהָֽם]');
INSERT INTO verses VALUES (22391, 29, 2, 11, 'e-yhwh dar קוֹלוֹ֙ diante-de seu exército que muito muito מַחֲנֵ֔הוּ que עָצ֖וּם fez דְבָר֑וֹ porque grande dia-de muito וְנוֹרָ֥א muito e-quem יְכִילֶֽנּוּ׃');
INSERT INTO verses VALUES (22392, 29, 2, 12, 'e-também agora oráculo-de yhwh [בְּכָל־לְבַבְכֶ֑ם] [וּבְצ֥וֹם] em-todo [וּבְמִסְפֵּֽד]');
INSERT INTO verses VALUES (22393, 29, 2, 13, 'וְקִרְע֤וּ vosso-coração e-a בִּגְדֵיכֶ֔ם וְשׁ֖וּבוּ a yhwh אֱלֹֽהֵיכֶ֑ם ele חַנּ֤וּן וְרַחוּם֙ ele longo rosto e-grande bondade e se alegrar sobre a-ráah');
INSERT INTO verses VALUES (22394, 29, 2, 14, 'quem que conhece voltara e se alegrar e manterá atrás-dele בְּרָכָ֔ה oferta e vinho para-יהוה Elohim-vosso');
INSERT INTO verses VALUES (22395, 29, 2, 15, 'solemneis corneta em Sião santifiquem- jejejemais- chamai- convocação; assembleia:');
INSERT INTO verses VALUES (22396, 29, 2, 16, 'congregai- povo santifiquem- assembleia; congregai- idosos congregai- estrangeiros; וְיֹנְקֵ֖י שָׁדָ֑יִם sairá noivo מֵֽחֶדְר֔וֹ וְכַלָּ֖ה מֵחֻפָּתָֽהּ׃');
INSERT INTO verses VALUES (22397, 29, 2, 17, 'entre הָאוּלָם֙ וְלַמִּזְבֵּ֔חַ chorareis os-sacerdotes מְשָׁרְתֵ֖י yhwh וְֽיֹאמְר֞וּ ח֧וּסָה yhwh sobre seu-people e-a tu-gives tua-heirloom para-honra para-governar- em-eles nações por-que dirão em-povos onde אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (22398, 29, 2, 18, 'e-comprar-se yhwh para-sua-terra e-misericordiar-se sobre povo-dele');
INSERT INTO verses VALUES (22399, 29, 2, 19, 'e-ele-respondeu yhwh E-disse para-seu-povo eis-me enviou a-vós a הַדָּגָן֙ וְהַתִּיר֣וֹשׁ e-hayitzháras ele a-ela e-não אֶתֵּ֨ן a-vocês ainda que בָּגוֹיִם׃');
INSERT INTO verses VALUES (22400, 29, 2, 20, 'e-a הַצְּפוֹנִ֞י אַרְחִ֣יק מֵעֲלֵיכֶ֗ם וְהִדַּחְתִּיו֮ a terra צִיָּה וּשְׁמָמָה֒ a as-pnai a o mar הַקַּדְמֹנִ֔י וְסֹפ֖וֹ a o-mar que e suba no fogo e se elevem sua tenda porque aumente para-fazer');
INSERT INTO verses VALUES (22401, 29, 2, 21, 'a terra terra-a meu prazer e minha alegria yhwh aumente yhwh para-fazer');
INSERT INTO verses VALUES (22402, 29, 2, 22, 'a temam com animais que porque דָּשַׁע pastagens מִדְבָּר porque madeira nasa פְּרִיֹּ תְּאֵנָה וַגֶּפֶן eles-deram חֵילָֽם׃');
INSERT INTO verses VALUES (22403, 29, 2, 23, 'e-filhos-de [צִיּ֗וֹן] [גִּ֤ילוּ] [וְשִׂמְחוּ֙] [בַּיהוָ֣ה] Elohim-vosso porque a-vós a-vós a [וַיּ֣וֹרֶד] a-vós [גֶּ֛שֶׁם] para-vós [וּמַלְק֖וֹשׁ] [בָּרִאשֽׁוֹן]');
INSERT INTO verses VALUES (22404, 29, 2, 24, 'e-encheram הַגֳּרָנ֖וֹת em bar וְהֵשִׁ֥יקוּ הַיְקָבִ֖ים תִּיר֥וֹשׁ וְיִצְהָֽר׃');
INSERT INTO verses VALUES (22405, 29, 2, 25, 'וְשִׁלַּמְתִּ֤י a-vós a הַשָּׁנִ֔ים comer אָכַ֣ל הָֽאַרְבֶּ֔ה o yelek e hachasil e hagazam chayli a-grande que shillachtiti בכם׃');
INSERT INTO verses VALUES (22406, 29, 2, 26, 'e-voces-comeram akol veshavuach velillatem a yhwh yhwh אֱלֹהִים-de-vós que fez com-vós lehapleya e-não vergonhem-se; povo-meu para-eternidade');
INSERT INTO verses VALUES (22407, 29, 2, 27, 'vidatetem que בְקֶ֤רֶב Israel eu e-eu yhwh Elohim de-vós e-não ainda e-não vergonhem-se; povo-meu para-eternidade');
INSERT INTO chapters VALUES (879, 29, 3, 5);
INSERT INTO verses VALUES (22408, 29, 3, 1, 'e-foi depois-de assim [אֶת־רוּחִי֙] a [וְנִבְּא֖וּ] sobre todo [זִקְנֵיכֶם֙] [חֲלֹמ֣וֹת] filhos-vossos [בַּח֣וּרֵיכֶ֔ם] [חֶזְיֹנ֖וֹת] [יִרְאֽוּ]');
INSERT INTO verses VALUES (22409, 29, 3, 2, 'e-também sobre הָֽעֲבָדִ֖ים e-sobre as-shaphachot em-os-dias הנה esh-sphokh a ruchi');
INSERT INTO verses VALUES (22410, 29, 3, 3, 'e-n-d-e-rei moftim nos-samaxim e-nas-teres sangue va-esh ve-ti-marot עָשָֽׁן׃');
INSERT INTO verses VALUES (22411, 29, 3, 4, 'o-sol ye-hafekh para as trevas ve-ha-yyarach לְדָ֑ם lifnei trazer dia yhwh o-grande ve-hanora');
INSERT INTO verses VALUES (22412, 29, 3, 5, 'e-será todo que [בְּשֵׁ֥ם] yhwh yhwh que porque em-monte-de [תִּֽהְיֶ֣ה] [פְלֵיטָ֗ה] [כַּֽאֲשֶׁר֙] disse yhwh disse yhwh yhwh que yhwh chamou');
INSERT INTO chapters VALUES (880, 29, 4, 21);
INSERT INTO verses VALUES (22413, 29, 4, 1, 'que eis בַּיָּמִ֥ים הָהֵ֖מָּה e-no-tempo-de aquela que a שבות יְהוּדָה וִירוּשָׁלָֽ͏ִם׃');
INSERT INTO verses VALUES (22414, 29, 4, 2, 'וְקִבַּצְתִּי֙ a todo as-nações וְה֣וֹרַדְתִּ֔ים a עֵ֖מֶק יְהֽוֹשָׁפָ֑ט e julgar-me-ei com eles nome sobre meu povo e minha herança Israel que dividam nos gentios e-a minha-terra se partilhem;');
INSERT INTO verses VALUES (22415, 29, 4, 3, 'e-a povo-meu eles tirarem sorteio e-eles-deram a-criança em zonas e a nascida Vendem no vinho וַיִּשְׁתּֽוּ׃');
INSERT INTO verses VALUES (22416, 29, 4, 4, 'e-tambem o-quê vós a-mim Síra e-tudo e-todo Gileade Filisteia o dívida vós pagam por mim e-se que remitem vós sobre-mim ligeiro depressa eu trarei gemulchem boreshchem:');
INSERT INTO verses VALUES (22417, 29, 4, 5, 'que kaspipi uzechavi lekachtem umachadai hatovim havete leheiklchem:');
INSERT INTO verses VALUES (22418, 29, 4, 6, 'e-filhos-de יְהוּדָה e-filhos-de Jerusalém mekartem a-filhos-de הַיְּוָנִ֑ים para הַרְחִיקָ֖ם de-cima-de em seus limites:');
INSERT INTO verses VALUES (22419, 29, 4, 7, 'eis-me מְעִירָ֔ם de o-lugar eles מְכַרְתֶּ֥ם eles para-lá וַהֲשִׁבֹתִ֥י גְמֻלְכֶ֖ם בְּרֹאשְׁכֶֽם׃');
INSERT INTO verses VALUES (22420, 29, 4, 8, 'וּמָכַרְתִּ֞י a filhos-vossos e-a בְּנֽוֹתֵיכֶ֗ם em-mão-de filhos-de Judá וּמְכָר֥וּם para os prisioneiros que yhwh distante porque yhwh palavra');
INSERT INTO verses VALUES (22421, 29, 4, 9, 'chamai esta entre-as-nações santifiquem guerra anunciem os-heróis aproximem-se subam todo homens-de a-batalha');
INSERT INTO verses VALUES (22422, 29, 4, 10, 'dizem com-vós para as desoladas e vossas harpas para os gafanhotos o lagarto será dito heroi- eu');
INSERT INTO verses VALUES (22423, 29, 4, 11, 'façais e entrardes todo as-nações ao-redor e juntar-vos-eis ali yhwh yhwh גבוריך׃');
INSERT INTO verses VALUES (22424, 29, 4, 12, 'dormireis וְיַעֲלוּ as-nações a עֵ֖מֶק que porque nome אֵשֵׁ֛ב לִשְׁפֹּ֥ט a todo as-nações misaviv');
INSERT INTO verses VALUES (22425, 29, 4, 13, 'שִׁלְח֣וּ מַגָּ֔ל que בָשַׁ֖ל קָצִ֑יר בֹּ֤אֽוּ רְדוּ֙ porque מָ֣לְאָה gat הֵשִׁיקוּ que porque multiplicai רָעַתָם׃');
INSERT INTO verses VALUES (22426, 29, 4, 14, 'הֲמוֹנִים הֲמוֹנִים be-emek הֶחָרַץ que proximo dia yhwh be-emek הֶחָרַץ׃');
INSERT INTO verses VALUES (22427, 29, 4, 15, 'שֶׁמֶשׁ וְיָרֵ֖חַ קָדְרוּ וְכוֹכָבִים אָסְפוּ נָגְהָֽם׃');
INSERT INTO verses VALUES (22428, 29, 4, 16, 'e-יהוה יִשְׁאָ֗ג וּמִירוּשָׁלִַ֙ם֙ dará קוֹל֔וֹ וְרָעֲשׁ֖וּ céus וָאָ֑רֶץ e-יהוה מַֽחֲסֶ֣ה לְעַמּ֔וֹ וּמָע֖וֹז para-filhos-de Israel');
INSERT INTO verses VALUES (22429, 29, 4, 17, 'e-vocês-sabereis que eu yhwh אֱלֹהִים-de-vós שֹׁכֵ֖ן בּצִיּוֹן monte-de קָדְשִׁי e-será Jerusalém santidade וְזָרִים não não nela ainda');
INSERT INTO verses VALUES (22430, 29, 4, 18, 'e-será no-dia o-aquele יִטּוּ hehārim עָסִיס וְהַגְּבָּעוֹת תּלַכְנָה חָלָב e-todo אֲפִיקֵי יְהוּדָה irão águas וּמַעְיָן yhwh yhwh ele sairá e-regou a ribeiro-de os‭ ‬deserto:');
INSERT INTO verses VALUES (22431, 29, 4, 19, 'Mitzrayim para‭ ‬Shammah sera e‭ ‬Edom para‭ ‬deserto: Shammah תהיה de‭ ‬Chamas filhos-de Judá que derramaram sangue‭ puro em sua terra:');
INSERT INTO verses VALUES (22432, 29, 4, 20, 'וִיהוּדָה para-sempre residiria Jerusalém para-geração geração:');
INSERT INTO verses VALUES (22433, 29, 4, 21, 'e eu levantarei silêncio não eu levantarei e-יהוה morando em Sião:');
INSERT INTO books VALUES (30, 'AMO', 'Amós', 'AT', 9);
INSERT INTO chapters VALUES (881, 30, 1, 15);
INSERT INTO verses VALUES (22434, 30, 1, 1, 'palavras-de עמוס que foi בַנֹּקְדִ֖ים מִתְּק֑וֹעַ que חָזָ֨ה sobre Israel nos-dias-de עֻזִיָּ֣ה rei-de Judá וּבִימֵ֞י Jeroboao filho-de יוֹאָשׁ֙ rei Israel dois-anos diante-de הָרָֽעַשׁ׃');
INSERT INTO verses VALUES (22435, 30, 1, 2, 'va-yomer yhwh yhwh יִשְׁאָ֔ג וּמִירוּשָׁלַ֖͏ִם dará sua voz e se lamentarão pastagens das pastagens e secará cabeça o jardim');
INSERT INTO verses VALUES (22436, 30, 1, 3, 'assim disse yhwh sobre três os pecados Damasco não quatro não eu os restituirei sobre destruí-los-ei em suas ruínas o-ferro a o-Gileade');
INSERT INTO verses VALUES (22437, 30, 1, 4, 'e enviarei fogo em-casa-de חזהאל e-consumiu palacios filho-de Hadá:');
INSERT INTO verses VALUES (22438, 30, 1, 5, 'e quebra-ei בריח de-Damasco e cortarei- יושב מבIQUEת- iniquidade ו samtke shevet de-casa-de עדן ו גלו com disse yhwh disse yhwh');
INSERT INTO verses VALUES (22439, 30, 1, 6, 'assim disse yhwh sobre três [עַזָּ֔ה] [וְעַל־אַרְבָּעָ֖ה] não quatro não [גָּל֥וּת] sobre [לְהַסְגִּ֥יר] [לֶאֱדֽוֹם]');
INSERT INTO verses VALUES (22440, 30, 1, 7, 'ואשלחתי fogo בכמת Gaza e-consumiu ארמנותיה׃');
INSERT INTO verses VALUES (22441, 30, 1, 8, 'e cortarei- יושב מעASHBOARD ואתך shevet מעשקלון e restituirei minha mão sobre Ekron e destruirão remanescente disse disse Adonai yhwh');
INSERT INTO verses VALUES (22442, 30, 1, 9, 'assim disse yhwh sobre três seus pecados não e-sobre quatro não os restituirei sobre e os aprisionarei exílio perfeita para Edom e-não zakru yhwh אַחִֽים׃');
INSERT INTO verses VALUES (22443, 30, 1, 10, 'veshillachti fogo b''chomat tsor e-consumiu armento''teha:');
INSERT INTO verses VALUES (22444, 30, 1, 11, 'assim disse yhwh sobre três pisha''e Edom não quatro não ashivenu sobre radfo bacharab seu-irmao vesichet suas misericórdias e alimentou até a eternidade sua-ira e sua lealdade ele guardou eternidade:');
INSERT INTO verses VALUES (22445, 30, 1, 12, 'e eu enviaria fogo em Teman e-consumiu palacios na angústia:');
INSERT INTO verses VALUES (22446, 30, 1, 13, 'assim disse yhwh sobre três os seus pecados filhos-de não e-sobre quatro não eu os retribuiria sobre בִּקְעָם֙ הָר֣וֹת Gileade para-que הַרְחִ֥יב a em seus limites:');
INSERT INTO verses VALUES (22447, 30, 1, 14, 'וְהִצַּ֤תִּי fogo בְּחוֹמַ֣ת multiplicai e-consumiu אַרְמְנוֹתֶ֑יהָ בִּתְרוּעָה֙ em-dia-de guerra בְּסַ֖עַר em-dia סוּפָֽה');
INSERT INTO verses VALUES (22448, 30, 1, 15, '[וְהָלַ֥ךְ] [מַלְכָּ֖ם] [בַּגּוֹלָ֑ה] ele [וְשָׂרָ֛יו] juntos disse yhwh');
INSERT INTO chapters VALUES (882, 30, 2, 16);
INSERT INTO verses VALUES (22449, 30, 2, 1, 'assim disse yhwh sobre três [מוֹאָ֔ב] Moabe não quatro não [עַצְמ֥וֹת] sobre [לַשִּֽׂיד] rei-de Edom');
INSERT INTO verses VALUES (22450, 30, 2, 2, 'וְשִׁלַּחְתִּי־ fogo בְּמוֹאָ֔ב e-consumiu armêntes as-queirot e-met no-são Moabe em-troeira com-voz chifre');
INSERT INTO verses VALUES (22451, 30, 2, 3, 'e-cortarei juiz da-milhares e-todo seus-sares e-horg disse yhwh yhwh');
INSERT INTO verses VALUES (22452, 30, 2, 4, 'assim disse yhwh sobre três transgressões Judá não quatro não אֲשִׁיבֶ֑נּוּ yhwh מָאֳסָ֞ם não lei-de yhwh וְחֻקָּיו֙ não guardaram וַיַּתְעוּם֙ כִּזְבֵיהֶ֔ם que e-caminharam pais-deles depois-deles');
INSERT INTO verses VALUES (22453, 30, 2, 5, 'וְשִׁלַּ֥חְתִּי fogo בִּֽיהוּדָ֑ה e-consumiu palacios Jerusalém');
INSERT INTO verses VALUES (22454, 30, 2, 6, 'assim disse yhwh sobre três [יִשְׂרָאֵ֔ל] Israel não quatro não [בַּכֶּ֙סֶף֙] sobre [וְאֶבְי֖וֹן] [בַּעֲב֥וּר] [נַעֲלָֽיִם]');
INSERT INTO verses VALUES (22455, 30, 2, 7, 'הַשֹּׁאֲפִ֤ים sobre עֲפַר־ terra na-cabeça דַּלּ֔ים e caminho עֲנָוִ֖ים יַטּ֑וּ e-homem וְאָבִ֗יו יֵֽלְכוּ֙ a a-moça para חַלֵּ֖ל a nome minha-santa-lócus');
INSERT INTO verses VALUES (22456, 30, 2, 8, 'e-sobre [חֲבֻלִים֙] [יַטּ֔וּ] [אֵ֖צֶל] junto todo [עֲנוּשִׁים֙] [יִשְׁתּ֔וּ] [בֵּ֖ית] [אֱלֹהֵיהֶֽם] casa אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (22457, 30, 2, 9, 'ואני השמדתי a o-emori de-diante-deles que כאbove ארזים gávaho ele ele ká''alônîm vá''ashmíd píryô de-acima vé''shárashâv de-baixo');
INSERT INTO verses VALUES (22458, 30, 2, 10, 'vé''ânoki he''aliti vós de-terra-de Egito vá''ôlêk a-vos bamidbar quarenta ano para-possuir a terra o-amorreu');
INSERT INTO verses VALUES (22459, 30, 2, 11, 'vâ''akím mibbênêkem lénabi''im e-dos-jovens-vossos para-os-nazaritas o-nariz não há isto filhos-de Israel oráculo-de yhwh');
INSERT INTO verses VALUES (22460, 30, 2, 12, 'e-ajambelem-no a os-nazaritas vinho e-sobre dizendo não para-dizer não e-consultem-vos');
INSERT INTO verses VALUES (22461, 30, 2, 13, 'eis eu de-antigamente por-baixo-de-vós como-que incrustem-no ha''agala o-cheio para-ela amor');
INSERT INTO verses VALUES (22462, 30, 2, 14, 'e destruirá manos de cal e fortalecerá não será encorajado seu poder e valente não será salvo a sua alma:');
INSERT INTO verses VALUES (22463, 30, 2, 15, 'e tomará a arco não יַעֲמֹ֔ד וְקַ֥ל בְּרַגְלָ֖יו não יְמַלֵּ֑ט e aquele que monta הַסּ֔וּס não יְמַלֵּ֖ט a sua alma:');
INSERT INTO verses VALUES (22464, 30, 2, 16, 'וְאַמִּ֥יץ para-seu-coração בַּגִּבּוֹרִ֑ים nu יָנ֥וּס בַּיּוֹם־ o-aquele oráculo-de yhwh');
INSERT INTO chapters VALUES (883, 30, 3, 15);
INSERT INTO verses VALUES (22465, 30, 3, 1, '[שִׁמְע֞וּ] a a-coisa o-este que yhwh yhwh sobre-vós filhos-de sobre sobre todo [הֶעֱלֵ֛יתִי] que [מִצְרַ֖יִם] dizendo Egito para-dizer');
INSERT INTO verses VALUES (22466, 30, 3, 2, 'somente [אֶתְכֶ֣ם] soube de-toda [מִשְׁפְּח֣וֹת] a-terra sobre assim [עֲלֵיכֶ֔ם] sobre-vós את todo');
INSERT INTO verses VALUES (22467, 30, 3, 3, '[הֲיֵלְכ֥וּ] dois juntos [בִּלְתִּ֖י] se');
INSERT INTO verses VALUES (22468, 30, 3, 4, '[הֲיִשְׁאַ֤ג] [אַרְיֵה֙] [בַּיַּ֔עַר] [וְטֶ֖רֶף] não-há a-ele [הֲיִתֵּ֨ן] [כְּפִ֤יר] [קוֹלוֹ֙] [מִמְּעֹ֣נָת֔וֹ] [בִּלְתִּ֖י] se');
INSERT INTO verses VALUES (22469, 30, 3, 5, '[הֲתִפֹּ֤ל] [צִפּוֹר֙] sobre a-terra a-terra [אֵ֣ין] não-há para ela [מִן־הָ֣אֲדָמָ֔ה] [וְלָכ֖וֹד] não a-terra não');
INSERT INTO verses VALUES (22470, 30, 3, 6, 'se יִתָּקַ֤ע שופר בְּעִ֔יר não não יֶחֱרָ֑דוּ se תִּהְיֶ֤ה mal não E Yahweh não fez');
INSERT INTO verses VALUES (22471, 30, 3, 7, 'que não [יַעֲשֶׂ֛ה] Adonai yhwh palavra que se [סוֹד֔וֹ] [אֶל־עֲבָדָ֖יו] a servos-dele');
INSERT INTO verses VALUES (22472, 30, 3, 8, '[אַרְיֵ֥ה] [שָׁאָ֖ג] quem não [יִירָ֑א] Adonai yhwh palavra quem não [יִנָּבֵֽא]');
INSERT INTO verses VALUES (22473, 30, 3, 9, 'השמיעו sobre ארמנות באסדוד e-sobre ארמנות em-terra-de Egito ואמרו האספוּ sobre montes-de שֹׁמְר֔וֹן וראוּ mhūmōt rabbōth yhwh va''ăšûqîm na-sua-entre');
INSERT INTO verses VALUES (22474, 30, 3, 10, 'e-não [עֲשׂוֹת־נְכֹחָ֖ה] [נְאֻם־יְהוָ֑ה] [הָאֽוֹצְרִ֛ים] oráculo-de yhwh [בְּאַרְמְנֽוֹתֵיהֶֽם׃]');
INSERT INTO verses VALUES (22475, 30, 3, 11, 'portanto assim disse Adonai yhwh [צַ֖ר] [וּסְבִ֣יב] a-terra [וְהוֹרִ֤ד] [מִמֵּךְ֙] [עֻזֵּ֔ךְ] [וְנָבֹ֖זּוּ] [אַרְמְנוֹתָֽיִךְ]');
INSERT INTO verses VALUES (22476, 30, 3, 12, '[כֹּה֮] disse yhwh como-que [יַצִּ֨יל] [הָרֹעֶ֜ה] [מִפִּ֧י] [הָאֲרִ֛י] duas-de [כְרָעַ֖יִם] ou [בְדַל־אֹ֑זֶן] [כֵּ֣ן] assim [בְּנֵ֣י] filhos-de Israel os-habitam em-Samaria [מִטָּ֖ה] [וּבִדְמֶ֥שֶׁק] [עָֽרֶשׂ]');
INSERT INTO verses VALUES (22477, 30, 3, 13, 'ouvi [וְהָעִ֖ידוּ] em-casa-de Jacó oráculo-de Adonai yhwh Elohim-de');
INSERT INTO verses VALUES (22478, 30, 3, 14, 'que em-dia-de [פָּקְדִ֥י] [פִשְׁעֵֽי־יִשְׂרָאֵ֖ל] Israel sobre-ele [עַל־מִזְבְּח֣וֹת] sobre [וְנִגְדְּעוּ֙] casa-de El [וְנָפְל֖וּ] [לָאָֽרֶץ] o altar para-a-terra');
INSERT INTO verses VALUES (22479, 30, 3, 15, 'e matarei casa-de o inverno sobre casa o verão e serão destruídos בָּתֵּ֣י o outono e sujem-se em casas muitos oráculo-de yhwh');
INSERT INTO chapters VALUES (884, 30, 4, 13);
INSERT INTO verses VALUES (22480, 30, 4, 1, 'ouvireis a-coisa o-este ovos o-Basã que em-monte-de Samaria as trabalhadoras דלים הרצכות איבונים האמורות לאדוניהם הביאה וישתה׃');
INSERT INTO verses VALUES (22481, 30, 4, 2, 'jura Adonai yhwh בקדשוֹ que eis dias Ba''îm sobre-vós ונשע a-vós בצינות וְאַחֲרִיתְכֶ֖ן בְּסִיר֥וֹת דּוּגָֽה׃');
INSERT INTO verses VALUES (22482, 30, 4, 3, '[וּפְרָצִ֥ים] [תֵּצֶ֖אנָה] mulher [נֶגְדָּ֑הּ] [וְהִשְׁלַכְתֶּ֥נָה] [הַהַרְמ֖וֹנָה] oráculo-de yhwh');
INSERT INTO verses VALUES (22483, 30, 4, 4, '-venham casa-de El וּפִשְׁע֔וּ o-Gilgal הַרְבּ֣וּ para espalharem e trazam no manha vossos sacrifícios para trinta dias mašśārōteḵem:');
INSERT INTO verses VALUES (22484, 30, 4, 5, 'e ofereçam incenso de fermento oblação de agradecimento e invocarem נדבות השמיעו que assim אהבתם filhos-de Israel oráculo-de Adonai yhwh');
INSERT INTO verses VALUES (22485, 30, 4, 6, 'e-também dei a-vós para-vocês [שִׁנַּ֙יִם֙] dois em-todo pão [בְּכֹ֖ל] Belém em-todo [עָדַ֖י] e-não oráculo-de yhwh');
INSERT INTO verses VALUES (22486, 30, 4, 7, 'e-também eu מנעתי mikem: a hag-gesh-tem בעוד três חדשים לקציר והמטרטתי sobre cidade uma não cidade uma uma אמטיר חלקה uma תימטר והחלקה que não תמטיר sobre-ela תיבוש׃');
INSERT INTO verses VALUES (22487, 30, 4, 8, '[וְנָע֡וּ] [שְׁתַּיִם֩] três [עָרִ֜ים] a uma uma águas águas e-não [וְלֹֽא־שַׁבְתֶּ֥ם] e-não [נְאֻם־יְהוָֽה] oráculo-de yhwh');
INSERT INTO verses VALUES (22488, 30, 4, 9, 'הכיתי a-vós בְּשַׁדּוֹף וּבִיַּרְקֹון֒ הֶרְבֹּות גָּנוֹתֵיכֶם וְכַרְמֵיכֶם וּתְאֵנֵיכֶם e vossos olivais comer-á o seu e-não descansastes até oráculo-de yhwh');
INSERT INTO verses VALUES (22489, 30, 4, 10, 'enviei em vós palavra no-caminho Egito matei בחרב os jovens vossos povo senta vossos cavalos e subi em-אֹשׁ vossos-machnicem e-em-appekhem e-não volvei-shabtem contra-adai oráculo-de yhwh');
INSERT INTO verses VALUES (22490, 30, 4, 11, 'tornei-hafachtie em-bekhem como-mahpechath Elohim a Sedom e-a Amorá e-vastehiyu כּ-אוֹד מֻצָּל מִשְׂרֵפָה e-não שַׁבְתֶּם עָדַי oráculo-de yhwh');
INSERT INTO verses VALUES (22491, 30, 4, 12, 'portanto assim farei- para ti Israel por causa disso porque זֹאת farei para-ti הִכָּון לִקְרַאת- teu-Elohim Israel');
INSERT INTO verses VALUES (22492, 30, 4, 13, 'que eis [יוֹצֵ֨ר] [הָרִ֜ים] [וּבֹרֵ֣א] espírito [וּמַגִּ֤יד] [לְאָדָם֙] que- [עֹשֵׂ֥ה] fez [עֵיפָ֔ה] [וְדֹרֵ֖ךְ] [עַל־בָּ֣מֳתֵי] sobre yhwh terra yhwh de-exércitos nome-dele');
INSERT INTO chapters VALUES (885, 30, 5, 27);
INSERT INTO verses VALUES (22493, 30, 5, 1, 'שִׁמְע֞וּ a a-coisa o-este eu eu נֹשֵׂ֧א sobre-vós קִינָ֖ה casa Israel');
INSERT INTO verses VALUES (22494, 30, 5, 2, '[נָֽפְלָה֙] não [ק֔וּם] levantou [יִשְׂרָאֵ֑ל] Israel [עַל־אַדְמָתָ֖הּ] sobre [מְקִימָֽהּ] não');
INSERT INTO verses VALUES (22495, 30, 5, 3, 'que assim disse Adonai yhwh a-cidade הַיֹּצֵ֥את mil תַּשְׁאִ֣יר cem וְהַיּוֹצֵ֥את cem תַּשְׁאִ֥יר עֲשָׂרָ֖ה segundo-casa-de Israel');
INSERT INTO verses VALUES (22496, 30, 5, 4, 'que assim disse yhwh para-casa-de Israel דִּרְשׁוּנִי וִֽחְיֽוּ׃');
INSERT INTO verses VALUES (22497, 30, 5, 5, 'e-a [בֵּֽית־אֵ֔ל] casa-de não [תָבֹ֔אוּ] não [שֶׁ֖בַע] não sete que [הַגִּלְגָּל֙] porque [יִגְלֶ֔ה] [וּבֵֽית־אֵ֖ל] será [לְאָֽוֶן] El será');
INSERT INTO verses VALUES (22498, 30, 5, 6, '[דִּרְשׁ֥וּ] a yhwh [פֶּן־יִצְלַ֤ח] para-que-não [בֵּ֣ית] [יוֹסֵ֔ף] casa José [לְבֵֽית־אֵֽל] e-não-há El');
INSERT INTO verses VALUES (22499, 30, 5, 7, 'הַהֹפְכִ֥ים לְלַעֲנָ֖ה juízo e-justica לָאָ֥רֶץ הִנִּֽיחוּ׃');
INSERT INTO verses VALUES (22500, 30, 5, 8, 'fez כִימָ֜ה וּכְסִ֗יל וְהֹפֵ֤ךְ al-laboker tsalamavet ve-yom noite he-chashak ha-kore le-mei- hay-yam [עַל־פְּנֵ֥י] a-terra yhwh a-terra yhwh nome-dele');
INSERT INTO verses VALUES (22501, 30, 5, 9, 'hamavalig shod sobre az וְשֹׁ֖ד sobre מִבְצָ֥ר yhwh');
INSERT INTO verses VALUES (22502, 30, 5, 10, 'שָׂנְא֥וּ בַשַּׁ֖עַר provará וְדֹבֵ֥ר perfeito יְתָעֵֽבוּ׃');
INSERT INTO verses VALUES (22503, 30, 5, 11, 'portanto porque [בּוֹשַׁסְכֶ֞ם] sobre pobre [תִּקְח֣וּ] nós [בָּתֵּ֥י] dele [בְּנִיתֶ֖ם] [וְלֹא־תֵ֣שְׁבוּ] [בָ֑ם] e-não [נְטַעְתֶּ֔ם] em-elas [תִשְׁתּ֖וּ] [אֶת־יֵינָֽם] e-não a');
INSERT INTO verses VALUES (22504, 30, 5, 12, 'que conheci רַבִּ֣ים פִּשְׁעֵיכֶ֔ם וַעֲצֻמִים חַטֹּֽאתֵיכֶ֑ם צֹרְרֵ֤י just-o לוֹקְחֵי cobre וְאֶבְיוֹנִים בַּשַׁ֥עַר הִטּֽוּ׃');
INSERT INTO verses VALUES (22505, 30, 5, 13, 'portanto הַמַּשְׂכִּ֛יל em-o tempo aquela se-estabeleça que tempo maldade ela');
INSERT INTO verses VALUES (22506, 30, 5, 14, 'דִּרְשׁוּ־ bom e-a mau para-que yhwh וִיהִי־ assim yhwh Elohim-de exércitos com-vocês como-que אֲמַרְתֶּֽם׃');
INSERT INTO verses VALUES (22507, 30, 5, 15, 'שִׂנְאוּ־ mau bom bom e exibissem no portão juízo talvez yhwh yhwh Elohim-de de-exércitos restante José');
INSERT INTO verses VALUES (22508, 30, 5, 16, 'portanto assim yhwh yhwh Elohim-de dos-exércitos Adonai em-todo ruas luto e-em-todo portões dirão o e e chamassem tristeza a debaixo luto a יודעי נHEYי׃');
INSERT INTO verses VALUES (22509, 30, 5, 17, 'e-em-todo כראמים MSNPED porque disse yhwh disse yhwh');
INSERT INTO verses VALUES (22510, 30, 5, 18, 'ai המתאוים a yhwh yhwh a-vós dia yhwh dia yhwh ele escuridão e-não luz');
INSERT INTO verses VALUES (22511, 30, 5, 19, 'como-que YNCUS homem de-diante-de האריה UFGEAo הدب ובא a-casa e-ele-apoiará sua-mão sobre o muro - o escudo a cobra');
INSERT INTO verses VALUES (22512, 30, 5, 20, 'não-é dia yhwh yhwh e-não luz a-ele e-não a-ele');
INSERT INTO verses VALUES (22513, 30, 5, 21, 'odiava rejeitava vossos festivais e-não eu farei em vossas assembleias');
INSERT INTO verses VALUES (22514, 30, 5, 22, 'que se levantai-vos para-mim não e-vossas-minhações não eu-terrei não vosso-liquor não olha:');
INSERT INTO verses VALUES (22515, 30, 5, 23, 'tira de-sobre-mim multidão vosso-cantos e-vossas-cantigas neḇāleḵa não אֶשְׁמַֽע׃');
INSERT INTO verses VALUES (22516, 30, 5, 24, 'e-se-revelem כאמים juízo e-justica כנחל איתן׃');
INSERT INTO verses VALUES (22517, 30, 5, 25, '[הַזְּבָחִ֨ים] [וּמִנְחָ֜ה] [הִֽגַּשְׁתֶּם־לִ֧י] [בַמִּדְבָּ֛ר] [אַרְבָּעִ֥ים] quarenta ano casa Israel');
INSERT INTO verses VALUES (22518, 30, 5, 26, 'ונשאתם את סכות vossos-reis e-a כיון צלמייכם estrela אֱלֹהִים-de-vós que fizestes a-vós');
INSERT INTO verses VALUES (22519, 30, 5, 27, 'והגליתי vós מהלאה לדמשק disse yhwh Elohim-de de-exércitos nome-dele');
INSERT INTO chapters VALUES (886, 30, 6, 14);
INSERT INTO verses VALUES (22520, 30, 6, 1, 'ה֜וֹי השעננים בציון והבטחים em-monte-de Samaria נקבי ré''eshít as-nações u-ba''u a-eles casa Israel');
INSERT INTO verses VALUES (22521, 30, 6, 2, 'עברו כלנה e-vede ולכו de-lá chamath multiplicai e-dominai גַת־ פְּלִשְׁתּ֗ים הֲטוֹבִים֙ de הַמַּמְלָכ֣וֹת os-estes se muito e-sejam מִגְּבֻלְכֶֽם׃');
INSERT INTO verses VALUES (22522, 30, 6, 3, '[הַֽמְנַדִּ֖ים] para-o-dia mal [וַתַּגִּישׁ֖וּן] [שֶׁ֥בֶת] violência');
INSERT INTO verses VALUES (22523, 30, 6, 4, '[הַשֹּֽׁכְבִים֙] sobre [שֵׁ֔ן] [וּסְרֻחִ֖ים] [עַל־עַרְשׂוֹתָ֑ם] sobre [כָּרִים֙] [מִצֹּ֔אן] [וַעֲגָלִ֖ים] [מִתּ֥וֹךְ] [מַרְבֵּֽק]');
INSERT INTO verses VALUES (22524, 30, 6, 5, '[הַפֹּרְטִ֖ים] sobre boca-de [כְּדָוִ֕יד] [חָשְׁב֥וּ] a-eles a-eles objetos-de');
INSERT INTO verses VALUES (22525, 30, 6, 6, '[הַשֹּׁתִ֤ים] [בְּמִזְרְקֵי֙] vinho [וְרֵאשִׁ֥ית] [שְׁמָנִ֖ים] [יִמְשָׁ֑חוּ] e-não [נֶחְל֖וּ] sobre [יוֹסֵֽף]');
INSERT INTO verses VALUES (22526, 30, 6, 7, 'por-isso agora יִגְל֖וּ na-cabeça גֹּלִ֑ים וְסָ֖ר מִרְזַ֥ח סְרוּחִֽים׃');
INSERT INTO verses VALUES (22527, 30, 6, 8, 'נִשְׁבַּע֩ Adonai yhwh בְּנַפְשׁ֗וֹ oráculo-de yhwh Elohim-de exércitos eu eu a orgulho Jacó וְאַרְמְנֹתָ֖יו שָׂנֵ֑אתִי וְהִסְגַּרְתִּ֖י cidade e plenitude');
INSERT INTO verses VALUES (22528, 30, 6, 9, 'e-será se sobraram dez homens um um e-morreram');
INSERT INTO verses VALUES (22529, 30, 6, 10, 'e levou-o seu tio e separou-o para levar ossos de o templo e disse a quem בּיַרְכּתֵי a-casa הַע֥וֹד contigo וְאָמַ֣ר אָפֶס וְאָמַ֣ר que não não לַזְכּוֹר yhwh yhwh');
INSERT INTO verses VALUES (22530, 30, 6, 11, 'porque yhwh yhwh מַצָּוֶה וְהֵכִּים o-templo o-grande רְסִיסִים o-pequeno o pequeno בַקִיעִים׃');
INSERT INTO verses VALUES (22531, 30, 6, 12, 'הֵרֹץ בָּסֶלַע cavalos se יְחַרֵשׁ no-bkarim porque hafachtetem lerosh משפט ufrui justiça llelanah');
INSERT INTO verses VALUES (22532, 30, 6, 13, 'hasameichim lal palavra haomrim não bchazkeinu lakachnu para-nós קרניים׃');
INSERT INTO verses VALUES (22533, 30, 6, 14, 'que eis-me levanta sobre-vos casa Israel oráculo-de yhwh Elohim-de הַצְּבָא֖וֹת nação וְלָחֲצ֥וּ a-vós do leite de cór até ribeiro-de הָעֲרָבָֽה׃');
INSERT INTO chapters VALUES (887, 30, 7, 17);
INSERT INTO verses VALUES (22534, 30, 7, 1, 'assim הִרְאַ֙נִי֙ Adonai yhwh e-eis יווצר גֹּבַ֔י no-início-de עֲל֣וֹת הַלָּ֑קֶשׁ וְהִ֨נֵּה־ לֶ֔קֶשׁ apos גִּזֵּ֥י o rei');
INSERT INTO verses VALUES (22535, 30, 7, 2, 'e-será se kille le-ʾeḵol a-terra erva a-terra e-disse Adonai quem sela- por-favor que yaqum ele porque pequeno ela');
INSERT INTO verses VALUES (22536, 30, 7, 3, '[נִחַ֥ם] yhwh sobre não não disse yhwh yhwh');
INSERT INTO verses VALUES (22537, 30, 7, 4, 'assim hirʾaniy Adonai yhwh e-eis chamou para a multidão com-fogo Adonai yhwh e-comeste a abismo multiplicai e-consumiu a o pedaço:');
INSERT INTO verses VALUES (22538, 30, 7, 5, 'e-disse Adonai yhwh deixou de quem quem levantar-se que porque ele ela');
INSERT INTO verses VALUES (22539, 30, 7, 6, 'נִחַ֥ם yhwh sobre esta não ela disse sera disse Adonai yhwh');
INSERT INTO verses VALUES (22540, 30, 7, 7, 'assim [הִרְאַ֔נִי] e-eis Adonai [נִצָּ֖ב] sobre muro-de [וּבְיָד֖וֹ] [אֲנָֽךְ]');
INSERT INTO verses VALUES (22541, 30, 7, 8, 'E-disse yhwh a-mim que tu viu [וָאֹמַ֖ר] e-disse E-disse E-disse Adonai eis-me nome [בְּקֶ֙רֶב֙] [עַמִּ֣י] meu-povo Israel não [עֲב֥וֹר] a-ele');
INSERT INTO verses VALUES (22542, 30, 7, 9, 'e-respirarão בָּמוֹת יִשְׂחָ֔ק e os santuários Israel serão destruídos e levantar-me-ei sobre casa Jeroboão pela-espada');
INSERT INTO verses VALUES (22543, 30, 7, 10, 'e-enviou Amazias sacerdote casa-de El a dizendo rei-de Israel dizendo fiz sobre ti Amós no meio de a-terra Israel não poderias a-terra anunciar a todo דְבָרָֽיו׃');
INSERT INTO verses VALUES (22544, 30, 7, 11, 'porque disse disse [בַּחֶ֖רֶב] pela-espada [יָרָבְעָ֑ם] [וְיִ֨שְׂרָאֵ֔ל] [גָּלֹ֥ה] [יִגְלֶ֖ה] de-cima-de de-sobre');
INSERT INTO verses VALUES (22545, 30, 7, 12, 'E-disse [אֲמַצְיָה֙] a [חֹזֶ֕ה] [לֵ֥ךְ] vai [אֶל־אֶ֣רֶץ] a-ti a pão Judá [תִּנָּבֵֽא] nome');
INSERT INTO verses VALUES (22546, 30, 7, 13, '[וּבֵֽית־אֵ֔ל] El não [לְהִנָּבֵ֑א] que [מִקְדַּשׁ־מֶ֙לֶךְ֙] ele [וּבֵ֥ית] rei ele');
INSERT INTO verses VALUES (22547, 30, 7, 14, 'e-respondeu [עָמוֹס֙] E-disse a [לֹא־נָבִ֣יא] eu profeta eu eu filho-de eu eu porque');
INSERT INTO verses VALUES (22548, 30, 7, 15, 'e tomou-me yhwh de-após do-rebanho E-disse a-mim yhwh vai e profetizou a povo-meu Israel');
INSERT INTO verses VALUES (22549, 30, 7, 16, 'e-agora ouviu palavra-de tu tu não não tu profetiza sobre Israel e-não tu beberás sobre casa Isaque');
INSERT INTO verses VALUES (22550, 30, 7, 17, 'portanto assim yhwh yhwh a tua mulher em a cidade tu te prostituirás e os teus filhos e as tuas filhas com-a-espada יִפֹּ֔לוּ וְאַדְמָתְךָ֖ בַּחֶ֣בֶל תְּחֻלָּ֑ק e-tu sobre morrerás טְמֵאָה֙ morres וְיִ֨שְׂרָאֵ֔ל de-cima-de יִגְלֶ֖ה de-sobre אַדְמָתֽוֹ׃');
INSERT INTO chapters VALUES (888, 30, 8, 14);
INSERT INTO verses VALUES (22551, 30, 8, 1, 'assim [הִרְאַ֖נִי] Adonai yhwh e-eis [כְּל֥וּב] [קָֽיִץ]');
INSERT INTO verses VALUES (22552, 30, 8, 2, 'E-disse que tu viu [וָאֹמַ֖ר] e-disse [קָ֑יִץ] E-disse yhwh yhwh a-mim veio [אֶל־עַמִּ֣י] a meu-povo Israel não a-ele');
INSERT INTO verses VALUES (22553, 30, 8, 3, '[וְהֵילִ֜ילוּ] [שִׁיר֤וֹת] [הֵיכָל֙] no-dia aquele oráculo-de Adonai yhwh muito [הַפֶּ֔גֶר] em-todo [הִשְׁלִ֥יךְ] [הָֽס׃]');
INSERT INTO verses VALUES (22554, 30, 8, 4, 'ouvi isto as sopas pobre e para quebrar terra');
INSERT INTO verses VALUES (22555, 30, 8, 5, 'dizendo quando יַעֲבֹ֤ר o mês e quebraremos quebra-obra e o sabbat e quebraremos em bar para diminuir eifá e para aumentar prata e para enganar מֹאזְנֵ֥י engano');
INSERT INTO verses VALUES (22556, 30, 8, 6, 'para comprar em dinheiro dálmata e pobre por-causa-de meus sapatos וּמַפּ֥ל בַּ֖ר נַשְׁבִּֽיר׃');
INSERT INTO verses VALUES (22557, 30, 8, 7, 'jurou yhwh [בִּגְא֣וֹן] Jacó se [לָנֶ֖צַח] [כָּל־מַעֲשֵׂיהֶֽם] todo');
INSERT INTO verses VALUES (22558, 30, 8, 8, '[הַ֤עַל] esta não a-terra a-terra [כָּל־יוֹשֵׁ֣ב] todo habitante-de nela [כֻּלָּ֔הּ] [וְנִגְרְשָׁ֥ה] [*ונשקה] [**וְנִשְׁקְעָ֖ה] [כִּיא֥וֹר] Egito');
INSERT INTO verses VALUES (22559, 30, 8, 9, 'e-era em-o-dia no-dia oráculo-de Adonai yhwh וְהֵבֵאתִ֥י o-sol בְּצָהֳרָ֑יִם וְהַחֲשַׁךְתִּ֥י לָאָ֖רֶץ em-dia luz');
INSERT INTO verses VALUES (22560, 30, 8, 10, 'וְהָפַךְתִּ֨י חַגּוֹכֶ֜ם לְאֵ֗בֶל e-todo vossas-cantigas para-lamento e-elevarei sobre todo duas-colunas שָׂ֔ק e-sobre todo cabeça cicatriz e-terei-na como-luto solitário e-depois-del-a como o dia amargura');
INSERT INTO verses VALUES (22561, 30, 8, 11, 'eis dias באים oráculo-de Adonai yhwh e lançarei fome em-a-terra não fome ao pão e-não fome que porque se para ouvir yhwh palavras-de yhwh');
INSERT INTO verses VALUES (22562, 30, 8, 12, 'e se moverão águas até mar e do norte e-até do oriente andarão de lado a lado para-buscar a palavra-de yhwh e-não e se encontrarão;');
INSERT INTO verses VALUES (22563, 30, 8, 13, 'no-dia o-aquele se cobrirá [הַבְּתוּלֹ֧ת] as belas e os jovens no deserto:');
INSERT INTO verses VALUES (22564, 30, 8, 14, 'os jurados pela iniqüidade Samaria e-diretriz viveu Elohim-teu דן e a vida o-caminho-de por água sete cairão e-não arising ainda');
INSERT INTO chapters VALUES (889, 30, 9, 15);
INSERT INTO verses VALUES (22565, 30, 9, 1, 'eu vi a Adonai נצב E-disse o-altar E-disse aquela o cipoel e tremerão as tábuas e com estremecimento na-cabeça todos eles e depois deles com-a-espada a-eles não salvo a-eles salvado e-não se refugiará a-eles פליט׃');
INSERT INTO verses VALUES (22566, 30, 9, 2, 'se [בִשְׁא֔וֹל] [מִשָּׁ֖ם] de-lá mão-de-mim [וְאִֽם־יַעֲלוּ֙] [הַשָּׁמַ֔יִם] [מִשָּׁ֖ם] os-céus');
INSERT INTO verses VALUES (22567, 30, 9, 3, 'e-se יחבוּן na-cabeça הַכַּרְמֶ֔ל daí אֲחַפשׂ ולקחתים e-se serão escondidos de frente para o-mar bekarka o-mar de-lá mandemos a a-serpente e vosso inimigo');
INSERT INTO verses VALUES (22568, 30, 9, 4, 'e-se andarão em sua desgraça diante-de seus inimigos de-lá mandemos a a-espada e os exterminarei e colocarei meu olho sobre-eles para a maldição e-não para-bem:');
INSERT INTO verses VALUES (22569, 30, 9, 5, 'e-Adonai yhwh o-exércitos o-penitente na-terra e-marchou וְאָבְל֖וּ todo os-assentados nela e-subiu como-rio toda-a e-afundou-se כּיֹור מִצְרַיִם');
INSERT INTO verses VALUES (22570, 30, 9, 6, '[הַבּוֹנֶ֤ה] [בַשָּׁמַ֙יִם֙] [*מעלותו] sobre terra [עַל־אֶ֣רֶץ] [יְסָדָ֑הּ] [הַקֹּרֵ֣א] [לְמֵֽי־הַיָּ֗ם] [וַֽיִּשְׁפְּכֵ֛ם] sobre a-terra yhwh yhwh');
INSERT INTO verses VALUES (22571, 30, 9, 7, 'porventura-não [כִבְנֵי֩] [כֻשִׁיִּ֨ים] vós para-mim filhos-de Israel oráculo-de yhwh porventura-não a Israel [מִצְרַ֔יִם] da-terra Egito [וַאֲרָ֥ם] [מִקִּֽיר]');
INSERT INTO verses VALUES (22572, 30, 9, 8, 'eis os-olhos-de Adonai yhwh [יְהוִ֗ה] [בַּמַּמְלָכָה֙] [הַֽחַטָּאָ֔ה] a-ela de-sobre de-cima-de face-de a-terra porque que não [הַשְׁמֵ֥יד] a casa Jacó oráculo-de yhwh');
INSERT INTO verses VALUES (22573, 30, 9, 9, 'porque eu [מְצַוֶּ֔ה] [וַהֲנִע֥וֹתִי] [בְכָֽל־הַגּוֹיִ֖ם] em-todo as-nações a casa Israel como-que [צְר֖וֹר] [אָֽרֶץ] e-não terra');
INSERT INTO verses VALUES (22574, 30, 9, 10, 'com-a-espada יָמ֔וּתוּ todo חַטָּאֵ֣י meu-povo os que dizem não תַגִּ֧ישׁ e-taqudim para-nos a-ráah');
INSERT INTO verses VALUES (22575, 30, 9, 11, 'no-dia aquele eu-elevarei a tenda David as caídas e-erguirei-a-muralha a suas-portas e-destruirei-seus-muros eu-elevarei eternidade כִּימֵ֥י eternidade');
INSERT INTO verses VALUES (22576, 30, 9, 12, 'para-que יִֽירְשׁ֜וּ a שְׁאֵרִ֤ית Edom e-todo as-nações que foi-chamado nome-meu sobre-eles oráculo-de yhwh fez esta');
INSERT INTO verses VALUES (22577, 30, 9, 13, 'eis dias os-vindo oráculo-de yhwh וְנִגַּ֤שׁ חוֹרֵשׁ֙ בַּקֹּצֵ֔ר וְדֹרֵ֥ךְ anabim בְּמֹשֵׁ֣ךְ הַזָּ֑רַע וְהִטִּ֤יפוּ os-montes אסיס e-todo הגבאות תיתמודגן');
INSERT INTO verses VALUES (22578, 30, 9, 14, 'ושבתי a שְׁב֣וּת meu-povo Israel ובנו ערים נשמות VASHUBU VNATOIU vinhas VASHTU a יֵינָ֑ם ועשוּ גַנּ֔וֹת va''aklu a פְּרִיהֶֽם׃');
INSERT INTO verses VALUES (22579, 30, 9, 15, '[וּנְטַעְתִּ֖ים] sobre [וְלֹ֨א] e-não [ע֗וֹד] de-cima-de [אַדְמָתָם֙] [אֲשֶׁ֣ר] dei a-eles disse yhwh yhwh');
INSERT INTO books VALUES (31, 'OBA', 'Obadias', 'AT', 1);
INSERT INTO chapters VALUES (890, 31, 1, 21);
INSERT INTO verses VALUES (22580, 31, 1, 1, '[חֲז֖וֹן] [עֹֽבַדְיָ֑ה] assim disse Adonai yhwh [שְׁמוּעָ֨ה] [שָׁמַ֜עְנוּ] [מֵאֵ֤ת] yhwh yhwh [בַּגּוֹיִ֣ם] [שֻׁלָּ֔ח] enviou [וְנָק֥וּמָה] [עָלֶיהָ[c]] [לַמִּלְחָמָֽה]');
INSERT INTO verses VALUES (22581, 31, 1, 2, 'eis pequeno eu-deti-te em-países בזוי tu muito');
INSERT INTO verses VALUES (22582, 31, 1, 3, 'זְדֹ֣ון לִבֶּֽךָ הִשַּׁעֲיֵ֖ךָ שֹׁכְנִ֣י בְּחַגְוֵֽי־ סֶ֑לַע altura שִׁבְתּ֔וֹ disse quem quem יוֹרַדֵּ֖נִי terra');
INSERT INTO verses VALUES (22583, 31, 1, 4, 'se תַּגְבִּ֣יהָ כַּנּוֹשֶׁר e-se entre estrelas foi-posto seu-cinto daí seu-alcance oráculo-de yhwh');
INSERT INTO verses VALUES (22584, 31, 1, 5, 'se ganhos-ladrões virão para-ti se destruidores noite como vossa-ruína não roubarão para-ti se de-mal vieram para-ti acaso-nao brilharão injustiças:');
INSERT INTO verses VALUES (22585, 31, 1, 6, 'como [נֶחְפְּשׂ֣וּ] Esaú [נִבְע֖וּ] [מַצְפֻּנָֽיו]');
INSERT INTO verses VALUES (22586, 31, 1, 7, 'até הַגְּב֣וּל שִׁלְּח֗וּךָ todo homens-de בְרִיתֶ֔ךָ הִשִּׁיא֛וּךָ a-ti para-ti homens-de שְׁלֹמֶ֑ךָ לַחְמְךָ֗ yasum מָזוֹר֙ tachatcha não tevuna em-ele');
INSERT INTO verses VALUES (22587, 31, 1, 8, 'acaso-nao no-dia o-aquele oráculo-de yhwh vehabadti sábios me''edom e-entendimento me-ha-mar euveus:');
INSERT INTO verses VALUES (22588, 31, 1, 9, 'vechata giborecha teiman para-propósito-de yikarat- homem me-ha-mar Esaú mikatel:');
INSERT INTO verses VALUES (22589, 31, 1, 10, 'mechamas seu-irmão Jacó cobrir-te-ás vergonha e-será-cortado para-eternidade');
INSERT INTO verses VALUES (22590, 31, 1, 11, 'em-dia-de seu-poder em-frente em-dia-de sábios זָרִ֖ים seu-exército e-negros vieram e-sobre Jerusalém eles tirarem sorteio também tu como-um-de de-eles');
INSERT INTO verses VALUES (22591, 31, 1, 12, 'e-a [בְיוֹם־אָחִ֙יךָ֙] [בְּי֣וֹם] irmão-teu em-dia-de [לִבְנֵֽי] e-a [בְּי֣וֹם] [אָבְדָ֑ם] יְהוּדָה em-dia-de [בְּי֥וֹם] e-a em-dia angústia');
INSERT INTO verses VALUES (22592, 31, 1, 13, 'a [בְשַֽׁעַר־עַמִּי֙] em-porta-de meu-povo em-dia-de [גַם־אַתָּ֛ה] a [בְּי֣וֹם] também tu [בְחֵיל֖וֹ] em-dia-de [אֵידֽוֹ] e-a em-dia');
INSERT INTO verses VALUES (22593, 31, 1, 14, 'e-a [עַל־הַפֶּ֔רֶק] sobre [אֶת־פְּלִיטָ֑יו] [וְאַל־תַּסְגֵּ֥ר] a [בְּי֥וֹם] e-a em-dia angústia');
INSERT INTO verses VALUES (22594, 31, 1, 15, 'porque próximo [עַל־כָּל־הַגּוֹיִ֑ם] yhwh sobre todo as-nações como-que tu-fizeste [בְּרֹאשֶֽׁךָ] para-ti');
INSERT INTO verses VALUES (22595, 31, 1, 16, 'que [כַּֽאֲשֶׁ֤ר] [שְׁתִיתֶם֙] sobre monte-de [יִשְׁתּ֥וּ] [כָֽל־הַגּוֹיִ֖ם] todo as-nações [וְלָע֔וּ] e-sejam [כְּל֥וֹא] e-serão');
INSERT INTO verses VALUES (22596, 31, 1, 17, '[וּבְהַ֥ר] [צִיּ֛וֹן] será [פְלֵיטָ֖ה] [וְהָ֣יָה] santidade [וְיָֽרְשׁוּ֙] casa Jacó את [מוֹרָֽשֵׁיהֶם]');
INSERT INTO verses VALUES (22597, 31, 1, 18, 'e-será casa-de Jacó Fogo ובית José להבה וּבֵ֤ית Esaú לקשׁ והדלכוּ neles ואכלוּם e-não será שריד֙ que yhwh porque yhwh palavra');
INSERT INTO verses VALUES (22598, 31, 1, 19, 'וירשוּ o Negue a monte-de Esaú e a Shefala a filisteus e Jerusalém a campo- Efraim e-a campo- Samaria e Benjamim a o-Gileade');
INSERT INTO verses VALUES (22599, 31, 1, 20, 'e Galut o Chel- o Zeh para-os-filhos-de Israel que Canaanitas até Tzarat e Galut Jerusalém que em Bisfarad ירשו את cidades-de הַנֶּֽגֶב');
INSERT INTO verses VALUES (22600, 31, 1, 21, '[וְעָל֤וּ] [מֽוֹשִׁעִים֙] em-monte-de Sião [לִשְׁפֹּ֖ט] a monte-de Esaú e-será a-yhwh o-reino');
INSERT INTO books VALUES (32, 'JON', 'Jonas', 'AT', 4);
INSERT INTO chapters VALUES (891, 32, 1, 16);
INSERT INTO verses VALUES (22601, 32, 1, 1, 'e-houve palavra-de yhwh a dizendo filho-de para-dizer');
INSERT INTO verses VALUES (22602, 32, 1, 2, 'levantou לך a נינוה a-cidade a-grande וקרא sobre-ela porque subiu suas maldades para-meu');
INSERT INTO verses VALUES (22603, 32, 1, 3, 'E-levantou יונה לברך תרשיה de-diante-de yhwh e-descer יפוא WAYYIMTZAA אניה בָּאָ֗ה תַרְשִׁ֗ישׁ E-deu E-colocou e-ele-descerrou nela #adventar עִמָּהֶם֙ תַּרְשִׁ֔ישָׁה de-diante-de yhwh');
INSERT INTO verses VALUES (22604, 32, 1, 4, '[וַֽיהוָ֗ה] [הֵטִ֤יל] espírito-de [אֶל־הַיָּ֔ם] e-houve o-mar E-foi [וְהָ֣אֳנִיָּ֔ה] grande [לְהִשָּׁבֵֽר]');
INSERT INTO verses VALUES (22605, 32, 1, 5, 'vayir''e''u הַמַּלָּחִ֗ים e gritaram homem a Elohim dele e lançaram a as ferramentas que na nau a o-mar para se jazer de cima deles e Jóvão desceu a as escadas a-sfinah e-deitou-se e-eradam:');
INSERT INTO verses VALUES (22606, 32, 1, 6, 'vayiqra a-ele muito ha-chovel E-disse a-ele que- para-ti nardam levantou chamou a Elohim-teu ulay yita''ashet o-Elohim para-nós e-não noebad:');
INSERT INTO verses VALUES (22607, 32, 1, 7, 'e-eles-disseram homem a companheiro-seu vão-vocês venafila goralot e-nedáah בְּשֶׁלְּמִ֛י a-maldade a-esta para-nós vayaffilú gorálot e-caiu hagorál sobre Yoán:');
INSERT INTO verses VALUES (22608, 32, 1, 8, 'e-disseram a-ele hágidá: agora para-nós ba''asher para-quem- a-maldade a-esta para-nós que- melakhtaká úme''ayín תבוא que a-tzé-kha וְאֵֽי־ mizze povo tu');
INSERT INTO verses VALUES (22609, 32, 1, 9, 'E-disse a-eles i-vri eu e-a yhwh Elohim-de os-céus temer temia que fez a o-mar e-a há-yá-ba-shá-ha:');
INSERT INTO verses VALUES (22610, 32, 1, 10, 'vay-ri-khu os-homens yé-ra-á grande e-disseram a-ele que- isto fizeste porque ya-da-khu yhwh ele mil-lif-nei que declarou a-eles porque disse para-eles');
INSERT INTO verses VALUES (22611, 32, 1, 11, 'e-disseram a-ele que- na-ă-shé-ha para-ti o-mar o-mar que o-mar o-mar הלך vés-o-ré:');
INSERT INTO verses VALUES (22612, 32, 1, 12, 'E-disse a-eles Sejam-me-elevados e lançaram-me a o-mar o-mar o-mar que porque sabe que porque no-meu-entendimento o-tormento o grande este sobre-vós');
INSERT INTO verses VALUES (22613, 32, 1, 13, 'e-eles-suspiraram os-homens para-devolver a a-terra e-não que o-mar o-mar הלך e-a-nuvem sobre-eles');
INSERT INTO verses VALUES (22614, 32, 1, 14, 'e-eles-chamaram a yhwh e-disseram yhwh yhwh a por-favor נוֹאֲבַדְתֶּן בְּנֶ֙פֶשׁ֙ o-homem esta e-a dareis sobre nós yhwh נָקִי porque tu yhwh como-que חָפַץ tu');
INSERT INTO verses VALUES (22615, 32, 1, 15, 'e-levantaram a Jonas וַיְטִלוּהוּ a o-mar e-estabeleceu o-mar מִזַּעְפּוֹ');
INSERT INTO verses VALUES (22616, 32, 1, 16, 'וַיִּירְאוּ os-homens יִרְאָה grande a yhwh וַיִּזְבְּחוּ oferta para-יהוה וַיִּדְרּוּ nédarim∶');
INSERT INTO chapters VALUES (892, 32, 2, 11);
INSERT INTO verses VALUES (22617, 32, 2, 1, 'e man· yhwh peixe grande para engolir· a e-houve E-foi Joná· nos intestinos· do peixe· três dias e três· noites∶');
INSERT INTO verses VALUES (22618, 32, 2, 2, 'e orou· Jonas a yhwh Elohim-dele dos intestinos· a-pesca׃');
INSERT INTO verses VALUES (22619, 32, 2, 3, 'E-disse eu-chamei da-miséria para-mim a yhwh וַֽיַּעֲנֵ֑נִי do-ventre de-tormento שִׁוּ֖עְתִּי ouviste קוֹלִֽי׃');
INSERT INTO verses VALUES (22620, 32, 2, 4, 'e-ele-jo-ga-me de-punhalada no-coração mares e-um-réu me-rodeava todo מִשׁוֹבְרֶךָ וְגַלֵּךָ sobre-mim עָבְרוּ׃');
INSERT INTO verses VALUES (22621, 32, 2, 5, 'e-eu eu-disse [נִגְרַ֖שְׁתִּי] desde-em-frente-de [עֵינֶ֑יךָ] somente [אוֹסִ֣יף] [לְהַבִּ֔יט] a [קָדְשֶֽׁךָ]');
INSERT INTO verses VALUES (22622, 32, 2, 6, '[אֲפָפ֤וּנִי] águas até alma [יְסֹבְבֵ֑נִי] [ס֖וּף] [חָב֥וּשׁ] [לְרֹאשִֽׁי]');
INSERT INTO verses VALUES (22623, 32, 2, 7, 'לְקִצְבֵ֤י montes יָרַ֔דְתִּי a-terra בְּרִחֶ֥יהָ בַעֲדִ֖י para-sempre e-ela-subiu מִשַׁ֛חַת חַיַּ֖י yhwh Elohim-meu');
INSERT INTO verses VALUES (22624, 32, 2, 8, '[בְּהִתְעַטֵּ֤ף] sobre-mim [נַפְשִׁ֔י] a yhwh [וַתָּב֤וֹא] [אֵלֶ֙יךָ֙] a-ti [אֶל־הֵיכַ֖ל] a');
INSERT INTO verses VALUES (22625, 32, 2, 9, '[מְשַׁמְּרִ֖ים] [הַבְלֵי־שָׁ֑וְא] [חַסְדָּ֖ם] [יַעֲזֹֽבוּ]');
INSERT INTO verses VALUES (22626, 32, 2, 10, 'e-eu [בְּק֤וֹל] [תּוֹדָה֙] [אֶזְבְּחָה־לָּ֔ךְ] para-ti que [אֲשַׁלֵּ֑מָה] [יְשׁוּעָ֖תָה] [לַיהוָֽה׃] para-יהוה');
INSERT INTO verses VALUES (22627, 32, 2, 11, 'E-disse yhwh [לַדָּ֑ג] [וַיָּקֵ֥א] a pomba a');
INSERT INTO chapters VALUES (893, 32, 3, 10);
INSERT INTO verses VALUES (22628, 32, 3, 1, 'e-houve palavra-de yhwh a dizendo para-dizer');
INSERT INTO verses VALUES (22629, 32, 3, 2, 'levantou vai a נינוה a-cidade o-grande VUKERA'' para-ela a eu que eu palavra para-ti');
INSERT INTO verses VALUES (22630, 32, 3, 3, 'E-levantou יונה E-andou a conforme-a-palavra-de yhwh VNINVEH era עיר- g''dolah para-Elohim MALAKH três dias');
INSERT INTO verses VALUES (22631, 32, 3, 4, 'e começou יונא para-vir na cidade andar dia um E-chamou E-disse ainda quarenta dia e Ninive foi arrebatada');
INSERT INTO verses VALUES (22632, 32, 3, 5, 'e creram homens-de Ninive em Elohim e-ele-chamou- צוֹם֙ e vestiram-se sacos deles e-até que eles');
INSERT INTO verses VALUES (22633, 32, 3, 6, 'וַיִּגַּ֤ע a-palavra a rei Nínive E-levantou de seu trono e passou adornou-o dele cobriu-se saco e-habitou sobre הָאֵֽפֶר׃');
INSERT INTO verses VALUES (22634, 32, 3, 7, 'e clamou E-disse a Nínive por causa de o-rei e seus grandes dizendo o-homem e-o-animal o gado e a ovelha a comerão que-feito a pastarão não a beberão');
INSERT INTO verses VALUES (22635, 32, 3, 8, 'e cobrirão olhos o-homem והבהמה e clamaram a Elohim com força e voltarão homem de-seu-caminho a má e-de o furor que em suas mãos:');
INSERT INTO verses VALUES (22636, 32, 3, 9, 'quem- que conhece יָשׁ֔וּב e consolou o-Elohim e voltou de ardor sua-ira e-não nós morreremos:');
INSERT INTO verses VALUES (22637, 32, 3, 10, 'E-viu הָֽאֱלֹהִים את- seus feitos porque voltaram em seus caminhos a-maldade e-lamentou os-Elohim sobre הָרָעָה que palavra לַעֲשׂוֹת־ a-eles e-não fez');
INSERT INTO chapters VALUES (894, 32, 4, 11);
INSERT INTO verses VALUES (22638, 32, 4, 1, 'e-foi-mal a pomba mal grande a-ele a-ele');
INSERT INTO verses VALUES (22639, 32, 4, 2, '[וַיִּתְפַּלֵּ֨ל] a yhwh E-disse yhwh yhwh porventura-não este [עַל־אַדְמָתִ֔י] até [קִדַּ֖מְתִּי] sobre [תַּרְשִׁ֑ישָׁה] que assim que tu [אֵֽל־חַנּ֣וּן] porque [אֶ֤רֶךְ] porque tu a [עַל־הָרָעָֽה] bondade sobre');
INSERT INTO verses VALUES (22640, 32, 4, 3, 'e-agora yhwh toma agora a que bom porque bom');
INSERT INTO verses VALUES (22641, 32, 4, 4, 'E-disse yhwh o-que-alimenta ardeu para-ti');
INSERT INTO verses VALUES (22642, 32, 4, 5, 'e-saiu joná: de a-cidade ao-oriente do-leste para-a-cidade a-ele a-ele nome sussa: e-habitou su-ba-a: até até que ver-irá: que- ser-irá: em-cidade:');
INSERT INTO verses VALUES (22643, 32, 4, 6, 'e-ele-preparou: yhwh Elohim cicávio: e subiu de-cima-de a joná para-ser sombra sobre cabeça-sua a-ele para-ele de ruim dele e alegrou-se joná sobre o gafanhoto שִׂמְחָ֥ה g''dolah');
INSERT INTO verses VALUES (22644, 32, 4, 7, 'e fez הָֽאֱלֹהִים verme em subida הַשַׁ֖חַר para o dia seguinte e cobriu-se a o quicão e secou-se');
INSERT INTO verses VALUES (22645, 32, 4, 8, 'e-houve kîzrōach o sol e se tornou Elohim espírito espírito crespo e cobriu-se o-sol sobre cabeça pomba e secou-se e-ele-perguntou a a sua alma E-disse bom bom minha morte de minha vida');
INSERT INTO verses VALUES (22646, 32, 4, 9, 'E-disse Elohim a [הַהֵיטֵ֥ב] [חָרָֽה־לְךָ֖] [עַל־הַקִּֽיקָי֑וֹן] E-disse sobre [חָֽרָה־לִ֖י] E-disse para-mim até');
INSERT INTO verses VALUES (22647, 32, 4, 10, 'E-disse yhwh tu [חַ֙סְתָּ֙] sobre [אֲשֶׁ֛ר] que não [וְלֹ֣א] nele e-não ser [וּבִן־לַ֥יְלָה] noite foi noite');
INSERT INTO verses VALUES (22648, 32, 4, 11, '[וַֽאֲנִי֙] não [אָח֔וּס] sobre [הָעִ֣יר] a-cidade o-grande que há [מִֽשְׁתֵּים־עֶשְׂרֵ֨ה] [רִבּ֜וֹ] homem dez [לֹֽא־יָדַע֙] homem que não conheceu entre multiplicai');
INSERT INTO books VALUES (33, 'MIC', 'Miquéias', 'AT', 7);
INSERT INTO chapters VALUES (895, 33, 1, 16);
INSERT INTO verses VALUES (22649, 33, 1, 1, 'palavra-de יהוה que ser a מיכא o morash''ti בִּימֵ֥י Yoțam Acaz Yeḥizqiyāh reis-de Judá que Hāzā sobre שרֹן Ve-Irūšālām׃');
INSERT INTO verses VALUES (22650, 33, 1, 2, 'Šimʿū povos Kullam הקשבי terra U-melōāh e-seja Adonai yhwh Bāḵem Ləʿēd Adonai Mehiḵāl Sua santidade:');
INSERT INTO verses VALUES (22651, 33, 1, 3, 'porque yhwh sai saindo de Seu lugar: e descerá e passará por sobre terra');
INSERT INTO verses VALUES (22652, 33, 1, 4, 'e tocarão os-montes em-lugar-dele e os abismos terão penetrado como um dragão de-diante-de o-fogo כְּמַ֖יִם serão envergonhados em Morá:');
INSERT INTO verses VALUES (22653, 33, 1, 5, 'por causa do pecado Jacó todo isto e nos seus sacrifícios casa Israel quem- pecado Jacó não-verdade Samaria e-quem בָּמ֣וֹת Judá acaso-nao Jerusalém');
INSERT INTO verses VALUES (22654, 33, 1, 6, 'e-eu-postarei Samaria para a montanha o-campo para os seus pinheiros vinha e habitarei na sua escuridão em suas pedras ויסודה אגל');
INSERT INTO verses VALUES (22655, 33, 1, 7, 'e-todo [יֻכַּ֗תּוּ] [וְכָל־אֶתְנַנֶּ֙יהָ֙] e-todo [בָאֵ֔שׁ] [וְכָל־עֲצַבֶּ֖יהָ] [אָשִׂ֣ים] e-todo que [מֵאֶתְנַ֤ן] [זוֹנָה֙] porque [וְעַד־אֶתְנַ֥ן] [זוֹנָ֖ה] [יָשֽׁוּבוּ] e-até');
INSERT INTO verses VALUES (22656, 33, 1, 8, 'sobre esta אספדה ואילילה אילכה ועROOM farei מספד כタンים ואבל כּ-בְנוֹת יאנה׃');
INSERT INTO verses VALUES (22657, 33, 1, 9, 'que [אֲנוּשָׁ֖ה] [מַכּוֹתֶ֑יהָ] porque [עַד־יְהוּדָ֔ה] tocar Judá [עַמִּ֖י] até portão-de povo-meu até');
INSERT INTO verses VALUES (22658, 33, 1, 10, '[בְּגַת֙] a [בָּכ֖וֹ] [אַל־תִּבְכּ֑וּ] a [לְעַפְרָ֔ה] pó [*התפלשתי] pó');
INSERT INTO verses VALUES (22659, 33, 1, 11, '[עִבְרִ֥י] a-vós [יוֹשֶׁ֥בֶת] [שָׁפִ֖יר] [עֶרְיָה־בֹ֑שֶׁת] não não [יוֹשֶׁ֣בֶת] sentada [מִסְפַּד֙] [בֵּ֣ית] casa [יִקַּ֥ח] ele-tomará [עֶמְדָּתֽוֹ]');
INSERT INTO verses VALUES (22660, 33, 1, 12, 'porque [לְט֖וֹב] para-bom sentada [כִּֽי־יָ֤רַד] mal [מֵאֵ֣ת] yhwh de-junto-de yhwh');
INSERT INTO verses VALUES (22661, 33, 1, 13, 'רְתֹ֧ם a-carroça לָרֶ֖כֶשׁ sentada לָכִ֑ישׁ רֵאשִׁ֨ית chéttā''ath ela para-filha-de Sião porque em-te נמצאו pisse''ey Israel');
INSERT INTO verses VALUES (22662, 33, 1, 14, 'portanto tittənī shillūakh sobre mōresheth gā''ath em-as Akziv lə''akzāb para-reis-de Israel');
INSERT INTO verses VALUES (22663, 33, 1, 15, 'até hayyōrēsh אבי para-ti josébet māreshāh até ʿădullāham virá glória Israel');
INSERT INTO verses VALUES (22664, 33, 1, 16, '[קָרְחִ֣י] [וָגֹ֔זִּי] sobre filhos-de [הַרְחִ֤בִי] [קָרְחָתֵךְ֙] [כַּנֶּ֔שֶׁר] que porque [מִמֵּֽךְ׃]');
INSERT INTO chapters VALUES (896, 33, 2, 13);
INSERT INTO verses VALUES (22665, 33, 2, 1, '[ה֧וֹי] [חֹֽשְׁבֵי־אָ֛וֶן] [וּפֹ֥עֲלֵי] mal mau sobre [הַבֹּ֙קֶר֙] [יַעֲשׂ֔וּהָ] que [יֶשׁ־לְאֵ֖ל] porque há');
INSERT INTO verses VALUES (22666, 33, 2, 2, '[וְחָמְד֤וּ] [שָׂדוֹת֙] [וְגָזָ֔לוּ] [וּבָתִּ֖ים] [וְנָשָׂ֑אוּ] [וְעָֽשְׁקוּ֙] [גֶּ֣בֶר] [וּבֵית֔וֹ] e-homem [וְנַחֲלָתֽוֹ׃]');
INSERT INTO verses VALUES (22667, 33, 2, 3, 'portanto assim disse yhwh eis-me contador sobre a-misfachá a-esta maldade que não tamišu de-lá tzavvārōteḵem e-não que romá porque tempo maldade ela');
INSERT INTO verses VALUES (22668, 33, 2, 4, 'no-dia o-aquele yissa alēḵem mashál vénaḥá nehí נִֽהְיָה֙ disse שָׁד֣וֹד נְשַׁדֻּ֔נוּ porção povo-meu יָמִ֑יר como יָמִ֣ישׁ para-mim לְשׁוֹבֵ֥ב שָׂדֵ֖ינוּ יְחַלֵּֽק׃');
INSERT INTO verses VALUES (22669, 33, 2, 5, 'portanto não a-ti para-ti מַשְׁלִ֥יךְ por herança בְּגוֹרָ֑ל yhwh yhwh');
INSERT INTO verses VALUES (22670, 33, 2, 6, 'a [יַטִּיפ֑וּן] [לֹֽא־יַטִּ֣פוּ] não não [יִסַּ֖ג] não');
INSERT INTO verses VALUES (22671, 33, 2, 7, '[הֶאָמ֣וּר] casa-de Jacó espírito yhwh yhwh se estes [דְבָרַי֙] não [עִ֖ם] [הַיָּשָׁ֥ר] povo');
INSERT INTO verses VALUES (22672, 33, 2, 8, '[וְאֶתְמ֗וּל] meu-povo [לְאוֹיֵ֣ב] [יְקוֹמֵ֔ם] [מִמּ֣וּל] [שַׂלְמָ֔ה] [אֶ֖דֶר] [תַּפְשִׁט֑וּן] [מֵעֹבְרִ֣ים] [בֶּ֔טַח] [שׁוּבֵ֖י] guerra');
INSERT INTO verses VALUES (22673, 33, 2, 9, '[נְשֵׁ֤י] meu-povo [תְּגָ֣רְשׁ֔וּן] [מִבֵּ֖ית] [תַּֽעֲנֻגֶ֑יהָ] de-cima-de [עֹֽלָלֶ֔יהָ] [תִּקְח֥וּ] [הֲדָרִ֖י] para-eternidade');
INSERT INTO verses VALUES (22674, 33, 2, 10, 'levantai-vos וּלְכ֔וּ que não esta הַמְּנוּחָ֑ה por-causa-de טָמְאָ֛ה תְּחַבֵּ֖ל וְחֶ֥בֶל נִמְרָֽץ׃');
INSERT INTO verses VALUES (22675, 33, 2, 11, 'se homem espírito espírito וָשֶׁ֣קֶר כִּזֵּ֔ב a-ti para-ti para-a-licor e-para-o-salário e-acontecerá espalha o-povo a-esta');
INSERT INTO verses VALUES (22676, 33, 2, 12, 'reúno e-reúne Jacó tudo-você reúno e-reúne remanescente Israel יחד e-poso-o-lá como-ovelhas בּצְרָה כּעֵדר no-meio-de הַדּוֹבְר֔וֹ תּהִימֶנָה מֵאָדָם׃');
INSERT INTO verses VALUES (22677, 33, 2, 13, 'subir הַפּוֹרֵץ֙ em-frente-de-eles פּוֹרְצוּ֙ וַיַעֲבֹ֔רוּ porta-de וַיֵצְאוּ nele e-ele-passou מַלְכּוֹם֙ em-frente-de-eles וַיהוָ֖ה em-o-cabeça-deles-verso-final');
INSERT INTO chapters VALUES (897, 33, 3, 12);
INSERT INTO verses VALUES (22678, 33, 3, 1, 'e-disse ouvi por-favor cabeças-de Jacó [בֵּ֣ית] casa Israel a-vós para-conhecer [אֶת־הַמִּשְׁפָּֽט] a');
INSERT INTO verses VALUES (22679, 33, 3, 2, 'שֹׂ֥נְאֵי bom וְאֹ֣הֲבֵי גֹּזְלֵ֤י sua pele מֵעֲלֵיהֶם וּשְׁאֵרָ֖ם de-sobre עַצְמוֹתָֽם׃');
INSERT INTO verses VALUES (22680, 33, 3, 3, 'e-que אָכְלוּ֮ שְׁאֵ֣ר povo-meu וְעוֹרָם֙ de-lhes se-espalharam e-a suas-corporações abriram-se e-estenderam como-que em-circunferência no-meio-de em-meio-de frágil:');
INSERT INTO verses VALUES (22681, 33, 3, 4, 'então chamarão a yhwh e-não responderá eles e-esconderá suas-faces deles em-o-tempo aquela como-que se-divertiram seus-pecados');
INSERT INTO verses VALUES (22682, 33, 3, 5, 'assim disse yhwh sobre os-profetas os-perversos a meu-povo os-malfeitos em-suas-bocas e chamem paz e que não dará sobre a-seu-boca e-sanctifiquem sobre-ele guerra');
INSERT INTO verses VALUES (22683, 33, 3, 6, 'portanto noite a-vós de-sonho e-escuridão a-vós de-cobertura e venha o-sol sobre os-profetas e se encolham o-dia o-dia');
INSERT INTO verses VALUES (22684, 33, 3, 7, 'e vergem-se os que vêem e escavem os que profetizam e se exaltarem sobre seus lábios que porque não resposta Elohim');
INSERT INTO verses VALUES (22685, 33, 3, 8, 'e-entretanto eu eu preenchi força a yhwh yhwh וּמִשָׁ֖פֵט e-poder para-declarar לְיַֽעֲקֹב֙ פִּשְׁע֔וֹ e para Israel seu pecado');
INSERT INTO verses VALUES (22686, 33, 3, 9, 'ouvi esta [רָאשֵׁי֙] [בֵּ֣ית] casa Jacó [בֵּ֣ית] casa Israel [מִשְׁפָּ֔ט] e-[OBJ] e-a todo');
INSERT INTO verses VALUES (22687, 33, 3, 10, 'בֹּנֶ֥ה Sião בְּדָמִ֑ים Jerusalém em-Abel:');
INSERT INTO verses VALUES (22688, 33, 3, 11, 'seus-cabeças em-corrupção julgariam e-seus-sacerdotes em-preço ensinarão e-seus-prophetas em prata acordariam e-sobre yhwh נְשַׁעֵ֣נוּ dizendo não yhwh בְּקִרְבֵּ֔נוּ não viras sobre nós mal');
INSERT INTO verses VALUES (22689, 33, 3, 12, 'portanto בִּגְלַלְכֶ֔ם Sião שָׂדֶ֣ה תֵֽחָרֵ֑שׁ וִירוּשָׁלִַ֙ם֙ עִיִּ֣ין תִּֽהְיֶ֔ה וְהַ֥ר a-casa לְבָמ֥וֹת YE''AR:');
INSERT INTO chapters VALUES (898, 33, 4, 14);
INSERT INTO verses VALUES (22690, 33, 4, 1, 'e-era em-último הַיָּמִים irá será casa-de yhwh nakhon na-cabeça HEH-HARIM VE-NISSA'' ele MIGVAVOT VENAHARU sobre-ele povos:');
INSERT INTO verses VALUES (22691, 33, 4, 2, 'VE-HALCU nações muitos va''amru LECU ⚠ e-nos-calhemos a monte-de yhwh e-a casa Elohim-de Jacó e ensine-nos MIDRACAV que BE''ORCHOTAV porque מִצִיּוֹן תֵּצֵ֣א תּוֹרָה e-palavra-de yhwh מִירוּשָׁלָֽ͏ִם׃');
INSERT INTO verses VALUES (22692, 33, 4, 3, 'וְשָׁפַט entre povos muitos וְהוֹכִ֛יחַ לְגוֹיִ֥ים fortes até רָח֑וֹק וְכִתְּת֨וּ חַרְבֹתֵיהֶ֜ם לְאִתִּ֗ים e suas tendas para as tocadoras de harpa não e levantarão espada a nação espada e-não e ensinarão mais guerra');
INSERT INTO verses VALUES (22693, 33, 4, 4, 'e habitareis homem debaixo gafnão e-baixo sua figueira e-não מַחֲרִ֑יד porque yhwh yhwh de-exércitos palavra');
INSERT INTO verses VALUES (22694, 33, 4, 5, 'que todo os-povos andarão homem em-nome-de Elohim-dele וַאֲנַ֗חְנוּ e caminharemos em-o-nome-de yhwh Elohim-nosso para-sempre para-sempre');
INSERT INTO verses VALUES (22695, 33, 4, 6, 'no-dia o-aquele oráculo-de yhwh e recolheremos a que amassa e a renegada eu recolherei e que eu destruirei');
INSERT INTO verses VALUES (22696, 33, 4, 7, 'e eu estabelecerei a a que se deita para sobrevivente e a que se levanta para-povo grande yhwh yhwh sobre-eles em-monte-de Sião desde agora e-até eternidade');
INSERT INTO verses VALUES (22697, 33, 4, 8, 'e-tu torre- Eder עֹפֶל filha-de Sião Adêikha Téateh Uváah Hamemshala Harishonah Mamleket Lebat Jerusalém');
INSERT INTO verses VALUES (22698, 33, 4, 9, 'agora por-que Taríui mau המלך não há em-te se יוועצך אבד porque החזיקך tremeluzimos como-que-nascemos:');
INSERT INTO verses VALUES (22699, 33, 4, 10, 'חוליתי וגOCIHI filha-de Sião כיילודא porque עתה Saí de-cria e-habitarei basadeh e-virás até Babilônia nome yhwh nome salve-te yhwh da-mão os teus inimigos');
INSERT INTO verses VALUES (22700, 33, 4, 11, 'e-agora se-gatherem sobre-ti nações muitos aqueles que dizem enganar-te-ão וְתַ֥חַז בְּצִיּ֖וֹן nosso olhos:');
INSERT INTO verses VALUES (22701, 33, 4, 12, 'e-elas não conheceram [מַחְשְׁב֣וֹת] yhwh e-não [הֵבִ֖ינוּ] [עֲצָת֑וֹ] que [קִבְּצָ֖ם] [כֶּעָמִ֥יר] [גֹּֽרְנָה]');
INSERT INTO verses VALUES (22702, 33, 4, 13, 'ק֧וּמִי וָד֣וֹשִׁי filha-de Siao porque as-cornos אָשִׂ֤ים barzel e as parsothayik ás ashim nichusha e havidakot povos muitos e hacharamti para-יהוה betsuam e chilam para adon todo a-terra');
INSERT INTO verses VALUES (22703, 33, 4, 14, 'agora tittig''dodi filha-de guddud מָצ֖וֹר nome sobre-nós בַּשֵׁ֙בֶט֙ יַכּ֣וּ sobre הַלְּחִ֔י את julgando Israel');
INSERT INTO chapters VALUES (899, 33, 5, 14);
INSERT INTO verses VALUES (22704, 33, 5, 1, 'e-tu casa-de pão אֶפְרָ֗תָה צָעִיר֙ לִֽהְיוֹת֙ בְּאַלְפֵ֣י Judá de-tu a-mim וַיֵּצֵ֔א para-ser moshel em-Israel ao-oriente מִקֶּ֖דֶם eternidade eternidade');
INSERT INTO verses VALUES (22705, 33, 5, 2, 'por-isso irá-lhes até tempo trará-a deu-a-luz e restante seus-irmãos ye-shubun sobre filhos-de Israel');
INSERT INTO verses VALUES (22706, 33, 5, 3, 'e ficou-se e ruí em força yhwh בִּגְא֕וֹן nome yhwh Elohim-dele e habitaram-se porque agora será exaltado até extremidades-de terra');
INSERT INTO verses VALUES (22707, 33, 5, 4, 'e-acontecerá este paz Assíria porque vira em-nossa e-que tocará em-nossas e-elevaremos-nos sobre-ele sete pastores e-sete príncipes homem');
INSERT INTO verses VALUES (22708, 33, 5, 5, 'e-ruas a terra Açãur pela espada e-a terra nemrod em-suas-aberturas e salve de Assuero porque vira em-nossa terra e-que percorra em nosso limite:');
INSERT INTO verses VALUES (22709, 33, 5, 6, 'e-era remanescente Jacó no meio de povos muitos como chuva de-junto-de yhwh yhwh sobre de herba que não que germe para-homem e-não e floresça homem homem');
INSERT INTO verses VALUES (22710, 33, 5, 7, 'e-será שֶׁאֱרִיָּה Jacó בַּגּוֹיִ֗ם בְּקֶ֙רֶב֙ povos muitos כְּאַרְיֵה בְּבַהֲמֹות יַעַר כִּכָּפֵר ovelhas- que עָבַר וְרָמַס וְטָרַף e-não-há מחסלי');
INSERT INTO verses VALUES (22711, 33, 5, 8, 'תָּרֹ֥ם tua-mao sobre צָרֶ֑יךָ e-todo teus-inimigos serão cortados:');
INSERT INTO verses VALUES (22712, 33, 5, 9, 'e-era [בַיּוֹם־הַהוּא֙] o-aquele oráculo-de yhwh [מִקִּרְבֶּ֑ךָ] [וְהַאֲבַדְתִּ֖י] [מַרְכְּבֹתֶֽיךָ]');
INSERT INTO verses VALUES (22713, 33, 5, 10, 'e cortarei cidades-de ארצך@ וְהָרַסְתִּ֖י todo de-te');
INSERT INTO verses VALUES (22714, 33, 5, 11, 'e cortarei cavernas dos-te e-tempos não serao para-ti');
INSERT INTO verses VALUES (22715, 33, 5, 12, 'e cortarei os-tus-pedras e-ossos-te dos-te-midst e-não vai-adorar mais a-trabalho as tuas mãos');
INSERT INTO verses VALUES (22716, 33, 5, 13, 'e deixei a tua alegria de ti e destruí as tuas cidades');
INSERT INTO verses VALUES (22717, 33, 5, 14, 'e farei com fúria e com ira vinganca a as-nações não não שְׁמַע׃');
INSERT INTO chapters VALUES (900, 33, 6, 16);
INSERT INTO verses VALUES (22718, 33, 6, 1, 'ouvi por favor a que yhwh disse levantou רִיב a as montanhas e ouvirá הַגְבָעֹות o teu grito');
INSERT INTO verses VALUES (22719, 33, 6, 2, 'ouvi montes a yhwh yhwh e os cedros fundamentos que porque רִיב para-יהוה com povo-seu e-com- Israel será julgada');
INSERT INTO verses VALUES (22720, 33, 6, 3, 'povo-meu que a-ti para-ti e que e verás Anê em-mim');
INSERT INTO verses VALUES (22721, 33, 6, 4, 'que e elevaste de-terra-de Egito e-de-casa servos pediti-te vashalach diante-de-ti a Moisés Aarão u-miryam');
INSERT INTO verses VALUES (22722, 33, 6, 5, 'עַמִּי lembra-de por-favor que- ya''atz balak rei ele u-me Anê a-ele בלעם filho-de conhecimento de yhwh até o-Gilgal lem''onen conhecimento tsidqot yhwh');
INSERT INTO verses VALUES (22723, 33, 6, 6, 'בַּמָּ֙ה֙ אֲקַדֵּ֣ם yhwh אִכַּ֖ף לֵאלֹהֵ֣י מָר֑וֹם הַאֲקַדְּמֶ֣נּוּ בְעוֹל֔וֹת em-carruagens filhos-de anos');
INSERT INTO verses VALUES (22724, 33, 6, 7, 'הֲיִרְצֶ֤ה yhwh בְּאַלְפֵ֣י as ovelhas בְּרִֽבְב֖וֹת נחלים- óleo האתן בכורי fruto פרי בטני chéttāth alma-de-mim');
INSERT INTO verses VALUES (22725, 33, 6, 8, 'declarou a-ti homem que- bom [דּוֹרֵ֣שׁ] yhwh que [אִם־עֲשׂ֤וֹת] porque se [חֶ֔סֶד] [וְהַצְנֵ֥עַ] [לֶ֖כֶת] bondade com');
INSERT INTO verses VALUES (22726, 33, 6, 9, 'voz yhwh lá-ʻir chamaria vé-tushiyá iráh o-teu-nome ouvi מַטֶּ֖ה e-quem yé-adá:');
INSERT INTO verses VALUES (22727, 33, 6, 10, 'ainda a-ʻiš casa perverso-o o-tsorot resha'' vé-eifat razon zé-ʻumá:');
INSERT INTO verses VALUES (22728, 33, 6, 11, 'a azcê בְּמֹ֣אזְנֵי resha'' úbicis pedras-de engano');
INSERT INTO verses VALUES (22729, 33, 6, 12, 'que asheirêhâ malêvu chamas véyoshbêhâ dibburû- falsidade úlêsônâm remiyyâ em-sua-boca:');
INSERT INTO verses VALUES (22730, 33, 6, 13, 'e-também eu tu-haleití o-kotéka o-shemé sobre o-chatótke:');
INSERT INTO verses VALUES (22731, 33, 6, 14, 'tu comerás e-não tishbá'' ve-yeshakhaká בְּקִרְבֶּ֑ךָ ve-taség e-não taplit e-que תּפלָט pela espada darei:');
INSERT INTO verses VALUES (22732, 33, 6, 15, 'tu sow e-não recolha tu pisaras zayit e-não be clothed óleo e be filled e-não beberas VINHO:');
INSERT INTO verses VALUES (22733, 33, 6, 16, 'e será guardado חֻקּוֹת עָמְרִי e-tudo obra-de casa-de Acabe e-vos בְּמֹֽעֲצוֹתָ֑ם a-fim-de תִּתִּ֨י אֹתְךָ֜ לְשַׁמָּ֗ה וְיֹשְׁבֶ֙יהָ֙ para-se-ráque וְחֶרְפַּ֥ת povo-meu תִּשָּֽׂאוּ׃');
INSERT INTO chapters VALUES (901, 33, 7, 20);
INSERT INTO verses VALUES (22734, 33, 7, 1, '[אַ֣לְלַי] para-mim que [הָיִ֙יתִי֙] [כְּאָסְפֵּי־קַ֔יִץ] [כְּעֹלְלֹ֖ת] [בָּצִ֑יר] [אֵין־אֶשְׁכּ֣וֹל] não-há [בִּכּוּרָ֖ה] [אִוְּתָ֥ה] [נַפְשִֽׁי]');
INSERT INTO verses VALUES (22735, 33, 7, 2, 'אבד חסיד de a-terra VASHAR em-o-homem AIYN todos-os LEDAMIM YEAAROVU homem a ACHIHU יָצ֥וּדוּ CHEREM');
INSERT INTO verses VALUES (22736, 33, 7, 3, 'sobre HARAH duas-mãos para-bem o-sar a-por e-o-julgador no-reembolso e-o-grande palavra העת ele ele e-adoraram-a:');
INSERT INTO verses VALUES (22737, 33, 7, 4, 'seu-bem como-direito ישׁר מִמסוכָה dia מְצַפֹּיךָ פּקֻדְתֶּךָ veio עַתָּ֥ה será מְבוּכָתָֽם׃');
INSERT INTO verses VALUES (22738, 33, 7, 5, 'a [בְרֵ֔עַ] [אַֽל־תִּבְטְח֖וּ] a [מִשֹּׁכֶ֣בֶת] [חֵיקֶ֔ךָ] [שְׁמֹ֖ר] seio-teu');
INSERT INTO verses VALUES (22739, 33, 7, 6, 'porque filho pai pai בַּת קָמָה בְּאִמָּֽהּ kalah בַּחֲמֹתָ֑הּ os teus inimigos homem homens-de seu lar:');
INSERT INTO verses VALUES (22740, 33, 7, 7, 'e-eu [בַּיהוָ֣ה] [אֲצַפֶּ֔ה] [אוֹחִ֖ילָה] [לֵאלֹהֵ֣י] Isei [יִשְׁמָעֵ֖נִי] Elohim-meu');
INSERT INTO verses VALUES (22741, 33, 7, 8, 'a fique alegre אֹיֵבְתִּי que porque נָפַלְתִּי קָמְתִּי porque yhwh luz yhwh luz para-mim');
INSERT INTO verses VALUES (22742, 33, 7, 9, 'זַעַף yhwh אֶשְׂאָ que eu-senhor-me-arrependi a-ele até que יָרֵיב רִיבִי e-fará מִשְׁפַּטִּי tire-me à-luz vejo-eu em-sua-justiça:');
INSERT INTO verses VALUES (22743, 33, 7, 10, 'e cobre meu inimigo e a vergonha de-a que diz a-mim ai yhwh Elohim meus-olhos que veja em-ela agora serás לְמִרְמָ֖ס כְּטִ֥יט חוּץ-וֹת׃');
INSERT INTO verses VALUES (22744, 33, 7, 11, 'dia [לִבְנ֣וֹת] [גְּדֵרָ֑יִךְ] dia o-aquele [יִרְחַק־חֹֽק]');
INSERT INTO verses VALUES (22745, 33, 7, 12, 'dia ele וְעָדֶ֣יךָ vira לְמִנּ֥י Assíria e-cidades-de מָצ֑וֹר לְמִנּ֥י מצור e-até נָהָר וְיָ֥ם águas וְהַ֥ר a-montanha');
INSERT INTO verses VALUES (22746, 33, 7, 13, 'e-será a-terra [לִשְׁמָמָ֖ה] sobre do-fruto-de [מַֽעַלְלֵיהֶֽם׃]');
INSERT INTO verses VALUES (22747, 33, 7, 14, 'רְעֵ֧ה teu-povo em-teu-tribo צֹ֚ן a tua herança meu-direito só floresta no-meio-de carmelo pastarão basã e-gileade כִּימֵ֥י eternidade');
INSERT INTO verses VALUES (22748, 33, 7, 15, 'כִּימֵ֥י sua-flor da-terra Egito e verão maravilhas');
INSERT INTO verses VALUES (22749, 33, 7, 16, 'verão nações e-terão-vergonha de-toda sua-félicitude הֵרִימוּ mão sobre פֶּה אֹזְנֵיהֶם תִּחֲרַשׁ');
INSERT INTO verses VALUES (22750, 33, 7, 17, 'יְלַחֵךְ pó כַּנּוֹחָשׁ כְּזוֹחֲלוֹ terra irgutz מִמִּסְגְּרֹתָיו a yhwh Elohim-nosso יִפַּחְדוּ e verão de-te');
INSERT INTO verses VALUES (22751, 33, 7, 18, 'quem El como-tu levante-se )(((עָוֺן֙))) e passar sobre pecado para a posteridade sua herança não tenha segurado para sempre ele porque desejava Hesed ela');
INSERT INTO verses VALUES (22752, 33, 7, 19, 'voltara nos tenha misericordiado יִכְבֹּ֖שׁ עֲוֺֽנֹתֵ֑ינוּ וְתַשָּׁׁלִ֛יךְ בִּמְצֻל֥וֹת mar todo חַטֹּאותָֽם׃');
INSERT INTO verses VALUES (22753, 33, 7, 20, 'תִּתֵּ֤ן verdade a Jacó Hesed le-abr-a-ham que נִשָּׁׂאֵ֥הוּ לַאֲבֹתֵ֖ינוּ oriente oriente');
INSERT INTO books VALUES (34, 'NAM', 'Naum', 'AT', 3);
INSERT INTO chapters VALUES (902, 34, 1, 14);
INSERT INTO verses VALUES (22754, 34, 1, 1, 'Massá [נִֽינְוֵ֑ה] [סֵ֧פֶר] [חֲז֛וֹן] [נַח֖וּם] [הָאֶלְקֹשִֽׁי]');
INSERT INTO verses VALUES (22755, 34, 1, 2, 'El [קַנּ֤וֹא] [וְנֹקֵם֙] yhwh [נֹקֵ֥ם] yhwh [וּבַ֣עַל] [חֵמָ֑ה] [נֹקֵ֤ם] yhwh [לְצָרָ֔יו] [וְנוֹטֵ֥ר] ele [לְאֹיְבָֽיו]');
INSERT INTO verses VALUES (22756, 34, 1, 3, 'yhwh אֶ֤רֶךְ אַפַּ֙יִם֙ כּוֹחַ וְנַקּוה não יְנַקֶה yhwh בְּסוּפָה וּבִשׂעָרָה דּרְכּוֹ e nuvem po de-seus-pés');
INSERT INTO verses VALUES (22757, 34, 1, 4, 'que faz chover na-mar e secou-o e-todo os rios destruiu queimado vermelho e vinha e flor לְבָנ֖וֹן אֻמְלָֽל׃');
INSERT INTO verses VALUES (22758, 34, 1, 5, 'montes רָעֲשׁ֣וּ nós וְהַגְּבָּע֖וֹת הִתְמֹגָ֑גוּ e levantou-se a-terra diante-dele וְתֵבֵ֖ל e-todo יֹ֥שְׁבֵי em-ela');
INSERT INTO verses VALUES (22759, 34, 1, 6, 'diante-de זַעְמוֹ֙ quem יַֽעֲמ֔וֹד e-quem יָק֖וּם בּחֲר֣וֹן sua-ira חֲמָתוֹ נִתְּכָ֣ה כָאֵ֔שׁ וְהַצֻּרִ֖ים נִתְּצ֥וּ nós');
INSERT INTO verses VALUES (22760, 34, 1, 7, 'bom yhwh [לְמָע֖וֹז] em-dia-de [צָרָ֑ה] e-conhecedor [חֹ֥סֵי] nele');
INSERT INTO verses VALUES (22761, 34, 1, 8, 'וּבְשֶׁ֣טֶף עֹבֵר plenamente fará מְקוֹמָהּ וְאֹיְבָיו יְרַדֶּף־ escuridão');
INSERT INTO verses VALUES (22762, 34, 1, 9, 'que- [אֶל־יְהוָ֔ה] a ele [עֹשֶׂ֑ה] ele fez não angústia');
INSERT INTO verses VALUES (22763, 34, 1, 10, 'que até [סְבֻכִ֔ים] [וּכְסָבְאָ֖ם] [סְבוּאִ֑ים] [אֻ֨כְּל֔וּ] [כְּקַ֥שׁ] [יָבֵ֖שׁ] [מָלֵֽא] enchei');
INSERT INTO verses VALUES (22764, 34, 1, 11, '[מִמֵּ֣ךְ] sair [חֹשֵׁ֥ב] sobre yhwh maldade [בְּלִיָּֽעַל׃]');
INSERT INTO verses VALUES (22765, 34, 1, 12, 'assim disse disse yhwh שְׁלוֹמִים֙ e-assim muitos e-assim נָגוּזּוּ וְעָבָר וְעִנִּיתִךְ não אֲעַנֶּךְ ainda');
INSERT INTO verses VALUES (22766, 34, 1, 13, 'e-agora [אֶשְׁבֹּ֥ר] [מֹטֵ֖הוּ] [מֵֽעָלָ֑יִךְ] [וּמוֹסְרֹתַ֖יִךְ] [אֲנַתֵּֽק]');
INSERT INTO verses VALUES (22767, 34, 1, 14, 'e ordenou sobre-ti yhwh não יִזְרַע מִשֶּׁמְךָ ainda de-a-casa Elohim-teu אַכְרִ֨ית פֶּ֧סֶל וּמַסֵּכָ֛ה acuso que porque קַלּֽוֹתָ׃');
INSERT INTO chapters VALUES (903, 34, 2, 14);
INSERT INTO verses VALUES (22768, 34, 2, 1, 'eis sobre הֶהָרִ֜ים pés-de מְבַשֵּׂר֙ מַשְׁמִ֣יעַ paz חָגִּ֧י יְהוּדָה חַגַּ֖יִךְ שַׁלְּמִ֣י que não não e também ainda em-te sem-al tod-a foi-cortado:');
INSERT INTO verses VALUES (22769, 34, 2, 2, 'subir do-dispersor sobre tu-rosto guardião prisão espera- caminho forte מָתְנַ֔יִם muito força muito');
INSERT INTO verses VALUES (22770, 34, 2, 3, 'que retornou yhwh a orgulho Jacó [יִשְׂרָאֵ֑ל] que porque [בֹּֽקְקִ֔ים] [וּזְמֹרֵיהֶ֖ם] [שִׁחֵֽתוּ]');
INSERT INTO verses VALUES (22771, 34, 2, 4, 'מָגֵ֨ן גִּבֹּרֵ֜יהוּ מְאָדָּ֗ם ANASH''E- חַ֙יִל֙ מְתֻלָּעִ֔ים em-a-ê-s f-la-dót hár-kheb em-dia-de há-ki-nô vá-hár-rosh-im hár-â-lû');
INSERT INTO verses VALUES (22772, 34, 2, 5, 'bá-khutzôth yi-tê-hol-lû o-carro yi-she-têt-kh-sh-qûn bá-rakhôvôt מרָאֵי-הֶן כַּלּוֹפְדִים כַּבְרָקִים יְרוֹץ-יוּ');
INSERT INTO verses VALUES (22773, 34, 2, 6, 'יִזְכֹּר֙ אַדִיר-יו יִכָּשְׁל֖וּ יְמַהֵרֻ חֹמֶת-הָ וְהֻכָּן o socó');
INSERT INTO verses VALUES (22774, 34, 2, 7, 'as portas os rios foram abertos e o templo foi formado');
INSERT INTO verses VALUES (22775, 34, 2, 8, 'e foi perfurado foi girada foi levantada e suas colunas מְנַֽהֲגוֹת֙ כְּק֣וֹל יוֹנִ֔ים מְתֹפְפֹ֖ת sobre לִבְבֵהֶֽן׃');
INSERT INTO verses VALUES (22776, 34, 2, 9, 'וְנִינְוֵ֥ה כִבְרֵֽכַת־ águas de-mais ela e-eles נָסִ֔ים עִמְד֥וּ עֲמֹ֖דוּ e-não-há מַפְנֶֽה׃');
INSERT INTO verses VALUES (22777, 34, 2, 10, 'בֹּ֥זּוּ prata בֹּ֣זּוּ ouro e-não-há קֵ֙צֶה֙ לַתְּכוּנָ֔ה כָּבֹ֕ד de-toda instrumento חֶמְדָּֽה׃');
INSERT INTO verses VALUES (22778, 34, 2, 11, 'בּוּקָ֥ה וּמְבוּקָ֖ה וּמְבֻלָּקָ֑ה e-lév ná-mes u-píq bír-káyim vá-chal-chálaha em-todo mátnayím וּפְנֵ֥י kól-lam qibbértzu pá-arár׃');
INSERT INTO verses VALUES (22779, 34, 2, 12, 'á-yéhah מְע֣וֹן arayot וּמִרְעֶ֥ה ele לַכְּפִרִ֑ים que andar אַרְיֵ֨ה לָבִ֥יא nome גּ֥וּר אַרְיֵ֖ה e-não-há מַחֲרִֽיד׃');
INSERT INTO verses VALUES (22780, 34, 2, 13, '[אַרְיֵ֤ה] [טֹרֵף֙] [בְּדֵ֣י] [גֹֽרוֹתָ֔יו] [וּמְחַנֵּ֖ק] [לְלִבְאֹתָ֑יו] [וַיְמַלֵּא־טֶ֣רֶף] [חֹרָ֔יו] [וּמְעֹֽנֹתָ֖יו] [טְרֵפָֽה]');
INSERT INTO verses VALUES (22781, 34, 2, 14, 'eis-me אֵלַ֗יִךְ oráculo-de yhwh exércitos e eu queimarei no ashan sua carruagem e seus leões comerás espada e eu cortarei da terra seu ventre e-não será ouvido voz voz seu anjo');
INSERT INTO chapters VALUES (904, 34, 3, 19);
INSERT INTO verses VALUES (22782, 34, 3, 1, 'ah! cidade דּוֹמִים כְּלֻלָּהּ כַּחַשׁ פְּרֵק מְלֻאָה não יַמִּישׁ טַרֵף׃');
INSERT INTO verses VALUES (22783, 34, 3, 2, 'voz [שׁ֔וֹט] [וְק֖וֹל] [רַ֣עַשׁ] [אוֹפָ֑ן] [וְס֣וּס] [דֹּהֵ֔ר] [וּמֶרְכָּבָ֖ה] [מְרַקֵּדָֽה]');
INSERT INTO verses VALUES (22784, 34, 3, 3, 'פָּרָ֣שׁ מַעֲלֶ֗ה וְלַ֤הַב espada וּבְרַ֣ק חֲנִ֔ית e abundância traspassado וְכֹ֣בֶד פָּ֑גֶר e-não-há קֵ֙צֶה֙ para-gviah em-gviyatam:');
INSERT INTO verses VALUES (22785, 34, 3, 4, 'por-mrov zunnay zonah tovat graça ba''alat kashafim hamokharet nações bazunneneihah u-mishpachot בִּכְשָׁפֶֽיהָ׃');
INSERT INTO verses VALUES (22786, 34, 3, 5, 'eis-me [אֵלַ֗יִךְ] oráculo-de yhwh exércitos [וְגִלֵּיתִ֥י] [שׁוּלַ֖יִךְ] sobre face-tua [גוֹיִם֙] [מַעְרֵ֔ךְ] [וּמַמְלָכ֖וֹת] [קְלוֹנֵֽךְ]');
INSERT INTO verses VALUES (22787, 34, 3, 6, 'וְהִשְׁלַכְתִּ֥י sobre-ti שִׁקֻּצִ֖ים e te nivvaltíkhe e te sámtikhe cróiy');
INSERT INTO verses VALUES (22788, 34, 3, 7, 'e-era todo ráyikh Yidód mimmékhe e-ele-disse sháddáh quem quem yánud para ela meyáyn avakkésh para-ti para-ti');
INSERT INTO verses VALUES (22789, 34, 3, 8, '[הֲתֵֽיטְבִי֙] [מִנֹּ֣א] [אָמ֔וֹן] [הַיֹּֽשְׁבָה֙] [בַּיְאֹרִ֔ים] águas [סָבִ֣יב] para ela que mar [מִיָּ֖ם] águas');
INSERT INTO verses VALUES (22790, 34, 3, 9, 'Cuxe עָצְמָ֛ה e-Misraim e-não קֵ֑צֶה פּ֣וּט e-lóbes foram em-ásar-te:');
INSERT INTO verses VALUES (22791, 34, 3, 10, 'também ela para-a-gola viagem também também por-ela serão-rebostos na-cabeça todo חוּץ-וֹת e-sobre sua-majestade e-levem sorteio e-todo suas-grandes רֻתּ ק֥וּ בַזִּיקִּֽים׃');
INSERT INTO verses VALUES (22792, 34, 3, 11, 'também tu [תְּהִ֖י] [נַֽעֲלָמָ֑ה] [גַּם־אַ֛תְּ] também [OBJ] [מֵאוֹיֵֽב]');
INSERT INTO verses VALUES (22793, 34, 3, 12, 'todo [תְּאֵנִ֖ים] [עִם־בִּכּוּרִ֑ים] com [וְנָפְל֖וּ] se [אוֹכֵֽל] sobre');
INSERT INTO verses VALUES (22794, 34, 3, 13, 'eis עַמֵּ֤ךְ mulheres בְּקִרְבֵּ֔ךְ לְאֹ֣יְבַ֔יִךְ פָּת֥וֹחַ נִפְתְּח֖וּ שַׁעֲרֵ֣י tua terra ela-comeu fogo teu perfume:');
INSERT INTO verses VALUES (22795, 34, 3, 14, 'águas-de מָצוֹר֙ meu pai— para-ti força-te de tua fortaleza vindo teu ferrete e teu martelo na madeira fortalece-me מלבלן׃');
INSERT INTO verses VALUES (22796, 34, 3, 15, 'nome [תֹּאכְלֵ֣ךְ] fogo [תַּכְרִיתֵ֣ךְ] espada [תֹּאכְלֵ֖ךְ] [כַּיָּ֑לֶק] [הִתְכַּבֵּ֣ד] [כַּיֶּ֔לֶק] [הִֽתְכַּבְּדִ֖י] [כָּאַרְבֶּֽה]');
INSERT INTO verses VALUES (22797, 34, 3, 16, 'הִרְבֵּית֙ rochlayikh mikkochovei os-céus yelek pashat vayyaof');
INSERT INTO verses VALUES (22798, 34, 3, 17, 'minzarayikh kaarbeh vetafpsrayikh kagob gobay os que estão acampados nas paredes em-dia-de aconteceu sol foi-se-elevando e se movimentou e-não conhecido meqom-o ainda');
INSERT INTO verses VALUES (22799, 34, 3, 18, 'cresceram vossos pastores rei Assur dormirão Adeerécha Nafoshu o-teu-povo sobre הַהֲרִים e-não-há Mekabbets');
INSERT INTO verses VALUES (22800, 34, 3, 19, 'não-há Keicha Leshivrakhakha Nachalah Makkatechaka todas Shomerei Shim''akhakha Tak''u כַף sobre-ti que sobre מִי não עָבְרָה teu-mal sempre');
INSERT INTO books VALUES (35, 'HAB', 'Habacuque', 'AT', 3);
INSERT INTO chapters VALUES (905, 35, 1, 17);
INSERT INTO verses VALUES (22801, 35, 1, 1, 'הַמַּשָׂא֙ que חזתה חֲבַקּ֖וּק o profeta:');
INSERT INTO verses VALUES (22802, 35, 1, 2, 'até yhwh yhwh [וְלֹ֣א] e-não [אֶזְעַ֥ק] [אֵלֶ֛יךָ] [חָמָ֖ס] violência e-não');
INSERT INTO verses VALUES (22803, 35, 1, 3, 'por-que [תַרְאֵ֤נִי] [אָ֙וֶן֙] [וְעָמָ֣ל] [תַּבִּ֔יט] [וְשֹׁ֥ד] [וְחָמָ֖ס] [לְנֶגְדִּ֑י] e-houve [רִ֦יב] [וּמָד֖וֹן] [יִשָּֽׂא]');
INSERT INTO verses VALUES (22804, 35, 1, 4, 'sobre assim תָּפ֣וּג תּוֹרָ֔ה e-não saia que juízo porque perverso מַכְתִּ֣יר a o-justo sobre assim saia juízo מְעֻקָּֽל׃');
INSERT INTO verses VALUES (22805, 35, 1, 5, '[רְא֤וּ] [בַגּוֹיִם֙] [וְֽהַבִּ֔יטוּ] [וְהִֽתַּמְּה֖וּ] [תְּמָ֑הוּ] porque [פֹּעֵ֣ל] [בִּֽימֵיכֶ֔ם] não não que porque');
INSERT INTO verses VALUES (22806, 35, 1, 6, 'porque eis-me מֵקִים֙ a הַכַּשׂדִים o-povo הַמּר e o nimhar o holêk para merachêi- terra para-possuir mishchanôt não a-ele');
INSERT INTO verses VALUES (22807, 35, 1, 7, 'aim e norá ele nós misfatto e seato saira');
INSERT INTO verses VALUES (22808, 35, 1, 8, 'e kalû minmerîm suasi e haddu mizaevei tarde u pashu parashayo uparashayo merachok yavo-u yaafu kenesher chas para comer:');
INSERT INTO verses VALUES (22809, 35, 1, 9, 'todoa por violência vira de perigo faces-deles antiga e arreuniu como areia destruição:');
INSERT INTO verses VALUES (22810, 35, 1, 10, 'e-ele entre reis se despedaçará e príncipes משׂחק a-ele ele para-todo מבצר יִשְׂחָ֔ק pó pó WAYYILKADHA:');
INSERT INTO verses VALUES (22811, 35, 1, 11, 'então [חָלַ֥ף] espírito e-atravessou [וְאָשֵׁ֑ם] [ז֥וּ] [כֹח֖וֹ] [לֵאלֹהֽוֹ]');
INSERT INTO verses VALUES (22812, 35, 1, 12, 'não tu ao-oriente yhwh Elohim-me קדשׁי não que-nós-moirtemos yhwh למשפט סמתו ואשם לְהוֹכִ֥יחַ יְסַדְתּֽוֹ׃');
INSERT INTO verses VALUES (22813, 35, 1, 13, '[טְה֤וֹר] [עֵינַ֙יִם֙] [מֵרְא֣וֹת] mal [וְהַבִּ֥יט] a não não [לָ֤מָּה] por-que [בּֽוֹגְדִ֔ים] [תַּחֲרִ֕ישׁ] [בְּבַלַּ֥ע] [רָשָׁ֖ע] [צַדִּ֥יק] nós de-nós');
INSERT INTO verses VALUES (22814, 35, 1, 14, '[וַתַּעֲשֶׂ֥ה] homem [כִּדְגֵ֣י] o-mar [כְּרֶ֖מֶשׂ] não [בּֽוֹ] em-ele');
INSERT INTO verses VALUES (22815, 35, 1, 15, '[כֻּלֹּה֙] [בְּחַכָּ֣ה] [הֵֽעֲלָ֔ה] [יְגֹרֵ֣הוּ] [בְחֶרְמ֔וֹ] [וְיַאַסְפֵ֖הוּ] [בְּמִכְמַרְתּ֑וֹ] sobre assim [וְיָגִֽיל]');
INSERT INTO verses VALUES (22816, 35, 1, 16, 'sobre assim [לְחֶרְמ֔וֹ] [וִֽיקַטֵּ֖ר] [לְמִכְמַרְתּ֑וֹ] que porque animal [חֶלְק֔וֹ] [וּמַאֲכָל֖וֹ] [בְּרִאָֽה]');
INSERT INTO verses VALUES (22817, 35, 1, 17, 'הַ֥עַל assim יָרִ֣יק חֶרְמ֑וֹ וְתָמִ֛יד להרג nações não יַחְמֽוֹל׃');
INSERT INTO chapters VALUES (906, 35, 2, 20);
INSERT INTO verses VALUES (22818, 35, 2, 1, 'sobre [אֶעֱמֹ֔דָה] [וְאֶֽתְיַצְּבָ֖ה] [עַל־מָצ֑וֹר] sobre para-ver [מַה־יְדַבֶּר־בִּ֔י] para-ver que- [עַל־תּוֹכַחְתִּֽי] em-mim farei-voltar sobre');
INSERT INTO verses VALUES (22819, 35, 2, 2, '[וַיַּעֲנֵ֤נִי] yhwh E-disse [כְּת֣וֹב] [חָז֔וֹן] [וּבָאֵ֖ר] sobre [לְמַ֥עַן] para [ק֥וֹרֵא] nele');
INSERT INTO verses VALUES (22820, 35, 2, 3, 'que ainda [חָזוֹן֙] [לַמּוֹעֵ֔ד] [וְיָפֵ֥חַ] [לַקֵּ֖ץ] e-não [יְכַזֵּ֑ב] se [חַכֵּה־ל֔וֹ] [כִּֽי־בֹ֥א] a-ele não veio não');
INSERT INTO verses VALUES (22821, 35, 2, 4, 'eis [עֻפְּלָ֔ה] não [נַפְשׁ֖וֹ] [בּ֑וֹ] nele [בֶּאֱמוּנָת֥וֹ] [יִחְיֶֽה]');
INSERT INTO verses VALUES (22822, 35, 2, 5, 'וְאַף֙ porque הַיַּ֣יִן בּוֹגֵ֔ד homem יהִיר e-não יִנְוֵה que הִרְחִיב כִּשְׁאֹל נַפְשׁוֹ e-ele כַמָּ֙וֶת֙ e-não יִשְׂבָּע a-ele a-ele todo a-ele וַיִּקְבֹּץ a-ele todo ha-ammim');
INSERT INTO verses VALUES (22823, 35, 2, 6, 'porventura-não estes כֻלָּ֗ם sobre-ele מָשָׁל יִשָּׂאֻ וּמְלִיצָ֖ה a-ele para-ele E-disse ה֜וֹי o que multiplica não a-ele até quando e faz sofrer sobre-ele abutre');
INSERT INTO verses VALUES (22824, 35, 2, 7, 'não de repente levantem-se as suas mordeduras e despertem as suas agitações e-você-seja para morderem a-eles');
INSERT INTO verses VALUES (22825, 35, 2, 8, 'que tu [שַׁלּ֙וֹתָ֙] nações muitos [יְשָׁלּ֖וּךָ] todo Jetro [מִדְּמֵ֤י] homem homem [קִרְיָ֖ה] terra [בָֽהּ׃] e-todo em-ela');
INSERT INTO verses VALUES (22826, 35, 2, 9, 'ai בּוֹצֵעַ בֶּ֥צַע mal para-seu-lugar: לָשׂוּם בְּמָרֹם קִנֹּ לַהֲנִיחַלֵץ da-mão mau');
INSERT INTO verses VALUES (22827, 35, 2, 10, 'יָעַצְתָּ vergonha em-teu-casa fins-de nations muitos e-senhor alma-tua');
INSERT INTO verses VALUES (22828, 35, 2, 11, 'porque eben do-fundo chamaste e-ferro de-árvore responderá:');
INSERT INTO verses VALUES (22829, 35, 2, 12, '[ה֛וֹי] [בֹּנֶ֥ה] cidade [בְּדָמִ֑ים] [וְכוֹנֵ֥ן] [קִרְיָ֖ה] [בְּעַוְלָֽה]');
INSERT INTO verses VALUES (22830, 35, 2, 13, 'não eis de-com yhwh exércitos [וְיִֽיגְע֤וּ] [עַמִּים֙] [בְּדֵי־אֵ֔שׁ] fogo [בְּדֵי־רִ֥יק] [יִעָֽפוּ]');
INSERT INTO verses VALUES (22831, 35, 2, 14, 'que será cheia; a-terra para-conhecer a yhwh yhwh כאמים cobrirão; sobre mar');
INSERT INTO verses VALUES (22832, 35, 2, 15, 'ה֜וֹי de água; companheiro-seu e de suor; a tua ira, e o teu fôlego; que seca; para olha; sobre as suas faces.');
INSERT INTO verses VALUES (22833, 35, 2, 16, '[שָׂבַ֤עְתָּ] [קָלוֹן֙] [מִכָּב֔וֹד] [שְׁתֵ֥ה] também tu [תִּסּ֣וֹב] [עָלֶ֗יךָ] sobre-ti [יְמִ֣ין] yhwh yhwh [עַל־כְּבוֹדֶֽךָ] sobre');
INSERT INTO verses VALUES (22834, 35, 2, 17, 'que [חֲמַ֤ס] [לְבָנוֹן֙] [יְכַסֶּ֔ךָּ] [וְשֹׁ֥ד] [בְּהֵמ֖וֹת] [יְחִיתַ֑ן] [מִדְּמֵ֤י] homem [וַחֲמַס־אֶ֔רֶץ] terra [וְכָל־יֹ֥שְׁבֵי] e-todo em-ela');
INSERT INTO verses VALUES (22835, 35, 2, 18, 'que [פֶּ֗סֶל] que porque [יֹֽצְר֔וֹ] [מַסֵּכָ֖ה] [וּמ֣וֹרֶה] [שָּׁ֑קֶר] que porque [יֹצֵ֤ר] [יִצְרוֹ֙] [עָלָ֔יו] sobre-ele para-fazer [אִלְּמִֽים׃]');
INSERT INTO verses VALUES (22836, 35, 2, 19, 'ai disse לאצ הakitze arrega-a a pedra mudo ele ensinador eis-que- ele ouro ouro וכסף e-todo espírito não em-o-centro-dele');
INSERT INTO verses VALUES (22837, 35, 2, 20, 'e-יהוה em-templo-de sua-santidade הַ֥ס מפניו todo a-terra');
INSERT INTO chapters VALUES (907, 35, 3, 19);
INSERT INTO verses VALUES (22838, 35, 3, 1, 'oração para Chavakuk o-profeta sobre pensamentos');
INSERT INTO verses VALUES (22839, 35, 3, 2, 'yhwh eu ouvi ouves-te tremi yhwh o teu trabalho בְּקֶ֤רֶב dois חַיֵּ֔יהוּ em-meio-de dois תּוֹדִ֑יעַ בְּרֹ֖גֶז רַחֵ֥ם תִּזְכּֽוֹר׃');
INSERT INTO verses VALUES (22840, 35, 3, 3, 'אֱל֙וֹהַ֙ מִתֵּימָ֣ן vira וְקָד֥וֹשׁ מֵֽהַר־ פָּארָ֖ן סֶ֑לָּה כִּסֵּה céus הוֹד֔וֹ וּתְהִלָּת֖וֹ a-terra a-terra');
INSERT INTO verses VALUES (22841, 35, 3, 4, '[וְנֹ֙גַהּ֙] [כָּא֣וֹר] [תִּֽהְיֶ֔ה] [קַרְנַ֥יִם] [מִיָּד֖וֹ] a-ele e-ali [חֶבְי֥וֹן] [עֻזֹּֽה]');
INSERT INTO verses VALUES (22842, 35, 3, 5, 'diante-dele יֵ֣לֶךְ palavra e sairá resf pelas suas pernas:');
INSERT INTO verses VALUES (22843, 35, 3, 6, 'estava e mediu terra terra ver nações e se dividiram as montanhas— até caíram montanhas eternidade caminhos eternidade a-ele');
INSERT INTO verses VALUES (22844, 35, 3, 7, 'debaixo iniquidade vi אֹהֲלֵי כושָׁ֑ן יִרְגְּז֤וּן יְרִיע֖וֹת terra de-Madian');
INSERT INTO verses VALUES (22845, 35, 3, 8, '[הֲבִנְהָרִים֙] [חָרָ֣ה] yhwh mãe [בַּנְּהָרִים֙] [אַפֶּ֔ךָ] se [עֶבְרָתֶ֑ךָ] que porque [עַל־סוּסֶ֔יךָ] sobre [יְשׁוּעָֽה]');
INSERT INTO verses VALUES (22846, 35, 3, 9, 'עריה תITOR קשתחך שבועות varas disse סלא נהרות תבקעה- terra');
INSERT INTO verses VALUES (22847, 35, 3, 10, '[רָא֤וּךָ] [יָחִ֙ילוּ֙] [הָרִ֔ים] [זֶ֥רֶם] águas [עָבָ֑ר] dar [תְּהוֹם֙] [קוֹל֔וֹ] [ר֖וֹם] [יָדֵ֥יהוּ] [נָשָֽׂא]');
INSERT INTO verses VALUES (22848, 35, 3, 11, 'שֶׁמֶשׁ יָרֵ֖חַ ficou-em-pé זְבֻ֑לָה לְא֤וֹר seu-arco andarão para-a-ventura relâmpago seu-campo');
INSERT INTO verses VALUES (22849, 35, 3, 12, 'com-ira andarás-em terra com-ira destruirás goyim:');
INSERT INTO verses VALUES (22850, 35, 3, 13, 'sairás לְיֵ֣שַׁע seu povo לְיֵ֖שַׁע a מְשִׁיחֶ֑ךָ מָחַ֤צְתָּ cabeça de-casa-de perverso-o עָר֛וֹת יְס֥וֹד até צַוּ֖אר Selá');
INSERT INTO verses VALUES (22851, 35, 3, 14, 'נָקַ֤בְתָּ בְמַטָּיו֙ cabeça יִסְעֲר֖וּ para me fazer sobre as suas ondas como para-comer pobre em segredo');
INSERT INTO verses VALUES (22852, 35, 3, 15, 'caminhei בַ-יָּם seu cavalo חומר águas muitos');
INSERT INTO verses VALUES (22853, 35, 3, 16, 'eu ouvi váthirgez no meu ventre pelo som à-voz-de minha boca virá רָקָ֛ב בַּעֲצָמַ֖י וְתַחְתַּ֣י אֶרְגָּ֑ז que אָנ֙וּחַ֙ para-o-dia צָרָ֔ה para-subir para-o-povo יְגוּדֶֽנּוּ׃');
INSERT INTO verses VALUES (22854, 35, 3, 17, 'porque תְאֵנָ֣ה não תִפְרָ֗ח e-não-há יְבוּל֙ nos-brafanim kachesh maaseh- zayit u-shedomot não fez o''achel gazar mimiklaha rebanho e-não-há manhã barfatiym');
INSERT INTO verses VALUES (22855, 35, 3, 18, 'e-eu בּיהוָ֣ה e''alozah אָגִילָה בֵּאלֹהֵ֥י Isaías');
INSERT INTO verses VALUES (22856, 35, 3, 19, 'yhwh Adonai [חֵילִ֔י] e-ele-colocou [רַגְלַי֙] [כָּֽאַיָּל֔וֹת] e-sobre [בָּמוֹתַ֖י] [יַדְרִכֵ֑נִי] [לַמְנַצֵּ֖חַ] [בִּנְגִינוֹתָֽי]');
INSERT INTO books VALUES (36, 'ZEP', 'Sofonias', 'AT', 3);
INSERT INTO chapters VALUES (908, 36, 1, 18);
INSERT INTO verses VALUES (22857, 36, 1, 1, 'palavra-de יהוה que ser a Tsefanyah filho-de Kushi filho-de G''dalyah filho-de Amaryah filho-de Chizkiyah בִּימֵ֛י Josias filho-de אָמ֖וֹן rei Judá');
INSERT INTO verses VALUES (22858, 36, 1, 2, 'Asaf Asaf todo de-cima-de face-de a-terra oráculo-de yhwh');
INSERT INTO verses VALUES (22859, 36, 1, 3, 'Asaf homem uvehema Asaf em-o os-céus o-mar o-mar e-as-machsheloth a as-rasha''im de-cima-de face-de a-terra de-al face-de que oráculo-de yhwh');
INSERT INTO verses VALUES (22860, 36, 1, 4, 'וְנָטִ֤יתִי mão-minha sobre Judá e-sobre todo habitantes-de Jerusalém e-cortarei de o-lugar o-este a sar o-Baal a nome as-kamarim com aos-sacerdotes');
INSERT INTO verses VALUES (22861, 36, 1, 5, 'e-a os-mishtachavim sobre as-gagot para-tzaba'' os-céus e-a os que se prostram os que juraram a-yhwh e os que juraram em seu rei:');
INSERT INTO verses VALUES (22862, 36, 1, 6, 'e-a os que se escondem yhwh yhwh e que não buscaram a yhwh e-não דרשהוּ׃');
INSERT INTO verses VALUES (22863, 36, 1, 7, 'eis que de-diante-de Adonai yhwh que proximo dia yhwh porque yhwh yhwh sacrifício-masculino-singular dedicou קְרֻאָֽיו׃');
INSERT INTO verses VALUES (22864, 36, 1, 8, 'e-foi em-dia-de sacrifício-de yhwh [וּפָקַדְתִּ֥י] sobre [וְעַל־בְּנֵ֣י] e-sobre filhos-de o-rei e-sobre todo');
INSERT INTO verses VALUES (22865, 36, 1, 9, '[וּפָקַדְתִּ֗י] sobre todo [עַל־הַמִּפְתָּ֖ן] no-dia [הַה֑וּא] em-o-dia o-aquele [אֲדֹנֵיהֶ֖ם] casa [וּמִרְמָֽה׃]');
INSERT INTO verses VALUES (22866, 36, 1, 10, 'e-será no-dia o-aquele oráculo-de voz voz chamado do portão os-peixes e alarido de ha-mishne''h e ruína grande de cima');
INSERT INTO verses VALUES (22867, 36, 1, 11, 'bradaram habitantes-de o moinho que pareceu-se todo povo Canaã foram-cortadas todo levado prata:');
INSERT INTO verses VALUES (22868, 36, 1, 12, 'e-foi em-o-tempo aquela [אֲחַפֵּ֥שׂ] a Jerusalém [וּפָקַדְתִּ֣י] [עַל־הָאֲנָשִׁ֗ים] sobre os-homens [הָאֹֽמְרִים֙] sobre [לֹֽא־יֵיטִ֥יב] yhwh [וְלֹ֥א] não yhwh e-não');
INSERT INTO verses VALUES (22869, 36, 1, 13, 'e-era חֵילָם לִמְשִׂיסָה וּבָתֵּיהֶם לִשְׁמָמָה e edificarão casa-s e-não residirão VNATOIU vinhas e-não beberão a יֵינָֽם׃');
INSERT INTO verses VALUES (22870, 36, 1, 14, 'קָר֤וֹב dia-de yhwh a-grande próximo muito voz dia yhwh yhwh amargo chamando nome vencedor:');
INSERT INTO verses VALUES (22871, 36, 1, 15, 'dia transgressão o-dia o-aquele dia angústia e tormento dia שֹׁאָה וּמְשׁוֹאָ֔ה dia escuridão וַאֲפֵלָ֔ה dia nuvem e-trevas');
INSERT INTO verses VALUES (22872, 36, 1, 16, 'dia שׁוֹפָ֖ר וּתְרוּעָ֑ה sobre ha-arim הַבְּצֻר֔וֹת e-sobre הַפִּנּ֥וֹת הַגְּבֹהֽוֹת׃');
INSERT INTO verses VALUES (22873, 36, 1, 17, 'וַהֲצֵרֹ֣תִי לָאָדָ֗ם e-vão como-ciegos que a-yhwh pecaram e-derramado sangue-esse como areia e-seu-carne como-pedras:');
INSERT INTO verses VALUES (22874, 36, 1, 18, 'também como-su-silverio também e-seu-ouro não podera yhwh em-dia-de sua-tração yhwh e-em fogo sua ira será consumida todo a-terra porque a-terra somente tremular-se-á entre a todo a-terra a-terra');
INSERT INTO chapters VALUES (909, 36, 2, 15);
INSERT INTO verses VALUES (22875, 36, 2, 1, 'se agitarão e-agitar-se-ão o-povo não será consumido:');
INSERT INTO verses VALUES (22876, 36, 2, 2, 'antes que destruição lei כּ-מוֹצִ עָ-בַר dia בּ-טֶרֶם não vira עֲלֵי-כֶם חֲרֹן também yhwh בּ-טֶרֶם não dia sobre-vós dia também yhwh');
INSERT INTO verses VALUES (22877, 36, 2, 3, 'בּ-קָשׁוּ a yhwh a-terra עַנְוֵי a-terra que מִשְׁפָּט-וֹ פּ-עַלּוּ busquem- justiça busquem- humildade talvez escondam-se em-dia também yhwh');
INSERT INTO verses VALUES (22878, 36, 2, 4, 'que forte desamparo sera e Ashkelon para Shama Ashdod no meio-dia e a expulsarão e-עֶקְר֖וֹן תֵּעָקֵֽר׃');
INSERT INTO verses VALUES (22879, 36, 2, 5, 'ai יֹֽשְׁבֵ֛י chevel o-mar nação כְּרֵתִ֑ים palavra-de yhwh עֲלֵיכֶ֗ם terra terra filisteus וְהַאֲבַדְתִּ֖יךְ sem IOSוב׃');
INSERT INTO verses VALUES (22880, 36, 2, 6, 'e seria região o-mar נְוֺ֛ת כְּרֹ֥ת רֹעִ֖ים וְגִדְר֥וֹת צֹֽאן׃');
INSERT INTO verses VALUES (22881, 36, 2, 7, 'וְהָ֣יָה חֶבֶל לִשְׁאֵרִית casa Judá sobre-eles יִרְע֑וּן בְּבָתֵּ֣י אַשְׁקְל֗וֹן בָּעֶ֙רֶב֙ יִרְבָּצ֔וּן que יִפְקְדֵ֛ם yhwh Elohim-deles וְשָׁ֥ב');
INSERT INTO verses VALUES (22882, 36, 2, 8, 'ouvi [חֶרְפַּ֣ת] Moabe [וְגִדּוּפֵ֖י] filhos-de Amom que [חֵֽרְפוּ֙] a povo-meu [עַל־גְּבוּלָֽם] sobre');
INSERT INTO verses VALUES (22883, 36, 2, 9, 'por-isso vive אָ֡נִי yhwh yhwh de-exércitos Elohim-de Israel porque מוֹאָ֞ב כִּסְדֹ֤ם será e-filhos-de Amom כַּֽעֲמֹרָ֔ה מִמְשַׁ֥ק חָר֛וּל וּמִכְרֵה־ sal e-a até eternidade שְׁאֵרִ֤ית meu-povo vão-se-achar וְיֶ֥תֶר herdarão');
INSERT INTO verses VALUES (22884, 36, 2, 10, 'esta a-eles debaixo sua-gloria que se-honraram e-creceram sobre yhwh yhwh exércitos');
INSERT INTO verses VALUES (22885, 36, 2, 11, 'temor yhwh sobre-eles que segredo a todo a-terra a-terra e-adorarão a-ele homem de-seu-lugar todo איֵי os-gentios');
INSERT INTO verses VALUES (22886, 36, 2, 12, 'também vós [חַֽלְלֵ֥י] [חַרְבִּ֖י] [הֵֽמָּה]');
INSERT INTO verses VALUES (22887, 36, 2, 13, '[וְיֵ֤ט] sua-mão sobre [וִֽיאַבֵּ֖ד] [אֶת־אַשּׁ֑וּר] a Assíria [לִשְׁמָמָ֔ה] a [כַּמִּדְבָּֽר]');
INSERT INTO verses VALUES (22888, 36, 2, 14, 'e rugirão dentro dela עֲדָרִים֙ todo suas criaturas- nação também gafanhoto- voz ciclope- em suas bordas ילינו voz que na-janela destruição no meio porque carvalho- עֵרָֽה׃');
INSERT INTO verses VALUES (22889, 36, 2, 15, '[זֹ֞֠[c]את] [הָעִ֤יר] [הָעַלִּיזָה֙] [הַיּוֹשֶׁ֣בֶת] [לָבֶ֔טַח] [הָאֹֽמְרָה֙] eu [אֲנִ֖י] ainda [ע֑וֹד] ela-foi [׀] era [לְשַׁמָּ֗ה] todo [לַֽחַיָּ֔ה] sobre-ela [עוֹבֵ֣ר] [עָלֶ֔יהָ] [יִשְׁרֹ֖ק]');
INSERT INTO chapters VALUES (910, 36, 3, 20);
INSERT INTO verses VALUES (22890, 36, 3, 1, 'ai MOREAh VANIGAalah a-cidade HYONAH׃');
INSERT INTO verses VALUES (22891, 36, 3, 2, 'não ouviu BKOL não LAKACHא disciplina em-yhwh não BATCHAה a não não que se aproxime');
INSERT INTO verses VALUES (22892, 36, 3, 3, 'suas princesas em seu meio seus arraios seus saugim suas juízas seus zevay tarde não eles se agitaram no-quer');
INSERT INTO verses VALUES (22893, 36, 3, 4, 'suas profetisas seus fochazim homens-de הַבֹּֽגְד֑וֹת כֹּהֲנֶ֙יהָ֙ חִלְּלוּ־ santidade חָמְס֖וּ תּוֹרָֽה׃');
INSERT INTO verses VALUES (22894, 36, 3, 5, 'yhwh just-o em seu seio não faz-o עַוְלָ֑ה בַּבֹּ֨קֶר na-manhã מִשְׁפָּט֨וֹ dará à-luz não foi-entregue e-não conhecedor עַוָּ֖ל בֹּֽשֶׁת׃');
INSERT INTO verses VALUES (22895, 36, 3, 6, 'הִכְרַ֣תִּי [גוֹיִ֗ם] suspiraram פנותם החרבתי חוצותם מִבְּלִ֣י עובר ניצדו seus-cidades מִבְּלִי־ homem sem IOSוב׃');
INSERT INTO verses VALUES (22896, 36, 3, 7, 'disse somente תיראי a-mim תיקחי מוסר e-não ele-será-cortado מעונה todo que eu vigiei sobre-ela certamente levantaram-se destruíram todo suas iniquidades');
INSERT INTO verses VALUES (22897, 36, 3, 8, 'por isso esperaram até que a-mim oráculo-de yhwh o dia que até o fim porque miepáti para reunir גוֹיִ֜ם לְקָבְצִ֣י מַמְלָכ֗וֹת לִשְׁפֹּ֨ךְ עֲלֵיהֶ֤ם זַעְמִי֙ todo que minha ira porque בְּאֵ֣שׁ קִנְאָתִ֔י תֵּאָכֵ֖ל todo a-terra');
INSERT INTO verses VALUES (22898, 36, 3, 9, 'porque então אֶהְפֹּ֥ךְ a povo-es de-língua בְרוּרָ֑ה para-chamar yhwh no-nome-de yhwh um Shekem um');
INSERT INTO verses VALUES (22899, 36, 3, 10, 'מֵעֵ֖בֶר aos-rios- Cush- Ataray- filha-de Futsiy- jubilun- minhati-:');
INSERT INTO verses VALUES (22900, 36, 3, 11, 'no-dia aquele não tavoshi- de-toda עֲלִילֹתַ֔יִךְ que pashaat- em-mim porque Então Prisioneiro do teu meio Alizai teu orgulho e-não mais adicionar-me-ia para a altivez ainda em-monte-de minha-santa-lócus');
INSERT INTO verses VALUES (22901, 36, 3, 12, 'e eu me manteria em-te povo pobre e Dáil e conspirem em-nome-de yhwh');
INSERT INTO verses VALUES (22902, 36, 3, 13, 'resto Israel não façam iniquidade e-não e falem mentira e-não יִמָּצֵ֥א com a sua boca língua-de farpa porque הֵ֛מָּה e morderem וְרָבְצ֖וּ e-não-há de chacota;');
INSERT INTO verses VALUES (22903, 36, 3, 14, 'רָנַּי filha-de Sião tirate Israel שִׂמַּחְיִ וְעָלְזִי em-todo coração filha-de Jerusalém');
INSERT INTO verses VALUES (22904, 36, 3, 15, 'הֵסִיר yhwh מִשְׁפָּטַיִךְ פִּנָּה אֹיְבֵךְ rei israel yhwh yhwh não תִּירְאִי mal ainda');
INSERT INTO verses VALUES (22905, 36, 3, 16, 'no-dia aquele será dito para Jerusalém a תִּרְאֵי Sião a ירפפו Yadayik');
INSERT INTO verses VALUES (22906, 36, 3, 17, 'yhwh Elohayik b''qirbakh homem Yosha'' Yasas alayik b''simhah יַחֲרִישׁ ba''ahavato יָגִ֥יל sobre-ti בְּרִנָּֽה׃');
INSERT INTO verses VALUES (22907, 36, 3, 18, '[נוּגֵ֧י] [מִמּוֹעֵ֛ד] [אָסַ֖פְתִּי] [מִמֵּ֣ךְ] [הָי֑וּ] [מַשְׂאֵ֥ת] sobre-ela opróbrio');
INSERT INTO verses VALUES (22908, 36, 3, 19, 'eis-me fez a todo מְעַנַּ֖יִךְ em-o-tempo aquela וְהוֹשַׁעְתִּ֣י a a quebrada e a desonrada acarreço e puseses para alegria e para o nome em-todo a-terra deles');
INSERT INTO verses VALUES (22909, 36, 3, 20, 'em-o-tempo הַהִיא֙ trarei vos e no tempo קַבְּצִ֣י a-vós porque אֶתֵּ֨ן a-vós para-nome-de para alegria em-todo a-terra a-terra em-me a disse yhwh disse yhwh');
INSERT INTO books VALUES (37, 'HAG', 'Ageu', 'AT', 2);
INSERT INTO chapters VALUES (911, 37, 1, 15);
INSERT INTO verses VALUES (22910, 37, 1, 1, 'em-ano-de שָׁתַיִם לְדָרְיָ֣וֶשׁ o-rei em-o-mês o-sexto em-dia um para-o-mês ser palavra-de yhwh por-mão-de חגי o-profeta a Zarubabel filho-de Salatiel filho-de Judá dizendo יהושע filho-de יהוצדק o-sacerdote o-grande para-dizer');
INSERT INTO verses VALUES (22911, 37, 1, 2, 'assim disse yhwh de-exércitos dizendo o-povo o-este [אָֽמְר֔וּ] não [עֶת־בֹּ֛א] veio yhwh casa yhwh');
INSERT INTO verses VALUES (22912, 37, 1, 3, 'e-houve palavra-de yhwh por-mão-de dizendo');
INSERT INTO verses VALUES (22913, 37, 1, 4, 'העת a-vós vós para-habitar בבתיכם ספונים והבית este חרב׃');
INSERT INTO verses VALUES (22914, 37, 1, 5, 'e-agora assim disse yhwh exércitos [שִׂ֥ימוּ] [לְבַבְכֶ֖ם] sobre');
INSERT INTO verses VALUES (22915, 37, 1, 6, 'זרעתם הרבה e traga um pouco אָכַל e-não-há para saciar ele beberá e-não-há para alugar a-ele e-não-há para o pão a-ele e aquele que aluga alugador a safra cavará');
INSERT INTO verses VALUES (22916, 37, 1, 7, 'assim disse yhwh exércitos [שִׂ֥ימוּ] [לְבַבְכֶ֖ם] sobre');
INSERT INTO verses VALUES (22917, 37, 1, 8, 'עֲל֥וּ הָהָר וַהֲבֵאתֶם árvore וּבָנוּ a-casa וְאֶרְצֶה־ nele disse disse');
INSERT INTO verses VALUES (22918, 37, 1, 9, 'פָּנֹה a multiplique-te e-eis לִמְעָט e-vai-vos-trazer-ais a-casa nele nele porque מֶה yhwh yhwh exércitos porque betî que ele חָרֵב e-vós querem homem para-sua-casa');
INSERT INTO verses VALUES (22919, 37, 1, 10, 'sobre assim sobre-vós preencha-los da-chuva E-a-terra preencha-a semente-ela:');
INSERT INTO verses VALUES (22920, 37, 1, 11, 'e chamei deserto sobre a-terra e-sobre as montanhas e-sobre הַדָּגָן֙ e-sobre הַתִּ֖רְוֹשׁ a-terra do-Horebe e-sobre que saia a-terra-a e-sobre o-homem e-sobre os-animais e-sobre todo געה com-duas:');
INSERT INTO verses VALUES (22921, 37, 1, 12, 'E-ouviu Zerubavel filho-de Šaltil vayehôshûa'' filho-de יְהוֹצָדָק o-sacerdote e-tudo e-todo remanescente o povo בְּקוֹל֙ yhwh אלהיהם e-sobre palavras-de חגי o-profeta como-que yhwh yhwh Elohim-deles e-eles-tremeliram de-diante-de yhwh yhwh');
INSERT INTO verses VALUES (22922, 37, 1, 13, 'E-disse Chagai anjo yhwh em-malakut yhwh ao-povo dizendo eu com-vocês oráculo-de yhwh');
INSERT INTO verses VALUES (22923, 37, 1, 14, 'e-va''ar yhwh a espírito Zerubavel filho-de Šaltiel filho-de Judá e-a espírito Josué filho-de יְהוֹצָדָק o-sacerdote a-grande e-a espírito obra remanescente o-povo e-vieram e-fizeram obra na-casa-de yhwh de-exércitos אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (22924, 37, 1, 15, 'no-dia VINTE e quatro no-chodesh em-sheshi em-ano-de שְׁתֵּים Ladaryāwēš o rei');
INSERT INTO chapters VALUES (912, 37, 2, 23);
INSERT INTO verses VALUES (22925, 37, 2, 1, 'em-shabu''i em-esaris e-um para-o-mês ser palavra-de yhwh por-mão-de dizendo o-profeta para-dizer');
INSERT INTO verses VALUES (22926, 37, 2, 2, 'dize por-favor a زرובבל filho-de Shaltiel filho-de Judá e-a יְהוֹשֻׁ֥עַ filho-de dizendo o-sacerdote sozinho e-a restante o-povo para-dizer');
INSERT INTO verses VALUES (22927, 37, 2, 3, 'quem בָכֶם֙ o-nissoar que ver a a-casa esta -bikvodoo o-primeiro u-ma vós ele ele até-agora não -kamoohu -kaayin nosso-em-vossos:');
INSERT INTO verses VALUES (22928, 37, 2, 4, 'e-agora forte zrubavel oráculo-de yhwh e fortaleça Yehoshua filho-de yehotadak o-sacerdote o-grande וַחֲזַ֨ק a-terra povo a-terra oráculo-de yhwh va-asu yhwh eu convosco oráculo-de yhwh exércitos');
INSERT INTO verses VALUES (22929, 37, 2, 5, 'a [אֲשֶׁר־כָּרַ֤תִּי] que [בְּצֵאתְכֶ֣ם] com-vós [וְרוּחִ֖י] do-Egito [בְּתוֹכְכֶ֑ם] [אַל־תִּירָֽאוּ׃] a');
INSERT INTO verses VALUES (22930, 37, 2, 6, 'que assim disse yhwh exércitos ainda uma pouco ela e-eu מַרְעִישׁ֙ a os-céus e-a a-terra e-a o-mar e-a a desolada:');
INSERT INTO verses VALUES (22931, 37, 2, 7, '[וְהִרְעַשְׁתִּי֙] a todo as-nações [כָּל־הַגּוֹיִ֑ם] [וּמִלֵּאתִ֞י] todo as-nações [כָּב֔וֹד] disse yhwh o-este disse yhwh');
INSERT INTO verses VALUES (22932, 37, 2, 8, 'para-mim o cêsfe e-para-mim o-ouro oráculo-de yhwh exércitos');
INSERT INTO verses VALUES (22933, 37, 2, 9, 'grande será כְּבוֹד֩ o-casa ha-zeh o último de disse yhwh yhwh exércitos e no lugar o-este darei paz yhwh yhwh exércitos');
INSERT INTO verses VALUES (22934, 37, 2, 10, 'VINTE e quatro no nono em-ano-de שְׁתֵּים לְדָרְיָוֶשׁ ser palavra-de yhwh a dizendo o-profeta para-dizer');
INSERT INTO verses VALUES (22935, 37, 2, 11, 'assim disse yhwh exércitos pergunta- נָ֧א a dizendo torá para-dizer');
INSERT INTO verses VALUES (22936, 37, 2, 12, 'eis carrega homem carne de santo em-penho seus vestuários e tocou em suas asas a o pão e-a o esquálido e-a הַיֵּין e-a שֶׁמֶן não todo מַאֲכָל הַיִּקְדֹּשׁ e-eles-responderam hakohanim e-disseram não');
INSERT INTO verses VALUES (22937, 37, 2, 13, 'E-disse [חַגַּ֔י] se [טְמֵא־נֶ֛פֶשׁ] [בְּכָל־אֵ֖לֶּה] alma em-todo estes [וַיֹּאמְר֖וּ] [יִטְמָֽא]');
INSERT INTO verses VALUES (22938, 37, 2, 14, 'e-ele-respondeu חַגַּי E-disse assim o-povo- o Zeh וְכֵן־ הַגֹּוי ha-zeh diante-de-mim oráculo-de yhwh e-assim todo obra-de יְדֵיהֶם ele יַקְרִיבוּ nome a-vós ela');
INSERT INTO verses VALUES (22939, 37, 2, 15, 'e-agora שִׂימוּ־ por-favor para-coracoes-vos de o-dia este e-para-cima מִטֶּרֶם שׂום- yhwh a pedra yhwh yhwh');
INSERT INTO verses VALUES (22940, 37, 2, 16, 'מִהְיוֹתָם veio a עֲרֵמַ֣ת vinte e haveria dez veio a o floculoso o brilhante cinquenta a pura e será vinte');
INSERT INTO verses VALUES (22941, 37, 2, 17, 'eu matei a-vós no-שִׁדָּפ֤וֹן e no espinheiro e na neve a todo obra-de vossas mãos e-não-há a-vocês para-mim oráculo-de yhwh');
INSERT INTO verses VALUES (22942, 37, 2, 18, 'põe-vos- por-favor para-coracoes-vos de o-dia este e-para-cima מִיּוֹם֩ vinte e quatro לַתְּשִׁיעִ֗י desde o-dia que יֻסַּ֥ד הֵֽיכַל־ yhwh שִׂ֥ימוּ vossos-corações:');
INSERT INTO verses VALUES (22943, 37, 2, 19, '[הַע֤וֹד] [הַזֶּ֙רַע֙] [בַּמְּגוּרָ֔ה] e-até [וְהַתְּאֵנָ֧ה] [וְהָרִמּ֛וֹן] [וְעֵ֥ץ] [הַזַּ֖יִת] não não [מִן־הַיּ֥וֹם] de o-dia');
INSERT INTO verses VALUES (22944, 37, 2, 20, 'e-houve palavra-de יהוה שַׁנִּית֙ a חַגִּי בְּעֶשְׂרִים וְאַרְבָּעָה dizendo para-dizer');
INSERT INTO verses VALUES (22945, 37, 2, 21, 'disse a [פַּֽחַת־יְהוּדָ֖ה] dizendo Judá dizendo eu [וְאֶת־הָאָֽרֶץ] a os-céus e-[OBJ] a-terra');
INSERT INTO verses VALUES (22946, 37, 2, 22, 'וְהָפַכְתִּי trono-de מלכות וְהִשְׁמַדְתּ֔י חֹזֶק reinos-de as-nações e farçai carro וְרֹכְבֶ֔יהָ וְיָרְד֤וּ סוּסִים֙ וְרֹ֣כְבֵיהֶ֔ם homem בְּחֶ֥רֶב irmão-dele');
INSERT INTO verses VALUES (22947, 37, 2, 23, 'no-dia הַה֣וּא oráculo-de yhwh צְבָאֹות אֶ֠קָּחֲךָ זְרֻבָּבֶ֨ל filho-de שָׁאַלְתִּיאֵ֤ל meu- servo oráculo-de yhwh וְשַׂמְתִּ֖יךָ כַּֽחוֹתָ֑ם yhwh בְךָ֣ escolhi oráculo-de yhwh exércitos');
INSERT INTO books VALUES (38, 'ZEC', 'Zacarias', 'AT', 14);
INSERT INTO chapters VALUES (913, 38, 1, 17);
INSERT INTO verses VALUES (22948, 38, 1, 1, 'em-o-mês o-oitavo em-ano-de [שְׁתַּ֖יִם] [לְדָרְיָ֑וֶשׁ] ser palavra-de yhwh a Zacarias filho-de dizendo filho-de o-profeta para-dizer');
INSERT INTO verses VALUES (22949, 38, 1, 2, 'ira-se yhwh sobre אֲבֽוֹתֵיכֶ֖ם');
INSERT INTO verses VALUES (22950, 38, 1, 3, 'e-dirás a-eles assim disse yhwh exércitos שׁ֣וּבוּ a-mim oráculo-de yhwh exércitos [וְאָשׁ֣וּב] a-vós disse yhwh exércitos');
INSERT INTO verses VALUES (22951, 38, 1, 4, 'a tִּהְי֣וּ [אֲשֶׁ֣ר] que [הַנְּבִיאִ֨ים] a-eles dizendo os-primeiros disse yhwh disse yhwh exércitos שֻׁבוּ por-favor [*ומעליליכם] [**וּמַֽעֲלְלֵיכֶ֖ם] [הָֽרָעִ֑ים] e-não [שָׁמְע֛וּ] e-não [אֵלַ֖י] para-mim oráculo-de yhwh');
INSERT INTO verses VALUES (22952, 38, 1, 5, 'אֲבֹתֵיכֶם אַיּוּה־ eles e os profetas do sempre viverão');
INSERT INTO verses VALUES (22953, 38, 1, 6, 'somente minhas palavras e minhas leis que eu-ordenei a meus-servos os-profetas não atingiram seus pais e voltaram e-disseram como-que planejaram yhwh dos-exércitos para fazer para-nós como nossos caminhos e-cma''aláleynu assim fez com-nos');
INSERT INTO verses VALUES (22954, 38, 1, 7, 'em-dia vinte ve-arba''ah le-ash''tey- dez novo ele novo shábat em-ano-de ser ledaryávesh foi palavra-de yhwh a dizendo filho-de beréchyahu filho-de idú''ah o-profeta para-dizer');
INSERT INTO verses VALUES (22955, 38, 1, 8, 'ra''iti a-noite e-eis- homem rocheb sobre cavalo homem e-ele entre entre ha-hadassim que בַּמְּצֻלָ֑ה וְאַחֲרָיו֙ סוּסִ֣ים אֲדֻמִּ֔ים שְׂרֻקִּ֖ים וּלְבָנִֽים׃');
INSERT INTO verses VALUES (22956, 38, 1, 9, 'e-disse o-quê estes E-disse E-disse a-mim o-anjo o-falando em-mim eu [מָה־הֵ֥מָּה] Estas eles estes');
INSERT INTO verses VALUES (22957, 38, 1, 10, 'e-respondeu o-homem [הָעֹמֵ֥ד] entre [וַיֹּאמַ֑ר] Estas estas-estes que yhwh yhwh [בָּאָֽרֶץ] na-terra');
INSERT INTO verses VALUES (22958, 38, 1, 11, '[וַֽיַּעֲנ֞וּ] a yhwh yhwh entre entre [וַיֹּאמְר֖וּ] e-disseram na-terra [וְהִנֵּ֥ה] e-eis todo a-terra יֹשֶׁ֥בֶת');
INSERT INTO verses VALUES (22959, 38, 1, 12, 'e-respondeu anjo-de yhwh yhwh yhwh exércitos tu מָתַ֗י tu e-[OBJ] [עָרֵ֣י] a Jerusalém e-a cidades-de Judá que este setenta anos');
INSERT INTO verses VALUES (22960, 38, 1, 13, 'e-respondeu yhwh a o malakh o daber em-mi דְּבָרִ֣ים bons davarim nichumim');
INSERT INTO verses VALUES (22961, 38, 1, 14, 'E-disse a-mim o malakh o-falando em-mim chamou dizendo assim disse yhwh exércitos qinneti para jerusalém e para zion קִנְאָ֥ה g''dolah');
INSERT INTO verses VALUES (22962, 38, 1, 15, 'e qetsef grande eu qotsef sobre as-nações as-ânânim que eu qatsafti mê''ât e-eles azru lerâah');
INSERT INTO verses VALUES (22963, 38, 1, 16, 'portanto assim yhwh yhwh shabti lirûšâm bêrachamim betî yibbeneh em-ela yhwh yhwh exércitos será estendida sobre Jerusalém');
INSERT INTO verses VALUES (22964, 38, 1, 17, 'od chamou dizendo dizendo disse disse yhwh ainda se despedaçará minha boca de bom e confortará yhwh yhwh a Sião e escolherá ainda em-Jerusalém');
INSERT INTO chapters VALUES (914, 38, 2, 17);
INSERT INTO verses VALUES (22965, 38, 2, 1, 'וָאֶשָּׂ֥א a minha vista e vi e-eis quatro cabras:');
INSERT INTO verses VALUES (22966, 38, 2, 2, 'e-disse a o anjo o-dáber em-mi E-disse estes Estas a-mim estes ha-qaranot que zeru a Judá a Israel vi-irushaláym');
INSERT INTO verses VALUES (22967, 38, 2, 3, 'va-yare''eni yhwh quatro chārashim');
INSERT INTO verses VALUES (22968, 38, 2, 4, 'e-eu-disse que Estas vindo la-`asot E-disse dizendo Estas ha-qaranot que zeru a Judá kipi- homem Estas nasa eles וַיָּבוֹאֻ estes lehaḥarid a-eles leyadot a as-chifres הגויים hanosh''im keren a terra יְהוּדָה lezarotah');
INSERT INTO verses VALUES (22969, 38, 2, 5, 'e-elevei meus-olhos e-eu-vi e-eis- homem e-em-a-sua-mão [מִדָּֽה]');
INSERT INTO verses VALUES (22970, 38, 2, 6, 'e-eu-disse אָ֖נָה tu andou E-disse a-mim [לָמֹד֙] a para-ver para-ver [וְכַמָּ֥ה] largura-sua');
INSERT INTO verses VALUES (22971, 38, 2, 7, 'e-eis [הַמַּלְאָ֛ךְ] [הַדֹּבֵ֥ר] em-mi sai e anjo outro sai [לִקְרָאתֽוֹ]');
INSERT INTO verses VALUES (22972, 38, 2, 8, 'E-disse אֵלָו רֻץ palavra a o-menino dizendo dizendo פְּרָזוֹת תֵּשֵׁ֣ב Jerusalém homem homem e-behemah no seu meio:');
INSERT INTO verses VALUES (22973, 38, 2, 9, 'e-ani אֶהְיֶה- la oráculo-de yhwh chomath fogo ao-redor u-le-kavod ehyeh betokha:');
INSERT INTO verses VALUES (22974, 38, 2, 10, 'ai ai e levantou-se de-terra-de norte oráculo-de que porque como quatro ventos os-céus expus vos oráculo-de yhwh');
INSERT INTO verses VALUES (22975, 38, 2, 11, 'ai Sião libertei sentada filha-de Babilônia');
INSERT INTO verses VALUES (22976, 38, 2, 12, 'que assim disse yhwh exércitos atrás-de glória enviei-me a as-nações os que roubam que porque o que toca בכם que toca na caixa do coração seus olhos:');
INSERT INTO verses VALUES (22977, 38, 2, 13, 'que eis-me que agita a mão-minha e-sejam e-serão o que roubou para seus servos וִֽידַעְתֶּ֕ם porque yhwh de-exércitos envia-me:');
INSERT INTO verses VALUES (22978, 38, 2, 14, 'alegra-te e alegria-me filha-de que porque eis-me aqui- veio e habitar-ei no teu meio oráculo-de yhwh');
INSERT INTO verses VALUES (22979, 38, 2, 15, 'e conhecereis goyim rabbîm a no-dia no-dia e-sejam e-serão a-mim para povo- e habitar-ei dentro de ti e conhecereis porque yhwh exércitos enviou-me me-');
INSERT INTO verses VALUES (22980, 38, 2, 16, '[וְנָחַ֨ל] yhwh a Judá sobre sobre terra-de a-santidade וּבָחַ֥ר ainda em-Jerusalém');
INSERT INTO verses VALUES (22981, 38, 2, 17, '[הַ֥ס] todo de-diante-de yhwh que porque [מִמְּע֥וֹן] [קָדְשֽׁוֹ׃] קָדְשֽׁוֹ׃');
INSERT INTO chapters VALUES (915, 38, 3, 10);
INSERT INTO verses VALUES (22982, 38, 3, 1, '[וַיַּרְאֵ֗נִי] a יְהוֹשֻׁעַ o-sacerdote a-grande ficou-em-pé diante-de yhwh yhwh [עֹמֵ֥ד] ficou-em-pé sobre sua-direita');
INSERT INTO verses VALUES (22983, 38, 3, 2, 'E-disse yhwh a o satanás yhwh yhwh be-ka o diabo yhwh yhwh a-você o escolhido em- Jerusalém não isto Aod forjado do fogo:');
INSERT INTO verses VALUES (22984, 38, 3, 3, 'e- Josué ser vestido roupas que saem e ficar de pé diante-de o anjo:');
INSERT INTO verses VALUES (22985, 38, 3, 4, 'e-respondeu E-disse a os que permanecem dizendo dizendo tirai os vestuários as saídas E-disse a-ele a-ele viu eu retirei de ti teu pecado e vestisse a-ti as calças');
INSERT INTO verses VALUES (22986, 38, 3, 5, 'e-eu-disse colocarão cinto puro sobre sua-cabeça e colocaram o cinto o purificado sobre cabeça-sua e vestiu-o yhwh e anjo yhwh ficou-em-pé');
INSERT INTO verses VALUES (22987, 38, 3, 6, 'e testemunhou anjo yhwh em Josué dizendo');
INSERT INTO verses VALUES (22988, 38, 3, 7, 'assim yhwh yhwh exércitos se nos meus caminhos andarás e-se a da minha guarda guarda e-também tu julgares a a-ti e-também entre a חֲצֵרַי e-darei a-ti מַהְלְכִים entre os-que-estavam-de-pé as estas');
INSERT INTO verses VALUES (22989, 38, 3, 8, 'ouve；： por-favor [׀] o-sacerdote a-grande tu [וְרֵעֶ֙יךָ֙] os-dignantes diante-de-ti porque homens-de [הֵ֑מָּה] elas-eram porque eis-me [צֶֽמַח] a servo-meu');
INSERT INTO verses VALUES (22990, 38, 3, 9, 'que eis eis que dei dei Yehoshua sobre pedra uma sete einaim eis-me [מְפַתֵּ֣חַ] [פִּתֻּחָ֗הּ] oráculo-de yhwh exércitos [וּמַשְׁתִּ֛י] a iniquidade-de [בְּי֥וֹם] um em-dia um');
INSERT INTO verses VALUES (22991, 38, 3, 10, 'no-dia aquele oráculo-de yhwh exércitos [תִּקְרְא֖וּ] homem para-companheiro-seu a debaixo-de גֶּ֖פֶן e-a em-baixo-de');
INSERT INTO chapters VALUES (916, 38, 4, 14);
INSERT INTO verses VALUES (22992, 38, 4, 1, '[וַיָּ֕שָׁב] o-mensagem-elohim o-falando em-mim [וַיְעִירֵ֕נִי] [כְּאִ֖ישׁ] que [מִשְּׁנָתֽוֹ]');
INSERT INTO verses VALUES (22993, 38, 4, 2, 'E-disse a-mim que tu viu vi e-eis lámpada ouro todo-o e-ela ouro cabeça-sua e-sete luzes-suas sobre-ela sete וְשִׁבְעָה֙ forjadas lanerot que sobre ro-sha-ho-:');
INSERT INTO verses VALUES (22994, 38, 4, 3, 'u-shnayim oliveiras sobre-ela um do-direito hagulla e-um sobre da-esquerda׃');
INSERT INTO verses VALUES (22995, 38, 4, 4, 'e-respondei e-disse a o-angel הַדּוֹבֵר dizendo dizendo o-quê estes Adonai');
INSERT INTO verses VALUES (22996, 38, 4, 5, 'e respondeu o mensageiro o que fala em-mim E-disse a-mim não sabes o-quê Estas estes não não Adonai');
INSERT INTO verses VALUES (22997, 38, 4, 6, 'e respondeu E-disse a-mim dizendo este palavra-de yhwh dizendo não dizendo não em força que em poder disse yhwh pelo meu espírito disse yhwh exércitos');
INSERT INTO verses VALUES (22998, 38, 4, 7, 'quem você monte-de o grande diante-de Zorobabel para o meio e-sa-irá a a-pedra a-cabeça as-mãos favor graça a-ela');
INSERT INTO verses VALUES (22999, 38, 4, 8, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (23000, 38, 4, 9, 'mãos-de Zorobabel estabelecer-ão o-templo este e-sus-mãos cortar-ão e-saber-ás porque yhwh de-exércitos enviou-me a-vós');
INSERT INTO verses VALUES (23001, 38, 4, 10, 'que quem no-bacalhau para-o-dia pequeninas e-alegrar-se-ão וְרָא֞וּ a הָאֶ֧בֶן הַבְּדִ֛יל em-mão-de Zorobabel os-olhos-de yhwh os-olhos-de yhwh eles em-todo a-terra');
INSERT INTO verses VALUES (23002, 38, 4, 11, '[וָאַ֖עַן] e-disse a-ele que segundo [הָאֵ֔לֶה] [עַל־יְמִ֥ין] sobre Direito e-sobre');
INSERT INTO verses VALUES (23003, 38, 4, 12, '[וָאַ֣עַן] segunda-noite e-disse a-ele que [שִׁבֲּלֵ֣י] [הַזֵּיתִ֗ים] [אֲשֶׁר֙] que [שְׁנֵי֙] segundo o-ouro o-ouro [מֵעֲלֵיהֶ֖ם] o-ouro o-ouro');
INSERT INTO verses VALUES (23004, 38, 4, 13, 'E-disse a-mim dizendo não [יָדַ֖עְתָּ] o-quê estes não não Adonai');
INSERT INTO verses VALUES (23005, 38, 4, 14, 'E-disse Estas segundo filhos-de [הָעֹמְדִ֖ים] os-que-estavam-de-pé sobre todo a-terra');
INSERT INTO chapters VALUES (917, 38, 5, 11);
INSERT INTO verses VALUES (23006, 38, 5, 1, 'וָאָשׁוּב וָאֶשָּׂ֥א עֵינַי Eu vi e-eis Megalá Afá:');
INSERT INTO verses VALUES (23007, 38, 5, 2, 'E-disse a-mim que tu viu e-disse eu viu Megalá Afá Sua extensão era vinte na-côvado e seu comprimento dez em côvados:');
INSERT INTO verses VALUES (23008, 38, 5, 3, 'E-disse a-mim esta A ala que saía sobre face-de que a-terra porque todo o гонев de-este como-a năкаh e-todo o нисбּע de-este como-a năкаh');
INSERT INTO verses VALUES (23009, 38, 5, 4, '[הוֹצֵאתִ֗יהָ] oráculo-de yhwh exércitos [וּבָ֙אָה֙] a casa o גַּנָּ֔ב e-a casa [לַשָּׁ֑קֶר] bish-mi no-meio-de [בֵּית֔וֹ] em-meio-de casa-dele [וְאֶת־אֲבָנָֽיו] e-a e-a');
INSERT INTO verses VALUES (23010, 38, 5, 5, 'e-ele-saiu o-mensagem-elohim o-falando em-mim E-disse a-mim eleva por-favor os-teus-olhos e-vê que [הַיּוֹצֵ֥את] a esta');
INSERT INTO verses VALUES (23011, 38, 5, 6, 'e-disse que E-disse esta esta [הַיּוֹצֵ֔את] E-disse esta esta [בְּכָל־הָאָֽרֶץ] em-todo a-terra');
INSERT INTO verses VALUES (23012, 38, 5, 7, 'e-eis [כִּכַּ֥ר] [עֹפֶ֖רֶת] [נִשֵּׂ֑את] ve-zot mulher uma [יוֹשֶׁ֖בֶת] no-meio-de [הָאֵיפָֽה]');
INSERT INTO verses VALUES (23013, 38, 5, 8, 'E-disse esta [הָרִשְׁעָ֔ה] e lançou a-ela a meio-de [וַיַּשְׁלֵ֛ךְ] [אֶת־אֶ֥בֶן] a pedra a boca-dela');
INSERT INTO verses VALUES (23014, 38, 5, 9, 'VASאשא עיני eu vi e-eis duas mulheres saindo e-Espírito-de com asas delas e para elas como asas como asas da da cipresteira e elas se assustaram a entre a-terra e-entre e-entre os-céus');
INSERT INTO verses VALUES (23015, 38, 5, 10, 'e-eu-disse a o-mensagem-elohim o-falando em-mim [הֵ֥מָּה] eles [אֶת־הָאֵיפָֽה] a');
INSERT INTO verses VALUES (23016, 38, 5, 11, 'E-disse a-mim para-construir- [בַ֖יִת] casa em-terra-de [וְהוּכַ֛ן] [וְהֻנִּ֥יחָה] [שָּׁ֖ם] nome sobre');
INSERT INTO chapters VALUES (918, 38, 6, 15);
INSERT INTO verses VALUES (23017, 38, 6, 1, '[וָאָשֻׁ֗ב] e-levantei e-olhos [וָֽאֶרְאֶ֔ה] e-eis quatro [מַרְכָּבוֹת֙] [יֹֽצְא֔וֹת] de-mezzo-a segundo [הֶֽהָרִ֑ים] [וְהֶהָרִ֖ים] montes-de bronze');
INSERT INTO verses VALUES (23018, 38, 6, 2, '[בַּמֶּרְכָּבָ֥ה] [הָרִֽאשֹׁנָ֖ה] [סוּסִ֣ים] [אֲדֻמִּ֑ים] [וּבַמֶּרְכָּבָ֥ה] a-segunda cavalos [שְׁחֹרִֽים]');
INSERT INTO verses VALUES (23019, 38, 6, 3, 'בהרכבה a-šalı̂šı̂ṯ sūśı̂m ləḇānı̂m u-ba-měrakkabhāh ha-rēḇı̂ʿı̂ṯ cavalos bərūddı̂m ʾămuṣṣı̂m');
INSERT INTO verses VALUES (23020, 38, 6, 4, 'wa-ʿaănā wāʾōmer a o-mensagem-elohim o-falando em-mim o-quê estes Adonai');
INSERT INTO verses VALUES (23021, 38, 6, 5, 'e-respondeu o-mensagem-elohim E-disse a-mim Estas quatro [רֻח֣וֹת] os-céus [יוֹצְא֕וֹת] מהתיצב sobre [כָּל־הָאָֽרֶץ] todo a-terra');
INSERT INTO verses VALUES (23022, 38, 6, 6, 'que [הַסּוּסִ֣ים] [הַשְּׁחֹרִ֗ים] [יֹֽצְאִים֙] [אֶל־אֶ֣רֶץ] a terra norte [אֶל־אֽ͏ַחֲרֵיהֶ֑ם] saíram a [אֶל־אֶ֥רֶץ] [הַתֵּימָֽן] saíram a terra');
INSERT INTO verses VALUES (23023, 38, 6, 7, '[וְהָאֲמֻצִּ֣ים] saíram e-buscaram para-andar [לְהִתְהַלֵּ֣ך] na-terra E-disse ide [הִתְהַלְּכ֣וּ] na-terra [וַתִּתְהַלַּ֖כְנָה] na-terra');
INSERT INTO verses VALUES (23024, 38, 6, 8, '[וַיַּזְעֵ֣ק] oti e-falou para-mim dizendo viu [הַיּֽוֹצְאִים֙] a terra norte [אֶת־רוּחִ֖י] a [צָפֽוֹן׃] em-terra-de צָפֽוֹן׃');
INSERT INTO verses VALUES (23025, 38, 6, 9, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (23026, 38, 6, 10, '[לָק֙וֹחַ֙] de-junto-de o-exílio [מֵחֶלְדַּ֕י] [וּמֵאֵ֥ת] Tobiah [וּמֵאֵ֣ת] [יְדַֽעְיָ֑ה] [וּבָאתָ֤] tu no-dia aquele ובאתה casa [יֹאשִׁיָּ֣ה] filho-de [אֲשֶׁר־בָּ֖אוּ] que entraram Mibavel');
INSERT INTO verses VALUES (23027, 38, 6, 11, 'e-toma [כֶֽסֶף־וְזָהָ֖ב] וְזָהָ֖ב e-farás [וְשַׂמְתָּ֗] [בְּרֹ֛אשׁ] בראש יְהוֹשֻׁ֥עַ filho-de [הַגָּדֽוֹל] o-sacerdote o-grande');
INSERT INTO verses VALUES (23028, 38, 6, 12, 'e-dirás a-ele dizendo assim disse yhwh de-exércitos dizendo eis-que- homem [שְׁמוֹ֙] nome-dele brotou [וּבָנָ֖ה] [אֶת־הֵיכַ֥ל] a templo-de yhwh');
INSERT INTO verses VALUES (23029, 38, 6, 13, 've-hu יִבְנֶ֞ה a yhwh yhwh e-ele יISA ה֔וֹד e assentou-se e domínio sobre seu trono e-era sacerdote sobre entre e conselho paz não entre dois-deles');
INSERT INTO verses VALUES (23030, 38, 6, 14, 'e coroa será para ruína e beleza e glória e favor filho-de Tsafanya לְזִכּוֹר֖וֹן yhwh yhwh');
INSERT INTO verses VALUES (23031, 38, 6, 15, 'e distâncias virão e edificarão em-templo-de yhwh yhwh porque yhwh de-exércitos enviou-me a-vós e-foi se ouvireis ouviráis yhwh yhwh Elohim-vosso');
INSERT INTO chapters VALUES (919, 38, 7, 14);
INSERT INTO verses VALUES (23032, 38, 7, 1, 'e-houve em-ano-de quatro para-dar-yavesh o-rei ser palavra-de yhwh a [לַחֹ֥דֶשׁ] [הַתְּשִׁעִ֖י] [בְּכִסְלֵֽו]');
INSERT INTO verses VALUES (23033, 38, 7, 2, 'e-enviou casa-de El príncipe-de [מֶ֖לֶךְ] [וַֽאֲנָשָׁ֑יו] rei [אֶת־פְּנֵ֥י] yhwh a face-de yhwh');
INSERT INTO verses VALUES (23034, 38, 7, 3, 'dizendo a os-sacerdotes que para-casa-de yhwh dizendo e-a os-profetas dizendo [הִנָּזֵ֕ר] no-mês [עָשִׂ֔יתִי] [זֶ֖ה] como-que fiz este  kamme dois');
INSERT INTO verses VALUES (23035, 38, 7, 4, 'e-houve palavra-de yhwh de-exércitos dizendo para-dizer');
INSERT INTO verses VALUES (23036, 38, 7, 5, 'disse a a-terra povo dizendo e-a os-sacerdotes dizendo porque [וְזֶה֙] [שִׁבְעִ֣ים] [שָׁנָ֔ה] [הֲצ֥וֹם] וְזֶה֙ setenta ano eu:');
INSERT INTO verses VALUES (23037, 38, 7, 6, 'e-que comereis e-porque [תִשְׁתּ֑וּ] não vós [הָאֹ֣כְלִ֔ים] e-vós [הַשֹּׁתִֽים]');
INSERT INTO verses VALUES (23038, 38, 7, 7, 'não a as palavras chamou yhwh yhwh em-mão-de הנביאים [בִּהְי֤וֹת] [יְרוּשָׁלִַ֙ם֙] Jerusalém [וּשְׁלֵוָ֔ה] [וְעָרֶ֖יהָ] [סְבִיבֹתֶ֑יהָ] seu-volta-tes [וְהַשְּׁפֵלָ֖ה] [יֹשֵֽׁב׃] habitou');
INSERT INTO verses VALUES (23039, 38, 7, 8, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (23040, 38, 7, 9, 'assim disse yhwh de-exércitos dizendo משפט verdade שפטו והחסד e misericórdias façais homem a irmão-dele');
INSERT INTO verses VALUES (23041, 38, 7, 10, 'e órfãos e viúvas e estrangeiro e pobre a vós os traiçoeiros e pensamentos de maldade homem irmão-seu a tende nos vossos corações:');
INSERT INTO verses VALUES (23042, 38, 7, 11, 'e disseram para ouvir e-eles-distribuíram ombro sorreret e suas orelhas se fizessem ouvir de ouvido');
INSERT INTO verses VALUES (23043, 38, 7, 12, 'e seus corações colocaram se endurecessem de ouvido a a lei e-a as palavras yhwh enviou yhwh exércitos no seu espírito na-mão-de e-houve os primeiros E-foi raiva yhwh de-com yhwh exércitos');
INSERT INTO verses VALUES (23044, 38, 7, 13, 'e-houve como-que chamou e-não ouvirão assim chamarão e-não disse yhwh yhwh exércitos');
INSERT INTO verses VALUES (23045, 38, 7, 14, 'e arderão sobre todo as-nações que E-a-terra conhecerão e a terra suspirou אַחֲרֵיהֶם מֵעֹבֵר וּמִשָׁב e-os-colocaram terra-de חֶמְדָּה לְשַׁמָּה׃');
INSERT INTO chapters VALUES (920, 38, 8, 23);
INSERT INTO verses VALUES (23046, 38, 8, 1, 'e-houve palavra-de yhwh dizendo para-dizer');
INSERT INTO verses VALUES (23047, 38, 8, 2, 'assim disse yhwh exércitos [קִנֵּ֥אתִי] [לְצִיּ֖וֹן] [קִנְאָ֣ה] grande [וְחֵמָ֥ה] grande [קִנֵּ֥אתִי] a-ela');
INSERT INTO verses VALUES (23048, 38, 8, 3, 'assim disse yhwh [שַׁ֚בְתִּי] a Sião no-meio-de em-meio-de ירVASלם [יְרוּשָׁלִַ֙ם֙] Jerusalém [וְהַר־יְהוָ֥ה] [צְבָא֖וֹת] e-har- yhwh de-exércitos monte-de o-santuário');
INSERT INTO verses VALUES (23049, 38, 8, 4, 'assim disse yhwh exércitos até se-já-sentarão זְקֵנִ֣ים [וּזְקֵנ֔וֹת] [בִּרְחֹב֖וֹת] Jerusalém e-homem [מִשְׁעַנְתּ֛וֹ] em-sua-mão de-abundância-de dias');
INSERT INTO verses VALUES (23050, 38, 8, 5, 'וּרְחֹב֤וֹת a-cidade serão multiplicados filhos e filhas brincando em suas ruas');
INSERT INTO verses VALUES (23051, 38, 8, 6, 'assim disse yhwh exércitos que serão vistos diante dos olhos de perpétua o-povo esta em-os-dias os-aqueles também nos meus olhos serão vistos yhwh yhwh exércitos');
INSERT INTO verses VALUES (23052, 38, 8, 7, 'assim disse yhwh exércitos eis-me salvador a povo-meu da-terra do oriente e de terra ingresso o-sol');
INSERT INTO verses VALUES (23053, 38, 8, 8, 'e eu trarei eles e habitareis no-meio-de Jerusalém e serão para-mim para povo וַֽאֲנִי֙ a-eles a-eles para-Elohim be-emet e em justiça');
INSERT INTO verses VALUES (23054, 38, 8, 9, 'assim yhwh yhwh Cavalarias sejam-fortes vossas mãos aqueles que ouvem em-os-dias estes a as-palavras estes מִפִּי֙ os-profetas que בְּי֞וֹם יֻסַּ֨ד casa-de yhwh exercitos não לְהִבָּנֽוֹת׃');
INSERT INTO verses VALUES (23055, 38, 8, 10, 'que diante-de os-dias aqueles שְׂכַ֤ר o-homem não נִֽהְיָ֔ה וּשְׂכַ֥ר os-animais אֵינֶ֑נָּה וְלַיּוֹצֵ֨א וְלַבָּ֤א não-há שָׁלוֹם֙ de o inimigo e estender a todo o-homem homem sobre ele:');
INSERT INTO verses VALUES (23056, 38, 8, 11, 'e-agora não como os dias os primeiros eu sou para sobreviver o-povo esta oráculo-de yhwh exércitos');
INSERT INTO verses VALUES (23057, 38, 8, 12, 'porque descendência o paz a videira vai dar E-a-terra e a terra תִּתֵּן a seu fruto e os céus darão chuva e herdarão a semente o-povo este a todo Estas');
INSERT INTO verses VALUES (23058, 38, 8, 13, 'e-será como-que seriam maldição בַּגּוֹיִ֗ם casa Judá e-Beit Israel assim salvador vos e-sereis ברכה a תיראוּ תחזקה ידיכם׃');
INSERT INTO verses VALUES (23059, 38, 8, 14, 'que assim disse yhwh exércitos como-que [זָמַמְ֜תִּי] [לְהָרַ֣ע] a-vós [בְּהַקְצִ֤יף] pais-vossos oti disse yhwh exércitos e-não [נִחָֽמְתִּי]');
INSERT INTO verses VALUES (23060, 38, 8, 15, 'assim [שַׁ֤בְתִּי] [זָמַ֙מְתִּי֙] em-os-dias os-estes para bem a Jerusalém e-a casa Judá a');
INSERT INTO verses VALUES (23061, 38, 8, 16, 'Estas as-palavras que [תַּֽעֲשׂ֑וּ] falem verdade homem a companheiro-seu verdade [שָׁל֔וֹם] paz [בְּשַׁעֲרֵיכֶֽם]');
INSERT INTO verses VALUES (23062, 38, 8, 17, 'וְאִ֣ישׁ ׀ a mau companheiro-seu a תַּחְשְׁבוּ֙ no-seu-lixo-vos e-sua-jura enganos que odiareis porque a todo Estas que detestei oráculo-de yhwh');
INSERT INTO verses VALUES (23063, 38, 8, 18, 'e-houve palavra-de yhwh de-exércitos dizendo para-dizer');
INSERT INTO verses VALUES (23064, 38, 8, 19, 'assim yhwh yhwh exércitos o-quarto o-quarto e-fasting o-quinquagesimal e-fasting o sétimo e-fasting será sera para-casa-de Judá para-a-guizza e-para-a-felizidade e-para-os-encontros bons e-a-verdade e-o-paz amem:');
INSERT INTO verses VALUES (23065, 38, 8, 20, 'assim disse yhwh exércitos até que entrarão nations e-os-habitantes cidades dos-muitos:');
INSERT INTO verses VALUES (23066, 38, 8, 21, '[וְֽהָלְכ֡וּ] [יֹשְׁבֵי֩] uma a dizendo dizendo [הָלוֹךְ֙] caminhar [אֶת־פְּנֵ֣י] yhwh face-de yhwh e-te-pesquises∶ a yhwh também eu:');
INSERT INTO verses VALUES (23067, 38, 8, 22, 'e-entraram [עַמִּ֤ים] רַבִּים [וְגוֹיִ֣ם] [עֲצוּמִ֔ים] [לְבַקֵּ֛שׁ] a yhwh de-exércitos em-Jerusalém [אֶת־פְּנֵ֥י] yhwh face-de yhwh');
INSERT INTO verses VALUES (23068, 38, 8, 23, 'assim disse yhwh exércitos em-os-dias e-eles que [יַחֲזִ֙יקוּ֙] asarah homens de-toda [לְשֹׁנ֣וֹת] as-nações [וְֽהֶחֱזִ֡יקוּ] [בִּכְנַף֩] homem [יְהוּדִ֜י] dizendo [נֵֽלְכָה֙] com-vocês que ouvimos Elohim com-vos');
INSERT INTO chapters VALUES (921, 38, 9, 17);
INSERT INTO verses VALUES (23069, 38, 9, 1, 'משאה palavra-de yhwh em-terra-de חדרך e Damasco que porque para-יהוה homem e-tudo e-todo tribos-de Israel');
INSERT INTO verses VALUES (23070, 38, 9, 2, 'e-também de cór Tigbal- nela que e Zidon muito sabedoria muito');
INSERT INTO verses VALUES (23071, 38, 9, 3, 'e edificou Sior em Sior para ela e armazenou- prata como areia e arroto כּ-טִיט חוּץֽוֹת׃');
INSERT INTO verses VALUES (23072, 38, 9, 4, 'eis Adonai [יֽוֹרִשֶׁ֔נָּה] וְהִכָּ֥ה [בַיָּ֖ם] [חֵילָ֑הּ] e-ela בָּאֵ֥שׁ [תֵּאָכֵֽל]');
INSERT INTO verses VALUES (23073, 38, 9, 5, '[תֵּרֶ֨א] [אַשְׁקְל֜וֹן] [וְתִירָ֗א] [וְעַזָּה֙] [וְתָחִ֣יל] muito [וְעֶקְר֖וֹן] porque [מֶבָּטָ֑הּ] [וְאָ֤בַד] [מֶ֙לֶךְ֙] rei [וְאַשְׁקְל֖וֹן] não não תֵשֵֽׁב׃');
INSERT INTO verses VALUES (23074, 38, 9, 6, 'e-yָשַׁ֥ב mַמְזֵ֖ר em-Ashdod e cortarei orgulho filisteus');
INSERT INTO verses VALUES (23075, 38, 9, 7, 'e removerei seus sangues de sua boca e suas escarificações entre suas gengivas e restará também ele para nosso Elohim e-foi כְּאַלֻּ֣ף בִּֽיהוּדָ֔ה וְעֶקְר֖וֹן כִּיבוּסִֽי׃');
INSERT INTO verses VALUES (23076, 38, 9, 8, 'וְחָנִ֨יתִי לְבֵיתִ֤י מִצָּבָה֙ מֵעֹבֵ֣ר וּמִשָׁ֔ב e-não יַעֲבֹ֧ר sobre-eles ainda que porque agora Vi com os meus olhos:');
INSERT INTO verses VALUES (23077, 38, 9, 9, 'alegra-te muito filha-de Siao e toca בת eis eis Rei teu para-ti para-ti justo ele ele pobre e aquele que monta sobre cavalo e-sobre cidade filho-de as jumentas:');
INSERT INTO verses VALUES (23078, 38, 9, 10, 'e cortarei carros de-Afrãim e-cavalo de-Jerusalém e-será-cortada arco guerra e-foi-dito paz para-povos e-segredo-suyo águas até mar e-río até extremidades-de terra');
INSERT INTO verses VALUES (23079, 38, 9, 11, 'também tu por-sangue- por-aliança-teu שִׁלַּחְתִּי אֲסִירֶיךָ águas não-há águas em-ele');
INSERT INTO verses VALUES (23080, 38, 9, 12, 'Shuvu@ [לְבִצָּר֔וֹן] [אֲסִירֵ֖י] [הַתִּקְוָ֑ה] também הַיּוֹם [מִשְׁנֶ֖ה] [אָשִׁ֥יב] para-ti para-ti');
INSERT INTO verses VALUES (23081, 38, 9, 13, 'porque דָּרַכְתִּי para-mim Judá arco-de מִלֵּאֹתִי Efraim e despertarei filhos teus Sião sobre filhos teus Jão e estabelecer-te-ei como uma espada vencedor:');
INSERT INTO verses VALUES (23082, 38, 9, 14, 'e-יהוה sobre-eles será visto e-saiu como relâmpago seu arco וַֽאדֹנָ֤י yhwh בַּשּׁוֹפָ֣ר יִתְקָ֔ע וְהָלַ֖ךְ בְּסַעֲר֥וֹת תֵּימָֽן׃');
INSERT INTO verses VALUES (23083, 38, 9, 15, 'yhwh צְבָאוֹת֮ יָגֵ֣ן עֲלֵיהֶם֒ וְאָכְל֗וּ e domineiem pedras-de cavas e bebam e comam como vinho e preencha-los como uma espingarda como feras no altar:');
INSERT INTO verses VALUES (23084, 38, 9, 16, 'e salve-os yhwh seus elohimes no-dia aquele כּ-צֹאן povo-seu que pedras-de נֵ-זֶר מִ-תְנוֹסְס֖וֹת sobre אַדְמָתֽוֹ׃');
INSERT INTO verses VALUES (23085, 38, 9, 17, 'que que [וּמַה־יָפְי֑וֹ] e-que [בַּֽחוּרִ֔ים] grão [יְנוֹבֵ֥ב] [בְּתֻלֽוֹת]');
INSERT INTO chapters VALUES (922, 38, 10, 12);
INSERT INTO verses VALUES (23086, 38, 10, 1, 'שאלו מיהוה por chuva na época מלকו yhwh fez חזיזים ומטר־ גשם a-eles a-eles para cada um erva-de no-campo');
INSERT INTO verses VALUES (23087, 38, 10, 2, 'que htarafim דברו־ אוֹן e os que consultam viram mentira e as visões o que busca dirão-eles הֶ֖בֶל consolam sobre assim se levantaram como- rebanho responderão porque não o pastor:');
INSERT INTO verses VALUES (23088, 38, 10, 3, 'sobre [חָרָ֣ה] ira-se אפיתי e-sobre [כִּֽי־פָקַד֩] yhwh porque [אֶת־עֶדְרוֹ֙] yhwh [יְהוּדָ֔ה] a [אוֹתָ֔ם] a casa Judá e pôs a-eles cavalo na-guerra');
INSERT INTO verses VALUES (23089, 38, 10, 4, 'nós [פִנָּה֙] nós יָתֵ֔ד nós קֶ֣שֶׁת guerra nós saia todo nogesh juntos-verso');
INSERT INTO verses VALUES (23090, 38, 10, 5, 'e-sejam [כְגִבֹּרִ֜ים] [בּוֹסִ֨ים] [בְּטִ֤יט] [חוּצוֹת֙] na-guerra [וְנִ֨לְחֲמ֔וּ] que yhwh עִמָּם [וְהֹבִ֖ישׁוּ] montadores susim');
INSERT INTO verses VALUES (23091, 38, 10, 6, '[וְגִבַּרְתִּ֣י] a casa Judá e-[OBJ] casa José [וְהֽוֹשְׁבוֹתִים֙] que porque e-sejam e-serão como-que que [אֲנִ֛י] yhwh eu yhwh');
INSERT INTO verses VALUES (23092, 38, 10, 7, 'e-sejam כְגִבּוֹר֙ Efraim e-ele-se-alegrará לִבָּ֖ם como vinho וּבְנֵיהֶם֙ temerao וְשָׂמֵ֔חוּ יָגֵ֥ל לִבָּ֖ם em-Yahweh:');
INSERT INTO verses VALUES (23093, 38, 10, 8, 'אֶשְׁרְקָ֥ה a-eles וַאֲקַבְּצֵ֖ם que פְּדִיֹת e-multipliquem כְּ multiplicaram-se');
INSERT INTO verses VALUES (23094, 38, 10, 9, '[וְאֶזְרָעֵם֙] [בָּֽעַמִּ֔ים] [וּבַמֶּרְחַקִּ֖ים] [יִזְכְּר֑וּנִי] [וְחָי֥וּ] a [וָשָֽׁבוּ]');
INSERT INTO verses VALUES (23095, 38, 10, 10, '[וַהֲשִֽׁיבוֹתִים֙] da-terra Egito [וּמֵֽאַשּׁ֖וּר] [אֲקַבְּצֵ֑ם] e-a terra [וּלְבָנוֹן֙] [אֲבִיאֵ֔ם] [וְלֹ֥א] e-não a-eles');
INSERT INTO verses VALUES (23096, 38, 10, 11, 'e-passou בַּיָּ֜ם צָרָ֗ה וְהִכָּ֤ה בַיָּם֙ גַּלִּ֔ים וְהֹבִ֕ישׁוּ todo מְצוּל֣וֹת יְאֹ֑ר וְהוּרַד֙ orgulho Assur וְשֵׁ֥בֶט Egito יָסֽוּר׃');
INSERT INTO verses VALUES (23097, 38, 10, 12, 'וְגִבַּרְתִּים֙ em-יהוה e-no-seu-nome-o יִתְהַלָּ֑כוּ oráculo-de yhwh');
INSERT INTO chapters VALUES (923, 38, 11, 17);
INSERT INTO verses VALUES (23098, 38, 11, 1, 'פְּתַ֥ח לְבָנ֖וֹן דְּלָתֶ֑יךָ e-consuma fogo nos teus cedros:');
INSERT INTO verses VALUES (23099, 38, 11, 2, 'brilhou nas suas ramos porque caíram erez que aromas foram esmagados brilharam nos seus pinheiros que porque desceu Jáar');
INSERT INTO verses VALUES (23100, 38, 11, 3, 'voz as suas folhas das pastagens que שודדה אַדּוֹרְתָ֑ם voz shagat כְּפִירִ֔ים que שׁוֹדַּ֖ד glória o-Jordão');
INSERT INTO verses VALUES (23101, 38, 11, 4, 'assim disse yhwh meu-Elohim seu a rebanho a matem');
INSERT INTO verses VALUES (23102, 38, 11, 5, 'que seus compradores e matem e-não יֶאֱשָׁ֔מוּ e seus vendedores אָמַר bendito yhwh וַאֲשַׁר וְרֹעֵי אֹתָם não יַחְמֹל עֲלֵהֶן');
INSERT INTO verses VALUES (23103, 38, 11, 6, 'que não אֶחְמֹל ainda sobre a-terra a-terra oráculo-de eu e-eis eu מַמְצִיא a o-homem homem por-mão-de seu-proximo וּבְיַד מַלְכוֹ וְכִתֵּיתֻ a a-terra e-não אַצִּ֖יל mi-yada:');
INSERT INTO verses VALUES (23104, 38, 11, 7, '[וָֽאֶרְעֶה֙] a ovelhas [לָכֵ֖ן] [עֲנִיֵּ֣י] [הַצֹּ֑אן] [וָאֶקַּֽח־לִ֞י] [שְׁנֵ֣י] para-mim segundo [קָרָ֤אתִי] [נֹ֙עַם֙] [וּלְאַחַד֙] [קָרָ֣אתִי] [חֹֽבְלִ֔ים] [וָאֶרְעֶ֖ה] [אֶת־הַצֹּֽאן] a');
INSERT INTO verses VALUES (23105, 38, 11, 8, '[וָאַכְחִ֛ד] a três os-pastores um um [נַפְשִׁי֙] [בָּהֶ֔ם] neles e-também [בִֽי]');
INSERT INTO verses VALUES (23106, 38, 11, 9, 'e-eu-disse não eu-רעדה a-vós a morta morra e a que foi achada seja achada e as que foram levadas comeram mulher a de-a-carne sua irmã');
INSERT INTO verses VALUES (23107, 38, 11, 10, 'e-tomei a minha vara a ele e cortei a-ela para fazer brilhar a beriti que - eu cortei a todo הָעַמִּים׃');
INSERT INTO verses VALUES (23108, 38, 11, 11, 'e foi feita no-dia o-aquele e-souberam assim os pobres o-rebanho dos guardas a-mim que palavra-de ele ela');
INSERT INTO verses VALUES (23109, 38, 11, 12, 'e-disse a-eles se bom em vossos olhos dai minha recompensa e-se não - cessaram e pesaram a meu salário trinta כסף׃');
INSERT INTO verses VALUES (23110, 38, 11, 13, 'E-disse yhwh a-mim lançai-o fora a o formador tela o precioso que eu o vali deles e tomei trinta a-prata ele a-ele yhwh yhwh a o formador:');
INSERT INTO verses VALUES (23111, 38, 11, 14, 'e-egdá a malké o-segundo a ha-chóvlim le-hafér entre ha-acháva e-entre Judá e-entre Israel');
INSERT INTO verses VALUES (23112, 38, 11, 15, 'E-disse yhwh a-mim ainda toma para-ti כליה roé évili');
INSERT INTO verses VALUES (23113, 38, 11, 16, 'que eis-a eu levanta roé ba-áretz haníchchodót não יִפְקֹד֙ o-jovem não יְבַקֵּ֔שׁ וְהַנִּשְׁבֶּ֖רֶת não יְרַפֵּ֑א הַנִּצָּבָה֙ não יְכַלְכֵּ֔ל וּבְשַׂ֤ר הַבְּרִיאָה֙ יֹאכַ֔ל וּפַרְסֵיהֶ֖ן יְפָרֵֽק׃');
INSERT INTO verses VALUES (23114, 38, 11, 17, '[ה֣וֹי] [רֹעִ֤י] [הֽ͏ָאֱלִיל֙] [עֹזְבִ֣י] o-rebanho espada sobre [וְעַל־עֵ֣ין] e-sobre olho direita-de-ele [תִּיבָ֔שׁ] [וְעֵ֥ין] [יְמִינ֖וֹ] [כָּהֹ֥ה] [תִכְהֶֽה׃]');
INSERT INTO chapters VALUES (924, 38, 12, 14);
INSERT INTO verses VALUES (23115, 38, 12, 1, '[מַשָּׂ֥א] palavra-de yhwh sobre Israel oráculo-de yhwh [אָ֔רֶץ] céus [רֽוּחַ־אָדָ֖ם] terra homem');
INSERT INTO verses VALUES (23116, 38, 12, 2, 'eis eu nome a [סַף־רַ֛עַל] [לְכָל־הָעַמִּ֖ים] [סָבִ֑יב] para-todo [עַל־יְהוּדָ֛ה] será [בַמָּצ֖וֹר] sobre sobre');
INSERT INTO verses VALUES (23117, 38, 12, 3, 'e-foi no-dia-de هَالهُوَا אָשִׂימ pedra Jerusalém אבן مَعَامِسَة para-todo os-povos todo os seus pesos seu torto seriam tortos a-terra sobre-ela todo nações-de a-terra');
INSERT INTO verses VALUES (23118, 38, 12, 4, 'no-dia o-aquele oráculo-de yhwh eu maldizer-ei todo cavalo em suas iniquidades e seu cavaleiro em sua soberba e-sobre casa e-tudo eu abrir-ei a עֵינַי e-todo sūs debaixo eu maldizer-ei em sua ardência');
INSERT INTO verses VALUES (23119, 38, 12, 5, '[וְאָֽמְר֛וּ] [אַלֻּפֵ֥י] Judá [בְּלִבָּ֑ם] [אַמְצָ֥ה] a-mim habitantes-de Jerusalém [בַּיהוָ֥ה] de-exércitos אֱלֹהֵיהֶם-de-eles');
INSERT INTO verses VALUES (23120, 38, 12, 6, 'no-dia [הַה֡וּא] [אָשִׂים֩] a [יְהוּדָ֜ה] Judá [אֵ֣שׁ] fogo [וּכְלַפִּ֥יד] [אֵשׁ֙] fogo [וְאָ֨כְל֜וּ] [עַל־יָמִ֧ין] sobre [אֶת־כָּל־הָעַמִּ֖ים] e-sobre [וְיָשְׁבָ֨ה] a todo [תַּחְתֶּ֖יהָ] ao-redor');
INSERT INTO verses VALUES (23121, 38, 12, 7, 'והושע yhwh a aholei Judá no-primeiro-tempo para-que não תִגְדַּל תפארת casa-de דּוֹוִד ותפארת habitou Jerusalém sobre Judá');
INSERT INTO verses VALUES (23122, 38, 12, 8, 'no-dia aquele [יָגֵ֤ן] yhwh [בְּעַד֙] habitante-de Jerusalém e-será [הַנִּכְשָׁ֥ל] [בָּהֶ֛ם] no-dia o-aquele [כְּדָוִ֑יד] [וּבֵ֤ית] Davi como-Elohim [כְּמַלְאַ֥ךְ] yhwh diante-deles');
INSERT INTO verses VALUES (23123, 38, 12, 9, 'e-foi no-dia aquele [אֲבַקֵּ֗שׁ] [לְהַשְׁמִיד֙] a todo as-nações sobre');
INSERT INTO verses VALUES (23124, 38, 12, 10, '[וְשָׁפַכְתִּי֩] sobre casa [וְעַ֣ל] [׀] habitante-de Jerusalém espírito graça [וְתַ֣חֲנוּנִ֔ים] [וְהִבִּ֥יטוּ] a-mim a que [וְסָפְד֣וּ] [עָלָ֗יו] sobre-ele [עַל־הַיָּחִ֔יד] sobre [עָלָ֖יו] [כְּהָמֵ֥ר] sobre-ele sobre');
INSERT INTO verses VALUES (23125, 38, 12, 11, 'no-dia aquele [יִגְדַּ֤ל] [הַמִּסְפֵּד֙] em-Jerusalém [כְּמִסְפַּ֥ד] [הֲדַדְ־רִמּ֖וֹן] [בְּבִקְעַ֥ת] [מְגִדּֽוֹן]');
INSERT INTO verses VALUES (23126, 38, 12, 12, 'וְסָפְדָ֣ה a-terra מִשְׁפָּח֥וֹת מִשְׁפָּח֖וֹת sozinho מִשְׁפַּ֨חַת casa-de Davi לְבָד֙ וּנְשֵׁיהֶ֣ם sozinho família-de casa-de deu sozinho e suas mulheres לְבָֽד׃');
INSERT INTO verses VALUES (23127, 38, 12, 13, 'família-de casa-de Levi sozinho e suas mulheres sozinho família-de השמعي sozinho e suas mulheres por si só');
INSERT INTO verses VALUES (23128, 38, 12, 14, 'todo הַמִּשְׁפָּחוֹת֙ הַנִּשְׁאָר֔וֹת מִשְׁפָּחֹ֥ת מִשְׁפָּחֹ֖ת sozinho e suas mulheres por si só');
INSERT INTO chapters VALUES (925, 38, 13, 9);
INSERT INTO verses VALUES (23129, 38, 13, 1, 'no-dia aquele será מָק֣וֹר נִפְתָּ֔ח segundo-casa-de David וּלְיֹשְׁבֵ֣י Jerusalém לְחַטַּ֖את e-a-nidá:');
INSERT INTO verses VALUES (23130, 38, 13, 2, 'e-será no-dia o-aquele [נְאֻ֣ם] yhwh yhwh acrit a Shmot os-açabim de a-terra e-não serão-lembrados ainda e-também a os-nabi''im e-a espírito a-tum''áh eu-levarei de a-terra');
INSERT INTO verses VALUES (23131, 38, 13, 3, 'e-foi porque será profetizado homem ainda- a-ele seu-pai seu pai e sua mãe não não que porque mentira falaste yhwh yhwh e o desmascareis seu pai e sua mãe que gerou eis que');
INSERT INTO verses VALUES (23132, 38, 13, 4, 'e-era em-o-dia no-dia יֵבֹ֧שׁוּ os profetas homem de sua visão בְּהִנָּֽבְאֹת֑וֹ e-não יִלְבְּשׁ֛וּ אַדֶּ֥רֶת שֵׂעָ֖ר para כַּחֵֽשׁ׃');
INSERT INTO verses VALUES (23133, 38, 13, 5, '[וְאָמַ֕ר] não profeta eu homem-de terra eu que homem homem [מִנְּעוּרָֽי]');
INSERT INTO verses VALUES (23134, 38, 13, 6, 'e disse a-ele מה הַמַּכּ֛וֹת estes entre as tuas mãos וְאָמַ֕ר que הוכיתי casa מאהבי׃');
INSERT INTO verses VALUES (23135, 38, 13, 7, 'espada [עוּרִ֤י] sobre [וְעַל־גֶּ֣בֶר] e-sobre [נְאֻ֖ם] yhwh oráculo-de yhwh exércitos [וּתְפוּצֶ֣יןָ] a [וַהֲשִׁבֹתִ֥י] [יָדִ֖י] o-rebanho sobre');
INSERT INTO verses VALUES (23136, 38, 13, 8, 'e-era em-todo a-terra oráculo-de yhwh boca-de dois em-ela יחרתו יִגְוָ֑עוּ וְהַשְׁלִשִׁ֖ית יִוּ֥תֶר nela');
INSERT INTO verses VALUES (23137, 38, 13, 9, 'e-eu-trarei a וְהַשְׁלִשִׁ֖ית no-fogo וּצְרַפְתִּים֙ כִּצְרֹ֣ף a a-prata וּבְחַנְתִּ֖ים ele a chamaria ele chamar בִשְׁמִ֗י ele אֶעֱנֶ֣ה a-ele ele meu-povo ele yhwh יֹאמַ֖ר yhwh yhwh');
INSERT INTO chapters VALUES (926, 38, 14, 21);
INSERT INTO verses VALUES (23138, 38, 14, 1, 'eis [יֽוֹם־בָּ֖א] veio para-יהוה [שְׁלָלֵ֖ךְ] [בְּקִרְבֵּֽךְ]');
INSERT INTO verses VALUES (23139, 38, 14, 2, 'וְאָסַפְתִּ֨י a todo הַגּוֹיִ֥ם ׀ a יְרוּשָׁלִַם֮ לַמִּלְחָמָה֒ וְנִלְכְּדָ֣ה a-cidade וְנָשַׁ֙סּוּ֙ as-bat-tim e-as-mulheres e-yatsa chati a-cidade be-golah e restante o-povo não yikkaret de a-cidade');
INSERT INTO verses VALUES (23140, 38, 14, 3, 'e-sairá yhwh e-lutaremos be-goyim os-aqueles como um dia hil-lachamo em-dia karev');
INSERT INTO verses VALUES (23141, 38, 14, 4, 'e-amdu reglayav no-dia- הַ֠הוּא sobre הַ֨ר הַזֵּתִ֜ים que ao-oriente face-de יְרוּשָׁלִַם֮ מִקֶּדֶם֒ וְנִבְקַע֩ הַ֨ר הַזֵּיתִים מֵֽחֶצְיוֹ֙ leste muito vale grande muito e mês metade-de o monte צָפ֖וֹנָה e metade- ao-sul');
INSERT INTO verses VALUES (23142, 38, 14, 5, 'e estender-se- גֵּֽיא־ os raios porque atingirá valores- as montanhas a de-diante-de e-nastem como-que nastem de-diante-de hara''ash yhwh uzziya rei-de Judá e-ele-virá yhwh meu-Elohim todo ele contigo');
INSERT INTO verses VALUES (23143, 38, 14, 6, 'e-foi no-dia o-aquele não luz luz que sejam preciosas');
INSERT INTO verses VALUES (23144, 38, 14, 7, 'e-foi dia-de ele ele yidua a-yhwh não dia e-não noite a-ti le-etu- tarde ele-será- luz');
INSERT INTO verses VALUES (23145, 38, 14, 8, 'e-era em-o-dia no-dia yetseu מים־ vidos de-Jerusalém chetziyam a o mar o-primeiro ve-chetziyam a o mar הָאַחֲר֑וֹן será u-bachoref será');
INSERT INTO verses VALUES (23146, 38, 14, 9, 'e será yhwh para-rei sobre no-dia a-terra será yhwh um yhwh um e-nome-dele um');
INSERT INTO verses VALUES (23147, 38, 14, 10, 'yissov todo a-terra Kăl-ʿarābah Miggēvā'' Lerimmōn Nēgēb jerusalém Ve-rāʾamāh Ve-yāšvāh Taḥṭehā'' Lemishʿar Benjamim até Mekōm porta-de a-primeira até portão até Umigdāl Hananeel até יִקְבֵ֥י o rei');
INSERT INTO verses VALUES (23148, 38, 14, 11, '[וְיָ֣שְׁבוּ] nela [וְחֵ֖רֶם] não ele-será- ainda [יְרוּשָׁלַ֖͏ִם] Jerusalém');
INSERT INTO verses VALUES (23149, 38, 14, 12, 've-zot תִּֽהְיֶ֣ה הַמַּגֵּפָ֗ה que יִגֹּ֤ף yhwh yhwh todo os-povos que צָבְא֖וּ sobre Jerusalém הָמֵ֣ק ׀ be-saro e-ele ficou-em-pé sobre seus-pes וְעֵינָיו֙ תִּמַּ֣קְנָה בְחֹֽרֵיהֶ֔ן וּלְשׁוֹנ֖וֹ תִּמַּ֥ק em-cls:');
INSERT INTO verses VALUES (23150, 38, 14, 13, 'e-foi no-dia aquele תִּֽהְיֶ֧ה de-tumulto-de yhwh multiplicai com-eles וְהֶחֱזִ֗יקוּ homem mão companheiro-seu sua-mão mão-sua sobre mão seu-amigo');
INSERT INTO verses VALUES (23151, 38, 14, 14, 'e também Judá תִּלָּחֵ֖ם be-Yerushalaim וְאֻסַּף֩ chail todo ouro ao-redor ouro וָכֶ֛סֶף muito לָרֹ֥ב muito');
INSERT INTO verses VALUES (23152, 38, 14, 15, 'e-assim תִּֽהְיֶ֜ה maggafá ha-sus ha-pered ha-gamal ve-ha-chamor e-todo a-animal será será bamachonot ha-hemá kamaggafá a esta');
INSERT INTO verses VALUES (23153, 38, 14, 16, 'e-foi todo o-restante de-todo as-nações os-vindos sobre jerusalém ve-''alú middei ano yhwh para se prostrar para-o-rei yhwh exércitos e cantar a festa-de as tendas');
INSERT INTO verses VALUES (23154, 38, 14, 17, 'e será que não subirá de-a a-terra a-terra a Jerusalém yhwh para-rei yhwh exércitos será sobre-eles será הַגָּֽשֶׁם׃');
INSERT INTO verses VALUES (23155, 38, 14, 18, 'e-se da família do Egito não subirá e-não na primavera e-não sobre-eles será a praga yhwh כינים yhwh não as-nações que não יעלו לחוג a festa-de הסוכות׃');
INSERT INTO verses VALUES (23156, 38, 14, 19, 'esta será chéttā''ath Egito והatta'' todo as-nações não não יעלו לחוג a festa-de הסוכות׃');
INSERT INTO verses VALUES (23157, 38, 14, 20, 'no-dia aquele será sobre מצלות הסוס santidade para-יהוה e-era הסירוות yhwh yhwh como-aspas diante-de o-altar');
INSERT INTO verses VALUES (23158, 38, 14, 21, 'e será todo ferveu em-Jerusalém e-em-Juda santo a-yhwh exércitos e-vieram todo os-que-ofereceram e-levaram-no deles e-cozinharão bahêm e-não for Canaanita no-dia na-casa-de yhwh de-exércitos no-dia a-aquela');
INSERT INTO books VALUES (39, 'MAL', 'Malaquias', 'AT', 3);
INSERT INTO chapters VALUES (927, 39, 1, 14);
INSERT INTO verses VALUES (23159, 39, 1, 1, 'massa- palavra-de yhwh a Israel na-mão-de מלאכי:');
INSERT INTO verses VALUES (23160, 39, 1, 2, 'Eu amei vos disse yhwh e-disseis por qual você me amou porventura-não irmão עשו לְיַֽעֲקֹב֙ oráculo-de yhwh e eu amei a Jacó');
INSERT INTO verses VALUES (23161, 39, 1, 3, 'e-a Esaú שָׂנֵ֑אתִי e eu fiz a eu o feri שממה e-a seu-pai para mentir מִדְבַּר׃');
INSERT INTO verses VALUES (23162, 39, 1, 4, 'porque você dirá אֱדוֹם רֻשׁוּ וְנָשׁוּב וְנִבְנֶה חֲרוֹבֹת disse yhwh yhwh exércitos eles יִבְנוּ e-eu אֶהְרֹוס a-eles para-eles território iniquidade וְהָעָם yhwh זָעַם yhwh até eternidade');
INSERT INTO verses VALUES (23163, 39, 1, 5, '[וְעֵינֵיכֶ֖ם] [תִּרְאֶ֑ינָה] [וְאַתֶּ֤ם] [תֹּֽאמְרוּ֙] [יִגְדַּ֣ל] yhwh de-cima-de [לִגְב֥וּל] Israel');
INSERT INTO verses VALUES (23164, 39, 1, 6, 'filho יְכַבֵּ֥ד pai וְעֶ֣בֶד seu-mestre e-se pai אָ֣נִי onde כְבוֹדִ֡י e-se אֲדוֹנִ֣ים אָנִי֩ disse Mo''rā''ī yhwh yhwh a-vós para-vocês os-sacerdotes Bozē'' Šəmî e-vós-direis Bammeh Ba''zīnū a Šheme''kā:');
INSERT INTO verses VALUES (23165, 39, 1, 7, 'Maggishim sobre pão pão Megō''al e-disseis Bammeh Gē''ālнуkha בֶּאֱמָרְכֶ֕ם yhwh yhwh ele ela');
INSERT INTO verses VALUES (23166, 39, 1, 8, 'e-quando תַגִּשׁ֨וּן עִוֵּ֤ר לִזְבֹּ֙חַ֙ mal mau e-que תַגִּישׁוּ פִּסֵּ֥חַ וְחֹלֶ֖ה mal mau הַקְרִיבֵ֨הוּ por-favor לְפֶחָתֶ֗ךָ הֲיִּרְצְךָ֙ ou הֲיִשָׂא disse yhwh yhwh exércitos');
INSERT INTO verses VALUES (23167, 39, 1, 9, 'e-agora חַלּוּ־ agora פנים- El era מִיֶּדְכֶם֙ foi esta הֲיִשָׂא disse yhwh disse yhwh exércitos');
INSERT INTO verses VALUES (23168, 39, 1, 10, 'quem também [וְיִסְגֹּ֣ר] [דְּלָתַ֔יִם] [וְלֹֽא־תָאִ֥ירוּ] e-não [חִנָּ֑ם] [אֵֽין־לִ֨י] [חֵ֜פֶץ] não-há disse yhwh [צְבָא֔וֹת] disse yhwh exércitos não');
INSERT INTO verses VALUES (23169, 39, 1, 11, 'que [מִמִּזְרַח־שֶׁ֜מֶשׁ] [וְעַד־מְבוֹא֗וֹ] e-até [שְׁמִי֙] grande [וּבְכָל־מָק֗וֹם] entre-as-nações e-em-todo lugar [וּמִנְחָ֣ה] [טְהוֹרָ֑ה] [כִּֽי־גָד֤וֹל] [שְׁמִי֙] [בַּגּוֹיִ֔ם] disse yhwh [צְבָאֽוֹת] disse yhwh');
INSERT INTO verses VALUES (23170, 39, 1, 12, 'e-vós tocando [אוֹת֑וֹ] [בֶּאֱמָרְכֶ֗ם] [שֻׁלְחַ֤ן] Adonai [מְגֹאָ֣ל] ele [וְנִיב֖וֹ] [נִבְזֶ֥ה] [אָכְלֽוֹ]');
INSERT INTO verses VALUES (23171, 39, 1, 13, 'וַאֲמַרְתֶּם֩ eis מַתְּלָאָ֜ה וְהִפַּחְתֶּ֣ם אותו disse yhwh exércitos vahavetem גָּז֗וּל e-a o pasach e-a a doente e vós trareis a a-oferenda disse yhwh dos vossos disse yhwh');
INSERT INTO verses VALUES (23172, 39, 1, 14, 'e maldito que come e-ha em seu lugar macho e jurarei e sacrifique ungüento para o Adonai que rei grande eu disse yhwh exércitos e o meu nome assustador בַגּוֹיִֽים׃');
INSERT INTO chapters VALUES (928, 39, 2, 17);
INSERT INTO verses VALUES (23173, 39, 2, 1, 'e-agora aleichem a ordem a-esta os sacerdotes:');
INSERT INTO verses VALUES (23174, 39, 2, 2, 'se não ouvireis e-se não por mim sobre coração disse yhwh ao meu nome disse yhwh exércitos וְשִׁלַּחְתִּ֤י em vós a a claridade que a nas bênçãos e-também suas fontes porque אַנְتֶֽם céus sobre coração');
INSERT INTO verses VALUES (23175, 39, 2, 3, 'eis-me [גֹעֵ֤ר] a-vós a [וְזֵרִ֤יתִי] [פֶ֙רֶשׁ֙] [עַל־פְּנֵיכֶ֔ם] sobre [חַגֵּיכֶ֑ם] [וְנָשָׂ֥א] [אֶתְכֶ֖ם] a-ele');
INSERT INTO verses VALUES (23176, 39, 2, 4, 'וִֽידַעְתֶּ֕ם que שָׁלַחְתִּי a-vós a הַמִּצְוָה esta ser aliança-minha a disse yhwh yhwh exércitos');
INSERT INTO verses VALUES (23177, 39, 2, 5, 'minha aliança ela-foi era a vida a-vida e dei-lhe a-ele temor e me temeu e diante de nome-meu sedei ele');
INSERT INTO verses VALUES (23178, 39, 2, 6, 'תּוֹרַ֤ת verdade era em sua boca e desobediência não foi-achado em-su-pátiy b-shálom andar andou comigo vé-rábíym השיב m-é''awn');
INSERT INTO verses VALUES (23179, 39, 2, 7, 'porque שַׂפְתֵ֤י sacerdote yish-márû- conhecimento vé-toráh que m-pí-yahu porque ele yhwh- de-exércitos ela');
INSERT INTO verses VALUES (23180, 39, 2, 8, 'e-vós שָׂרְתֶּם de a-de-ré-kh hiksháltem muitos בתורה shíkháttem aliança disse yhwh yhwh exércitos');
INSERT INTO verses VALUES (23181, 39, 2, 9, 'e-também dei [אֶתְכֶ֛ם] a-vós [וּשְׁפָלִ֖ים] [לְכָל־הָעָ֑ם] para-todo o-povo [אֵֽינְכֶם֙] que não-vós [וְנֹשְׂאִ֥ים] a [בַּתּוֹרָֽה׃] face');
INSERT INTO verses VALUES (23182, 39, 2, 10, 'porventura-não pai um לכלנוו acaso-nao El um בראנוו madua'' ניבגד homem ב אחיו para profanar berit nosso-Pai');
INSERT INTO verses VALUES (23183, 39, 2, 11, 'a traição Judá e abominação foi feita em Israel e em Jerusalém que profanou Judá santo-de yhwh yhwh amou e com o senhor filha-de El foi rejeitado');
INSERT INTO verses VALUES (23184, 39, 2, 12, 'cortará yhwh para o homem que faça virgem e rapina dos acampamentos de Jacó e traga oferenda a-yhwh exércitos');
INSERT INTO verses VALUES (23185, 39, 2, 13, 've-zot segunda façam como casamentos דִּמְעָה֙ a yhwh yhwh porque e anaque mêʾēn ainda פנות a a oferta-cereais וְלָקַ֥חַת רָצ֖וֹן מִיֶּדְכֶֽם׃');
INSERT INTO verses VALUES (23186, 39, 2, 14, '[וַאֲמַרְתֶּ֖ם] sobre sobre sobre porque entre-ti e-entre [׀] [אֵ֣שֶׁת] mulher-de [אֲשֶׁ֤ר] tu tu [בָּ֔הּ] em-ela e ela [וְאֵ֥שֶׁת] [בְּרִיתֶֽךָ]');
INSERT INTO verses VALUES (23187, 39, 2, 15, 'e-não um fez espírito a-ele a-ele o-primeiro [מְבַקֵּ֖שׁ] semente semente Elohim [בְּר֣וּחֲכֶ֔ם] [וּבְאֵ֥שֶׁת] [נְעוּרֶ֖יךָ] [אַל־יִבְגֹּֽד] a');
INSERT INTO verses VALUES (23188, 39, 2, 16, 'porque odiou disse yhwh yhwh Elohim-de Israel וְכִסּ֤ה חָמָס֙ disse yhwh disse yhwh exércitos venishmartem בְּרוּחֲכֶ֖ם e-não eles trairão');
INSERT INTO verses VALUES (23189, 39, 2, 17, 'hogā''te''em yhwh bədibre''kem bamma'' hogā''nu bə''amarke''m todo fez mal bom em-olhos-de yhwh yhwh ele ele ou onde Elohim-de הַמִּשְׁפָּֽט׃');
INSERT INTO chapters VALUES (929, 39, 3, 24);
INSERT INTO verses VALUES (23190, 39, 3, 1, 'eis-me enviou malakhi u芬nah- caminho diante-de-mim u pit''om- vira a hēkālō ha''adōn que vós מְבַקְשִׁ֗ים וּמַלְאַ֨ךְ הַבְּרִ֜ית que disse yhwh eis-que- veio disse yhwh exércitos');
INSERT INTO verses VALUES (23191, 39, 3, 2, 'e-quem [מְכַלְכֵּל֙] a dia [וּמִ֥י] e-quem [בְּהֵרָֽאוֹת֑וֹ] [כִּֽי־הוּא֙] porque ele [וּכְבֹרִ֖ית] [מְכַבְּסִֽים]');
INSERT INTO verses VALUES (23192, 39, 3, 3, 'וְיָשַׁ֨ב fabricante e purificador prata e purificou a filhos-de eles e espremeu a-eles e-sejam e com prata serão a-yhwh enviadores oferta בִּצְדָקָֽה׃');
INSERT INTO verses VALUES (23193, 39, 3, 4, 'e aliança a-yhwh oferenda-de Judá e Jerusalém nos dias de eternidade e-cashanim qadmoniyot');
INSERT INTO verses VALUES (23194, 39, 3, 5, 've-qaravti al-ekhem lamishpat ve-hayiti até memaher bamakashafim u-bamana''im u-banissheba''im para mentira e nos queixos de salário- salariado viúva e órfão e nas mãos de estrangeiro e-não disse yhwh yhwh exércitos');
INSERT INTO verses VALUES (23195, 39, 3, 6, 'que eu yhwh não minha e vós filhos-de não não guardastes:');
INSERT INTO verses VALUES (23196, 39, 3, 7, 'לְמִימֵ֨י אֲבֹתֵיכֶ֜ם סַרְתֶּ֤ם מֵֽחֻקַּי֙ e-não שְׁמַרְתֶּ֔ם שׁ֤וּבוּ a-mim וְאָשׁ֣וּבָה a-vós disse yhwh exércitos e-disseis בַּמֶּ֥ה נָשֽׁוּב׃');
INSERT INTO verses VALUES (23197, 39, 3, 8, 'הֲיִקְבַּ֨ע homem Elohim que vós קֹבְעִים a-mim e-disseis בַּמֶּ֣ה קְבַעֲנ֑וּךָ הַֽמַּעֲשֵׂ֖ר וְהַתְּרוּמָֽה׃');
INSERT INTO verses VALUES (23198, 39, 3, 9, 'בַּמְּאֵרָה֙ vós נֵֽאָרִ֔ים וְאֹתִ֖י vós קֹבְעִ֑ים o-povo כלו׃');
INSERT INTO verses VALUES (23199, 39, 3, 10, 'הָבִ֨יאוּ a todo o décimo e-seja casa a arrecadação E-foi teref בְּבֵיתִ֔י disse yhwh nisto disse yhwh a-vós se não אֶפְתַּ֣ח para-vós a-vós aruboth até e eu dispersaria a-vós ברכה até sem suficiente:');
INSERT INTO verses VALUES (23200, 39, 3, 11, 'e eu repreenderia a-vós em comer e-não a-vós para-vocês a-terra fruto a-vós e-não teshakkal disse yhwh no-campo disse yhwh exércitos');
INSERT INTO verses VALUES (23201, 39, 3, 12, 've''ishru vos todo as-nações porque terra vós disse yhwh disse yhwh exércitos');
INSERT INTO verses VALUES (23202, 39, 3, 13, 'chazku sobre-mim dibreikhem disse yhwh e-vós-direis que nidbernu sobre-te');
INSERT INTO verses VALUES (23203, 39, 3, 14, 'amarthem vazio servo Elohim e-que que porque shamarunu mishmarato e-que halchnu de-diante-de yhwh yhwh exércitos');
INSERT INTO verses VALUES (23204, 39, 3, 15, 'e-agora nos me''ashirim זֵדִים também נִבְנוּ עֹשֵׂי também também provaram Elohim וַיִּמָּלֵֽטוּ׃');
INSERT INTO verses VALUES (23205, 39, 3, 16, '[אָ֧ז] [נִדְבְּר֛וּ] [יִרְאֵ֥י] yhwh homem a companheiro-seu yhwh yhwh E-ouviu [סֵ֣פֶר] livro [לְפָנָיו֙] diante-dele yhwh yhwh [שְׁמֽוֹ]');
INSERT INTO verses VALUES (23206, 39, 3, 17, 'e-sejam para-mim disse yhwh exércitos לַיּ֕וֹם que eu fez segulá e eu teria compaixão sobre-eles como-que ele teria compaixão homem sobre filho-seu ele ele');
INSERT INTO verses VALUES (23207, 39, 3, 18, 'e voltaríeis e veríeis entre justo para o malvado entre servo Elohim que não עֲבָדֽוֹ׃');
INSERT INTO verses VALUES (23208, 39, 3, 19, 'porque o-dia o-dia veio foge e-sejam ve-hayu todo zédim e-todo fez eles o-dia e se entretivesse disse yhwh o-que-vem disse yhwh a-eles que não יַעֲזֹ֥ב a-eles שורש ו ענהף׃');
INSERT INTO verses VALUES (23209, 39, 3, 20, 'ו זרחא׃ a-vós יראי shmiei שמש צדקה ומרפאה בקנפייהה ויצאו׃ e fizerdes como antílopes de Marbeque:');
INSERT INTO verses VALUES (23210, 39, 3, 21, 'e façais rasha''im porque serão debaixo sob plantas-de no-dia בַּיּוֹם֙ que eu disse yhwh yhwh exércitos');
INSERT INTO verses VALUES (23211, 39, 3, 22, 'lembrai-vos lei-de Moisés meu servo que eu ordenei a ele no Horebe sobre todo Israel chuqim e em juízos:');
INSERT INTO verses VALUES (23212, 39, 3, 23, 'eis eu enviou a-vós a Elias o-profeta lifnei trazer dia yhwh o-grande ve-hanora');
INSERT INTO verses VALUES (23213, 39, 3, 24, 'e-pagava coração-de [עַל־בָּנִ֔ים] sobre [בָּנִ֖ים] [עַל־אֲבוֹתָ֑ם] filhos sobre pais-deles para-que-não a a-terra');
INSERT INTO books VALUES (40, 'MAT', 'Mateus', 'NT', 28);
INSERT INTO chapters VALUES (930, 40, 1, 25);
INSERT INTO verses VALUES (23214, 40, 1, 1, 'livro origem Iesous de-Christos do-Filho Davi do-Filho Abraão');
INSERT INTO verses VALUES (23215, 40, 1, 2, 'Abraão gerou o Isaque Isaque porém gerou o Jacó Jacó porém gerou o Judas e o irmãos dele');
INSERT INTO verses VALUES (23216, 40, 1, 3, 'Judas porém gerou o Fares e o Zará de o Tamar Fares porém gerou o Esrom Esrom porém gerou o Arão');
INSERT INTO verses VALUES (23217, 40, 1, 4, 'Arão porém gerou o Aminadabe Aminadabe porém gerou o Naassom Naassom porém gerou o Salmom');
INSERT INTO verses VALUES (23218, 40, 1, 5, 'Salmom porém gerou o Boaz de o Raabe Boaz porém gerou o Obede de o Rute Obede porém gerou o Jessé');
INSERT INTO verses VALUES (23219, 40, 1, 6, 'Jessé porém gerou o Davi o rei Davi porém gerou o Salomão de o o Urias');
INSERT INTO verses VALUES (23220, 40, 1, 7, 'Salomão porém gerou o Roboão Roboão porém gerou o Abia Abias porém gerou o Asafe');
INSERT INTO verses VALUES (23221, 40, 1, 8, 'Asafe porém gerou o Josafá Josafá porém gerou o Jorão Jorão porém gerou o Ozias');
INSERT INTO verses VALUES (23222, 40, 1, 9, 'Ozias porém gerou o Joatão Joatão porém gerou o Acaz Acaz porém gerou o Ezequias');
INSERT INTO verses VALUES (23223, 40, 1, 10, 'Ezequias porém gerou o Manassés Manassés porém gerou o Amós Amós porém gerou o Josias');
INSERT INTO verses VALUES (23224, 40, 1, 11, 'Josias porém gerou o Jeconias e o irmãos dele sobre o deportação Babilônia');
INSERT INTO verses VALUES (23225, 40, 1, 12, 'com porém o deportação Babilônia Jeconias gerou o Salatiel Salatiel porém gerou o Zorobabel');
INSERT INTO verses VALUES (23226, 40, 1, 13, 'Zorobabel porém gerou o Abiúde Abiúde porém gerou o Eliaquim Eliaquim porém gerou o Azor');
INSERT INTO verses VALUES (23227, 40, 1, 14, 'Azor porém gerou o Sadoque Sadoque porém gerou o Aquim Aquim porém gerou o Eliúde');
INSERT INTO verses VALUES (23228, 40, 1, 15, 'Eliúde porém gerou o Eleazar Eleazar porém gerou o Matã Matã porém gerou o Jacó');
INSERT INTO verses VALUES (23229, 40, 1, 16, 'Jacó porém gerou o José o homem Maria de o qual foi-gerado Iesous o chamado Christos');
INSERT INTO verses VALUES (23230, 40, 1, 17, 'todas portanto o gerações de Abraão até Davi gerações quatorze e de Davi até o deportação Babilônia gerações quatorze e de o deportação Babilônia até o de-Christos gerações quatorze');
INSERT INTO verses VALUES (23231, 40, 1, 18, 'o porém Iesous de-Christos o origem assim era tendo-sido-desposada o mãe dele Maria o José antes-de ou reunir-se eles foi-encontrado em ventre tendo de do-espírito do-santo');
INSERT INTO verses VALUES (23232, 40, 1, 19, 'José porém o homem dela justo sendo e não querendo ela expor-publicamente quis secretamente soltar ela');
INSERT INTO verses VALUES (23233, 40, 1, 20, 'estas-coisas porém dele tendo-pensado eis anjo do-Kyrios segundo sonho apareceu a ele dizendo José Filho Davi não temas tomar Maria o mulher teu o pois em a-ela tendo-sido-gerado de Espírito é do-santo');
INSERT INTO verses VALUES (23234, 40, 1, 21, 'gerará porém Filho e chamarás o nome dele Iesous ele pois salvará o povo dele de o pecados deles');
INSERT INTO verses VALUES (23235, 40, 1, 22, 'isto porém todo aconteceu para que seja-cumprido o o-dito sob do-Kyrios através-de o profeta dizendo');
INSERT INTO verses VALUES (23236, 40, 1, 23, 'Eis o virgem em ventre terá e gerará filho e chamarão o nome dele Emanuel o qual é sendo-traduzido com nosso o Theos');
INSERT INTO verses VALUES (23237, 40, 1, 24, 'levantando-se porém o José de o sono fez como ordenou a ele o anjo do-Kyrios e recebeu o mulher dele');
INSERT INTO verses VALUES (23238, 40, 1, 25, 'e não conhecia ela até o qual deu-à-luz filho e chamou o nome dele Iesous');
INSERT INTO chapters VALUES (931, 40, 2, 23);
INSERT INTO verses VALUES (23239, 40, 2, 1, 'o porém Iesous tendo-sido-gerado em Belém o Judeia em dias de-Herodes o rei eis magos de oriente apresentaram-se para Jerusalém');
INSERT INTO verses VALUES (23240, 40, 2, 2, 'dizendo onde é o tendo-sido-gerado rei o judeus vimos pois dele o estrela em o oriente e viemos adorar a ele');
INSERT INTO verses VALUES (23241, 40, 2, 3, 'ouvindo porém o rei Herodes perturbou-se e toda Jerusalém com dele');
INSERT INTO verses VALUES (23242, 40, 2, 4, 'e tendo-reunido todos o sumos-sacerdotes e escribas o povo inquiria de deles onde o Christos é-gerado');
INSERT INTO verses VALUES (23243, 40, 2, 5, 'o porém disseram a ele em Belém o Judeia assim pois está-escrito através-de o profeta');
INSERT INTO verses VALUES (23244, 40, 2, 6, 'e tu Belém terra Judá de-modo-algum mínima és em o governadores Judá de teu pois sairá liderando qualquer-que apascentará o povo meu o Israel');
INSERT INTO verses VALUES (23245, 40, 2, 7, 'Então Herodes secretamente chamando o magos averiguou-cuidadosamente de-junto-de deles o tempo o aparecendo estrela');
INSERT INTO verses VALUES (23246, 40, 2, 8, 'e tendo-enviado eles para Belém disse Tendo-ido examinai com-exatidão acerca-de o criança quando porém encontreis anunciai a-mim para-que e-eu vindo prostrar-me-ei a ele');
INSERT INTO verses VALUES (23247, 40, 2, 9, 'o porém ouvindo o rei foram e eis o estrela o qual vi em o oriente conduzia-adiante eles até vindo colocou-se sobre do-qual era o criança');
INSERT INTO verses VALUES (23248, 40, 2, 10, 'vendo porém o estrela alegraram-se alegria grande extremamente');
INSERT INTO verses VALUES (23249, 40, 2, 11, 'e vindo para o casa vi o criança com Maria o mãe dele e tendo-caído adoraram a ele e tendo-aberto o tesouros deles trouxeram a ele presentes ouro e olíbano e mirra');
INSERT INTO verses VALUES (23250, 40, 2, 12, 'e tendo-sido-advertidos-divinamente segundo sonho não retornar junto-a Herodes através-de outra do-caminho retiraram-se para o região deles');
INSERT INTO verses VALUES (23251, 40, 2, 13, 'Tendo-se-retirado porém deles eis anjo do-Kyrios aparece segundo sonho o José dizendo Tendo-sido-levantado recebe o criança e o mãe dele e foge para Egito e sê ali até partícula-condicional diga a-ti está-para pois Herodes buscar o criança o destruir isso');
INSERT INTO verses VALUES (23252, 40, 2, 14, 'o porém levantando-se recebeu o criança e o mãe dele noite e retirou-se para Egito');
INSERT INTO verses VALUES (23253, 40, 2, 15, 'e era ali até o de-morte de-Herodes para que seja-cumprido o o-dito sob do-Kyrios através-de o profeta dizendo de Egito chamei o filho meu');
INSERT INTO verses VALUES (23254, 40, 2, 16, 'Então Herodes vendo que foi-escarnecido sob o magos irou-se muito e enviando matou todos o crianças o em Belém e em todos o limites dela de de-dois-anos e mais-abaixo segundo o tempo o qual averiguou-cuidadosamente de-junto-de o magos');
INSERT INTO verses VALUES (23255, 40, 2, 17, 'então foi-cumprido o o-dito através-de Jeremias o profeta dizendo');
INSERT INTO verses VALUES (23256, 40, 2, 18, 'voz em Ramá foi-ouvido choro e lamento muito Raquel chorando o filhos dela e não queria ser-consolado que não são');
INSERT INTO verses VALUES (23257, 40, 2, 19, 'Tendo-morrido porém o de-Herodes eis anjo do-Kyrios aparece segundo sonho o José em Egito');
INSERT INTO verses VALUES (23258, 40, 2, 20, 'dizendo Tendo-sido-levantado recebe o criança e o mãe dele e vai para terra Israel têm-morrido pois o buscando o alma o criança');
INSERT INTO verses VALUES (23259, 40, 2, 21, 'o porém levantando-se recebeu o criança e o mãe dele e entrou para terra Israel');
INSERT INTO verses VALUES (23260, 40, 2, 22, 'ouvindo porém que Arquelau reina o Judeia em-troca-de o do-Pai dele de-Herodes temeu ali ir-embora tendo-sido-avisado-divinamente porém segundo sonho retirou-se para o partes o Galileia');
INSERT INTO verses VALUES (23261, 40, 2, 23, 'e vindo habitou para cidade chamada Nazaré para-que seja-cumprido o o-dito através-de o profetas que nazareno será-chamado');
INSERT INTO chapters VALUES (932, 40, 3, 17);
INSERT INTO verses VALUES (23262, 40, 3, 1, 'em porém o dias aqueles chega João o batista pregando em o deserto o Judeia');
INSERT INTO verses VALUES (23263, 40, 3, 2, 'dizendo Arrependei-vos aproximou-se pois o reino o dos-céus');
INSERT INTO verses VALUES (23264, 40, 3, 3, 'este pois é o tendo-sido-dito através-de Isaías o profeta dizendo voz clamando em o deserto Preparai o caminho do-Kyrios retas fazei o caminhos dele');
INSERT INTO verses VALUES (23265, 40, 3, 4, 'ele porém o João tinha o veste dele de cabelos camelo e cinto de-couro acerca-de o lombo dele o porém alimento era dele gafanhotos e mel silvestre');
INSERT INTO verses VALUES (23266, 40, 3, 5, 'Então saía junto-a ele Jerusalém e toda o Judeia e toda o região-circunvizinha o Jordão');
INSERT INTO verses VALUES (23267, 40, 3, 6, 'e eram-batizados em o Jordão rio sob dele confessando o do-pecado deles');
INSERT INTO verses VALUES (23268, 40, 3, 7, 'Vendo porém a-muitos o fariseus e saduceus Vindo sobre o batismo disse a-eles Crias víboras quem mostrou a-vós fugir de o está-para ira');
INSERT INTO verses VALUES (23269, 40, 3, 8, 'fazei portanto fruto digno o arrependimento');
INSERT INTO verses VALUES (23270, 40, 3, 9, 'e não penseis dizer em si-mesmos Pai temos o Abraão digo pois a-vós que pode o Theos de o pedras destes levanta filhos o Abraão');
INSERT INTO verses VALUES (23271, 40, 3, 10, 'já porém o machado junto-a o raiz o árvores está-posto todo portanto árvore não fazendo fruto belo é-cortado e para fogo é-lançado');
INSERT INTO verses VALUES (23272, 40, 3, 11, 'eu por-um-lado vos batizo em água para arrependimento o porém atrás meu vindo mais-forte meu é o qual não sou digno o sandálias suportar ele vos batizará em Espírito no-santo e fogo');
INSERT INTO verses VALUES (23273, 40, 3, 12, 'o qual o pá em o mão dele e limpará-completamente o eira dele e reunirá o trigo dele para o celeiro o porém palha queimará fogo inextinguível');
INSERT INTO verses VALUES (23274, 40, 3, 13, 'Então chega o Iesous de o Galileia sobre o Jordão junto-a o João o ser-batizado sob dele');
INSERT INTO verses VALUES (23275, 40, 3, 14, 'o porém impedia ele dizendo eu necessidade tenho sob teu ser-batizado e tu Vens para me');
INSERT INTO verses VALUES (23276, 40, 3, 15, 'respondendo porém o Iesous disse a ele Deixa agora assim pois conveniente é a-nós cumprir toda justiça então perdoa ele');
INSERT INTO verses VALUES (23277, 40, 3, 16, 'tendo-sido-batizado porém o Iesous imediatamente subiu de o água e eis foram-abertos o céus e viu espírito de-Theos descendo como pomba vindo sobre ele');
INSERT INTO verses VALUES (23278, 40, 3, 17, 'e eis voz de o dos-céus dizendo Este é o filho meu o amado em o qual agradei-me');
INSERT INTO chapters VALUES (933, 40, 4, 25);
INSERT INTO verses VALUES (23279, 40, 4, 1, 'Então o Iesous foi-levado-ao-mar para o deserto sob o do-espírito ser-tentado sob o diabo');
INSERT INTO verses VALUES (23280, 40, 4, 2, 'e tendo-jejuado do-dia quarenta e quarenta noites depois teve-fome');
INSERT INTO verses VALUES (23281, 40, 4, 3, 'e aproximando-se o tentando disse a ele se Filho és o de-Theos dize para que o pedras estes pães tornem-se');
INSERT INTO verses VALUES (23282, 40, 4, 4, 'o porém respondendo disse está-escrito não sobre pão somente viverá o homem mas sobre todo palavra saindo através-de boca de-Theos');
INSERT INTO verses VALUES (23283, 40, 4, 5, 'Então toma-consigo ele o diabo para o santa cidade e estabeleceu ele sobre o pináculo o do-templo');
INSERT INTO verses VALUES (23284, 40, 4, 6, 'e diz a ele se Filho és o de-Theos lança a-ti-mesmo abaixo está-escrito pois que o anjo dele ordena acerca-de teu e sobre mãos levantarão te não alguma-vez tropeçes junto-a pedra o pé teu');
INSERT INTO verses VALUES (23285, 40, 4, 7, 'disse a ele o Iesous novamente está-escrito não tentarás Kyrion o Theos teu');
INSERT INTO verses VALUES (23286, 40, 4, 8, 'novamente toma-consigo ele o diabo para monte alto muito e mostra a ele todas o do-reino o do-mundo e o glória deles');
INSERT INTO verses VALUES (23287, 40, 4, 9, 'e disse a ele Estas-coisas a-ti todas-as-coisas darei se caindo adores a-mim');
INSERT INTO verses VALUES (23288, 40, 4, 10, 'então diz a ele o Iesous Vai Satanás está-escrito pois Kyrion o Theon teu prostrar-te-ás e a ele somente servirás-sagradamente');
INSERT INTO verses VALUES (23289, 40, 4, 11, 'Então perdoa ele o diabo e eis anjo aproximaram-se e serviam a ele');
INSERT INTO verses VALUES (23290, 40, 4, 12, 'ouvindo porém que João foi-entregue retirou-se para o Galileia');
INSERT INTO verses VALUES (23291, 40, 4, 13, 'e deixando o Nazaré vindo habitou para Cafarnaum o marítima em limites Zebulom e Naftali');
INSERT INTO verses VALUES (23292, 40, 4, 14, 'para que seja-cumprido o o-dito através-de Isaías o profeta dizendo');
INSERT INTO verses VALUES (23293, 40, 4, 15, 'terra Zebulom e terra Naftali caminho do-mar além o Jordão Galileia o nações');
INSERT INTO verses VALUES (23294, 40, 4, 16, 'o povo o sentado em trevas luz viu grande e o sentados em região e sombra da-morte luz nasceu a-eles');
INSERT INTO verses VALUES (23295, 40, 4, 17, 'de então começou o Iesous proclamar e dizer Arrependei-vos aproximou-se pois o reino o dos-céus');
INSERT INTO verses VALUES (23296, 40, 4, 18, 'Andando porém de-junto-de o mar o Galileia viu dois irmãos Simão o chamado Pedro e André o irmão dele lançando rede-de-pesca para o mar eram pois pescadores');
INSERT INTO verses VALUES (23297, 40, 4, 19, 'e diz a-eles vinde atrás meu e farei vos pescadores dos-homens');
INSERT INTO verses VALUES (23298, 40, 4, 20, 'o porém imediatamente deixando o redes seguiram a ele');
INSERT INTO verses VALUES (23299, 40, 4, 21, 'e tendo-avançado dali viu outros dois irmãos Tiago o o Zebedeu e João o irmão dele em o no-barco com Zebedeu o do-Pai deles restaurando o redes deles e chamou eles');
INSERT INTO verses VALUES (23300, 40, 4, 22, 'o porém imediatamente deixando o barco e o Pai deles seguiram a ele');
INSERT INTO verses VALUES (23301, 40, 4, 23, 'e percorria em toda o Galileia ensinando em o nas-sinagogas deles e pregando o evangelho o do-reino e curando toda doença e toda enfermidade em o povo');
INSERT INTO verses VALUES (23302, 40, 4, 24, 'e partiu o ouvido dele para toda o Síria e trouxeram a ele todos o mal tendo diversas doenças e tormentos sendo-constrangidos endemoninhados e lunáticos e paralíticos e curou eles');
INSERT INTO verses VALUES (23303, 40, 4, 25, 'e seguiram a ele multidões muitos de o Galileia e Decápolis e Jerusalém e Judeia e além o Jordão');
INSERT INTO chapters VALUES (934, 40, 5, 48);
INSERT INTO verses VALUES (23304, 40, 5, 1, 'Vendo porém o multidões subiu para o monte e tendo-sentado dele aproximaram-se a ele o discípulos dele');
INSERT INTO verses VALUES (23305, 40, 5, 2, 'e abrindo o boca dele ensinava eles dizendo');
INSERT INTO verses VALUES (23306, 40, 5, 3, 'bem-aventurados o pobres o espírito que deles é o reino o dos-céus');
INSERT INTO verses VALUES (23307, 40, 5, 4, 'bem-aventurados o lamentando que eles-mesmos serão-consolados');
INSERT INTO verses VALUES (23308, 40, 5, 5, 'bem-aventurados o mansos que eles-mesmos herdarão o terra');
INSERT INTO verses VALUES (23309, 40, 5, 6, 'bem-aventurados o tendo-fome e tendo-sede o justiça que eles-mesmos serão-saciados');
INSERT INTO verses VALUES (23310, 40, 5, 7, 'bem-aventurados o misericordiosos que eles-mesmos receberão-misericórdia');
INSERT INTO verses VALUES (23311, 40, 5, 8, 'bem-aventurados o puros o no-coração que eles-mesmos o Theos verão');
INSERT INTO verses VALUES (23312, 40, 5, 9, 'bem-aventurados o pacificadores que eles-mesmos filhos de-Theos serão-chamados');
INSERT INTO verses VALUES (23313, 40, 5, 10, 'bem-aventurados o tendo-sido-perseguidos por-causa-de da-justiça que deles é o reino o dos-céus');
INSERT INTO verses VALUES (23314, 40, 5, 11, 'bem-aventurados sois quando injuriem vos e persigam e digam todo mau segundo vosso mentindo por-causa-de mim');
INSERT INTO verses VALUES (23315, 40, 5, 12, 'alegrai-vos e exultai que o salário vosso muito em o nos-céus assim pois perseguiram o profetas o antes-de vosso');
INSERT INTO verses VALUES (23316, 40, 5, 13, 'vós sois o sal o da-terra se porém o sal torne-se-insípido em a-quem será-salgado para nada tem-poder ainda se não tendo-sido-lançado fora ser-pisado sob o dos-homens');
INSERT INTO verses VALUES (23317, 40, 5, 14, 'vós sois o luz o do-mundo não pode cidade ser-escondido em-cima do-monte jazendo');
INSERT INTO verses VALUES (23318, 40, 5, 15, 'nem acendem lâmpada e põem ele sob o alqueire mas sobre o candelabro e brilha todos o em o casa');
INSERT INTO verses VALUES (23319, 40, 5, 16, 'assim brilhe o luz vosso diante-de o dos-homens para-que vejam vosso o boas obra e glorifiquem o Pai vosso o em o nos-céus');
INSERT INTO verses VALUES (23320, 40, 5, 17, 'não penseis que vieram destruir o lei ou o profetas não vieram destruir mas cumprir');
INSERT INTO verses VALUES (23321, 40, 5, 18, 'amém pois digo a-vós até partícula-condicional passe o céu e o terra Iota um ou uma til não não passe de o da-lei até partícula-condicional todas-as-coisas aconteça');
INSERT INTO verses VALUES (23322, 40, 5, 19, 'o qual se portanto desate uma o mandamentos destes o menores e ensine assim o homens menor será-chamado em o no-reino o dos-céus o qual e/mas partícula-condicional faça e ensine este grande será-chamado em o no-reino o dos-céus');
INSERT INTO verses VALUES (23323, 40, 5, 20, 'digo pois a-vós que se não abunde vosso o justiça mais o dos-escribas e fariseus não não entreis para o reino o dos-céus');
INSERT INTO verses VALUES (23324, 40, 5, 21, 'Ouvistes que foi-dito o antigos não assassinarás o qual e/mas partícula-condicional mate culpado será o juízo');
INSERT INTO verses VALUES (23325, 40, 5, 22, 'eu porém digo a-vós que todo o irando-se o ao-irmão dele culpado será o juízo o qual e/mas partícula-condicional diga o ao-irmão dele Racá culpado será o sinédrio o qual e/mas partícula-condicional diga Tolo culpado será para o Geena o fogo');
INSERT INTO verses VALUES (23326, 40, 5, 23, 'se portanto ofereças o oferta teu sobre o altar e-ali lembres-te que o irmão teu tem algo segundo teu');
INSERT INTO verses VALUES (23327, 40, 5, 24, 'deixa ali o oferta teu diante-de o altar e vai primeiro reconcilia-te o ao-irmão teu e então vindo oferece o oferta teu');
INSERT INTO verses VALUES (23328, 40, 5, 25, 'sê sendo-benevolente o adversário teu rapidamente até de-quem és com dele em o caminho não alguma-vez te entregue o adversário o juiz e o juiz o servo e para prisão serás-lançado');
INSERT INTO verses VALUES (23329, 40, 5, 26, 'amém digo a-ti não não saias dali até partícula-condicional devolvas o último quadrante');
INSERT INTO verses VALUES (23330, 40, 5, 27, 'Ouvistes que foi-dito não adulterarás');
INSERT INTO verses VALUES (23331, 40, 5, 28, 'eu porém digo a-vós que todo o vendo mulher junto-a o desejar ela já adulterou ela em o no-coração dele');
INSERT INTO verses VALUES (23332, 40, 5, 29, 'se porém o olho teu o direito escandaliza te arranca ele e lança de teu convém pois a-ti para que pereça um o membros teu e não todo o corpo teu seja-lançado para Geena');
INSERT INTO verses VALUES (23333, 40, 5, 30, 'e se o direita teu mão escandaliza te corta ela e lança de teu convém pois a-ti para que pereça um o membros teu e não todo o corpo teu para Geena parta');
INSERT INTO verses VALUES (23334, 40, 5, 31, 'foi-dito e/mas o qual partícula-condicional solte o mulher dele dê a-ela carta-de-divórcio');
INSERT INTO verses VALUES (23335, 40, 5, 32, 'eu porém digo a-vós que todo o soltando o mulher dele exceto da-palavra imoralidade faz ela ser-adulterada e o qual se tendo-sido-solta case adultera');
INSERT INTO verses VALUES (23336, 40, 5, 33, 'novamente ouvistes que foi-dito o antigos não jurarás-falsamente devolverás porém o ao-Kyrios o juramentos teu');
INSERT INTO verses VALUES (23337, 40, 5, 34, 'eu porém digo a-vós não jurar totalmente nem em o no-céu que trono é o de-Theos');
INSERT INTO verses VALUES (23338, 40, 5, 35, 'nem em o terra que estrado é o pés dele nem para Jerusalém que cidade é o grande rei');
INSERT INTO verses VALUES (23339, 40, 5, 36, 'nem em o cabeça teu jures que não podes uma cabelo branca fazer ou preta');
INSERT INTO verses VALUES (23340, 40, 5, 37, 'seja porém o palavra vosso sim sim não não o porém abundante destes de o do-mal é');
INSERT INTO verses VALUES (23341, 40, 5, 38, 'Ouvistes que foi-dito Olho em-troca-de olho e dente em-troca-de dente');
INSERT INTO verses VALUES (23342, 40, 5, 39, 'eu porém digo a-vós não resistir o mau mas qualquer-que te esbofeteia para o direita face teu vira a ele e o outra');
INSERT INTO verses VALUES (23343, 40, 5, 40, 'e o querendo a-ti ser-julgado e o túnica teu receber deixa a ele e o manto');
INSERT INTO verses VALUES (23344, 40, 5, 41, 'e qualquer-que te obrigará-a-servir milha um vai com dele dois');
INSERT INTO verses VALUES (23345, 40, 5, 42, 'o pedindo te dá e o querendo de teu tomar-emprestado não te-desvies');
INSERT INTO verses VALUES (23346, 40, 5, 43, 'Ouvistes que foi-dito Amarás o próximo teu e odiarás o Inimigo teu');
INSERT INTO verses VALUES (23347, 40, 5, 44, 'eu porém digo a-vós amai o inimigos vosso e orai em-favor-de o perseguindo vos');
INSERT INTO verses VALUES (23348, 40, 5, 45, 'para-que torneis-vos filhos o do-Pai vosso o em nos-céus que o sol dele faz-nascer sobre maus e bons e chove sobre justos e injustos');
INSERT INTO verses VALUES (23349, 40, 5, 46, 'se pois ameis o amando vos quem salário tendes não e o cobradores-de-impostos o ele fazem');
INSERT INTO verses VALUES (23350, 40, 5, 47, 'e se saudeis o irmãos vosso somente quê abundante fazei não e o gentios o ele fazem');
INSERT INTO verses VALUES (23351, 40, 5, 48, 'Sereis portanto vós perfeitos como o Pai vosso o celestial perfeito é');
INSERT INTO chapters VALUES (935, 40, 6, 34);
INSERT INTO verses VALUES (23352, 40, 6, 1, 'Guardai-vos porém o justiça vosso não fazer diante-de o dos-homens junto-a o ser-contemplado a-eles se porém de-outro-modo salário não tendes de-junto-de o Pai vosso o em o nos-céus');
INSERT INTO verses VALUES (23353, 40, 6, 2, 'quando portanto fazes esmola não toques-trombeta diante-de teu assim-como o hipócritas fazem em o nas-sinagogas e em o ruelas para-que sejam-glorificados sob o dos-homens amém digo a-vós recebem-por-completo o salário deles');
INSERT INTO verses VALUES (23354, 40, 6, 3, 'teu porém fazendo esmola não conheça o esquerda teu quê faz o direita teu');
INSERT INTO verses VALUES (23355, 40, 6, 4, 'para-que seja teu o esmola em o oculto e o Pai teu o vendo em o oculto retribuirá a-ti');
INSERT INTO verses VALUES (23356, 40, 6, 5, 'e quando oreis não sereis como o hipócritas que amam em o nas-sinagogas e em o cantos o praças de-pé orar para-que apareçam o aos-homens amém digo a-vós recebem-por-completo o salário deles');
INSERT INTO verses VALUES (23357, 40, 6, 6, 'tu porém quando oras entra para o quarto-interior teu e tendo-fechado o porta teu ora o Pai teu o em o oculto e o Pai teu o vendo em o oculto retribuirá a-ti');
INSERT INTO verses VALUES (23358, 40, 6, 7, 'Orando porém não balbuciais-em-vão assim-como o gentios parecem pois que em o palavrório deles serão-ouvidos');
INSERT INTO verses VALUES (23359, 40, 6, 8, 'não portanto sejais-assemelhados a-eles sei pois o Pai vosso o qual necessidade tendes antes-de o vos pedir ele');
INSERT INTO verses VALUES (23360, 40, 6, 9, 'assim portanto orai vós Pai nosso o em o nos-céus Seja-santificado o nome teu');
INSERT INTO verses VALUES (23361, 40, 6, 10, 'venha o reino teu seja-feito o vontade teu como em no-céu e sobre da-terra');
INSERT INTO verses VALUES (23362, 40, 6, 11, 'o pão nosso o necessário dá a-nós hoje');
INSERT INTO verses VALUES (23363, 40, 6, 12, 'e deixa a-nós o dívidas nosso como e nós deixamos o devedores nosso');
INSERT INTO verses VALUES (23364, 40, 6, 13, 'e não conduzas-para-dentro nos para tentação mas livra nos de o do-mal');
INSERT INTO verses VALUES (23365, 40, 6, 14, 'se pois perdoeis o aos-homens o transgressões deles deixará e a-vós o Pai vosso o celestial');
INSERT INTO verses VALUES (23366, 40, 6, 15, 'se porém não perdoeis o aos-homens nem o Pai vosso deixará o transgressões vosso');
INSERT INTO verses VALUES (23367, 40, 6, 16, 'quando porém jejueis não tornai-vos como o hipócritas de-rosto-triste desfiguram pois o faces deles para-que apareçam o aos-homens jejuando amém digo a-vós recebem-por-completo o salário deles');
INSERT INTO verses VALUES (23368, 40, 6, 17, 'tu porém jejuando unge teu o cabeça e o face teu lavar');
INSERT INTO verses VALUES (23369, 40, 6, 18, 'para-que não apareças o aos-homens jejuando mas o Pai teu o em o secreto e o Pai teu o vendo em o secreto retribuirá a-ti');
INSERT INTO verses VALUES (23370, 40, 6, 19, 'não entesourais a-vós tesouros sobre o da-terra onde tua e comida desfigura e onde ladrões arrombam e furtam');
INSERT INTO verses VALUES (23371, 40, 6, 20, 'entesourais porém a-vós tesouros em no-céu onde nem tua nem comida desfigura e onde ladrões não arrombam nem furtam');
INSERT INTO verses VALUES (23372, 40, 6, 21, 'onde pois é o tesouro teu ali será e o coração teu');
INSERT INTO verses VALUES (23373, 40, 6, 22, 'o lâmpada o corpo é o olho se portanto seja o olho teu simples todo o corpo teu luminoso será');
INSERT INTO verses VALUES (23374, 40, 6, 23, 'se porém o olho teu mau seja todo o corpo teu tenebroso será se portanto o luz o em a-ti trevas é o trevas quanto');
INSERT INTO verses VALUES (23375, 40, 6, 24, 'Ninguém pode dois senhores servir ou pois o um odiará e o outro amará ou de-um apegar-se-á e o de-outro desprezará não podeis a-Theos servir e mamom');
INSERT INTO verses VALUES (23376, 40, 6, 25, 'através-de isto digo a-vós não andais-ansiosos o alma vosso quê comei ou quê bebais nem o corpo vosso quê vistais não o alma mais é o alimento e o corpo o vestimenta');
INSERT INTO verses VALUES (23377, 40, 6, 26, 'olhai para o aves o do-céu que não semeiam nem ceifam nem reúnem para celeiros e o Pai vosso o celestial alimenta elas não vós mais diferis deles');
INSERT INTO verses VALUES (23378, 40, 6, 27, 'quem porém de vosso preocupando-se pode acrescentar sobre o estatura dele côvado um');
INSERT INTO verses VALUES (23379, 40, 6, 28, 'e acerca-de vestimenta quê andais-ansiosos considerai-atentamente o lírios o campo como crescem não trabalham nem fiam');
INSERT INTO verses VALUES (23380, 40, 6, 29, 'digo porém a-vós que nem Salomão em toda o glória dele vestiu-se como um destes');
INSERT INTO verses VALUES (23381, 40, 6, 30, 'se porém o erva o campo hoje sendo e amanhã para forno sendo-lançado o Theos assim veste não muito mais vos pouca-fé');
INSERT INTO verses VALUES (23382, 40, 6, 31, 'não portanto preocupeis dizendo quê comamos ou quê bebamos ou quê vistamo-nos');
INSERT INTO verses VALUES (23383, 40, 6, 32, 'todas-as-coisas pois estas-coisas o nações buscam sei pois o Pai vosso o celestial que necessitais destes todos');
INSERT INTO verses VALUES (23384, 40, 6, 33, 'buscais porém primeiro o reino e o justiça dele e estas-coisas todas-as-coisas será-acrescentado a-vós');
INSERT INTO verses VALUES (23385, 40, 6, 34, 'não portanto preocupeis para o amanhã o pois amanhã preocupar-se-á de-si-mesma suficiente o dia o maldade dela');
INSERT INTO chapters VALUES (936, 40, 7, 29);
INSERT INTO verses VALUES (23386, 40, 7, 1, 'não julgais para que não sejais-julgados');
INSERT INTO verses VALUES (23387, 40, 7, 2, 'em o qual pois julgamento julgais sereis-julgados e em o qual medida medis será-medido a-vós');
INSERT INTO verses VALUES (23388, 40, 7, 3, 'quê porém vês o cisco o em o olho o do-irmão teu o porém em o teu olho viga não consideras');
INSERT INTO verses VALUES (23389, 40, 7, 4, 'ou como dirás o ao-irmão teu Deixa expulse o cisco de o olho teu e eis o trave em o olho teu');
INSERT INTO verses VALUES (23390, 40, 7, 5, 'hipócrita expulsa primeiro de o olho teu o trave e então verás-claramente expulsar o cisco de o olho o do-irmão teu');
INSERT INTO verses VALUES (23391, 40, 7, 6, 'não deis o santo o cães nem lanceis o pérolas vosso diante-de o porcos não alguma-vez pisarão eles em o pés deles e tendo-se-virado Rompam vos');
INSERT INTO verses VALUES (23392, 40, 7, 7, 'Pedi e será-dado a-vós buscais e encontrareis batei e será-aberto a-vós');
INSERT INTO verses VALUES (23393, 40, 7, 8, 'todo pois o pedindo recebe e o buscando encontra e o batendo será-aberto');
INSERT INTO verses VALUES (23394, 40, 7, 9, 'ou quem é de vosso homem o qual pedirá o Filho dele pão não pedra dará a ele');
INSERT INTO verses VALUES (23395, 40, 7, 10, 'ou e peixe pedirá não serpente dará a ele');
INSERT INTO verses VALUES (23396, 40, 7, 11, 'se portanto vós maus sendo sei dons boas-coisas dar o filhos vosso quanto mais o Pai vosso o em o nos-céus dará boas-coisas o pedem ele');
INSERT INTO verses VALUES (23397, 40, 7, 12, 'todas-as-coisas portanto quanto se queirais para que façam a-vós o homens assim e vós fazei a-eles este pois é o lei e o profetas');
INSERT INTO verses VALUES (23398, 40, 7, 13, 'Entrai através-de o estreita porta que praça o porta e espaçoso o caminho o conduzindo para o perdição e muitos são o entrando através-de dela');
INSERT INTO verses VALUES (23399, 40, 7, 14, 'que estreita o porta e tendo-sido-estreitada o caminho o conduzindo para o vida e poucos são o encontrando ela');
INSERT INTO verses VALUES (23400, 40, 7, 15, 'Guardai-vos de o falsos-profetas os-quais vêm junto-a vos em vestes ovelhas por-dentro e/mas são lobos rapaces');
INSERT INTO verses VALUES (23401, 40, 7, 16, 'de o frutos deles conhecereis-plenamente eles acaso colhem de espinhos uvas ou de abrolhos figos');
INSERT INTO verses VALUES (23402, 40, 7, 17, 'assim todo árvore bom frutos bons faz o porém podre árvore frutos maus faz');
INSERT INTO verses VALUES (23403, 40, 7, 18, 'não pode árvore bom frutos maus trazer nem árvore podre frutos bons trazer');
INSERT INTO verses VALUES (23404, 40, 7, 19, 'todo árvore não fazendo fruto belo é-cortado e para fogo é-lançado');
INSERT INTO verses VALUES (23405, 40, 7, 20, 'porventura de o frutos deles conhecereis-plenamente eles');
INSERT INTO verses VALUES (23406, 40, 7, 21, 'não todo o dizendo a-mim Kyrie Kyrie entrará para o reino o dos-céus mas o fazendo o vontade o do-Pai meu o em o nos-céus');
INSERT INTO verses VALUES (23407, 40, 7, 22, 'muitos Dirão a-mim em naquela o dia Kyrie Kyrie não o teu em-nome Profetizamos e o teu em-nome demônios expulsamos e o teu em-nome poderes muitas fizemos');
INSERT INTO verses VALUES (23408, 40, 7, 23, 'e então confessarei a-eles que Nunca conheci vos retirai-vos de mim o trabalhando o iniquidade');
INSERT INTO verses VALUES (23409, 40, 7, 24, 'todo portanto qualquer-que ouve meu o palavras estes e faz eles será-semelhante marido ao-prudente qualquer-que edificou dele o casa sobre o rocha');
INSERT INTO verses VALUES (23410, 40, 7, 25, 'e desceu o chuva e vieram o rios e sopraram o ventos e caíram-diante o casa naquela e não caiu tinha-sido-fundada pois sobre o rocha');
INSERT INTO verses VALUES (23411, 40, 7, 26, 'e todo o ouvindo meu o palavras estes e não fazendo eles será-semelhante homem tolo qualquer-que edificou dele o casa sobre o areia');
INSERT INTO verses VALUES (23412, 40, 7, 27, 'e desceu o chuva e vieram o rios e sopraram o ventos e tropeçaram o casa naquela e caiu e era o queda dela grande');
INSERT INTO verses VALUES (23413, 40, 7, 28, 'e aconteceu quando terminou o Iesous o palavras estes ficavam-espantados o multidões sobre o em-ensino dele');
INSERT INTO verses VALUES (23414, 40, 7, 29, 'era pois ensinando eles como autoridade tendo e não como o escribas deles');
INSERT INTO chapters VALUES (937, 40, 8, 34);
INSERT INTO verses VALUES (23415, 40, 8, 1, 'Tendo-descido porém dele de o do-monte seguiram a ele multidões muitos');
INSERT INTO verses VALUES (23416, 40, 8, 2, 'e eis leproso aproximando-se adorava a ele dizendo Kyrie se queiras podes me purificar');
INSERT INTO verses VALUES (23417, 40, 8, 3, 'e estendendo o mão tocou dele dizendo quero sê-purificado e imediatamente foi-purificado dele o lepra');
INSERT INTO verses VALUES (23418, 40, 8, 4, 'e diz a ele o Iesous veja a-ninguém digas mas vai a-ti-mesmo mostra o sacerdote e oferece o presente o qual ordenou Moisés para testemunho a-eles');
INSERT INTO verses VALUES (23419, 40, 8, 5, 'Tendo-entrado porém dele para Cafarnaum aproximou-se a ele centurião exortando ele');
INSERT INTO verses VALUES (23420, 40, 8, 6, 'e dizendo Kyrie o servo meu tem-sido-lançado em o casa paralítico terrivelmente sendo-atormentado');
INSERT INTO verses VALUES (23421, 40, 8, 7, 'diz a ele eu vindo curarei ele');
INSERT INTO verses VALUES (23422, 40, 8, 8, 'respondendo porém o centurião disse Kyrie não sou digno para que meu sob o telhado entres mas somente dize em-palavra e Será-curado o servo meu');
INSERT INTO verses VALUES (23423, 40, 8, 9, 'e pois eu homem sou sob autoridade tendo sob a-mim-mesmo soldados e digo neste Vai e vai e a-outro Vem e vem e o servo meu faz isto e faz');
INSERT INTO verses VALUES (23424, 40, 8, 10, 'ouvindo porém o Iesous admirou-se e disse o seguem Amém digo a-vós de-junto-de a-ninguém tão-grande fé em o Israel encontraram');
INSERT INTO verses VALUES (23425, 40, 8, 11, 'digo porém a-vós que muitos de oriente e ocidente virão e serão-reclinados com Abraão e Isaque e Jacó em o no-reino o dos-céus');
INSERT INTO verses VALUES (23426, 40, 8, 12, 'o porém filhos o do-reino serão-lançados-fora para o trevas o exterior ali será o choro e o ranger o dentes');
INSERT INTO verses VALUES (23427, 40, 8, 13, 'e disse o Iesous o centurião Vai como creste seja-feito a-ti e foi-curado o servo em o hora naquela');
INSERT INTO verses VALUES (23428, 40, 8, 14, 'e vindo o Iesous para o casa de-Pedro viu o sogra dele tendo-sido-lançada e tendo-febre');
INSERT INTO verses VALUES (23429, 40, 8, 15, 'e tocou o da-mão dela e deixou ela o febre e foi-ressuscitado e servia a ele');
INSERT INTO verses VALUES (23430, 40, 8, 16, 'Tarde porém tendo-acontecido trouxeram a ele endemoninhados muitos e expulsou o espíritos em-palavra e todos o mal tendo curou');
INSERT INTO verses VALUES (23431, 40, 8, 17, 'para-que seja-cumprido o o-dito através-de Isaías o profeta dizendo ele o fraqueza nosso recebeu e o doenças carregou');
INSERT INTO verses VALUES (23432, 40, 8, 18, 'Vendo porém o Iesous multidão acerca-de ele ordenou ir-embora para o além');
INSERT INTO verses VALUES (23433, 40, 8, 19, 'e aproximando-se um escriba disse a ele Mestre seguirei a-ti onde se partes');
INSERT INTO verses VALUES (23434, 40, 8, 20, 'e diz a ele o Iesous o raposas tocas têm e o aves o do-céu aninharás o porém Filho o do-homem não tem onde o cabeça cama');
INSERT INTO verses VALUES (23435, 40, 8, 21, 'outro porém o discípulos disse a ele Kyrie permite a-mim primeiro ir-embora e sepultar o Pai meu');
INSERT INTO verses VALUES (23436, 40, 8, 22, 'o porém Iesous diz a ele Segue a-mim e deixa o mortos sepultar o deles-mesmos mortos');
INSERT INTO verses VALUES (23437, 40, 8, 23, 'e tendo-embarcado a ele para o barco seguiram a ele o discípulos dele');
INSERT INTO verses VALUES (23438, 40, 8, 24, 'e eis terremoto grande aconteceu em o mar de-modo-que o barco cobrir-se sob o ondas ele porém dormia');
INSERT INTO verses VALUES (23439, 40, 8, 25, 'e aproximando-se levantaram ele dizendo Kyrie salva perecemos');
INSERT INTO verses VALUES (23440, 40, 8, 26, 'e diz a-eles quê covardes sois pouca-fé então levantando-se repreendeu o ventos e o mar e aconteceu calmaria grande');
INSERT INTO verses VALUES (23441, 40, 8, 27, 'o porém homens admiraram-se dizendo Que-tipo é este que e o ventos e o mar a ele obedecem');
INSERT INTO verses VALUES (23442, 40, 8, 28, 'e tendo-vindo dele para o além para o região o Gadarenos encontraram a ele dois sendo-endemoninhados de o sepulcros saindo difíceis muito de-modo-que não Ser-forte algum passar através-de o do-caminho daquela');
INSERT INTO verses VALUES (23443, 40, 8, 29, 'e eis clamaram dizendo quê a-nós e a-ti Filho o de-Theos vieste aqui antes-de tempo atormentar nos');
INSERT INTO verses VALUES (23444, 40, 8, 30, 'era porém longe de deles manada porcos muitos sendo-apascentada');
INSERT INTO verses VALUES (23445, 40, 8, 31, 'o porém demônios suplicavam ele dizendo se lanças-fora nos envia nos para o rebanho o porcos');
INSERT INTO verses VALUES (23446, 40, 8, 32, 'e disse a-eles ide o porém saindo foram para o porcos e eis precipitou-se toda o manada segundo o precipício para o mar e morreram em o água');
INSERT INTO verses VALUES (23447, 40, 8, 33, 'o porém apascentando fugiram e tendo-ido-embora para o cidade anunciaram todas-as-coisas e o o sendo-endemoninhados');
INSERT INTO verses VALUES (23448, 40, 8, 34, 'e eis toda o cidade saiu para encontro o Iesous e vendo ele suplicaram para-que passe de o fronteiras deles');
INSERT INTO chapters VALUES (938, 40, 9, 38);
INSERT INTO verses VALUES (23449, 40, 9, 1, 'e embarcando para barco atravessou e veio para o própria cidade');
INSERT INTO verses VALUES (23450, 40, 9, 2, 'e eis ofereciam a ele paralítico sobre cama tendo-sido-lançado e vendo o Iesous o fé deles disse o paralítico tem-ânimo filho são-perdoados teu o pecados');
INSERT INTO verses VALUES (23451, 40, 9, 3, 'e eis alguns o dos-escribas disseram em si-mesmos este blasfema');
INSERT INTO verses VALUES (23452, 40, 9, 4, 'e sei o Iesous o pensamentos deles disse para que quê pensais má em o corações vosso');
INSERT INTO verses VALUES (23453, 40, 9, 5, 'quê pois é mais-fácil dizer São-perdoados teu o pecados ou dizer Levanta-te e anda');
INSERT INTO verses VALUES (23454, 40, 9, 6, 'para que porém sei que autoridade tem o Filho o do-homem sobre o da-terra perdoar do-pecado então diz o paralítico Levanta-te levanta teu o cama e vai para o casa teu');
INSERT INTO verses VALUES (23455, 40, 9, 7, 'e levantando-se partiu para o casa dele');
INSERT INTO verses VALUES (23456, 40, 9, 8, 'vendo porém o multidões temeram e glorificaram o Theos o tendo-dado autoridade tal o aos-homens');
INSERT INTO verses VALUES (23457, 40, 9, 9, 'e passando o Iesous dali viu homem sentado sobre o coletoria Mateus chamado e diz a ele Segue a-mim e levantando-se seguiu a ele');
INSERT INTO verses VALUES (23458, 40, 9, 10, 'e aconteceu dele reclinado em o casa e eis muitos cobradores-de-impostos e pecadores vindo reclinavam-se-à-mesa-junto o Iesous e o discípulos dele');
INSERT INTO verses VALUES (23459, 40, 9, 11, 'e vendo o fariseus diziam o discípulos dele através-de quê com o cobradores-de-impostos e dos-pecadores come o mestre vosso');
INSERT INTO verses VALUES (23460, 40, 9, 12, 'o porém ouvindo disse não necessidade têm o sendo-fortes médico mas o mal tendo');
INSERT INTO verses VALUES (23461, 40, 9, 13, 'tendo-ido porém aprendei quê é Misericórdia quero e não sacrifício não pois vieram chamar justos mas pecadores');
INSERT INTO verses VALUES (23462, 40, 9, 14, 'Então aproximam-se a ele o discípulos João dizendo através-de quê nós e o fariseus jejuamos o porém discípulos teu não jejuam');
INSERT INTO verses VALUES (23463, 40, 9, 15, 'e disse a-eles o Iesous não podem o filhos o câmara-nupcial lamentar sobre quanto com deles é o noivo virão porém dias quando seja-tirado de deles o noivo e então jejuarão');
INSERT INTO verses VALUES (23464, 40, 9, 16, 'ninguém porém lança-sobre remendo pano não-pisoado sobre Veste velho levanta pois o plenitude dele de o manto e pior divisão torna-se');
INSERT INTO verses VALUES (23465, 40, 9, 17, 'nem lançam vinho novo para odres velhos se porém de-outro-modo Rompem-se o odres e o vinho é-derramado e o odres perecem mas lançam vinho novo para odres novos e ambos são-preservados');
INSERT INTO verses VALUES (23466, 40, 9, 18, 'estas-coisas dele falando a-eles eis governante um aproximando-se adorava a ele dizendo que o filha meu agora morreu mas vindo coloca-sobre o mão teu sobre ela e viverá');
INSERT INTO verses VALUES (23467, 40, 9, 19, 'e levantando-se o Iesous seguia a ele e o discípulos dele');
INSERT INTO verses VALUES (23468, 40, 9, 20, 'e eis mulher sofrendo-hemorragia doze anos tendo-se-aproximado atrás tocou o franja o manto dele');
INSERT INTO verses VALUES (23469, 40, 9, 21, 'dizia pois em a-si-mesma se somente toque o manto dele serei-salvo');
INSERT INTO verses VALUES (23470, 40, 9, 22, 'o porém Iesous voltando-se e vendo ela disse tem-ânimo filha o fé teu tem-salvo te e foi-salvo o mulher de o hora daquela');
INSERT INTO verses VALUES (23471, 40, 9, 23, 'e vindo o Iesous para o casa o governante e vendo o flautistas e o multidão sendo-tumultuado');
INSERT INTO verses VALUES (23472, 40, 9, 24, 'dizia Retirai-vos não pois morreu o menina mas dorme e riam-se dele');
INSERT INTO verses VALUES (23473, 40, 9, 25, 'quando porém foi-expulso o multidão entrando prendeu o da-mão dela e foi-ressuscitado o menina');
INSERT INTO verses VALUES (23474, 40, 9, 26, 'e saiu o notícia esta para toda o terra aquela');
INSERT INTO verses VALUES (23475, 40, 9, 27, 'e ao-que-passa dali o Iesous seguiram dois cegos gritando e dizendo Tem-misericórdia nos Filho Davi');
INSERT INTO verses VALUES (23476, 40, 9, 28, 'tendo-vindo porém para o casa aproximaram-se a ele o cegos e diz a-eles o Iesous Crede que posso isto fazer dizem a ele Sim Kyrie');
INSERT INTO verses VALUES (23477, 40, 9, 29, 'então tocou o olhos deles dizendo segundo o fé vosso seja-feito a-vós');
INSERT INTO verses VALUES (23478, 40, 9, 30, 'e foram-abertos deles o olhos e foi-severamente-repreendido a-eles o Iesous dizendo Vede ninguém saiba');
INSERT INTO verses VALUES (23479, 40, 9, 31, 'o porém saindo divulgaram ele em toda o terra naquela');
INSERT INTO verses VALUES (23480, 40, 9, 32, 'deles porém saindo eis trouxeram a ele mudo sendo-endemoninhado');
INSERT INTO verses VALUES (23481, 40, 9, 33, 'e tendo-sido-lançado-fora o demônio falou o mudo e admiraram-se o multidões dizendo Nunca apareceu assim em o Israel');
INSERT INTO verses VALUES (23482, 40, 9, 34, 'o porém fariseus diziam em o governante o demônios expulsa o demônios');
INSERT INTO verses VALUES (23483, 40, 9, 35, 'e percorria o Iesous o cidades todas e o aldeias ensinando em o nas-sinagogas deles e pregando o evangelho o do-reino e curando toda doença e toda enfermidade');
INSERT INTO verses VALUES (23484, 40, 9, 36, 'Vendo porém o multidões compadeceu-se acerca-de deles que eram Tendo-sido-esfolados e Tendo-sido-lançados como ovelhas não tendo pastor');
INSERT INTO verses VALUES (23485, 40, 9, 37, 'então diz o discípulos dele o por-um-lado ceifa muito o porém trabalhadores poucos');
INSERT INTO verses VALUES (23486, 40, 9, 38, 'suplicai portanto o do-Kyrios o ceifa para-que expulse trabalhadores para o ceifa dele');
INSERT INTO chapters VALUES (939, 40, 10, 42);
INSERT INTO verses VALUES (23487, 40, 10, 1, 'e tendo-chamado o doze discípulos dele deu a-eles autoridade espíritos impuros de-modo-que expulsar eles e curar toda doença e toda enfermidade');
INSERT INTO verses VALUES (23488, 40, 10, 2, 'o porém doze apóstolos o nomes é estas-coisas primeiro Simão o chamado Pedro e André o irmão dele e Tiago o o Zebedeu e João o irmão dele');
INSERT INTO verses VALUES (23489, 40, 10, 3, 'Filipe e Bartolomeu Tomé e Mateus o cobrador-de-impostos Tiago o o Alfeu e Tadeu');
INSERT INTO verses VALUES (23490, 40, 10, 4, 'Simão o Cananeu e Judas o Iscariotes o e entregando ele');
INSERT INTO verses VALUES (23491, 40, 10, 5, 'estes o doze enviou o Iesous ordenando a-eles dizendo para caminho nações não partais e para cidade samaritanos não entreis');
INSERT INTO verses VALUES (23492, 40, 10, 6, 'ide porém mais junto-a o ovelhas o tendo-se-perdido da-casa Israel');
INSERT INTO verses VALUES (23493, 40, 10, 7, 'indo porém proclamais dizendo que Tem-se-aproximado o reino o dos-céus');
INSERT INTO verses VALUES (23494, 40, 10, 8, 'enfermos curai mortos levantai leprosos limpais demônios lançai-fora gratuitamente recebestes gratuitamente dai');
INSERT INTO verses VALUES (23495, 40, 10, 9, 'não adquirais ouro nem prata nem bronze para o cintos vosso');
INSERT INTO verses VALUES (23496, 40, 10, 10, 'não alforje para caminho nem dois túnicas nem sandálias nem vara digno pois o trabalhador o alimento dele');
INSERT INTO verses VALUES (23497, 40, 10, 11, 'para o qual e/mas partícula-condicional cidade ou aldeia entreis examinai quem em a-ela digno é e-ali permanecei até partícula-condicional saiais');
INSERT INTO verses VALUES (23498, 40, 10, 12, 'entrando porém para o casa saudai ela');
INSERT INTO verses VALUES (23499, 40, 10, 13, 'e se por-um-lado seja o casa digna venha o paz vosso sobre ela se porém não seja digna o paz vosso junto-a vos volte-se');
INSERT INTO verses VALUES (23500, 40, 10, 14, 'e o qual partícula-condicional não receba vos nem ouça o palavras vosso saindo fora o da-casa ou o cidade daquela sacudi o poeira o pés vosso');
INSERT INTO verses VALUES (23501, 40, 10, 15, 'amém digo a-vós mais-tolerável será terra Sodoma e Gomorra em dia julgamento ou o na-cidade naquela');
INSERT INTO verses VALUES (23502, 40, 10, 16, 'Eis eu envio vos como ovelhas em no-meio lobos tornai-vos portanto prudentes como o serpentes e puros como o pombas');
INSERT INTO verses VALUES (23503, 40, 10, 17, 'Guardai-vos porém de o dos-homens entregarão pois vos para sinédrios e em o nas-sinagogas deles açoitarão vos');
INSERT INTO verses VALUES (23504, 40, 10, 18, 'e sobre governadores porém e reis sereis-levados por-causa-de mim para testemunho a-eles e o nações');
INSERT INTO verses VALUES (23505, 40, 10, 19, 'quando porém entreguem vos não preocupeis como ou quê faleis será-dado pois a-vós em naquela o hora quê faleis');
INSERT INTO verses VALUES (23506, 40, 10, 20, 'não pois vós sois o falando mas o espírito o do-Pai vosso o falando em a-vós');
INSERT INTO verses VALUES (23507, 40, 10, 21, 'entregará porém irmão irmão para morte e Pai filho e levantar-se-ão-contra filhos sobre pais e matarão eles');
INSERT INTO verses VALUES (23508, 40, 10, 22, 'e sereis odiados sob todos através-de o nome meu o porém tendo-perseverado para fim este será-salvo');
INSERT INTO verses VALUES (23509, 40, 10, 23, 'quando porém persigam vos em o na-cidade nesta fugi para o outra amém pois digo a-vós não não completeis o cidades o Israel até venha o Filho o do-homem');
INSERT INTO verses VALUES (23510, 40, 10, 24, 'não é discípulo em-favor-de o mestre nem servo em-favor-de o Kyrion dele');
INSERT INTO verses VALUES (23511, 40, 10, 25, 'suficiente o discípulo para que aconteça como o mestre dele e o servo como o kyrios dele se o senhor-da-casa Belzebu invocaram quanto mais o domésticos dele');
INSERT INTO verses VALUES (23512, 40, 10, 26, 'não portanto temais eles nada pois é tendo-sido-coberto o qual não será-revelado e oculto o qual não será-conhecido');
INSERT INTO verses VALUES (23513, 40, 10, 27, 'o qual digo a-vós em o trevas dizei em o luz e o qual para o ouvido ouvi proclamai sobre o terraços');
INSERT INTO verses VALUES (23514, 40, 10, 28, 'e não temeis de o matando o corpo o porém alma não podendo matar temeis porém mais o podendo e alma e corpo destruir em Geena');
INSERT INTO verses VALUES (23515, 40, 10, 29, 'não dois pardais asse é-vendido e um de deles não cairá sobre o terra sem o do-Pai vosso');
INSERT INTO verses VALUES (23516, 40, 10, 30, 'vosso porém e o cabelos o cabeça todas tendo-sido-contadas são');
INSERT INTO verses VALUES (23517, 40, 10, 31, 'não portanto temeis muitos pardais diferis vós');
INSERT INTO verses VALUES (23518, 40, 10, 32, 'todo portanto qualquer-que confessará em mim diante-de o dos-homens confessarei e-eu em a ele diante-de o do-Pai meu o em o nos-céus');
INSERT INTO verses VALUES (23519, 40, 10, 33, 'qualquer-que e/mas partícula-condicional negue me diante-de o dos-homens negarei e-eu ele diante-de o do-Pai meu o em o nos-céus');
INSERT INTO verses VALUES (23520, 40, 10, 34, 'não penseis que vieram lançar paz sobre o terra não vieram lançar paz mas espada');
INSERT INTO verses VALUES (23521, 40, 10, 35, 'vieram pois dividir homem segundo o do-Pai dele e filha segundo o mãe dela e noiva segundo o sogra dela');
INSERT INTO verses VALUES (23522, 40, 10, 36, 'e inimigos o do-homem o domésticos dele');
INSERT INTO verses VALUES (23523, 40, 10, 37, 'o amando Pai ou mãe em-favor-de mim não é meu digno e o amando Filho ou filha em-favor-de mim não é meu digno');
INSERT INTO verses VALUES (23524, 40, 10, 38, 'e o qual não recebe o cruz dele e segue atrás meu não é meu digno');
INSERT INTO verses VALUES (23525, 40, 10, 39, 'o encontrando o alma dele destruirá ela e o tendo-perdido o alma dele por-causa-de mim encontrará ela');
INSERT INTO verses VALUES (23526, 40, 10, 40, 'o recebendo vos mim recebe e o mim recebendo recebe o enviante me');
INSERT INTO verses VALUES (23527, 40, 10, 41, 'o recebendo profeta para nome profeta salário profeta receberá e o recebendo justo para nome justo salário justo receberá');
INSERT INTO verses VALUES (23528, 40, 10, 42, 'e o qual se dê-de-beber um o pequenos destes cálice frio somente para nome discípulo amém digo a-vós não não destrua o salário dele');
INSERT INTO chapters VALUES (940, 40, 11, 30);
INSERT INTO verses VALUES (23529, 40, 11, 1, 'e aconteceu quando terminou o Iesous ordenando o doze discípulos dele passou dali o ensinar e proclamar em o cidades deles');
INSERT INTO verses VALUES (23530, 40, 11, 2, 'o porém João ouvindo em o prisão o obra o de-Christos tendo-enviado através-de o discípulos dele');
INSERT INTO verses VALUES (23531, 40, 11, 3, 'disse a ele tu és o o-que-vem ou outro esperemos');
INSERT INTO verses VALUES (23532, 40, 11, 4, 'e respondendo o Iesous disse a-eles Tendo-ido anunciai João o qual ouvi e vede');
INSERT INTO verses VALUES (23533, 40, 11, 5, 'cegos recuperam-a-vista e coxos andam leprosos são-purificados e mudos ouvem e mortos são-levantados e pobres anunciam-boa-nova');
INSERT INTO verses VALUES (23534, 40, 11, 6, 'e bem-aventurado é o qual se não seja-escandalizado em a-mim');
INSERT INTO verses VALUES (23535, 40, 11, 7, 'Destas-coisas porém indo começou o Iesous dizer o às-multidões acerca-de João quê saístes para o deserto contemplar cana sob vento sendo-abalado');
INSERT INTO verses VALUES (23536, 40, 11, 8, 'mas quê saístes ver homem em moles tendo-sido-vestido eis o o macias carregando em o casas o reis');
INSERT INTO verses VALUES (23537, 40, 11, 9, 'mas quê saístes profeta ver sim digo a-vós e abundantemente profeta');
INSERT INTO verses VALUES (23538, 40, 11, 10, 'este é acerca-de o qual está-escrito Eis eu envio o anjo meu antes-de face teu o qual preparará o caminho teu diante-de teu');
INSERT INTO verses VALUES (23539, 40, 11, 11, 'amém digo a-vós não foi-levantado em nascidos mulheres maior João o Batista o porém menor em o no-reino o dos-céus maior dele é');
INSERT INTO verses VALUES (23540, 40, 11, 12, 'de porém o dos-dias João o Batista até agora o reino o dos-céus é-tomado-à-força e violentos arrebatam ela');
INSERT INTO verses VALUES (23541, 40, 11, 13, 'todos pois o profetas e o lei até João Profetizaram');
INSERT INTO verses VALUES (23542, 40, 11, 14, 'e se quereis receber ele é Elias o estando-prestes-a vir');
INSERT INTO verses VALUES (23543, 40, 11, 15, 'o tendo ouvidos ouça');
INSERT INTO verses VALUES (23544, 40, 11, 16, 'A-quem porém compararei o geração esta semelhante é criancinhas sentados em o praças o qual chamando o outros');
INSERT INTO verses VALUES (23545, 40, 11, 17, 'dizem Tocamos-flauta a-vós e não dançastes lamentamos e não lamentastes');
INSERT INTO verses VALUES (23546, 40, 11, 18, 'veio pois João nem comendo nem bebendo e dizem Demônio tem');
INSERT INTO verses VALUES (23547, 40, 11, 19, 'veio o Filho o do-homem comendo e bebendo e dizem Eis homem comilão e bebedor-de-vinho cobradores-de-impostos amigo e dos-pecadores e foi-justificado o sabedoria de o obra dela');
INSERT INTO verses VALUES (23548, 40, 11, 20, 'Então começou injuriar o cidades em o qual tornaram-se o muitíssimas poderes dele que não arrependeram-se');
INSERT INTO verses VALUES (23549, 40, 11, 21, 'ai a-ti Corazim ai a-ti Betsaida que se em Tiro e Sidom tornaram-se o poderes o acontecidas em a-vós outrora partícula-condicional em saco e cinza arrependeram-se');
INSERT INTO verses VALUES (23550, 40, 11, 22, 'porém digo a-vós Tiro e Sidom mais-tolerável será em dia julgamento ou a-vós');
INSERT INTO verses VALUES (23551, 40, 11, 23, 'e tu Cafarnaum não até do-céu serás-exaltado até Hades desças que se em Sodoma tornaram-se o poderes o acontecidas em a-ti permaneceu partícula-condicional até o hoje');
INSERT INTO verses VALUES (23552, 40, 11, 24, 'porém digo a-vós que terra Sodoma mais-tolerável será em dia julgamento ou a-ti');
INSERT INTO verses VALUES (23553, 40, 11, 25, 'em naquele o tempo respondendo o Iesous disse Confesso a-ti Pai Kyrie o do-céu e o da-terra que Escondeste estas-coisas de sábios e entendidos e revelaste eles infantes');
INSERT INTO verses VALUES (23554, 40, 11, 26, 'sim o Pai que assim boa-vontade aconteceu diante-de teu');
INSERT INTO verses VALUES (23555, 40, 11, 27, 'todas-as-coisas a-mim foi-entregue sob o do-Pai meu e ninguém conhece-plenamente o Filho se não o Pai nem o Pai alguém conhece-plenamente se não o Filho e o qual se queira o Filho revelar');
INSERT INTO verses VALUES (23556, 40, 11, 28, 'Vinde para me todos o labutando e tendo-sido-carregados e-eu darei-descanso vos');
INSERT INTO verses VALUES (23557, 40, 11, 29, 'levantai o jugo meu sobre vos e aprendei de mim que manso sou e humilde o no-coração e encontrareis descanso o almas vosso');
INSERT INTO verses VALUES (23558, 40, 11, 30, 'o pois jugo meu benigno e o carga meu leve é');
INSERT INTO chapters VALUES (941, 40, 12, 50);
INSERT INTO verses VALUES (23559, 40, 12, 1, 'em naquele o tempo foi o Iesous o nos-sábados através-de o searas o porém discípulos dele tiveram-fome e começaram arrancar espigas e comer');
INSERT INTO verses VALUES (23560, 40, 12, 2, 'o porém fariseus vendo disseram a ele Eis o discípulos teu fazem o qual não é-lícito fazer em no-sábado');
INSERT INTO verses VALUES (23561, 40, 12, 3, 'o porém disse a-eles não lestes quê fez Davi quando teve-fome e o com dele');
INSERT INTO verses VALUES (23562, 40, 12, 4, 'como entrou para o casa o de-Theos e o pães o propósito comeram o qual não sendo-lícito era a ele comer nem o com dele se não o sacerdotes somente');
INSERT INTO verses VALUES (23563, 40, 12, 5, 'ou não lestes em o lei que o nos-sábados o sacerdotes em o templo o sábado profanam e inocentes são');
INSERT INTO verses VALUES (23564, 40, 12, 6, 'digo porém a-vós que o do-templo maior é aqui');
INSERT INTO verses VALUES (23565, 40, 12, 7, 'se porém tínheis-conhecido quê é Misericórdia quero e não sacrifício não partícula-condicional condenastes o inocentes');
INSERT INTO verses VALUES (23566, 40, 12, 8, 'Kyrios pois é o do-sábado o Filho o do-homem');
INSERT INTO verses VALUES (23567, 40, 12, 9, 'e tendo-passado dali veio para o sinagoga deles');
INSERT INTO verses VALUES (23568, 40, 12, 10, 'e eis homem mão tendo seca e perguntaram ele dizendo se é-lícito o nos-sábados curar para que acusem dele');
INSERT INTO verses VALUES (23569, 40, 12, 11, 'o porém disse a-eles Quem será de vosso homem o qual terá ovelha um e se caia-dentro isto o nos-sábados para cova não segurará ele e levantará');
INSERT INTO verses VALUES (23570, 40, 12, 12, 'quanto portanto difere homem ovelha de-modo-que é-lícito o nos-sábados bem fazer');
INSERT INTO verses VALUES (23571, 40, 12, 13, 'então diz o ao-homem Estende teu o mão e estendeu e foi-restaurado são como o outra');
INSERT INTO verses VALUES (23572, 40, 12, 14, 'saindo porém o fariseus conselho receberam segundo dele para-que ele destruam');
INSERT INTO verses VALUES (23573, 40, 12, 15, 'o porém Iesous sabendo retirou-se dali e seguiram a ele muitos e curou eles todos');
INSERT INTO verses VALUES (23574, 40, 12, 16, 'e repreendeu a-eles para que não manifesto ele façam');
INSERT INTO verses VALUES (23575, 40, 12, 17, 'para que seja-cumprido o o-dito através-de Isaías o profeta dizendo');
INSERT INTO verses VALUES (23576, 40, 12, 18, 'Eis o servo meu o qual Escolhi o amado meu o qual agradou-se o alma meu porei o Espírito meu sobre ele e juízo o nações anunciará');
INSERT INTO verses VALUES (23577, 40, 12, 19, 'não Contenderá nem clamará nem ouvirá alguém em o praças o voz dele');
INSERT INTO verses VALUES (23578, 40, 12, 20, 'cana tendo-sido-quebrado não quebrará e linho sendo-enfumaçado não apagará até partícula-condicional expulse para vitória o juízo');
INSERT INTO verses VALUES (23579, 40, 12, 21, 'e o em-nome dele nações esperam');
INSERT INTO verses VALUES (23580, 40, 12, 22, 'Então foi-oferecido a ele sendo-endemoninhado cego e mudo e curou ele de-modo-que o mudo falar e ver');
INSERT INTO verses VALUES (23581, 40, 12, 23, 'e ficavam-fora-de-si todos o multidões e diziam Acaso este é o Filho Davi');
INSERT INTO verses VALUES (23582, 40, 12, 24, 'o porém fariseus ouvindo disseram este não expulsa o demônios se não em o Belzebu governante o demônios');
INSERT INTO verses VALUES (23583, 40, 12, 25, 'sei porém o pensamentos deles disse a-eles toda reino tendo-sido-dividida segundo de-si-mesma é-desolada e toda cidade ou casa tendo-sido-dividida segundo de-si-mesma não será-estabelecido');
INSERT INTO verses VALUES (23584, 40, 12, 26, 'e se o Satanás o Satanás expulsa sobre si-mesmo foi-dividido como portanto será-estabelecido o reino dele');
INSERT INTO verses VALUES (23585, 40, 12, 27, 'e se eu em Belzebu expulso o demônios o filhos vosso em a-quem expulsam através-de isto eles-mesmos juízes serão vosso');
INSERT INTO verses VALUES (23586, 40, 12, 28, 'se porém em Espírito de-Theos eu expulso o demônios então chegou sobre vos o reino o de-Theos');
INSERT INTO verses VALUES (23587, 40, 12, 29, 'ou como pode alguém entrar para o casa o forte e o vasos dele arrebatar se não primeiro amarre o Forte e então o casa dele saqueará');
INSERT INTO verses VALUES (23588, 40, 12, 30, 'o não sendo com mim segundo mim é e o não reunindo com mim dispersa');
INSERT INTO verses VALUES (23589, 40, 12, 31, 'através-de isto digo a-vós toda pecado e blasfêmia será-perdoado o aos-homens o porém o do-espírito blasfêmia não será-perdoado');
INSERT INTO verses VALUES (23590, 40, 12, 32, 'e o qual se diga palavra segundo o do-Filho o do-homem será-perdoado a ele o qual e/mas partícula-condicional diga segundo o do-espírito o do-santo não será-perdoado a ele nem em neste o era nem em o vindouro');
INSERT INTO verses VALUES (23591, 40, 12, 33, 'ou fazei o árvore belo e o fruto dele bom ou fazei o árvore podre e o fruto dele podre de pois o fruto o árvore é-conhecida');
INSERT INTO verses VALUES (23592, 40, 12, 34, 'crias víboras como podeis boas-coisas falar maus sendo de pois o abundância o do-coração o boca fala');
INSERT INTO verses VALUES (23593, 40, 12, 35, 'o bom homem de o bom tesouro expulsa boas-coisas e o mau homem de o do-mal tesouro expulsa má');
INSERT INTO verses VALUES (23594, 40, 12, 36, 'digo porém a-vós que todo palavra ocioso o qual falarão o homens retribuirão acerca-de dele palavra em dia julgamento');
INSERT INTO verses VALUES (23595, 40, 12, 37, 'de pois o palavras teu sejas-justificado e de o palavras teu serás-condenado');
INSERT INTO verses VALUES (23596, 40, 12, 38, 'Então responderam a ele alguns o dos-escribas e fariseus dizendo Mestre queremos de teu sinal ver');
INSERT INTO verses VALUES (23597, 40, 12, 39, 'o porém respondendo disse a-eles Geração má e adúltera sinal busca e sinal não será-dado a-ela se não o sinal Jonas o profeta');
INSERT INTO verses VALUES (23598, 40, 12, 40, 'assim-como pois era Jonas em o ventre o grande-peixe três do-dia e três noites assim será o Filho o do-homem em o no-coração o da-terra três do-dia e três noites');
INSERT INTO verses VALUES (23599, 40, 12, 41, 'homens Ninivitas ressuscitarão em o juízo com o geração desta e condenarão ela que arrependeram-se para o pregação Jonas e eis mais Jonas aqui');
INSERT INTO verses VALUES (23600, 40, 12, 42, 'rainha sul será-levantado em o juízo com o geração desta e condenará ela que veio de o confins o da-terra ouvir o sabedoria Salomão e eis mais Salomão aqui');
INSERT INTO verses VALUES (23601, 40, 12, 43, 'quando porém o impuro espírito saia de o do-homem atravessa através-de sem-água lugares buscando descanso e não encontra');
INSERT INTO verses VALUES (23602, 40, 12, 44, 'então diz para o casa meu voltarei de-onde saíram e tendo-vindo encontra estando-desocupado e tendo-sido-varrido e tendo-sido-adornado');
INSERT INTO verses VALUES (23603, 40, 12, 45, 'então vai e toma-consigo com si-mesmo sete outras espíritos piores si-mesmo e entrando habita ali e torna-se o últimas o do-homem daquele piores o primeiro assim será e o geração nesta o má');
INSERT INTO verses VALUES (23604, 40, 12, 46, 'ainda dele falando o às-multidões eis o mãe e o irmãos dele estavam-de-pé fora buscando a ele falar');
INSERT INTO verses VALUES (23605, 40, 12, 47, 'disse e/mas alguém a ele Eis o mãe teu e o irmãos teu fora estão-de-pé buscando a-ti falar');
INSERT INTO verses VALUES (23606, 40, 12, 48, 'o porém respondendo disse o dizendo a ele Quem é o mãe meu e quem são o irmãos meu');
INSERT INTO verses VALUES (23607, 40, 12, 49, 'e estendendo o mão dele sobre o discípulos dele disse Eis o mãe meu e o irmãos meu');
INSERT INTO verses VALUES (23608, 40, 12, 50, 'qualquer-que pois partícula-condicional faça o vontade o do-Pai meu o em nos-céus ele-mesmo meu irmão e irmã e mãe é');
INSERT INTO chapters VALUES (942, 40, 13, 58);
INSERT INTO verses VALUES (23609, 40, 13, 1, 'em o dia naquela saindo o Iesous o da-casa sentava-se de-junto-de o mar');
INSERT INTO verses VALUES (23610, 40, 13, 2, 'e foram-reunidos junto-a ele multidões muitos de-modo-que ele para barco tendo-embarcado sentar e todo o multidão sobre o praia estava-de-pé');
INSERT INTO verses VALUES (23611, 40, 13, 3, 'e falou a-eles muitas-coisas em em-parábolas dizendo Eis saiu o o-que-semeia o semear');
INSERT INTO verses VALUES (23612, 40, 13, 4, 'e em o semear ele o qual por-um-lado caiu de-junto-de o caminho e tendo-vindo o aves devorou elas');
INSERT INTO verses VALUES (23613, 40, 13, 5, 'outras-coisas porém caiu sobre o pedregosos onde não tinha terra muita e imediatamente brotou através-de o não ter profundidade da-terra');
INSERT INTO verses VALUES (23614, 40, 13, 6, 'sol porém tendo-nascido foi-queimado e através-de o não ter raiz secou');
INSERT INTO verses VALUES (23615, 40, 13, 7, 'outras-coisas porém caiu sobre o espinhos e subiram o espinhos e sufocaram elas');
INSERT INTO verses VALUES (23616, 40, 13, 8, 'outras-coisas porém caiu sobre o terra o boa e dava fruto o qual por-um-lado cem o qual porém sessenta o qual porém trinta');
INSERT INTO verses VALUES (23617, 40, 13, 9, 'o tendo ouvidos ouça');
INSERT INTO verses VALUES (23618, 40, 13, 10, 'e aproximando-se o discípulos disseram a ele através-de quê em em-parábolas falas a-eles');
INSERT INTO verses VALUES (23619, 40, 13, 11, 'o porém respondendo disse que a-vós foi-dado conhecer o mistérios o do-reino o dos-céus àqueles porém não foi-dado');
INSERT INTO verses VALUES (23620, 40, 13, 12, 'qualquer-que pois tem será-dado a ele e será-feito-abundar qualquer-que porém não tem e o qual tem será-tirado de dele');
INSERT INTO verses VALUES (23621, 40, 13, 13, 'através-de isto em em-parábolas a-eles falo que vendo não veem e ouvindo não ouvem nem compreendem');
INSERT INTO verses VALUES (23622, 40, 13, 14, 'e é-preenchido a-eles o profecia Isaías o dizendo Ouvido ouvireis e não não compreendais e vendo vereis e não não vejais');
INSERT INTO verses VALUES (23623, 40, 13, 15, 'engrossou-se pois o coração o povo deste e o ouvidos pesadamente ouviram e o olhos deles fecharam não alguma-vez vejam o olhos e o ouvidos ouçam e o no-coração compreendam e convertam-se e curarei eles');
INSERT INTO verses VALUES (23624, 40, 13, 16, 'vosso porém bem-aventurados o olhos que veem e o ouvidos vosso que ouvem');
INSERT INTO verses VALUES (23625, 40, 13, 17, 'amém pois digo a-vós que muitos profetas e justos desejaram ver o qual vede e não viram e ouvir o qual ouvi e não ouviram');
INSERT INTO verses VALUES (23626, 40, 13, 18, 'vós portanto ouvi o parábola o tendo-semeado');
INSERT INTO verses VALUES (23627, 40, 13, 19, 'todo ouvindo o palavra o do-reino e não compreendendo vem o mau e arrebata o tendo-sido-semeado em o no-coração dele este é o de-junto-de o caminho semeado');
INSERT INTO verses VALUES (23628, 40, 13, 20, 'o porém sobre o pedregosos semeado este é o o palavra ouvindo e imediatamente com alegria recebendo ele');
INSERT INTO verses VALUES (23629, 40, 13, 21, 'não tem porém raiz em si-mesmo mas temporário é tendo-acontecido porém tribulação ou perseguição através-de o palavra imediatamente é-escandalizado');
INSERT INTO verses VALUES (23630, 40, 13, 22, 'o porém para o espinhos semeado este é o o palavra ouvindo e o preocupação o eternidade e o engano o riqueza sufoca o palavra e infrutífero torna-se');
INSERT INTO verses VALUES (23631, 40, 13, 23, 'o porém sobre o boa terra semeado este é o o palavra ouvindo e compreendes o qual pois frutifica e faz o qual por-um-lado cem o qual porém sessenta o qual porém trinta');
INSERT INTO verses VALUES (23632, 40, 13, 24, 'outra parábola pôs-diante a-eles dizendo Foi-comparado o reino o dos-céus ao-homem tendo-semeado belo semente em o campo dele');
INSERT INTO verses VALUES (23633, 40, 13, 25, 'em porém o dormir o homens veio dele o inimigo e semeou-sobre joio cada meio o trigo e partiu');
INSERT INTO verses VALUES (23634, 40, 13, 26, 'quando porém brotou o erva e fruto fez então apareceu e o joio');
INSERT INTO verses VALUES (23635, 40, 13, 27, 'aproximando-se porém o servos o dono-de-casa disseram a ele Kyrie não belo semente semeaste em o teu campo de-onde portanto tem joio');
INSERT INTO verses VALUES (23636, 40, 13, 28, 'o porém disse a-eles Inimigo homem isto fez o porém servos a ele dizem Queres portanto tendo-ido-embora colhamos elas');
INSERT INTO verses VALUES (23637, 40, 13, 29, 'o e/mas diz Não não alguma-vez colhendo o joio desarraigueis juntamente a-eles o trigo');
INSERT INTO verses VALUES (23638, 40, 13, 30, 'deixai crescer-junto ambos até o ceifa e em tempo o ceifa direi o ceifeiros Recolhei primeiro o joio e amarrai eles para feixes junto-a o queimar elas o porém trigo reuni para o celeiro meu');
INSERT INTO verses VALUES (23639, 40, 13, 31, 'outra parábola pôs-diante a-eles dizendo semelhante é o reino o dos-céus grão mostarda o qual tomando homem semeou em o campo dele');
INSERT INTO verses VALUES (23640, 40, 13, 32, 'o qual menor de-fato é todos o sementes quando porém seja-feito-crescer maior o hortaliças é e torna-se árvore de-modo-que vir o aves o do-céu e aninhar em o ramos dele');
INSERT INTO verses VALUES (23641, 40, 13, 33, 'outra parábola falou a-eles semelhante é o reino o dos-céus fermento o qual tomando mulher escondeu-dentro para farinha satas três até o qual foi-levedado todo');
INSERT INTO verses VALUES (23642, 40, 13, 34, 'estas-coisas todas-as-coisas falou o Iesous em em-parábolas o às-multidões e sem parábola nada falava a-eles');
INSERT INTO verses VALUES (23643, 40, 13, 35, 'para-que seja-cumprido o o-dito através-de o profeta dizendo Abrirei em em-parábolas o boca meu Proclamarei tendo-sido-escondidas de fundação');
INSERT INTO verses VALUES (23644, 40, 13, 36, 'Então deixando o multidões veio para o casa e aproximaram-se a ele o discípulos dele dizendo Explica-claramente a-nós o parábola o joio o campo');
INSERT INTO verses VALUES (23645, 40, 13, 37, 'o porém respondendo disse o o-que-semeia o belo semente é o Filho o do-homem');
INSERT INTO verses VALUES (23646, 40, 13, 38, 'o porém campo é o mundo o porém belo semente estes são o filhos o do-reino o porém joio são o filhos o do-mal');
INSERT INTO verses VALUES (23647, 40, 13, 39, 'o porém inimigo o tendo-semeado elas é o diabo o porém colheita consumação era é o porém ceifeiros anjo são');
INSERT INTO verses VALUES (23648, 40, 13, 40, 'assim-como portanto é-colhido o joio e fogo é-queimado assim será em o consumação o eternidade');
INSERT INTO verses VALUES (23649, 40, 13, 41, 'enviará o Filho o do-homem o anjo dele e colherão de o do-reino dele todas-as-coisas o escândalos e o fazendo o iniquidade');
INSERT INTO verses VALUES (23650, 40, 13, 42, 'e lançarão eles para o fornalha o fogo ali será o choro e o ranger o dentes');
INSERT INTO verses VALUES (23651, 40, 13, 43, 'então o justos resplandecerão como o sol em o no-reino o do-Pai deles o tendo ouvidos ouça');
INSERT INTO verses VALUES (23652, 40, 13, 44, 'semelhante é o reino o dos-céus tesouro tendo-sido-escondido em o campo o qual encontrando homem escondeu e de o alegria dele vai e vende quanto tem e compra o campo aquele');
INSERT INTO verses VALUES (23653, 40, 13, 45, 'novamente semelhante é o reino o dos-céus comerciante buscando bons pérolas');
INSERT INTO verses VALUES (23654, 40, 13, 46, 'encontrando porém um muito-precioso pérola partindo tem-vendido todas-as-coisas quanto tinha e comprou ele');
INSERT INTO verses VALUES (23655, 40, 13, 47, 'novamente semelhante é o reino o dos-céus em-rede-de-arrasto tendo-sido-lançada para o mar e de de-todo raça tendo-reunido');
INSERT INTO verses VALUES (23656, 40, 13, 48, 'o qual quando foi-cumprido tendo-puxado-para-cima sobre o praia e tendo-sentado recolheram o boas para vasos o porém podre fora lançaram');
INSERT INTO verses VALUES (23657, 40, 13, 49, 'assim será em o consumação o eternidade sairão o anjo e separarão o maus de meio o justos');
INSERT INTO verses VALUES (23658, 40, 13, 50, 'e lançarão eles para o fornalha o fogo ali será o choro e o ranger o dentes');
INSERT INTO verses VALUES (23659, 40, 13, 51, 'Compreendestes estas-coisas todas-as-coisas dizem a ele Sim');
INSERT INTO verses VALUES (23660, 40, 13, 52, 'o porém disse a-eles através-de isto todo escriba tendo-sido-feito-discípulo o no-reino o dos-céus semelhante é ao-homem senhor-da-casa qualquer-que expulsa de o tesouro dele novas e velha');
INSERT INTO verses VALUES (23661, 40, 13, 53, 'e aconteceu quando terminou o Iesous o parábolas estas partiu dali');
INSERT INTO verses VALUES (23662, 40, 13, 54, 'e vindo para o pátria dele ensinava eles em o na-sinagoga deles de-modo-que estar-assombrado eles e dizer de-onde neste o sabedoria esta e o poderes');
INSERT INTO verses VALUES (23663, 40, 13, 55, 'não este é o o de-carpinteiro filho não o mãe dele é-chamado Maria e o irmãos dele Tiago e José e Simão e Judas');
INSERT INTO verses VALUES (23664, 40, 13, 56, 'e o irmãs dele não todas junto-a nos são de-onde portanto neste estas-coisas todas-as-coisas');
INSERT INTO verses VALUES (23665, 40, 13, 57, 'e eram-escandalizados em a ele o porém Iesous disse a-eles não é profeta sem-honra se não em o pátria e em o casa dele');
INSERT INTO verses VALUES (23666, 40, 13, 58, 'e não fez ali poderes muitas através-de o incredulidade deles');
INSERT INTO chapters VALUES (943, 40, 14, 36);
INSERT INTO verses VALUES (23667, 40, 14, 1, 'em naquele o tempo ouviu Herodes o tetrarca o audição Iesous');
INSERT INTO verses VALUES (23668, 40, 14, 2, 'e disse o crianças dele Este é João o Batista ele foi-ressuscitado de o mortos e através-de isto o poderes operam em a ele');
INSERT INTO verses VALUES (23669, 40, 14, 3, 'o pois Herodes segurando o João amarrou e em na-prisão depôs através-de Herodíade o mulher Filipe o do-irmão dele');
INSERT INTO verses VALUES (23670, 40, 14, 4, 'dizia pois o João a ele não é-lícito a-ti ter ela');
INSERT INTO verses VALUES (23671, 40, 14, 5, 'e querendo ele matar temeu o multidão que como profeta ele tinham');
INSERT INTO verses VALUES (23672, 40, 14, 6, 'aniversário porém tendo-acontecido o de-Herodes Dançou o filha o Herodíades em o no-meio e agradou o Herodes');
INSERT INTO verses VALUES (23673, 40, 14, 7, 'de-onde com juramento confessou a-ela dar o qual se peça');
INSERT INTO verses VALUES (23674, 40, 14, 8, 'o porém tendo-sido-instigada sob o mãe dela Dá a-mim diz aqui sobre prato o cabeça João o Batista');
INSERT INTO verses VALUES (23675, 40, 14, 9, 'e tendo-sido-entristecido o rei através-de o juramentos e o reclinando-se-à-mesa-com ordenou ser-dado');
INSERT INTO verses VALUES (23676, 40, 14, 10, 'e tendo-enviado decapitou João em o na-prisão');
INSERT INTO verses VALUES (23677, 40, 14, 11, 'e foi-trazido o cabeça dele sobre prato e foi-dado o menina e trouxe o mãe dela');
INSERT INTO verses VALUES (23678, 40, 14, 12, 'e aproximando-se o discípulos dele levantaram o cadáver e sepultaram ele e vindo anunciaram o Iesous');
INSERT INTO verses VALUES (23679, 40, 14, 13, 'ouvindo porém o Iesous retirou-se dali em no-barco para deserto lugar segundo própria e ouvindo o multidões seguiram a ele a-pé de o cidades');
INSERT INTO verses VALUES (23680, 40, 14, 14, 'e saindo viu muito multidão e compadeceu-se sobre a-eles e curou o enfermos deles');
INSERT INTO verses VALUES (23681, 40, 14, 15, 'tarde porém tendo-acontecido aproximaram-se a ele o discípulos dizendo Deserta é o lugar e o hora já passou liberta portanto o multidões para que tendo-ido-embora para o aldeias comprem si-mesmos alimentos');
INSERT INTO verses VALUES (23682, 40, 14, 16, 'o porém Iesous disse a-eles não necessidade têm ir-embora dai a-eles vós comer');
INSERT INTO verses VALUES (23683, 40, 14, 17, 'o porém dizem a ele não temos aqui se não cinco pães e dois peixes');
INSERT INTO verses VALUES (23684, 40, 14, 18, 'o porém disse Trazei a-mim aqui eles');
INSERT INTO verses VALUES (23685, 40, 14, 19, 'e tendo-ordenado o multidões ser-reclinado sobre o erva tomando o cinco pães e o dois peixes olhando-para-cima para o céu abençoou e partindo deu o discípulos o pães o porém discípulos o às-multidões');
INSERT INTO verses VALUES (23686, 40, 14, 20, 'e comeram todos e foram-saciados e levantaram o abundando o pedaços doze cestos cheios');
INSERT INTO verses VALUES (23687, 40, 14, 21, 'o porém comendo eram homens como cinco-mil sem mulheres e crianças');
INSERT INTO verses VALUES (23688, 40, 14, 22, 'e imediatamente compeliu o discípulos embarcar para o barco e conduzir-adiante ele para o além até o qual solte o multidões');
INSERT INTO verses VALUES (23689, 40, 14, 23, 'e tendo-soltado o multidões subiu para o monte segundo própria orar tarde porém tendo-acontecido só era ali');
INSERT INTO verses VALUES (23690, 40, 14, 24, 'o porém barco já estádios a-muitos de o da-terra estava-distante sendo-atormentado sob o ondas era pois contrário o vento');
INSERT INTO verses VALUES (23691, 40, 14, 25, 'quarta porém na-prisão o da-noite veio junto-a eles caminhando sobre o mar');
INSERT INTO verses VALUES (23692, 40, 14, 26, 'o porém discípulos vendo ele sobre o do-mar andando foram-perturbados dizendo que Fantasma é e de o medo clamaram');
INSERT INTO verses VALUES (23693, 40, 14, 27, 'imediatamente porém falou o Iesous a-eles dizendo Tende-coragem eu sou não temei');
INSERT INTO verses VALUES (23694, 40, 14, 28, 'respondendo porém a ele o Pedro disse Kyrie se tu és ordena me vir junto-a te sobre o água');
INSERT INTO verses VALUES (23695, 40, 14, 29, 'o porém disse vem e descendo de o do-barco Pedro andou sobre o água e veio junto-a o Iesous');
INSERT INTO verses VALUES (23696, 40, 14, 30, 'vendo porém o vento temeu e começando ser-afundado gritou dizendo Kyrie salva me');
INSERT INTO verses VALUES (23697, 40, 14, 31, 'imediatamente porém o Iesous estendendo o mão apoderou-se dele e diz a ele Pouca-fé para quê duvidaste');
INSERT INTO verses VALUES (23698, 40, 14, 32, 'e dos-que-subiram deles para o barco cessou o vento');
INSERT INTO verses VALUES (23699, 40, 14, 33, 'o porém em o no-barco adoraram a ele dizendo Verdadeiramente de-Theos Filho és');
INSERT INTO verses VALUES (23700, 40, 14, 34, 'e tendo-atravessado vieram sobre o terra para Genesaré');
INSERT INTO verses VALUES (23701, 40, 14, 35, 'e reconhecendo ele o homens o lugar daquele enviaram para toda o região-ao-redor aquela e trouxeram a ele todos o mal tendo');
INSERT INTO verses VALUES (23702, 40, 14, 36, 'e suplicavam ele para que somente toquem o franja o manto dele e quanto tocaram foram-salvos');
INSERT INTO chapters VALUES (944, 40, 15, 39);
INSERT INTO verses VALUES (23703, 40, 15, 1, 'Então aproximam-se o Iesous de Jerusalém fariseus e escribas dizendo');
INSERT INTO verses VALUES (23704, 40, 15, 2, 'através-de quê o discípulos teu transgridem o tradição o dos-anciãos não pois lavam o mãos quando pão comam');
INSERT INTO verses VALUES (23705, 40, 15, 3, 'o porém respondendo disse a-eles através-de quê e vós transgredis o mandamento o de-Theos através-de o tradição vosso');
INSERT INTO verses VALUES (23706, 40, 15, 4, 'o pois Theos disse Honra o Pai e o mãe e o falando-mal Pai ou mãe morte morra');
INSERT INTO verses VALUES (23707, 40, 15, 5, 'vós porém dizeis o qual partícula-condicional diga o pai ou o mãe Oferta o qual se de mim sejas-beneficiado');
INSERT INTO verses VALUES (23708, 40, 15, 6, 'não não honrará o Pai dele ou o mãe dele e anulastes o palavra o de-Theos através-de o tradição vosso');
INSERT INTO verses VALUES (23709, 40, 15, 7, 'hipócritas bem profetizou acerca-de vosso Isaías dizendo');
INSERT INTO verses VALUES (23710, 40, 15, 8, 'o povo este o lábios me honra o porém coração deles longe está-distante de mim');
INSERT INTO verses VALUES (23711, 40, 15, 9, 'em-vão porém adoram me ensinando ensino mandamentos dos-homens');
INSERT INTO verses VALUES (23712, 40, 15, 10, 'e tendo-chamado o multidão disse a-eles Ouvi e entendeis');
INSERT INTO verses VALUES (23713, 40, 15, 11, 'não o entrando para o boca contamina o homem mas o saindo de o da-boca isto contamina o homem');
INSERT INTO verses VALUES (23714, 40, 15, 12, 'Então aproximando-se o discípulos dizem a ele sei que o fariseus ouvindo o palavra Foram-escandalizados');
INSERT INTO verses VALUES (23715, 40, 15, 13, 'o porém respondendo disse toda plantação o qual não plantou o Pai meu o celestial será-desarraigado');
INSERT INTO verses VALUES (23716, 40, 15, 14, 'deixai eles cegos são guias cegos cego porém cego se guie ambos para cova cairão');
INSERT INTO verses VALUES (23717, 40, 15, 15, 'Tendo-respondido porém o Pedro disse a ele Explica a-nós o parábola');
INSERT INTO verses VALUES (23718, 40, 15, 16, 'o porém disse Ainda e vós insensatos sois');
INSERT INTO verses VALUES (23719, 40, 15, 17, 'não entendeis que todo o entrando para o boca para o ventre tem-espaço e para latrina é-lançado-fora');
INSERT INTO verses VALUES (23720, 40, 15, 18, 'o porém saindo de o da-boca de o do-coração sai e-aquelas contamina o homem');
INSERT INTO verses VALUES (23721, 40, 15, 19, 'de pois o do-coração saem raciocínios maus homicídios adultérios fornicações furtos falsos-testemunhos blasfêmias');
INSERT INTO verses VALUES (23722, 40, 15, 20, 'estas-coisas é o tornando-comum o homem o porém não-lavadas mãos comer não contamina o homem');
INSERT INTO verses VALUES (23723, 40, 15, 21, 'e saindo dali o Iesous retirou-se para o partes Tiro e Sidom');
INSERT INTO verses VALUES (23724, 40, 15, 22, 'e eis mulher Cananeia de o fronteiras daqueles tendo-saído gritava dizendo Tem-misericórdia me Kyrie Filho Davi o filha meu mal é-endemoninhado');
INSERT INTO verses VALUES (23725, 40, 15, 23, 'o porém não respondeu a-ela palavra e aproximando-se o discípulos dele perguntavam ele dizendo Liberta ela que clama atrás nosso');
INSERT INTO verses VALUES (23726, 40, 15, 24, 'o porém respondendo disse não fui-enviado se não para o ovelhas o tendo-se-perdido da-casa Israel');
INSERT INTO verses VALUES (23727, 40, 15, 25, 'o porém tendo-vindo adorava a ele dizendo Kyrie ajuda a-mim');
INSERT INTO verses VALUES (23728, 40, 15, 26, 'o porém respondendo disse não é belo receber o pão o filhos e lançar o cachorrinhos');
INSERT INTO verses VALUES (23729, 40, 15, 27, 'o porém disse Sim kyrie e pois o cachorrinhos come de o migalhas o caindo de o mesa o senhores deles');
INSERT INTO verses VALUES (23730, 40, 15, 28, 'então respondendo o Iesous disse a-ela Ômega mulher grande teu o fé seja-feito a-ti como queres e foi-curado o filha dela de o hora daquela');
INSERT INTO verses VALUES (23731, 40, 15, 29, 'e tendo-passado dali o Iesous veio de-junto-de o mar o Galileia e subindo para o monte sentava-se ali');
INSERT INTO verses VALUES (23732, 40, 15, 30, 'e aproximaram-se a ele multidões muitos tendo com deles-mesmos coxos aleijados cegos mudos e outros muitos e lançaram eles de-junto-de o pés dele e curou eles');
INSERT INTO verses VALUES (23733, 40, 15, 31, 'de-modo-que o multidão maravilhar-se vendo mudos falando aleijados sãos e coxos andando e cegos vendo e glorificaram o Theos Israel');
INSERT INTO verses VALUES (23734, 40, 15, 32, 'o porém Iesous tendo-chamado o discípulos dele disse Tenho-compaixão sobre o multidão que já dias três permanecem-junto a-mim e não têm quê comam e soltar eles em-jejum não quero não alguma-vez desfaleçam em o caminho');
INSERT INTO verses VALUES (23735, 40, 15, 33, 'e dizem a ele o discípulos de-onde a-nós em deserto pães tantos de-modo-que saciar multidão tanto');
INSERT INTO verses VALUES (23736, 40, 15, 34, 'e diz a-eles o Iesous Quantos pães tendes o porém disseram sete e poucas-coisas peixinhos');
INSERT INTO verses VALUES (23737, 40, 15, 35, 'e ordenando o à-multidão reclinar-se sobre o terra');
INSERT INTO verses VALUES (23738, 40, 15, 36, 'recebeu o sete pães e o peixes e tendo-dado-graças partiu e dava o discípulos o porém discípulos o às-multidões');
INSERT INTO verses VALUES (23739, 40, 15, 37, 'e comeram todos e fartaram-se e o abundando o pedaços levantaram sete cestos cheios');
INSERT INTO verses VALUES (23740, 40, 15, 38, 'o porém comendo eram quatro-mil homens sem mulheres e crianças');
INSERT INTO verses VALUES (23741, 40, 15, 39, 'e tendo-soltado o multidões embarcou para o barco e veio para o limites Magadã');
INSERT INTO chapters VALUES (945, 40, 16, 28);
INSERT INTO verses VALUES (23742, 40, 16, 1, 'e aproximando-se o fariseus e Saduceus tentando perguntaram ele sinal de o do-céu mostrar a-eles');
INSERT INTO verses VALUES (23743, 40, 16, 2, 'o porém respondendo disse a-eles Tarde tendo-acontecido dizeis Bom-tempo avermelha pois o céu');
INSERT INTO verses VALUES (23744, 40, 16, 3, 'e de-manhã Hoje tempestade avermelha pois ficando-sombrio o céu o por-um-lado rosto o do-céu sabeis distinguir o porém sinais o tempos não podeis');
INSERT INTO verses VALUES (23745, 40, 16, 4, 'geração má e adúltera sinal busca e sinal não será-dado a-ela se não o sinal Jonas e deixando eles partiu');
INSERT INTO verses VALUES (23746, 40, 16, 5, 'e vindo o discípulos para o além esqueceram-se pães receber');
INSERT INTO verses VALUES (23747, 40, 16, 6, 'o porém Iesous disse a-eles Vede e guardai-vos de o fermento o fariseus e saduceus');
INSERT INTO verses VALUES (23748, 40, 16, 7, 'o porém debatiam em si-mesmos dizendo que Pães não recebemos');
INSERT INTO verses VALUES (23749, 40, 16, 8, 'sabendo porém o Iesous disse quê raciocinais em si-mesmos pouca-fé que pães não tendes');
INSERT INTO verses VALUES (23750, 40, 16, 9, 'ainda-não entendeis nem lembrai-vos o cinco pães o cinco-mil e quantos cestos recebestes');
INSERT INTO verses VALUES (23751, 40, 16, 10, 'nem o sete pães o quatro-mil e quantas cestos recebestes');
INSERT INTO verses VALUES (23752, 40, 16, 11, 'como não entendeis que não acerca-de pães disseram a-vós guardai-vos porém de o fermento o fariseus e saduceus');
INSERT INTO verses VALUES (23753, 40, 16, 12, 'então compreenderam que não disse atentar de o fermento o pães mas de o ensino o fariseus e saduceus');
INSERT INTO verses VALUES (23754, 40, 16, 13, 'tendo-vindo porém o Iesous para o partes Cesareia o Filipe perguntava o discípulos dele dizendo Quem dizem o homens ser o Filho o do-homem');
INSERT INTO verses VALUES (23755, 40, 16, 14, 'o porém disseram o por-um-lado João o Batista outros porém Elias outros porém Jeremias ou um o profetas');
INSERT INTO verses VALUES (23756, 40, 16, 15, 'diz a-eles vós porém quem me dizeis ser');
INSERT INTO verses VALUES (23757, 40, 16, 16, 'respondendo porém Simão Pedro disse tu és o Christos o Filho o de-Theos o vivente');
INSERT INTO verses VALUES (23758, 40, 16, 17, 'respondendo porém o Iesous disse a ele Bem-aventurado és Simão Bar-Jonas que carne e sangue não revelou a-ti mas o Pai meu o em o nos-céus');
INSERT INTO verses VALUES (23759, 40, 16, 18, 'e-eu e/mas a-ti digo que tu és Pedro e sobre nesta o rocha edificarei meu o igreja e portas Hades não prevalecerão dela');
INSERT INTO verses VALUES (23760, 40, 16, 19, 'darei a-ti o chaves o do-reino o dos-céus e o qual se amarres sobre o da-terra será amarrado em o nos-céus e o qual se desates sobre o da-terra será tendo-sido-desatado em o nos-céus');
INSERT INTO verses VALUES (23761, 40, 16, 20, 'então repreendeu o discípulos para que a-ninguém digam que ele é o Christos');
INSERT INTO verses VALUES (23762, 40, 16, 21, 'de então começou Iesous Christos mostrar o discípulos dele que é necessário ele para Jerusalém ir-embora e muitas-coisas sofrer de o dos-anciãos e sumos-sacerdotes e dos-escribas e ser-morto e o no-terceiro dia ser-levantado');
INSERT INTO verses VALUES (23763, 40, 16, 22, 'e tendo-tomado-consigo ele o Pedro começou repreender a ele dizendo Propício a-ti Kyrie não não será a-ti isto');
INSERT INTO verses VALUES (23764, 40, 16, 23, 'o porém voltando-se disse o a-Pedro Vai atrás meu Satanás tropeço és mim que não pensas o o de-Theos mas o o dos-homens');
INSERT INTO verses VALUES (23765, 40, 16, 24, 'Então o Iesous disse o discípulos dele se alguém quer atrás meu vir negue-a-si-mesmo si-mesmo e levante o cruz dele e siga a-mim');
INSERT INTO verses VALUES (23766, 40, 16, 25, 'o qual pois se queira o alma dele salvar destruirá ela o qual e/mas partícula-condicional destrua o alma dele por-causa-de mim encontrará ela');
INSERT INTO verses VALUES (23767, 40, 16, 26, 'quê pois Será-aproveitado homem se o mundo todo ganhe o porém alma dele sofra-perda ou quê dará homem resgate o alma dele');
INSERT INTO verses VALUES (23768, 40, 16, 27, 'está-a-ponto-de pois o Filho o do-homem vir em o glória o do-Pai dele com o anjo dele e então retribuirá a-cada-um segundo o ação dele');
INSERT INTO verses VALUES (23769, 40, 16, 28, 'amém digo a-vós que são alguns o aqui Estando-de-pé os-quais não não provem da-morte até partícula-condicional vejam o Filho o do-homem o-que-vem em o no-reino dele');
INSERT INTO chapters VALUES (946, 40, 17, 26);
INSERT INTO verses VALUES (23770, 40, 17, 1, 'e com do-dia seis toma-consigo o Iesous o Pedro e Tiago e João o irmão dele e oferece eles para monte alto segundo própria');
INSERT INTO verses VALUES (23771, 40, 17, 2, 'e foi-transfigurado diante-de deles e resplandeceu o rosto dele como o sol o porém vestes dele aconteceu brancas como o luz');
INSERT INTO verses VALUES (23772, 40, 17, 3, 'e eis apareceu a-eles Moisés e Elias falando-junto com dele');
INSERT INTO verses VALUES (23773, 40, 17, 4, 'respondendo porém o Pedro disse o Iesous Kyrie bom é nos aqui ser se queres farei aqui três tendas a-ti uma e Moisés uma e Elias uma');
INSERT INTO verses VALUES (23774, 40, 17, 5, 'ainda dele falando eis nuvem luminosa fez-sombra-sobre eles e eis voz de o nuvem dizendo Este é o filho meu o amado em o qual agradei-me ouvi dele');
INSERT INTO verses VALUES (23775, 40, 17, 6, 'e ouvindo o discípulos caíram sobre rosto deles e temeram extremamente');
INSERT INTO verses VALUES (23776, 40, 17, 7, 'e aproximou-se o Iesous e tendo-tocado deles disse Levantai-vos e não temei');
INSERT INTO verses VALUES (23777, 40, 17, 8, 'tendo-levantado porém o olhos deles a-ninguém vi se não ele Iesous somente');
INSERT INTO verses VALUES (23778, 40, 17, 9, 'e descendo deles de o do-monte ordenou a-eles o Iesous dizendo A-ninguém digais o visão até o qual o Filho o do-homem de mortos seja-levantado');
INSERT INTO verses VALUES (23779, 40, 17, 10, 'e perguntaram ele o discípulos dizendo quê portanto o escribas dizem que Elias é necessário vir primeiro');
INSERT INTO verses VALUES (23780, 40, 17, 11, 'o porém respondendo disse Elias por-um-lado vem e restaurará todas-as-coisas');
INSERT INTO verses VALUES (23781, 40, 17, 12, 'digo porém a-vós que Elias já veio e não reconheceram ele mas fizeram em a ele quanto quiseram assim e o Filho o do-homem está-para sofrer sob deles');
INSERT INTO verses VALUES (23782, 40, 17, 13, 'então compreenderam o discípulos que acerca-de João o Batista disse a-eles');
INSERT INTO verses VALUES (23783, 40, 17, 14, 'e tendo-vindo junto-a o multidão aproximou-se a ele homem ajoelhando ele');
INSERT INTO verses VALUES (23784, 40, 17, 15, 'e dizendo Kyrie tem-misericórdia meu o filho que é-lunático e mal tem muitas-vezes pois cai para o fogo e muitas-vezes para o água');
INSERT INTO verses VALUES (23785, 40, 17, 16, 'e ofereci ele o discípulos teu e não puderam ele curar');
INSERT INTO verses VALUES (23786, 40, 17, 17, 'respondendo porém o Iesous disse Ômega geração incrédulo e tendo-sido-pervertida até quando com vosso serei até quando suportarei vosso trazei a-mim ele aqui');
INSERT INTO verses VALUES (23787, 40, 17, 18, 'e repreendeu a ele o Iesous e saiu de dele o demônio e foi-curada o servo de o hora daquela');
INSERT INTO verses VALUES (23788, 40, 17, 19, 'Então aproximando-se o discípulos o Iesous segundo própria disseram através-de quê nós não pudemos expulsar isso');
INSERT INTO verses VALUES (23789, 40, 17, 20, 'o porém diz a-eles através-de o pouca-fé vosso amém pois digo a-vós se tenhais fé como grão mostarda direis o no-monte neste Passa-daqui daqui ali e passará e nada será-impossível a-vós');
INSERT INTO verses VALUES (23790, 40, 17, 22, 'Reunindo-se porém deles em o Galileia disse a-eles o Iesous está-para o Filho o do-homem ser-entregue para mãos dos-homens');
INSERT INTO verses VALUES (23791, 40, 17, 23, 'e matarão ele e o no-terceiro dia será-levantado e entristeceram-se extremamente');
INSERT INTO verses VALUES (23792, 40, 17, 24, 'Tendo-vindo porém deles para Cafarnaum aproximaram-se o o duas-dracmas recebendo o a-Pedro e disseram o mestre vosso não completa duas-dracmas');
INSERT INTO verses VALUES (23793, 40, 17, 25, 'diz Sim e tendo-vindo para o casa precedeu ele o Iesous dizendo quê a-ti parece Simão o reis o da-terra de de-quais recebem fins ou tributo de o dos-filhos deles ou de o estranhos');
INSERT INTO verses VALUES (23794, 40, 17, 26, 'tendo-dito e/mas de o estranhos disse a ele o Iesous Porventura livres são o filhos');
INSERT INTO verses VALUES (23795, 40, 17, 27, 'para que porém não escandalizemos eles tendo-ido para mar lança anzol e o tendo-subido primeiro peixe levanta e abrindo o boca dele encontrarás estáter aquele tomando dá a-eles em-troca-de mim e teu');
INSERT INTO chapters VALUES (947, 40, 18, 34);
INSERT INTO verses VALUES (23796, 40, 18, 1, 'em naquela o hora aproximaram-se o discípulos o Iesous dizendo Quem então maior é em o no-reino o dos-céus');
INSERT INTO verses VALUES (23797, 40, 18, 2, 'e tendo-chamado criança estabeleceu ele em no-meio deles');
INSERT INTO verses VALUES (23798, 40, 18, 3, 'e disse Amém digo a-vós se não vireis-vos e torneis-vos como o crianças não não entreis para o reino o dos-céus');
INSERT INTO verses VALUES (23799, 40, 18, 4, 'qualquer-que portanto humilhará si-mesmo como o criança isto este é o maior em o no-reino o dos-céus');
INSERT INTO verses VALUES (23800, 40, 18, 5, 'e o qual se receba um criança tal sobre o no-nome meu mim recebe');
INSERT INTO verses VALUES (23801, 40, 18, 6, 'o qual e/mas partícula-condicional escandalize um o pequenos destes o crentes para a-mim convém a ele para que seja-pendurado pedra-de-moinho de-moinho acerca-de o pescoço dele e seja-afundado em o profundeza-do-mar o do-mar');
INSERT INTO verses VALUES (23802, 40, 18, 7, 'Ai o ao-mundo de o escândalos necessidade pois vir o escândalos porém ai o ao-homem através-de o qual o tropeço vem');
INSERT INTO verses VALUES (23803, 40, 18, 8, 'se porém o mão teu ou o pé teu escandaliza te corta ele e lança de teu bom a-ti é entrar para o vida aleijado ou manco ou dois mãos ou dois pés tendo ser-lançado para o fogo o eterno');
INSERT INTO verses VALUES (23804, 40, 18, 9, 'e se o olho teu escandaliza te arranca ele e lança de teu bom a-ti é com-um-só-olho para o vida entrar ou dois olhos tendo ser-lançado para o Geena o fogo');
INSERT INTO verses VALUES (23805, 40, 18, 10, 'Vede não desprezeis de-um o pequenos destes digo pois a-vós que o anjo deles em nos-céus através-de de-todo veem o rosto o do-Pai meu o em nos-céus');
INSERT INTO verses VALUES (23806, 40, 18, 12, 'quê a-vós parece se aconteça a-alguém ao-homem cem ovelhas e seja-desviado um de deles não deixará o noventa nove sobre o montes e tendo-ido busca o sendo-enganado');
INSERT INTO verses VALUES (23807, 40, 18, 13, 'e se aconteça encontrar isso amém digo a-vós que alegra-se sobre a ele mais ou sobre o noventa nove o não tendo-sido-enganados');
INSERT INTO verses VALUES (23808, 40, 18, 14, 'assim não é vontade diante-de o do-Pai vosso o em nos-céus para que pereça um o pequenos destes');
INSERT INTO verses VALUES (23809, 40, 18, 15, 'se porém peque o irmão teu vai repreende ele entre teu e dele somente se teu ouça lucraste o irmão teu');
INSERT INTO verses VALUES (23810, 40, 18, 16, 'se porém não ouça recebe com teu ainda um ou dois para que sobre da-boca dois testemunhas ou três seja-posto-de-pé todo palavra');
INSERT INTO verses VALUES (23811, 40, 18, 17, 'se porém recuse-ouvir deles dize o na-igreja se porém e o da-assembleia recuse-ouvir seja a-ti assim-como o gentio e o cobrador-de-impostos');
INSERT INTO verses VALUES (23812, 40, 18, 18, 'Amém digo a-vós quanto se amarreis sobre o da-terra será tendo-sido-amarradas em no-céu e quanto se desateis sobre o da-terra será tendo-sido-desatados em no-céu');
INSERT INTO verses VALUES (23813, 40, 18, 19, 'novamente amém digo a-vós que se dois concordem de vosso sobre o da-terra acerca-de de-todo assunto o qual se peçam acontecerá a-eles de-junto-de o do-Pai meu o em nos-céus');
INSERT INTO verses VALUES (23814, 40, 18, 20, 'do-qual pois são dois ou três tendo-sido-reunidos para o meu nome ali sou em no-meio deles');
INSERT INTO verses VALUES (23815, 40, 18, 21, 'Então aproximando-se o Pedro disse a ele Kyrie quantas-vezes pecará para mim o irmão meu e deixarei a ele até sete-vezes');
INSERT INTO verses VALUES (23816, 40, 18, 22, 'diz a ele o Iesous não digo a-ti até sete-vezes mas até Setenta-vezes sete');
INSERT INTO verses VALUES (23817, 40, 18, 23, 'através-de isto Foi-comparado o reino o dos-céus ao-homem rei o qual quis ajustar-contas palavra com o servos dele');
INSERT INTO verses VALUES (23818, 40, 18, 24, 'tendo-começado porém dele ajustar-contas foi-trazido um a ele devedor dez-mil de-talentos');
INSERT INTO verses VALUES (23819, 40, 18, 25, 'não tendo porém dele retribuir ordenou ele o kyrios ser-vendido e o mulher e o filhos e todas-as-coisas quanto tem e ser-devolvido');
INSERT INTO verses VALUES (23820, 40, 18, 26, 'caindo portanto o servo adorava a ele dizendo Tem-paciência sobre a-mim e todas-as-coisas retribuirei a-ti');
INSERT INTO verses VALUES (23821, 40, 18, 27, 'compadecido porém o kyrios o servo daquele soltou ele e o empréstimo deixou a ele');
INSERT INTO verses VALUES (23822, 40, 18, 28, 'saindo porém o servo aquele encontrou um o co-servos dele o qual devia a ele cem denários e segurando ele Sufocava dizendo Devolve se algo deves');
INSERT INTO verses VALUES (23823, 40, 18, 29, 'caindo portanto o co-servo dele suplicava ele dizendo Tem-paciência sobre a-mim e retribuirei a-ti');
INSERT INTO verses VALUES (23824, 40, 18, 30, 'o porém não queria mas partindo lançou ele para prisão até retribua o sendo-devido');
INSERT INTO verses VALUES (23825, 40, 18, 31, 'vendo portanto o conservos dele o tendo-acontecido entristeceram-se extremamente e vindo explicaram o ao-Kyrios deles-mesmos todas-as-coisas o tendo-acontecido');
INSERT INTO verses VALUES (23826, 40, 18, 32, 'então tendo-chamado ele o kyrios dele diz a ele Servo mau toda o dívida aquela deixei a-ti porque consolaste me');
INSERT INTO verses VALUES (23827, 40, 18, 33, 'não é necessário e te ter-misericórdia o co-servo teu como e-eu te tive-misericórdia');
INSERT INTO verses VALUES (23828, 40, 18, 34, 'e tendo-se-irado o kyrios dele entregou ele o torturadores até o qual retribua todo o sendo-devido a ele');
INSERT INTO verses VALUES (23829, 40, 18, 35, 'assim e o Pai meu o celestial fará a-vós se não perdoeis cada-um o ao-irmão dele de o corações vosso');
INSERT INTO chapters VALUES (948, 40, 19, 30);
INSERT INTO verses VALUES (23830, 40, 19, 1, 'e aconteceu quando terminou o Iesous o palavras estes partiu de o Galileia e veio para o limites o Judeia além o Jordão');
INSERT INTO verses VALUES (23831, 40, 19, 2, 'e seguiram a ele multidões muitos e curou eles ali');
INSERT INTO verses VALUES (23832, 40, 19, 3, 'e aproximaram-se a ele fariseus tentando ele e dizendo se é-lícito soltar o mulher dele segundo toda causa');
INSERT INTO verses VALUES (23833, 40, 19, 4, 'o porém respondendo disse não lestes que o tendo-criado de princípio macho e fêmea fez eles');
INSERT INTO verses VALUES (23834, 40, 19, 5, 'e disse Por-causa-de deste deixará homem o Pai e o mãe e será-unido o mulher dele e serão o dois para carne uma');
INSERT INTO verses VALUES (23835, 40, 19, 6, 'de-modo-que não-mais são dois mas carne uma o qual portanto o Theos juntou homem não separe');
INSERT INTO verses VALUES (23836, 40, 19, 7, 'dizem a ele quê portanto Moisés ordenou dar livro divórcio e soltar');
INSERT INTO verses VALUES (23837, 40, 19, 8, 'diz a-eles que Moisés junto-a o dureza-de-coração vosso permitiu a-vós soltar o mulheres vosso de princípio porém não aconteceu assim');
INSERT INTO verses VALUES (23838, 40, 19, 9, 'digo porém a-vós que o qual partícula-condicional solte o mulher dele não sobre imoralidade e case outra adultera');
INSERT INTO verses VALUES (23839, 40, 19, 10, 'dizem a ele o discípulos se assim é o causa o do-homem com o mulher não convém casar');
INSERT INTO verses VALUES (23840, 40, 19, 11, 'o porém disse a-eles não todos cabem o palavra este mas o qual foi-dado');
INSERT INTO verses VALUES (23841, 40, 19, 12, 'são pois eunucos os-quais de ventre mãe foram-gerados assim e são eunucos os-quais foram-feitos-eunucos sob o dos-homens e são eunucos os-quais fizeram-eunucos si-mesmos através-de o reino o dos-céus o podendo ter-espaço dê-lugar');
INSERT INTO verses VALUES (23842, 40, 19, 13, 'Então foram-oferecidos a ele crianças para que o mãos imponha a-eles e ore o porém discípulos repreenderam a-eles');
INSERT INTO verses VALUES (23843, 40, 19, 14, 'o porém Iesous disse Deixai o crianças e não impedis eles vir para me o pois de-tais é o reino o dos-céus');
INSERT INTO verses VALUES (23844, 40, 19, 15, 'e pondo-sobre o mãos a-eles foi dali');
INSERT INTO verses VALUES (23845, 40, 19, 16, 'e eis um aproximando-se a ele disse Mestre quê bom farei para que tenha vida eterno');
INSERT INTO verses VALUES (23846, 40, 19, 17, 'o porém disse a ele quê me perguntas acerca-de o bom um é o bom se porém queres para o vida entrar guarda o mandamentos');
INSERT INTO verses VALUES (23847, 40, 19, 18, 'diz a ele Qual o porém Iesous disse o não assassinarás não adulterarás não furtarás não testemunharás-falsamente');
INSERT INTO verses VALUES (23848, 40, 19, 19, 'Honra o Pai e o mãe e Amarás o próximo teu como a-ti-mesmo');
INSERT INTO verses VALUES (23849, 40, 19, 20, 'diz a ele o jovem estas-coisas todas-as-coisas guardei quê ainda Falto');
INSERT INTO verses VALUES (23850, 40, 19, 21, 'disse a ele o Iesous se queres perfeito ser vai vende teu o posses e dá pobres e terás tesouro em nos-céus e vem segue a-mim');
INSERT INTO verses VALUES (23851, 40, 19, 22, 'ouvindo porém o jovem o palavra partiu entristecendo-se era pois tendo propriedades muitas-coisas');
INSERT INTO verses VALUES (23852, 40, 19, 23, 'o porém Iesous disse o discípulos dele Amém digo a-vós que rico dificilmente entrará para o reino o dos-céus');
INSERT INTO verses VALUES (23853, 40, 19, 24, 'novamente porém digo a-vós mais-fácil é camelo através-de orifício agulha entrar ou rico para o reino o de-Theos');
INSERT INTO verses VALUES (23854, 40, 19, 25, 'ouvindo porém o discípulos ficavam-espantados extremamente dizendo Quem então pode ser-salvo');
INSERT INTO verses VALUES (23855, 40, 19, 26, 'olhando-fixamente porém o Iesous disse a-eles de-junto-de aos-homens isto impossível é de-junto-de porém a-Theos todas-as-coisas poderosas');
INSERT INTO verses VALUES (23856, 40, 19, 27, 'Então respondendo o Pedro disse a ele Eis nós deixamos todas-as-coisas e seguimos a-ti quê então será a-nós');
INSERT INTO verses VALUES (23857, 40, 19, 28, 'o porém Iesous disse a-eles Amém digo a-vós que vós o tendo-seguido a-mim em o em-regeneração quando sente-se o Filho o do-homem sobre trono da-glória dele sentareis e eles-mesmos sobre doze tronos julgando o doze tribos o Israel');
INSERT INTO verses VALUES (23858, 40, 19, 29, 'e todo qualquer-que deixou da-casa ou irmãos ou irmãs ou Pai ou mãe ou filhos ou campos por-causa-de o mim nome muitas-vezes-mais receberá e vida eterno herdará');
INSERT INTO verses VALUES (23859, 40, 19, 30, 'muitos porém serão primeiro últimos e últimos primeiro');
INSERT INTO chapters VALUES (949, 40, 20, 34);
INSERT INTO verses VALUES (23860, 40, 20, 1, 'semelhante pois é o reino o dos-céus ao-homem senhor-da-casa qualquer-que saiu juntamente de-manhã contratar trabalhadores para o vinha dele');
INSERT INTO verses VALUES (23861, 40, 20, 2, 'tendo-concordado porém com o trabalhadores de denário o dia enviou eles para o vinha dele');
INSERT INTO verses VALUES (23862, 40, 20, 3, 'e saindo acerca-de terceira hora viu outros de-pé em o praça ociosos');
INSERT INTO verses VALUES (23863, 40, 20, 4, 'e àqueles disse ide e vós para o vinha e o qual se seja justo darei a-vós');
INSERT INTO verses VALUES (23864, 40, 20, 5, 'o porém foram novamente porém saindo acerca-de sexta e nona hora fez da-mesma-forma');
INSERT INTO verses VALUES (23865, 40, 20, 6, 'acerca-de porém o décima-primeira saindo encontrou outros de-pé e diz a-eles quê aqui estais-de-pé toda o dia ociosos');
INSERT INTO verses VALUES (23866, 40, 20, 7, 'dizem a ele que ninguém nos alugou diz a-eles ide e vós para o vinha');
INSERT INTO verses VALUES (23867, 40, 20, 8, 'tarde porém tendo-acontecido diz o kyrios o vinha o Procurador dele Chama o trabalhadores e devolve o salário começando de o últimas até o primeiro');
INSERT INTO verses VALUES (23868, 40, 20, 9, 'vindo porém o acerca-de o décima-primeira hora receberam cada denário');
INSERT INTO verses VALUES (23869, 40, 20, 10, 'e vindo o primeiro supuseram que mais receberão e receberam o cada denário e eles');
INSERT INTO verses VALUES (23870, 40, 20, 11, 'tendo-tomado porém murmuravam segundo o dono-de-casa');
INSERT INTO verses VALUES (23871, 40, 20, 12, 'dizendo estas o últimos uma hora fizeram e Iguais eles a-nós fizeste o tendo-carregado o peso o do-dia e o calor-ardente');
INSERT INTO verses VALUES (23872, 40, 20, 13, 'o porém respondendo um deles disse companheiro não pratico-injustiça te não denário combinaste a-mim');
INSERT INTO verses VALUES (23873, 40, 20, 14, 'levanta o teu e vai quero porém neste o último dar como e a-ti');
INSERT INTO verses VALUES (23874, 40, 20, 15, 'não é-lícito a-mim o qual quero fazer em o meus ou o olho teu mau é que eu bom sou');
INSERT INTO verses VALUES (23875, 40, 20, 16, 'Assim serão o últimos primeiro e o primeiro últimos');
INSERT INTO verses VALUES (23876, 40, 20, 17, 'Estando-a-ponto-de porém subir Iesous para Jerusalém recebeu o doze segundo própria e em o caminho disse a-eles');
INSERT INTO verses VALUES (23877, 40, 20, 18, 'Eis subimos para Jerusalém e o Filho o do-homem será-entregue o sumos-sacerdotes e escribas e condenarão ele para morte');
INSERT INTO verses VALUES (23878, 40, 20, 19, 'e entregarão ele o nações para o escarnecer e açoitar e crucificar e o no-terceiro dia será-levantado');
INSERT INTO verses VALUES (23879, 40, 20, 20, 'Então aproximou-se a ele o mãe o dos-filhos Zebedeu com o dos-filhos dela prostrando-se e pedindo algo de dele');
INSERT INTO verses VALUES (23880, 40, 20, 21, 'o porém disse a-ela quê queres diz a ele Dize para que sentem-se estes o dois filhos meu um de direita e um de esquerda teu em o no-reino teu');
INSERT INTO verses VALUES (23881, 40, 20, 22, 'respondendo porém o Iesous disse não sei quê pedis podeis beber o cálice o qual eu estou-para beber dizem a ele Podemos');
INSERT INTO verses VALUES (23882, 40, 20, 23, 'diz a-eles o por-um-lado cálice meu bebereis o porém sentar de direita meu e de esquerda não é meu isto dar mas o qual tem-sido-preparado sob o do-Pai meu');
INSERT INTO verses VALUES (23883, 40, 20, 24, 'e ouvindo o dez indignaram-se acerca-de o dois dos-irmãos');
INSERT INTO verses VALUES (23884, 40, 20, 25, 'o porém Iesous tendo-chamado eles disse sei que o governantes o nações dominam deles e o grandes exercem-autoridade-sobre deles');
INSERT INTO verses VALUES (23885, 40, 20, 26, 'não assim é em a-vós mas o qual se queira em a-vós grande tornar-se será vosso servo');
INSERT INTO verses VALUES (23886, 40, 20, 27, 'e o qual partícula-condicional queira em a-vós ser primeiro será vosso servo');
INSERT INTO verses VALUES (23887, 40, 20, 28, 'assim-como o Filho o do-homem não veio ser-servido mas servir e dar o alma dele resgate em-troca-de muitos');
INSERT INTO verses VALUES (23888, 40, 20, 29, 'e saindo deles de Jericó seguiu a ele multidão muito');
INSERT INTO verses VALUES (23889, 40, 20, 30, 'e eis dois cegos sentados de-junto-de o caminho ouvindo que Iesous passa clamaram dizendo Kyrie tem-misericórdia nos Filho Davi');
INSERT INTO verses VALUES (23890, 40, 20, 31, 'o porém multidão repreendeu a-eles para que calem-se o porém maior clamaram dizendo Kyrie tem-misericórdia nos Filho Davi');
INSERT INTO verses VALUES (23891, 40, 20, 32, 'e tendo-ficado-de-pé o Iesous clamou eles e disse quê quereis farei a-vós');
INSERT INTO verses VALUES (23892, 40, 20, 33, 'dizem a ele Kyrie para que abram o olhos nosso');
INSERT INTO verses VALUES (23893, 40, 20, 34, 'compadecido porém o Iesous tocou o olhos deles e imediatamente recuperaram-a-visão e seguiram a ele');
INSERT INTO chapters VALUES (950, 40, 21, 46);
INSERT INTO verses VALUES (23894, 40, 21, 1, 'e quando aproximaram-se para Jerusalém e vieram para Betfagé para o monte o Oliveiras então Iesous enviou dois discípulos');
INSERT INTO verses VALUES (23895, 40, 21, 2, 'dizendo a-eles Ide para o aldeia o defronte-de vosso e imediatamente encontrareis jumento tendo-sido-amarrada e jumentinho com dela tendo-desatado conduzi a-mim');
INSERT INTO verses VALUES (23896, 40, 21, 3, 'e se alguém a-vós diga algo direis que o Kyrios deles necessidade tem imediatamente porém enviará eles');
INSERT INTO verses VALUES (23897, 40, 21, 4, 'isto porém aconteceu para que seja-cumprido o o-dito através-de o profeta dizendo');
INSERT INTO verses VALUES (23898, 40, 21, 5, 'Dizei o filha Sião Eis o rei teu vem a-ti manso e tendo-montado sobre jumento e sobre jumentinho Filho Animal-de-carga');
INSERT INTO verses VALUES (23899, 40, 21, 6, 'tendo-ido porém o discípulos e tendo-feito assim-como ordenou a-eles o Iesous');
INSERT INTO verses VALUES (23900, 40, 21, 7, 'levaram o jumento e o jumentinho e puseram-sobre sobre deles o vestes e sentou-se-sobre em-cima deles');
INSERT INTO verses VALUES (23901, 40, 21, 8, 'o porém muito-grande multidão estenderam deles-mesmos o vestes em o caminho outros porém Cortavam ramos de o árvores e Estendiam em o caminho');
INSERT INTO verses VALUES (23902, 40, 21, 9, 'o porém multidões o precedendo ele e o seguindo clamavam dizendo Hosana o filho Davi Bendito o o-que-vem em em-nome do-Kyrios Hosana em o alturas');
INSERT INTO verses VALUES (23903, 40, 21, 10, 'e tendo-entrado dele para Jerusalém foi-sacudida toda o cidade dizendo Quem é este');
INSERT INTO verses VALUES (23904, 40, 21, 11, 'o porém multidões diziam Este é o profeta Iesous o de Nazaré o Galileia');
INSERT INTO verses VALUES (23905, 40, 21, 12, 'e entrou Iesous para o templo e expulsou todos o vendendo e comprando em o templo e o mesas o cambistas derrubou e o cadeiras o vendendo o pombas');
INSERT INTO verses VALUES (23906, 40, 21, 13, 'e diz a-eles Tem-sido-escrito o casa meu casa oração será-chamado vós porém ele fazei caverna ladrões');
INSERT INTO verses VALUES (23907, 40, 21, 14, 'e aproximaram-se a ele cegos e coxos em o templo e curou eles');
INSERT INTO verses VALUES (23908, 40, 21, 15, 'vendo porém o sumos-sacerdotes e o escribas o maravilhas o qual fez e o crianças o clamando em o templo e dizendo Hosana o filho Davi indignaram-se');
INSERT INTO verses VALUES (23909, 40, 21, 16, 'e disseram a ele Ouves quê estes dizem o porém Iesous diz a-eles Sim nunca lestes que de da-boca criancinhas e amamentando preparaste louvor');
INSERT INTO verses VALUES (23910, 40, 21, 17, 'e deixando eles saiu fora o cidade para Betânia e hospedou-se ali');
INSERT INTO verses VALUES (23911, 40, 21, 18, 'De-manhã porém tendo-conduzido-para-o-alto para o cidade teve-fome');
INSERT INTO verses VALUES (23912, 40, 21, 19, 'e vendo figueira uma sobre o do-caminho veio sobre ela e nada encontrou em a-ela se não folhas somente e diz a-ela não não-mais de teu fruto aconteça para o eternidade e secou imediatamente o figueira');
INSERT INTO verses VALUES (23913, 40, 21, 20, 'e vendo o discípulos admiraram-se dizendo como imediatamente secou o figueira');
INSERT INTO verses VALUES (23914, 40, 21, 21, 'respondendo porém o Iesous disse a-eles Amém digo a-vós se tenhais fé e não sejais-divididos não somente o o figueira fareis mas e-se o no-monte neste digais Sê-levantado e sê-lançado para o mar acontecerá');
INSERT INTO verses VALUES (23915, 40, 21, 22, 'e todas-as-coisas quanto partícula-condicional peçais em o oração crendo recebereis');
INSERT INTO verses VALUES (23916, 40, 21, 23, 'e tendo-vindo dele para o templo aproximaram-se a ele ensinando o sumos-sacerdotes e o anciãos o povo dizendo em qual em-autoridade estas-coisas fazes e quem a-ti deu o autoridade esta');
INSERT INTO verses VALUES (23917, 40, 21, 24, 'respondendo porém o Iesous disse a-eles Perguntarei vos e-eu palavra um o qual se disserdes a-mim e-eu a-vós direi em qual em-autoridade estas-coisas faço');
INSERT INTO verses VALUES (23918, 40, 21, 25, 'o batismo o João de-onde era de do-céu ou de dos-homens o porém debatiam em si-mesmos dizendo se digamos de do-céu dirá a-nós através-de quê portanto não crestes a ele');
INSERT INTO verses VALUES (23919, 40, 21, 26, 'se porém digamos de dos-homens tememos o multidão todos pois como profeta têm o João');
INSERT INTO verses VALUES (23920, 40, 21, 27, 'e respondendo o Iesous disseram não sei disse a-eles e ele nem eu digo a-vós em qual em-autoridade estas-coisas faço');
INSERT INTO verses VALUES (23921, 40, 21, 28, 'quê porém a-vós parece homem tinha filhos dois aproximando-se o primeiro disse filho vai hoje Trabalha em o vinha');
INSERT INTO verses VALUES (23922, 40, 21, 29, 'o porém respondendo disse eu kyrie e não partiu');
INSERT INTO verses VALUES (23923, 40, 21, 30, 'aproximando-se porém o segundo disse da-mesma-forma o porém respondendo disse não quero depois tendo-se-arrependido partiu');
INSERT INTO verses VALUES (23924, 40, 21, 31, 'quem de o dois fez o vontade o pai dizem o Último diz a-eles o Iesous Amém digo a-vós que o cobradores-de-impostos e o prostitutas vão-adiante vos para o reino o de-Theos');
INSERT INTO verses VALUES (23925, 40, 21, 32, 'veio pois João junto-a vos em caminho da-justiça e não crestes a ele o porém cobradores-de-impostos e o prostitutas creram a ele vós porém vendo nem arrependestes-vos depois o crer a ele');
INSERT INTO verses VALUES (23926, 40, 21, 33, 'outra parábola ouvi homem era dono-de-casa qualquer-que plantou vinha e cerca a ele colocou-ao-redor e cavou em a ele lagar e edificou torre e arrendou ele lavradores e viajou');
INSERT INTO verses VALUES (23927, 40, 21, 34, 'quando porém aproximou-se o tempo o frutos enviou o servos dele junto-a o lavradores receber o frutos dele');
INSERT INTO verses VALUES (23928, 40, 21, 35, 'e tendo-tomado o lavradores o servos dele o qual por-um-lado espancaram o qual porém mataram o qual porém apedrejaram');
INSERT INTO verses VALUES (23929, 40, 21, 36, 'novamente enviou outros servos mais o primeiro e fizeram a-eles da-mesma-forma');
INSERT INTO verses VALUES (23930, 40, 21, 37, 'depois porém enviou junto-a eles o Filho dele dizendo Envergonhar-se-ão o filho meu');
INSERT INTO verses VALUES (23931, 40, 21, 38, 'o porém lavradores vendo o Filho disseram em si-mesmos Este é o herdeiro vinde matemos ele e tenhamos o herança dele');
INSERT INTO verses VALUES (23932, 40, 21, 39, 'e tendo-tomado ele expulsaram fora o vinha e mataram');
INSERT INTO verses VALUES (23933, 40, 21, 40, 'quando portanto venha o kyrios o vinha quê fará o lavradores àqueles');
INSERT INTO verses VALUES (23934, 40, 21, 41, 'dizem a ele Maus mal destruirá eles e o vinha arrendará a-outros lavradores os-quais retribuirão a ele o frutos em o tempos deles');
INSERT INTO verses VALUES (23935, 40, 21, 42, 'diz a-eles o Iesous Nunca lestes em o escrituras pedra o qual rejeitaram o edificantes este aconteceu para cabeça cantos de-junto-de do-Kyrios aconteceu esta e é admirável em olhos nosso');
INSERT INTO verses VALUES (23936, 40, 21, 43, 'através-de isto digo a-vós que será-tirado de vosso o reino o de-Theos e será-dado nação fazendo o frutos dela');
INSERT INTO verses VALUES (23937, 40, 21, 44, 'e o caindo sobre o pedra este será-esmagado sobre o qual e/mas partícula-condicional caia esmagará ele');
INSERT INTO verses VALUES (23938, 40, 21, 45, 'e ouvindo o sumos-sacerdotes e o fariseus o parábolas dele conheceram que acerca-de deles diz');
INSERT INTO verses VALUES (23939, 40, 21, 46, 'e buscando ele agarrar temeram o multidões porque para profeta ele tinham');
INSERT INTO chapters VALUES (951, 40, 22, 46);
INSERT INTO verses VALUES (23940, 40, 22, 1, 'e respondendo o Iesous novamente disse em em-parábolas a-eles dizendo');
INSERT INTO verses VALUES (23941, 40, 22, 2, 'Foi-comparado o reino o dos-céus ao-homem rei qualquer-que fez bodas o filho dele');
INSERT INTO verses VALUES (23942, 40, 22, 3, 'e enviou o servos dele chamar o tendo-sido-chamados para o bodas e não queriam vir');
INSERT INTO verses VALUES (23943, 40, 22, 4, 'novamente enviou outros servos dizendo Dizei o tendo-sido-chamados Eis o almoço meu Tenho-preparado o touros meu e o engordados tendo-sido-sacrificadas e todas-as-coisas preparadas vinde para o bodas');
INSERT INTO verses VALUES (23944, 40, 22, 5, 'o porém tendo-negligenciado foram o qual por-um-lado para o próprio campo o qual porém sobre o comércio dele');
INSERT INTO verses VALUES (23945, 40, 22, 6, 'o porém restantes tendo-agarrado o servos dele Ultrajaram e mataram');
INSERT INTO verses VALUES (23946, 40, 22, 7, 'o porém rei irou-se e tendo-enviado o exércitos dele perdeu o assassinos aqueles e o cidade deles incendiou');
INSERT INTO verses VALUES (23947, 40, 22, 8, 'então diz o servos dele o por-um-lado bodas preparado é o porém chamados não eram dignos');
INSERT INTO verses VALUES (23948, 40, 22, 9, 'ide portanto sobre o saídas o caminhos e quanto se encontreis chamai para o bodas');
INSERT INTO verses VALUES (23949, 40, 22, 10, 'e saindo o servos aqueles para o caminhos reuniram todos o qual encontraram maus e e bons e encheu-se o câmara-nupcial reclinados');
INSERT INTO verses VALUES (23950, 40, 22, 11, 'entrando porém o rei contemplar o reclinados viu ali homem não vestido veste bodas');
INSERT INTO verses VALUES (23951, 40, 22, 12, 'e diz a ele companheiro como entraste aqui não tendo veste bodas o porém Foi-amordaçado');
INSERT INTO verses VALUES (23952, 40, 22, 13, 'então o rei disse o servos Tendo-amarrado dele pés e mãos lançai-fora ele para o trevas o exterior ali será o choro e o ranger o dentes');
INSERT INTO verses VALUES (23953, 40, 22, 14, 'muitos pois são chamados poucos porém escolhidos');
INSERT INTO verses VALUES (23954, 40, 22, 15, 'Então tendo-ido o fariseus conselho receberam para-que ele enlacem em em-palavra');
INSERT INTO verses VALUES (23955, 40, 22, 16, 'e enviam a ele o discípulos deles com o herodianos dizendo Mestre sei que verdadeiro és e o caminho o de-Theos em verdade ensinas e não importa a-ti acerca-de ninguém não pois vês para rosto dos-homens');
INSERT INTO verses VALUES (23956, 40, 22, 17, 'dize portanto a-nós quê a-ti parece é-lícito dar tributo César ou não');
INSERT INTO verses VALUES (23957, 40, 22, 18, 'sabendo porém o Iesous o maldade deles disse quê me tentais hipócritas');
INSERT INTO verses VALUES (23958, 40, 22, 19, 'mostrai a-mim o moeda o censo o porém trouxeram a ele denário');
INSERT INTO verses VALUES (23959, 40, 22, 20, 'e diz a-eles De-quem o imagem esta e o inscrição');
INSERT INTO verses VALUES (23960, 40, 22, 21, 'dizem de-César então diz a-eles Devolvei portanto o de-César César e o o de-Theos o a-Theos');
INSERT INTO verses VALUES (23961, 40, 22, 22, 'e ouvindo admiraram-se e deixando ele passaram');
INSERT INTO verses VALUES (23962, 40, 22, 23, 'em naquela o dia aproximaram-se a ele Saduceus dizendo não ser ressurreição e perguntaram ele');
INSERT INTO verses VALUES (23963, 40, 22, 24, 'dizendo Mestre Moisés disse se alguém morra não tendo filhos casará-por-levirato o irmão dele o mulher dele e levantará semente o ao-irmão dele');
INSERT INTO verses VALUES (23964, 40, 22, 25, 'eram porém de-junto-de a-nós sete irmãos e o primeiro tendo-casado morreu e não tendo semente deixou o mulher dele o ao-irmão dele');
INSERT INTO verses VALUES (23965, 40, 22, 26, 'semelhantemente e o segundo e o terceiro até o sete');
INSERT INTO verses VALUES (23966, 40, 22, 27, 'depois porém todos morreu o mulher');
INSERT INTO verses VALUES (23967, 40, 22, 28, 'em o ressurreição portanto de-quem o sete será mulher todos pois tiveram ela');
INSERT INTO verses VALUES (23968, 40, 22, 29, 'respondendo porém o Iesous disse a-eles Errais não sei o escrituras nem o poder o de-Theos');
INSERT INTO verses VALUES (23969, 40, 22, 30, 'em pois o ressurreição nem casam nem são-dados-em-casamento mas como anjo em o no-céu são');
INSERT INTO verses VALUES (23970, 40, 22, 31, 'acerca-de porém o da-ressurreição o mortos não lestes o o-dito a-vós sob o de-Theos dizendo');
INSERT INTO verses VALUES (23971, 40, 22, 32, 'Eu sou o Theos Abraão e o Theos Isaque e o Theos Jacó não é o Theos mortos mas viventes');
INSERT INTO verses VALUES (23972, 40, 22, 33, 'e ouvindo o multidões ficavam-espantados sobre o em-ensino dele');
INSERT INTO verses VALUES (23973, 40, 22, 34, 'o porém fariseus ouvindo que Amordaçou o Saduceus foram-reunidos sobre o isso');
INSERT INTO verses VALUES (23974, 40, 22, 35, 'e perguntou um de deles perito-na-lei tentando ele');
INSERT INTO verses VALUES (23975, 40, 22, 36, 'Mestre qual mandamento grande em o lei');
INSERT INTO verses VALUES (23976, 40, 22, 37, 'o porém disse a ele Amarás Kyrion o Theos teu em toda o no-coração teu e em toda o alma teu e em toda o entendimento teu');
INSERT INTO verses VALUES (23977, 40, 22, 38, 'esta é o grande e primeiro mandamento');
INSERT INTO verses VALUES (23978, 40, 22, 39, 'segunda semelhante a-ela Amarás o próximo teu como a-ti-mesmo');
INSERT INTO verses VALUES (23979, 40, 22, 40, 'em estas o dois mandamentos todo o lei pende e o profetas');
INSERT INTO verses VALUES (23980, 40, 22, 41, 'Tendo-sido-reunidos porém o fariseus perguntou eles o Iesous');
INSERT INTO verses VALUES (23981, 40, 22, 42, 'dizendo quê a-vós parece acerca-de o de-Christos de-quem filho é dizem a ele o Davi');
INSERT INTO verses VALUES (23982, 40, 22, 43, 'diz a-eles como portanto Davi em Espírito chama ele Kyrion dizendo');
INSERT INTO verses VALUES (23983, 40, 22, 44, 'disse Kyrios o ao-Kyrios meu Senta-te de direita meu até partícula-condicional ponha o inimigos teu debaixo o pés teu');
INSERT INTO verses VALUES (23984, 40, 22, 45, 'se portanto Davi chama ele Kyrion como Filho dele é');
INSERT INTO verses VALUES (23985, 40, 22, 46, 'e ninguém podia responder a ele palavra nem Ousou alguém de daquela o do-dia perguntar ele não-mais');
INSERT INTO chapters VALUES (952, 40, 23, 38);
INSERT INTO verses VALUES (23986, 40, 23, 1, 'Então o Iesous falou o às-multidões e o discípulos dele');
INSERT INTO verses VALUES (23987, 40, 23, 2, 'dizendo sobre o de-Moisés cadeiras sentaram-se o escribas e o fariseus');
INSERT INTO verses VALUES (23988, 40, 23, 3, 'todas-as-coisas portanto quanto se digam a-vós fazei e guardais segundo porém o obra deles não fazei dizem pois e não fazem');
INSERT INTO verses VALUES (23989, 40, 23, 4, 'amarram porém cargas pesados e Põem-sobre sobre o ombros o dos-homens eles-mesmos porém o dedo deles não querem mover elas');
INSERT INTO verses VALUES (23990, 40, 23, 5, 'todas-as-coisas porém o obra deles fazem junto-a o ser-contemplado o aos-homens alargam pois o filactérios deles e engrandecem o franjas');
INSERT INTO verses VALUES (23991, 40, 23, 6, 'amam porém o primeiro-assento em o banquetes e o primeiros-assentos em o nas-sinagogas');
INSERT INTO verses VALUES (23992, 40, 23, 7, 'e o saudações em o praças e ser-chamado sob o dos-homens Rabi');
INSERT INTO verses VALUES (23993, 40, 23, 8, 'vós porém não sejais-chamados Rabi um pois é vosso o mestre todos porém vós irmãos sois');
INSERT INTO verses VALUES (23994, 40, 23, 9, 'e Pai não chameis vosso sobre o da-terra um pois é vosso o Pai o celestial');
INSERT INTO verses VALUES (23995, 40, 23, 10, 'nem sejais-chamados mestres que mestre vosso é um o Christos');
INSERT INTO verses VALUES (23996, 40, 23, 11, 'o porém maior vosso será vosso servo');
INSERT INTO verses VALUES (23997, 40, 23, 12, 'Quem-quer-que porém exaltará si-mesmo será-humilhado e qualquer-que humilhará si-mesmo será-exaltado');
INSERT INTO verses VALUES (23998, 40, 23, 13, 'Ai porém a-vós escribas e fariseus hipócritas que fechais o reino o dos-céus diante-de o dos-homens vós pois não entrais nem o entrando perdoais entrar');
INSERT INTO verses VALUES (23999, 40, 23, 15, 'Ai a-vós escribas e fariseus hipócritas que percorreis o mar e o seca fazer um prosélito e quando aconteça fazei ele Filho geena em-dobro vosso');
INSERT INTO verses VALUES (24000, 40, 23, 16, 'Ai a-vós guias cegos o dizendo o qual partícula-condicional jure em o templo nada é o qual e/mas partícula-condicional jure em o ouro o templo deve');
INSERT INTO verses VALUES (24001, 40, 23, 17, 'tolos e cegos quem pois maior é o ouro ou o templo o tendo-santificado o ouro');
INSERT INTO verses VALUES (24002, 40, 23, 18, 'e o qual partícula-condicional jure em o altar nada é o qual e/mas partícula-condicional jure em o presente o em-cima dele deve');
INSERT INTO verses VALUES (24003, 40, 23, 19, 'cegos quê pois maior o presente ou o altar o santificando o presente');
INSERT INTO verses VALUES (24004, 40, 23, 20, 'o portanto tendo-jurado em o altar jura em a ele e em todos o em-cima dele');
INSERT INTO verses VALUES (24005, 40, 23, 21, 'e o tendo-jurado em o templo jura em a ele e em o habitando ele');
INSERT INTO verses VALUES (24006, 40, 23, 22, 'e o tendo-jurado em o no-céu jura em o trono o de-Theos e em o sentado em-cima dele');
INSERT INTO verses VALUES (24007, 40, 23, 23, 'Ai a-vós escribas e fariseus hipócritas que dizimais o hortelã e o endro e o cominho e deixastes o mais-pesadas o da-lei o juízo e o misericórdia e o fé estas-coisas porém é necessário fazer e-aquelas não perdoar');
INSERT INTO verses VALUES (24008, 40, 23, 24, 'guias cegos o coando o mosquito o porém camelo tragando');
INSERT INTO verses VALUES (24009, 40, 23, 25, 'Ai a-vós escribas e fariseus hipócritas que limpais o de-fora o cálice e o do-prato por-dentro porém cheios de rapina e intemperança');
INSERT INTO verses VALUES (24010, 40, 23, 26, 'Fariseu cego purifica primeiro o dentro o cálice para que aconteça e o fora-de dele limpo');
INSERT INTO verses VALUES (24011, 40, 23, 27, 'Ai a-vós escribas e fariseus hipócritas que assemelhais-vos em-sepulcros tendo-sido-caiados os-quais de-fora por-um-lado aparecem formosos por-dentro porém cheios ossos mortos e toda impureza');
INSERT INTO verses VALUES (24012, 40, 23, 28, 'assim e vós de-fora por-um-lado apareceis o aos-homens justos por-dentro e/mas sois cheios Hipocrisia e iniquidade');
INSERT INTO verses VALUES (24013, 40, 23, 29, 'Ai a-vós escribas e fariseus hipócritas que edificai o sepulcros o profetas e adornais o sepulcros o justos');
INSERT INTO verses VALUES (24014, 40, 23, 30, 'e dizeis se estávamos em o dias o dos-pais nosso não partícula-condicional estávamos deles participantes em o sangue o profetas');
INSERT INTO verses VALUES (24015, 40, 23, 31, 'de-modo-que testemunhais si-mesmos que filhos sois o dos-que-mataram o profetas');
INSERT INTO verses VALUES (24016, 40, 23, 32, 'e vós enchei o medida o dos-pais vosso');
INSERT INTO verses VALUES (24017, 40, 23, 33, 'serpentes crias víboras como fujais de o juízo o geena');
INSERT INTO verses VALUES (24018, 40, 23, 34, 'através-de isto eis eu envio junto-a vos profetas e sábios e escribas de deles matareis e crucificareis e de deles açoitareis em o nas-sinagogas vosso e perseguireis de cidade para cidade');
INSERT INTO verses VALUES (24019, 40, 23, 35, 'para-que venha sobre vos todo sangue justo derramado sobre o da-terra de o sangue Abel o justo até o sangue Zacarias do-Filho Baraquias o qual assassinastes entre o santuário e o altar');
INSERT INTO verses VALUES (24020, 40, 23, 36, 'amém digo a-vós virá estas-coisas todas-as-coisas sobre o geração esta');
INSERT INTO verses VALUES (24021, 40, 23, 37, 'Jerusalém Jerusalém o matando o profetas e apedrejando o tendo-sido-enviados junto-a ela quantas-vezes quis Reunir o filhos teu o qual modo galinha Reúne o ninhada dela sob o asas e não quisestes');
INSERT INTO verses VALUES (24022, 40, 23, 38, 'eis é-perdoado a-vós o casa vosso');
INSERT INTO verses VALUES (24023, 40, 23, 39, 'digo pois a-vós não não me vejais de agora até partícula-condicional digais Bendito o o-que-vem em em-nome do-Kyrios');
INSERT INTO chapters VALUES (953, 40, 24, 51);
INSERT INTO verses VALUES (24024, 40, 24, 1, 'e saindo o Iesous de o do-templo ia e aproximaram-se o discípulos dele mostrar a ele o edificações o do-templo');
INSERT INTO verses VALUES (24025, 40, 24, 2, 'o porém respondendo disse a-eles não vede estas-coisas todas-as-coisas amém digo a-vós não não seja-perdoado aqui pedra sobre pedra o qual não será-destruído');
INSERT INTO verses VALUES (24026, 40, 24, 3, 'sentado porém dele sobre o do-monte o Oliveiras aproximaram-se a ele o discípulos segundo própria dizendo Dize a-nós quando estas-coisas será e quê o sinal o tua presença e consumação o eternidade');
INSERT INTO verses VALUES (24027, 40, 24, 4, 'e respondendo o Iesous disse a-eles Vede não alguém vos engane');
INSERT INTO verses VALUES (24028, 40, 24, 5, 'muitos pois virão sobre o no-nome meu dizendo Eu sou o Christos e a-muitos enganarão');
INSERT INTO verses VALUES (24029, 40, 24, 6, 'estareis-a-ponto-de porém ouvir guerras e ouvidos guerras vede não alarmeis-vos é necessário pois tornar-se mas ainda-não é o fim');
INSERT INTO verses VALUES (24030, 40, 24, 7, 'será-levantado pois nação sobre nação e reino sobre reino e serão fomes e terremotos segundo lugares');
INSERT INTO verses VALUES (24031, 40, 24, 8, 'todas-as-coisas porém estas-coisas princípio dores-de-parto');
INSERT INTO verses VALUES (24032, 40, 24, 9, 'então entregarão vos para tribulação e matarão vos e sereis odiados sob todos o nações através-de o nome meu');
INSERT INTO verses VALUES (24033, 40, 24, 10, 'e então serão-escandalizados muitos e uns-aos-outros entregarão e odiarão uns-aos-outros');
INSERT INTO verses VALUES (24034, 40, 24, 11, 'e muitos falsos-profetas serão-levantados e enganarão muitos');
INSERT INTO verses VALUES (24035, 40, 24, 12, 'e através-de o ser-multiplicados o iniquidade esfriará o amor o muitos');
INSERT INTO verses VALUES (24036, 40, 24, 13, 'o porém tendo-perseverado para fim este será-salvo');
INSERT INTO verses VALUES (24037, 40, 24, 14, 'e será-proclamado isto o evangelho o do-reino em toda o terra-habitada para testemunho todos o nações e então virá o fim');
INSERT INTO verses VALUES (24038, 40, 24, 15, 'quando portanto vejais o abominação o desolação o o-dito através-de Daniel o profeta de-pé em no-lugar no-santo o lendo entenda');
INSERT INTO verses VALUES (24039, 40, 24, 16, 'então o em o Judeia fujam para o montes');
INSERT INTO verses VALUES (24040, 40, 24, 17, 'o sobre o telhado não desça levantar o de o da-casa dele');
INSERT INTO verses VALUES (24041, 40, 24, 18, 'e o em o campo não volte atrás levantar o manto dele');
INSERT INTO verses VALUES (24042, 40, 24, 19, 'ai porém o em ventre tendo e o às-que-amamentam em aqueles o dias');
INSERT INTO verses VALUES (24043, 40, 24, 20, 'orai porém para que não aconteça o fuga vosso inverno nem no-sábado');
INSERT INTO verses VALUES (24044, 40, 24, 21, 'será pois então tribulação grande quais não aconteceu de princípio do-mundo até o agora nem não não aconteça');
INSERT INTO verses VALUES (24045, 40, 24, 22, 'e se não foram-encurtados o dias aquelas não partícula-condicional foi-salvo toda carne através-de porém o eleitos serão-encurtados o dias aquelas');
INSERT INTO verses VALUES (24046, 40, 24, 23, 'então se alguém a-vós diga Eis aqui o Christos ou Aqui não creiais');
INSERT INTO verses VALUES (24047, 40, 24, 24, 'serão-levantados pois falsos-ungidos e falsos-profetas e darão sinais grandes e prodígios de-modo-que enganar se possível e o escolhidos');
INSERT INTO verses VALUES (24048, 40, 24, 25, 'eis predisse a-vós');
INSERT INTO verses VALUES (24049, 40, 24, 26, 'se portanto digam a-vós Eis em o deserto é não saiais Eis em o aposentos-interiores não creiais');
INSERT INTO verses VALUES (24050, 40, 24, 27, 'assim-como pois o relâmpago sai de oriente e aparece até ocidente assim será o presença o do-Filho o do-homem');
INSERT INTO verses VALUES (24051, 40, 24, 28, 'onde se seja o cadáver ali serão-reunidos o águias');
INSERT INTO verses VALUES (24052, 40, 24, 29, 'imediatamente porém com o tribulação o dos-dias daqueles o sol será-obscurecido e o lua não dará o brilho dela e o estrelas cairão de o do-céu e o poderes o dos-céus serão-abalados');
INSERT INTO verses VALUES (24053, 40, 24, 30, 'e então aparecerá o sinal o do-Filho o do-homem em no-céu e então lamentarão todas o tribos o da-terra e verão o Filho o do-homem o-que-vem sobre o nuvens o do-céu com do-poder e da-glória muita');
INSERT INTO verses VALUES (24054, 40, 24, 31, 'e enviará o anjo dele com trombeta grande e Reunirão o eleitos dele de o quatro ventos de extremidades dos-céus até extremidades deles');
INSERT INTO verses VALUES (24055, 40, 24, 32, 'de porém o figueira aprendei o parábola quando já o ramo dela aconteça tenro e o folhas brote sabeis que perto o verão');
INSERT INTO verses VALUES (24056, 40, 24, 33, 'assim e vós quando vejais todas-as-coisas estas-coisas sabeis que perto é sobre portas');
INSERT INTO verses VALUES (24057, 40, 24, 34, 'amém digo a-vós que não não passe o geração esta até partícula-condicional todas-as-coisas estas-coisas aconteça');
INSERT INTO verses VALUES (24058, 40, 24, 35, 'o céu e o terra passará o porém palavras meu não não passem');
INSERT INTO verses VALUES (24059, 40, 24, 36, 'acerca-de porém o do-dia daquela e hora ninguém sei nem o anjo o dos-céus nem o filho se não o Pai só');
INSERT INTO verses VALUES (24060, 40, 24, 37, 'assim-como pois o dias o Noé assim será o presença o do-Filho o do-homem');
INSERT INTO verses VALUES (24061, 40, 24, 38, 'como pois eram em o dias aqueles o antes-de o dilúvio mastigando e bebendo casando e dando-em-casamento até o qual do-dia entrou Noé para o arca');
INSERT INTO verses VALUES (24062, 40, 24, 39, 'e não conheceram até veio o dilúvio e levantou todos assim será e o presença o do-Filho o do-homem');
INSERT INTO verses VALUES (24063, 40, 24, 40, 'então serão dois em o campo um é-tomado e um é-perdoado');
INSERT INTO verses VALUES (24064, 40, 24, 41, 'dois moendo em o moinho uma é-tomado e uma é-perdoado');
INSERT INTO verses VALUES (24065, 40, 24, 42, 'vigiai portanto que não sei qual dia o kyrios vosso vem');
INSERT INTO verses VALUES (24066, 40, 24, 43, 'aquilo porém sabeis que se sei o dono-de-casa qual na-prisão o ladrão vem vigiou partícula-condicional e não partícula-condicional permitiu ser-arrombada o casa dele');
INSERT INTO verses VALUES (24067, 40, 24, 44, 'através-de isto e vós tornai-vos prontos que o qual não pensais hora o Filho o do-homem vem');
INSERT INTO verses VALUES (24068, 40, 24, 45, 'Quem então é o fiel servo e prudente o qual constituiu o kyrios sobre o serviçais dele o dar a-eles o alimento em tempo');
INSERT INTO verses VALUES (24069, 40, 24, 46, 'bem-aventurado o servo aquele o qual vindo o kyrios dele encontrará assim fazendo');
INSERT INTO verses VALUES (24070, 40, 24, 47, 'amém digo a-vós que sobre todos o existem dele estabelecerá ele');
INSERT INTO verses VALUES (24071, 40, 24, 48, 'se porém diga o mau servo aquele em o no-coração dele Demora meu o kyrios');
INSERT INTO verses VALUES (24072, 40, 24, 49, 'e comece bater o co-servos dele coma porém e beba com o embriagando-se');
INSERT INTO verses VALUES (24073, 40, 24, 50, 'virá o kyrios o servo daquele em dia o qual não espera e em hora o qual não conhece');
INSERT INTO verses VALUES (24074, 40, 24, 51, 'e cortará-em-dois ele e o parte dele com o hipócritas porá ali será o choro e o ranger o dentes');
INSERT INTO chapters VALUES (954, 40, 25, 46);
INSERT INTO verses VALUES (24075, 40, 25, 1, 'Então será-semelhante o reino o dos-céus dez a-virgens as-quais tendo-recebido o lâmpadas deles-mesmos saíram para encontro o noivo');
INSERT INTO verses VALUES (24076, 40, 25, 2, 'cinco porém de deles eram tolas e cinco prudentes');
INSERT INTO verses VALUES (24077, 40, 25, 3, 'o pois tolas tendo-recebido o lâmpadas não receberam com deles-mesmos azeite');
INSERT INTO verses VALUES (24078, 40, 25, 4, 'o porém prudentes receberam azeite em o vasilhas com o lâmpadas deles-mesmos');
INSERT INTO verses VALUES (24079, 40, 25, 5, 'demorando porém o noivo cochilaram todas e dormiam');
INSERT INTO verses VALUES (24080, 40, 25, 6, 'meio porém da-noite clamor aconteceu Eis o noivo saí para encontro');
INSERT INTO verses VALUES (24081, 40, 25, 7, 'então foram-levantados todas o virgens aquelas e adornaram o lâmpadas deles-mesmos');
INSERT INTO verses VALUES (24082, 40, 25, 8, 'o porém tolas o prudentes disseram dai a-nós de o azeite vosso que o tochas nosso são-apagadas');
INSERT INTO verses VALUES (24083, 40, 25, 9, 'responderam porém o prudentes dizendo não alguma-vez não não baste a-nós e a-vós ide mais junto-a o vendendo e comprai A-si-mesmas');
INSERT INTO verses VALUES (24084, 40, 25, 10, 'partindo porém deles comprares veio o noivo e o prontos entraram com dele para o bodas e foi-fechado o porta');
INSERT INTO verses VALUES (24085, 40, 25, 11, 'depois porém vêm e o restantes virgens dizendo Kyrie kyrie abre a-nós');
INSERT INTO verses VALUES (24086, 40, 25, 12, 'o porém respondendo disse Amém digo a-vós não sei vos');
INSERT INTO verses VALUES (24087, 40, 25, 13, 'Vigiai portanto que não sei o dia nem o hora');
INSERT INTO verses VALUES (24088, 40, 25, 14, 'como pois homem viajando chamou o próprios servos e entregou a-eles o posses dele');
INSERT INTO verses VALUES (24089, 40, 25, 15, 'e o qual por-um-lado deu cinco talentos o qual porém dois o qual porém um a-cada-um segundo o própria poder e viajou imediatamente');
INSERT INTO verses VALUES (24090, 40, 25, 16, 'tendo-ido o o cinco talentos tomando trabalhou em a-eles e ganhou outras-coisas cinco');
INSERT INTO verses VALUES (24091, 40, 25, 17, 'da-mesma-forma o o dois ganhou outras-coisas dois');
INSERT INTO verses VALUES (24092, 40, 25, 18, 'o porém o um tomando partindo cavou terra e escondeu o prata o do-Kyrios dele');
INSERT INTO verses VALUES (24093, 40, 25, 19, 'com porém muito tempo vem o kyrios o servos daqueles e acerta-contas palavra com deles');
INSERT INTO verses VALUES (24094, 40, 25, 20, 'e aproximando-se o o cinco talentos tomando ofereceu outras-coisas cinco talentos dizendo Kyrie cinco talentos a-mim entregaste vê outras-coisas cinco talentos ganhei');
INSERT INTO verses VALUES (24095, 40, 25, 21, 'disse a ele o kyrios dele Bem servo bom e fiel sobre poucas-coisas fosses fiel sobre muitos te constituirei entra para o alegria o do-Kyrios teu');
INSERT INTO verses VALUES (24096, 40, 25, 22, 'aproximando-se e o o dois talentos disse Kyrie dois talentos a-mim entregaste vê outras-coisas dois talentos ganhei');
INSERT INTO verses VALUES (24097, 40, 25, 23, 'disse a ele o kyrios dele Bem servo bom e fiel sobre poucas-coisas fosses fiel sobre muitos te constituirei entra para o alegria o do-Kyrios teu');
INSERT INTO verses VALUES (24098, 40, 25, 24, 'aproximando-se porém e o o um talento tendo-recebido disse Kyrie conheci te que duro és homem ceifando onde não semeaste e reunindo de-onde não dispersaste');
INSERT INTO verses VALUES (24099, 40, 25, 25, 'e tendo-temido partindo Escondi o talento teu em o terra vê tens o teu');
INSERT INTO verses VALUES (24100, 40, 25, 26, 'respondendo porém o kyrios dele disse a ele Mau servo e preguiçoso sei que ceifo onde não semeei e reúno de-onde não dispersei');
INSERT INTO verses VALUES (24101, 40, 25, 27, 'é necessário te portanto lançar o moedas-de-prata meu o banqueiros e vindo eu recebi-de-volta partícula-condicional o meu com juro');
INSERT INTO verses VALUES (24102, 40, 25, 28, 'levantai portanto de dele o talento e dai o tendo o dez talentos');
INSERT INTO verses VALUES (24103, 40, 25, 29, 'o pois tendo todo será-dado e será-feito-abundar o porém não tendo e o qual tem será-tirado de dele');
INSERT INTO verses VALUES (24104, 40, 25, 30, 'e o inútil servo lançai-fora para o trevas o exterior ali será o choro e o ranger o dentes');
INSERT INTO verses VALUES (24105, 40, 25, 31, 'quando porém venha o Filho o do-homem em o glória dele e todos o anjo com dele então sentará sobre trono da-glória dele');
INSERT INTO verses VALUES (24106, 40, 25, 32, 'e serão-reunidos diante-de dele todas-as-coisas o nações e separará eles de uns-aos-outros assim-como o pastor separa o ovelhas de o Cabritos');
INSERT INTO verses VALUES (24107, 40, 25, 33, 'e estabelecerá o por-um-lado ovelhas de direita dele o porém Cabritos de esquerda');
INSERT INTO verses VALUES (24108, 40, 25, 34, 'então dirá o Rei o de direita dele vinde o tendo-sido-abençoados o do-Pai meu herdai o preparada a-vós reino de fundação do-mundo');
INSERT INTO verses VALUES (24109, 40, 25, 35, 'tive-fome pois e destes a-mim comer tive-sede e destes-de-beber me estrangeiro eu-era e reunistes me');
INSERT INTO verses VALUES (24110, 40, 25, 36, 'nu e vestistes me adoeci e visitastes me em na-prisão eu-era e Viestes para me');
INSERT INTO verses VALUES (24111, 40, 25, 37, 'então responderão a ele o justos dizendo Kyrie quando te vimos tendo-fome e nutrimos ou tendo-sede e Demos-de-beber');
INSERT INTO verses VALUES (24112, 40, 25, 38, 'quando e/mas te vimos estranho e reunimos ou nu e vestimos');
INSERT INTO verses VALUES (24113, 40, 25, 39, 'quando e/mas te vimos estando-fraco ou em na-prisão e viemos para te');
INSERT INTO verses VALUES (24114, 40, 25, 40, 'e respondendo o Rei dirá a-eles Amém digo a-vós sobre quanto fizestes um destes o dos-irmãos meu o menores mim fizestes');
INSERT INTO verses VALUES (24115, 40, 25, 41, 'então dirá e o de esquerda Ide de mim tendo-sido-amaldiçoados para o fogo o eterno o tendo-sido-preparado o diabo e o anjo dele');
INSERT INTO verses VALUES (24116, 40, 25, 42, 'tive-fome pois e não destes a-mim comer tive-sede e não destes-de-beber me');
INSERT INTO verses VALUES (24117, 40, 25, 43, 'estrangeiro eu-era e não reunistes me nu e não vestistes me fraco e em na-prisão e não visitastes me');
INSERT INTO verses VALUES (24118, 40, 25, 44, 'então responderão e eles-mesmos dizendo Kyrie quando te vimos tendo-fome ou tendo-sede ou estranho ou nu ou fracos ou em na-prisão e não servimos a-ti');
INSERT INTO verses VALUES (24119, 40, 25, 45, 'então será-respondido a-eles dizendo Amém digo a-vós sobre quanto não fizestes um destes o menores nem mim fizestes');
INSERT INTO verses VALUES (24120, 40, 25, 46, 'e irão estes para castigo eterno o porém justos para vida eterno');
INSERT INTO chapters VALUES (955, 40, 26, 75);
INSERT INTO verses VALUES (24121, 40, 26, 1, 'e aconteceu quando terminou o Iesous todos o palavras estes disse o discípulos dele');
INSERT INTO verses VALUES (24122, 40, 26, 2, 'sei que com dois do-dia o páscoa torna-se e o Filho o do-homem é-entregue para o ser-crucificado');
INSERT INTO verses VALUES (24123, 40, 26, 3, 'Então foram-reunidos o sumos-sacerdotes e o anciãos o povo para o pátio o do-sumo-sacerdote o sendo-chamado Caifás');
INSERT INTO verses VALUES (24124, 40, 26, 4, 'e aconselharam-se-junto para que o Iesous engano segurem e matem');
INSERT INTO verses VALUES (24125, 40, 26, 5, 'diziam e/mas não em o festa para que não tumulto aconteça em o povo');
INSERT INTO verses VALUES (24126, 40, 26, 6, 'o porém Iesous tendo-acontecido em Betânia em casa de-Simão o leproso');
INSERT INTO verses VALUES (24127, 40, 26, 7, 'aproximou-se a ele mulher tendo alabastro perfume de-muito-valor e derramou sobre o cabeça dele reclinado');
INSERT INTO verses VALUES (24128, 40, 26, 8, 'vendo porém o discípulos indignaram-se dizendo para quê o perdição esta');
INSERT INTO verses VALUES (24129, 40, 26, 9, 'podia pois isto ser-vendido grande e ser-dado pobres');
INSERT INTO verses VALUES (24130, 40, 26, 10, 'sabendo porém o Iesous disse a-eles quê trabalhos apresentai o mulher obra pois belo trabalhou para a-mim');
INSERT INTO verses VALUES (24131, 40, 26, 11, 'sempre pois o pobres tendes com deles-mesmos mim porém não sempre tendes');
INSERT INTO verses VALUES (24132, 40, 26, 12, 'tendo-lançado pois esta o mirra isto sobre o corpo meu junto-a o embalsamar me fez');
INSERT INTO verses VALUES (24133, 40, 26, 13, 'amém digo a-vós onde se seja-proclamado o evangelho isto em todo o ao-mundo será-falado e o qual fez esta para memorial dela');
INSERT INTO verses VALUES (24134, 40, 26, 14, 'Então tendo-ido um o doze o chamado Judas Iscariotes junto-a o sumos-sacerdotes');
INSERT INTO verses VALUES (24135, 40, 26, 15, 'disse quê quereis a-mim dar e-eu a-vós entregarei ele o porém estavam-de-pé a ele trinta moedas-de-prata');
INSERT INTO verses VALUES (24136, 40, 26, 16, 'e de então buscava oportunidade para que ele entregue');
INSERT INTO verses VALUES (24137, 40, 26, 17, 'o porém primeiro o ázimos aproximaram-se o discípulos o Iesous dizendo onde queres Preparemos a-ti comer o páscoa');
INSERT INTO verses VALUES (24138, 40, 26, 18, 'o porém disse ide para o cidade junto-a o fulano e dizei a ele o Mestre diz o tempo meu perto é junto-a te faço o páscoa com o discípulos meu');
INSERT INTO verses VALUES (24139, 40, 26, 19, 'e fizeram o discípulos como ordenou a-eles o Iesous e prepararam o páscoa');
INSERT INTO verses VALUES (24140, 40, 26, 20, 'Tarde porém tendo-acontecido estava-reclinado com o doze discípulos');
INSERT INTO verses VALUES (24141, 40, 26, 21, 'e comendo deles disse Amém digo a-vós que um de vosso entregará me');
INSERT INTO verses VALUES (24142, 40, 26, 22, 'e entristecendo-se extremamente começaram dizer a ele um cada-um Acaso eu sou Kyrie');
INSERT INTO verses VALUES (24143, 40, 26, 23, 'o porém respondendo disse o tendo-mergulhado com mim o mão em o prato este me entregará');
INSERT INTO verses VALUES (24144, 40, 26, 24, 'o por-um-lado Filho o do-homem vai assim-como está-escrito acerca-de dele ai porém o ao-homem naquele através-de o qual o Filho o do-homem é-entregue belo era a ele se não foi-gerado o homem aquele');
INSERT INTO verses VALUES (24145, 40, 26, 25, 'respondendo porém Judas o entregando ele disse Acaso eu sou Rabi diz a ele tu disseste');
INSERT INTO verses VALUES (24146, 40, 26, 26, 'Comendo porém deles tomando o Iesous pão e tendo-abençoado partiu e dando o discípulos disse Tomai comei isto é o corpo meu');
INSERT INTO verses VALUES (24147, 40, 26, 27, 'e tomando cálice e tendo-dado-graças deu a-eles dizendo Bebei de dele todos');
INSERT INTO verses VALUES (24148, 40, 26, 28, 'isto pois é o sangue meu o da-aliança o acerca-de muitos derramado para perdão dos-pecados');
INSERT INTO verses VALUES (24149, 40, 26, 29, 'digo porém a-vós não não beba de agora de deste o fruto o videira até o do-dia daquela quando ele bebo com vosso novo em o no-reino o do-Pai meu');
INSERT INTO verses VALUES (24150, 40, 26, 30, 'e tendo-cantado-hinos saíram para o monte o Oliveiras');
INSERT INTO verses VALUES (24151, 40, 26, 31, 'Então diz a-eles o Iesous todos vós sereis-escandalizados em mim em o à-noite nesta está-escrito pois Ferirei o pastor e serão-dispersos o ovelhas o rebanho');
INSERT INTO verses VALUES (24152, 40, 26, 32, 'com porém o ser-levantado me conduzirei-adiante vos para o Galileia');
INSERT INTO verses VALUES (24153, 40, 26, 33, 'respondendo porém o Pedro disse a ele se todos serão-escandalizados em a-ti eu nunca serei-escandalizado');
INSERT INTO verses VALUES (24154, 40, 26, 34, 'disse a ele o Iesous Amém digo a-ti que em nesta o à-noite antes-de galo chamar três-vezes negará me');
INSERT INTO verses VALUES (24155, 40, 26, 35, 'diz a ele o Pedro Mesmo-se é necessário me com a-ti morrer não não te negarei semelhantemente e todos o discípulos disseram');
INSERT INTO verses VALUES (24156, 40, 26, 36, 'Então vem com deles o Iesous para campo chamado Getsêmani e diz o discípulos Sentai-vos dele até o qual partindo ali ore');
INSERT INTO verses VALUES (24157, 40, 26, 37, 'e tomando-consigo o Pedro e o dois filhos Zebedeu começou entristecer-se e angustiar-se');
INSERT INTO verses VALUES (24158, 40, 26, 38, 'então diz a-eles Profundamente-triste é o alma meu até da-morte permanecei aqui e vigiai com mim');
INSERT INTO verses VALUES (24159, 40, 26, 39, 'e tendo-ido-adiante pouco caiu sobre rosto dele orando e dizendo Pai meu se possível é passe de mim o cálice isto porém não como eu quero mas como tu');
INSERT INTO verses VALUES (24160, 40, 26, 40, 'e vem junto-a o discípulos e encontra eles dormindo e diz o a-Pedro Assim não Fostes-fortes uma hora vigiar com mim');
INSERT INTO verses VALUES (24161, 40, 26, 41, 'vigiai e orai para que não entreis para tentação o por-um-lado espírito pronto o porém carne fraco');
INSERT INTO verses VALUES (24162, 40, 26, 42, 'novamente de segunda partindo orou dizendo Pai meu se não pode isto passar se não ele beba seja-feito o vontade teu');
INSERT INTO verses VALUES (24163, 40, 26, 43, 'e vindo novamente encontrou eles dormindo eram pois deles o olhos tendo-sido-sobrecarregados');
INSERT INTO verses VALUES (24164, 40, 26, 44, 'e deixando eles novamente partindo orou de terceiro o ele palavra dizendo novamente');
INSERT INTO verses VALUES (24165, 40, 26, 45, 'então vem junto-a o discípulos e diz a-eles Dormis restante e descansai eis aproximou-se o hora e o Filho o do-homem é-entregue para mãos dos-pecadores');
INSERT INTO verses VALUES (24166, 40, 26, 46, 'levantai-vos vamos eis aproximou-se o entregando me');
INSERT INTO verses VALUES (24167, 40, 26, 47, 'e ainda dele falando eis Judas um o doze veio e com dele multidão muito com espadas e madeiras de o sumos-sacerdotes e dos-anciãos o povo');
INSERT INTO verses VALUES (24168, 40, 26, 48, 'o porém entregando ele deu a-eles sinal dizendo o qual partícula-condicional beijarei ele é segurai ele');
INSERT INTO verses VALUES (24169, 40, 26, 49, 'e imediatamente aproximando-se o Iesous disse Alegra-te Rabi e beijou-intensamente ele');
INSERT INTO verses VALUES (24170, 40, 26, 50, 'o porém Iesous disse a ele companheiro sobre o qual está-presente então aproximando-se lançaram-sobre o mãos sobre o Iesous e agarraram ele');
INSERT INTO verses VALUES (24171, 40, 26, 51, 'e eis um o com Iesous estendendo o mão separou-se o espada dele e tendo-ferido o servo o do-sumo-sacerdote tirou dele o orelha');
INSERT INTO verses VALUES (24172, 40, 26, 52, 'então diz a ele o Iesous Volta-atrás o espada teu para o lugar dela todos pois o tendo-tomado espada em espada perecerão');
INSERT INTO verses VALUES (24173, 40, 26, 53, 'ou pareces que não posso consolar o Pai meu e apresentará a-mim agora mais doze legiões anjo');
INSERT INTO verses VALUES (24174, 40, 26, 54, 'como portanto sejam-completados o escrituras que assim é necessário tornar-se');
INSERT INTO verses VALUES (24175, 40, 26, 55, 'em naquela o hora disse o Iesous o às-multidões como sobre ladrão saístes com espadas e madeiras prender me segundo dia em o templo sentava-me ensinando e não prendestes me');
INSERT INTO verses VALUES (24176, 40, 26, 56, 'isto porém todo aconteceu para que sejam-completados o escrituras o profetas Então o discípulos todos deixando ele fugiram');
INSERT INTO verses VALUES (24177, 40, 26, 57, 'o porém tendo-agarrado o Iesous levaram-embora junto-a Caifás o sumo-sacerdote onde o escribas e o anciãos foram-reunidos');
INSERT INTO verses VALUES (24178, 40, 26, 58, 'o porém Pedro seguia a ele de de-longe até o pátio o do-sumo-sacerdote e entrando dentro sentava-se com o servindo ver o fim');
INSERT INTO verses VALUES (24179, 40, 26, 59, 'o porém sumos-sacerdotes e o sinédrio todo buscavam falso-testemunho segundo o Iesous para-que ele matem');
INSERT INTO verses VALUES (24180, 40, 26, 60, 'e não encontraram muitos tendo-se-aproximado falsas-testemunhas depois porém aproximando-se dois');
INSERT INTO verses VALUES (24181, 40, 26, 61, 'disseram este disse posso destruir o templo o de-Theos e através-de três dos-dias edificar');
INSERT INTO verses VALUES (24182, 40, 26, 62, 'e levantando-se o sumo-sacerdote disse a ele nada respondes quê estes teu testemunham-contra');
INSERT INTO verses VALUES (24183, 40, 26, 63, 'o porém Iesous calava-se e o sumo-sacerdote disse a ele Conjuro te segundo o de-Theos o vivente para que a-nós digas se tu és o Christos o Filho o de-Theos');
INSERT INTO verses VALUES (24184, 40, 26, 64, 'diz a ele o Iesous tu disseste porém digo a-vós de agora vereis o Filho o do-homem sentado de direita o do-poder e o-que-vem sobre o nuvens o do-céu');
INSERT INTO verses VALUES (24185, 40, 26, 65, 'então o sumo-sacerdote rasgou o vestes dele dizendo Blasfemou quê ainda necessidade temos testemunhas vê agora ouvistes o blasfêmia');
INSERT INTO verses VALUES (24186, 40, 26, 66, 'quê a-vós parece o porém respondendo disseram Culpado da-morte é');
INSERT INTO verses VALUES (24187, 40, 26, 67, 'Então cuspiram-em para o rosto dele e esbofetearam ele o porém Esbofetearam');
INSERT INTO verses VALUES (24188, 40, 26, 68, 'dizendo Profetiza a-nós Christos quem é o tendo-golpeado te');
INSERT INTO verses VALUES (24189, 40, 26, 69, 'o porém Pedro sentava-se fora em o pátio e aproximou-se a ele uma serva dizendo e tu eras com Iesous o Galileu');
INSERT INTO verses VALUES (24190, 40, 26, 70, 'o porém negou diante-de todos dizendo não sei quê dizes');
INSERT INTO verses VALUES (24191, 40, 26, 71, 'tendo-saído porém para o portão viu ele outra e diz o ali este era com Iesous o nazareno');
INSERT INTO verses VALUES (24192, 40, 26, 72, 'e novamente negou com juramento que não sei o homem');
INSERT INTO verses VALUES (24193, 40, 26, 73, 'com pouco porém aproximando-se o de-pé disseram o a-Pedro Verdadeiramente e tu de deles és e pois o fala teu evidente te faz');
INSERT INTO verses VALUES (24194, 40, 26, 74, 'então começou amaldiçoar e jurar que não sei o homem e imediatamente galo clamou');
INSERT INTO verses VALUES (24195, 40, 26, 75, 'e lembrou o Pedro o palavra Iesous tendo-dito que Antes-que galo chamar três-vezes negará me e saindo fora chorou amargamente');
INSERT INTO chapters VALUES (956, 40, 27, 66);
INSERT INTO verses VALUES (24196, 40, 27, 1, 'Manhã porém tendo-acontecido conselho receberam todos o sumos-sacerdotes e o anciãos o povo segundo o Iesous de-modo-que matar ele');
INSERT INTO verses VALUES (24197, 40, 27, 2, 'e tendo-amarrado ele levaram-embora e entregaram Pilatos o governador');
INSERT INTO verses VALUES (24198, 40, 27, 3, 'Então vendo Judas o entregando ele que foi-condenado tendo-se-arrependido virou o trinta moedas-de-prata o sumos-sacerdotes e presbíteros');
INSERT INTO verses VALUES (24199, 40, 27, 4, 'dizendo Pequei entregando sangue inocente o porém disseram quê junto-a nos tu verás');
INSERT INTO verses VALUES (24200, 40, 27, 5, 'e tendo-lançado o moedas-de-prata para o templo retirou-se e partindo enforcou-se');
INSERT INTO verses VALUES (24201, 40, 27, 6, 'o porém sumos-sacerdotes tendo-tomado o moedas-de-prata disseram não é-lícito lançar eles para o corbã porque honra sangue é');
INSERT INTO verses VALUES (24202, 40, 27, 7, 'conselho porém tendo-tomado compraram de deles o campo o oleiro para sepultamento o estrangeiros');
INSERT INTO verses VALUES (24203, 40, 27, 8, 'por-isso foi-chamado o campo aquele Campo sangue até o hoje');
INSERT INTO verses VALUES (24204, 40, 27, 9, 'então foi-cumprido o o-dito através-de Jeremias o profeta dizendo e receberam o trinta moedas-de-prata o honra o tendo-sido-honrado o qual Avaliaram de dos-filhos Israel');
INSERT INTO verses VALUES (24205, 40, 27, 10, 'e deram eles para o campo o oleiro conforme ordenou a-mim Kyrios');
INSERT INTO verses VALUES (24206, 40, 27, 11, 'o porém Iesous colocou-se diante-de o governador e perguntou ele o governador dizendo tu és o Rei o judeus o porém Iesous disse tu dizes');
INSERT INTO verses VALUES (24207, 40, 27, 12, 'e em o ser-acusado ele sob o sumos-sacerdotes e dos-anciãos nada respondeu');
INSERT INTO verses VALUES (24208, 40, 27, 13, 'então diz a ele o Pilatos não ouves quantas teu testemunham-contra');
INSERT INTO verses VALUES (24209, 40, 27, 14, 'e não respondeu a ele junto-a nem um palavra de-modo-que admirar o governador muito');
INSERT INTO verses VALUES (24210, 40, 27, 15, 'segundo porém festa costumava o governador soltar um o à-multidão prisioneiro o qual queriam');
INSERT INTO verses VALUES (24211, 40, 27, 16, 'tinham porém então prisioneiro notável chamado Barrabás');
INSERT INTO verses VALUES (24212, 40, 27, 17, 'tendo-sido-reunidos portanto deles disse a-eles o Pilatos Quem quereis soltarei a-vós Barrabás ou Iesous o chamado Christos');
INSERT INTO verses VALUES (24213, 40, 27, 18, 'sei pois que através-de inveja entregaram ele');
INSERT INTO verses VALUES (24214, 40, 27, 19, 'Estando-sentado porém dele sobre o tribunal enviou junto-a ele o mulher dele dizendo nada a-ti e o justo aquele muitas-coisas pois Sofreram hoje segundo sonho através-de ele');
INSERT INTO verses VALUES (24215, 40, 27, 20, 'o porém sumos-sacerdotes e o anciãos Persuadiram o multidões para que peçam o Barrabás o porém Iesous destruam');
INSERT INTO verses VALUES (24216, 40, 27, 21, 'respondendo porém o governador disse a-eles Quem quereis de o dois soltarei a-vós o porém disseram o Barrabás');
INSERT INTO verses VALUES (24217, 40, 27, 22, 'diz a-eles o Pilatos quê portanto farei Iesous o chamado Christon dizem todos Seja-crucificado');
INSERT INTO verses VALUES (24218, 40, 27, 23, 'o porém disse quê pois mau fez o porém abundantemente clamavam dizendo Seja-crucificado');
INSERT INTO verses VALUES (24219, 40, 27, 24, 'vendo porém o Pilatos que nada aproveita mas mais tumulto torna-se tomando água lavou o mãos defronte-de o da-multidão dizendo Inocente sou de o sangue deste vós vereis');
INSERT INTO verses VALUES (24220, 40, 27, 25, 'e respondendo todo o povo disse o sangue dele sobre nos e sobre o filhos nosso');
INSERT INTO verses VALUES (24221, 40, 27, 26, 'então soltou a-eles o Barrabás o porém Iesous tendo-açoitado entregou para que seja-crucificado');
INSERT INTO verses VALUES (24222, 40, 27, 27, 'Então o soldados o governador tendo-recebido o Iesous para o pretório reuniram sobre ele toda o coorte');
INSERT INTO verses VALUES (24223, 40, 27, 28, 'e tendo-despido ele manto escarlate colocaram-ao-redor a ele');
INSERT INTO verses VALUES (24224, 40, 27, 29, 'e tendo-trançado coroa de espinhos puseram-sobre sobre o cabeça dele e cana em o direita dele e tendo-ajoelhado diante-de dele zombaram a ele dizendo Alegra-te Rei o judeus');
INSERT INTO verses VALUES (24225, 40, 27, 30, 'e tendo-cuspido para ele receberam o cana e batiam para o cabeça dele');
INSERT INTO verses VALUES (24226, 40, 27, 31, 'e quando zombaram a ele despiram ele o manto e vestiram ele o vestes dele e levaram-embora ele para o crucificar');
INSERT INTO verses VALUES (24227, 40, 27, 32, 'Saindo porém encontraram homem Cireneu em-nome Simão este requisitaram para que levante o cruz dele');
INSERT INTO verses VALUES (24228, 40, 27, 33, 'e vindo para lugar chamado Gólgota o qual é crânio lugar chamado');
INSERT INTO verses VALUES (24229, 40, 27, 34, 'deram a ele beber vinho com de-fel tendo-sido-misturado e tendo-provado não quis beber');
INSERT INTO verses VALUES (24230, 40, 27, 35, 'tendo-crucificado porém ele repartiram o vestes dele lançando sorte');
INSERT INTO verses VALUES (24231, 40, 27, 36, 'e sentados guardavam ele ali');
INSERT INTO verses VALUES (24232, 40, 27, 37, 'e puseram-sobre em-cima o cabeça dele o causa dele tendo-sido-escrita ESTE É Iesous o REI o JUDEUS');
INSERT INTO verses VALUES (24233, 40, 27, 38, 'Então são-crucificados com a ele dois salteadores um de direita e um de esquerda');
INSERT INTO verses VALUES (24234, 40, 27, 39, 'o porém passando-ao-lado blasfemavam ele movendo o cabeças deles');
INSERT INTO verses VALUES (24235, 40, 27, 40, 'e dizendo o destruindo o templo e em três dias edificando salva a-ti-mesmo se Filho és o de-Theos e desce de o da-cruz');
INSERT INTO verses VALUES (24236, 40, 27, 41, 'semelhantemente o sumos-sacerdotes zombando com o dos-escribas e dos-anciãos diziam');
INSERT INTO verses VALUES (24237, 40, 27, 42, 'Outros salvou si-mesmo não pode salvar Rei Israel é desça agora de o da-cruz e creremos sobre ele');
INSERT INTO verses VALUES (24238, 40, 27, 43, 'tem-confiado sobre o Theos livre agora se quer ele disse pois que de-Theos sou Filho');
INSERT INTO verses VALUES (24239, 40, 27, 44, 'o e/mas ele e o ladrões o tendo-sido-co-crucificados com a ele injuriavam ele');
INSERT INTO verses VALUES (24240, 40, 27, 45, 'de porém sexta hora trevas aconteceu sobre toda o terra até hora nona');
INSERT INTO verses VALUES (24241, 40, 27, 46, 'acerca-de porém o nona hora clamou-em-alta-voz o Iesous com-voz grande dizendo Eli Eli lema sabactâni isto é Thee meu Theos meu para que quê me abandonaste');
INSERT INTO verses VALUES (24242, 40, 27, 47, 'alguns porém o ali estando-de-pé ouvindo diziam que Elias chama este');
INSERT INTO verses VALUES (24243, 40, 27, 48, 'e imediatamente tendo-corrido um de deles e tomando esponja tendo-enchido e vinagre e tendo-posto-ao-redor cana dava-de-beber ele');
INSERT INTO verses VALUES (24244, 40, 27, 49, 'o porém restantes disseram Deixa vejamos se vem Elias havendo-de-salvar ele');
INSERT INTO verses VALUES (24245, 40, 27, 50, 'o porém Iesous novamente clamando com-voz grande deixou o espírito');
INSERT INTO verses VALUES (24246, 40, 27, 51, 'e eis o véu o templo rasgou-se de de-cima até abaixo para dois e o terra foi-sacudida e o rochas Foram-rasgados');
INSERT INTO verses VALUES (24247, 40, 27, 52, 'e o sepulcros foram-abertos e muitas-coisas corpos o tendo-adormecido dos-santos foram-levantados');
INSERT INTO verses VALUES (24248, 40, 27, 53, 'e saindo de o sepulcros com o Ressurreição dele entraram para o santa cidade e foram-revelados muitos');
INSERT INTO verses VALUES (24249, 40, 27, 54, 'o porém centurião e o com dele guardando o Iesous vendo o terremoto e o acontecendo temeram extremamente dizendo Verdadeiramente de-Theos Filho era este');
INSERT INTO verses VALUES (24250, 40, 27, 55, 'eram porém ali mulheres muitas de de-longe contemplando as-quais seguiram o Iesous de o Galileia servindo a ele');
INSERT INTO verses VALUES (24251, 40, 27, 56, 'em o qual era Maria o Madalena e Maria o o de-Tiago e José mãe e o mãe o dos-filhos Zebedeu');
INSERT INTO verses VALUES (24252, 40, 27, 57, 'Tarde porém tendo-acontecido veio homem rico de Arimateia o-nome José o qual e ele foi-feito-discípulo o Iesous');
INSERT INTO verses VALUES (24253, 40, 27, 58, 'este aproximando-se o Pilatos pediu o corpo o Iesous então o Pilatos ordenou ser-devolvido');
INSERT INTO verses VALUES (24254, 40, 27, 59, 'e tomando o corpo o José envolveu ele em linho pura');
INSERT INTO verses VALUES (24255, 40, 27, 60, 'e colocou ele em o novo dele sepulcro o qual escavou-na-rocha em o rocha e tendo-rolado-para pedra grande o porta o sepulcro partiu');
INSERT INTO verses VALUES (24256, 40, 27, 61, 'era porém ali Maria o Madalena e o outra Maria estando-sentadas diante-de o de-sepulcro');
INSERT INTO verses VALUES (24257, 40, 27, 62, 'o porém no-dia-seguinte a-qual é com o Preparação foram-reunidos o sumos-sacerdotes e o fariseus junto-a Pilatos');
INSERT INTO verses VALUES (24258, 40, 27, 63, 'dizendo Kyrie lembramo-nos que aquele o enganador disse ainda vivendo com três do-dia levanto-me');
INSERT INTO verses VALUES (24259, 40, 27, 64, 'ordena portanto ser-assegurado o sepulcro até o terceira do-dia não alguma-vez vindo o discípulos furtem ele e digam o povo Foi-levantado de o mortos e será o última engano pior o primeiro');
INSERT INTO verses VALUES (24260, 40, 27, 65, 'disse a-eles o Pilatos tendes guarda ide assegurai como sei');
INSERT INTO verses VALUES (24261, 40, 27, 66, 'o porém tendo-ido Asseguraram o sepulcro tendo-selado o pedra com o guarda');
INSERT INTO chapters VALUES (957, 40, 28, 20);
INSERT INTO verses VALUES (24262, 40, 28, 1, 'Tarde porém sábados o Amanhecendo para uma sábados veio Maria o Madalena e o outra Maria contemplar o sepulcro');
INSERT INTO verses VALUES (24263, 40, 28, 2, 'e eis terremoto aconteceu grande anjo pois do-Kyrios descendo de do-céu e aproximando-se rolou o pedra e sentava-se em-cima dele');
INSERT INTO verses VALUES (24264, 40, 28, 3, 'era porém o aparência dele como relâmpago e o veste dele branco como neve');
INSERT INTO verses VALUES (24265, 40, 28, 4, 'de porém o medo dele Foram-sacudidos o guardando e tornaram-se como mortos');
INSERT INTO verses VALUES (24266, 40, 28, 5, 'respondendo porém o anjo disse o mulheres não temei vós sei pois que Iesous o crucificado buscais');
INSERT INTO verses VALUES (24267, 40, 28, 6, 'não é aqui foi-ressuscitado pois assim-como disse vinde vede o lugar onde estava-posto');
INSERT INTO verses VALUES (24268, 40, 28, 7, 'e rapidamente tendo-ido dizei o discípulos dele que Foi-levantado de o mortos e eis vai-adiante vos para o Galileia ali ele vereis eis disseram a-vós');
INSERT INTO verses VALUES (24269, 40, 28, 8, 'e tendo-partido rapidamente de o sepulcro com medo e alegria grande correram anunciar o discípulos dele');
INSERT INTO verses VALUES (24270, 40, 28, 9, 'e eis Iesous encontrou elas dizendo Alegrai-vos o porém tendo-se-aproximado agarraram dele o pés e adoraram a ele');
INSERT INTO verses VALUES (24271, 40, 28, 10, 'então diz elas o Iesous não temei ide anunciai o aos-irmãos meu para que partam para o Galileia e-ali me verão');
INSERT INTO verses VALUES (24272, 40, 28, 11, 'Indo porém deles eis alguns o guarda vindo para o cidade anunciaram o sumos-sacerdotes todas-as-coisas o tendo-acontecido');
INSERT INTO verses VALUES (24273, 40, 28, 12, 'e tendo-sido-reunidos com o dos-anciãos conselho e tendo-tomado moedas-de-prata Suficientes deram o soldados');
INSERT INTO verses VALUES (24274, 40, 28, 13, 'dizendo Dizei que o discípulos dele da-noite vindo Roubaram ele nosso adormecendo');
INSERT INTO verses VALUES (24275, 40, 28, 14, 'e se seja-ouvido isto sobre o governador nós persuadiremos e vos livres-de-preocupação faremos');
INSERT INTO verses VALUES (24276, 40, 28, 15, 'o porém tendo-tomado moedas-de-prata fizeram como foram-ensinados e foi-divulgado o palavra este de-junto-de judeus até o hoje do-dia');
INSERT INTO verses VALUES (24277, 40, 28, 16, 'o porém onze discípulos foram para o Galileia para o monte do-qual Designou-para-si a-eles o Iesous');
INSERT INTO verses VALUES (24278, 40, 28, 17, 'e vendo ele adoraram o porém duvidaram');
INSERT INTO verses VALUES (24279, 40, 28, 18, 'e aproximando-se o Iesous falou a-eles dizendo foi-dado a-mim toda autoridade em no-céu e sobre o da-terra');
INSERT INTO verses VALUES (24280, 40, 28, 19, 'tendo-ido portanto fazei-discípulos todas-as-coisas o nações batizando eles para o nome o do-Pai e o do-Filho e o do-santo do-espírito');
INSERT INTO verses VALUES (24281, 40, 28, 20, 'ensinando eles guardar todas-as-coisas quanto ordenei a-vós e eis eu com vosso sou todas o do-dia até o consumação o eternidade');
INSERT INTO books VALUES (41, 'MRK', 'Marcos', 'NT', 16);
INSERT INTO chapters VALUES (958, 41, 1, 45);
INSERT INTO verses VALUES (24282, 41, 1, 1, 'princípio o evangelho Iesous de-Christos do-Filho de-Theos');
INSERT INTO verses VALUES (24283, 41, 1, 2, 'Assim-como está-escrito em o Isaías o a-profeta Eis envio o anjo meu antes-de face teu o qual preparará o caminho teu');
INSERT INTO verses VALUES (24284, 41, 1, 3, 'voz clamando em o deserto Preparai o caminho do-Kyrios retas fazei o caminhos dele');
INSERT INTO verses VALUES (24285, 41, 1, 4, 'aconteceu João o batizando em o deserto pregando batismo arrependimento para perdão pecados');
INSERT INTO verses VALUES (24286, 41, 1, 5, 'e saía junto-a ele toda o Judeia região e o Jerosolimitas todos e eram-batizados sob dele em o Jordão rio confessando o do-pecado deles');
INSERT INTO verses VALUES (24287, 41, 1, 6, 'e era o João tendo-sido-vestido cabelos camelo e cinto de-couro acerca-de o lombo dele e Comendo gafanhotos e mel silvestre');
INSERT INTO verses VALUES (24288, 41, 1, 7, 'e proclamava dizendo vem o mais-forte meu atrás meu o qual não sou digno tendo-se-inclinado abrir o correia o sandálias dele');
INSERT INTO verses VALUES (24289, 41, 1, 8, 'eu batizei vos água ele porém batizará vos Espírito no-santo');
INSERT INTO verses VALUES (24290, 41, 1, 9, 'e aconteceu em aqueles o dias veio Iesous de Nazaré o Galileia e foi-batizado para o Jordão sob João');
INSERT INTO verses VALUES (24291, 41, 1, 10, 'e imediatamente subindo de o água viu sendo-rasgados o céus e o espírito como pomba descendo para ele');
INSERT INTO verses VALUES (24292, 41, 1, 11, 'e voz aconteceu de o dos-céus tu és o filho meu o amado em a-ti agradei-me');
INSERT INTO verses VALUES (24293, 41, 1, 12, 'e imediatamente o espírito ele expulsa para o deserto');
INSERT INTO verses VALUES (24294, 41, 1, 13, 'e era em o deserto quarenta do-dia tentado sob o Satanás e era com o feras e o anjo serviam a ele');
INSERT INTO verses VALUES (24295, 41, 1, 14, 'e com o ser-entregue o João veio o Iesous para o Galileia pregando o evangelho o de-Theos');
INSERT INTO verses VALUES (24296, 41, 1, 15, 'e dizendo que Tem-sido-cumprido o tempo e aproximou-se o reino o de-Theos arrependei-vos e credes em o no-evangelho');
INSERT INTO verses VALUES (24297, 41, 1, 16, 'e passando de-junto-de o mar o Galileia viu Simão e André o irmão de-Simão lançando-rede em o mar eram pois pescadores');
INSERT INTO verses VALUES (24298, 41, 1, 17, 'e disse a-eles o Iesous vinde atrás meu e farei vos tornar-se pescadores dos-homens');
INSERT INTO verses VALUES (24299, 41, 1, 18, 'e imediatamente deixando o redes seguiram a ele');
INSERT INTO verses VALUES (24300, 41, 1, 19, 'e tendo-avançado pouco viu Tiago o o Zebedeu e João o irmão dele e eles em o no-barco restaurando o redes');
INSERT INTO verses VALUES (24301, 41, 1, 20, 'e imediatamente chamou eles e deixando o Pai deles Zebedeu em o no-barco com o assalariados foram atrás dele');
INSERT INTO verses VALUES (24302, 41, 1, 21, 'e adentram para Cafarnaum e imediatamente o nos-sábados entrando para o sinagoga ensinava');
INSERT INTO verses VALUES (24303, 41, 1, 22, 'e ficavam-espantados sobre o em-ensino dele era pois ensinando eles como autoridade tendo e não como o escribas');
INSERT INTO verses VALUES (24304, 41, 1, 23, 'e imediatamente era em o na-sinagoga deles homem em espírito impuro e clamou');
INSERT INTO verses VALUES (24305, 41, 1, 24, 'dizendo quê a-nós e te Iesous Nazareno vieste destruir nos sei te quem és o santo o de-Theos');
INSERT INTO verses VALUES (24306, 41, 1, 25, 'e repreendeu a ele o Iesous Cala-te e sai de dele');
INSERT INTO verses VALUES (24307, 41, 1, 26, 'e tendo-convulsionado ele o espírito o impuro e chamou voz grande saiu de dele');
INSERT INTO verses VALUES (24308, 41, 1, 27, 'e ficaram-atônitos todos de-modo-que debater eles dizendo quê é isto ensino nova segundo autoridade e o espíritos o impuros ordena e obedecem a ele');
INSERT INTO verses VALUES (24309, 41, 1, 28, 'e saiu o ouvido dele imediatamente por-toda-parte para toda o região-ao-redor o Galileia');
INSERT INTO verses VALUES (24310, 41, 1, 29, 'e imediatamente de o sinagoga saindo vieram para o casa de-Simão e André com de-Tiago e João');
INSERT INTO verses VALUES (24311, 41, 1, 30, 'o porém sogra de-Simão estava-deitado tendo-febre e imediatamente dizem a ele acerca-de dela');
INSERT INTO verses VALUES (24312, 41, 1, 31, 'e aproximando-se ressuscitou ela segurando o mão e deixou ela o febre e servia a-eles');
INSERT INTO verses VALUES (24313, 41, 1, 32, 'Tarde porém tendo-acontecido quando Pôs-se o sol traziam junto-a ele todos o mal tendo e o endemoninhados');
INSERT INTO verses VALUES (24314, 41, 1, 33, 'e era toda o cidade Tendo-sido-reunida junto-a o porta');
INSERT INTO verses VALUES (24315, 41, 1, 34, 'e curou a-muitos mal tendo diversas doenças e demônios muitas-coisas expulsou e não deixava falar o demônios que sei ele');
INSERT INTO verses VALUES (24316, 41, 1, 35, 'e de-manhã De-madrugada muito levantando-se saiu e partiu para deserto lugar e-ali orava');
INSERT INTO verses VALUES (24317, 41, 1, 36, 'e perseguiu ele Simão e o com dele');
INSERT INTO verses VALUES (24318, 41, 1, 37, 'e encontraram ele e dizem a ele que todos buscam te');
INSERT INTO verses VALUES (24319, 41, 1, 38, 'e diz a-eles Vamos em-outro-lugar para o Seguintes vilas para que e ali proclamarei para isto pois saíram');
INSERT INTO verses VALUES (24320, 41, 1, 39, 'e veio pregando para o sinagogas deles para toda o Galileia e o demônios lançando-fora');
INSERT INTO verses VALUES (24321, 41, 1, 40, 'e vem junto-a ele leproso exortando ele e ajoelhando dizendo a ele que se queiras podes me purificar');
INSERT INTO verses VALUES (24322, 41, 1, 41, 'e compadecido estendendo o mão dele tocou e diz a ele quero sê-purificado');
INSERT INTO verses VALUES (24323, 41, 1, 42, 'e imediatamente partiu de dele o lepra e foi-purificado');
INSERT INTO verses VALUES (24324, 41, 1, 43, 'e tendo-repreendido-severamente a ele imediatamente expulsou ele');
INSERT INTO verses VALUES (24325, 41, 1, 44, 'e diz a ele veja a-ninguém nada digas mas vai a-ti-mesmo mostra o sacerdote e oferece acerca-de o purificação teu o qual ordenou Moisés para testemunho a-eles');
INSERT INTO verses VALUES (24326, 41, 1, 45, 'o porém saindo começou proclamar muitas-coisas e espalhar o palavra de-modo-que não-mais ele poder manifestamente para cidade entrar mas fora sobre desertos lugares era e vinham junto-a ele de-todo-lado');
INSERT INTO chapters VALUES (959, 41, 2, 28);
INSERT INTO verses VALUES (24327, 41, 2, 1, 'e entrando novamente para Cafarnaum através-de dias foi-ouvido que em na-casa é');
INSERT INTO verses VALUES (24328, 41, 2, 2, 'e foram-reunidos muitos de-modo-que não-mais ter-espaço nem o junto-a o porta e falava a-eles o palavra');
INSERT INTO verses VALUES (24329, 41, 2, 3, 'e vêm trazendo junto-a ele paralítico sendo-levantado sob quatro');
INSERT INTO verses VALUES (24330, 41, 2, 4, 'e não podendo oferecer a ele através-de o multidão destelharam o telhado onde era e tendo-cavado abaixam o maca onde o paralítico estava-deitado');
INSERT INTO verses VALUES (24331, 41, 2, 5, 'e vendo o Iesous o fé deles diz o paralítico filho são-perdoados teu o pecados');
INSERT INTO verses VALUES (24332, 41, 2, 6, 'eram e/mas alguns o dos-escribas ali sentados e raciocinando em o corações deles');
INSERT INTO verses VALUES (24333, 41, 2, 7, 'quê este assim fala blasfema quem pode perdoar do-pecado se não um o Theos');
INSERT INTO verses VALUES (24334, 41, 2, 8, 'e imediatamente reconhecendo o Iesous o espírito dele que assim raciocinam em si-mesmos diz a-eles quê estas-coisas raciocinais em o corações vosso');
INSERT INTO verses VALUES (24335, 41, 2, 9, 'quê é mais-fácil dizer o paralítico São-perdoados teu o pecados ou dizer Levanta-te e levanta o maca teu e anda');
INSERT INTO verses VALUES (24336, 41, 2, 10, 'para que porém sei que autoridade tem o Filho o do-homem perdoar do-pecado sobre o da-terra diz o paralítico');
INSERT INTO verses VALUES (24337, 41, 2, 11, 'a-ti digo levanta-te levanta o maca teu e vai para o casa teu');
INSERT INTO verses VALUES (24338, 41, 2, 12, 'e foi-ressuscitado e imediatamente levantando o maca saiu diante todos de-modo-que ficar-fora-de-si todos e glorificar o Theos dizendo que assim nunca vimos');
INSERT INTO verses VALUES (24339, 41, 2, 13, 'e saiu novamente de-junto-de o mar e todo o multidão vinha junto-a ele e ensinava eles');
INSERT INTO verses VALUES (24340, 41, 2, 14, 'e passando viu Levi o o Alfeu sentado sobre o coletoria e diz a ele Segue a-mim e levantando-se seguiu a ele');
INSERT INTO verses VALUES (24341, 41, 2, 15, 'e torna-se estar-reclinado ele em o casa dele e muitos cobradores-de-impostos e pecadores reclinavam-se-à-mesa-junto o Iesous e o discípulos dele eram pois muitos e seguiam a ele');
INSERT INTO verses VALUES (24342, 41, 2, 16, 'e o escribas o fariseus vendo que come com o dos-pecadores e cobradores-de-impostos diziam o discípulos dele que com o cobradores-de-impostos e dos-pecadores come');
INSERT INTO verses VALUES (24343, 41, 2, 17, 'e ouvindo o Iesous diz a-eles não necessidade têm o sendo-fortes médico mas o mal tendo não vieram chamar justos mas pecadores');
INSERT INTO verses VALUES (24344, 41, 2, 18, 'e eram o discípulos João e o fariseus jejuando e vêm e dizem a ele através-de quê o discípulos João e o discípulos o fariseus jejuam o porém a-ti discípulos não jejuam');
INSERT INTO verses VALUES (24345, 41, 2, 19, 'e disse a-eles o Iesous não podem o filhos o câmara-nupcial em o qual o noivo com deles é jejuar quanto tempo têm o noivo com deles não podem jejuar');
INSERT INTO verses VALUES (24346, 41, 2, 20, 'virão porém dias quando seja-tirado de deles o noivo e então jejuarão em naquela o dia');
INSERT INTO verses VALUES (24347, 41, 2, 21, 'ninguém remendo pano não-pisoado costura-sobre sobre manto velho se porém não levanta o plenitude de dele o novo o velho e pior divisão torna-se');
INSERT INTO verses VALUES (24348, 41, 2, 22, 'e ninguém lança vinho novo para odres velhos se porém não romperá o vinho o odres e o vinho perece e o odres mas vinho novo para odres novos');
INSERT INTO verses VALUES (24349, 41, 2, 23, 'e aconteceu ele em o nos-sábados passar-ao-lado através-de o searas e o discípulos dele começaram caminho fazer arrancando o espigas');
INSERT INTO verses VALUES (24350, 41, 2, 24, 'e o fariseus diziam a ele Vê quê fazem o nos-sábados o qual não é-lícito');
INSERT INTO verses VALUES (24351, 41, 2, 25, 'e diz a-eles Nunca lestes quê fez Davi quando necessidade teve e teve-fome ele e o com dele');
INSERT INTO verses VALUES (24352, 41, 2, 26, 'como entrou para o casa o de-Theos sobre Abiatar do-sumo-sacerdote e o pães o propósito comeu o qual não é-lícito comer se não o sacerdotes e deu e o com a ele estando');
INSERT INTO verses VALUES (24353, 41, 2, 27, 'e dizia a-eles o sábado através-de o homem aconteceu e não o homem através-de o sábado');
INSERT INTO verses VALUES (24354, 41, 2, 28, 'de-modo-que senhor é o Filho o do-homem e o do-sábado');
INSERT INTO chapters VALUES (960, 41, 3, 35);
INSERT INTO verses VALUES (24355, 41, 3, 1, 'e entrou novamente para sinagoga e era ali homem tendo-sido-secada tendo o mão');
INSERT INTO verses VALUES (24356, 41, 3, 2, 'e observavam ele se o nos-sábados curará ele para que acusem dele');
INSERT INTO verses VALUES (24357, 41, 3, 3, 'e diz o ser-humano o o mão tendo seca Levanta-te para o meio');
INSERT INTO verses VALUES (24358, 41, 3, 4, 'e diz a-eles É-permitido o nos-sábados bom fazer ou fazer-mal alma salvar ou matar o porém calavam-se');
INSERT INTO verses VALUES (24359, 41, 3, 5, 'e olhando-ao-redor eles com ira entristecendo-se-juntamente sobre o em-endurecimento o do-coração deles diz o ao-homem Estende o mão e estendeu e foi-restaurado o mão dele');
INSERT INTO verses VALUES (24360, 41, 3, 6, 'e saindo o fariseus imediatamente com o herodianos conselho davam segundo dele para-que ele destruam');
INSERT INTO verses VALUES (24361, 41, 3, 7, 'e o Iesous com o discípulos dele retirou-se junto-a o mar e muito multidão de o Galileia seguiu e de o Judeia');
INSERT INTO verses VALUES (24362, 41, 3, 8, 'e de Jerusalém e de o Idumeia e além o Jordão e acerca-de Tiro e Sidom multidão muito ouvindo quanto faz vieram junto-a ele');
INSERT INTO verses VALUES (24363, 41, 3, 9, 'e disse o discípulos dele para que barquinho persevere a ele através-de o multidão para que não aflinjam ele');
INSERT INTO verses VALUES (24364, 41, 3, 10, 'a-muitos pois curou de-modo-que cair-sobre a ele para que dele toquem quanto tinham açoites');
INSERT INTO verses VALUES (24365, 41, 3, 11, 'e o espíritos o imundos quando ele observavam caíam-diante a ele e clamavam dizendo que tu és o Filho o de-Theos');
INSERT INTO verses VALUES (24366, 41, 3, 12, 'e muitas-coisas repreendia a-eles para que não ele manifesto façam');
INSERT INTO verses VALUES (24367, 41, 3, 13, 'e sobe para o monte e chama-a-si o qual queria ele e foram junto-a ele');
INSERT INTO verses VALUES (24368, 41, 3, 14, 'e fez doze para que sejam com dele e para que envie eles proclamar');
INSERT INTO verses VALUES (24369, 41, 3, 15, 'e ter autoridade expulsar o demônios');
INSERT INTO verses VALUES (24370, 41, 3, 16, 'e fez o doze e pôs-sobre nome o Simão Pedro');
INSERT INTO verses VALUES (24371, 41, 3, 17, 'e Tiago o o Zebedeu e João o irmão o de-Tiago e pôs-sobre a-eles nome Boanerges o qual é filhos trovão');
INSERT INTO verses VALUES (24372, 41, 3, 18, 'e André e Filipe e Bartolomeu e Mateus e Tomé e Tiago o o Alfeu e Tadeu e Simão o Cananeu');
INSERT INTO verses VALUES (24373, 41, 3, 19, 'e Judas Iscariotes o qual e entregou ele');
INSERT INTO verses VALUES (24374, 41, 3, 20, 'e vem para casa e reúne-se novamente o multidão de-modo-que não poder eles nem pão comer');
INSERT INTO verses VALUES (24375, 41, 3, 21, 'e ouvindo o de dele saíram agarrar ele diziam pois que ficou-fora-de-si');
INSERT INTO verses VALUES (24376, 41, 3, 22, 'e o escribas o de Jerusalém tendo-descido diziam que Belzebu tem e que em o governante o demônios expulsa o demônios');
INSERT INTO verses VALUES (24377, 41, 3, 23, 'e tendo-chamado eles em em-parábolas dizia a-eles como pode Satanás Satanás expulsar');
INSERT INTO verses VALUES (24378, 41, 3, 24, 'e se reino sobre a-si-mesma seja-dividida não pode ficar-de-pé o reino aquela');
INSERT INTO verses VALUES (24379, 41, 3, 25, 'e se casa sobre a-si-mesma seja-dividida não poderá o casa aquela estar-de-pé');
INSERT INTO verses VALUES (24380, 41, 3, 26, 'e se o Satanás levantou-se sobre si-mesmo e foi-dividido não pode estar-de-pé mas fim tem');
INSERT INTO verses VALUES (24381, 41, 3, 27, 'mas não pode ninguém para o casa o forte entrando o vasos dele saquear se não primeiro o forte amarre e então o casa dele saqueará');
INSERT INTO verses VALUES (24382, 41, 3, 28, 'Amém digo a-vós que todas-as-coisas será-perdoado o filhos o dos-homens o pecados e o blasfêmias quanto se blasfemem');
INSERT INTO verses VALUES (24383, 41, 3, 29, 'o qual e/mas partícula-condicional blasfeme para o espírito o santo não tem perdão para o eternidade mas Réu é eterno pecado');
INSERT INTO verses VALUES (24384, 41, 3, 30, 'que diziam espírito impuro tem');
INSERT INTO verses VALUES (24385, 41, 3, 31, 'e vêm o mãe dele e o irmãos dele e fora permanecendo-firmes enviaram junto-a ele chamando ele');
INSERT INTO verses VALUES (24386, 41, 3, 32, 'e sentava-se acerca-de ele multidão e dizem a ele Eis o mãe teu e o irmãos teu e o irmãs teu fora buscam te');
INSERT INTO verses VALUES (24387, 41, 3, 33, 'e respondendo a-eles diz Quem é o mãe meu e o irmãos');
INSERT INTO verses VALUES (24388, 41, 3, 34, 'e olhando-ao-redor o acerca-de ele ao-redor sentados diz Vê o mãe meu e o irmãos meu');
INSERT INTO verses VALUES (24389, 41, 3, 35, 'o qual partícula-condicional faça o vontade o de-Theos este irmão meu e irmã e mãe é');
INSERT INTO chapters VALUES (961, 41, 4, 41);
INSERT INTO verses VALUES (24390, 41, 4, 1, 'e novamente começou ensinar de-junto-de o mar e é-reunido junto-a ele multidão muito-grande de-modo-que ele para barco tendo-embarcado sentar em o mar e todo o multidão junto-a o mar sobre o da-terra eram');
INSERT INTO verses VALUES (24391, 41, 4, 2, 'e ensinava eles em em-parábolas muitas-coisas e dizia a-eles em o em-ensino dele');
INSERT INTO verses VALUES (24392, 41, 4, 3, 'Ouvi eis saiu o o-que-semeia semear');
INSERT INTO verses VALUES (24393, 41, 4, 4, 'e aconteceu em o semear o qual por-um-lado caiu de-junto-de o caminho e veio o aves e devorou isso');
INSERT INTO verses VALUES (24394, 41, 4, 5, 'e outro caiu sobre o pedregoso onde não tinha terra muita e imediatamente brotou através-de o não ter profundidade da-terra');
INSERT INTO verses VALUES (24395, 41, 4, 6, 'e quando nasceu o sol foi-queimado e através-de o não ter raiz secou');
INSERT INTO verses VALUES (24396, 41, 4, 7, 'e outro caiu para o espinhos e subiram o espinhos e sufocaram isso e fruto não deu');
INSERT INTO verses VALUES (24397, 41, 4, 8, 'e outras-coisas caiu para o terra o boa e dava fruto subindo e crescendo e Trazia para trinta e em sessenta e em cem');
INSERT INTO verses VALUES (24398, 41, 4, 9, 'e dizia o qual tem ouvidos ouvir ouça');
INSERT INTO verses VALUES (24399, 41, 4, 10, 'e quando aconteceu segundo somente perguntavam ele o acerca-de ele com o doze o parábolas');
INSERT INTO verses VALUES (24400, 41, 4, 11, 'e dizia a-eles a-vós o mistério foi-dado o do-reino o de-Theos àqueles porém o fora em em-parábolas o todas-as-coisas torna-se');
INSERT INTO verses VALUES (24401, 41, 4, 12, 'para que vendo vejam e não vejam e ouvindo ouçam e não compreendam não alguma-vez convertam-se e seja-perdoado a-eles');
INSERT INTO verses VALUES (24402, 41, 4, 13, 'e diz a-eles não sei o parábola esta e como todas o parábolas conhecereis');
INSERT INTO verses VALUES (24403, 41, 4, 14, 'o o-que-semeia o palavra semeia');
INSERT INTO verses VALUES (24404, 41, 4, 15, 'estes e/mas são o de-junto-de o caminho onde é-semeado o palavra e quando ouçam imediatamente vem o Satanás e levanta o palavra o tendo-sido-semeado para eles');
INSERT INTO verses VALUES (24405, 41, 4, 16, 'e estes são semelhantemente o sobre o pedregosos sendo-semeados o qual quando ouçam o palavra imediatamente com alegria recebem ele');
INSERT INTO verses VALUES (24406, 41, 4, 17, 'e não têm raiz em si-mesmos mas temporários são então tendo-acontecido tribulação ou perseguição através-de o palavra imediatamente são-escandalizados');
INSERT INTO verses VALUES (24407, 41, 4, 18, 'e outros são o para o espinhos sendo-semeados estes são o o palavra ouvindo');
INSERT INTO verses VALUES (24408, 41, 4, 19, 'e o ansiedades o eternidade e o engano o riqueza e o acerca-de o restantes desejos entrando sufocam o palavra e infrutífero torna-se');
INSERT INTO verses VALUES (24409, 41, 4, 20, 'e aqueles são o sobre o terra o boa tendo-sido-semeados os-quais ouvem o palavra e aceitam e frutificam em trinta e em sessenta e em cem');
INSERT INTO verses VALUES (24410, 41, 4, 21, 'e dizia a-eles que Acaso vem o lâmpada para que sob o alqueire seja-posto ou sob o cama não para que sobre o candelabro seja-posto');
INSERT INTO verses VALUES (24411, 41, 4, 22, 'não pois é algo oculto se não para que seja-manifestada nem aconteceu oculto mas para que venha para manifesto');
INSERT INTO verses VALUES (24412, 41, 4, 23, 'se alguém tem ouvidos ouvir ouça');
INSERT INTO verses VALUES (24413, 41, 4, 24, 'e dizia a-eles Vede quê ouvi em o qual medida medis será-medido a-vós e será-acrescentado a-vós');
INSERT INTO verses VALUES (24414, 41, 4, 25, 'o qual pois tem será-dado a ele e o qual não tem e o qual tem será-tirado de dele');
INSERT INTO verses VALUES (24415, 41, 4, 26, 'e dizia assim é o reino o de-Theos como homem lance o semente sobre o da-terra');
INSERT INTO verses VALUES (24416, 41, 4, 27, 'e durma e tenha-sido-levantado noite e dia e o semente brota e cresça como não sei ele');
INSERT INTO verses VALUES (24417, 41, 4, 28, 'por-si-mesma o terra frutifica primeiro erva disse espiga disse cheio trigo em o espiga');
INSERT INTO verses VALUES (24418, 41, 4, 29, 'quando porém entregue o fruto imediatamente envia o foice que tem-estado-de-pé o ceifa');
INSERT INTO verses VALUES (24419, 41, 4, 30, 'e dizia como assemelharemos o reino o de-Theos ou em a-quem ela parábola coloquemos');
INSERT INTO verses VALUES (24420, 41, 4, 31, 'como grão mostarda o qual quando seja-semeado sobre o da-terra menor sendo todos o sementes o sobre o da-terra');
INSERT INTO verses VALUES (24421, 41, 4, 32, 'e quando seja-semeado sobe e torna-se maior todos o hortaliças e faz ramos grandes de-modo-que poder sob o sombra dele o aves o do-céu aninhar');
INSERT INTO verses VALUES (24422, 41, 4, 33, 'e tais em-parábolas muitas falava a-eles o palavra assim-como podiam ouvir');
INSERT INTO verses VALUES (24423, 41, 4, 34, 'sem porém parábola não falava a-eles segundo própria porém o próprios discípulos resolvia todas-as-coisas');
INSERT INTO verses VALUES (24424, 41, 4, 35, 'e diz a-eles em naquela o dia tarde tendo-acontecido Passemos-ao-outro-lado para o além');
INSERT INTO verses VALUES (24425, 41, 4, 36, 'e deixando o multidão tomam ele como era em o no-barco e outras-coisas navios era com dele');
INSERT INTO verses VALUES (24426, 41, 4, 37, 'e torna-se tempestade grande vento e o ondas lançava-sobre para o barco de-modo-que já ser-enchido o barco');
INSERT INTO verses VALUES (24427, 41, 4, 38, 'e ele era em o em-popa sobre o travesseiro dormindo e levantam ele e dizem a ele Mestre não importa a-ti que perecemos');
INSERT INTO verses VALUES (24428, 41, 4, 39, 'e tendo-sido-despertado repreendeu o vento e disse o mar Cala-te sê-amordaçado e cessou o vento e aconteceu calmaria grande');
INSERT INTO verses VALUES (24429, 41, 4, 40, 'e disse a-eles quê covardes sois assim como não tendes fé');
INSERT INTO verses VALUES (24430, 41, 4, 41, 'e temeram medo grande e diziam junto-a uns-aos-outros Quem então este é que e o vento e o mar obedece a ele');
INSERT INTO chapters VALUES (962, 41, 5, 43);
INSERT INTO verses VALUES (24431, 41, 5, 1, 'e vieram para o além o do-mar para o região o Gerasenos');
INSERT INTO verses VALUES (24432, 41, 5, 2, 'e tendo-saído dele de o do-barco imediatamente encontrou a ele de o sepulcros homem em espírito impuro');
INSERT INTO verses VALUES (24433, 41, 5, 3, 'o qual o habitação tinha em o sepulcros e nem cadeia não-mais ninguém podia ele amarrar');
INSERT INTO verses VALUES (24434, 41, 5, 4, 'através-de o ele muitas-vezes grilhões e cadeias ter-sido-amarrado e ter-sido-despedaçado sob dele o cadeias e o grilhões ter-sido-quebrado e ninguém era-capaz ele domar');
INSERT INTO verses VALUES (24435, 41, 5, 5, 'e através-de de-todo da-noite e do-dia em o sepulcros e em o montes era clamando e cortando si-mesmo pedras');
INSERT INTO verses VALUES (24436, 41, 5, 6, 'e vendo o Iesous de de-longe correu e adorou ele');
INSERT INTO verses VALUES (24437, 41, 5, 7, 'e clamando com-voz grande diz quê mim e a-ti Iesous Filho o de-Theos o Altíssimo conjuro te o Theos não me atormentes');
INSERT INTO verses VALUES (24438, 41, 5, 8, 'dizia pois a ele Sai o espírito o impuro de o do-homem');
INSERT INTO verses VALUES (24439, 41, 5, 9, 'e perguntava ele quê nome a-ti e diz a ele Legião nome a-mim que muitos somos');
INSERT INTO verses VALUES (24440, 41, 5, 10, 'e suplicava ele muitas-coisas para que não eles envie fora o região');
INSERT INTO verses VALUES (24441, 41, 5, 11, 'era porém ali junto-a o no-monte manada porcos grande sendo-apascentada');
INSERT INTO verses VALUES (24442, 41, 5, 12, 'e suplicaram ele dizendo envia nos para o porcos para que para eles entremos');
INSERT INTO verses VALUES (24443, 41, 5, 13, 'e permitiu a-eles e tendo-saído o espíritos o imundos entraram para o porcos e precipitou-se o manada segundo o precipício para o mar como dois-mil e Eram-afogados em o mar');
INSERT INTO verses VALUES (24444, 41, 5, 14, 'e o apascentando eles fugiram e anunciaram para o cidade e para o campos e vieram ver quê é o tendo-acontecido');
INSERT INTO verses VALUES (24445, 41, 5, 15, 'e vêm junto-a o Iesous e contemplam o sendo-endemoninhado sentado tendo-sido-vestido e sendo-sóbrio-de-mente o Tendo-tido o legião e temeram');
INSERT INTO verses VALUES (24446, 41, 5, 16, 'e narraram a-eles o vendo como aconteceu o sendo-endemoninhado e acerca-de o porcos');
INSERT INTO verses VALUES (24447, 41, 5, 17, 'e começaram exortar ele ir-embora de o fronteiras deles');
INSERT INTO verses VALUES (24448, 41, 5, 18, 'e embarcando dele para o barco suplicava ele o tendo-sido-endemoninhado para que com dele seja');
INSERT INTO verses VALUES (24449, 41, 5, 19, 'e não deixou ele mas diz a ele Vai para o casa teu junto-a o teus e anuncia a-eles quanto o Kyrios a-ti tem-feito e teve-misericórdia te');
INSERT INTO verses VALUES (24450, 41, 5, 20, 'e partiu e começou proclamar em o Decápolis quanto fez a ele o Iesous e todos admiravam-se');
INSERT INTO verses VALUES (24451, 41, 5, 21, 'e tendo-atravessado o Iesous em o no-barco novamente para o além reuniu-se multidão muito sobre ele e era de-junto-de o mar');
INSERT INTO verses VALUES (24452, 41, 5, 22, 'e vem um o chefes-da-sinagoga em-nome Jairo e vendo ele cai junto-a o pés dele');
INSERT INTO verses VALUES (24453, 41, 5, 23, 'e consola ele muitas-coisas dizendo que o filhinha meu Extremamente tem para que vindo imponhas o mãos a-ela para que seja-salvo e viva');
INSERT INTO verses VALUES (24454, 41, 5, 24, 'e partiu com dele e seguia a ele multidão muito e comprimiam ele');
INSERT INTO verses VALUES (24455, 41, 5, 25, 'e mulher sendo em livrará sangue doze anos');
INSERT INTO verses VALUES (24456, 41, 5, 26, 'e muitas-coisas tendo-sofrido sob muitos Médicos e tendo-gastado o de-junto-de dela todas-as-coisas e nada Tendo-sido-aproveitada mas mais para o pior tendo-vindo');
INSERT INTO verses VALUES (24457, 41, 5, 27, 'tendo-ouvido o acerca-de o Iesous tendo-vindo em o à-multidão atrás tocou o manto dele');
INSERT INTO verses VALUES (24458, 41, 5, 28, 'dizia pois que se toque e-se o vestes dele serei-salvo');
INSERT INTO verses VALUES (24459, 41, 5, 29, 'e imediatamente secou o fonte o sangue dela e conheceu o corpo que cura de o açoite');
INSERT INTO verses VALUES (24460, 41, 5, 30, 'e imediatamente o Iesous reconhecendo em si-mesmo o de dele poder tendo-saído tendo-se-voltado em o à-multidão dizia Quem meu tocou o vestes');
INSERT INTO verses VALUES (24461, 41, 5, 31, 'e diziam a ele o discípulos dele vês o multidão comprimindo te e dizes Quem meu tocou');
INSERT INTO verses VALUES (24462, 41, 5, 32, 'e olhava-ao-redor ver o isto tendo-feito');
INSERT INTO verses VALUES (24463, 41, 5, 33, 'o porém mulher tendo-temido e tremendo sei o qual aconteceu a-ela veio e prostrou-se a ele e disse a ele toda o verdade');
INSERT INTO verses VALUES (24464, 41, 5, 34, 'o porém disse a-ela Filha o fé teu tem-salvo te vai para paz e sê são de o açoite teu');
INSERT INTO verses VALUES (24465, 41, 5, 35, 'ainda dele falando vêm de o chefe-da-sinagoga dizendo que o filha teu morreu quê ainda incomodas o mestre');
INSERT INTO verses VALUES (24466, 41, 5, 36, 'o porém Iesous tendo-desobedecido o palavra sendo-falado diz o chefe-da-sinagoga não temas somente crê');
INSERT INTO verses VALUES (24467, 41, 5, 37, 'e não deixou a-ninguém com dele seguir-junto se não o Pedro e Tiago e João o irmão de-Tiago');
INSERT INTO verses VALUES (24468, 41, 5, 38, 'e vêm para o casa o chefe-da-sinagoga e contempla tumulto e chorando e uivando muitas-coisas');
INSERT INTO verses VALUES (24469, 41, 5, 39, 'e entrando diz a-eles quê perturbai-vos e chorai o criança não morreu mas dorme');
INSERT INTO verses VALUES (24470, 41, 5, 40, 'e riam-se dele ele porém tendo-expulsado todos toma-consigo o Pai o criança e o mãe e o com dele e entra onde era o criança');
INSERT INTO verses VALUES (24471, 41, 5, 41, 'e segurando o da-mão o criança diz a-ela Talitá levanta-te o qual é sendo-traduzido o menina a-ti digo levanta-te');
INSERT INTO verses VALUES (24472, 41, 5, 42, 'e imediatamente levantou-se o menina e andava era pois anos doze e ficaram-fora-de-si imediatamente espanto grande');
INSERT INTO verses VALUES (24473, 41, 5, 43, 'e ordenou-severamente a-eles muitas-coisas para que ninguém conheça isto e disse ser-dado a-ela comer');
INSERT INTO chapters VALUES (963, 41, 6, 56);
INSERT INTO verses VALUES (24474, 41, 6, 1, 'e saiu dali e vem para o pátria dele e seguem a ele o discípulos dele');
INSERT INTO verses VALUES (24475, 41, 6, 2, 'e tendo-acontecido do-sábado começou ensinar em o na-sinagoga e o muitos ouvindo ficavam-espantados dizendo de-onde neste estas-coisas e quem o sabedoria o tendo-sido-dada neste e o poderes tais através-de o mãos dele acontecendo');
INSERT INTO verses VALUES (24476, 41, 6, 3, 'não este é o carpinteiro o Filho o Maria e irmão de-Tiago e José e Judá e de-Simão e não são o irmãs dele aqui junto-a nos e eram-escandalizados em a ele');
INSERT INTO verses VALUES (24477, 41, 6, 4, 'e dizia a-eles o Iesous que não é profeta sem-honra se não em o pátria dele e em o parentes dele e em o casa dele');
INSERT INTO verses VALUES (24478, 41, 6, 5, 'e não podia ali fazer nenhuma poder se não poucos enfermos pondo-sobre o mãos curou');
INSERT INTO verses VALUES (24479, 41, 6, 6, 'e admirou-se através-de o incredulidade deles e percorria o aldeias ao-redor ensinando');
INSERT INTO verses VALUES (24480, 41, 6, 7, 'e chama-a-si o doze e começou eles enviar dois dois e dava a-eles autoridade o espíritos o impuros');
INSERT INTO verses VALUES (24481, 41, 6, 8, 'e ordenou a-eles para que nada levantem para caminho se não vara somente não pão não alforje não para o cinto bronze');
INSERT INTO verses VALUES (24482, 41, 6, 9, 'mas Tendo-calçado sandálias e não vistais dois túnicas');
INSERT INTO verses VALUES (24483, 41, 6, 10, 'e dizia a-eles onde se entreis para casa ali permanecei até partícula-condicional saiais dali');
INSERT INTO verses VALUES (24484, 41, 6, 11, 'e o qual partícula-condicional lugar não receba vos nem ouçam vosso saindo dali sacudi o pó o debaixo o pés vosso para testemunho a-eles');
INSERT INTO verses VALUES (24485, 41, 6, 12, 'e saindo proclamaram para que arrependam-se');
INSERT INTO verses VALUES (24486, 41, 6, 13, 'e demônios muitas-coisas expulsavam e Ungiam azeite a-muitos enfermos e curavam');
INSERT INTO verses VALUES (24487, 41, 6, 14, 'e ouviu o rei Herodes manifesto pois aconteceu o nome dele e diziam que João o Batizando foi-levantado de mortos e através-de isto operam o poderes em a ele');
INSERT INTO verses VALUES (24488, 41, 6, 15, 'outros porém diziam que Elias é outros porém diziam que profeta como um o profetas');
INSERT INTO verses VALUES (24489, 41, 6, 16, 'ouvindo porém o Herodes dizia o qual eu decapitei João este foi-ressuscitado');
INSERT INTO verses VALUES (24490, 41, 6, 17, 'ele pois o Herodes enviando prendeu o João e amarrou ele em na-prisão através-de Herodíade o mulher Filipe o do-irmão dele que ela casou');
INSERT INTO verses VALUES (24491, 41, 6, 18, 'dizia pois o João o Herodes que não é-lícito a-ti ter o mulher o do-irmão teu');
INSERT INTO verses VALUES (24492, 41, 6, 19, 'o porém Herodias guardava-rancor a ele e queria ele matar e não podia');
INSERT INTO verses VALUES (24493, 41, 6, 20, 'o pois Herodes Temia o João sei ele homem justo e santo e guardava-junto ele e ouvindo dele muitas-coisas estava-perplexo e prazerosamente dele ouvia');
INSERT INTO verses VALUES (24494, 41, 6, 21, 'e tendo-acontecido do-dia oportuno quando Herodes o aniversário dele ceia fez o grandes-homens dele e o comandantes-de-mil e o primeiro o Galileia');
INSERT INTO verses VALUES (24495, 41, 6, 22, 'e tendo-entrado o filha dela o Herodíades e tendo-dançado agradou o Herodes e o reclinando-se-à-mesa-com o porém rei disse o menina Pede me o qual se queiras e darei a-ti');
INSERT INTO verses VALUES (24496, 41, 6, 23, 'e jurou a-ela que se me peças darei a-ti até Metade o do-reino meu');
INSERT INTO verses VALUES (24497, 41, 6, 24, 'e tendo-saído disse o mãe dela quê peça o porém disse o cabeça João o Batizando');
INSERT INTO verses VALUES (24498, 41, 6, 25, 'e tendo-entrado imediatamente com diligência junto-a o rei pediu dizendo quero para que imediatamente dês a-mim sobre prato o cabeça João o Batista');
INSERT INTO verses VALUES (24499, 41, 6, 26, 'e profundamente-triste tendo-se-tornado o rei através-de o juramentos e o reclinados não quis anular ela');
INSERT INTO verses VALUES (24500, 41, 6, 27, 'e imediatamente enviando o rei guarda-executor ordenou trazer o cabeça dele');
INSERT INTO verses VALUES (24501, 41, 6, 28, 'e partindo decapitou ele em o na-prisão e trouxe o cabeça dele sobre prato e deu ela o menina e o menina deu ela o mãe dela');
INSERT INTO verses VALUES (24502, 41, 6, 29, 'e ouvindo o discípulos dele vieram e levantaram o cadáver dele e puseram ele em sepulcro');
INSERT INTO verses VALUES (24503, 41, 6, 30, 'e reúnem-se o apóstolos junto-a o Iesous e anunciaram a ele todas-as-coisas quanto fizeram e quanto ensinaram');
INSERT INTO verses VALUES (24504, 41, 6, 31, 'e diz a-eles vinde vós eles-mesmos segundo própria para deserto lugar e descansai pouco eram pois o vindos e o indo muitos e nem comer tinham-oportunidade');
INSERT INTO verses VALUES (24505, 41, 6, 32, 'e foram em o no-barco para Deserto lugar segundo própria');
INSERT INTO verses VALUES (24506, 41, 6, 33, 'e vi eles indo e reconheceram muitos e a-pé de todas o cidades correram-junto ali e foram-adiante eles');
INSERT INTO verses VALUES (24507, 41, 6, 34, 'e saindo viu muito multidão e compadeceu-se sobre eles que eram como ovelhas não tendo pastor e começou ensinar eles muitas-coisas');
INSERT INTO verses VALUES (24508, 41, 6, 35, 'e já hora muita tendo-acontecido aproximando-se a ele o discípulos dele diziam que Deserta é o lugar e já hora muita');
INSERT INTO verses VALUES (24509, 41, 6, 36, 'liberta eles para que tendo-ido-embora para o ao-redor campos e aldeias comprem si-mesmos quê comam');
INSERT INTO verses VALUES (24510, 41, 6, 37, 'o porém respondendo disse a-eles dai a-eles vós comer e dizem a ele Tendo-partido compremos denários duzentos pães e demos a-eles comer');
INSERT INTO verses VALUES (24511, 41, 6, 38, 'o porém diz a-eles Quantos tendes pães ide vede e conhecendo dizem cinco e dois peixes');
INSERT INTO verses VALUES (24512, 41, 6, 39, 'e ordenou a-eles ser-reclinado todos grupos-de-banquete grupos-de-banquete sobre o verde erva');
INSERT INTO verses VALUES (24513, 41, 6, 40, 'e reclinaram-se canteiros canteiros segundo cem e segundo cinquenta');
INSERT INTO verses VALUES (24514, 41, 6, 41, 'e tomando o cinco pães e o dois peixes olhando-para-cima para o céu abençoou e partiu o pães e dava o discípulos para que confiem a-eles e o dois peixes dividiu todos');
INSERT INTO verses VALUES (24515, 41, 6, 42, 'e comeram todos e fartaram-se');
INSERT INTO verses VALUES (24516, 41, 6, 43, 'e levantaram pedaços doze cestos plenitudes e de o peixes');
INSERT INTO verses VALUES (24517, 41, 6, 44, 'e eram o tendo-comido o pães cinco-mil homens');
INSERT INTO verses VALUES (24518, 41, 6, 45, 'e imediatamente compeliu o discípulos dele embarcar para o barco e conduzir-adiante para o além junto-a Betsaida até ele solta o multidão');
INSERT INTO verses VALUES (24519, 41, 6, 46, 'e despedindo-se a-eles partiu para o monte orar');
INSERT INTO verses VALUES (24520, 41, 6, 47, 'e tarde tendo-acontecido era o barco em no-meio o do-mar e ele só sobre o da-terra');
INSERT INTO verses VALUES (24521, 41, 6, 48, 'e vendo eles sendo-atormentados em o remar era pois o vento contrário a-eles acerca-de quarta prisão o da-noite vem junto-a eles caminhando sobre o do-mar e queria passar eles');
INSERT INTO verses VALUES (24522, 41, 6, 49, 'o porém vendo ele sobre o do-mar andando glorificaram que fantasma é e clamaram');
INSERT INTO verses VALUES (24523, 41, 6, 50, 'todos pois ele viram e foram-perturbados o porém imediatamente falou com deles e diz a-eles Tende-coragem eu sou não temei');
INSERT INTO verses VALUES (24524, 41, 6, 51, 'e subiu junto-a eles para o barco e cessou o vento e muito de abundante em si-mesmos ficavam-fora-de-si');
INSERT INTO verses VALUES (24525, 41, 6, 52, 'não pois compreenderam sobre o pães mas era deles o coração tendo-sido-endurecida');
INSERT INTO verses VALUES (24526, 41, 6, 53, 'e tendo-atravessado sobre o terra vieram para Genesaré e ancoraram');
INSERT INTO verses VALUES (24527, 41, 6, 54, 'e tendo-saído deles de o do-barco imediatamente reconhecendo ele');
INSERT INTO verses VALUES (24528, 41, 6, 55, 'correram-ao-redor toda o região aquela e começaram sobre o leitos o mal tendo carregar-ao-redor onde ouviam que é');
INSERT INTO verses VALUES (24529, 41, 6, 56, 'e onde partícula-condicional entrava para aldeias ou para cidades ou para campos em o praças Punham o enfermos e suplicavam ele para que e-se o franja o manto dele toquem e quanto partícula-condicional tocaram dele Eram-salvos');
INSERT INTO chapters VALUES (964, 41, 7, 36);
INSERT INTO verses VALUES (24530, 41, 7, 1, 'e reúnem-se junto-a ele o fariseus e alguns o dos-escribas vindo de Jerusalém');
INSERT INTO verses VALUES (24531, 41, 7, 2, 'e vendo alguns o discípulos dele que comuns mãos isto é não-lavadas comem o pães');
INSERT INTO verses VALUES (24532, 41, 7, 3, 'o pois fariseus e todos o judeus se não com-punho lavem o mãos não comem segurando o tradição o dos-anciãos');
INSERT INTO verses VALUES (24533, 41, 7, 4, 'e de praça se não asperjam-a-si-mesmos não comem e outras-coisas muitas-coisas é o qual recebi segurar batismos cálices e jarros e de-vasos-de-bronze');
INSERT INTO verses VALUES (24534, 41, 7, 5, 'e perguntem ele o fariseus e o escribas através-de quê não andam o discípulos teu segundo o tradição o dos-anciãos mas comuns mãos comem o pão');
INSERT INTO verses VALUES (24535, 41, 7, 6, 'o porém disse a-eles Bem profetizou Isaías acerca-de vosso o hipócritas como está-escrito que este o povo o lábios me honra o porém coração deles longe está-distante de mim');
INSERT INTO verses VALUES (24536, 41, 7, 7, 'em-vão porém adoram me ensinando ensino mandamentos dos-homens');
INSERT INTO verses VALUES (24537, 41, 7, 8, 'deixando o mandamento o de-Theos segurai o tradição o dos-homens');
INSERT INTO verses VALUES (24538, 41, 7, 9, 'e dizia a-eles Bem anulais o mandamento o de-Theos para que o tradição vosso guardeis');
INSERT INTO verses VALUES (24539, 41, 7, 10, 'Moisés pois disse Honra o Pai teu e o mãe teu e o falando-mal Pai ou mãe morte morra');
INSERT INTO verses VALUES (24540, 41, 7, 11, 'vós porém dizeis se diga homem o pai ou o mãe Corbã o qual é Oferta o qual se de mim sejas-beneficiado');
INSERT INTO verses VALUES (24541, 41, 7, 12, 'não-mais perdoais ele nada fazer o pai ou o mãe');
INSERT INTO verses VALUES (24542, 41, 7, 13, 'invalidando o palavra o de-Theos o em-tradição vosso o qual entregastes e semelhantes tais-coisas muitas-coisas fazei');
INSERT INTO verses VALUES (24543, 41, 7, 14, 'e tendo-chamado novamente o multidão dizia a-eles Ouvi meu todos e entendei');
INSERT INTO verses VALUES (24544, 41, 7, 15, 'nada é de-fora o do-homem entrando para ele o qual pode tornar-comum ele mas o de o do-homem saindo é o tornando-comum o homem');
INSERT INTO verses VALUES (24545, 41, 7, 17, 'e quando entrou para casa de o da-multidão perguntavam ele o discípulos dele o parábola');
INSERT INTO verses VALUES (24546, 41, 7, 18, 'e diz a-eles assim e vós insensatos sois não entendeis que todo o de-fora entrando para o homem não pode ele tornar-comum');
INSERT INTO verses VALUES (24547, 41, 7, 19, 'que não entra dele para o coração mas para o ventre e para o latrina sai purificando todas-as-coisas o alimentos');
INSERT INTO verses VALUES (24548, 41, 7, 20, 'dizia porém que o de o do-homem saindo aquilo contamina o homem');
INSERT INTO verses VALUES (24549, 41, 7, 21, 'por-dentro pois de o do-coração o dos-homens o raciocínios o maus saem fornicações furtos homicídios');
INSERT INTO verses VALUES (24550, 41, 7, 22, 'adultérios avarezes maldades engano devassidão olho mau blasfêmia Soberba insensatez');
INSERT INTO verses VALUES (24551, 41, 7, 23, 'todas-as-coisas estas-coisas o má por-dentro sai e contamina o homem');
INSERT INTO verses VALUES (24552, 41, 7, 24, 'Dali porém levantando-se partiu para o limites Tiro e entrando para casa a-ninguém queria conhecer e não foi-capaz esconder-se');
INSERT INTO verses VALUES (24553, 41, 7, 25, 'mas imediatamente tendo-ouvido mulher acerca-de dele o qual tinha o filhinha dela espírito impuro tendo-vindo prostrou-se junto-a o pés dele');
INSERT INTO verses VALUES (24554, 41, 7, 26, 'o porém mulher era Grega Siro-fenícia o raça e perguntava ele para que o demônio expulse de o filha dela');
INSERT INTO verses VALUES (24555, 41, 7, 27, 'e dizia a-ela Deixa primeiro ser-saciado o filhos não pois é bom receber o pão o de-filhos e o cachorrinhos lançar');
INSERT INTO verses VALUES (24556, 41, 7, 28, 'o porém respondeu e diz a ele Sim Kyrie e o cachorrinhos debaixo o mesa comem de o migalhas o crianças');
INSERT INTO verses VALUES (24557, 41, 7, 29, 'e disse a-ela através-de este o palavra vai tem-saído de o filha teu o demônio');
INSERT INTO verses VALUES (24558, 41, 7, 30, 'e tendo-partido para o casa dela encontrou o criança tendo-sido-lançado sobre o cama e o demônio tendo-saído');
INSERT INTO verses VALUES (24559, 41, 7, 31, 'e novamente saindo de o fronteiras Tiro veio através-de Sidom para o mar o Galileia cada meio o fronteiras Decápolis');
INSERT INTO verses VALUES (24560, 41, 7, 32, 'e trazem a ele mudo e gago e exortam ele para que imponha a ele o mão');
INSERT INTO verses VALUES (24561, 41, 7, 33, 'e tendo-tomado-à-parte ele de o da-multidão segundo própria lançou o dedos dele para o ouvidos dele e tendo-cuspido tocou o língua dele');
INSERT INTO verses VALUES (24562, 41, 7, 34, 'e olhando-para-cima para o céu Gemeu e diz a ele Efatá o qual é Sê-aberto');
INSERT INTO verses VALUES (24563, 41, 7, 35, 'e abriram dele o rumores e imediatamente foi-desatado o cadeia o língua dele e falava retamente');
INSERT INTO verses VALUES (24564, 41, 7, 36, 'e ordenou-severamente a-eles para que a-ninguém digam quanto porém a-eles ordenava eles-mesmos mais abundantemente proclamavam');
INSERT INTO verses VALUES (24565, 41, 7, 37, 'e Superabundantemente ficavam-espantados dizendo Bem todas-as-coisas tem-feito e o mudos faz ouvir e mudos falar');
INSERT INTO chapters VALUES (965, 41, 8, 38);
INSERT INTO verses VALUES (24566, 41, 8, 1, 'em naquelas o dias novamente muito da-multidão sendo e não tendo quê comam tendo-chamado o discípulos diz a-eles');
INSERT INTO verses VALUES (24567, 41, 8, 2, 'Tenho-compaixão sobre o multidão que já dias três permanecem-junto a-mim e não têm quê comam');
INSERT INTO verses VALUES (24568, 41, 8, 3, 'e se soltarei eles em-jejum para casa deles desfalecerão em o caminho e alguns deles de de-longe são');
INSERT INTO verses VALUES (24569, 41, 8, 4, 'e responderam a ele o discípulos dele que De-onde estes poderá alguém aqui saciar pães sobre Deserto');
INSERT INTO verses VALUES (24570, 41, 8, 5, 'e perguntava eles Quantos tendes pães o porém disseram Sete');
INSERT INTO verses VALUES (24571, 41, 8, 6, 'e ordena o à-multidão reclinar-se sobre o da-terra e tomando o sete pães tendo-dado-graças partiu e dava o discípulos dele para que confiem e puseram-diante o à-multidão');
INSERT INTO verses VALUES (24572, 41, 8, 7, 'e tinham peixinhos poucas-coisas e tendo-abençoado eles disse e estas-coisas pôr-diante');
INSERT INTO verses VALUES (24573, 41, 8, 8, 'e comeram e foram-saciados e levantaram sobras pedaços sete cestos');
INSERT INTO verses VALUES (24574, 41, 8, 9, 'eram porém como quatro-mil e soltou eles');
INSERT INTO verses VALUES (24575, 41, 8, 10, 'e imediatamente embarcando para o barco com o discípulos dele veio para o partes Dalmanuta');
INSERT INTO verses VALUES (24576, 41, 8, 11, 'e saíram o fariseus e começaram debater a ele buscando de-junto-de dele sinal de o do-céu tentando ele');
INSERT INTO verses VALUES (24577, 41, 8, 12, 'e tendo-gemido-profundamente o espírito dele diz quê o geração esta busca sinal amém digo a-vós se será-dado o geração nesta sinal');
INSERT INTO verses VALUES (24578, 41, 8, 13, 'e deixando eles novamente embarcando partiu para o além');
INSERT INTO verses VALUES (24579, 41, 8, 14, 'e esqueceram-se receber pães e se não um pão não tinham com deles-mesmos em o no-barco');
INSERT INTO verses VALUES (24580, 41, 8, 15, 'e ordenava a-eles dizendo Vede vede de o fermento o fariseus e o fermento de-Herodes');
INSERT INTO verses VALUES (24581, 41, 8, 16, 'e debatiam junto-a uns-aos-outros que pães não têm');
INSERT INTO verses VALUES (24582, 41, 8, 17, 'e sabendo diz a-eles quê raciocinais que pães não tendes ainda-não entendeis nem entendeis tendo-sido-endurecida tendes o coração vosso');
INSERT INTO verses VALUES (24583, 41, 8, 18, 'olhos tendo não vede e ouvidos tendo não ouvi e não lembrai-vos');
INSERT INTO verses VALUES (24584, 41, 8, 19, 'quando o cinco pães Parti para o cinco-mil quantos cestos pedaços cheios levastes dizem a ele Doze');
INSERT INTO verses VALUES (24585, 41, 8, 20, 'quando o sete para o quatro-mil de-quantos cestos plenitudes pedaços levastes e dizem Sete');
INSERT INTO verses VALUES (24586, 41, 8, 21, 'e dizia a-eles Ainda-não entendeis');
INSERT INTO verses VALUES (24587, 41, 8, 22, 'e vêm para Betsaida e trazem a ele cego e exortam ele para que dele toque');
INSERT INTO verses VALUES (24588, 41, 8, 23, 'e tomando o da-mão o cego carregou-para-fora ele fora o aldeia e tendo-cuspido para o olhos dele pondo-sobre o mãos a ele perguntava ele se algo vês');
INSERT INTO verses VALUES (24589, 41, 8, 24, 'e olhando-para-cima dizia vejo o homens que como árvores vejo andando');
INSERT INTO verses VALUES (24590, 41, 8, 25, 'então novamente pôs-sobre o mãos sobre o olhos dele e viu-claramente e foi-restaurado e olhava-fixamente claramente todas-as-coisas');
INSERT INTO verses VALUES (24591, 41, 8, 26, 'e enviou ele para casa dele dizendo nem para o aldeia entres');
INSERT INTO verses VALUES (24592, 41, 8, 27, 'e saiu o Iesous e o discípulos dele para o aldeias Cesareia o Filipe e em o caminho perguntava o discípulos dele dizendo a-eles Quem me dizem o homens ser');
INSERT INTO verses VALUES (24593, 41, 8, 28, 'o porém disseram a ele dizendo que João o Batista e outros Elias outros porém que um o profetas');
INSERT INTO verses VALUES (24594, 41, 8, 29, 'e ele perguntava eles vós porém quem me dizeis ser respondendo o Pedro diz a ele tu és o Christos');
INSERT INTO verses VALUES (24595, 41, 8, 30, 'e repreendeu a-eles para que a-ninguém digam acerca-de dele');
INSERT INTO verses VALUES (24596, 41, 8, 31, 'e começou ensinar eles que é necessário o Filho o do-homem muitas-coisas sofrer e ser-rejeitado sob o dos-anciãos e o sumos-sacerdotes e o dos-escribas e ser-morto e com três do-dia levantar-se');
INSERT INTO verses VALUES (24597, 41, 8, 32, 'e com-ousadia o palavra falava e tendo-tomado-consigo o Pedro ele começou repreender a ele');
INSERT INTO verses VALUES (24598, 41, 8, 33, 'o porém tendo-se-voltado e vendo o discípulos dele repreendeu a-Pedro e diz Vai atrás meu Satanás que não pensas o o de-Theos mas o o dos-homens');
INSERT INTO verses VALUES (24599, 41, 8, 34, 'e tendo-chamado o multidão com o discípulos dele disse a-eles se alguém quer atrás meu vir negue-a-si-mesmo si-mesmo e levante o cruz dele e siga a-mim');
INSERT INTO verses VALUES (24600, 41, 8, 35, 'o qual pois se queira o alma dele salvar destruirá ela o qual e/mas partícula-condicional destruirá o alma dele por-causa-de mim e o evangelho salvará ela');
INSERT INTO verses VALUES (24601, 41, 8, 36, 'quê pois aproveita homem ganhar o mundo todo e sofrer-perda o alma dele');
INSERT INTO verses VALUES (24602, 41, 8, 37, 'quê pois dê homem resgate o alma dele');
INSERT INTO verses VALUES (24603, 41, 8, 38, 'o qual pois se envergonhe-se me e o meus palavras em o geração nesta o adúltera e pecador e o Filho o do-homem envergonhar-se-á ele quando venha em o glória o do-Pai dele com o anjo o dos-santos');
INSERT INTO chapters VALUES (966, 41, 9, 48);
INSERT INTO verses VALUES (24604, 41, 9, 1, 'e dizia a-eles Amém digo a-vós que são alguns aqui o estando-de-pé os-quais não não provem da-morte até partícula-condicional vejam o reino o de-Theos tendo-vindo em poder');
INSERT INTO verses VALUES (24605, 41, 9, 2, 'e com do-dia seis toma-consigo o Iesous o Pedro e o Tiago e João e oferece eles para monte alto segundo própria somente e foi-transfigurado diante-de deles');
INSERT INTO verses VALUES (24606, 41, 9, 3, 'e o vestes dele aconteceu resplandecentes brancos muito quais lavandeiro sobre o da-terra não pode assim branquear');
INSERT INTO verses VALUES (24607, 41, 9, 4, 'e apareceu a-eles Elias com Moisés e eram falando-junto o Iesous');
INSERT INTO verses VALUES (24608, 41, 9, 5, 'e respondendo o Pedro diz o Iesous Rabi bom é nos aqui ser e façamos três tendas a-ti uma e Moisés uma e Elias uma');
INSERT INTO verses VALUES (24609, 41, 9, 6, 'não pois sei quê responda Muito-temerosos pois tornaram-se');
INSERT INTO verses VALUES (24610, 41, 9, 7, 'e aconteceu nuvem fazendo-sombra-sobre a-eles e aconteceu voz de o nuvem Este é o Filho meu o amado ouvi dele');
INSERT INTO verses VALUES (24611, 41, 9, 8, 'e repentinamente tendo-olhado-ao-redor não-mais a-ninguém vi mas o Iesous somente com deles-mesmos');
INSERT INTO verses VALUES (24612, 41, 9, 9, 'e descendo deles de o do-monte ordenou-severamente a-eles para que a-ninguém o qual vi narrem se não quando o Filho o do-homem de mortos levante-se');
INSERT INTO verses VALUES (24613, 41, 9, 10, 'e o palavra agarraram junto-a si-mesmos disputando-junto quê é o de mortos levantar-se');
INSERT INTO verses VALUES (24614, 41, 9, 11, 'e perguntavam ele dizendo que dizem o escribas que Elias é necessário vir primeiro');
INSERT INTO verses VALUES (24615, 41, 9, 12, 'o porém disse a-eles Elias por-um-lado vindo primeiro restaura todas-as-coisas e como está-escrito sobre o Filho o do-homem para que muitas-coisas sofra e seja-desprezado');
INSERT INTO verses VALUES (24616, 41, 9, 13, 'mas digo a-vós que e Elias tem-vindo e fizeram a ele quanto queriam assim-como está-escrito sobre ele');
INSERT INTO verses VALUES (24617, 41, 9, 14, 'e vindo junto-a o discípulos vi multidão muito acerca-de eles e escribas discutindo junto-a eles');
INSERT INTO verses VALUES (24618, 41, 9, 15, 'e imediatamente todo o multidão vendo ele ficaram-muito-assombrados e correndo-para Saudavam ele');
INSERT INTO verses VALUES (24619, 41, 9, 16, 'e perguntou eles quê discutis junto-a si-mesmos');
INSERT INTO verses VALUES (24620, 41, 9, 17, 'e respondeu a ele um de o da-multidão Mestre Trouxe o filho meu junto-a te tendo espírito mudo');
INSERT INTO verses VALUES (24621, 41, 9, 18, 'e onde se ele alcance Convulsiona ele e espuma e range o dentes e seca-se e disse o discípulos teu para que ele expulsem e não tiveram-força');
INSERT INTO verses VALUES (24622, 41, 9, 19, 'o porém respondendo a-eles diz Ó geração incrédulo até quando junto-a vos serei até quando suportarei vosso trazei ele para me');
INSERT INTO verses VALUES (24623, 41, 9, 20, 'e trouxeram ele junto-a ele e vendo ele o espírito imediatamente convulsionou ele e caindo sobre o da-terra revolvia-se espumando');
INSERT INTO verses VALUES (24624, 41, 9, 21, 'e perguntou o Pai dele Quanto tempo é como isto aconteceu a ele o porém disse de desde-a-infância');
INSERT INTO verses VALUES (24625, 41, 9, 22, 'e muitas-vezes e para fogo ele lançou e para água para que destrua ele mas se algo podes socorre a-nós compadecido sobre nos');
INSERT INTO verses VALUES (24626, 41, 9, 23, 'o porém Iesous disse a ele o se podes todas-as-coisas possíveis o crente');
INSERT INTO verses VALUES (24627, 41, 9, 24, 'imediatamente clamando o Pai o criança dizia creio ajuda meu o incredulidade');
INSERT INTO verses VALUES (24628, 41, 9, 25, 'vendo porém o Iesous que Corre-junto multidão repreendeu o espírito o impuro dizendo a ele o mudo e mudo espírito eu Ordeno a-ti sai de dele e não-mais entres para ele');
INSERT INTO verses VALUES (24629, 41, 9, 26, 'e clamando e muitas-coisas tendo-convulsionado saiu e aconteceu como morto de-modo-que o a-muitos dizer que morreu');
INSERT INTO verses VALUES (24630, 41, 9, 27, 'o porém Iesous segurando o da-mão dele ressuscitou ele e levantou-se');
INSERT INTO verses VALUES (24631, 41, 9, 28, 'e tendo-entrado dele para casa o discípulos dele segundo própria perguntavam ele que nós não pudemos expulsar isso');
INSERT INTO verses VALUES (24632, 41, 9, 29, 'e disse a-eles isto o raça em a-ninguém pode sair se não em oração');
INSERT INTO verses VALUES (24633, 41, 9, 30, 'E-dali saindo passavam-ao-lado através-de o Galileia e não queria para que alguém conheça');
INSERT INTO verses VALUES (24634, 41, 9, 31, 'ensinava pois o discípulos dele e dizia a-eles que o Filho o do-homem é-entregue para mãos dos-homens e matarão ele e tendo-sido-morto com três do-dia ressuscitará');
INSERT INTO verses VALUES (24635, 41, 9, 32, 'o porém ignoravam o palavra e temiam ele perguntar');
INSERT INTO verses VALUES (24636, 41, 9, 33, 'e vieram para Cafarnaum e em o casa tendo-se-tornado perguntava eles quê em o caminho discutíeis');
INSERT INTO verses VALUES (24637, 41, 9, 34, 'o porém calavam-se junto-a uns-aos-outros pois discutiram em o caminho quem maior');
INSERT INTO verses VALUES (24638, 41, 9, 35, 'e sentando-se chamou o doze e diz a-eles se alguém quer primeiro ser será todos último e todos servo');
INSERT INTO verses VALUES (24639, 41, 9, 36, 'e tomando criança estabeleceu ele em no-meio deles e tendo-abraçado ele disse a-eles');
INSERT INTO verses VALUES (24640, 41, 9, 37, 'o qual partícula-condicional um o de-tais crianças receba sobre o no-nome meu mim recebe e o qual partícula-condicional mim receba não mim recebe mas o enviante me');
INSERT INTO verses VALUES (24641, 41, 9, 38, 'Disse a ele o João Mestre vimos alguém em o no-nome teu lançando-fora demônios o qual não segue a-nós e impedíamos ele que não seguia a-nós');
INSERT INTO verses VALUES (24642, 41, 9, 39, 'o porém Iesous disse não impedis ele ninguém pois é o qual fará poder sobre o no-nome meu e poderá rapidamente amaldiçoar me');
INSERT INTO verses VALUES (24643, 41, 9, 40, 'o qual pois não é segundo nosso em-favor-de nosso é');
INSERT INTO verses VALUES (24644, 41, 9, 41, 'o qual pois partícula-condicional dê-de-beber vos cálice água em em-nome que de-Christos sois amém digo a-vós que não não destrua o salário dele');
INSERT INTO verses VALUES (24645, 41, 9, 42, 'e o qual partícula-condicional escandalize um o pequenos destes o crentes bom é a ele mais se está-posto-ao-redor pedra-de-moinho de-moinho acerca-de o pescoço dele e tem-sido-lançado para o mar');
INSERT INTO verses VALUES (24646, 41, 9, 43, 'e se escandalize te o mão teu corta-fora ela bom é te aleijado entrar para o vida ou o dois mãos tendo ir-embora para o Geena para o fogo o inextinguível');
INSERT INTO verses VALUES (24647, 41, 9, 45, 'e se o pé teu escandaliza te corta-fora ele bom é te entrar para o vida coxo ou o dois pés tendo ser-lançado para o Geena');
INSERT INTO verses VALUES (24648, 41, 9, 47, 'e se o olho teu escandaliza te expulsa ele bom te é com-um-só-olho entrar para o reino o de-Theos ou dois olhos tendo ser-lançado para o Geena');
INSERT INTO verses VALUES (24649, 41, 9, 48, 'onde o verme deles não morre e o fogo não é-apagada');
INSERT INTO verses VALUES (24650, 41, 9, 49, 'todo pois fogo será-salgado');
INSERT INTO verses VALUES (24651, 41, 9, 50, 'belo o sal se porém o sal insípido aconteça em a-quem ele temperareis tendes em si-mesmos sal e tende-paz em uns-aos-outros');
INSERT INTO chapters VALUES (967, 41, 10, 52);
INSERT INTO verses VALUES (24652, 41, 10, 1, 'e dali levantando-se vem para o limites o Judeia e além o Jordão e caminham-junto novamente multidões junto-a ele e como costumava novamente ensinava eles');
INSERT INTO verses VALUES (24653, 41, 10, 2, 'e aproximando-se fariseus perguntavam ele se é-lícito homem mulher soltar tentando ele');
INSERT INTO verses VALUES (24654, 41, 10, 3, 'o porém respondendo disse a-eles quê a-vós ordenou Moisés');
INSERT INTO verses VALUES (24655, 41, 10, 4, 'o porém disseram Permitiu Moisés livro divórcio escrever e soltar');
INSERT INTO verses VALUES (24656, 41, 10, 5, 'o porém Iesous disse a-eles junto-a o dureza-de-coração vosso escreveu a-vós o mandamento esta');
INSERT INTO verses VALUES (24657, 41, 10, 6, 'de porém princípio criação macho e fêmea fez eles');
INSERT INTO verses VALUES (24658, 41, 10, 7, 'por-causa-de deste deixará homem o Pai dele e o mãe');
INSERT INTO verses VALUES (24659, 41, 10, 8, 'e serão o dois para carne uma de-modo-que não-mais são dois mas uma carne');
INSERT INTO verses VALUES (24660, 41, 10, 9, 'o qual portanto o Theos juntou homem não separe');
INSERT INTO verses VALUES (24661, 41, 10, 10, 'e para o casa novamente o discípulos acerca-de deste perguntavam ele');
INSERT INTO verses VALUES (24662, 41, 10, 11, 'e diz a-eles o qual partícula-condicional solte o mulher dele e case outra adultera sobre ela');
INSERT INTO verses VALUES (24663, 41, 10, 12, 'e se ela tendo-soltado o homem dela case outro adultera');
INSERT INTO verses VALUES (24664, 41, 10, 13, 'e ofereciam a ele crianças para que deles toque o porém discípulos repreenderam a-eles');
INSERT INTO verses VALUES (24665, 41, 10, 14, 'vendo porém o Iesous indignou-se e disse a-eles Deixai o crianças vir para me não impedis elas o pois de-tais é o reino o de-Theos');
INSERT INTO verses VALUES (24666, 41, 10, 15, 'amém digo a-vós o qual partícula-condicional não receba o reino o de-Theos como criança não não entre para ela');
INSERT INTO verses VALUES (24667, 41, 10, 16, 'e tendo-abraçado eles abençoava pondo o mãos sobre elas');
INSERT INTO verses VALUES (24668, 41, 10, 17, 'e saindo dele para caminho tendo-corrido-até um e tendo-ajoelhado ele perguntava ele Mestre bom quê farei para que vida eterno herdarei');
INSERT INTO verses VALUES (24669, 41, 10, 18, 'o porém Iesous disse a ele quê me dizes bom ninguém bom se não um o Theos');
INSERT INTO verses VALUES (24670, 41, 10, 19, 'o mandamentos sei não assassines não adulteres não furtes não testemunhes-falsamente não prives Honra o Pai teu e o mãe');
INSERT INTO verses VALUES (24671, 41, 10, 20, 'o porém disse a ele Mestre estas-coisas todas-as-coisas Guardei-a-mim-mesmo de juventude meu');
INSERT INTO verses VALUES (24672, 41, 10, 21, 'o porém Iesous olhando-fixamente a ele amou ele e disse a ele Um te Falta vai quanto tens vende e dá o pobres e terás tesouro em no-céu e vem segue a-mim');
INSERT INTO verses VALUES (24673, 41, 10, 22, 'o porém tendo-ficado-sombrio sobre o em-palavra partiu entristecendo-se era pois tendo propriedades muitas-coisas');
INSERT INTO verses VALUES (24674, 41, 10, 23, 'e olhando-ao-redor o Iesous diz o discípulos dele como dificilmente o o posses tendo para o reino o de-Theos entrarão');
INSERT INTO verses VALUES (24675, 41, 10, 24, 'o porém discípulos ficavam-assombrados sobre o palavras dele o porém Iesous novamente respondendo diz a-eles Filhos como difícil é para o reino o de-Theos entrar');
INSERT INTO verses VALUES (24676, 41, 10, 25, 'mais-fácil é camelo através-de o fundo-de-agulha o agulha atravessar ou rico para o reino o de-Theos entrar');
INSERT INTO verses VALUES (24677, 41, 10, 26, 'o porém abundantemente ficavam-espantados dizendo junto-a a-si-mesmos e quem pode ser-salvo');
INSERT INTO verses VALUES (24678, 41, 10, 27, 'olhando-fixamente a-eles o Iesous diz de-junto-de aos-homens impossível mas não de-junto-de a-Theos todas-as-coisas pois possíveis de-junto-de o a-Theos');
INSERT INTO verses VALUES (24679, 41, 10, 28, 'Começou dizer o Pedro a ele Eis nós deixamos todas-as-coisas e temos-seguido a-ti');
INSERT INTO verses VALUES (24680, 41, 10, 29, 'disse o Iesous Amém digo a-vós ninguém é o qual deixou casa ou irmãos ou irmãs ou mãe ou Pai ou filhos ou campos por-causa-de mim e por-causa-de o evangelho');
INSERT INTO verses VALUES (24681, 41, 10, 30, 'se não receba cem-vezes-mais agora em o tempo neste da-casa e irmãos e irmãs e mães e filhos e campos com perseguições e em o era o vindo vida eterno');
INSERT INTO verses VALUES (24682, 41, 10, 31, 'muitos porém serão primeiro últimos e o últimos primeiro');
INSERT INTO verses VALUES (24683, 41, 10, 32, 'eram porém em o caminho subindo para Jerusalém e era precedendo eles o Iesous e ficavam-assombrados o porém seguindo temiam e tomando-consigo novamente o doze começou a-eles dizer o as-coisas-futuras a ele acontecer');
INSERT INTO verses VALUES (24684, 41, 10, 33, 'que Eis subimos para Jerusalém e o Filho o do-homem será-entregue o sumos-sacerdotes e o escribas e condenarão ele morte e entregarão ele o nações');
INSERT INTO verses VALUES (24685, 41, 10, 34, 'e escarnecerão a ele e cuspirão a ele e açoitarão ele e matarão e com três do-dia ressuscitará');
INSERT INTO verses VALUES (24686, 41, 10, 35, 'e aproximam-se a ele Tiago e João o filhos Zebedeu dizendo a ele Mestre queremos para que o qual se peçamos te faças a-nós');
INSERT INTO verses VALUES (24687, 41, 10, 36, 'o porém disse a-eles quê quereis me farei a-vós');
INSERT INTO verses VALUES (24688, 41, 10, 37, 'o porém disseram a ele Dá a-nós para que um teu de direita e um de esquerda sentemo-nos em o glória teu');
INSERT INTO verses VALUES (24689, 41, 10, 38, 'o porém Iesous disse a-eles não sei quê pedis podeis beber o cálice o qual eu bebo ou o batismo o qual eu sou-batizado ser-batizado');
INSERT INTO verses VALUES (24690, 41, 10, 39, 'o porém disseram a ele Podemos o porém Iesous disse a-eles o cálice o qual eu bebo bebereis e o batismo o qual eu sou-batizado sereis-batizados');
INSERT INTO verses VALUES (24691, 41, 10, 40, 'o porém sentar de direita meu ou de esquerda não é meu dar mas o qual tem-sido-preparado');
INSERT INTO verses VALUES (24692, 41, 10, 41, 'e ouvindo o dez começaram indignar-se acerca-de de-Tiago e João');
INSERT INTO verses VALUES (24693, 41, 10, 42, 'e tendo-chamado eles o Iesous diz a-eles sei que o parecendo governar o nações dominam deles e o grandes deles exercem-autoridade-sobre deles');
INSERT INTO verses VALUES (24694, 41, 10, 43, 'não assim e/mas é em a-vós mas o qual partícula-condicional queira grande tornar-se em a-vós será vosso servo');
INSERT INTO verses VALUES (24695, 41, 10, 44, 'e o qual partícula-condicional queira em a-vós ser primeiro será todos servo');
INSERT INTO verses VALUES (24696, 41, 10, 45, 'e pois o Filho o do-homem não veio ser-servido mas servir e dar o alma dele resgate em-troca-de muitos');
INSERT INTO verses VALUES (24697, 41, 10, 46, 'e vêm para Jericó e saindo dele de Jericó e o discípulos dele e da-multidão suficiente o Filho Timeu Bartimeu cego mendigo sentava-se de-junto-de o caminho');
INSERT INTO verses VALUES (24698, 41, 10, 47, 'e ouvindo que Iesous o Nazareno é começou clamar e dizer Filho Davi Iesous tem-misericórdia me');
INSERT INTO verses VALUES (24699, 41, 10, 48, 'e repreendiam a ele muitos para que cale-se o porém muito mais gritava Filho Davi tem-misericórdia me');
INSERT INTO verses VALUES (24700, 41, 10, 49, 'e tendo-ficado-de-pé o Iesous disse Chamai ele e chamam o cego dizendo a ele tem-ânimo levanta-te chama te');
INSERT INTO verses VALUES (24701, 41, 10, 50, 'o porém tendo-lançado-fora o manto dele tendo-saltado veio junto-a o Iesous');
INSERT INTO verses VALUES (24702, 41, 10, 51, 'e respondendo a ele o Iesous disse quê a-ti queres farei o porém cego disse a ele Rabôni para que recuperarei-a-vista');
INSERT INTO verses VALUES (24703, 41, 10, 52, 'e o Iesous disse a ele Vai o fé teu tem-salvo te e imediatamente olhou-para-cima e seguia a ele em o caminho');
INSERT INTO chapters VALUES (968, 41, 11, 32);
INSERT INTO verses VALUES (24704, 41, 11, 1, 'e quando aproximam-se para Jerusalém para Betfagé e Betânia junto-a o monte o Oliveiras envia dois o discípulos dele');
INSERT INTO verses VALUES (24705, 41, 11, 2, 'e diz a-eles ide para o aldeia o defronte-de vosso e imediatamente entrando para ela encontrareis jumentinho amarrado sobre o qual ninguém ainda-não dos-homens sentou-se desatai ele e trazei');
INSERT INTO verses VALUES (24706, 41, 11, 3, 'e se alguém a-vós diga quê fazei isto dizei o Kyrios dele necessidade tem e imediatamente ele envia novamente aqui');
INSERT INTO verses VALUES (24707, 41, 11, 4, 'e foram e encontraram jumentinho amarrado junto-a porta fora sobre o encruzilhada e desatam ele');
INSERT INTO verses VALUES (24708, 41, 11, 5, 'e alguns o ali estando-de-pé diziam a-eles quê fazei desatando o jumentinho');
INSERT INTO verses VALUES (24709, 41, 11, 6, 'o porém disseram a-eles assim-como disse o Iesous e deixaram eles');
INSERT INTO verses VALUES (24710, 41, 11, 7, 'e trazem o jumentinho junto-a o Iesous e lançam-sobre a ele o vestes deles e sentou-se sobre ele');
INSERT INTO verses VALUES (24711, 41, 11, 8, 'e muitos o vestes deles estenderam para o caminho outros porém ramos tendo-golpeado de o campos');
INSERT INTO verses VALUES (24712, 41, 11, 9, 'e o precedendo e o seguindo Clamavam Hosana Bendito o o-que-vem em em-nome do-Kyrios');
INSERT INTO verses VALUES (24713, 41, 11, 10, 'Tendo-sido-abençoada o vindo reino o do-Pai nosso Davi Hosana em o alturas');
INSERT INTO verses VALUES (24714, 41, 11, 11, 'e entrou para Jerusalém para o templo e olhando-ao-redor todas-as-coisas tarde já sendo o hora saiu para Betânia com o doze');
INSERT INTO verses VALUES (24715, 41, 11, 12, 'e o no-dia-seguinte tendo-saído deles de Betânia teve-fome');
INSERT INTO verses VALUES (24716, 41, 11, 13, 'e vendo figueira de de-longe tendo folhas veio se então algo encontrará em a-ela e vindo sobre ela nada encontrou se não folhas o pois tempo-oportuno não era de-figos');
INSERT INTO verses VALUES (24717, 41, 11, 14, 'e respondendo disse a-ela Não-mais para o eternidade de teu ninguém fruto comesse e ouviam o discípulos dele');
INSERT INTO verses VALUES (24718, 41, 11, 15, 'e vêm para Jerusalém e entrando para o templo começou expulsar o vendendo e o comprando em o templo e o mesas o cambistas e o cadeiras o vendendo o pombas derrubou');
INSERT INTO verses VALUES (24719, 41, 11, 16, 'e não deixava para que alguém carregue-através vaso através-de o do-templo');
INSERT INTO verses VALUES (24720, 41, 11, 17, 'e ensinava e dizia a-eles não está-escrito que o casa meu casa oração será-chamado todos o nações vós porém tendes-feito ele caverna ladrões');
INSERT INTO verses VALUES (24721, 41, 11, 18, 'e ouviram o sumos-sacerdotes e o escribas e buscavam como ele destruam temiam pois ele todo pois o multidão ficava-maravilhado sobre o em-ensino dele');
INSERT INTO verses VALUES (24722, 41, 11, 19, 'e quando tarde aconteceu saíam fora o cidade');
INSERT INTO verses VALUES (24723, 41, 11, 20, 'e passando-ao-lado de-manhã vi o figueira tendo-sido-secada de raízes');
INSERT INTO verses VALUES (24724, 41, 11, 21, 'e tendo-se-lembrado o Pedro diz a ele Rabi vê o figueira o qual amaldiçoaste têm-sido-secados');
INSERT INTO verses VALUES (24725, 41, 11, 22, 'e respondendo o Iesous diz a-eles Tendes fé de-Theos');
INSERT INTO verses VALUES (24726, 41, 11, 23, 'amém digo a-vós que o qual partícula-condicional diga o no-monte neste Sê-levantado e sê-lançado para o mar e não seja-dividido em o no-coração dele mas creia que o qual fala torna-se será a ele');
INSERT INTO verses VALUES (24727, 41, 11, 24, 'através-de isto digo a-vós todas-as-coisas quanto orai e pedis credes que recebestes e será a-vós');
INSERT INTO verses VALUES (24728, 41, 11, 25, 'e quando permanecei-firmes orando perdoais se algo tendes segundo de-alguém para que e o Pai vosso o em o nos-céus perdoe a-vós o transgressões vosso');
INSERT INTO verses VALUES (24729, 41, 11, 27, 'e vêm novamente para Jerusalém e em o templo andando dele vêm junto-a ele o sumos-sacerdotes e o escribas e o anciãos');
INSERT INTO verses VALUES (24730, 41, 11, 28, 'e diziam a ele em qual em-autoridade estas-coisas fazes ou quem a-ti deu o autoridade esta para que estas-coisas fazes');
INSERT INTO verses VALUES (24731, 41, 11, 29, 'o porém Iesous disse a-eles Perguntarei vos um palavra e respondei a-mim e direi a-vós em qual em-autoridade estas-coisas faço');
INSERT INTO verses VALUES (24732, 41, 11, 30, 'o batismo o João de do-céu era ou de dos-homens respondei a-mim');
INSERT INTO verses VALUES (24733, 41, 11, 31, 'e debatiam junto-a si-mesmos dizendo se digamos de do-céu dirá através-de quê portanto não crestes a ele');
INSERT INTO verses VALUES (24734, 41, 11, 32, 'mas digamos de dos-homens temiam o multidão todos pois tinham o João verdadeiramente que profeta era');
INSERT INTO verses VALUES (24735, 41, 11, 33, 'e respondendo o Iesous dizem não sei e o Iesous diz a-eles nem eu digo a-vós em qual em-autoridade estas-coisas faço');
INSERT INTO chapters VALUES (969, 41, 12, 44);
INSERT INTO verses VALUES (24736, 41, 12, 1, 'e começou a-eles em em-parábolas falar vinha homem plantou e colocou-ao-redor cerca e cavou Tanque-do-lagar e edificou torre e arrendou ele lavradores e viajou');
INSERT INTO verses VALUES (24737, 41, 12, 2, 'e enviou junto-a o lavradores o tempo servo para que de-junto-de o lavradores receba de o frutos o vinha');
INSERT INTO verses VALUES (24738, 41, 12, 3, 'e tendo-tomado ele espancaram e enviaram vazio');
INSERT INTO verses VALUES (24739, 41, 12, 4, 'e novamente enviou junto-a eles outro servo e-aquele feriram-na-cabeça e Desonraram');
INSERT INTO verses VALUES (24740, 41, 12, 5, 'e outro enviou e-aquele mataram e a-muitos outros o qual por-um-lado espancando o qual porém matando');
INSERT INTO verses VALUES (24741, 41, 12, 6, 'ainda um tinha Filho amado enviou ele último junto-a eles dizendo que Envergonhar-se-ão o filho meu');
INSERT INTO verses VALUES (24742, 41, 12, 7, 'aqueles porém o lavradores junto-a si-mesmos disseram que Este é o herdeiro vinde matemos ele e nosso será o herança');
INSERT INTO verses VALUES (24743, 41, 12, 8, 'e tendo-tomado mataram ele e expulsaram ele fora o vinha');
INSERT INTO verses VALUES (24744, 41, 12, 9, 'quê fará o kyrios o vinha virá e destruirá o lavradores e dará o vinha a-outros');
INSERT INTO verses VALUES (24745, 41, 12, 10, 'nem o escritura esta lestes Pedra o qual rejeitaram o edificantes este aconteceu para cabeça esquina');
INSERT INTO verses VALUES (24746, 41, 12, 11, 'de-junto-de do-Kyrios aconteceu esta e é admirável em olhos nosso');
INSERT INTO verses VALUES (24747, 41, 12, 12, 'e buscavam ele agarrar e temeram o multidão conheceram pois que junto-a eles o parábola disse e deixando ele foram');
INSERT INTO verses VALUES (24748, 41, 12, 13, 'e enviam junto-a ele alguns o fariseus e o herodianos para que ele apanhem em-palavra');
INSERT INTO verses VALUES (24749, 41, 12, 14, 'e vindo dizem a ele Mestre sei que verdadeiro és e não importa a-ti acerca-de ninguém não pois vês para rosto dos-homens mas sobre da-verdade o caminho o de-Theos ensinas é-lícito dar tributo César ou não demos ou não demos');
INSERT INTO verses VALUES (24750, 41, 12, 15, 'o porém sei deles o Hipocrisia disse a-eles quê me tentais trazei a-mim denário para que veja');
INSERT INTO verses VALUES (24751, 41, 12, 16, 'o porém trouxeram e diz a-eles De-quem o imagem esta e o inscrição o porém disseram a ele de-César');
INSERT INTO verses VALUES (24752, 41, 12, 17, 'o porém Iesous disse a-eles o de-César devolvei César e o o de-Theos o a-Theos e admiravam-grandemente sobre a ele');
INSERT INTO verses VALUES (24753, 41, 12, 18, 'e vêm Saduceus junto-a ele os-quais dizem ressurreição não ser e perguntavam ele dizendo');
INSERT INTO verses VALUES (24754, 41, 12, 19, 'Mestre Moisés escreveu a-nós que se de-alguém irmão morra e deixe mulher e não perdoe filho para que receba o irmão dele o mulher e levante semente o ao-irmão dele');
INSERT INTO verses VALUES (24755, 41, 12, 20, 'sete irmãos eram e o primeiro recebeu mulher e morrendo não deixou semente');
INSERT INTO verses VALUES (24756, 41, 12, 21, 'e o segundo recebeu ela e morreu não deixando semente e o terceiro da-mesma-forma');
INSERT INTO verses VALUES (24757, 41, 12, 22, 'e o sete não deixaram semente último todos e o mulher morreu');
INSERT INTO verses VALUES (24758, 41, 12, 23, 'em o ressurreição quando levantem-se de-quem deles será mulher o pois sete tiveram ela mulher');
INSERT INTO verses VALUES (24759, 41, 12, 24, 'disse a-eles o Iesous não através-de isto errais não sei o escrituras nem o poder o de-Theos');
INSERT INTO verses VALUES (24760, 41, 12, 25, 'quando pois de mortos levantem-se nem casam nem são-dados-em-casamento mas são como anjo em o nos-céus');
INSERT INTO verses VALUES (24761, 41, 12, 26, 'acerca-de porém o mortos que são-levantados não lestes em o livro de-Moisés sobre o Sarça como disse a ele o Theos dizendo eu o Theos Abraão e Theos Isaque e Theos Jacó');
INSERT INTO verses VALUES (24762, 41, 12, 27, 'não é Theos mortos mas viventes muito errais');
INSERT INTO verses VALUES (24763, 41, 12, 28, 'e aproximando-se um o dos-escribas ouvindo deles dos-que-disputam-juntamente sei que bem respondeu a-eles perguntou ele Qual é mandamento primeiro todos');
INSERT INTO verses VALUES (24764, 41, 12, 29, 'respondeu o Iesous que primeiro é Ouve Israel Kyrios o Theos nosso Kyrios um é');
INSERT INTO verses VALUES (24765, 41, 12, 30, 'e amarás Kyrion o Theos teu de de-toda o do-coração teu e de de-toda o alma teu e de de-toda o entendimento teu e de de-toda o força teu');
INSERT INTO verses VALUES (24766, 41, 12, 31, 'segunda esta Amarás o próximo teu como a-ti-mesmo maior destes outra mandamento não é');
INSERT INTO verses VALUES (24767, 41, 12, 32, 'e disse a ele o escriba Bem Mestre sobre da-verdade disseste que um é e não é outro porém dele');
INSERT INTO verses VALUES (24768, 41, 12, 33, 'e o amar ele de de-toda o do-coração e de de-toda o entendimento e de de-toda o força e o amar o próximo como si-mesmo mais-abundantemente é todos o holocaustos e sacrifícios');
INSERT INTO verses VALUES (24769, 41, 12, 34, 'e o Iesous vendo ele que prudentemente respondeu disse a ele não longe és de o do-reino o de-Theos e ninguém não-mais ousava ele perguntar');
INSERT INTO verses VALUES (24770, 41, 12, 35, 'e respondendo o Iesous dizia ensinando em o templo como dizem o escribas que o Christos Filho Davi é');
INSERT INTO verses VALUES (24771, 41, 12, 36, 'ele Davi disse em o Espírito o no-santo disse Kyrios o ao-Kyrios meu Senta-te de direita meu até partícula-condicional ponha o inimigos teu Debaixo-de o pés teu');
INSERT INTO verses VALUES (24772, 41, 12, 37, 'ele Davi diz ele Kyrion e de-onde dele é filho e o muito multidão ouvia dele prazerosamente');
INSERT INTO verses VALUES (24773, 41, 12, 38, 'e em o em-ensino dele dizia Vede de o dos-escribas o dos-que-querem em vestes-longas andar e saudações em o praças');
INSERT INTO verses VALUES (24774, 41, 12, 39, 'e primeiros-assentos em o nas-sinagogas e primeiros-lugares em o banquetes');
INSERT INTO verses VALUES (24775, 41, 12, 40, 'o devorando o da-casa o viúvas e pretexto longa orando estes receberão abundantemente juízo');
INSERT INTO verses VALUES (24776, 41, 12, 41, 'e sentando-se defronte-de o tesouro contemplava como o multidão lança bronze para o tesouro e muitos ricos Lançavam muitas-coisas');
INSERT INTO verses VALUES (24777, 41, 12, 42, 'e tendo-vindo uma viúva pobre lançou lepta dois o qual é quadrante');
INSERT INTO verses VALUES (24778, 41, 12, 43, 'e tendo-chamado o discípulos dele disse a-eles Amém digo a-vós que o viúva esta o pobre mais todos lançou o lançando para o tesouro');
INSERT INTO verses VALUES (24779, 41, 12, 44, 'todos pois de o abundando a-eles lançaram esta porém de o Falta dela todas-as-coisas quanto tinha lançou todo o vida dela');
INSERT INTO chapters VALUES (970, 41, 13, 37);
INSERT INTO verses VALUES (24780, 41, 13, 1, 'e saindo dele de o do-templo diz a ele um o discípulos dele Mestre vê que-espécie-de pedras e que-espécie-de edificações');
INSERT INTO verses VALUES (24781, 41, 13, 2, 'e o Iesous disse a ele Vês estas o grandes edificações não não seja-perdoado pedra sobre pedra o qual não não seja-destruído');
INSERT INTO verses VALUES (24782, 41, 13, 3, 'e estando-sentado dele para o monte o Oliveiras defronte-de o do-templo perguntava ele segundo própria Pedro e Tiago e João e André');
INSERT INTO verses VALUES (24783, 41, 13, 4, 'Dize a-nós quando estas-coisas será e quê o sinal quando esteja-a-ponto-de estas-coisas consumar-se todas-as-coisas');
INSERT INTO verses VALUES (24784, 41, 13, 5, 'o porém Iesous começou dizer a-eles Vede não alguém vos engane');
INSERT INTO verses VALUES (24785, 41, 13, 6, 'muitos virão sobre o no-nome meu dizendo que Eu sou e a-muitos enganarão');
INSERT INTO verses VALUES (24786, 41, 13, 7, 'quando porém ouçais guerras e ouvidos guerras não alarmeis-vos é necessário tornar-se mas ainda-não o fim');
INSERT INTO verses VALUES (24787, 41, 13, 8, 'será-levantado pois nação sobre nação e reino sobre reino serão terremotos segundo lugares serão fomes princípio dores-de-parto estas-coisas');
INSERT INTO verses VALUES (24788, 41, 13, 9, 'Vede porém vós a-si-mesmos entregarão vos para sinédrios e para sinagogas sereis-açoitados e sobre Governadores e reis sereis-postos-de-pé por-causa-de mim para testemunho a-eles');
INSERT INTO verses VALUES (24789, 41, 13, 10, 'e para todas-as-coisas o nações primeiro é necessário ser-proclamado o evangelho');
INSERT INTO verses VALUES (24790, 41, 13, 11, 'e quando conduzam vos entregando não preocupai-vos-de-antemão quê faleis mas o qual se seja-dada a-vós em naquela o hora isto falais não pois sois vós o falando mas o espírito o santo');
INSERT INTO verses VALUES (24791, 41, 13, 12, 'e entregará irmão irmão para morte e Pai filho e levantar-se-ão-contra filhos sobre pais e matarão eles');
INSERT INTO verses VALUES (24792, 41, 13, 13, 'e sereis odiados sob todos através-de o nome meu o porém tendo-perseverado para fim este será-salvo');
INSERT INTO verses VALUES (24793, 41, 13, 14, 'quando porém vejais o abominação o desolação Tendo-permanecido-de-pé onde não é necessário o lendo entenda então o em o Judeia fujam para o montes');
INSERT INTO verses VALUES (24794, 41, 13, 15, 'o sobre o telhado não desça nem entre algo levantar de o da-casa dele');
INSERT INTO verses VALUES (24795, 41, 13, 16, 'e o para o campo não volte para o atrás levantar o manto dele');
INSERT INTO verses VALUES (24796, 41, 13, 17, 'ai porém o em ventre tendo e o às-que-amamentam em naquelas o dias');
INSERT INTO verses VALUES (24797, 41, 13, 18, 'orai porém para que não aconteça inverno');
INSERT INTO verses VALUES (24798, 41, 13, 19, 'serão pois o dias aquelas tribulação quais não aconteceu tal de princípio criação o qual criou o Theos até o agora e não não aconteça');
INSERT INTO verses VALUES (24799, 41, 13, 20, 'e se não abreviou Kyrios o do-dia não partícula-condicional foi-salvo toda carne mas através-de o eleitos o qual escolheu abreviou o do-dia');
INSERT INTO verses VALUES (24800, 41, 13, 21, 'e então se alguém a-vós diga Vê aqui o Christos Vê ali não credes');
INSERT INTO verses VALUES (24801, 41, 13, 22, 'serão-levantados porém falsos-ungidos e falsos-profetas e farão sinais e prodígios junto-a o desviar se possível o escolhidos');
INSERT INTO verses VALUES (24802, 41, 13, 23, 'vós porém vede predisse a-vós todas-as-coisas');
INSERT INTO verses VALUES (24803, 41, 13, 24, 'mas em naquelas o dias com o aflição aquela o sol será-obscurecido e o lua não dará o brilho dela');
INSERT INTO verses VALUES (24804, 41, 13, 25, 'e o estrelas serão de o do-céu caindo e o poderes o em o nos-céus serão-abalados');
INSERT INTO verses VALUES (24805, 41, 13, 26, 'e então verão o Filho o do-homem o-que-vem em nuvens com do-poder muita e da-glória');
INSERT INTO verses VALUES (24806, 41, 13, 27, 'e então enviará o anjo e Reunirá o eleitos dele de o de-quatro ventos de extremidade da-terra até extremidade do-céu');
INSERT INTO verses VALUES (24807, 41, 13, 28, 'de porém o figueira aprendei o parábola quando já o ramo dela tenro aconteça e brote o folhas sabeis que perto o verão é');
INSERT INTO verses VALUES (24808, 41, 13, 29, 'assim e vós quando vejais estas-coisas acontecendo sabeis que perto é sobre portas');
INSERT INTO verses VALUES (24809, 41, 13, 30, 'amém digo a-vós que não não passe o geração esta até o qual estas-coisas todas-as-coisas aconteça');
INSERT INTO verses VALUES (24810, 41, 13, 31, 'o céu e o terra passarão o porém palavras meu não passarão');
INSERT INTO verses VALUES (24811, 41, 13, 32, 'acerca-de porém o do-dia daquela ou o hora ninguém sei nem o anjo em no-céu nem o Filho se não o Pai');
INSERT INTO verses VALUES (24812, 41, 13, 33, 'Vede vigiai não sei pois quando o tempo é');
INSERT INTO verses VALUES (24813, 41, 13, 34, 'como homem viajante deixando o casa dele e dando o escravos dele o autoridade a-cada-um o obra dele e o porteiro ordenou para que vigie');
INSERT INTO verses VALUES (24814, 41, 13, 35, 'vigiai portanto não sei pois quando o kyrios o da-casa vem ou tarde ou meia-noite ou canto-do-galo ou de-manhã');
INSERT INTO verses VALUES (24815, 41, 13, 36, 'não vindo subitamente encontre vos dormindo');
INSERT INTO verses VALUES (24816, 41, 13, 37, 'o qual porém a-vós digo todos digo vigiai');
INSERT INTO chapters VALUES (971, 41, 14, 72);
INSERT INTO verses VALUES (24817, 41, 14, 1, 'era porém o páscoa e o ázimos com dois do-dia e buscavam o sumos-sacerdotes e o escribas como ele em engano tendo-agarrado matem');
INSERT INTO verses VALUES (24818, 41, 14, 2, 'diziam pois não em o festa não alguma-vez será tumulto o povo');
INSERT INTO verses VALUES (24819, 41, 14, 3, 'e sendo dele em Betânia em o casa de-Simão o leproso reclinado dele veio mulher tendo alabastro perfume nardo genuína de-grande-valor tendo-quebrado o alabastro derramou dele o cabeça');
INSERT INTO verses VALUES (24820, 41, 14, 4, 'eram e/mas alguns indignando-se junto-a a-si-mesmos para quê o perdição esta o perfume aconteceu');
INSERT INTO verses VALUES (24821, 41, 14, 5, 'podia pois isto o perfume ser-vendido em-cima denários trezentos e ser-dado o pobres e repreendiam-severamente a-ela');
INSERT INTO verses VALUES (24822, 41, 14, 6, 'o porém Iesous disse Deixai ela quê a-ela trabalhos apresentai belo obra trabalhou em a-mim');
INSERT INTO verses VALUES (24823, 41, 14, 7, 'sempre pois o pobres tendes com deles-mesmos e quando queirais podeis a-eles bem fazer mim porém não sempre tendes');
INSERT INTO verses VALUES (24824, 41, 14, 8, 'o qual teve fez antecipou ungir o corpo meu para o sepultamento');
INSERT INTO verses VALUES (24825, 41, 14, 9, 'amém porém digo a-vós onde se seja-proclamado o evangelho para todo o mundo e o qual fez esta será-falado para memorial dela');
INSERT INTO verses VALUES (24826, 41, 14, 10, 'e Judas Iscariotes o um o doze partiu junto-a o sumos-sacerdotes para que ele entregue a-eles');
INSERT INTO verses VALUES (24827, 41, 14, 11, 'o porém ouvindo alegraram-se e prometeram a ele prata dar e buscava como ele oportunamente entregue');
INSERT INTO verses VALUES (24828, 41, 14, 12, 'e o primeiro dia o ázimos quando o páscoa Sacrificavam dizem a ele o discípulos dele Onde queres tendo-ido-embora preparemos para que comas o páscoa');
INSERT INTO verses VALUES (24829, 41, 14, 13, 'e envia dois o discípulos dele e diz a-eles ide para o cidade e encontrará a-vós homem cântaro água carregando segui a ele');
INSERT INTO verses VALUES (24830, 41, 14, 14, 'e onde se entre dizei o senhor-da-casa que o Mestre diz Onde é o hospedaria meu onde o páscoa com o discípulos meu coma');
INSERT INTO verses VALUES (24831, 41, 14, 15, 'e ele a-vós mostrará aposento-superior grande tendo-sido-estendido preparado e ali preparai a-nós');
INSERT INTO verses VALUES (24832, 41, 14, 16, 'e saíram o discípulos e vieram para o cidade e encontraram assim-como disse a-eles e prepararam o páscoa');
INSERT INTO verses VALUES (24833, 41, 14, 17, 'e tarde tendo-acontecido vem com o doze');
INSERT INTO verses VALUES (24834, 41, 14, 18, 'e reclinados deles e comendo o Iesous disse Amém digo a-vós que um de vosso entregará me o comendo com mim');
INSERT INTO verses VALUES (24835, 41, 14, 19, 'começaram entristecer-se e dizer a ele um segundo um Acaso eu');
INSERT INTO verses VALUES (24836, 41, 14, 20, 'o porém disse a-eles Um o doze o mergulhando com mim para o prato');
INSERT INTO verses VALUES (24837, 41, 14, 21, 'que o por-um-lado Filho o do-homem vai assim-como está-escrito acerca-de dele ai porém o ao-homem aquele através-de o qual o Filho o do-homem é-entregue belo a ele se não foi-gerado o homem aquele');
INSERT INTO verses VALUES (24838, 41, 14, 22, 'e comendo deles tomando pão tendo-abençoado partiu e deu a-eles e disse Tomai isto é o corpo meu');
INSERT INTO verses VALUES (24839, 41, 14, 23, 'e tomando cálice tendo-dado-graças deu a-eles e beberam de dele todos');
INSERT INTO verses VALUES (24840, 41, 14, 24, 'e disse a-eles Isto é o sangue meu o da-aliança o derramado em-favor-de muitos');
INSERT INTO verses VALUES (24841, 41, 14, 25, 'amém digo a-vós que não-mais não não beba de o fruto o videira até o do-dia daquela quando ele bebo novo em o no-reino o de-Theos');
INSERT INTO verses VALUES (24842, 41, 14, 26, 'e tendo-cantado-hinos saíram para o monte o Oliveiras');
INSERT INTO verses VALUES (24843, 41, 14, 27, 'e diz a-eles o Iesous que todos sereis-escandalizados que está-escrito Ferirei o pastor e o ovelhas serão-dispersos');
INSERT INTO verses VALUES (24844, 41, 14, 28, 'mas com o ser-levantado me conduzirei-adiante vos para o Galileia');
INSERT INTO verses VALUES (24845, 41, 14, 29, 'o porém Pedro disse a ele se e todos serão-escandalizados mas não eu');
INSERT INTO verses VALUES (24846, 41, 14, 30, 'e diz a ele o Iesous Amém digo a-ti que tu hoje nesta o à-noite antes-de ou duas-vezes galo chamar três-vezes me negará');
INSERT INTO verses VALUES (24847, 41, 14, 31, 'o porém excessivamente falava se é necessário me morrer-junto a-ti não não te negarei da-mesma-forma porém e todos diziam');
INSERT INTO verses VALUES (24848, 41, 14, 32, 'e vêm para campo o qual o nome Getsêmani e diz o discípulos dele Sentai-vos aqui até ore');
INSERT INTO verses VALUES (24849, 41, 14, 33, 'e toma-consigo o Pedro e o Tiago e o João com dele e começou estar-grandemente-espantado e angustiar-se');
INSERT INTO verses VALUES (24850, 41, 14, 34, 'e diz a-eles Profundamente-triste é o alma meu até da-morte permanecei aqui e vigiai');
INSERT INTO verses VALUES (24851, 41, 14, 35, 'e tendo-ido-adiante pouco Caía sobre o da-terra e orava para que se possível é passe de dele o hora');
INSERT INTO verses VALUES (24852, 41, 14, 36, 'e dizia Abba o Pai todas-as-coisas poderosas a-ti afasta o cálice isto de mim mas não quê eu quero mas quê tu');
INSERT INTO verses VALUES (24853, 41, 14, 37, 'e vem e encontra eles dormindo e diz o a-Pedro Simão dormes não Foste-forte uma hora vigiar');
INSERT INTO verses VALUES (24854, 41, 14, 38, 'vigiai e orai para que não Venhais para tentação o por-um-lado espírito pronto o porém carne fraco');
INSERT INTO verses VALUES (24855, 41, 14, 39, 'e novamente partindo orou o ele palavra dizendo');
INSERT INTO verses VALUES (24856, 41, 14, 40, 'e novamente vindo encontrou eles dormindo eram pois deles o olhos sendo-pesados e não sei quê respondam a ele');
INSERT INTO verses VALUES (24857, 41, 14, 41, 'e vem o terceira-vez e diz a-eles Dormis o restante e descansai está-distante veio o hora eis é-entregue o Filho o do-homem para o mãos o dos-pecadores');
INSERT INTO verses VALUES (24858, 41, 14, 42, 'levantai-vos vamos eis o entregando me aproximou-se');
INSERT INTO verses VALUES (24859, 41, 14, 43, 'e imediatamente ainda dele falando chega o Judas um o doze e com dele multidão com espadas e madeiras de-junto-de o sumos-sacerdotes e o dos-escribas e o dos-anciãos');
INSERT INTO verses VALUES (24860, 41, 14, 44, 'tinha-dado porém o entregando ele sinal-combinado a-eles dizendo o qual partícula-condicional beijarei ele-mesmo é seguai ele e conduzi seguramente');
INSERT INTO verses VALUES (24861, 41, 14, 45, 'e vindo imediatamente aproximando-se a ele diz Rabi e beijou-intensamente ele');
INSERT INTO verses VALUES (24862, 41, 14, 46, 'o porém lançaram-sobre o mãos a ele e agarraram ele');
INSERT INTO verses VALUES (24863, 41, 14, 47, 'um e/mas alguém o tendo-estado-de-pé tendo-desembainhado o espada golpeou o servo o do-sumo-sacerdote e tirou dele o orelha');
INSERT INTO verses VALUES (24864, 41, 14, 48, 'e respondendo o Iesous disse a-eles como sobre ladrão saístes com espadas e madeiras prender me');
INSERT INTO verses VALUES (24865, 41, 14, 49, 'segundo dia eu-era junto-a vos em o templo ensinando e não prendestes me mas para que sejam-cumpridos o escrituras');
INSERT INTO verses VALUES (24866, 41, 14, 50, 'e deixando ele fugiram todos');
INSERT INTO verses VALUES (24867, 41, 14, 51, 'e jovem alguém seguia-junto a ele tendo-sido-vestido linho sobre nu e seguram ele');
INSERT INTO verses VALUES (24868, 41, 14, 52, 'o porém deixando o linho nu Fugiu');
INSERT INTO verses VALUES (24869, 41, 14, 53, 'e levaram-embora o Iesous junto-a o sumo-sacerdote e reúnem-se todos o sumos-sacerdotes e o anciãos e o escribas');
INSERT INTO verses VALUES (24870, 41, 14, 54, 'e o Pedro de de-longe seguiu a ele até dentro para o pátio o do-sumo-sacerdote e era sentando-se-com com o servindo e aquecendo-se junto-a o luz');
INSERT INTO verses VALUES (24871, 41, 14, 55, 'o porém sumos-sacerdotes e todo o sinédrio buscavam segundo o Iesous testemunho para o matar ele e não encontravam');
INSERT INTO verses VALUES (24872, 41, 14, 56, 'muitos pois testemunhavam-falsamente segundo dele e Iguais o testemunhos não eram');
INSERT INTO verses VALUES (24873, 41, 14, 57, 'e alguns levantando-se testemunhavam-falsamente segundo dele dizendo');
INSERT INTO verses VALUES (24874, 41, 14, 58, 'que nós ouvimos dele dizendo que eu destruirei o santuário este o feito-por-mãos e através-de três dos-dias outro não-feito-por-mãos edificarei');
INSERT INTO verses VALUES (24875, 41, 14, 59, 'e nem assim Igual era o testemunho deles');
INSERT INTO verses VALUES (24876, 41, 14, 60, 'e levantando-se o sumo-sacerdote para meio perguntou o Iesous dizendo não respondes nada quê estes teu testemunham-contra');
INSERT INTO verses VALUES (24877, 41, 14, 61, 'o porém calava-se e não respondeu nada novamente o sumo-sacerdote perguntava ele e diz a ele tu és o Christos o Filho o Bendito');
INSERT INTO verses VALUES (24878, 41, 14, 62, 'o porém Iesous disse Eu sou e vereis o Filho o do-homem de direita sentado o do-poder e o-que-vem com o nuvens o do-céu');
INSERT INTO verses VALUES (24879, 41, 14, 63, 'o porém sumo-sacerdote tendo-rasgado o túnicas dele diz quê ainda necessidade temos testemunhas');
INSERT INTO verses VALUES (24880, 41, 14, 64, 'ouvistes o blasfêmia quê a-vós aparece o porém todos condenaram ele Réu ser da-morte');
INSERT INTO verses VALUES (24881, 41, 14, 65, 'e Começaram alguns cuspir a ele e cobrir dele o rosto e esbofetear ele e dizer a ele Profetiza e o servos bofetadas ele receberam');
INSERT INTO verses VALUES (24882, 41, 14, 66, 'e sendo o de-Pedro abaixo em o pátio vem uma o servas o do-sumo-sacerdote');
INSERT INTO verses VALUES (24883, 41, 14, 67, 'e vendo o Pedro aquecendo-se tendo-olhado-fixamente a ele diz e tu com o Nazareno eras o Iesous');
INSERT INTO verses VALUES (24884, 41, 14, 68, 'o porém negou dizendo Nem sei nem conheço tu quê dizes e saiu fora para o pátio-exterior');
INSERT INTO verses VALUES (24885, 41, 14, 69, 'e o serva vendo ele começou novamente dizer o estejam-de-pé que este de deles é');
INSERT INTO verses VALUES (24886, 41, 14, 70, 'o porém novamente negava e com pouco novamente o estando-de-pé diziam o a-Pedro Verdadeiramente de deles és e pois Galileu és');
INSERT INTO verses VALUES (24887, 41, 14, 71, 'o porém começou amaldiçoar e jurar que não sei o homem este o qual dizeis');
INSERT INTO verses VALUES (24888, 41, 14, 72, 'e imediatamente de segundo galo chamou e lembrou-se o Pedro o palavra como disse a ele o Iesous que Antes-que galo duas-vezes chamar três-vezes me negará e tendo-lançado-sobre chorava');
INSERT INTO chapters VALUES (972, 41, 15, 46);
INSERT INTO verses VALUES (24889, 41, 15, 1, 'e imediatamente de-manhã conselho Tendo-preparado o sumos-sacerdotes com o dos-anciãos e dos-escribas e todo o sinédrio tendo-amarrado o Iesous levaram e entregaram Pilatos');
INSERT INTO verses VALUES (24890, 41, 15, 2, 'e perguntou ele o Pilatos tu és o Rei o judeus o porém respondendo a ele diz tu dizes');
INSERT INTO verses VALUES (24891, 41, 15, 3, 'e acusavam dele o sumos-sacerdotes muitas-coisas');
INSERT INTO verses VALUES (24892, 41, 15, 4, 'o porém Pilatos novamente perguntava ele dizendo não respondes nada vê quantas teu acusam');
INSERT INTO verses VALUES (24893, 41, 15, 5, 'o porém Iesous não-mais nada respondeu de-modo-que admirar o Pilatos');
INSERT INTO verses VALUES (24894, 41, 15, 6, 'segundo porém festa soltava a-eles um prisioneiro o qual recusavam');
INSERT INTO verses VALUES (24895, 41, 15, 7, 'era porém o chamado Barrabás com o insurgentes amarrado os-quais em o dissensão assassinato tinham-feito');
INSERT INTO verses VALUES (24896, 41, 15, 8, 'e subindo o multidão começou pedir assim-como fazia a-eles');
INSERT INTO verses VALUES (24897, 41, 15, 9, 'o porém Pilatos respondeu a-eles dizendo quereis soltarei a-vós o Rei o judeus');
INSERT INTO verses VALUES (24898, 41, 15, 10, 'conhecia pois que através-de inveja tinham-entregado ele o sumos-sacerdotes');
INSERT INTO verses VALUES (24899, 41, 15, 11, 'o porém sumos-sacerdotes agitaram o multidão para que mais o Barrabás solte a-eles');
INSERT INTO verses VALUES (24900, 41, 15, 12, 'o porém Pilatos novamente respondendo dizia a-eles quê portanto farei o qual dizeis o Rei o judeus');
INSERT INTO verses VALUES (24901, 41, 15, 13, 'o porém novamente clamaram Crucifica ele');
INSERT INTO verses VALUES (24902, 41, 15, 14, 'o porém Pilatos dizia a-eles quê pois fez mal o porém abundantemente clamaram Crucifica ele');
INSERT INTO verses VALUES (24903, 41, 15, 15, 'o porém Pilatos querendo o à-multidão o suficiente fazer soltou a-eles o Barrabás e entregou o Iesous tendo-açoitado para que seja-crucificado');
INSERT INTO verses VALUES (24904, 41, 15, 16, 'o porém soldados levaram-embora ele dentro o pátio o qual é Pretório e convocam toda o coorte');
INSERT INTO verses VALUES (24905, 41, 15, 17, 'e vestem ele púrpura e colocam-ao-redor a ele tendo-trançado de-espinhos coroa');
INSERT INTO verses VALUES (24906, 41, 15, 18, 'e começaram saudar ele Alegra-te Rei o judeus');
INSERT INTO verses VALUES (24907, 41, 15, 19, 'e batiam dele o cabeça cana e cuspiam-em a ele e pondo o joelhos prostavam-se a ele');
INSERT INTO verses VALUES (24908, 41, 15, 20, 'e quando zombaram a ele despiram ele o púrpura e vestiram ele o vestes dele e conduzem-para-fora ele para que crucifiquem ele');
INSERT INTO verses VALUES (24909, 41, 15, 21, 'e obrigam-a-servir passando alguém Simão Cireneu o-que-vem de campo o Pai Alexandre e Rufo para que levante o cruz dele');
INSERT INTO verses VALUES (24910, 41, 15, 22, 'e trazem ele sobre o Gólgota lugar o qual é sendo-traduzido Crânio lugar');
INSERT INTO verses VALUES (24911, 41, 15, 23, 'e davam a ele Tendo-sido-misturado-com-mirra vinho o qual porém não recebeu');
INSERT INTO verses VALUES (24912, 41, 15, 24, 'e crucificam ele e dividem o vestes dele lançando sorte sobre eles quem quê levante');
INSERT INTO verses VALUES (24913, 41, 15, 25, 'era porém hora terceira e crucificaram ele');
INSERT INTO verses VALUES (24914, 41, 15, 26, 'e era o inscrição o causa dele tendo-sido-inscrita o REI o JUDEUS');
INSERT INTO verses VALUES (24915, 41, 15, 27, 'e com a ele crucificam dois salteadores um de direita e um de esquerda dele');
INSERT INTO verses VALUES (24916, 41, 15, 29, 'e o passando-ao-lado blasfemavam ele movendo o cabeças deles e dizendo Ah o destruindo o santuário e edificando em três dias');
INSERT INTO verses VALUES (24917, 41, 15, 30, 'salva a-ti-mesmo descendo de o da-cruz');
INSERT INTO verses VALUES (24918, 41, 15, 31, 'semelhantemente e o sumos-sacerdotes zombando junto-a uns-aos-outros com o dos-escribas diziam Outros salvou si-mesmo não pode salvar');
INSERT INTO verses VALUES (24919, 41, 15, 32, 'o Christos o Rei Israel desça agora de o da-cruz para que vejamos e creiamos e o tendo-sido-co-crucificados com a ele injuriavam ele');
INSERT INTO verses VALUES (24920, 41, 15, 33, 'e tendo-acontecido hora sexta trevas aconteceu sobre toda o terra até hora nona');
INSERT INTO verses VALUES (24921, 41, 15, 34, 'e o nona hora clamou o Iesous com-voz grande Eloí Eloí lama sabactâni o qual é sendo-traduzido o Theos meu o Theos meu para quê abandonaste me');
INSERT INTO verses VALUES (24922, 41, 15, 35, 'e alguns o tendo-estado-de-pé ouvindo diziam Vê Elias chama');
INSERT INTO verses VALUES (24923, 41, 15, 36, 'tendo-corrido e/mas alguém e tendo-enchido esponja vinagre tendo-posto-ao-redor cana dava-de-beber ele dizendo Deixai vejamos se vem Elias derrubar ele');
INSERT INTO verses VALUES (24924, 41, 15, 37, 'o porém Iesous deixando voz grande expirou');
INSERT INTO verses VALUES (24925, 41, 15, 38, 'e o véu o santuário rasgou-se para dois de de-cima até abaixo');
INSERT INTO verses VALUES (24926, 41, 15, 39, 'Vendo porém o centurião o tendo-estado-de-pé de contrária dele que assim expirou disse Verdadeiramente este o homem Filho de-Theos era');
INSERT INTO verses VALUES (24927, 41, 15, 40, 'eram porém e mulheres de de-longe contemplando em o qual e Maria o Madalena e Maria o de-Tiago o pequeno e José mãe e Salomé');
INSERT INTO verses VALUES (24928, 41, 15, 41, 'o qual quando era em o Galileia seguiam a ele e serviam a ele e outras muitas o tendo-subido-junto a ele para Jerusalém');
INSERT INTO verses VALUES (24929, 41, 15, 42, 'e já tarde tendo-acontecido porque era Preparação o qual é véspera-de-sábado');
INSERT INTO verses VALUES (24930, 41, 15, 43, 'vindo José o de Arimateia decoroso conselheiro o qual e ele era esperando o reino o de-Theos tendo-ousado entrou junto-a o Pilatos e pediu o corpo o Iesous');
INSERT INTO verses VALUES (24931, 41, 15, 44, 'o porém Pilatos admirou-se se já tem-morrido e tendo-chamado o centurião perguntou ele se outrora morreu');
INSERT INTO verses VALUES (24932, 41, 15, 45, 'e sabendo de o centurião concedeu o cadáver o José');
INSERT INTO verses VALUES (24933, 41, 15, 46, 'e tendo-comprado linho tendo-derrubado ele envolveu o linho e depositou ele em sepulcro o qual era tendo-sido-cavado-em-rocha de rocha e rolou-para pedra sobre o porta o sepulcro');
INSERT INTO verses VALUES (24934, 41, 15, 47, 'o porém Maria o Madalena e Maria o José observavam onde tem-sido-posto');
INSERT INTO chapters VALUES (973, 41, 16, 21);
INSERT INTO verses VALUES (24935, 41, 16, 1, 'e tendo-passado o do-sábado Maria o Madalena e Maria o o de-Tiago e Salomé compraram aromas para que tendo-vindo unjam ele');
INSERT INTO verses VALUES (24936, 41, 16, 2, 'e muito de-manhã o uma o sábados vêm sobre o sepulcro tendo-nascido o sol');
INSERT INTO verses VALUES (24937, 41, 16, 3, 'e diziam junto-a si-mesmas Quem rolará a-nós o pedra de o porta o sepulcro');
INSERT INTO verses VALUES (24938, 41, 16, 4, 'e tendo-olhado-para-cima contemplam que tem-sido-rolado o pedra era pois grande grandemente');
INSERT INTO verses VALUES (24939, 41, 16, 5, 'e tendo-entrado para o túmulo vi jovem sentado em o direitos tendo-sido-vestido veste-longa branca e ficaram-muito-assombrados');
INSERT INTO verses VALUES (24940, 41, 16, 6, 'o porém diz a-elas não estais-grandemente-espantadas Iesous buscais o Nazareno o crucificado foi-ressuscitado não é aqui vê o lugar onde puseram ele');
INSERT INTO verses VALUES (24941, 41, 16, 7, 'mas ide dizei o discípulos dele e o a-Pedro que Precede vos para o Galileia ali ele vereis assim-como disse a-vós');
INSERT INTO verses VALUES (24942, 41, 16, 8, 'e tendo-saído fugiram de o sepulcro tinha pois a-elas tremor e êxtase e a-ninguém nada disseram temiam pois');
INSERT INTO verses VALUES (24943, 41, 16, 9, 'Levantando-se porém de-manhã primeiro do-sábado apareceu primeiro Maria o Madalena de-junto-de o qual tinha-lançado-fora sete demônios');
INSERT INTO verses VALUES (24944, 41, 16, 10, 'aquela tendo-ido anunciou o com dele tendo-acontecido lamentam e choram');
INSERT INTO verses VALUES (24945, 41, 16, 11, 'e-aqueles ouvindo que vive e foi-contemplado sob dela descreram');
INSERT INTO verses VALUES (24946, 41, 16, 12, 'com porém estas-coisas dois de deles andam foi-manifestado em outra forma aos-que-caminham para campo');
INSERT INTO verses VALUES (24947, 41, 16, 13, 'e-aqueles tendo-ido-embora anunciaram o restantes nem àqueles creram');
INSERT INTO verses VALUES (24948, 41, 16, 14, 'Depois porém reclinados a-eles o onze foi-manifestado e Censurou o incredulidade deles e dureza-de-coração que o tendo-contemplado ele tendo-sido-levantado não creram');
INSERT INTO verses VALUES (24949, 41, 16, 15, 'e disse a-eles Tendo-ido para o mundo todas-as-coisas proclamai o evangelho toda o criação');
INSERT INTO verses VALUES (24950, 41, 16, 16, 'o tendo-crido e tendo-sido-batizado será-salvo o porém tendo-desacreditado será-condenado');
INSERT INTO verses VALUES (24951, 41, 16, 17, 'sinais porém o aos-que-creram estas-coisas seguirá em o no-nome meu demônios lançarão-fora em-línguas falarão novas');
INSERT INTO verses VALUES (24952, 41, 16, 18, 'serpentes levantarão e-se mortal algo bebam não não eles danifique sobre enfermos mãos imporão e bem terão');
INSERT INTO verses VALUES (24953, 41, 16, 19, 'o por-um-lado portanto Kyrios Iesous com o falar a-eles foi-elevado para o céu e sentou-se de direita o de-Theos');
INSERT INTO verses VALUES (24954, 41, 16, 20, 'aqueles porém saindo proclamaram por-toda-parte o do-Kyrios cooperando e o palavra confirmando através-de o seguindo sinais');
INSERT INTO verses VALUES (24955, 41, 16, 99, 'todas-as-coisas porém o as-coisas-tendo-sido-ordenadas o acerca-de o Pedro brevemente anunciaram com porém estas-coisas e ele o Iesous de oriente e até ocidente enviou-embora através-de deles o templo e incorruptível pregação o eterno salvação');
INSERT INTO books VALUES (42, 'LUK', 'Lucas', 'NT', 24);
INSERT INTO chapters VALUES (974, 42, 1, 80);
INSERT INTO verses VALUES (24956, 42, 1, 1, 'Visto-que muitos empreenderam compor-em-ordem narração acerca-de o tendo-sido-plenamente-asseguradas em a-nós coisas');
INSERT INTO verses VALUES (24957, 42, 1, 2, 'assim-como entregaram a-nós o de princípio testemunhas-oculares e servos tendo-se-tornado o da-palavra');
INSERT INTO verses VALUES (24958, 42, 1, 3, 'pareceu e-a-mim ao-tendo-seguido de-cima todos com-exatidão por-ordem a-ti escrever excelentíssimo Teófilo');
INSERT INTO verses VALUES (24959, 42, 1, 4, 'para que reconheças acerca-de o qual foste-instruído palavras o segurança');
INSERT INTO verses VALUES (24960, 42, 1, 5, 'aconteceu em o dias de-Herodes rei o Judeia sacerdote alguém em-nome Zacarias de divisão-sacerdotal Abia e mulher a ele de o filhas Aarão e o nome dela Elisabete');
INSERT INTO verses VALUES (24961, 42, 1, 6, 'eram porém justos ambos diante-de o de-Theos indo em todas o mandamentos e ordenanças o do-Kyrios irrepreensíveis');
INSERT INTO verses VALUES (24962, 42, 1, 7, 'e não era a-eles filho assim-como era o Elisabete estéril e ambos tendo-avançado-em-idade em o dias deles eram');
INSERT INTO verses VALUES (24963, 42, 1, 8, 'aconteceu porém em o exercer-sacerdócio ele em o em-ordem o divisão-sacerdotal dele diante-de o de-Theos');
INSERT INTO verses VALUES (24964, 42, 1, 9, 'segundo o costume o Sacerdócio Obteve-por-sorte o queimar-incenso entrando para o templo o do-Kyrios');
INSERT INTO verses VALUES (24965, 42, 1, 10, 'e todo o multidão era o povo orando fora o hora o incenso');
INSERT INTO verses VALUES (24966, 42, 1, 11, 'apareceu porém a ele anjo do-Kyrios estando-de-pé de direita o altar o incenso');
INSERT INTO verses VALUES (24967, 42, 1, 12, 'e perturbou-se Zacarias tendo-visto e medo caiu-sobre sobre ele');
INSERT INTO verses VALUES (24968, 42, 1, 13, 'disse porém junto-a ele o anjo não temas Zacarias porque foi-ouvido o súplica teu e o mulher teu Elisabete gerará filho a-ti e chamarás o nome dele João');
INSERT INTO verses VALUES (24969, 42, 1, 14, 'e será alegria a-ti e exultação e muitos sobre o nascimento dele alegrar-se-ão');
INSERT INTO verses VALUES (24970, 42, 1, 15, 'será pois grande diante-de do-Kyrios e vinho e bebida-forte não não beba e do-espírito do-santo será-enchido ainda de ventre mãe dele');
INSERT INTO verses VALUES (24971, 42, 1, 16, 'e a-muitos o filhos Israel converterá sobre Kyrion o Theos deles');
INSERT INTO verses VALUES (24972, 42, 1, 17, 'e ele irá-adiante diante-de dele em espírito e poder Elias converter do-coração dos-pais sobre filhos e desobedientes em prudência justos preparar ao-Kyrios povo tendo-sido-preparado');
INSERT INTO verses VALUES (24973, 42, 1, 18, 'e disse Zacarias junto-a o anjo segundo quê conhecerei isto eu pois sou ancião e o mulher meu tendo-avançado em o dias dela');
INSERT INTO verses VALUES (24974, 42, 1, 19, 'e respondendo o anjo disse a ele Eu sou Gabriel o tendo-estado-de-pé diante-de o de-Theos e fui-enviado falar junto-a te e ter-anunciado-boa-nova a-ti estas-coisas');
INSERT INTO verses VALUES (24975, 42, 1, 20, 'e eis serás calando e não podendo falar até o qual do-dia aconteça estas-coisas em-vez-de o qual não creste o palavras meu os-quais serão-cumpridos para o tempo deles');
INSERT INTO verses VALUES (24976, 42, 1, 21, 'e era o povo esperando o Zacarias e admiravam-se em o demorar em o templo ele');
INSERT INTO verses VALUES (24977, 42, 1, 22, 'saindo porém não podia falar a-eles e reconheceram que visão tem-visto em o templo e ele era acenando a-eles e permanecia mudo');
INSERT INTO verses VALUES (24978, 42, 1, 23, 'e aconteceu como foram-cheios o dias o serviço dele partiu para o casa dele');
INSERT INTO verses VALUES (24979, 42, 1, 24, 'com porém estas o do-dia concebeu Elisabete o mulher dele e escondia-se a-si-mesma meses cinco dizendo');
INSERT INTO verses VALUES (24980, 42, 1, 25, 'que assim a-mim tem-feito Kyrios em dias o qual olhou-sobre tirar opróbrio meu em aos-homens');
INSERT INTO verses VALUES (24981, 42, 1, 26, 'em porém o mês o sexto foi-enviado o anjo Gabriel de o de-Theos para cidade o Galileia o qual nome Nazaré');
INSERT INTO verses VALUES (24982, 42, 1, 27, 'junto-a virgem tendo-sido-prometida-em-casamento marido o qual nome José de da-casa Davi e o nome o de-virgem Miriam');
INSERT INTO verses VALUES (24983, 42, 1, 28, 'e entrando junto-a ela disse Alegra-te tendo-sido-agraciada o Kyrios com teu');
INSERT INTO verses VALUES (24984, 42, 1, 29, 'o porém sobre o em-palavra perturbou-se e deliberava que-tipo-de seria o saudação este');
INSERT INTO verses VALUES (24985, 42, 1, 30, 'e disse o anjo a-ela não temas Miriam encontraste pois graça de-junto-de o a-Theos');
INSERT INTO verses VALUES (24986, 42, 1, 31, 'e eis conceberás em ventre e dará-à-luz filho e chamarás o nome dele Iesous');
INSERT INTO verses VALUES (24987, 42, 1, 32, 'este será grande e Filho Altíssimo será-chamado e dará a ele Kyrios o Theos o trono Davi o do-Pai dele');
INSERT INTO verses VALUES (24988, 42, 1, 33, 'e reinará sobre o casa Jacó para o eras e o do-reino dele não será fim');
INSERT INTO verses VALUES (24989, 42, 1, 34, 'disse porém Maria junto-a o anjo como será isto porque homem não conheço');
INSERT INTO verses VALUES (24990, 42, 1, 35, 'e respondendo o anjo disse a-ela espírito santo sobrevirá sobre te e poder Altíssimo fará-sombra-sobre a-ti por-isso e o sendo-gerado santo será-chamado Filho de-Theos');
INSERT INTO verses VALUES (24991, 42, 1, 36, 'e eis Elisabete o parenta teu e ela concebeu Filho em velhice dela e este certamente sexto é a-ela o chamada estéril');
INSERT INTO verses VALUES (24992, 42, 1, 37, 'que não será-impossível de-junto-de o de-Theos todo palavra');
INSERT INTO verses VALUES (24993, 42, 1, 38, 'disse porém Miriam Eis o escrava do-Kyrios seja a-mim segundo o palavra teu e partiu de dela o anjo');
INSERT INTO verses VALUES (24994, 42, 1, 39, 'Tendo-se-levantado porém Maria em o dias estas foi para o montanhosa com diligência para cidade Judá');
INSERT INTO verses VALUES (24995, 42, 1, 40, 'e entrou para o casa Zacarias e Saudou o Elisabete');
INSERT INTO verses VALUES (24996, 42, 1, 41, 'e aconteceu como ouviu o saudação o Maria o Elisabete saltou o bebê em o ventre dela e encheu-se do-espírito do-santo o Elisabete');
INSERT INTO verses VALUES (24997, 42, 1, 42, 'e exclamou clamor grande e disse Tendo-sido-abençoada tu em mulheres e tendo-sido-bendito o fruto o ventre teu');
INSERT INTO verses VALUES (24998, 42, 1, 43, 'e de-onde a-mim isto para que venha o mãe o do-Kyrios meu junto-a me');
INSERT INTO verses VALUES (24999, 42, 1, 44, 'eis pois como aconteceu o voz o saudação teu para o Orelhas meu saltou em exultação o bebê em o ventre meu');
INSERT INTO verses VALUES (25000, 42, 1, 45, 'e bem-aventurada o tendo-crido que será perfeição o tendo-sido-falados a-ela de-junto-de do-Kyrios');
INSERT INTO verses VALUES (25001, 42, 1, 46, 'e disse Miriam Engrandece o alma meu o Kyrion');
INSERT INTO verses VALUES (25002, 42, 1, 47, 'e exultou o espírito meu sobre o a-Theos o Salvador meu');
INSERT INTO verses VALUES (25003, 42, 1, 48, 'que olhou-sobre sobre o humilhação o escrava dele eis pois de o agora chamarão-bem-aventurada me todas o gerações');
INSERT INTO verses VALUES (25004, 42, 1, 49, 'que fez a-mim grandes o poderoso e santo o nome dele');
INSERT INTO verses VALUES (25005, 42, 1, 50, 'e o misericórdia dele para gerações e gerações o aos-que-temem ele');
INSERT INTO verses VALUES (25006, 42, 1, 51, 'fez domínio em braço dele dispersou soberbos entendimento do-coração deles');
INSERT INTO verses VALUES (25007, 42, 1, 52, 'derrubou poderosos de tronos e exaltou humildes');
INSERT INTO verses VALUES (25008, 42, 1, 53, 'tendo-fome encheu boas-coisas e enriquecendo enviou-embora vazios');
INSERT INTO verses VALUES (25009, 42, 1, 54, 'socorreu Israel servo dele lembrar-se misericórdia');
INSERT INTO verses VALUES (25010, 42, 1, 55, 'assim-como falou junto-a o pais nosso o Abraão e o semente dele para o eternidade');
INSERT INTO verses VALUES (25011, 42, 1, 56, 'Permaneceu porém Maria com a-ela como meses três e retornou para o casa dela');
INSERT INTO verses VALUES (25012, 42, 1, 57, 'o porém Elisabete encheu-se o tempo o dar-à-luz ela e gerou filho');
INSERT INTO verses VALUES (25013, 42, 1, 58, 'e ouviram o vizinhos e o parentes dela que engrandeceu Kyrios o misericórdia dele com dela e alegravam-se-com a-ela');
INSERT INTO verses VALUES (25014, 42, 1, 59, 'e aconteceu em o dia o oitavo vieram circuncidar o criança e chamavam ele sobre o em-nome o do-Pai dele Zacarias');
INSERT INTO verses VALUES (25015, 42, 1, 60, 'e tendo-respondido o mãe dele disse não mas será-chamado João');
INSERT INTO verses VALUES (25016, 42, 1, 61, 'e disseram junto-a ela que ninguém é de o parentela teu o qual chama-se o em-nome neste');
INSERT INTO verses VALUES (25017, 42, 1, 62, 'faziam-sinais porém o pai dele o quê partícula-condicional quisesse ser-chamado isso');
INSERT INTO verses VALUES (25018, 42, 1, 63, 'e tendo-pedido tabuinha escreveu dizendo João é nome dele e admiraram-se todos');
INSERT INTO verses VALUES (25019, 42, 1, 64, 'foi-aberto porém o boca dele imediatamente e o língua dele e falava bendizendo o Theos');
INSERT INTO verses VALUES (25020, 42, 1, 65, 'e aconteceu sobre todos medo o habitando-ao-redor eles e em toda o montanhosa o Judeia era-comentado todas-as-coisas o palavras estas-coisas');
INSERT INTO verses VALUES (25021, 42, 1, 66, 'e puseram todos o ouvindo em o no-coração deles dizendo quê então o criança isto será e pois mão do-Kyrios era com dele');
INSERT INTO verses VALUES (25022, 42, 1, 67, 'e Zacarias o Pai dele encheu-se do-espírito do-santo e profetizou dizendo');
INSERT INTO verses VALUES (25023, 42, 1, 68, 'Bendito Kyrios o Theos o Israel que visitou e fez redenção o povo dele');
INSERT INTO verses VALUES (25024, 42, 1, 69, 'e ressuscitou chifre salvação a-nós em na-casa Davi servo dele');
INSERT INTO verses VALUES (25025, 42, 1, 70, 'assim-como falou através-de boca o santos de eternidade profetas dele');
INSERT INTO verses VALUES (25026, 42, 1, 71, 'salvação de inimigos nosso e de mão todos o odiando nos');
INSERT INTO verses VALUES (25027, 42, 1, 72, 'fazer misericórdia com o dos-pais nosso e lembrar-se da-aliança santa dele');
INSERT INTO verses VALUES (25028, 42, 1, 73, 'juramento o qual jurou junto-a Abraão o Pai nosso o dar a-nós');
INSERT INTO verses VALUES (25029, 42, 1, 74, 'sem-temor de mão inimigos tendo-sido-livrados servir-cultualmente a ele');
INSERT INTO verses VALUES (25030, 42, 1, 75, 'em santidade e justiça diante-de dele todas o dias nosso');
INSERT INTO verses VALUES (25031, 42, 1, 76, 'e tu e/mas criança profeta Altíssimo serás-chamado irás-adiante pois diante-de do-Kyrios preparar caminhos dele');
INSERT INTO verses VALUES (25032, 42, 1, 77, 'o dar saibam salvação o povo dele em perdão pecados deles');
INSERT INTO verses VALUES (25033, 42, 1, 78, 'através-de entranhas misericórdia de-Theos nosso em o qual visitará nos oriente de altura');
INSERT INTO verses VALUES (25034, 42, 1, 79, 'Resplandecer o em trevas e sombra da-morte sentados o dirigir o pés nosso para caminho paz');
INSERT INTO verses VALUES (25035, 42, 1, 80, 'o porém criança crescia e fortalecia-se espírito e era em o desertos até do-dia manifestação dele junto-a o Israel');
INSERT INTO chapters VALUES (975, 42, 2, 52);
INSERT INTO verses VALUES (25036, 42, 2, 1, 'aconteceu porém em o dias aqueles saiu decreto de-junto-de de-César Augusto ser-registrado toda o mundo-habitado');
INSERT INTO verses VALUES (25037, 42, 2, 2, 'esta registro primeiro aconteceu governando o Síria Quirínio');
INSERT INTO verses VALUES (25038, 42, 2, 3, 'e iam todos ser-registrado cada-um para o si-mesmo cidade');
INSERT INTO verses VALUES (25039, 42, 2, 4, 'subiu porém e José de o Galileia de cidade Nazaré para o Judeia para cidade Davi a-qual chama-se Belém através-de o ser ele de da-casa e família Davi');
INSERT INTO verses VALUES (25040, 42, 2, 5, 'ser-registrado com Maria o tendo-sido-prometida-em-casamento a ele estando grávida');
INSERT INTO verses VALUES (25041, 42, 2, 6, 'aconteceu porém em o ser eles ali foram-cheios o dias o dar-à-luz ela');
INSERT INTO verses VALUES (25042, 42, 2, 7, 'e deu-à-luz o Filho dela o primogênito e Envolveu-em-panos ele e reclinou ele em manjedoura porque não era a-eles lugar em o hospedaria');
INSERT INTO verses VALUES (25043, 42, 2, 8, 'e pastores eram em o região o a-ela vivendo-no-campo e guardando guardas o noite sobre o rebanho deles');
INSERT INTO verses VALUES (25044, 42, 2, 9, 'e anjo do-Kyrios apresentou-se a-eles e glória do-Kyrios resplandeceu-ao-redor eles e temeram medo grande');
INSERT INTO verses VALUES (25045, 42, 2, 10, 'e disse a-eles o anjo não temei eis pois anuncio-boas-novas a-vós alegria grande a-qual será todo o povo');
INSERT INTO verses VALUES (25046, 42, 2, 11, 'que Foi-gerado a-vós hoje Salvador o qual é Christos Kyrios em cidade Davi');
INSERT INTO verses VALUES (25047, 42, 2, 12, 'e isto a-vós sinal encontrareis bebê Tendo-sido-envolto-em-panos e posto em manjedoura');
INSERT INTO verses VALUES (25048, 42, 2, 13, 'e subitamente aconteceu com o anjo multidão exército celestial louvando o Theos e dizendo');
INSERT INTO verses VALUES (25049, 42, 2, 14, 'glória em alturas a-Theos e sobre da-terra paz em aos-homens boa-vontade');
INSERT INTO verses VALUES (25050, 42, 2, 15, 'e aconteceu como foram de deles para o céu o anjo o pastores falavam junto-a uns-aos-outros Passemos-ao-outro-lado pois até Belém e vejamos o palavra isto o tendo-acontecido o qual o Kyrios fez-conhecer a-nós');
INSERT INTO verses VALUES (25051, 42, 2, 16, 'e vieram tendo-se-apressado e encontraram o e Maria e o José e o bebê posto em o manjedoura');
INSERT INTO verses VALUES (25052, 42, 2, 17, 'vendo porém fizeram-conhecer acerca-de o palavra o tendo-sido-falado a-eles acerca-de o criança deste');
INSERT INTO verses VALUES (25053, 42, 2, 18, 'e todos o ouvindo admiraram-se acerca-de o tendo-sido-falados sob o pastores junto-a eles');
INSERT INTO verses VALUES (25054, 42, 2, 19, 'o porém Maria todas-as-coisas guardava-junto o palavras estas-coisas ponderando em o no-coração dela');
INSERT INTO verses VALUES (25055, 42, 2, 20, 'e retornaram o pastores glorificando e louvando o Theos sobre todos o qual ouviram e vi assim-como foi-falado junto-a eles');
INSERT INTO verses VALUES (25056, 42, 2, 21, 'e quando foram-cheios dias oito o circuncidar ele e foi-chamado o nome dele Iesous o tendo-sido-chamado sob o anjo antes-de o ser-concebido ele em o ventre');
INSERT INTO verses VALUES (25057, 42, 2, 22, 'e quando foram-cheios o dias o purificação deles segundo o lei Moisés conduziram-para-cima ele para Jerusalém apresentar o ao-Kyrios');
INSERT INTO verses VALUES (25058, 42, 2, 23, 'assim-como está-escrito em lei do-Kyrios que todo macho abrindo ventre santo o ao-Kyrios será-chamado');
INSERT INTO verses VALUES (25059, 42, 2, 24, 'e o dar sacrifício segundo o dito em o lei do-Kyrios par rolas ou dois filhotes pombas');
INSERT INTO verses VALUES (25060, 42, 2, 25, 'e eis homem era em Jerusalém o qual nome Simeão e o homem este justo e piedoso esperando consolação o Israel e espírito era santo sobre ele');
INSERT INTO verses VALUES (25061, 42, 2, 26, 'e era a ele tendo-sido-revelado sob o do-espírito o do-santo não ver morte antes-de ou partícula-condicional veja o Christos do-Kyrios');
INSERT INTO verses VALUES (25062, 42, 2, 27, 'e veio em o Espírito para o templo e em o introduzir o pais o criança Iesous o fazer eles segundo o tendo-sido-acostumado o da-lei acerca-de dele');
INSERT INTO verses VALUES (25063, 42, 2, 28, 'e ele recebeu ele para o braços e abençoou o Theos e disse');
INSERT INTO verses VALUES (25064, 42, 2, 29, 'agora soltas o escravo teu Soberano segundo o palavra teu em paz');
INSERT INTO verses VALUES (25065, 42, 2, 30, 'que vi o olhos meu o salvação teu');
INSERT INTO verses VALUES (25066, 42, 2, 31, 'o qual preparaste segundo face todos o povos');
INSERT INTO verses VALUES (25067, 42, 2, 32, 'luz para revelação nações e glória povo teu Israel');
INSERT INTO verses VALUES (25068, 42, 2, 33, 'e era o Pai dele e o mãe admirando sobre o coisas-faladas acerca-de dele');
INSERT INTO verses VALUES (25069, 42, 2, 34, 'e abençoou eles Simeão e disse junto-a Maria o mãe dele Eis este está-posto para queda e ressurreição muitos em o Israel e para sinal sendo-contradito');
INSERT INTO verses VALUES (25070, 42, 2, 35, 'e teu porém dela o alma atravessará espada para-que partícula-condicional sejam-revelados de muitos corações raciocínios');
INSERT INTO verses VALUES (25071, 42, 2, 36, 'e era Ana profetisa filha Fanuel de tribo Aser esta tendo-avançado em dias muitas tendo-vivido com homem anos sete de o de-virgindade dela');
INSERT INTO verses VALUES (25072, 42, 2, 37, 'e ela viúva até anos oitenta quatro o qual não afastava-se o do-templo jejuns e súplicas servindo noite e dia');
INSERT INTO verses VALUES (25073, 42, 2, 38, 'e a-ela o hora tendo-se-apresentado dava-graças o a-Theos e falava acerca-de dele todos o esperando redenção Jerusalém');
INSERT INTO verses VALUES (25074, 42, 2, 39, 'e como completaram todas-as-coisas o segundo o lei do-Kyrios voltaram para o Galileia para cidade deles-mesmos Nazaré');
INSERT INTO verses VALUES (25075, 42, 2, 40, 'o porém criança crescia e fortalecia-se sendo-preenchido com-sabedoria e graça de-Theos era sobre isso');
INSERT INTO verses VALUES (25076, 42, 2, 41, 'e iam o pais dele segundo ano para Jerusalém o festa o páscoa');
INSERT INTO verses VALUES (25077, 42, 2, 42, 'e quando aconteceu anos doze subindo deles segundo o costume o festa');
INSERT INTO verses VALUES (25078, 42, 2, 43, 'e tendo-aperfeiçoado o do-dia em o retornar eles perseverou Iesous o servo em Jerusalém e não conheceram o pais dele');
INSERT INTO verses VALUES (25079, 42, 2, 44, 'tendo-suposto porém ele ser em o caravana vieram do-dia caminho e buscavam ele em o parentes e o conhecidos');
INSERT INTO verses VALUES (25080, 42, 2, 45, 'e não tendo-encontrado retornaram para Jerusalém buscando ele');
INSERT INTO verses VALUES (25081, 42, 2, 46, 'e aconteceu com do-dia três encontraram ele em o templo sentando-se em no-meio o mestres e ouvindo deles e perguntando eles');
INSERT INTO verses VALUES (25082, 42, 2, 47, 'ficavam-fora-de-si porém todos o ouvindo dele sobre o entendimento e o respostas dele');
INSERT INTO verses VALUES (25083, 42, 2, 48, 'e vendo ele ficaram-atônitos e disse junto-a ele o mãe dele filho quê fizeste a-nós assim eis o Pai teu e-eu sendo-atormentados buscamos te');
INSERT INTO verses VALUES (25084, 42, 2, 49, 'e disse junto-a eles quê que buscáveis me não sei que em o o Pai meu é necessário ser me');
INSERT INTO verses VALUES (25085, 42, 2, 50, 'e eles-mesmos não compreenderam o palavra o qual falou a-eles');
INSERT INTO verses VALUES (25086, 42, 2, 51, 'e desceu com deles e veio para Nazaré e era Sujeitando-se a-eles e o mãe dele guardava todas-as-coisas o palavras em o no-coração dela');
INSERT INTO verses VALUES (25087, 42, 2, 52, 'e Iesous progredia em o com-sabedoria e estatura e graça de-junto-de a-Theos e aos-homens');
INSERT INTO chapters VALUES (976, 42, 3, 38);
INSERT INTO verses VALUES (25088, 42, 3, 1, 'em Ano porém décimo-quinto o Governo Tibério de-César governando Pôncio Pilatos o Judeia e sendo-tetrarca o Galileia de-Herodes Filipe porém o do-irmão dele sendo-tetrarca o Itureia e Traconites região e Lisânias o Abilene sendo-tetrarca');
INSERT INTO verses VALUES (25089, 42, 3, 2, 'sobre do-sumo-sacerdote Ana e Caifás aconteceu palavra de-Theos sobre João o Zacarias Filho em o deserto');
INSERT INTO verses VALUES (25090, 42, 3, 3, 'e veio para toda o região-ao-redor o Jordão pregando batismo arrependimento para perdão pecados');
INSERT INTO verses VALUES (25091, 42, 3, 4, 'como está-escrito em livro palavras Isaías o profeta voz clamando em o deserto Preparai o caminho do-Kyrios retas fazei o caminhos dele');
INSERT INTO verses VALUES (25092, 42, 3, 5, 'toda vale será-cumprido e todo monte e colina será-humilhado e será o tortuosas para retas e o ásperas para caminhos lisa');
INSERT INTO verses VALUES (25093, 42, 3, 6, 'e verá toda carne o salvação o de-Theos');
INSERT INTO verses VALUES (25094, 42, 3, 7, 'Dizia portanto o saindo às-multidões ser-batizado sob dele Crias víboras quem mostrou a-vós fugir de o está-para ira');
INSERT INTO verses VALUES (25095, 42, 3, 8, 'fazei portanto frutos dignos o arrependimento e não comeceis dizer em si-mesmos Pai temos o Abraão digo pois a-vós que pode o Theos de o pedras destes levanta filhos o Abraão');
INSERT INTO verses VALUES (25096, 42, 3, 9, 'já porém e o machado junto-a o raiz o árvores está-posto todo portanto árvore não fazendo fruto belo é-cortado e para fogo é-lançado');
INSERT INTO verses VALUES (25097, 42, 3, 10, 'e perguntavam ele o multidões dizendo quê portanto façamos');
INSERT INTO verses VALUES (25098, 42, 3, 11, 'respondendo porém dizia a-eles o tendo dois túnicas reparta o não tendo e o tendo alimentos semelhantemente faça');
INSERT INTO verses VALUES (25099, 42, 3, 12, 'vieram porém e cobradores-de-impostos ser-batizado e disseram junto-a ele Mestre quê façamos');
INSERT INTO verses VALUES (25100, 42, 3, 13, 'o porém disse junto-a eles nada mais de-junto-de o tendo-sido-designado a-vós praticais');
INSERT INTO verses VALUES (25101, 42, 3, 14, 'perguntavam porém ele e guerreando dizendo quê façamos e nós e disse a-eles ninguém extorquais nem extorquais e contentai-vos o soldos vosso');
INSERT INTO verses VALUES (25102, 42, 3, 15, 'Esperando porém o povo e raciocinando todos em o corações deles acerca-de o João não alguma-vez ele seria o Christos');
INSERT INTO verses VALUES (25103, 42, 3, 16, 'respondeu dizendo todos o João eu por-um-lado água batizo vos vem porém o mais-forte meu o qual não sou digno abrir o correia o sandálias dele ele vos batizará em Espírito no-santo e fogo');
INSERT INTO verses VALUES (25104, 42, 3, 17, 'o qual o pá em o mão dele limpar-completamente o eira dele e reunir o trigo para o celeiro dele o porém palha queimará fogo inextinguível');
INSERT INTO verses VALUES (25105, 42, 3, 18, 'muitos por-um-lado portanto e outras exortando anunciava-boa-nova o povo');
INSERT INTO verses VALUES (25106, 42, 3, 19, 'o porém Herodes o tetrarca sendo-repreendido sob dele acerca-de Herodíades o mulher o do-irmão dele e acerca-de todos o qual fez maus o Herodes');
INSERT INTO verses VALUES (25107, 42, 3, 20, 'acrescentou e isto sobre todos encerrou o João em na-prisão');
INSERT INTO verses VALUES (25108, 42, 3, 21, 'aconteceu porém em o ser-batizado todas-as-coisas o povo e Iesous tendo-sido-batizado e orando ser-aberto o céu');
INSERT INTO verses VALUES (25109, 42, 3, 22, 'e descer o espírito o santo corporal forma como pomba sobre ele e voz de do-céu tornar-se tu és o filho meu o amado em a-ti agradei-me');
INSERT INTO verses VALUES (25110, 42, 3, 23, 'e ele era Iesous começando como anos trinta sendo filho como era-considerado José o Eli');
INSERT INTO verses VALUES (25111, 42, 3, 24, 'o Matat o Levi o Melqui o Janai o José');
INSERT INTO verses VALUES (25112, 42, 3, 25, 'o Matatias o Amós o Naum o Esli o Nagai');
INSERT INTO verses VALUES (25113, 42, 3, 26, 'o Maate o Matatias o Semeí o José o Jodá');
INSERT INTO verses VALUES (25114, 42, 3, 27, 'o Joanã o Resa o Zorobabel o Salatiel o Neri');
INSERT INTO verses VALUES (25115, 42, 3, 28, 'o Melqui o Adi o Cosã o Elmadã o Er');
INSERT INTO verses VALUES (25116, 42, 3, 29, 'o Iesous o Eliezer o Joreim o Matat o Levi');
INSERT INTO verses VALUES (25117, 42, 3, 30, 'o Simeão o Judá o José o Jonã o Eliaquim');
INSERT INTO verses VALUES (25118, 42, 3, 31, 'o Meleia o Mená o Matata o Natã o Davi');
INSERT INTO verses VALUES (25119, 42, 3, 32, 'o Jessé o Obede o Boaz o Salá o Naassom');
INSERT INTO verses VALUES (25120, 42, 3, 33, 'o Aminadabe o Admim o Arni o Esrom o Fares o Judá');
INSERT INTO verses VALUES (25121, 42, 3, 34, 'o Jacó o Isaque o Abraão o Terá o Nacor');
INSERT INTO verses VALUES (25122, 42, 3, 35, 'o Serugue o Ragau o Faleque o Héber o Salá');
INSERT INTO verses VALUES (25123, 42, 3, 36, 'o Cainã o Arfaxade o Sem o Noé o Lameque');
INSERT INTO verses VALUES (25124, 42, 3, 37, 'o Matusalém o Enoque o Jared o Maalaleel o Cainã');
INSERT INTO verses VALUES (25125, 42, 3, 38, 'o Enos o Sete o Adão o de-Theos');
INSERT INTO chapters VALUES (977, 42, 4, 44);
INSERT INTO verses VALUES (25126, 42, 4, 1, 'Iesous porém cheio do-espírito do-santo retornou de o Jordão e Era-conduzido em o Espírito em o deserto');
INSERT INTO verses VALUES (25127, 42, 4, 2, 'do-dia quarenta tentado sob o diabo e não comeu nada em o dias aqueles e tendo-sido-completadas deles teve-fome');
INSERT INTO verses VALUES (25128, 42, 4, 3, 'disse porém a ele o diabo se Filho és o de-Theos dize o pedra neste para que aconteça pão');
INSERT INTO verses VALUES (25129, 42, 4, 4, 'e respondeu junto-a ele o Iesous está-escrito que não sobre pão somente viverá o homem');
INSERT INTO verses VALUES (25130, 42, 4, 5, 'e tendo-conduzido-para-cima ele mostrou a ele todas o do-reino o mundo-habitado em instante tempo');
INSERT INTO verses VALUES (25131, 42, 4, 6, 'e disse a ele o diabo a-ti darei o autoridade esta toda e o glória deles que mim tem-sido-entregue e o qual se quero dou ela');
INSERT INTO verses VALUES (25132, 42, 4, 7, 'tu portanto se adores diante-de mim será teu toda');
INSERT INTO verses VALUES (25133, 42, 4, 8, 'e respondendo o Iesous disse a ele está-escrito Adorarás Kyrion o Theos teu e a ele somente servirás-sagradamente');
INSERT INTO verses VALUES (25134, 42, 4, 9, 'Conduziu porém ele para Jerusalém e estabeleceu sobre o pináculo o do-templo e disse a ele se Filho és o de-Theos lança a-ti-mesmo daqui abaixo');
INSERT INTO verses VALUES (25135, 42, 4, 10, 'está-escrito pois que o anjo dele ordena acerca-de teu o guardar te');
INSERT INTO verses VALUES (25136, 42, 4, 11, 'e que sobre mãos levantarão te não alguma-vez tropeçes junto-a pedra o pé teu');
INSERT INTO verses VALUES (25137, 42, 4, 12, 'e respondendo disse a ele o Iesous que Tem-sido-dito não tentarás Kyrion o Theos teu');
INSERT INTO verses VALUES (25138, 42, 4, 13, 'e tendo-completado todas-as-coisas tentação o diabo afastou-se de dele até tempo');
INSERT INTO verses VALUES (25139, 42, 4, 14, 'e retornou o Iesous em o poder o do-espírito para o Galileia e notícia saiu segundo de-toda o região-circunvizinha acerca-de dele');
INSERT INTO verses VALUES (25140, 42, 4, 15, 'e ele ensinava em o nas-sinagogas deles sendo-glorificado sob todos');
INSERT INTO verses VALUES (25141, 42, 4, 16, 'e veio para Nazaré do-qual era tendo-sido-criado e entrou segundo o costumado a ele em o dia o sábados para o sinagoga e levantou-se ler');
INSERT INTO verses VALUES (25142, 42, 4, 17, 'e foi-entregue a ele livro o profeta Isaías e abrindo o livro encontrou o lugar do-qual era escrito');
INSERT INTO verses VALUES (25143, 42, 4, 18, 'espírito do-Kyrios sobre me o qual por-causa-de ungiu me evangelizar pobres tem-enviado me proclamar cativos perdão e cegos recuperação-da-visão enviar os-tendo-sido-quebrantados em perdão');
INSERT INTO verses VALUES (25144, 42, 4, 19, 'proclamar ano do-Kyrios aceitável');
INSERT INTO verses VALUES (25145, 42, 4, 20, 'e tendo-enrolado o livro tendo-devolvido o servo sentou-se e todos o olhos em o na-sinagoga eram fitando-os-olhos a ele');
INSERT INTO verses VALUES (25146, 42, 4, 21, 'começou porém dizer junto-a eles que Hoje foi-cumprido o escritura esta em o ouvidos vosso');
INSERT INTO verses VALUES (25147, 42, 4, 22, 'e todos testemunhavam a ele e admiravam-se sobre o palavras o da-graça o saindo de o boca dele e diziam Não filho é José este');
INSERT INTO verses VALUES (25148, 42, 4, 23, 'e disse junto-a eles Certamente Direis a-mim o parábola esta Médico cura a-ti-mesmo quanto ouvimos tendo-acontecido para o Cafarnaum faz e aqui em o pátria teu');
INSERT INTO verses VALUES (25149, 42, 4, 24, 'disse e/mas Amém digo a-vós que ninguém profeta aceitável é em o pátria dele');
INSERT INTO verses VALUES (25150, 42, 4, 25, 'sobre da-verdade porém digo a-vós muitas viúvas eram em o dias Elias em o Israel quando foi-fechado o céu sobre anos três e meses seis como aconteceu fome grande sobre toda o terra');
INSERT INTO verses VALUES (25151, 42, 4, 26, 'e junto-a nenhuma deles foi-enviado Elias se não para Sarepta o Sidônia junto-a mulher viúva');
INSERT INTO verses VALUES (25152, 42, 4, 27, 'e muitos leprosos eram em o Israel sobre Eliseu o profeta e ninguém deles foi-purificado se não Naamã o Sírio');
INSERT INTO verses VALUES (25153, 42, 4, 28, 'e foram-cheios todos ira em o na-sinagoga ouvindo estas-coisas');
INSERT INTO verses VALUES (25154, 42, 4, 29, 'e levantando-se expulsaram ele fora o cidade e levaram ele até precipício o do-monte sobre o qual o cidade Tinha-sido-edificado deles de-modo-que precipitar ele');
INSERT INTO verses VALUES (25155, 42, 4, 30, 'ele porém tendo-passado através-de meio deles ia');
INSERT INTO verses VALUES (25156, 42, 4, 31, 'e desceu para Cafarnaum cidade o Galileia e era ensinando eles em o nos-sábados');
INSERT INTO verses VALUES (25157, 42, 4, 32, 'e ficavam-espantados sobre o em-ensino dele que em em-autoridade era o palavra dele');
INSERT INTO verses VALUES (25158, 42, 4, 33, 'e em o na-sinagoga era homem tendo espírito demônio impuro e clamou com-voz grande');
INSERT INTO verses VALUES (25159, 42, 4, 34, 'Ah quê a-nós e a-ti Iesous Nazareno vieste destruir nos sei te quem és o santo o de-Theos');
INSERT INTO verses VALUES (25160, 42, 4, 35, 'e repreendeu a ele o Iesous dizendo Cala-te e sai de dele e tendo-lançado ele o demônio para o meio saiu de dele nada tendo-danificado ele');
INSERT INTO verses VALUES (25161, 42, 4, 36, 'e aconteceu espanto sobre todos e falavam-entre-si junto-a uns-aos-outros dizendo quem o palavra este que em em-autoridade e poder ordena o impuros espíritos e saem');
INSERT INTO verses VALUES (25162, 42, 4, 37, 'e saía som acerca-de dele para todas-as-coisas lugar o região-circunvizinha');
INSERT INTO verses VALUES (25163, 42, 4, 38, 'Levantando-se porém de o sinagoga entrou para o casa de-Simão sogra porém o de-Simão era sendo-constrangida febre grande e perguntaram ele acerca-de dela');
INSERT INTO verses VALUES (25164, 42, 4, 39, 'e aproximando-se sobre dela repreendeu o febre e deixou ela imediatamente porém tendo-se-levantado servia a-eles');
INSERT INTO verses VALUES (25165, 42, 4, 40, 'Pondo-se porém o sol todos quanto tinham enfermos doenças diversas levaram eles junto-a ele o porém um a-cada-um deles o mãos Tendo-posto-sobre curava eles');
INSERT INTO verses VALUES (25166, 42, 4, 41, 'saía porém e demônios de muitos clamando e dizendo que tu és o Filho o de-Theos e repreendendo não permitia elas falar que sei o Christos ele ser');
INSERT INTO verses VALUES (25167, 42, 4, 42, 'Tendo-acontecido porém do-dia saindo foi para deserto lugar e o multidões buscavam ele e vieram até dele e retinham ele o não ir de deles');
INSERT INTO verses VALUES (25168, 42, 4, 43, 'o porém disse junto-a eles que e o outras cidades ter-anunciado-boa-nova me é necessário o reino o de-Theos que sobre isto fui-enviado');
INSERT INTO verses VALUES (25169, 42, 4, 44, 'e era pregando para o sinagogas o Judeia');
INSERT INTO chapters VALUES (978, 42, 5, 39);
INSERT INTO verses VALUES (25170, 42, 5, 1, 'aconteceu porém em o o multidão estar-imposto-sobre a ele e ouvir o palavra o de-Theos e ele era estando-de-pé de-junto-de o lago Genesaré');
INSERT INTO verses VALUES (25171, 42, 5, 2, 'e viu navios dois de-pé de-junto-de o lago o porém pescadores de deles tendo-desembarcado Lavavam o redes');
INSERT INTO verses VALUES (25172, 42, 5, 3, 'embarcando porém para um o navios o qual era de-Simão perguntou ele de o da-terra conduzir-para-o-alto pouco sentando-se porém de o do-barco ensinava o multidões');
INSERT INTO verses VALUES (25173, 42, 5, 4, 'como porém cessou falando disse junto-a o Simão Conduz-de-volta para o profundidade e abaixai o redes vosso para presa');
INSERT INTO verses VALUES (25174, 42, 5, 5, 'e respondendo Simão disse Mestre através-de de-toda da-noite tendo-trabalhado nada recebemos sobre porém o Palavra teu abaixarei o redes');
INSERT INTO verses VALUES (25175, 42, 5, 6, 'e isto tendo-feito encerraram-junto multidão peixes muito rompia-se porém o redes deles');
INSERT INTO verses VALUES (25176, 42, 5, 7, 'e acenaram o participantes em o a-outro no-barco o tendo-vindo prender a-eles e vieram e Encheram ambos o navios de-modo-que serem-submergidos elas');
INSERT INTO verses VALUES (25177, 42, 5, 8, 'vendo porém Simão Pedro prostrou-se o joelhos Iesous dizendo Sai de mim que homem pecador sou Kyrie');
INSERT INTO verses VALUES (25178, 42, 5, 9, 'espanto pois envolveu ele e todos o com a ele sobre o pesca o peixes o qual prenderam');
INSERT INTO verses VALUES (25179, 42, 5, 10, 'semelhantemente porém e Tiago e João filhos Zebedeu o qual eram participantes o Simão e disse junto-a o Simão o Iesous não temas de o agora homens serás capturando-vivos');
INSERT INTO verses VALUES (25180, 42, 5, 11, 'e tendo-feito-descer o navios sobre o terra deixando todas-as-coisas seguiram a ele');
INSERT INTO verses VALUES (25181, 42, 5, 12, 'e aconteceu em o ser ele em uma o cidades e eis homem cheio lepra vendo porém o Iesous caindo sobre face suplicou dele dizendo Kyrie se queiras podes me purificar');
INSERT INTO verses VALUES (25182, 42, 5, 13, 'e estendendo o mão tocou dele dizendo quero sê-purificado e imediatamente o lepra partiu de dele');
INSERT INTO verses VALUES (25183, 42, 5, 14, 'e ele ordenou a ele a-ninguém dizer mas partindo mostra a-ti-mesmo o sacerdote e oferece acerca-de o purificação teu assim-como ordenou Moisés para testemunho a-eles');
INSERT INTO verses VALUES (25184, 42, 5, 15, 'atravessava porém mais o palavra acerca-de dele e reuniam-se multidões muitos ouvir e ser-curado de o enfermidades deles');
INSERT INTO verses VALUES (25185, 42, 5, 16, 'ele porém era Retirando-se em o desertos e orando');
INSERT INTO verses VALUES (25186, 42, 5, 17, 'e aconteceu em uma o dias e ele era ensinando e eram sentados fariseus e mestres-da-lei o qual eram tendo-vindo de toda aldeia o Galileia e Judeia e Jerusalém e poder do-Kyrios era para o curar ele');
INSERT INTO verses VALUES (25187, 42, 5, 18, 'e eis homens trazendo sobre cama homem o qual era tendo-sido-paralisado e buscavam ele trazer-para-dentro e pôr diante-de dele');
INSERT INTO verses VALUES (25188, 42, 5, 19, 'e não tendo-encontrado de-qual tragam-para-dentro ele através-de o multidão tendo-subido sobre o terraço através-de o telhas desceram ele com o leito para o meio diante-de o Iesous');
INSERT INTO verses VALUES (25189, 42, 5, 20, 'e vendo o fé deles disse Homem têm-sido-perdoados a-ti o pecados teu');
INSERT INTO verses VALUES (25190, 42, 5, 21, 'e começaram raciocinar o escribas e o fariseus dizendo Quem é este o qual fala blasfêmias quem pode do-pecado perdoar se não só o Theos');
INSERT INTO verses VALUES (25191, 42, 5, 22, 'reconhecendo porém o Iesous o raciocínios deles respondendo disse junto-a eles quê raciocinais em o corações vosso');
INSERT INTO verses VALUES (25192, 42, 5, 23, 'quê é mais-fácil dizer Têm-sido-perdoados a-ti o pecados teu ou dizer Levanta-te e anda');
INSERT INTO verses VALUES (25193, 42, 5, 24, 'para que porém sei que o Filho o do-homem autoridade tem sobre o da-terra perdoar do-pecado disse o ao-tendo-sido-paralisado a-ti digo levanta-te e levantando o leito teu vai para o casa teu');
INSERT INTO verses VALUES (25194, 42, 5, 25, 'e imediatamente levantando-se diante-de deles levantando sobre o qual estava-deitado partiu para o casa dele glorificando o Theos');
INSERT INTO verses VALUES (25195, 42, 5, 26, 'e êxtase recebeu todos e glorificavam o Theos e foram-cheios medo dizendo que Vimos coisas-paradoxais hoje');
INSERT INTO verses VALUES (25196, 42, 5, 27, 'e com estas-coisas saiu e contemplou cobrador-de-impostos em-nome Levi sentado sobre o coletoria e disse a ele Segue a-mim');
INSERT INTO verses VALUES (25197, 42, 5, 28, 'e deixando todas-as-coisas levantando-se seguia a ele');
INSERT INTO verses VALUES (25198, 42, 5, 29, 'e fez banquete grande Levi a ele em o casa dele e era multidão muito cobradores-de-impostos e outros o qual eram com deles reclinados');
INSERT INTO verses VALUES (25199, 42, 5, 30, 'e murmuravam o fariseus e o escribas deles junto-a o discípulos dele dizendo através-de quê com o cobradores-de-impostos e dos-pecadores comeis e bebei');
INSERT INTO verses VALUES (25200, 42, 5, 31, 'e respondendo o Iesous disse junto-a eles não necessidade têm o estando-sãos médico mas o mal tendo');
INSERT INTO verses VALUES (25201, 42, 5, 32, 'não tenho-vindo chamar justos mas pecadores para arrependimento');
INSERT INTO verses VALUES (25202, 42, 5, 33, 'o porém disseram junto-a ele o discípulos João jejuam frequentemente e súplicas fazem semelhantemente e o o fariseus o porém a-ti comem e bebem');
INSERT INTO verses VALUES (25203, 42, 5, 34, 'o porém Iesous disse junto-a eles não podeis o filhos o câmara-nupcial em o qual o noivo com deles é fazer jejuar');
INSERT INTO verses VALUES (25204, 42, 5, 35, 'virão porém dias e quando seja-tirado de deles o noivo então jejuarão em aqueles o dias');
INSERT INTO verses VALUES (25205, 42, 5, 36, 'Dizia porém e parábola junto-a eles que ninguém remendo de manto novo tendo-rasgado lança-sobre sobre manto velho se porém de-outro-modo e o novo rasgará e o velho não concordará o remendo o de o novo');
INSERT INTO verses VALUES (25206, 42, 5, 37, 'e ninguém lança vinho novo para odres velhos se porém de-outro-modo romperá o vinho o novo o odres e ele será-derramado e o odres perecerão');
INSERT INTO verses VALUES (25207, 42, 5, 38, 'mas vinho novo para odres novos deve-ser-posto');
INSERT INTO verses VALUES (25208, 42, 5, 39, 'e ninguém tendo-bebido velho quer novo diz pois o velho benigno é');
INSERT INTO chapters VALUES (979, 42, 6, 49);
INSERT INTO verses VALUES (25209, 42, 6, 1, 'aconteceu porém em no-sábado passar-através ele através-de searas e arrancavam o discípulos dele e comiam o espigas esfregando o mãos');
INSERT INTO verses VALUES (25210, 42, 6, 2, 'alguns porém o fariseus disseram quê fazei o qual não é-lícito o nos-sábados');
INSERT INTO verses VALUES (25211, 42, 6, 3, 'e respondendo junto-a eles disse o Iesous nem isto lestes o qual fez Davi quando teve-fome ele e o com dele sendo');
INSERT INTO verses VALUES (25212, 42, 6, 4, 'como entrou para o casa o de-Theos e o pães o propósito tomando comeu e deu o com dele o qual não é-lícito comer se não somente o sacerdotes');
INSERT INTO verses VALUES (25213, 42, 6, 5, 'e dizia a-eles Kyrios é o do-sábado o Filho o do-homem');
INSERT INTO verses VALUES (25214, 42, 6, 6, 'aconteceu porém em a-outro no-sábado entrar ele para o sinagoga e ensinar e era homem ali e o mão dele o direita era seca');
INSERT INTO verses VALUES (25215, 42, 6, 7, 'observavam porém ele o escribas e o fariseus se em o no-sábado cura para que encontrem acusar dele');
INSERT INTO verses VALUES (25216, 42, 6, 8, 'ele porém sei o raciocínios deles disse porém o marido o seca tendo o mão Levanta-te e fica-de-pé para o meio e levantando-se pôs-se-de-pé');
INSERT INTO verses VALUES (25217, 42, 6, 9, 'disse porém o Iesous junto-a eles Pergunto vos se é-lícito o no-sábado fazer-o-bem ou fazer-mal alma salvar ou destruir');
INSERT INTO verses VALUES (25218, 42, 6, 10, 'e olhando-ao-redor todos eles disse a ele Estende o mão teu o porém fez e foi-restaurado o mão dele');
INSERT INTO verses VALUES (25219, 42, 6, 11, 'eles-mesmos porém foram-cheios insensatez e conversavam junto-a uns-aos-outros quê partícula-condicional fizessem o Iesous');
INSERT INTO verses VALUES (25220, 42, 6, 12, 'aconteceu porém em o dias estas sair ele para o monte orar e era passando-a-noite em o oração o de-Theos');
INSERT INTO verses VALUES (25221, 42, 6, 13, 'e quando aconteceu dia chamou o discípulos dele e tendo-escolhido de deles doze o qual e apóstolos nomeou');
INSERT INTO verses VALUES (25222, 42, 6, 14, 'Simão o qual e nomeou Pedro e André o irmão dele e Tiago e João e Filipe e Bartolomeu');
INSERT INTO verses VALUES (25223, 42, 6, 15, 'e Mateus e Tomé e Tiago Alfeu e Simão o chamado zelote');
INSERT INTO verses VALUES (25224, 42, 6, 16, 'e Judas de-Tiago e Judas Iscariotes o qual aconteceu traidor');
INSERT INTO verses VALUES (25225, 42, 6, 17, 'e descendo com deles pôs-se-de-pé sobre lugar planície e multidão muito discípulos dele e multidão muito o povo de toda o Judeia e Jerusalém e o costeira Tiro e Sidom');
INSERT INTO verses VALUES (25226, 42, 6, 18, 'o qual vieram ouvir dele e Ser-curado de o doenças deles e o sendo-perturbados de espíritos impuros eram-curados');
INSERT INTO verses VALUES (25227, 42, 6, 19, 'e todo o multidão buscavam tocar dele que poder de dele saía e curava todos');
INSERT INTO verses VALUES (25228, 42, 6, 20, 'e ele levantando o olhos dele para o discípulos dele dizia bem-aventurados o pobres que vossa é o reino o de-Theos');
INSERT INTO verses VALUES (25229, 42, 6, 21, 'bem-aventurados o tendo-fome agora que sereis-saciados bem-aventurados o chorando agora que rireis');
INSERT INTO verses VALUES (25230, 42, 6, 22, 'bem-aventurados sois quando odeiem vos o homens e quando separem vos e injuriem e expulsem o nome vosso como mau por-causa-de o do-Filho o do-homem');
INSERT INTO verses VALUES (25231, 42, 6, 23, 'alegreis-vos em naquela o dia e saltai-de-alegria eis pois o salário vosso muito em o no-céu segundo o elas pois faziam o profetas o pais deles');
INSERT INTO verses VALUES (25232, 42, 6, 24, 'exceto ai a-vós o ricos que tendes-recebido o consolação vosso');
INSERT INTO verses VALUES (25233, 42, 6, 25, 'ai a-vós o tendo-sido-saciados agora que tereis-fome ai o rindo agora que lamentareis e chorareis');
INSERT INTO verses VALUES (25234, 42, 6, 26, 'ai quando bem vos digam todos o homens segundo o elas pois faziam o falsos-profetas o pais deles');
INSERT INTO verses VALUES (25235, 42, 6, 27, 'mas a-vós digo o ouvem Amai o inimigos vosso bem fazei o odeiam vos');
INSERT INTO verses VALUES (25236, 42, 6, 28, 'bendizei o tendo-sido-amaldiçoados vos orai acerca-de o maltratando vos');
INSERT INTO verses VALUES (25237, 42, 6, 29, 'o golpeando te sobre o face apresenta e o outra e de o levantando teu o manto e o túnica não impeças');
INSERT INTO verses VALUES (25238, 42, 6, 30, 'todo pedindo te dá e de o levantando o tuas não exige-de-volta');
INSERT INTO verses VALUES (25239, 42, 6, 31, 'e assim-como quereis para que façam a-vós o homens fazei a-eles semelhantemente');
INSERT INTO verses VALUES (25240, 42, 6, 32, 'e se amai o amando vos qual a-vós graça é e pois o pecadores o amando eles amam');
INSERT INTO verses VALUES (25241, 42, 6, 33, 'e pois se façais-o-bem o fazendo-o-bem vos qual a-vós graça é e o pecadores o ele fazem');
INSERT INTO verses VALUES (25242, 42, 6, 34, 'e se emprestardes de-junto-de o qual esperais receber qual a-vós graça é e pecadores pecadores emprestam para que recebam o iguais');
INSERT INTO verses VALUES (25243, 42, 6, 35, 'porém amai o inimigos vosso e fazei-o-bem e emprestais nada nada-esperando-em-retorno e será o salário vosso muito e sereis filhos Altíssimo que ele benigno é sobre o ingratos e maus');
INSERT INTO verses VALUES (25244, 42, 6, 36, 'Tornai-vos compassivos assim-como o Pai vosso misericordioso é');
INSERT INTO verses VALUES (25245, 42, 6, 37, 'e não julgais e não não sejais-julgados e não condenais e não não sejais-condenados soltai e sereis-soltos');
INSERT INTO verses VALUES (25246, 42, 6, 38, 'dai e será-dado a-vós medida belo tendo-sido-pressionado tendo-sido-sacudido Transbordando darão para o seio vosso o qual pois medida medis será-medido-de-volta a-vós');
INSERT INTO verses VALUES (25247, 42, 6, 39, 'disse porém e parábola a-eles Acaso pode cego cego guiar não ambos para cova cairão-em');
INSERT INTO verses VALUES (25248, 42, 6, 40, 'não é discípulo em-favor-de o mestre tendo-sido-restaurado porém todo será como o mestre dele');
INSERT INTO verses VALUES (25249, 42, 6, 41, 'quê porém vês o cisco o em o olho o do-irmão teu o porém viga o em o próprio olho não consideras');
INSERT INTO verses VALUES (25250, 42, 6, 42, 'como podes dizer o ao-irmão teu Irmão deixa expulse o cisco o em o olho teu ele o em o olho teu viga não vendo hipócrita expulsa primeiro o viga de o olho teu e então verás-claramente o cisco o em o olho o do-irmão teu expulsar');
INSERT INTO verses VALUES (25251, 42, 6, 43, 'não pois é árvore belo fazendo fruto podre nem novamente árvore podre fazendo fruto bom');
INSERT INTO verses VALUES (25252, 42, 6, 44, 'cada-um pois árvore de o próprio fruto é-conhecida não pois de espinhos colhem figos nem de sarça uva vindimem');
INSERT INTO verses VALUES (25253, 42, 6, 45, 'o bom homem de o bom tesouro o do-coração produz o bom e o mau de o do-mal produz o mau de pois abundância do-coração fala o boca dele');
INSERT INTO verses VALUES (25254, 42, 6, 46, 'quê e/mas me chamais Kyrie kyrie e não fazei o qual digo');
INSERT INTO verses VALUES (25255, 42, 6, 47, 'todo o vindo para me e ouvindo meu o palavras e fazendo eles mostrarei a-vós a-quem é semelhante');
INSERT INTO verses VALUES (25256, 42, 6, 48, 'semelhante é ao-homem edificando casa o qual Cavou e aprofundou e colocou fundamento sobre o rocha enchente porém tendo-acontecido arrojou-se-contra o rio o casa naquela e não prevaleceu abalar ela através-de o bem ser-edificada ela');
INSERT INTO verses VALUES (25257, 42, 6, 49, 'o porém ouvindo e não tendo-feito semelhante é ser-humano tendo-edificado casa sobre o terra sem fundamento o qual arrojou-se-contra o rio e imediatamente caiu-junto e aconteceu o ruína o da-casa daquela grande');
INSERT INTO chapters VALUES (980, 42, 7, 50);
INSERT INTO verses VALUES (25258, 42, 7, 1, 'Porquanto cumpriu todas-as-coisas o palavras dele para o ouvidos o povo entrou para Cafarnaum');
INSERT INTO verses VALUES (25259, 42, 7, 2, 'Centurião e/mas de-alguém servo mal tendo estava-prestes-a morrer o qual era a ele Honrado');
INSERT INTO verses VALUES (25260, 42, 7, 3, 'ouvindo porém acerca-de o Iesous enviou junto-a ele anciãos o judeus Perguntando ele para-que vindo salve o servo dele');
INSERT INTO verses VALUES (25261, 42, 7, 4, 'o porém tendo-chegado junto-a o Iesous suplicavam ele diligentemente dizendo que digno é o qual fornecerá isto');
INSERT INTO verses VALUES (25262, 42, 7, 5, 'ama pois o nação nosso e o sinagoga ele edificou a-nós');
INSERT INTO verses VALUES (25263, 42, 7, 6, 'o porém Iesous ia com a-eles já porém dele não longe estando-distante de o da-casa enviou amigos o centurião dizendo a ele Kyrie não incomodes não pois suficiente sou para que sob o telhado meu entres');
INSERT INTO verses VALUES (25264, 42, 7, 7, 'por-isso nem a-mim-mesmo considerei-digno junto-a te vir mas dize em-palavra e Que-seja-curado o servo meu');
INSERT INTO verses VALUES (25265, 42, 7, 8, 'e pois eu homem sou sob autoridade sendo-designado tendo sob a-mim-mesmo soldados e digo neste Vai e vai e a-outro Vem e vem e o servo meu faz isto e faz');
INSERT INTO verses VALUES (25266, 42, 7, 9, 'ouvindo porém estas-coisas o Iesous admirou-se ele e voltando-se o seguindo a ele à-multidão disse digo a-vós nem em o Israel tão-grande fé encontraram');
INSERT INTO verses VALUES (25267, 42, 7, 10, 'e tendo-retornado para o casa o tendo-sido-enviados encontraram o servo sendo-saudável');
INSERT INTO verses VALUES (25268, 42, 7, 11, 'e aconteceu em o na-sequência foi para cidade chamada Naim e caminhavam-junto a ele o discípulos dele e multidão muito');
INSERT INTO verses VALUES (25269, 42, 7, 12, 'como porém aproximou-se o em-porta o cidade e eis era-levado-para-fora tendo-morrido unigênito Filho o mãe dele e ela era viúva e multidão o cidade digno era com a-ela');
INSERT INTO verses VALUES (25270, 42, 7, 13, 'e vendo ela o Kyrios compadeceu-se sobre a-ela e disse a-ela não chores');
INSERT INTO verses VALUES (25271, 42, 7, 14, 'e aproximando-se tocou o caixão o porém carregando colocaram-de-pé e disse Jovem a-ti digo levanta-te');
INSERT INTO verses VALUES (25272, 42, 7, 15, 'e sentou-se o morto e começou falar e deu ele o mãe dele');
INSERT INTO verses VALUES (25273, 42, 7, 16, 'recebeu porém medo todos e glorificavam o Theos dizendo que Profeta grande foi-ressuscitado em a-nós e que Visitou o Theos o povo dele');
INSERT INTO verses VALUES (25274, 42, 7, 17, 'e saiu o palavra este em toda o Judeia acerca-de dele e toda o região-circunvizinha');
INSERT INTO verses VALUES (25275, 42, 7, 18, 'e anunciaram João o discípulos dele acerca-de todos destes e tendo-chamado dois alguns o discípulos dele o João');
INSERT INTO verses VALUES (25276, 42, 7, 19, 'enviou junto-a o Kyrion dizendo tu és o vindo ou outro esperemos');
INSERT INTO verses VALUES (25277, 42, 7, 20, 'tendo-chegado porém junto-a ele o homens disseram João o Batista enviou nos junto-a te dizendo tu és o vindo ou outro esperemos');
INSERT INTO verses VALUES (25278, 42, 7, 21, 'em naquela o hora curou a-muitos de doenças e açoites e espíritos maus e cegos muitos concedeu-graciosamente ver');
INSERT INTO verses VALUES (25279, 42, 7, 22, 'e respondendo disse a-eles Tendo-ido anunciai João o qual vistes e ouvistes cegos recuperam-a-vista coxos andam leprosos são-purificados e mudos ouvem mortos são-levantados pobres anunciam-boa-nova');
INSERT INTO verses VALUES (25280, 42, 7, 23, 'e bem-aventurado é o qual se não seja-escandalizado em me');
INSERT INTO verses VALUES (25281, 42, 7, 24, 'Tendo-partido porém o anjo João começou dizer junto-a o multidões acerca-de João quê saístes para o deserto contemplar cana sob vento sendo-abalado');
INSERT INTO verses VALUES (25282, 42, 7, 25, 'mas quê saístes ver homem em moles vestes tendo-sido-vestido eis o em vestuário glorioso e luxúria existindo em o palácios-reais são');
INSERT INTO verses VALUES (25283, 42, 7, 26, 'mas quê saístes ver profeta sim digo a-vós e abundantemente profeta');
INSERT INTO verses VALUES (25284, 42, 7, 27, 'este é acerca-de o qual está-escrito Eis envio o anjo meu antes-de face teu o qual preparará o caminho teu diante-de teu');
INSERT INTO verses VALUES (25285, 42, 7, 28, 'digo a-vós maior em nascidos mulheres João ninguém é o porém menor em o reino o de-Theos maior dele é');
INSERT INTO verses VALUES (25286, 42, 7, 29, 'e todo o povo ouvindo e o cobradores-de-impostos justificaram o Theos tendo-sido-batizados o batismo João');
INSERT INTO verses VALUES (25287, 42, 7, 30, 'o porém fariseus e o peritos-na-lei o conselho o de-Theos rejeitaram para a-si-mesmos não tendo-sido-batizados sob dele');
INSERT INTO verses VALUES (25288, 42, 7, 31, 'A-quem portanto compararei o homens o geração desta e a-quem são semelhantes');
INSERT INTO verses VALUES (25289, 42, 7, 32, 'semelhantes são criancinhas o em praça sentados e chamam uns-aos-outros o qual diz Tocamos-flauta a-vós e não dançastes lamentamos e não chorai');
INSERT INTO verses VALUES (25290, 42, 7, 33, 'tem-vindo pois João o Batista não comendo pão nem bebendo vinho e dizeis Demônio tem');
INSERT INTO verses VALUES (25291, 42, 7, 34, 'tem-vindo o Filho o do-homem comendo e bebendo e dizeis Eis homem comilão e bebedor-de-vinho amigo cobradores-de-impostos e dos-pecadores');
INSERT INTO verses VALUES (25292, 42, 7, 35, 'e foi-justificado o sabedoria de todos o filhos dela');
INSERT INTO verses VALUES (25293, 42, 7, 36, 'Perguntava e/mas alguém ele o fariseus para que coma com dele e entrando para o casa o Fariseu reclinou-se');
INSERT INTO verses VALUES (25294, 42, 7, 37, 'e eis mulher a-qual era em o cidade pecador e tendo-conhecido-plenamente que está-reclinado em o casa o Fariseu tendo-trazido alabastro perfume');
INSERT INTO verses VALUES (25295, 42, 7, 38, 'e tendo-ficado-de-pé atrás de-junto-de o pés dele chorando o lágrimas começou chover o pés dele e o cabelos o cabeça dela enxugava e beijava o pés dele e Ungia o ungüento');
INSERT INTO verses VALUES (25296, 42, 7, 39, 'vendo porém o fariseu o chamando ele disse em si-mesmo dizendo este se era profeta conhecia partícula-condicional quem e que-espécie-de o mulher a-qual toca dele que pecador é');
INSERT INTO verses VALUES (25297, 42, 7, 40, 'e respondendo o Iesous disse junto-a ele Simão tenho te algo dizer o e/mas Mestre dize diz');
INSERT INTO verses VALUES (25298, 42, 7, 41, 'dois devedores eram credor a-alguém o um devia denários quinhentos o porém outro cinquenta');
INSERT INTO verses VALUES (25299, 42, 7, 42, 'não tendo deles retribuir ambos concedeu-graciosamente quem portanto deles mais amará ele');
INSERT INTO verses VALUES (25300, 42, 7, 43, 'respondendo Simão disse Suponho que o qual o mais concedeu-graciosamente o porém disse a ele Retamente julgaste');
INSERT INTO verses VALUES (25301, 42, 7, 44, 'e voltando-se junto-a o mulher o Simão disse vês esta o mulher entraram teu para o casa água a-mim sobre pés não deste esta porém o lágrimas Choveu meu o pés e o cabelos dela enxugou');
INSERT INTO verses VALUES (25302, 42, 7, 45, 'beijo a-mim não deste esta porém de o qual entraram não cessou beijando meu o pés');
INSERT INTO verses VALUES (25303, 42, 7, 46, 'azeite o cabeça meu não Ungiste esta porém ungüento ungiu o pés meu');
INSERT INTO verses VALUES (25304, 42, 7, 47, 'o qual graça digo a-ti são-perdoados o pecados dela o muitas que amou muito o qual porém pouco é-perdoado pouco ama');
INSERT INTO verses VALUES (25305, 42, 7, 48, 'disse porém a-ela Têm-sido-perdoados teu o pecados');
INSERT INTO verses VALUES (25306, 42, 7, 49, 'e começaram o reclinados-à-mesa-junto dizer em si-mesmos quem este é o qual e do-pecado perdoa');
INSERT INTO verses VALUES (25307, 42, 7, 50, 'disse porém junto-a o mulher o fé teu tem-salvo te vai para paz');
INSERT INTO chapters VALUES (981, 42, 8, 56);
INSERT INTO verses VALUES (25308, 42, 8, 1, 'e aconteceu em o por-ordem e ele percorria segundo cidade e aldeia pregando e anunciando-boa-nova o reino o de-Theos e o doze com a ele');
INSERT INTO verses VALUES (25309, 42, 8, 2, 'e mulheres alguns o qual eram tendo-sido-curadas de espíritos maus e enfermidades Maria o chamada Madalena de o qual demônios sete tinha-saído');
INSERT INTO verses VALUES (25310, 42, 8, 3, 'e Joana mulher Cuza Procurador de-Herodes e Susana e outras muitas as-quais serviam a-eles de o posses elas');
INSERT INTO verses VALUES (25311, 42, 8, 4, 'Reunindo-se porém multidão grande e o segundo cidade acorrendo junto-a ele disse através-de parábola');
INSERT INTO verses VALUES (25312, 42, 8, 5, 'saiu o o-que-semeia o semear o semente dele e em o semear ele o qual por-um-lado caiu de-junto-de o caminho e foi-pisado e o aves o do-céu devorou isso');
INSERT INTO verses VALUES (25313, 42, 8, 6, 'e outro caiu sobre o rocha e tendo-crescido secou através-de o não ter umidade');
INSERT INTO verses VALUES (25314, 42, 8, 7, 'e outro caiu em meio o espinhos e tendo-crescido-junto o espinhos sufocaram isso');
INSERT INTO verses VALUES (25315, 42, 8, 8, 'e outro caiu para o terra o boa e tendo-crescido fez fruto cem-vezes-mais estas-coisas dizendo Chamava-em-voz-alta o tendo ouvidos ouvir ouça');
INSERT INTO verses VALUES (25316, 42, 8, 9, 'Perguntavam porém ele o discípulos dele quem esta seria o parábola');
INSERT INTO verses VALUES (25317, 42, 8, 10, 'o porém disse a-vós foi-dado conhecer o mistérios o do-reino o de-Theos o porém restantes em em-parábolas para que vendo não vejam e ouvindo não compreendam');
INSERT INTO verses VALUES (25318, 42, 8, 11, 'é porém esta o parábola o semente é o palavra o de-Theos');
INSERT INTO verses VALUES (25319, 42, 8, 12, 'o porém de-junto-de o caminho são o ouvindo então vem o diabo e levanta o palavra de o do-coração deles para que não tendo-crido sejam-salvos');
INSERT INTO verses VALUES (25320, 42, 8, 13, 'o porém sobre o rochas o qual quando ouçam com alegria recebem o palavra e estes raiz não têm o qual junto-a tempo creem e em tempo provação afastam-se');
INSERT INTO verses VALUES (25321, 42, 8, 14, 'o porém para o espinhos tendo-caído estes são o ouvindo e sob preocupando-se e riqueza e prazeres o vida indo são-sufocados-juntamente e não frutificam-até-o-fim');
INSERT INTO verses VALUES (25322, 42, 8, 15, 'o porém em o boa terra estes são os-quais em no-coração boa e boa ouvindo o palavra retêm e frutificam em perseverança');
INSERT INTO verses VALUES (25323, 42, 8, 16, 'ninguém porém lâmpada tendo-acendido cobre ele vaso ou debaixo cama põe mas sobre candelabros põe para que o entrando vejam o luz');
INSERT INTO verses VALUES (25324, 42, 8, 17, 'não pois é oculto o qual não manifesto acontecerá nem oculto o qual não não seja-conhecido e para manifesto venha');
INSERT INTO verses VALUES (25325, 42, 8, 18, 'vede portanto como ouvi o qual partícula-condicional pois tenha será-dado a ele e o qual partícula-condicional não tenha e o qual parece ter será-tirado de dele');
INSERT INTO verses VALUES (25326, 42, 8, 19, 'Chegou porém junto-a ele o mãe e o irmãos dele e não podiam encontrar a ele através-de o multidão');
INSERT INTO verses VALUES (25327, 42, 8, 20, 'foi-anunciado porém a ele o mãe teu e o irmãos teu estão-de-pé fora ver querendo te');
INSERT INTO verses VALUES (25328, 42, 8, 21, 'o porém respondendo disse junto-a eles Mãe meu e irmãos meu estes são o o palavra o de-Theos ouvindo e fazendo');
INSERT INTO verses VALUES (25329, 42, 8, 22, 'aconteceu porém em uma o dias e ele embarcou para barco e o discípulos dele e disse junto-a eles Passemos-ao-outro-lado para o além o lago e foram-levados-ao-mar');
INSERT INTO verses VALUES (25330, 42, 8, 23, 'navegando porém deles adormeceu e desceu tempestade vento para o lago e enchiam-se e corriam-perigo');
INSERT INTO verses VALUES (25331, 42, 8, 24, 'aproximando-se porém despertaram ele dizendo Mestre mestre perecemos o porém tendo-sido-despertado repreendeu o vento e o onda o água e cessaram e aconteceu calmaria');
INSERT INTO verses VALUES (25332, 42, 8, 25, 'disse porém a-eles onde o fé vosso tendo-temido porém admiraram-se dizendo junto-a uns-aos-outros quem então este é que e o ventos ordena e o água e obedecem a ele');
INSERT INTO verses VALUES (25333, 42, 8, 26, 'e navegaram-para para o região o Gerasenos a-qual é do-lado-oposto o Galileia');
INSERT INTO verses VALUES (25334, 42, 8, 27, 'tendo-saído porém a ele sobre o terra encontrou homem alguém de o cidade tendo demônios e tempo suficiente não vestiu-se manto e em casa não permanecia mas em o sepulcros');
INSERT INTO verses VALUES (25335, 42, 8, 28, 'vendo porém o Iesous tendo-clamado prostrou-se a ele e voz grande disse quê mim e te Iesous Filho o de-Theos o Altíssimo suplico teu não me atormentes');
INSERT INTO verses VALUES (25336, 42, 8, 29, 'ordenava pois o espírito o impuro sair de o do-homem muitos pois tempos tinha-arrebatado ele e estava-preso cadeias e grilhões guardando-se e rasgando o cadeias era-impelido de o demônio para o Desertos');
INSERT INTO verses VALUES (25337, 42, 8, 30, 'perguntou porém ele o Iesous quê a-ti nome é o porém disse Legião que entrou demônios muitas-coisas para ele');
INSERT INTO verses VALUES (25338, 42, 8, 31, 'e suplicavam ele para que não Ordene a-eles para o abismo ir-embora');
INSERT INTO verses VALUES (25339, 42, 8, 32, 'era porém ali manada porcos suficientes sendo-apascentada em o no-monte e suplicaram ele para que permita a-eles para aqueles entrar e permitiu a-eles');
INSERT INTO verses VALUES (25340, 42, 8, 33, 'tendo-saído porém o demônios de o do-homem entraram para o porcos e precipitou-se o manada segundo o precipício para o lago e afogou-se');
INSERT INTO verses VALUES (25341, 42, 8, 34, 'vendo porém o apascentando o tendo-acontecido fugiram e anunciaram para o cidade e para o campos');
INSERT INTO verses VALUES (25342, 42, 8, 35, 'saíram porém ver o tendo-acontecido e vieram junto-a o Iesous e encontraram sentado o homem de o qual o demônios saiu tendo-sido-vestido e sendo-sóbrio-de-mente de-junto-de o pés o Iesous e temeram');
INSERT INTO verses VALUES (25343, 42, 8, 36, 'anunciaram porém a-eles o vendo como foi-salvo o tendo-sido-endemoninhado');
INSERT INTO verses VALUES (25344, 42, 8, 37, 'e perguntou ele todo o multidão o região-circunvizinha o Gerasenos ir-embora de deles que medo grande eram-constrangidos ele porém embarcando para barco retornou');
INSERT INTO verses VALUES (25345, 42, 8, 38, 'suplicava porém dele o homem de o qual tinha-saído o demônios ser com a ele soltou porém ele dizendo');
INSERT INTO verses VALUES (25346, 42, 8, 39, 'Retorna para o casa teu e narra quanto a-ti fez o Theos e partiu segundo toda o cidade pregando quanto fez a ele o Iesous');
INSERT INTO verses VALUES (25347, 42, 8, 40, 'em porém o retornar o Iesous recebeu ele o multidão eram pois todos esperando ele');
INSERT INTO verses VALUES (25348, 42, 8, 41, 'e eis veio homem o qual nome Jairo e este governante o sinagoga existia e caindo de-junto-de o pés Iesous suplicava ele entrar para o casa dele');
INSERT INTO verses VALUES (25349, 42, 8, 42, 'que filha unigênito era a ele como anos doze e ela morria em porém o ir ele o multidões sufocavam-juntamente ele');
INSERT INTO verses VALUES (25350, 42, 8, 43, 'e mulher sendo em livrará sangue de anos doze a-qual não prevaleceu de de-ninguém ser-curado');
INSERT INTO verses VALUES (25351, 42, 8, 44, 'tendo-se-aproximado atrás tocou o franja o manto dele e imediatamente pôs-se-de-pé o fluxo o sangue dela');
INSERT INTO verses VALUES (25352, 42, 8, 45, 'e disse o Iesous quem o tendo-tocado meu negando porém todos disse o Pedro Mestre o multidões constrangem te e comprimem');
INSERT INTO verses VALUES (25353, 42, 8, 46, 'o porém Iesous disse Tocou meu alguém eu pois conheci poder tendo-saído de mim');
INSERT INTO verses VALUES (25354, 42, 8, 47, 'vendo porém o mulher que não Ficou-oculto tremendo veio e tendo-caído-diante a ele através-de o qual causa tocou dele anunciou diante-de de-todo o povo e como foi-curado imediatamente');
INSERT INTO verses VALUES (25355, 42, 8, 48, 'o porém disse a-ela Filha o fé teu tem-salvo te vai para paz');
INSERT INTO verses VALUES (25356, 42, 8, 49, 'ainda dele falando vem alguém de-junto-de o chefe-da-sinagoga dizendo que Tem-morrido o filha teu não-mais incomodes o Mestre');
INSERT INTO verses VALUES (25357, 42, 8, 50, 'o porém Iesous ouvindo respondeu a ele não temas somente crê e será-salvo');
INSERT INTO verses VALUES (25358, 42, 8, 51, 'vindo porém para o casa não deixou entrar alguém com a ele se não Pedro e João e Tiago e o Pai o servo e o mãe');
INSERT INTO verses VALUES (25359, 42, 8, 52, 'chorava porém todos e lamentavam-se ela o porém disse não chorai não morreu mas dorme');
INSERT INTO verses VALUES (25360, 42, 8, 53, 'e riam-se dele sei que morreu');
INSERT INTO verses VALUES (25361, 42, 8, 54, 'ele porém segurando o mão dela clamou dizendo o servo levanta-te');
INSERT INTO verses VALUES (25362, 42, 8, 55, 'e voltou o espírito dela e levantou-se imediatamente e ordenou a-ela ser-dado comer');
INSERT INTO verses VALUES (25363, 42, 8, 56, 'e ficaram-fora-de-si o pais dela o porém ordenou a-eles a-ninguém dizer o tendo-acontecido');
INSERT INTO chapters VALUES (982, 42, 9, 62);
INSERT INTO verses VALUES (25364, 42, 9, 1, 'Tendo-convocado porém o doze deu a-eles poder e autoridade sobre todas-as-coisas o demônios e doenças curar');
INSERT INTO verses VALUES (25365, 42, 9, 2, 'e enviou eles proclamar o reino o de-Theos e curar');
INSERT INTO verses VALUES (25366, 42, 9, 3, 'e disse junto-a eles nada levantai para o caminho nem vara nem alforje nem pão nem prata nem cada dois túnicas ter');
INSERT INTO verses VALUES (25367, 42, 9, 4, 'e para o qual partícula-condicional casa entreis ali permanecei e dali saí');
INSERT INTO verses VALUES (25368, 42, 9, 5, 'e quanto partícula-condicional não recebam vos saindo de o cidade daquela o poeira de o pés vosso sacudi para testemunho sobre eles');
INSERT INTO verses VALUES (25369, 42, 9, 6, 'saindo porém atravessavam segundo o aldeias evangelizando e curando por-toda-parte');
INSERT INTO verses VALUES (25370, 42, 9, 7, 'ouviu porém Herodes o tetrarca o acontecendo todas-as-coisas e ficava-perplexo através-de o ser-dito por alguns que João foi-ressuscitado de mortos');
INSERT INTO verses VALUES (25371, 42, 9, 8, 'por alguns porém que Elias apareceu outros porém que profeta alguém o antigos levantou-se');
INSERT INTO verses VALUES (25372, 42, 9, 9, 'disse porém Herodes João eu decapitei quem e/mas é este acerca-de o qual ouço tais-coisas e buscava ver ele');
INSERT INTO verses VALUES (25373, 42, 9, 10, 'e tendo-retornado o apóstolos narraram a ele quanto fizeram e tomando-consigo eles Retirou-se segundo própria para cidade chamada Betsaida');
INSERT INTO verses VALUES (25374, 42, 9, 11, 'o porém multidões conhecendo seguiram a ele e tendo-recebido eles falava a-eles acerca-de o do-reino o de-Theos e o necessidade tendo cura curava');
INSERT INTO verses VALUES (25375, 42, 9, 12, 'o porém dia começou inclinar aproximando-se porém o doze disseram a ele Liberta o multidão para que tendo-ido para o ao-redor aldeias e campos destruam e encontrem provisão que aqui em deserto no-lugar somos');
INSERT INTO verses VALUES (25376, 42, 9, 13, 'disse porém junto-a eles dai a-eles comer vós o porém disseram não são a-nós mais ou pães cinco e Peixes dois se acaso tendo-ido nós compremos para todas-as-coisas o povo este alimentos');
INSERT INTO verses VALUES (25377, 42, 9, 14, 'eram pois como homens cinco-mil disse porém junto-a o discípulos dele Fazei-reclinar eles grupos como cada cinquenta');
INSERT INTO verses VALUES (25378, 42, 9, 15, 'e fizeram assim e reclinaram todos');
INSERT INTO verses VALUES (25379, 42, 9, 16, 'tomando porém o cinco pães e o dois peixes olhando-para-cima para o céu abençoou eles e partiu e dava o discípulos pôr-diante o à-multidão');
INSERT INTO verses VALUES (25380, 42, 9, 17, 'e comeram e fartaram-se todos e foi-levantado o abundou a-eles pedaços cestos doze');
INSERT INTO verses VALUES (25381, 42, 9, 18, 'e aconteceu em o ser ele orando segundo somente estavam-junto a ele o discípulos e perguntou eles dizendo Quem me o multidões dizem ser');
INSERT INTO verses VALUES (25382, 42, 9, 19, 'o porém respondendo disseram João o Batista outros porém Elias outros porém que profeta alguém o antigos levantou-se');
INSERT INTO verses VALUES (25383, 42, 9, 20, 'disse porém a-eles vós porém quem me dizeis ser Pedro porém respondendo disse o Christos o de-Theos');
INSERT INTO verses VALUES (25384, 42, 9, 21, 'o porém Tendo-repreendido a-eles ordenou a-ninguém dizer isto');
INSERT INTO verses VALUES (25385, 42, 9, 22, 'dizendo que é necessário o Filho o do-homem muitas-coisas sofrer e ser-rejeitado de o anciãos e sumos-sacerdotes e dos-escribas e ser-morto e o no-terceiro dia ser-levantado');
INSERT INTO verses VALUES (25386, 42, 9, 23, 'Dizia porém junto-a todos se alguém quer atrás meu vir negue si-mesmo e levante o cruz dele segundo dia e siga a-mim');
INSERT INTO verses VALUES (25387, 42, 9, 24, 'o qual pois se queira o alma dele salvar destruirá ela o qual e/mas partícula-condicional destrua o alma dele por-causa-de mim este salvará ela');
INSERT INTO verses VALUES (25388, 42, 9, 25, 'quê pois É-aproveitado homem tendo-ganho o mundo todo si-mesmo porém tendo-perdido ou tendo-sofrido-perda');
INSERT INTO verses VALUES (25389, 42, 9, 26, 'o qual pois partícula-condicional envergonhe-se me e o meus palavras este o Filho o do-homem envergonhar-se-á quando venha em o glória dele e o do-Pai e o dos-santos anjo');
INSERT INTO verses VALUES (25390, 42, 9, 27, 'digo porém a-vós verdadeiramente são alguns o dele estando-de-pé o qual não não provem da-morte até partícula-condicional vejam o reino o de-Theos');
INSERT INTO verses VALUES (25391, 42, 9, 28, 'aconteceu porém com o palavras estes como dias oito e tomando-consigo Pedro e João e Tiago subiu para o monte orar');
INSERT INTO verses VALUES (25392, 42, 9, 29, 'e aconteceu em o orar ele o forma o face dele outro e o vestimenta dele branco resplandecendo');
INSERT INTO verses VALUES (25393, 42, 9, 30, 'e eis homens dois falavam-entre-si a ele os-quais eram Moisés e Elias');
INSERT INTO verses VALUES (25394, 42, 9, 31, 'o qual tendo-aparecido em glória diziam o partida dele o qual estava-prestes-a preencher em Jerusalém');
INSERT INTO verses VALUES (25395, 42, 9, 32, 'o porém Pedro e o com a ele eram tendo-sido-sobrecarregados sono tendo-despertado-completamente porém viram o glória dele e o dois homens o tendo-se-reunido a ele');
INSERT INTO verses VALUES (25396, 42, 9, 33, 'e aconteceu em o separar-se eles de dele disse o Pedro junto-a o Iesous Mestre bom é nos aqui ser e façamos tendas três uma a-ti e uma Moisés e uma Elias não sei o qual diz');
INSERT INTO verses VALUES (25397, 42, 9, 34, 'estas-coisas porém dele dizendo aconteceu nuvem e fazia-sombra-sobre eles temeram porém em o entrar eles para o nuvem');
INSERT INTO verses VALUES (25398, 42, 9, 35, 'e voz aconteceu de o nuvem dizendo Este é o filho meu o tendo-sido-escolhido dele ouvi');
INSERT INTO verses VALUES (25399, 42, 9, 36, 'e em o tornar-se o voz foi-encontrado Iesous só e eles-mesmos silenciaram e a-ninguém anunciaram em aqueles o dias nada o qual Viram');
INSERT INTO verses VALUES (25400, 42, 9, 37, 'aconteceu porém o na-sequência dia tendo-descido deles de o do-monte encontrou a ele multidão muito');
INSERT INTO verses VALUES (25401, 42, 9, 38, 'e eis homem de o multidão clamou dizendo Mestre suplico teu olhar-sobre sobre o filho meu que unigênito me é');
INSERT INTO verses VALUES (25402, 42, 9, 39, 'e eis espírito recebe ele e subitamente clama e convulsiona ele com espuma e dificilmente retira-se de dele quebrando ele');
INSERT INTO verses VALUES (25403, 42, 9, 40, 'e supliquei o discípulos teu para que expulsem isso e não puderam');
INSERT INTO verses VALUES (25404, 42, 9, 41, 'respondendo porém o Iesous disse Ômega geração incrédulo e tendo-sido-pervertida até quando serei junto-a vos e suportarei vosso traz aqui o filho teu');
INSERT INTO verses VALUES (25405, 42, 9, 42, 'ainda porém aproximando-se dele Rasgou ele o demônio e convulsionou repreendeu porém o Iesous o espírito o impuro e curou o servo e devolveu ele o pai dele');
INSERT INTO verses VALUES (25406, 42, 9, 43, 'ficavam-espantados porém todos sobre o majestade o de-Theos todos porém admirando sobre todos o qual fazia disse junto-a o discípulos dele');
INSERT INTO verses VALUES (25407, 42, 9, 44, 'Ponde vós para o ouvidos vosso o palavras estes o pois Filho o do-homem está-para ser-entregue para mãos dos-homens');
INSERT INTO verses VALUES (25408, 42, 9, 45, 'o porém ignoravam o palavra isto e era tendo-sido-encoberto de deles para que não percebam isso e temiam Perguntar ele acerca-de o palavra deste');
INSERT INTO verses VALUES (25409, 42, 9, 46, 'Entrou porém raciocínio em a-eles o quem partícula-condicional seria maior deles');
INSERT INTO verses VALUES (25410, 42, 9, 47, 'o porém Iesous sei o raciocínio o do-coração deles tomando criança estabeleceu ele de-junto-de si-mesmo');
INSERT INTO verses VALUES (25411, 42, 9, 48, 'e disse a-eles o qual se receba isto o criança sobre o no-nome meu mim recebe e o qual partícula-condicional mim receba recebe o enviante me o pois menor em todos a-vós sendo este é grande');
INSERT INTO verses VALUES (25412, 42, 9, 49, 'Tendo-respondido porém o João disse Mestre vimos alguém em o no-nome teu lançando-fora demônios e impedíamos ele que não segue com nosso');
INSERT INTO verses VALUES (25413, 42, 9, 50, 'disse porém junto-a ele Iesous não impedis o qual pois não é segundo vosso em-favor-de vosso é');
INSERT INTO verses VALUES (25414, 42, 9, 51, 'aconteceu porém em o ser-completado o do-dia o ascensão dele e ele o rosto Firmou o ir para Jerusalém');
INSERT INTO verses VALUES (25415, 42, 9, 52, 'e enviou anjo antes-de face dele e tendo-ido entraram para aldeia samaritanos de-modo-que preparar a ele');
INSERT INTO verses VALUES (25416, 42, 9, 53, 'e não receberam ele que o rosto dele era indo para Jerusalém');
INSERT INTO verses VALUES (25417, 42, 9, 54, 'vendo porém o discípulos Tiago e João disseram Kyrie queres digamos fogo descer de o do-céu e consumir eles');
INSERT INTO verses VALUES (25418, 42, 9, 55, 'voltando-se porém repreendeu a-eles');
INSERT INTO verses VALUES (25419, 42, 9, 56, 'e foram para outra aldeia');
INSERT INTO verses VALUES (25420, 42, 9, 57, 'e indo deles em o caminho disse alguém junto-a ele Seguirei a-ti onde se partes');
INSERT INTO verses VALUES (25421, 42, 9, 58, 'e disse a ele o Iesous o raposas tocas têm e o aves o do-céu aninharás o porém Filho o do-homem não tem onde o cabeça cama');
INSERT INTO verses VALUES (25422, 42, 9, 59, 'disse porém junto-a outro Segue a-mim o porém disse Permite a-mim primeiro ao-que-partiu sepultar o Pai meu');
INSERT INTO verses VALUES (25423, 42, 9, 60, 'disse porém a ele Deixa o mortos sepultar o deles-mesmos mortos tu porém partindo anuncia o reino o de-Theos');
INSERT INTO verses VALUES (25424, 42, 9, 61, 'disse porém e outro Seguirei a-ti Kyrie primeiro porém permite a-mim despedir-se o para o casa meu');
INSERT INTO verses VALUES (25425, 42, 9, 62, 'disse porém junto-a ele o Iesous ninguém tendo-lançado-sobre o mão sobre arado e vendo para o atrás apropriado é o no-reino o de-Theos');
INSERT INTO chapters VALUES (983, 42, 10, 42);
INSERT INTO verses VALUES (25426, 42, 10, 1, 'com porém estas-coisas mostrou-publicamente o Kyrios outros setenta e enviou eles cada dois antes-de face dele para toda cidade e lugar do-qual estava-prestes-a ele vir');
INSERT INTO verses VALUES (25427, 42, 10, 2, 'dizia porém junto-a eles o por-um-lado colheita muito o porém trabalhadores poucos suplicai portanto o do-Kyrios o ceifa para-que trabalhadores expulse para o ceifa dele');
INSERT INTO verses VALUES (25428, 42, 10, 3, 'ide eis envio vos como cordeiros em no-meio lobos');
INSERT INTO verses VALUES (25429, 42, 10, 4, 'não carregai bolsa não alforje não sandálias e ninguém segundo o caminho saudeis');
INSERT INTO verses VALUES (25430, 42, 10, 5, 'para o qual e/mas partícula-condicional entreis casa primeiro dizeis paz o na-casa neste');
INSERT INTO verses VALUES (25431, 42, 10, 6, 'e se ali seja Filho paz descansará-sobre sobre ele o paz vosso se porém de-outro-modo sobre vos retornará');
INSERT INTO verses VALUES (25432, 42, 10, 7, 'em a-ela porém o casa permanecei Comendo e bebendo o de-junto-de deles digno pois o trabalhador o salário dele não passai de da-casa para casa');
INSERT INTO verses VALUES (25433, 42, 10, 8, 'e para o qual partícula-condicional cidade entreis e recebam vos comeis o as-coisas-postas-diante a-vós');
INSERT INTO verses VALUES (25434, 42, 10, 9, 'e curai o em a-ela fracos e dizeis a-eles Tem-se-aproximado sobre vos o reino o de-Theos');
INSERT INTO verses VALUES (25435, 42, 10, 10, 'para o qual e/mas partícula-condicional cidade entreis e não recebam vos saindo para o praças dela dizei');
INSERT INTO verses VALUES (25436, 42, 10, 11, 'e o poeira o tendo-sido-unido a-nós de o cidade vosso para o pés limpamos a-vós porém isto sabeis que aproximou-se o reino o de-Theos');
INSERT INTO verses VALUES (25437, 42, 10, 12, 'digo a-vós que Sodoma em o dia naquela mais-tolerável será ou o na-cidade naquela');
INSERT INTO verses VALUES (25438, 42, 10, 13, 'ai a-ti Corazim ai a-ti Betsaida que se em Tiro e Sidom tornaram-se o poderes o acontecidas em a-vós outrora partícula-condicional em saco e cinza sentados arrependeram-se');
INSERT INTO verses VALUES (25439, 42, 10, 14, 'porém Tiro e Sidom mais-tolerável será em o juízo ou a-vós');
INSERT INTO verses VALUES (25440, 42, 10, 15, 'e tu Cafarnaum não até do-céu serás-exaltado até o Hades desças');
INSERT INTO verses VALUES (25441, 42, 10, 16, 'o ouvindo vosso mim ouve e o rejeitando vos mim rejeita o porém mim rejeitando rejeita o enviante me');
INSERT INTO verses VALUES (25442, 42, 10, 17, 'Retornaram porém o setenta com alegria dizendo Kyrie e o demônios sujeita-se a-nós em o no-nome teu');
INSERT INTO verses VALUES (25443, 42, 10, 18, 'disse porém a-eles Contemplavam o Satanás como relâmpago de o do-céu tendo-caído');
INSERT INTO verses VALUES (25444, 42, 10, 19, 'eis dei a-vós o autoridade o pisar em-cima serpentes e escorpiões e sobre toda o poder o Inimigo e nada vos não não cometerá-injustiça');
INSERT INTO verses VALUES (25445, 42, 10, 20, 'porém em neste não alegrai-vos que o espíritos a-vós sujeita-se alegrai-vos porém que o nomes vosso tem-sido-inscrito em o nos-céus');
INSERT INTO verses VALUES (25446, 42, 10, 21, 'em a-ela o hora exultou o Espírito o no-santo e disse Confesso a-ti Pai Kyrie o do-céu e o da-terra que escondeste estas-coisas de sábios e entendidos e revelaste eles infantes sim o Pai que assim boa-vontade aconteceu diante-de teu');
INSERT INTO verses VALUES (25447, 42, 10, 22, 'todas-as-coisas a-mim foi-entregue sob o do-Pai meu e ninguém conhece quem é o Filho se não o Pai e quem é o Pai se não o Filho e o qual se queira o Filho revelar');
INSERT INTO verses VALUES (25448, 42, 10, 23, 'e voltando-se junto-a o discípulos segundo própria disse bem-aventurados o olhos o vendo o qual vede');
INSERT INTO verses VALUES (25449, 42, 10, 24, 'digo pois a-vós que muitos profetas e reis quiseram ver o qual vós vede e não viram e ouvir o qual ouvi e não ouviram');
INSERT INTO verses VALUES (25450, 42, 10, 25, 'e eis perito-na-lei alguém levantou-se tentando ele dizendo Mestre quê tendo-feito vida eterno herdarei');
INSERT INTO verses VALUES (25451, 42, 10, 26, 'o porém disse junto-a ele em o lei quê está-escrito como lês');
INSERT INTO verses VALUES (25452, 42, 10, 27, 'o porém respondendo disse Amarás Kyrion o Theos teu de de-toda o do-coração teu e em toda o alma teu e em toda o força teu e em toda o entendimento teu e o próximo teu como a-ti-mesmo');
INSERT INTO verses VALUES (25453, 42, 10, 28, 'disse porém a ele Retamente respondeste isto faze e viva');
INSERT INTO verses VALUES (25454, 42, 10, 29, 'o porém querendo justificar si-mesmo disse junto-a o Iesous e quem é meu próximo');
INSERT INTO verses VALUES (25455, 42, 10, 30, 'Tendo-respondido o Iesous disse Homem alguém descia de Jerusalém para Jericó e ladrões caiu-entre o qual e tendo-despido ele e pragas tendo-posto-sobre foram deixando Meio-morto');
INSERT INTO verses VALUES (25456, 42, 10, 31, 'segundo coincidência porém sacerdote alguém descia em o caminho naquela e vendo ele passou-pelo-lado-oposto');
INSERT INTO verses VALUES (25457, 42, 10, 32, 'semelhantemente porém e Levita segundo o lugar vindo e vendo passou-pelo-lado-oposto');
INSERT INTO verses VALUES (25458, 42, 10, 33, 'Samaritano e/mas alguém caminhando veio segundo ele e vendo compadeceu-se');
INSERT INTO verses VALUES (25459, 42, 10, 34, 'e aproximando-se atou o feridas dele Derramando-sobre azeite e vinho tendo-feito-montar porém ele sobre o próprio animal conduziu ele para hospedaria e cuidou dele');
INSERT INTO verses VALUES (25460, 42, 10, 35, 'e sobre o amanhã tendo-expulsado dois denários deu o hospedaria e disse Cuida dele e o qual algo partícula-condicional gastes-além eu em o retornar me retribuirei a-ti');
INSERT INTO verses VALUES (25461, 42, 10, 36, 'quem destes o três próximo parece a-ti ter-acontecido o tendo-caído-em para o salteadores');
INSERT INTO verses VALUES (25462, 42, 10, 37, 'o porém disse o tendo-feito o misericórdia com dele disse porém a ele o Iesous vai e tu faze semelhantemente');
INSERT INTO verses VALUES (25463, 42, 10, 38, 'em porém o ir eles ele entrou para aldeia algum mulher e/mas alguém em-nome Marta acolheu ele para o casa');
INSERT INTO verses VALUES (25464, 42, 10, 39, 'e estas coisas era irmã sendo-chamada Miriam o qual e tendo-se-sentado-ao-lado junto-a o pés o do-Kyrios ouvia o palavra dele');
INSERT INTO verses VALUES (25465, 42, 10, 40, 'o porém Marta estava-distraída acerca-de muita serviço tendo-se-apresentado porém disse Kyrie não importa a-ti que o irmã meu somente me deixou servir dize portanto a-ela para que a-mim ajude-junto');
INSERT INTO verses VALUES (25466, 42, 10, 41, 'respondendo porém disse a-ela o Kyrios Marta Marta preocupas-te e perturbas-te acerca-de muitas-coisas');
INSERT INTO verses VALUES (25467, 42, 10, 42, 'poucos e/mas é necessidade ou um Maria pois o boa porção escolheu a-qual não será-tirado dela');
INSERT INTO chapters VALUES (984, 42, 11, 54);
INSERT INTO verses VALUES (25468, 42, 11, 1, 'e aconteceu em o ser ele em no-lugar a-alguém orando como cessou disse alguém o discípulos dele junto-a ele Kyrie ensina nos orar assim-como e João ensinou o discípulos dele');
INSERT INTO verses VALUES (25469, 42, 11, 2, 'disse porém a-eles quando oreis dizeis Pai seja-santificado o nome teu venha o reino teu');
INSERT INTO verses VALUES (25470, 42, 11, 3, 'o pão nosso o necessário dá a-nós o segundo dia');
INSERT INTO verses VALUES (25471, 42, 11, 4, 'e deixa a-nós o do-pecado nosso e pois eles-mesmos perdoamos todo devendo a-nós e não conduzas-para-dentro nos para tentação');
INSERT INTO verses VALUES (25472, 42, 11, 5, 'e disse junto-a eles Quem de vosso terá amigo e irá junto-a ele meia-noite e diga a ele Amigo empresta a-mim três pães');
INSERT INTO verses VALUES (25473, 42, 11, 6, 'uma-vez-que amigo meu apresentou-se de do-caminho para me e não tenho o qual porei-diante a ele');
INSERT INTO verses VALUES (25474, 42, 11, 7, 'e-aquele por-dentro respondendo diga não a-mim trabalhos apresenta já o porta tem-sido-fechado e o crianças meu com mim para o leito são não posso levantando-se dar a-ti');
INSERT INTO verses VALUES (25475, 42, 11, 8, 'digo a-vós se e não dará a ele levantando-se através-de o ser amigo dele através pois o impudência dele levantando-se dará a ele quanto tem-necessidade');
INSERT INTO verses VALUES (25476, 42, 11, 9, 'eu-também a-vós digo pedi e será-dado a-vós buscais e encontrareis batei e será-aberto a-vós');
INSERT INTO verses VALUES (25477, 42, 11, 10, 'todo pois o pedindo recebe e o buscando encontra e o batendo será-aberto');
INSERT INTO verses VALUES (25478, 42, 11, 11, 'quem porém de vosso o Pai pedirá o Filho Peixe não em-troca-de peixe serpente a ele dará');
INSERT INTO verses VALUES (25479, 42, 11, 12, 'ou e pedirá Ovo dará a ele escorpião');
INSERT INTO verses VALUES (25480, 42, 11, 13, 'se portanto vós maus existindo sei dons boas-coisas dar o filhos vosso quanto mais o Pai o de do-céu dará espírito santo o pedem ele');
INSERT INTO verses VALUES (25481, 42, 11, 14, 'e era lançando-fora demônio e ele era mudo aconteceu porém o demônio tendo-saído falou o mudo e admiraram-se o multidões');
INSERT INTO verses VALUES (25482, 42, 11, 15, 'alguns porém de deles disseram em Belzebu o governante o demônios expulsa o demônios');
INSERT INTO verses VALUES (25483, 42, 11, 16, 'outros porém tentando sinal de do-céu buscavam de-junto-de dele');
INSERT INTO verses VALUES (25484, 42, 11, 17, 'ele porém sei deles o pensamentos disse a-eles toda reino sobre A-si-mesma tendo-sido-dividida é-desolada e casa sobre casa cai');
INSERT INTO verses VALUES (25485, 42, 11, 18, 'se porém e o Satanás sobre si-mesmo foi-repartida como será-estabelecido o reino dele que dizeis em Belzebu expulsar me o demônios');
INSERT INTO verses VALUES (25486, 42, 11, 19, 'se porém eu em Belzebu expulso o demônios o filhos vosso em a-quem expulsam através-de isto eles-mesmos vosso juízes serão');
INSERT INTO verses VALUES (25487, 42, 11, 20, 'se porém em dedo de-Theos eu expulso o demônios então chegou sobre vos o reino o de-Theos');
INSERT INTO verses VALUES (25488, 42, 11, 21, 'quando o forte tendo-se-armado guarde o si-mesmo pátio em paz é o posses dele');
INSERT INTO verses VALUES (25489, 42, 11, 22, 'quando porém mais-forte dele tendo-sobrevindo vença ele o armadura-completa dele levanta sobre o qual confiava e o despojos dele distribui');
INSERT INTO verses VALUES (25490, 42, 11, 23, 'o não sendo com mim segundo mim é e o não reunindo com mim dispersa');
INSERT INTO verses VALUES (25491, 42, 11, 24, 'quando o impuro espírito saia de o do-homem atravessa através-de sem-água lugares buscando descanso e não encontravam diz Retornarei para o casa meu de-onde saíram');
INSERT INTO verses VALUES (25492, 42, 11, 25, 'e tendo-vindo encontra tendo-sido-varrido e tendo-sido-adornado');
INSERT INTO verses VALUES (25493, 42, 11, 26, 'então vai e toma-consigo outras espíritos piores si-mesmo sete e entrando habita ali e torna-se o últimas o do-homem daquele piores o primeiro');
INSERT INTO verses VALUES (25494, 42, 11, 27, 'aconteceu porém em o dizer ele estas-coisas tendo-eu-amaldiçoado alguém voz mulher de o da-multidão disse a ele Bem-aventurada o ventre o tendo-carregado te e seios o qual amamentaste');
INSERT INTO verses VALUES (25495, 42, 11, 28, 'ele porém disse Antes-pelo-contrário bem-aventurados o ouvindo o palavra o de-Theos e guardando');
INSERT INTO verses VALUES (25496, 42, 11, 29, 'o porém multidões ajuntando-se-sobre começou dizer o geração esta geração má é sinal busca e sinal não será-dado a-ela se não o sinal Jonas');
INSERT INTO verses VALUES (25497, 42, 11, 30, 'assim-como pois aconteceu Jonas o ninivitas sinal assim será e o Filho o do-homem o geração nesta');
INSERT INTO verses VALUES (25498, 42, 11, 31, 'rainha sul será-levantado em o juízo com o homens o geração desta e condenará eles que veio de o confins o da-terra ouvir o sabedoria Salomão e eis mais Salomão aqui');
INSERT INTO verses VALUES (25499, 42, 11, 32, 'homens Ninivitas ressuscitarão em o juízo com o geração desta e condenarão ela que arrependeram-se para o pregação Jonas e eis mais Jonas aqui');
INSERT INTO verses VALUES (25500, 42, 11, 33, 'ninguém lâmpada tendo-acendido para oculto põe nem sob o alqueire mas sobre o candelabro para que o entrando o brilho vejam');
INSERT INTO verses VALUES (25501, 42, 11, 34, 'o lâmpada o corpo é o olho teu quando o olho teu simples seja e todo o corpo teu luminoso é quando porém mau seja e o corpo teu tenebroso');
INSERT INTO verses VALUES (25502, 42, 11, 35, 'observa portanto não o luz o em a-ti trevas é');
INSERT INTO verses VALUES (25503, 42, 11, 36, 'se portanto o corpo teu todo luminoso não Tendo parte algo tenebroso será luminoso todo como quando o lâmpada o relâmpago ilumine te');
INSERT INTO verses VALUES (25504, 42, 11, 37, 'em porém o falar pede ele fariseu para-que coma-a-refeição de-junto-de a ele entrando porém reclinou-se');
INSERT INTO verses VALUES (25505, 42, 11, 38, 'o porém fariseu vendo admirou-se que não primeiro foi-batizado antes-de o refeição');
INSERT INTO verses VALUES (25506, 42, 11, 39, 'disse porém o Kyrios junto-a ele agora vós o fariseus o de-fora o cálice e o bandeja limpais o porém por-dentro vosso está-cheio rapina e maldade');
INSERT INTO verses VALUES (25507, 42, 11, 40, 'insensatos não o tendo-feito o de-fora e o por-dentro fez');
INSERT INTO verses VALUES (25508, 42, 11, 41, 'porém o estando-dentro dai esmola e eis todas-as-coisas pura a-vós é');
INSERT INTO verses VALUES (25509, 42, 11, 42, 'mas ai a-vós o Fariseus que dizimais o hortelã e o arruda e todo hortaliça e passais o juízo e o amor o de-Theos estas-coisas porém é necessário fazer e-aquelas não estar-presente');
INSERT INTO verses VALUES (25510, 42, 11, 43, 'ai a-vós o Fariseus que amai o primeiro-assento em o nas-sinagogas e o saudações em o praças');
INSERT INTO verses VALUES (25511, 42, 11, 44, 'ai a-vós que sois como o sepulcros o obscuras e o homens o andando em-cima não sei');
INSERT INTO verses VALUES (25512, 42, 11, 45, 'Tendo-respondido e/mas alguém o peritos-na-lei diz a ele Mestre estas-coisas dizendo e nos ultrajas');
INSERT INTO verses VALUES (25513, 42, 11, 46, 'o porém disse e a-vós o legistas ai que carregais o homens cargas difíceis-de-carregar e eles-mesmos um o dedos vosso não tocais o com-cargas');
INSERT INTO verses VALUES (25514, 42, 11, 47, 'ai a-vós que edificai o sepulcros o profetas o porém pais vosso mataram eles');
INSERT INTO verses VALUES (25515, 42, 11, 48, 'então testemunhas sois e consentis-juntamente o obra o dos-pais vosso que eles-mesmos por-um-lado mataram eles vós porém edificai');
INSERT INTO verses VALUES (25516, 42, 11, 49, 'através-de isto e o sabedoria o de-Theos disse Enviarei para eles profetas e apóstolos e de deles matarão e perseguirão');
INSERT INTO verses VALUES (25517, 42, 11, 50, 'para que seja-requerido o sangue todos o profetas o tendo-sido-derramado de fundação do-mundo de o geração desta');
INSERT INTO verses VALUES (25518, 42, 11, 51, 'de sangue Abel até sangue Zacarias o do-que-pereceu entre o altar e o da-casa sim digo a-vós será-requerido de o geração desta');
INSERT INTO verses VALUES (25519, 42, 11, 52, 'ai a-vós o legistas que levastes o chave o do-conhecimento eles-mesmos não entrastes e o entrando impedistes');
INSERT INTO verses VALUES (25520, 42, 11, 53, 'E-dali tendo-saído dele começaram o escribas e o fariseus terrivelmente guardar-rancor e interrogar-insidiosamente ele acerca-de mais');
INSERT INTO verses VALUES (25521, 42, 11, 54, 'emboscando ele apanhar algo de o da-boca dele');
INSERT INTO chapters VALUES (985, 42, 12, 59);
INSERT INTO verses VALUES (25522, 42, 12, 1, 'em o qual Tendo-sido-reunidas o miríades o da-multidão de-modo-que pisar uns-aos-outros começou dizer junto-a o discípulos dele primeiro Guardai-vos si-mesmos de o fermento a-qual é Hipocrisia o fariseus');
INSERT INTO verses VALUES (25523, 42, 12, 2, 'nada porém tendo-sido-encoberto é o qual não será-revelado e oculto o qual não será-conhecido');
INSERT INTO verses VALUES (25524, 42, 12, 3, 'em-vez-de o qual quanto em o trevas dizei em o luz será-ouvido e o qual junto-a o ouvido falastes em o aposentos-interiores será-proclamado sobre o terraços');
INSERT INTO verses VALUES (25525, 42, 12, 4, 'digo porém a-vós o amigos meu não temais de o matando o corpo e com estas-coisas não tendo mais-abundantemente algo fazer');
INSERT INTO verses VALUES (25526, 42, 12, 5, 'mostrarei porém a-vós quem temais temei o com o matar tendo autoridade lançar-dentro para o Geena sim digo a-vós este temei');
INSERT INTO verses VALUES (25527, 42, 12, 6, 'não cinco pardais são-vendidos asses dois e um de deles não é tendo-sido-esquecido diante-de o de-Theos');
INSERT INTO verses VALUES (25528, 42, 12, 7, 'mas e o cabelos o cabeça vosso todas têm-sido-contados não temeis muitos pardais diferis');
INSERT INTO verses VALUES (25529, 42, 12, 8, 'digo porém a-vós todo o qual partícula-condicional confesse em mim diante-de o dos-homens e o Filho o do-homem confessará em a ele diante-de o anjo o de-Theos');
INSERT INTO verses VALUES (25530, 42, 12, 9, 'o porém tendo-negado me diante-de o dos-homens negará diante-de o anjo o de-Theos');
INSERT INTO verses VALUES (25531, 42, 12, 10, 'e todo o qual dirá palavra para o Filho o do-homem será-perdoado a ele o porém para o santo espírito tendo-blasfemado não será-perdoado');
INSERT INTO verses VALUES (25532, 42, 12, 11, 'quando porém tragam-para-dentro vos sobre o sinagogas e o principados e o da-autoridade não preocupeis como ou quê vos-defendais ou quê digais');
INSERT INTO verses VALUES (25533, 42, 12, 12, 'o pois santo espírito ensinará vos em a-ela o hora o qual é necessário dizer');
INSERT INTO verses VALUES (25534, 42, 12, 13, 'disse e/mas alguém de o da-multidão a ele Mestre dize o ao-irmão meu repartir com mim o herança');
INSERT INTO verses VALUES (25535, 42, 12, 14, 'o porém disse a ele Homem quem me constituiu juiz ou repartidor sobre vos');
INSERT INTO verses VALUES (25536, 42, 12, 15, 'disse porém junto-a eles Vede e guardai-vos de toda ganância que não em o abundar a-alguém o vida dele é de o posses a ele');
INSERT INTO verses VALUES (25537, 42, 12, 16, 'disse porém parábola junto-a eles dizendo do-homem algum rico produziu-abundantemente o região');
INSERT INTO verses VALUES (25538, 42, 12, 17, 'e deliberava em si-mesmo dizendo quê farei que não tenho onde reunirei o frutos meu');
INSERT INTO verses VALUES (25539, 42, 12, 18, 'e disse isto farei derrubarei meu o celeiros e maiores edificarei e reunirei ali todas-as-coisas o trigo e o boas-coisas meu');
INSERT INTO verses VALUES (25540, 42, 12, 19, 'e direi o alma meu Alma tens muitas-coisas boas-coisas postos para anos muitas-coisas descansa come bebe alegra-te');
INSERT INTO verses VALUES (25541, 42, 12, 20, 'disse porém a ele o Theos Insensato nesta o à-noite o alma teu exigem-de-volta de teu o qual porém preparaste a-quem será');
INSERT INTO verses VALUES (25542, 42, 12, 21, 'assim o entesourando a-si-mesmo e não para Theos enriquecendo');
INSERT INTO verses VALUES (25543, 42, 12, 22, 'disse porém junto-a o discípulos dele através-de isto digo a-vós não andais-ansiosos o alma quê comais nem o corpo quê vistais');
INSERT INTO verses VALUES (25544, 42, 12, 23, 'o pois alma mais é o alimento e o corpo o vestimenta');
INSERT INTO verses VALUES (25545, 42, 12, 24, 'considerai o corvos que nem semeiam nem ceifam o qual não é quarto-interior nem celeiro e o Theos alimenta eles quanto mais vós diferis o aves');
INSERT INTO verses VALUES (25546, 42, 12, 25, 'quem porém de vosso preocupando-se pode sobre o estatura dele acrescentar côvado');
INSERT INTO verses VALUES (25547, 42, 12, 26, 'se portanto nem mínimo podeis quê acerca-de o restantes andais-ansiosos');
INSERT INTO verses VALUES (25548, 42, 12, 27, 'considerai o lírios como nem fia nem Tece digo porém a-vós nem Salomão em toda o glória dele vestiu-se como um destes');
INSERT INTO verses VALUES (25549, 42, 12, 28, 'se porém em campo o erva sendo hoje e amanhã para forno sendo-lançado o Theos assim veste quanto mais vos pouca-fé');
INSERT INTO verses VALUES (25550, 42, 12, 29, 'e vós não buscais quê comais e quê bebais e não inquieteis-vos');
INSERT INTO verses VALUES (25551, 42, 12, 30, 'estas-coisas pois todas-as-coisas o nações o do-mundo buscam vosso porém o Pai sei que necessitais destes');
INSERT INTO verses VALUES (25552, 42, 12, 31, 'porém buscais o reino dele e estas-coisas será-acrescentado a-vós');
INSERT INTO verses VALUES (25553, 42, 12, 32, 'não teme o pouco pequeno-rebanho que agradou-se o Pai vosso dar a-vós o reino');
INSERT INTO verses VALUES (25554, 42, 12, 33, 'Vendei o posses vosso e dai esmola fazei si-mesmos bolsas não sendo-envelhecidas tesouro inesgotável em o nos-céus onde ladrão não aproxima-se nem tua corrompe');
INSERT INTO verses VALUES (25555, 42, 12, 34, 'onde pois é o tesouro vosso ali e o coração vosso será');
INSERT INTO verses VALUES (25556, 42, 12, 35, 'Sejam vosso o lombos tendo-sido-cingidas e o candeias queimando-se');
INSERT INTO verses VALUES (25557, 42, 12, 36, 'e vós semelhantes aos-homens esperando o Kyrion deles-mesmos quando retorne de o casamento para que tendo-vindo e tendo-batido imediatamente abram a ele');
INSERT INTO verses VALUES (25558, 42, 12, 37, 'bem-aventurados o servos aqueles o qual vindo o kyrios encontrará vigiando amém digo a-vós que se-cingirá e reclinará eles e tendo-passado servirá a-eles');
INSERT INTO verses VALUES (25559, 42, 12, 38, 'e-se em o segunda e-se em o no-terceiro na-prisão venha e encontre assim bem-aventurados são aqueles');
INSERT INTO verses VALUES (25560, 42, 12, 39, 'isto porém sabeis que se sei o dono-de-casa qual hora o ladrão vem não partícula-condicional deixou ser-arrombada o casa dele');
INSERT INTO verses VALUES (25561, 42, 12, 40, 'e vós tornai-vos prontos que o qual hora não pensais o Filho o do-homem vem');
INSERT INTO verses VALUES (25562, 42, 12, 41, 'disse porém o Pedro Kyrios junto-a nos o parábola esta dizes ou e junto-a todos');
INSERT INTO verses VALUES (25563, 42, 12, 42, 'e disse o Kyrios Quem então é o fiel administrador o prudente o qual estabelecerá o kyrios sobre o cura dele o dar em tempo o ração-de-cereal');
INSERT INTO verses VALUES (25564, 42, 12, 43, 'bem-aventurado o servo aquele o qual vindo o kyrios dele encontrará fazendo assim');
INSERT INTO verses VALUES (25565, 42, 12, 44, 'verdadeiramente digo a-vós que sobre todos o existem dele estabelecerá ele');
INSERT INTO verses VALUES (25566, 42, 12, 45, 'se porém diga o servo aquele em o no-coração dele Demora o senhor meu vir e comece bater o crianças e o servas comer e e beber e embriagar-se');
INSERT INTO verses VALUES (25567, 42, 12, 46, 'virá o kyrios o servo daquele em dia o qual não espera e em hora o qual não conhece e cortará-em-dois ele e o parte dele com o incrédulos porá');
INSERT INTO verses VALUES (25568, 42, 12, 47, 'aquele porém o servo o sabendo o vontade o do-Kyrios dele e não Tendo-preparado ou tendo-feito junto-a o vontade dele será-espancado muitas');
INSERT INTO verses VALUES (25569, 42, 12, 48, 'o porém não sabendo tendo-feito porém dignos golpes será-espancado poucas todo porém o qual foi-dado muito muito será-buscado de-junto-de dele e o qual confiaram muito abundantemente pedirão ele');
INSERT INTO verses VALUES (25570, 42, 12, 49, 'fogo vieram lançar sobre o terra e quê quero se já foi-aceso');
INSERT INTO verses VALUES (25571, 42, 12, 50, 'batismo porém tenho ser-batizado e como sou-constrangido até de-quem seja-completado');
INSERT INTO verses VALUES (25572, 42, 12, 51, 'pensais que paz cheguei dar em o terra não digo a-vós mas ou divisão');
INSERT INTO verses VALUES (25573, 42, 12, 52, 'serão pois de o agora cinco em um na-casa tendo-sido-divididos três sobre dois e dois sobre três');
INSERT INTO verses VALUES (25574, 42, 12, 53, 'serão-divididos Pai sobre filho e Filho sobre pai mãe sobre filha e filha sobre o mãe sogra sobre o noiva dela e noiva sobre o sogra');
INSERT INTO verses VALUES (25575, 42, 12, 54, 'Dizia porém e o às-multidões quando vejais nuvem nascendo sobre ocidente imediatamente dizeis que Chuva vem e torna-se assim');
INSERT INTO verses VALUES (25576, 42, 12, 55, 'e quando sul soprando dizeis que Calor-abrasador será e torna-se');
INSERT INTO verses VALUES (25577, 42, 12, 56, 'hipócritas o rosto o da-terra e o do-céu sei provar o tempo porém este como não examinai');
INSERT INTO verses VALUES (25578, 42, 12, 57, 'quê porém e de deles-mesmos não julgais o justo');
INSERT INTO verses VALUES (25579, 42, 12, 58, 'como pois vais com o adversário teu sobre governante em o caminho dá trabalho ter-sido-libertado de dele não alguma-vez arraste te junto-a o juiz e o juiz te entregará o cobrador e o cobrador te lançará para prisão');
INSERT INTO verses VALUES (25580, 42, 12, 59, 'digo a-ti não não saias dali até e o último lepto devolvas');
INSERT INTO chapters VALUES (986, 42, 13, 35);
INSERT INTO verses VALUES (25581, 42, 13, 1, 'Estavam-presentes e/mas alguns em a ele o tempo anunciando a ele acerca-de o Galileus o qual o sangue Pilatos Misturou com o sacrifícios deles');
INSERT INTO verses VALUES (25582, 42, 13, 2, 'e respondendo disse a-eles Pensais que o galileus estes pecadores de-junto-de todos o Galileus tornaram-se que estas-coisas têm-sofrido');
INSERT INTO verses VALUES (25583, 42, 13, 3, 'não digo a-vós mas se não arrependais-vos todos semelhantemente perecereis');
INSERT INTO verses VALUES (25584, 42, 13, 4, 'ou aqueles o dez oito sobre o qual caiu o torre em o Siloé e matou eles pensais que eles-mesmos devedores tornaram-se de-junto-de todos o homens o habitando Jerusalém');
INSERT INTO verses VALUES (25585, 42, 13, 5, 'não digo a-vós mas se não arrependais-vos todos da-mesma-forma perecereis');
INSERT INTO verses VALUES (25586, 42, 13, 6, 'Dizia porém esta o parábola figueira tinha alguém tendo-sido-plantada em o vinha dele e veio buscando fruto em a-ela e não encontrou');
INSERT INTO verses VALUES (25587, 42, 13, 7, 'disse porém junto-a o vinhateiro Eis três anos de o qual venho buscando fruto em o figueira nesta e não encontro corta ela para que quê e o terra anula');
INSERT INTO verses VALUES (25588, 42, 13, 8, 'o porém respondendo diz a ele Kyrie deixa ela e isto o ano até de-quem cavarei acerca-de ela e lance esterco');
INSERT INTO verses VALUES (25589, 42, 13, 9, 'e-se por-um-lado faça fruto para o estando-a-ponto-de se porém de-outro-modo cortarás-fora ela');
INSERT INTO verses VALUES (25590, 42, 13, 10, 'era porém ensinando em uma o sinagogas em o nos-sábados');
INSERT INTO verses VALUES (25591, 42, 13, 11, 'e eis mulher espírito tendo fraqueza anos dez oito e era estando-encurvada e não podendo erguer-se para o completo');
INSERT INTO verses VALUES (25592, 42, 13, 12, 'vendo porém ela o Iesous chamou e disse a-ela Mulher tens-sido-solta o fraqueza teu');
INSERT INTO verses VALUES (25593, 42, 13, 13, 'e pôs-sobre a-ela o mãos e imediatamente foi-endireitada e glorificava o Theos');
INSERT INTO verses VALUES (25594, 42, 13, 14, 'respondendo porém o chefe-da-sinagoga indignando-se que o no-sábado curou o Iesous dizia o à-multidão que Seis dias são em o qual é necessário trabalhar em a-elas portanto vindos sois-curados e não o dia o do-sábado');
INSERT INTO verses VALUES (25595, 42, 13, 15, 'respondeu porém a ele o Kyrios e disse Hipócritas cada-um vosso o no-sábado não desata o boi dele ou o jumento de o manjedoura e tendo-conduzido rega');
INSERT INTO verses VALUES (25596, 42, 13, 16, 'esta porém filha Abraão sendo o qual Amarrou o Satanás eis dez e oito anos não é necessário ser-desatado de o cadeia deste o dia o do-sábado');
INSERT INTO verses VALUES (25597, 42, 13, 17, 'e estas-coisas dizendo dele eram-envergonhados todos o opondo-se a ele e todo o multidão Alegrava-se sobre todos o gloriosos o acontecendo sob dele');
INSERT INTO verses VALUES (25598, 42, 13, 18, 'Dizia portanto A-quem semelhante é o reino o de-Theos e a-quem compararei ela');
INSERT INTO verses VALUES (25599, 42, 13, 19, 'semelhante é grão mostarda o qual tomando homem lançou para jardim si-mesmo e fez-crescer e aconteceu para árvore e o aves o do-céu aninhou-se em o ramos dele');
INSERT INTO verses VALUES (25600, 42, 13, 20, 'e novamente disse A-quem compararei o reino o de-Theos');
INSERT INTO verses VALUES (25601, 42, 13, 21, 'semelhante é fermento o qual tomando mulher escondeu para farinha satas três até o qual foi-levedado todo');
INSERT INTO verses VALUES (25602, 42, 13, 22, 'e atravessava segundo cidades e aldeias ensinando e jornada fazendo para Jerusalém');
INSERT INTO verses VALUES (25603, 42, 13, 23, 'disse e/mas alguém a ele Kyrie se poucos o os-sendo-salvos o porém disse junto-a eles');
INSERT INTO verses VALUES (25604, 42, 13, 24, 'Lutai entrar através-de o estreita porta que muitos digo a-vós buscarão entrar e não prevalecerão');
INSERT INTO verses VALUES (25605, 42, 13, 25, 'de o qual partícula-condicional seja-levantado o dono-de-casa e feche o porta e comeceis fora estar-de-pé e bater o porta dizendo Kyrie abre a-nós e respondendo dirá a-vós não sei vos de-onde sois');
INSERT INTO verses VALUES (25606, 42, 13, 26, 'então começareis dizer Comemos diante-de teu e bebemos e em o praças nosso ensinaste');
INSERT INTO verses VALUES (25607, 42, 13, 27, 'e dirá dizendo a-vós não sei de-onde sois afastai-vos de mim todos trabalhadores da-injustiça');
INSERT INTO verses VALUES (25608, 42, 13, 28, 'ali será o choro e o ranger o dentes quando vereis Abraão e Isaque e Jacó e todos o profetas em o no-reino o de-Theos vos porém sendo-lançados-fora fora');
INSERT INTO verses VALUES (25609, 42, 13, 29, 'e virão de oriente e ocidente e de norte e sul e serão-reclinados em o no-reino o de-Theos');
INSERT INTO verses VALUES (25610, 42, 13, 30, 'e eis são últimos o qual serão primeiro e são primeiro o qual serão últimos');
INSERT INTO verses VALUES (25611, 42, 13, 31, 'em a-ela o hora aproximaram-se alguns fariseus dizendo a ele Sai e vai daqui que Herodes quer te matar');
INSERT INTO verses VALUES (25612, 42, 13, 32, 'e disse a-eles Tendo-ido dizei o raposa nesta Eis expulso demônios e Curas completo hoje e amanhã e o no-terceiro sou-aperfeiçoado');
INSERT INTO verses VALUES (25613, 42, 13, 33, 'porém é necessário me hoje e amanhã e o seguinte ir que não é-possível profeta perecer fora Jerusalém');
INSERT INTO verses VALUES (25614, 42, 13, 34, 'Jerusalém Jerusalém o matando o profetas e apedrejando o tendo-sido-enviados junto-a ela quantas-vezes quis Reunir o filhos teu o qual modo galinha o de-si-mesma ninhada sob o asas e não quisestes');
INSERT INTO verses VALUES (25615, 42, 13, 35, 'eis é-perdoado a-vós o casa vosso digo porém a-vós não não Vejais me até virá quando digais Bendito o o-que-vem em em-nome do-Kyrios');
INSERT INTO chapters VALUES (987, 42, 14, 35);
INSERT INTO verses VALUES (25616, 42, 14, 1, 'e aconteceu em o vir ele para casa de-alguém o governantes o fariseus no-sábado comer pão e eles-mesmos eram observando ele');
INSERT INTO verses VALUES (25617, 42, 14, 2, 'e eis homem alguém era hidrópico diante-de dele');
INSERT INTO verses VALUES (25618, 42, 14, 3, 'e respondendo o Iesous disse junto-a o peritos-na-lei e Fariseus dizendo É-permitido o no-sábado curar ou não');
INSERT INTO verses VALUES (25619, 42, 14, 4, 'o porém aquietaram-se e tomando curou ele e soltou');
INSERT INTO verses VALUES (25620, 42, 14, 5, 'e junto-a eles disse De-quem vosso Filho ou boi para poço cairá e não imediatamente puxará-para-cima ele em dia o do-sábado');
INSERT INTO verses VALUES (25621, 42, 14, 6, 'e não tiveram-força responder-de-volta junto-a estas-coisas');
INSERT INTO verses VALUES (25622, 42, 14, 7, 'Dizia porém junto-a o tendo-sido-chamados parábola prestando-atenção como o primeiros-lugares foram-escolhidos dizendo junto-a eles');
INSERT INTO verses VALUES (25623, 42, 14, 8, 'quando sejas-chamado Sob de-alguém para bodas não te-reclines para o primeiro-assento não alguma-vez mais-honrado teu seja tendo-sido-chamado sob dele');
INSERT INTO verses VALUES (25624, 42, 14, 9, 'e vindo o te e ele chamando dirá a-ti Dá neste lugar e então comece com vergonha o último lugar reter');
INSERT INTO verses VALUES (25625, 42, 14, 10, 'mas quando sejas-chamado tendo-ido reclina-te para o último lugar para que quando venha o tendo-chamado te dirá a-ti Amigo sobe-mais-acima mais-acima então será a-ti glória diante-de todos o reclinando-se-à-mesa-junto a-ti');
INSERT INTO verses VALUES (25626, 42, 14, 11, 'que todo o exaltando si-mesmo será-humilhado e o humildes si-mesmo será-exaltado');
INSERT INTO verses VALUES (25627, 42, 14, 12, 'Dizia porém e o tendo-chamado ele quando fazes almoço ou ceia não chama o amigos teu nem o irmãos teu nem o parentes teu nem vizinhos ricos não alguma-vez e eles-mesmos convidem-de-volta te e aconteça retribuição a-ti');
INSERT INTO verses VALUES (25628, 42, 14, 13, 'mas quando banquete fazes chama pobres aleijados coxos cegos');
INSERT INTO verses VALUES (25629, 42, 14, 14, 'e bem-aventurado serás que não têm retribuir a-ti será-retribuído pois a-ti em o ressurreição o justos');
INSERT INTO verses VALUES (25630, 42, 14, 15, 'Tendo-ouvido e/mas alguém o reclinando-se-à-mesa-junto estas-coisas disse a ele bem-aventurado qualquer-que comerá pão em o no-reino o de-Theos');
INSERT INTO verses VALUES (25631, 42, 14, 16, 'o porém disse a ele Homem alguém fazia ceia grande e chamou muitos');
INSERT INTO verses VALUES (25632, 42, 14, 17, 'e enviou o servo dele o hora o ceia dizer o tendo-sido-chamados Vinde que já preparadas é');
INSERT INTO verses VALUES (25633, 42, 14, 18, 'e começaram de uma todos recusar o primeiro disse a ele Campo comprei e tenho necessidade saindo ver ele peço te tem me tendo-sido-rejeitado');
INSERT INTO verses VALUES (25634, 42, 14, 19, 'e outro disse Pares clamando comprei cinco e vou examinar elas peço te tem me tendo-sido-rejeitado');
INSERT INTO verses VALUES (25635, 42, 14, 20, 'e outro disse Mulher Casei e através-de isto não posso vir');
INSERT INTO verses VALUES (25636, 42, 14, 21, 'e tendo-chegado o servo anunciou o ao-Kyrios dele estas-coisas então tendo-se-irado o dono-de-casa disse o servo dele Sai rapidamente para o praças e ruelas o cidade e o pobres e aleijados e cegos e coxos introduze aqui');
INSERT INTO verses VALUES (25637, 42, 14, 22, 'e disse o servo Kyrie aconteceu o qual ordenaste e ainda lugar é');
INSERT INTO verses VALUES (25638, 42, 14, 23, 'e disse o kyrios junto-a o servo Sai para o caminhos e cercas e compele entrar para que seja-enchido meu o casa');
INSERT INTO verses VALUES (25639, 42, 14, 24, 'digo pois a-vós que ninguém o varões daqueles o tendo-sido-chamados provará meu o ceia');
INSERT INTO verses VALUES (25640, 42, 14, 25, 'Caminhavam-junto porém a ele multidões muitos e voltando-se disse junto-a eles');
INSERT INTO verses VALUES (25641, 42, 14, 26, 'se alguém vem para me e não odeia o Pai dele e o mãe e o mulher e o filhos e o irmãos e o irmãs ainda e e o alma si-mesmo não pode ser meu discípulo');
INSERT INTO verses VALUES (25642, 42, 14, 27, 'qualquer-que não carrega o cruz si-mesmo e vem atrás meu não pode ser meu discípulo');
INSERT INTO verses VALUES (25643, 42, 14, 28, 'Quem pois de vosso querendo torre edificar não primeiro sentando-se calcula o despesa se tem para completamento');
INSERT INTO verses VALUES (25644, 42, 14, 29, 'para que não alguma-vez tendo-posto dele fundamento e não Sendo-forte completar todos o observando comecem a ele escarnecer');
INSERT INTO verses VALUES (25645, 42, 14, 30, 'dizendo que este o homem começou edificar e não prevaleceu completar');
INSERT INTO verses VALUES (25646, 42, 14, 31, 'ou quem rei indo a-outro rei ponderar para guerra não sentando-se primeiro deliberará se poderoso é em dez em-milhares encontrar o com vinte de-milhares vindo sobre ele');
INSERT INTO verses VALUES (25647, 42, 14, 32, 'se porém de-outro-modo ainda dele longe sendo embaixada tendo-enviado pede o junto-a paz');
INSERT INTO verses VALUES (25648, 42, 14, 33, 'assim portanto todo de vosso o qual não despede-se todos o si-mesmo existem não pode ser meu discípulo');
INSERT INTO verses VALUES (25649, 42, 14, 34, 'belo portanto o sal se porém e o sal torne-se-insípido em a-quem será-temperado');
INSERT INTO verses VALUES (25650, 42, 14, 35, 'nem para terra nem para esterco apropriado é fora lançam isso o tendo ouvidos ouvir ouça');
INSERT INTO chapters VALUES (988, 42, 15, 32);
INSERT INTO verses VALUES (25651, 42, 15, 1, 'eram porém a ele aproximando-se todos o cobradores-de-impostos e o pecadores ouvir dele');
INSERT INTO verses VALUES (25652, 42, 15, 2, 'e murmuravam o e fariseus e o escribas dizendo que este pecadores recebe e come-com a-eles');
INSERT INTO verses VALUES (25653, 42, 15, 3, 'disse porém junto-a eles o parábola esta dizendo');
INSERT INTO verses VALUES (25654, 42, 15, 4, 'Quem homem de vosso tendo cem ovelhas e tendo-perdido de deles um não deixa o noventa nove em o deserto e vai sobre o tendo-se-perdido até encontre isso');
INSERT INTO verses VALUES (25655, 42, 15, 5, 'e encontrando Põe-sobre sobre o ombros dele alegrando-se');
INSERT INTO verses VALUES (25656, 42, 15, 6, 'e vindo para o casa convoca-junto o amigos e o vizinhos dizendo a-eles Alegrai-vos-comigo a-mim que encontraram o ovelha meu o tendo-se-perdido');
INSERT INTO verses VALUES (25657, 42, 15, 7, 'digo a-vós que assim alegria em o no-céu será sobre um pecador arrependendo-se ou sobre noventa nove justos os-quais não necessidade têm arrependimento');
INSERT INTO verses VALUES (25658, 42, 15, 8, 'ou quem mulher dracmas tendo dez se destrua dracma uma não acende lâmpada e varre o casa e busca cuidadosamente até o qual encontre');
INSERT INTO verses VALUES (25659, 42, 15, 9, 'e tendo-encontrado convoca-junto o amigas e vizinhos dizendo Alegrai-vos-comigo a-mim que encontraram o dracma o qual perdi');
INSERT INTO verses VALUES (25660, 42, 15, 10, 'assim digo a-vós torna-se alegria diante-de o anjo o de-Theos sobre um pecador arrependendo-se');
INSERT INTO verses VALUES (25661, 42, 15, 11, 'disse e/mas Homem alguém tinha dois filhos');
INSERT INTO verses VALUES (25662, 42, 15, 12, 'e disse o mais-jovem deles o pai Pai dá a-mim o pertencendo parte o propriedade o porém dividiu a-eles o vida');
INSERT INTO verses VALUES (25663, 42, 15, 13, 'e com não muitas do-dia tendo-reunido todas-as-coisas o mais-jovem Filho viajou para região longe e ali dispersou o propriedade dele vivendo dissolutamente');
INSERT INTO verses VALUES (25664, 42, 15, 14, 'tendo-gastado porém dele todas-as-coisas aconteceu fome Forte segundo o região aquela e ele começou ter-falta');
INSERT INTO verses VALUES (25665, 42, 15, 15, 'e tendo-ido uniu-se um o cidadãos o região daquela e enviou ele para o campos dele apascentar porcos');
INSERT INTO verses VALUES (25666, 42, 15, 16, 'e desejava encher o ventre dele de o alfarrobas o qual comiam o porcos e ninguém dava a ele');
INSERT INTO verses VALUES (25667, 42, 15, 17, 'para si-mesmo porém vindo disse Quantos assalariados o pai meu abundam pães eu porém fome aqui pereço');
INSERT INTO verses VALUES (25668, 42, 15, 18, 'levantando-se irei junto-a o Pai meu e direi a ele Pai pecaram para o céu e diante-de teu');
INSERT INTO verses VALUES (25669, 42, 15, 19, 'não-mais sou digno ser-chamado filho teu faze me como um o salários teu');
INSERT INTO verses VALUES (25670, 42, 15, 20, 'e levantando-se veio junto-a o Pai si-mesmo ainda porém dele longe estando-distante viu ele o Pai dele e compadeceu-se e tendo-corrido caiu-sobre sobre o pescoço dele e beijou-intensamente ele');
INSERT INTO verses VALUES (25671, 42, 15, 21, 'disse porém o Filho a ele Pai pecaram para o céu e diante-de teu não-mais sou digno ser-chamado filho teu');
INSERT INTO verses VALUES (25672, 42, 15, 22, 'disse porém o Pai junto-a o servos dele Rapidamente trazei-para-fora veste-longa o primeiro e vesti ele e dai anel para o mão dele e sandálias para o pés');
INSERT INTO verses VALUES (25673, 42, 15, 23, 'e trazei o novilho o cevado sacrificai e tendo-comido alegremo-nos');
INSERT INTO verses VALUES (25674, 42, 15, 24, 'que este o filho meu morto era e reviveu era tendo-se-perdido e foi-encontrada e começaram alegrar-se');
INSERT INTO verses VALUES (25675, 42, 15, 25, 'era porém o Filho dele o ancião em campo e como o-que-vem aproximou-se o casa ouviu sinfonia e de-danças');
INSERT INTO verses VALUES (25676, 42, 15, 26, 'e tendo-chamado um o crianças inquiria quê partícula-condicional seria estas-coisas');
INSERT INTO verses VALUES (25677, 42, 15, 27, 'o porém disse a ele que o irmão teu chegou e Sacrificou o pai teu o novilho o cevado que sendo-saudável ele recebeu-de-volta');
INSERT INTO verses VALUES (25678, 42, 15, 28, 'Irou-se porém e não queria entrar o porém Pai dele saindo suplicava ele');
INSERT INTO verses VALUES (25679, 42, 15, 29, 'o porém respondendo disse o pai Eis tantas-coisas anos sirvo a-ti e nunca mandamento teu passaram e mim nunca deste Cabrito para que com o amigos meu alegre-me');
INSERT INTO verses VALUES (25680, 42, 15, 30, 'quando porém o filho teu este o tendo-devorado teu o vida com fornicadores veio Sacrificaste a ele o cevado novilho');
INSERT INTO verses VALUES (25681, 42, 15, 31, 'o porém disse a ele Filho tu sempre com mim és e todas-as-coisas o minhas-coisas tuas é');
INSERT INTO verses VALUES (25682, 42, 15, 32, 'alegrar-se porém e alegrar-se é necessário que o irmão teu este morto era e Viveu e tendo-se-perdido e foi-encontrada');
INSERT INTO chapters VALUES (989, 42, 16, 31);
INSERT INTO verses VALUES (25683, 42, 16, 1, 'Dizia porém e junto-a o discípulos Homem alguém era rico o qual tinha administrador e este foi-acusado a ele como dispersando o posses dele');
INSERT INTO verses VALUES (25684, 42, 16, 2, 'e chamando ele disse a ele quê isto ouço acerca-de teu devolve o palavra o administração teu não pois podes ainda administrar');
INSERT INTO verses VALUES (25685, 42, 16, 3, 'disse porém em si-mesmo o administrador quê farei que o senhor meu é-tirado o administração de mim cavar não sou-capaz mendigar envergonho-me');
INSERT INTO verses VALUES (25686, 42, 16, 4, 'conheci quê farei para que quando seja-removido de o administração recebam me para o casas deles-mesmos');
INSERT INTO verses VALUES (25687, 42, 16, 5, 'e tendo-chamado um cada-um o de-devedores o do-Kyrios si-mesmo dizia o primeiro Quanto deves o ao-Kyrios meu');
INSERT INTO verses VALUES (25688, 42, 16, 6, 'o porém disse Cem sarças azeite o porém disse a ele Recebe teu o letras e sentando-se rapidamente escreve cinquenta');
INSERT INTO verses VALUES (25689, 42, 16, 7, 'depois a-outro disse tu porém quanto deves o porém disse Cem coros trigo diz a ele Recebe teu o letras e escreve oitenta');
INSERT INTO verses VALUES (25690, 42, 16, 8, 'e Elogiou o kyrios o administrador o da-injustiça que prudentemente fez que o filhos o eternidade deste mais-prudentes em-favor-de o filhos o luz para o geração o deles-mesmos são');
INSERT INTO verses VALUES (25691, 42, 16, 9, 'e eu a-vós digo si-mesmos fazei amigos de o mamom o da-injustiça para que quando desfaleça recebam vos para o eternos tendas');
INSERT INTO verses VALUES (25692, 42, 16, 10, 'o fiel em mínimo e em muito fiel é e o em mínimo injusto e em muito injusto é');
INSERT INTO verses VALUES (25693, 42, 16, 11, 'se portanto em o injusto mamom fiéis não tornastes-vos o verdadeiro quem a-vós crerá');
INSERT INTO verses VALUES (25694, 42, 16, 12, 'e se em o estranho fiéis não tornastes-vos o nosso quem dará a-vós');
INSERT INTO verses VALUES (25695, 42, 16, 13, 'Ninguém servo-doméstico pode dois senhores servir ou pois o um odiará e o outro amará ou de-um apegar-se-á e o de-outro desprezará não podeis a-Theos servir e mamom');
INSERT INTO verses VALUES (25696, 42, 16, 14, 'Ouviam porém estas-coisas todas-as-coisas o fariseus amantes-de-dinheiro existindo e escarneciam ele');
INSERT INTO verses VALUES (25697, 42, 16, 15, 'e disse a-eles vós sois o justificando si-mesmos diante-de o dos-homens o porém Theos conhece o do-coração vosso que o em aos-homens alto abominação diante-de o de-Theos');
INSERT INTO verses VALUES (25698, 42, 16, 16, 'o lei e o profetas até João de então o reino o de-Theos anuncia-boa-nova e todo para ela é-tomado-à-força');
INSERT INTO verses VALUES (25699, 42, 16, 17, 'mais-fácil e/mas é o céu e o terra passar ou o da-lei uma til cair');
INSERT INTO verses VALUES (25700, 42, 16, 18, 'todo o soltando o mulher dele e casando outra comete-adultério e o tendo-sido-solta de homem casando comete-adultério');
INSERT INTO verses VALUES (25701, 42, 16, 19, 'homem e/mas alguém era rico e vestia-se púrpura e linho-fino alegrando-se segundo dia esplendidamente');
INSERT INTO verses VALUES (25702, 42, 16, 20, 'pobre e/mas alguém em-nome Lázaro havia-sido-lançado junto-a o portão dele tendo-sido-ulcerado');
INSERT INTO verses VALUES (25703, 42, 16, 21, 'e desejando ser-saciado de o caindo de o mesa o rico mas e o cães vindos lambiam o úlceras dele');
INSERT INTO verses VALUES (25704, 42, 16, 22, 'aconteceu porém morrer o pobre e ser-levado ele sob o anjo para o seio Abraão morreu porém e o rico e foi-sepultado');
INSERT INTO verses VALUES (25705, 42, 16, 23, 'e em o Hades levantando o olhos dele sendo em tormentos vê Abraão de de-longe e Lázaro em o seios dele');
INSERT INTO verses VALUES (25706, 42, 16, 24, 'e ele chamando disse Pai Abraão tem-misericórdia me e envia Lázaro para que mergulhe o extremidade o dedo dele água e refresque o língua meu que sofro-dor em o chama nesta');
INSERT INTO verses VALUES (25707, 42, 16, 25, 'disse porém Abraão Filho lembra-te que recebeste-de-volta o boas-coisas teu em o vida teu e Lázaro semelhantemente o males agora porém aqui é-consolado tu porém sofres-dor');
INSERT INTO verses VALUES (25708, 42, 16, 26, 'e em todos nestes entre nosso e vosso abismo grande Tem-sido-firmado para-que o querendo atravessar daqui junto-a vos não possam nem dali junto-a nos atravessem');
INSERT INTO verses VALUES (25709, 42, 16, 27, 'disse e/mas Peço te portanto pai para que envies ele para o casa o pai meu');
INSERT INTO verses VALUES (25710, 42, 16, 28, 'tenho pois cinco irmãos para-que testifique-solenemente a-eles para que não e eles-mesmos venham para o lugar este o tormento');
INSERT INTO verses VALUES (25711, 42, 16, 29, 'diz porém Abraão Têm Moisés e o profetas ouçam deles');
INSERT INTO verses VALUES (25712, 42, 16, 30, 'o porém disse Não pai Abraão mas se alguém de mortos vá junto-a eles arrepender-se-ão');
INSERT INTO verses VALUES (25713, 42, 16, 31, 'disse porém a ele se de-Moisés e o profetas não ouvem nem se alguém de mortos levante-se serão-persuadidos');
INSERT INTO chapters VALUES (990, 42, 17, 36);
INSERT INTO verses VALUES (25714, 42, 17, 1, 'disse porém junto-a o discípulos dele Impossível é o o escândalos não vir ai porém através-de o qual vem');
INSERT INTO verses VALUES (25715, 42, 17, 2, 'é-proveitoso a ele se pedra de-moinho está-posto-ao-redor acerca-de o pescoço dele e Tem-sido-lançado para o mar ou para que escandalize o pequenos destes um');
INSERT INTO verses VALUES (25716, 42, 17, 3, 'guardai-vos si-mesmos se peque o irmão teu repreende a ele e se arrependa-se deixa a ele');
INSERT INTO verses VALUES (25717, 42, 17, 4, 'e se sete-vezes o do-dia peque para te e sete-vezes converta junto-a te dizendo Arrependo-me deixarás a ele');
INSERT INTO verses VALUES (25718, 42, 17, 5, 'e disseram o apóstolos o ao-Kyrios Acrescenta a-nós fé');
INSERT INTO verses VALUES (25719, 42, 17, 6, 'disse porém o Kyrios se tendes fé como grão mostarda dizíeis partícula-condicional o sicômoro nesta Sê-desarraigada e sê-plantada em o mar e obedeceu partícula-condicional a-vós');
INSERT INTO verses VALUES (25720, 42, 17, 7, 'Quem porém de vosso servo tendo arando ou apascentando o qual tendo-entrado de o campo dirá a ele Imediatamente tendo-passado reclina-te');
INSERT INTO verses VALUES (25721, 42, 17, 8, 'mas não dirá a ele Prepara quê cearei e tendo-se-cingido serve a-mim até coma e beba e com estas-coisas comerás e beberás tu');
INSERT INTO verses VALUES (25722, 42, 17, 9, 'não tem graça o servo que fez o tendo-sido-ordenados');
INSERT INTO verses VALUES (25723, 42, 17, 10, 'assim e vós quando façais todas-as-coisas o tendo-sido-ordenados a-vós dizeis que Servos inúteis somos o qual devemos fazer temos-feito');
INSERT INTO verses VALUES (25724, 42, 17, 11, 'e aconteceu em o ir para Jerusalém e ele atravessava através-de meio Samaria e Galileia');
INSERT INTO verses VALUES (25725, 42, 17, 12, 'e entrando dele um alguém aldeia encontraram dez leprosos homens o qual colocaram-de-pé de-longe');
INSERT INTO verses VALUES (25726, 42, 17, 13, 'e eles-mesmos levantaram voz dizendo Iesous Mestre tem-misericórdia nos');
INSERT INTO verses VALUES (25727, 42, 17, 14, 'e vendo disse a-eles Tendo-ido mostrai si-mesmos o sacerdotes e aconteceu em o ir eles foram-purificados');
INSERT INTO verses VALUES (25728, 42, 17, 15, 'um porém de deles vendo que foi-curado retornou com voz grande glorificando o Theos');
INSERT INTO verses VALUES (25729, 42, 17, 16, 'e caiu sobre rosto de-junto-de o pés dele dando-graças a ele e ele era Samaritano');
INSERT INTO verses VALUES (25730, 42, 17, 17, 'respondendo porém o Iesous disse não o dez foram-purificados o porém nove onde');
INSERT INTO verses VALUES (25731, 42, 17, 18, 'não foram-encontrados tendo-retornado dar glória o a-Theos se não o de-outra-raça este');
INSERT INTO verses VALUES (25732, 42, 17, 19, 'e disse a ele Levantando-se vai o fé teu tem-salvo te');
INSERT INTO verses VALUES (25733, 42, 17, 20, 'Tendo-sido-perguntado porém sob o fariseus quando vem o reino o de-Theos respondeu a-eles e disse não vem o reino o de-Theos com de-observação');
INSERT INTO verses VALUES (25734, 42, 17, 21, 'nem dirão Eis aqui ou Ali eis pois o reino o de-Theos dentro vosso é');
INSERT INTO verses VALUES (25735, 42, 17, 22, 'disse porém junto-a o discípulos Virão dias quando desejareis uma o dos-dias o do-Filho o do-homem ver e não vereis');
INSERT INTO verses VALUES (25736, 42, 17, 23, 'e dirão a-vós Eis ali Eis aqui não partais nem persigais');
INSERT INTO verses VALUES (25737, 42, 17, 24, 'assim-como pois o relâmpago relampejando de o sob o céu para o sob céu brilha assim será o Filho o do-homem em o dia dele');
INSERT INTO verses VALUES (25738, 42, 17, 25, 'primeiro porém é necessário ele muitas-coisas sofrer e ser-rejeitado de o geração desta');
INSERT INTO verses VALUES (25739, 42, 17, 26, 'e assim-como aconteceu em o dias Noé assim será e em o dias o do-Filho o do-homem');
INSERT INTO verses VALUES (25740, 42, 17, 27, 'comiam bebiam casavam eram-dados-em-casamento até o qual do-dia entrou Noé para o arca e veio o dilúvio e perdeu todos');
INSERT INTO verses VALUES (25741, 42, 17, 28, 'semelhantemente assim-como aconteceu em o dias Ló comiam bebiam compravam Vendiam Plantavam Edificavam');
INSERT INTO verses VALUES (25742, 42, 17, 29, 'o qual porém dia saiu Ló de Sodoma choveu fogo e enxofre de do-céu e perdeu todos');
INSERT INTO verses VALUES (25743, 42, 17, 30, 'segundo o eles será o qual dia o Filho o do-homem é-revelado');
INSERT INTO verses VALUES (25744, 42, 17, 31, 'em naquela o dia o qual será sobre o telhado e o vasos dele em o casa não desça levantar elas e o em campo semelhantemente não volte para o atrás');
INSERT INTO verses VALUES (25745, 42, 17, 32, 'lembrai-vos o mulher Ló');
INSERT INTO verses VALUES (25746, 42, 17, 33, 'o qual se busque o alma dele adquirir destruirá ela e o qual partícula-condicional destruirá preservará-vivos ela');
INSERT INTO verses VALUES (25747, 42, 17, 34, 'digo a-vós nesta o à-noite serão dois sobre cama uma o um será-tomado e o outro será-perdoado');
INSERT INTO verses VALUES (25748, 42, 17, 35, 'serão dois moendo sobre o isso o uma será-tomado o porém outra será-perdoado');
INSERT INTO verses VALUES (25749, 42, 17, 37, 'e respondendo dizem a ele Onde Kyrie o porém disse a-eles onde o corpo ali e o águias Serão-reunidos');
INSERT INTO chapters VALUES (991, 42, 18, 43);
INSERT INTO verses VALUES (25750, 42, 18, 1, 'Dizia porém parábola a-eles junto-a o é necessário sempre orar eles e não desanimar');
INSERT INTO verses VALUES (25751, 42, 18, 2, 'dizendo Juiz alguém era em a-alguém na-cidade o Theos não temendo e homem não envergonhando-se');
INSERT INTO verses VALUES (25752, 42, 18, 3, 'viúva porém era em o na-cidade naquela e vinha junto-a ele dizendo Vinga me de o adversário meu');
INSERT INTO verses VALUES (25753, 42, 18, 4, 'e não queria sobre tempo com estas-coisas porém disse em si-mesmo se e o Theos não temo nem homem envergonho-me');
INSERT INTO verses VALUES (25754, 42, 18, 5, 'por-meio-de pois o oferecer a-mim labor o viúva esta vingarei ela para que não para fim vindo Golpeie-sob-o-olho me');
INSERT INTO verses VALUES (25755, 42, 18, 6, 'disse porém o Kyrios Ouvi quê o juiz o da-injustiça diz');
INSERT INTO verses VALUES (25756, 42, 18, 7, 'o porém Theos não não faça o vingança o eleitos dele o clamando a ele do-dia e noite e é-longânimo sobre a-eles');
INSERT INTO verses VALUES (25757, 42, 18, 8, 'digo a-vós que fará o vingança deles em rapidez porém o Filho o do-homem vindo acaso encontrará o fé sobre o da-terra');
INSERT INTO verses VALUES (25758, 42, 18, 9, 'disse porém e para alguns o tendo-confiado sobre si-mesmos que são justos e desprezando o restantes o parábola esta');
INSERT INTO verses VALUES (25759, 42, 18, 10, 'Homens dois subiram para o templo orar o um fariseu e o outro cobrador-de-impostos');
INSERT INTO verses VALUES (25760, 42, 18, 11, 'o fariseu pondo-se-de-pé estas-coisas junto-a si-mesmo orava o Theos dou-graças a-ti que não sou assim-como o restantes o dos-homens rapaces injustos adúlteros ou e como este o cobrador-de-impostos');
INSERT INTO verses VALUES (25761, 42, 18, 12, 'jejuo duas-vezes o do-sábado dou-o-dízimo todas-as-coisas quanto adquiro');
INSERT INTO verses VALUES (25762, 42, 18, 13, 'o porém cobrador-de-impostos de-longe estando-de-pé não queria nem o olhos Levantar para o céu mas Batia o peito dele dizendo o Theos Sê-propício a-mim o pecador');
INSERT INTO verses VALUES (25763, 42, 18, 14, 'digo a-vós desceu este tendo-sido-justificado para o casa dele de-junto-de aquele que todo o exaltando si-mesmo será-humilhado o porém humildes si-mesmo será-exaltado');
INSERT INTO verses VALUES (25764, 42, 18, 15, 'Traziam porém a ele e o crianças-de-peito para que deles toque vendo porém o discípulos repreendiam a-eles');
INSERT INTO verses VALUES (25765, 42, 18, 16, 'o porém Iesous chamou-a-si eles dizendo Deixai o crianças vir para me e não impedis elas o pois de-tais é o reino o de-Theos');
INSERT INTO verses VALUES (25766, 42, 18, 17, 'amém digo a-vós o qual partícula-condicional não receba o reino o de-Theos como criança não não entre para ela');
INSERT INTO verses VALUES (25767, 42, 18, 18, 'e perguntou alguém ele governante dizendo Mestre bom quê tendo-feito vida eterno herdarei');
INSERT INTO verses VALUES (25768, 42, 18, 19, 'disse porém a ele o Iesous quê me dizes bom ninguém bom se não um o Theos');
INSERT INTO verses VALUES (25769, 42, 18, 20, 'o mandamentos sei não adulteres não assassines não furtes não testemunhes-falsamente Honra o Pai teu e o mãe');
INSERT INTO verses VALUES (25770, 42, 18, 21, 'o porém disse estas-coisas todas-as-coisas guardei de juventude');
INSERT INTO verses VALUES (25771, 42, 18, 22, 'ouvindo porém o Iesous disse a ele Ainda um a-ti falta todas-as-coisas quanto tens vende e distribui pobres e terás tesouro em o nos-céus e vem segue a-mim');
INSERT INTO verses VALUES (25772, 42, 18, 23, 'o porém ouvindo estas-coisas profundamente-triste aconteceu era pois rico grandemente');
INSERT INTO verses VALUES (25773, 42, 18, 24, 'vendo porém ele o Iesous disse como dificilmente o o posses tendo para o reino o de-Theos adentram');
INSERT INTO verses VALUES (25774, 42, 18, 25, 'mais-fácil pois é camelo através-de orifício agulha entrar ou rico para o reino o de-Theos entrar');
INSERT INTO verses VALUES (25775, 42, 18, 26, 'disseram porém o ouvindo e quem pode ser-salvo');
INSERT INTO verses VALUES (25776, 42, 18, 27, 'o porém disse o impossíveis de-junto-de aos-homens possíveis de-junto-de o a-Theos é');
INSERT INTO verses VALUES (25777, 42, 18, 28, 'disse porém o Pedro Eis nós deixando o próprias seguimos a-ti');
INSERT INTO verses VALUES (25778, 42, 18, 29, 'o porém disse a-eles Amém digo a-vós que ninguém é o qual deixou casa ou mulher ou irmãos ou pais ou filhos por-causa-de o do-reino o de-Theos');
INSERT INTO verses VALUES (25779, 42, 18, 30, 'o qual não não receba muitas-vezes-mais em o tempo neste e em o era o vindo vida eterno');
INSERT INTO verses VALUES (25780, 42, 18, 31, 'Tendo-tomado-consigo porém o doze disse junto-a eles Eis subimos para Jerusalém e será-completado todas-as-coisas o escritas através-de o profetas o Filho o do-homem');
INSERT INTO verses VALUES (25781, 42, 18, 32, 'será-entregue pois o nações e será-escarnecido e será-ultrajado e será-cuspido');
INSERT INTO verses VALUES (25782, 42, 18, 33, 'e tendo-açoitado matarão ele e o dia o no-terceiro ressuscitará');
INSERT INTO verses VALUES (25783, 42, 18, 34, 'e eles-mesmos nada destes compreenderam e era o palavra isto tendo-sido-escondido de deles e não conheciam o sendo-ditas');
INSERT INTO verses VALUES (25784, 42, 18, 35, 'aconteceu porém em o aproximar-se ele para Jericó cego alguém sentava-se de-junto-de o caminho mendigando');
INSERT INTO verses VALUES (25785, 42, 18, 36, 'ouvindo porém da-multidão passando-através inquiria quê seria isto');
INSERT INTO verses VALUES (25786, 42, 18, 37, 'anunciaram porém a ele que Iesous o nazareno passa');
INSERT INTO verses VALUES (25787, 42, 18, 38, 'e clamou dizendo Iesous filho Davi tem-misericórdia me');
INSERT INTO verses VALUES (25788, 42, 18, 39, 'e o precedendo repreendiam a ele para que cale-se ele porém muito mais gritava Filho Davi tem-misericórdia me');
INSERT INTO verses VALUES (25789, 42, 18, 40, 'pondo-se-de-pé porém o Iesous ordenou ele ser-levado junto-a ele tendo-se-aproximado porém dele perguntou ele');
INSERT INTO verses VALUES (25790, 42, 18, 41, 'quê a-ti queres farei o porém disse Kyrie para que recuperarei-a-vista');
INSERT INTO verses VALUES (25791, 42, 18, 42, 'e o Iesous disse a ele Olha-para-cima o fé teu tem-salvo te');
INSERT INTO verses VALUES (25792, 42, 18, 43, 'e imediatamente olhou-para-cima e seguia a ele glorificando o Theos e todo o povo vendo deu louvor o a-Theos');
INSERT INTO chapters VALUES (992, 42, 19, 48);
INSERT INTO verses VALUES (25793, 42, 19, 1, 'e entrando atravessava o Jericó');
INSERT INTO verses VALUES (25794, 42, 19, 2, 'e eis homem em-nome chamado Zaqueu e ele era chefe-dos-cobradores-de-impostos e ele rico');
INSERT INTO verses VALUES (25795, 42, 19, 3, 'e buscava ver o Iesous quem é e não podia de o da-multidão que o estatura pequeno era');
INSERT INTO verses VALUES (25796, 42, 19, 4, 'e tendo-corrido-adiante para o diante-de subiu sobre sicômoro para que veja ele que daquela estava-prestes-a atravessar');
INSERT INTO verses VALUES (25797, 42, 19, 5, 'e como veio sobre o lugar olhando-para-cima o Iesous disse junto-a ele Zaqueu tendo-se-apressado desce hoje pois em o na-casa teu é necessário me permanecer');
INSERT INTO verses VALUES (25798, 42, 19, 6, 'e tendo-se-apressado desceu e acolheu ele alegrando-se');
INSERT INTO verses VALUES (25799, 42, 19, 7, 'e vendo todos murmuravam dizendo que de-junto-de pecador homem entrou destruir');
INSERT INTO verses VALUES (25800, 42, 19, 8, 'pondo-se-de-pé porém Zaqueu disse junto-a o Kyrion Eis o metade meu o posses Kyrie o pobres dou e se de-alguém algo Extorqui devolvo quádruplo');
INSERT INTO verses VALUES (25801, 42, 19, 9, 'disse porém junto-a ele o Iesous que Hoje salvação o na-casa neste aconteceu assim-como e ele Filho Abraão é');
INSERT INTO verses VALUES (25802, 42, 19, 10, 'veio pois o Filho o do-homem buscar e salvar o tendo-se-perdido');
INSERT INTO verses VALUES (25803, 42, 19, 11, 'Ouvindo porém deles estas-coisas tendo-acrescentado disse parábola através-de o perto ser Jerusalém ele e parecer eles que imediatamente está-a-ponto-de o reino o de-Theos aparecer');
INSERT INTO verses VALUES (25804, 42, 19, 12, 'disse portanto Homem alguém nobre foi para região longe receber si-mesmo reino e retornar');
INSERT INTO verses VALUES (25805, 42, 19, 13, 'chamando porém dez servos si-mesmo deu a-eles dez minas e disse junto-a eles Negociai em o qual venho');
INSERT INTO verses VALUES (25806, 42, 19, 14, 'o porém cidadãos dele odiavam ele e enviaram embaixada atrás dele dizendo não queremos este reinar sobre nos');
INSERT INTO verses VALUES (25807, 42, 19, 15, 'e aconteceu em o retornar ele tendo-tomado o reino e disse ser-chamado a ele o servos estes o qual tinha-dado o prata para que conheça quem quê negociou');
INSERT INTO verses VALUES (25808, 42, 19, 16, 'apresentou-se porém o primeiro dizendo Kyrie o mina teu dez ganhou-além minas');
INSERT INTO verses VALUES (25809, 42, 19, 17, 'e disse a ele Bem bom servo que em mínimo fiel tornaste-te sê autoridade tendo em-cima dez cidades');
INSERT INTO verses VALUES (25810, 42, 19, 18, 'e veio o segundo dizendo o mina teu kyrie fez cinco minas');
INSERT INTO verses VALUES (25811, 42, 19, 19, 'disse porém e neste e tu em-cima torna-te cinco cidades');
INSERT INTO verses VALUES (25812, 42, 19, 20, 'e o outro veio dizendo Kyrie eis o mina teu o qual tinham tendo-sido-reservada em lenço');
INSERT INTO verses VALUES (25813, 42, 19, 21, 'Eu-temia pois te que homem severo és levantas o qual não colocaste e ceifas o qual não semeaste');
INSERT INTO verses VALUES (25814, 42, 19, 22, 'diz a ele de o boca teu julgo te mau servo sei que eu homem severo sou levantando o qual não pus e ceifando o qual não semeei');
INSERT INTO verses VALUES (25815, 42, 19, 23, 'e através-de quê não deste meu o prata sobre mesa e-eu vindo com juro partícula-condicional ele Pratiquei');
INSERT INTO verses VALUES (25816, 42, 19, 24, 'e o estejam-de-pé disse Levantai de dele o mina e dai o o dez minas tendo');
INSERT INTO verses VALUES (25817, 42, 19, 25, 'e disseram a ele Kyrie tem dez minas');
INSERT INTO verses VALUES (25818, 42, 19, 26, 'digo a-vós que todo o tendo será-dado de porém o não tendo e o qual tem será-tirado');
INSERT INTO verses VALUES (25819, 42, 19, 27, 'porém o inimigos meu estes o não tendo-querido me reinar sobre eles conduzi aqui e massacrai eles diante-de meu');
INSERT INTO verses VALUES (25820, 42, 19, 28, 'e dizendo estas-coisas ia diante-de subindo para Jerusalém');
INSERT INTO verses VALUES (25821, 42, 19, 29, 'e aconteceu como aproximou-se para Betfagé e Betânia junto-a o monte o chamado Oliveiras enviou dois o discípulos');
INSERT INTO verses VALUES (25822, 42, 19, 30, 'dizendo ide para o defronte-de aldeia em o qual entrando encontrareis jumentinho amarrado sobre o qual ninguém jamais dos-homens sentou-se e tendo-desatado ele conduzi');
INSERT INTO verses VALUES (25823, 42, 19, 31, 'e se alguém vos pede através-de quê desatai assim direis que o Kyrios dele necessidade tem');
INSERT INTO verses VALUES (25824, 42, 19, 32, 'tendo-ido-embora porém o tendo-sido-enviados encontraram assim-como disse a-eles');
INSERT INTO verses VALUES (25825, 42, 19, 33, 'desatando porém deles o jumentinho disseram o senhores dele junto-a eles quê desatai o jumentinho');
INSERT INTO verses VALUES (25826, 42, 19, 34, 'o porém disseram que o Kyrios dele necessidade tem');
INSERT INTO verses VALUES (25827, 42, 19, 35, 'e levaram ele junto-a o Iesous e tendo-lançado-sobre deles o vestes sobre o jumentinho fizeram-montar o Iesous');
INSERT INTO verses VALUES (25828, 42, 19, 36, 'indo porém dele Estendiam o vestes deles-mesmos em o caminho');
INSERT INTO verses VALUES (25829, 42, 19, 37, 'aproximando-se porém dele já junto-a o descida o do-monte o Oliveiras começaram todo o multidão o discípulos alegrando-se louvar o Theos com-voz grande acerca-de todas o qual vi poderes');
INSERT INTO verses VALUES (25830, 42, 19, 38, 'dizendo Bendito o o-que-vem o Rei em em-nome do-Kyrios em no-céu paz e glória em alturas');
INSERT INTO verses VALUES (25831, 42, 19, 39, 'e alguns o fariseus de o da-multidão disseram junto-a ele Mestre repreende o discípulos teu');
INSERT INTO verses VALUES (25832, 42, 19, 40, 'e respondendo disse digo a-vós se estes calarão o pedras clamarão');
INSERT INTO verses VALUES (25833, 42, 19, 41, 'e como aproximou-se vendo o cidade chorou sobre ela');
INSERT INTO verses VALUES (25834, 42, 19, 42, 'dizendo que se conheceste em o dia nesta e tu o junto-a paz agora porém escondeu-se de olhos teu');
INSERT INTO verses VALUES (25835, 42, 19, 43, 'que virão dias sobre te e cercarão-com-trincheiras o Inimigos teu estacada a-ti e cercarão te e conterão te de-todo-lado');
INSERT INTO verses VALUES (25836, 42, 19, 44, 'e lançarão-ao-chão te e o filhos teu em a-ti e não deixarão pedra sobre pedra em a-ti em-vez-de o qual não conheceste o tempo o supervisão teu');
INSERT INTO verses VALUES (25837, 42, 19, 45, 'e entrando para o templo começou expulsar o vendendo');
INSERT INTO verses VALUES (25838, 42, 19, 46, 'dizendo a-eles Tem-sido-escrito e será o casa meu casa oração vós porém ele fizestes caverna ladrões');
INSERT INTO verses VALUES (25839, 42, 19, 47, 'e era ensinando o segundo dia em o templo o porém sumos-sacerdotes e o escribas buscavam ele destruir e o primeiro o povo');
INSERT INTO verses VALUES (25840, 42, 19, 48, 'e não encontravam o quê façam o povo pois todo pendia dele ouvindo');
INSERT INTO chapters VALUES (993, 42, 20, 47);
INSERT INTO verses VALUES (25841, 42, 20, 1, 'e aconteceu em uma o dos-dias ensinando dele o povo em o templo e anunciando-boas-novas aproximaram-se o sumos-sacerdotes e o escribas com o presbíteros');
INSERT INTO verses VALUES (25842, 42, 20, 2, 'e disseram dizendo junto-a ele Dize a-nós em qual em-autoridade estas-coisas fazes ou quem é o tendo-dado a-ti o autoridade esta');
INSERT INTO verses VALUES (25843, 42, 20, 3, 'respondendo porém disse junto-a eles Perguntarei vos e-eu palavra e dizei a-mim');
INSERT INTO verses VALUES (25844, 42, 20, 4, 'o batismo João de do-céu era ou de dos-homens');
INSERT INTO verses VALUES (25845, 42, 20, 5, 'o porém raciocinaram junto-a si-mesmos dizendo que se digamos de do-céu dirá através-de quê não crestes a ele');
INSERT INTO verses VALUES (25846, 42, 20, 6, 'se porém digamos de dos-homens o povo todo apedrejará nos tendo-sido-persuadido pois é João profeta ser');
INSERT INTO verses VALUES (25847, 42, 20, 7, 'e responderam não sei de-onde');
INSERT INTO verses VALUES (25848, 42, 20, 8, 'e o Iesous disse a-eles nem eu digo a-vós em qual em-autoridade estas-coisas faço');
INSERT INTO verses VALUES (25849, 42, 20, 9, 'Começou porém junto-a o povo dizer o parábola esta homem plantou vinha e arrendou ele lavradores e viajou tempos Suficientes');
INSERT INTO verses VALUES (25850, 42, 20, 10, 'e tempo enviou junto-a o lavradores servo para que de o fruto o vinha darão a ele o porém lavradores enviaram-embora ele tendo-espancado vazio');
INSERT INTO verses VALUES (25851, 42, 20, 11, 'e acrescentou outro enviar servo o porém e-aquele tendo-espancado e tendo-desonrado enviaram-embora vazio');
INSERT INTO verses VALUES (25852, 42, 20, 12, 'e acrescentou terceira-vez enviar o porém e este tendo-ferido expulsaram');
INSERT INTO verses VALUES (25853, 42, 20, 13, 'disse porém o kyrios o vinha quê farei enviarei o filho meu o amado Talvez este envergonhar-se-ão');
INSERT INTO verses VALUES (25854, 42, 20, 14, 'vendo porém ele o lavradores debatiam junto-a uns-aos-outros dizendo Este é o herdeiro matemos ele para que nosso aconteça o herança');
INSERT INTO verses VALUES (25855, 42, 20, 15, 'e tendo-lançado-fora ele fora o vinha mataram quê portanto fará a-eles o kyrios o vinha');
INSERT INTO verses VALUES (25856, 42, 20, 16, 'virá e destruirá o lavradores estes e dará o vinha a-outros ouvindo porém disseram não seja-assim');
INSERT INTO verses VALUES (25857, 42, 20, 17, 'o porém olhando-fixamente a-eles disse quê portanto é o escrito isto Pedra o qual rejeitaram o edificantes este aconteceu para cabeça esquina');
INSERT INTO verses VALUES (25858, 42, 20, 18, 'todo o caindo sobre aquele o pedra será-esmagado sobre o qual e/mas partícula-condicional caia esmagará ele');
INSERT INTO verses VALUES (25859, 42, 20, 19, 'e buscaram o escribas e o sumos-sacerdotes lançar-sobre sobre ele o mãos em a-ela o hora e temeram o povo conheceram pois que junto-a eles disse o parábola esta');
INSERT INTO verses VALUES (25860, 42, 20, 20, 'e tendo-observado enviaram espiões Fingindo si-mesmos justos ser para que apanhem dele da-palavra de-modo-que entregar ele o princípio e o em-autoridade o governador');
INSERT INTO verses VALUES (25861, 42, 20, 21, 'e perguntaram ele dizendo Mestre sei que retamente dizes e ensinas e não recebes rosto mas sobre da-verdade o caminho o de-Theos ensinas');
INSERT INTO verses VALUES (25862, 42, 20, 22, 'é-lícito nos César tributo dar ou não');
INSERT INTO verses VALUES (25863, 42, 20, 23, 'tendo-considerado porém deles o astúcia disse junto-a eles');
INSERT INTO verses VALUES (25864, 42, 20, 24, 'Mostrai a-mim denário de-quem tem imagem e inscrição o porém disseram de-César');
INSERT INTO verses VALUES (25865, 42, 20, 25, 'o porém disse junto-a eles Portanto devolvei o de-César César e o o de-Theos o a-Theos');
INSERT INTO verses VALUES (25866, 42, 20, 26, 'e não tiveram-força tomar-de dele palavra diante-de o povo e tendo-se-maravilhado sobre o resposta dele silenciaram');
INSERT INTO verses VALUES (25867, 42, 20, 27, 'Tendo-se-aproximado e/mas alguns o saduceus o contradizendo ressurreição não ser perguntaram ele');
INSERT INTO verses VALUES (25868, 42, 20, 28, 'dizendo Mestre Moisés escreveu a-nós se de-alguém irmão morra tendo mulher e este sem-filhos seja para que receba o irmão dele o mulher e levante semente o ao-irmão dele');
INSERT INTO verses VALUES (25869, 42, 20, 29, 'sete portanto irmãos eram e o primeiro tomando mulher morreu sem-filhos');
INSERT INTO verses VALUES (25870, 42, 20, 30, 'e o segundo');
INSERT INTO verses VALUES (25871, 42, 20, 31, 'e o terceiro recebeu ela da-mesma-forma porém e o sete não deixaram filhos e morreram');
INSERT INTO verses VALUES (25872, 42, 20, 32, 'depois e o mulher morreu');
INSERT INTO verses VALUES (25873, 42, 20, 33, 'o mulher portanto em o ressurreição de-quem deles torna-se mulher o pois sete tiveram ela mulher');
INSERT INTO verses VALUES (25874, 42, 20, 34, 'e disse a-eles o Iesous o filhos o eternidade deste casam e são-dados-em-casamento');
INSERT INTO verses VALUES (25875, 42, 20, 35, 'o porém tendo-sido-considerados-dignos o eternidade daquele obter e o da-ressurreição o de mortos nem casam nem são-dados-em-casamento');
INSERT INTO verses VALUES (25876, 42, 20, 36, 'nem pois morrer ainda podem iguais-a-anjos pois são e filhos são de-Theos o da-ressurreição filhos sendo');
INSERT INTO verses VALUES (25877, 42, 20, 37, 'que porém são-levantados o mortos e Moisés revelou sobre o Sarça como diz Kyrion o Theos Abraão e Theos Isaque e Theos Jacó');
INSERT INTO verses VALUES (25878, 42, 20, 38, 'Theos porém não é mortos mas viventes todos pois a ele vivam');
INSERT INTO verses VALUES (25879, 42, 20, 39, 'respondendo e/mas alguns o dos-escribas disseram Mestre bem disseste');
INSERT INTO verses VALUES (25880, 42, 20, 40, 'não-mais pois Ousavam perguntar ele nada');
INSERT INTO verses VALUES (25881, 42, 20, 41, 'disse porém junto-a eles como dizem o Christos ser Davi filho');
INSERT INTO verses VALUES (25882, 42, 20, 42, 'ele pois Davi diz em livro salmos disse Kyrios o ao-Kyrios meu Senta-te de direita meu');
INSERT INTO verses VALUES (25883, 42, 20, 43, 'até partícula-condicional ponha o inimigos teu estrado o pés teu');
INSERT INTO verses VALUES (25884, 42, 20, 44, 'Davi portanto ele Kyrion chama e como dele filho é');
INSERT INTO verses VALUES (25885, 42, 20, 45, 'Ouvindo porém de-todo o povo disse o discípulos');
INSERT INTO verses VALUES (25886, 42, 20, 46, 'Guardai-vos de o dos-escribas o dos-que-querem andar em vestes-longas e amando saudações em o praças e primeiros-assentos em o nas-sinagogas e primeiros-lugares em o banquetes');
INSERT INTO verses VALUES (25887, 42, 20, 47, 'o qual devoram o da-casa o viúvas e pretexto longa oram estes receberão abundantemente juízo');
INSERT INTO chapters VALUES (994, 42, 21, 38);
INSERT INTO verses VALUES (25888, 42, 21, 1, 'Tendo-olhado-para-cima porém viu o lançando para o tesouro o presentes deles ricos');
INSERT INTO verses VALUES (25889, 42, 21, 2, 'viu e/mas alguém viúva pobre lançando ali lepta dois');
INSERT INTO verses VALUES (25890, 42, 21, 3, 'e disse Verdadeiramente digo a-vós que o viúva esta o pobre mais todos lançou');
INSERT INTO verses VALUES (25891, 42, 21, 4, 'todos pois estes de o abundando a-eles lançaram para o presentes esta porém de o Falta dela todas-as-coisas o vida o qual tinha lançou');
INSERT INTO verses VALUES (25892, 42, 21, 5, 'E alguns dizendo acerca-de o do-templo que pedras boas e ofertas-votivas tem-sido-adornado disse');
INSERT INTO verses VALUES (25893, 42, 21, 6, 'estas-coisas o qual contemplais virão dias em o qual não será-perdoado pedra sobre pedra o qual não será-destruído');
INSERT INTO verses VALUES (25894, 42, 21, 7, 'perguntaram porém ele dizendo Mestre quando portanto estas-coisas será e quê o sinal quando esteja-a-ponto-de estas-coisas tornar-se');
INSERT INTO verses VALUES (25895, 42, 21, 8, 'o porém disse Vede não sejais-enganados muitos pois virão sobre o no-nome meu dizendo Eu sou e o tempo-oportuno aproximou-se não ide atrás deles');
INSERT INTO verses VALUES (25896, 42, 21, 9, 'quando porém ouçais guerras e desordens não sejais-aterrorizados é necessário pois estas-coisas tornar-se primeiro mas não imediatamente o fim');
INSERT INTO verses VALUES (25897, 42, 21, 10, 'Então dizia a-eles Será-levantado nação sobre nação e reino sobre reino');
INSERT INTO verses VALUES (25898, 42, 21, 11, 'terremotos e grandes e segundo lugares pestilências e fomes serão terrores e e de do-céu sinais grandes será');
INSERT INTO verses VALUES (25899, 42, 21, 12, 'antes-de porém destes todos lançarão-sobre sobre vos o mãos deles e perseguirão entregando para o sinagogas e vigílias sendo-conduzidos sobre reis e governadores por-causa-de o nome meu');
INSERT INTO verses VALUES (25900, 42, 21, 13, 'resultará a-vós para testemunho');
INSERT INTO verses VALUES (25901, 42, 21, 14, 'ponde portanto em o corações vosso não premeditando defender-se');
INSERT INTO verses VALUES (25902, 42, 21, 15, 'eu pois darei a-vós boca e sabedoria o qual não poderão resistir ou contradizer todos o opondo-se a-vós');
INSERT INTO verses VALUES (25903, 42, 21, 16, 'sereis-entregues porém e sob pais e dos-irmãos e parentes e amigos e matarão de vosso');
INSERT INTO verses VALUES (25904, 42, 21, 17, 'e sereis odiados sob todos através-de o nome meu');
INSERT INTO verses VALUES (25905, 42, 21, 18, 'e cabelo de o cabeça vosso não não pereça');
INSERT INTO verses VALUES (25906, 42, 21, 19, 'em o Perseverança vosso adquirireis o almas vosso');
INSERT INTO verses VALUES (25907, 42, 21, 20, 'quando porém vejais sendo-cercada sob exércitos Jerusalém então conheçais que aproximou-se o Desolação dela');
INSERT INTO verses VALUES (25908, 42, 21, 21, 'então o em o Judeia fujam para o montes e o em no-meio dela retirem-se e o em o regiões não entrem para ela');
INSERT INTO verses VALUES (25909, 42, 21, 22, 'que dias vingança estas são o ser-enchido todas-as-coisas o escritas');
INSERT INTO verses VALUES (25910, 42, 21, 23, 'ai o em ventre tendo e o às-que-amamentam em naquelas o dias será pois necessidade grande sobre o da-terra e ira o povo neste');
INSERT INTO verses VALUES (25911, 42, 21, 24, 'e cairão boca espada e serão-levados-cativos para o nações todas-as-coisas e Jerusalém será sendo-pisada sob nações até o qual sejam-cumpridos tempos nações');
INSERT INTO verses VALUES (25912, 42, 21, 25, 'e serão sinais em sol e em-lua e estrelas e sobre o da-terra angústia nações em perplexidade Sons do-mar e de-agitação');
INSERT INTO verses VALUES (25913, 42, 21, 26, 'desfalecendo dos-homens de medo e expectativa o sobrevindo o terra-habitada o pois poderes o dos-céus serão-abalados');
INSERT INTO verses VALUES (25914, 42, 21, 27, 'e então verão o Filho o do-homem o-que-vem em nuvem com do-poder e da-glória muita');
INSERT INTO verses VALUES (25915, 42, 21, 28, 'começando porém destes tornar-se erguei-vos e levantai o cabeças vosso porque aproxima-se o redenção vosso');
INSERT INTO verses VALUES (25916, 42, 21, 29, 'e disse parábola a-eles Vede o figueira e todas-as-coisas o árvores');
INSERT INTO verses VALUES (25917, 42, 21, 30, 'quando brotem já vendo de deles-mesmos sabeis que já perto o verão é');
INSERT INTO verses VALUES (25918, 42, 21, 31, 'assim e vós quando vejais estas-coisas acontecendo sabeis que perto é o reino o de-Theos');
INSERT INTO verses VALUES (25919, 42, 21, 32, 'amém digo a-vós que não não passe o geração esta até partícula-condicional todas-as-coisas aconteça');
INSERT INTO verses VALUES (25920, 42, 21, 33, 'o céu e o terra passarão o porém palavras meu não não passarão');
INSERT INTO verses VALUES (25921, 42, 21, 34, 'Guardai-vos porém si-mesmos não alguma-vez sejam-sobrecarregados vosso o corações em embriaguez e bebedeira e preocupações desta-vida e Sobrevenha sobre vos repentino o dia aquela');
INSERT INTO verses VALUES (25922, 42, 21, 35, 'como laço sobrevirá pois sobre todos o estando-sentados sobre rosto toda o da-terra');
INSERT INTO verses VALUES (25923, 42, 21, 36, 'vigiai porém em todo tempo suplicando para que prevaleçais escapar estas-coisas todas-as-coisas o as-coisas-futuras tornar-se e ser-posto-de-pé diante-de o do-Filho o do-homem');
INSERT INTO verses VALUES (25924, 42, 21, 37, 'era porém o do-dia em o templo ensinando o porém noites saindo hospedava-se para o monte o chamado Oliveiras');
INSERT INTO verses VALUES (25925, 42, 21, 38, 'e todo o povo Madrugava junto-a ele em o templo ouvir dele');
INSERT INTO chapters VALUES (995, 42, 22, 71);
INSERT INTO verses VALUES (25926, 42, 22, 1, 'Aproximava-se porém o festa o ázimos o sendo-chamada Páscoa');
INSERT INTO verses VALUES (25927, 42, 22, 2, 'e buscavam o sumos-sacerdotes e o escribas o como destruam ele temiam pois o povo');
INSERT INTO verses VALUES (25928, 42, 22, 3, 'Entrou porém Satanás para Judas o chamado Iscariotes sendo de o número o doze');
INSERT INTO verses VALUES (25929, 42, 22, 4, 'e partindo conversou-com o sumos-sacerdotes e comandantes o como a-eles entregue ele');
INSERT INTO verses VALUES (25930, 42, 22, 5, 'e alegraram-se e combinaram a ele prata dar');
INSERT INTO verses VALUES (25931, 42, 22, 6, 'e confessou e buscava oportunidade o entregar ele sem da-multidão a-eles');
INSERT INTO verses VALUES (25932, 42, 22, 7, 'veio porém o dia o ázimos o qual é necessário ser-sacrificado o páscoa');
INSERT INTO verses VALUES (25933, 42, 22, 8, 'e enviou Pedro e João dizendo Tendo-ido preparai a-nós o páscoa para que comamos');
INSERT INTO verses VALUES (25934, 42, 22, 9, 'o porém disseram a ele Onde queres preparemos');
INSERT INTO verses VALUES (25935, 42, 22, 10, 'o porém disse a-eles Eis tendo-entrado vosso para o cidade encontrará a-vós homem cântaro água carregando segui a ele para o casa para o qual entra');
INSERT INTO verses VALUES (25936, 42, 22, 11, 'e direis o senhor-da-casa o da-casa diz a-ti o Mestre Onde é o hospedaria onde o páscoa com o discípulos meu coma');
INSERT INTO verses VALUES (25937, 42, 22, 12, 'e-aquele a-vós mostrará aposento-superior grande tendo-sido-estendido ali preparai');
INSERT INTO verses VALUES (25938, 42, 22, 13, 'tendo-ido-embora porém encontraram assim-como tinha-dito a-eles e prepararam o páscoa');
INSERT INTO verses VALUES (25939, 42, 22, 14, 'e quando aconteceu o hora reclinou-se e o apóstolos com a ele');
INSERT INTO verses VALUES (25940, 42, 22, 15, 'e disse junto-a eles Desejo desejei isto o páscoa comer com vosso antes-de o me sofrer');
INSERT INTO verses VALUES (25941, 42, 22, 16, 'digo pois a-vós que não-mais não não coma ele até de-quem seja-cumprido em o no-reino o de-Theos');
INSERT INTO verses VALUES (25942, 42, 22, 17, 'e tendo-recebido cálice tendo-dado-graças disse Tomai isto e dividi para a-si-mesmos');
INSERT INTO verses VALUES (25943, 42, 22, 18, 'digo pois a-vós não não beba de o agora de o fruto o videira até o qual o reino o de-Theos venha');
INSERT INTO verses VALUES (25944, 42, 22, 19, 'e tomando pão tendo-dado-graças partiu e deu a-eles dizendo Isto é o corpo meu o em-favor-de vosso sendo-dado isto fazei para o minha memória');
INSERT INTO verses VALUES (25945, 42, 22, 20, 'e o cálice da-mesma-forma com o cear dizendo isto o cálice o nova aliança em o sangue meu o em-favor-de vosso derramado');
INSERT INTO verses VALUES (25946, 42, 22, 21, 'porém eis o mão o do-que-entrega me com mim sobre o mesa');
INSERT INTO verses VALUES (25947, 42, 22, 22, 'que o Filho por-um-lado o do-homem segundo o Tendo-sido-determinado vai porém ai o ao-homem aquele através-de o qual é-entregue');
INSERT INTO verses VALUES (25948, 42, 22, 23, 'e eles-mesmos começaram debater junto-a si-mesmos o quem então seria de deles o isto estando-prestes-a praticar');
INSERT INTO verses VALUES (25949, 42, 22, 24, 'aconteceu porém e contenda em a-eles o quem deles parece ser maior');
INSERT INTO verses VALUES (25950, 42, 22, 25, 'o porém disse a-eles o reis o nações dominam deles e o exercendo-autoridade deles benfeitores são-chamados');
INSERT INTO verses VALUES (25951, 42, 22, 26, 'vós porém não assim mas o maior em a-vós seja como o mais-jovem e o liderando como o servindo');
INSERT INTO verses VALUES (25952, 42, 22, 27, 'quem pois maior o reclinado ou o servindo não o reclinado eu porém em no-meio vosso sou como o servindo');
INSERT INTO verses VALUES (25953, 42, 22, 28, 'vós e/mas sois o tendo-permanecido com mim em o tentações meu');
INSERT INTO verses VALUES (25954, 42, 22, 29, 'e-eu disponho a-vós assim-como estabeleceu a-mim o Pai meu reino');
INSERT INTO verses VALUES (25955, 42, 22, 30, 'para que Comei e bebais sobre o mesa meu em o no-reino meu e sentareis sobre tronos o doze tribos julgando o Israel');
INSERT INTO verses VALUES (25956, 42, 22, 31, 'Simão Simão eis o Satanás pediu vos o peneirar como o trigo');
INSERT INTO verses VALUES (25957, 42, 22, 32, 'eu porém supliquei acerca-de teu para que não desfaleça o fé teu e tu alguma-vez tendo-voltado firma o irmãos teu');
INSERT INTO verses VALUES (25958, 42, 22, 33, 'o porém disse a ele Kyrie com teu preparado sou e para prisão e para morte ir');
INSERT INTO verses VALUES (25959, 42, 22, 34, 'o porém disse digo a-ti Pedro não chamará hoje galo até três-vezes me negará não sei');
INSERT INTO verses VALUES (25960, 42, 22, 35, 'e disse a-eles Quando enviei vos sem bolsa e alforje e sandálias não de-alguém Faltastes o porém disseram Nenhum');
INSERT INTO verses VALUES (25961, 42, 22, 36, 'disse porém a-eles mas agora o tendo bolsa levante semelhantemente e alforje e o não tendo venda o manto dele e compre espada');
INSERT INTO verses VALUES (25962, 42, 22, 37, 'digo pois a-vós que isto o escrito é necessário ser-completado em a-mim o e com iníquos foi-contado e pois o acerca-de mim fim tem');
INSERT INTO verses VALUES (25963, 42, 22, 38, 'o porém disseram Kyrie eis espadas aqui dois o porém disse a-eles Suficiente é');
INSERT INTO verses VALUES (25964, 42, 22, 39, 'e saindo foi segundo o costume para o monte o Oliveiras seguiram porém a ele e o discípulos');
INSERT INTO verses VALUES (25965, 42, 22, 40, 'tendo-se-tornado porém sobre o lugar disse a-eles Orai não entrar para tentação');
INSERT INTO verses VALUES (25966, 42, 22, 41, 'e ele foi-arrancado de deles como pedra tiro e pondo o joelhos orava');
INSERT INTO verses VALUES (25967, 42, 22, 42, 'dizendo Pai se queres afasta isto o cálice de mim porém não o vontade meu mas o teu seja');
INSERT INTO verses VALUES (25968, 42, 22, 43, 'apareceu porém a ele anjo de do-céu fortalecendo ele');
INSERT INTO verses VALUES (25969, 42, 22, 44, 'e tendo-se-tornado em agonia mais-fervorosamente orava e aconteceu o Suor dele como gotas sangue descendo sobre o terra');
INSERT INTO verses VALUES (25970, 42, 22, 45, 'e levantando-se de o oração vindo junto-a o discípulos encontrou adormecidos eles de o tristeza');
INSERT INTO verses VALUES (25971, 42, 22, 46, 'e disse a-eles quê dormis levantando-se orai para que não entreis para tentação');
INSERT INTO verses VALUES (25972, 42, 22, 47, 'Ainda dele falando eis multidão e o chamado Judas um o doze ia-adiante eles e aproximou-se o Iesous beijar ele');
INSERT INTO verses VALUES (25973, 42, 22, 48, 'Iesous porém disse a ele Judá beijo o Filho o do-homem entregas');
INSERT INTO verses VALUES (25974, 42, 22, 49, 'vendo porém o acerca-de ele o Estando-para-ser disseram Kyrie se feriremos em espada');
INSERT INTO verses VALUES (25975, 42, 22, 50, 'e feriu um alguém de deles o do-sumo-sacerdote o servo e tirou o ouvido dele o direito');
INSERT INTO verses VALUES (25976, 42, 22, 51, 'respondendo porém o Iesous disse Deixai até deste e tendo-tocado o Orelha curou ele');
INSERT INTO verses VALUES (25977, 42, 22, 52, 'disse porém Iesous junto-a o tendo-chegado sobre ele sumos-sacerdotes e comandantes o do-templo e anciãos como sobre ladrão saístes com espadas e madeiras');
INSERT INTO verses VALUES (25978, 42, 22, 53, 'segundo dia sendo meu com vosso em o templo não estendestes o mãos sobre a-mim mas esta é vosso o hora e o autoridade o das-trevas');
INSERT INTO verses VALUES (25979, 42, 22, 54, 'Tendo-prendido porém ele levaram e introduziram para o casa o do-sumo-sacerdote o porém Pedro seguia de-longe');
INSERT INTO verses VALUES (25980, 42, 22, 55, 'tendo-acendido porém fogo em no-meio o pátio e tendo-sentado-com sentava-se o Pedro meio deles');
INSERT INTO verses VALUES (25981, 42, 22, 56, 'vendo porém ele serva alguém sentado junto-a o luz e tendo-fitado a ele disse e este com a ele era');
INSERT INTO verses VALUES (25982, 42, 22, 57, 'o porém negou dizendo não sei ele mulher');
INSERT INTO verses VALUES (25983, 42, 22, 58, 'e com pouco outro vendo ele disse e tu de deles és o porém Pedro disse Homem não sou');
INSERT INTO verses VALUES (25984, 42, 22, 59, 'e tendo-se-separado como hora uma outro alguém afirmava-com-insistência dizendo sobre da-verdade e este com dele era e pois Galileu é');
INSERT INTO verses VALUES (25985, 42, 22, 60, 'disse porém o Pedro Homem não sei o qual dizes e imediatamente ainda falando dele chamou galo');
INSERT INTO verses VALUES (25986, 42, 22, 61, 'e voltando-se o Kyrios olhou-fixamente o a-Pedro e Lembrou-se o Pedro o da-palavra o do-Kyrios como disse a ele que Antes-que galo chamar hoje negará me três-vezes');
INSERT INTO verses VALUES (25987, 42, 22, 62, 'e saindo fora chorou amargamente');
INSERT INTO verses VALUES (25988, 42, 22, 63, 'e o homens o constrangendo ele escarneciam a ele espancando');
INSERT INTO verses VALUES (25989, 42, 22, 64, 'e tendo-coberto ele perguntavam dizendo Profetiza quem é o tendo-golpeado te');
INSERT INTO verses VALUES (25990, 42, 22, 65, 'e outras muitas-coisas blasfemando diziam para ele');
INSERT INTO verses VALUES (25991, 42, 22, 66, 'e como aconteceu dia reuniu-se o conselho-de-anciãos o povo sumos-sacerdotes e e escribas e levaram-embora ele para o sinédrio deles');
INSERT INTO verses VALUES (25992, 42, 22, 67, 'dizendo se tu és o Christos dize a-nós disse porém a-eles se a-vós diga não não creiais');
INSERT INTO verses VALUES (25993, 42, 22, 68, 'se porém perguntarei não não respondais');
INSERT INTO verses VALUES (25994, 42, 22, 69, 'de o agora porém será o Filho o do-homem estando-sentado de direita o do-poder o de-Theos');
INSERT INTO verses VALUES (25995, 42, 22, 70, 'disseram porém todos tu portanto és o Filho o de-Theos o porém junto-a eles disse vós dizeis que eu sou');
INSERT INTO verses VALUES (25996, 42, 22, 71, 'o porém disseram quê ainda temos testemunho necessidade eles-mesmos pois ouvimos de o da-boca dele');
INSERT INTO chapters VALUES (996, 42, 23, 55);
INSERT INTO verses VALUES (25997, 42, 23, 1, 'e tendo-levantado todo o multidão deles levaram ele sobre o Pilatos');
INSERT INTO verses VALUES (25998, 42, 23, 2, 'começaram porém acusar dele dizendo Este encontramos pervertendo o nação nosso e impedindo tributos César dar e dizendo si-mesmo Christos rei ser');
INSERT INTO verses VALUES (25999, 42, 23, 3, 'o porém Pilatos perguntou ele dizendo tu és o Rei o judeus o porém respondendo a ele disse tu dizes');
INSERT INTO verses VALUES (26000, 42, 23, 4, 'o porém Pilatos disse junto-a o sumos-sacerdotes e o multidões Nada encontro causa em o ao-homem neste');
INSERT INTO verses VALUES (26001, 42, 23, 5, 'o porém insistiam dizendo que Incita o povo ensinando segundo de-toda o Judeia e começando de o Galileia até aqui');
INSERT INTO verses VALUES (26002, 42, 23, 6, 'Pilatos porém ouvindo perguntou se o homem Galileu é');
INSERT INTO verses VALUES (26003, 42, 23, 7, 'e reconhecendo que de o da-autoridade de-Herodes é enviou-de-volta ele junto-a Herodes sendo e ele em em-Jerusalém em estas o dias');
INSERT INTO verses VALUES (26004, 42, 23, 8, 'o porém Herodes vendo o Iesous alegrou-se muito era pois de suficientes tempos querendo ver ele através-de o ouvir acerca-de dele e Esperava algo sinal ver sob dele acontecendo');
INSERT INTO verses VALUES (26005, 42, 23, 9, 'perguntava porém ele em palavras Suficientes ele porém nada respondeu a ele');
INSERT INTO verses VALUES (26006, 42, 23, 10, 'estavam-de-pé porém o sumos-sacerdotes e o escribas vigorosamente acusando dele');
INSERT INTO verses VALUES (26007, 42, 23, 11, 'tendo-desprezado porém ele o Herodes com o exércitos dele e tendo-escarnecido tendo-vestido veste resplandecente enviou-de-volta ele o Pilatos');
INSERT INTO verses VALUES (26008, 42, 23, 12, 'tornaram-se porém amigos o e Herodes e o Pilatos em a-ela o dia com uns-aos-outros existiam-anteriormente pois em Inimizade sendo junto-a si-mesmos');
INSERT INTO verses VALUES (26009, 42, 23, 13, 'Pilatos porém tendo-convocado-junto o sumos-sacerdotes e o governantes e o povo');
INSERT INTO verses VALUES (26010, 42, 23, 14, 'disse junto-a eles Trouxestes a-mim o homem este como desviando o povo e eis eu diante-de vosso tendo-examinado nada encontraram em o ao-homem neste causa o qual acusais segundo dele');
INSERT INTO verses VALUES (26011, 42, 23, 15, 'mas nem Herodes enviou-de-volta pois ele junto-a nos e eis nada digno da-morte é tendo-sido-praticado a ele');
INSERT INTO verses VALUES (26012, 42, 23, 16, 'tendo-disciplinado portanto ele soltarei');
INSERT INTO verses VALUES (26013, 42, 23, 18, 'clamaram porém em-toda-a-multidão dizendo Levanta este liberta porém a-nós o Barrabás');
INSERT INTO verses VALUES (26014, 42, 23, 19, 'qualquer-que era através-de dissensão algum acontecida em o na-cidade e assassinato tendo-sido-lançado em o na-prisão');
INSERT INTO verses VALUES (26015, 42, 23, 20, 'novamente porém o Pilatos chamou a-eles querendo soltar o Iesous');
INSERT INTO verses VALUES (26016, 42, 23, 21, 'o porém clamavam dizendo Cruz cruz ele');
INSERT INTO verses VALUES (26017, 42, 23, 22, 'o porém terceira-vez disse junto-a eles quê pois mau fez este nada causa da-morte encontraram em a ele tendo-disciplinado portanto ele soltarei');
INSERT INTO verses VALUES (26018, 42, 23, 23, 'o porém pressionavam-sobre com-vozes grandes pedindo ele ser-crucificado e prevaleciam o vozes deles');
INSERT INTO verses VALUES (26019, 42, 23, 24, 'e Pilatos sentenciou tornar-se o pedido deles');
INSERT INTO verses VALUES (26020, 42, 23, 25, 'soltou porém o através-de dissensão e assassinato tendo-sido-lançado para prisão o qual pediam o porém Iesous entregou o vontade deles');
INSERT INTO verses VALUES (26021, 42, 23, 26, 'e como levaram-embora ele agarrando Simão alguém Cireneu o-que-vem de campo puseram-sobre a ele o cruz trazer por-detrás o Iesous');
INSERT INTO verses VALUES (26022, 42, 23, 27, 'Seguia porém a ele muito multidão o povo e mulheres o qual lamentavam-se e lamentavam ele');
INSERT INTO verses VALUES (26023, 42, 23, 28, 'voltando-se porém junto-a a-elas Iesous disse Filhas Jerusalém não chorai sobre a-mim porém sobre A-si-mesmas chorai e sobre o filhos vosso');
INSERT INTO verses VALUES (26024, 42, 23, 29, 'que eis vêm dias em o qual dirão Bem-aventuradas o estéreis e o ventres o qual não geraram e seios o qual não Alimentaram');
INSERT INTO verses VALUES (26025, 42, 23, 30, 'então começarão dizer o montes Caí sobre nos e o colinas Cobri nos');
INSERT INTO verses VALUES (26026, 42, 23, 31, 'que se em verde madeira estas-coisas fazem em o seco quê aconteça');
INSERT INTO verses VALUES (26027, 42, 23, 32, 'Eram-conduzidos porém e outros malfeitores dois com a ele ser-morto');
INSERT INTO verses VALUES (26028, 42, 23, 33, 'e quando vieram sobre o lugar o chamado Crânio ali crucificaram ele e o malfeitores o qual por-um-lado de direita o qual porém de esquerda');
INSERT INTO verses VALUES (26029, 42, 23, 34, 'o porém Iesous dizia Pai deixa a-eles não pois sei quê fazem sendo-divididos porém o vestes dele lançaram sortes');
INSERT INTO verses VALUES (26030, 42, 23, 35, 'e estava-de-pé o povo observando escarneciam porém e o governantes dizendo Outros salvou salve a-si-mesmo se este é o Christos o de-Theos o escolhido');
INSERT INTO verses VALUES (26031, 42, 23, 36, 'zombaram porém a ele e o soldados aproximando-se vinagre oferecendo a ele');
INSERT INTO verses VALUES (26032, 42, 23, 37, 'e dizendo se tu és o Rei o judeus salva a-ti-mesmo');
INSERT INTO verses VALUES (26033, 42, 23, 38, 'era porém e inscrição sobre a ele o REI o JUDEUS ESTE');
INSERT INTO verses VALUES (26034, 42, 23, 39, 'Um porém o tendo-sido-pendurados malfeitores blasfemava ele Não tu és o Christos salva a-ti-mesmo e nos');
INSERT INTO verses VALUES (26035, 42, 23, 40, 'respondendo porém o outro repreendendo a ele disse nem temes tu o Theos que em o a ele julgamento és');
INSERT INTO verses VALUES (26036, 42, 23, 41, 'e nós por-um-lado justamente dignos pois o qual Praticamos recebemos este porém nada absurdo praticou');
INSERT INTO verses VALUES (26037, 42, 23, 42, 'e dizia Iesous lembra-te meu quando Venhas para o reino teu');
INSERT INTO verses VALUES (26038, 42, 23, 43, 'e disse a ele Amém a-ti digo hoje com mim serás em o Paraíso');
INSERT INTO verses VALUES (26039, 42, 23, 44, 'e era já como hora sexta e trevas aconteceu sobre toda o terra até hora nona');
INSERT INTO verses VALUES (26040, 42, 23, 45, 'o sol tendo-faltado rasgou-se porém o véu o santuário meio');
INSERT INTO verses VALUES (26041, 42, 23, 46, 'e chamando com-voz grande o Iesous disse Pai para mãos teu confio o espírito meu isto porém dizendo expirou');
INSERT INTO verses VALUES (26042, 42, 23, 47, 'vendo porém o centurião o acontecido glorificava o Theos dizendo Verdadeiramente o homem este justo era');
INSERT INTO verses VALUES (26043, 42, 23, 48, 'e todos o tendo-se-apresentado-junto multidões sobre o espetáculo esta tendo-contemplado o tendo-acontecido batendo o peitos retornavam');
INSERT INTO verses VALUES (26044, 42, 23, 49, 'estavam-de-pé porém todos o conhecidos a ele de de-longe e mulheres o seguindo-junto a ele de o Galileia vendo estas-coisas');
INSERT INTO verses VALUES (26045, 42, 23, 50, 'e eis homem em-nome José conselheiro sendo homem bom e justo');
INSERT INTO verses VALUES (26046, 42, 23, 51, 'este não era tendo-consentido o conselho e o prática deles de Arimateia cidade o judeus o qual esperava o reino o de-Theos');
INSERT INTO verses VALUES (26047, 42, 23, 52, 'este aproximando-se o Pilatos pediu o corpo o Iesous');
INSERT INTO verses VALUES (26048, 42, 23, 53, 'e tendo-derrubado envolveu ele linho e colocou ele em sepulcro cavado-em-rocha do-qual não era ninguém ainda-não jazendo');
INSERT INTO verses VALUES (26049, 42, 23, 54, 'e dia era Preparação e sábado amanhecia');
INSERT INTO verses VALUES (26050, 42, 23, 55, 'Tendo-seguido porém o mulheres as-quais eram tendo-se-reunido de o Galileia a ele contemplaram o túmulo e como Foi-posto o corpo dele');
INSERT INTO verses VALUES (26051, 42, 23, 56, 'tendo-retornado porém prepararam aromas e perfumes e o por-um-lado sábado aquietaram-se segundo o mandamento');
INSERT INTO chapters VALUES (997, 42, 24, 53);
INSERT INTO verses VALUES (26052, 42, 24, 1, 'o porém uma o sábados madrugada profundamente sobre o sepulcro vieram carregando o qual prepararam aromas');
INSERT INTO verses VALUES (26053, 42, 24, 2, 'encontraram porém o pedra tendo-sido-rolado de o sepulcro');
INSERT INTO verses VALUES (26054, 42, 24, 3, 'tendo-entrado porém não encontraram o corpo o do-Kyrios Iesous');
INSERT INTO verses VALUES (26055, 42, 24, 4, 'e aconteceu em o estar-perplexo a-elas acerca-de deste e eis homens dois aproximaram-se a-elas em veste relampejante');
INSERT INTO verses VALUES (26056, 42, 24, 5, 'atemorizados porém tendo-acontecido deles e inclinando o faces para o terra disseram junto-a elas quê buscais o vivendo com o mortos');
INSERT INTO verses VALUES (26057, 42, 24, 6, 'não é aqui mas foi-ressuscitado lembrai-vos como falou a-vós ainda sendo em o Galileia');
INSERT INTO verses VALUES (26058, 42, 24, 7, 'dizendo o Filho o do-homem que é necessário ser-entregue para mãos dos-homens dos-pecadores e ser-crucificado e o no-terceiro dia levantar-se');
INSERT INTO verses VALUES (26059, 42, 24, 8, 'e lembraram-se o palavras dele');
INSERT INTO verses VALUES (26060, 42, 24, 9, 'e tendo-retornado de o sepulcro anunciaram estas-coisas todas-as-coisas o onze e todos o restantes');
INSERT INTO verses VALUES (26061, 42, 24, 10, 'eram porém o Madalena Maria e Joana e Maria o de-Tiago e o restantes com a-elas diziam junto-a o apóstolos estas-coisas');
INSERT INTO verses VALUES (26062, 42, 24, 11, 'e Apareceram diante-de deles como tolice o palavras estas-coisas e não-criam a-elas');
INSERT INTO verses VALUES (26063, 42, 24, 12, 'o porém Pedro levantando-se correu sobre o túmulo e inclinando-se vê o faixas-de-linho somente e partiu junto-a si-mesmo maravilhando-se o tendo-acontecido');
INSERT INTO verses VALUES (26064, 42, 24, 13, 'e eis dois de deles em a-ela o dia eram indo para aldeia distando estádios Sessenta de Jerusalém o qual nome Emaús');
INSERT INTO verses VALUES (26065, 42, 24, 14, 'e eles-mesmos conversavam junto-a uns-aos-outros acerca-de todos o tendo-acontecido destes');
INSERT INTO verses VALUES (26066, 42, 24, 15, 'e aconteceu em o conversar eles e debater e ele Iesous tendo-se-aproximado caminhava-junto a-eles');
INSERT INTO verses VALUES (26067, 42, 24, 16, 'o porém olhos deles eram-segurados o não reconhecer ele');
INSERT INTO verses VALUES (26068, 42, 24, 17, 'disse porém junto-a eles Quais o palavras estes o qual discutis junto-a uns-aos-outros andando e Foram-postos-em-pé de-rosto-triste');
INSERT INTO verses VALUES (26069, 42, 24, 18, 'respondendo porém um em-nome Cleopas disse junto-a ele tu só peregrina Jerusalém e não conheceste o tendo-acontecido em a-ela em o dias estas');
INSERT INTO verses VALUES (26070, 42, 24, 19, 'e disse a-eles Qual o porém disseram a ele o acerca-de Iesous o Nazareno o qual aconteceu homem profeta poderoso em obra e em-palavra diante-de o de-Theos e de-todo o povo');
INSERT INTO verses VALUES (26071, 42, 24, 20, 'para-que e entregaram ele o sumos-sacerdotes e o governantes nosso para juízo da-morte e crucificaram ele');
INSERT INTO verses VALUES (26072, 42, 24, 21, 'nós porém esperávamos que ele-mesmo é o estando-prestes-a resgatar o Israel mas pois e com todos nestes terceira esta dia conduz de o qual estas-coisas aconteceu');
INSERT INTO verses VALUES (26073, 42, 24, 22, 'mas e mulheres alguns de nosso ficaram-fora-de-si nos acontecidas madrugadoras sobre o túmulo');
INSERT INTO verses VALUES (26074, 42, 24, 23, 'e não tendo-encontrado o corpo dele vieram dizendo e visão anjo Ter-visto o qual dizem ele viver');
INSERT INTO verses VALUES (26075, 42, 24, 24, 'e parti alguns o com a-nós sobre o túmulo e encontraram assim assim-como e o mulheres disseram ele porém não vi');
INSERT INTO verses VALUES (26076, 42, 24, 25, 'e ele disse junto-a eles Ó insensatos e lentos o no-coração o crer sobre todos o qual falaram o profetas');
INSERT INTO verses VALUES (26077, 42, 24, 26, 'não estas-coisas é necessário sofrer o Christos e entrar para o glória dele');
INSERT INTO verses VALUES (26078, 42, 24, 27, 'e começando de de-Moisés e de todos o profetas interpretou a-eles em todas o escrituras o acerca-de si-mesmo');
INSERT INTO verses VALUES (26079, 42, 24, 28, 'e aproximaram-se para o aldeia do-qual iam e ele fingiu mais-adiante ir');
INSERT INTO verses VALUES (26080, 42, 24, 29, 'e constrangeram ele dizendo Permanece com nosso que junto-a Tarde é e tem-declinado já o dia e entrou o permanecer com a-eles');
INSERT INTO verses VALUES (26081, 42, 24, 30, 'e aconteceu em o reclinar-se ele com deles tomando o pão abençoou e partindo entregava a-eles');
INSERT INTO verses VALUES (26082, 42, 24, 31, 'deles porém foram-abertos o olhos e reconheceram ele e ele invisível aconteceu de deles');
INSERT INTO verses VALUES (26083, 42, 24, 32, 'e disseram junto-a uns-aos-outros Não o coração nosso queimando era em a-nós como falava a-nós em o caminho como abria a-nós o escrituras');
INSERT INTO verses VALUES (26084, 42, 24, 33, 'e levantando-se a-ela o hora retornaram para Jerusalém e encontraram tendo-sido-reunidos o onze e o com a-eles');
INSERT INTO verses VALUES (26085, 42, 24, 34, 'dizendo que verdadeiramente foi-ressuscitado o Kyrios e apareceu Simão');
INSERT INTO verses VALUES (26086, 42, 24, 35, 'e eles-mesmos narravam o em o caminho e como foi-conhecido a-eles em o partir o pão');
INSERT INTO verses VALUES (26087, 42, 24, 36, 'estas-coisas porém deles falantes ele pôs-se-de-pé em no-meio deles e diz a-eles Paz a-vós');
INSERT INTO verses VALUES (26088, 42, 24, 37, 'tendo-sido-aterrorizados porém e Amedrontados tendo-se-tornado pensavam espírito contemplar');
INSERT INTO verses VALUES (26089, 42, 24, 38, 'e disse a-eles quê tendo-sido-perturbados sois e através-de quê raciocínios sobem em o no-coração vosso');
INSERT INTO verses VALUES (26090, 42, 24, 39, 'vede o mãos meu e o pés meu que eu sou ele-mesmo apalpai me e vede que espírito carne e ossos não tem assim-como mim contemplais tendo');
INSERT INTO verses VALUES (26091, 42, 24, 40, 'e isto dizendo mostrou a-eles o mãos e o pés');
INSERT INTO verses VALUES (26092, 42, 24, 41, 'ainda porém dos-que-não-creem deles de o alegria e admirando disse a-eles Tendes algo comestível aqui');
INSERT INTO verses VALUES (26093, 42, 24, 42, 'o porém entregaram a ele peixe assado parte');
INSERT INTO verses VALUES (26094, 42, 24, 43, 'e tomando diante-de deles comeu');
INSERT INTO verses VALUES (26095, 42, 24, 44, 'disse porém junto-a eles Estes o palavras meu o qual falei junto-a vos ainda sendo com a-vós que é necessário ser-cumprido todas-as-coisas o escritas em o lei de-Moisés e o profetas e salmos acerca-de mim');
INSERT INTO verses VALUES (26096, 42, 24, 45, 'então abriu deles o mente o compreender o escrituras e disse a-eles');
INSERT INTO verses VALUES (26097, 42, 24, 46, 'que assim está-escrito sofrer o Christos e levantar-se de mortos o no-terceiro dia');
INSERT INTO verses VALUES (26098, 42, 24, 47, 'e ser-proclamado sobre o em-nome dele arrependimento para perdão dos-pecados para todas-as-coisas o nações tendo-começado de Jerusalém');
INSERT INTO verses VALUES (26099, 42, 24, 48, 'vós testemunhas destes');
INSERT INTO verses VALUES (26100, 42, 24, 49, 'e eis eu envio-para-fora o promessa o do-Pai meu sobre vos vós porém sentai-vos em o na-cidade até o qual vistais de altura poder');
INSERT INTO verses VALUES (26101, 42, 24, 50, 'Conduziu-para-fora porém eles até junto-a Betânia e levantando o mãos dele abençoou eles');
INSERT INTO verses VALUES (26102, 42, 24, 51, 'e aconteceu em o abençoar ele eles separou-se de deles e era-levado-para-cima para o céu');
INSERT INTO verses VALUES (26103, 42, 24, 52, 'e eles-mesmos tendo-se-prostrado ele retornaram para Jerusalém com alegria grande');
INSERT INTO verses VALUES (26104, 42, 24, 53, 'e eram através-de de-todo em o templo bendizendo o Theos');
INSERT INTO books VALUES (43, 'JHN', 'João', 'NT', 21);
INSERT INTO chapters VALUES (998, 43, 1, 51);
INSERT INTO verses VALUES (26105, 43, 1, 1, 'em princípio era o palavra e o palavra era junto-a o Theos e Theos era o palavra');
INSERT INTO verses VALUES (26106, 43, 1, 2, 'este era em princípio junto-a o Theos');
INSERT INTO verses VALUES (26107, 43, 1, 3, 'todas-as-coisas através-de dele aconteceu e sem dele aconteceu nem um o qual aconteceu');
INSERT INTO verses VALUES (26108, 43, 1, 4, 'em a ele vida era e o vida era o luz o dos-homens');
INSERT INTO verses VALUES (26109, 43, 1, 5, 'e o luz em o trevas brilha e o trevas ele não alcançou');
INSERT INTO verses VALUES (26110, 43, 1, 6, 'aconteceu homem tendo-sido-enviado de-junto-de de-Theos nome a ele João');
INSERT INTO verses VALUES (26111, 43, 1, 7, 'este veio para testemunho para que testemunhe acerca-de o luz para que todos creiam através-de dele');
INSERT INTO verses VALUES (26112, 43, 1, 8, 'não era aquele o luz mas para que testemunhe acerca-de o luz');
INSERT INTO verses VALUES (26113, 43, 1, 9, 'era o luz o verdadeiro o qual ilumina todas-as-coisas homem vindo para o mundo');
INSERT INTO verses VALUES (26114, 43, 1, 10, 'em o ao-mundo era e o mundo através-de dele aconteceu e o mundo ele não conheceu');
INSERT INTO verses VALUES (26115, 43, 1, 11, 'para o próprias veio e o Próprios ele não recebi');
INSERT INTO verses VALUES (26116, 43, 1, 12, 'quanto porém receberam ele deu a-eles autoridade filhos de-Theos tornar-se o creem para o nome dele');
INSERT INTO verses VALUES (26117, 43, 1, 13, 'o qual não de sangue nem de da-vontade carne nem de da-vontade homem mas de de-Theos foram-gerados');
INSERT INTO verses VALUES (26118, 43, 1, 14, 'e o palavra carne aconteceu e Habitou-em-tenda em a-nós e contemplamos o glória dele glória como unigênito de-junto-de Pai cheio da-graça e da-verdade');
INSERT INTO verses VALUES (26119, 43, 1, 15, 'João testifica acerca-de dele e tem-clamado dizendo este era o qual disseram o atrás meu vindo diante-de meu aconteceu que primeiro meu era');
INSERT INTO verses VALUES (26120, 43, 1, 16, 'que de o plenitude dele nós todos recebemos e graça em-troca-de da-graça');
INSERT INTO verses VALUES (26121, 43, 1, 17, 'que o lei através-de Moisés foi-dado o graça e o verdade através-de Iesous de-Christos aconteceu');
INSERT INTO verses VALUES (26122, 43, 1, 18, 'Theos ninguém tem-visto jamais unigênito Theos o sendo para o seio o do-Pai aquele relatou');
INSERT INTO verses VALUES (26123, 43, 1, 19, 'e esta é o testemunho o João quando enviaram junto-a ele o judeus de Jerusalém sacerdotes e levitas para que Perguntem ele tu quem és');
INSERT INTO verses VALUES (26124, 43, 1, 20, 'e confessou e não negou e confessou que eu não sou o Christos');
INSERT INTO verses VALUES (26125, 43, 1, 21, 'e perguntaram ele quê portanto tu Elias és e diz não sou o profeta és tu e respondeu Não');
INSERT INTO verses VALUES (26126, 43, 1, 22, 'disseram portanto a ele quem és para que resposta demos o tendo-enviado nos quê dizes acerca-de ti-mesmo');
INSERT INTO verses VALUES (26127, 43, 1, 23, 'disse eu voz clamando em o deserto Endireitai o caminho do-Kyrios assim-como disse Isaías o profeta');
INSERT INTO verses VALUES (26128, 43, 1, 24, 'e enviados eram de o fariseus');
INSERT INTO verses VALUES (26129, 43, 1, 25, 'e perguntaram ele e disseram a ele quê portanto batizas se tu não és o Christos nem Elias nem o profeta');
INSERT INTO verses VALUES (26130, 43, 1, 26, 'respondeu a-eles o João dizendo eu batizo em água meio vosso está-firme o qual vós não sei');
INSERT INTO verses VALUES (26131, 43, 1, 27, 'o atrás meu vindo o qual não sou eu digno para que desatarei dele o correia o Sandália');
INSERT INTO verses VALUES (26132, 43, 1, 28, 'estas-coisas em Betânia aconteceu além o Jordão onde era o João batizando');
INSERT INTO verses VALUES (26133, 43, 1, 29, 'o no-dia-seguinte vê o Iesous o-que-vem junto-a ele e diz Vê o Cordeiro o de-Theos o levantando o pecado o do-mundo');
INSERT INTO verses VALUES (26134, 43, 1, 30, 'este é em-favor-de o qual eu disseram atrás meu vem homem o qual diante-de meu aconteceu que primeiro meu era');
INSERT INTO verses VALUES (26135, 43, 1, 31, 'e-eu não sei ele mas para que seja-manifestada o Israel através-de isto vieram eu em água batizando');
INSERT INTO verses VALUES (26136, 43, 1, 32, 'e testemunhou João dizendo que Tenho-contemplado o espírito descendo como pomba de do-céu e permaneceu sobre ele');
INSERT INTO verses VALUES (26137, 43, 1, 33, 'e-eu não sei ele mas o tendo-enviado me batizar em água aquele a-mim disse sobre o qual partícula-condicional Vejas o espírito descendo e permanecendo sobre ele este é o batizando em Espírito no-santo');
INSERT INTO verses VALUES (26138, 43, 1, 34, 'e-eu tenho-visto e tenho-testemunhado que este é o Filho o de-Theos');
INSERT INTO verses VALUES (26139, 43, 1, 35, 'o no-dia-seguinte novamente estava-de-pé o João e de o discípulos dele dois');
INSERT INTO verses VALUES (26140, 43, 1, 36, 'e olhando-fixamente o Iesous andando diz Vê o Cordeiro o de-Theos');
INSERT INTO verses VALUES (26141, 43, 1, 37, 'e ouviram o dois discípulos dele falando e seguiram o Iesous');
INSERT INTO verses VALUES (26142, 43, 1, 38, 'voltando-se porém o Iesous e tendo-contemplado eles seguindo diz a-eles quê buscais o porém disseram a ele Rabi o qual é-chamado sendo-traduzido Mestre onde permaneces');
INSERT INTO verses VALUES (26143, 43, 1, 39, 'diz a-eles Vinde e vereis vieram portanto e viram onde permanece e de a ele permaneceram o dia aquela hora era como décima');
INSERT INTO verses VALUES (26144, 43, 1, 40, 'era André o irmão de-Simão de-Pedro um de o dois o tendo-ouvido de-junto-de João e tendo-seguido a ele');
INSERT INTO verses VALUES (26145, 43, 1, 41, 'encontra este primeiro o irmão o próprio Simão e diz a ele Encontramos o Messias o qual é sendo-traduzido Christos');
INSERT INTO verses VALUES (26146, 43, 1, 42, 'conduziu ele junto-a o Iesous olhando-fixamente a ele o Iesous disse tu és Simão o Filho João tu serás-chamado Cefas o qual é-interpretado Pedro');
INSERT INTO verses VALUES (26147, 43, 1, 43, 'o no-dia-seguinte quis sair para o Galileia e encontra Filipe e diz a ele o Iesous Segue a-mim');
INSERT INTO verses VALUES (26148, 43, 1, 44, 'era porém o Filipe de Betsaida de o cidade André e de-Pedro');
INSERT INTO verses VALUES (26149, 43, 1, 45, 'encontra Filipe o Natanael e diz a ele o qual escreveu Moisés em o lei e o profetas encontramos Iesous Filho o José o de Nazaré');
INSERT INTO verses VALUES (26150, 43, 1, 46, 'e disse a ele Natanael de Nazaré pode algo bom ser diz a ele o Filipe Vem e vê');
INSERT INTO verses VALUES (26151, 43, 1, 47, 'viu Iesous o Natanael vindo junto-a ele e diz acerca-de dele Vê verdadeiramente Israelita em o qual engano não é');
INSERT INTO verses VALUES (26152, 43, 1, 48, 'diz a ele Natanael de-onde me conheces respondeu Iesous e disse a ele Antes-de o te Filipe chamar sendo sob o figueira viram te');
INSERT INTO verses VALUES (26153, 43, 1, 49, 'respondeu a ele Natanael Rabi tu és o Filho o de-Theos tu Rei és o Israel');
INSERT INTO verses VALUES (26154, 43, 1, 50, 'respondeu Iesous e disse a ele que dize a-ti que viram te debaixo o figueira crês maior destes verás');
INSERT INTO verses VALUES (26155, 43, 1, 51, 'e diz a ele Amém amém digo a-vós vereis o céu tendo-sido-abertos e o anjo o de-Theos subindo e descendo sobre o Filho o do-homem');
INSERT INTO chapters VALUES (999, 43, 2, 25);
INSERT INTO verses VALUES (26156, 43, 2, 1, 'e o dia o no-terceiro bodas aconteceu em Caná o Galileia e era o mãe o Iesous ali');
INSERT INTO verses VALUES (26157, 43, 2, 2, 'foi-chamado porém e o Iesous e o discípulos dele para o casamento');
INSERT INTO verses VALUES (26158, 43, 2, 3, 'e Tendo-faltado vinho diz o mãe o Iesous junto-a ele vinho não têm');
INSERT INTO verses VALUES (26159, 43, 2, 4, 'e diz a-ela o Iesous quê mim e te mulher ainda-não chegou o hora meu');
INSERT INTO verses VALUES (26160, 43, 2, 5, 'diz o mãe dele o servos o qual algo partícula-condicional diga a-vós fazei');
INSERT INTO verses VALUES (26161, 43, 2, 6, 'eram porém ali de-pedra talhas seis segundo o purificação o judeus jazendo contendo cada metretas dois ou três');
INSERT INTO verses VALUES (26162, 43, 2, 7, 'diz a-eles o Iesous Enchei o talhas água e encheram elas até acima');
INSERT INTO verses VALUES (26163, 43, 2, 8, 'e diz a-eles Tirai agora e trazei o mestre-de-cerimônias o porém trouxeram');
INSERT INTO verses VALUES (26164, 43, 2, 9, 'como porém provou o mestre-de-cerimônias o água vinho tendo-sido-feito e não sei de-onde é o porém servos sei o tendo-tirado o água chama o noivo o mestre-de-cerimônias');
INSERT INTO verses VALUES (26165, 43, 2, 10, 'e diz a ele todo homem primeiro o belo vinho põe e quando embriaguem-se o menor tu tens-guardado o belo vinho até agora');
INSERT INTO verses VALUES (26166, 43, 2, 11, 'esta fez início o sinais o Iesous em Caná o Galileia e manifestou o glória dele e creram para ele o discípulos dele');
INSERT INTO verses VALUES (26167, 43, 2, 12, 'com isto desceu para Cafarnaum ele e o mãe dele e o irmãos e o discípulos dele e ali permaneceram não muitas do-dia');
INSERT INTO verses VALUES (26168, 43, 2, 13, 'e perto era o páscoa o judeus e subiu para Jerusalém o Iesous');
INSERT INTO verses VALUES (26169, 43, 2, 14, 'e encontrou em o templo o vendendo bois e ovelhas e pombas e o cambistas sentados');
INSERT INTO verses VALUES (26170, 43, 2, 15, 'e tendo-feito flagelo de de-cordas todos expulsou de o do-templo o e ovelhas e o bois e o cambistas derramou o moedas e o mesas transtornou');
INSERT INTO verses VALUES (26171, 43, 2, 16, 'e o o pombas vendem disse Levantai estas-coisas daqui não fazei o casa o Pai meu casa comércio');
INSERT INTO verses VALUES (26172, 43, 2, 17, 'lembraram-se o discípulos dele que escrito é o zelo o da-casa teu devorará me');
INSERT INTO verses VALUES (26173, 43, 2, 18, 'responderam portanto o judeus e disseram a ele quê sinal mostras a-nós que estas-coisas fazes');
INSERT INTO verses VALUES (26174, 43, 2, 19, 'respondeu Iesous e disse a-eles Desatai o templo este e em três dias levantarei ele');
INSERT INTO verses VALUES (26175, 43, 2, 20, 'disseram portanto o judeus quarenta e seis anos foi-edificada o templo este e tu em três dias levantarás ele');
INSERT INTO verses VALUES (26176, 43, 2, 21, 'aquele porém dizia acerca-de o templo o do-corpo dele');
INSERT INTO verses VALUES (26177, 43, 2, 22, 'quando portanto foi-ressuscitado de mortos lembraram-se o discípulos dele que isto dizia e creram o escritura e o em-palavra o qual disse o Iesous');
INSERT INTO verses VALUES (26178, 43, 2, 23, 'como porém era em o em-Jerusalém em o páscoa em o festa muitos creram para o nome dele observando dele o sinais o qual fazia');
INSERT INTO verses VALUES (26179, 43, 2, 24, 'ele porém Iesous não cria si-mesmo a-eles através-de o ele conhecer todos');
INSERT INTO verses VALUES (26180, 43, 2, 25, 'e que não necessidade tinha para que alguém testemunhe acerca-de o do-homem ele pois conhecia quê era em o ser-humano');
INSERT INTO chapters VALUES (1000, 43, 3, 36);
INSERT INTO verses VALUES (26181, 43, 3, 1, 'era porém homem de o fariseus Nicodemos nome a ele governante o judeus');
INSERT INTO verses VALUES (26182, 43, 3, 2, 'este veio junto-a ele noite e disse a ele Rabi sei que de de-Theos tens-vindo mestre ninguém pois pode estas-coisas o sinais fazer o qual tu fazes se não seja o Theos com dele');
INSERT INTO verses VALUES (26183, 43, 3, 3, 'respondeu Iesous e disse a ele Amém amém digo a-ti se não alguém seja-gerado de-cima não pode ver o reino o de-Theos');
INSERT INTO verses VALUES (26184, 43, 3, 4, 'diz junto-a ele o Nicodemos como pode homem ser-gerado ancião sendo não pode para o ventre o mãe dele segundo entrar e ser-gerado');
INSERT INTO verses VALUES (26185, 43, 3, 5, 'respondeu Iesous Amém amém digo a-ti se não alguém seja-gerado de água e do-espírito não pode entrar para o reino o de-Theos');
INSERT INTO verses VALUES (26186, 43, 3, 6, 'o gerado de o carne carne é e o gerado de o do-espírito espírito é');
INSERT INTO verses VALUES (26187, 43, 3, 7, 'não maravilles que dize a-ti é necessário vos ser-gerado de-cima');
INSERT INTO verses VALUES (26188, 43, 3, 8, 'o espírito onde quer sopra e o voz dele ouves mas não sei de-onde vem e onde vai assim é todo o gerado de o do-espírito');
INSERT INTO verses VALUES (26189, 43, 3, 9, 'respondeu Nicodemos e disse a ele como pode estas-coisas tornar-se');
INSERT INTO verses VALUES (26190, 43, 3, 10, 'respondeu Iesous e disse a ele tu és o mestre o Israel e estas-coisas não conheces');
INSERT INTO verses VALUES (26191, 43, 3, 11, 'amém amém digo a-ti que o qual sei falamos e o qual vimos testemunhamos e o testemunho nosso não recebeis');
INSERT INTO verses VALUES (26192, 43, 3, 12, 'se o terrenas disseram a-vós e não credes como se diga a-vós o celestiais crereis');
INSERT INTO verses VALUES (26193, 43, 3, 13, 'e ninguém tem-subido para o céu se não o de o do-céu tendo-descido o Filho o do-homem');
INSERT INTO verses VALUES (26194, 43, 3, 14, 'e assim-como Moisés exaltou o serpente em o deserto assim ser-exaltado é necessário o Filho o do-homem');
INSERT INTO verses VALUES (26195, 43, 3, 15, 'para que todo o crendo em a ele tenha vida eterno');
INSERT INTO verses VALUES (26196, 43, 3, 16, 'assim pois amou o Theos o mundo de-modo-que o Filho o unigênito deu para que todo o crendo para ele não pereça mas tenha vida eterno');
INSERT INTO verses VALUES (26197, 43, 3, 17, 'não pois enviou o Theos o Filho para o mundo para que julgue o mundo mas para que seja-salvo o mundo através-de dele');
INSERT INTO verses VALUES (26198, 43, 3, 18, 'o crendo para ele não é-julgado o não crendo já tem-sido-julgado que não tem-crido para o nome o unigênito do-Filho o de-Theos');
INSERT INTO verses VALUES (26199, 43, 3, 19, 'esta e/mas é o julgamento que o luz tem-vindo para o mundo e amaram o homens mais o trevas ou o luz era pois deles má o obra');
INSERT INTO verses VALUES (26200, 43, 3, 20, 'todo pois o vis praticando odeia o luz e não vem junto-a o luz para que não seja-repreendido o obra dele');
INSERT INTO verses VALUES (26201, 43, 3, 21, 'o porém fazendo o verdade vem junto-a o luz para que seja-manifestada dele o obra que em a-Theos é tendo-sido-trabalhadas');
INSERT INTO verses VALUES (26202, 43, 3, 22, 'com estas-coisas veio o Iesous e o discípulos dele para o Judeia terra e ali permanecia com deles e batizava');
INSERT INTO verses VALUES (26203, 43, 3, 23, 'era porém e João batizando em Enom perto o Salim que água muitas-coisas era ali e chegavam e eram-batizados');
INSERT INTO verses VALUES (26204, 43, 3, 24, 'ainda-não pois era tendo-sido-lançado para o prisão João');
INSERT INTO verses VALUES (26205, 43, 3, 25, 'aconteceu portanto busca de o discípulos João com Judeu acerca-de purificação');
INSERT INTO verses VALUES (26206, 43, 3, 26, 'e vieram junto-a o João e disseram a ele Rabi o qual era com teu além o Jordão o qual tu tens-testemunhado vê este batiza e todos vêm junto-a ele');
INSERT INTO verses VALUES (26207, 43, 3, 27, 'respondeu João e disse não pode homem receber nada se não seja dado a ele de o do-céu');
INSERT INTO verses VALUES (26208, 43, 3, 28, 'eles-mesmos vós a-mim testemunhais que disseram não sou eu o Christos mas que Tendo-sido-enviado sou diante daquele');
INSERT INTO verses VALUES (26209, 43, 3, 29, 'o tendo o noiva noivo é o porém amigo o noivo o tendo-ficado-de-pé e ouvindo dele alegria alegra-se através-de o voz o noivo esta portanto o alegria o minha foi-cumprido');
INSERT INTO verses VALUES (26210, 43, 3, 30, 'aquele é necessário crescer mim porém ser-diminuído');
INSERT INTO verses VALUES (26211, 43, 3, 31, 'o de-cima vindo sobre todos é o sendo de o da-terra de o da-terra é e de o da-terra fala o de o do-céu vindo sobre todos é');
INSERT INTO verses VALUES (26212, 43, 3, 32, 'o qual tem-visto e ouviu isto testifica e o testemunho dele ninguém recebe');
INSERT INTO verses VALUES (26213, 43, 3, 33, 'o tomando dele o testemunho Selou que o Theos verdadeiro é');
INSERT INTO verses VALUES (26214, 43, 3, 34, 'o qual pois enviou o Theos o palavras o de-Theos fala não pois de medida dá o espírito');
INSERT INTO verses VALUES (26215, 43, 3, 35, 'o Pai ama o filho e todas-as-coisas tem-dado em o mão dele');
INSERT INTO verses VALUES (26216, 43, 3, 36, 'o crendo para o Filho tem vida eterno o porém desobedecendo o filho não verá vida mas o ira o de-Theos permanece sobre ele');
INSERT INTO chapters VALUES (1001, 43, 4, 54);
INSERT INTO verses VALUES (26217, 43, 4, 1, 'como portanto conheceu o Kyrios que ouviram o fariseus que Iesous mais discípulos faz e batiza ou João');
INSERT INTO verses VALUES (26218, 43, 4, 2, 'embora Iesous ele não batizava mas o discípulos dele');
INSERT INTO verses VALUES (26219, 43, 4, 3, 'deixou o Judeia e partiu novamente para o Galileia');
INSERT INTO verses VALUES (26220, 43, 4, 4, 'é necessário porém ele atravessar através-de o Samaria');
INSERT INTO verses VALUES (26221, 43, 4, 5, 'vem portanto para cidade o Samaria chamada Sicar próximo o campo o qual deu Jacó José o filho dele');
INSERT INTO verses VALUES (26222, 43, 4, 6, 'era porém ali fonte o Jacó o portanto Iesous tendo-trabalhado de o jornada sentava-se assim sobre o fonte hora era como sexta');
INSERT INTO verses VALUES (26223, 43, 4, 7, 'vem mulher de o Samaria tirar-água água diz a-ela o Iesous Dá a-mim beber');
INSERT INTO verses VALUES (26224, 43, 4, 8, 'o pois discípulos dele tinham-partido para o cidade para que alimentos comprem');
INSERT INTO verses VALUES (26225, 43, 4, 9, 'diz portanto a ele o mulher o Samaritana como tu judeu sendo de-junto-de mim beber pedes mulher Samaritana sendo não pois têm-trato-com judeus Samaritanos');
INSERT INTO verses VALUES (26226, 43, 4, 10, 'respondeu Iesous e disse a-ela se sei o gratuitamente o de-Theos e quem é o dizendo a-ti Dá a-mim beber tu partícula-condicional Pediste ele e deu se a-ti água vivendo');
INSERT INTO verses VALUES (26227, 43, 4, 11, 'diz a ele Kyrie nem balde tens e o poço é profundo de-onde portanto tens o água o vivendo');
INSERT INTO verses VALUES (26228, 43, 4, 12, 'não tu maior és o do-Pai nosso Jacó o qual deu a-nós o poço e ele de dele bebeu e o filhos dele e o rebanhos dele');
INSERT INTO verses VALUES (26229, 43, 4, 13, 'respondeu Iesous e disse a-ela todo o bebendo de o água deste terá-sede novamente');
INSERT INTO verses VALUES (26230, 43, 4, 14, 'o qual e/mas partícula-condicional beba de o água o qual eu darei a ele não não terá-sede para o eternidade mas o água o qual darei a ele acontecerá em a ele fonte água saltando para vida eterno');
INSERT INTO verses VALUES (26231, 43, 4, 15, 'diz junto-a ele o mulher Kyrie dá a-mim isto o água para que não tenho-sede nem passe-através aqui tirar-água');
INSERT INTO verses VALUES (26232, 43, 4, 16, 'diz a-ela Vai chama o homem teu e vem aqui');
INSERT INTO verses VALUES (26233, 43, 4, 17, 'respondeu o mulher e disse não tenho homem diz a-ela o Iesous Bem disseste que homem não tenho');
INSERT INTO verses VALUES (26234, 43, 4, 18, 'cinco pois homens Tiveste e agora o qual tens não é teu homem isto verdadeiro tens-dito');
INSERT INTO verses VALUES (26235, 43, 4, 19, 'diz a ele o mulher Kyrie observo que profeta és tu');
INSERT INTO verses VALUES (26236, 43, 4, 20, 'o pais nosso em o no-monte neste adoraram e vós dizeis que em em-Jerusalém é o lugar onde adorar é necessário');
INSERT INTO verses VALUES (26237, 43, 4, 21, 'diz a-ela o Iesous Crê a-mim mulher que vem hora quando nem em o no-monte neste nem em em-Jerusalém prostrar-vos-eis o Pai');
INSERT INTO verses VALUES (26238, 43, 4, 22, 'vós prostrais-vos o qual não sei nós prostramo-nos o qual sei que o salvação de o judeus é');
INSERT INTO verses VALUES (26239, 43, 4, 23, 'mas vem hora e agora é quando o verdadeiras adoradores adorarão o Pai em espírito e verdade e pois o Pai tais busca o adorando ele');
INSERT INTO verses VALUES (26240, 43, 4, 24, 'espírito o Theos e o adorando em espírito e verdade é necessário adorar');
INSERT INTO verses VALUES (26241, 43, 4, 25, 'diz a ele o mulher sei que Messias vem o chamado Christos quando venha aquele anunciará a-nós todas-as-coisas');
INSERT INTO verses VALUES (26242, 43, 4, 26, 'diz a-ela o Iesous Eu sou o falando a-ti');
INSERT INTO verses VALUES (26243, 43, 4, 27, 'e sobre neste vieram o discípulos dele e admiravam-se que com mulher falava ninguém contudo disse quê buscas ou quê falas com dela');
INSERT INTO verses VALUES (26244, 43, 4, 28, 'deixou portanto o talha dela o mulher e partiu para o cidade e diz o aos-homens');
INSERT INTO verses VALUES (26245, 43, 4, 29, 'vinde vede homem o qual disse a-mim todas-as-coisas o qual fiz acaso este é o Christos');
INSERT INTO verses VALUES (26246, 43, 4, 30, 'saíram de o cidade e vinham junto-a ele');
INSERT INTO verses VALUES (26247, 43, 4, 31, 'em o entre perguntavam ele o discípulos dizendo Rabi come');
INSERT INTO verses VALUES (26248, 43, 4, 32, 'o porém disse a-eles eu comida tenho comer o qual vós não sei');
INSERT INTO verses VALUES (26249, 43, 4, 33, 'diziam portanto o discípulos junto-a uns-aos-outros não alguém trouxe a ele comer');
INSERT INTO verses VALUES (26250, 43, 4, 34, 'diz a-eles o Iesous Meu alimento é para que faço o vontade o que-enviou me e aperfeiçoarei dele o obra');
INSERT INTO verses VALUES (26251, 43, 4, 35, 'não vós dizeis que Ainda de-quatro-meses é e o ceifa vem eis digo a-vós levantai o olhos vosso e contemplai o região que brancas são junto-a ceifa já');
INSERT INTO verses VALUES (26252, 43, 4, 36, 'o ceifando salário recebe e reúne fruto para vida eterno para que o o-que-semeia juntamente alegra-se e o ceifando');
INSERT INTO verses VALUES (26253, 43, 4, 37, 'em pois neste o palavra é verdadeiro que outro é o o-que-semeia e outro o ceifando');
INSERT INTO verses VALUES (26254, 43, 4, 38, 'eu enviei vos ceifar o qual não vós tendes-trabalhado outros têm-trabalhado e vós para o trabalho deles tendes-entrado');
INSERT INTO verses VALUES (26255, 43, 4, 39, 'de porém o cidade daquela muitos creram para ele o samaritanos através-de o palavra o mulher testemunhando que disse a-mim todas-as-coisas o qual fiz');
INSERT INTO verses VALUES (26256, 43, 4, 40, 'como portanto vieram junto-a ele o Samaritanos perguntavam ele permanecer de a-eles e permaneceu ali dois do-dia');
INSERT INTO verses VALUES (26257, 43, 4, 41, 'e muito mais creram através-de o palavra dele');
INSERT INTO verses VALUES (26258, 43, 4, 42, 'o e mulher diziam que não-mais através-de o tua fala cremos eles-mesmos pois temos-ouvido e sei que este é verdadeiramente o Salvador o do-mundo');
INSERT INTO verses VALUES (26259, 43, 4, 43, 'com porém o dois do-dia saiu dali para o Galileia');
INSERT INTO verses VALUES (26260, 43, 4, 44, 'ele pois Iesous testemunhou que profeta em o em-particular pátria honra não tem');
INSERT INTO verses VALUES (26261, 43, 4, 45, 'quando portanto veio para o Galileia receberam ele o galileus todas-as-coisas Tendo-visto quanto fez em em-Jerusalém em o festa e eles-mesmos pois vieram para o festa');
INSERT INTO verses VALUES (26262, 43, 4, 46, 'veio portanto novamente para o Caná o Galileia onde fez o água vinho e era alguém real o qual o Filho estava-doente em Cafarnaum');
INSERT INTO verses VALUES (26263, 43, 4, 47, 'este ouvindo que Iesous chegou de o Judeia para o Galileia partiu junto-a ele e perguntava para que desça e Cure dele o filho estava-prestes-a pois morrer');
INSERT INTO verses VALUES (26264, 43, 4, 48, 'disse portanto o Iesous junto-a ele se não sinais e prodígios vejais não não creiais');
INSERT INTO verses VALUES (26265, 43, 4, 49, 'diz junto-a ele o real Kyrie desce antes-de morrer o criança meu');
INSERT INTO verses VALUES (26266, 43, 4, 50, 'diz a ele o Iesous vai o filho teu vive creu o homem o em-palavra o qual disse a ele o Iesous e ia');
INSERT INTO verses VALUES (26267, 43, 4, 51, 'já porém dele descendo o servos encontraram a ele dizendo que o servo dele vive');
INSERT INTO verses VALUES (26268, 43, 4, 52, 'Inquiriu portanto o hora de deles em o qual melhor teve disseram portanto a ele que Ontem hora sétima deixou ele o febre');
INSERT INTO verses VALUES (26269, 43, 4, 53, 'conheceu portanto o Pai que naquela o hora em o qual disse a ele o Iesous o filho teu vive e creu ele e o casa dele toda');
INSERT INTO verses VALUES (26270, 43, 4, 54, 'isto porém novamente segundo sinal fez o Iesous vindo de o Judeia para o Galileia');
INSERT INTO chapters VALUES (1002, 43, 5, 47);
INSERT INTO verses VALUES (26271, 43, 5, 1, 'com estas-coisas era festa o judeus e subiu Iesous para Jerusalém');
INSERT INTO verses VALUES (26272, 43, 5, 2, 'é porém em o em-Jerusalém sobre o das-ovelhas tanque o sendo-chamada em-hebraico Betzatá cinco pórticos tendo');
INSERT INTO verses VALUES (26273, 43, 5, 3, 'em estas estava-deitado multidão o estando-fracos cegos de-mancos secos esperando o o água movimento');
INSERT INTO verses VALUES (26274, 43, 5, 4, 'anjo pois segundo tempo descia em o tanque e Perturbava o água o portanto primeiro embarcando com o perturbação o água são tornava-se o qual alguma-vez era-retida doença');
INSERT INTO verses VALUES (26275, 43, 5, 5, 'era e/mas alguém homem ali trinta e oito anos tendo em o fraqueza dele');
INSERT INTO verses VALUES (26276, 43, 5, 6, 'este vendo o Iesous reclinado e sabendo que muito já tempo tem diz a ele Queres são tornar-se');
INSERT INTO verses VALUES (26277, 43, 5, 7, 'respondeu a ele o fracos Kyrie homem não tenho para que quando seja-perturbado o água lance me para o tanque em o qual porém venho eu outro antes-de mim desce');
INSERT INTO verses VALUES (26278, 43, 5, 8, 'diz a ele o Iesous Levanta-te levanta o maca teu e anda');
INSERT INTO verses VALUES (26279, 43, 5, 9, 'e imediatamente aconteceu são o homem e levantou o maca dele e andava era porém sábado em naquela o dia');
INSERT INTO verses VALUES (26280, 43, 5, 10, 'diziam portanto o judeus o tendo-sido-curado Sábado é e não é-lícito a-ti levantar o maca');
INSERT INTO verses VALUES (26281, 43, 5, 11, 'o qual porém respondeu a-eles o tendo-feito me são aquele a-mim disse Levanta o maca teu e anda');
INSERT INTO verses VALUES (26282, 43, 5, 12, 'perguntaram ele quem é o homem o dizendo a-ti Levanta e anda');
INSERT INTO verses VALUES (26283, 43, 5, 13, 'o porém Tendo-sido-curado não sei quem é o pois Iesous retirou-se multidão sendo em o no-lugar');
INSERT INTO verses VALUES (26284, 43, 5, 14, 'com estas-coisas encontra ele o Iesous em o templo e disse a ele Vê são tens-te-tornado não-mais peca para que não pior te algo aconteça');
INSERT INTO verses VALUES (26285, 43, 5, 15, 'partiu o homem e disse o judeus que Iesous é o tendo-feito ele são');
INSERT INTO verses VALUES (26286, 43, 5, 16, 'e através-de isto perseguiam o judeus o Iesous que estas-coisas fazia em no-sábado');
INSERT INTO verses VALUES (26287, 43, 5, 17, 'o porém respondeu a-eles o Pai meu até agora trabalha e-eu trabalho');
INSERT INTO verses VALUES (26288, 43, 5, 18, 'através-de isto portanto mais buscavam ele o judeus matar que não somente Desatava o sábado mas e Pai próprio dizia o Theos Igual si-mesmo fazendo o a-Theos');
INSERT INTO verses VALUES (26289, 43, 5, 19, 'Respondeu portanto o Iesous e dizia a-eles Amém amém digo a-vós não pode o Filho fazer de si-mesmo nada partícula-condicional não algo veja o Pai fazendo o qual pois partícula-condicional aquele faça estas-coisas e o Filho semelhantemente faz');
INSERT INTO verses VALUES (26290, 43, 5, 20, 'o pois Pai ama o Filho e todas-as-coisas mostra a ele o qual ele faz e maior destes mostrará a ele obra para que vós maravilheis');
INSERT INTO verses VALUES (26291, 43, 5, 21, 'como pois o Pai levanta o mortos e vivifica assim e o Filho o qual quer vivifica');
INSERT INTO verses VALUES (26292, 43, 5, 22, 'nem pois o Pai julga a-ninguém mas o juízo toda tem-dado o filho');
INSERT INTO verses VALUES (26293, 43, 5, 23, 'para que todos honrem o Filho assim-como honrem o Pai o não honrando o Filho não honra o Pai o tendo-enviado ele');
INSERT INTO verses VALUES (26294, 43, 5, 24, 'amém amém digo a-vós que o o palavra meu ouvindo e crendo o tendo-enviado me tem vida eterno e para juízo não vem mas tem-passado de o da-morte para o vida');
INSERT INTO verses VALUES (26295, 43, 5, 25, 'amém amém digo a-vós que vem hora e agora é quando o mortos ouvirão o voz o do-Filho o de-Theos e o ouvindo viverão');
INSERT INTO verses VALUES (26296, 43, 5, 26, 'assim-como pois o Pai tem vida em si-mesmo assim e o filho deu vida ter em si-mesmo');
INSERT INTO verses VALUES (26297, 43, 5, 27, 'e autoridade deu a ele juízo fazer que Filho do-homem é');
INSERT INTO verses VALUES (26298, 43, 5, 28, 'não admirais isto que vem hora em o qual todos o em o sepulcros ouvirão o voz dele');
INSERT INTO verses VALUES (26299, 43, 5, 29, 'e sairão o o boas-coisas tendo-feito para ressurreição da-vida o o vis tendo-praticado para ressurreição julgamento');
INSERT INTO verses VALUES (26300, 43, 5, 30, 'não posso eu fazer de de-mim-mesmo nada assim-como ouço julgo e o julgamento o minha justa é que não busco o vontade o meu mas o vontade o que-enviou me');
INSERT INTO verses VALUES (26301, 43, 5, 31, 'se eu testemunho acerca-de de-mim-mesmo o testemunho meu não é verdadeiro');
INSERT INTO verses VALUES (26302, 43, 5, 32, 'outro é o testemunhando acerca-de mim e sei que verdadeiro é o testemunho o qual testifica acerca-de mim');
INSERT INTO verses VALUES (26303, 43, 5, 33, 'vós enviastes junto-a João e tem-testemunhado o verdade');
INSERT INTO verses VALUES (26304, 43, 5, 34, 'eu porém não de-junto-de do-homem o testemunho recebo mas estas-coisas digo para que vós sejais-salvos');
INSERT INTO verses VALUES (26305, 43, 5, 35, 'aquele era o lâmpada o ardendo e brilhando vós porém quisestes exultar junto-a hora em o luz dele');
INSERT INTO verses VALUES (26306, 43, 5, 36, 'eu porém tenho o testemunho maior o João o pois obra o qual deu a-mim o Pai para que aperfeiçoarei elas elas o obra o qual faço testifica acerca-de mim que o Pai me enviou');
INSERT INTO verses VALUES (26307, 43, 5, 37, 'e o tendo-enviado me Pai aquele tem-testemunhado acerca-de mim nem voz dele jamais tendes-ouvido nem forma dele tendes-visto');
INSERT INTO verses VALUES (26308, 43, 5, 38, 'e o palavra dele não tendes em a-vós permanecendo que o qual enviou aquele neste vós não credes');
INSERT INTO verses VALUES (26309, 43, 5, 39, 'Examinais o escrituras que vós pensais em elas vida eterno ter e aquelas são o testemunhando acerca-de mim');
INSERT INTO verses VALUES (26310, 43, 5, 40, 'e não quereis vir para me para que vida tenhais');
INSERT INTO verses VALUES (26311, 43, 5, 41, 'glória de-junto-de dos-homens não recebo');
INSERT INTO verses VALUES (26312, 43, 5, 42, 'mas Tenho-conhecido vos que o amor o de-Theos não tendes em si-mesmos');
INSERT INTO verses VALUES (26313, 43, 5, 43, 'eu tenho-vindo em o em-nome o Pai meu e não recebeis me se outro venha em o em-nome o próprio aquele recebereis');
INSERT INTO verses VALUES (26314, 43, 5, 44, 'como podeis vós crer glória de-junto-de uns-aos-outros recebendo e o glória o de-junto-de o somente de-Theos não buscais');
INSERT INTO verses VALUES (26315, 43, 5, 45, 'não pensais que eu acusarei vosso junto-a o Pai é o acusando vosso Moisés para o qual vós tendes-esperado');
INSERT INTO verses VALUES (26316, 43, 5, 46, 'se pois acreditáveis Moisés acreditáveis partícula-condicional me acerca-de pois mim aquele escreveu');
INSERT INTO verses VALUES (26317, 43, 5, 47, 'se porém o daquele letras não credes como o meus Palavras crereis');
INSERT INTO chapters VALUES (1003, 43, 6, 71);
INSERT INTO verses VALUES (26318, 43, 6, 1, 'com estas-coisas partiu o Iesous além o do-mar o Galileia o Tiberíades');
INSERT INTO verses VALUES (26319, 43, 6, 2, 'seguia porém a ele multidão muito que Viam o sinais o qual fazia sobre o estando-fracos');
INSERT INTO verses VALUES (26320, 43, 6, 3, 'subiu porém para o monte Iesous e ali sentava-se com o discípulos dele');
INSERT INTO verses VALUES (26321, 43, 6, 4, 'era porém perto o páscoa o festa o judeus');
INSERT INTO verses VALUES (26322, 43, 6, 5, 'levantando portanto o olhos o Iesous e tendo-contemplado que muito multidão vem junto-a ele diz junto-a Filipe de-onde compremos pães para que comam estes');
INSERT INTO verses VALUES (26323, 43, 6, 6, 'isto porém dizia tentando ele ele pois sei quê estava-prestes fazer');
INSERT INTO verses VALUES (26324, 43, 6, 7, 'respondeu a ele o Filipe Duzentos denários pães não bastam a-eles para que cada-um pouco algo tome');
INSERT INTO verses VALUES (26325, 43, 6, 8, 'diz a ele um de o discípulos dele André o irmão de-Simão de-Pedro');
INSERT INTO verses VALUES (26326, 43, 6, 9, 'é rapazinho aqui o qual tem cinco pães de-cevada e dois peixinhos mas estas-coisas quê é para tantos');
INSERT INTO verses VALUES (26327, 43, 6, 10, 'disse o Iesous Fazei o homens reclinar-se era porém erva muito em o no-lugar reclinaram-se portanto o homens o número como cinco-mil');
INSERT INTO verses VALUES (26328, 43, 6, 11, 'recebeu portanto o pães o Iesous e tendo-dado-graças distribuiu o reclinados semelhantemente e de o peixinhos quanto queriam');
INSERT INTO verses VALUES (26329, 43, 6, 12, 'como porém foram-enchidos diz o discípulos dele Reuni o tendo-abundado pedaços para que não algo pereça');
INSERT INTO verses VALUES (26330, 43, 6, 13, 'reuniram portanto e encheram doze cestos pedaços de o cinco pães o de-cevada o qual abundaram o tendo-comido');
INSERT INTO verses VALUES (26331, 43, 6, 14, 'o portanto homens vendo o qual fez sinal diziam que Este é verdadeiramente o profeta o vindo para o mundo');
INSERT INTO verses VALUES (26332, 43, 6, 15, 'Iesous portanto sabendo que estão-a-ponto-de vir e arrebatar ele para que façam rei retirou-se novamente para o monte ele só');
INSERT INTO verses VALUES (26333, 43, 6, 16, 'como porém tarde aconteceu desceram o discípulos dele sobre o mar');
INSERT INTO verses VALUES (26334, 43, 6, 17, 'e tendo-embarcado para barco vinham além o mar para Cafarnaum e trevas já tinha-acontecido e ainda-não tinha-vindo junto-a eles o Iesous');
INSERT INTO verses VALUES (26335, 43, 6, 18, 'o e mar vento grande soprando despertava-se');
INSERT INTO verses VALUES (26336, 43, 6, 19, 'tendo-remado portanto como estádios vinte cinco ou trinta contemplam o Iesous andando sobre o mar e perto o do-barco acontecendo e temeram');
INSERT INTO verses VALUES (26337, 43, 6, 20, 'o porém diz a-eles Eu sou não temei');
INSERT INTO verses VALUES (26338, 43, 6, 21, 'queriam portanto receber ele para o barco e imediatamente aconteceu o barco sobre o da-terra para o qual iam');
INSERT INTO verses VALUES (26339, 43, 6, 22, 'o no-dia-seguinte o multidão o tendo-ficado-de-pé além o do-mar vi que barquinho outro não era ali se não um e que não entrou-junto o discípulos dele o Iesous para o barco mas sós o discípulos dele foram');
INSERT INTO verses VALUES (26340, 43, 6, 23, 'mas veio barquinhos de Tiberíades perto o lugar onde comeram o pão tendo-dado-graças o do-Kyrios');
INSERT INTO verses VALUES (26341, 43, 6, 24, 'quando portanto viu o multidão que Iesous não é ali nem o discípulos dele embarcaram eles-mesmos para o barquinhos e vieram para Cafarnaum buscando o Iesous');
INSERT INTO verses VALUES (26342, 43, 6, 25, 'e tendo-encontrado ele além o mar disseram a ele Rabi quando aqui tens-te-tornado');
INSERT INTO verses VALUES (26343, 43, 6, 26, 'respondeu a-eles o Iesous e disse Amém amém digo a-vós buscais me não que vistes sinais mas que Comestes de o pães e Fostes-saciados');
INSERT INTO verses VALUES (26344, 43, 6, 27, 'trabalhai não o comida o sendo-destruída mas o comida o permanecendo para vida eterno o qual o Filho o do-homem a-vós dará este pois o Pai selou o Theos');
INSERT INTO verses VALUES (26345, 43, 6, 28, 'disseram portanto junto-a ele quê façamos para que trabalhemos o obra o de-Theos');
INSERT INTO verses VALUES (26346, 43, 6, 29, 'respondeu Iesous e disse a-eles isto é o obra o de-Theos para que creiais para o qual enviou aquele');
INSERT INTO verses VALUES (26347, 43, 6, 30, 'disseram portanto a ele quê portanto fazes tu sinal para que vejamos e creiamos a-ti quê Trabalhas');
INSERT INTO verses VALUES (26348, 43, 6, 31, 'o pais nosso o maná comeram em o deserto assim-como é escrito Pão de o do-céu deu a-eles comer');
INSERT INTO verses VALUES (26349, 43, 6, 32, 'disse portanto a-eles o Iesous Amém amém digo a-vós não Moisés tem-dado a-vós o pão de o do-céu mas o Pai meu dá a-vós o pão de o do-céu o verdadeiro');
INSERT INTO verses VALUES (26350, 43, 6, 33, 'o pois pão o de-Theos é o descendo de o do-céu e vida dando o ao-mundo');
INSERT INTO verses VALUES (26351, 43, 6, 34, 'disseram portanto junto-a ele Kyrie sempre dá a-nós o pão este');
INSERT INTO verses VALUES (26352, 43, 6, 35, 'disse a-eles o Iesous Eu sou o pão o da-vida o vindo junto-a mim não não tenha-fome e o crendo para mim não não terá-sede jamais');
INSERT INTO verses VALUES (26353, 43, 6, 36, 'mas disseram a-vós que e Tendes-visto me e não credes');
INSERT INTO verses VALUES (26354, 43, 6, 37, 'todo o qual dá a-mim o Pai junto-a mim virá e o vindo para me não não expulse fora');
INSERT INTO verses VALUES (26355, 43, 6, 38, 'que tenho-descido de o do-céu não para que faço o vontade o meu mas o vontade o que-enviou me');
INSERT INTO verses VALUES (26356, 43, 6, 39, 'isto e/mas é o vontade o que-enviou me para que todo o qual deu a-mim não destrua de dele mas ressuscitarei ele em o última dia');
INSERT INTO verses VALUES (26357, 43, 6, 40, 'isto pois é o vontade o Pai meu para que todo o observando o Filho e crendo para ele tenha vida eterno e ressuscitarei ele eu em o última dia');
INSERT INTO verses VALUES (26358, 43, 6, 41, 'Murmuravam portanto o judeus acerca-de dele que disse Eu sou o pão o descendo de o do-céu');
INSERT INTO verses VALUES (26359, 43, 6, 42, 'e diziam não este é Iesous o Filho José o qual nós sei o Pai e o mãe como agora diz que de o do-céu tenho-descido');
INSERT INTO verses VALUES (26360, 43, 6, 43, 'respondeu Iesous e disse a-eles não murmurais com uns-aos-outros');
INSERT INTO verses VALUES (26361, 43, 6, 44, 'ninguém pode vir para me se não o Pai o tendo-enviado me Arraste ele e-eu ressuscitarei ele em o última dia');
INSERT INTO verses VALUES (26362, 43, 6, 45, 'é escrito em o profetas e serão todos ensinados de-Theos todo o ouvindo de-junto-de o do-Pai e tendo-aprendido vem junto-a a-mim');
INSERT INTO verses VALUES (26363, 43, 6, 46, 'não que o Pai Tem-visto alguém se não o sendo de-junto-de o de-Theos este tem-visto o Pai');
INSERT INTO verses VALUES (26364, 43, 6, 47, 'amém amém digo a-vós o crendo tem vida eterno');
INSERT INTO verses VALUES (26365, 43, 6, 48, 'eu sou o pão o da-vida');
INSERT INTO verses VALUES (26366, 43, 6, 49, 'o pais vosso comeram em o deserto o maná e morreram');
INSERT INTO verses VALUES (26367, 43, 6, 50, 'este é o pão o de o do-céu descendo para que alguém de dele coma e não morra');
INSERT INTO verses VALUES (26368, 43, 6, 51, 'eu sou o pão o vivendo o de o do-céu tendo-descido se alguém coma de deste o pão viverá para o eternidade e o pão porém o qual eu darei o carne meu é em-favor-de o o do-mundo da-vida');
INSERT INTO verses VALUES (26369, 43, 6, 52, 'Contendiam portanto junto-a uns-aos-outros o judeus dizendo como pode este a-nós dar o carne comer');
INSERT INTO verses VALUES (26370, 43, 6, 53, 'disse portanto a-eles o Iesous Amém amém digo a-vós se não comei o carne o do-Filho o do-homem e bebais dele o sangue não tendes vida em si-mesmos');
INSERT INTO verses VALUES (26371, 43, 6, 54, 'o comendo meu o carne e bebendo meu o sangue tem vida eterno e-eu ressuscitarei ele o última dia');
INSERT INTO verses VALUES (26372, 43, 6, 55, 'o pois carne meu verdadeiro é comida e o sangue meu verdadeiro é bebida');
INSERT INTO verses VALUES (26373, 43, 6, 56, 'o comendo meu o carne e bebendo meu o sangue em mim permanece e-eu em a ele');
INSERT INTO verses VALUES (26374, 43, 6, 57, 'assim-como enviou me o vivendo Pai e-eu vivo através-de o Pai e o comendo me e-aquele viverá através-de me');
INSERT INTO verses VALUES (26375, 43, 6, 58, 'este é o pão o de do-céu tendo-descido não assim-como comeram o pais e morreram o comendo este o pão viverá para o eternidade');
INSERT INTO verses VALUES (26376, 43, 6, 59, 'estas-coisas disse em na-sinagoga ensinando em Cafarnaum');
INSERT INTO verses VALUES (26377, 43, 6, 60, 'muitos portanto ouvindo de o discípulos dele disseram Duro é o palavra este quem pode dele ouvir');
INSERT INTO verses VALUES (26378, 43, 6, 61, 'sei porém o Iesous em si-mesmo que murmuram acerca-de deste o discípulos dele disse a-eles isto vos escandaliza');
INSERT INTO verses VALUES (26379, 43, 6, 62, 'se portanto contempleis o Filho o do-homem subindo onde era o antes');
INSERT INTO verses VALUES (26380, 43, 6, 63, 'o espírito é o vivificando o carne não aproveita nada o palavras o qual eu tenho-falado a-vós espírito é e vida é');
INSERT INTO verses VALUES (26381, 43, 6, 64, 'mas são de vosso alguns o qual não creem sei pois de princípio o Iesous quem são o não crendo e quem é o estando-para-entregar ele');
INSERT INTO verses VALUES (26382, 43, 6, 65, 'e dizia através-de isto disse a-vós que ninguém pode vir para me se não seja dado a ele de o Pai');
INSERT INTO verses VALUES (26383, 43, 6, 66, 'de deste muitos o discípulos dele foram para o atrás e não-mais com dele andavam');
INSERT INTO verses VALUES (26384, 43, 6, 67, 'disse portanto o Iesous o doze não e vós quereis ir');
INSERT INTO verses VALUES (26385, 43, 6, 68, 'respondeu a ele Simão Pedro Kyrie junto-a quem iremos palavras da-vida eterno tens');
INSERT INTO verses VALUES (26386, 43, 6, 69, 'e nós temos-crido e temos-conhecido que tu és o santo o de-Theos');
INSERT INTO verses VALUES (26387, 43, 6, 70, 'respondeu a-eles o Iesous não eu vos o doze escolhi e de vosso um diabo é');
INSERT INTO verses VALUES (26388, 43, 6, 71, 'dizia porém o Judas de-Simão Iscariotes este pois estava-prestes entregar ele um de o doze');
INSERT INTO chapters VALUES (1004, 43, 7, 53);
INSERT INTO verses VALUES (26389, 43, 7, 1, 'e com estas-coisas andava o Iesous em o Galileia não pois queria em o Judeia andar que buscavam ele o judeus matar');
INSERT INTO verses VALUES (26390, 43, 7, 2, 'era porém perto o festa o judeus o festa-das-tendas');
INSERT INTO verses VALUES (26391, 43, 7, 3, 'disseram portanto junto-a ele o irmãos dele Passa-daqui daqui e vai para o Judeia para que e o discípulos teu contemplarão o obra teu o qual fazes');
INSERT INTO verses VALUES (26392, 43, 7, 4, 'ninguém pois algo em oculto faz e busca ele em com-ousadia ser se estas-coisas fazes manifesta a-ti-mesmo o ao-mundo');
INSERT INTO verses VALUES (26393, 43, 7, 5, 'nem pois o irmãos dele criam para ele');
INSERT INTO verses VALUES (26394, 43, 7, 6, 'diz portanto a-eles o Iesous o tempo o meu ainda-não está-presente o porém tempo o vosso sempre é preparado');
INSERT INTO verses VALUES (26395, 43, 7, 7, 'não pode o mundo odiar vos mim porém odeia que eu testemunho acerca-de dele que o obra dele má é');
INSERT INTO verses VALUES (26396, 43, 7, 8, 'vós subi para o festa eu ainda-não subo para o festa esta que o meu tempo ainda-não foi-cumprido');
INSERT INTO verses VALUES (26397, 43, 7, 9, 'estas-coisas porém dizendo a-eles permaneceu em o Galileia');
INSERT INTO verses VALUES (26398, 43, 7, 10, 'como porém subiram o irmãos dele para o festa então e ele subiu não manifestamente mas como em oculto');
INSERT INTO verses VALUES (26399, 43, 7, 11, 'o portanto judeus buscavam ele em o festa e diziam onde é aquele');
INSERT INTO verses VALUES (26400, 43, 7, 12, 'e murmuração acerca-de dele era muito em o às-multidões o por-um-lado diziam que Bom é outros porém diziam Não mas engana o multidão');
INSERT INTO verses VALUES (26401, 43, 7, 13, 'ninguém contudo com-ousadia falava acerca-de dele através-de o medo o judeus');
INSERT INTO verses VALUES (26402, 43, 7, 14, 'já porém o festa estando-no-meio subiu Iesous para o templo e ensinava');
INSERT INTO verses VALUES (26403, 43, 7, 15, 'admiravam-se portanto o judeus dizendo como este letras sei não tendo-aprendido');
INSERT INTO verses VALUES (26404, 43, 7, 16, 'respondeu portanto a-eles Iesous e disse o minha ensino não é minha mas o que-enviou me');
INSERT INTO verses VALUES (26405, 43, 7, 17, 'se alguém queira o vontade dele fazer conhecerá acerca-de o ensino qual-dos-dois de o de-Theos é ou eu de de-mim-mesmo falo');
INSERT INTO verses VALUES (26406, 43, 7, 18, 'o de si-mesmo falando o glória o própria busca o porém buscando o glória o tendo-enviado ele este verdadeiro é e injustiça em a ele não é');
INSERT INTO verses VALUES (26407, 43, 7, 19, 'não Moisés deu a-vós o lei e ninguém de vosso faz o lei quê me buscais matar');
INSERT INTO verses VALUES (26408, 43, 7, 20, 'respondeu o multidão Demônio tens quem te busca matar');
INSERT INTO verses VALUES (26409, 43, 7, 21, 'respondeu Iesous e disse a-eles um obra fiz e todos admirais');
INSERT INTO verses VALUES (26410, 43, 7, 22, 'através-de isto Moisés tem-dado a-vós o circuncisão não que de o Moisés é mas de o dos-pais e em no-sábado circuncidais homem');
INSERT INTO verses VALUES (26411, 43, 7, 23, 'se circuncisão recebe homem em no-sábado para que não seja-desatado o lei Moisés mim irais-vos que todo homem são fiz em no-sábado');
INSERT INTO verses VALUES (26412, 43, 7, 24, 'não julgais segundo aparência mas o justa juízo julgai');
INSERT INTO verses VALUES (26413, 43, 7, 25, 'diziam portanto alguns de o Jerosolimitas não este é o qual buscam matar');
INSERT INTO verses VALUES (26414, 43, 7, 26, 'e vê com-ousadia fala e nada a ele dizem não alguma-vez verdadeiramente conheceram o governantes que este é o Christos');
INSERT INTO verses VALUES (26415, 43, 7, 27, 'mas este sei de-onde é o porém Christos quando venha ninguém conhece de-onde é');
INSERT INTO verses VALUES (26416, 43, 7, 28, 'gritou portanto em o templo ensinando o Iesous e dizendo E-a-mim sei e sei de-onde sou e de de-mim-mesmo não tenho-vindo mas é verdadeiro o tendo-enviado me o qual vós não sei');
INSERT INTO verses VALUES (26417, 43, 7, 29, 'eu sei ele que de dele sou e-aquele me enviou');
INSERT INTO verses VALUES (26418, 43, 7, 30, 'Buscavam portanto ele prender e ninguém lançou-sobre sobre ele o mão que ainda-não tinha-vindo o hora dele');
INSERT INTO verses VALUES (26419, 43, 7, 31, 'de o multidão porém muitos creram para ele e diziam o Christos quando venha não maiores sinais fará o qual este fez');
INSERT INTO verses VALUES (26420, 43, 7, 32, 'Ouviram o fariseus o multidão murmurando acerca-de dele estas-coisas e enviaram o sumos-sacerdotes e o fariseus servos para que agarrem ele');
INSERT INTO verses VALUES (26421, 43, 7, 33, 'disse portanto o Iesous ainda tempo pouco com vosso sou e vou junto-a o o-que-enviou me');
INSERT INTO verses VALUES (26422, 43, 7, 34, 'buscareis me e não encontrareis e onde sou eu vós não podeis vir');
INSERT INTO verses VALUES (26423, 43, 7, 35, 'disseram portanto o judeus junto-a a-si-mesmos onde este está-para ir que nós não encontraremos ele não para o dispersão o gregos está-para ir e ensinar o Gregos');
INSERT INTO verses VALUES (26424, 43, 7, 36, 'quem é o palavra este o qual disse Buscareis me e não encontrareis e onde sou eu vós não podeis vir');
INSERT INTO verses VALUES (26425, 43, 7, 37, 'em porém o última dia o grande o festa estava-de-pé o Iesous e gritou dizendo se alguém tem-sede Venha para me e beba');
INSERT INTO verses VALUES (26426, 43, 7, 38, 'o crendo para me assim-como disse o escritura rios de o ventre dele fluirão água vivente');
INSERT INTO verses VALUES (26427, 43, 7, 39, 'isto porém disse acerca-de o do-espírito o qual estavam-para receber o tendo-crido para ele ainda-não pois era espírito que Iesous ainda-não foi-glorificado');
INSERT INTO verses VALUES (26428, 43, 7, 40, 'de o multidão portanto ouvindo o palavras destes diziam Este é verdadeiramente o profeta');
INSERT INTO verses VALUES (26429, 43, 7, 41, 'outros diziam Este é o Christos o porém diziam não pois de o Galileia o Christos vem');
INSERT INTO verses VALUES (26430, 43, 7, 42, 'não o escritura disse que de o semente Davi e de Belém o aldeia onde era Davi vem o Christos');
INSERT INTO verses VALUES (26431, 43, 7, 43, 'divisão portanto aconteceu em o à-multidão através-de ele');
INSERT INTO verses VALUES (26432, 43, 7, 44, 'alguns porém queriam de deles prender ele mas ninguém lançou-sobre sobre ele o mãos');
INSERT INTO verses VALUES (26433, 43, 7, 45, 'vieram portanto o servos junto-a o sumos-sacerdotes e Fariseus e disseram a-eles aqueles através-de quê não conduzistes ele');
INSERT INTO verses VALUES (26434, 43, 7, 46, 'responderam o servos Nunca falou assim homem como este fala o homem');
INSERT INTO verses VALUES (26435, 43, 7, 47, 'responderam portanto a-eles o fariseus não e vós tendes-sido-enganados');
INSERT INTO verses VALUES (26436, 43, 7, 48, 'não alguém de o governantes creu para ele ou de o fariseus');
INSERT INTO verses VALUES (26437, 43, 7, 49, 'mas o multidão este o não conhecendo o lei malditos são');
INSERT INTO verses VALUES (26438, 43, 7, 50, 'diz Nicodemos junto-a eles o vindo junto-a ele antes um sendo de deles');
INSERT INTO verses VALUES (26439, 43, 7, 51, 'não o lei nosso julga o homem se não ouça primeiro de-junto-de dele e conheça quê faz');
INSERT INTO verses VALUES (26440, 43, 7, 52, 'responderam e disseram a ele não e tu de o Galileia és Examina e vê que de o Galileia profeta não é-levantado');
INSERT INTO verses VALUES (26441, 43, 7, 53, 'e foi cada-um para o casa dele');
INSERT INTO chapters VALUES (1005, 43, 8, 59);
INSERT INTO verses VALUES (26442, 43, 8, 1, 'Iesous porém foi para o monte o oliveiras');
INSERT INTO verses VALUES (26443, 43, 8, 2, 'Madrugada porém novamente apresentou-se para o templo e todo o povo vinha junto-a ele e sentando-se ensinava eles');
INSERT INTO verses VALUES (26444, 43, 8, 3, 'conduzem porém o escribas e o fariseus junto-a ele mulher em adultério tendo-sido-apanhada e tendo-colocado-de-pé ela em meio');
INSERT INTO verses VALUES (26445, 43, 8, 4, 'dizem a ele Mestre esta o mulher foi-alcançado em-flagrante sendo-adulterada');
INSERT INTO verses VALUES (26446, 43, 8, 5, 'em porém o lei Moisés a-nós ordenou o tais ser-apedrejado tu portanto quê dizes');
INSERT INTO verses VALUES (26447, 43, 8, 6, 'isto porém diziam tentando ele para que tenham acusar dele o porém Iesous abaixo tendo-se-inclinado o dedo escrevia para o terra');
INSERT INTO verses VALUES (26448, 43, 8, 7, 'como porém permaneciam Perguntando ele tendo-se-erguido disse junto-a eles o sem-pecado vosso primeiro o pedra sobre a-ela lance');
INSERT INTO verses VALUES (26449, 43, 8, 8, 'e novamente abaixo tendo-se-inclinado escrevia para o terra');
INSERT INTO verses VALUES (26450, 43, 8, 9, 'o porém ouvindo e sob o consciência sendo-repreendidos saíam um cada-um tendo-começado de o anciãos até o últimas e foi-deixado só o Iesous e o mulher em meio Estando-de-pé');
INSERT INTO verses VALUES (26451, 43, 8, 10, 'tendo-se-erguido porém o Iesous e ninguém tendo-contemplado exceto o mulher disse a-ela o mulher onde são aqueles o acusadores teu ninguém te condenou');
INSERT INTO verses VALUES (26452, 43, 8, 11, 'o porém disse ninguém kyrie disse porém a-ela o Iesous nem eu te condeno vai e não-mais peca');
INSERT INTO verses VALUES (26453, 43, 8, 12, 'novamente portanto a-eles falou o Iesous dizendo Eu sou o luz o do-mundo o seguindo a-mim não não ande em o trevas mas terá o luz o da-vida');
INSERT INTO verses VALUES (26454, 43, 8, 13, 'disseram portanto a ele o fariseus tu acerca-de ti-mesmo testemunhas o testemunho teu não é verdadeiro');
INSERT INTO verses VALUES (26455, 43, 8, 14, 'respondeu Iesous e disse a-eles Mesmo-se eu testemunho acerca-de de-mim-mesmo verdadeiro é o testemunho meu que sei de-onde vieram e onde vou vós porém não sei de-onde venho ou onde vou');
INSERT INTO verses VALUES (26456, 43, 8, 15, 'vós segundo o carne julgais eu não julgo a-ninguém');
INSERT INTO verses VALUES (26457, 43, 8, 16, 'e se julgo porém eu o julgamento o minha verdadeira é que só não sou mas eu e o tendo-enviado me');
INSERT INTO verses VALUES (26458, 43, 8, 17, 'e em o lei porém o vosso está-escrito que dois dos-homens o testemunho verdadeiro é');
INSERT INTO verses VALUES (26459, 43, 8, 18, 'eu sou o testemunhando acerca-de de-mim-mesmo e testifica acerca-de mim o tendo-enviado me Pai');
INSERT INTO verses VALUES (26460, 43, 8, 19, 'diziam portanto a ele Onde é o Pai teu respondeu Iesous Nem mim sei nem o Pai meu se mim sei e o Pai meu partícula-condicional sei');
INSERT INTO verses VALUES (26461, 43, 8, 20, 'estas-coisas o palavras falou em o tesouro ensinando em o templo e ninguém prendeu ele que ainda-não tinha-vindo o hora dele');
INSERT INTO verses VALUES (26462, 43, 8, 21, 'disse portanto novamente a-eles eu vou e buscareis me e em o pecado vosso morrereis onde eu vou vós não podeis vir');
INSERT INTO verses VALUES (26463, 43, 8, 22, 'diziam portanto o judeus Acaso matará si-mesmo que diz onde eu vou vós não podeis vir');
INSERT INTO verses VALUES (26464, 43, 8, 23, 'e dizia a-eles vós de o abaixo sois eu de o acima sou vós de deste o do-mundo sois eu não sou de o do-mundo deste');
INSERT INTO verses VALUES (26465, 43, 8, 24, 'disseram portanto a-vós que morrereis em o pecados vosso se pois não creiais que eu sou morrereis em o pecados vosso');
INSERT INTO verses VALUES (26466, 43, 8, 25, 'diziam portanto a ele tu quem és disse a-eles o Iesous o início o qual algo e falo a-vós');
INSERT INTO verses VALUES (26467, 43, 8, 26, 'muitas-coisas tenho acerca-de vosso falar e julgar mas o tendo-enviado me verdadeiro é e-eu o qual ouvi de dele estas-coisas falo para o mundo');
INSERT INTO verses VALUES (26468, 43, 8, 27, 'não conheceram que o Pai a-eles dizia');
INSERT INTO verses VALUES (26469, 43, 8, 28, 'disse portanto o Iesous quando Exalteis o Filho o do-homem então conhecereis que eu sou e de de-mim-mesmo faço nada mas assim-como ensinou me o Pai estas-coisas falo');
INSERT INTO verses VALUES (26470, 43, 8, 29, 'e o tendo-enviado me com mim é não deixou me somente que eu o agradáveis a ele faço sempre');
INSERT INTO verses VALUES (26471, 43, 8, 30, 'estas-coisas dele falando muitos creram para ele');
INSERT INTO verses VALUES (26472, 43, 8, 31, 'Dizia portanto o Iesous junto-a o tendo-crido a ele judeus se vós permaneçais em o em-palavra o meu verdadeiramente discípulos meu sois');
INSERT INTO verses VALUES (26473, 43, 8, 32, 'e conhecereis o verdade e o verdade libertará vos');
INSERT INTO verses VALUES (26474, 43, 8, 33, 'responderam junto-a ele Semente Abraão somos e a-ninguém temos-servido jamais como tu dizes que Livres sereis');
INSERT INTO verses VALUES (26475, 43, 8, 34, 'respondeu a-eles o Iesous Amém amém digo a-vós que todo o fazendo o pecado servo é o do-pecado');
INSERT INTO verses VALUES (26476, 43, 8, 35, 'o porém servo não permanece em o casa para o eternidade o Filho permanece para o eternidade');
INSERT INTO verses VALUES (26477, 43, 8, 36, 'se portanto o Filho vos liberte verdadeiramente livres sereis');
INSERT INTO verses VALUES (26478, 43, 8, 37, 'sei que semente Abraão sois mas buscais me matar que o palavra o meu não tem-espaço em a-vós');
INSERT INTO verses VALUES (26479, 43, 8, 38, 'o qual eu tenho-visto de-junto-de o Pai falo e vós portanto o qual ouvistes de-junto-de o do-Pai fazei');
INSERT INTO verses VALUES (26480, 43, 8, 39, 'responderam e disseram a ele o Pai nosso Abraão é diz a-eles o Iesous se filhos o Abraão sois o obra o Abraão fazei');
INSERT INTO verses VALUES (26481, 43, 8, 40, 'agora porém buscais me matar homem o qual o verdade a-vós tenho-falado o qual ouvi de-junto-de o de-Theos isto Abraão não fez');
INSERT INTO verses VALUES (26482, 43, 8, 41, 'vós fazei o obra o do-Pai vosso disseram a ele nós de imoralidade não fomos-gerados um Pai temos o Theos');
INSERT INTO verses VALUES (26483, 43, 8, 42, 'disse a-eles o Iesous se o Theos Pai vosso era amáveis partícula-condicional a-mim eu pois de o de-Theos saíram e venho nem pois de de-mim-mesmo tenho-vindo mas aquele me enviou');
INSERT INTO verses VALUES (26484, 43, 8, 43, 'através-de quê o fala o minha não sabeis que não podeis ouvir o palavra o meu');
INSERT INTO verses VALUES (26485, 43, 8, 44, 'vós de o do-Pai o diabo sois e o desejos o do-Pai vosso quereis fazer aquele homicida era de princípio e em o verdade não Tem-permanecido-de-pé que não é verdade em a ele quando fale o mentira de o próprios fala que mentiroso é e o Pai dele');
INSERT INTO verses VALUES (26486, 43, 8, 45, 'eu porém que o verdade digo não credes a-mim');
INSERT INTO verses VALUES (26487, 43, 8, 46, 'quem de vosso repreende me acerca-de do-pecado se verdade digo através-de quê vós não credes a-mim');
INSERT INTO verses VALUES (26488, 43, 8, 47, 'o sendo de o de-Theos o palavras o de-Theos ouve através-de isto vós não ouvi que de o de-Theos não sois');
INSERT INTO verses VALUES (26489, 43, 8, 48, 'Responderam o judeus e disseram a ele não bem dizemos nós que Samaritano és tu e demônio tens');
INSERT INTO verses VALUES (26490, 43, 8, 49, 'respondeu Iesous eu demônio não tenho mas honro o Pai meu e vós desonrais me');
INSERT INTO verses VALUES (26491, 43, 8, 50, 'eu porém não busco o glória meu é o buscando e julgando');
INSERT INTO verses VALUES (26492, 43, 8, 51, 'amém amém digo a-vós se alguém o meu palavra guarde morte não não contemple para o eternidade');
INSERT INTO verses VALUES (26493, 43, 8, 52, 'disseram a ele o judeus agora temos-conhecido que demônio tens Abraão morreu e o profetas e tu dizes se alguém o palavra meu guarde não não prove da-morte para o eternidade');
INSERT INTO verses VALUES (26494, 43, 8, 53, 'não tu maior és o do-Pai nosso Abraão qualquer-que morreu e o profetas morreram quem a-ti-mesmo fazes');
INSERT INTO verses VALUES (26495, 43, 8, 54, 'respondeu Iesous se eu glorificarei a-mim-mesmo o glória meu nada é é o Pai meu o glorificando me o qual vós dizeis que Theos nosso é');
INSERT INTO verses VALUES (26496, 43, 8, 55, 'e não conhecestes ele eu porém sei ele e-se diga que não sei ele serei semelhante a-vós mentiroso mas sei ele e o palavra dele guardo');
INSERT INTO verses VALUES (26497, 43, 8, 56, 'Abraão o Pai vosso exultou para que veja o dia o minha e viu e alegrou-se');
INSERT INTO verses VALUES (26498, 43, 8, 57, 'disseram portanto o judeus junto-a ele Cinquenta anos ainda-não tens e Abraão tens-visto');
INSERT INTO verses VALUES (26499, 43, 8, 58, 'disse a-eles Iesous Amém amém digo a-vós antes-de Abraão tornar-se eu sou');
INSERT INTO verses VALUES (26500, 43, 8, 59, 'levantaram portanto pedras para que lancem sobre ele Iesous porém escondeu-se e saiu de o do-templo');
INSERT INTO chapters VALUES (1006, 43, 9, 41);
INSERT INTO verses VALUES (26501, 43, 9, 1, 'e passando viu homem cego de nascimento');
INSERT INTO verses VALUES (26502, 43, 9, 2, 'e perguntaram ele o discípulos dele dizendo Rabi quem pecou este ou o pais dele para que cego seja-gerado');
INSERT INTO verses VALUES (26503, 43, 9, 3, 'respondeu Iesous nem este pecou nem o pais dele mas para que seja-manifestada o obra o de-Theos em a ele');
INSERT INTO verses VALUES (26504, 43, 9, 4, 'nos é necessário trabalhar o obra o que-enviou me até dia é vem noite quando ninguém pode trabalhar');
INSERT INTO verses VALUES (26505, 43, 9, 5, 'quando em o ao-mundo Ômega luz sou o do-mundo');
INSERT INTO verses VALUES (26506, 43, 9, 6, 'estas-coisas dizendo Cuspiu ao-chão e fez barro de o de-cuspe e pôs-sobre dele o barro sobre o olhos');
INSERT INTO verses VALUES (26507, 43, 9, 7, 'e disse a ele Vai lavar para o tanque o Siloé o qual é-interpretado Tendo-sido-enviado partiu portanto e lavou e veio vendo');
INSERT INTO verses VALUES (26508, 43, 9, 8, 'o portanto vizinhos e o observando ele o antes que mendigo era diziam não este é o sentado e mendigando');
INSERT INTO verses VALUES (26509, 43, 9, 9, 'outros diziam que Este é outros diziam não mas semelhante a ele é aquele dizia que Eu sou');
INSERT INTO verses VALUES (26510, 43, 9, 10, 'diziam portanto a ele como portanto foram-abertas teu o olhos');
INSERT INTO verses VALUES (26511, 43, 9, 11, 'respondeu aquele o homem o chamado Iesous barro fez e ungiu-sobre meu o olhos e disse a-mim que Vai para o Siloé e lavar partindo portanto e tendo-se-lavado recuperei-a-vista');
INSERT INTO verses VALUES (26512, 43, 9, 12, 'e disseram a ele onde é aquele diz não sei');
INSERT INTO verses VALUES (26513, 43, 9, 13, 'Conduzem ele junto-a o Fariseus o alguma-vez cego');
INSERT INTO verses VALUES (26514, 43, 9, 14, 'era porém sábado em o qual dia o barro fez o Iesous e abriu dele o olhos');
INSERT INTO verses VALUES (26515, 43, 9, 15, 'novamente portanto perguntavam ele e o fariseus como olhou-para-cima o porém disse a-eles Lodo colocou-sobre meu sobre o olhos e lavei e vejo');
INSERT INTO verses VALUES (26516, 43, 9, 16, 'diziam portanto de o fariseus alguns não é este de-junto-de de-Theos o homem que o sábado não guarda outros diziam como pode homem pecador tais-coisas sinais fazer e divisão era em a-eles');
INSERT INTO verses VALUES (26517, 43, 9, 17, 'dizem portanto o cego novamente quê tu dizes acerca-de dele que abriu teu o olhos o porém disse que Profeta é');
INSERT INTO verses VALUES (26518, 43, 9, 18, 'não creram portanto o judeus acerca-de dele que era cego e olhou-para-cima até de-quem Chamaram-em-voz-alta o pais dele o tendo-recuperado-a-visão');
INSERT INTO verses VALUES (26519, 43, 9, 19, 'e perguntaram eles dizendo Este é o Filho vosso o qual vós dizeis que cego foi-gerado como portanto vê agora');
INSERT INTO verses VALUES (26520, 43, 9, 20, 'responderam portanto o pais dele e disseram sei que este é o Filho nosso e que cego foi-gerado');
INSERT INTO verses VALUES (26521, 43, 9, 21, 'como porém agora vê não sei ou quem abriu dele o olhos nós não sei ele Perguntai estatura tem ele acerca-de si-mesmo falará');
INSERT INTO verses VALUES (26522, 43, 9, 22, 'estas-coisas disseram o pais dele que temiam o judeus já pois tinham-combinado o judeus para que se alguém ele confesse Christon expulso-da-sinagoga aconteça');
INSERT INTO verses VALUES (26523, 43, 9, 23, 'através-de isto o pais dele disseram que Estatura tem ele perguntai');
INSERT INTO verses VALUES (26524, 43, 9, 24, 'Clamaram portanto o homem de segunda o qual era cego e disseram a ele Dá glória o a-Theos nós sei que este o homem pecador é');
INSERT INTO verses VALUES (26525, 43, 9, 25, 'respondeu portanto aquele se pecador é não sei um sei que cego sendo agora vejo');
INSERT INTO verses VALUES (26526, 43, 9, 26, 'disseram portanto a ele quê fez a-ti como abriu teu o olhos');
INSERT INTO verses VALUES (26527, 43, 9, 27, 'respondeu a-eles disseram a-vós já e não ouvistes quê novamente quereis ouvir não e vós quereis dele discípulos tornar-se');
INSERT INTO verses VALUES (26528, 43, 9, 28, 'e injuriaram ele e disseram tu discípulo és daquele nós porém o de-Moisés somos discípulos');
INSERT INTO verses VALUES (26529, 43, 9, 29, 'nós sei que Moisés tem-falado o Theos este porém não sei de-onde é');
INSERT INTO verses VALUES (26530, 43, 9, 30, 'respondeu o homem e disse a-eles em neste pois o maravilhoso é que vós não sei de-onde é e abriu meu o olhos');
INSERT INTO verses VALUES (26531, 43, 9, 31, 'sei que o Theos dos-pecadores não ouve mas se alguém piedoso-a-Theos seja e o vontade dele faça deste ouve');
INSERT INTO verses VALUES (26532, 43, 9, 32, 'de o eternidade não foi-ouvido que abriu alguém olhos cego tendo-sido-gerado');
INSERT INTO verses VALUES (26533, 43, 9, 33, 'se não era este de-junto-de de-Theos não podia fazer nada');
INSERT INTO verses VALUES (26534, 43, 9, 34, 'responderam e disseram a ele em pecados tu foste-gerado todo e tu ensinas nos e expulsaram ele fora');
INSERT INTO verses VALUES (26535, 43, 9, 35, 'ouviu Iesous que expulsaram ele fora e encontrando ele disse tu crês para o Filho o do-homem');
INSERT INTO verses VALUES (26536, 43, 9, 36, 'respondeu aquele e disse e quem é Kyrie para que creia para ele');
INSERT INTO verses VALUES (26537, 43, 9, 37, 'disse a ele o Iesous e tens-visto ele e o falando com teu aquele é');
INSERT INTO verses VALUES (26538, 43, 9, 38, 'o porém disse creio Kyrie e adorou a ele');
INSERT INTO verses VALUES (26539, 43, 9, 39, 'e disse o Iesous para julgamento eu para o mundo este vieram para que o não vendo vejam e o vendo cegos tornem-se');
INSERT INTO verses VALUES (26540, 43, 9, 40, 'ouviram de o fariseus estas-coisas o com dele sendo e disseram a ele não e nós cegos somos');
INSERT INTO verses VALUES (26541, 43, 9, 41, 'disse a-eles o Iesous se cegos éreis não partícula-condicional tínheis pecado agora porém dizeis que vemos o pecado vosso permanece');
INSERT INTO chapters VALUES (1007, 43, 10, 42);
INSERT INTO verses VALUES (26542, 43, 10, 1, 'Amém amém digo a-vós o não entrando através-de o porta para o pátio o ovelhas mas subindo por-outro-lugar aquele ladrão é e salteador');
INSERT INTO verses VALUES (26543, 43, 10, 2, 'o porém entrando através-de o porta pastor é o ovelhas');
INSERT INTO verses VALUES (26544, 43, 10, 3, 'neste o porteiro abre e o ovelhas o voz dele ouve e o próprias ovelhas chama segundo nome e conduz-para-fora elas');
INSERT INTO verses VALUES (26545, 43, 10, 4, 'quando o próprias todas-as-coisas expulse diante deles vai e o ovelhas a ele segue que sei o voz dele');
INSERT INTO verses VALUES (26546, 43, 10, 5, 'estranho porém não não seguirão mas fugirão de dele que não sei o estranhos o voz');
INSERT INTO verses VALUES (26547, 43, 10, 6, 'esta o provérbio disse a-eles o Iesous aqueles porém não conheceram quem era o qual falava a-eles');
INSERT INTO verses VALUES (26548, 43, 10, 7, 'disse portanto novamente o Iesous Amém amém digo a-vós que eu sou o porta o ovelhas');
INSERT INTO verses VALUES (26549, 43, 10, 8, 'todos quanto vieram antes-de mim ladrões são e salteadores mas não ouviram deles o ovelhas');
INSERT INTO verses VALUES (26550, 43, 10, 9, 'eu sou o porta através-de mim se alguém entre será-salvo e entrará e sairá e pasto encontrará');
INSERT INTO verses VALUES (26551, 43, 10, 10, 'o ladrão não vem se não para que furte e sacrifique e destrua eu vieram para que vida tenham e abundante tenham');
INSERT INTO verses VALUES (26552, 43, 10, 11, 'eu sou o pastor o bom o pastor o belo o alma dele põe em-favor-de o ovelhas');
INSERT INTO verses VALUES (26553, 43, 10, 12, 'o assalariado e não sendo pastor o qual não é o ovelhas próprias contempla o lobo o-que-vem e perdoa o ovelhas e foge e o lobo arrebata eles e dispersa');
INSERT INTO verses VALUES (26554, 43, 10, 13, 'que assalariado é e não importa a ele acerca-de o ovelhas');
INSERT INTO verses VALUES (26555, 43, 10, 14, 'eu sou o pastor o bom e conheço o minhas-coisas e conhecem me o minhas');
INSERT INTO verses VALUES (26556, 43, 10, 15, 'assim-como conhece me o Pai e-eu conheço o Pai e o alma meu ponho em-favor-de o ovelhas');
INSERT INTO verses VALUES (26557, 43, 10, 16, 'e outras-coisas ovelhas tenho o qual não é de o pátio desta e-aquelas é necessário me conduzir e o voz meu ouvirão e acontecerá uma rebanho um pastor');
INSERT INTO verses VALUES (26558, 43, 10, 17, 'através-de isto me o Pai ama que eu ponho o alma meu para que novamente tome ela');
INSERT INTO verses VALUES (26559, 43, 10, 18, 'ninguém levantou ela de mim mas eu ponho ela de de-mim-mesmo autoridade tenho pôr ela e autoridade tenho novamente receber ela esta o mandamento receberam de-junto-de o Pai meu');
INSERT INTO verses VALUES (26560, 43, 10, 19, 'Divisão novamente aconteceu em o judeus através-de o palavras estes');
INSERT INTO verses VALUES (26561, 43, 10, 20, 'diziam porém muitos de deles Demônio tem e enlouquece quê dele ouvi');
INSERT INTO verses VALUES (26562, 43, 10, 21, 'outros diziam estas-coisas o palavras não é sendo-endemoninhado não demônio pode cegos olhos abrir');
INSERT INTO verses VALUES (26563, 43, 10, 22, 'aconteceu então o inauguração em o em-Jerusalém tempestade era');
INSERT INTO verses VALUES (26564, 43, 10, 23, 'e andava o Iesous em o templo em o pórtico o Salomão');
INSERT INTO verses VALUES (26565, 43, 10, 24, 'cercaram portanto ele o judeus e diziam a ele até quando o alma nosso levantas se tu és o Christos dize a-nós com-ousadia');
INSERT INTO verses VALUES (26566, 43, 10, 25, 'respondeu a-eles o Iesous disseram a-vós e não credes o obra o qual eu faço em o em-nome o Pai meu estas-coisas testifica acerca-de mim');
INSERT INTO verses VALUES (26567, 43, 10, 26, 'mas vós não credes que não sois de o ovelhas o meus');
INSERT INTO verses VALUES (26568, 43, 10, 27, 'o ovelhas o minhas-coisas o voz meu ouvem e-eu conheço elas e seguem a-mim');
INSERT INTO verses VALUES (26569, 43, 10, 28, 'e-eu dou a-eles vida eterno e não não pereçam para o eternidade e não arrebatará alguém elas de o mão meu');
INSERT INTO verses VALUES (26570, 43, 10, 29, 'o Pai meu o qual deu a-mim todos maior é e ninguém pode arrebatar de o da-mão o do-Pai');
INSERT INTO verses VALUES (26571, 43, 10, 30, 'eu e o Pai um somos');
INSERT INTO verses VALUES (26572, 43, 10, 31, 'Carregaram novamente pedras o judeus para que apedrejem ele');
INSERT INTO verses VALUES (26573, 43, 10, 32, 'respondeu a-eles o Iesous muitos obra Mostrei a-vós boas de o do-Pai através-de qual deles obra mim apedrejais');
INSERT INTO verses VALUES (26574, 43, 10, 33, 'responderam a ele o judeus acerca-de bom obra não apedrejamos te mas acerca-de blasfêmias e que tu homem sendo fazes a-ti-mesmo Theos');
INSERT INTO verses VALUES (26575, 43, 10, 34, 'respondeu a-eles o Iesous não é escrito em o lei vosso que eu disse theoi sois');
INSERT INTO verses VALUES (26576, 43, 10, 35, 'se aqueles disse theoi junto-a o qual o palavra o de-Theos aconteceu e não pode ser-solto o escritura');
INSERT INTO verses VALUES (26577, 43, 10, 36, 'o qual o Pai Santificou e enviou para o mundo vós dizeis que Blasfemas que disseram Filho o de-Theos sou');
INSERT INTO verses VALUES (26578, 43, 10, 37, 'se não faço o obra o do-Pai meu não credes a-mim');
INSERT INTO verses VALUES (26579, 43, 10, 38, 'se porém faço e-se mim não creiais o obra credes para que conheçais e conheçais que em mim o Pai e-eu em o Pai');
INSERT INTO verses VALUES (26580, 43, 10, 39, 'Buscavam portanto ele novamente prender e saiu de o da-mão deles');
INSERT INTO verses VALUES (26581, 43, 10, 40, 'e partiu novamente além o Jordão para o lugar onde era João o primeiro batizando e permanecia ali');
INSERT INTO verses VALUES (26582, 43, 10, 41, 'e muitos vieram junto-a ele e diziam que João por-um-lado sinal fez nada todas-as-coisas porém quanto disse João acerca-de deste verdadeiras era');
INSERT INTO verses VALUES (26583, 43, 10, 42, 'e muitos creram para ele ali');
INSERT INTO chapters VALUES (1008, 43, 11, 57);
INSERT INTO verses VALUES (26584, 43, 11, 1, 'era e/mas alguém fracos Lázaro de Betânia de o aldeia Maria e Marta o irmã dela');
INSERT INTO verses VALUES (26585, 43, 11, 2, 'era porém Maria o tendo-ungido o Kyrion ungüento e tendo-enxugado o pés dele o cabelos dela o qual o irmão Lázaro estava-doente');
INSERT INTO verses VALUES (26586, 43, 11, 3, 'enviaram portanto o irmãs junto-a ele dizendo Kyrie vê o qual amas está-fraco');
INSERT INTO verses VALUES (26587, 43, 11, 4, 'ouvindo porém o Iesous disse esta o fraqueza não é junto-a morte mas em-favor-de o da-glória o de-Theos para que seja-glorificado o Filho o de-Theos através-de dela');
INSERT INTO verses VALUES (26588, 43, 11, 5, 'amava porém o Iesous o Marta e o irmã dela e o Lázaro');
INSERT INTO verses VALUES (26589, 43, 11, 6, 'como portanto ouviu que está-fraco então por-um-lado permaneceu em o qual era no-lugar dois do-dia');
INSERT INTO verses VALUES (26590, 43, 11, 7, 'depois com isto diz o discípulos Vamos para o Judeia novamente');
INSERT INTO verses VALUES (26591, 43, 11, 8, 'dizem a ele o discípulos Rabi agora buscavam te apedrejar o judeus e novamente vais ali');
INSERT INTO verses VALUES (26592, 43, 11, 9, 'respondeu Iesous Não doze hora são o do-dia se alguém ande em o dia não tropeça que o luz o do-mundo deste vê');
INSERT INTO verses VALUES (26593, 43, 11, 10, 'se e/mas alguém ande em o noite tropeça que o luz não é em a ele');
INSERT INTO verses VALUES (26594, 43, 11, 11, 'estas-coisas disse e com isto diz a-eles Lázaro o amigo nosso tem-adormecido mas vou para que despertarei ele');
INSERT INTO verses VALUES (26595, 43, 11, 12, 'disseram portanto o discípulos a ele Kyrie se tem-adormecido será-salvo');
INSERT INTO verses VALUES (26596, 43, 11, 13, 'tinha-dito porém o Iesous acerca-de o da-morte dele aqueles porém glorificaram que acerca-de o sono o sono diz');
INSERT INTO verses VALUES (26597, 43, 11, 14, 'então portanto disse a-eles o Iesous com-ousadia Lázaro morreu');
INSERT INTO verses VALUES (26598, 43, 11, 15, 'e alegro-me através-de vos para que creiais que não eu-era ali mas vamos junto-a ele');
INSERT INTO verses VALUES (26599, 43, 11, 16, 'disse portanto Tomé o chamado Dídimo o co-discípulos Vamos e nós para que morramos com dele');
INSERT INTO verses VALUES (26600, 43, 11, 17, 'tendo-vindo portanto o Iesous encontrou ele quatro já do-dia tendo em o sepulcro');
INSERT INTO verses VALUES (26601, 43, 11, 18, 'era porém Betânia perto o Jerusalém como de estádios quinze');
INSERT INTO verses VALUES (26602, 43, 11, 19, 'muitos porém de o judeus tinham-vindo junto-a o Marta e Maria para que consolem elas acerca-de o do-irmão');
INSERT INTO verses VALUES (26603, 43, 11, 20, 'o portanto Marta como ouviu que Iesous vem encontrou a ele Maria porém em o na-casa sentava-se');
INSERT INTO verses VALUES (26604, 43, 11, 21, 'disse portanto o Marta junto-a Iesous Kyrie se fosses aqui não partícula-condicional morreu o irmão meu');
INSERT INTO verses VALUES (26605, 43, 11, 22, 'e agora sei que quanto partícula-condicional peça o Theos dará a-ti o Theos');
INSERT INTO verses VALUES (26606, 43, 11, 23, 'diz a-ela o Iesous Levantar-se-á o irmão teu');
INSERT INTO verses VALUES (26607, 43, 11, 24, 'diz a ele o Marta sei que ressuscitará em o ressurreição em o última dia');
INSERT INTO verses VALUES (26608, 43, 11, 25, 'disse a-ela o Iesous Eu sou o ressurreição e o vida o crendo para mim e-se morra viverá');
INSERT INTO verses VALUES (26609, 43, 11, 26, 'e todo o vivendo e crendo para mim não não morra para o eternidade crês isto');
INSERT INTO verses VALUES (26610, 43, 11, 27, 'diz a ele Sim Kyrie eu tenho-crido que tu és o Christos o Filho o de-Theos o para o mundo o-que-vem');
INSERT INTO verses VALUES (26611, 43, 11, 28, 'e isto tendo-dito partiu e chamou Maria o irmã dela secretamente tendo-dito o Mestre está-presente e chama te');
INSERT INTO verses VALUES (26612, 43, 11, 29, 'aquela porém como ouviu é-levantado rapidamente e vinha junto-a ele');
INSERT INTO verses VALUES (26613, 43, 11, 30, 'ainda-não porém tinha-vindo o Iesous para o aldeia mas era ainda em o no-lugar onde encontrou a ele o Marta');
INSERT INTO verses VALUES (26614, 43, 11, 31, 'o portanto judeus o sendo com dela em o casa e consolando ela vendo o Maria que rapidamente levantou-se e saiu seguiram a-ela tendo-parecido que vai para o túmulo para que chore ali');
INSERT INTO verses VALUES (26615, 43, 11, 32, 'o portanto Maria como veio onde era Iesous vendo ele caiu dele junto-a o pés dizendo a ele Kyrie se fosses aqui não se meu morreu o irmão');
INSERT INTO verses VALUES (26616, 43, 11, 33, 'Iesous portanto como viu ela chorando e o tendo-se-reunido a-ela judeus chorando repreendeu-severamente o espírito e Perturbou a-si-mesmo');
INSERT INTO verses VALUES (26617, 43, 11, 34, 'e disse onde tendes-posto ele dizem a ele Kyrie vem e vê');
INSERT INTO verses VALUES (26618, 43, 11, 35, 'chorou o Iesous');
INSERT INTO verses VALUES (26619, 43, 11, 36, 'diziam portanto o judeus Vê como amava ele');
INSERT INTO verses VALUES (26620, 43, 11, 37, 'alguns porém de deles disseram não podia este o abrindo o olhos o cego fazer para que e este não morra');
INSERT INTO verses VALUES (26621, 43, 11, 38, 'Iesous portanto novamente repreendendo-severamente em si-mesmo vem para o túmulo era porém caverna e pedra pressionava-sobre sobre a ele');
INSERT INTO verses VALUES (26622, 43, 11, 39, 'diz o Iesous Levantai o pedra diz a ele o irmã o tendo-morrido Marta Kyrie já cheira-mal de-quatro-dias pois é');
INSERT INTO verses VALUES (26623, 43, 11, 40, 'diz a-ela o Iesous não dize a-ti que se creias verás o glória o de-Theos');
INSERT INTO verses VALUES (26624, 43, 11, 41, 'levantaram portanto o pedra o porém Iesous levantou o olhos acima e disse Pai dou-graças a-ti que Ouviste meu');
INSERT INTO verses VALUES (26625, 43, 11, 42, 'eu porém sei que sempre meu ouves mas através-de o multidão o tendo-estado-ao-redor disseram para que creiam que tu me enviaste');
INSERT INTO verses VALUES (26626, 43, 11, 43, 'e estas-coisas dizendo com-voz grande clamou Lázaro vem fora');
INSERT INTO verses VALUES (26627, 43, 11, 44, 'saiu o tendo-morrido amarrado o pés e o mãos faixas e o aparência dele lenço tinha-sido-amarrado-ao-redor diz a-eles o Iesous Desatai ele e deixai ele ir');
INSERT INTO verses VALUES (26628, 43, 11, 45, 'muitos portanto de o judeus o vindo junto-a o Maria e tendo-contemplado o qual fez creram para ele');
INSERT INTO verses VALUES (26629, 43, 11, 46, 'alguns porém de deles foram junto-a o Fariseus e disseram a-eles o qual fez Iesous');
INSERT INTO verses VALUES (26630, 43, 11, 47, 'Reuniram portanto o sumos-sacerdotes e o fariseus sinédrio e diziam quê fazemos que este o homem muitas-coisas faz sinais');
INSERT INTO verses VALUES (26631, 43, 11, 48, 'se deixemos ele assim todos crerão para ele e virão o Romanos e levantarão nosso e o lugar e o nação');
INSERT INTO verses VALUES (26632, 43, 11, 49, 'um e/mas alguém de deles Caifás sumo-sacerdote sendo o ano daquele disse a-eles vós não sei nada');
INSERT INTO verses VALUES (26633, 43, 11, 50, 'nem considerai que convém a-vós para que um homem morra em-favor-de o povo e não todo o nação pereça');
INSERT INTO verses VALUES (26634, 43, 11, 51, 'isto porém de si-mesmo não disse mas sumo-sacerdote sendo o ano daquele profetizou que estava-prestes Iesous morrer em-favor-de o nação');
INSERT INTO verses VALUES (26635, 43, 11, 52, 'e não em-favor-de o nação somente mas para que e o filhos o de-Theos o tendo-sido-dispersos reúna para um');
INSERT INTO verses VALUES (26636, 43, 11, 53, 'de daquela portanto o do-dia deliberaram para que matem ele');
INSERT INTO verses VALUES (26637, 43, 11, 54, 'o portanto Iesous não-mais com-ousadia andava em o judeus mas partiu dali para o região perto o deserto para Efraim chamada cidade e-ali permaneceu com o discípulos');
INSERT INTO verses VALUES (26638, 43, 11, 55, 'era porém perto o páscoa o judeus e subiram muitos para Jerusalém de o região antes-de o páscoa para que purifiquem a-si-mesmos');
INSERT INTO verses VALUES (26639, 43, 11, 56, 'buscavam portanto o Iesous e diziam com uns-aos-outros em o templo Tendo-permanecido-de-pé quê parece a-vós que não não venha para o festa');
INSERT INTO verses VALUES (26640, 43, 11, 57, 'tinham-dado porém o sumos-sacerdotes e o fariseus mandamentos para que se alguém conheça onde é informe para-que agarrem ele');
INSERT INTO chapters VALUES (1009, 43, 12, 50);
INSERT INTO verses VALUES (26641, 43, 12, 1, 'o portanto Iesous antes-de seis dos-dias o páscoa veio para Betânia onde era Lázaro o qual ressuscitou de mortos Iesous');
INSERT INTO verses VALUES (26642, 43, 12, 2, 'fizeram portanto a ele ceia ali e o Marta servia o porém Lázaro um era de o reclinados com a ele');
INSERT INTO verses VALUES (26643, 43, 12, 3, 'o portanto Maria tomando libra perfume nardo genuína muito-precioso ungiu o pés o Iesous e enxugou o cabelos dela o pés dele o porém casa foi-cumprido de o cheiro o perfume');
INSERT INTO verses VALUES (26644, 43, 12, 4, 'diz porém Judas o Iscariotes um o discípulos dele o estando-prestes-a ele entregar');
INSERT INTO verses VALUES (26645, 43, 12, 5, 'através-de quê isto o mirra não Foi-vendido trezentos denários e foi-dado pobres');
INSERT INTO verses VALUES (26646, 43, 12, 6, 'disse porém isto não que acerca-de o pobres importava a ele mas que ladrão era e o bolsa tendo o sendo-lançadas carregava');
INSERT INTO verses VALUES (26647, 43, 12, 7, 'disse portanto o Iesous Deixa ela para que para o dia o embalsamento meu guarde isso');
INSERT INTO verses VALUES (26648, 43, 12, 8, 'o pobres pois sempre tendes com deles-mesmos mim porém não sempre tendes');
INSERT INTO verses VALUES (26649, 43, 12, 9, 'conheceu portanto o multidão muito de o judeus que ali é e vieram não através-de o Iesous somente mas para que e o Lázaro vejam o qual ressuscitou de mortos');
INSERT INTO verses VALUES (26650, 43, 12, 10, 'deliberaram porém o sumos-sacerdotes para que e o Lázaro matem');
INSERT INTO verses VALUES (26651, 43, 12, 11, 'que muitos através-de ele iam o judeus e criam para o Iesous');
INSERT INTO verses VALUES (26652, 43, 12, 12, 'o no-dia-seguinte o multidão muito o vindo para o festa ouvindo que vem Iesous para Jerusalém');
INSERT INTO verses VALUES (26653, 43, 12, 13, 'receberam o ramos-de-palmeira o de-palmeiras e saíram para encontro a ele e clamavam Hosana tendo-sido-bendito o o-que-vem em em-nome do-Kyrios e o Rei o Israel');
INSERT INTO verses VALUES (26654, 43, 12, 14, 'encontrando porém o Iesous jumentinho sentou-se sobre isso assim-como é escrito');
INSERT INTO verses VALUES (26655, 43, 12, 15, 'não temas filha Sião eis o rei teu vem sentado sobre jumentinho jumento');
INSERT INTO verses VALUES (26656, 43, 12, 16, 'estas-coisas não conheceram dele o discípulos o primeiro mas quando foi-glorificado Iesous então lembraram-se que estas-coisas era sobre a ele escritas e estas-coisas fizeram a ele');
INSERT INTO verses VALUES (26657, 43, 12, 17, 'Testemunhava portanto o multidão o sendo com dele quando o Lázaro clamou de o sepulcro e ressuscitou ele de mortos');
INSERT INTO verses VALUES (26658, 43, 12, 18, 'através-de isto e encontrou a ele o multidão que ouviram isto ele ter-feito o sinal');
INSERT INTO verses VALUES (26659, 43, 12, 19, 'o portanto fariseus disseram junto-a a-si-mesmos Contemplai que não Aproveitais nada vê o mundo atrás dele partiu');
INSERT INTO verses VALUES (26660, 43, 12, 20, 'eram porém Gregos alguns de o subindo para que adorem em o festa');
INSERT INTO verses VALUES (26661, 43, 12, 21, 'estes portanto aproximaram-se Filipe o de Betsaida o Galileia e perguntavam ele dizendo Kyrie queremos o Iesous ver');
INSERT INTO verses VALUES (26662, 43, 12, 22, 'vem o Filipe e diz o André vem André e Filipe e dizem o Iesous');
INSERT INTO verses VALUES (26663, 43, 12, 23, 'o porém Iesous responde a-eles dizendo Tem-vindo o hora para que seja-glorificado o Filho o do-homem');
INSERT INTO verses VALUES (26664, 43, 12, 24, 'amém amém digo a-vós se não o grão o trigo caindo para o terra morra ele só permanece se porém morra muito fruto carrega');
INSERT INTO verses VALUES (26665, 43, 12, 25, 'o amando o alma dele destrói ela e o odiando o alma dele em o ao-mundo neste para vida eterno guardará ela');
INSERT INTO verses VALUES (26666, 43, 12, 26, 'se a-mim alguém sirva mim siga e onde sou eu ali e o servo o meu será se alguém mim sirva honrará ele o Pai');
INSERT INTO verses VALUES (26667, 43, 12, 27, 'agora o alma meu tem-sido-perturbado e quê diga Pai salva me de o hora desta mas através-de isto vieram para o hora esta');
INSERT INTO verses VALUES (26668, 43, 12, 28, 'Pai glorifica teu o nome veio portanto voz de o do-céu e glorifiquei e novamente glorificarei');
INSERT INTO verses VALUES (26669, 43, 12, 29, 'o portanto multidão o estando-de-pé e ouvindo dizia trovão ter-acontecido outros diziam anjo a ele tem-falado');
INSERT INTO verses VALUES (26670, 43, 12, 30, 'respondeu Iesous e disse não através-de mim o voz esta aconteceu mas através-de vos');
INSERT INTO verses VALUES (26671, 43, 12, 31, 'agora juízo é o do-mundo deste agora o governante o do-mundo deste será-lançado-fora fora');
INSERT INTO verses VALUES (26672, 43, 12, 32, 'e-eu se Seja-exaltado de o da-terra todos Arrastarei junto-a a-mim-mesmo');
INSERT INTO verses VALUES (26673, 43, 12, 33, 'isto porém dizia sinalizando qual morte estava-prestes-a morrer');
INSERT INTO verses VALUES (26674, 43, 12, 34, 'respondeu portanto a ele o multidão nós ouvimos de o da-lei que o Christos permanece para o eternidade e como dizes tu que é necessário ser-exaltado o Filho o do-homem quem é este o Filho o do-homem');
INSERT INTO verses VALUES (26675, 43, 12, 35, 'disse portanto a-eles o Iesous ainda pouco tempo o luz em a-vós é andai como o luz tendes para que não trevas vos alcance e o caminhando em o trevas não sei onde vai');
INSERT INTO verses VALUES (26676, 43, 12, 36, 'como o luz tendes credes para o luz para que filhos luz torneis-vos estas-coisas falou Iesous e partindo escondeu-se de deles');
INSERT INTO verses VALUES (26677, 43, 12, 37, 'Tantas-coisas porém dele sinais tendo-feito diante-de deles não criam para ele');
INSERT INTO verses VALUES (26678, 43, 12, 38, 'para que o palavra Isaías o profeta seja-cumprido o qual disse Kyrie quem creu o ouvido nosso e o braço do-Kyrios a-quem foi-revelado');
INSERT INTO verses VALUES (26679, 43, 12, 39, 'através-de isto não podiam crer que novamente disse Isaías');
INSERT INTO verses VALUES (26680, 43, 12, 40, 'Tem-cegado deles o olhos e Endureceu deles o coração para que não vejam o olhos e compreendam o no-coração e virem-se e curarei eles');
INSERT INTO verses VALUES (26681, 43, 12, 41, 'estas-coisas disse Isaías que viu o glória dele e falou acerca-de dele');
INSERT INTO verses VALUES (26682, 43, 12, 42, 'contudo contudo e de o governantes muitos creram para ele mas através-de o Fariseus não Confessavam para que não expulsos-da-sinagoga tornem-se');
INSERT INTO verses VALUES (26683, 43, 12, 43, 'amaram pois o glória o dos-homens mais Do-que o glória o de-Theos');
INSERT INTO verses VALUES (26684, 43, 12, 44, 'Iesous porém clamou e disse o crendo para mim não crê para mim mas para o o-que-enviou me');
INSERT INTO verses VALUES (26685, 43, 12, 45, 'e o observando mim contempla o o-que-enviou me');
INSERT INTO verses VALUES (26686, 43, 12, 46, 'eu luz para o mundo tenho-vindo para que todo o crendo para mim em o trevas não permaneça');
INSERT INTO verses VALUES (26687, 43, 12, 47, 'e se quem meu ouça o palavras e não guarde eu não julgo ele não pois vieram para que julgo o mundo mas para que salvarei o mundo');
INSERT INTO verses VALUES (26688, 43, 12, 48, 'o rejeitando mim e não recebendo o palavras meu tem o julgando ele o palavra o qual falei aquele julgará ele em o última dia');
INSERT INTO verses VALUES (26689, 43, 12, 49, 'que eu de de-mim-mesmo não falei mas o tendo-enviado me Pai ele-mesmo a-mim mandamento tem-dado quê diga e quê falarei');
INSERT INTO verses VALUES (26690, 43, 12, 50, 'e sei que o mandamento dele vida eterno é o qual portanto eu falo assim-como tem-dito a-mim o Pai assim falo');
INSERT INTO chapters VALUES (1010, 43, 13, 38);
INSERT INTO verses VALUES (26691, 43, 13, 1, 'Antes-de porém o festa o páscoa sei o Iesous que veio dele o hora para que passe de o do-mundo deste junto-a o Pai tendo-amado o próprios o em o ao-mundo para fim amou eles');
INSERT INTO verses VALUES (26692, 43, 13, 2, 'e ceia acontecendo o diabo já tendo-lançado para o coração para que entregue ele Judas de-Simão Iscariotes');
INSERT INTO verses VALUES (26693, 43, 13, 3, 'sei que todas-as-coisas deu a ele o Pai para o mãos e que de de-Theos saiu e junto-a o Theos vai');
INSERT INTO verses VALUES (26694, 43, 13, 4, 'é-levantado de o ceia e põe o vestes e tomando toalha cingiu a-si-mesmo');
INSERT INTO verses VALUES (26695, 43, 13, 5, 'então lança água para o bacia e começou lavar o pés o discípulos e enxugar o toalha o qual era tendo-se-cingido');
INSERT INTO verses VALUES (26696, 43, 13, 6, 'vem portanto junto-a Simão Pedro diz a ele Kyrie tu meu lavas o pés');
INSERT INTO verses VALUES (26697, 43, 13, 7, 'respondeu Iesous e disse a ele o qual eu faço tu não sei agora conheças porém com estas-coisas');
INSERT INTO verses VALUES (26698, 43, 13, 8, 'diz a ele Pedro não não laves meu o pés para o eternidade respondeu Iesous a ele se não lavarei te não tens parte com mim');
INSERT INTO verses VALUES (26699, 43, 13, 9, 'diz a ele Simão Pedro Kyrie não o pés meu somente mas e o mãos e o cabeça');
INSERT INTO verses VALUES (26700, 43, 13, 10, 'diz a ele Iesous o tendo-sido-lavado não tem necessidade se não o pés lavar mas é puro todo e vós puros sois mas não todos');
INSERT INTO verses VALUES (26701, 43, 13, 11, 'sei pois o entregando ele através-de isto disse que Não todos puros sois');
INSERT INTO verses VALUES (26702, 43, 13, 12, 'Quando portanto lavou o pés deles e recebeu o vestes dele e reclinou-se novamente disse a-eles Conhecei quê tenho-feito a-vós');
INSERT INTO verses VALUES (26703, 43, 13, 13, 'vós chamais me o Mestre e o Kyrios e bem dizeis sou pois');
INSERT INTO verses VALUES (26704, 43, 13, 14, 'se portanto eu Lavei vosso o pés o Kyrios e o Mestre e vós deveis uns-aos-outros lavar o pés');
INSERT INTO verses VALUES (26705, 43, 13, 15, 'exemplo pois Dei a-vós para que assim-como eu fiz a-vós e vós façais');
INSERT INTO verses VALUES (26706, 43, 13, 16, 'amém amém digo a-vós não é servo maior o do-Kyrios dele nem apóstolo maior o tendo-enviado ele');
INSERT INTO verses VALUES (26707, 43, 13, 17, 'se estas-coisas sei bem-aventurados sois se façais elas');
INSERT INTO verses VALUES (26708, 43, 13, 18, 'não acerca-de todos vosso digo eu sei quais escolhi mas para que o escritura seja-cumprido o comendo meu o pão levantou sobre mim o calcanhar dele');
INSERT INTO verses VALUES (26709, 43, 13, 19, 'de agora digo a-vós antes-de o tornar-se para que creiais quando aconteça que eu sou');
INSERT INTO verses VALUES (26710, 43, 13, 20, 'amém amém digo a-vós o recebendo se alguém enviarei mim recebe o porém mim recebendo recebe o o-que-enviou me');
INSERT INTO verses VALUES (26711, 43, 13, 21, 'estas-coisas dizendo Iesous perturbou-se o espírito e testemunhou e disse Amém amém digo a-vós que um de vosso entregará me');
INSERT INTO verses VALUES (26712, 43, 13, 22, 'Viam para uns-aos-outros o discípulos estando-perplexos acerca-de de-quem diz');
INSERT INTO verses VALUES (26713, 43, 13, 23, 'era reclinado um de o discípulos dele em o seio o Iesous o qual amava o Iesous');
INSERT INTO verses VALUES (26714, 43, 13, 24, 'acena portanto neste Simão Pedro e diz a ele Dize quem é acerca-de o qual diz');
INSERT INTO verses VALUES (26715, 43, 13, 25, 'tendo-reclinado aquele assim sobre o peito o Iesous diz a ele Kyrie quem é');
INSERT INTO verses VALUES (26716, 43, 13, 26, 'responde portanto o Iesous Aquele é o qual eu mergulharei o bocado e darei a ele tendo-mergulhado portanto o bocado recebe e dá Judá de-Simão Iscariotes');
INSERT INTO verses VALUES (26717, 43, 13, 27, 'e com o bocado então entrou para aquele o Satanás diz portanto a ele Iesous o qual fazes faze mais-rapidamente');
INSERT INTO verses VALUES (26718, 43, 13, 28, 'isto porém ninguém conheceu o reclinados junto-a quê disse a ele');
INSERT INTO verses VALUES (26719, 43, 13, 29, 'alguns pois pensavam porque o bolsa tinha Judas que diz a ele Iesous Compra o qual necessidade temos para o festa ou o pobres para que algo dê');
INSERT INTO verses VALUES (26720, 43, 13, 30, 'tomando portanto o bocado aquele saiu reto era porém noite');
INSERT INTO verses VALUES (26721, 43, 13, 31, 'Quando portanto saiu diz Iesous Agora foi-glorificado o Filho o do-homem e o Theos foi-glorificado em a ele');
INSERT INTO verses VALUES (26722, 43, 13, 32, 'se o Theos foi-glorificado em a ele e o Theos glorificará ele em a-si-mesmo e imediatamente glorificará ele');
INSERT INTO verses VALUES (26723, 43, 13, 33, 'filhinhos ainda pouco com vosso sou buscareis me e assim-como disseram o judeus que onde eu vou vós não podeis vir e a-vós digo agora');
INSERT INTO verses VALUES (26724, 43, 13, 34, 'mandamento nova dou a-vós para que amai uns-aos-outros assim-como amei vos para que e vós amai uns-aos-outros');
INSERT INTO verses VALUES (26725, 43, 13, 35, 'em neste conhecerão todos que mim discípulos sois se amor tenhais em uns-aos-outros');
INSERT INTO verses VALUES (26726, 43, 13, 36, 'diz a ele Simão Pedro Kyrie onde vais respondeu Iesous onde vou não podes a-mim agora seguir seguirás porém depois');
INSERT INTO verses VALUES (26727, 43, 13, 37, 'diz a ele Pedro Kyrie através-de quê não posso a-ti seguir agora o alma meu em-favor-de teu porei');
INSERT INTO verses VALUES (26728, 43, 13, 38, 'responde Iesous o alma teu em-favor-de mim porás amém amém digo a-ti não não galo chame até o qual negues me três-vezes');
INSERT INTO chapters VALUES (1011, 43, 14, 31);
INSERT INTO verses VALUES (26729, 43, 14, 1, 'não seja-perturbado vosso o coração credes para o Theos e para mim credes');
INSERT INTO verses VALUES (26730, 43, 14, 2, 'em o casa o do-Pai meu moradas muitas são se porém não disseram partícula-condicional a-vós que vou preparar lugar a-vós');
INSERT INTO verses VALUES (26731, 43, 14, 3, 'e se vá e Prepararei lugar a-vós novamente venho e tomarei vos junto-a a-mim-mesmo para que onde sou eu e vós éreis');
INSERT INTO verses VALUES (26732, 43, 14, 4, 'e onde eu vou sei o caminho');
INSERT INTO verses VALUES (26733, 43, 14, 5, 'diz a ele Tomé Kyrie não sei onde vais como sei o caminho');
INSERT INTO verses VALUES (26734, 43, 14, 6, 'diz a ele Iesous Eu sou o caminho e o verdade e o vida ninguém vem junto-a o Pai se não através-de mim');
INSERT INTO verses VALUES (26735, 43, 14, 7, 'se tínheis-conhecido me e o Pai meu partícula-condicional sei de agora sabeis ele e tendes-visto');
INSERT INTO verses VALUES (26736, 43, 14, 8, 'diz a ele Filipe Kyrie mostra a-nós o Pai e basta a-nós');
INSERT INTO verses VALUES (26737, 43, 14, 9, 'diz a ele o Iesous Tanto tempo com vosso sou e não Tens-conhecido me Filipe o tendo-visto mim tem-visto o Pai como tu dizes Mostra a-nós o Pai');
INSERT INTO verses VALUES (26738, 43, 14, 10, 'não crês que eu em o Pai e o Pai em a-mim é o palavras o qual eu digo a-vós de de-mim-mesmo não falo o porém Pai em mim permanecendo faz o obra dele');
INSERT INTO verses VALUES (26739, 43, 14, 11, 'credes a-mim que eu em o Pai e o Pai em a-mim se porém não através-de o obra eles credes');
INSERT INTO verses VALUES (26740, 43, 14, 12, 'amém amém digo a-vós o crendo para mim o obra o qual eu faço e-aquele fará e maior destes fará que eu junto-a o Pai vou');
INSERT INTO verses VALUES (26741, 43, 14, 13, 'e o qual algo partícula-condicional peçais em o no-nome meu isto farei para que seja-glorificado o Pai em o Filho');
INSERT INTO verses VALUES (26742, 43, 14, 14, 'se algo peçais me em o no-nome meu eu farei');
INSERT INTO verses VALUES (26743, 43, 14, 15, 'se amai me o mandamentos o minhas guardareis');
INSERT INTO verses VALUES (26744, 43, 14, 16, 'e-eu perguntarei o Pai e outro Consolador dará a-vós para que seja com vosso para o eternidade');
INSERT INTO verses VALUES (26745, 43, 14, 17, 'o espírito o da-verdade o qual o mundo não pode receber que não contempla ele nem conhece vós sabeis isso que de-junto-de a-vós permanece e em a-vós será');
INSERT INTO verses VALUES (26746, 43, 14, 18, 'não deixarei vos órfãos venho junto-a vos');
INSERT INTO verses VALUES (26747, 43, 14, 19, 'ainda pouco e o mundo me não-mais contempla vós porém contemplais me que eu vivo e vós vivereis');
INSERT INTO verses VALUES (26748, 43, 14, 20, 'em naquela o dia conhecereis vós que eu em o Pai meu e vós em mim e-eu em a-vós');
INSERT INTO verses VALUES (26749, 43, 14, 21, 'o tendo o mandamentos meu e guardando a-elas aquele é o amando me o porém amando me será-amado sob o do-Pai meu e-eu amarei ele e revelarei a ele a-mim-mesmo');
INSERT INTO verses VALUES (26750, 43, 14, 22, 'diz a ele Judas não o Iscariotes Kyrie e quê aconteceu que a-nós estás-a-ponto-de manifestar a-ti-mesmo e não o ao-mundo');
INSERT INTO verses VALUES (26751, 43, 14, 23, 'respondeu Iesous e disse a ele Se alguém ama me o palavra meu guardará e o Pai meu amará ele e junto-a ele viremos e morada de-junto-de a ele faremos');
INSERT INTO verses VALUES (26752, 43, 14, 24, 'o não amando me o palavras meu não guarda e o palavra o qual ouvi não é meu mas o que-enviou me do-Pai');
INSERT INTO verses VALUES (26753, 43, 14, 25, 'estas-coisas tenho-falado a-vós de-junto-de a-vós permanecendo');
INSERT INTO verses VALUES (26754, 43, 14, 26, 'o porém Consolador o espírito o santo o qual enviará o Pai em o no-nome meu aquele vos ensinará todas-as-coisas e lembrará vos todas-as-coisas o qual disseram a-vós eu');
INSERT INTO verses VALUES (26755, 43, 14, 27, 'Paz deixo a-vós paz o minha dou a-vós não assim-como o mundo dá eu dou a-vós não seja-perturbado vosso o coração nem acovarde-se');
INSERT INTO verses VALUES (26756, 43, 14, 28, 'ouvistes que eu disseram a-vós Vou e venho junto-a vos se amáveis me Alegrastes-vos se que vou junto-a o Pai que o Pai maior meu é');
INSERT INTO verses VALUES (26757, 43, 14, 29, 'e agora tenho-dito a-vós antes-de tornar-se para que quando aconteça creiais');
INSERT INTO verses VALUES (26758, 43, 14, 30, 'não-mais muitas-coisas falarei com vosso vem pois o o do-mundo governante e em mim não tem nada');
INSERT INTO verses VALUES (26759, 43, 14, 31, 'mas para que conheça o mundo que amo o Pai e assim-como ordenou a-mim o Pai assim faço Levantai-vos vamos daqui');
INSERT INTO chapters VALUES (1012, 43, 15, 27);
INSERT INTO verses VALUES (26760, 43, 15, 1, 'Eu sou o videira o verdadeira e o Pai meu o lavrador é');
INSERT INTO verses VALUES (26761, 43, 15, 2, 'todo ramo em mim não trazendo fruto levanta isso e todo o fruto trazendo poda ele para que fruto mais leve');
INSERT INTO verses VALUES (26762, 43, 15, 3, 'já vós puros sois através-de o palavra o qual tenho-falado a-vós');
INSERT INTO verses VALUES (26763, 43, 15, 4, 'permanecei em a-mim e-eu em a-vós assim-como o ramo não pode fruto trazer de si-mesmo se não permaneça em o videira assim nem vós se não em mim permaneçais');
INSERT INTO verses VALUES (26764, 43, 15, 5, 'eu sou o videira vós o ramos o permanecendo em mim e-eu em a ele este carrega fruto muito que sem mim não podeis fazer nada');
INSERT INTO verses VALUES (26765, 43, 15, 6, 'se não alguém permaneça em a-mim foi-lançado fora como o ramo e secou-se e reúnem eles e para o fogo lançam e queima-se');
INSERT INTO verses VALUES (26766, 43, 15, 7, 'se permaneçais em mim e o palavras meu em a-vós permaneça o qual se queirais pedi-para-vós e acontecerá a-vós');
INSERT INTO verses VALUES (26767, 43, 15, 8, 'em neste foi-glorificado o Pai meu para que fruto muito tragais e sereis mim discípulos');
INSERT INTO verses VALUES (26768, 43, 15, 9, 'assim-como amou me o Pai e-eu vos amei permanecei em o amor o minha');
INSERT INTO verses VALUES (26769, 43, 15, 10, 'se o mandamentos meu guardeis permanecereis em o amor meu assim-como eu o do-Pai meu o mandamentos tenho-guardado e permaneço dele em o amor');
INSERT INTO verses VALUES (26770, 43, 15, 11, 'estas-coisas tenho-falado a-vós para que o alegria o minha em a-vós seja e o alegria vosso seja-cumprido');
INSERT INTO verses VALUES (26771, 43, 15, 12, 'esta é o mandamento o minha para que amai uns-aos-outros assim-como amei vos');
INSERT INTO verses VALUES (26772, 43, 15, 13, 'maior desta amor ninguém tem para que alguém o alma dele ponha em-favor-de o amigos dele');
INSERT INTO verses VALUES (26773, 43, 15, 14, 'vós amigos meu sois se façais o qual eu ordeno a-vós');
INSERT INTO verses VALUES (26774, 43, 15, 15, 'não-mais digo vos servos que o servo não sei quê faz dele o kyrios vos porém tenho-dito amigos que todas-as-coisas o qual ouvi de-junto-de o do-Pai meu fiz-conhecido a-vós');
INSERT INTO verses VALUES (26775, 43, 15, 16, 'não vós me escolhestes mas eu escolhi vos e pus vos para que vós ide e fruto tragais e o fruto vosso permaneça para que o qual algo partícula-condicional peçais o Pai em o no-nome meu dê a-vós');
INSERT INTO verses VALUES (26776, 43, 15, 17, 'estas-coisas ordeno a-vós para que amai uns-aos-outros');
INSERT INTO verses VALUES (26777, 43, 15, 18, 'se o mundo vos odeia sabeis que mim primeiro vosso tem-odiado');
INSERT INTO verses VALUES (26778, 43, 15, 19, 'se de o do-mundo éreis o mundo partícula-condicional o próprio amava que porém de o do-mundo não sois mas eu escolhi vos de o do-mundo através-de isto odeia vos o mundo');
INSERT INTO verses VALUES (26779, 43, 15, 20, 'lembrai-vos o da-palavra o qual eu disseram a-vós não é servo maior o do-Kyrios dele se mim perseguiram e vos perseguirão se o palavra meu Guardaram e o vosso guardarão');
INSERT INTO verses VALUES (26780, 43, 15, 21, 'mas estas-coisas todas-as-coisas farão para vos através-de o nome meu que não sei o o-que-enviou me');
INSERT INTO verses VALUES (26781, 43, 15, 22, 'se não vieram e falei a-eles pecado não tinham agora porém pretexto não têm acerca-de o do-pecado deles');
INSERT INTO verses VALUES (26782, 43, 15, 23, 'o mim odiando e o Pai meu odeia');
INSERT INTO verses VALUES (26783, 43, 15, 24, 'se o obra não fiz em a-eles o qual ninguém outro fez pecado não tinham agora porém e Têm-visto e têm-odiado e mim e o Pai meu');
INSERT INTO verses VALUES (26784, 43, 15, 25, 'mas para que seja-cumprido o palavra o em o lei deles tendo-sido-escrito que Odiaram me gratuitamente');
INSERT INTO verses VALUES (26785, 43, 15, 26, 'quando venha o Consolador o qual eu enviarei a-vós de-junto-de o do-Pai o espírito o da-verdade o qual de-junto-de o do-Pai sai aquele testemunhará acerca-de mim');
INSERT INTO verses VALUES (26786, 43, 15, 27, 'e vós porém testemunhais que de princípio com mim sois');
INSERT INTO chapters VALUES (1013, 43, 16, 33);
INSERT INTO verses VALUES (26787, 43, 16, 1, 'estas-coisas tenho-falado a-vós para que não sejais-escandalizados');
INSERT INTO verses VALUES (26788, 43, 16, 2, 'expulsos-da-sinagoga farão vos mas vem hora para que todo o tendo-matado vos glória serviço-sagrado oferecer o a-Theos');
INSERT INTO verses VALUES (26789, 43, 16, 3, 'e estas-coisas farão que não conheceram o Pai nem a-mim');
INSERT INTO verses VALUES (26790, 43, 16, 4, 'mas estas-coisas tenho-falado a-vós para que quando venha o hora deles lembreis deles que eu disseram a-vós estas-coisas porém a-vós de princípio não disseram que com vosso eu-era');
INSERT INTO verses VALUES (26791, 43, 16, 5, 'agora porém vou junto-a o o-que-enviou me e ninguém de vosso pede me Onde vais');
INSERT INTO verses VALUES (26792, 43, 16, 6, 'mas que estas-coisas tenho-falado a-vós o tristeza tem-cumprido vosso o coração');
INSERT INTO verses VALUES (26793, 43, 16, 7, 'mas eu o verdade digo a-vós convém a-vós para que eu parta se pois não parta o Consolador não não venha junto-a vos se porém vá enviarei ele junto-a vos');
INSERT INTO verses VALUES (26794, 43, 16, 8, 'e vindo aquele repreenderá o mundo acerca-de do-pecado e acerca-de da-justiça e acerca-de juízo');
INSERT INTO verses VALUES (26795, 43, 16, 9, 'acerca-de do-pecado de-fato que não creem para a-mim');
INSERT INTO verses VALUES (26796, 43, 16, 10, 'acerca-de da-justiça e/mas que junto-a o Pai vou e não-mais contemplais me');
INSERT INTO verses VALUES (26797, 43, 16, 11, 'acerca-de porém juízo que o governante o do-mundo deste tem-sido-julgado');
INSERT INTO verses VALUES (26798, 43, 16, 12, 'Ainda muitas-coisas tenho a-vós dizer mas não podeis carregar agora');
INSERT INTO verses VALUES (26799, 43, 16, 13, 'quando porém venha aquele o espírito o da-verdade guiará vos para o verdade toda não pois falará de si-mesmo mas quanto ouve falará e o vindas anunciará a-vós');
INSERT INTO verses VALUES (26800, 43, 16, 14, 'aquele mim glorificará que de o mim receberá e anunciará a-vós');
INSERT INTO verses VALUES (26801, 43, 16, 15, 'todas-as-coisas quanto tem o Pai minhas é através-de isto disseram que de o mim recebe e anunciará a-vós');
INSERT INTO verses VALUES (26802, 43, 16, 16, 'Pouco e não-mais contemplais me e novamente pouco e vereis me');
INSERT INTO verses VALUES (26803, 43, 16, 17, 'Disseram portanto de o discípulos dele junto-a uns-aos-outros quê é isto o qual diz a-nós Pouco e não contemplais me e novamente pouco e vereis me e que vou junto-a o Pai');
INSERT INTO verses VALUES (26804, 43, 16, 18, 'diziam portanto isto quê é o qual diz o pequeno não sei quê fala');
INSERT INTO verses VALUES (26805, 43, 16, 19, 'conheceu Iesous que queriam ele Perguntar e disse a-eles acerca-de deste buscais com uns-aos-outros que disseram Pouco e não contemplais me e novamente pouco e vereis me');
INSERT INTO verses VALUES (26806, 43, 16, 20, 'amém amém digo a-vós que chorareis e lamentareis vós o porém mundo alegrará vós sereis-entristecidos mas o tristeza vosso para alegria acontecerá');
INSERT INTO verses VALUES (26807, 43, 16, 21, 'o mulher quando dê-à-luz tristeza tem que veio o hora dela quando porém gere o criança não-mais lembra o tribulação através-de o alegria que foi-gerado homem para o mundo');
INSERT INTO verses VALUES (26808, 43, 16, 22, 'e vós portanto agora por-um-lado tristeza tendes novamente porém verei vos e alegrará vosso o coração e o alegria vosso ninguém levanta de vosso');
INSERT INTO verses VALUES (26809, 43, 16, 23, 'e em naquela o dia mim não perguntareis nada amém amém digo a-vós se algo peçais o Pai dará a-vós em o no-nome meu');
INSERT INTO verses VALUES (26810, 43, 16, 24, 'até agora não Pedistes nada em o no-nome meu pedi e recebereis para que o alegria vosso seja tendo-sido-preenchida');
INSERT INTO verses VALUES (26811, 43, 16, 25, 'estas-coisas em provérbios tenho-falado a-vós vem hora quando não-mais em provérbios falarei a-vós mas com-ousadia acerca-de o do-Pai anunciarei a-vós');
INSERT INTO verses VALUES (26812, 43, 16, 26, 'em naquela o dia em o no-nome meu pedireis e não digo a-vós que eu perguntarei o Pai acerca-de vosso');
INSERT INTO verses VALUES (26813, 43, 16, 27, 'ele pois o Pai ama vos que vós mim tendes-amado e tendes-crido que eu de-junto-de o de-Theos saíram');
INSERT INTO verses VALUES (26814, 43, 16, 28, 'saíram de o do-Pai e tenho-vindo para o mundo novamente deixo o mundo e vou junto-a o Pai');
INSERT INTO verses VALUES (26815, 43, 16, 29, 'Dizem o discípulos dele Vê agora em com-ousadia falas e provérbio nenhuma dizes');
INSERT INTO verses VALUES (26816, 43, 16, 30, 'agora sei que sei todas-as-coisas e não necessidade tens para que quem te pede em neste cremos que de de-Theos saíste');
INSERT INTO verses VALUES (26817, 43, 16, 31, 'respondeu a-eles Iesous Agora credes');
INSERT INTO verses VALUES (26818, 43, 16, 32, 'eis vem hora e tem-vindo para que sejais-dispersos cada-um para o próprias também-a-mim somente perdoeis e não sou só que o Pai com mim é');
INSERT INTO verses VALUES (26819, 43, 16, 33, 'estas-coisas tenho-falado a-vós para que em mim paz tenhais em o ao-mundo aflição tendes mas tende-ânimo eu tenho-vencido o mundo');
INSERT INTO chapters VALUES (1014, 43, 17, 26);
INSERT INTO verses VALUES (26820, 43, 17, 1, 'estas-coisas falou Iesous e levantando o olhos dele para o céu disse Pai tem-vindo o hora glorifica teu o Filho para que o Filho glorifique te');
INSERT INTO verses VALUES (26821, 43, 17, 2, 'assim-como deste a ele autoridade toda carne para que todo o qual tens-dado a ele dê a-eles vida eterno');
INSERT INTO verses VALUES (26822, 43, 17, 3, 'esta e/mas é o eterno vida para que conheçam te o somente verdadeiro Theos e o qual enviaste Iesous Christos');
INSERT INTO verses VALUES (26823, 43, 17, 4, 'eu te glorifiquei sobre o da-terra o obra tendo-aperfeiçoado o qual tens-dado a-mim para que farei');
INSERT INTO verses VALUES (26824, 43, 17, 5, 'e agora glorifica me tu Pai de-junto-de a-ti-mesmo o glória o qual tinham antes-de o o mundo ser de-junto-de a-ti');
INSERT INTO verses VALUES (26825, 43, 17, 6, 'Manifestei teu o nome o aos-homens o qual deste a-mim de o do-mundo a-ti eram e-a-mim eles deste e o palavra teu têm-guardado');
INSERT INTO verses VALUES (26826, 43, 17, 7, 'agora Conheceram que todas-as-coisas quanto tens-dado a-mim de-junto-de teu são');
INSERT INTO verses VALUES (26827, 43, 17, 8, 'que o palavras o qual deste a-mim tenho-dado a-eles e eles-mesmos receberam e conheceram verdadeiramente que de-junto-de teu saíram e creram que tu me enviaste');
INSERT INTO verses VALUES (26828, 43, 17, 9, 'eu acerca-de deles peço não acerca-de o do-mundo peço mas acerca-de o qual tens-dado a-mim que a-ti são');
INSERT INTO verses VALUES (26829, 43, 17, 10, 'e o minhas-coisas todas-as-coisas tuas é e o tuas minhas e tenho-sido-glorificado em a-eles');
INSERT INTO verses VALUES (26830, 43, 17, 11, 'e não-mais sou em o ao-mundo e eles-mesmos em o ao-mundo são e-eu junto-a te venho Pai santo guarda eles em o no-nome teu o qual tens-dado a-mim para que sejam um assim-como nós');
INSERT INTO verses VALUES (26831, 43, 17, 12, 'quando eu-era com deles eu guardavam eles em o no-nome teu o qual tens-dado a-mim e guardei e ninguém de deles pereceu se não o Filho o perdição para que o escritura seja-cumprido');
INSERT INTO verses VALUES (26832, 43, 17, 13, 'agora porém junto-a te venho e estas-coisas falo em o ao-mundo para que tenham o alegria o minha tendo-sido-cumprida em si-mesmos');
INSERT INTO verses VALUES (26833, 43, 17, 14, 'eu tenho-dado a-eles o palavra teu e o mundo odiou eles que não são de o do-mundo assim-como eu não sou de o do-mundo');
INSERT INTO verses VALUES (26834, 43, 17, 15, 'não peço para que levantes eles de o do-mundo mas para que guardes eles de o do-mal');
INSERT INTO verses VALUES (26835, 43, 17, 16, 'de o do-mundo não são assim-como eu não sou de o do-mundo');
INSERT INTO verses VALUES (26836, 43, 17, 17, 'santifica eles em o verdade o palavra o teu verdade é');
INSERT INTO verses VALUES (26837, 43, 17, 18, 'assim-como mim enviaste para o mundo e-eu enviei eles para o mundo');
INSERT INTO verses VALUES (26838, 43, 17, 19, 'e em-favor-de deles eu santifico a-mim-mesmo para que sejam e eles-mesmos tendo-sido-santificados em verdade');
INSERT INTO verses VALUES (26839, 43, 17, 20, 'não acerca-de destes porém peço somente mas e acerca-de o crentes através-de o da-palavra deles para a-mim');
INSERT INTO verses VALUES (26840, 43, 17, 21, 'para que todos um sejam assim-como tu Pai em mim e-eu em a-ti para que e eles-mesmos em a-nós sejam para que o mundo creia que tu me enviaste');
INSERT INTO verses VALUES (26841, 43, 17, 22, 'e-eu o glória o qual tens-dado a-mim tenho-dado a-eles para que sejam um assim-como nós um');
INSERT INTO verses VALUES (26842, 43, 17, 23, 'eu em a-eles e tu em a-mim para que sejam tendo-sido-aperfeiçoados para um para que conheças o mundo que tu me enviaste e amaste eles assim-como mim amaste');
INSERT INTO verses VALUES (26843, 43, 17, 24, 'Pai o qual tens-dado a-mim quero para que onde sou eu e-aqueles sejam com mim para que contemplem o glória o minha o qual tens-dado a-mim que amaste me antes-de fundação do-mundo');
INSERT INTO verses VALUES (26844, 43, 17, 25, 'Pai justo e o mundo te não conheceu eu e/mas te conheci e estes conheceram que tu me enviaste');
INSERT INTO verses VALUES (26845, 43, 17, 26, 'e fiz-conhecido a-eles o nome teu e farei-conhecer para que o amor o qual amaste me em a-eles seja e-eu em a-eles');
INSERT INTO chapters VALUES (1015, 43, 18, 40);
INSERT INTO verses VALUES (26846, 43, 18, 1, 'estas-coisas dizendo Iesous saiu com o discípulos dele além o de-torrente o Cedrom onde era jardim para o qual entrou ele e o discípulos dele');
INSERT INTO verses VALUES (26847, 43, 18, 2, 'sei porém e Judas o entregando ele o lugar que muitas-vezes reuniu-se Iesous ali com o discípulos dele');
INSERT INTO verses VALUES (26848, 43, 18, 3, 'o portanto Judas tomando o coorte e de o sumos-sacerdotes e de o fariseus servos vem ali com lanternas e lâmpadas e armas');
INSERT INTO verses VALUES (26849, 43, 18, 4, 'Iesous portanto sei todas-as-coisas o vindas sobre ele saiu e diz a-eles Quem buscais');
INSERT INTO verses VALUES (26850, 43, 18, 5, 'responderam a ele Iesous o Nazareno diz a-eles Eu sou estava-de-pé porém e Judas o entregando ele com deles');
INSERT INTO verses VALUES (26851, 43, 18, 6, 'como portanto disse a-eles Eu sou partiram para o atrás e caíram ao-chão');
INSERT INTO verses VALUES (26852, 43, 18, 7, 'novamente portanto perguntou eles Quem buscais o porém disseram Iesous o Nazareno');
INSERT INTO verses VALUES (26853, 43, 18, 8, 'respondeu Iesous Disseram a-vós que eu sou se portanto mim buscais deixai estes ir');
INSERT INTO verses VALUES (26854, 43, 18, 9, 'para que seja-cumprido o palavra o qual disse que o qual tens-dado a-mim não perdi de deles a-ninguém');
INSERT INTO verses VALUES (26855, 43, 18, 10, 'Simão portanto Pedro tendo espada arrastou ela e golpeou o o do-sumo-sacerdote servo e cortou dele o orelha o direito era porém nome o servo Malco');
INSERT INTO verses VALUES (26856, 43, 18, 11, 'disse portanto o Iesous o a-Pedro Lança o espada para o bainha o cálice o qual deu a-mim o Pai não não beba isso');
INSERT INTO verses VALUES (26857, 43, 18, 12, 'o portanto coorte e o quiliarca e o servos o judeus prenderam o Iesous e amarraram ele');
INSERT INTO verses VALUES (26858, 43, 18, 13, 'e levaram junto-a Anás primeiro era pois sogro o Caifás o qual era sumo-sacerdote o ano daquele');
INSERT INTO verses VALUES (26859, 43, 18, 14, 'era porém Caifás o tendo-aconselhado o judeus que convém um homem morrer em-favor-de o povo');
INSERT INTO verses VALUES (26860, 43, 18, 15, 'Seguia porém o Iesous Simão Pedro e outro discípulo o porém discípulo aquele era conhecido o sumo-sacerdote e entrou-junto o Iesous para o pátio o do-sumo-sacerdote');
INSERT INTO verses VALUES (26861, 43, 18, 16, 'o porém Pedro estava-de-pé junto-a o porta fora saiu portanto o discípulo o outro o conhecido o do-sumo-sacerdote e disse o porteiro e introduziu o Pedro');
INSERT INTO verses VALUES (26862, 43, 18, 17, 'diz portanto o a-Pedro o serva o porteiro não e tu de o discípulos és o do-homem deste diz aquele não sou');
INSERT INTO verses VALUES (26863, 43, 18, 18, 'estavam-de-pé porém o servos e o servos braseiro tendo-feito que frio era e aqueciam-se era porém e o Pedro com deles estando-de-pé e aquecendo-se');
INSERT INTO verses VALUES (26864, 43, 18, 19, 'o portanto sumo-sacerdote perguntou o Iesous acerca-de o discípulos dele e acerca-de o ensino dele');
INSERT INTO verses VALUES (26865, 43, 18, 20, 'respondeu a ele Iesous eu com-ousadia tenho-falado o ao-mundo eu sempre ensinei em na-sinagoga e em o templo onde todos o judeus reúnem-se e em oculto falei nada');
INSERT INTO verses VALUES (26866, 43, 18, 21, 'quê me perguntas Pergunta o tendo-ouvido quê falei a-eles vê estes sei o qual disseram eu');
INSERT INTO verses VALUES (26867, 43, 18, 22, 'estas-coisas porém dele tendo-dito um tendo-estado-de-pé o servindo deu Bofetada o Iesous dizendo Assim respondes o sumo-sacerdote');
INSERT INTO verses VALUES (26868, 43, 18, 23, 'respondeu a ele Iesous se mal falei testemunha acerca-de o mal se porém bem quê me bates');
INSERT INTO verses VALUES (26869, 43, 18, 24, 'enviou portanto ele o Anás amarrado junto-a Caifás o sumo-sacerdote');
INSERT INTO verses VALUES (26870, 43, 18, 25, 'era porém Simão Pedro estando-de-pé e aquecendo-se disseram portanto a ele não e tu de o discípulos dele és negou aquele e disse não sou');
INSERT INTO verses VALUES (26871, 43, 18, 26, 'diz um de o escravos o do-sumo-sacerdote parente sendo o qual cortou Pedro o orelha não eu te vi em o jardim com dele');
INSERT INTO verses VALUES (26872, 43, 18, 27, 'novamente portanto negou Pedro e imediatamente galo chamou');
INSERT INTO verses VALUES (26873, 43, 18, 28, 'Conduzem portanto o Iesous de o Caifás para o pretório era porém de-manhã e eles-mesmos não entraram para o pretório para que não sejam-contaminados mas comam o páscoa');
INSERT INTO verses VALUES (26874, 43, 18, 29, 'saiu portanto o Pilatos fora junto-a eles e diz Quem acusação trazei o do-homem deste');
INSERT INTO verses VALUES (26875, 43, 18, 30, 'responderam e disseram a ele se não era este mau fazendo não se a-ti entregamos ele');
INSERT INTO verses VALUES (26876, 43, 18, 31, 'disse portanto a-eles o Pilatos Tomai ele vós e segundo o lei vosso julgai ele disseram a ele o judeus a-nós não é-lícito matar a-ninguém');
INSERT INTO verses VALUES (26877, 43, 18, 32, 'para que o palavra o Iesous seja-cumprido o qual disse sinalizando qual morte estava-prestes-a morrer');
INSERT INTO verses VALUES (26878, 43, 18, 33, 'Entrou portanto novamente para o pretório o Pilatos e chamou o Iesous e disse a ele tu és o Rei o judeus');
INSERT INTO verses VALUES (26879, 43, 18, 34, 'respondeu Iesous desde si-mesmo tu isto dizes ou outros dize a-ti acerca-de mim');
INSERT INTO verses VALUES (26880, 43, 18, 35, 'respondeu o Pilatos Acaso eu judeu sou o nação o teu e o sumos-sacerdotes entregaram te a-mim quê Fizeste');
INSERT INTO verses VALUES (26881, 43, 18, 36, 'respondeu Iesous o reino o minha não é de o do-mundo deste se de o do-mundo deste era o reino o minha o servos partícula-condicional o mim lutavam para que não eu-seja-entregue o judeus agora porém o reino o minha não é daqui');
INSERT INTO verses VALUES (26882, 43, 18, 37, 'disse portanto a ele o Pilatos Portanto rei és tu respondeu o Iesous tu dizes que rei sou eu para isto tenho-sido-gerado e para isto tenho-vindo para o mundo para que testemunharei o verdade todo o sendo de o da-verdade ouve meu o voz');
INSERT INTO verses VALUES (26883, 43, 18, 38, 'diz a ele o Pilatos quê é verdade e isto dizendo novamente saiu junto-a o judeus e diz a-eles eu nenhuma encontro em a ele causa');
INSERT INTO verses VALUES (26884, 43, 18, 39, 'é porém costume a-vós para que um soltarei a-vós em o páscoa quereis portanto soltarei a-vós o Rei o judeus');
INSERT INTO verses VALUES (26885, 43, 18, 40, 'gritaram portanto novamente dizendo não este mas o Barrabás era porém o Barrabás salteador');
INSERT INTO chapters VALUES (1016, 43, 19, 42);
INSERT INTO verses VALUES (26886, 43, 19, 1, 'Então portanto recebeu o Pilatos o Iesous e açoitou');
INSERT INTO verses VALUES (26887, 43, 19, 2, 'e o soldados tendo-trançado coroa de espinhos puseram-sobre dele o cabeça e manto púrpura vestiram ele');
INSERT INTO verses VALUES (26888, 43, 19, 3, 'e vinham junto-a ele e diziam Alegra-te o Rei o judeus e davam a ele bofetadas');
INSERT INTO verses VALUES (26889, 43, 19, 4, 'e saiu novamente fora o Pilatos e diz a-eles Vê conduzo a-vós ele fora para que conheçais que nenhuma causa encontro em a ele');
INSERT INTO verses VALUES (26890, 43, 19, 5, 'saiu portanto o Iesous fora carregando o de-espinhos coroa e o púrpura manto e diz a-eles Eis o homem');
INSERT INTO verses VALUES (26891, 43, 19, 6, 'quando portanto vi ele o sumos-sacerdotes e o servos gritaram dizendo Crucifica crucifica diz a-eles o Pilatos Tomai ele vós e crucificai eu pois não encontro em a ele causa');
INSERT INTO verses VALUES (26892, 43, 19, 7, 'responderam a ele o judeus nós lei temos e segundo o lei deve morrer que Filho de-Theos si-mesmo fez');
INSERT INTO verses VALUES (26893, 43, 19, 8, 'Quando portanto ouviu o Pilatos este o palavra mais temeu');
INSERT INTO verses VALUES (26894, 43, 19, 9, 'e entrou para o pretório novamente e diz o Iesous De-onde és tu o porém Iesous resposta não deu a ele');
INSERT INTO verses VALUES (26895, 43, 19, 10, 'diz portanto a ele o Pilatos A-mim não falas não sei que autoridade tenho soltar te e autoridade tenho crucificar te');
INSERT INTO verses VALUES (26896, 43, 19, 11, 'respondeu Iesous não tinhas autoridade segundo mim nenhuma se não era dado a-ti de-cima através-de isto o tendo-entregado me a-ti maior pecado tem');
INSERT INTO verses VALUES (26897, 43, 19, 12, 'de deste o Pilatos buscava soltar ele o porém judeus gritaram dizendo se este soltes não és amigo o de-César todo o rei si-mesmo fazendo contradiz o César');
INSERT INTO verses VALUES (26898, 43, 19, 13, 'o portanto Pilatos ouvindo o palavras destes conduziu fora o Iesous e sentou-se sobre tribunal para lugar chamado Litóstrotos Em-hebraico porém Gabatá');
INSERT INTO verses VALUES (26899, 43, 19, 14, 'era porém Preparação o páscoa hora era como sexta e diz o judeus Vê o Rei vosso');
INSERT INTO verses VALUES (26900, 43, 19, 15, 'gritaram portanto aqueles Levanta levanta crucifica ele diz a-eles o Pilatos o Rei vosso crucificarei responderam o sumos-sacerdotes não temos rei se não César');
INSERT INTO verses VALUES (26901, 43, 19, 16, 'então portanto entregou ele a-eles para que seja-crucificado Recebi portanto o Iesous');
INSERT INTO verses VALUES (26902, 43, 19, 17, 'e carregando si-mesmo o cruz saiu para o chamado Crânio lugar o qual é-dito Em-hebraico Gólgota');
INSERT INTO verses VALUES (26903, 43, 19, 18, 'onde ele crucificaram e com dele outros dois daqui e daqui meio porém o Iesous');
INSERT INTO verses VALUES (26904, 43, 19, 19, 'escreveu porém e inscrição o Pilatos e colocou sobre o da-cruz era porém escrito Iesous o nazareno o REI o JUDEUS');
INSERT INTO verses VALUES (26905, 43, 19, 20, 'este portanto o inscrição muitos leram o judeus que perto era o lugar o cidade onde foi-crucificado o Iesous e era escrito Em-hebraico Em-romano Em-grego');
INSERT INTO verses VALUES (26906, 43, 19, 21, 'diziam portanto o Pilatos o sumos-sacerdotes o judeus não escreve o Rei o judeus mas que aquele disse Rei sou o judeus');
INSERT INTO verses VALUES (26907, 43, 19, 22, 'respondeu o Pilatos o qual tenho-escrito tenho-escrito');
INSERT INTO verses VALUES (26908, 43, 19, 23, 'o portanto soldados quando crucificaram o Iesous receberam o vestes dele e fizeram quatro partes a-cada-um soldado parte e o túnica era porém o túnica sem-costura de o de-cima Tecido através-de inteiro');
INSERT INTO verses VALUES (26909, 43, 19, 24, 'disseram portanto junto-a uns-aos-outros não rasguemos ele mas obtenhamos-por-sorte acerca-de dele de-quem será para que o escritura seja-cumprido Dividiram-entre-si o Vestes meu si-mesmos e sobre o Vestuário meu lançaram sorte o por-um-lado portanto soldados estas-coisas fizeram');
INSERT INTO verses VALUES (26910, 43, 19, 25, 'estavam-de-pé porém de-junto-de o cruz o Iesous o mãe dele e o irmã o mãe dele Maria o o Clopas e Maria o Madalena');
INSERT INTO verses VALUES (26911, 43, 19, 26, 'Iesous portanto vendo o mãe e o discípulo os-que-estão-de-pé-junto o qual amava diz o mãe Mulher vê o filho teu');
INSERT INTO verses VALUES (26912, 43, 19, 27, 'então diz o discípulo Vê o mãe teu e de daquela o hora recebeu o discípulo ela para o próprias');
INSERT INTO verses VALUES (26913, 43, 19, 28, 'com isto sei o Iesous que já todas-as-coisas tem-sido-completado para que seja-aperfeiçoado o escritura diz Tenho-sede');
INSERT INTO verses VALUES (26914, 43, 19, 29, 'vaso jazia vinagre cheio esponja portanto cheio o vinagre Hissopo tendo-colocado-ao-redor trouxeram dele o boca');
INSERT INTO verses VALUES (26915, 43, 19, 30, 'quando portanto recebeu o vinagre o Iesous disse Tem-sido-consumado e tendo-inclinado o cabeça entregou o espírito');
INSERT INTO verses VALUES (26916, 43, 19, 31, 'o portanto judeus porque Preparação era para que não permaneça sobre o da-cruz o corpos em o no-sábado era pois grande o dia daquele o do-sábado perguntaram o Pilatos para que sejam-quebrados deles o pernas e sejam-levantados');
INSERT INTO verses VALUES (26917, 43, 19, 32, 'vieram portanto o soldados e o por-um-lado primeiro quebraram o pernas e o outro o co-crucificado a ele');
INSERT INTO verses VALUES (26918, 43, 19, 33, 'sobre porém o Iesous vindo como vi já ele tendo-morrido não quebraram dele o pernas');
INSERT INTO verses VALUES (26919, 43, 19, 34, 'mas um o soldados lança dele o lado Perfurou e saiu imediatamente sangue e água');
INSERT INTO verses VALUES (26920, 43, 19, 35, 'e o tendo-visto tem-testemunhado e verdadeira dele é o testemunho e aquele sei que verdadeiras diz para que e vós creiais');
INSERT INTO verses VALUES (26921, 43, 19, 36, 'aconteceu pois estas-coisas para que o escritura seja-cumprido Osso não será-quebrado dele');
INSERT INTO verses VALUES (26922, 43, 19, 37, 'e novamente outra escritura diz Verão para o qual traspassaram');
INSERT INTO verses VALUES (26923, 43, 19, 38, 'com porém estas-coisas perguntou o Pilatos José de Arimateia sendo discípulo o Iesous tendo-sido-escondido porém através-de o medo o judeus para que levante o corpo o Iesous e permitiu o Pilatos veio portanto e levantou o corpo dele');
INSERT INTO verses VALUES (26924, 43, 19, 39, 'veio porém e Nicodemos o vindo junto-a ele da-noite o primeiro trazendo mistura mirra e aloés como libras Cem');
INSERT INTO verses VALUES (26925, 43, 19, 40, 'receberam portanto o corpo o Iesous e amarraram ele faixas-de-linho com o aromas assim-como costume é o judeus embalsamar');
INSERT INTO verses VALUES (26926, 43, 19, 41, 'era porém em o no-lugar onde foi-crucificado jardim e em o jardim túmulo novo em o qual ainda-não ninguém era tendo-sido-posto');
INSERT INTO verses VALUES (26927, 43, 19, 42, 'ali portanto através-de o Preparação o judeus que perto era o túmulo puseram o Iesous');
INSERT INTO chapters VALUES (1017, 43, 20, 31);
INSERT INTO verses VALUES (26928, 43, 20, 1, 'o porém uma o sábados Maria o Madalena vem de-manhã trevas ainda sendo para o túmulo e vê o pedra tendo-sido-levantado de o sepulcro');
INSERT INTO verses VALUES (26929, 43, 20, 2, 'corre portanto e vem junto-a Simão Pedro e junto-a o outro discípulo o qual amava o Iesous e diz a-eles Levantaram o Kyrion de o sepulcro e não sei onde puseram ele');
INSERT INTO verses VALUES (26930, 43, 20, 3, 'Saiu portanto o Pedro e o outro discípulo e vinham para o túmulo');
INSERT INTO verses VALUES (26931, 43, 20, 4, 'Corriam porém o dois juntamente e o outro discípulo correu-adiante mais-rapidamente o de-Pedro e veio primeiro para o túmulo');
INSERT INTO verses VALUES (26932, 43, 20, 5, 'e inclinando-se vê postos o faixas-de-linho não contudo entrou');
INSERT INTO verses VALUES (26933, 43, 20, 6, 'vem portanto e Simão Pedro seguindo a ele e entrou para o túmulo e contempla o faixas-de-linho postos');
INSERT INTO verses VALUES (26934, 43, 20, 7, 'e o lenço o qual era sobre o cabeça dele não com o faixas-de-linho posto mas sem tendo-sido-enrolado para um lugar');
INSERT INTO verses VALUES (26935, 43, 20, 8, 'então portanto entrou e o outro discípulo o vindo primeiro para o túmulo e viu e creu');
INSERT INTO verses VALUES (26936, 43, 20, 9, 'ainda-não pois sei o escritura que é necessário ele de mortos levantar-se');
INSERT INTO verses VALUES (26937, 43, 20, 10, 'foram portanto novamente junto-a si-mesmos o discípulos');
INSERT INTO verses VALUES (26938, 43, 20, 11, 'Maria porém estava-de-pé junto-a o sepulcro fora chorando como portanto chorava inclinou-se para o túmulo');
INSERT INTO verses VALUES (26939, 43, 20, 12, 'e contempla dois anjo em brancos sentando-se um junto-a o cabeça e um junto-a o pés onde jazia o corpo o Iesous');
INSERT INTO verses VALUES (26940, 43, 20, 13, 'e dizem a-ela aqueles Mulher quê choras diz a-eles que Levantaram o Kyrion meu e não sei onde puseram ele');
INSERT INTO verses VALUES (26941, 43, 20, 14, 'estas-coisas tendo-dito Voltou-se para o atrás e contempla o Iesous de-pé e não sei que Iesous é');
INSERT INTO verses VALUES (26942, 43, 20, 15, 'diz a-ela Iesous Mulher quê choras quem buscas aquela parecendo que o jardineiro é diz a ele Kyrie se tu carregaste ele dize a-mim onde colocaste ele e-eu ele levantarei');
INSERT INTO verses VALUES (26943, 43, 20, 16, 'diz a-ela Iesous Miriam tendo-se-virado aquela diz a ele Em-hebraico Rabôni o qual é-dito Mestre');
INSERT INTO verses VALUES (26944, 43, 20, 17, 'diz a-ela Iesous Não meu não-toques ainda-não pois tenho-subido junto-a o Pai vai porém junto-a o irmãos meu e dize a-eles Subo junto-a o Pai meu e Pai vosso e Theos meu e Theos vosso');
INSERT INTO verses VALUES (26945, 43, 20, 18, 'vem Maria o Madalena anunciando o discípulos que Tenho-visto o Kyrion e estas-coisas disse a-ela');
INSERT INTO verses VALUES (26946, 43, 20, 19, 'Sendo portanto tarde o dia naquela o uma sábados e o portas tendo-sido-fechadas onde eram o discípulos através-de o medo o judeus veio o Iesous e pôs-se-de-pé para o meio e diz a-eles Paz a-vós');
INSERT INTO verses VALUES (26947, 43, 20, 20, 'e isto dizendo mostrou e o mãos e o lado a-eles alegraram-se portanto o discípulos vendo o Kyrion');
INSERT INTO verses VALUES (26948, 43, 20, 21, 'disse portanto a-eles o Iesous novamente Paz a-vós assim-como tem-enviado me o Pai e-eu envio vos');
INSERT INTO verses VALUES (26949, 43, 20, 22, 'e isto dizendo soprou-sobre e diz a-eles Tomai espírito santo');
INSERT INTO verses VALUES (26950, 43, 20, 23, 'se alguns perdoeis o do-pecado são-perdoados a-eles se alguns segureis têm-sido-retidos');
INSERT INTO verses VALUES (26951, 43, 20, 24, 'Tomé porém um de o doze o chamado Dídimo não era com deles quando veio Iesous');
INSERT INTO verses VALUES (26952, 43, 20, 25, 'diziam portanto a ele o outros discípulos Temos-visto o Kyrion o porém disse a-eles se não veja em o com-mãos dele o modelo o cravos e lance o dedo meu para o lugar o cravos e lance meu o mão para o lado dele não não creia');
INSERT INTO verses VALUES (26953, 43, 20, 26, 'e com do-dia oito novamente eram dentro o discípulos dele e Tomé com deles vem o Iesous o portas tendo-sido-fechadas e pôs-se-de-pé para o meio e disse Paz a-vós');
INSERT INTO verses VALUES (26954, 43, 20, 27, 'então diz o Tomé Traz o dedo teu aqui e vê o mãos meu e traz o mão teu e lança para o lado meu e não torna-te incrédulo mas fiel');
INSERT INTO verses VALUES (26955, 43, 20, 28, 'respondeu Tomé e disse a ele o Kyrios meu e o Theos meu');
INSERT INTO verses VALUES (26956, 43, 20, 29, 'diz a ele o Iesous que Tens-visto me tens-crido bem-aventurados o não vendo e tendo-crido');
INSERT INTO verses VALUES (26957, 43, 20, 30, 'Muitas-coisas por-um-lado portanto e outras-coisas sinais fez o Iesous diante-de o discípulos o qual não é escritas em o livro neste');
INSERT INTO verses VALUES (26958, 43, 20, 31, 'estas-coisas porém está-escrito para que creiais que Iesous é o Christos o Filho o de-Theos e para que crendo vida tenhais em o em-nome dele');
INSERT INTO chapters VALUES (1018, 43, 21, 25);
INSERT INTO verses VALUES (26959, 43, 21, 1, 'com estas-coisas manifestou si-mesmo novamente Iesous o discípulos sobre o do-mar o Tiberíades manifestou porém assim');
INSERT INTO verses VALUES (26960, 43, 21, 2, 'eram juntamente Simão Pedro e Tomé o chamado Dídimo e Natanael o de Caná o Galileia e o o Zebedeu e outros de o discípulos dele dois');
INSERT INTO verses VALUES (26961, 43, 21, 3, 'diz a-eles Simão Pedro Vou pescar dizem a ele Vimos e nós com a-ti saíram e embarcaram para o barco e em naquela o à-noite prenderam nada');
INSERT INTO verses VALUES (26962, 43, 21, 4, 'de-manhã porém já acontecendo pôs-se-de-pé Iesous para o praia não contudo sei o discípulos que Iesous é');
INSERT INTO verses VALUES (26963, 43, 21, 5, 'diz portanto a-eles Iesous Criancinhas não algo comida tendes responderam a ele Não');
INSERT INTO verses VALUES (26964, 43, 21, 6, 'o porém disse a-eles Lançai para o direita partes o do-barco o rede e encontrareis lançaram portanto e não-mais ele Arrastar tinham-força de o multidão o peixes');
INSERT INTO verses VALUES (26965, 43, 21, 7, 'diz portanto o discípulo aquele o qual amava o Iesous o a-Pedro o Kyrios é Simão portanto Pedro ouvindo que o Kyrios é o veste-exterior cingiu-se era pois nu e lançou si-mesmo para o mar');
INSERT INTO verses VALUES (26966, 43, 21, 8, 'o porém outros discípulos o barquinho vieram não pois eram longe de o da-terra mas como de côvados duzentos arrastando o rede o peixes');
INSERT INTO verses VALUES (26967, 43, 21, 9, 'como portanto desembarcaram para o terra veem braseiro jazendo e peixinho imposto-sobre e pão');
INSERT INTO verses VALUES (26968, 43, 21, 10, 'diz a-eles o Iesous Trazei de o peixinhos o qual prendei agora');
INSERT INTO verses VALUES (26969, 43, 21, 11, 'subiu Simão Pedro e arrastou o rede para o terra cheio peixes grandes cem cinquenta três e tantos existindo não rasgou-se o rede');
INSERT INTO verses VALUES (26970, 43, 21, 12, 'diz a-eles o Iesous Vinde comei-a-refeição-da-manhã ninguém ousava o discípulos examinar ele tu quem és sei que o Kyrios é');
INSERT INTO verses VALUES (26971, 43, 21, 13, 'vem Iesous e recebe o pão e dá a-eles e o peixinho semelhantemente');
INSERT INTO verses VALUES (26972, 43, 21, 14, 'isto já terceira-vez foi-manifestado Iesous o discípulos levantando-se de mortos');
INSERT INTO verses VALUES (26973, 43, 21, 15, 'Quando portanto almoçaram diz o Simão a-Pedro o Iesous Simão João amas me mais destes diz a ele Sim Kyrie tu sei que amo te diz a ele Apascenta o cordeiros meu');
INSERT INTO verses VALUES (26974, 43, 21, 16, 'diz a ele novamente segunda-vez Simão João amas me diz a ele Sim Kyrie tu sei que amo te diz a ele pastoreia o ovelhinhas meu');
INSERT INTO verses VALUES (26975, 43, 21, 17, 'diz a ele o terceira-vez Simão João amas me foi-entristecido o Pedro que disse a ele o terceira-vez Amas me e disse a ele Kyrie todas-as-coisas tu sei tu conheces que amo te diz a ele Iesous Apascenta o ovelhinhas meu');
INSERT INTO verses VALUES (26976, 43, 21, 18, 'amém amém digo a-ti quando eras mais-jovem te-cingias a-ti-mesmo e andavas onde Querias quando porém envelheças fervorosos o mãos teu e outro cingirá te e levará onde não queres');
INSERT INTO verses VALUES (26977, 43, 21, 19, 'isto porém disse sinalizando qual morte glorificará o Theos e isto dizendo diz a ele Segue a-mim');
INSERT INTO verses VALUES (26978, 43, 21, 20, 'tendo-se-voltado o Pedro vê o discípulo o qual amava o Iesous seguindo o qual e reclinou-se em o ceia sobre o peito dele e disse Kyrie quem é o entregando te');
INSERT INTO verses VALUES (26979, 43, 21, 21, 'este portanto vendo o Pedro diz o Iesous Kyrios este porém quê');
INSERT INTO verses VALUES (26980, 43, 21, 22, 'diz a ele o Iesous se ele quero permanecer até venho quê junto-a te tu a-mim segue');
INSERT INTO verses VALUES (26981, 43, 21, 23, 'saiu portanto este o palavra para o irmãos que o discípulo aquele não morre não disse porém a ele o Iesous que não morre mas se ele quero permanecer até venho quê junto-a te');
INSERT INTO verses VALUES (26982, 43, 21, 24, 'Este é o discípulo o testemunhando acerca-de destes e o tendo-escrito estas-coisas e sei que verdadeiro dele o testemunho é');
INSERT INTO verses VALUES (26983, 43, 21, 25, 'É porém e outras-coisas muitas-coisas o qual fez o Iesous quaisquer se seja-escrito segundo um nem ele suponho o mundo conter o sendo-escritos livros');
INSERT INTO books VALUES (44, 'ACT', 'Atos', 'NT', 28);
INSERT INTO chapters VALUES (1019, 44, 1, 26);
INSERT INTO verses VALUES (26984, 44, 1, 1, 'o por-um-lado primeiro palavra Fiz-para-mim acerca-de todos Ômega Teófilo o qual começou o Iesous fazer e e ensinar');
INSERT INTO verses VALUES (26985, 44, 1, 2, 'até o qual do-dia tendo-ordenado o apóstolos através-de do-espírito do-santo o qual escolheu foi-elevado');
INSERT INTO verses VALUES (26986, 44, 1, 3, 'o qual e apresentou si-mesmo vivendo com o sofrer ele em muitos em-provas-infalíveis através-de dias quarenta aparecendo a-eles e dizendo o acerca-de o do-reino o de-Theos');
INSERT INTO verses VALUES (26987, 44, 1, 4, 'e reunindo-se-com ordenou a-eles de Jerusalém não separar-se mas esperar o promessa o do-Pai o qual ouvistes meu');
INSERT INTO verses VALUES (26988, 44, 1, 5, 'que João por-um-lado batizou água vós porém em Espírito sereis-batizados no-santo não com muitas estas do-dia');
INSERT INTO verses VALUES (26989, 44, 1, 6, 'o por-um-lado portanto tendo-se-reunido perguntavam ele dizendo Kyrie se em o tempo neste restauras o reino o Israel');
INSERT INTO verses VALUES (26990, 44, 1, 7, 'disse junto-a eles não vosso é conhecer tempos ou tempos o qual o Pai pôs em o em-particular em-autoridade');
INSERT INTO verses VALUES (26991, 44, 1, 8, 'mas recebereis poder tendo-sobrevindo o do-santo do-espírito sobre vos e sereis meu testemunhas em e Jerusalém e em toda o Judeia e Samaria e até último o da-terra');
INSERT INTO verses VALUES (26992, 44, 1, 9, 'e estas-coisas dizendo vendo deles foi-levantado e nuvem Tomou ele de o olhos deles');
INSERT INTO verses VALUES (26993, 44, 1, 10, 'e como fitando-os-olhos eram para o céu indo dele e eis homens dois estavam-de-pé-junto a-eles em Vestes brancas');
INSERT INTO verses VALUES (26994, 44, 1, 11, 'o qual e disseram homens galileus quê estais-de-pé vendo para o céu este o Iesous o tendo-sido-levado-para-cima de vosso para o céu assim virá o qual modo contemplastes ele indo para o céu');
INSERT INTO verses VALUES (26995, 44, 1, 12, 'Então retornaram para Jerusalém de do-monte o sendo-chamado Oliveiras o qual é perto Jerusalém do-sábado tendo caminho');
INSERT INTO verses VALUES (26996, 44, 1, 13, 'e quando entraram para o quarto-superior subiram do-qual eram permanecendo o e Pedro e João e Tiago e André Filipe e Tomé Bartolomeu e Mateus Tiago Alfeu e Simão o Zelote e Judas de-Tiago');
INSERT INTO verses VALUES (26997, 44, 1, 14, 'estes todos eram perseverando unanimemente o oração com mulheres e Maria o mãe o Iesous e com o aos-irmãos dele');
INSERT INTO verses VALUES (26998, 44, 1, 15, 'e em o dias estas levantando-se Pedro em no-meio o dos-irmãos disse era e multidão nomes sobre o ele como cem vinte');
INSERT INTO verses VALUES (26999, 44, 1, 16, 'Homens irmãos é necessário ser-cumprido o escritura o qual disse-de-antemão o espírito o santo através-de da-boca Davi acerca-de Judá o tendo-acontecido guia o prendam Iesous');
INSERT INTO verses VALUES (27000, 44, 1, 17, 'que tendo-sido-contado-entre era em a-nós e Obteve-por-sorte o sorte o ministério desta');
INSERT INTO verses VALUES (27001, 44, 1, 18, 'este por-um-lado portanto adquiriu campo de salário o da-injustiça e de-cabeça-para-baixo tendo-se-tornado rebentou meio e derramou-se todas-as-coisas o entranhas dele');
INSERT INTO verses VALUES (27002, 44, 1, 19, 'e conhecido aconteceu todos o habitam Jerusalém de-modo-que ser-chamado o campo aquilo o em-particular dialeto deles Akeldamá isto é Campo sangue');
INSERT INTO verses VALUES (27003, 44, 1, 20, 'está-escrito pois em livro Salmos Seja-feito o Propriedade dele deserta e não seja o habitando em a-ela e o supervisão dele tome outro');
INSERT INTO verses VALUES (27004, 44, 1, 21, 'é necessário portanto o tendo-se-reunido a-nós homens em todo tempo o qual entrou e saiu sobre nos o Kyrios Iesous');
INSERT INTO verses VALUES (27005, 44, 1, 22, 'começando de o batismo João até o do-dia o qual foi-elevado de nosso testemunha o da-ressurreição dele com a-nós tornar-se um destes');
INSERT INTO verses VALUES (27006, 44, 1, 23, 'e estavam-de-pé dois José o chamado Barsabás o qual foi-chamado Justo e Matias');
INSERT INTO verses VALUES (27007, 44, 1, 24, 'e tendo-orado disseram tu Kyrie conhecedor-de-corações todos mostra-publicamente o qual escolhi de destes o dois um');
INSERT INTO verses VALUES (27008, 44, 1, 25, 'receber o lugar o ministério desta e apostolado de o qual transgrediu Judas ir para o lugar o próprio');
INSERT INTO verses VALUES (27009, 44, 1, 26, 'e deram sortes a-eles e caiu o sorte sobre Matias e foi-contado-com com o onze apóstolos');
INSERT INTO chapters VALUES (1020, 44, 2, 47);
INSERT INTO verses VALUES (27010, 44, 2, 1, 'e em o ser-enchido o dia o Pentecostes eram todos juntamente sobre o isso');
INSERT INTO verses VALUES (27011, 44, 2, 2, 'e aconteceu subitamente de o do-céu som como sendo-carregada fôlego violenta e cumpriu todo o casa do-qual eram sentados');
INSERT INTO verses VALUES (27012, 44, 2, 3, 'e Foram-vistos a-eles sendo-divididas línguas como fogo e sentou-se sobre um cada-um deles');
INSERT INTO verses VALUES (27013, 44, 2, 4, 'e foram-cheios todos do-espírito do-santo e começaram falar outras em-línguas assim-como o espírito dava pronunciar a-eles');
INSERT INTO verses VALUES (27014, 44, 2, 5, 'eram porém para Jerusalém habitando judeus homens reverentes de de-todo nação o sob o céu');
INSERT INTO verses VALUES (27015, 44, 2, 6, 'tendo-acontecido porém o voz desta reuniu-se o multidão e foi-confundida que ouviam um cada-um o em-particular dialeto falantes deles');
INSERT INTO verses VALUES (27016, 44, 2, 7, 'ficavam-fora-de-si porém e admiravam-se dizendo Não eis todos estes são o falando galileus');
INSERT INTO verses VALUES (27017, 44, 2, 8, 'e como nós ouvimos cada-um o em-particular dialeto nosso em o qual fomos-gerados');
INSERT INTO verses VALUES (27018, 44, 2, 9, 'partos e Medos e Elamitas e o habitando o Mesopotâmia Judeia e e Capadócia Ponto e o Ásia');
INSERT INTO verses VALUES (27019, 44, 2, 10, 'Frígia e e Panfília Egito e o partes o Líbia o segundo Cirene e o residindo Romanos');
INSERT INTO verses VALUES (27020, 44, 2, 11, 'Judeus e e prosélitos Cretenses e Árabes ouvimos falantes deles o nossas em-línguas o grandezas o de-Theos');
INSERT INTO verses VALUES (27021, 44, 2, 12, 'ficavam-fora-de-si porém todos e ficavam-perplexos outro junto-a outro dizendo quê quer isto ser');
INSERT INTO verses VALUES (27022, 44, 2, 13, 'outros porém zombando diziam que mosto tendo-sido-cheios são');
INSERT INTO verses VALUES (27023, 44, 2, 14, 'Tendo-ficado-de-pé porém o Pedro com o onze levantou o voz dele e pronunciou a-eles homens judeus e o habitando Jerusalém todos isto a-vós conhecido seja e dai-ouvidos o palavras meu');
INSERT INTO verses VALUES (27024, 44, 2, 15, 'não pois como vós Supondes estes embriagam-se é pois hora terceira o do-dia');
INSERT INTO verses VALUES (27025, 44, 2, 16, 'mas isto é o dito através-de o profeta Joel');
INSERT INTO verses VALUES (27026, 44, 2, 17, 'e será em o últimas dias diz o Theos derramarei de o Espírito meu sobre toda carne e profetizarão o filhos vosso e o filhas vosso e o jovens vosso visões verão e o anciãos vosso sonhos sonharão');
INSERT INTO verses VALUES (27027, 44, 2, 18, 'e-de-fato sobre o servos meu e sobre o escravas meu em o dias aqueles derramarei de o Espírito meu e profetizarão');
INSERT INTO verses VALUES (27028, 44, 2, 19, 'e darei prodígios em o no-céu acima e sinais sobre o da-terra abaixo sangue e fogo e vapor fumaça');
INSERT INTO verses VALUES (27029, 44, 2, 20, 'o sol será-convertida para trevas e o lua para sangue antes-de vir dia do-Kyrios o grande e Manifesto');
INSERT INTO verses VALUES (27030, 44, 2, 21, 'e será todo o qual se invoque o nome do-Kyrios será-salvo');
INSERT INTO verses VALUES (27031, 44, 2, 22, 'Homens Israelitas ouvi o palavras estes Iesous o Nazareno homem tendo-sido-demonstrado de o de-Theos para vos poderes e em-prodígios e sinais o qual fez através-de dele o Theos em no-meio vosso assim-como eles-mesmos sei');
INSERT INTO verses VALUES (27032, 44, 2, 23, 'este o Tendo-sido-determinada conselho e presciência o de-Theos Entregue através-de da-mão iníquos tendo-pregado matastes');
INSERT INTO verses VALUES (27033, 44, 2, 24, 'o qual o Theos levantou tendo-desatado o Dores-de-parto o da-morte assim-como não era possível ser-segurado ele sob dele');
INSERT INTO verses VALUES (27034, 44, 2, 25, 'Davi pois diz para ele Eu-via-diante-de-mim o Kyrion diante meu através-de todo que de direita meu é para que não seja-abalado');
INSERT INTO verses VALUES (27035, 44, 2, 26, 'através-de isto alegrou-se meu o coração e exultou o língua meu ainda porém e o carne meu aninhará sobre esperança');
INSERT INTO verses VALUES (27036, 44, 2, 27, 'que não abandonarás o alma meu para Hades nem darás o Santo teu ver corrupção');
INSERT INTO verses VALUES (27037, 44, 2, 28, 'fizeste-conhecer a-mim caminhos da-vida preencherás me alegria com o face teu');
INSERT INTO verses VALUES (27038, 44, 2, 29, 'homens irmãos sendo-lícito dizer com ousadia junto-a vos acerca-de o patriarca Davi que e morreu e foi-sepultado e o sepulcro dele é em a-nós até o do-dia desta');
INSERT INTO verses VALUES (27039, 44, 2, 30, 'profeta portanto sendo e sei que juramento jurou a ele o Theos de fruto o lombo dele sentar sobre o trono dele');
INSERT INTO verses VALUES (27040, 44, 2, 31, 'tendo-previsto falou acerca-de o da-ressurreição o de-Christos que nem foi-abandonado para Hades nem o carne dele viu corrupção');
INSERT INTO verses VALUES (27041, 44, 2, 32, 'este o Iesous levantou o Theos o qual todos nós somos testemunhas');
INSERT INTO verses VALUES (27042, 44, 2, 33, 'o direita portanto o de-Theos Tendo-sido-exaltado o e promessa o do-espírito o do-santo tomando de-junto-de o do-Pai derramou isto o qual vós e vede e ouvi');
INSERT INTO verses VALUES (27043, 44, 2, 34, 'não pois Davi subiu para o céus diz porém ele disse Kyrios o ao-Kyrios meu Senta-te de direita meu');
INSERT INTO verses VALUES (27044, 44, 2, 35, 'até partícula-condicional ponha o inimigos teu estrado o pés teu');
INSERT INTO verses VALUES (27045, 44, 2, 36, 'seguramente portanto saiba todo casa Israel que e Kyrion ele e Christos fez o Theos este o Iesous o qual vós crucificastes');
INSERT INTO verses VALUES (27046, 44, 2, 37, 'Tendo-ouvido porém foram-compungidos o coração dize e junto-a o Pedro e o restantes apóstolos quê façamos homens irmãos');
INSERT INTO verses VALUES (27047, 44, 2, 38, 'Pedro porém junto-a eles Arrependei-vos e seja-batizado cada-um vosso sobre o em-nome Iesous de-Christos para perdão o pecados vosso e recebereis o gratuitamente o do-santo do-espírito');
INSERT INTO verses VALUES (27048, 44, 2, 39, 'a-vós pois é o promessa e o filhos vosso e todos o para longe quanto partícula-condicional chame-a-si Kyrios o Theos nosso');
INSERT INTO verses VALUES (27049, 44, 2, 40, 'outros e palavras mais testificou-solenemente e suplicava eles dizendo Sede-salvos de o geração o perversa desta');
INSERT INTO verses VALUES (27050, 44, 2, 41, 'o por-um-lado portanto tendo-recebido o palavra dele foram-batizados e foram-acrescentados em o dia naquela almas como três-mil');
INSERT INTO verses VALUES (27051, 44, 2, 42, 'eram porém perseverando o em-ensino o apóstolos e o comunhão o partir o pão e o orações');
INSERT INTO verses VALUES (27052, 44, 2, 43, 'Acontecia porém toda alma medo muitos porém prodígios e sinais através-de o apóstolos tornava-se');
INSERT INTO verses VALUES (27053, 44, 2, 44, 'todos porém o tendo-crido sobre o ele tinham todas-as-coisas comuns');
INSERT INTO verses VALUES (27054, 44, 2, 45, 'e o propriedades e o posses vendiam e repartiam elas todos assim-como se alguém necessidade tinha');
INSERT INTO verses VALUES (27055, 44, 2, 46, 'segundo dia e perseverando unanimemente em o templo partindo e segundo casa pão participavam alimento em exultação e simplicidade do-coração');
INSERT INTO verses VALUES (27056, 44, 2, 47, 'louvando o Theos e tendo graça junto-a todo o povo o porém Kyrios acrescentava o os-sendo-salvos segundo dia sobre o isso');
INSERT INTO chapters VALUES (1021, 44, 3, 26);
INSERT INTO verses VALUES (27057, 44, 3, 1, 'Pedro porém e João subiam para o templo sobre o hora o oração o nona');
INSERT INTO verses VALUES (27058, 44, 3, 2, 'e alguém homem coxo de ventre mãe dele sendo era-carregado o qual colocavam segundo dia junto-a o porta o do-templo o chamada Formosa o pedir esmola de-junto-de o entrando para o templo');
INSERT INTO verses VALUES (27059, 44, 3, 3, 'o qual vendo Pedro e João estando-para entrar para o templo perguntava esmola receber');
INSERT INTO verses VALUES (27060, 44, 3, 4, 'fitando-os-olhos porém Pedro para ele com o João disse Olha para nos');
INSERT INTO verses VALUES (27061, 44, 3, 5, 'o porém retinha a-eles esperando algo de deles receber');
INSERT INTO verses VALUES (27062, 44, 3, 6, 'disse porém Pedro Prata e ouro não existe a-mim o qual porém tenho isto a-ti dou em o em-nome Iesous de-Christos o nazareno anda');
INSERT INTO verses VALUES (27063, 44, 3, 7, 'e tendo-agarrado ele o direita da-mão ressuscitou ele imediatamente porém Foram-fortalecidos o pés dele e o violenta');
INSERT INTO verses VALUES (27064, 44, 3, 8, 'e saltando pôs-se-de-pé e andava e entrou com a-eles para o templo caminhando e saltando e louvando o Theos');
INSERT INTO verses VALUES (27065, 44, 3, 9, 'e viu todo o povo ele andando e louvando o Theos');
INSERT INTO verses VALUES (27066, 44, 3, 10, 'reconheciam porém ele que este era o junto-a o esmola sentado sobre o Formosa Porta o do-templo e foram-cheios espanto e êxtase sobre o tendo-acontecido a ele');
INSERT INTO verses VALUES (27067, 44, 3, 11, 'Segurando porém dele o Pedro e o João correu-junto todo o povo junto-a eles sobre o pórtico o chamada Salomão Grandemente-espantados');
INSERT INTO verses VALUES (27068, 44, 3, 12, 'vendo porém o Pedro respondeu junto-a o povo Homens Israelitas quê admirais sobre neste ou a-nós quê fitais como em-particular poder ou piedade tendo-feito o andar ele');
INSERT INTO verses VALUES (27069, 44, 3, 13, 'o Theos Abraão e Isaque e Jacó o Theos o dos-pais nosso glorificou o Servo dele Iesous o qual vós por-um-lado entregastes e negastes segundo rosto Pilatos tendo-julgado daquele soltar');
INSERT INTO verses VALUES (27070, 44, 3, 14, 'vós porém o santo e justo negastes e Pedistes homem homicida ser-concedido-por-graça a-vós');
INSERT INTO verses VALUES (27071, 44, 3, 15, 'o porém Príncipe o da-vida matastes o qual o Theos ressuscitou de mortos o qual nós testemunhas somos');
INSERT INTO verses VALUES (27072, 44, 3, 16, 'e sobre o fé o do-nome dele este o qual contemplais e sei Fortaleceu o nome dele e o fé o através-de dele deu a ele o integridade-completa esta diante-de todos vosso');
INSERT INTO verses VALUES (27073, 44, 3, 17, 'e agora irmãos sei que segundo ignorância Praticastes assim-como e o governantes vosso');
INSERT INTO verses VALUES (27074, 44, 3, 18, 'o porém Theos o qual anunciou-de-antemão através-de da-boca todos o profetas sofrer o Christos dele cumpriu assim');
INSERT INTO verses VALUES (27075, 44, 3, 19, 'arrependei-vos portanto e convertei-vos junto-a o ser-apagados vosso o do-pecado');
INSERT INTO verses VALUES (27076, 44, 3, 20, 'para-que partícula-condicional venham tempos refrigério de face o do-Kyrios e envie o tendo-sido-designado-de-antemão a-vós Christos Iesous');
INSERT INTO verses VALUES (27077, 44, 3, 21, 'o qual é necessário céu por-um-lado receber até tempos restauração todos o qual falou o Theos através-de da-boca o dos-santos de eternidade dele profetas');
INSERT INTO verses VALUES (27078, 44, 3, 22, 'Moisés por-um-lado disse que Profeta a-vós levantará Kyrios o Theos de o dos-irmãos vosso como a-mim dele ouvireis segundo todas-as-coisas quanto partícula-condicional fale junto-a vos');
INSERT INTO verses VALUES (27079, 44, 3, 23, 'será porém toda alma a-qual se não ouça o profeta daquele será-totalmente-destruído de o povo');
INSERT INTO verses VALUES (27080, 44, 3, 24, 'e todos porém o profetas de Samuel e o por-ordem quanto falaram e anunciaram o do-dia estas');
INSERT INTO verses VALUES (27081, 44, 3, 25, 'vós sois o filhos o profetas e o da-aliança o qual o Theos estabeleceu junto-a o pais vosso dizendo junto-a Abraão e em o semente teu serão-abençoados-em todas o famílias o da-terra');
INSERT INTO verses VALUES (27082, 44, 3, 26, 'a-vós primeiro tendo-levantado o Theos o Servo dele enviou ele abençoando vos em o desviar cada-um de o maldades vosso');
INSERT INTO chapters VALUES (1022, 44, 4, 37);
INSERT INTO verses VALUES (27083, 44, 4, 1, 'Falando porém deles junto-a o povo aproximaram-se a-eles o sacerdotes e o comandante o do-templo e o Saduceus');
INSERT INTO verses VALUES (27084, 44, 4, 2, 'estando-indignados através-de o ensinar eles o povo e anunciar em o Iesous o ressurreição o de mortos');
INSERT INTO verses VALUES (27085, 44, 4, 3, 'e lançaram-sobre a-eles o mãos e puseram para guarda para o amanhã era pois Tarde já');
INSERT INTO verses VALUES (27086, 44, 4, 4, 'muitos porém o tendo-ouvido o palavra creram e aconteceu número o homens como milhares cinco');
INSERT INTO verses VALUES (27087, 44, 4, 5, 'aconteceu porém sobre o amanhã ser-reunidos deles o governantes e o anciãos e o escribas em Jerusalém');
INSERT INTO verses VALUES (27088, 44, 4, 6, 'e Anás o sumo-sacerdote e Caifás e João e Alexandre e quanto eram de raça sumo-sacerdotal');
INSERT INTO verses VALUES (27089, 44, 4, 7, 'e tendo-colocado-de-pé eles em o no-meio perguntavam em qual poder ou em qual em-nome fizestes isto vós');
INSERT INTO verses VALUES (27090, 44, 4, 8, 'então Pedro tendo-sido-preenchido do-espírito do-santo disse junto-a eles Governantes o povo e anciãos');
INSERT INTO verses VALUES (27091, 44, 4, 9, 'se nós hoje somos-examinados sobre beneficência do-homem fraco em a-quem este tem-sido-salvo');
INSERT INTO verses VALUES (27092, 44, 4, 10, 'conhecido seja todos a-vós e todo o povo Israel que em o em-nome Iesous de-Christos o nazareno o qual vós crucificastes o qual o Theos ressuscitou de mortos em neste este tem-estado-de-pé diante-de vosso são');
INSERT INTO verses VALUES (27093, 44, 4, 11, 'este é o pedra o tendo-sido-desprezado sob vosso o construtores o tendo-se-tornado para cabeça cantos');
INSERT INTO verses VALUES (27094, 44, 4, 12, 'e não é em a-outro a-ninguém o salvação nem pois nome é outro sob o céu o dado em aos-homens em o qual é necessário ser-salvo nos');
INSERT INTO verses VALUES (27095, 44, 4, 13, 'Contemplando porém o o de-Pedro ousadia e João e tendo-alcançado que homens iletrados são e leigos admiravam-se reconheciam e eles que com o Iesous eram');
INSERT INTO verses VALUES (27096, 44, 4, 14, 'o e homem vendo com a-eles de-pé o tendo-sido-curado nada tinham contradizer');
INSERT INTO verses VALUES (27097, 44, 4, 15, 'tendo-ordenado porém eles fora o sinédrio ir-embora conferiam junto-a uns-aos-outros');
INSERT INTO verses VALUES (27098, 44, 4, 16, 'dizendo quê façamos o aos-homens nestes que por-um-lado pois conhecido sinal aconteceu através-de deles todos o habitam Jerusalém manifesto e não podemos negar');
INSERT INTO verses VALUES (27099, 44, 4, 17, 'mas para que não sobre mais seja-espalhado para o povo ameacemos a-eles não-mais falar sobre o em-nome neste a-ninguém dos-homens');
INSERT INTO verses VALUES (27100, 44, 4, 18, 'e tendo-chamado eles ordenaram de-todo não falar nem ensinar sobre o em-nome o Iesous');
INSERT INTO verses VALUES (27101, 44, 4, 19, 'o porém Pedro e João respondendo disseram junto-a eles se justo é diante-de o de-Theos vosso ouvir mais ou o de-Theos julgai');
INSERT INTO verses VALUES (27102, 44, 4, 20, 'não podemos pois nós o qual vimos e ouvimos não falar');
INSERT INTO verses VALUES (27103, 44, 4, 21, 'o porém tendo-ameaçado-ainda-mais soltaram eles nada encontrando o como punam eles através-de o povo que todos glorificavam o Theos sobre o tendo-se-tornado');
INSERT INTO verses VALUES (27104, 44, 4, 22, 'anos pois era mais quarenta o homem sobre o qual tinha-se-tornado o sinal isto o Cura');
INSERT INTO verses VALUES (27105, 44, 4, 23, 'Tendo-sido-soltos porém vieram junto-a o próprios e anunciaram quanto junto-a eles o sumos-sacerdotes e o anciãos disseram');
INSERT INTO verses VALUES (27106, 44, 4, 24, 'o porém ouvindo unanimemente levantaram voz junto-a o Theos e disseram Soberano tu o tendo-feito o céu e o terra e o mar e todas-as-coisas o em a-eles');
INSERT INTO verses VALUES (27107, 44, 4, 25, 'o o do-Pai nosso através-de do-espírito do-santo da-boca Davi criança teu dizendo para que quê Bramaram nações e povos tramaram vazias');
INSERT INTO verses VALUES (27108, 44, 4, 26, 'apresentaram o reis o da-terra e o governantes foram-reunidos sobre o ele segundo o do-Kyrios e segundo o de-Christos dele');
INSERT INTO verses VALUES (27109, 44, 4, 27, 'foram-reunidos pois sobre da-verdade em o na-cidade nesta sobre o santo Servo teu Iesous o qual ungiste Herodes e e Pôncio Pilatos com nações e povos Israel');
INSERT INTO verses VALUES (27110, 44, 4, 28, 'fazer quanto o mão teu e o conselho predestinou tornar-se');
INSERT INTO verses VALUES (27111, 44, 4, 29, 'e o agora Kyrie Olha sobre o ameaças deles e dá o servos teu com ousadia toda falar o palavra teu');
INSERT INTO verses VALUES (27112, 44, 4, 30, 'em o o mão estender te para Cura e sinais e prodígios tornar-se através-de o do-nome o do-santo Servo teu Iesous');
INSERT INTO verses VALUES (27113, 44, 4, 31, 'e tendo-suplicado deles Foi-sacudido o lugar em o qual eram tendo-sido-reunidos e foram-cheios todos o do-santo do-espírito e falavam o palavra o de-Theos com ousadia');
INSERT INTO verses VALUES (27114, 44, 4, 32, 'o porém multidão o tendo-crido era coração e alma uma e nem um algo o posses a ele dizia próprio ser mas era a-eles todas-as-coisas comuns');
INSERT INTO verses VALUES (27115, 44, 4, 33, 'e poder grande devolviam o testemunho o apóstolos o do-Kyrios Iesous o da-ressurreição graça e grande era sobre todos eles');
INSERT INTO verses VALUES (27116, 44, 4, 34, 'nem pois necessitado alguém era em a-eles quanto pois possuidores de-campos ou casas existiam vendendo traziam o honras o sendo-vendidos');
INSERT INTO verses VALUES (27117, 44, 4, 35, 'e colocavam de-junto-de o pés o apóstolos era-distribuído porém a-cada-um assim-como se alguém necessidade tinha');
INSERT INTO verses VALUES (27118, 44, 4, 36, 'José porém o tendo-sido-chamado Barnabé de o apóstolos o qual é sendo-traduzido Filho da-consolação Levita cipriota o raça');
INSERT INTO verses VALUES (27119, 44, 4, 37, 'existindo a ele campo tendo-vendido trouxe o riqueza e colocou junto-a o pés o apóstolos');
INSERT INTO chapters VALUES (1023, 44, 5, 42);
INSERT INTO verses VALUES (27120, 44, 5, 1, 'Homem e/mas alguém Ananias em-nome com Safira o mulher dele Vendeu propriedade');
INSERT INTO verses VALUES (27121, 44, 5, 2, 'e desviou-para-si de o honra estando-ciente e o mulher e tendo-trazido parte algo de-junto-de o pés o apóstolos colocou');
INSERT INTO verses VALUES (27122, 44, 5, 3, 'disse porém o Pedro Ananias através-de quê cumpriu o Satanás o coração teu mentir te o espírito o santo e reter-para-si de o honra o campo');
INSERT INTO verses VALUES (27123, 44, 5, 4, 'não permanecendo a-ti permanecia e tendo-sido-vendido em o tua em-autoridade existia quê que Puseste em o no-coração teu o assunto isto não Mentiste aos-homens mas o a-Theos');
INSERT INTO verses VALUES (27124, 44, 5, 5, 'ouvindo porém o Ananias o palavras estes caindo expirou e aconteceu medo grande sobre todos o ouvintes');
INSERT INTO verses VALUES (27125, 44, 5, 6, 'levantando-se porém o mais-jovens envolveram ele e tendo-levado-para-fora sepultaram');
INSERT INTO verses VALUES (27126, 44, 5, 7, 'aconteceu porém como hora três intervalo e o mulher dele não sei o tendo-acontecido entrou');
INSERT INTO verses VALUES (27127, 44, 5, 8, 'respondeu porém junto-a ela Pedro Dize a-mim se tão-grande o campo vendestes o porém disse Sim tão-grande');
INSERT INTO verses VALUES (27128, 44, 5, 9, 'o porém Pedro junto-a ela quê que foi-combinado a-vós provar o espírito do-Kyrios eis o pés o tendo-sepultado o homem teu sobre o porta e carregarão-para-fora te');
INSERT INTO verses VALUES (27129, 44, 5, 10, 'caiu porém imediatamente junto-a o pés dele e expirou entrando porém o jovens encontraram ela morta e tendo-levado-para-fora sepultaram junto-a o homem dela');
INSERT INTO verses VALUES (27130, 44, 5, 11, 'e aconteceu medo grande sobre toda o igreja e sobre todos o ouvintes estas-coisas');
INSERT INTO verses VALUES (27131, 44, 5, 12, 'através-de porém o mãos o apóstolos tornava-se sinais e prodígios muitas-coisas em o povo e eram unanimemente todos em o pórtico Salomão');
INSERT INTO verses VALUES (27132, 44, 5, 13, 'o porém restantes ninguém ousava unir-se a-eles mas engrandeceu eles o povo');
INSERT INTO verses VALUES (27133, 44, 5, 14, 'mais porém eram-acrescentados crendo o ao-Kyrios multidões homens e e mulheres');
INSERT INTO verses VALUES (27134, 44, 5, 15, 'de-modo-que e para o praças levar-para-fora o fracos e pôr sobre leitos e camas para que vindo de-Pedro e-se o sombra faça-sombra-sobre a-alguém deles');
INSERT INTO verses VALUES (27135, 44, 5, 16, 'reunia-se porém e o multidão o ao-redor cidades Jerusalém trazendo fracos e sendo-atormentados sob espíritos impuros os-quais eram-curados todos');
INSERT INTO verses VALUES (27136, 44, 5, 17, 'Levantando-se porém o sumo-sacerdote e todos o com a ele o sendo heresia o saduceus foram-cheios zelo');
INSERT INTO verses VALUES (27137, 44, 5, 18, 'e lançaram-sobre o mãos sobre o apóstolos e puseram eles em guardará publicamente');
INSERT INTO verses VALUES (27138, 44, 5, 19, 'anjo porém do-Kyrios através-de da-noite Abriu o porta o prisão tendo-conduzido-para-fora e eles disse');
INSERT INTO verses VALUES (27139, 44, 5, 20, 'Ide e tendo-sido-colocados-de-pé falais em o templo o povo todas-as-coisas o palavras o da-vida desta');
INSERT INTO verses VALUES (27140, 44, 5, 21, 'ouvindo porém entraram sob o madrugada para o templo e ensinavam Tendo-chegado porém o sumo-sacerdote e o com a ele convocaram o sinédrio e toda o conselho-de-anciãos o dos-filhos Israel e enviaram para o prisão ser-levado eles');
INSERT INTO verses VALUES (27141, 44, 5, 22, 'o porém tendo-chegado servos não encontraram eles em o na-prisão tendo-retornado porém anunciaram');
INSERT INTO verses VALUES (27142, 44, 5, 23, 'dizendo que o prisão encontramos tendo-sido-fechado em toda segurança e o guardas de-pé sobre o portas tendo-aberto porém dentro a-ninguém encontramos');
INSERT INTO verses VALUES (27143, 44, 5, 24, 'como porém ouviram o palavras estes o e comandante o do-templo e o sumos-sacerdotes ficavam-perplexos acerca-de deles quê partícula-condicional seja-assim isto');
INSERT INTO verses VALUES (27144, 44, 5, 25, 'tendo-chegado e/mas alguém anunciou a-eles que Eis o homens o qual Pusestes em o na-prisão são em o templo Estando-de-pé e ensinando o povo');
INSERT INTO verses VALUES (27145, 44, 5, 26, 'Então partindo o comandante com o Servos Conduzia eles não com violência temiam pois o povo não sejam-apedrejados');
INSERT INTO verses VALUES (27146, 44, 5, 27, 'tendo-conduzido porém eles estavam-de-pé em o sinédrio e perguntou eles o sumo-sacerdote');
INSERT INTO verses VALUES (27147, 44, 5, 28, 'dizendo Ordem ordenamos a-vós não ensinar sobre o em-nome neste e eis tendes-enchido o Jerusalém o ensino vosso e quereis trazer-sobre sobre nos o sangue o do-homem deste');
INSERT INTO verses VALUES (27148, 44, 5, 29, 'respondendo porém Pedro e o apóstolos disseram obedecer é necessário a-Theos mais ou aos-homens');
INSERT INTO verses VALUES (27149, 44, 5, 30, 'o Theos o dos-pais nosso ressuscitou Iesous o qual vós matastes tendo-pendurado sobre árvore');
INSERT INTO verses VALUES (27150, 44, 5, 31, 'este o Theos Príncipe e Salvador exaltou o direita dele o dar arrependimento o Israel e perdão dos-pecados');
INSERT INTO verses VALUES (27151, 44, 5, 32, 'e nós somos testemunhas o palavras destes e o espírito o santo o qual deu o Theos o obedecem a ele');
INSERT INTO verses VALUES (27152, 44, 5, 33, 'o porém ouvindo ficavam-enfurecidos e desejavam matar eles');
INSERT INTO verses VALUES (27153, 44, 5, 34, 'Levantando-se e/mas alguém em o sinédrio fariseu em-nome Gamaliel mestre-da-lei precioso todo o povo ordenou fora pouco o homens fazer');
INSERT INTO verses VALUES (27154, 44, 5, 35, 'disse e junto-a eles Homens Israelitas guardai-vos si-mesmos sobre o aos-homens nestes quê estais-a-ponto-de praticar');
INSERT INTO verses VALUES (27155, 44, 5, 36, 'antes-de pois destes o dos-dias levantou-se Teudas dizendo ser alguém a-si-mesmo o qual inclinou-se-a homens número como quatrocentos o qual foi-morto e todos quanto eram-persuadidos a ele foram-dispersos e tornaram-se para nada');
INSERT INTO verses VALUES (27156, 44, 5, 37, 'com este levantou-se Judas o Galileu em o dias o registro e afastou povo atrás dele e-aquele pereceram e todos quanto eram-persuadidos a ele foram-dispersos');
INSERT INTO verses VALUES (27157, 44, 5, 38, 'e o agora digo a-vós afastai-vos de o dos-homens destes e deixai eles que se seja de dos-homens o conselho esta ou o obra isto será-destruído');
INSERT INTO verses VALUES (27158, 44, 5, 39, 'se porém de de-Theos é não podereis destruir eles não alguma-vez e lutadores-contra-Theos sejais-encontrados foram-persuadidos porém a ele');
INSERT INTO verses VALUES (27159, 44, 5, 40, 'e tendo-chamado-a-si o apóstolos tendo-espancado ordenaram não falar sobre o em-nome o Iesous e soltaram');
INSERT INTO verses VALUES (27160, 44, 5, 41, 'o por-um-lado portanto iam alegrando-se de face o sinédrio que foram-considerados-dignos em-favor-de o do-nome ser-desonrado');
INSERT INTO verses VALUES (27161, 44, 5, 42, 'toda e dia em o templo e segundo casa não cessavam ensinando e evangelizando o Christos Iesous');
INSERT INTO chapters VALUES (1024, 44, 6, 15);
INSERT INTO verses VALUES (27162, 44, 6, 1, 'em porém o dias estas multiplicando-se o discípulos aconteceu murmuração o Helenistas junto-a o Hebreus que eram-negligenciadas em o ministério o diária o viúvas deles');
INSERT INTO verses VALUES (27163, 44, 6, 2, 'tendo-chamado-a-si porém o doze o multidão o discípulos disseram não agradável é nos tendo-deixado o palavra o de-Theos servir mesas');
INSERT INTO verses VALUES (27164, 44, 6, 3, 'visitai e/mas irmãos homens de vosso sendo-testemunhados sete cheios do-espírito e da-sabedoria o qual constituiremos sobre o necessidade desta');
INSERT INTO verses VALUES (27165, 44, 6, 4, 'nós porém o oração e o ministério o da-palavra perseveraremos');
INSERT INTO verses VALUES (27166, 44, 6, 5, 'e agradou o palavra diante-de de-todo o multidão e escolheram Estêvão homem cheio da-fé e do-espírito do-santo e Filipe e Prócoro e Nicanor e Tímon e Pármenas e Nicolau prosélito Antioqueno');
INSERT INTO verses VALUES (27167, 44, 6, 6, 'o qual estavam-de-pé diante-de o apóstolos e tendo-orado puseram-sobre a-eles o mãos');
INSERT INTO verses VALUES (27168, 44, 6, 7, 'e o palavra o de-Theos crescia e multiplicava-se o número o discípulos em Jerusalém extremamente muito e multidão o sacerdotes Obedeciam o fé');
INSERT INTO verses VALUES (27169, 44, 6, 8, 'coroa porém cheio da-graça e do-poder fazia prodígios e sinais grandes em o povo');
INSERT INTO verses VALUES (27170, 44, 6, 9, 'levantaram e/mas alguns o de o sinagoga o sendo-chamada Libertos e Cireneus e Alexandrinos e o de Cilícia e Ásia disputando-junto o Estêvão');
INSERT INTO verses VALUES (27171, 44, 6, 10, 'e não tinham-força resistir o com-sabedoria e o Espírito o qual falava');
INSERT INTO verses VALUES (27172, 44, 6, 11, 'então Subornaram homens dizendo que Temos-ouvido dele falando palavras blasfemas para Moisés e o Theos');
INSERT INTO verses VALUES (27173, 44, 6, 12, 'agitaram e o povo e o anciãos e o escribas e tendo-se-apresentado arrebataram ele e levaram para o sinédrio');
INSERT INTO verses VALUES (27174, 44, 6, 13, 'Puseram-de-pé e testemunhas falsos dizendo o homem este não cessa falando palavras segundo o lugar o do-santo e o da-lei');
INSERT INTO verses VALUES (27175, 44, 6, 14, 'temos-ouvido pois dele dizendo que Iesous o nazareno este destruirá o lugar este e mudará o costumes o qual entregou a-nós Moisés');
INSERT INTO verses VALUES (27176, 44, 6, 15, 'e tendo-fitado para ele todos o sentando-se em o sinédrio vi o rosto dele como rosto anjo');
INSERT INTO chapters VALUES (1025, 44, 7, 60);
INSERT INTO verses VALUES (27177, 44, 7, 1, 'disse porém o sumo-sacerdote se estas-coisas assim tem');
INSERT INTO verses VALUES (27178, 44, 7, 2, 'o porém disse Homens irmãos e pais ouvi o Theos o da-glória apareceu o pai nosso Abraão estando em o Mesopotâmia antes-de ou habitar ele em Harã');
INSERT INTO verses VALUES (27179, 44, 7, 3, 'e disse junto-a ele Sai de o da-terra teu e o parentela teu e vem para o terra o qual se a-ti mostrarei');
INSERT INTO verses VALUES (27180, 44, 7, 4, 'então saindo de da-terra Caldeus habitou em Harã e-de-lá com o morrer o Pai dele deportou ele para o terra esta para o qual vós agora habitais');
INSERT INTO verses VALUES (27181, 44, 7, 5, 'e não deu a ele herança em a-ela nem tribunal pé e prometeu dar a ele para posse ela e o semente dele com ele não sendo a ele filho');
INSERT INTO verses VALUES (27182, 44, 7, 6, 'falou porém assim o Theos que será o semente dele peregrino em terra alheia e escravizarão ele e maltratarão anos quatrocentos');
INSERT INTO verses VALUES (27183, 44, 7, 7, 'e o nação o qual se servirão julgarei eu o Theos disse e com estas-coisas sairão e servirão a-mim em o no-lugar neste');
INSERT INTO verses VALUES (27184, 44, 7, 8, 'e deu a ele aliança da-circuncisão e assim gerou o Isaque e circuncidou ele o dia o oitavo e Isaque o Jacó e Jacó o doze patriarcas');
INSERT INTO verses VALUES (27185, 44, 7, 9, 'e o patriarcas tendo-sido-zelosos o José venderam para Egito e era o Theos com dele');
INSERT INTO verses VALUES (27186, 44, 7, 10, 'e livrou ele de todas o tribulações dele e deu a ele graça e sabedoria diante-de Faraó rei Egito e constituiu ele Líder sobre Egito e todo o casa dele');
INSERT INTO verses VALUES (27187, 44, 7, 11, 'veio porém fome sobre toda o Egito e Canaã e tribulação grande e não encontravam forragens o pais nosso');
INSERT INTO verses VALUES (27188, 44, 7, 12, 'ouvindo porém Jacó sendo alimentos para Egito enviou-embora o pais nosso primeiro');
INSERT INTO verses VALUES (27189, 44, 7, 13, 'e em o segundo foi-dado-a-conhecer José o aos-irmãos dele e manifesto aconteceu o Faraó o raça José');
INSERT INTO verses VALUES (27190, 44, 7, 14, 'enviando porém José mandou-chamar Jacó o Pai dele e toda o parentela em almas setenta cinco');
INSERT INTO verses VALUES (27191, 44, 7, 15, 'e desceu Jacó para Egito e morreu ele e o pais nosso');
INSERT INTO verses VALUES (27192, 44, 7, 16, 'e foram-transferidos para Siquém e foram-colocados em o sepulcro o qual Comprou Abraão honra prata de-junto-de o dos-filhos Hamor em Siquém');
INSERT INTO verses VALUES (27193, 44, 7, 17, 'Assim-como porém Aproximava-se o tempo o promessa o qual confessou o Theos o Abraão fez-crescer o povo e Foi-multiplicado em Egito');
INSERT INTO verses VALUES (27194, 44, 7, 18, 'até o qual levantou-se rei outro sobre Egito o qual não sei o José');
INSERT INTO verses VALUES (27195, 44, 7, 19, 'este tendo-agido-astutamente-contra o raça nosso maltratou o pais o fazer o crianças-de-peito Expostos deles para o não ser-preservados-vivos');
INSERT INTO verses VALUES (27196, 44, 7, 20, 'em o qual tempo foi-gerado Moisés e era belo o a-Theos o qual foi-criado meses três em o na-casa o pai');
INSERT INTO verses VALUES (27197, 44, 7, 21, 'tendo-sido-exposto porém dele tomou ele o filha Faraó e criou ele a-si-mesma para filho');
INSERT INTO verses VALUES (27198, 44, 7, 22, 'e foi-disciplinado Moisés toda com-sabedoria Egípcios era porém poderoso em palavras e obra dele');
INSERT INTO verses VALUES (27199, 44, 7, 23, 'como porém Era-cumprido a ele de-quarenta-anos tempo subiu sobre o coração dele visitar o irmãos dele o filhos Israel');
INSERT INTO verses VALUES (27200, 44, 7, 24, 'e tendo-visto alguém sendo-injustiçado defendeu e fez vingança o sendo-oprimido tendo-ferido o Egípcio');
INSERT INTO verses VALUES (27201, 44, 7, 25, 'supunha porém compreender o irmãos que o Theos através-de da-mão dele dá salvação a-eles o porém não compreenderam');
INSERT INTO verses VALUES (27202, 44, 7, 26, 'o e seguinte dia apareceu a-eles aos-que-combatem e reconciliava eles para paz dizendo Homens irmãos sois para que quê praticais-injustiça uns-aos-outros');
INSERT INTO verses VALUES (27203, 44, 7, 27, 'o porém praticando-injustiça o próximo rejeitou ele dizendo Quem te constituiu governante e juiz sobre nosso');
INSERT INTO verses VALUES (27204, 44, 7, 28, 'não matar me tu queres o qual modo mataste ontem o Egípcio');
INSERT INTO verses VALUES (27205, 44, 7, 29, 'fugiu porém Moisés em o em-palavra neste e aconteceu peregrino em terra Midiã do-qual gerou filhos dois');
INSERT INTO verses VALUES (27206, 44, 7, 30, 'e tendo-sido-cumpridos anos quarenta apareceu a ele em o deserto o do-monte Sinai anjo em chama fogo sarça');
INSERT INTO verses VALUES (27207, 44, 7, 31, 'o porém Moisés vendo admirava o visão aproximando-se porém dele considerar aconteceu voz do-Kyrios');
INSERT INTO verses VALUES (27208, 44, 7, 32, 'eu o Theos o dos-pais teu o Theos Abraão e Isaque e Jacó tremendo porém tendo-se-tornado Moisés não ousava considerar');
INSERT INTO verses VALUES (27209, 44, 7, 33, 'disse porém a ele o Kyrios solta o sandália o pés teu o pois lugar sobre o qual tens-ficado-de-pé terra santa é');
INSERT INTO verses VALUES (27210, 44, 7, 34, 'vendo vi o maltrato o povo meu o em Egito e o gemido dele ouvi e desci livrar eles e agora vem envie te para Egito');
INSERT INTO verses VALUES (27211, 44, 7, 35, 'Este o Moisés o qual negaram tendo-dito Quem te constituiu governante e juiz este o Theos e governante e resgatador enviou com mão anjo o tendo-aparecido a ele em o sarça');
INSERT INTO verses VALUES (27212, 44, 7, 36, 'este conduziu-fora eles tendo-feito prodígios e sinais em terra Egito e em Vermelho mar e em o deserto anos quarenta');
INSERT INTO verses VALUES (27213, 44, 7, 37, 'este é o Moisés o disseste o filhos Israel Profeta a-vós levantará o Theos de o dos-irmãos vosso como a-mim');
INSERT INTO verses VALUES (27214, 44, 7, 38, 'este é o tendo-se-tornado em o na-igreja em o deserto com o anjo o falando a ele em o no-monte Sinai e o dos-pais nosso o qual recebeu oráculos vivendo dar a-vós');
INSERT INTO verses VALUES (27215, 44, 7, 39, 'o qual não quiseram Obedientes tornar-se o pais nosso mas rejeitaram e Voltaram-se em o corações deles para Egito');
INSERT INTO verses VALUES (27216, 44, 7, 40, 'tendo-dito o Aarão faz a-nós theoi o qual irão-adiante nosso o pois Moisés este o qual conduziu-fora nos de da-terra Egito não sei quê aconteceu a ele');
INSERT INTO verses VALUES (27217, 44, 7, 41, 'e fizeram-um-bezerro em o dias aqueles e conduziram-para-cima sacrifício o ídolo e alegravam-se em o obra o mãos deles');
INSERT INTO verses VALUES (27218, 44, 7, 42, 'virou porém o Theos e entregou eles servir-cultualmente o exército o do-céu assim-como está-escrito em livro o profetas não vítimas-de-sacrifício e sacrifício oferecestes a-mim anos quarenta em o deserto casa Israel');
INSERT INTO verses VALUES (27219, 44, 7, 43, 'e tomastes o tabernáculo o Moloque e o estrela o de-Theos Renfã o modelos o qual fizestes adorar a-eles e deportarei vos além-de Babilônia');
INSERT INTO verses VALUES (27220, 44, 7, 44, 'o tabernáculo o testemunho era o pais nosso em o deserto assim-como ordenou o falando o Moisés fazer ela segundo o modelo o qual Tinha-visto');
INSERT INTO verses VALUES (27221, 44, 7, 45, 'o qual e introduziram tendo-sucedido o pais nosso com Iesous em o posse o nações o qual empurrou-para-fora o Theos de face o dos-pais nosso até o dos-dias Davi');
INSERT INTO verses VALUES (27222, 44, 7, 46, 'o qual encontrou graça diante-de o de-Theos e pediu encontrar habitação o na-casa Jacó');
INSERT INTO verses VALUES (27223, 44, 7, 47, 'Salomão porém edificou a ele casa');
INSERT INTO verses VALUES (27224, 44, 7, 48, 'mas não o Altíssimo em feitos-por-mãos habita assim-como o profeta diz');
INSERT INTO verses VALUES (27225, 44, 7, 49, 'o céu a-mim trono o porém terra estrado o pés meu qual casa edificareis a-mim diz Kyrios ou quem lugar o descanso meu');
INSERT INTO verses VALUES (27226, 44, 7, 50, 'não o mão meu fez estas-coisas todas-as-coisas');
INSERT INTO verses VALUES (27227, 44, 7, 51, 'Duros-de-cerviz e incircuncisos corações e o Ouvidos vós sempre o Espírito o no-santo resistis como o pais vosso e vós');
INSERT INTO verses VALUES (27228, 44, 7, 52, 'quem o profetas não perseguiram o pais vosso e mataram o tendo-anunciado-de-antemão acerca-de o vinda o Justo o qual agora vós traidores e assassinos tornastes-vos');
INSERT INTO verses VALUES (27229, 44, 7, 53, 'os-quais recebestes o lei para ordenanças anjo e não Guardastes');
INSERT INTO verses VALUES (27230, 44, 7, 54, 'Ouvindo porém estas-coisas ficavam-enfurecidos o corações deles e Rangiam o dentes sobre ele');
INSERT INTO verses VALUES (27231, 44, 7, 55, 'sendo porém cheio do-espírito do-santo fitando-os-olhos para o céu viu glória de-Theos e Iesous de-pé de direita o de-Theos');
INSERT INTO verses VALUES (27232, 44, 7, 56, 'e disse Eis observo o céus tendo-sido-abertos e o Filho o do-homem de direita de-pé o de-Theos');
INSERT INTO verses VALUES (27233, 44, 7, 57, 'tendo-clamado porém com-voz grande apertaram o ouvidos deles e Precipitaram-se unanimemente sobre ele');
INSERT INTO verses VALUES (27234, 44, 7, 58, 'e tendo-lançado-fora fora o cidade apedrejavam e o testemunhas depuseram o vestes deles de-junto-de o pés jovem sendo-chamado Saulo');
INSERT INTO verses VALUES (27235, 44, 7, 59, 'e apedrejavam o Estêvão sendo-invocado e dizendo Kyrie Iesous recebe o espírito meu');
INSERT INTO verses VALUES (27236, 44, 7, 60, 'pondo porém o joelhos clamou com-voz grande Kyrie não estabeleças a-eles esta o pecado e isto dizendo adormeceu');
INSERT INTO chapters VALUES (1026, 44, 8, 39);
INSERT INTO verses VALUES (27237, 44, 8, 1, 'Saulo porém era consentindo-junto o morte dele aconteceu porém em naquela o dia perseguição grande sobre o igreja o em em-Jerusalém todos porém foram-espalhados segundo o região o Judeia e Samaria porém o apóstolos');
INSERT INTO verses VALUES (27238, 44, 8, 2, 'levaram-para-sepultar porém o Estêvão homens reverentes e fizeram lamento grande sobre a ele');
INSERT INTO verses VALUES (27239, 44, 8, 3, 'Saulo porém devastava o igreja segundo o casas adentrando arrastando e homens e mulheres entregava para prisão');
INSERT INTO verses VALUES (27240, 44, 8, 4, 'o por-um-lado portanto tendo-sido-dispersos atravessaram evangelizando o palavra');
INSERT INTO verses VALUES (27241, 44, 8, 5, 'Filipe porém tendo-descido para o cidade o Samaria proclamava a-eles o Christos');
INSERT INTO verses VALUES (27242, 44, 8, 6, 'prestavam-atenção porém o multidões o chamados sob o Filipe unanimemente em o ouvir eles e ver o sinais o qual fazia');
INSERT INTO verses VALUES (27243, 44, 8, 7, 'muitos pois o tendo espíritos impuros clamando com-voz grande saíam muitos porém tendo-sido-paralisados e coxos foram-curados');
INSERT INTO verses VALUES (27244, 44, 8, 8, 'aconteceu porém muita alegria em o na-cidade naquela');
INSERT INTO verses VALUES (27245, 44, 8, 9, 'Homem e/mas alguém em-nome Simão existia-anteriormente em o na-cidade praticando-magia e fazendo-ficar-fora-de-si o nação o Samaria dizendo ser alguém si-mesmo grande');
INSERT INTO verses VALUES (27246, 44, 8, 10, 'o qual prestavam-atenção todos de pequeno até grande dizendo Este é o poder o de-Theos o sendo-chamada grande');
INSERT INTO verses VALUES (27247, 44, 8, 11, 'prestavam-atenção porém a ele através-de o suficiente tempo o magias estar-fora-de-si eles');
INSERT INTO verses VALUES (27248, 44, 8, 12, 'quando porém creram o Filipe anunciando-boas-novas acerca-de o do-reino o de-Theos e o do-nome Iesous de-Christos eram-batizados homens e e mulheres');
INSERT INTO verses VALUES (27249, 44, 8, 13, 'o porém Simão e ele creu e tendo-sido-batizado era perseverando o Filipe observando e sinais e poderes grandes acontecendo ficava-fora-de-si');
INSERT INTO verses VALUES (27250, 44, 8, 14, 'Tendo-ouvido porém o em em-Jerusalém apóstolos que tem-recebido o Samaria o palavra o de-Theos enviaram junto-a eles Pedro e João');
INSERT INTO verses VALUES (27251, 44, 8, 15, 'os-quais tendo-descido oraram acerca-de deles para-que recebam espírito santo');
INSERT INTO verses VALUES (27252, 44, 8, 16, 'ainda-não pois era sobre a-ninguém deles tendo-caído-sobre somente porém tendo-sido-batizados existiam para o nome o do-Kyrios Iesous');
INSERT INTO verses VALUES (27253, 44, 8, 17, 'então impunham o mãos sobre eles e recebiam espírito santo');
INSERT INTO verses VALUES (27254, 44, 8, 18, 'vendo porém o Simão que através-de o imposição o de-mãos o apóstolos é-dado o espírito ofereceu a-eles posses');
INSERT INTO verses VALUES (27255, 44, 8, 19, 'dizendo dai e-a-mim o autoridade esta para que o qual se imponha o mãos receba espírito santo');
INSERT INTO verses VALUES (27256, 44, 8, 20, 'Pedro porém disse junto-a ele o prata teu com a-ti seria para perdição que o gratuitamente o de-Theos supuseste através-de de-posses adquirir');
INSERT INTO verses VALUES (27257, 44, 8, 21, 'não é a-ti porção nem sorte em o em-palavra neste o pois coração teu não é reta diante-de o de-Theos');
INSERT INTO verses VALUES (27258, 44, 8, 22, 'arrepende-te portanto de o maldade teu desta e suplica o do-Kyrios se então será-perdoado a-ti o pensamento o do-coração teu');
INSERT INTO verses VALUES (27259, 44, 8, 23, 'para pois fel amargura e vínculo da-injustiça vejo te sendo');
INSERT INTO verses VALUES (27260, 44, 8, 24, 'respondendo porém o Simão disse Rogai vós em-favor-de mim junto-a o Kyrion para-que nada venha-sobre sobre mim o qual tendes-dito');
INSERT INTO verses VALUES (27261, 44, 8, 25, 'o por-um-lado portanto tendo-testificado-solenemente e tendo-falado o palavra o do-Kyrios retornavam para Jerusalém muitas e aldeias o samaritanos anunciavam-boas-novas');
INSERT INTO verses VALUES (27262, 44, 8, 26, 'anjo porém do-Kyrios falou junto-a Filipe dizendo Levanta-te e vai segundo meio-dia sobre o caminho o descendo de Jerusalém para Gaza esta é deserta');
INSERT INTO verses VALUES (27263, 44, 8, 27, 'e levantando-se foi e eis homem etiope eunuco poderoso Candace rainha Etíopes o qual era sobre toda o Gaza dela o qual tinha-vindo para-adorar para Jerusalém');
INSERT INTO verses VALUES (27264, 44, 8, 28, 'era porém Retornando e sentado sobre o carro dele e lia o profeta Isaías');
INSERT INTO verses VALUES (27265, 44, 8, 29, 'disse porém o espírito o Filipe Aproxima-te e une-te o carro neste');
INSERT INTO verses VALUES (27266, 44, 8, 30, 'tendo-corrido-até porém o Filipe ouviu dele lendo Isaías o profeta e disse Porventura pois conheces o qual lês');
INSERT INTO verses VALUES (27267, 44, 8, 31, 'o porém disse como pois partícula-condicional pudesse se não alguém guiará me consolou e o Filipe tendo-subido sentar com a ele');
INSERT INTO verses VALUES (27268, 44, 8, 32, 'o porém passagem o escritura o qual lia era esta como ovelha sobre matança foi-conduzido e como cordeiro diante-de o tosquiando ele mudo assim não abre o boca dele');
INSERT INTO verses VALUES (27269, 44, 8, 33, 'em o humilhará o julgamento dele foi-levantado o geração dele quem narrará que é-levantado de o da-terra o vida dele');
INSERT INTO verses VALUES (27270, 44, 8, 34, 'respondendo porém o eunuco o Filipe disse Rogo teu acerca-de de-quem o profeta diz isto acerca-de si-mesmo ou acerca-de de-outro de-alguém');
INSERT INTO verses VALUES (27271, 44, 8, 35, 'abrindo porém o Filipe o boca dele e começando de o escritura desta anunciou-boa-nova a ele o Iesous');
INSERT INTO verses VALUES (27272, 44, 8, 36, 'como porém iam segundo o caminho vieram sobre algo água e diz o eunuco Eis água quê impede me ser-batizado');
INSERT INTO verses VALUES (27273, 44, 8, 38, 'e ordenou estar-de-pé o carro e desceram ambos para o água o e Filipe e o eunuco e batizou ele');
INSERT INTO verses VALUES (27274, 44, 8, 39, 'quando porém subiram de o água espírito do-Kyrios Arrebatou o Filipe e não viu ele não-mais o eunuco ia pois o caminho dele alegrando-se');
INSERT INTO verses VALUES (27275, 44, 8, 40, 'Filipe porém foi-encontrado para Azoto e passando anunciava-boa-nova o cidades todas até o vir ele para Cesareia');
INSERT INTO chapters VALUES (1027, 44, 9, 43);
INSERT INTO verses VALUES (27276, 44, 9, 1, 'o porém Saulo ainda respirando ameaça e homicídio para o discípulos o do-Kyrios aproximando-se o sumo-sacerdote');
INSERT INTO verses VALUES (27277, 44, 9, 2, 'pediu de-junto-de dele cartas para Damasco junto-a o sinagogas para-que se alguns encontre o do-caminho sendo homens e e mulheres presos conduza para Jerusalém');
INSERT INTO verses VALUES (27278, 44, 9, 3, 'em porém o ir aconteceu ele aproximar-se o Damasco subitamente e ele resplandeceu-ao-redor luz de o do-céu');
INSERT INTO verses VALUES (27279, 44, 9, 4, 'e caindo sobre o terra ouviu voz dizendo a ele Saul Saul quê me persegues');
INSERT INTO verses VALUES (27280, 44, 9, 5, 'disse e/mas Quem és Kyrie o e/mas Eu sou Iesous o qual tu persegues');
INSERT INTO verses VALUES (27281, 44, 9, 6, 'mas levanta-te e entra para o cidade e será-falado a-ti o qual quê te é necessário fazer');
INSERT INTO verses VALUES (27282, 44, 9, 7, 'o porém homens o viajando-junto a ele estavam-de-pé mudos ouvindo por-um-lado o voz ninguém porém observando');
INSERT INTO verses VALUES (27283, 44, 9, 8, 'foi-ressuscitado porém Saulo de o da-terra tendo-sido-abertas porém o olhos dele nada Via conduzindo-pela-mão porém ele introduziram para Damasco');
INSERT INTO verses VALUES (27284, 44, 9, 9, 'e era do-dia três não vendo e não comeu nem bebeu');
INSERT INTO verses VALUES (27285, 44, 9, 10, 'era e/mas alguém discípulo em Damasco em-nome Ananias e disse junto-a ele em visão o Kyrios Ananias o porém disse Eis eu Kyrie');
INSERT INTO verses VALUES (27286, 44, 9, 11, 'o porém Kyrios junto-a ele Levantando-se vai sobre o rua o chamada Reta e busca em casa Judá Saulo em-nome De-Tarso eis pois ora');
INSERT INTO verses VALUES (27287, 44, 9, 12, 'e viu homem Ananias em-nome entrando e tendo-imposto a ele mãos para-que recupere-a-visão');
INSERT INTO verses VALUES (27288, 44, 9, 13, 'respondeu porém Ananias Kyrie ouvi de muitos acerca-de o homem deste quanto males o santos teu fez em Jerusalém');
INSERT INTO verses VALUES (27289, 44, 9, 14, 'e aqui tem autoridade de-junto-de o sumos-sacerdotes amarrar todos o invocando o nome teu');
INSERT INTO verses VALUES (27290, 44, 9, 15, 'disse porém junto-a ele o Kyrios vai que vaso eleição é a-mim este o suportar o nome meu diante-de nações e e reis dos-filhos e Israel');
INSERT INTO verses VALUES (27291, 44, 9, 16, 'eu pois mostrarei a ele quanto é necessário ele em-favor-de o nome meu sofrer');
INSERT INTO verses VALUES (27292, 44, 9, 17, 'partiu porém Ananias e entrou para o casa e pondo-sobre sobre ele o mãos disse Saul irmão o Kyrios tem-enviado me Iesous o tendo-aparecido a-ti em o caminho o qual Vinhas para-que recuperes-a-visão e sejas-preenchido do-espírito do-santo');
INSERT INTO verses VALUES (27293, 44, 9, 18, 'e imediatamente caíram dele de o olhos como escamas recuperou-a-visão e e levantando-se foi-batizado');
INSERT INTO verses VALUES (27294, 44, 9, 19, 'e tomando alimento fortaleceu aconteceu porém com o em Damasco discípulos do-dia alguns');
INSERT INTO verses VALUES (27295, 44, 9, 20, 'e imediatamente em o nas-sinagogas proclamava o Iesous que este é o Filho o de-Theos');
INSERT INTO verses VALUES (27296, 44, 9, 21, 'ficavam-fora-de-si porém todos o ouvindo e diziam não este é o tendo-devastado para Jerusalém o invocando o nome isto e aqui para isto tinha-vindo para que presos eles conduza sobre o sumos-sacerdotes');
INSERT INTO verses VALUES (27297, 44, 9, 22, 'Saulo porém mais era-fortalecido e confundia judeus o habitantes em Damasco unindo que este é o Christos');
INSERT INTO verses VALUES (27298, 44, 9, 23, 'como porém eram-preenchidos dias Suficientes aconselharam-se-junto o judeus matar ele');
INSERT INTO verses VALUES (27299, 44, 9, 24, 'foi-conhecido porém o Saulo o conspiração deles observavam porém e o portas do-dia e e da-noite para-que ele destruam');
INSERT INTO verses VALUES (27300, 44, 9, 25, 'tendo-tomado porém o discípulos dele da-noite através-de o muro desceram ele tendo-baixado em cesto');
INSERT INTO verses VALUES (27301, 44, 9, 26, 'Tendo-chegado porém para Jerusalém tentava unir-se o discípulos e todos temiam ele não crendo que é discípulo');
INSERT INTO verses VALUES (27302, 44, 9, 27, 'Barnabé porém tomando ele conduziu junto-a o apóstolos e narrou a-eles como em o caminho viu o Kyrion e que falou a ele e como em Damasco falou-com-ousadia em o em-nome Iesous');
INSERT INTO verses VALUES (27303, 44, 9, 28, 'e era com deles adentrando e saindo para Jerusalém falando-ousadamente em o em-nome o do-Kyrios');
INSERT INTO verses VALUES (27304, 44, 9, 29, 'falava e e discutia junto-a o Helenistas o porém empreendiam matar ele');
INSERT INTO verses VALUES (27305, 44, 9, 30, 'reconhecendo porém o irmãos conduziram-abaixo ele para Cesareia e enviaram-embora ele para Tarso');
INSERT INTO verses VALUES (27306, 44, 9, 31, 'o por-um-lado portanto assembleia segundo de-toda o Judeia e Galileia e Samaria tinha paz sendo-edificada e indo o medo o do-Kyrios e o consolação o do-santo do-espírito multiplicava-se');
INSERT INTO verses VALUES (27307, 44, 9, 32, 'aconteceu porém Pedro atravessando através-de todos descer e junto-a o santos o habitantes Lida');
INSERT INTO verses VALUES (27308, 44, 9, 33, 'encontrou porém ali homem alguém em-nome Eneias de anos oito reclinado sobre cama o qual era tendo-sido-paralisado');
INSERT INTO verses VALUES (27309, 44, 9, 34, 'e disse a ele o Pedro Eneias Cura te Iesous Christos levanta-te e prepara a-ti-mesmo e imediatamente levantou-se');
INSERT INTO verses VALUES (27310, 44, 9, 35, 'e viram ele todos o habitando Lida e o Sarom os-quais voltaram sobre o Kyrion');
INSERT INTO verses VALUES (27311, 44, 9, 36, 'em Jope e/mas alguém era discípula em-nome Tabita o qual sendo-interpretada é-chamado Dorcas esta era cheio obra boas-coisas e esmolas o qual fazia');
INSERT INTO verses VALUES (27312, 44, 9, 37, 'aconteceu porém em o dias aqueles tendo-adoecido ela morrer tendo-lavado porém puseram em quarto-superior');
INSERT INTO verses VALUES (27313, 44, 9, 38, 'perto porém sendo Lida o Jope o discípulos ouvindo que Pedro é em a-ela enviaram dois homens junto-a ele exortando não hesites atravessar até nosso');
INSERT INTO verses VALUES (27314, 44, 9, 39, 'levantando-se porém Pedro reuniu-se a-eles o qual tendo-chegado conduziram-para-cima para o quarto-superior e apresentaram a ele todas o viúvas chorando e sendo-mostradas túnicas e vestes quanto fazia com deles sendo o Dorcas');
INSERT INTO verses VALUES (27315, 44, 9, 40, 'tendo-expulsado porém fora todos o Pedro e pondo o joelhos orou e tendo-virado junto-a o corpo disse Tabita levanta-te o porém abriu o olhos dela e vendo o Pedro sentou-se');
INSERT INTO verses VALUES (27316, 44, 9, 41, 'dando porém a-ela mão levantou ela chamando porém o santos e o viúvas apresentou ela vivente');
INSERT INTO verses VALUES (27317, 44, 9, 42, 'conhecido porém aconteceu segundo de-toda o Jope e creram muitos sobre o Kyrion');
INSERT INTO verses VALUES (27318, 44, 9, 43, 'aconteceu porém do-dia suficientes permanecer em Jope junto-a a-alguém Simão curtidor');
INSERT INTO chapters VALUES (1028, 44, 10, 48);
INSERT INTO verses VALUES (27319, 44, 10, 1, 'Homem e/mas alguém em Cesareia em-nome Cornélio centurião de coorte o sendo-chamada Itálica');
INSERT INTO verses VALUES (27320, 44, 10, 2, 'piedoso e temendo o Theos com todo o na-casa dele fazendo esmolas muitas o povo e suplicando o de-Theos através-de todo');
INSERT INTO verses VALUES (27321, 44, 10, 3, 'viu em visão manifestamente como acerca-de hora nona o do-dia anjo o de-Theos entrando junto-a ele e tendo-dito a ele Cornélio');
INSERT INTO verses VALUES (27322, 44, 10, 4, 'o porém fitando-os-olhos a ele e aterrorizado tendo-se-tornado disse quê é Kyrie disse porém a ele o orações teu e o esmolas teu subiram para memorial diante-de o de-Theos');
INSERT INTO verses VALUES (27323, 44, 10, 5, 'e agora envia homens para Jope e mandar-buscar Simão alguém o qual é-invocado Pedro');
INSERT INTO verses VALUES (27324, 44, 10, 6, 'este hospeda-se junto-a a-alguém Simão curtidor o qual é casa de-junto-de mar');
INSERT INTO verses VALUES (27325, 44, 10, 7, 'como porém partiu o anjo o falando a ele chamando dois o servos-domésticos e soldado piedoso o perseverando a ele');
INSERT INTO verses VALUES (27326, 44, 10, 8, 'e tendo-narrado todas-as-coisas a-eles enviou eles para o Jope');
INSERT INTO verses VALUES (27327, 44, 10, 9, 'o porém no-dia-seguinte viajando daqueles e o na-cidade aproximando-se subiu Pedro sobre o terraço orar acerca-de hora sexta');
INSERT INTO verses VALUES (27328, 44, 10, 10, 'aconteceu porém faminto e queria provar dos-que-preparam porém deles aconteceu sobre ele êxtase');
INSERT INTO verses VALUES (27329, 44, 10, 11, 'e contempla o céu tendo-sido-aberto e descendo vaso algo como lençol grande quatro governos sendo-baixado sobre o da-terra');
INSERT INTO verses VALUES (27330, 44, 10, 12, 'em o qual existia todas-as-coisas o quadrúpedes e répteis o da-terra e aves o do-céu');
INSERT INTO verses VALUES (27331, 44, 10, 13, 'e aconteceu voz junto-a ele Tendo-se-levantado Pedro sacrifica e come');
INSERT INTO verses VALUES (27332, 44, 10, 14, 'o porém Pedro disse De-nenhum-modo Kyrie que nunca comeram todo comum e impuro');
INSERT INTO verses VALUES (27333, 44, 10, 15, 'e voz novamente de segundo junto-a ele o qual o Theos purificou tu não comum');
INSERT INTO verses VALUES (27334, 44, 10, 16, 'isto porém aconteceu sobre três-vezes e imediatamente foi-elevado o vaso para o céu');
INSERT INTO verses VALUES (27335, 44, 10, 17, 'como porém em si-mesmo ficava-perplexo o Pedro quê partícula-condicional seria o visão o qual viu eis o homens o enviados sob o Cornélio tendo-indagado o casa o de-Simão aproximaram-se sobre o portão');
INSERT INTO verses VALUES (27336, 44, 10, 18, 'e tendo-chamado perguntavam se Simão o invocando Pedro aqui hospeda-se');
INSERT INTO verses VALUES (27337, 44, 10, 19, 'o porém de-Pedro ponderando acerca-de o visão disse o espírito Eis homens dois buscando te');
INSERT INTO verses VALUES (27338, 44, 10, 20, 'mas levantando-se desce e vai com a-eles nada duvidando que eu tenho-enviado eles');
INSERT INTO verses VALUES (27339, 44, 10, 21, 'descendo porém Pedro junto-a o homens disse Eis eu sou o qual buscais quem o causa através-de o qual estais-presentes');
INSERT INTO verses VALUES (27340, 44, 10, 22, 'o porém disseram Cornélio centurião homem justo e temendo o Theos sendo-testemunhado e sob inteiro o nação o judeus Foi-divinamente-advertido sob anjo do-santo mandar-buscar te para o casa dele e ouvir palavras de-junto-de teu');
INSERT INTO verses VALUES (27341, 44, 10, 23, 'tendo-chamado-para-dentro portanto eles hospedou o porém no-dia-seguinte levantando-se saiu com a-eles e alguns o dos-irmãos o de Jope reuniram-se a ele');
INSERT INTO verses VALUES (27342, 44, 10, 24, 'o porém no-dia-seguinte entrou para o Cesareia o porém Cornélio era esperando eles tendo-convocado-junto o parentes dele e o necessários amigos');
INSERT INTO verses VALUES (27343, 44, 10, 25, 'como porém aconteceu o entrar o Pedro tendo-encontrado a ele o Cornélio caindo sobre o pés adorou');
INSERT INTO verses VALUES (27344, 44, 10, 26, 'o porém Pedro ressuscitou ele dizendo Levanta-te e eu ele homem sou');
INSERT INTO verses VALUES (27345, 44, 10, 27, 'e conversando-com a ele entrou e encontra tendo-se-reunido muitos');
INSERT INTO verses VALUES (27346, 44, 10, 28, 'disse e junto-a eles vós sabeis como ilícito é marido judeu unir-se ou aproximar-se estrangeiro e-a-mim o Theos mostrou ninguém comum ou impuro dizer homem');
INSERT INTO verses VALUES (27347, 44, 10, 29, 'por-isso e incontestavelmente vieram tendo-sido-mandado-buscar pergunto portanto A-quem em-palavra mandastes-buscar me');
INSERT INTO verses VALUES (27348, 44, 10, 30, 'e o Cornélio disse de quarta do-dia até desta o hora eu-era o nona orando em o na-casa meu e eis homem pôs-se-de-pé diante meu em veste resplandecente');
INSERT INTO verses VALUES (27349, 44, 10, 31, 'e diz Cornélio foi-ouvido teu o oração e o esmolas teu lembraram-se diante-de o de-Theos');
INSERT INTO verses VALUES (27350, 44, 10, 32, 'envia portanto para Jope e mandar-chamar Simão o qual é-invocado Pedro este hospeda-se em casa de-Simão curtidor de-junto-de mar');
INSERT INTO verses VALUES (27351, 44, 10, 33, 'imediatamente portanto enviei junto-a te tu e bem fizeste tendo-chegado agora portanto todos nós diante-de o de-Theos estamos-presentes ouvir todas-as-coisas o tendo-sido-ordenados a-ti sob o do-Kyrios');
INSERT INTO verses VALUES (27352, 44, 10, 34, 'Tendo-aberto porém Pedro o boca disse sobre da-verdade alcanço que não é aceitador-de-faces o Theos');
INSERT INTO verses VALUES (27353, 44, 10, 35, 'mas em todo nação o temendo ele e trabalhando justiça aceitável a ele é');
INSERT INTO verses VALUES (27354, 44, 10, 36, 'o palavra o qual enviou o filhos Israel anunciando-boa-nova paz através-de Iesous de-Christos este é todos Kyrios');
INSERT INTO verses VALUES (27355, 44, 10, 37, 'vós sei o acontecido palavra segundo de-toda o Judeia começando de o Galileia com o batismo o qual proclamou João');
INSERT INTO verses VALUES (27356, 44, 10, 38, 'Iesous o de Nazaré como ungiu ele o Theos Espírito no-santo e poder o qual atravessou fazendo-bem e Curando todos o sendo-oprimidos sob o diabo que o Theos era com dele');
INSERT INTO verses VALUES (27357, 44, 10, 39, 'e nós testemunhas todos o qual fez em e o região o judeus e Jerusalém o qual e mataram tendo-pendurado sobre árvore');
INSERT INTO verses VALUES (27358, 44, 10, 40, 'este o Theos ressuscitou em o no-terceiro dia e deu ele manifesto tornar-se');
INSERT INTO verses VALUES (27359, 44, 10, 41, 'não todo o povo mas testemunhas o tendo-sido-escolhidos-de-antemão sob o de-Theos a-nós os-quais comemos-com e bebemos-com a ele com o levantar-se ele de mortos');
INSERT INTO verses VALUES (27360, 44, 10, 42, 'e ordenou a-nós proclamar o povo e testificar-solenemente que este é o Tendo-sido-determinado sob o de-Theos Juiz viventes e mortos');
INSERT INTO verses VALUES (27361, 44, 10, 43, 'neste todos o profetas testemunham perdão dos-pecados receber através-de o do-nome dele todas-as-coisas o crendo para ele');
INSERT INTO verses VALUES (27362, 44, 10, 44, 'ainda falando o de-Pedro o palavras estas-coisas caiu-sobre o espírito o santo sobre todos o ouvintes o palavra');
INSERT INTO verses VALUES (27363, 44, 10, 45, 'e ficaram-fora-de-si o de da-circuncisão fiéis quanto vieram-junto o a-Pedro que e sobre o nações o dom o do-santo do-espírito tem-sido-derramado');
INSERT INTO verses VALUES (27364, 44, 10, 46, 'ouviam pois deles falantes em-línguas e engrandecendo o Theos então respondeu Pedro');
INSERT INTO verses VALUES (27365, 44, 10, 47, 'Acaso o água pode impedir alguém o não ser-batizado estes os-quais o espírito o santo receberam como e nós');
INSERT INTO verses VALUES (27366, 44, 10, 48, 'ordenou porém eles em o em-nome Iesous de-Christos ser-batizado então perguntaram ele permanecer do-dia alguns');
INSERT INTO chapters VALUES (1029, 44, 11, 30);
INSERT INTO verses VALUES (27367, 44, 11, 1, 'Ouviram porém o apóstolos e o irmãos o sendo segundo o Judeia que e o nações receberam o palavra o de-Theos');
INSERT INTO verses VALUES (27368, 44, 11, 2, 'quando porém subiu Pedro para Jerusalém disputavam junto-a ele o de da-circuncisão');
INSERT INTO verses VALUES (27369, 44, 11, 3, 'dizendo que Entraste junto-a homens prepúcio tendo e comeste-com a-eles');
INSERT INTO verses VALUES (27370, 44, 11, 4, 'começando porém Pedro expunha a-eles por-ordem dizendo');
INSERT INTO verses VALUES (27371, 44, 11, 5, 'eu eu-era em na-cidade Jope orando e vi em espanto visão descendo vaso algo como lençol grande quatro governos sendo-baixada de o do-céu e veio até mim');
INSERT INTO verses VALUES (27372, 44, 11, 6, 'para o qual fitando-os-olhos consideravam e vi o quadrúpedes o da-terra e o feras e o répteis e o aves o do-céu');
INSERT INTO verses VALUES (27373, 44, 11, 7, 'ouvi porém e voz dizendo a-mim Tendo-se-levantado Pedro sacrifica e come');
INSERT INTO verses VALUES (27374, 44, 11, 8, 'disseram e/mas De-nenhum-modo Kyrie que comum ou impuro nunca entrou para o boca meu');
INSERT INTO verses VALUES (27375, 44, 11, 9, 'respondeu porém de segunda voz de o do-céu o qual o Theos purificou tu não comum');
INSERT INTO verses VALUES (27376, 44, 11, 10, 'isto porém aconteceu sobre três-vezes e foi-arrancado novamente todas-as-coisas para o céu');
INSERT INTO verses VALUES (27377, 44, 11, 11, 'e eis imediatamente três homens aproximaram-se sobre o casa em o qual éramos enviados de Cesareia para me');
INSERT INTO verses VALUES (27378, 44, 11, 12, 'disse porém o Espírito a-mim reunir-se a-eles nada tendo-distinguido vieram porém com mim e o seis irmãos estes e entramos para o casa o varão');
INSERT INTO verses VALUES (27379, 44, 11, 13, 'anunciou porém a-nós como viu o anjo em o na-casa dele tendo-sido-posto-de-pé e tendo-dito Envia para Jope e mandar-buscar Simão o sendo-invocado Pedro');
INSERT INTO verses VALUES (27380, 44, 11, 14, 'o qual falará palavras junto-a te em o qual serás-salvo tu e todo o casa teu');
INSERT INTO verses VALUES (27381, 44, 11, 15, 'em porém o começar me falar caiu-sobre o espírito o santo sobre eles assim-como e sobre nos em princípio');
INSERT INTO verses VALUES (27382, 44, 11, 16, 'lembrei-me porém o palavra o do-Kyrios como dizia João por-um-lado batizou água vós porém sereis-batizados em Espírito no-santo');
INSERT INTO verses VALUES (27383, 44, 11, 17, 'se portanto o Igual gratuitamente deu a-eles o Theos como e a-nós aos-que-creram sobre o Kyrion Iesous Christon eu quem eu-era poderoso impedir o Theos');
INSERT INTO verses VALUES (27384, 44, 11, 18, 'ouvindo porém estas-coisas aquietaram-se e glorificaram o Theos dizendo então e o nações o Theos o arrependimento para vida deu');
INSERT INTO verses VALUES (27385, 44, 11, 19, 'o por-um-lado portanto tendo-sido-dispersos de o tribulação o tendo-acontecido sobre Estêvão atravessaram até Fenícia e Chipre e Antioquia a-ninguém falando o palavra se não somente judeus');
INSERT INTO verses VALUES (27386, 44, 11, 20, 'eram e/mas alguns de deles homens Cipriotas e Cireneus os-quais vindo para Antioquia falavam e junto-a o Gregos evangelizando o Kyrion Iesous');
INSERT INTO verses VALUES (27387, 44, 11, 21, 'e era mão do-Kyrios com deles muito e número o tendo-crido voltou sobre o Kyrion');
INSERT INTO verses VALUES (27388, 44, 11, 22, 'Foi-ouvido porém o palavra para o ouvidos o da-assembleia o sendo em Jerusalém acerca-de deles e enviaram-embora Barnabé até Antioquia');
INSERT INTO verses VALUES (27389, 44, 11, 23, 'o qual tendo-chegado e vendo o graça o o de-Theos alegrou-se e suplicava todos o propósito o do-coração permanecer-junto o ao-Kyrios');
INSERT INTO verses VALUES (27390, 44, 11, 24, 'que era homem bom e cheio do-espírito do-santo e da-fé e foi-acrescentado multidão digno o ao-Kyrios');
INSERT INTO verses VALUES (27391, 44, 11, 25, 'saiu porém para Tarso buscar Saulo');
INSERT INTO verses VALUES (27392, 44, 11, 26, 'e encontrando conduziu para Antioquia aconteceu porém a-eles e ano todo ser-reunidos em o na-igreja e ensinar multidão suficiente advertir-divinamente e primeiramente em Antioquia o discípulos Cristãos');
INSERT INTO verses VALUES (27393, 44, 11, 27, 'em estas porém o dias desceram de Jerusalém profetas para Antioquia');
INSERT INTO verses VALUES (27394, 44, 11, 28, 'levantando-se porém um de deles em-nome Ágabo Significava através-de o do-espírito fome grande estar-prestes ser sobre toda o mundo-habitado a-qual aconteceu sobre Cláudio');
INSERT INTO verses VALUES (27395, 44, 11, 29, 'o porém discípulos assim-como prosperava alguém Determinaram cada-um deles para serviço enviar o habitam em o Judeia aos-irmãos');
INSERT INTO verses VALUES (27396, 44, 11, 30, 'o qual e fizeram tendo-enviado junto-a o anciãos através-de da-mão Barnabé e Saulo');
INSERT INTO chapters VALUES (1030, 44, 12, 25);
INSERT INTO verses VALUES (27397, 44, 12, 1, 'segundo aquele porém o tempo lançou-sobre Herodes o rei o mãos maltratar alguns o de o da-assembleia');
INSERT INTO verses VALUES (27398, 44, 12, 2, 'matou porém Tiago o irmão João espada');
INSERT INTO verses VALUES (27399, 44, 12, 3, 'vendo porém que agradável é o judeus acrescentou prender e Pedro eram porém dias o ázimos');
INSERT INTO verses VALUES (27400, 44, 12, 4, 'o qual e tendo-agarrado pôs para prisão entregando quatro quaterniões soldados guardar ele querendo com o páscoa conduzir-para-cima ele o povo');
INSERT INTO verses VALUES (27401, 44, 12, 5, 'o por-um-lado portanto Pedro Era-guardado em o na-prisão oração porém era fervorosamente acontecendo sob o da-assembleia junto-a o Theos acerca-de dele');
INSERT INTO verses VALUES (27402, 44, 12, 6, 'Quando porém estava-prestes-a trazer-adiante ele o Herodes o à-noite naquela era o Pedro dormindo entre dois soldados amarrado cadeias dois guardas e antes-de o porta guardavam o prisão');
INSERT INTO verses VALUES (27403, 44, 12, 7, 'e eis anjo do-Kyrios apresentou-se e luz resplandeceu em o cela tendo-ferido porém o lado o de-Pedro ressuscitou ele dizendo Levanta-te em brevemente e caíram dele o cadeias de o mãos');
INSERT INTO verses VALUES (27404, 44, 12, 8, 'disse porém o anjo junto-a ele Cinge-te e Calça o sandálias teu fez porém assim e diz a ele Veste-te o Veste teu e segue a-mim');
INSERT INTO verses VALUES (27405, 44, 12, 9, 'e saindo seguia e não sei que verdadeiro é o acontecendo através-de o anjo parecia porém visão ver');
INSERT INTO verses VALUES (27406, 44, 12, 10, 'atravessando porém primeiro prisão e segunda vieram sobre o porta o de-ferro o carregando para o cidade a-qual por-si-mesma abriu-se a-eles e saindo foram-adiante rua uma e imediatamente afastou-se o anjo de dele');
INSERT INTO verses VALUES (27407, 44, 12, 11, 'e o Pedro em si-mesmo tendo-se-tornado disse agora sei verdadeiramente que enviou-embora o Kyrios o anjo dele e livrou me de da-mão de-Herodes e toda o expectativa o povo o judeus');
INSERT INTO verses VALUES (27408, 44, 12, 12, 'tendo-percebido e veio sobre o casa o Maria o mãe João o invocando Marcos do-qual eram suficientes tendo-sido-reunidos e orando');
INSERT INTO verses VALUES (27409, 44, 12, 13, 'tendo-batido porém dele o porta o portão aproximou-se serva Obedecer em-nome Rode');
INSERT INTO verses VALUES (27410, 44, 12, 14, 'e tendo-conhecido-plenamente o voz o de-Pedro de o alegria não abriu o portão tendo-corrido-para-dentro porém anunciou estar-de-pé o Pedro antes-de o portão');
INSERT INTO verses VALUES (27411, 44, 12, 15, 'o porém junto-a ela disseram Enlouqueces o porém afirmava-com-insistência assim ter o porém diziam o anjo é dele');
INSERT INTO verses VALUES (27412, 44, 12, 16, 'o porém Pedro permanecia batendo tendo-aberto porém viram ele e ficaram-fora-de-si');
INSERT INTO verses VALUES (27413, 44, 12, 17, 'tendo-acenado porém a-eles o mão calar narrou a-eles como o Kyrios ele conduziu-fora de o prisão disse e Anunciai Jacó e o aos-irmãos estas-coisas e saindo foi para outro lugar');
INSERT INTO verses VALUES (27414, 44, 12, 18, 'Tendo-acontecido porém do-dia era tumulto não pouco em o soldados quê então o Pedro aconteceu');
INSERT INTO verses VALUES (27415, 44, 12, 19, 'Herodes porém tendo-buscado ele e não encontrando tendo-examinado o guardas ordenou ser-levado e tendo-descido de o Judeia para Cesareia permanecia');
INSERT INTO verses VALUES (27416, 44, 12, 20, 'era porém furioso Tírios e Sidônios unanimemente porém estavam-presentes junto-a ele e tendo-persuadido Blasto o sobre o quarto o rei pediam paz através-de o ser-alimentado deles o região de o real');
INSERT INTO verses VALUES (27417, 44, 12, 21, 'designada porém dia o Herodes tendo-vestido veste real sentando-se sobre o tribunal discursava junto-a eles');
INSERT INTO verses VALUES (27418, 44, 12, 22, 'o porém povo clamava de-Theos voz e não do-homem');
INSERT INTO verses VALUES (27419, 44, 12, 23, 'imediatamente porém feriu ele anjo do-Kyrios em-vez-de o qual não deu o glória o a-Theos e tendo-se-tornado comido-por-vermes expirou');
INSERT INTO verses VALUES (27420, 44, 12, 24, 'o porém palavra o do-Kyrios crescia e multiplicava-se');
INSERT INTO verses VALUES (27421, 44, 12, 25, 'Barnabé porém e Saulo retornaram de Jerusalém tendo-cumprido o serviço tendo-levado-consigo João o tendo-sido-chamado Marcos');
INSERT INTO chapters VALUES (1031, 44, 13, 52);
INSERT INTO verses VALUES (27422, 44, 13, 1, 'eram porém em Antioquia segundo o sendo igreja profetas e mestres o e Barnabé e Simeão o chamado Níger e Lúcio o Cireneu Manaém e de-Herodes o de-tetrarca criado-junto e Saulo');
INSERT INTO verses VALUES (27423, 44, 13, 2, 'Ministrando porém deles o ao-Kyrios e jejuando disse o espírito o santo Separai pois a-mim o Barnabé e Saulo para o obra o qual tenho-sido-chamado eles');
INSERT INTO verses VALUES (27424, 44, 13, 3, 'então tendo-jejuado e tendo-orado e tendo-posto-sobre o mãos a-eles soltaram');
INSERT INTO verses VALUES (27425, 44, 13, 4, 'Eles-mesmos por-um-lado portanto tendo-sido-enviados-fora sob o do-santo do-espírito desceram para Selêucia dali e navegaram para Chipre');
INSERT INTO verses VALUES (27426, 44, 13, 5, 'e tendo-se-tornado em Salamina anunciavam o palavra o de-Theos em o nas-sinagogas o judeus tinham porém e João servo');
INSERT INTO verses VALUES (27427, 44, 13, 6, 'atravessando porém toda o ilha até Pafos encontraram homem algum mago falso-profeta Judeu o qual nome Bar-Iesous');
INSERT INTO verses VALUES (27428, 44, 13, 7, 'o qual era com o procônsul Sérgio a-Paulo marido prudente este tendo-chamado Barnabé e Saulo buscou ouvir o palavra o de-Theos');
INSERT INTO verses VALUES (27429, 44, 13, 8, 'resistia porém a-eles Elimas o mago assim pois é-traduzido o nome dele buscando perverter o procônsul de o da-fé');
INSERT INTO verses VALUES (27430, 44, 13, 9, 'Saulo e/mas o e Paulo tendo-sido-preenchido do-espírito do-santo fitando-os-olhos para ele');
INSERT INTO verses VALUES (27431, 44, 13, 10, 'disse Ômega cheio de-todo engano e toda vilania filho diabo Inimigo toda da-justiça não cesse pervertendo o caminhos o do-Kyrios o retas');
INSERT INTO verses VALUES (27432, 44, 13, 11, 'e agora eis mão do-Kyrios sobre te e serás cego não vendo o sol até tempo imediatamente porém caiu sobre ele névoa e trevas e andando-ao-redor buscava condutores-pela-mão');
INSERT INTO verses VALUES (27433, 44, 13, 12, 'então vendo o procônsul o tendo-acontecido creu estando-assombrado sobre o em-ensino o do-Kyrios');
INSERT INTO verses VALUES (27434, 44, 13, 13, 'Tendo-navegado porém de o Pafos o acerca-de Paulo vieram para Perge o Panfília João porém tendo-se-retirado de deles retornou para Jerusalém');
INSERT INTO verses VALUES (27435, 44, 13, 14, 'Eles-mesmos porém atravessando de o Perge apresentaram-se para Antioquia o Pisídia e vindo para o sinagoga o dia o sábados sentaram-se');
INSERT INTO verses VALUES (27436, 44, 13, 15, 'com porém o leitura o da-lei e o profetas enviaram o chefes-da-sinagoga junto-a eles dizendo Homens irmãos se quem é em a-vós palavra da-consolação junto-a o povo dizeis');
INSERT INTO verses VALUES (27437, 44, 13, 16, 'levantando-se porém Paulo e tendo-acenado o mão disse Homens Israelitas e o tementes o Theos ouvi');
INSERT INTO verses VALUES (27438, 44, 13, 17, 'o Theos o povo deste Israel escolheu o pais nosso e o povo exaltou em o em-peregrinação em terra Egito e com braço Alto conduziu-fora eles de dela');
INSERT INTO verses VALUES (27439, 44, 13, 18, 'e como de-quarenta-anos tempo Suportou-os-modos eles em o deserto');
INSERT INTO verses VALUES (27440, 44, 13, 19, 'e tendo-derrubado nações sete em terra Canaã deu-como-herança o terra deles');
INSERT INTO verses VALUES (27441, 44, 13, 20, 'como anos quatrocentos e cinquenta e com estas-coisas deu juízes até Samuel profeta');
INSERT INTO verses VALUES (27442, 44, 13, 21, 'e-de-lá pediram rei e deu a-eles o Theos o Saul Filho E-para homem de tribo Benjamim anos quarenta');
INSERT INTO verses VALUES (27443, 44, 13, 22, 'e tendo-removido ele ressuscitou o Davi a-eles para rei o qual e disse tendo-testemunhado Encontraram Davi o o Jessé homem segundo o coração meu o qual fará todas-as-coisas o vontades meu');
INSERT INTO verses VALUES (27444, 44, 13, 23, 'deste o Theos de o semente segundo promessa conduziu o Israel Salvador Iesous');
INSERT INTO verses VALUES (27445, 44, 13, 24, 'tendo-proclamado-de-antemão João antes-de face o entrada dele batismo arrependimento todo o povo Israel');
INSERT INTO verses VALUES (27446, 44, 13, 25, 'como porém Cumpria João o corrida dizia quê mim Supondes ser não sou eu mas eis vem com mim o qual não sou digno o sandália o pés abrir');
INSERT INTO verses VALUES (27447, 44, 13, 26, 'Homens irmãos filhos raça Abraão e o em a-vós tementes o Theos a-nós o palavra o salvação desta foi-enviado-para-fora');
INSERT INTO verses VALUES (27448, 44, 13, 27, 'o pois habitando em Jerusalém e o governantes deles este tendo-ignorado e o vozes o profetas o segundo todo sábado sendo-lidas tendo-julgado cumpriram');
INSERT INTO verses VALUES (27449, 44, 13, 28, 'e nenhuma causa da-morte tendo-encontrado pediram Pilatos ser-morto ele');
INSERT INTO verses VALUES (27450, 44, 13, 29, 'como porém completaram todas-as-coisas o acerca-de dele escritas tendo-derrubado de o árvore puseram para túmulo');
INSERT INTO verses VALUES (27451, 44, 13, 30, 'o porém Theos ressuscitou ele de mortos');
INSERT INTO verses VALUES (27452, 44, 13, 31, 'o qual apareceu sobre do-dia mais o tendo-subido-com a ele de o Galileia para Jerusalém os-quais agora são testemunhas dele junto-a o povo');
INSERT INTO verses VALUES (27453, 44, 13, 32, 'e nós vos anunciamos-boas-novas o junto-a o pais promessa acontecida');
INSERT INTO verses VALUES (27454, 44, 13, 33, 'que esta o Theos tem-cumprido-plenamente o filhos nosso tendo-levantado Iesous como e em o salmo está-escrito o segundo filho meu és tu eu hoje gerei te');
INSERT INTO verses VALUES (27455, 44, 13, 34, 'que porém levantou ele de mortos não-mais as-coisas-futuras retornar para corrupção assim tem-dito que darei a-vós o santas-coisas Davi o fiéis');
INSERT INTO verses VALUES (27456, 44, 13, 35, 'porque e em a-outro diz não darás o Santo teu ver corrupção');
INSERT INTO verses VALUES (27457, 44, 13, 36, 'Davi por-um-lado pois em-particular geração Tendo-servido o o de-Theos conselho adormeceu e foi-acrescentado junto-a o pais dele e viu corrupção');
INSERT INTO verses VALUES (27458, 44, 13, 37, 'o qual porém o Theos ressuscitou não viu corrupção');
INSERT INTO verses VALUES (27459, 44, 13, 38, 'conhecido portanto seja a-vós homens irmãos que através-de deste a-vós remissão dos-pecados é-anunciado e de todos o qual não fostes-capazes em lei de-Moisés ser-justificado');
INSERT INTO verses VALUES (27460, 44, 13, 39, 'em neste todo o crendo é-justificado');
INSERT INTO verses VALUES (27461, 44, 13, 40, 'vede portanto não venha-sobre o dito em o profetas');
INSERT INTO verses VALUES (27462, 44, 13, 41, 'Vede o desprezadores e maravilhai-vos e sede-destruídos que obra trabalho eu em o dias vosso obra o qual não não creiais se alguém narre-plenamente a-vós');
INSERT INTO verses VALUES (27463, 44, 13, 42, 'Saindo porém deles suplicavam para o entre sábado ser-falado a-eles o palavras estas-coisas');
INSERT INTO verses VALUES (27464, 44, 13, 43, 'tendo-sido-desatada porém o sinagoga seguiram muitos o judeus e o adorando prosélitos o a-Paulo e o Barnabé os-quais falando-a a-eles Persuadiam eles permanecer-junto o graça o de-Theos');
INSERT INTO verses VALUES (27465, 44, 13, 44, 'o porém vindo no-sábado quase toda o cidade reuniu-se ouvir o palavra o de-Theos');
INSERT INTO verses VALUES (27466, 44, 13, 45, 'vendo porém o judeus o multidões foram-cheios zelo e contradiziam o sob Paulo coisas-faladas blasfemando');
INSERT INTO verses VALUES (27467, 44, 13, 46, 'tendo-falado-com-ousadia e o Paulo e o Barnabé disseram a-vós era necessário primeiro ser-falado o palavra o de-Theos uma-vez-que rejeitais ele e não dignos julgais si-mesmos o eterno da-vida eis viramo-nos para o nações');
INSERT INTO verses VALUES (27468, 44, 13, 47, 'assim pois tem-ordenado a-nós o Kyrios Tenho-posto te para luz nações o ser te para salvação até último o da-terra');
INSERT INTO verses VALUES (27469, 44, 13, 48, 'ouvindo porém o nações Alegravam-se e glorificavam o palavra o do-Kyrios e creram quanto eram tendo-sido-designados para vida eterno');
INSERT INTO verses VALUES (27470, 44, 13, 49, 'era-divulgado porém o palavra o do-Kyrios através-de de-toda o região');
INSERT INTO verses VALUES (27471, 44, 13, 50, 'o porém judeus incitaram o adorando mulheres o decorosos e o primeiro o cidade e levantaram-contra perseguição sobre o Paulo e Barnabé e expulsaram eles de o fronteiras deles');
INSERT INTO verses VALUES (27472, 44, 13, 51, 'o porém tendo-sacudido-fora o poeira o pés sobre eles vieram para Icônio');
INSERT INTO verses VALUES (27473, 44, 13, 52, 'o e discípulos eram-preenchidos alegria e do-espírito do-santo');
INSERT INTO chapters VALUES (1032, 44, 14, 28);
INSERT INTO verses VALUES (27474, 44, 14, 1, 'aconteceu porém em Icônio segundo o ele entrar eles para o sinagoga o judeus e falar assim de-modo-que crer judeus e e gregos muito multidão');
INSERT INTO verses VALUES (27475, 44, 14, 2, 'o porém tendo-desobedecido judeus levantaram-contra e maltrataram o almas o nações segundo o dos-irmãos');
INSERT INTO verses VALUES (27476, 44, 14, 3, 'suficiente por-um-lado portanto tempo permaneceram falando-com-ousadia sobre o ao-Kyrios o ao-que-testemunha sobre o em-palavra o da-graça dele dando sinais e prodígios tornar-se através-de o mãos deles');
INSERT INTO verses VALUES (27477, 44, 14, 4, 'rasgou-se porém o multidão o cidade e o por-um-lado eram com o judeus o porém com o apóstolos');
INSERT INTO verses VALUES (27478, 44, 14, 5, 'como porém aconteceu ímpeto o nações e e judeus com o governantes deles ultrajar e apedrejar eles');
INSERT INTO verses VALUES (27479, 44, 14, 6, 'tendo-percebido refugiaram-se para o cidades o Licaônia Listra e Derbe e o região-ao-redor');
INSERT INTO verses VALUES (27480, 44, 14, 7, 'e-ali evangelizando eram');
INSERT INTO verses VALUES (27481, 44, 14, 8, 'e alguém homem impossível em Listra o pés sentava-se coxo de ventre mãe dele o qual nunca andou');
INSERT INTO verses VALUES (27482, 44, 14, 9, 'este ouvia o Paulo falando o qual fitando-os-olhos a ele e vendo que tem fé o ser-salvo');
INSERT INTO verses VALUES (27483, 44, 14, 10, 'disse grande com-voz Levanta-te sobre o pés teu reto e Saltou e andava');
INSERT INTO verses VALUES (27484, 44, 14, 11, 'o e multidões vendo o qual fez Paulo levantaram o voz deles Em-licaônico dizendo o theoi tendo-sido-assemelhados aos-homens desceram junto-a nos');
INSERT INTO verses VALUES (27485, 44, 14, 12, 'chamavam e o Barnabé Zeus o porém Paulo Hermes uma-vez-que ele era o liderando o da-palavra');
INSERT INTO verses VALUES (27486, 44, 14, 13, 'o e sacerdote o Zeus o sendo antes-de o cidade touros e grinaldas sobre o portões tendo-trazido com o às-multidões queria sacrificar');
INSERT INTO verses VALUES (27487, 44, 14, 14, 'ouvindo porém o apóstolos Barnabé e Paulo tendo-rasgado o vestes deles-mesmos saltaram-para-fora para o multidão gritando');
INSERT INTO verses VALUES (27488, 44, 14, 15, 'e dizendo Homens quê estas-coisas fazei e nós de-natureza-semelhante somos a-vós homens evangelizando vos de destes o vãs voltar sobre Theos vivendo o qual fez o céu e o terra e o mar e todas-as-coisas o em a-eles');
INSERT INTO verses VALUES (27489, 44, 14, 16, 'o qual em o tendo-passado gerações permitiu todas-as-coisas o nações ir o caminhos deles');
INSERT INTO verses VALUES (27490, 44, 14, 17, 'embora não sem-testemunho si-mesmo deixou fazendo-o-bem do-céu a-vós chuvas dando e tempos frutíferas saciando alimento e alegria o do-coração vosso');
INSERT INTO verses VALUES (27491, 44, 14, 18, 'e estas-coisas dizendo dificilmente cessaram o multidões o não sacrificar a-eles');
INSERT INTO verses VALUES (27492, 44, 14, 19, 'Sobrevieram porém de Antioquia e Icônio judeus e tendo-persuadido o multidões e tendo-apedrejado o Paulo arrastavam fora o cidade supondo ele ter-morrido');
INSERT INTO verses VALUES (27493, 44, 14, 20, 'tendo-cercado porém o discípulos ele levantando-se entrou para o cidade e o no-dia-seguinte saiu com o Barnabé para Derbe');
INSERT INTO verses VALUES (27494, 44, 14, 21, 'anunciando-boas-novas e o cidade aquela e tendo-feito-discípulos suficientes retornaram para o Listra e para Icônio e para Antioquia');
INSERT INTO verses VALUES (27495, 44, 14, 22, 'fortalecendo o almas o discípulos exortando permanecer o fé e que através-de muitos tribulações é necessário nos entrar para o reino o de-Theos');
INSERT INTO verses VALUES (27496, 44, 14, 23, 'tendo-escolhido-por-mãos-estendidas porém a-eles segundo igreja anciãos tendo-orado com jejuns confiaram eles o ao-Kyrios para o qual tinham-crido');
INSERT INTO verses VALUES (27497, 44, 14, 24, 'e atravessando o Pisídia vieram para o Panfília');
INSERT INTO verses VALUES (27498, 44, 14, 25, 'e tendo-falado em Perge o palavra desceram para Atália');
INSERT INTO verses VALUES (27499, 44, 14, 26, 'e-de-lá navegaram para Antioquia de-onde eram tendo-sido-entregues o graça o de-Theos para o obra o qual cumpriram');
INSERT INTO verses VALUES (27500, 44, 14, 27, 'Tendo-chegado porém e tendo-reunido o igreja anunciavam quanto fez o Theos com deles e que abriu o nações porta da-fé');
INSERT INTO verses VALUES (27501, 44, 14, 28, 'permaneciam porém tempo não pouco com o discípulos');
INSERT INTO chapters VALUES (1033, 44, 15, 40);
INSERT INTO verses VALUES (27502, 44, 15, 1, 'e alguns tendo-descido de o Judeia ensinavam o irmãos que se não sejais-circuncidados o Costume o de-Moisés não podeis ser-salvo');
INSERT INTO verses VALUES (27503, 44, 15, 2, 'tendo-acontecido porém dissensão e investigação não pouca o a-Paulo e o Barnabé junto-a eles designaram subir Paulo e Barnabé e alguns outros de deles junto-a o apóstolos e anciãos para Jerusalém acerca-de o questão deste');
INSERT INTO verses VALUES (27504, 44, 15, 3, 'o por-um-lado portanto tendo-sido-enviados-adiante sob o da-assembleia atravessavam o e Fenícia e Samaria narrando-plenamente o conversão o nações e faziam alegria grande todos o aos-irmãos');
INSERT INTO verses VALUES (27505, 44, 15, 4, 'tendo-chegado porém para Jerusalém foram-aceitos de o da-assembleia e o apóstolos e o dos-anciãos anunciaram e quanto o Theos fez com deles');
INSERT INTO verses VALUES (27506, 44, 15, 5, 'Levantaram-se e/mas alguns o de o heresia o fariseus tendo-crido dizendo que é necessário circuncidar eles ordenar e guardar o lei de-Moisés');
INSERT INTO verses VALUES (27507, 44, 15, 6, 'Foram-reunidos e o apóstolos e o anciãos ver acerca-de o da-palavra deste');
INSERT INTO verses VALUES (27508, 44, 15, 7, 'Muita porém investigação tendo-acontecido levantando-se Pedro disse junto-a eles Homens irmãos vós sabeis que de dos-dias antigos em a-vós escolheu o Theos através-de o boca meu ouvir o nações o palavra o evangelho e crer');
INSERT INTO verses VALUES (27509, 44, 15, 8, 'e o conhecedor-de-corações Theos testemunhou a-eles dando o espírito o santo assim-como e a-nós');
INSERT INTO verses VALUES (27510, 44, 15, 9, 'e nada distinguiu entre nosso e e deles o fé tendo-purificado o do-coração deles');
INSERT INTO verses VALUES (27511, 44, 15, 10, 'agora portanto quê tentais o Theos impor balança sobre o pescoço o discípulos o qual nem o pais nosso nem nós fomos-capazes suportar');
INSERT INTO verses VALUES (27512, 44, 15, 11, 'mas através-de o da-graça o do-Kyrios Iesous cremos ser-salvo segundo o qual modo e-aqueles');
INSERT INTO verses VALUES (27513, 44, 15, 12, 'Calou-se porém todo o multidão e ouviam Barnabé e Paulo narrando quanto fez o Theos sinais e prodígios em o nações através-de deles');
INSERT INTO verses VALUES (27514, 44, 15, 13, 'com porém o calar eles respondeu Tiago dizendo Homens irmãos ouvi meu');
INSERT INTO verses VALUES (27515, 44, 15, 14, 'Simeão relatou assim-como primeiro o Theos visitou receber de nações povo o em-nome dele');
INSERT INTO verses VALUES (27516, 44, 15, 15, 'e neste concordam o palavras o profetas assim-como está-escrito');
INSERT INTO verses VALUES (27517, 44, 15, 16, 'com estas-coisas retornarei e reedificarei o tabernáculo Davi o tendo-caído e o tendo-sido-arruinados dela reedificarei e endireitarei ela');
INSERT INTO verses VALUES (27518, 44, 15, 17, 'para-que partícula-condicional busquem-diligentemente o restantes o dos-homens o Kyrion e todas-as-coisas o nações sobre o qual tem-sido-chamado o nome meu sobre eles diz Kyrios fazendo estas-coisas');
INSERT INTO verses VALUES (27519, 44, 15, 18, 'conhecidas de eternidade');
INSERT INTO verses VALUES (27520, 44, 15, 19, 'por-isso eu julgo não causar-perturbação o de o nações convertem-se sobre o Theos');
INSERT INTO verses VALUES (27521, 44, 15, 20, 'mas escrever a-eles o abster-se o contaminações o ídolos e o imoralidade e sufocado e o sangue');
INSERT INTO verses VALUES (27522, 44, 15, 21, 'Moisés pois de gerações antigos segundo cidade o proclamando ele tem em o nas-sinagogas segundo todo sábado sendo-lido');
INSERT INTO verses VALUES (27523, 44, 15, 22, 'Então pareceu o apóstolos e o presbíteros com toda o na-igreja tendo-escolhido homens de deles enviar para Antioquia com o a-Paulo e Barnabé Judas o chamado Barsabás e Silas homens líderes em o aos-irmãos');
INSERT INTO verses VALUES (27524, 44, 15, 23, 'tendo-escrito através-de da-mão deles o apóstolos e o anciãos irmãos o segundo o Antioquia e Síria e Cilícia aos-irmãos o de nações alegrar-se');
INSERT INTO verses VALUES (27525, 44, 15, 24, 'Porquanto ouvimos que alguns de nosso perturbaram vos palavras perturbando o almas vosso o qual não ordenamos');
INSERT INTO verses VALUES (27526, 44, 15, 25, 'pareceu a-nós tendo-acontecido unanimemente tendo-escolhido homens enviar junto-a vos com o amados nosso Barnabé e a-Paulo');
INSERT INTO verses VALUES (27527, 44, 15, 26, 'aos-homens aos-que-tinham-entregado o almas deles em-favor-de o do-nome o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (27528, 44, 15, 27, 'temos-enviado portanto Judas e Silas e eles através-de da-palavra anunciando o elas');
INSERT INTO verses VALUES (27529, 44, 15, 28, 'pareceu pois o Espírito o no-santo e a-nós nada mais Pôr-sobre a-vós peso porém destes o necessariamente');
INSERT INTO verses VALUES (27530, 44, 15, 29, 'abster-se sacrificado-a-ídolos e sangue e sufocados e imoralidade de o qual guardando si-mesmos bem praticareis Passai-bem');
INSERT INTO verses VALUES (27531, 44, 15, 30, 'o por-um-lado portanto tendo-sido-soltos desceram para Antioquia e tendo-reunido o multidão entregaram o carta');
INSERT INTO verses VALUES (27532, 44, 15, 31, 'tendo-lido porém alegraram-se sobre o consolação');
INSERT INTO verses VALUES (27533, 44, 15, 32, 'Judas e e Silas e eles-mesmos profetas sendo através-de da-palavra grande suplicaram o irmãos e fortaleceram');
INSERT INTO verses VALUES (27534, 44, 15, 33, 'tendo-feito porém tempo foram-soltos com paz de o dos-irmãos junto-a o os-que-enviaram eles');
INSERT INTO verses VALUES (27535, 44, 15, 35, 'Paulo porém e Barnabé permaneciam em Antioquia ensinando e evangelizando com e outros muitos o palavra o do-Kyrios');
INSERT INTO verses VALUES (27536, 44, 15, 36, 'com e/mas alguns do-dia disse junto-a Barnabé Paulo Tendo-retornado pois visitemos o irmãos segundo cidade toda em o qual anunciamos o palavra o do-Kyrios como têm');
INSERT INTO verses VALUES (27537, 44, 15, 37, 'Barnabé porém queria levar-consigo e o João o chamado Marcos');
INSERT INTO verses VALUES (27538, 44, 15, 38, 'Paulo porém considerava-digno o tendo-se-afastado de deles de Panfília e não tendo-se-reunido a-eles para o obra não levar-consigo este');
INSERT INTO verses VALUES (27539, 44, 15, 39, 'aconteceu porém provocação de-modo-que serem-separados eles de uns-aos-outros o e Barnabé tendo-tomado o Marcos navegar-para-fora para Chipre');
INSERT INTO verses VALUES (27540, 44, 15, 40, 'Paulo porém tendo-escolhido Silas saiu tendo-sido-entregue o graça o do-Kyrios sob o dos-irmãos');
INSERT INTO verses VALUES (27541, 44, 15, 41, 'atravessava porém o Síria e Cilícia fortalecendo o da-assembleia');
INSERT INTO chapters VALUES (1034, 44, 16, 40);
INSERT INTO verses VALUES (27542, 44, 16, 1, 'Chegou porém e para Derbe e para Listra e eis discípulo alguém era ali em-nome Timóteo Filho mulher Judeia fiel do-Pai porém grego');
INSERT INTO verses VALUES (27543, 44, 16, 2, 'o qual era-testemunhado sob o em Listra e Icônio dos-irmãos');
INSERT INTO verses VALUES (27544, 44, 16, 3, 'este quis o Paulo com a ele sair e tomando circuncidou ele através-de o judeus o sendo em o lugares àqueles sei pois todos que grego o Pai dele existia');
INSERT INTO verses VALUES (27545, 44, 16, 4, 'como porém atravessavam o cidades entregavam a-eles guardar o decretos o tendo-sido-julgadas sob o apóstolos e dos-anciãos o em em-Jerusalém');
INSERT INTO verses VALUES (27546, 44, 16, 5, 'o por-um-lado portanto assembleias Eram-fortalecidos o fé e abundavam o número segundo dia');
INSERT INTO verses VALUES (27547, 44, 16, 6, 'Atravessaram porém o Frígia e Galática região tendo-sido-impedidos sob o do-santo do-espírito falar o palavra em o Ásia');
INSERT INTO verses VALUES (27548, 44, 16, 7, 'vindo porém segundo o Mísia tentavam para o Bitínia ir e não permitiu eles o espírito Iesous');
INSERT INTO verses VALUES (27549, 44, 16, 8, 'tendo-passado porém o Mísia desceram para Trôade');
INSERT INTO verses VALUES (27550, 44, 16, 9, 'e visão através-de da-noite o a-Paulo apareceu homem macedônio alguém era estando-de-pé e exortando ele e dizendo Tendo-atravessado para Macedônia socorre a-nós');
INSERT INTO verses VALUES (27551, 44, 16, 10, 'como porém o visão viu imediatamente buscamos sair para Macedônia unindo que tem-sido-chamado nos o Theos evangelizar eles');
INSERT INTO verses VALUES (27552, 44, 16, 11, 'Tendo-navegado porém de Trôade navegamos-em-linha-reta para Samotrácia o porém seguinte para Nova cidade');
INSERT INTO verses VALUES (27553, 44, 16, 12, 'e-de-lá para Filipos a-qual é primeiro o porção Macedônia cidade colônia Éramos porém em nesta o na-cidade permanecendo do-dia alguns');
INSERT INTO verses VALUES (27554, 44, 16, 13, 'o e dia o sábados saímos fora o porta de-junto-de rio do-qual considerávamos oração ser e tendo-sentado falávamos o tendo-se-reunido mulheres');
INSERT INTO verses VALUES (27555, 44, 16, 14, 'e alguém mulher em-nome Lídia vendedora-de-púrpura cidade Tiatira adorando o Theos ouvia o qual o Kyrios abriu o coração atentar o coisas-faladas sob Paulo');
INSERT INTO verses VALUES (27556, 44, 16, 15, 'como porém foi-batizado e o casa dela exortou dizendo se tendes-julgado me fiel o ao-Kyrios ser entrando para o casa meu permanecei e constrangeu nos');
INSERT INTO verses VALUES (27557, 44, 16, 16, 'aconteceu porém indo nosso para o oração serva algum tendo espírito Píton encontrar a-nós a-qual trabalho muita fornecia o senhores dela adivinhando');
INSERT INTO verses VALUES (27558, 44, 16, 17, 'esta seguindo o a-Paulo e a-nós gritava dizendo estas o homens servos o de-Theos o Altíssimo são os-quais anunciam a-vós caminho salvação');
INSERT INTO verses VALUES (27559, 44, 16, 18, 'isto porém fazia sobre muitas do-dia tendo-se-indignado porém Paulo e tendo-virado o espírito disse ordeno a-ti em em-nome Iesous de-Christos sair de dela e saiu a-ela o hora');
INSERT INTO verses VALUES (27560, 44, 16, 19, 'Tendo-visto porém o senhores dela que saiu o esperança o trabalho deles agarrando o Paulo e o Silas arrastaram para o praça sobre o governantes');
INSERT INTO verses VALUES (27561, 44, 16, 20, 'e tendo-conduzido eles o comandantes disseram estas o homens perturbam-grandemente nosso o cidade judeus existindo');
INSERT INTO verses VALUES (27562, 44, 16, 21, 'e anunciam costumes o qual não é-lícito a-nós aceitar nem fazer Romanos estando');
INSERT INTO verses VALUES (27563, 44, 16, 22, 'e levantou-se-junto o multidão segundo deles e o comandantes tendo-rasgado deles o vestes ordenavam açoitar-com-varas');
INSERT INTO verses VALUES (27564, 44, 16, 23, 'muitas porém tendo-posto-sobre a-eles golpes lançaram para prisão tendo-ordenado o carcereiro seguramente guardar eles');
INSERT INTO verses VALUES (27565, 44, 16, 24, 'o qual ordem tal tomando lançou eles para o Interior prisão e o pés Assegurou deles para o madeira/árvore');
INSERT INTO verses VALUES (27566, 44, 16, 25, 'segundo porém o meia-noite Paulo e Silas orando Cantavam-hinos o Theos escutavam porém deles o prisioneiros');
INSERT INTO verses VALUES (27567, 44, 16, 26, 'subitamente porém terremoto aconteceu grande de-modo-que ser-abalado o fundamentos o prisão foram-abertos porém imediatamente o portas todas e todos o cadeias subiu');
INSERT INTO verses VALUES (27568, 44, 16, 27, 'Desperto porém tendo-se-tornado o carcereiro e vendo tendo-sido-abertas o porta o prisão tendo-desembainhado o espada estava-prestes-a si-mesmo matar supondo ter-escapado o prisioneiros');
INSERT INTO verses VALUES (27569, 44, 16, 28, 'clamou porém Paulo grande com-voz dizendo nada pratiques a-ti-mesmo mal todos pois somos aqui');
INSERT INTO verses VALUES (27570, 44, 16, 29, 'tendo-pedido porém luzes saltou-para-dentro e tremendo tendo-se-tornado prostrou-se o a-Paulo e Silas');
INSERT INTO verses VALUES (27571, 44, 16, 30, 'e tendo-conduzido-adiante eles fora disse Kyrioses quê me é necessário fazer para que seja-salvo');
INSERT INTO verses VALUES (27572, 44, 16, 31, 'o porém disseram Crê sobre o Kyrion Iesous e serás-salvo tu e o casa teu');
INSERT INTO verses VALUES (27573, 44, 16, 32, 'e falaram a ele o palavra o de-Theos com todos o em o casa dele');
INSERT INTO verses VALUES (27574, 44, 16, 33, 'e tomando-consigo eles em naquela o hora o da-noite Lavou de o pragas e foi-batizado ele e o dele todos imediatamente');
INSERT INTO verses VALUES (27575, 44, 16, 34, 'tendo-levado-para-cima e eles para o casa pôs-diante mesa e exultou com-toda-a-casa tendo-crido o a-Theos');
INSERT INTO verses VALUES (27576, 44, 16, 35, 'do-dia porém tendo-acontecido enviaram o comandantes o portadores-de-varas dizendo Liberta o homens aqueles');
INSERT INTO verses VALUES (27577, 44, 16, 36, 'anunciou porém o carcereiro o palavras estes junto-a o Paulo que Têm-enviado o comandantes para que sejais-soltos agora portanto saindo ide em paz');
INSERT INTO verses VALUES (27578, 44, 16, 37, 'o porém Paulo disse junto-a eles Tendo-espancado nos publicamente incondenados homens Romanos possuindo Lançaram para prisão e agora secretamente nos expulsam não pois mas vindo eles-mesmos nos conduzam-para-fora');
INSERT INTO verses VALUES (27579, 44, 16, 38, 'anunciaram porém o comandantes o portadores-de-varas o palavras estas-coisas temeram porém ouvindo que Romanos são');
INSERT INTO verses VALUES (27580, 44, 16, 39, 'e vindo suplicaram eles e tendo-conduzido-para-fora perguntavam ir-embora de o cidade');
INSERT INTO verses VALUES (27581, 44, 16, 40, 'saindo porém de o prisão entraram junto-a o Lídia e vendo suplicaram o irmãos e saíram');
INSERT INTO chapters VALUES (1035, 44, 17, 34);
INSERT INTO verses VALUES (27582, 44, 17, 1, 'Tendo-percorrido porém o Anfípolis e o Apolônia vieram para Tessalônica onde era sinagoga o judeus');
INSERT INTO verses VALUES (27583, 44, 17, 2, 'segundo porém o costumado o a-Paulo entrou junto-a eles e sobre sábados três discutiu a-eles de o escrituras');
INSERT INTO verses VALUES (27584, 44, 17, 3, 'abrindo e pondo-diante que o Christos é necessário sofrer e levantar-se de mortos e que este é o Christos o Iesous o qual eu anuncio a-vós');
INSERT INTO verses VALUES (27585, 44, 17, 4, 'e alguns de deles foram-persuadidos e uniram-se o a-Paulo e o Silas o e adorando gregos multidão muito mulheres e o primeiro não poucas');
INSERT INTO verses VALUES (27586, 44, 17, 5, 'tendo-zelado porém o judeus e tendo-tomado-consigo o da-praça homens alguns maus e tendo-amotinado-multidão tumultuavam o cidade e tendo-se-apresentado o casa Jasão buscavam eles trazer-adiante para o povo');
INSERT INTO verses VALUES (27587, 44, 17, 6, 'não tendo-encontrado porém eles arrastavam Jasão e alguns irmãos sobre o politarcas clamando que o o mundo-habitado tendo-subvertido estes e aqui estão-presentes');
INSERT INTO verses VALUES (27588, 44, 17, 7, 'o qual Tem-recebido Jasão e estes todos diante-de o decretos de-César praticam rei outro dizendo ser Iesous');
INSERT INTO verses VALUES (27589, 44, 17, 8, 'perturbaram porém o multidão e o politarcas ouvintes estas-coisas');
INSERT INTO verses VALUES (27590, 44, 17, 9, 'e tendo-tomado o suficiente de-junto-de o Jasão e o restantes soltaram eles');
INSERT INTO verses VALUES (27591, 44, 17, 10, 'o porém irmãos imediatamente através-de da-noite enviaram-para-fora o e Paulo e o Silas para Bereia os-quais tendo-chegado para o sinagoga o judeus iam-embora');
INSERT INTO verses VALUES (27592, 44, 17, 11, 'estes porém eram mais-nobres o em Tessalônica os-quais receberam o palavra com toda prontidão o segundo dia examinando o escrituras se tivesse estas-coisas assim');
INSERT INTO verses VALUES (27593, 44, 17, 12, 'muitos por-um-lado portanto de deles creram e o Gregas mulheres o decorosos e homens não poucos');
INSERT INTO verses VALUES (27594, 44, 17, 13, 'como porém conheceram o de o Tessalônica judeus que e em o Bereia foi-anunciado sob o Paulo o palavra o de-Theos vieram e-ali abalando e perturbando o multidões');
INSERT INTO verses VALUES (27595, 44, 17, 14, 'imediatamente porém então o Paulo enviaram-embora o irmãos ir até sobre o mar Perseveraram e o e Silas e o Timóteo ali');
INSERT INTO verses VALUES (27596, 44, 17, 15, 'o porém estabelecendo o Paulo levaram até Atenas e tendo-tomado mandamento junto-a o Silas e o Timóteo para que como o-mais-rapidamente venham junto-a ele saíam');
INSERT INTO verses VALUES (27597, 44, 17, 16, 'em porém o Atenas esperando eles o Paulo era-provocado o espírito dele em a ele contemplando cheia-de-ídolos sendo o cidade');
INSERT INTO verses VALUES (27598, 44, 17, 17, 'discutia por-um-lado portanto em o na-sinagoga o judeus e o adorando e em o praça segundo toda dia junto-a o os-que-se-encontram');
INSERT INTO verses VALUES (27599, 44, 17, 18, 'alguns porém e o Epicureus e Estoicos filósofos conferiam a ele e alguns diziam quê partícula-condicional quisesse o tagarela este dizer o e/mas hospedagens demônios parece anunciador ser que o Iesous e o ressurreição anunciava-boa-nova');
INSERT INTO verses VALUES (27600, 44, 17, 19, 'tendo-tomado-de porém dele sobre o Areio colina levaram dizendo Podemos conhecer quem o nova esta o sob teu sendo-falada ensino');
INSERT INTO verses VALUES (27601, 44, 17, 20, 'estranhando pois alguém trazes-para-dentro para o ouvidos nosso queremos portanto conhecer quem quer estas-coisas ser');
INSERT INTO verses VALUES (27602, 44, 17, 21, 'Atenienses porém todos e o residindo estrangeiros para nada outro tinham-oportunidade ou dizer algo ou ouvir algo mais-novo');
INSERT INTO verses VALUES (27603, 44, 17, 22, 'Tendo-ficado-de-pé porém Paulo em no-meio o Areio Areópago disse Homens Atenienses segundo todas-as-coisas como mais-supersticiosos vos observo');
INSERT INTO verses VALUES (27604, 44, 17, 23, 'passando pois e observando-atentamente o objetos-de-adoração vosso encontraram e altar em o qual tinha-sido-inscrito DESCONHECIDO THEOS o qual portanto ignorando sois-piedosos isto eu anuncio a-vós');
INSERT INTO verses VALUES (27605, 44, 17, 24, 'o Theos o tendo-feito o mundo e todas-as-coisas o em a ele este do-céu e da-terra sendo Kyrios não em feitos-por-mãos templos habita');
INSERT INTO verses VALUES (27606, 44, 17, 25, 'nem sob mãos humanas é-curado necessitando de-alguém ele dando todos vida e fôlego e o todas-as-coisas');
INSERT INTO verses VALUES (27607, 44, 17, 26, 'fez e de de-um todo nação dos-homens habitar sobre de-todo face o da-terra tendo-determinado tendo-sido-ordenados tempos e o limites-determinados o habitações deles');
INSERT INTO verses VALUES (27608, 44, 17, 27, 'buscar o Theos se então pois tateassem ele e encontrassem e pois não longe de de-um cada-um nosso posses');
INSERT INTO verses VALUES (27609, 44, 17, 28, 'em a ele pois vivamos e movemo-nos e somos como e alguns o segundo vos fazedores têm-dito o pois e raça somos');
INSERT INTO verses VALUES (27610, 44, 17, 29, 'raça portanto existindo o de-Theos não devemos supor ouro ou prata ou pedra com-marca arte e pensamento do-homem o enxofre ser semelhante');
INSERT INTO verses VALUES (27611, 44, 17, 30, 'o por-um-lado portanto tempos o ignorância Tendo-desconsiderado o Theos o agora anuncia o aos-homens todos por-toda-parte arrepender-se');
INSERT INTO verses VALUES (27612, 44, 17, 31, 'assim-como estabeleceu dia em o qual está-para julgar o mundo-habitado em justiça em marido o qual Determinou fé tendo-fornecido todos tendo-levantado ele de mortos');
INSERT INTO verses VALUES (27613, 44, 17, 32, 'ouvindo porém ressurreição mortos o por-um-lado Zombavam o porém disseram Ouviremos teu acerca-de deste e novamente');
INSERT INTO verses VALUES (27614, 44, 17, 33, 'assim o Paulo saiu de meio deles');
INSERT INTO verses VALUES (27615, 44, 17, 34, 'alguns porém homens tendo-sido-unidos a ele creram em o qual e Dionísio o Areopagita e mulher em-nome Dâmaris e outros com a-eles');
INSERT INTO chapters VALUES (1036, 44, 18, 28);
INSERT INTO verses VALUES (27616, 44, 18, 1, 'com estas-coisas tendo-sido-separado de o Atenas veio para Corinto');
INSERT INTO verses VALUES (27617, 44, 18, 2, 'e tendo-encontrado alguém Judeu em-nome Áquila pôntico o raça recentemente tendo-vindo de o Itália e Priscila mulher dele através-de o ter-ordenado Cláudio separar-se todos o judeus de o Roma aproximou-se a-eles');
INSERT INTO verses VALUES (27618, 44, 18, 3, 'e através-de o do-mesmo-ofício ser permanecia de-junto-de a-eles e trabalhavam eram pois fabricantes-de-tendas o em-arte');
INSERT INTO verses VALUES (27619, 44, 18, 4, 'discutia porém em o na-sinagoga segundo todo sábado Persuadia e judeus e Gregos');
INSERT INTO verses VALUES (27620, 44, 18, 5, 'como porém desceram de o Macedônia o e Silas e o Timóteo era-constrangido o em-palavra o Paulo testificando o judeus ser o Christos Iesous');
INSERT INTO verses VALUES (27621, 44, 18, 6, 'opondo-se porém deles e blasfemando tendo-sacudido-fora o vestes disse junto-a eles o sangue vosso sobre o cabeça vosso puro eu de o agora para o nações irei');
INSERT INTO verses VALUES (27622, 44, 18, 7, 'e tendo-passado dali veio para casa algum em-nome Tício Justo adorando o Theos o qual o casa era fazendo-fronteira-com o na-sinagoga');
INSERT INTO verses VALUES (27623, 44, 18, 8, 'Crispo porém o chefe-da-sinagoga creu o ao-Kyrios com todo o na-casa dele e muitos o Coríntios ouvindo criam e eram-batizados');
INSERT INTO verses VALUES (27624, 44, 18, 9, 'disse porém o Kyrios em à-noite através-de visão o a-Paulo não temas mas fala e não cales-te');
INSERT INTO verses VALUES (27625, 44, 18, 10, 'porque eu sou com teu e ninguém imporá a-ti o maltratar te porque povo É a-mim muito em o na-cidade nesta');
INSERT INTO verses VALUES (27626, 44, 18, 11, 'Sentou-se porém ano e meses seis ensinando em a-eles o palavra o de-Theos');
INSERT INTO verses VALUES (27627, 44, 18, 12, 'Gálio porém procônsul sendo o Acaia levantaram-se-contra unanimemente o judeus o a-Paulo e levaram ele sobre o tribunal');
INSERT INTO verses VALUES (27628, 44, 18, 13, 'dizendo que de-junto-de o lei persuade este o homens adorar o Theos');
INSERT INTO verses VALUES (27629, 44, 18, 14, 'do-que-está-por-vir porém o Paulo abrir o boca disse o Gálio junto-a o judeus se por-um-lado era injustiça algo ou ato-perverso mau Ômega judeus segundo palavra partícula-condicional suportei vosso');
INSERT INTO verses VALUES (27630, 44, 18, 15, 'se porém questões é acerca-de da-palavra e nomes e da-lei o segundo vos vereis eles juiz eu destes não quero ser');
INSERT INTO verses VALUES (27631, 44, 18, 16, 'e expulsou eles de o tribunal');
INSERT INTO verses VALUES (27632, 44, 18, 17, 'agarrando porém todos Sóstenes o chefe-da-sinagoga batiam diante-de o tribunal e nada destes o Gálio importava');
INSERT INTO verses VALUES (27633, 44, 18, 18, 'o porém Paulo ainda tendo-permanecido do-dia suficientes o aos-irmãos despedindo-se navegava-para-fora para o Síria e com a ele Priscila e Áquila tendo-rapado em Cencreia o cabeça tinha pois voto');
INSERT INTO verses VALUES (27634, 44, 18, 19, 'chegaram porém para Éfeso e-aqueles deixou dele ele porém entrando para o sinagoga discutiu o judeus');
INSERT INTO verses VALUES (27635, 44, 18, 20, 'Perguntando porém deles sobre maiores tempo permanecer não consentiu');
INSERT INTO verses VALUES (27636, 44, 18, 21, 'mas despedindo-se e dizendo novamente retornarei junto-a vos o de-Theos querendo foi-levado-ao-mar de o Éfeso');
INSERT INTO verses VALUES (27637, 44, 18, 22, 'e tendo-descido para Cesareia subindo e tendo-saudado o igreja desceu para Antioquia');
INSERT INTO verses VALUES (27638, 44, 18, 23, 'e tendo-feito tempo algum saiu passando por-ordem o Galática região e Frígia firmando todos o discípulos');
INSERT INTO verses VALUES (27639, 44, 18, 24, 'judeu e/mas alguém Apolo em-nome Alexandrino o raça homem eloquente chegou para Éfeso poderoso sendo em o escrituras');
INSERT INTO verses VALUES (27640, 44, 18, 25, 'este era tendo-sido-instruído o caminho o do-Kyrios e fervendo o espírito falava e ensinava com-exatidão o acerca-de o Iesous sabendo somente o batismo João');
INSERT INTO verses VALUES (27641, 44, 18, 26, 'este e começou falar-com-ousadia em o na-sinagoga ouvindo porém dele Priscila e Áquila receberam-consigo ele e mais-exatamente a ele expuseram o caminho o de-Theos');
INSERT INTO verses VALUES (27642, 44, 18, 27, 'querendo porém dele atravessar para o Acaia tendo-exortado o irmãos Escreveram o discípulos receber ele o qual tendo-chegado contribuiu muito o tendo-crido através-de o da-graça');
INSERT INTO verses VALUES (27643, 44, 18, 28, 'vigorosamente pois o judeus refutava-vigorosamente publicamente mostrando através-de o escrituras ser o Christos Iesous');
INSERT INTO chapters VALUES (1037, 44, 19, 40);
INSERT INTO verses VALUES (27644, 44, 19, 1, 'aconteceu porém em o o Apolo ser em Corinto Paulo tendo-atravessado o superiores partes vir para Éfeso e encontrar alguns discípulos');
INSERT INTO verses VALUES (27645, 44, 19, 2, 'disse e junto-a eles se espírito santo recebestes tendo-crido o porém junto-a ele mas nem se espírito santo é ouvimos');
INSERT INTO verses VALUES (27646, 44, 19, 3, 'disse e para quê portanto fostes-batizados o porém disseram para o João batismo');
INSERT INTO verses VALUES (27647, 44, 19, 4, 'disse porém Paulo João batizou batismo arrependimento o povo dizendo para o o-que-vem com ele para que creiam isto é para o Iesous');
INSERT INTO verses VALUES (27648, 44, 19, 5, 'ouvindo porém foram-batizados para o nome o do-Kyrios Iesous');
INSERT INTO verses VALUES (27649, 44, 19, 6, 'e tendo-posto-sobre a-eles o Paulo mãos Veio o espírito o santo sobre eles falavam e em-línguas e Profetizavam');
INSERT INTO verses VALUES (27650, 44, 19, 7, 'eram porém o todos homens como doze');
INSERT INTO verses VALUES (27651, 44, 19, 8, 'Tendo-entrado porém para o sinagoga falava-com-ousadia sobre meses três discutindo e persuadindo acerca-de o do-reino o de-Theos');
INSERT INTO verses VALUES (27652, 44, 19, 9, 'como e/mas alguns Eram-endurecidos e desobedeciam amaldiçoando o caminho diante-de o multidão tendo-se-afastado de deles separou o discípulos segundo dia discutindo em o escola Tirano');
INSERT INTO verses VALUES (27653, 44, 19, 10, 'isto porém aconteceu sobre anos dois de-modo-que todos o habitantes o Ásia ouvir o palavra o do-Kyrios judeus e e Gregos');
INSERT INTO verses VALUES (27654, 44, 19, 11, 'poderes e não o tendo-obtido o Theos fazia através-de o mãos Paulo');
INSERT INTO verses VALUES (27655, 44, 19, 12, 'de-modo-que e sobre o enfermos ser-levado de o de-pele dele lenços ou aventais e ser-libertado de deles o doenças o e espíritos o má sair');
INSERT INTO verses VALUES (27656, 44, 19, 13, 'Empreenderam e/mas alguns e o andando-ao-redor judeus exorcistas nomear sobre o tendo o espíritos o má o nome o do-Kyrios Iesous dizendo Conjuro vos o Iesous o qual Paulo proclama');
INSERT INTO verses VALUES (27657, 44, 19, 14, 'eram e/mas de-alguém Ceva Judeu do-sumo-sacerdote sete filhos isto fazendo');
INSERT INTO verses VALUES (27658, 44, 19, 15, 'tendo-respondido porém o espírito o mau disse a-eles o Iesous conheço e o Paulo conheço vós porém quem sois');
INSERT INTO verses VALUES (27659, 44, 19, 16, 'e Tendo-saltado-sobre o homem sobre eles em o qual era o espírito o mau tendo-dominado ambos prevaleceu segundo deles de-modo-que nus e tendo-sido-feridos escapar de o da-casa daquele');
INSERT INTO verses VALUES (27660, 44, 19, 17, 'isto porém aconteceu conhecido todos judeus e e gregos o habitam o Éfeso e caiu-sobre medo sobre todos eles e era-engrandecido o nome o do-Kyrios Iesous');
INSERT INTO verses VALUES (27661, 44, 19, 18, 'muitos e o dos-que-creram vinham confessando e anunciando o ações deles');
INSERT INTO verses VALUES (27662, 44, 19, 19, 'suficientes porém o o curiosas tendo-praticado tendo-carregado-junto o livros queimavam diante-de todos e contaram-junto o honras deles e encontraram prata miríades cinco');
INSERT INTO verses VALUES (27663, 44, 19, 20, 'assim segundo domínio o do-Kyrios o palavra crescia e era-capaz');
INSERT INTO verses VALUES (27664, 44, 19, 21, 'como porém foi-cumprido estas-coisas pôs o Paulo em o espírito tendo-passado o Macedônia e Acaia ir para Jerusalém dizendo que com o tornar-se me ali é necessário me e Roma ver');
INSERT INTO verses VALUES (27665, 44, 19, 22, 'enviando porém para o Macedônia dois o servindo a ele Timóteo e Erasto ele deteve tempo para o Ásia');
INSERT INTO verses VALUES (27666, 44, 19, 23, 'aconteceu porém segundo o tempo aquele tumulto não pouco acerca-de o do-caminho');
INSERT INTO verses VALUES (27667, 44, 19, 24, 'Demétrio pois alguém em-nome ourives-de-prata fazendo templos de-prata Ártemis fornecia o artífices não pouca trabalho');
INSERT INTO verses VALUES (27668, 44, 19, 25, 'o qual tendo-reunido e o acerca-de o tais-coisas trabalhadores disse Homens sabeis que de desta o trabalho o prosperidade a-nós é');
INSERT INTO verses VALUES (27669, 44, 19, 26, 'e contemplais e ouvi que não somente Éfeso mas quase toda o Ásia o Paulo este tendo-persuadido removeu suficiente multidão dizendo que não são theoi o através-de mãos tornando-se');
INSERT INTO verses VALUES (27670, 44, 19, 27, 'não somente porém isto corre-perigo a-nós o parte para descrédito vir mas e o o grande deus Ártemis templo para nada ser-considerado estar-prestes e e ser-demolido o grandeza dela o qual toda o Ásia e o terra-habitada adora');
INSERT INTO verses VALUES (27671, 44, 19, 28, 'Tendo-ouvido porém e tendo-se-tornado cheios ira clamavam dizendo grande o Ártemis efésios');
INSERT INTO verses VALUES (27672, 44, 19, 29, 'e encheu-se o cidade o confusão Precipitaram-se e unanimemente para o teatro tendo-arrebatado Gaio e Aristarco Macedônios com-viajantes Paulo');
INSERT INTO verses VALUES (27673, 44, 19, 30, 'Paulo porém querendo entrar para o povo não permitiam ele o discípulos');
INSERT INTO verses VALUES (27674, 44, 19, 31, 'alguns porém e o Asiarcas sendo a ele amigos tendo-enviado junto-a ele suplicavam não dar si-mesmo para o teatro');
INSERT INTO verses VALUES (27675, 44, 19, 32, 'outros por-um-lado portanto outro algo clamavam era pois o assembleia tendo-sido-confundida e o mais não sei de-quem por-causa-de tinham-se-reunido');
INSERT INTO verses VALUES (27676, 44, 19, 33, 'de porém o da-multidão concluíram Alexandre tendo-brotado ele o judeus o porém Alexandre tendo-acenado o mão queria defender-se o povo');
INSERT INTO verses VALUES (27677, 44, 19, 34, 'reconhecendo porém que judeu é voz aconteceu uma de todos como sobre hora dois gritando grande o Ártemis efésios');
INSERT INTO verses VALUES (27678, 44, 19, 35, 'tendo-acalmado porém o escriba o multidão diz Homens Efésios quem pois é dos-homens o qual não conhece o efésios cidade guardiã-do-templo sendo o grande Ártemis e o caído-do-céu');
INSERT INTO verses VALUES (27679, 44, 19, 36, 'incontestáveis portanto existindo destes é necessário é vos acalmados existir e nada precipitado praticar');
INSERT INTO verses VALUES (27680, 44, 19, 37, 'conduzistes pois o homens estes nem Sacrílegos nem blasfemando o Theos nosso');
INSERT INTO verses VALUES (27681, 44, 19, 38, 'se por-um-lado portanto Demétrio e o com a ele artífices Têm para alguém palavra dias-de-tribunal são-conduzidos e procônsules são acusem uns-aos-outros');
INSERT INTO verses VALUES (27682, 44, 19, 39, 'se e/mas algo mais-além buscais em o legítima na-igreja será-desatada');
INSERT INTO verses VALUES (27683, 44, 19, 40, 'e pois corremos-perigo ser-acusado dissensão acerca-de o hoje nenhum causa existindo acerca-de o qual não poderemos retribuir palavra acerca-de o de-ajuntamento desta e estas-coisas dizendo soltou o igreja');
INSERT INTO chapters VALUES (1038, 44, 20, 38);
INSERT INTO verses VALUES (27684, 44, 20, 1, 'com porém o cessar o tumulto tendo-mandado-buscar o Paulo o discípulos e tendo-exortado tendo-saudado saiu ir para Macedônia');
INSERT INTO verses VALUES (27685, 44, 20, 2, 'tendo-passado porém o partes aquelas-coisas e tendo-exortado eles em-palavra muito veio para o Grécia');
INSERT INTO verses VALUES (27686, 44, 20, 3, 'tendo-feito e meses três tendo-acontecido conspiração a ele sob o judeus vindouro zarpar para o Síria aconteceu parecer o retornar através-de Macedônia');
INSERT INTO verses VALUES (27687, 44, 20, 4, 'seguia-com porém a ele Sópatro Pirro Bereiano Tessalonicenses porém Aristarco e Segundo e Gaio De-Derbe e Timóteo Asianos porém Tíquico e Trófimo');
INSERT INTO verses VALUES (27688, 44, 20, 5, 'estes porém tendo-ido-adiante Permaneciam nos em Trôade');
INSERT INTO verses VALUES (27689, 44, 20, 6, 'nós porém navegamos-para-fora com o do-dia o ázimos de Filipos e viemos junto-a eles para o Trôade até dos-dias cinco onde permanecemos do-dia sete');
INSERT INTO verses VALUES (27690, 44, 20, 7, 'em porém o uma o sábados tendo-sido-reunidos nosso partir pão o Paulo discutia a-eles estando-prestes-a sair o no-dia-seguinte prolongou e o palavra até meia-noite');
INSERT INTO verses VALUES (27691, 44, 20, 8, 'eram porém tochas Suficientes em o quarto-superior do-qual éramos tendo-sido-reunidos');
INSERT INTO verses VALUES (27692, 44, 20, 9, 'sentando-se e/mas alguém jovem em-nome Êutico sobre o janela sendo-levado-para-baixo sono profundo discutindo o Paulo sobre mais tendo-sido-levado-para-baixo de o sono caiu de o terceiro-andar abaixo e foi-levantado morto');
INSERT INTO verses VALUES (27693, 44, 20, 10, 'descendo porém o Paulo caiu-sobre a ele e tendo-abraçado disse não perturbai-vos o pois alma dele em a ele é');
INSERT INTO verses VALUES (27694, 44, 20, 11, 'subindo porém e partindo o pão e tendo-provado sobre suficiente e tendo-conversado até aurora assim saiu');
INSERT INTO verses VALUES (27695, 44, 20, 12, 'levaram porém o servo vivendo e foram-consolados não moderadamente');
INSERT INTO verses VALUES (27696, 44, 20, 13, 'nós porém tendo-ido-adiante sobre o barco navegamos sobre o Asso dali estando-para tomar o Paulo assim pois tendo-sido-ordenado era estando-prestes-a ele ir-a-pé');
INSERT INTO verses VALUES (27697, 44, 20, 14, 'como porém ponderava a-nós para o Asso tendo-tomado ele viemos para Mitilene');
INSERT INTO verses VALUES (27698, 44, 20, 15, 'e-de-lá tendo-navegado o seguinte chegamos defronte Quios o porém outra chegamos para Samos o porém seguinte viemos para Mileto');
INSERT INTO verses VALUES (27699, 44, 20, 16, 'tinha-julgado pois o Paulo navegar-ao-longo o Éfeso para-que não aconteça a ele gastar-tempo em o Ásia Apressava-se pois se possível seria a ele o dia o Pentecostes tornar-se para Jerusalém');
INSERT INTO verses VALUES (27700, 44, 20, 17, 'de porém o Mileto tendo-enviado para Éfeso mandou-chamar o anciãos o da-assembleia');
INSERT INTO verses VALUES (27701, 44, 20, 18, 'como porém apresentaram-se junto-a ele disse a-eles vós sabeis de primeiro do-dia de o qual embarquei para o Ásia como com vosso o todas-as-coisas tempo tornei-me');
INSERT INTO verses VALUES (27702, 44, 20, 19, 'servindo o ao-Kyrios com toda humildade-de-mente e lágrimas e tentações o tendo-acontecido a-mim em o conspirações o judeus');
INSERT INTO verses VALUES (27703, 44, 20, 20, 'como nada retraí-me o sendo-convenientes o não anunciar a-vós e ensinar vos publicamente e segundo casas');
INSERT INTO verses VALUES (27704, 44, 20, 21, 'testificando judeus e e gregos o para Theos arrependimento e fé para o Kyrion nosso Iesous');
INSERT INTO verses VALUES (27705, 44, 20, 22, 'e agora eis amarrado eu o espírito vou para Jerusalém o em a-ela que-virá-ao-encontro mim não sei');
INSERT INTO verses VALUES (27706, 44, 20, 23, 'porém que o espírito o santo segundo cidade testifica-solenemente a-mim dizendo que cadeias e tribulações me permanecem');
INSERT INTO verses VALUES (27707, 44, 20, 24, 'mas de-ninguém da-palavra faço o alma preciosa a-mim-mesmo como aperfeiçoarei o corrida meu e o serviço o qual receberam de-junto-de o do-Kyrios Iesous testificar-solenemente o evangelho o da-graça o de-Theos');
INSERT INTO verses VALUES (27708, 44, 20, 25, 'e agora eis eu sei que não-mais vereis o face meu vós todos em o qual atravessaram pregando o reino');
INSERT INTO verses VALUES (27709, 44, 20, 26, 'porque testifico a-vós em o hoje dia que puro sou de o sangue todos');
INSERT INTO verses VALUES (27710, 44, 20, 27, 'não pois retraí-me o não anunciar toda o conselho o de-Theos a-vós');
INSERT INTO verses VALUES (27711, 44, 20, 28, 'guardai-vos si-mesmos e todo o rebanho em o qual vos o espírito o santo pôs supervisores apascentar o igreja o de-Theos o qual adquiriu através-de o sangue o próprio');
INSERT INTO verses VALUES (27712, 44, 20, 29, 'eu sei que entrarão com o partida meu lobos pesados para vos não poupando o rebanho');
INSERT INTO verses VALUES (27713, 44, 20, 30, 'e de vosso deles ressuscitarão homens falando tendo-sido-pervertidas o arrancar o discípulos atrás deles-mesmos');
INSERT INTO verses VALUES (27714, 44, 20, 31, 'por-isso vigiai lembrando que triênio noite e dia não cessei com lágrimas admoestando um cada-um');
INSERT INTO verses VALUES (27715, 44, 20, 32, 'e o agora confio vos o ao-Kyrios e o em-palavra o da-graça dele o podendo edificar e dar o herança em o tendo-sido-santificados todos');
INSERT INTO verses VALUES (27716, 44, 20, 33, 'prata ou ouro ou Vestuário de-ninguém desejei');
INSERT INTO verses VALUES (27717, 44, 20, 34, 'eles-mesmos sabeis que o necessidades meu e o estando com mim Serviram o mãos estas');
INSERT INTO verses VALUES (27718, 44, 20, 35, 'todas-as-coisas Mostrei a-vós que assim labutando é necessário socorrer o estando-fracos lembrar e o palavras o do-Kyrios Iesous que ele disse Bem-aventurado é mais dar ou receber');
INSERT INTO verses VALUES (27719, 44, 20, 36, 'e estas-coisas dizendo pondo o joelhos dele com todos a-eles orou');
INSERT INTO verses VALUES (27720, 44, 20, 37, 'digno porém choro aconteceu todos e tendo-caído-sobre sobre o pescoço o Paulo beijavam ele');
INSERT INTO verses VALUES (27721, 44, 20, 38, 'sendo-atormentados principalmente sobre o em-palavra o qual tinha-dito que não-mais estão-a-ponto-de o rosto dele contemplar acompanhavam porém ele para o barco');
INSERT INTO chapters VALUES (1039, 44, 21, 40);
INSERT INTO verses VALUES (27722, 44, 21, 1, 'como porém aconteceu zarpar nos tendo-sido-arrancados de deles tendo-navegado-em-linha-reta viemos para o Cós o porém na-sequência para o Rodes e-de-lá para Pátara');
INSERT INTO verses VALUES (27723, 44, 21, 2, 'e tendo-encontrado barco atravessando para Fenícia tendo-embarcado navegamos');
INSERT INTO verses VALUES (27724, 44, 21, 3, 'tendo-avistado porém o Chipre e tendo-deixado ela esquerdo Navegávamos para Síria e descemos para Tiro ali pois o barco era descarregando o carga');
INSERT INTO verses VALUES (27725, 44, 21, 4, 'tendo-encontrado porém o discípulos permanecemos dele do-dia sete os-quais o a-Paulo diziam através-de o do-espírito não embarcar para Jerusalém');
INSERT INTO verses VALUES (27726, 44, 21, 5, 'quando porém aconteceu completar nos o do-dia saindo Caminhávamos enviando-adiante nos todos com mulheres e filhos até fora o cidade e tendo-posto o joelhos sobre o praia tendo-orado');
INSERT INTO verses VALUES (27727, 44, 21, 6, 'despedimo-nos uns-aos-outros e embarcamos para o barco aqueles porém retornaram para o próprias');
INSERT INTO verses VALUES (27728, 44, 21, 7, 'nós porém o navegação tendo-completado de Tiro chegamos para Ptolemaida e tendo-saudado o irmãos permanecemos dia uma de-junto-de a-eles');
INSERT INTO verses VALUES (27729, 44, 21, 8, 'o porém no-dia-seguinte saindo viemos para Cesareia e entrando para o casa Filipe o anunciador-de-boa-nova sendo de o sete permanecemos de-junto-de a ele');
INSERT INTO verses VALUES (27730, 44, 21, 9, 'neste porém eram filhas quatro virgens profetizando');
INSERT INTO verses VALUES (27731, 44, 21, 10, 'Permanecendo porém do-dia mais desceu alguém de o Judeia profeta em-nome Ágabo');
INSERT INTO verses VALUES (27732, 44, 21, 11, 'e vindo junto-a nos e levantando o cinto o Paulo tendo-amarrado si-mesmo o pés e o mãos disse estas coisas diz o espírito o santo o homem o qual é o cinto esta assim amarrarão em Jerusalém o judeus e entregarão para mãos nações');
INSERT INTO verses VALUES (27733, 44, 21, 12, 'como porém ouvimos estas-coisas consolávamos nós e e o locais o não subir ele para Jerusalém');
INSERT INTO verses VALUES (27734, 44, 21, 13, 'então respondeu o Paulo quê fazei chorando e enternecendo meu o coração eu pois não somente ser-amarrado mas e morrer para Jerusalém prontamente tenho em-favor-de o do-nome o do-Kyrios Iesous');
INSERT INTO verses VALUES (27735, 44, 21, 14, 'não sendo-persuadido porém dele Aquietamo-nos tendo-dito o do-Kyrios o vontade seja');
INSERT INTO verses VALUES (27736, 44, 21, 15, 'com porém o do-dia estas tendo-nos-preparado subíamos para Jerusalém');
INSERT INTO verses VALUES (27737, 44, 21, 16, 'reuniram-se porém e o discípulos de Cesareia com a-nós conduzindo de-junto-de o qual sejamos-hospedados Mnáson a-alguém cipriota antigo discípulo');
INSERT INTO verses VALUES (27738, 44, 21, 17, 'tendo-acontecido porém nosso para Jerusalém alegremente receberam nos o irmãos');
INSERT INTO verses VALUES (27739, 44, 21, 18, 'o porém seguinte entrava o Paulo com a-nós junto-a Tiago todos e apresentaram-se o anciãos');
INSERT INTO verses VALUES (27740, 44, 21, 19, 'e tendo-saudado eles narrava segundo um cada-um o qual fez o Theos em o nações através-de o ministério dele');
INSERT INTO verses VALUES (27741, 44, 21, 20, 'o porém ouvindo glorificavam o Theos disseram e a ele Contemplas irmão quantas miríades são em o judeus o dos-que-creram e todos zelosos o da-lei existem');
INSERT INTO verses VALUES (27742, 44, 21, 21, 'foram-instruídos porém acerca-de teu que apostasia ensinas de de-Moisés o segundo o nações todos judeus dizendo não circuncidar eles o filhos nem o Costumes andar');
INSERT INTO verses VALUES (27743, 44, 21, 22, 'quê portanto é de-todo-modo ouvirão que tens-vindo');
INSERT INTO verses VALUES (27744, 44, 21, 23, 'isto portanto faz o qual a-ti dizemos são a-nós homens quatro voto tendo sobre deles-mesmos');
INSERT INTO verses VALUES (27745, 44, 21, 24, 'estes tomando-consigo purifica-te com a-eles e gasta sobre a-eles para que rasparão o cabeça e conhecerão todos que o qual têm-sido-instruídos acerca-de teu nada é mas caminhas e ele guardando o lei');
INSERT INTO verses VALUES (27746, 44, 21, 25, 'acerca-de porém o dos-que-creram nações nós escrevemos tendo-julgado guardar-se eles o e sacrificado-a-ídolo e sangue e sufocado e prostituição');
INSERT INTO verses VALUES (27747, 44, 21, 26, 'então o Paulo tomando-consigo o homens o seguinte dia com a-eles tendo-se-purificado entrava para o templo anunciando o cumprimento o dos-dias o purificação até o qual foi-oferecido em-favor-de de-um cada-um deles o oferta');
INSERT INTO verses VALUES (27748, 44, 21, 27, 'como porém estavam-para o sete dias consumar-se o de o Ásia judeus tendo-contemplado ele em o templo confundiam todas-as-coisas o multidão e lançaram-sobre sobre ele o mãos');
INSERT INTO verses VALUES (27749, 44, 21, 28, 'gritando Homens Israelitas auxiliai este é o homem o segundo o povo e o da-lei e o lugar deste todos em-todo-lugar ensinando ainda e e Gregos introduziu para o templo e tem-tornado-comum o santo lugar este');
INSERT INTO verses VALUES (27750, 44, 21, 29, 'eram pois tendo-visto-antes Trófimo o Efésio em o na-cidade com a ele o qual supunham que para o templo introduziu o Paulo');
INSERT INTO verses VALUES (27751, 44, 21, 30, 'foi-movida e o cidade toda e aconteceu concurso o povo e agarrando o Paulo arrastavam ele fora o do-templo e imediatamente foram-fechados o portas');
INSERT INTO verses VALUES (27752, 44, 21, 31, 'Buscando e ele matar subiu denúncia o tribuno o coorte que toda é-confundida Jerusalém');
INSERT INTO verses VALUES (27753, 44, 21, 32, 'o qual imediatamente tomando-consigo soldados e Centuriões correu-para-baixo sobre eles o porém vendo o comandante-de-mil e o soldados cessaram batendo o Paulo');
INSERT INTO verses VALUES (27754, 44, 21, 33, 'então tendo-se-aproximado o quiliarca apoderou-se dele e ordenou ser-amarrado correntes dois e inquiria quem seria e quê é tendo-feito');
INSERT INTO verses VALUES (27755, 44, 21, 34, 'outros porém outro algo clamavam em o à-multidão não podendo porém dele conhecer o seguro através-de o tumulto ordenou ser-conduzido ele para o acampamento');
INSERT INTO verses VALUES (27756, 44, 21, 35, 'quando porém aconteceu sobre o degraus aconteceu ser-carregado ele sob o soldados através-de o violência o da-multidão');
INSERT INTO verses VALUES (27757, 44, 21, 36, 'seguia pois o multidão o povo gritando Levanta ele');
INSERT INTO verses VALUES (27758, 44, 21, 37, 'Estando-a-ponto-de e ser-introduzido para o acampamento o Paulo diz o tribuno se é-lícito a-mim dizer algo junto-a te o porém disse Em-grego conheces');
INSERT INTO verses VALUES (27759, 44, 21, 38, 'não então tu és o Egípcio o antes-de destes o dos-dias tendo-subvertido e tendo-conduzido-para-fora para o deserto o quatro-mil homens o de-sicários');
INSERT INTO verses VALUES (27760, 44, 21, 39, 'disse porém o Paulo eu homem de-fato sou judeu De-Tarso o Cilícia não insignificante cidade cidadão suplico e/mas teu permite a-mim falar junto-a o povo');
INSERT INTO verses VALUES (27761, 44, 21, 40, 'Tendo-permitido porém dele o Paulo estando-de-pé sobre o degraus acenou o mão o povo muita porém de-silêncio tendo-acontecido chamou o hebraico dialeto dizendo');
INSERT INTO chapters VALUES (1040, 44, 22, 30);
INSERT INTO verses VALUES (27762, 44, 22, 1, 'Homens irmãos e pais ouvi meu o junto-a vos agora defesa');
INSERT INTO verses VALUES (27763, 44, 22, 2, 'ouvindo porém que o hebraico dialeto chamava a-eles mais forneceram Quietude e diz');
INSERT INTO verses VALUES (27764, 44, 22, 3, 'Eu sou homem judeu gerado em Tarso o Cilícia tendo-sido-criado porém em o na-cidade nesta de-junto-de o pés Gamaliel tendo-sido-instruído segundo exatidão o paterno da-lei zeloso sendo o de-Theos assim-como todos vós sois hoje');
INSERT INTO verses VALUES (27765, 44, 22, 4, 'o qual esta o caminho persegui até da-morte amarrando e entregando para guardas homens e e mulheres');
INSERT INTO verses VALUES (27766, 44, 22, 5, 'como e o sumo-sacerdote testifica a-mim e todo o conselho-de-anciãos de-junto-de o qual e cartas tendo-recebido junto-a o irmãos para Damasco Caminhava eixo e o ali sendo presos para Jerusalém para que sejam-castigados');
INSERT INTO verses VALUES (27767, 44, 22, 6, 'aconteceu e/mas a-mim indo e aproximando-se o Damasco acerca-de meio-dia subitamente de o do-céu resplandecer-ao-redor luz suficiente acerca-de a-mim');
INSERT INTO verses VALUES (27768, 44, 22, 7, 'Caí e para o Solo e ouvi voz dizendo a-mim Saul Saul quê me persegues');
INSERT INTO verses VALUES (27769, 44, 22, 8, 'eu porém respondi Quem és Kyrie disse e junto-a a-mim Eu sou Iesous o nazareno o qual tu persegues');
INSERT INTO verses VALUES (27770, 44, 22, 9, 'o porém com mim sendo o por-um-lado luz contemplaram o porém voz não ouviram o falando a-mim');
INSERT INTO verses VALUES (27771, 44, 22, 10, 'disseram e/mas quê farei Kyrie o porém Kyrios disse para me Levantando-se vai para Damasco e-ali a-ti será-falado acerca-de todos o qual tem-sido-designado a-ti fazer');
INSERT INTO verses VALUES (27772, 44, 22, 11, 'como porém não olhavam-fixamente de o da-glória o luz daquele sendo-conduzido-pela-mão sob o estando-junto a-mim vieram para Damasco');
INSERT INTO verses VALUES (27773, 44, 22, 12, 'Ananias e/mas alguém homem piedoso segundo o lei sendo-testificado sob todos o habitantes judeus');
INSERT INTO verses VALUES (27774, 44, 22, 13, 'vindo junto-a mim e aproximando-se disse a-mim Saul irmão olha-para-cima e-eu a-ela o hora recuperei-a-vista para ele');
INSERT INTO verses VALUES (27775, 44, 22, 14, 'o porém disse o Theos o dos-pais nosso designou-de-antemão te conhecer o vontade dele e ver o justo e ouvir voz de o da-boca dele');
INSERT INTO verses VALUES (27776, 44, 22, 15, 'que serás testemunha a ele junto-a todos homens o qual tens-visto e ouviste');
INSERT INTO verses VALUES (27777, 44, 22, 16, 'e agora quê estás-para levantando-se batiza-te e lava-te o do-pecado teu tendo-invocado o nome dele');
INSERT INTO verses VALUES (27778, 44, 22, 17, 'aconteceu e/mas a-mim Tendo-retornado para Jerusalém e orando meu em o templo tornar-se me em espanto');
INSERT INTO verses VALUES (27779, 44, 22, 18, 'e ver ele dizendo a-mim Apressa-te e sai em brevemente de Jerusalém porque não aceitarão teu testemunho acerca-de mim');
INSERT INTO verses VALUES (27780, 44, 22, 19, 'e-eu disseram Kyrie eles-mesmos conhecem que eu eu-era aprisionando e espancando segundo o sinagogas o crentes sobre te');
INSERT INTO verses VALUES (27781, 44, 22, 20, 'e quando era-derramado o sangue Estêvão o testemunha teu e ele eu-era Estando-presente e consentindo-junto e guardando o vestes o dos-que-matam ele');
INSERT INTO verses VALUES (27782, 44, 22, 21, 'e disse para me vai que eu para nações longe enviarei-para-fora te');
INSERT INTO verses VALUES (27783, 44, 22, 22, 'Ouviam porém dele até deste o da-palavra e levantaram o voz deles dizendo Levanta de o da-terra o tal não pois convinha ele viver');
INSERT INTO verses VALUES (27784, 44, 22, 23, 'clamando e deles e lançando o vestes e poeira lançando para o ar');
INSERT INTO verses VALUES (27785, 44, 22, 24, 'ordenou o quiliarca ser-introduzido ele para o acampamento disseste açoites ser-interrogado ele para que reconheça através-de o qual causa assim clamavam a ele');
INSERT INTO verses VALUES (27786, 44, 22, 25, 'como porém estenderam ele o Correias disse junto-a o de-pé Centurião o Paulo se homem Romano e incondenado é-lícito a-vós açoitar');
INSERT INTO verses VALUES (27787, 44, 22, 26, 'ouvindo porém o centurião aproximando-se o tribuno anunciou dizendo quê estás-a-ponto-de fazer o pois homem este Romano é');
INSERT INTO verses VALUES (27788, 44, 22, 27, 'aproximando-se porém o quiliarca disse a ele Dize a-mim tu Romano és o porém disse Sim');
INSERT INTO verses VALUES (27789, 44, 22, 28, 'respondeu porém o quiliarca eu grande soma o cidadania esta adquiri o porém Paulo disse eu porém e tenho-sido-gerado');
INSERT INTO verses VALUES (27790, 44, 22, 29, 'imediatamente portanto apartaram-se de dele o estando-para ele interrogar e o quiliarca porém temeu reconhecendo que Romano é e que ele era tendo-recebido');
INSERT INTO verses VALUES (27791, 44, 22, 30, 'o porém no-dia-seguinte querendo conhecer o seguro o quê é-acusado sob o judeus Desatou ele e ordenou reunir-se o sumos-sacerdotes e todo o sinédrio e tendo-feito-descer o Paulo estabeleceu para eles');
INSERT INTO chapters VALUES (1041, 44, 23, 35);
INSERT INTO verses VALUES (27792, 44, 23, 1, 'fitando-os-olhos porém o Paulo o sinédrio disse Homens irmãos eu toda consciência boa tenho-vivido-como-cidadão o a-Theos até desta o do-dia');
INSERT INTO verses VALUES (27793, 44, 23, 2, 'o porém sumo-sacerdote Ananias ordenou o estejam-de-pé a ele bater dele o boca');
INSERT INTO verses VALUES (27794, 44, 23, 3, 'então o Paulo junto-a ele disse Bater te está-para o Theos parede tendo-sido-caiado e tu te-sentas julgando me segundo o lei e transgredindo-a-lei ordenas me ser-golpeado');
INSERT INTO verses VALUES (27795, 44, 23, 4, 'o porém estando-de-pé disseram o sumo-sacerdote o de-Theos injurias');
INSERT INTO verses VALUES (27796, 44, 23, 5, 'disse e o Paulo não sei irmãos que é sumo-sacerdote está-escrito pois que Governante o povo teu não dirás mal');
INSERT INTO verses VALUES (27797, 44, 23, 6, 'sabendo porém o Paulo que o um parte é saduceus o porém outro fariseus gritava em o sinédrio Homens irmãos eu Fariseu sou Filho fariseus acerca-de da-esperança e da-ressurreição mortos sou-julgado');
INSERT INTO verses VALUES (27798, 44, 23, 7, 'isto porém dele falando aconteceu dissensão o fariseus e saduceus e rasgou-se o multidão');
INSERT INTO verses VALUES (27799, 44, 23, 8, 'Saduceus pois dizem não ser ressurreição nem anjo nem espírito fariseus porém confessam o ambos');
INSERT INTO verses VALUES (27800, 44, 23, 9, 'aconteceu porém clamor grande e levantando-se alguns o dos-escribas o da-parte o fariseus contendiam dizendo nada mau encontramos em o ao-homem neste se porém espírito falou a ele ou anjo');
INSERT INTO verses VALUES (27801, 44, 23, 10, 'muita porém acontecendo dissensão tendo-temido o quiliarca não seja-despedaçado o Paulo sob deles ordenou o exército tendo-descido arrebatar ele de meio deles conduzir e para o acampamento');
INSERT INTO verses VALUES (27802, 44, 23, 11, 'o porém seguinte à-noite aproximando-se a ele o Kyrios disse tem-ânimo como pois testificaste-solenemente o acerca-de mim para Jerusalém assim te é necessário e para Roma testemunhar');
INSERT INTO verses VALUES (27803, 44, 23, 12, 'Tendo-acontecido porém do-dia tendo-feito ajuntamento o judeus amaldiçoaram-com-anátema si-mesmos dizendo nem comer nem beber até o qual matem o Paulo');
INSERT INTO verses VALUES (27804, 44, 23, 13, 'eram porém mais quarenta o esta o conspiração tendo-feito');
INSERT INTO verses VALUES (27805, 44, 23, 14, 'os-quais aproximando-se o sumos-sacerdotes e o presbíteros disseram Anátema amaldiçoamo-nos-com-maldição si-mesmos nenhum provar até o qual matemos o Paulo');
INSERT INTO verses VALUES (27806, 44, 23, 15, 'agora portanto vós revelai o tribuno com o sinédrio para-que faça-descer ele para vos como estando-para examinar mais-exatamente o acerca-de dele nós porém antes-de o aproximar-se ele preparados somos o matar ele');
INSERT INTO verses VALUES (27807, 44, 23, 16, 'ouvindo porém o Filho o irmã Paulo o emboscada tendo-chegado e entrando para o acampamento anunciou o a-Paulo');
INSERT INTO verses VALUES (27808, 44, 23, 17, 'tendo-chamado porém o Paulo um o centuriões disse o jovem este vai-embora junto-a o comandante-de-mil tem pois anunciar algo a ele');
INSERT INTO verses VALUES (27809, 44, 23, 18, 'o por-um-lado portanto tomando-consigo ele conduziu junto-a o comandante-de-mil e diz o prisioneiro Paulo tendo-chamado-a-si me perguntou este o jovem conduzir junto-a te Tendo algo falar a-ti');
INSERT INTO verses VALUES (27810, 44, 23, 19, 'tomando porém o da-mão dele o quiliarca e tendo-se-retirado segundo própria inquiria quê é o qual tens anunciar a-mim');
INSERT INTO verses VALUES (27811, 44, 23, 20, 'disse porém que o judeus combinaram o Perguntar te para-que amanhã o Paulo faças-descer para o sinédrio como estando-prestes-a algo mais-exatamente perguntar acerca-de dele');
INSERT INTO verses VALUES (27812, 44, 23, 21, 'tu portanto não sejas-persuadido a-eles emboscam pois ele de deles homens mais quarenta os-quais amaldiçoaram-com-anátema si-mesmos nem comer nem beber até o qual destruam ele e agora são prontos aguardando o de teu promessa');
INSERT INTO verses VALUES (27813, 44, 23, 22, 'o por-um-lado portanto quiliarca libertou o jovem ordenando a-ninguém falar-fora que estas-coisas revelaste junto-a a-mim');
INSERT INTO verses VALUES (27814, 44, 23, 23, 'e tendo-chamado-a-si alguns dois o centuriões disse Preparai soldados duzentos para-que vão até Cesareia e cavaleiros setenta e lanceiros duzentos de terceira hora o noite');
INSERT INTO verses VALUES (27815, 44, 23, 24, 'gados e apresentar para que tendo-feito-montar o Paulo salvem junto-a Félix o governador');
INSERT INTO verses VALUES (27816, 44, 23, 25, 'tendo-escrito carta tendo o modelo este');
INSERT INTO verses VALUES (27817, 44, 23, 26, 'Cláudio Lísias o excelentíssimo governador Félix alegrar-se');
INSERT INTO verses VALUES (27818, 44, 23, 27, 'o homem este tendo-sido-concebido sob o judeus e as-coisas-futuras ser-morto sob deles aproximando-se com o exército livrei tendo-aprendido que Romano é');
INSERT INTO verses VALUES (27819, 44, 23, 28, 'querendo e reconhecer o causa através-de o qual acusavam a ele conduziram-abaixo para o sinédrio deles');
INSERT INTO verses VALUES (27820, 44, 23, 29, 'o qual encontraram sendo-acusado acerca-de questões o da-lei deles nada porém digno da-morte ou prisões tendo Acusação');
INSERT INTO verses VALUES (27821, 44, 23, 30, 'tendo-sido-informada e/mas a-mim conspiração para o homem ser imediatamente enviei junto-a te ordenando e o acusadores dizer junto-a ele sobre teu');
INSERT INTO verses VALUES (27822, 44, 23, 31, 'o por-um-lado portanto soldados segundo o tendo-sido-designado a-eles tendo-tomado o Paulo levaram através-de da-noite para o Antipátride');
INSERT INTO verses VALUES (27823, 44, 23, 32, 'o porém no-dia-seguinte tendo-permitido o cavaleiros partir com a ele retornaram para o acampamento');
INSERT INTO verses VALUES (27824, 44, 23, 33, 'os-quais entrando para o Cesareia e tendo-entregado o carta o governador apresentaram e o Paulo a ele');
INSERT INTO verses VALUES (27825, 44, 23, 34, 'tendo-lido porém e tendo-perguntado de de-qual província é e tendo-perguntado que de Cilícia');
INSERT INTO verses VALUES (27826, 44, 23, 35, 'ouvirei-plenamente teu disse quando e o acusadores teu cheguem tendo-ordenado em o pretório o de-Herodes guardar-se ele');
INSERT INTO chapters VALUES (1042, 44, 24, 26);
INSERT INTO verses VALUES (27827, 44, 24, 1, 'com porém cinco do-dia desceu o sumo-sacerdote Ananias com dos-anciãos alguns e Orador Tértulo de-alguém os-quais apresentaram o governador segundo o Paulo');
INSERT INTO verses VALUES (27828, 44, 24, 2, 'tendo-sido-chamado porém dele começou acusar o Tértulo dizendo Muita paz obtendo através-de teu e reformas acontecendo o nação neste através-de o tua providência');
INSERT INTO verses VALUES (27829, 44, 24, 3, 'de-todo-modo e e por-toda-parte recebemos excelentíssimo Félix com toda ação-de-graças');
INSERT INTO verses VALUES (27830, 44, 24, 4, 'para que porém não sobre mais te impedo rogo ouvir te nosso brevemente o tua moderação');
INSERT INTO verses VALUES (27831, 44, 24, 5, 'tendo-encontrado pois o homem este pestilento e movendo dissensões todos o judeus o segundo o mundo-habitado líder-principal e o o Nazarenos heresia');
INSERT INTO verses VALUES (27832, 44, 24, 6, 'o qual e o templo tentou profanar o qual e seguramos');
INSERT INTO verses VALUES (27833, 44, 24, 8, 'de-junto-de o qual possas ele tendo-examinado acerca-de todos destes reconhecer o qual nós acusamos dele');
INSERT INTO verses VALUES (27834, 44, 24, 9, 'atacaram-junto porém e o judeus declarando estas-coisas assim ter');
INSERT INTO verses VALUES (27835, 44, 24, 10, 'respondeu e o Paulo tendo-acenado a ele o governador dizer de muitos anos sendo te juiz o nação neste sabendo alegremente o acerca-de de-mim-mesmo defendo-me');
INSERT INTO verses VALUES (27836, 44, 24, 11, 'podendo teu reconhecer que não mais são a-mim dias doze de o qual subi para-adorar para Jerusalém');
INSERT INTO verses VALUES (27837, 44, 24, 12, 'e nem em o templo encontraram me para alguém conversando ou conhecimento-pleno fazendo da-multidão nem em o nas-sinagogas nem segundo o cidade');
INSERT INTO verses VALUES (27838, 44, 24, 13, 'nem apresentar podem a-ti acerca-de o qual agora acusam meu');
INSERT INTO verses VALUES (27839, 44, 24, 14, 'confesso porém isto a-ti que segundo o caminho o qual dizem heresia assim sirvo o paterno a-Theos crendo todos o segundo o lei e o em o profetas tendo-sido-escritas');
INSERT INTO verses VALUES (27840, 44, 24, 15, 'esperança tendo para o Theos o qual e eles-mesmos estes recebem ressurreição estar-prestes ser justos e e injustos');
INSERT INTO verses VALUES (27841, 44, 24, 16, 'em neste e ele exercito-me sem-tropeço consciência ter junto-a o Theos e o homens através-de todo');
INSERT INTO verses VALUES (27842, 44, 24, 17, 'através-de anos porém mais esmolas estando-para-fazer para o nação meu cheguei e ofertas');
INSERT INTO verses VALUES (27843, 44, 24, 18, 'em o qual encontraram me Tendo-sido-purificado em o templo não com da-multidão nem com tumulto');
INSERT INTO verses VALUES (27844, 44, 24, 19, 'alguns porém de o Ásia judeus o qual é necessário sobre teu estar-presente e acusar se algo Tivessem junto-a a-mim');
INSERT INTO verses VALUES (27845, 44, 24, 20, 'ou eles-mesmos estes digam quê encontraram injustiça tendo-ficado-de-pé meu sobre o sinédrio');
INSERT INTO verses VALUES (27846, 44, 24, 21, 'ou acerca-de uma desta voz o qual clamei em a-eles estando-de-pé que acerca-de da-ressurreição mortos eu sou-julgado hoje sobre vosso');
INSERT INTO verses VALUES (27847, 44, 24, 22, 'Adiou porém eles o Félix mais-exatamente sei o acerca-de o do-caminho disseste quando Lísias o quiliarca desça examinarei o segundo vos');
INSERT INTO verses VALUES (27848, 44, 24, 23, 'tendo-ordenado o centurião ser-guardado ele ter e alívio e ninguém impedir o próprios dele Servir a ele');
INSERT INTO verses VALUES (27849, 44, 24, 24, 'com porém do-dia alguns tendo-chegado o Félix com Drusila o em-particular mulher estando Judeia mandou-buscar o Paulo e ouviu dele acerca-de o para Christos Iesous da-fé');
INSERT INTO verses VALUES (27850, 44, 24, 25, 'discutindo porém dele acerca-de da-justiça e domínio-próprio e o julgamento o do-que-está-por-vir aterrorizado tendo-se-tornado o Félix respondeu o agora tendo vai tempo porém tendo-participado mandarei-chamar te');
INSERT INTO verses VALUES (27851, 44, 24, 26, 'juntamente e esperando que posses será-dado a ele sob o Paulo por-isso e mais-frequentemente ele mandando-buscar conversava a ele');
INSERT INTO verses VALUES (27852, 44, 24, 27, 'Dois-anos porém tendo-sido-cumprida recebeu sucessor o Félix Pórcio Festo querendo e graça depositar-favor o judeus o Félix deixou o Paulo amarrado');
INSERT INTO chapters VALUES (1043, 44, 25, 27);
INSERT INTO verses VALUES (27853, 44, 25, 1, 'Festo portanto tendo-embarcado o província com três do-dia subiu para Jerusalém de Cesareia');
INSERT INTO verses VALUES (27854, 44, 25, 2, 'revelaram e a ele o sumos-sacerdotes e o primeiro o judeus segundo o Paulo e suplicavam ele');
INSERT INTO verses VALUES (27855, 44, 25, 3, 'pedindo graça segundo dele para-que mande-buscar ele para Jerusalém emboscada fazendo matar ele segundo o caminho');
INSERT INTO verses VALUES (27856, 44, 25, 4, 'o por-um-lado portanto Festo respondeu ser-guardado o Paulo para Cesareia si-mesmo porém estar-prestes em brevemente sair');
INSERT INTO verses VALUES (27857, 44, 25, 5, 'o portanto em a-vós diz poderosos tendo-descido-com se quê é em o marido absurdo acusem dele');
INSERT INTO verses VALUES (27858, 44, 25, 6, 'Tendo-permanecido porém em a-eles do-dia não mais oito ou dez descendo para Cesareia o no-dia-seguinte sentando-se sobre o tribunal ordenou o Paulo ser-levado');
INSERT INTO verses VALUES (27859, 44, 25, 7, 'tendo-chegado porém dele cercaram ele o de Jerusalém tendo-descido judeus muitas-coisas e pesados acusações levando-contra o qual não tinham-força demonstrar');
INSERT INTO verses VALUES (27860, 44, 25, 8, 'o Paulo defendendo-se que nem para o lei o judeus nem para o templo nem para César algo pecaram');
INSERT INTO verses VALUES (27861, 44, 25, 9, 'o Festo porém querendo o judeus graça depositar-favor respondendo o a-Paulo disse Queres para Jerusalém subindo ali acerca-de destes ser-julgado sobre mim');
INSERT INTO verses VALUES (27862, 44, 25, 10, 'disse porém o Paulo Tendo-estado-de-pé sobre o tribunal de-César sou do-qual me é necessário ser-julgado judeus nada cometi-injustiça como e tu muito-bem reconheces');
INSERT INTO verses VALUES (27863, 44, 25, 11, 'se por-um-lado portanto pratico-injustiça e digno da-morte tenho-praticado algo não recuso o morrer se porém nada é o qual estes acusam meu ninguém me pode a-eles conceder-graciosamente César invoco');
INSERT INTO verses VALUES (27864, 44, 25, 12, 'então o Festo tendo-conversado-com com o conselho respondeu César tens-sido-chamado sobre César vás');
INSERT INTO verses VALUES (27865, 44, 25, 13, 'dias porém tendo-transcorrido alguns Agripa o rei e Berenice chegaram para Cesareia tendo-saudado o Festo');
INSERT INTO verses VALUES (27866, 44, 25, 14, 'como porém mais do-dia permaneciam ali o Festo o rei expôs o segundo o Paulo dizendo homem quem é tendo-sido-deixado sob Félix prisioneiro');
INSERT INTO verses VALUES (27867, 44, 25, 15, 'acerca-de o qual tendo-acontecido meu para Jerusalém apresentaram o sumos-sacerdotes e o anciãos o judeus pedindo segundo dele condenação');
INSERT INTO verses VALUES (27868, 44, 25, 16, 'junto-a o qual respondi que não é costume Romanos perdoar alguém homem antes-de ou o sendo-acusado segundo rosto tivesse o acusadores lugar e defesa tomasse acerca-de o acusação');
INSERT INTO verses VALUES (27869, 44, 25, 17, 'tendo-se-reunido portanto aqui adiamento nenhuma tendo-feito o na-sequência sentando-se sobre o tribunal ordenei ser-levado o homem');
INSERT INTO verses VALUES (27870, 44, 25, 18, 'acerca-de o qual tendo-sido-colocados-de-pé o acusadores nenhuma causa traziam o qual eu supunham maus');
INSERT INTO verses VALUES (27871, 44, 25, 19, 'questões e/mas alguém acerca-de o próprias superstição tinham junto-a ele e acerca-de de-alguém Iesous tendo-morrido o qual Afirmava o Paulo viver');
INSERT INTO verses VALUES (27872, 44, 25, 20, 'estando-perplexo porém eu o acerca-de destes busca diziam se quisesse ir para Jerusalém e-ali ser-julgado acerca-de destes');
INSERT INTO verses VALUES (27873, 44, 25, 21, 'o porém Paulo tendo-invocado ser-guardado ele para o o Augusto decisão ordenei ser-guardado ele até o qual enviarei-de-volta ele junto-a César');
INSERT INTO verses VALUES (27874, 44, 25, 22, 'Agripa porém junto-a o Festo Eu-desejava e ele o do-homem ouvir Amanhã diz ouça dele');
INSERT INTO verses VALUES (27875, 44, 25, 23, 'o portanto no-dia-seguinte tendo-vindo o Agripa e o Berenice com muita pompa e tendo-entrado para o auditório com e comandantes-de-mil e homens o segundo eminência o cidade e tendo-ordenado o Festo foi-conduzido o Paulo');
INSERT INTO verses VALUES (27876, 44, 25, 24, 'e diz o Festo Agripa rei e todos o estando-presentes-com a-nós homens contemplais este acerca-de o qual todo o multidão o judeus intercederam a-mim em e em-Jerusalém e aqui clamando não é necessário ele viver não-mais');
INSERT INTO verses VALUES (27877, 44, 25, 25, 'eu porém alcancei nada digno ele da-morte ter-praticado dele porém deste tendo-invocado o Augusto julguei enviar');
INSERT INTO verses VALUES (27878, 44, 25, 26, 'acerca-de o qual seguro algo escrever o ao-Kyrios não tenho por-isso conduziram-adiante ele sobre vosso e principalmente sobre teu rei Agripa para-que o exame tendo-acontecido tenha quê escreverei');
INSERT INTO verses VALUES (27879, 44, 25, 27, 'irracional pois a-mim parece enviando prisioneiro não e o segundo dele causa sinalizar');
INSERT INTO chapters VALUES (1044, 44, 26, 32);
INSERT INTO verses VALUES (27880, 44, 26, 1, 'Agripa porém junto-a o Paulo disse É-permitido a-ti em-favor-de ti-mesmo dizer então o Paulo estendendo o mão defendia-se');
INSERT INTO verses VALUES (27881, 44, 26, 2, 'acerca-de todos o qual sou-acusado sob judeus rei Agripa tenho-considerado a-mim-mesmo bem-aventurado sobre teu estando-prestes-a hoje defender-se');
INSERT INTO verses VALUES (27882, 44, 26, 3, 'principalmente conhecedor sendo te todos o segundo judeus costumes e e questões por-isso suplico pacientemente ouvir meu');
INSERT INTO verses VALUES (27883, 44, 26, 4, 'o por-um-lado portanto vivam meu de juventude o de princípio acontecida em o nação meu em e em-Jerusalém sei todos judeus');
INSERT INTO verses VALUES (27884, 44, 26, 5, 'conhecendo-de-antemão me de-cima se queiram testemunhar que segundo o mais-exata heresia o Nossa religião Vivi fariseu');
INSERT INTO verses VALUES (27885, 44, 26, 6, 'e agora sobre esperança o para o pais nosso promessa tendo-acontecido sob o de-Theos estou-de-pé sendo-julgado');
INSERT INTO verses VALUES (27886, 44, 26, 7, 'para o qual o doze-tribos nosso em fervor noite e dia servindo espera chegar acerca-de o qual da-esperança sou-acusado sob judeus rei');
INSERT INTO verses VALUES (27887, 44, 26, 8, 'quê incrédulo é-julgado de-junto-de a-vós se o Theos mortos levanta');
INSERT INTO verses VALUES (27888, 44, 26, 9, 'eu por-um-lado portanto Pareceu-me a-mim-mesmo junto-a o nome Iesous o nazareno é necessário muitas-coisas contrárias praticar');
INSERT INTO verses VALUES (27889, 44, 26, 10, 'o qual e fiz em em-Jerusalém e muitos e o dos-santos eu em prisões encerrei o de-junto-de o sumos-sacerdotes autoridade tendo-recebido sendo-mortos e deles trouxe pedrinha');
INSERT INTO verses VALUES (27890, 44, 26, 11, 'e segundo todas o sinagogas muitas-vezes castigando eles forçavam blasfemar abundantemente e enfurecendo-se a-eles perseguiam até e para o fora cidades');
INSERT INTO verses VALUES (27891, 44, 26, 12, 'em o qual indo para o Damasco com da-autoridade e Comissão o o sumos-sacerdotes');
INSERT INTO verses VALUES (27892, 44, 26, 13, 'do-dia meio segundo o caminho vi rei do-céu em-favor-de o esplendor o sol tendo-resplandecido-ao-redor me luz e o com mim indo');
INSERT INTO verses VALUES (27893, 44, 26, 14, 'todos e tendo-caído nosso para o terra ouvi voz dizendo para me o hebraico dialeto Saul Saul quê me persegues duro a-ti junto-a ferrões coicear');
INSERT INTO verses VALUES (27894, 44, 26, 15, 'eu porém disse Quem és Kyrie o porém Kyrios disse Eu sou Iesous o qual tu persegues');
INSERT INTO verses VALUES (27895, 44, 26, 16, 'mas levanta-te e fica-de-pé sobre o pés teu para isto pois Fui-visto a-ti designar-de-antemão te servo e testemunha o qual e viste me o qual e serei-visto a-ti');
INSERT INTO verses VALUES (27896, 44, 26, 17, 'livrando te de o povo e de o nações para o qual eu envio te');
INSERT INTO verses VALUES (27897, 44, 26, 18, 'abrir olhos deles o converter de das-trevas para luz e o da-autoridade o Satanás sobre o Theos o receber eles perdão dos-pecados e sorte em o tendo-sido-santificados fé o para a-mim');
INSERT INTO verses VALUES (27898, 44, 26, 19, 'de-onde rei Agripa não tornei-me desobediente o celestial visão');
INSERT INTO verses VALUES (27899, 44, 26, 20, 'mas o em Damasco primeiro e e em-Jerusalém toda e o região o Judeia e o nações anunciavam arrepender-se e voltar sobre o Theos dignos o arrependimento obra praticando');
INSERT INTO verses VALUES (27900, 44, 26, 21, 'por-causa-de destes me judeus tendo-prendido em o templo tentavam matar');
INSERT INTO verses VALUES (27901, 44, 26, 22, 'socorro portanto tendo-obtido o de o de-Theos até o do-dia desta estou-de-pé testificando pequeno e e grande nada fora-de dizendo o qual e o profetas falaram estando-para tornar-se e Moisés');
INSERT INTO verses VALUES (27902, 44, 26, 23, 'se sujeito-a-sofrimento o Christos se primeiro de da-ressurreição mortos luz está-para anunciar o e povo e o nações');
INSERT INTO verses VALUES (27903, 44, 26, 24, 'estas-coisas porém dele defendendo-se o Festo grande o com-voz diz Enlouqueces Paulo o muitas-coisas te letras para loucura enlouquece');
INSERT INTO verses VALUES (27904, 44, 26, 25, 'o porém Paulo não enlouqueço diz excelentíssimo Festo mas da-verdade e sobriedade palavras proclamo');
INSERT INTO verses VALUES (27905, 44, 26, 26, 'conhece pois acerca-de destes o rei junto-a o qual e falando-ousadamente falo estar-oculto pois ele destes não sou-persuadido nada não pois é em esquina tendo-sido-praticado isto');
INSERT INTO verses VALUES (27906, 44, 26, 27, 'crês rei Agripa o profetas sei que crês');
INSERT INTO verses VALUES (27907, 44, 26, 28, 'o porém Agripa junto-a o Paulo em pouco me persuades Cristão fazer');
INSERT INTO verses VALUES (27908, 44, 26, 29, 'o porém Paulo Eu-desejaria partícula-condicional o a-Theos e em pouco e em grande não somente te mas e todos o ouvindo meu hoje tornar-se tais de-que-tipo e eu sou exceto o prisões destes');
INSERT INTO verses VALUES (27909, 44, 26, 30, 'Levantou-se e o rei e o governador o e Berenice e o sentando-se-com a-eles');
INSERT INTO verses VALUES (27910, 44, 26, 31, 'e tendo-se-retirado falavam junto-a uns-aos-outros dizendo que nada da-morte ou prisões digno pratica o homem este');
INSERT INTO verses VALUES (27911, 44, 26, 32, 'Agripa porém o Festo disse Ter-sido-solto podia o homem este se não tinha-sido-chamado César');
INSERT INTO chapters VALUES (1045, 44, 27, 44);
INSERT INTO verses VALUES (27912, 44, 27, 1, 'como porém foi-julgado o navegar nos para o Itália entregavam o e Paulo e alguns outros prisioneiros centurião em-nome Júlio coorte Augusta');
INSERT INTO verses VALUES (27913, 44, 27, 2, 'tendo-embarcado porém no-barco Adramiteno vindouro navegar para o segundo o Ásia lugares navegamos sendo com a-nós Aristarco Macedônio Tessalonicense');
INSERT INTO verses VALUES (27914, 44, 27, 3, 'o e outra fomos-levados-para-baixo para Sidom filantropicamente e o Júlio o a-Paulo tendo-usado permitiu junto-a o amigos ao-que-partiu cuidado obter');
INSERT INTO verses VALUES (27915, 44, 27, 4, 'e-de-lá tendo-zarpado navegamos-sob o Chipre através-de o o ventos ser contrários');
INSERT INTO verses VALUES (27916, 44, 27, 5, 'o e profundeza o segundo o Cilícia e Panfília tendo-navegado-através descemos para Mirra o Lícia');
INSERT INTO verses VALUES (27917, 44, 27, 6, 'E-ali encontrando o centurião barco Alexandrino mais para o Itália fez-embarcar nos para isso');
INSERT INTO verses VALUES (27918, 44, 27, 7, 'em suficientes porém dias navegando-lentamente e dificilmente tendo-se-tornado segundo o Cnido não permitindo nos o vento navegamos-sob o Creta segundo Salmone');
INSERT INTO verses VALUES (27919, 44, 27, 8, 'dificilmente e navegando-ao-longo ela viemos para lugar algum chamado bons Portos o qual perto era cidade Laseia');
INSERT INTO verses VALUES (27920, 44, 27, 9, 'Suficiente porém tempo tendo-passado e sendo já Perigosa o navegação através-de o e o Jejum já ter-passado exortava o Paulo');
INSERT INTO verses VALUES (27921, 44, 27, 10, 'dizendo a-eles Homens observo que com Ultraje e muita perda não somente o de-carga e o do-barco mas e o almas nosso estar-prestes ser o navegação');
INSERT INTO verses VALUES (27922, 44, 27, 11, 'o porém centurião o piloto e o piloto-do-navio mais obedecia ou o sob Paulo chamados');
INSERT INTO verses VALUES (27923, 44, 27, 12, 'inconveniente porém o porto existindo junto-a invernada o mais-numerosos puseram conselho zarpar dali se como pudessem tendo-chegado para Fenícia passar-o-inverno porto o Creta vendo segundo sudoeste e segundo lugar');
INSERT INTO verses VALUES (27924, 44, 27, 13, 'Tendo-soprado-suavemente porém sul tendo-parecido o propósito ter-retido tendo-levantado mais-perto navegavam-ao-longo o Creta');
INSERT INTO verses VALUES (27925, 44, 27, 14, 'com não muito porém lançou segundo dela vento tufônico o chamado Euroaquilão');
INSERT INTO verses VALUES (27926, 44, 27, 15, 'tendo-sido-arrebatado porém o do-barco e não podendo enfrentar o vento tendo-entregue Éramos-levados');
INSERT INTO verses VALUES (27927, 44, 27, 16, 'pequena-ilha e/mas algo Tendo-navegado-sob chamado Clauda fomos-capazes dificilmente tendo-domínio tornar-se o bote');
INSERT INTO verses VALUES (27928, 44, 27, 17, 'o qual tendo-levantado auxílios Usavam Cingindo-por-baixo o barco tementes e não para o Sirte caiam-fora tendo-baixado o vaso assim Eram-levados');
INSERT INTO verses VALUES (27929, 44, 27, 18, 'veementemente porém sendo-açoitados-pela-tempestade nosso o na-sequência lançamento-fora Faziam-para-si');
INSERT INTO verses VALUES (27930, 44, 27, 19, 'e o no-terceiro com-as-próprias-mãos o equipamento o do-barco lançaram');
INSERT INTO verses VALUES (27931, 44, 27, 20, 'nem porém sol nem estrelas Aparecendo sobre mais do-dia de-inverno e não pouco imposto-sobre restante era-removida esperança toda o ser-salvo nos');
INSERT INTO verses VALUES (27932, 44, 27, 21, 'Muita e abstinência-de-comida Existindo então pondo-se-de-pé o Paulo em no-meio deles disse é necessário de-fato Ômega homens tendo-obedecido a-mim não zarpar de o Creta ganhar e o Ultraje esta e o perda');
INSERT INTO verses VALUES (27933, 44, 27, 22, 'e o agora aconselho vos estar-alegre rejeição pois alma nenhuma será de vosso porém o do-barco');
INSERT INTO verses VALUES (27934, 44, 27, 23, 'apresentou-se pois a-mim nesta o à-noite o de-Theos o qual sou o qual e sirvo anjo');
INSERT INTO verses VALUES (27935, 44, 27, 24, 'dizendo não temas Paulo César te é necessário apresentar e eis tem-sido-concedido a-ti o Theos todos o navegando com teu');
INSERT INTO verses VALUES (27936, 44, 27, 25, 'por-isso tende-ânimo homens creio pois o a-Theos que assim será segundo o qual modo tem-sido-falado a-mim');
INSERT INTO verses VALUES (27937, 44, 27, 26, 'para ilha e/mas alguém é necessário nos cair');
INSERT INTO verses VALUES (27938, 44, 27, 27, 'como porém décima-quarta noite aconteceu sendo-carregados nosso em o Ádria segundo meio o da-noite supunham o marinheiros trazer algum a-eles região');
INSERT INTO verses VALUES (27939, 44, 27, 28, 'e tendo-lançado-sonda encontraram braças vinte pouco porém tendo-separado e novamente tendo-lançado-sonda encontraram braças quinze');
INSERT INTO verses VALUES (27940, 44, 27, 29, 'tementes e não em-algum-lugar segundo ásperos lugares caiamos-fora de de-popa tendo-lançado âncoras quatro desejavam dia tornar-se');
INSERT INTO verses VALUES (27941, 44, 27, 30, 'o porém marinheiros buscando fugir de o do-barco e tendo-abaixado o bote para o mar pretexto como de de-proa âncoras estando-para estender');
INSERT INTO verses VALUES (27942, 44, 27, 31, 'disse o Paulo o centurião e o soldados se não estes permaneçam em o no-barco vós ser-salvo não podeis');
INSERT INTO verses VALUES (27943, 44, 27, 32, 'então cortaram o soldados o cordas o bote e permitiram ela cair');
INSERT INTO verses VALUES (27944, 44, 27, 33, 'até porém o qual dia estava-prestes-a tornar-se suplicava o Paulo todos participar alimento dizendo Décima-quarta hoje dia esperando sem-alimento persistis nada tendo-tomado-consigo');
INSERT INTO verses VALUES (27945, 44, 27, 34, 'por-isso rogo vos participar alimento isto pois junto-a o vossa salvação existe de-ninguém pois vosso cabelo de o cabeça perecerá');
INSERT INTO verses VALUES (27946, 44, 27, 35, 'disseste porém estas-coisas e tomando pão deu-graças o a-Theos diante-de todos e partindo começou comer');
INSERT INTO verses VALUES (27947, 44, 27, 36, 'animados porém tendo-se-tornado todos e eles-mesmos receberam-consigo alimento');
INSERT INTO verses VALUES (27948, 44, 27, 37, 'estávamos porém o todas almas em o no-barco duzentas setenta seis');
INSERT INTO verses VALUES (27949, 44, 27, 38, 'tendo-sido-saciados porém alimento aliviavam o barco sendo-lançados-fora o trigo para o mar');
INSERT INTO verses VALUES (27950, 44, 27, 39, 'quando porém dia aconteceu o terra não reconheciam seio e/mas alguém consideravam tendo praia para o qual deliberavam se pudessem empurrar-para-fora o barco');
INSERT INTO verses VALUES (27951, 44, 27, 40, 'e o âncoras tendo-removido permitiam para o mar juntamente tendo-afrouxado o correias o lemes e tendo-levantado o vela-de-proa o soprando retinham para o praia');
INSERT INTO verses VALUES (27952, 44, 27, 41, 'tendo-caído-entre porém para lugar entre-dois-mares encalharam o navio e o por-um-lado proa Tendo-encalhado permaneceu inabalável o porém popa era-desatado sob o violência');
INSERT INTO verses VALUES (27953, 44, 27, 42, 'o porém soldados conselho aconteceu para que o prisioneiros matem não alguém tendo-nadado-para-fora escape');
INSERT INTO verses VALUES (27954, 44, 27, 43, 'o porém centurião querendo salvar o Paulo impediu eles o vontade ordenou e o podendo nadar tendo-lançado primeiro sobre o terra sair');
INSERT INTO verses VALUES (27955, 44, 27, 44, 'e o restantes o qual por-um-lado sobre em-tábuas o qual porém sobre alguns o de o do-barco e assim aconteceu todos ser-salvo sobre o terra');
INSERT INTO chapters VALUES (1046, 44, 28, 30);
INSERT INTO verses VALUES (27956, 44, 28, 1, 'e tendo-sido-salvos então conhecemos-plenamente que Malta o ilha chama-se');
INSERT INTO verses VALUES (27957, 44, 28, 2, 'o e bárbaros forneciam não o tendo-obtido filantropia a-nós tendo-acendido pois fogueira receberam-consigo todos nos através-de o chuva o Estando-presente e através-de o frio');
INSERT INTO verses VALUES (27958, 44, 28, 3, 'tendo-ajuntado porém o Paulo de-gravetos algo multidão e tendo-posto-sobre sobre o fogueira Víbora de o calor tendo-saído atou o da-mão dele');
INSERT INTO verses VALUES (27959, 44, 28, 4, 'como porém vi o bárbaros pendurando o besta de o da-mão dele junto-a uns-aos-outros diziam Certamente homicida é o homem este o qual tendo-sido-salvo de o do-mar o Justiça viver não permitiu');
INSERT INTO verses VALUES (27960, 44, 28, 5, 'o por-um-lado portanto tendo-sacudido o besta para o fogo sofreu nada mal');
INSERT INTO verses VALUES (27961, 44, 28, 6, 'o porém esperavam ele estar-prestes inchar ou cair subitamente morto sobre muito porém deles esperando e contemplando nada absurdo para ele acontecendo tendo-mudado diziam ele ser Theon');
INSERT INTO verses VALUES (27962, 44, 28, 7, 'em porém o acerca-de o lugar aquele existia campos o primeiro o ilha em-nome Públio o qual tendo-recebido nos do-dia três cordialmente hospedou');
INSERT INTO verses VALUES (27963, 44, 28, 8, 'aconteceu porém o Pai o Públio em-febres e disenteria sendo-constrangido estar-reclinado junto-a o qual o Paulo entrando e tendo-orado pondo-sobre o mãos a ele curou ele');
INSERT INTO verses VALUES (27964, 44, 28, 9, 'deste porém tendo-acontecido e o restantes o em o ilha tendo fraqueza aproximavam-se e eram-curados');
INSERT INTO verses VALUES (27965, 44, 28, 10, 'o qual e muitas honras Honraram nos e aos-que-estão-navegando colocaram-sobre o junto-a o necessidade');
INSERT INTO verses VALUES (27966, 44, 28, 11, 'com porém três meses navegamos em no-barco tendo-invernado em o ilha Alexandrino com-insígnia Dióscuros');
INSERT INTO verses VALUES (27967, 44, 28, 12, 'e tendo-sido-conduzidos-abaixo para Siracusa permanecemos do-dia três');
INSERT INTO verses VALUES (27968, 44, 28, 13, 'de-onde tendo-percorrido chegamos para Régio e com uma dia tendo-sobrevindo sul no-segundo-dia viemos para Putéolos');
INSERT INTO verses VALUES (27969, 44, 28, 14, 'do-qual tendo-encontrado irmãos fomos-exortados de-junto-de a-eles permanecer do-dia sete e assim para o Roma Viemos');
INSERT INTO verses VALUES (27970, 44, 28, 15, 'e-de-lá o irmãos ouvindo o acerca-de nosso vieram para encontro a-nós até Ápio Fóro e três Tabernas o qual vendo o Paulo tendo-dado-graças o a-Theos Recebeu coragem');
INSERT INTO verses VALUES (27971, 44, 28, 16, 'quando porém entramos para Roma foi-permitido o a-Paulo permanecer segundo si-mesmo com o ao-que-guarda ele soldado');
INSERT INTO verses VALUES (27972, 44, 28, 17, 'aconteceu porém com do-dia três convocar ele o sendo o judeus primeiro tendo-se-reunido porém deles dizia junto-a eles Eu homens irmãos nada diante-de tendo-feito o povo ou o Costumes o paternos prisioneiro de Jerusalém fui-entregue para o mãos o Romanos');
INSERT INTO verses VALUES (27973, 44, 28, 18, 'os-quais tendo-examinado me desejavam soltar através-de o nenhuma causa da-morte existir em a-mim');
INSERT INTO verses VALUES (27974, 44, 28, 19, 'contradizendo porém o judeus fui-forçado invocar César não como o nação meu tendo algo acusar');
INSERT INTO verses VALUES (27975, 44, 28, 20, 'através-de esta portanto o causa exortei vos ver e falar-a por-causa-de pois o da-esperança o Israel o cadeia esta estou-rodeado');
INSERT INTO verses VALUES (27976, 44, 28, 21, 'o porém junto-a ele disseram nós nem letras acerca-de teu recebemos de o Judeia nem tendo-chegado alguém o dos-irmãos anunciou ou falou algo acerca-de teu mau');
INSERT INTO verses VALUES (27977, 44, 28, 22, 'consideramos-digno porém de-junto-de teu ouvir o qual pensas acerca-de por-um-lado pois o heresia desta conhecido a-nós é que por-toda-parte é-contradito');
INSERT INTO verses VALUES (27978, 44, 28, 23, 'Tendo-designado porém a ele dia vieram junto-a ele para o hospedagem mais-numerosos o qual expunha testificando o reino o de-Theos persuadindo e eles acerca-de o Iesous de e o da-lei de-Moisés e o profetas de de-manhã até Tarde');
INSERT INTO verses VALUES (27979, 44, 28, 24, 'e o por-um-lado eram-persuadidos o chamados o porém não-criam');
INSERT INTO verses VALUES (27980, 44, 28, 25, 'em-desacordo porém sendo junto-a uns-aos-outros eram-soltos tendo-dito o Paulo palavra um que Bem o espírito o santo falou através-de Isaías o profeta junto-a o pais vosso');
INSERT INTO verses VALUES (27981, 44, 28, 26, 'dizendo Vai junto-a o povo este e dize Ouvido ouvireis e não não compreendais e vendo vereis e não não vejais');
INSERT INTO verses VALUES (27982, 44, 28, 27, 'engrossou-se pois o coração o povo deste e o ouvidos pesadamente ouviram e o olhos deles fecharam não alguma-vez vejam o olhos e o ouvidos ouçam e o no-coração compreendam e convertam-se e curarei eles');
INSERT INTO verses VALUES (27983, 44, 28, 28, 'conhecido portanto seja a-vós que o nações foi-enviado isto o salvação o de-Theos eles-mesmos e ouvirão');
INSERT INTO verses VALUES (27984, 44, 28, 30, 'Permaneceu porém dois-anos toda em próprio aluguel e recebia todos o entrando junto-a ele');
INSERT INTO verses VALUES (27985, 44, 28, 31, 'pregando o reino o de-Theos e ensinando o acerca-de o do-Kyrios Iesous de-Christos com toda ousadia sem-impedimento');
INSERT INTO books VALUES (45, 'ROM', 'Romanos', 'NT', 16);
INSERT INTO chapters VALUES (1047, 45, 1, 32);
INSERT INTO verses VALUES (27986, 45, 1, 1, 'Paulo servo de-Christos Iesous chamado apóstolo tendo-sido-separado para evangelho de-Theos');
INSERT INTO verses VALUES (27987, 45, 1, 2, 'o qual prometeu-de-antemão através-de o profetas dele em escrituras santas');
INSERT INTO verses VALUES (27988, 45, 1, 3, 'acerca-de o do-Filho dele o tendo-acontecido de semente Davi segundo carne');
INSERT INTO verses VALUES (27989, 45, 1, 4, 'o tendo-sido-determinado do-Filho de-Theos em poder segundo espírito santidade de da-ressurreição mortos Iesous de-Christos o do-Kyrios nosso');
INSERT INTO verses VALUES (27990, 45, 1, 5, 'através-de o qual recebemos graça e apostolado para obediência da-fé em todos o nações em-favor-de o do-nome dele');
INSERT INTO verses VALUES (27991, 45, 1, 6, 'em o qual sois e vós chamados Iesous de-Christos');
INSERT INTO verses VALUES (27992, 45, 1, 7, 'todos o estando em Roma amados de-Theos chamados santos graça a-vós e paz de de-Theos do-Pai nosso e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (27993, 45, 1, 8, 'primeiro por-um-lado dou-graças o a-Theos meu através-de Iesous de-Christos acerca-de todos vosso que o fé vosso é-anunciado em todo o ao-mundo');
INSERT INTO verses VALUES (27994, 45, 1, 9, 'testemunha pois meu é o Theos o qual sirvo em o espírito meu em o no-evangelho o do-Filho dele como incessantemente menção vosso faço');
INSERT INTO verses VALUES (27995, 45, 1, 10, 'sempre sobre o orações meu suplicando se como já alguma-vez serei-prosperado em o vontade o de-Theos vir junto-a vos');
INSERT INTO verses VALUES (27996, 45, 1, 11, 'desejo-ardentemente pois ver vos para que algo reparta dom a-vós espiritual para o ser-firmado vos');
INSERT INTO verses VALUES (27997, 45, 1, 12, 'isto e/mas é ser-co-encorajado em a-vós através-de o em uns-aos-outros da-fé vosso e e mim');
INSERT INTO verses VALUES (27998, 45, 1, 13, 'não quero porém vos ignorar irmãos que muitas-vezes propus vir junto-a vos e fui-impedido até o vem para que algum fruto tenha e em a-vós assim-como e em o restantes nações');
INSERT INTO verses VALUES (27999, 45, 1, 14, 'Gregos e e bárbaros sábios e e insensatos devedor sou');
INSERT INTO verses VALUES (28000, 45, 1, 15, 'assim o segundo mim pronto e a-vós o em Roma evangelizar');
INSERT INTO verses VALUES (28001, 45, 1, 16, 'não pois envergonho-me o evangelho poder pois de-Theos é para salvação todo o crente judeu e primeiro e Grego');
INSERT INTO verses VALUES (28002, 45, 1, 17, 'justiça pois de-Theos em a ele é-revelado de da-fé para fé assim-como está-escrito o porém justo de da-fé viverá');
INSERT INTO verses VALUES (28003, 45, 1, 18, 'É-revelado pois ira de-Theos de do-céu sobre toda impiedade e injustiça dos-homens o o verdade em injustiça retendo');
INSERT INTO verses VALUES (28004, 45, 1, 19, 'porque o conhecido o de-Theos manifesto é em a-eles o Theos pois a-eles manifestou');
INSERT INTO verses VALUES (28005, 45, 1, 20, 'o pois invisíveis dele de criação do-mundo o obras sendo-compreendidas é-percebido-claramente o e eterno dele poder e divindade para o ser eles indesculpáveis');
INSERT INTO verses VALUES (28006, 45, 1, 21, 'porque conhecendo o Theos não como Theos glorificaram ou deram-graças mas foram-feitos-vãos em o raciocínios deles e Foi-obscurecido o sem-entendimento deles coração');
INSERT INTO verses VALUES (28007, 45, 1, 22, 'declarando ser sábios foram-feitos-tolos');
INSERT INTO verses VALUES (28008, 45, 1, 23, 'e Trocaram o glória o incorruptível de-Theos em semelhança imagem corruptível do-homem e aves e quadrúpedes e répteis');
INSERT INTO verses VALUES (28009, 45, 1, 24, 'por-isso entregou eles o Theos em o desejos o corações deles para impureza o ser-desonrado o corpos deles em a-eles');
INSERT INTO verses VALUES (28010, 45, 1, 25, 'os-quais trocaram o verdade o de-Theos em o mentira e Veneraram e serviram-em-culto o criação de-junto-de o Tendo-criado o qual é bendito para o eras amém');
INSERT INTO verses VALUES (28011, 45, 1, 26, 'através-de isto entregou eles o Theos para paixões desonra o e pois fêmeas deles trocaram o natural uso para o de-junto-de natureza');
INSERT INTO verses VALUES (28012, 45, 1, 27, 'semelhantemente e e o machos deixando o natural uso o fêmea inflamaram-se em o apetite deles para uns-aos-outros machos em machos o vergonha realizando e o retribuição o qual é necessário o engano deles em si-mesmos recebendo');
INSERT INTO verses VALUES (28013, 45, 1, 28, 'e assim-como não aprovaram o Theos ter em conhecimento-pleno entregou eles o Theos para reprovado entendimento fazer o não convindo');
INSERT INTO verses VALUES (28014, 45, 1, 29, 'tendo-sido-cumpridos toda injustiça maldade ganância maldade cheios inveja homicídio Contenda engano malícia murmuradores');
INSERT INTO verses VALUES (28015, 45, 1, 30, 'caluniadores odiadores-de-Theos insolentes soberbos arrogantes Inventores males pais desobedientes');
INSERT INTO verses VALUES (28016, 45, 1, 31, 'sem-entendimento sem-aliança sem-afeição-natural sem-misericórdia');
INSERT INTO verses VALUES (28017, 45, 1, 32, 'os-quais o ordenança-justa o de-Theos reconhecendo que o o tais-coisas praticando dignos da-morte são não somente elas fazem mas e consentem o praticam');
INSERT INTO chapters VALUES (1048, 45, 2, 29);
INSERT INTO verses VALUES (28018, 45, 2, 1, 'por-isso indesculpável és Ômega homem todo o julgando em o qual pois julgas o outro a-ti-mesmo condenas o pois elas praticas o julgando');
INSERT INTO verses VALUES (28019, 45, 2, 2, 'sei porém que o julgamento o de-Theos é segundo verdade sobre o o tais-coisas praticando');
INSERT INTO verses VALUES (28020, 45, 2, 3, 'consideras porém isto Ômega homem o julgando o o tais-coisas praticando e fazendo elas que tu escaparás o julgamento o de-Theos');
INSERT INTO verses VALUES (28021, 45, 2, 4, 'ou o riqueza o de-benignidade dele e o paciência e o paciência desprezas ignorando que o benigno o de-Theos para arrependimento te conduz');
INSERT INTO verses VALUES (28022, 45, 2, 5, 'segundo porém o dureza teu e impenitente coração entesourás a-ti-mesmo ira em dia ira e revelação justo-julgamento o de-Theos');
INSERT INTO verses VALUES (28023, 45, 2, 6, 'o qual retribuirá a-cada-um segundo o obra dele');
INSERT INTO verses VALUES (28024, 45, 2, 7, 'o por-um-lado segundo perseverança obra bom glória e honra e incorruptibilidade buscam vida eterno');
INSERT INTO verses VALUES (28025, 45, 2, 8, 'o porém de contenda e desobedecem o verdade sendo-persuadidos porém o injustiça ira e ira');
INSERT INTO verses VALUES (28026, 45, 2, 9, 'tribulação e angústia sobre toda alma do-homem o realizando o mal Judeu e primeiro e grego');
INSERT INTO verses VALUES (28027, 45, 2, 10, 'glória porém e honra e paz todo o trabalhando o bom judeu e primeiro e Grego');
INSERT INTO verses VALUES (28028, 45, 2, 11, 'não pois é acepção-de-pessoas de-junto-de o a-Theos');
INSERT INTO verses VALUES (28029, 45, 2, 12, 'quanto pois sem-lei pecaram sem-lei e perecerão e quanto em lei pecaram através-de da-lei serão-julgados');
INSERT INTO verses VALUES (28030, 45, 2, 13, 'não pois o ouvintes da-lei justos de-junto-de o a-Theos mas o praticantes da-lei serão-justificados');
INSERT INTO verses VALUES (28031, 45, 2, 14, 'quando pois nações o não lei tendo natureza o o da-lei façam estes lei não tendo si-mesmos são lei');
INSERT INTO verses VALUES (28032, 45, 2, 15, 'os-quais mostram o obra o da-lei escrito em o corações deles co-testemunhando deles o consciência e entre uns-aos-outros o raciocínios acusando ou e defendendo-se');
INSERT INTO verses VALUES (28033, 45, 2, 16, 'em o qual dia julga o Theos o ocultas o dos-homens segundo o boa-nova meu através-de de-Christos Iesous');
INSERT INTO verses VALUES (28034, 45, 2, 17, 'se porém tu judeu Te-denominas e descansas-sobre lei e glorias-te em a-Theos');
INSERT INTO verses VALUES (28035, 45, 2, 18, 'e conheces o vontade e examinas o importando sendo-instruído de o da-lei');
INSERT INTO verses VALUES (28036, 45, 2, 19, 'tens-confiado e a-ti-mesmo guia ser cegos luz o em trevas');
INSERT INTO verses VALUES (28037, 45, 2, 20, 'disciplinador insensatos mestre criancinhas tendo o forma-exterior o do-conhecimento e o da-verdade em o lei');
INSERT INTO verses VALUES (28038, 45, 2, 21, 'o portanto ensinando outro a-ti-mesmo não ensinas o pregando não furtar furtas');
INSERT INTO verses VALUES (28039, 45, 2, 22, 'o dizendo não adulterar cometes-adultério o abominando o ídolos Roubas-templos');
INSERT INTO verses VALUES (28040, 45, 2, 23, 'o qual em lei glorias-te através-de o transgressão o da-lei o Theos desonras');
INSERT INTO verses VALUES (28041, 45, 2, 24, 'o pois nome o de-Theos através-de vos é-blasfemado em o nações assim-como está-escrito');
INSERT INTO verses VALUES (28042, 45, 2, 25, 'circuncisão por-um-lado pois aproveita se lei pratiques se porém transgressor da-lei Fosses o circuncisão teu incircuncisão aconteceu');
INSERT INTO verses VALUES (28043, 45, 2, 26, 'se portanto o incircuncisão o atos-justos o da-lei guarde não o incircuncisão dele para circuncisão será-considerado');
INSERT INTO verses VALUES (28044, 45, 2, 27, 'e julgará o de natureza incircuncisão o lei completando te o através-de letra e da-circuncisão transgressor da-lei');
INSERT INTO verses VALUES (28045, 45, 2, 28, 'não pois o em o manifesto judeu é nem o em o manifesto em carne circuncisão');
INSERT INTO verses VALUES (28046, 45, 2, 29, 'mas o em o oculto judeu e circuncisão do-coração em espírito não letra o qual o louvor não de dos-homens mas de o de-Theos');
INSERT INTO chapters VALUES (1049, 45, 3, 31);
INSERT INTO verses VALUES (28047, 45, 3, 1, 'quê portanto o abundante o Judeu ou quem o Proveito o da-circuncisão');
INSERT INTO verses VALUES (28048, 45, 3, 2, 'muito segundo todas-as-coisas modo primeiro por-um-lado pois que foram-confiados o oráculos o de-Theos');
INSERT INTO verses VALUES (28049, 45, 3, 3, 'quê pois se descreram alguns não o incredulidade deles o fé o de-Theos anulará');
INSERT INTO verses VALUES (28050, 45, 3, 4, 'não seja-assim seja porém o Theos verdadeiro todo porém homem mentiroso assim-como está-escrito para-que partícula-condicional sejas-justificado em o palavras teu e vencerás em o ser-julgado te');
INSERT INTO verses VALUES (28051, 45, 3, 5, 'se porém o injustiça nosso de-Theos justiça recomenda quê diremos não injusto o Theos o Trazendo-sobre o ira segundo homem digo');
INSERT INTO verses VALUES (28052, 45, 3, 6, 'não seja-assim porque como julgará o Theos o mundo');
INSERT INTO verses VALUES (28053, 45, 3, 7, 'se porém o verdade o de-Theos em o meu mentira abundou para o glória dele quê ainda e-eu como pecador sou-julgado');
INSERT INTO verses VALUES (28054, 45, 3, 8, 'e não assim-como somos-blasfemados e assim-como dizem alguns nos dizer que Façamos o males para que venha o boas-coisas o qual o julgamento Justa é');
INSERT INTO verses VALUES (28055, 45, 3, 9, 'quê portanto temos-vantagem não de-todo-modo acusamos-anteriormente pois judeus e e Gregos todos sob pecado ser');
INSERT INTO verses VALUES (28056, 45, 3, 10, 'assim-como está-escrito que não é justo nem um');
INSERT INTO verses VALUES (28057, 45, 3, 11, 'não é o compreendendo não é o buscando-diligentemente o Theos');
INSERT INTO verses VALUES (28058, 45, 3, 12, 'todos desviaram-se juntamente Tornaram-se-inúteis não é o fazendo benignidade não é até um');
INSERT INTO verses VALUES (28059, 45, 3, 13, 'sepulcro tendo-sido-aberto o garganta deles o em-línguas deles enganavam veneno víboras sob o lábios deles');
INSERT INTO verses VALUES (28060, 45, 3, 14, 'o qual o boca maldição e amargura está-cheio');
INSERT INTO verses VALUES (28061, 45, 3, 15, 'afiados o pés deles derramar sangue');
INSERT INTO verses VALUES (28062, 45, 3, 16, 'destruição e miséria em o caminhos deles');
INSERT INTO verses VALUES (28063, 45, 3, 17, 'e caminho paz não conheceram');
INSERT INTO verses VALUES (28064, 45, 3, 18, 'não é medo de-Theos diante-de o olhos deles');
INSERT INTO verses VALUES (28065, 45, 3, 19, 'sei porém que quanto o lei diz o em o lei fala para que todo boca seja-fechada e Sob-juízo aconteça todo o mundo o a-Theos');
INSERT INTO verses VALUES (28066, 45, 3, 20, 'porque de obra da-lei não será-justificado toda carne diante-de dele através-de pois da-lei pleno-conhecimento do-pecado');
INSERT INTO verses VALUES (28067, 45, 3, 21, 'Agora porém sem da-lei justiça de-Theos tem-sido-manifestado sendo-testificada sob o da-lei e o profetas');
INSERT INTO verses VALUES (28068, 45, 3, 22, 'justiça porém de-Theos através-de da-fé Iesous de-Christos para todos o crentes não pois é distinção');
INSERT INTO verses VALUES (28069, 45, 3, 23, 'todos pois pecaram e São-privados o da-glória o de-Theos');
INSERT INTO verses VALUES (28070, 45, 3, 24, 'sendo-justificados gratuitamente o dele graça através-de o redenção o em em-Christos Iesous');
INSERT INTO verses VALUES (28071, 45, 3, 25, 'o qual propôs o Theos propiciatório através-de da-fé em o dele sangue para demonstração o justiça dele através-de o passagem o tendo-acontecido-antes pecados');
INSERT INTO verses VALUES (28072, 45, 3, 26, 'em o paciência o de-Theos junto-a o demonstração o justiça dele em o agora tempo para o ser ele justo e justificando o de da-fé Iesous');
INSERT INTO verses VALUES (28073, 45, 3, 27, 'onde portanto o glória foi-excluído através-de qual da-lei o obra não mas através-de da-lei da-fé');
INSERT INTO verses VALUES (28074, 45, 3, 28, 'consideramos pois ser-justificado fé homem sem obra da-lei');
INSERT INTO verses VALUES (28075, 45, 3, 29, 'ou judeus o Theos somente não e nações sim e nações');
INSERT INTO verses VALUES (28076, 45, 3, 30, 'se-de-fato um o Theos o qual justificação circuncisão de da-fé e prepúcio através-de o da-fé');
INSERT INTO verses VALUES (28077, 45, 3, 31, 'lei portanto anulamos através-de o da-fé não seja-assim mas lei Estabelecemos');
INSERT INTO chapters VALUES (1050, 45, 4, 25);
INSERT INTO verses VALUES (28078, 45, 4, 1, 'quê portanto diremos ter-encontrado Abraão o antepassado nosso segundo carne');
INSERT INTO verses VALUES (28079, 45, 4, 2, 'se pois Abraão de obra foi-justificado tem orgulho mas não junto-a Theos');
INSERT INTO verses VALUES (28080, 45, 4, 3, 'quê pois o escritura diz Acreditou porém Abraão o a-Theos e foi-contado a ele para justiça');
INSERT INTO verses VALUES (28081, 45, 4, 4, 'o porém trabalhando o salário não é-contado segundo graça mas segundo dívida');
INSERT INTO verses VALUES (28082, 45, 4, 5, 'o porém não trabalhando crente porém sobre o justificando o ímpio é-contado o fé dele para justiça');
INSERT INTO verses VALUES (28083, 45, 4, 6, 'assim-como e Davi diz o bem-aventurança o do-homem o qual o Theos é-contado justiça sem obra');
INSERT INTO verses VALUES (28084, 45, 4, 7, 'bem-aventurados o qual foram-perdoados o iniquidades e o qual foram-cobertos o pecados');
INSERT INTO verses VALUES (28085, 45, 4, 8, 'bem-aventurado homem o qual não não considere Kyrios pecado');
INSERT INTO verses VALUES (28086, 45, 4, 9, 'o bem-aventurança portanto este sobre o circuncisão ou e sobre o prepúcio dizemos pois Foi-contado o Abraão o fé para justiça');
INSERT INTO verses VALUES (28087, 45, 4, 10, 'como portanto foi-contado em circuncisão estando ou em incircuncisão não em circuncisão mas em incircuncisão');
INSERT INTO verses VALUES (28088, 45, 4, 11, 'e sinal recebeu da-circuncisão selo o da-justiça o da-fé o em o incircuncisão para o ser ele Pai todos o crentes através-de incircuncisão para o ser-considerado a-eles o justiça');
INSERT INTO verses VALUES (28089, 45, 4, 12, 'e Pai da-circuncisão o não de da-circuncisão somente mas e o caminham o pegadas o em incircuncisão da-fé o do-Pai nosso Abraão');
INSERT INTO verses VALUES (28090, 45, 4, 13, 'não pois através-de da-lei o promessa o Abraão ou o semente dele o herdeiro ele ser do-mundo mas através-de justiça da-fé');
INSERT INTO verses VALUES (28091, 45, 4, 14, 'se pois o de da-lei herdeiros tem-sido-esvaziado o fé e tem-sido-anulado o promessa');
INSERT INTO verses VALUES (28092, 45, 4, 15, 'o pois lei ira opera do-qual porém não é lei nem transgressão');
INSERT INTO verses VALUES (28093, 45, 4, 16, 'através-de isto de da-fé para que segundo graça para o ser firme o promessa todo o semente não o de o da-lei somente mas e o de da-fé Abraão o qual é Pai todos nosso');
INSERT INTO verses VALUES (28094, 45, 4, 17, 'assim-como está-escrito que Pai muitos nações tenho-posto te defronte-de o qual creu de-Theos o vivificando o mortos e chamante o não sendo como sendo');
INSERT INTO verses VALUES (28095, 45, 4, 18, 'o qual de esperança sobre esperança creu para o tornar-se ele Pai muitos nações segundo o dito assim será o semente teu');
INSERT INTO verses VALUES (28096, 45, 4, 19, 'e não tendo-adoecido o fé considerou o si-mesmo corpo tendo-sido-mortificado De-cem-anos em-algum-lugar sendo e o mortificação o ventre Sara');
INSERT INTO verses VALUES (28097, 45, 4, 20, 'para porém o promessa o de-Theos não duvidou o incredulidade mas foi-fortalecido o fé dando glória o a-Theos');
INSERT INTO verses VALUES (28098, 45, 4, 21, 'e tendo-sido-plenamente-convicto que o qual tem-prometido poderoso é e fazer');
INSERT INTO verses VALUES (28099, 45, 4, 22, 'por-isso e foi-contado a ele para justiça');
INSERT INTO verses VALUES (28100, 45, 4, 23, 'não foi-escrito porém através-de ele somente que foi-contado a ele');
INSERT INTO verses VALUES (28101, 45, 4, 24, 'mas e através-de nos o qual está-para considerar o creem sobre o tendo-levantado Iesous o Kyrion nosso de mortos');
INSERT INTO verses VALUES (28102, 45, 4, 25, 'o qual foi-entregue através-de o transgressões nosso e foi-ressuscitado através-de o justificação nosso');
INSERT INTO chapters VALUES (1051, 45, 5, 21);
INSERT INTO verses VALUES (28103, 45, 5, 1, 'Tendo-sido-justificados portanto de da-fé paz tenhamos junto-a o Theos através-de o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (28104, 45, 5, 2, 'através-de o qual e o acesso temos-tido o fé para o graça esta em o qual Temos-permanecido-de-pé e gloriamo-nos sobre esperança o da-glória o de-Theos');
INSERT INTO verses VALUES (28105, 45, 5, 3, 'não somente e/mas mas e gloriamo-nos em o tribulações sei que o tribulação perseverança opera');
INSERT INTO verses VALUES (28106, 45, 5, 4, 'o porém perseverança prova o porém prova esperança');
INSERT INTO verses VALUES (28107, 45, 5, 5, 'o porém esperança não envergonha que o amor o de-Theos tem-sido-derramado em o corações nosso através-de do-espírito do-santo o tendo-sido-dado a-nós');
INSERT INTO verses VALUES (28108, 45, 5, 6, 'ainda pois Christos existindo nosso fracos ainda segundo tempo em-favor-de ímpios morreu');
INSERT INTO verses VALUES (28109, 45, 5, 7, 'dificilmente pois em-favor-de justo alguém morrerá em-favor-de pois o bom talvez alguém e ousa morrer');
INSERT INTO verses VALUES (28110, 45, 5, 8, 'recomenda porém o si-mesmo amor para nos o Theos que ainda dos-pecadores existindo nosso Christos em-favor-de nosso morreu');
INSERT INTO verses VALUES (28111, 45, 5, 9, 'muito portanto mais tendo-sido-justificados agora em o sangue dele seremos-salvos através-de dele de o ira');
INSERT INTO verses VALUES (28112, 45, 5, 10, 'se pois inimigos sendo fomos-reconciliados o a-Theos através-de o da-morte o do-Filho dele muito mais tendo-sido-reconciliados seremos-salvos em o vida dele');
INSERT INTO verses VALUES (28113, 45, 5, 11, 'não somente e/mas mas e gloriando-se em o a-Theos através-de o do-Kyrios nosso Iesous de-Christos através-de o qual agora o reconciliação recebemos');
INSERT INTO verses VALUES (28114, 45, 5, 12, 'através-de isto como através-de um do-homem o pecado para o mundo entrou e através-de o do-pecado o morte e assim para todos homens o morte atravessou sobre o qual todos pecaram');
INSERT INTO verses VALUES (28115, 45, 5, 13, 'até pois da-lei pecado era em ao-mundo pecado porém não é-imputado não sendo da-lei');
INSERT INTO verses VALUES (28116, 45, 5, 14, 'mas reinou o morte de Adão até Moisés e sobre o não tendo-pecado sobre o semelhança o transgressão Adão o qual é modelo o do-que-está-por-vir');
INSERT INTO verses VALUES (28117, 45, 5, 15, 'mas não como o transgressão assim e o dom se pois o o um transgressão o muitos morreram muito mais o graça o de-Theos e o dom em graça o o um do-homem Iesous de-Christos para o a-muitos abundou');
INSERT INTO verses VALUES (28118, 45, 5, 16, 'e não como através-de um tendo-pecado o dádiva o por-um-lado pois julgamento de um para condenação o porém dom de muitos transgressões para ordenança-justa');
INSERT INTO verses VALUES (28119, 45, 5, 17, 'se pois o o um transgressão o morte reinou através-de o um muito mais o o abundância o da-graça e o dom o justiça recebendo em vida reinarão através-de o um Iesous de-Christos');
INSERT INTO verses VALUES (28120, 45, 5, 18, 'então portanto como através-de um de-transgressão para todos homens para condenação assim e através-de um ordenança para todos homens para justificação da-vida');
INSERT INTO verses VALUES (28121, 45, 5, 19, 'como pois através-de o de-desobediência o de-um do-homem pecadores foram-constituídos o muitos assim e através-de o obediência o de-um justos serão-constituídos o muitos');
INSERT INTO verses VALUES (28122, 45, 5, 20, 'lei porém entrou-secretamente para que abunde o transgressão do-qual porém abundou o pecado Superabundou o graça');
INSERT INTO verses VALUES (28123, 45, 5, 21, 'para que assim-como reinou o pecado em o morte assim e o graça reine através-de da-justiça para vida eterno através-de Iesous de-Christos o do-Kyrios nosso');
INSERT INTO chapters VALUES (1052, 45, 6, 23);
INSERT INTO verses VALUES (28124, 45, 6, 1, 'quê portanto diremos permaneçamos o pecado para que o graça abunde');
INSERT INTO verses VALUES (28125, 45, 6, 2, 'não seja-assim os-quais morremos o pecado como ainda viveremos em a-ela');
INSERT INTO verses VALUES (28126, 45, 6, 3, 'ou ignorais que quanto fomos-batizados para Christos Iesous para o morte dele fomos-batizados');
INSERT INTO verses VALUES (28127, 45, 6, 4, 'fomos-co-sepultados portanto a ele através-de o batismo para o morte para que assim-como foi-ressuscitado Christos de mortos através-de o da-glória o do-Pai assim e nós em novidade da-vida andemos');
INSERT INTO verses VALUES (28128, 45, 6, 5, 'se pois co-plantados tornamo-nos o semelhança o da-morte dele mas e o da-ressurreição seremos');
INSERT INTO verses VALUES (28129, 45, 6, 6, 'isto conhecendo que o velho nosso homem foi-co-crucificado para que seja-anulado o corpo o do-pecado o não-mais servir nos o pecado');
INSERT INTO verses VALUES (28130, 45, 6, 7, 'o pois tendo-morrido tem-sido-justificado de o do-pecado');
INSERT INTO verses VALUES (28131, 45, 6, 8, 'se porém morremos com em-Christos cremos que e co-viveremos a ele');
INSERT INTO verses VALUES (28132, 45, 6, 9, 'sei que Christos levantando-se de mortos não-mais morre morte dele não-mais domina');
INSERT INTO verses VALUES (28133, 45, 6, 10, 'o qual pois morreu o pecado morreu de-uma-vez-por-todas o qual porém vive vive o a-Theos');
INSERT INTO verses VALUES (28134, 45, 6, 11, 'assim e vós considerai si-mesmos ser mortos por-um-lado o pecado viventes porém o a-Theos em em-Christos Iesous');
INSERT INTO verses VALUES (28135, 45, 6, 12, 'não portanto reine o pecado em o mortal vosso corpo para o Obedecer o desejos dele');
INSERT INTO verses VALUES (28136, 45, 6, 13, 'nem apresentai o membros vosso armas da-injustiça o pecado mas apresentai si-mesmos o a-Theos como de mortos viventes e o membros vosso armas da-justiça o a-Theos');
INSERT INTO verses VALUES (28137, 45, 6, 14, 'pecado pois vosso não dominará não pois sois sob lei mas sob graça');
INSERT INTO verses VALUES (28138, 45, 6, 15, 'quê portanto pequemos que não somos sob lei mas sob graça não seja-assim');
INSERT INTO verses VALUES (28139, 45, 6, 16, 'não sei que o qual apresentai si-mesmos servos para obediência escravos sois o qual obedecei Quer do-pecado para morte ou obediência para justiça');
INSERT INTO verses VALUES (28140, 45, 6, 17, 'graça porém o a-Theos que éreis servos o do-pecado obedecestes porém de do-coração para o qual fostes-entregues modelo ensino');
INSERT INTO verses VALUES (28141, 45, 6, 18, 'tendo-sido-libertados porém de o do-pecado fostes-escravizados o justiça');
INSERT INTO verses VALUES (28142, 45, 6, 19, 'humano digo através-de o fraqueza o carne vosso assim-como pois apresentastes o membros vosso escrava o impureza e o iniquidade para o iniquidade assim agora apresentai o membros vosso escrava o justiça para santificação');
INSERT INTO verses VALUES (28143, 45, 6, 20, 'quando pois servos éreis o do-pecado livres éreis o justiça');
INSERT INTO verses VALUES (28144, 45, 6, 21, 'quem portanto fruto tínheis então sobre o qual agora vos-envergonhais o pois fim daqueles morte');
INSERT INTO verses VALUES (28145, 45, 6, 22, 'agora e/mas tendo-sido-libertados de o do-pecado tendo-sido-escravizados porém o a-Theos tendes o fruto vosso para santificação o porém fim vida eterno');
INSERT INTO verses VALUES (28146, 45, 6, 23, 'o pois soldos o do-pecado morte o porém dom o de-Theos vida eterno em em-Christos Iesous o ao-Kyrios nosso');
INSERT INTO chapters VALUES (1053, 45, 7, 25);
INSERT INTO verses VALUES (28147, 45, 7, 1, 'ou ignorais irmãos conhecem pois lei falo que o lei domina o do-homem sobre quanto tempo vive');
INSERT INTO verses VALUES (28148, 45, 7, 2, 'o pois Sob-marido mulher o vivendo marido tem-sido-atado lei se porém morra o homem tem-sido-anulado de o da-lei o homem');
INSERT INTO verses VALUES (28149, 45, 7, 3, 'então portanto vivente o homem adúltera advertirá-divinamente se aconteça marido a-outro se porém morra o homem livre é de o da-lei o não ser ela adúltera acontecida marido a-outro');
INSERT INTO verses VALUES (28150, 45, 7, 4, 'de-modo-que irmãos meu e vós fostes-mortos o lei através-de o do-corpo o de-Christos para o tornar-se vos a-outro o de mortos tendo-sido-levantado para que frutifiquemos o a-Theos');
INSERT INTO verses VALUES (28151, 45, 7, 5, 'quando pois éramos em o na-carne o sofrimentos o dos-pecados o através-de o da-lei era-operado em o membros nosso para o frutificar o morte');
INSERT INTO verses VALUES (28152, 45, 7, 6, 'agora porém fomos-anulados de o da-lei tendo-morrido em o qual éramos-retidos de-modo-que servir nos em novidade do-espírito e não velhice letra');
INSERT INTO verses VALUES (28153, 45, 7, 7, 'quê portanto diremos o lei pecado não seja-assim mas o pecado não conheci se não através-de da-lei o e pois desejo não sei se não o lei dizia não desejarás');
INSERT INTO verses VALUES (28154, 45, 7, 8, 'ocasião porém tomando o pecado através-de o mandamento produziu em mim toda desejo sem pois da-lei pecado morta');
INSERT INTO verses VALUES (28155, 45, 7, 9, 'eu porém viviam sem da-lei alguma-vez tendo-vindo porém o mandamento o pecado reviveu');
INSERT INTO verses VALUES (28156, 45, 7, 10, 'eu porém morreram e foi-encontrado a-mim o mandamento o para vida esta para morte');
INSERT INTO verses VALUES (28157, 45, 7, 11, 'o pois pecado ocasião tomando através-de o mandamento enganou me e através-de dela matou');
INSERT INTO verses VALUES (28158, 45, 7, 12, 'de-modo-que o por-um-lado lei santo e o mandamento santa e justa e boa');
INSERT INTO verses VALUES (28159, 45, 7, 13, 'o portanto bom mim aconteceu morte não seja-assim mas o pecado para que apareça pecado através-de o bom a-mim realizando morte para que aconteça segundo excesso pecador o pecado através-de o mandamento');
INSERT INTO verses VALUES (28160, 45, 7, 14, 'sei pois que o lei espiritual é eu porém carnal sou tendo-sido-vendido sob o pecado');
INSERT INTO verses VALUES (28161, 45, 7, 15, 'o qual pois produzo não conheço não pois o qual quero isto pratico mas o qual odeio isto faço');
INSERT INTO verses VALUES (28162, 45, 7, 16, 'se porém o qual não quero isto faço concordo o lei que bom');
INSERT INTO verses VALUES (28163, 45, 7, 17, 'agora porém não-mais eu produzo ele mas o habitando-em em mim pecado');
INSERT INTO verses VALUES (28164, 45, 7, 18, 'sei pois que não habita em a-mim isto é em o na-carne meu bom o pois querer está-presente a-mim o porém realizar o belo não');
INSERT INTO verses VALUES (28165, 45, 7, 19, 'não pois o qual quero faço bom mas o qual não quero mau isto pratico');
INSERT INTO verses VALUES (28166, 45, 7, 20, 'se porém o qual não quero eu isto faço não-mais eu produzo ele mas o habitando em mim pecado');
INSERT INTO verses VALUES (28167, 45, 7, 21, 'encontro então o lei o querendo mim fazer o belo que mim o mau está-presente');
INSERT INTO verses VALUES (28168, 45, 7, 22, 'deleito-me-juntamente pois o lei o de-Theos segundo o dentro homem');
INSERT INTO verses VALUES (28169, 45, 7, 23, 'vejo porém outro lei em o membros meu guerreando-contra o lei o mente meu e levando-cativo me em o lei o do-pecado o estando em o membros meu');
INSERT INTO verses VALUES (28170, 45, 7, 24, 'miserável eu homem quem me livrará de o do-corpo o da-morte deste');
INSERT INTO verses VALUES (28171, 45, 7, 25, 'graça o a-Theos através-de Iesous de-Christos o do-Kyrios nosso então portanto ele eu o por-um-lado mente sirvo lei de-Theos o porém carne lei do-pecado');
INSERT INTO chapters VALUES (1054, 45, 8, 39);
INSERT INTO verses VALUES (28172, 45, 8, 1, 'nada então agora condenação o em em-Christos Iesous');
INSERT INTO verses VALUES (28173, 45, 8, 2, 'o pois lei o do-espírito o da-vida em em-Christos Iesous libertou te de o da-lei o do-pecado e o da-morte');
INSERT INTO verses VALUES (28174, 45, 8, 3, 'o pois impossível o da-lei em o qual estava-doente através-de o carne o Theos o si-mesmo Filho tendo-enviado em semelhança carne do-pecado e acerca-de do-pecado condenou o pecado em o na-carne');
INSERT INTO verses VALUES (28175, 45, 8, 4, 'para que o ordenança-justa o da-lei seja-cumprido em a-nós o não segundo carne andam mas segundo espírito');
INSERT INTO verses VALUES (28176, 45, 8, 5, 'o pois segundo carne sendo o o carne pensam o porém segundo espírito o o do-espírito');
INSERT INTO verses VALUES (28177, 45, 8, 6, 'o pois pensamento o carne morte o porém pensamento o do-espírito vida e paz');
INSERT INTO verses VALUES (28178, 45, 8, 7, 'porque o pensamento o carne inimizade para Theos o pois lei o de-Theos não sujeita-se nem pois pode');
INSERT INTO verses VALUES (28179, 45, 8, 8, 'o porém em carne sendo a-Theos agradar não podem');
INSERT INTO verses VALUES (28180, 45, 8, 9, 'vós porém não sois em carne mas em espírito se-de-fato espírito de-Theos habita em a-vós se e/mas alguém espírito de-Christos não tem este não é dele');
INSERT INTO verses VALUES (28181, 45, 8, 10, 'se porém Christos em a-vós o por-um-lado corpo morto através-de pecado o porém espírito vida através-de justiça');
INSERT INTO verses VALUES (28182, 45, 8, 11, 'se porém o espírito o tendo-levantado o Iesous de mortos habita em a-vós o tendo-levantado de mortos Christos Iesous vivificará e o mortal corpos vosso através-de o habitando dele do-espírito em a-vós');
INSERT INTO verses VALUES (28183, 45, 8, 12, 'então portanto irmãos devedores somos não o carne o segundo carne viver');
INSERT INTO verses VALUES (28184, 45, 8, 13, 'se pois segundo carne vivais estais-a-ponto-de morrer se porém espírito o ações o do-corpo matais vivereis');
INSERT INTO verses VALUES (28185, 45, 8, 14, 'quanto pois Espírito de-Theos são-conduzidos estes filhos são de-Theos');
INSERT INTO verses VALUES (28186, 45, 8, 15, 'não pois recebestes espírito escravidão novamente para medo mas recebestes espírito adoção-como-filhos em o qual clamamos Abba o Pai');
INSERT INTO verses VALUES (28187, 45, 8, 16, 'ele o espírito testifica-juntamente o espírito nosso que somos filhos de-Theos');
INSERT INTO verses VALUES (28188, 45, 8, 17, 'se porém filhos e herdeiros herdeiros por-um-lado de-Theos co-herdeiros porém de-Christos se-de-fato sofremos-com para que e sejamos-co-glorificados');
INSERT INTO verses VALUES (28189, 45, 8, 18, 'Considero pois que não dignos o sofrimentos o agora tempo junto-a o vindoura glória ser-revelado para nos');
INSERT INTO verses VALUES (28190, 45, 8, 19, 'o pois ardente-expectativa o criação o revelação o dos-filhos o de-Theos aguarda-ansiosamente');
INSERT INTO verses VALUES (28191, 45, 8, 20, 'o pois vaidade o criação Foi-sujeitado não Voluntária mas através-de o Tendo-sujeitado sobre Esperança');
INSERT INTO verses VALUES (28192, 45, 8, 21, 'porque e ela o criação será-libertado de o escravidão o corrupção para o liberdade o da-glória o filhos o de-Theos');
INSERT INTO verses VALUES (28193, 45, 8, 22, 'sei pois que toda o criação geme-junto e sofre-dores-de-parto-junto até o agora');
INSERT INTO verses VALUES (28194, 45, 8, 23, 'não somente e/mas mas e eles-mesmos o primícia o do-espírito tendo nós e eles-mesmos em si-mesmos gememos adoção-como-filhos aguardando-ansiosamente o redenção o do-corpo nosso');
INSERT INTO verses VALUES (28195, 45, 8, 24, 'o pois esperança Fomos-salvos esperança porém sendo-vista não é esperança o qual pois vê alguém quê espera');
INSERT INTO verses VALUES (28196, 45, 8, 25, 'se porém o qual não vemos esperamos através-de perseverança aguardamos-ansiosamente');
INSERT INTO verses VALUES (28197, 45, 8, 26, 'Do-mesmo-modo porém e o espírito ajuda-juntamente o fraqueza nosso o pois quê oremos conforme é necessário não sei mas ele o espírito Intercede-acima gemidos inexprimíveis');
INSERT INTO verses VALUES (28198, 45, 8, 27, 'o porém Examinando o do-coração sei quê o pensamento o do-espírito que segundo Theos intercede em-favor-de dos-santos');
INSERT INTO verses VALUES (28199, 45, 8, 28, 'sei porém que o amam o Theos todas-as-coisas coopera para bom o segundo propósito chamados estando');
INSERT INTO verses VALUES (28200, 45, 8, 29, 'que o qual conheceu-de-antemão e predestinou conformes o imagem o do-Filho dele para o ser ele primogênito em muitos aos-irmãos');
INSERT INTO verses VALUES (28201, 45, 8, 30, 'o qual porém predestinou estes e chamou e o qual chamou estes e justificou o qual porém justificou estes e glorificou');
INSERT INTO verses VALUES (28202, 45, 8, 31, 'quê portanto diremos junto-a estas-coisas se o Theos em-favor-de nosso quem segundo nosso');
INSERT INTO verses VALUES (28203, 45, 8, 32, 'o qual pois o próprio do-Filho não poupou mas em-favor-de nosso todos entregou ele como não e com a ele o todas-as-coisas a-nós concederá');
INSERT INTO verses VALUES (28204, 45, 8, 33, 'quem acusará segundo eleitos de-Theos Theos o justificando');
INSERT INTO verses VALUES (28205, 45, 8, 34, 'quem o condenando Christos Iesous o tendo-morrido mais porém tendo-sido-levantado o qual é em direita o de-Theos o qual e intercede em-favor-de nosso');
INSERT INTO verses VALUES (28206, 45, 8, 35, 'quem nos separará de o do-amor o de-Christos tribulação ou angústia ou perseguição ou fome ou nudez ou perigo ou espada');
INSERT INTO verses VALUES (28207, 45, 8, 36, 'assim-como está-escrito que Por-causa-de teu somos-mortos toda o dia fomos-considerados como ovelhas matança');
INSERT INTO verses VALUES (28208, 45, 8, 37, 'mas em nestes todos Somos-mais-que-vencedores através-de o tendo-amado nos');
INSERT INTO verses VALUES (28209, 45, 8, 38, 'estou-persuadido pois que nem morte nem vida nem anjo nem principados nem presentes nem as-coisas-futuras nem poderes');
INSERT INTO verses VALUES (28210, 45, 8, 39, 'nem altivez nem profundidade nem alguém criação outra poderá nos separar de o do-amor o de-Theos o em em-Christos Iesous o ao-Kyrios nosso');
INSERT INTO chapters VALUES (1055, 45, 9, 33);
INSERT INTO verses VALUES (28211, 45, 9, 1, 'verdade digo em em-Christos não minto co-testemunhando a-mim o consciência meu em Espírito no-santo');
INSERT INTO verses VALUES (28212, 45, 9, 2, 'que tristeza me é grande e incessante dor o no-coração meu');
INSERT INTO verses VALUES (28213, 45, 9, 3, 'desejava pois anátema ser ele eu de o de-Christos em-favor-de o dos-irmãos meu o parentes meu segundo carne');
INSERT INTO verses VALUES (28214, 45, 9, 4, 'os-quais são Israelitas o qual o adoção-como-filhos e o glória e o alianças e o legislação e o serviço-sagrado e o promessas');
INSERT INTO verses VALUES (28215, 45, 9, 5, 'o qual o pais e de o qual o Christos o segundo carne o sendo sobre todos Theos bendito para o eras amém');
INSERT INTO verses VALUES (28216, 45, 9, 6, 'não qual porém que caiu-fora o palavra o de-Theos não pois todos o de Israel estes Israel');
INSERT INTO verses VALUES (28217, 45, 9, 7, 'nem que são semente Abraão todos filhos mas em Isaque será-chamado a-ti semente');
INSERT INTO verses VALUES (28218, 45, 9, 8, 'isto é não o filhos o carne estas-coisas filhos o de-Theos mas o filhos o promessa é-contado para semente');
INSERT INTO verses VALUES (28219, 45, 9, 9, 'promessa pois o palavra este segundo o tempo este virei e será o Sara filho');
INSERT INTO verses VALUES (28220, 45, 9, 10, 'não somente e/mas mas e Rebeca de de-um leito tendo Isaque o do-Pai nosso');
INSERT INTO verses VALUES (28221, 45, 9, 11, 'ainda-não pois tendo-sido-gerados nem tendo-praticado algo bom ou vil para que o segundo eleição propósito o de-Theos permaneça');
INSERT INTO verses VALUES (28222, 45, 9, 12, 'não de obra mas de o chamante foi-dito a-ela que o maior servirá o menor');
INSERT INTO verses VALUES (28223, 45, 9, 13, 'assim-como está-escrito o Jacó amei o porém Esaú odiei');
INSERT INTO verses VALUES (28224, 45, 9, 14, 'quê portanto diremos não injustiça de-junto-de o a-Theos não seja-assim');
INSERT INTO verses VALUES (28225, 45, 9, 15, 'o Moisés pois diz Terei-misericórdia o qual partícula-condicional tenho-misericórdia e terei-compaixão o qual partícula-condicional tenho-compaixão');
INSERT INTO verses VALUES (28226, 45, 9, 16, 'então portanto não o querendo nem o correndo mas o tendo-misericórdia de-Theos');
INSERT INTO verses VALUES (28227, 45, 9, 17, 'diz pois o escritura o Faraó que para ele isto levantei te para-que eu-mostre em a-ti o poder meu e para-que seja-anunciado o nome meu em toda o terra');
INSERT INTO verses VALUES (28228, 45, 9, 18, 'então portanto o qual quer tem-misericórdia o qual porém quer endurece');
INSERT INTO verses VALUES (28229, 45, 9, 19, 'Dirás a-mim portanto quê ainda censura o pois vontade dele quem tem-resistido');
INSERT INTO verses VALUES (28230, 45, 9, 20, 'Ômega homem antes-pelo-contrário tu quem és o respondendo-de-volta o a-Theos não dirá o criatura-formada o ao-que-formou quê me fizeste assim');
INSERT INTO verses VALUES (28231, 45, 9, 21, 'ou não tem autoridade o oleiro o barro de o dele de-massa fazer o qual por-um-lado para honra vaso o qual porém para desonra');
INSERT INTO verses VALUES (28232, 45, 9, 22, 'se porém querendo o Theos mostrar o ira e fazer-conhecer o possível dele trouxe em muita paciência vasos ira tendo-sido-restaurados para perdição');
INSERT INTO verses VALUES (28233, 45, 9, 23, 'e para que faça-conhecer o riqueza o da-glória dele sobre vasos misericórdia o qual preparou-de-antemão para glória');
INSERT INTO verses VALUES (28234, 45, 9, 24, 'o qual e chamou nos não somente de judeus mas e de nações');
INSERT INTO verses VALUES (28235, 45, 9, 25, 'como e em o Oseias diz Chamarei o não povo meu povo meu e o não amada amada');
INSERT INTO verses VALUES (28236, 45, 9, 26, 'e será em o no-lugar do-qual foi-dito a-eles não povo meu vós ali serão-chamados filhos de-Theos vivente');
INSERT INTO verses VALUES (28237, 45, 9, 27, 'Isaías porém clama em-favor-de o Israel se seja o número o dos-filhos Israel como o areia o do-mar o Remanescente será-salvo');
INSERT INTO verses VALUES (28238, 45, 9, 28, 'palavra pois completando e abreviando fará Kyrios sobre o da-terra');
INSERT INTO verses VALUES (28239, 45, 9, 29, 'e assim-como tem-dito-de-antemão Isaías se não Kyrios Sabaoth abandonou a-nós semente como Sodoma partícula-condicional tornamo-nos e como Gomorra partícula-condicional Fomos-comparados');
INSERT INTO verses VALUES (28240, 45, 9, 30, 'quê portanto diremos que nações o não perseguindo justiça alcançou justiça justiça porém o de da-fé');
INSERT INTO verses VALUES (28241, 45, 9, 31, 'Israel porém perseguindo lei da-justiça para lei não chegou');
INSERT INTO verses VALUES (28242, 45, 9, 32, 'através-de quê que não de da-fé mas como de obra tropeçaram o pedra o tropeço');
INSERT INTO verses VALUES (28243, 45, 9, 33, 'assim-como está-escrito Eis ponho em Sião pedra tropeço e rocha tropeço e o crendo sobre a ele não será-envergonhado');
INSERT INTO chapters VALUES (1056, 45, 10, 21);
INSERT INTO verses VALUES (28244, 45, 10, 1, 'Irmãos o por-um-lado boa-vontade o minha do-coração e o súplica junto-a o Theos em-favor-de deles para salvação');
INSERT INTO verses VALUES (28245, 45, 10, 2, 'testemunho pois a-eles que zelo de-Theos têm mas não segundo conhecimento-pleno');
INSERT INTO verses VALUES (28246, 45, 10, 3, 'ignorando pois o o de-Theos justiça e o própria buscando estabelecer o justiça o de-Theos não Foram-sujeitados');
INSERT INTO verses VALUES (28247, 45, 10, 4, 'fim pois da-lei Christos para justiça todo o crente');
INSERT INTO verses VALUES (28248, 45, 10, 5, 'Moisés pois escreve que o justiça o de da-lei o tendo-feito homem viverá em a-ela');
INSERT INTO verses VALUES (28249, 45, 10, 6, 'o porém de da-fé justiça assim diz não digas em o no-coração teu Quem subirá para o céu isto é Christos fazer-descer');
INSERT INTO verses VALUES (28250, 45, 10, 7, 'ou Quem descerá para o abismo isto é Christos de mortos conduzir-para-cima');
INSERT INTO verses VALUES (28251, 45, 10, 8, 'mas quê diz perto teu o palavra é em o boca teu e em o no-coração teu isto é o palavra o da-fé o qual pregamos');
INSERT INTO verses VALUES (28252, 45, 10, 9, 'que se confesses em o boca teu Kyrion Iesous e creias em o no-coração teu que o Theos ele ressuscitou de mortos serás-salvo');
INSERT INTO verses VALUES (28253, 45, 10, 10, 'no-coração pois é-crido para justiça boca porém é-confessado para salvação');
INSERT INTO verses VALUES (28254, 45, 10, 11, 'diz pois o escritura todo o crendo sobre a ele não será-envergonhado');
INSERT INTO verses VALUES (28255, 45, 10, 12, 'não pois é distinção Judeu e e grego o pois ele Kyrios todos enriquecendo para todos o invocando ele');
INSERT INTO verses VALUES (28256, 45, 10, 13, 'todo pois o qual partícula-condicional invoque o nome do-Kyrios será-salvo');
INSERT INTO verses VALUES (28257, 45, 10, 14, 'como portanto invoquem para o qual não creram como porém creiam o qual não ouviram como porém ouçam sem proclamando');
INSERT INTO verses VALUES (28258, 45, 10, 15, 'como porém proclamem se não sejam-enviados assim-como está-escrito como formosos o pés o anunciando-boas-novas boas-coisas');
INSERT INTO verses VALUES (28259, 45, 10, 16, 'mas não todos Obedeceram o no-evangelho Isaías pois diz Kyrie quem creu o ouvido nosso');
INSERT INTO verses VALUES (28260, 45, 10, 17, 'então o fé de ouvido o porém ouvido através-de palavra de-Christos');
INSERT INTO verses VALUES (28261, 45, 10, 18, 'mas digo não não ouviram antes-pelo-contrário para toda o terra saiu o som deles e para o confins o mundo-habitado o palavras deles');
INSERT INTO verses VALUES (28262, 45, 10, 19, 'mas digo não Israel não conheceu primeiro Moisés diz eu provocarei-a-ciúmes vos sobre não nação sobre nação sem-entendimento provocarei-à-ira vos');
INSERT INTO verses VALUES (28263, 45, 10, 20, 'Isaías porém ousa e diz Fui-encontrado o mim não buscam manifesto tornei-me o mim não perguntem');
INSERT INTO verses VALUES (28264, 45, 10, 21, 'junto-a porém o Israel diz Toda o dia estendi o mãos meu junto-a povo desobedecendo e contradizendo');
INSERT INTO chapters VALUES (1057, 45, 11, 36);
INSERT INTO verses VALUES (28265, 45, 11, 1, 'digo portanto não rejeitou o Theos o povo dele não seja-assim e pois eu Israelita sou de semente Abraão tribo Benjamim');
INSERT INTO verses VALUES (28266, 45, 11, 2, 'não rejeitou o Theos o povo dele o qual conheceu-de-antemão ou não sei em Elias quê diz o escritura como intercede o a-Theos segundo o Israel');
INSERT INTO verses VALUES (28267, 45, 11, 3, 'Kyrie o profetas teu mataram o altares teu derrubaram e-eu Fui-deixado só e buscam o alma meu');
INSERT INTO verses VALUES (28268, 45, 11, 4, 'mas quê diz a ele o advertência-divina Deixei a-mim-mesmo Sete-mil homens os-quais não dobraram joelho o Baal');
INSERT INTO verses VALUES (28269, 45, 11, 5, 'assim portanto e em o agora tempo resto segundo eleição da-graça aconteceu');
INSERT INTO verses VALUES (28270, 45, 11, 6, 'se porém graça não-mais de obra porque o graça não-mais torna-se graça');
INSERT INTO verses VALUES (28271, 45, 11, 7, 'quê portanto o qual busca Israel isto não alcançou o porém eleição alcançou o porém restantes Foram-endurecidos');
INSERT INTO verses VALUES (28272, 45, 11, 8, 'assim-como está-escrito deu a-eles o Theos espírito torpor olhos o não ver e ouvidos o não ouvir até o hoje do-dia');
INSERT INTO verses VALUES (28273, 45, 11, 9, 'e Davi diz Seja-feito o mesa deles para laço e para caça e para tropeço e para retribuição a-eles');
INSERT INTO verses VALUES (28274, 45, 11, 10, 'sejam-obscurecidos o olhos deles o não ver e o costas deles através-de de-todo curva-junto');
INSERT INTO verses VALUES (28275, 45, 11, 11, 'digo portanto não Tropeçaram para que caiam não seja-assim mas o deles transgressão o salvação o nações para o provocar-a-ciúme eles');
INSERT INTO verses VALUES (28276, 45, 11, 12, 'se porém o transgressão deles riqueza do-mundo e o derrota deles riqueza nações quanto mais o plenitude deles');
INSERT INTO verses VALUES (28277, 45, 11, 13, 'a-vós porém digo o nações sobre quanto por-um-lado portanto sou eu nações apóstolo o serviço meu glorifico');
INSERT INTO verses VALUES (28278, 45, 11, 14, 'se como provocarei-a-ciúmes meu o carne e salvarei alguns de deles');
INSERT INTO verses VALUES (28279, 45, 11, 15, 'se pois o rejeição deles reconciliação do-mundo quem o recepção se não vida de mortos');
INSERT INTO verses VALUES (28280, 45, 11, 16, 'se porém o primícias santa e o massa e se o raiz santa e o ramos');
INSERT INTO verses VALUES (28281, 45, 11, 17, 'se e/mas alguns o ramos foram-cortados tu porém oliveira-brava sendo foste-enxertado em a-eles e co-participante o raiz o gordura o oliveira tornaste-te');
INSERT INTO verses VALUES (28282, 45, 11, 18, 'não glorio-me-contra o ramos se porém glorias-te-contra não tu o raiz carregas mas o raiz te');
INSERT INTO verses VALUES (28283, 45, 11, 19, 'dirás portanto Foram-quebrados ramos para que eu seja-enxertado');
INSERT INTO verses VALUES (28284, 45, 11, 20, 'bem o incredulidade foram-cortados tu porém o fé tens-ficado-de-pé não altas pensa mas temas');
INSERT INTO verses VALUES (28285, 45, 11, 21, 'se pois o Theos o segundo natureza ramos não poupou nem teu poupará');
INSERT INTO verses VALUES (28286, 45, 11, 22, 'vê portanto benignidade e severidade de-Theos sobre por-um-lado o tendo-caído severidade sobre porém te benignidade de-Theos se permaneças o benignidade porque e tu sejas-cortado-fora');
INSERT INTO verses VALUES (28287, 45, 11, 23, 'e-aqueles e/mas se não permaneçam o incredulidade serão-enxertados poderoso pois é o Theos novamente enxertar eles');
INSERT INTO verses VALUES (28288, 45, 11, 24, 'se pois tu de o segundo natureza foste-cortado oliveira-brava e de-junto-de natureza foste-enxertado para oliveira-cultivada quanto mais estes o segundo natureza serão-enxertados o em-particular oliveira');
INSERT INTO verses VALUES (28289, 45, 11, 25, 'não pois quero vos ignorar irmãos o mistério isto para que não éreis em si-mesmos prudentes que endurecimento de da-parte o Israel aconteceu até o qual o plenitude o nações entre');
INSERT INTO verses VALUES (28290, 45, 11, 26, 'e assim todo Israel será-salvo assim-como está-escrito Virá de Sião o Livrando desviará impiedade de Jacó');
INSERT INTO verses VALUES (28291, 45, 11, 27, 'e esta a-eles o de-junto-de mim aliança quando tire o do-pecado deles');
INSERT INTO verses VALUES (28292, 45, 11, 28, 'segundo por-um-lado o evangelho inimigos através-de vos segundo porém o eleição amados através-de o pais');
INSERT INTO verses VALUES (28293, 45, 11, 29, 'irrevogáveis pois o dons e o chamado o de-Theos');
INSERT INTO verses VALUES (28294, 45, 11, 30, 'assim-como pois vós alguma-vez desobedecestes o a-Theos agora porém fostes-alvos-de-misericórdia o destes desobediência');
INSERT INTO verses VALUES (28295, 45, 11, 31, 'assim e estes agora desobedeceram o vosso tem-misericórdia para que e eles-mesmos agora recebam-misericórdia');
INSERT INTO verses VALUES (28296, 45, 11, 32, 'encerrou-junto pois o Theos o todos para desobediência para que o todos tenha-misericórdia');
INSERT INTO verses VALUES (28297, 45, 11, 33, 'Ômega profundidade riqueza e da-sabedoria e do-conhecimento de-Theos como inescrutáveis o julgamentos dele e inescrutáveis o caminhos dele');
INSERT INTO verses VALUES (28298, 45, 11, 34, 'Quem pois conheceu entendimento do-Kyrios ou quem conselheiro dele aconteceu');
INSERT INTO verses VALUES (28299, 45, 11, 35, 'ou quem deu-de-antemão a ele e será-retribuído a ele');
INSERT INTO verses VALUES (28300, 45, 11, 36, 'que de dele e através-de dele e para ele o todas-as-coisas a ele o glória para o eras amém');
INSERT INTO chapters VALUES (1058, 45, 12, 21);
INSERT INTO verses VALUES (28301, 45, 12, 1, 'Exorto portanto vos irmãos através-de o compaixões o de-Theos apresentar o corpos vosso sacrifício vivente santa o a-Theos agradável o racional serviço-sagrado vosso');
INSERT INTO verses VALUES (28302, 45, 12, 2, 'e não conformai-vos o era neste mas sede-transformados o renovação o mente para o provar vos quê o vontade o de-Theos o bom e agradável e perfeito');
INSERT INTO verses VALUES (28303, 45, 12, 3, 'digo pois através-de o da-graça o tendo-sido-dada a-mim todo o estando em a-vós não Ter-altivez de-junto-de o qual é necessário pensar mas pensar para o ser-sóbrio-de-mente a-cada-um como o Theos dividiu medida da-fé');
INSERT INTO verses VALUES (28304, 45, 12, 4, 'assim-como pois em um corpo muitas-coisas membros temos o porém membros todas-as-coisas não o ela tem ação');
INSERT INTO verses VALUES (28305, 45, 12, 5, 'assim o muitos um corpo somos em em-Christos o porém segundo um uns-aos-outros membros');
INSERT INTO verses VALUES (28306, 45, 12, 6, 'tendo porém dons segundo o graça o tendo-sido-dada a-nós diferentes seja profecia segundo o proporção o da-fé');
INSERT INTO verses VALUES (28307, 45, 12, 7, 'seja serviço em o ministério seja o ensinando em o ensino');
INSERT INTO verses VALUES (28308, 45, 12, 8, 'seja o exortando em o consolação o repartindo em simplicidade o presidindo em diligência o tendo-misericórdia em Alegria');
INSERT INTO verses VALUES (28309, 45, 12, 9, 'o amor sem-hipocrisia abominando o mau unindo-se o bom');
INSERT INTO verses VALUES (28310, 45, 12, 10, 'o amor-fraternal para uns-aos-outros afetuosos o honra uns-aos-outros considerando-superiores');
INSERT INTO verses VALUES (28311, 45, 12, 11, 'o diligência não preguiçosos o espírito fervendo o ao-Kyrios servindo');
INSERT INTO verses VALUES (28312, 45, 12, 12, 'o esperança alegrando-se o tribulação Perseverando o oração perseverando');
INSERT INTO verses VALUES (28313, 45, 12, 13, 'o necessidades o dos-santos participando o hospitalidade perseguindo');
INSERT INTO verses VALUES (28314, 45, 12, 14, 'bendizei o perseguindo bendizei e não amaldiçoais');
INSERT INTO verses VALUES (28315, 45, 12, 15, 'alegrar-se com dos-que-se-alegram chorar com chorando');
INSERT INTO verses VALUES (28316, 45, 12, 16, 'o ele para uns-aos-outros pensando não o altas pensando mas o humildes sendo-levados-junto não tornai-vos prudentes de-junto-de si-mesmos');
INSERT INTO verses VALUES (28317, 45, 12, 17, 'a-ninguém mau em-troca-de mal retribuindo cuidando boas diante-de todos dos-homens');
INSERT INTO verses VALUES (28318, 45, 12, 18, 'se possível o de vosso com todos dos-homens vivendo-em-paz');
INSERT INTO verses VALUES (28319, 45, 12, 19, 'não si-mesmos vingando amados mas dai lugar o ira está-escrito pois A-mim vingança eu retribuirei diz Kyrios');
INSERT INTO verses VALUES (28320, 45, 12, 20, 'mas se tem-fome o Inimigo teu alimenta ele se tem-sede dá-de-beber ele isto pois fazendo carvões fogo amontoarás sobre o cabeça dele');
INSERT INTO verses VALUES (28321, 45, 12, 21, 'não venço sob o mal mas vence em o bom o mal');
INSERT INTO chapters VALUES (1059, 45, 13, 14);
INSERT INTO verses VALUES (28322, 45, 13, 1, 'toda alma autoridades Superiores Sujeite-se não pois é autoridade se não sob de-Theos o porém sendo sob de-Theos tendo-sido-designadas são');
INSERT INTO verses VALUES (28323, 45, 13, 2, 'de-modo-que o opondo-se o em-autoridade o o de-Theos ordenança tem-resistido o porém tendo-resistido si-mesmos julgamento receberão');
INSERT INTO verses VALUES (28324, 45, 13, 3, 'o pois governantes não são medo o bom obra mas o mau queres porém não temer o autoridade o bom faze e terás louvor de dela');
INSERT INTO verses VALUES (28325, 45, 13, 4, 'de-Theos pois servo é a-ti para o bom se porém o mau fazes temas não pois em-vão o espada carrega de-Theos pois servo é vingador para ira o o mau praticando');
INSERT INTO verses VALUES (28326, 45, 13, 5, 'por-isso necessidade sujeitar-se não somente através-de o ira mas e através-de o consciência');
INSERT INTO verses VALUES (28327, 45, 13, 6, 'através-de isto pois e tributos completais ministros pois de-Theos são para ele isto perseverando');
INSERT INTO verses VALUES (28328, 45, 13, 7, 'devolvei todos o dívidas o o tributo o tributo o o fim o fim o o medo o medo o o honra o honra');
INSERT INTO verses VALUES (28329, 45, 13, 8, 'A-ninguém nada deveis se não o uns-aos-outros amar o pois amando o outro lei tem-cumprido');
INSERT INTO verses VALUES (28330, 45, 13, 9, 'o pois não adulterarás não assassinarás não furtarás não desejarás e se alguém outra mandamento em o em-palavra neste é-recapitulado em o Amarás o próximo teu como a-ti-mesmo');
INSERT INTO verses VALUES (28331, 45, 13, 10, 'o amor o próximo mau não trabalha plenitude portanto da-lei o amor');
INSERT INTO verses VALUES (28332, 45, 13, 11, 'e isto sei o tempo-oportuno que hora já vos de sono ser-levantado agora pois mais-perto nosso o salvação ou quando acreditamos');
INSERT INTO verses VALUES (28333, 45, 13, 12, 'o noite progrediu o porém dia aproximou-se despojemo-nos portanto o obra o das-trevas vistamo-nos porém o armas o luz');
INSERT INTO verses VALUES (28334, 45, 13, 13, 'como em dia decorosamente andemos não orgias e bebedeiras não leitos e dissoluções não Contenda e zelo');
INSERT INTO verses VALUES (28335, 45, 13, 14, 'mas vesti-vos o Kyrion Iesous Christon e o carne providência não fazei para desejos');
INSERT INTO chapters VALUES (1060, 45, 14, 23);
INSERT INTO verses VALUES (28336, 45, 14, 1, 'o porém estando-fraco o fé acolhei não para discernimentos raciocínios');
INSERT INTO verses VALUES (28337, 45, 14, 2, 'o qual por-um-lado crê comer todas-as-coisas o porém fracos hortaliças come');
INSERT INTO verses VALUES (28338, 45, 14, 3, 'o comendo o não comendo não que-não-menospreze o porém não comendo o comendo não julgue o Theos pois ele tomou-consigo');
INSERT INTO verses VALUES (28339, 45, 14, 4, 'tu quem és o julgando alheio servo-doméstico o próprio ao-Kyrios está-firme ou cai será-estabelecido e/mas é-poderoso pois o Kyrios estabelecer ele');
INSERT INTO verses VALUES (28340, 45, 14, 5, 'o qual por-um-lado pois julga dia de-junto-de dia o qual porém julga toda dia cada-um em o próprio mente esteja-plenamente-convicto');
INSERT INTO verses VALUES (28341, 45, 14, 6, 'o pensando o dia ao-Kyrios pensa e o comendo ao-Kyrios come dá-graças pois o a-Theos e o não comendo ao-Kyrios não come e dá-graças o a-Theos');
INSERT INTO verses VALUES (28342, 45, 14, 7, 'ninguém pois nosso si-mesmo vive e ninguém si-mesmo morre');
INSERT INTO verses VALUES (28343, 45, 14, 8, 'se e pois vivamos o ao-Kyrios vivamos se e morramos o ao-Kyrios morremos se e portanto vivamos se e morramos o do-Kyrios somos');
INSERT INTO verses VALUES (28344, 45, 14, 9, 'para isto pois Christos morreu e viveu para que e mortos e viventes domine');
INSERT INTO verses VALUES (28345, 45, 14, 10, 'tu porém quê julgas o irmão teu ou e tu quê desprezas o irmão teu todos pois seremos-apresentados o tribunal o de-Theos');
INSERT INTO verses VALUES (28346, 45, 14, 11, 'está-escrito pois Vivo eu diz Kyrios que mim dobrará todo joelho e toda língua confessará o a-Theos');
INSERT INTO verses VALUES (28347, 45, 14, 12, 'então portanto cada-um nosso acerca-de si-mesmo palavra dará o a-Theos');
INSERT INTO verses VALUES (28348, 45, 14, 13, 'Não-mais portanto uns-aos-outros julguemos mas isto julgai mais o não pôr tropeço o ao-irmão ou tropeço');
INSERT INTO verses VALUES (28349, 45, 14, 14, 'sei e estou-persuadido em ao-Kyrios Iesous que nada comum através-de si-mesmo se não o ao-que-considera algo comum ser naquele comum');
INSERT INTO verses VALUES (28350, 45, 14, 15, 'se pois através-de alimento o irmão teu entristece-se não-mais segundo amor andas não o alimento teu aquele destrói em-favor-de o qual Christos morreu');
INSERT INTO verses VALUES (28351, 45, 14, 16, 'não seja-blasfemado portanto vosso o bom');
INSERT INTO verses VALUES (28352, 45, 14, 17, 'não pois é o reino o de-Theos comida e bebida mas justiça e paz e alegria em Espírito no-santo');
INSERT INTO verses VALUES (28353, 45, 14, 18, 'o pois em neste servindo o em-Christos agradável o a-Theos e aprovado o aos-homens');
INSERT INTO verses VALUES (28354, 45, 14, 19, 'então portanto o o paz perseguimos e o o edificação o para uns-aos-outros');
INSERT INTO verses VALUES (28355, 45, 14, 20, 'não por-causa-de alimento destrói o obra o de-Theos todas-as-coisas por-um-lado pura mas mau o ao-homem o através-de tropeço Comendo');
INSERT INTO verses VALUES (28356, 45, 14, 21, 'belo o não comer carnes nem beber vinho nem em o qual o irmão teu tropeça');
INSERT INTO verses VALUES (28357, 45, 14, 22, 'tu fé o qual tens segundo a-ti-mesmo tem diante-de o de-Theos bem-aventurado o não julgando si-mesmo em o qual examina');
INSERT INTO verses VALUES (28358, 45, 14, 23, 'o porém duvidando se coma tem-sido-condenado que não de da-fé todo porém o qual não de da-fé pecado é');
INSERT INTO chapters VALUES (1061, 45, 15, 33);
INSERT INTO verses VALUES (28359, 45, 15, 1, 'Devemos porém nós o poderosos o fraquezas o impossíveis carregar e não si-mesmos agradar');
INSERT INTO verses VALUES (28360, 45, 15, 2, 'cada-um nosso o próximo agrade para o bom junto-a edificação');
INSERT INTO verses VALUES (28361, 45, 15, 3, 'e pois o Christos não si-mesmo agradou mas assim-como está-escrito o injúrias o injuriando te caíram-sobre sobre a-mim');
INSERT INTO verses VALUES (28362, 45, 15, 4, 'quanto pois foi-escrito-antes para o Nossa ensino foi-escrito para que através-de o perseverança e através-de o da-consolação o escrituras o esperança tenhamos');
INSERT INTO verses VALUES (28363, 45, 15, 5, 'o porém Theos o perseverança e o da-consolação dê a-vós o ele pensar em uns-aos-outros segundo Christos Iesous');
INSERT INTO verses VALUES (28364, 45, 15, 6, 'para que unanimemente em um boca glorifiqueis o Theos e Pai o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (28365, 45, 15, 7, 'por-isso acolhei uns-aos-outros assim-como e o Christos tomou-consigo nos para glória o de-Theos');
INSERT INTO verses VALUES (28366, 45, 15, 8, 'digo pois Christos servo ter-sido-feito da-circuncisão em-favor-de da-verdade de-Theos para o confirmar o promessa o dos-pais');
INSERT INTO verses VALUES (28367, 45, 15, 9, 'o porém nações em-favor-de misericórdia glorificar o Theos assim-como está-escrito através-de isto confessarei a-ti em nações e o no-nome teu salmodiarei');
INSERT INTO verses VALUES (28368, 45, 15, 10, 'e novamente diz Alegrai-vos nações com o povo dele');
INSERT INTO verses VALUES (28369, 45, 15, 11, 'e novamente Louvai todas-as-coisas o nações o Kyrion e Louvem ele todos o povos');
INSERT INTO verses VALUES (28370, 45, 15, 12, 'e novamente Isaías diz será o raiz o Jessé e o levantando-se governar nações sobre a ele nações esperam');
INSERT INTO verses VALUES (28371, 45, 15, 13, 'o porém Theos o da-esperança cumprir vos toda alegria e paz em o crer para o abundar vos em o esperança em poder do-espírito do-santo');
INSERT INTO verses VALUES (28372, 45, 15, 14, 'Tenho-sido-persuadido e/mas irmãos meu e ele eu acerca-de vosso que e eles-mesmos cheios sois bondade tendo-sido-preenchidos toda o do-conhecimento podendo e uns-aos-outros admoestar');
INSERT INTO verses VALUES (28373, 45, 15, 15, 'mais-ousadamente porém escrevi a-vós de da-parte como relembrando vos através-de o graça o dada a-mim de o de-Theos');
INSERT INTO verses VALUES (28374, 45, 15, 16, 'para o ser me ministro de-Christos Iesous para o nações Ministrando-sacerdotalmente o evangelho o de-Theos para que aconteça o oferta o nações aceitável Tendo-sido-santificada em Espírito no-santo');
INSERT INTO verses VALUES (28375, 45, 15, 17, 'tenho portanto o glorificação em em-Christos Iesous o junto-a o Theos');
INSERT INTO verses VALUES (28376, 45, 15, 18, 'não pois ousarei algo falar o qual não produziu Christos através-de mim para obediência nações em-palavra e obra');
INSERT INTO verses VALUES (28377, 45, 15, 19, 'em poder sinais e de-prodígios em poder do-espírito do-santo de-modo-que me de Jerusalém e ao-redor até o Ilírico ter-cumprido o evangelho o de-Christos');
INSERT INTO verses VALUES (28378, 45, 15, 20, 'assim porém ambicionando anunciar-boa-nova não onde Foi-nomeado Christos para que não sobre alheio fundamento edifico');
INSERT INTO verses VALUES (28379, 45, 15, 21, 'mas assim-como está-escrito Verão o qual não foi-anunciado acerca-de dele e o qual não têm-ouvido compreenderão');
INSERT INTO verses VALUES (28380, 45, 15, 22, 'por-isso e era-impedido o muitas-coisas o vir junto-a vos');
INSERT INTO verses VALUES (28381, 45, 15, 23, 'agora porém não-mais lugar tendo em o regiões nestes desejo-ardente porém tendo o vir junto-a vos de suficientes anos');
INSERT INTO verses VALUES (28382, 45, 15, 24, 'como partícula-condicional vá para o Espanha espero pois passando-através contemplar vos e sob vosso ser-enviado-adiante ali se vosso primeiro de da-parte eu-seja-saciado');
INSERT INTO verses VALUES (28383, 45, 15, 25, 'agora porém vou para Jerusalém servindo o santos');
INSERT INTO verses VALUES (28384, 45, 15, 26, 'tiveram-prazer pois Macedônia e Acaia comunhão algum fazer para o pobres o dos-santos o em Jerusalém');
INSERT INTO verses VALUES (28385, 45, 15, 27, 'tiveram-prazer pois e devedores são deles se pois o espirituais deles participaram o nações devem e em o carnais ministrar a-eles');
INSERT INTO verses VALUES (28386, 45, 15, 28, 'isto portanto Tendo-completado e tendo-selado a-eles o fruto este irei através-de vosso para Espanha');
INSERT INTO verses VALUES (28387, 45, 15, 29, 'sei porém que o-que-vem junto-a vos em plenitude bênção de-Christos virei');
INSERT INTO verses VALUES (28388, 45, 15, 30, 'Exorto porém vos irmãos através-de o do-Kyrios nosso Iesous de-Christos e através-de o do-amor o do-espírito lutar-juntamente a-mim em o orações em-favor-de mim junto-a o Theos');
INSERT INTO verses VALUES (28389, 45, 15, 31, 'para que seja-livrado de o desobedecendo em o Judeia e o ministério meu o para Jerusalém aceitável o santos aconteça');
INSERT INTO verses VALUES (28390, 45, 15, 32, 'para que em alegria vindo junto-a vos através-de da-vontade de-Theos descanse-juntamente a-vós');
INSERT INTO verses VALUES (28391, 45, 15, 33, 'o porém Theos o paz com todos vosso amém');
INSERT INTO chapters VALUES (1062, 45, 16, 26);
INSERT INTO verses VALUES (28392, 45, 16, 1, 'Recomendo porém a-vós Febe o irmã nosso sendo servo o da-assembleia o em Cencreia');
INSERT INTO verses VALUES (28393, 45, 16, 2, 'para que ela recebais em ao-Kyrios dignamente o dos-santos e apresentai a-ela em o qual partícula-condicional vosso tenha-necessidade assunto e pois ela protetora muitos aconteceu e mim dele');
INSERT INTO verses VALUES (28394, 45, 16, 3, 'Saudai Prisca e Áquila o cooperadores meu em em-Christos Iesous');
INSERT INTO verses VALUES (28395, 45, 16, 4, 'os-quais em-favor-de o alma meu o deles-mesmos pescoço Puseram-sob o qual não eu só dou-graças mas e todas o assembleias o nações');
INSERT INTO verses VALUES (28396, 45, 16, 5, 'e o segundo casa deles igreja saudai Epeneto o amado meu o qual é primícias o Ásia para Christos');
INSERT INTO verses VALUES (28397, 45, 16, 6, 'saudai Maria a-qual muitas-coisas trabalhou para vos');
INSERT INTO verses VALUES (28398, 45, 16, 7, 'saudai Andrônico e Júnias o parentes meu e co-prisioneiros meu os-quais são notáveis em o apóstolos o qual e antes-de mim tornaram-se em em-Christos');
INSERT INTO verses VALUES (28399, 45, 16, 8, 'saudai Ampliato o amado meu em ao-Kyrios');
INSERT INTO verses VALUES (28400, 45, 16, 9, 'saudai Urbano o cooperador nosso em em-Christos e Estáquis o amado meu');
INSERT INTO verses VALUES (28401, 45, 16, 10, 'saudai Apeles o aprovado em em-Christos saudai o de o Aristóbulo');
INSERT INTO verses VALUES (28402, 45, 16, 11, 'saudai Herodião o parente meu saudai o de o Narciso o sendo em ao-Kyrios');
INSERT INTO verses VALUES (28403, 45, 16, 12, 'saudai Trifena e Trifosa o tendo-trabalhado em ao-Kyrios saudai Pérsida o amada a-qual muitas-coisas trabalhou em ao-Kyrios');
INSERT INTO verses VALUES (28404, 45, 16, 13, 'saudai Rufo o escolhido em ao-Kyrios e o mãe dele e mim');
INSERT INTO verses VALUES (28405, 45, 16, 14, 'saudai Assíncrito Flegonte Hermes Pátrobas Hermes e o com a-eles irmãos');
INSERT INTO verses VALUES (28406, 45, 16, 15, 'saudai Filólogo e Júlia Nereu e o irmã dele e Olimpas e o com a-eles todos santos');
INSERT INTO verses VALUES (28407, 45, 16, 16, 'saudai uns-aos-outros em beijo no-santo saúdam vos o assembleias todas o de-Christos');
INSERT INTO verses VALUES (28408, 45, 16, 17, 'Exorto porém vos irmãos observar o o divisões e o escândalos de-junto-de o ensino o qual vós aprendestes fazendo e desviai-vos de deles');
INSERT INTO verses VALUES (28409, 45, 16, 18, 'o pois tais o ao-Kyrios nosso em-Christos não servem mas o deles-mesmos ventre e através-de o de-belas-palavras e bênção enganam o do-coração o inocentes');
INSERT INTO verses VALUES (28410, 45, 16, 19, 'o pois vosso Obediência para todos chegou sobre a-vós portanto alegro-me quero porém vos sábios ser para o bom puros porém para o mal');
INSERT INTO verses VALUES (28411, 45, 16, 20, 'o porém Theos o paz quebrará o Satanás sob o pés vosso em rapidez o graça o do-Kyrios nosso Iesous com vosso');
INSERT INTO verses VALUES (28412, 45, 16, 21, 'Saúda vos Timóteo o cooperador meu e Lúcio e Jasão e Sosípatro o parentes meu');
INSERT INTO verses VALUES (28413, 45, 16, 22, 'saúdo vos eu Tércio o tendo-escrito o carta em ao-Kyrios');
INSERT INTO verses VALUES (28414, 45, 16, 23, 'saúda vos Gaio o estrangeiro meu e de-toda o da-assembleia saúda vos Erasto o administrador o cidade e Quarto o irmão');
INSERT INTO verses VALUES (28415, 45, 16, 25, 'o porém podendo vos firmar segundo o boa-nova meu e o pregação Iesous de-Christos segundo revelação mistério tempos eternos tendo-sido-silenciado');
INSERT INTO verses VALUES (28416, 45, 16, 26, 'tendo-sido-manifestado porém agora por-meio-de e escrituras proféticos segundo mandado o eterno de-Theos para obediência da-fé para todas-as-coisas o nações tendo-sido-feito-conhecer');
INSERT INTO verses VALUES (28417, 45, 16, 27, 'somente sábio a-Theos através-de Iesous de-Christos o qual o glória para o eras o eras amém');
INSERT INTO books VALUES (46, '1CO', '1 Coríntios', 'NT', 16);
INSERT INTO chapters VALUES (1063, 46, 1, 31);
INSERT INTO verses VALUES (28418, 46, 1, 1, 'Paulo chamado apóstolo de-Christos Iesous através-de da-vontade de-Theos e Sóstenes o irmão');
INSERT INTO verses VALUES (28419, 46, 1, 2, 'o assembleia o de-Theos o estando em Corinto tendo-sido-santificados em em-Christos Iesous chamados santos com todos o invocando o nome o do-Kyrios nosso Iesous de-Christos em todo no-lugar deles e nosso');
INSERT INTO verses VALUES (28420, 46, 1, 3, 'graça a-vós e paz de de-Theos do-Pai nosso e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (28421, 46, 1, 4, 'Dou-graças o a-Theos sempre acerca-de vosso sobre o graça o de-Theos o tendo-sido-dada a-vós em em-Christos Iesous');
INSERT INTO verses VALUES (28422, 46, 1, 5, 'que em todo Fostes-enriquecidos em a ele em todo em-palavra e toda conhecimento');
INSERT INTO verses VALUES (28423, 46, 1, 6, 'assim-como o testemunho o de-Christos foi-confirmado em a-vós');
INSERT INTO verses VALUES (28424, 46, 1, 7, 'de-modo-que vos não ter-falta em a-ninguém com-dom-de-graça aos-que-aguardam-ansiosamente o revelação o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (28425, 46, 1, 8, 'o qual e confirmação vos até fim irrepreensíveis em o dia o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (28426, 46, 1, 9, 'fiel o Theos através-de o qual fostes-chamados para comunhão o do-Filho dele Iesous de-Christos o do-Kyrios nosso');
INSERT INTO verses VALUES (28427, 46, 1, 10, 'Exorto porém vos irmãos através-de o do-nome o do-Kyrios nosso Iesous de-Christos para que o ele digais todos e não seja em a-vós divisões éreis porém tendo-sido-restaurados em o a ele mente e em o a-ela parecer');
INSERT INTO verses VALUES (28428, 46, 1, 11, 'foi-revelado pois a-mim acerca-de vosso irmãos meu sob o Cloe que Contendas em a-vós são');
INSERT INTO verses VALUES (28429, 46, 1, 12, 'digo porém isto que cada-um vosso diz eu de-fato sou Paulo eu porém Apolo eu porém Cefas eu porém de-Christos');
INSERT INTO verses VALUES (28430, 46, 1, 13, 'tem-sido-dividido o Christos não Paulo foi-crucificado em-favor-de vosso ou para o nome Paulo fostes-batizados');
INSERT INTO verses VALUES (28431, 46, 1, 14, 'dou-graças que a-ninguém vosso batizei se não Crispo e Gaio');
INSERT INTO verses VALUES (28432, 46, 1, 15, 'para que não alguém diga que para o meu nome fostes-batizados');
INSERT INTO verses VALUES (28433, 46, 1, 16, 'batizei porém e o Estéfanas casa restante não sei se alguém outro batizei');
INSERT INTO verses VALUES (28434, 46, 1, 17, 'não pois enviou me Christos batizar mas anunciar-boa-nova não em com-sabedoria da-palavra para que não seja-esvaziada o cruz o de-Christos');
INSERT INTO verses VALUES (28435, 46, 1, 18, 'o palavra pois o o da-cruz o por-um-lado perecendo loucura é o porém aos-sendo-salvos a-nós poder de-Theos é');
INSERT INTO verses VALUES (28436, 46, 1, 19, 'está-escrito pois Destruirei o sabedoria o sábios e o entendimento o entendidos anularei');
INSERT INTO verses VALUES (28437, 46, 1, 20, 'onde sábio onde escriba onde disputador o eternidade deste não tornou-tolo o Theos o sabedoria o do-mundo');
INSERT INTO verses VALUES (28438, 46, 1, 21, 'uma-vez-que pois em o com-sabedoria o de-Theos não conheceu o mundo através-de o da-sabedoria o Theos agradou-se o Theos através-de o loucura o proclamação salvar o crentes');
INSERT INTO verses VALUES (28439, 46, 1, 22, 'uma-vez-que e judeus sinais pedem e Gregos sabedoria buscam');
INSERT INTO verses VALUES (28440, 46, 1, 23, 'nós porém pregamos Christos crucificado judeus por-um-lado tropeço nações porém loucura');
INSERT INTO verses VALUES (28441, 46, 1, 24, 'a-eles porém o chamados judeus e e gregos Christos de-Theos poder e de-Theos sabedoria');
INSERT INTO verses VALUES (28442, 46, 1, 25, 'que o tolo o de-Theos mais-sábio o dos-homens é e o fraco o de-Theos Mais-forte o dos-homens');
INSERT INTO verses VALUES (28443, 46, 1, 26, 'Vede pois o chamado vosso irmãos que não muitos sábios segundo carne não muitos poderosos não muitos nobres');
INSERT INTO verses VALUES (28444, 46, 1, 27, 'mas o tolas o do-mundo escolheu o Theos para que envergonhe o sábios e o fracos o do-mundo escolheu o Theos para que envergonhe o Forte');
INSERT INTO verses VALUES (28445, 46, 1, 28, 'e o ignóbil o do-mundo e o menosprezadas escolheu o Theos o não sendo para que o sendo anule');
INSERT INTO verses VALUES (28446, 46, 1, 29, 'para-que não glorie-se toda carne diante-de o de-Theos');
INSERT INTO verses VALUES (28447, 46, 1, 30, 'de dele porém vós sois em em-Christos Iesous o qual aconteceu sabedoria a-nós de de-Theos justiça e e santificação e redenção');
INSERT INTO verses VALUES (28448, 46, 1, 31, 'para que assim-como está-escrito o gloriando-se em ao-Kyrios glorie-se');
INSERT INTO chapters VALUES (1064, 46, 2, 16);
INSERT INTO verses VALUES (28449, 46, 2, 1, 'eu-também vindo junto-a vos irmãos vieram não segundo Superioridade da-palavra ou da-sabedoria anunciando a-vós o testemunho o de-Theos');
INSERT INTO verses VALUES (28450, 46, 2, 2, 'não pois Julguei algo sei em a-vós se não Iesous Christos e este crucificado');
INSERT INTO verses VALUES (28451, 46, 2, 3, 'e-eu em fraqueza e em medo e em tremor muito tornei-me junto-a vos');
INSERT INTO verses VALUES (28452, 46, 2, 4, 'e o palavra meu e o pregação meu não em persuasivas da-sabedoria palavras mas em demonstração do-espírito e do-poder');
INSERT INTO verses VALUES (28453, 46, 2, 5, 'para que o fé vosso não seja em com-sabedoria dos-homens mas em poder de-Theos');
INSERT INTO verses VALUES (28454, 46, 2, 6, 'sabedoria porém falamos em o aos-perfeitos sabedoria porém não o eternidade deste nem o governantes o eternidade deste o sendo-anuladas');
INSERT INTO verses VALUES (28455, 46, 2, 7, 'mas falamos de-Theos sabedoria em mistério o tendo-sido-escondida o qual predestinou o Theos antes-de o eras para glória nosso');
INSERT INTO verses VALUES (28456, 46, 2, 8, 'o qual ninguém o governantes o eternidade deste tem-conhecido se pois conheceram não partícula-condicional o Kyrion o da-glória crucificaram');
INSERT INTO verses VALUES (28457, 46, 2, 9, 'mas assim-como está-escrito o qual olho não viu e ouvido não ouviu e sobre coração do-homem não subiu quanto preparou o Theos o amam ele');
INSERT INTO verses VALUES (28458, 46, 2, 10, 'a-nós pois revelou o Theos através-de o do-espírito o pois espírito todas-as-coisas Examina e o profundezas o de-Theos');
INSERT INTO verses VALUES (28459, 46, 2, 11, 'quem pois sei dos-homens o o do-homem se não o espírito o do-homem o em a ele assim e o o de-Theos ninguém tem-conhecido se não o espírito o de-Theos');
INSERT INTO verses VALUES (28460, 46, 2, 12, 'nós porém não o espírito o do-mundo recebemos mas o espírito o de o de-Theos para que sei o sob o de-Theos os-tendo-sido-concedidos-por-graça a-nós');
INSERT INTO verses VALUES (28461, 46, 2, 13, 'o qual e falamos não em ensinados humana da-sabedoria palavras mas em ensinados do-espírito espirituais espirituais comparando');
INSERT INTO verses VALUES (28462, 46, 2, 14, 'natural porém homem não recebe o o do-espírito o de-Theos loucura pois a ele é e não pode conhecer que espiritualmente é-examinado');
INSERT INTO verses VALUES (28463, 46, 2, 15, 'o porém espiritual examina por-um-lado todas-as-coisas ele porém sob de-ninguém é-examinado');
INSERT INTO verses VALUES (28464, 46, 2, 16, 'quem pois conheceu entendimento do-Kyrios o qual unirá ele nós porém entendimento de-Christos temos');
INSERT INTO chapters VALUES (1065, 46, 3, 23);
INSERT INTO verses VALUES (28465, 46, 3, 1, 'eu-também irmãos não fui-capaz falar a-vós como espirituais mas como carnais como infantes em em-Christos');
INSERT INTO verses VALUES (28466, 46, 3, 2, 'leite vos Dei-de-beber não alimento ainda-não pois podíeis mas nem ainda agora podeis');
INSERT INTO verses VALUES (28467, 46, 3, 3, 'ainda pois carnais sois onde pois em a-vós zelo e contenda não carnais sois e segundo homem andai');
INSERT INTO verses VALUES (28468, 46, 3, 4, 'quando pois diga alguém eu de-fato sou Paulo outro e/mas eu Apolo não homens sois');
INSERT INTO verses VALUES (28469, 46, 3, 5, 'quê portanto é Apolo quê e/mas é Paulo servos através-de o qual crestes e a-cada-um como o Kyrios deu');
INSERT INTO verses VALUES (28470, 46, 3, 6, 'eu Plantei Apolo Deu-de-beber mas o Theos crescia');
INSERT INTO verses VALUES (28471, 46, 3, 7, 'de-modo-que nem o plantando é algo nem o regando mas o fazendo-crescer Theos');
INSERT INTO verses VALUES (28472, 46, 3, 8, 'o plantando porém e o regando um são cada-um porém o próprio salário receberá segundo o próprio trabalho');
INSERT INTO verses VALUES (28473, 46, 3, 9, 'de-Theos pois somos cooperadores de-Theos lavoura de-Theos edificação sois');
INSERT INTO verses VALUES (28474, 46, 3, 10, 'segundo o graça o de-Theos o dada a-mim como sábio mestre-construtor fundamento pus outro porém edifica-sobre cada-um porém veja como edifica-sobre');
INSERT INTO verses VALUES (28475, 46, 3, 11, 'fundamento pois outro ninguém pode pôr de-junto-de o posto o qual é Iesous Christos');
INSERT INTO verses VALUES (28476, 46, 3, 12, 'se e/mas alguém edifica-sobre sobre o fundamento ouro prata pedras preciosos madeiras erva palha');
INSERT INTO verses VALUES (28477, 46, 3, 13, 'cada-um o obra manifesto acontecerá o pois dia manifestará que em fogo é-revelado e cada-um o obra qual é o fogo ele examinará');
INSERT INTO verses VALUES (28478, 46, 3, 14, 'se de-alguém o obra permanecerá o qual Edificou-sobre salário receberá');
INSERT INTO verses VALUES (28479, 46, 3, 15, 'se de-alguém o obra será-queimado sofrerá-perda ele porém será-salvo assim porém como através-de fogo');
INSERT INTO verses VALUES (28480, 46, 3, 16, 'não sei que templo de-Theos sois e o espírito o de-Theos em a-vós habita');
INSERT INTO verses VALUES (28481, 46, 3, 17, 'se alguém o templo o de-Theos corrompe corromperá este o Theos o pois templo o de-Theos santo é os-quais sois vós');
INSERT INTO verses VALUES (28482, 46, 3, 18, 'ninguém si-mesmo que-não-engane se alguém parece sábio ser em a-vós em o era neste tolo aconteça para que aconteça sábio');
INSERT INTO verses VALUES (28483, 46, 3, 19, 'o pois sabedoria o do-mundo deste loucura de-junto-de o a-Theos é está-escrito pois o apanhando o sábios em o astúcia deles');
INSERT INTO verses VALUES (28484, 46, 3, 20, 'e novamente Kyrios conhece o raciocínios o sábios que são vãos');
INSERT INTO verses VALUES (28485, 46, 3, 21, 'de-modo-que ninguém glorie-se em aos-homens todas-as-coisas pois vosso é');
INSERT INTO verses VALUES (28486, 46, 3, 22, 'seja Paulo seja Apolo seja Cefas seja mundo seja vida seja morte seja presentes seja as-coisas-futuras todas-as-coisas vosso');
INSERT INTO verses VALUES (28487, 46, 3, 23, 'vós porém de-Christos Christos porém de-Theos');
INSERT INTO chapters VALUES (1066, 46, 4, 21);
INSERT INTO verses VALUES (28488, 46, 4, 1, 'assim nos considere homem como servos de-Christos e administradores mistérios de-Theos');
INSERT INTO verses VALUES (28489, 46, 4, 2, 'aqui restante é-buscado em o administradores para que fiel alguém seja-encontrada');
INSERT INTO verses VALUES (28490, 46, 4, 3, 'mim porém para mínimo é para que sob vosso seja-interrogado ou sob humana do-dia mas nem a-mim-mesmo examino');
INSERT INTO verses VALUES (28491, 46, 4, 4, 'nada pois a-mim-mesmo tenho-consciência mas não em neste tenho-sido-justificado o porém examinando me Kyrios é');
INSERT INTO verses VALUES (28492, 46, 4, 5, 'de-modo-que não antes-de tempo algo julgais até partícula-condicional venha o Kyrios o qual e iluminará o ocultas o das-trevas e manifestação o propósitos o corações e então o louvor acontecerá a-cada-um de o de-Theos');
INSERT INTO verses VALUES (28493, 46, 4, 6, 'estas-coisas e/mas irmãos apliquei-figuradamente para a-mim-mesmo e Apolo através-de vos para que em a-nós aprendei o não em-favor-de o qual está-escrito para que não um em-favor-de o um estais-inchados segundo o de-outro');
INSERT INTO verses VALUES (28494, 46, 4, 7, 'quem pois te distingue quê porém tens o qual não recebeste se porém e recebeste quê glorias-te como não tendo-recebido');
INSERT INTO verses VALUES (28495, 46, 4, 8, 'já tendo-sido-saciados sois já Enriquecestes sem nosso reinastes e oxalá pois reinastes para que e nós a-vós reinemos-juntamente');
INSERT INTO verses VALUES (28496, 46, 4, 9, 'penso pois o Theos nos o apóstolos Últimos demonstrou como condenados-à-morte que teatro tornamo-nos o ao-mundo e anjo e aos-homens');
INSERT INTO verses VALUES (28497, 46, 4, 10, 'nós tolos através-de Christon vós porém prudentes em em-Christos nós fracos vós porém fortes vós Ilustres nós porém desonrados');
INSERT INTO verses VALUES (28498, 46, 4, 11, 'até o agora hora e temos-fome e tenhamos-sede e estamos-nus e somos-esbofeteados e somos-sem-lar');
INSERT INTO verses VALUES (28499, 46, 4, 12, 'e labutamos trabalhando o próprias mãos sendo-injuriados bendizemos sendo-perseguidos suportamos');
INSERT INTO verses VALUES (28500, 46, 4, 13, 'sendo-difamados exortamos como imundícies o do-mundo tornamo-nos todos refugo até agora');
INSERT INTO verses VALUES (28501, 46, 4, 14, 'não envergonhando vos escrever estas-coisas mas como filhos meu amados admoestando');
INSERT INTO verses VALUES (28502, 46, 4, 15, 'se pois dez-mil tutores tenhais em em-Christos mas não a-muitos pais em pois em-Christos Iesous através-de o evangelho eu vos gerei');
INSERT INTO verses VALUES (28503, 46, 4, 16, 'rogo portanto vos imitadores meu tornai-vos');
INSERT INTO verses VALUES (28504, 46, 4, 17, 'através-de isto ele enviei a-vós Timóteo o qual é meu filho amado e fiel em ao-Kyrios o qual vos lembrança o caminhos meu o em em-Christos Iesous assim-como por-toda-parte em toda na-igreja ensino');
INSERT INTO verses VALUES (28505, 46, 4, 18, 'como não vindo e/mas meu junto-a vos foram-ensoberbecidos alguns');
INSERT INTO verses VALUES (28506, 46, 4, 19, 'virei porém rapidamente junto-a vos se o Kyrios queira e conhecerei não o palavra o tendo-sido-inchados mas o poder');
INSERT INTO verses VALUES (28507, 46, 4, 20, 'não pois em em-palavra o reino o de-Theos mas em poder');
INSERT INTO verses VALUES (28508, 46, 4, 21, 'quê quereis em vara venha junto-a vos ou em amor espírito e mansidão');
INSERT INTO chapters VALUES (1067, 46, 5, 13);
INSERT INTO verses VALUES (28509, 46, 5, 1, 'Totalmente é-ouvido em a-vós prostituição e tal prostituição a-qual nem em o nações de-modo-que mulher alguém o do-Pai ter');
INSERT INTO verses VALUES (28510, 46, 5, 2, 'e vós tendo-sido-inchados sois e não mais lamentai para que seja-levantado de meio vosso o o obra isto tendo-praticado');
INSERT INTO verses VALUES (28511, 46, 5, 3, 'eu por-um-lado pois estando-ausente o corpo estando-presente porém o espírito já tenho-julgado como estando-presente o assim isto tendo-realizado');
INSERT INTO verses VALUES (28512, 46, 5, 4, 'em o em-nome o do-Kyrios Iesous tendo-sido-reunidos vosso e o mim do-espírito com o poder o do-Kyrios nosso Iesous');
INSERT INTO verses VALUES (28513, 46, 5, 5, 'entregar o tal o Satanás para destruição o carne para que o espírito seja-salvo em o dia o do-Kyrios');
INSERT INTO verses VALUES (28514, 46, 5, 6, 'não belo o orgulho vosso não sei que pequena fermento todo o massa leveda');
INSERT INTO verses VALUES (28515, 46, 5, 7, 'limpai o velha fermento para que éreis novo massa assim-como sois ázimos e pois o páscoa nosso Foi-sacrificado Christos');
INSERT INTO verses VALUES (28516, 46, 5, 8, 'de-modo-que Celebremos-a-festa não em fermento velha nem em fermento maldade e maldade mas em ázimos sinceridade e da-verdade');
INSERT INTO verses VALUES (28517, 46, 5, 9, 'Escrevi a-vós em o carta não misturar-se-com imorais');
INSERT INTO verses VALUES (28518, 46, 5, 10, 'não de-todo-modo o imorais o do-mundo deste ou o avarentos e rapaces ou idólatras porque Devíeis então de o do-mundo sair');
INSERT INTO verses VALUES (28519, 46, 5, 11, 'agora porém escrevi a-vós não misturar-se-com se alguém irmão sendo-nomeado seja fornicador ou ganancioso ou idólatra ou injuriador ou bêbado ou rapace o tal nem comer-com');
INSERT INTO verses VALUES (28520, 46, 5, 12, 'quê pois a-mim o fora julgar não o dentro vós julgais');
INSERT INTO verses VALUES (28521, 46, 5, 13, 'o porém fora o Theos julgará expulsai o mau de vosso deles');
INSERT INTO chapters VALUES (1068, 46, 6, 20);
INSERT INTO verses VALUES (28522, 46, 6, 1, 'Ousa alguém vosso assunto tendo junto-a o outro ser-julgado sobre o injustos e não sobre o dos-santos');
INSERT INTO verses VALUES (28523, 46, 6, 2, 'ou não sei que o santos o mundo julgarão e se em a-vós é-julgado o mundo indignos sois tribunais menores');
INSERT INTO verses VALUES (28524, 46, 6, 3, 'não sei que anjo julgaremos quanto-mais desta-vida');
INSERT INTO verses VALUES (28525, 46, 6, 4, 'desta-vida por-um-lado portanto tribunais se tenhais o tendo-sido-desprezados em o assembleia estes sentais');
INSERT INTO verses VALUES (28526, 46, 6, 5, 'junto-a vergonha a-vós digo assim não há em a-vós ninguém sábio o qual poderá distinguir cada meio o do-irmão dele');
INSERT INTO verses VALUES (28527, 46, 6, 6, 'mas irmão com do-irmão é-julgado e isto sobre incrédulos');
INSERT INTO verses VALUES (28528, 46, 6, 7, 'já por-um-lado portanto totalmente derrota a-vós é que julgamentos tendes com deles-mesmos através-de quê não mais sois-injustiçados através-de quê não mais sois-privados');
INSERT INTO verses VALUES (28529, 46, 6, 8, 'mas vós praticais-injustiça e defraudais e isto irmãos');
INSERT INTO verses VALUES (28530, 46, 6, 9, 'ou não sei que injustos de-Theos reino não herdarão não errais nem fornicadores nem idólatras nem adúlteros nem efeminados nem sodomitas');
INSERT INTO verses VALUES (28531, 46, 6, 10, 'nem ladrões nem avarentos não bêbados não injuriadores não rapaces reino de-Theos herdarão');
INSERT INTO verses VALUES (28532, 46, 6, 11, 'e estas-coisas alguns éreis mas fostes-lavados mas Fostes-santificados mas fostes-justificados em o em-nome o do-Kyrios Iesous de-Christos e em o Espírito o de-Theos nosso');
INSERT INTO verses VALUES (28533, 46, 6, 12, 'todas-as-coisas a-mim é-lícito mas não todas-as-coisas convém todas-as-coisas a-mim é-lícito mas não eu serei-dominado por de-alguém');
INSERT INTO verses VALUES (28534, 46, 6, 13, 'o alimentos o ventre e o ventre o alimentos o porém Theos e esta e estas-coisas anulará o porém corpo não o imoralidade mas o ao-Kyrios e o Kyrios o corpo');
INSERT INTO verses VALUES (28535, 46, 6, 14, 'o porém Theos e o Kyrion ressuscitou e nos ressuscitará através-de o do-poder dele');
INSERT INTO verses VALUES (28536, 46, 6, 15, 'não sei que o corpos vosso membros de-Christos é levantando portanto o membros o de-Christos farei de-prostituta membros não seja-assim');
INSERT INTO verses VALUES (28537, 46, 6, 16, 'ou não sei que o unindo-se o a-prostituta um corpo é serão pois diz o dois para carne uma');
INSERT INTO verses VALUES (28538, 46, 6, 17, 'o porém unindo-se o ao-Kyrios um espírito é');
INSERT INTO verses VALUES (28539, 46, 6, 18, 'fugi o prostituição todo pecado o qual se faça homem fora-de o corpo é o porém fornicando para o próprio corpo peca');
INSERT INTO verses VALUES (28540, 46, 6, 19, 'ou não sei que o corpo vosso templo o em a-vós do-santo Espírito é o qual tendes de de-Theos e não sois deles-mesmos');
INSERT INTO verses VALUES (28541, 46, 6, 20, 'fostes-comprados pois honra glorificai pois o Theos em o corpo vosso');
INSERT INTO chapters VALUES (1069, 46, 7, 40);
INSERT INTO verses VALUES (28542, 46, 7, 1, 'acerca-de porém o qual escrevestes belo ao-homem mulher não tocar');
INSERT INTO verses VALUES (28543, 46, 7, 2, 'através-de porém o imoralidade cada-um o si-mesmo mulher tenha e Cada-uma o próprio homem tenha');
INSERT INTO verses VALUES (28544, 46, 7, 3, 'o mulher o homem o dívida devolva semelhantemente porém e o mulher o homem');
INSERT INTO verses VALUES (28545, 46, 7, 4, 'o mulher o próprio do-corpo não tem-autoridade mas o homem semelhantemente porém e o homem o próprio do-corpo não tem-autoridade mas o mulher');
INSERT INTO verses VALUES (28546, 46, 7, 5, 'não defraudais uns-aos-outros se acaso partícula-condicional de acordo-mútuo junto-a tempo para que dediqueis-vos o oração e novamente sobre o ele éreis para que não tente vos o Satanás através-de o intemperança vosso');
INSERT INTO verses VALUES (28547, 46, 7, 6, 'isto porém digo segundo concessão não segundo Mandamento');
INSERT INTO verses VALUES (28548, 46, 7, 7, 'quero porém todos homens ser como e a-mim-mesmo mas cada-um próprio tem dom de de-Theos o por-um-lado assim o porém assim');
INSERT INTO verses VALUES (28549, 46, 7, 8, 'digo porém o não-casados e o viúvas belo a-eles se permaneçam como eu-também');
INSERT INTO verses VALUES (28550, 46, 7, 9, 'se porém não dominam-se casem-se melhor pois é casar ou ser-inflamado');
INSERT INTO verses VALUES (28551, 46, 7, 10, 'o porém tendo-casado ordeno não eu mas o Kyrios mulher de homem não ser-separado');
INSERT INTO verses VALUES (28552, 46, 7, 11, 'se porém e seja-separado permaneça não-casado ou o marido seja-reconciliado e homem mulher não perdoar');
INSERT INTO verses VALUES (28553, 46, 7, 12, 'o porém restantes digo eu não o Kyrios se alguém irmão mulher tem incrédulo e esta consente-junto habitar com dele não deixe ela');
INSERT INTO verses VALUES (28554, 46, 7, 13, 'e mulher a-qual tem homem incrédulo e este consente-junto habitar com dela não deixe o homem');
INSERT INTO verses VALUES (28555, 46, 7, 14, 'tem-sido-santificado pois o homem o incrédulo em o mulher e tem-sido-santificado o mulher o incrédulo em o ao-irmão porque então o filhos vosso impuros é agora porém santas é');
INSERT INTO verses VALUES (28556, 46, 7, 15, 'se porém o incrédulo separa-se separe-se não tem-sido-escravizado o irmão ou o irmã em o tais em porém paz tem-chamado vos o Theos');
INSERT INTO verses VALUES (28557, 46, 7, 16, 'quê pois sei mulher se o homem salvarás ou quê sei homem se o mulher salvarás');
INSERT INTO verses VALUES (28558, 46, 7, 17, 'se não a-cada-um como tem-dividido o Kyrios cada-um como tem-chamado o Theos assim ande e assim em o assembleias todas ordeno');
INSERT INTO verses VALUES (28559, 46, 7, 18, 'tendo-sido-circuncidado alguém foi-chamado não não-se-desfaça-a-circuncisão em incircuncisão tem-sido-chamado alguém não seja-circuncidado');
INSERT INTO verses VALUES (28560, 46, 7, 19, 'o circuncisão nada é e o incircuncisão nada é mas guarda mandamentos de-Theos');
INSERT INTO verses VALUES (28561, 46, 7, 20, 'cada-um em o chamado o qual foi-chamado em nesta permaneça');
INSERT INTO verses VALUES (28562, 46, 7, 21, 'servo foste-chamado não a-ti importe mas se e podes livre tornar-se mais usar');
INSERT INTO verses VALUES (28563, 46, 7, 22, 'o pois em ao-Kyrios tendo-sido-chamado servo liberto do-Kyrios é semelhantemente o livre tendo-sido-chamado servo é de-Christos');
INSERT INTO verses VALUES (28564, 46, 7, 23, 'honra fostes-comprados não tornai-vos servos dos-homens');
INSERT INTO verses VALUES (28565, 46, 7, 24, 'cada-um em o qual foi-chamado irmãos em neste permaneça de-junto-de a-Theos');
INSERT INTO verses VALUES (28566, 46, 7, 25, 'acerca-de porém o de-virgens mandado do-Kyrios não tenho opinião porém dou como tendo-sido-alvo-de-misericórdia sob do-Kyrios fiel ser');
INSERT INTO verses VALUES (28567, 46, 7, 26, 'Penso portanto isto belo existir através-de o tendo-se-apresentado necessidade que belo ao-homem o assim ser');
INSERT INTO verses VALUES (28568, 46, 7, 27, 'tens-sido-amarrado mulher não busca soltura tens-sido-desatado de mulher não busca mulher');
INSERT INTO verses VALUES (28569, 46, 7, 28, 'se porém e cases não Pecaste e se case o virgem não pecou tribulação porém o carne terão o tais eu porém vosso poupo');
INSERT INTO verses VALUES (28570, 46, 7, 29, 'isto e/mas digo irmãos o tempo tendo-sido-contraído é o restante para que e o tendo mulheres como não tendo sejam');
INSERT INTO verses VALUES (28571, 46, 7, 30, 'e o chorando como não chorando e o alegrando-se como não alegrando-se e o comprando como não retendo');
INSERT INTO verses VALUES (28572, 46, 7, 31, 'e o usando o mundo como não usando-plenamente passa pois o forma o do-mundo deste');
INSERT INTO verses VALUES (28573, 46, 7, 32, 'quero porém vos livres-de-preocupação ser o não-casado preocupa-se o o do-Kyrios como agrade o ao-Kyrios');
INSERT INTO verses VALUES (28574, 46, 7, 33, 'o porém tendo-casado preocupa-se o o do-mundo como agrade o mulher');
INSERT INTO verses VALUES (28575, 46, 7, 34, 'e tem-sido-dividido e o mulher o não-casado e o virgem preocupa-se o o do-Kyrios para que seja santa e o corpo e o espírito o porém tendo-casado preocupa-se o o do-mundo como agrade o homem');
INSERT INTO verses VALUES (28576, 46, 7, 35, 'isto porém junto-a o vosso deles proveitoso digo não para que laço a-vós lançarei-sobre mas junto-a o decoroso e assíduo o ao-Kyrios sem-distração');
INSERT INTO verses VALUES (28577, 46, 7, 36, 'se e/mas alguém agir-indecentemente sobre o virgem dele supõe se seja Além-da-flor-da-idade e assim deve tornar-se o qual quer faça não peca casem-se');
INSERT INTO verses VALUES (28578, 46, 7, 37, 'o qual porém está-de-pé em o no-coração dele Firme não tendo necessidade autoridade porém tem acerca-de o próprio da-vontade e isto tem-julgado em o em-particular no-coração guardar o si-mesmo virgem bem fará');
INSERT INTO verses VALUES (28579, 46, 7, 38, 'de-modo-que e o dando-em-casamento o si-mesmo virgem bem faz e o não dando-em-casamento melhor fará');
INSERT INTO verses VALUES (28580, 46, 7, 39, 'mulher tem-sido-atado sobre quanto tempo vive o homem dela se porém adormeça o homem livre é o qual quer ser-dada-em-casamento somente em ao-Kyrios');
INSERT INTO verses VALUES (28581, 46, 7, 40, 'mais-bem-aventurada e/mas é se assim permaneça segundo o minha opinião penso porém e-eu espírito de-Theos ter');
INSERT INTO chapters VALUES (1070, 46, 8, 13);
INSERT INTO verses VALUES (28582, 46, 8, 1, 'acerca-de porém o sacrificado-a-ídolos sei que todos saibam temos o conhecimento incha o porém amor edifica');
INSERT INTO verses VALUES (28583, 46, 8, 2, 'se alguém parece ter-conhecido algo ainda-não conheceu assim-como é necessário conhecer');
INSERT INTO verses VALUES (28584, 46, 8, 3, 'se e/mas alguém ama o Theos este Tem-sido-conhecido sob dele');
INSERT INTO verses VALUES (28585, 46, 8, 4, 'acerca-de o alimento portanto o sacrificado-a-ídolos sei que nada ídolo em ao-mundo e que ninguém Theos se não um');
INSERT INTO verses VALUES (28586, 46, 8, 5, 'e pois se-de-fato são sendo-chamados theoi seja em no-céu seja sobre da-terra assim-como são theoi muitos e senhores muitos');
INSERT INTO verses VALUES (28587, 46, 8, 6, 'mas a-nós um Theos o Pai de o qual o todas-as-coisas e nós para ele e um Kyrios Iesous Christos através-de o qual o todas-as-coisas e nós através-de dele');
INSERT INTO verses VALUES (28588, 46, 8, 7, 'mas não em todos o conhecimento alguns porém o costume até agora o ídolo como sacrificado-a-ídolo comem e o consciência deles fraco sendo é-contaminado');
INSERT INTO verses VALUES (28589, 46, 8, 8, 'alimento porém nos não apresentará o a-Theos nem se não comamos Faltamos nem se comamos abundamos');
INSERT INTO verses VALUES (28590, 46, 8, 9, 'vede porém não como o autoridade vosso esta tropeço aconteça o fracos');
INSERT INTO verses VALUES (28591, 46, 8, 10, 'se pois alguém veja te o tendo saibam em templo-de-ídolo reclinado não o consciência dele fraco sendo será-edificada para o o coisas-sacrificadas-a-ídolos comer');
INSERT INTO verses VALUES (28592, 46, 8, 11, 'perece pois o fracos em o tua conhecimento o irmão através-de o qual Christos morreu');
INSERT INTO verses VALUES (28593, 46, 8, 12, 'assim porém pecando para o irmãos e batendo deles o consciência estando-enferma para Christos pecais');
INSERT INTO verses VALUES (28594, 46, 8, 13, 'pelo-que-também se alimento escandaliza o irmão meu não não coma carnes para o eternidade para que não o irmão meu escandalizarei');
INSERT INTO chapters VALUES (1071, 46, 9, 27);
INSERT INTO verses VALUES (28595, 46, 9, 1, 'não sou livre não sou apóstolo não Iesous o Kyrion nosso Tenho-visto não o obra meu vós sois em ao-Kyrios');
INSERT INTO verses VALUES (28596, 46, 9, 2, 'se a-outros não sou apóstolo mas pois a-vós sou o pois selo meu o apostolado vós sois em ao-Kyrios');
INSERT INTO verses VALUES (28597, 46, 9, 3, 'o minha defesa o mim examinam é esta');
INSERT INTO verses VALUES (28598, 46, 9, 4, 'não não temos autoridade comer e beber');
INSERT INTO verses VALUES (28599, 46, 9, 5, 'não não temos autoridade irmã mulher andar-ao-redor como e o restantes apóstolos e o irmãos o do-Kyrios e Cefas');
INSERT INTO verses VALUES (28600, 46, 9, 6, 'ou só eu e Barnabé não temos autoridade não trabalhar');
INSERT INTO verses VALUES (28601, 46, 9, 7, 'quem guerreia próprios soldos alguma-vez quem planta vinha e o fruto dele não come ou quem apascenta rebanho e de o leite o rebanho não come');
INSERT INTO verses VALUES (28602, 46, 9, 8, 'não segundo homem estas-coisas falo ou e o lei estas-coisas não diz');
INSERT INTO verses VALUES (28603, 46, 9, 9, 'em pois o de-Moisés lei está-escrito não amordaçarás boi debulhando não o clamando importa o a-Theos');
INSERT INTO verses VALUES (28604, 46, 9, 10, 'ou através-de nos de-todo-modo diz através-de nos pois foi-escrito que deve sobre esperança o arando arar e o debulhando sobre esperança o participar');
INSERT INTO verses VALUES (28605, 46, 9, 11, 'se nós a-vós o espirituais Semeamos grande se nós vosso o carnais ceifaremos');
INSERT INTO verses VALUES (28606, 46, 9, 12, 'se outros o vosso da-autoridade participam não mais nós mas não Usamos o em-autoridade nesta mas todas-as-coisas suportamos para que não alguém impedimento demos o no-evangelho o de-Christos');
INSERT INTO verses VALUES (28607, 46, 9, 13, 'não sei que o o sagradas trabalhando o de o do-templo comem o o altar servindo-junto o altar repartem-entre-si');
INSERT INTO verses VALUES (28608, 46, 9, 14, 'assim e o Kyrios ordenou o o evangelho anunciam de o evangelho viver');
INSERT INTO verses VALUES (28609, 46, 9, 15, 'eu porém não tenho-usado a-ninguém destes não escrevi porém estas-coisas para que assim aconteça em a-mim belo pois a-mim mais morrer ou o glória meu ninguém esvaziará');
INSERT INTO verses VALUES (28610, 46, 9, 16, 'se pois anuncie-boa-nova não é a-mim orgulho necessidade pois a-mim está-colocado-sobre ai pois me é se não anuncie-boas-novas');
INSERT INTO verses VALUES (28611, 46, 9, 17, 'se pois Voluntariamente isto pratico salário tenho se porém involuntariamente administração tenho-sido-confiado');
INSERT INTO verses VALUES (28612, 46, 9, 18, 'quem portanto meu é o salário para que anunciando-boa-nova sem-custo porei o evangelho para o não usar-plenamente o em-autoridade meu em o no-evangelho');
INSERT INTO verses VALUES (28613, 46, 9, 19, 'livre pois sendo de todos todos a-mim-mesmo escravizei para que o mais ganhe');
INSERT INTO verses VALUES (28614, 46, 9, 20, 'e tornei-me o judeus como judeu para que judeus ganhe o sob lei como sob lei não sendo ele sob lei para que o sob lei ganhe');
INSERT INTO verses VALUES (28615, 46, 9, 21, 'o sem-lei como sem-lei não sendo sem-lei de-Theos mas Sob-lei de-Christos para que ganhe o sem-lei');
INSERT INTO verses VALUES (28616, 46, 9, 22, 'tornei-me o fracos fraco para que o fracos ganhe o todos tornei-me todas-as-coisas para que de-todo-modo alguns salvarei');
INSERT INTO verses VALUES (28617, 46, 9, 23, 'todas-as-coisas porém faço através-de o evangelho para que co-participante dele torne-me');
INSERT INTO verses VALUES (28618, 46, 9, 24, 'não sei que o em estádio correndo todos por-um-lado correm um porém recebe o prêmio assim correis para que alcanceis');
INSERT INTO verses VALUES (28619, 46, 9, 25, 'todo porém o lutando todas-as-coisas domina-se aqueles por-um-lado portanto para que corruptível coroa recebam nós porém incorruptível');
INSERT INTO verses VALUES (28620, 46, 9, 26, 'eu portanto assim corro como não incertamente assim luto-com-os-punhos como não ar espancando');
INSERT INTO verses VALUES (28621, 46, 9, 27, 'mas Golpeio-sob-o-olho meu o corpo e escravizo não como a-outros tendo-proclamado ele reprovado torne-me');
INSERT INTO chapters VALUES (1072, 46, 10, 33);
INSERT INTO verses VALUES (28622, 46, 10, 1, 'não quero pois vos ignorar irmãos que o pais nosso todos sob o nuvem eram e todos através-de o do-mar atravessaram');
INSERT INTO verses VALUES (28623, 46, 10, 2, 'e todos para o Moisés batizaram-se em o nuvem e em o mar');
INSERT INTO verses VALUES (28624, 46, 10, 3, 'e todos o ele espiritual alimento comeram');
INSERT INTO verses VALUES (28625, 46, 10, 4, 'e todos o ele espiritual beberam bebida bebiam pois de espiritual seguindo rochas o rocha porém era o Christos');
INSERT INTO verses VALUES (28626, 46, 10, 5, 'mas não em o mais deles agradou-se o Theos foram-prostrados pois em o deserto');
INSERT INTO verses VALUES (28627, 46, 10, 6, 'estas-coisas porém modelos nosso tornaram-se para o não ser nos desejadores males assim-como e-aqueles desejaram');
INSERT INTO verses VALUES (28628, 46, 10, 7, 'nem idólatras tornai-vos assim-como alguns deles assim-como está-escrito Sentou-se o povo comer e beber e levantaram brincar');
INSERT INTO verses VALUES (28629, 46, 10, 8, 'nem forniquemos assim-como alguns deles Fornicaram e caíram uma dia vinte-e-três milhares');
INSERT INTO verses VALUES (28630, 46, 10, 9, 'nem tentemos o Kyrion assim-como alguns deles tentaram e sob o serpentes pereciam');
INSERT INTO verses VALUES (28631, 46, 10, 10, 'nem murmurais assim-como alguns deles murmuraram e pereceram sob o destruidor');
INSERT INTO verses VALUES (28632, 46, 10, 11, 'estas-coisas porém tipologicamente acontecia àqueles foi-escrito porém junto-a admoestação nosso para o qual o fins o eras tem-chegado');
INSERT INTO verses VALUES (28633, 46, 10, 12, 'de-modo-que o parecendo estar-de-pé veja não caia');
INSERT INTO verses VALUES (28634, 46, 10, 13, 'tentação vos não recebeu se não humano fiel porém o Theos o qual não permitirá vos ser-tentado em-favor-de o qual podeis mas fará com o tentação e o saída o poder Suportar');
INSERT INTO verses VALUES (28635, 46, 10, 14, 'Por-isso-mesmo amados meu fugi de o idolatria');
INSERT INTO verses VALUES (28636, 46, 10, 15, 'como prudentes digo julgai vós o qual digo');
INSERT INTO verses VALUES (28637, 46, 10, 16, 'o cálice o bênção o qual bendizemos não comunhão é o sangue o de-Christos o pão o qual partimos não comunhão o do-corpo o de-Christos é');
INSERT INTO verses VALUES (28638, 46, 10, 17, 'que um pão um corpo o muitos somos o pois todos de o de-um pão participamos');
INSERT INTO verses VALUES (28639, 46, 10, 18, 'vede o Israel segundo carne não o comendo o sacrifício participantes o altar são');
INSERT INTO verses VALUES (28640, 46, 10, 19, 'quê portanto digo que sacrificado-a-ídolos quê é ou que ídolo quê é');
INSERT INTO verses VALUES (28641, 46, 10, 20, 'mas que o qual sacrificam demônios e não a-Theos sacrificam não quero porém vos participantes o demônios tornar-se');
INSERT INTO verses VALUES (28642, 46, 10, 21, 'não podeis cálice do-Kyrios beber e cálice demônios não podeis mesa do-Kyrios participar e mesa demônios');
INSERT INTO verses VALUES (28643, 46, 10, 22, 'ou provocamos-a-ciúme o Kyrion não mais-fortes dele somos');
INSERT INTO verses VALUES (28644, 46, 10, 23, 'todas-as-coisas é-lícito mas não todas-as-coisas convém todas-as-coisas é-lícito mas não todas-as-coisas edifica');
INSERT INTO verses VALUES (28645, 46, 10, 24, 'ninguém o si-mesmo busque mas o o de-outro');
INSERT INTO verses VALUES (28646, 46, 10, 25, 'todo o em mercado-de-carnes sendo-vendido comeis nada examinando através-de o consciência');
INSERT INTO verses VALUES (28647, 46, 10, 26, 'o do-Kyrios pois o terra e o plenitude dela');
INSERT INTO verses VALUES (28648, 46, 10, 27, 'se alguém chama vos o incrédulos e quereis ir todo o o-sendo-posto-diante a-vós comeis nada examinando através-de o consciência');
INSERT INTO verses VALUES (28649, 46, 10, 28, 'se e/mas alguém a-vós diga isto sacrificado-em-templo é não comeis através-de aquele o tendo-informado e o consciência');
INSERT INTO verses VALUES (28650, 46, 10, 29, 'consciência porém digo não o si-mesmo mas o o de-outro para que quê pois o liberdade meu é-julgado sob outra consciência');
INSERT INTO verses VALUES (28651, 46, 10, 30, 'se eu graça participo quê sou-blasfemado em-favor-de o qual eu dou-graças');
INSERT INTO verses VALUES (28652, 46, 10, 31, 'seja portanto comeis seja bebei seja algo fazei todas-as-coisas para glória de-Theos fazei');
INSERT INTO verses VALUES (28653, 46, 10, 32, 'sem-tropeço e judeus tornai-vos e gregos e o na-igreja o de-Theos');
INSERT INTO verses VALUES (28654, 46, 10, 33, 'assim-como e-eu todas-as-coisas todos agrado não buscando o de-mim-mesmo proveitoso mas o o muitos para que sejam-salvos');
INSERT INTO chapters VALUES (1073, 46, 11, 34);
INSERT INTO verses VALUES (28655, 46, 11, 1, 'imitadores meu tornai-vos assim-como e-eu de-Christos');
INSERT INTO verses VALUES (28656, 46, 11, 2, 'Louvo porém vos que todas-as-coisas meu lembrai-vos e assim-como entreguei a-vós o tradições retende');
INSERT INTO verses VALUES (28657, 46, 11, 3, 'quero porém vos sei que de-todo homem o cabeça o Christos é cabeça porém mulher o homem cabeça porém o de-Christos o Theos');
INSERT INTO verses VALUES (28658, 46, 11, 4, 'todo homem orando ou profetizando segundo cabeça tendo envergonha o cabeça dele');
INSERT INTO verses VALUES (28659, 46, 11, 5, 'toda porém mulher orando ou profetizando descoberta o cabeça envergonha o cabeça dela um pois é e o ele o tendo-sido-rapada');
INSERT INTO verses VALUES (28660, 46, 11, 6, 'se pois não cobre-se mulher e rape se porém vergonhoso mulher o rapar ou raspar-se cubra-se');
INSERT INTO verses VALUES (28661, 46, 11, 7, 'homem por-um-lado pois não deve cobrir-se o cabeça imagem e glória de-Theos sendo o mulher porém glória homem é');
INSERT INTO verses VALUES (28662, 46, 11, 8, 'não pois é homem de mulher mas mulher de homem');
INSERT INTO verses VALUES (28663, 46, 11, 9, 'e pois não foi-criado homem através-de o mulher mas mulher através-de o homem');
INSERT INTO verses VALUES (28664, 46, 11, 10, 'através-de isto deve o mulher autoridade ter sobre o cabeça através-de o anjo');
INSERT INTO verses VALUES (28665, 46, 11, 11, 'porém nem mulher sem homem nem homem sem mulher em ao-Kyrios');
INSERT INTO verses VALUES (28666, 46, 11, 12, 'assim-como pois o mulher de o homem assim e o homem através-de o mulher o porém todas-as-coisas de o de-Theos');
INSERT INTO verses VALUES (28667, 46, 11, 13, 'em a-vós a-eles julgai conveniente é mulher descoberta o a-Theos orar');
INSERT INTO verses VALUES (28668, 46, 11, 14, 'nem o natureza ela ensina vos que homem por-um-lado se tem-cabelo-longo desonra a ele é');
INSERT INTO verses VALUES (28669, 46, 11, 15, 'mulher porém se tem-cabelo-longo glória a-ela é que o cabelo em-troca-de manto foi-dado a-ela');
INSERT INTO verses VALUES (28670, 46, 11, 16, 'se e/mas alguém parece contencioso ser nós tal costume não temos nem o assembleias o de-Theos');
INSERT INTO verses VALUES (28671, 46, 11, 17, 'isto porém ordenando não louvo que não para o melhor mas para o menos reunis-vos');
INSERT INTO verses VALUES (28672, 46, 11, 18, 'primeiro por-um-lado pois reunindo-se vosso em na-igreja ouço divisões em a-vós existir e parte algo creio');
INSERT INTO verses VALUES (28673, 46, 11, 19, 'é necessário pois e heresias em a-vós ser para que e o aprovados manifestos tornem-se em a-vós');
INSERT INTO verses VALUES (28674, 46, 11, 20, 'Reunindo-se portanto vosso sobre o ele não é do-Kyrios ceia comer');
INSERT INTO verses VALUES (28675, 46, 11, 21, 'cada-um pois o próprio ceia toma-de-antemão em o comer e o qual por-um-lado tem-fome o qual porém embriaga-se');
INSERT INTO verses VALUES (28676, 46, 11, 22, 'não pois da-casa não tendes para o comer e beber ou o da-assembleia o de-Theos desprezais e envergonhais o não tendo quê diga a-vós louvarei vos em neste não louvo');
INSERT INTO verses VALUES (28677, 46, 11, 23, 'eu pois recebi de o do-Kyrios o qual e entreguei a-vós que o Kyrios Iesous em o à-noite o qual era-entregue recebeu pão');
INSERT INTO verses VALUES (28678, 46, 11, 24, 'e tendo-dado-graças partiu e disse isto meu é o corpo o em-favor-de vosso isto fazei para o minha memória');
INSERT INTO verses VALUES (28679, 46, 11, 25, 'da-mesma-forma e o cálice com o cear dizendo isto o cálice o nova aliança é em o meu sangue isto fazei quantas-vezes se bebais para o minha memória');
INSERT INTO verses VALUES (28680, 46, 11, 26, 'quantas-vezes pois se Comais o pão este e o cálice bebais o morte o do-Kyrios anunciais até o qual venha');
INSERT INTO verses VALUES (28681, 46, 11, 27, 'de-modo-que o qual partícula-condicional coma o pão ou beba o cálice o do-Kyrios indignamente culpado será o do-corpo e o sangue o do-Kyrios');
INSERT INTO verses VALUES (28682, 46, 11, 28, 'examine porém homem a-si-mesmo e assim de o pão coma e de o cálice beba');
INSERT INTO verses VALUES (28683, 46, 11, 29, 'o pois comendo e bebendo julgamento si-mesmo come e bebe não distinguindo o corpo');
INSERT INTO verses VALUES (28684, 46, 11, 30, 'através-de isto em a-vós muitos fracos e enfermos e dormem suficientes');
INSERT INTO verses VALUES (28685, 46, 11, 31, 'se porém si-mesmos discerníamos não partícula-condicional éramos-julgados');
INSERT INTO verses VALUES (28686, 46, 11, 32, 'sendo-julgados porém sob o do-Kyrios somos-disciplinados para que não com o ao-mundo sejamos-condenados');
INSERT INTO verses VALUES (28687, 46, 11, 33, 'de-modo-que irmãos meu reunindo-se para o comer uns-aos-outros esperai');
INSERT INTO verses VALUES (28688, 46, 11, 34, 'se alguém tem-fome em na-casa coma para que não para julgamento vos-reunis o porém restantes como partícula-condicional venha ordenarei');
INSERT INTO chapters VALUES (1074, 46, 12, 31);
INSERT INTO verses VALUES (28689, 46, 12, 1, 'acerca-de porém o espirituais irmãos não quero vos ignorar');
INSERT INTO verses VALUES (28690, 46, 12, 2, 'sei que quando nações éreis junto-a o ídolos o mudas como partícula-condicional éreis-conduzidos sendo-conduzidos');
INSERT INTO verses VALUES (28691, 46, 12, 3, 'por-isso faço-conhecer a-vós que ninguém em Espírito de-Theos falando diz anátema Iesous e ninguém pode dizer KYRIOS Iesous se não em Espírito no-santo');
INSERT INTO verses VALUES (28692, 46, 12, 4, 'Distribuições porém de-dons-de-graça são o porém ele espírito');
INSERT INTO verses VALUES (28693, 46, 12, 5, 'e distribuições serviços são e o ele Kyrios');
INSERT INTO verses VALUES (28694, 46, 12, 6, 'e distribuições operações são o porém ele Theos o operando o todas-as-coisas em todos');
INSERT INTO verses VALUES (28695, 46, 12, 7, 'a-cada-um porém é-dado o manifestação o do-espírito junto-a o conveniente');
INSERT INTO verses VALUES (28696, 46, 12, 8, 'o qual por-um-lado pois através-de o do-espírito é-dado palavra da-sabedoria a-outro porém palavra do-conhecimento segundo o ele espírito');
INSERT INTO verses VALUES (28697, 46, 12, 9, 'a-outro fé em o a ele Espírito a-outro porém dons curas em o um Espírito');
INSERT INTO verses VALUES (28698, 46, 12, 10, 'a-outro porém operações poderes a-outro porém profecia a-outro porém discernimentos espíritos a-outro raças línguas a-outro porém Interpretação línguas');
INSERT INTO verses VALUES (28699, 46, 12, 11, 'todas-as-coisas porém estas-coisas opera o um e o ele espírito dividindo em-particular a-cada-um assim-como quer');
INSERT INTO verses VALUES (28700, 46, 12, 12, 'Assim-como pois o corpo um é e membros muitas-coisas tem todas-as-coisas porém o membros o do-corpo muitas-coisas sendo um é corpo assim e o Christos');
INSERT INTO verses VALUES (28701, 46, 12, 13, 'e pois em um Espírito nós todos para um corpo fomos-batizados seja judeus seja Gregos seja servos seja livres e todos um espírito Fomos-feitos-beber');
INSERT INTO verses VALUES (28702, 46, 12, 14, 'e pois o corpo não é um membro mas muitas-coisas');
INSERT INTO verses VALUES (28703, 46, 12, 15, 'se diga o pé que não sou mão não sou de o do-corpo não de-junto-de isto não é de o do-corpo');
INSERT INTO verses VALUES (28704, 46, 12, 16, 'e se diga o ouvido que não sou olho não sou de o do-corpo não de-junto-de isto não é de o do-corpo');
INSERT INTO verses VALUES (28705, 46, 12, 17, 'se todo o corpo olho onde o audição se todo audição onde o olfato');
INSERT INTO verses VALUES (28706, 46, 12, 18, 'agora porém o Theos pôs o membros um cada-um deles em o corpo assim-como quis');
INSERT INTO verses VALUES (28707, 46, 12, 19, 'se porém era o todas-as-coisas um membro onde o corpo');
INSERT INTO verses VALUES (28708, 46, 12, 20, 'agora porém muitas-coisas por-um-lado membros um porém corpo');
INSERT INTO verses VALUES (28709, 46, 12, 21, 'não pode porém o olho dizer o mão necessidade teu não tenho ou novamente o cabeça o pés necessidade vosso não tenho');
INSERT INTO verses VALUES (28710, 46, 12, 22, 'mas muito mais o parecendo membros o do-corpo mais-fracos existir necessárias é');
INSERT INTO verses VALUES (28711, 46, 12, 23, 'e o qual parecemos menos-honrosos ser o do-corpo nestes honra mais-abundante colocamos-ao-redor e o indecorosas nosso decoro mais-abundante tem');
INSERT INTO verses VALUES (28712, 46, 12, 24, 'o porém decoroso nosso não necessidade tem mas o Theos misturou o corpo o Faltando mais-abundante dando honra');
INSERT INTO verses VALUES (28713, 46, 12, 25, 'para que não seja divisão em o corpo mas o ele em-favor-de uns-aos-outros preocupem-se o membros');
INSERT INTO verses VALUES (28714, 46, 12, 26, 'e seja sofre um membro sofre-com todas-as-coisas o membros seja é-glorificado membro alegra-se-junto todas-as-coisas o membros');
INSERT INTO verses VALUES (28715, 46, 12, 27, 'vós e/mas sois corpo de-Christos e membros de da-parte');
INSERT INTO verses VALUES (28716, 46, 12, 28, 'e o qual por-um-lado pôs o Theos em o na-igreja primeiro apóstolos segundo profetas terço mestres depois poderes depois dons curas socorros governos raças línguas');
INSERT INTO verses VALUES (28717, 46, 12, 29, 'não todos apóstolos não todos profetas não todos mestres não todos poderes');
INSERT INTO verses VALUES (28718, 46, 12, 30, 'não todos dons têm curas não todos em-línguas falam não todos interpretam');
INSERT INTO verses VALUES (28719, 46, 12, 31, 'zelai porém o dons o maior e ainda segundo excesso caminho a-vós mostro');
INSERT INTO chapters VALUES (1075, 46, 13, 13);
INSERT INTO verses VALUES (28720, 46, 13, 1, 'se o em-línguas o dos-homens falo e o anjo amor porém não tenho tornei-me bronze Soando ou címbalo ressoando');
INSERT INTO verses VALUES (28721, 46, 13, 2, 'e se tenho profecia e sei o mistérios todas-as-coisas e toda o saibam e se tenho toda o fé de-modo-que montes remover amor porém não tenho nada sou');
INSERT INTO verses VALUES (28722, 46, 13, 3, 'e se alimentar todas-as-coisas o pertences meu e se eu-entregue o corpo meu para que serei-queimado amor porém não tenho nada Sou-aproveitado');
INSERT INTO verses VALUES (28723, 46, 13, 4, 'o amor é-longânimo é-benigno o amor não tem-ciúmes o amor não vangloria-se não incha-se');
INSERT INTO verses VALUES (28724, 46, 13, 5, 'não age-indecentemente não busca o de-si-mesma não é-provocado não é-contado o mal');
INSERT INTO verses VALUES (28725, 46, 13, 6, 'não alegra-se sobre o injustiça alegra-se-junto porém o verdade');
INSERT INTO verses VALUES (28726, 46, 13, 7, 'todas-as-coisas suporta todas-as-coisas crê todas-as-coisas espera todas-as-coisas persevera');
INSERT INTO verses VALUES (28727, 46, 13, 8, 'o amor nunca cai seja porém profecias serão-anulados seja línguas cessarão seja conhecimento será-anulado');
INSERT INTO verses VALUES (28728, 46, 13, 9, 'de da-parte pois conhecemos e de da-parte profetizamos');
INSERT INTO verses VALUES (28729, 46, 13, 10, 'quando porém venha o perfeito o de da-parte será-anulado');
INSERT INTO verses VALUES (28730, 46, 13, 11, 'quando eu-era infante falavam como infante Pensavam como infante eu-considerava como infante quando tornei-me homem tenho-abolido o o infante');
INSERT INTO verses VALUES (28731, 46, 13, 12, 'vemos pois agora através-de Espelho em enigma então porém rosto junto-a rosto agora conheço de da-parte então porém reconhecerei assim-como e fui-reconhecido');
INSERT INTO verses VALUES (28732, 46, 13, 13, 'agora porém permanece fé esperança amor o três estas-coisas maior porém destes o amor');
INSERT INTO chapters VALUES (1076, 46, 14, 40);
INSERT INTO verses VALUES (28733, 46, 14, 1, 'Persegui o amor zelai porém o espirituais mais porém para que profetizeis');
INSERT INTO verses VALUES (28734, 46, 14, 2, 'o pois falando língua não aos-homens fala mas a-Theos ninguém pois ouve espírito porém fala mistérios');
INSERT INTO verses VALUES (28735, 46, 14, 3, 'o porém profetizando aos-homens fala edificação e consolação e consolação');
INSERT INTO verses VALUES (28736, 46, 14, 4, 'o falando língua si-mesmo edifica o porém profetizando igreja edifica');
INSERT INTO verses VALUES (28737, 46, 14, 5, 'quero porém todos vos falar em-línguas mais porém para que profetizeis maior porém o profetizando ou o falando em-línguas fora-de se não interprete para que o assembleia edificação tome');
INSERT INTO verses VALUES (28738, 46, 14, 6, 'agora e/mas irmãos se venha junto-a vos em-línguas falando quê vos Aproveitarei se não a-vós falarei ou em revelação ou em conhecimento ou em em-profecia ou em-ensino');
INSERT INTO verses VALUES (28739, 46, 14, 7, 'contudo o sem-vida voz dando seja flauta seja cítara se distinção o sons não dê como será-conhecido o sendo-tocado-flauta ou o sendo-tocado-cítara');
INSERT INTO verses VALUES (28740, 46, 14, 8, 'e pois se obscuro trombeta voz dê quem preparar-se-á para guerra');
INSERT INTO verses VALUES (28741, 46, 14, 9, 'assim e vós através-de o língua se não claro palavra deis como será-conhecido o sendo-falado sereis pois para ar falando');
INSERT INTO verses VALUES (28742, 46, 14, 10, 'tantas-coisas se aconteça raças de-vozes são em ao-mundo e nada mudo');
INSERT INTO verses VALUES (28743, 46, 14, 11, 'se portanto não sei o poder o voz serei o falando bárbaro e o falando em mim bárbaro');
INSERT INTO verses VALUES (28744, 46, 14, 12, 'assim e vós porque zelosos sois espíritos junto-a o edificação o da-assembleia buscais para que abundeis');
INSERT INTO verses VALUES (28745, 46, 14, 13, 'por-isso o falando língua ore para que interprete');
INSERT INTO verses VALUES (28746, 46, 14, 14, 'se pois ore língua o espírito meu ora o porém mente meu infrutífero é');
INSERT INTO verses VALUES (28747, 46, 14, 15, 'quê portanto é orarei o espírito orarei porém e o mente salmodiarei o espírito salmodiarei porém e o mente');
INSERT INTO verses VALUES (28748, 46, 14, 16, 'porque se abençoes espírito o preenchendo o lugar o Leigo como dirá o Amém sobre o tua ação-de-graças uma-vez-que quê dizes não sei');
INSERT INTO verses VALUES (28749, 46, 14, 17, 'tu por-um-lado pois bem dás-graças mas o outro não é-edificada');
INSERT INTO verses VALUES (28750, 46, 14, 18, 'dou-graças o a-Theos todos vosso mais em-línguas falo');
INSERT INTO verses VALUES (28751, 46, 14, 19, 'mas em na-igreja quero cinco palavras o mente meu falar para que e outros instruirei ou dez-mil palavras em língua');
INSERT INTO verses VALUES (28752, 46, 14, 20, 'Irmãos não crianças tornai-vos o em-mentes mas o maldade sejais-crianças o porém em-mentes perfeitos tornai-vos');
INSERT INTO verses VALUES (28753, 46, 14, 21, 'em o lei está-escrito que em De-outras-línguas e em com-lábios outros falarei o povo neste e nem assim ouvirão meu diz Kyrios');
INSERT INTO verses VALUES (28754, 46, 14, 22, 'de-modo-que o línguas para sinal são não o creem mas o incrédulos o porém profecia não o incrédulos mas o creem');
INSERT INTO verses VALUES (28755, 46, 14, 23, 'se portanto reúna-se o assembleia toda sobre o ele e todos falem em-línguas entrem porém leigos ou incrédulos não dirão que enlouqueceis');
INSERT INTO verses VALUES (28756, 46, 14, 24, 'se porém todos profetizem entre e/mas alguém incrédulo ou leigo é-repreendido sob todos é-examinado sob todos');
INSERT INTO verses VALUES (28757, 46, 14, 25, 'o ocultas o do-coração dele manifesta torna-se e assim caindo sobre rosto prostrar-se-á o a-Theos anunciando que Verdadeiramente o Theos em a-vós é');
INSERT INTO verses VALUES (28758, 46, 14, 26, 'quê portanto é irmãos quando vos-reunis cada-um salmo tem ensino tem revelação tem língua tem Interpretação tem todas-as-coisas junto-a edificação seja');
INSERT INTO verses VALUES (28759, 46, 14, 27, 'seja língua alguém fala segundo dois ou o muitíssimo três e cada parte e um interprete');
INSERT INTO verses VALUES (28760, 46, 14, 28, 'se porém não seja intérprete cale-se em na-igreja si-mesmo porém fale e o a-Theos');
INSERT INTO verses VALUES (28761, 46, 14, 29, 'profetas porém dois ou três falem e o outros julguem');
INSERT INTO verses VALUES (28762, 46, 14, 30, 'se porém a-outro seja-revelado estando-sentado o primeiro cale-se');
INSERT INTO verses VALUES (28763, 46, 14, 31, 'podeis pois segundo um todos profetizar para que todos aprendam e todos sejam-consolados');
INSERT INTO verses VALUES (28764, 46, 14, 32, 'e espíritos profetas profetas sujeita-se');
INSERT INTO verses VALUES (28765, 46, 14, 33, 'não pois é desordens o Theos mas paz como em todas o assembleias o dos-santos');
INSERT INTO verses VALUES (28766, 46, 14, 34, 'o mulheres em o assembleias calem-se não pois É-permitido a-elas falar mas Sujeitem-se assim-como e o lei diz');
INSERT INTO verses VALUES (28767, 46, 14, 35, 'se e/mas algo aprender querem em na-casa o próprios homens perguntem vergonhoso pois é mulher falar em na-igreja');
INSERT INTO verses VALUES (28768, 46, 14, 36, 'ou de vosso o palavra o de-Theos saiu ou para vos somente chegou');
INSERT INTO verses VALUES (28769, 46, 14, 37, 'se alguém parece profeta ser ou espiritual reconheça o qual escrevo a-vós que do-Kyrios é mandamento');
INSERT INTO verses VALUES (28770, 46, 14, 38, 'se e/mas alguém ignora é-ignorado');
INSERT INTO verses VALUES (28771, 46, 14, 39, 'De-modo-que irmãos meu zelai o profetizar e o falar não impedis em-línguas');
INSERT INTO verses VALUES (28772, 46, 14, 40, 'todas-as-coisas porém decorosamente e segundo ordem seja');
INSERT INTO chapters VALUES (1077, 46, 15, 58);
INSERT INTO verses VALUES (28773, 46, 15, 1, 'Faço-conhecer porém a-vós irmãos o evangelho o qual evangelizei a-vós o qual e recebestes em o qual e estais-de-pé');
INSERT INTO verses VALUES (28774, 46, 15, 2, 'através-de o qual e sois-salvos a-quem em-palavra evangelizei a-vós se retende fora-de se não em-vão crestes');
INSERT INTO verses VALUES (28775, 46, 15, 3, 'entreguei pois a-vós em primeiro o qual e recebi que Christos morreu em-favor-de o dos-pecados nosso segundo o escrituras');
INSERT INTO verses VALUES (28776, 46, 15, 4, 'e que foi-sepultado e que foi-levantado o dia o no-terceiro segundo o escrituras');
INSERT INTO verses VALUES (28777, 46, 15, 5, 'e que apareceu Cefas então o doze');
INSERT INTO verses VALUES (28778, 46, 15, 6, 'depois apareceu em-cima quinhentos aos-irmãos de-uma-vez-por-todas de o qual o mais-numerosos permanecem até agora alguns porém adormeceram');
INSERT INTO verses VALUES (28779, 46, 15, 7, 'depois apareceu Jacó então o apóstolos todos');
INSERT INTO verses VALUES (28780, 46, 15, 8, 'último porém todos Como-que o aborto apareceu e-a-mim');
INSERT INTO verses VALUES (28781, 46, 15, 9, 'eu pois sou o menor o apóstolos o qual não sou digno ser-chamado apóstolo porque persegui o igreja o de-Theos');
INSERT INTO verses VALUES (28782, 46, 15, 10, 'graça porém de-Theos sou o qual sou e o graça dele o para mim não vazia aconteceu mas abundantemente deles todos trabalhei não eu porém mas o graça o de-Theos com a-mim');
INSERT INTO verses VALUES (28783, 46, 15, 11, 'seja portanto eu seja aqueles assim pregamos e assim crestes');
INSERT INTO verses VALUES (28784, 46, 15, 12, 'se porém Christos é-proclamado que de mortos foi-levantado como dizem em a-vós alguns que ressurreição mortos não é');
INSERT INTO verses VALUES (28785, 46, 15, 13, 'se porém ressurreição mortos não é nem Christos foi-levantado');
INSERT INTO verses VALUES (28786, 46, 15, 14, 'se porém Christos não foi-levantado vazio então o pregação nosso vazia e o fé vosso');
INSERT INTO verses VALUES (28787, 46, 15, 15, 'somos-encontrados porém e falsas-testemunhas o de-Theos que testemunhamos segundo o de-Theos que ressuscitou o Christos o qual não ressuscitou se-de-fato então mortos não são-levantados');
INSERT INTO verses VALUES (28788, 46, 15, 16, 'se pois mortos não são-levantados nem Christos foi-levantado');
INSERT INTO verses VALUES (28789, 46, 15, 17, 'se porém Christos não foi-levantado vã o fé vosso ainda sois em o pecados vosso');
INSERT INTO verses VALUES (28790, 46, 15, 18, 'então e o tendo-adormecido em em-Christos pereceram');
INSERT INTO verses VALUES (28791, 46, 15, 19, 'se em o vida nesta em em-Christos tendo-esperado somos somente mais-dignos-de-compaixão todos dos-homens somos');
INSERT INTO verses VALUES (28792, 46, 15, 20, 'Agora porém Christos foi-levantado de mortos primícias o tendo-adormecido');
INSERT INTO verses VALUES (28793, 46, 15, 21, 'uma-vez-que pois através-de do-homem morte e através-de do-homem ressurreição mortos');
INSERT INTO verses VALUES (28794, 46, 15, 22, 'assim-como pois em o Adão todos morrem assim e em o em-Christos todos serão-vivificados');
INSERT INTO verses VALUES (28795, 46, 15, 23, 'Cada-um porém em o próprio em-ordem primícias Christos depois o o de-Christos em o presença dele');
INSERT INTO verses VALUES (28796, 46, 15, 24, 'então o fim quando entrega o reino o a-Theos e Pai quando anule toda início e toda autoridade e poder');
INSERT INTO verses VALUES (28797, 46, 15, 25, 'é necessário pois ele reinar até o qual ponha todos o inimigos sob o pés dele');
INSERT INTO verses VALUES (28798, 46, 15, 26, 'último inimigo é-anulado o morte');
INSERT INTO verses VALUES (28799, 46, 15, 27, 'todas-as-coisas pois sujeitou sob o pés dele quando porém diga que todas-as-coisas Tem-sido-sujeitado evidente que fora-de o Tendo-sujeitado a ele o todas-as-coisas');
INSERT INTO verses VALUES (28800, 46, 15, 28, 'quando porém sujeição a ele o todas-as-coisas então e ele o Filho Será-sujeitado o Ao-que-sujeitou a ele o todas-as-coisas para que seja o Theos todas-as-coisas em todos');
INSERT INTO verses VALUES (28801, 46, 15, 29, 'Visto-que quê farão o sendo-batizados em-favor-de o mortos se totalmente mortos não são-levantados quê e são-batizados em-favor-de deles');
INSERT INTO verses VALUES (28802, 46, 15, 30, 'quê e nós corremos-perigo toda hora');
INSERT INTO verses VALUES (28803, 46, 15, 31, 'segundo dia morro por o vossa glorificação irmãos o qual tenho em em-Christos Iesous o ao-Kyrios nosso');
INSERT INTO verses VALUES (28804, 46, 15, 32, 'se segundo homem lutei-com-feras em Éfeso quê a-mim o proveito se mortos não são-levantados comamos e bebamos amanhã pois morremos');
INSERT INTO verses VALUES (28805, 46, 15, 33, 'não errais corrompem Costumes boas companhias más');
INSERT INTO verses VALUES (28806, 46, 15, 34, 'tornai-à-sobriedade justamente e não pecais ignorância pois de-Theos alguns têm junto-a vergonha a-vós falo');
INSERT INTO verses VALUES (28807, 46, 15, 35, 'mas dirá alguém como são-levantados o mortos qual porém corpo vêm');
INSERT INTO verses VALUES (28808, 46, 15, 36, 'insensato tu o qual semeias não é-vivificado se não morra');
INSERT INTO verses VALUES (28809, 46, 15, 37, 'e o qual semeias não o corpo o havendo-de-acontecer semeias mas nu grão se aconteça trigo ou de-alguém o restantes');
INSERT INTO verses VALUES (28810, 46, 15, 38, 'o porém Theos dá a ele corpo assim-como quis e a-cada-um o sementes próprio corpo');
INSERT INTO verses VALUES (28811, 46, 15, 39, 'não toda carne o ela carne mas outra por-um-lado dos-homens outra porém carne animais outra porém carne de-aves outra porém peixes');
INSERT INTO verses VALUES (28812, 46, 15, 40, 'e corpos celestiais e corpos terrenas mas outra por-um-lado o o celestiais glória outra porém o o terrenas');
INSERT INTO verses VALUES (28813, 46, 15, 41, 'outra glória sol e outra glória de-lua e outra glória estrelas estrela pois estrela difere em glória');
INSERT INTO verses VALUES (28814, 46, 15, 42, 'assim e o ressurreição o mortos é-semeado em corrupção é-levantado em incorruptibilidade');
INSERT INTO verses VALUES (28815, 46, 15, 43, 'é-semeado em desonra é-levantado em glória é-semeado em fraqueza é-levantado em poder');
INSERT INTO verses VALUES (28816, 46, 15, 44, 'é-semeado corpo natural é-levantado corpo espiritual se é corpo natural é e espiritual');
INSERT INTO verses VALUES (28817, 46, 15, 45, 'assim e está-escrito aconteceu o primeiro homem Adão para alma vivente o último Adão para espírito vivificando');
INSERT INTO verses VALUES (28818, 46, 15, 46, 'mas não primeiro o espiritual mas o natural depois o espiritual');
INSERT INTO verses VALUES (28819, 46, 15, 47, 'o primeiro homem de da-terra terreno o segundo homem de do-céu');
INSERT INTO verses VALUES (28820, 46, 15, 48, 'qual o terreno tais e o terrenos e qual o Celestial tais e o Celestiais');
INSERT INTO verses VALUES (28821, 46, 15, 49, 'e assim-como Trouxemos o imagem o do-terreno carreguemos-a-imagem e o imagem o celestial');
INSERT INTO verses VALUES (28822, 46, 15, 50, 'isto e/mas digo irmãos que carne e sangue reino de-Theos herdar não pode nem o corrupção o incorruptibilidade herda');
INSERT INTO verses VALUES (28823, 46, 15, 51, 'eis mistério a-vós digo todos não adormeceremos todos porém seremos-transformados');
INSERT INTO verses VALUES (28824, 46, 15, 52, 'em átomo em num-instante olho em o última trombeta tocará-trombeta pois e o mortos serão-levantados incorruptíveis e nós seremos-transformados');
INSERT INTO verses VALUES (28825, 46, 15, 53, 'é necessário pois o corruptível isto vestir incorruptibilidade e o mortal isto vestir imortalidade');
INSERT INTO verses VALUES (28826, 46, 15, 54, 'quando porém o corruptível isto vista-se incorruptibilidade e o mortal isto vista-se imortalidade então acontecerá o palavra o tendo-sido-escrito Foi-tragado o morte para vitória');
INSERT INTO verses VALUES (28827, 46, 15, 55, 'onde teu morte o vitória onde teu morte o aguilhão');
INSERT INTO verses VALUES (28828, 46, 15, 56, 'o porém aguilhão o da-morte o pecado o porém poder o do-pecado o lei');
INSERT INTO verses VALUES (28829, 46, 15, 57, 'o porém a-Theos graça o dando a-nós o vitória através-de o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (28830, 46, 15, 58, 'De-modo-que irmãos meu amados firmes tornai-vos inamovíveis abundando em o obra o do-Kyrios sempre sei que o labor vosso não é vazio em ao-Kyrios');
INSERT INTO chapters VALUES (1078, 46, 16, 24);
INSERT INTO verses VALUES (28831, 46, 16, 1, 'acerca-de porém o coleta o para o santos assim-como ordenei o assembleias o Galácia assim e vós fazei');
INSERT INTO verses VALUES (28832, 46, 16, 2, 'segundo uma do-sábado cada-um vosso de-junto-de si-mesmo ponha entesourando o qual algo se seja-prosperado para que não quando venha então coletas tornem-se');
INSERT INTO verses VALUES (28833, 46, 16, 3, 'quando porém eu-chegue o qual se examineis através-de cartas estes enviarei levar o graça vosso para Jerusalém');
INSERT INTO verses VALUES (28834, 46, 16, 4, 'se porém digno seja o também-a-mim ir com mim irão');
INSERT INTO verses VALUES (28835, 46, 16, 5, 'Virei porém junto-a vos quando Macedônia passe Macedônia pois passo-através');
INSERT INTO verses VALUES (28836, 46, 16, 6, 'junto-a vos porém por-acaso permanecerei ou e invernarei para que vós me envieis-adiante do-qual se vá');
INSERT INTO verses VALUES (28837, 46, 16, 7, 'não quero pois vos agora em passagem ver espero pois tempo algum permanecer junto-a vos se o Kyrios permita');
INSERT INTO verses VALUES (28838, 46, 16, 8, 'permanecerei porém em Éfeso até o Pentecostes');
INSERT INTO verses VALUES (28839, 46, 16, 9, 'porta pois a-mim tinha-aberto grande e eficaz e opondo-se muitos');
INSERT INTO verses VALUES (28840, 46, 16, 10, 'se porém venha Timóteo vede para que sem-temor aconteça junto-a vos o pois obra do-Kyrios trabalha como e-eu');
INSERT INTO verses VALUES (28841, 46, 16, 11, 'não alguém portanto ele despreze enviai-adiante porém ele em paz para que venha para me espero pois ele com o dos-irmãos');
INSERT INTO verses VALUES (28842, 46, 16, 12, 'acerca-de porém Apolo o do-irmão muitas-coisas exortei ele para que venha junto-a vos com o dos-irmãos e de-todo-modo não era vontade para que agora venha virá porém quando tenha-oportunidade');
INSERT INTO verses VALUES (28843, 46, 16, 13, 'Vigiai permanecei-firmes em o fé portai-vos-como-homens fortalecei-vos');
INSERT INTO verses VALUES (28844, 46, 16, 14, 'todas-as-coisas vosso em amor seja');
INSERT INTO verses VALUES (28845, 46, 16, 15, 'Exorto porém vos irmãos sei o casa Estéfanas que é primícias o Acaia e para serviço o santos designaram a-si-mesmos');
INSERT INTO verses VALUES (28846, 46, 16, 16, 'para que e vós Sujeiteis-vos o tais e todo o cooperando e ao-que-labuta');
INSERT INTO verses VALUES (28847, 46, 16, 17, 'alegro-me porém sobre o presença Estéfanas e Fortunato e Acaico que o vosso falta estes supriram');
INSERT INTO verses VALUES (28848, 46, 16, 18, 'deram-descanso pois o meu espírito e o vosso conheceis-plenamente portanto o tais');
INSERT INTO verses VALUES (28849, 46, 16, 19, 'Saúdam vos o assembleias o Ásia saúda vos em ao-Kyrios muitas-coisas Áquila e Prisca com o segundo casa deles na-igreja');
INSERT INTO verses VALUES (28850, 46, 16, 20, 'saúdam vos o irmãos todos Saudai uns-aos-outros em beijo no-santo');
INSERT INTO verses VALUES (28851, 46, 16, 21, 'o saudação o minha com-mão Paulo');
INSERT INTO verses VALUES (28852, 46, 16, 22, 'se alguém não ama o Kyrion seja anátema maran vem');
INSERT INTO verses VALUES (28853, 46, 16, 23, 'o graça o do-Kyrios Iesous com vosso');
INSERT INTO verses VALUES (28854, 46, 16, 24, 'o amor meu com todos vosso em em-Christos Iesous');
INSERT INTO books VALUES (47, '2CO', '2 Coríntios', 'NT', 13);
INSERT INTO chapters VALUES (1079, 47, 1, 24);
INSERT INTO verses VALUES (28855, 47, 1, 1, 'Paulo apóstolo de-Christos Iesous através-de da-vontade de-Theos e Timóteo o irmão o assembleia o de-Theos o estando em Corinto com o santos todos o estando em toda o Acaia');
INSERT INTO verses VALUES (28856, 47, 1, 2, 'graça a-vós e paz de de-Theos do-Pai nosso e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (28857, 47, 1, 3, 'Bendito o Theos e Pai o do-Kyrios nosso Iesous de-Christos o Pai o compaixões e Theos toda da-consolação');
INSERT INTO verses VALUES (28858, 47, 1, 4, 'o exortando nos sobre toda o tribulação nosso para o poder nos exortar o em toda tribulação através-de o da-consolação o qual somos-exortados eles-mesmos sob o de-Theos');
INSERT INTO verses VALUES (28859, 47, 1, 5, 'que assim-como abunda o sofrimentos o de-Christos para nos assim através-de o de-Christos abunda e o consolação nosso');
INSERT INTO verses VALUES (28860, 47, 1, 6, 'seja porém somos-afligidos em-favor-de o vosso da-consolação e salvação seja somos-exortados em-favor-de o vosso da-consolação o sendo-operada em perseverança o deles sofrimentos o qual e nós sofremos');
INSERT INTO verses VALUES (28861, 47, 1, 7, 'e o esperança nosso firme em-favor-de vosso sei que como participantes sois o sofrimentos assim e o da-consolação');
INSERT INTO verses VALUES (28862, 47, 1, 8, 'não pois queremos vos ignorar irmãos em-favor-de o tribulação nosso o tendo-acontecido em o Ásia que segundo excesso em-favor-de poder fomos-sobrecarregados de-modo-que desesperar-se nos e o viver');
INSERT INTO verses VALUES (28863, 47, 1, 9, 'mas eles-mesmos em si-mesmos o sentença o da-morte temos-tido para que não tendo-confiado sejamos sobre si-mesmos mas sobre o a-Theos o levantando o mortos');
INSERT INTO verses VALUES (28864, 47, 1, 10, 'o qual de tão-grande da-morte Livrou nos e livrará para o qual temos-esperado que e ainda livrará');
INSERT INTO verses VALUES (28865, 47, 1, 11, 'cooperando e vosso em-favor-de nosso o súplica para que de muitos de-faces o para nos dom através-de muitos seja-dada-graças em-favor-de nosso');
INSERT INTO verses VALUES (28866, 47, 1, 12, 'o pois glória nosso esta é o testemunho o consciência nosso que em santidade e sinceridade o de-Theos não em com-sabedoria carnal mas em graça de-Theos conduzimo-nos em o ao-mundo ainda-mais porém junto-a vos');
INSERT INTO verses VALUES (28867, 47, 1, 13, 'não pois outras-coisas escrevemos a-vós mas ou o qual ledes ou e conheceis-plenamente espero porém que até fim conhecereis-plenamente');
INSERT INTO verses VALUES (28868, 47, 1, 14, 'assim-como e conhecestes-plenamente nos de da-parte que orgulho vosso somos assim-como e vós nosso em o dia o do-Kyrios nosso Iesous');
INSERT INTO verses VALUES (28869, 47, 1, 15, 'e nesta o confiança desejava antes junto-a vos vir para que segunda graça tenhais');
INSERT INTO verses VALUES (28870, 47, 1, 16, 'e através-de vosso atravessar para Macedônia e novamente de Macedônia vir junto-a vos e sob vosso ser-enviado-adiante para o Judeia');
INSERT INTO verses VALUES (28871, 47, 1, 17, 'isto portanto querendo acaso então o leviandade Usei ou o qual delibero segundo carne delibero para que seja de-junto-de mim o Sim sim e o Não não');
INSERT INTO verses VALUES (28872, 47, 1, 18, 'fiel porém o Theos que o palavra nosso o junto-a vos não é sim e Não');
INSERT INTO verses VALUES (28873, 47, 1, 19, 'o o de-Theos pois Filho Christos Iesous o em a-vós através-de nosso tendo-sido-proclamado através-de mim e Silvano e Timóteo não aconteceu sim e Não mas sim em a ele aconteceu');
INSERT INTO verses VALUES (28874, 47, 1, 20, 'quanto pois promessas de-Theos em a ele o sim por-isso e através-de dele o Amém o a-Theos junto-a glória através-de nosso');
INSERT INTO verses VALUES (28875, 47, 1, 21, 'o porém confirmando nos com a-vós para Christos e tendo-ungido nos Theos');
INSERT INTO verses VALUES (28876, 47, 1, 22, 'o e tendo-selado nos e dando o penhor o do-espírito em o corações nosso');
INSERT INTO verses VALUES (28877, 47, 1, 23, 'eu porém testemunha o Theos invoco sobre o minha alma que poupando vosso não-mais vieram para Corinto');
INSERT INTO verses VALUES (28878, 47, 1, 24, 'não que dominamos vosso o da-fé mas cooperadores somos o alegria vosso o pois fé estais-de-pé');
INSERT INTO chapters VALUES (1080, 47, 2, 17);
INSERT INTO verses VALUES (28879, 47, 2, 1, 'julguei porém a-mim-mesmo isto o não novamente em tristeza junto-a vos vir');
INSERT INTO verses VALUES (28880, 47, 2, 2, 'se pois eu entristeço vos e quem o alegrando me se não o entristecendo-se de mim');
INSERT INTO verses VALUES (28881, 47, 2, 3, 'e escrevi isto ele para que não vindo tristeza tenha de o qual é necessário me alegrar-se confiando sobre todos vos que o minha alegria todos vosso é');
INSERT INTO verses VALUES (28882, 47, 2, 4, 'de pois muita tribulação e angústia do-coração escrevi a-vós através-de muitos lágrimas não para que sejais-entristecidos mas o amor para que conheçais o qual tenho ainda-mais para vos');
INSERT INTO verses VALUES (28883, 47, 2, 5, 'se e/mas alguém tem-entristecido não mim tem-entristecido mas de da-parte para que não serei-pesado-sobre todos vos');
INSERT INTO verses VALUES (28884, 47, 2, 6, 'suficiente o tal o Repreensão esta o sob o mais');
INSERT INTO verses VALUES (28885, 47, 2, 7, 'de-modo-que pelo-contrário mais vos conceder-graciosamente e consolar não como o mais-abundante tristeza seja-tragado o tal');
INSERT INTO verses VALUES (28886, 47, 2, 8, 'por-isso rogo vos confirmar para ele amor');
INSERT INTO verses VALUES (28887, 47, 2, 9, 'para isto pois e escrevi para que conheça o prova vosso se para todas-as-coisas Obedientes sois');
INSERT INTO verses VALUES (28888, 47, 2, 10, 'o qual e/mas algo perdoai eu-também e pois eu o qual tenho-concedido-graciosamente se algo tenho-concedido-graciosamente através-de vos em face de-Christos');
INSERT INTO verses VALUES (28889, 47, 2, 11, 'para que não sejamos-explorados sob o Satanás não pois dele o pensamentos ignoramos');
INSERT INTO verses VALUES (28890, 47, 2, 12, 'tendo-vindo porém para o Trôade para o evangelho o de-Christos e porta a-mim tendo-sido-aberta em ao-Kyrios');
INSERT INTO verses VALUES (28891, 47, 2, 13, 'não Tenho-tido alívio o espírito meu o não encontrar me Tito o irmão meu mas despedindo-se a-eles saíram para Macedônia');
INSERT INTO verses VALUES (28892, 47, 2, 14, 'o porém a-Theos graça o sempre triunfando nos em o em-Christos e o cheiro o do-conhecimento dele manifestando através-de nosso em todo no-lugar');
INSERT INTO verses VALUES (28893, 47, 2, 15, 'que de-Christos fragrância somos o a-Theos em o aos-sendo-salvos e em o perecendo');
INSERT INTO verses VALUES (28894, 47, 2, 16, 'o qual por-um-lado aroma de da-morte para morte o qual porém aroma de da-vida para vida e junto-a estas-coisas quem suficiente');
INSERT INTO verses VALUES (28895, 47, 2, 17, 'não pois somos como o muitos mercadejando o palavra o de-Theos mas como de sinceridade mas como de de-Theos defronte-de de-Theos em em-Christos falamos');
INSERT INTO chapters VALUES (1081, 47, 3, 18);
INSERT INTO verses VALUES (28896, 47, 3, 1, 'Começamos novamente si-mesmos recomendar ou não temos-necessidade como alguns de-recomendação cartas junto-a vos ou de vosso');
INSERT INTO verses VALUES (28897, 47, 3, 2, 'o carta nosso vós sois tendo-sido-inscrita em o corações nosso sendo-conhecida e sendo-lida sob todos dos-homens');
INSERT INTO verses VALUES (28898, 47, 3, 3, 'sendo-manifestados que sois carta de-Christos tendo-sido-servida sob nosso tendo-sido-inscrita não tinta mas Espírito de-Theos vivente não em tábuas de-pedra mas em tábuas corações carnais');
INSERT INTO verses VALUES (28899, 47, 3, 4, 'confiança porém tal temos através-de o de-Christos junto-a o Theos');
INSERT INTO verses VALUES (28900, 47, 3, 5, 'não que de deles-mesmos suficientes somos considerar algo como de deles-mesmos mas o Suficiência nosso de o de-Theos');
INSERT INTO verses VALUES (28901, 47, 3, 6, 'o qual e Capacitou nos servos nova da-aliança não letra mas do-espírito o pois letra mata o porém espírito vivifica');
INSERT INTO verses VALUES (28902, 47, 3, 7, 'se porém o ministério o da-morte em letras tendo-sido-gravada pedras aconteceu em glória de-modo-que não poder fitar-os-olhos o filhos Israel para o face Moisés através-de o glória o face dele o sendo-anulada');
INSERT INTO verses VALUES (28903, 47, 3, 8, 'como não mais o ministério o do-espírito será em glória');
INSERT INTO verses VALUES (28904, 47, 3, 9, 'se pois o ministério o condenação glória muito mais abunda o ministério o justiça glória');
INSERT INTO verses VALUES (28905, 47, 3, 10, 'e pois não tem-sido-glorificado o tendo-sido-glorificado em neste o parte por-causa-de o Excedente da-glória');
INSERT INTO verses VALUES (28906, 47, 3, 11, 'se pois o sendo-anulado através-de da-glória muito mais o permanecendo em glória');
INSERT INTO verses VALUES (28907, 47, 3, 12, 'tendo portanto tal esperança muita com-ousadia usamos');
INSERT INTO verses VALUES (28908, 47, 3, 13, 'e não assim-como Moisés Punha véu sobre o face dele junto-a o não fitar-os-olhos o filhos Israel para o fim o sendo-anulado');
INSERT INTO verses VALUES (28909, 47, 3, 14, 'mas Foi-endurecido o pensamentos deles até pois o hoje do-dia o ele véu sobre o leitura o velha da-aliança permanece não sendo-desvelado que em em-Christos é-anulado');
INSERT INTO verses VALUES (28910, 47, 3, 15, 'mas até hoje quando partícula-condicional seja-lido Moisés véu sobre o coração deles está-posto');
INSERT INTO verses VALUES (28911, 47, 3, 16, 'quando porém se converta junto-a Kyrion é-removido o véu');
INSERT INTO verses VALUES (28912, 47, 3, 17, 'o porém Kyrios o Espírito é do-qual porém o espírito do-Kyrios liberdade');
INSERT INTO verses VALUES (28913, 47, 3, 18, 'nós porém todos tendo-sido-desvelado face o glória do-Kyrios contemplando-como-em-espelho o ela imagem somos-transformados de da-glória para glória assim-como de do-Kyrios do-espírito');
INSERT INTO chapters VALUES (1082, 47, 4, 18);
INSERT INTO verses VALUES (28914, 47, 4, 1, 'através-de isto tendo o serviço esta assim-como fomos-alvos-de-misericórdia não desanimamos');
INSERT INTO verses VALUES (28915, 47, 4, 2, 'mas renunciamos o ocultas o vergonha não andando em astúcia nem adulterando o palavra o de-Theos mas o manifestação o da-verdade recomendando si-mesmos junto-a toda consciência dos-homens diante-de o de-Theos');
INSERT INTO verses VALUES (28916, 47, 4, 3, 'se porém e é tendo-sido-coberto o evangelho nosso em o perecendo é tendo-sido-coberto');
INSERT INTO verses VALUES (28917, 47, 4, 4, 'em o qual o Theos o eternidade deste cegou o pensamentos o incrédulos para o não resplandecer o iluminação o evangelho o da-glória o de-Christos o qual é imagem o de-Theos');
INSERT INTO verses VALUES (28918, 47, 4, 5, 'não pois si-mesmos pregamos mas Christos Iesous Kyrion si-mesmos porém servos vosso através-de Iesous');
INSERT INTO verses VALUES (28919, 47, 4, 6, 'que o Theos o dizendo de das-trevas luz brilhará o qual resplandeceu em o corações nosso junto-a iluminação o do-conhecimento o da-glória o de-Theos em face de-Christos');
INSERT INTO verses VALUES (28920, 47, 4, 7, 'Temos porém o tesouro este em de-barro vasos para que o Excesso o do-poder seja o de-Theos e não de nosso');
INSERT INTO verses VALUES (28921, 47, 4, 8, 'em todo sendo-atribulados mas não sendo-angustiados estando-perplexos mas não desesperando-se');
INSERT INTO verses VALUES (28922, 47, 4, 9, 'sendo-perseguidos mas não sendo-abandonados sendo-derrubados mas não perecendo');
INSERT INTO verses VALUES (28923, 47, 4, 10, 'sempre o mortificação o Iesous em o corpo carregando-ao-redor para que e o vida o Iesous em o corpo nosso seja-manifestada');
INSERT INTO verses VALUES (28924, 47, 4, 11, 'sempre pois nós o vivos para morte somos-entregues através-de Iesous para que e o vida o Iesous seja-manifestada em o mortal carne nosso');
INSERT INTO verses VALUES (28925, 47, 4, 12, 'de-modo-que o morte em a-nós é-operado o porém vida em a-vós');
INSERT INTO verses VALUES (28926, 47, 4, 13, 'tendo porém o ele espírito o da-fé segundo o escrito Cri por-isso falei e nós cremos por-isso e falamos');
INSERT INTO verses VALUES (28927, 47, 4, 14, 'sei que o tendo-levantado o Kyrion Iesous e nos com Iesous levantará e apresentará com a-vós');
INSERT INTO verses VALUES (28928, 47, 4, 15, 'o pois todas-as-coisas através-de vos para que o graça tendo-abundado através-de o mais o ação-de-graças abunde para o glória o de-Theos');
INSERT INTO verses VALUES (28929, 47, 4, 16, 'por-isso não desanimamos mas se e o fora nosso homem é-corrompido mas o dentro nosso é-renovado dia e dia');
INSERT INTO verses VALUES (28930, 47, 4, 17, 'o pois momentâneo leve o tribulação segundo excesso para excesso eterno peso da-glória opera a-nós');
INSERT INTO verses VALUES (28931, 47, 4, 18, 'não observando nosso o vistos mas o não vistos o pois vistos temporárias o porém não vistos eterna');
INSERT INTO chapters VALUES (1083, 47, 5, 21);
INSERT INTO verses VALUES (28932, 47, 5, 1, 'sei pois que se o terreno nosso casa o tenda seja-destruído edificação de de-Theos temos casa não-feito-por-mãos eterno em o nos-céus');
INSERT INTO verses VALUES (28933, 47, 5, 2, 'e pois em neste gememos o habitação nosso o de do-céu revestir-se desejando-ardentemente');
INSERT INTO verses VALUES (28934, 47, 5, 3, 'se pois e vestidos não nus seremos-encontrados');
INSERT INTO verses VALUES (28935, 47, 5, 4, 'e pois o sendo em o tenda gememos sendo-sobrecarregados sobre o qual não queremos despojar-se mas revestir-se para que seja-tragado o mortal sob o da-vida');
INSERT INTO verses VALUES (28936, 47, 5, 5, 'o porém tendo-realizado nos para ele isto Theos o dando a-nós o penhor o do-espírito');
INSERT INTO verses VALUES (28937, 47, 5, 6, 'Tendo-coragem portanto sempre e sei que estando-presentes em o corpo estamos-ausentes de o do-Kyrios');
INSERT INTO verses VALUES (28938, 47, 5, 7, 'através-de da-fé pois andamos não através-de forma');
INSERT INTO verses VALUES (28939, 47, 5, 8, 'temos-confiança porém e temos-prazer mais estar-ausente de o do-corpo e estar-em-casa junto-a o Kyrion');
INSERT INTO verses VALUES (28940, 47, 5, 9, 'por-isso e ambicionamos seja estando-presentes seja estando-ausentes agradáveis a ele ser');
INSERT INTO verses VALUES (28941, 47, 5, 10, 'o pois todos nos ser-manifestado é necessário diante o tribunal o de-Christos para que receba cada-um o através-de o do-corpo junto-a o qual praticou seja bom seja vil');
INSERT INTO verses VALUES (28942, 47, 5, 11, 'sei portanto o medo o do-Kyrios homens persuadimos a-Theos porém temos-sido-manifestados espero porém e em o consciências vosso ter-sido-manifestado');
INSERT INTO verses VALUES (28943, 47, 5, 12, 'não novamente si-mesmos recomendamos a-vós mas ocasião dando a-vós glorificação em-favor-de nosso para que tenhais junto-a o em face gloriando-se e não em no-coração');
INSERT INTO verses VALUES (28944, 47, 5, 13, 'seja pois ficamos-fora-de-nós a-Theos seja somos-sóbrios a-vós');
INSERT INTO verses VALUES (28945, 47, 5, 14, 'o pois amor o de-Christos constrange nos tendo-julgado isto que um em-favor-de todos morreu então o todos morreram');
INSERT INTO verses VALUES (28946, 47, 5, 15, 'e em-favor-de todos morreu para que o vivos não-mais si-mesmos vivam mas o em-favor-de deles ao-que-morreu e tendo-sido-levantado');
INSERT INTO verses VALUES (28947, 47, 5, 16, 'de-modo-que nós de o agora a-ninguém sei segundo carne se e temos-conhecido segundo carne Christon mas agora não-mais conhecemos');
INSERT INTO verses VALUES (28948, 47, 5, 17, 'de-modo-que se alguém em em-Christos nova criação o antigas passou eis aconteceu novas');
INSERT INTO verses VALUES (28949, 47, 5, 18, 'o porém todas-as-coisas de o de-Theos o tendo-reconciliado nos si-mesmo através-de de-Christos e tendo-dado a-nós o serviço o reconciliação');
INSERT INTO verses VALUES (28950, 47, 5, 19, 'como que Theos era em em-Christos mundo reconciliando si-mesmo não considerando a-eles o transgressões deles e tendo-posto em a-nós o palavra o reconciliação');
INSERT INTO verses VALUES (28951, 47, 5, 20, 'em-favor-de de-Christos portanto somos-embaixadores como o de-Theos do-que-consola através-de nosso suplicamos em-favor-de de-Christos sede-reconciliados o a-Theos');
INSERT INTO verses VALUES (28952, 47, 5, 21, 'o não tendo-conhecido pecado em-favor-de nosso pecado fez para que nós tornemo-nos justiça de-Theos em a ele');
INSERT INTO chapters VALUES (1084, 47, 6, 18);
INSERT INTO verses VALUES (28953, 47, 6, 1, 'Cooperando porém e exortamos não para vazio o graça o de-Theos receber vos');
INSERT INTO verses VALUES (28954, 47, 6, 2, 'diz pois Tempo aceitável ouvi teu e em dia salvação socorri a-ti eis agora tempo aceitável eis agora dia salvação');
INSERT INTO verses VALUES (28955, 47, 6, 3, 'nenhuma em a-ninguém dando tropeço para que não seja-censurado o ministério');
INSERT INTO verses VALUES (28956, 47, 6, 4, 'mas em todo recomendando si-mesmos como de-Theos servos em perseverança muita em tribulações em necessidades em angústias');
INSERT INTO verses VALUES (28957, 47, 6, 5, 'em pragas em prisões em desordens em labores em vigílias em jejuns');
INSERT INTO verses VALUES (28958, 47, 6, 6, 'em pureza em conhecimento em paciência em benignidade em Espírito no-santo em amor sem-hipocrisia');
INSERT INTO verses VALUES (28959, 47, 6, 7, 'em em-palavra da-verdade em poder de-Theos através-de o armas o justiça o direita e esquerda');
INSERT INTO verses VALUES (28960, 47, 6, 8, 'através-de da-glória e desonra através-de difamação e boa-fama como enganadores e verdadeiros');
INSERT INTO verses VALUES (28961, 47, 6, 9, 'como sendo-ignorados e sendo-reconhecidos como morrendo e eis vivamos como sendo-disciplinados e não sendo-mortos');
INSERT INTO verses VALUES (28962, 47, 6, 10, 'como entristecendo-se sempre porém alegrando-se como pobres a-muitos porém enriquecendo como nada tendo e todas-as-coisas retendo');
INSERT INTO verses VALUES (28963, 47, 6, 11, 'o boca nosso tinha-aberto junto-a vos Coríntios o coração nosso tem-sido-alargado');
INSERT INTO verses VALUES (28964, 47, 6, 12, 'não estais-angustiados em a-nós estais-angustiados porém em o entranhas vosso');
INSERT INTO verses VALUES (28965, 47, 6, 13, 'o porém ela retribuição como filhos digo alargai-vos e vós');
INSERT INTO verses VALUES (28966, 47, 6, 14, 'não tornai-vos Pondo-se-em-jugo-desigual incrédulos quem pois participação justiça e iniquidade ou quem comunhão luz junto-a trevas');
INSERT INTO verses VALUES (28967, 47, 6, 15, 'quem porém concordância de-Christos junto-a Beliar ou quem porção fiel com incrédulo');
INSERT INTO verses VALUES (28968, 47, 6, 16, 'quem porém acordo templo de-Theos com ídolos nós pois templo de-Theos somos vivente assim-como disse o Theos que Habitarei-em em a-eles e andarei-em e serei deles Theos e eles-mesmos serão meu povo');
INSERT INTO verses VALUES (28969, 47, 6, 17, 'por-isso saí de meio deles e sede-separados diz Kyrios e impuro não toqueis e-eu receberei vos');
INSERT INTO verses VALUES (28970, 47, 6, 18, 'e serei a-vós para Pai e vós sereis a-mim para filhos e filhas diz Kyrios Todo-Poderoso');
INSERT INTO chapters VALUES (1085, 47, 7, 16);
INSERT INTO verses VALUES (28971, 47, 7, 1, 'estas portanto tendo o promessa amados purifiquemo-nos si-mesmos de de-todo contaminação carne e do-espírito completando santidade em medo de-Theos');
INSERT INTO verses VALUES (28972, 47, 7, 2, 'Dai-lugar nos a-ninguém cometemos-injustiça a-ninguém Corrompemos a-ninguém Exploramos');
INSERT INTO verses VALUES (28973, 47, 7, 3, 'junto-a condenação não digo predisse pois que em o corações nosso sois para o morrer-junto e co-viver');
INSERT INTO verses VALUES (28974, 47, 7, 4, 'muita a-mim ousadia junto-a vos muita a-mim glória em-favor-de vosso tenho-sido-preenchido o consolação Superabundo o alegria sobre toda o tribulação nosso');
INSERT INTO verses VALUES (28975, 47, 7, 5, 'e pois tendo-vindo nosso para Macedônia nenhuma Tem-tido alívio o carne nosso mas em todo sendo-atribulados de-fora contendas por-dentro temores');
INSERT INTO verses VALUES (28976, 47, 7, 6, 'mas o exortando o humildes exortou nos o Theos em o presença Tito');
INSERT INTO verses VALUES (28977, 47, 7, 7, 'não somente porém em o presença dele mas e em o consolação o qual foi-consolado sobre a-vós anunciando a-nós o vosso desejo-ardente o vosso lamento o vosso zelo em-favor-de mim de-modo-que me mais alegrar-se');
INSERT INTO verses VALUES (28978, 47, 7, 8, 'que se e entristeci vos em o carta não arrependo-me se e arrependia-me vejo que o carta aquela se e junto-a hora entristeceu vos');
INSERT INTO verses VALUES (28979, 47, 7, 9, 'agora alegro-me não que fostes-entristecidos mas que fostes-entristecidos para arrependimento fostes-entristecidos pois segundo Theos para que em a-ninguém sofrais-perda de nosso');
INSERT INTO verses VALUES (28980, 47, 7, 10, 'o pois segundo Theos tristeza arrependimento para salvação irrevogável trabalha o porém o do-mundo tristeza morte opera');
INSERT INTO verses VALUES (28981, 47, 7, 11, 'eis pois ele isto o segundo Theos ser-entristecido quanta produziu a-vós diligência mas defesa mas indignação mas medo mas desejo-ardente mas zelo mas vingança em todo recomendaste si-mesmos puros ser o assunto');
INSERT INTO verses VALUES (28982, 47, 7, 12, 'então se e escrevi a-vós não por-causa-de o tendo-sido-injusto nem por-causa-de o tendo-sido-injustiçado mas por-causa-de o ser-manifestado o diligência vosso o em-favor-de nosso junto-a vos diante-de o de-Theos');
INSERT INTO verses VALUES (28983, 47, 7, 13, 'através-de isto temos-sido-consolados sobre porém o consolação nosso ainda-mais mais Alegramo-nos sobre o alegria Tito que tem-descansado o espírito dele de todos vosso');
INSERT INTO verses VALUES (28984, 47, 7, 14, 'que se algo a ele em-favor-de vosso tenho-me-gloriado não fui-envergonhado mas como todas-as-coisas em verdade falamos a-vós assim e o glória nosso sobre Tito verdade aconteceu');
INSERT INTO verses VALUES (28985, 47, 7, 15, 'e o entranhas dele ainda-mais para vos é lembrando-se o todos vosso obediência como com medo e tremor recebestes ele');
INSERT INTO verses VALUES (28986, 47, 7, 16, 'alegro-me que em todo tenho-ânimo em a-vós');
INSERT INTO chapters VALUES (1086, 47, 8, 24);
INSERT INTO verses VALUES (28987, 47, 8, 1, 'Fazemos-conhecer porém a-vós irmãos o graça o de-Theos o tendo-sido-dada em o assembleias o Macedônia');
INSERT INTO verses VALUES (28988, 47, 8, 2, 'que em muita prova tribulação o abundância o alegria deles e o segundo profundidade pobreza deles abundou para o riqueza o simplicidade deles');
INSERT INTO verses VALUES (28989, 47, 8, 3, 'que segundo poder testemunho e de-junto-de poder por-vontade-própria');
INSERT INTO verses VALUES (28990, 47, 8, 4, 'com muita da-consolação suplicando nosso o graça e o comunhão o ministério o para o santos');
INSERT INTO verses VALUES (28991, 47, 8, 5, 'e não assim-como esperamos mas si-mesmos deram primeiro o ao-Kyrios e a-nós através-de da-vontade de-Theos');
INSERT INTO verses VALUES (28992, 47, 8, 6, 'para o consolar nos Tito para que assim-como começou-de-antemão assim e Complete para vos e o graça esta');
INSERT INTO verses VALUES (28993, 47, 8, 7, 'mas assim-como em todo abundais fé e em-palavra e conhecimento e toda diligência e o de nosso em a-vós amor para que e em nesta o graça abundeis');
INSERT INTO verses VALUES (28994, 47, 8, 8, 'não segundo mandado digo mas através-de o outros diligência e o o vossa do-amor genuíno examinando');
INSERT INTO verses VALUES (28995, 47, 8, 9, 'sabeis pois o graça o do-Kyrios nosso Iesous de-Christos que através-de vos Empobreceu rico sendo para que vós o daquele em-pobreza enriqueçais');
INSERT INTO verses VALUES (28996, 47, 8, 10, 'e opinião em neste dou isto pois a-vós convém os-quais não somente o fazer mas e o querer começastes-de-antemão de desde-o-ano-passado');
INSERT INTO verses VALUES (28997, 47, 8, 11, 'agora porém e o fazer Completai para-que assim-como o prontidão o querer assim e o Completar de o ter');
INSERT INTO verses VALUES (28998, 47, 8, 12, 'se pois o prontidão está-exposto conforme se tenha aceitável não conforme não tem');
INSERT INTO verses VALUES (28999, 47, 8, 13, 'não pois para que a-outros alívio a-vós tribulação mas de Igualdade');
INSERT INTO verses VALUES (29000, 47, 8, 14, 'em o agora tempo o vosso abundância para o daqueles falta para que e o daqueles abundância aconteça para o vosso falta para-que aconteça igualdade');
INSERT INTO verses VALUES (29001, 47, 8, 15, 'assim-como está-escrito o o muito não abundou e o o pouco não teve-falta');
INSERT INTO verses VALUES (29002, 47, 8, 16, 'graça porém o a-Theos o dando o ela diligência em-favor-de vosso em o no-coração Tito');
INSERT INTO verses VALUES (29003, 47, 8, 17, 'que o por-um-lado consolação recebeu mais-diligente porém sendo por-vontade-própria saiu junto-a vos');
INSERT INTO verses VALUES (29004, 47, 8, 18, 'enviamos-junto porém com dele o irmão o qual o louvor em o no-evangelho através-de todas o igrejas');
INSERT INTO verses VALUES (29005, 47, 8, 19, 'não somente porém mas e tendo-sido-escolhido-por-mãos-estendidas sob o igrejas com-viajante nosso em o graça nesta o sendo-servida sob nosso junto-a o dele o do-Kyrios glória e prontidão nosso');
INSERT INTO verses VALUES (29006, 47, 8, 20, 'afastando-se isto não alguém nos seja-censurado em o abundância nesta o sendo-servida sob nosso');
INSERT INTO verses VALUES (29007, 47, 8, 21, 'cuidamos pois boas não somente diante-de do-Kyrios mas e diante-de dos-homens');
INSERT INTO verses VALUES (29008, 47, 8, 22, 'enviamos-junto porém a-eles o irmão nosso o qual fomos-aprovados em muitos muitas-vezes diligente sendo agora porém muito mais-diligente confiança muita o para vos');
INSERT INTO verses VALUES (29009, 47, 8, 23, 'seja em-favor-de Tito participante meu e para vos cooperador seja irmãos nosso apóstolos igrejas glória de-Christos');
INSERT INTO verses VALUES (29010, 47, 8, 24, 'o portanto demonstração o do-amor vosso e nosso glorificação em-favor-de vosso para eles mostrando para face o igrejas');
INSERT INTO chapters VALUES (1087, 47, 9, 15);
INSERT INTO verses VALUES (29011, 47, 9, 1, 'acerca-de por-um-lado pois o ministério o para o santos abundante me é o escrever a-vós');
INSERT INTO verses VALUES (29012, 47, 9, 2, 'sei pois o prontidão vosso o qual em-favor-de vosso glorio-me Macedônios que Acaia tem-sido-preparado de desde-o-ano-passado e o vosso zelo provocou o mais');
INSERT INTO verses VALUES (29013, 47, 9, 3, 'enviei porém o irmãos para que não o orgulho nosso o em-favor-de vosso seja-esvaziada em o parte neste para que assim-como diziam tendo-sido-preparados éreis');
INSERT INTO verses VALUES (29014, 47, 9, 4, 'não como se venham com mim Macedônios e encontrem vos despreparados sejamos-envergonhados nós para que não digamos vós em o confiança nesta');
INSERT INTO verses VALUES (29015, 47, 9, 5, 'necessário portanto considerei consolar o irmãos para que avancem para vos e preparem-de-antemão o tendo-sido-prometida-de-antemão bênção vosso esta preparada ser assim como bênção e não como ganância');
INSERT INTO verses VALUES (29016, 47, 9, 6, 'isto e/mas o o-que-semeia poupadamente poupadamente e ceifará e o o-que-semeia sobre bênçãos sobre bênçãos e ceifará');
INSERT INTO verses VALUES (29017, 47, 9, 7, 'cada-um assim-como tem-escolhido-de-antemão o no-coração não de tristeza ou de necessidade Alegre pois dador ama o Theos');
INSERT INTO verses VALUES (29018, 47, 9, 8, 'é-poderoso porém o Theos toda graça abundar para vos para que em todo sempre toda suficiência tendo abundeis para todo obra bom');
INSERT INTO verses VALUES (29019, 47, 9, 9, 'assim-como está-escrito Espalhou deu o pobres o justiça dele permanece para o eternidade');
INSERT INTO verses VALUES (29020, 47, 9, 10, 'o porém suprindo semente o semeando e pão para comida suprirá e multiplicará o semente vosso e fará-crescer o frutos o da-justiça vosso');
INSERT INTO verses VALUES (29021, 47, 9, 11, 'em todo sendo-enriquecidos para toda simplicidade a-qual opera através-de nosso ação-de-graças o a-Theos');
INSERT INTO verses VALUES (29022, 47, 9, 12, 'que o ministério o serviço desta não somente é suprindo o carências o santos mas e abundando através-de muitos ações-de-graças o a-Theos');
INSERT INTO verses VALUES (29023, 47, 9, 13, 'através-de o prova o ministério desta glorificando o Theos sobre o sujeição o confissão vosso para o evangelho o de-Christos e simplicidade o comunhão para eles e para todos');
INSERT INTO verses VALUES (29024, 47, 9, 14, 'e deles súplica em-favor-de vosso desejando-ardentemente vos através-de o excedente graça o de-Theos sobre a-vós');
INSERT INTO verses VALUES (29025, 47, 9, 15, 'graça o a-Theos sobre o inexprimível dele dom');
INSERT INTO chapters VALUES (1088, 47, 10, 18);
INSERT INTO verses VALUES (29026, 47, 10, 1, 'ele porém eu Paulo rogo vos através-de o mansidão e moderação o de-Christos o qual segundo face por-um-lado humilde em a-vós estando-ausente porém tenho-ânimo para vos');
INSERT INTO verses VALUES (29027, 47, 10, 2, 'suplico porém o não estando-presente ter-confiança o confiança o qual considero ousar sobre alguns o considerando nos como segundo carne andando');
INSERT INTO verses VALUES (29028, 47, 10, 3, 'em carne pois andando não segundo carne guerreamos');
INSERT INTO verses VALUES (29029, 47, 10, 4, 'o pois armas o guerra nosso não carnais mas possíveis o a-Theos junto-a destruição fortalezas raciocínios demolindo');
INSERT INTO verses VALUES (29030, 47, 10, 5, 'e todo altivez sendo-levantado segundo o do-conhecimento o de-Theos e levando-cativos todo pensamento para o obediência o de-Christos');
INSERT INTO verses VALUES (29031, 47, 10, 6, 'e em Preparado tendo vingar toda desobediência quando seja-cumprido vosso o Obediência');
INSERT INTO verses VALUES (29032, 47, 10, 7, 'o segundo face vede se alguém tem-confiado si-mesmo de-Christos ser isto considere novamente sobre si-mesmo que assim-como ele de-Christos assim e nós');
INSERT INTO verses VALUES (29033, 47, 10, 8, 'se e pois mais-abundantemente algo me-glorie acerca-de o da-autoridade nosso o qual deu o Kyrios para edificação e não para destruição vosso não serei-envergonhado');
INSERT INTO verses VALUES (29034, 47, 10, 9, 'para que não glorificarei como partícula-condicional amedrontar vos através-de o cartas');
INSERT INTO verses VALUES (29035, 47, 10, 10, 'que o cartas de-fato diz pesadas e Fortes o porém presença o do-corpo fraco e o palavra tendo-sido-desprezado');
INSERT INTO verses VALUES (29036, 47, 10, 11, 'isto considere o tal que quais somos o em-palavra através-de cartas estando-ausentes tais e estando-presentes o obra');
INSERT INTO verses VALUES (29037, 47, 10, 12, 'não pois ousamos classificar-entre ou comparar a-si-mesmos alguns o si-mesmos recomendando mas eles-mesmos em si-mesmos si-mesmos medindo e comparando si-mesmos si-mesmos não compreendem');
INSERT INTO verses VALUES (29038, 47, 10, 13, 'nós porém não para o desmedidas gloriar-nos-emos mas segundo o medida o regra o qual dividiu a-nós o Theos medida Alcançar até e vosso');
INSERT INTO verses VALUES (29039, 47, 10, 14, 'não pois como não Alcançando para vos Estendemo-nos-além a-si-mesmos até pois e vosso chegamos em o no-evangelho o de-Christos');
INSERT INTO verses VALUES (29040, 47, 10, 15, 'não para o desmedidas gloriando-se em alheios labores esperança porém tendo crescendo o da-fé vosso em a-vós ser-engrandecido segundo o regra nosso para abundância');
INSERT INTO verses VALUES (29041, 47, 10, 16, 'para o Além-de vosso evangelizar não em estranho regra para o preparadas ter-se-gloriado');
INSERT INTO verses VALUES (29042, 47, 10, 17, 'o porém gloriando-se em ao-Kyrios glorie-se');
INSERT INTO verses VALUES (29043, 47, 10, 18, 'não pois o si-mesmo recomendando aquele é aprovado mas o qual o Kyrios recomenda');
INSERT INTO chapters VALUES (1089, 47, 11, 33);
INSERT INTO verses VALUES (29044, 47, 11, 1, 'oxalá suportáveis meu pouco algo insensatez mas e suportais meu');
INSERT INTO verses VALUES (29045, 47, 11, 2, 'zelo pois vos de-Theos zelo desposei pois vos um marido virgem pura apresentar o em-Christos');
INSERT INTO verses VALUES (29046, 47, 11, 3, 'temo porém não como como o serpente enganou Eva em o astúcia dele seja-corrompido o pensamentos vosso de o simplicidade e o pureza o para Christon');
INSERT INTO verses VALUES (29047, 47, 11, 4, 'se por-um-lado pois o vindo outro Iesous proclama o qual não proclamamos ou espírito outro recebeis o qual não recebestes ou evangelho outro o qual não recebestes bem suportais');
INSERT INTO verses VALUES (29048, 47, 11, 5, 'considero pois nada ter-faltado o super-eminentes apóstolos');
INSERT INTO verses VALUES (29049, 47, 11, 6, 'se porém e leigo o em-palavra mas não o conhecimento mas em todo tendo-manifestado em todos para vos');
INSERT INTO verses VALUES (29050, 47, 11, 7, 'ou pecado fiz a-mim-mesmo humildes para que vós sede-exaltados que gratuitamente o o de-Theos evangelho evangelizei a-vós');
INSERT INTO verses VALUES (29051, 47, 11, 8, 'outras da-assembleia Despojei tomando soldo junto-a o vosso serviço');
INSERT INTO verses VALUES (29052, 47, 11, 9, 'e estando-presente junto-a vos e Tendo-faltado não fui-peso nenhum o pois Falta meu supriram o irmãos vindo de Macedônia e em todo sem-peso a-mim-mesmo a-vós Guardei e guardarei');
INSERT INTO verses VALUES (29053, 47, 11, 10, 'é verdade de-Christos em mim que o glória esta não será-fechada para mim em o regiões o Acaia');
INSERT INTO verses VALUES (29054, 47, 11, 11, 'através-de quê que não amo vos o Theos sei');
INSERT INTO verses VALUES (29055, 47, 11, 12, 'o qual porém faço e farei para que cortarei-fora o ocasião o dos-que-querem ocasião para que em o qual gloriam-se sejam-encontrados assim-como e nós');
INSERT INTO verses VALUES (29056, 47, 11, 13, 'o pois tais falsos-apóstolos trabalhadores enganosos transfigurando-se para apóstolos de-Christos');
INSERT INTO verses VALUES (29057, 47, 11, 14, 'e não maravilha ele pois o Satanás transfigura-se para anjo luz');
INSERT INTO verses VALUES (29058, 47, 11, 15, 'não grande portanto se e o servos dele transfiguram-se como servos justiça o qual o fim será segundo o obra deles');
INSERT INTO verses VALUES (29059, 47, 11, 16, 'novamente digo não quem me glória insensato ser se porém de-outro-modo e-se como insensato recebei me para que e-eu pouco algo me-glorie');
INSERT INTO verses VALUES (29060, 47, 11, 17, 'o qual falo não segundo Kyrion falo mas como em insensatez em nesta o confiança o glorificação');
INSERT INTO verses VALUES (29061, 47, 11, 18, 'porque muitos gloriam-se segundo o carne e-eu gloriar-me-ei');
INSERT INTO verses VALUES (29062, 47, 11, 19, 'prazerosamente pois suportais o insensatos prudentes sendo');
INSERT INTO verses VALUES (29063, 47, 11, 20, 'suportais pois se alguém vos escraviza se alguém devora se alguém recebe se alguém levanta-se se alguém para face vos bate');
INSERT INTO verses VALUES (29064, 47, 11, 21, 'segundo desonra digo como que nós Temos-enfraquecido em o qual e/mas se alguém ousa em insensatez digo ouso eu-também');
INSERT INTO verses VALUES (29065, 47, 11, 22, 'Hebreus são eu-também Israelitas são eu-também semente Abraão são eu-também');
INSERT INTO verses VALUES (29066, 47, 11, 23, 'servos de-Christos são sendo-louco falo em-favor-de eu em labores ainda-mais em prisões ainda-mais em pragas Excedentemente em mortes muitas-vezes');
INSERT INTO verses VALUES (29067, 47, 11, 24, 'sob judeus cinco-vezes quarenta de-junto-de uma receberam');
INSERT INTO verses VALUES (29068, 47, 11, 25, 'três-vezes Fui-açoitado-com-varas uma-vez fui-apedrejado três-vezes naufragei noite-e-dia em o abismo tenho-feito');
INSERT INTO verses VALUES (29069, 47, 11, 26, 'jornadas muitas-vezes perigos rios perigos ladrões perigos de raça perigos de nações perigos em cidade perigos em deserto perigos em mar perigos em falsos-irmãos');
INSERT INTO verses VALUES (29070, 47, 11, 27, 'labor e labor em vigílias muitas-vezes em fome e sede em jejuns muitas-vezes em esfria e nudez');
INSERT INTO verses VALUES (29071, 47, 11, 28, 'sem o exceto o conspiração a-mim o segundo dia o preocupação todas o igrejas');
INSERT INTO verses VALUES (29072, 47, 11, 29, 'quem está-fraco e não estou-fraco quem é-escandalizado e não eu sou-inflamado');
INSERT INTO verses VALUES (29073, 47, 11, 30, 'se gloriar-se é necessário o o fraqueza meu gloriar-me-ei');
INSERT INTO verses VALUES (29074, 47, 11, 31, 'o Theos e Pai o do-Kyrios Iesous sei o sendo bendito para o eras que não minto');
INSERT INTO verses VALUES (29075, 47, 11, 32, 'em Damasco o etnarca Aretas o rei Guardava o cidade Damascenos prender me');
INSERT INTO verses VALUES (29076, 47, 11, 33, 'e através-de janela em em-cesto Fui-descido através-de o muro e escaparam o mãos dele');
INSERT INTO chapters VALUES (1090, 47, 12, 21);
INSERT INTO verses VALUES (29077, 47, 12, 1, 'Gloriar-se é necessário não conveniente de-fato virei porém para visão e revelações do-Kyrios');
INSERT INTO verses VALUES (29078, 47, 12, 2, 'sei homem em em-Christos antes-de anos quatorze seja em corpo não sei seja fora-de o do-corpo não sei o Theos sei tendo-sido-arrebatado o tal até terceiro do-céu');
INSERT INTO verses VALUES (29079, 47, 12, 3, 'e sei o tal homem seja em corpo seja sem o do-corpo não sei o Theos sei');
INSERT INTO verses VALUES (29080, 47, 12, 4, 'que Foi-arrebatado para o Paraíso e ouviu indizíveis palavras o qual não sendo-lícito ser-humano falar');
INSERT INTO verses VALUES (29081, 47, 12, 5, 'em-favor-de o tal gloriar-me-ei em-favor-de porém de-mim-mesmo não gloriar-me-ei se não em o fraquezas');
INSERT INTO verses VALUES (29082, 47, 12, 6, 'se pois quererei ter-se-gloriado não serei insensato verdade pois direi poupo e/mas não alguém para mim considere em-favor-de o qual vê me ou ouve de mim');
INSERT INTO verses VALUES (29083, 47, 12, 7, 'e o Excesso o revelações por-isso para que não me-exalte foi-dado a-mim espinho o na-carne anjo Satanás para que me esbofeteie para que não me-exalte');
INSERT INTO verses VALUES (29084, 47, 12, 8, 'em-favor-de deste três-vezes o Kyrion exortei para que afaste-se de mim');
INSERT INTO verses VALUES (29085, 47, 12, 9, 'e tem-dito a-mim Basta a-ti o graça meu o pois poder em fraqueza é-completado Muito-prazerosamente portanto mais gloriar-me-ei em o fraquezas para que habite-sobre sobre mim o poder o de-Christos');
INSERT INTO verses VALUES (29086, 47, 12, 10, 'por-isso comprazo-me em fraquezas em Ultrajes em necessidades em perseguições e angústias em-favor-de de-Christos quando pois estou-fraco então poderoso sou');
INSERT INTO verses VALUES (29087, 47, 12, 11, 'Tenho-me-tornado insensato vós me forçastes eu pois Devia sob vosso recomendar-se nada pois Faltei o super-eminentes apóstolos se e nada sou');
INSERT INTO verses VALUES (29088, 47, 12, 12, 'o por-um-lado sinais o apóstolo foi-realizado em a-vós em toda perseverança sinais e e prodígios e poderes');
INSERT INTO verses VALUES (29089, 47, 12, 13, 'quê pois é o qual fostes-inferiorizados em-favor-de o restantes da-assembleia se não que ele eu não fui-peso vosso perdoai a-mim o injustiça esta');
INSERT INTO verses VALUES (29090, 47, 12, 14, 'Eis terço isto prontamente tenho vir junto-a vos e não serei-peso não pois busco o vosso mas vos não pois deve o filhos o pais entesourar mas o pais o filhos');
INSERT INTO verses VALUES (29091, 47, 12, 15, 'eu porém Com-muito-prazer gastarei e serei-totalmente-gasto em-favor-de o almas vosso se ainda-mais vos amo menos sou-amado');
INSERT INTO verses VALUES (29092, 47, 12, 16, 'Seja e/mas eu não fui-peso vos mas sendo astuto engano vos receberam');
INSERT INTO verses VALUES (29093, 47, 12, 17, 'não alguém o qual tenho-enviado junto-a vos através-de dele Explorei vos');
INSERT INTO verses VALUES (29094, 47, 12, 18, 'exortei Tito e enviei-junto o irmão acaso Explorou vos Tito não o a ele Espírito andamos não o a-eles pegadas');
INSERT INTO verses VALUES (29095, 47, 12, 19, 'Desde-há-muito pensais que a-vós defendemo-nos defronte-de de-Theos em em-Christos falamos o porém todas-as-coisas amados em-favor-de o vosso edificação');
INSERT INTO verses VALUES (29096, 47, 12, 20, 'temo pois não como vindo não quais quero encontre vos e-eu seja-encontrado a-vós qual não quereis não como contenda zelo iras contendas maledicências murmurações inchações desordens');
INSERT INTO verses VALUES (29097, 47, 12, 21, 'não novamente tendo-vindo meu humilhe me o Theos meu junto-a vos e lamentarei a-muitos o tendo-pecado-antes e não tendo-se-arrependido sobre o impureza e imoralidade e devassidão o qual Praticaram');
INSERT INTO chapters VALUES (1091, 47, 13, 13);
INSERT INTO verses VALUES (29098, 47, 13, 1, 'terço isto venho junto-a vos sobre boca dois testemunhas e três será-estabelecido todo palavra');
INSERT INTO verses VALUES (29099, 47, 13, 2, 'predisse e digo-de-antemão como estando-presente o segundo e estando-ausente agora o tendo-pecado-antes e o restantes todos que se venha para o novamente não pouparei');
INSERT INTO verses VALUES (29100, 47, 13, 3, 'porque prova buscais o em mim falando de-Christos o qual para vos não está-fraco mas é-poderoso em a-vós');
INSERT INTO verses VALUES (29101, 47, 13, 4, 'e pois foi-crucificado de fraqueza mas vive de do-poder de-Theos e pois nós somos-fracos em a ele mas viveremos com a ele de do-poder de-Theos para vos');
INSERT INTO verses VALUES (29102, 47, 13, 5, 'a-si-mesmos tentais se sois em o fé si-mesmos examinai ou não conheceis-plenamente si-mesmos que Iesous Christos em a-vós se acaso reprovados sois');
INSERT INTO verses VALUES (29103, 47, 13, 6, 'espero porém que conhecereis que nós não somos reprovados');
INSERT INTO verses VALUES (29104, 47, 13, 7, 'oramos porém junto-a o Theos não fazer vos mau nada não para que nós aprovados apareçamos mas para que vós o belo façais nós porém como reprovados sejamos');
INSERT INTO verses VALUES (29105, 47, 13, 8, 'não pois podemos algo segundo o da-verdade mas em-favor-de o da-verdade');
INSERT INTO verses VALUES (29106, 47, 13, 9, 'alegramo-nos pois quando nós sejamos-fracos vós porém poderosos éreis isto e oramos o vosso aperfeiçoamento');
INSERT INTO verses VALUES (29107, 47, 13, 10, 'através-de isto estas-coisas estando-ausente escrever para que estando-presente não severamente eu-use segundo o autoridade o qual o Kyrios Deu a-mim para edificação e não para destruição');
INSERT INTO verses VALUES (29108, 47, 13, 11, 'Quanto-ao-resto irmãos alegrai-vos sede-restaurados sois-consolados o ele pensais tende-paz e o Theos o do-amor e paz será com vosso');
INSERT INTO verses VALUES (29109, 47, 13, 12, 'Saudai uns-aos-outros em no-santo beijo Saúdam vos o santos todos');
INSERT INTO verses VALUES (29110, 47, 13, 13, 'o graça o do-Kyrios Iesous de-Christos e o amor o de-Theos e o comunhão o do-santo do-espírito com todos vosso');
INSERT INTO books VALUES (48, 'GAL', 'Gálatas', 'NT', 6);
INSERT INTO chapters VALUES (1092, 48, 1, 24);
INSERT INTO verses VALUES (29111, 48, 1, 1, 'Paulo apóstolo não de dos-homens nem através-de do-homem mas através-de Iesous de-Christos e de-Theos do-Pai o tendo-levantado ele de mortos');
INSERT INTO verses VALUES (29112, 48, 1, 2, 'e o com mim todos irmãos o assembleias o Galácia');
INSERT INTO verses VALUES (29113, 48, 1, 3, 'graça a-vós e paz de de-Theos do-Pai nosso e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (29114, 48, 1, 4, 'o tendo-dado si-mesmo em-favor-de o pecados nosso para-que livre nos de o eternidade o tendo-se-apresentado do-mal segundo o vontade o de-Theos e do-Pai nosso');
INSERT INTO verses VALUES (29115, 48, 1, 5, 'o qual o glória para o eras o eras amém');
INSERT INTO verses VALUES (29116, 48, 1, 6, 'admiro-me que assim rapidamente transferis-vos de o chamante vos em graça de-Christos para outro evangelho');
INSERT INTO verses VALUES (29117, 48, 1, 7, 'o qual não é outro se não alguns são o perturbando vos e querendo converter o evangelho o de-Christos');
INSERT INTO verses VALUES (29118, 48, 1, 8, 'mas e se nós ou anjo de do-céu anuncie-boas-novas a-vós de o qual anunciamos-boas-novas a-vós anátema seja');
INSERT INTO verses VALUES (29119, 48, 1, 9, 'como temos-dito-de-antemão e agora novamente digo se alguém vos anuncia-boa-nova de o qual recebestes anátema seja');
INSERT INTO verses VALUES (29120, 48, 1, 10, 'Agora pois homens persuado ou o Theos ou busco aos-homens agradar se ainda aos-homens Agradavam de-Christos servo não partícula-condicional eu-era');
INSERT INTO verses VALUES (29121, 48, 1, 11, 'faço-conhecer pois a-vós irmãos o evangelho o tendo-sido-anunciado-como-boa-nova sob mim que não é segundo homem');
INSERT INTO verses VALUES (29122, 48, 1, 12, 'nem pois eu de-junto-de do-homem recebi isso nem fui-ensinado mas através-de revelação Iesous de-Christos');
INSERT INTO verses VALUES (29123, 48, 1, 13, 'Ouvistes pois o minha conduta alguma-vez em o Judaísmo que segundo excesso perseguiam o igreja o de-Theos e Devastavam ela');
INSERT INTO verses VALUES (29124, 48, 1, 14, 'e progredia em o Judaísmo em-favor-de a-muitos contemporâneos em o raça meu ainda-mais zeloso sendo o paternais meu de-tradições');
INSERT INTO verses VALUES (29125, 48, 1, 15, 'quando porém agradou-se o tendo-separado me de ventre mãe meu e chamando através-de o da-graça dele');
INSERT INTO verses VALUES (29126, 48, 1, 16, 'revelar o Filho dele em mim para que anuncie-boa-nova ele em o nações imediatamente não consultei carne e sangue');
INSERT INTO verses VALUES (29127, 48, 1, 17, 'nem subi para Jerusalém junto-a o antes-de mim apóstolos mas foram para Arábia e novamente Retornei para Damasco');
INSERT INTO verses VALUES (29128, 48, 1, 18, 'Depois com três anos subi para Jerusalém Visitar Cefas e permaneci junto-a ele do-dia quinze');
INSERT INTO verses VALUES (29129, 48, 1, 19, 'outro porém o apóstolos não vi se não Tiago o irmão o do-Kyrios');
INSERT INTO verses VALUES (29130, 48, 1, 20, 'o qual porém escrever a-vós eis diante-de o de-Theos que não minto');
INSERT INTO verses VALUES (29131, 48, 1, 21, 'depois vieram para o regiões o Síria e o Cilícia');
INSERT INTO verses VALUES (29132, 48, 1, 22, 'eu-era porém sendo-ignorado o face o assembleias o Judeia o em em-Christos');
INSERT INTO verses VALUES (29133, 48, 1, 23, 'somente porém ouvindo eram que o perseguindo nos alguma-vez agora anuncia-boa-nova o fé o qual alguma-vez Devastava');
INSERT INTO verses VALUES (29134, 48, 1, 24, 'e glorificavam em mim o Theos');
INSERT INTO chapters VALUES (1093, 48, 2, 21);
INSERT INTO verses VALUES (29135, 48, 2, 1, 'Depois através-de quatorze anos novamente subi para Jerusalém com Barnabé tendo-levado-consigo e Tito');
INSERT INTO verses VALUES (29136, 48, 2, 2, 'subi porém segundo revelação e expus a-eles o evangelho o qual proclamo em o nações segundo própria porém o parecem não como para vazio corro ou correram');
INSERT INTO verses VALUES (29137, 48, 2, 3, 'mas nem Tito o com me grego sendo foi-forçado ser-circuncidado');
INSERT INTO verses VALUES (29138, 48, 2, 4, 'através-de porém o introduzidos-secretamente falsos-irmãos os-quais entraram-secretamente espiar o liberdade nosso o qual temos em em-Christos Iesous para que nos escravizarão');
INSERT INTO verses VALUES (29139, 48, 2, 5, 'o qual nem junto-a hora cedemos o sujeição para que o verdade o evangelho permaneça junto-a vos');
INSERT INTO verses VALUES (29140, 48, 2, 6, 'de porém o parecendo ser algo quais alguma-vez eram nada a-mim difere face o Theos do-homem não recebe mim pois o parecendo nada consultaram');
INSERT INTO verses VALUES (29141, 48, 2, 7, 'mas pelo-contrário vendo que tenho-sido-confiado o evangelho o incircuncisão assim-como Pedro o da-circuncisão');
INSERT INTO verses VALUES (29142, 48, 2, 8, 'o pois tendo-operado a-Pedro para apostolado o da-circuncisão operou e mim para o nações');
INSERT INTO verses VALUES (29143, 48, 2, 9, 'e conhecendo o graça o dada a-mim Tiago e Cefas e João o parecendo coluna ser direitas deram mim e Barnabé comunhão para que nós para o nações eles-mesmos porém para o circuncisão');
INSERT INTO verses VALUES (29144, 48, 2, 10, 'somente o pobres para que lembremos o qual e Esforcei-me ele isto fazer');
INSERT INTO verses VALUES (29145, 48, 2, 11, 'quando porém veio Cefas para Antioquia segundo face a ele resisti que tendo-sido-condenado era');
INSERT INTO verses VALUES (29146, 48, 2, 12, 'antes-de o pois vir alguns de de-Tiago com o nações comia-junto quando porém vieram Retraía-se e separava a-si-mesmo temendo o de da-circuncisão');
INSERT INTO verses VALUES (29147, 48, 2, 13, 'e dissimularam-junto a ele e o restantes judeus de-modo-que e Barnabé foi-levado-junto deles o hipocrisia');
INSERT INTO verses VALUES (29148, 48, 2, 14, 'mas quando vi que não andam-retamente junto-a o verdade o evangelho disseram o Cefas diante todos se tu judeu sendo à-maneira-dos-gentios e não Judaicamente vives como o nações compeles Judaizar');
INSERT INTO verses VALUES (29149, 48, 2, 15, 'nós natureza judeus e não de nações pecadores');
INSERT INTO verses VALUES (29150, 48, 2, 16, 'sei porém que não é-justificado homem de obra da-lei se não através-de da-fé de-Christos Iesous e nós para Christos Iesous acreditamos para que sejamos-justificados de da-fé de-Christos e não de obra da-lei que de obra da-lei não será-justificado toda carne');
INSERT INTO verses VALUES (29151, 48, 2, 17, 'se porém buscando ser-justificado em em-Christos fomos-encontrados e eles-mesmos pecadores acaso Christos do-pecado servo não seja-assim');
INSERT INTO verses VALUES (29152, 48, 2, 18, 'se pois o qual destruí estas-coisas novamente edifico transgressor a-mim-mesmo recomendo');
INSERT INTO verses VALUES (29153, 48, 2, 19, 'eu pois através-de da-lei lei morreram para que a-Theos viverei em-Christos tenho-sido-co-crucificado');
INSERT INTO verses VALUES (29154, 48, 2, 20, 'vivo porém não-mais eu vive porém em mim Christos o qual porém agora vivo em na-carne em fé vivo o o do-Filho o de-Theos o tendo-amado me e do-que-entregou si-mesmo em-favor-de mim');
INSERT INTO verses VALUES (29155, 48, 2, 21, 'não anulo o graça o de-Theos se pois através-de da-lei justiça então Christos gratuitamente morreu');
INSERT INTO chapters VALUES (1094, 48, 3, 29);
INSERT INTO verses VALUES (29156, 48, 3, 1, 'Ômega insensatos Gálatas quem vos enfeitiçou o qual segundo olhos Iesous Christos foi-escrito-antes Tendo-sido-crucificado');
INSERT INTO verses VALUES (29157, 48, 3, 2, 'isto somente quero aprender de vosso de obra da-lei o espírito recebestes ou de ouvido da-fé');
INSERT INTO verses VALUES (29158, 48, 3, 3, 'assim insensatos sois tendo-começado Espírito agora carne Completais');
INSERT INTO verses VALUES (29159, 48, 3, 4, 'tantas-coisas sofrestes em-vão se pois e em-vão');
INSERT INTO verses VALUES (29160, 48, 3, 5, 'o portanto suprindo a-vós o espírito e operando poderes em a-vós de obra da-lei ou de ouvido da-fé');
INSERT INTO verses VALUES (29161, 48, 3, 6, 'assim-como Abraão creu o a-Theos e foi-contado a ele para justiça');
INSERT INTO verses VALUES (29162, 48, 3, 7, 'Conhecei então que o de da-fé estes filhos são Abraão');
INSERT INTO verses VALUES (29163, 48, 3, 8, 'tendo-previsto porém o escritura que de da-fé justifica o nações o Theos anunciou-boas-novas-de-antemão o Abraão que Serão-abençoadas-em em a-ti todas-as-coisas o nações');
INSERT INTO verses VALUES (29164, 48, 3, 9, 'de-modo-que o de da-fé são-abençoados com o fiel Abraão');
INSERT INTO verses VALUES (29165, 48, 3, 10, 'quanto pois de obra da-lei são sob maldição são está-escrito pois que Maldito todo o qual não permanece todos o tendo-sido-escritas em o livro o da-lei o fazer elas');
INSERT INTO verses VALUES (29166, 48, 3, 11, 'que porém em lei ninguém é-justificado de-junto-de o a-Theos evidente que o justo de da-fé viverá');
INSERT INTO verses VALUES (29167, 48, 3, 12, 'o porém lei não é de da-fé mas o tendo-feito elas viverá em a-eles');
INSERT INTO verses VALUES (29168, 48, 3, 13, 'Christos nos resgatou de o maldição o da-lei tendo-se-tornado em-favor-de nosso maldição que está-escrito Maldito todo o pendurando sobre árvore');
INSERT INTO verses VALUES (29169, 48, 3, 14, 'para que para o nações o bênção o Abraão aconteça em Iesous em-Christos para que o promessa o do-espírito recebamos através-de o da-fé');
INSERT INTO verses VALUES (29170, 48, 3, 15, 'Irmãos segundo homem digo contudo do-homem tendo-sido-ratificada aliança ninguém rejeita ou acrescenta-disposições');
INSERT INTO verses VALUES (29171, 48, 3, 16, 'o porém Abraão Foram-ditas o promessas e o semente dele não diz e o sementes como sobre muitos mas como sobre um e o semente teu o qual é Christos');
INSERT INTO verses VALUES (29172, 48, 3, 17, 'isto porém digo aliança tendo-sido-ratificada-de-antemão sob o de-Theos o com quatrocentos e trinta anos tendo-se-tornado lei não invalida para o anular o promessa');
INSERT INTO verses VALUES (29173, 48, 3, 18, 'se pois de da-lei o herança não-mais de promessa o porém Abraão através-de promessa tem-sido-concedido o Theos');
INSERT INTO verses VALUES (29174, 48, 3, 19, 'quê portanto o lei o transgressões graça foi-acrescentado até partícula-condicional venha o semente o qual tem-prometido tendo-sido-ordenado através-de anjo em mão mediador');
INSERT INTO verses VALUES (29175, 48, 3, 20, 'o porém mediador um não é o porém Theos um é');
INSERT INTO verses VALUES (29176, 48, 3, 21, 'o portanto lei segundo o promessas o de-Theos não seja-assim se pois foi-dado lei o podendo vivificar verdadeiramente de da-lei partícula-condicional era o justiça');
INSERT INTO verses VALUES (29177, 48, 3, 22, 'mas encerrou-junto o escritura o todas-as-coisas sob pecado para que o promessa de da-fé Iesous de-Christos seja-dada o creem');
INSERT INTO verses VALUES (29178, 48, 3, 23, 'Antes-de o porém vir o fé sob lei Éramos-guardados sendo-encerrados para o vindoura fé ser-revelado');
INSERT INTO verses VALUES (29179, 48, 3, 24, 'de-modo-que o lei tutor nosso aconteceu para Christon para que de da-fé sejamos-justificados');
INSERT INTO verses VALUES (29180, 48, 3, 25, 'tendo-vindo porém o da-fé não-mais sob tutor somos');
INSERT INTO verses VALUES (29181, 48, 3, 26, 'todos pois filhos de-Theos sois através-de o da-fé em em-Christos Iesous');
INSERT INTO verses VALUES (29182, 48, 3, 27, 'quanto pois para Christos fostes-batizados Christos vestistes');
INSERT INTO verses VALUES (29183, 48, 3, 28, 'não há judeu nem grego não há servo nem livre não há macho e fêmea todos pois vós um sois em em-Christos Iesous');
INSERT INTO verses VALUES (29184, 48, 3, 29, 'se porém vós de-Christos então o Abraão semente sois segundo promessa herdeiros');
INSERT INTO chapters VALUES (1095, 48, 4, 31);
INSERT INTO verses VALUES (29185, 48, 4, 1, 'digo e/mas sobre quanto tempo o herdeiro infante é nada difere servo kyrios todos sendo');
INSERT INTO verses VALUES (29186, 48, 4, 2, 'mas sob Procuradores é e administradores até o prazo-designado o pai');
INSERT INTO verses VALUES (29187, 48, 4, 3, 'assim e nós quando éramos criancinhas sob o elementos o do-mundo estávamos tendo-sido-escravizados');
INSERT INTO verses VALUES (29188, 48, 4, 4, 'quando porém veio o plenitude o tempo enviou-embora o Theos o Filho dele acontecido de mulher acontecido sob lei');
INSERT INTO verses VALUES (29189, 48, 4, 5, 'para que o sob lei resgatasse para que o adoção-como-filhos recebamos');
INSERT INTO verses VALUES (29190, 48, 4, 6, 'que e/mas sois filhos enviou-embora o Theos o espírito o do-Filho dele para o do-coração nosso clamando Abba o Pai');
INSERT INTO verses VALUES (29191, 48, 4, 7, 'de-modo-que não-mais és servo mas filho se porém filho e herdeiro através-de de-Theos');
INSERT INTO verses VALUES (29192, 48, 4, 8, 'mas então por-um-lado não sei Theos servistes o natureza não estando theoi');
INSERT INTO verses VALUES (29193, 48, 4, 9, 'agora porém conhecendo Theos mais porém tendo-sido-conhecidos sob de-Theos como convertei-vos novamente sobre o fracos e pobres elementos o qual novamente de-cima servir quereis');
INSERT INTO verses VALUES (29194, 48, 4, 10, 'do-dia observais e meses e tempos e anos');
INSERT INTO verses VALUES (29195, 48, 4, 11, 'temo vos não como em-vão tenho-trabalhado para vos');
INSERT INTO verses VALUES (29196, 48, 4, 12, 'Tornai-vos como eu que e-eu como vós irmãos suplico vosso nada me cometestes-injustiça');
INSERT INTO verses VALUES (29197, 48, 4, 13, 'sei porém que através-de fraqueza o carne evangelizei a-vós o antes');
INSERT INTO verses VALUES (29198, 48, 4, 14, 'e o tentação vosso em o na-carne meu não desprezastes nem desprezastes mas como anjo de-Theos recebestes me como Christos Iesous');
INSERT INTO verses VALUES (29199, 48, 4, 15, 'onde portanto o bem-aventurança vosso testemunho pois a-vós que se possível o olhos vosso tendo-cavado destes a-mim');
INSERT INTO verses VALUES (29200, 48, 4, 16, 'de-modo-que inimigo vosso tornei-me falando-a-verdade a-vós');
INSERT INTO verses VALUES (29201, 48, 4, 17, 'têm-ciúmes vos não bem mas excluir vos querem para que eles zelai');
INSERT INTO verses VALUES (29202, 48, 4, 18, 'belo porém ser-zelados em bom sempre e não somente em o estar-presente me junto-a vos');
INSERT INTO verses VALUES (29203, 48, 4, 19, 'filhos meu o qual novamente Tenho-dores-de-parto até o qual seja-formado Christos em a-vós');
INSERT INTO verses VALUES (29204, 48, 4, 20, 'queriam porém estar-presente junto-a vos agora e mudar o voz meu que estou-perplexo em a-vós');
INSERT INTO verses VALUES (29205, 48, 4, 21, 'Dizeis a-mim o sob lei querendo ser o lei não ouvi');
INSERT INTO verses VALUES (29206, 48, 4, 22, 'está-escrito pois que Abraão dois filhos teve um de o serva e um de o livre');
INSERT INTO verses VALUES (29207, 48, 4, 23, 'mas o por-um-lado de o serva segundo carne foi-gerado o porém de o livre através-de o promessa');
INSERT INTO verses VALUES (29208, 48, 4, 24, 'as-quais é sendo-alegorizado estas pois são dois alianças uma por-um-lado de do-monte Sinai para escravidão gerando a-qual é Agar');
INSERT INTO verses VALUES (29209, 48, 4, 25, 'o porém Agar Sinai monte é em o Arábia corresponde porém o agora Jerusalém serve pois com o filhos dela');
INSERT INTO verses VALUES (29210, 48, 4, 26, 'o porém acima Jerusalém livre é a-qual é mãe nosso');
INSERT INTO verses VALUES (29211, 48, 4, 27, 'está-escrito pois Alegra-te estéril o não dando-à-luz rasga e clama o não Tendo-dores-de-parto que muitas-coisas o filhos o deserto mais ou o tendo o homem');
INSERT INTO verses VALUES (29212, 48, 4, 28, 'vós e/mas irmãos segundo Isaque promessa filhos sois');
INSERT INTO verses VALUES (29213, 48, 4, 29, 'mas como então o segundo carne tendo-sido-gerado perseguia o segundo espírito assim e agora');
INSERT INTO verses VALUES (29214, 48, 4, 30, 'mas quê diz o escritura Lança-fora o serva e o Filho dela não pois não herdará o Filho o serva com o do-Filho o livre');
INSERT INTO verses VALUES (29215, 48, 4, 31, 'pelo-que irmãos não somos serva filhos mas o livre');
INSERT INTO chapters VALUES (1096, 48, 5, 26);
INSERT INTO verses VALUES (29216, 48, 5, 1, 'o liberdade nos Christos libertou permanecei-firmes portanto e não novamente jugo escravidão estais-presos');
INSERT INTO verses VALUES (29217, 48, 5, 2, 'Vê eu Paulo digo a-vós que se sejais-circuncidados Christos vos nada Aproveitará');
INSERT INTO verses VALUES (29218, 48, 5, 3, 'testifico porém novamente todo ao-homem sendo-circuncidado que devedor é todo o lei fazer');
INSERT INTO verses VALUES (29219, 48, 5, 4, 'fostes-anulados de de-Christos os-quais em lei sois-justificados o da-graça caístes-fora');
INSERT INTO verses VALUES (29220, 48, 5, 5, 'nós pois Espírito de da-fé esperança da-justiça aguardamos-ansiosamente');
INSERT INTO verses VALUES (29221, 48, 5, 6, 'em pois em-Christos Iesous nem circuncisão algo tem-poder nem incircuncisão mas fé através-de do-amor sendo-operada');
INSERT INTO verses VALUES (29222, 48, 5, 7, 'Corríeis bem quem vos impediu verdade não obedecer');
INSERT INTO verses VALUES (29223, 48, 5, 8, 'o persuasão não de o chamante vos');
INSERT INTO verses VALUES (29224, 48, 5, 9, 'pequena fermento todo o massa leveda');
INSERT INTO verses VALUES (29225, 48, 5, 10, 'eu tenho-confiado para vos em ao-Kyrios que nada outro pensareis o porém perturbando vos carregará o julgamento qualquer-que se seja');
INSERT INTO verses VALUES (29226, 48, 5, 11, 'eu e/mas irmãos se circuncisão ainda proclamo quê ainda sou-perseguido então tem-sido-anulado o tropeço o da-cruz');
INSERT INTO verses VALUES (29227, 48, 5, 12, 'oxalá e cortarão-fora o subvertendo vos');
INSERT INTO verses VALUES (29228, 48, 5, 13, 'vós pois sobre liberdade fostes-chamados irmãos somente não o liberdade para ocasião o na-carne mas através-de o do-amor servis uns-aos-outros');
INSERT INTO verses VALUES (29229, 48, 5, 14, 'o pois todo lei em um em-palavra foi-cumprido em o Amarás o próximo teu como a-ti-mesmo');
INSERT INTO verses VALUES (29230, 48, 5, 15, 'se porém uns-aos-outros mordeis e devoráveis vede não sob uns-aos-outros sejais-consumidos');
INSERT INTO verses VALUES (29231, 48, 5, 16, 'digo e/mas Espírito andai e desejo carne não não completeis');
INSERT INTO verses VALUES (29232, 48, 5, 17, 'o pois carne deseja segundo o do-espírito o porém espírito segundo o carne estas-coisas pois uns-aos-outros opõe-se para que não o qual se queirais estas-coisas façais');
INSERT INTO verses VALUES (29233, 48, 5, 18, 'se porém Espírito sois-conduzidos não sois sob lei');
INSERT INTO verses VALUES (29234, 48, 5, 19, 'manifesta e/mas é o obra o carne as-quais é prostituição impureza devassidão');
INSERT INTO verses VALUES (29235, 48, 5, 20, 'idolatria feitiçaria Inimizades contenda zelo iras contendas divisões heresias');
INSERT INTO verses VALUES (29236, 48, 5, 21, 'invejas bebedeiras orgias e o semelhantes nestes o qual digo-de-antemão a-vós assim-como disse-de-antemão que o o tais-coisas praticando reino de-Theos não herdarão');
INSERT INTO verses VALUES (29237, 48, 5, 22, 'o porém fruto o Espírito é amor alegria paz longanimidade benignidade bondade fé');
INSERT INTO verses VALUES (29238, 48, 5, 23, 'mansidão domínio-próprio segundo o de-tais não é lei');
INSERT INTO verses VALUES (29239, 48, 5, 24, 'o porém o de-Christos Iesous o carne crucificaram com o sofrimentos e o desejos');
INSERT INTO verses VALUES (29240, 48, 5, 25, 'se vivamos Espírito Espírito e caminhemos');
INSERT INTO verses VALUES (29241, 48, 5, 26, 'não tornemo-nos vaidosos uns-aos-outros provocando uns-aos-outros invejando');
INSERT INTO chapters VALUES (1097, 48, 6, 18);
INSERT INTO verses VALUES (29242, 48, 6, 1, 'Irmãos se e seja-surpreendido homem em a-alguém transgressão vós o espirituais restaurai o tal em espírito mansidão observando a-ti-mesmo não e tu sejas-tentado');
INSERT INTO verses VALUES (29243, 48, 6, 2, 'Uns-dos-outros o pesos carregai e assim preenchereis o lei o de-Christos');
INSERT INTO verses VALUES (29244, 48, 6, 3, 'se pois parece alguém ser algo nada sendo engana-a-mente a-si-mesmo');
INSERT INTO verses VALUES (29245, 48, 6, 4, 'o porém obra si-mesmo examine cada-um e então para si-mesmo somente o orgulho terá e não para o outro');
INSERT INTO verses VALUES (29246, 48, 6, 5, 'cada-um pois o próprio carga carregará');
INSERT INTO verses VALUES (29247, 48, 6, 6, 'Compartilhe porém o sendo-instruído o palavra o instruindo em todos bons');
INSERT INTO verses VALUES (29248, 48, 6, 7, 'não errais Theos não é-escarnecido o qual pois se semeie homem isto e ceifará');
INSERT INTO verses VALUES (29249, 48, 6, 8, 'que o o-que-semeia para o carne si-mesmo de o carne ceifará corrupção o porém o-que-semeia para o espírito de o do-espírito ceifará vida eterno');
INSERT INTO verses VALUES (29250, 48, 6, 9, 'o porém belo fazendo não desanimemos tempo pois próprio ceifaremos não desfalecendo');
INSERT INTO verses VALUES (29251, 48, 6, 10, 'então portanto como tempo tenhamos trabalhemos o bom junto-a todos principalmente porém junto-a o membros-da-casa o da-fé');
INSERT INTO verses VALUES (29252, 48, 6, 11, 'Vede quão-grandes a-vós letras escrevi o minha mão');
INSERT INTO verses VALUES (29253, 48, 6, 12, 'quanto querem fazer-boa-aparência em na-carne estes compelem vos ser-circuncidado somente para que o cruz o de-Christos não sejam-perseguidos');
INSERT INTO verses VALUES (29254, 48, 6, 13, 'nem pois o sendo-circuncidados eles-mesmos lei guardam mas querem vos ser-circuncidado para que em o vossa carne gloriem-se');
INSERT INTO verses VALUES (29255, 48, 6, 14, 'mim porém não seja-assim gloriar-se se não em o cruz o do-Kyrios nosso Iesous de-Christos através-de o qual mim mundo Tem-sido-crucificado e-eu ao-mundo');
INSERT INTO verses VALUES (29256, 48, 6, 15, 'nem pois circuncisão quê é nem incircuncisão mas nova criação');
INSERT INTO verses VALUES (29257, 48, 6, 16, 'e quanto o regra neste caminharão paz sobre eles e misericórdia e sobre o Israel o de-Theos');
INSERT INTO verses VALUES (29258, 48, 6, 17, 'o restante trabalhos a-mim ninguém ofereça eu pois o marcas o Iesous em o corpo meu carrego');
INSERT INTO verses VALUES (29259, 48, 6, 18, 'o graça o do-Kyrios nosso Iesous de-Christos com o do-espírito vosso irmãos amém');
INSERT INTO books VALUES (49, 'EPH', 'Efésios', 'NT', 6);
INSERT INTO chapters VALUES (1098, 49, 1, 23);
INSERT INTO verses VALUES (29260, 49, 1, 1, 'Paulo apóstolo de-Christos Iesous através-de da-vontade de-Theos o santos o estando em Éfeso e fiéis em em-Christos Iesous');
INSERT INTO verses VALUES (29261, 49, 1, 2, 'graça a-vós e paz de de-Theos do-Pai nosso e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (29262, 49, 1, 3, 'Bendito o Theos e Pai o do-Kyrios nosso Iesous de-Christos o tendo-abençoado nos em toda bênção espiritual em o celestiais em em-Christos');
INSERT INTO verses VALUES (29263, 49, 1, 4, 'assim-como escolheu nos em a ele antes-de fundação do-mundo ser nos santos e irrepreensíveis diante-de dele em amor');
INSERT INTO verses VALUES (29264, 49, 1, 5, 'tendo-predeterminado nos para adoção-como-filhos através-de Iesous de-Christos para ele segundo o boa-vontade o da-vontade dele');
INSERT INTO verses VALUES (29265, 49, 1, 6, 'para louvor da-glória o da-graça dele o qual Agraciou nos em o Amado');
INSERT INTO verses VALUES (29266, 49, 1, 7, 'em o qual temos o redenção através-de o sangue dele o perdão o transgressões segundo o riqueza o da-graça dele');
INSERT INTO verses VALUES (29267, 49, 1, 8, 'o qual abundou para nos em toda com-sabedoria e prudência');
INSERT INTO verses VALUES (29268, 49, 1, 9, 'tendo-feito-conhecer a-nós o mistério o da-vontade dele segundo o boa-vontade dele o qual propôs em a ele');
INSERT INTO verses VALUES (29269, 49, 1, 10, 'para administração o plenitude o tempos recapitular o todas-as-coisas em o em-Christos o sobre o nos-céus e o sobre o da-terra em a ele');
INSERT INTO verses VALUES (29270, 49, 1, 11, 'em o qual e fomos-feitos-herança tendo-sido-predeterminados segundo propósito o o todas-as-coisas operando segundo o conselho o da-vontade dele');
INSERT INTO verses VALUES (29271, 49, 1, 12, 'para o ser nos para louvor da-glória dele o tendo-esperado-de-antemão em o em-Christos');
INSERT INTO verses VALUES (29272, 49, 1, 13, 'em o qual e vós ouvindo o palavra o da-verdade o evangelho o salvação vosso em o qual e tendo-crido fostes-selados o Espírito o promessa o no-santo');
INSERT INTO verses VALUES (29273, 49, 1, 14, 'o qual é penhor o herança nosso para redenção o aquisição para louvor o da-glória dele');
INSERT INTO verses VALUES (29274, 49, 1, 15, 'através-de isto eu-também ouvindo o segundo vos fé em o ao-Kyrios Iesous e o amor o para todos o santos');
INSERT INTO verses VALUES (29275, 49, 1, 16, 'não cesso dando-graças em-favor-de vosso menção fazendo sobre o orações meu');
INSERT INTO verses VALUES (29276, 49, 1, 17, 'para que o Theos o do-Kyrios nosso Iesous de-Christos o Pai o da-glória dê a-vós espírito da-sabedoria e revelação em conhecimento-pleno dele');
INSERT INTO verses VALUES (29277, 49, 1, 18, 'tendo-sido-iluminados o olhos o do-coração vosso para o sei vos quem é o esperança o chamado dele quem o riqueza o da-glória o herança dele em o santos');
INSERT INTO verses VALUES (29278, 49, 1, 19, 'e quê o excedente grandeza o do-poder dele para nos o crentes segundo o operação o poder o força dele');
INSERT INTO verses VALUES (29279, 49, 1, 20, 'o qual tem-operado em o em-Christos tendo-levantado ele de mortos e sentando-se em direita dele em o celestiais');
INSERT INTO verses VALUES (29280, 49, 1, 21, 'muito-acima toda princípio e da-autoridade e do-poder e senhorio e todo do-nome sendo-nomeado não somente em o era neste mas e em o vindouro');
INSERT INTO verses VALUES (29281, 49, 1, 22, 'e todas-as-coisas sujeitou sob o pés dele e ele deu cabeça em-favor-de todas-as-coisas o assembleia');
INSERT INTO verses VALUES (29282, 49, 1, 23, 'a-qual é o corpo dele o plenitude o o todas-as-coisas em todos sendo-cumprido');
INSERT INTO chapters VALUES (1099, 49, 2, 22);
INSERT INTO verses VALUES (29283, 49, 2, 1, 'e vos sendo mortos o transgressões e o pecados vosso');
INSERT INTO verses VALUES (29284, 49, 2, 2, 'em o qual alguma-vez andastes segundo o eternidade o do-mundo deste segundo o governante o da-autoridade o ar o do-espírito o agora operando em o filhos o desobediência');
INSERT INTO verses VALUES (29285, 49, 2, 3, 'em o qual e nós todos conduzimo-nos alguma-vez em o desejos o carne nosso fazendo o vontades o carne e o mentes e estávamos filhos natureza ira como e o restantes');
INSERT INTO verses VALUES (29286, 49, 2, 4, 'o porém Theos rico sendo em tem-misericórdia através-de o muita amor dele o qual amou nos');
INSERT INTO verses VALUES (29287, 49, 2, 5, 'e sendo nos mortos o transgressões vivificou-junto o em-Christos graça sois tendo-sido-salvos');
INSERT INTO verses VALUES (29288, 49, 2, 6, 'e co-ressuscitou e fez-sentar-junto em o celestiais em em-Christos Iesous');
INSERT INTO verses VALUES (29289, 49, 2, 7, 'para que demonstre em o eras o sobrevindo o excedente riqueza o da-graça dele em benignidade sobre nos em em-Christos Iesous');
INSERT INTO verses VALUES (29290, 49, 2, 8, 'o pois graça sois tendo-sido-salvos através-de da-fé e isto não de vosso de-Theos o presente');
INSERT INTO verses VALUES (29291, 49, 2, 9, 'não de obra para que não alguém glorie-se');
INSERT INTO verses VALUES (29292, 49, 2, 10, 'dele pois somos obra tendo-sido-criados em em-Christos Iesous sobre obra bons o qual preparou-de-antemão o Theos para que em a-eles andemos');
INSERT INTO verses VALUES (29293, 49, 2, 11, 'por-isso lembrai-vos que alguma-vez vós o nações em na-carne o sendo-chamados incircuncisão sob o sendo-chamada da-circuncisão em carne feito-por-mãos');
INSERT INTO verses VALUES (29294, 49, 2, 12, 'que éreis o tempo naquele sem de-Christos tendo-sido-alienados o cidadania o Israel e estrangeiros o alianças o promessa esperança não tendo e sem-Theos em o ao-mundo');
INSERT INTO verses VALUES (29295, 49, 2, 13, 'agora porém em em-Christos Iesous vós o alguma-vez sendo longe tornastes-vos perto em o sangue o de-Christos');
INSERT INTO verses VALUES (29296, 49, 2, 14, 'ele pois é o paz nosso o tendo-feito o ambos um e o parede-do-meio o de-cerca tendo-desatado o inimizade em o carne dele');
INSERT INTO verses VALUES (29297, 49, 2, 15, 'o lei o mandamentos em decretos tendo-anulado para que o dois crie em a-si-mesmo para um novo homem fazendo paz');
INSERT INTO verses VALUES (29298, 49, 2, 16, 'e reconcilie o ambos em um corpo o a-Theos através-de o da-cruz tendo-matado o inimizade em a ele');
INSERT INTO verses VALUES (29299, 49, 2, 17, 'e vindo anunciou-boa-nova paz a-vós o longe e paz o perto');
INSERT INTO verses VALUES (29300, 49, 2, 18, 'que através-de dele temos o acesso o ambos em um Espírito junto-a o Pai');
INSERT INTO verses VALUES (29301, 49, 2, 19, 'então portanto não-mais sois estrangeiros e peregrinos mas sois co-cidadãos o dos-santos e membros-da-casa o de-Theos');
INSERT INTO verses VALUES (29302, 49, 2, 20, 'Tendo-sido-edificados-sobre sobre o fundamento o apóstolos e profetas sendo pedra-angular dele de-Christos Iesous');
INSERT INTO verses VALUES (29303, 49, 2, 21, 'em o qual toda edificação sendo-ajustada-junto faz-crescer para templo santo em ao-Kyrios');
INSERT INTO verses VALUES (29304, 49, 2, 22, 'em o qual e vós sois-co-edificados para habitação o de-Theos em Espírito');
INSERT INTO chapters VALUES (1100, 49, 3, 21);
INSERT INTO verses VALUES (29305, 49, 3, 1, 'disto graça eu Paulo o prisioneiro o de-Christos Iesous em-favor-de vosso o nações');
INSERT INTO verses VALUES (29306, 49, 3, 2, 'se pois ouvistes o administração o da-graça o de-Theos o tendo-sido-dada a-mim para vos');
INSERT INTO verses VALUES (29307, 49, 3, 3, 'que segundo revelação foi-dado-a-conhecer a-mim o mistério assim-como escrevi-de-antemão em pouco');
INSERT INTO verses VALUES (29308, 49, 3, 4, 'junto-a o qual podeis lendo compreender o entendimento meu em o mistério o de-Christos');
INSERT INTO verses VALUES (29309, 49, 3, 5, 'o qual outras gerações não foi-dado-a-conhecer o filhos o dos-homens como agora foi-revelado o santos apóstolos dele e profetas em Espírito');
INSERT INTO verses VALUES (29310, 49, 3, 6, 'ser o nações co-herdeira e co-corpo e co-participantes o promessa em em-Christos Iesous através-de o evangelho');
INSERT INTO verses VALUES (29311, 49, 3, 7, 'o qual tornei-me servo segundo o gratuitamente o da-graça o de-Theos o tendo-sido-dada a-mim segundo o operação o do-poder dele');
INSERT INTO verses VALUES (29312, 49, 3, 8, 'mim o menor-de-todos todos santos foi-dado o graça esta o nações evangelizar o inescrutável riqueza o de-Christos');
INSERT INTO verses VALUES (29313, 49, 3, 9, 'e iluminar quem o administração o mistério o do-que-tem-sido-escondido de o eras em o a-Theos o o todas-as-coisas tendo-criado');
INSERT INTO verses VALUES (29314, 49, 3, 10, 'para que seja-feito-conhecer agora o governos e o autoridades em o celestiais através-de o da-assembleia o multiforme sabedoria o de-Theos');
INSERT INTO verses VALUES (29315, 49, 3, 11, 'segundo propósito o eras o qual fez em o em-Christos Iesous o ao-Kyrios nosso');
INSERT INTO verses VALUES (29316, 49, 3, 12, 'em o qual temos o ousadia e acesso em confiança através-de o da-fé dele');
INSERT INTO verses VALUES (29317, 49, 3, 13, 'por-isso peço não desanimar em o tribulações meu em-favor-de vosso a-qual é glória vosso');
INSERT INTO verses VALUES (29318, 49, 3, 14, 'disto graça dobro o joelhos meu junto-a o Pai');
INSERT INTO verses VALUES (29319, 49, 3, 15, 'de o qual toda família em nos-céus e sobre da-terra é-nomeado');
INSERT INTO verses VALUES (29320, 49, 3, 16, 'para que dê a-vós segundo o riqueza o da-glória dele poder ser-fortalecido através-de o do-espírito dele para o dentro homem');
INSERT INTO verses VALUES (29321, 49, 3, 17, 'habitar o Christos através-de o da-fé em o corações vosso em amor tendo-sido-enraizados e tendo-sido-fundamentados');
INSERT INTO verses VALUES (29322, 49, 3, 18, 'para que sejais-plenamente-capazes alcançar com todos o santos quê o largura e comprimento e altura e profundidade');
INSERT INTO verses VALUES (29323, 49, 3, 19, 'conhecer e o excedente o do-conhecimento amor o de-Christos para que sejais-preenchidos para todo o plenitude o de-Theos');
INSERT INTO verses VALUES (29324, 49, 3, 20, 'o porém podendo em-favor-de todas-as-coisas fazer superabundantemente o qual pedimos ou entendemos segundo o poder o sendo-operada em a-nós');
INSERT INTO verses VALUES (29325, 49, 3, 21, 'a ele o glória em o assembleia e em em-Christos Iesous para todas o gerações o eternidade o eras amém');
INSERT INTO chapters VALUES (1101, 49, 4, 32);
INSERT INTO verses VALUES (29326, 49, 4, 1, 'Exorto portanto vos eu o prisioneiro em ao-Kyrios dignamente andar o chamado o qual fostes-chamados');
INSERT INTO verses VALUES (29327, 49, 4, 2, 'com toda humildade-de-mente e mansidão com paciência suportando uns-aos-outros em amor');
INSERT INTO verses VALUES (29328, 49, 4, 3, 'sendo-diligentes guardar o unidade o do-espírito em o ligadura o paz');
INSERT INTO verses VALUES (29329, 49, 4, 4, 'um corpo e um espírito assim-como e fostes-chamados em uma esperança o chamado vosso');
INSERT INTO verses VALUES (29330, 49, 4, 5, 'um Kyrios uma fé um batismo');
INSERT INTO verses VALUES (29331, 49, 4, 6, 'um Theos e Pai todos o sobre todos e através-de todos e em todos');
INSERT INTO verses VALUES (29332, 49, 4, 7, 'Um porém a-cada-um nosso foi-dado o graça segundo o medida o dom o de-Christos');
INSERT INTO verses VALUES (29333, 49, 4, 8, 'por-isso diz Tendo-subido para altura Levou-cativo cativeiro deu dons o aos-homens');
INSERT INTO verses VALUES (29334, 49, 4, 9, 'o porém subiu quê é se não que e desceu para o inferiores partes o da-terra');
INSERT INTO verses VALUES (29335, 49, 4, 10, 'o descendo ele é e o subindo muito-acima todos o dos-céus para que cumpra o todas-as-coisas');
INSERT INTO verses VALUES (29336, 49, 4, 11, 'e ele deu o por-um-lado apóstolos o porém profetas o porém evangelistas o porém pastores e mestres');
INSERT INTO verses VALUES (29337, 49, 4, 12, 'junto-a o aperfeiçoamento o santos para obra ministério para edificação o do-corpo o de-Christos');
INSERT INTO verses VALUES (29338, 49, 4, 13, 'até cheguemos o todos para o unidade o da-fé e o pleno-conhecimento o do-Filho o de-Theos para homem perfeito para medida estatura o plenitude o de-Christos');
INSERT INTO verses VALUES (29339, 49, 4, 14, 'para que não-mais sejamos criancinhas sendo-agitados-por-ondas e sendo-levados-ao-redor todo vento o ensino em o artimanha o dos-homens em astúcia junto-a o artimanha o engano');
INSERT INTO verses VALUES (29340, 49, 4, 15, 'falando-a-verdade porém em amor façamos-crescer para ele o todas-as-coisas o qual é o cabeça Christos');
INSERT INTO verses VALUES (29341, 49, 4, 16, 'de o qual todo o corpo sendo-ajustado-junto e sendo-unido-junto através-de toda toque o suprimento segundo operação em medida um cada-um da-parte o crescimento o do-corpo faz para edificação si-mesmo em amor');
INSERT INTO verses VALUES (29342, 49, 4, 17, 'isto portanto digo e testifico em ao-Kyrios não-mais vos andar assim-como e o nações anda em vaidade o mente deles');
INSERT INTO verses VALUES (29343, 49, 4, 18, 'Tendo-sido-obscurecidos o entendimento sendo tendo-sido-alienados o da-vida o de-Theos através-de o ignorância o sendo em a-eles através-de o endurecimento o do-coração deles');
INSERT INTO verses VALUES (29344, 49, 4, 19, 'os-quais tendo-se-tornado-insensíveis si-mesmos entregaram o devassidão para trabalho impureza toda em ganância');
INSERT INTO verses VALUES (29345, 49, 4, 20, 'vós porém não assim aprendestes o Christon');
INSERT INTO verses VALUES (29346, 49, 4, 21, 'se pois ele ouvistes e em a ele fostes-ensinados assim-como é verdade em o Iesous');
INSERT INTO verses VALUES (29347, 49, 4, 22, 'despojar-se vos segundo o anterior conduta o velho homem o sendo-corrompido segundo o desejos o engano');
INSERT INTO verses VALUES (29348, 49, 4, 23, 'ser-renovado porém o espírito o mente vosso');
INSERT INTO verses VALUES (29349, 49, 4, 24, 'e vestir o novo homem o segundo Theos tendo-sido-criados em justiça e santidade o da-verdade');
INSERT INTO verses VALUES (29350, 49, 4, 25, 'por-isso tendo-despojado o mentira falais verdade cada-um com o próximo dele que somos uns-aos-outros membros');
INSERT INTO verses VALUES (29351, 49, 4, 26, 'irai-vos e não pecais o sol não ponha-se sobre em-provocação-à-ira vosso');
INSERT INTO verses VALUES (29352, 49, 4, 27, 'nem dai lugar o diabo');
INSERT INTO verses VALUES (29353, 49, 4, 28, 'o furtando não-mais furte mais porém trabalhe trabalhando o próprias mãos o bom para que tenha repartir o necessidade tendo');
INSERT INTO verses VALUES (29354, 49, 4, 29, 'todo palavra podre de o boca vosso não saia mas se alguém bom junto-a edificação o necessidade para que dê graça o ouvem');
INSERT INTO verses VALUES (29355, 49, 4, 30, 'e não entristeceis o espírito o santo o de-Theos em o qual fostes-selados para dia redenção');
INSERT INTO verses VALUES (29356, 49, 4, 31, 'toda amargura e ira e ira e clamor e blasfêmia seja-levantado de vosso com toda maldade');
INSERT INTO verses VALUES (29357, 49, 4, 32, 'tornai-vos porém para uns-aos-outros benignos compassivos concedendo-graciosamente si-mesmos assim-como e o Theos em em-Christos concedeu-graciosamente a-vós');
INSERT INTO chapters VALUES (1102, 49, 5, 33);
INSERT INTO verses VALUES (29358, 49, 5, 1, 'tornai-vos portanto imitadores o de-Theos como filhos amados');
INSERT INTO verses VALUES (29359, 49, 5, 2, 'e andai em amor assim-como e o Christos amou vos e entregou si-mesmo em-favor-de nosso oferta e sacrifício o a-Theos para cheiro fragrância');
INSERT INTO verses VALUES (29360, 49, 5, 3, 'Fornicação porém e impureza toda ou avareza nem seja-nomeado em a-vós assim-como convém santos');
INSERT INTO verses VALUES (29361, 49, 5, 4, 'e torpeza e conversa-tola ou gracejos-obscenos o qual não convinha mas mais ação-de-graças');
INSERT INTO verses VALUES (29362, 49, 5, 5, 'isto pois sei conhecendo que todo fornicador ou impuro ou ganancioso o qual é idólatra não tem herança em o reino o de-Christos e de-Theos');
INSERT INTO verses VALUES (29363, 49, 5, 6, 'ninguém vos engane vazios palavras através-de estas-coisas pois vem o ira o de-Theos sobre o filhos o desobediência');
INSERT INTO verses VALUES (29364, 49, 5, 7, 'não portanto tornai-vos co-participantes deles');
INSERT INTO verses VALUES (29365, 49, 5, 8, 'éreis pois alguma-vez trevas agora porém luz em ao-Kyrios como filhos luz andai');
INSERT INTO verses VALUES (29366, 49, 5, 9, 'o pois fruto o luz em toda bondade e justiça e verdade');
INSERT INTO verses VALUES (29367, 49, 5, 10, 'examinando quê é agradável o ao-Kyrios');
INSERT INTO verses VALUES (29368, 49, 5, 11, 'e não participais-com o obra o infrutíferos o das-trevas mais porém e repreendei');
INSERT INTO verses VALUES (29369, 49, 5, 12, 'o pois em-oculto acontecendo sob deles vergonhoso é e dizer');
INSERT INTO verses VALUES (29370, 49, 5, 13, 'o porém todas-as-coisas sendo-repreendidas sob o luz é-manifestado todo pois o sendo-manifestado luz é');
INSERT INTO verses VALUES (29371, 49, 5, 14, 'por-isso diz Levanta-te o dormindo e levanta-te de o mortos e Resplandecerá a-ti o Christos');
INSERT INTO verses VALUES (29372, 49, 5, 15, 'Vede portanto com-exatidão como andai não como insensatos mas como sábios');
INSERT INTO verses VALUES (29373, 49, 5, 16, 'resgatando o tempo-oportuno que o dias más são');
INSERT INTO verses VALUES (29374, 49, 5, 17, 'através-de isto não tornai-vos insensatos mas entendeis quê o vontade o do-Kyrios');
INSERT INTO verses VALUES (29375, 49, 5, 18, 'e não embriagai-vos vinho em o qual é dissolução mas sede-preenchidos em Espírito');
INSERT INTO verses VALUES (29376, 49, 5, 19, 'falando si-mesmos salmos e hinos e cânticos espirituais cantando e salmodiando o no-coração vosso o ao-Kyrios');
INSERT INTO verses VALUES (29377, 49, 5, 20, 'dando-graças sempre em-favor-de todos em em-nome o do-Kyrios nosso Iesous de-Christos o a-Theos e Pai');
INSERT INTO verses VALUES (29378, 49, 5, 21, 'sujeitando-se uns-aos-outros em medo de-Christos');
INSERT INTO verses VALUES (29379, 49, 5, 22, 'o mulheres o próprios homens como o ao-Kyrios');
INSERT INTO verses VALUES (29380, 49, 5, 23, 'que homem é cabeça o mulher como e o Christos cabeça o da-assembleia ele salvador o do-corpo');
INSERT INTO verses VALUES (29381, 49, 5, 24, 'mas como o assembleia sujeita-se o em-Christos assim e o mulheres o homens em a-todo');
INSERT INTO verses VALUES (29382, 49, 5, 25, 'o homens amai o mulheres assim-como e o Christos amou o igreja e si-mesmo entregou em-favor-de dela');
INSERT INTO verses VALUES (29383, 49, 5, 26, 'para que ela santifique tendo-purificado o lavagem o água em palavra');
INSERT INTO verses VALUES (29384, 49, 5, 27, 'para que apresente ele si-mesmo Glorioso o igreja não tendo mancha ou ruga ou algo o de-tais mas para que seja santa e sem-mácula');
INSERT INTO verses VALUES (29385, 49, 5, 28, 'assim devem e o homens amar o deles-mesmos mulheres como o deles-mesmos corpos o amando o si-mesmo mulher si-mesmo ama');
INSERT INTO verses VALUES (29386, 49, 5, 29, 'ninguém pois alguma-vez o si-mesmo carne odiou mas nutre e cuida ela assim-como e o Christos o igreja');
INSERT INTO verses VALUES (29387, 49, 5, 30, 'que membros somos o do-corpo dele');
INSERT INTO verses VALUES (29388, 49, 5, 31, 'em-troca-de deste deixará homem o Pai e o mãe e será-unido junto-a o mulher dele e serão o dois para carne uma');
INSERT INTO verses VALUES (29389, 49, 5, 32, 'o mistério isto grande é eu porém digo para Christos e para o igreja');
INSERT INTO verses VALUES (29390, 49, 5, 33, 'exceto e vós o segundo um cada-um o si-mesmo mulher assim ame como a-si-mesmo o porém mulher para que tema o homem');
INSERT INTO chapters VALUES (1103, 49, 6, 24);
INSERT INTO verses VALUES (29391, 49, 6, 1, 'o filhos obedecei o pais vosso em ao-Kyrios isto pois é justo');
INSERT INTO verses VALUES (29392, 49, 6, 2, 'honra o Pai teu e o mãe a-qual é mandamento primeiro em promessa');
INSERT INTO verses VALUES (29393, 49, 6, 3, 'para que bem a-ti aconteça e serás longevo sobre o da-terra');
INSERT INTO verses VALUES (29394, 49, 6, 4, 'e o pais não provocais-à-ira o filhos vosso mas nutri eles em disciplina e admoestação do-Kyrios');
INSERT INTO verses VALUES (29395, 49, 6, 5, 'o servos obedecei o segundo carne senhores com medo e tremor em simplicidade o do-coração vosso como o em-Christos');
INSERT INTO verses VALUES (29396, 49, 6, 6, 'não segundo serviço-para-os-olhos como agradadores-de-homens mas como servos de-Christos fazendo o vontade o de-Theos de alma');
INSERT INTO verses VALUES (29397, 49, 6, 7, 'com benevolência servindo como o ao-Kyrios e não aos-homens');
INSERT INTO verses VALUES (29398, 49, 6, 8, 'sei que cada-um se algo faça bom isto receberá de-junto-de do-Kyrios seja servo seja livre');
INSERT INTO verses VALUES (29399, 49, 6, 9, 'e o senhores o eles fazei junto-a eles cessando o ameaça sei que e deles e vosso o Kyrios é em nos-céus e acepção-de-pessoas não é de-junto-de a ele');
INSERT INTO verses VALUES (29400, 49, 6, 10, 'o restante fortalecei-vos em ao-Kyrios e em o segura o força dele');
INSERT INTO verses VALUES (29401, 49, 6, 11, 'vesti-vos o armadura-completa o de-Theos junto-a o poder vos estar-de-pé junto-a o artimanhas o diabo');
INSERT INTO verses VALUES (29402, 49, 6, 12, 'que não é a-nós o luta junto-a sangue e carne mas junto-a o principados junto-a o da-autoridade junto-a o dominadores-do-mundo o das-trevas deste junto-a o espirituais o maldade em o celestiais');
INSERT INTO verses VALUES (29403, 49, 6, 13, 'através-de isto tomai o armadura-completa o de-Theos para que possais resistir em o dia o má e todas-as-coisas tendo-realizado estar-de-pé');
INSERT INTO verses VALUES (29404, 49, 6, 14, 'ficai-de-pé portanto tendo-se-cingido o lombo vosso em verdade e vestidos o couraça o da-justiça');
INSERT INTO verses VALUES (29405, 49, 6, 15, 'e Tendo-calçado o pés em Preparação o evangelho o paz');
INSERT INTO verses VALUES (29406, 49, 6, 16, 'em todos tendo-tomado o escudo o da-fé em o qual podereis todas-as-coisas o flechas o do-mal o tendo-sido-refinados-pelo-fogo apagar');
INSERT INTO verses VALUES (29407, 49, 6, 17, 'e o capacete o de-salvação recebei e o espada o do-espírito o qual é palavra de-Theos');
INSERT INTO verses VALUES (29408, 49, 6, 18, 'através-de toda oração e súplica orando em todo tempo em Espírito e para ele vigiando em toda perseverança e súplica acerca-de todos o dos-santos');
INSERT INTO verses VALUES (29409, 49, 6, 19, 'e em-favor-de mim para que a-mim seja-dada palavra em abrirá o boca meu em com-ousadia fazer-conhecer o mistério o evangelho');
INSERT INTO verses VALUES (29410, 49, 6, 20, 'em-favor-de o qual sou-embaixador em cadeia para que em a ele eu-fale-com-ousadia como é necessário me falar');
INSERT INTO verses VALUES (29411, 49, 6, 21, 'para que porém sei e vós o segundo a-mim quê pratico todas-as-coisas fará-conhecer a-vós Tíquico o amado irmão e fiel servo em ao-Kyrios');
INSERT INTO verses VALUES (29412, 49, 6, 22, 'o qual enviei junto-a vos para ele isto para que conheçais o acerca-de nosso e exorte o do-coração vosso');
INSERT INTO verses VALUES (29413, 49, 6, 23, 'paz o aos-irmãos e amor com da-fé de de-Theos do-Pai e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (29414, 49, 6, 24, 'o graça com todos o amando o Kyrion nosso Iesous Christos em incorruptibilidade');
INSERT INTO books VALUES (50, 'PHP', 'Filipenses', 'NT', 4);
INSERT INTO chapters VALUES (1104, 50, 1, 30);
INSERT INTO verses VALUES (29415, 50, 1, 1, 'Paulo e Timóteo servos de-Christos Iesous todos o santos em em-Christos Iesous o estando em Filipos com supervisores e servos');
INSERT INTO verses VALUES (29416, 50, 1, 2, 'graça a-vós e paz de de-Theos do-Pai nosso e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (29417, 50, 1, 3, 'Dou-graças o a-Theos meu sobre toda o lembrança vosso');
INSERT INTO verses VALUES (29418, 50, 1, 4, 'sempre em toda súplica meu em-favor-de todos vosso com alegria o súplica fazendo');
INSERT INTO verses VALUES (29419, 50, 1, 5, 'sobre o comunhão vosso para o evangelho de o primeiro do-dia até o agora');
INSERT INTO verses VALUES (29420, 50, 1, 6, 'confiando ele isto que o tendo-começado em a-vós obra bom Completará até do-dia de-Christos Iesous');
INSERT INTO verses VALUES (29421, 50, 1, 7, 'assim-como é justo mim isto pensar em-favor-de todos vosso através-de o ter me em o no-coração vos em e o cadeias meu e em o defesa e confirmação o evangelho co-participantes meu o da-graça todos vos sendo');
INSERT INTO verses VALUES (29422, 50, 1, 8, 'testemunha pois meu o Theos como desejo-ardentemente todos vos em entranhas de-Christos Iesous');
INSERT INTO verses VALUES (29423, 50, 1, 9, 'e isto oro para que o amor vosso ainda mais e mais abunde em conhecimento-pleno e toda discernimento');
INSERT INTO verses VALUES (29424, 50, 1, 10, 'para o provar vos o importando para que éreis sinceros e sem-tropeço para dia de-Christos');
INSERT INTO verses VALUES (29425, 50, 1, 11, 'tendo-sido-preenchidos fruto justiça o através-de Iesous de-Christos para glória e louvor de-Theos');
INSERT INTO verses VALUES (29426, 50, 1, 12, 'conhecer porém vos quero irmãos que o segundo mim mais para progresso o evangelho tem-vindo');
INSERT INTO verses VALUES (29427, 50, 1, 13, 'de-modo-que o cadeias meu manifestos em em-Christos tornar-se em todo o pretório e o restantes todos');
INSERT INTO verses VALUES (29428, 50, 1, 14, 'e o mais o irmãos em ao-Kyrios tendo-confiado o cadeias meu ainda-mais ousar sem-temor o palavra o de-Theos falar');
INSERT INTO verses VALUES (29429, 50, 1, 15, 'Alguns por-um-lado e através-de inveja e contenda alguns porém e através-de boa-vontade o Christos proclamam');
INSERT INTO verses VALUES (29430, 50, 1, 16, 'o por-um-lado de do-amor sei que para defesa o evangelho jazo');
INSERT INTO verses VALUES (29431, 50, 1, 17, 'o porém de contenda o Christos anunciam não puramente supondo tribulação levantar o cadeias meu');
INSERT INTO verses VALUES (29432, 50, 1, 18, 'quê pois exceto que todo modo seja pretexto seja verdade Christos é-anunciado e em neste alegro-me mas e alegrar-me-ei');
INSERT INTO verses VALUES (29433, 50, 1, 19, 'sei pois que isto a-mim resultará para salvação através-de o vosso súplica e suprimento o do-espírito Iesous de-Christos');
INSERT INTO verses VALUES (29434, 50, 1, 20, 'segundo o ardente-expectativa e esperança meu que em a-ninguém serei-envergonhado mas em toda com-ousadia como sempre e agora será-engrandecido Christos em o corpo meu seja através-de da-vida seja através-de da-morte');
INSERT INTO verses VALUES (29435, 50, 1, 21, 'A-mim pois o viver Christos e o morrer lucro');
INSERT INTO verses VALUES (29436, 50, 1, 22, 'se porém o viver em na-carne isto a-mim fruto obra e quê escolherei não faço-conhecer');
INSERT INTO verses VALUES (29437, 50, 1, 23, 'sou-constrangido porém de o dois o desejo tendo para o partir e com em-Christos ser muito pois mais melhor');
INSERT INTO verses VALUES (29438, 50, 1, 24, 'o porém permanecer o carne mais-necessário através-de vos');
INSERT INTO verses VALUES (29439, 50, 1, 25, 'e isto confiando sei que permanecerei e permanecerei todos a-vós para o vosso progresso e alegria o da-fé');
INSERT INTO verses VALUES (29440, 50, 1, 26, 'para que o orgulho vosso abunde em em-Christos Iesous em mim através-de o minha presença novamente junto-a vos');
INSERT INTO verses VALUES (29441, 50, 1, 27, 'somente dignamente o evangelho o de-Christos vivei-como-cidadãos para que seja vindo e vendo vos seja estando-ausente ouço o acerca-de vosso que permanecei-firmes em um espírito uma alma combatendo-junto o fé o evangelho');
INSERT INTO verses VALUES (29442, 50, 1, 28, 'e não sendo-assustados em a-ninguém sob o opondo-se a-qual é a-eles Demonstração perdição vosso porém salvação e isto de de-Theos');
INSERT INTO verses VALUES (29443, 50, 1, 29, 'que a-vós Foi-dado-por-graça o em-favor-de de-Christos não somente o para ele crer mas e o em-favor-de dele sofrer');
INSERT INTO verses VALUES (29444, 50, 1, 30, 'o ele luta tendo qual vistes em mim e agora ouvi em me');
INSERT INTO chapters VALUES (1105, 50, 2, 30);
INSERT INTO verses VALUES (29445, 50, 2, 1, 'se alguém portanto consolação em em-Christos se algo consolo do-amor se alguém comunhão do-espírito se alguém entranhas e compaixões');
INSERT INTO verses VALUES (29446, 50, 2, 2, 'enchei meu o alegria para que o ele penseis o ela amor tendo de-uma-só-alma o um pensando');
INSERT INTO verses VALUES (29447, 50, 2, 3, 'nada segundo contenda nem segundo vanglória mas o humildade-de-mente uns-aos-outros líderes Superiores deles-mesmos');
INSERT INTO verses VALUES (29448, 50, 2, 4, 'não o deles-mesmos cada-um observando mas e o outros cada-um');
INSERT INTO verses VALUES (29449, 50, 2, 5, 'isto pensais em a-vós o qual e em em-Christos Iesous');
INSERT INTO verses VALUES (29450, 50, 2, 6, 'o qual em forma de-Theos sendo não roubo considerou o ser iguais a-Theos');
INSERT INTO verses VALUES (29451, 50, 2, 7, 'mas si-mesmo esvaziou forma servo tendo-recebido em semelhança dos-homens tendo-se-tornado e em-forma tendo-sido-encontrado como homem');
INSERT INTO verses VALUES (29452, 50, 2, 8, 'Humilhou si-mesmo tendo-se-tornado Obediente até da-morte da-morte porém da-cruz');
INSERT INTO verses VALUES (29453, 50, 2, 9, 'por-isso e o Theos ele Superexaltou e concedeu-graciosamente a ele o nome o em-favor-de todo nome');
INSERT INTO verses VALUES (29454, 50, 2, 10, 'para que em o em-nome Iesous todo joelho dobre celestiais e terrenas e subterrâneos');
INSERT INTO verses VALUES (29455, 50, 2, 11, 'e toda língua confesse que KYRIOS Iesous Christos para glória de-Theos Pai');
INSERT INTO verses VALUES (29456, 50, 2, 12, 'de-modo-que amados meu assim-como sempre obedecestes não como em o presença meu somente mas agora muito mais em o ausência meu com medo e tremor o deles-mesmos salvação realizais');
INSERT INTO verses VALUES (29457, 50, 2, 13, 'Theos pois é o operando em a-vós e o querer e o operar em-favor-de o boa-vontade');
INSERT INTO verses VALUES (29458, 50, 2, 14, 'todas-as-coisas fazei sem murmurações e raciocínios');
INSERT INTO verses VALUES (29459, 50, 2, 15, 'para que torneis-vos irrepreensíveis e puros filhos de-Theos sem-mácula meio geração perversa e tendo-sido-pervertida em o qual apareceis como luminares em ao-mundo');
INSERT INTO verses VALUES (29460, 50, 2, 16, 'palavra da-vida retendo para orgulho mim para dia de-Christos que não para vazio correram nem para vazio trabalhei');
INSERT INTO verses VALUES (29461, 50, 2, 17, 'mas se e sou-derramado-como-libação sobre o sacrifício e serviço-litúrgico o da-fé vosso alegro-me e alegro-me-junto todos a-vós');
INSERT INTO verses VALUES (29462, 50, 2, 18, 'o porém ele e vós alegrai-vos e alegrai-vos-comigo a-mim');
INSERT INTO verses VALUES (29463, 50, 2, 19, 'Espero porém em ao-Kyrios Iesous Timóteo rapidamente enviar a-vós para que e-eu tenho-bom-ânimo sabendo o acerca-de vosso');
INSERT INTO verses VALUES (29464, 50, 2, 20, 'a-ninguém pois tenho De-igual-ânimo qualquer-que genuinamente o acerca-de vosso preocupar-se-á');
INSERT INTO verses VALUES (29465, 50, 2, 21, 'o todos pois o deles-mesmos buscam não o de-Christos Iesous');
INSERT INTO verses VALUES (29466, 50, 2, 22, 'o porém prova dele sabeis que como pai filho com mim serviu para o evangelho');
INSERT INTO verses VALUES (29467, 50, 2, 23, 'este por-um-lado portanto espero enviar como partícula-condicional veja o acerca-de mim imediatamente');
INSERT INTO verses VALUES (29468, 50, 2, 24, 'tenho-confiado porém em ao-Kyrios que e ele rapidamente virei');
INSERT INTO verses VALUES (29469, 50, 2, 25, 'necessário porém considerei Epafrodito o irmão e cooperador e co-soldado meu vosso porém apóstolo e ministro o necessidade meu enviar junto-a vos');
INSERT INTO verses VALUES (29470, 50, 2, 26, 'uma-vez-que desejando-ardentemente era todos vos e angustiando-se porque ouvistes que adoeceu');
INSERT INTO verses VALUES (29471, 50, 2, 27, 'e pois adoeceu semelhante morte mas o Theos teve-misericórdia ele não ele porém somente mas e me para que não tristeza sobre tristeza tenha');
INSERT INTO verses VALUES (29472, 50, 2, 28, 'mais-diligentemente portanto enviei ele para que vendo ele novamente alegreis-vos e-eu menos-triste Ômega');
INSERT INTO verses VALUES (29473, 50, 2, 29, 'recebei portanto ele em ao-Kyrios com toda alegria e o tais honrados tendes');
INSERT INTO verses VALUES (29474, 50, 2, 30, 'que através-de o obra de-Christos até da-morte aproximou-se tendo-arriscado o alma para que preencha o vosso falta o para me serviço');
INSERT INTO chapters VALUES (1106, 50, 3, 21);
INSERT INTO verses VALUES (29475, 50, 3, 1, 'o restante irmãos meu alegrai-vos em ao-Kyrios o elas escrever a-vós mim por-um-lado não preguiçoso a-vós porém seguro');
INSERT INTO verses VALUES (29476, 50, 3, 2, 'Vede o cães vede o maus trabalhadores vede o mutilação');
INSERT INTO verses VALUES (29477, 50, 3, 3, 'nós pois somos o circuncisão o Espírito de-Theos servindo-sagradamente e gloriando-se em em-Christos Iesous e não em carne tendo-confiado');
INSERT INTO verses VALUES (29478, 50, 3, 4, 'embora eu tendo confiança e em na-carne se alguém parece outro ter-confiado em na-carne eu mais');
INSERT INTO verses VALUES (29479, 50, 3, 5, 'circuncisão de-oito-dias de raça Israel tribo Benjamim Hebreu de Hebreus segundo lei fariseu');
INSERT INTO verses VALUES (29480, 50, 3, 6, 'segundo zelo perseguindo o igreja segundo justiça o em lei tendo-se-tornado irrepreensível');
INSERT INTO verses VALUES (29481, 50, 3, 7, 'mas quaisquer era a-mim lucros estas-coisas tenho-considerado através-de o Christos perda');
INSERT INTO verses VALUES (29482, 50, 3, 8, 'mas por-um-lado portanto pois e considero todas-as-coisas perda ser através-de o Excedendo o do-conhecimento de-Christos Iesous o do-Kyrios meu através-de o qual o todas-as-coisas sofri-perda e considero refugo para que Christos ganhe');
INSERT INTO verses VALUES (29483, 50, 3, 9, 'e seja-encontrado em a ele não tendo minha justiça o de da-lei mas o através-de da-fé de-Christos o de de-Theos justiça sobre o fé');
INSERT INTO verses VALUES (29484, 50, 3, 10, 'o conhecer ele e o poder o da-ressurreição dele e comunhão sofrimentos dele sendo-conformado o morte dele');
INSERT INTO verses VALUES (29485, 50, 3, 11, 'se como chegarei para o ressurreição-dentre o de mortos');
INSERT INTO verses VALUES (29486, 50, 3, 12, 'não que já receberam ou já tenho-sido-aperfeiçoado persigo porém se e alcance sobre o qual e fui-alcançado sob de-Christos Iesous');
INSERT INTO verses VALUES (29487, 50, 3, 13, 'irmãos eu a-mim-mesmo ainda-não considero ter-alcançado um e/mas o por-um-lado atrás esquecendo-se o porém diante estendendo-se-para');
INSERT INTO verses VALUES (29488, 50, 3, 14, 'segundo alvo persigo para o prêmio o acima chamado o de-Theos em em-Christos Iesous');
INSERT INTO verses VALUES (29489, 50, 3, 15, 'quanto portanto perfeitos isto pensemos e se algo De-outro-modo pensais e isto o Theos a-vós revelação');
INSERT INTO verses VALUES (29490, 50, 3, 16, 'exceto para o qual chegamos o a ele caminhar');
INSERT INTO verses VALUES (29491, 50, 3, 17, 'Co-imitadores meu tornai-vos irmãos e observai o assim andando assim-como tendes modelo nos');
INSERT INTO verses VALUES (29492, 50, 3, 18, 'muitos pois andam o qual muitas-vezes diziam a-vós agora porém e chorando digo o inimigos o da-cruz o de-Christos');
INSERT INTO verses VALUES (29493, 50, 3, 19, 'o qual o fim perdição o qual o Theos o ventre e o glória em o vergonha deles o o terrenas pensando');
INSERT INTO verses VALUES (29494, 50, 3, 20, 'nosso pois o cidadania em nos-céus existe de o qual e Salvador aguardamos-ansiosamente Kyrion Iesous Christon');
INSERT INTO verses VALUES (29495, 50, 3, 21, 'o qual transformará o corpo o de-humilhação nosso conforme o corpo o da-glória dele segundo o operação o poder ele e sujeitar a ele o todas-as-coisas');
INSERT INTO chapters VALUES (1107, 50, 4, 23);
INSERT INTO verses VALUES (29496, 50, 4, 1, 'de-modo-que irmãos meu amados e ardentemente-desejados alegria e coroa meu assim permanecei-firmes em ao-Kyrios amados');
INSERT INTO verses VALUES (29497, 50, 4, 2, 'Evódia rogo e Síntique rogo o ele pensar em ao-Kyrios');
INSERT INTO verses VALUES (29498, 50, 4, 3, 'sim peço e te genuíno companheiro-de-jugo auxilia-juntamente elas as-quais em o no-evangelho combateram-junto a-mim com e Clemente e o restantes cooperando meu o qual o nomes em livro da-vida');
INSERT INTO verses VALUES (29499, 50, 4, 4, 'Alegrai-vos em ao-Kyrios sempre novamente direi alegrai-vos');
INSERT INTO verses VALUES (29500, 50, 4, 5, 'o moderado vosso seja-conhecido todos aos-homens o Kyrios perto');
INSERT INTO verses VALUES (29501, 50, 4, 6, 'nada andais-ansiosos mas em todo o oração e o súplica com ação-de-graças o pedidos vosso seja-feito-conhecer junto-a o Theos');
INSERT INTO verses VALUES (29502, 50, 4, 7, 'e o paz o de-Theos o Que-excede todas-as-coisas entendimento guardará o do-coração vosso e o pensamentos vosso em em-Christos Iesous');
INSERT INTO verses VALUES (29503, 50, 4, 8, 'o restante irmãos quanto é verdadeiras quanto dignos quanto justas quanto puras quanto amáveis quanto respeitáveis se alguém virtude e se alguém louvor estas-coisas considerai');
INSERT INTO verses VALUES (29504, 50, 4, 9, 'o qual e aprendestes e recebestes e ouvistes e vistes em me estas-coisas praticais e o Theos o paz será com vosso');
INSERT INTO verses VALUES (29505, 50, 4, 10, 'Alegrei-me porém em ao-Kyrios grandemente que já alguma-vez reverdecestes o em-favor-de mim pensar sobre o qual e Pensáveis tínheis-falta-de-oportunidade e/mas');
INSERT INTO verses VALUES (29506, 50, 4, 11, 'não que segundo Falta digo eu pois Aprenderam em o qual sou autossuficiente ser');
INSERT INTO verses VALUES (29507, 50, 4, 12, 'sei e ser-humilhado sei e abundar em todo e em todos tenho-sido-iniciado e ser-saciado e ter-fome e abundar e ter-falta');
INSERT INTO verses VALUES (29508, 50, 4, 13, 'todas-as-coisas sou-capaz em o fortalecendo me');
INSERT INTO verses VALUES (29509, 50, 4, 14, 'exceto bem fizestes tendo-participado-com meu o tribulação');
INSERT INTO verses VALUES (29510, 50, 4, 15, 'sei porém e vós Filipenses que em princípio o evangelho quando saíram de Macedônia nenhuma a-mim assembleia participou para palavra dádiva e recebimento se não vós sós');
INSERT INTO verses VALUES (29511, 50, 4, 16, 'que e em Tessalônica e uma-vez e duas-vezes para o necessidade a-mim enviastes');
INSERT INTO verses VALUES (29512, 50, 4, 17, 'não que busco o dom mas busco o fruto o abundando para palavra vosso');
INSERT INTO verses VALUES (29513, 50, 4, 18, 'tenho-recebido porém todas-as-coisas e abundo tenho-sido-preenchido tendo-recebido de-junto-de Epafrodito o de-junto-de vosso cheiro fragrância sacrifício aceitável agradável o a-Theos');
INSERT INTO verses VALUES (29514, 50, 4, 19, 'o porém Theos meu cumprirá toda necessidade vosso segundo o riqueza dele em glória em em-Christos Iesous');
INSERT INTO verses VALUES (29515, 50, 4, 20, 'o porém a-Theos e Pai nosso o glória para o eras o eras amém');
INSERT INTO verses VALUES (29516, 50, 4, 21, 'Saudai todas-as-coisas santo em em-Christos Iesous saúdam vos o com mim irmãos');
INSERT INTO verses VALUES (29517, 50, 4, 22, 'saúdam vos todos o santos principalmente porém o de o de-César da-casa');
INSERT INTO verses VALUES (29518, 50, 4, 23, 'o graça o do-Kyrios Iesous de-Christos com o do-espírito vosso');
INSERT INTO books VALUES (51, 'COL', 'Colossenses', 'NT', 4);
INSERT INTO chapters VALUES (1108, 51, 1, 29);
INSERT INTO verses VALUES (29519, 51, 1, 1, 'Paulo apóstolo de-Christos Iesous através-de da-vontade de-Theos e Timóteo o irmão');
INSERT INTO verses VALUES (29520, 51, 1, 2, 'o em Colossos santos e fiéis aos-irmãos em em-Christos graça a-vós e paz de de-Theos do-Pai nosso');
INSERT INTO verses VALUES (29521, 51, 1, 3, 'Damos-graças o a-Theos Pai o do-Kyrios nosso Iesous de-Christos sempre acerca-de vosso orando');
INSERT INTO verses VALUES (29522, 51, 1, 4, 'ouvindo o fé vosso em em-Christos Iesous e o amor o qual tendes para todos o santos');
INSERT INTO verses VALUES (29523, 51, 1, 5, 'através-de o esperança o tendo-sido-reservada a-vós em o nos-céus o qual ouvistes-antes em o em-palavra o da-verdade o evangelho');
INSERT INTO verses VALUES (29524, 51, 1, 6, 'o estando-presente para vos assim-como e em todo o ao-mundo é frutificando e crescendo assim-como e em a-vós de o qual do-dia ouvistes e conhecestes-plenamente o graça o de-Theos em verdade');
INSERT INTO verses VALUES (29525, 51, 1, 7, 'assim-como aprendestes de Epafras o amado co-servo nosso o qual é fiel em-favor-de vosso servo o de-Christos');
INSERT INTO verses VALUES (29526, 51, 1, 8, 'o e tendo-manifestado a-nós o vosso amor em Espírito');
INSERT INTO verses VALUES (29527, 51, 1, 9, 'através-de isto e nós de o qual do-dia ouvimos não cessamos em-favor-de vosso orando e pedindo para que sejais-preenchidos o conhecimento-pleno o da-vontade dele em toda com-sabedoria e entendimento espiritual');
INSERT INTO verses VALUES (29528, 51, 1, 10, 'andar dignamente o do-Kyrios para toda agrado em todo obra bom frutificando e crescendo o conhecimento-pleno o de-Theos');
INSERT INTO verses VALUES (29529, 51, 1, 11, 'em toda poder sendo-fortalecidos segundo o domínio o da-glória dele para toda perseverança e paciência com alegria');
INSERT INTO verses VALUES (29530, 51, 1, 12, 'dando-graças o Pai o Tendo-capacitado vos para o porção o herança o santos em o luz');
INSERT INTO verses VALUES (29531, 51, 1, 13, 'o qual livrou nos de o da-autoridade o das-trevas e removeu para o reino o do-Filho o do-amor dele');
INSERT INTO verses VALUES (29532, 51, 1, 14, 'em o qual temos o redenção o perdão o pecados');
INSERT INTO verses VALUES (29533, 51, 1, 15, 'o qual é imagem o de-Theos o invisível primogênito toda criação');
INSERT INTO verses VALUES (29534, 51, 1, 16, 'que em a ele foi-criado o todas-as-coisas em o nos-céus e sobre o da-terra o visíveis e o invisíveis seja tronos seja senhorios seja principados seja autoridades o todas-as-coisas através-de dele e para ele Tem-sido-criado');
INSERT INTO verses VALUES (29535, 51, 1, 17, 'e ele é antes-de todos e o todas-as-coisas em a ele subsiste');
INSERT INTO verses VALUES (29536, 51, 1, 18, 'e ele é o cabeça o do-corpo o da-assembleia o qual é princípio primogênito de o mortos para que aconteça em todos ele tendo-a-primazia');
INSERT INTO verses VALUES (29537, 51, 1, 19, 'que em a ele agradou-se todo o plenitude habitar');
INSERT INTO verses VALUES (29538, 51, 1, 20, 'e através-de dele reconciliar o todas-as-coisas para ele tendo-feito-paz através-de o sangue o da-cruz dele através-de dele seja o sobre o da-terra seja o em o nos-céus');
INSERT INTO verses VALUES (29539, 51, 1, 21, 'e vos alguma-vez sendo tendo-sido-alienados e inimigos o entendimento em o obra o maus');
INSERT INTO verses VALUES (29540, 51, 1, 22, 'agora porém reconciliou em o corpo o carne dele através-de o da-morte apresentar vos santos e irrepreensíveis e irrepreensíveis diante-de dele');
INSERT INTO verses VALUES (29541, 51, 1, 23, 'se pois permaneceis o fé tendo-sido-fundamentados e firmes e não sendo-movidos de o da-esperança o evangelho o qual ouvistes o tendo-sido-proclamado em toda criação o sob o céu o qual tornei-me eu Paulo servo');
INSERT INTO verses VALUES (29542, 51, 1, 24, 'agora alegro-me em o sofrimentos em-favor-de vosso e completo-no-lugar o carências o tribulações o de-Christos em o na-carne meu em-favor-de o do-corpo dele o qual é o assembleia');
INSERT INTO verses VALUES (29543, 51, 1, 25, 'o qual tornei-me eu servo segundo o administração o de-Theos o dada a-mim para vos cumprir o palavra o de-Theos');
INSERT INTO verses VALUES (29544, 51, 1, 26, 'o mistério o tendo-sido-escondido de o eras e de o gerações agora porém foi-manifestado o santos dele');
INSERT INTO verses VALUES (29545, 51, 1, 27, 'o qual quis o Theos fazer-conhecer quê o riqueza o da-glória o mistério deste em o nações o qual é Christos em a-vós o esperança o da-glória');
INSERT INTO verses VALUES (29546, 51, 1, 28, 'o qual nós anunciamos admoestando todas-as-coisas homem e ensinando todas-as-coisas homem em toda com-sabedoria para que apresentemos todas-as-coisas homem perfeito em em-Christos');
INSERT INTO verses VALUES (29547, 51, 1, 29, 'para o qual e trabalho lutando segundo o operação dele o sendo-operada em mim em poder');
INSERT INTO chapters VALUES (1109, 51, 2, 23);
INSERT INTO verses VALUES (29548, 51, 2, 1, 'quero pois vos sei quão-grande luta tenho em-favor-de vosso e o em Laodiceia e quanto não Viram o face meu em na-carne');
INSERT INTO verses VALUES (29549, 51, 2, 2, 'para que sejam-consolados o corações deles tendo-sido-unidos em amor e para todo riqueza o plena-convicção o entendimento para conhecimento-pleno o mistério o de-Theos de-Christos');
INSERT INTO verses VALUES (29550, 51, 2, 3, 'em o qual são todos o tesouros o da-sabedoria e do-conhecimento ocultos');
INSERT INTO verses VALUES (29551, 51, 2, 4, 'isto digo para que ninguém vos engane em discurso-persuasivo');
INSERT INTO verses VALUES (29552, 51, 2, 5, 'se pois e o carne estou-ausente mas o espírito com a-vós sou alegrando-se e vendo vosso o ordem e o firmeza o para Christos da-fé vosso');
INSERT INTO verses VALUES (29553, 51, 2, 6, 'como portanto recebestes o Christos Iesous o Kyrion em a ele andai');
INSERT INTO verses VALUES (29554, 51, 2, 7, 'tendo-sido-enraizados e Sendo-edificados-sobre em a ele e sendo-confirmados o fé assim-como fostes-ensinados abundando em ação-de-graças');
INSERT INTO verses VALUES (29555, 51, 2, 8, 'Vede não alguém vos será o fazendo-presa através-de o filosofia e vazia engano segundo o tradição o dos-homens segundo o elementos o do-mundo e não segundo Christon');
INSERT INTO verses VALUES (29556, 51, 2, 9, 'que em a ele habita todo o plenitude o divindade corporalmente');
INSERT INTO verses VALUES (29557, 51, 2, 10, 'e sois em a ele tendo-sido-preenchidos o qual é o cabeça toda princípio e da-autoridade');
INSERT INTO verses VALUES (29558, 51, 2, 11, 'em o qual e fostes-circuncidados circuncisão não-feito-por-mãos em o despojamento o do-corpo o carne em o circuncisão o de-Christos');
INSERT INTO verses VALUES (29559, 51, 2, 12, 'co-sepultados a ele em o batismo em o qual e fostes-ressuscitados-junto através-de o da-fé o operação o de-Theos o tendo-levantado ele de mortos');
INSERT INTO verses VALUES (29560, 51, 2, 13, 'e vos mortos sendo o transgressões e o incircuncisão o carne vosso vivificou-junto vos com a ele tendo-perdoado a-nós todas-as-coisas o transgressões');
INSERT INTO verses VALUES (29561, 51, 2, 14, 'tendo-apagado o segundo nosso escrito-à-mão o decretos o qual era Contrário a-nós e ele Tem-bastado de o meio tendo-pregado ele o cruz');
INSERT INTO verses VALUES (29562, 51, 2, 15, 'tendo-se-despojado o principados e o da-autoridade expôs-publicamente em com-ousadia tendo-triunfado eles em a ele');
INSERT INTO verses VALUES (29563, 51, 2, 16, 'não portanto alguém vos julgue em alimento e em em-quantidade ou em parte festa ou lua-nova ou sábados');
INSERT INTO verses VALUES (29564, 51, 2, 17, 'o qual é sombra o estando-para o porém corpo o de-Christos');
INSERT INTO verses VALUES (29565, 51, 2, 18, 'ninguém vos desqualifique querendo em humildade-de-mente e religião o anjo o qual Tem-visto adentrando em-vão inchando-se sob o mente o carne dele');
INSERT INTO verses VALUES (29566, 51, 2, 19, 'e não segurando o Cabeça de o qual todo o corpo através-de o toques e ligaduras Sendo-suprido e sendo-unido-junto faz-crescer o crescimento o de-Theos');
INSERT INTO verses VALUES (29567, 51, 2, 20, 'se morrestes com em-Christos de o elementos o do-mundo quê como vivos em ao-mundo sujeitais-vos-a-ordenanças');
INSERT INTO verses VALUES (29568, 51, 2, 21, 'não toques nem proves nem toques');
INSERT INTO verses VALUES (29569, 51, 2, 22, 'o qual é todas-as-coisas para corrupção o uso-pleno segundo o mandamentos e ensino o dos-homens');
INSERT INTO verses VALUES (29570, 51, 2, 23, 'as-quais é palavra por-um-lado tendo da-sabedoria em culto-voluntário e humildade-de-mente e severidade do-corpo não em honra a-alguém junto-a saciedade o carne');
INSERT INTO chapters VALUES (1110, 51, 3, 25);
INSERT INTO verses VALUES (29571, 51, 3, 1, 'se portanto fostes-ressuscitados-junto o em-Christos o acima buscais do-qual o Christos é em direita o de-Theos sentado');
INSERT INTO verses VALUES (29572, 51, 3, 2, 'o acima pensais não o sobre o da-terra');
INSERT INTO verses VALUES (29573, 51, 3, 3, 'morrestes pois e o vida vosso tem-sido-escondido com o em-Christos em o a-Theos');
INSERT INTO verses VALUES (29574, 51, 3, 4, 'quando o Christos seja-manifestada o vida nosso então e vós com a ele sereis-manifestados em glória');
INSERT INTO verses VALUES (29575, 51, 3, 5, 'Mortificai portanto o membros o sobre o da-terra prostituição impureza paixão desejo má e o ganância a-qual é idolatria');
INSERT INTO verses VALUES (29576, 51, 3, 6, 'através-de o qual vem o ira o de-Theos');
INSERT INTO verses VALUES (29577, 51, 3, 7, 'em o qual e vós andastes alguma-vez quando vivíeis em nestes');
INSERT INTO verses VALUES (29578, 51, 3, 8, 'agora porém despoji-vos e vós o todas-as-coisas ira furor malícia blasfêmia linguagem-torpe de o boca vosso');
INSERT INTO verses VALUES (29579, 51, 3, 9, 'não mentis para uns-aos-outros tendo-se-despojado o velho homem com o práticas dele');
INSERT INTO verses VALUES (29580, 51, 3, 10, 'e vestidos o novo o sendo-renovado para conhecimento-pleno segundo imagem o tendo-criado ele');
INSERT INTO verses VALUES (29581, 51, 3, 11, 'onde não há grego e judeu circuncisão e incircuncisão bárbaro Cita servo livre mas todas-as-coisas e em todos Christos');
INSERT INTO verses VALUES (29582, 51, 3, 12, 'Revesti-vos portanto como escolhidos o de-Theos santos e tendo-sido-amados entranhas compaixão benignidade humildade-de-mente mansidão paciência');
INSERT INTO verses VALUES (29583, 51, 3, 13, 'suportando uns-aos-outros e concedendo-graciosamente si-mesmos se alguém para alguém tenha queixa assim-como e o Kyrios concedeu-graciosamente a-vós assim e vós');
INSERT INTO verses VALUES (29584, 51, 3, 14, 'sobre todos porém nestes o amor o qual é vínculo o de-perfeição');
INSERT INTO verses VALUES (29585, 51, 3, 15, 'e o paz o de-Christos governe em o corações vosso para o qual e fostes-chamados em um corpo e agradecidos tornai-vos');
INSERT INTO verses VALUES (29586, 51, 3, 16, 'o palavra o de-Christos habite-em em a-vós ricamente em toda com-sabedoria ensinando e admoestando si-mesmos salmos hinos cânticos espirituais em o graça cantando em o corações vosso o a-Theos');
INSERT INTO verses VALUES (29587, 51, 3, 17, 'e todo o qual algo se façais em em-palavra ou em obra todas-as-coisas em em-nome do-Kyrios Iesous dando-graças o a-Theos Pai através-de dele');
INSERT INTO verses VALUES (29588, 51, 3, 18, 'o mulheres Sujeitai-vos o homens como convinha em ao-Kyrios');
INSERT INTO verses VALUES (29589, 51, 3, 19, 'o homens amai o mulheres e não amargurai-vos junto-a elas');
INSERT INTO verses VALUES (29590, 51, 3, 20, 'o filhos obedecei o pais segundo todas-as-coisas isto pois agradável é em ao-Kyrios');
INSERT INTO verses VALUES (29591, 51, 3, 21, 'o pais não Provoqueis o filhos vosso para que não desanimem');
INSERT INTO verses VALUES (29592, 51, 3, 22, 'o servos obedecei segundo todas-as-coisas o segundo carne senhores não em serviços-para-os-olhos como agradadores-de-homens mas em simplicidade do-coração tementes o Kyrion');
INSERT INTO verses VALUES (29593, 51, 3, 23, 'o qual se façais de alma trabalhai como o ao-Kyrios e não aos-homens');
INSERT INTO verses VALUES (29594, 51, 3, 24, 'sei que de do-Kyrios recebereis o retribuição o herança o ao-Kyrios em-Christos servis');
INSERT INTO verses VALUES (29595, 51, 3, 25, 'o pois praticando-injustiça receberá o qual cometeu-injustiça e não é acepção-de-pessoas');
INSERT INTO chapters VALUES (1111, 51, 4, 18);
INSERT INTO verses VALUES (29596, 51, 4, 1, 'o senhores o justo e o Igualdade o servos forneceis sei que e vós tendes Kyrion em no-céu');
INSERT INTO verses VALUES (29597, 51, 4, 2, 'o oração perseverai vigiando em a-ela em ação-de-graças');
INSERT INTO verses VALUES (29598, 51, 4, 3, 'orando juntamente e acerca-de nosso para que o Theos abra a-nós porta o da-palavra falar o mistério o de-Christos através-de o qual e tenho-sido-amarrado');
INSERT INTO verses VALUES (29599, 51, 4, 4, 'para que manifestarei ele como é necessário me falar');
INSERT INTO verses VALUES (29600, 51, 4, 5, 'em com-sabedoria andai junto-a o fora o tempo resgatando');
INSERT INTO verses VALUES (29601, 51, 4, 6, 'o palavra vosso sempre em graça sal tendo-sido-temperado sei como é necessário vos um a-cada-um responder');
INSERT INTO verses VALUES (29602, 51, 4, 7, 'o segundo mim todas-as-coisas fará-conhecer a-vós Tíquico o amado irmão e fiel servo e co-servo em ao-Kyrios');
INSERT INTO verses VALUES (29603, 51, 4, 8, 'o qual enviei junto-a vos para ele isto para que conheçais o acerca-de nosso e exorte o do-coração vosso');
INSERT INTO verses VALUES (29604, 51, 4, 9, 'com Onésimo o fiel e amado ao-irmão o qual é de vosso todas-as-coisas a-vós farão-conhecer o aqui');
INSERT INTO verses VALUES (29605, 51, 4, 10, 'Saúda vos Aristarco o co-prisioneiro meu e Marcos o primo Barnabé acerca-de o qual recebestes mandamentos se venha junto-a vos recebei ele');
INSERT INTO verses VALUES (29606, 51, 4, 11, 'e Iesous o chamado Justo o sendo de da-circuncisão estes sós cooperadores para o reino o de-Theos os-quais tornaram-se a-mim consolo');
INSERT INTO verses VALUES (29607, 51, 4, 12, 'saúda vos Epafras o de vosso servo de-Christos Iesous sempre lutando em-favor-de vosso em o orações para que sejais-postos-de-pé perfeitos e tendo-sido-plenamente-assegurados em todo vontade o de-Theos');
INSERT INTO verses VALUES (29608, 51, 4, 13, 'testemunho pois a ele que tem muito dor em-favor-de vosso e o em Laodiceia e o em Hierápolis');
INSERT INTO verses VALUES (29609, 51, 4, 14, 'saúda vos Lucas o médico o amado e Demas');
INSERT INTO verses VALUES (29610, 51, 4, 15, 'Saudai o em Laodiceia irmãos e Ninfa e o segundo casa dela igreja');
INSERT INTO verses VALUES (29611, 51, 4, 16, 'e quando seja-lida de a-vós o carta fazei para que e em o Laodiceia assembleia seja-lida e o de Laodiceia para que e vós leiais');
INSERT INTO verses VALUES (29612, 51, 4, 17, 'e dizei Arquipo Olha o serviço o qual recebeste em ao-Kyrios para que ela preenchesses');
INSERT INTO verses VALUES (29613, 51, 4, 18, 'o saudação o minha mão Paulo lembrai meu o prisões o graça com vosso');
INSERT INTO books VALUES (52, '1TH', '1 Tessalonicenses', 'NT', 5);
INSERT INTO chapters VALUES (1112, 52, 1, 10);
INSERT INTO verses VALUES (29614, 52, 1, 1, 'Paulo e Silvano e Timóteo o assembleia Tessalonicenses em a-Theos Pai e ao-Kyrios Iesous em-Christos graça a-vós e paz');
INSERT INTO verses VALUES (29615, 52, 1, 2, 'Damos-graças o a-Theos sempre acerca-de todos vosso menção fazendo sobre o orações nosso incessantemente');
INSERT INTO verses VALUES (29616, 52, 1, 3, 'lembrando vosso o obra o da-fé e o trabalho o do-amor e o perseverança o da-esperança o do-Kyrios nosso Iesous de-Christos diante o de-Theos e do-Pai nosso');
INSERT INTO verses VALUES (29617, 52, 1, 4, 'sei irmãos tendo-sido-amados sob o de-Theos o eleição vosso');
INSERT INTO verses VALUES (29618, 52, 1, 5, 'que o evangelho nosso não aconteceu para vos em em-palavra somente mas e em poder e em Espírito no-santo e plena-convicção muita assim-como sei quais tornamo-nos em a-vós através-de vos');
INSERT INTO verses VALUES (29619, 52, 1, 6, 'e vós imitadores nosso tornastes-vos e o do-Kyrios tendo-recebido o palavra em tribulação muita com alegria do-espírito do-santo');
INSERT INTO verses VALUES (29620, 52, 1, 7, 'de-modo-que tornar-se vos modelo todos o creem em o Macedônia e em o Acaia');
INSERT INTO verses VALUES (29621, 52, 1, 8, 'de vosso pois tem-ressoado o palavra o do-Kyrios não somente em o Macedônia e Acaia mas em todo no-lugar o fé vosso o junto-a o Theos tem-saído de-modo-que não necessidade ter nos falar algo');
INSERT INTO verses VALUES (29622, 52, 1, 9, 'eles-mesmos pois acerca-de nosso anunciam qual entrada Tivemos junto-a vos e como convertestes junto-a o Theos de o ídolos servir a-Theos vivendo e verdadeiro');
INSERT INTO verses VALUES (29623, 52, 1, 10, 'e aguardar o Filho dele de o dos-céus o qual ressuscitou de o mortos Iesous o livrando nos de o ira o Vindo');
INSERT INTO chapters VALUES (1113, 52, 2, 20);
INSERT INTO verses VALUES (29624, 52, 2, 1, 'Eles-mesmos pois sei irmãos o entrada nosso o junto-a vos que não vazia aconteceu');
INSERT INTO verses VALUES (29625, 52, 2, 2, 'mas tendo-sofrido-antes e tendo-sido-ultrajados assim-como sei em Filipos falamos-com-ousadia em o a-Theos nosso falar junto-a vos o evangelho o de-Theos em muito combate');
INSERT INTO verses VALUES (29626, 52, 2, 3, 'o pois consolação nosso não de engano nem de impureza nem em engano');
INSERT INTO verses VALUES (29627, 52, 2, 4, 'mas assim-como temos-sido-aprovados sob o de-Theos ser-crido o evangelho assim falamos não como aos-homens agradando mas a-Theos o examinando o do-coração nosso');
INSERT INTO verses VALUES (29628, 52, 2, 5, 'nem pois alguma-vez em em-palavra lisonja tornamo-nos assim-como sei nem em pretexto ganância Theos testemunha');
INSERT INTO verses VALUES (29629, 52, 2, 6, 'nem buscando de dos-homens glória nem de vosso nem de outros');
INSERT INTO verses VALUES (29630, 52, 2, 7, 'podendo em peso ser como de-Christos apóstolos mas tornamo-nos Gentis em meio vosso como se nutriz cuide o de-si-mesma filhos');
INSERT INTO verses VALUES (29631, 52, 2, 8, 'assim desejando-ardentemente vosso temos-prazer repartir a-vós não somente o evangelho o de-Theos mas e o deles-mesmos almas porque amados a-nós tornastes-vos');
INSERT INTO verses VALUES (29632, 52, 2, 9, 'lembrai-vos pois irmãos o trabalho nosso e o labuta da-noite e do-dia trabalhando junto-a o não sobrecarregar alguém vosso proclamamos para vos o evangelho o de-Theos');
INSERT INTO verses VALUES (29633, 52, 2, 10, 'vós testemunhas e o Theos como santamente e justamente e irrepreesivelmente a-vós o creem tornamo-nos');
INSERT INTO verses VALUES (29634, 52, 2, 11, 'assim-como sei como um cada-um vosso como Pai filhos si-mesmo');
INSERT INTO verses VALUES (29635, 52, 2, 12, 'exortando vos e consolando e testificando para o andar vos dignamente o de-Theos o chamante vos para o si-mesmo reino e glória');
INSERT INTO verses VALUES (29636, 52, 2, 13, 'e através-de isto e nós damos-graças o a-Theos incessantemente que tendo-recebido palavra ouvido de nosso o de-Theos recebestes não palavra dos-homens mas assim-como verdadeiramente é palavra de-Theos o qual e é-operado em a-vós o creem');
INSERT INTO verses VALUES (29637, 52, 2, 14, 'vós pois imitadores tornastes-vos irmãos o igrejas o de-Theos o sendo em o Judeia em em-Christos Iesous que o elas sofrestes e vós sob o próprios compatriotas assim-como e eles-mesmos sob o judeus');
INSERT INTO verses VALUES (29638, 52, 2, 15, 'o e o Kyrion dos-que-mataram Iesous e o profetas e nos tendo-perseguido e a-Theos não agradando e todos aos-homens contrários');
INSERT INTO verses VALUES (29639, 52, 2, 16, 'impedindo nos o nações falar para que sejam-salvos para o preencher deles o do-pecado sempre chegou porém sobre eles o ira para fim');
INSERT INTO verses VALUES (29640, 52, 2, 17, 'nós e/mas irmãos tendo-sido-tornados-órfãos de vosso junto-a tempo hora face não no-coração ainda-mais Nos-esforçamos o face vosso ver em muita desejo');
INSERT INTO verses VALUES (29641, 52, 2, 18, 'porque quisemos vir junto-a vos eu por-um-lado Paulo e uma-vez e duas-vezes e impediu nos o Satanás');
INSERT INTO verses VALUES (29642, 52, 2, 19, 'quem pois nosso esperança ou alegria ou coroa glorificação ou não e vós diante o do-Kyrios nosso Iesous em o dele presença');
INSERT INTO verses VALUES (29643, 52, 2, 20, 'vós pois sois o glória nosso e o alegria');
INSERT INTO chapters VALUES (1114, 52, 3, 13);
INSERT INTO verses VALUES (29644, 52, 3, 1, 'por-isso não-mais suportando comprazemo-nos ser-deixado em Atenas sós');
INSERT INTO verses VALUES (29645, 52, 3, 2, 'e enviamos Timóteo o irmão nosso e servo o de-Theos em o no-evangelho o de-Christos para o firmar vos e consolar em-favor-de o da-fé vosso');
INSERT INTO verses VALUES (29646, 52, 3, 3, 'o ninguém ser-abalado em o tribulações estas eles-mesmos pois sei que para isto jazemos');
INSERT INTO verses VALUES (29647, 52, 3, 4, 'e pois quando junto-a vos éramos dizíamos-de-antemão a-vós que estamos-a-ponto-de ser-afligido assim-como e aconteceu e sei');
INSERT INTO verses VALUES (29648, 52, 3, 5, 'através-de isto e-eu não-mais suportando enviei para o conhecer o fé vosso não como tentou vos o tentando e para vazio aconteça o labor nosso');
INSERT INTO verses VALUES (29649, 52, 3, 6, 'Agora porém tendo-vindo Timóteo junto-a nos de vosso e tendo-anunciado-boas-novas a-nós o fé e o amor vosso e que tendes menção nosso boa sempre desejando-ardentemente nos ver assim-como e nós vos');
INSERT INTO verses VALUES (29650, 52, 3, 7, 'através-de isto fomos-exortados irmãos sobre a-vós sobre toda o necessidade e tribulação nosso através-de o vosso da-fé');
INSERT INTO verses VALUES (29651, 52, 3, 8, 'que agora vivamos se vós permanecei-firmes em ao-Kyrios');
INSERT INTO verses VALUES (29652, 52, 3, 9, 'quem pois ação-de-graças podemos o a-Theos retribuir acerca-de vosso sobre toda o alegria o qual alegramo-nos através-de vos diante-de o de-Theos nosso');
INSERT INTO verses VALUES (29653, 52, 3, 10, 'noite e do-dia superabundantemente suplicando para o ver vosso o face e restaurar o carências o da-fé vosso');
INSERT INTO verses VALUES (29654, 52, 3, 11, 'ele porém o Theos e Pai nosso e o Kyrios nosso Iesous dirigir o caminho nosso junto-a vos');
INSERT INTO verses VALUES (29655, 52, 3, 12, 'vos porém o Kyrios abundar e abundar o amor para uns-aos-outros e para todos assim-como e nós para vos');
INSERT INTO verses VALUES (29656, 52, 3, 13, 'para o firmar vosso o do-coração irrepreensíveis em santidade diante o de-Theos e do-Pai nosso em o presença o do-Kyrios nosso Iesous com todos o santos dele');
INSERT INTO chapters VALUES (1115, 52, 4, 18);
INSERT INTO verses VALUES (29657, 52, 4, 1, 'Quanto-ao-resto portanto irmãos Perguntamos vos e exortamos em ao-Kyrios Iesous para que assim-como recebestes de nosso o como é necessário vos andar e agradar a-Theos assim-como e andai para que abundeis mais');
INSERT INTO verses VALUES (29658, 52, 4, 2, 'sei pois quais ordem demos a-vós através-de o do-Kyrios Iesous');
INSERT INTO verses VALUES (29659, 52, 4, 3, 'isto pois é vontade o de-Theos o santificação vosso abster-se vos de o imoralidade');
INSERT INTO verses VALUES (29660, 52, 4, 4, 'sei cada-um vosso o si-mesmo vaso adquirir em santificação e honra');
INSERT INTO verses VALUES (29661, 52, 4, 5, 'não em sofrimento desejos assim-como e o nações o não sei o Theos');
INSERT INTO verses VALUES (29662, 52, 4, 6, 'o não Transgredir e tirar-vantagem em o assunto o irmão dele porque vingador Kyrios acerca-de todos destes assim-como e dissemos-de-antemão a-vós e testificamos-solenemente');
INSERT INTO verses VALUES (29663, 52, 4, 7, 'não pois chamou nos o Theos sobre impureza mas em santificação');
INSERT INTO verses VALUES (29664, 52, 4, 8, 'portanto o rejeitando não homem rejeita mas o Theos o e dando o espírito dele o santo para vos');
INSERT INTO verses VALUES (29665, 52, 4, 9, 'acerca-de porém o amor-fraternal não necessidade tendes escrever a-vós eles-mesmos pois vós ensinados-por-Theos sois para o amar uns-aos-outros');
INSERT INTO verses VALUES (29666, 52, 4, 10, 'e pois fazei ele para todos o irmãos em toda o Macedônia Exortamos porém vos irmãos abundar mais');
INSERT INTO verses VALUES (29667, 52, 4, 11, 'e ambicionar Estar-quieto e praticar o próprias e trabalhar o mãos vosso assim-como a-vós ordenamos');
INSERT INTO verses VALUES (29668, 52, 4, 12, 'para que andeis decorosamente junto-a o fora e nenhum necessidade tenhais');
INSERT INTO verses VALUES (29669, 52, 4, 13, 'não queremos porém vos ignorar irmãos acerca-de o adormecendo para que não estejais-entristecidos assim-como e o restantes o não tendo esperança');
INSERT INTO verses VALUES (29670, 52, 4, 14, 'se pois cremos que Iesous morreu e levantou-se assim e o Theos o tendo-adormecido através-de o Iesous conduzirá com a ele');
INSERT INTO verses VALUES (29671, 52, 4, 15, 'isto pois a-vós dizemos em em-palavra do-Kyrios que nós o vivos o restando para o vinda o do-Kyrios não não precedamos o tendo-adormecido');
INSERT INTO verses VALUES (29672, 52, 4, 16, 'que ele o Kyrios em ordem em voz arcanjo e em trombeta de-Theos descerá de do-céu e o mortos em em-Christos ressuscitarão primeiro');
INSERT INTO verses VALUES (29673, 52, 4, 17, 'depois nós o vivos o restando juntamente com a-eles seremos-arrebatados em nuvens para encontro o do-Kyrios para ar e assim sempre com ao-Kyrios seremos');
INSERT INTO verses VALUES (29674, 52, 4, 18, 'de-modo-que exortai uns-aos-outros em o palavras nestes');
INSERT INTO chapters VALUES (1116, 52, 5, 28);
INSERT INTO verses VALUES (29675, 52, 5, 1, 'acerca-de porém o tempos e o tempos irmãos não necessidade tendes a-vós ser-escrito');
INSERT INTO verses VALUES (29676, 52, 5, 2, 'eles-mesmos pois com-exatidão sei que dia do-Kyrios como ladrão em à-noite assim vem');
INSERT INTO verses VALUES (29677, 52, 5, 3, 'quando digam paz e segurança então repentino a-eles conhece destruição como o Dor-de-parto o em ventre Tendo e não não escapem');
INSERT INTO verses VALUES (29678, 52, 5, 4, 'vós e/mas irmãos não sois em trevas para que o dia vos como ladrão alcance');
INSERT INTO verses VALUES (29679, 52, 5, 5, 'todos pois vós filhos luz sois e filhos do-dia não somos noite nem das-trevas');
INSERT INTO verses VALUES (29680, 52, 5, 6, 'então portanto não durmamos como o restantes mas vigiemos e sejamos-sóbrios');
INSERT INTO verses VALUES (29681, 52, 5, 7, 'o pois dormindo noite dormem e o embriagando-se noite embriagam-se');
INSERT INTO verses VALUES (29682, 52, 5, 8, 'nós porém do-dia sendo sejamos-sóbrios vestidos couraça da-fé e do-amor e capacete esperança salvação');
INSERT INTO verses VALUES (29683, 52, 5, 9, 'que não pôs nos o Theos para ira mas para aquisição salvação através-de o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (29684, 52, 5, 10, 'o do-que-morreu acerca-de nosso para que seja vigiemos seja durmamos juntamente com a ele vivamos');
INSERT INTO verses VALUES (29685, 52, 5, 11, 'por-isso exortai uns-aos-outros e edificai um o um assim-como e fazei');
INSERT INTO verses VALUES (29686, 52, 5, 12, 'Perguntamos porém vos irmãos sei o labutando em a-vós e presidindo vosso em ao-Kyrios e admoestando vos');
INSERT INTO verses VALUES (29687, 52, 5, 13, 'e Liderar eles Superabundantemente em amor através-de o obra deles tende-paz em si-mesmos');
INSERT INTO verses VALUES (29688, 52, 5, 14, 'Exortamos porém vos irmãos admoestai o desordenados consolai o desanimados apegai-vos o fracos sede-pacientes junto-a todos');
INSERT INTO verses VALUES (29689, 52, 5, 15, 'vede não alguém mau em-troca-de mal a-alguém retribua mas sempre o bom persegui para uns-aos-outros e para todos');
INSERT INTO verses VALUES (29690, 52, 5, 16, 'Sempre alegrai-vos');
INSERT INTO verses VALUES (29691, 52, 5, 17, 'incessantemente orai');
INSERT INTO verses VALUES (29692, 52, 5, 18, 'em todo dai-graças isto pois vontade de-Theos em em-Christos Iesous para vos');
INSERT INTO verses VALUES (29693, 52, 5, 19, 'o espírito não apagais');
INSERT INTO verses VALUES (29694, 52, 5, 20, 'profecia não desprezais');
INSERT INTO verses VALUES (29695, 52, 5, 21, 'todas-as-coisas porém examinai o belo retende');
INSERT INTO verses VALUES (29696, 52, 5, 22, 'de todo forma do-mal abstende-vos');
INSERT INTO verses VALUES (29697, 52, 5, 23, 'ele porém o Theos o paz santificar vos inteiramente e íntegro vosso o espírito e o alma e o corpo irrepreesivelmente em o presença o do-Kyrios nosso Iesous de-Christos fosse-guardado');
INSERT INTO verses VALUES (29698, 52, 5, 24, 'fiel o boas vos o qual e fará');
INSERT INTO verses VALUES (29699, 52, 5, 25, 'Irmãos orai acerca-de nosso');
INSERT INTO verses VALUES (29700, 52, 5, 26, 'Saudai o irmãos todos em beijo no-santo');
INSERT INTO verses VALUES (29701, 52, 5, 27, 'Adjuro vos o Kyrion ser-lida o carta todos o aos-irmãos');
INSERT INTO verses VALUES (29702, 52, 5, 28, 'o graça o do-Kyrios nosso Iesous de-Christos com vosso');
INSERT INTO books VALUES (53, '2TH', '2 Tessalonicenses', 'NT', 3);
INSERT INTO chapters VALUES (1117, 53, 1, 12);
INSERT INTO verses VALUES (29703, 53, 1, 1, 'Paulo e Silvano e Timóteo o assembleia Tessalonicenses em a-Theos Pai nosso e ao-Kyrios Iesous em-Christos');
INSERT INTO verses VALUES (29704, 53, 1, 2, 'graça a-vós e paz de de-Theos do-Pai e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (29705, 53, 1, 3, 'Dar-graças devemos o a-Theos sempre acerca-de vosso irmãos assim-como digno é que Cresce-excedentemente o fé vosso e abunda o amor um cada-um todos vosso para uns-aos-outros');
INSERT INTO verses VALUES (29706, 53, 1, 4, 'de-modo-que eles nos em a-vós gloriar-se-em em o assembleias o de-Theos em-favor-de o perseverança vosso e da-fé em todos o perseguições vosso e o tribulações o qual suportais');
INSERT INTO verses VALUES (29707, 53, 1, 5, 'Demonstração o justa julgamento o de-Theos para o ser-considerado-digno vos o do-reino o de-Theos em-favor-de o qual e sofreis');
INSERT INTO verses VALUES (29708, 53, 1, 6, 'se-de-fato justo de-junto-de a-Theos retribuir o afligem vos tribulação');
INSERT INTO verses VALUES (29709, 53, 1, 7, 'e a-vós o aos-que-são-afligidos alívio com nosso em o revelação o do-Kyrios Iesous de do-céu com anjo do-poder dele');
INSERT INTO verses VALUES (29710, 53, 1, 8, 'em fogo de-chama dando vingança o não sei Theos e o não obedecem o no-evangelho o do-Kyrios nosso Iesous');
INSERT INTO verses VALUES (29711, 53, 1, 9, 'os-quais castigo pagarão destruição eterno de face o do-Kyrios e de o da-glória o força dele');
INSERT INTO verses VALUES (29712, 53, 1, 10, 'quando venha ser-glorificado em o santos dele e ser-maravilhado em todos o aos-que-creram que foi-confiado o testemunho nosso sobre vos em o dia naquela');
INSERT INTO verses VALUES (29713, 53, 1, 11, 'para o qual e oramos sempre acerca-de vosso para que vos considere-digno o chamado o Theos nosso e cumpra toda boa-vontade bondade e obra da-fé em poder');
INSERT INTO verses VALUES (29714, 53, 1, 12, 'para-que seja-glorificado o nome o do-Kyrios nosso Iesous em a-vós e vós em a ele segundo o graça o de-Theos nosso e do-Kyrios Iesous de-Christos');
INSERT INTO chapters VALUES (1118, 53, 2, 17);
INSERT INTO verses VALUES (29715, 53, 2, 1, 'Perguntamos porém vos irmãos em-favor-de o presença o do-Kyrios nosso Iesous de-Christos e nosso reunião sobre ele');
INSERT INTO verses VALUES (29716, 53, 2, 2, 'para o não rapidamente ser-abalado vos de o mente nem alarmar-se nem através-de do-espírito nem através-de da-palavra nem através-de carta como através-de nosso como que tem-se-apresentado o dia o do-Kyrios');
INSERT INTO verses VALUES (29717, 53, 2, 3, 'não alguém vos engane segundo ninguém modo que se não venha o apostasia primeiro e seja-revelado o homem o iniquidade o Filho o perdição');
INSERT INTO verses VALUES (29718, 53, 2, 4, 'o opondo-se e Exaltando-se-acima sobre todas-as-coisas chamado Theos ou objeto-de-adoração de-modo-que ele para o templo o de-Theos sentar demonstrando si-mesmo que é Theos');
INSERT INTO verses VALUES (29719, 53, 2, 5, 'não lembrai-vos que ainda sendo junto-a vos estas-coisas diziam a-vós');
INSERT INTO verses VALUES (29720, 53, 2, 6, 'e agora o retendo sei para o ser-revelado ele em o dele tempo');
INSERT INTO verses VALUES (29721, 53, 2, 7, 'o pois mistério já é-operado o iniquidade somente o retendo agora até de meio aconteça');
INSERT INTO verses VALUES (29722, 53, 2, 8, 'e então será-revelado o sem-lei o qual o Kyrios Iesous matará o espírito o da-boca dele e anulará o Manifestação o presença dele');
INSERT INTO verses VALUES (29723, 53, 2, 9, 'o qual é o presença segundo operação o Satanás em toda poder e sinais e prodígios mentira');
INSERT INTO verses VALUES (29724, 53, 2, 10, 'e em toda engano da-injustiça o perecendo em-vez-de o qual o amor o da-verdade não receberam para o ser-salvo eles');
INSERT INTO verses VALUES (29725, 53, 2, 11, 'e através-de isto envia a-eles o Theos operação engano para o crer eles o mentira');
INSERT INTO verses VALUES (29726, 53, 2, 12, 'para que sejam-julgados todos o não tendo-crido o verdade mas tendo-se-comprazido o injustiça');
INSERT INTO verses VALUES (29727, 53, 2, 13, 'nós porém devemos dar-graças o a-Theos sempre acerca-de vosso irmãos tendo-sido-amados sob do-Kyrios que escolheu vos o Theos de princípio para salvação em santificação do-espírito e fé da-verdade');
INSERT INTO verses VALUES (29728, 53, 2, 14, 'para o qual e chamou vos através-de o evangelho nosso para aquisição da-glória o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (29729, 53, 2, 15, 'então portanto irmãos permanecei-firmes e segurai o tradições o qual fostes-ensinados seja através-de da-palavra seja através-de carta nosso');
INSERT INTO verses VALUES (29730, 53, 2, 16, 'ele porém o Kyrios nosso Iesous Christos e o Theos o Pai nosso o tendo-amado nos e dando consolação eterna e esperança boa em graça');
INSERT INTO verses VALUES (29731, 53, 2, 17, 'consolar vosso o do-coração e firmar em todo obra e em-palavra bom');
INSERT INTO chapters VALUES (1119, 53, 3, 18);
INSERT INTO verses VALUES (29732, 53, 3, 1, 'o restante orai irmãos acerca-de nosso para que o palavra o do-Kyrios corra e seja-glorificado assim-como e junto-a vos');
INSERT INTO verses VALUES (29733, 53, 3, 2, 'e para que sejamos-livrados de o perversos e maus dos-homens não pois todos o fé');
INSERT INTO verses VALUES (29734, 53, 3, 3, 'fiel e/mas é o Kyrios o qual firmará vos e guardará de o do-mal');
INSERT INTO verses VALUES (29735, 53, 3, 4, 'temos-confiado porém em ao-Kyrios sobre vos que o qual ordenamos e fazei e fareis');
INSERT INTO verses VALUES (29736, 53, 3, 5, 'o porém Kyrios dirigir vosso o do-coração para o amor o de-Theos e para o perseverança o de-Christos');
INSERT INTO verses VALUES (29737, 53, 3, 6, 'Ordenamos porém a-vós irmãos em em-nome o do-Kyrios Iesous de-Christos afastar-se vos de todo do-irmão desordenadamente andando e não segundo o tradição o qual recebestes de nosso');
INSERT INTO verses VALUES (29738, 53, 3, 7, 'eles-mesmos pois sei como é necessário imitar nos que não fomos-desordenados em a-vós');
INSERT INTO verses VALUES (29739, 53, 3, 8, 'nem gratuitamente pão Comemos junto-a de-alguém mas em labor e labor noite e do-dia trabalhando junto-a o não sobrecarregar alguém vosso');
INSERT INTO verses VALUES (29740, 53, 3, 9, 'não que não temos autoridade mas para que si-mesmos modelo demos a-vós para o imitar nos');
INSERT INTO verses VALUES (29741, 53, 3, 10, 'e pois quando éramos junto-a vos isto ordenávamos a-vós que se alguém não quer trabalhar nem coma');
INSERT INTO verses VALUES (29742, 53, 3, 11, 'ouvimos pois alguns andando em a-vós desordenadamente nada Trabalhando mas intrometendo-se');
INSERT INTO verses VALUES (29743, 53, 3, 12, 'o porém tais ordenamos e exortamos em ao-Kyrios Iesous em-Christos para que com Quietude trabalhando o deles-mesmos pão comam');
INSERT INTO verses VALUES (29744, 53, 3, 13, 'vós e/mas irmãos não desanimeis fazendo-o-bem');
INSERT INTO verses VALUES (29745, 53, 3, 14, 'se e/mas alguém não obedece o em-palavra nosso através-de o carta este notai não misturar-se-com a ele para que envergonhe-se');
INSERT INTO verses VALUES (29746, 53, 3, 15, 'e não como Inimigo considerai mas admoestai como irmão');
INSERT INTO verses VALUES (29747, 53, 3, 16, 'ele porém o Kyrios o paz dê a-vós o paz através-de todo em todo modo o Kyrios com todos vosso');
INSERT INTO verses VALUES (29748, 53, 3, 17, 'o saudação o minha mão Paulo o qual é sinal em toda carta assim escrever');
INSERT INTO verses VALUES (29749, 53, 3, 18, 'o graça o do-Kyrios nosso Iesous de-Christos com todos vosso');
INSERT INTO books VALUES (54, '1TI', '1 Timóteo', 'NT', 6);
INSERT INTO chapters VALUES (1120, 54, 1, 20);
INSERT INTO verses VALUES (29750, 54, 1, 1, 'Paulo apóstolo de-Christos Iesous segundo mandado de-Theos do-Salvador nosso e de-Christos Iesous o da-esperança nosso');
INSERT INTO verses VALUES (29751, 54, 1, 2, 'Timóteo genuíno filho em fé graça misericórdia paz de de-Theos do-Pai e de-Christos Iesous o do-Kyrios nosso');
INSERT INTO verses VALUES (29752, 54, 1, 3, 'Assim-como consolei te permanecer em Éfeso indo para Macedônia para que ordenes alguns não Ensinar-outra-doutrina');
INSERT INTO verses VALUES (29753, 54, 1, 4, 'nem atentar fábulas e genealogias intermináveis as-quais buscas-diligentes fornecem mais ou administração de-Theos o em fé');
INSERT INTO verses VALUES (29754, 54, 1, 5, 'o porém fim o ordem é amor de pura do-coração e consciência boa e da-fé sem-hipocrisia');
INSERT INTO verses VALUES (29755, 54, 1, 6, 'o qual alguns tendo-se-desviado desviaram-se para conversa-vã');
INSERT INTO verses VALUES (29756, 54, 1, 7, 'querendo ser mestres-da-lei não compreendendo nem o qual dizem nem acerca-de de-quais afirmam-com-certeza');
INSERT INTO verses VALUES (29757, 54, 1, 8, 'sei porém que belo o lei se alguém a ele legitimamente usa');
INSERT INTO verses VALUES (29758, 54, 1, 9, 'sei isto que justo lei não está-posto sem-lei porém e insubmissos ímpios e pecadores profanos e profanos parricidas e matricidas homicidas');
INSERT INTO verses VALUES (29759, 54, 1, 10, 'imorais sodomitas escravizadores mentirosos Perjuros e se algo outro o sã ensino opõe-se');
INSERT INTO verses VALUES (29760, 54, 1, 11, 'segundo o evangelho o da-glória o bem-aventurado de-Theos o qual fui-confiado eu');
INSERT INTO verses VALUES (29761, 54, 1, 12, 'graça tenho o tendo-fortalecido me em-Christos Iesous o ao-Kyrios nosso que fiel me considerou tendo-posto para serviço');
INSERT INTO verses VALUES (29762, 54, 1, 13, 'o antes sendo blasfemo e perseguidor e insolente mas fui-misericordiado que ignorando fiz em incredulidade');
INSERT INTO verses VALUES (29763, 54, 1, 14, 'Superabundou porém o graça o do-Kyrios nosso com da-fé e do-amor o em em-Christos Iesous');
INSERT INTO verses VALUES (29764, 54, 1, 15, 'fiel o palavra e toda aceitação digno que Christos Iesous veio para o mundo pecadores salvar o qual primeiro sou eu');
INSERT INTO verses VALUES (29765, 54, 1, 16, 'mas através-de isto fui-misericordiado para que em mim primeiro demonstre Iesous Christos o toda paciência junto-a modelo o estando-para crer sobre a ele para vida eterno');
INSERT INTO verses VALUES (29766, 54, 1, 17, 'o porém Rei o eras incorruptível invisível somente a-Theos honra e glória para o eras o eras amém');
INSERT INTO verses VALUES (29767, 54, 1, 18, 'esta o ordem confio a-ti filho Timóteo segundo o indo-adiante sobre te profecia para que guerreies em elas o boa guerra');
INSERT INTO verses VALUES (29768, 54, 1, 19, 'tendo fé e boa consciência o qual alguns tendo-rejeitado acerca-de o fé naufragaram');
INSERT INTO verses VALUES (29769, 54, 1, 20, 'o qual é Himeneu e Alexandre o qual entreguei o Satanás para que sejam-disciplinados não blasfemar');
INSERT INTO chapters VALUES (1121, 54, 2, 15);
INSERT INTO verses VALUES (29770, 54, 2, 1, 'Exorto portanto primeiro todos fazer súplicas orações intercessões ação-de-graças em-favor-de todos dos-homens');
INSERT INTO verses VALUES (29771, 54, 2, 2, 'em-favor-de reis e todos o em Superioridade existindo para que sereno e Tranquilo vida vivamos em toda piedade e em-dignidade');
INSERT INTO verses VALUES (29772, 54, 2, 3, 'isto belo e aceitável diante-de o do-Salvador nosso de-Theos');
INSERT INTO verses VALUES (29773, 54, 2, 4, 'o qual todos homens quer ser-salvo e para conhecimento-pleno da-verdade vir');
INSERT INTO verses VALUES (29774, 54, 2, 5, 'um pois Theos um e mediador de-Theos e dos-homens homem Christos Iesous');
INSERT INTO verses VALUES (29775, 54, 2, 6, 'o dando si-mesmo resgate em-favor-de todos o testemunho tempos próprios');
INSERT INTO verses VALUES (29776, 54, 2, 7, 'para o qual fui-colocado eu arauto e apóstolo verdade digo não minto mestre nações em fé e verdade');
INSERT INTO verses VALUES (29777, 54, 2, 8, 'Quero portanto orar o homens em todo no-lugar levantando santos mãos sem ira e raciocínio');
INSERT INTO verses VALUES (29778, 54, 2, 9, 'Do-mesmo-modo mulheres em vestimenta decoroso com pudor e sobriedade adornar si-mesmas não em tranças e ouro ou pérolas ou vestuário muito-custoso');
INSERT INTO verses VALUES (29779, 54, 2, 10, 'mas o qual convém mulheres prometendo piedade-a-Theos através-de obra boas-coisas');
INSERT INTO verses VALUES (29780, 54, 2, 11, 'mulher em quietude aprenda em toda sujeição');
INSERT INTO verses VALUES (29781, 54, 2, 12, 'ensinar porém mulher não Permito nem exercer-autoridade homem mas ser em quietude');
INSERT INTO verses VALUES (29782, 54, 2, 13, 'Adão pois primeiro Foi-formada então Eva');
INSERT INTO verses VALUES (29783, 54, 2, 14, 'e Adão não foi-enganada o porém mulher tendo-sido-enganada em em-transgressão aconteceu');
INSERT INTO verses VALUES (29784, 54, 2, 15, 'será-salvo porém através-de o de-geração-de-filhos se permaneçam em fé e amor e santificação com sobriedade');
INSERT INTO chapters VALUES (1122, 54, 3, 16);
INSERT INTO verses VALUES (29785, 54, 3, 1, 'fiel o palavra se alguém supervisão aspira bom obra deseja');
INSERT INTO verses VALUES (29786, 54, 3, 2, 'é necessário portanto o supervisor irrepreensível ser uma mulher homem sóbrio sóbrio-de-mente decoroso hospitaleiro apto-para-ensinar');
INSERT INTO verses VALUES (29787, 54, 3, 3, 'não não-dado-ao-vinho não agressor mas moderado pacífico sem-amor-ao-dinheiro');
INSERT INTO verses VALUES (29788, 54, 3, 4, 'o próprio da-casa bem presidindo filhos tendo em sujeição com toda de-dignidade');
INSERT INTO verses VALUES (29789, 54, 3, 5, 'se e/mas alguém o próprio da-casa presidir não sei como da-assembleia de-Theos cuidará');
INSERT INTO verses VALUES (29790, 54, 3, 6, 'não neófito para que não tendo-sido-enfatuado para julgamento caia-dentro o diabo');
INSERT INTO verses VALUES (29791, 54, 3, 7, 'é necessário porém e testemunho boa ter de o de-fora para que não para opróbrio caia-dentro e laço o diabo');
INSERT INTO verses VALUES (29792, 54, 3, 8, 'servos da-mesma-forma dignos não de-dupla-palavra não vinho muito atentando não gananciosos-por-lucro-torpe');
INSERT INTO verses VALUES (29793, 54, 3, 9, 'tendo o mistério o da-fé em pura consciência');
INSERT INTO verses VALUES (29794, 54, 3, 10, 'e estes porém sejam-examinados primeiro então sirvam irrepreensíveis sendo');
INSERT INTO verses VALUES (29795, 54, 3, 11, 'mulheres da-mesma-forma dignas não caluniadores sóbrios fiéis em todos');
INSERT INTO verses VALUES (29796, 54, 3, 12, 'servos Sejam uma mulher homens filhos bem presidindo e o próprios casas');
INSERT INTO verses VALUES (29797, 54, 3, 13, 'o pois bem tendo-servido grau si-mesmos belo adquirem e muita ousadia em fé o em em-Christos Iesous');
INSERT INTO verses VALUES (29798, 54, 3, 14, 'Estas-coisas a-ti escrever esperando vir junto-a te mais-rapidamente');
INSERT INTO verses VALUES (29799, 54, 3, 15, 'se porém demoro para que sei como é necessário em na-casa de-Theos conduzir-se a-qual é assembleia de-Theos vivente coluna e Fundamento o da-verdade');
INSERT INTO verses VALUES (29800, 54, 3, 16, 'e confessadamente grande é o o piedade mistério o qual foi-manifestado em na-carne foi-justificado em espírito apareceu anjo foi-proclamado em nações foi-confiado em ao-mundo foi-elevado em glória');
INSERT INTO chapters VALUES (1123, 54, 4, 16);
INSERT INTO verses VALUES (29801, 54, 4, 1, 'o porém espírito expressamente diz que em Últimos tempos afastar-se-ão alguns o da-fé prestando-atenção espíritos enganadores e ensinos demônios');
INSERT INTO verses VALUES (29802, 54, 4, 2, 'em hipocrisia falsos-falantes tendo-sido-cauterizados o própria consciência');
INSERT INTO verses VALUES (29803, 54, 4, 3, 'impedindo casar abster-se alimentos o qual o Theos criou para recebimento com ação-de-graças o fiéis e tendo-reconhecido o verdade');
INSERT INTO verses VALUES (29804, 54, 4, 4, 'que todo criatura de-Theos bom e nada rejeitável com ação-de-graças sendo-recebido');
INSERT INTO verses VALUES (29805, 54, 4, 5, 'é-santificado pois através-de da-palavra de-Theos e intercessão');
INSERT INTO verses VALUES (29806, 54, 4, 6, 'estas-coisas Pondo-diante o aos-irmãos belo serás servo de-Christos Iesous sendo-nutrido o palavras o da-fé e o boa ensino o qual seguiste');
INSERT INTO verses VALUES (29807, 54, 4, 7, 'o porém profanos e de-velhas fábulas recusa exercita porém a-ti-mesmo junto-a piedade');
INSERT INTO verses VALUES (29808, 54, 4, 8, 'o pois corporal exercício junto-a pouco é proveitoso o porém piedade junto-a todas-as-coisas Proveitoso é promessa tendo da-vida o agora e o está-para');
INSERT INTO verses VALUES (29809, 54, 4, 9, 'fiel o palavra e toda aceitação digno');
INSERT INTO verses VALUES (29810, 54, 4, 10, 'para isto pois labutamos e combatemos que temos-esperado sobre a-Theos vivendo o qual é Salvador todos dos-homens principalmente fiéis');
INSERT INTO verses VALUES (29811, 54, 4, 11, 'Ordena estas-coisas e ensina');
INSERT INTO verses VALUES (29812, 54, 4, 12, 'ninguém teu o juventude despreze mas modelo sê o fiéis em em-palavra em conduta em amor em fé em pureza');
INSERT INTO verses VALUES (29813, 54, 4, 13, 'até venho tem-cuidado o leitura o consolação o ensino');
INSERT INTO verses VALUES (29814, 54, 4, 14, 'não descuida o em a-ti de-dom-de-graça o qual foi-dado a-ti através-de profecia com imposição o mãos o conselho-de-anciãos');
INSERT INTO verses VALUES (29815, 54, 4, 15, 'estas-coisas medita em nestes sê para que teu o progresso manifesta seja todos');
INSERT INTO verses VALUES (29816, 54, 4, 16, 'Presta-atenção a-ti-mesmo e o ensino permanece a-eles isto pois fazendo e a-ti-mesmo salvarás e o ouvindo teu');
INSERT INTO chapters VALUES (1124, 54, 5, 25);
INSERT INTO verses VALUES (29817, 54, 5, 1, 'Ancião não repreendas mas exortava como Pai mais-jovens como irmãos');
INSERT INTO verses VALUES (29818, 54, 5, 2, 'anciãs como mães mais-jovens como irmãs em toda pureza');
INSERT INTO verses VALUES (29819, 54, 5, 3, 'Viúvas honra o verdadeiramente viúvas');
INSERT INTO verses VALUES (29820, 54, 5, 4, 'se e/mas alguém viúva filhos ou Descendentes tem aprendam primeiro o próprio casa ser-piedoso e retribuições devolver o antepassados isto pois é aceitável diante-de o de-Theos');
INSERT INTO verses VALUES (29821, 54, 5, 5, 'o porém verdadeiramente viúva e tendo-sido-isolada Tem-esperado sobre Theos e permanece o súplicas e o orações da-noite e do-dia');
INSERT INTO verses VALUES (29822, 54, 5, 6, 'o porém vivendo-em-luxúria vivendo tem-morrido');
INSERT INTO verses VALUES (29823, 54, 5, 7, 'e estas-coisas ordena para que irrepreensíveis sejam');
INSERT INTO verses VALUES (29824, 54, 5, 8, 'se e/mas alguém o próprios e principalmente membros-da-casa não cuida o fé Tem-negado e é incrédulo pior');
INSERT INTO verses VALUES (29825, 54, 5, 9, 'Viúva seja-alistada não menor anos sessenta tendo-se-tornado um homem mulher');
INSERT INTO verses VALUES (29826, 54, 5, 10, 'em obra boas sendo-testificada se Criou-filhos se hospedou-estrangeiros se santos pés lavou se aos-que-são-afligidos socorreu se todo obra bom seguiu');
INSERT INTO verses VALUES (29827, 54, 5, 11, 'mais-jovens porém viúvas recusa quando pois se-entreguem-à-sensualidade-contra o de-Christos casar querem');
INSERT INTO verses VALUES (29828, 54, 5, 12, 'tendo julgamento que o primeiro fé rejeitaram');
INSERT INTO verses VALUES (29829, 54, 5, 13, 'juntamente porém e ociosas aprendem andando-ao-redor o da-casa não somente porém ociosas mas e tagarelas e curiosos falando o não é necessário');
INSERT INTO verses VALUES (29830, 54, 5, 14, 'quero portanto mais-jovens casar gerar-filhos governar-a-casa nenhuma ocasião dar o opondo-se injúria graça');
INSERT INTO verses VALUES (29831, 54, 5, 15, 'já pois alguns desviaram-se atrás o Satanás');
INSERT INTO verses VALUES (29832, 54, 5, 16, 'se alguém fiel tem viúvas socorra elas e não seja-pesado o assembleia para que o verdadeiramente viúvas socorra');
INSERT INTO verses VALUES (29833, 54, 5, 17, 'o bem presidindo anciãos dupla honra sejam-considerados-dignos principalmente o labutando em em-palavra e ensino');
INSERT INTO verses VALUES (29834, 54, 5, 18, 'diz pois o escritura Boi debulhando não amordaçarás e digno o trabalhador o salário dele');
INSERT INTO verses VALUES (29835, 54, 5, 19, 'segundo ancião acusação não aceita fora-de se não sobre dois ou três testemunhas');
INSERT INTO verses VALUES (29836, 54, 5, 20, 'o pecando diante-de todos repreende para que e o restantes medo tenham');
INSERT INTO verses VALUES (29837, 54, 5, 21, 'testifico-solenemente diante-de o de-Theos e de-Christos Iesous e o eleitos anjo para que estas-coisas guardes sem prejulgamento nada fazendo segundo parcialidade');
INSERT INTO verses VALUES (29838, 54, 5, 22, 'Mãos rapidamente a-ninguém Põe-sobre nem torna-comum pecados alheias a-ti-mesmo puro guarda');
INSERT INTO verses VALUES (29839, 54, 5, 23, 'Não-mais bebe-água mas vinho pouco usa através-de o estômago e o frequentes teu fraqueza');
INSERT INTO verses VALUES (29840, 54, 5, 24, 'Alguns dos-homens o pecados evidentes são indo-adiante para juízo alguns porém e seguem');
INSERT INTO verses VALUES (29841, 54, 5, 25, 'da-mesma-forma e o obra o boas evidentes e o de-outro-modo tendo ser-escondido não podem');
INSERT INTO chapters VALUES (1125, 54, 6, 21);
INSERT INTO verses VALUES (29842, 54, 6, 1, 'quanto são sob balança servos o próprios senhores toda honra dignos que-liderem para que não o nome o de-Theos e o ensino seja-blasfemado');
INSERT INTO verses VALUES (29843, 54, 6, 2, 'o porém fiéis tendo senhores não desprezem que irmãos são mas mais sirvam que fiéis são e amados o o beneficência socorrendo estas-coisas ensina e exortava');
INSERT INTO verses VALUES (29844, 54, 6, 3, 'se alguém Ensina-outra-doutrina e não aproxima-se estão-sãos palavras o o do-Kyrios nosso Iesous de-Christos e o segundo piedade ensino');
INSERT INTO verses VALUES (29845, 54, 6, 4, 'tem-sido-enfatuado nada sabendo mas adoecendo acerca-de buscas e contenda-de-palavras de o qual torna-se inveja contenda blasfêmias Suspeitas más');
INSERT INTO verses VALUES (29846, 54, 6, 5, 'atritos-constantes tendo-sido-corrompidos dos-homens o entendimento e dos-que-foram-privados o da-verdade supondo ganho ser o piedade');
INSERT INTO verses VALUES (29847, 54, 6, 6, 'é porém ganho grande o piedade com suficiência');
INSERT INTO verses VALUES (29848, 54, 6, 7, 'nada pois trouxemos-para-dentro para o mundo que nem levar-para-fora algo podemos');
INSERT INTO verses VALUES (29849, 54, 6, 8, 'tendo porém alimentos e coberturas nestes seremos-suficientes');
INSERT INTO verses VALUES (29850, 54, 6, 9, 'o porém querendo enriquecer caem-em para tentação e laço e desejos muitas insensatos e prejudiciais as-quais submergem o homens para destruição e perdição');
INSERT INTO verses VALUES (29851, 54, 6, 10, 'raiz pois todos o males é o amor-ao-dinheiro o qual alguns aspirando foram-desviados de o da-fé e si-mesmos traspassaram dores muitas');
INSERT INTO verses VALUES (29852, 54, 6, 11, 'tu e/mas Ômega homem de-Theos estas-coisas foge persegue porém justiça piedade fé amor perseverança brandura-de-espírito');
INSERT INTO verses VALUES (29853, 54, 6, 12, 'combate o belo luta o da-fé toma-de o eterno da-vida para o qual foste-chamado e Confessaste o boa confissão diante-de muitos testemunhas');
INSERT INTO verses VALUES (29854, 54, 6, 13, 'ordeno diante-de o de-Theos o preservando-vivos o todas-as-coisas e de-Christos Iesous o tendo-testemunhado sobre Pôncio Pilatos o boa confissão');
INSERT INTO verses VALUES (29855, 54, 6, 14, 'guardar te o mandamento sem-mancha irrepreensível até o manifestação o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (29856, 54, 6, 15, 'o qual tempos próprios mostrará o bem-aventurado e só Governante o Rei o reinando e Kyrios o dominando');
INSERT INTO verses VALUES (29857, 54, 6, 16, 'o só tendo imortalidade luz habitando inacessível o qual viu ninguém dos-homens nem ver pode o qual honra e domínio eterno amém');
INSERT INTO verses VALUES (29858, 54, 6, 17, 'o ricos em o agora era ordena não Ter-pensamentos-altivos nem ter-esperado sobre riqueza incerteza mas sobre a-Theos o ao-que-fornece a-nós todas-as-coisas ricamente para deleite');
INSERT INTO verses VALUES (29859, 54, 6, 18, 'fazer-o-bem enriquecer em obra boas generosos ser generosos');
INSERT INTO verses VALUES (29860, 54, 6, 19, 'entesourando si-mesmos fundamento belo para o estando-a-ponto-de para que apanhem o verdadeiramente da-vida');
INSERT INTO verses VALUES (29861, 54, 6, 20, 'Ômega Timóteo o depósito guarda desviando-se o profanos palavras-vãs e oposições o falsamente-nomeada do-conhecimento');
INSERT INTO verses VALUES (29862, 54, 6, 21, 'o qual alguns prometendo acerca-de o fé desviaram-se o graça com vosso');
INSERT INTO books VALUES (55, '2TI', '2 Timóteo', 'NT', 4);
INSERT INTO chapters VALUES (1126, 55, 1, 18);
INSERT INTO verses VALUES (29863, 55, 1, 1, 'Paulo apóstolo de-Christos Iesous através-de da-vontade de-Theos segundo promessa da-vida o em em-Christos Iesous');
INSERT INTO verses VALUES (29864, 55, 1, 2, 'Timóteo amado filho graça misericórdia paz de de-Theos do-Pai e de-Christos Iesous o do-Kyrios nosso');
INSERT INTO verses VALUES (29865, 55, 1, 3, 'graça tenho o a-Theos o qual sirvo de antepassados em pura consciência como incessante tenho o acerca-de teu menção em o súplicas meu noite e do-dia');
INSERT INTO verses VALUES (29866, 55, 1, 4, 'desejando-ardentemente te ver tendo-se-lembrado teu o lágrimas para que alegria seja-preenchido');
INSERT INTO verses VALUES (29867, 55, 1, 5, 'Lembrança tomando o em a-ti sem-hipocrisia da-fé a-qual habitou-em primeiro em o avó teu Loide e o mãe teu Eunice estou-persuadido porém que e em te');
INSERT INTO verses VALUES (29868, 55, 1, 6, 'por o qual causa faço-lembrar te reavivar o dom o de-Theos o qual é em a-ti através-de o imposição o mãos meu');
INSERT INTO verses VALUES (29869, 55, 1, 7, 'não pois deu a-nós o Theos espírito covardia mas do-poder e do-amor e de-sobriedade');
INSERT INTO verses VALUES (29870, 55, 1, 8, 'não portanto te-envergonhes o testemunho o do-Kyrios nosso nem mim o prisioneiro dele mas sofre-junto o no-evangelho segundo poder de-Theos');
INSERT INTO verses VALUES (29871, 55, 1, 9, 'o tendo-salvo nos e chamante chamado santa não segundo o obra nosso mas segundo própria propósito e graça o tendo-sido-dada a-nós em em-Christos Iesous antes-de tempos eternas');
INSERT INTO verses VALUES (29872, 55, 1, 10, 'tendo-sido-manifestada porém agora através-de o manifestação o do-Salvador nosso de-Christos Iesous tendo-anulado por-um-lado o morte do-que-iluminou porém vida e incorruptibilidade através-de o evangelho');
INSERT INTO verses VALUES (29873, 55, 1, 11, 'para o qual fui-colocado eu pregador e apóstolo e mestre');
INSERT INTO verses VALUES (29874, 55, 1, 12, 'através-de o qual causa e estas-coisas sofro mas não envergonho-me sei pois o qual tenho-crido e estou-persuadido que poderoso é o depósito meu guardar para aquela o dia');
INSERT INTO verses VALUES (29875, 55, 1, 13, 'modelo tem estando-sãos palavras o qual de mim ouviste em fé e amor o em em-Christos Iesous');
INSERT INTO verses VALUES (29876, 55, 1, 14, 'o boa depósito guarda através-de do-espírito do-santo o habitando em a-nós');
INSERT INTO verses VALUES (29877, 55, 1, 15, 'sei isto que desviaram-se me todos o em o Ásia o qual é Fígelo e Hermógenes');
INSERT INTO verses VALUES (29878, 55, 1, 16, 'dê misericórdia o Kyrios o Onesíforo na-casa que muitas-vezes me refrigerou e o corrente meu não envergonhou-se');
INSERT INTO verses VALUES (29879, 55, 1, 17, 'mas tendo-se-tornado em Roma diligentemente buscou me e encontrou');
INSERT INTO verses VALUES (29880, 55, 1, 18, 'dê a ele o Kyrios encontrar misericórdia de-junto-de do-Kyrios em naquela o dia e quanto em Éfeso serviu melhor tu conheces');
INSERT INTO chapters VALUES (1127, 55, 2, 26);
INSERT INTO verses VALUES (29881, 55, 2, 1, 'tu portanto filho meu fortalece-te em o graça o em em-Christos Iesous');
INSERT INTO verses VALUES (29882, 55, 2, 2, 'e o qual ouviste de mim através-de muitos testemunhas estas-coisas deposita fiéis aos-homens os-quais suficientes serão e outros ensinar');
INSERT INTO verses VALUES (29883, 55, 2, 3, 'sofre-junto como belo soldado de-Christos Iesous');
INSERT INTO verses VALUES (29884, 55, 2, 4, 'ninguém guerreando enreda-se o o vida negócios para que o tendo-alistado agrade');
INSERT INTO verses VALUES (29885, 55, 2, 5, 'se porém e compete alguém não é-coroado se não legitimamente compita');
INSERT INTO verses VALUES (29886, 55, 2, 6, 'o trabalhando lavrador é necessário primeiro o frutos participar');
INSERT INTO verses VALUES (29887, 55, 2, 7, 'compreende o qual digo dará pois a-ti o Kyrios entendimento em todos');
INSERT INTO verses VALUES (29888, 55, 2, 8, 'lembra Iesous Christos tendo-sido-levantado de mortos de semente Davi segundo o boa-nova meu');
INSERT INTO verses VALUES (29889, 55, 2, 9, 'em o qual sofro-dificuldades até prisões como malfeitor mas o palavra o de-Theos não tem-sido-atado');
INSERT INTO verses VALUES (29890, 55, 2, 10, 'através-de isto todas-as-coisas Persevero através-de o escolhidos para que e eles-mesmos salvação obtenham o em em-Christos Iesous com da-glória eterno');
INSERT INTO verses VALUES (29891, 55, 2, 11, 'fiel o palavra se pois co-morremos e viveremos-com');
INSERT INTO verses VALUES (29892, 55, 2, 12, 'se Perseveramos e co-reinaremos se negaremos e-aquele negara nos');
INSERT INTO verses VALUES (29893, 55, 2, 13, 'se não-cremos aquele fiel permanece negar pois si-mesmo não pode');
INSERT INTO verses VALUES (29894, 55, 2, 14, 'estas-coisas Lembra testificando diante-de o de-Theos não contender-sobre-palavras sobre nada útil sobre ruína o ouvindo');
INSERT INTO verses VALUES (29895, 55, 2, 15, 'apressa-te a-ti-mesmo aprovado apresentar o a-Theos obreiro que-não-se-envergonha cortando-retamente o palavra o da-verdade');
INSERT INTO verses VALUES (29896, 55, 2, 16, 'o porém profanos palavras-vãs evita sobre mais pois progredirão impiedade');
INSERT INTO verses VALUES (29897, 55, 2, 17, 'e o palavra deles como gangrena pasto terá o qual é Himeneu e Fileto');
INSERT INTO verses VALUES (29898, 55, 2, 18, 'os-quais acerca-de o verdade desviaram-se dizendo ressurreição já ter-acontecido e transtornam o alguns fé');
INSERT INTO verses VALUES (29899, 55, 2, 19, 'o contudo sólido fundamento o de-Theos está-de-pé tendo o selo esta conheceu Kyrios o sendo dele e Afaste-se de da-injustiça todo o nomeando o nome do-Kyrios');
INSERT INTO verses VALUES (29900, 55, 2, 20, 'em grande porém casa não é somente vasos dourado e prata mas e madeira e de-barro e o qual por-um-lado para honra o qual porém para desonra');
INSERT INTO verses VALUES (29901, 55, 2, 21, 'se portanto alguém limpe si-mesmo de destes será vaso para honra Tendo-sido-santificado útil o soberano para todo obra bom tendo-sido-preparado');
INSERT INTO verses VALUES (29902, 55, 2, 22, 'o porém juvenis desejos foge persegue porém justiça fé amor paz com o invocando o Kyrion de pura do-coração');
INSERT INTO verses VALUES (29903, 55, 2, 23, 'o porém tolas e sem-instrução buscas recusa sei que geram contendas');
INSERT INTO verses VALUES (29904, 55, 2, 24, 'servo porém do-Kyrios não é necessário combater mas brandos ser junto-a todos apto-para-ensinar paciente');
INSERT INTO verses VALUES (29905, 55, 2, 25, 'em mansidão disciplinando o opondo-se não alguma-vez dê a-eles o Theos arrependimento para conhecimento-pleno da-verdade');
INSERT INTO verses VALUES (29906, 55, 2, 26, 'e voltem-à-sobriedade de o o diabo laço tendo-sido-capturados-vivos sob dele para o daquele vontade');
INSERT INTO chapters VALUES (1128, 55, 3, 17);
INSERT INTO verses VALUES (29907, 55, 3, 1, 'isto porém conhece que em últimas dias se-apresentarão tempos difíceis');
INSERT INTO verses VALUES (29908, 55, 3, 2, 'serão pois o homens amantes-de-si-mesmos amantes-de-dinheiro arrogantes Soberbos blasfemos pais desobedientes ingratos profanos');
INSERT INTO verses VALUES (29909, 55, 3, 3, 'sem-afeição-natural implacáveis caluniadores sem-domínio-próprio selvagens sem-amor-ao-bem');
INSERT INTO verses VALUES (29910, 55, 3, 4, 'traidores precipitados tendo-sido-enfatuados amantes-do-prazer mais ou amantes-de-Theos');
INSERT INTO verses VALUES (29911, 55, 3, 5, 'tendo forma-exterior piedade o porém poder dela tendo-negado e estes afasta-te');
INSERT INTO verses VALUES (29912, 55, 3, 6, 'de destes pois são o infiltrando-se para o da-casa e levando-cativos mulherzinhas tendo-sido-amontoadas pecados sendo-conduzidos desejos diversas');
INSERT INTO verses VALUES (29913, 55, 3, 7, 'sempre aprendendo e nunca para conhecimento-pleno da-verdade vir podendo');
INSERT INTO verses VALUES (29914, 55, 3, 8, 'o qual modo porém Janes e Jambres resistiram Moisés assim e estes resistem o verdade homens tendo-sido-corrompidos o entendimento reprovados acerca-de o fé');
INSERT INTO verses VALUES (29915, 55, 3, 9, 'mas não progredirão sobre mais o pois insensatez deles Manifesto será todos como e o daqueles aconteceu');
INSERT INTO verses VALUES (29916, 55, 3, 10, 'tu porém seguiste meu o ensino o conduta o propósito o fé o paciência o amor o perseverança');
INSERT INTO verses VALUES (29917, 55, 3, 11, 'o perseguições o sofrimentos quais a-mim aconteceu em Antioquia em Icônio em Listra quais perseguições Suportei e de todos me livrou o Kyrios');
INSERT INTO verses VALUES (29918, 55, 3, 12, 'e todos porém o querendo viver piedosamente em em-Christos Iesous serão-perseguidos');
INSERT INTO verses VALUES (29919, 55, 3, 13, 'maus porém homens e impostores progredirão sobre o pior enganando e errantes');
INSERT INTO verses VALUES (29920, 55, 3, 14, 'tu porém permanece em o qual aprendeste e foste-confirmado sei de-junto-de de-quais aprendeste');
INSERT INTO verses VALUES (29921, 55, 3, 15, 'e que de criança-de-peito sagradas letras sei o podendo te tornar-sábio para salvação através-de da-fé o em em-Christos Iesous');
INSERT INTO verses VALUES (29922, 55, 3, 16, 'toda escritura inspirado-por-Theos e proveitoso junto-a ensino junto-a repreensão junto-a correção junto-a disciplina o em justiça');
INSERT INTO verses VALUES (29923, 55, 3, 17, 'para que completo seja o o de-Theos homem junto-a todo obra bom tendo-sido-completado');
INSERT INTO chapters VALUES (1129, 55, 4, 22);
INSERT INTO verses VALUES (29924, 55, 4, 1, 'Testifico-solenemente diante-de o de-Theos e de-Christos Iesous o do-que-está-por-vir julgar viventes e mortos e o manifestação dele e o reino dele');
INSERT INTO verses VALUES (29925, 55, 4, 2, 'prega o palavra apresenta-te oportunamente inoportunamente repreende repreende consola em toda paciência e em-ensino');
INSERT INTO verses VALUES (29926, 55, 4, 3, 'será pois tempo quando o sendo-sã ensino não suportarão mas segundo o próprias desejos si-mesmos Amontoarão mestres tendo-coceira o ouvido');
INSERT INTO verses VALUES (29927, 55, 4, 4, 'e de por-um-lado o da-verdade o audição desviarão sobre porém o fábulas desviar-se-ão');
INSERT INTO verses VALUES (29928, 55, 4, 5, 'tu porém sê-sóbrio em todos sofre-dificuldades obra faz anunciador-de-boa-nova o serviço teu cumpre-plenamente');
INSERT INTO verses VALUES (29929, 55, 4, 6, 'eu pois já sou-derramado-como-libação e o tempo o partida meu Está-presente');
INSERT INTO verses VALUES (29930, 55, 4, 7, 'o belo luta tenho-lutado o corrida tenho-completado o fé tenho-guardado');
INSERT INTO verses VALUES (29931, 55, 4, 8, 'restante está-reservado a-mim o o justiça coroa o qual retribuirá a-mim o kyrios em naquela o dia o justo juiz não somente porém mim mas e todos o tendo-amado o manifestação dele');
INSERT INTO verses VALUES (29932, 55, 4, 9, 'Apressa-te vir para me rapidamente');
INSERT INTO verses VALUES (29933, 55, 4, 10, 'Demas pois me abandonou tendo-amado o agora eternidade e foi para Tessalônica Crescente para Galácia Tito para Dalmácia');
INSERT INTO verses VALUES (29934, 55, 4, 11, 'Lucas é só com mim Marcos tendo-tomado vem com ti-mesmo é pois a-mim útil para serviço');
INSERT INTO verses VALUES (29935, 55, 4, 12, 'Tíquico porém enviei para Éfeso');
INSERT INTO verses VALUES (29936, 55, 4, 13, 'o capa o qual deixei em Trôade de-junto-de Carpo o-que-vem traz e o livros principalmente o pergaminhos');
INSERT INTO verses VALUES (29937, 55, 4, 14, 'Alexandre o ferreiro muitos a-mim males demonstrou retribuirá a ele o Kyrios segundo o obra dele');
INSERT INTO verses VALUES (29938, 55, 4, 15, 'o qual e tu guarda-te muito pois resistiu o nossos palavras');
INSERT INTO verses VALUES (29939, 55, 4, 16, 'em o primeiro meu defesa ninguém a-mim apresentou-se mas todos me abandonaram não a-eles seja-considerado');
INSERT INTO verses VALUES (29940, 55, 4, 17, 'o porém Kyrios a-mim apresentou-se e fortaleceu me para que através-de mim o pregação seja-plenamente-convicto e ouçam todas-as-coisas o nações e Fui-livrado de boca leão');
INSERT INTO verses VALUES (29941, 55, 4, 18, 'livrará me o Kyrios de todo obra do-mal e salvará para o reino dele o Celestial o qual o glória para o eras o eras amém');
INSERT INTO verses VALUES (29942, 55, 4, 19, 'Saúda Prisca e Áquila e o Onesíforo casa');
INSERT INTO verses VALUES (29943, 55, 4, 20, 'Erasto permaneceu em Corinto Trófimo porém deixei em Mileto estando-fraco');
INSERT INTO verses VALUES (29944, 55, 4, 21, 'Apressa-te antes-de inverno vir Saúda te Eubulo e Pudente e Lino e Cláudia e o irmãos todos');
INSERT INTO verses VALUES (29945, 55, 4, 22, 'o Kyrios com o espírito teu o graça com vosso');
INSERT INTO books VALUES (56, 'TIT', 'Tito', 'NT', 3);
INSERT INTO chapters VALUES (1130, 56, 1, 16);
INSERT INTO verses VALUES (29946, 56, 1, 1, 'Paulo servo de-Theos apóstolo porém Iesous de-Christos segundo fé eleitos de-Theos e conhecimento-pleno da-verdade o segundo piedade');
INSERT INTO verses VALUES (29947, 56, 1, 2, 'sobre esperança da-vida eterno o qual prometeu o que-não-mente Theos antes-de tempos eternas');
INSERT INTO verses VALUES (29948, 56, 1, 3, 'manifestou porém tempos próprios o palavra dele em proclamação o qual fui-confiado eu segundo mandado o do-Salvador nosso de-Theos');
INSERT INTO verses VALUES (29949, 56, 1, 4, 'Tito genuíno filho segundo comum fé graça e paz de de-Theos do-Pai e de-Christos Iesous o do-Salvador nosso');
INSERT INTO verses VALUES (29950, 56, 1, 5, 'disto graça deixei te em Creta para que o faltando corrigas e constituas segundo cidade anciãos como eu a-ti ordenei');
INSERT INTO verses VALUES (29951, 56, 1, 6, 'se quem é irrepreensível uma mulher homem filhos tendo fiéis não em acusação dissolução ou insubmissas');
INSERT INTO verses VALUES (29952, 56, 1, 7, 'é necessário pois o supervisor irrepreensível ser como de-Theos administrador não arrogante não irascível não não-dado-ao-vinho não agressor não ganancioso-por-lucro-torpe');
INSERT INTO verses VALUES (29953, 56, 1, 8, 'mas hospitaleiro amante-do-bem sóbrio-de-mente justo santo dominado');
INSERT INTO verses VALUES (29954, 56, 1, 9, 'apegando-se o segundo o ensino fiel da-palavra para que poderoso seja e exortar em o ensino o sã e o contradizendo repreender');
INSERT INTO verses VALUES (29955, 56, 1, 10, 'são pois muitos insubmissos faladores-vãos e enganadores-de-mente principalmente o de o da-circuncisão');
INSERT INTO verses VALUES (29956, 56, 1, 11, 'o qual é necessário silenciar os-quais todos casas transtornam ensinando o qual não é necessário torpe lucro graça');
INSERT INTO verses VALUES (29957, 56, 1, 12, 'disse alguém de deles Próprio deles profeta Cretenses sempre mentirosos males feras ventres ociosas');
INSERT INTO verses VALUES (29958, 56, 1, 13, 'o testemunho esta é verdadeiro através-de o qual causa repreende eles severamente para que estejam-sãos em o fé');
INSERT INTO verses VALUES (29959, 56, 1, 14, 'não prestando-atenção Judaicos fábulas e mandamentos dos-homens dos-que-se-desviam o verdade');
INSERT INTO verses VALUES (29960, 56, 1, 15, 'todas-as-coisas pura o puros o porém tendo-sido-contaminados e incrédulos nada limpo mas têm-sido-contaminados deles e o mente e o consciência');
INSERT INTO verses VALUES (29961, 56, 1, 16, 'Theos confessam sei o porém obra negam abomináveis sendo e desobedientes e junto-a todo obra bom reprovados');
INSERT INTO chapters VALUES (1131, 56, 2, 15);
INSERT INTO verses VALUES (29962, 56, 2, 1, 'tu porém fala o qual convém o sã ensino');
INSERT INTO verses VALUES (29963, 56, 2, 2, 'anciãos sóbrios ser dignos sóbrios-de-mente estando-sãos o fé o amor o perseverança');
INSERT INTO verses VALUES (29964, 56, 2, 3, 'mulheres-idosas da-mesma-forma em comportamento Dignos-de-sagrado não caluniadores nem vinho muito tendo-sido-escravizadas ensinando-o-bem');
INSERT INTO verses VALUES (29965, 56, 2, 4, 'para que ensinem-a-ser-sóbrias o novas amantes-dos-maridos ser amantes-dos-filhos');
INSERT INTO verses VALUES (29966, 56, 2, 5, 'sóbrios-de-mente puras trabalhadoras-do-lar boas Sujeitando-se o próprios homens para que não o palavra o de-Theos seja-blasfemado');
INSERT INTO verses VALUES (29967, 56, 2, 6, 'o mais-jovens da-mesma-forma exortava ser-sóbrio-de-mente');
INSERT INTO verses VALUES (29968, 56, 2, 7, 'acerca-de todas-as-coisas a-ti-mesmo fornecendo modelo boas obra em o ensino incorrupção dignidade');
INSERT INTO verses VALUES (29969, 56, 2, 8, 'palavra são irrepreensível para que o de contrária envergonhe-se nada tendo dizer acerca-de nosso vil');
INSERT INTO verses VALUES (29970, 56, 2, 9, 'servos próprios senhores sujeitar-se em todos agradáveis ser não contradizendo');
INSERT INTO verses VALUES (29971, 56, 2, 10, 'não retendo-para-si mas toda fé demonstrando boa para que o ensino o o do-Salvador nosso de-Theos adornem em todos');
INSERT INTO verses VALUES (29972, 56, 2, 11, 'Manifestou-se pois o graça o de-Theos salvífico todos aos-homens');
INSERT INTO verses VALUES (29973, 56, 2, 12, 'disciplinando nos para que tendo-negado o impiedade e o mundanas desejos sobriamente e justamente e piedosamente vivamos em o agora era');
INSERT INTO verses VALUES (29974, 56, 2, 13, 'aguardando o bem-aventurada esperança e manifestação o da-glória o grande de-Theos e do-Salvador nosso de-Christos Iesous');
INSERT INTO verses VALUES (29975, 56, 2, 14, 'o qual deu si-mesmo em-favor-de nosso para que resgate nos de toda iniquidade e purifique si-mesmo povo peculiar zeloso boas obra');
INSERT INTO verses VALUES (29976, 56, 2, 15, 'estas-coisas fala e exortava e repreende com toda Mandamento ninguém teu despreze');
INSERT INTO chapters VALUES (1132, 56, 3, 15);
INSERT INTO verses VALUES (29977, 56, 3, 1, 'Lembra eles governos autoridades sujeitar-se obedecer junto-a todo obra bom Preparados ser');
INSERT INTO verses VALUES (29978, 56, 3, 2, 'ninguém blasfemar não-contenciosos ser moderados toda demonstrando mansidão junto-a todos homens');
INSERT INTO verses VALUES (29979, 56, 3, 3, 'Éramos pois alguma-vez e nós insensatos desobedientes errantes servindo desejos e prazeres diversas em maldade e inveja vivendo odiosos odiando uns-aos-outros');
INSERT INTO verses VALUES (29980, 56, 3, 4, 'quando porém o benignidade e o filantropia apareceu o do-Salvador nosso de-Theos');
INSERT INTO verses VALUES (29981, 56, 3, 5, 'não de obra o em justiça o qual fizemos nós mas segundo o dele misericórdia salvou nos através-de lavagem de-regeneração e renovação do-espírito do-santo');
INSERT INTO verses VALUES (29982, 56, 3, 6, 'o qual derramou sobre nos ricamente através-de Iesous de-Christos o do-Salvador nosso');
INSERT INTO verses VALUES (29983, 56, 3, 7, 'para que tendo-sido-justificados o daquele graça herdeiros tornemo-nos segundo esperança da-vida eterno');
INSERT INTO verses VALUES (29984, 56, 3, 8, 'fiel o palavra e acerca-de destes quero te afirmar-com-certeza para que cuidem boas obra presidir o tendo-crido a-Theos estas-coisas é boas e Proveitosas o aos-homens');
INSERT INTO verses VALUES (29985, 56, 3, 9, 'tolas porém buscas e genealogias e contenda e contendas legais evita são pois inúteis e vãos');
INSERT INTO verses VALUES (29986, 56, 3, 10, 'herético homem com uma e segunda admoestação recusa');
INSERT INTO verses VALUES (29987, 56, 3, 11, 'sei que tem-sido-pervertido o tal e peca sendo autocondenado');
INSERT INTO verses VALUES (29988, 56, 3, 12, 'quando enviarei Artemas junto-a te ou Tíquico apressa-te vir para me para Nicópolis ali pois tenho-julgado passar-o-inverno');
INSERT INTO verses VALUES (29989, 56, 3, 13, 'Zenas o perito-na-lei e Apolo diligentemente envia-adiante para que nada a-eles falte');
INSERT INTO verses VALUES (29990, 56, 3, 14, 'aprendam porém e o Nossos boas obra presidir para o necessárias necessidade para que não sejam infrutíferos');
INSERT INTO verses VALUES (29991, 56, 3, 15, 'Saúdam te o com mim todos saúda o amando nos em fé o graça com todos vosso');
INSERT INTO books VALUES (57, 'PHM', 'Filemom', 'NT', 1);
INSERT INTO chapters VALUES (1133, 57, 1, 25);
INSERT INTO verses VALUES (29992, 57, 1, 1, 'Paulo prisioneiro de-Christos Iesous e Timóteo o irmão Filemom o amado e cooperador nosso');
INSERT INTO verses VALUES (29993, 57, 1, 2, 'e Áfia o irmã e Arquipo o co-soldado nosso e o segundo casa teu assembleia');
INSERT INTO verses VALUES (29994, 57, 1, 3, 'graça a-vós e paz de de-Theos do-Pai nosso e do-Kyrios Iesous de-Christos');
INSERT INTO verses VALUES (29995, 57, 1, 4, 'Dou-graças o a-Theos meu sempre menção teu fazendo sobre o orações meu');
INSERT INTO verses VALUES (29996, 57, 1, 5, 'ouvindo teu o amor e o fé o qual tens junto-a o Kyrios Iesous e para todos o santos');
INSERT INTO verses VALUES (29997, 57, 1, 6, 'para-que o comunhão o fé teu eficaz aconteça em conhecimento-pleno todo bom o em a-nós para Christon');
INSERT INTO verses VALUES (29998, 57, 1, 7, 'alegria pois muita tiveram e consolação sobre o amor teu que o entranhas o santos tem-descansado através-de teu irmão');
INSERT INTO verses VALUES (29999, 57, 1, 8, 'Por-isso muita em em-Christos ousadia tendo Ordenar a-ti o convindo');
INSERT INTO verses VALUES (30000, 57, 1, 9, 'através-de o amor mais rogo tal sendo como Paulo ancião agora porém e prisioneiro de-Christos Iesous');
INSERT INTO verses VALUES (30001, 57, 1, 10, 'rogo te acerca-de o mim filho o qual gerei em o cadeias Onésimo');
INSERT INTO verses VALUES (30002, 57, 1, 11, 'o alguma-vez a-ti inútil agora porém e a-ti e mim útil');
INSERT INTO verses VALUES (30003, 57, 1, 12, 'o qual enviei-de-volta a-ti ele isto é o minhas-coisas entranhas');
INSERT INTO verses VALUES (30004, 57, 1, 13, 'o qual eu desejava junto-a a-mim-mesmo reter para que em-favor-de teu a-mim sirva em o cadeias o evangelho');
INSERT INTO verses VALUES (30005, 57, 1, 14, 'sem porém o tua parecer nada quis fazer para que não como segundo necessidade o bom teu seja mas segundo Voluntário');
INSERT INTO verses VALUES (30006, 57, 1, 15, 'talvez pois através-de isto Foi-separado junto-a hora para que eterno ele te-abstenhas');
INSERT INTO verses VALUES (30007, 57, 1, 16, 'não-mais como servo mas em-favor-de servo irmão amado principalmente me quanto porém mais a-ti e em carne e em ao-Kyrios');
INSERT INTO verses VALUES (30008, 57, 1, 17, 'se portanto me tens participante recebe ele como me');
INSERT INTO verses VALUES (30009, 57, 1, 18, 'se e/mas algo cometeu-injustiça te ou deve isto mim imputa');
INSERT INTO verses VALUES (30010, 57, 1, 19, 'eu Paulo escrevi o minha mão eu pagarei para que não digo a-ti que e a-ti-mesmo a-mim deves-além');
INSERT INTO verses VALUES (30011, 57, 1, 20, 'sim irmão eu teu eu-tenha-proveito em ao-Kyrios dá-descanso meu o entranhas em em-Christos');
INSERT INTO verses VALUES (30012, 57, 1, 21, 'Tendo-confiado o obediência teu Escrevi a-ti sei que e em-favor-de o qual digo farás');
INSERT INTO verses VALUES (30013, 57, 1, 22, 'juntamente porém e Prepara a-mim hospedagem espero pois que através-de o orações vosso serei-concedido-por-graça a-vós');
INSERT INTO verses VALUES (30014, 57, 1, 23, 'Saúda te Epafras o co-prisioneiro meu em em-Christos Iesous');
INSERT INTO verses VALUES (30015, 57, 1, 24, 'Marcos Aristarco Demas Lucas o cooperadores meu');
INSERT INTO verses VALUES (30016, 57, 1, 25, 'o graça o do-Kyrios Iesous de-Christos com o do-espírito vosso');
INSERT INTO books VALUES (58, 'HEB', 'Hebreus', 'NT', 13);
INSERT INTO chapters VALUES (1134, 58, 1, 14);
INSERT INTO verses VALUES (30017, 58, 1, 1, 'Em-muitas-partes e de-muitas-maneiras outrora o Theos tendo-falado o pais em o profetas');
INSERT INTO verses VALUES (30018, 58, 1, 2, 'sobre último o dias destes falou a-nós em filho o qual colocou herdeiro todos através-de o qual e fez o eras');
INSERT INTO verses VALUES (30019, 58, 1, 3, 'o qual sendo resplendor o da-glória e expressão-exata o confiança dele trazendo e o todas-as-coisas o palavra o do-poder dele purificação o pecados tendo-feito sentou-se em direita o Majestade em Alturas');
INSERT INTO verses VALUES (30020, 58, 1, 4, 'tão-grande melhor tendo-se-tornado o anjo quanto mais-excelente de eles tem-herdado nome');
INSERT INTO verses VALUES (30021, 58, 1, 5, 'A-quem pois disse alguma-vez o anjo filho meu és tu eu hoje gerei te e novamente eu serei a ele para Pai e ele será a-mim para filho');
INSERT INTO verses VALUES (30022, 58, 1, 6, 'quando porém novamente introduza o primogênito para o mundo-habitado diz e prostrem-se a ele todos anjo de-Theos');
INSERT INTO verses VALUES (30023, 58, 1, 7, 'e junto-a por-um-lado o anjo diz o fazendo o anjo dele espíritos e o ministros dele fogo chama');
INSERT INTO verses VALUES (30024, 58, 1, 8, 'junto-a porém o filho o trono teu o Theos para o eternidade o eternidade e o vara o retidão vara o do-reino dele');
INSERT INTO verses VALUES (30025, 58, 1, 9, 'amaste justiça e odiaste iniquidade através-de isto ungiu te o Theos o Theos teu azeite exultação de-junto-de o participantes teu');
INSERT INTO verses VALUES (30026, 58, 1, 10, 'e tu segundo principados Kyrie o terra fundamentaste e obra o mãos teu são o céus');
INSERT INTO verses VALUES (30027, 58, 1, 11, 'eles-mesmos perecerão tu porém permaneces e todos como manto serão-envelhecidas');
INSERT INTO verses VALUES (30028, 58, 1, 12, 'e como manto Enrolarás eles como manto e serão-mudados tu porém o ele és e o anos teu não desfalecerão');
INSERT INTO verses VALUES (30029, 58, 1, 13, 'junto-a quem porém o anjo tem-dito alguma-vez Senta-te de direita meu até partícula-condicional ponha o inimigos teu estrado o pés teu');
INSERT INTO verses VALUES (30030, 58, 1, 14, 'não todos são ministrantes espíritos para serviço sendo-enviados através-de o estando-para herdar salvação');
INSERT INTO chapters VALUES (1135, 58, 2, 18);
INSERT INTO verses VALUES (30031, 58, 2, 1, 'através-de isto é necessário ainda-mais atentar nos o tendo-sido-ouvidas não alguma-vez nos-desviemos');
INSERT INTO verses VALUES (30032, 58, 2, 2, 'se pois o através-de anjo tendo-sido-falado palavra aconteceu firme e toda transgressão e desobediência recebeu Justa recompensa');
INSERT INTO verses VALUES (30033, 58, 2, 3, 'como nós escaparemos tão-grande tendo-negligenciado salvação a-qual início tomando ser-falado através-de o do-Kyrios sob o tendo-ouvido para nos foi-confirmado');
INSERT INTO verses VALUES (30034, 58, 2, 4, 'co-testificando o de-Theos sinais e e prodígios e diversas poderes e do-espírito do-santo distribuições segundo o dele vontade');
INSERT INTO verses VALUES (30035, 58, 2, 5, 'não pois anjo sujeitou o mundo-habitado o vindoura acerca-de o qual falamos');
INSERT INTO verses VALUES (30036, 58, 2, 6, 'testificou-solenemente e/mas onde alguém dizendo quê é homem que lembres-te dele ou Filho do-homem que visitas ele');
INSERT INTO verses VALUES (30037, 58, 2, 7, 'diminuíste ele pouco algo de anjo glória e honra Coroaste ele');
INSERT INTO verses VALUES (30038, 58, 2, 8, 'todas-as-coisas Sujeitaste debaixo o pés dele em o pois sujeitar a ele o todas-as-coisas nada deixou a ele insubmisso agora porém ainda-não vemos a ele o todas-as-coisas Tendo-sido-sujeitadas');
INSERT INTO verses VALUES (30039, 58, 2, 9, 'o porém pouco algo de anjo tendo-sido-diminuído vemos Iesous através-de o sofrimento o da-morte glória e honra Tendo-sido-coroado para-que graça de-Theos em-favor-de todo prove da-morte');
INSERT INTO verses VALUES (30040, 58, 2, 10, 'Convinha pois a ele através-de o qual o todas-as-coisas e através-de o qual o todas-as-coisas a-muitos filhos para glória tendo-conduzido o príncipe o salvação deles através-de sofrimentos aperfeiçoar');
INSERT INTO verses VALUES (30041, 58, 2, 11, 'o e pois santificando e o sendo-santificados de um todos através-de o qual causa não envergonha-se irmãos eles chamar');
INSERT INTO verses VALUES (30042, 58, 2, 12, 'dizendo Anunciarei o nome teu o aos-irmãos meu em meio da-assembleia hino-cantarei te');
INSERT INTO verses VALUES (30043, 58, 2, 13, 'e novamente eu serei confiando sobre a ele e novamente Eis eu e o crianças o qual a-mim deu o Theos');
INSERT INTO verses VALUES (30044, 58, 2, 14, 'porque portanto o crianças tem-participado sangue e carne e ele semelhantemente participou o deles para que através-de o da-morte anule o o domínio tendo o da-morte isto é o diabo');
INSERT INTO verses VALUES (30045, 58, 2, 15, 'e liberte estes quanto medo da-morte através-de todo o viver Réus eram escravidão');
INSERT INTO verses VALUES (30046, 58, 2, 16, 'não pois certamente anjo toma mas semente Abraão toma');
INSERT INTO verses VALUES (30047, 58, 2, 17, 'de-onde devia segundo todas-as-coisas o aos-irmãos ser-assemelhado para que misericordioso aconteça e fiel sumo-sacerdote o junto-a o Theos para o Fazer-propiciação o do-pecado o povo');
INSERT INTO verses VALUES (30048, 58, 2, 18, 'em o qual pois tem-sofrido ele tendo-sido-tentado pode o sendo-tentados auxiliar');
INSERT INTO chapters VALUES (1136, 58, 3, 19);
INSERT INTO verses VALUES (30049, 58, 3, 1, 'de-onde irmãos santos chamado celestial participantes considerai o Apóstolo e Sumo-sacerdote o confissão nosso Iesous');
INSERT INTO verses VALUES (30050, 58, 3, 2, 'fiel sendo o que-fez ele como e Moisés em todo o na-casa dele');
INSERT INTO verses VALUES (30051, 58, 3, 3, 'maior pois este da-glória de-junto-de Moisés tem-sido-considerado-digno segundo quanto maiores honra tem o da-casa o tendo-preparado ele');
INSERT INTO verses VALUES (30052, 58, 3, 4, 'todo pois casa é-preparado por de-alguém o porém todas-as-coisas tendo-preparado Theos');
INSERT INTO verses VALUES (30053, 58, 3, 5, 'e Moisés por-um-lado fiel em todo o na-casa dele como servo para testemunho o havendo-de-ser-falados');
INSERT INTO verses VALUES (30054, 58, 3, 6, 'Christos porém como Filho sobre o casa dele o qual casa somos nós se o ousadia e o orgulho o da-esperança até fim firme retenhamos');
INSERT INTO verses VALUES (30055, 58, 3, 7, 'Por-isso assim-como diz o espírito o santo Hoje se o voz dele ouçais');
INSERT INTO verses VALUES (30056, 58, 3, 8, 'não endureçais o do-coração vosso como em o provocação segundo o dia o provação em o deserto');
INSERT INTO verses VALUES (30057, 58, 3, 9, 'do-qual tentaram o pais vosso em provação e vi o obra meu');
INSERT INTO verses VALUES (30058, 58, 3, 10, 'quarenta anos por-isso indignei-me o geração nesta e disseram Sempre são-enganados o no-coração eles-mesmos porém não conheceram o caminhos meu');
INSERT INTO verses VALUES (30059, 58, 3, 11, 'como jurei em o ira meu se entrarão para o repouso meu');
INSERT INTO verses VALUES (30060, 58, 3, 12, 'vede irmãos não alguma-vez será em a-alguém vosso coração má incredulidade em o afastar-se de de-Theos vivente');
INSERT INTO verses VALUES (30061, 58, 3, 13, 'mas exortai si-mesmos segundo Cada-uma dia até o qual o Hoje chama-se para que não seja-endurecido alguém de vosso engano o do-pecado');
INSERT INTO verses VALUES (30062, 58, 3, 14, 'participantes pois o de-Christos tornamo-nos se-de-fato o início o confiança até fim firme retenhamos');
INSERT INTO verses VALUES (30063, 58, 3, 15, 'em o ser-dito Hoje se o voz dele ouçais não endureçais o do-coração vosso como em o provocação');
INSERT INTO verses VALUES (30064, 58, 3, 16, 'quem pois ouvindo provocaram mas não todos o saindo de Egito através-de Moisés');
INSERT INTO verses VALUES (30065, 58, 3, 17, 'quais porém indignou-se quarenta anos não o tendo-pecado o qual o membros caiu em o deserto');
INSERT INTO verses VALUES (30066, 58, 3, 18, 'quais porém jurou não entrar para o descanso dele se não o tendo-desobedecido');
INSERT INTO verses VALUES (30067, 58, 3, 19, 'e vemos que não puderam entrar através-de incredulidade');
INSERT INTO chapters VALUES (1137, 58, 4, 16);
INSERT INTO verses VALUES (30068, 58, 4, 1, 'temamos portanto não alguma-vez sendo-deixada promessa entrar para o descanso dele pareça alguém de vosso ter-faltado');
INSERT INTO verses VALUES (30069, 58, 4, 2, 'e pois somos tendo-sido-anunciadas-boas-novas assim-como e-aqueles mas não Aproveitou o palavra o ouvido aqueles não tendo-sido-misturado o fé o tendo-ouvido');
INSERT INTO verses VALUES (30070, 58, 4, 3, 'Entramos pois para o descanso o tendo-crido assim-como tem-dito como jurei em o ira meu se entrarão para o repouso meu embora o obra de fundação do-mundo tendo-se-tornado');
INSERT INTO verses VALUES (30071, 58, 4, 4, 'tem-dito pois em-algum-lugar acerca-de o Sétima assim e descansou o Theos em o dia o Sétimo de todos o obra dele');
INSERT INTO verses VALUES (30072, 58, 4, 5, 'e em neste novamente se entrarão para o repouso meu');
INSERT INTO verses VALUES (30073, 58, 4, 6, 'porque portanto resta alguns entrar para ela e o antes tendo-sido-anunciadas-boas-novas não entraram através-de desobediência');
INSERT INTO verses VALUES (30074, 58, 4, 7, 'novamente algum determina dia Hoje em Davi dizendo com tanto tempo assim-como tem-sido-dito-de-antemão Hoje se o voz dele ouçais não endureçais o do-coração vosso');
INSERT INTO verses VALUES (30075, 58, 4, 8, 'se pois eles Iesous descansou não partícula-condicional acerca-de outra falava com estas-coisas do-dia');
INSERT INTO verses VALUES (30076, 58, 4, 9, 'então resta repouso-sabático o povo o de-Theos');
INSERT INTO verses VALUES (30077, 58, 4, 10, 'o pois entrando para o descanso dele e ele descansou de o obra dele como de o próprios o Theos');
INSERT INTO verses VALUES (30078, 58, 4, 11, 'Esforcemo-nos portanto entrar para aquela o descanso para que não em o a ele alguém exemplo caia o desobediência');
INSERT INTO verses VALUES (30079, 58, 4, 12, 'Vivente pois o palavra o de-Theos e eficaz e mais-cortante em-favor-de toda espada de-dois-gumes e penetrando até divisão alma e do-espírito juntas e e medulas e discernidor pensamentos e pensamentos do-coração');
INSERT INTO verses VALUES (30080, 58, 4, 13, 'e não é criação invisível diante-de dele todas-as-coisas porém nus e tendo-sido-desnudados o olhos dele junto-a o qual a-nós o palavra');
INSERT INTO verses VALUES (30081, 58, 4, 14, 'tendo portanto sumo-sacerdote grande tendo-atravessado o céus Iesous o Filho o de-Theos seguraremos o confissão');
INSERT INTO verses VALUES (30082, 58, 4, 15, 'não pois temos sumo-sacerdote não podendo compadecer-se o fraquezas nosso tendo-sido-tentado porém segundo todas-as-coisas segundo semelhança sem do-pecado');
INSERT INTO verses VALUES (30083, 58, 4, 16, 'aproximemo-nos portanto com ousadia o trono o da-graça para que recebamos misericórdia e graça encontremos para oportuno auxílio');
INSERT INTO chapters VALUES (1138, 58, 5, 14);
INSERT INTO verses VALUES (30084, 58, 5, 1, 'todo pois sumo-sacerdote de dos-homens sendo-recebido em-favor-de dos-homens é-constituído o junto-a o Theos para que ofereça ofertas e e sacrifício em-favor-de pecados');
INSERT INTO verses VALUES (30085, 58, 5, 2, 'ter-compaixão-moderada podendo o ignoram e sendo-enganados porque e ele está-posto-ao-redor fraqueza');
INSERT INTO verses VALUES (30086, 58, 5, 3, 'e através-de ela deve assim-como acerca-de o povo assim e acerca-de si-mesmo oferecer acerca-de dos-pecados');
INSERT INTO verses VALUES (30087, 58, 5, 4, 'e não si-mesmo alguém recebe o honra mas chamado sob o de-Theos assim-como e Aarão');
INSERT INTO verses VALUES (30088, 58, 5, 5, 'assim e o Christos não si-mesmo glorificou tornar-se sumo-sacerdote mas o tendo-falado junto-a ele filho meu és tu eu hoje gerei te');
INSERT INTO verses VALUES (30089, 58, 5, 6, 'assim-como e em a-outro diz tu sacerdote para o eternidade segundo o ordem Melquisedeque');
INSERT INTO verses VALUES (30090, 58, 5, 7, 'o qual em o dias o carne dele súplicas e e Súplica junto-a o podendo salvar ele de da-morte com clamor forte e lágrimas tendo-oferecido e tendo-sido-ouvido de o reverência');
INSERT INTO verses VALUES (30091, 58, 5, 8, 'embora sendo filho Aprendeu de o qual sofreu o obediência');
INSERT INTO verses VALUES (30092, 58, 5, 9, 'e tendo-sido-aperfeiçoado aconteceu todos o obedecem a ele causa salvação eterno');
INSERT INTO verses VALUES (30093, 58, 5, 10, 'tendo-sido-designado sob o de-Theos sumo-sacerdote segundo o ordem Melquisedeque');
INSERT INTO verses VALUES (30094, 58, 5, 11, 'acerca-de o qual muito a-nós o palavra e difícil-de-explicar dizer porque lentos tornastes-vos o ouvidos');
INSERT INTO verses VALUES (30095, 58, 5, 12, 'e pois devendo ser mestres através-de o tempo novamente necessidade tendes o ensinar vos alguém o elementos o princípio o oráculos o de-Theos e tornastes-vos necessidade tendo leite não sólida alimento');
INSERT INTO verses VALUES (30096, 58, 5, 13, 'todo pois o participando leite inexperiente da-palavra justiça infante pois é');
INSERT INTO verses VALUES (30097, 58, 5, 14, 'de-perfeitos e/mas é o sólida alimento o através-de o prática o sentidos tendo-sido-exercitados tendo junto-a discernimento bom e e mal');
INSERT INTO chapters VALUES (1139, 58, 6, 20);
INSERT INTO verses VALUES (30098, 58, 6, 1, 'por-isso deixando o o princípio o de-Christos palavra sobre o perfeição sejamos-levados não novamente fundamento sendo-derrubados arrependimento de mortos obra e da-fé sobre Theos');
INSERT INTO verses VALUES (30099, 58, 6, 2, 'batismos ensino imposição e mãos ressurreição mortos e julgamento eterno');
INSERT INTO verses VALUES (30100, 58, 6, 3, 'e isto faremos se-de-fato Permita o Theos');
INSERT INTO verses VALUES (30101, 58, 6, 4, 'Impossível pois o uma-vez os-tendo-sido-iluminados tendo-provado e o dom o celestial e participantes tendo-se-tornado do-espírito do-santo');
INSERT INTO verses VALUES (30102, 58, 6, 5, 'e belo tendo-provado de-Theos palavra poderes e do-que-está-por-vir eternidade');
INSERT INTO verses VALUES (30103, 58, 6, 6, 'e os-tendo-caído novamente renovar para arrependimento crucificando-de-novo si-mesmos o Filho o de-Theos e expondo-a-vergonha-pública');
INSERT INTO verses VALUES (30104, 58, 6, 7, 'terra pois o tendo-bebido o sobre dela o-que-vem muitas-vezes chuva e dando-à-luz erva apropriado àqueles através-de o qual e é-cultivada participa bênção de o de-Theos');
INSERT INTO verses VALUES (30105, 58, 6, 8, 'produzindo porém espinhos e abrolhos reprovado e maldição perto o qual o fim para queima');
INSERT INTO verses VALUES (30106, 58, 6, 9, 'Temos-sido-persuadidos porém acerca-de vosso amados o melhor e Seguintes salvação se e assim falamos');
INSERT INTO verses VALUES (30107, 58, 6, 10, 'não pois injusto o Theos esquecer-se o obra vosso e o do-amor o qual mostrastes para o nome dele tendo-servido o santos e servindo');
INSERT INTO verses VALUES (30108, 58, 6, 11, 'desejamos porém cada-um vosso o ela mostrar diligência junto-a o plena-convicção o da-esperança até fim');
INSERT INTO verses VALUES (30109, 58, 6, 12, 'para que não lentos torneis-vos imitadores porém o através-de da-fé e paciência herdando o promessa');
INSERT INTO verses VALUES (30110, 58, 6, 13, 'o pois Abraão tendo-prometido o Theos porque segundo de-ninguém tinha maior jurar jurou segundo si-mesmo');
INSERT INTO verses VALUES (30111, 58, 6, 14, 'dizendo se certamente bendizendo abençoarei te e multiplicando multiplicarei te');
INSERT INTO verses VALUES (30112, 58, 6, 15, 'e assim tendo-sido-paciente alcançou o promessa');
INSERT INTO verses VALUES (30113, 58, 6, 16, 'homens pois segundo o maior juram e toda a-eles contradição limite para confirmação o juramento');
INSERT INTO verses VALUES (30114, 58, 6, 17, 'em o qual abundantemente querendo o Theos mostrar o herdeiros o promessa o imutável o conselho dele mediou juramento');
INSERT INTO verses VALUES (30115, 58, 6, 18, 'para que através-de dois coisas imutáveis em o qual impossível mentir Theos forte consolação tenhamos o tendo-fugido-para agarrar o estando-posta-diante da-esperança');
INSERT INTO verses VALUES (30116, 58, 6, 19, 'o qual como âncora temos o alma seguro e e firme e entrando para o Interior o véu');
INSERT INTO verses VALUES (30117, 58, 6, 20, 'onde precursor em-favor-de nosso entrou Iesous segundo o ordem Melquisedeque sumo-sacerdote tendo-se-tornado para o eternidade');
INSERT INTO chapters VALUES (1140, 58, 7, 28);
INSERT INTO verses VALUES (30118, 58, 7, 1, 'este pois o Melquisedeque rei Salém sacerdote o de-Theos o Altíssimo o tendo-encontrado Abraão Retornando de o matança o reis e tendo-abençoado ele');
INSERT INTO verses VALUES (30119, 58, 7, 2, 'o qual e décima de todos dividiu Abraão primeiro por-um-lado Sendo-interpretado rei da-justiça depois porém e rei Salém o qual é rei paz');
INSERT INTO verses VALUES (30120, 58, 7, 3, 'sem-pai sem-mãe sem-genealogia nem início dos-dias nem da-vida fim tendo tendo-sido-assemelhado porém o filho o de-Theos permanece sacerdote para o perpétuo');
INSERT INTO verses VALUES (30121, 58, 7, 4, 'Contemplai porém quão-grande este o qual décima Abraão deu de o primícias o patriarca');
INSERT INTO verses VALUES (30122, 58, 7, 5, 'e o por-um-lado de o dos-filhos Levi o Sacerdócio recebendo mandamento têm dizimar o povo segundo o lei isto é o irmãos deles embora tendo-saído de o lombo Abraão');
INSERT INTO verses VALUES (30123, 58, 7, 6, 'o porém não sendo-genealogizado de deles tem-dizimado Abraão e o tendo o promessa tem-abençoado');
INSERT INTO verses VALUES (30124, 58, 7, 7, 'sem porém toda contradição o menor sob o melhor é-abençoado');
INSERT INTO verses VALUES (30125, 58, 7, 8, 'e aqui por-um-lado dízimos morrendo homens recebem ali porém sendo-testificado que vive');
INSERT INTO verses VALUES (30126, 58, 7, 9, 'e como Palavra dizer através-de Abraão e Levi o dízimos recebendo tem-sido-dizimado');
INSERT INTO verses VALUES (30127, 58, 7, 10, 'ainda pois em o lombo o do-Pai era quando encontrou a ele Melquisedeque');
INSERT INTO verses VALUES (30128, 58, 7, 11, 'se por-um-lado portanto perfeição através-de o Levítica sacerdócio era o povo pois sobre dela tem-sido-legislado quem ainda necessidade segundo o ordem Melquisedeque outro levantar-se sacerdote e não segundo o ordem Aarão ser-dito');
INSERT INTO verses VALUES (30129, 58, 7, 12, 'sendo-transferida pois o sacerdócio de necessidade e da-lei mudança torna-se');
INSERT INTO verses VALUES (30130, 58, 7, 13, 'sobre o qual pois é-chamado estas-coisas tribo outra tem-participado de o qual ninguém tem-atentado o altar');
INSERT INTO verses VALUES (30131, 58, 7, 14, 'evidente pois que de Judá tem-nascido o Kyrios nosso para o qual tribo acerca-de sacerdotes nada Moisés falou');
INSERT INTO verses VALUES (30132, 58, 7, 15, 'e abundantemente ainda evidente é se segundo o semelhança Melquisedeque levanta-se sacerdote outro');
INSERT INTO verses VALUES (30133, 58, 7, 16, 'o qual não segundo lei mandamento de-carnal aconteceu mas segundo poder da-vida indissolúvel');
INSERT INTO verses VALUES (30134, 58, 7, 17, 'é-testemunhado pois que tu sacerdote para o eternidade segundo o ordem Melquisedeque');
INSERT INTO verses VALUES (30135, 58, 7, 18, 'anulação por-um-lado pois torna-se indo-adiante mandamento através-de o dela fraco e inútil');
INSERT INTO verses VALUES (30136, 58, 7, 19, 'nada pois Aperfeiçoou o lei introdução-de porém melhor da-esperança através-de o qual aproximamo-nos o a-Theos');
INSERT INTO verses VALUES (30137, 58, 7, 20, 'e segundo quanto não sem juramento o por-um-lado pois sem juramento são sacerdotes tendo-se-tornado');
INSERT INTO verses VALUES (30138, 58, 7, 21, 'o porém com juramento através-de o dizendo junto-a ele jurou Kyrios e não arrepender-se-á tu sacerdote para o eternidade');
INSERT INTO verses VALUES (30139, 58, 7, 22, 'segundo tanto e melhor da-aliança aconteceu Fiador Iesous');
INSERT INTO verses VALUES (30140, 58, 7, 23, 'e o por-um-lado mais-numerosos são tendo-se-tornado sacerdotes através-de o morte ser-impedido permanecer');
INSERT INTO verses VALUES (30141, 58, 7, 24, 'o porém através-de o permanecer ele para o eternidade intransferível tem o Sacerdócio');
INSERT INTO verses VALUES (30142, 58, 7, 25, 'de-onde e salvar para o completo pode o aproximando-se através-de dele o a-Theos sempre vivendo para o interceder em-favor-de deles');
INSERT INTO verses VALUES (30143, 58, 7, 26, 'Tal pois a-nós e Convinha sumo-sacerdote santo inocente incontaminado tendo-sido-separado de o dos-pecadores e Mais-alto o dos-céus tendo-se-tornado');
INSERT INTO verses VALUES (30144, 58, 7, 27, 'o qual não tem segundo dia necessidade assim-como o sumos-sacerdotes antes em-favor-de o próprios dos-pecados sacrifício oferecer depois o o povo isto pois fez de-uma-vez-por-todas si-mesmo tendo-oferecido');
INSERT INTO verses VALUES (30145, 58, 7, 28, 'o lei pois homens constitui sumos-sacerdotes tendo fraqueza o palavra porém o juramento o com o lei filho para o eternidade tendo-sido-aperfeiçoado');
INSERT INTO chapters VALUES (1141, 58, 8, 13);
INSERT INTO verses VALUES (30146, 58, 8, 1, 'Ponto-principal porém sobre o chamados tal temos sumo-sacerdote o qual sentou-se em direita o trono o Majestade em o nos-céus');
INSERT INTO verses VALUES (30147, 58, 8, 2, 'o dos-santos ministro e o tabernáculo o verdadeira o qual Fincou o Kyrios não homem');
INSERT INTO verses VALUES (30148, 58, 8, 3, 'todo pois sumo-sacerdote para o oferecer ofertas e e sacrifício é-constituído de-onde necessário ter algo e este o qual ofereça');
INSERT INTO verses VALUES (30149, 58, 8, 4, 'se por-um-lado portanto era sobre da-terra nem partícula-condicional era sacerdote existindo o oferecendo segundo lei o presentes');
INSERT INTO verses VALUES (30150, 58, 8, 5, 'os-quais exemplo e sombra servem o celestiais assim-como tem-sido-revelado Moisés estando-prestes-a Completar o tenda veja pois diz farás todas-as-coisas segundo o modelo o tendo-sido-mostradas a-ti em o no-monte');
INSERT INTO verses VALUES (30151, 58, 8, 6, 'agora porém mais-excelente tem-obtido serviço quanto e melhor é da-aliança mediador a-qual sobre melhores promessas tem-sido-legislado');
INSERT INTO verses VALUES (30152, 58, 8, 7, 'se pois o primeiro aquela era irrepreensível não partícula-condicional segunda era-procurado lugar');
INSERT INTO verses VALUES (30153, 58, 8, 8, 'censurando pois eles diz Eis dias vêm diz Kyrios e completarei sobre o casa Israel e sobre o casa Judá aliança nova');
INSERT INTO verses VALUES (30154, 58, 8, 9, 'não segundo o aliança o qual fiz o pais deles em dia tendo-tomado-de meu o da-mão deles conduzir-para-fora eles de da-terra Egito que eles-mesmos não permaneceram em o aliança meu e-eu negligenciei deles diz Kyrios');
INSERT INTO verses VALUES (30155, 58, 8, 10, 'que esta o aliança o qual estabelecerei o na-casa Israel com o do-dia aquelas diz Kyrios dando leis meu para o entendimento deles e sobre do-coração deles inscreverei eles e serei a-eles para Theos e eles-mesmos serão a-mim para povo');
INSERT INTO verses VALUES (30156, 58, 8, 11, 'e não não ensinem cada-um o cidadão dele e cada-um o irmão dele dizendo Conhece o Kyrion que todos sei me de pequeno até grande deles');
INSERT INTO verses VALUES (30157, 58, 8, 12, 'que Propício serei o injustiças deles e o dos-pecados deles não não lembre-me ainda');
INSERT INTO verses VALUES (30158, 58, 8, 13, 'em o dizer nova tem-tornado-obsoleto o primeiro o porém sendo-envelhecido e envelhecendo perto destruição');
INSERT INTO chapters VALUES (1142, 58, 9, 28);
INSERT INTO verses VALUES (30159, 58, 9, 1, 'Tinha por-um-lado portanto e o primeiro atos-justos serviço-sagrado o e santo mundano');
INSERT INTO verses VALUES (30160, 58, 9, 2, 'tabernáculo pois foi-preparado o primeiro em o qual o e candelabro e o mesa e o propósito o pães a-qual é-dito Santas');
INSERT INTO verses VALUES (30161, 58, 9, 3, 'com porém o segunda-vez véu tenda o sendo-chamada Santas dos-santos');
INSERT INTO verses VALUES (30162, 58, 9, 4, 'dourado tendo incensário e o arca o da-aliança tendo-sido-coberta de-todo-lado ouro em o qual vaso dourado tendo o maná e o vara Aarão o tendo-brotado e o tábuas o da-aliança');
INSERT INTO verses VALUES (30163, 58, 9, 5, 'muito-acima porém dela Querubins da-glória cobrindo-com-sombra o propiciatório acerca-de o qual não é agora dizer segundo parte');
INSERT INTO verses VALUES (30164, 58, 9, 6, 'estas porém assim tendo-sido-preparados para por-um-lado o primeiro tabernáculo através-de de-todo entram o sacerdotes o serviço-sagrado completando');
INSERT INTO verses VALUES (30165, 58, 9, 7, 'para porém o segunda uma-vez o ano só o sumo-sacerdote não sem sangue o qual oferece em-favor-de si-mesmo e o o povo ignorâncias');
INSERT INTO verses VALUES (30166, 58, 9, 8, 'isto manifestando o do-espírito o do-santo ainda-não ter-sido-manifestado o o dos-santos caminho ainda o primeiro tabernáculo tendo dissensão');
INSERT INTO verses VALUES (30167, 58, 9, 9, 'a-qual parábola para o tempo o tendo-se-apresentado segundo o qual ofertas e e sacrifícios são-oferecidos não podendo segundo consciência aperfeiçoar o servindo');
INSERT INTO verses VALUES (30168, 58, 9, 10, 'somente sobre alimentos e em-bebidas e diversas batismos atos-justos carne até tempo correção impostas');
INSERT INTO verses VALUES (30169, 58, 9, 11, 'Christos porém tendo-chegado sumo-sacerdote o tendo-acontecido boas-coisas através-de o maior e mais-perfeita tabernáculo não feito-por-mãos isto é não desta o criação');
INSERT INTO verses VALUES (30170, 58, 9, 12, 'nem através-de sangue bodes e bezerros através-de porém o próprio sangue entrou de-uma-vez-por-todas para o santas eterna redenção tendo-encontrado');
INSERT INTO verses VALUES (30171, 58, 9, 13, 'se pois o sangue bodes e touros e cinza novilha aspergindo o tendo-sido-tornados-comuns santifica junto-a o o carne pureza');
INSERT INTO verses VALUES (30172, 58, 9, 14, 'quanto mais o sangue o de-Christos o qual através-de do-espírito eterno si-mesmo ofereceu amomo o a-Theos purificará o consciência nosso de mortos obra para o servir-cultualmente a-Theos vivendo');
INSERT INTO verses VALUES (30173, 58, 9, 15, 'e através-de isto da-aliança nova mediador é para-que da-morte tendo-acontecido para redenção o sobre o primeiro aliança transgressões o promessa recebam o chamados o eterno herança');
INSERT INTO verses VALUES (30174, 58, 9, 16, 'onde pois aliança morte necessidade ser-levado o tendo-disposto');
INSERT INTO verses VALUES (30175, 58, 9, 17, 'aliança pois sobre mortos firme porque não alguma-vez tem-poder quando vive o tendo-disposto');
INSERT INTO verses VALUES (30176, 58, 9, 18, 'de-onde nem o primeiro sem sangue tem-sido-inaugurado');
INSERT INTO verses VALUES (30177, 58, 9, 19, 'tendo-sido-falada pois toda mandamento segundo o lei sob de-Moisés todo o povo tomando o sangue o bezerros e o bodes com água e Lã escarlate e Hissopo isso e o livro e todas-as-coisas o povo aspergiu');
INSERT INTO verses VALUES (30178, 58, 9, 20, 'dizendo isto o sangue o da-aliança o qual ordenou junto-a vos o Theos');
INSERT INTO verses VALUES (30179, 58, 9, 21, 'e o tenda porém e todas-as-coisas o vasos o serviço o sangue semelhantemente aspergiu');
INSERT INTO verses VALUES (30180, 58, 9, 22, 'e quase em sangue todas-as-coisas é-purificado segundo o lei e sem derramamento-de-sangue não torna-se remissão');
INSERT INTO verses VALUES (30181, 58, 9, 23, 'Necessidade portanto o por-um-lado Exemplos o em o nos-céus nestes ser-purificado eles porém o celestiais melhores sacrifícios de-junto-de estas');
INSERT INTO verses VALUES (30182, 58, 9, 24, 'não pois para feitos-por-mãos entrou santas Christos antítipos o verdadeiros mas para ele o céu agora ser-revelado o face o de-Theos em-favor-de nosso');
INSERT INTO verses VALUES (30183, 58, 9, 25, 'nem para que muitas-vezes ofereça a-si-mesmo assim-como o sumo-sacerdote entra para o santas segundo ano em sangue estranho');
INSERT INTO verses VALUES (30184, 58, 9, 26, 'porque é necessário ele muitas-vezes sofrer de fundação do-mundo agora porém uma-vez sobre consumação o eras para anulação o do-pecado através-de o sacrifício dele tem-sido-manifestado');
INSERT INTO verses VALUES (30185, 58, 9, 27, 'e segundo quanto está-reservado o aos-homens uma-vez morrer com porém isto julgamento');
INSERT INTO verses VALUES (30186, 58, 9, 28, 'assim e o Christos uma-vez tendo-sido-oferecido para o muitos oferecer do-pecado de segunda sem do-pecado será-visto o ele aos-que-aguardam-ansiosamente para salvação');
INSERT INTO chapters VALUES (1143, 58, 10, 39);
INSERT INTO verses VALUES (30187, 58, 10, 1, 'Sombra pois tendo o lei o estando-para boas-coisas não ela o imagem o coisas segundo ano o elas sacrifícios o qual oferecem para o perpetuidade nunca pode o aproximando-se aperfeiçoar');
INSERT INTO verses VALUES (30188, 58, 10, 2, 'porque não partícula-condicional cessaram sendo-oferecidas através-de o nenhuma ter ainda consciência dos-pecados o servindo uma-vez tendo-sido-purificados');
INSERT INTO verses VALUES (30189, 58, 10, 3, 'mas em elas recordação dos-pecados segundo ano');
INSERT INTO verses VALUES (30190, 58, 10, 4, 'impossível pois sangue touros e bodes tirar do-pecado');
INSERT INTO verses VALUES (30191, 58, 10, 5, 'por-isso entrando para o mundo diz Sacrifício e oferta não quiseste corpo porém preparaste a-mim');
INSERT INTO verses VALUES (30192, 58, 10, 6, 'holocaustos e acerca-de do-pecado não tiveste-prazer');
INSERT INTO verses VALUES (30193, 58, 10, 7, 'então disseram Eis venho em rolo livro está-escrito acerca-de mim o fazer o Theos o vontade teu');
INSERT INTO verses VALUES (30194, 58, 10, 8, 'mais-acima dizendo que Sacrifício e ofertas e holocaustos e acerca-de do-pecado não quiseste nem tiveste-prazer as-quais segundo lei são-oferecidos');
INSERT INTO verses VALUES (30195, 58, 10, 9, 'então tem-dito Eis venho o fazer o vontade teu mata o primeiro para que o segundo estabeleça');
INSERT INTO verses VALUES (30196, 58, 10, 10, 'em o qual vontade tendo-sido-santificados somos através-de o de-oferta o do-corpo Iesous de-Christos de-uma-vez-por-todas');
INSERT INTO verses VALUES (30197, 58, 10, 11, 'e todo por-um-lado sacerdote está-de-pé segundo dia ministrando e o elas muitas-vezes oferecendo sacrifício as-quais nunca podem remover do-pecado');
INSERT INTO verses VALUES (30198, 58, 10, 12, 'este porém uma em-favor-de dos-pecados tendo-oferecido sacrifício para o perpetuidade sentou-se em direita o de-Theos');
INSERT INTO verses VALUES (30199, 58, 10, 13, 'o restante esperando até sejam-postos o inimigos dele estrado o pés dele');
INSERT INTO verses VALUES (30200, 58, 10, 14, 'uma pois em-oferta tem-aperfeiçoado para o perpetuidade o sendo-santificados');
INSERT INTO verses VALUES (30201, 58, 10, 15, 'Testifica porém a-nós e o espírito o santo com pois o ter-dito');
INSERT INTO verses VALUES (30202, 58, 10, 16, 'esta o aliança o qual estabelecerei junto-a eles com o do-dia aquelas diz Kyrios dando leis meu sobre do-coração deles e sobre o entendimento deles inscreverei eles');
INSERT INTO verses VALUES (30203, 58, 10, 17, 'e o dos-pecados deles e o iniquidades deles não não lembrarei ainda');
INSERT INTO verses VALUES (30204, 58, 10, 18, 'onde porém remissão destes não-mais oferta acerca-de do-pecado');
INSERT INTO verses VALUES (30205, 58, 10, 19, 'tendo portanto irmãos ousadia para o entrada o dos-santos em o sangue Iesous');
INSERT INTO verses VALUES (30206, 58, 10, 20, 'o qual inaugurou a-nós caminho recente e vivente através-de o véu isto é o carne dele');
INSERT INTO verses VALUES (30207, 58, 10, 21, 'e sacerdote grande sobre o casa o de-Theos');
INSERT INTO verses VALUES (30208, 58, 10, 22, 'aproximemo-nos com verdadeira do-coração em plena-convicção da-fé tendo-sido-aspergidos o do-coração de consciência perversa e tendo-sido-lavados o corpo água puro');
INSERT INTO verses VALUES (30209, 58, 10, 23, 'retenhamos o confissão o da-esperança inabalável fiel pois o tendo-prometido');
INSERT INTO verses VALUES (30210, 58, 10, 24, 'e consideremos uns-aos-outros para provocação do-amor e boas obra');
INSERT INTO verses VALUES (30211, 58, 10, 25, 'não abandonando o Reunião deles-mesmos assim-como costume alguns mas exortando e tão-grande mais quanto vede aproximando-se o dia');
INSERT INTO verses VALUES (30212, 58, 10, 26, 'Voluntariamente pois pecando nosso com o receber o conhecimento-pleno o da-verdade não-mais acerca-de dos-pecados resta sacrifício');
INSERT INTO verses VALUES (30213, 58, 10, 27, 'temível e/mas alguém expectativa julgamento e fogo zelo comer do-que-está-por-vir o Contrários');
INSERT INTO verses VALUES (30214, 58, 10, 28, 'tendo-rejeitado alguém lei de-Moisés sem compaixões sobre dois ou três testemunhas morre');
INSERT INTO verses VALUES (30215, 58, 10, 29, 'quanto pensais de-pior será-considerado-digno castigo o o Filho o de-Theos tendo-pisado e o sangue o da-aliança comum tendo-considerado em o qual Foi-santificado e o espírito o da-graça tendo-ultrajado');
INSERT INTO verses VALUES (30216, 58, 10, 30, 'sei pois o tendo-dito A-mim vingança eu retribuirei e novamente Julgará Kyrios o povo dele');
INSERT INTO verses VALUES (30217, 58, 10, 31, 'terrível o cair-em para mãos de-Theos vivente');
INSERT INTO verses VALUES (30218, 58, 10, 32, 'Lembrai-vos porém o antes do-dia em o qual tendo-sido-iluminados muita luta Perseverastes sofrimentos');
INSERT INTO verses VALUES (30219, 58, 10, 33, 'isto por-um-lado injúrias e e tribulações sendo-expostos-publicamente isto porém participantes o assim conduzindo-se tendo-se-tornado');
INSERT INTO verses VALUES (30220, 58, 10, 34, 'e pois o prisioneiros compadecestes-vos e o rapina o posses vosso com alegria recebestes conhecendo ter si-mesmos melhor Bens e permanecendo');
INSERT INTO verses VALUES (30221, 58, 10, 35, 'não lanceis-fora portanto o ousadia vosso a-qual tem grande recompensa');
INSERT INTO verses VALUES (30222, 58, 10, 36, 'perseverança pois tendes necessidade para que o vontade o de-Theos tendo-feito recebereis o promessa');
INSERT INTO verses VALUES (30223, 58, 10, 37, 'ainda pois pouco quanto quanto o o-que-vem virá e não demorará');
INSERT INTO verses VALUES (30224, 58, 10, 38, 'o porém justo meu de da-fé viverá e se Retraia-se não compraz-se o alma meu em a ele');
INSERT INTO verses VALUES (30225, 58, 10, 39, 'nós porém não somos Retrocesso para perdição mas da-fé para aquisição alma');
INSERT INTO chapters VALUES (1144, 58, 11, 40);
INSERT INTO verses VALUES (30226, 58, 11, 1, 'É porém fé sendo-esperados Substância coisas Prova não sendo-vistas');
INSERT INTO verses VALUES (30227, 58, 11, 2, 'em nesta pois foram-testemunhados o anciãos');
INSERT INTO verses VALUES (30228, 58, 11, 3, 'pela-fé entendemos ter-sido-restaurado o eras palavra de-Theos para o não de aparecendo o sendo-visto ter-acontecido');
INSERT INTO verses VALUES (30229, 58, 11, 4, 'pela-fé mais sacrifício Abel de-junto-de Caim ofereceu o a-Theos através-de o qual foi-testemunhado ser justo testemunhando sobre o presentes dele o de-Theos e através-de dela tendo-morrido ainda fala');
INSERT INTO verses VALUES (30230, 58, 11, 5, 'pela-fé Enoque foi-transferido o não ver morte e não era-encontrado porque transferiu ele o Theos antes-de pois o mudança tem-sido-testificado ter-agradado o a-Theos');
INSERT INTO verses VALUES (30231, 58, 11, 6, 'sem porém da-fé impossível agradar crer pois é necessário o aproximando-se o a-Theos que é e o buscam-diligentemente ele recompensador torna-se');
INSERT INTO verses VALUES (30232, 58, 11, 7, 'pela-fé tendo-sido-avisado-divinamente Noé acerca-de o ainda-não sendo-vistas tendo-sido-reverente preparou arca para salvação o da-casa dele através-de o qual condenou o mundo e o segundo fé da-justiça aconteceu herdeiro');
INSERT INTO verses VALUES (30233, 58, 11, 8, 'pela-fé chamado Abraão obedeceu sair para lugar o qual estava-prestes-a receber para herança e saiu não sabendo onde vem');
INSERT INTO verses VALUES (30234, 58, 11, 9, 'pela-fé peregrinou para terra o promessa como alheia em tendas tendo-habitado com Isaque e Jacó o co-herdeiros o promessa o dela');
INSERT INTO verses VALUES (30235, 58, 11, 10, 'esperava pois o o fundamentos tendo cidade o qual artífice e artífice o Theos');
INSERT INTO verses VALUES (30236, 58, 11, 11, 'pela-fé e a-ela Sara poder para fundação semente recebeu e de-junto-de tempo estatura porque fiel considerou o tendo-prometido');
INSERT INTO verses VALUES (30237, 58, 11, 12, 'por-isso e de de-um foram-gerados e estas-coisas tendo-sido-mortificado assim-como o estrelas o do-céu o multidão e como o areia o de-junto-de o lábio o do-mar o inumerável');
INSERT INTO verses VALUES (30238, 58, 11, 13, 'segundo fé morreram estes todos não tendo-recebido o promessa mas de-longe a-elas vendo e tendo-saudado e tendo-confessado que estrangeiros e peregrinos são sobre o da-terra');
INSERT INTO verses VALUES (30239, 58, 11, 14, 'o pois tais-coisas dizendo revelam que pátria buscam');
INSERT INTO verses VALUES (30240, 58, 11, 15, 'e se por-um-lado daquela lembravam de o qual saíram tinham partícula-condicional tempo retornar');
INSERT INTO verses VALUES (30241, 58, 11, 16, 'agora porém melhor aspiram isto é celestial por-isso não envergonha-se eles o Theos Theos invocar deles Preparou pois a-eles cidade');
INSERT INTO verses VALUES (30242, 58, 11, 17, 'pela-fé tem-oferecido Abraão o Isaque tentado e o unigênito oferecia o o promessa tendo-recebido');
INSERT INTO verses VALUES (30243, 58, 11, 18, 'junto-a o qual foi-falado que em Isaque será-chamado a-ti semente');
INSERT INTO verses VALUES (30244, 58, 11, 19, 'tendo-considerado que e de mortos levantar poderoso o Theos de-onde ele e em parábola recebeu-de-volta');
INSERT INTO verses VALUES (30245, 58, 11, 20, 'pela-fé e acerca-de das-coisas-que-estão-a-ponto-de abençoou Isaque o Jacó e o Esaú');
INSERT INTO verses VALUES (30246, 58, 11, 21, 'pela-fé Jacó morrendo cada-um o dos-filhos José abençoou e adorou sobre o extremidade o Vara dele');
INSERT INTO verses VALUES (30247, 58, 11, 22, 'pela-fé José morrendo acerca-de o partida o dos-filhos Israel lembrou e acerca-de o ossos dele ordenou');
INSERT INTO verses VALUES (30248, 58, 11, 23, 'pela-fé Moisés tendo-sido-gerado escondeu-se três-meses sob o dos-pais dele porque vi belo o criança e não temeram o decreto o rei');
INSERT INTO verses VALUES (30249, 58, 11, 24, 'pela-fé Moisés grande tendo-se-tornado negou ser-dito Filho filha Faraó');
INSERT INTO verses VALUES (30250, 58, 11, 25, 'mais Tendo-escolhido ser-maltratado-com o povo o de-Theos ou temporário ter do-pecado deleite');
INSERT INTO verses VALUES (30251, 58, 11, 26, 'maior riqueza tendo-considerado o Egito tesouros o opróbrio o de-Christos olhava pois para o recompensa');
INSERT INTO verses VALUES (30252, 58, 11, 27, 'pela-fé deixou Egito não tendo-temido o furor o rei o pois invisível como vendo perseverou');
INSERT INTO verses VALUES (30253, 58, 11, 28, 'pela-fé tem-feito o páscoa e o aspersão o sangue para que não o destruindo o primogênitos toque deles');
INSERT INTO verses VALUES (30254, 58, 11, 29, 'pela-fé atravessaram o Vermelho Mar como através-de seca da-terra o qual prova tendo-tomado o Egípcios foram-tragados');
INSERT INTO verses VALUES (30255, 58, 11, 30, 'pela-fé o muros Jericó caíram tendo-sido-cercado sobre sete do-dia');
INSERT INTO verses VALUES (30256, 58, 11, 31, 'pela-fé Raabe o prostituta não pereceu-junto o tendo-desobedecido tendo-recebido o espiões com paz');
INSERT INTO verses VALUES (30257, 58, 11, 32, 'e quê ainda digo faltará me pois narrando o tempo acerca-de Gedeão Baraque Sansão Jefté Davi e e Samuel e o profetas');
INSERT INTO verses VALUES (30258, 58, 11, 33, 'o qual através-de da-fé venceram do-reino trabalharam justiça obtiveram promessas Taparam bocas leões');
INSERT INTO verses VALUES (30259, 58, 11, 34, 'Apagaram poder fogo fugiram bocas espada foram-fortalecidos de fraqueza tornaram-se Fortes em guerra acampamentos Inclinaram estranhos');
INSERT INTO verses VALUES (30260, 58, 11, 35, 'receberam mulheres de da-ressurreição o mortos deles outros porém Foram-torturados não tendo-recebido o redenção para que melhor da-ressurreição obtenham');
INSERT INTO verses VALUES (30261, 58, 11, 36, 'outros porém escárnios e açoites prova receberam ainda porém prisões e de-prisão');
INSERT INTO verses VALUES (30262, 58, 11, 37, 'foram-apedrejados foram-tentados Foram-serrados em em-homicídio espada morreram percorreram em peles-de-ovelha em de-cabras peles Faltando sendo-atribulados sendo-maltratados');
INSERT INTO verses VALUES (30263, 58, 11, 38, 'o qual não era digno o mundo sobre Desertos errantes e montes e cavernas e o cavernas o da-terra');
INSERT INTO verses VALUES (30264, 58, 11, 39, 'e estes todos tendo-sido-testemunhados através-de o da-fé não receberam-de-volta o promessa');
INSERT INTO verses VALUES (30265, 58, 11, 40, 'o de-Theos acerca-de nosso melhor algo tendo-provido-de-antemão para que não sem nosso sejam-aperfeiçoados');
INSERT INTO chapters VALUES (1145, 58, 12, 29);
INSERT INTO verses VALUES (30266, 58, 12, 1, 'Por-conseguinte e nós tanto tendo rodeando a-nós nuvem testemunhas peso tendo-despojado todas-as-coisas e o facilmente-envolvente pecado através-de perseverança corramos o posto-diante a-nós luta');
INSERT INTO verses VALUES (30267, 58, 12, 2, 'olhando-fixamente para o o da-fé príncipe e aperfeiçoador Iesous o qual em-troca-de o estando-posta-diante a ele alegria perseverou cruz vergonha tendo-desprezado em direita e o trono o de-Theos tem-sentado');
INSERT INTO verses VALUES (30268, 58, 12, 3, 'considerai pois o tal Tendo-perseverado sob o dos-pecadores para si-mesmo contradição para que não desfaleceis o almas vosso desfalecendo');
INSERT INTO verses VALUES (30269, 58, 12, 4, 'Ainda-não até sangue resististes junto-a o pecado lutando-contra');
INSERT INTO verses VALUES (30270, 58, 12, 5, 'e tendes-esquecido o da-consolação a-qual a-vós como filhos conversa Filho meu não menospreza disciplina do-Kyrios nem desanimes sob dele sendo-repreendido');
INSERT INTO verses VALUES (30271, 58, 12, 6, 'o qual pois ama Kyrios disciplina açoita porém todas-as-coisas Filho o qual aceita');
INSERT INTO verses VALUES (30272, 58, 12, 7, 'para disciplina Perseverais como filhos a-vós é-oferecido o Theos quem pois Filho o qual não disciplina pai');
INSERT INTO verses VALUES (30273, 58, 12, 8, 'se porém separadamente sois disciplina o qual participantes tornaram-se todos então ilegítimos e não filhos sois');
INSERT INTO verses VALUES (30274, 58, 12, 9, 'então o por-um-lado o carne nosso pais tínhamos disciplinadores e respeitávamos não muito mais Seremos-sujeitados o Pai o espíritos e viveremos');
INSERT INTO verses VALUES (30275, 58, 12, 10, 'o por-um-lado pois junto-a poucas do-dia segundo o parecendo a-eles disciplinavam o porém sobre o conveniente para o participar o santidade dele');
INSERT INTO verses VALUES (30276, 58, 12, 11, 'toda por-um-lado disciplina junto-a por-um-lado o estando-presente não parece alegria ser mas tristeza depois porém fruto pacífico o através-de dela tendo-sido-exercitados devolve da-justiça');
INSERT INTO verses VALUES (30277, 58, 12, 12, 'por-isso o tendo-sido-enfraquecidas mãos e o tendo-sido-paralisados joelhos endireitai');
INSERT INTO verses VALUES (30278, 58, 12, 13, 'e veredas retas fazei o pés vosso para que não o coxo seja-desviado Seja-curado porém mais');
INSERT INTO verses VALUES (30279, 58, 12, 14, 'Paz persegui com todos e o santificação o qual sem ninguém verá o Kyrion');
INSERT INTO verses VALUES (30280, 58, 12, 15, 'supervisionando não alguém Faltando de o da-graça o de-Theos não alguém raiz amargura acima produzindo perturbe e através-de desta sejam-contaminados o muitos');
INSERT INTO verses VALUES (30281, 58, 12, 16, 'não alguém fornicador ou profano como Esaú o qual em-troca-de alimento uma depositou o primogenitura si-mesmo');
INSERT INTO verses VALUES (30282, 58, 12, 17, 'sei pois que e depois querendo herdar o bênção foi-rejeitado arrependimento pois lugar não encontrou embora com lágrimas tendo-buscado-diligentemente ela');
INSERT INTO verses VALUES (30283, 58, 12, 18, 'não pois tendes-vos-aproximado sendo-apalpado e tendo-sido-queimado fogo e trevas-espessas e trevas e tempestade');
INSERT INTO verses VALUES (30284, 58, 12, 19, 'e de-trombeta Som e com-voz palavras o qual o ouvindo recusaram não ser-acrescentado a-eles palavra');
INSERT INTO verses VALUES (30285, 58, 12, 20, 'não traziam pois o sendo-ordenado Mesmo-se fera toque o do-monte será-apedrejado');
INSERT INTO verses VALUES (30286, 58, 12, 21, 'e assim terrível era o sendo-apresentado Moisés disse Aterrorizado sou e tremendo');
INSERT INTO verses VALUES (30287, 58, 12, 22, 'mas tendes-vos-aproximado Sião no-monte e na-cidade de-Theos vivendo Jerusalém Celestial e miríades anjo em-assembleia-festiva');
INSERT INTO verses VALUES (30288, 58, 12, 23, 'e na-igreja de-primogênitos dos-que-foram-inscritos em nos-céus e Juiz a-Theos todos e espíritos justos tendo-sido-aperfeiçoados');
INSERT INTO verses VALUES (30289, 58, 12, 24, 'e da-aliança novas mediador Iesous e sangue aspersão melhor falando de-junto-de o Abel');
INSERT INTO verses VALUES (30290, 58, 12, 25, 'Vede não recuseis o falando se pois aqueles não escaparam sobre da-terra tendo-recusado o advertindo-divinamente muito mais nós o o de dos-céus desviando-se');
INSERT INTO verses VALUES (30291, 58, 12, 26, 'o qual o voz o terra Sacudiu então agora porém tem-prometido dizendo Ainda uma-vez eu sacudirei não somente o terra mas e o céu');
INSERT INTO verses VALUES (30292, 58, 12, 27, 'o porém Ainda uma-vez manifesta o o sendo-abalados mudança como tendo-sido-feitas para que permaneça o não sendo-abalados');
INSERT INTO verses VALUES (30293, 58, 12, 28, 'por-isso reino inabalável tomando tenhamos graça através-de o qual sirvamos agradavelmente o a-Theos com reverência e temor');
INSERT INTO verses VALUES (30294, 58, 12, 29, 'e pois o Theos nosso fogo consumindo');
INSERT INTO chapters VALUES (1146, 58, 13, 25);
INSERT INTO verses VALUES (30295, 58, 13, 1, 'o amor-fraternal permaneça');
INSERT INTO verses VALUES (30296, 58, 13, 2, 'o hospitalidade não esqueceis através-de desta pois Ficou-oculto alguns tendo-hospedado anjo');
INSERT INTO verses VALUES (30297, 58, 13, 3, 'lembrais-vos o prisioneiros como tendo-sido-amarrados-com o sendo-maltratados como e eles-mesmos sendo em corpo');
INSERT INTO verses VALUES (30298, 58, 13, 4, 'Precioso o casamento em todos e o leito incontaminado fornicadores pois e adúlteros julgará o Theos');
INSERT INTO verses VALUES (30299, 58, 13, 5, 'Sem-amor-ao-dinheiro o modo contentando-se o aos-presentes ele pois tem-dito não não te deixarei nem não não te abandone');
INSERT INTO verses VALUES (30300, 58, 13, 6, 'de-modo-que tendo-confiança nos dizer Kyrios mim auxiliador não temerei quê fará a-mim homem');
INSERT INTO verses VALUES (30301, 58, 13, 7, 'Lembrai-vos o Líderes vosso os-quais falaram a-vós o palavra o de-Theos o qual observando-atentamente o saída o conduta imitai o fé');
INSERT INTO verses VALUES (30302, 58, 13, 8, 'Iesous Christos ontem e hoje o ele-mesmo e para o eras');
INSERT INTO verses VALUES (30303, 58, 13, 9, 'ensinos diversas e estranhas não sois-levados belo pois graça ser-confirmado o coração não alimentos em o qual não Foram-aproveitados o andando');
INSERT INTO verses VALUES (30304, 58, 13, 10, 'Temos altar de o qual comer não têm autoridade o o tenda servindo-sagradamente');
INSERT INTO verses VALUES (30305, 58, 13, 11, 'o qual pois é-trazido-para-dentro ser vivente o sangue acerca-de do-pecado para o santas através-de o do-sumo-sacerdote destes o corpos é-queimado fora o acampamento');
INSERT INTO verses VALUES (30306, 58, 13, 12, 'por-isso e Iesous para que santifique através-de o próprio sangue o povo fora o porta sofreu');
INSERT INTO verses VALUES (30307, 58, 13, 13, 'portanto saiamos junto-a ele fora o acampamento o opróbrio dele trazendo');
INSERT INTO verses VALUES (30308, 58, 13, 14, 'não pois temos aqui permanecendo cidade mas o vindoura buscamos');
INSERT INTO verses VALUES (30309, 58, 13, 15, 'através-de dele portanto ofereçamos sacrifício louvor através-de de-todo o a-Theos isto é fruto de-lábios confessando o em-nome dele');
INSERT INTO verses VALUES (30310, 58, 13, 16, 'o porém beneficência e comunhão não esqueceis tais pois sacrifícios agrada-se o Theos');
INSERT INTO verses VALUES (30311, 58, 13, 17, 'Obedecei o Líderes vosso e Submetei-vos eles-mesmos pois vigiam em-favor-de o almas vosso como palavra devolvendo para que com alegria isto façam e não gemendo sem-proveito pois a-vós isto');
INSERT INTO verses VALUES (30312, 58, 13, 18, 'Orai acerca-de nosso somos-persuadidos pois que boa consciência temos em todos bem querendo conduzir-se');
INSERT INTO verses VALUES (30313, 58, 13, 19, 'ainda-mais porém rogo isto fazer para que mais-rapidamente seja-restaurado a-vós');
INSERT INTO verses VALUES (30314, 58, 13, 20, 'o porém Theos o paz o tendo-conduzido-para-cima de mortos o pastor o ovelhas o grande em sangue da-aliança eterno o Kyrion nosso Iesous');
INSERT INTO verses VALUES (30315, 58, 13, 21, 'restaurar vos em todo bom para o fazer o vontade dele fazendo em a-nós o agradável diante-de dele através-de Iesous de-Christos o qual o glória para o eras o eras amém');
INSERT INTO verses VALUES (30316, 58, 13, 22, 'Exorto porém vos irmãos suportais o da-palavra o da-consolação e pois através-de poucas escrevi a-vós');
INSERT INTO verses VALUES (30317, 58, 13, 23, 'Conhecei o irmão nosso Timóteo tendo-sido-solto com o qual se mais-rapidamente venha verei vos');
INSERT INTO verses VALUES (30318, 58, 13, 24, 'Saudai todos o líderes vosso e todos o santos Saúdam vos o de o Itália');
INSERT INTO verses VALUES (30319, 58, 13, 25, 'o graça com todos vosso');
INSERT INTO books VALUES (59, 'JAS', 'Tiago', 'NT', 5);
INSERT INTO chapters VALUES (1147, 59, 1, 27);
INSERT INTO verses VALUES (30320, 59, 1, 1, 'Tiago de-Theos e do-Kyrios Iesous de-Christos servo o doze às-tribos o em o Dispersão alegrar-se');
INSERT INTO verses VALUES (30321, 59, 1, 2, 'toda alegria Considerastes irmãos meu quando tentações caiais-entre variados');
INSERT INTO verses VALUES (30322, 59, 1, 3, 'conhecendo que o prova vosso o da-fé opera perseverança');
INSERT INTO verses VALUES (30323, 59, 1, 4, 'o porém perseverança obra perfeito tenha para que éreis perfeitos e íntegros em a-ninguém faltando');
INSERT INTO verses VALUES (30324, 59, 1, 5, 'se e/mas alguém vosso é-deficiente da-sabedoria peça de-junto-de o dando de-Theos todos simplesmente e não injuriando e será-dado a ele');
INSERT INTO verses VALUES (30325, 59, 1, 6, 'peça porém em fé nada duvidando o pois duvidando assemelha-se onda mar sendo-agitado-pelo-vento e sendo-agitado-pelas-ondas');
INSERT INTO verses VALUES (30326, 59, 1, 7, 'não pois suponha o homem aquele que receberá algo de-junto-de o do-Kyrios');
INSERT INTO verses VALUES (30327, 59, 1, 8, 'homem de-dupla-mente instável em todas o caminhos dele');
INSERT INTO verses VALUES (30328, 59, 1, 9, 'Glorie-se porém o irmão o humilde em o Altura dele');
INSERT INTO verses VALUES (30329, 59, 1, 10, 'o porém rico em o humilhará dele que como flor erva passará');
INSERT INTO verses VALUES (30330, 59, 1, 11, 'nasceu pois o sol com o calor-ardente e secou o erva e o flor dele caiu e o beleza o face dele pereceram assim e o rico em o jornadas dele será-murchado');
INSERT INTO verses VALUES (30331, 59, 1, 12, 'Bem-aventurado homem o qual persevera tentação que aprovado tendo-se-tornado receberá o coroa o da-vida o qual prometeu o amam ele');
INSERT INTO verses VALUES (30332, 59, 1, 13, 'ninguém tentado diga que de de-Theos sou-tentado o pois Theos não-tentável é males tenta porém ele a-ninguém');
INSERT INTO verses VALUES (30333, 59, 1, 14, 'cada-um porém é-tentado sob o próprias desejos sendo-arrastado-para-fora e sendo-seduzido');
INSERT INTO verses VALUES (30334, 59, 1, 15, 'então o desejo tendo-concebido dá-à-luz pecado o porém pecado tendo-sido-completada gera morte');
INSERT INTO verses VALUES (30335, 59, 1, 16, 'não errais irmãos meu amados');
INSERT INTO verses VALUES (30336, 59, 1, 17, 'toda dádiva boa e todo dádiva perfeito de-cima é descendo de o do-Pai o de-luzes de-junto-de o qual não há variação ou variação sombra-de-variação');
INSERT INTO verses VALUES (30337, 59, 1, 18, 'tendo-querido gerou nos em-palavra da-verdade para o ser nos primícia alguém o dele criaturas');
INSERT INTO verses VALUES (30338, 59, 1, 19, 'sei irmãos meu amados seja porém todo homem rápido para o ouvir lento para o falar lento para ira');
INSERT INTO verses VALUES (30339, 59, 1, 20, 'ira pois homem justiça de-Theos não trabalha');
INSERT INTO verses VALUES (30340, 59, 1, 21, 'por-isso tendo-despojado toda imundicia e abundância maldade em mansidão recebei o Implantado palavra o podendo salvar o almas vosso');
INSERT INTO verses VALUES (30341, 59, 1, 22, 'tornai-vos porém praticantes da-palavra e não ouvintes somente enganando a-si-mesmos');
INSERT INTO verses VALUES (30342, 59, 1, 23, 'que se alguém ouvinte da-palavra é e não fazedor este assemelha-se marido considerando o face o origem dele em Espelho');
INSERT INTO verses VALUES (30343, 59, 1, 24, 'considerou pois si-mesmo e tem-partido e imediatamente esqueceu-se de-que-tipo era');
INSERT INTO verses VALUES (30344, 59, 1, 25, 'o porém inclinando-se para lei perfeito o o liberdade e tendo-permanecido não ouvinte esquecimento tendo-se-tornado mas praticante obra este bem-aventurado em o fará dele será');
INSERT INTO verses VALUES (30345, 59, 1, 26, 'se alguém parece religioso ser não refreando língua si-mesmo mas enganando coração si-mesmo deste vão o religião');
INSERT INTO verses VALUES (30346, 59, 1, 27, 'religião pura e incontaminado de-junto-de o a-Theos e Pai esta é visitar órfãos e viúvas em o tribulação deles sem-mancha si-mesmo guardar de o do-mundo');
INSERT INTO chapters VALUES (1148, 59, 2, 26);
INSERT INTO verses VALUES (30347, 59, 2, 1, 'Irmãos meu não em em-acepções-de-faces tendes o fé o do-Kyrios nosso Iesous de-Christos o da-glória');
INSERT INTO verses VALUES (30348, 59, 2, 2, 'se pois entre para sinagoga vosso homem com-anel-de-ouro em veste resplandecente entre porém e pobre em imunda veste');
INSERT INTO verses VALUES (30349, 59, 2, 3, 'olheis-sobre porém sobre o carregando o veste o resplandecente e digais tu senta-te aqui bem e o a-pobre digais tu fica-de-pé ali ou senta-te sob o estrado meu');
INSERT INTO verses VALUES (30350, 59, 2, 4, 'não duvidastes em si-mesmos e tornastes-vos juízes raciocínios maus');
INSERT INTO verses VALUES (30351, 59, 2, 5, 'ouvi irmãos meu amados não o Theos escolheu o pobres o ao-mundo ricos em fé e herdeiros o do-reino o qual prometeu o amam ele');
INSERT INTO verses VALUES (30352, 59, 2, 6, 'vós porém desonrastes o pobre não o ricos oprimem vosso e eles-mesmos arrastam vos para tribunais');
INSERT INTO verses VALUES (30353, 59, 2, 7, 'não eles-mesmos blasfemam o belo nome o tendo-sido-chamado sobre vos');
INSERT INTO verses VALUES (30354, 59, 2, 8, 'se contudo lei completais real segundo o escritura Amarás o próximo teu como a-ti-mesmo bem fazei');
INSERT INTO verses VALUES (30355, 59, 2, 9, 'se porém aceitais-faces pecado trabalhai sendo-repreendidos sob o da-lei como transgressores');
INSERT INTO verses VALUES (30356, 59, 2, 10, 'qualquer-que pois todo o lei guarde tropece porém em Um aconteceu todos culpado');
INSERT INTO verses VALUES (30357, 59, 2, 11, 'o pois dizendo não adulteres disse e não assassines se porém não cometes-adultério matas e/mas tens-te-tornado transgressor da-lei');
INSERT INTO verses VALUES (30358, 59, 2, 12, 'assim falais e assim fazei como através-de da-lei liberdade estando-para ser-julgado');
INSERT INTO verses VALUES (30359, 59, 2, 13, 'o pois julgamento sem-misericórdia o não que-fez misericórdia gloria-se-contra misericórdia julgamento');
INSERT INTO verses VALUES (30360, 59, 2, 14, 'quê o proveito irmãos meu se fé diga alguém ter obra porém não tenha não pode o fé salvar ele');
INSERT INTO verses VALUES (30361, 59, 2, 15, 'se irmão ou irmã nus existam e faltando o Diária alimento');
INSERT INTO verses VALUES (30362, 59, 2, 16, 'diga e/mas alguém a-eles de vosso ide em paz aquecei-vos e sede-saciados não deis porém a-eles o Necessárias o do-corpo quê o proveito');
INSERT INTO verses VALUES (30363, 59, 2, 17, 'assim e o fé se não tenha obra morta é segundo a-si-mesma');
INSERT INTO verses VALUES (30364, 59, 2, 18, 'mas dirá alguém tu fé tens e-eu obra tenho mostra a-mim o fé teu sem o obra eu-também a-ti mostrarei de o obra meu o fé');
INSERT INTO verses VALUES (30365, 59, 2, 19, 'tu crês que um é o Theos bem fazes e o demônios creem e estremecem');
INSERT INTO verses VALUES (30366, 59, 2, 20, 'queres porém conhecer Ômega homem vão que o fé sem o obra ociosa é');
INSERT INTO verses VALUES (30367, 59, 2, 21, 'Abraão o Pai nosso não de obra foi-justificado tendo-oferecido Isaque o Filho dele sobre o altar');
INSERT INTO verses VALUES (30368, 59, 2, 22, 'vês que o fé cooperava o obra dele e de o obra o fé Foi-aperfeiçoado');
INSERT INTO verses VALUES (30369, 59, 2, 23, 'e foi-cumprido o escritura o dizendo Acreditou porém Abraão o a-Theos e foi-contado a ele para justiça e amigo de-Theos foi-chamado');
INSERT INTO verses VALUES (30370, 59, 2, 24, 'vede que de obra é-justificado homem e não de da-fé somente');
INSERT INTO verses VALUES (30371, 59, 2, 25, 'semelhantemente porém e Raabe o prostituta não de obra foi-justificado Tendo-recebido o anjo e outra caminho tendo-lançado-fora');
INSERT INTO verses VALUES (30372, 59, 2, 26, 'assim-como pois o corpo sem do-espírito morto é assim e o fé sem obra morta é');
INSERT INTO chapters VALUES (1149, 59, 3, 18);
INSERT INTO verses VALUES (30373, 59, 3, 1, 'não muitos mestres tornai-vos irmãos meu sei que maior julgamento receberemos');
INSERT INTO verses VALUES (30374, 59, 3, 2, 'muitas-coisas pois tropeçamos todos se alguém em em-palavra não tropeça este perfeito homem poderoso refrear e todo o corpo');
INSERT INTO verses VALUES (30375, 59, 3, 3, 'se porém o cavalo o freios para o bocas lançamos para o obedecer eles a-nós e todo o corpo deles dirigimos');
INSERT INTO verses VALUES (30376, 59, 3, 4, 'eis e o navios tão-grandes sendo e sob ventos duros sendo-impelidos é-dirigido sob mínimo leme onde o ímpeto o endireitando quer');
INSERT INTO verses VALUES (30377, 59, 3, 5, 'assim e o língua pouco membro é e grandes vangloria-se eis quão-grande fogo Quão-grande Matéria acende');
INSERT INTO verses VALUES (30378, 59, 3, 6, 'e o língua fogo o mundo o da-injustiça o língua é-constituído em o membros nosso o manchando todo o corpo e inflamando o roda o origem e sendo-inflamada sob o geena');
INSERT INTO verses VALUES (30379, 59, 3, 7, 'toda pois natureza feras e e aves répteis e e marinhos é-domada e tem-sido-domada o natureza o humana');
INSERT INTO verses VALUES (30380, 59, 3, 8, 'o porém língua ninguém domar pode dos-homens instável mal cheia veneno mortífero');
INSERT INTO verses VALUES (30381, 59, 3, 9, 'em a-ela bendizemos o Kyrion e Pai e em a-ela amaldiçoamos o homens o segundo semelhança de-Theos tendo-se-tornado');
INSERT INTO verses VALUES (30382, 59, 3, 10, 'de o dele boca sai bênção e maldição não é-necessário irmãos meu estas-coisas assim tornar-se');
INSERT INTO verses VALUES (30383, 59, 3, 11, 'acaso o fonte de o dela caverna brota o doce e o amargo');
INSERT INTO verses VALUES (30384, 59, 3, 12, 'não pode irmãos meu figueira oliveira fazer ou videira figos nem salgado doce fazer água');
INSERT INTO verses VALUES (30385, 59, 3, 13, 'quem sábio e entendido em a-vós mostre de o boa conduta o obra dele em mansidão da-sabedoria');
INSERT INTO verses VALUES (30386, 59, 3, 14, 'se porém zelo amargo tendes e contenda em o no-coração vosso não gloriais-vos-contra e mentis segundo o da-verdade');
INSERT INTO verses VALUES (30387, 59, 3, 15, 'não é esta o sabedoria de-cima descendo mas terreno natural demoníaca');
INSERT INTO verses VALUES (30388, 59, 3, 16, 'onde pois zelo e Contenda ali desordem e todo vil assunto');
INSERT INTO verses VALUES (30389, 59, 3, 17, 'o porém de-cima sabedoria primeiro por-um-lado pura é depois pacífica moderado obediente cheia misericórdia e frutos boas-coisas imparcial sem-hipocrisia');
INSERT INTO verses VALUES (30390, 59, 3, 18, 'fruto porém justiça em paz é-semeado o fazem paz');
INSERT INTO chapters VALUES (1150, 59, 4, 17);
INSERT INTO verses VALUES (30391, 59, 4, 1, 'de-onde guerras e de-onde contendas em a-vós não daqui de o prazeres vosso o guerreando em o membros vosso');
INSERT INTO verses VALUES (30392, 59, 4, 2, 'desejais e não tendes matais e zelai e não podeis Alcançar combateis e guerreais não tendes através-de o não pedir vos');
INSERT INTO verses VALUES (30393, 59, 4, 3, 'pedi e não recebeis porque mal pedis para que em o prazeres vosso gasteis');
INSERT INTO verses VALUES (30394, 59, 4, 4, 'adúlteras não sei que o amizade o do-mundo inimizade o de-Theos é o qual se portanto queira amigo ser o do-mundo inimigo o de-Theos é-constituído');
INSERT INTO verses VALUES (30395, 59, 4, 5, 'ou pensais que em-vão o escritura diz junto-a inveja deseja-ardentemente o espírito o qual fez-habitar em a-nós');
INSERT INTO verses VALUES (30396, 59, 4, 6, 'maior porém dá graça por-isso diz o Theos soberbos opõe-se humildes porém dá graça');
INSERT INTO verses VALUES (30397, 59, 4, 7, 'sujeitai-vos portanto o a-Theos resisti porém o diabo e fugirá de vosso');
INSERT INTO verses VALUES (30398, 59, 4, 8, 'aproximai-vos o a-Theos e aproximar-se-á a-vós purificai mãos pecadores e purificai do-coração de-dupla-mente lamentai e lamentai e chorai');
INSERT INTO verses VALUES (30399, 59, 4, 9, 'o riso vosso para luto seja-convertido e o alegria para abatimento');
INSERT INTO verses VALUES (30400, 59, 4, 10, 'sede-humilhados diante-de do-Kyrios e exaltará vos');
INSERT INTO verses VALUES (30401, 59, 4, 11, 'não falais-contra uns-aos-outros irmãos o falando-contra do-irmão ou julgando o irmão dele fala-contra da-lei e julga lei se porém lei julgas não és praticante da-lei mas juiz');
INSERT INTO verses VALUES (30402, 59, 4, 12, 'um é legislador e juiz o podendo salvar e destruir tu porém quem és o julgando o próximo');
INSERT INTO verses VALUES (30403, 59, 4, 13, 'Vamos agora o dizendo Hoje ou amanhã iremos para estas coisas o cidade e faremos ali ano e comerciaremos e ganharemos');
INSERT INTO verses VALUES (30404, 59, 4, 14, 'os-quais não sabeis o amanhã qual o vida vosso vapor pois sois o junto-a pouco aparecendo depois e desvanecendo-se');
INSERT INTO verses VALUES (30405, 59, 4, 15, 'em-troca-de o dizer vos se o Kyrios queira e viveremos e faremos isto ou aquilo');
INSERT INTO verses VALUES (30406, 59, 4, 16, 'agora porém gloriais-vos em o arrogâncias vosso toda glória tal má é');
INSERT INTO verses VALUES (30407, 59, 4, 17, 'sei portanto belo fazer e não fazendo pecado a ele é');
INSERT INTO chapters VALUES (1151, 59, 5, 20);
INSERT INTO verses VALUES (30408, 59, 5, 1, 'Vamos agora o ricos chorai lamentando-em-alta-voz sobre o em-misérias vosso o sobrevindo');
INSERT INTO verses VALUES (30409, 59, 5, 2, 'o riqueza vosso tem-apodrecido e o vestes vosso comidos-por-traças aconteceu');
INSERT INTO verses VALUES (30410, 59, 5, 3, 'o ouro vosso e o prata tem-enferrujado e o veneno deles para testemunho a-vós será e comerá o carnes vosso como fogo entesourastes em últimas dias');
INSERT INTO verses VALUES (30411, 59, 5, 4, 'eis o salário o trabalhadores o dos-que-não-ceifaram o região vosso o tendo-ficado-privado de vosso clama e o clamores o tendo-ceifado para o ouvidos do-Kyrios Sabaoth têm-entrado');
INSERT INTO verses VALUES (30412, 59, 5, 5, 'Vivestes-em-delícias sobre o da-terra e Vivestes-em-deleites nutriste o do-coração vosso em dia matança');
INSERT INTO verses VALUES (30413, 59, 5, 6, 'condenastes assassinastes o justo não opõe-se a-vós');
INSERT INTO verses VALUES (30414, 59, 5, 7, 'Sede-pacientes portanto irmãos até o presença o do-Kyrios eis o lavrador espera o precioso fruto o da-terra sendo-paciente sobre a ele até tome temporã e tardio');
INSERT INTO verses VALUES (30415, 59, 5, 8, 'sede-pacientes e vós firmai o do-coração vosso que o presença o do-Kyrios aproximou-se');
INSERT INTO verses VALUES (30416, 59, 5, 9, 'não gemeis irmãos segundo uns-aos-outros para que não sejais-julgados eis o juiz antes-de o portas está-de-pé');
INSERT INTO verses VALUES (30417, 59, 5, 10, 'exemplo tomai irmãos o sofrimento e o paciência o profetas o qual falaram em o em-nome do-Kyrios');
INSERT INTO verses VALUES (30418, 59, 5, 11, 'eis consideramos-bem-aventurados o Tendo-perseverado o perseverança Jó ouvistes e o fim do-Kyrios vistes que muito-compassivo é o Kyrios e misericordioso');
INSERT INTO verses VALUES (30419, 59, 5, 12, 'Antes-de todos e/mas irmãos meu não jurais nem o céu nem o terra nem outro algum juramento seja porém vosso o Sim sim e o Não não para que não sob juízo caiais');
INSERT INTO verses VALUES (30420, 59, 5, 13, 'Sofre-males alguém em a-vós ore está-alegre alguém salmodie');
INSERT INTO verses VALUES (30421, 59, 5, 14, 'está-fraco alguém em a-vós chame-a-si o anciãos o da-assembleia e orem sobre ele tendo-ungido azeite em o em-nome o do-Kyrios');
INSERT INTO verses VALUES (30422, 59, 5, 15, 'e o voto o da-fé salvará o estando-enfermo e levantará ele o Kyrios e-se do-pecado seja tendo-feito será-perdoado a ele');
INSERT INTO verses VALUES (30423, 59, 5, 16, 'confessai portanto uns-aos-outros o do-pecado e orai em-favor-de uns-aos-outros para-que Sejais-curados muito tem-poder súplica justo sendo-operada');
INSERT INTO verses VALUES (30424, 59, 5, 17, 'Elias homem era de-natureza-semelhante a-nós e oração orou o não chover e não choveu sobre o da-terra anos três e meses seis');
INSERT INTO verses VALUES (30425, 59, 5, 18, 'e novamente orou e o céu chuva deu e o terra brotou o fruto dela');
INSERT INTO verses VALUES (30426, 59, 5, 19, 'Irmãos meu se alguém em a-vós seja-desviado de o da-verdade e converta alguém ele');
INSERT INTO verses VALUES (30427, 59, 5, 20, 'sabeis que o tendo-virado pecador de engano do-caminho dele salvará alma dele de da-morte e cobrirá multidão pecados');
INSERT INTO books VALUES (60, '1PE', '1 Pedro', 'NT', 5);
INSERT INTO chapters VALUES (1152, 60, 1, 25);
INSERT INTO verses VALUES (30428, 60, 1, 1, 'Pedro apóstolo Iesous de-Christos escolhidos a-peregrinos dispersão Ponto Galácia Capadócia Ásia e Bitínia');
INSERT INTO verses VALUES (30429, 60, 1, 2, 'segundo presciência de-Theos Pai em santificação do-espírito para obediência e aspersão sangue Iesous de-Christos graça a-vós e paz seja-multiplicada');
INSERT INTO verses VALUES (30430, 60, 1, 3, 'Bendito o Theos e Pai o do-Kyrios nosso Iesous de-Christos o segundo o muito dele misericórdia tendo-regenerado nos para esperança vivente através-de da-ressurreição Iesous de-Christos de mortos');
INSERT INTO verses VALUES (30431, 60, 1, 4, 'para herança incorruptível e imaculado e imarcescível tendo-sido-guardada em nos-céus para vos');
INSERT INTO verses VALUES (30432, 60, 1, 5, 'o em poder de-Theos sendo-guardados através-de da-fé para salvação preparada ser-revelado em tempo último');
INSERT INTO verses VALUES (30433, 60, 1, 6, 'em o qual exultai pouco agora se é necessário tendo-sido-entristecidos em variados tentações');
INSERT INTO verses VALUES (30434, 60, 1, 7, 'para que o prova vosso o da-fé muito-mais-precioso ouro o do-que-está-perecendo através-de fogo porém sendo-examinado seja-encontrada para louvor e glória e honra em revelação Iesous de-Christos');
INSERT INTO verses VALUES (30435, 60, 1, 8, 'o qual não vendo amai para o qual agora não vendo crendo porém exultai alegria indizível e tendo-sido-glorificada');
INSERT INTO verses VALUES (30436, 60, 1, 9, 'recebendo o fim o da-fé salvação almas');
INSERT INTO verses VALUES (30437, 60, 1, 10, 'acerca-de o qual salvação buscaram-diligentemente e esquadrinharam profetas o acerca-de o para vos da-graça tendo-profetizado');
INSERT INTO verses VALUES (30438, 60, 1, 11, 'Examinando para quem ou qual tempo indicava o em a-eles espírito de-Christos testificando-de-antemão o para Christos sofrimentos e o com estas-coisas glórias');
INSERT INTO verses VALUES (30439, 60, 1, 12, 'o qual foi-revelado que não si-mesmos a-vós porém serviam elas o qual agora foi-anunciado a-vós através-de o tendo-anunciado-boas-novas vos em Espírito no-santo ao-que-foi-enviado de do-céu para o qual desejam anjo inclinar-se');
INSERT INTO verses VALUES (30440, 60, 1, 13, 'por-isso tendo-cingido o lombos o entendimento vosso sendo-sóbrios perfeitamente esperai sobre o sendo-levada a-vós graça em revelação Iesous de-Christos');
INSERT INTO verses VALUES (30441, 60, 1, 14, 'como filhos obediência não conformando-se o antes em o ignorância vosso desejos');
INSERT INTO verses VALUES (30442, 60, 1, 15, 'mas segundo o tendo-chamado vos santo e eles-mesmos santos em toda conduta tornai-vos');
INSERT INTO verses VALUES (30443, 60, 1, 16, 'porque está-escrito santos sereis que eu santo');
INSERT INTO verses VALUES (30444, 60, 1, 17, 'e se Pai invocais o sem-parcialidade julgando segundo o cada-um obra em medo o o de-peregrinação vosso tempo conduzi-vos');
INSERT INTO verses VALUES (30445, 60, 1, 18, 'sei que não corruptíveis prata ou ouro fostes-resgatados de o vãs vosso conduta transmitida-pelos-pais');
INSERT INTO verses VALUES (30446, 60, 1, 19, 'mas precioso sangue como cordeiro irrepreensível e imaculada de-Christos');
INSERT INTO verses VALUES (30447, 60, 1, 20, 'tendo-sido-conhecido-de-antemão por-um-lado antes-de fundação do-mundo tendo-sido-manifestado porém sobre último o tempos através-de vos');
INSERT INTO verses VALUES (30448, 60, 1, 21, 'o através-de dele fiéis para Theos o tendo-levantado ele de mortos e glória a ele tendo-dado de-modo-que o fé vosso e esperança ser para Theos');
INSERT INTO verses VALUES (30449, 60, 1, 22, 'o almas vosso Tendo-purificado em o obediência o da-verdade para amor-fraternal sem-hipocrisia de do-coração uns-aos-outros amai fervorosamente');
INSERT INTO verses VALUES (30450, 60, 1, 23, 'tendo-sido-regenerados não de semente corruptível mas incorruptível através-de da-palavra vivente de-Theos e permanecendo');
INSERT INTO verses VALUES (30451, 60, 1, 24, 'porque toda carne como erva e toda glória dela como flor erva secou o erva e o flor caiu');
INSERT INTO verses VALUES (30452, 60, 1, 25, 'o porém palavra do-Kyrios permanece para o eternidade isto e/mas é o palavra o tendo-sido-anunciado-como-boa-nova para vos');
INSERT INTO chapters VALUES (1153, 60, 2, 25);
INSERT INTO verses VALUES (30453, 60, 2, 1, 'Tendo-despido portanto toda malícia e todas-as-coisas engano e Hipocrisias e invejas e todas maledicências');
INSERT INTO verses VALUES (30454, 60, 2, 2, 'como recém-nascidos crianças-de-peito o racional sem-engano leite desejai-ardentemente para que em a ele sejais-feitos-crescer para salvação');
INSERT INTO verses VALUES (30455, 60, 2, 3, 'se provastes que benigno o Kyrios');
INSERT INTO verses VALUES (30456, 60, 2, 4, 'junto-a o qual aproximando-se pedra vivendo sob dos-homens por-um-lado tendo-sido-rejeitado de-junto-de porém a-Theos escolhido honrado');
INSERT INTO verses VALUES (30457, 60, 2, 5, 'e eles-mesmos como pedras vivos sois-edificados casa espiritual para sacerdócio santo oferecer espirituais sacrifício aceitáveis a-Theos através-de Iesous de-Christos');
INSERT INTO verses VALUES (30458, 60, 2, 6, 'porque contém em escritura Eis ponho em Sião pedra escolhido pedra-angular honrado e o crendo sobre a ele não não seja-envergonhado');
INSERT INTO verses VALUES (30459, 60, 2, 7, 'a-vós portanto o honra o creem não-creem porém pedra o qual rejeitaram o edificantes este aconteceu para cabeça cantos');
INSERT INTO verses VALUES (30460, 60, 2, 8, 'e pedra tropeço e rocha tropeço o qual tropeçam o em-palavra desobedecendo para o qual e foram-colocados');
INSERT INTO verses VALUES (30461, 60, 2, 9, 'vós porém raça escolhido real sacerdócio nação santo povo para aquisição para-que o virtudes anuncieis o de das-trevas vos chamante para o maravilhoso dele luz');
INSERT INTO verses VALUES (30462, 60, 2, 10, 'o qual alguma-vez não povo agora porém povo de-Theos o não tendo-sido-alvos-de-misericórdia agora porém tendo-recebido-misericórdia');
INSERT INTO verses VALUES (30463, 60, 2, 11, 'Amados rogo como peregrinos e peregrinos abster-se o carnais desejos as-quais guerreiam segundo o alma');
INSERT INTO verses VALUES (30464, 60, 2, 12, 'o conduta vosso em o nações tendo boa para que em o qual falam-contra vosso como malfeitores de o boas obra Observando glorifiquem o Theos em dia supervisão');
INSERT INTO verses VALUES (30465, 60, 2, 13, 'Sujeitai-vos toda humana criação através-de o Kyrion seja rei como Ao-que-excede');
INSERT INTO verses VALUES (30466, 60, 2, 14, 'seja governadores como através-de dele sendo-enviados para vingança malfeitores louvor porém fazendo-o-bem');
INSERT INTO verses VALUES (30467, 60, 2, 15, 'que assim é o vontade o de-Theos fazendo-o-bem amordaçar o o insensatos dos-homens ignorância');
INSERT INTO verses VALUES (30468, 60, 2, 16, 'como livres e não como cobertura tendo o maldade o liberdade mas como de-Theos servos');
INSERT INTO verses VALUES (30469, 60, 2, 17, 'todos honrai o irmandade amai o Theos temei o rei honrais');
INSERT INTO verses VALUES (30470, 60, 2, 18, 'o servos-domésticos sujeitando-se em todo medo o senhores não somente o bons e moderados mas e o tortuosos');
INSERT INTO verses VALUES (30471, 60, 2, 19, 'isto pois graça se através-de consciência de-Theos Suporta alguém tristezas sofrendo injustamente');
INSERT INTO verses VALUES (30472, 60, 2, 20, 'qual pois glória se pecando e sendo-esbofeteados perseverareis mas se fazendo-o-bem e sofrendo perseverareis isto graça de-junto-de a-Theos');
INSERT INTO verses VALUES (30473, 60, 2, 21, 'para isto pois fostes-chamados que e Christos sofreu em-favor-de vosso a-vós Deixando Exemplo para que tenhais-seguido o pegadas dele');
INSERT INTO verses VALUES (30474, 60, 2, 22, 'o qual pecado não fez nem foi-encontrado engano em o boca dele');
INSERT INTO verses VALUES (30475, 60, 2, 23, 'o qual sendo-injuriado não não-injuriava-em-troca sofrendo não ameaçava entregava porém o julgando justamente');
INSERT INTO verses VALUES (30476, 60, 2, 24, 'o qual o do-pecado nosso ele ofereceu em o corpo dele sobre o madeira/árvore para que o pecados tendo-morrido o justiça vivamos o qual o ferida Fostes-curados');
INSERT INTO verses VALUES (30477, 60, 2, 25, 'éreis pois como ovelhas errantes mas vos-convertestes agora sobre o pastor e Supervisor o almas vosso');
INSERT INTO chapters VALUES (1154, 60, 3, 22);
INSERT INTO verses VALUES (30478, 60, 3, 1, 'semelhantemente mulheres sujeitando-se o próprios homens para que e se alguns desobedecem o em-palavra através-de o o mulheres conduta sem da-palavra serão-ganhos');
INSERT INTO verses VALUES (30479, 60, 3, 2, 'Tendo-observado o em medo pura conduta vosso');
INSERT INTO verses VALUES (30480, 60, 3, 3, 'o qual seja não o de-fora entrelaçamento cabelos e adorno de-objetos-de-ouro ou vestimenta vestes mundo');
INSERT INTO verses VALUES (30481, 60, 3, 4, 'mas o oculto o do-coração homem em o incorruptível o mansamente e tranquilo do-espírito o qual é diante-de o de-Theos muito-custoso');
INSERT INTO verses VALUES (30482, 60, 3, 5, 'assim pois alguma-vez e o santas mulheres o esperando para Theos adornavam si-mesmas sujeitando-se o próprios homens');
INSERT INTO verses VALUES (30483, 60, 3, 6, 'como Sara obedeceu o Abraão Kyrion ele chamando o qual tornastes-vos filhos fazendo-o-bem e não as-que-temem nenhuma terror');
INSERT INTO verses VALUES (30484, 60, 3, 7, 'o homens semelhantemente habitando-com segundo saibam como mais-fraco vaso o feminino atribuindo honra como e co-herdeiros da-graça da-vida para o não ser-impedido o orações vosso');
INSERT INTO verses VALUES (30485, 60, 3, 8, 'o porém fim todos de-mesmo-pensamento compassivos amantes-dos-irmãos compassivos humildes-de-mente');
INSERT INTO verses VALUES (30486, 60, 3, 9, 'não retribuindo mau em-troca-de mal ou injúria em-troca-de injúria pelo-contrário porém bendizendo que para isto fostes-chamados para que bênção herdeis');
INSERT INTO verses VALUES (30487, 60, 3, 10, 'o pois querendo vida amar e ver do-dia boas cesse o língua de mal e lábios o não falar engano');
INSERT INTO verses VALUES (30488, 60, 3, 11, 'desvie-se porém de mal e faça bom busque paz e persiga ela');
INSERT INTO verses VALUES (30489, 60, 3, 12, 'que olhos do-Kyrios sobre justos e ouvidos dele para súplica deles face porém do-Kyrios sobre fazendo males');
INSERT INTO verses VALUES (30490, 60, 3, 13, 'e quem o tendo-maltratado vos se o bom zelosos torneis-vos');
INSERT INTO verses VALUES (30491, 60, 3, 14, 'mas se e sofrêsseis através-de justiça bem-aventurados o porém medo deles não temais nem sejais-perturbados');
INSERT INTO verses VALUES (30492, 60, 3, 15, 'Kyrion porém o Christos santificai em o corações vosso prontos sempre junto-a defesa todo o pedindo vos palavra acerca-de o em a-vós da-esperança');
INSERT INTO verses VALUES (30493, 60, 3, 16, 'mas com mansidão e medo consciência tendo boa para que em o qual sois-falados-contra sejam-envergonhados o maltratando vosso o boa em em-Christos conduta');
INSERT INTO verses VALUES (30494, 60, 3, 17, 'melhor pois fazendo-o-bem se quisesse o vontade o de-Theos sofrer ou fazendo-o-mal');
INSERT INTO verses VALUES (30495, 60, 3, 18, 'que e Christos uma-vez acerca-de pecados morreu justo em-favor-de injustos para que vos conduza o a-Theos tendo-sido-morto por-um-lado carne tendo-sido-vivificado porém espírito');
INSERT INTO verses VALUES (30496, 60, 3, 19, 'em o qual e o em na-prisão espíritos tendo-ido proclamou');
INSERT INTO verses VALUES (30497, 60, 3, 20, 'aos-que-desobedeceram alguma-vez quando aguardava-ansiosamente o o de-Theos longanimidade em dias Noé sendo-preparada arca para o qual poucos isto é oito almas foram-salvos através-de água');
INSERT INTO verses VALUES (30498, 60, 3, 21, 'o qual e vos antítipo agora salva batismo não carne remoção imundícia mas consciência boa pergunta para Theos através-de da-ressurreição Iesous de-Christos');
INSERT INTO verses VALUES (30499, 60, 3, 22, 'o qual é em direita de-Theos tendo-ido para céu Tendo-sido-sujeitados a ele anjo e autoridades e poderes');
INSERT INTO chapters VALUES (1155, 60, 4, 19);
INSERT INTO verses VALUES (30500, 60, 4, 1, 'de-Christos portanto tendo-sofrido carne e vós o ela Intenção armai-vos que o tendo-sofrido carne tem-cessado do-pecado');
INSERT INTO verses VALUES (30501, 60, 4, 2, 'para o não-mais dos-homens desejos mas vontade de-Theos o restante em carne viver tempo');
INSERT INTO verses VALUES (30502, 60, 4, 3, 'suficiente pois o tendo-passado tempo o vontade o nações ter-realizado tendo-ido em dissoluções desejos embriaguezes orgias em-bebedeiras e ilícitos idolatrias');
INSERT INTO verses VALUES (30503, 60, 4, 4, 'em o qual estranham não correndo-junto vosso para o ela o dissolução excesso blasfemando');
INSERT INTO verses VALUES (30504, 60, 4, 5, 'o qual retribuirão palavra o prontamente tendo julgar viventes e mortos');
INSERT INTO verses VALUES (30505, 60, 4, 6, 'para isto pois e mortos foram-anunciadas-boas-novas para que sejam-julgados por-um-lado segundo homens na-carne vivem porém segundo Theos espírito');
INSERT INTO verses VALUES (30506, 60, 4, 7, 'todos porém o fim aproximou-se sede-sóbrios portanto e sede-sóbrios para orações');
INSERT INTO verses VALUES (30507, 60, 4, 8, 'antes-de todos o para si-mesmos amor fervorosa tendo que amor cobre multidão pecados');
INSERT INTO verses VALUES (30508, 60, 4, 9, 'hospitaleiros para uns-aos-outros sem murmuração');
INSERT INTO verses VALUES (30509, 60, 4, 10, 'cada-um assim-como recebeu dom para si-mesmos ele servindo como bons administradores variada da-graça de-Theos');
INSERT INTO verses VALUES (30510, 60, 4, 11, 'se alguém fala como oráculos de-Theos se alguém serve como de força o qual supre o Theos para que em todos seja-glorificado o Theos através-de Iesous de-Christos o qual é o glória e o domínio para o eras o eras amém');
INSERT INTO verses VALUES (30511, 60, 4, 12, 'Amados não estranhais o em a-vós em-queima junto-a tentação a-vós acontecendo como estrangeiro a-vós acontecendo');
INSERT INTO verses VALUES (30512, 60, 4, 13, 'mas conforme participais o o de-Christos sofrimentos alegrai-vos para que e em o revelação o da-glória dele alegreis-vos exultando');
INSERT INTO verses VALUES (30513, 60, 4, 14, 'se sois-injuriados em em-nome de-Christos bem-aventurados que o o da-glória e o o de-Theos espírito sobre vos descansa');
INSERT INTO verses VALUES (30514, 60, 4, 15, 'não pois alguém vosso sofra como homicida ou ladrão ou malfeitor ou como intrometido-em-assuntos-alheios');
INSERT INTO verses VALUES (30515, 60, 4, 16, 'se porém como Cristão não envergonhe-se glorifique porém o Theos em o em-nome neste');
INSERT INTO verses VALUES (30516, 60, 4, 17, 'que o tempo o começar o julgamento de o da-casa o de-Theos se porém primeiro de nosso quê o fim o desobedecendo o o de-Theos no-evangelho');
INSERT INTO verses VALUES (30517, 60, 4, 18, 'e se o justo dificilmente é-salvo o ímpio e pecador onde aparecerá');
INSERT INTO verses VALUES (30518, 60, 4, 19, 'de-modo-que e o sofrendo segundo o vontade o de-Theos fiel Criador confiem o almas deles em prática-do-bem');
INSERT INTO chapters VALUES (1156, 60, 5, 14);
INSERT INTO verses VALUES (30519, 60, 5, 1, 'anciãos portanto em a-vós rogo o co-presbítero e testemunha o o de-Christos sofrimentos o e o está-para ser-revelado da-glória participante');
INSERT INTO verses VALUES (30520, 60, 5, 2, 'apascentai o em a-vós pequeno-rebanho o de-Theos não por-compulsão mas Voluntariamente segundo Theos nem por-ganância-de-lucro-torpe mas prontamente');
INSERT INTO verses VALUES (30521, 60, 5, 3, 'nem como dominando o sortes mas modelos tornando-se o rebanho');
INSERT INTO verses VALUES (30522, 60, 5, 4, 'e tendo-sido-manifestado o Sumo-pastor recebereis o imarcescível o da-glória coroa');
INSERT INTO verses VALUES (30523, 60, 5, 5, 'semelhantemente mais-jovens sujeitai-vos presbíteros todos porém uns-aos-outros o humildade-de-mente revesti-vos-de-humildade que o Theos soberbos opõe-se humildes porém dá graça');
INSERT INTO verses VALUES (30524, 60, 5, 6, 'Sede-humilhados portanto sob o forte mão o de-Theos para que vos Exalte em tempo');
INSERT INTO verses VALUES (30525, 60, 5, 7, 'toda o ansiedade vosso tendo-lançado-sobre sobre ele que a ele importa acerca-de vosso');
INSERT INTO verses VALUES (30526, 60, 5, 8, 'Sede-sóbrios vigiai o adversário vosso diabo como leão Rugindo anda buscando alguém tragar');
INSERT INTO verses VALUES (30527, 60, 5, 9, 'o qual resisti sólidos o fé sei o elas o sofrimentos o em o ao-mundo vosso irmandade Ser-completado');
INSERT INTO verses VALUES (30528, 60, 5, 10, 'o porém Theos toda da-graça o chamando vos para o eterno dele glória em em-Christos pouco tendo-sofrido ele restaurará firmará fortalecerá firmará');
INSERT INTO verses VALUES (30529, 60, 5, 11, 'a ele o domínio para o eras o eras amém');
INSERT INTO verses VALUES (30530, 60, 5, 12, 'através-de Silvano a-vós o fiel do-irmão como considero através-de poucos escrevi exortando e testificando esta ser verdadeiras graça o de-Theos para o qual ficai-de-pé');
INSERT INTO verses VALUES (30531, 60, 5, 13, 'Saúda vos o em Babilônia co-eleita e Marcos o filho meu');
INSERT INTO verses VALUES (30532, 60, 5, 14, 'saudai uns-aos-outros em beijo do-amor paz a-vós todos o em em-Christos');
INSERT INTO books VALUES (61, '2PE', '2 Pedro', 'NT', 3);
INSERT INTO chapters VALUES (1157, 61, 1, 21);
INSERT INTO verses VALUES (30533, 61, 1, 1, 'Simeão Pedro servo e apóstolo Iesous de-Christos o De-igual-valor a-nós tendo-obtido-por-sorte fé em justiça o de-Theos nosso e do-Salvador Iesous de-Christos');
INSERT INTO verses VALUES (30534, 61, 1, 2, 'graça a-vós e paz seja-multiplicada em conhecimento-pleno o de-Theos e Iesous o do-Kyrios nosso');
INSERT INTO verses VALUES (30535, 61, 1, 3, 'como o todas-as-coisas a-nós o divina do-poder dele o junto-a vida e piedade tendo-sido-concedida através-de o pleno-conhecimento o chamante nos em-particular glória e virtude');
INSERT INTO verses VALUES (30536, 61, 1, 4, 'através-de o qual o preciosas e grandíssimas a-nós promessas tem-sido-concedido para que através-de destes torneis-vos divina participantes natureza tendo-escapado o em o ao-mundo em desejo corrupção');
INSERT INTO verses VALUES (30537, 61, 1, 5, 'e ele isto porém diligência toda tendo-trazido-além-disso Supliai em o fé vosso o virtude em porém o virtude o saibam');
INSERT INTO verses VALUES (30538, 61, 1, 6, 'em porém o conhecimento o domínio-próprio em porém o domínio-próprio o perseverança em porém o perseverança o piedade');
INSERT INTO verses VALUES (30539, 61, 1, 7, 'em porém o piedade o amor-fraternal em porém o amor-fraternal o amor');
INSERT INTO verses VALUES (30540, 61, 1, 8, 'estas-coisas pois a-vós posses e abundando não ociosos nem infrutíferos constitui para o o do-Kyrios nosso Iesous de-Christos conhecimento-pleno');
INSERT INTO verses VALUES (30541, 61, 1, 9, 'o qual pois não está-presente estas-coisas cego é sendo-míope esquecimento tomando o purificação o outrora dele pecados');
INSERT INTO verses VALUES (30542, 61, 1, 10, 'por-isso mais irmãos apressai-vos firme vosso o chamado e eleição fazer estas-coisas pois fazendo não não tropeçais alguma-vez');
INSERT INTO verses VALUES (30543, 61, 1, 11, 'assim pois ricamente Será-suprido a-vós o entrada para o eterno reino o do-Kyrios nosso e do-Salvador Iesous de-Christos');
INSERT INTO verses VALUES (30544, 61, 1, 12, 'por-isso estarei-a-ponto-de sempre vos Lembrar acerca-de destes embora sei e Tendo-sido-firmados em o presente verdade');
INSERT INTO verses VALUES (30545, 61, 1, 13, 'justo porém considero sobre quanto sou em neste o habitação despertar vos em lembrará');
INSERT INTO verses VALUES (30546, 61, 1, 14, 'sei que breve é o remoção o habitação meu assim-como e o Kyrios nosso Iesous Christos revelou a-mim');
INSERT INTO verses VALUES (30547, 61, 1, 15, 'serei-diligente porém e Cada-vez ter vos com o minha partida o destes memória fazer');
INSERT INTO verses VALUES (30548, 61, 1, 16, 'não pois tendo-sido-tornados-sábios fábulas tendo-seguido fizemos-conhecer a-vós o o do-Kyrios nosso Iesous de-Christos poder e vinda mas Testemunhas-oculares tendo-se-tornado o daquele grandeza');
INSERT INTO verses VALUES (30549, 61, 1, 17, 'tomando pois de-junto-de de-Theos do-Pai honra e glória voz tendo-sido-trazida a ele de-tal-tipo sob o majestosa da-glória o filho meu o amado meu este é para o qual eu agradei-me');
INSERT INTO verses VALUES (30550, 61, 1, 18, 'e esta o voz nós ouvimos de do-céu tendo-sido-trazida com a ele sendo em o no-santo no-monte');
INSERT INTO verses VALUES (30551, 61, 1, 19, 'e temos mais-firme o profético palavra o qual bem fazei prestando-atenção como candeia aparecendo em sombrio no-lugar até o qual dia amanheça e portador-de-luz nasça em o corações vosso');
INSERT INTO verses VALUES (30552, 61, 1, 20, 'isto primeiro conhecendo que toda profecia escritura próprias interpretação não torna-se');
INSERT INTO verses VALUES (30553, 61, 1, 21, 'não pois vontade do-homem foi-trazido profecia alguma-vez mas sob do-espírito do-santo sendo-levados falaram de de-Theos homens');
INSERT INTO chapters VALUES (1158, 61, 2, 22);
INSERT INTO verses VALUES (30554, 61, 2, 1, 'tornaram-se porém e falsos-profetas em o povo como e em a-vós serão falsos-mestres os-quais introduzirão-secretamente heresias perdição e o tendo-comprado eles Soberano negando trazendo-sobre si-mesmos breve perdição');
INSERT INTO verses VALUES (30555, 61, 2, 2, 'e muitos seguirão deles o dissoluções através-de o qual o caminho o da-verdade será-blasfemado');
INSERT INTO verses VALUES (30556, 61, 2, 3, 'e em ganância fabricadas palavras vos negociarão o qual o julgamento desde-outrora não está-ocioso e o perdição deles não cochila');
INSERT INTO verses VALUES (30557, 61, 2, 4, 'se pois o Theos anjo tendo-pecado não poupou mas em-correntes trevas tendo-lançado-ao-Tártaro entregou para juízo sendo-guardados');
INSERT INTO verses VALUES (30558, 61, 2, 5, 'e antigo do-mundo não poupou mas oitavo Noé justiça pregador Guardou dilúvio ao-mundo ímpios tendo-trazido-sobre');
INSERT INTO verses VALUES (30559, 61, 2, 6, 'e cidades Sodoma e Gomorra tendo-reduzido-a-cinzas ruína condenou exemplo estando-para ser-ímpio tendo-posto');
INSERT INTO verses VALUES (30560, 61, 2, 7, 'e justo Ló sendo-oprimido sob o o iníquos em devassidão conduta livrou');
INSERT INTO verses VALUES (30561, 61, 2, 8, 'olhar pois e ouvido o justo habitando-em em a-eles dia de do-dia alma justa sem-lei obra atormentava');
INSERT INTO verses VALUES (30562, 61, 2, 9, 'sei Kyrios piedosos de provação livrar injustos porém para dia julgamento sendo-punidos guardar');
INSERT INTO verses VALUES (30563, 61, 2, 10, 'principalmente porém o atrás carne em desejo contaminação indo e senhorio desprezando ousados arrogantes glórias não tremendo blasfemando');
INSERT INTO verses VALUES (30564, 61, 2, 11, 'onde anjo força e poder maiores sendo não trazem segundo deles de-junto-de ao-Kyrios blasfemo juízo');
INSERT INTO verses VALUES (30565, 61, 2, 12, 'estes e/mas como irracionais ser vivente tendo-sido-gerados naturais para captura e corrupção em o qual ignoram blasfemando em o corrupção deles e serão-corrompidos');
INSERT INTO verses VALUES (30566, 61, 2, 13, 'sendo-injustiçados salário da-injustiça Prazer líderes o em dia luxúria manchas e manchas deleitando-se em o enganos deles banqueteando-junto a-vós');
INSERT INTO verses VALUES (30567, 61, 2, 14, 'olhos tendo cheios adúltera e incessantes do-pecado seduzindo almas instáveis coração tendo-sido-exercitada ganância tendo maldição filhos');
INSERT INTO verses VALUES (30568, 61, 2, 15, 'deixando reta caminho foram-enganados tendo-seguido o caminho o Balaão o Beor o qual salário da-injustiça amou');
INSERT INTO verses VALUES (30569, 61, 2, 16, 'Repreensão porém teve próprias de-iniquidade Animal-de-carga mudo em do-homem voz tendo-falado impediu o o profeta loucura');
INSERT INTO verses VALUES (30570, 61, 2, 17, 'estes são fontes sem-água e névoas sob tempestade sendo-impelidas o qual o escuridão o das-trevas tem-sido-guardado');
INSERT INTO verses VALUES (30571, 61, 2, 18, 'arrogantes pois vaidade falando seduzem em desejos carne dissoluções o por-pouco escapando o em engano conduzindo-se');
INSERT INTO verses VALUES (30572, 61, 2, 19, 'liberdade a-eles prometendo eles-mesmos servos existindo o corrupção o qual pois alguém Tem-sido-vencido neste tem-sido-escravizado');
INSERT INTO verses VALUES (30573, 61, 2, 20, 'se pois tendo-escapado o contaminações o do-mundo em conhecimento-pleno o do-Kyrios e do-Salvador Iesous de-Christos nestes porém novamente tendo-se-enredado São-vencidos aconteceu a-eles o últimas piores o primeiro');
INSERT INTO verses VALUES (30574, 61, 2, 21, 'melhor pois era a-eles não ter-reconhecido o caminho o da-justiça ou tendo-reconhecido retornar de o tendo-sido-entregue a-eles santa mandamento');
INSERT INTO verses VALUES (30575, 61, 2, 22, 'tem-acontecido a-eles o o verdadeiro provérbios Cão tendo-virado sobre o próprio vômito e Porca tendo-se-lavado para chafurdo lama');
INSERT INTO chapters VALUES (1159, 61, 3, 18);
INSERT INTO verses VALUES (30576, 61, 3, 1, 'esta já amados segunda a-vós escrever carta em o qual desperto vosso em lembrará o sincero entendimento');
INSERT INTO verses VALUES (30577, 61, 3, 2, 'lembrar-se o tendo-sido-ditos-antes palavras sob o santos profetas e o o apóstolos vosso mandamento o do-Kyrios e do-Salvador');
INSERT INTO verses VALUES (30578, 61, 3, 3, 'isto primeiro conhecendo que virão sobre últimas o dias em escárnio zombadores segundo o próprias desejos deles indo');
INSERT INTO verses VALUES (30579, 61, 3, 4, 'e dizendo onde é o promessa o presença dele de o qual pois o pais adormeceram todas-as-coisas assim permanece de princípio criação');
INSERT INTO verses VALUES (30580, 61, 3, 5, 'está-oculto pois eles isto querendo que céus eram desde-outrora e terra de água e através-de água tendo-subsistido o o de-Theos em-palavra');
INSERT INTO verses VALUES (30581, 61, 3, 6, 'através-de o qual o então mundo água tendo-sido-inundado pereceram');
INSERT INTO verses VALUES (30582, 61, 3, 7, 'o porém agora céus e o terra o a ele em-palavra tendo-sido-entesourados são fogo sendo-guardados para dia julgamento e perdição o ímpios dos-homens');
INSERT INTO verses VALUES (30583, 61, 3, 8, 'um porém isto não esteja-oculto vos amados que uma dia de-junto-de ao-Kyrios como mil anos e mil anos como dia uma');
INSERT INTO verses VALUES (30584, 61, 3, 9, 'não demora Kyrios o promessa como alguns demora consideram mas é-longânimo para vos não querendo alguns perecer mas todos para arrependimento caber');
INSERT INTO verses VALUES (30585, 61, 3, 10, 'Virá porém dia do-Kyrios como ladrão em o qual o céus com-estrondo passarão elementos porém sendo-consumidas-pelo-fogo será-solto e terra e o em a-ela obra será-encontrado');
INSERT INTO verses VALUES (30586, 61, 3, 11, 'estas assim todos sendo-desatados que-espécie-de é necessário existir vos em santas condutas e piedades');
INSERT INTO verses VALUES (30587, 61, 3, 12, 'esperando e apressando-se o vinda o o de-Theos do-dia através-de o qual céus sendo-inflamados serão-desatados e elementos sendo-consumidas-pelo-fogo é-derretido');
INSERT INTO verses VALUES (30588, 61, 3, 13, 'novos porém céus e terra nova segundo o promessa dele esperemos em o qual justiça habita');
INSERT INTO verses VALUES (30589, 61, 3, 14, 'Por-isso amados estas-coisas esperando apressai-vos imaculados e irrepreensíveis a ele ser-encontrado em paz');
INSERT INTO verses VALUES (30590, 61, 3, 15, 'e o o do-Kyrios nosso paciência salvação considerai assim-como e o amado nosso irmão Paulo segundo o tendo-sido-dada a ele sabedoria escreveu a-vós');
INSERT INTO verses VALUES (30591, 61, 3, 16, 'como e em todas cartas falando em elas acerca-de destes em o qual é difíceis-de-entender alguém o qual o ignorantes e instáveis torcem como e o restantes escrituras junto-a o própria deles perdição');
INSERT INTO verses VALUES (30592, 61, 3, 17, 'vós portanto amados conhecendo-de-antemão guardai-vos para que não o o iníquos engano tendo-sido-levados-junto caiais-fora o próprio firmeza');
INSERT INTO verses VALUES (30593, 61, 3, 18, 'crescei porém em graça e conhecimento o do-Kyrios nosso e do-Salvador Iesous de-Christos a ele o glória e agora e para dia eternidade');
INSERT INTO books VALUES (62, '1JN', '1 João', 'NT', 5);
INSERT INTO chapters VALUES (1160, 62, 1, 10);
INSERT INTO verses VALUES (30594, 62, 1, 1, 'o qual era de princípio o qual temos-ouvido o qual vimos o olhos nosso o qual contemplamos e o mãos nosso Apalparam acerca-de o da-palavra o da-vida');
INSERT INTO verses VALUES (30595, 62, 1, 2, 'e o vida foi-manifestado e vimos e testemunhamos e anunciamos a-vós o vida o eterno a-qual era junto-a o Pai e foi-manifestado a-nós');
INSERT INTO verses VALUES (30596, 62, 1, 3, 'o qual vimos e temos-ouvido anunciamos e a-vós para que e vós comunhão tenhais com nosso e o comunhão porém o Nossa com o do-Pai e com o do-Filho dele Iesous de-Christos');
INSERT INTO verses VALUES (30597, 62, 1, 4, 'e estas-coisas escrevemos nós para que o alegria nosso seja tendo-sido-preenchida');
INSERT INTO verses VALUES (30598, 62, 1, 5, 'e é esta o mensagem o qual temos-ouvido de dele e anunciamos a-vós que o Theos luz é e trevas em a ele não é nenhuma');
INSERT INTO verses VALUES (30599, 62, 1, 6, 'se digamos que comunhão temos com dele e em o trevas andemos mentimos e não fazemos o verdade');
INSERT INTO verses VALUES (30600, 62, 1, 7, 'se porém em o luz andemos como ele é em o luz comunhão temos com uns-aos-outros e o sangue Iesous o do-Filho dele purifica nos de toda do-pecado');
INSERT INTO verses VALUES (30601, 62, 1, 8, 'se digamos que pecado não temos si-mesmos enganemos e o verdade não é em a-nós');
INSERT INTO verses VALUES (30602, 62, 1, 9, 'se confessemos o do-pecado nosso fiel é e justo para que perdoe a-nós o do-pecado e purifique nos de toda da-injustiça');
INSERT INTO verses VALUES (30603, 62, 1, 10, 'se digamos que não Temos-pecado mentiroso fazemos ele e o palavra dele não é em a-nós');
INSERT INTO chapters VALUES (1161, 62, 2, 29);
INSERT INTO verses VALUES (30604, 62, 2, 1, 'Filhinhos meu estas-coisas escrever a-vós para que não pequeis e se alguém peque Consolador temos junto-a o Pai Iesous Christos justo');
INSERT INTO verses VALUES (30605, 62, 2, 2, 'e ele Propiciação é acerca-de o pecados nosso não acerca-de o Nossos porém somente mas e acerca-de inteiro o do-mundo');
INSERT INTO verses VALUES (30606, 62, 2, 3, 'e em neste conhecemos que temos-conhecido ele se o mandamentos dele guardemos');
INSERT INTO verses VALUES (30607, 62, 2, 4, 'o dizendo que Tenho-conhecido ele e o mandamentos dele não guardando mentiroso é e em neste o verdade não é');
INSERT INTO verses VALUES (30608, 62, 2, 5, 'o qual e/mas partícula-condicional guarde dele o palavra verdadeiramente em neste o amor o de-Theos tem-sido-aperfeiçoado em neste conhecemos que em a ele somos');
INSERT INTO verses VALUES (30609, 62, 2, 6, 'o dizendo em a ele permanecer deve assim-como aquele andou e ele assim andar');
INSERT INTO verses VALUES (30610, 62, 2, 7, 'Amados não mandamento nova escrever a-vós mas mandamento velha o qual tínheis de princípio o mandamento o velha é o palavra o qual ouvistes');
INSERT INTO verses VALUES (30611, 62, 2, 8, 'novamente mandamento nova escrever a-vós o qual é verdadeiro em a ele e em a-vós que o trevas passa e o luz o verdadeiro já brilha');
INSERT INTO verses VALUES (30612, 62, 2, 9, 'o dizendo em o luz ser e o irmão dele odiando em o trevas é até agora');
INSERT INTO verses VALUES (30613, 62, 2, 10, 'o amando o irmão dele em o luz permanece e tropeço em a ele não é');
INSERT INTO verses VALUES (30614, 62, 2, 11, 'o porém odiando o irmão dele em o trevas é e em o trevas anda e não sei onde vai que o trevas cegou o olhos dele');
INSERT INTO verses VALUES (30615, 62, 2, 12, 'escrever a-vós filhinhos que são-perdoados a-vós o pecados através-de o nome dele');
INSERT INTO verses VALUES (30616, 62, 2, 13, 'escrever a-vós pais que conhecestes o de princípio escrever a-vós jovens que tendes-vencido o mau');
INSERT INTO verses VALUES (30617, 62, 2, 14, 'escrevi a-vós crianças que conhecestes o Pai escrevi a-vós pais que conhecestes o de princípio escrevi a-vós jovens que fortes sois e o palavra o de-Theos em a-vós permanece e tendes-vencido o mau');
INSERT INTO verses VALUES (30618, 62, 2, 15, 'não amai o mundo nem o em o ao-mundo se alguém ama o mundo não é o amor o do-Pai em a ele');
INSERT INTO verses VALUES (30619, 62, 2, 16, 'que todo o em o ao-mundo o desejo o carne e o desejo o olhos e o arrogância o vida não é de o pai mas de o do-mundo é');
INSERT INTO verses VALUES (30620, 62, 2, 17, 'e o mundo passa e o desejo dele o porém fazendo o vontade o de-Theos permanece para o eternidade');
INSERT INTO verses VALUES (30621, 62, 2, 18, 'Criancinhas última hora é e assim-como ouvistes que anticristo vem e agora anticristos muitos tornaram-se de-onde conhecemos que última hora é');
INSERT INTO verses VALUES (30622, 62, 2, 19, 'de nosso saíram mas não eram de nosso se pois de nosso eram tinham-permanecido partícula-condicional com nosso mas para que sejam-manifestados que não são todos de nosso');
INSERT INTO verses VALUES (30623, 62, 2, 20, 'e vós unção tendes de o do-santo e sei todos');
INSERT INTO verses VALUES (30624, 62, 2, 21, 'não escrevi a-vós que não sei o verdade mas que sei ela e que todo mentira de o da-verdade não é');
INSERT INTO verses VALUES (30625, 62, 2, 22, 'quem é o mentiroso se não o negando que Iesous não é o Christos este é o anticristo o negando o Pai e o filho');
INSERT INTO verses VALUES (30626, 62, 2, 23, 'todo o negando o Filho nem o Pai tem o confessando o Filho e o Pai tem');
INSERT INTO verses VALUES (30627, 62, 2, 24, 'vós o qual ouvistes de princípio em a-vós permaneça se em a-vós permaneça o qual de princípio ouvistes e vós em o filho e em o Pai permanecereis');
INSERT INTO verses VALUES (30628, 62, 2, 25, 'e esta é o promessa o qual ele prometeu a-nós o vida o eterno');
INSERT INTO verses VALUES (30629, 62, 2, 26, 'estas-coisas escrevi a-vós acerca-de o enganando vos');
INSERT INTO verses VALUES (30630, 62, 2, 27, 'e vós o unção o qual recebestes de dele permanece em a-vós e não necessidade tendes para que alguém ensine vos mas como o dele unção ensina vos acerca-de todos e verdadeiro é e não é mentira e assim-como ensinou vos permanecei em a ele');
INSERT INTO verses VALUES (30631, 62, 2, 28, 'e agora filhinhos permanecei em a ele para que se seja-manifestada tenhamos ousadia e não sejamos-envergonhados de dele em o presença dele');
INSERT INTO verses VALUES (30632, 62, 2, 29, 'se sei que justo é sabeis que e todo o fazendo o justiça de dele foi-gerado');
INSERT INTO chapters VALUES (1162, 62, 3, 24);
INSERT INTO verses VALUES (30633, 62, 3, 1, 'Vede que-espécie-de amor tem-dado a-nós o Pai para que filhos de-Theos sejamos-chamados e somos através-de isto o mundo não conhece nos que não conheceu ele');
INSERT INTO verses VALUES (30634, 62, 3, 2, 'Amados agora filhos de-Theos somos e ainda-não foi-manifestado quê seremos sei que se seja-manifestada semelhantes a ele seremos que veremos ele assim-como é');
INSERT INTO verses VALUES (30635, 62, 3, 3, 'e todo o tendo o esperança esta sobre a ele purifica si-mesmo assim-como aquele puro é');
INSERT INTO verses VALUES (30636, 62, 3, 4, 'todo o fazendo o pecado e o iniquidade faz e o pecado é o iniquidade');
INSERT INTO verses VALUES (30637, 62, 3, 5, 'e sei que aquele foi-manifestado para que o do-pecado levante e pecado em a ele não é');
INSERT INTO verses VALUES (30638, 62, 3, 6, 'todo o em a ele permanecendo não peca todo o pecando não tem-visto ele nem tem-conhecido ele');
INSERT INTO verses VALUES (30639, 62, 3, 7, 'Filhinhos ninguém engane vos o fazendo o justiça justo é assim-como aquele justo é');
INSERT INTO verses VALUES (30640, 62, 3, 8, 'o fazendo o pecado de o diabo é que de princípio o diabo peca para isto foi-manifestado o Filho o de-Theos para que desate o obra o diabo');
INSERT INTO verses VALUES (30641, 62, 3, 9, 'todo o gerado de o de-Theos pecado não faz que semente dele em a ele permanece e não pode pecar que de o de-Theos foi-gerado');
INSERT INTO verses VALUES (30642, 62, 3, 10, 'em neste manifesta é o filhos o de-Theos e o filhos o diabo todo o não fazendo justiça não é de o de-Theos e o não amando o irmão dele');
INSERT INTO verses VALUES (30643, 62, 3, 11, 'que esta é o mensagem o qual ouvistes de princípio para que amemos uns-aos-outros');
INSERT INTO verses VALUES (30644, 62, 3, 12, 'não assim-como Caim de o do-mal era e matou o irmão dele e graça de-quem matou ele que o obra dele má era o porém o do-irmão dele justas');
INSERT INTO verses VALUES (30645, 62, 3, 13, 'não admirais irmãos se odeia vos o mundo');
INSERT INTO verses VALUES (30646, 62, 3, 14, 'nós sei que temos-passado de o da-morte para o vida que amemos o irmãos o não amando permanece em o morte');
INSERT INTO verses VALUES (30647, 62, 3, 15, 'todo o odiando o irmão dele homicida é e sei que todo homicida não tem vida eterno em a ele permanecendo');
INSERT INTO verses VALUES (30648, 62, 3, 16, 'em neste temos-conhecido o amor que aquele em-favor-de nosso o alma dele colocou e nós devemos em-favor-de o irmãos o almas pôr');
INSERT INTO verses VALUES (30649, 62, 3, 17, 'o qual e/mas partícula-condicional tenha o vida o do-mundo e contemple o irmão dele necessidade tendo e feche o entranhas dele de dele como o amor o de-Theos permanece em a ele');
INSERT INTO verses VALUES (30650, 62, 3, 18, 'Filhinhos não amemos em-palavra nem o língua mas em obra e verdade');
INSERT INTO verses VALUES (30651, 62, 3, 19, 'em neste conheceremos que de o da-verdade somos e diante dele persuadiremos o coração nosso');
INSERT INTO verses VALUES (30652, 62, 3, 20, 'que se condene nosso o coração que maior é o Theos o do-coração nosso e conhece todas-as-coisas');
INSERT INTO verses VALUES (30653, 62, 3, 21, 'Amados se o coração não condene ousadia temos junto-a o Theos');
INSERT INTO verses VALUES (30654, 62, 3, 22, 'e o qual se peçamos recebemos de dele que o mandamentos dele guardamos e o agradáveis diante-de dele fazemos');
INSERT INTO verses VALUES (30655, 62, 3, 23, 'e esta é o mandamento dele para que creiamos o em-nome o do-Filho dele Iesous de-Christos e amemos uns-aos-outros assim-como deu mandamento a-nós');
INSERT INTO verses VALUES (30656, 62, 3, 24, 'e o guardando o mandamentos dele em a ele permanece e ele em a ele e em neste conhecemos que permanece em a-nós de o do-espírito o qual a-nós deu');
INSERT INTO chapters VALUES (1163, 62, 4, 21);
INSERT INTO verses VALUES (30657, 62, 4, 1, 'Amados não todo espírito credes mas examinai o espíritos se de o de-Theos é que muitos falsos-profetas têm-saído para o mundo');
INSERT INTO verses VALUES (30658, 62, 4, 2, 'em neste sabeis o espírito o de-Theos todo espírito o qual confessa Iesous Christos em carne tendo-vindo de o de-Theos é');
INSERT INTO verses VALUES (30659, 62, 4, 3, 'e todo espírito o qual não confessa o Iesous de o de-Theos não é e isto é o o anticristo o qual tendes-ouvido que vem e agora em o ao-mundo é já');
INSERT INTO verses VALUES (30660, 62, 4, 4, 'vós de o de-Theos sois filhinhos e tendes-vencido eles que maior é o em a-vós ou o em o ao-mundo');
INSERT INTO verses VALUES (30661, 62, 4, 5, 'eles-mesmos de o do-mundo são através-de isto de o do-mundo falam e o mundo deles ouve');
INSERT INTO verses VALUES (30662, 62, 4, 6, 'nós de o de-Theos somos o conhecendo o Theos ouve nosso o qual não é de o de-Theos não ouve nosso de deste conhecemos o espírito o da-verdade e o espírito o engano');
INSERT INTO verses VALUES (30663, 62, 4, 7, 'Amados amemos uns-aos-outros que o amor de o de-Theos é e todo o amando de o de-Theos foi-gerado e conhece o Theos');
INSERT INTO verses VALUES (30664, 62, 4, 8, 'o não amando não conheceu o Theos que o Theos amor é');
INSERT INTO verses VALUES (30665, 62, 4, 9, 'em neste foi-manifestado o amor o de-Theos em a-nós que o Filho dele o unigênito enviou o Theos para o mundo para que vivamos através-de dele');
INSERT INTO verses VALUES (30666, 62, 4, 10, 'em neste é o amor não que nós temos-amado o Theos mas que ele amou nos e enviou o Filho dele Propiciação acerca-de o pecados nosso');
INSERT INTO verses VALUES (30667, 62, 4, 11, 'Amados se assim o Theos amou nos e nós devemos uns-aos-outros amar');
INSERT INTO verses VALUES (30668, 62, 4, 12, 'Theos ninguém jamais tem-contemplado se amemos uns-aos-outros o Theos em a-nós permanece e o amor dele tendo-sido-aperfeiçoada em a-nós é');
INSERT INTO verses VALUES (30669, 62, 4, 13, 'em neste conhecemos que em a ele permanecemos e ele em a-nós que de o do-espírito dele tem-dado a-nós');
INSERT INTO verses VALUES (30670, 62, 4, 14, 'e nós temos-contemplado e testemunhamos que o Pai enviou o Filho Salvador o do-mundo');
INSERT INTO verses VALUES (30671, 62, 4, 15, 'o qual se confesse que Iesous é o Filho o de-Theos o Theos em a ele permanece e ele em o a-Theos');
INSERT INTO verses VALUES (30672, 62, 4, 16, 'e nós temos-conhecido e temos-crido o amor o qual tem o Theos em a-nós o Theos amor é e o permanecendo em o amor em o a-Theos permanece e o Theos em a ele permanece');
INSERT INTO verses VALUES (30673, 62, 4, 17, 'em neste tem-sido-aperfeiçoado o amor com nosso para que ousadia tenhamos em o dia o julgamento que assim-como aquele é e nós somos em o ao-mundo neste');
INSERT INTO verses VALUES (30674, 62, 4, 18, 'medo não é em o amor mas o perfeita amor fora lança o medo que o medo castigo tem o porém temendo não tem-sido-aperfeiçoado em o amor');
INSERT INTO verses VALUES (30675, 62, 4, 19, 'nós amemos que ele primeiro amou nos');
INSERT INTO verses VALUES (30676, 62, 4, 20, 'se alguém diga que Amo o Theos e o irmão dele odeie mentiroso é o pois não amando o irmão dele o qual tem-visto o Theos o qual não tem-visto não pode amar');
INSERT INTO verses VALUES (30677, 62, 4, 21, 'e esta o mandamento temos de dele para que o amando o Theos ama e o irmão dele');
INSERT INTO chapters VALUES (1164, 62, 5, 21);
INSERT INTO verses VALUES (30678, 62, 5, 1, 'todo o crendo que Iesous é o Christos de o de-Theos foi-gerado e todo o amando o tendo-gerado ama o gerado de dele');
INSERT INTO verses VALUES (30679, 62, 5, 2, 'em neste conhecemos que amemos o filhos o de-Theos quando o Theos amemos e o mandamentos dele façamos');
INSERT INTO verses VALUES (30680, 62, 5, 3, 'esta pois é o amor o de-Theos para que o mandamentos dele guardemos e o mandamentos dele pesadas não são');
INSERT INTO verses VALUES (30681, 62, 5, 4, 'que todo o gerado de o de-Theos vence o mundo e esta é o vitória o tendo-vencido o mundo o fé nosso');
INSERT INTO verses VALUES (30682, 62, 5, 5, 'quem é o vencendo o mundo se não o crendo que Iesous é o Filho o de-Theos');
INSERT INTO verses VALUES (30683, 62, 5, 6, 'este é o vindo através-de água e sangue Iesous Christos não em o água somente mas em o água e em o sangue e o Espírito é o testemunhando que o Espírito é o verdade');
INSERT INTO verses VALUES (30684, 62, 5, 7, 'que três são o testemunhando');
INSERT INTO verses VALUES (30685, 62, 5, 8, 'o espírito e o água e o sangue e o três para o um são');
INSERT INTO verses VALUES (30686, 62, 5, 9, 'se o testemunho o dos-homens recebemos o testemunho o de-Theos maior é que esta é o testemunho o de-Theos que tem-testemunhado acerca-de o do-Filho dele');
INSERT INTO verses VALUES (30687, 62, 5, 10, 'o crendo para o Filho o de-Theos tem o testemunho em a-si-mesmo o não crendo o a-Theos mentiroso tem-feito ele que não tem-crido para o testemunho o qual tem-testemunhado o Theos acerca-de o do-Filho dele');
INSERT INTO verses VALUES (30688, 62, 5, 11, 'e esta é o testemunho que vida eterno deu o Theos a-nós e esta o vida em o filho dele é');
INSERT INTO verses VALUES (30689, 62, 5, 12, 'o tendo o Filho tem o vida o não tendo o Filho o de-Theos o vida não tem');
INSERT INTO verses VALUES (30690, 62, 5, 13, 'estas-coisas escrevi a-vós para que sei que vida tendes eterno o creem para o nome o do-Filho o de-Theos');
INSERT INTO verses VALUES (30691, 62, 5, 14, 'e esta é o ousadia o qual temos junto-a ele que se algo peçamos segundo o vontade dele ouve nosso');
INSERT INTO verses VALUES (30692, 62, 5, 15, 'e se sei que ouve nosso o qual se peçamos sei que temos o pedidos o qual Pedimos de dele');
INSERT INTO verses VALUES (30693, 62, 5, 16, 'se alguém veja o irmão dele pecando pecado não junto-a morte pedirá e dará a ele vida o pecam não junto-a morte é pecado junto-a morte não acerca-de daquela digo para que Pergunte');
INSERT INTO verses VALUES (30694, 62, 5, 17, 'toda injustiça pecado é e é pecado não junto-a morte');
INSERT INTO verses VALUES (30695, 62, 5, 18, 'sei que todo o gerado de o de-Theos não peca mas o tendo-sido-gerado de o de-Theos guarda ele e o mau não toca dele');
INSERT INTO verses VALUES (30696, 62, 5, 19, 'sei que de o de-Theos somos e o mundo todo em o mau está-posto');
INSERT INTO verses VALUES (30697, 62, 5, 20, 'sei porém que o Filho o de-Theos chegou e tem-dado a-nós entendimento para que conhecemos o verdadeiro e somos em o verdadeiro em o filho dele Iesous em-Christos este é o verdadeiro Theos e vida eterno');
INSERT INTO verses VALUES (30698, 62, 5, 21, 'Filhinhos guardai A-si-mesmos de o ídolos');
INSERT INTO books VALUES (63, '2JN', '2 João', 'NT', 1);
INSERT INTO chapters VALUES (1165, 63, 1, 13);
INSERT INTO verses VALUES (30699, 63, 1, 1, 'o ancião escolhida senhora e o filhos dela o qual eu amo em verdade e não eu só mas e todos o tendo-conhecido o verdade');
INSERT INTO verses VALUES (30700, 63, 1, 2, 'através-de o verdade o permanecendo em a-nós e com nosso será para o eternidade');
INSERT INTO verses VALUES (30701, 63, 1, 3, 'será com nosso graça misericórdia paz de-junto-de de-Theos Pai e de-junto-de Iesous de-Christos o do-Filho o Pai em verdade e amor');
INSERT INTO verses VALUES (30702, 63, 1, 4, 'Alegrei-me muito que tenho-encontrado de o filhos teu andando em verdade assim-como mandamento recebemos de-junto-de o Pai');
INSERT INTO verses VALUES (30703, 63, 1, 5, 'e agora peço te senhora não como mandamento escrevendo a-ti nova mas o qual tínhamos de princípio para que amemos uns-aos-outros');
INSERT INTO verses VALUES (30704, 63, 1, 6, 'e esta é o amor para que andemos segundo o mandamentos dele esta o mandamento é assim-como ouvistes de princípio para que em a-ela andeis');
INSERT INTO verses VALUES (30705, 63, 1, 7, 'que muitos enganadores saíram para o mundo o não confessando Iesous Christos vindo em na-carne este é o enganador e o anticristo');
INSERT INTO verses VALUES (30706, 63, 1, 8, 'vede a-si-mesmos para que não percais o qual trabalhamos mas salário cheio recebais');
INSERT INTO verses VALUES (30707, 63, 1, 9, 'todo o precedendo e não permanecendo em o em-ensino o de-Christos Theos não tem o permanecendo em o em-ensino este e o Pai e o Filho tem');
INSERT INTO verses VALUES (30708, 63, 1, 10, 'se alguém vem junto-a vos e esta o ensino não carrega não recebeis ele para casa e alegrar-se a ele não dizeis');
INSERT INTO verses VALUES (30709, 63, 1, 11, 'o dizendo pois a ele alegrar-se participa o obra dele o maus');
INSERT INTO verses VALUES (30710, 63, 1, 12, 'muitos tendo a-vós escrever não quis através-de de-papel e tinta mas espero tornar-se junto-a vos e boca junto-a boca falar para que o alegria nosso tendo-sido-preenchida seja');
INSERT INTO verses VALUES (30711, 63, 1, 13, 'Saúda te o filhos o irmã teu o escolhida');
INSERT INTO books VALUES (64, '3JN', '3 João', 'NT', 1);
INSERT INTO chapters VALUES (1166, 64, 1, 15);
INSERT INTO verses VALUES (30712, 64, 1, 1, 'o ancião Gaio o amado o qual eu amo em verdade');
INSERT INTO verses VALUES (30713, 64, 1, 2, 'Amado acerca-de todos oro te prosperar e estar-são assim-como prospera teu o alma');
INSERT INTO verses VALUES (30714, 64, 1, 3, 'Alegrei-me pois muito Vindo irmãos e testemunhando teu o verdade assim-como tu em verdade andas');
INSERT INTO verses VALUES (30715, 64, 1, 4, 'maior destes não tenho alegria para que ouço o minhas-coisas filhos em o verdade andando');
INSERT INTO verses VALUES (30716, 64, 1, 5, 'Amado fiel fazes o qual se Trabalhe para o irmãos e isto estrangeiros');
INSERT INTO verses VALUES (30717, 64, 1, 6, 'o qual testemunharam teu o amor diante-de da-assembleia o qual bem farás tendo-enviado-adiante dignamente o de-Theos');
INSERT INTO verses VALUES (30718, 64, 1, 7, 'em-favor-de pois o do-nome saíram nada recebendo de o gentios');
INSERT INTO verses VALUES (30719, 64, 1, 8, 'nós portanto devemos Supor o tais para que cooperadores tornemo-nos o verdade');
INSERT INTO verses VALUES (30720, 64, 1, 9, 'Escrevi algo o assembleia mas o amando-ser-o-primeiro deles Diótrefes não recebe nos');
INSERT INTO verses VALUES (30721, 64, 1, 10, 'através-de isto se venha Lembrarei dele o obra o qual faz palavras maus tagarelando nos e não contentando-se sobre nestes nem ele recebe o irmãos e o querendo impede e de o da-assembleia expulsa');
INSERT INTO verses VALUES (30722, 64, 1, 11, 'Amado não imita o mau mas o bom o fazendo-o-bem de o de-Theos é o malfeitores não tem-visto o Theos');
INSERT INTO verses VALUES (30723, 64, 1, 12, 'Demétrio tem-sido-testificado sob todos e sob dela o da-verdade e nós porém testemunhamos e sei que o testemunho nosso verdadeiro é');
INSERT INTO verses VALUES (30724, 64, 1, 13, 'muitos tinham escrever a-ti mas não quero através-de tinta e cana a-ti escrever');
INSERT INTO verses VALUES (30725, 64, 1, 14, 'espero porém imediatamente te ver e boca junto-a boca falaremos');
INSERT INTO verses VALUES (30726, 64, 1, 15, 'paz a-ti saúdam te o amigos saúda o amigos segundo nome');
INSERT INTO books VALUES (65, 'JUD', 'Judas', 'NT', 1);
INSERT INTO chapters VALUES (1167, 65, 1, 25);
INSERT INTO verses VALUES (30727, 65, 1, 1, 'Judas Iesous de-Christos servo irmão porém de-Tiago o em a-Theos Pai tendo-sido-amados e Iesous em-Christos aos-tendo-sido-guardados chamados');
INSERT INTO verses VALUES (30728, 65, 1, 2, 'misericórdia a-vós e paz e amor seja-multiplicada');
INSERT INTO verses VALUES (30729, 65, 1, 3, 'Amados toda diligência fazendo escrever a-vós acerca-de o comum nosso salvação necessidade tiveram escrever a-vós exortando lutar-em-favor-de o uma-vez tendo-sido-entregue o santos fé');
INSERT INTO verses VALUES (30730, 65, 1, 4, 'infiltraram-se pois alguns homens o outrora tendo-sido-escritos-de-antemão para isto o julgamento ímpios o o de-Theos nosso graça transferindo para devassidão e o somente Soberano e Kyrion nosso Iesous Christos negando');
INSERT INTO verses VALUES (30731, 65, 1, 5, 'Lembrar porém vos quero sei uma-vez todas-as-coisas que Kyrios povo de da-terra Egito tendo-salvo o segundo o não tendo-crido perdeu');
INSERT INTO verses VALUES (30732, 65, 1, 6, 'anjo e o não tendo-guardado o deles-mesmos início mas tendo-abandonado o próprio habitação para juízo grande do-dia cadeias eternos sob trevas tem-guardado');
INSERT INTO verses VALUES (30733, 65, 1, 7, 'como Sodoma e Gomorra e o acerca-de elas cidades o semelhante modo nestes tendo-fornicado-intensamente e tendo-partido atrás carne outra estão-expostos exemplo fogo eterno castigo Sofrendo');
INSERT INTO verses VALUES (30734, 65, 1, 8, 'semelhantemente contudo e estes sonhando carne por-um-lado contaminam senhorio porém anulam glórias porém blasfemam');
INSERT INTO verses VALUES (30735, 65, 1, 9, 'o porém Miguel o arcanjo quando o diabo duvidando discutia acerca-de o Moisés do-corpo não Ousou juízo proferir blasfêmias mas disse Repreender a-ti Kyrios');
INSERT INTO verses VALUES (30736, 65, 1, 10, 'estes porém quanto por-um-lado não sei blasfemam quanto porém naturalmente como o irracionais ser vivente conhecem em nestes são-corrompidos');
INSERT INTO verses VALUES (30737, 65, 1, 11, 'ai a-eles que o caminho o Caim foram e o engano o Balaão salário foram-derramados e o contradição o Coré pereceram');
INSERT INTO verses VALUES (30738, 65, 1, 12, 'estes são o em o festas-de-amor vosso rochas-ocultas banqueteando-junto sem-temor si-mesmos apascentando nuvens sem-água sob ventos sendo-levadas árvores outonais infrutíferas duas-vezes tendo-morrido tendo-sido-desarraigado');
INSERT INTO verses VALUES (30739, 65, 1, 13, 'ondas selvagens mar espumando-sobre o deles-mesmos vergonhas estrelas seja-enganado o qual o escuridão o das-trevas para eternidade tem-sido-guardado');
INSERT INTO verses VALUES (30740, 65, 1, 14, 'Profetizou porém e nestes sétimo de Adão Enoque dizendo Eis veio Kyrios em santas miríades dele');
INSERT INTO verses VALUES (30741, 65, 1, 15, 'fazer juízo segundo todos e repreender todos o ímpios acerca-de todos o obra impiedade deles o qual agiram-impiamente e acerca-de todos o duros o qual falaram segundo dele pecadores ímpios');
INSERT INTO verses VALUES (30742, 65, 1, 16, 'estes são murmuradores murmuradores segundo o desejos deles indo e o boca deles fala arrogantes admirando faces Proveito graça');
INSERT INTO verses VALUES (30743, 65, 1, 17, 'vós e/mas amados lembrai-vos o palavras o tendo-sido-ditos-antes sob o apóstolos o do-Kyrios nosso Iesous de-Christos');
INSERT INTO verses VALUES (30744, 65, 1, 18, 'que diziam a-vós sobre último o tempo serão zombadores segundo o deles-mesmos desejos indo o impiedades');
INSERT INTO verses VALUES (30745, 65, 1, 19, 'estes são o causando-divisões naturais espírito não tendo');
INSERT INTO verses VALUES (30746, 65, 1, 20, 'vós e/mas amados Edificando-sobre si-mesmos o santíssima vosso fé em Espírito no-santo orando');
INSERT INTO verses VALUES (30747, 65, 1, 21, 'si-mesmos em amor de-Theos guardai aguardando o misericórdia o do-Kyrios nosso Iesous de-Christos para vida eterno');
INSERT INTO verses VALUES (30748, 65, 1, 22, 'e o qual por-um-lado tende-misericórdia sendo-divididos');
INSERT INTO verses VALUES (30749, 65, 1, 23, 'salvais de fogo arrebatando o qual porém tende-misericórdia em medo odiando e o de o carne Tendo-sido-manchado túnica');
INSERT INTO verses VALUES (30750, 65, 1, 24, 'o porém podendo guardar vos sem-tropeçar e estabelecer diante-de o da-glória dele irrepreensíveis em exultação');
INSERT INTO verses VALUES (30751, 65, 1, 25, 'somente a-Theos Salvador nosso através-de Iesous de-Christos o do-Kyrios nosso glória majestade domínio e autoridade antes-de todo o eternidade e agora e para todos o eras amém');
INSERT INTO books VALUES (66, 'DES', 'Desvelação de Jesus Cristo', 'NT', 22);
INSERT INTO chapters VALUES (1168, 66, 1, 20);
INSERT INTO verses VALUES (30752, 66, 1, 1, 'Revelação Iesous de-Christos o qual deu a ele o Theos mostrar o servos dele o qual é necessário tornar-se em brevemente e significou enviando através-de o anjo dele o servo dele João');
INSERT INTO verses VALUES (30753, 66, 1, 2, 'o qual testemunhou o palavra o de-Theos e o testemunho Iesous de-Christos quanto viu');
INSERT INTO verses VALUES (30754, 66, 1, 3, 'Bem-aventurado o lendo e o ouvindo o palavras o profecia e guardando o em a-ela escritas o pois tempo perto');
INSERT INTO verses VALUES (30755, 66, 1, 4, 'João o sete assembleias o em o Ásia graça a-vós e paz de o sendo e o era e o vindo e de o sete Espíritos o qual diante o trono dele');
INSERT INTO verses VALUES (30756, 66, 1, 5, 'e de Iesous de-Christos o testemunha o fiel o primogênito o mortos e o governante o reis o da-terra o amando nos e libertou nos de o pecados nosso em o sangue dele');
INSERT INTO verses VALUES (30757, 66, 1, 6, 'e fez nos reino sacerdotes o a-Theos e Pai dele a ele o glória e o domínio para o eras o eras amém');
INSERT INTO verses VALUES (30758, 66, 1, 7, 'Eis vem com o nuvens e verá ele todo olho e os-quais ele traspassaram e lamentarão sobre ele todas o tribos o da-terra sim amém');
INSERT INTO verses VALUES (30759, 66, 1, 8, 'Eu sou o Alfa e o Ômega diz Kyrios o Theos o sendo e o era e o vindo o Todo-Poderoso');
INSERT INTO verses VALUES (30760, 66, 1, 9, 'eu João o irmão vosso e co-participante em o tribulação e reino e perseverança em Iesous tornei-me em o ilha o chamada Patmos através-de o palavra o de-Theos e o testemunho Iesous');
INSERT INTO verses VALUES (30761, 66, 1, 10, 'tornei-me em Espírito em o do-Kyrios dia e ouvi atrás meu voz grande como trombeta');
INSERT INTO verses VALUES (30762, 66, 1, 11, 'dizendo o qual vês escreve para livro e envia o sete assembleias para Éfeso e para Esmirna e para Pérgamo e para Tiatira e para Sardes e para Filadélfia e para Laodiceia');
INSERT INTO verses VALUES (30763, 66, 1, 12, 'e virei ver o voz a-qual falava com meu e tendo-virado vi sete candelabros dourado');
INSERT INTO verses VALUES (30764, 66, 1, 13, 'e em meio o candelabros semelhante Filho do-homem vestido até-os-pés e cingido junto-a o peitos cinto dourado');
INSERT INTO verses VALUES (30765, 66, 1, 14, 'o porém cabeça dele e o cabelos brancas como lã branco como neve e o olhos dele como chama fogo');
INSERT INTO verses VALUES (30766, 66, 1, 15, 'e o pés dele semelhantes bronze-polido como em fornalha ardente e o voz dele como voz água muitos');
INSERT INTO verses VALUES (30767, 66, 1, 16, 'e tendo em o direita mão dele estrelas sete e de o boca dele espada de-dois-gumes afiada saindo e o aparência dele como o sol brilha em o poder dele');
INSERT INTO verses VALUES (30768, 66, 1, 17, 'e quando vi ele caí junto-a o pés dele como morto e colocou o direita dele sobre mim dizendo não temas eu sou o primeiro e o último');
INSERT INTO verses VALUES (30769, 66, 1, 18, 'e o Vivente e tornei-me morto e eis vivendo sou para o eras o eras e tenho o chaves o da-morte e o Hades');
INSERT INTO verses VALUES (30770, 66, 1, 19, 'escreve portanto o qual viste e o qual são e o qual está-para tornar-se com estas-coisas');
INSERT INTO verses VALUES (30771, 66, 1, 20, 'o mistério o sete estrelas o qual viste sobre o direita meu e o sete candelabros o dourado o sete estrelas anjo o sete igrejas são e o candelabros o sete sete assembleias são');
INSERT INTO chapters VALUES (1169, 66, 2, 29);
INSERT INTO verses VALUES (30772, 66, 2, 1, 'o anjo o em Éfeso da-assembleia escreve estas coisas diz o segurando o sete estrelas em o direita dele o caminhando em meio o sete candelabros o dourado');
INSERT INTO verses VALUES (30773, 66, 2, 2, 'sei o obra teu e o trabalho e o perseverança teu e que não podes suportar maus e provaste o dizendo a-si-mesmos apóstolos e não são e encontraste eles falsos');
INSERT INTO verses VALUES (30774, 66, 2, 3, 'e perseverança tens e suportaste através-de o nome meu e não te-cansaste');
INSERT INTO verses VALUES (30775, 66, 2, 4, 'mas tenho segundo teu que o amor teu o primeiro deixaste');
INSERT INTO verses VALUES (30776, 66, 2, 5, 'lembra portanto de-onde caíste e arrepende-te e o primeiro obra faz se porém não venho a-ti e moverei o candelabro teu de o lugar dela se não te-arrependas');
INSERT INTO verses VALUES (30777, 66, 2, 6, 'mas isto tens que odeias o obra o nicolaítas o qual eu-também odeio');
INSERT INTO verses VALUES (30778, 66, 2, 7, 'o tendo ouvido ouça quê o espírito diz o assembleias o vencendo darei a ele comer de o árvore o da-vida o qual é em o Paraíso o de-Theos');
INSERT INTO verses VALUES (30779, 66, 2, 8, 'e o anjo o em Esmirna da-assembleia escreve estas coisas diz o primeiro e o último o qual aconteceu morto e viveu');
INSERT INTO verses VALUES (30780, 66, 2, 9, 'sei teu o tribulação e o pobreza mas rico és e o blasfêmia de o dizendo judeus ser a-si-mesmos e não são mas sinagoga o Satanás');
INSERT INTO verses VALUES (30781, 66, 2, 10, 'não temas o qual estás-para sofrer eis está-para lançar o diabo de vosso para prisão para que sejais-provados e tereis tribulação dias dez sê fiel até da-morte e darei a-ti o coroa o da-vida');
INSERT INTO verses VALUES (30782, 66, 2, 11, 'o tendo ouvido ouça quê o espírito diz o assembleias o vencendo não não seja-prejudicado de o da-morte o segunda');
INSERT INTO verses VALUES (30783, 66, 2, 12, 'e o anjo o em Pérgamo da-assembleia escreve estas coisas diz o tendo o espada o de-dois-gumes o afiada');
INSERT INTO verses VALUES (30784, 66, 2, 13, 'sei onde habitas onde o trono o Satanás e manténs o nome meu e não negaste o fé meu e em o dias Antipas o testemunha meu o fiel meu o qual foi-morto de a-vós onde o Satanás habita');
INSERT INTO verses VALUES (30785, 66, 2, 14, 'mas tenho segundo teu poucas-coisas que tens ali segurando o ensino Balaão o qual ensinava o Balaque lançar tropeço diante o filhos Israel comer coisas-sacrificadas-a-ídolos e fornicar');
INSERT INTO verses VALUES (30786, 66, 2, 15, 'assim tens e tu segurando o ensino o nicolaítas semelhantemente');
INSERT INTO verses VALUES (30787, 66, 2, 16, 'arrepende-te portanto se porém não venho a-ti rapidamente e guerrearei com deles em o espada o boca meu');
INSERT INTO verses VALUES (30788, 66, 2, 17, 'o tendo ouvido ouça quê o espírito diz o assembleias o vencendo darei a ele o maná o escondido e darei a ele pedrinha branca e sobre o pedrinha nome novo escrito o qual ninguém sei se não o recebendo');
INSERT INTO verses VALUES (30789, 66, 2, 18, 'e o anjo o em Tiatira da-assembleia escreve estas coisas diz o Filho o de-Theos o tendo o olhos dele como chama fogo e o pés dele semelhantes bronze-polido');
INSERT INTO verses VALUES (30790, 66, 2, 19, 'sei teu o obra e o amor e o fé e o serviço e o perseverança teu e o obra teu o últimas maiores o primeiro');
INSERT INTO verses VALUES (30791, 66, 2, 20, 'mas tenho segundo teu que permites o mulher Jezabel o dizendo a-si-mesma profetisa e ensina e engana o meus servos fornicar e comer coisas-sacrificadas-a-ídolos');
INSERT INTO verses VALUES (30792, 66, 2, 21, 'e dei a-ela tempo para que se-arrependa e não quer arrepender-se de o imoralidade dela');
INSERT INTO verses VALUES (30793, 66, 2, 22, 'eis lanço ela para cama e o cometendo-adultério com dela para tribulação grande se não se-arrependerão de o obra dela');
INSERT INTO verses VALUES (30794, 66, 2, 23, 'e o filhos dela matarei em morte e conhecerão todas o assembleias que eu sou o examinando rins e do-coração e darei a-vós a-cada-um segundo o obra vosso');
INSERT INTO verses VALUES (30795, 66, 2, 24, 'a-vós porém digo o restantes o em Tiatira quanto não têm o ensino esta os-quais não conheceram o profundas o Satanás como dizem não lanço sobre vos outro peso');
INSERT INTO verses VALUES (30796, 66, 2, 25, 'exceto o qual tendes segurai até o qual até virei');
INSERT INTO verses VALUES (30797, 66, 2, 26, 'e o vencendo e o guardando até fim o obra meu darei a ele autoridade sobre o nações');
INSERT INTO verses VALUES (30798, 66, 2, 27, 'e apascentará eles em vara ferro como o vasos o cerâmica são-quebrados');
INSERT INTO verses VALUES (30799, 66, 2, 28, 'como eu-também recebi de-junto-de o Pai meu e darei a ele o estrela o matutina');
INSERT INTO verses VALUES (30800, 66, 2, 29, 'o tendo ouvido ouça quê o espírito diz o assembleias');
INSERT INTO chapters VALUES (1170, 66, 3, 22);
INSERT INTO verses VALUES (30801, 66, 3, 1, 'e o anjo o em Sardes da-assembleia escreve estas coisas diz o tendo o sete Espíritos o de-Theos e o sete estrelas sei teu o obra que nome tens que vives e morto és');
INSERT INTO verses VALUES (30802, 66, 3, 2, 'sê vigiando e fortalece o restantes o qual estavam-para morrer não pois encontrei teu obra completas diante o de-Theos meu');
INSERT INTO verses VALUES (30803, 66, 3, 3, 'lembra portanto como recebeste e ouviste e guarda e arrepende-te se portanto não vigies virei como ladrão e não não saibas qual hora virei sobre te');
INSERT INTO verses VALUES (30804, 66, 3, 4, 'mas tens poucas-coisas nomes em Sardes o qual não mancharam o vestes deles e andarão com meu em brancas que dignos são');
INSERT INTO verses VALUES (30805, 66, 3, 5, 'o vencendo assim será-vestido em vestes brancas e não não apagarei o nome dele de o livro o da-vida e confessarei o nome dele diante o Pai meu e diante o anjo dele');
INSERT INTO verses VALUES (30806, 66, 3, 6, 'o tendo ouvido ouça quê o espírito diz o assembleias');
INSERT INTO verses VALUES (30807, 66, 3, 7, 'e o anjo o em Filadélfia da-assembleia escreve estas coisas diz o santo o verdadeiro o tendo o chave Davi o abrindo e ninguém fechará e fechando e ninguém abre');
INSERT INTO verses VALUES (30808, 66, 3, 8, 'sei teu o obra eis dei diante teu porta aberta o qual ninguém pode fechar ela que pequena tens poder e guardaste meu o palavra e não negaste o nome meu');
INSERT INTO verses VALUES (30809, 66, 3, 9, 'eis dou de o sinagoga o Satanás o dizendo a-si-mesmos judeus ser e não são mas mentem eis farei eles para que virão e adorarão diante o pés teu e saibam que eu amei te');
INSERT INTO verses VALUES (30810, 66, 3, 10, 'que guardaste o palavra o perseverança meu eu-também te guardarei de o hora o provação o está-para vir sobre o mundo-habitado toda provar o habitantes sobre o da-terra');
INSERT INTO verses VALUES (30811, 66, 3, 11, 'venho rapidamente segura o qual tens para que ninguém tome o coroa teu');
INSERT INTO verses VALUES (30812, 66, 3, 12, 'o vencendo farei ele coluna em o templo o de-Theos meu e fora não não saia ainda e escreverei sobre ele o nome o de-Theos meu e o nome o cidade o de-Theos meu o nova Jerusalém o descendo de o do-céu de o de-Theos meu e o nome meu o novo');
INSERT INTO verses VALUES (30813, 66, 3, 13, 'o tendo ouvido ouça quê o espírito diz o assembleias');
INSERT INTO verses VALUES (30814, 66, 3, 14, 'e o anjo o em Laodiceia da-assembleia escreve estas coisas diz o Amém o testemunha o fiel e verdadeiro o princípio o criação o de-Theos');
INSERT INTO verses VALUES (30815, 66, 3, 15, 'sei teu o obra que nem frio és nem quente oxalá frio fosses ou quente');
INSERT INTO verses VALUES (30816, 66, 3, 16, 'assim que morno és e nem quente nem frio estou-para te vomitar de o boca meu');
INSERT INTO verses VALUES (30817, 66, 3, 17, 'que dizes que rico sou e enriqueci e nada necessidade tenho e não sei que tu és o miserável e digno-de-pena e pobre e cego e nu');
INSERT INTO verses VALUES (30818, 66, 3, 18, 'aconselho a-ti comprares de meu ouro refinado-no-fogo de fogo para que enriqueças e vestes brancas para que te-vistas e não seja-manifestada o vergonha o nudez teu e colírio ungir o olhos teu para que vejas');
INSERT INTO verses VALUES (30819, 66, 3, 19, 'eu quanto se amo repreendo e disciplino sê-zeloso portanto e arrepende-te');
INSERT INTO verses VALUES (30820, 66, 3, 20, 'Eis estou-de-pé sobre o porta e bato se alguém ouça o voz meu e abra o porta entrarei junto-a ele e cearei com dele e ele com meu');
INSERT INTO verses VALUES (30821, 66, 3, 21, 'o vencendo darei a ele sentar com meu em o trono meu como eu-também venci e sentei com o Pai meu em o trono dele');
INSERT INTO verses VALUES (30822, 66, 3, 22, 'o tendo ouvido ouça quê o espírito diz o assembleias');
INSERT INTO chapters VALUES (1171, 66, 4, 11);
INSERT INTO verses VALUES (30823, 66, 4, 1, 'com estas-coisas vi e eis porta aberta em o no-céu e o voz o primeiro o qual ouvi como trombeta falando com meu dizendo sobe aqui e mostrarei a-ti o qual é necessário tornar-se com estas-coisas');
INSERT INTO verses VALUES (30824, 66, 4, 2, 'imediatamente tornei-me em Espírito e eis trono estava-posto em o no-céu e sobre o trono sentado');
INSERT INTO verses VALUES (30825, 66, 4, 3, 'e o sentado semelhante aparência pedra jaspe e sardônio e arco-íris ao-redor o trono semelhante aparência esmeralda');
INSERT INTO verses VALUES (30826, 66, 4, 4, 'e ao-redor o trono tronos vinte quatro e sobre o tronos vinte quatro anciãos sentados vestidos em vestes brancas e sobre o cabeças deles coroas dourado');
INSERT INTO verses VALUES (30827, 66, 4, 5, 'e de o trono saem relâmpagos e vozes e trovões e sete tochas fogo ardendo diante o trono o qual são o sete Espíritos o de-Theos');
INSERT INTO verses VALUES (30828, 66, 4, 6, 'e diante o trono como mar vidro semelhante cristal e em meio o trono e ao-redor o trono quatro ser vivente cheio olhos diante e atrás');
INSERT INTO verses VALUES (30829, 66, 4, 7, 'e o ser vivente o primeiro semelhante leão e o segundo ser vivente semelhante bezerro e o terço ser vivente tendo o face como do-homem e o quarto ser vivente semelhante águia voando');
INSERT INTO verses VALUES (30830, 66, 4, 8, 'e o quatro ser vivente um segundo um deles tendo cada asas seis ao-redor e por-dentro cheios olhos e descanso não têm do-dia e noite dizendo santo santo santo Kyrios o Theos o Todo-Poderoso o era e o sendo e o vindo');
INSERT INTO verses VALUES (30831, 66, 4, 9, 'e quando darão o ser vivente glória e honra e ação-de-graças o sentado sobre o trono o vivendo para o eras o eras');
INSERT INTO verses VALUES (30832, 66, 4, 10, 'cairão o vinte quatro anciãos diante o sentado sobre o trono e adorarão o vivendo para o eras o eras e lançarão o coroas deles diante o trono dizendo');
INSERT INTO verses VALUES (30833, 66, 4, 11, 'digno és o Kyrios e o Theos nosso receber o glória e o honra e o poder que tu criaste o todas-as-coisas e através-de o vontade teu eram e foram-criadas');
INSERT INTO chapters VALUES (1172, 66, 5, 14);
INSERT INTO verses VALUES (30834, 66, 5, 1, 'e vi sobre o direita o sentado sobre o trono livro escrito por-dentro e atrás selado selos sete');
INSERT INTO verses VALUES (30835, 66, 5, 2, 'e vi anjo forte proclamando em voz grande quem digno abrir o livro e abrir o selos dele');
INSERT INTO verses VALUES (30836, 66, 5, 3, 'e ninguém podia em o no-céu nem sobre o da-terra nem debaixo o da-terra abrir o livro nem ver isso');
INSERT INTO verses VALUES (30837, 66, 5, 4, 'e chorava muito que ninguém digno foi-encontrado abrir o livro nem ver isso');
INSERT INTO verses VALUES (30838, 66, 5, 5, 'e um de o anciãos diz a-mim não chores eis venceu o Leão o de o tribo Judá o Raiz Davi abrir o livro e o sete selos dele');
INSERT INTO verses VALUES (30839, 66, 5, 6, 'e vi em meio o trono e o quatro ser vivente e em meio o anciãos Cordeiro de-pé como morto tendo chifres sete e olhos sete o qual são o sete Espíritos o de-Theos enviados para toda o terra');
INSERT INTO verses VALUES (30840, 66, 5, 7, 'e veio e recebeu de o direita o sentado sobre o trono');
INSERT INTO verses VALUES (30841, 66, 5, 8, 'e quando recebeu o livro o quatro ser vivente e o vinte quatro anciãos caíram diante o Cordeiro tendo cada-um harpa e taças dourado cheias incenso o qual são o orações o santos');
INSERT INTO verses VALUES (30842, 66, 5, 9, 'e cantam cântico nova dizendo digno és receber o livro e abrir o selos dele que foste-morto e compraste o a-Theos em o sangue teu de toda tribo e língua e povo e nação');
INSERT INTO verses VALUES (30843, 66, 5, 10, 'e fizeste eles o a-Theos nosso reino e sacerdotes e reinarão sobre o da-terra');
INSERT INTO verses VALUES (30844, 66, 5, 11, 'e vi e ouvi voz anjo muitos ao-redor o trono e o ser vivente e o anciãos e era o número deles miríades miríades e milhares milhares');
INSERT INTO verses VALUES (30845, 66, 5, 12, 'dizendo voz grande Digno é o Cordeiro o morto receber o poder e riqueza e sabedoria e força e honra e glória e bênção');
INSERT INTO verses VALUES (30846, 66, 5, 13, 'e todo criatura o qual em o no-céu e sobre o da-terra e debaixo o da-terra e sobre o mar é e o em a-eles todas-as-coisas ouvi dizendo o sentado sobre o trono e o Cordeiro o bênção e o honra e o glória e o domínio para o eras o eras');
INSERT INTO verses VALUES (30847, 66, 5, 14, 'e o quatro ser vivente diziam Amém e o anciãos caíram e adoraram');
INSERT INTO chapters VALUES (1173, 66, 6, 17);
INSERT INTO verses VALUES (30848, 66, 6, 1, 'e vi quando abriu o Cordeiro uma de o sete selos e ouvi um de o quatro ser vivente dizendo como voz trovão Vem');
INSERT INTO verses VALUES (30849, 66, 6, 2, 'e vi e eis cavalo branco e o sentado sobre ele tendo arco e foi-dado a ele coroa e saiu vencendo e para que vença');
INSERT INTO verses VALUES (30850, 66, 6, 3, 'e quando abriu o selo o segunda ouvi o segunda ser vivente dizendo Vem');
INSERT INTO verses VALUES (30851, 66, 6, 4, 'e saiu outro cavalo vermelho e o sentado sobre ele foi-dado a ele receber o paz de o da-terra e para que uns-aos-outros matem e foi-dado a ele espada grande');
INSERT INTO verses VALUES (30852, 66, 6, 5, 'e quando abriu o selo o terceira ouvi o terceiro ser vivente dizendo Vem e vi e eis cavalo preto e o sentado sobre ele tendo balança em o mão dele');
INSERT INTO verses VALUES (30853, 66, 6, 6, 'e ouvi como voz em meio o quatro ser vivente dizendo medida trigo denário e três medidas cevada denário e o azeite e o vinho não danifiques');
INSERT INTO verses VALUES (30854, 66, 6, 7, 'e quando abriu o selo o quarta ouvi voz o quarto ser vivente dizendo Vem');
INSERT INTO verses VALUES (30855, 66, 6, 8, 'e vi e eis cavalo amarelo-esverdeado e o sentado sobre dele nome a ele o morte e o Hades seguia com dele e foi-dado a-eles autoridade sobre o quarto o da-terra matar em espada e em fome e em morte e sob o feras o da-terra');
INSERT INTO verses VALUES (30856, 66, 6, 9, 'e quando abriu o quinta selo vi debaixo o altar o almas o mortos através-de o palavra o de-Theos e através-de o testemunho o qual tinham');
INSERT INTO verses VALUES (30857, 66, 6, 10, 'e clamaram voz grande dizendo até quando o Soberano o santo e verdadeiro não julgas e vingas o sangue nosso de o habitantes sobre o da-terra');
INSERT INTO verses VALUES (30858, 66, 6, 11, 'e foi-dado a-eles a-cada-um veste branca e foi-dito a-eles para que descansem ainda tempo pouco até sejam-completados e o conservos deles e o irmãos deles o estando-para serem-mortos como e eles');
INSERT INTO verses VALUES (30859, 66, 6, 12, 'e vi quando abriu o selo o sexta e terremoto grande aconteceu e o sol aconteceu preto como saco de-pelo e o lua toda aconteceu como sangue');
INSERT INTO verses VALUES (30860, 66, 6, 13, 'e o estrelas o do-céu caíram para o terra como figueira lança o olintos-de dela sob do-vento grande tremendo-a');
INSERT INTO verses VALUES (30861, 66, 6, 14, 'e o céu se-separou como livro girando-se e todo monte e ilha de o lugares deles foram-movidos');
INSERT INTO verses VALUES (30862, 66, 6, 15, 'e o reis o da-terra e o grandes e o comandantes e o ricos e o fortes e todo servo e livre esconderam a-si-mesmos para o cavernas e para o rochas o montes');
INSERT INTO verses VALUES (30863, 66, 6, 16, 'e dizem o montes e o rochas caí sobre nos e escondei nos de face o sentado sobre o trono e de o ira o Cordeiro');
INSERT INTO verses VALUES (30864, 66, 6, 17, 'que veio o dia o grande o ira deles e quem pode ficar-de-pé');
INSERT INTO chapters VALUES (1174, 66, 7, 17);
INSERT INTO verses VALUES (30865, 66, 7, 1, 'com isto vi quatro anjo de-pé sobre o quatro cantos o da-terra segurando o quatro ventos o da-terra para que não sopre vento sobre o da-terra nem sobre o mar nem sobre todo árvore');
INSERT INTO verses VALUES (30866, 66, 7, 2, 'e vi outro anjo subindo de oriente sol tendo selo de-Theos vivente e gritou voz grande o quatro anjo o qual foi-dado a-eles prejudicar o terra e o mar');
INSERT INTO verses VALUES (30867, 66, 7, 3, 'dizendo não danifiqueis o terra nem o mar nem o árvores até selemos o servos o de-Theos nosso sobre o testas deles');
INSERT INTO verses VALUES (30868, 66, 7, 4, 'e ouvi o número o selados cem quarenta quatro milhares selados de toda tribo filhos Israel');
INSERT INTO verses VALUES (30869, 66, 7, 5, 'de tribo Judá doze milhares selados de tribo Rúben doze milhares de tribo Gade doze milhares');
INSERT INTO verses VALUES (30870, 66, 7, 6, 'de tribo Aser doze milhares de tribo Naftali doze milhares de tribo Manassés doze milhares');
INSERT INTO verses VALUES (30871, 66, 7, 7, 'de tribo Simeão doze milhares de tribo Levi doze milhares de tribo Issacar doze milhares');
INSERT INTO verses VALUES (30872, 66, 7, 8, 'de tribo Zebulom doze milhares de tribo José doze milhares de tribo Benjamim doze milhares selados');
INSERT INTO verses VALUES (30873, 66, 7, 9, 'com estas-coisas vi e eis multidão muito o qual contar ele ninguém podia de todo nação e tribos e povos e línguas de-pé diante o trono e diante o Cordeiro vestidos vestes brancas e palmas em o mãos deles');
INSERT INTO verses VALUES (30874, 66, 7, 10, 'e clamam voz grande dizendo o salvação o a-Theos nosso o sentado sobre o trono e o Cordeiro');
INSERT INTO verses VALUES (30875, 66, 7, 11, 'e todos o anjo estavam-de-pé ao-redor o trono e o anciãos e o quatro ser vivente e caíram diante o trono sobre o faces deles e adoraram o a-Theos');
INSERT INTO verses VALUES (30876, 66, 7, 12, 'dizendo Amém o bênção e o glória e o sabedoria e o ação-de-graças e o honra e o poder e o força o a-Theos nosso para o eras o eras amém');
INSERT INTO verses VALUES (30877, 66, 7, 13, 'e respondeu um de o anciãos dizendo a-mim estes o vestidos o vestes o brancas quem são e de-onde vieram');
INSERT INTO verses VALUES (30878, 66, 7, 14, 'e disse a ele Kyrios meu tu sei e disse a-mim estes são o vindos de o tribulação o grande e lavaram o vestes deles e embranqueceram elas em o sangue o Cordeiro');
INSERT INTO verses VALUES (30879, 66, 7, 15, 'através-de isto são diante o trono o de-Theos e servem a ele do-dia e noite em o templo dele e o sentado sobre o trono habitará sobre eles');
INSERT INTO verses VALUES (30880, 66, 7, 16, 'não terão-fome ainda nem terão-sede ainda nem não caia sobre eles o sol nem todo calor');
INSERT INTO verses VALUES (30881, 66, 7, 17, 'que o Cordeiro o cada meio o trono apascentará eles e guiará eles sobre da-vida fontes água e apagará o Theos todo lágrima de o olhos deles');
INSERT INTO chapters VALUES (1175, 66, 8, 13);
INSERT INTO verses VALUES (30882, 66, 8, 1, 'e quando abriu o selo o sétima aconteceu silêncio em o no-céu como meia-hora');
INSERT INTO verses VALUES (30883, 66, 8, 2, 'e vi o sete anjo o qual diante o de-Theos estão-de-pé e foram-dadas a-eles sete trombetas');
INSERT INTO verses VALUES (30884, 66, 8, 3, 'e outro anjo veio e colocou-se sobre o altar tendo incensário dourado e foi-dado a ele incensos muitos para que dará o orações o santos todos sobre o altar o dourado o diante o trono');
INSERT INTO verses VALUES (30885, 66, 8, 4, 'e subiu o fumaça o incenso o orações o santos de mão o anjo diante o de-Theos');
INSERT INTO verses VALUES (30886, 66, 8, 5, 'e recebeu o anjo o incensário e encheu ele de o fogo o altar e lançou para o terra e tornaram-se trovões e vozes e relâmpagos e terremoto');
INSERT INTO verses VALUES (30887, 66, 8, 6, 'e o sete anjo o tendo o sete trombetas prepararam a-si-mesmos para que tocarem');
INSERT INTO verses VALUES (30888, 66, 8, 7, 'e o primeiro tocou-trombeta e aconteceu granizo e fogo misturado em sangue e foi-lançado para o terra e o terço o da-terra foi-queimado e o terço o árvores foi-queimado e todo erva verde foi-queimado');
INSERT INTO verses VALUES (30889, 66, 8, 8, 'e o segundo anjo tocou-trombeta e como monte grande fogo ardendo foi-lançado para o mar e aconteceu o terço o mar sangue');
INSERT INTO verses VALUES (30890, 66, 8, 9, 'e morreu o terço o criaturas o em o mar o tendo almas e o terço o navios foram-destruídos');
INSERT INTO verses VALUES (30891, 66, 8, 10, 'e o terceiro anjo tocou-trombeta e caiu de o do-céu estrela grande ardendo como tocha e caiu sobre o terço o rios e sobre o fontes o água');
INSERT INTO verses VALUES (30892, 66, 8, 11, 'e o nome o estrela é-chamado o Absinto e aconteceu o terço o água para absinto e muitos o dos-homens morreram de o água que tornaram-se-amargos');
INSERT INTO verses VALUES (30893, 66, 8, 12, 'e o quarto anjo tocou-trombeta e foi-ferido o terço o sol e o terço o lua e o terço o estrelas para que seja-escurecido o terço deles e o dia não brilhe o terço dela e o noite semelhantemente');
INSERT INTO verses VALUES (30894, 66, 8, 13, 'e vi e ouvi um águia voando em meio-do-céu dizendo voz grande Ai ai ai o habitantes sobre o da-terra de o restantes vozes o trombeta o três anjo o estando-para tocar-trombeta');
INSERT INTO chapters VALUES (1176, 66, 9, 21);
INSERT INTO verses VALUES (30895, 66, 9, 1, 'e o quinto anjo tocou-trombeta e vi estrela de o do-céu caído para o terra e foi-dado a ele o chave o poço o abismo');
INSERT INTO verses VALUES (30896, 66, 9, 2, 'e abriu o poço o abismo e subiu fumaça de o poço como fumaça fornalha grande e foi-escurecido o sol e o ar de o fumaça o poço');
INSERT INTO verses VALUES (30897, 66, 9, 3, 'e de o fumaça saíram gafanhotos para o terra e foi-dado a-eles autoridade como têm autoridade o escorpiões o da-terra');
INSERT INTO verses VALUES (30898, 66, 9, 4, 'e foi-dito a-eles para que não danificarão o erva o da-terra nem todo verde nem todo árvore se não o homens os-quais não têm o selo o de-Theos sobre o testas');
INSERT INTO verses VALUES (30899, 66, 9, 5, 'e foi-dado a-eles para que não matem eles mas para que serão-atormentados meses cinco e o tormento deles como tormento escorpião quando ferisse homem');
INSERT INTO verses VALUES (30900, 66, 9, 6, 'e em o dias aqueles buscarão o homens o morte e não não acharão ele e desejarão morrer e foge o morte de deles');
INSERT INTO verses VALUES (30901, 66, 9, 7, 'e o semelhanças o gafanhotos semelhantes cavalo preparados para guerra e sobre o cabeças deles como coroas semelhantes ouro e o faces deles como faces dos-homens');
INSERT INTO verses VALUES (30902, 66, 9, 8, 'e tinham cabelos como cabelos mulheres e o dentes deles como leões eram');
INSERT INTO verses VALUES (30903, 66, 9, 9, 'e tinham couraças como couraças ferro e o voz o asas deles como voz carros cavalo muitos correndo para guerra');
INSERT INTO verses VALUES (30904, 66, 9, 10, 'e têm caudas semelhantes escorpiões e ferrões e em o caudas deles o autoridade deles prejudicar o homens meses cinco');
INSERT INTO verses VALUES (30905, 66, 9, 11, 'têm sobre deles rei o anjo o abismo nome a ele em-hebraico Abadom e em o em-grego nome tem Apoliom');
INSERT INTO verses VALUES (30906, 66, 9, 12, 'o Ai o uma partiu eis vem ainda dois Ai com estas-coisas');
INSERT INTO verses VALUES (30907, 66, 9, 13, 'e o sexto anjo tocou-trombeta e ouvi voz uma de o quatro chifres o altar o dourado o diante o de-Theos');
INSERT INTO verses VALUES (30908, 66, 9, 14, 'dizendo o sexto anjo o tendo o trombeta solta o quatro anjo o presos sobre o rio o grande Eufrates');
INSERT INTO verses VALUES (30909, 66, 9, 15, 'e foram-soltos o quatro anjo o preparados para o hora e dia e mês e ano para que matem o terço o dos-homens');
INSERT INTO verses VALUES (30910, 66, 9, 16, 'e o número o exércitos o cavalaria vinte-mil miríades ouvi o número deles');
INSERT INTO verses VALUES (30911, 66, 9, 17, 'e assim vi o cavalo em o aparência e o sentados sobre deles tendo couraças de-fogo e jacinto e enxofre e o cabeças o cavalo como cabeças leões e de o bocas deles sai fogo e fumaça e enxofre');
INSERT INTO verses VALUES (30912, 66, 9, 18, 'de o três pragas estas foram-mortos o terço o dos-homens de o fogo e o fumaça e o enxofre o saindo de o bocas deles');
INSERT INTO verses VALUES (30913, 66, 9, 19, 'o pois autoridade o cavalo em o boca deles é e em o caudas deles o pois caudas deles semelhantes serpentes tendo cabeças e em elas danificam');
INSERT INTO verses VALUES (30914, 66, 9, 20, 'e o restantes o dos-homens o qual não foram-mortos em o pragas estas nem arrependeram-se de o obra o mãos deles para que não adorarão o demônios e o ídolos o dourado e o prata e o bronze e o pedra e o madeira o qual nem ver podem nem ouvir nem andar');
INSERT INTO verses VALUES (30915, 66, 9, 21, 'e não arrependeram-se de o homicídios deles nem de o feitiçarias deles nem de o imoralidade deles nem de o furtos deles');
INSERT INTO chapters VALUES (1177, 66, 10, 11);
INSERT INTO verses VALUES (30916, 66, 10, 1, 'e vi outro anjo forte descendo de o do-céu vestido nuvem e o arco-íris sobre o cabeça dele e o face dele como o sol e o pés dele como coluna fogo');
INSERT INTO verses VALUES (30917, 66, 10, 2, 'e tendo em o mão dele livrinho aberto e colocou o pé dele o direito sobre o mar o porém esquerdo sobre o da-terra');
INSERT INTO verses VALUES (30918, 66, 10, 3, 'e gritou voz grande como leão ruge e quando gritou falaram o sete trovões o suas-próprias vozes');
INSERT INTO verses VALUES (30919, 66, 10, 4, 'e quando falaram o sete trovões estava-para escrever e ouvi voz de o do-céu dizendo sela o qual falaram o sete trovões e não elas escrevas');
INSERT INTO verses VALUES (30920, 66, 10, 5, 'e o anjo o qual vi de-pé sobre o mar e sobre o da-terra levantou o mão dele o direita para o céu');
INSERT INTO verses VALUES (30921, 66, 10, 6, 'e jurou em o vivendo para o eras o eras o qual criou o céu e o em a ele e o terra e o em a-ela e o mar e o em a-ela que tempo não-mais será');
INSERT INTO verses VALUES (30922, 66, 10, 7, 'mas em o dias o voz o do-sétimo anjo quando virá-a tocar-trombeta e completou-se o mistério o de-Theos como evangelizou-o o si-mesmo servos o profetas');
INSERT INTO verses VALUES (30923, 66, 10, 8, 'e o voz o qual ouvi de o do-céu novamente falando-a com meu e dizendo Vai-te toma o livro o aberto em o mão o anjo o estando-estacionado sobre o mar e sobre o da-terra');
INSERT INTO verses VALUES (30924, 66, 10, 9, 'e parti-eu junto-a o anjo dizendo a ele dar a-mim o livrinho e diz a-mim toma e comer-em isso e fazer-amargo teu o estômago mas em o boca-com teu será doce como mel');
INSERT INTO verses VALUES (30925, 66, 10, 10, 'e receberam o livrinho de o mão o anjo e comeram isso e era em o boca-com meu como mel doce e quando comeram isso foi-metido-em o ventre meu');
INSERT INTO verses VALUES (30926, 66, 10, 11, 'e dizem-lhes a-mim é necessário te novamente profetizar sobre povos-a e nações e em-línguas e reis-em muitos-a');
INSERT INTO chapters VALUES (1178, 66, 11, 19);
INSERT INTO verses VALUES (30927, 66, 11, 1, 'e foi-dado a-mim cálamo semelhante vara dizendo Levanta-te e mede-o o templo o de-Theos e o altar e o adorando em a ele');
INSERT INTO verses VALUES (30928, 66, 11, 2, 'e o átrio o de-fora o templo expulsa de-fora e não ela você-medirá que foi-dado o nações e o cidade o santa pisarão meses quarenta dois');
INSERT INTO verses VALUES (30929, 66, 11, 3, 'e darei o com-dois testemunhas meu e profetizarão do-dia milhares duzentas sessenta vestidos saco');
INSERT INTO verses VALUES (30930, 66, 11, 4, 'estes são o dois oliveiras e o dois candelabros o diante o do-Kyrios o da-terra de-pé');
INSERT INTO verses VALUES (30931, 66, 11, 5, 'e se alguém eles quer prejudicar fogo sai de o boca deles e devora o inimigos deles e se alguém quererá eles prejudicar assim é necessário ele ser-matado');
INSERT INTO verses VALUES (30932, 66, 11, 6, 'estes têm o autoridade fechar o céu para que não chuva torrencia o do-dia o profecia deles e autoridade têm sobre o água virar elas para sangue e golpear o terra em toda em-ferimento quando-seja se quererão');
INSERT INTO verses VALUES (30933, 66, 11, 7, 'e quando completarão o testemunho deles o besta o subindo de o abismo fará com deles guerra e vencerá eles e matará eles');
INSERT INTO verses VALUES (30934, 66, 11, 8, 'e o corpo deles sobre o largura o cidade o grande a-qual chama-se espiritualmente Sodoma e Egito onde e o Kyrios deles foi-crucificado');
INSERT INTO verses VALUES (30935, 66, 11, 9, 'e vêem de o povos e tribos e línguas e nações o corpo deles do-dia três e metade e o corpos deles não deixam-eles para-ser-colocado para tumba');
INSERT INTO verses VALUES (30936, 66, 11, 10, 'e o habitando sobre o da-terra alegram-se sobre a-eles e regozijam-se e douros enviarão uns-aos-outros que estes o dois profetas tormentaram o habitantes sobre o da-terra');
INSERT INTO verses VALUES (30937, 66, 11, 11, 'e com o três do-dia e metade espírito da-vida de o de-Theos entrou em a-eles e estavam-de-pé sobre o pés deles e medo grande caiu sobre o observando eles');
INSERT INTO verses VALUES (30938, 66, 11, 12, 'e ouviram voz grande de o do-céu dizendo a-eles Subiam aqui e subiram para o céu em o nuvem- e viram eles o inimigos deles');
INSERT INTO verses VALUES (30939, 66, 11, 13, 'e em naquela o hora aconteceu terremoto grande e o décimo o cidade caiu e foram-mortos em o terremoto-em nomes dos-homens milhares sete e o restantes em-freados tornaram-se e deram glória o a-Theos o do-céu');
INSERT INTO verses VALUES (30940, 66, 11, 14, 'o Ai o segunda partiu eis o Ai o terceira vem rapidamente');
INSERT INTO verses VALUES (30941, 66, 11, 15, 'e o sétimo anjo tocou-trombeta e tornaram-se vozes grandes-as em o no-céu dizendo aconteceu o reino o do-mundo o do-Kyrios nosso e o de-Christos dele e reinará para o eras o eras');
INSERT INTO verses VALUES (30942, 66, 11, 16, 'e o vinte quatro anciãos o diante o de-Theos sentados-os sobre o tronos deles caíram sobre o faces deles e adoraram o a-Theos');
INSERT INTO verses VALUES (30943, 66, 11, 17, 'dizendo agradecemos-nos a-ti Kyrie o Theos o Todo-Poderoso o sendo e o era que recebeste o poder-em teu o grande e reinaste-vós');
INSERT INTO verses VALUES (30944, 66, 11, 18, 'e o nações irados-foram e veio o ira teu e o tempo o mortos julgados e dar o salário o servos teu o profetas e o santos e o temendo o nome teu o pequenos e o grandes e corromper o corrompendo o terra');
INSERT INTO verses VALUES (30945, 66, 11, 19, 'e abriu-se o templo o de-Theos o em o no-céu e apareceu o arca o da-aliança dele em o templo dele e tornaram-se relâmpagos e vozes e trovões e terremoto e granizo grande');
INSERT INTO chapters VALUES (1179, 66, 12, 18);
INSERT INTO verses VALUES (30946, 66, 12, 1, 'e sinal grande apareceu em o no-céu mulher vestida o sol e o lua debaixo o pés dela e sobre o cabeça dela coroa estrelas doze');
INSERT INTO verses VALUES (30947, 66, 12, 2, 'e em com-a-ventre tendo e grita dolorida e martirizada para-parir');
INSERT INTO verses VALUES (30948, 66, 12, 3, 'e apareceu outro sinal em o no-céu e eis dragão vermelho grande tendo cabeças sete e chifres dez e sobre o cabeças dele sete diademas');
INSERT INTO verses VALUES (30949, 66, 12, 4, 'e o coda dele arrasta o terço o estrelas o do-céu e lançou eles para o terra e o dragão está-estacionada diante o mulher o está-para para-parir para que quando parto o filho dela comer-e');
INSERT INTO verses VALUES (30950, 66, 12, 5, 'e deu-à-luz filho macho o qual está-para pastorear todas-as-coisas o nações em vara ferro e foi-arrebatado o filho dela junto-a o Theos e junto-a o trono dele');
INSERT INTO verses VALUES (30951, 66, 12, 6, 'e o mulher fugiu para o deserto onde tem ali lugar preparado de o de-Theos para que ali nutrem-no-os ela do-dia mil-e duzentos-e sessenta');
INSERT INTO verses VALUES (30952, 66, 12, 7, 'e aconteceu guerra em o no-céu o Micae-l e o anjo dele o lutar-contra com o dragão e o dragão fez-guerra e o anjo dele');
INSERT INTO verses VALUES (30953, 66, 12, 8, 'e não forçaram nem lugar foi-encontrado deles ainda em o no-céu');
INSERT INTO verses VALUES (30954, 66, 12, 9, 'e foi-lançado o dragão o grande o serpente o antigo o chamado diabo e o Satanás o enganando o habitação toda foi-lançado para o terra e o anjo dele com dele foram-lançados');
INSERT INTO verses VALUES (30955, 66, 12, 10, 'e ouvi voz grande em o no-céu dizendo Agora aconteceu o salvação e o poder e o reino o de-Theos nosso e o autoridade o de-Christos dele que foi-lançado o acusador o irmãos nosso o acusando eles diante o de-Theos nosso do-dia e noite');
INSERT INTO verses VALUES (30956, 66, 12, 11, 'e eles-mesmos venceram ele através-de o sangue o Cordeiro e através-de o palavra o testemunho deles e não amaram o alma deles até da-morte');
INSERT INTO verses VALUES (30957, 66, 12, 12, 'através-de isto alegrai-vos céus e o em a-eles acampando ai o terra e o mar que desceu o diabo junto-a vos tendo ira grande sei que pouco tempo tem');
INSERT INTO verses VALUES (30958, 66, 12, 13, 'e quando viu o dragão que foi-lançado para o terra perseguiu o mulher a-qual deu-à-luz o homem');
INSERT INTO verses VALUES (30959, 66, 12, 14, 'e foram-dadas o mulher-a o dois asas o águia o grande para que voa para o deserto para o lugar dela onde é-nutrido ali tempo e tempos e metade tempo de face o serpente');
INSERT INTO verses VALUES (30960, 66, 12, 15, 'e lançou o serpente de o boca dele atrás o mulher água como rio para que ela levada-pelo-rio faça');
INSERT INTO verses VALUES (30961, 66, 12, 16, 'e ajudou o terra o mulher e abriu o terra o boca dela e engoliu o rio o qual lançou o dragão de o boca dele');
INSERT INTO verses VALUES (30962, 66, 12, 17, 'e irou-se o dragão sobre o mulher e partiu fazer guerra com o restantes o semente dela o guardando o mandamentos o de-Theos e tendo o testemunho Iesous');
INSERT INTO verses VALUES (30963, 66, 12, 18, 'e colocou-se sobre o areia o mar');
INSERT INTO chapters VALUES (1180, 66, 13, 18);
INSERT INTO verses VALUES (30964, 66, 13, 1, 'e vi de o mar besta subindo tendo chifres dez e cabeças sete e sobre o chifres dele dez diademas e sobre o cabeças dele nomes blasfêmias');
INSERT INTO verses VALUES (30965, 66, 13, 2, 'e o besta o qual vi era semelhante leopardo e o pés dele como urso e o boca dele como boca leão e deu a ele o dragão o poder dele e o trono dele e autoridade grande');
INSERT INTO verses VALUES (30966, 66, 13, 3, 'e uma de o cabeças dele como morta para morte e o ferida o da-morte dele foi-curada e foi-maravilhada toda o terra atrás o besta');
INSERT INTO verses VALUES (30967, 66, 13, 4, 'e adoraram o dragão que deu o autoridade o besta e adoraram o besta dizendo quem semelhante o besta e quem pode para-pôr-em-luta com dele');
INSERT INTO verses VALUES (30968, 66, 13, 5, 'e foi-dado a ele boca falando grandes e blasfêmias e foi-dado a ele autoridade fazer meses quarenta dois');
INSERT INTO verses VALUES (30969, 66, 13, 6, 'e abriu o boca dele para blasfêmias junto-a o Theon blasfemar o nome dele e o tabernáculo dele o em o no-céu habitando');
INSERT INTO verses VALUES (30970, 66, 13, 7, 'e foi-dado a ele fazer guerra com o santos e vencer eles e foi-dado a ele autoridade sobre toda tribo e povo e língua e nação');
INSERT INTO verses VALUES (30971, 66, 13, 8, 'e adorarão ele todos o habitando sobre o da-terra o qual não está-escrito o nome dele em o livro o da-vida o Cordeiro o morto de fundação do-mundo');
INSERT INTO verses VALUES (30972, 66, 13, 9, 'se alguém tem ouvido ouça');
INSERT INTO verses VALUES (30973, 66, 13, 10, 'se alguém para cativeiro para cativeiro vai se alguém em espada matará é necessário ele em espada ser-matado aqui é o perseverança e o fé o santos');
INSERT INTO verses VALUES (30974, 66, 13, 11, 'e vi outro besta subindo de o da-terra e tinha chifres dois semelhantes cordeiro e falava como dragão');
INSERT INTO verses VALUES (30975, 66, 13, 12, 'e o autoridade o primeiro besta toda faz diante dele e faz o terra e o em a-ela habitantes para que adorarão o besta o primeiro o qual foi-curada o ferida o da-morte dele');
INSERT INTO verses VALUES (30976, 66, 13, 13, 'e faz sinais grandes para que e fogo faça de o do-céu descer para o terra diante o dos-homens');
INSERT INTO verses VALUES (30977, 66, 13, 14, 'e engana o habitantes sobre o da-terra através-de o sinais o qual foi-dado a ele fazer diante o besta dizendo o habitam sobre o da-terra fazer imagem o besta o qual tem o ferida o espada e viveu');
INSERT INTO verses VALUES (30978, 66, 13, 15, 'e foi-dado a ele dar espírito o imagem o besta para que e fale o imagem o besta e faça para que quanto se não adorem o imagem o besta sejam-mortos');
INSERT INTO verses VALUES (30979, 66, 13, 16, 'e faz todos o pequenos e o grandes e o ricos e o pobres e o livres e o servos para que deem a-eles marca sobre o mão deles o direita ou sobre o testa deles');
INSERT INTO verses VALUES (30980, 66, 13, 17, 'e para que não alguém possa comprares ou vender se não o tendo o marca o nome o besta ou o número o do-nome dele');
INSERT INTO verses VALUES (30981, 66, 13, 18, 'aqui o sabedoria é o tendo entendimento calcule o número o besta número pois do-homem é e o número dele seiscentos sessenta seis');
INSERT INTO chapters VALUES (1181, 66, 14, 20);
INSERT INTO verses VALUES (30982, 66, 14, 1, 'e vi e eis o Cordeiro de-pé sobre o monte Sião e com dele cem quarenta quatro milhares tendo o nome dele e o nome o do-Pai dele escrito sobre o testas deles');
INSERT INTO verses VALUES (30983, 66, 14, 2, 'e ouvi voz de o do-céu como voz água muitos e como voz trovão grande e o voz o qual ouvi como harpistas tocando-harpa em o harpas deles');
INSERT INTO verses VALUES (30984, 66, 14, 3, 'e cantam cântico nova diante o trono e diante o quatro ser vivente e o anciãos e ninguém podia aprender o cântico se não o cem quarenta quatro milhares o comprados de o da-terra');
INSERT INTO verses VALUES (30985, 66, 14, 4, 'estes são o qual com mulheres não mancharam-se virgens pois são estes o seguindo o Cordeiro onde até vá estes foram-comprados de o dos-homens primícias o a-Theos e o Cordeiro');
INSERT INTO verses VALUES (30986, 66, 14, 5, 'e em o boca deles não foi-encontrado mentira sem-mancha são');
INSERT INTO verses VALUES (30987, 66, 14, 6, 'e vi outro anjo voando em meio-do-céu tendo evangelho eterno evangelizar sobre o sentados sobre o da-terra e sobre todo nação e tribo e língua e povo');
INSERT INTO verses VALUES (30988, 66, 14, 7, 'dizendo em voz grande temei o Theos e dai a ele glória que veio o hora o julgamento dele e adorai o que-fez o céu e o terra e mar e fontes água');
INSERT INTO verses VALUES (30989, 66, 14, 8, 'e outro anjo segundo seguiu dizendo caiu caiu Babilônia o grande o qual de o vinho o ira o imoralidade dela deu-de-beber todas-as-coisas o nações');
INSERT INTO verses VALUES (30990, 66, 14, 9, 'e outro anjo terceiro seguiu a-eles dizendo em voz grande se alguém adora o besta e o imagem dele e recebe marca sobre o testa dele ou sobre o mão dele');
INSERT INTO verses VALUES (30991, 66, 14, 10, 'e ele beberá de o vinho o ira o de-Theos o misturado puro em o cálice o ira dele e será-atormentado em fogo e enxofre diante anjo santos e diante o Cordeiro');
INSERT INTO verses VALUES (30992, 66, 14, 11, 'e o fumaça o tormento deles para eras eras sobe e não têm descanso do-dia e noite o adorando o besta e o imagem dele e se alguém recebe o marca o do-nome dele');
INSERT INTO verses VALUES (30993, 66, 14, 12, 'aqui o perseverança o santos é o guardando o mandamentos o de-Theos e o fé Iesous');
INSERT INTO verses VALUES (30994, 66, 14, 13, 'e ouvi voz de o do-céu dizendo escreve bem-aventurados o mortos o em ao-Kyrios morrendo desde-agora sim diz o espírito para que descansarão de o trabalhos deles o pois obra deles segue com deles');
INSERT INTO verses VALUES (30995, 66, 14, 14, 'e vi e eis nuvem branca e sobre o nuvem sentado semelhante Filho do-homem tendo sobre o cabeça dele coroa dourado e em o mão dele foice afiada');
INSERT INTO verses VALUES (30996, 66, 14, 15, 'e outro anjo saiu de o templo clamando em voz grande o sentado sobre o nuvem envia o foice teu e ceifa que veio o hora ceifar que secou o colheita o da-terra');
INSERT INTO verses VALUES (30997, 66, 14, 16, 'e lançou o sentado sobre o nuvem o foice dele sobre o terra e foi-ceifada o terra');
INSERT INTO verses VALUES (30998, 66, 14, 17, 'e outro anjo saiu de o templo o em o no-céu tendo e ele foice afiada');
INSERT INTO verses VALUES (30999, 66, 14, 18, 'e outro anjo saiu de o altar o tendo autoridade sobre o fogo e clamou voz grande o tendo o foice o afiada dizendo envia teu o foice o afiada e vindima o cachos o videira o da-terra que amadureceram o uvas dela');
INSERT INTO verses VALUES (31000, 66, 14, 19, 'e lançou o anjo o foice dele para o terra e vindimou o videira o da-terra e lançou para o lagar o ira o de-Theos o grande');
INSERT INTO verses VALUES (31001, 66, 14, 20, 'e foi-pisado o lagar de-fora o cidade e saiu sangue de o lagar até o freios o cavalo de estádios mil seiscentos');
INSERT INTO chapters VALUES (1182, 66, 15, 8);
INSERT INTO verses VALUES (31002, 66, 15, 1, 'e vi outro sinal em o no-céu grande e maravilhoso anjo sete tendo pragas sete o últimas que em elas completou-se o ira o de-Theos');
INSERT INTO verses VALUES (31003, 66, 15, 2, 'e vi como mar vidro misturada fogo e o vencedores de o besta e de o imagem dele e de o número o do-nome dele de-pé sobre o mar o vidro tendo harpas o de-Theos');
INSERT INTO verses VALUES (31004, 66, 15, 3, 'e cantam o cântico Moisés o servo o de-Theos e o cântico o Cordeiro dizendo grandes e maravilhosas o obra teu Kyrie o Theos o Todo-Poderoso justos e verdadeiros o caminhos teu o Rei o nações');
INSERT INTO verses VALUES (31005, 66, 15, 4, 'quem não não tema Kyrios e glorifique o nome teu que só santo que todas-as-coisas o nações virão e adorarão diante teu que o juízos teu foram-manifestados');
INSERT INTO verses VALUES (31006, 66, 15, 5, 'e com estas-coisas vi e abriu-se o templo o tabernáculo o testemunho em o no-céu');
INSERT INTO verses VALUES (31007, 66, 15, 6, 'e saíram o sete anjo o tendo o sete pragas de o templo vestidos linho limpo resplandecente e cingidos acerca-de o peitos cintos dourado');
INSERT INTO verses VALUES (31008, 66, 15, 7, 'e um de o quatro ser vivente deu o sete anjo sete taças dourado cheias o ira o de-Theos o vivente para o eras o eras');
INSERT INTO verses VALUES (31009, 66, 15, 8, 'e encheu-se o templo fumaça de o da-glória o de-Theos e de o do-poder dele e ninguém podia entrar para o templo até sejam-completadas o sete pragas o sete anjo');
INSERT INTO chapters VALUES (1183, 66, 16, 21);
INSERT INTO verses VALUES (31010, 66, 16, 1, 'e ouvi grande voz de o templo dizendo o sete anjo ide e derramai o sete taças o ira o de-Theos para o terra');
INSERT INTO verses VALUES (31011, 66, 16, 2, 'e partiu o primeiro e derramou o taça dele para o terra e aconteceu ferida mau e mau sobre o homens o tendo o marca o besta e o adorando o imagem dele');
INSERT INTO verses VALUES (31012, 66, 16, 3, 'e o segundo derramou o taça dele para o mar e aconteceu sangue como morto e toda alma da-vida morreu o em o mar');
INSERT INTO verses VALUES (31013, 66, 16, 4, 'e o terceiro derramou o taça dele para o rios e o fontes o água e aconteceu sangue');
INSERT INTO verses VALUES (31014, 66, 16, 5, 'e ouvi o anjo o água dizendo justo és o sendo e o era o Santo que estas-coisas julgaste');
INSERT INTO verses VALUES (31015, 66, 16, 6, 'que sangue santos e profetas derramaram e sangue a-eles deste beber dignos são');
INSERT INTO verses VALUES (31016, 66, 16, 7, 'e ouvi o altar dizendo sim Kyrie o Theos o Todo-Poderoso verdadeiros e justos o julgamentos teu');
INSERT INTO verses VALUES (31017, 66, 16, 8, 'e o quarto derramou o taça dele sobre o sol e foi-dado a ele queimar o homens em fogo');
INSERT INTO verses VALUES (31018, 66, 16, 9, 'e foram-queimados o homens calor grande e blasfemaram o nome o de-Theos o tendo o autoridade sobre o pragas estas e não arrependeram-se dar a ele glória');
INSERT INTO verses VALUES (31019, 66, 16, 10, 'e o quinto derramou o taça dele sobre o trono o besta e aconteceu o reino dele escurecida e mordiam o línguas deles de o dor');
INSERT INTO verses VALUES (31020, 66, 16, 11, 'e blasfemaram o Theos o do-céu de o dores deles e de o feridas deles e não arrependeram-se de o obra deles');
INSERT INTO verses VALUES (31021, 66, 16, 12, 'e o sexto derramou o taça dele sobre o rio o grande Eufrates e secou o água dele para que seja-preparado o caminho o reis o de oriente sol');
INSERT INTO verses VALUES (31022, 66, 16, 13, 'e vi de o boca o dragão e de o boca o besta e de o boca o falso-profeta espíritos três imundos como rãs');
INSERT INTO verses VALUES (31023, 66, 16, 14, 'são pois espíritos demônios fazendo sinais o qual sai sobre o reis o mundo-habitado toda reunir eles para o guerra o do-dia o grande o de-Theos o Todo-Poderoso');
INSERT INTO verses VALUES (31024, 66, 16, 15, 'Eis venho como ladrão bem-aventurado o vigiando e guardando o vestes dele para que não nu ande e vejam o vergonha dele');
INSERT INTO verses VALUES (31025, 66, 16, 16, 'e reuniu eles para o lugar o chamado em-hebraico Armagedom');
INSERT INTO verses VALUES (31026, 66, 16, 17, 'e o sétimo derramou o taça dele sobre o ar e saiu voz grande de o templo de o trono dizendo aconteceu');
INSERT INTO verses VALUES (31027, 66, 16, 18, 'e tornaram-se relâmpagos e vozes e trovões e terremoto aconteceu grande tal-qual não aconteceu de o qual homem aconteceu sobre o da-terra tão-grande terremoto assim grande');
INSERT INTO verses VALUES (31028, 66, 16, 19, 'e aconteceu o cidade o grande para três partes e o cidades o nações caíram e Babilônia o grande lembrou diante o de-Theos dar a-ela o cálice o vinho o ira o ira dele');
INSERT INTO verses VALUES (31029, 66, 16, 20, 'e toda ilha fugiu e montes não foram-encontrados');
INSERT INTO verses VALUES (31030, 66, 16, 21, 'e granizo grande como de-talento desce de o do-céu sobre o homens e blasfemaram o homens o Theos de o praga o de-tormenta que grande é o ferida dela extremamente');
INSERT INTO chapters VALUES (1184, 66, 17, 18);
INSERT INTO verses VALUES (31031, 66, 17, 1, 'e veio um de o sete anjo o tendo o sete taças e falou com meu dizendo Aqui mostrarei a-ti o julgamento o Prostituta o grande o sentada sobre água muitos');
INSERT INTO verses VALUES (31032, 66, 17, 2, 'com o qual cometeram-prostituição o reis o da-terra e for-intoxicados o habitando o terra de o vinho o imoralidade dela');
INSERT INTO verses VALUES (31033, 66, 17, 3, 'e levou-a me para deserto em Espírito e vi mulher sentada sobre besta escarlate cheio nomes blasfêmias tendo cabeças sete e chifres dez');
INSERT INTO verses VALUES (31034, 66, 17, 4, 'e o mulher era vestida púrpura e escarlate e em-o-ouro de-o-ouro e pedra precioso e com-as-perolas tendo cálice dourado em o mão dela cheia-de das-abominações e o imundos o imoralidade dela');
INSERT INTO verses VALUES (31035, 66, 17, 5, 'e sobre o testa dela nome escrito mistério BABILÔNIA o Grande o Mãe o de-pornos e o de-bdelugma o da-gees');
INSERT INTO verses VALUES (31036, 66, 17, 6, 'e vi o mulher estavam-intoxicando-se de o sangue o santos e de o sangue o testemunhas Iesous e maravilhei-me vendo ela maravilha grande');
INSERT INTO verses VALUES (31037, 66, 17, 7, 'e disse a-mim o anjo através-de quê maravilhaste-te eu darei-testemunho a-ti o mistério o mulher e o besta o levando-o ela o tendo o sete cabeças e o dez chifres');
INSERT INTO verses VALUES (31038, 66, 17, 8, 'o besta o qual viste era e não é e está-para subir de o abismo e para perdição vai e serão-maravilhados o habitando sobre o da-terra o qual não está-escrito o nome sobre o livro o da-vida de fundação do-mundo veendo-os o besta que era e não é e estará-aqui');
INSERT INTO verses VALUES (31039, 66, 17, 9, 'aqui o mente o tendo sabedoria o sete cabeças sete montes são onde o mulher está-se-assentando sobre deles e reis sete são');
INSERT INTO verses VALUES (31040, 66, 17, 10, 'o cinco caíram o um é o outro ainda-não veio e quando venha pouco ele é necessário permanecer');
INSERT INTO verses VALUES (31041, 66, 17, 11, 'e o besta o qual era e não é e ele oitavo é e de o sete é e para destruição-em vai');
INSERT INTO verses VALUES (31042, 66, 17, 12, 'e o dez chifres o qual viste dez reis são os-quais reino ainda-não receberam mas autoridade como reis uma hora recebem-deles com o besta');
INSERT INTO verses VALUES (31043, 66, 17, 13, 'estes uma opinião têm e o poder e autoridade deles o besta dão-a-eles');
INSERT INTO verses VALUES (31044, 66, 17, 14, 'estes com o Cordeiro guerra-fará e o Cordeiro vencerá eles que Kyrios senhores-de é e Rei reis e o com dele chamados-a e elegidos-os e fiéis');
INSERT INTO verses VALUES (31045, 66, 17, 15, 'e diz a-mim o água o qual viste do-qual o meretriz-a assenta-se povos e multidões são e nações e línguas');
INSERT INTO verses VALUES (31046, 66, 17, 16, 'e o dez chifres o qual viste e o besta estes odiarão o meretriz e deserta fazerão ela e nua e o carnes dela comerão e ela queimarão em fogo');
INSERT INTO verses VALUES (31047, 66, 17, 17, 'o pois Theos deu para o do-coração deles fazer o opinião dele e fazer uma opinião e dar o reino deles o besta até serão cumpridas o palavras o de-Theos');
INSERT INTO verses VALUES (31048, 66, 17, 18, 'e o mulher o qual viste é o cidade o grande o tendo reino sobre o reis o da-terra');
INSERT INTO chapters VALUES (1185, 66, 18, 24);
INSERT INTO verses VALUES (31049, 66, 18, 1, 'com estas-coisas vi outro anjo descendo de o do-céu tendo autoridade grande e o terra foi-iluminado de o da-glória dele');
INSERT INTO verses VALUES (31050, 66, 18, 2, 'e gritou em com-forte voz dizendo caiu caiu Babilônia o grande e aconteceu morada-em demônios e guarda- todo do-espírito de-imundo e guarda- todo de-pássaro de-imundo e marcado-contra');
INSERT INTO verses VALUES (31051, 66, 18, 3, 'que de o vinho o ira o imoralidade dela for-amassados todas-as-coisas o nações e o reis o da-terra com dela fizeram-pornografia e o mercadores o da-terra de o do-poder o gastadores dela enriqueceram-se');
INSERT INTO verses VALUES (31052, 66, 18, 4, 'e ouvi outra voz de o do-céu dizendo saiam o povo meu de dela para que não comunicai-vos o pecados dela e de o pragas dela para que não tomais');
INSERT INTO verses VALUES (31053, 66, 18, 5, 'que coligaram-se dela o pecados até o do-céu e lembrara o Theos o injustiças dela');
INSERT INTO verses VALUES (31054, 66, 18, 6, 'repassai a-ela como e ela repassou e duplicais o dobro segundo o obra dela em o cálice o qual espremeu espremem a-ela duplicando');
INSERT INTO verses VALUES (31055, 66, 18, 7, 'quanto glorificou ela e estendeu tanto-assim dai a-ela tormento-em e luto que em o no-coração dela diz que Sento-me rainha-a e viúva-a não sou e luto não não vejo-eu');
INSERT INTO verses VALUES (31056, 66, 18, 8, 'através-de isto em uma dia virão o pragas dela morte e luto e fome-o e em fogo queimará-se-fora que forte Kyrios o Theos o julgando-você ela');
INSERT INTO verses VALUES (31057, 66, 18, 9, 'e chorarão-eles e lamentarão sobre ela o reis o da-terra o com dela prostituindo-se e desperdiçando-se quando vejam o fumo- o queimadura- dela');
INSERT INTO verses VALUES (31058, 66, 18, 10, 'de de-longe estando-parados através-de o medo o tormento dela dizendo Ai ai o cidade o grande Babilônia o cidade o fortes que uma hora veio o julgamento teu');
INSERT INTO verses VALUES (31059, 66, 18, 11, 'e o mercadores o da-terra choram e lamentam-se sobre ela que o goma- deles ninguém compra não-mais');
INSERT INTO verses VALUES (31060, 66, 18, 12, 'gomo de-ouro e de-prata e de-pedra precioso e de-perola e de-linho e púrpura e sírio-de e carmesim-de e todo madeira/árvore oferta-vaporosa e todo vaso marfim e todo vaso de árvore preciosíssima e bronze e ferro e mármore');
INSERT INTO verses VALUES (31061, 66, 18, 13, 'e canela e amomo e incensos e mirra e olíbano e vinho e azeite e flor-de-farinha e trigo e gados e ovelhas e cavalo e carros e corpos e almas dos-homens');
INSERT INTO verses VALUES (31062, 66, 18, 14, 'e o frutos teu o desejos o alma partiu de teu e todas-as-coisas o gorduras e o esplêndidas pereceram de teu e não-mais não não elas acharão');
INSERT INTO verses VALUES (31063, 66, 18, 15, 'o mercadores estas o enriquecidos de dela de de-longe ficarão-de-pé através-de o medo o tormento dela chorando e lamentando');
INSERT INTO verses VALUES (31064, 66, 18, 16, 'dizendo Ai ai o cidade o grande o vestida linho-fino e púrpura e escarlate e em-ouro-posto em com-ouro e pedra precioso e pérola');
INSERT INTO verses VALUES (31065, 66, 18, 17, 'que uma hora foi-devastada o tão-grande riqueza e todo piloto e todo o sobre lugar navegando e marinheiros e quanto o mar trabalham de de-longe estavam-de-pé');
INSERT INTO verses VALUES (31066, 66, 18, 18, 'e clamavam vendo o vapor o de-incandescência dela dizendo quem semelhante o cidade o grande');
INSERT INTO verses VALUES (31067, 66, 18, 19, 'e lançaram pó sobre o cabeças deles e clamavam chorando e lamentando dizendo Ai ai o cidade o grande em o qual enriqueceram-se todos o tendo o navios em o mar de o preciosidade dela que uma hora foi-devastada');
INSERT INTO verses VALUES (31068, 66, 18, 20, 'alegra-te sobre a-ela céu e o santos e o apóstolos e o profetas que julgou o Theos o julgamento vosso de dela');
INSERT INTO verses VALUES (31069, 66, 18, 21, 'e levantou um anjo forte pedra como mó grande e lançou para o mar dizendo assim ímpeto será-lançada Babilônia o grande cidade e não não seja-encontrada ainda');
INSERT INTO verses VALUES (31070, 66, 18, 22, 'e voz harpistas e músicos e flautistas e trombeteiros não não seja-ouvido em a-ti ainda e todo artífice toda arte não não seja-encontrada em a-ti ainda e voz moinho não não seja-ouvido em a-ti ainda');
INSERT INTO verses VALUES (31071, 66, 18, 23, 'e luz lâmpada não não brilhe em a-ti ainda e voz noivo e noiva não não seja-ouvido em a-ti ainda que o mercadores teu eram o grandes o da-terra que em o feitiçaria teu foram-enganados todas-as-coisas o nações');
INSERT INTO verses VALUES (31072, 66, 18, 24, 'e em a-ela sangue profetas e santos foi-encontrado e todos o mortos sobre o da-terra');
INSERT INTO chapters VALUES (1186, 66, 19, 21);
INSERT INTO verses VALUES (31073, 66, 19, 1, 'com estas-coisas ouvi como voz grande multidão grande em o no-céu dizendo Aleluia o salvação e o glória e o poder o de-Theos nosso');
INSERT INTO verses VALUES (31074, 66, 19, 2, 'que verdadeiros e justos o julgamentos dele que julgou o meretriz o grande a-qual corrompeu o terra em o imoralidade dela e vingou o sangue o servos dele de mão dela');
INSERT INTO verses VALUES (31075, 66, 19, 3, 'e segundo disseram Aleluia e o fumaça dela sobe para o eras o eras');
INSERT INTO verses VALUES (31076, 66, 19, 4, 'e caíram o anciãos o vinte quatro e o quatro ser vivente e adoraram o a-Theos o sentado sobre o trono dizendo Amém Aleluia');
INSERT INTO verses VALUES (31077, 66, 19, 5, 'e voz de o trono saiu dizendo louvai o a-Theos nosso todos o servos dele o tementes ele o pequenos e o grandes');
INSERT INTO verses VALUES (31078, 66, 19, 6, 'e ouvi como voz multidão grande e como voz água muitos e como voz trovões fortes dizendo Aleluia que reinou Kyrios o Theos nosso o Todo-Poderoso');
INSERT INTO verses VALUES (31079, 66, 19, 7, 'alegremo-nos e regozijemo-nos e demos o glória a ele que veio o bodas o Cordeiro e o mulher dele preparou a-si-mesma');
INSERT INTO verses VALUES (31080, 66, 19, 8, 'e foi-dado a-ela para que vista-se linho-fino resplandecente limpo o pois linho-fino o atos-justos o santos é');
INSERT INTO verses VALUES (31081, 66, 19, 9, 'e diz a-mim escreve bem-aventurados o para o ceia o bodas o Cordeiro chamados e diz a-mim estas o palavras verdadeiras o de-Theos são');
INSERT INTO verses VALUES (31082, 66, 19, 10, 'e caí diante o pés dele adorar a ele e diz a-mim veja não conservo teu sou e o irmãos teu o tendo o testemunho Iesous o a-Theos adora o pois testemunho Iesous é o espírito o profecia');
INSERT INTO verses VALUES (31083, 66, 19, 11, 'e vi o céu aberto e eis cavalo branco e o sentado sobre ele chamado fiel e Verdadeiro e em justiça julga e guerreia');
INSERT INTO verses VALUES (31084, 66, 19, 12, 'o porém olhos dele chama fogo e sobre o cabeça dele diademas muitos tendo nome escrito o qual ninguém sei se não ele');
INSERT INTO verses VALUES (31085, 66, 19, 13, 'e vestido manto tingido sangue e é-chamado o nome dele o palavra o de-Theos');
INSERT INTO verses VALUES (31086, 66, 19, 14, 'e o exércitos o em o no-céu seguia a ele sobre cavalo brancas vestidos linho-fino branco limpo');
INSERT INTO verses VALUES (31087, 66, 19, 15, 'e de o boca dele sai espada afiada para que em a-ela fira o nações e ele apascentará eles em vara ferro e ele pisa o lagar o vinho o ira o ira o de-Theos o Todo-Poderoso');
INSERT INTO verses VALUES (31088, 66, 19, 16, 'e tem sobre o manto e sobre o coxa dele nome escrito REI REIS E KYRIOS SENHORES');
INSERT INTO verses VALUES (31089, 66, 19, 17, 'e vi um anjo de-pé em o sol e gritou em voz grande dizendo todos o aves o voando em meio-do-céu vinde ajuntai-vos para o ceia o grande o de-Theos');
INSERT INTO verses VALUES (31090, 66, 19, 18, 'para que comei carnes reis e carnes comandantes e carnes fortes e carnes cavalo e o montados sobre deles e carnes todos livres e e servos e pequenos e grandes');
INSERT INTO verses VALUES (31091, 66, 19, 19, 'e vi o besta e o reis o da-terra e o exércitos deles reunidos fazer o guerra com o sentado sobre o cavalo e com o exército dele');
INSERT INTO verses VALUES (31092, 66, 19, 20, 'e foi-presa o besta e com dele o falso-profeta o tendo-feito o sinais diante-de dele em o qual enganou o recebendo o marca o besta e o adorando o imagem dele vivos foram-lançados o dois para o lago o fogo o ardendo em enxofre');
INSERT INTO verses VALUES (31093, 66, 19, 21, 'e o restantes foram-mortos em o espada o sentado sobre o cavalo o saindo de o boca dele e todas-as-coisas o aves fartaram-se de o carnes deles');
INSERT INTO chapters VALUES (1187, 66, 20, 15);
INSERT INTO verses VALUES (31094, 66, 20, 1, 'e vi anjo descendo de o do-céu tendo o chave o abismo e cadeia grande sobre o mão dele');
INSERT INTO verses VALUES (31095, 66, 20, 2, 'e prendeu o dragão o serpente o antigo o qual é diabo e o Satanás e amarrou ele mil anos');
INSERT INTO verses VALUES (31096, 66, 20, 3, 'e lançou ele para o abismo e fechou e selou sobre dele para que não engane ainda o nações até sejam-completados o mil anos com estas-coisas é necessário ser-solto ele pouco tempo');
INSERT INTO verses VALUES (31097, 66, 20, 4, 'e vi tronos e sentaram-se sobre eles e julgamento foi-dado a-eles e o almas o decapitados através-de o testemunho Iesous e através-de o palavra o de-Theos e os-quais não adoraram o besta nem o imagem dele e não receberam o marca sobre o testa e sobre o mão deles e viveram e reinaram com o de-Christos mil anos');
INSERT INTO verses VALUES (31098, 66, 20, 5, 'o restantes o mortos não viveram até sejam-completados o mil anos esta o ressurreição o primeiro');
INSERT INTO verses VALUES (31099, 66, 20, 6, 'bem-aventurado e santo o tendo parte em o ressurreição o primeiro sobre estas o segundo morte não tem autoridade mas serão sacerdotes o de-Theos e o de-Christos e reinarão com dele o mil anos');
INSERT INTO verses VALUES (31100, 66, 20, 7, 'e quando sejam-completados o mil anos será-solto o Satanás de o prisão dele');
INSERT INTO verses VALUES (31101, 66, 20, 8, 'e sairá enganar o nações o em o quatro cantos o da-terra o Gogue e Magogue reunir eles para o guerra o qual o número deles como o areia o mar');
INSERT INTO verses VALUES (31102, 66, 20, 9, 'e subiram sobre o largura o da-terra e cercaram o acampamento o santos e o cidade o amada e desceu fogo de o do-céu e devorou eles');
INSERT INTO verses VALUES (31103, 66, 20, 10, 'e o diabo o enganando eles foi-lançado para o lago o fogo e enxofre onde e o besta e o falso-profeta e serão-atormentados do-dia e noite para o eras o eras');
INSERT INTO verses VALUES (31104, 66, 20, 11, 'e vi trono grande branco e o sentado sobre ele o qual de o face fugiu o terra e o céu e lugar não foi-encontrado a-eles');
INSERT INTO verses VALUES (31105, 66, 20, 12, 'e vi o mortos o grandes e o pequenos de-pé diante o trono e livros foram-abertos e outro livro foi-aberto o qual é o da-vida e foram-julgados o mortos de o escritas em o livros segundo o obra deles');
INSERT INTO verses VALUES (31106, 66, 20, 13, 'e deu o mar o mortos o em a-ela e o morte e o Hades deram o mortos o em a-eles e foram-julgados cada-um segundo o obra deles');
INSERT INTO verses VALUES (31107, 66, 20, 14, 'e o morte e o Hades foram-lançados para o lago o fogo este o morte o segundo é o lago o fogo');
INSERT INTO verses VALUES (31108, 66, 20, 15, 'e se alguém não foi-encontrado em o livro o da-vida escrito foi-lançado para o lago o fogo');
INSERT INTO chapters VALUES (1188, 66, 21, 27);
INSERT INTO verses VALUES (31109, 66, 21, 1, 'e vi céu novo e terra nova o pois primeiro céu e o primeiro terra passaram e o mar não é ainda');
INSERT INTO verses VALUES (31110, 66, 21, 2, 'e o cidade o santa Jerusalém nova vi descendo de o do-céu de o de-Theos preparada como noiva adornada o marido dela');
INSERT INTO verses VALUES (31111, 66, 21, 3, 'e ouvi voz grande de o trono dizendo Eis o tabernáculo o de-Theos com o dos-homens e habitará com deles e eles-mesmos povos dele serão e ele o Theos com deles será');
INSERT INTO verses VALUES (31112, 66, 21, 4, 'e apagará todo lágrima de o olhos deles e o morte não será ainda nem luto nem clamor nem dor não será ainda que o primeiro passaram');
INSERT INTO verses VALUES (31113, 66, 21, 5, 'e disse o sentado sobre o trono Eis novas faço todas-as-coisas e diz escreve que estes o palavras fiéis e verdadeiros são');
INSERT INTO verses VALUES (31114, 66, 21, 6, 'e disse a-mim está-feito eu o Alfa e o Ômega o princípio e o fim eu o sedento darei de o fonte o água o da-vida de-graça');
INSERT INTO verses VALUES (31115, 66, 21, 7, 'o vencendo herdará estas-coisas e serei a ele Theos e ele será a-mim filho');
INSERT INTO verses VALUES (31116, 66, 21, 8, 'o porém covardes e incrédulos e abomináveis e homicidas e imorais e feiticeiros e idólatras e todos o mentirosos o parte deles em o lago o ardendo fogo e enxofre o qual é o morte o segundo');
INSERT INTO verses VALUES (31117, 66, 21, 9, 'e veio um de o sete anjo o tendo o sete taças o cheias o sete pragas o últimas e falou com meu dizendo Aqui mostrarei a-ti o noiva o mulher o cordeiro');
INSERT INTO verses VALUES (31118, 66, 21, 10, 'e levou-para me em Espírito sobre monte grande e alto e mostrou a-mim o cidade o santa Jerusalém descendo de o do-céu de o de-Theos');
INSERT INTO verses VALUES (31119, 66, 21, 11, 'tendo o glória o de-Theos o luminária dela semelhante pedra preciosíssima como pedra jaspe cristalino');
INSERT INTO verses VALUES (31120, 66, 21, 12, 'tendo muro grande e alto tendo portas doze e sobre o portando anjo doze e nomes escritos-em o qual é o doze tribos filhos Israel');
INSERT INTO verses VALUES (31121, 66, 21, 13, 'de oriente portões três e de norte portões três e de do-sul portões três e de do-poente portões três');
INSERT INTO verses VALUES (31122, 66, 21, 14, 'e o muro o cidade tendo fundamentos doze e sobre deles doze nomes o doze apóstolos o Cordeiro');
INSERT INTO verses VALUES (31123, 66, 21, 15, 'e o falando com meu tinha medida cálamo dourado para que medirás o cidade e o portas dela e o muro dela');
INSERT INTO verses VALUES (31124, 66, 21, 16, 'e o cidade quadrado está-deitado e o comprimento dela quanto o largura e mediu o cidade o com-espada-de-cana sobre estádios doze milhares o comprimento e o largura e o altura dela igual é');
INSERT INTO verses VALUES (31125, 66, 21, 17, 'e o-medeu o muro dela cem quarenta quatro côvados-de-homem medida do-homem o qual é anjo');
INSERT INTO verses VALUES (31126, 66, 21, 18, 'e o a-forração o das-paredes dela jaspe e o cidade ouro limpo semelhante de-vidro puro');
INSERT INTO verses VALUES (31127, 66, 21, 19, 'o fundamentos o de-a-muralha o cidade todo pedra precioso ornamentados o fundamento o primeiro jaspe o segundo sapfo-íris o terceiro calcedônia o quarto esmeralda');
INSERT INTO verses VALUES (31128, 66, 21, 20, 'o quinto sardônix o sexto saradion o sétimo crisólito o oitavo berilo o Nono topázio o décimo crisópraso o Décimo-primeiro jacinto o décimo-segundo ametista');
INSERT INTO verses VALUES (31129, 66, 21, 21, 'e o doze portões doze pérolas cada um cada-um o portões era de de-um da-pérola e o praça o cidade ouro limpo como vidro claro');
INSERT INTO verses VALUES (31130, 66, 21, 22, 'e templo não vi em a-ela o pois Kyrios o Theos o Todo-Poderoso templo dela é e o Cordeiro');
INSERT INTO verses VALUES (31131, 66, 21, 23, 'e o cidade não necessidade tem o sol nem o lua para que iluminação a-ela o pois glória o de-Theos iluminou ela e o candeia dela o Cordeiro');
INSERT INTO verses VALUES (31132, 66, 21, 24, 'e andarão o nações através-de o luz dela e o reis o da-terra trazem o glória deles para ela');
INSERT INTO verses VALUES (31133, 66, 21, 25, 'e o portões dela não não sejam-fechados do-dia noite pois não será ali');
INSERT INTO verses VALUES (31134, 66, 21, 26, 'e trarão o glória e o honra o nações para ela');
INSERT INTO verses VALUES (31135, 66, 21, 27, 'e não não entre para ela todo comum e o fazendo abominação e mentira se não o escritos em o livro o da-vida o Cordeiro');
INSERT INTO chapters VALUES (1189, 66, 22, 21);
INSERT INTO verses VALUES (31136, 66, 22, 1, 'e mostrou a-mim rio água da-vida resplandecente como crystallo saindo de o trono o de-Theos e o Cordeiro');
INSERT INTO verses VALUES (31137, 66, 22, 2, 'em meio o largura dela e o do-río dali-de e dali madeira/árvore da-vida fazendo frutos doze segundo mês cada-um dando-em-retornar o fruto dele e o folhas o árvore para cura o nações');
INSERT INTO verses VALUES (31138, 66, 22, 3, 'e todo maldição não será ainda e o trono o de-Theos e o Cordeiro em a-ela será e o servos dele servirão-a a ele');
INSERT INTO verses VALUES (31139, 66, 22, 4, 'e verão o face dele e o nome dele sobre o testas deles');
INSERT INTO verses VALUES (31140, 66, 22, 5, 'e noite não será ainda e não têm necessidade luz lâmpada e luz sol que Kyrios o Theos iluminará sobre eles e reinarão para o eras o eras');
INSERT INTO verses VALUES (31141, 66, 22, 6, 'e disse a-mim estas o palavras fiéis e verdadeiros e o Kyrios o Theos o espíritos o profetas enviou o anjo dele mostrar o servos dele o qual é necessário tornar-se em brevemente');
INSERT INTO verses VALUES (31142, 66, 22, 7, 'e Eis venho rapidamente bem-aventurado o guardando o palavras o profecia o livro disto');
INSERT INTO verses VALUES (31143, 66, 22, 8, 'eu-também João o ouvindo e vendo estas-coisas e quando ouvi e vi-ou caí adorar diante o pés o anjo o mostrando-os a-mim estas-coisas');
INSERT INTO verses VALUES (31144, 66, 22, 9, 'e diz a-mim veja não conservo teu sou e o irmãos teu o profetas e o guardando o palavras o livro disto o a-Theos adora');
INSERT INTO verses VALUES (31145, 66, 22, 10, 'e diz a-mim não selarás o palavras o profecia o livro disto o tempo pois perto é');
INSERT INTO verses VALUES (31146, 66, 22, 11, 'o injusto faça-injúria ainda e o sujo torne-se-sujo ainda e o justo justiça faça-o ainda e o santo seja-santificado ainda');
INSERT INTO verses VALUES (31147, 66, 22, 12, 'Eis venho rapidamente e o salário meu com meu dar-lhe a-cada-um como o obra é dele');
INSERT INTO verses VALUES (31148, 66, 22, 13, 'eu o Alfa e o Ômega o primeiro e o último o princípio e o fim');
INSERT INTO verses VALUES (31149, 66, 22, 14, 'bem-aventurados o lavando-os o vestes deles para que será o autoridade deles sobre o madeira/árvore o da-vida e o fechem-lhes entrem-eles para o cidade');
INSERT INTO verses VALUES (31150, 66, 22, 15, 'fora o cães e o feiticeiros e o meretrizes e o assassinos e o adoradoras-de-idolos e todo amando e fazendo mentira');
INSERT INTO verses VALUES (31151, 66, 22, 16, 'eu Iesous enviei o anjo meu para-martirizar-se a-vós estas-coisas sobre o assembleias eu sou o raiz e o gênero Davi o estrela o brilhante o matinal');
INSERT INTO verses VALUES (31152, 66, 22, 17, 'e o espírito e o noiva dizem Vem e o ouvindo que-fale Vem e o sedente venha o querendo tome água da-vida de-graça');
INSERT INTO verses VALUES (31153, 66, 22, 18, 'testifico eu todo o ouvinte o palavras o profecia o livro disto se alguém ponha sobre elas põe o Theos sobre ele o pragas o escritas em o livro nisto');
INSERT INTO verses VALUES (31154, 66, 22, 19, 'e se alguém remova de o palavras o livro o profecia desta retirará o Theos o parte dele de o árvore o da-vida e de o cidade o santas o escritas em o livro nisto');
INSERT INTO verses VALUES (31155, 66, 22, 20, 'diz o testemunhando estas-coisas sim venho rapidamente Amém vem Kyrie Iesous');
INSERT INTO verses VALUES (31156, 66, 22, 21, 'o graça o do-Kyrios Iesous com todos');
